create or replace function AanmakenArtikelLocatie(in @LocGid integer, in @ArtGid integer)
  returns integer
begin
  declare @ArtLocGid integer;
  //call TraceBegin('AanmakenArtikelLocatie');
  lock mutex MutArtikelLocatie; // Be SURE that only one record will exist any time
  if not exists(select 1 from tabArtikelLocatie where ArtLocArtGid = @ArtGid and ArtLocLocGid=@LocGid)  then
    insert into tabArtikelLocatie (ArtLocArtGid, ArtLocLocGid)
                           values (@ArtGid,      @LocGid);
  end if;

  select  ArtLocGid into @ArtLocGid from tabArtikelLocatie where ArtLocArtGid = @ArtGid and ArtLocLocGid=@LocGid;

  // Een transactie-mutex mag niet worden gereleased
  //release mutex MutArtikelLocatie;

  return @ArtLocGid;

  //call TraceEind('AanmakenArtikelLocatie');
end;


create or replace procedure AanmakenProjectMutatiesObvWerkbon(in @PwbkGid integer, in @PbrMutatieDatum DateTime, out @AangemaaktPbkGid integer)
begin
  //gegenereerde waarden
  declare @NieuwVolgnummer numeric(10,0);
  declare @NieuwPbkGid     integer;
  declare @NieuwPbrGid     integer;
  //tabProjectWerkbonKop variabelen
  declare @PwbkProjGid     integer;
  declare @PwbkOms         nchar(40);
  declare @PwbkStatus      smallint;
  //tabProjectVastegegevens variabelen
  declare @ProjVastBijVerwerkenWerkbon smallint;
  //overige variabelen
  declare @tmpPbrStatus    smallint;

  set @@ErrorTextProcedure = 'AanmakenProjectMutatiesObvWerkbon > ';
  //call TraceBegin(@@ErrorTextProcedure + '@PwbkGid = ' + string(@PwbkGid));

  set @NieuwPbkGid = null;

  select PwbkProjGid, PwbkOms, PwbkStatus into @PwbkProjGid, @PwbkOms, @PwbkStatus from tabProjectWerkbonKop where PwbkGid = @PwbkGid;
  select ProjVastBijVerwerkenWerkbon into @ProjVastBijVerwerkenWerkbon from tabProjectVasteGegevens;

  //geen vaste gegevens gevonden, dan maken we de regels met status concept aan
  set @ProjVastBijVerwerkenWerkbon = IsNull(@ProjVastBijVerwerkenWerkbon, 0);

  //@ProjVastBijVerwerkenWerkbon --> vervolgactie na afhandelen werkbon --> 0 = geen vervolgacties | 1 = venster invoeren projectmutaties openen | 2 = venster accepteren projectmutaties openen
  //De regelstatus wordt alleen 'ingeleverd' als we vervolgactie 2 ingesteld hebben. In alle andere gevallen wordt de regelstatus concept.
  set @tmpPbrStatus = if @ProjVastBijVerwerkenWerkbon = 2 then 1 else 0 endif;


  //alleen werkbonnen met de status afgehandeld mogen worden overgeheveld naar een projectmutatiebestand.
  if IsNull(@PwbkStatus,-1) <> 3 then
    set @@ErrorTextProcedure = 'AanmakenProjectMutatiesObvWerkbon > 20304: De werkbon moet status ''Afgehandeld'' hebben om een projectmutatiebestand aan te kunnen maken!';
    raiserror 20304;
  end if;

  //MR 22-apr-2008 bug #28266: Als de datum leeg is, vul hem dan met de verwerkingsdatum.
  set @PbrMutatieDatum  = IsNull(@PbrMutatieDatum, @@Verwerkingsdatum);

  for @Cursor AS CURSOR_ProjectMutatiesAanmaken CURSOR FOR
    select
      PwbrGid                          @CursPwbrGid,
      PwbrPbGid                        @CursPwbrPbGid,
      PwbrArtGid                       @CursPwbrArtGid,
      PwbrArtPartijGid                 @CursPwbrArtPartijGid,
      PwbrMagGid                       @CursPwbrMagGid,
      PwbrLocGid                       @CursPwbrLocGid,
      PwbrRelGid                       @CursPwbrRelGid,
      PwbrNawGidLeverancier            @CursPwbrNawGidLeverancier,
      PwbrMutSoort                     @CursPwbrMutSoort,
      PwbrOms                          @CursPwbrOms,
      PwbrIsDirecteInkoop              @CursPwbrIsDirecteInkoop,
      PwbrAantalGeboekt                @CursPwbrAantalGeboekt,
      PwbrAantalDeclarabel             @CursPwbrAantalDeclarabel,
      PwbrDoorbelastPercentage         @CursPwbrDoorbelastPercentage,
      PwbrKostprijs                    @CursPwbrKostprijs,
      PwbrKostprijsRegelTotaal         @CursPwbrKostprijsRegelTotaal,
      PwbrVerkoopprijs                 @CursPwbrVerkoopprijs,
      PwbrVerkoopprijsRegelTotaal      @CursPwbrVerkoopprijsRegelTotaal,
      PwbrPartFactEenheidFactor        @CursPwbrPartFactEenheidFactor,
      PwbrPrijsPer                     @CursPwbrPrijsPer,
      PwbrSelectieCodes                @CursPwbrSelectieCodes,
      PwbrUrenIngevoerdAls             @CursPwbrUrenIngevoerdAls,
      PwbrAantalGeboektBeginTijd       @CursPwbrAantalGeboektBeginTijd
    from
      tabProjectWerkbonRegel
    where
          PwbrPwbkGid = @PwbkGid
      and PwbrMutSoort in (0,1,2) //tekstregels (=3) hebben we niet in proj.mut.
    order by
      PwbrRegelnr, PwbrMutSoort, PwbrGid
  for read only
  do
    //TG 13-11-2007: tijdens de eerste loop is dit veld null en wordt de projectmutatiekop aangemaakt.
    //Dit gebeurt alleen als er werkbonregels zijn (derhalve binnen de cursor opgelost)
    if @NieuwPbkGid is null then

      //nieuw volgnummer projectmutatiebestand bepalen; 4 = via werkbon
      call VolgnummerProjectMutGenereren(1, 4, @NieuwVolgnummer);

      //koprecord aanmaken
      insert into tabProjectBoekingsKop
      (PbkVolgnummer, PbkHerkomst, PbkOms)
      values (@NieuwVolgnummer, 4, @PwbkOms);

      //koprecord gidje opslaan
      set @NieuwPbkGid = @@Identity;
    end if;

    //variabele resetten na elke loop
    set @NieuwPbrGid = null;

    //werkbonregel uit cursor overnemen naar projectmutatiebestand; regelnummer wordt automatisch gevuld in de boekingsregeltrigger
    //TG 12-11-2008: Ivm bug #29550 voegen we de regels hier toe met PbrStatus "concept" (0). De status wordt pas aangepast naar "ingeleverd" (indien nodig) als de serienummers aangemaakt zijn.
    insert into tabProjectBoekingsRegel(
    PbrPbkGid,        PbrProjGid,                 PbrPbGid,                 PbrArtGid,    PbrArtPartijGid,         PbrMagGid,
    PbrLocGid,        PbrRelGid,                  PbrLeverancierNawGid,     PbrMutSoort,  PbrOmschr,               PbrIsDirecteInkoop,
    PbrAantalGeboekt, PbrAantalDeclarabel,        PbrDoorbelastPercentage,  PbrKostprijs, PbrKostprijsRegelTotaal,
    PbrVerkoopprijs,  PbrVerkoopprijsRegelTotaal, PbrPartFactEenheidFactor, PbrPrijsPer,  PbrSelectieCodes,
    PbrStatus,        PbrMutatieDatum,            PbrUrenIngevoerdAls,      PbrAantalGeboektBeginTijd)
    values(
    @NieuwPbkGid,           @PwbkProjGid,                     @CursPwbrPbGid,                 @CursPwbrArtGid,    @CursPwbrArtPartijGid,         @CursPwbrMagGid,
    @CursPwbrLocGid,        @CursPwbrRelGid,                  @CursPwbrNawGidLeverancier,     @CursPwbrMutSoort,  @CursPwbrOms,                  @CursPwbrIsDirecteInkoop,
    @CursPwbrAantalGeboekt, @CursPwbrAantalDeclarabel,        @CursPwbrDoorbelastPercentage,  @CursPwbrKostprijs, @CursPwbrKostprijsRegelTotaal,
    @CursPwbrVerkoopprijs,  @CursPwbrVerkoopprijsRegelTotaal, @CursPwbrPartFactEenheidFactor, @CursPwbrPrijsPer,  @CursPwbrSelectieCodes,
    0                    ,  @PbrMutatieDatum,                 @CursPwbrUrenIngevoerdAls,      @CursPwbrAantalGeboektBeginTijd);

    set @NieuwPbrGid = @@Identity;
    //Als er serienummers zijn toegevoegd aan een regel dan ook die kopieren naar de projectmutatie
    insert into tabProjectBoekingsRegelDetail (PbrdPbrGid, PbrdArtSerieGid,  PbrdAantal)
    select @NieuwPbrGid, PwbdArtSerieGid, PwbdAantal
    from   tabProjectWerkbonRegelDetail
    where  PwbdPwbrGid = @CursPwbrGid;

    //TG 12-11-2008: bug #29550: Als de status op "ingeleverd" moet worden gezet obv de instelling in vaste gegevens, dan de status nu wijzigen.
    //Dit mag namelijk pas als de serienummers zijn ingevoerd. Bij de status "ingeleverd" wordt namelijk een controle uitgevoerd of het aantal geboekt
    //overeenkomt met het aantal serienummers. Echter, bij het toevoegen van de regel zijn er nog geen serienummers dus die controle levert altijd raiseError 20253 op!
    if @tmpPbrStatus <> 0 then
      update tabProjectBoekingsRegel
      set    PbrStatus = @tmpPbrStatus
      where  PbrGid    = @NieuwPbrGid;
    end if;

    //TG 28-11-2007: update de detailregels zodat de aantallen van de serienummers bijgewerkt worden
    update tabProjectWerkbonRegelDetail set PwbdGid = PwbdGid where PwbdPwbrGid = @CursPwbrGid;
  end for;


  set @AangemaaktPbkGid = @NieuwPbkGid;

  set @@ErrorTextProcedure = 'AanmakenProjectMutatiesObvWerkbon';
  //call TraceEind(@@ErrorTextProcedure + ' > @AangemaaktPbkGid = ' + string(@AangemaaktPbkGid));
end;

// ---------------------------------------------------------------------------------------
// ------------------------- Aanmaken order tbv project facturering ----------------------
// ---------------------------------------------------------------------------------------
create or replace procedure AanmakenProjectOrders(
  in  @ConnId             integer,
  in  @LoginTime          nchar(50),
  in  @SelecteerOp        smallint,
  in  @VanNaw             nchar(10),
  in  @TotNaw             nchar(10),
  in  @VanProject         nchar(10),
  in  @TotProject         nchar(10),
  in  @VanProjectLeider   nchar(10),
  in  @TotProjectLeider   nchar(10),
  out @OrkNummerVan       numeric(10,0),
  out @OrkNummerTot       numeric(10,0),
  out @FbGid              integer
  )
begin
  declare @OrkGid                      integer;
  declare @OrkNummer                   integer;
  declare @ProjGid                     integer;
  declare @PfvkGid                     integer;
  declare @PfvkStatus                  smallint;
  declare @ProjRelGid                  integer;
  declare @ProjTariefGid               integer;
  declare @pfvrGid                     integer;
  declare @pfvrPbGid                   integer;
  declare @pfvrBtwCode                 integer;
  declare @pfvrPmwGid                  integer;
  declare @pfvrArtGid                  integer;
  declare @pfvrOpbrGrpGid              integer;
  declare @pfvrMutSoort                integer;
  declare @pfvrAantal                  numeric(20,8);
  declare @pfvrVerkoopprijsExclBTW     numeric(15,3);
  declare @pfvrPrijsPer                numeric(15,3);
  declare @pfvrIsAantalEnPrijzenGeldig smallint;
  declare @pfvrVerkoopwaarde           numeric(15,3);
  declare @pfvrTekstOpFactuur          long nvarchar;
  declare @pfvrOms                     nchar(80);
  declare @OrkInclBtw                  smallint;
  declare @OrkValuta                   integer;
  declare @BjGid                       integer;
  declare @PerNr                       integer;
  declare @BtwPerc                     numeric(15,3);
  declare @PbSoort                     smallint;
  declare @tmp                         integer;
  declare @ArtOpbrGrpGid               integer;
  declare @ArtAantDecAantallen         smallint;
  declare @ArtAantDecPrijzen           smallint;
  declare @TijdVakAanduiding           smallint;
  declare @AantDecValuta               smallint;
  declare @TijdvakBegin                date;
  declare @TijdvakEind                 date;
  declare @NietVerwerken               smallint;
  declare @RegelAantalUur              numeric(20,8);

  declare cursor_ProjFactVoorstelKop no scroll cursor for
    select ProjGid, pfvkGid, IsNull(pfvkStatus, 0), ProjDebContactPersRelGid from tabProjectFactuurVoorstelKop
    inner join tabNawFile on PfvkNawGid = NawFilNawGid and ((@SelecteerOp = 1 and NawFilNummer between @VanNaw and @TotNaw) or (@SelecteerOp = 2 and NawFilZoekCode between @VanNaw and @TotNaw))
    inner join tabProject on pfvkProjGid = ProjGid and ProjCode between @VanProject and @TotProject
    inner join tabProjectMedewerker on PmwRelGid = ProjProjLeiderRelGid and PmwZoekcode between @VanProjectLeider and @TotProjectLeider
    where IsNull(PfvkStatus,0) in (1,3)  // Vrijgegeven voor facturering OF te crediteren
    order by ProjCode, PfvkStatus, PmwZoekcode asc
  for read only;

  declare cursor_ProjFactVoorstelRegels no scroll cursor for
    select pfvrGid, pfvrPbGid, pfvrBtwCode, pfvrPmwGid, pfvrArtGid, ProjectTarief.ArtOpbrGrpGid, ProjectTarief.ArtAantDecAantallen, ProjectTarief.ArtAantDecPrijzen, pfvrOpbrGrpGid, pfvrMutSoort, pfvrAantal,
         pfvrVerkoopprijsExclBTW, pfvrPrijsPer, pfvrIsAantalEnPrijzenGeldig, pfvrVerkoopwaarde, pfvrTekstOpFactuur, pfvrOms,
         case pfvrMutSoort // Hier direct het juiste tarief voor de orderregel teruggeven
             when 0  then (select ProjVastArtGidActiviteit from tabProjectVasteGegevens)
             when 1  then (select ProjVastArtGidMachine    from tabProjectVasteGegevens)
             when 2  then (select ProjVastArtGidArtikel    from tabProjectVasteGegevens)
             when 99 then (select ProjVastArtGidTermijn    from tabProjectVasteGegevens)
           end ProjTarGid, BtwPercentage, PbSoort
    from   tabProjectFactuurVoorstelRegel
    inner join tabProjectBoom on pfvrPbGid = PbGid
    left outer join tabArtikel ProjectTarief on ProjTarGid = ProjectTarief.ArtGid
    left outer join tabBtw on pfvrBtwCode = BtwCode
    LEFT OUTER JOIN (tabProjectFactuurVoorstelRealisatie inner join tabProjectTermijn ON ptmGid = pfvlPtmGid)ON  pfvlFvrGid = pfvrgid
		where  pfvrPfvkGid = @pfvkGid
  order by pbZoekCode, pfvrMutSoort, PtmTermijnNr, pfvrOms, pfvrBtwCode asc
  for read only;

  set @@ErrorTextProcedure = 'AanmakenProjectOrders -> @ConnId='+string(@ConnId)+', @LoginTime='+string(@LoginTime)+', @VanProject='+string(@VanProject)+', @TotProject='+@TotProject+', @VanProjectLeider='+@VanProjectLeider+', @TotProjectLeider='+@TotProjectLeider;

  //call TraceBegin(@@ErrorTextProcedure);

  // Om er zeker van te zijn dat de aangemaakte projectorders een opeenvolgende nummering hebben, zodat de reeks gemakkelijk geselecteerd kan worden,
  // wordt er hier eventueel gewacht op een andere gebruiker die projectorders aanmaakt. Zelfde principe als uitdelen factuurnummers.
  LockLoop:
  loop
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'AanmakenProjectOrders', '', @tmp);
    if @tmp = 0 then
      leave LockLoop;
    end if;
    waitfor delay '0:00:00:500'; // 500 miliseconden wachten (1/2 seconde dus!)
  end loop LockLoop;

  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid, @PerNr);

  //Factuurbatch aanmaken
  insert into tabFactuurBatch (fbAangemaaktDoor, fbAangemaaktOp, fbSoortBatch, fbAcceptGiroAfgedrukt, fbPakbonAfgedrukt)
  values(@@GebruikerCode, now(), 65, (select DocOrdAfdrukkenFactuurAcceptgiro from tabDocument where DocSoort = 65), 0);
  set @FbGid = @@Identity;
  call LockSetOnId(@ConnId, @LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid), 0);

  set @OrkNummerVan = null;

  open cursor_ProjFactVoorstelKop;
  LoopProjFactVoorstelKop:
  Loop
    fetch next cursor_ProjFactVoorstelKop into @ProjGid, @PfvkGid, @PfvkStatus, @ProjRelGid;
    if sqlstate = '02000' then
      leave LoopProjFactVoorstelKop;
    end if;

    case @PfvkStatus
      when 0 then call Raise(20265); // (20265) Factuurvoorstel is nog niet vrijgegeven!
      when 2 then call Raise(20266); // (20266) Factuurvoorstel is al gefactureerd!
    end case;

    call OrdersGenereerNieuwOrderNummer(1, 1, @OrkNummer);

    if @OrkNummerVan is null then
      set @OrkNummerVan = @OrkNummer
    end if;
    set @OrkNummerTot  = @OrkNummer;
    set @NietVerwerken = 0;

    insert into tabOrderKop (OrkSoort, OrkPfvkGid, OrkNummer, OrkInclBtw, OrkDatum, OrkNawGid, OrkValNummer, OrkBtcNummer, OrkLvcNummer, OrkVtgCode, OrkReferentie, OrkFactuurAdres, OrkVerzendAdres, OrkApartFaktureren, OrkGoedgekeurd, OrkVrijVoorFaktureren, OrkIsInkoopCombinatie, orkFactuurnawGid, orkNawGidOmzet, orkNawGidPrijzen, OrkAdrGid)
  select 1, @PfvkGid, @OrkNummer, 0, Now(), pfvkNawGid, NawFilValNummer, isNull(pfvkBtcNummer, isNull(ProjBtcNummer,NawFilBtcNummer)),  isNull(pfvkLvcNummer, ProjLvcNummer), NawVertegenwCode, ProjOmschr, NawFactuurAdres, (if NawVerzendAdres in (2,5) and nawGidVerzendAdres is null then 1 else NawVerzendAdres endif), 1, 1, 1, PfvkIsInkoopCombinatie, PfvknawGidFactuur, PfvkNawGidOmzet, PfvkNawGidPrijzen, (if NawVerzendAdres in (2,5) then nawGidVerzendAdres else null endif)
    from  tabProjectFactuurVoorstelKop
    inner join tabProject on ProjGid = pfvkProjGid
    inner join tabNaw on pfvkNawGid = NawGid
    inner join tabNawFile on NawFilNawGid = NawGid
    where pfvkGid = @pfvkGid;

    // Gidje van aangemaakte projectorder ophalen
    set @OrkGid = @@Identity;

    if @ProjRelGid is not null then
      insert into tabOrderRelatieVoorDocument (OrdRelDocSoort, OrdRelRelGid, OrdRelOrkGid) values ( 65, @ProjRelGid, @OrkGid);
    end if;

    call LockSetOnId(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid, @tmp);
    if @tmp <> 0 then
      call Raise(20268); //(20268) Projectorder niet kunnen locken!
    end if;

    // Op deze plek het projectfactuurvoorstel proberen te locken
    // lukt dit niet dan is de order toch nodig voor referentie naar het project op het overzicht
    call LockSetOnId(@ConnId, @LoginTime, 1, 'tabProjectFactuurVoorstelKop', @PfvkGid, @tmp);
    if @tmp <> 0 then
      if not exists( select 1 from tabFactuurNietGefactureerd where fngFbGid = @fbGid and fngOrkGid = @OrkGid) then
        insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
        values( @fbGid, @OrkGid, 24, 0); // 24 Factuurvoorstel is in gebruik
        set @NietVerwerken = 1;
      end if;
    end if;

    if @PfvkStatus = 3 and exists(select 1 from tabProjectFactuurVoorstelKop where PfvkProjGid = @ProjGid and PfvkStatus = 0) then
      if not exists( select 1 from tabFactuurNietGefactureerd where fngFbGid = @fbGid and fngOrkGid = @OrkGid) then
        insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
        values( @fbGid, @OrkGid, 25, 1); // 25 Er is al een concept factuurvoorstel voor dit project
        set @NietVerwerken = 1;
      end if;
    end if;

    if @PfvkStatus = 3 and exists( select 1 from tabOrderKop
                                    inner join tabProjectFactuurVoorstelKop on OrkPfvkGid = PfvkGid
                                    where OrkSoort = 1
                                    and   PfvkGid <> @PfvkGid
                                    and   PfvkProjGid = @ProjGid
                                    and   PfvkStatus = 3
                                    and   LockedById(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid) = 1)
    then
      if not exists( select 1 from tabFactuurNietGefactureerd where fngFbGid = @fbGid and fngOrkGid = @OrkGid) then
        insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
        values( @fbGid, @OrkGid, 26, 1); // 26 Er wordt al een factuurvoorstel voor dit project gecrediteerd
        set @NietVerwerken = 1;
      end if;
    end if;

    select OrkInclBtw, OrkValNummer into @OrkInclBtw, @OrkValuta from taborderkop where orkgid = @OrkGid;

    if @NietVerwerken = 0 then  // Bug 29836 - geen regels aanmaken, zijn toch niet nodig voor het overzicht van niet gefactureerde voorstellen
      open cursor_ProjFactVoorstelRegels;
      LoopProjFactVoorstelRegels:
      Loop
        fetch next cursor_ProjFactVoorstelRegels into
            @pfvrGid, @pfvrPbGid, @pfvrBtwCode, @pfvrPmwGid, @pfvrArtGid, @ArtOpbrGrpGid, @ArtAantDecAantallen, @ArtAantDecPrijzen, @pfvrOpbrGrpGid, @pfvrMutSoort,  @pfvrAantal,
            @pfvrVerkoopprijsExclBTW, @pfvrPrijsPer, @pfvrIsAantalEnPrijzenGeldig, @pfvrVerkoopwaarde, @pfvrTekstOpFactuur, @pfvrOms,
            @ProjTariefGid, @BtwPerc, @PbSoort;
        if sqlstate = '02000' then
          leave LoopProjFactVoorstelRegels;
        end if;

        //  RS 03/07/08 - dit weggecomment nav bug 28763
  /*      if @ProjSoort = 0 then  // Regie Project -> Herbepalen Verkoopprijs, PrijsPer en Aantal in factuurvoorstelregel
          call ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck(@PfvrGid);

          // evt door bovenstaande routine aangepaste waardes opnieuw ophalen
          select pfvrAantal,  pfvrVerkoopprijsExclBTW,  pfvrVerkoopWaarde,  pfvrPrijsPer, pfvrIsAantalEnPrijzenGeldig into
                 @pfvrAantal, @pfvrVerkoopprijsExclBTW, @pfvrVerkoopWaarde, @pfvrPrijsPer, @pfvrIsAantalEnPrijzenGeldig
          from tabProjectFactuurVoorstelRegel where PfvrGid = @PfvrGid;
        end if;
  */

        // Projecten : Tijdvak invullen volgens instelling
        set @TijdvakBegin = null;
        set @TijdvakEind  = null;
        set @TijdVakAanduiding = (select isnull(ProjVastDefaultFactTijdvakAanduiding, 0) from tabProjectVastegegevens);
        if (@TijdvakAanduiding <> 0) then
          select
            if @TijdVakAanduiding = 1 then (select BeginDatum from tabPeriode where Min(PbrMutatieDatum) between BeginDatum and EindDatum ) else Min(PbrMutatieDatum) endif,
            if @TijdVakAanduiding = 1 then (select EindDatum  from tabPeriode where Max(PbrMutatieDatum) between BeginDatum and EindDatum ) else Max(PbrMutatieDatum) endif
            into @TijdvakBegin, @TijdvakEind
          from
            tabProjectFactuurVoorstelKop
            inner join tabProjectFactuurVoorstelRegel on PfvrPfvkGid = PfvkGid
            inner join tabProjectFactuurvoorstelRealisatie on pfvlFvrGid = PfvrGid
            inner join tabProjectBoekingsRegel on pfvlPbrGid = PbrGid
          where PfvrGid =  @pfvrGid;
        end if;

        if @PfvrMutSoort = 0 then
          select sum(pfvlAantal) into @RegelAantalUur from tabProjectFactuurVoorstelRealisatie where pfvlFvrGid = @pfvrGid
        else
          set @RegelAantalUur = null;
        end if;

        set @AantDecValuta = (select DecimalenRegel*2 from tabvaluta where ValNummer=@OrkValuta);

        if (@pfvrIsAantalEnPrijzenGeldig = 1) then

          insert into tabOrderRegel (OrrOrkGid, OrrPfvrGid, OrrArtGid, OrrIsAantallen, OrrAantDecBedrag, OrrAantDecAantal,OrrAantDecAantalVrrdEenh,
                                    OrrOpbrGrpGId, OrrRegelSoort, OrrBtwCode, OrrTekstOpFactuur,
                                    OrrAantalBesteld, OrrAantalBesteldVrrdEenh,
                                    OrrAantalDezeFacturering, OrrAantalDezeFactureringVrrdEenh,
                                    OrrPrijsPer,
                                    OrrBrutoVerkoopPrijs,
                                    OrrTijdvakBegin, OrrTijdvakEind, OrrPbSoort, OrrPrjAantalUur)
                                    values
                                   (@OrkGid, @pfvrGid, @ProjTariefGid, 1, @ArtAantDecPrijzen, @ArtAantDecAantallen, @ArtAantDecAantallen,
                                   @ArtOpbrGrpGid, 1, @pfvrBtwCode, IsNull(@pfvrTekstOpFactuur,@pfvrOms),
                                   (if @PfvkStatus = 3 then -@pfvrAantal else @pfvrAantal endif),(if @PfvkStatus = 3 then -@pfvrAantal else @pfvrAantal endif),
                                   (if @PfvkStatus = 3 then -@pfvrAantal else @pfvrAantal endif),(if @PfvkStatus = 3 then -@pfvrAantal else @pfvrAantal endif),
                                   @pfvrPrijsPer,
                                   (if @OrkInclBtw = 1 then (ValutaOmrekenen(@@BasisValutaNummer, @pfvrVerkoopprijsExclBTW, @OrkValuta, @BjGid, @PerNr, @ArtAantDecPrijzen) * (100+@BtwPerc)) / 100 else ValutaOmrekenen(@@BasisValutaNummer, @pfvrVerkoopprijsExclBTW, @OrkValuta, @BjGid, @PerNr, @ArtAantDecPrijzen) endif),
                                   @TijdvakBegin, @TijdvakEind, @PbSoort, @RegelAantalUur);

        else
          insert into tabOrderRegel (OrrOrkGid, OrrPfvrGid, OrrArtGid, OrrIsAantallen, OrrAantDecBedrag, OrrOpbrGrpGId,
                                     OrrRegelSoort, OrrBtwCode,  OrrTekstOpFactuur,
                                     OrrAantalBesteld, OrrAantalBesteldVrrdEenh,
                                     OrrAantalDezeFacturering, OrrAantalDezeFactureringVrrdEenh,
                                     OrrBrutoVerkoopPrijs,
                                     OrrTijdvakBegin, OrrTijdvakEind, OrrPbSoort, OrrPrjAantalUur)
                                     values
                                    (@OrkGid, @pfvrGid, @ProjTariefGid, (if @PfvkStatus = 3 then 1 else 0 endif),
                                    @AantDecValuta, @ArtOpbrGrpGid,
                                    (if @pfvrMutSoort = -1 then 0 else 1 endif), @pfvrBtwCode, IsNull(@pfvrTekstOpFactuur,@pfvrOms),
                                    (if @PfvkStatus = 3 then -1 else 1 endif), (if @PfvkStatus = 3 then -1 else 1 endif),
                                    (if @PfvkStatus = 3 then -1 else 1 endif), (if @PfvkStatus = 3 then -1 else 1 endif),
                                    (if @OrkInclBtw = 1 then (ValutaOmrekenen(@@BasisValutaNummer, @pfvrVerkoopWaarde, @OrkValuta, @BjGid, @PerNr, @AantDecValuta) * (100+@BtwPerc)) / 100 else ValutaOmrekenen(@@BasisValutaNummer, @pfvrVerkoopWaarde, @OrkValuta, @BjGid, @PerNr, @AantDecValuta) endif),
                                    @TijdvakBegin, @TijdvakEind, @PbSoort, @RegelAantalUur);
        end if;

      End loop LoopProjFactVoorstelRegels;
      close cursor_ProjFactVoorstelRegels;
    end if;
  End loop LoopProjFactVoorstelKop;
  close cursor_ProjFactVoorstelKop;

  //Aanmaken Project Orders lock weer vrijgeven
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'AanmakenProjectOrders', '');

  set @@ErrorTextProcedure = 'AanmakenProjectOrders -> @ConnId='+string(@ConnId)+', @LoginTime='+string(@LoginTime)+', @VanProject='+string(@VanProject)+', @TotProject='+@TotProject+', @VanProjectLeider='+@VanProjectLeider+', @TotProjectLeider='+@TotProjectLeider+', @OrkNummerVan='+string(@OrkNummerVan)+', @OrkNummerTot='+string(@OrkNummerTot)+', @FbGid='+string(@FbGid);

  //call TraceEind(@@ErrorTextProcedure);

end;
/*==[
# Plan 37: Copy file, one submenu

## 1. trial

The folder pane's right-click menu has three loose items: Copy file name, Copy path, Copy relative path. They
are to make way for one item, **Copy name to Windows clipboard**, with a submenu of six ways to copy a file's name. The same submenu
also goes on the File menu, where it acts on the active document, and the tab menu of a document.


### 1.1 The six items
The menu of a folder changes the 'file' into 'folder'; 'Filename' becomes 'Foldername', the 'Path' copies the path without the ending folder name , etc.

| Item                           | Copies for files                               | Copies for folders | Example (root `D:\Work`, file `D:\Work\docs\a.md`) |
| ------------------------------ | ---------------------------------------------- | --- | -------------------------------------------------- |
| Filename                       | the name without its extension                 | The name without its extension | `a`                                                |
| Filename.ext                   | the name with its extension                    | The name with its extension    | `a.md`                                             |
| `---`                          |                                                |     |                                                    |
| Path                           | the folder, without the file                   | the folder, without the ending folder name | `D:\Work\docs`                                     |
| Path and filename.ext          | the full name                                  | the full name    | `D:\Work\docs\a.md`                                |
| `---`                          |                                                |     |                                                    |
| Relative path                  | the folder, relative to the folder pane's root | the folder without the ending folder name, relative to the folder pane's root    | `docs`                                             |
| Relative path and filename.ext | the full name, relative to the root            | the full name, relative to the root    | `docs\a.md`                                        |

### 2 also a test

- `file.copy` in actions.js, with parameter `part`: `name`, `nameExt`, `dir`, `full`, `relDir`, `relFull`.
- The parameters are what the menus pass. A key in keys.json can be put on each part, and a macro records them like
  any other action.
- No path given: the active document's path. A draft that has never been saved has no path: the Name menu
  item is greyed out, and a key does nothing.
- A file on the root adds a '\' for the path: 'D:\a.md' copies path 'D:\'.
- A file on a network drive gives the network url: '\\server.local\a.md' copies '\\server.local\'; '\\server.local\path\a.md' copies '\\server.local\path'.
- A relative path in the root gives no path: 'D:\root\a.md' with root 'D:\root' gives '' as path, and 'a.md' as file.

]==*/

// ---------- Aanmaken acceptgirotabel tbv. aanmaningen ----------
create or replace procedure AanmaningCreateAcceptGiroBatch(in @AanmAfdrId integer, in @IsRekeningOverzicht integer, in @IsInstellenLayout integer, in @SorterenOp smallint, in @SorteerVolgorde smallint, out @AcbGid integer)
begin
  declare @vgaFormcode                 nchar(2);
  declare @vgaDiversen                 nchar(5);
  declare @vgaEigenrek                 nchar(34);
  declare @vgaBIC											 nchar(11);
  declare @vgaBedragOpAanmaning        integer;

  set @@ErrorTextProcedure = 'AanmaningCreateAcceptGiroBatch > @AanmAfdrId='+string(@AanmAfdrId);
  //call TraceBegin(@@ErrorTextProcedure);

  insert into tabAcceptGiroBatch (AcbAangemaaktDoor, AcbAangemaaktOp, AcbGid, AcbOms,     AcbSoort)
  Values                         (@@GebruikerCode,   Now(),           Null,   _A('Aanmaning'), 0);

  set @AcbGid = @@Identity;

  //Locken van de acc.batch
  call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabAcceptGiroBatch', 'AcbGid='+string(@AcbGid), 0);

  // Vaste gegevens acceptgiro uitlezen
  select first vgaFormcode, vgaDiversen, vgaEigenrek, vgaBIC, vgaBedragOpAanmaning
  into   @vgaFormcode, @vgaDiversen, @vgaEigenrek, @vgaBIC, @vgaBedragOpAanmaning
  from   tabVasteGegevensAcceptGiro;

  // Nu alle acceptgiros van de facturen overnemen waarvan een acceptgiro moet worden afgedrukt
  //call Trace('Batch vullen');
  insert into tabAcceptGiro(
         AccAcbGid, accRegelNummer, AccDebNummer,
         accFactuurDatum, accVervalDatum,
         accReferentie,
         accValNummer, AccValCode, accBedrag,

         AccCorrAdresNaam1,    AccCorrAdresNaam2,
         AccCorrAdresStraat,   AccCorrAdresHuisnummer,
         AccCorrAdresPostcode, AccCorrAdresPlaats,
         AccCorrAdresLndEigenCode, AccCorrAdresLndOms, AccCorrAdresLndPlaatsHuisnr,
         AccCorrAdresLndPlaatsPostcode, AccCorrAdresLndInNAWBlok,

         AccVestAdresNaam1, AccVestAdresNaam2,
         AccVestAdresStraat, AccVestAdresHuisnummer,
         AccVestAdresPostcode, AccVestAdresPlaats,
         AccVestAdresLndEigenCode, AccVestAdresLndOms, AccVestAdresLndPlaatsHuisnr,
         AccVestAdresLndPlaatsPostcode, AccVestAdresLndInNAWBlok,

         AccGebruikCorrespondentieAdres,

         AccBankRekBankRekening, AccBankRekNaamRekHouder,
         AccBankRekAdresRekHouder, accBankRekPostcodeRekHouder, AccBankRekPlaatsRekHouder,
         AccPrintBedragAcceptgiro,

         AccRapNummer,
         AccFormCode,
         AccDiversen,
         AccEigenRekening,
         accBIC,
         AccbetalingsKenmerk,
         AccTaalCode)
  select @AcbGid, number(), AanmAfdrRksNummer,
         min(AanmAfdrAanmDatum), min(AanmAfdrAanmDatum) /*vervaldatum='per omgaande', dus de oudste acceptgirodatum*/,
         '' /*Dit is de referentie/omschrijving van de acceptgiro/aanmaning: leeg dus!*/,
         AanmAfdrValNummer, AanmAfdrValCode,
         // Bedrag op acceptgiro
         sum(isnull((if @vgaBedragOpAanmaning = 0 then // Vervallen bedrag + kosten
                       AanmAfdrVervallenBedrag
                     else                              // Openstaand bedrag
                       AanmAfdrOpenstaandBedrag
                     endif),0)) +
         isnull(
           if @vgaBedragOpAanmaning = 0 then // Openstaand bedrag
             (select AdmKostBedrag from tabAdministratieKosten where AdmKostValNummer = AanmAfdrValNummer and AdmKostAanmNummer = (if (NawAanmaningsType = 2) or (@IsRekeningOverzicht = 1)  then 0 else (AanmAfdrHoogstNrPerDebPerValuta + 1) endif))
           else
             0
           endif,
         0),
         // Correspondentieadres
         Correspondentie.adrNaam1,    Correspondentie.adrNaam2,
         Correspondentie.adrStraat,   Correspondentie.adrHuisnummer,
         Correspondentie.adrPostcode, Correspondentie.adrPlaats,
         CorrLand.LndEigenCode,       CorrLand.LndOms,         CorrLand.LndPlaatsHuisnr,
         CorrLand.LndPlaatsPostcode,  CorrLand.LndInNAWBlok,
         // Vestigingsadres
         Vestiging.adrNaam1,         Vestiging.adrNaam2,
         Vestiging.adrStraat,        Vestiging.adrHuisnummer,
         Vestiging.adrPostcode,      Vestiging.adrPlaats,
         VestLand.LndEigenCode,      VestLand.LndOms,         VestLand.LndPlaatsHuisnr,
         VestLand.LndPlaatsPostcode, VestLand.LndInNAWBlok,

         if Correspondentie.AdrGid is null then 0 else 1 endif,

         // Bankrekening
         nawRekBankRekening,   nawrekNaamRekHouder,
         nawRekAdresRekHouder, nawrekPostcodeRekHouder, nawrekPlaatsRekHouder,

         // Uit valutacodetabel
         PrintBedragAcceptGiro,

         // Rapportnummer in de taal van de debiteur; HIERO: Wat te doen als rapnummer=null??
         (select RapNummer from tabDocumentLayout inner join tabRapport on RapGid = DocLayRapGidAcceptgiro where DocLayDocSoort = 75 and DocLayTaalGid = nawTaalGid),

         // DOcumentgegevens
         @vgaFormcode,
         @vgaDiversen,
         @vgaEigenrek,
         @vgaBIC,
         OCRBetalingskenmerk(AanmAfdrRksNummer) Betalingskenmerk,
         TaalCode

  from                   tabAanmaningafdrukken
         INNER JOIN      tabTaal on (TaalGid = AanmAfdrTaalGid)
         INNER JOIN      tabNawFile      on (nawFilNummer = AanmAfdrRksNummer and NawFilFonId = 'D')
         INNER JOIN      tabNaw on (NawGid = NawFilNawGid)
         INNER JOIN      (tabAdres Vestiging
                          inner join tabLand VestLand on (VestLand.LndGid = Vestiging.AdrLndGid)
                         ) on (Vestiging.adrGid = NawGidVestiging)
         LEFT OUTER JOIN (tabAdres Correspondentie
                          inner join tabLand CorrLand on (CorrLand.LndGid = Correspondentie.AdrLndGid)
                         ) on (Correspondentie.adrGid = nawGidCorrespondentie)
         LEFT OUTER JOIN tabNawRekening on ((nawRekNawGid = NawGid) and (nawRekSoort like '%D%'))
         INNER JOIN      tabValuta       on (ValNummer = AanmAfdrValNummer)
//         LEFT OUTER JOIN tabAanmaningLayout ON (AanmAfdrtaalGid = AanmLayTaalGid AND (if (NawAanmaningsType = 2) then 0 else (AanmAfdrHoogstNrPerDebPerValuta + 1) endif) = AanmLayNummer) // Hierdoor worden alleen de acceptgiros afgedrukt waarvan de aanmaning WEL een layout heeft!
  where  (AanmAfdrId = @AanmAfdrId)
         // #23865
         // Geblokkeerde posten zitten wel in de aanmaningentabel (worden onderdrukt op rapport; zie opm. AanmaningTabelVullen.sp),
         // maar mogen niet meetellen in het aan te manen bedrag
         and (AanmAfdrIsGeblokkeerd = 0)
         and PrintAcceptgiro = 1
         // Alleen acceptgirogegevens bij instellen layout OF er is een aanmaningslayout(die afgedrukt wordt, zie ook tabNawdocumenten)
         and
         (
         @IsInstellenLayout = 1 or
         //onderstaande query lijkt op query uit dmAanmaningdata, sqlNawDocumenten
         //als er iets afgedrukt wordt(of naar bestand), dan ook acceptgiro vullen
         //dus kijken naar tabel van vaste gegevens aanmaningen
         //en naar documenten per naw
         //en naar afdrukvoorwaarde !
         //Layouts weer afhankelijk van aanmaningnummer(overzicht/1/2/3/4e aanm of na mislukte incasso)
         exists
         (
         select
           (select AanmLayRapGid from tabAanmaningLayout  where AanmLayTaalGid = AanmAfdrtaalGid and AanmLayNummer =  (if (NawAanmaningsType = 2) then 0 else (AanmAfdrHoogstNrPerDebPerValuta + 1) endif) ) DefaultRapNummerIn,
           NawDocRapGidInclBTW NawRapNummerIn,
           IsNull(NawRapNummerIn, DefaultRapNummerIn) RapNummerIn//gidje per naw of uit vaste geg voor een bepaalde aanmaningsnummer
         from Dummy
           left outer join tabNawDocument on (NawDocNawGid = nawgid and NawDocDocSoort = AanmNrNaarDocSoort( (if (NawAanmaningsType = 2) then 0 else (AanmAfdrHoogstNrPerDebPerValuta + 1) endif) ))
           left outer join tabRapDocFormat on rdfGid=nawDocRdfGid
         where  IsNull(NawDocAfdrukVoorwaarde,0) = 0
           and (RapNummerIn is not Null or rdfSoort = 10)//voor xlm uitvoer mag is geen layout nodig
         )//exists
         )//and
  group by
         // Aanmaningen
         AanmAfdrRksNummer,
         AanmAfdrValNummer, AanmAfdrValCode,
         AanmAfdrHoogstNrPerDebPerValuta,
         // NAW
         nawTaalGid,
         Taalcode,
         NawAanmaningsType,
         NawFilZoekcode, //TG 25-07-2013: toegevoegd inzake bug #37664.
         // Correspondentieadres
         Correspondentie.adrNaam1,    Correspondentie.adrNaam2,
         Correspondentie.adrStraat,   Correspondentie.adrHuisnummer,
         Correspondentie.adrPostcode, Correspondentie.adrPlaats,
         CorrLand.LndEigenCode,       CorrLand.LndOms,         CorrLand.LndPlaatsHuisnr,
         CorrLand.LndPlaatsPostcode,  CorrLand.LndInNAWBlok,
         Correspondentie.AdrGid,
         // Vestigingsadres
         Vestiging.adrNaam1,         Vestiging.adrNaam2,
         Vestiging.adrStraat,        Vestiging.adrHuisnummer,
         Vestiging.adrPostcode,      Vestiging.adrPlaats,
         VestLand.LndEigenCode,      VestLand.LndOms,         VestLand.LndPlaatsHuisnr,
         VestLand.LndPlaatsPostcode, VestLand.LndInNAWBlok,
         // Bankrekening
         nawRekBankRekening,   nawrekNaamRekHouder,
         nawRekAdresRekHouder, nawrekPostcodeRekHouder, nawrekPlaatsRekHouder,
         // Uit valutacodetabel
         PrintBedragAcceptGiro
  //TG 25-07-2013: order by is een deel van de oplossing voor bug #37664.
  order by
    if @SorteerVolgorde=0 then if @SorterenOp=0 then AanmAfdrRksNummer else nawFilZoekcode endif endif desc,
    if @SorteerVolgorde=1 then if @SorterenOp=0 then AanmAfdrRksNummer else nawFilZoekcode endif endif,
    AanmAfdrValCode;

  // LET OP: Als een acceptgiro om welke reden dan ook niet kan worden afgedrukt,
  //         dan kan de aanmaning DUS ook niet worden afgedrukt !!!
  // Redenen:
  // - Acceptgiro wordt in deze valuta niet afgedrukt -> gewoon doorgaan
  // - Layoutnummer is in de taal van de debiteur niet ingevuld -> Afbreken (wordt in het programma opgelost)

  // Als de acceptgirobatch leeg is, dan ook die verwijderen
  if not exists( select 1 from tabAcceptGiro where AccAcbGid = @AcbGid) then
    call VerwijderAcceptGiroTabel(@AcbGid);
    // En doorgeven dat er geen tabel is aangemaakt
    set @AcbGid = null;
  end if;

  set @@ErrorTextProcedure = 'AanmaningCreateAcceptGiroBatch > @AcbGid='+string(@AcbGid);
  //call TraceEind(@@ErrorTextProcedure);

end;

//call AanmaningCreateAcceptGiroBatch(1027709960, 0, null)


//-------- Verhoog aanmaningtellers, bijwerken aanmaningdatum en maak tabAanmaningAfdrukken leeg
create or replace procedure AanmaningenBijwerken(in @Id integer, in @TellersVerhogen smallint, in @DatumBijwerken smallint, in @AanmaningDatum date)
begin

  //call TraceBegin ('AanmaningTellersVerhogen (@TellersVerhogen='+string(@TellersVerhogen)+', @DatumBijwerken='+string(@DatumBijwerken)+')');

  set @@ErrorTextProcedure = 'AanmaningTellersVerhogen > @TellersVerhogen='+string(@TellersVerhogen)+', @DatumBijwerken='+string(@DatumBijwerken);
  //call TraceBegin(@@ErrorTextProcedure);

  if @TellersVerhogen = 1 then
    //Rekeningoverzicht niet verhogen
    update tabOpenstaandePost
    set    OspAanmaningTeller = (if AanmMislukteIncasso <> 0 then 1 else OspAanmaningTeller + 1 endif),
           OspSoortFactuur    = (if AanmMislukteIncasso <> 0 then 0 else OspSoortFactuur endif),  //Als het mislukte incasso was, dan nu op normale factuur zetten
           OspBtcNummer       = (if AanmMislukteIncasso <> 0 then null else OspBtcNummer endif),  //Als het mislukte incasso was, dan Betalingsconditie leegmaken
           OspLaatsteAanmaning = (if OspLaatsteAanmaning is null and @DatumBijwerken = 0 then @@verwerkingsdatum else OspLaatsteAanmaning endif)
    from   tabAanmaningAfdrukken
    where (OspGid = AanmAfdrOspGid)
      and (AanmAfdrId = @Id)
      and (OspIsGeblokkeerd = 0)
      and (AanmAfdrVervallenBedrag > 0)
      and (AanmAfdrIsAfgedrukt = 1)
      and ((AanmAfdrAanmnr <> 5) or (AanmMislukteIncasso <> 0))  //Bij afdruk mislukte incasso''s geen tellers bijwerken, maar wel als de soort veranderd wordt
      and (AanmAfdrRekOverzichtIpvAanmaning <> 1);    // niet bij rekoverzicht ipv aanmaning
  end if;

  if @DatumBijwerken = 1 then
    //Datum aanpassen indien aanmaning is of rekeningoverzicht en debiteur krijgt alleen maar rekeningoverzicht
    update tabOpenstaandePost
    set    OspLaatsteAanmaning = @AanmaningDatum
    from   tabAanmaningAfdrukken
    where  (OspGid = AanmAfdrOspGid)
      and (AanmAfdrId = @Id)
      and (OspIsGeblokkeerd = 0)
      and ((AanmAfdrAanmnr <> 5) or (AanmMislukteIncasso <> 0)) //Bij afdruk mislukte incasso''s geen datum bijwerken , maar bij incasso''s die zojuist gewijzigd zijn naar normale factuur wel
      and (AanmAfdrVervallenBedrag > 0)
      and (AanmAfdrIsAfgedrukt = 1);
  end if;

  //call TraceEind ('AanmaningTellersVerhogen');
end;


create or replace procedure AanmaningenTabelVullen(
  inout @Id integer,
  in @BjGid integer,
  in @SelecterenOp smallint,
  in @VanDebiteur nchar(10), in @TotDebiteur nchar(10),
  in @BtcSelecterenOp smallint,
  in @VanBtcNummer integer, in @TotBtcNummer integer,
  in @VanBtcOms nchar(40), in @TotBtcOms nchar(40),
  in @InclusiefPostenZonderBtc smallint,
  in @PeilDatum date,
  in @DatumAanmaning date,
  in @SoortAanmaning smallint, //0=rekeningoverz 1..4 5=mislukte incasso''s, 6=all, 7=rekeningoverzicht(obv instelling debiteur)
  in @VoorlopigeFacturen smallint,
  in @GeblokkeerdePosten smallint,
  in @AllePosten smallint, //0=alleen vervallen, 1=alle
  in @IncassoAfdrukken smallint,
  in @EmailExtraTekst long nvarchar)

begin
  //-------- Vul tijdelijke aanmaningen tabel
  //@SoortAanmaning 0=rekeningoverz 1..4 5 mislukte incasso''s 6=alle
  //@AllePosten     0=alleen vervallen, 1=alle
  //Constanten
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;
  //Constanten @SoortAanmaning
  declare _SoortAanmaningRekeningOverzichtAlleDebiteuren smallint = 0;
  declare _SoortAanmaning1eAanmaning smallint = 1;
  declare _SoortAanmaning2eAanmaning smallint = 2;
  declare _SoortAanmaning3eAanmaning smallint = 3;
  declare _SoortAanmaning4eAanmaning smallint = 4;
  declare _SoortAanmaningNaMislukteIncasso smallint = 5;
  declare _SoortAanmaningAanmaningenEnRekeningoverzicht smallint = 6;
  declare _SoortAanmaningRekeningOverzichtobvInstellingDebiteur smallint = 7;
  //Constanten nawAanmaningsType
  declare _NawAanmaningsTypeGeen smallint = 0;
  declare _NawAanmaningsTypeAanmaning smallint = 1;
  declare _NawAanmaningsTypeRekeningoverzicht smallint = 2;

  declare @DagenNaVerval        integer;
  declare @DagenNaEerste        integer;
  declare @DagenNaTweede        integer;
  declare @DagenNaDerde         integer;
  declare @DagenNaRekOverzicht  integer;
  declare @DagenNaIncasso       integer;
  declare @AantalRegels         integer;

  set @@ErrorTextProcedure = 'AanmaningenTabelVullen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Id = ' + string(@Id) + ', @BjGid = ' + string(@BjGid) + ', @VanDebiteur = ' + @VanDebiteur + ', @TotDebiteur = ' + @TotDebiteur + ', @SoortAanmaning = ' + string(@SoortAanmaning));

  Set @DagenNaRekOverzicht  = (select IsNull(AanmAfdrukkenNa, 0) from tabAanmaning where AanmNummer=0);
  Set @DagenNaVerval        = (select IsNull(AanmAfdrukkenNa, 0) from tabAanmaning where AanmNummer=1);
  Set @DagenNaEerste        = (select IsNull(AanmAfdrukkenNa, 0) from tabAanmaning where AanmNummer=2);
  Set @DagenNaTweede        = (select IsNull(AanmAfdrukkenNa, 0) from tabAanmaning where AanmNummer=3);
  Set @DagenNaDerde         = (select IsNull(AanmAfdrukkenNa, 0) from tabAanmaning where AanmNummer=4);
  Set @DagenNaIncasso       = (select IsNull(AanmAfdrukkenNa, 0) from tabAanmaning where AanmNummer=5);

  //call Trace('AanmaningenTabelVullen > Dagen na RekOverz : '+String(@DagenNaRekOverzicht) + '  Verval : '+String(@DagenNaVerval)+'  1e : '+String(@DagenNaEerste) + '  2e : '+String(@DagenNaTweede) + '  3e : '+String(@DagenNaDerde));

  if @Id is null then
    call RandomNumber2(@Id);
    call LockSetOnId(@@SpId, @@LoginTime, 0, 'tabAanmaningAfdrukken', 'AanmAfdrId='+string(@Id), 0);
  end if;

  delete tabAanmaningAfdrukken where (AanmAfdrId = @Id);

  set @@ErrorTextProcedure = 'AanmaningenTabelVullen > Zet alle openstaande posten van de opgegeven debiteuren in tijdelijke tabel';
  //call Trace(@@ErrorTextProcedure);
  insert into tabAanmaningAfdrukken(AanmAfdrId, AanmAfdrRksNummer, AanmAfdrRksZoekcode, AanmAfdrOspGid,
                                    AanmAfdrTaalGid, AanmAfdrAanmDatum, AanmAfdrVervaldatum, AanmAfdrIsAfgedrukt,
                                    AanmAfdrHoogstNrPerDebPerValuta, AanmAfdrSoortFactuur,
                                    AanmMislukteIncasso,
                                    AanmAfdrAanmnr,
                                    AanmAfdrOpenstaandBedrag,
                                    AanmAfdrVervallenBedrag,
                                    AanmAfdrValNummer, AanmAfdrIsGeblokkeerd,
                                    AanmAfdrFaktuurnr, AanmAfdrFaktuurnr_Lengte, AanmAfdrFaktuurDatum, AanmAfdrBetkenmerk, AanmAfdrOms,
                                    AanmAfdrFaktuurBedrag,
                                    AanmAfdrBetaaldBedrag, AanmAfdrValCode, AanmAfdrDatumLaatsteAanmaning,
                                    AanmAfdrRekOverzichtIpvAanmaning,
                                    AanmAfdrIncDatum, AanmAfdrIncOpdrachten, AanmAfdrIncPogingenOver, AanmAfdrIncRekening, AanmAfdrEmailExtraTekst)

  select  @Id, NawFilNummer, NawFilZoekcode, OspGid,
          NawTaalGid, @DatumAanmaning, OspVervaldatum, _qcNEE,
          OspAanmaningTeller, OspSoortFactuur,
          if OspSoortFactuur = 3 and OspIncPogingenOver = 0 then
            //MR 15-okt-2009 bug #31004: als niet gevonden, dan niet afdrukken. Dan staat de opdracht nog op aangemaakt.
            // Als er een opdracht op aangemaakt staat, dan niet doen.
            IsNull((select MIN(if (IncRglStatus = 1) then 0 else 1 endif) from tabIncassoRegel where OspFactuurNummer_Lengte = length(IncRglFactuurNummer) and OspFactuurNummer = IncRglFactuurNummer and OspRksGid = IncRglRksGid), 1)
          else
            _qcNEE
          endif  AanmMislukteIncasso,
          if OspAanmaningTeller < 4 then
            if (AanmMislukteIncasso <> _qcNEE) and (@SoortAanmaning = _SoortAanmaningNaMislukteIncasso) then  //Incasso, dan kan het alleen maar "na mislukte incasso" zijn... na deze aanmaning wordt ospfactuur op 0 gezet
              5
            else
              if (AanmAfdrOpenstaandBedrag > 0) then //MR 29-mei-2007 Bug# 25952: Alleen teller ophogen als het bedrag groter is dan 0
                OspAanmaningTeller+1
               else
                OspAanmaningTeller
              endif
            endif
          else
            if OspAanmaningTeller = 5 then  //Bij "na mislukte incasso" gaan we gelijk naar 2e aamaning
              2
            else
              4
            endif
          endif AanmAfdrAanmnr,
         (if (@VoorlopigeFacturen <> _qcNEE)
            then ((OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig))
            else ((OspFactuurBedragDefinitief) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig))
          endif) AanmAfdrOpenstaandBedrag,
         (if OspVervalDatum <= @PeilDatum or AanmMislukteIncasso <> _qcNEE then AanmAfdrOpenstaandBedrag else 0 endif),
          OspValNummer, OspIsGeblokkeerd,
          OspFactuurNummer, OspFactuurNummer_Lengte, OspFactuurDatum, OspBetalingsKenmerk, OspOms,
         (if @VoorlopigeFacturen <> _qcNEE
            then (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)
            else OspFactuurBedragDefinitief
          endif) AanmAfdrFaktuurBedrag,
          (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), OspValCode, OspLaatsteAanmaning,
          (if NawAanmaningsType = _NawAanmaningsTypeRekeningoverzicht then _qcJA else _qcNEE endif),
          OspIncDatum, OspIncOpdrachten, OspIncPogingenOver, NawRekBankRekening, @EmailExtraTekst
  from (tabOpenstaandePost
         inner join (tabNawFile inner join tabNaw on (NawGid = NawFilNawGid)
         inner join tabFileOfNaw on (FonGid = NawFilFonGid)) on (NawFilRksGid = OspRksGid)
        )
  left outer join tabNawRekening on (NawRekNawGid = NawGid and OspIncNawRekGid = NawRekGid)
  left outer join tabBetalingsconditie on OspBtcNummer = BtcNummer
  where (OspBjGid = @BjGid)
    and (fonID='D') and (OspSoortFactuur <> 3 or (OspSoortFactuur = 3 and @IncassoAfdrukken <> _qcNEE))
    and (@GeblokkeerdePosten <> _qcNEE or OspIsGeblokkeerd = _qcNEE) //MR 14-okt-2009 bug #30999: Geblokkeerde posten vinkje
    and (NawAanmaningsType <> _NawAanmaningsTypeGeen) 	//Ook al is OSP geblokkeerd dan toch meenemen, wordt afgedrukt met een * o.i.d.
    and (@SoortAanmaning <> _SoortAanmaningRekeningOverzichtobvInstellingDebiteur or NawAanmaningsType = _NawAanmaningsTypeRekeningoverzicht)
    and (   ((@VoorlopigeFacturen <> _qcNEE) and OspIsVervallen = _qcNEE)
         or ((@VoorlopigeFacturen = _qcNEE) and ((OspFactuurBedragDefinitief) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig) <> 0))
        )
    and	(    (@SelecterenOp = 1 and NawFilNummer   between @VanDebiteur and @TotDebiteur)
          or (@SelecterenOp = 2 and (NawFilZoekcode between @VanDebiteur and @TotDebiteur))
        )
    and (    (@BtcSelecterenOp = 0 and OspBtcNummer between @VanBtcNummer and @TotBtcNummer)
          or (@BtcSelecterenOp = 1 and BtcOms between @VanBtcOms and @TotBtcOms)
          or (@InclusiefPostenZonderBtc = 1 and OspBtcNummer is null)
        )
    // DG 12-02-2007: In kader van #24073; Sla de OSP's van NAW's over in andere batches, om te voorkomen dat ze dubbel worden aangemaand
    and not Exists (select 1 from tabAanmaningAfdrukken where AanmAfdrId <> @Id and NawFilNummer = AanmAfdrRksNummer);

  //select count(*) into @AantalRegels from tabAanmaningAfdrukken where AanmAfdrId = @Id;
  //call Trace('AanmaningenTabelVullen > AantalRegels (1)= '+string(@AantalRegels));

  // Gooi alle regels weg (in iedere valuta) voor die debiteur die al 4 aanmaningen (in een valuta) heeft gehad en de bijbehorede OSP is niet geblokkeerd
  //RB 22-08-2003 : Dit doen we dus niet meer voor rekeningoverzichten !!! (bug 8708)
  if @SoortAanmaning not in (_SoortAanmaningRekeningOverzichtAlleDebiteuren, _SoortAanmaningRekeningOverzichtobvInstellingDebiteur) then
    delete tabAanmaningAfdrukken
     where AanmAfdrRekOverzichtIpvAanmaning = _qcNEE and (AanmAfdrId = @Id) //JV/RvdL, 8 april 08, laatste and nav bug 28085
       and tabAanmaningAfdrukken.AanmAfdrRksNummer in (select distinct a.AanmAfdrRksNummer from tabAanmaningAfdrukken a where a.AanmAfdrHoogstNrPerDebPerValuta = 4 and a.AanmAfdrIsGeblokkeerd = _qcNEE and (a.AanmAfdrId = @Id));
  end if;

  //select count(*) into @AantalRegels from tabAanmaningAfdrukken where AanmAfdrId = @Id;
  //call Trace('AanmaningenTabelVullen > AantalRegels (2)= '+string(@AantalRegels));

  if IsModuleActive('n2') <> _qcNEE then
    //Indien we alleen de vervallen posten meenemen, dan de lopende incasso''s NIET meenenem
    delete tabAanmaningAfdrukken where AanmAfdrId = @Id and @AllePosten = _qcNEE and AanmAfdrSoortFactuur = 3 and AanmMislukteIncasso = _qcNEE;

    //Vervallen bedrag moet alleen gevuld zijn voor mislukte incasso''s
    update tabAanmaningAfdrukken set AanmAfdrVervallenBedrag = null where AanmAfdrId = @Id and AanmAfdrSoortFactuur = 3 and AanmMislukteIncasso = _qcNEE;
  end if;

  //select count(*) into @AantalRegels from tabAanmaningAfdrukken where AanmAfdrId = @Id;
  //call Trace('AanmaningenTabelVullen > AantalRegels (3)= '+string(@AantalRegels));

  update tabAanmaningAfdrukken
  set    AanmAfdrHoogstNrPerDebPerValuta =       //Per debiteur per valuta het huidige hoogste aanmaningnummer bepalen waarvoor geldt dat post vervallen is
            IsNull((select (if max(a.AanmAfdrHoogstNrPerDebPerValuta) < 4 then max(a.AanmAfdrHoogstNrPerDebPerValuta) else 4 endif)
                    from    tabAanmaningAfdrukken a
                    where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
                      and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
                      and  (a.AanmAfdrVervaldatum <= @Peildatum or a.AanmMislukteIncasso <> _qcNEE)
                      and  (a.AanmAfdrIsGeblokkeerd = _qcNEE)
                      and  (a.AanmAfdrOpenstaandBedrag > 0)   // ACW 11-08-2005 bug 18517: alleen als openstaande bedrag > 0 dan de datum in de bepaling meenemen
                      and  (a.AanmAfdrId = @Id)
                     ), -1),
        AanmAfdrJongsteDatumLaatsteAanmaning =    //Per debiteur per valuta de datum van de laatste aanmaning bepalenwaavoor geldt dat post vervallen is
            (select  max(a.AanmAfdrDatumLaatsteAanmaning)
             from    tabAanmaningAfdrukken a
             where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
               and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
               and  (a.AanmAfdrVervaldatum <= @Peildatum or a.AanmMislukteIncasso <> _qcNEE)
               and  (a.AanmAfdrIsGeblokkeerd = _qcNEE)
               and  (a.AanmAfdrOpenstaandBedrag > 0)
               and  (a.AanmAfdrId = @Id)),
        AanmAfdrOudsteVervaldatum =               //Per debiteur per valuta de oudste vervaldatum bepalen waavoor geldt dat post vervallen is
            (select  min(a.AanmAfdrVervaldatum)
             from    tabAanmaningAfdrukken a
             where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
               and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
               and  (a.AanmAfdrVervaldatum <= @Peildatum or a.AanmMislukteIncasso <> _qcNEE)
               and  (a.AanmAfdrIsGeblokkeerd = _qcNEE)
               and  (a.AanmAfdrOpenstaandBedrag > 0)
               and  (a.AanmAfdrId = @Id)),
        AanmAfdrTotaalVervallen =                 // per debiteur per valuta het totaal vervallen bedrag
            (select  sum(a.AanmAfdrVervallenBedrag)
             from    tabAanmaningAfdrukken a
             where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
               and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
               and  (a.AanmAfdrVervaldatum <= @Peildatum or a.AanmMislukteIncasso <> _qcNEE)
               and  (a.AanmAfdrIsGeblokkeerd = _qcNEE)
               //and  (a.AanmAfdrOpenstaandBedrag > 0)   //Defect #29545
               and  (a.AanmAfdrId = @Id))
  where  (AanmAfdrId = @Id);

  if IsModuleActive('n2') <> _qcNEE then ///incasso''s
    update tabAanmaningAfdrukken
    set    AanmAfdrHoogstNrPerDebPerValuta =
              IsNull((select (if max(a.AanmAfdrHoogstNrPerDebPerValuta) < 4 then max(a.AanmAfdrHoogstNrPerDebPerValuta) else 4 endif)
                      from    tabAanmaningAfdrukken a
                      where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
                        and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
                        and  (a.AanmAfdrVervaldatum <= @Peildatum)
                        and  (a.AanmAfdrIsGeblokkeerd = _qcNEE)
                        and  (a.AanmAfdrId = @Id)
                        and  (a.AanmAfdrHoogstNrPerDebPerValuta <> 5)
                        and  (a.AanmAfdrHoogstNrPerDebPerValuta <> 0)
                        and  (a.AanmAfdrOpenstaandBedrag > 0)  // ACW 11-08-2005 bug 18517: alleen als openstaande bedrag > 0 dan de datum in de bepaling meenemen
                     ), AanmAfdrHoogstNrPerDebPerValuta)
    where  (AanmAfdrId = @Id) and AanmAfdrHoogstNrPerDebPerValuta = 5;
  end if;

  if @SoortAanmaning not in (_SoortAanmaningRekeningOverzichtAlleDebiteuren, _SoortAanmaningRekeningOverzichtobvInstellingDebiteur) then    // niet bij rekeningoverzicht !
    delete tabAanmaningAfdrukken
    where (AanmAfdrTotaalVervallen <= 0)
      and (AanmAfdrRekOverzichtIpvAanmaning = _qcNEE) and (AanmAfdrSoortFactuur <> 3)  //Met incasso''s niets doen, die zijn er evt. al uitgefilterd
      and (AanmAfdrId = @Id);

    //select count(*) into @AantalRegels from tabAanmaningAfdrukken where AanmAfdrId = @Id;
    //call Trace('AanmaningenTabelVullen > AantalRegels (3a)= '+string(@AantalRegels));

    //ACW 4-5-2000: Gooi alle regels weg van een debiteur in een taal als deze alleen niet-geblokkeerde en/of niet-vervallen posten heeft
    //RVL 07-10-2010 #32911 : Niet de rekeningoverzichtregels weggooien als je alle posten afdrukt
    delete tabAanmaningAfdrukken where  AanmAfdrId = @Id and tabAanmaningAfdrukken.AanmAfdrRksNummer not in
      (select distinct a.AanmAfdrRksNummer
       from tabAanmaningAfdrukken a
       where a.AanmAfdrIsGeblokkeerd = _qcNEE
        and AanmAfdrId = @Id
        and (AanmAfdrVervallenBedrag <> 0 or AanmAfdrSoortFactuur = 3 or (AanmAfdrRekOverzichtIpvAanmaning <> _qcNEE and @AllePosten <> _qcNEE)));

  end if;

  //select count(*) into @AantalRegels from tabAanmaningAfdrukken where AanmAfdrId = @Id;
  //call Trace('AanmaningenTabelVullen > AantalRegels (4)= '+string(@AantalRegels));

  if @SoortAanmaning = _SoortAanmaningNaMislukteIncasso then
    delete tabAanmaningAfdrukken where AanmAfdrId = @Id and AanmMislukteIncasso = _qcNEE;
  else
    delete tabAanmaningAfdrukken
    where not (    (  (@SoortAanmaning in (_SoortAanmaningAanmaningenEnRekeningoverzicht, _SoortAanmaningRekeningOverzichtobvInstellingDebiteur))
                      and (AanmAfdrRekOverzichtIpvAanmaning <> _qcNEE)
                      and (AanmAfdrJongsteDatumLaatsteAanmaning + @DagenNaRekOverzicht <= @Peildatum)
                    )
                or (  (@SoortAanmaning in (_SoortAanmaning1eAanmaning,_SoortAanmaningAanmaningenEnRekeningoverzicht))
                      and (AanmAfdrRekOverzichtIpvAanmaning = _qcNEE)
                      and (AanmAfdrHoogstNrPerDebPerValuta  =  0)
                      and (AanmAfdrOudsteVervaldatum + @DagenNaVerval <= @Peildatum)
                    )
                or (  (@SoortAanmaning in (_SoortAanmaning2eAanmaning,_SoortAanmaningAanmaningenEnRekeningoverzicht))
                      and (AanmAfdrRekOverzichtIpvAanmaning = _qcNEE)
                      and (AanmAfdrHoogstNrPerDebPerValuta  =  1)
                      and (AanmAfdrJongsteDatumLaatsteAanmaning + @DagenNaEerste <= @Peildatum)
                   )
                or (  (@SoortAanmaning in (_SoortAanmaning3eAanmaning,_SoortAanmaningAanmaningenEnRekeningoverzicht))
                      and (AanmAfdrRekOverzichtIpvAanmaning = _qcNEE)
                      and (AanmAfdrHoogstNrPerDebPerValuta  =  2)
                      and (AanmAfdrJongsteDatumLaatsteAanmaning + @DagenNaTweede <= @Peildatum)
                    )
                or (  (@SoortAanmaning in (_SoortAanmaning4eAanmaning,_SoortAanmaningAanmaningenEnRekeningoverzicht))
                      and (AanmAfdrRekOverzichtIpvAanmaning = _qcNEE)
                      and (AanmAfdrHoogstNrPerDebPerValuta  =  3)
                      and (AanmAfdrJongsteDatumLaatsteAanmaning + @DagenNaDerde  <= @Peildatum)
                    )
                or (@SoortAanmaning = _SoortAanmaningRekeningOverzichtAlleDebiteuren)
              )
          and (AanmAfdrId = @Id);
  end if;

  //select count(*) into @AantalRegels from tabAanmaningAfdrukken where AanmAfdrId = @Id;
  //call Trace('AanmaningenTabelVullen > AantalRegels (5)= '+string(@AantalRegels));

  // gooi alle regels weg van rekeningoverzicht indien alleen NIET vervallen posten en deze NIET afdrukken
  if (@AllePosten = _qcNEE) then
    delete tabAanmaningAfdrukken
    where (((@SoortAanmaning in (_SoortAanmaningAanmaningenEnRekeningoverzicht, _SoortAanmaningRekeningOverzichtobvInstellingDebiteur)) and (AanmAfdrRekOverzichtIpvAanmaning <> _qcNEE))
          or (@SoortAanmaning = _SoortAanmaningRekeningOverzichtAlleDebiteuren))
      and (AanmAfdrId = @Id) //JV/RvdL, 8 april 08, laatste and nav bug 28085.
      and  ((select count (1)
             from    tabAanmaningAfdrukken a
             where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
               and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
               and  (a.AanmAfdrVervaldatum <= @Peildatum)
               and  (a.AanmAfdrId = @Id)) = 0);
  end if;

  //call Trace('Update laatste betaaldatum en laatste betaling');
  update tabAanmaningAfdrukken
  set    AanmAfdrLaatsteBetaalDatum    = JrBoekDatum ,
         AanmAfdrBedragLaatsteBetaling = JrValutaBedrag
  from   tabJournaalregel
  where  (JrGid = LaatsteBetaling(@BjGid, AanmAfdrOspGid, 2))
   and  (AanmAfdrId = @Id);

  //call TraceEind ('AanmaningenTabelVullen');
end;


//-------  Maak 5 records aan in tabAanmaning om de instellingen op te slaan
create or replace procedure AanmaningInstellingenCreate()
begin
  declare @Teller integer;

  //call TraceBegin('AanmaningInstellingenCreate()');

  set @Teller = 0;
  while @Teller <= 5 loop //0=rekeningoverzicht, 1-4=aanmaningen, 5=misluke incasso
    if not exists(select 1 from tabAanmaning where AanmNummer = @Teller) then
      insert into tabAanmaning (AanmNummer, AanmAfdrukkenNa, AanmOpBellijstNa) values (@Teller, 1, 0);
    end if;
    set @Teller = @Teller + 1;
  end loop;

  //call TraceEind('AanmaningInstellingenCreate');

end;


//-------  Update de aanmaning layouts
create or replace procedure AanmaningLayoutsUpdate(in @AanmNummer integer, in @TaalGid integer, in @RapGid integer)
begin
  //call TraceBegin('AanmaningLayoutsUpdate(@AanmNummer='+string(@AanmNummer)+' @TaalGid='+string(@TaalGid)+', @RapGid='+string(@RapGid)+')');

  if exists(select 1 from tabAanmaningLayout where AanmLayNummer = @AanmNummer and AanmLayTaalGid = @TaalGid) then
    update tabAanmaningLayout set AanmLayRapGid=@RapGid where AanmLayNummer=@AanmNummer and AanmLayTaalGid=@TaalGid;
  else
    insert into tabAanmaningLayout(AanmLayNummer, AanmLayTaalGid, AanmLayRapGid) values (@AanmNummer, @TaalGid, @RapGid);
  end if;

  //call TraceEind('AanmaningLayoutsUpdate');

end;


//-------- Vul tijdelijke aanmaningen tabel
create or replace procedure AanmaningOverzichtTabelVullen(inout @Id integer, in @BjGid integer, in @SelecterenOp smallint,
                                               in @VanDebiteur nchar(10), in @TotDebiteur nchar(10),
                                               in @BtcSelecterenOp smallint,
                                               in @VanBtcNummer integer, in @TotBtcNummer integer,
                                               in @VanBtcOms nchar(40), in @TotBtcOms nchar(40),
                                               in @InclusiefPostenZonderBtc smallint,
                                               in @PeilDatum date, in @SoortAanmaning smallint, //0|die vervallen posten hebben|1..4|die ten minste 1..4 keer zijn aangemaand
                                               in @OpBasisVan smallint)

begin
  //@SoortAanmaning 0|die vervallen posten hebben|1..4|die ten minste 1..4 keer zijn aangemaand
  //@OpBasisVan     0|Definitieve gegevens|1|Voorlopige gegevens|2|Definitieve en voorlopige gegevens

  declare @DatumAanmaning       date;

  set @@ErrorTextProcedure = 'AanmaningOverzichtTabelVullen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@SelecterenOp = ' + string(@SelecterenOp) + ', @VanDebiteur = ' + @VanDebiteur + ', @TotDebiteur = ' + @TotDebiteur + ', @PeilDatum = ' + string(@PeilDatum) + ', @DatumAanmaning = ' + string(@DatumAanmaning) + ', @SoortAanmaning = ' +string(@SoortAanmaning));

  //call Trace('AanmaningOverzichtTabelVullen > Maak unieknummer aan en zet lock');
  if @Id is null then
    call RandomNumber2(@Id);
    call LockSetOnId(@@SpId, @@LoginTime, 0, 'tabAanmaningAfdrukken', 'AanmAfdrId='+string(@Id), 0);
  end if;

  //call Trace('AanmaningOverzichtTabelVullen > Verwijder eventuele nog bestaande regels uit tijdelijke tabel');
  delete tabAanmaningAfdrukken where (AanmAfdrId = @Id);

  //call Trace('AanmaningOverzichtTabelVullen > Zet alle openstaande posten van de opgegeven debiteuren in tijdelijke tabel');
  insert into tabAanmaningAfdrukken(AanmAfdrId, AanmAfdrRksNummer, AanmAfdrRksZoekcode, AanmAfdrOspGid,
                                    AanmAfdrTaalGid, AanmAfdrAanmDatum, AanmAfdrVervaldatum, AanmAfdrIsAfgedrukt,
                                    AanmAfdrHoogstNrPerDebPerValuta, AanmAfdrAanmnr,
                                    AanmAfdrOpenstaandBedrag, AanmAfdrVervallenBedrag, AanmAfdrValNummer, AanmAfdrIsGeblokkeerd,
                                    AanmAfdrFaktuurnr, AanmAfdrFaktuurnr_Lengte, AanmAfdrFaktuurDatum, AanmAfdrBetkenmerk, AanmAfdrOms, AanmAfdrFaktuurBedrag,
                                    AanmAfdrBetaaldBedrag, AanmAfdrValCode, AanmAfdrDatumLaatsteAanmaning, AanmAfdrRekOverzichtIpvAanmaning)
  select  @Id, NawFilNummer, NawFilZoekcode, OspGid,
          NawTaalGid, @DatumAanmaning, OspVervaldatum, 0,
          IsNull(OspAanmaningTeller, 0) AanmAfdrHoogstNrPerDebPerValuta,
          AanmAfdrHoogstNrPerDebPerValuta AanmAfdrAanmnr,
         (if @OpBasisVan = 0
            then (OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief)
            else if @OpBasisVan = 1
                    then (OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig)
                    else ((OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig))
                 endif
          endif) AanmAfdrOpenstaandBedrag,
         (if OspVervalDatum <= @PeilDatum then AanmAfdrOpenstaandBedrag else 0 endif),
          OspValNummer, OspIsGeblokkeerd,
          OspFactuurNummer, OspFactuurNummer_Lengte, OspFactuurDatum, OspBetalingsKenmerk, OspOms,
         (if @OpBasisVan = 0
            then OspFactuurBedragDefinitief
            else if @OpBasisVan = 1
                    then OspFactuurBedragVoorlopig
                    else (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)
                 endif
          endif) AanmAfdrFaktuurBedrag,
         (if @OpBasisVan = 0
            then OspBetaaldBedragDefinitief
            else if @OpBasisVan = 1
                    then OspBetaaldBedragVoorlopig
                    else (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                 endif
          endif) AanmAfdrBetaaldBedrag,
          OspValCode, OspLaatsteAanmaning,
          (if NawAanmaningsType = 2 then 1 else 0 endif)
  from    tabOpenstaandePost
    inner join (tabNawFile inner join tabNaw on (NawGid = NawFilNawGid)
    inner join tabFileOfNaw on (FonGid = NawFilFonGid)) on (NawFilRksGid = OspRksGid)
    left outer join tabBetalingsconditie on OspBtcNummer = BtcNummer
  where   (OspBjGid = @BjGid)
    and   (fonID='D')
    and  (    ((@OpBasisVan = 0) and ((OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief) <> 0 ))
           or ((@OpBasisVan = 1) and ((OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig)   <> 0 ))
           or ((@OpBasisVan = 2) and OspIsVervallen = 0))
    and	 (    (@SelecterenOp = 1 and NawFilNummer    between @VanDebiteur and @TotDebiteur)
           or (@SelecterenOp = 2 and (NawFilZoekcode between @VanDebiteur and @TotDebiteur))  )
    and   (
               (@BtcSelecterenOp = 0 and OspBtcNummer between @VanBtcNummer and @TotBtcNummer)
            or (@BtcSelecterenOp = 1 and BtcOms between @VanBtcOms and @TotBtcOms)
            or (@InclusiefPostenZonderBtc = 1 and OspBtcNummer is null)  );

  //call Trace('AanmaningOverzichtTabelVullen > Bijwerken totalen');
  update tabAanmaningAfdrukken
  set    AanmAfdrHoogstNrPerDebPerValuta =       //Per debiteur per valuta het huidige hoogste aanmaningnummer bepalen waavoor geldt dat post vervallen is
            (select (if max(a.AanmAfdrHoogstNrPerDebPerValuta) < 4 then max(a.AanmAfdrHoogstNrPerDebPerValuta) else 4 endif)
             from    tabAanmaningAfdrukken a
             where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
               and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
               and  (a.AanmAfdrId = @Id)),
        AanmAfdrJongsteDatumLaatsteAanmaning =    //Per debiteur per valuta de datum van de laatste aanmaning bepalenwaavoor geldt dat post vervallen is
            (select  max(a.AanmAfdrDatumLaatsteAanmaning)
             from    tabAanmaningAfdrukken a
             where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
               and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
               and  (a.AanmAfdrId = @Id)),
        AanmAfdrOudsteVervaldatum =               //Per debiteur per valuta de oudste vervaldatum bepalen waavoor geldt dat post vervallen is
            (select  min(a.AanmAfdrVervaldatum)
             from    tabAanmaningAfdrukken a
             where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
               and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
               and  (a.AanmAfdrId = @Id)),
        AanmAfdrTotaalVervallen =                 // per debiteur per valuta het totaal vervallen bedrag
            (select  sum(a.AanmAfdrVervallenBedrag)
             from    tabAanmaningAfdrukken a
             where  (a.AanmAfdrRksNummer = tabAanmaningAfdrukken.AanmAfdrRksNummer)
               and  (a.AanmAfdrValNummer = tabAanmaningAfdrukken.AanmAfdrValNummer)
               and  (a.AanmAfdrId = @Id))
  where  (AanmAfdrId = @Id);

  //@SoortAanmaning 0|die vervallen posten hebben|1..4|die ten minste 1..4 keer zijn aangemaand
  // gooi alle niet af te drukken posten weg !
  delete tabAanmaningAfdrukken
  where not (    ((@SoortAanmaning = 1) and (AanmAfdrHoogstNrPerDebPerValuta >= 1) )
              or ((@SoortAanmaning = 2) and (AanmAfdrHoogstNrPerDebPerValuta >= 2) )
              or ((@SoortAanmaning = 3) and (AanmAfdrHoogstNrPerDebPerValuta >= 3) )
              or ((@SoortAanmaning = 4) and (AanmAfdrHoogstNrPerDebPerValuta >= 4) )
              or ((@SoortAanmaning = 0))
            )
        and (AanmAfdrId = @Id);

  //call Trace('AanmaningOverzichtTabelVullen > Update laatste betaaldatum en laatste betaling');
  update tabAanmaningAfdrukken
  set    AanmAfdrLaatsteBetaalDatum    = JrBoekDatum ,
         AanmAfdrBedragLaatsteBetaling = JrValutaBedrag
  from   tabJournaalregel
  where  (JrGid = LaatsteBetaling(@BjGid, AanmAfdrOspGid, @OpBasisVan))
   and  (AanmAfdrId = @Id);

  set @@ErrorTextProcedure = 'AanmaningOverzichtTabelVullen';
  //call TraceEind(@@ErrorTextProcedure);
end;


//----------- Geef Documentsoort adv aanmaningsnummer
create or replace function AanmNrNaarDocSoort( in @AanmNr integer)
returns integer
begin
  declare @DocSoort integer;
  set @@ErrorTextProcedure = 'AanmNrNaarDocSoort > @AanmNr='+string(@AanmNr);
  //call TraceBegin(@@ErrorTextProcedure);
  //(20290) Onjuist aanmaningsnummer!;
  case @AanmNr
    when null then
      //RB raiserror 20290;//foutmelding geven
      //RB Indien NULL dan uitgaan van rekening overzicht ivm DevOps 32881
      set @DocSoort = 81; //rekeningoverzicht
    when 0 then
      set @DocSoort = 81; //rekeningoverzicht
    when 1 then
      set @DocSoort = 83; //1e aanmaning
    when 2 then
      set @DocSoort = 84; //2e aanmaning
    when 3 then
      set @DocSoort = 85; //3e aanmaning
    when 4 then
      set @DocSoort = 86; //4e aanmaning
    when 5 then
      set @DocSoort = 82; //Na mislukte incasso
    else
      raiserror 20290;//foutmelding geven
    end case;
  set @@ErrorTextProcedure = 'AanmNrNaarDocSoort > @DocSoort='+string(@DocSoort);
  //call TraceEind(@@ErrorTextProcedure);
  return(@DocSoort);

end;


//---- procedure retourneert het aantal lege strings in de kolom @Veldnaam
create or replace procedure AantalLegeStringsInKolom(in @TabelNaam nchar(30), in @VeldNaam nchar(30), out @AantalLegeStrings integer)
begin

  set @@ErrorTextProcedure = 'AantalLegeStringsInKolom > @TabelNaam='+string(@TabelNaam)+', @VeldNaam='+string(@Veldnaam);
  //call TraceBegin(@@ErrorTextProcedure);

  execute immediate 'select count(*) into @AantalLegeStrings from '||@TabelNaam||' where string('||@Veldnaam||') = '''' ';

  set @@ErrorTextProcedure = 'AantalLegeStringsInKolom > @AantalLegeStrings='+string(@AantalLegeStrings);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure AantalNullInKolom(
//---- procedure retourneert het aantal null waarden in de kolom @Veldnaam
  in  @TabelNaam  varchar(30),
  in  @VeldNaam   varchar(30),
  out @AantalNull integer)
begin
  select count(*) into @AantalNull from `[@TabelNaam]` where `[@Veldnaam]` is null;
end;


create or replace procedure AbonnementAanMakenOrder(
  in  @AboGid integer,
  in  @AbvGid integer,
  in  @OrderDatum date,
      @PeriodeBeginDatum date,
      @PeriodeEindDatum date,
      @AlleenOrderAanmaken smallint,
  out @OrkGid integer,
  out @FoutNummer smallint,
  out @FoutMelding nchar(250)
) //@FoutNummer = 0 = OK
begin
  declare @OrderNummer                      numeric(10,0);
  declare @AantalRegels                     integer = 0;                //Nieuwe order => 0 regels dus
  declare @GegenereerdOrderNummerGebruikt   smallint;
  declare @OrderKopMagGid                   integer = null;             //magazijn voor de orderkop
  declare @NawGidDebiteur                   integer;
  declare @NawBlokOrderInvoer               smallint;
  declare @OrderKorting                     numeric(15,2);
  declare @AbvContractperiodeAantal         integer;
  declare @AbvContractperiodePeriode        smallint;
  declare @AbvFactureerfrequentieAantal     integer;
  declare @AbvFactureerfrequentiePeriode    smallint;
  declare @AbvNawGidFactuur                 integer;
  declare @AbvOrderStatusIsVrijVoorLeveren  integer;
  declare @AbvNummer                        integer;
  declare @AbvNawGidPrijzen                 integer;
  declare @AbvBeginDatum                    date;
  declare @ContractPeriode                  date;
  declare @LeverDatum                       date;

  declare @OrderBevestigingsfunctie       integer;
  declare @GebruikOrderkorting            smallint;
  declare @IsStuksKorting                 smallint;
  declare @ReserveerNegatief              smallint;

  declare @DatePartFactureerPeriode       nchar(5);
  declare @DatePartContractPeriode        nchar(5);
  declare @NieuweContractPeriode          smallint = 0;

  declare @DummyChar                      nchar(3);
  declare @DummyInt                       integer; //dummy voor parameters die je niet gebruikt
  declare @PraVerkoopPrijs                numeric(15,3);
  declare @PraKortingsoort                smallint;
  declare @PraKortingsPercentage          numeric(6,2);
  declare @PraKortingsBedrag              numeric(15,3);
  declare @NawOrderKorting                numeric(6,2);


  //call TraceBegin('AbonnementAanMakenOrder > ');

  //Kostenplaats en kostendrager check
  select _U('Abonnement moet een kostenplaats hebben!') into @FoutMelding
  from tabAbonnementVersie,tabVasteGegevensOrdersFactureren
  where (abvGid = @AbvGid) and (AbvKstpGid is null and vofRegelKstpVerplicht <> 0);

  if @Foutmelding <> '' then
    set @Foutnummer = 1;
    return;
  end if;

  select _U('Abonnement moet een kostendrager hebben!') into @FoutMelding
  from tabAbonnementVersie,tabVasteGegevensOrdersFactureren
  where (abvGid = @AbvGid) and (AbvKstdGid is null and vofRegelKstdVerplicht <> 0) ;

  if @Foutmelding <> '' then
    set @Foutnummer = 1;
    return;
  end if;


  //Ordernummer genereren en onthouden
  set @OrderNummer  = GeefNieuwOrderNummer(0, 1);
  //call Trace('AbonnementAanMakenOrder > @OrderNummer = ' + string(@OrderNummer));

  select DocFnCodeDefault into @OrderBevestigingsfunctie  from tabDocument  where DocSoort = 20;
  select first vofOrderKortingSoort, vofIsStukskorting, VofFactVoorraadReserverenNegatief into @GebruikOrderkorting, @IsStuksKorting, @ReserveerNegatief from tabVasteGegevensOrdersFactureren;

  //Magazijn bepalen
  select ToeMagMagGid into @OrderKopMagGid from tabToegestaneMagazijnen inner join tabGebruiker on (GebruikerGid = ToeMagGebrGid) where NaamGebruiker = @@GebruikerCode and ToeMagToepassing = 10;
  if @OrderKopMagGid is null then
    select MagGid into @OrderKopMagGid from tabMagazijn where MagCode=1;
  end if;

  select AboNawGidDebiteur, NawBlokOrderInvoer into @NawGidDebiteur, @NawBlokOrderInvoer
  from tabAbonnementKop
  inner join tabNaw on NawGid = AboNawGidDebiteur
  where aboGid = @AboGid;

  select AbvOrderKorting, AbvContractperiodeAantal, AbvContractperiodePeriode, AbvFactureerfrequentieAantal, AbvFactureerfrequentiePeriode, AbvNawGidFactuur, AbvOrderStatusIsVrijVoorLeveren, AbvNummer, AbvNawGidPrijzen, AbvBeginDatum
    into @OrderKorting, @AbvContractperiodeAantal, @AbvContractperiodePeriode, @AbvFactureerfrequentieAantal, @AbvFactureerfrequentiePeriode, @AbvNawGidFactuur, @AbvOrderStatusIsVrijVoorLeveren, @AbvNummer, @AbvNawGidPrijzen, @AbvBeginDatum
    from tabAbonnementVersie
    where abvGid = @AbvGid;

  set @LeverDatum = @OrderDatum;

  if @AlleenOrderAanmaken = 1 then //Als je alleen de order aanmaakt is er mischien een ander historie record. Gebruik deze dan voor de leverdatum en de Nieuwecontractperiode
    Select first AbhOrderDatum, AbhNieuweContractPeriode into @LeverDatum, @NieuweContractPeriode
    from tabAbonnementHistorie
    where AbhAboGid = @AboGid
    and AbhAbvGid = @AbvGid
    and AbhPeriodeBeginDatum = @PeriodeBeginDatum
    and AbhPeriodeEindDatum = @PeriodeEindDatum
  end if;

  //Haal de vaste gegevens van de versie op om de kop van de order aan te maken
  //Voor deze debiteur een order beginnen.
  insert into tabOrderkop
   (OrkSoort, OrkInclBtw, OrkIsDeelLeveringToegestaan,
    OrkIsGeblokkeerdVoorMuteren,OrkBackTotaalInklBtw,OrkBackTotaalExklBtw,
    OrkGoedgekeurd,           OrkGoedgekeurdDatum,           OrkGoedgekeurdDoor,
    OrkVrijVoorFaktureren,    OrkVrijgegevenDatum,           OrkVrijgegevenDoor,
    OrkVrijVoorLevering,      OrkVrijVoorLeveringDatum,      OrkVrijVoorLeveringDoor,
    OrkVrijVoorVerzamelLijst, OrkVrijVoorVerzamelLijstDatum, OrkVrijVoorVerzamelLijstDoor,
    OrkDatum,OrkLeverdatum, OrkVtgCode,
    OrkNawGid,
    OrkApartFaktureren,
    OrkAdrGid,OrkVerzendAdres,
    OrkAdrGidEindAdres, OrkEindAdres,
    OrkFactuurAdres,OrkBtcNummer,OrkLvcNummer,OrkValNummer,OrkNummer,
    OrkRelGid,OrkReferentie,
    OrkDefaultMagGid, OrkIsVerzamellijstGebruiken, OrkIncNawRekGid,
    OrkIsInkoopCombinatie, OrkFactuurNawGid, OrkNawGidOmzet, OrkNawGidPrijzen,
    OrkKstpGid, OrkKstdGid,
    OrkApartLeveren
    )
  select   0 /*Verkooporder*/, AbvBtwStand, AbvIsDeelLeveringToegestaan,
    //Vlaggetjes vd order
    0, 0, 0,
    //goedgekeurd                //goedgekeurd datum                                     //goedgekeurd gebruiker
    AbvOrderStatusIsGoedgekeurd, if (AbvOrderStatusIsGoedgekeurd = 1) then now(*) endif, if (AbvOrderStatusIsGoedgekeurd = 1) then @@GebruikerCode endif,
    //vrij voor Fact                    //vrijgegeven datum                                            //vrijgegeven gebruiker
    AbvOrderStatusIsVrijVoorFactureren, if (AbvOrderStatusIsVrijVoorFactureren = 1) then now(*) endif, if (AbvOrderStatusIsVrijVoorFactureren = 1) then @@GebruikerCode endif,
    //vrij voor lev.          //vrijgegeven datum                              //vrijgegeven gebruiker
    0, null, null, //Deze zetten we beneden in de proc ivm partij/serienummers.
    //vrij voor verzamellijst              //vrijgegeven datum                                                //vrijgegeven gebruiker
    AbvOrderStatusIsVrijVoorVerzamellijst, if (AbvOrderStatusIsVrijVoorVerzamellijst = 1)  then now(*) endif, if (AbvOrderStatusIsVrijVoorVerzamellijst = 1)  then @@GebruikerCode endif,
    //datums
    @OrderDatum, @LeverDatum,
    //vertegenwoordiger ophalen
    IsNull(AboVtgCode,MainNaw.nawVertegenwCode),
    //velden uit deb-gegevens...
    MainNaw.NawGid,
    AbvAparteFactuur,
    IsNull(AbvAdrGidVerzendAdres,IsNull((select FactuurDeb.NawGidVerzendAdres from tabNaw FactuurDeb where FactuurDeb.NawGid = AbvNawGidFactuur), MainNaw.NawGidVerzendAdres)) VerzendAdresGid,
    (if VerzendAdresGid is null and AbvVerzendadres = 2 then
      0 //=corr. order deb
    else
      if VerzendAdresGid is null and AbvVerzendadres = 5 then
        3 //=corr. fact. deb.
      else
        AbvVerzendadres
    endif endif),
    IsNull(AbvAdrGidEindBestemming,IsNull((select FactuurDeb.NawGidEindAdres from tabNaw FactuurDeb where FactuurDeb.NawGid = AbvNawGidFactuur), MainNaw.NawGidEindAdres)) EindAdresGid,
    (if EindAdresGid is null and AbvFactuurAdres = 2 then
      0 //=corr. adres
    else
      AbvEindAdres
    endif),
    AbvFactuurAdres,
    AbvBtcNummer,
    AbvLvcNummer, AbvValNummer,
    //Gegenereerd ordernummer
    @OrderNummer,
    //VoorkeurContactpersoon van functie die bij Orderbevestiging staat
    RelGid,
    AbonnementAanmakenTekst(abvReferentie, @AbvGid, @PeriodeBeginDatum, @PeriodeEindDatum),
    //Magazijn
    @OrderKopMagGid, AbvOrderVerzamellijstGebruiken,
    //Orderkop rekeningnummer
    (if (select SoortFactuurBtc from tabBetalingsConditie where BtcNummer = AbvBtcNummer) = 3 then
      (select NawRekGid from tabNawRekening where NawRekNawGid = IsNull(AbvNawGidFactuur, MainNaw.NawGid) and Locate(NawRekSoort, 'I') <> 0)
    else
      null
    endif),
    AbvIsInkoopcombinatie, AbvNawGidFactuur, AbvNawGidOmzet, AbvNawGidPrijzen,
    AbvKstpGid, AbvKstdGid,
    // Waarde bepalen voor OrkApartLeveren. Is afhankelijk van vaste gegevens van debiteur.
    (select NawAparteLevering from tabNaw where NawGid =  MainNaw.NawGid) NawAparteLevering

  from tababonnementKop
  inner join tabAbonnementversie on abvabogid = abogid
  inner join (tabNaw MainNaw inner join tabNawFile MainNawFile on (MainNawFile.NawFilNawGid = MainNaw.NawGid)) on NawGid = AboNawGidDebiteur
  //left outer join (tababonnementKop inner join tabAbonnementversie on abvabogid = abogid and abvgid = @AbvGid ) on AboNawGidDebiteur = nawgid
  //left outer join tabContributieCode on ContributieCode = @NawContributieCode
  left outer join (tabScherm inner join tabFunctieContact on (SchermFnCode = FnCode )
    inner join ( tabRelatieFunctie inner join tabRelatie on(RelGid = FnRelGid and relNawGid = @NawGidDebiteur ) ) on ( FnCode = RelFnCode and IsBelangrijkste = 1 )) on SchermSoort = 30
  where AboGid = @AboGid
  and abvgid = @AbvGid;
//           where MainNaw.NawGid = aboNawGid;

  SET @OrkGid = @@Identity;

  //Wanneer begint de nieuwe contractperiode?
  SET @DatePartContractPeriode  = Case @AbvContractperiodePeriode
                                  when 0 then 'day'
                                  when 1 then 'week'
                                  when 2 then 'month'
                                  when 3 then 'year'
                                  end;

  //Zoek de contractperiode van de versie op
  select first AbhPeriodeBeginDatum into @ContractPeriode
    from tabAbonnementHistorie
    inner join tabAbonnementVersie on abvGid = abhabvGid
    where abvGid = @AbvGid
    and AbhNieuweContractPeriode = 1
    order by AbhPeriodeBeginDatum desc;

  if @ContractPeriode is null then
    set @ContractPeriode = @AbvBeginDatum; //gelijkstellen aan de eerste periode van de versie
    //Defect #56652: Het kan zijn dat er nog geen contractperiode bestaat. Zet de @Contractperiode wel naar de eerstvolgende qua datum dan.
    while @ContractPeriode < @PeriodeBeginDatum loop
      execute immediate 'SET @ContractPeriode = DateAdd(' + @DatePartContractPeriode + ', @AbvContractperiodeAantal, @ContractPeriode)';
    end loop;
  else
    execute immediate 'SET @ContractPeriode = DateAdd(' + @DatePartContractPeriode + ', @AbvContractperiodeAantal, @ContractPeriode)';
  end if;

  if @NieuweContractPeriode=0 then //Als deze 1 is dan is hij al bepaald.
    set @NieuweContractPeriode = if (@ContractPeriode = @PeriodeBeginDatum) then 1 else 0 endif; //De komende periode is het begin van een nieuwe contractperiode;
  end if;

  if @AlleenOrderAanmaken = 0 then //Alleen de order aanmaken en niet de prijzen aanpassen
  begin
    declare @ArtikelBlokkeerTekst long nvarchar;
    declare @TariefBlokkeerTekst long nvarchar;
    declare @PartijBlokkeerTekst long nvarchar;

    set @ArtikelBlokkeerTekst = _U('Artikel %1! is geblokkeerd voor verkoop');
    set @TariefBlokkeerTekst = _U('Tarief %1! is geblokkeerd voor verkoop');
    set @PartijBlokkeerTekst = _U('Partijnummer %1! van artikel %2! is geblokkeerd voor verkoop');

    //Open cursor voor de abonnementRegels.
    FOR @Cursor AS CURSOR_AbonnementRegels CURSOR FOR
      select  AbrGid                              @AbrGid,
              abrRegelnr                          @AbrRegelNr,
              abrAantalDecimalenVoorAantallen     @abrAantalDecimalenVoorAantallen,
              abrAantalDecimalenVoorPrijzen       @abrAantalDecimalenVoorPrijzen,
              abrKostprijs                        @abrKostprijs,
              abrPrijsPer                         @abrPrijsPer,
              AbrArtGid                           @AbrArtGid,
              abrArtPartijGid                     @AbrArtPartijGid,
              ArtCode                             @ArtCode,
              ArtAantallen                        @ArtAantallen,
              (if (ArtIsPartijAparteKostPrijs=1) and not (ArtPartijGid is null) then ArtPartijKostprijsEx else ArtKostprijsEx endif) @ArtKostPrijs,
              ArtIsGeblokkeerd                    @ArtIsGeblokkeerd,
              ArtPartijNummer                     @ArtPartijNummer,
              ArtPartijIsGeblokkeerdVoorVerkoop   @ArtPartijIsGeblokkeerdVoorVerkoop,
              abrRegelsoort                       @abrRegelsoort,
              AbrIsKortingsPercentage             @AbrIsKortingsPercentage,
              Abrkorting2                         @Abrkorting2,
              AbrKorting1                         @AbrKorting1,
              AbrBtwCode                          @AbrBtwCode,
              abrPrijs                            @abrPrijs,
              ArtOpbrGrpGId                       @ArtOpbrGrpGId,
              AbrTekstOpOrder                     @AbrTekstOpOrder,
              AbrAantalOpOrder                    @AbrAantalOpOrder,
              abrPrijsBepalenBij                  @abrPrijsBepalenBij,
              abrKostprijsBepalenBij              @abrKostprijsBepalenBij,
              abrKorting1BepalenBij               @abrKorting1BepalenBij,
              abrKorting2BepalenBij               @abrKorting2BepalenBij,
              abrabrGidVolgregelMaster            @abrabrGidVolgregelMaster,
              abrVolgartikelFactor                @abrVolgartikelFactor,
              AbvBtwStand                         @AbvBtwStand,
              AbvValNummer                        @AbvValNummer
      from tabAbonnementRegel
      inner join tabAbonnementVersie on abvGid = abrAbvGid
      inner join tabartikel on artgid = abrArtGid
      left outer join tabartikelPartij on ArtPartijArtGid = abrArtGid and ArtPartijGid = abrArtPartijGid
      where AbrAbvGid = @abvGid
      order by abrRegelnr
    FOR UPDATE
    DO
      //Is het artikel geblokkeerd?
      if @ArtIsGeblokkeerd=1 then //Blocked voor orderinvoer
        set @FoutNummer=1;
        set @FoutMelding= if (@abrRegelsoort=2) then _P(@ArtikelBlokkeerTekst, @ArtCode) else _P(@TariefBlokkeerTekst, @ArtCode) endif;
        delete from tabOrderKop where OrkGid = @OrkGid;
        call ResetGegenereerdOrderNummer(@OrderNummer);
        set @OrkGid = null;
        return;
      end if;
      //Is de partij geblokkeerd?
      if @ArtPartijIsGeblokkeerdVoorVerkoop=1 then //Blocked voor orderinvoer
        set @FoutNummer=2;
        set @FoutMelding=_P(@PartijBlokkeerTekst,  @ArtPartijNummer, @ArtCode);
        delete from tabOrderKop where OrkGid = @OrkGid;
        call ResetGegenereerdOrderNummer(@OrderNummer);
        set @OrkGid = null;
        return;
      end if;

      call BepaalPrijsAfspraak(isNull(@AbvNawGidPrijzen,@NawGidDebiteur),@AbrArtGid,Null,Null,Null,@AbrArtPartijGid,@AbvBtwStand,@AbvValNummer,@AbrAantalOpOrder,@AbrAantalOpOrder,
                               @@BasisValutaNummer, @@BasisValutaCode, @@VerwerkingsDatum, @DummyInt,@DummyInt,@DummyInt,@DummyChar,@PraVerkoopPrijs,@PraKortingSoort,
                               @PraKortingsPercentage,@PraKortingsBedrag,
                               @DummyInt,@DummyInt,@DummyInt);
      //Prijzen bepalen bij
      //0 = afblijven
      //1 = contractperiode
      //2 = factureerperiode
      Case @abrPrijsBepalenBij
      when 1 then //contractperiode
        if (@NieuweContractPeriode = 1) then
          set @abrPrijs = @PraVerkoopPrijs;
        end if;
      when 2 then //factureerperiode
        set @abrPrijs = @PraVerkoopPrijs;
      end;

      Case @abrKostprijsBepalenBij
      when 1 then //contractperiode
        if (@NieuweContractPeriode = 1) then
          set @abrKostprijs = @ArtKostPrijs;
        end if;
      when 2 then //factureerperiode
        set @abrKostprijs = @ArtKostPrijs;
      end;

      if (((@abrKorting1BepalenBij = 1) and (@NieuweContractPeriode = 1)) or (@abrKorting1BepalenBij = 2)) and (@IsStukskorting = 0) and (@PraKortingsBedrag <> 0) then
        set @AbrIsKortingsPercentage = 1;
        set @PraKortingsPercentage   = if @PraVerkoopPrijs = 0 then 0 else Round((@PraKortingsBedrag / @PraVerkoopPrijs) * 100, 2) end if;
        set @PraKortingsBedrag       = 0;

        //Kortingspercentage is kleiner dan 0. Zet de korting dan in de BrutoVerkoopprijs
        if  (@PraKortingsPercentage < -100) or (@PraKortingsPercentage > 100) then
          set @abrPrijs               = @PraVerkoopPrijs * ((100.00 - @PraKortingsPercentage) / 100.00);
          set @PraKortingsPercentage  = 0.00;
        end if;
      end if;

      //RB Defect 49305: @AbrIsKortingsPercentage niet zomaar aanpassen als korting niet wordt aangepast!
      // Korting alleen vullen als korting bepalen bij nieuwe contractperiode of factureerperiode
      if ( (@abrKorting1BepalenBij = 1) and (@NieuweContractPeriode = 1) ) or (@abrKorting1BepalenBij = 2) then
        if (@PraKortingSoort=1) then
          set @AbrKorting1 = @PraKortingsPercentage;
          set @AbrIsKortingsPercentage = 1;
        else
          set @AbrKorting1 = @PraKortingsBedrag;
          set @AbrIsKortingsPercentage = 0;
        end if;
      end if;

      if (@GebruikOrderkorting = 2) then
        // Orderkorting als regelkorting 2 opnemen
        select (if NawFilWelkeOrderKorting = 1 then DebGrpOrderKorting else NawOrderKorting endif) into @NawOrderKorting
        from tabNaw
        inner join tabNawFile on NawFilNawGid = NawGid and NawFilFonId = 'D'
        left outer join tabDebiteurGroepen on NawFilDebGrpGid = DebGrpGid
        where NawFilNawGid = IsNull(null, @NawGidDebiteur);
      end if;

      Case @abrKorting2BepalenBij
      when 1 then //contractperiode
        if (@NieuweContractPeriode = 1) then
          set @AbrKorting2 = if (@GebruikOrderkorting = 2) then @NawOrderKorting else 0 endif;
        end if;
      when 2 then //factureerperiode
        set @AbrKorting2 = if (@GebruikOrderkorting = 2) then @NawOrderKorting else 0 endif;
      end;

      update tabAbonnementRegel set abrPrijs                = isNull(@abrPrijs,0),
                                    abrKostprijs            = isNull(@abrKostprijs,0),
                                    AbrKorting1             = isNull(@AbrKorting1,0),
                                    AbrKorting2             = isNull(@AbrKorting2,0),
                                    AbrIsKortingsPercentage = @AbrIsKortingsPercentage
      where abrGid = @abrGid;
    END FOR;
  end;
  end if;

  //Haal de abonnementsregels op en maak er orderregels van
  insert into tabOrderRegel
    (OrrOrkGid,OrrLeverDatum,OrrRegelnr,OrrAantDecAantal,OrrAantDecAantalVrrdEenh, OrrAantDecBedrag,OrrKostprijs,
     OrrPrijsPer,OrrArtGid,OrrArtPartijGid,OrrIsAantallen,OrrRegelsoort,OrrIsKortingsPercentage,OrrRegelkorting2,
     OrrRegelKorting1,OrrBtwCode,OrrBrutoVerkoopPrijs,OrrOpbrGrpGid,OrrTekstOpFactuur,
     OrrVkeGid,OrrAantalVrrdEenhInVerkEenh, OrrAantalVrrdEenhInVerkEenhMagAfwijken, OrrEenheidPrijsPer,
     OrrAantalBesteld, OrrAantalBesteldVrrdEenh,
     OrrAantalDezeFacturering, OrrAantalDezeFactureringVrrdEenh,
     OrrAantalLevering, OrrAantalLeveringVrrdEenh,
     OrrMagGid, OrrReserveringNegatief,
     OrrDirecteInkoop, OrrDirecteLevering, OrrKstpGid, OrrKstdGid)
  select  orkGid, OrkLeverDatum,abrRegelnr,abrAantalDecimalenVoorAantallen, abrAantalDecimalenVoorAantallen,abrAantalDecimalenVoorPrijzen,abrKostprijs,
          abrPrijsPer,AbrArtGid,AbrArtPartijGid,if (isNull(AbrAantalOpOrder,0)<>0) then 1 else ArtAantallen endif,abrRegelsoort,AbrIsKortingsPercentage,Abrkorting2,
          AbrKorting1,AbrBtwCode,abrPrijs,ArtOpbrGrpGId,
          AbonnementAanmakenTekst(AbrTekstOpOrder, @AbvGid, @PeriodeBeginDatum, @PeriodeEindDatum),
          VkeGid, VkeAantalVoorraadEenhedenInVerkoopEenheid, VkeAantalKanVerschillen, VkeVerkoopPrijsPer,
          AbrAantalOpOrder,
          AbrAantalOpOrder,
          (if (ArtBestellenViaDirecteInkoop=0) or (abrRegelsoort<>2) then if (ArtAantallen=0 and isNull(AbrAantalOpOrder,0)=0) then 1 else AbrAantalOpOrder endif else 0 endif),
          (if (ArtBestellenViaDirecteInkoop=0) or (abrRegelsoort<>2) then if (ArtAantallen=0 and isNull(AbrAantalOpOrder,0)=0) then 1 else AbrAantalOpOrder endif else 0 endif),
          (if (ArtBestellenViaDirecteInkoop=0) or (abrRegelsoort<>2) then if (ArtAantallen=0 and isNull(AbrAantalOpOrder,0)=0) then 1 else AbrAantalOpOrder endif else 0 endif),
          (if (ArtBestellenViaDirecteInkoop=0) or (abrRegelsoort<>2) then if (ArtAantallen=0 and isNull(AbrAantalOpOrder,0)=0) then 1 else AbrAantalOpOrder endif else 0 endif),
          OrkDefaultMagGid,@ReserveerNegatief, ArtBestellenViaDirecteInkoop, ArtBestellenVoorDirecteLevering, if (abrRegelsoort<>0) then AbvKstpGid endif, if (abrRegelsoort<>0) then AbvKstdGid endif
  from (tabAbonnementRegel inner join tabAbonnementVersie on abvGid = abrAbvGid
                           left outer join tabartikel on artgid = abrArtGid
                           left outer join tabVerkoopEenheid on VkeArtGid = abrArtGid and VkeIsVoorraadEenheid = 1), tabOrderKop
  where abrabvgid = @abvGid
  and Orkgid = @OrkGid
  order by abrRegelnr;

  if IsOrderSpecificatieregelActief() = 1 then
    // ACW 2023-04-04: Specificatieregels aanmaken obv status
    begin
      declare @HeeftSpecregelsZonderLocatie smallint;
      call OrderRegelSpecificaties_VulLocatiesAan(
        @OrkGid,
        null, // voor alle orderregels van deze order
        @MatViewNummerVoorraadAantallen = '',
        @HeeftSpecregelsZonderLocatie=@HeeftSpecregelsZonderLocatie
      );
    end;
  end if;

  update tabOrderRegel
  Set OrrVervolgMasterOrrGid = (Select orrmaster.orrGid
                                from taborderRegel orrmaster,tabAbonnementregel abrMaster
                                Where  orrmaster.OrrRegelnr = abrMaster.AbrRegelNr
                                and orrmaster.OrrArtGid = abrMaster.AbrArtgid
                                And orrmaster.OrrOrkGid = @OrkGid
                                and abrMaster.abrGid = abrChild.abrabrGidVolgregelMaster)
  from taborderregel orrchild,tabAbonnementregel abrChild
  Where  orrchild.OrrRegelnr = abrChild.AbrRegelNr
  and orrchild.OrrArtGid = abrChild.AbrArtgid
  And orrchild.OrrOrkGid = @OrkGid
  and not abrChild.abrabrGidVolgregelMaster is null
  and abrChild.AbrAbvGid =@AbvGid;

  //Kijken of er nu uberhaupt regels zijn aangemaakt bij het ordernummer
  if not exists (select 1 from tabOrderRegel inner join tabOrderKop where OrkNummer = @OrderNummer) then
    delete from tabOrderKop where OrkNummer = @OrderNummer;
    set @Foutnummer = 1;
    set @FoutMelding= _U('De order heeft geen regels.');
    set @GegenereerdOrderNummerGebruikt = 0;
  else
    begin
      declare @_OrderKortingTekst long nvarchar;

      if (@OrderKorting <> 0) and (@GebruikOrderkorting = 1)then
        set @_OrderKortingTekst = _A('Orderkorting');
        insert into tabOrderExtraRegel
           (OerOrkGid, OerBerekenOverToeslag,OerBerekenOverKorting,OerBerekenOverEmballage,OerBerekenOverArtikel,OerBerekenOverTarief,
            OerRegelnr,OerRegelSoort,OerOmschrijving,OerTekstOpFactuur,OerPerc)
        values
           (@OrkGid, 1, 1, 2, 2, 2,
           0, 0, @_OrderKortingTekst, @_OrderKortingTekst, @OrderKorting);
      end if;

      //Als er artikelen met partijen/serienummer registratie zijn gebruikt, kan de order nooit op "Vrij voor leveren" komen.
      if not (exists (select 1 from tabOrderRegel inner join tabOrderKop left outer join tabArtikel on OrrArtGid = ArtGid where OrkNummer = @OrderNummer and OrrRegelSoort = 2 and (ArtIsPartijRegistreren = 1 or ArtSerieNrRegistreren = 1)))
         and @AbvOrderStatusIsVrijVoorLeveren =1 then
        update tabOrderKop set
          OrkVrijVoorLevering = 1,
          OrkVrijVoorLeveringDatum = now(*),
          OrkVrijVoorLeveringDoor = @@GebruikerCode
        where OrkNummer = @OrderNummer;
      end if;

      set @GegenereerdOrderNummerGebruikt = 1;
    end;
  end if;

  //Orderstartnummer terugzetten indien niet gebruikt.
  if (@Foutnummer >= 1) and (@GegenereerdOrderNummerGebruikt = 0) then
    call ResetGegenereerdOrderNummer(@OrderNummer);
    set @OrkGid = null;
  else
    //Vul de gegevens in in de abonnementshistorie
    insert into tabAbonnementHistorie (AbhAboGid,AbhAbvGid, AbhVersieNummer, AbhOrderDatum, AbhOrkNummer, AbhPeriodeBeginDatum, AbhPeriodeEindDatum, AbhNieuweContractPeriode )
    values (@AboGid, @AbvGid, @AbvNummer, @OrderDatum, @OrderNummer, @PeriodeBeginDatum, @PeriodeEindDatum, @NieuweContractPeriode);

    call VrKopieerRecord('ABO',0,0,'ORK',0,0,@AbvGid,@OrkGid);

    if @AlleenOrderAanmaken = 0 then //Alleen de order aanmaken en niet de prijzen aanpassen
      //De volgende orderdatum.
      SET @DatePartFactureerPeriode  = Case @AbvFactureerfrequentiePeriode
                                        when 0 then 'day'
                                        when 1 then 'week'
                                        when 2 then 'month'
                                        when 3 then 'year'
                                       end;

      execute immediate 'SET @OrderDatum = DateAdd(' + @DatePartFactureerPeriode + ', @AbvFactureerfrequentieAantal, @OrderDatum)';

      //De volgende orderdatum invullen
      update tabAbonnementVersie set abvVolgendeOrderdatum = @OrderDatum where abvGid = @abvGid;
    end if;

    call Maatwerk_AbonnementOrder(@AbvGid,@OrkGid);
  end if;

  //call TraceEind('AbonnementAanMakenOrder');
end;

create or replace function AbonnementAanmakenTekst(in @Referentie long nvarchar, in @AbvGid integer, in @FactuurPeriodeBeginDatum date, in @FactuurPeriodeEindDatum date)
returns long nvarchar
begin
  declare @AboCode                nchar(20);
  declare @AboOmschrijving        nchar(40);
  declare @AbvNummer              integer;
  declare @TaalGid                integer;
  declare @ContractperiodeAantal  integer;
  declare @ContractperiodePeriode integer;
  declare @BeginDatum             date;
  declare @EindDatum              date;

  declare @ContractPeriodeBeginDatum  date;
  declare @ContractPeriodeEindDatum   date;

  declare @DatePartContractPeriode  nchar(5);

  set @@ErrorTextProcedure = 'AbonnementAanmakenTekst > ';
  //call TraceBegin(@@ErrorTextProcedure);

  //Haal abonnement op
  select AboCode, AboOmschrijving, AbvNummer, abvTaalGid,
         AbvContractperiodeAantal, AbvContractperiodePeriode, AbvBeginDatum, AbvEindDatum
         into @AboCode, @AboOmschrijving, @AbvNummer, @TaalGid,@ContractperiodeAantal, @ContractperiodePeriode, @BeginDatum, @EindDatum
  from tabAbonnementVersie
  inner join tabAbonnementKop on AboGid = AbvAboGid
  where abvGid = @AbvGid;

  //De contractperiodedatums goed zetten.
  SET @DatePartContractPeriode  = Case @ContractperiodePeriode
                                when 0 then 'day'
                                when 1 then 'week'
                                when 2 then 'month'
                                when 3 then 'year'
                                end;

  set @ContractPeriodeBeginDatum  = @BeginDatum;
  if (@ContractperiodeAantal = 0) then
    SET @ContractPeriodeEindDatum   = @ContractPeriodeBeginDatum;
  else
    execute immediate 'SET @ContractPeriodeEindDatum   = DateAdd(day,-1,DateAdd(' + @DatePartContractPeriode + ',@ContractperiodeAantal, @ContractPeriodeBeginDatum))';
  end if;

  WHILE (@ContractPeriodeEindDatum < @FactuurPeriodeEindDatum) LOOP
    //De volgende orderdatum, periode begindatum en periode einddatum goed zetten
    if @ContractPeriodeEindDatum is null then
      execute immediate 'SET @ContractPeriodeBeginDatum = DateAdd(' + @DatePartContractPeriode + ', @ContractperiodeAantal, @ContractPeriodeBeginDatum)';
    else
      Set @ContractPeriodeBeginDatum = DateAdd(Day,1,@ContractPeriodeEindDatum);
    end if;

    if (@ContractperiodeAantal = 0) then
      SET @ContractPeriodeEindDatum = @ContractPeriodeBeginDatum;
    else
      execute immediate 'SET @ContractPeriodeEindDatum   = DateAdd(day,-1,DateAdd(' + @DatePartContractPeriode + ',@ContractperiodeAantal, @ContractPeriodeBeginDatum))';
    end if;
  END LOOP;

  //De referentie opbouwen
  SET @Referentie = REPLACE(@Referentie,'<CODE>',@aboCode);
  SET @Referentie = REPLACE(@Referentie,'<OMSCHRIJVING>',@AboOmschrijving);
  SET @Referentie = REPLACE(@Referentie,'<VERSIENUMMER>',@abvNummer);

  if @FactuurPeriodeBeginDatum is not null then
    SET @Referentie = AbonnementAanmakenTekstDatum(@Referentie,'BEGIN',@FactuurPeriodeBeginDatum,@TaalGid);
  end if;

  if @FactuurPeriodeEindDatum is not null then
    SET @Referentie = AbonnementAanmakenTekstDatum(@Referentie,'EIND',@FactuurPeriodeEindDatum,@TaalGid);
  end if;

  if @ContractPeriodeBeginDatum is not null then
    SET @Referentie = AbonnementAanmakenTekstDatum(@Referentie,'CONTRACT BEGIN',@ContractPeriodeBeginDatum,@TaalGid);
  end if;

  if @ContractPeriodeEindDatum is not null then
    SET @Referentie = AbonnementAanmakenTekstDatum(@Referentie,'CONTRACT EIND',@ContractPeriodeEindDatum,@TaalGid);
  end if;

  set @@ErrorTextProcedure = 'AbonnementAanmakenTekst';
  //call TraceEind(@@ErrorTextProcedure);

  return(@Referentie);
end;

create or replace function AbonnementAanmakenTekstDatum(in @Referentie long nvarchar, in @DatumPrefix nchar(40), in @ReferentieDatum date, in @TaalGid integer)
returns long nvarchar
begin
  declare @DatumWeekNumber        integer;
  declare @DatumYearOfWeekNumber  integer;

  declare @FormatDate   nchar(80);
  declare @FormatKort   nchar(40);
  declare @FormatMiddel nchar(40);
  declare @FormatLang   nchar(40);
  declare @MaandNaam    nchar(15);

  set @@ErrorTextProcedure = 'AbonnementAanmakenTekstDatum > ';
  //call TraceBegin(@@ErrorTextProcedure);

  //Haal het begin- en eind weeknummer en jaar op
  call ISOWeekOfYearAndYearOfWeek(@ReferentieDatum,@DatumWeekNumber,@DatumYearOfWeekNumber);

  select TaalDatumKort, TaalDatumMiddel, TaalDatumLang into @FormatKort, @formatMiddel, @formatLang from tabTaal where TaalGid = @TaalGid;

  //Korte datumnotatie
  call DatumFormat(@ReferentieDatum, @FormatKort, @TaalGid, @FormatDate);
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'DATUM>'        , @FormatDate);
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'DATUM-k>'      , @FormatDate);
  //Middel datumnotatie
  call DatumFormat(@ReferentieDatum, @formatMiddel, @TaalGid, @FormatDate);
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'DATUM-m>'      , @FormatDate);
  //Lange datumnotatie
  call DatumFormat(@ReferentieDatum, @formatLang, @TaalGid, @FormatDate);
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'DATUM-l>'      , @FormatDate);
  //Weeknummer
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'WEEKNUMMER>' , string(@DatumWeekNumber));
  //Lange Maandnaam
  select Trim(MndLang) into @MaandNaam from tabMaandnaam where MndTaalGid = @TaalGid and MndId = Month(@ReferentieDatum);
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'MAAND>'    , @MaandNaam);
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'MAAND-l>'  , @MaandNaam);
  //Korte Maandnaam
  select Trim(MndKort) into @MaandNaam from tabMaandnaam where MndTaalGid = @TaalGid and MndId = Month(@ReferentieDatum);
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'MAAND-k>'  , @MaandNaam);
  //Maandnummer
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'MAAND-nr>'  , Month(@ReferentieDatum));
  //Jaar
  SET @Referentie = REPLACE(@Referentie,'<'+@DatumPrefix+'JAAR>'     , Year(@ReferentieDatum));

  set @@ErrorTextProcedure = 'AbonnementAanmakenTekstDatum';
  //call TraceEind(@@ErrorTextProcedure);

  return(@Referentie);
end;

create or replace procedure AbonnementAanTeMakenOrders(in @AboSelectieOp smallint, in @VanAbo nchar(40), in @TotAbo nchar(40),
                                                       in @DebSelectieOp smallint, in @VanDeb nchar(10), in @TotDeb nchar(10),
                                                       in @AanmakenTmDatum date)

result (
  AboGid            integer,
  AbvGid            integer,
  NawFilNummer      nchar(10),
  AdrNaam1          nchar(40),
  Factureerperiode  integer,
  OrderDatum        date,
  PeriodeBeginDatum date,
  PeriodeEindDatum  date,
  abvStatus         smallint,
  abvMelding        nchar(250),
  OrkGid            integer
)
begin
  declare local temporary table tmpAbonnementen(
  AboGid            integer,
  AbvGid            integer,
  NawFilNummer      nchar(10),
  AdrNaam1          nchar(40),
  Factureerperiode  integer,
  OrderDatum        date,
  PeriodeBeginDatum date,
  PeriodeEindDatum  date)
  on commit preserve rows;

  declare @CurrentAbvGid            integer = 0;
  declare @volgendeOrderDatum       date;
  declare @PeriodeBeginDatum        date;
  declare @PeriodeEindDatum         date;
  declare @DatePartFactureerPeriode nchar(5);

  set @@ErrorTextProcedure = 'AbonnementAanTeMakenOrders > ';
  //call TraceBegin(@@ErrorTextProcedure);

  FOR @Cursor AS CURSOR_Abonnementen CURSOR FOR
    select
      AboGid                          @AboGid,
      AbvGid                          @AbvGid,
      NawFilNummer                    @NawFilNummer,
      AdrNaam1                        @AdrNaam1,
      AbvFactureerfrequentieAantal    @AbvFactureerfrequentieAantal,
      AbvFactureerfrequentiePeriode   @AbvFactureerfrequentiePeriode,
      AbvEersteOrderDatum             @AbvEersteOrderDatum,
      AbvVolgendeOrderDatum           @AbvVolgendeOrderDatum,
      abvBeginDatum                   @AbvBeginDatum,
      AbvEindDatum                    @AbvEindDatum,
      (if isnull(abvEinddatum,@AanmakenTmDatum) < @AanmakenTmDatum then abvEinddatum else @AanmakenTmDatum  endif) as @TmDatum,
      (select first abhGid from tabAbonnementHistorie where abhabvgid=abvGid order by abhPeriodeBeginDatum desc) as @LaatsteOrder
    from tabAbonnementVersie
    inner join tabAbonnementKop on aboGid = AbvAboGid
    left outer join (tabNaw inner join tabAdres on adrNawGid = NawGid and (adrGid=nawGidVestiging) inner join tabNawFile on (NawFilNawGid = NawGid)) on nawGid = AboNawGidDebiteur
    where NawfilFonId = 'D'
    and ((@AboSelectieOp = 0 and AboCode      between @VanAbo and @TotAbo) or (@AboSelectieOp = 1 and AboOmschrijving  between @VanAbo and @TotAbo))
    and ((@DebSelectieOp = 0 and NawfilNummer between @VanDeb and @TotDeb) or (@DebSelectieOp = 1 and NawfilZoekcode   between @VanDeb and @TotDeb))
    and (isNull(abvVolgendeorderdatum, abvEersteOrderDatum) <= @TmDatum)
    and ((AbvEinddatum is null) or (AbvEinddatum >= (select isNull(Max(abhPeriodeEinddatum),abvEindDatum) from tabAbonnementHistorie where abhabvgid = abvGid)))
    order by aboCode,abvNummer
  FOR READ ONLY
  DO
    //Kijken hoeveel periodes er moeten worden aangemaakt
    if (@CurrentAbvGid <> @AbvGid) then
      SET @PeriodeBeginDatum = null;
      SET @PeriodeEindDatum = null;
      SET @CurrentAbvGid = @AbvGid
    end if;

    SET @volgendeOrderDatum = isNull(@AbvVolgendeOrderDatum,@AbvEersteOrderDatum);
    Select abhPeriodeBegindatum,abhPeriodeEinddatum into @PeriodeBeginDatum,@PeriodeEindDatum from tabAbonnementHistorie where abhgid=@LaatsteOrder;

    SET @DatePartFactureerPeriode  = Case @AbvFactureerfrequentiePeriode
                                      when 0 then 'day'
                                      when 1 then 'week'
                                      when 2 then 'month'
                                      when 3 then 'year'
                                     end;

    WHILE (@volgendeOrderDatum <= @TmDatum) LOOP
      if (@PeriodeBeginDatum is Null) then
        //Als er nog geen order ooit is aangemaakt dan de datum van de volgende order pakken als startdatum.
        Set @PeriodeBeginDatum = @AbvBeginDatum;
      else
        //De volgende orderdatum, periode begindatum en periode einddatum goed zetten
        if @PeriodeEindDatum is null then
          execute immediate 'SET @PeriodeBeginDatum = DateAdd(' + @DatePartFactureerPeriode + ', @AbvFactureerfrequentieAantal, @PeriodeBeginDatum)';
        else
          Set @PeriodeBeginDatum = DateAdd(Day,1,@PeriodeEindDatum);
        end if;
      end if;

      if (@AbvFactureerfrequentieAantal = 0) then
        SET @PeriodeEindDatum   = @PeriodeBeginDatum;
      else
        execute immediate 'SET @PeriodeEindDatum   = DateAdd(day,-1,DateAdd(' + @DatePartFactureerPeriode + ',@AbvFactureerfrequentieAantal, @PeriodeBeginDatum))';
      end if;

      if (@PeriodeEindDatum > @AbvEindDatum) then
        //Nooit voorbij de einddatum gaan.
        SET @PeriodeEindDatum = @AbvEindDatum;
        if @PeriodeEindDatum < @PeriodeBeginDatum then
          SET @PeriodeEindDatum   = @PeriodeBeginDatum;
        end if;
        SET @TmDatum          = DateAdd(day,-1,@PeriodeEindDatum ); //tm datum -1 dag, anders komt je in een neverending lus
      end if;

      if (@PeriodeBeginDatum < IsNull(@AbvEindDatum,@PeriodeEindDatum)) then
        //Maak een order aan voor de @volgendeOrderDatum als de begindatum van de periode binnen het abonnement valt
        insert into tmpAbonnementen(AboGid, AbvGid, NawFilNummer, AdrNaam1, FactureerPeriode, OrderDatum, PeriodeBeginDatum, PeriodeEindDatum)
        values(@AboGid, @AbvGid, @NawFilNummer, @AdrNaam1, 1, @volgendeOrderDatum,@PeriodeBeginDatum,@PeriodeEindDatum);
      end if;

      //De volgende orderdatum, periode begindatum en periode einddatum goed zetten
      if (@AbvFactureerfrequentieAantal = 0) then
        SET @volgendeOrderDatum = @PeriodeEindDatum;
      else
        execute immediate 'SET @volgendeOrderDatum = DateAdd(' + @DatePartFactureerPeriode + ', @AbvFactureerfrequentieAantal, @volgendeOrderDatum)';
      end if;
    END LOOP;
  END FOR; //CURSOR_Abonnementen

  set @@ErrorTextProcedure = 'AbonnementAanTeMakenOrders';
  //call TraceEind(@@ErrorTextProcedure);

  select
    AboGid,
    AbvGid,
    NawFilnummer,
    AdrNaam1,
    FactureerPeriode,
    OrderDatum,
    PeriodeBeginDatum,
    PeriodeEindDatum,
    null abvStatus,
    '' abvMelding,
    null OrkGid
  from tmpAbonnementen;

end;
//call AbonnementAanTeMakenOrders(0,'2','2',0,'1200000004','1234567890','2015-12-31');

create or replace procedure AbonnementGenereerAbonnementCode(out @AboCode nchar(20), out @AbvgAboCodeStartNummer nchar(20))
begin
  declare @NieuweAboCode    nchar(20);
  declare @GenereerAboCode  integer;    // 0 = nog niet, 1 = nieuwe abocode, 2 = niet te genereren

  set @@ErrorTextProcedure = 'AbonnementGenereerAbonnementCode > ';
  //call TraceBegin(@@ErrorTextProcedure);

  set @NieuweAboCode          = '';
  set @AboCode                = '';
  set @AbvgAboCodeStartNummer = '';
  set @GenereerAboCode        = 0;

  //Dit deel moet uniek gelocked (met een wacht-lus)
  call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'AbonnementGenereerAbonnementCode', '');


  select AbvgAboCodeStartNummer into @NieuweAboCode from tabAbonnementVastegegevens;

  if (@NieuweAboCode <> '') then
    //call TraceBegin('AbonnementGenereerAbonnementCode > Start loop');
    while @GenereerAboCode = 0 loop
      if (@AboCode = '') and (not exists (select 1 from tabAbonnementKop where AboCode=@NieuweAboCode)) then
        set @AboCode = @NieuweAboCode;
        //call Trace('AbonnementGenereerAbonnementCode > @AboCode = ' + @AboCode);
      else
        call GenereerVolgendeCode(@NieuweAboCode, @NieuweAboCode);
        if @NieuweAboCode = '' then
          set @GenereerAboCode = 2;      // Fout dus
        else
          if (@AboCode <> '') then
            set @AbvgAboCodeStartNummer = @NieuweAboCode;
            //call Trace('AbonnementGenereerAbonnementCode > @AbvgAboCodeStartNummer = ' + @AbvgAboCodeStartNummer);
          end if;
        end if;
      end if;
      //Als beide zijn opgehaald ga dan uit de loop.
      if (@AboCode <> '') and (@AbvgAboCodeStartNummer <> '') then
        set @GenereerAboCode = 1;
      end if;
    end loop;
    //call TraceEind('AbonnementGenereerAbonnementCode > Einde loop');

    if @GenereerAboCode=1 then
      //call Trace('AbonnementGenereerAbonnementCode > Updaten nieuwe AboCode in vaste gegevens, @AbvgAboCodeStartNummer = ' + @AbvgAboCodeStartNummer);
      update tabAbonnementVastegegevens set AbvgAboCodeStartNummer = @AbvgAboCodeStartNummer;
    end if;
  end if;

  //NawGenereernummers-lock weer vrijgeven
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'AbonnementGenereerAbonnementCode', '');

  set @@ErrorTextProcedure = 'AbonnementGenereerAbonnementCode';
  //call TraceEind(@@ErrorTextProcedure+ ' > @AboCode = ' + @AboCode + ', @AbvgAboCodeStartNummer = ' + @AbvgAboCodeStartNummer);
end;


create or replace procedure AbonnementKopieren
( in @AboCode               nchar(20),
  in @AboOmschrijving       nchar(40),
  in @AboNawGidDebiteur     integer,
  in @AboVtgCode            integer,
  in @AboVtgVanDeb          smallint,
  in @AboOpmerking          long nvarchar,
  in @AboAangemaaktDoor     nchar(40),
  in @AbvBegindatum         date,
  in @AbvEindDatum          date,
  in @AbvEersteOrderDatum   date,
  in @LevCondVanDeb         smallint,
  in @BtcCondVanDeb         smallint,
  in @BronAbvGid            integer,
  out @AboGid               integer
)

begin
  declare @qcLockTable       nchar(40) = 'tabAbonnementKop';
  declare @AbvGid            integer;
  declare @AbvValNummer      integer;
  declare @DebValNummer      integer;
  declare @AbvBtwStand       integer;
  declare @DebBtwStand       integer;
  declare @DebBtwCode        integer;
  declare @DebBtwPerc        numeric(6,2);
  declare @BTWAfstandsVerkopenHerberekenen smallint = 0;

  begin atomic


		// Neem vertegenwoordiger van debiteur als niet meegegevn
    if @AboVtgVanDeb = 1 then
      select NawVertegenwCode into @AboVtgCode from tabNaw where NawGid = @AboNawGidDebiteur;
    endif;

    // Controle: Indien VertegenwoordigerNummer is meegegeven, dan moet dit een bestaande vertegenwoordiger zijn
    if @AboVtgCode is not null then
      select VtgCode into @AboVtgCode from tabVertegenwoordiger where VtgCode = @AboVtgCode;
      if (@AboVtgCode is null) then
        call Raise(20700,_U('Vertegenwoordigernummer'));   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

   // Nieuwe AbonnementKop wordt toegevoegd in de database
   insert into tabAbonnementKop
           (    AboNawGidDebiteur,
                AboAangemaaktDoor,
                AboCode,
                AboOmschrijving,
                AboOpmerking,
                AboVtgCode
           )
           values
           (    @AboNawGidDebiteur,
                isnull(@AboAangemaaktDoor,''),
                @AboCode,
                isnull(@AboOmschrijving,''),
                isnull(@AboOpmerking,''),
                @AboVtgCode
           );
    set @AboGid = @@Identity;

    // Toegevoegde abonnement locken
    begin
      declare @LockResult integer;
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid, @LockResult, 0);
      if @LockResult <> 0 /*Lock gelukt*/ then
        call Raise(20741,_U('Abonnement'));   // (20741) %1! is in gebruik!
      end if;
    end;

  //Abonnementversie kopieren */
  insert into tabAbonnementVersie with auto name
  select
    @AboGid as AbvAboGid,
    1 as AbvNummer,
    @AbvBeginDatum as AbvBeginDatum,
    @AbvEindDatum as AbvEindDatum,
    isnull(@AbvEersteOrderDatum, @AbvBeginDatum) as AbvEersteOrderDatum,
//    AbvVolgendeOrderDatum,
    AbvAdrGidEindBestemming,
    AbvAdrGidVerzendAdres,
    AbvBtcNummer,
    AbvBtwStand,
    AbvContractperiodeAantal,
    AbvContractperiodePeriode,
    AbvEindAdres,
    AbvFactureerfrequentieAantal,
    AbvFactureerfrequentiePeriode,
    AbvFactuurAdres,
    AbvIsInkoopcombinatie,
    AbvLvcNummer,
    AbvNawGidFactuur,
    AbvNawGidOmzet,
    AbvNawGidPrijzen,
    AbvOpzegTermijnAantal,
    AbvOpzegTermijnPeriode,
    AbvOrderKorting,
    AbvReferentie,
    AbvTaalGid,
    AbvValNummer,
    AbvVerzendadres,
    AbvAparteFactuur,
    AbvIsDeelLeveringToegestaan,
    AbvKstdGid,
    AbvKstpGid,
    AbvOrderStatusIsGoedgekeurd,
    AbvOrderStatusIsVrijVoorFactureren,
    AbvOrderStatusIsVrijVoorLeveren,
    AbvOrderStatusIsVrijVoorVerzamellijst,
    AbvOrderVerzamellijstGebruiken
  from tabAbonnementVersie
  where AbvGid = @BronAbvGid;

  set @AbvGid = @@Identity;   //nieuw AbvGid ophalen

  select NawFilValNummer, NawFacturerenInclBtw, NawFilBtwCode  into @DebValNummer, @DebBtwStand, @DebBtwCode
         from tabNaw, tabNawFile where NawGid = @AboNawGidDebiteur and  NawFilNawGid = @AboNawGidDebiteur;

  // Als debiteur geen BtwCode heeft dan 0.0% nemen. (Regels worden niet omgerekend naar 0.0%)
  if @DebBtwCode is null  then
    set @DebBtwPerc = 0.0;
  else
    select BtwPercentage into @DebBtwPerc from tabBtw where @DebBtwCode = BtwCode;
  end if;

  // Aantal velden van debiteur overnemen
  update tabAbonnementVersie
   set AbvIsInkoopcombinatie = NawIsInkoopCombinatie,
       AbvNawGidFactuur = NawIdFactdeb,
       AbvNawGidOmzet = NawIdDebOmzet,
       AbvNawGidPrijzen = NawidDebPrijzen,
       AbvFactuurAdres = NawFactuurAdres,
       AbvVerzendadres = NawVerzendadres,
       AbvAdrGidVerzendAdres = NawGidVerzendAdres,
       AbvEindAdres = NawEindAdres,
       AbvAdrGidEindBestemming  = NawGidEindAdres,
       AbvValNummer = @DebValNummer,
       AbvBtwStand = NawFacturerenInclBtw,

       // Lever en Betalingsconditie optioneel van AboVersie of Deb
       AbvLvcNummer = case @LevCondVanDeb
                        when 0 then AbvLvcNummer
                        else NawFilLvcNummer
                      end,

       AbvBtcNummer = case @BtcCondVanDeb
                        when 0 then AbvBtcNummer
                        else NawFilBtcNummer
                      end,



       // Deellevering van debiteur of vastegeg deb.
       AbvIsDeelLeveringToegestaan = case NawIsDeelLeveringToegestaan
                                        when 2 then (select vofKopDefDeelLevering from tabVasteGegevensOrdersFactureren)
                                        else NawIsDeelLeveringToegestaan
                                      end

   from tabNaw, tabNawFile
   where abvGid = @abvGid and NawGid = @AboNawGidDebiteur and  NawFilNawGid = @AboNawGidDebiteur;

 //Abonnementregels overnemen
  insert into tabAbonnementRegel with auto name
  select
    abrAantalDecimalenVoorAantallen,
    abrAantalDecimalenVoorPrijzen,
    abrAantalOpOrder,
//    abrabrGidVolgregelMaster,
    @AbvGid as abrAbvGid,
    abrArtGid,
    abrArtPartijGid,
    abrBtwCode,
    abrIsKortingsPercentage,
    abrKorting1,
    abrKorting1BepalenBij,
    abrKorting2,
    abrKorting2BepalenBij,
    abrKostprijs,
    abrKostprijsBepalenBij,
    abrLastModified,
    abrPrijs,
    abrPrijsBepalenBij,
    abrPrijsPer,
    abrRegelNr,
    abrRegelsoort,
    abrTekstOpOrder,
    abrVolgartikelFactor
  from tabAbonnementRegel
  where tabAbonnementRegel.AbrAbvGid = @BronAbvGid;

  //Volgartikelen nog even zetten
  update tabAbonnementregel AbrDoel
  Set AbrDoel.abrabrGidVolgregelMaster = (Select abrDoelMaster.abrGid
                                from tabAbonnementregel abrDoelMaster, tabAbonnementregel abrBronMaster
                                Where abrDoelMaster.AbrRegelNr = abrBronMaster.AbrRegelNr
                                and abrDoelMaster.AbrArtGid = abrBronMaster.AbrArtgid
                                And abrDoelMaster.AbrAbvGid = @AbvGid
                                and abrBronMaster.abrGid = abrBron.abrabrGidVolgregelMaster)
  from tabAbonnementregel AbrDoel,tabAbonnementregel abrBron
  Where AbrDoel.AbrRegelnr = abrBron.AbrRegelNr
  and AbrDoel.AbrArtGid = abrBron.AbrArtgid
  And AbrDoel.AbrAbvGid = @AbvGid
  and not abrBron.abrabrGidVolgregelMaster is null
  and abrBron.AbrAbvGid = @BronAbvGid;


  // Regels omrekenen vwb valuta, btw stand en nul tarief
  select AbvValNummer, AbvBtwStand into @AbvValNummer, @AbvBtwStand from tabAbonnementVersie where AbvGid = @BronAbvGid;

  // Bij btw nul tarief prijzen indien nodig terugrekenen naar 0% en btwcode regels gelijk aan btwcode debiteur  (niet als debiteur geen btwcode heeft)
  if @DebBtwPerc = 0.0 and @DebBtwCode is not null  then
    update tabAbonnementregel
      set abrPrijs    =  if (@AbvBtwStand = 1) then round(abrPrijs/ (100 + BtwPercentage) * 100, abrAantalDecimalenVoorPrijzen) else abrPrijs end if,
          abrKorting1 = if (@AbvBtwStand = 1 and abrIsKortingsPercentage = 0) then round(abrKorting1 / (100 + BtwPercentage) * 100, abrAantalDecimalenVoorPrijzen) else abrKorting1 end if,
          abrBtwCode = @DebBtwCode
      from tabBtw
      where BtwCode = AbrBtwCode
      and   abrRegelSoort in (1,2)
      and   abrAbvGid = @AbvGid;
   end if;

  if (@DebBtwPerc <> 0.0 or @DebBtwCode is null) then
    //Als de btwstand inclusief btw is dan kijken of afstandsverkopen actief zijn
    select cast(Contents as smallint) into @BTWAfstandsVerkopenHerberekenen from tabRegistry where RegKey = 'AFSTANDSVERKOPEN';
  end if;

   // btwstand en valuta omrekenen. Bij nul btw tarief (of debiteur zonder BtwCode) alleen valuta
   call AbonnementRegelsOmrekenen(@AbvGid,
                                   if (@DebBtwPerc <> 0.0 or @DebBtwCode is null) and @AbvBtwStand <> @DebBtwStand then 1 else 0 end if,
                                   if @AbvValNummer <> @DebValNummer then 1 else 0 end if,
                                   @AbvValNummer, @BTWAfstandsVerkopenHerberekenen);

  // Vrije rubrieken kopieren
  call VrKopieerRecord('ABO',0,0,'ABO',0,0,@BronAbvGid,@AbvGid);

  // Na afloop Abonnement unlocken
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid);

  end;
end;




create or replace procedure AbonnementRegelsOmrekenen(in @AbvGid integer, in @BTWStandGewijzigd smallint, in @ValutaNummerGewijzigd smallint, in @OudValutaNummer integer, in @BTWAfstandsVerkopenHerberekenen smallint)
begin
  declare @BjGid          integer;
  declare @PerNr          integer;
  declare @BTWStand       smallint; //0 = Excl; 1 = Incl;
  declare @NieuwValNummer integer;

  set @@ErrorTextTrigger = 'AbonnementRegelsOmrekenen';
  //call TraceBegin(@@ErrorTextTrigger);

  select abvBtwStand, abvValNummer into @BTWStand,@NieuwValNummer from tabAbonnementVersie where abvGid = @abvGid;

  //Btw-stand gewijzigt? regels omrekenen
  if (isNull(@BTWStandGewijzigd,0)=1) then
    //call Trace('AbonnementRegelsOmrekenen > Abonnementregels omrekenen: btwstand is gewijzigd');

    update tabAbonnementregel
      set abrPrijs    = round((if @BtwStand <> 0 then (abrPrijs * (100 + BtwPercentage)) / 100 else (abrPrijs/ (100 + BtwPercentage)) * 100 endif), abrAantalDecimalenVoorPrijzen),
          abrKorting1 = if (abrIsKortingsPercentage = 0)  then round((if @BtwStand <> 0 then (abrKorting1 * (100 + BtwPercentage)) / 100 else (abrKorting1 / (100 + BtwPercentage)) * 100 endif), abrAantalDecimalenVoorPrijzen) else abrKorting1 endif
      from tabBtw
      where BtwCode = AbrBtwCode
      and   abrRegelSoort in (1,2)
      and   abrAbvGid = @AbvGid;
  end if;

  //Valuta wijzigt? regels omrekenen
  if (isNull(@ValutaNummerGewijzigd,0)=1) then
    //call Trace('AbonnementRegelsOmrekenen > Abonnementregels omrekenen: btwstand is gewijzigd');
    call BepaalBoekjaarEnPeriode(@@Verwerkingsdatum, @BjGid, @PerNr);

    update tabAbonnementregel
       set abrPrijs    = (if abrPrijs    <> 0 then ValutaOmrekenen(@OudValutaNummer, abrPrijs, @NieuwValNummer, @BjGid, @PerNr, abrAantalDecimalenVoorPrijzen) else abrPrijs endif),
           abrKorting1 = (if (abrIsKortingsPercentage = 0) and (abrKorting1 <> 0) then ValutaOmrekenen(@OudValutaNummer, abrKorting1, @NieuwValNummer, @BjGid, @PerNr, abrAantalDecimalenVoorPrijzen) else abrKorting1 endif)
      from tabBtw
      where BtwCode = AbrBtwCode
      and   abrRegelSoort in (1,2)
      and   abrAbvGid = @AbvGid;
  end if;

  //Afstandsverkopen herberekenen
  if (isNull(@BTWAfstandsVerkopenHerberekenen,0)=1) then
    call AbonnementUpdateBtwCodeAfstandsVerkopen(@AbvGid);
  end if;

  set @@ErrorTextTrigger = 'AbonnementRegelsOmrekenen';
  //call TraceEind(@@ErrorTextTrigger);
end;

create or replace procedure AbonnementRegelVerschuiven(
 in @AbvGid       integer,
 in @VanafRegelNr integer,   // Vanaf welk regelnummer doorschuiven (indien leeg, dan wordt 1 gebruikt!)
 in @Delta        integer    // Indien leeg, dan wordt 1 gebruikt (1 doorschuiven), maar nu kan ook worden teruggeschoven indien nodig (@delta=-1)
)
begin
  set @@ErrorTextProcedure = 'AbonnementRegelVerschuiven(@AbvGid='+string(@AbvGid)+', @VanafRegelNr='+string(@VanafRegelNr)+', @Delta='+string(@Delta)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @Delta = IsNull(@Delta, 1);
  set @VanafRegelNr = IsNull(@VanafRegelNr, 1);

  update tabAbonnementRegel
  set    abrRegelNr = abrRegelNr + @Delta
  where  abrAbvGid = @AbvGid
     and abrRegelNr >= @VanafRegelNr
  order by abrRegelNr * sign(@Delta) desc; // Bij negatief moeten we vanaf de kleinste werken, anders vanaf de grootste!

  set @@ErrorTextProcedure = 'AbonnementRegelVerschuiven(@AbvGid='+string(@AbvGid)+')';
  //call TraceEind(@@ErrorTextProcedure);
end;
//call AbonnementRegelVerschuiven(2457,4,-1);

create or replace procedure AbonnementUpdateBtwCodeAfstandsVerkopen(in @AbvGid integer)
// call AbonnementUpdateBtwCodeAfstandsVerkopen(9, 11, 166);
begin
  declare @DefaultMagazijn integer;
  declare @NewBtwCode integer;
  declare @NewBtwPerc numeric(15,3);
  declare @PrijzenHerberekenen smallint;
  declare @AbvVerzendAdres smallint;
  declare @AbvAdrGidVerzendAdres integer;
  declare @AboNawGidCorrespondentie integer;
  declare @AboNawGidVestiging integer;
  declare @FactNawGidCorrespondentie integer;
  declare @FactNawGidVestiging integer;
  declare @AfleverLndGid integer;

  select AbvgIsAfstandsVerkHerberekenenInclBtwPrijs into @PrijzenHerberekenen from tabAbonnementVasteGegevens;

  //Haal het default magazijn op
  select IsNull(( select ToeMagMagGid
                  from tabToegestaneMagazijnen
                  inner join tabGebruiker on (GebruikerGid = ToeMagGebrGid)
                  where NaamGebruiker = @@GebruikerCode and ToeMagToepassing = 10 /* Invoeren orders*/
                ), (select MagGid from tabMagazijn where MagCode='001') ) into @DefaultMagazijn;

  //Haal de verzendadres op van de abonnementsversie
  select  AbvVerzendAdres, AbvAdrGidVerzendAdres, AboNaw.NawGidCorrespondentie, AboNaw.NawGidVestiging, FactNaw.NawGidCorrespondentie, FactNaw.NawGidVestiging
    into @AbvVerzendAdres, @AbvAdrGidVerzendAdres, @AboNawGidCorrespondentie, @AboNawGidVestiging, @FactNawGidCorrespondentie, @FactNawGidVestiging
  from tabAbonnementVersie
  inner join tabAbonnementKop on AboGid = AbvAboGid
  inner join tabNaw AboNaw on AboNaw.NawGid = AboNawGidDebiteur
  left outer join tabNaw FactNaw on FactNaw.NawGid = AbvNawGidFactuur
  where  AbvGid = @AbvGid;

  //Haal het goede Afleverland op
  select AdrLndGid into @AfleverLndGid from tabAdres where AdrGid =  (case @AbvVerzendAdres
                                                                        when 0 then @aboNawGidCorrespondentie
                                                                        when 1 then @AboNawGidVestiging
                                                                        when 2 then @AbvAdrGidVerzendAdres
                                                                        when 3 then @FactNawGidCorrespondentie
                                                                        when 4 then @FactNawGidVestiging
                                                                        when 5 then @AbvAdrGidVerzendAdres
                                                                      end case);

  for @Cursor AS Cursor_AboRegels cursor for
    /* alle regels van alle versies van het abonnement ophalen */
    select AbrArtGid        @ArtGid,      	  /* om welk artikel gaat het */
	         AbrArtPartijGid  @PartijGid,       /* om welk partij gaat het */
	         AbvNawGidFactuur @NawGid,          /* om welke debiteur gaat het */
		       AbvBtwStand      @AbvBtwStand,     /* worden de prijzen incl/excl btw berekend */
           AbrBtwCode       @OldBtwCode,
           AbrGid           @AbrGid,
           BtwPercentage    @OldBtwPerc,       /* nodig om prijzen om te rekenen */
          (select AdrLndGid from tabMagazijn inner join tabAdres on MagAdrGid = AdrGid where MagGid = @DefaultMagazijn) @AbrVerzendLndGid
    from tabAbonnementRegel
	  inner join tabAbonnementVersie on AbvGid = AbrAbvGid  /* alleen de regels van de versie */
	  inner join tabBtw on AbrBtwCode = BtwCode             /* de btwgegevens die bij de regels horen */
	  where abrRegelsoort in (1,2)                          /* alleen tarieven en artikelen */
      and AbvGid = @AbvGid                           /* alleen de specifieke versie */
	  order by abrGid
    for update
    do

      /* nieuwe btwcode bepalen */
      set @NewBtwCode = GeefBtwCodeVerkoop(@NawGid, @ArtGid, @PartijGid, @AfleverLndGid, @AbrVerzendLndGid);

	    /* alleen updaten wanneer btwcode gewijzigd is */
	    if @NewBtwCode <> @OldBtwCode then
        select BtwPercentage into @NewBtwPerc from tabBtw where BtwCode = @NewBtwCode;

      if @AbvBtwStand = 0 /* exclusief btw */ or @PrijzenHerberekenen = 0 then
        update tabAbonnementRegel set AbrBtwCode = @NewBtwCode where AbrAbvGid = @AbvGid;
      else
        /* prijzen zijn inclusief btw, dus eerst de oude btw er uit en dan nieuwe btw erbij */
        update tabAbonnementRegel set
             AbrBtwCode  = @NewBtwCode,
            AbrPrijs    = round(round((AbrPrijs    / (100+@OldBtwPerc )) * 100, abrAantalDecimalenVoorPrijzen) * (100+@NewBtwPerc ) / 100, abrAantalDecimalenVoorPrijzen),
            AbrKorting1 = (if abrIsKortingsPercentage = 1 then AbrKorting1 else round(round((AbrKorting1 / (100+@OldBtwPerc )) * 100, abrAantalDecimalenVoorPrijzen) * (100+@NewBtwPerc ) / 100, abrAantalDecimalenVoorPrijzen) endif)
          where AbrGid = @AbrGid;
        end if;
      end if;
    end for;
end;





create or replace procedure AbonnementUpdateVolgArtikelen(in @AbrGId integer,in @OudeAantalOpOrder float)
begin
  declare @AantalOpOrder double;

  set @@ErrorTextProcedure = 'AbonnementUpdateVolgArtikelen >';
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select 1 from tabAbonnementRegel where (abrabrGidVolgregelMaster = @AbrGId)) then //zijn er volgartikelen voor dit artikel?
    //call Trace('Update tabAbonnementRegel');
    Select abrAantalOpOrder into @AantalOpOrder from tabAbonnementRegel where (AbrGid = @AbrGId);

    update  tabAbonnementRegel
    set     abrAantalOpOrder = round(@AantalOpOrder * abrVolgartikelFactor, abrAantalDecimalenVoorAantallen)
    where  (abrabrGidVolgregelMaster = @AbrGId)
    and abrAantalOpOrder = round(@OudeAantalOpOrder * abrVolgartikelFactor, abrAantalDecimalenVoorAantallen);
  end if;

  set @@ErrorTextProcedure = 'AbonnementUpdateVolgArtikelen';
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure AbonnementVersieBerekenMarges
(
  in  @AbvGid                                      integer,
  //Bij eerstvolgende factuur
  out @VerkoopprijsExBtwInValutaBijEerstvolgendeFactuur       numeric(15,2),
  out @VerkoopprijsExBtwInBasisvalutaBijEerstvolgendeFactuur  numeric(15,2),
  out @KostprijsExBtwInBasisvalutaBijEerstvolgendeFactuur     numeric(15,2),
  out @MargebedragExBtwInBasisvalutaBijEerstvolgendeFactuur   numeric(15,2),
  out @MargepercentageObvVerkoopprijsBijEerstvolgendeFactuur  numeric(15,2),
  out @MargepercentageObvKostprijsBijEerstvolgendeFactuur     numeric(15,2),
  //Bij nieuwe contractperiode
  out @VerkoopprijsExBtwInValutaBijNieuweContractperiode      numeric(15,2),
  out @VerkoopprijsExBtwInBasisvalutaBijNieuweContractperiode numeric(15,2),
  out @KostprijsExBtwInBasisvalutaBijNieuweContractperiode    numeric(15,2),
  out @MargebedragExBtwInBasisvalutaBijNieuweContractperiode  numeric(15,2),
  out @MargepercentageObvVerkoopprijsBijNieuweContractperiode numeric(15,2),
  out @MargepercentageObvKostprijsBijNieuweContractperiode    numeric(15,2)
)
begin
  declare @qcAantalDecTotaalbedragen     smallint      = 2;

  declare @AbvBtwStand                                        smallint;
  declare @AbvValNummer                                       integer;
  declare @AbonnementtotaalBijEerstvolgendeFactuur            numeric(15,2);
  declare @AbonnementtotaalAfgeleidBijEerstvolgendeFactuur    numeric(15,2);
  declare @AbonnementtotaalKostprijsBijEerstvolgendeFactuur   numeric(15,2);
  declare @AbonnementtotaalBijNieuweContractperiode           numeric(15,2);
  declare @AbonnementtotaalAfgeleidBijNieuweContractperiode   numeric(15,2);
  declare @AbonnementtotaalKostprijsBijNieuweContractperiode  numeric(15,2);
  declare @AbvGidBestaat                                      smallint = 0;


  set @@ErrorTextProcedure = 'AbonnementversieBerekenMarges > @AbvGid=' + string(@AbvGid);
  //call TraceBegin(@@ErrorTextProcedure);

  /* init resultaatvelden */
  set @VerkoopprijsExBtwInValutaBijEerstvolgendeFactuur       = 0;
  set @VerkoopprijsExBtwInBasisvalutaBijEerstvolgendeFactuur  = 0;
  set @KostprijsExBtwInBasisvalutaBijEerstvolgendeFactuur     = 0;
  set @MargebedragExBtwInBasisvalutaBijEerstvolgendeFactuur   = 0;
  set @MargepercentageObvVerkoopprijsBijEerstvolgendeFactuur  = 0;
  set @MargepercentageObvKostprijsBijEerstvolgendeFactuur     = 0;

  set @VerkoopprijsExBtwInValutaBijNieuweContractperiode      = 0;
  set @VerkoopprijsExBtwInBasisvalutaBijNieuweContractperiode = 0;
  set @KostprijsExBtwInBasisvalutaBijNieuweContractperiode    = 0;
  set @MargebedragExBtwInBasisvalutaBijNieuweContractperiode  = 0;
  set @MargepercentageObvVerkoopprijsBijNieuweContractperiode = 0;
  set @MargepercentageObvKostprijsBijNieuweContractperiode    = 0;

  //benodigde gegevens van Abonnementversie ophalen
  select 1, abvBtwStand, abvValNummer,
  AbonnementtotaalBijEerstvolgendeFactuur, AbonnementtotaalAfgeleidBijEerstvolgendeFactuur, AbonnementtotaalKostprijsBijEerstvolgendeFactuur,
  AbonnementtotaalBijNieuweContractperiode, AbonnementtotaalAfgeleidBijNieuweContractperiode, AbonnementtotaalKostprijsBijNieuweContractperiode
  into @abvGidBestaat, @abvBtwStand, @abvValNummer,
  @AbonnementtotaalBijEerstvolgendeFactuur, @AbonnementtotaalAfgeleidBijEerstvolgendeFactuur, @AbonnementtotaalKostprijsBijEerstvolgendeFactuur,
  @AbonnementtotaalBijNieuweContractperiode, @AbonnementtotaalAfgeleidBijNieuweContractperiode, @AbonnementtotaalKostprijsBijNieuweContractperiode
  from tabAbonnementVersie ,
  AbonnementversieBerekenTotalen(@abvGid)
  where abvGid = @abvGid;

  /* marges berekenen als de offerteversie gevonden is */
  if @abvGidBestaat = 1 then
    set @VerkoopprijsExBtwInValutaBijEerstvolgendeFactuur = if (@abvBtwStand = 1) then @AbonnementtotaalAfgeleidBijEerstvolgendeFactuur else @AbonnementtotaalBijEerstvolgendeFactuur endif;

    if (@abvValNummer <> @@BasisValutaNummer) and (@VerkoopprijsExBtwInValutaBijEerstvolgendeFactuur <> 0) then
      begin
        declare @BjGid integer;
        declare @PerNr integer;

        call BepaalBoekjaarEnPeriode(@@Verwerkingsdatum, @BjGid, @PerNr);
        set @VerkoopprijsExBtwInBasisvalutaBijEerstvolgendeFactuur = ValutaOmrekenen(@abvValNummer, @VerkoopprijsExBtwInValutaBijEerstvolgendeFactuur, @@BasisValutaNummer, @BjGid, @PerNr, @qcAantalDecTotaalbedragen);
      end;
    else
      set @VerkoopprijsExBtwInBasisvalutaBijEerstvolgendeFactuur = @VerkoopprijsExBtwInValutaBijEerstvolgendeFactuur;
    end if;


    set @KostprijsExBtwInBasisvalutaBijEerstvolgendeFactuur   = @AbonnementtotaalKostprijsBijEerstvolgendeFactuur; //de kostprijs is altijd ex btw en in basisvaluta, dus hoeft niet afh van btwstand berekend te worden.
    set @MargebedragExBtwInBasisvalutaBijEerstvolgendeFactuur = @VerkoopprijsExBtwInBasisvalutaBijEerstvolgendeFactuur - @KostprijsExBtwInBasisvalutaBijEerstvolgendeFactuur;

    /* MargepercentageObvVerkoopprijsBijEerstvolgendeFactuur berekenen */
    if (@VerkoopprijsExBtwInBasisvalutaBijEerstvolgendeFactuur = 0) then
      if (@KostprijsExBtwInBasisvalutaBijEerstvolgendeFactuur = 0) then /* indien 0 */
        set @MargepercentageObvVerkoopprijsBijEerstvolgendeFactuur = 0;
      else /* groter dan 0 (kleiner dan 0 kan niet, we staan geen negatieve prijzen in offertes toe) */
        set @MargepercentageObvVerkoopprijsBijEerstvolgendeFactuur = -100;
      end if;
    else
      set @MargepercentageObvVerkoopprijsBijEerstvolgendeFactuur = round((@MargebedragExBtwInBasisvalutaBijEerstvolgendeFactuur / @VerkoopprijsExBtwInBasisvalutaBijEerstvolgendeFactuur) * 100, @qcAantalDecTotaalbedragen);
    end if;


    /* MargepercentageObvKostprijsBijEerstvolgendeFactuur berekenen */
    if (@KostprijsExBtwInBasisvalutaBijEerstvolgendeFactuur = 0) then
      if (@VerkoopprijsExBtwInBasisvalutaBijEerstvolgendeFactuur = 0) then /* indien 0 */
        set @MargepercentageObvKostprijsBijEerstvolgendeFactuur = 0;
      else /* groter dan 0 (kleiner dan 0 kan niet, we staan geen negatieve prijzen in offertes toe) */
        set @MargepercentageObvKostprijsBijEerstvolgendeFactuur = 100;
      end if;
    else
      set @MargepercentageObvKostprijsBijEerstvolgendeFactuur = round((@MargebedragExBtwInBasisvalutaBijEerstvolgendeFactuur / @KostprijsExBtwInBasisvalutaBijEerstvolgendeFactuur) * 100, @qcAantalDecTotaalbedragen);
    end if;
  end if;

/* marges berekenen als de offerteversie gevonden is */
  if @abvGidBestaat = 1 then
    set @VerkoopprijsExBtwInValutaBijNieuweContractperiode = if (@abvBtwStand = 1) then @AbonnementtotaalAfgeleidBijNieuweContractperiode else @AbonnementtotaalBijNieuweContractperiode endif;

    if (@abvValNummer <> @@BasisValutaNummer) and (@VerkoopprijsExBtwInValutaBijNieuweContractperiode <> 0) then
      begin
        declare @BjGid integer;
        declare @PerNr integer;

        call BepaalBoekjaarEnPeriode(@@Verwerkingsdatum, @BjGid, @PerNr);
        set @VerkoopprijsExBtwInBasisvalutaBijNieuweContractperiode = ValutaOmrekenen(@abvValNummer, @VerkoopprijsExBtwInValutaBijNieuweContractperiode, @@BasisValutaNummer, @BjGid, @PerNr, @qcAantalDecTotaalbedragen);
      end;
    else
      set @VerkoopprijsExBtwInBasisvalutaBijNieuweContractperiode = @VerkoopprijsExBtwInValutaBijNieuweContractperiode;
    end if;


    set @KostprijsExBtwInBasisvalutaBijNieuweContractperiode   = @AbonnementtotaalKostprijsBijNieuweContractperiode; //de kostprijs is altijd ex btw en in basisvaluta, dus hoeft niet afh van btwstand berekend te worden.
    set @MargebedragExBtwInBasisvalutaBijNieuweContractperiode = @VerkoopprijsExBtwInBasisvalutaBijNieuweContractperiode - @KostprijsExBtwInBasisvalutaBijNieuweContractperiode;

    /* MargepercentageObvVerkoopprijsBijNieuweContractperiode berekenen */
    if (@VerkoopprijsExBtwInBasisvalutaBijNieuweContractperiode = 0) then
      if (@KostprijsExBtwInBasisvalutaBijNieuweContractperiode = 0) then /* indien 0 */
        set @MargepercentageObvVerkoopprijsBijNieuweContractperiode = 0;
      else /* groter dan 0 (kleiner dan 0 kan niet, we staan geen negatieve prijzen in offertes toe) */
        set @MargepercentageObvVerkoopprijsBijNieuweContractperiode = -100;
      end if;
    else
      set @MargepercentageObvVerkoopprijsBijNieuweContractperiode = round((@MargebedragExBtwInBasisvalutaBijNieuweContractperiode / @VerkoopprijsExBtwInBasisvalutaBijNieuweContractperiode) * 100, @qcAantalDecTotaalbedragen);
    end if;


    /* MargepercentageObvKostprijsBijNieuweContractperiode berekenen */
    if (@KostprijsExBtwInBasisvalutaBijNieuweContractperiode = 0) then
      if (@VerkoopprijsExBtwInBasisvalutaBijNieuweContractperiode = 0) then /* indien 0 */
        set @MargepercentageObvKostprijsBijNieuweContractperiode = 0;
      else /* groter dan 0 (kleiner dan 0 kan niet, we staan geen negatieve prijzen in offertes toe) */
        set @MargepercentageObvKostprijsBijNieuweContractperiode = 100;
      end if;
    else
      set @MargepercentageObvKostprijsBijNieuweContractperiode = round((@MargebedragExBtwInBasisvalutaBijNieuweContractperiode / @KostprijsExBtwInBasisvalutaBijNieuweContractperiode) * 100, @qcAantalDecTotaalbedragen);
    end if;
  end if;
  set @@ErrorTextProcedure = 'AbonnementversieBerekenMarges > @AbvGid=' + string(@AbvGid);
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure AbonnementversieBerekenTotalen(in @AbvGid integer)
result (
  //Totalen obv prijzen bij eerstvolgende factuur
  BtwRegelsBtwDeelTotaalBijEerstvolgendeFactuur       numeric(15,2),
  AbonnementtotaalBijEerstvolgendeFactuur             numeric(15,2),
  AbonnementtotaalAfgeleidBijEerstvolgendeFactuur     numeric(15,2),
  AbonnementtotaalBrutoBijEerstvolgendeFactuur        numeric(15,2),
  AbonnementtotaalNettoBijEerstvolgendeFactuur        numeric(15,2),
  AbonnementOrderKortingBijEerstvolgendeFactuur       numeric(15,2),
  AbonnementtotaalKorting1DeelBijEerstvolgendeFactuur numeric(15,2),
  AbonnementtotaalKorting2DeelBijEerstvolgendeFactuur numeric(15,2),
  AbonnementtotaalKostprijsBijEerstvolgendeFactuur    numeric(15,2),
  //Totalen obv prijzen bij nieuwe contractperiode
  BtwRegelsBtwDeelTotaalBijNieuweContractperiode       numeric(15,2),
  AbonnementtotaalBijNieuweContractperiode             numeric(15,2),
  AbonnementtotaalAfgeleidBijNieuweContractperiode     numeric(15,2),
  AbonnementtotaalBrutoBijNieuweContractperiode        numeric(15,2),
  AbonnementtotaalNettoBijNieuweContractperiode        numeric(15,2),
  AbonnementOrderKortingBijNieuweContractperiode       numeric(15,2),
  AbonnementtotaalKorting1DeelBijNieuweContractperiode numeric(15,2),
  AbonnementtotaalKorting2DeelBijNieuweContractperiode numeric(15,2),
  AbonnementtotaalKostprijsBijNieuweContractperiode    numeric(15,2)
)
begin
  /* variabelen */
  declare @AbvBtwStand                                    smallint;
  declare @AbvOrderKorting                                numeric(15,2) = 0;
  declare @NawGid                                         integer;
  declare @AbvValNummer                                   integer;
  //declare @BtwRegelsBtwDeelTotaal numeric(15,2) = 0;
  declare @BtwRegelsBtwDeelTotaalBijEerstvolgendeFactuur  numeric(15,2) = 0;
  declare @BtwRegelsBtwDeelTotaalBijNieuweContractperiode numeric(15,2) = 0;

  //Totalen obv prijzen bij eerstvolgende factuur
  declare @AbonnementtotaalBijEerstvolgendeFactuur              numeric(15,2) = 0;
  declare @AbonnementtotaalAfgeleidBijEerstvolgendeFactuur      numeric(15,2) = 0;
  declare @AbonnementtotaalBrutoBijEerstvolgendeFactuur         numeric(15,2) = 0;
  declare @AbonnementtotaalNettoBijEerstvolgendeFactuur         numeric(15,2) = 0;
  declare @AbonnementOrderKortingBijEerstvolgendeFactuur        numeric(15,2) = 0;
  declare @AbonnementtotaalKorting1DeelBijEerstvolgendeFactuur  numeric(15,2) = 0;
  declare @AbonnementtotaalKorting2DeelBijEerstvolgendeFactuur  numeric(15,2) = 0;
  declare @AbonnementtotaalKostprijsBijEerstvolgendeFactuur     numeric(15,2) = 0;
  //Totalen obv prijzen bij nieuwe contractperiode
  declare @AbonnementtotaalBijNieuweContractperiode             numeric(15,2) = 0;
  declare @AbonnementtotaalAfgeleidBijNieuweContractperiode     numeric(15,2) = 0;
  declare @AbonnementtotaalBrutoBijNieuweContractperiode        numeric(15,2) = 0;
  declare @AbonnementtotaalNettoBijNieuweContractperiode        numeric(15,2) = 0;
  declare @AbonnementOrderKortingBijNieuweContractperiode       numeric(15,2) = 0;
  declare @AbonnementtotaalKorting1DeelBijNieuweContractperiode numeric(15,2) = 0;
  declare @AbonnementtotaalKorting2DeelBijNieuweContractperiode numeric(15,2) = 0;
  declare @AbonnementtotaalKostprijsBijNieuweContractperiode    numeric(15,2) = 0;

  //Vaste gegevens Orders
  declare @vofIsStuksKorting    smallint;
  declare @GebruikOrderkorting  smallint;
  declare @NawOrderKorting      numeric(6,2);

  //Prijsafspraak variabelen
  declare @DummyChar              nchar(3); //dummy voor parameters die je niet gebruikt
  declare @DummyInt               integer;  //dummy voor parameters die je niet gebruikt
  declare @PraKortingsoort        smallint;
  declare @PraVerkoopPrijs        numeric(15,3);
  declare @PraKortingsPercentage  numeric(6,2);
  declare @PraKortingsBedrag      numeric(15,3);

  //De prijzen variabelen
  declare @abrKostprijsBijEerstvolgendeFactuur  numeric(15,3);
  declare @abrKostprijsBijNieuweContractperiode numeric(15,3);
  declare @abrPrijsBijEerstvolgendeFactuur      numeric(15,3);
  declare @abrPrijsBijNieuweContractperiode     numeric(15,3);
  declare @abrKorting1BijEerstvolgendeFactuur   numeric(15,3);
  declare @abrKorting1BijNieuweContractperiode  numeric(15,3);
  declare @abrKorting2BijEerstvolgendeFactuur   numeric(15,3);
  declare @abrKorting2BijNieuweContractperiode  numeric(15,3);

  declare local temporary table tmpAbonnementTotaal
  ( tmpGid                                                  integer default autoincrement,
    //Totalen obv prijzen bij eerstvolgende factuur
    tmpAbonnementtotaalBijEerstvolgendeFactuur              numeric(15,2),
    tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur         numeric(15,2),
    tmpAbonnementtotaalKorting1DeelBijEerstvolgendeFactuur  numeric(15,2),
    tmpAbonnementtotaalKorting2DeelBijEerstvolgendeFactuur  numeric(15,2),
    tmpAbonnementtotaalKostprijsBijEerstvolgendeFactuur     numeric(15,2),
    //Totalen obv prijzen bij nieuwe contractperiode
    tmpAbonnementtotaalBijNieuweContractperiode             numeric(15,2),
    tmpAbonnementtotaalBrutoBijNieuweContractperiode        numeric(15,2),
    tmpAbonnementtotaalKorting1DeelBijNieuweContractperiode numeric(15,2),
    tmpAbonnementtotaalKorting2DeelBijNieuweContractperiode numeric(15,2),
    tmpAbonnementtotaalKostprijsBijNieuweContractperiode    numeric(15,2)
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'AbonnementversieBerekenTotalen > @AbvGid=' + string(@AbvGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select AbvBtwStand, abvOrderKorting, AbvValNummer, (if AbvNawGidPrijzen is null then AboNawGidDebiteur else AbvNawGidPrijzen endif)
    into @AbvBTWStand, @AbvOrderKorting, @AbvValNummer, @NawGid
  from tabAbonnementVersie
  inner join tabAbonnementKop on AboGid = AbvAboGid
  where AbvGid = @AbvGid;

  select first vofIsStuksKorting, vofOrderKortingSoort into @vofIsStuksKorting, @GebruikOrderkorting from tabVasteGegevensOrdersFactureren;

  if (@GebruikOrderkorting = 2) then
    // Orderkorting als regelkorting 2 opnemen
    select (if NawFilWelkeOrderKorting = 1 then DebGrpOrderKorting else NawOrderKorting endif) into @NawOrderKorting
    from tabNaw
    inner join tabNawFile on NawFilNawGid = NawGid and NawFilFonId = 'D'
    inner join tabDebiteurGroepen on NawFilDebGrpGid = DebGrpGid
    where NawFilNawGid = IsNull(null, @NawGid);
  end if;

  //Open een cursor om de prijzen te bepalen
  for @Cursor AS CURSOR_BepaalPrijzen CURSOR FOR
    select
      AbrGid                  @AbrGid,
      abrArtGid               @ArtGid,
      abrBtwCode              @BtwCode,
      BtwPercentage           @BTWPercentage,
      if (abrAantalOpOrder=0) then 1 else abrAantalOpOrder endif  @AantalOpOrder,
      abrArtPartijGid         @AbrArtPartijGid,
      abrPrijsPer             @abrPrijsPer,
      abrPrijs                @abrPrijs,
      abrKostprijs            @abrKostprijs,
      abrIsKortingsPercentage @abrIsKortingsPercentage,
      abrKorting1             @abrKorting1,
      abrKorting2             @abrKorting2,
      abrPrijsBepalenBij      @PrijsBepalenBij,
      abrKostprijsBepalenBij  @KostprijsBepalenBij,
      abrKorting1BepalenBij   @Korting1BepalenBij,
      abrKorting2BepalenBij   @Korting2BepalenBij,
      (if (ArtIsPartijAparteKostPrijs=1) and not (ArtPartijGid is null) then ArtPartijKostprijsEx else ArtKostprijsEx endif) @ArtKostPrijs
    from
      tabAbonnementRegel
      inner join tabBtw on (BtwCode=AbrBtwCode)
      inner join tabartikel on artgid = abrArtGid
      left outer join tabartikelPartij on ArtPartijArtGid = abrArtGid and ArtPartijGid = abrArtPartijGid
//      inner join tabAbonnementVersie on (AbvGid=tmpAbvGid)
//      inner join tabBtw on (BtwCode=tmpBtwCode),
//      tabVasteGegevensOrdersFactureren
//    order by abrBtwCode, BtwPercentage
    where abrAbvGid = @AbvGid
    and   abrRegelsoort in (1,2) //alleen de artikel- en tariefregels.
    order by abrBtwCode, BtwPercentage
    for read only
    do
      if isNull(@abrPrijsPer,0) = 0 then
        set @abrPrijsPer = 1;
      end if;
      //Haal de nieuwe prijzen op voor het betreffende artikel
      call BepaalPrijsAfspraak(@NawGid,@ArtGid,Null,Null,Null,@AbrArtPartijGid,@AbvBtwStand,@AbvValNummer,@AantalOpOrder,@AantalOpOrder,@@BasisValutaNummer, @@BasisValutaCode, @@VerwerkingsDatum,
                                    @DummyInt,@DummyInt,@DummyInt,@DummyChar,@PraVerkoopPrijs,@PraKortingsoort, @PraKortingsPercentage,@PraKortingsBedrag,@DummyInt,@DummyInt,@DummyInt);

      //Kostprijs
      set @abrKostprijsBijEerstvolgendeFactuur  = if (@KostprijsBepalenBij=2) then @ArtKostPrijs    else @abrKostPrijs endif; //wijzigen als het per factuurperiode is
      set @abrKostprijsBijNieuweContractperiode = if (@KostprijsBepalenBij=1) then @ArtKostPrijs    else @abrKostprijsBijEerstvolgendeFactuur endif; //wijzigen als het per contractperiode is
      //Prijs
      set @abrPrijsBijEerstvolgendeFactuur      = if (@PrijsBepalenBij=2) then @PraVerkoopPrijs else @abrPrijs endif; //wijzigen als het per factuurperiode is
      set @abrPrijsBijNieuweContractperiode     = if (@PrijsBepalenBij=1) then @PraVerkoopPrijs else @abrPrijsBijEerstvolgendeFactuur endif; //wijzigen als het per contractperiode is

      //korting1
      set @abrKorting1BijEerstvolgendeFactuur   = if (@Korting1BepalenBij=2) then
                                                    if (@PraKortingsoort = 1) then @PraKortingsPercentage else isNull(@PraKortingsBedrag,0) endif
                                                  else
                                                    @abrKorting1
                                                  endif; //wijzigen als het per factuurperiode is
      set @abrKorting1BijNieuweContractperiode  = if (@Korting1BepalenBij=1) then
                                                    if (@PraKortingsoort = 1) then @PraKortingsPercentage else isNull(@PraKortingsBedrag,0) endif
                                                  else
                                                    @abrKorting1BijEerstvolgendeFactuur
                                                  endif; //wijzigen als het per contractperiode is

      //korting2
      set @abrKorting2BijEerstvolgendeFactuur   = if (@Korting2BepalenBij=2) then
                                                    if (@GebruikOrderkorting = 2) then @NawOrderKorting else 0 endif
                                                  else
                                                    @abrKorting2
                                                  endif; //wijzigen als het per factuurperiode is
      set @abrKorting2BijNieuweContractperiode  = if (@Korting2BepalenBij=1) then
                                                    if (@GebruikOrderkorting = 2) then @NawOrderKorting else 0 endif
                                                  else
                                                    @abrKorting2BijEerstvolgendeFactuur
                                                  endif; //wijzigen als het per factuurperiode is




  /* ABONNEMENTVERSIETOTALEN BEREKENEN */
  insert into tmpAbonnementTotaal
  (
    tmpAbonnementtotaalBijEerstvolgendeFactuur, tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur, tmpAbonnementtotaalKorting1DeelBijEerstvolgendeFactuur,
    tmpAbonnementtotaalKorting2DeelBijEerstvolgendeFactuur, tmpAbonnementtotaalKostprijsBijEerstvolgendeFactuur,
    tmpAbonnementtotaalBijNieuweContractperiode, tmpAbonnementtotaalBrutoBijNieuweContractperiode, tmpAbonnementtotaalKorting1DeelBijNieuweContractperiode,
    tmpAbonnementtotaalKorting2DeelBijNieuweContractperiode, tmpAbonnementtotaalKostprijsBijNieuweContractperiode
  )
  Select
      Round((
        if @vofIsStuksKorting=0 then
          if @abrIsKortingsPercentage=1 then
            (((@abrPrijsBijEerstvolgendeFactuur/@AbrPrijsPer) * (100 - @abrKorting1BijEerstvolgendeFactuur) / 100) * (100 - @abrKorting2BijEerstvolgendeFactuur) / 100) * @AantalOpOrder
          else
            (((@abrPrijsBijEerstvolgendeFactuur/@AbrPrijsPer) * @AantalOpOrder) - (@abrKorting1BijEerstvolgendeFactuur)) * (100 - @abrKorting2BijEerstvolgendeFactuur) / 100
          endif
        else
          if @abrIsKortingsPercentage=1 then
            (((@abrPrijsBijEerstvolgendeFactuur/@AbrPrijsPer) * @AantalOpOrder) * (100 - @abrKorting1BijEerstvolgendeFactuur) / 100) * (100 - @abrKorting2BijEerstvolgendeFactuur) / 100
          else
            (((@abrPrijsBijEerstvolgendeFactuur/@AbrPrijsPer) * @AantalOpOrder) - (@abrKorting1BijEerstvolgendeFactuur * @AantalOpOrder)) * (100 - @abrKorting2BijEerstvolgendeFactuur) / 100
          endif
        endif
      ),2) as tmpAbonnementtotaalBijEerstvolgendeFactuur,
      round(((@abrPrijsBijEerstvolgendeFactuur/@AbrPrijsPer) * @AantalOpOrder),2) as tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur,
      round((
      if @vofIsStuksKorting=0 then
        if IsNull(@abrKorting2BijEerstvolgendeFactuur,0) <> 0 then
          if @AbrIsKortingsPercentage=1 then
            round(tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur * @abrKorting1BijEerstvolgendeFactuur / 100, 2) //ACW 16-08-2011: REGELkorting altijd in aantal decimalen van de regel
          else
            @abrKorting1BijEerstvolgendeFactuur
          endif
        else
          tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur - tmpAbonnementtotaalBijEerstvolgendeFactuur
        endif
      else
        if IsNull(@abrKorting2BijEerstvolgendeFactuur,0) <> 0 then
          if @abrIsKortingsPercentage=1 then
            tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur * @abrKorting1BijEerstvolgendeFactuur / 100
          else
            (@abrKorting1BijEerstvolgendeFactuur * @AantalOpOrder)
          endif
        else
          tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur - tmpAbonnementtotaalBijEerstvolgendeFactuur
        endif
      endif),2) as tmpAbonnementtotaalKorting1DeelBijEerstvolgendeFactuur,
      tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur-tmpAbonnementtotaalBijEerstvolgendeFactuur-tmpAbonnementtotaalKorting1DeelBijEerstvolgendeFactuur as tmpAbonnementtotaalKorting2DeelBijEerstvolgendeFactuur,
      (@AantalOpOrder * (@abrKostprijsBijEerstvolgendeFactuur/@AbrPrijsPer)) as tmpAbonnementtotaalKostprijsBijEerstvolgendeFactuur,
      Round((
        if @vofIsStuksKorting=0 then
          if @abrIsKortingsPercentage=1 then
            (((@abrPrijsBijNieuweContractperiode/@AbrPrijsPer) * (100 - @abrKorting1BijNieuweContractperiode) / 100) * (100 - @abrKorting2BijNieuweContractperiode) / 100) * @AantalOpOrder
          else
            ((((@abrPrijsBijNieuweContractperiode/@AbrPrijsPer) * @AantalOpOrder) - @abrKorting1BijNieuweContractperiode) * (100 - @abrKorting2BijNieuweContractperiode) / 100)
          endif
        else
          if @abrIsKortingsPercentage=1 then
            (((@abrPrijsBijNieuweContractperiode/@AbrPrijsPer) * @AantalOpOrder) * (100 - @abrKorting1BijNieuweContractperiode) / 100) * (100 - @abrKorting2BijNieuweContractperiode) / 100
          else
            (((@abrPrijsBijNieuweContractperiode/@AbrPrijsPer) * @AantalOpOrder) - (@abrKorting1BijNieuweContractperiode * @AantalOpOrder)) * (100 - @abrKorting2BijNieuweContractperiode) / 100
          endif
        endif
      ),2) as tmpAbonnementtotaalBijNieuweContractperiode,
      round(((@abrPrijsBijNieuweContractperiode/@AbrPrijsPer) * @AantalOpOrder),2) as tmpAbonnementtotaalBrutoBijNieuweContractperiode,
      round((
      if @vofIsStuksKorting=0 then
        if IsNull(@abrKorting2BijNieuweContractperiode,0) <> 0 then
          if @AbrIsKortingsPercentage=1 then
            round(tmpAbonnementtotaalBrutoBijNieuweContractperiode * @abrKorting1BijNieuweContractperiode / 100, 2) //ACW 16-08-2011: REGELkorting altijd in aantal decimalen van de regel
          else
            @abrKorting1BijNieuweContractperiode
          endif
        else
          tmpAbonnementtotaalBrutoBijNieuweContractperiode - tmpAbonnementtotaalBijNieuweContractperiode
        endif
      else
        if IsNull(@abrKorting2BijNieuweContractperiode,0) <> 0 then
          if @AbrIsKortingsPercentage=1 then
            tmpAbonnementtotaalBrutoBijNieuweContractperiode * @abrKorting1BijNieuweContractperiode / 100
          else
            (@abrKorting1BijNieuweContractperiode * @AantalOpOrder)
          endif
        else
          tmpAbonnementtotaalBrutoBijNieuweContractperiode - tmpAbonnementtotaalBijNieuweContractperiode
        endif
      endif),2) as tmpAbonnementtotaalKorting1DeelBijNieuweContractperiode,
      tmpAbonnementtotaalBrutoBijNieuweContractperiode-tmpAbonnementtotaalBijNieuweContractperiode-tmpAbonnementtotaalKorting1DeelBijNieuweContractperiode as tmpAbonnementtotaalKorting2DeelBijNieuweContractperiode,
      (@AantalOpOrder * (@abrKostprijsBijNieuweContractperiode/@AbrPrijsPer)) as tmpAbonnementtotaalKostprijsBijNieuweContractperiode

  end for;

  //De totalen van de BTW regels
  //set @BtwRegelsBtwDeelTotaalBijEerstvolgendeFactuur = IsNull((select sum(BedragBtwDeelBijEerstvolgendeFactuur) from AbonnementVersieBTWRegels(@AbvGid)), 0);
  //set @BtwRegelsBtwDeelTotaalBijNieuweContractperiode = IsNull((select sum(BedragBtwDeelBijNieuweContractperiode) from AbonnementVersieBTWRegels(@AbvGid)), 0);
  select sum(BedragBtwDeelBijEerstvolgendeFactuur), sum(BedragBtwDeelBijNieuweContractperiode)
  into @BtwRegelsBtwDeelTotaalBijEerstvolgendeFactuur, @BtwRegelsBtwDeelTotaalBijNieuweContractperiode
  from AbonnementVersieBTWRegels(@AbvGid);

  //Alles bij elkaar optellen
  select sum(tmpAbonnementtotaalBijEerstvolgendeFactuur), sum(tmpAbonnementtotaalBrutoBijEerstvolgendeFactuur), sum(tmpAbonnementtotaalKorting1DeelBijEerstvolgendeFactuur),
  sum(tmpAbonnementtotaalKorting2DeelBijEerstvolgendeFactuur), sum(tmpAbonnementtotaalKostprijsBijEerstvolgendeFactuur),
  sum(tmpAbonnementtotaalBijNieuweContractperiode), sum(tmpAbonnementtotaalBrutoBijNieuweContractperiode), sum(tmpAbonnementtotaalKorting1DeelBijNieuweContractperiode),
  sum(tmpAbonnementtotaalKorting2DeelBijNieuweContractperiode), sum(tmpAbonnementtotaalKostprijsBijNieuweContractperiode)
  into @AbonnementtotaalBijEerstvolgendeFactuur, @AbonnementtotaalBrutoBijEerstvolgendeFactuur, @AbonnementtotaalKorting1DeelBijEerstvolgendeFactuur,
  @AbonnementtotaalKorting2DeelBijEerstvolgendeFactuur, @AbonnementtotaalKostprijsBijEerstvolgendeFactuur,
  @AbonnementtotaalBijNieuweContractperiode, @AbonnementtotaalBrutoBijNieuweContractperiode, @AbonnementtotaalKorting1DeelBijNieuweContractperiode,
  @AbonnementtotaalKorting2DeelBijNieuweContractperiode, @AbonnementtotaalKostprijsBijNieuweContractperiode
  from tmpAbonnementTotaal;

  set @AbonnementtotaalNettoBijEerstvolgendeFactuur = @AbonnementtotaalBijEerstvolgendeFactuur;
  set @AbonnementtotaalNettoBijNieuweContractperiode = @AbonnementtotaalBijNieuweContractperiode;

  if @AbvOrderKorting<>0 then
    set @AbonnementOrderKortingBijEerstvolgendeFactuur = (@AbonnementtotaalBijEerstvolgendeFactuur / 100) * @AbvOrderKorting;
    set @AbonnementtotaalBijEerstvolgendeFactuur       = (@AbonnementtotaalBijEerstvolgendeFactuur - @AbonnementOrderKortingBijEerstvolgendeFactuur);
    set @AbonnementOrderKortingBijNieuweContractperiode = (@AbonnementtotaalBijNieuweContractperiode / 100) * @AbvOrderKorting;
    set @AbonnementtotaalBijNieuweContractperiode       = (@AbonnementtotaalBijNieuweContractperiode - @AbonnementOrderKortingBijNieuweContractperiode);
  end if;

  set @AbonnementtotaalAfgeleidBijEerstvolgendeFactuur = if (@AbvBtwStand = 1) then /* incl btw */
                                    @AbonnementtotaalBijEerstvolgendeFactuur - @BtwRegelsBtwDeelTotaalBijEerstvolgendeFactuur /* Abonnementtotaal is incl btw, dus btwdeel eraf */
                                  else
                                    @AbonnementtotaalBijEerstvolgendeFactuur + @BtwRegelsBtwDeelTotaalBijEerstvolgendeFactuur /* Abonnementtotaal is excl btw, dus btwdeel erbij */
                                  end if;

  set @AbonnementtotaalAfgeleidBijNieuweContractperiode = if (@AbvBtwStand = 1) then /* incl btw */
                                    @AbonnementtotaalBijNieuweContractperiode - @BtwRegelsBtwDeelTotaalBijNieuweContractperiode /* Abonnementtotaal is incl btw, dus btwdeel eraf */
                                  else
                                    @AbonnementtotaalBijNieuweContractperiode + @BtwRegelsBtwDeelTotaalBijNieuweContractperiode /* Abonnementtotaal is excl btw, dus btwdeel erbij */
                                  end if;

  select
    @BtwRegelsBtwDeelTotaalBijEerstvolgendeFactuur,
    @AbonnementtotaalBijEerstvolgendeFactuur,
    @AbonnementtotaalAfgeleidBijEerstvolgendeFactuur,
    @AbonnementtotaalBrutoBijEerstvolgendeFactuur,
    @AbonnementtotaalNettoBijEerstvolgendeFactuur,
    @AbonnementOrderKortingBijEerstvolgendeFactuur,
    @AbonnementtotaalKorting1DeelBijEerstvolgendeFactuur,
    @AbonnementtotaalKorting2DeelBijEerstvolgendeFactuur,
    @AbonnementtotaalKostprijsBijEerstvolgendeFactuur,
    @BtwRegelsBtwDeelTotaalBijNieuweContractperiode,
    @AbonnementtotaalBijNieuweContractperiode,
    @AbonnementtotaalAfgeleidBijNieuweContractperiode,
    @AbonnementtotaalBrutoBijNieuweContractperiode,
    @AbonnementtotaalNettoBijNieuweContractperiode,
    @AbonnementOrderKortingBijNieuweContractperiode,
    @AbonnementtotaalKorting1DeelBijNieuweContractperiode,
    @AbonnementtotaalKorting2DeelBijNieuweContractperiode,
    @AbonnementtotaalKostprijsBijNieuweContractperiode;

  set @@ErrorTextProcedure = 'AbonnementversieBerekenTotalen';
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure AbonnementversieBTWRegels(in @AbvGid integer)
result (
  BtwCode                                           integer,
  BtwPercentage                                     numeric(15,2),
  //Totalen obv prijzen bij eerstvolgende factuur
  RegeltotaalExRegelKortingBijEerstvolgendeFactuur  numeric(15,2),
  orderkortingBijEerstvolgendeFactuur               numeric(15,2),
  RegeltotaalBijEerstvolgendeFactuur                numeric(15,2),
  BedragBtwDeelBijEerstvolgendeFactuur              numeric(15,2),
  BedragBtwGrondslagBijEerstvolgendeFactuur         numeric(15,2),
  //Totalen obv prijzen bij nieuwe contractperiode
  RegeltotaalExRegelKortingBijNieuweContractperiode numeric(15,2),
  orderkortingBijNieuweContractperiode              numeric(15,2),
  RegeltotaalBijNieuweContractperiode               numeric(15,2),
  BedragBtwDeelBijNieuweContractperiode             numeric(15,2),
  BedragBtwGrondslagBijNieuweContractperiode        numeric(15,2)
)
begin
  declare @NawGid           integer;
  declare @AbvBtwStand      smallint;
  declare @AbvOrderKorting  numeric(15,3);
  declare @AbvValNummer     integer;

  //Vaste gegevens Orders
  declare @vofIsStuksKorting    smallint;
  declare @GebruikOrderkorting  smallint;

  //Prijsafspraak variabelen
  declare @DummyChar              nchar(3); //dummy voor parameters die je niet gebruikt
  declare @DummyInt               integer;  //dummy voor parameters die je niet gebruikt
  declare @PraVerkoopPrijs        numeric(15,3);
  declare @PraKortingsoort        smallint;
  declare @PraKortingsPercentage  numeric(6,2);
  declare @PraKortingsBedrag      numeric(15,3);
  declare @NawOrderKorting        numeric(6,2);

  declare @abrKostprijsBijEerstvolgendeFactuur  numeric(15,3);
  declare @abrKostprijsBijNieuweContractperiode numeric(15,3);
  declare @abrPrijsBijEerstvolgendeFactuur      numeric(15,3);
  declare @abrPrijsBijNieuweContractperiode     numeric(15,3);
  declare @abrKorting1BijEerstvolgendeFactuur   numeric(15,3);
  declare @abrKorting1BijNieuweContractperiode  numeric(15,3);
  declare @abrKorting2BijEerstvolgendeFactuur   numeric(15,3);
  declare @abrKorting2BijNieuweContractperiode  numeric(15,3);

  /* tabel om nieuwe btwregels tijdelijk in op te slaan. btwregel is een opsomming van de btwbedragen uit alle offerteregels van een versie, gegroepeerd per btwcode. */
  declare local temporary table tmpAbonnementBtwRegel
  ( tmpGid                        integer         default autoincrement,
    tmpAbvGid                     integer,
    tmpAbrGid                     integer,
    tmpArtGid                     integer,
    tmpBtwCode                    integer,
    tmpBtwPercentage              numeric(6,2),
    tmpIsKortingsPercentage       smallint,
    tmpAantal                     numeric(15,3),
    tmpPrijsPer                   numeric(15,3),
//Kostprijs
    tmpKostprijsBijEerstvolgendeFactuur   numeric(15,3),
    tmpKostprijsBijNieuweContractperiode  numeric(15,3),
//Prijs
    tmpPrijsBijEerstvolgendeFactuur       numeric(15,3),
    tmpPrijsBijNieuweContractperiode      numeric(15,3),
//korting1
    tmpKorting1BijEerstvolgendeFactuur    numeric(15,3),
    tmpKorting1BijNieuweContractperiode   numeric(15,3),
//korting2
    tmpKorting2BijEerstvolgendeFactuur    numeric(15,3),
    tmpKorting2BijNieuweContractperiode   numeric(15,3)

/*
    //Totalen obv prijzen bij eerstvolgende factuur
    tmpRegeltotaalBijEerstvolgendeFactuur                numeric(15,2),
    tmporderkortingBijEerstvolgendeFactuur               numeric(15,2),
    tmpRegeltotaalExOrderKortingBijEerstvolgendeFactuur  numeric(15,2),
    tmpBedragBtwDeelBijEerstvolgendeFactuur              numeric(15,2),
    tmpBedragBtwGrondslagBijEerstvolgendeFactuur         numeric(15,2)
    //Totalen obv prijzen bij nieuwe contractperiode
    tmpRegeltotaalBijNieuweContractperiode                numeric(15,2),
    tmporderkortingBijNieuweContractperiode               numeric(15,2),
    tmpRegeltotaalExOrderKortingBijNieuweContractperiode  numeric(15,2),
    tmpBedragBtwDeelBijNieuweContractperiode              numeric(15,2),
    tmpBedragBtwGrondslagBijNieuweContractperiode         numeric(15,2)
*/
    ) on commit preserve rows;

  set @@ErrorTextProcedure = 'AbonnementversieBTWRegels > @AbvGid=' + string(@AbvGid);
  //call TraceBegin(@@ErrorTextProcedure);

  /*
    @TotalenObv 1 = prijzen bij eerstvolgende factuur
                2 = prijzen bij nieuwe contractperiode
  */

  select
    AbvBtwStand, abvOrderKorting, AbvValNummer, (if AbvNawGidPrijzen is null then AboNawGidDebiteur else AbvNawGidPrijzen endif)
    into @AbvBTWStand, @AbvOrderKorting, @AbvValNummer, @NawGid
  from tabAbonnementVersie
  inner join tabAbonnementKop on AboGid = AbvAboGid
  where AbvGid = @AbvGid;

  select first vofIsStuksKorting, vofOrderKortingSoort into @vofIsStuksKorting, @GebruikOrderkorting from tabVasteGegevensOrdersFactureren;

  if (@GebruikOrderkorting = 2) then
    // Orderkorting als regelkorting 2 opnemen
    select (if NawFilWelkeOrderKorting = 1 then DebGrpOrderKorting else NawOrderKorting endif) into @NawOrderKorting
    from tabNaw
    inner join tabNawFile on NawFilNawGid = NawGid and NawFilFonId = 'D'
    inner join tabDebiteurGroepen on NawFilDebGrpGid = DebGrpGid
    where NawFilNawGid = IsNull(null, @NawGid);
  end if;

  //Open een cursor om de prijzen te bepalen
  for @Cursor AS CURSOR_BepaalPrijzen CURSOR FOR
    select
      AbrGid                  @AbrGid,
      abrArtGid               @ArtGid,
      abrBtwCode              @BtwCode,
      BtwPercentage           @BTWPercentage,
      abrAantalOpOrder        @AantalOpOrder,
      abrArtPartijGid         @AbrArtPartijGid,
      abrPrijsPer             @abrPrijsPer,
      abrPrijs                @abrPrijs,
      abrKostprijs            @abrKostprijs,
      abrIsKortingsPercentage @abrIsKortingsPercentage,
      abrKorting1             @abrKorting1,
      abrKorting2             @abrKorting2,
      abrPrijsBepalenBij      @PrijsBepalenBij,
      abrKostprijsBepalenBij  @KostprijsBepalenBij,
      abrKorting1BepalenBij   @Korting1BepalenBij,
      abrKorting2BepalenBij   @Korting2BepalenBij,
      (if (ArtIsPartijAparteKostPrijs=1) and not (ArtPartijGid is null) then ArtPartijKostprijsEx else ArtKostprijsEx endif) @ArtKostPrijs
    from
      tabAbonnementRegel
      inner join tabBtw on (BtwCode=AbrBtwCode)
      inner join tabartikel on artgid = abrArtGid
      left outer join tabartikelPartij on ArtPartijArtGid = abrArtGid and ArtPartijGid = abrArtPartijGid
//      inner join tabAbonnementVersie on (AbvGid=tmpAbvGid)
//      inner join tabBtw on (BtwCode=tmpBtwCode),
//      tabVasteGegevensOrdersFactureren
//    order by abrBtwCode, BtwPercentage
    where abrAbvGid = @AbvGid
    and   abrRegelsoort in (1,2) //alleen de artikel- en tariefregels.
    order by abrBtwCode, BtwPercentage
    for read only
    do
      if isNull(@abrPrijsPer,0) = 0 then
        set @abrPrijsPer = 1;
      end if;
      //Haal de nieuwe prijzen op voor het betreffende artikel
      call BepaalPrijsAfspraak(@NawGid,@ArtGid,null,null,null,@AbrArtPartijGid,@AbvBtwStand,@AbvValNummer,@AantalOpOrder,@AantalOpOrder,@@BasisValutaNummer, @@BasisValutaCode, @@VerwerkingsDatum,
                                    @DummyInt,@DummyInt,@DummyInt,@DummyChar,@PraVerkoopPrijs,@PraKortingsoort,@PraKortingsPercentage,@PraKortingsBedrag,@DummyInt,@DummyInt,@DummyInt);

      //Kostprijs
      set @abrKostprijsBijEerstvolgendeFactuur  = if (@KostprijsBepalenBij=2) then @ArtKostPrijs    else @abrKostPrijs endif; //wijzigen als het per factuurperiode is
      set @abrKostprijsBijNieuweContractperiode = if (@KostprijsBepalenBij=1) then @ArtKostPrijs    else @abrKostprijsBijEerstvolgendeFactuur endif; //wijzigen als het per contractperiode is
      //Prijs
      set @abrPrijsBijEerstvolgendeFactuur      = if (@PrijsBepalenBij=2) then @PraVerkoopPrijs else @abrPrijs endif; //wijzigen als het per factuurperiode is
      set @abrPrijsBijNieuweContractperiode     = if (@PrijsBepalenBij=1) then @PraVerkoopPrijs else @abrPrijsBijEerstvolgendeFactuur endif; //wijzigen als het per contractperiode is

      //korting1
      set @abrKorting1BijEerstvolgendeFactuur   = if (@Korting1BepalenBij=2) then
                                                    if (@PraKortingsoort = 1) then @PraKortingsPercentage else isNull(@PraKortingsBedrag,0) endif
                                                  else
                                                    @abrKorting1
                                                  endif; //wijzigen als het per factuurperiode is
      set @abrKorting1BijNieuweContractperiode  = if (@Korting1BepalenBij=1) then
                                                    if (@PraKortingsoort = 1) then @PraKortingsPercentage else isNull(@PraKortingsBedrag,0) endif
                                                  else
                                                    @abrKorting1BijEerstvolgendeFactuur
                                                  endif; //wijzigen als het per contractperiode is

      //korting2
      set @abrKorting2BijEerstvolgendeFactuur   = if (@Korting2BepalenBij=2) then
                                                    if (@GebruikOrderkorting = 2) then @NawOrderKorting else 0 endif
                                                  else
                                                    @abrKorting2
                                                  endif; //wijzigen als het per factuurperiode is
      set @abrKorting2BijNieuweContractperiode  = if (@Korting2BepalenBij=1) then
                                                    if (@GebruikOrderkorting = 2) then @NawOrderKorting else 0 endif
                                                  else
                                                    @abrKorting2BijEerstvolgendeFactuur
                                                  endif; //wijzigen als het per factuurperiode is



    insert into tmpAbonnementBtwRegel
    (
      tmpAbvGid, tmpAbrGid, tmpArtGid, tmpBtwCode, tmpBtwPercentage, tmpAantal,tmpPrijsPer,tmpIsKortingsPercentage,
      //Kostprijs
      tmpKostprijsBijEerstvolgendeFactuur, tmpKostprijsBijNieuweContractperiode,
      //Prijs
      tmpPrijsBijEerstvolgendeFactuur, tmpPrijsBijNieuweContractperiode,
      //korting1
      tmpKorting1BijEerstvolgendeFactuur, tmpKorting1BijNieuweContractperiode,
      //korting2
      tmpKorting2BijEerstvolgendeFactuur, tmpKorting2BijNieuweContractperiode
    )
    values
    (
      @AbvGid, @abrGid, @ArtGid, @BtwCode, @BtwPercentage, (if (@AantalOpOrder=0) then 1 else @AantalOpOrder endif), @abrPrijsPer, @abrIsKortingsPercentage,
      //Kostprijs
      @abrKostprijsBijEerstvolgendeFactuur, @abrKostprijsBijNieuweContractperiode,
      //Prijs
      @abrPrijsBijEerstvolgendeFactuur, @abrPrijsBijNieuweContractperiode,
      //korting1
      @abrKorting1BijEerstvolgendeFactuur, @abrKorting1BijNieuweContractperiode,
      //korting2
      @abrKorting2BijEerstvolgendeFactuur, @abrKorting2BijNieuweContractperiode
    )

  end for;

  select
    tmpBtwCode as BTWCode,
    tmpBtwPercentage as BTWPercentage,
  //Totalen obv prijzen bij eerstvolgende factuur
    sum(Round(
    if @vofIsStuksKorting=0 then
      if tmpIsKortingsPercentage=1 then
        (((tmpPrijsBijEerstvolgendeFactuur/tmpPrijsPer) * (100 - tmpKorting1BijEerstvolgendeFactuur) / 100) * (100 - tmpKorting2BijEerstvolgendeFactuur) / 100) * tmpAantal
      else
        ((((tmpPrijsBijEerstvolgendeFactuur/tmpPrijsPer) * tmpAantal) - tmpKorting1BijEerstvolgendeFactuur) * (100 - tmpKorting2BijEerstvolgendeFactuur) / 100)
      endif
    else
      if tmpIsKortingsPercentage=1 then
        (((tmpPrijsBijEerstvolgendeFactuur/tmpPrijsPer) * tmpAantal) * (100 - tmpKorting1BijEerstvolgendeFactuur) / 100) * (100 - tmpKorting2BijEerstvolgendeFactuur) / 100
      else
        (((tmpPrijsBijEerstvolgendeFactuur/tmpPrijsPer) - tmpKorting1BijEerstvolgendeFactuur) * tmpAantal) * (100 - tmpKorting2BijEerstvolgendeFactuur) / 100
      endif
    endif
    , 2)) as RegeltotaalExRegelKortingBijEerstvolgendeFactuur,
  round((RegeltotaalExRegelKortingBijEerstvolgendeFactuur/100) * @AbvOrderKorting,2) as orderkortingBijEerstvolgendeFactuur,
  (RegeltotaalExRegelKortingBijEerstvolgendeFactuur - orderkortingBijEerstvolgendeFactuur) as RegeltotaalBijEerstvolgendeFactuur,
  if (@AbvBtwStand = 1) then /*incl btw*/
    round((RegeltotaalBijEerstvolgendeFactuur / (100 + BtwPercentage)) * BtwPercentage, 2)
  else /* excl btw*/
    round((RegeltotaalBijEerstvolgendeFactuur * (BtwPercentage / 100)), 2)
  endif as BedragBtwDeelBijEerstvolgendeFactuur,
  if (@AbvBtwStand = 1) then /*incl btw*/
    round((RegeltotaalBijEerstvolgendeFactuur / (100 + BtwPercentage)) * 100, 2)
  else /* excl btw*/
    RegeltotaalBijEerstvolgendeFactuur
  endif as BedragBtwGrondslagBijEerstvolgendeFactuur,
  //Totalen obv prijzen bij nieuwe contractperiode
  sum(round(
  if @vofIsStuksKorting=0 then
    if tmpIsKortingsPercentage=1 then
      (((tmpPrijsBijNieuweContractperiode/tmpPrijsPer) * (100 - tmpKorting1BijNieuweContractperiode) / 100) * (100 - tmpKorting2BijNieuweContractperiode) / 100) * tmpAantal
    else
      ((((tmpPrijsBijNieuweContractperiode/tmpPrijsPer)* tmpAantal) - tmpKorting1BijNieuweContractperiode) * (100 - tmpKorting2BijNieuweContractperiode) / 100)
    endif
  else
    if tmpIsKortingsPercentage=1 then
      (((tmpPrijsBijNieuweContractperiode/tmpPrijsPer) * tmpAantal) * (100 - tmpKorting1BijNieuweContractperiode) / 100) * (100 - tmpKorting2BijNieuweContractperiode) / 100
    else
      (((tmpPrijsBijNieuweContractperiode/tmpPrijsPer) - tmpKorting1BijNieuweContractperiode)* tmpAantal) * (100 - tmpKorting2BijNieuweContractperiode) / 100
    endif
  endif
  , 2)) as RegeltotaalExRegelKortingBijNieuweContractperiode,
  round((RegeltotaalExRegelKortingBijNieuweContractperiode/100) * @AbvOrderKorting,2) as orderkortingBijNieuweContractperiode,
  (RegeltotaalExRegelKortingBijNieuweContractperiode - orderkortingBijNieuweContractperiode) as RegeltotaalBijNieuweContractperiode,
  if (@AbvBtwStand = 1) then /*incl btw*/
    round((RegeltotaalBijNieuweContractperiode / (100 + BtwPercentage)) * BtwPercentage, 2)
  else /* excl btw*/
    round((RegeltotaalBijNieuweContractperiode * (BtwPercentage / 100)), 2)
  endif as BedragBtwDeelBijNieuweContractperiode,
  if (@AbvBtwStand = 1) then /*incl btw*/
    round((RegeltotaalBijNieuweContractperiode / (100 + BtwPercentage)) * 100, 2)
  else /* excl btw*/
    RegeltotaalBijNieuweContractperiode
  endif as BedragBtwGrondslagBijNieuweContractperiode

  from tmpAbonnementBtwRegel
  group by BtwPercentage, BtwCode
  order by BtwPercentage desc;

  set @@ErrorTextProcedure = 'AbonnementversieBTWRegels';
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure AbonnementVersieKopieren
(
  in  @BronAboGid   integer,
  in  @BronAbvGid   integer,
  out @DoelAbvGid   integer
)
begin
  /* variabelen */
  declare @DoelVersienummer   integer;
  declare @DoelBeginDatum     DateTime;
  declare @qcLockTable        nchar(40) = 'tabAbonnementKop';


  declare @BronOfkOffGid             integer       = null;
  declare @BronOfkOffertenummer      nchar(14)     = null;
  declare @AanmaakDatumTijd          DateTime      = now();
  declare @Offertenummer             numeric(10,0) = null;
  declare @NieuwVersienummer         integer       = null;
  declare @SamengesteldOffertenummer nchar(14)     = null;

  set @@ErrorTextProcedure = 'AbonnementVersieKopieren > @BronAboGid=' + string(@BronAboGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //Haal het Nieuwe versienummer op
  select max(AbvNummer)+1, isNull(DateAdd(day,1,max(AbvEindDatum)), now()) into @DoelVersienummer, @DoelBeginDatum
  from tabAbonnementVersie
  where AbvAboGid = @BronAboGid;

  if LockedById(@@SpId, @@LoginTime, 1, @qcLockTable, string(@BronAboGid)) = 0 then
    call Raise(20368); /* (20368) Abonnement moet gelocked zijn! */
  end if;

  //Abonnementversie kopieren */
  insert into tabAbonnementVersie with auto name
  select
    @BronAboGid as AbvAboGid,
    @DoelVersienummer as AbvNummer,
    @DoelBeginDatum as AbvBeginDatum,
//    AbvEindDatum,
    @DoelBeginDatum as AbvEersteOrderDatum,
//    AbvVolgendeOrderDatum,
    AbvAdrGidEindBestemming,
    AbvAdrGidVerzendAdres,
    AbvBtcNummer,
    AbvBtwStand,
    AbvContractperiodeAantal,
    AbvContractperiodePeriode,
    AbvEindAdres,
    AbvFactureerfrequentieAantal,
    AbvFactureerfrequentiePeriode,
    AbvFactuurAdres,
    AbvIsInkoopcombinatie,
    AbvLvcNummer,
    AbvNawGidFactuur,
    AbvNawGidOmzet,
    AbvNawGidPrijzen,
    AbvOpzegTermijnAantal,
    AbvOpzegTermijnPeriode,
    AbvOrderKorting,
    AbvReferentie,
    AbvTaalGid,
    AbvValNummer,
    AbvVerzendadres,
    AbvAparteFactuur,
    AbvIsDeelLeveringToegestaan,
    AbvKstdGid,
    AbvKstpGid,
    AbvOrderStatusIsGoedgekeurd,
    AbvOrderStatusIsVrijVoorFactureren,
    AbvOrderStatusIsVrijVoorLeveren,
    AbvOrderStatusIsVrijVoorVerzamellijst,
    AbvOrderVerzamellijstGebruiken
  from tabAbonnementVersie
  where AbvGid = @BronAbvGid;

  set @DoelAbvGid = @@Identity;   //nieuw AbvGid ophalen

  //Abonnementregels overnemen
  insert into tabAbonnementRegel with auto name
  select
    abrAantalDecimalenVoorAantallen,
    abrAantalDecimalenVoorPrijzen,
    abrAantalOpOrder,
//    abrabrGidVolgregelMaster,
    @DoelAbvGid as abrAbvGid,
    abrArtGid,
    abrArtPartijGid,
    abrBtwCode,
    abrIsKortingsPercentage,
    abrKorting1,
    abrKorting1BepalenBij,
    abrKorting2,
    abrKorting2BepalenBij,
    abrKostprijs,
    abrKostprijsBepalenBij,
    abrLastModified,
    abrPrijs,
    abrPrijsBepalenBij,
    abrPrijsPer,
    abrRegelNr,
    abrRegelsoort,
    abrTekstOpOrder,
    abrVolgartikelFactor
  from tabAbonnementRegel
  where tabAbonnementRegel.AbrAbvGid = @BronAbvGid;

  //Volgartikelen nog even zetten
  update tabAbonnementregel AbrDoel
  Set AbrDoel.abrabrGidVolgregelMaster = (Select abrDoelMaster.abrGid
                                from tabAbonnementregel abrDoelMaster, tabAbonnementregel abrBronMaster
                                Where abrDoelMaster.AbrRegelNr = abrBronMaster.AbrRegelNr
                                and abrDoelMaster.AbrArtGid = abrBronMaster.AbrArtgid
                                And abrDoelMaster.AbrAbvGid = @DoelAbvGid
                                and abrBronMaster.abrGid = abrBron.abrabrGidVolgregelMaster)
  from tabAbonnementregel AbrDoel,tabAbonnementregel abrBron
  Where AbrDoel.AbrRegelnr = abrBron.AbrRegelNr
  and AbrDoel.AbrArtGid = abrBron.AbrArtgid
  And AbrDoel.AbrAbvGid = @DoelAbvGid
  and not abrBron.abrabrGidVolgregelMaster is null
  and abrBron.AbrAbvGid = @BronAbvGid;

  call VrKopieerRecord('ABO',0,0,'ABO',0,0,@BronAbvGid,@DoelAbvGid);

  set @@ErrorTextProcedure = 'AbonnementVersieKopieren > @BronAboGid=' + string(@BronAboGid);
  //call TraceBegin(@@ErrorTextProcedure);
end;

//-------  Update de acceptgiro layouts tbv. aanmaning
create or replace procedure AcceptGiroAanmaningLayoutsUpdate(in @TaalGid integer, in @RapGid integer)
begin
  //call TraceBegin('AanmaningLayoutsUpdate(@AanmNummer='+string(@AanmNummer)+' @TaalGid='+string(@TaalGid)+', @RapGid='+string(@RapGid)+')');

  if exists(select 1 from tabDocumentLayout where DocLayDocSoort = 75 and DocLayTaalGid = @TaalGid) then
    update tabDocumentLayout set DocLayRapGidAcceptgiro=@RapGid where DocLayDocSoort = 75 and DocLayTaalGid=@TaalGid;
  else
    insert into tabDocumentLayout(DocLayDocSoort, DocLayTaalGid, DocLayRapGidAcceptgiro) values (75, @TaalGid, @RapGid);
  end if;

  //call TraceEind('AcceptGiroAanmaningLayoutsUpdate');
end;


create or replace procedure AcceptGiroVerwijderDummy( in @AcbGid integer )
begin
  //De dummy-AcceptGirobatch wordt geheel ongedaan gemaakt

  set @@ErrorTextProcedure = 'AcceptGiroVerwijderDummy > @AcbGid = '+string(@AcbGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //AcceptGirobatch verwijderen
  delete from tabAcceptGiroBatch where AcbGid = @AcbGid;

  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabAcceptGiroBatch','AcbGid='+string(@AcbGid));

  //call TraceEind(@@ErrorTextProcedure);

end;


//--------- Automatisch genereren van termijnen van activum ---------
create or replace procedure ActivaGenereerTermijnen(in @ActkGid integer, in @Restwaarde numeric(15,3), in @DatumEersteAfschr Date)
begin
  declare @Methode           smallint;
  declare @BoekenPer         smallint;
  declare @Looptijd          integer;
  declare @Aanschafwaarde    numeric(15,3);
  declare @Perc              numeric(15,6);

  declare @SumOfYears        integer;
  declare @Afschrijving      numeric(15,2);
  declare @Afgeschreven      numeric(15,2);
  declare @AfgeschrevenJaar  numeric(15,2);
  declare @JaarAfschr        numeric(15,2);
  declare @Termijnen         integer;
  declare @CurTermijn        integer;
  declare @CurTermijnVanJaar integer;
  declare @TermijnenPerJaar  integer;
  declare @CurJaar           integer;
  declare @CurDate           date;
  declare @IsLaatsteDagVanMaand integer;

  set @@ErrorTextProcedure = 'ActivaGenereerTermijnen';
  //call TraceBegin(@@ErrorTextProcedure);

  delete tabActivaAfschrijvingstermijn where ActatActkGid = @ActkGid;

  set @SumOfYears        = 0;
  set @Afschrijving      = 0;
  set @Afgeschreven      = 0;
  set @Termijnen         = 0;
  set @CurTermijn        = 0;
  set @CurTermijnVanJaar = 0;
  set @TermijnenPerJaar  = 0;
  set @CurJaar           = 0;
  set @JaarAfschr        = 0;
  set @AfgeschrevenJaar  = 0;

  // Als de opgegegeven datum op de laatste dag van de maand valt, dan moeten alle volgende termijnen ook
  // op de laatste dag van de maand vallen.
  if month (@DatumEersteAfschr) = month (dateadd (day, 1, @DatumEersteAfschr)) then
    set @IsLaatsteDagVanMaand = 0
  else
    set @IsLaatsteDagVanMaand = 1
  end if;

  select
    ActkAanschafwaarde,
    ActkAfschrMethode,
    ActkAfschrLooptijd,
    ActkAfschrBoekenPer,
    ActkAfschrPercentage
  into
    @Aanschafwaarde,
    @Methode,
    @Looptijd,
    @BoekenPer,
    @Perc
  from tabActivaKop where ActkGid = @ActkGid;

  case @BoekenPer
    when 0 then set @TermijnenPerJaar =  1;
    when 1 then set @TermijnenPerJaar =  4;
    when 2 then set @TermijnenPerJaar = 12;
    when 3 then set @TermijnenPerJaar = 13;
  end case;

  set @Termijnen = @Looptijd * @TermijnenPerJaar;

  SOYloop:
  loop
    set @CurJaar    = @CurJaar + 1;
    set @SumOfYears = @SumOfYears + @CurJaar;
    if @CurJaar = @Looptijd then
      leave SOYloop;
    end if;
  end loop SOYloop;

  set @CurJaar = 0;
  set @CurDate = null;

  JaarLoop:
  loop
    set @CurJaar   = @CurJaar + 1;
    //call TraceBegin('ActivaGenereerTermijnen > JaarLoop : @CurJaar='+string(@CurJaar)+', @Methode='+string(@Methode)+', @Aanschafwaarde='+string(@Aanschafwaarde)+', @Restwaarde='+string(@Restwaarde)+', @Afgeschreven='+string(@Afgeschreven)+', @JaarAfschr='+string(@JaarAfschr)+', @SumOfYears='+string(@SumOfYears));
    case @Methode

      when 0 then  // Lineair - vast bedrag/percentage van de aanschafwaarde - restwaarde
        set @JaarAfschr = (@Aanschafwaarde - @Restwaarde) / @LoopTijd;

      when 7 then  // Lineair - vast bedrag/percentage van de aanschafwaarde
        set @JaarAfschr = @Aanschafwaarde / @LoopTijd;

      when 1 then  // Vast percentage (in te geven) van de boekwaarde
        set @JaarAfschr = ((@Aanschafwaarde - @Afgeschreven) / 100) * @Perc;

      when 2 then // Vast percentage (berekend) van de boekwaarde
        begin
          //call Trace('(1 - power('+string(@Restwaarde)+' / '+string(@Aanschafwaarde)+', 1 / '+string(@Looptijd)+')) * 100;');
          set @Perc       = (1 - power(@Restwaarde / @Aanschafwaarde, 1.00 / @Looptijd)) * 100;
          set @JaarAfschr = ((@Aanschafwaarde - @Afgeschreven) / 100) * @Perc;
        end;

      when 3 then // Som van de jaarnummers (Sum of the year digits)
        begin
          //call Trace('((('+string(@Looptijd)+' +1) - '+string(@CurJaar)+') / '+string(@SumOfYears)+') * ('+string(@Aanschafwaarde)+' - '+string(@Restwaarde)+')');
          set @JaarAfschr = (((@Looptijd +1.0) - @CurJaar) / @SumOfYears) * (@Aanschafwaarde - @Restwaarde) // <-- 1.0 laten staan ivm int/float conversieprobleem!!
        end;

      when 4 then // Variabel percentage per jaar van de aanschafwaarde
        begin
          if exists(select 1 from tabActivaAfschrijvingPerJaar where ActajActkGid = @ActkGid and ActajJaar = @CurJaar) then
            select ActajPercentage into @Perc from tabActivaAfschrijvingPerJaar where ActajActkGid = @ActkGid and ActajJaar = @CurJaar;
          else // zijn er geen ingevulde jaren meer dan maar stoppen
            leave JaarLoop;
          end if;
          set @JaarAfschr = (@Aanschafwaarde / 100) * @Perc;
        end;

      when 5 then // Variabel percentage per jaar van de boekwaarde
        begin
          if exists(select 1 from tabActivaAfschrijvingPerJaar where ActajActkGid = @ActkGid and ActajJaar = @CurJaar) then
            select ActajPercentage into @Perc from tabActivaAfschrijvingPerJaar where ActajActkGid = @ActkGid and ActajJaar = @CurJaar;
          else // zijn er geen ingevulde jaren meer dan maar stoppen
            leave JaarLoop;
          end if;
          set @JaarAfschr = ((@Aanschafwaarde - @Afgeschreven) / 100) * @Perc;
        end;

      when 6 then // Handmatig
        select ActajBedrag into @JaarAfschr from tabActivaAfschrijvingPerJaar where ActajActkGid = @ActkGid and ActajJaar = @CurJaar;
    end case;

    set @CurTermijnVanJaar = 0;
    TermijnLoop:
    loop
      set @CurTermijn        = @CurTermijn + 1;
      set @CurTermijnVanJaar = @CurTermijnVanJaar + 1;
      set @Afschrijving      = round(@JaarAfschr / @TermijnenPerJaar, 2);
      set @AfgeschrevenJaar  = @AfgeschrevenJaar + @Afschrijving;
      if @CurTermijnVanJaar = @TermijnenPerJaar then  // Bij ieder jaar wordt in de laatste termijn een evt afrondingsverschil verwerkt
        set @Afschrijving     = @Afschrijving + (@JaarAfschr - @AfgeschrevenJaar);
        set @AfgeschrevenJaar = 0.00;
       end if;
      set @Afgeschreven      = @Afgeschreven + @Afschrijving;
      //call TraceBegin('ActivaGenereerTermijnen > TermijnLoop : @Methode='+string(@Methode)+', @Perc='+string(@Perc)+', @Afschrijving='+string(@Afschrijving)+', @CurJaar='+string(@CurJaar)+', @Afgeschreven='+string(@Afgeschreven)+', @JaarAfschr='+string(@JaarAfschr));

      if @CurDate is null then
        set @CurDate = @DatumEersteAfschr
      else
        // ACW: Andere berekening ivm. laatste dag van de maand (31-01-2007, daarna blijft de laatste dag op 30 staan als je per kwartaal boekt; dat was fout)
        /* DG : Indien Datum eerste afschrijving op de laatste datum van de maand valt dan moeten alle gegenereerde datums op de laatste dag van de maand vallen.
                We doen dit door DatumEersteAfschrijving op de eerste dag van de volgende maand te laten vallen, de periode erbij op te tellen,
                en dan een dag ervan af te halen.
        */
        case @BoekenPer
          when 0 then set @CurDate = dateadd(  year, 1 * (@CurTermijn - 1), @DatumEersteAfschr );
          when 1 then
            if @IsLaatsteDagVanMaand = 1 then
              set @CurDate = dateadd (day, -1, dateadd( month, 3 * (@CurTermijn - 1), dateadd (day, 1, @DatumEersteAfschr )));
            else
              set @CurDate = dateadd( month, 3 * (@CurTermijn - 1), @DatumEersteAfschr );
            end if;
          when 2 then
            if @IsLaatsteDagVanMaand = 1 then
              set @CurDate = dateadd (day, -1, dateadd (month, 1 * (@CurTermijn - 1), dateadd (day, 1, @DatumEersteAfschr)));
            else
              set @CurDate = dateadd( month, 1 * (@CurTermijn - 1), @DatumEersteAfschr );
            end if;
          when 3 then set @CurDate = dateadd(  week, 4 * (@CurTermijn - 1), @DatumEersteAfschr );
        end case;
      end if;

      //ACW/TG 13-11-2008: oplossing voor bug #29575 - Methode 7 (Lineair - vast bedrag/percentage van de aanschafwaarde) werd niet opnieuw berekend als het de laatste termijn betrof. Nu wel.
      if    (@Methode in (0,2,3,7) // Evt afrondingsverschillen corrigeren, alleen bij methodes met restwaarde
             and @CurTermijn = @Termijnen and @CurTermijnVanJaar = @TermijnenPerJaar)
         or (@Methode = 7
             and abs(@Afgeschreven) >= abs(@Aanschafwaarde - @Restwaarde)) then
        set @Afschrijving = @Afschrijving + ((@Aanschafwaarde - @Restwaarde) - @Afgeschreven);
      end if;

      insert into tabActivaAfschrijvingstermijn (ActatActkGid, ActatBedragAfschrijving, ActatDatumAfschrijving, ActatNummer, ActatStatus)
                                        select   @ActkGid,     @Afschrijving,           @CurDate,               @CurTermijn, 0;

      //call TraceEind('ActivaGenereerTermijnen > TermijnLoop : @Methode='+string(@Methode)+', @Perc='+string(@Perc)+', @Afschrijving='+string(@Afschrijving)+', @CurJaar='+string(@CurJaar)+', @Afgeschreven='+string(@Afgeschreven)+', @JaarAfschr='+string(@JaarAfschr));
      if (@CurTermijnVanJaar = @TermijnenPerJaar) or (@Methode = 7 and abs(@Afgeschreven) >= abs(@Aanschafwaarde - @Restwaarde)) then
         //call trace('Stoppen!; @CurTermijnVanJaar='+string(@CurTermijnVanJaar)+', @TermijnenPerJaar='+string(@TermijnenPerJaar)+', abs(@Afgeschreven)='+string(abs(@Afgeschreven))+', abs(@Aanschafwaarde - @Restwaarde))='+string(abs(@Aanschafwaarde - @Restwaarde)));
       leave TermijnLoop;
      end if;
    end loop TermijnLoop;

    //call TraceEind('ActivaGenereerTermijnen > JaarLoop : @CurJaar='+string(@CurJaar)+', @Methode='+string(@Methode)+', @Aanschafwaarde='+string(@Aanschafwaarde)+', @Restwaarde='+string(@Restwaarde)+', @Afgeschreven='+string(@Afgeschreven)+', @JaarAfschr='+string(@JaarAfschr));
    if (@CurTermijn = @Termijnen) or (@Methode = 7 and abs(@Afgeschreven) >= abs(@Aanschafwaarde - @Restwaarde)) then
      leave JaarLoop;
    end if;
  end loop JaarLoop;

  set @@ErrorTextProcedure = 'ActivaGenereerTermijnen';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function Activa_BerekenRestwaarde(in @ActkGid integer)
returns numeric(15,2)
begin
  declare @TotaalAfschrijving numeric(15,2);
  declare @TotaalAfgeschreven numeric(15,2);
  declare @Restwaarde         numeric(15,2);

  set @@ErrorTextProcedure = 'Activa_BerekenRestwaarde';
  //call TraceBegin(@@ErrorTextProcedure);

  // Totaal afschrijving berekenen (bestaat uit nog af te schrijven + reeds afgeschreven [ook a.g.v. desinvesteringen!!])
  select sum(ActatBedragAfschrijving) into @TotaalAfschrijving from tabActivaAfschrijvingstermijn where ActatActkGid = @ActkGid and ActatStatus = 0;
  select sum(ActmhAfschrActiva)       into @TotaalAfgeschreven from tabActivaMutatieHistorie      where ActmhActkGid = @ActkGid;
  set @TotaalAfschrijving = isnull(@TotaalAfschrijving, 0.00) + isnull(@TotaalAfgeschreven, 0.00);


  // Activakop aanpassen, zodat de restwaarde weer klopt.
  select ActkAanschafwaarde - @TotaalAfschrijving into @Restwaarde
  from   tabActivaKop
  where  ActKGid = @ActkGid;

  return (isnull(@Restwaarde, 0.00));

  set @@ErrorTextProcedure = 'Activa_BerekenRestwaarde';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure Activa_UpdateDatumEersteAfschrijving(in @ActkGid integer)
begin
  declare @DatumEersteAfschr Date;

  set @@ErrorTextProcedure = 'Activa_UpdateDatumEersteAfschrijving(@ActkGid='+string(@ActkGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  // Update eventueel de datum 1e afschrijving in de activakop
  select min(isnull(ActmhBoekdatum, ActatDatumAfschrijving)) into @DatumEersteAfschr
  from   tabActivaAfschrijvingstermijn
         left outer join tabActivaMutatieHistorie on (ActmhGid = ActatActmhGid)
  where  ActatActkGid = @ActKGid;

  if @DatumEersteAfschr is null then
    update tabActivaKop
    set    ActkAfschrDatumEersteAfschr = null
    where  ActkGid = @ActkGid;
  else
    update tabActivaKop
    set    ActkAfschrDatumEersteAfschr = @DatumEersteAfschr
    where     (ActkGid = @ActkGid)
          and (  (ActkAfschrDatumEersteAfschr is null)
               or (@DatumEersteAfschr <> ActkAfschrDatumEersteAfschr)
              );
  end if;

  set @@ErrorTextProcedure = 'Activa_UpdateRestwaarde';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure "KingSystem".AdminEigenBankrekeningSetLaatsteDatumTijd(in @RakGid integer, in @LaatsteDatumTijd Timestamp)
//Hierin passen we de laatste Datum+Tijd aan en zetten we de laatste transactieID naar null van een opgegeven bankrekening.
//Dit word gebruikt bij het aanmaken van een banktransactie vanuit een bestand.
//Het doel ervan is dat als er vanuit Bizcuit gewerkt wordt er geen dubbele regels in de database terecht komen
//Call AdminEigenBankrekeningSetLaatsteDatumTijd(32019227)
begin
  declare @_EigenBankrekeningNummer nchar(34);
	declare @_LaatsteDatumTijd				Timestamp;

	if (@LaatsteDatumTijd is Null) then
		call Raise(20700, _U('Laatste datum/tijd is leeg')); //(20700) Ongeldige waarde: %1!
	end if;
	set @_LaatsteDatumTijd = @LaatsteDatumTijd;

	//Datum van de laatste regel als datum pakken
	select first RakBankGiro
	into @_EigenBankrekeningNummer
	from tabRekeningAfschriftKop
	inner join tabRekeningAfschriftRegel on rarRakGid = RakGid
	where RakGid = @RakGid
	order by rarRegelnr desc;

	if exists(select 1 from systable where table_name = 'App_tabAdminEigenRekening') then
		begin
			declare @_aerGid			integer;
			declare @_LockResult	integer;
			// Eigen bankrekening locken
			call LockSetOnIdandReleaseRedundantLocks(@@SpId, @@LoginTime, 1, 'App_tabAdminEigenRekening', @_EigenBankrekeningNummer, @_LockResult);

			if @_LockResult = 1 /*Lock gelukt*/ then
				select first App_AerGid
				into   @_aerGid
				from   App_tabAdminEigenRekening
				where  App_AerBankrekeningNummer = @_EigenBankrekeningNummer;

				if @_aerGid is null then
					// Toevoegen!
					insert into App_tabAdminEigenRekening(App_AerBankrekeningNummer, App_AerLaatsteTransactieID, App_AerLaatsteDatumTijdUTC)
					values(@_EigenBankrekeningNummer, null, @_LaatsteDatumTijd);
				else
					// Wijzigen
					update App_tabAdminEigenRekening
					set    App_AerLaatsteTransactieID = null,
									App_AerLaatsteDatumTijdUTC = @_LaatsteDatumTijd
					where App_AerGid = @_aerGid
						and isNull(App_AerLaatsteDatumTijdUTC,@_LaatsteDatumTijd) <= @_LaatsteDatumTijd;
				end if;

				// Na afloop unlocken
				call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'App_tabAdminEigenRekening', @_EigenBankrekeningNummer);

			end if;
		end;
	end if;
end;


//-------  Update de administratiekosten
create or replace procedure AdministratieKostenUpdate(in @AanmNummer integer, in @ValNummer integer, in @Bedrag numeric(15,2))
begin

  //call TraceBegin('AdministratieKostenUpdate(@AanmNummer='+string(@AanmNummer)+' @ValNummer='+string(@ValNummer)+', @Bedrag='+string(@Bedrag)+')');

  if exists(select 1 from tabAdministratieKosten where AdmKostAanmNummer = @AanmNummer and AdmKostValNummer = @ValNummer) then
    update tabAdministratieKosten set AdmKostBedrag=@Bedrag where AdmKostAanmNummer=@AanmNummer and AdmKostValNummer=@ValNummer;
  else
    insert into tabAdministratieKosten(AdmKostAanmNummer, AdmKostValNummer, AdmKostBedrag) values (@AanmNummer, @ValNummer, @Bedrag);
  end if;

  //call TraceEind('AdministratieKostenUpdate');
end;


create or replace function AfrondingOvernemenJaarbudget(in @bedrag numeric(15,2), in @AfrondenVan smallint)
returns numeric(15,2)
begin
  //Afronden op aantal decimalen volgens de tabel
  //en omhoog/omlaag afronden van het bedrag volgens opgave

  //@AfrondenVan: //0=Standaard, 1=Altijd omhoog, 2=Altijd omlaag
  declare @Afronding smallint; //-2=0,01 -1=0,1 0=1 1=10 2=100 etc.

  //call TraceBegin('AfrondingOvernemenJaarbudget(@bedrag='+string(@bedrag)+', @AfrondenVan='+string(@AfrondenVan)+')');

  select first OjbaAfronding into @Afronding from tabOvernemenJaarBudgetAfronding where abs(@bedrag) <= OjbaBedrag order by OjbaBedrag;
  if @Afronding is null then
    //Oeps: niet gevonden, dan maar de laatste gebruiken!
    set @Afronding = -2;  //Als er ook geen laatste is, dan gewoon niet afronden
    select first OjbaAfronding into @Afronding from tabOvernemenJaarBudgetAfronding order by OjbaBedrag desc;
  end if;

  call ProgressAdd(1); //tbv. updaten progress

  //call TraceEind('AfrondingOvernemenJaarbudget(Return='+string(round(@bedrag+(case @AfrondenVan when 0 then 0 when 1 then 0.499 when 2 then -0.5 end)*power(10,@Afronding), -@Afronding ))+')');
  return(sign(@bedrag)*(round(abs(@bedrag)+(if @AfrondenVan = 0 then 0 else 0.499 endif)*power(10,@Afronding), -@Afronding )));

end;


create or replace procedure AfsluitenBoekjaar(
  in  @OudBjGid         integer,
  in  @VanafRegelNummer integer,
  in  @Definitief       integer,  //Geeft aan of de boekingsgang definitief moet worden of niet, zegt niks over soort afsluiting!
  in  @Afsluiting       integer, //0 = niet, 1 = voorlopig, 2 = definitief
  out @BoekGangNr       integer)
begin
  declare @BoekstukNummer               numeric(10,0);
  declare @Verlies                      numeric(15,2);
  declare @Bedrag                       numeric(15,2);
  declare @IsCredit                     smallint;
  declare @ValNummer                    integer;
  declare @NieuwBjGid                   integer;
  declare @BoekgangGid                  integer;
  declare @DgbGid                       integer;
  declare @BjCode                       nchar(10);
  declare @JpOms                        nchar(40);
  declare @NieuweJPGid                  integer;
  declare @ResultaatRksGid              integer;
  declare @ProgressMax                  integer;
  declare @AantalRegelsTotaal           integer;
  declare @AantalRegelsRekeningen       integer;
  declare @AantalRegelsResultaatRek     integer;
  declare @AantalRegelsJournaalpost     integer;
  declare @MaakNieuweJournaalpostAan    smallint;
  declare @NieuweBjAfsluitJrGid         integer;
  //declare @Afsluiting                   Smallint; //0 = niet, 1 = voorlopig, 2 = definitief
  declare @BjBoekgangGidAfsluit         integer;
  declare @BronId                       integer;
  declare @BoekingsgangBronOms          nchar(80);
  declare @VorigeRksGid                 integer;
  declare @TeVerwijderenBoekingsgang    integer; // Indien gevuld, dan hebben we een oude beginbalans die we later moeten verwijderen
  declare @Pogingen                     smallint = 10; // tbv. meerdere malen proberen anti-deadlock

  declare local temporary table tmpBoekingsregels(
    JrGid                            integer,
    RksGid                           integer,
    RksInvoer                        nchar(26),
    DefaultSoort                     integer,
    RksRefNummerBoeken               integer,
    JrValNummer                      integer,
    JrReferentie                     nchar(40),
    JrReferentie_Lengte              integer,
    JrValutaBedrag                   numeric(15,2),
    JrBoekDatum                      date,
    Aantal                           numeric(15,2),
    OmsJournaalregel                 nchar(40),
    SoortBoeking                     integer,
    IsCreditBoeking                  integer,
    JrDarGid                         integer,
    OspFactuurnummer                 nchar(40),
    OspBetalingskenmerk              nchar(140),
    OspFactuurDatum                  date,
    OspVervalDatum                   date,
    AantalRegelsPerRekening          integer
    ) on commit preserve rows;

  declare local temporary table tmpOsp(
    tmpSoort                         smallint, // 0 = gegevens uit te verwijderen beginbalans, 1 = gegevens uit vorige boekjaar
    OspBjGID                         integer,
    OspRksGID                        integer,
    OspFactuurNummer                 nchar(40),
    OspFactuurNummer_Lengte          integer,
    OspIncNawRekGid                  integer,
    OspKredietBeperkingsRksGID       integer,
    OspValNummer                     integer,
    OspValNummerBedragOnderweg       integer,
    OspAanmaningTeller               smallint,
    OspBedragOnderwegInValuta        numeric(15,2),
    OspBtwBedragDefinitief           numeric(15,2),
    OspBtwBedragVoorlopig            numeric(15,2),
    OspFiatteringGewijzigdDoor       nchar(40),
    OspFiatteringGewijzigdOp         timestamp,
    OspGefiatteerd                   smallint,
    OspIcmReferentie                 nchar(35),
    OspIncDatum                      date,
    OspIncOpdrachten                 smallint,
    OspIncPogingenOver               smallint,
    OspIsGeblokkeerd                 smallint,
    OspKredietBeperkingsBedrag       numeric(15,2),
    OspKredietBeperkingsDatum        date,
    OspLaatsteAanmaning              date,
    OspMeldingGeven                  smallint,
    OspOms                           nchar(40),
    OspSoortFactuur                  smallint,
    OspBtcNummer                     integer,
    OspOpmerking                     long nvarchar
  ) on commit preserve rows;

  declare @IsolationLevel smallint; // Snapshot
  declare @SavepointIsActive smallint;

  //call TraceBegin('AfsluitenBoekjaar > @OudBjGid = ' + string(@OudBjGid) + ', @VanafRegelNummer = ' + string(@VanafRegelNummer));

  // *****************************
  // *** Stap 1: Voorbereiding ***
  // *****************************

  set @ProgressMax               = 0;
  set @NieuweJpGid               = null; //dit moet standaard null zijn
  set @MaakNieuweJournaalpostAan = 1;    //bij het starten van de proc moeten we er altijd eentje aanmaken
  set @NieuweBjAfsluitJrGid      = null;
  set @AantalRegelsTotaal        = 0;

  // Not allowed in snapshot, so now here at the top (making inserts somewhat slower...)
  create index Idx_tmpRksGid    on tmpBoekingsregels(RksGid, JrGid);
  create index Idx_tmpRksInvoer on tmpBoekingsregels(RksInvoer, JrReferentie_Lengte, JrReferentie, JrGid);


  select BjAfsluitNaarBjGid, Code,    BjAfsluitDgbGid, BjAfsluitOms, BjAfsluitRksGid,  BjBoekgangGidAfsluit
  into   @NieuwBjGid,        @BjCode, @DgbGid,         @JpOms,       @ResultaatRksGid, @BjBoekgangGidAfsluit
  from   tabBoekjaar
  where  BjGid = @OudBjGid;


  // ******************************
  // *** Stap 2: Start snapshot ***
  // ******************************
  // Using snapshot for this connection
  commit; // HEEL belangrijk, anders kunnen we geen snapshot beginnen
  set @IsolationLevel = @@Isolation;
  set temporary option Isolation_Level = 'Snapshot'; // = 4
  begin snapshot;

  begin
    set @SavepointIsActive = 1;
    savepoint; // Nodig om bij fouten een rollback te kunnen doen

    // ivm snapshot moeten we alvast een lock op @BjBoekgangGidAfsluit zetten, omdat we die straks verwijderen!
    // Let op, dis gebeurt in de snapshot, maar wel in de werkelijke data, andere gebruikers zien dit ook
    if @BjBoekgangGidAfsluit is not null then
      // De lock wordt wel in de echte database gezet, dus ook de anderen blijven er nu af!
      if BoekingsGangInGebruikNemen(@BjBoekgangGidAfsluit) <> 0 then // Als niet gelukt, jammer dan, we verwijderen hem toch straks
        // In feite kan dit niet, want de voorlopige boekingsgang mag door de gebruiker niet in gebruik worden genomen.
        call Raise(20667); //(20667) Boekingsgang is in gebruik!
      end if;
    end if;


    // ************************************************************
    // *** Stap 3: Onthouden van nieuwe boekingen in temp table ***
    // ************************************************************
//  begin // Atomic hoeft niet; bij een fout doen we een rollback en tot nu toe hebben we nog niks gedaan


    // --- - Overnemen rekeningen (excl. debiteuren en crediteuren) per saldo
    call ProgressCreate(0, 100000, _U('Balans rekeningen ophalen'));
    //Vul de tabel met alle boekingen die gemaakt moeten worden voor balans, activa en passiva rekeningen
    insert into tmpBoekingsregels(JrGid, RksGid, RksInvoer, DefaultSoort, RksRefNummerBoeken,
                JrReferentie, JrReferentie_Lengte, JrValNummer, JrValutaBedrag,
                Aantal, OmsJournaalregel, SoortBoeking, IsCreditBoeking)
    select      max(JrGid), JrRksGid, JrRksInvoer, DefaultSoort, RksRefNummerBoeken,
                if RksRefNummerBoeken = 1 then JrReferentie else '' endif Referentie,
                if RksRefNummerBoeken = 1 then JrReferentie_Lengte else 0 endif Referentie_Lengte,
                JrValNummer,
                sum(if IsCreditBoeking = 0 then JrValutaBedrag else -JrValutaBedrag endif) ValutaBedrag,
                sum(if IsCreditBoeking = 0 then Aantal else -Aantal endif) Aantal,
                if RksRefNummerBoeken  = 0 then @JpOms else max(OmsJournaalregel) endif,
                0,
                DefaultBoekzijde
    from        tabJournaalregel
    inner join  tabRekeningschema on (RksGid = JrRksGid and DefaultSoort in (0, 1, 2))
    where       JrBjGid = @OudBjGid and
              ((RegelNummer>=@VanafRegelNummer) or (@Afsluiting = 1 /*Voorlopig*/))
    group by    JrRksGid, JrRksInvoer, DefaultSoort, RksRefNummerBoeken, JrValNummer, Referentie, Referentie_Lengte, DefaultBoekzijde
    having     (ValutaBedrag <> 0) or (Aantal <> 0)
    order by   JrRksInvoer, Referentie_Lengte, Referentie, JrValnummer;

    // --- - Bepaal verlies/winst
    call ProgressCreate(0, 100000, _U('Saldo winst/verlies bepalen'));
    select     IsNull(sum(if IsCreditBoeking = 0 then JrBasisBedrag else -JrBasisBedrag endif),0) into @Verlies   //Let op : positieve uitkomst is een verlies en wordt in principe debet geboekt
    from       tabJournaalregel
    inner join tabRekeningschema on (RksGid = JrRksGid and DefaultSoort in (3,4,5))
    where      JrBjGid = @OudBjGid and ((RegelNummer>=@VanafRegelNummer) or (@Afsluiting = 1 /*Voorlopig*/));

    // --- - Extra boeking tbv verlies/winst
    if @Verlies <> 0 then
      insert into tmpBoekingsregels(RksGid, RksInvoer, DefaultSoort, RksRefNummerBoeken,
                  JrReferentie, JrReferentie_Lengte, JrValNummer, JrValutaBedrag,
                  Aantal, OmsJournaalregel, SoortBoeking, IsCreditBoeking)
      select      RksGid, RksInvoer, DefaultSoort, 0,
                  '', 0, RksValNummer, @Verlies,
                  0, @JpOms, 0, DefaultBoekzijde
      from        tabRekeningschema
      where       RksGid = @ResultaatRksGid;
    end if;

    // --- - Bepaal juiste boekzijde van de boekingen
    //Juiste boekzijde bepalen (2=afhankelijk van saldo) en eventueel bedrag "omklappen"
    update tmpBoekingsregels set IsCreditBoeking = (if IsCreditBoeking in (0, 1) then IsCreditBoeking else if JrValutaBedrag < 0 then 1 else 0 endif endif),
                                 JrValutaBedrag = JrValutaBedrag * (if (IsCreditBoeking = 1) or ((IsCreditBoeking = 2) and (JrValutaBedrag < 0)) then -1 else 1 endif);


    // --- - Overnemen debiteuren- en crediteurenboekingen
    call ProgressCreate(0, 100000, _U('Debiteuren en crediteuren ophalen'));
    //Vul de tabel met alle boekingen die gemaakt moeten worden voor debiteuren en crediteuren
    //Voor alle openstaande posten die nog openstaan, worden alle journaalregels afzonderlijk meegenomen
    insert into tmpBoekingsregels(JrGid, RksGid, RksInvoer, DefaultSoort, RksRefNummerBoeken,
                JrReferentie, JrReferentie_Lengte, JrValNummer, JrValutaBedrag,
                Aantal, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBoekDatum,
                JrDarGid, OspFactuurnummer, OspBetalingskenmerk, OspFactuurDatum, OspVervalDatum)
    select      JrGid, JrRksGid, JrRksInvoer, (select DefaultSoort from tabRekeningschema where RksGid = JrRksgid), 1,
                JrReferentie, JrReferentie_Lengte,
                IsNull((select OspValNummer from tabOpenstaandePost where (OspRksGID = JrRksGid) and (OspFactuurNummer_Lengte = JrReferentie_Lengte) and (OspFactuurNummer = JrReferentie) and (OspBjGid = @NieuwBjGid)), JrValNummer) ValNummer,
               (if ValNummer = JrValNummer then JrValutaBedrag else ValutaOmrekenen(JrValNummer, JrValutaBedrag, ValNummer, @NieuwBjGid, 0, 2) endif),
                Aantal, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBoekDatum,
                JrDarGid, OspFactuurnummer, OspBetalingskenmerk, OspFactuurDatum, OspVervalDatum
    from        tabJournaalregel
    inner join  tabOpenstaandepost OspOld on (OspOld.OspGid = JrOspGid)
    where       JrBjGid = @OudBjGid
           and ((RegelNummer>=@VanafRegelNummer) or (@Afsluiting = 1 /*Voorlopig*/))
           and OspOld.OspBjGid = @OudBjGid
           and (((@Afsluiting <> 1 /*Voorlopig*/) and (((OspOld.OspFactuurBedragDefinitief - OspOld.OspBetaaldBedragDefinitief) <> 0) or (@VanafRegelNummer > 1))) or
               ((@Afsluiting = 1 /*Voorlopig*/) and (OspIsVervallen = 0)))
    order by   JrRksInvoer, JrReferentie_Lengte, JrReferentie, JrGid;



    // ***************************************************************
    // *** Stap 4: Bepaal aantal te boeken rekeningen tbv progress ***
    // ***************************************************************
    //Bepaal het aantal journaalregels dat straks per rekening wordt gemaakt (nodig om te bepalen wanneer er een nieuwe journaalpost moet worden gemaakt)
    update   tmpBoekingsregels
    set      AantalRegelsPerRekening = (select count() from tmpBoekingsregels a where a.RksGid = tmpBoekingsregels.RksGid);

    //TG 08-10-2007:
    //Bepalen hoeveel stappen eruit moeten worden gevoerd; dit wordt berekend door het aantal grootboekrekeningen dat in de for-lus doorlopen wordt.
    //Het betreft hier Activa, passiva, balans rekeningen en de debiteuren en crediteuren. Daarnaast worden er buiten de for-lus nog 7 stappen uitgevoerd.
    //Het totaal van de te doorlopen rekeningen + 7 wordt gebruikt als de 100% stand van de progressbar in het scherm af- en aansluiten boekjaar.
    select count(*) into @ProgressMax from tmpBoekingsregels;
    set @ProgressMax = @ProgressMax + 7;

    //Progress wordt alleen gebruikt om omschrijving uit te kunnen lezen
    call ProgressCreate(0, @ProgressMax, if @VanafRegelNummer=0 then _U('Afsluiten boekjaar') else _U('Aansluiting met vorig boekjaar') endif);

    call ProgressAddAndSetDesc(1, _U('Aanmaken boekingsgang'));

    // *********************************************************************************
    // *** Stap 5: Bij afsluiten de oude afsluitingsboeking onthouden en verwijderen ***
    // *********************************************************************************
    //Als we gaan afsluiten, dan verwijderen we de boekingsgang die is aangemaakt tijdens de vorige keer (voorlopig) afsluiten boekjaar
    if (@VanafRegelNummer = 0) and (not @BjBoekgangGidAfsluit is null) then
      // --- - Reset afsluiting in tabBoekjaar
      call ProgressAddAndSetDesc(1, _U('Beginbalansboeking markeren (1)'));
      //// Als BjBoekGangGIDAfsluit=NULL wordt gezet, dan wordt ook BjAfsluiting op 0 gezet! Knap vervelend, die hebben we later nog nodig.
      // Uitgesteld, omdat hieronder nog een COMMIT zit waardoor een volledige rollback niet kan
//      update tabBoekjaar set BjBoekGangGIDAfsluit = null where BjGid = @OudBjGid
//      OPTION(Isolation_level=1); // Ook echt is de data, niet alleen in de snapshot
      // Corrigeren van trigger... weer terugzetten op voorlopig als dat zo is.
//      update tabBoekjaar set BjAfsluiting = @Afsluiting where BjGid = @OudBjGid and BjAfsluiting <> @Afsluiting
//      OPTION(Isolation_level=1); // Ook echt is de data, niet alleen in de snapshot

      // --- - Onthouden van alle OSPgegevens in de te verwijderen beginbalans
      //#43764 : Alle velden van tabOpenstaandePost die behoren bij de boekingsgang in het nieuwe boekjaar die we zo gaan verwijderen, bufferen zodat we ze bij het opnieuw aanmaken van de nieuwe boekingsgang kunnen overnemen
      call ProgressAddAndSetDesc(1, _U('Onthouden gegevens van bestaande posten'));
      insert into tmpOsp( tmpSoort, OspBjGID, OspRksGID, OspFactuurNummer, OspFactuurNummer_Lengte, OspIncNawRekGid, OspKredietBeperkingsRksGID, OspValNummerBedragOnderweg,
                          OspAanmaningTeller, OspBedragOnderwegInValuta, OspBtwBedragDefinitief, OspBtwBedragVoorlopig, OspFiatteringGewijzigdDoor, OspFiatteringGewijzigdOp,
                          OspGefiatteerd, OspIcmReferentie, OspIncDatum, OspIncOpdrachten, OspIncPogingenOver, OspIsGeblokkeerd, OspKredietBeperkingsBedrag,
                          OspKredietBeperkingsDatum, OspLaatsteAanmaning, OspMeldingGeven, OspOms, OspSoortFactuur, OspBtcNummer, OspOpmerking)
               select     0, OspBjGID, OspRksGID, OspFactuurNummer, OspFactuurNummer_Lengte, OspIncNawRekGid, OspKredietBeperkingsRksGID, OspValNummerBedragOnderweg,
                          OspAanmaningTeller, OspBedragOnderwegInValuta, OspBtwBedragDefinitief, OspBtwBedragVoorlopig, OspFiatteringGewijzigdDoor, OspFiatteringGewijzigdOp,
                          OspGefiatteerd, OspIcmReferentie, OspIncDatum, OspIncOpdrachten, OspIncPogingenOver, OspIsGeblokkeerd, OspKredietBeperkingsBedrag,
                          OspKredietBeperkingsDatum, OspLaatsteAanmaning, OspMeldingGeven, OspOms, OspSoortFactuur, OspBtcNummer, OspOpmerking
               //ACW 13-01-2017 Defect #50733: tabBoekingsgang is niet nodig!
               //from       tabBoekingsgang
               //inner join tabJournaalPost on (JpBoekgangGid = BoekgangGid)
               //inner join tabJournaalregel on (JrJpGid = JpGid)
               //inner join tabOpenstaandepost on (OspGid = JrOspGid)
               //where      BoekGangGid = @BjBoekgangGidAfsluit;
               from       tabJournaalPost
               inner join tabJournaalregel on (JrJpGid = JpGid)
               inner join tabOpenstaandepost on (OspGid = JrOspGid)
               where      JpBoekgangGid = @BjBoekgangGidAfsluit;

      // --- - Verwijder de boekingsgang van de vorige afsluiting
      set @@OverRuleLock = @@OverRuleLock + 1; // Deze is ivm snapshot nu al eerder gelockt
      // Was in gebruik, dus dat eerst ongedaan maken zodat die weer kan worden verwijderd.
      call ProgressAddAndSetDesc(1, _U('Beginbalansboeking markeren (3)'));
      //ACW Dit is uitgesteld totdat we deze gaan verwijderen, zorgt ervoor dat een gebruiker deze niet in gebruik kan nemen tijdens afsluiting
      //update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangGid = @BjBoekgangGidAfsluit and BoekGangInGebruik <> 0
      //OPTION(Isolation_level=1); // Niet in de snapshot, maar werkelijk verwijderen
      set @TeVerwijderenBoekingsgang = @BjBoekgangGidAfsluit;

      //Dit kan dus niet, als we halverwege een deadlock krijgen, dan blijkt de oude boekingsgang toch weg te zijn. Erg vervelend als daar nog info in staat
      //call BoekingsGangVerwijderen(@BjBoekgangGidAfsluit, 0); // Mag best alleen in de snapshot
      set @@OverRuleLock = @@OverRuleLock - 1; // ivm snapshot
    end if;

    // ACW Omdat de bron van boekingsgang bij insert verkeerd wordt gezet hier alvast de juiste oms onthouden, na insert overschrijven
    if @VanafRegelNummer = 0 then
      set @BronId = 4; /*Afsluiting*/
      set @BoekingsgangBronOms = (if @Afsluiting = 1 /*Voorlopig*/ then _A('Voorlopig afsluiten boekjaar %1!', @BjCode) else _A('Definitief afsluiten boekjaar %1!', @BjCode) endif);
    else
      set @BronId = 5; /*Aansluiting*/
      select _A('Aansluiting met vorig boekjaar %1!', Code) into @BoekingsgangBronOms from tabBoekjaar where BjAfsluitNaarBjGid = @NieuwBjGid;
    end if;


    // *************************************************************************************
    // *** Stap 6: Overnemen OSP-gegevens van oude naar nieuwe boekjaar voor nieuwe OSPs ***
    // *************************************************************************************
    //call tracebegin('AfsluitenBoekjaar Begin lus');
    // ACW 2021-06-28: Gegevens hieronder onthouden in een tijdelijke tabel en pas NA beeindigen van de snapshot tabOSP updaten
    // --- - In cursor de OSP-gegevens onthouden van de OSPs uit vorig boekjaar en die worden overgenomen naar nieuwe boekjaar
    // (de OSPs zijn al in het nieuwe jaar bekend)
    call ProgressAddAndSetDesc(1, _U('Openstaande posten onthouden'));
    for @Cursor as CURSOR_tmptabJournaalregel CURSOR FOR
      select distinct
         RksGid     @CursJrRksGid,
         JrReferentie @CursJrReferentie,
         JrReferentie_Lengte @CursJrReferentie_Lengte
      from
        tmpBoekingsregels
      where
        DefaultSoort in (6 /*debiteuren*/, 7 /*Crediteuren*/)
// Als in het nieuwe boekjaar al een betaling heeft plaatsgevonden, dan nog moeten we de aanmaningtellers etc. vergelijken
//        // Als al bestaat in het nieuwe boekjaar, dan NIET opnemen, houd dan de originele OSP-data intact
//        and not exists(select first 1
//                       from   tabJournaalregel
//                              inner join tabJournaalpost on JpGid = JrJpGid
//                       where  JrBjGid = @NieuwBjGid
//                         and  JpBoekgangGid <> isnull(@BjBoekgangGidAfsluit, -1)
//                      )
    for read only
    do
      // --- - Alle OSP-info van oude boekjaar onthouden (Als al in nieuwe boekjaar, dan wellicht bedrag corrigeren naar valuta)
      //(De afsluitingsboekingsgang is al verwijderd, maar wellicht niet in de snapshot, geeft niet)
      //call trace('AfsluitenBoekjaar Statement 1');
      insert into tmpOsp( tmpSoort, OspBjGID, OspRksGID, OspFactuurNummer, OspFactuurNummer_Lengte,
                          OspIncNawRekGid, OspKredietBeperkingsRksGID, OspValNummerBedragOnderweg, OspValNummer,
                          OspAanmaningTeller, OspBedragOnderwegInValuta,
                          OspBtwBedragDefinitief, OspBtwBedragVoorlopig,
                          OspFiatteringGewijzigdDoor, OspFiatteringGewijzigdOp, OspGefiatteerd,
                          OspIcmReferentie, OspIncDatum, OspIncOpdrachten, OspIncPogingenOver,
                          OspIsGeblokkeerd,
                          OspKredietBeperkingsBedrag, OspKredietBeperkingsDatum, OspLaatsteAanmaning, OspMeldingGeven,
                          OspOms, OspSoortFactuur, OspBtcNummer, OspOpmerking)
      select 1, //Soort, 1 = gegevens uit oude boekjaar
             @OudBjGid, @CursJrRksGid, @CursJrReferentie, @CursJrReferentie_Lengte,
             Oud.OspIncNawRekGid, Oud.OspKredietBeperkingsRksGid, Oud.OspValNummerBedragOnderweg, isnull(Nieuw.OspValNummer, Oud.OspValNummer),
             Oud.OspAanmaningTeller, Oud.OspBedragOnderwegInValuta,
             if Oud.OspValNummer = isnull(Nieuw.OspValNummer, Oud.OspValNummer) then Oud.OspBtwBedragDefinitief else ValutaOmrekenen(Oud.OspValNummer, Oud.OspBtwBedragDefinitief, Nieuw.OspValNummer, @NieuwBjGid, 0, 2) endif,
             if Oud.OspValNummer = isnull(Nieuw.OspValNummer, Oud.OspValNummer) then Oud.OspBtwBedragVoorlopig  else ValutaOmrekenen(Oud.OspValNummer, Oud.OspBtwBedragVoorlopig,  Nieuw.OspValNummer, @NieuwBjGid, 0, 2) endif,
             Oud.OspFiatteringGewijzigdDoor, Oud.OspFiatteringGewijzigdOp, Oud.OspGefiatteerd,
             Oud.OspIcmReferentie, Oud.OspIncDatum, Oud.OspIncOpdrachten, Oud.OspIncPogingenOver,
             Oud.OspIsGeblokkeerd,
             if Oud.OspValNummer = isnull(Nieuw.OspValNummer, Oud.OspValNummer) then Oud.OspKredietBeperkingsBedrag else ValutaOmrekenen(Oud.OspValNummer, Oud.OspKredietBeperkingsBedrag, Nieuw.OspValNummer, @NieuwBjGid, 0, 2) endif,
             Oud.OspKredietBeperkingsDatum, Oud.OspLaatsteAanmaning, Oud.OspMeldingGeven,
             Oud.OspOms, Oud.OspSoortFactuur, Oud.OspBtcNummer, Oud.OspOpmerking
      from   tabOpenstaandepost Oud
             left outer join tabOpenstaandepost Nieuw on
               Nieuw.OspBjGid                 = @NieuwBjGid and
               Nieuw.OspRksGid                = @CursJrRksGid and
               Nieuw.OspFactuurNummer_Lengte  = @CursJrReferentie_Lengte
               and Nieuw.OspFactuurNummer     = @CursJrReferentie
      where      Oud.OspBjGid                 = @OudBjGid                 //Oude OSP moet uit vorige boekjaar zijn
             and Oud.OspRksGid                = @CursJrRksGid             //De oude en nieuwe (kopie van oude) OSP bij elkaar zoeken op basis van rekeningnummer..
             and Oud.OspFactuurNummer_lengte  = @CursJrReferentie_Lengte  //De oude en nieuwe lengte
             and Oud.OspFactuurNummer         = @CursJrReferentie         //De oude en nieuwe (kopie van oude) OSP bij elkaar zoeken op basis van factuurnummer..
      OPTION(Isolation_level=1); // Werkelijke data lezen
    end for;

    // ******************************
    // *** Stap 7: Einde snapshot ***
    // ******************************
    commit;
    set @SavepointIsActive = 0;
    set temporary option Isolation_Level = @IsolationLevel;

  // *** EXCEPTIONS
  exception
    when others then
      // --- - Rollback indien nodig/mogelijk
      if @SavepointIsActive = 1 then
        rollback to savepoint; // Alles ongedaan maken!
      else
        rollback; // De rest ook
      end if;
      // --- - Herstellen van tijdelijke Isolation level en triggers
      set temporary option Isolation_Level = @IsolationLevel;
      set temporary option fire_triggers = 'on'; // Voor de zekerheid
      set @@OverRuleLock = 0;
      resignal; // Fout doorgeven naar boven

  end;


  // ******************************************************************
  // *** Stap 8: Aanmaken en vullen boekingsgang in nieuwe boekjaar ***
  // ******************************************************************
  begin
    declare @AanmakenBoekingenTekst            long nvarchar;
    declare @AanmakenBeginBalansBoekingTekst   long nvarchar;
    declare @AanmakenNieuweJournaalRegelsTekst long nvarchar;
    declare @AfsluitenJournaalpostenTekst      long nvarchar;
    declare @AanmakenJournaalpostTekst         long nvarchar;
    declare @VerwerkenRekeningTekst            long nvarchar;
    declare @OnthoudenJournaalregelTekst       long nvarchar;
    declare @OnthoudenBeginbalansTekst         long nvarchar;
    declare @AfsluitenBoekingsgangTekst        long nvarchar;
    declare @OvernemenOSPVorigBoekjaarTekst    long nvarchar;
    declare @OvernemenOSPHuidigBoekjaarTekst   long nvarchar;
    declare @MarkeerJournaalPostenTekst        long nvarchar;
    declare @AfrondenAfsluitenBoekjaarTekst    long nvarchar;
    declare @AfrondenAansluitingTekst          long nvarchar;

    set @AanmakenBoekingenTekst            = _U('Aanmaken boekingen (%1!)');
    set @AanmakenBeginBalansBoekingTekst   = _U('Aanmaken nieuwe beginbalansboeking');
    set @AanmakenNieuweJournaalRegelsTekst = _U('Aanmaken nieuwe journaalregels');
    set @AfsluitenJournaalpostenTekst      = _U('Afsluiten journaalpost %1!');
    set @AanmakenJournaalpostTekst         = _U('Aanmaken journaalpost %1!');
    set @VerwerkenRekeningTekst            = _U('Verwerken rekening %1!');
    set @OnthoudenJournaalregelTekst       = _U('Onthouden nieuwste journaalregel');
    set @OnthoudenBeginbalansTekst         = _U('Onthouden nieuwe beginbalans');
    set @AfsluitenBoekingsgangTekst        = _U('Afsluiten boekingsgang');
    set @OvernemenOSPVorigBoekjaarTekst    = _U('Overnemen gegevens OSP (vorig boekjaar)');
    set @OvernemenOSPHuidigBoekjaarTekst   = _U('Overnemen gegevens OSP (huidig boekjaar)');
    set @MarkeerJournaalPostenTekst        = _U('Markeer alle verwerkte journaalposten');
    set @AfrondenAfsluitenBoekjaarTekst    = _U('Afronden afsluiten boekjaar');
    set @AfrondenAansluitingTekst          = _U('Afronden aansluiting met vorig boekjaar');


    set @Pogingen = 10; // na 5x proberen stoppen we ermee
    while @Pogingen >= 0 loop
      begin
        savepoint; // Bij een deadlock nogmaals proberen
        //alle rekeningen die doorlopen worden
        call ProgressAddAndSetDesc(1, _P(@AanmakenBoekingenTekst, 11-@Pogingen));

        //call Trace('Aanmaken boekingsgang');
        call ProgressAddAndSetDesc(1, @AanmakenBeginBalansBoekingTekst);
        insert into tabBoekingsGang (BoekGangBjGid, BoekGangBronId, BoekGangInGebruik, IsBoekGangDefinitief)
        select @NieuwBjGid, @BronId, 1, @Definitief
        OPTION(Isolation_level=1);
        set @BoekgangGid = @@Identity;
        // Bron omschrijving wordt verkeerd gezet (tabBoekjaar is nog niet geupdatet), hier dus alsnog goed zetten
        update tabboekingsgang
        set BronOms = @BoekingsgangBronOms
        where BoekgangGid = @BoekgangGid
        OPTION(Isolation_level=1);


        //set @@OverRuleLock = @@OverRuleLock + 1;
        set @MaakNieuweJournaalpostAan = 1;
        set @VorigeRksGid = -1;
        //alle rekeningen die doorlopen worden
        // --- - Lus per grootboekrekening
        call ProgressAddAndSetDesc(1, @AanmakenNieuweJournaalRegelsTekst);
        for @Cursor AS Cursor_tmpBoekingsregels CURSOR FOR
          select
            RksGid                   @RksGid,
            RksInvoer                @RksInvoer,
            DefaultSoort             @RksDefaultSoort,
            JrValNummer              @JrValNummer,
            JrReferentie             @JrReferentie,
            JrReferentie_Lengte      @JrReferentie_Lengte,
            RksRefNummerBoeken       @RksRefNummerBoeken,
            JrValutaBedrag           @JrValutaBedrag,
            JrBoekDatum              @JrBoekDatum,
            Aantal                   @Aantal,
            OmsJournaalregel         @OmsJournaalregel,
            SoortBoeking             @SoortBoeking,
            IsCreditBoeking          @IsCreditBoeking,
            JrDarGid                 @JrDarGid,
            OspFactuurnummer         @OspFactuurnummer,
            OspBetalingskenmerk      @OspBetalingskenmerk,
            OspFactuurDatum          @OspFactuurDatum,
            OspVervalDatum           @OspVervalDatum,
            AantalRegelsPerRekening  @AantalRegelsPerRekening
          from
            tmpBoekingsregels
          order by
            RksInvoer, JrReferentie_Lengte, JrReferentie, JrGid
        for read only
        do
          if @VorigeRksGid <> @RksGid then
            if @AantalRegelsJournaalpost > 960 then
              // --- - Afsluiten oude JP
              call ProgressSetDesc(_P(@AfsluitenJournaalpostenTekst, string(@BoekStukNummer)));
              //call Trace('Afsluiten journaalpost ' + string(@BoekStukNummer));
              update tabJournaalPost set JpIsIngebruik = 0 where JpGid = @NieuweJPGid;
              set @MaakNieuweJournaalpostAan = 1;
            end if;

            //nieuwe journaalpost aanmaken als dat gewenst is.
            if @MaakNieuweJournaalpostAan = 1 then
              // --- - Aanmaken nieuwe JP: Boekstuknummer genereren
              call BoekstuknummerGenereren(@NieuwBjGid, @DgbGid, @BoekStukNummer, @BjBoekgangGidAfsluit);
              if IsNull(@BoekStukNummer, 0) = 0 then
                call BoekstuknummerPlusEen(@NieuwBjGid, @DgbGid, 1, @BoekstukNummer, @BjBoekgangGidAfsluit);
              end if;

              // --- - Aanmaken nieuwe JP: post toevoegen
              //nieuwe journaalpost aanmaken
              //call Trace('Aanmaken Journaalpost ' + string(@BoekStukNummer));
              call ProgressSetDesc(_P(@AanmakenJournaalpostTekst, string(@BoekStukNummer)));
              insert into tabJournaalPost(JpBoekGangGid, JpBjGid, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum, JpIsInGebruik)
              select @BoekGangGid, @NieuwBjGid, @DgbGid, @BoekStukNummer, @JpOms, BeginDatum, 1
              from   tabPeriode where PerBjGid = @NieuwBjGid and Pernr = 1;

              //laatste aangemaakte journaalpostgidje onthouden
              set @NieuweJPGid = @@Identity;
              set @MaakNieuweJournaalpostAan = 0;
              set @AantalRegelsJournaalpost = 0;
            end if;
            //call ProgressSetDesc('Rekening ' + string(@RksInvoer));
          end if;

          if Mod(@AantalRegelsTotaal, 100) = 0 then
            call ProgressAddAndSetDesc(@AantalRegelsTotaal, _P(@VerwerkenRekeningTekst, @RksInvoer));
            set @AantalRegelsTotaal = 0;
          end if;

          // --- - Aanmaken journaalregels
          //call Trace('Aanmaken journaalregel voor rekening ' + string(@RksInvoer));
          insert into
            tabJournaalregel
            (JrJpGid, JrRksGid, JrBoekdatum, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrValutaBedrag, JrBasisBedrag,
             JrValNummer, Aantal, JrReferentie, JrBetalingskenmerk, JrFactuurDatum, JrVervalDatum, JrDarGid)
          select
            @NieuweJPGid,
            @RksGid,
            @JrBoekDatum,
            @OmsJournaalregel,
            @SoortBoeking,
            @IsCreditBoeking,
            @JrValutaBedrag,
           (if @JrValNummer = @@BasisValutaNummer then @JrValutaBedrag    else ValutaOmrekenen(@JrValNummer, @JrValutaBedrag, @@BasisValutaNummer, @NieuwBjGid, 0, 2) endif),
            @JrValNummer,
            @Aantal,
            @JrReferentie,
            @OspBetalingskenmerk,
            @OspFactuurDatum,
            @OspVervalDatum,
            @JrDarGid;

          set @AantalRegelsTotaal       = @AantalRegelsTotaal + 1;
          set @AantalRegelsJournaalpost = @AantalRegelsJournaalpost + 1;

          //call Trace('Rekening verwerkt: ' + string(@RksInvoer));
        end for;
        //set @@OverRuleLock = @@OverRuleLock - 1;


          // --- - Afsluiten laatste JP
        //call Trace('Afsluiten journaalpost ' + string(@BoekStukNummer));
        call ProgressAddAndSetDesc(1, _P(@AfsluitenJournaalpostenTekst, string(@BoekStukNummer)));
        update tabJournaalPost set JpIsIngebruik=0 where JpGid=@NieuweJPGid;

        //call Trace('Afsluiten boekingsgang');

        // **********************************************
        // *** Stap 9: Beeindigen af- en aansluiting ***
        // **********************************************
        // --- - Opslaan tot welke definitieve journaalregel is bijgewerkt
        //call Trace('Instellingen opslaan');
        call ProgressAdd(1);
        select first JrGid into @NieuweBjAfsluitJrGid from tabJournaalregel where (JrBjGid = @OudBjGid) and (Regelnummer is not null) order by Regelnummer desc;

        if @NieuweBjAfsluitJrGid is not null then
          call ProgressAddAndSetDesc(1, @OnthoudenJournaalregelTekst);
          update tabBoekjaar set BjAfsluitJrGid = @NieuweBjAfsluitJrGid where BjGid=@OudBjGid;
        end if;

        // --- - Opslaan van boekingsgang tbv afsluiting in oude boekjaar
        if @VanafRegelNummer = 0 then
          //Als we afsluiten boekjaar draaien en we nemen voorlopige boekingsgangen mee uit het vorige boekjaar, dan bewaren we aangemaakte boekingsgang,
          //zodat verwijderd kan worden als we de definitieve jaarafsluiting draaien (is dus zonder voorlopige boekingsgangen uit het vorige boekjaar)
          //RVL 27-01-2015 Eerst nog even testen of er uberhaupt iets is aangemaakt, zo niet, dan beschouwen we het boekjaar als niet afgesloten
          call ProgressAddAndSetDesc(1, @OnthoudenBeginbalansTekst);
          if exists(select BoekGangGid from tabBoekingsgang where BoekGangGid = @BoekGangGid) then
            update tabBoekjaar set BjBoekGangGIDAfsluit = (if @Afsluiting = 1 /*Vooropig*/ then @BoekGangGid else null endif), BjAfsluiting = @Afsluiting where BjGid = @OudBjGid;
          else
            update tabBoekjaar set BjBoekGangGIDAfsluit = null, BjAfsluitNaarBjGid = null where BjGid = @OudBjGid;
            // Corrigeren van trigger... weer terugzetten op voorlopig als dat zo is.
            update tabBoekjaar set BjAfsluiting = @Afsluiting where BjGid = @OudBjGid and BjAfsluiting <> @Afsluiting;
          end if;
        end if;

        // --- - Afsluiten boekingsgang voor aan/afsluiting
        call ProgressAddAndSetDesc(1, @AfsluitenBoekingsgangTekst);
        update tabBoekingsgang set BoekGangInGebruik=0 where BoekGangGid=@BoekGangGid;

        //call traceeind('AfsluitenBoekjaar Ende lus');


        // ****************************************************
        // *** Stap 10: Gegevens uit oude boekjaar overnemen ***
        // ****************************************************
        // --- - OSP-gegevens uit oude jaar die tijdelijk zijn bewaard hier alsnog in de OSP plaatsen
        //call Trace('Een aantal veldjes uit openstaandeposten moeten direct worden overgenomen');
        call ProgressAddAndSetDesc(1, @OvernemenOSPVorigBoekjaarTekst);
        update tabOpenstaandepost Nieuw
        set
               OspLaatsteAanmaning        = if IsNull(Nieuw.OspAanmaningTeller, 0) >= IsNull(Oud.OspAanmaningTeller, 0) then isnull(Nieuw.OspLaatsteAanmaning, oud.OspLaatsteAanmaning) else isnull(Oud.OspLaatsteAanmaning, Nieuw.OspLaatsteAanmaning) endif,
               OspAanmaningTeller         = if IsNull(Nieuw.OspAanmaningTeller, 0) >= IsNull(Oud.OspAanmaningTeller, 0) then Nieuw.OspAanmaningTeller else Oud.OspAanmaningTeller endif,
               OspMeldingGeven            = Oud.OspMeldingGeven,
               OspIsGeblokkeerd           = Oud.OspIsGeblokkeerd,
               OspKredietBeperkingsBedrag = Oud.OspKredietBeperkingsBedrag,
               OspSoortFactuur            = Oud.OspSoortFactuur,
               OspKredietBeperkingsDatum  = Oud.OspKredietBeperkingsDatum,
               OspKredietBeperkingsRksGid = Oud.OspKredietBeperkingsRksGid,
               OspBtwBedragVoorlopig      = if Oud.OspValNummer = Nieuw.OspValNummer then Oud.OspBtwBedragVoorlopig  else ValutaOmrekenen(Oud.OspValNummer, Oud.OspBtwBedragVoorlopig,  Nieuw.OspValNummer, @NieuwBjGid, 0, 2) endif,
               OspBtwBedragDefinitief     = if Oud.OspValNummer = Nieuw.OspValNummer then Oud.OspBtwBedragDefinitief else ValutaOmrekenen(Oud.OspValNummer, Oud.OspBtwBedragDefinitief, Nieuw.OspValNummer, @NieuwBjGid, 0, 2) endif,
               OspValNummerBedragOnderweg = Oud.OspValNummerBedragOnderweg,
               OspBedragOnderwegInValuta  = Oud.OspBedragOnderwegInValuta,
               OspOms                     = Oud.OspOms,
               OspIncDatum                = Oud.OspIncDatum,
               OspIncNawRekGid            = Oud.OspIncNawRekGid,
               OspIncOpdrachten           = Oud.OspIncOpdrachten,
               OspIncPogingenOver         = Oud.OspIncPogingenOver,
               OspIcmReferentie           = Oud.OspIcmReferentie,
               OspFiatteringGewijzigdDoor = Oud.OspFiatteringGewijzigdDoor,
               OspFiatteringGewijzigdOp   = Oud.OspFiatteringGewijzigdOp,
               OspGefiatteerd             = Oud.OspGefiatteerd,
               OspBtcNummer               = Oud.OspBtcNummer,
               OspOpmerking               = Oud.OspOpmerking
        from   tmpOsp Oud
               inner join tabOpenstaandePost Nieuw on
                     Nieuw.OspBjGid                = @NieuwBjGid                    //Nieuwe OSP moet uit nieuwe boekjaar zijn
                 and Nieuw.OspRksGid               = Oud.OspRksGID                  //..en het moet gaan over de rekening uit de cursor
                 and Nieuw.OspFactuurNummer_Lengte = Oud.OspFactuurNummer_Lengte    //..en het moet gaan over het factuurnummer (referentie) uit de cursor
                 and Nieuw.OspFactuurNummer        = Oud.OspFactuurNummer           //..en het moet gaan over het factuurnummer (referentie) uit de cursor
        where  Oud.tmpSoort = 1 /*Oude gegevens uit vorig boekjaar voor OSPs die in nieuwe boekjaar ook al bekend zijn*/
        ;


        //#43764 Als we de vorige beginbalans hebben verwijderd, dan willen we sommige velden van de opstaande posten overnemen zoals ze waren in het nieuwe boekjaar voordat we de beginbalans verwijderde
          //call trace('AfsluitenBoekjaar Statement 2?');
        // --- - OSP-gegevens uit verwijderde boekingsgang die tijdelijk zijn bewaard hier overnemen
        if (@VanafRegelNummer = 0) and (not @BjBoekgangGidAfsluit is null) then
          call ProgressAddAndSetDesc(1, @OvernemenOSPHuidigBoekjaarTekst);
          update tabOpenstaandePost set
            OspLaatsteAanmaning        = if IsNull(tabOpenstaandePost.OspAanmaningTeller, 0) >= IsNull(tmpOsp.OspAanmaningTeller, 0) then tabOpenstaandePost.OspLaatsteAanmaning else tmpOsp.OspLaatsteAanmaning endif,
            OspAanmaningTeller         = if IsNull(tabOpenstaandePost.OspAanmaningTeller, 0) >= IsNull(tmpOsp.OspAanmaningTeller, 0) then tabOpenstaandePost.OspAanmaningTeller else tmpOsp.OspAanmaningTeller endif,
            OspFiatteringGewijzigdOp   = if IsNull(tabOpenstaandePost.OspFiatteringGewijzigdOp, '1900-01-01') >= IsNull(tmpOsp.OspFiatteringGewijzigdOp, '1900-01-01') then tabOpenstaandePost.OspFiatteringGewijzigdOp else tmpOsp.OspFiatteringGewijzigdOp endif,
            OspFiatteringGewijzigdDoor = if IsNull(tabOpenstaandePost.OspFiatteringGewijzigdOp, '1900-01-01') >= IsNull(tmpOsp.OspFiatteringGewijzigdOp, '1900-01-01') then tabOpenstaandePost.OspFiatteringGewijzigdDoor else tmpOsp.OspFiatteringGewijzigdDoor endif,
            OspGefiatteerd             = if IsNull(tabOpenstaandePost.OspFiatteringGewijzigdOp, '1900-01-01') >= IsNull(tmpOsp.OspFiatteringGewijzigdOp, '1900-01-01') then tabOpenstaandePost.OspGefiatteerd else tmpOsp.OspGefiatteerd endif,
            OspIncDatum                = if IsNull(tabOpenstaandePost.OspIncDatum, '1900-01-01') >= IsNull(tmpOsp.OspIncDatum, '1900-01-01') then tabOpenstaandePost.OspIncDatum else tmpOsp.OspIncDatum endif,
            OspIcmReferentie           = if IsNull(tabOpenstaandePost.OspIncDatum, '1900-01-01') >= IsNull(tmpOsp.OspIncDatum, '1900-01-01') then tabOpenstaandePost.OspIcmReferentie else tmpOsp.OspIcmReferentie endif,
            OspIncOpdrachten           = if IsNull(tabOpenstaandePost.OspIncDatum, '1900-01-01') >= IsNull(tmpOsp.OspIncDatum, '1900-01-01') then tabOpenstaandePost.OspIncOpdrachten else tmpOsp.OspIncOpdrachten endif,
            OspIncPogingenOver         = if IsNull(tabOpenstaandePost.OspIncDatum, '1900-01-01') >= IsNull(tmpOsp.OspIncDatum, '1900-01-01') then tabOpenstaandePost.OspIncPogingenOver else tmpOsp.OspIncPogingenOver endif,
            OspIncNawRekGid            = if IsNull(tabOpenstaandePost.OspIncDatum, '1900-01-01') >= IsNull(tmpOsp.OspIncDatum, '1900-01-01') then tabOpenstaandePost.OspIncNawRekGid else tmpOsp.OspIncNawRekGid endif,
            OspKredietBeperkingsRksGID = tmpOsp.OspKredietBeperkingsRksGID,
            OspValNummerBedragOnderweg = tmpOsp.OspValNummerBedragOnderweg,
            OspBedragOnderwegInValuta  = tmpOsp.OspBedragOnderwegInValuta,
            OspBtwBedragDefinitief     = tmpOsp.OspBtwBedragDefinitief,
            OspBtwBedragVoorlopig      = tmpOsp.OspBtwBedragVoorlopig,
            OspIsGeblokkeerd           = tmpOsp.OspIsGeblokkeerd,
            OspKredietBeperkingsBedrag = tmpOsp.OspKredietBeperkingsBedrag,
            OspKredietBeperkingsDatum  = tmpOsp.OspKredietBeperkingsDatum,
            OspMeldingGeven            = tmpOsp.OspMeldingGeven,
            OspOms                     = tmpOsp.OspOms,
            OspSoortFactuur            = tmpOsp.OspSoortFactuur,
            OspBtcNummer               = tmpOsp.OspBtcNummer,
            OspOpmerking               = tmpOsp.OspOpmerking
          from  tmpOsp
          where tmpOsp.tmpSoort = 0 /*Oude beginbalans*/
            and tmpOsp.OspBjGID = tabOpenstaandePost.OspBjGID and
                tmpOsp.OspRksGID = tabOpenstaandePost.OspRksGID and
                tmpOsp.OspFactuurNummer = tabOpenstaandePost.OspFactuurNummer and
                tmpOsp.OspFactuurNummer_Lengte = tabOpenstaandePost.OspFactuurNummer_Lengte;
        end if;


        // --- - Markeren van alle journaalposten in het oude boekjaar die inmiddels in het nieuwe boekjaar zijn verwerkt
        //call Trace('De journaalposten die overgenomen zijn naar de beginbalans van het volgende boekjaar, even markeren. Kan in de toekomst dan gebruikt worden ipv bij aansluiting naar het regelnummer te kijken');
        call ProgressAddAndSetDesc(1, @MarkeerJournaalPostenTekst);
        set @@OverRuleLock = 1;
        update tabJournaalPost
        set    JpAlInBeginbalans = 1
        from   tabJournaalPost inner join tabBoekingsgang on (JpBoekgangGid = BoekgangGid)
        where      BoekGangBjGid = @OudBjGid
               and JpBjGid = @OudBjGid
               and IsBoekgangDefinitief = 1
               and IsNull(JpAlInBeginbalans, 0) = 0;
        set @@OverRuleLock = 0;

        // --- - Teruggeven van het nieuwe boekingsgangnummer
        //call Trace('Boekingsgangnummer teruggeven');
        call ProgressAddAndSetDesc(1, if @VanafRegelNummer=0 then @AfrondenAfsluitenBoekjaarTekst else @AfrondenAansluitingTekst endif);

        // --- - Voor de zekerheid de lock op oude afsluitingsboekingsgang vrijgeven
        // Deze hebben we eerder al gelockt, dus nu weer lock vrijgeven, behalve als die nog nodig is
        if @BjBoekgangGidAfsluit is not null and @TeVerwijderenBoekingsgang is null then
          call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabBoekingsgang', 'BoekGangGid=' || @BjBoekgangGidAfsluit);
        end if;

        // Laten we niet vergeten om de oude boekingsgang te verwijderen en zijn boekingsgangnummer toe te wijzen aan de nieuwe boekingsgang
        if @TeVerwijderenBoekingsgang is not null then
          select BoekGangNummer into @BoekGangNr from tabBoekingsgang where BoekGangGid=@TeVerwijderenBoekingsgang;
          update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangGid = @TeVerwijderenBoekingsgang and BoekGangInGebruik <> 0;
          set @@OverRuleLock = @@OverRuleLock + 1; // Deze is ivm snapshot nu al eerder gelockt
          call BoekingsGangVerwijderen(@TeVerwijderenBoekingsgang, 0); // Mag best alleen in de snapshot
          set @@OverRuleLock = @@OverRuleLock - 1; // ivm snapshot
          set @TeVerwijderenBoekingsgang = 0;
          // Oorspronkelijke boekingsgangnummer weer aan de nieuwe boekingsgang toewijzen
          set temporary option fire_triggers='off';
          update tabBoekingsgang set BoekGangNummer = @BoekGangNr where BoekGangGid=@BoekGangGid;
          set temporary option fire_triggers='on';
        else
          // Nieuwe boekingsgangnummer onthouden
          select BoekGangNummer into @BoekGangNr from tabBoekingsgang where BoekGangGid=@BoekGangGid;
        end if;

        //call Trace('Progress verwijderen');
        call ProgressDelete;

        // Einde van deadlock-code
        set @Pogingen = -1; // We zijn klaar en het is gelukt
        commit;

      exception
        when others then // Alleen deadlock??
          if @Pogingen > 0 then
            rollback to savepoint; // Alles ongedaan maken!
            set @Pogingen = @Pogingen - 1; // Nogmaals proberen
          else
            resignal; // Genoeg pogingen ondernomen
          end if;
      end;
    end loop; // lus om steeds te proberen tot er geen deadlock meer is
  end;


  //call TraceEind('AfsluitenBoekjaar > @BoekGangNr='+string(@BoekGangNr));
end;


//---- procedure retourneert in verschil het aantal rijen in de tabel verminderd
//---- met het aantal unieke waarden van in de kolom @veldnaam
//---- verschil = 0 ------> allemaal unieke waarden
create or replace procedure AlleWaardenUniek(in @TabelNaam nchar(30), in @VeldNaam nchar(30), out @Verschil integer)
begin

  //call TraceBegin('AlleWaardenUniek(@TabelNaam='+string(@TabelNaam)+', @VeldNaam='+string(@Veldnaam)+')');

  execute immediate 'select @Verschil = ((select count(*) from ' || @TabelNaam || ' ) '+
                    ' - (select count(distinct ' || @Veldnaam || ' ) from ' || @TabelNaam || ')) ';

  //call TraceEind('AlleWaardenUniek --> @Verschil='+string(@Verschil));

end;


create or replace procedure ArtikelKopieren
(
  in  @BronArtGid             integer,
  in  @NieuwArtCode	          nchar(20),
  in  @DefaultLevEenhKopieren smallint,
  in  @NieuwArtCodeBijLev	    nchar(20),
  in  @NieuwArtEanCode        nchar(30),
  in  @OverigeLevEenhKopieren smallint,
  in  @PartijenKopieren       smallint,
  in  @WebwinkelsKopieren     smallint,
  out @NieuwArtGid            integer
)

//JV, 27 juni 2005:
//wel kopieren:
//-1 tabArtikel             1 stuks, bijna alle velden(niet mbt gereserveerd, voorraadaantallen, defaultmagazijn)
//-2 tabVerkoopEenheid      n stuks, meerdere verkoopeenheden en de voorraadeenheid.
//-2 tabPrijsAfspraak       1 stuks, alleen kortingen/staffels die je bij artikelscherm kunt invoeren(dus geen relatie tot naw,etc)
//-3 tabArtikelTeksten      n stuks, meerdere talen, maar opmerking hoort hier ook bij (taalgid null)
//-4 tabArtikelLeverancier  1 stuks, als bron ingevuld is
//-5 tabArtikelMagazijn     n stuks, alleen minimumvoorraad
//-6 tabArtikelVervolg      n stuks
//-7 vrije rubrieken        1 stuks

//niet kopieren:
//-tabArtikelEan
//-tabArtikelLocatie
//-tabArtikelSerienummer

//Alle insert/select statements gegenereerd door in meta editor op sql tab select statement te genereren
//Als er later velden bijgevoegd worden gaarne deze nieuwe velden lijst er even naast zetten en velden op juist positie tussenvoegen

begin
  declare @NieuwArtLevGid integer;
  declare @NieuwArtEanGid integer;

  set @@ErrorTextProcedure = 'ArtikelKopieren > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @BronArtGid = ' + string(@BronArtGid) + ', @NieuwArtCode = ' + string(@NieuwArtCode) + ', @NieuwArtCodeBijLev = ' + string(@NieuwArtCodeBijLev));

  set @NieuwArtCode	          = trim(IsNull(@NieuwArtCode , ''));
  set @DefaultLevEenhKopieren = IsNull(@DefaultLevEenhKopieren, 0);
  set @NieuwArtCodeBijLev     = trim(IsNull(@NieuwArtCodeBijLev, ''));
  set @NieuwArtEanCode        = trim(IsNull(@NieuwArtEanCode, ''));
  set @OverigeLevEenhKopieren = IsNull(@OverigeLevEenhKopieren, 0);
  set @PartijenKopieren       = IsNull(@PartijenKopieren, 0);
  set @WebwinkelsKopieren     = IsNull(@WebwinkelsKopieren, 0);

  if @DefaultLevEenhKopieren=0 then
    set @NieuwArtCodeBijLev     = '';
    set @NieuwArtEanCode        = '';
    set @OverigeLevEenhKopieren = 0;
  end if;

  set @NieuwArtLevGid = null;
  set @NieuwArtEanGid = null;

  //call Trace('ArtikelKopieren > tabArtikel');
  insert into tabArtikel with auto name
  select
    ArtAantallen,
    ArtAantDecAantallen,
    ArtAantDecPrijzen,
    ArtAdviesPrijs,
    ArtAfbeeldingGroot,
    ArtAfbeeldingKlein,
    ArtBerekenPrijs,
    ArtBerekenPrijsMargeIs,
    ArtBerekenPrijsPerc,
    ArtBerekenPrijsVan,
    ArtBtwCode,
    ArtBtwCodeInkoop,
    ArtCbsGcGid,
    ArtCbsMaatstaf,
    ArtLndGidCbsOorsprong,
    @NieuwArtCode ArtCode,        //nieuwe ArtCode
    //ArtDefaultMagGid,           //niet kopieren
    ArtGarantieVullenBijLeveren,
    ArtGcGid,
    //ArtGereserveerd,            //niet kopieren
    ArtGewicht,
    ArtGewichtPer,
    ArtGewichtPerEenheid,
    //ArtGid,                     //niet kopieren
    ArtHeeftVoorraad,
    ArtIngangsDatumHuidigeKostprijs,
    ArtIngangsdatumHuidigeVerkoopPrijsExcl,
    ArtIngangsdatumHuidigeVerkoopPrijsIncl,
    ArtIngangsDatumHuidigeprijsper,
  	ArtIngangsDatumOudeVerkoopPrijsExcl,
    ArtIngangsDatumOudeVerkoopPrijsIncl,
    ArtIngangsDatumOudeprijsper,
    ArtIngangsDatumOudeKostprijs,
    ArtInvTekstOpFactuur,
    ArtIsAdviesPrijsInclBtw,
    ArtIsGeblokkeerd,
    ArtIsGeblokkeerdInkoop,
    ArtIsPartijAparteKostPrijs,
    ArtIsPartijAparteTekstOpFactuur,
    ArtIsPartijAparteVerkoopPrijs,
    ArtIsPartijNrBijLeverenVerplicht,
    ArtIsPartijNrGenereren,
    ArtIsPartijRegistreren,
    ArtIsPartijVerkoopCheckOuderePartijOp,
    ArtIsSerieNrBijVerkoopZoeken,
    ArtIsSerieNrBijVrijgaveVerplicht,
    ArtKostprijsEx,
    ArtMutatieInkoopBijhouden,
    ArtMutatieVerkoopBijhouden,
    ArtOms,
    ArtOmsEenheid,
    ArtOpbrGrpGId,
    ArtOudeKostprijs,
    ArtOudePrijsPer,
    ArtOudeVerkoopPrijs,
    ArtPartijAparteKostPrijsDefault,
    ArtPartijAparteTekstOpFactuurDefault,
    ArtPartijAparteVerkoopPrijsDefault,
    ArtPartijNrLengteVolgnr,
    ArtPartijNrStartNummer,
    ArtPartijNrTekstAchter,
    ArtPartijNrTekstVoor,
    ArtPartijNrVolgnrUitvullen,
    ArtPartijVerkoopCheckOuderePartij,
    ArtPrijsPer,
    //ArtSamengesteldRcptGid,   //niet kopieren!
    ArtSerieNrAanmakenBij,
    ArtSerieNrBijVerkoopAanmaken,
    ArtSerieNrGenereren,
    ArtSerieNrLengteVolgnr,
    ArtSerieNrRegistreren,
    ArtSerieNrStartNummer,
    ArtSerieNrTekstAchter,
    ArtSerieNrTekstVoor,
    ArtSerieNrVolgnrUitvullen,
    ArtSoort,
    ArtTimeStamp,
    ArtVerkprijs,
    ArtVerkprijsIsIncl,
    ArtVolume,
    ArtVolumePer,
    ArtVolumePerEenheid,
    //ArtVoorraad,                //niet kopieren
    ArtZoekcode,
    ArtIsGeblokkeerdMagOntv,
    ArtIsGebruikVoorBestelAdvies,
    ArtIsGebruikVoorProductieAdvies,
    ArtIsKostprijsWijzigenInOrder,
    ArtBestellenViaDirecteInkoop,
    ArtOmsVerkooporderOvernemen,
    ArtBestellenVoorDirecteLevering,
    ArtDefaultVerkoopEenheid

  from tabArtikel
  where Artgid = @BronArtGid;

  //Artgid van nieuwe artikel ophalen
  set @NieuwArtGid = @@Identity;

  if @WebwinkelsKopieren = 1 then
    //call Trace('ArtikelKopieren > Webwinkels');
    update tabArtikel Doel set
      Doel.ArtWebArtikel       = Bron.ArtWebArtikel,
      Doel.ArtWebBestelGrootte = Bron.ArtWebBestelGrootte,
      Doel.ArtWebLevertijd     = Bron.ArtWebLevertijd,
      Doel.ArtWebTonenTot      = Bron.ArtWebTonenTot,
      Doel.ArtWebTonenVanaf    = Bron.ArtWebTonenVanaf
    from tabArtikel Bron where Bron.ArtGid = @BronArtGid and Doel.ArtGid = @NieuwArtGid;
  end if;

  //call Trace('ArtikelKopieren > tabVerkoopEenheid');
  //Dit zijn de verkoopeenheden exclusief de voorraadeenheid. de laatste word in de trigger aangemaakt.
  insert into tabVerkoopEenheid (
    VkeAantalDecimalen,
    VkeAantalKanVerschillen,
    VkeAantalVoorraadEenhedenInVerkoopEenheid,
    VkeAdviesprijs,
    VkeArtGid,
    VkeGewicht,
    VkeGewichtPer,
    VkeHeeftAparteVerkoopPrijsOfKorting,
    VkeIsAdviesprijsInclusiefBTW,
    VkeIsAfwijkendGewichtOfVolume,
    VkeIsGeblokkeerdVoorVerkoop,
    VkeIsVerkoopprijsInclusiefBTW,
    VkeIsVoorraadEenheid,
    VkeVerkoopEenheid,
    VkeVerkoopprijs,
    VkeVerkoopPrijsPer,
    VkeVolume,
    VkeVolumePer )
  select
    VkeAantalDecimalen,
    VkeAantalKanVerschillen,
    VkeAantalVoorraadEenhedenInVerkoopEenheid,
    VkeAdviesprijs,
    @NieuwArtGid,
    VkeGewicht,
    VkeGewichtPer,
    VkeHeeftAparteVerkoopPrijsOfKorting,
    VkeIsAdviesprijsInclusiefBTW,
    VkeIsAfwijkendGewichtOfVolume,
    VkeIsGeblokkeerdVoorVerkoop,
    VkeIsVerkoopprijsInclusiefBTW,
    VkeIsVoorraadEenheid,
    VkeVerkoopEenheid,
    VkeVerkoopprijs,
    VkeVerkoopPrijsPer,
    VkeVolume,
    VkeVolumePer
  from tabVerkoopEenheid
  where VkeArtGid = @BronArtGid and VkeIsVoorraadEenheid=0;

  //Update de voorraadeenheid velden. De trigger heefthet record al aangemaakt.
  Update tabVerkoopEenheid NieuwVrdEenheid
  set
    NieuwVrdEenheid.VkeAantalDecimalen                        = BronVrdEenheid.VkeAantalDecimalen,
    NieuwVrdEenheid.VkeAantalKanVerschillen                   = BronVrdEenheid.VkeAantalKanVerschillen,
    NieuwVrdEenheid.VkeAantalVoorraadEenhedenInVerkoopEenheid = BronVrdEenheid.VkeAantalVoorraadEenhedenInVerkoopEenheid,
    NieuwVrdEenheid.VkeAdviesprijs                            = BronVrdEenheid.VkeAdviesprijs,
    NieuwVrdEenheid.VkeGewicht                                = BronVrdEenheid.VkeGewicht,
    NieuwVrdEenheid.VkeGewichtPer                             = BronVrdEenheid.VkeGewichtPer,
    NieuwVrdEenheid.VkeHeeftAparteVerkoopPrijsOfKorting       = BronVrdEenheid.VkeHeeftAparteVerkoopPrijsOfKorting,
    NieuwVrdEenheid.VkeIsAdviesprijsInclusiefBTW              = BronVrdEenheid.VkeIsAdviesprijsInclusiefBTW,
    NieuwVrdEenheid.VkeIsAfwijkendGewichtOfVolume             = BronVrdEenheid.VkeIsAfwijkendGewichtOfVolume,
    NieuwVrdEenheid.VkeIsGeblokkeerdVoorVerkoop               = BronVrdEenheid.VkeIsGeblokkeerdVoorVerkoop,
    NieuwVrdEenheid.VkeIsVerkoopprijsInclusiefBTW             = BronVrdEenheid.VkeIsVerkoopprijsInclusiefBTW,
    NieuwVrdEenheid.VkeIsVoorraadEenheid                      = BronVrdEenheid.VkeIsVoorraadEenheid,
    NieuwVrdEenheid.VkeVerkoopEenheid                         = BronVrdEenheid.VkeVerkoopEenheid,
    NieuwVrdEenheid.VkeVerkoopprijs                           = BronVrdEenheid.VkeVerkoopprijs,
    NieuwVrdEenheid.VkeVerkoopPrijsPer                        = BronVrdEenheid.VkeVerkoopPrijsPer,
    NieuwVrdEenheid.VkeVolume                                 = BronVrdEenheid.VkeVolume,
    NieuwVrdEenheid.VkeVolumePer                              = BronVrdEenheid.VkeVolumePer
  from tabVerkoopEenheid BronVrdEenheid
  where BronVrdEenheid.VkeArtGid = @BronArtGid and
  BronVrdEenheid.VkeIsVoorraadEenheid = 1 and
  NieuwVrdEenheid.VkeArtGid = @NieuwArtGid and
  NieuwVrdEenheid.VkeIsVoorraadEenheid = 1;

  //call Trace('ArtikelKopieren > tabPrijsAfspraak');
  //with auto name werkt niet omdat bij de select PraArtGid in where zit, maar in de veldenlijst dit veld een nieuwe waarde moet krijgen
  insert into tabPrijsAfspraak (
    PraArtGid,
    PraDebGrpGid,
    PraVkeGid,
    //PraGid,
    PraIsInclBtw,
    PraKortingsBedrag,
    PraKortingsPerc,
    PraNawGid,
    PraOpbrGrpGid,
    PraOpm,
    PraSoort,
    PraStfKopGid,
    PraValNummer,
    PraVerkoopPrijs )
  select
    @NieuwArtGid,                 //verwijzing naar nieuwe artgid
    PraDebGrpGid,
    (Select VkeGid from tabVerkoopEenheid where vkeArtGid=@NieuwArtGid and vkeVerkoopeenheid = (Select vkeVerkoopeenheid from tabVerkoopeenheid where VkeGid = PraVkeGid)),
    //PraGid,                     //niet kopieren
    PraIsInclBtw,
    PraKortingsBedrag,
    PraKortingsPerc,
    PraNawGid,
    PraOpbrGrpGid,
    PraOpm,
    PraSoort,
    PraStfKopGid,
    PraValNummer,
    PraVerkoopPrijs
  from tabPrijsAfspraak
  where (PraArtGid = @BronArtGid  AND PraNawGid is null AND PraOpbrGrpGid is null AND PraDebGrpGid is null);

  //call Trace('ArtikelKopieren > tabArtikelTeksten');
  insert into tabArtikelTeksten (
    ArtTaalGid,
    ArtTekst,
    ArtTekstArtGid,
    ArtTekstDocSoort
    //ArtTekstGid
     )
   select
    ArtTaalGid,
    ArtTekst,
    @NieuwArtGid,                 //verwijzing naar nieuwe artgid
    ArtTekstDocSoort
    //ArtTekstGid                 //niet kopieren
  from tabArtikelTeksten
  where ArtTekstArtGid = @BronArtGid;

  //call Trace('ArtikelKopieren > tabArtikelLeveranciers + eenheden');
  for @Cursor AS CURSOR_ArtikelLeveranciersOvernemen CURSOR FOR
    select
      ArtLevGid          @CursArtLevGid,
      ArtLevArtGid       @CursArtLevArtGid,
      ArtLevNawGid       @CursArtLevNawGid,
      ArtLevIsDefault    @CursArtLevIsDefault
    from
      tabArtikelLeverancier
    where
          ArtLevArtGid = @BronArtGid
      and ((@DefaultLevEenhKopieren=1 and ArtLevIsDefault=1) or (@OverigeLevEenhKopieren=1))
    //let op: order by op dit veld, zodat de default leverancier als eerst wordt toegevoegd. Als dit niet gebeurt dan wordt de een niet-default leverancier default gemaakt (onnodig)
    //totdat de echte default toegevoegd wordt (dan moet die niet-default WEER geupdate worden om hem weer niet-default te maken).
    order by
      ArtLevIsDefault desc, ArtLevGid
  for read only
  do
    set @NieuwArtLevGid = null;

    //leverancier per stuk toevoegen, zodat het laatste gidje gebruikt kan worden voor het toevoegen van de eenheden.
    insert into tabArtikelLeverancier
           (ArtLevArtGid, ArtLevNawGid     , ArtLevIsDefault)
    values (@NieuwArtGid, @CursArtLevNawGid, @CursArtLevIsDefault);

    set @NieuwArtLevGid = @@Identity;

    //als de EAN-code nog niet is aangemaakt dan aanmaken als we de default leverancier kopieren (ean-code rubriek staat
    //op artikelkopieren-scherm namelijk binnen de checkbox kopieren standaardleverancier/eenheid
    if @CursArtLevIsDefault=1 then
      if @NieuwArtEanGid is null and @NieuwArtEanCode <> '' then
        insert into tabArtikelEan
               (ArtEanArtGid, ArtEanCode      , ArtEanIsDefault)
        values (@NieuwArtGid, @NieuwArtEanCode, 0);

        set @NieuwArtEanGid = @@Identity;
      end if;
    end if;


    //eenheden van leverancier overnemen
    //let op: AldArtEanGid mag NIET overgenomen worden!! is artikelgebonden en EAN-codes kunnen maar bij 1 artikel voorkomen; EAN-code alleen invullen indien deze aangemaakt moest worden voor de defaultlev/eenheid
    insert into tabArtikelLeverancierDetail
           (AldArtLevGid           , AldValNummer            , AldNstfKopGid                     , AldInkoopEenheid      , AldInkoopEenheidBijLeverancier,
            AldAantalKanVerschillen, AldArtCodeBijLeverancier,
            AldBedragToeslag       , AldBerekeningKostprijs, AldBestelGrootte,
            AldFactorKostprijs     , AldHeeftEigenInkoopprijs, AldInkoopPrijs                    , AldInkoopPrijsPer     , AldIsDefaultInkoopEenheidBijLev,
            AldKortingBedrag       , AldKortingPercentage    , AldKortingSoort                   , AldKwaliteit          , AldLevertijd,
            AldMinimumAfname       , AldOmsBijLeverancier    , AldVoorraadEenhedenInInkoopEenheid, AldOpm,
            AldArtEanGid, AldDirecteLevering, AldLndGidCBSOorsprong)
    select
      @NieuwArtLevGid        , AldValNummer            , AldNstfKopGid                     , AldInkoopEenheid      , AldInkoopEenheidBijLeverancier,
      AldAantalKanVerschillen, if ArtLevIsDefault=1 and AldIsDefaultInkoopEenheidBijLev=1 then @NieuwArtCodeBijLev else AldArtCodeBijLeverancier endif,
      AldBedragToeslag       , AldBerekeningKostprijs  , AldBestelGrootte,
      AldFactorKostprijs     , AldHeeftEigenInkoopprijs, AldInkoopPrijs                    , AldInkoopPrijsPer     , AldIsDefaultInkoopEenheidBijLev,
      AldKortingBedrag       , AldKortingPercentage    , AldKortingSoort                   , AldKwaliteit          , AldLevertijd,
      AldMinimumAfname       , AldOmsBijLeverancier    , AldVoorraadEenhedenInInkoopEenheid, AldOpm,
      if ArtLevIsDefault=1 and AldIsDefaultInkoopEenheidBijLev=1 then @NieuwArtEanGid endif, AldDirecteLevering, AldLndGidCBSOorsprong
    from
      tabArtikelLeverancierDetail
      inner join tabArtikelLeverancier on (ArtLevGid=AldArtLevGid)
    where
          AldArtLevGid = @CursArtLevGid
      and ((@DefaultLevEenhKopieren=1 and AldIsDefaultInkoopEenheidBijLev=1) or (@OverigeLevEenhKopieren=1))
    order by
     AldIsDefaultInkoopEenheidBijLev desc, AldGid;
  end for;

  //call Trace('ArtikelKopieren > tabArtikelMagazijn');
  insert into tabArtikelMagazijn (
    //heleboel velden niet meenemen
    ArtMagArtGid,
    ArtMagMagGid,
    ArtMagMinimumVoorraad,
    ArtMagMaximumVoorraad)
  select
    //heleboel velden niet meenemen
    @NieuwArtGid,                 //verwijzing naar nieuwe artgid
    ArtMagMagGid,
    ArtMagMinimumVoorraad,
    ArtMagMaximumVoorraad
  from tabArtikelMagazijn
  where ArtMagArtGid= @BronArtGid;

  //call Trace('ArtikelKopieren > tabArtikelVervolg');
  insert into tabArtikelVervolg (
    ArtVlgAantal,
    ArtVlgDetailArtGid,
    //ArtVlgGid,
    ArtVlgMasterArtGid )
  select
    ArtVlgAantal,
    ArtVlgDetailArtGid,
    //ArtVlgGid,                  //niet kopieren
    @NieuwArtGid                  //verwijzing naar nieuwe artgid
  from tabArtikelVervolg
  where ArtVlgMasterArtGid = @BronArtGid;

  //call Trace('ArtikelKopieren > tabArtikelPartij');
  if @PartijenKopieren <> 0 then
    insert into tabArtikelPartij (ArtPartijArtGid, ArtPartijDatumOntvangst, ArtPartijDatumProductie, ArtPartijInkoopPrijs,  ArtPartijInkoopValNummer,
                                  ArtPartijInvTekstOpFactuur, ArtPartijIsGeblokkeerdVoorInkoop, ArtPartijIsGeblokkeerdVoorVerkoop, ArtPartijKortingsBedrag,
                                  ArtPartijKortingsPerc, ArtPartijKostprijsEx, ArtPartijnawGid, ArtPartijNrBijLeverancier, ArtPartijNummer, ArtPartijOms,
                                  ArtPartijOpm, ArtPartijTHTdatum, ArtPartijVerkoopBtwCode, ArtPartijVerkoopPrijs, ArtPartijVerkoopPrijsIsIncl, ArtPartijVrijTmDatum,
                                  ArtPartijVrijVanafDatum, ArtPartijLndGidCbsOorsprong)
    select @NieuwArtGid, ArtPartijDatumOntvangst, ArtPartijDatumProductie, ArtPartijInkoopPrijs,  ArtPartijInkoopValNummer,
           ArtPartijInvTekstOpFactuur, ArtPartijIsGeblokkeerdVoorInkoop, ArtPartijIsGeblokkeerdVoorVerkoop, ArtPartijKortingsBedrag,
           ArtPartijKortingsPerc, ArtPartijKostprijsEx, ArtPartijnawGid, ArtPartijNrBijLeverancier, ArtPartijNummer, ArtPartijOms,
           ArtPartijOpm, ArtPartijTHTdatum, ArtPartijVerkoopBtwCode, ArtPartijVerkoopPrijs, ArtPartijVerkoopPrijsIsIncl, ArtPartijVrijTmDatum,
           ArtPartijVrijVanafDatum, ArtPartijLndGidCbsOorsprong
    from   tabArtikel inner join tabArtikelPartij on (ArtPartijArtGid = ArtGid) where ArtGid = @BronArtGid;
  end if;

  if @WebwinkelsKopieren = 1 then
    //call Trace('ArtikelKopieren > Webshops');
    insert into tabWebArtikel (WArtArtGid, WArtWscGid) select @NieuwArtGid, WArtWscGid from tabWebArtikel where WArtArtGid = @BronArtGid;
  end if;

  //call Trace('ArtikelKopieren > Vrije rubrieken');
  call VrKopieerRecord('ART',0,0,'ART',0,0,@BronArtGid,@NieuwArtGid);

  //call Trace('ArtikelKopieren > tabArtikelBTWAfstandsVerkopen');
  insert into tabArtikelBTWAfstandsVerkopen
  (
  	AbaArtGid,
  	AbaLndGid,
  	AbaBtwCodeVanuitAnderEULand,
  	AbaBtwCodeVanuitEigenLand,
  	AbaBtwCodeVanuitLandVanAangifte,
  	AbaBtwCodeVanuitNietEULand
  )
  select
    @NieuwArtGid,
  	AbaLndGid,
  	AbaBtwCodeVanuitAnderEULand,
  	AbaBtwCodeVanuitEigenLand,
  	AbaBtwCodeVanuitLandVanAangifte,
  	AbaBtwCodeVanuitNietEULand
  from tabArtikelBTWAfstandsVerkopen
  where AbaArtGid = @BronArtGid;

  set @@ErrorTextProcedure = 'ArtikelKopieren';
  //call TraceEind(@@ErrorTextProcedure + ' > @NieuwArtGid = ' + string(@NieuwArtGid));

end;

//call ArtikelKopieren(53,'drukwerk17','17',null)
//call Artikelkopieren(3600169, '0001',1,'','A-000-0111',0,0,@dummy);
