create or replace procedure ArtikelPrijsAfronden(in @ArtGid integer, inout @Prijs numeric(15,3), inout @AantalDecimalen smallint)
begin
  //call TraceBegin('ArtikelPrijsAfronden');

  //Indien @AantalDecimalen null is, dan lezen we het aantal decimalen uit het artikelbestand
  if @AantalDecimalen is null then
    select ArtAantDecPrijzen into @AantalDecimalen from tabArtikel where ArtGid = @ArtGid;
  end if;

  set @Prijs = ArtikelPrijsAfronding(@Prijs, @AantalDecimalen);

  //call TraceEind('ArtikelPrijsAfronden');
end;


create or replace function ArtikelPrijsAfronding(
  in @Prijs numeric(15,3),
  in @AantalDecimalen smallint
) returns numeric(15,3)
//MR 13-feb-2018  : Deze function berekent de prijsafronding van de meegegeven prijs
//Aanleiding      : PrijzenBerekenenObvRecepten gebruikt deze function voor het bepalen van de verkoopprijs inclusief de afronding.
//Test            : select ArtikelPrijsAfronding(11.00,2) from dummy;
begin
  declare @PrijsAfgerond numeric(15,3);
  //call TraceBegin('ArtikelPrijsAfronding');

  select case ArtVastSoortPrijsAfronding
           when 0 then  round (@Prijs /  PrAfrAfrondenOp, 0) * PrAfrAfrondenOp + PrAfrBedragBijAf                                   //Standaard
           when 1 then  round((@Prijs + (PrAfrAfrondenOp / 2.00000001)) / PrAfrAfrondenOp, 0) * PrAfrAfrondenOp  + PrAfrBedragBijAf //Naar boven
           when 2 then  floor(@Prijs / PrAfrAfrondenOp) * PrAfrAfrondenOp  + PrAfrBedragBijAf                                       //Naar beneden
           else @Prijs
         end into @PrijsAfgerond
  from   tabartikelvastegegevens, tabPrijsafrondingen
  where  ArtVastSoort = 2 and @Prijs between PrAfrVanBedrag and PrAfrTotBedrag;

  //call TraceEind('ArtikelPrijsAfronding');
  return round(isNull(@PrijsAfgerond, @Prijs), isNull(@AantalDecimalen, 2));
end;

//------- Verwerk journaalregels vanuit ASCII-bestand
create or replace procedure AsciiJournaalVerwerken()
begin
  declare @AjLineNumber integer;
  declare @BjGid integer;
  declare @Pernr integer;
  declare @DgbCode nchar(10);
  declare @DgbGid integer;
  declare @RksGid integer;
  declare @DefaultSoort integer;
  declare @Boekdatum date;
  declare @BoekStukdatum date;
  declare @Stuknummer numeric(10,0);
  declare @JPOmschrijving nchar(40);
  declare @HulpRekening nchar(28);
  declare @Referentie nchar(40);

  declare @RekeningNummer      nchar(28);
  declare @StukVolgnr          integer;
  declare @OmsJournaalRegel    nchar(40);
  declare @IsCreditBoeking     integer;
  declare @Aantal              numeric(15,2);
  declare @BasisBedrag         numeric(15,2);
  declare @ValutaBedrag        numeric(15,2);
  declare @ValNummer           integer;
  declare @FactuurDatum        date;
  declare @VervalDatum         date;
  declare @Betalingskenmerk    nchar(24);
  declare @HulpRekSoort        integer;
  declare @HulpRekValNummer    integer;
  declare @HulpRekIsCredit     integer;
  declare @HulpRekBasisBedrag  numeric(15,2);
  declare @HulpRekValutaBedrag numeric(15,2);
  declare @HulpRekBtwCode      integer;

  declare @VorigAjLineNumber integer;
  declare @VorigDgbCode nchar(10);
  declare @VorigStuknummer numeric(10,0);
  declare @VorigJPOmschrijving nchar(40);
  declare @Boekgang      integer;
  declare @VorigBoekGang integer;

  declare @BoekGangOpen smallint;
  declare @JpOpen smallint;
  declare @OrigineelStuknummer numeric(10,0);
  declare @NieuweFactuurBoeking smallint;

  declare cursor_tmpAsciiJournaal cursor for
    select tmpAjBoekgangNummer, tmpAjLineNumber, tmpAJBoekBjGid, tmpAJDagboekCode, tmpAjBoekStukDatum, tmpAjBoekstukNummer, tmpAjJournaalPostOms,
           tmpAJHulpRekeningnrText, tmpAjReferentie, tmpAjPeriode, tmpAjRekeningNrText,
           tmpAjStukVolgnr, tmpAjOmsJournaalRegel, tmpAjIsCreditBoeking, tmpAjAantal, tmpAjBasisBedrag,
           tmpAjValutaBedrag, (select ValNummer from tabValuta where ValCode = tmpAjValCode), tmpAjFactuurDatum, tmpAjVervalDatum, tmpAjBetalingskenmerk,
           tmpAJHulpRekSoort, (select ValNummer from tabValuta where ValCode = tmpAjHulpRekValCode), tmpAjHulpRekIsCredit,
           tmpAjHulpRekBasisBedrag, tmpAjHulpRekValutaBedrag, tmpAjHulpRekBtwCode, tmpAjBoekdatum
    from   tmpAsciiJournaal order by tmpAjLineNumber
  for read only;

  set @@ErrorTextProcedure = 'AsciiJournaalVerwerken > @AjLineNumber='+String(@AjLineNumber);
  //call TraceBegin(@@ErrorTextProcedure);

  if (@@ModuleD1 <> 0) then //Dealer Demo --> er mogen wel meer journaalregels worden ingelezen
    Set @@AllowInsert = 1;
  end if;

  set @VorigAjLineNumber = -1;
  set @VorigDgbCode = '';
  set @VorigStukNummer = -1;
  set @VorigBoekGang   = -1;
  set @BoekGangOpen = 0;
  set @JpOpen       = 0;

  //Indien de boekstukdatum leeg is, dan vullen we de boekstukdatum met de boekdatum van de regel
  update tmpAsciiJournaal set tmpAjBoekStukDatum = tmpAjBoekdatum where tmpAjBoekStukDatum is null;

  open cursor_tmpAsciiJournaal;
  loopje1:
  loop

    fetch next cursor_tmpAsciiJournaal
          into @Boekgang, @AjLineNumber, @BjGid, @DgbCode, @BoekStukDatum, @StukNummer, @JPOmschrijving, @HulpRekening, @Referentie, @Pernr, @RekeningNummer,
               @StukVolgnr, @OmsJournaalRegel, @IsCreditBoeking, @Aantal, @BasisBedrag, @ValutaBedrag, @ValNummer, @FactuurDatum, @VervalDatum, @Betalingskenmerk,
               @HulpRekSoort, @HulpRekValNummer, @HulpRekIsCredit, @HulpRekBasisBedrag, @HulpRekValutaBedrag, @HulpRekBtwCode, @BoekDatum;

    if sqlstate = '02000' then
      leave loopje1;
    end if;

    set @OrigineelStuknummer = @StukNummer;

    set @@AsciiJournaalLineNumber = @AjLineNumber;
    //call Trace('@AjLineNumber = '+string(@AjLineNumber));

    set @NieuweFactuurBoeking = 0;

    //call Trace('Boekingsgang, DgbCode='+@DgbCode);
    if (@DgbCode <> @VorigDgbCode) or (@VorigBoekgang <> @Boekgang) then
      if @BoekGangOpen <> 0 then
        //call Trace('Afsluiten boekingsgang');
        update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangGid = @@BoekGangGid;
        set @JpOpen = 0;
      end if;
      //call Trace('Boekingsgang toevoegen');
      insert into tabBoekingsgang(BoekGangBjGid, BoekgangBronId, IsBoekGangDefinitief) values (@BjGid, 7, 0);

      //Sla BoekgangGid op in 1 regel, om bij fouten de boekingsgangen op te ruimen
      update tmpAsciiJournaal set tmpAjBoekGangGid = @@BoekGangGid where tmpAjLineNumber = @AjLineNumber;

      set @BoekGangOpen = 1;
      set @VorigStukNummer = -1;
      set @VorigBoekgang = @Boekgang;
      select DgbGid into @DgbGid from tabDagboek where DgbCode = @DgbCode;
    end if;

    //call Trace('Journaalpost, @BoekDatum='+string(@BoekDatum)+', @StukNummer='+string(@StukNummer)+' @VorigStukNummer='+string(@VorigStukNummer)+', @JPomschrijving='+@JPOmschrijving);
    if (@JpOpen = 0) or (IsNull(@Stuknummer, -1) <> IsNull(@VorigStuknummer, -1)) or (@VorigJPOmschrijving <> @JPOmschrijving) then
      if @JpOpen <> 0 then
        //call Trace('Afsluiten journaalpost');
        update tabJournaalpost set JpIsInGebruik = 0 where JpGid = @@JpGid;
      end if;
      //call Trace('Journaalpost toevoegen');
      if @Stuknummer is null then
        //call Trace('Stuknummer genereren');
        call BoekstuknummerGenereren(@BjGid, @DgbGid, @StukNummer)
      end if;
      insert into tabJournaalpost(JpBoekGangGid, JpDgbGid, BoekDatum, BoekStukNummer, OmsJournaalPost, JpBjGid, JpPernr)
      select @@BoekGangGid, @DgbGid, @BoekStukdatum, @StukNummer, @JPOmschrijving, @Bjgid, @Pernr;
      set @JpOpen = 1;
    end if;

    select RksGid, DefaultSoort into @RksGid, @DefaultSoort from tabRekeningschema where RksInvoer = @RekeningNummer;

    //Indien factnr leeg is en het gaat om deb of cred, dan het stuknummer vd jp in factnr zetten:
    if (@DefaultSoort in (6,7)) and (IsNull(@Referentie, '')='') then
      //call Trace('Referentie is leeg --> vullen met stuknummer');
      select BoekstukNummer into @Referentie from tabJournaalpost where JpGid = @@JpGid;
    end if;

    //---Begin incasso gedeelte---
    //Ivm [rev. 1.02] van module 816a:
    //Is optie incasso actief?
    if (select IsModuleActive('n2')) <> 0 then
      //Is het een debiteur?
      if @DefaultSoort = 6 then
        //Gaat default Btc van debiteur via incasso?
        if (select SoortFactuurBtc from tabBetalingsConditie inner join tabNawFile on BtcNummer = NawFilBtcNummer and NawFilNummer = @RekeningNummer) = 3 then
          //Controle of het een nieuwe factuurboeking is
          if (select count(*) from tabOpenstaandePost where OspFactuurNummer = @Referentie and OspFactuurNummer_Lengte = Length(@Referentie) and OspRksGID = @RksGid) = 0 then
            set @NieuweFactuurBoeking = 1;
          end if;
        end if;
      end if;
    end if;
    //---Einde incasso gedeelte---

    //call Trace('Journaalregel toevoegen');
    insert into tabJournaalregel(JrJpGid, JrRksGid, StukVolgnr, JrBoekdatum,
                                 OmsJournaalRegel, JrReferentie, SoortBoeking, IsCreditBoeking, Aantal, JrBasisBedrag,
                                 JrValutaBedrag, JrValNummer, JrFactuurDatum, JrVervalDatum, JrBetalingsKenmerk, JrIsViaIncasso)
    select @@JpGid, @RksGid, @StukVolgnr, @Boekdatum,
           @OmsJournaalRegel, @Referentie, 0, @IsCreditBoeking, @Aantal, @BasisBedrag,
           @ValutaBedrag, @ValNummer, @FactuurDatum, @VervalDatum, @Betalingskenmerk, 0;

    //call Trace('Hulprekening');
    if IsNull(@HulpRekening, '') <> '' then
      //call Trace('Hulprekening toevoegen');
      insert into tabHulpRekening(HulpRekJrGid, HulpRekSoort, HulpRekRksGid, HulpRekValNummer, HulpRekIsCredit,
                                  HulpRekBasisBedrag, HulpRekValutaBedrag, HulpRekBtwCode)
      select @@JrGid, @HulpRekSoort, RksGid, @HulpRekValNummer, @HulpRekIsCredit, @HulpRekBasisBedrag, @HulpRekValutaBedrag, @HulpRekBtwCode
      from   tabRekeningschema where RksInvoer = @HulpRekening;
    end if;

    //---Begin incasso gedeelte---
    //OSP update
    if @NieuweFactuurBoeking = 1 then
      update tabOpenstaandePost set OspSoortFactuur = 3,
                                    OspIncNawRekGid = (select nawrekgid from tabnawrekening where locate(nawreksoort, 'I') <> 0 and  nawreknawgid = (select nawgid from tabnaw inner join tabnawfile on nawgid = nawfilnawgid and nawfilnummer = @RekeningNummer)),
                                    OspIncDatum     = @VervalDatum
                                where OspFactuurNummer = @Referentie and OspFactuurNummer_Lengte = Length(@Referentie) and OspRksGid = @RksGid;
    end if;
    //---Einde incasso gedeelte---

    set @VorigAjLineNumber = @AjLineNumber;
    set @VorigDgbCode      = @DgbCode;
    set @VorigStuknummer   = @OrigineelStuknummer;
    set @VorigJPOmschrijving=@JPOmschrijving;

  end Loop loopje1;
  close cursor_tmpAsciiJournaal;

  if @JpOpen <> 0 then
    //call Trace('Afsluiten journaalpost');
    update tabJournaalpost set JpIsInGebruik = 0 where JpGid = @@JpGid;
  end if;

  if @BoekGangOpen <> 0 then
    //call Trace('Afsluiten boekingsgang');
    update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangGid = @@BoekGangGid;
  end if;

  Set @@AllowInsert = 0;

  set @@ErrorTextProcedure = 'AsciiJournaalVerwerken';
  //call TraceEind(@@ErrorTextProcedure);

end;


//------- Maak de koppeling tussen grootboekrekening en balanscode
create or replace procedure BalansCodeKoppelingUpdate(in @RksGid integer, in @BalansCode integer, in @BlGid integer)
begin

  set @@ErrorTextProcedure = 'BalansCodeKoppelingUpdate > @RksGid='+string(@RksGid)+', @BalansCode='+string(@BalansCode)+', @BlGid='+string(@BlGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if @BlGid is null then
    delete tabBalansCodeRekening where BlRekBlCode=@BalansCode and BlRksGid=@RksGid;
  else
    if exists (select 1 from tabBalansCodeRekening where BlRekBlCode=@BalansCode and BlRksGid=@RksGid) then
      update tabBalansCodeRekening set BlRekBlGid=@BlGid where BlRekBlCode=@BalansCode and BlRksGid=@RksGid;
    else
      if exists(select 1 from tabRekeningschema where RksGid = @RksGid) then
        insert into tabBalansCodeRekening (BlRekBlCode, BlRksGid, BlRekBlGid) values (@BalansCode, @RksGid, @BlGid);
      end if;
    end if;
  end if;

  set @@ErrorTextProcedure = 'BalansCodeKoppelingUpdate';
  //call TraceEind(@@ErrorTextProcedure);

end;


//----------- Controleer rekeningen voor een evt. update in balansomschrijvingen (speciaal voor kmBalansOmkschrijvingen)
create or replace procedure BalansOmschrijvingen_CheckRange(in @RksGid integer, in @BlGid integer, inout @KstpKstdExistInRks smallint, inout @RekExistInBlCode smallint, inout @KstpKstdExistInBlCode smallint)
begin
  declare @RksNummer nchar(10);
  declare @BlCode integer;
  declare @KstpGid integer;
  declare @KstdGid integer;
  declare @OldRubriek nchar(3);
  declare @OldParagraaf nchar(3);
  declare @OldSubParagraaf nchar(3);
  declare @NewRubriek nchar(3);
  declare @NewParagraaf nchar(3);
  declare @NewSubParagraaf nchar(3);

  set @@ErrorTextProcedure = 'BalansOmschrijvingen_CheckRange > @RksGid='+string(@RksGid)+', @BlGid='+string(@BlGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //Test of huidig rksnummer van meegegeven rksGid een kostenplaats of kostendrager heeft en zelf niet een kostenplaats of kostendrager is
  select RksNummer, RksKstpGid, RksKstdGid into @RksNummer,@KstpGid,@KstdGid from tabRekeningschema where RksGid = @RksGid;
  set @KstpKstdExistInRks=0;
  if(@KstpGid is null) and(@KstdGid is null) then
    if exists(select 1 from tabRekeningschema where RksNummer = @RksNummer and RksGid <> @RksGid) then
      set @KstpKstdExistInRks=1
    end if
  end if;

  // Controleer of rekening in de balanscode wordt gebruikt
  select Rubriek,Paragraaf,Subparagraaf into @NewRubriek,@NewParagraaf,@NewSubparagraaf from tabBalansCodeDetail where BlGid = @BlGid;
  select DetailBlCode into @BlCode from tabBalansCodeDetail where BlGid = @BlGid;

  if exists(select 1 from tabBalansCodeDetail,tabBalansCodeRekening where
      DetailBlCode = @BlCode and BlRekBlGid = BlGid and
      (rubriek <> @NewRubriek or(Paragraaf <> @NewParagraaf and IsNull(Paragraaf,'') <> '') or
      (Subparagraaf <> @NewSubParagraaf and IsNull(Subparagraaf,'') <> '')) and BlRksGid = @RksGid) then
    set @RekExistInBlCode=1
  else
    set @RekExistInBlCode=0
  end if;

  //Test of de kostenplaatsen en/of kostendragers in deze balanscode worden gebruikt
  set @KstpKstdExistInBlCode=0;
  if(@KstpGid is null) and(@KstdGid is null) then
    if exists(select 1 from tabBalansCodeDetail,tabBalansCodeRekening,tabRekeningschema where
        RksGid = BlRksGid and BlRekBlGid = BlGid and DetailBlCode = @BlCode and RksNummer = @RksNummer and RksGid <> @RksGid) then
      //Dus: als 1 van de kosten gebruikt in de balanscode *niet* dezelfde rub/par/sub, dan inderdaad gebruikt
      if exists(select 1 from tabBalansCodeDetail,tabBalansCodeRekening where
          DetailBlCode = @BlCode and BlRekBlGid = BlGid and
          (rubriek <> @NewRubriek or(Paragraaf <> @NewParagraaf and IsNull(Paragraaf,'') <> '') or
          (Subparagraaf <> @NewSubParagraaf and IsNull(Subparagraaf,'') <> '')) and
          BlRksGid = any(select RksGid from tabBalansCodeDetail,tabBalansCodeRekening,tabRekeningschema where
            RksGid = BlRksGid and BlRekBlGid = BlGid and DetailBlCode = @BlCode and RksNummer = @RksNummer and RksGid <> @RksGid)) then
        set @KstpKstdExistInBlCode=1
      end if
    end if
  end if;

  set @@ErrorTextProcedure = 'BalansOmschrijvingen_CheckRange > @KstpKstdExistInRks='+string(@KstpKstdExistInRks)+', @RekExistInBlCode='+string(@RekExistInBlCode)+', @KstpKstdExistInBlCode='+string(@KstpKstdExistInBlCode);
  //call TraceEind(@@ErrorTextProcedure);

end;


//-------- Speciaal gebouwd voor module balansomschrijvingen
create or replace procedure BalansOmschrijvingen_UpdateRange(in @RksGid integer, in @BlGid integer, in @OokKstpTesten smallint, in @OverschrijfRekening smallint)
begin
  declare @RksNummer nchar(10);
  declare @BlCode integer;

  set @@ErrorTextProcedure = 'BalansOmschrijvingen_UpdateRange > @RksGid='+string(@RksGid)+', @BlGid='+string(@BlGid)+', @OokKstpTesten='+string(@OokKstpTesten)+', @OverschrijfRekening='+string(@OverschrijfRekening);
  //call TraceBegin(@@ErrorTextProcedure);

  select RksNummer into @RksNummer from tabRekeningschema where RksGid = @RksGid;
  select DetailBlCode into @BlCode from tabBalansCodeDetail where BlGid = @BlGid;

  //Als rekeningen overschreven mogen worden, dan eerst verwijderen en vervolgens records toevoegen in tabBalansCodeRekening
  if @OverschrijfRekening <> 0 then
    if @OokKstpTesten = 0 then
      delete from tabBalansCodeRekening
             from tabBalansCodeDetail join tabBalansCodeRekening on(BlRekBlGid = BlGid) join tabRekeningschema on(RksGid = BlRksGid) where DetailBlCode = @BlCode and RksGid = @RksGid
    else
      delete from tabBalansCodeRekening
             from tabBalansCodeDetail join tabBalansCodeRekening on(BlRekBlGid = BlGid) join tabRekeningschema on(RksGid = BlRksGid) where DetailBlCode = @BlCode and RksNummer = @RksNummer
    end if
  end if;
  if @OokKstpTesten = 0 then
    insert into tabBalansCodeRekening(BlRekBlGid,BlRksGid)
    select @BlGid,RksGid from tabRekeningschema
    where  RksGid = @RksGid and not RksGid =  any(select BlRksGid from tabBalansCodeRekening join tabBalansCodeDetail on(BlGid = BlRekBlGid) where DetailBlCode = @BlCode)
  else
    insert into tabBalansCodeRekening(BlRekBlGid,BlRksGid)
    select @BlGid,RksGid from tabRekeningschema
    where  RksNummer = @RksNummer and not RksGid = any(select BlRksGid from tabBalansCodeRekening join tabBalansCodeDetail on(BlGid = BlRekBlGid) where DetailBlCode = @BlCode)
  end if;

  set @@ErrorTextProcedure = 'BalansOmschrijvingen_UpdateRange';
  //call TraceEind(@@ErrorTextProcedure);

end;


//--------- Geef nummer en code van de basisvaluta terug
create or replace procedure BasisValuta(inout @ValNummer integer, inout @ValCode nchar(3))
begin
  set @@ErrorTextProcedure = 'BasisValuta > ';
