  //Er wordt gebruikt gemaakt van globale variabelen om pakket te versnellen
  set @Valnummer = @@BasisValutaNummer;
  set @ValCode   = @@BasisValutaCode;

  set @@ErrorTextProcedure = 'BasisValuta';
  //call TraceEind(@@ErrorTextProcedure + ' > @ValNummer = ' + string(@ValNummer) + ', @ValCode = ' + @ValCode);
end;


create or replace function Bedragonderweg(in @RksGid integer, in @IsCrediteur integer, in @Factuurnummer nchar(40), @FactuurNummer_Lengte integer)
returns numeric(15,2)
begin
  declare @Bedrag              numeric(15,2);
  declare @FactorDebiteurenOsp integer;

  set @@ErrorTextProcedure = 'BedragonderwegBerekenen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@RksGid = ' + string(@RksGid));

  if @IsCrediteur = 0 /*debiteur*/ then
    set @FactorDebiteurenOsp = -1;
  else
    set @FactorDebiteurenOsp = 1;
  end if;

  set @Bedrag =
    // Bedrag uit de incassoregels (eigenlijk alleen voor debiteuren)
    if @IsCrediteur = 0 /*debiteur*/ then
      IsNull((
        select
          sum(IncRglTeIncasseren)
        from
          tabIncassoRegel
        where     IncRglRksGid               = @RksGid               /*Alleen indien van deze debiteur*/
              and IncRglFactuurNummer_Lengte = @FactuurNummer_Lengte /*Alleen betreffende factuur*/
              and IncRglFactuurNummer        = @FactuurNummer        /*Alleen betreffende factuur*/
              and IncRglStatus = 1                                                /*Opdracht aangemaakt*/
      ), 0)
      +
      IsNull((
        select
          sum(IrvTeIncasseren)
        from
          tabIncassoRegelVerzameld
        inner join tabIncassoRegel on IncRglGid = IrvIncRglGid
        where     IncRglRksGid               = @RksGid               /*Alleen indien van deze debiteur*/
              and IrvFactuurNummer_Lengte    = @FactuurNummer_Lengte /*Alleen betreffende factuur*/
              and IrvFactuurNummer           = @FactuurNummer        /*Alleen betreffende factuur*/
              and IncRglStatus = 1                                                /*Opdracht aangemaakt*/
      ), 0)
    else
      0.00 //Crediteuren kunnen niet in incassoregels zitten
    endif
    +
      // gegevens uit betalingsopdrachten
        IsNull((
             select
              sum(BetRglTeBetalenInValOsp + BetRglVerschilAfboeken * BetRglVerschilAfboekenBedragInValOsp) * @FactorDebiteurenOsp
             from
              tabBetalingRegel
             where
              BetRglRksGid                   = @RksGid               /*Alleen indien van deze debiteur*/
              and BetRglFactuurNummer_Lengte = @FactuurNummer_Lengte /*Alleen betreffende factuur*/
              and BetRglFactuurNummer        = @FactuurNummer        /*Alleen betreffende factuur*/
              and BetRglStatus = 1                                                /*Opdracht*/
            ), 0)
            +
            isnull((
             select
              sum(BetVerzTeBetalenInValOsp + BetVerzVerschilAfboeken * BetVerzVerschilAfboekenBedragInValOsp) * @FactorDebiteurenOsp
             from
              tabBetalingRegel
              inner join tabBetalingVerzameld on (BetVerzBetRglGid = BetRglGid)
             where
              BetRglRksGid                    = @RksGid               /*Alleen indien van deze debiteur*/
              and BetVerzFactuurNummer_Lengte = @FactuurNummer_Lengte /*Alleen betreffende factuur*/
              and BetVerzFactuurNummer        = @FactuurNummer        /*Alleen betreffende factuur*/
              and BetRglStatus = 1                                                 /*Opdracht*/
            ), 0);
  set @@ErrorTextProcedure = 'BedragonderwegBerekenen';
  //call TraceEind(@@ErrorTextProcedure + ' > @Bedrag = ' + string(@Bedrag));

  return @Bedrag;
end;


create or replace procedure BepaalBestelregelAantallenObvMagOntRegel(in @MokGid integer, in @MagOntGid integer, in @BstRglGid integer, in @MagOntAantalOpScherm numeric(15,3), in @MagOntAantalCorrectieOpScherm numeric(15,3))

result
(
  DeelbaarTotaalAantalOntvangenOverigeOntv     smallint,
  DeelbaarTotaalAantalOntvangenDezeOntv        smallint,
  DeelbaarAantalNogTeOntvangen                 smallint,
  DeelbaarTotaalAantalCorrectieDezeOntv        smallint,
  DeelbaarTotaalAantalCorrectieOverigeOntv     smallint,

  BstRglSoort                                  smallint,
  ArtOmsEenheid                                nchar(20),
  BstRglInkoopEenheid                          nchar(20),
  BstRglArtikelNummerLeverancier               nchar(20),
  BstRglEANcode                                nchar(14),
  ArtAantDecAantallen                          integer,

  AantalBesteldInInkEenheden                   numeric(15,3),
  AantalBesteldInVoorrEenheden                 numeric(15,3),
  TotaalAantalOntvangenOverigeOntvInInkEenh    numeric(15,3),
  TotaalAantalOntvangenOverigeOntvInVoorrEenh  numeric(15,3),
  TotaalAantalOntvangenDezeOntvInInkEenh       numeric(15,3),
  TotaalAantalOntvangenDezeOntvInVoorrEenh     numeric(15,3),
  TotaalAantalCorrectieOverigeOntvInInkEenh    numeric(15,3),
  TotaalAantalCorrectieOverigeOntvInVoorrEenh  numeric(15,3),
  TotaalAantalCorrectieDezeOntvInInkEenh       numeric(15,3),
  TotaalAantalCorrectieDezeOntvInVoorrEenh     numeric(15,3),
  AantalNogTeOntvangenInInkEenh                numeric(15,3),
  AantalNogTeOntvangenInVoorrEenh              numeric(15,3),
  VoorraadEenhedenInInkoopEenheid              numeric(15,3)
)
begin
  declare @ErrText		                                  nchar(500);

  Declare @DeelbaarheidBepalen                          smallint;
  Declare @DeelbaarTotaalAantalOntvangenOverigeOntv     smallint;
  Declare @DeelbaarTotaalAantalOntvangenDezeOntv        smallint;
  Declare @DeelbaarAantalNogTeOntvangen                 smallint;
  Declare @DeelbaarTotaalAantalCorrectieDezeOntv        smallint;
  Declare @DeelbaarTotaalAantalCorrectieOverigeOntv     smallint;

  Declare @BstRglSoort                                  smallint;
  Declare @BstRglInkoopEenheid                          nchar(20);
  Declare @BstRglArtikelNummerLeverancier               nchar(20);
  Declare @BstRglEANcode                                nchar(14);
  Declare @BstRglVoorraadEenhedenInInkoopEenheid        numeric(15,3);
  Declare @BstRglAantalBesteld                          numeric(15,3);
  Declare @BstRglAantalOntvangenInVoorrEenh             numeric(15,3);
  Declare @BstRglAantalNogTeOntvangenInVoorrEenh        numeric(15,3);
  Declare @ArtOmsEenheid                                nchar(20);
  Declare @ArtAantDecAantallen                          numeric(15,3);

  Declare @AantalOntvInVoorrEenhDezeRegelInDb           numeric(15,3);
  Declare @AantalOntvInVoorrEenhDezeRegelInDbCorrectie  numeric(15,3);
  Declare @AantalBesteldInInkEenh                       numeric(15,3);
  Declare @AantalBesteldInVoorrEenh                     numeric(15,3);
  Declare @AantalOntvInInkEenhDezeRegel                 numeric(15,3);
  Declare @AantalOntvInVoorrEenhDezeRegel               numeric(15,3);
  Declare @AantalCorrInInkEenhDezeRegel                 numeric(15,3);
  Declare @AantalCorrInVoorrEenhDezeRegel               numeric(15,3);
  Declare @AantalNogTeOntvangenInInkEenh                numeric(15,3);
  Declare @AantalNogTeOntvangenInVoorrEenh              numeric(15,3);
  Declare @TotaalAantalOntvangenDezeOntvInVoorrEenh     numeric(15,3);
  Declare @TotaalAantalOntvangenDezeOntvInInkEenh       numeric(15,3);
  Declare @TotaalAantalOntvangenOverigeOntvInVoorrEenh  numeric(15,3);
  Declare @TotaalAantalOntvangenOverigeOntvInInkEenh    numeric(15,3);
  Declare @TotaalAantalCorrectieDezeOntvInVoorrEenh     numeric(15,3);
  Declare @TotaalAantalCorrectieDezeOntvInInkEenh       numeric(15,3);
  Declare @TotaalAantalCorrectieOverigeOntvInVoorrEenh  numeric(15,3);
  Declare @TotaalAantalCorrectieOverigeOntvInInkEenh    numeric(15,3);

  set @ErrText = 'BepaalBestelregelAantallenObvMagOntRegel(@MokGid='+ string(@MokGid) + ', @MagOntGid=' + string(@MagOntGid) + ', @BstRglGid=' + string(@BstRglGid) + ', @MagOntAantalOpScherm=' + string(@MagOntAantalOpScherm) + ', @MagOntAantalCorrectieOpScherm=' + string(@MagOntAantalCorrectieOpScherm) + ')';;
  set @@ErrorTextProcedure = @ErrText;
  //call TraceBegin(@@ErrorTextProcedure);


  //VARIABELEN INITIALISEREN OM NULL-VALUES TE VOORKOMEN
  set @AantalOntvInVoorrEenhDezeRegelInDb          = 0;
  set @AantalOntvInVoorrEenhDezeRegelInDbCorrectie = 0;
  set @AantalBesteldInInkEenh                      = 0;
  set @AantalBesteldInVoorrEenh                    = 0;
  set @AantalOntvInInkEenhDezeRegel                = 0;
  set @AantalOntvInVoorrEenhDezeRegel              = 0;
  set @AantalCorrInInkEenhDezeRegel                = 0;
  set @AantalCorrInVoorrEenhDezeRegel              = 0;
  set @AantalNogTeOntvangenInInkEenh               = 0;
  set @AantalNogTeOntvangenInVoorrEenh             = 0;
  set @TotaalAantalOntvangenDezeOntvInVoorrEenh    = 0;
  set @TotaalAantalOntvangenDezeOntvInInkEenh      = 0;
  set @TotaalAantalOntvangenOverigeOntvInVoorrEenh = 0;
  set @TotaalAantalOntvangenOverigeOntvInInkEenh   = 0;
  set @TotaalAantalCorrectieDezeOntvInVoorrEenh    = 0;
  set @TotaalAantalCorrectieDezeOntvInInkEenh      = 0;
  set @TotaalAantalCorrectieOverigeOntvInVoorrEenh = 0;
  set @TotaalAantalCorrectieOverigeOntvInInkEenh   = 0;


  //BESTELREGEL-INFORMATIE OPHALEN
  select  BstRglSoort,  BstRglInkoopEenheid, BstRglArtikelNummerLeverancier,  BstRglEANcode,  BstRglVoorraadEenhedenInInkoopEenheid,  BstRglAantalBesteld,  BstRglAantalOntvangenInVoorrEenh,  BstRglAantalNogTeOntvangenInVoorrEenh,  ArtOmsEenheid,  ArtAantDecAantallen
  into   @BstRglSoort, @BstRglInkoopEenheid, @BstRglArtikelNummerLeverancier, @BstRglEANcode, @BstRglVoorraadEenhedenInInkoopEenheid, @BstRglAantalBesteld, @BstRglAantalOntvangenInVoorrEenh, @BstRglAantalNogTeOntvangenInVoorrEenh, @ArtOmsEenheid, @ArtAantDecAantallen
  from   tabBestelRegel
         inner join tabArtikel on (ArtGid = BstRglArtGid)
  where  BstRglGid = @BstRglGid and BstRglSoort in (1,2); //alleen tarief- of artikelregels!

  //even initialiseren mocht de waarde een null opleveren; indien veld 0 is dan op 1 zetten zodat we geen divisions by zero krijgen!
  set @BstRglVoorraadEenhedenInInkoopEenheid = IsNull(@BstRglVoorraadEenhedenInInkoopEenheid, 0);
  set @DeelbaarheidBepalen = if (@BstRglSoort in (1,2)) and (@BstRglVoorraadEenhedenInInkoopEenheid <> 0) then 1 else 0 endif;

  //Als het aantal voorraadeenheden 0 is dan zetten we hem even op 1 zodat we er niet uitknallen met een division by zero. Er worden toch geen aantallen getoond in inkoopeenheden, omdat
  if @BstRglVoorraadEenhedenInInkoopEenheid = 0 then
    set @BstRglVoorraadEenhedenInInkoopEenheid = 1;
  end if;

  //HUIDIGE MAGAZIJNREGEL INFORMATIE OPHALEN
  select MagOntAantal, MagOntAantalCorrectie
  into   @AantalOntvInVoorrEenhDezeRegelInDb, @AantalOntvInVoorrEenhDezeRegelInDbCorrectie
  from   tabMagazijnOntvangsten
  where  MagOntGid = @MagOntGid and MagOntBstRglGid = @BstRglGid;

  //ALLE REGELS VAN DEZE MAGAZIJNONTVANGST OPHALEN
  select sum(MagOntAantal), sum(MagOntAantalCorrectie)
  into   @TotaalAantalOntvangenDezeOntvInVoorrEenh, @TotaalAantalCorrectieDezeOntvInVoorrEenh
  from   tabMagazijnOntvangsten where MagOntMokGid = @MokGid and MagOntBstRglGid = @BstRglGid;

  set @TotaalAantalOntvangenDezeOntvInVoorrEenh = IsNull(@TotaalAantalOntvangenDezeOntvInVoorrEenh, 0);
  set @TotaalAantalCorrectieDezeOntvInVoorrEenh = IsNull(@TotaalAantalCorrectieDezeOntvInVoorrEenh, 0);

  //AANTALLEN IN VOORRAADEENHEDEN UIT HUIDIGE MAGAZIJNONTVANGSTREGEL (VAN SCHERM) OMREKENEN NAAR AANTALLEN IN INKOOPEENHEDEN
  set @AantalOntvInVoorrEenhDezeRegel           = cast(round(@MagOntAantalOpScherm, @ArtAantDecAantallen) as numeric(15,3));
  set @AantalOntvInInkEenhDezeRegel             = Round(@AantalOntvInVoorrEenhDezeRegel / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);

  set @AantalCorrInVoorrEenhDezeRegel           = cast(round(@MagOntAantalCorrectieOpScherm, @ArtAantDecAantallen) as numeric(15,3));
  set @AantalCorrInInkEenhDezeRegel             = Round(@AantalCorrInVoorrEenhDezeRegel / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);

  //AANTALLEN BESTELREGEL BEREKENEN
  //--AANTAL BESTELD
  set @AantalBesteldInInkEenh                      = @BstRglAantalBesteld;
  set @AantalBesteldInVoorrEenh                    = Round(@AantalBesteldInInkEenh * @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);
  //--AANTAL ONTVANGEN VOOR DEZE BESTELLING IN ANDERE (MAGAZIJN)ONTVANGSTEN
  set @TotaalAantalOntvangenOverigeOntvInVoorrEenh = @BstRglAantalOntvangenInVoorrEenh - @TotaalAantalOntvangenDezeOntvInVoorrEenh;
  set @TotaalAantalOntvangenOverigeOntvInInkEenh   = Round(@TotaalAantalOntvangenOverigeOntvInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);
  //--AANTAL ONTVANGEN VOOR DEZE BESTELLING VIA DE HUIDIGE MAGAZIJNONTVANGST
  set @TotaalAantalOntvangenDezeOntvInVoorrEenh    = @TotaalAantalOntvangenDezeOntvInVoorrEenh - @AantalOntvInVoorrEenhDezeRegelInDb + @AantalOntvInVoorrEenhDezeRegel;
  set @TotaalAantalOntvangenDezeOntvInInkEenh      = Round(@TotaalAantalOntvangenDezeOntvInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);
  //--AANTAL NOG TE ONTVANGEN
  set @AantalNogTeOntvangenInVoorrEenh             = @BstRglAantalNogTeOntvangenInVoorrEenh + (@AantalOntvInVoorrEenhDezeRegelInDb - @AantalOntvInVoorrEenhDezeRegelInDbCorrectie) - (@AantalOntvInVoorrEenhDezeRegel - @AantalCorrInVoorrEenhDezeRegel);
  set @AantalNogTeOntvangenInInkEenh               = Round(@AantalNogTeOntvangenInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);
  //--AANTAL CORRECTIE VOOR DEZE BESTELLING VIA DE HUIDIGE MAGAZIJNONTVANGST
  set @TotaalAantalCorrectieDezeOntvInVoorrEenh    = @TotaalAantalCorrectieDezeOntvInVoorrEenh - @AantalOntvInVoorrEenhDezeRegelInDbCorrectie + @AantalCorrInVoorrEenhDezeRegel;
  set @TotaalAantalCorrectieDezeOntvInInkEenh      = Round(@TotaalAantalCorrectieDezeOntvInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);
  //--AANTAL CORRECTIE VOOR DEZE BESTELLING IN ANDERE (MAGAZIJN)ONTVANGSTEN
  set @TotaalAantalCorrectieOverigeOntvInVoorrEenh = @AantalNogTeOntvangenInVoorrEenh - (@AantalBesteldInVoorrEenh - @TotaalAantalOntvangenOverigeOntvInVoorrEenh - @TotaalAantalOntvangenDezeOntvInVoorrEenh + @TotaalAantalCorrectieDezeOntvInVoorrEenh);
  set @TotaalAantalCorrectieOverigeOntvInInkEenh   = Round(@TotaalAantalCorrectieOverigeOntvInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);

  //BEPALEN OF INKOOPEENHEDEN NOG TE TONEN IS OBV ONTVANGEN VOORRAADEENHEDEN
  set @DeelbaarTotaalAantalOntvangenOverigeOntv = if (@DeelbaarheidBepalen = 1) and (round(@TotaalAantalOntvangenOverigeOntvInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen) * @BstRglVoorraadEenhedenInInkoopEenheid) = @TotaalAantalOntvangenOverigeOntvInVoorrEenh then 1 else 0 endif;
  set @DeelbaarTotaalAantalOntvangenDezeOntv    = if (@DeelbaarheidBepalen = 1) and (round(@TotaalAantalOntvangenDezeOntvInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen) * @BstRglVoorraadEenhedenInInkoopEenheid) = @TotaalAantalOntvangenDezeOntvInVoorrEenh then 1 else 0 endif;
  set @DeelbaarAantalNogTeOntvangen             = if (@DeelbaarheidBepalen = 1) and (round(@AantalNogTeOntvangenInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen) * @BstRglVoorraadEenhedenInInkoopEenheid) = @AantalNogTeOntvangenInVoorrEenh then 1 else 0 endif;
  set @DeelbaarTotaalAantalCorrectieDezeOntv    = if (@DeelbaarheidBepalen = 1) and (round(@TotaalAantalCorrectieDezeOntvInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen) * @BstRglVoorraadEenhedenInInkoopEenheid) = @TotaalAantalCorrectieDezeOntvInVoorrEenh then 1 else 0 endif;
  set @DeelbaarTotaalAantalCorrectieOverigeOntv = if (@DeelbaarheidBepalen = 1) and (round(@TotaalAantalCorrectieOverigeOntvInVoorrEenh / @BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen) * @BstRglVoorraadEenhedenInInkoopEenheid) = @TotaalAantalCorrectieOverigeOntvInVoorrEenh then 1 else 0 endif;

  set @@ErrorTextProcedure = @ErrText;
  //call TraceBegin(@@ErrorTextProcedure);

  //RESULTSET TERUGGEVEN
  select
    @DeelbaarTotaalAantalOntvangenOverigeOntv,
    @DeelbaarTotaalAantalOntvangenDezeOntv,
    @DeelbaarAantalNogTeOntvangen,
    @DeelbaarTotaalAantalCorrectieDezeOntv,
    @DeelbaarTotaalAantalCorrectieOverigeOntv,
    @BstRglSoort,
    @ArtOmsEenheid,
    @BstRglInkoopEenheid,
    @BstRglArtikelNummerLeverancier,
    @BstRglEANcode,
    @ArtAantDecAantallen,
    @AantalBesteldInInkEenh,
    @AantalBesteldInVoorrEenh,
    @TotaalAantalOntvangenOverigeOntvInInkEenh,
    @TotaalAantalOntvangenOverigeOntvInVoorrEenh,
    @TotaalAantalOntvangenDezeOntvInInkEenh,
    @TotaalAantalOntvangenDezeOntvInVoorrEenh,
    @TotaalAantalCorrectieOverigeOntvInInkEenh,
    @TotaalAantalCorrectieOverigeOntvInVoorrEenh,
    @TotaalAantalCorrectieDezeOntvInInkEenh,
    @TotaalAantalCorrectieDezeOntvInVoorrEenh,
    @AantalNogTeOntvangenInInkEenh,
    @AantalNogTeOntvangenInVoorrEenh,
    @BstRglVoorraadEenhedenInInkoopEenheid;

end;

//----- Geef aan de hand van een datum het boekjaar en de periode terug
//      Als deze niet wordt gevonden, dan wordt het laatste boekjaar en periode tergugegeven of
//      de eerste. Dit is afhakelijk van de datum
create or replace procedure BepaalBoekjaarEnPeriode(in @Datum Date, inout @BjGid integer, inout @PerNr integer)
begin
  declare @EersteDatum Date;
  declare @LaatsteDatum Date;

  set @@ErrorTextProcedure = 'BepaalBoekjaarEnPeriode > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Datum = ' + string(@Datum));

  set @BjGid = null;
  select PerBjGid, PerNr into @BjGid, @PerNr from tabPeriode where @Datum between BeginDatum and EindDatum;
  if @BjGid is null then
    select min(BeginDatum) into @EersteDatum from tabPeriode;
    if @EersteDatum > @Datum then
      select PerBjGid, PerNr into @BjGid, @PerNr from tabPeriode where @EersteDatum between BeginDatum and EindDatum;
    else
      select max(BeginDatum) into @LaatsteDatum from tabPeriode;
      select PerBjGid, PerNr into @BjGid, @PerNr from tabPeriode where @LaatsteDatum between BeginDatum and EindDatum;
    end if;
  end if;

  set @@ErrorTextProcedure = 'BepaalBoekjaarEnPeriode';
  //call TraceEind(@@ErrorTextProcedure + ' > @BjGid = ' +string(@BjGid) + ', @Pernr = ' + string(@Pernr));
end;


// *****************************************************************************************************
// Procnaam       : BepaalDefaultMagazijnGid
// Resultaat      : Geeft default magazijn terug voor een bepaald artikel of een opgegeven toepassing
// Parameters     : @ArtGid        - optioneel - voor het bepalen van het defaultmagazijn van het opgegeven artikel
//                  @MagToepassing - optioneel - voor het bepalen van het defaultmagazijn voor een opgegeven toepassing
//                  @GebruikerCode - optioneel - nodig voor @MagToepassing -> indien leeggelaten wordt de ingelogde gebruiker ingevuld
// Beschrijving   : Deze routine bepaalt het default magazijn van een artikel danwel opgegeven toepassing, te weten in de volgende stappen:
//                  1. Default magazijn van het opgegeven artikel; indien parameter null is wordt deze default overgeslagen.
//                  2. Default magazijn van de opgegeven toepassing; indien parameter null is wordt deze default overgeslagen.
//                     Alleen mogelijk met optie meerdere magazijnen/locaties (optie 43)
//                  3. Indien geen default magazijn gevonden is bij stap 1 of 2 dan wordt magazijn 1 als default teruggegeven
// Reden bouw     : Initieel gebouwd omdat het defaultmagazijn van een artikel/toepassing op veel verschillende manieren bepaald werd.
// Gebouwd door/op: TG 06-11-2007, iom PG/RB - NB: (VOLGORDE) NIET AANPASSEN ZONDER OVERLEG MET PG/RB!
// *****************************************************************************************************
create or replace function BepaalDefaultMagazijnGid(in @ArtGid integer, in @MagToepassing integer, in @GebruikerCode nchar(40))
  returns integer
begin
  declare @MagGid integer;

  set @@ErrorTextTrigger = 'BepaalDefaultMagazijnGid > @ArtGid='+string(@ArtGid)+ ', @MagToepassing='+string(@MagToepassing)+', @GebruikerCode='+@GebruikerCode;
  //call TraceBegin(@@ErrorTextTrigger);

  set @MagGid = null;

  //1. Bepalen van defaultmagazijn van artikel (tarief- en tekstblokgidjes worden genegeerd)
  if @ArtGid is not null then
    //call Trace('Gid defaultmagazijn bepalen obv artikel');
    select ArtDefaultMagGid into @MagGid from tabArtikel where Artgid = @ArtGid and ArtSoort=2;
  end if;

  //2. Bepalen op basis van opgegeven toepassing
  if @MagGid is null and @MagToepassing is not null then
    if @@ModuleM1 = 1 then //Alleen mogelijk bij optie meerdere magazijnen en locaties
      //call Trace('Gid defaultmagazijn bepalen obv magazijntoepassing');

      //gebruikercode is alleen van belang als we willen selecteren obv een toepassingstype. In dat geval moet de gebruiker ingevuld zijn.
      //Bij een null-value als parameter pakt ie de huidige (ingelogde) gebruiker, anders de opgegeven gebruiker.
      set @GebruikerCode = IsNull(@GebruikerCode, @@GebruikerCode);

      select first ToeMagMagGid into @MagGid
      from   tabToegestaneMagazijnen
             inner join tabGebruiker ON (ToeMagGebrGid = GebruikerGid)
      where  (ToeMagToepassing = @MagToepassing) AND (NaamGebruiker = @GebruikerCode);
    end if;
  end if;

  //3. Nog geen default gevonden; Magazijn 1 als default teruggeven
  if @MagGid is null then
    //call Trace('Gid magazijn 1 bepalen');
    select MagGid into @MagGid from tabMagazijn where MagCode = 1;
  end if;

  set @@ErrorTextTrigger = 'BepaalDefaultMagazijnGid > @MagGid='+string(@MagGid);
  //call TraceEind(@@ErrorTextTrigger);

  return @MagGid;
end;

create or replace procedure BepaalInkoopprijs(
  in @ArtGid integer,
  in @PartijGid integer,
  in @Inkoopeenheid nchar(20),
  in @VoorraadeenhedenInInkoopeenheid numeric(15,3),
  in @NawGid integer,
  in @ValutaNr integer,
  in @AantalOntvangen  numeric(15,3),
  in @FactuurDatum date
)
result
(
  Inkoopprijs numeric(15,3),
  KortingSoort smallint,
  Kortingbedrag numeric(15,3),
  KortingPercentage numeric(15,2),
  PrijsPerSoort smallint
)
begin
  declare @Inkoopprijs numeric(15,3);
  declare @KortingSoort smallint;
  declare @Kortingbedrag numeric(15,3);
  declare @KortingPercentage numeric(15,2);
  declare @PrijsPerSoort smallint;

  declare @ValutaVanInkoopPrijs  integer;
  declare @AantalDecimalenPrijzen smallint;
  declare @ArtSoort smallint;
  declare @ArtIsPartijAparteKostPrijs smallint;

  set @@ErrorTextProcedure = 'BepaalInkoopprijs';
  //call TraceBegin(@@ErrorTextProcedure);

  // Initialseren/Zet defaults
  set @ValutaVanInkoopPrijs = @@BasisValutaNummer;
  set @KortingSoort = 1; /*Kortingspercentage*/
  set @Kortingbedrag = 0;
  set @KortingPercentage = 0;
  set @PrijsPerSoort = 1; // In voorraadeenheden

  // 1. Ophalen artikelgegevens
  // Inkoopprijs is default de kostprijs van het tarief/artikel
  select
    ArtSoort,
    ArtIsPartijAparteKostPrijs,
    ArtAantDecPrijzen,
    ArtKostprijsEx
  into
    @ArtSoort,
    @ArtIsPartijAparteKostPrijs,
    @AantalDecimalenPrijzen,
    @Inkoopprijs
  from tabArtikel
  where
    ArtGid = @ArtGid;

  // Alleen voor artikelen: heeft partij inkoopprijs of is er een inkoopeenheid
  if @ArtSoort = 2 /*Artikel*/ then
    begin
      declare @AldGid integer;
      declare @AldVoorraadEenhedenInInkoopEenheid numeric(15,3);
      declare @AldHeeftEigenInkoopprijs smallint;
      declare @InkoopprijsPartij numeric (15,3);
      declare @ValutaInkoopPrijsPartij integer;

      // 2. Ophalen partijgegevens
      if @PartijGid is not null then
        select
          // NOTE: Als Inkoopprijs van partij gelijk aan 0 dan Kostprijs van partij gebruiken, maar alleen als partij aparte kostprijs hanteert!
          // In andere gevallen dienen we gewoon de prijs van de inkoopeenheid hanteren
          if IsNull(ArtPartijInkoopPrijs,0) <> 0 then ArtPartijInkoopPrijs else if @ArtIsPartijAparteKostPrijs = 1 then ArtPartijKostPrijsEx else null endif endif,
          if IsNull(ArtPartijInkoopPrijs,0) <> 0 then ArtPartijInkoopValNummer else @@BasisValutaNummer endif
        into
          @InkoopprijsPartij,
          @ValutaInkoopPrijsPartij
        from tabArtikelPartij
        where
          ArtPartijGid = @PartijGid;
      end if;

      // 3. Ophalen inkoopgegevens
      select
        AldGid,
        AldInkoopPrijsPer,
        AldVoorraadEenhedenInInkoopEenheid,
        if AldHeeftEigenInkoopprijs = 0 then ArtKostprijsEx      else AldInkoopPrijs endif,
        if AldHeeftEigenInkoopprijs = 0 then @@BasisValutaNummer else AldValNummer endif,
        AldHeeftEigenInkoopprijs
      into
        @AldGid,
        @PrijsPerSoort,
        @AldVoorraadEenhedenInInkoopEenheid,
        @Inkoopprijs,
        @ValutaVanInkoopPrijs,
        @AldHeeftEigenInkoopprijs
      from
        tabArtikelLeverancier
      inner join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid)
      inner join tabArtikel on (ArtGid = ArtLevArtGid)
      where
            ArtLevArtGid     = @ArtGid
        and ArtLevNawGid     = @NawGid
        and AldInkoopEenheid = @InkoopEenheid;

      // Partij met een inkoopprijs gaat boven de prijs van de inkoopeenheid, echter wel rekening houden met omrekenen
      if @PartijGid is not null and @InkoopprijsPartij is not null then
        if @PrijsPerSoort = 0 /* In Inkoopeenheden*/ and @AldGid is not null then
          // Bereken prijs in inkoopeenheid!
          set @Inkoopprijs = round(@InkoopprijsPartij * @AldVoorraadEenhedenInInkoopEenheid, @AantalDecimalenPrijzen);
        else
          set @Inkoopprijs = @InkoopprijsPartij;
        end if;

        set @ValutaVanInkoopPrijs = @ValutaInkoopPrijsPartij;
      end if;

      if @AldGid is not null then
        // 4. Kortingen bepalen
        if @AldHeeftEigenInkoopprijs = 1 then
          call BerekenLeveranciersKorting(@AldGid, @AantalOntvangen, @ValutaNr, @FactuurDatum, @KortingSoort, @KortingBedrag, @KortingPercentage);
        end if;

        // Corrigeren voor een eventueel een opgegeven afwijkend aantal in inkoopeenheid
        if @PrijsPerSoort = 0 /* In Inkoopeenheden*/ then
          set @Inkoopprijs = round(@Inkoopprijs * @VoorraadeenhedenInInkoopeenheid/ @AldVoorraadEenhedenInInkoopEenheid, @AantalDecimalenPrijzen);
          set @KortingBedrag = round(@KortingBedrag * @VoorraadeenhedenInInkoopeenheid/ @AldVoorraadEenhedenInInkoopEenheid, @AantalDecimalenPrijzen);
        end if;
    end if;
    end;
  end if;

  // 5. Omrekenen in de valuta van de inkoop
  if @ValutaVanInkoopPrijs <> @ValutaNr then
    begin
      declare @BjGid integer;
      declare @PerNr integer;

      call BepaalBoekjaarEnPeriode (@FactuurDatum, @BjGid, @PerNr);

      set @Inkoopprijs = ValutaOmrekenen(@ValutaVanInkoopPrijs, @Inkoopprijs,  @ValutaNr, @BjGid, @Pernr, @AantalDecimalenPrijzen);
      set @Kortingbedrag = ValutaOmrekenen(@ValutaVanInkoopPrijs, @Kortingbedrag, @ValutaNr, @BjGid, @Pernr, @AantalDecimalenPrijzen);
    end;
  end if;

  set @@ErrorTextProcedure = 'BepaalInkoopprijs';
  //call TraceEind(@@ErrorTextProcedure);

  select @Inkoopprijs, @KortingSoort, @Kortingbedrag, @KortingPercentage, @PrijsPerSoort;
end;

//call BepaalInkoopprijs;

create or replace procedure BepaalLandenVanAdressenVerschillen(in @VanAdrGid integer, in @NaarAdrGid integer,  out @VanLndGid integer, out @NaarLndGid integer, out @VanLndOms nchar(40), out @NaarLndOms nchar(40), out @LandenVerschillen smallint)
begin
  select LndGid, LndOms into @VanLndGid,  @VanLndOms  from tabLand inner join tabAdres on AdrLndGid = LndGid where AdrGid = @VanAdrGid;
  select LndGid, LndOms into @NaarLndGid, @NaarLndOms from tabLand inner join tabAdres on AdrLndGid = LndGid where AdrGid = @NaarAdrGid;

  set @LandenVerschillen = (if @VanLndGid = @NaarLndGid then 0 else 1 endif);
end;


//---------------------------------------------------------------------------
//------------------------------ Leverancier Inkoopeenheid bepalen ----------
//---------------------------------------------------------------------------

create or replace procedure BepaalLevInkoopeenheid(in @ArtLevArtGid integer, in @ArtLevNawGid integer, inout @AldInkoopEenheid nchar(20))
begin
  declare @InkoopEenheid nchar(20);
  set @@ErrorTextProcedure = 'BepaalLevInkoopeenheid > @ArtLevArtGid='+string(@ArtLevArtGid)+', @ArtLevNawGid='+string(@ArtLevNawGid)+', @AldInkoopEenheid='+string(@AldInkoopEenheid);
  //call TraceBegin(@@ErrorTextProcedure);

  //set @InkoopEenheid = '';

  //Als de meegegeven inkoopeenheid bestaat in combinatie met artikel en leverancier, deze teruggeven
  SELECT AldInkoopEenheid into @InkoopEenheid
  FROM tabArtikelLeverancier
  inner join tabArtikelLeverancierDetail on (aldArtLevGid = ArtLevGid)
  WHERE ArtLevArtGid    = @ArtLevArtGid
  and ArtLevNawGid      = @ArtLevNawGid
  and AldInkoopEenheid  = @AldInkoopEenheid;

  if @InkoopEenheid is null then
    //Zoek de default van artikel leverancier op.
    SELECT AldInkoopEenheid into @InkoopEenheid
    FROM tabArtikelLeverancier
    inner join tabArtikelLeverancierDetail on (aldArtLevGid = ArtLevGid)
    WHERE ArtLevArtGid    = @ArtLevArtGid
    and ArtLevNawGid      = @ArtLevNawGid
    and AldIsDefaultInkoopEenheidBijLev = 1;

    if @InkoopEenheid is null then
      //Haal de default van het artikel op.
      select ArtOmsEenheid into @InkoopEenheid from tabArtikel where ArtGid = @ArtLevArtGid;
    end if;
  end if;

  //De nieuwe terugsturen
  set @AldInkoopEenheid = @InkoopEenheid;

  set @@ErrorTextProcedure = 'BepaalLevInkoopeenheid > @ArtLevArtGid='+string(@ArtLevArtGid)+', @ArtLevNawGid='+string(@ArtLevNawGid)+', @AldInkoopEenheid='+string(@AldInkoopEenheid);
  //call TraceEind(@@ErrorTextProcedure);
end;


