// ---------------- Vertaling vd de delphifunctie in qdstring.pas   ----------------------
// ---------------------------------------------------------------------------------------

create or replace function BepaalNawRekBankRekening(in @NawRekBankRekeningInvoer nchar(40))
returns nchar(40)
begin
  declare @Result nchar(40);
  declare @IsIban smallint;

  set @@ErrorTextProcedure = 'BepaalNawRekBankRekening > ' + @NawRekBankRekeningInvoer;
  //call TraceBegin(@@ErrorTextProcedure);

  select IsValidIBAN(@NawRekBankRekeningInvoer) into @IsIban;

  if (@IsIban = 1) and (substr(@NawRekBankRekeningInvoer, 1, 2) = 'NL') then
    select GetRekeningnummerFromIBAN(@NawRekBankRekeningInvoer) into @Result;
  else
    set @Result = @NawRekBankRekeningInvoer;
  end if;

  set @@ErrorTextProcedure = 'BepaalNawRekBankRekening > Result = ' + @Result;
  //call TraceEind(@@ErrorTextProcedure);
  return (@Result);
end;


//select BepaalNawRekBankRekening('555');
//select BepaalNawRekBankRekening('NL11FTSB0806038438');


create or replace procedure BepaalPartijObvNummer(in @ArtGid integer, in @ArtPartijNummer nchar(20), out @ArtPartijGid integer, inout @ErrorMask integer)
begin
  //------------- Geef Gidje van partij terug adhv Artikel, Partijnummer combi tbv Order aanmaken via Factuurhistorie

  set @@ErrorTextProcedure = 'BepaalPartijObvNummer > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @ArtGid = ' + string(@ArtGid) + ', @ArtPartijNummer = ' + string(@ArtPartijNummer));

  if IsNull(@ArtPartijNummer,'') = '' then
    set @ArtPartijGid = null;
  else
    select ArtPartijGid into @ArtPartijGid from tabArtikelPartij where ArtPartijNummer = @ArtPartijNummer and ArtPartijArtGid = @ArtGid;

    if @ArtPartijGid is null then  // De partij niet terug kunnen vinden, dan de standaard maar opzoeken
      set @ErrorMask = @ErrorMask + 2;
      select ArtPartijGid into @ArtPartijGid from tabArtikelPartij where ArtPartijNummer = '(Standaard)' and ArtPartijArtGid = @ArtGid;
    end if;

    if @ArtPartijGid is null then
      insert into tabArtikelPartij(ArtPartijArtGid, ArtPartijNummer,        ArtPartijOms, ArtPartijVerkoopprijs, ArtPartijKostprijsEx, ArtPartijIsGeblokkeerdVoorInkoop, ArtPartijIsGeblokkeerdVoorVerkoop, ArtPartijInkoopValNummer)
      select                               ArtGid,   '(Standaard)', _A('Standaard-partij'),          ArtVerkprijs,       ArtKostprijsEx,                 ArtIsGeblokkeerd,                  ArtIsGeblokkeerd,      @@BasisValutaNummer
      from tabArtikel where ArtGid = @ArtGid;
      set @ArtPartijGid = @@Identity;
    end if;
  end if;

  set @@ErrorTextProcedure = 'BepaalPartijObvNummer';
  //call TraceEind(@@ErrorTextProcedure+ ' > @ArtPartijGid = ' + string(@ArtPartijGid));
end;


create or replace procedure BepaalPrijsAfspraak(
in  @NawGid             integer,       // debiteur-gidje
in  @ArtGid             integer,       // artikel-gidje
in  @VkeGid             integer,       // Verkoopeenheid-gidje
in  @ArtOpbrGrpGid      integer,       // Opbr.grp.-gidje; Als ArtGid is gevuld, dan wordt deze leeggemaakt en niet gebruikt evt. wel de groep die bij het opgegeven ArtGid hoort als er voor het betreffende artikel zelf geen prijsafspraak is gevonden
in  @DebGrpGid          integer,       // deb.grp.-gidje;Als NawGid is gevuld, dan wordt deze leeggemaakt en niet gebruikt evt. wel de groep die bij het opgegeven NawGid hoort als er voor de betreffende naw zelf geen prijsafspraak is gevonden
in  @ArtPartijGid       integer,       // Partij van het artikel (Partijkorting overruled andere prijsafspraken!)
in  @IsInclBtw          integer,       // Afspraak tonen : 1 = incl. BTW / 0 = excl. BTW / NULL = volgens afspraak/artikel/debiteur
in  @ValNummer          integer,       // Afspraak tonen in valuta ... / NULL = volgens afspraak/artikel/debiteur
in  @AantalVerkEenheid  numeric(15,3), // Aantal in verkoopeenheden (word alleen gebruikt bij staffels)
in  @AantalVrdEenheid   numeric(15,3), // Aantal in voorraadeenheden (word alleen gebruikt bij staffels)
in  @BasisValutaNummer  integer,
in  @BasisValutaCode    nchar(3),
in  @VerwerkingsDatum   date,
out @PraGid             integer,       // prijsafspraak-gidje, dat vervolgens gebruikt kan worden om bijvoorbeeld de pra-opmerking op te halen.
out @PraIsInclBtw       integer,
out @PraValNummer       integer,
out @PraValcode         nchar(3),
out @PraVerkoopPrijs    numeric(15,3),
out @PraKortingsoort    smallint,      //0=Geen 1=KortingsPercentage 2=KortingsBedrag
out @PraKortingsPerc    numeric(6,2),
out @PraKortingsBedrag  numeric(15,3),
out @TypeAfspraak       integer,       // 0=Geen 10=Deb/Art 20=Deb/OpbrGrp 30=DebGrp/Art 40=DebGrp/OpbrGrp 50=Art Verkoopeenheid 60=Art 70=Partij 100=Maatwerk ....  en +1 als het om staffel gaat
out @StfKopGid          integer,       //Staffel
out @PrijzenPer         smallint)      //0=verkoopeenheid 1=voorraadeenheid

begin
  declare @BjGid                 integer;
  declare @PerNr                 integer;
  declare @RekenIsIncl           integer;
  declare @RekenValNummer        integer;
  declare @GevraagdType          smallint       = 6;

  declare @tmpIsInclBtw          integer        = null;
  declare @tmpValNummer          integer        = null;
  declare @tmpVerkoopPrijs       numeric(15,3)  = null;
  declare @tmpKortingsPerc       numeric( 6,2)  = null;
  declare @tmpKortingsBedrag     numeric(15,3)  = null;
  declare @TmpPraSoort           integer        = null;

  declare @tmpVerkoopPrijsIncl   numeric(15,3);
  declare @tmpVerkoopPrijsExcl   numeric(15,3);

  //artikel veldjes
  declare @artVerkoopPrijs       numeric(15,3);
  declare @artIsInclBtw          integer;
  declare @ArtAantDecPrijzen     integer        = 3;
  declare @ArtPrijsPer           numeric(15,3)  = 1; //TG 29-06-2005: als we geen artikel hebben, dan blijft deze var leeg. Standaard dus prijs per 1.
  declare @PartijAparteVerkPrijs integer        = 0; //TG 29-06-2005: werd niet altijd gevuld, en kreeg dus geen prijsafspraken omdat (null = 0) niet werkt.
  declare @BtwPercentage         numeric(5, 2)  = 0;
  declare @StfRglVanafAantal     numeric(15,3);
  declare @AantalVoorraadEenhedenInVerkoopEenheid numeric(15,3);
  //naw-veldjes
  declare @nawIsInclBtw          integer        = null;
  declare @nawValNummer          integer        = null;//op basis van de meegegeven parameters bepalen welk type prijsafspraak we zoeken.

  //Uiteindelijke velden
  declare @VerkPrijs             numeric(15,3);
  declare @VerkPrijsIsIncl       smallint;
  declare @VerkPrijsValNummer    integer;
  declare @KortBedrag            numeric(15,3);
  declare @KortBedragIsIncl      smallint;
  declare @KortBedragValNummer   integer;
  declare @KortPerc              numeric(6,2);

  declare @PraKortingsoortGeen        smallint = 0;
  declare @PraKortingsoortPercentage  smallint = 1;
  declare @PraKortingsoortBedrag      smallint = 2;

  declare @PrijzenPerVerkoopeenheid   smallint = 0;
  declare @PrijzenPerVoorraadeenheid  smallint = 1;

  declare @IsMaatwerkPrijs            smallint = 0;  //0=Geen maatwerkprijs, 1=Wel maatwerkprijs

  set @@ErrorTextProcedure = 'BepaalPrijsAfspraak > ';
  //call TraceBegin(@@ErrorTextProcedure + '@NawGid = ' + string(@NawGid)+', @ArtGid = ' + string(@ArtGid) + ', @ArtOpbrGrpGid = ' + string(@ArtOpbrGrpGid) + ', @DebGrpGid = ' + string(@DebGrpGid) + ', @IsInclBtw='+ string(@IsInclBtw));

  set @PraGid           = null;
  set @PraKortingsoort  = @PraKortingsoortGeen;
  set @TypeAfspraak     = 0; //Geen prijsafspraak totdat er 1 gevonden wordt
  set @PrijzenPer       = @PrijzenPerVoorraadeenheid; //normaliter zijn alle prijzen per voorraadeenheid. Per verkoopeenheid is alleen mogelijk bij prijsafspraken per verkoopeenheid.

  case
    when @artGid is not null        and @nawGid is not null    then                           set @GevraagdType = 1;
    when @artOpbrGrpGid is not null and @nawGid is not null    then                           set @GevraagdType = 2;
    when @artGid is not null        and @DebGrpGid is not null then                           set @GevraagdType = 3;
    when @artOpbrGrpGid is not null and @DebGrpGid is not null then                           set @GevraagdType = 4;
    when @artGid is not null        and @nawGid is not null    and @VkeGid is not null then   set @GevraagdType = 5;
    when @artGid is not null        and @nawGid is not null    then                           set @GevraagdType = 6;
  end case;

  //call Trace(@@ErrorTextProcedure + '@GevraagdType = '+ string(@GevraagdType));

  //bepalen artikelgegevens
  if @ArtGid is not null then
    //call Trace('BepaalPrijsAfspraak > Ophalen standaardprijs artikel : @ArtGid = ' + string(@ArtGid));
    select  ArtVerkprijsIsIncl,  ArtVerkprijs    , (select BtwPercentage from tabBtw where BtwCode = ArtBtwCode),  ArtAantDecPrijzen,  ArtIsPartijAparteVerkoopPrijs,  ArtPrijsPer,  ArtOpbrGrpGid, 60
    into   @artIsInclBtw      , @ArtVerkoopPrijs,         @BtwPercentage,                                         @ArtAantDecPrijzen, @PartijAparteVerkPrijs        , @ArtPrijsPer, @ArtOpbrGrpGid, @TypeAfspraak
    from   tabArtikel
    where (ArtGid = @ArtGid);
  end if;

  //bepalen partijgegevens, maar alleen indien we een aparte verkoopprijs per partij hanteren!
  if @PartijAparteVerkPrijs <> 0 then
    //call Trace('BepaalPrijsAfspraak > Prijs en korting van partij teruggeven : @ArtPartijGid = ' + string(@ArtPartijGid));
    select  ArtPartijVerkoopPrijsIsIncl, (select BtwPercentage from tabBtw where BtwCode = ArtPartijVerkoopBtwCode), @BasisValutaNummer,  ArtPartijVerkoopPrijs,  ArtPartijKortingsPerc,  ArtPartijKortingsBedrag, 70
    into   @tmpIsInclBtw               , @BtwPercentage,                                                             @tmpValNummer     , @tmpVerkoopPrijs      , @tmpKortingsPerc      , @tmpKortingsBedrag      , @TypeAfspraak
    from   tabArtikelPartij
    where  ArtPartijGid = @ArtPartijGid;

    //TG 29-06-2005: als we geen partijgid meegeven, maar wel een partijartikel hebben, dan toch type 70 terug geven.
    set @TypeAfspraak = IsNull(@TypeAfspraak, 70);
  end if;

  //bepalen NAW-gegevens
  if (@PartijAparteVerkPrijs = 0) and @NawGid is not null then
    //call Trace('BepaalPrijsAfspraak > Ophalen valuta en in/ex BTW van debiteur : @NawGid = ' + string(@NawGid));
    select NawFacturerenInclBtw into @nawIsInclBtw from tabNaw where NawGid = @NawGid;
    select NawFilValNummer, NawFilDebGrpGid into @nawValNummer, @DebGrpGid from tabNawFile where NawFilNawGid = @NawGid;
  end if;

  //TG 14-07-2005: Als we geen In/ex BTW van een NAW hebben kunnen bepalen, dan bepalen op basis van de instelling uit de vaste gegevens debiteuren.
  if @nawIsInclBtw is null then
    select FonFactuurBTW into @nawIsInclBtw from tabFileOfNaw where FonId = 'D';
  end if;

  //call Trace('BepaalPrijsAfspraak > @nawIsInclBtw = ' + string(@nawIsInclBtw));

  // 0. Maatwerk
  if exists(select 1 from sysprocedure key join sysusers where name='KINGSYSTEM' and proc_name = 'Maatwerk_BepaalPrijs') then
    //call Trace('BepaalPrijsAfspraak > Prijsafspraak maatwerk');
    call Maatwerk_BepaalPrijs(@NawGid, @ArtGid, @VkeGid, @ArtOpbrGrpGid, @DebGrpGid, @ArtPartijGid, @IsInclBtw, @ValNummer, @AantalVerkEenheid, @AantalVrdEenheid, @BasisValutaNummer, @BasisValutaCode, @VerwerkingsDatum,
                              @PraGid, @tmpIsInclBtw, @tmpValNummer, @PraValcode, @tmpVerkoopPrijs, @TmpPraSoort,     @tmpKortingsPerc, @tmpKortingsBedrag, @TypeAfspraak, @StfKopGid, @PrijzenPer, @IsMaatwerkPrijs);
  end if;

  //TG 14-07-2005: Alleen prijsafspraken bepalen als niet gaat om een artikel met partijenregistratie waarbij per partij aparte verkoopprijzen gehanteerd worden.
  //RS 14-11-2022: En alleen prijsafspraken bepalen als er geen maatwerkprijs geldt.
  if not (@PartijAparteVerkPrijs = 1 or @IsMaatwerkPrijs = 1) then

    //********************************************************************************//
    //** VOLGORDE WAARIN DE PRIJSAFSPRAKEN BEPAALD WORDEN:                          **//
    //** 0. Maatwerk                                                                **//
    //** 1. prijsafspraak debiteur/artikel; en als die er niet is:                  **//
    //** 2. prijsafspraak debiteur/opbrengstgroep; en als die er niet is:           **//
    //** 3. prijsafspraak debiteurgroep/artikel; en als die er niet is:             **//
    //** 4. prijsafspraak debiteurgroep/opbrengstgroep; en als die er niet is:      **//
    //** 5. Prijs en korting van verkoopeenheid van artikel; en als die er niet is: **//
    //** 6. standaard-artikelprijs (incl. standaardkorting)                         **//
    //********************************************************************************//

    // 1. prijsafspraak debiteur/artikel:
    if (@NawGid is not null) and (@ArtGid is not null) then
      //call Trace('BepaalPrijsAfspraak > Prijsafspraak debiteur/artikel : @NawGid = ' + string(@NawGid) + ', @ArtGid = ' + string(@ArtGid));
      select  first  PraGid,  PraIsInclBtw,  PraValNummer,  PraVerkoopPrijs,  PraKortingsPerc,  PraKortingsBedrag, PraStfKopGid,  PraSoort    , 10
      into          @PraGid, @tmpIsInclBtw, @tmpValNummer, @tmpVerkoopPrijs, @tmpKortingsPerc, @tmpKortingsBedrag, @StfKopGid, @TmpPraSoort, @TypeAfspraak
      from    tabPrijsafspraak
      where  (PraNawGid    = @NawGid) and
             (PraArtGid    = @ArtGid) and
             (PraCombiSoort = 4);
    end if;

    // 2. prijsafspraak debiteur/opbrengstgroep:
    if (@PraGid is null) and (@NawGid is not null) and (@ArtOpbrGrpGid is not null) then
      //call Trace('BepaalPrijsAfspraak > Prijsafspraak debiteur/opbrengstgroep : @NawGid = ' + string(@NawGid) + ', @ArtOpbrGrpGid = ' + string(@ArtOpbrGrpGid));
      select  first  PraGid,  PraIsInclBtw,  PraValNummer,  PraVerkoopPrijs,  PraKortingsPerc,  PraKortingsBedrag,  PraStfKopGid, PraSoort    , 20
      into          @PraGid, @tmpIsInclBtw, @tmpValNummer, @tmpVerkoopPrijs, @tmpKortingsPerc, @tmpKortingsBedrag, @StfKopGid, @TmpPraSoort, @TypeAfspraak
      from    tabPrijsafspraak
      where  (PraNawGid     = @NawGid) and
             (PraOpbrGrpGid = @ArtOpbrGrpGid) and
             (PraCombiSoort = 3);
    end if;

    // 3. prijsafspraak debiteurgroep/artikel:
    if (@PraGid is null) and (@ArtGid is not null) and (@DebGrpGid is not null) then
      //call Trace('BepaalPrijsAfspraak > Prijsafspraak debiteurgroep/artikel : @DebGrpGid = ' + string(@DebGrpGid)+', @ArtGid = ' + string(@ArtGid));
      select  first  PraGid,  PraIsInclBtw,  PraValNummer,  PraVerkoopPrijs,  PraKortingsPerc,  PraKortingsBedrag,  PraStfKopGid, PraSoort    , 30
      into          @PraGid, @tmpIsInclBtw, @tmpValNummer, @tmpVerkoopPrijs, @tmpKortingsPerc, @tmpKortingsBedrag, @StfKopGid, @TmpPraSoort, @TypeAfspraak
      from    tabPrijsafspraak
      where  (PraArtGid     = @ArtGid)    and
             (PraDebGrpGid  = @DebGrpGid) and
             (PraCombiSoort = 2);
    end if;

    // 4. prijsafspraak debiteurgroep/opbrengstgroep:
    if (@PraGid is null) and (@DebGrpGid is not null) and (@ArtOpbrGrpGid is not null) then
      //call Trace('BepaalPrijsAfspraak > Prijsafspraak debiteurgroep/opbrengstgroep : @DebGrpGid = ' + string(@DebGrpGid)+', @ArtOpbrGrpGid = ' + string(@ArtOpbrGrpGid));
      select  first  PraGid,  PraIsInclBtw,  PraValNummer,  PraVerkoopPrijs,  PraKortingsPerc,  PraKortingsBedrag,  PraStfKopGid, PraSoort    , 40
      into          @PraGid, @tmpIsInclBtw, @tmpValNummer, @tmpVerkoopPrijs, @tmpKortingsPerc, @tmpKortingsBedrag, @StfKopGid, @TmpPraSoort, @TypeAfspraak
      from    tabPrijsafspraak
      where  (PraDebGrpGid  = @DebGrpGid) and
             (PraOpbrGrpGid = @ArtOpbrGrpGid) and
             (PraCombiSoort = 1);
    end if;

    // 5. Prijs en korting van verkoopeenheid van artikel
    if (@PraGid is null) and (@ArtGid is not null) and (@VkeGid is not null) then
      //Voor het geval de btw niet hetzelfde is als de verkoopeenheid en er alleen een aparte korting is.
      set @tmpVerkoopPrijsIncl = if @ArtIsInclBtw=1 then  @ArtVerkoopPrijs                              else @ArtVerkoopPrijs * ((100+@BtwPercentage)/100)  end if;
      set @tmpVerkoopPrijsExcl = if @ArtIsInclBtw=1 then  @ArtVerkoopPrijs * (100/(@BtwPercentage+100)) else @ArtVerkoopPrijs                               end if;

      //call Trace('BepaalPrijsAfspraak > Prijsafspraak artikel : @ArtGid = ' + string(@ArtGid) + '@VkeGid = ' + string(@VkeGid));
      select  VkeIsVerkoopprijsInclusiefBTW,
              if (VkeHeeftAparteVerkoopPrijsOfKorting = 1) then
                    if (ArtVerkprijsIsIncl<>VkeIsVerkoopprijsInclusiefBTW) then
                      if(VkeIsVerkoopprijsInclusiefBTW=1) then
                        @tmpVerkoopPrijsIncl
                      else
                        @tmpVerkoopPrijsExcl
                      endif
                    else
                      @ArtVerkoopPrijs
                    endif
              else
                VkeVerkoopprijs
              endif ,
              (select BtwPercentage from tabBtw where BtwCode = ArtBtwCode),
              ArtAantDecPrijzen,
              ArtIsPartijAparteVerkoopPrijs,
              if (VkeVerkoopPrijsPer = @PrijzenPerVerkoopeenheid) then 1 else ArtPrijsPer endif,
              ArtOpbrGrpGid,
              VkeVerkoopPrijsPer,
              VkeAantalVoorraadEenhedenInVerkoopEenheid,
              50
      into   @ArtIsInclBtw,
             @ArtVerkoopPrijs,
             @BtwPercentage,
             @ArtAantDecPrijzen,
             @PartijAparteVerkPrijs,
             @ArtPrijsPer,
             @ArtOpbrGrpGid,
             @PrijzenPer,
             @AantalVoorraadEenhedenInVerkoopEenheid,
             @TypeAfspraak
      from   tabVerkoopEenheid
      inner join tabArtikel on ArtGid = VkeArtGid
      where (VkeArtGid = @ArtGid)
      and   (VkeGid = @VkeGid)
      and   (VkeHeeftAparteVerkoopPrijsOfKorting in (1,2));

      select  first  PraGid,  PraIsInclBtw,  PraValNummer,  PraKortingsPerc,  PraKortingsBedrag,  PraStfKopGid, PraSoort    , 50
      into          @PraGid, @tmpIsInclBtw, @tmpValNummer, @tmpKortingsPerc, @tmpKortingsBedrag, @StfKopGid, @TmpPraSoort, @TypeAfspraak
      from    tabPrijsafspraak
      where  (PraArtGid     = @ArtGid) and
             (PraVkeGid     = @VkeGid) and
             (PraCombiSoort = 5);
    end if;

    // 6. standaard-artikelkorting (artikelprijs is al eerder bepaald):
    //    Ook een check op @typeprijsafspraak = 50. een verkoopeenheid hoeft geen @Pragid te hebben maar wel een prijs
    if (@PraGid is null) and (@ArtGid is not null) and (@TypeAfspraak <> 50) then
      //call Trace('BepaalPrijsAfspraak > Prijsafspraak artikel : @ArtGid = ' + string(@ArtGid));
      select  first  PraGid,  PraIsInclBtw,  PraValNummer,  PraKortingsPerc,  PraKortingsBedrag,  PraStfKopGid, PraSoort    , 60
      into          @PraGid, @tmpIsInclBtw, @tmpValNummer, @tmpKortingsPerc, @tmpKortingsBedrag, @StfKopGid, @TmpPraSoort, @TypeAfspraak
      from    tabPrijsafspraak
      where  (PraArtGid     = @ArtGid) and
             (PraCombiSoort = 0);
    end if;

    //BEPALING STAFFELGEGEVENS (indien aanwezig)
    if @StfKopGid is not null then
      //call Trace('BepaalPrijsAfspraak > Ophalen staffelgegevens van prijsafspraak : @AantalVerkEenheid = ' + string(@AantalVerkEenheid));

      //TG 27-06-2005: Als we een staffelgid hebben, dan het type afspraak ophogen met 1.
      set @TypeAfspraak = @TypeAfspraak + 1;

      //TG 27-06-2005: als VanafAantal niet opgegeven is, maar er is wel een staffeltabel, dan de korting voor vanafaantal 0 doorberekenen.
      if @PrijzenPer = @PrijzenPerVerkoopeenheid then
        set @StfRglVanafAantal = IsNull(@AantalVerkEenheid, 0);
      else
        set @StfRglVanafAantal = IsNull(@AantalVrdEenheid, 0);
      end if;

      select   first (if StfRglIsPercKorting = 1 then StfRglKorting endif), (if StfRglIsPercKorting = 0 then StfRglKorting endif)
      into            @tmpKortingsPerc,                                     @tmpKortingsBedrag
      from     tabStaffelRegel
      where        (StfRglStfKopGid = @StfKopGid)
               and (StfRglVanafAantal <= abs(@StfRglVanafAantal))
      order by StfRglVanafAantal desc;

      //Prijsafspraakvelden vullen met staffelkortingsbedrag in de incl/excl btw en valuta volgens prijsafspraak
      if @tmpKortingsBedrag is not null then

        if @tmpValNummer is null and @tmpVerkoopprijs is null and @NawGid is not null then
          set @tmpValNummer = @NawValNummer;
        end if;

        //omrekenen naar valuta van prijsafspraak
        if @tmpValNummer is not null and @tmpValNummer <> @BasisValutaNummer then
          set @tmpKortingsBedrag = ValutaOmrekenen(@BasisValutaNummer, @tmpKortingsBedrag * @ArtPrijsPer, @tmpValNummer, @BjGid, @Pernr, @ArtAantDecPrijzen);
        else
          set @tmpKortingsBedrag = Round(@tmpKortingsBedrag * @ArtPrijsPer, @ArtAantDecPrijzen);
          set @tmpValNummer = @BasisValutaNummer;
        end if;

        //als we een prijsafspraak met een staffelkortingsbedrag (dus zonder afwijkende prijs) hebben, dan de btw-instelling
        //van de NAW (dan wel vaste gegevens NAW-debiteuren) gebruiken.
        if @tmpIsInclBtw is null and @tmpVerkoopprijs is null and @ArtGid is not null then //alleen staffelkortignbedrag zonder prijs
          set @tmpIsInclBtw=@nawIsInclBtw;
        end if;

        //omrekenen naar incl/excl btw van prijsafspraak, want staffelkortingsbedragen zijn altijd excl btw
        if @tmpIsInclBtw is not null and @tmpIsInclBtw = 1 then
          set @tmpKortingsBedrag = Round((@tmpKortingsBedrag * (100 + @BtwPercentage)) / 100, @ArtAantDecPrijzen);
        else
          set @tmpIsInclBtw = 0;
        end if;
      end if;

    //call Trace('BepaalPrijsAfspraak > Staffelkorting : @tmpKortingsPerc = ' + string(@tmpKortingsPerc) + ', @tmpKortingsBedrag = ' +string(@tmpKortingsBedrag));
    end if;
  end if;  //einde géén aparte verkoopprijs

  //call Trace('BepaalPrijsAfspraak >  @tmpVerkoopPrijs = ' + string(@tmpVerkoopPrijs));

  //Als er geen verkoopprijs bepaald is obv een prijsafspraak, dan de artikelprijs gebruiken.
  if @tmpVerkoopPrijs is null then
    set @VerkPrijs          = @artVerkoopPrijs;
    set @VerkPrijsIsIncl    = @artIsInclBtw;
    set @VerkPrijsValNummer = @BasisValutaNummer;
  else
    set @VerkPrijs          = @tmpVerkoopPrijs;
    set @VerkPrijsIsIncl    = @tmpIsInclBtw;
    set @VerkPrijsValNummer = @tmpValNummer;
  end if;

  set @KortPerc            = @tmpKortingsPerc;
  set @KortBedrag          = @tmpKortingsBedrag;
  set @KortBedragIsIncl    = @tmpIsInclBtw;
  set @KortBedragValNummer = @tmpValNummer;

  //Bepalen of we rekenen obv incl of excl btw prijzen.
  //vb: EUR 25,00 incl 6% btw -> EUR 23,58 excl btw -> EUR 24.99 incl 6% btw als de order excl btw is.
  // ORDER/NAW | ART  | Resultaat (basis in/ex btw)
  // ----------+------+----------
  // incl      | incl | incl
  // incl      | excl | excl
  // excl      | incl | excl
  // excl      | excl | excl

  set @RekenIsIncl = IsNull(@IsInclBtw, @nawIsInclBtw) * @VerkPrijsIsIncl;
  //call Trace('BepaalPrijsAfspraak >  @RekenIsIncl = ' + string(@RekenIsIncl));

  //Ten behoeve van onderhoud prijsafspraken; Incl/excl btw in principe conform de gewenste prijsafspraak...
  if @IsInclBtw is null and @GevraagdType = round((@TypeAfspraak / 10),0) then
    set @IsInclBtw = @tmpIsInclBtw;
  end if;
  //...anders obv de debiteur, maar als artikel niet bekend is, is ook de BTW niet bekend en volgen we de gevonden prijsafspraak.
  if @ArtGid is null then
    set @IsInclBtw = IsNull(@IsInclBtw, @KortBedragIsIncl, @VerkPrijsIsIncl);
  end if;
  //...anders obv de debiteur.
  set @IsInclBtw   = IsNull(@IsInclBtw, @nawIsInclBtw, @KortBedragIsIncl, @VerkPrijsIsIncl);

  //call Trace('BepaalPrijsAfspraak >  @IsInclBtw = ' + string(@IsInclBtw));

  //omrekenen verkoopprijs naar basis in/ex btw.
  if @VerkPrijs is not null and @RekenIsIncl <> @VerkPrijsIsIncl then
    set @VerkPrijs        = Round(if @RekenIsIncl = 1 then @VerkPrijs * (100 + @BtwPercentage) / 100 else @VerkPrijs / (100 + @BtwPercentage) * 100 endif, @ArtAantDecPrijzen);
    set @VerkPrijsIsIncl  = @RekenIsIncl;
  else
    set @VerkPrijs        = Round(@VerkPrijs, @ArtAantDecPrijzen);
  end if;
  //call Trace('BepaalPrijsAfspraak >  @BtwPercentage = ' + string(@BtwPercentage));
  //call Trace('BepaalPrijsAfspraak >  @VerkPrijsIsIncl = ' + string(@VerkPrijsIsIncl));
  //call Trace('BepaalPrijsAfspraak >  @VerkPrijs = ' + string(@VerkPrijs));

  //omrekenen kortingsbedrag naar basis in/ex btw.
  if @KortBedrag is not null and @RekenIsIncl <> @KortBedragIsIncl then
    set @KortBedrag       = Round(if @RekenIsIncl = 1 then @KortBedrag * (100 + @BtwPercentage) / 100 else @KortBedrag / (100 + @BtwPercentage) * 100 endif, @ArtAantDecPrijzen);
    set @KortBedragIsIncl = @RekenIsIncl;
  else
    set @KortBedrag       = Round(@KortBedrag, @ArtAantDecPrijzen);
  end if;

  //Valuta wordt valuta zoals gevraagd of anders die van de gevraagde prijsafspraak, en anders de debiteur en anders de basisvaluta
  if @ValNummer is null and @GevraagdType = round((@TypeAfspraak / 10),0) then
    set @ValNummer = IsNull(@KortBedragValNummer, @VerkPrijsValNummer);
  end if;

  set @ValNummer = IsNull(@ValNummer, @NawValNummer, @BasisValutaNummer);

  if (@ValNummer <> @VerkPrijsValNummer) or (@ValNummer <> @KortBedragValNummer) then
    call BepaalBoekjaarEnPeriode(@VerwerkingsDatum, @BjGid, @PerNr);
  end if;

  //omrekenen verkoopprijs naar gewenste valuta en vervolgens naar gewenste incl/excl btw
  if @VerkPrijs is not null then
    //Omrekenen verkoopprijs naar juiste valuta (indien afwijkend van gewenst)
    if (@ValNummer <> @VerkPrijsValNummer) then
      set @VerkPrijs          = ValutaOmrekenen(@VerkPrijsValNummer, @VerkPrijs, @ValNummer, @BjGid, @Pernr, @ArtAantDecPrijzen);
      set @VerkPrijsValNummer = @ValNummer;
    end if;

    if @IsInclBtw <> @RekenIsIncl then
      set @VerkPrijs = Round(if @IsInclBtw = 1 then @VerkPrijs * (100 + @BtwPercentage) / 100 else @VerkPrijs / (100 + @BtwPercentage) * 100 endif, @ArtAantDecPrijzen);
      set @VerkPrijsIsIncl  = @IsInclBtw; //niet relevant, want we geven @IsInclBtw als output var terug.
    end if;
  end if;
  //call Trace('BepaalPrijsAfspraak >  @VerkPrijs = ' + string(@VerkPrijs));

  //omrekenen kortingsbedrag naar gewenste valuta en vervolgens naar gewenste incl/excl btw
  if @KortBedrag is not null then
    //Omrekenen kortingsbedrag naar juiste valuta (indien afwijkend van gewenst)
    if (@ValNummer <> @KortBedragValNummer) then
      set @KortBedrag          = ValutaOmrekenen(@KortBedragValNummer, @KortBedrag, @ValNummer, @BjGid, @Pernr, @ArtAantDecPrijzen);
      set @KortBedragValNummer = @ValNummer;
    end if;

    if @IsInclBtw <> @RekenIsIncl then
      set @KortBedrag = Round(if @IsInclBtw = 1 then @KortBedrag * (100 + @BtwPercentage) / 100 else @KortBedrag / (100 + @BtwPercentage) * 100 endif, @ArtAantDecPrijzen);
      set @KortBedragIsIncl  = @IsInclBtw; //niet relevant, want we geven @IsInclBtw als output var terug.
    end if;
  end if;

  set @PraIsInclBtw      = @IsInclBtw;
  set @PraValNummer      = @ValNummer;
  set @PraValcode        = if @ValNummer = @BasisValutaNummer then @BasisValutaCode else (select ValCode from tabValuta where ValNummer = @ValNummer) endif;
  set @PraVerkoopPrijs   = @VerkPrijs;
  set @PraKortingsPerc   = @KortPerc;
  set @PraKortingsBedrag = @KortBedrag;
  set @PraKortingsoort   = if (@PraKortingsPerc is null) then if (@PraKortingsBedrag is null) then @PraKortingsoortGeen else @PraKortingsoortBedrag endif else @PraKortingsoortPercentage endif;

  set @@ErrorTextProcedure = 'BepaalPrijsAfspraak';
  //call TraceEind(@@ErrorTextProcedure + ' > @TypeAfspraak = ' + string(@TypeAfspraak) + ', @PraGid = ' + string(@PraGid) + ' , @PraIsInclBtw = ' + string(@PraIsInclBtw) + ', @PraValNummer = ' + string(@PraValNummer) + ', @PraValcode = ' + string(@PraValcode) + ', @PraVerkoopPrijs = ' +string(@PraVerkoopPrijs) + ', @PraKortingsPerc = ' + string(@PraKortingsPerc) + ', @PraKortingsBedrag = ' + string(@PraKortingsBedrag));
end;


//Geeft de resultaten van Maatwerk_BepaalPrijs terug in een resultset, tbv rapporten (prijslijst, catalogus)
create or replace procedure BepaalPrijsResultSet(
  in  @NawGid             integer,       // debiteur-gidje
  in  @ArtGid             integer,       // artikel-gidje
  in  @VkeGid             integer,       // Verkoopeenheid-gidje
  in  @ArtOpbrGrpGid      integer,       // Opbr.grp.-gidje; Als ArtGid is gevuld, dan wordt deze leeggemaakt en niet gebruikt evt. wel de groep die bij het opgegeven ArtGid hoort als er voor het betreffende artikel zelf geen prijsafspraak is gevonden
  in  @DebGrpGid          integer,       // deb.grp.-gidje;Als NawGid is gevuld, dan wordt deze leeggemaakt en niet gebruikt evt. wel de groep die bij het opgegeven NawGid hoort als er voor de betreffende naw zelf geen prijsafspraak is gevonden
  in  @ArtPartijGid       integer,       // Partij van het artikel (Partijkorting overruled andere prijsafspraken!)
  in  @IsInclBtw          integer,       // Afspraak tonen : 1 = incl. BTW / 0 = excl. BTW / NULL = volgens afspraak/artikel/debiteur
  in  @ValNummer          integer,       // Afspraak tonen in valuta ... / NULL = volgens afspraak/artikel/debiteur
  in  @AantalVerkEenheid  numeric(15,3), // Aantal in verkoopeenheden (word alleen gebruikt bij staffels)
  in  @AantalVrdEenheid   numeric(15,3), // Aantal in voorraadeenheden (word alleen gebruikt bij staffels)
  in  @BasisValutaNummer  integer,
  in  @BasisValutaCode    nchar(3),
  in  @VerwerkingsDatum   date)      //0=Geen maatwerkprijs, 1=Wel maatwerkprijs
begin
  declare @PraGid             integer;       // prijsafspraak-gidje; dat vervolgens gebruikt kan worden om bijvoorbeeld de pra-opmerking op te halen.
  declare @PraIsInclBtw       integer;
  declare @PraValNummer       integer;
  declare @PraValcode         nchar(3);
  declare @PraVerkoopPrijs    numeric(15,3);
  declare @PraKortingsoort    smallint;      //0=Geen 1=KortingsPercentage 2=KortingsBedrag
  declare @PraKortingsPerc    numeric(6,2);
  declare @PraKortingsBedrag  numeric(15,3);
  declare @TypeAfspraak       integer  = 0;       // 0=Geen 10=Deb/Art 20=Deb/OpbrGrp 30=DebGrp/Art 40=DebGrp/OpbrGrp 50=Art Verkoopeenheid 60=Art 70=Partij 100=Maatwerk....  en +1 als het om staffel gaat
  declare @StfKopGid          integer;       //Staffel
  declare @PrijzenPer         smallint;      //0=verkoopeenheid 1=voorraadeenheid
  declare @IsMaatwerkPrijs    smallint = 0;

  //set @@ErrorTextProcedure = 'BepaalPrijsResultSet > ';
  //call TraceBegin(@@ErrorTextProcedure + '@NawGid = ' + string(@NawGid)+', @ArtGid = ' + string(@ArtGid) + ', @ArtOpbrGrpGid = ' + string(@ArtOpbrGrpGid) + ', @DebGrpGid = ' + string(@DebGrpGid) + ', @IsInclBtw='+ string(@IsInclBtw));

  if exists(select 1 from sysprocedure key join sysusers where name='KINGSYSTEM' and proc_name = 'Maatwerk_BepaalPrijs') then
    call Maatwerk_BepaalPrijs(@NawGid, @ArtGid, @VkeGid, @ArtOpbrGrpGid, @DebGrpGid, @ArtPartijGid, @IsInclBtw, @ValNummer, @AantalVerkEenheid, @AantalVrdEenheid, @BasisValutaNummer, @BasisValutaCode, @VerwerkingsDatum,
                              @PraGid, @PraIsInclBtw, @PraValNummer, @PraValcode, @PraVerkoopPrijs, @PraKortingsoort, @PraKortingsPerc, @PraKortingsBedrag, @TypeAfspraak, @StfKopGid, @PrijzenPer, @IsMaatwerkPrijs);
  end if;

  select
    @NawGid            MNawGid,
    @ArtGid            MArtGid,
    @VkeGid            MVkeGid,
    @ArtOpbrGrpGid     MArtOpbrGrpGid,
    @DebGrpGid         MDebGrpGid,
    @ArtPartijGid      MArtPartijGid,
    @IsInclBtw         MIsInclBtw,
    @ValNummer         MValNummer,
    @AantalVerkEenheid MAantalVerkEenheid,
    @AantalVrdEenheid  MAantalVrdEenheid,
    @BasisValutaNummer MBasisValutaNummer,
    @BasisValutaCode   MBasisValutaCode,
    @VerwerkingsDatum  MVerwerkingsDatum,
    @PraGid            MPraGid,
    @PraIsInclBtw      MPraIsInclBtw,
    @PraValNummer      MPraValNummer,
    @PraValcode        MPraValcode,
    @PraVerkoopPrijs   MPraVerkoopPrijs,
    @PraKortingsoort   MPraKortingsoort,
    @PraKortingsPerc   MPraKortingsPerc,
    @PraKortingsBedrag MPraKortingsBedrag,
    @TypeAfspraak      MTypeAfspraak,
    @StfKopGid         MStfKopGid,
    @PrijzenPer        MPrijzenPer,
    @IsMaatwerkPrijs   MIsMaatwerkPrijs;

  //set @@ErrorTextProcedure = 'BepaalPrijsResultSet';
  //call TraceEind(@@ErrorTextProcedure + ' > @TypeAfspraak = ' + string(@TypeAfspraak) + ', @PraGid = ' + string(@PraGid) + ' , @PraIsInclBtw = ' + string(@PraIsInclBtw) + ', @PraValNummer = ' + string(@PraValNummer) + ', @PraValcode = ' + string(@PraValcode) + ', @PraVerkoopPrijs = ' +string(@PraVerkoopPrijs) + ', @PraKortingsPerc = ' + string(@PraKortingsPerc) + ', @PraKortingsBedrag = ' + string(@PraKortingsBedrag)+', @IsMaatwerkPrijs='+string(@IsMaatwerkPrijs));
end;


//----------------------------------------------------------------------------------------------------
//------------------------ BEPALEN VAN EEN (PROJECT)RECHT VOOR EEN GEBRUIKER -------------------------
//----------------------------------------------------------------------------------------------------
//Nu alleen rechten per gebruiker(als PbGid dan Null meegeven)
//Later rechten per gebruiker per projectonderdeel(dan PbGid meegeven)
//Let op :  met bijv isql kan de @@GebruikersCode 'Kingsystem' zijn, dan is @@GebruikerGid Null, dus dan is recht altijd waar !
create or replace function BepaalProjectRecht(
in @RechtCode              nchar(4),
in @PbGid                  integer
)
returns smallint

begin
  declare @Active smallint;

  //Voorlopig geen rechten per project, dus nog niets doen met PbGid !! JV, 18 okt 2005

  //call TraceBegin('BepaalProjectRecht(@RechtCode='+@RechtCode+')');

  //Als recht voor een gebruiker niet in tabel staat(of @@GebruikerGid is Null), of recht is 1 dan heeft de gebruiker het recht
  //Dus geen recht als in tabel staat met recht is 0
  if exists(select 1 from tabRechtPerGebruiker where RechtGebrGebruikerGid=@@GebruikerGid and RechtGebrGebruikersRechtCode=@RechtCode and RechtGebrHeeftRecht=0 ) then
    set @Active = 0
  else
    set @Active = 1
  end if;

  //call TraceEind('BepaalProjectRecht ------> @Active='+string(@Active));
  return(@Active)

end;


//----------------------------------------------------------------------------------------------------
//------------------------ BEPALEN VERKOOP- EN KOSTPRIJS PROJECT(ONDERDEEL) --------------------------
//----------------------------------------------------------------------------------------------------
//Let op : bij voorcalculatie regels kan voor activiteiten de medewerker wel null zijn !
//Voor de werking: zie proces p13 in do621 Projecten.doc
create or replace procedure BepaalProjectVerkoopEnKostprijs(
in  @ProjGid               integer,
in  @PbGid                 integer,
in  @ArtGid                integer,
in  @ArtPartijGid          integer,
in  @PmwRelGid             integer,
in  @Aantal                numeric(15,3), //Aantal van artikel/machine/activiteit
out @ProjectVerkoopprijs   numeric(15,3), //De bepaalde verkoopprijs
out @ProjectKostprijs      numeric(15,3), //De bepaalde kostprijs
out @ProjectPbGid          integer,
out @DoorbelPerc           numeric(15,2)  // Doorbelastingspercentage vanaf 5.42
)       //indien niet null, dan prijsafspraak gevonden. Indien ongelijk aan
                                          //@PBGid dan alleen afspraak gevonden op hoger gelegen onderdeel
                                          //Dit veld wordt gebruikt voor maken/vullen tabel met prijsafspraken

begin
  declare  @ArtGidSoort                    integer;//0=activiteit, 1=ov.kosten, 2=artikel
  declare  @Kortingsoort                   smallint;
  declare  @KortingBedrag                  numeric(15,3);
  declare  @KortingPercentage              numeric(6,2);
  declare  @DummyInt                       integer;//speelt even voor debiteur nawgid van het project
  declare  @DummyChar                      nchar(3);
  declare  @KostPrijsMedewPrevaleert       integer;
  declare  @VerkPrijsMedewPrevaleert       integer;
  declare  @TempVerkPrijsAct               numeric(15,3);
  declare  @TempVerkPrijsMdw               numeric(15,3);
  declare  @ProjectArtGid                  integer;
  declare  @ProjectRelGid                  integer;
  declare  @ProjectPbGidAct                integer;
  declare  @ProjectArtGidAct               integer;
  declare  @ProjectRelGidAct               integer;
  declare  @pArtFactEenheidFactor          numeric(4,2);//voorbeeld: als factuureenheid dag is , dan is de factor 8, want 8 uur is 1 dag

  set @@ErrorTextProcedure = 'BepaalProjectVerkoopEnKostprijs(@ProjGid='+string(@ProjGid)+'@PbGid='+string(@PbGid)+'@ArtGid='+string(@ArtGid)+'@ArtPartijGid='+string(@ArtPartijGid)+'@PmwRelGid='+string(@PmwRelGid)+'@Aantal='+string(@Aantal)+')';
  //call TraceBegin(@@ErrorTextProcedure);


  //ArtSoort:    0|Tekstblok |1|Tarief |2|Artikel|
  //pArtSoort:   0|Activiteit voor urenregistratie|1|Gebruik van machine of materieel (Activiteiten en machines zijn ook tarieven in tabartikel)
  select (if ArtSoort = 2 then 2 else PArtSoort endif), (if pArtBerekenVerkoopprijsObv = 1 then pArtDoorbelastPercentage else null endif) into @ArtGidSoort, @DoorbelPerc from tabartikel left outer join tabProjectArtikel on(Artgid=pArtArtgid and ArtSoort=1) where ArtGid = @ArtGid;


  //PG/TG 16-07-2009: Medewerker mag nu ook bij andere soorten ingevuld worden, maar mag dan nooit gebruikt worden bij het bepalen van prijzen (als parameter toch gevuld is, dan dus leegmaken).
  if @ArtGidSoort <> 0 and @PmwRelGid is not null then
    set @PmwRelGid = null;
  end if;

  set @ProjectVerkoopprijs = Null;
  set @ProjectKostprijs    = Null;
  set @ProjectPbGid        = Null;
  set @ProjectArtGid       = Null;
  set @ProjectRelGid       = Null;

  //=============================BEPALEN KOST EN VERKOOP PRIJS===========================================================================================
  if @PmwRelGid is null then
    //==Geen medewerker==================================================================================================================================
    //prijsafspraak voor project-(activiteit/machine/artikel)?
    call ZoekPrijsafspraakViaProjectboom(@PbGid,@ArtGid,Null      ,@ProjectVerkoopprijs,@ProjectPbGid,@ProjectArtgid,@ProjectRelGid);
    if @ProjectVerkoopprijs is null then//niets gevonden
      if @ArtGidSoort = 2 then
        //artikel --> bepaal gewone prijsafspraak (excl btw, basisvaluta, kortingsbedrag/korting eraf halen)
        //eerst NawGid van project bepalen
        select IsNull(ProjNawGidPrijzen, ProjNawGid) into @DummyInt from tabProject where ProjGid = @ProjGid;
        call BepaalPrijsAfspraak(@DummyInt,@ArtGid,Null,Null,Null,@ArtPartijGid,0,@@BasisValutaNummer,@Aantal,@Aantal,@@BasisValutaNummer, @@BasisValutaCode, @@VerwerkingsDatum,
                                  @DummyInt,@DummyInt,@DummyInt,@DummyChar,@ProjectVerkoopprijs,@Kortingsoort,@KortingPercentage,@KortingBedrag,@DummyInt,@DummyInt,@DummyInt);
        if IsNull(@KortingBedrag,0)<>0 then
          set @ProjectVerkoopprijs = @ProjectVerkoopprijs - @KortingBedrag;
        end if;
        if (@Kortingsoort = 1) then
          set @ProjectVerkoopprijs = round(((100-@KortingPercentage)*@ProjectVerkoopprijs)/100,(select ArtAantDecPrijzen from tabArtikel where ArtGid=@ArtGid));
        end if;
      else
        //activiteit of machine --> prijs opzoeken
        select pArtVerkoopprijsExBtw into @ProjectVerkoopprijs from tabProjectArtikel where pArtArtgid = @ArtGid;
      end if;
    end if;
    //kostprijs ophalen uit tabartikel of uit tabartikelpartij
    if @ArtPartijGid is not null then
      select (if ArtIsPartijAparteKostPrijs=1 then ArtPartijKostprijsEx else ArtKostprijsEx endif)
      into   @ProjectKostprijs
      from   tabArtikelPartij inner join tabArtikel on ArtPartijArtGid = ArtGid
      where  ArtPartijGid = @ArtPartijGid;
    else
      select ArtKostprijsEx into @ProjectKostprijs from tabArtikel where Artgid = @ArtGid;
    end if;
  else
    //==Wel  medewerker =================================================================================================================================
    select ProjKostPrijsMedewPrevaleert,
           ProjVerkPrijsMedewPrevaleert
    into   @KostPrijsMedewPrevaleert,
           @VerkPrijsMedewPrevaleert
    from   tabProject
    where  ProjGid = @ProjGid;
    //als prijs van medewerker komt, dan is prijs per uur, dan eventueel omrekenen naar factuureenheid van activiteit
    //als in prijsafspraken het artgidje ingevuld is, dan is die prijs per factuureenheid van die activiteit, anders per uur
    //factor kan ook gewoon 1 zijn
    select pArtFactEenheidFactor
    into   @pArtFactEenheidFactor
    from   tabProjectArtikel
    where  pArtArtgid = @ArtGid;
    //prijsafspraak voor project-activiteit-medewerker?
    call ZoekPrijsafspraakViaProjectboom(@PbGid,@ArtGid,@PmwRelGid,@ProjectVerkoopprijs,@ProjectPbGid,@ProjectArtgid,@ProjectRelGid);//prijs afspraak is per factuureenheid activiteit
    if @ProjectVerkoopprijs is null then//niets gevonden
      call ZoekPrijsafspraakViaProjectboom(@PbGid,@ArtGid,null      ,@TempVerkPrijsAct,@ProjectPbGidAct,@ProjectArtgidAct,@ProjectRelGidAct);
      call ZoekPrijsafspraakViaProjectboom(@PbGid,null   ,@PmwRelGid,@TempVerkPrijsMdw,@ProjectPbGid,@ProjectArtgid,@ProjectRelGid);
      //prijsafspraak voor project-activiteit OF project-medewerker?
      if @TempVerkPrijsAct is not null or @TempVerkPrijsMdw is not null then
        if @TempVerkPrijsAct is not null and @TempVerkPrijsMdw is not null then
          //Er zijn prijsafspraken voor medewerker EN voor activiteit, dus een keuze maken
          if @VerkPrijsMedewPrevaleert=1 then
            set @ProjectVerkoopprijs = @TempVerkPrijsMdw * @pArtFactEenheidFactor;
            //de laatste aangeroepen prijsafspraak is actueel, dus pb, art en rel gid zijn goed gevuld
          else
            set @ProjectVerkoopprijs = @TempVerkPrijsAct;
            //de voorlaatste aangeroepen prijsafspraak is actueel, dus pb, art en rel gid zijn fout gevuld
            set @ProjectPbGid  = @ProjectPbGidAct;
            set @ProjectArtgid = @ProjectArtgidAct;
            set @ProjectRelGid = @ProjectRelGidAct;
          end if;
        else
          //slechts 1 prijsafspraak gevonden, die dus kiezen
          if @TempVerkPrijsAct is null then//dus prijsafspraak voor medewerker gevonden
            set @ProjectVerkoopprijs = @TempVerkPrijsMdw * @pArtFactEenheidFactor;
            //de laatste aangeroepen prijsafspraak is actueel, dus pb, art en rel gid zijn goed gevuld
          else
            set @ProjectVerkoopprijs = @TempVerkPrijsAct;
            //de voorlaatste aangeroepen prijsafspraak is actueel, dus pb, art en rel gid zijn fout gevuld
            set @ProjectPbGid  = @ProjectPbGidAct;
            set @ProjectArtgid = @ProjectArtgidAct;
            set @ProjectRelGid = @ProjectRelGidAct;
          end if;
        end if;
      else//niets gevonden
        //prijsafspraak voor activiteit-medewerker?
        //call ZoekPrijsafspraakViaProjectboom(Null  ,@ArtGid, @PmwRelGid,@ProjectVerkoopprijs,@ProjectPbGid,@ProjectArtgid,@ProjectRelGid);
        //deze prijsafspraak staat los van projecten(boom), en kan meteen bepaald worden via tabProjectPrijsafspraak:
        Select ppaVerkoopprijsExBtw into @ProjectVerkoopprijs//prijs afspraak is per factuureenheid activiteit
        from   tabProjectPrijsafspraak
        where  ppaPbGid is null and ppaArtGid=@ArtGid and ppaRelGid=@PmwRelGid;
        if @ProjectVerkoopprijs is null then//niets gevonden
          //verkoopprijs van activiteit of medewerker
          select (if PmwHeeftVerkoopprijs=1 and @VerkPrijsMedewPrevaleert=1 then PmwVerkoopprijsExBtw * pArtFactEenheidFactor else pArtVerkoopprijsExBtw endif)
          into   @ProjectVerkoopprijs
          from   tabProjectMedewerker left outer join tabProjectArtikel on (pArtArtgid = @Artgid)
          where  PmwRelGid = @PmwRelGid;
        end if;
      end if;
    end if;
    //Kostprijs van activiteit of medewerker
    select (if PmwHeeftKostprijs=1 and @KostPrijsMedewPrevaleert=1 then PmwKostprijs else ArtKostprijsEx endif)
    into   @ProjectKostprijs
    from   tabProjectMedewerker left outer join tabArtikel on (Artgid = @Artgid)
    where  PmwRelGid = @PmwRelGid;
  end if;

  if @DoorbelPerc is not null then
    set @ProjectVerkoopprijs = round(@DoorbelPerc * @ProjectKostprijs / 100,(select ArtAantDecPrijzen from tabArtikel where ArtGid=@ArtGid));
  end if;

  //JV, 14 nov 2005: Na overleg met PG/TG : als artgid of relgid van de ZoekPrijsafspraakViaProjectboom procedure afwijkt van
  //meegegeven artgid en relgid, dan zorgen dat @ProjectPbGid Null wordt.
  //ZoekPrijsafspraakViaProjectboom kan op meerdere manieren aangeroepen zijn, de variabelen bevatten info van de laatst uitgevoerde aanroep
  if IsNull(@ProjectArtGid,0)<>IsNull(@ArtGid,0) or IsNull(@ProjectRelGid,0)<>IsNull(@PmwRelGid,0) then
    set @ProjectPbGid = Null;
  end if;

  set @@ErrorTextProcedure = 'BepaalProjectVerkoopEnKostprijs(@ProjectVerkoopprijs='+string(@ProjectVerkoopprijs)+'@ProjectKostprijs='+string(@ProjectKostprijs)+'@ProjectPbGid='+string(@ProjectPbGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function BepaalTeBetalenBedragInBetalingsVoorstellen(
  in @OspRksGid        integer,
  in @OspFactuurNummer nchar(40),
  in @OspValNummer     integer,
  in @BjGid            integer,
  in @PerNr            integer
)
returns numeric(15,2)
begin
  declare @TotaalTeBetalen numeric(15, 2);

  set @@ErrorTextProcedure = 'BepaalTeBetalenBedragInBetalingsVoorstellen';
  //call traceBegin(@@ErrorTextProcedure);
  select
        isnull((select sum(ValutaOmrekenen(BetRglValNummer, BetRglTeBetalen + (BetRglVerschilAfboeken * BetRglVerschilAfboekenBedragInValOsp), @OspValNummer, @BjGid, @PerNr, 2) )            // Bedrag in nog niet verwerkte voorstellen
                from   tabBetalingRegel
                       inner join tabBetalingKop on (BetKopID = BetRglBetKopID)
                where  BetRglRksGid = @OspRksGid and BetRglFactuurnummer_Lengte = length(@OspFactuurNummer) and BetRglFactuurnummer = @OspFactuurNummer

                   and BetKopStatus = 0  // Is nog voorstel
        ), 0) +
          isnull((select sum(ValutaOmrekenen(BetRglValNummer, BetVerzTeBetalen + (BetVerzVerschilAfboeken * BetVerzVerschilAfboekenBedragInValOsp), @OspValNummer, @BjGid, @PerNr, 2) )           // Bedrag in verzamelde nog niet verwerkte voorstellen
                  from   tabBetalingVerzameld
                         inner join tabBetalingRegel on (BetVerzBetRglGid=BetRglGid)
                         inner join tabBetalingKop on (BetKopID = BetRglBetKopID)
                  where  BetRglRksGid = @OspRksGid and BetVerzFactuurnummer_Lengte = length(@OspFactuurNummer) and BetVerzFactuurnummer = @OspFactuurNummer
                     and BetKopStatus       = 0  // Is nog voorstel
          ), 0)
  into @TotaalTeBetalen;
  //call traceEind(@@ErrorTextProcedure);
  return(@TotaalTeBetalen);

end;


if exists (select 1 from sys.sysProcedure where proc_name= 'BerekenAfleverDatum') then
  drop procedure BerekenAfleverDatum;
end if;

create procedure BerekenAfleverDatum(
  in  @NawGid             integer,
  in  @Levertijd          integer,
  in  @BestelDagVanDeWeek smallint, //loopt van 1 (=maandag) t/m 7 (=zondag)
  in  @Besteldatum        DateTime,
  in  @HeeftBestelTijd    smallint,
  out @Afleverdatum       DateTime
)
begin
  // Extra variabelen nodig om tussenresultaten te berekenen
  declare @MinimumLevertijd                  integer;
  declare @KingDOWMinimumLevertijd           integer;
  declare @AantalDagenBijMinimumLevertijd    integer;
  declare @Afleverdag                        integer;
  declare @WerkelijkeAfleverdag              integer;
  declare @WerkelijkeAfleverTijdNaBestelling integer;

  set @@ErrorTextProcedure = 'BerekenAfleverDatum > @NawGid='+string(@NawGid)+', @Levertijd='+string(@Levertijd)+', @BestelDagVanDeWeek='+string(@BestelDagVanDeWeek)+', @Besteldatum='+string(@Besteldatum);
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select first 1 from tabLeverancierAfleverDagen inner join tabLeverancierGegevens on LevGegGid = LadLevGegGid where LevGegNawGid = @NawGid) then
    // Er zijn afleverdagen, dus op basis daarvan berekenen

    if @HeeftBestelTijd = 0 then
      // Zonder tijd, dan 1 dag erbij tellen en zonder tijd werken
      set @Besteldatum = date(DateAdd(day, 1, @Besteldatum));
      set @BestelDagVanDeWeek = @BestelDagVanDeWeek + 1;
      if @BestelDagVanDeWeek > 7 then
        set @BestelDagVanDeWeek = 1
      end if;
    end if;

    set @AfleverDatum = null;

    select first
      greater(@levertijd, beoogdelevertijd) MinimumLevertijd,  // Als de beoogde levertijd kleiner is dan de minimum levertijd van de inkoopeenheid, dan die grotere levertijd aanhouden!
      mod(@BestelDagVanDeWeek - 1 + MinimumLevertijd, 7)+ 1 KingDOWMinimumLevertijd, // De minimum levertijd valt op deze dag (dus alleen dagen OP of NA deze dag mogen voorkomen!)
      @BestelDagVanDeWeek + MinimumLevertijd - KingDOWMinimumLevertijd AantalDagenBijMinimumLevertijd, // als KingDOWMinimumLevertijd in een toekomstige week valt, dan hier een aantal dagen erbij tellen
      LadAfleverdag + (row_num-1)*7 Afleverdag,
      Afleverdag - @BestelDagVanDeWeek + AantalDagenBijMinimumLevertijd WerkelijkeAfleverdag, // Is eigenlijk de aflevertijd NA de meegegeven besteldatum
      DateAdd(day, WerkelijkeAfleverdag, @Besteldatum) Afleverdatum
    into
      @MinimumLevertijd,
      @KingDOWMinimumLevertijd,
      @AantalDagenBijMinimumLevertijd,
      @Afleverdag,
      @WerkelijkeAfleverdag,
      @Afleverdatum
    from
    (
      //Bepaal het aantal dagen NA de besteldatum van de beoogde levering
      select
      //Als BestellenVoor (Dag in de week, evt met tijd) NA de besteldatum+tijd valt, dan 1 week doorschuiven
      if ladBestellenVoor < @BestelDagVanDeWeek
        or (ladBestellenVoor = @BestelDagVanDeWeek and isnull(DateFormat(DateTime(ladTijdstip), 'HH:NN'), '00:00') < DateFormat(DateTime(@Besteldatum), 'HH:NN')) then
        7
      else
        0
      endif AantalDagenErbij,
      //ACW 05-11-2008 incident 2093 - als Afleverdatum VOOR besteldatum valt, dan naast eventueel al een week verder i.i.g. 7 dagen erbij
      LadAfleverdag + AantalDagenErbij + if LadAfleverdag < ladBestellenVoor then 7 else 0 endif Afleverdag,       // Bepalen juiste afleverdag (evt. een week erbij)
      Afleverdag - @BestelDagVanDeWeek BeoogdeLevertijd  // Afleverdag terugrekenen naar aantal dagen na de gewenste besteldatum

      from
      tabLeverancierAfleverDagen
      inner join tabLeverancierGegevens on LevGegGid = LadLevGegGid
      where
        LevGegNawGid = @NawGid
    ) tmpBepaalBeoogdeLevertijd
    , tabLeverancierAfleverDagen
      inner join tabLeverancierGegevens on LevGegGid = LadLevGegGid
    , RowGenerator // tbv. extra week erna!
    where
      LevGegNawGid = @NawGid
    and WerkelijkeAfleverdag >= MinimumLevertijd // Alleen regels selecteren die NA de mogelijke levertijd valt
    and Row_Num <= 2 // Begint bij 1, dus 2 weken, zodat i.i.g. altijd een afleverdag na de gevraagde afleverdag bestaat
    order by
      // In de volgorde van afleveren, zodat de eerste bestellingsregel de beoogde levertijd bevat
      WerkelijkeAfleverdag;

    if @AfleverDatum is null then
      set @AfleverDatum = DateAdd(day, @Levertijd, @Besteldatum);
    end if;
  else
    //Er zijn geen afleverdagen, dus eenvoudig de levertijd bij de besteldatum optellen (en alleen de datum teruggeven)
    set @AfleverDatum = date(DateAdd(day, @Levertijd, @Besteldatum));
  end if;

  set @@ErrorTextProcedure = 'BerekenAfleverDatum > @NawGid='+string(@NawGid)+', @Levertijd='+string(@Levertijd)+', @BestelDagVanDeWeek='+string(@BestelDagVanDeWeek)+', @Besteldatum='+string(@Besteldatum)+' -> @AfleverDatum='+string(@AfleverDatum);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BerekenIncassoDatumFactuur(in @Vervaldatum datetime, in @LndGid integer, out @IncassoDatum datetime)
begin
  set @@ErrorTextProcedure = 'BerekenIncassoDatumFactuur; @Vervaldatum='+string(@Vervaldatum)+', @LndGid='+string(@LndGid);
  //call TraceBegin(@@ErrorTextProcedure);

  // De incassodatum is rechtstreeks afkomstig van de vervaldatum. Echter, als de vervaldatum in het weekend valt, moet de eerstvolgende werkdag worden gebruikt.
  set @IncassoDatum = DezeOfVolgendeWerkdag(@Vervaldatum, @LndGid);

  set @@ErrorTextProcedure = @@ErrorTextProcedure + ' -> ' + string(@IncassoDatum);
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure BerekenJournaalPostSaldo(in @JpGid integer, in @ValNummer integer, out @DebetBasisBedrag numeric(15,2), out @CreditBasisBedrag numeric(15,2),
                                          out @DebetAantal numeric(15,2), out @CreditAantal numeric(15,2), out @DebetValutaBedrag numeric(15,2), out @CreditValutaBedrag numeric(15,2))
begin

  set @@ErrorTextProcedure = 'BerekenJournaalPostSaldo > ';
  //call TraceBegin(@@ErrorTextProcedure + '@JpGid = ' + string(@JpGid));

  select IsNull(sum(if IsCreditBoeking<>0 then JrBasisBedrag else 0 endif),0),
         IsNull(sum(if IsCreditBoeking<>0 then Aantal else 0 endif),0),
         IsNull(sum(if IsCreditBoeking =0 then JrBasisBedrag else 0 endif),0),
         IsNull(sum(if IsCreditBoeking =0 then Aantal else 0 endif),0),
         IsNull(sum(if JrValNummer = @ValNummer then if IsCreditBoeking<>0 then JrValutaBedrag else 0 endif else ValutaOmrekenen(JrValNummer, if IsCreditBoeking<>0 then JrValutaBedrag else 0 endif, @ValNummer, JrBjGid, JrPernr, 2) endif),0),
         IsNull(sum(if JrValNummer = @ValNummer then if IsCreditBoeking= 0 then JrValutaBedrag else 0 endif else ValutaOmrekenen(JrValNummer, if IsCreditBoeking= 0 then JrValutaBedrag else 0 endif, @ValNummer, JrBjGid, JrPernr, 2) endif),0)
  into   @CreditBasisBedrag, @CreditAantal, @DebetBasisBedrag, @DebetAantal, @CreditValutaBedrag, @DebetValutaBedrag
  from   tabJournaalregel where JrJpGid = @JpGid;

  set @@ErrorTextProcedure = 'BerekenJournaalPostSaldo';
  //call TraceEind(@@ErrorTextProcedure + ' > @DebetBasisBedrag = '  + string(@DebetBasisBedrag) + ', @CreditBasisBedrag = ' + string(@CreditBasisBedrag) + ', @DebetAantal = ' + string(@DebetAantal) + ', @CreditAantal = ' + string(@CreditAantal) + ', @DebetValutaBedrag = ' + string(@DebetValutaBedrag) + ', @CreditValutaBedrag = ' + string(@CreditValutaBedrag));
end;


//----- Geef het journaalpostsaldo terug m.u.v. het meegegeven JrGid en tel de (negatieve) hulpbedragen er bij op
create or replace procedure BerekenJournaalPostSaldoExHulpBedrag(in @JpGid integer, in @JrGid integer, in @ValNummer integer, in @PerNr integer, inout @DebetBasisBedrag numeric(15,2), inout @CreditBasisBedrag numeric(15,2), inout @DebetValutaBedrag numeric(15,2), inout @CreditValutaBedrag numeric(15,2))
begin
  set @@ErrorTextProcedure = 'BerekenJournaalPostSaldoExHulpBedrag > ';
  //call TraceBegin(@@ErrorTextProcedure + '@JpGid = ' + string(@JpGid)+', @JrGid = ' + string(@JrGid) + ', @ValNummer = ' + string(@ValNummer) + ', @PerNr = ' + string(@PerNr));

  select sum( if IsCreditBoeking<>0 then IsNull(JrBasisBedrag,0) else 0 endif + if IsNull(HulpRekIsCredit,0) <> 0 then IsNull(HulpRekBasisBedrag,0) else 0 endif),
         sum( if IsCreditBoeking=0  then IsNull(JrBasisBedrag,0) else 0 endif + if IsNull(HulpRekIsCredit,1) = 0  then IsNull(HulpRekBasisBedrag,0) else 0 endif),
         //RVL 03-03-2010 Bug 32215 Omrekenen tussen valuta, uitgaan van de valuta waarin geboekt is en de periode waarin geboekt is.
         sum( if JrValNummer                  = @Valnummer then isnull((if IsCreditBoeking<>0 then JrValutaBedrag else 0 endif),0)                  else ValutaOmrekenen(JrValNummer,      isnull((if IsCreditBoeking           <> 0 then JrValutaBedrag      else 0 endif),0), @ValNummer, JrBjGid, JrPernr, 2) endif +
              if HulpRekValNummer is null then 0 else if HulpRekValNummer = @ValNummer then isnull((if IsNull(HulpRekIsCredit,0) <> 0 then HulpRekValutaBedrag else 0 endif),0) else ValutaOmrekenen(HulpRekValNummer, isnull((if IsNull(HulpRekIsCredit,0) <> 0 then HulpRekValutaBedrag else 0 endif),0), @ValNummer, JrBjGid, JrPernr, 2) endif endif),
         sum( if JrValNummer                  = @ValNummer then isnull((if IsCreditBoeking =0 then JrValutaBedrag else 0 endif),0)                  else ValutaOmrekenen(JrValNummer,      isnull((if IsCreditBoeking            = 0 then JrValutaBedrag      else 0 endif),0), @ValNummer, JrBjGid, JrPernr, 2) endif +
              if HulpRekValNummer is null then 0 else if isnull(HulpRekValNummer, -1) = @ValNummer then isnull((if IsNull(HulpRekIsCredit,0)  = 0 then HulpRekValutaBedrag else 0 endif),0) else ValutaOmrekenen(HulpRekValNummer, isnull((if IsNull(HulpRekIsCredit,0)  = 0 then HulpRekValutaBedrag else 0 endif),0), @ValNummer, JrBjGid, JrPernr, 2) endif endif)
  into   @CreditBasisBedrag, @DebetBasisBedrag, @CreditValutaBedrag, @DebetValutaBedrag
  from   tabJournaalregel left outer join tabHulpRekening on (JrGid=HulpRekJrGid)
  where  JrJpGid=@JpGid and (JrGid<>@JrGid or @JrGid is null);

  set @@ErrorTextProcedure = 'BerekenJournaalPostSaldoExHulpBedrag';
  //call TraceEind(@@ErrorTextProcedure + ' > @DebetBasisBedrag = ' + string(@DebetBasisBedrag) + ', @CreditBasisBedrag = ' + string(@CreditBasisBedrag) + ', @DebetValutaBedrag = ' + string(@DebetValutaBedrag) + ', @CreditValutaBedrag = ' + string(@CreditValutaBedrag));
end;


create or replace procedure BerekenKredBepVervalDatumFactuur (in @FactuurDatum date, in @BtcNummer integer, inout @VervalDatum date)
begin
  declare @DagenMaanden integer;
  declare @Aantal integer;
  declare @tmpDatum date;

  set @@ErrorTextProcedure = 'BerekenKredBepVervalDatumFactuur > ';
  //call TraceBegin(@@ErrorTextProcedure + '@FactuurDatum = ' + string(@FactuurDatum) + ', @BtcNummer = ' + string(@BtcNummer));

  call BerekenVervalDatumFactuur(@FactuurDatum, @BtcNummer, @tmpDatum);
  select GeldigDgMnd, GeldigAantal into @DagenMaanden, @Aantal from tabBetalingsconditie where Btcnummer = @BtcNummer;
  case @DagenMaanden
  when 1 then  //Einde maand
    set @VervalDatum=dateadd(day,-1,dateadd(month,1,String(Year(@FactuurDatum))+'-'+String(Month(@FactuurDatum))));
  when 2 then        //Dagen na factuurdatum
    set @VervalDatum=dateadd(day,@Aantal,@FactuurDatum);
  when 3 then   //Maanden na einde maand
    set @VervalDatum=dateadd(month,@Aantal,dateadd(day,-1,dateadd(month,1,String(Year(@FactuurDatum))+'-'+String(Month(@FactuurDatum)))));
   when 4 then //Werkdagen na factuurdatum
     set @VervalDatum = BerekenWerkdag(@FactuurDatum, @Aantal);
  else
    set @VervalDatum=@tmpDatum;
  end case;

  if @VervalDatum > @tmpDatum then
    set @VervalDatum = @tmpDatum;
  end if;

  set @@ErrorTextProcedure = 'BerekenKredBepVervalDatumFactuur';
  //call TraceEind(@@ErrorTextProcedure + ' > @Vervaldatum='+string(@Vervaldatum));

end;


//---------- Genereer een of meerdere bestellingen obv een besteladvies ----------
create or replace procedure BerekenLeveranciersKorting(in  @AldGid integer,        in  @AantalBesteld  numeric(15,3), in  @ValNummer integer, @Datum date,
                                                       out @KortingSoort smallint, out @KortingsBedrag numeric(15,2), out @KortingsPercentage numeric(15,2))
begin
  declare @StafKortingSoort       smallint;
  declare @StafValNummer          smallint;
  declare @StafKortingsBedrag     numeric(15,3);
  declare @StafKortingsPercentage numeric(15,2);
  declare @AldHeeftEigenInkoopprijs integer;
  declare @BjGid integer;
  declare @PerNr integer;

  if @Datum is null then
    set @BjGid = @@BjGid;
    set @PerNr = @@PerNr
  else
    call BepaalBoekjaarEnPeriode (@Datum, @BjGid, @PerNr);
  end if;

  set @@ErrorTextProcedure = 'BerekenLeveranciersKorting > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @AldGid = ' + string(@AldGid) + ', @AantalBesteld = '+string(@AantalBesteld) + ', @ValNummer = '+string(@ValNummer));

  select first
    /* gegevens uit tabArtikelLeverancierDetail */
    AldKortingSoort,
    if AldKortingSoort=0 and @ValNummer <> AldValNummer then
      ValutaOmrekenen(AldValNummer, AldKortingBedrag, @ValNummer, @BjGid, @Pernr, ArtAantDecPrijzen)
    else
      Round (AldKortingBedrag, ArtAantDecPrijzen)
    endif AldKortingBedrag,
    AldKortingPercentage,
    AldHeeftEigenInkoopprijs,

    /* gegevens uit tabNawStaffelRegel */
    NstfKopSoort,
    NstfKopValNummer,
    if AldKortingSoort=2 and NstfKopSoort = 0 and @ValNummer <> NstfKopValNummer then
      if AldInkoopPrijsPer = 0 then
        ValutaOmrekenen(NstfKopValNummer, NstfRglBedrag, @ValNummer, @BjGid, @Pernr, ArtAantDecPrijzen)
      else
        ValutaOmrekenen(NstfKopValNummer, (NstfRglBedrag / AldVoorraadEenhedenInInkoopEenheid * ArtPrijsPer), @ValNummer, @BjGid, @Pernr, ArtAantDecPrijzen)
      endif
    else
      if AldInkoopPrijsPer = 0 then
        Round (NstfRglBedrag, ArtAantDecPrijzen)
      else
        Round ((NstfRglBedrag / AldVoorraadEenhedenInInkoopEenheid * ArtPrijsPer), ArtAantDecPrijzen)
      endif
    endif NstfRglBedrag,
    NstfRglPercentage

    into @KortingSoort,
         @KortingsBedrag,
         @KortingsPercentage,
         @AldHeeftEigenInkoopprijs,
         @StafKortingSoort,
         @StafValNummer,
         @StafKortingsBedrag,
         @StafKortingsPercentage
  from
    tabArtikelLeverancierDetail
    inner join tabArtikelLeverancier on AldArtLevGid = ArtLevGid
    inner join tabArtikel on ArtLevArtGid = ArtGid
    inner join tabNawFile on NawFilNawGid = ArtLevNawGid
    left outer join tabNawStaffelRegel on NstfRglNstfKopGid = AldNstfKopGid
    left outer join tabNawStaffelKop on NstfKopGid = AldNstfKopGid
  where
    AldGid = @AldGid and
    (NstfKopGid is null or NstfRglVanafAantal <= @AantalBesteld)
  order by
    NstfRglVanafAantal desc;

  if @AldHeeftEigenInkoopprijs = 1 then
    /* gebruiker heeft vinkje aparte inkoopprijs aangezet */
    if @KortingSoort = 0 then //Bedrag
      set @KortingsPercentage = 0;
    else
      if @KortingSoort = 1 then //Percentage
        set @KortingsBedrag = 0;
      else
        if @KortingSoort = 2 then //Gestaffeld
          set @KortingSoort = @StafKortingSoort;
          if @KortingSoort = 0 then  //Bedrag
            set @KortingsBedrag     = @StafKortingsBedrag;
            set @KortingsPercentage = 0;
          else
            set @KortingsBedrag     = 0;
            set @KortingsPercentage = @StafKortingsPercentage;
          end if
        end if
      end if
    end if
  else
    // gebruiker heeft vinkje aparte inkoopprijs uitgezet of nooit aangezet
    set @KortingSoort = 1; // Percentage is default
    set @KortingsBedrag = 0;
    set @KortingsPercentage = 0;
  end if;

  set @@ErrorTextProcedure = 'BerekenLeveranciersKorting';
  //call TraceEind(@@ErrorTextProcedure + ' > @KortingSoort = '+string(@KortingSoort) + ', @KortingsBedrag = ' + string(@KortingsBedrag) + ', @KortingsPercentage = ' + string(@KortingsPercentage));
end;


create or replace procedure BerekenOrdersBepaalExtraRegelsZonderBtw(in @ObvBesteldOfTeFact integer, in @OrkGid integer, in @OrkInclBtw integer, in @BtwCode integer, in @BtwPerc numeric(6,2), out @BtwBasisExtraZonder numeric(15,2), out @TotaalInclBtwExtraZonder numeric(15,2))
begin
  //call TraceBegin('BerekenOrdersBepaalExtraRegelsZonderBtw(@OrkGid='+string(@OrkGid)+', @OrkInclBtw='+string(@OrkInclBtw)+', @BtwCode='+string(@BtwCode)+')');
  //Bereken afhankelijk van incl. of excl. BTW het totaalbedrag incl. en excl. BTW van de extra orderregels die zelf geen BTW hebben
  select
    sum(OerPerc/100 * ( isnull((select sum(case @ObvBesteldOfTeFact
                                             when 1 then OrrRegelTotaal        // Besteld aantal
                                             when 2 then OrrTeFactRegelTotaal  // Aantal nog te factureren
                                             when 3 then OrrDezeFactRegelTotaal// Aantal deze facturering
                                           end case)
                                from   tabOrderRegel
                                where  OrrOrkGid = @OrkGid and
                                       OrrRegelSoort in (1, 2) and
                                       OrrBtwCode = @BtwCode ), 0)) * if OerRegelSoort = 0 then -1 else 1 endif) as BtwBasis
  into   @BtwBasisExtraZonder
  from   tabOrderExtraRegel buiten
  where  OerBtwCode is null and OerOrkGid = @OrkGid and OerPerc is not null
  group by OerRegelNr
  order by OerRegelNr;

  if @OrkInclBtw = 0 then
    set @BtwBasisExtraZonder = isnull(@BtwBasisExtraZonder,0);
    set @TotaalInclBtwExtraZonder = (1 + @BtwPerc / 100) * @BtwBasisExtraZonder;
  else
    set @TotaalInclBtwExtraZonder = isnull(@BtwBasisExtraZonder,0);
    set @BtwBasisExtraZonder = @TotaalInclBtwExtraZonder / (1 + @BtwPerc / 100);
  end if;
  //call TraceEind('BerekenOrdersBepaalExtraRegelsZonderBtw(@BtwBasisExtraZonder='+string(@BtwBasisExtraZonder)+', @TotaalInclBtwExtraZonder='+string(@TotaalInclBtwExtraZonder)+')');
end;

//PG: 23/11/05 voor backward compatibility, extra parameter nodig bij aanroep functie hernoemt met dummy aanroep.
create or replace procedure BerekenProjectTotalen(in @PbGid integer, in @Project integer)
begin
  call BerekenProjectTotalenBasis(@PbGid,@Project,0,0,0);
end;


//BerekenProjectTotalen: Totaliseert alle takken in de boom vanaf een opgegeven projectonderdeel
//Extra parameter Project zorg ervoor dat alleen regel met dat projectnummer worden geselecteerd,
//bedragen van deelrojecten kunnen op die manier buiten de telling worden gehouden.
//Resultaat wordt opgeslagen in connectie-gebonden temporary table tmpProjectTotalen
//14-10-05: aangepast aan laatste eisen ontwerp projecten m.b.t. de te tonen kolommen met informatie
//PG: 23/11/05 extra parameter Mtw BTW toegevoegd, geeft nu per PBGid per BTWcode een regel terug
//             indien met Btw wordt gevraagd, functie hernoemd en oude naam met oude aantal paramters
//             weer toegevoegd als nieuwe functie.
//DG: 03/10/07 Param @Filter vervangen door @SessieNr en @AantalCats
create or replace procedure BerekenProjectTotalenBasis(
in @PbGid       integer,
in @Project     integer,
in @MetBtw      smallint,
in @SessieNr    integer,
in @AantalCats  integer
)

begin
  declare local temporary table tmpProjCalc(      //Voor opslag van saldi per tak
    tmpTakId                    integer,
    tmpParId                    integer,
    tmpKostprijsRegelTotaal     numeric(15,3),   //= begrootbedrag
    tmpVerkoopprijsRegelTotaal  numeric(15,3),   //= verkoopwaarde volgens normale prijsbepaling
    tmpOffertebedrag            numeric(15,3),   //= offertebedrag
    tmpOfferteBedragVastgesteld numeric(15,3),
    tmpVastgesteldBegrootBedrag numeric(15,3),   //= vastgesteld begroot bedrag

    tmpGeboekt                  numeric(15,3),   //= kostprijs van projectmutates
    tmpOnderHanden              numeric(15,3),   //= kostprijs van nog te factureren projectmutaties
                                                 //  (er wordt niet gekeken naar termijnfacturen!)
    tmpFactuurvoorstel          numeric(15,3),   //= waarde van onderhanden factuurvoorstellen
    tmpOmzetwaarde              numeric(15,3),   //= totale omzetwaarde (op regiebasis) als alles is/wordt gefactureerd
    tmpBtwCode                  integer null,    //= btwcode van geselecteerde artikelen/onderdelen....
    tmpLevel                    integer,
    tmpIsSom                    integer,
    tmpPcId                     integer default AutoIncrement,
    tmpTimestamp                datetime,
    tmpIsBedragAfwijkend        smallint)
  on commit preserve rows;

  declare @MaxLevel integer;

  set @@ErrorTextProcedure = 'BerekenProjectTotalenBasis > @PbGid='+string(@PbGid)+', @Project='+string(@Project)+', @MetBtw='+string(@MetBtw)+', @SessieNr='+string(@SessieNr)+', @AantalCats='+string(@AantalCats);
  //call TraceBegin(@@ErrorTextProcedure);


  select MAX(PbLevel)+1 into @MaxLevel from tabprojectboom;


  //Stap 1 totaliseer voorcalculaties per PbGid en btwcode
  //PvcOffertebedrag alleen meenemen als parent-onderdeel geen afwijkend offertebedrag heeft.
  //call Trace('BerekenProjectTotalenBasis > Aanvang stap 1: totaliseer voorcalculaties per PbGid en btwcode');

  insert into tmpProjCalc with auto name
  select
    PbGid                                                                                             as tmpTakId,
    PbParentPbGid                                                                                     as tmpParId,
    IsNull(sum(PvcKostprijsRegelTotaal), 0)                                                           as tmpKostprijsRegelTotaal,
    IsNull(sum(PvcVerkoopprijsRegelTotaal), 0)                                                        as tmpVerkoopprijsRegelTotaal,
    if max(PbOfferteBedragAfwijkend) is null then sum(PvcOffertebedrag) else 0 endif                  as tmpOffertebedrag,
    if IsNull(PbIsOfferteBedragVastgesteld, 0) = 0 then sum(PvcVastgesteldOfferteBedrag) else 0 endif as tmpOfferteBedragVastgesteld,
    IsNull(sum(PvcVastgesteldBegrootbedrag),0)                                                        as tmpVastgesteldBegrootBedrag,
    0                                                                                                 as tmpGeboekt,
    0                                                                                                 as tmpOnderHanden,
    0                                                                                                 as tmpFactuurvoorstel,
    0                                                                                                 as tmpOmzetwaarde,
    PbLevel                                                                                           as tmpLevel,
    0                                                                                                 as tmpIsSom,
    Max(PvcTimeStamp)                                                                                 as tmpTimestamp,
    PbIsOfferteBedragAfwijkend                                                                        as tmpIsBedragAfwijkend,
    artBtwCode                                                                                        as tmpBtwCode
  from
    tabProjectVoorcalculatie
    inner join tabprojectboom on  (PbGid = PvcPbGid
                              and (@Project=0 or PvcProjGid = @Project)
                              and (PvcPbGid in (select PbpPbGid from tabprojectboompad where PbpParentPbGid=@PbGid)))
    join tabartikel on artgid=pvcartgid
    where
    (
      (select count (*) from tabProjectSelectieCode inner join tmpProjSelCodes on tmpPscCode = PscCode and tmpPscSessieNr = @SessieNr WHERE PscPvcGid = PvcGid)
      >= @AantalCats
    )
  group by
    PbGid, PbParentPbGid, PbLevel, PbIsOfferteBedragAfwijkend, PbIsOfferteBedragVastgesteld, ArtBtwCode;

  //Stap 2: totaliseer projectmutaties per PbGid en Btwcode
  //call Trace('BerekenProjectTotalenBasis > Aanvang stap 2: totaliseer projectmutaties per PbGid en Btwcode');

  insert into tmpProjCalc with auto name
  select
    PbGid                                                                                       as tmpTakId,
    PbParentPbGid                                                                               as tmpParId,
    0                                                                                           as tmpKostprijsRegelTotaal,
    0                                                                                           as tmpVerkoopprijsRegelTotaal,
    0                                                                                           as tmpOffertebedrag,
    0                                                                                           as tmpOfferteBedragVastgesteld,
    0                                                                                           as tmpVastgesteldBegrootBedrag,
    IsNull(sum(pbrKostprijsRegelTotaal),0)                                                      as tmpGeboekt,
    IsNull(sum(pbrKostprijs*PbrAantalOpFactuurvoorstel*PbrPartFactEenheidFactor/PbrPrijsPer),0) as tmpOnderHanden,
    IsNull(sum(pbrAantalOpFactuurVoorstel*PbrVerkoopprijs/PbrPrijsPer),0)                       as tmpFactuurvoorstel,
    IsNull(sum(pbrVerkoopprijsRegeltotaal),0)                                                   as tmpOmzetwaarde,
    PbLevel                                                                                     as tmpLevel,
    0                                                                                           as tmpIsSom,
    Max(PbrTimeStamp)                                                                           as tmpTimestamp,
    PbIsOfferteBedragAfwijkend                                                                  as tmpIsBedragAfwijkend,
    ArtBtwCode                                                                                  as tmpBtwCode
  from
    tabProjectBoekingsRegel
    inner join tabprojectboom on  (PbGid=pbrPbGid
                              and (@Project=0 or pbrProjGid = @Project)
                              and (pbrPbGid in (select PbpPbGid from tabprojectboompad where PbpParentPbGid=@PbGid)))
    join tabartikel on artgid=pbrartgid
    where
    (
      (select count (*) from tabProjectSelectieCode inner join tmpProjSelCodes on tmpPscCode = PscCode and tmpPscSessieNr = @SessieNr WHERE PscPbrGid = PbrGid)
      >= @AantalCats
    )
  group by
    PbGid, PbParentPbGid, PbLevel, PbIsOfferteBedragAfwijkend, ArtBtwCode;

  //Stap 3: Doorrekenen projectboom
  //stap 3.1 Voor ieder pbgid is de som van pvc en pbr al berekend, nu de som van de onderliggende projectonderdelen toevoegen
  //         van onder naar boven, zodat als laatste level 1 de som van alles is.
  //         Wederom, als een parentonderdeel een afwijkend offertebedrag heeft offertebedrag niet meetellen.
  //call Trace('BerekenProjectTotalenBasis > Aanvang stap 3.1: Doorrekenen projectboom');

  WHILE @maxlevel >= 1 LOOP
   insert into tmpProjCalc(tmpTakId,tmpParId,tmpKostprijsRegelTotaal,tmpVerkoopprijsRegelTotaal,tmpOffertebedrag,
                            tmpVastgesteldBegrootBedrag, tmpGeboekt, tmpOnderHanden, tmpFactuurvoorstel,
                            tmpOmzetwaarde,tmpLevel,tmpIsSom, tmpTimestamp, tmpIsBedragAfwijkend, tmpBtwCode, tmpOfferteBedragVastgesteld)
    select
     PbGid,
     PbParentPbGid,
     sum(tmpKostprijsRegelTotaal),
     sum(tmpVerkoopprijsRegelTotaal),
     if max(PbOfferteBedragAfwijkend) is null then sum(tmpOffertebedrag) else 0 endif,
     sum(tmpVastgesteldBegrootBedrag),
     sum(tmpGeboekt),
     sum(tmpOnderHanden),
     sum(tmpFactuurvoorstel),
     sum(tmpVerkoopprijsRegeltotaal),
     @maxlevel - 1,
     1,
     Max(tmpTimeStamp),
     PbIsOfferteBedragAfwijkend,
     tmpBtwCode,
     if IsNull(PbIsOfferteBedragVastgesteld, 0) = 0 then sum(tmpOfferteBedragVastgesteld) else 0 endif
   from
     tmpProjCalc
     inner join tabProjectBoom on (PbGid = tmpParId)
   where
     tmpLevel = @maxlevel
   group by
     PbGid, PbParentPbGid, tmpBtwCode, PbIsOfferteBedragAfwijkend, PbIsOfferteBedragVastgesteld;

    //Stap 3.2 Invullen van de afwijkende offerte bedragen per projectonderdeel,
    //         Later besloten ook onderdeel zonder afwijkend bedrag mee te nemen, zodat deze timestamp meekomt.
    //         Lost probleem op dat parent niet werd ververst als afwijkend bedrag wed uitgezet.
    //call Trace('BerekenProjectTotalenBasis > Aanvang stap 3.2: Invullen van de afwijkende offerte bedragen per projectonderdeel');

    insert into tmpProjCalc with auto name
    select
      pbGid                                as tmpTakId,
      PbParentPbGid                        as tmpParId,
      0                                    as tmpKostprijsRegelTotaal,
      0                                    as tmpVerkoopprijsRegelTotaal,
      IsNull(PbOfferteBedragAfwijkend,0)   as tmpOffertebedrag,
      IsNull(PbOfferteBedragVastgesteld,0) as tmpOffertebedragVastgesteld,
      0                                    as tmpVastgesteldBegrootBedrag,
      0                                    as tmpGeboekt,
      0                                    as tmpOnderHanden,
      0                                    as tmpFactuurvoorstel,
      0                                    as tmpOmzetwaarde,
      @MaxLevel-1                          as tmpLevel,
      1                                    as tmpIsSom,
      pbTimestamp                          as tmpTimestamp,
      0                                    as tmpIsBedragAfwijkend,
      pbBtwCodeAfwijkend                   as tmpBtwCode
    from
      tabProjectBoom
    where
      (PbGid in (select PbpPbGid from tabProjectBoomPad where PbpParentPbGid = @PbGid union select @PbGid)) and PbLevel=@maxlevel-1;

    set @MaxLevel = @MaxLevel - 1;
  END LOOP;

  //null-stellen btw codes: altijd indien geen btwinformatie is gevraagd;
  if @MetBtw = 0 then
    update tmpProjCalc set tmpBtwCode = null;
  end if;

  //null-stellen btw codes: als btwinformatie is gevraagd dan nulstellen van alle regels die niet 'meetellen' omdat
  //offertebedrag op hoger niveau afwijkend is vastgelegd.
  //order by level zodat afwijkend bedrag doorwerkt naar diepere niveaus
  select MAX(PbLevel) into @MaxLevel from tabprojectboom;
  update  tmpProjCalc join tabprojectboom on pbgid=tmpParId
     set tmpBtwCode = null,
         tmpIsBedragAfwijkend=1 where pbIsOfferteBedragAfwijkend=1 or tmpIsBedragAfwijkend=1
     order by tmpLevel;

  delete from tmpProjectTotalen;

  //call Trace('BerekenProjectTotalenBasis > Projecttotalen tabel vullen');
  insert into tmpProjectTotalen with auto name
  select
    PbGid                                                                             as tmpPtPbGid,
    max(PbProjGid)                                                                    as tmpPtProjGid,
    sum(tmpKostprijsRegelTotaal)                                                      as tmpPtKostprijsRegelTotaal,
    sum(tmpVerkoopprijsRegelTotaal)                                                   as tmpPtVerkoopprijsRegelTotaal,
    sum(tmpOffertebedrag)                                                             as tmpPtOffertebedrag,
    sum(tmpOfferteBedragVastgesteld)                                                  as tmpPtOfferteBedragVastgesteld,
    sum(tmpVastgesteldBegrootBedrag)                                                  as tmpPtVastgesteldBegrootBedrag,
    sum(tmpGeboekt)                                                                   as tmpPtGeboekt,
    sum(tmpOnderHanden)                                                               as tmpPtOnderHanden,
    sum(tmpFactuurvoorstel)                                                           as tmpPtFactuurvoorstel,
    sum(tmpVerkoopprijsRegeltotaal)                                                   as tmpPTOmzetwaarde,
    if PbTimeStamp > max(tmpTimestamp) then PbTimeStamp else max(tmpTimestamp) endif  as tmpPtTimestamp,
    tmpBtwCode                                                                        as tmpPtBtwCode
  from
    tabProjectBoom
    inner join tmpProjCalc on (tmpTakId = PbGid)
  group by
    PbGid, PbTimeStamp, tmpBtwCode;

  set @@ErrorTextProcedure = 'BerekenProjectTotalenBasis';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure BerekenProjectTotalenBTW(in @PbGid integer, in @Project integer)
begin
  call BerekenProjectTotalenBasis(@PbGid,@Project,1, 0, 0);
end;


create or replace procedure BerekenProjectTotalenFilter(
in @PbGid       integer,
in @Project     integer,
in @SessieNr    integer,
in @AantalCats  integer
)
begin
  call BerekenProjectTotalenBasis(@PbGid, @Project, 0, @SessieNr, @AantalCats);
end;


create or replace procedure BerekenProjectVoortgang(
in @PbGid integer,
in @Project integer,
in @SessieNr    integer,
in @AantalCats  integer
)
begin
  call BerekenProjectVoortgangBasis (@PbGid, @Project, @SessieNr, @AantalCats, Null, Null, 1, 1, 1, 1);
end;


create or replace procedure BerekenProjectVoortgangAlle(
in @DatumVan Date,
in @DatumTM Date,
in @MutatieregelsMetStatusConcept      smallint,
in @MutatieregelsMetStatusIngeleverd   smallint,
in @MutatieregelsMetStatusAfgekeurd    smallint,
in @MutatieregelsMetStatusGeaccepteerd smallint
)
begin
  declare @TopLevelPbGid int;

  select PbGid into @TopLevelPbGid from tabprojectboom where pbLevel = 0;

  call BerekenProjectVoortgangBasis (@TopLevelPbGid, 0, -1, 0, @DatumVan, @DatumTM, @MutatieregelsMetStatusConcept ,@MutatieregelsMetStatusIngeleverd ,@MutatieregelsMetStatusAfgekeurd ,@MutatieregelsMetStatusGeaccepteerd);
end;


//BerekenProjectVoortgangBasis: Berekent de projectvoortgang voor een projectonderdeel en onderliggende onderdelen
//Extra parameter Project zorg ervoor dat alleen regels met dat projectnummer worden geselecteerd,
//bedragen van deelrojecten kunnen op die manier buiten de telling worden gehouden.
//Resultaat wordt opgeslagen in connectie-gebonden temporary table tmpProjectVoortgang

create or replace procedure BerekenProjectVoortgangBasis(
in @PbGid                              integer,
in @Project                            integer,
in @SessieNr                           integer,
in @AantalCats                         integer,
in @DatumVan                           Date,
in @DatumTM                            Date,
in @MutatieregelsMetStatusConcept      smallint,
in @MutatieregelsMetStatusIngeleverd   smallint,
in @MutatieregelsMetStatusAfgekeurd    smallint,
in @MutatieregelsMetStatusGeaccepteerd smallint
)

begin
  declare @MaxLevel integer;
  select MAX(PbLevel)+1 into @MaxLevel from tabProjectBoom;
  delete from tmpProjectVoortgang;

  //TG 22-09-2009, 12:08u: als de parameter niet gevuld wordt dan gaan we ervanuit dat de mutatiestatus meemoet (dus op 1 zetten)
  set @MutatieregelsMetStatusConcept      = IsNull(@MutatieregelsMetStatusConcept      , 1);
  set @MutatieregelsMetStatusIngeleverd   = IsNull(@MutatieregelsMetStatusIngeleverd   , 1);
  set @MutatieregelsMetStatusAfgekeurd    = IsNull(@MutatieregelsMetStatusAfgekeurd    , 1);
  set @MutatieregelsMetStatusGeaccepteerd = IsNull(@MutatieregelsMetStatusGeaccepteerd , 1);

  //Stap 1 totaliseer voorcalculaties per PbGid, ArtGid en PmwGid, Mutsoort en IsDirecteInkoop
  insert into tmpProjectVoortgang( tmpPvPbGid, tmpPvLopend, tmpPvRegelSoort, tmpPvProjGid, tmpPvArtGid, tmpPvPmwGid, tmpPvMutSoort, tmpPvIsDirecteInkoop,
  tmpPvBegrootAantal, tmpPvBegrootBedrag, tmpPvVastGesteldBegrootAantal, tmpPvVastGesteldBegrootBedrag,
  tmpPvGeboektAantal, tmpPvGeboektBedrag,
  tmpPvNogTeBestedenAantal,tmpPvNogTeBestedenBedrag,tmpPvNogTeBestedenVastgesteldAantal,tmpPvNogTeBestedenVastgesteldBedrag, tmpPvVerkoopWaarde, tmpPvOfferteAantal, tmpPvOfferteBedrag,
  tmpPvVerkoopBesteed, tmpPvVerkoopNogTeBesteden, tmpPvVerkoopNogTeBestedenVastgesteld)

  select
    PbGid,
    if IsNull(PbPercGereed,0)=100 then 0 else 1 endif as Lopend,
    0,
    max(PbProjGid),
    PvcArtGid,
    null, //PvcRelGid,
    PvcMutsoort,
    IsNull(PvcIsDirecteInkoop, 0),
    IsNull(sum(PvcBudAantal), 0),
    IsNull(sum(PvcKostprijsRegelTotaal), 0),
    IsNull(sum(PvcVastgesteldBudAantal), 0),
    IsNull(sum(PvcVastgesteldBegrootbedrag), 0),
    0,0,
    0,0,0,0,
    IsNull(sum(PvcVerkoopprijsRegelTotaal), 0),
    IsNull(sum(PvcOffAantal * PvcPartFactEenheidFactor), 0),
    IsNull(sum(PvcOfferteBedrag), 0),
    0,0,0
  from
    tabProjectVoorcalculatie
    inner join tabProjectBoom on  (PbGid = PvcPbGid
                              and (@Project=0 or PvcProjGid = @Project)
                              and (PvcPbGid in (select PbpPbGid from tabProjectBoomPad where PbpParentPbGid=@PbGid union select @PbGid)))
  where
    (
      (select count (*) from tabProjectSelectieCode inner join tmpProjSelCodes on tmpPscCode = PscCode and tmpPscSessieNr = @SessieNr WHERE PscPvcGid = PvcGid)
      >= @AantalCats
    )

  group by
    PbGid, Lopend, PvcArtGid, PvcRelGid, PvcMutSoort, PvcIsDirecteInkoop;

  //Stap 2 totaliseer mutaties per PbGid, ArtGid en PmwGid, Mutsoort en IsDirecteInkoop
  insert into tmpProjectVoortgang(tmpPvPbGid, tmpPvLopend, tmpPvRegelSoort, tmpPvProjGid, tmpPvArtGid,
                                  tmpPvPmwGid, tmpPvMutSoort, tmpPvIsDirecteInkoop, tmpPvBegrootAantal, tmpPvBegrootBedrag,
                                  tmpPvVastGesteldBegrootAantal, tmpPvVastGesteldBegrootBedrag, tmpPvGeboektAantal, tmpPvGeboektBedrag, tmpPvNogTeBestedenAantal,
                                  tmpPvNogTeBestedenBedrag, tmpPvNogTeBestedenVastgesteldAantal, tmpPvNogTeBestedenVastgesteldBedrag, tmpPvVerkoopWaarde, tmpPvOfferteAantal, tmpPvOfferteBedrag,
                                  tmpPvVerkoopBesteed, tmpPvVerkoopNogTeBesteden, tmpPvVerkoopNogTeBestedenVastgesteld )
  select
    PbGid,
    if IsNull(PbPercGereed,0)=100 then 0 else 1 endif as Lopend,
    0,
    max(PbProjGid),
    PbrArtGid,
    null, //PbrRelGid,
    PbrMutsoort,
    IsNull(PbrIsDirecteInkoop, 0),
    0,0,
    0,0,
    IsNull(sum(PbrAantalGeboekt), 0),
    IsNull(sum(PbrKostprijsRegelTotaal), 0),
    0,
    0,0,0,0,0, 0, //(if PbOfferteBedragAfwijkend = 0 then 0 else PbOfferteBedragAfwijkend endif),
    0,0,0
  from
    tabProjectBoekingsRegel
    inner join tabProjectBoom on  (PbGid=pbrPbGid
                              and (@Project=0 or pbrProjGid = @Project)
                              and (pbrPbGid in (select PbpPbGid from tabProjectBoomPad where PbpParentPbGid=@PbGid union select @PbGid)))
  where
    (
      (select count (*) from tabProjectSelectieCode inner join tmpProjSelCodes on tmpPscCode = PscCode and tmpPscSessieNr = @SessieNr WHERE PscPbrGid = PbrGid)
      >= @AantalCats
    )
    and
    (
      (@DatumVan is null or PbrMutatieDatum >= @DatumVan) and (@DatumTM is null or PbrMutatieDatum <= @DatumTM)
    )
    and
    (
        (@MutatieregelsMetStatusConcept      = 1 and PbrStatus = 0)
     or (@MutatieregelsMetStatusIngeleverd   = 1 and PbrStatus = 1)
     or (@MutatieregelsMetStatusAfgekeurd    = 1 and PbrStatus = 2)
     or (@MutatieregelsMetStatusGeaccepteerd = 1 and PbrStatus = 3)
    )

  group by
    PbGid, Lopend, PbrArtGid, PbrRelGid, PbrMutSoort, PbrIsDirecteInkoop;

  insert into tmpProjectVoortgang(
    tmpPvPbGid,                          tmpPvLopend,                         tmpPvRegelsoort,    tmpPvProjGid,             tmpPvArtGid,                   tmpPvPmwGid,
    tmpPvMutSoort,                       tmpPvIsDirecteInkoop,                tmpPvBegrootAantal, tmpPvBegrootBedrag,       tmpPvVastGesteldBegrootAantal,
    tmpPvVastGesteldBegrootBedrag,       tmpPvGeboektAantal,                  tmpPvGeboektBedrag, tmpPvNogTeBestedenAantal, tmpPvNogTeBestedenBedrag,
    tmpPvNogTeBestedenVastgesteldAantal, tmpPvNogTeBestedenVastgesteldBedrag, tmpPvVerkoopWaarde, tmpPvOfferteAantal, tmpPvOfferteBedrag,
    tmpPvVerkoopBesteed,                 tmpPvVerkoopNogTeBesteden,           tmpPvVerkoopNogTeBestedenVastgesteld)
  select
    tmpPvPbGid , max(tmpPvLopend), 1, tmpPvProjGid, tmpPvArtGid, tmpPvPmwGid,
    tmpPvMutSoort, tmpPvIsDirecteInkoop, sum(tmpPvBegrootAantal), sum(tmpPvBegrootBedrag), sum(tmpPvVastGesteldBegrootAantal),
    sum(tmpPvVastGesteldBegrootBedrag), sum(tmpPvGeboektAantal), sum( tmpPvGeboektBedrag), sum(tmpPvNogTeBestedenAantal), sum(tmpPvNogTeBestedenBedrag),
    sum(tmpPvNogTeBestedenVastgesteldAantal), sum(tmpPvNogTeBestedenVastgesteldBedrag), sum(tmpPvVerkoopWaarde), sum(tmpPvOfferteAantal), sum(tmpPvOfferteBedrag),
    sum(tmpPvVerkoopBesteed), sum(tmpPvVerkoopNogTeBesteden), sum(tmpPvVerkoopNogTeBestedenVastgesteld)
  from tmpProjectVoortgang
  group by
    tmpPvPbGid, tmpPvProjGid, tmpPvArtGid, tmpPvPmwGid, tmpPvMutSoort,tmpPvIsDirecteInkoop;

  delete from tmpProjectVoortgang where tmpPvRegelSoort=0;

  update tmpProjectVoortgang
  set    tmpPvNogTeBestedenAantal            = if ((tmpPvBegrootAantal - tmpPvGeboektaantal) >= 0) then (tmpPvBegrootAantal - tmpPvGeboektaantal) * tmpPvLopend else 0 endif,
         tmpPvNogTeBestedenVastgesteldAantal = if ((tmpPvVastgesteldBegrootAantal - tmpPvGeboektaantal) >= 0) then (tmpPvVastgesteldBegrootAantal - tmpPvGeboektaantal) * tmpPvLopend else 0 endif
  where  tmpPvRegelSoort=1;


  update tmpProjectVoortgang
    set
      tmpPvNogTeBestedenBedrag = tmpPvNogTeBestedenAantal *
        if tmpPvBegrootAantal = 0 then
          0
        else
          if tmpPvBegrootBedrag = 0 then
            if tmpPvGeboektAantal = 0 then
              0
            else
              tmpPvGeboektBedrag/tmpPvGeboektAantal
            endif
          else
            tmpPvBegrootBedrag/tmpPvBegrootAantal
          endif
        endif,

        tmpPvNogTeBestedenVastgesteldBedrag = tmpPvNogTeBestedenVastgesteldAantal *
          if tmpPvVastgesteldBegrootAantal = 0 then
            0
          else
            if tmpPvVastGesteldBegrootBedrag = 0 then
              if tmpPvGeboektAantal = 0 then
                0
              else
                tmpPvGeboektBedrag/tmpPvGeboektAantal
              endif
            else
              tmpPvVastGesteldBegrootBedrag/tmpPvVastgesteldBegrootAantal
            endif
          endif,

        tmpPvBudgetruimte = tmpPvBegrootBedrag - tmpPvGeboektBedrag - tmpPvNogTeBestedenAantal *
          if tmpPvBegrootAantal=0 then
            0
          else
            if tmpPvBegrootBedrag=0 then
              if tmpPvGeboektAantal = 0 then
                0
              else
                tmpPvGeboektBedrag/tmpPvGeboektAantal
              endif
            else
              tmpPvBegrootBedrag/tmpPvBegrootAantal
            endif
          endif,

        tmpPvBudgetruimteVastGesteld = tmpPvVastgesteldBegrootBedrag - tmpPvGeboektBedrag - tmpPvNogTeBestedenVastgesteldAantal *
          if tmpPvVastgesteldBegrootAantal = 0 then
            0
          else
            if tmpPvVastGesteldBegrootBedrag=0 then
              if tmpPvGeboektAantal = 0 then
                0
              else
                tmpPvGeboektBedrag/tmpPvGeboektAantal
              endif
            else
              tmpPvVastGesteldBegrootBedrag/tmpPvVastgesteldBegrootAantal
            endif
          endif

  where tmpPvRegelSoort=1;

  update tmpProjectVoortgang
  set    tmpPvVerkoopBesteed=if tmpPvOfferteAantal <> 0 then (tmpPvVerkoopWaarde / tmpPvOfferteAantal) * tmpPvGeboektAantal else 0 endif,
         tmpPvVerkoopNogTeBesteden=if tmpPvOfferteAantal <> 0 then (tmpPvVerkoopWaarde / tmpPvOfferteAantal) * tmpPvNogTeBestedenAantal else 0 endif,
         tmpPvVerkoopNogTeBestedenVastgesteld=if tmpPvOfferteAantal <> 0 then (tmpPvVerkoopWaarde / tmpPvOfferteAantal) * tmpPvNogTeBestedenVastgesteldAantal else 0 endif
  where  tmpPvRegelSoort=1;
end;


//--------- Bereken de vervaldatum van de factuur aan de hand van de betalingsconditie
create or replace procedure BerekenVervalDatumFactuur (in @FactuurDatum date, in @BtcNummer integer, inout @VervalDatum date)
begin
  declare @DagenMaanden integer;
  declare @Aantal integer;
  declare @Year integer;

  set @@ErrorTextProcedure = 'BerekenVervalDatumFactuur > @FactuurDatum='+string(@FactuurDatum)+', @BtcNummer='+string(@BtcNummer);
  //call TraceBegin(@@ErrorTextProcedure);
  set @Year = Year(@FactuurDatum);
  if (@Year <= 999) then           //bug:51971
    set @VervalDatum = now();
  else
    select DagenMaanden, AantalDgnMnd into @DagenMaanden, @Aantal from tabBetalingsconditie where Btcnummer = @BtcNummer;
    case @DagenMaanden
    when 1 then  //Einde maand
      set @VervalDatum = dateadd(day,-1,dateadd(month,1,String(Year(@FactuurDatum))+'-'+String(Month(@FactuurDatum))));
    when 2 then        //Dagen na factuurdatum
      set @VervalDatum = dateadd(day,@Aantal,@FactuurDatum);
    when 3 then  //Maanden na einde maand
      set @VervalDatum = dateadd(day,-1,dateadd(month,1+@Aantal,String(Year(@FactuurDatum))+'-'+String(Month(@FactuurDatum))));
      //dateadd(month,@Aantal,dateadd(day,-1,dateadd(month,1,String(Year(@FactuurDatum))+'-'+String(Month(@FactuurDatum)))));
     when 4 then //Werkdagen na factuurdatum
       set @VervalDatum = BerekenWerkdag(@FactuurDatum, @Aantal);
     else
       set @VervalDatum = @FactuurDatum;
  end case;

  end if;


  set @@ErrorTextProcedure = 'BerekenVervalDatumFactuur > @Vervaldatum='+string(@Vervaldatum);
  //call TraceEind(@@ErrorTextProcedure);

end;


//-------- Bereken de vervaldatum van de betalingskorting aan de hand van de betalingsconditie
create or replace procedure BerekenVervalDatumKorting(in @FactuurDatum date, in @BtcNummer integer, inout @VervalDatum date)
begin
  declare @DagenMaanden integer;
  declare @Aantal integer;

  set @@ErrorTextProcedure = 'BerekenVervalDatumKorting > @FactuurDatum='+string(@FactuurDatum)+', @BtcNummer='+string(@BtcNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  select GeldigDgMnd, GeldigAantal into @DagenMaanden, @Aantal from tabBetalingsconditie where Btcnummer = @BtcNummer;
  case @DagenMaanden
  when 1 then         //Dagen na factuurdatum
    set @VervalDatum = dateadd(day,@Aantal,@FactuurDatum);
  when 2 then    //Einde maand
    set @VervalDatum = dateadd(day,-1,dateadd(month,1,String(Year(@FactuurDatum))+'-'+String(Month(@FactuurDatum))));
  when 3 then    //Maanden na einde maand
    set @VervalDatum = dateadd(month,@Aantal,dateadd(day,-1,dateadd(month,1,String(Year(@FactuurDatum))+'-'+String(Month(@FactuurDatum)))));
   when 4 then //Werkdagen na factuurdatum
     set @VervalDatum = BerekenWerkdag(@FactuurDatum, @Aantal);
  else
    set @VervalDatum = @FactuurDatum;
  end case;

  set @@ErrorTextProcedure = 'BerekenVervalDatumKorting > @Vervaldatum='+string(@Vervaldatum);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function BerekenWerkdag(@Start datetime, @AantalDagen integer)
returns datetime
begin
  declare @DatumResult datetime;
  declare @teller  integer;

  set @DatumResult=@Start; //CONVERT(datetime ,(CONVERT(char(10),@Start,102)),102 );
  if @AantalDagen > 0 then
    set @teller=1;

    while @teller <= @AantalDagen
    loop
      SET @Datumresult = VolgendeWerkdag(@Datumresult, null);
      SET @teller=@teller+1;
    end loop;
  else
    // Kleiner dan 0, dus juist aantal dagen eraf halen
    set @teller=ABS(@AantalDagen);

    while @teller > 0
    loop
      set @Datumresult = VorigeWerkdag(@Datumresult, null);
      set @teller=@teller-1;
    end loop;
  end if;
  return(@Datumresult);
end;

create or replace procedure Bereken_Omzet_Inclusief_KortingToeslag_FactuurExtraRegels
  ( in    @SoortRegel     integer,       //1 = Tarief, 2 = Artikel
    in    @FrefGid        integer,       //Factuurreferentie
    in    @BrutoOmzet     numeric(15,2),
    in    @IsInclBtw      integer,
    in    @BtwPercentage  numeric(6,2),
    inout @Omzet          numeric(15,2)
  )
//Hierin berekenen we de omzet inclusief de extra factuurregels voor korting/toeslag.
//call Bereken_Omzet_Inclusief_KortingToeslag_FactuurExtraRegels(...);
begin atomic
  declare @ferSoortRegel                  integer;
  declare @ferPercentage                  numeric(5,2);
  declare @BerekenOver                    integer; //1=over brutobedragen (excl. regelkortingen), 2=over regeltotalen (incl. regelkortingen)
  declare @BerekenMetOmzet                numeric(15,2);

  declare cursor_ExtraRegels  scroll cursor for
    select   ferSoortRegel, ferPercentage, if @SoortRegel = 1 then ferBerekenOverTarief else ferBerekenOverArtikel endif
    from     tabFactuurExtraRegel
    where    FerFrefGid = @FrefGid  and
             (@SoortRegel in (1,2)) and
             ((@SoortRegel = 1 and ferBerekenOverTarief <> 0) or (@SoortRegel = 2 and ferBerekenOverArtikel <> 0))
    order by ferRegelNummer
  for read only;

  //Korting/toeslag berekenen
  open cursor_ExtraRegels;
  ExtraRegels:
  Loop
    Fetch next cursor_ExtraRegels into @ferSoortRegel, @ferPercentage, @BerekenOver;
    if sqlstate = '02000' then
      leave ExtraRegels;
    end if;

    //1   = Bereken over brutobedragen
    //0,2 = Bereken over regeltotalen (incl. regel/stukskortingen)
    set @BerekenMetOmzet = if (@BerekenOver = 1) then @BrutoOmzet else @Omzet endif;

    case @ferSoortRegel
      when 0 then  // Korting
        set @Omzet = @Omzet - (@BerekenMetOmzet * @ferPercentage) / 100;
      when 1 then  // Toeslag
        set @Omzet = @Omzet + (@BerekenMetOmzet * @ferPercentage) / 100;
    end case;
  end loop ExtraRegels;
  close cursor_ExtraRegels;

  //Bedrag eventueel exclusief BTW uitrekenen
  if @IsInclBtw = 1 then
    set @Omzet = @Omzet / (100 + @BtwPercentage) * 100;
  end if;

end;


create or replace procedure BestelAdviesGenereren(
//----- Genereer besteladvies om magazijnvoorraden aan te vullen en eventueel directe inkooporders te bestellen -------
  in  @ConnectionId                       integer,
  in  @LoginTime                          datetime,
  in  @MagazijnVoorraadBestellen          smallint,
  in  @DirecteInkoopOrdersBestellen       smallint,
  in  @BestellingenVerzamelen             smallint,
  in  @SamenvoegMagGid                    integer,
  in  @MagSelect                          smallint,
  in  @VanMag                             nchar(40),
  in  @TotMag                             nchar(40),
  in  @NawLevSelect                       smallint,
  in  @VanNawLev                          nchar(40),
  in  @TotNawLev                          nchar(40),
  in  @ArtSelect                          smallint,
  in  @VanArt                             nchar(40),
  in  @TotArt                             nchar(40),
  in  @VanOpbrGrp                         nchar(4),
  in  @TotOpbrGrp                         nchar(4),
  in  @OrderSelect                        smallint,
  in  @VanOrder                           nchar(10),
  in  @TotOrder                           nchar(10),
  in  @BestelRegels                       smallint,
  in  @TermijnVoorraadPositie             integer,
  in  @RekeningHoudenLevertijden          smallint,
  in  @BestelDatum                        date,
  in  @BestelTijd                         time,
  in  @OntvangstDatum                     date,
  in  @OntvangstDatumAutomVullen          smallint,
  in  @ArtikelenZonderLeverancierMeenemen smallint,
  in  @VoorraadPositieOpDatumGebruiken    smallint,
  in  @InVeelvoudBestelgrootte            smallint,
  in  @ArtikelOpnemenIndien               smallint,
  in  @RelGid                             integer,
  in  @OrdersVolgensArtikelSelectie       integer,
  in  @KeuzeInkoper                       smallint,
  in  @PerOrderAparteBestelling           smallint,
  in  @PerOrderRegelAparteBestelRegel     smallint,
  out @Resultaat                          smallint,
  out @BakGid                             integer
  )
begin
  declare @Teller integer;
  declare @InsertedBakGid integer;
  declare @BarGid integer;
  declare @ProgressCreate integer;
  declare @AantalInVoorraadEenheden numeric(15,3);
  declare @LockString nchar(100);
  declare @DefOmsRegels smallint;
  declare @MatViewNr nchar(20);
  declare @GegenereerdBestelAdviesTekst long nvarchar;

  set @GegenereerdBestelAdviesTekst = _A('Gegenereerd besteladvies');

  set @@ErrorTextProcedure = 'BestelAdviesGenereren > ';
  //call TraceBegin(@@ErrorTextProcedure + '@MagazijnVoorraadBestellen = ' + string(@MagazijnVoorraadBestellen) + ', @VanMag = ' + string(@VanMag) + ', @TotMag = '+string(@TotMag));

  set @ProgressCreate = 0;
  call ProgressCreate(1, 2, _U('Aanmaken besteladvies voor magazijnen'));

  if @VoorraadPositieOpDatumGebruiken = 0 then
    set @TermijnVoorraadPositie = 0
  end if;

  // Vaste gegevens opvragen
  select VgbDefOmsRegels into @DefOmsRegels from tabVasteGegevensBestellingen;

  set @Resultaat = 1;
  set @BakGid = null;
  set @Teller = 1;
  while @Teller <= 999 loop
    if not exists(select 1 from tabBestelAdviesKop where BakNummer = @Teller) then
      insert into tabBestelAdviesKop (BakNummer, BakOmschrijving, BakBestelDatum, BakBestelTijd, BakIsOntvangstdatumVullenObvAfleverdagen, BakOntvangstDatum, BakIsInVeelvoudBestelgrootte,
                                      BakRekeningHoudenMetBestelling, BakIsRekeningHoudenMetLevertijd, BakIsMagazijnSamengevoegd, BakMagGidSamengevoegd,
                                      BakIsUitgaanVanVoorraadPositie, BakUitgaanVanVoorraadPositieOverDagen, BakArtikelOpnemenIndien, BakRelGid, BakDefaultInkoper,
                                      BakPerOrderAparteBestelling, BakPerOrderregelAparteBestelregel, BakMagazijnVoorraadBestellen, BakDirecteInkoopOrdersBestellen,
                                      BakMagSelect, BakMagVan, BakMagTot, BakNawLevSelect, BakNawLevVan, BakNawLevTot, BakArtSelect, BakArtVan, BakArtTot,
                                      BakOpbrGrpVan, BakOpbrGrpTot, BakOrderSelect, BakOrderVan, BakOrderTot, BakRekeninghoudenMetSelectieBlok)
      select @Teller, @GegenereerdBestelAdviesTekst, @BestelDatum, @BestelTijd, @OntvangstDatumAutomVullen, @OntvangstDatum, @InVeelvoudBestelgrootte,
             @BestelRegels, @RekeningHoudenLevertijden,@BestellingenVerzamelen, @SamenvoegMagGid,
             @VoorraadPositieOpDatumGebruiken, @TermijnVoorraadPositie, @ArtikelOpnemenIndien, @RelGid, @KeuzeInkoper,
             @PerOrderAparteBestelling, @PerOrderRegelAparteBestelRegel, @MagazijnVoorraadBestellen, @DirecteInkoopOrdersBestellen,
             @MagSelect, @VanMag, @TotMag, @NawLevSelect, @VanNawLev, @TotNawLev, @ArtSelect, @VanArt, @TotArt,
             @VanOpbrGrp, @TotOpbrGrp, @OrderSelect, @VanOrder, @TotOrder, @OrdersVolgensArtikelSelectie;
      set @InsertedBakGid = @@Identity;
      set @LockString = 'BakGid = '+string(@InsertedBakGid);
      call LockSetOnId(@ConnectionId, @LoginTime, 1, 'tabBestelAdviesKop', @LockString, null);
      set @Resultaat = 0;
      set @Teller = 999;
    end if;
    set @Teller = @Teller + 1;
  end loop;

  if @DirecteInkoopOrdersBestellen <> 0 and @Resultaat = 0 then
  begin
    declare @AanmakenVoorOrdersTekst long nvarchar;
    set @AanmakenVoorOrdersTekst = _U('Aanmaken besteladvies voor orders');

    set @ProgressCreate = 0;
    call ProgressCreate(0, 1, @AanmakenVoorOrdersTekst);
    //call Trace('BestelAdviesGenereren > Orders meenenem die voor directe inkoop zijn');
    for @Cursor As Cursor_TeBestellenOrderRegels Cursor For
      select   distinct OrrArtGid @ArtGid,
               if @BestellingenVerzamelen = 1 then
                 @SamenvoegMagGid
               else
                 OrrMagGid
               endif @MagGid, NawGid @NawGid, OrrGid @OrrGid, if ArtIsPartijRegistreren <> 0 then OrrArtPartijGid endif @ArtPartijGid, OrrAantalBackorderVrrdEenh @OrrAantalBackorderVrrdEenh, isnull(AldVoorraadEenhedenInInkoopEenheid, 1) @VoorraadEenhedenInInkoopEenheid,
               if AldGid is null then ArtOmsEenheid else AldInkoopEenheid endif @InkoopEenheid, OrkNummer @OrkNummer,
               //ACW 01-02-2010 bug 32135, 32142, 32143 - Inkoopeenheid-oms, anders afhankelijk van vaste gegevens, maar wel ALTIJD documentsoort 50!!
               //ACW 06-05-2010: Uitbreiding naar partij -> Indien aparte TekstOpFactuur van de partijen, dan partijomschrijving in de juiste taal OF de partijomschrijving nemen; als die leeg is, dan pas bij artikel kijken
               if OrrOmsNaarBestelling = 0 then
                 IsNull((if isnull(AldOmsBijLeverancier, '')<> '' then AldOmsBijLeverancier endif),
                        if @DefOmsRegels =  0 /*TekstOpFactuur*/ and @ArtPartijGid is not null and ArtIsPartijAparteTekstOpFactuur <> 0 then (select ArtPartijTekstOpFactuur from tabArtikelPartijTeksten where (ArtPartijTekstArtPartijGid = @ArtPartijGid and ArtPartijTekstTaalGid = IsNull(NawTaalGid, (select DefaultTaalgid from tabvastegegevens)))) endif,
                        if @DefOmsRegels <> 2 /*Leeg*/           and @ArtPartijGid is not null and ArtIsPartijAparteTekstOpFactuur <> 0 then if ArtPartijOms <> '' then ArtPartijOms endif endif,
                        if @DefOmsRegels =  0 /*TekstOpFactuur*/ then (select ArtTekst from tabArtikelTeksten where (ArtTekstArtGid = OrrArtGid and ArtTekstDocSoort = 50 /*Factuur-batch*/ and ArtTaalGid = IsNull(NawTaalGid, (select DefaultTaalgid from tabvastegegevens)))) endif,
                        if @DefOmsRegels <> 2 /*Leeg*/           then ArtOms endif)
               else
                 OrrTekstOpFactuur endif @BarOmschrijvingOpBestelbrief,
               if OrrDirecteLevering = 2 /*Volgens lev./IE*/ then
                 if    (isnull(LevGegDirLevGeschikt, 1) = 0 /*Leveranciersgegevens gevonden EN niet geschikt voor directe levering*/)
                    or (isnull(AldDirecteLevering, 1) = 0 /*IE gevonden EN niet geschikt*/) then
                   0 /*Bestemming = Magazijn*/
                 else
                   // Leverancier niet gevonden of toegestaan
                   if isnull(AldDirecteLevering, 0) = 2 /*Toegestaan, default via directe levering*/ then
                     1 /*Bestemming = debiteur*/
                   else
                    0 /*(default) IE niet gevonden of niet default*/
                   endif
                 endif
               else
                 OrrDirecteLevering
               endif @Bestemming,
               /*Gegevens voor aflevering aan klant*/
               if OrkVerzendAdres / 3 = 0 then OrkNawGid else OrkFactuurNawGid endif @DirLevAfleverNawGid, /*Orderdebiteur of Factuurdebiteur (indien in verzendadres zo aangegeven)*/
               mod(OrkVerzendAdres, 3) @DirLevAfleverVerzendadres,  /* Alleen 0, 1, 2 mogelijk; van factuurdeb. geldt ook 0, 1 of 2!*/
               OrkAdrGid       @DirLevAfleverAdrGid,
               (select OrdRelRelGid from tabOrderRelatieVoorDocument where OrdRelOrkGid = OrkGid and OrdRelDocSoort = 30 /*Pakbon*/) @DirLevRelGid,

               rank() OVER AantalWindow as @AantalRecords
      from     tabOrderKop
               inner join tabOrderRegel                         on (OrkGid     = OrrOrkGid)
               inner join tabArtikel                            on (ArtGid     = OrrArtGid)
               left outer join tabBestelAdviesRegelSpecificatie on (BarsOrrGid = OrrGid)
               left outer join tabBestelRegelDetail             on (BrdOrrGid  = OrrGid)
               left outer join tabMagazijnOntvangstenDetail     on (MagOntDetOrrGid = OrrGid)
               left outer join tabArtikelLeverancier            on (    (ArtLevArtGid = OrrArtGid)                                                         // MOET leverancier van artikel zijn
                                                                    and (   (OrrNawGidDirecteInkoop is     null and ArtLevIsDefault = 1)                   // Geen leverancier in orderregel opgegeven, dan de default lev.
                                                                         or (OrrNawGidDirecteInkoop is not null and ArtLevNawGid = OrrNawGidDirecteInkoop) // Wel leverancier in orderregel opgegeven, dan die gebruiken
                                                                        )
                                                                   )
               left outer join (tabNaw
                                inner join tabNawFile on (NawFilNawGid = NawGid and NawFilFonId = 'C')
                               )                                on (NawGid       = isnull(OrrNawGidDirecteInkoop, ArtLevNawGid))
               left outer join tabLeverancierGegevens           on (LevGegNawGid = NawGid)
               left outer join tabArtikelLeverancierDetail      on (    (AldArtLevGid = ArtLevGid)
                                                                    and (   (OrrDirInkInkoopEenheid =  '' and AldIsDefaultInkoopEenheidBijLev = 1)
                                                                         or (OrrDirInkInkoopEenheid <> '' and AldInkoopEenheid = OrrDirInkInkoopEenheid)
                                                                        )
                                                                   )
               left outer join tabArtikelPartij                 on (ArtPartijGid = @ArtPartijGid)
               inner join tabMagazijn on (MagGid = OrrMagGid)
      where    OrkGoedgekeurd = 1 and OrrRegelsoort = 2 and OrrDirecteInkoop = 1 and OrrAantalBackorderVrrdEenh > 0 and BarsOrrGid is null and BrdOrrGid is null and MagOntDetOrrGid is null and
          ((@OrderSelect = 0 and (OrkNummer between @VanOrder and @TotOrder)) or
           (@OrderSelect = 1 and OrkNawGid in (select NawFilNawGid from tabNawFile where NawFilNummer between @VanOrder and @TotOrder))) and

          ((@OrdersVolgensArtikelSelectie = 0) or
          ((
            (
              (@NawLevSelect = 0 and NawFilNummer   between @VanNawLev and @TotNawLev) or
              (@NawLevSelect = 1 and NawFilZoekCode between @VanNawLev and @TotNawLev) or
              (@NawLevSelect = 2 and NawGid in (select AdrNawGid from tabAdres where NawGid = AdrNawGid and AdrGid = NawGidVestiging and AdrNaam1 between @VanNawLev and @TotNawLev))
            ) or
            (@ArtikelenZonderLeverancierMeenemen = 1 and NawGid is Null)
          )
          and
            (
              (@MagSelect = 0 and (right('000'+string(MagCode),3) between @VanMag and @TotMag)) or
              (@MagSelect = 1 and (MagZoekCode                    between @VanMag and @TotMag)) or
              (@MagSelect = 2 and (MagOms                         between @VanMag and @TotMag))
            )
          and
            ((@ArtSelect = 0 and (ArtCode        between @VanArt and @TotArt)) or
             (@ArtSelect = 1 and (ArtZoekCode    between @VanArt and @TotArt)) or
             (@ArtSelect = 2 and (ArtOms         between @VanArt and @TotArt)))
          and
            (ArtOpbrGrpGID in (select OpbrGrpGID from tabOpbrengstgroep where OpbrGrpNummer between @VanOpbrGrp and @TotOpbrGrp))
          ))
      window AantalWindow as (order by OrrGid desc)  //De Orderby van dit statement en van de query niet veranderen. Aantal bij het eerste record, geeft het aantal records van deze select terug
      order by OrrGid

    for read only
    do
      if @ProgressCreate = 0 then
        call ProgressCreate(1, @AantalRecords, @AanmakenVoorOrdersTekst);
        set @ProgressCreate = 1
      end if;
      call ProgressAdd(1);

      // Bestemming = magazijn, dan alle bestemmingsvelden leeg maken
      if @Bestemming = 0 /*Magazijn*/ then
        set @DirLevAfleverNawGid      = null;
        set @DirLevAfleverVerzendadres= null;
        set @DirLevAfleverAdrGid      = null;
        set @DirLevRelGid             = null;
      end if;

      set @BarGid = null;
      if (@PerOrderRegelAparteBestelRegel = 0) then //Kijk of er al een zelfde soort bestelregel is, dan kunnen we deze orderregel daaronder hangen, de orderregels hoeven niet als aparte bestelregels te worden opgenomen
        //ACW 06-05-2010: Bestellen met partij -> Indien partij in verkooporder is ingevoerd, dan ook in advies meenemen

        select BarGid into @BarGid from tabBestelAdviesRegel
        where BarBakGid = @InsertedBakGid and BarArtGid = @ArtGid and isnull(@ArtPartijGid, BarArtPartijGid-1, 0) = isnull(BarArtPartijGid, @ArtPartijGid - 1, 0 )
              and BarMagGid = @MagGid and IsNull(BarNawGid,0) = IsNull(@NawGid,0) and BarInkoopEenheid = @InkoopEenheid and BarOmschrijvingOpBestelbrief = @BarOmschrijvingOpBestelbrief
              and BarBestemming = @Bestemming
              and (   (@Bestemming = 0) /*Magazijn -> is al vergeleken*/
                   or (    (@Bestemming = 1)
                       and (BarNawGidAflevering = @DirLevAfleverNawGid)
                       and (BarAfleveradresNAW  = @DirLevAfleverVerzendadres)
                       and (@DirLevAfleverVerzendadres <> 3 /*Verzendadres*/ or isnull(BarAdrGidAflevering, 0) = isnull(@DirLevAfleverAdrGid, 0))
                       and (isnull(BarRelGid, 0) = isnull(@DirLevRelGid, 0) or @DirLevRelGid is null) // Geen relatie in verkooporderregel aangegeven, dan is het altijd goed!
                      )
                  )
              // Omdat meerdere orders in 1 besteladvies komen, controleren of deze verk.order samen met een andere verkooporder op 1 bestelregel mag komen
              and (@PerOrderAparteBestelling = 0
                   or (    (@PerOrderAparteBestelling = 1)
                       and @OrkNummer in (select OrkNummer from tabBestelAdviesRegelSpecificatie
                                                 inner join tabOrderRegel on (OrrGid = BarsOrrGid)
                                                 inner join tabOrderKop   on (OrkGid = OrrOrkGid)
                                                 where BarsBarGid = BarGid)
                      )
                  );
      end if;

      //call Trace('BestelAdviesGenereren > @InsertedBakGid = ' + string(@InsertedBakGid) + ', @BarGid = ' + string(@BarGid) + ', @ArtGid = ' + string(@ArtGid) + ', @ArtPartijGid = ' + string(@ArtPartijGid));
      if @BarGid is null then
        insert into tabBestelAdviesRegel (BarBakGid, BarArtGid, BarArtPartijGid, BarMagGid, BarNawGid, BarInkoopEenheid, BarVoorraadEenhedenInInkoopEenheid, BarOmschrijvingOpBestelbrief, BarBestemming, BarNawGidAflevering,  BarAfleveradresNAW,         BarAdrGidAflevering,  BarRelGid)
                                  select   @InsertedBakGid,   @ArtGid,   @ArtPartijGid,   @MagGid,   @NawGid,   @InkoopEenheid,   @VoorraadEenhedenInInkoopEenheid, @BarOmschrijvingOpBestelbrief,  @Bestemming, @DirLevAfleverNawGid, @DirLevAfleverVerzendadres, @DirLevAfleverAdrGid, @DirLevRelGid;
        set @BarGid = @@Identity;
      end if;
      insert into tabBestelAdviesRegelSpecificatie (BarsBarGid, BarsOrrGid, BarsAantalInVoorraadEenheden, BarsSoort)
      select   @BarGid, @OrrGid, @OrrAantalBackorderVrrdEenh, 1; /* Verkooporder */
    end for;
    end;
  end if;

  // Gebruik materialized view
  call PooledMatViewUse(0,1,@MatViewNr);

  if @MagazijnVoorraadBestellen <> 0 and @Resultaat = 0 then
  begin
    declare @AanmakenVoorMagazijnenTekst long nvarchar;

    // Variable type MOET varchar zijn, wordt gebruikt als dynamsche tablename
    declare @vwVoorraadAantallenMatViewNr varchar(100) = 'vwVoorraadAantallen'||@MatViewNr;
    set @ProgressCreate = 0;
    set @AanmakenVoorMagazijnenTekst = _U('Aanmaken besteladvies voor magazijnen');

    call ProgressCreate(1, 2, @AanmakenVoorMagazijnenTekst);
    for @Cursor As Cursor_TeBestellenArtikelen Cursor For
      select
        // Artikelgegevens
        ArtGid @ArtGid,
        ArtOms @ArtOms,
        // Inkoopprijs
        if AldGid is null then
          0
        else
          1
        endif @InkoopEenheidBeschikbaar,
        if (@InkoopEenheidBeschikbaar = 0) or (AldHeeftEigenInkoopprijs = 0) then
          if @@BasisValutaNummer = IsNull (NawFilValNummer, @@BasisValutaNummer) then
            ArtKostprijsEx
          else
            ValutaOmrekenen(@@BasisValutaNummer, ArtKostprijsEx, NawFilValNummer, @@BjGid, @@Pernr, ArtAantDecPrijzen)
          endif
        else
          if AldValNummer = IsNull (NawFilValNummer, @@BasisValutaNummer) then
            AldInkoopPrijs
          else
            ValutaOmrekenen(AldValNummer, AldInkoopPrijs, NawFilValNummer, @@BjGid, @@Pernr, ArtAantDecPrijzen)
          endif
        endif InkoopPrijs,
        // Magazijngegeven
        if @BestellingenVerzamelen = 1 then
          @SamenvoegMagGid
        else
          MagGid
        endif @MagGid,
        // Voorraad gegevens
        sum(if (MagGid = calcMagGid) then calcMinimumVoorraad else 0 endif) @MinimumVoorraad,
        sum(if (MagGid = calcMagGid) then calcMaximumVoorraad else 0 endif) @MaximumVoorraad,
        sum(if (MagGid = calcMagGid) then
              calcEconomischeVoorraad - calcInBestellingVoorEconomischeVoorraad + calcInBestellingVerwerkt +
              if @BestelRegels = 0 then
                calcInBestellingConcept + calcInBestellingGoedgek
              else
                if @BestelRegels = 1 then calcInBestellingGoedgek else 0 endif
              endif
            else
              0
            endif) @ArtikelVoorraad,
        // NawFile gegevens (hoeft er niet te zijn)
        NawFilNawGid @NawGid,
        NawTaalGid @NawTaalGid,
        // ArtikelLeverancier gegevens (hoeft er niet te zijn)
        AldGid @AldGid,
        AldLeverTijd,
        AldVoorraadEenhedenInInkoopEenheid @AldVoorraadEenhedenInInkoopEenheid,
        if AldGid is null then ArtOmsEenheid else AldInkoopEenheid endif @InkoopEenheid,
        //ACW 01-02-2010 bug 32135, 32142, 32143 - Inkoopeenheid-oms, indien leeg, dan ook echt leeg houden
        if isnull(AldOmsBijLeverancier, '') <> '' then AldOmsBijLeverancier endif @AldOmsBijLeverancier,
        AldHeeftEigenInkoopprijs,
        AldBestelGrootte @AldBestelGrootte,
        AldMinimumAfname @AldMinimumAfname,

        //ACW 01-02-2010 bug 32135, 32142, 32143 - Inkoopeenheid-oms, anders afhankelijk van vaste gegevens, maar wel ALTIJD documentsoort 50!!
        IsNull(@AldOmsBijLeverancier,
               if @DefOmsRegels = 0 /*TekstOpFactuur*/ then (select ArtTekst from tabArtikelTeksten where (ArtTekstArtGid = ArtGid and ArtTekstDocSoort = 50 /* factuur-batch */ and ArtTaalGid = IsNull(NawTaalGid, (select DefaultTaalgid from tabvastegegevens)))) endif,
               if @DefOmsRegels <> 2 /*Leeg*/ then ArtOms endif) @BarOmschrijvingOpBestelbrief,
        DateAdd (day, + @TermijnVoorraadPositie + (if @RekeningHoudenLevertijden = 1 then IsNull (AldLeverTijd, 0) else 0 endif), IsNull (@BestelDatum, Date(Now(*)))) DatumVoorraadPositie,
        IsNull(LevGegBestellenGeblokkeerd,0) as LevGegBestellenGeblokkeerd,
        rank() OVER AantalWindow as @AantalRecords
      from tabArtikel
      left outer join `[@vwVoorraadAantallenMatViewNr]` on (calcArtGid = ArtGid)
      left outer join tabMagazijn on (MagGid = calcMagGid) or ((MagGid <> isnull(calcMagGid,0)) and  (@ArtikelOpnemenIndien = 2 /*Altijd*/))
      left outer join tabArtikelLeverancier on ArtLevArtGid = ArtGid and ArtLevIsDefault = 1
      left outer join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid and AldIsDefaultInkoopEenheidBijLev = 1
      left outer join (tabNaw inner join tabNawFile on NawGid = NawFilNawGid and NawFilFonId = 'C')
      on NawFilNawGid = ArtLevNawGid
      left outer join tabLeverancierGegevens on (LevGegNawGid = NawGid)
      where
        ArtSoort = 2 and
        ArtIsGeblokkeerdInkoop = 0 and
        ArtIsGebruikVoorBestelAdvies <> 0
        and
        // Voorloopscherm (door gebruiker opgegeven) restricties
        (
          (
            (@NawLevSelect = 0 and NawFilNummer   between @VanNawLev and @TotNawLev) or
            (@NawLevSelect = 1 and NawFilZoekCode between @VanNawLev and @TotNawLev) or
            (@NawLevSelect = 2 and NawGid in (select AdrNawGid from tabAdres where NawGid = AdrNawGid and AdrGid = NawGidVestiging and AdrNaam1 between @VanNawLev and @TotNawLev))
          ) or
          (@ArtikelenZonderLeverancierMeenemen = 1 and NawGid is Null)
        )
        and
          ((@VoorraadPositieOpDatumGebruiken = 0) or (calcDatum is null) or (calcDatum <= DatumVoorraadPositie))
        and
          (
            (@MagSelect = 0 and (right('000'+string(MagCode),3) between trim(@VanMag) and trim(@TotMag))) or
            (@MagSelect = 1 and (MagZoekCode                    between @VanMag and @TotMag)) or
            (@MagSelect = 2 and (MagOms                         between @VanMag and @TotMag))
          )
        and
          ((@ArtSelect = 0 and (ArtCode        between @VanArt and @TotArt)) or
           (@ArtSelect = 1 and (ArtZoekCode    between @VanArt and @TotArt)) or
           (@ArtSelect = 2 and (ArtOms         between @VanArt and @TotArt)))
        and
          (ArtOpbrGrpGID in (select OpbrGrpGID from tabOpbrengstgroep where OpbrGrpNummer between @VanOpbrGrp and @TotOpbrGrp))
      group by
        // Artikelgegevens
        ArtGid,
        ArtOms,
        ArtOmsEenheid,
        @InkoopEenheidBeschikbaar,
        InkoopPrijs,
        NawTaalGid,
        NawFilNawGid,
        AldHeeftEigenInkoopprijs,
        AldGid,
        AldLeverTijd,
        AldVoorraadEenhedenInInkoopEenheid,
        AldInkoopEenheid,
        AldOmsBijLeverancier,
        AldBestelGrootte,
        AldMinimumAfname,
        @MagGid,
        DatumVoorraadPositie,
        LevGegBestellenGeblokkeerd
      having
        //ACW 13-07-2010: Parameter uitgebreid; is nu een combobox ipv. een checkbox
        (   (@ArtikelOpnemenIndien = 2 /*Altijd*/)
         or (@ArtikelOpnemenIndien = 0 /*Alleen indien onder minimumvoorraad*/ and @ArtikelVoorraad < @MinimumVoorraad)
         or (@ArtikelOpnemenIndien = 1 /*Alleen indien onder maximumvoorraad*/ and @ArtikelVoorraad < @MaximumVoorraad)
        )
      window AantalWindow as (order by ArtGid desc)  //De Orderby van dit statement en van de query niet veranderen. Aantal bij het eerste record, geeft het aantal records van deze select terug
      order by ArtGid

    for read only
    do
      if @ProgressCreate = 0 then
        call ProgressCreate(1, @AantalRecords, @AanmakenVoorMagazijnenTekst);
        set @ProgressCreate = 1;
      end if;
      call ProgressAdd(1);

      set @BarGid = null;
      //ACW 06-05-2010: Bestellen met partij -> Magazijnen altijd zonder partij! (Dus ook niet samenvoegen met partijregels)
      if (@PerOrderRegelAparteBestelRegel = 0) then //Kijk of er al een zelfde soort bestelregel is, dan kunnen we deze orderregel daaronder hangen, de orderregels hoeven niet als aparte bestelregels te worden opgenomen
        if (@PerOrderAparteBestelling = 1) then //Kijk of er al een bestelregel is, waar een specificatie regel onder hangt, waarbij een orderregel wordt gebruikt, die bij hetzelfde ordernummer hoort als het ordernummer dat bij het huidige orderregelgidje hoort
          //call trace('BestelAdviesGenereren > 2!');
          select BarGid into @BarGid
          from   tabBestelAdviesRegel
          where  BarBakGid = @InsertedBakGid and BarArtGid = @ArtGid and BarArtPartijGid is null and BarMagGid = @MagGid and BarNawGid = @NawGid and BarInkoopEenheid = @InkoopEenheid and
                 BarOmschrijvingOpBestelbrief = @BarOmschrijvingOpBestelbrief and (not exists(select 1 from tabBestelAdviesRegelSpecificatie where BarsOrrGid is not null and BarsBarGid = BarGid))
                 and BarBestemming = 0; //ACW 03-11-2010: Alleen als bestemming hetzelfde magazijn!
        else
          //call trace('BestelAdviesGenereren > 3!');
          select BarGid into @BarGid
          from   tabBestelAdviesRegel
          where  BarBakGid = @InsertedBakGid and BarArtGid = @ArtGid and BarArtPartijGid is null and BarMagGid = @MagGid and IsNull(BarNawGid, -1) = IsNull(@NawGid, -1) and BarInkoopEenheid = @InkoopEenheid and
                 BarOmschrijvingOpBestelbrief = @BarOmschrijvingOpBestelbrief
                 and BarBestemming = 0; //ACW 03-11-2010: Alleen als bestemming hetzelfde magazijn!
        end if;
      end if;
      //call trace('BestelAdviesGenereren > 4!');

      if @BarGid is null then
        insert into tabBestelAdviesRegel (BarBakGid, BarArtGid, BarMagGid, BarNawGid, BarInkoopEenheid, BarVoorraadEenhedenInInkoopEenheid, BarOmschrijvingOpBestelbrief, BarBestemming)
        select @InsertedBakGid, @ArtGid, @MagGid, @NawGid,
               @InkoopEenheid,
               if @InkoopEenheidBeschikbaar = 0 then 1 else @AldVoorraadEenhedenInInkoopEenheid endif,
               @BarOmschrijvingOpBestelbrief,
               0 /*Bestemming=magazijn*/;
        set @BarGid = @@Identity;
      end if;

      //RB 23-12-2009 niet naar beneden afronden indien er GEEN maximumvoorraad is
      //ACW 14-07-2010: Als aantal te bestellen kleiner dan 0, dan 0 in de besteladviesregel zetten
      if (@InVeelvoudBestelgrootte = 0) or (@AldGid is null) or (round(@MaximumVoorraad,3) = round(@MinimumVoorraad,3)) or (exists(select 1 from tabBestelAdviesRegelSpecificatie where BarsBarGid = @BarGid)) then
        insert into tabBestelAdviesRegelSpecificatie (BarsBarGid, BarsAantalInVoorraadEenheden, BarsSoort)
        select @BarGid, greater(0, @MaximumVoorraad - @ArtikelVoorraad), 0 /* MagazijnVoorraad */
      else //Voor die besteladviesregels die alleen maar uit 1 magazijnregel bestaan, eventueel het aantal naar beneden aanpassen, zodat we niet meer bestellen dan de maximum voorraad
        set @AantalInVoorraadEenheden = floor((@MaximumVoorraad - @ArtikelVoorraad) / (@AldBestelGrootte * @AldVoorraadEenhedenInInkoopEenheid)) * (@AldBestelGrootte * @AldVoorraadEenhedenInInkoopEenheid);
        if @AantalInVoorraadEenheden < (@AldMinimumAfname* @AldVoorraadEenhedenInInkoopEenheid) then
          set @AantalInVoorraadEenheden = 0;
        end if;
        insert into tabBestelAdviesRegelSpecificatie (BarsBarGid, BarsAantalInVoorraadEenheden, BarsSoort)
        select @BarGid, greater(0, @AantalInVoorraadEenheden), 0 /* MagazijnVoorraad */
      end if;
    end for;
  end;
  end if;

  call ProgressDelete();
  if not exists(select 1 from tabBestelAdviesRegel where BarBakGid = @InsertedBakGid) then
    //call Trace('BestelAdviesGenereren > Verwijder besteladvieskop');
    delete tabBestelAdviesKop where BakGid = @InsertedBakGid;
    call LockreleaseOnId(@ConnectionId, @LoginTime, 1, 'tabBestelAdviesKop', @LockString);
  else
    set @BakGid = @InsertedBakGid;
    call BestelAdviesMaakBerekendeRegels(@InsertedBakGid, null, @MatViewNr);
  end if;

  call PooledMatViewRelease(@MatViewNr);

  set @@ErrorTextProcedure = 'BestelAdviesGenereren';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure BestelAdviesHergroepeerRegels(
  in @BakGid       integer,
  in @MatVoorrViewExt nchar(20))
begin
  declare @BatGid              integer;
  declare @BestellingPerOrder  smallint;
  declare @ElkeOrderRegelApart smallint;
  declare @BarGid              integer;
  declare @MaxBarGid           integer;

  set @@ErrorTextProcedure = 'BestelAdviesHergroepeerRegels > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BakGid = ' + string(@BakGid));

  delete tabBestelAdviesTotalen where batBakGid = @BakGid;

  // Ook alle berekende regels verwijdeern
  delete tabBestelAdviesRegelSpecificatie
  where  BarsSoort = 9
     and BarsBarGid in (select BarGid from tabBestelAdviesRegel where BarBakGid = @BakGid);

  // Omdat alle nieuwe regels hierna worden toegevoegd... (Kan dus ook niet leeg zijn)
  select max(BarGid) into @MaxBarGid from tabBestelAdviesRegel;

  //Enkele gegevens uit de kop lezen
  select BakPerOrderAparteBestelling, BakPerOrderregelAparteBestelregel
  into   @BestellingPerOrder,         @ElkeOrderRegelApart
  from   tabBestelAdviesKop
  where  BakGid = @BakGid;

  //call trace('BestelAdviesHergroepeerRegels > @BestellingPerOrder = ' + string(@BestellingPerOrder) + ', @ElkeOrderRegelApart = ' + string(@ElkeOrderRegelApart));

  //Cursor door de besteladviesregels (Indien @BarGid gevuld, dan alleen voor die regel 'doorlopen')
  for @Cursor As Cursor_tabBestelAdviesSpecificatie Cursor For
    select BarGid                             @CurBarGid                             ,
           BarArtGid                          @CurBarArtGid                          ,
           BarMagGid                          @CurBarMagGid                          ,
           BarNawGid                          @CurBarNawGid                          ,
           BarInkoopEenheid                   @CurBarInkoopEenheid                   ,
           BarVoorraadEenhedenInInkoopEenheid @CurBarVoorraadEenhedenInInkoopEenheid ,
           BarOmschrijvingOpBestelbrief       @CurBarOmschrijvingOpBestelbrief       ,
           BarsGid                            @CurBarsGid                            ,
           BarsSoort                          @CurBarsSoort                          ,
           BarsAantalInVoorraadEenheden       @CurBarsAantalInVoorraadEenheden       ,
           BarsOrrGid                         @CurBarsOrrGid                         ,
           OrkGid                             @CurOrkGid                             ,
           OrrGid                             @CurOrrGid                             ,
           BarBestemming                      @BarBestemming                         ,
           BarNawGidAflevering                @BarNawGidAflevering                   ,
           BarAfleveradresNAW                 @BarAfleveradresNAW                    ,
           BarAdrGidAflevering                @BarAdrGidAflevering                   ,
           BarRelGid                          @BarRelGid
    from   tabBestelAdviesRegel
           inner join tabBestelAdviesRegelSpecificatie on BarsBarGid = BarGid
           left outer join tabOrderRegel on (OrrGid = BarsOrrGid)
           left outer join tabOrderKop   on (OrkGid = OrrOrkGid)
    where  barBakGid = @BakGid
       and barGid <= @MaxBarGid
    order by BarGid, BarsGid
  for read only do

    //@BestellingPerOrder  = 1 -> Zoek alleen regels met dezelfde OrkGid
    //@ElkeOrderRegelApart = 1 -> Zoek aleen regels met dezelfde OrrGid
    //Verder: -> Zoek alleen regels met dezelfde ArtGid, NawGid, MagGid, Inkoopeenheid, VEperIE, OmsOpBestelbrief
    set @BarGid = null;
    // Zoek bestaande regel op die NA maximum ligt (Dat zijn de nieuwe)
    select first barGid
    into   @BarGid
    from   tabBestelAdviesRegel
           inner join tabBestelAdviesRegelSpecificatie on BarsBarGid = BarGid
           left outer join tabOrderRegel on (OrrGid = BarsOrrGid)
           left outer join tabOrderKop   on (OrkGid = OrrOrkGid)
    where  barBakGid = @BakGid
           and (BarGid > @MaxBarGid)
           and (BarArtGid = @CurBarArtGid)
           and (BarNawGid = @CurBarNawGid)
           and (BarMagGid = @CurBarMagGid)
           and (BarOmschrijvingOpBestelbrief = @CurBarOmschrijvingOpBestelbrief)
           and (   (@BestellingPerOrder  = 0)                                             //GEEN aparte bestelling per order
                or (   (BarsSoort = 9 /*Magazijn*/ and @CurBarsSoort = 9 /*Magazijn*/)    // WEL aparte bestelling, dus ofwel het is magazijnregel, ofwel orkgids komen overeen
                    or (BarsSoort = 1 /*verkoop*/ and @CurBarsSoort = 1 /*verkoop*/ and isnull(OrkGid, @CurOrkGid-1, 0) = isnull(@CurOrkGid, -1))
                   )
               )
           and (   (@ElkeOrderRegelApart = 0)
                or (BarsSoort = 1  /*Verkoop*/ and isnull(OrrGid, @CurOrrGid-1, 0) = isnull(@CurOrrGid, -1) and BarsSoort = @CurBarsSoort)
                or (BarsSoort <> 1 and BarsSoort = @CurBarsSoort) // GEEN verkoop, dus moet er al een magazijnregel zijn
               )
           and (//ACW 02-09-2010: Zowiezo alleen bij elkaar als bestemmingsgegevens overeen komen
                    (BarBestemming = @BarBestemming)
                and (   (@BarBestemming = 0) // Magazijn, dan doet de rest er niet toe, anders moet het overeen komen
                     or (    (BarNawGidAflevering = @BarNawGidAflevering)
                         and (BarAfleveradresNAW = @BarAfleveradresNAW)
                         and (   (@BarAfleveradresNAW <> 2) // Geen Verzendadres, dan doet de rest er niet toe, anders moet het adresgid overeen komen
                              or (BarAdrGidAflevering = @BarAdrGidAflevering)
                             )
                         and (BarRelGid = @BarRelGid)
                        )
                     )
               );

    if @BarGid is null then
      // Eerst een nieuwe regel aanmaken
      insert into tabBestelAdviesRegel(BarBakGid,     BarArtGid,     BarNawGid,     BarMagGid,     BarInkoopEenheid,     BarVoorraadEenhedenInInkoopEenheid,     BarOmschrijvingOpBestelbrief,
                                       BarBestemming,   BarNawGidAflevering,  BarAfleveradresNAW,  BarAdrGidAflevering,  BarRelGid)
                                values(@BakGid,   @CurBarArtGid, @CurBarNawGid, @CurBarMagGid, @CurBarInkoopEenheid, @CurBarVoorraadEenhedenInInkoopEenheid, @CurBarOmschrijvingOpBestelbrief,
                                       @BarBestemming, @BarNawGidAflevering, @BarAfleveradresNAW, @BarAdrGidAflevering, @BarRelGid);
      set @BarGid = @@Identity;
    end if;
    // En de specificatie updaten
    update tabBestelAdviesRegelSpecificatie
    set    barsBarGid = @barGid
    where  barsGid = @CurBarsGid;

  end for; //Cursor_tabBestelAdviesRegel

  // Lege regels verwijderen
  delete tabBestelAdviesRegel
  where  barGid not in (Select BarsBarGid from tabBestelAdviesRegelSpecificatie)
     and BarBakGid = @BakGid;

  // Als laatste de gegevens weer updaten
  call BestelAdviesMaakBerekendeRegels(@BakGid, null, @MatVoorrViewExt);
  call BestelAdviesMaakTotalenPerBestelling(@BakGid, null, null);

  set @@ErrorTextProcedure = 'BestelAdviesHergroepeerRegels';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure BestelAdviesKopGenereren(in @Omschrijving nchar(40), out @Resultaat integer, out @BakGid integer, out @lockString nchar(100))
begin
  declare @Teller integer;

  set @@ErrorTextProcedure = 'BestelAdviesKopGenereren > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Omschrijving = '+@Omschrijving);

  set @Resultaat = 1;
  set @BakGid = null;
  set @Teller = 1;
  while @Teller <= 999 loop
    if not exists(select 1 from tabBestelAdviesKop where BakNummer = @Teller) then
      insert into tabBestelAdviesKop(BakNummer, BakOmschrijving, BakBestelDatum, BakIsOntvangstdatumVullenObvAfleverdagen, BakOntvangstDatum, BakIsInVeelvoudBestelgrootte,
                                     BakRekeningHoudenMetBestelling, BakIsRekeningHoudenMetLevertijd, BakDefaultInkoper, BakIsMagazijnSamengevoegd, BakMagGidSamengevoegd, BakOrderSelect,
                                     BakOrderVan, BakOrderTot, BakPerOrderAparteBestelling, BakPerOrderregelAparteBestelregel, BakMagazijnVoorraadBestellen, BakDirecteInkoopOrdersBestellen, BakRekeninghoudenMetSelectieBlok)
      select  @Teller,
              @Omschrijving,
              case VgbDefBestelDatum
                when 0 then Date(now())
                when 1 then Date(@@VerwerkingsDatum)
                else null
              end,
              VgbAutAfleverDatumAutoVullen,
              case VgbDefAfleverDatumKop
                when 0 then Date(now())
                when 1 then Date(@@VerwerkingsDatum)
                else null
              end,
              VgbVeelvanBestelgrootte,
              VgbRekeningNietverwBestellingen,
              VgbAutRekeningHoudenLevertijdArt,
              if VgbDefInkoper = 0 then 3 else VgbDefInkoper endif,
              0,
              null,
              0,
              '',
              '',
              VgbPerOrderAparteBestelling,
              VgbPerOrderregelAparteBestelregel,
              0, 0, 0
              from tabVasteGegevensBestellingen;
      set @BakGid = @@Identity;
      set @LockString = 'BakGid = '+string(@BakGid);
      call LockSetOnId(@@spid, @@LoginTime, 1, 'tabBestelAdviesKop', @LockString, null);
      set @Resultaat = 0;
      set @Teller = 999;
    end if;
    set @Teller = @Teller + 1;
  end loop;

  set @@ErrorTextProcedure = 'BestelAdviesKopGenereren';
  //call TraceEind(@@ErrorTextProcedure);
end;


//-------  Maak 5 records aan in tabAanmaning om de instellingen op te slaan
create or replace procedure BestelAdviesMaakBerekendeRegels(in @bakGid integer, in @BarGid integer, in @MatVoorrViewExt nchar(20))
begin
  // vanuit kop tbv. berekeningen
  declare @RekeningHoudenMetbestaandeBestelRegels smallint;
  declare @TermijnVoorraadPositie                 integer;
  declare @RekeningHoudenLevertijden              smallint;
  declare @DatumTeBestellen                       DateTime;
  declare @VoorraadPositieOpDatumGebruiken        smallint;
  declare @InVeelvoudBestelgrootte                smallint;
  declare @MagSelectieGebruiken                   smallint;
  declare @MagSelectie                            smallint;
  declare @MagVan                                 nchar(40);
  declare @MagTot                                 nchar(40);
  declare @AldGid                                 integer;
  // tbv. bepaling datum
  declare @Peildatum                              DateTime;   // = Besteldatum OF 'vandaag'
  // tbv. bepaling voorraad en eenheden
  declare @VEperIE                                numeric(15,3);
  declare @MinAfnameVE                            numeric(15,3);
  declare @BestelgrootteVE                        numeric(15,3);
  declare @MinVoorraad                            numeric(15,3);
  declare @MaxVoorraad                            numeric(15,3);
  declare @ArtVoorraad                            numeric(15,3);
  declare @DatumVoorraadPositie                   DateTime;
  //tbv. berekening extra regel
  declare @TotaalAantalInRegelsVE                 numeric(15,3);
  declare @TotaalAantalInMagRegelsVE              numeric(15,3);
  declare @TotaalAantalInAdviesVE                 numeric(15,3);
  declare @TotaalAantalInOverigeRegelsVE          numeric(15,3);
  declare @TotaalAantalOpVeelvoudenVE             numeric(15,3);
  declare @CurBarsGidAanvulling                   integer;
  declare @AantalInBerekendeRegelVE               numeric(15,3);
  declare @NieuweMagVoorraadVE                    numeric(15,3);

  declare @ProgressCreate                         integer;
  declare @AanvullenTekst                         long nvarchar;

  set @@ErrorTextProcedure = 'BestelAdviesMaakBerekendeRegels(@bakGid='+string(@bakGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @AanvullenTekst = _U('Aanvullen/controleren besteladvies');

  // Gegevens van de kop lezen
  //call trace('Stap 1 -> kopgegevens lezen');
  select
    BakRekeningHoudenMetBestelling,          BakUitgaanVanVoorraadPositieOverDagen, BakIsRekeningHoudenMetLevertijd,
    BakBestelDatum + BakBestelTijd,          BakIsUitgaanVanVoorraadPositie,        BakIsInVeelvoudBestelgrootte,
    BakIsMagazijnSamengevoegd,
    BakMagSelect,                            BakMagVan,                             BakMagTot
  into
    @RekeningHoudenMetbestaandeBestelRegels, @TermijnVoorraadPositie,               @RekeningHoudenLevertijden,
    @DatumTeBestellen,                       @VoorraadPositieOpDatumGebruiken,      @InVeelvoudBestelgrootte,
    @MagSelectieGebruiken,
    @MagSelectie,                            @MagVan,                               @MagTot
  from tabBestelAdviesKop
  where bakGid = @bakGid;

  set @Peildatum = IsNull (@DatumTeBestellen, Date(Now(*)));

  //call trace('Stap 2 -> regelcursor');
  //*** Cursor om per regel te verwerken
  set @ProgressCreate = 0;
  call ProgressCreate(1, 2, @AanvullenTekst);

  for @Cursor AS CURSOR_BestelAdviesRegel CURSOR FOR
    select barGid              @curBarGid,
           ArtAantDecAantallen @CurArtAantDecAantallen,
           BarNawGid           @CurBarNawGid,
           BarArtGid           @CurBarArtGid,
           BarMagGid           @CurBarMagGid,
           BarInkoopEenheid    @CurBarInkoopEenheid,
           BarVoorraadEenhedenInInkoopEenheid @CurVEperIE,
           rank() OVER AantalWindow as @AantalRecords

    from   tabBestelAdviesRegel
           inner join tabArtikel on (ArtGid = BarArtGid)
    where  barBakGid = @BakGid
           and isnull(@BarGid, BarGid) = BarGid
           and BarVoorraadEenhedenInInkoopEenheid <> 0 //ACW 09-06-2010: Aantal kan nu 0 zijn -> niks doen met berekende regels!
    window AantalWindow as (order by barGid desc)  //De Orderby van dit statement en van de query niet veranderen. Aantal bij het eerste record, geeft het aantal records van deze select terug
    order by barGid
  for read only
  do
    if @ProgressCreate = 0 then
      call ProgressCreate(1, @AantalRecords, @AanvullenTekst);
    end if;
    set @ProgressCreate = @ProgressCreate + 1;
    //Niet voor elke regel, maar na enkele regels pas de progress updaten
    if mod(@ProgressCreate, 4) = 0 then
      call ProgressAdd(4);
     end if;

    //*** Bepaal inkoopgegevens
    //call trace('Stap 3 -> inkoopgegevens bepalen');
    set @VEperIE         = null;
    set @MinAfnameVE     = null;
    set @BestelgrootteVE = null;
    select
      AldGid,
      AldVoorraadEenhedenInInkoopEenheid,
      if (@InVeelvoudBestelgrootte = 0) or AldGid is null then 0                                   else AldMinimumAfname endif * @CurVEperIE,  // Geen minimum afname, dus minimum is 0
      if (@InVeelvoudBestelgrootte = 0) or AldGid is null then 1/power(10,@CurArtAantDecAantallen) else AldBestelGrootte endif * @CurVEperIE   // NIET in veelvouden, dan gewoon [1] als bestelgrootte en min.afname gebruiken
    into @AldGid,
         @VEperIE,
         @MinAfnameVE,
         @BestelgrootteVE
    from tabArtikelLeverancier
         inner join tabArtikelLeverancierDetail on (aldArtLevGid = ArtLevGid)
    where  ArtLevNawGid = @CurBarNawGid
       and ArtLevArtGid = @CurBarArtGid
       and AldInkoopEenheid = @CurBarInkoopEenheid;

    if isnull(@VEperIE,         0) = 0 then set @VEperIE         = 1           end if;
    if isnull(@BestelgrootteVE, 0) = 0 then set @BestelgrootteVE = @CurVEperIE end if;
    set @MinAfnameVE = isnull(@MinAfnameVE, 0);


    // *** Bepaal wat in de specificatieregels zit
    //call trace('Stap 6 -> Bepaal spec.regel');
    select sum(if BarsSoort <> 9 /*berekend*/ then BarsAantalInVoorraadEenheden else 0 endif),
           sum(if BarsSoort =  0 /*magazijn*/ then BarsAantalInVoorraadEenheden else 0 endif),
           max(if BarsSoort = 9 /*berekend*/ then BarsGid endif)
    into   @TotaalAantalInRegelsVE,
           @TotaalAantalInMagRegelsVE,
           @CurBarsGidAanvulling
    from   tabBestelAdviesRegelSpecificatie
    where  BarsBarGid = @CurBarGid;

    if @TotaalAantalInRegelsVE = 0 then
      set @AantalInBerekendeRegelVE = 0;
    else

      //*** Magazijnvoorraad (op bepaalde datum) bepalen
      //call trace('Stap 4 -> @curBarGid='+string(@curBarGid)+'; magazijngegevens bepalen');

      execute immediate
      'select
          Sum(calcMinimumVoorraad),
          Sum(calcMaximumVoorraad),
          (
            Sum (calcEconomischeVoorraad - calcInBestellingVoorEconomischeVoorraad + calcInBestellingVerwerkt +
              (
                if @RekeningHoudenMetbestaandeBestelRegels = 0 then
                  calcInBestellingConcept + calcInBestellingGoedgek
                else
                  if @RekeningHoudenMetbestaandeBestelRegels = 1 then
                    calcInBestellingGoedgek
                  else
                    0
                  endif
                endif
              )
            )
          ) ArtikelVoorraad,
          (DateAdd (day, + @TermijnVoorraadPositie + (if @RekeningHoudenLevertijden = 1 then IsNull (AldLeverTijd, 0) else 0 endif), @Peildatum)) DatumVoorraadPositie
        into
          @MinVoorraad,
          @MaxVoorraad,
          @ArtVoorraad,
          @DatumVoorraadPositie
        from
          vwVoorraadAantallen' || @MatVoorrViewExt || '
          inner join tabMagazijn on (MagGid = calcMagGid)
          left outer join tabArtikelLeverancierDetail on AldGid = @AldGid
        where
          // Voorloopscherm (door gebruiker opgegeven) restricties
         calcArtGid = @CurBarArtGid
         and
         ((@VoorraadPositieOpDatumGebruiken = 0) or (calcDatum is null) or (calcDatum <= DatumVoorraadPositie))
         and
            (   (    (@MagSelectieGebruiken =  0)   /*Geen selectie gebruiken, dan magazijn van de regel*/
                 and (MagGid = @CurBarMagGid)
                )
             or (    (@MagSelectieGebruiken <> 0)   /*Wel selectie gebruiken, dus de range van de kop overnemen*/
                 and (   (@MagSelectie = 0 /*Code*/     and right(''000''+string(MagCode),3) between @MagVan and @MagTot)
                      or (@MagSelectie = 1 /*ZoekCode*/ and MagZoekCode                      between @MagVan and @MagTot)
                      or (@MagSelectie = 2 /*Oms*/      and MagOms                           between @MagVan and @MagTot)
                 )
                )
            )
        group by
          DatumVoorraadPositie
       ';

      set @TotaalAantalInAdviesVE        = @TotaalAantalInRegelsVE;
      set @TotaalAantalInOverigeRegelsVE = @TotaalAantalInAdviesVE - @TotaalAantalInMagRegelsVE;
      if @TotaalAantalInAdviesVE < @MinAfnameVE then
        set @TotaalAantalInAdviesVE = @MinAfnameVE;  // We zullen toch minstens de min.afname moeten hebben!
      end if;

      // Naar boven afronden op bestelgrootte
      set @TotaalAantalOpVeelvoudenVE = Ceiling(@TotaalAantalInAdviesVE / @BestelGrootteVE) * @BestelGrootteVE;

      // Default gaan we dit aantal op de berekende regel zetten
      set @AantalInBerekendeRegelVE = @TotaalAantalOpVeelvoudenVE - @TotaalAantalInRegelsVE;
      if @MinVoorraad <> @MaxVoorraad then
        // Er is een maximum voorraad! Dus niet erboven gaan zitten
        set @NieuweMagVoorraadVE = @ArtVoorraad + @TotaalAantalOpVeelvoudenVE - @TotaalAantalInOverigeRegelsVE;
        if @NieuweMagVoorraadVE > @MaxVoorraad then
          // OEPS! Magazijnvoorraad zou te groot worden; wellicht de berekende regel aanpassen
          if @TotaalAantalInMagRegelsVE > 0 then
            // Er is een magazijnregel, dus nu mag de berekende regel ietwat negatief zijn
            if (@TotaalAantalOpVeelvoudenVE - @BestelGrootteVE) - @TotaalAantalInRegelsVE + @TotaalAantalInMagRegelsVE >= 0 then
              // Dan maar 1 bestelgrootte minder in de berekende regel zetten, want ook dan kan het nog
              set @AantalInBerekendeRegelVE = (@TotaalAantalOpVeelvoudenVE - @BestelGrootteVE) - @TotaalAantalInRegelsVE;
            end if;
          end if;
        end if;
        //ACW 23-09-2009 - besloten om niet negatief toe te staan, dus dan alsnog verhogen
        if @AantalInBerekendeRegelVE < 0 then
          // Zo vaak de bestelgrootte erbijtellen dat het weer positief wordt
          set @AantalInBerekendeRegelVE = @AantalInBerekendeRegelVE - floor(@AantalInBerekendeRegelVE / @BestelGrootteVE) * @BestelGrootteVE;
        end if;
      end if;

      // Minstens de minimum afname, dus eventueel toch maar weer wat erbij
      if @TotaalAantalInRegelsVE + @AantalInBerekendeRegelVE < @MinAfnameVE then
        set @AantalInBerekendeRegelVE = @MinAfnameVE - @TotaalAantalInRegelsVE;
      end if;
    end if;

    //*** Als laatste de berekende regel aanmaken, updaten of verwijderen
    if (@AantalInBerekendeRegelVE <> 0) and ((@TotaalAantalInRegelsVE + @TotaalAantalInMagRegelsVE) <> 0) then  //Als het totaal van magazijn en orderregels gelijk aan 0 is, dan ook geen berekende regel aanmaken
      // Een nieuwe regel aanmaken/updaten met het restant als aantal voorraadeenheden!
      if @CurBarsGidAanvulling is not null then
        //call trace('Stap 7 -> Spec.regel updaten');
        update tabBestelAdviesRegelSpecificatie
        set    BarsAantalInVoorraadEenheden = @AantalInBerekendeRegelVE
        where BarsGid = @CurBarsGidAanvulling;
      else
        //call trace('Stap 7 -> Spec.regel toevoegen');
        insert into tabBestelAdviesRegelSpecificatie(BarsBarGid, BarsSoort,      BarsAantalInVoorraadEenheden)
                                              values(@CurBarGid, 9 /*berekend*/, @AantalInBerekendeRegelVE);
      end if;
    else
      // Geen restant, dus als de berekende regel bestaat, verwijderen
      //call trace('Stap 7 -> Spec.regel verwijderen');
      //ACW 14-07-2010: Als we een BarsGid hebben, dan die verwijderen
      if @CurBarsGidAanvulling is not null then
        delete tabBestelAdviesRegelSpecificatie where BarsGid = @CurBarsGidAanvulling;
      end if;
    end if;

  end for; //CURSOR_BestelAdviesRegel
  call ProgressDelete();



  //call TraceEind('BestelAdviesMaakBerekendeRegels');

end;


create or replace procedure BestelAdviesMaakTotalenPerBestelling(
  in @BakGid       integer,
  in @BarGid       integer,   // Indien leeg, dan gehele totalen bepalen
  in @BarToevoegen smallint)  // Indien @BarGid gevuld, dan -> 1 = toevoegen aan totalen; anders verwijderen uit totalen
begin
  declare @BatGid             integer;
  declare @BatOntvangstDatum  Date;
  declare @BestellingPerOrder smallint;
  declare @BakIsOntvangstdatumVullenObvAfleverdagen smallint;
  declare @BakBestelDatum                           Date;
  declare @BakBestelTijd                            Time;
  declare @BakOntvangstDatum                        Date;
  // tbv. berekening ontvangstdatum
  declare @Ontvangstdatum                           Date;
  declare @BestelDatum                              DateTime;
  declare @HeeftBestelTijd                          smallint;
  declare @KoppelingIsAlOk                          smallint;

  set @@ErrorTextProcedure = 'BestelAdviesMaakTotalenPerBestelling > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BakGid = ' + string(@BakGid) + ' , @BarGid = ' + string(@BarGid) + ', @BarToevoegen = ' + string(@BarToevoegen));

  //Enkele gegevens uit de kop lezen
  select BakPerOrderAparteBestelling, BakIsOntvangstdatumVullenObvAfleverdagen,  BakBestelDatum,  BakBestelTijd,  BakOntvangstDatum
  into   @BestellingPerOrder,         @BakIsOntvangstdatumVullenObvAfleverdagen, @BakBestelDatum, @BakBestelTijd, @BakOntvangstDatum
  from   tabBestelAdviesKop
  where  BakGid = @BakGid;

  //Cursor door de besteladviesregels (Indien @BarGid gevuld, dan alleen voor die regel 'doorlopen')
  for @Cursor As Cursor_tabBestelAdviesRegels Cursor For
    select BarGid                   @CurBarGid,
           BarBatGid                @CurBarBatGid,
           BarNawGid                @CurNawGid,
           BarMagGid                @CurMagGid,
           GroepOpOrderGid          @CurGroepOpOrderGid,
           NawFilValNummer          @CurValNummerBestelling,
           AantalVE                 @CurAantalVE,

           //*** Regeltotaal berekenen met (heel) veel tussenvariabelen ***//

           if BarVoorraadEenhedenInInkoopEenheid = 0 then 0 else AantalVE / BarVoorraadEenhedenInInkoopEenheid endif AantalInkoopEenheden,

           (if InkEenhHeeftEigenInkoopprijs <> 0 then IsNull (AldInkoopPrijsPer, 1) else 1 endif) InkEenhPrijsIsPer,  /* 0=per inkoopeenheid, 1=per ... voorraadeenheden */

           IsNull(AldHeeftEigenInkoopprijs, 0) InkEenhHeeftEigenInkoopprijs,

          (if InkEenhHeeftEigenInkoopprijs <> 0 then
              if (NawFilValNummer = AldValNummer) then
                round(AldInkoopPrijs, ArtAantDecPrijzen)
              else
                ValutaOmrekenen(AldValNummer, AldInkoopPrijs, NawFilValNummer, @@BjGid, @@PerNr, ArtAantDecPrijzen)
              endif
           else
//!@# Te kort door de bocht ivm. aparte partijprijzen!!
              if (NawFilValNummer = @@BasisValutaNummer) then
                round(ArtKostprijsEx, ArtAantDecPrijzen)
              else
                ValutaOmrekenen(@@BasisValutaNummer, ArtKostprijsEx, NawFilValNummer, @@BjGid, @@PerNr, ArtAantDecPrijzen)
              endif
           endif
          ) InkEenhBrutoInkoopPrijs,
          (if InkEenhHeeftEigenInkoopprijs <> 0 then AldKortingSoort else 1    endif) InkEenhKortingSoort, /* 0=bedrag 1=percentage 2=staffel */
          (if InkEenhHeeftEigenInkoopprijs <> 0 then AldNstfKopGid   else null endif) InkEenhNstfKopGid,
          IsNull(AldBerekeningKostprijs, 0) InkEenhBerekeningKostprijs,

          //staffelgegevens
          (if NstfKopSoort = 0 /*bedrag*/     then (SELECT first NstfRglBedrag     FROM tabNawStaffelRegel WHERE (NstfRglNstfKopGid = NstfKopGid) and (NstfRglVanafAantal <= AantalInkoopEenheden) ORDER BY NstfRglVanafAantal DESC) else 0 endif) NstfRglBedrag,
          (if NstfKopSoort = 1 /*percentage*/ then (SELECT first NstfRglPercentage FROM tabNawStaffelRegel WHERE (NstfRglNstfKopGid = NstfKopGid) and (NstfRglVanafAantal <= AantalInkoopEenheden) ORDER BY NstfRglVanafAantal DESC) else 0 endif) NstfRglPercentage,

          //wat is het kortingspercentage per inkoopeenheid
          (if InkEenhHeeftEigenInkoopprijs = 0 then
            0.00
           else
            (case InkEenhKortingSoort
              when 0 then //kortingsbedrag
                Null
              when 1 then //kortingspercentage
                AldKortingPercentage
              when 2 then //kortingstaffel
                (if NstfKopSoort = 0 then   //bedrag
                   Null
                 else
                   NstfRglPercentage
                 endif)
             end)
           endif
          ) InkEenhKortingPercentage,

         //wat is het kortingsbedrag per inkoopeenheid, vanuit staffel wel even omrekenen naar 'Inkoopprijs is per...' en valuta van inkoopeenheid
         (if InkEenhHeeftEigenInkoopprijs = 0 then
           null
          else
           (case InkEenhKortingSoort
             when 0 then //kortingsbedrag
               if (NawFilValNummer = AldValNummer) then
                 round(AldKortingBedrag, ArtAantDecPrijzen)
               else
                 ValutaOmrekenen(AldValNummer, AldKortingBedrag, NawFilValNummer, @@BjGid, @@PerNr, ArtAantDecPrijzen)
               endif
             when 1 then //kortingspercentage
               Null
             when 2 then //kortingstaffel
               (if NstfKopSoort = 0 /*Bedrag*/ and BarVoorraadEenhedenInInkoopEenheid <> 0 then
                 if NstfKopValNummer = NawFilValNummer then
                   if InkEenhPrijsIsPer = 1 then   // per ...voorraadeenheden
                     round(((NstfRglBedrag / BarVoorraadEenhedenInInkoopEenheid) * ArtPrijsPer), ArtAantDecPrijzen)
                   else
                     round(NstfRglBedrag, ArtAantDecPrijzen)
                   endif
                 else
                   if InkEenhPrijsIsPer = 1 then   // per ...voorraadeenheden
                     ValutaOmrekenen(NstfKopValNummer, (NstfRglBedrag / BarVoorraadEenhedenInInkoopEenheid) * ArtPrijsPer, NawFilValNummer, @@BjGid, @@PerNr, ArtAantDecPrijzen)
                   else
                     ValutaOmrekenen(NstfKopValNummer, NstfRglBedrag, NawFilValNummer, @@BjGid, @@PerNr, ArtAantDecPrijzen)
                   endif
                 endif
                else
                  Null
                endif)
            end)
          endif
         ) InkEenhKortingBedrag,

        //netto inkoopprijs ( = bruto minus de korting )
        (if InkEenhHeeftEigenInkoopprijs = 0 then
            InkEenhBrutoInkoopPrijs
         else
           (case InkEenhKortingSoort
              when 0 then //kortingsbedrag
                Round(InkEenhBrutoInkoopPrijs - InkEenhKortingBedrag, 2)
              when 1 then //kortingspercentage
                round(InkEenhBrutoInkoopPrijs * round((100 - InkEenhKortingPercentage)/100, 4), ArtAantDecPrijzen)
              when 2 then //kortingstaffel
                (if NstfKopSoort = 0 then   //bedrag
                    Round(InkEenhBrutoInkoopPrijs - InkEenhKortingBedrag, 2)
                 else
                    round(InkEenhBrutoInkoopPrijs * round((100 - InkEenhKortingPercentage)/100, 4), ArtAantDecPrijzen)
                 endif)
            end)
         endif
        ) InkEenhNettoInkoopPrijs,

        //regeltotaal
        (if InkEenhPrijsIsPer = 0 then    //prijs is per inkoopeenheid
                                     round(AantalInkoopEenheden * InkEenhNettoInkoopPrijs, 2)
                                   else
                                     if BarVoorraadEenhedenInInkoopEenheid = 0 then 0 else round(AantalInkoopEenheden * (InkEenhNettoInkoopPrijs * BarVoorraadEenhedenInInkoopEenheid / ArtPrijsPer), 2) endif
                                   endif) @CurRegelTotaalInValVanBestelling,
        //Regeltotaal dat al in de totalen was opgenomen (gebufferd)
        BarRegelTotaalInTotalen @CurBarRegelTotaalInTotalen,

    //DirLev velden in de totalen
    BarBestemming       @Bestemming,
    BarNawGidAflevering @NawGidAflevering,
    BarAfleveradresNAW  @AfleveradresNAW,
    BarAdrGidAflevering @AdrGidAflevering,
    BarRelGid           @RelGidAflevering,

    if BarArtPartijGid is null then
      0 // Geen partij, dus ook niet geblokkeerd
    else
      (select ArtPartijIsGeblokkeerdVoorInkoop + (if @Bestemming = 0 then 0 else ArtPartijIsGeblokkeerdVoorVerkoop endif) from tabArtikelPartij where ArtPartijGid = BarArtPartijGid)
    endif @PartijIsGeblokkeerd,
    // Geblokkeerd voor directe levering = blokkade van artikel, leverancier en IE bij elkaar optellen
    /*Artikel:    */ if ArtBestellenVoorDirecteLevering = 0 /*BestellenVoorDirLev=Nee*/ then 1 else 0 endif +
    /*Leverancier:*/ if isnull(LevGegDirLevGeschikt, 0) = 0 /*Lev. is NIET geschikt*/   then 1 else 0 endif +
    /*Inkoopeenh.:*/ if isnull(AldDirecteLevering, 0)   = 0 /*Niet toegestaan*/         then 1 else 0 endif @ArtLevIEgeblokkeerdVoorDirecteInkoop,
    IsNull((select first 1 from tabBestelAdviesRegelSpecificatie where BarsBarGid = BarGid and BarsSoort = 9 /*Aanvulling*/), 0) @HeeftAanvullingsRegel,

    //*** Hieronder staan alle controles op een regel. Als controles worden toegevoegd in het programma, dan hier ook opnemen!! ***
    if    (ArtIsGeblokkeerdInkoop = 0)                        // Geblokkeerde artikelen niet meenemen
      and (BarNawGid is not null)                             // Leverancier is gevuld
      and (isnull(LevGegBestellenGeblokkeerd, 0) = 0)         // Geblokkeerde leveranciers niet meenemen
      and (AantalVerkeerdeSpecRegels = 0)                     // Alleen als er geen foutieve spec.regels zijn (bijv. verk.order verwijderd)
      and (AantalInkoopEenheden <> 0)                         // Alleen als er een aantal moet worden besteld
      and (AantalInkoopEenheden < 9999999999.99)              // Alleen als het aantal voorraadeenheden niet te hoog is
      and (AantalVE < 9999999999.99)                          // Alleen als het aantal inkoopeenheden niet te hoog is
      and (@PartijIsGeblokkeerd = 0)                          // En als er een partij is, dan mag die NIET zijn geblokkeerd voor in- of verkoop
      and (BarVoorraadEenhedenInInkoopEenheid <> 0)           // ACW 09-06-2010: Kan tegenwoordig ook 0 zijn
      and (   (BarBestemming = 0) /*magazijn*/                // ACW 18-06-2010: Magazijn -> ok, is goed
           or (BarBestemming = 1  /*debiteur*/                // Debiteur -> verder onderzoeken op blokkades en fouten voor directe levering:
               and BarNawGidAflevering is not null            //   Debiteur moet zijn ingevuld
               and (   (BarAfleveradresNAW <> 2)              //   Afleveradres <> verzendadres
                    or (BarAdrGidAflevering is not null)      //   OF verzendadres is ingevuld
                   )
               and @ArtLevIEgeblokkeerdVoorDirecteInkoop = 0  //   Artikel, leverancier EN inkoopeenheid zijn niet geblokkeerd voor directe levering
               and @HeeftAanvullingsRegel = 0                 //   Geen aanvullingsregel gevonden
              )
          )
    then 1 else 0 endif @RegelIsCorrect

  from  tabBestelAdviesRegel
          inner join  (select barGid BarGidTotaal,
                              sum(BarsAantalInVoorraadEenheden) AantalVE,
                              if @BestellingPerOrder <> 0 then
                                case MIN(BarsSoort)
                                when 0 /*magazijn*/ then
                                  null
                                when 1 /*VerkoopOrder*/ then
                                  (select first OrkGid
                                   from   tabOrderKop
                                          inner join tabOrderRegel on (OrkGid = OrrOrkGid)
                                   where  OrrGid = MIN(BarsOrrGid)
                                  )
                                end
                              endif GroepOpOrderGid,
                              sum(if BarsSoort = 1 /*Verkooporder*/ and BarsOrrGid is null then 1 else 0 endif) AantalVerkeerdeSpecRegels

                       from   tabBestelAdviesRegel
                              inner join tabBestelAdviesRegelSpecificatie on (BarsBarGid = BarGid)
                       where  BarBakGid = @BakGid
                              and (@BarGid is null or BarGid = @BarGid)
                       group by barGid, BarMagGid
                      ) TotaalAantalPerAdviesRegel on (BarGid = BarGidTotaal)
          inner join tabArtikel on (ArtGid = barArtGid)
          left outer join tabArtikelLeverancier       on (ArtLevArtGid = barArtGid and ArtLevNawGid = barNawGid)
          left outer join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid and aldInkoopEenheid = barInkoopEenheid)
          left outer join tabNawStaffelKop            on (NstfKopGid=AldNstfKopGid)
          left outer join tabLeverancierGegevens      on (LevGegNawGid = BarNawGid)
          inner join tabNawFile on (NawFilNawGid = barNawGid and nawFilFonID='C')
    where (BarBakGid = @BakGid)                               // Alles van het besteladvies
      and (@BarGid is null or BarGid = @BarGid)               // Alles of, indien regel is meegegeven, alleen die regel
  for read only
  do
    set @KoppelingIsAlOk = 0; // Ga ervan uit dat de koppeling niet juist is, zodat er een nieuwe koppeling zal worden gemaakt
    if @RegelIsCorrect = 0 then
      //Eventuele bestaande koppeling van de regel ongedaan maken (De regel wordt straks uit de oude totaalregel gehaald)
      if @CurBarBatGid is not null then
        update tabBestelAdviesRegel set BarBatGid = null, BarRegelTotaalInTotalen = 0 where BarGid = @CurBarGid;
      end if;
    else
      // Regel is akkoord, dus in de totalen opnemen
      // Eerst bestaande adviestotaalregel opzoeken obv. naw, magazijn en (indien nodig) groepering
      set @BatGid = null;
      select first batGid,  batOntvangstDatum
      into   @BatGid, @BatOntvangstDatum
      from   tabBestelAdviesTotalen
      where  BatBakGid = @BakGid
         and BatNawGid = @CurNawGid
         and BatMagGid = @CurMagGid
         and (   (@BestellingPerOrder = 0)        // Bestellingen gewoon bij elkaar
              or (    (@BestellingPerOrder <> 0)  // Bestelling per order apart (Bestelling voor magazijn komt ook niet bij bestelling voor order!)
                  and (   (@CurGroepOpOrderGid is null and BatGroepOpOrderGid is null)
                       or (@CurGroepOpOrderGid = BatGroepOpOrderGid)
                      )
                 )
             )
         //Testen op velden voor Directe Levering
         and (BatBestemming = @Bestemming)
         and (   (@Bestemming = 0 /*Magazijn*/)
              or (    (@Bestemming = 1 /*Debiteur*/)
                  and (BatNawGidAflevering = @NawGidAflevering)
                  and (BatAfleveradresNAW  = @AfleveradresNAW)
                  and (   (@AfleveradresNAW <> 2 /*Verzendadres*/)
                       or (isnull(BatAdrGidAflevering, @AdrGidAflevering - 1, 0) = isnull(@AdrGidAflevering, BatAdrGidAflevering - 1, 1))  //Verzendadres, dus ook adres controleren
                      )
                  // Contactpersoon bij adres testen (Als de regel geen rel heeft, dan bij de eerste de beste totaalregel van dezelfde naw, mag, etc.
                  and (isnull(@RelGidAflevering, BatRelGid, 0) = isnull(BatRelGid, @RelGidAflevering - 1, 0))
                 )
             )
      order by batGid;
      if (@BarGid is null) or (isnull(@BarToevoegen, 1) = 1) then
        //*** Alle regels  OR 1 regel toevoegen aan totalen ***//

        // Ontvangstdatum opnieuw bepalen
        set @Ontvangstdatum = null;
        //RVL 22-12-2009 : #31914, Als er geen afleverdagen zijn, dan is de meegegeven otnvangstdatum, de datum die gebruikt wordt
        if (@BakIsOntvangstdatumVullenObvAfleverdagen = 1) and (exists(select first 1 from tabLeverancierAfleverDagen inner join tabLeverancierGegevens on LevGegGid = LadLevGegGid where LevGegNawGid = @CurNawGid)) then
          set @BestelDatum = @BakBestelDatum;
          if @BestelDatum is not null then
            if @BakBestelTijd is not null then
               set @BestelDatum = @BestelDatum + @BakBestelTijd;
               set @HeeftBestelTijd = 1;
            else
               set @HeeftBestelTijd = 0;
            end if;
            call BerekenAfleverDatum(@CurNawGid, 0, ISODayOfWeek(@BestelDatum), @Besteldatum, @HeeftBestelTijd, @Ontvangstdatum)
          end if;
        end if;
        if @Ontvangstdatum is null then
          set @Ontvangstdatum = @BakOntvangstDatum
        end if;

        if @BatGid is null then
          // Totaalregel bestaat nog niet, dus aanmaken
          insert into tabBestelAdviesTotalen(BatBakGid, BatNawGid,  BatMagGid,  BatValNummer,            BatGroepOpOrderGid,  BatAantalBestelRegels, BatOntvangstdatum, BatTotaalBedragInValuta,           BatBestemming, BatNawGidAflevering, BatAfleveradresNAW, BatAdrGidAflevering, BatRelGid)
                                      values(@BakGid,   @CurNawGid, @CurMagGid, @CurValNummerBestelling, @CurGroepOpOrderGid, 1,                     @OntvangstDatum,   @CurRegelTotaalInValVanBestelling, @Bestemming,   @NawGidAflevering,   @AfleveradresNAW,   @AdrGidAflevering,   @RelGidAflevering);
          set @BatGid = @@Identity;
        else
          // Totaalregel bestaat al, dus aanvullen ALS deze anders is dan die waar de regel al naar verwees (met zelfde aantal en ontvangstdatum)
          if @CurBarBatGid is null or (@CurBarBatGid <> @BatGid) or (@CurRegelTotaalInValVanBestelling <> @CurBarRegelTotaalInTotalen) or (isnull(datediff(day, @OntvangstDatum, @BatOntvangstDatum), 0) <> 0) then
            update tabBestelAdviesTotalen
            set    BatAantalBestelRegels   = BatAantalBestelRegels + 1,
                   BatOntvangstdatum       = @OntvangstDatum,
                   BatTotaalBedragInValuta = BatTotaalBedragInValuta + @CurRegelTotaalInValVanBestelling
            where BatGid = @BatGid;
          else
            // Doe net alsof de regel niet was gekoppeld (zodat de regel niet van de totalen af wordt gehaald; de nieuwe koppeling = oude koppeling)
            set @KoppelingIsAlOk = 1;
          end if;
        end if;

        // Nieuwe koppeling onthouden in de regel (De regel wordt straks uit de oude totaalregel gehaald)
        if @KoppelingIsAlOk = 0 then
          update tabBestelAdviesRegel set BarbatGid = @BatGid, BarRegelTotaalInTotalen = @CurRegelTotaalInValVanBestelling where BarGid = @CurBarGid;
        end if;

      else
        // Koppeling weghalen (De regel wordt straks uit de oude totaalregel gehaald)
        update tabBestelAdviesRegel set BarBatGid = null, BarRegelTotaalInTotalen = 0 where BarGid = @CurBarGid;
      end if;

    end if;

    //Oude totaalregel evt. opschonen (de regel eruit vissen)
    if (@KoppelingIsAlOk = 0) and (@CurBarBatGid is not null) then
      update tabBestelAdviesTotalen
      set    BatAantalBestelRegels = BatAantalBestelRegels - 1,
             BatTotaalBedragInValuta = BatTotaalBedragInValuta - @CurBarRegelTotaalInTotalen
      where BatGid = @CurBarBatGid;
    end if;

  end for; //Cursor_tabBestelAdviesRegels

  // Opschonen totaalregels: Alle totaalregels verwijderen die geen koppeling naar besteladviesregels meer hebben
  delete tabBestelAdviesTotalen
  where (BatBakGid = @BakGid)
    and (   (BatAantalBestelRegels <= 0)
         //or (BatGid not in (Select BarBatGid from tabBestelAdviesRegel where BarBakGid = @BakGid))
        );

  set @@ErrorTextProcedure = 'BestelAdviesMaakTotalenPerBestelling';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure BestelAdviesObvVerkoopOrder(in @OrkGid integer, out @Resultaat integer, out @BakGid integer)
begin
  //---------- Genereer een besteladvies obv een verkooporder (directe inkoop) ----------
  //@Resultaat 0 = Besteladvies is goed aangemaakt
  //           1 = Er is geen vrijnummer meer voor besteladvieskop

  declare @Teller                            integer;
  declare @BarGid                            integer;
  declare @InsertedBakGid                    integer;
  declare @BakPerOrderregelAparteBestelregel integer;
  declare @BstKopNummer                      numeric(10,0);
  declare @DefOmsRegels                      smallint;
  declare @TekstVerkoopOrder                 long nvarchar;

  set @@ErrorTextProcedure = 'BestelAdviesObvVerkoopOrder > ';
  //call TraceBegin(@@ErrorTextProcedure + 'OrkGid = ' + string(@OrkGid));

  set @BakGid = null;
  set @Resultaat = 1;
  set @Teller = 1;
  set @TekstVerkoopOrder = _A('Verkooporder %1!');

  select VgbPerOrderregelAparteBestelregel, VgbDefOmsRegels into @BakPerOrderregelAparteBestelregel, @DefOmsRegels from tabVasteGegevensBestellingen;

  while @Teller <= 999 loop
    if not exists(select 1 from tabBestelAdviesKop where BakNummer = @Teller) then
      insert into tabBestelAdviesKop (BakNummer, BakOmschrijving, BakBestelDatum, BakIsOntvangstdatumVullenObvAfleverdagen, BakOntvangstDatum, BakIsInVeelvoudBestelgrootte, BakRekeningHoudenMetBestelling,
                                      BakIsRekeningHoudenMetLevertijd, BakDefaultInkoper, BakIsMagazijnSamengevoegd, BakMagGidSamengevoegd, BakOrderSelect, BakOrderVan, BakOrderTot,
                                      BakPerOrderAparteBestelling, BakPerOrderregelAparteBestelregel, BakMagazijnVoorraadBestellen, BakDirecteInkoopOrdersBestellen, BakRekeninghoudenMetSelectieBlok)
      select @Teller, _P(@TekstVerkoopOrder, string(OrkNummer)),
            case VgbDefBestelDatum
              when 0 then Date(now())
              when 1 then Date(@@VerwerkingsDatum)
              else null
            end, VgbAutAfleverDatumAutoVullen,
            case VgbDefAfleverDatumKop
              when 0 then Date(now())
              when 1 then Date(@@VerwerkingsDatum)
              else null
            end, VgbVeelvanBestelgrootte, VgbRekeningNietverwBestellingen, VgbAutRekeningHoudenLevertijdArt, if VgbDefInkoper = 0 then 3 else VgbDefInkoper endif, 0, null, 0 /* Ordernummer */, OrkNummer, OrkNummer,
            VgbPerOrderAparteBestelling, VgbPerOrderregelAparteBestelregel, 0, 1, 0
      from   tabOrderKop, tabVasteGegevensBestellingen
      where  OrkGid = @OrkGid;
      set @InsertedBakGid = @@Identity;
      set @Resultaat = 0;
      set @Teller = 999;
    end if;
    set @Teller = @Teller + 1;
  end loop;

  if @Resultaat = 0 then
    for @Cursor As Cursor_OrderRegelsTeBestellen Cursor For
      select   OrrArtGid @ArtGid, if ArtIsPartijRegistreren <> 0 then OrrArtPartijGid endif @ArtPartijGid, OrrMagGid @MagGid, NawGid @NawGid, OrrGid @OrrGid, OrrAantalBackorderVrrdEenh @OrrAantalBackorderVrrdEenh,
               if AldGid is null then if OrrDirInkInkoopEenheid = '' then ArtOmsEenheid else OrrDirInkInkoopEenheid endif else AldInkoopEenheid endif @InkoopEenheid,
               if AldGid is null then 1 else AldVoorraadEenhedenInInkoopEenheid endif @VoorraadEenhedenInInkoopEenheid,
               if OrrOmsNaarBestelling = 0 then
                 IsNull((if isnull(AldOmsBijLeverancier, '')<> '' then AldOmsBijLeverancier endif),
                        if @DefOmsRegels =  0 /*TekstOpFactuur*/ and @ArtPartijGid is not null and ArtIsPartijAparteTekstOpFactuur <> 0 then (select ArtPartijTekstOpFactuur from tabArtikelPartijTeksten where (ArtPartijTekstArtPartijGid = @ArtPartijGid and ArtPartijTekstTaalGid = IsNull(NawTaalGid, (select DefaultTaalgid from tabvastegegevens)))) endif,
                        if @DefOmsRegels <> 2 /*Leeg*/           and @ArtPartijGid is not null and ArtIsPartijAparteTekstOpFactuur <> 0 then if ArtPartijOms <> '' then ArtPartijOms endif endif,
                        if @DefOmsRegels =  0 /*TekstOpFactuur*/ then (select ArtTekst from tabArtikelTeksten where (ArtTekstArtGid = OrrArtGid and ArtTekstDocSoort = 50 /*Factuur-batch*/ and ArtTaalGid = IsNull(NawTaalGid, (select DefaultTaalgid from tabvastegegevens)))) endif,
                        if @DefOmsRegels <> 2 /*Leeg*/           then ArtOms endif)
               else
                 OrrTekstOpFactuur
               endif @BarOmschrijvingOpBestelbrief,
               //Directe levering -> gegevens uit verkooporder
               if OrrDirecteLevering = 2 /*Volgens lev./IE*/ then
                 if    (isnull(LevGegDirLevGeschikt, 1) = 0 /*Leveranciersgegevens gevonden EN niet geschikt voor directe levering*/)
                    or (isnull(AldDirecteLevering, 1) = 0 /*IE gevonden EN niet geschikt*/) then
                   0 /*Bestemming = Magazijn*/
                 else
                   // Leverancier niet gevonden of toegestaan
                   if isnull(AldDirecteLevering, 0) = 2 /*Toegestaan, default via directe levering*/ then
                     1 /*Bestemming = debiteur*/
                   else
                    0 /*(default) IE niet gevonden of niet default*/
                   endif
                 endif
               else
                 OrrDirecteLevering
               endif @Bestemming,
               /*Gegevens voor aflevering aan klant*/
               if OrkVerzendAdres / 3 = 0 then OrkNawGid else OrkFactuurNawGid endif @DirLevAfleverNawGid, /*Orderdebiteur of Factuurdebiteur (indien in verzendadres zo aangegeven)*/
               mod(OrkVerzendAdres, 3) @DirLevAfleverVerzendadres,  /* Alleen 0, 1, 2 mogelijk; van factuurdeb. geldt ook 0, 1 of 2!*/
               OrkAdrGid       @DirLevAfleverAdrGid,
               (if OrkAdrGid is not null then (select AdrRelGid from tabAdres where AdrGid = OrkAdrGid) else null endif) @VerzAdrRelGid,
               (select OrdRelRelGid from tabOrderRelatieVoorDocument where OrdRelOrkGid = OrkGid and OrdRelDocSoort = 35 /*Pakbon directe levering*/) @DocRelGid,
               IsNull(@VerzAdrRelGid, @DocRelGid) @DirLevRelGid
      from     tabOrderKop
               inner join tabOrderRegel                         on (OrkGid     = OrrOrkGid)
               inner join tabArtikel                            on (ArtGid     = OrrArtGid)
               left outer join tabBestelAdviesRegelSpecificatie on (BarsOrrGid = OrrGid)
               left outer join tabBestelRegelDetail             on (BrdOrrGid  = OrrGid)
               left outer join tabMagazijnOntvangstenDetail     on (MagOntDetOrrGid = OrrGid)
               left outer join tabArtikelLeverancier            on (    (ArtLevArtGid = OrrArtGid)                                                         // MOET leverancier van artikel zijn
                                                                    and (   (OrrNawGidDirecteInkoop is     null and ArtLevIsDefault = 1)                   // Geen leverancier in orderregel opgegeven, dan de default lev.
                                                                         or (OrrNawGidDirecteInkoop is not null and ArtLevNawGid = OrrNawGidDirecteInkoop) // Wel leverancier in orderregel opgegeven, dan die gebruiken
                                                                        )
                                                                   )
               left outer join tabNaw                           on (NawGid       = isnull(OrrNawGidDirecteInkoop, ArtLevNawGid))
               left outer join tabLeverancierGegevens           on (LevGegNawGid = NawGid)
               left outer join tabArtikelLeverancierDetail      on (    (AldArtLevGid = ArtLevGid)
                                                                    and (   (OrrDirInkInkoopEenheid =  '' and AldIsDefaultInkoopEenheidBijLev = 1)
                                                                         or (OrrDirInkInkoopEenheid <> '' and AldInkoopEenheid = OrrDirInkInkoopEenheid)
                                                                        )
                                                                   )
               left outer join tabArtikelPartij                 on (ArtPartijGid = @ArtPartijGid)
      where    OrkGid = @OrkGid and OrkGoedgekeurd = 1 and OrrRegelsoort = 2 and OrrDirecteInkoop = 1 and OrrAantalBackorderVrrdEenh > 0
      and BarsOrrGid is null and BrdOrrGid is null and MagOntDetOrrGid is null
    for read only
    do
      // Bestemming = magazijn, dan alle bestemmingsvelden leeg maken
      if @Bestemming = 0 /*Magazijn*/ then
        set @DirLevAfleverNawGid      = null;
        set @DirLevAfleverVerzendadres= null;
        set @DirLevAfleverAdrGid      = null;
        set @DirLevRelGid             = null;
      end if;

      set @BarGid = null;
      if (@BakPerOrderregelAparteBestelregel = 0) then
        select BarGid into @BarGid from tabBestelAdviesRegel
        where BarBakGid = @InsertedBakGid and BarArtGid = @ArtGid and isnull(@ArtPartijGid, BarArtPartijGid-1, 0) = isnull(BarArtPartijGid, @ArtPartijGid - 1, 0 )
              and BarMagGid = @MagGid and IsNull(BarNawGid,0) = IsNull(@NawGid,0) and BarInkoopEenheid = @InkoopEenheid and BarOmschrijvingOpBestelbrief = @BarOmschrijvingOpBestelbrief
              and BarBestemming = @Bestemming
              and (   (@Bestemming = 0) /*Magazijn -> is al vergeleken*/
                   or (    (@Bestemming = 1)
                       and (BarNawGidAflevering = @DirLevAfleverNawGid)
                       and (BarAfleveradresNAW  = @DirLevAfleverVerzendadres)
                       and (@DirLevAfleverVerzendadres <> 3 /*Verzendadres*/ or isnull(BarAdrGidAflevering, 0) = isnull(@DirLevAfleverAdrGid, 0))
                       and (isnull(BarRelGid, 0) = isnull(@DirLevRelGid, 0) or @DirLevRelGid is null) // Geen relatie in verkooporderregel aangegeven, dan is het altijd goed!
                      )
                  );
      end if;
      if (@BarGid is null) then
        insert into tabBestelAdviesRegel (BarBakGid, BarArtGid, BarArtPartijGid, BarMagGid, BarNawGid, BarInkoopEenheid, BarVoorraadEenhedenInInkoopEenheid, BarOmschrijvingOpBestelbrief, BarBestemming, BarNawGidAflevering,  BarAfleveradresNAW,         BarAdrGidAflevering,  BarRelGid)
                                  select   @InsertedBakGid,   @ArtGid,   @ArtPartijGid,   @MagGid,   @NawGid,   @InkoopEenheid,   @VoorraadEenhedenInInkoopEenheid, @BarOmschrijvingOpBestelbrief,  @Bestemming, @DirLevAfleverNawGid, @DirLevAfleverVerzendadres, @DirLevAfleverAdrGid, @DirLevRelGid;
        set @BarGid = @@Identity;
      end if;
      insert into tabBestelAdviesRegelSpecificatie (BarsBarGid, BarsOrrGid, BarsAantalInVoorraadEenheden, BarsSoort)
      select   @BarGid, @OrrGid, @OrrAantalBackorderVrrdEenh, 1; /* Verkooporder */
    end for;

    if not exists(select 1 from tabBestelAdviesRegel where BarBakGid = @InsertedBakGid) then
      //call Trace('BestelAdviesObvVerkoopOrder > Verwijder besteladvieskop');
      delete tabBestelAdviesKop where BakGid = @InsertedBakGid;
    else
      set @BakGid = @InsertedBakGid;
      call BestelAdviesMaakBerekendeRegels(@InsertedBakGid, null, null)
    end if;
  end if;

  set @@ErrorTextProcedure = 'BestelAdviesObvVerkoopOrder';
  //call TraceEind(@@ErrorTextProcedure + ' > @Resultaat = '+string(@Resultaat) + ', @BakGid = ' + string(@BakGid));
end;


// De parameters @BatGid kan  optioneel worden meegegeven. Indien deze leeg zijn, dan wordt
// (voor zover dat kan) voor het hele besteladvies 1 of meerdere bestellingen aan gemaakt. Is @BatGid
// wel gevuld, dan wordt er 1 bestelling aangemaakt voor die besteladviesregels die verwijzen naar het betreffende @BatGid.

create or replace procedure BestellingenObvBesteladvies(in @BakGid integer, in @BatGid integer, in @BakStartNummerBestelling numeric(10,0), out @BstKopGid integer, out @AantalBestellingen integer)
begin
  declare @BstRglGid                integer;
  declare @VorigeNawGid             integer;
  declare @VorigeMagGid             integer;
  declare @VorigeOrkNummer          numeric(10,0);
  declare @BstKopNummer             numeric(10,0);
  declare @BestelDatum              datetime;
  declare @Ontvangstdatum           datetime;
  declare @HeeftBestelTijd          smallint;
  declare @VgbDefAfleverDatumRegels smallint;
  declare @AantalBesteld            numeric(15,3);
  declare @KortingSoort             smallint;
  declare @KortingsBedrag           numeric(15,3);
  declare @KortingsPercentage       numeric(15,2);
  declare @VgbDefStatus             smallint;
  declare @VorigeBatBestemming       integer;
  declare @VorigeBatNawGidAflevering integer;
  declare @VorigeBatAfleveradresNAW  integer;
  declare @VorigeBatAdrGidAflevering integer;
  declare @VorigeBatRelGid           integer;

  set @@ErrorTextProcedure = 'BestellingenObvBesteladvies > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BakGid = ' + string(@BakGid)+', @BatGid = '+string(@BatGid));

  set @AantalBestellingen = 0;
  set @VorigeNawGid       = -1;
  set @VorigeMagGid       = -1;
  set @VorigeOrkNummer    = -1;

  select VgbDefAfleverDatumRegels, VgbDefStatus into @VgbDefAfleverDatumRegels, @VgbDefStatus from tabVasteGegevensBestellingen;

  for @Cursor As Cursor_tabBestelAdviesRegel Cursor For
    select   BarGid @BarGid, BarMagGid @BarMagGid, BarNawGid @BarNawGid, BarArtGid @BarArtGid, BarArtPartijGid @BarArtPartijGid, BarVoorraadEenhedenInInkoopEenheid @BarVoorraadEenhedenInInkoopEenheid,
             BarOmschrijvingOpBestelbrief @BarOmschrijvingOpBestelbrief, BarInkoopEenheid @BarInkoopEenheid,
             BakIsOntvangstdatumVullenObvAfleverdagen @BakIsOntvangstdatumVullenObvAfleverdagen, BakBestelDatum @BakBestelDatum, BakBestelTijd @BakBestelTijd, BakOntvangstDatum @BakOntvangstDatum,
             case BakDefaultInkoper
               when 0 then null
               when 1 then (select GebrRelGID from tabGebruiker where NaamGebruiker = @@GebruikerCode)
               when 2 then LevGegRelGidInkoper
               when 3 then BakRelGid
             end @BakRelGid, BakPerOrderAparteBestelling @BakPerOrderAparteBestelling,
             BatOntvangstdatum @BatOntvangstdatum,
             ArtAantDecAantallen @ArtAantDecAantallen, ArtBtwCodeInkoop @ArtBtwCodeInkoop, ArtPrijsPer @ArtPrijsPer, ArtAantDecPrijzen @ArtAantDecPrijzen,
             ArtKostprijsEx @ArtKostprijsEx,
             NawFilValNummer @NawFilValNummer, NawFilLvcNummer @NawFilLvcNummer, NawFilBtcNummer @NawFilBtcNummer, NawFilBtwCode @NawFilBtwCode,
             LevGegBestelAdres @LevGegBestelAdres, LevGegAdrGidBestelAdres @LevGegAdrGidBestelAdres,
             AldHeeftEigenInkoopprijs @AldHeeftEigenInkoopprijs, AldInkoopPrijsPer @AldInkoopPrijsPer, AldLeverTijd @AldLeverTijd, AldArtCodeBijLeverancier @AldArtCodeBijLeverancier,
             AldGid @AldGid, AldValNummer @AldValNummer, AldInkoopPrijs @AldInkoopPrijs,
             ArtEanCode @ArtEanCode,
             //Indien aparte bestelling per order, dan van de eerste de beste specificatieregel die onder een besteladviesregel hangt, het order nummer ophalen. In dit geval horen alle specificatie bij dezelfde order
             if (BakPerOrderAparteBestelling = 1) or
                (BakPerOrderregelAparteBestelregel = 1) then IsNull((select first OrkNummer from tabBestelAdviesRegelSpecificatie
                                                                             inner join tabOrderRegel on (OrrGid = BarsOrrGid)
                                                                             inner join tabOrderKop   on (OrkGid = OrrOrkGid)
                                                                             where BarsBarGid = BarGid),0) else 0 endif @OrkNummer,
             if BakPerOrderregelAparteBestelregel = 1   then IsNull((select first OrrRegelnr from tabBestelAdviesRegelSpecificatie
                                                                             inner join tabOrderRegel on (OrrGid = BarsOrrGid)
                                                                             where BarsBarGid = BarGid),0) else 0 endif @OrrRegelnr,
             //ACW 23-07-2010: Directe levering
             BatBestemming       @BatBestemming,
             BatNawGidAflevering @BatNawGidAflevering,
             BatAfleveradresNAW  @BatAfleveradresNAW,
             BatAdrGidAflevering @BatAdrGidAflevering,
             BatRelGid           @BatRelGid,
             ArtPartijInkoopPrijs @ArtPartijInkoopPrijs,
             ArtPartijInkoopValNummer @ArtPartijInkoopValNummer
    from     tabBestelAdviesRegel
             inner join tabBestelAdviesKop               on (BakGid = BarBakGid)
             inner join tabBestelAdviesTotalen           on (BatGid = BarBatGid)
             inner join tabArtikel                       on (ArtGid = BarArtGid and ArtIsGeblokkeerdInkoop = 0)
             inner join tabNawFile                       on (NawFilNawGid = BarNawGid)
             left outer join tabLeverancierGegevens      on (LevGegNawGid = BarNawGid)
             left outer join tabArtikelLeverancier       on (ArtLevArtGid = BarArtGid and ArtLevNawGid = BarNawGid)
             left outer join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid and AldInkoopEenheid = BarInkoopEenheid)
             left outer join tabArtikelEan               on (ArtEanGId = AldArtEanGid)
             left outer join tabArtikelPartij            on (ArtPartijGid = BarArtPartijGid)
    where    BarBakGid = @BakGid and (@BatGid is null or @BatGid = BarBatGid) and
            (BarNawGid is not null) and (BarVoorraadeenhedenInInkoopEenheid > 0) and (IsNull(LevGegBestellenGeblokkeerd, 0) = 0)
             //ACW 03-11-2010 Incident #04490: De volgorde is altijd gelijk aan de eisen gesteld aan het aanmaken van nieuwe bestellingen (groeperen)
    order by BarNawGid, BarMagGid, BatBestemming, BatNawGidAflevering, BatAfleveradresNAW, BatAdrGidAflevering, BatRelGid,
             //ACW Defect 48785/48786: Als we per order een aparte bestelling hebben, dan qua volgorde eerst de ordernummers en dan pas het artikel
             if BakPerOrderAparteBestelling = 1 then @OrkNummer endif,
             if (BakPerOrderAparteBestelling = 0 or BakPerOrderregelAparteBestelregel = 0) then ArtCode else '' endif, @OrkNummer, @OrrRegelnr, ArtCode
  for read only
  do
    if @BarMagGid <> @VorigeMagGid or @BarNawGid <> @VorigeNawGid or (@OrkNummer <> @VorigeOrkNummer and @BakPerOrderAparteBestelling = 1)
      //ACW 03-11-2010 Incident #04490: Uitbreiding voor bestemming; als bestemming(saders) verandert, dan ok gelijk een nieuwe aanmaken
      or @BatBestemming <> @VorigeBatBestemming
      or not (   (@BatBestemming = 0) // NOT (Bestemming = magazijn OF een debiteur, maar dan moet het adres van die debiteur ook helemaal gelijk zijn)
              or (@BatBestemming = 1 and isnull(@BatNawGidAflevering, 0) = isnull(@VorigeBatNawGidAflevering, 0)
                                     and        @BatAfleveradresNAW      =        @VorigeBatAfleveradresNAW
                                     and isnull(@BatAdrGidAflevering, 0) = isnull(@VorigeBatAdrGidAflevering, 0)
                                     and isnull(@BatRelGid          , 0) = isnull(@VorigeBatRelGid          , 0)
                 )
              )
      then
      //call Trace('BestellingenObvBesteladvies > Genereer bestelnummer');
      call BestellingGenereerNieuwBestellingnummer(1, @BakStartNummerBestelling, @BstKopNummer);

      insert into tabBestelKop(BstKopMagGid, BstKopNawGid, BstKopNummer, BstKopValNummer, BstKopLvcNummer, BstKopBtcNummer,
                               BstKopBestelAdresSoort, BstKopAdrGid, BstKopAfleverDatum, BstKopBestelDatum, BstKopBestelTijd, BstKopRelGidInkoper, BstKopIsGoedgekeurd,
                               BstKopRelGid, BstKopAfleverAdres, BstKopNawGidAflevering, BstKopAfleverAdresNAW, BstKopAdrGidAflevering, BstKopRelGidAflevering)
      select  @BarMagGid, @BarNawGid, @BstKopNummer, @NawFilValNummer, @NawFilLvcNummer, @NawFilBtcNummer,
              @LevGegBestelAdres, @LevGegAdrGidBestelAdres, @BatOntvangstdatum, @BakBestelDatum, @BakBestelTijd, @BakRelGid, @VgbDefStatus,
             (select RelGid from tabRelatie
                      inner join tabRelatieFunctie on (FnRelGid=RelGid and IsBelangrijkste<>0)
                      inner join tabScherm         on (SchermFnCode=RelFnCode and SchermSoort=40) where RelNawGid = @BarNawGid),
              @BatBestemming, @BatNawGidAflevering, @BatAfleveradresNAW, @BatAdrGidAflevering, @BatRelGid;

      set @BstKopGid                 = @@Identity;
      set @AantalBestellingen        = @AantalBestellingen + 1;
      set @VorigeNawGid              = @BarNawGid;
      set @VorigeMagGid              = @BarMagGid;
      set @VorigeOrkNummer           = @OrkNummer;
      set @VorigeBatBestemming       = @BatBestemming;
      set @VorigeBatNawGidAflevering = @BatNawGidAflevering;
      set @VorigeBatAfleveradresNAW  = @BatAfleveradresNAW ;
      set @VorigeBatAdrGidAflevering = @BatAdrGidAflevering;
      set @VorigeBatRelGid           = @BatRelGid          ;
      call VrijeRubriekenVulDefaults('BST', 0, 0, @BstKopGid);
      call BestellingOvernemenVrijeRubrieken(@BstKopGid);
    end if;

    set @BestelDatum = @BakBestelDatum;
    //call Trace('BestellingenObvBesteladvies > Afleverdatum voor bestelregel bepalen');
    case @VgbDefAfleverDatumRegels
       when 0 then set @Ontvangstdatum = Date(now());
       when 1 then set @Ontvangstdatum = Date(@@VerwerkingsDatum);
       when 2 then set @Ontvangstdatum = if @Besteldatum is null then null else @BestelDatum + @AldLeverTijd endif;
       when 3 then if @BestelDatum is not null then
                     if @BakBestelTijd is not null then
                        set @BestelDatum = @BestelDatum + @BakBestelTijd;
                        set @HeeftBestelTijd = 1;
                     else
                        set @HeeftBestelTijd = 0;
                     end if;
                     call BerekenAfleverDatum(@BarNawGid, @AldLevertijd, ISODayOfWeek(@BestelDatum), @Besteldatum, @HeeftBestelTijd, @Ontvangstdatum)
                   end if;
       when 4 then set @Ontvangstdatum = (select BstKopAfleverDatum from tabBestelKop where BstKopGid = @BstKopGid)
       else set @Ontvangstdatum = null;
    end case;

    insert into tabBestelRegel(BstRglBstKopGid, BstRglSoort, BstRglArtGid, BstRglArtPartijGid, BstRglNummer, BstRglVoorraadEenhedenInInkoopEenheid,
                               BstRglOms, BstRglBtwCode, BstRglPrijsPerSoort, BstRglPrijsPer, BstRglAfleverDatum, BstRglInkoopEenheid, BstRglArtikelNummerLeverancier,
                               BstRglEANcode, BstRglPrijs, BstRglAantalNogTeOntvangenInVoorrEenh)
    select @BstKopGid, 2 /* Artikel */, @BarArtGid, @BarArtPartijGid, IsNull((select max(BstRglNummer) from tabBestelRegel where BstRglBstKopGid = @BstKopGid), 0)+1, @BarVoorraadEenhedenInInkoopEenheid,
           @BarOmschrijvingOpBestelbrief,
           if ((select BtwPercentage from tabBtw where BtwCode = @NawFilBtwCode) = 0) and (@NawFilBtwCode is not null) then
             @NawFilBtwCode
           else
             @ArtBtwCodeInkoop
           endif,
           if IsNull(@AldHeeftEigenInkoopprijs, 0) = 1 then @AldInkoopPrijsPer else 1 endif BstRglPrijsPerSoort,
           //25-06-2013 RVL #38654: De prijsper altijd vanuit het artikel overnemen. Als er direct een bestelling wordt aangemaakt (dus niet via besteladvies),
           //                       dan wordt dit ook zo gedaan. Zou eingelijk "1" moeten zijn, de prijs per inkoopeenheid. Maar om niet alles overhoop te halen, zetten
           //                       we hier nu ook de prijs per van het artikel in.
           //if BstRglPrijsPerSoort = 1 then @ArtPrijsPer else 1 endif,
           @ArtPrijsPer,
           @OntvangstDatum, @BarInkoopEenheid, @AldArtCodeBijLeverancier,
           @ArtEanCode,
           if (@BarArtPartijGid is not null) then // inkoopprijs van partij
             if @ArtPartijInkoopValNummer = IsNull(@NawFilValNummer, @@BasisValutaNummer) then
               @ArtPartijInkoopPrijs
             else
               ValutaOmrekenen(@ArtPartijInkoopValNummer, @ArtPartijInkoopPrijs, @NawFilValNummer, @@BjGid, @@Pernr, @ArtAantDecPrijzen)
           endif
           else
             if (@AldGid is null) or (@AldHeeftEigenInkoopprijs = 0) then // inkoopprijs vullen met kostprijs van artikel
               if @@BasisValutaNummer = IsNull(@NawFilValNummer, @@BasisValutaNummer) then
                 @ArtKostprijsEx
               else
                 ValutaOmrekenen(@@BasisValutaNummer, @ArtKostprijsEx, @NawFilValNummer, @@BjGid, @@Pernr, @ArtAantDecPrijzen)
               endif
             else
               if @AldValNummer = IsNull(@NawFilValNummer, @@BasisValutaNummer) then // inkoopprijs bij leverancier
                 @AldInkoopPrijs
               else
                 ValutaOmrekenen(@AldValNummer, @AldInkoopPrijs, @NawFilValNummer, @@BjGid, @@Pernr, @ArtAantDecPrijzen)
               endif
             endif
		   endif, 1;  //Aantal "nog te ontvangen" moet iig <> 0 zijn, anders wordt "datum laatste ontvangst" gevuld. Het goede aantal wordt verderop berekend.
    set @BstRglGid = @@Identity;

    //call Trace('BestellingenObvBesteladvies > Voeg bestelregedetails toe voor BstRglGid = '+string(@BstRglGid));
    // Indien BarsSoort = 9 (=Berekende regel), dan behandelen als een magazijnregel dus eventueel optellen bij een bestaande magazijnregel
    insert into tabBestelRegelDetail(BrdBstRglGid, BrdSoort, BrdOrrGid, BrdAantalBesteld, brdAantalNogTeOntvangen)
    select   @BstRglGid, if BarsSoort  = 9 then 0 else BarsSoort endif Soort, BarsOrrGid, sum(BarsAantalInVoorraadEenheden), sum(BarsAantalInVoorraadEenheden)
    from     tabBestelAdviesRegelSpecificatie
    where    BarsBarGid = @BarGid
    group by @BstRglGid, Soort, BarsOrrGid
    order by Soort desc;


    //call Trace('Bereken aantal besteld ivm eventuele korting');
    select Round(sum(BrdAantalBesteld) / BstRglVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen) into @AantalBesteld
    from   tabBestelRegel inner join tabBestelRegelDetail on (BrdBstRglgid = BstRglGid) where BrdBstRglGid = @BstRglGid group by BstRglVoorraadEenhedenInInkoopEenheid;
    if @AldGid is not null then
      call BerekenLeveranciersKorting(@AldGid, @AantalBesteld, @NawFilValNummer, null, @KortingSoort, @KortingsBedrag, @KortingsPercentage);
    else
      set @KortingSoort       = null;
      set @KortingsBedrag     = null;
      set @KortingsPercentage = null;
    end if;

    //call Trace('BestellingenObvBesteladvies > Schrijf aantal besteld per bestelregel weg');
    update tabBestelRegel
    set    BstRglKortingSoort                    = @KortingSoort,
           BstRglKortingPercentage               = @KortingsPercentage,
           BstRglKortingBedrag                   = @KortingsBedrag,
           BstRglAantalBesteld                   = @AantalBesteld,
           BstRglAantalNogTeOntvangenInVoorrEenh = (select sum(brdAantalNogTeOntvangen) from tabBestelRegelDetail where BrdBstRglGid = @BstRglGid)
    where  BstRglGid = @BstRglGid;

    //call Trace('BestellingenObvBesteladvies > Verwijder de besteladviesregel die overgehaald is naar de bestelregel');
    //ACW 10-08-2010: incident 4132: Regel uit de totalen halen vooradt die wordt verwijderd
    call BestelAdviesMaakTotalenPerBestelling(@BakGid, @BarGid, 0);
    delete tabBestelAdviesRegel where BarGid = @BarGid;

  end for;

  //call Trace('BestellingenObvBesteladvies > Test of er nog besteladviesregels zijn');
  if not exists(select 1 from tabBestelAdviesRegel where BarBakGid = @BakGid) then
    //call Trace('BestellingenObvBesteladvies > Verwijder besteladvieskop');
    delete tabBestelAdviesKop where BakGid = @BakGid;
  end if;

  set @@ErrorTextProcedure = 'BestellingenObvBesteladvies';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure BestellingGenereerNieuwBestellingnummer(in @Forceer smallint, in @StartNummer numeric(10,0), out @Nummer numeric(10,0))
begin
  declare @Genereren numeric(10,0);
  declare @Gevonden integer;

  set @@ErrorTextProcedure = 'BestellingGenereerNieuwBestellingnummer > @Forceer = '+string(@Forceer)+', @StartNummer = '+string(@StartNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  set @nummer=0;
  if @Forceer = 1 then
    set @Genereren=1;
    select if @StartNummer <> -1 then @StartNummer else VgbStartnummer endif into @Startnummer from tabVasteGegevensBestellingen;
  else
    select VgbDefBestelnummer, if @StartNummer <> -1 then @StartNummer else VgbStartnummer endif into @Genereren, @Startnummer from tabVasteGegevensBestellingen;
  end if;
  if @Genereren=1 then
    set @gevonden=0;
    while @gevonden=0
    loop
      set @nummer = null;
      select min(BstKopNummer) into @Nummer from tabBestelKop where BstKopNummer >= @Startnummer;
      if @Nummer is null then
        set @Gevonden = 1;
        set @Nummer   = @Startnummer;
      else
        if @Nummer = @Startnummer then
          if @Startnummer=9999999999 then
            set @Startnummer=1;
          else
            set @startnummer=@nummer+1;
          end if
        else
          // Eerstvolgende ligt toch hoger, dus we kunnen gewoon het startnummer gebruiken
          set @Nummer   = @Startnummer;
          set @Gevonden = 1;
        end if;
      end if;
    end loop;
    if @nummer=9999999999 then
      update tabVasteGegevensBestellingen set VgbStartnummer = 1;
    else
      update tabVasteGegevensBestellingen set VgbStartnummer = @Nummer + 1;
    end if;
  end if;

  set @@ErrorTextProcedure = 'BestellingGenereerNieuwBestellingnummer > @Nummer='+string(@Nummer);
  //call TraceBegin(@@ErrorTextProcedure);

end;


create or replace procedure BestellingKopieren(in @BronBstKopGid integer, in @NieuweNawGid integer, in @PrijzenOpnieuwBepalen smallint, out @NieuwBstKopGid integer)
//Kopieren:
//-1 tabBestelKop           1 stuks, bijna alle velden(niet mbt gereserveerd, voorraadaantallen, defaultmagazijn)
//-2 tabBestelRegel         n stuks, meerdere bestelregels.
//-3 tabBestelRegelDetail   n stuks, meerdere besteldetailregels.
//-4 vrije rubrieken        1 stuks

begin
  declare @AndereLeverancier      smallint        = 0;
  declare @BstKopNummer           numeric(10,0);
  declare @BstKopIsGoedgekeurd    smallint;
  declare @BstKopBestelDatum      date;
  declare @BstKopBestelTijd       time;
  declare @BstKopAfleverDatum     date;
  declare @BstKopReferentie       long nvarchar;
  declare @BstKopRelGidInkoper    integer;
  declare @VgbDefAfleverDatumKop  smallint;
  declare @VgbDefBestelDatum      smallint;
  declare @VgbDefInkoper          smallint;
  declare @VgbDefReferentie       long nvarchar;
  declare @VgbDefStatus           smallint;
  declare @ValutaNummer           integer;
  declare @LvcNummer              integer;
  declare @BtcNummer              integer;
  declare @DefaultRelGid          integer;
  declare @LevGegRelGidInkoper    integer;
  declare @KortingSoort           smallint;
  declare @KortingsBedrag         numeric(15,3);
  declare @KortingsPercentage     numeric(15,2);
  declare @BstKopEmailExtraTekst  long nvarchar;

  //call TraceBegin('Bestelling kopieren > @BronBstKopGid = ' + string(@BronBstKopGid));

  //Vaste gegevens bestellingen inlezen
  select VgbDefAfleverDatumKop,  VgbDefBestelDatum,  VgbDefInkoper,  VgbDefReferentie,  VgbDefStatus
  into  @VgbDefAfleverDatumKop, @VgbDefBestelDatum, @VgbDefInkoper, @VgbDefReferentie, @VgbDefStatus
  from tabVasteGegevensBestellingen;

  call BestellingGenereerNieuwBestellingnummer(1, -1, @BstKopNummer);  //altijd een nummer genereren

  //Als er een andere crediteur is gekozen dan ook de vaste gegevens ophalen.
  if @NieuweNawGid <> (Select BstKopNawGid from tabBestelKop where BstKopGid = @BronBstKopGid) then
    set @AndereLeverancier = 1;

    select
      NawFilValNummer, NawFilLvcNummer, NawFilBtcNummer,
      (select RelGid from tabRelatie
                          inner join tabRelatieFunctie on (FnRelGid=RelGid and IsBelangrijkste<>0)
                          inner join tabScherm on (SchermFnCode=RelFnCode and SchermSoort=40) where RelNawGid = NawGid) DefaultRelGid,
      LevGegRelGidInkoper
    into @ValutaNummer, @LvcNummer, @BtcNummer, @DefaultRelGid, @LevGegRelGidInkoper
    from tabNawFile
    inner join      tabNaw                    on (NawGid                  = NawFilNawGid)
    inner join      tabAdres Vestiging        on (Vestiging.AdrGid        = NawGidVestiging)
    inner join      tabAdres Correspondentie  on (Correspondentie.AdrGid  = NawGidCorrespondentie)
    left outer join tabLeverancierGegevens    on (LevGegNawGid            = NawGid)
    where NawGid = @NieuweNawGid;

    //set @ValutaNummer = @@BasisValutaNummer;

    //als we rechten hebben tot goedkeuren, dan vinkje zetten obv vaste gegevens, anders vinkje uit laten. (bug #14448)
    if (IsModuleActive('mbsg') = 1) then
      set @BstKopIsGoedgekeurd = @VgbDefStatus;
    else
      set @BstKopIsGoedgekeurd = 0;
    end if;

    set @BstKopReferentie = @VgbDefReferentie;

    //default inkoper
    case @VgbDefInkoper
      when 0 then //Leeg
        set @BstKopRelGidInkoper = Null;
      when 1 then //Volgens gebruiker
        select GebrRelGID into @BstKopRelGidInkoper from tabGebruiker where NaamGebruiker = @@GebruikerCode;
      when 2 then //Volgens leverancier
        set @BstKopRelGidInkoper  = @LevGegRelGidInkoper;
    end case;
  end if;

  case @VgbDefBestelDatum
    when 0 then //Systeemdatum
      set @BstKopBestelDatum  = now();
      set @BstKopBestelTijd   = Null;
    when 1 then //Verwerkingsdatum
      set @BstKopBestelDatum  = @@Verwerkingsdatum;
      set @BstKopBestelTijd   = Null;
    when 2 then //Leeg
      set @BstKopBestelDatum  = Null;
      set @BstKopBestelTijd   = Null;
  end case;

  case @VgbDefAfleverDatumKop
    when 0 then //Systeemdatum
      set @BstKopAfleverDatum = now();
    when 1 then //Verwerkingsdatum
      set @BstKopAfleverDatum = @@Verwerkingsdatum;
    when 3 then //Leeg
      set @BstKopAfleverDatum = Null;
  end case;

  //call Trace('Bestelling kopieren > BestelKop');
  insert into tabBestelKop with auto name
  select
    now() as BstKopAanmaakDatum,
    BstKopAdrGid,
    BstKopAdrGidAflevering,
    BstKopAfleverAdres,
    BstKopAfleverAdresNAW,
    @BstKopAfleverDatum as BstKopAfleverDatum,
    BstKopBestelAdresSoort,
    @BstKopBestelDatum as BstKopBestelDatum,
    @BstKopBestelTijd as BstKopBestelTijd,
    IsNull(@BtcNummer, if (@AndereLeverancier = 0) then BstKopBtcNummer endif) as BstKopBtcNummer,
    //BstKopGid,
//    BstKopGoedgekeurdDoor,
//    BstKopGoedgekeurdOp,
    IsNull(@BstKopIsGoedgekeurd, if (@AndereLeverancier = 0) then BstKopIsGoedgekeurd endif) as BstKopIsGoedgekeurd,
//    BstKopIsVerwerkt,
//    BstKopIsVolledigGeboekt,
//    BstKopIsVolledigOntvangen,
//    BstKopLaatstGeboektDoor,
//    BstKopLaatstGeboektOp,
//    BstKopLaatstOntvangenDoor,
//    BstKopLaatstOntvangenOp,
    //BstKopLastModified,
    IsNull(@LvcNummer, if (@AndereLeverancier = 0) then BstKopLvcNummer endif) as BstKopLvcNummer,
    BstKopMagGid,
    @NieuweNawGid as BstKopNawGid,
    BstKopNawGidAflevering,
    @BstKopNummer as BstKopNummer,
    BstKopOpm,
    IsNull(@BstKopReferentie, if (@AndereLeverancier = 0) then BstKopReferentie endif) as BstKopReferentie,
    IsNull(@DefaultRelGid, if (@AndereLeverancier = 0) then BstKopRelGid endif) as BstKopRelGid,
    BstKopRelGidAflevering,
    IsNull(@BstKopRelGidInkoper, if (@AndereLeverancier = 0) then BstKopRelGidInkoper endif) as BstKopRelGidInkoper,
    IsNull(@ValutaNummer, if (@AndereLeverancier = 0) then BstKopValNummer endif) as BstKopValNummer,
//    BstKopVerwerktDoor,
//    BstKopVerwerktOp,
    BstKopEmailExtraTekst
  from tabBestelKop
  where BstKopGid = @BronBstKopGid;

  //Artgid van nieuwe artikel ophalen
  set @NieuwBstKopGid = @@Identity;

  //call Trace('Bestelling kopieren > BestelRegel');
  insert into tabBestelRegel  with auto name
  select
    BstRglAantalBesteld,
    BstRglAantalBesteld as BstRglAantalNogTeOntvangenInVoorrEenh,
    //BstRglAantalOntvangenInVoorrEenh,
    //BstRglAfleverdatum,
    BstRglArtGid,
    BstRglArtikelNummerLeverancier,
    BstRglArtPartijGid,
    @NieuwBstKopGid as BstRglBstKopGid,
    BstRglBtwCode,
    BstRglEANcode,
    //BstRglGid,
    BstRglInkoopEenheid,
    BstRglKortingBedrag,
    BstRglKortingPercentage,
    BstRglKortingSoort,
    //BstRglLastModified,
    BstRglNummer,
    BstRglOms,
    BstRglOpm,
    BstRglPrijs,
    BstRglPrijsPer,
    BstRglPrijsPerSoort,
    BstRglSoort,
    BstRglTotaalAantalSpecRegelsKomtOvereen,
    BstRglVoorraadEenhedenInInkoopEenheid
  from tabBestelRegel
  inner join tabBestelKop                     on (BstKopGid = tabBestelRegel.BstRglBstKopGid)
  inner join tabArtikel                       on (ArtGid = BstRglArtGid)
  left outer join tabArtikelLeverancier       on (ArtLevArtGid = BstRglArtGid and ArtLevNawGid = @NieuweNawGid)
  left outer join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid and AldInkoopEenheid = BstRglInkoopEenheid)
  where tabBestelRegel.BstRglBstKopGid = @BronBstKopGid;

  //call Trace('Bestelling kopieren > BestelRegelDetail');
  insert into tabBestelRegelDetail(brdAantalBesteld, brdAantalOntvangen, brdAantalNogTeOntvangen, brdSoort, brdBstRglGid)
  select BstRglAantalBesteld, BstRglAantalOntvangenInVoorrEenh, BstRglAantalNogTeOntvangenInVoorrEenh, 0, BstRglGid
  from tabBestelRegel
  where BstRglBstKopGid = @NieuwBstKopGid
  and BstRglSoort = 2;

  //Prijzen en kortingen opnieuw bepalen
  if (@PrijzenOpnieuwBepalen = 1) then
    call BestellingPrijzenenKortingOpnieuwBepalen(@NieuwBstKopGid);

  end if;

  //call Trace('Bestelling kopieren > Vrije rubrieken');
  call VrKopieerRecord('BST',0,0,'BST',0,0,@BronBstKopGid,@NieuwBstKopGid);

  //call TraceEind('Bestelling kopieren > @NieuwBstKopGid = ' + string(@NieuwBstKopGid));
end;
//call BestellingKopieren(1,3,0,@NieuwBstKopGid);



create or replace procedure BestellingOvernemenVrijeRubrieken(in @BstKopGid integer)
begin
  declare @NawGid             integer;
  declare @VeldNaam           nchar(20);
  declare @VeldInhoudChar     nchar(255);
  declare @VeldInhoudNumeric  numeric(16,5);
  declare @VeldInhoudSelectie smallint;
  declare @VeldInhoudDate     date;
  declare @VeldInhoudTime     time;
  declare @SrcVeldNaam        nchar(30);

  set @@ErrorTextProcedure = 'OrdersOvernemenVrijeRubrieken > @BstKopGid='+string(@BstKopGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select BstKopNawGid into @NawGid from tabBestelKop where BstKopGid = @BstKopGid;

  for @Cursor AS cursor_VrijeRubrieken CURSOR FOR
    select BST.VrVeldNaam @BSTVrVeldNaam, BST.VrLabel @BSTVrLabel, BST.VrType @BSTVrVeldType, BST.VrLengte @BSTVrLengte, BST.VrDecimalen @BSTVrDecimalen, BST.VrSjabloon @BSTVrSjabloon, NAW.VrGid @NawVrGid, NAW.VrType @NawVrType, NAW.VrVeldnaam @NawVrVeldNaam, NAW.VrDefaultDate @NawVrDefaultDate, NAW.VrDefaultGetal @NawVrDefaultGetal, NAW.VrDefaultString @NawVrDefaultString, NAW.VrDefaultTime @NawVrDefaultTime
    from   tabVrijeRubrieken BST
    inner join tabVrijeRubrieken NAW on NAW.VrBestandOms = 'NAW' and NAW.VrGroepId = 2 and NAW.VrSubGroepId = 2 and NAW.VrLabel = BST.VrLabel and NAW.VrType = BST.VrType and NAW.VrLengte = BST.VrLengte and NAW.VrDecimalen = BST.VrDecimalen and NAW.VrSjabloon = BST.VrSjabloon
    where  BST.VrBestandOms = 'BST'
  for read only
  do
    // Alle bestelling vrije rubrieken doorlopen die ook als NAW vrije rubriek voorkomen met dezelfde kenmerken
    //call Trace('---->@BstVrLabel='+string(@BstVrLabel)+', @BstVrVeldNaam='+string(@BstVrVeldNaam)+', @NawVrVeldNaam='+string(@NawVrVeldNaam));

    // Er is een vrije rubrieken record voor deze debiteur !
    if exists(select 1 from tabVrBST000000 where VrBST000000RecordId = @BstKopGid) then
      //call Trace('update tabVrBST000000 set '+@BSTVrVeldNaam+' = (select '+string(@NawVrVeldNaam)+' from tabVrNAW002002 where VrNaw002002RecordId = '+string(@NawGid)+') where VrBST000000RecordId = @BstKopGid;');
      execute immediate ('update tabVrBST000000 set '+string(@BSTVrVeldNaam)+' = (select '+string(@NawVrVeldNaam)+' from tabVrNAW002002 where VrNaw002002RecordId = @NawGid) where VrBST000000RecordId = @BstKopGid;');
    else
      //call Trace('insert into tabVrBST000000 (VrBST000000RecordId, '+string(@BstVrVeldNaam)+') values (@BstKopGid, (select '+string(@NawVrVeldNaam)+' from tabVrNAW002002 where VrNaw002002RecordId = @NawGid));');
      execute immediate ('insert into tabVrBST000000 (VrBST000000RecordId, '+string(@BSTVrVeldNaam)+') values (@BstKopGid, (select '+string(@NawVrVeldNaam)+' from tabVrNAW002002 where VrNaw002002RecordId = @NawGid));');
    end if;

  end for;
  //call TraceEind(@@ErrorTextProcedure);

end;
//call BestellingOvernemenVrijeRubrieken(0);


create or replace procedure BestellingPrijzenenKortingOpnieuwBepalen(in @BstKopGid integer)
begin
  declare @KortingSoort           smallint;
  declare @KortingsBedrag         numeric(15,3);
  declare @KortingsPercentage     numeric(15,2);

  //call TraceBegin('Bestelling prijzen en kortingen opnieuw bepalen > @BstKopGid = ' + string(@BstKopGid));

  for @Cursor As Cursor_tabBestelAdviesRegel Cursor For
    select Round((Select sum(BrdAantalBesteld) from tabBestelRegelDetail where BrdBstRglgid = BstRglGid) / BstRglVoorraadEenhedenInInkoopEenheid, ArtAantDecAantallen) @AantalBesteld,
           BstKopValNummer @BstKopValNummer,
           AldGid @AldGid,
           BstRglGid @BstRglGid,
           if (AldGid is null) or (AldHeeftEigenInkoopprijs = 0) then
            if @@BasisValutaNummer = IsNull(BstKopValNummer, @@BasisValutaNummer) then
              ArtKostprijsEx
            else
              ValutaOmrekenen(@@BasisValutaNummer, ArtKostprijsEx, BstKopValNummer, @@BjGid, @@Pernr, ArtAantDecPrijzen)
            endif
           else
            if AldValNummer = IsNull(BstKopValNummer, @@BasisValutaNummer) then
              AldInkoopPrijs
            else
              ValutaOmrekenen(AldValNummer, AldInkoopPrijs, BstKopValNummer, @@BjGid, @@Pernr, ArtAantDecPrijzen)
            endif
           endif @BstRglPrijs,
           BstRglPrijsPer @BstRglPrijsPer,
           if IsNull(AldHeeftEigenInkoopprijs, 0) = 1 then AldInkoopPrijsPer else 1 endif @BstRglPrijsPerSoort
    from   tabBestelRegel
    inner join tabBestelKop                     on (BstKopGid = BstRglBstKopGid)
//      inner join tabBestelRegelDetail             on (BstRglGid = BrdBstRglgid)
    inner join tabArtikel                       on (ArtGid = BstRglArtGid)
    left outer join tabArtikelLeverancier       on (ArtLevArtGid = BstRglArtGid and ArtLevNawGid = BstKopNawGid)
    left outer join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid and AldInkoopEenheid = BstRglInkoopEenheid)
    where BstRglBstKopGid = @BstKopGid
//      group by BstRglVoorraadEenhedenInInkoopEenheid,BstKopValNummer,AldGid,BstRglGid, ArtAantDecAantallen
  for read only
  do

    if @AldGid is not null then
      call BerekenLeveranciersKorting(@AldGid, @AantalBesteld, @BstKopValNummer, null, @KortingSoort, @KortingsBedrag, @KortingsPercentage);
    else
      set @KortingSoort       = null;
      set @KortingsBedrag     = null;
      set @KortingsPercentage = null;
    end if;

    update tabBestelRegel
    set    BstRglKortingSoort                    = @KortingSoort,
           BstRglKortingPercentage               = @KortingsPercentage,
           BstRglKortingBedrag                   = @KortingsBedrag,
           BstRglPrijs                           = @BstRglPrijs,
           BstRglPrijsPer                        = @BstRglPrijsPer,
           BstRglPrijsPerSoort                   = @BstRglPrijsPerSoort,
           BstRglAantalBesteld                   = @AantalBesteld,
           BstRglAantalNogTeOntvangenInVoorrEenh = (select sum(brdAantalNogTeOntvangen) from tabBestelRegelDetail where BrdBstRglGid = @BstRglGid)
    where  BstRglGid = @BstRglGid;
  end for;

  //call TraceEind('Bestelling prijzen en kortingen opnieuw bepalen > @BstKopGid = ' + string(@BstKopGid));
end;

create or replace procedure BestelRegelpositieWijzigen(
 in  @BstRglGid         integer,
 in  @VerplaatsenNaar   integer,    // 0 = ga naar eerste regel, 1 = ga Ã©Ã©n positie omhoog, 2 = ga Ã©Ã©n positie omlaag, 3 = ga naar laatste regel, overig=ongeldige waarde
 out @NieuweRegelNummer integer
)
begin
  declare @BstKopGid              integer;
  declare @HuidigeRegelNummer     integer;

  // call TraceBegin('BestelRegelPositieWijzigen(@BstRglGid=' + string(@BstRglGid) + ', @VerplaatsenNaar=' + string(@VerplaatsenNaar) + ' (0=naar eerste regel, 1=een regel omhoog, 2=een regel omlaag, 3=naar laatste regel, overig=ongeldige waarde)');

  // Bij bestellen zijn er geen volgregels of versieregels, dus kunnen we puur met BstRglNummer werken.
  select BstRglBstKopGid, BstRglNummer
  into @BstKopGid, @HuidigeRegelNummer
  from tabBestelRegel
  where (BstRglGid = @BstRglGid);

  // call Trace('@BstKopGid=' + string(@BstKopGid) + ',  @HuidigeRegelNummer=' + string(@HuidigeRegelNummer) );

  if (@HuidigeRegelNummer is not null) and (@BstKopGid is not null) then
  begin

    if not @VerplaatsenNaar between 0 and 3 then
      // call Trace('@VerplaatsenNaar=' + string(@VerplaatsenNaar) + ' ==> PROCEDURE AFBREKEN: ongeldige waarde @VerplaatsenNaar');
    else
      set @NieuweRegelNummer = (case @VerplaatsenNaar
                                      /*eerste regel */ when 0 then (select first BstRglNummer from tabBestelRegel where (BstRglBstKopGid = @BstKopGid) and (BstRglNummer < @HuidigeRegelNummer) order by BstRglNummer)
                                      /*regel omhoog */ when 1 then (select first BstRglNummer from tabBestelRegel where (BstRglBstKopGid = @BstKopGid) and (BstRglNummer < @HuidigeRegelNummer) order by BstRglNummer desc)
                                      /*regel omlaag */ when 2 then (select first BstRglNummer from tabBestelRegel where (BstRglBstKopGid = @BstKopGid) and (BstRglNummer > @HuidigeRegelNummer) order by BstRglNummer)
                                      /*laatste regel*/ when 3 then (select first BstRglNummer from tabBestelRegel where (BstRglBstKopGid = @BstKopGid) and (BstRglNummer > @HuidigeRegelNummer) order by BstRglNummer desc)
                                 end);
      // als het veld niet gevuld is dan is verplaatsen niet mogelijk en vullen we het huidige regelnummer in zodat er niets gebeurt.
      // call Trace(if (@NieuweRegelNummer is null) then '==> PROCEDURE AFBREKEN: @NieuweRegelNummer is null (waarschijnlijk was regel al eerste of laatste regel)' else '@NieuweRegelNummer=' + string(@NieuweRegelNummer) endif);
    end if;

    set @NieuweRegelNummer = IsNull(@NieuweRegelNummer, @HuidigeRegelNummer);

    if (@HuidigeRegelNummer <> @NieuweRegelNummer) then
    begin
      // call Trace('update: huidige regel tijdelijk nummer geven (-' + string(@HuidigeRegelNummer) + ')');

      update tabBestelRegel
      set    BstRglNummer = -BstRglNummer
      where  (BstRglBstKopGid = @BstKopGid)
         and (BstRglGid = @BstRglGid);

      if (@HuidigeRegelNummer > @NieuweRegelNummer) then
      begin
        // call TraceBegin('Naar boven verplaatsen');

        // call Trace('update: bovenliggende regel(s) 1 regel omlaag schuiven');
        update tabBestelRegel
        set    BstRglNummer = BstRglNummer + 1
        where  (BstRglBstKopGid = @BstKopGid)
           and (BstRglNummer >= @NieuweRegelNummer)
           and (BstRglNummer <  @HuidigeRegelNummer)
        order by BstRglNummer desc;

        // call TraceEind('Naar boven verplaatsen');
      end;
      else
      begin
        // call TraceBegin('Naar beneden verplaatsen');

        // call Trace('update: onderliggende regel(s) 1 regel omhoog schuiven');
        update tabBestelRegel
        set    BstRglNummer = BstRglNummer - 1
        where  (BstRglBstKopGid = @BstKopGid)
           and (BstRglNummer >  @HuidigeRegelNummer)
           and (BstRglNummer <= @NieuweRegelNummer)
        order by BstRglNummer asc;

        // call TraceEind('Naar beneden verplaatsen');
      end;
      end if;

      // call Trace('update: oorspronkelijke regel nieuwe positie toekennen');
      update tabBestelRegel
      set    BstRglNummer = @NieuweRegelNummer
      where  (BstRglBstKopGid = @BstKopGid)
	     and (BstRglGid = @BstRglGid);
    end;
	end if;

  end;
  end if;

  // call TraceEind('BestelRegelpositieWijzigen(@NieuweRegelNummer=' + string(@NieuweRegelNummer) + ')');
end;


create or replace procedure BestelRegelsZoekenOmTeKoppelen(
 inout @SessieNr          integer,
 in    @LeverancierNawGid integer,  // NULL -> zoek niet afhankelijk van leverancier, anders alleen voor de gegeven leverancier
 in    @Regelsoort        integer,
 in    @Invoerveld        smallint,
 in    @ArtGid            integer,
 in    @ArtCodeLev        nchar(20),
 in    @Ean               nchar(20),
 in    @BstRglGid         integer,  // NULL -> normale aanroep. <>NULL -> geef in ieder geval deze regel terug
 in    @OokNietVerwerkt   integer,  // NULL -> Zelf uit vaste gegevens lezen; 0 -> Alleen in de verwerkte bestellingen zoeken en teruggeven; 1 -> in alle goedgekeurde en eventueel verwerkte bestellingen zoeken
 in    @Functie           integer,  // 0 -> MagazijnOntvangst, 1 -> Directe levering, 100 = beiden
 in    @BestelSoortMagazijn integer, //0 -> Bestellingen voor magazijn NIET meenemen; 1 = WEL meenemen
 in    @BestelSoortDebiteur integer) //0 -> Bestellingen voor debiteur NIET meenemen; 1 = WEL meenemen
begin
  // Mogelijke invoervelden
  declare @InvoerArtCode    smallint;
  declare @InvoerArtCodeLev smallint;
  declare @InvoerEan        smallint;

  declare @EanGevondenInEanTabel smallint; // 0 = Niet gezocht op EAN of in de EAN-tabel of zoekveld<>EAN, <> 0 = gevonden in de EAN-tabel (en niet in de inkoopeenheden)

  // Laatste toon-query keuze
  declare @ToonQuery smallint;
  declare @QueryObvInvoerveld                         smallint;
  declare @QueryObvArtikelCodeEnInvoerveld            smallint;
  declare @QueryObvInkoopEenheidEnArtCodeEnInvoerveld smallint;

  declare @AantalArtGevonden integer;
  declare local temporary table tmpArtikel(
    tmpArtGid           integer,
    tmpAldInkoopEenheid nchar(20)
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'BestelRegelsZoekenOmTeKoppelen(@SessieNr='+string(@SessieNr)+', @LeverancierNawGid='+string(@LeverancierNawGid)+', @Regelsoort='+string(@Regelsoort)+', @Invoerveld='+string(@Invoerveld)+', @ArtGid='+string(@ArtGid)+', @ArtCodeLev='+string(@ArtCodeLev)+', @Ean='+string(@Ean)+', @BstRglGid='+string(@BstRglGid)+', @OokNietVerwerkt='+string(@OokNietVerwerkt)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  // Mogelijke waarden van invoerveld
  set @InvoerArtCode    = 0;
  set @InvoerArtCodeLev = 1;
  set @InvoerEan        = 2;

  // Mogelijke queries
  set @QueryObvInvoerveld                         = 0;
  set @QueryObvArtikelCodeEnInvoerveld            = 1;
  set @QueryObvInkoopEenheidEnArtCodeEnInvoerveld = 2;

  // Defaults
  set @EanGevondenInEanTabel = 0;

  if @OokNietVerwerkt is null then
    // Als het volgens vaste gegevens niet toegestaan is om niet-verwerkte te koppelen, dan dus niet doen,
    // anders wel (dus als er een melding moet komen, dan ervan uitgaan dat het mag!)
    select if MagVastKoppelenNietVerwerkteBestelling = 1 then 0 else 1 endif into @OokNietVerwerkt from tabMagazijnOntvangstenVastegegevens;
  end if;

  //Zoek artikel obv. leverancier + invoerveld binnen de inkoopeenheden
  insert into tmpArtikel(tmpArtGid, tmpAldInkoopEenheid)
  select distinct ArtGid, AldInkoopEenheid
  from   tabArtikel
         inner join tabArtikelLeverancier on (ArtLevArtGid = ArtGid and ArtLevNawGid = isnull(@LeverancierNawGid, ArtLevNawGid))
         inner join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid)
         left outer join tabArtikelEan on (ArtEanGid = AldArtEanGid)
  where     (artsoort = @Regelsoort)
        and (   (@Invoerveld=@InvoerArtCode    and ArtGid = @ArtGid)
             or (@Invoerveld=@InvoerArtCodeLev and AldArtCodeBijLeverancier = @ArtCodeLev)
             or (@Invoerveld=@InvoerEan        and ArtEanCode = @Ean) // Ean-code binnen een inkoopeenheid
            )
        and ((ArtIsGeblokkeerdMagOntv = 0) or (@Functie = 1)); // Alleen de niet-geblokkeerde OF het is Directe levering


  select count(*) into @AantalArtGevonden from tmpArtikel;
  //call trace('@AantalArtGevonden='+string(@AantalArtGevonden));
  case @AantalArtGevonden
  when 0 then
    // Geen enkele gevonden, daarom als EAN, dan in EAN-tabel zoeken, anders blijft @AantalArtGevonden=0
    //delete tmpArtikel; Onnodig, want het resultaat was al 0 records
    if @Invoerveld=@InvoerEan then
      // Als EAN, dan in de EAN-tabel zoeken naar artikel, onafhankelijk van leverancier/inkoopeenheid
      // Dit kan maar 1 record opleveren!
      insert into tmpArtikel(tmpArtGid)
      select distinct ArtGid
      from   tabArtikel
             inner join tabArtikelEan on (ArtEanArtGid = ArtGid)
      where     (artsoort = @Regelsoort)
            and (ArtEanCode = @Ean)
            and ((ArtIsGeblokkeerdMagOntv = 0) or (@Functie = 1)); // Alleen de niet-geblokkeerde OF het is Directe levering
      select count(*) into @AantalArtGevonden from tmpArtikel;
      set @EanGevondenInEanTabel = @AantalArtGevonden;
    end if;
    if @AantalArtGevonden = 0 then
      // Nog steeds niets gevonden, dus in bestelregels alleen zoeken naar zoekveld
      set @ToonQuery = @QueryObvInvoerveld
    else
      // Nu wel een artikel met EAN gevonden, dus in bestelregels zoeken naar dit artikel (of zoekveld)
      set @ToonQuery = @QueryObvArtikelCodeEnInvoerveld
    end if;

  when 1 then
    //1 artikel/inkoopeenheid combinatie gevonden
    //bestaat er een niet volledig ontvangen bestelling met de eerder gevonden combinatie artikelcode+inkoopeenheid
    if exists(select first 1
              from tabBestelKop
                   inner join tabBestelRegel on (BstRglBstKopGid = BstKopGid)
                   inner join tabArtikel   on (ArtGid = BstRglArtGid)
                   inner join tmpArtikel   on (tmpAldInkoopEenheid = BstRglInkoopEenheid and tmpArtGid = ArtGid)
              where (BstKopNawGid = isnull(@LeverancierNawGid, BstKopNawGid))
                and (BstRglsoort = @Regelsoort)
                and (BstRglAantalNogTeOntvangenInVoorrEenh <> 0)
                and (   (@OokNietVerwerkt <> 0)
                     or (BstKopIsVerwerkt <> 0))
                and (BstKopIsGoedgekeurd <> 0)
             ) then
      // Ja, bestelregel met eerder gevonden artikelcode+inkoopeenheid gevonden, dus o.b.v. artikelcode+inkoopeenheid zoeken (of invoerveld)
      set @ToonQuery = @QueryObvInkoopEenheidEnArtCodeEnInvoerveld
    else
      // Nee, geen bestelregel met eerder gevonden artikelcode+inkoopeenheid gevonden, dus alleen zoeken naar art.code (of invoerveld)
      set @ToonQuery = @QueryObvArtikelCodeEnInvoerveld
    end if;
  else
    // Meer artcode+ink.eenh. gevonden, dus alleen bestelregels tonen met eerder gevonden artcode (of invoerveld)
    // Let op: dit gebeurt alleen als er eigenlijk iets fout zit in de stamgegevens (bijv. zelfde artikelcode lev. bij meer inkoopeenheden)
    set @ToonQuery = @QueryObvArtikelCodeEnInvoerveld
  end case;

  // Sessie aanmaken om eindresultaat in op te slaan
  if @SessieNr is null then
    call MaakUniekSessieNummer(@SessieNr);
  end if;
  delete tmpBestelregelKoppelen where tmpBrkSessieNr = @SessieNr;

  case
  when @ToonQuery = @QueryObvInvoerveld then
    // Toon alle bestelregels die voldoen aan invoerveld
    //call trace('@QueryObvInvoerveld');
    insert into tmpBestelregelKoppelen(tmpBrkSessieNr, tmpBrkBstRglGid)
    select distinct @SessieNr, BstRglGid
    from tabBestelRegel
         inner join tabBestelKop on (BstKopGid = BstRglBstKopGid)
         inner join tabArtikel   on (ArtGid = BstRglArtGid)
    where    (BstRglGid = isnull(@BstRglGid, BstRglGid-1))                             // De meegegeven regel OF
          or (    (artsoort = @Regelsoort)                                             // zelfde regelsoort
              and (BstKopNawGid = isnull(@LeverancierNawGid, BstKopNawGid))            // van dezelfde leverancier (of geen leverancier meegegeven)
              and (   (@Invoerveld = @InvoerArtCode    and ArtGid = @ArtGid)           // en waarvoor de selectie voldoet
                   or (@Invoerveld = @InvoerArtCodeLev and BstRglArtikelNummerLeverancier = @ArtCodeLev)
                   or (@Invoerveld = @InvoerEan        and BstRglEANcode = @Ean)
                  )
              and (BstRglAantalNogTeOntvangenInVoorrEenh <> 0)                   // en die nog niet volledig zijn ontvangen
              and (@OokNietVerwerkt <> 0 or BstKopIsVerwerkt <> 0)               // en waarvoor de bestelling al is verwerkt (of als aangegeven dat dat niet nodig is)
              and (BstKopIsGoedgekeurd <> 0)
              //ACW 30-11-2010 - Vervangen door 2 losse tests op afleveradres
              //and (   (@Functie = 0 /*MagOntv.*/ and ArtIsGeblokkeerdMagOntv = 0)
              //     or (@Functie = 1 /*Dir.Lev.*/ and BstKopAfleverAdres = 1 /*debiteur*/)
              //    )
              and (   (@BestelSoortMagazijn = 1 and BstKopAfleverAdres = 0)
                   or (@BestelSoortDebiteur = 1 and BstKopAfleverAdres = 1)
                  )

             )
  when @ToonQuery in (@QueryObvInvoerveld, @QueryObvArtikelCodeEnInvoerveld) then
    // Toon alle bestelregels van gevonden artikelen obv. artikel + alle bestelregels die voldoen aan invoerveld
    //call trace('@QueryObvArtikelCodeEnInvoerveld');
    if @ToonQuery = @QueryObvInvoerveld then
      // op basis van invoerveld, dus we willen niks met de eventueel gevonden artikelen te maken hebben
      delete tmpArtikel;
    end if;
    insert into tmpBestelregelKoppelen(tmpBrkSessieNr, tmpBrkBstRglGid)
    select distinct @SessieNr, BstRglGid
    from tabBestelRegel
         inner join tabBestelKop    on (BstKopGid = BstRglBstKopGid)
         inner join tabArtikel      on (ArtGid = BstRglArtGid)
         left outer join tmpArtikel on (tmpArtGid = BstRglArtGid)
    where    (BstRglGid = isnull(@BstRglGid, BstRglGid-1))                             // De meegegeven regel OF
          or(    (artsoort = @Regelsoort)                                              // zelfde artikelsoort
             and (BstRglSoort = @Regelsoort)                                           // zelfde regelsoort
             and (BstKopNawGid = isnull(@LeverancierNawGid, BstKopNawGid))             // van dezelfde leverancier (of geen leverancier meegegeven)
             and (   (   (tmpArtGid is not null)                                       // van een gevonden artikel
                      or (@ToonQuery = @QueryObvInvoerveld)                            //   of de gevonden artikelen zijn niet van toepassing
                     )
                  or (   (@Invoerveld = @InvoerArtCode    and ArtGid = @ArtGid)        // of waarvoor de selectie van bestelregels voldoet aan het zoekveld
                      or (@Invoerveld = @InvoerArtCodeLev and BstRglArtikelNummerLeverancier = @ArtCodeLev)
                      or (@Invoerveld = @InvoerEan        and BstRglEANcode = @Ean)
                     )
                 )
             and (BstRglAantalNogTeOntvangenInVoorrEenh <> 0)                   // en die nog niet volledig zijn ontvangen
             and (@OokNietVerwerkt <> 0 or BstKopIsVerwerkt <> 0)               // en waarvoor de bestelling al is verwerkt (of als aangegeven dat dat niet nodig is)
             and (BstKopIsGoedgekeurd <> 0)
             //ACW 30-11-2010 - Vervangen door 2 losse tests op afleveradres
             //and (   (@Functie = 0 /*MagOntv.*/ and ArtIsGeblokkeerdMagOntv = 0)
             //     or (@Functie = 1 /*Dir.Lev.*/ and BstKopAfleverAdres = 1 /*debiteur*/)
             //    )
             and (   (@BestelSoortMagazijn = 1 and BstKopAfleverAdres = 0)
                  or (@BestelSoortDebiteur = 1 and BstKopAfleverAdres = 1)
                 )
             )


  when @ToonQuery = @QueryObvInkoopEenheidEnArtCodeEnInvoerveld then
    // Toon alle bestelregels van gevonden artikelen obv. combinatie inkoopeenheid + alle bestelregels die voldoen aan invoerveld
    //call trace('@QueryObvInkoopEenheidEnArtCodeEnInvoerveld');
    insert into tmpBestelregelKoppelen(tmpBrkSessieNr, tmpBrkBstRglGid)
    select distinct @SessieNr, BstRglGid
    from tabBestelRegel
         inner join tabBestelKop    on (BstKopGid = BstRglBstKopGid)
         inner join tabArtikel      on (ArtGid = BstRglArtGid)
         // Zoek in artikelen naar juiste artikel om bestelregels me te vergelijken
         left outer join tmpArtikel on (   (@EanGevondenInEanTabel = 0 and tmpAldInkoopEenheid = BstRglInkoopEenheid and BstRglArtGid = tmpArtGid) // als @EanGevondenInEanTabel=0, dan NIET gevonden omdat niet gezocht hoefde te worden, of omdat EAN niet bestaat
                                        or (@EanGevondenInEanTabel <> 0 and BstRglArtGid = tmpArtGid))
    where     (BstRglGid = isnull(@BstRglGid, BstRglGid-1))                             // De meegegeven regel OF
           or (    (artsoort = @Regelsoort)                                             // zelfde artikelsoort
               and (BstRglSoort = @Regelsoort)                                          // zelfde bestelregelsoort
               and (BstKopNawGid = isnull(@LeverancierNawGid, BstKopNawGid))            // van dezelfde leverancier (of geen leverancier meegegeven)
               and (   (tmpAldInkoopEenheid is not null)                                // Artikel gevonden obv. artikelstam (zie outer join op tmpArtikel)
                    or (   (@Invoerveld = @InvoerArtCode    and ArtGid = @ArtGid)       // OF rechtstreeks obv. zoekveld in de bestellingen
                        or (@Invoerveld = @InvoerArtCodeLev and BstRglArtikelNummerLeverancier = @ArtCodeLev)
                        or (@Invoerveld = @InvoerEan        and BstRglEANcode = @Ean)
                       )
                   )
              and (BstRglAantalNogTeOntvangenInVoorrEenh <> 0)                   // en die nog niet volledig zijn ontvangen
              and (@OokNietVerwerkt <> 0 or BstKopIsVerwerkt <> 0)               // en waarvoor de bestelling al is verwerkt (of als aangegeven dat dat niet nodig is)
              and (BstKopIsGoedgekeurd <> 0)
              //ACW 30-11-2010 - Vervangen door 2 losse tests op afleveradres
              //and (   (@Functie = 0 /*MagOntv.*/ and ArtIsGeblokkeerdMagOntv = 0)
              //     or (@Functie = 1 /*Dir.Lev.*/ and BstKopAfleverAdres = 1 /*debiteur*/)
              //    )
              and (   (@BestelSoortMagazijn = 1 and BstKopAfleverAdres = 0)
                   or (@BestelSoortDebiteur = 1 and BstKopAfleverAdres = 1)
                  )
             )
  end case;

  //select count(*) into @ToonQuery from tmpBestelregelKoppelen where tmpBrkSessieNr = @SessieNr;
  //call trace('Aantal regels in tmp='+string(@ToonQuery));

  set @@ErrorTextProcedure = 'BestelRegelsZoekenOmTeKoppelen(@SessieNr='+string(@SessieNr)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;
//call BestelRegelsZoekenOmTeKoppelen(null, 46, 2, 0, 221, 'ArtCodeLev', 'Ean', null, 1)




if exists (select 1 from sys.sysProcedure where proc_name='BestelRegelsZoekenSessieOpschonen') then
  drop procedure BestelRegelsZoekenSessieOpschonen;
end if;

create procedure BestelRegelsZoekenSessieOpschonen(
  in @SessieNr integer,
  in @Unlock   integer)
begin
  set @@ErrorTextProcedure = 'BestelRegelsZoekenSessieOpschonen(@SessieNr='+string(@SessieNr)+')';
  //call TraceBegin(@@ErrorTextProcedure);
  // Het is nu een global temporary tabel, maar toch opschonen, zodat de sessie weer vrij komt.
  delete tmpBestelregelKoppelen where tmpBrkSessieNr = @SessieNr;
  if @Unlock <> 0 then
    call LockReleaseOnId(@@spid, @@LoginTime , 1, 'CreateSession', @SessieNr );
  end if;
  //call TraceEind(@@ErrorTextProcedure);

end;


// Wordt gebruikt t.b.v. betalingsopdrachten; vantui trigger BetalingRegel en BetalingVerzameld
create or replace function BetOpdrachtBepaalVerschilInValOsp(
  in @RksGid            integer,
  in @FactuurNummer     nchar(40),
  in @TeBetalenInValOsp numeric(15,2),
  in @BetRglGid         integer,
  in @BetVerzGid        integer)
returns numeric(15,2)
begin
  declare @Result numeric(15,2);

  set @@ErrorTextProcedure = 'BetOpdrachtBepaalVerschilInValOsp > RksGid='+ string(@RksGid)+', FactuurNummer='+@FactuurNummer+', TeBetalenInValOsp=' + string(@TeBetalenInValOsp)+', BetRglGid='+string(@BetRglGid)+', BetVerzGid='+string(@BetVerzGid);
  //call TraceBegin(@@ErrorTextProcedure);
  set @result = IsNull((select sum((OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - // (Factuurbedrag   -
                                   (OspBetaaldBedragDefinitief +OspBetaaldBedragVoorlopig)  - //  Betaald bedrag  -
                                   OspBedragOnderwegInValuta) *                               //  Bedrag onderweg) *
                                   if DefaultSoort = 6 /*Debiteur*/ then -1 else 1 endif      // (AlsDebiteur, dan -1; AlsCrediteur, dan 1) =
                        from   tabOpenstaandePost                                             // Openstaand bedrag
                               inner join tabRekeningschema on (RksGid = @RksGid)
                        where  OspFactuurNummer_Lengte = Length(@FactuurNummer)
                           and OspFactuurNummer = @FactuurNummer
                           and OspRksGid        = @RksGid
                           and OspBjGid = @@BjGid
                        group by DefaultSoort
                       ), 0.0) -
                @TeBetalenInValOsp -
                IsNull((select sum(BetRglTeBetalenInValOsp + (BetRglVerschilAfboeken * BetRglVerschilAfboekenBedragInValOsp))                                   // = Te betalen bedragen van alle betalingsregels in voorstellen
                        from   tabBetalingRegel
                        where  (@BetRglGid is null or BetRglGid <> @BetRglGid)                // Alle ANDERE voorstelregels
                           and (BetRglStatus        = 0)                                      // ALLEEN de voorstellen
                           and (BetRglRksGid        = @RksGid)                                // van dezelfde crediteur
                           and (BetRglFactuurNummer_Lengte = Length(@FactuurNummer))          // en dezelfde lengte
                           and (BetRglFactuurNummer = @FactuurNummer)                         // en dezelfde factuur
                           and (@BetRglGid is null or BetRglGid<> @BetRglGid)                 // maar NIET de regel die juist moet worden getest (Dat zit al in @TeBetalenInValOsp)
                       ), 0.0) -
                IsNull((select sum(BetVerzTeBetalenInValOsp + (BetVerzVerschilAfboeken * BetVerzVerschilAfboekenBedragInValOsp))                                  // = Te betalen bedragen in verzamelregels van deze cred. en deze factuur
                        from   tabBetalingVerzameld
                               inner join tabBetalingRegel on (BetRglGid = BetVerzBetRglGid)
                        where  (@betVerzGid is null or BetVerzGid <> @BetVerzGid)
                           and (BetRglRksGid  = @RksGid)                                      // van dezelfde crediteur
                           and (BetRglStatus         = 0)                                     // ALLEEN de voorstellen
                           and (BetVerzFactuurNummer_lengte = length(@FactuurNummer))         // en dezelfde factuur
                           and (BetVerzFactuurNummer = @FactuurNummer)                        // en dezelfde factuur
                           and (@BetVerzGid is null or BetVerzGid<> @BetVerzGid)              // maar NIET de regel die juist moet worden getest (Dat zit al in @TeBetalenInValOsp)
                       ), 0.0);
  set @@ErrorTextProcedure = 'BetOpdrachtBepaalVerschilInValOsp > ' + string(@result);
  //call TraceEind (@@ErrorTextProcedure);
  return(@result);

end;


//---------- Status van opdracht van OpdrachtAangemaakt op Voorstel zetten ----------

create or replace procedure BetOpdrAnnuleerOpdracht(in @BetKopId integer)
begin
  set @@ErrorTextProcedure = 'Begin BetOpdrAnnuleerOpdracht > @BetKopId = ' + string(@BetKopId);
  //call Trace(@@ErrorTextProcedure);

  update   tabBetalingRegel
  set      BetRglBatchNr           = 0,
           BetRglStatus            = 0, // = Voorstel
           BetRglE2E               = ''
  where    BetRglBetKopID = @BetKopID
           and BetRglStatus in (1, 2) // Alleen bij Opdracht of Geweigerd de bedragen terugzetten!
  order by BetRglBetaalDatum, BetRglValNummer, BetRglGid;

  //aangeven dat de posten verwerkt zijn
  update tabBetalingKop
  set BetKopStatus = 0, // = Voorstel aangemaakt
      BetKopHash              = null,
      BetKopHashAlgoritme     = null
  where  BetKopId = @BetKopId;

  set @@ErrorTextProcedure = 'Einde BetOpdrAnnuleerOpdracht';
  //call Trace(@@ErrorTextProcedure);
end;


//---------- Status van opdracht op OpdrachtAangemaakt zetten ----------

create or replace procedure BetOpdrVerwerkNaAanmakenBestand(in @BetKopId integer, in @AutomBoeken integer, in @BijwerkenBatchNrs integer)
begin
  declare @BatchNr      integer;
  declare @VorigeDatum  date;
  declare @VorigeValuta integer;
  declare @ValDgb       integer;

  set @@ErrorTextProcedure = 'Begin BetOpdrVerwerkNaAanmakenBestand > @BetKopId = ' + string(@BetKopId);
  //call Trace(@@ErrorTextProcedure);

  set @BatchNr = 0;

  select BetKopValnummerDgb into @ValDgb from tabBetalingKop where BetKopID = @BetKopId;

  for @BetOpdrRegels AS CURSOR_BetalingRegels CURSOR FOR
    select   BetRglGid                            @BetRglGid,
             BetRglIsVerzameld                    @BetRglIsVerzameld,
             BetRglRksGid                         @BetRglRksGid,
             BetRglBetaalDatum                    @BetRglBetaalDatum,
             BetRglValNummer                      @BetRglValNummer,
             BetRglFactuurNummer                  @BetRglFactuurNummer,
             BetRglTeBetalenInValOsp              @BetRglTeBetalenInValOsp,
             BetRglTeBetalenInValOsp + if BetRglVerschilAfboeken = 0 then 0 else BetRglVerschilAfboekenBedragInValOsp endif @BedragOnderweg
    from     tabBetalingRegel
    where    BetRglBetKopID = @BetKopID
             and BetRglStatus = 0 // Voorkom per ongeluk een verkeerde status nogmaals in de OSP te updaten
    order by BetRglBetaalDatum, BetRglValNummer, BetRglGid
  for update
  do
    if    (@VorigeDatum is null               )
       or (@BetRglBetaalDatum <> @VorigeDatum )
       or (@BetRglValNummer   <> @VorigeValuta) then
      // Volgende batch!
      set @BatchNr      = @BatchNr + 1;        // Bathcnummer verhogen
      set @VorigeDatum  = @BetRglBetaalDatum;  // i.v.m. zoeken naar volgende batch
      set @VorigeValuta = @BetRglValNummer;
    end if;

    // Update deze regel (Bedrag onderweg, Status, Batchnummer)
    update tabBetalingRegel
    set    BetRglBatchNr    = if @BijwerkenBatchNrs = 1 then @BatchNr else BetRglBatchNr endif,
           BetRglStatus     = 1 // = Opdracht
    where  current of CURSOR_BetalingRegels;
  end for;

  //aangeven dat de posten verwerkt zijn
  update tabBetalingKop
  set    BetKopStatus = 1, // = Opdracht aangemaakt
         BetKopIsAutomBoeken = @AutomBoeken
  where  BetKopId = @BetKopId;

  set @@ErrorTextProcedure = 'Einde BetOpdrVerwerkNaAanmakenBestand';
  //call Trace(@@ErrorTextProcedure);
end;

//----------------------------------------------------------------
//---------- Omschrijving van verzamelregel samenstellen ---------
//----------------------------------------------------------------
create or replace procedure BetRglVerzamelOmschrijving(in @BetRglGid integer, in @Crediteur nchar(28),
                                            in @OmsUwRef smallint,
                                            in @OmsUwRefTekst nchar(10), in @OmsOspOms smallint,
                                            in @OmsOnzeRef smallint, in @OmsOnzeRefTekst nchar(10),
                                            out @Omschrijving nchar(250))
begin
  declare @HuidigeBetVerzGid    integer;
  declare @VorigeBetVerzGid     integer;
  declare @OnsDebiteurNummer    nchar(20);
  declare @OspRksGid            integer;
  declare @FactuurNummer        nchar(40);
  declare @OspKenmerk           nchar(140);
  declare @BetVerzUwRef         nchar(250);
  declare @BetVerzOnzeRef       nchar(250);

  set @@ErrorTextProcedure = 'BetRglVerzamelOmschrijving > @BetRglGid='+string(@BetRglGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //ophalen OnsDebiteruNummer
  select NawOnsDebiteurNummer
  into   @OnsDebiteurNummer
  from   tabNawFile inner join tabNaw on (NawGid = NawFilNawGid)
  where  NawFilNummer = @Crediteur and NawFilFonId='C';

  // vul begin van onze en uw referentie
  set @BetVerzUwRef    = '';
  set @BetVerzOnzeRef  = '';
  if (@OmsOnzeRef = 1) then
    if (Trim(@OmsOnzeRefTekst) <> '') then
      set @BetVerzOnzeRef = Trim(@OmsOnzeReftekst) + ' ';
    end if;
    set @BetVerzOnzeRef = @BetVerzOnzeRef + Trim(@Crediteur);
  end if;

  // doorloop de  verzamelregels
  set @VorigeBetVerzGid = null;
  VerzamelingAflopen:
  loop
    set @HuidigeBetVerzGid = null;
    select min(BetVerzGid) into @HuidigeBetVerzGid
    from   tabBetalingVerzameld
    where  (BetVerzBetRglGid = @BetRglGid)
      and ((@VorigeBetVerzGid is null) or (BetVerzGid > @VorigeBetVerzGid));

    if @HuidigeBetVerzGid is null then
      leave VerzamelingAflopen;
    end if;

    set @OspRksGid      = null;
    set @FactuurNummer  = null;
    set @OspKenmerk     = null;

    // Regel gevonden : haal de benodigde gegevens op
    select BetRglRksGid, BetVerzFactuurNummer, OspBetalingsKenmerk
    into   @OspRksGid, @FactuurNummer, @OspKenmerk
    from   tabBetalingVerzameld inner Join tabBetalingRegel on (BetRglGid = BetVerzBetRglGid)
                                left outer join tabopenstaandepost
                                             on ((OspRksGid = BetRglRksGid)
                                            and  (OspFactuurNummer_Lengte=length(BetVerzFactuurNummer))
                                            and  (OspFactuurnummer=BetVerzFactuurNummer)
                                            and  (OspBjGid = @@BJGid))
    where  (BetVerzGid = @HuidigeBetVerzGid);

    //omschrijving verzameling bijhouden
    if (Trim(@OspKenmerk)<>'') and (@OmsUwRef = 1) then
      set @OspKenmerk = Trim(@OspKenmerk);
      if length(@OnsDebiteurNummer) <> 0 then
        if left(@BetVerzUwRef, length(@OnsDebiteurNummer)) = @OnsDebiteurNummer then
          set @OspKenmerk = substr(@OspKenmerk, length(@OnsDebiteurNummer)+1, length(@OspKenmerk))
        end if;
      end if;
      set @BetVerzUwRef = @BetVerzUwRef + @OspKenmerk + ' ';
    end if;
    if (@OmsOnzeRef = 1) then
      set @BetVerzOnzeRef = @BetVerzOnzeRef + ' ' + Trim(@FactuurNummer);
    end if;

    // zorgen dat de volgende regel gevonden kan worden
    set @VorigeBetVerzGid = @HuidigeBetVerzGid;
  end loop VerzamelingAflopen;

  if (Trim(@OmsUwReftekst)<>'') and (@OmsUwRef = 1) and (trim(@BetVerzUwRef)<>'') then
    set @BetVerzUwRef = Trim(@OmsUwReftekst) + ' ' + trim(@BetVerzUwRef);
  end if;


  // plak uw referentie en onze referentie aan elkander
  set @Omschrijving = @BetVerzUwRef;
  if Trim(@BetVerzOnzeRef) <> '' then
    if @Omschrijving <> '' then
      set @Omschrijving = @Omschrijving + char(13)+char(10);
    end if;
    set @Omschrijving = @Omschrijving + Trim(@BetVerzOnzeRef);
  end if;

  set @@ErrorTextProcedure = 'BetRglVerzamelOmschrijving';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BetVerzAanmaken(in @BetKopId integer, in @NawNummer nchar(28), in @ValutaNummer integer, in @OmsUwRef smallint,
                                            in @OmsUwRefTekst nchar(10), in @OmsOspOms smallint,
                                            in @OmsOnzeRef smallint, in @OmsOnzeRefTekst nchar(10),
                                            in @BOBchequeVerzenden nchar(1), in @BOBsoortCrossen nchar(1), out @IsBetNogAanwezig smallint)
begin
  declare @IsolationLevel   smallint;
  declare @BetKopBetForId   integer;
  declare @BetVerzBetRglGid integer;
  declare @BetVerzOms       nchar(250);
  declare @BankGiroRek      nchar(40);
  declare @RksGid           integer;
  declare @HuidigeNawNummer nchar(28);
  declare @VorigeNawNummer  nchar(28);
  declare @NawRekGid        integer;
  declare @BankIsVoorBetaling  smallInt;
  declare @IsBetalingInSEPAgebied smallint;
  // Codelijsten
  declare @BOBbankBIC             nchar(11);
  declare @BOBbankNaam            nchar(35);
  declare @BOBbankPlaats          nchar(35);
  declare @BOBsoortOpdracht       nchar(1);
  declare @BOBsoortUitvoering     nchar(1);
  declare @BOBkostenBinnenland    nchar(1);
  declare @BOBkostenCorrespondent nchar(1);
  declare @BOBinstr1              nchar(2);
  declare @BOBinstr2              nchar(2);
  declare @BOBinstr3              nchar(2);
  declare @BOBinstr4              nchar(2);

  set @@ErrorTextProcedure = 'BetVerzAanmaken > @BetKopId='+string(@BetKopId)+', @NawNummer='+string(@NawNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsBetNogAanwezig = 0;
  select 1, BetKopBetForId into @IsBetNogAanwezig, @BetKopBetForId from tabBetalingKop where BetKopId = @BetKopId;
  if @IsBetNogAanwezig <> 0 then
    set @IsolationLevel = @@Isolation;
    if @@Isolation < 1 then
      set temporary option Isolation_Level = 1;
    end if;
    set @BankGiroRek = '';

    //--- @NawNummer = null ---> voor alle NAWs verzameling aanmaken
    if IsNull(@NawNummer, '') = '' then
      set @VorigeNawNummer = null;

      // doorloop alle NAWs
      NAWsAflopen:
      loop
        // bepaal volgende verzamelregel
        set @HuidigeNawNummer = null;
        select min(RksInvoer) into @HuidigeNawNummer
        from   tabBetalingRegel inner join tabRekeningschema on (RksGid = BetRglRksGid)
        where (BetRglBetKopId = @BetKopId)
          and (BetRglIsVerzameld <> 1)
          and ((@VorigeNawNummer is null) or (RksInvoer > @VorigeNawNummer));

        if @HuidigeNawNummer is null then
          leave NAWsAflopen;
        end if;

        // NAW gevonden : roep eigen proc weer aan, maar dan MET betreffende BetRglGid
        call BetVerzAanmaken(@BetKopId, @HuidigeNawNummer, @ValutaNummer, @OmsUwRef, @OmsUwRefTekst, @OmsOspOms,@OmsOnzeRef, @OmsOnzeRefTekst, @BOBchequeVerzenden, @BOBsoortCrossen, @IsBetNogAanwezig);

        set @VorigeNawNummer = @HuidigeNawNummer;

      end loop NAWsAflopen;

    else
      // verzamelopdracht maken voor meegegeven NAW

      // Bepaal of het SEPA-betaling is of niet
      // Wel, indien formaatgroep = PAIN
      select if BetForId in (5) or (BetForFormaat like '%PAIN%') then 1 else 0 endif into @IsBetalingInSEPAgebied from tabBetalingFormaten where BetForId = @BetKopBetForId;


      // Ophalen RksGid
      select RksGid into @RksGid from tabRekeningschema where RksInvoer = @NawNummer;

      // Lus voor elke valuta in de betalingsopdracht voor deze NAW
      for @Cursor AS CURSOR_Valuta CURSOR FOR
        select distinct BetRglValNummer @ValNummer
        from   tabBetalingRegel
        where  BetRglRksGid = @RksGid and BetRglIsVerzameld = 0 and BetRglBetKopId = @BetKopId and (@ValutaNummer is null or @ValNummer = @ValutaNummer)
        order by BetRglValNummer
      for read only
      do
        // of er voor deze credituer+valuta ale een verzamlregel bestaat zoja voeg de regels dan hier aan toe
        set @BetVerzBetRglGid = null;
        select BetRglGid into @BetVerzBetRglGid
        from   tabBetalingRegel
        where  (BetRglBetKopId = @BetKopId) and (BetRglIsVerzameld=1) and (BetRglRksGid=@RksGid) and (BetRglValNummer = @ValNummer);

        //call Trace('@BetVerzBetRglGid ='+string(@BetVerzBetRglGid));

        if @BetVerzBetRglGid is Null then
          //call Trace('@BetVerzBetRglGid is null !    nog geen verzamelregel --> Voeg nieuew toe');

          //ophalen rekening tbv betalingen
          call BetvrstlBepaalBankGiroRek(@NawNummer, @IsBetalingInSEPAgebied, @BankGiroRek, @BankIsVoorBetaling);

          // Bankgegevens van de NAW opvragen
          select NawRekGid into @NawRekGid
          from   tabNawFile
                 left outer join tabNawRekening on (NawRekNawGid = NawFilNawGid and NawRekSoort like '%B%') // and NawRekIsBuitenland <> 0)
          where  NawFilRksGid = @RksGid and NawFilFonID in ('C', 'D');

          // Defaults (codelijsten) opnieuw uitlezen en meenemen in de nieuwe regel
          select NawRekBankBIC, NawRekBankNaam, NawRekBankPlaats, NawRekSoortOpdracht, NawRekSoortUitvoering, NawRekKostenBinnen,   NawRekKostenCorrespondent, NawRekBobInstr1, NawRekBobInstr2, NawRekBobInstr3, NawRekBobInstr4
          into   @BOBbankBIC,   @BOBbankNaam,   @BOBbankPlaats,   @BOBsoortOpdracht,   @BOBsoortUitvoering,   @BOBkostenBinnenland, @BOBkostenCorrespondent,   @BOBinstr1,      @BOBinstr2,      @BOBinstr3,      @BOBinstr4
          from   tabNawRekening
          where  NawRekGid = @NawRekGid;

          // voeg verzamelregel toe aan betalingsvoorstel
          insert into tabBetalingregel(BetrglBetKopId, BetrglBankrekening, BetRglBetaalDatum,  BetRglFactuurNummer, BetRglRksGid, BetRglValNummer, BetRglTeBetalen, BetRglTeBetalenInValDgb, BetRglIsVerzameld, BetRglVerschilAfboekenBedragInValOsp, BetRglVerschilAfboeken, BetRglBOBbankBIC, BetRglBOBbankNaam, BetRglBOBbankPlaats, BetRglBOBsoortOpdracht, BetRglBOBsoortUitvoering, BetRglBOBchequeVerzenden, BetRglBOBsoortCrossen, BetRglBOBkostenBinnen, BetRglBOBkostenCorrespondent, BetRglBOBinstr1, BetRglBOBinstr2, BetRglBOBinstr3, BetRglBOBinstr4)
                      values          (@BetKopId,      @BankGiroRek,       @@VerwerkingsDatum, '[VERZAMEL]',        @RksGid     , @Valnummer,      0,               0,                       1,                 0,                                    0,                      @BOBbankBIC,      @BOBbankNaam,      @BOBbankPlaats,      @BOBsoortOpdracht,      @BOBsoortUitvoering,      @BOBchequeVerzenden,      @BOBsoortCrossen,      @BOBkostenBinnenland,  @BOBkostenCorrespondent,      @BOBinstr1,      @BOBinstr2,      @BOBinstr3,      @BOBinstr4);
          set @BetVerzBetRglGid = @@Identity;
        end if;

        // zet alle losse regels uit voorstel naar verzamelregels
        set @@IgnoreProgressAdd = isnull(@@IgnoreProgressAdd,0) + 1; // Zodat het verschilbedrag niet nogmaals wordt berekend!
        // ACW 11-10-2005: bug 18973: Het bedrag in valuta van OSP wordt niet berekend. Dat is goed, maar het werd niet uit de regel overgenomen; nu wel
        insert into tabBetalingVerzameld(BetVerzBetRglGid,  BetVerzBankrekening, BetVerzBetaalDatum, BetVerzOms, BetVerzFactuurNummer, BetVerzTeBetalen, BetVerzTeBetalenInValOsp, BetVerzVerschilAfboeken, BetVerzVerschilAfboekenBedragInValOsp, BetVerzBetKenmerk, BetVerzGefiatteerdDoor, BetVerzGefiatteerdOp)
        select                           @BetVerzBetRglGid, BetRglBankrekening,  BetRglBetaalDatum,  BetRglOms,  BetRglFactuurNummer,  BetRglTeBetalen,  BetRglTeBetalenInValOsp,  BetRglVerschilAfboeken,  BetRglVerschilAfboekenBedragInValOsp,  BetRglBetKenmerk, BetRglGefiatteerdDoor, BetRglGefiatteerdOp
        from tabBetalingRegel
        where (BetrglBetKopId = @BetKopId) and (BetRglIsVerzameld <> 1) and (BetRglRksGid=@RksGid) and (BetRglValNummer = @ValNummer);
        set @@IgnoreProgressAdd = @@IgnoreProgressAdd - 1;
        // verwijderd de oude losse regels
        delete
        from tabBetalingRegel
        where (BetrglBetKopId = @BetKopId)
          and (BetRglIsVerzameld <> 1) and (BetRglRksGid=@RksGid) and (BetRglValNummer = @ValNummer);

        // bepaal betalingskede omschrijving van de verzamelregel
        call BetRglVerzamelOmschrijving(@BetVerzBetRglGid, @NawNummer, @OmsUwRef, @OmsUwRefTekst,
                                        @OmsOspOms, @OmsOnzeRef, @OmsOnzeRefTekst, @BetVerzOms);

        // bijwerken verzamelregel
        select string(min(BetVerzBetaalDatum)) into @@ErrorTextProcedure
        from   tabBetalingVerzameld
        where  BetVerzBetRglGid=@BetVerzBetRglGid;
        update tabBetalingRegel
        set    BetRglBetaalDatum = isnull((select min(BetVerzBetaalDatum)
                                          from   tabBetalingVerzameld
                                          where  BetVerzBetRglGid=@BetVerzBetRglGid)
                                          , @@VerwerkingsDatum),
               BetRglOms         = @BetVerzOms,
               BetRglBetKenmerk  = '',
               BetRglIsVerzameld = 1,
               BetRglTeBetalen   = IsNull((select sum(BetVerzTeBetalen)
                                           from   tabBetalingVerzameld
                                           where  (BetVerzBetRglGid = @BetVerzBetRglGid)), 0),
							 BetRglGefiatteerdDoor = ''
        where  BetRglGid = @BetVerzBetRglGid;
      end for; // Valutalus
    end if;

    execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;
  end if;

  set @@ErrorTextProcedure = 'BetVerzAanmaken';
  //call TraceEind(@@ErrorTextProcedure);

end;


//------------------------------------------------------------------------
//---------- Verzamelopdracht uitsplitsen naar lossen betalingen ---------
//------------------------------------------------------------------------
create or replace procedure BetVerzUitsplitsen(in @BetKopId integer, in @BetRglGid integer, out @Gelukt integer, out @IsBetNogAanwezig smallint)
begin
  declare @IsolationLevel   smallint;
  declare @HuidigeBetRglGid integer;
  declare @VorigeBetRglGid  integer;
  declare @TempGelukt       integer;

  set @@ErrorTextProcedure = 'BetVerzUitsplitsen > @BetRglGid='+string(@BetRglGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsBetNogAanwezig = 0;
  select 1 into @IsBetNogAanwezig from tabBetalingKop where BetKopId = @BetKopId;
  if @IsBetNogAanwezig <> 0 then

    set @IsolationLevel = @@Isolation;
    if @@Isolation < 1 then
      set temporary option Isolation_Level = 1;
    end if;
    set @Gelukt = 1;

    // @BetVerzGid = null ---> alle verzamelingen uitsplitsen
    if @BetRglGid is null then
      set @VorigeBetRglGid = null;

      // doorloop alle verzamelregels
      VerzamelingenAflopen:
      loop
        // bepaal volgende verzamelregel
        set @HuidigeBetRglGid = null;
        select min(BetRglGid) into @HuidigeBetRglGid
        from   tabBetalingRegel
        where  (BetRglBetKopId = @BetKopId)
          and  (BetRglIsVerzameld = 1)
          and ((@VorigeBetRglGid is null) or (BetRglGid > @VorigeBetRglGid));
        if @HuidigeBetRglGid is null then
          leave VerzamelingenAflopen;
        end if;

        // Verzamelregel gevonden : roep eigen proc weer aan, maar dan MET betreffende BetRglGid
        call BetVerzUitsplitsen(@BetKopId, @HuidigeBetRglGid, @TempGelukt);

        // Zet @Gelukt op 0 als een van de regels niet kon worden uitgesplits!
        if @TempGelukt = 0 then
          set @Gelukt = 0;
        end if;

        set @VorigeBetRglGid = @HuidigeBetRglGid;
      end loop VerzamelingenAflopen;

    else
      if (select min(BetVerzTeBetalen) from tabBetalingVerzameld where (BetVerzBetRglGid = @BetRglGid)) < 0 then
         //call Trace('credititnotas is verzameling --> uitsplitsen niet mogelijjk');
         set @Gelukt = 0;
      else
        //call Trace('Uitsplitsen regels');
        set @@IgnoreProgressAdd = isnull(@@IgnoreProgressAdd,0) + 1; // Zodat het verschilbedrag niet nogmaals wordt berekend!
        // ACW 11-10-2005: bug 18973: Het bedrag in valuta van OSP wordt niet berekend. Dat is goed, maar het werd niet uit de verz.regel overgenomen; nu wel
        insert into tabBetalingregel with auto name
        select
          BetRglBetKopId,
          BetVerzBankrekening                   BetrglBankrekening,
          BetVerzBetaalDatum                    BetRglBetaalDatum,
          BetVerzOms                            BetRglOms,
          BetRglRksGid,
          BetVerzFactuurNummer                  BetRglFactuurNummer,
          BetRglValNummer,
          BetVerzTeBetalen                      BetRglTeBetalen,
          BetVerzTeBetalenInValOsp              BetRglTeBetalenInValOsp,
          BetVerzVerschilAfboeken               BetRglVerschilAfboeken,
          BetVerzVerschilAfboekenBedragInValOsp BetRglVerschilAfboekenBedragInValOsp,
          BetVerzBetKenmerk                     BetRglBetKenmerk,
          0                                     BetRglIsVerzameld,
          BetRglBOBbankBIC,
          BetRglBOBbankNaam,
          BetRglBOBbankPlaats,
          BetRglBOBchequeVerzenden,
          BetRglBOBinstr1,
          BetRglBOBinstr2,
          BetRglBOBinstr3,
          BetRglBOBinstr4,
          BetRglBOBkostenBinnen,
          BetRglBOBkostenCorrespondent,
          BetRglBOBsoortCrossen,
          BetRglBOBsoortOpdracht,
          BetRglBOBsoortUitvoering,
          BetVerzGefiatteerdDoor                BetRglGefiatteerdDoor,
          BetVerzGefiatteerdOp                  BetRglGefiatteerdOp
        from tabBetalingRegel inner join tabBetalingVerzameld on (BetRglGid = BetVerzBetRglGid)
        where (BetRglGid = @BetRglGid);
        set @@IgnoreProgressAdd = @@IgnoreProgressAdd - 1;
        // verwijderd de oude verzamel regel
        delete from tabBetalingRegel where (BetRglGid = @BetRglGid);
      end if;
    end if;

    execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;
  end if;

  set @@ErrorTextProcedure = 'BetVerzUitsplitsen';
  //call TraceEind(@@ErrorTextProcedure);

end;


//------------------------------------------------------
//---------- Regel verwijderen uit verzameling ---------
//------------------------------------------------------

create or replace procedure BetVerzVerwijderenOsp(in @BjGid integer, in @BetVerzBetRglGid integer,
                                                  in @BetVerzGid integer, out @Resultaat integer)
begin
  // @Resultaat ---> 0 = gelukt
  //                 1 = bedrag zou negatief worden             Mag nu wel !!!
  //                 2 = Verzamelregel is verwijderd
  declare @IsolationLevel smallint;
  declare @Pernr        integer;
  declare @RksGid       integer;
  declare @Totaal       numeric(15,2);
  declare @TeBetalen    numeric(15,2);
  declare @Onderweg     numeric(15,2);
  declare @FactuurNr    nchar(40);
  declare @BetKopValNr  integer;

  set @@ErrorTextProcedure = 'BetVerzVerwijderenOsp > @BetVerzBetRglGid='+string(@BetVerzBetRglGid)+', @BetVerzGid='+string(@BetVerzGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;
  set @Resultaat         = 0;

  //--- kijken wat er tot nu toe betaald moet worden
  select BetRglTeBetalen into @Totaal from tabBetalingRegel where BetRglGid = @BetVerzBetRglGid;
  if @Totaal is null then
    set @Resultaat = 2;             // verzamelregel is verdwenen
  else
    //call Trace('@Totaal(met)='+string(@Totaal));

    select PeriodeBepalen(@BjGid, @@VerwerkingsDatum) into @Pernr; // voor omrekenen

    // haal gegevens van regel op
    select BetVerzTeBetalen, BetVerzBedragOnderweg, BetRglRksGid, BetVerzFactuurNummer, BetKopValNummer
    into   @TeBetalen, @Onderweg, @RksGid, @FactuurNr, @BetKopValNr
    from   tabBetalingVerzameld inner join tabBetalingRegel on (BetRglGid = BetVerzBetRglGid) inner join tabBetalingKop on (BetKopId = BetRglBetKopId)
    where  (BetVerzGid = @BetVerzGid);

    //--- kijken wat er nu betaald zou moeten worden
    set @Totaal = @Totaal - IsNull(@TeBetalen, 0);
    //call Trace('@Totaal(zonder)='+string(@Totaal));

      // bijwerken bedrag onderweg in OSP
      if @Onderweg <> 0 then
        call OspBijwerkenBedragOnderweg(@BjGid, @PerNr, -@Onderweg, @RksGid, @FactuurNr, @BetKopValNr);
      end if;
      // gooi de regel weg
      delete from tabBetalingVerzameld where BetVerzGid = @BetVerzGid;
      // Was dit de laatste regel uit de verzamelregelt ?  Zo ja, verwijdere dan de verzamelregel
      if (select count (*) from tabBetalingVerzameld where BetVerzBetRglGid = @BetVerzBetRglGid) = 0 then
        delete tabBetalingRegel where BetRglGid = @BetVerzBetRglGid;
      end if;
  end if;

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  set @@ErrorTextProcedure = 'BetVerzVerwijderenOsp > @Resultaat='+string(@Resultaat);
  //call TraceBegin(@@ErrorTextProcedure);

end;


//--- aanmaken van betalingsvoorstel in een valuta (1 voorstel voor alle osps binnen de selectie)
create or replace procedure BetvrstlAanmakenInValuta(
 inout @SessieNr            integer, // Indien niet gevuld, dan aanmaken en teruggeven
 in @HeeftRechtcopf         smallint,
 in @BankRekening           nchar(40),
 in @VasteOms               nchar(32),
 in @VolgNr                 integer,
 in @IsAanvullenAlsBestaat  integer, // 0 = NIET aanvullen, maar resultaat=1 teruggeven; 1 = WEL aanvullen; Aanvullen gaat NIET goed omdat de combinatie Crediteur+factuur maar 1x mag voorkomen
 in @IsBuitenland           smallint, // Indien 0, dan kan het een binnenlandse betaling (Clieop) OF een SEPA-betaling (PAIN) zijn
 in @VulKenmerk             integer,
 in @OmsUwRef               smallint,
 in @OmsUwRefTekst          nchar(10),
 in @OmsOspOms              smallint,
 in @OmsOnzeRef             smallint,
 in @OmsOnzeRefTekst        nchar(10),
 in @BjGid                  integer,
 in @VanNAW           			nchar(10),
 in @TotNAW          			 	nchar(10),
 in @VanFactuurdatum        date,
 in @TotFactuurdatum        date,
 in @VanVervaldatum         date,
 in @TotVervaldatum         date,
 in @VanFactuurnummer       nchar(40),
 in @TotFactuurnummer       nchar(40),
 in @VanValCode             nchar(3),
 in @TotValCode             nchar(3),
 in @MetCreditnotas         smallint,
 in @IsValNummerVanOsp      smallint,
 in @ValNummerVoorstel      integer,
 in @VerzamelenPerCrediteur smallint,
 in @MetBetaaldatum         smallint,
 in @Betaaldatum            date,
 in @MetVooruitbetalingen   smallint,
 in @VoorlopigeFacturen     smallInt,
 in @CrediteurenSelecteren  integer, // 0 = Alleen MET bankrekening t.b.v. betalingen, 1 = alleen ZONDER bankrekening t.b.v. betalingen, 2 = bankrekening maakt niet uit
 in @MetTeveelBetalingen    integer, // Alleen relevant voor Debiteuren.
 in @DgbGid                 integer,
 in @Formaat                smallint,
 in @IsSepaBetaling         smallint, // 0, dan is de eigen rekening niet bedoeld als SEPA-rekening; 1, dan is de eigen rekening bedoeld voor SEPA, maar als @IsBuitenland=1, dan is het toch een overige betaling! Hiertoe variabele @_IsBetalingInSEPAgebied gebruikt
 in @BOBchequeVerzenden     nchar(1),
 in @BOBsoortCrossen        nchar(1),
 out @Resultaat             integer,
 out @RegelsInserted        integer
)
begin
//--- Let op: In deze stored proc komt vaak de term crediteur terug. Ooit werden in betalingsvoorstellen alleen de notas van crediteuren opgenomen.
//--- Inmiddels kunnen ook de credit-notas van debiteuren worden opgenomen in betalingsvoorstellen. Echter de namen van variabelen zijn niet aangepast.

  //Constanten
  declare _qcNEE smallint = 0;
  declare _qcJA smallint = 1;

  // Hulpvelden
  declare @_IsolationLevel smallint;
  declare @_PerNr integer; // Voor valutaomrekeningen
  declare @_ValNummerEur integer;
  declare @_ValNummerDgb integer;
  declare @_IsBetalingInSEPAgebied smallint;
  declare @_IsCrediteur smallint; // Geeft aan of we hier facturen van debiteuren of crediteuren aan het toevoegen zijn

  //MR 10-okt-2013: Opvullen tot 40 met spaties. Dit is gedaan omdat de zoek versneld word (Project Verlengen factuur- en NAW-nummers)
  set @VanFactuurnummer = Repeat(' ',40-length(@VanFactuurnummer))+Trim(@VanFactuurnummer);
  set @TotFactuurnummer = Repeat(' ',40-length(@TotFactuurnummer))+Trim(@TotFactuurnummer);

  //  @Resultaat ---> 0 = alles is goed gegaan
  //                  1 = Volgnummer komt al voor
  //                  2 = geen posten binnen selectie
  //                  4 = Totaal verzamelregels > grensbedrag EU -> Het is dus wel goed gegaan, maar dit wordt een opmerking
  //                  5 = Overige

  set @@ErrorTextProcedure = 'BetvrstlAanmakenInValuta>';
    //call traceBegin(@@ErrorTextProcedure);
    //call traceBegin('Selectie : ');
    //call trace('@VanNAW='+string(@VanNAW)+', @TotNAW='+string(@TotNAW));
    //call trace('@VanFactuurDatum='+string(@VanFactuurDatum)+', @TotFactuurDatum='+string(@TotFactuurDatum));
    //call trace('@VanVervalDatum='+string(@VanVervalDatum)+', @TotVervalDatum='+string(@TotVervalDatum));
    //call trace('@VanFactuurnummer='+string(@VanFactuurnummer)+', @TotFactuurnummer='+string(@TotFactuurnummer));
    //call trace('@VanValCode='+string(@VanValCode)+', @TotValCode='+string(@TotValCode));
    //call trace('@MetCreditnotas='+string(@MetCreditnotas));
    //call traceEind('Selectie');
    //call trace('@BjGid='+string(@BjGid)+', @ValNummerVoorstel='+string(@ValNummerVoorstel)+', @Verz.p.cred='+string(@VerzamelenPerCrediteur));
    //call trace('@MetBetaalDatum='+string(@MetBetaalDatum)+', @BetaalDatum='+string(@Betaaldatum));
    //call trace('@OmsOnzeRefTekst='+@OmsOnzeRefTekst);

  set @Resultaat = 0; // alles is goed gegaan

  // Geen sessienummer meegegeven, dan alsnog aanmaken, maar dit moet echt nog niet bestaan!
  if @SessieNr is null then
    begin
      declare @Pogingen smallint =  0;

      set @Resultaat = 1;
      MaakSessieNr:
      loop
        call BetVrstlAanmakenSessieNr(@SessieNr);
        call LockSetOnId(null, null, 1 /*Exclusive lock*/, 'tabBetalingsVoorstelCreate', String(@SessieNr), @Resultaat, 1 /*Automatisch opruimen komt dan in TMainBG.CheckLocksWithoutConnection*/);
        if @Pogingen > 10 or @Resultaat = 0 then
          leave MaakSessieNr;
        end if;
        set @Pogingen = @Pogingen + 1;
      end loop MaakSessieNr;
    end;
  end if;

  set @_PerNr = 1;
  set @RegelsInserted = 0;

  if @SessieNr is null or @Resultaat <> 0 then
    set @resultaat = 5; // Overige fout
  end if;

  // +++ Hulpvariabelen vullen +++

  // De proceduer wordt maximaal 2x aangeroepen: 1x voor crediteuren en 1x voor debiteuren.
  // Daarom moeten we weten of het de eerste of volgende keer is. dat wordt gedaan m.b.v. het soort NAW (veld BvcIsCrediteur)
	//Geen naw opgegeven, dan kunnen we @_IsCrediteur niet berekenen.
	if (@VanNAW = '') or (@TotNAW = '') then
		set @resultaat = 5;
	end if;

  set @_IsCrediteur = isnull((select first 0 /*debiteur*/
                             from  tabParagraaf
                                   inner join tabBalansCodeDetail on BlGid = ParBlGid
                             where ParSoort = 10 /*Debiteuren*/ and
                                   Paragraaf = left(@VanNAW, 2)
                            ), 1 /*Geen debiteur, dus crediteur*/);
    //call trace('We gaan @_IsCrediteur='+string(@_IsCrediteur)+' toevoegen!');

  //--- doorgaan indien ruimte
  select PeriodeBepalen(@BjGid, @@VerwerkingsDatum) into @_PerNr; // voor omrekenen

  // Eurovaluta bepalen
  select first ValNummer into @_ValNummerEur from tabValuta where IsEuro = _qcJA;

  //Alleen als SEPA bestempelen als het binnenland is, DUS binnen SEPA-gebied
  set @_IsBetalingInSEPAgebied = if @IsBuitenland = _qcNEE then @IsSepaBetaling else _qcNEE endif;

  // LET OP: Er wordt hier nog GEEN rekening gehouden met het feit dat een bestaande opdracht een bepaald status heeft of dat deze wel/niet binnen- of juist buitenland is!!
  //         en of de valuta etc. kloppen

  // Opvragen valuta van de tegenrekening van het dagboek (Wordt in de header gezet)
  select RksValNummer into @_ValNummerDgb from tabRekeningschema inner join tabDagboek on (RksGid = DgbTegenRksGid) where DgbGid = @DgbGid;

  // +++ Keuze aanvullen of nieuw +++
  begin
    declare @bestaat integer;
    select first 1 into @Bestaat from tabBetalingKop where BetKopId = @VolgNr;
    if     (@IsAanvullenAlsBestaat = _qcNEE)
       and  isnull(@Bestaat,0) = _qcJA then
      set @Resultaat = 1; // Volgnummer komt al voor en mag NIET worden aangevuld
    else
      //--- voorstel aanmaken
      if isnull(@Bestaat,0) = _qcNEE then
        insert into tabBetalingKop (BetKopID, BetKopValNummer,    BetKopBankGiro, BetKopVasteOms, BetKopDgbGid, BetKopValnummerDgb, BetKopIsBuitenland, BetKopBetForId)
                    values         (@VolgNr, @ValNummerVoorstel,  @BankRekening,  @VasteOms,      @DgbGid,      @_ValNummerDgb,      @IsBuitenland,      @Formaat);
      end if;
    end if;
  end;

  if @resultaat = 0 then

    set @_IsolationLevel = @@Isolation;
    if @@Isolation < 1 then
      set temporary option Isolation_Level = 1;
    end if;

    // +++++++++++++++++++++++++++++++++++++++
    // +++ STAP 1 - OSPs bij elkaar zoeken +++
    // +++++++++++++++++++++++++++++++++++++++

    begin
      // Opvragen bankrekeninggegevens crediteur
      declare @BankGiroRek            nchar(34);
      declare @BankIsVoorBetaling     smallint;
      declare @NawRekGid              integer;
      declare @NawRekIsBuitenland     smallint;
      // Keuze wel/niet meenemen
      declare @PostMeenemen           smallint;
      // Lus-velden
      declare @VorigeRksGid           integer;
      declare @VorigeBetRglValNummer  integer;

      set @VorigeRksGid          = -1;
      set @VorigeBetRglValNummer = -1;



      insert into tabBetalingsVoorstelCreate(
        BvcUniekId, BvcOverslaan,
        BvcRksGID, BvcOspGid,
        BvcValNummerVanBetalingsRegel,
        BvcBedragFactuur,
        BvcBedragBetaald,
        BvcBedragTeBetalenInValutaVanOsp,
        BvcBedragTeBetalenInValutaVanBetRgl,
        BvcTegenBankrek,
        BvcIsCrediteur
      )
        select
          @SessieNR, '',
          RksGid @RksGid,  OspGid @OspGid,
          if @IsValNummerVanOsp = _qcNEE then @ValNummerVoorstel else OspValNummer endif @BetRglValNummer,
          (OspFactuurBedragDefinitief + if @VoorlopigeFacturen <> 0 then OspFactuurBedragVoorlopig else 0 endif) @FactuurBedrag,
          (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig) @BetaaldBedrag,
            @FactuurBedrag -                                                                                      // Factuurbedrag -
            @BetaaldBedrag -                                                                                      // Reeds betaalde bedrag -
            OspBedragOnderwegInValuta -                                                                           // Bedrag onderweg LET OP: IN DE OUDE SITUATIE KON DE VALUTA ANDERS ZIJN! NU IS DEZE ALTIJD GELIJK AAN DE OSPVALUTA
            if DefaultSoort = 7 then
              BepaalTeBetalenBedragInBetalingsVoorstellen(@RksGid, OspFactuurNummer, OspValNummer, @BjGid, @_PerNr) // crediteuren
            else
              -BepaalTeBetalenBedragInBetalingsVoorstellen(@RksGid, OspFactuurNummer, OspValNummer, @BjGid, @_PerNr) // debiteuren
            endif // Bedrag in voorstellen maar nog niet onderweg
          @TeBetalenBedragInValutaVanOsp,

          if OspValNummer <> @BetRglValNummer then
            ValutaOmrekenen(OspValNummer, @TeBetalenBedragInValutaVanOsp, @BetRglValNummer, @BjGid, @_PerNr, 2)
          else
            @TeBetalenBedragInValutaVanOsp
          endif TeBetalenBedragInValutaVanBetRgl,
          isnull(NawRekBankRekening, ''),
        if DefaultSoort = 6 then 0 else 1 endif @_IsCrediteur

        from
          tabOpenstaandePost
          inner join tabRekeningschema   on (OspRksGid = RksGid)
          inner join tabNawFile          on (NawFilFonID in ('C', 'D') and NawFilRksGID = RksGid and NawFilRksGID = OspRksGid)
          left outer join tabNawRekening on (NawRekNawGid = NawFilNawGid and (   (NawFilFonID = 'C' and NawRekSoort like '%B%') //ACW 05-04-2016 defect #48224: Voor debiteuren de default bankrekening gebruiken
                                                                              or (NawFilFonID = 'D' and NawRekSoort like '%D%')
                                                                             )
                                            ) // Alleen de default gebruiken/opzoeken
        where      (DefaultSoort in (6, 7))   // Debiteur + Crediteur
               and (OspBjGid=@BjGid)    // In huidige boekjaar
               and (OspIsVervallen = _qcNEE) // nav bug 29497 - alleen niet verwerkte osps meenemen
               and (OspRksInvoer     between @VanNAW     and @TotNAW)     // In crediteurenrange
               and (OspFactuurdatum  between @VanFactuurdatum  and @TotFactuurdatum)  // In factuurdatumrange
               and (OspVervaldatum   between @VanVervalDatum   and @TotVervalDatum)   // In vervaldatumrange
               and ((Repeat(' ',40-OspFactuurnummer_Lengte)+Trim(OspFactuurnummer)) between @VanFactuurnummer and @TotFactuurnummer) // In factuurnummerrange
               and (OspValCode       between @VanValCode       and @TotValCode)       // In valutarange
               and (TeBetalenBedragInValutaVanBetRgl <> 0) // Deze nemen we zowiezo nooit op (test op OspIsVervallen is niet genoeg i.v.m. bedragonderweg en voorlopig/definitief)
               and (   //Crediteuren: alle posten > 0 of wanneer we ook gaan verrekenen (dan alles)
                       (DefaultSoort = 7 /*cred.*/ and (TeBetalenBedragInValutaVanBetRgl > 0 or @MetCreditnotas + @MetVooruitbetalingen <> 0))
                        //Debiteuren: alle posten < 0 of wanneer we ook gaan verrekenen (dan alles)
                    or ( DefaultSoort = 6 /*deb.*/ and (TeBetalenBedragInValutaVanBetRgl < 0 or @MetCreditnotas = _qcJA))
                   )
        ;

      //Bij verrekenen van normale facturen van debiteuren moeten er natuurljik wel creditnotas ed. voor die debiteur zijn, anders helemaal niet opnemen!
      //Bij verrekenen van creditnotas van crediteuren moet de crediteur natuurlijk wel een normale factuur hebben
      delete tabBetalingsVoorstelCreate bvcBuiten
      where  BvcUniekId = @SessieNR
         and bvcIsCrediteur = @_IsCrediteur // Beperken tot alleen het juiste soort te controleren, scheelt weer doorlopen van records
         and bvcRksGid not in (select bvcBinnen.bvcRksGid
                               from   tabBetalingsVoorstelCreate bvcBinnen
                              where  bvcBinnen.BvcBedragTeBetalenInValutaVanBetRgl * (if bvcIsCrediteur = _qcNEE then 1 else -1 endif) < 0
                                  and bvcBinnen.BvcValNummerVanBetalingsRegel = bvcBuiten.BvcValNummerVanBetalingsRegel
                              );

      /* Redenen voor het overslaan van een OSP:
        A = Geblokkeerd
        B = Niet gefiatteerd
        C = Creditnota
        D = Geen geldige bankrekening
        E = BIC niet gevuld
        F = Grensbedrag EU overschreden
        G = OSP al in incassovoorstel opgenomen
        H = Vooruitbetaling
        I = Teveelbetaling door debiteur
        J = Verzamelbetaling is negatief
        K = Bankrekening is ingevuld
        L = Bankrekening is niet ingevuld
        M = Is SEPA-betaling
      */

      //*******************************************************
      //*** Controles voor zowel debiteuren als crediteuren ***
      //*******************************************************

      // *** Controle betalingen BUITEN SEPA, dan de SEPA-betalingen eruit halen (ook niet vermelden)
      if @_IsBetalingInSEPAgebied = _qcNEE then
        update tabBetalingsVoorstelCreate
               inner join tabNawFile on (NawFilRksGID = BvcRksGID)
               inner join tabNawRekening on (NawRekNawGid = NawFilNawGid and NawRekBankRekening = BvcTegenBankrek)
        set    BvcOverslaan = BvcOverslaan + 'M'
        where  BvcUniekId = @SessieNR
           and BvcIsCrediteur = @_IsCrediteur
           and BvcValNummerVanBetalingsRegel = @_ValNummerEur // EURO, dan misschien eruit halen
           // Eruit knikkeren als de NAW een bankrekening heeft, maar die bankrekening is een geldige IBAN
           and BvcTegenBankrek <> ''
           and NawRekIsIBAN = _qcJA
      end if;

      // *** Controle: Geblokkeerd
      update tabBetalingsVoorstelCreate
             inner join tabOpenstaandePost on OspGid = BvcOspGid
      set    BvcOverslaan = BvcOverslaan + 'A'
      where  BvcUniekId = @SessieNR
         and BvcIsCrediteur = @_IsCrediteur
         and OspIsGeblokkeerd <> 0;

      // *** Controle: Niet gefiatteerd
      //ACW 16-03-2016 defect #48239: Ongeacht de rechten controleren op gefiatteerd
      //if @HeeftRechtcopf = 0 then
        // Gebruiker kan zelf niet fiatteren, dus OSP moet al zijn gefiatteerd
        update tabBetalingsVoorstelCreate
               inner join tabOpenstaandePost on OspGid = BvcOspGid
        set    BvcOverslaan = BvcOverslaan + 'B'
        where  BvcUniekId = @SessieNR
           and BvcIsCrediteur = @_IsCrediteur
           and OspGefiatteerd = _qcNEE;
      //end if;

      // *** Controle: Te betalen bedrag <> 0
      //ACW Kan nu niet voorkomen, omdat deze OSPs al niet mee gaan!
      //update tabBetalingsVoorstelCreate
      //set    BvcOverslaan = BvcOverslaan + '?'
      //where  BvcUniekId = @SessieNR
      //   and BvcIsCrediteur = @_IsCrediteur
      //   and BvcBedragTeBetalenInValutaVanOsp = 0;

      // *** Controle: Geldige IBAN binnen SEPA-betaling
      if @_IsBetalingInSEPAgebied = _qcJA and @CrediteurenSelecteren = _qcNEE /*MET bankrekening, dus die dan ook controleren!*/ then
        update tabBetalingsVoorstelCreate
               inner join tabNawFile on NawFilRksGID = BvcRksGID
               inner join tabNawRekening on (NawRekNawGid = NawFilNawGid and NawRekBankRekening = BvcTegenBankrek)
        set    BvcOverslaan = BvcOverslaan + 'D'
        where  BvcUniekId = @SessieNR
           and BvcTegenBankrek <> ''
           and BvcIsCrediteur = @_IsCrediteur
           and isnull(NawRekIsIBAN, 0) <> 1
      end if;

      // *** Controle: BIC ingevuld binnen SEPA-betaling
      //ACW 16-03-2016 defect 48237: Geen controle op BIC meer
      //if @_IsBetalingInSEPAgebied = 1 then
      //  update tabBetalingsVoorstelCreate
      //         inner join tabNawFile on NawFilRksGID = BvcRksGID
      //         inner join tabNawRekening on (NawRekNawGid = NawFilNawGid and NawRekBankRekening = BvcTegenBankrek)
      //  set    BvcOverslaan = BvcOverslaan + 'E'
      //  where  BvcUniekId = @SessieNR
      //     and BvcIsCrediteur = @_IsCrediteur
      //     and BvcTegenBankrek <> ''
      //     and isnull(NawRekBankBIC, '') = ''
      //end if;

      // *** Controle: OSP al in incassovoorstel opgenomen
      update tabBetalingsVoorstelCreate
             inner join tabOpenstaandePost on (OspGid = BvcOspGid)
      set    BvcOverslaan = BvcOverslaan + 'G'
      where  BvcUniekId = @SessieNR
         and BvcIsCrediteur = @_IsCrediteur
         and (   exists ( //In incassoregels
                         select first 1
                         from   tabIncassoRegel
                         where  IncRglStatus = _qcNEE // voorstel
                            and IncRglRksGid = BvcRksGID
                            and IncRglFactuurNummer = OspFactuurNummer
                         )
              or exists( // of in incassoverzamelregels
                        select first 1
                        from   tabIncassoRegel
                               inner join tabIncassoRegelVerzameld on IncRglGid = IrvIncRglGid
                        where  IncRglStatus = _qcNEE // voorstel
                           and IncRglRksGid = BvcRksGID
                           and IrvFactuurNummer = OspFactuurNummer
                        )
             );

      // *** Controle: De rekening moet zijn ingevuld
      if @CrediteurenSelecteren <> 2 /*MET en ZONDER bankrekening is toegestaan*/ then
        update tabBetalingsVoorstelCreate
        set    BvcOverslaan = BvcOverslaan + if @CrediteurenSelecteren = 0 /*MET bankrek.*/ then 'L' /*Bankrek. is leeg*/ else 'K' /*Bankrek. is ingevuld*/ endif
        where  ((@CrediteurenSelecteren = 0 /*met, dus de ZONDER overslaan*/) and (BvcTegenBankrek = '')) or
               ((@CrediteurenSelecteren = 1 /*zonder, dus de MET overslaan*/) and (BvcTegenBankrek <> ''))
           and BvcIsCrediteur                   = @_IsCrediteur;
      end if;

      //*****************************************
      //*** Controles voor alleen crediteuren ***
      //*****************************************

      // *** Controle: Crediteur: Vooruitbetaling (factuurbedrag=0, Betaald bedrag<>0)
      if @MetVooruitbetalingen = _qcNEE and @_IsCrediteur = _qcJA then
        // Vooruitbetalingen aan crediteuren eruit filteren, want die gaan we niet verrekenen
        update tabBetalingsVoorstelCreate
        set    BvcOverslaan = BvcOverslaan + 'H'
        where  BvcUniekId = @SessieNR
           and BvcIsCrediteur                   = _qcJA /*Crediteur*/
           and BvcBedragFactuur                 = 0 /*Anders is het al geen vooruitbetaling*/
           and BvcBedragTeBetalenInValutaVanOsp > 0 /*Per saldo is er wel (vooruit)betaald*/
      end if;

      // *** Controle: Crediteur: Creditnota
      if @MetCreditnotas = _qcNEE and @_IsCrediteur = _qcJA then
        // Creditnotas eruit filteren
        update tabBetalingsVoorstelCreate
        set    BvcOverslaan = BvcOverslaan + 'C'
        where  BvcUniekId = @SessieNR
           and BvcIsCrediteur   = _qcJA                /*Crediteur*/
           and BvcBedragFactuur < 0                /*Dus creditnota*/
      end if;

      // *** Controle: Crediteur: Soort factuur ia 'Automatische incasso'
      if @_IsCrediteur = _qcJA then
        update tabBetalingsVoorstelCreate
             inner join tabOpenstaandePost on OspGid = BvcOspGid
        set BvcOverslaan = BvcOverslaan + 'N'
        where BvcUniekId = @SessieNR
          and BvcIsCrediteur = _qcJA
          and OspBtcNummer in (select BtcNummer from tabBetalingsconditie where SoortFactuurBTC = 3 /* Factuur via automatische incasso*/);
      end if;

      //ACW 21-06-2016 Defect #48691: Totaal negatief, dan NIET opnemen, want geen negatieve verzamelingen
      if @MetCreditnotas = _qcJA and @_IsCrediteur = _qcJA then
        update tabBetalingsVoorstelCreate tabBvcBuiten
        set    BvcOverslaan = BvcOverslaan + 'J'
        where  BvcUniekId = @SessieNR
           and BvcIsCrediteur   =  _qcJA /*Crediteur*/
           // Totaalbedrag negatief, dan niet opnemen!
           and tabBvcBuiten.BvcRksGid in (select tabBvcBinnen.BvcRksGID from tabBetalingsVoorstelCreate tabBvcBinnen where BvcOverslaan = '' and BvcUniekId = @SessieNR group by tabBvcBinnen.BvcRksGid having sum(tabBvcBinnen.BvcBedragTeBetalenInValutaVanBetRgl) <= 0)
      end if;

      //****************************************
      //*** Controles voor alleen debiteuren ***
      //****************************************

      // *** Controle: Teveelbetalingen op debiteur
      if @MetTeveelBetalingen = _qcNEE and @_IsCrediteur = _qcNEE then
        // Alle teveelbetalingen eruit filteren (alleen van debiteuren, want voor crediteuren zouden we dan juist geld moeten krijgen)
        update tabBetalingsVoorstelCreate
        set    BvcOverslaan = BvcOverslaan + 'I'
        where  BvcUniekId = @SessieNR
           and BvcIsCrediteur   =  _qcNEE           /*Debiteur*/
           and BvcBedragFactuur <> 0                /*Zodat het geen vooruitbetaling is*/
           and BvcBedragBetaald > BvcBedragFactuur  /*Er is meer betaald dan het factuurbedrag*/
           and BvcBedragTeBetalenInValutaVanOsp < 0 /*Er moet nog een bedrag te betalen zijn*/
      end if;

      //// Controle verrekenen met normale facturen levert te hoog verzamelbedrag op
      //ACW/RB: Deze controle niet. Neem maar gewoon op en dan moet de gebruiker zelf maar bepalen welke facturen wel/niet worden verrekend
      //if @MetCreditnotas = 1 and @_IsCrediteur = 0 then
      //  update tabBetalingsVoorstelCreate tabBvcBuiten
      //  set    BvcOverslaan = BvcOverslaan + 'J'
      //  where  BvcUniekId = @SessieNR
      //     and BvcIsCrediteur   =  0                /*Debiteur*/
      //     // Totaalbedrag te hoog, dan niet opnemen! (want dat bedrag wordt juist met omgekeerd teken opgenomen, omdat het natuurlijk een debiteur betreft)
      //     and tabBvcBuiten.BvcRksGid in (select tabBvcBinnen.BvcRksGID from tabBetalingsVoorstelCreate tabBvcBinnen where BvcOverslaan = '' and BvcUniekId = @SessieNR group by tabBvcBinnen.BvcRksGid having sum(tabBvcBinnen.BvcBedragTeBetalenInValutaVanBetRgl) >= 0)
      //end if;
    end;

    // -----------------------------------------
    // +++ Post opnemen in betalingsvoorstel +++
    // -----------------------------------------
    insert into tmpZetOspInBetVoorstel(
           tmpZoibvSessieNr, tmpZoibvRksGid, tmpZoibvOspGid, tmpZoibvBetRglValNummer,
           tmpZoibvTeBetalenInValVanBetRgl,
           tmpZoibvBankGiroRekening)
    select @SessieNR,        BvcRksGID,      BvcOspGid,      BvcValNummerVanBetalingsRegel,
           if BvcIsCrediteur = _qcJA then BvcBedragTeBetalenInValutaVanBetRgl else -BvcBedragTeBetalenInValutaVanBetRgl endif,
           BvcTegenBankrek
    from tabBetalingsVoorstelCreate
    where BvcUniekId = @SessieNR
      and BvcIsCrediteur = @_IsCrediteur
      and BvcOverslaan = '';

    // ++++++++++++++++++++++++++++++++++++++++++++++++++++
    // +++ Stap 2 - aanmaken voorstel obv gevonden OSPs +++
    // ++++++++++++++++++++++++++++++++++++++++++++++++++++
    call BetvrstlAanmakenInValutaVerwerk(
      @SessieNr,
      1, // Via automatisch aanmaken/aanvullen
      @VolgNr,
      @IsBuitenland,
      @_IsBetalingInSEPAgebied,
      @VulKenmerk,
      @OmsUwRef,
      @OmsUwRefTekst,
      @OmsOspOms,
      @OmsOnzeRef,
      @OmsOnzeRefTekst,
      @BjGid,
      if @VerzamelenPerCrediteur = _qcJA then 1 else if @MetVooruitbetalingen + @MetCreditnotas > 0 then 2 /*Alleen verzamelen indien negatief bedrag*/ else 0 /*niet verzamelen*/ endif endif,
      @MetBetaaldatum,
      @Betaaldatum,
      @VoorlopigeFacturen,
      @BOBchequeVerzenden,
      @BOBsoortCrossen,
      null, //@ToevoegenAanBetRglGid
      @Resultaat,
      @RegelsInserted);

    // Tussentabel voor de netheid opschonen
    delete tmpZetOspInBetVoorstel where tmpZoibvSessieNr = @SessieNr;

    //--- controleren of er wel regels zijn toegevoegd
    if not exists(select 1 from tabBetalingRegel where BetRglBetKopID = @VolgNr) then
//      delete from tabbetalingkop where betkopid=@VolgNr;  // LET OP: verwijderen gebeurt nu in Delphi i.v.m. keuze van de gebruiker
      set @Resultaat = 2; // Er zijn geen posten in de selectie
    end if;

    execute immediate 'set temporary option Isolation_Level = ' || @_IsolationLevel;

  end if; // Volgnummer bestaat reeds

  set @@ErrorTextProcedure = 'BetvrstlAanmakenInValuta  ---> @Resultaat='+string(@Resultaat);
  //call traceEind(@@ErrorTextProcedure);
end;

create or replace procedure BetvrstlAanmakenInValutaVerwerk(
 in @SessieNr               integer,
 in @AutomAanmaken          smallint, // 0 = losse OSPs geseelcteerd om aan het bestaande voorstel toe te voegen, 1 = via automatisch aanmaken/aanvullen
 in @VolgNr                 integer,
 in @IsBuitenland           smallint, // Indien 0, dan kan het een binnenlandse betaling (Clieop) OF een SEPA-betaling (PAIN) zijn
 in @IsBetalingInSEPAgebied smallint,
 in @VulKenmerk             integer,
 in @OmsUwRef               smallint,
 in @OmsUwRefTekst          nchar(10),
 in @OmsOspOms              smallint,
 in @OmsOnzeRef             smallint,
 in @OmsOnzeRefTekst        nchar(10),
 in @BjGid                  integer,
 in @VerzamelenPerCrediteur smallint, //0 = niet, 1 = gebruiker wil verzamelen, 2 = alleen verzamelen indien negatieve bedragen (creditnota of vooruitbetaling)
 in @MetBetaaldatum         smallint,
 in @Betaaldatum            date,
 in @VoorlopigeFacturen     smallInt,
 in @BOBchequeVerzenden     nchar(1),
 in @BOBsoortCrossen        nchar(1),
 in @ToevoegenAanBetRglGid  integer, // Indien <>null, dan moeten de OSPs aan deze regel worden toegevoegd
 out @Resultaat             integer,
 out @RegelsInserted        integer
)
begin
//--- Let op: In deze stored proc komt vaak de term crediteur terug. Ooit werden in betalingsvoorstellen alleen de notas van crediteuren opgenomen.
//--- Inmiddels kunnen ook de credit-notas van debiteuren worden opgenomen in betalingsvoorstellen. Echter de namen van variabelen zijn niet aangepast.

  declare @errorText              nchar(250);
  declare @RegelsAanBestaandeVerzamelingenToevoegen smallint; //0 = Normale werking, 1 = Probeer elke OSP aan een al bestaande verzameling toe te voegen
  declare @PerNr                  integer; // Voor valutaomrekeningen
  // tbv. betaalregel
  declare @BetaalDatumRegel       date;
  declare @RegelOms               nchar(250);
  declare @RegelKenmerk           nchar(140);
  declare @ExternFact             nchar(40);
  declare @ExternFactRest         nchar(40);
  declare @FactuurNummer          nchar(40);
  declare @OspKenmerk             nchar(140);
  declare @OspOms                 nchar(40);

  // tbv. verzamelregels
  declare @BetVerzOmschrijving    nchar(250);
  declare @BetVerzBetaaldatum     date;
  // Lus-velden
  declare @VorigeRksGid           integer;
  declare @VorigeBetRglValNummer  integer;
  declare @HuidigeRksInvoer       nchar(28); // Bewaart RksInvoer van de zojuist verwerkte regel, want FETCH NEXT (peek) overschrijft @RksInvoer al met de volgende crediteur
  declare @ControleStatus         smallint;

  declare @BetVerzBetRglGid       integer;
  declare @BetRglIsVerzameld      integer;
  declare @DoVerzamelen           smallint;

  // OSP-gegevens
  declare @Openstaand             numeric(15,3);
  declare @Onderweg               numeric(15,3);
  declare @TeBetalen              numeric(15,3);
  // Codelijsten
  declare @BOBsoortOpdracht       nchar(1);
  declare @BOBsoortUitvoering     nchar(1);
  declare @BOBkostenBinnenland    nchar(1);
  declare @BOBkostenCorrespondent nchar(1);
  declare @BOBbankBIC             nchar(11);
  declare @BOBbankNaam            nchar(35);
  declare @BOBbankPlaats          nchar(35);
  declare @BOBbankLndGid          integer;
  declare @BOBinstr1              nchar(2);
  declare @BOBinstr2              nchar(2);
  declare @BOBinstr3              nchar(2);
  declare @BOBinstr4              nchar(2);
  declare @OspGefiatteerd         smallint;
  declare @GefiatteerdDoor        nchar(40);
  declare @GefiatteerdOp          DateTime;

  set @errorText = 'BetvrstlAanmakenInValutaVerwerk>';
  set @@ErrorTextProcedure = @errorText;
  //call traceBegin(@@ErrorTextProcedure);

 set @Resultaat      = 0;
 set @RegelsInserted = 0;

  // Hulpvariabelen
  select PeriodeBepalen(@BjGid, @@VerwerkingsDatum) into @Pernr; // voor omrekenen

  // Als via multi-select of losse OSP, dan proberen om deze aan een al bestaande verzameling toe te voegen
  if @AutomAanmaken = 0 then
    set @RegelsAanBestaandeVerzamelingenToevoegen = 1;
  else
    set @RegelsAanBestaandeVerzamelingenToevoegen = 0;
  end if;

  set @VorigeRksGid          = -1;
  set @VorigeBetRglValNummer = -1;
  for @tmpCursor AS Cursor_TmpOsp cursor for
    select
      tmpZoibvGid                      @tmpZoibvGid,
      tmpZoibvRksGid                   @RksGid,
      RksInvoer                        @RksInvoer,
      tmpZoibvOspGid                   @OspGid,
      tmpZoibvBetRglValNummer          @BetRglValNummer,
      if     (@AantalPostenPerCrediteur > 1)   // Alleen verzamelen als meer dan 1 post
         and (   (@VerzamelenPerCrediteur = 1) // Gebruiker wil wel verzamelen
              or ((@VerzamelenPerCrediteur = 2) and (@NAWheeftNegatieveOSP > 0))  // Creditnotas of vooruitbetalingen en negatief bedrag, dan altijd verzamelen
             ) then
          1 // Ja, verzamelen, want de gebruiker wil dat of het kan niet anders
        else
          0 // Nee, niet verzamelen
      endif @Verzamelen,
      tmpZoibvTeBetalenInValVanBetRgl  @TeBetalenBedragInValutaVanBetRgl,
      tmpZoibvBankGiroRekening         @BankGiroRek,
      DefaultSoort                     @DefaultSoort,
      sum(@TeBetalenBedragInValutaVanBetRgl)                       over NAW_Window @TotaalTeBetalenPerCrediteur,
      count(tmpZoibvOspGid)                                        over NAW_Window @AantalPostenPerCrediteur,
      count(if    (@DefaultSoort = 7 and @TeBetalenBedragInValutaVanBetRgl < 0)
               or (@DefaultSoort = 6 and @TeBetalenBedragInValutaVanBetRgl > 0) then 1 endif) over NAW_Window @NAWheeftNegatieveOSP
    from
      tmpZetOspInBetVoorstel
      inner join tabRekeningschema on RksGid = tmpZoibvRksGid
    where tmpZoiBvSessieNr = @SessieNr
    WINDOW NAW_Window as (PARTITION BY RksInvoer, tmpZoibvBetRglValNummer)
    order by
      RksInvoer,
      tmpZoibvBetRglValNummer,
      tmpZoibvTeBetalenInValVanBetRgl desc // Eerst de positieve, daarna de negatieve
  for read only
  do
      //call trace('@tmpZoibvGid='+string(@tmpZoibvGid)+',@RksGid='+string(@RksGid)+',@RksInvoer='+string(@RksInvoer)+',@OspGid='+string(@OspGid)+',@BetRglValNummer='+string(@BetRglValNummer)+',@Verzamelen='+string(@Verzamelen)+',@TeBetalenBedragInValutaVanBetRgl='+string(@TeBetalenBedragInValutaVanBetRgl)+',@BankGiroRek='+string(@BankGiroRek)+',@TotaalTeBetalenPerCrediteur='+string(@TotaalTeBetalenPerCrediteur)+',@AantalPostenPerCrediteur='+string(@AantalPostenPerCrediteur)+',@NAWheeftNegatieveOSP='+string(@NAWheeftNegatieveOSP));

    if @VorigeRksGid <> @RksGid or @VorigeBetRglValNummer <> @BetRglValNummer then
      set @BetVerzBetRglGid      = @ToevoegenAanBetRglGid; // Als we straks verzamelen, dan wordt de regelGid hierin gezet. Is standaard nog NULL; indien gevuld, dan altijd in die regel zetten
      set @VorigeRksGid          = @RksGid;
      set @VorigeBetRglValNummer = @BetRglValNummer;

    end if;

    call BetvrstlVulRegelGegevensObvOsp(@BjGid, @PerNr, @BetRglValNummer, @VulKenmerk,
         @OmsUwRef, @OmsUwRefTekst, @OmsOspOms, @OmsOnzeRef, @OmsOnzeRefTekst,
         @MetBetaaldatum, @Betaaldatum, @OspGid, @VoorlopigeFacturen, @IsBuitenland, @IsBetalingInSEPAgebied,
         @FactuurNummer, @OspKenmerk, @OspOms, @Openstaand,
         @Onderweg, @TeBetalen, null, @BetaalDatumRegel, @RegelOms, @RegelKenmerk,
         @BankGiroRek, @IsBankGiroRekBuitenland, @RksGid, @RksInvoer, @ExternFact, @ExternFactRest,
         @BOBsoortOpdracht, @BOBsoortUitvoering, @BOBkostenBinnenland, @BOBkostenCorrespondent,
         @BOBbankBIC, @BOBbankNaam, @BOBbankPlaats, @BOBbankLndGid, @BOBinstr1, @BOBinstr2, @BOBinstr3, @BOBinstr4,
         @OspGefiatteerd, @GefiatteerdDoor, @GefiatteerdOp);

    if @ospgefiatteerd = 0 then
      // Blijkbaar wordt de OSP op dit moment gefiatteerd, dus de huidige gebruiker opnemen
      set @GefiatteerdDoor = @@GebruikerCode;
      set @GefiatteerdOp   = now();
    end if;

    // Controleren of de OSP wel kan worden opgenomen bij toevoegen via multi-select
    set @ControleStatus = 0; // In principe lekker doorgaan
    if @AutomAanmaken = 0 then
      //Controle: OSP is geblokkeerd
      if exists(select first 1 from tabOpenstaandePost where OspGid = @OspGid and OspIsGeblokkeerd = 1) then
        set @ControleStatus = 4; //OSP is geblokkeerd
      end if;

      //Controle: OSP komt al voor in dit betalingsvoorstel
      if     (@ControleStatus = 0)
         and (  exists(select first 1 from tabBetalingRegel where BetRglBetKopId = @VolgNr and BetRglRksGid = @RksGid and BetRglFactuurNummer_Lengte = length(@FactuurNummer) and BetRglFactuurNummer = @FactuurNummer)
              or exists(select first 1 from tabBetalingRegel inner join tabBetalingVerzameld on BetVerzBetRglGid = BetRglGid where BetRglBetKopId = @VolgNr and BetRglRksGid = @RksGid and BetVerzFactuurnummer_Lengte = length(@FactuurNummer) and BetVerzFactuurnummer = @FactuurNummer)
             ) then
        set @ControleStatus = 3; /*OSP komt al voor*/
      end if;
      //Controle: bedrag is onderweg
      //if (@ControleStatus = 0) and (@Openstaand = @Onderweg) then
      //  set @ControleStatus = 5; // Openstaande bedrag is al onderweg
      //end if;
      //Controle: Toevoegen aan voorstel met andere valuta
      if (@ControleStatus = 0) and ((select first OspValNummer from tabOpenstaandePost where OspGid = @OspGid) <> @BetRglValNummer) then
        //Controle: Toevoegen aan opdracht of verzamelregel in andere valuta
        if @ToevoegenAanBetRglGid is not null then
          set @ControleStatus = 7; // De openstaande post is in een andere valuta dan de verzamelregel
        else
          set @ControleStatus = 6; // De openstaande post is in een andere valuta dan de betalingsopdracht
        end if;
      end if;

      //Controle: Bij debiteuren alleen als het totaal saldo niet positief is
      if @ControleStatus = 0 and @DefaultSoort = 6 /*debiteur*/ then
        begin
          declare @OpenstaandSaldo numeric(15,2);
          select sum(if OspValNummer = @@basisvalutanummer then
                       (OspFactuurBedragDefinitief-OspBetaaldBedragDefinitief) + (OspFactuurBedragVoorlopig-OspBetaaldBedragVoorlopig)
                     else
                       ValutaOmrekenen( OspValNummer, (OspFactuurBedragDefinitief-OspBetaaldBedragDefinitief) + (OspFactuurBedragVoorlopig-OspBetaaldBedragVoorlopig),
                                             @@basisvalutanummer, @@BjGid, @@Pernr, 2)
                     endif
                    )
            into @OpenstaandSaldo
          from   tabOpenstaandePost
          where  OspRksGid = @RksGid and OspBjGid = @@BjGid;
          if @OpenstaandSaldo > 0 then
            set @ControleStatus = 11; //Openstaand saldo debiteur groter dan 0
          end if;
        end;
      end if;

      // Controleer of de post niet is opgenomen in een Incassovoorstel
      if @ControleStatus = 0 and @DefaultSoort = 6 /*debiteur*/ then
        if (exists(
              select first 1 from tabIncassoRegel
              left outer join tabIncassoRegelVerzameld on IncRglGid = IrvIncRglGid
              where
                    IncRglStatus = 0 /* voorstel */
                and IncRglRksGid = @RksGid
                and IsNull(IrvFactuurNummer, IncRglFactuurNummer) = @FactuurNummer
          )
        ) then
          set @ControleStatus = 12; //Openstaand post zit in incassovoorstel
        end if;
      end if;
    end if;

    if @ControleStatus <> 0 then
      update tmpZetOspInBetVoorstel set tmpZoiBvResultaat = @ControleStatus where tmpZoibvGid = @tmpZoibvGid;
    else
      // Ok, door de controle heengekomen, DUS opnemen in voorstel
      if ((@Verzamelen = 0) and (@RegelsAanBestaandeVerzamelingenToevoegen = 0)) then
        set @DoVerzamelen = 0;
      else
        set @DoVerzamelen = 1;
        if @BetVerzBetRglGid is null then
          //ACW 30-10-2012 Bug #36709: Als er meer regels zijn, dan slechts 1 terug geven
          select first BetRglGid, BetRglIsVerzameld into @BetVerzBetRglGid, @BetRglIsVerzameld from tabBetalingRegel where BetrglBetKopId = @VolgNr and BetRglValNummer = @BetRglValNummer and BetRglRksGid = @RksGid order by BetRglIsVerzameld desc /*liefst een al verzamelde regel*/;
          if @RegelsAanBestaandeVerzamelingenToevoegen = 1 and @BetVerzBetRglGid is null and
             (    (@DefaultSoort = 7 /*crediteur*/ and @Openstaand >= 0)
               or (@DefaultSoort = 6 /*debiteur */ and @Openstaand <= 0)
             ) then
            // Liefst verzamelen, maar als er geen enkele regel is gevonden, dan toch maar niet, anders wordt er een verzamelign van slechts 1 regel gemaakt
            // Als bedrag negatief, dan toch verzamelen, al is het maar een verzameling met 1 regel
            set @DoVerzamelen = 0;
          else
            if @BetVerzBetRglGid is not null and @BetRglIsVerzameld = 0 then
              // We hebben een regel, maar die is nog niet verzameld! Daarom alsnog verzamelen
              // De regel zelf is NIET verzameld, maar dat is eigenlijk wel de bedoeling, daarom alsnog alles voor die crediteur verzamelen ...
              call BetVerzAanmaken(@VolgNr, @RksInvoer, @BetRglValNummer, @OmsUwRef, @OmsUwRefTekst, @OmsOspOms, @OmsOnzeRef, @BOBchequeVerzenden, @BOBsoortCrossen, null);
              // Opnieuw opzoeken, maar dan verzameld
              set @BetVerzBetRglGid = null;
              //ACW 23-07-2013 defect #38935: @BetVerzBetaalDatum ook vullen als het om een verzameling gaat die we nu net gaan aanmaken
              select first BetRglGid, BetRglBetaalDatum into @BetVerzBetRglGid, @BetVerzBetaalDatum from tabBetalingRegel where BetrglBetKopId = @VolgNr and BetRglValNummer = @BetRglValNummer and BetRglRksGid = @RksGid and BetRglIsVerzameld = 1;
            end if;
          end if;
        end if;
      end if;

      // Als losse OF als verzamelregel!
      if @DoVerzamelen = 0 then
        insert into tabBetalingregel(BetrglBetKopId, BetrglBankrekening, BetRglBetaalDatum, BetRglOms, BetRglRksGid, BetRglValNummer,  BetRglFactuurNummer, BetRglTeBetalen,                   /*BetRglTeBetalenInValDgb,*/ BetRglBetKenmerk, BetRglIsVerzameld, BetRglVerschilAfboekenBedragInValOsp, BetRglVerschilAfboeken, BetRglBOBsoortOpdracht, BetRglBOBsoortUitvoering, BetRglBOBchequeVerzenden, BetRglBOBsoortCrossen, BetRglBOBkostenBinnen, BetRglBOBkostenCorrespondent, BetRglBOBbankBIC, BetRglBOBbankNaam, BetRglBOBbankPlaats, BetRglBOBbankLndGid, BetRglBOBinstr1, BetRglBOBinstr2, BetRglBOBinstr3, BetRglBOBinstr4, BetRglGefiatteerdDoor, BetRglGefiatteerdOp)
                    values          (@VolgNr,        @BankGiroRek,       @BetaalDatumRegel, @RegelOms, @RksGid     , @BetRglValNummer, @FactuurNummer     , @TeBetalenBedragInValutaVanBetRgl, /*@TeBetalenInValDgb,     */ @RegelKenmerk,    0,                 0,                                    0,                      @BOBsoortOpdracht,      @BOBsoortUitvoering,      @BOBchequeVerzenden,      @BOBsoortCrossen,      @BOBkostenBinnenland,  @BOBkostenCorrespondent,      @BOBbankBIC,      @BOBbankNaam,      @BOBbankPlaats,      @BOBbankLndGid,      @BOBinstr1,      @BOBinstr2,      @BOBinstr3,      @BOBinstr4, @GefiatteerdDoor, @GefiatteerdOp);
        set @RegelsInserted = @RegelsInserted + 1;
      else
        // In verzamelpost opnemen
        if @BetVerzBetRglGid is null then
          // anders of niet gevonden, dan nieuwe reegl aanmaken
          //ACW 16-11-2012 Bug #36778: Bij toevoegen van een verzameling gewoon het bedrag van die ene regel erin zetten. De andere regels komen later erbij
          insert into tabBetalingregel(BetrglBetKopId, BetrglBankrekening, BetRglBetaalDatum,  BetRglValNummer,  BetRglFactuurNummer, BetRglRksGid, BetRglTeBetalen,                   BetRglIsVerzameld, BetRglBOBsoortOpdracht, BetRglBOBsoortUitvoering, BetRglBOBchequeVerzenden, BetRglBOBsoortCrossen, BetRglBOBkostenBinnen, BetRglBOBkostenCorrespondent, BetRglBOBbankBIC, BetRglBOBbankNaam, BetRglBOBbankPlaats, BetRglBOBbankLndGid, BetRglBOBinstr1, BetRglBOBinstr2, BetRglBOBinstr3, BetRglBOBinstr4, BetRglGefiatteerdDoor, BetRglGefiatteerdOp)
                      values          (@VolgNr,        @BankGiroRek,       @@VerwerkingsDatum, @BetRglValNummer, '[VERZAMEL]',        @RksGid,      @TeBetalenBedragInValutaVanBetRgl, 1,                 @BOBsoortOpdracht,      @BOBsoortUitvoering,      @BOBchequeVerzenden,      @BOBsoortCrossen,      @BOBkostenBinnenland,  @BOBkostenCorrespondent,      @BOBbankBIC,      @BOBbankNaam,      @BOBbankPlaats,      @BOBbankLndGid,      @BOBinstr1,      @BOBinstr2,      @BOBinstr3,      @BOBinstr4, @GefiatteerdDoor, @GefiatteerdOp);
          set @BetVerzBetRglGid = @@Identity;
          set @RegelsInserted = @RegelsInserted + 1;
        else
          //ACW 16-11-2012 Bug #36778: Totaal bedrag van de eregl ophogen met het bedrag van de verzamelde regel
          update tabBetalingregel set BetRglTeBetalen = BetRglTeBetalen + @TeBetalenBedragInValutaVanBetRgl where BetRglGid = @BetVerzBetRglGid;
        end if;
        // Nu de post toevoegen als verzamelregel
        Insert into tabBetalingVerzameld(BetVerzBetRglGid,  BetVerzFactuurNummer, BetVerzBankRekening, BetVerzBetaalDatum, BetVerzOms, BetVerzBetKenmerk, BetVerzTeBetalen,                  BetVerzVerschilAfboekenBedragInValOsp, BetVerzVerschilAfboeken, BetVerzGefiatteerdDoor, BetVerzGefiatteerdOp)
                    values              (@BetVerzBetRglGid, @FactuurNummer,       @BankGiroRek,        @BetaalDatumRegel,  @RegelOms,  @RegelKenmerk,     @TeBetalenBedragInValutaVanBetRgl, 0,                                     0,                       @GefiatteerdDoor,       @GefiatteerdOp);

        // Gegevens van de verzameling onthouden om straks in de betalingsregel zelf te zetten
        set @BetVerzBetaalDatum = lesser(isnull(@BetVerzBetaalDatum, @BetaalDatumRegel), @BetaalDatumRegel);  // vroegste datum bijhouden

        // Bewaar RksInvoer van de crediteur die we net aan het afsluiten zijn, VOORDAT de look-ahead FETCH NEXT hem overschrijft
        set @HuidigeRksInvoer = @RksInvoer;

        // Behoort de volgende regel nog steeds bij dezelfde verzameling? Zoniet, dan de verzameling afsluiten
        FETCH NEXT Cursor_TmpOsp into @tmpZoibvGid, @RksGid, @RksInvoer, @OspGid, @BetRglValNummer, @Verzamelen, @TeBetalenBedragInValutaVanBetRgl, @BankGiroRek, @DefaultSoort, @TotaalTeBetalenPerCrediteur, @AantalPostenPerCrediteur, @NAWheeftNegatieveOSP;
        if (SQLCODE <> 0) or (@VorigeRksGid <> @RksGid or @VorigeBetRglValNummer <> @BetRglValNummer) then
          // Verzamelen is afgelopen, DUS de regel ervan nog afsluiten
          // Totalen e.d. in de regel onthouden

          // De omschrijving weer helemaal opnieuw opbouwen ipv hier ingewikkeld te berekenen
          call BetRglVerzamelOmschrijving(@BetVerzBetRglGid, @HuidigeRksInvoer, @OmsUwRef, @OmsUwRefTekst, @OmsOspOms, @OmsOnzeRef, @OmsOnzeRefTekst, @BetVerzOmschrijving);

          update tabBetalingRegel
          set    BetRglBetaalDatum = @BetVerzBetaalDatum,
                 BetRglOms         = trim(@BetVerzOmschrijving)
          where  BetRglGid = @BetVerzBetRglGid;
          //ACW 23-07-2013 defect #38935: Betaalopdrachtdatum weer resetten, zodat voor de volgende crediteur opnieuw wordt gezocht naar de oudste datum
          set @BetVerzBetaalDatum = null;
        end if; // if Dit was de laatste post in deze verzamelregel
        FETCH PRIOR Cursor_TmpOsp;
      end if; // @DoVerzamelen = 0
    end if; // @ControleStatus <> 0
  end for; //Cursor_CrediteurOsp

  set @@ErrorTextProcedure = 'BetvrstlAanmakenInValutaVerwerk  ---> @Resultaat='+string(@Resultaat) + ', @RegelsInserted='+string(@RegelsInserted);
  //call traceEind(@@ErrorTextProcedure);
end;



