create or replace procedure BetVrstlAanmakenSessieNr(
  out @SessieNr integer
)
begin
  declare @Pogingen smallint;

  set @@ErrorTextProcedure = 'BetVrstlAanmakenSessieNr';
  //call traceBegin(@@ErrorTextProcedure);

  set @Pogingen = 0;
  MaakSessieNr:
  loop
    call RandomNumber2(@SessieNr);
    if @Pogingen > 100 or not exists(select first 1 from tmpZetOspInBetVoorstel where tmpZoibvSessieNr = @SessieNr) then
      leave MaakSessieNr;
    end if;
    set @Pogingen = @Pogingen + 1;
  end loop MaakSessieNr;
  set @@ErrorTextProcedure = 'BetVrstlAanmakenSessieNr ->' + string(@SessieNr);
  //call traceEind(@@ErrorTextProcedure);

end;


//-----------------------------------------------
//---------- Ophalen bankgirorekening -----------
//-----------------------------------------------
create or replace procedure BetvrstlBepaalBankGiroRek(
  in  @CredNummer         nchar(10),
  in  @IsBetalingInSEPAgebied     smallint,
  out @BankGiroRek        nchar(40),
  out @BankIsVoorBetaling Smallint,
  out @NawRekGid          integer,
  out @IsBuitenland       smallint)
begin
  declare @IsDefBetaling smallint;
  declare @IsDefault     smallint;
  declare @LndIso2       nchar(2);
  declare @AdrLndGid     integer;
  declare @NawFilFonId   nchar(3);

  set @@ErrorTextProcedure = 'BetvrstlBepaalBankGiroRek > @CredNummer='+@CredNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  //ophalen rekening tbv betalingen
  set @BankGiroRek        = null;
  set @BankIsVoorBetaling = 0;

  select first NawRekBankrekening, NawRekGid , if locate(IsNull(NawRekSoort, ''), 'B') <> 0 then 1 endif IsDefBetaling, if locate(IsNull(NawRekSoort, ''), 'D')  <> 0 then 1 endif IsDefault,AdrLndGid, LndIso2, NawFilFonId
  into         @BankGiroRek,       @NawRekGid, @IsDefBetaling,                                                          @IsDefault,                                                          @AdrLndGid,@LndIso2, @NawFilFonId
  from   tabNawFile
         inner join tabNaw on (NawGid = NawFilNawGid)
         inner join tabAdres on AdrGid = NawGidVestiging
         //Bij debiteuren is de default rekening WEL mogelijk!
         left outer join tabNawRekening on (nawFilNawGid=nawRekNawGid and ((NawFilFonId = 'D') or IsDefBetaling is not null)) /* or IsDefault is not null ACW 8-3-2005: Default rekening NOOIT teruggeven!! */
         left outer join tabLand on (LndGid = NawRekBankLndGid)
  where  (NawFilNummer = @CredNummer) and (NawFilFonId in ('C', 'D')) //ACW 10-12-2013 Kan ook een debiteur zijn (maar GEEN relatie!)
  order by IsDefBetaling desc, IsDefault desc; // Om eerst de default t.b.v. bet. opdrachten te krijgen en daarna de default rekening

  if @NawRekGid is null then
    //if @IsBetalingInSEPAgebied = 1 then
    //  // Als SEPA-betaling, dan moet het land van de crediteur een SEPA-land zijn, maar dat registreren we niet!
    //  select if @IsSepaLand = 1 then 0 else 1 endif into @IsBuitenland from tabVasteGegevens;
    //else
      // Als landcode van de crediteur = eigen land, dan is het binnenland, anders buitenland
      select if DefaultLndGid = @AdrLndGid then 0 else 1 endif into @IsBuitenland from tabVasteGegevens;
    //end if;
  else
    if @IsBetalingInSEPAgebied = 1 then
      // SEPA, dus buitenlands als geen geldige IBAN
      set @IsBuitenland = 1 - IsValidIBAN(@BankGiroRek);
    else
      //Als het bankland Nederlands is, dan is het ok
      //Anders uit bankrekening halen: IBAN beginnend met NL is ok, anders max. 10 cijfers
      set @IsBuitenland = 1 - IsBankrekeningNederlands(@BankGiroRek, @LndIso2);
    end if;
  end if;

  //select if @LndIso2 = 'NL' then 0 else 1 endif into @IsBuitenland from tabVasteGegevens;
  // DG 1-4-2014: Rekeningen voor debiteuren kunnen niet default voor betalen zijn, hier dus alleen kijken naar de default.
  set @BankIsVoorBetaling = if @NawFilFonId = 'C' then IsNull (@IsDefBetaling, 0) else IsNull(@IsDefault, 0) endif;

  set @@ErrorTextProcedure = 'BetvrstlBepaalBankGiroRek > @BankGiroRek='+@BankGiroRek;
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BetVrstlControleren(in @BetKopID integer)
result(
  SoortReden          integer, // 1 = OSP-openstaand<TeBetalen; 2 = TeBetalen<=0; 3 = bankrekening leeg of onbekend (voor deze crediteur); 4 = Opdrachtdatum in het verleden
  BetRksGid           integer,
  OspGid              integer,
  FactuurNummer       nchar(40),
  ValNummer           integer,
  TotaalBedrag        numeric(15,2),
  OspOpenMinOnderweg  numeric(15,2),
  TeveelBetaald       integer,
  OspGefiatteerd      integer
)
begin
  declare @IsSepaBetaling  smallint;


  set @@ErrorTextProcedure = 'BetVrstlControleren > @BetKopID='+String(@BetKopID);
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select first 1 from tabBetalingKop inner join tabBetalingFormaten on (BetForId = BetKopBetForId) where BetKopId = @BetKopId and BetKopIsBuitenland = 0 and BetForFormaat like '%PAIN%') then
    // PAIN-formaat, dus het is een SEPA-betaling
    set @IsSepaBetaling = 1;
  else
    set @IsSepaBetaling = 0;
  end if;
  // Controle bestaat uit 2 delen:
  // - Per OSP:
  //   Fout indien voor een OSP (dus in de niet-verzamelde EN de verzamelde regels) het
  //   berekend openstaand bedrag minus bedrag onderweg VAN DE OSP kleiner is dan het
  //   te betalen bedrag van alle regels voor die OSP in deze opdracht
  //   Velden: Valuta is die van de OSP; alle bedragen in valuta van OSP
  // - Per regel:
  //   Fout indien er een regel is waarvoor het te betalen bedrag 0 of kleiner is EN/OF als bankrekening niet is ingevuld
  // Velden: Valuta is die van de regel; alle bedragen in valuta van regel
  //call TraceEind(@@ErrorTextProcedure);

  select
    SoortReden,
    BetRksGid,
    OspGid,
    FactuurNummer,
    ValNummer,
    TotaalBedrag,
    OspOpenMinOnderweg,
    if ((TotaalBedrag > 0) and OspOpenMinOnderweg * If DefaultSoort = 6 /*Debiteur*/ then -1 else 1 endif < TotaalBedrag)
        or ((TotaalBedrag < 0) and OspOpenMinOnderweg * If DefaultSoort = 6 /*Debiteur*/ then -1 else 1 endif > TotaalBedrag) then 1 else 0 endif TeveelBetaald,
    OspGefiatteerd
  from
  (
  select
    SoortReden,
    BetRksGid,
    OspGid,
    BetFactuurNummer FactuurNummer,
    if SoortReden = 2 then BetValNummer else OspValNummer endif ValNummer, // 1(=Per OSP) -> gebruik valuta van de OSP!; 2(=per regel: gebruik regelValuta)
    isnull(sum(TotaalTeBetalen),0) TotaalBedrag,
    min( isnull((OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) -  // Factuurbedrag -
                (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig) -  // Reeds betaalde bedrag -
                (OspBedragOnderwegInValuta)                                 // Bedrag onderweg van de OSP
              ,0)) OspOpenMinOnderweg,                                          // = Nog te betalen voor 1 OSP
    DefaultSoort,
    OspGefiatteerd
  from
  (
    // Deel 1: OSP teveel betaald van regels; alles in OSP-valuta!
   select
    1                       SoortReden,
    betRglRksGid            BetRksGid,
    betRglFactuurNummer     BetFactuurNummer,
    null                    BetValNummer, // Gebruik de valuta van de OSP; Berekenen we later wel!
    BetRglTeBetalenInValOsp +
    if BetRglVerschilAfboeken = 0 then 0 else BetRglVerschilAfboekenBedragInValOsp endif TotaalTeBetalen
   from
    tabbetalingregel
   where
        betrglbetkopid    = @BetKopID
    and BetRglIsVerzameld = 0

   UNION ALL

    // Deel 1: OSP teveel betaald van verzamelregels
   select
    1                        SoortReden,
    betRglRksGid             BetRksGid,
    betVerzFactuurNummer     BetFactuurNummer,
    null                     BetValNummer,  // Gebruik de valuta van de OSP; Berekenen we later wel!
    BetVerzTeBetalenInValOsp +
    if BetVerzVerschilAfboeken = 0 then 0 else BetVerzVerschilAfboekenBedragInValOsp endif TotaalTeBetalen
   from
    tabbetalingregel
    inner join tabBetalingVerzameld on (BetVerzBetRglGid = BetRglGid)
   where
        betrglbetkopid    = @BetKopID
    and BetRglIsVerzameld = 1

  UNION ALL

    // Deel 2: *Regels* (dus OSP is NIET bekend!) met een TeBetalen bedrag van 0 of negatief EN/OF als bankrekening niet is ingevuld
    // Let op: deze 2 controles MOETEN bij elkaar, anders krijg je misschien 2x dezelfde regel te zien
    select
     2 + if isnull(BetRglBankrekening,'')='' or NawRekGid is null or (@IsSepaBetaling = 1 and IsValidIban(BetRglBankrekening)=0) then 1 else 0 endif SoortReden, // Op 3 zetten als rekening niet is ingevuld of niet gevonden (onbekend voor deze crediteur)
     betRglRksGid            BetRksGid,
     betRglFactuurNummer     BetFactuurNummer,
     BetRglValNummer         BetValNummer,
     BetRglTeBetalen         TotaalTeBetalen
     from
      tabbetalingregel
      left outer join (tabNawFile inner join tabNawRekening on (NawRekNawGid = NawFilNawGid))
      on (NawFilRksGID = BetRglRksGid and NawFilFonID in ('C', 'D') and NawRekBankRekening = BetRglBankrekening) //ACW 10-12-2013 Naw kan zowel crediteur als debiteur zijn

     where BetRglBetKoPID      =  @BetKopID
           and (   BetRglTeBetalen <= 0
                or SoortReden > 2
                //or isnull(BetRglBankrekening,'')=''
                //or NawRekGid is null
                //or (@IsSepaBetaling = 1 and IsValidIban(BetRglBankrekening)=0) // WEL SEPA, maar geen geldige IBAN, dus ook fout!
                )


  UNION ALL

    // Deel 3: Opdrachtdatum in het verleden
   select
    4                       SoortReden,
    betRglRksGid            BetRksGid,
    betRglFactuurNummer     BetFactuurNummer,
    BetRglValNummer         BetValNummer,
    BetRglTeBetalen         TotaalTeBetalen
   from
    tabbetalingregel
   where
        betrglbetkopid    = @BetKopID
    and BetRglBetaalDatum < Date(Now())

  ) Betaling
  left outer join tabOpenstaandePost on (OspBjGid = @@BjGid and OspRksGid = BetRksGid and OspFactuurNummer = BetFactuurNummer)
  inner join tabRekeningSchema on (RksGid = BetRksGid)
  group by
   SoortReden, BetRksGid, RksInvoer, OspGid, FactuurNummer, ValNummer, DefaultSoort, OspGefiatteerd
  having
      (SoortReden = 1)
   or (SoortReden = 2 and (TotaalBedrag <= 0)) /*Te betalen bedrag moet positief zijn*/
   or (SoortReden = 3)                         /*Bankrekening is niet correct*/
   or (SoortReden = 4)                         /*Datum in het verleden*/
  order by
   RksInvoer, FactuurNummer, SoortReden
   ) BetalingBuiten
   where
      SoortReden in (2, 3, 4) or (SoortReden = 1 and (TeveelBetaald = 1 or OspGefiatteerd = 0));
end;

//------------------------------------------------------------
//---------- Factuur toevoegen aan betalingsvoorstel ---------
//------------------------------------------------------------

create or replace procedure BetvrstlToevoegenOsp(
 in  @BjGid                   integer,
 in  @BetKopId                integer,
 in  @IsBetalingInSEPAgebied  smallint, // 0, dan is het een betaling in het SEPA-gebied, anders erbuiten
 in  @VulKenmerk              integer,
 in  @OmsUwRef                smallint,
 in  @OmsUwRefTekst           nchar(10),
 in  @OmsOspOms               smallint,
 in  @OmsOnzeRef              smallint,
 in  @OmsOnzeRefTekst         nchar(10),
 in  @BetRglGid               integer,
 in  @OspGid                  integer,
 in  @BOBchequeVerzenden      nchar(1), // Komt uit de eigen bankrekening!
 in  @BOBsoortCrossen         nchar(1), // Komt uit de eigen bankrekening!
 in  @IsTestOnly              smallint,   // 0 => indien alles ok, dan toevoegen. 1 => doe alleen de test, voeg nooit toe
 in  @Gebruiksrechten         nchar(10), //A=fiatteren verkoopfactuur, B=Fiatteren inkoopfactuur
 in  @HeeftRechtdopb          smallint,
 out @Resultaat               integer,
 out @RksInvoer               nchar(28),
 out @FactuurNummer           nchar(40)
)
begin
  // @Resultaat ---> 0 = alles goed gegaan
  //                 1 = osp komt al voor
  //                 2 = osp is van debiteur  ACW 10-12-2013 ivm. betalingen creditnotas debiteuren is dit vervallen!
  //                 3 = voorstel bestaat niet meer
  //                 4 = osp al volledig afgeboekt
  //                 5 = totaal te betalen wordt negatief         mag nu wel !!
  //                 6 = osp is geblokkeerd
  //                 7 = bedrag onderweg is openstaand bedrag
  //                 8 = te betalen bedrag is negatief
  //                 9 = verzamelregel bestaat niet meer
  //                10 = Normale facturen van debiteuren niet toegestaan (we hebben nog geen verzamelen debiteuren)
  //                12 = Geen recht op betalen van debiteurfacturen
  //                14 = Geen fiatteerrecht op inkoopfacturen
  //                15 = Geen fiatteerrecht op verkoopfacturen
  declare @IsolationLevel     smallint;
  declare @Pernr              integer;
  declare @ValNummerVoorstel  integer;
  declare @IsBuitenland       smallint;
  declare @OspKenmerk         nchar(140);
  declare @OspOms             nchar(40);
  declare @Openstaand         numeric(15,2);
  declare @Onderweg           numeric(15,2);
  declare @TeBetalen          numeric(15,2);
  declare @TeBetalenInValuta  numeric(15,2);
  declare @BetaalDatumRegel   date;
  declare @RegelOms           nchar(250);
  declare @RegelKenmerk       nchar(140);
  declare @BankGiroRek        nchar(34);
  declare @IsBankGiroRekBuitenland smallint;
  declare @OspRksGid          integer;
  declare @MetBetaaldatum     smallint;
  declare @Betaaldatum        date;
  declare @Totaal             numeric(15,2);
  declare @VoorlopigeFacturen smallInt;
  declare @BOBsoortOpdracht       nchar(1);
  declare @BOBsoortUitvoering     nchar(1);
  declare @BOBkostenBinnenland    nchar(1);
  declare @BOBkostenCorrespondent nchar(1);
  declare @BOBbankBIC             nchar(11);
  declare @BOBbankNaam            nchar(35);
  declare @BOBbankPlaats          nchar(35);
  declare @BOBbankLndGid          integer;
  declare @BOBinstr1              nchar(2);
  declare @BOBinstr2              nchar(2);
  declare @BOBinstr3              nchar(2);
  declare @BOBinstr4              nchar(2);

  declare @RksDefaultSoort          smallint;
  declare @ospgefiatteerd           smallint;
  declare @GefiatteerdDoor          nchar(40);
  declare @GefiatteerdOp            DateTime;

  set @@ErrorTextProcedure = 'BetvrstlToevoegenOsp > @BetKopId='+string(@BetKopId)+', @OspGid='+string(@OspGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  set @BankGiroRek        = '';
  set @Resultaat          = 0;
  set @VoorlopigeFacturen = 1;

  select PeriodeBepalen(@BjGid, @@VerwerkingsDatum) into @Pernr;                                 // Periode voor omrekenen

  select BetKopValNummer, BetKopIsBuitenland into @ValNummerVoorstel, @IsBuitenland from tabBetalingKop where BetKopID = @BetKopId;

  if @BetRglGid is null then
    // geen verzameling, dus valuta van de kop gebruiken (indien GEEN valuta, dan is deze leeg en moet met de OSPvaluta worden gevuld
    if @ValNummerVoorstel is null then
      select OspValNummer  into @ValNummerVoorstel from tabOpenstaandePost where OspGid = @OspGid;
    end if;
  else
    // Aan verzameling toevoegen, dus ALTIJD de valuta van de verzameling gebruiken
    select BetRglValNummer into @ValNummerVoorstel from tabBetalingRegel where BetRglGid = @BetRglGid;
  end if;

  OspToevoegen:         // geen echte loop. handig voor stopen bij error. kan ook met ifs
  loop
    //--- kijken wat er als betaaldatum gebruikt moet worden
    // indien alle regels dezelfde datum gebruiken dan ook deze gebruiken, anders de vervaldatum van de OSP
    if (select count(distinct BetRglBetaalDatum) from tabBetalingRegel where BetRglBetKopId = @BetKopId)=1 then
      set @MetBetaalDatum = 1;
      select first BetRglBetaalDatum into @BetaalDatum from tabBetalingRegel where BetRglBetKopId = @BetKopId;
      //call Trace('@BetaalDatum='+string(@BetaalDatum));
    else
      //En als er nog geen regels zijn gebruiken we de datum van het voorstel
      if not exists(select 1 from tabBetalingRegel where BetRglBetKopId = @BetKopId) then
        set @MetBetaalDatum = 1;
        select BetKopVoorstelDatum into @BetaalDatum from tabBetalingKop where BetKopId =  @BetKopId;
      else
        set @MetBetaalDatum = 0;
        set @BetaalDatum    = null;
      end if;
    end if;

    //--- gegevens voor regel ophalen
    call BetvrstlVulRegelGegevensObvOsp(@BjGid, @PerNr, @ValNummerVoorstel, @VulKenmerk,
         @OmsUwRef, @OmsUwRefTekst, @OmsOspOms, @OmsOnzeRef, @OmsOnzeRefTekst,
         @MetBetaaldatum, @Betaaldatum, @OspGid, @VoorlopigeFacturen, @IsBuitenland, @IsBetalingInSEPAgebied, @FactuurNummer, @OspKenmerk, @OspOms, @Openstaand,
         @Onderweg, @TeBetalen, @TeBetalenInValuta, @BetaalDatumRegel, @RegelOms, @RegelKenmerk,
         @BankGiroRek, @IsBankGiroRekBuitenland, @OspRksGid, @RksInvoer, @ExternFact, @ExternFactRest,
         @BOBsoortOpdracht, @BOBsoortUitvoering, @BOBkostenBinnenland, @BOBkostenCorrespondent, @BOBbankBIC, @BOBbankNaam, @BOBbankPlaats, @BOBbankLndGid, @BOBinstr1, @BOBinstr2, @BOBinstr3, @BOBinstr4,
         @ospgefiatteerd, @GefiatteerdDoor, @GefiatteerdOp);


    select DefaultSoort into @RksDefaultSoort from tabRekeningSchema where RksGid = @OspRksGid;

    //--- controle of geselecteerde OSP wel van een crediteur is, anders teken omdraaien
    if @RksDefaultSoort = 6 /*Debiteur*/ then
      //ACW 13-12-2013: Is gewoon mogelijk, maar teken omdraaien bij een debiteur
      set @TeBetalen         = -@TeBetalen;
      set @TeBetalenInValuta = -@TeBetalenInValuta;
    end if;


    //--- controle of de post niet geblokkeerd is
    if (select OspIsGeblokkeerd from tabOpenstaandePost where OspGid = @OspGid) = 1 then
      set @Resultaat = 6;
      leave OspToevoegen;
    end if;

    //--- Controleer rechten op toevoegen debiteur
    if @RksDefaultSoort = 6 /*Debiteur*/ then
      if @HeeftRechtdopb = 0 then
        set @Resultaat = 12; // Geen recht op betalen van debiteurfacturen
        leave OspToevoegen;
      end if;
    end if;

    //--- Controleer fiatteringsrechten
    if @ospgefiatteerd = 0 then
      if locate(@Gebruiksrechten, if @RksDefaultSoort = 6 /*Debiteur*/ then 'A' else 'B' endif) = 0 then
        set @Resultaat = 14 + if @RksDefaultSoort = 6 then 1 else 0 endif; // Geen fiatteerrecht op inkoop ersp. verkoopfacturen
        leave OspToevoegen;
      end if;
      // Blijkbaar wordt de OSP op dit moment gefiatteerd, dus de huidige gebruiker opnemen
      set @GefiatteerdDoor = @@GebruikerCode;
      set @GefiatteerdOp   = now();
    end if;

    //call Trace('@ValNummerVoorstel='+string(@ValNummerVoorstel));
    //--- controle of voorstel nog bestaat
    if @ValNummerVoorstel is null then
      set @Resultaat = 3;
      leave OspToevoegen;
    end if;

    //--- Te betalen is negatief --> Niet toegestaan als lossen regel
    if (@TeBetalen < 0) and (@BetRglGid is null) then
      set @Resultaat = 8;
      leave OspToevoegen;
    end if;

    // Alle controles uitgevoerd  ---> Toevoegen van (verzamel)regel kan beginnen
    if @IsTestOnly = 0 then
      // Als de bankrekening NIET gelijk is aan het voorstel (qua binnen/buitenland), dan de rekening NIET opnemen!
      if @IsBankGiroRekBuitenland <> (select BetKopIsBuitenland from tabbetalingkop where BetKopId = @BetKopId) then
        set @BankGiroRek = '';
      end if;

      if (@BetRglGid is null) then
        //call Trace('Losse regel toevoegen; @ValNummerVoorstel='+string(@ValNummerVoorstel));
        insert into tabBetalingregel(BetrglBetKopId, BetrglBankrekening, BetRglBetaalDatum, BetRglOms, BetRglRksGid, BetRglFactuurNummer, BetRglTeBetalen,    BetRglValNummer,    BetRglBetKenmerk, BetRglIsVerzameld, BetRglVerschilAfboeken, BetRglVerschilAfboekenBedragInValOsp, BetRglBOBsoortOpdracht, BetRglBOBsoortUitvoering, BetRglBOBchequeVerzenden, BetRglBOBsoortCrossen, BetRglBOBkostenBinnen, BetRglBOBkostenCorrespondent, BetRglBOBbankBIC, BetRglBOBbankNaam, BetRglBOBbankPlaats, BetRglBOBbankLndGid, BetRglBOBinstr1, BetRglBOBinstr2, BetRglBOBinstr3, BetRglBOBinstr4, BetRglGefiatteerdDoor, BetRglGefiatteerdOp)
                    values          (@BetKopId,      @BankGiroRek,       @BetaalDatumRegel, @RegelOms, @OspRksGid  , @FactuurNummer     , @TeBetalenInValuta, @ValNummerVoorstel, @RegelKenmerk,    0,                 0,                      0,                                    @BOBsoortOpdracht,      @BOBsoortUitvoering,      @BOBchequeVerzenden,      @BOBsoortCrossen,      @BOBkostenBinnenland,  @BOBkostenCorrespondent,      @BOBbankBIC,      @BOBbankNaam,      @BOBbankPlaats,      @BOBbankLndGid,      @BOBinstr1,      @BOBinstr2,      @BOBinstr3,      @BOBinstr4, @GefiatteerdDoor, @GefiatteerdOp);


      else
        //call Trace('Regel aan verzamelopdracht toevoegen');
        Insert into tabBetalingVerzameld(BetVerzBetRglGid,  BetVerzFactuurNummer, BetVerzBankRekening, BetVerzBetaalDatum, BetVerzOms, BetVerzBetKenmerk, BetVerzTeBetalen,   BetVerzVerschilAfboekenBedragInValOsp, BetVerzVerschilAfboeken, BetVerzGefiatteerdDoor, BetVerzGefiatteerdOp)
                    values              (@BetRglGid,        @FactuurNummer,       @BankGiroRek,        @BetaalDatumRegel,  @RegelOms,  @RegelKenmerk,     @TeBetalenInValuta, 0,                                     0,                       @GefiatteerdDoor,       @GefiatteerdOp);

        // bepaal betalingskede omschrijving van de verzamelregel
        call BetRglVerzamelOmschrijving(@BetRglGid, @RksInvoer,  @OmsUwRef,        @OmsUwRefTekst,
                                        0,          @OmsOnzeRef, @OmsOnzeRefTekst, @RegelOms);

        // bijweken totaal/oms
        update tabBetalingregel
        set    BetRglTeBetalen   = BetRglTeBetalen + @TeBetalenInValuta,
               betrgloms         = if BetRglIsOmsAangepast = 0 then _A('NIET aangepast') + @RegelOms else _A('AANGEPAST') + betrgloms endif,
               BetRglBetaalDatum = (select min(BetVerzBetaalDatum) from tabBetalingVerzameld where (BetVerzBetRglGid = @BetRglGid))
        where (BetRglGid = @BetRglGid)
      end if;
    end if;

    leave OspToevoegen;

  end loop OspToevoegen;

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  set @@ErrorTextProcedure = 'BetvrstlToevoegenOsp > @Resultaat='+string(@Resultaat);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BetVrstlVerwijderen(in @BetKopId integer)
begin
  set @@ErrorTextProcedure = 'BetvrstlVerwijderen > @BetKopID='+String(@BetKopID);
  //call TraceBegin(@@ErrorTextProcedure);

  // Als er een bedrag onderweg in de regel is ingevuld, dan die ALTIJD weer bij de openstaande post optellen!
  // Eerst alle verzamelregels
/* ACW 2007-10-11: Gaat niet meer op omdat de triggers dit oplossen
  update tabOpenstaandePost
  set    OspBedragOnderwegInValuta = OspBedragOnderwegInValuta - BetVerzBedragOnderweg
  from   tabBetalingRegel inner join tabBetalingVerzameld on (BetVerzBetRglGid = BetRglGid)
  where      BetRglBetKopId        =  @BetKopID
         and OspFactuurNummer      =  BetVerzFactuurnummer
         and OspRksGid             =  BetRglRksGid
         and OspBjGid              =  @@BjGid
         and BetVerzBedragOnderweg <> 0;

  // Daarna alle overige regels
  update tabOpenstaandePost
  set    OspBedragOnderwegInValuta = OspBedragOnderwegInValuta - BetRglBedragOnderweg
  from   tabBetalingRegel
  where      BetRglBetKopId       =  @BetKopID
         and OspFactuurNummer     =  BetRglFactuurNummer
         and OspRksGid            =  BetRglRksGid
         and OspBjGid             =  @@BjGid
         and BetRglBedragOnderweg <> 0;
*/
  //--- Als laatste de kop verwijderen; de regels gaan dan vanzelf wel mee
  delete from tabBetalingKop where BetKopId = @BetKopId;

  set @@ErrorTextProcedure = 'BetvrstlVerwijderen';
  //call TraceBegin(@@ErrorTextProcedure);

end;


//-----------------------------------------------------------------------------------
//---------- Ophalen gegevens voor het toevoegen van betalingsvoorstelregel ---------
//-----------------------------------------------------------------------------------

//--- ophalen factuurgegeven tbv toevoegen aan betalingsvoorstel
create or replace procedure BetvrstlVulRegelGegevensObvOsp(
 in  @BjGid integer,
 in  @PerNr integer,
 inout @ValNummerVoorstel integer,  // Let op: Indien LEEG meegegeven, dan wordt hier de valuta van de OSP in gezet!!
 in  @VulKenmerk integer,
 in  @OmsUwRef smallint,
 in  @OmsUwRefTekst nchar(10),
 in  @OmsOspOms smallint,
 in  @OmsOnzeRef smallint,
 in  @OmsOnzeRefTekst nchar(10),
 in  @MetBetaaldatum smallint,
 in  @Betaaldatum date,
 in  @OspGid integer,
 in  @VoorlopigeFacturen smallInt,
 in  @IsBuitenland smallint,
 in  @IsBetalingInSEPAgebied smallInt,
 out @FactuurNummer nchar(40),
 out @OspKenmerk nchar(140),
 out @OspOms nchar(40),
 out @Openstaand numeric(15,2),
 out @Onderweg numeric(15,2),
 out @TeBetalen numeric(15,2),
 out @TeBetalenInValuta numeric(15,2),
 out @BetaalDatumRegel date,
 out @RegelOms nchar(250),
 out @RegelKenmerk nchar(140),
 out @BankGiroRek nchar(40),
 out @IsBankGiroRekBuitenland smallint,
 out @OspRksGid integer,
 out @OspRksInvoer nchar(28),
 out @ExternFact nchar(40),
 out @ExternFactRest nchar(40),
 out @BOBsoortOpdracht       nchar(1),
 out @BOBsoortUitvoering     nchar(1),
 out @BOBkostenBinnenland    nchar(1),
 out @BOBkostenCorrespondent nchar(1),
 out @BOBbankBIC             nchar(11),
 out @BOBbankNaam            nchar(35),
 out @BOBbankPlaats          nchar(35),
 out @BOBbankLndGid          integer,
 out @BOBinstr1              nchar(2),
 out @BOBinstr2              nchar(2),
 out @BOBinstr3              nchar(2),
 out @BOBinstr4              nchar(2),
 out @OspGefiatteerd         smallint,
 out @GefiatteerdDoor        nchar(40),
 out @GefiatteerdOp          DateTime
)
begin
  declare @BankIsVoorBetaling  smallInt;
  declare @NawRekGid           integer;
  declare @NawRekIsBuitenland  smallint;
  declare @OspValNummer        integer; // Slechts overzetten in @ValNummerVoorstel inden @ValNummerVoorstel LEEG is!

  set @@ErrorTextProcedure = 'BetvrstlVulRegelGegevensObvOsp > @BjGid='+string(@BjGid)+', '+string(@PerNr);
  //call TraceBegin(@@ErrorTextProcedure);

  set @RegelOms     = '';
  set @RegelKenmerk = '';
  //--- gegevens voor regel ophalen
  select OspRksGid,
         OspRksInvoer,
         OspFactuurNummer,
         OspBetalingsKenmerk,
         OspOms,
         if @MetBetaalDatum = 1 then
           @Betaaldatum
         else
           (if OspVervaldatum < Now() then date(Now()) else OspVervalDatum endif)
         endif as BetaalDatum,
         (FactuurBedrag(OspFactuurBedragDefinitief, OspFactuurBedragVoorlopig, @VoorlopigeFacturen) - OspBetaaldBedragDefinitief - OspBetaaldBedragVoorlopig) as Openstaand,
         (OspBedragOnderwegInValuta) as Onderweg, // Let op: Hier gaan we er al van uit dat het bedrag onderweg ALTIJD in de OSP-valuta staat!!
         (Openstaand - Onderweg -
          //ACW Voor debiteuren het teken omdraaien (want een betaling aan een debiteur is eigenlijk een verhoging van het openstaand saldo)
          if Defaultsoort = 6 /*Debiteur*/ then -1 else 1 endif *
          (
           isnull((select sum(BetRglTeBetalenInValOsp + (BetRglVerschilAfboeken * BetRglVerschilAfboekenBedragInValOsp))            // Bedrag in nog niet verwerkte voorstellen
                   from   tabOpenstaandePost binnen
                          inner join tabBetalingRegel on (BetRglRksGid = OspRksGid and BetRglFactuurNummer_Lengte = Length(OspFactuurNummer) and BetRglFactuurnummer = OspFactuurNummer)
                          inner join tabBetalingKop on (BetKopID = BetRglBetKopID)
                   where  binnen.OspGid = Buiten.OspGid
                      and BetRglStatus  = 0 // Is nog voorstel
            ), 0) +
            isnull((select sum(BetVerzTeBetalenInValOsp + (BetVerzVerschilAfboeken * BetVerzVerschilAfboekenBedragInValOsp))           // Bedrag in verzamelde nog niet verwerkte voorstellen
                    from   tabOpenstaandePost binnen
                           inner join tabBetalingVerzameld on (BetVerzFactuurnummer_Lengte = length(binnen.OspFactuurNummer) and BetVerzFactuurnummer = binnen.OspFactuurNummer)
                           inner join tabBetalingRegel on (BetRglRksGid = binnen.OspRksGid and BetVerzBetRglGid=BetRglGid)
                           inner join tabBetalingKop on (BetKopID = BetRglBetKopID)
                    where  binnen.OspGid = Buiten.OspGid
                       and BetRglStatus  = 0 // Is nog voorstel
            ), 0)
          )
         ) as TeBetalen,
         if @ValNummerVoorstel is not null and (OspValNummer <> @ValNummerVoorstel) then
           ValutaOmrekenen(OspValnummer, TeBetalen, @ValNummerVoorstel, @BjGid, @Pernr, 2)
         else
           TeBetalen
         endif,
         OspValNummer,
         OspGefiatteerd,
         OspFiatteringGewijzigdDoor,
         OspFiatteringGewijzigdOp

  into   @OspRksGid, @OspRksInvoer, @FactuurNummer, @OspKenmerk, @OspOms, @BetaalDatumRegel, @Openstaand, @Onderweg, @TeBetalen, @TeBetalenInValuta, @OspValNummer,
         @OspGefiatteerd, @GefiatteerdDoor, @GefiatteerdOp
  from   tabOpenstaandePost buiten
         inner join tabRekeningschema on RksGid = OspRksGid
  Where  (OspGid=@OspGid);

  if @ValNummerVoorstel is null then
    set @ValNummerVoorstel = @OspValNummer;
  end if;

  //ophalen rekening tbv betalingen
  call BetvrstlBepaalBankGiroRek(@OspRksInvoer, @IsBetalingInSEPAgebied, @BankGiroRek, @BankIsVoorBetaling, @NawRekGid, @NawRekIsBuitenland);

  // Codelijsten van de bankrekening opvragen
  if @NawRekGid is null then
    set @BOBsoortOpdracht       = null;
    set @BOBsoortUitvoering     = null;
    set @BOBkostenBinnenland    = null;
    set @BOBkostenCorrespondent = null;
    set @BOBbankBIC             = null;
    set @BOBbankNaam            = null;
    set @BOBbankPlaats          = null;
    set @BOBbankLndGid          = null;
    set @BOBinstr1              = null;
    set @BOBinstr2              = null;
    set @BOBinstr3              = null;
    set @BOBinstr4              = null;
  else
    select NawRekSoortOpdracht, NawRekSoortUitvoering, NawRekKostenBinnen,   NawRekKostenCorrespondent, NawRekBankBIC, NawRekBankNaam, NawRekBankPlaats, NawRekBankLndGid, NawRekBobInstr1, NawRekBobInstr2, NawRekBobInstr3, NawRekBobInstr4
    into   @BOBsoortOpdracht,   @BOBsoortUitvoering,   @BOBkostenBinnenland, @BOBkostenCorrespondent,   @BOBbankBIC,   @BOBbankNaam,   @BOBbankPlaats,   @BOBbankLndGid,   @BOBinstr1,      @BOBinstr2,      @BOBinstr3,      @BOBinstr4
    from   tabNawRekening
    where  NawRekGid = @NawRekGid;
  end if;


  // bepaal exeternfactuurnummer
  call ZoekExternFactuurnummer(@OspRksGid, @Factuurnummer, @OspKenmerk, @ExternFact, @ExternFactRest);

  // vul betalingskenmerk en omschrijving tbv betalingsopdrachtregel
  if @IsBuitenland = 0 then
    case @VulKenmerk
      // niet invullen
      when 0 then  set @RegelKenmerk = '';
      // pos 1-16 uit OSP of gehele OSPkenmerk
      when 1 then
        if @IsBetalingInSEPAgebied = 0 then
          set @RegelKenmerk = Left(@OspKenmerk, 16);
        else
          // ACW 18-09-2012 Onderdeel 53435: SEPA kan het gehele OSPkenmerk aan!
          set @RegelKenmerk = @OspKenmerk;
        end if;
      // factuurnummer
      when 2 then set @RegelKenmerk = @Factuurnummer;
      // factuurnummer uit betalingskenmerk OSP
      when 3 then set @RegelKenmerk = @ExternFact;
    end case;
  else
    // Buitenlandse betalingen hebben geen betalingskenmerk-veld
    set @RegelKenmerk = '';
  end if;
  // vullen van omschrijvingveld
  set @RegelOms = '';
  // Uw referentie meenemen
  if (@OmsUwRef = 1) and (Trim(@OspKenmerk) <>'') then
    if trim(@OmsUwRefTekst) <> '' then
      set @RegelOms = @RegelOms + MultipleToSingleSpace(@OmsUwRefTekst) + ' ';
    end if;
    set @RegelOms = @RegelOms + MultipleToSingleSpace(@OspKenmerk);
  end if;
  // Omschrijving uit OSP meenemen
  if (@OmsOspOms = 1) and (Trim(@OspOms) <>'') then
    if (Trim(@RegelOms) <> '') then
      set @RegelOms = @RegelOms + char(13) + char(10);
    end if;
    set @RegelOms = @RegelOms + MultipleToSingleSpace(@OspOms);
  end if;
  // onze referentie meenemen
  if (@OmsOnzeRef = 1) then
    if Trim(@RegelOms) <> '' then
      set @RegelOms = @RegelOms + char(13) + char(10);
    end if;
    if trim(@OmsOnzeRefTekst) <> '' then
      set @RegelOms = @RegelOms + MultipleToSingleSpace(@OmsOnzeRefTekst) + ' ';
    end if;
    set @RegelOms = @RegelOms + @OspRksInvoer + ' ' + Trim(@Factuurnummer);
  end if;

  set @@ErrorTextProcedure = 'BetvrstlVulRegelGegevensObvOsp > @FactuurNummer='+@FactuurNummer + '; @OspRksGid='+string(@OspRksGid);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BijwerkenVoorraadAantallen(
  in @ArtGid integer,
  in @MagGid integer,
  in @LocGid integer,
  in @PartijGid integer,
  in @SerieGid integer,
  in @Aantal numeric(15,3),
  in @SoortMutatie smallint,
  in @Mutatiedatum date
)
begin
  // Verwerken van voorraadmutatielocatieregel in tabArtikel, tabArtikelLocatie, tabArtikelMagazijn, tabArtikelPartij
  // Deze routine past alle relevante aantallen aan.
  // Er wordt al uitgegaan dat de records in de database bestaan!

  declare @ArtLocGid integer;
  declare @ArtMagGid integer;
  declare @DefaultLocGid   integer;
  declare @RecordHeeftPartij smallint;
  declare @RecordHeeftVoorraad smallint;
  declare @MaxLoopCount smallint = 5;


  set @@ErrorTextProcedure = 'BijwerkenVoorraadAantallen > @ArtGid = ' + string(@ArtGid);
  //call TraceBegin(@@ErrorTextProcedure);

  // (20209) BijwerkenVoorraadAantallen mag niet direct worden aangeroepen!
  if @@FiredByTriggerVoorraadMutatieLocatie = 0 then
    raiserror 20209;
  end if;

  // Verwerken in tabArtikelLocatie (per partij)
  //set @@ErrorTextProcedure = 'BijwerkenVoorraadAantallen > Verwerken in tabArtikelLocatie';

  //Als GEEN optie m1('43 magazijnen en locaties'):
  //Een artikel kan per magazijn maar op 1 locatie liggen
  //Eerst bestaande artikellocaties omgooien naar deze locatie, zodat er niet een nieuwe artikellocatie record toegevoegd wordt
  //Dus ArtMagDefaultLocGid aanpassen, in trigger worden dan weer tabArtikelLocatie aangepast.
  //Als er nog geen record bestaat in tabArtikelMagazijn, dan bestaat er ook nog geen record(s) in tabArtikelLocatie, dus dan geen acties nodig
  if @@ModuleM1 = 0 then
    select ArtMagDefaultLocGid into @DefaultLocGid from tabArtikelMagazijn where ArtMagArtGid = @ArtGid and ArtMagMagGid = @MagGid;
    if @LocGid <> IsNull(@DefaultLocGid,0) then
      update tabArtikelMagazijn set ArtMagDefaultLocGid = @LocGid where ArtMagArtGid = @ArtGid and ArtMagMagGid = @MagGid;
    end if;
  end if;



    // Zoek juiste record, eerst zonder mutex, indien niet gevonden, dan met
  loop
    begin
      declare DUPLICATE_RECORD EXCEPTION FOR SQLSTATE 'WW012';
      select ArtLocGid, if ArtLocPartijGid is null then 0 else 1 endif, if ArtLocVoorraad = 0 then 0 else 1 endif
      into   @ArtLocGid, @RecordHeeftPartij, @RecordHeeftVoorraad
      from   tabArtikelLocatie
      where  ArtLocLocGid = @LocGid
         and ArtLocArtGid = @ArtGid
         and (   (ArtLocPartijGid is null)
              or (ArtLocPartijGid = @PartijGid)
             )
      order by ArtLocPartijGid desc; // Liefst die met de juiste partij

      if @ArtLocGid is not null and @PartijGid is not null then
        // We zoeken een record met partij
        if @RecordHeeftPartij = 0 then
          // Gevonden record heeft geen partij
          if @RecordHeeftVoorraad = 0 then
            // gevonden record heeft ook geen voorraad, dus die kunnen we aanpassen (deze partij eraan toevoegen)
            update tabArtikelLocatie set ArtLocPartijGid = @PartijGid where ArtLocGid = @ArtLocGid;
          else
            // Gevonden record heeft wel voorraad, dus doe alsof we die niet hebben gevonden (zodat we een nieuwe aanmaken met deze partij)
            set @ArtLocGid = null;
          end if;
        end if;
      end if;

      if @ArtLocGid is null then
        // ArtMagGid is al aangemaakt!
        insert into tabArtikelLocatie(ArtLocArtGid, ArtLocArtMagGid, ArtLocLocGid, ArtLocPartijGid, ArtLocVoorraad,
                                      ArtLocLaatsteInventarisatieOp)
        values(@ArtGid, @ArtMagGid, @LocGid, @PartijGid, @aantal,
               if @SoortMutatie = 3 /*Inventariatie*/ then @Mutatiedatum endif);
      else
        update tabArtikelLocatie
        set    ArtLocVoorraad = ArtLocVoorraad + @aantal,
               ArtLocLaatsteInventarisatieOp = if @SoortMutatie = 3 /*Inventariatie*/ then @Mutatiedatum else ArtLocLaatsteInventarisatieOp endif
        where ArtLocGid = @ArtLocGid;
      end if;
      // Gelukt, dus klaar
      leave;
    exception
      when DUPLICATE_RECORD then // Doen we nog een keer
          if locate(error_message(), '20721') = 0 then
            resignal;
          end if; // Vreet de Komt al voor-exception op en probeer nog een keer (2e keer zal het dus UPDATE worden ipv INSERT
      when others        then resignal; // Overige fouten doorgeven
    end;
    set @MaxLoopCount = @MaxLoopCount - 1;
    if @MaxLoopCount <= 0 then
      if @aantal <> 0 and @ArtLocGid is null then
        // We moeten een aantal kwijt, maar dat is na 5x nog niet gelukt! Dan maar terugmelden
        call raise(20721, _U('Artikellocatie%1!' , if @PartijGid is null then '' else ' (met partij)' endif)); //(20721) %1! komt al voor!
      end if;
      leave;
    end if;
  end loop;

  // Verwerken in tabArtikelMagazijn
  // Let op: Deze pas NA de ArtikelLocatie omdat de ArtikelLocatie evt. de ArtikelMagazijn aanmaakt!
  //set @@ErrorTextProcedure = 'BijwerkenVoorraadAantallen > Verwerken in tabArtikelMagazijn';
  // Magazijn bestaat ALTIJD al (?)
  select ArtMagGid into @ArtMagGid from tabArtikelMagazijn where ArtMagArtGid = @ArtGid and ArtMagMagGid = @MagGid;

  // (20205) Magazijn is geen magazijn voor dit artikel!
  if @ArtMagGid is null then
    raiserror 20205;
  end if;

  // Partij-afhankelijke gegevens verwerken
  if @PartijGid is null then

    //Toch een serienummer gevonden? -> FOUT!
    //(20206) Serienummer van een artikel gevonden zonder corresponderende partij!
    if @SerieGid is not null then
      raiserror 20206;
    end if;
  end if;


  set @@ErrorTextProcedure = 'BijwerkenVoorraadAantallen';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BoekdatumGenereren(in @BjGid integer, in @BoekGangGid integer, in @JpNummer integer, in @DgbGid integer, out @BoekDatum date)
begin
  //------- Genereer een nieuwe boekdatum a.d.h.v. een dagboek en zijn instellingen
  declare @DefBoekdatum smallint;

  set @@ErrorTextProcedure = 'BoekdatumGenereren > @BjGid='+string(@BjGid)+', @BoekGangGid='+string(@BoekGangGid)+', @JpNummer='+string(@JpNummer)+', @DgbGid='+string(@DgbGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select DefBoekdatum into @DefBoekdatum from tabDagboek where DgbGid=@DgbGid;

  if @DefBoekDatum = 0 then           //Leeg
    set @BoekDatum = null;
  else
    if @DefBoekDatum = 1 then         //Verwerkingsdatum
      set @BoekDatum = @@VerwerkingsDatum;
    else
      if @DefBoekDatum = 3 then         //systeemdatum
        set @BoekDatum = now()
      else                       //Zelfde als vorige Journaalpost
        //Zoek de datum van de vorige Journaalpost binnen deze boekingsgang
        select first BoekDatum into @BoekDatum from tabJournaalpost where (JpBoekGangGid = @BoekGangGid) and (JpNummer<@JpNummer) and ((JpDgbGid=@DgbGid) or (@DgbGid is null)) order by JpNummer desc;
        if @BoekDatum is null then    //Indien niet gevonden dan datum overnemen van de laatst gebruikte Journaalpost binnen het dagboek
           //call Trace('Ga naar BoekdatumVorigeJournaalPost');
           call BoekdatumVorigeJournaalPost(@BoekGangGid, @DgbGid, 2000000000, @Boekdatum);
        end if;
        if @BoekDatum is null then    //Indien ook deze niet gevonden dan huidige datum overnemen
          set @BoekDatum = @@VerwerkingsDatum;
        end if;
      end if;
    end if;
  end if;

  //call TraceEind('BoekdatumGenereren ------> @Boekdatum='+string(@BoekDatum));

end;


create or replace procedure BoekdatumVorigeJournaalPost(in @BoekGangGid integer, in @DgbGid integer, in @JpNummer integer, inout @Boekdatum date)
begin
  set @@ErrorTextProcedure = 'BoekdatumVorigeJournaalPost > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BoekGangGid = ' + string(@BoekGangGid) + ', @DgbGid = ' + string(@DgbGid) + ', @JpNummer = ' + string(@JpNummer));

  set @BoekDatum = null;

  select first BoekDatum into @BoekDatum from tabJournaalpost
  where  JpBoekGangGid=@BoekGangGid and JpDgbGid=@DgbGid and JpNummer<@JpNummer order by JpNummer desc;

  if @BoekDatum is null then
    select first BoekDatum into @BoekDatum from tabJournaalpost, tabBoekingsgang
    where BoekGangGid = @BoekGangGid and BoekGangBjGid = JpBjGid and JpDgbGid = @DgbGid order by Jpgid desc;  //Geen join tussen journaalpost en boekingsgang o.b.v. boekganggid. We hebben hier alleen maar het bjgidje nodig uit tabboekingsgang
  end if;

  set @@ErrorTextProcedure = 'BoekdatumVorigeJournaalPost';
  //call TraceEind(@@ErrorTextProcedure + ' > @BoekDatum = ' + string(@BoekDatum) + ', @DgbGid = ' + string(@DgbGid) + ', @JpNummer = ' + string(@JpNummer));
end;


create or replace procedure BoekenMutatieObvProject(
in @BoekgangPbkGid      integer,
in @PvcGid              integer,
in @PbGid               integer,
in @RegelsSamenvoegen   smallint,
in @AantalVerminderen   smallint,
in @PrijsOpnieuwBepalen smallint,
in @MdwRelGid           integer,
in @LevNawGid           integer,
in @HeeftRechtUpmu      smallint,
in @HeeftRechtUpmv      smallint,
in @HeeftRechtUpmm      smallint,
in @HeeftRechtUpma      smallint,
in @SessieNr            integer,
in @AantalCats          integer
)
begin
  declare @PvcPbGid              integer;
  declare @PvcArtGid             integer;
  declare @PvcRelGid             integer;
  declare @PvcIsDirecteInkoop    smallint;
  declare @PvcLeverancierNawGid  integer;
  declare @PvcPdosGid            integer;
  declare @PvcArtPartijGid       integer;

  declare @PvcDoorbelastPerc     numeric(15,2);

  declare local temporary table tmpPvcGidjes (
    tmpPvcGid integer
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'BoekenMutatieObvProject > @BoekgangPbkGid='+String(@BoekgangPbkGid)+', @PvcGid='+String(@PvcGid)+', @PbGid='+string(@PbGid)+', @RegelsSamenvoegen='+string(@RegelsSamenvoegen)+', @AantalVerminderen='+string(@AantalVerminderen)+' @LevNawGid='+string(@LevNawGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @HeeftRechtUpmu = IsNull(@HeeftRechtUpmu, 0);
  set @HeeftRechtUpmv = IsNull(@HeeftRechtUpmv, 0);
  set @HeeftRechtUpmm = IsNull(@HeeftRechtUpmm, 0);
  set @HeeftRechtUpma = IsNull(@HeeftRechtUpma, 0);


  if @PvcGid is not null then
    if @RegelsSamenvoegen = 1 then
      select PvcPbGid, PvcArtGid, PvcArtPartijGid, PvcRelGid, PvcIsDirecteInkoop, PvcLeverancierNawGid, PvcPdosGid, PvcDoorbelastPercentage
      into   @PvcPbGid, @PvcArtGid, @PvcArtPartijGid, @PvcRelGid, @PvcIsDirecteInkoop, @PvcLeverancierNawGid, @PvcPdosGid, @PvcDoorbelastPerc
      from   tabProjectVoorcalculatie
      where  PvcGid = @PvcGid;

      if @PvcDoorbelastPerc is null and @AantalVerminderen = 1 then
        insert into tmpPvcGidjes (tmppvcgid)
        select pvcgid
        from tabprojectvoorcalculatie
        where PvcPbGid = @PvcPbGid and PvcArtGid = @PvcArtGid and IsNull(PvcArtPartijGid,0) = IsNull(@PvcArtPartijGid,0) and IsNull(PvcRelGid,0) = IsNull(@PvcRelGid,0) and PvcIsDirecteInkoop = @PvcIsDirecteInkoop and IsNull(PvcLeverancierNawGid,0) = IsNull(@PvcLeverancierNawGid,0) and IsNull(PvcPdosGid,0) = IsNull(@PvcPdosGid,0) and PvcDoorbelastPercentage is null;
      else
        insert into tmpPvcGidjes (tmppvcgid) values(@PvcGid);
      end if;
    else
      insert into tmpPvcGidjes (tmppvcgid) values(@pvcgid);
    end if;
  else
    // Vullen obv. de PbGid (de hele tak, afhankelijk van filter)
    insert into tmpPvcGidjes (tmppvcgid)
    select pvcgid
    from   tabprojectvoorcalculatie
    where
         @PbGid is not null
     and pvcPbGid in (select PbpPbGid from tabProjectBoomPad where PbpParentPbGid = @PbGid union select @PbGid)
     and (
          (select count (*) from tabProjectSelectieCode
                                 inner join tmpProjSelCodes on tmpPscCode = PscCode and tmpPscSessieNr = @SessieNr
           where PscPvcGid = PvcGid)
          >= @AantalCats
         )
  end if;

  //20280: U heeft onvoldoende rechten om een of meer voorcalculatieregels te boeken!
  if exists(select 1
            from tmpPvcGidjes inner join tabProjectVoorcalculatie on (PvcGid = tmpPvcGid)
            where    (PvcMutSoort = 1 and @HeeftRechtUpmm = 0) //machines en geen recht invoeren machinemutaties
                  or (PvcMutSoort = 2 and @HeeftRechtUpma = 0) //artikelen en geen recht invoeren artikelmutaties
                  or (PvcMutSoort = 0 and @HeeftRechtUpmu = 0) //activiteiten en geen recht invoeren activiteiten
                  or (PvcMutSoort = 0 and @HeeftRechtUpmv = 0  //activeiten en geen recht invoeren activiteiten voor anderen
                      and (PvcRelGid <> IsNull((select first PmwRelGid from tabprojectMedewerker where pmwRelGid in (select GebrRelGid from tabgebruiker where GebruikerGid = @@GebruikerGid)), -1)))) then
    call Raise(20280);
  end if;

  if @RegelsSamenvoegen = 1 then
    insert into tabProjectBoekingsregel
     (PbrPbkGid           , PbrPbGid    , PbrArtGid               , PbrArtPartijGid           , PbrIsDirecteInkoop,
      PbrMagGid           , PbrLocGid   ,
      PbrLeverancierNawGid, PbrKostprijs, PbrKostprijsRegelTotaal , PbrMutSoort               , PbrPdosGid        ,
      PbrProjGid          , PbrOmschr   , PbrVerkoopprijs         , PbrVerkoopprijsRegelTotaal, PbrAantalGeboekt  ,
      PbrAantalDeclarabel , PbrPrijsPer , PbrPartFactEenheidFactor, PbrRelGid                 , PbrSelectieCodes,
      PbrMutatieDatum, PbrDoorbelastPercentage, PbrUrenIngevoerdAls)
    select
      // Regel 1
      @BoekgangPbkGid,
      PvcPbGid,
      PvcArtGid,
      IsNull(Max(PvcArtPartijGid), (select ArtPartijGid from tabArtikel inner join tabArtikelPartij on (ArtPartijArtGid = ArtGid) where ArtGid = PvcArtGid and ArtIsPartijRegistreren = 0 and ArtSerieNrRegistreren = 1)),
      PvcIsDirecteInkoop,
      // Regel 2
      if ArtSoort = 2 /*Artikel*/ and ArtHeeftVoorraad <> 0 and PvcIsDirecteInkoop = 0 then
        isnull(ArtDefaultMagGid,                                          // Default magazijn van het artikel
               (select ToeMagMagGid from tabToegestaneMagazijnen where ToeMagToepassing = 60 /*Projectmutaties*/ and ToeMagGebrGid = @@GebruikerGid), // Default magazijn voor deze gebruiker + toepassing
               (select first MagGid from tabMagazijn where MagCode = 1)) // Magazijn 001
      endif PbrMagGid,
      if PbrMagGid is not null then
        isnull((select ArtMagDefaultLocGid from tabartikelmagazijn where ArtMagMagGid = PbrMagGid and ArtMagArtGid = PvcArtGid),
               (select LocGid from tabLocatie where LocMagGid = PbrMagGid and LocNaam = '(Standaard)'))
      endif PbrLocGid,
      // Regel 3
      IsNull(PvcLeverancierNawGid,@LevNawGid) as Lev,
      // bugdoc:27681 Kostprijs niet opnieuw bepalen als overige kosten/doorbelasting ingevuld
      if @PrijsOpnieuwBepalen=0 or PvcDoorbelastPercentage is not null then (sum(PvcKostprijsRegelTotaal) / sum(PvcBudAantal)) * PrijsPer endif as Kostprijs,
      ((Kostprijs * AantalTeBoeken) / PrijsPer) as KostprijsRegelTotaal,
      PvcMutSoort,
      PvcPdosGid,
      // Regel 4
      PvcProjGid,
      Max(PvcOmschr),
      if @PrijsOpnieuwBepalen=0 then if Sum(PvcOffAantal) = 0 then sum(PvcVerkoopprijsRegelTotaal) else (sum(PvcVerkoopprijsRegelTotaal) / Sum(PvcOffAantal)) * PrijsPer endif endif Verkoopprijs,
      ((Verkoopprijs * AantalTeBoeken) / PrijsPer) / Max(PvcPartFactEenheidFactor)  as VerkoopprijsRegeltotaal,
      sum(PvcBudAantal) - if @AantalVerminderen = 1 then IsNull((select sum(PbrAantalGeboekt) from tabProjectBoekingsregel
        where PbrPbGid = PvcPbGid and PbrArtgid = PvcArtGid and IsNull(PbrArtPartijGid,0) = IsNull(PvcArtPartijGid,0) and IsNull(PbrRelGid,0) = IsNull(Medewerker,0) and PbrIsDirecteInkoop = PvcIsDirecteInkoop and IsNull(PbrLeverancierNawGid,0) = IsNull(Lev,0) and IsNull(PbrPdosGid,0) = IsNull(PvcPdosGid,0)), 0) else 0 endif as AantalTeBoeken,
      // Regel 5
      AantalTeBoeken / max(PvcPartFactEenheidFactor) as AantalDeclarabel,
      // Let op: in geval van Doorbelasting altijd 1, dus hoeft niet opnieuw bepaald te worden; anders wordt ook kostprijs niet goed berekend.
      if @PrijsOpnieuwBepalen=0 or PvcDoorbelastPercentage is not null then Max(PvcPrijsPer) endif as PrijsPer,
      if @PrijsOpnieuwBepalen=0 then Max(PvcPartFactEenheidFactor) endif,
      if PvcMutSoort=0 then IsNull(PvcRelGid, @MdwRelGid) endif as Medewerker,
      max(PvcSelectieCodes),
      // Regel 6
      @@VerwerkingsDatum,
      if @PrijsOpnieuwBepalen=0 then PvcDoorbelastPercentage endif DoorbelastPercentage,
      0
    from
      tmpPvcGidjes
      inner join      tabProjectVoorcalculatie on (pvcGid = tmppvcgid)
      left outer join tabArtikel               on (ArtGid = pvcArtGid)
    group by PvcProjGid, PvcPbGid, PvcArtGid, PvcArtPartijGid, ArtDefaultMagGid, ArtSoort, ArtHeeftVoorraad, Medewerker, PvcPdosGid, PvcIsDirecteInkoop, Lev, PvcMutSoort,
             PvcDoorbelastPercentage, if PvcDoorbelastPercentage is not null then PvcGid endif //TG 15-10-2007: regels met een doorbelastingspercentage mogen nooit samengevoegd worden!
    //<>0 erbij ivm bug 29263
    having (@RegelsSamenvoegen=0 and AantalTeBoeken <> 0) or (@RegelsSamenvoegen=1 and AantalTeBoeken > 0);
  else
    insert into tabProjectBoekingsregel
     (PbrPbkGid           , PbrPbGid    , PbrArtGid               , PbrArtPartijGid           , PbrIsDirecteInkoop,
      PbrMagGid           , PbrLocGid   ,
      PbrLeverancierNawGid, PbrKostprijs, PbrKostprijsRegelTotaal , PbrMutSoort               , PbrPdosGid        ,
      PbrProjGid          , PbrOmschr   , PbrVerkoopprijs         , PbrVerkoopprijsRegelTotaal, PbrAantalGeboekt  ,
      PbrAantalDeclarabel , PbrPrijsPer , PbrPartFactEenheidFactor, PbrRelGid                 , PbrSelectieCodes,
      PbrMutatieDatum, PbrDoorbelastPercentage, PbrUrenIngevoerdAls)
    select
      // Regel 1
      @BoekgangPbkGid,
      PvcPbGid,
      PvcArtGid,
      IsNull(PvcArtPartijGid, (select ArtPartijGid from tabartikel inner join tabArtikelPartij on (ArtPartijArtGid = ArtGid) where ArtGid = PvcArtGid and ArtIsPartijRegistreren = 0 and ArtSerieNrRegistreren = 1)),
      PvcIsDirecteInkoop,
      // Regel 2
      if ArtSoort = 2 /*Artikel*/ and ArtHeeftVoorraad <> 0 and PvcIsDirecteInkoop = 0 then
        isnull(ArtDefaultMagGid,                                          // Default magazijn van het artikel
               (select ToeMagMagGid from tabToegestaneMagazijnen where ToeMagToepassing = 60 /*Projectmutaties*/ and ToeMagGebrGid = @@GebruikerGid), // Default magazijn voor deze gebruiker + toepassing
               (select first MagGid from tabMagazijn where MagCode = 1))  // Magazijn 001
      endif PbrMagGid,
      if PbrMagGid is not null then
        isnull((select ArtMagDefaultLocGid from tabartikelmagazijn where ArtMagMagGid = PbrMagGid and ArtMagArtGid = PvcArtGid), (select LocGid from tabLocatie where LocMagGid = PbrMagGid and LocNaam = '(Standaard)'))
      endif PbrLocGid,
      // Regel 3
      IsNull(PvcLeverancierNawGid,@LevNawGid) as Lev,
      // bugdoc:27681 Kostprijs niet opnieuw bepalen als overige kosten/doorbelasting ingevuld
      if @PrijsOpnieuwBepalen=0 or PvcDoorbelastPercentage is not null then (PvcKostprijsRegelTotaal / PvcBudAantal) * PrijsPer endif as Kostprijs,
      ((Kostprijs * AantalTeBoeken) / PrijsPer) as KostprijsRegelTotaal,
      PvcMutSoort,
      PvcPdosGid,
      // Regel 4
      PvcProjGid,
      PvcOmschr,
      if @PrijsOpnieuwBepalen=0 then if PvcOffAantal = 0 then PvcVerkoopprijsRegelTotaal else (PvcVerkoopprijsRegelTotaal / PvcOffAantal) * PrijsPer endif endif Verkoopprijs ,
      ((Verkoopprijs * AantalTeBoeken) / PrijsPer) / PvcPartFactEenheidFactor as VerkoopprijsRegeltotaal,
      PvcBudAantal as AantalTeBoeken,
      // Regel 5
      AantalTeBoeken / PvcPartFactEenheidFactor as AantalDeclarabel,
      // Let op: in geval van Doorbelasting altijd 1, dus hoeft niet opnieuw bepaald te worden; anders wordt ook kostprijs niet goed berekend.
      if @PrijsOpnieuwBepalen=0 or PvcDoorbelastPercentage is not null then PvcPrijsPer endif as PrijsPer,
      if @PrijsOpnieuwBepalen=0 then PvcPartFactEenheidFactor endif,
      if PvcMutSoort=0 then IsNull(PvcRelGid, @MdwRelGid) endif as Medewerker,
      PvcSelectieCodes,
      // Regel 6
      @@VerwerkingsDatum,
      if @PrijsOpnieuwBepalen=0 then PvcDoorbelastPercentage endif DoorbelastPercentage,
      0
    from
      tmpPvcGidjes
      inner join      tabProjectVoorcalculatie on (pvcGid = tmppvcgid)
      left outer join tabArtikel on (ArtGid = pvcArtGid)
    where
      //<>0 erbij ivm bug 29263
      (@RegelsSamenvoegen=0 and AantalTeBoeken <> 0) or (@RegelsSamenvoegen=1 and AantalTeBoeken > 0);
  end if;

  set @@ErrorTextProcedure = 'BoekenMutatieObvProject > einde';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BoekHerwaardering(in @OpbrGrpGid integer, in @VoorraadBedrag numeric(15,2), in @Kostprijs numeric(15,2), in @JpGid integer, in @Oms nchar(40))
begin
  declare @TeBoekenBedrag numeric(15,2);
  declare @BoekZijde integer;
  declare @GrpSoortRksGID integer;

  set @@ErrorTextProcedure = 'BoekHerwaardering > @OpbrGrpGid='+string(@OpbrGrpGid)+', @VoorraadBedrag='+string(@VoorraadBedrag)+', @Kostprijs='+string(@Kostprijs)+', @JpGid='+string(@JpGid);
  //call TraceBegin(@@ErrorTextProcedure);

  call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 80, @GrpSoortRksGID); //Herwaardering
  select DefaultBoekzijde into @BoekZijde from tabRekeningschema where RksGid = @GrpSoortRksGID;
  set @TeBoekenBedrag = @VoorraadBedrag - @Kostprijs;  //In beginsel debet-bedrag! (Want CreditBedrag(voorraadboeking)-DebetBedrag(kostprijsboeking)=DebetRestant(herwaardering))

  //call Trace('1: @Boekzijde='+string(@Boekzijde)+', @TeBoekenBedrag='+string(@TeBoekenBedrag));
  if @Boekzijde = 1 then  //Credit, dus teken omdraaien
    set @TeBoekenBedrag = - @TeBoekenBedrag;
  end if;
  //call Trace('2: @Boekzijde='+string(@Boekzijde)+', @TeBoekenBedrag='+string(@TeBoekenBedrag));
  if @Boekzijde in (2,3) then //Geen voorkeur / afhankelijk van dagboek
    set @Boekzijde = (if @TeBoekenBedrag < 0 then 1 else 0 endif); //Als <0, dan credit, anders debet
    set @TeBoekenBedrag = abs(@TeBoekenBedrag);
  end if;
  //call Trace('Boek '+if @BoekZijde=1 then 'AAN ' else '' endif+'HERWAARDERING: '+string(@TeBoekenBedrag));
  if @TeBoekenBedrag <> 0 then
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                 IsCreditBoeking, SoortBoeking, JrValNummer )
      values( @JpGid, @GrpSoortRksGID, @TeBoekenBedrag, @TeBoekenBedrag, @oms, @BoekZijde, 0, @@BasisValutaNummer);
  end if;

  set @@ErrorTextProcedure = 'BoekHerwaardering';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function BoekingDebetOfCredit(in @RksGid integer, in @Bedrag numeric(15,2))
returns smallint
begin
  declare @BoekZijde smallint;
  declare @IsCredit smallint;

  //Let op : moet op dezelfde manier werken als BoekingsBedragPositiefOfNegatief
  //@Bedrag positief dan wordt dit als debet gezien (kan natuurlijk ook credit min worden)

  //call TraceBegin ('BoekingDebetOfCredit(@RksGid='+string(@RksGid)+', @Bedrag='+string(@Bedrag)+')');

  select DefaultBoekzijde into @BoekZijde from tabRekeningschema where RksGid=@RksGid;
  if @BoekZijde = 0 then         //Debet
    set @IsCredit=0;             //Als bedrag negatief is, dan was het oorspronkelijk een creditboeking en blijft bedrag negatief
  else
    if @BoekZijde = 1 then    //Credit
      set @IsCredit = 1;
    else                           //Geen voorkeur
      if @Bedrag < 0 then
        set @IsCredit = 1;
      else
        set @IsCredit = 0;         //Bedrag is al positief
      end if;
    end if;
  end if;

  //call TraceEind ('BoekingDebetOfCredit(@IsCredit='+string(@IsCredit)+')');
  return(@IsCredit);

end;


create or replace procedure BoekingHulpRekening(in @WordGeopend smallint, in @JpGid integer)
begin
  //call TraceBegin('BoekingHulpRekening >');

  //Bij het sluiten moet de hulprekening boekingen worden aangemaakt
  declare @CjpTekst long nvarchar;
  set @CjpTekst = _A('Cjp-boeking hulprekening');

  if @WordGeopend=0 then
    // Maak nu CJP-boekingen op hulprekeningen
    insert into tabJournaalregel(JrJpGid, JrRksGid, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, JrValNummer, JrBoekDatum, JrDarGid, JrRarGid, JrBetRglGid, JrBetVerzGID, JrIncRglGid, JrIrvGid)
    select @JpGid, HulpRekRksGid, @CjpTekst, 2, HulpRekIsCredit, sum(HulpRekBasisBedrag), sum(HulpRekValutaBedrag), HulpRekValNummer,
           max(JrBoekDatum) MaxDatum,
           if count (distinct JrDarGid) = 1 then min(JrDarGid) else null endif,
           JrRarGid, JrBetRglGid, JrBetVerzGID, JrIncRglGid, JrIrvGid
    from   tabJournaalregel
           inner join tabHulpRekening on (HulpRekJrGid = JrGid and ((HulpRekValutaBedrag <> 0) or (HulpRekBasisBedrag <> 0)))
           inner join tabPeriode on (JrPerGid = PerGid)
           where JrJpGid = @JpGid and SoortBoeking=0
    group by HulpRekRksGid, HulpRekValNummer, HulpRekIsCredit, HulpRekSoort, PerGid, JrRarGid, JrBetRglGid, JrBetVerzGID, JrIncRglGid, JrIrvGid
    order by MaxDatum, HulpRekSoort;
  else
    //Gooi alle hulprekening-boekingen weg
    delete from tabJournaalregel where JrJpGid=@JpGid and SoortBoeking in (2,3);
  end if;

  //call TraceEind('BoekingHulpRekening');
end;


create or replace procedure BoekingOpTegenRekening(in @WordGeopend smallint, in @JpGid integer, in @DgbGid integer)
begin
  //------------- Maak eventueel een boeking op de tegenrekening van het dagboek, om ervoor te zorgen dat de Journaalpost in evenwicht is
  declare @RksGid             integer;
  declare @BoekZijde          smallint;
  declare @BufBoekzijde       smallint;
  declare @DefaultBoekzijde   smallint;
  declare @StukVolgnr         integer;
  declare @ValNummer          integer;
  declare @ValutaBedrag       numeric(15,2);
  declare @Bedrag             numeric(15,2);
  declare @Aantal             numeric(15,2);

  //call TraceBegin('BoekingOpTegenRekening > @WordGeopend='+string(@WordGeopend)+', @JpGid='+string(@JpGid));

  //Bij het openenen van de journaalpost, gaan we de boeking op de tegenrekening weggooien
  if @WordGeopend = 1 then
    delete from tabJournaalregel where JrJpGid = @JpGid and SoortBoeking = 1;
  else
    begin
      declare @CjpregelTekst long nvarchar;
      set @CjpregelTekst = _A('Cjp-regel');

      select DgbTegenRksGid, CjpBoeken into @RksGid, @BufBoekZijde from tabDagboek where DgbGid = @DgbGid;

      //call Trace('Bepaal valuta van de tegenrekening');
      select RksValNummer, DefaultBoekzijde into @ValNummer, @DefaultBoekzijde from tabRekeningschema where RksGid = @RksGid;

      FOR @Cursor AS CURSOR_JpSaldoPerPeriode NO SCROLL cursor for
        select JrBjGid @BjGid,
               JrPerNr @PerNr,
               IsNull(sum(if IsCreditBoeking =1 then JrBasisBedrag else 0 endif),0)  @CreditBasisBedrag,
               IsNull(sum(if IsCreditBoeking =1 then Aantal else 0 endif),0)         @CreditAantal,
               IsNull(sum(if IsCreditBoeking =0 then JrBasisBedrag else 0 endif),0)  @DebetBasisBedrag,
               IsNull(sum(if IsCreditBoeking =0 then Aantal else 0 endif),0)         @DebetAantal,
               IsNull(sum(if JrValNummer = @ValNummer then if IsCreditBoeking= 1 then JrValutaBedrag else 0 endif else ValutaOmrekenen(JrValNummer, if IsCreditBoeking=1 then JrValutaBedrag else 0 endif, @ValNummer, JrBjGid, JrPernr, 2) endif),0) @CreditValutaBedrag,
               IsNull(sum(if JrValNummer = @ValNummer then if IsCreditBoeking= 0 then JrValutaBedrag else 0 endif else ValutaOmrekenen(JrValNummer, if IsCreditBoeking=0 then JrValutaBedrag else 0 endif, @ValNummer, JrBjGid, JrPernr, 2) endif),0) @DebetValutaBedrag,
               Max(JrBoekDatum) @JrBoekDatum,
               if count (distinct JrDarGid) = 1 then min(JrDarGid) else null endif @JrDarGid
        from   tabJournaalregel where JrJpGid = @JpGid and SoortBoeking <> 1
        group by JrBjGid, JrPerNr
        order by JrPerNr
      for read only
      do

        set @BoekZijde = @BufBoekzijde;
        //call Trace('Als Boekzijde = 2 (Default boekzijde van de rekening) dan boekzijde uit rekeningschema halen');
        if @BoekZijde=2 then
          set @BoekZijde = @DefaultBoekzijde;
          if @BoekZijde<>0 and @BoekZijde<>1 then   //0=debet en 1=credit
            set @BoekZijde=2;
          end if;
        else
          if @BoekZijde=0 then    //Saldo bepaald kant
            set @BoekZijde=2;
          else
            set @BoekZijde=3;      //Beide kanten moet er een boeking gemaakt worden
          end if;
        end if;

        //call Trace('Bepaal bedrag in de valuta van de');

        if round(@DebetBasisBedrag-@CreditBasisBedrag,2)<>0 or round(@DebetAantal-@CreditAantal,2)<>0 or (round(@DebetValutaBedrag-@CreditValutaBedrag,2)<>0 and @ValNummer <> @@BasisValutaNummer) then
        begin
          declare @Rargid integer;

          //Onderstaande test laten staan (in sommige gevallen is deze nodig)
          if @ValNummer = @@BasisValutaNummer then
            set @CreditValutaBedrag = @CreditBasisBedrag;
            set @DebetValutaBedrag  = @DebetBasisBedrag;
          end if;

          //Als in de journaalregels precies 1 Rargid is, dan die in de CJP-regel opnemen
          select min(jrRargid)
          into @Rargid
          from tabJournaalregel
          where JrJpGid = @JpGid and jrRargid is not null
          having min(jrRargid) = max(jrRargid);

          // Eerst testen of sign van basis en valuta gelijk zijn
          set @Bedrag       = @CreditBasisBedrag  - @DebetBasisBedrag;
          set @ValutaBedrag = @CreditValutaBedrag - @DebetValutaBedrag;
          if sign(@Bedrag) <> sign(@ValutaBedrag) and sign(@Bedrag) <> 0 and sign(@ValutaBedrag) <> 0 then
            // Sign is anders en ongelijk aan 0!! Daarom debet en credit apart boeken!!
            set @BoekZijde = 3;
          end if;

          //Uiteindelijk is boekzijde : 0=Debet, 1=Credit; 2=Saldo bepaald kant; 3=Beide kanten
          if @BoekZijde = 0 then
            set @Bedrag       = @CreditBasisBedrag  - @DebetBasisBedrag;
            set @Aantal       = @CreditAantal       - @DebetAantal;
            set @ValutaBedrag = @CreditValutaBedrag - @DebetValutaBedrag;
            //call Trace('cjp1: '+ 'Valuta: ' + string(@ValNummer) + ': ' + string( @Bedrag)+ ' -> ' + string(@ValutaBedrag));
            insert into tabJournaalregel(JrJpGid, JrRksGid, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, JrValNummer, Aantal, JrBoekDatum, JrDarGid)
            values (@JpGid, @RksGid, @CjpregelTekst, 1, 0, @Bedrag, @ValutaBedrag, @ValNummer, @Aantal, @JrBoekDatum, @JrDarGid);
          else
            if @BoekZijde = 1 then
              set @Bedrag       = @DebetBasisBedrag  - @CreditBasisBedrag;
              set @Aantal       = @DebetAantal       - @CreditAantal;
              set @ValutaBedrag = @DebetValutaBedrag - @CreditValutaBedrag;
              //call Trace('cjp2: '+ 'Valuta: ' + string(@ValNummer) + ': ' + string( @Bedrag)+ ' -> ' + string(@ValutaBedrag));
              insert into tabJournaalregel(JrJpGid, JrRksGid, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, JrValNummer, Aantal, JrBoekDatum, JrDarGid, JrRargid)
              values (@JpGid, @RksGid, @CjpregelTekst, 1, 1, @Bedrag, @ValutaBedrag, @ValNummer, @Aantal, @JrBoekDatum, @JrDarGid, @Rargid);
            else
              if @BoekZijde = 2 then
                if @DebetBasisBedrag>@CreditBasisBedrag then
                  //Credit boeking maken
                  set @Bedrag       = @DebetBasisBedrag  - @CreditBasisBedrag;
                  set @Aantal       = @DebetAantal       - @CreditAantal;
                  set @ValutaBedrag = @DebetValutaBedrag - @CreditValutaBedrag;
                  //call Trace('cjp3: '+ 'Valuta: ' + string(@ValNummer) + ': ' + string( @Bedrag)+ ' -> ' + string(@ValutaBedrag));
                  insert into tabJournaalregel(JrJpGid, JrRksGid, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, JrValNummer, Aantal, JrBoekDatum, JrDarGid, JrRargid)
                  values (@JpGid, @RksGid, @CjpregelTekst, 1, 1, @Bedrag, @ValutaBedrag, @ValNummer, @Aantal, @JrBoekDatum, @JrDarGid, @Rargid);
                else
                  set @Bedrag       = @CreditBasisBedrag  - @DebetBasisBedrag;
                  set @Aantal       = @CreditAantal       - @DebetAantal;
                  set @ValutaBedrag = @CreditValutaBedrag - @DebetValutaBedrag;
                  //call Trace('cjp4: '+ 'Valuta: ' + string(@ValNummer) + ': ' + string( @Bedrag)+ ' -> ' + string(@ValutaBedrag));
                  insert into tabJournaalregel(JrJpGid, JrRksGid, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, JrValNummer, Aantal, JrBoekDatum, JrDarGid, JrRargid)
                  values (@JpGid, @RksGid, @CjpregelTekst, 1, 0, @Bedrag, @ValutaBedrag, @ValNummer, @Aantal, @JrBoekDatum, @JrDarGid, @Rargid);
                end if;
              else
                //Debet boeking maken (creditbedragen debet boeken)
                if @CreditBasisBedrag <> 0 or @CreditAantal <> 0 or @CreditValutabedrag <> 0 then
                  //call Trace('cjp5: '+ 'Valuta: ' + string(@ValNummer) + ': ' + string( @Bedrag)+ ' -> ' + string(@ValutaBedrag));
                  insert into tabJournaalregel(JrJpGid, JrRksGid, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, JrValNummer, Aantal, JrBoekDatum, JrDarGid, JrRargid)
                  values (@JpGid, @RksGid, @CjpregelTekst, 1, 0, @CreditBasisBedrag, @CreditValutaBedrag, @ValNummer, @CreditAantal, @JrBoekDatum, @JrDarGid, @Rargid);
                end if;

                //Credit boeking maken (debetbedragen credit boeken)
                if @DebetBasisbedrag <> 0 or @DebetAantal <> 0 or @DebetValutabedrag <> 0 then
                  //call Trace('cjp6: '+ 'Valuta: ' + string(@ValNummer) + ': ' + string( @Bedrag)+ ' -> ' + string(@ValutaBedrag));
                  insert into tabJournaalregel(JrJpGid, JrRksGid, OmsJournaalregel, SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, JrValNummer, Aantal, JrBoekDatum, JrDarGid, JrRargid)
                  values (@JpGid, @RksGid, @CjpregelTekst, 1, 1, @DebetBasisBedrag, @DebetValutaBedrag, @ValNummer, @DebetAantal, @JrBoekDatum, @JrDarGid, @Rargid);
                end if;
              end if;
            end if;
          end if;
        end;
        end if;
      end for;
    end;
  end if;

  //call TraceEind('BoekingOpTegenRekening');
end;


create or replace function BoekingsBedragPositiefOfNegatief(in @RksGid integer, in @Bedrag numeric(15,2))
returns numeric(15,2)
begin
  declare @BoekZijde smallint;
  declare @IsCredit smallint;

  //Let op : moet op dezelfde manier werken als BoekingDebetofCredit
  //@Bedrag positief dan wordt dit als debet gezien (kan natuurlijk ook credit min worden)

  //call TraceBegin ('BoekingsBedragPositiefOfNegatief(@RksGid='+string(@RksGid)+', @Bedrag='+string(@Bedrag)+')');

  select DefaultBoekzijde into @BoekZijde from tabRekeningschema where RksGid=@RksGid;
  if @BoekZijde = 0 then         //Debet
    set @Bedrag=@Bedrag          //Als bedrag negatief is, dan was het oorspronkelijk een creditboeking en blijft bedrag negatief
  else
    if @BoekZijde = 1 then       //Credit
      set @Bedrag = -@Bedrag;    //Of bedrag nu negatief of positief is, dan altijd teken omklappen
    else                         //Geen voorkeur
      if @Bedrag < 0 then
        set @Bedrag = -@Bedrag;  //Positief maken
      else
        set @Bedrag=@Bedrag      //Bedrag is al positief
      end if;
    end if;
  end if;

  //call TraceEind ('BoekingsBedragPositiefOfNegatief(@Bedrag='+string(@Bedrag)+')');
  return(@Bedrag);

end;


create or replace function BoekingsGangInGebruikNemen(in @BoekGangGid integer)
returns smallint
begin
  declare @Resultaat smallint;
  declare @IsAlInGebruik smallint;
  declare @IsAlDefinitief smallint;

  set @@ErrorTextProcedure = 'BoekingsGangInGebruikNemen > @BoekGangGid='+string(@BoekGangGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Resultaat = 0;  //Ok
  set @IsAlinGebruik = null;
  select BoekGangInGebruik, IsBoekGangDefinitief into @IsAlinGebruik, @IsAlDefinitief from tabBoekingsgang where BoekGangGid=@BoekGangGid
  OPTION(Isolation_level=1);
  if @IsAlInGebruik is null then
    set @Resultaat = 2;  //Boekingsgang bestaat niet meer
  else
    if @IsAlDefinitief<>0 then
      set @Resultaat = 3;   //Boekingsgang is al definitief
    else
      if @IsAlIngebruik<>0 then
        set @Resultaat = 1;  //Boekingsgang is al in gebruik
      end if;
    end if;
  end if;
  if @Resultaat = 0 then
    update tabBoekingsGang set BoekGangInGebruik = 1 where BoekGangGid = @BoekGangGid
    OPTION(Isolation_level=1);
  end if;

  set @@ErrorTextProcedure = 'BoekingsGangInGebruikNemen > @Resultaat='+string(@Resultaat);
  //call TraceEind(@@ErrorTextProcedure);
  return(@Resultaat)

end;


create or replace procedure BoekingsgangSaldo(in  @BoekGangGid integer, in @JrGid integer, out @ValCode nchar(3), out @ValNummer integer,
                                              out @DebetBedrag numeric(15,2), out @CreditBedrag numeric(15,2),
                                              out @DebetAantal numeric(15,2), out @CreditAantal numeric(15,2))
begin
  declare @TegenRksGid  integer;
  declare @DagboekSoort integer;

  set @@ErrorTextProcedure = 'BoekingsgangSaldo >';
  //call TraceBegin(@@ErrorTextProcedure);

  select first DgbTegenRksGid, DagboekSoort into @TegenRksGid, @DagboekSoort from tabDagboek inner join tabJournaalpost on (JpDgbGid = DgbGid and JpBoekGangGid = @BoekGangGid) order by JpGid;

  call DefaultValuta(@TegenRksGid, @ValNummer, @ValCode);

  select sum( if                                        IsCreditBoeking     = 0 then 0 else if JrValNummer      = @ValNummer then JrValutaBedrag      else ValutaOmrekenen(JrValNummer,      JrValutaBedrag,      @ValNummer, @@BjGid, if @DagboekSoort = 5 then 0 else JrPerNr endif, 2) endif endif+
              if HulpRekValutaBedrag is null or IsNull( HulpRekIsCredit, 0 )= 0 then 0 else if HulpRekValNummer = @ValNummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, @ValNummer, @@BjGid, if @DagboekSoort = 5 then 0 else JrPerNr endif, 2) endif endif),
         sum( if                                        IsCreditBoeking     = 1 then 0 else if JrValNummer      = @ValNummer then JrValutaBedrag      else ValutaOmrekenen(JrValNummer,      JrValutaBedrag,      @ValNummer, @@BjGid, if @DagboekSoort = 5 then 0 else JrPerNr endif, 2) endif endif +
              if HulpRekValutaBedrag is null or IsNull( HulpRekIsCredit, 0 )= 1 then 0 else if HulpRekValNummer = @ValNummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, @ValNummer, @@BjGid, if @DagboekSoort = 5 then 0 else JrPerNr endif, 2) endif endif),
         sum(if IsCreditBoeking = 1 then IsNull(Aantal, 0) else 0 endif),
         sum(if IsCreditBoeking = 0 then IsNull(Aantal, 0) else 0 endif)
  into  @CreditBedrag, @DebetBedrag, @CreditAantal, @DebetAantal
  from   tabJournaalpost
         inner join tabJournaalregel on (JrJpGid = JpGid)
         left outer join tabHulpRekening on (JrGid=HulpRekJrGid)
  where  (JpBoekGangGid=@BoekGangGid) and (SoortBoeking = 0) and (JrGid<>@JrGid or @JrGid is null);

  set @@ErrorTextProcedure = 'BoekingsgangSaldo';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure BoekingsGangVerwerken(in @BoekGangGid integer, out @Resultaat smallint)
begin
  declare @IsolationLevel smallint;

  set @@ErrorTextProcedure = 'BoekingsGangVerwerken > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BoekGangGid = ' + string(@BoekGangGid));

  select BoekingsGangInGebruikNemen(@BoekGangGid) into @Resultaat;

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  if @Resultaat = 0 then
    set @@OverRuleLock = 1;   //We hoeven nu niet iedere keer de Journaalpost in gebruik te nemen

    //RVL : Is al in gebruik genomen in BoekingsgangInGebruikNemen
    //update tabBoekingsGang set BoekGangInGebruik = 1 where BoekGangGid = @BoekGangGid;

    //Debet en credit saldi worden in 1 keer ge-update
    update tabRekeningsaldo set SaldoDebetBasisVoorlopig    = SaldoDebetBasisVoorlopig    - if IsCreditBoeking=0  then JrBasisBedrag  else 0 endif,
                                SaldoDebetBasisDefinitief   = SaldoDebetBasisDefinitief   + if IsCreditBoeking=0  then JrBasisBedrag  else 0 endif,
                                SaldoDebetValutaVoorlopig   = SaldoDebetValutaVoorlopig   - if IsCreditBoeking=0  then JrValutaBedrag else 0 endif,
                                SaldoDebetValutaDefinitief  = SaldoDebetValutaDefinitief  + if IsCreditBoeking=0  then JrValutaBedrag else 0 endif,
                                SaldoDebetAantalVoorlopig   = SaldoDebetAantalVoorlopig   - if IsCreditBoeking=0  then Aantal         else 0 endif,
                                SaldoDebetAantalDefinitief  = SaldoDebetAantalDefinitief  + if IsCreditBoeking=0  then Aantal         else 0 endif,
                                SaldoCreditBasisVoorlopig   = SaldoCreditBasisVoorlopig   - if IsCreditBoeking<>0 then JrBasisBedrag  else 0 endif,
                                SaldoCreditBasisDefinitief  = SaldoCreditBasisDefinitief  + if IsCreditBoeking<>0 then JrBasisBedrag  else 0 endif,
                                SaldoCreditValutaVoorlopig  = SaldoCreditValutaVoorlopig  - if IsCreditBoeking<>0 then JrValutaBedrag else 0 endif,
                                SaldoCreditValutaDefinitief = SaldoCreditValutaDefinitief + if IsCreditBoeking<>0 then JrValutaBedrag else 0 endif,
                                SaldoCreditAantalVoorlopig  = SaldoCreditAantalVoorlopig  - if IsCreditBoeking<>0 then Aantal         else 0 endif,
                                SaldoCreditAantalDefinitief = SaldoCreditAantalDefinitief + if IsCreditBoeking<>0 then Aantal         else 0 endif
    from   tabJournaalpost, tabJournaalregel
    where  JpBoekGangGid=@BoekGangGid and JpGid=JrJpGid and JrPerGid=RekSaldoPerGid and JrValNummer=RekSaldoValNummer and JrRksGid=RekSaldoRksGid;

    //Factuurboeking en betalingen evt. met kredietbeperking/betalingskorting updaten
    update tabOpenstaandePost set OspValNummer                     = JrValNummer,  //Express doen, hierdoor conroleert de trigger of de oude en nieuwe valuta overeenkomen
                                  OspFactuurBedragVoorlopig        = OspFactuurBedragVoorlopig        - if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
                                  OspFactuurBedragDefinitief       = OspFactuurBedragDefinitief       + if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
                                  OspBetaaldBedragVoorlopig        = OspBetaaldBedragVoorlopig        - if IsBetaling      (JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
                                  OspBetaaldBedragDefinitief       = OspBetaaldBedragDefinitief       + if IsBetaling      (JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
                                  OspBtwBedragVoorlopig            = OspBtwBedragVoorlopig            -
                                                                     if IsNull(HulpRekSoort,0) = 1 then
                                                                       if HulpRekIsCredit = 0 then
                                                                         (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                                                       else
                                                                         (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                                                       endif
                                                                      else
                                                                        0
                                                                      endif,
                                  OspBtwBedragDefinitief           = OspBtwBedragDefinitief           +
                                                                     if IsNull(HulpRekSoort,0) = 1 then
                                                                       if HulpRekIsCredit = 0 then
                                                                         (if HulpRekValNummer = JrValnummer then  HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                                                       else
                                                                         (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                                                       endif
                                                                      else
                                                                        0
                                                                      endif
    from   tabJournaalpost, tabJournaalregel left outer join tabHulpRekening on (JrGid=HulpRekJrGid)
    where  JpBoekGangGid=@BoekGangGid and JpGid=JrJpGid and JrOspGid=OspGid;

    update tabBoekingsGang set BoekGangInGebruik = 0, IsBoekGangDefinitief = 1
    where  BoekGangGid = @BoekGangGid;

    set @@OverRuleLock = 0;

  end if;

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  set @@ErrorTextProcedure = 'BoekingsGangVerwerken';
  //call TraceEind(@@ErrorTextProcedure + ' > @Resultaat = ' + string(@Resultaat));
end;


//---- Verwerk boekingsgang die nog openstaat nadat gebruiker er uit is gegaan(bijv. als gevolg van een knal boem eruit)
create or replace procedure BoekingsgangVerwerkenSpeciaal(in @LockGid integer)
begin
  declare @IsolationLevel smallint;
  declare @Primkey nchar(20);

  set @@ErrorTextProcedure = 'BoekingsgangVerwerkenSpeciaal > @LockGid='+string(@LockGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  select substr(qLockPKey, Locate(qLockPKey,'=')+1,10) into @PrimKey from qtabLock where qLockTableName='tabBoekingsgang' and qLockGid=@LockGid;
  if @PrimKey is not null then
    update qtabLock set qLockConnection = @@spid, qLockLoginTime = @@LoginTime where qLockGid=@LockGid;
  end if;

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  if @PrimKey is not null then
    update tabRekeningAfschriftRegel
    set    RarBedragAlGeboekt = RarBedragAlGeboekt -
                               (if RarIsErbij = 0 then 1 else -1 endif) *
                              ((if IsCreditBoeking <> 0 then -1 else 1 endif) * ValutaOmrekenen(@@BasisValutaNummer, JrBasisBedrag, RarValNummer, JrBjGid, JrPerNr, 2) +
                        IsNull((if HulpRekIsCredit <> 0 then -1 else 1 endif) * ValutaOmrekenen(@@BasisValutaNummer, HulpRekBasisBedrag, RarValNummer, JrBjGid, JrPerNr, 2),0))
    from   tabJournaalpost
           inner join (tabJournaalRegel left outer join tabHulpRekening on (HulpRekJrGid = JrGid)) on (JrJpGid = JpGid)
    where  JpBoekGangGid = @PrimKey and JpIsInGebruik <> 0 and JrRarGid = RarGid;

    //TG 16-01-2008: Onderstaande twee regels code is komen te vervallen ivm bug #27751. Zie bugdocument voor overige aanpassingen!
    //delete tabJournaalpost where JpBoekGangGid = @PrimKey and JpIsInGebruik <> 0;
    //update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangInGebruik <> 0 and BoekGangGid = @PrimKey;

    //TG 16-01-2008: Nieuwe code (functionaliteit) ivm bug #27751. Zie bugdocument voor overige aanpassingen!
    if IsModuleActive('br') = 1 then
      update tabJournaalpost set JpIsInGebruik = 1 where JpBoekGangGid = @PrimKey and JpIsInGebruik = 0;
      update tabBoekingsgang set IsBoekgangDefinitief = 0 where BoekGangInGebruik = 1 and BoekGangGid = @PrimKey;
    end if;

    update tabJournaalpost set JpIsInGebruik = 0 where JpBoekGangGid = @PrimKey and JpIsInGebruik <> 0;
    update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangInGebruik = 1 and BoekGangGid = @PrimKey;

    delete qtabLock where qLockGid=@LockGid;
  end if;

  set @@ErrorTextProcedure = 'BoekingsgangVerwerkenSpeciaal';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BoekingsGangVerwijderen(in @BoekGangGid integer, inout @Resultaat smallint)
begin

  set @@ErrorTextProcedure = 'BoekingsGangVerwijderen > @BoekGangGid='+string(@BoekGangGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select BoekingsGangInGebruikNemen(@BoekGangGid) into @Resultaat;
  if @Resultaat = 0 then
    set @@JournaalVolgNummersNietVerlagen = @@JournaalVolgNummersNietVerlagen + 1;
    set @@ErrorTextProcedure = 'BoekingsGangVerwijderen : Neem journaalpost in gebruik';
    update tabJournaalpost set JpIsInGebruik = 1 where JpBoekGangGid = @BoekGangGid and JpIsInGebruik = 0;
    set @@ErrorTextProcedure = 'BoekingsGangVerwijderen > Verwijder daadwerkelijk de boekingsgang';
    delete tabBoekingsgang where BoekGangGid = @BoekGangGid;
    set @@JournaalVolgNummersNietVerlagen = @@JournaalVolgNummersNietVerlagen - 1;
  end if;

  //call TraceEind('BoekingsGangVerwijderen(@Resultaat='+string(@Resultaat)+')');

end;


Create or replace procedure BoekInkoopfactuur(
  in    @ConnId                integer,
  in    @LoginTime             nchar(50),
  in    @IfkGid                integer,
  in    @Boekdatum             date,
  in    @KeepBoekgangOpen      smallint, //0 = Neem boekingsgang uit gebruik, 1 = Laat boekingsgang in gebruik
  inout @DgbGid                integer,  // Indien leeg, dan die uit de vaste gegevens
  inout @BoekStukNummer        numeric(10,0), // Indien leeg, dan op basis van instelling van dagboek
  inout @BoekgangGid           integer
)
begin atomic
  //region Declares
  // Boekingsgegevens
  declare @BjGidBoeking                   integer;
  declare @PerNrBoeking                   integer;
  declare @TussenrekeningInkopenRksGid    integer;
  declare @TussenrekeningInkopenRksInvoer nchar(28);
  declare @JrVolgNr                       integer;
  // Factuurgegevens
  declare @FactuurNummer                  nchar(40);
  declare @Factuurnummer_Lengte           smallint;
  declare @IfkReferentienummer            nchar(40);
  declare @IfkReferentienummer_lengte     smallint;
  declare @ValNummer                      integer;
  declare @Factuurdatum                   date;
  declare @Vervaldatum                    date;
  declare @IsGefiatteerd                  smallint;
  declare @Betalingskenmerk               nchar(140);
  declare @Oms                            nchar(40);
  declare @NawRksGid                      integer;
  declare @NawNummer                      nchar(10);
  declare @NawNaam1                       nchar(40);
  declare @OntvBoekenTegen                smallint;
  //endregion Declares

  set @@ErrorTextProcedure = 'BoekInkoopfactuur < ' + string(@IfkGid)+', ' +string(@Boekdatum) + ', BoekgangGid=' +string(@BoekgangGid);
    //call traceBegin(@@ErrorTextProcedure);

  //region Gegevens van factuur ophalen
  // *******************************
  // *** Factuurgegevens ophalen ***
  // *******************************

  //Factuurkop
  select IfkFactuurNummer,  IfkFactuurnummer_Lengte,  IfkReferentienummer,  IfkReferentienummer_Lengte,  NawFilRksGid, NawFilNummer, AdrNaam1, IfkValNummer, IfkFactuurdatum, IfkVervaldatum, IfkBetalingskenmerk, IfkOmschrijving
  into   @FactuurNummer,    @Factuurnummer_Lengte,    @IfkReferentienummer, @IfkReferentienummer_lengte, @NawRksGid,   @NawNummer,   @NawNaam1, @ValNummer,  @Factuurdatum,   @Vervaldatum,   @Betalingskenmerk,   @Oms
  from   tabInkoopfactuurKop
         inner join tabNaw     on NawGid = ifkNawGid
         inner join tabAdres   on AdrGid = NawGidVestiging
         inner join tabNawFile on NawFilNawGid = ifkNawGid and NawFilFonId = 'C'
  where  IfkGid = @IfkGid;
    //call trace('@FactuurNummer='+@FactuurNummer+', @NawRksGid='+string(@NawRksGid));

  if @FactuurNummer is null then
    //(20371) %1! niet gevonden!
    call Raise(20371, _U('Inkoopfactuur'));
  end if;
  //endregion Gegevens van factuur ophalen

  //region Validatie inkoopfactuur
  // *******************************
  // *** Validatie inkoopfactuur ***
  // *******************************
  // Totaal van BTW-regels moet gelijk zijn aan totaal van inkoopfactuurregels
  // Controle alleen als bedragen niet 0,00 zijn!
  begin
    declare @TotalOfBTWGrondslag numeric(15,2);
    declare @TotalOfRegelExclBTW numeric(15,2);

    select sum(IfbGrondslagBedrag) into @TotalOfBTWGrondslag
    from tabInkoopfactuurBtwblok
    where IfbIfkGid = @IfkGid;
    set @TotalOfBTWGrondslag = isnull(@TotalOfBTWGrondslag, 0);

    if @TotalOfBTWGrondslag <> 0 then
      // Als we BTW-regels met een grondslagbedrag hebben, dan moet dat overeen komen met totaal van de regls
      select sum(IfrRegeltotaalExclBtw) into @TotalOfRegelExclBTW
      from tabInkoopfactuurRegel
      where IfrIfkGid = @IfkGid;
      set @TotalOfRegelExclBTW = isnull(@TotalOfRegelExclBTW, 0);
      if @TotalOfRegelExclBTW <> 0 and @TotalOfBTWGrondslag <> @TotalOfRegelExclBTW then
        call Raise(20373); // Totaal BTW-basisbedrag wijkt af van totaal van factuurregels!
      end if;
    end if;
  end;

  //region Gegevens van periode en boekjaar ophalen
  // ************************************
  // *** Boekperiode gegevens ophalen ***
  // ************************************
  call BepaalBoekjaarEnPeriode(@Boekdatum, @BjGidBoeking, @PerNrBoeking);

  if exists(select first 1 from  tabOpenstaandePost where OspBjGid=@BjGidBoeking and OspFactuurNummer=@FactuurNummer and OspRksGid=@NawRksGid and OspValNummer<>@ValNummer) then
    call Raise(20112); // Valuta van openstaande post kan niet veranderd worden!
  end if;
  //endregion Validatie inkoopfactuur


  //region Overige (vaste/stam)gegevens ophalen
  // ********************************
  // *** Overige gegevens ophalen ***
  // ********************************

  //Dagboek
  //TODO select first vgifDgbGid into @DgbGid from tabVastegegevensInkoopfacturen
  select first MagVastInkDgbGid, MagVastOntvBoekenTegen into @DgbGid, @OntvBoekenTegen from tabMagazijnOntvangstenVastegegevens;

  // Tussenrekening inkopen
  select first MagVastInkRksGID, RksInvoer into @TussenrekeningInkopenRksGid, @TussenrekeningInkopenRksInvoer
  from   tabMagazijnOntvangstenVastegegevens
         inner join tabRekeningschema on RksGid = MagVastInkRksGID;
  if @TussenrekeningInkopenRksGid is null then
    //(20371) %1! niet gevonden!
    call Raise(20371, _U('Tussenrekening inkopen'));
  end if;
  //endregion Overige (vaste/stam)gegevens ophalen

  //region Genereren doorlopende nummers
  // *************************************
  // *** Genereren doorlopende nummers ***
  // *************************************

  //region Boekstuknummer is soms gewoon het factuurnummer
  if @BoekStukNummer is null then
    //set @BoekStukNummer = @FactuurNummer; // Kan niet, omdat het factuurnummer alfanumeriek is!
    call BoekstuknummerGenereren(@BjGidBoeking, @DgbGid, @BoekStukNummer);
  end if;
  //endregion Genereren doorlopende nummers


  //region Boekingsgang controleren/aanmaken
  // *****************************************
  // *** Boekingsgang controleren/aanmaken ***
  // *****************************************

  if @BoekgangGid is null then
  begin
    declare @LockResult smallint;

    declare @VerwerkenInkoopFacturenTekst long nvarchar;
    set @VerwerkenInkoopFacturenTekst = _A('Verwerken inkoopfacturen %1!');
    set @VerwerkenInkoopFacturenTekst = _VervangMetRondeHaakjes(@VerwerkenInkoopFacturenTekst, 40, @NawNaam1);

    insert into tabBoekingsGang(BoekGangBjGid, BoekGangBronId, BronOms,                       BoekGangInGebruik, IsBoekGangDefinitief)
                        values (@BjGidBoeking, 37,             @VerwerkenInkoopFacturenTekst, 1,                 0);
    set @BoekgangGid = @@Identity;
    if @ConnId <> @@SpId or @LoginTime <> @@LoginTime then
      // Lock staat nu op verkeerde connectie! Dus omzetten naar de gewenste connectie
      call LockreleaseOnId(@@SpId, @@LoginTime, 1/*Exclusive lock*/, 'tabBoekingsgang','BoekgangGid='+string(@BoekgangGid));
      call LockSetOnId(@ConnId, @LoginTime, 1 /*Exclusive lock*/, 'tabBoekingsgang','BoekgangGid='+string(@BoekgangGid), @LockResult);
      if @LockResult <> 0 then
        //'(20370) %1! kan niet worden gelockt!'
        call Raise(20370, _U('Boekingsgang'));
      end if;
    end if;
  end
  else
    // Boekingsgang eventueel in gebruik nemen
    update tabBoekingsgang
    set    BoekGangInGebruik = 1
    where  BoekGangInGebruik = 0
       and BoekgangGid = @BoekgangGid;
  end if;
  //endregion Boekingsgang controleren/aanmaken

  // **************************************
  // *** Factuur in journaalpost zetten ***
  // **************************************

  //region Factuur in journaalpost zetten
  begin
    declare @JpGid integer;
    declare @DarGid integer;

    //region Aanmaken nieuwe journaalpost
    // ________________________________________
    // Journaalpost in de boekingsgang aanmaken
    // ----------------------------------------
    begin
      insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, JpBjGID,      JpPerNr,       BoekDatum,  BoekStukNummer, OmsJournaalpost)
                           values(@BoekGangGid,  1,             @DgbGid, @BjGidBoeking, @PerNrBoeking, @Boekdatum, @BoekStukNummer, @Oms);
      set @JpGid = @@Identity;
    end; //endregion Aanmaken nieuwe journaalpost

    //region Digitaal archief
    select first DaIfkDargid
    into @DarGid
    from tabDigitaalArchiefInkoopfactuur
    inner join tabDigitaalArchief on DarGid = DaIfkDarGid
    where DaIfkIfkGid     = @IfkGid
      and DaIfkIsFactuur  = 1;     /*Moet het factuurarchiefstuk zijn*/

  // onderstaande 2 regels uitgezet ivm Defect 56580  ( Archiefstuk koppelen vanuit Inkoopfacturen doet het niet meer sinds 5.61/62 )
  // de check op DaIfkIsFactuur zou genoeg moeten zijn

    //  and DarVerwerkSoort = 1     /*Invoeren journaalposten*/
    //  and DarDgbGID = @DgbGid;    /*In zelfde dagboek*/
    //endregion

    //region Journaalregels: Boeken van crediteur met BTW als hulprekening
    // _____________________________________________________________
    // Journaalregels: Boeken van crediteur met BTW als hulprekening
    // -------------------------------------------------------------
    begin
      declare @RegelBedragInclBtwInValVanFactuur  numeric(15,2) = 0;
      declare @RegelBedragInclBtwInBasisVal       numeric(15,2) = 0;
      declare @BtwBedragInBasisVal                numeric(15,2) = 0;

        //call trace('Boeken op crediteur met BTW als hulprekening');
      set @JrVolgNr = 0; // We beginnen bij 0, want bij toevoegen wordt eerst het nummer verhoogd

      // Factuurboekingen zjin per btw-code gegroepeerd
      for @Cursor AS CURSOR_BTW_boekingen CURSOR FOR
        // BTW o.b.v. het BTW-blok
        select   0                  @Regelsoort,
                 IfbBtwCode         @BtwCode,
                 BtwRksGid          @BtwRksGid,
                 IfbGrondslagBedrag @GrondslagBedragInValVanFactuur,
                 IfbBtwBedrag       @BtwBedragInValVanFactuur
        from     tabInkoopfactuurBtwblok
                 inner join tabBTW on BtwCode = IfbBtwCode
        where    IfbIfkGid = @IfkGid
        union all
        // Als er geen BTW-regels zijn, dan tóch 1 regel op de crediteur boeken!
        select   1                  @Regelsoort,
                 null               @BtwCode,
                 null               @BtwRksGid,
                 0.0                @GrondslagBedragInValVanFactuur,
                 0.0               @BtwBedragInValVanFactuur
        from     tabInkoopfactuurKop
        where    IfkGid = @IfkGid
        order by @Regelsoort, @BtwCode
      for read only
      do
        //Omrekeningen naar basisvaluta
        set @RegelBedragInclBtwInValVanFactuur = @GrondslagBedragInValVanFactuur + @BtwBedragInValVanFactuur;
        if @ValNummer = @@BasisValutaNummer then
          set @RegelBedragInclBtwInBasisVal = @RegelBedragInclBtwInValVanFactuur;
          set @BtwBedragInBasisVal          = @BtwBedragInValVanFactuur;
        else
          set @RegelBedragInclBtwInBasisVal = ValutaOmrekenen(@ValNummer, @RegelBedragInclBtwInValVanFactuur, @@BasisValutaNummer, @BjGidBoeking, @PerNrBoeking, 2);
          set @BtwBedragInBasisVal          = ValutaOmrekenen(@ValNummer, @BtwBedragInValVanFactuur, @@BasisValutaNummer, @BjGidBoeking, @PerNrBoeking, 2);
        end if;

        if @Regelsoort = 0 or @JrVolgNr = 0 then
          // Als het een BTW-regel is of het is de eerste regel, dan boeken!
          // Dus boeken gebeurt ook als er helemaal geen BTW-regel was! (Dan is namelijk @JrVolgNr nog 0)

          // Volgnummer verhogen
          if @JrVolgNr < 999 then
            set @JrVolgNr = @JrVolgNr + 1;
          end if;

          // Boeking op rekening van crediteur
          insert into tabJournaalregel(
                 //Meta-informatie over de journaalregel
                 JrJpGID,
                 JrRksGID,
                 JrRksInvoer,
                 JrBjGid,
                 JrPerNr,
                 JrBoekdatum,
                 StukVolgnr,
                 JrReferentie,
                 JrReferentie_Lengte,
                 JrBoekStukNummer,
                 OmsJournaalRegel,
                 // Gegevens over de OSP
                 JrOspGefiatteerd,
                 JrFactuurDatum,
                 JrVervaldatum,
                 JrBetalingsKenmerk,
                 //Financiele informatie
                 SoortBoeking,
                 IsCreditBoeking,
                 JrValNummer,
                 JrValutaBedrag,
                 JrBasisBedrag,
                 JrDarGid
                )
          values(
                 //Meta-informatie over de journaalregel
                 /*JrJpGID=*/              @JpGID,
                 /*JrRksGID=*/             @NawRksGid,
                 /*JrRksInvoer=*/          @NawNummer,
                 /*JrBjGid=*/              @BjGidBoeking,
                 /*JrPerNr=*/              @PerNrBoeking,
                 /*JrBoekdatum=*/          @Boekdatum,
                 /*StukVolgnr=*/           @JrVolgNr,
                 /*JrReferentie=*/         @FactuurNummer,
                 /*JrReferentie_Lengte=*/  length(@FactuurNummer),
                 /*JrBoekStukNummer=*/     @BoekStukNummer,
                 /*OmsJournaalRegel=*/     @Oms,
                 // Gegevens over de OSP
                 /*JrOspGefiatteerd=*/     @IsGefiatteerd,
                 /*JrFactuurDatum=*/       @Factuurdatum,
                 /*JrVervaldatum=*/        @Vervaldatum,
                 /*JrBetalingsKenmerk=*/   @Betalingskenmerk,
                 //Financiele informatie
                 /*SoortBoeking=*/         0 /*Normale boeking*/,
                 /*IsCreditBoeking=*/      1 /*Credit*/,
                 /*JrValNummer=*/          @ValNummer,
                 /*JrValutaBedrag=*/       @RegelBedragInclBtwInValVanFactuur,
                 /*JrBasisBedrag=*/        @RegelBedragInclBtwInBasisVal,
                 /*JrDarGid=*/             @DarGid
                );

          // *** BTW-boekingen als hulprekening ***
          // Het kan zijn dat er GEEN btw-code was, dan is er dus ook geen hulprekening!
          if @BtwRksGid is not null then
              //call trace('BTW-boeking als hulprekening in valuta van de factuur');
            insert into tabHulprekening(
                    HulpRekJrGid,
                    HulpRekSoort,
                    HulpRekRksGid,
                    HulpRekBtwCode,
                    HulpRekIsCredit,
                    HulpRekValNummer,
                    HulpRekValutaBedrag,
                    HulpRekBedragInJrValnummer,
                    HulpRekBasisBedrag
                  )
            values(
                    /*HulpRekJrGid=*/               @@Identity,
                    /*HulpRekSoort=*/               1 /*BTW*/,
                    /*HulpRekRksGid=*/              @BtwRksGid,
                    /*HulpRekBtwCode=*/             @BtwCode,
                    /*HulpRekIsCredit=*/            0 /*Debet*/,
                    /*HulpRekValNummer=*/           @ValNummer,
                    /*HulpRekValutaBedrag=*/        @BtwBedragInValVanFactuur,
                    /*HulpRekBedragInJrValnummer=*/ @BtwBedragInValVanFactuur,
                    /*HulpRekBasisBedrag=*/         @BtwBedragInBasisVal
                  );
          end if;
        end if;
      end for; //CURSOR_BTW_boekingen
    end;
    //endregion Journaalregels: Boeken van crediteur met BTW als hulprekening


    //region Bereken per regel het Nu Te Boeken Bedrag per PrijsPer
    // __________________________________________________
    // Berekenen van het nu te boeken bedrag per PrijsPer
    // --------------------------------------------------
  if @OntvBoekenTegen = 0 /*VVP*/ then
    //Voor alle artikel- en partijregels het te boeken bedrag bepalen o.b.v. VVP
    //Niet afronden, zodat alle decimalen (tot 6 stuks) bewaard kunnen blijven voor verdere berekeningen
    update tabInkoopfactuurRegel
    set    IfrTussenrekeningPrijsPerAantal   = if IfrRegelSoort = 2 /*Artikel*/ then ArtPrijsPer else 1 endif,
      IfrTussenrekeningBedragInPrijsPer = (if ArtIsPartijAparteKostPrijs = 1 then  ArtPartijKostprijsEx else ArtKostprijsEx end if),
      IfrTussenrekeningValNummer = @@BasisValutaNummer
    from tabInkoopfactuurRegel
      inner join tabArtikel on ArtGid = IfrArtGid
      left outer join tabArtikelPartij on ArtPartijGid = IfrArtPartijGid
    where IfrIfkGid = @IfkGid
    // ACW 22-04-2024 Defect 59316: Als tussenrekening niet bij MagOnt geboekt, dan is het hier NULL en alleen dan gaan we het bedrag bepalen
    // RB  22-05-2026 Defect 60228: ook als IfrTussenrekeningPrijsPerAantal 0.00 is
    and ((IfrTussenrekeningBedragInPrijsPer is null) or (IfrTussenrekeningPrijsPerAantal=0.0));
  else /*@OntvBoekenTegen = 1, Werkelijke inkoopprijs*/
  //Voor alle artikel- en partijregels het te boeken bedrag bepalen o.b.v. werkelijke inkoopprijs
    update tabInkoopfactuurRegel
    set    IfrTussenrekeningPrijsPerAantal   = if IfrRegelSoort = 2 /*Artikel*/ then IfrPrijsPer else 1 endif,
      IfrTussenrekeningBedragInPrijsPer = if IfrAantal = 0 then 0 else (IfrRegeltotaalExclBtw / (IfrAantal * IfrVoorraadeenhedenInInkoopeenheid)) * ArtPrijsPer endif,
      IfrTussenrekeningValNummer = IfkValNummer
    from tabInkoopfactuurRegel
      inner join tabArtikel on ArtGid = IfrArtGid
      left outer join tabArtikelPartij on ArtPartijGid = IfrArtPartijGid
      inner join tabInkoopfactuurKop on IfkGid = IfrIfkGid
    where IfrIfkGid = @IfkGid
    // ACW 22-04-2024 Defect 59316: Als tussenrekening niet bij MagOnt geboekt, dan is het hier NULL en alleen dan gaan we het bedrag bepalen
    // RB  22-05-2026 Defect 60228: ook als IfrTussenrekeningPrijsPerAantal 0.00 is
    and ((IfrTussenrekeningBedragInPrijsPer is null) or (IfrTussenrekeningPrijsPerAantal=0.0));
  end if;
    //endregion Bereken per regel het Nu Te Boeken Bedrag per PrijsPer



    // _____________________________________
    // Artikelen per groep op tussenrekening
    // -------------------------------------
    // Boeken van tussenrekening (artikel) en kostprijzen (tarieven) per opbrengstgroep en prijsverschillen
    begin // Artikelen, Tarieven en prijsverschillen
      // Constantes voor de paragrafen
      declare @ParagraafVoorKosten           integer = 40;
      declare @ParagraafVoorPrijsverschillen integer = 90;



      //region Ontbrekende opbrengstgroeprekeningen aanmaken
      // _____________________________________________
      // Ontbrekende opbrengstgroeprekeningen aanmaken
      // ---------------------------------------------
      begin
        //Alle ontbrekende rekeningen voor opbrengstgroepen vullen voor
        // - de kosten, paragraaf 40 (Alleen voor tarieven)
        // - prijsverschillen, paragraaf 90
          //call trace('--- Resultaatgroepen aanmaken');
        for @CursorOpbrGrp AS CURSOR_Opbrengstgroepen CURSOR FOR
          select distinct ArtOpbrGrpGid @ArtOpbrGrpGid, IfrRegelSoort @RegelSoort
          from tabInkoopfactuurRegel
               inner join tabArtikel on ArtGid = IfrArtGid
          where IfrIfkGid = @IfkGid
        for read only do
          if @RegelSoort = 1 /*Tarief*/ then
            call OpbrengtGroepsoortenVullen(@ArtOpbrGrpGid, @ParagraafVoorKosten);
          end if;
          call OpbrengtGroepsoortenVullen(@ArtOpbrGrpGid, @ParagraafVoorPrijsverschillen);
        end for;
      end;
      //endregion Ontbrekende opbrengstgroeprekeningen aanmaken



      //region Artikelen boeken op tussenrekening per referentie
      // ________________________________________________________________________________
      // Regels: Boeken van artikelen per referentie naar de tussenrekening o.b.v. de VVP
      // --------------------------------------------------------------------------------
      begin
          //call trace('--- Boeken artikelen op tussenrekening per referentie');
        insert into tabJournaalRegel(
                   //Meta-informatie over de journaalregel
                   JrJpGID,
                   JrRksGID,
                   JrRksInvoer,
                   JrBjGid,
                   JrPerNr,
                   JrBoekdatum,
                   StukVolgnr,
                   JrReferentie,
                   JrReferentie_Lengte,
                   JrBoekStukNummer,
                   OmsJournaalRegel,
                   //Financiele informatie
                   SoortBoeking,
                   IsCreditBoeking,
                   JrValNummer,
                   JrValutaBedrag,
                   JrBasisBedrag,
                   JrDarGid
                   )
        select     //Meta-informatie over de journaalregel
                   /*JrJpGID=*/             @JpGid,
                   /*JrRksGID=*/            @TussenrekeningInkopenRksGid,
                   /*JrRksInvoer=*/         @TussenrekeningInkopenRksInvoer,
                                            /*TODO Factuurnummer wordt later het referentienummer van de kop/regel en nog later per koppeling naar magazijnontvangst met een restant*/
                   /*JrBjGid=*/             @BjGidBoeking,
                   /*JrPerNr=*/             @PerNrBoeking,
                   /*JrBoekdatum=*/         @Boekdatum,
                   /*StukVolgnr=*/          lesser(999, @JrVolgNr + identity(0)),
                   /*JrReferentie=*/        IfrReferentienummer,
                   /*JrReferentie_Lengte=*/ Length(IfrReferentienummer),
                   /*JrBoekStukNummer=*/    @BoekStukNummer,
                   /*OmsJournaalRegel=*/    @Oms,
                   //Financiele informatie
                   /*SoortBoeking=*/        0 /*Normale boeking*/,
                   /*IsCreditBoeking=*/     0 /*Debet*/,
                   /*JrValNummer=*/         IfrTussenrekeningValNummer,
                   /*JrValutaBedrag=*/      /*Totaal obv VVP berekenen, later het werkelijk geboekte bedrag*/
                                            sum(round(ifrAantal * IfrVoorraadeenhedenInInkoopeenheid / IfrTussenrekeningPrijsPerAantal * IfrTussenrekeningBedragInPrijsPer, 2)) as BedragInVal,
                   /*JrBasisBedrag=*/       ValutaOmrekenen(IfrTussenrekeningValNummer, BedragInVal, @@BasisValutaNummer, @BjGidBoeking, @PerNrBoeking, 4) BedragInbasis,
                   /*JrDarGid=*/            @DarGid
        from tabInkoopfactuurRegel
        where IfrIfkGid = @IfkGid
          and IfrRegelSoort = 2 /*Artikel*/
          //RB-60176 toch weer boeken van 0,00 bedrag op tussenrekening inkopen/referentienr ivm defect tonen al geboekte ontvangsten
          //RB-60176 Wellicht dat division by zero van hieronder weer terug komt? die kreeg ik niet meer voor elkaar
          //RB-60176 and IfrTussenrekeningBedragInPrijsPer <> 0.00 /*Defect 59864, dit bedrag kan 0 zijn als kostprijs=0, maar dat hoeft dan niet te worden geboekt*/
        //order by @FactuurNummer
        group by
              IfrReferentienummer,
              IfrTussenrekeningValNummer
 //RB-60176       having
 //RB-60176             BedragInVal <> 0
 ;

        // Volgnummer verhogen
        set @JrVolgNr = lesser(999, @JrVolgNr + @@RowCount);
      end; //endregion Artikelen boeken op tussenrekening per referentie


      //region Tarieven boeken op kostenrekening van betreffende tarief
      begin
        // _____________________________________________________________________________________________________________________
        // Regels: Boeken van tariefregels per opbrengstgroep op de paragraaf 'Kostprijzen' van de opbrengstgroep van het tarief
        // ---------------------------------------------------------------------------------------------------------------------
        //call trace('--- Boeken tarieven per opbrengstgroep');
        insert into tabJournaalRegel(
                   //Meta-informatie over de journaalregel
                   JrJpGID,
                   JrRksGID,
                   JrRksInvoer,
                   JrBjGid,
                   JrPerNr,
                   JrBoekdatum,
                   StukVolgnr,
                   JrReferentie,
                   JrReferentie_Lengte,
                   JrBoekStukNummer,
                   OmsJournaalRegel,
                   //Financiele informatie
                   SoortBoeking,
                   IsCreditBoeking,
                   JrValNummer,
                   JrValutaBedrag,
                   JrBasisBedrag,
                   JrDarGid
                   )
        select     //Meta-informatie over de journaalregel
                   /*JrJpGID=*/             @JpGid,
                   /*JrRksGID=*/            GrpSoortRksGID,
                   /*JrRksInvoer=*/         RksInvoer,
                   /*JrBjGid=*/             @BjGidBoeking,
                   /*JrPerNr=*/             @PerNrBoeking,
                   /*JrBoekdatum=*/         @Boekdatum,
                   /*StukVolgnr=*/          lesser(999, @JrVolgNr + identity(0)),
                   /*JrReferentie=*/        '', //IfrReferentienummer,  GEEN referentienummer bij kostprijsboeking
                   /*JrReferentie_Lengte=*/ 0, //Length(IfrReferentienummer),
                   /*JrBoekStukNummer=*/    @BoekStukNummer,
                   /*OmsJournaalRegel=*/    @Oms,
                   //Financiele informatie
                   /*SoortBoeking=*/        0 /*Normale boeking*/,
                   /*IsCreditBoeking=*/     0 /*Debet*/,
                   /*JrValNummer=*/         @ValNummer,
                   /*JrValutaBedrag=*/      sum(IfrRegeltotaalExclBtw) BedragInVal,
                   /*JrBasisBedrag=*/       if @ValNummer = @@BasisValutaNummer then
                                              BedragInVal
                                            else
                                              ValutaOmrekenen(@ValNummer, BedragInVal, @@BasisValutaNummer, @BjGidBoeking, @PerNrBoeking, 2)
                                            endif,
                   /*JrDarGid=*/            @DarGid
        from tabInkoopfactuurRegel
             inner join tabArtikel on ArtGid = IfrArtGid
             inner join tabOpbrengstgroep on OpbrGrpGid = ArtOpbrGrpGid
             inner join tabOpbrengstgroepSoort on (GrpSoortGrpGId = OpbrGrpGId) and GrpSoortParSoort = @ParagraafVoorKosten
             inner join tabRekeningschema on RksGid = GrpSoortRksGID
        where IfrIfkGid = @IfkGid
          and IfrRegelSoort = 1 /*Tarief*/
        group by ArtOpbrGrpGId, GrpSoortRksGID, RksInvoer //, IfrReferentienummer   GEEN referentienummer bij kostprijsboeking
        order by RksInvoer;
        // Volgnummer verhogen

        set @JrVolgNr = lesser(999, @JrVolgNr + @@RowCount);
      end;
      //endregion Tarieven boeken op kostenrekening van betreffende tarief


      //region Boeken van prijsverschillen
      begin
        // _______________________
        // Prijsverschillen boeken
        // -----------------------
        /* Dit is het verschil tussen de geboekte bedragen en de inkoopbedragen:
           (regeltotaal) IfrAantal * IfrPrijs -
           (geboekt)     (IfrAantal * VoorraadeenhedenInInkoopeenheid / IfrTussenrekeningPrijsPerAantal) * IfrBedragOpTussenrekPerPrijsPer
                         Om Geboekt te berekenen is het dus aantal inkoopeenheden * voorraadeenheden per inkoopeenheid, maar dan nog delen door de GeprijsdPerAantal van het artikel
           Mocht in de toekomst het aantal worden gedifferentieerd tot deel op de tussenrekening en deel nog te boeken, dan vindt hier de scheiding plaats
        */
          //call trace('--- Boeken Prijsverschillen');
        insert into tabJournaalRegel(
                   //Meta-informatie over de journaalregel
                   JrJpGID,
                   JrRksGID,
                   JrRksInvoer,
                   JrBjGid,
                   JrPerNr,
                   JrBoekdatum,
                   StukVolgnr,
                   JrReferentie,
                   JrReferentie_Lengte,
                   JrBoekStukNummer,
                   OmsJournaalRegel,
                   //Financiele informatie
                   SoortBoeking,
                   IsCreditBoeking,
                   JrValNummer,
                   JrValutaBedrag,
                   JrBasisBedrag,
                   JrDarGid
                   )
        select     //Meta-informatie over de journaalregel
                   /*JrJpGID=*/             @JpGid,
                   /*JrRksGID=*/            GrpSoortRksGID,
                   /*JrRksInvoer=*/         RksInvoer,
                   /*JrBjGid=*/             @BjGidBoeking,
                   /*JrPerNr=*/             @PerNrBoeking,
                   /*JrBoekdatum=*/         @Boekdatum,
                   /*StukVolgnr=*/          lesser(999, @JrVolgNr + identity(0)),
                   /*JrReferentie=*/        '', //Defect 52342: Niet meer o.b.v. factuurnummer! @FactuurNummer,
                   /*JrReferentie_Lengte=*/ length(@FactuurNummer),
                   /*JrBoekStukNummer=*/    @BoekStukNummer,
                   /*OmsJournaalRegel=*/    @Oms,
                   //Financiele informatie
                   /*SoortBoeking=*/        0 /*Normale boeking*/,
                   /*IsCreditBoeking=*/    if tbPrijsverschil.calcPrijsverschilInBasis > 0 then
                                             0 /*Debet*/
                                           else
                                             1 /*Credit*/
                                           endif,
                   /*JrValNummer=*/        @@BasisValutaNummer,
                   /*JrValutaBedrag=*/     abs(tbPrijsverschil.calcPrijsverschilInBasis) PrijsverschilInBasis,
                   /*JrBasisBedrag=*/      PrijsverschilInBasis,
                   /*JrDarGid=*/           @DarGid

        from
                 (select   ArtOpbrGrpGid, IfrIfkGid,
                           sum(
                               // /*regeltotaal*/ round(IfrAantal * ((IfrPrijs - IfrKortingBedrag) * if IfrPrijsPerSoort = 0 /*Inkoopeenheid*/ then 1 else /* X voorr.eenh.*/ IfrVoorraadeenhedenInInkoopeenheid / ArtPrijsPer endif) * (100-IfrKortingPercentage)/100, 2)
                               /*regeltotaal*/ if @ValNummer = @@BasisValutaNummer then IfrRegeltotaalExclBtw else ValutaOmrekenen(@ValNummer, IfrRegeltotaalExclBtw, @@BasisValutaNummer, @BjGidBoeking, @PerNrBoeking, 2) endif
                               /*minus*/        -
                                               if isnull(IfrTussenrekeningPrijsPerAantal * IfrTussenrekeningBedragInPrijsPer, 0.00) = 0.00 then
                                                 0.00 // Incident #32430 Dyn2Dev, controle op juiste veld voor de berekening voor oplossing van defect 59864/59876 (eerdere oplossing via de where-clause was onjuist)
                                               else
                               /*geboekt*/       if IfrTussenrekeningValNummer = @@BasisValutaNummer then round(ifrAantal * IfrVoorraadeenhedenInInkoopeenheid / IfrTussenrekeningPrijsPerAantal * IfrTussenrekeningBedragInPrijsPer, 2)
                                                 else        ValutaOmrekenen(IfrTussenrekeningValNummer,  round(ifrAantal * IfrVoorraadeenhedenInInkoopeenheid / IfrTussenrekeningPrijsPerAantal * IfrTussenrekeningBedragInPrijsPer, 2), @@BasisValutaNummer, @BjGidBoeking, @PerNrBoeking, 2) endif
                                               endif
                              ) calcPrijsverschilInBasis
                  from     tabInkoopfactuurRegel
                           inner join tabArtikel on ArtGid = IfrArtGid
               inner join tabInkoopfactuurKop on IfkGid = IfrIfkGid
                  where    IfrIfkGid = @IfkGid and IfrRegelSoort = 2 /*Artikel*/ //Alleen voor artikelen kan er een prijsverschil ontstaan
                       //and IfrTussenrekeningBedragInPrijsPer <> 0.00 /*Defect 59864, dit bedrag kan 0 zijn als kostprijs=0, maar dat hoeft dan niet te worden geboekt*/
                  group by ArtOpbrGrpGid, IfrIfkGid
                 ) tbPrijsverschil
                 inner join tabOpbrengstgroepSoort on (GrpSoortGrpGId = ArtOpbrGrpGId) and GrpSoortParSoort = @ParagraafVoorPrijsverschillen
                 inner join tabOpbrengstgroep on OpbrGrpGid = ArtOpbrGrpGid
                 inner join tabRekeningschema on RksGid = GrpSoortRksGID
         inner join tabInkoopfactuurKop on IfkGid = IfrIfkGid
        where    tbPrijsverschil.calcPrijsverschilInBasis <> 0
        order by RksInvoer;
      end;
      //endregion Boeken van prijsverschillen

    end; // Artikelen, Tarieven en prijsverschillen


    //region Afsluiten journaalpost
    // ______________________
    // Afsluiten journaalpost
    // ----------------------
    //call trace('Sluiten journaalpost');
    update tabJournaalPost set JpIsIngebruik = 0 where JpGid = @JpGid;
    //endregion Afsluiten journaalpost

  end; //region Factuur in journaalpost zetten

  //region Eventueel afsluiten boekingsgang
  // ______________________
  // Afsluiten boekingsgang
  // ----------------------
  if @KeepBoekgangOpen = 0 then
    update tabBoekingsgang set BoekGangInGebruik = 0 where BoekgangGid = @BoekgangGid;
  end if;
  //endregion Eventueel afsluiten boekingsgang

  // ______________________
  // De inkoopfactuur verwerken in de inkoopstatistieken
  // ----------------------
  call InkoopFactuurVerwerkenInInkoopStatistieken(@IfkGid, @Boekdatum);

  // __________________________________
  // Status van inkoopfactuur aanpassen
  // ----------------------------------
  if IsModuleActive('if') <> 0 then
    update tabInkoopfactuurKop
    set    IfkIsVerwerkt   = 1,
           IfkVerwerktDoor = @@gebruikercode,
           IfkVerwerktOp   = now()
    where IfkGid = @IfkGid;
  else
    delete tabInkoopfactuurKop where IfkGid = @IfkGid;
  endif;

  set @@ErrorTextProcedure = 'BoekInkoopfactuur >' + string(@IfkGid)+', ' + string(@Boekdatum)+', BoekgangGid=' + string(@BoekgangGid);
    //call traceEind(@@ErrorTextProcedure);

end;

