create or replace function BoekjaarBepalen(in @Datum Date)
returns integer
begin
  declare @BjGid integer;

  set @@ErrorTextProcedure = 'BoekjaarBepalen > @Datum='+string(@Datum);
  //call TraceBegin(@@ErrorTextProcedure);

  select PerBjGid into @BjGid from tabPeriode where @Datum between BeginDatum and EindDatum;

  set @@ErrorTextProcedure = 'BoekjaarBepalen > @BjGid='+string(@BjGid);
  //call TraceEind(@@ErrorTextProcedure);
  return (@BjGid);

end;


create or replace procedure BoekstuknummerGenereren(in @BjGid integer, in @DgbGid integer, inout @BoekStukNummer numeric(10,0), in @IgnoreBoekgangGid integer default null)
begin
  //Genereer een nieuw boekstuknummer a.d.h.v. een dagboek en zijn instellingen
  declare @DefBoekstuk smallint;

  //call TraceBegin('BoekstuknummerGenereren > @BjGid = ' + string(@BjGid) + ', @DgbGid = ' + string(@DgbGid));

  select DefBoekstuk into @DefBoekstuk from tabDagboek where DgbGid=@DgbGid;

  if @DefBoekStuk = 0 then         //Leeg
     set @BoekStukNummer=0;
  else
    if @DefBoekStuk = 1 then
      call BoekstuknummerPlusEen(@BjGid, @DgbGid, 1, @BoekstukNummer, @IgnoreBoekgangGid);
    else
      call BoekstuknummerPlusEen(@BjGid, @DgbGid, 0, @BoekstukNummer, @IgnoreBoekgangGid);
    end if;
  end if;

  //call TraceEind('BoekstuknummerGenereren > @Boekstuknummer = ' + string(@Boekstuknummer));
end;


create or replace procedure BoekstuknummerPlusEen(in @BjGid integer, in @DgbGid integer, in @HoogstePlusEen smallint, inout @BoekstukNummer numeric(10,0), in @IgnoreBoekgangGid integer default null)
begin
  //call TraceBegin('BoekstuknummerPlusEen > @BjGid = ' + string(@BjGid) + ', @DgbGid = ' + string(@DgbGid) + ', @HoogstePlusEen = ' + string(@HoogstePlusEen));

  set @BoekStukNummer=null;
  if @IgnoreBoekgangGid is null then
    if @HoogstePlusEen<>0 then
      select max(BoekStukNummer) into @BoekStukNummer from tabJournaalpost where JpDgbGid=@DgbGid and JpBjGid=@BjGid
      OPTION(Isolation_level=0);
    else                   //Laatst gebruikte van dagboek plus één
      select first BoekStukNummer into @BoekStukNummer from tabJournaalpost where JpDgbGid=@DgbGid and JpBjGid=@BjGid order by JpGid desc
      OPTION(Isolation_level=0);
    end if;
  else
    if @HoogstePlusEen<>0 then
      select max(BoekStukNummer) into @BoekStukNummer from tabJournaalpost where JpDgbGid=@DgbGid and JpBjGid=@BjGid and JpBoekgangGid <> @IgnoreBoekgangGid
      OPTION(Isolation_level=0);
    else                   //Laatst gebruikte van dagboek plus één
      select first BoekStukNummer into @BoekStukNummer from tabJournaalpost where JpDgbGid=@DgbGid and JpBjGid=@BjGid and JpBoekgangGid <> @IgnoreBoekgangGid order by JpGid desc
      OPTION(Isolation_level=0);
    end if;
  end if;
  if IsNull(@BoekStukNummer,0) <> 9999999999 then
    set @BoekStukNummer = IsNull(@BoekStukNummer,0) + 1;
  end if;

  //call TraceEind('BoekstuknummerPlusEen > @BoekstukNummer = ' + string(@BoekstukNummer));
end;


create or replace procedure BoekstuknummerPlusEenExJpGid(in @BjGid integer, in @DgbGid integer, in @JpGid integer, in @HoogstePlusEen smallint, inout @BoekstukNummer numeric(10,0))
begin
  //call TraceBegin('BoekstuknummerPlusEenExJpGid > @BjGid = ' + string(@BjGid) + ', @DgbGid = ' + string(@DgbGid) + ', @JpGid = ' + string(@JpGid) + ', @HoogstePlusEen = ' + string(@HoogstePlusEen));

  set @BoekStukNummer = null;
  if @HoogstePlusEen <> 0 then
    if @JpGid is null then
      select IsNull(max(BoekStukNummer),0) into @BoekStukNummer from tabJournaalpost where JpDgbGid=@DgbGid and JpBjGid=@BjGid;
    else
      select IsNull(max(BoekStukNummer),0) into @BoekStukNummer from tabJournaalpost where JpDgbGid=@DgbGid and JpBjGid=@BjGid and JpGid <> @JpGid;
    end if;
  else                   //Laatst gebruikte van dagboek plus één
    if @JpGid is null then
      select first IsNull(BoekStukNummer,0) into @BoekStukNummer from tabJournaalpost where JpDgbGid=@DgbGid and JpBjGid=@BjGid order by JpGid desc;
    else
      select first IsNull(BoekStukNummer,0) into @BoekStukNummer from tabJournaalpost where JpDgbGid=@DgbGid and JpBjGid=@BjGid and JpGid <> @JpGid order by JpGid desc;
    end if;
  end if;
  if IsNull(@BoekStukNummer,0) <> 9999999999 then
    set @BoekStukNummer = IsNull(@BoekStukNummer,0) + 1
  end if;

  //call TraceEind('BoekstuknummerPlusEenExJpGid > @BoekstukNummer = ' + string(@BoekstukNummer));
end;


create or replace function BouwKIXCode ( in @LndGid            Integer,
                                         in @PostCode          nchar(40),          // AdrPostcode
                                         in @HuisAanduiding    nchar(10)           // AdrHuisnummer
                                       )

returns nchar(54)                              //maximale lengte =land(2)postcode(40)huisnummer(5)X(1)toevoeging(6)
begin
  declare @HuisNummer     nchar(5);
  declare @Toevoeging     nchar(6);
  declare @KarakterSet    nchar(36);           // **** alles controleren op karakterset
  declare @KIXCode        nchar(20);
  declare @Teller         smallint;
  declare @landAfdrukken  smallint;
  declare @LandCode       nchar(3);

  set @@ErrorTextProcedure = 'BouwKIXCode > ';
  //call TraceBegin(@@ErrorTextProcedure + '@LndGid = ' + string(@LndGid) + ', @PostCode = ' + @PostCode + ', @HuisAanduiding = ' + @HuisAanduiding);

  set @KarakterSet = 'abcdefghijklmnopqrstuvwxyz';

  select lndInNAWBlok, lndEigenCode into @landAfdrukken, @LandCode from tabLand where lndGid = @lndGid;

  if @landAfdrukken <> 0 then                 // Controleer of land ongelijk is aan eigen land.
    set @KIXCode = Stripstring (@LandCode, @KarakterSet);
  else
    set @KIXCode = '';
  end if ;

  set @KarakterSet = '1234567890abcdefghijklmnopqrstuvwxyz';

  //Voeg postcode toe
  set @KIXCode = @KIXCode + Stripstring (@PostCode, @KarakterSet);

  //call Trace('BouwKIXCode > Splits @HuisAanduiding in @HuisNummer (numeriekdeel) en @Toevoeging');

  set @Teller = 1;
  set @HuisAanduiding = Stripstring (@HuisAanduiding, @KarakterSet);
  while @Teller <= length(@HuisAanduiding) and @Teller <= 5 and
        locate('1234567890',substr(@HuisAanduiding,@Teller,1)) <> 0 loop
    set @Teller = @Teller + 1;
  end loop;

  //call Trace('BouwKIXCode > @Teller = ' + string(@Teller));

  set @HuisNummer = substr(@HuisAanduiding,1, @Teller - 1);
  set @Toevoeging = substr(@HuisAanduiding, @Teller, 6);

  set @KIXCode = @KIXCode + @HuisNummer + (if (@Toevoeging <> '') then 'X'  + @Toevoeging else '' endif);

  set @@ErrorTextProcedure = 'BouwKIXCode';
  //call TraceEind(@@ErrorTextProcedure + ' > @KIXCode = ' + @KIXCode);

  return (@KIXCode);
end;


create or replace procedure BtwAangifte(in @BjGid Integer, in @Selectie Integer, in @VanDatum date, in @TotDatum date, in @VanMaand integer, in @TotMaand integer, in @VoorlDef smallint) //0=Definitief, 1=Voorlopig, 2=Voorlopig en definitief
begin
  declare @EuroValNummer integer;

  //call TraceBegin('BtwAangifte');
  select  ValNummer  into @EuroValNummer from tabValuta where IsEuro <> 0;
  if @EuroValNummer is null then
   set @EuroValNummer = @@BasisValutaNummer;
  end if;

  select  BtwRubriekAangifte,
          sum(if DefaultSoort in (6,7) then
                if IsCreditBoeking = 0 then
                  ValutaOmrekenen(@@BasisValutaNummer,  JrBasisBedrag, @EuroValNummer, JrBjGid, JrPernr, 2)
                else
                  ValutaOmrekenen(@@BasisValutaNummer, -JrBasisBedrag, @EuroValNummer, JrBjGid, JrPernr, 2)
                endif
              else
                if IsCreditBoeking = 0 then   //Debet
                  ValutaOmrekenen(@@BasisValutaNummer, -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGid, JrPernr, 2)
                else
                  ValutaOmrekenen(@@BasisValutaNummer,  (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGid, JrPernr, 2)
                endif
              endif) BedragIncl,
          sum(if HulpRekIsCredit = 0 then
                ValutaOmrekenen(@@BasisValutaNummer,  HulpRekBasisBedrag, @EuroValNummer, JrBjGid, JrPernr, 2)
              else
                ValutaOmrekenen(@@BasisValutaNummer, -HulpRekBasisBedrag, @EuroValNummer, JrBjGid, JrPernr, 2)
              endif) BtwBedrag,
          -BtwBedrag - BedragIncl BedragExcl,
         //BtwBedragAangifte uitrekenen(rubriek 2a, 4a, 4b)
         //bedragexcl nog een keer uitrekenen om te vermenigvuldigen met BtwPercentageAangifte(per btwcode) en dan sommeren per rubriek
         //dus sum((-BtwBedrag - BedragIncl)*BtwPercentageAangifte/100)
          sum((-Isnull(if HulpRekIsCredit = 0 then
                 ValutaOmrekenen(@@BasisValutaNummer,  HulpRekBasisBedrag, @EuroValNummer, JrBjGid, JrPernr, 2)
               else
                 ValutaOmrekenen(@@BasisValutaNummer, -HulpRekBasisBedrag, @EuroValNummer, JrBjGid, JrPernrr, 2)
               endif,0) -
               if DefaultSoort in (6,7) then
                  if IsCreditBoeking = 0 then
                    ValutaOmrekenen(@@BasisValutaNummer,  JrBasisBedrag, @EuroValNummer, JrBjGid, JrPernr, 2)
                  else
                    ValutaOmrekenen(@@BasisValutaNummer, -JrBasisBedrag, @EuroValNummer, JrBjGid, JrPernr, 2)
                  endif
               else
                 IsNull(if IsCreditBoeking = 0 then   //Debet
                   ValutaOmrekenen(@@BasisValutaNummer, -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGid, JrPernr, 2)
                 else
                   ValutaOmrekenen(@@BasisValutaNummer,  (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGid, JrPernr, 2)
                 endif,0)
               endif)*(BtwPercentageAangifte/100)) BtwBedragAangifte

  from   tabBoekingsgang inner join tabjournaalpost on (JpBoekgangGid = BoekgangGid) inner join tabJournaalRegel on (JrJpGid = JpGid) inner join tabRekeningschema on (JrRksGid=RksGid) left outer join (tabHulpRekening inner join tabBtw on BtwCode = HulpRekBtwCode)on (JrGid = HulpRekJrGid)
  where  BoekGangBjGid = @BjGid and JpBjGid=@BjGid and
         JrBjGid = @BjGid and
         (
           (JrBoekDatum        between @VanDatum and @TotDatum and @Selectie = 1) or
           (MONTH(JrBoekDatum) between @VanMaand and @TotMaand and @Selectie = 2)
         ) and
         ( (@VoorlDef=0 and IsBoekGangDefinitief<>0) or
           (@VoorlDef=1 and IsBoekGangDefinitief =0) or
           (@VoorlDef=2)
         )
  group by BtwRubriekAangifte
  order by BtwRubriekAangifte;

  //call TraceEind('BtwAangifte');



end;

//call BtwAangifte (3, 1, 12, 2);


create or replace procedure BtwAangifteAnalyse(in @VanDatum date, in @TotDatum date, in @VoorlDef smallint) //0=Definitief, 1=Voorlopig, 2=Voorlopig en definitief
begin
  declare @EuroValNummer 	integer;

  declare @iloop 		smallint;
  declare @CurrentRubr		integer;

  declare @BtwRubr 		integer;
  declare @BedragIncl		float;
  declare @BtwBedrag		float;
  declare @BedragExcl		float;
  declare @BtwBedragAangifte	float;

  declare @Oba1aOmzJP    	integer;
  declare @Oba1aOmzBelJP 	integer;
  declare @Oba1bOmzJP    	integer;
  declare @Oba1bOmzBelJP 	integer;
  declare @Oba1cOmzJP    	integer;
  declare @Oba1cOmzBelJP 	integer;
  declare @Oba1dOmzJP    	integer;
  declare @Oba1dOmzBelJP 	integer;
  declare @Oba1eOmzJP    	integer;
  declare @Oba2aOmzJP    	integer;
  declare @Oba2aOmzBelJP 	integer;
  declare @Oba3aOmzJP    	integer;
  declare @Oba3bOmzJP    	integer;
  declare @Oba3cOmzJP    	integer;
  declare @Oba4aOmzJP    	integer;
  declare @Oba4aOmzBelJP 	integer;
  declare @Oba4bOmzJP    	integer;
  declare @Oba4bOmzBelJP 	integer;
  declare @Oba5aOmzBelJP 	integer;
  declare @Oba5bOmzBelJP 	integer;
  declare @Oba5cOmzBelJP 	integer;
  declare @Oba5dOmzBelJP 	integer;
  declare @Oba5eOmzBelJP 	integer;
  declare @Oba5fOmzBelJP 	integer;
  declare @Oba5gOmzBelJP 	integer;
  declare @Oba6aOmzBelJP 	integer;
  declare @Oba6bOmzBelJP 	integer;

  declare @d2aBtwJP		integer;
  declare @d4aBtwJP 		integer;
  declare @d4bBtwJP		integer;

  set @@ErrorTextProcedure = 'BtwAangifteExclBoekjaar > @VanDatum = '+string(@VanDatum)+', @TotDatum = '+string(@TotDatum)+', @VoorlDef = '+string(@VoorlDef);
  //call TraceBegin(@@ErrorTextProcedure);
  select  ValNummer  into @EuroValNummer from tabValuta where IsEuro <> 0;
  if @EuroValNummer is null then
    set @EuroValNummer = @@BasisValutaNummer;
  end if;

  //call Trace('Basisvaluta='+string(@@BasisValutaNummer) + ',Euro='+string(@EuroValNummer));

  set @iloop = 0;

  while @iloop < 13 loop
  //call Trace('Loop->'+string(@iloop));
  if @iloop <> 12 then
    set @CurrentRubr = @iloop
  else
   set @CurrentRubr = 20;
  end if;

  select  BtwRubriekAangifte,
          sum(if DefaultSoort in (6,7) then
                if IsCreditBoeking = 0 then
                  ValutaOmrekenen(@@BasisValutaNummer,  JrBasisBedrag, @EuroValNummer,  JrBjGID, JrPernr, 2)
                else
                  ValutaOmrekenen(@@BasisValutaNummer, -JrBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2)
                endif
              else
                if IsCreditBoeking = 0 then   //Debet
                  ValutaOmrekenen(@@BasisValutaNummer, -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGID, JrPernr, 2)
                else
                  ValutaOmrekenen(@@BasisValutaNummer,  (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGID, JrPernr, 2)
                endif
              endif) BedragIncl,

          sum(if HulpRekIsCredit = 0 then
                ValutaOmrekenen(@@BasisValutaNummer,  HulpRekBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2)
              else
                ValutaOmrekenen(@@BasisValutaNummer, -HulpRekBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2)
              endif) BtwBedrag,

          -BtwBedrag - BedragIncl BedragExcl,

         //BtwBedragAangifte uitrekenen(rubriek 2a, 4a, 4b)
         //bedragexcl nog een keer uitrekenen om te vermenigvuldigen met BtwPercentageAangifte(per btwcode) en dan sommeren per rubriek
         //dus sum((-BtwBedrag - BedragIncl)*BtwPercentageAangifte/100)
          sum((-Isnull(if HulpRekIsCredit = 0 then
                 ValutaOmrekenen(@@BasisValutaNummer,  HulpRekBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2)
               else
                 ValutaOmrekenen(@@BasisValutaNummer, -HulpRekBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2)
               endif,0) -
               if DefaultSoort in (6,7) then
                  if IsCreditBoeking = 0 then
                    ValutaOmrekenen(@@BasisValutaNummer,  JrBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2)
                  else
                    ValutaOmrekenen(@@BasisValutaNummer, -JrBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2)
                  endif
               else
                 IsNull(if IsCreditBoeking = 0 then   //Debet
                   ValutaOmrekenen(@@BasisValutaNummer, -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGID, JrPernr, 2)
                 else
                   ValutaOmrekenen(@@BasisValutaNummer,  (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGID, JrPernr, 2)
                 endif,0)
               endif)*(BtwPercentageAangifte/100)) BtwBedragAangifte

               into @BtwRubr, @BedragIncl, @BtwBedrag, @BedragExcl, @BtwBedragAangifte

  FROM tabBoekingsgang
  	INNER JOIN tabjournaalpost ON (JpBoekGangGid = BoekGangGid)
  	INNER JOIN tabJournaalRegel ON (JpGid = JrJpGid)
  	INNER JOIN tabRekeningschema ON (JrRksGid=RksGid)
  	INNER join (tabHulpRekening INNER join tabBtw on BtwCode = HulpRekBtwCode) ON (JrGid = HulpRekJrGid)
  	INNER JOIN tabDagboek ON (dgbGid = jpDgbGid)
  where   BtwRubriekAangifte = @CurrentRubr and
          JrBoekDatum between @VanDatum and @TotDatum and
         ( (@VoorlDef=0 and IsBoekGangDefinitief<>0) or
           (@VoorlDef=1 and IsBoekGangDefinitief =0) or
           (@VoorlDef=2)
         ) and DagBoeksoort <> 5
  group by BtwRubriekAangifte
  order by BtwRubriekAangifte;

    case @CurrentRubr
    when 1 then
     set @Oba1aOmzJP	 = Floor(IsNull(-@BedragExcl,0));
     set @Oba1aOmzBelJP  = Floor(IsNull(-@BtwBedrag,0));
    when 2 then
     set @Oba1bOmzJP	 = Floor(IsNull(-@BedragExcl,0));
     set @Oba1bOmzBelJP  = Floor(IsNull(-@BtwBedrag,0));
    when 3 then
     set @Oba1cOmzJP     = Floor(IsNull(-@BedragExcl,0));
     set @Oba1cOmzBelJP  = Floor(IsNull(-@BtwBedrag,0));
    when 11 then
     set @Oba1dOmzJP     = Floor(IsNull(-@BedragExcl,0));
     set @Oba1dOmzBelJP  = Floor(IsNull(-@BtwBedrag,0));
    when 4 then
     set @Oba1eOmzJP     = Floor(IsNull(-@BedragExcl,0));
    when 5 then
     set @Oba2aOmzJP     = Floor(IsNull(@BedragExcl,0));
     set @Oba2aOmzBelJP  = Floor(IsNull(@BtwBedragAangifte,0));
     set @d2aBtwJP	 = Floor(IsNull(@BtwBedrag,0));
    when 6 then
     set @Oba3aOmzJP     = Floor(IsNull(-@BedragExcl,0));
    when 7 then
     set @Oba3bOmzJP     = Floor(IsNull(-@BedragExcl,0));
    when 8 then
     set @Oba3cOmzJP     = Floor(IsNull(-@BedragExcl,0));
    when 9 then
     set @Oba4aOmzJP     = Floor(IsNull(@BedragExcl,0));
     set @Oba4aOmzBelJP  = Floor(IsNull(@BtwBedragAangifte,0));
     set @d4aBtwJP	 = Floor(IsNull(@BtwBedrag,0));
    when 10 then
     set @Oba4bOmzJP     = Floor(IsNull(@BedragExcl,0));
     set @Oba4bOmzBelJP  = Floor(IsNull(@BtwBedragAangifte,0));
     set @d4bBtwJP	 = Floor(IsNull(@BtwBedrag,0));
    when 20 then
     set @Oba5bOmzBelJP  = round(IsNull(@BtwBedrag,0)+0.49,0);
    end case;

    set @Oba5aOmzBelJP = IsNull(@Oba1aOmzBelJP + @Oba1bOmzBelJP + @Oba1cOmzBelJP + @Oba1dOmzBelJP + @Oba2aOmzBelJP + @Oba4aOmzBelJP + @Oba4bOmzBelJP,0);
    set @Oba5bOmzBelJP = IsNull(@Oba5bOmzBelJP  + @Oba2aOmzBelJP + @Oba4aOmzBelJP + @Oba4bOmzBelJP + @d2aBtwJP   + @d4aBtwJP   + @d4bBtwJP,0);
    set @Oba5cOmzBelJP = IsNull(@Oba5aOmzBelJP - @Oba5bOmzBelJP,0);
  //  @Oba5dOmzBelJP
  //  @Oba5eOmzBelJP
  //  @Oba5fOmzBelJP
    set @Oba5gOmzBelJP = @Oba5cOmzBelJP;
  //  @Oba6aOmzBelJP
  //  @Oba6bOmzBelJP

   // Deze variabelen resetten
    set @BtwRubr 	   = 0;
    set @BedragIncl	   = 0;
    set @BtwBedrag	   = 0;
    set @BedragExcl	   = 0;
    set @BtwBedragAangifte = 0;

    set @iloop = @iloop + 1;
  end loop;

  SELECT
    /* Aangifte gegevens volgens Journaal */
    @Oba1aOmzJP 	JP_Oba1aOmz,
    @Oba1aOmzBelJP 	JP_Oba1aOmzBel,
    @Oba1bOmzJP 	JP_Oba1bOmz,
    @Oba1bOmzBelJP 	JP_Oba1bOmzBel,
    @Oba1cOmzJP 	JP_Oba1cOmz,
    @Oba1cOmzBelJP 	JP_Oba1cOmzBel,
    @Oba1dOmzJP 	JP_Oba1dOmz,
    @Oba1dOmzBelJP 	JP_Oba1dOmzBel,
    @Oba1eOmzJP 	JP_Oba1eOmz,
    @Oba2aOmzJP 	JP_Oba2aOmz,
    @Oba2aOmzBelJP 	JP_Oba2aOmzBel,
    @Oba3aOmzJP 	JP_Oba3aOmz,
    @Oba3bOmzJP 	JP_Oba3bOmz,
    @Oba3cOmzJP 	JP_Oba3cOmz,
    @Oba4aOmzJP 	JP_Oba4aOmz,
    @Oba4aOmzBelJP 	JP_Oba4aOmzBel,
    @Oba4bOmzJP 	JP_Oba4bOmz,
    @Oba4bOmzBelJP 	JP_Oba4bOmzBel,
    @Oba5aOmzBelJP 	JP_Oba5aOmzBel,
    @Oba5bOmzBelJP 	JP_Oba5bOmzBel,
    @Oba5cOmzBelJP 	JP_Oba5cOmzBel,
    @Oba5dOmzBelJP 	JP_Oba5dOmzBel,
    @Oba5eOmzBelJP 	JP_Oba5eOmzBel,
    @Oba5fOmzBelJP 	JP_Oba5fOmzBel,
    @Oba5gOmzBelJP 	JP_Oba5gOmzBel,
    (IF JP_Oba5gOmzBel > 0 THEN  JP_Oba5gOmzBel       ELSE 0 ENDIF) JP_Oba5gTeBetalen,
    (IF JP_Oba5gOmzBel < 0 THEN (JP_Oba5gOmzBel * -1) ELSE 0 ENDIF) JP_Oba5gTerugTeVragen,
    @Oba6aOmzBelJP 	JP_Oba6aOmzBel,
    @Oba6bOmzBelJP 	JP_Oba6bOmzBel,

    /* Reeds aangegeven volgens tabObAangifte */
    IsNull(Sum(Oba1aOmz),0) 	AGG_Oba1aOmz,
    IsNull(Sum(Oba1aOmzBel),0) 	AGG_Oba1aOmzBel,
    IsNull(Sum(Oba1bOmz),0)	AGG_Oba1bOmz,
    IsNull(Sum(Oba1bOmzBel),0)	AGG_Oba1bOmzBel,
    IsNull(Sum(Oba1cOmz),0) 	AGG_Oba1cOmz,
    IsNull(Sum(Oba1cOmzBel),0) 	AGG_Oba1cOmzBel,
    IsNull(Sum(Oba1dOmz),0) 	AGG_Oba1dOmz,
    IsNull(Sum(Oba1dOmzBel),0) 	AGG_Oba1dOmzBel,
    IsNull(Sum(Oba1eOmz),0)	AGG_Oba1eOmz,
    IsNull(Sum(Oba2aOmz),0)	AGG_Oba2aOmz,
    IsNull(Sum(Oba2aOmzBel),0)	AGG_Oba2aOmzBel,
    IsNull(Sum(Oba3aOmz),0)	AGG_Oba3aOmz,
    IsNull(Sum(Oba3bOmz),0)	AGG_Oba3bOmz,
    IsNull(Sum(Oba3cOmz),0)	AGG_Oba3cOmz,
    IsNull(Sum(Oba4aOmz),0)	AGG_Oba4aOmz,
    IsNull(Sum(Oba4aOmzBel),0)	AGG_Oba4aOmzBel,
    IsNull(Sum(Oba4bOmz),0)	AGG_Oba4bOmz,
    IsNull(Sum(Oba4bOmzBel),0)	AGG_Oba4bOmzBel,
    IsNull(Sum(Oba5aOmzBel),0)	AGG_Oba5aOmzBel,
    IsNull(Sum(Oba5bOmzBel),0)	AGG_Oba5bOmzBel,
    IsNull(Sum(Oba5cOmzBel),0)	AGG_Oba5cOmzBel,
    IsNull(Sum(Oba5dOmzBel),0)	AGG_Oba5dOmzBel,
    IsNull(Sum(Oba5eOmzBel),0)	AGG_Oba5eOmzBel,
    IsNull(Sum(Oba5fOmzBel),0)	AGG_Oba5fOmzBel,
    IsNull(Sum(Oba5gOmzBel),0)	AGG_Oba5gOmzBel,
    (IF AGG_Oba5gOmzBel > 0 THEN  AGG_Oba5gOmzBel       ELSE 0 ENDIF) AGG_Oba5gTeBetalen,
    (IF AGG_Oba5gOmzBel < 0 THEN (AGG_Oba5gOmzBel * -1) ELSE 0 ENDIF) AGG_Oba5gTerugTeVragen,
    IsNull(Sum(Oba6aOmzBel),0)	AGG_Oba6aOmzBel,
    IsNull(Sum(Oba6bOmzBel),0)	AGG_Oba6bOmzBel,

    /* Nog aan te geven, Journaal minus Reeds aangegeven*/
    IsNull(JP_Oba1aOmz,0)     - AGG_Oba1aOmz	ATG_Oba1aOmz,
    IsNull(JP_Oba1aOmzBel,0)  - AGG_Oba1aOmzBel	ATG_Oba1aOmzBel,
    IsNull(JP_Oba1bOmz,0)     - AGG_Oba1bOmz	ATG_Oba1bOmz,
    IsNull(JP_Oba1bOmzBel,0)  - AGG_Oba1bOmzBel	ATG_Oba1bOmzBel,
    IsNull(JP_Oba1cOmz,0)     - AGG_Oba1cOmz	ATG_Oba1cOmz,
    IsNull(JP_Oba1cOmzBel,0)  - AGG_Oba1cOmzBel	ATG_Oba1cOmzBel,
    IsNull(JP_Oba1dOmz,0)     - AGG_Oba1dOmz	ATG_Oba1dOmz,
    IsNull(JP_Oba1dOmzBel,0)  - AGG_Oba1dOmzBel	ATG_Oba1dOmzBel,
    IsNull(JP_Oba1eOmz,0)     - AGG_Oba1eOmz	ATG_Oba1eOmz,
    IsNull(JP_Oba2aOmz,0)     - AGG_Oba2aOmz	ATG_Oba2aOmz,
    IsNull(JP_Oba2aOmzBel,0)  - AGG_Oba2aOmzBel	ATG_Oba2aOmzBel,
    IsNull(JP_Oba3aOmz,0)     - AGG_Oba3aOmz	ATG_Oba3aOmz,
    IsNull(JP_Oba3bOmz,0)     - AGG_Oba3bOmz	ATG_Oba3bOmz,
    IsNull(JP_Oba3cOmz,0)     - AGG_Oba3cOmz	ATG_Oba3cOmz,
    IsNull(JP_Oba4aOmz,0)     - AGG_Oba4aOmz	ATG_Oba4aOmz,
    IsNull(JP_Oba4aOmzBel,0)  - AGG_Oba4aOmzBel	ATG_Oba4aOmzBel,
    IsNull(JP_Oba4bOmz,0)     - AGG_Oba4bOmz	ATG_Oba4bOmz,
    IsNull(JP_Oba4bOmzBel,0)  - AGG_Oba4bOmzBel	ATG_Oba4bOmzBel,
    IsNull(JP_Oba5aOmzBel,0)  - AGG_Oba5aOmzBel	ATG_Oba5aOmzBel,
    IsNull(JP_Oba5bOmzBel,0)  - AGG_Oba5bOmzBel	ATG_Oba5bOmzBel,
    IsNull(JP_Oba5cOmzBel,0)  - AGG_Oba5cOmzBel	ATG_Oba5cOmzBel,
    IsNull(JP_Oba5dOmzBel,0)  - AGG_Oba5dOmzBel	ATG_Oba5dOmzBel,
    IsNull(JP_Oba5eOmzBel,0)  - AGG_Oba5eOmzBel	ATG_Oba5eOmzBel,
    IsNull(JP_Oba5fOmzBel,0)  - AGG_Oba5fOmzBel	ATG_Oba5fOmzBel,
    IsNull(JP_Oba5gOmzBel,0)  - AGG_Oba5gOmzBel ATG_Oba5gOmzBel,
    (IF ATG_Oba5gOmzBel > 0 THEN ATG_Oba5gOmzBel        ELSE 0 ENDIF) ATG_Oba5gTeBetalen,
    (IF ATG_Oba5gOmzBel < 0 THEN (ATG_Oba5gOmzBel * -1) ELSE 0 ENDIF) ATG_Oba5gTerugTeVragen,
    IsNull(JP_Oba6aOmzBel,0)  - AGG_Oba6aOmzBel	ATG_Oba6aOmzBel,
    IsNull(JP_Oba6bOmzBel,0)  - AGG_Oba6bOmzBel	ATG_Oba6bOmzBel
  FROM
    tabObAangifte
  WHERE
    ((ObaTijdVakDatumVan >= @VanDatum) AND (ObaTijdVakDatumTot <= @TotDatum));

  //call TraceEind(@@ErrorTextProcedure);

end;
// call BtwAangifteAnalyse('2004-01-01','2004-12-31',2);


create or replace procedure BtwAangifteExclBoekjaar(in @VanDatum date, in @TotDatum date, in @VoorlDef smallint) //0=Definitief, 1=Voorlopig, 2=Voorlopig en definitief
begin
  declare @EuroValNummer integer;

  set @@ErrorTextProcedure = 'BtwAangifteExclBoekjaar > @VanDatum = '+string(@VanDatum)+', @TotDatum = '+string(@TotDatum)+', @VoorlDef = '+string(@VoorlDef);
  //call TraceBegin(@@ErrorTextProcedure);
  select  ValNummer  into @EuroValNummer from tabValuta where IsEuro <> 0;
  if @EuroValNummer is null then
    set @EuroValNummer = @@BasisValutaNummer;
  end if;

  select  BtwRubriekAangifte,
          sum(if DefaultSoort in (6,7) then
                if IsCreditBoeking = 0 then
                  if @@BasisValutaNummer = @EuroValNummer then JrBasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, JrBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2) endif
                else
                  if @@BasisValutaNummer = @EuroValNummer then -JrBasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, -JrBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2) endif
                endif
              else
                if IsCreditBoeking = 0 then   //Debet
                  if @@BasisValutaNummer = @EuroValNummer then -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif) else ValutaOmrekenen(@@BasisValutaNummer, -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGID, JrPernr, 2) endif
                else
                  if @@BasisValutaNummer = @EuroValNummer then (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif) else ValutaOmrekenen(@@BasisValutaNummer, (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGID, JrPernr, 2) endif
                endif
              endif) BedragIncl,
          sum(if HulpRekIsCredit = 0 then
                if @@BasisValutaNummer = @EuroValNummer then HulpRekBasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, HulpRekBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2) endif
              else
                if @@BasisValutaNummer = @EuroValNummer then -HulpRekBasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, -HulpRekBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2) endif
              endif) BtwBedrag,
          -BtwBedrag - BedragIncl BedragExcl,
         //BtwBedragAangifte uitrekenen(rubriek 2a, 4a, 4b)
         //bedragexcl nog een keer uitrekenen om te vermenigvuldigen met BtwPercentageAangifte(per btwcode) en dan sommeren per rubriek
         //dus sum((-BtwBedrag - BedragIncl)*BtwPercentageAangifte/100)
          sum((-Isnull(if HulpRekIsCredit = 0 then
                 if @@BasisValutaNummer = @EuroValNummer then HulpRekBasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, HulpRekBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2) endif
               else
                 if @@BasisValutaNummer = @EuroValNummer then -HulpRekBasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, -HulpRekBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2) endif
               endif,0) -
               if DefaultSoort in (6,7) then
                  if IsCreditBoeking = 0 then
                    if @@BasisValutaNummer = @EuroValNummer then JrBasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, JrBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2) endif
                  else
                    if @@BasisValutaNummer = @EuroValNummer then -JrBasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, -JrBasisBedrag, @EuroValNummer, JrBjGID, JrPernr, 2) endif
                  endif
               else
                 IsNull(if IsCreditBoeking = 0 then   //Debet
                   if @@BasisValutaNummer = @EuroValNummer then -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif) else ValutaOmrekenen(@@BasisValutaNummer, -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGID, JrPernr, 2) endif
                 else
                   if @@BasisValutaNummer = @EuroValNummer then (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif) else ValutaOmrekenen(@@BasisValutaNummer, (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif), @EuroValNummer, JrBjGID, JrPernr, 2) endif
                 endif,0)
               endif)*(BtwPercentageAangifte/100)) BtwBedragAangifte

  FROM tabJournaalRegel
  INNER JOIN tabRekeningschema ON (JrRksGid=RksGid)
  inner join (tabHulpRekening inner join tabBtw on BtwCode = HulpRekBtwCode) ON (JrGid = HulpRekJrGid)
  INNER JOIN tabDagboek ON (DgbCode = JrDgbCode)
  where  JrBoekDatum between @VanDatum and @TotDatum and
         ( (@VoorlDef=0 and (RegelNummer is not null)) or
           (@VoorlDef=1 and (RegelNummer is null)) or
           (@VoorlDef=2)
         ) and DagBoeksoort <> 5

  group by BtwRubriekAangifte
  order by BtwRubriekAangifte;

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BtwBerekenen (in @BtwCode integer, in @ErUitHalen smallint, inout @BedragInclBtw numeric(15,2), inout @BtwBedrag numeric(15,2))
begin
  declare @Percentage numeric(6,2);

  set @@ErrorTextProcedure = 'BtwBerekenen > @BtwCode='+string(@BtwCode)+', @ErUitHalen='+string(@ErUitHalen)+', @BedragInclBtw='+string(@BedragInclBtw);
  //call TraceBegin(@@ErrorTextProcedure);

  select BtwPercentage into @Percentage from tabBtw where BtwCode = @BtwCode;

  if @ErUitHalen = 1 then
    set @BtwBedrag  = @BedragInclBtw - (@BedragInclBtw / Round(1+(@Percentage/100),4));
  else
    set @BtwBedrag  = (@BedragInclBtw * Round(1+(@Percentage/100),4)) - @BedragInclBtw;
    set @BedragInclBtw = @BedragInclBtw * Round(1+(@Percentage/100),4);
  end if;

  set @@ErrorTextProcedure = 'BtwBerekenen > @BedragInclBtw='+string(@BedragInclBtw)+', @BtwBedrag='+string(@BtwBedrag);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure BtwSoort(in @BtwCode integer, inout @BtwSoort smallint)
begin

  set @@ErrorTextProcedure = 'BtwSoort > @BtwCode='+string(@BtwCode);
  //call TraceBegin(@@ErrorTextProcedure);

  select BtwSoort into @BtwSoort from tabBtw where BtwCode=@BtwCode;

  set @@ErrorTextProcedure = 'BtwSoort > @BtwSoort='+string(@BtwSoort);
  //call TraceBegin(@@ErrorTextProcedure);

end;


create or replace procedure BudgetBedragPeriode(in @BjGid integer, in @VanPerNr integer, in @TotPerNr integer, in @BudgetCode integer, in @JaarBudget double)
begin
  set @@ErrorTextProcedure = 'BudgetBedragPeriode > @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @BudgetCode='+string(@BudgetCode)+', @JaarBudget='+string(@JaarBudget);
  //call TraceBegin(@@ErrorTextProcedure);

  set @@ErrorTextProcedure = 'BudgetBedragPeriode';
  //call TraceEind(@@ErrorTextProcedure);

  select BudPernr,
        (@JaarBudget*BudPerPercentage/100),
         cast(IsNull(BudPerPercentage,0) as numeric(5,2))
  from   tabBudgetCodePeriode
  where  BudPerBjGid=@BjGid and BudPerBudgetCode=@BudgetCode and (BudPerNr between @VanPerNr and @TotPerNr);


end;


create or replace procedure BudgetEditNormBalOnderliggendBudget(in @BjGid integer, in @PerNr integer, in @IsMaxPeriode smallint, in @RubParSub nchar(5), out @BudgetBedrag numeric(15,2))
begin
  declare local temporary table tmpBud (
    tmpRubParSub    nchar(5),
    tmpBudgetGid    integer,  // Budget van de balanscode
    tmpRksOok       smallint  // 0: Gebruik NIET de budgetten van de rekeningen van deze balanscode; 1: Gebruik de budgetten van de rekeningen in deze balanscode
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'BudgetEditNormBalOnderliggendBudget > @BjGid='+string(@BjGid)+', @PerNr='+string(@PerNr)+', @IsMaxPeriode='+string(@IsMaxPeriode)+', @RubParSub='+@RubParSub;
  //call TraceBegin(@@ErrorTextProcedure);

  // Zet alle te gebruiken balanscodes in de tussentabel
  insert into tmpBud(tmpRubParSub, tmpBudgetGid, tmpRksOok)
  select RubParSub, BudgetGid, if BudBlGid is null then 1 else 0 endif
  from   tabBalanscodeDetail
         left outer join tabBudget on (RubParSub <> @RubParSub and BudBlGid = BlGid and BudBjGid = @BjGid)
  where DetailBlCode = 0 and RubParSub like @RubParSub + '%';

  // Geef aan dat rekeningen op een ondieper niveau i.i.g. niet gebruikt kunnen worden als ze een stapje dieper ook gebruikt mogen worden
  update tmpBud buiten
  set    tmpRksOok = 0
  where exists( select 1 from tmpBud binnen where buiten.tmpRubParSub like binnen.tmpRubParSub +'%' and binnen.tmpRksOok = 0);

  // Bereken het totale budgetbedrag voor het opgegeven budget (van alle rekeningen dan wel balanscodes)
  select
  sum((if    BudMetVerdeling = 1 then
       if @IsMaxPeriode = 1 then
         /* Laatste periode, dus Jaarbedrag minus alle andere periodes */
         (select   (BinnenBudget.JaarBudget - sum(round(BinnenBudget.JaarBudget / 100 * Bud_PercAfronden(BudPerPercentage),2)))
          from     tabBudget BinnenBudget
                   inner join tabBudgetCodePeriode on (BudPerBudgetCode = BinnenBudget.BudBudgetCode and BudPerBjGid  = @BjGid and BudPerNr <> @PerNr)
          where    BinnenBudget.BudgetGid = buitenBudget.BudgetGid
          group by BinnenBudget.JaarBudget
         )
       else
         /* Niet de laatste periode, dus gewoon voor die periode berekenen */
         (select round(BinnenBudget.JaarBudget / 100 * Bud_PercAfronden(BudPerPercentage),2)
          from   tabBudget BinnenBudget
                 inner join tabBudgetCodePeriode on (BudPerBudgetCode = BinnenBudget.BudBudgetCode and BudPerBjGid  = @BjGid and BudPerNr = @PerNr)
          where  BinnenBudget.BudgetGid = buitenBudget.BudgetGid
         )
       endif
      else
        /* Periodebudget, dus gewoon die ene periode pakken */
       (select BudBedrag
        from   tabBudgetBedrag
        where     (BudBedrBudgetGid = BuitenBudget.BudgetGid)
              and (BudBedrBjGID = @BjGid)
              and (BudBedrPerNr = @PerNr)
       )
      endif
      /* En converteer eventueel naar de juiste valuta */
      / if tmpBudgetGid is not null or RksValNummer = @@BasisValutaNummer then 1 else KoersTovBasisValutaDouble( @BjGid, @PerNr, RksValNummer) endif
     )  *
     /* Even opletten dat we alle budgetten altijd aan de debetzijde relateren (Dus eventueele creditbudgetten negativeren) */
     (if (tmpBudgetGid is not null) then 1 else (if DefaultBoekZijde = 1 or DefaultSoort = 7 then -1 else 1 endif) endif) /* Boekzijde=Credit OF het is een crediteur, dan credit, anders debet */
    ) PeriodeBedrag

  into @BudgetBedrag
  from tmpBud buiten
       left outer join tabRekeningschema on (RksInvoer like tmpRubParSub+'%'
                                             and tmpRksOok = 1
                                             and not exists(select 1 from tmpBud Binnen where RksInvoer like binnen.tmpRubParSub + '%' and length(binnen.tmpRubParSub) > length(buiten.tmpRubParSub))
                                            )
       left outer join tabBudget buitenBudget on (if    (tmpBudgetGid is null and BudRksGid = RksGid)
                                                     or (tmpBudgetGid is not null and BudgetGid = tmpBudgetGid) then 1 else 0 endif = 1
                                                  and (BudBjGid = @BjGid)
                                                 )
  where BudgetGid is not null;

  set @@ErrorTextProcedure = 'BudgetEditNormBalOnderliggendBudget > @BudgetBedrag='+string(@BudgetBedrag);
  //call TraceEind(@@ErrorTextProcedure);



end;


//----------- Geef Periode, Percentage, budget, voorlopig saldo debet, voorlopig saldo credit,
//            voorlopig saldo, definitief saldo debet, definitief saldo credit, definitief saldo
//            terug van een balanscode
create or replace procedure BudgetPerBalanscode (in @SoortBudget smallint, in @BjGid integer, in @VanPerNr integer, in @TotPerNr integer,
                                                 in @BudgetCode integer, in @JaarBudget numeric(15,2), in @BlGid integer, in @BlCode integer,
                                                 in @Rubriek nchar(3), in @Paragraaf nchar(3), in @SubParagraaf nchar(3), in @ZoekCode smallint)
begin

  //@SoortBudget = 0 Percentage
  //               1 CumPercentage
  //               2 Bedrag
  //call TraceBegin('BudgetPerBalanscode(@SoortBudget='+string(@SoortBudget)+', @BjGid='+string(@BjGid)+', @JaarBudget='+string(@JaarBudget)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @BudgetCode='+string(@BudgetCode)+', @ZoekCode='+string(@ZoekCode)+')');

  //call TraceEind('BudgetPerBalanscode');

  select   PerNr,
           case @SoortBudget
             when 0 then
               BudPerPercentage
             when 1 then
               Bud_CumPercentage(@BjGid, @VanPerNr, PerNr, @BudgetCode)
             when 2 then
               0
           end Percentage,
           case @SoortBudget
             when 0 then
               @JaarBudget * Bud_PercAfronden(BudPerPercentage)/100
             when 1 then
               @JaarBudget * Bud_PercAfronden(BudPerPercentage)/100
             when 2 then
               BudBedrag
           end BudgetBedrag,
           case @ZoekCode
             when 1 then  // Voorlopig Debet
                Bud_BlSaldoVoorlopig(@BjGid, PerNr, 1, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)
             when 2 then  // Voorlopig Credit
               -Bud_BlSaldoVoorlopig(@BjGid, PerNr, 0, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)
             when 3 then  // Voorlopig Saldo
                Bud_BlSaldoVoorlopig(@BjGid, PerNr, 1, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf) - Bud_BlSaldoVoorlopig(@BjGid, PerNr, 0, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)
             when 4 then  // Definitief Debet
                Bud_BlSaldoDefinitief(@BjGid, PerNr, 1, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)
             when 5 then  // Definitief Credit
               -Bud_BlSaldoDefinitief(@BjGid, PerNr, 0, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)
             when 6 then  // Definitief Saldo
                Bud_BlSaldoDefinitief(@BjGid, PerNr, 1, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf) - Bud_BlSaldoDefinitief(@BjGid, PerNr, 0, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)
             when 7 then  // Beide Debet
                Bud_BlSaldoVoorlopig(@BjGid, PerNr, 1, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf) + Bud_BlSaldoDefinitief(@BjGid, PerNr, 1, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)
             when 8 then  // Beide Credit
                Bud_BlSaldoVoorlopig(@BjGid, PerNr, 0, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf) + Bud_BlSaldoDefinitief(@BjGid, PerNr, 0, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)
             when 9 then  // Beide Saldo
               (Bud_BlSaldoVoorlopig(@BjGid, PerNr, 1, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf) + Bud_BlSaldoDefinitief(@BjGid, PerNr, 1, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf)) - (Bud_BlSaldoVoorlopig(@BjGid, PerNr, 0, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf) + Bud_BlSaldoDefinitief(@BjGid, PerNr, 0, @BlCode, @Rubriek, @Paragraaf, @SubParagraaf))
           end Saldo
  from     tabPeriode left outer join tabBudgetCodePeriode on (BudPerBjGid=@BjGid and BudPerNr=Pernr and BudPerBudgetCode=@BudgetCode)
                      left outer join (tabBudget inner join tabBudgetBedrag on (BudBedrBudgetGid = BudgetGid)) on (BudBjGid=@BjGid and BudBlGid = @BlGid and BudBedrBjGid = @BjGid and BudBedrPernr=Pernr)
  where    PerBjGid=@BjGid and PerNr between @VanPerNr and @TotPerNr
  group by PerNr, BudPerPercentage, BudBedrag
  // TG 19-06-2003: De ORDER BY ontbrak, waardoor vervelende problemen konden onstaan bij administraties (anders dan demoart/demofin).
  // hierdoor werden de budgetten (op het scherm) in de verkeerde volgorde in de memquery geinsert. de order-by verhelpt dit probleem.
  order by PerNr

end;


//$Workfile: BudgetPerKstpKstd.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

//----------- Geef Periode, Percentage, budget, voorlopig saldo debet, voorlopig saldo credit,
//            voorlopig saldo, definitief saldo debet, definitief saldo credit, definitief saldo
//            terug van een kostenplaats/-drager
if exists (select 1 from sys.sysProcedure where proc_name='BudgetPerKstpKstd') then
  drop procedure BudgetPerKstpKstd;
end if;

create procedure BudgetPerKstpKstd (in @SoortBudget smallint, in @BjGid integer, in @VanPerNr integer, in @TotPerNr integer,
                                    in @KstpKstdGid integer, in @BudgetCode integer, in @JaarBudget numeric(15,2),
                                    in @KstpGidMee smallint, in @ZoekCode smallint)
begin
  //@SoortBudget = 0 Percentage
  //               1 CumPercentage
  //               2 Bedrag

  //call TraceBegin('BudgetPerKstpKstd(@SoortBudget='+string(@SoortBudget)+', @BjGid='+string(@BjGid)+', @JaarBudget='+string(@JaarBudget)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @KstpKstdGid='+string(@KstpKstdGid)+', @BudgetCode='+string(@BudgetCode)+', @ZoekCode='+string(@ZoekCode)+')');

  //call TraceEind('BudgetPerKstpKstd');

  select   PerNr,
           case @SoortBudget
             when 0 then
               BudPerPercentage
             when 1 then
               Bud_CumPercentage(@BjGid, @VanPerNr, PerNr, @BudgetCode)
             when 2 then
               0
           end Percentage,
           case @SoortBudget
             when 0 then
               @JaarBudget * Bud_PercAfronden(BudPerPercentage)/100
             when 1 then
               @JaarBudget * Bud_PercAfronden(BudPerPercentage)/100
             when 2 then
               BudBedrag
           end BudgetBedrag,
           case @ZoekCode
             when 1 then  // Voorlopig Debet
                Bud_KstpKstdSaldoVoorlopig(@BjGid, PerNr, 1, @KstpKstdGid, @KstpGidMee)
             when 2 then  // Voorlopig Credit
               -Bud_KstpKstdSaldoVoorlopig(@BjGid, PerNr, 0, @KstpKstdGid, @KstpGidMee)
             when 3 then  // Voorlopig Saldo
                Bud_KstpKstdSaldoVoorlopig(@BjGid, PerNr, 1, @KstpKstdGid, @KstpGidMee) - Bud_KstpKstdSaldoVoorlopig(@BjGid, PerNr, 0, @KstpKstdGid, @KstpGidMee)
             when 4 then  // Definitief Debet
                Bud_KstpKstdSaldoDefinitief(@BjGid, PerNr, 1, @KstpKstdGid, @KstpGidMee)
             when 5 then  // Definitief Credit
               -Bud_KstpKstdSaldoDefinitief(@BjGid, PerNr, 0, @KstpKstdGid, @KstpGidMee)
             when 6 then  // Definitief Saldo
                Bud_KstpKstdSaldoDefinitief(@BjGid, PerNr, 1, @KstpKstdGid, @KstpGidMee) - Bud_KstpKstdSaldoDefinitief(@BjGid, PerNr, 0, @KstpKstdGid, @KstpGidMee)
             when 7 then  // Beide Debet
                Bud_KstpKstdSaldoVoorlopig(@BjGid, PerNr, 1, @KstpKstdGid, @KstpGidMee) + Bud_KstpKstdSaldoDefinitief(@BjGid, PerNr, 1, @KstpKstdGid, @KstpGidMee)
             when 8 then  // Beide Credit
              -(Bud_KstpKstdSaldoVoorlopig(@BjGid, PerNr, 0, @KstpKstdGid, @KstpGidMee) + Bud_KstpKstdSaldoDefinitief(@BjGid, PerNr, 0, @KstpKstdGid, @KstpGidMee))
             when 9 then  // Beide Saldo
               (Bud_KstpKstdSaldoVoorlopig(@BjGid, PerNr, 1, @KstpKstdGid, @KstpGidMee) + Bud_KstpKstdSaldoDefinitief(@BjGid, PerNr, 1, @KstpKstdGid, @KstpGidMee)) - (Bud_KstpKstdSaldoVoorlopig(@BjGid, PerNr, 0, @KstpKstdGid, @KstpGidMee) + Bud_KstpKstdSaldoDefinitief(@BjGid, PerNr, 0, @KstpKstdGid, @KstpGidMee))
           end Saldo
  from     tabPeriode left outer join tabBudgetCodePeriode on (BudPerBjGid  = @BjGid and BudPerNr =Pernr and BudPerBudgetCode=@BudgetCode)
                      left outer join (tabBudget inner join tabBudgetBedrag on (BudBedrBudgetGid = BudgetGid)) on (BudBjGid = @BjGid and ((BudKstpGid=@KstpKstdGid and @KstpGidMee<>0) or (BudKstdGid=@KstpKstdGid and @KstpGidMee=0)) and BudBedrBjGid = @BjGid and BudBedrPernr=Pernr)
  where    PerBjGid=@BjGid and PerNr between @VanPerNr and @TotPerNr
  group by PerNr, BudPerPercentage, BudBedrag
  // TG 19-06-2003: De ORDER BY ontbrak, waardoor vervelende problemen konden onstaan bij administraties (anders dan demoart/demofin).
  // hierdoor werden de budgetten (op het scherm) in de verkeerde volgorde in de memquery geinsert. de order-by verhelpt dit probleem.
  order by PerNr


end;


//$Workfile: BudgetPerRekening.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

//----------- Geef Periode, Percentage, budget, voorlopig saldo debet, voorlopig saldo credit,
//            voorlopig saldo, definitief saldo debet, definitief saldo credit, definitief saldo
//            terug van een rekening
if exists (select 1 from sys.sysProcedure where proc_name='BudgetPerRekening') then
  drop procedure BudgetPerRekening;
end if;

create procedure BudgetPerRekening (in @SoortBudget smallint, in @BjGid integer, in @VanPerNr integer, in @TotPerNr integer,
                                    in @RksGid integer, in @BudgetCode integer, in @JaarBudget numeric(15,2), in @ZoekCode smallint)
begin
  declare @Teken smallint;

  //@SoortBudget = 0 Percentage
  //               1 CumPercentage
  //               2 Bedrag
  //call TraceBegin('BudgetPerRekening(@SoortBudget='+string(@SoortBudget)+', @BjGid='+string(@BjGid)+', @JaarBudget='+string(@JaarBudget)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @RksGid='+string(@RksGid)+', @BudgetCode='+string(@BudgetCode)+', @ZoekCode='+string(@ZoekCode)+')');

  select (if DefaultSoort = 7 or DefaultBoekzijde = 1 then -1 else 1 endif) into @Teken from tabRekeningschema where RksGid=@RksGid;

  //call TraceEind('BudgetPerRekening(@Teken='+string(@Teken)+')');

  select   PerNr,
           case @SoortBudget
             when 0 then
               BudPerPercentage
             when 1 then
               Bud_CumPercentage(@BjGid, @VanPerNr, PerNr, @BudgetCode)
             when 2 then
               0
           end Percentage,
           case @SoortBudget
             when 0 then
               @JaarBudget * Bud_PercAfronden(BudPerPercentage)/100
             when 1 then
               @JaarBudget * Bud_PercAfronden(BudPerPercentage)/100
             when 2 then
               BudBedrag
           end BudgetBedrag,
           case @ZoekCode
             when 1 then  // Voorlopig Debet
               @Teken *  Bud_RksSaldoVoorlopig(@BjGid, PerNr, 1, @RksGid)
             when 2 then  // Voorlopig Credit
               @Teken * -Bud_RksSaldoVoorlopig(@BjGid, PerNr, 0, @RksGid)
             when 3 then  // Voorlopig Saldo
               @Teken *  Bud_RksSaldoVoorlopig(@BjGid, PerNr, 1, @RksGid) - @Teken * Bud_RksSaldoVoorlopig(@BjGid, PerNr, 0, @RksGid)
             when 4 then  // Definitief Debet
               @Teken *  Bud_RksSaldoDefinitief(@BjGid, PerNr, 1, @RksGid)
             when 5 then  // Definitief Credit
               @Teken * -Bud_RksSaldoDefinitief(@BjGid, PerNr, 0, @RksGid)
             when 6 then  // Definitief Saldo
               @Teken *  Bud_RksSaldoDefinitief(@BjGid, PerNr, 1, @RksGid) - @Teken * Bud_RksSaldoDefinitief(@BjGid, PerNr, 0, @RksGid)
             when 7 then  // Beide Debet
               @Teken *  (Bud_RksSaldoVoorlopig(@BjGid, PerNr, 1, @RksGid) + Bud_RksSaldoDefinitief(@BjGid, PerNr, 1, @RksGid))
             when 8 then  // Beide Credit
               @Teken * -(Bud_RksSaldoVoorlopig(@BjGid, PerNr, 0, @RksGid) + Bud_RksSaldoDefinitief(@BjGid, PerNr, 0, @RksGid))
             when 9 then  // Beide Saldo
               @Teken *  (Bud_RksSaldoVoorlopig(@BjGid, PerNr, 1, @RksGid) + Bud_RksSaldoDefinitief(@BjGid, PerNr, 1, @RksGid)) - @Teken * (Bud_RksSaldoVoorlopig(@BjGid, PerNr, 0, @RksGid) + Bud_RksSaldoDefinitief(@BjGid, PerNr, 0, @RksGid))
           end Saldo
  from     tabPeriode left outer join tabBudgetCodePeriode on (BudPerBjGid  = @BjGid and BudPerNr=Pernr and BudPerBudgetCode=@BudgetCode)
                      left outer join (tabBudget inner join tabBudgetBedrag on (BudBedrBudgetGid = BudgetGid)) on (BudBjGid = @BjGid and BudRksGid = @RksGid and BudBedrBjGid = @BjGid and BudBedrPernr=Pernr)
  where    PerBjGid=@BjGid and PerNr between @VanPerNr and @TotPerNr
  group by PerNr, BudPerPercentage, BudBedrag
  // TG 19-06-2003: De ORDER BY ontbrak, waardoor vervelende problemen konden onstaan bij administraties (anders dan demoart/demofin).
  // hierdoor werden de budgetten (op het scherm) in de verkeerde volgorde in de memquery geinsert. de order-by verhelpt dit probleem.
  order by PerNr


end;


//$Workfile: BudgetVerdelingenOvernemen.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

//------- bij een nieuw boekjaar, budgetverdelingen overnemen
if exists (select 1 from sys.sysProcedure where proc_name='BudgetVerdelingenOvernemen') then
  drop procedure BudgetVerdelingenOvernemen;
end if;

create procedure BudgetVerdelingenOvernemen(in @VanBjGid integer, in @NaarBjGid integer)
begin
  declare @BudgetCode integer;
  declare @VorigeBudgetCode integer;
  declare @NogTeVerdelen numeric(15,2);
  declare @MaxPer Integer;

  set @@ErrorTextProcedure = 'BudgetVerdelingenOvernemen > @VanBjGid='+string(@VanBjGid)+', @NaarBjGid='+string(@NaarBjGid);
  //call TraceBegin(@@ErrorTextProcedure);

  insert into tabBudgetCodePeriode(BudPerBjGid, BudPernr, BudPerBudgetCode, BudPerPercentage)
  select @NaarBjGid, BudPernr, BudPerBudgetCode, BudPerPercentage from tabPeriode, tabBudgetCodePeriode where BudPerBjGid = @VanBjGid and PerBjGid=@NaarBjGid and Pernr=BudPernr;

  //call Trace('Zorg dat elke indeling op 100% uitkomt (bv bij minder periodes)');
  set @VorigeBudgetCode = null;

  Select Max(PerNr) into @MaxPer from tabPeriode where PerBjGid=@NaarBjGid;

  loopje:
  loop

    //call Trace('Bepaal eerste budgetcode/volgende budgetcode met totaal <> 100%');
    //Indien nieuw boekjaar minder periodes heeft, dan hoeven we niet op 100% uit te komen -> corrigeren
    set @BudgetCode = null;

    select first BudgetCode into @BudgetCode
    from   tabBudgetCode
    where ((BudgetCode > @VorigeBudgetCode) or (@VorigeBudgetCode is null))
      and  (round(IsNull((Select sum(Bud_PercAfronden(BudPerPercentage))
                          from   tabBudgetCodePeriode
                          where (BudPerBjGid = @NaarBjGid) and (BudPerBudgetCode = BudgetCode)),0.00) ,2)<>100)
    order by budgetcode;

    //call Trace('@Budgetcode : '+String(@BudgetCode)+'    @VorigeBudgetcode : '+String(@VorigeBudgetCode ));

    Set @VorigeBudgetCode = @BudgetCode;

    if @BudgetCode is null then
      leave loopje;
    end if;


    //call Trace('Bepaal nog te verdelen poercentage van budgetcode : '+String(@BudgetCode));

    Set @NogTeVerdelen = 100 - round(IsNull((Select sum(Bud_PercAfronden(BudPerPercentage))
                                            from   tabBudgetCodePeriode
                                            where (BudPerBjGid = @NaarBjGid) and (BudPerBudgetCode = @BudgetCode)),0.00) ,2);

    //call Trace('@NogTeVerdelen : '+string(@NogTeVerdelen));

    if exists(Select 1 from tabBudgetCodePeriode where (BudPerBjGid = @NaarBjGid) and (BudPerNr=@MaxPer) and (BudPerBudgetCode = @BudgetCode)) then
      //call Trace('Update percentage bij periode '+String(@MaxPer)+' van budgetcode : '+String(@BudgetCode));
      update tabBudgetCodePeriode
      set    BudPerPercentage = BudPerPercentage + @NogTeVerdelen
      where  (BudPerBjGid = @NaarBjGid) and (BudPerBudgetCode = @BudgetCode) and (BudPernr = @MaxPer);
    else
      //call Trace('Insert percentage bij periode '+String(@MaxPer)+' van budgetcode : '+String(@BudgetCode));
      insert into tabBudgetCodePeriode(BudPerBjGid, BudPernr, BudPerBudgetCode, BudPerPercentage)
                               values (@NaarBjGid,  @MaxPer,  @BudgetCode,      @NogTeVerdelen);
    end if;

  end loop loopje;

  set @@ErrorTextProcedure = 'BudgetVerdelingenOvernemen';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: BudgetverdelingKopieren.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

//------------ Kopieer budgetverdeling naar alle overige boekjaren, waar deze verdeling niet voorkomt
if exists (select 1 from sys.sysProcedure where proc_name='BudgetverdelingKopieren') then
  drop procedure BudgetverdelingKopieren;
end if;

create procedure BudgetverdelingKopieren(in @BjGid integer, in @BudgetCode integer)
begin
  declare @HulpBjGid integer;

  //call TraceBegin('BudgetverdelingKopieren (@BjGid='+string(@BjGid)+', @BudgetCode='+string(@BudgetCode)+')');

  loopje:
  loop
    //call Trace('Zoek het eerste boekjaar op dat de opgegeven budgetcode nog niet als verdeling heeft');
    set @HulpBjGid = null;
    select first BjGid into @HulpBjGid from tabBoekjaar where BjGid not in (select BudPerBjGid from tabBudgetCodePeriode where BudPerBudgetCode = @BudgetCode);
    if @HulpBjGid is null then
      leave loopje;
    end if;

    //call Trace('Kopieer nu de verdeling naar het hiervoor gevonden boekjaar');
    insert into tabBudgetCodePeriode (BudPerBjGid, BudPerNr, BudPerBudgetCode, BudPerPercentage)
    select @HulpBjGid, BudPerNr, BudPerBudgetCode, BudPerPercentage
    from   tabBudgetCodePeriode
    where  BudPerBjGid = @BjGid and BudPerBudgetCode = @BudgetCode and BudPernr in (select Pernr from tabPeriode where PerBjGid = @HulpBjGid);

    //call Trace('Als periode-indeling niet overeenkomt kan het zijn dat er geen perioden zijn toegevoegd, dan in ieder geval 1 aanmaken');
    if not exists (select 1 from tabBudgetCodePeriode where  BudPerBjGid = @HulpBjGid and BudPerBudgetCode = @BudgetCode) then
      insert into tabBudgetCodePeriode (BudPerBjGid, BudPerNr, BudPerBudgetCode, BudPerPercentage)
      select @HulpBjGid, (select max(Pernr) from tabPeriode where PerBjGid = @HulpBjGid), @BudgetCode, 100
    end if;

    //call Trace('Update percentage bij hoogste periode');
    update tabBudgetCodePeriode set BudPerPercentage = BudPerPercentage + (100 - (select round(sum(Bud_PercAfronden(BudPerPercentage)),2) from tabBudgetCodePeriode where BudPerBjGid = @HulpBjGid and BudPerBudgetCode = @BudgetCode))
    where  BudPerBjGid = @HulpBjGid and BudPerBudgetCode = @BudgetCode and BudPernr = (select max(BudPernr) from tabBudgetCodePeriode where BudPerBjGid = @HulpBjGid and BudPerBudgetCode = @BudgetCode);

  end loop;

  //call TraceEind('BudgetverdelingKopieren');

end;


//----------  Geef het definitieve debet of credit saldo van de grootboekrekening en
//            die horen bij een bepaalde balans/rubriek/paragraaf/subparagraaf van een
//            bepaalde periode terug in de defaultvaluta
create or replace function Bud_BlSaldoDefinitief(in @BjGid integer, in @PerNr integer, in @DebetSaldo smallint, in @BlCode integer, in @RubCode nchar(3), in @ParCode nchar(3), in @SubCode nchar(3))
returns numeric(15,2)
begin
  declare @Saldo numeric(15,2);

  //call TraceBegin ('Bud_BlSaldoDefinitief (@BjGid='+string(@BjGid)+', @Pernr='+string(@Pernr)+'@DebetSaldo='+string(@DebetSaldo)+', @BlCode='+string(@BlCode)+', @RubCode='+string(@RubCode)+', @ParCode='+string(@ParCode)+', @SubCode='+string(@SubCode)+ ')');

  if @BlCode <> 0 then // variabele balans
    if @DebetSaldo = 0 then // creditsaldo
      if @ParCode = '' then // rubriek
        select IsNull(sum(SaldoCreditBasisDefinitief),0) into @Saldo
        from tabrekeningsaldo, tabbalanscoderekening
        where BlRksGid = RekSaldoRksGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr
              and BlRekBlGid in (select BlGid from tabbalanscodedetail where DetailBlCode=@BlCode
                                 and Rubriek=@RubCode);
      else
        if @SubCode = '' then // paragraaf
          select IsNull(sum(SaldoCreditBasisDefinitief),0) into @Saldo
          from tabrekeningsaldo, tabbalanscoderekening
          where BlRksGid = RekSaldoRksGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr
                and BlRekBlGid in (select BlGid from tabbalanscodedetail where DetailBlCode=@BlCode
                                   and Rubriek=@RubCode and Paragraaf=@ParCode);
        else // subparagraaf
          select IsNull(sum(SaldoCreditBasisDefinitief),0) into @Saldo
          from tabrekeningsaldo, tabbalanscoderekening
          where BlRksGid = RekSaldoRksGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr
                and BlRekBlGid in (select BlGid from tabbalanscodedetail where DetailBlCode=@BlCode
                                   and Rubriek=@RubCode and Paragraaf=@ParCode and SubParagraaf=@SubCode);
        end if;
      end if;
    else // debetsaldo
      if @ParCode = '' then // rubriek
        select IsNull(sum(SaldoDebetBasisDefinitief),0) into @Saldo
        from tabrekeningsaldo, tabbalanscoderekening
        where BlRksGid = RekSaldoRksGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr
              and BlRekBlGid in (select BlGid from tabbalanscodedetail where DetailBlCode=@BlCode
                                 and Rubriek=@RubCode);
      else
        if @SubCode = '' then // paragraaf
          select IsNull(sum(SaldoDebetBasisDefinitief),0) into @Saldo
          from tabrekeningsaldo, tabbalanscoderekening
          where BlRksGid = RekSaldoRksGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr
                and BlRekBlGid in (select BlGid from tabbalanscodedetail where DetailBlCode=@BlCode
                                   and Rubriek=@RubCode and Paragraaf=@ParCode);
        else // subparagraaf
          select IsNull(sum(SaldoDebetBasisDefinitief),0) into @Saldo
          from tabrekeningsaldo, tabbalanscoderekening
          where BlRksGid = RekSaldoRksGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr
                and BlRekBlGid in (select BlGid from tabbalanscodedetail where DetailBlCode=@BlCode
                                   and Rubriek=@RubCode and Paragraaf=@ParCode and SubParagraaf=@SubCode);
        end if;
      end if;
    end if;
  else // normale balans
    if @DebetSaldo = 0 then // creditsaldo
      if @ParCode = '' then // rubriek
        select IsNull(sum(SaldoCreditBasisDefinitief),0) into @Saldo
        from tabrekeningsaldo
        where RekSaldoPerNr = @PerNr and RekSaldoBjGid = @BjGid and RekSaldoRksGid in
            (Select RksGid from tabRekeningschema where RksInvoer like (@RubCode + '%'));
      else
        if @SubCode = '' then // paragraaf
          select IsNull(sum(SaldoCreditBasisDefinitief),0) into @Saldo
          from tabrekeningsaldo
          where RekSaldoPerNr = @PerNr and RekSaldoBjGid = @BjGid and RekSaldoRksGid in
            (Select RksGid from tabRekeningschema where RksInvoer like (@ParCode + '%'));
        else // subparagraaf
          select IsNull(sum(SaldoCreditBasisDefinitief),0) into @Saldo
          from tabrekeningsaldo
          where RekSaldoPerNr = @PerNr and RekSaldoBjGid = @BjGid and RekSaldoRksGid in
            (Select RksGid from tabRekeningschema where RksInvoer like (@ParCode + @SubCode + '%'));
        end if;
      end if;
    else // debetsaldo
      if @ParCode = '' then // rubriek
        select IsNull(sum(SaldoDebetBasisDefinitief),0) into @Saldo
        from tabrekeningsaldo
        where RekSaldoPerNr = @PerNr and RekSaldoBjGid = @BjGid and RekSaldoRksGid in
            (Select RksGid from tabRekeningschema where RksInvoer like (@RubCode + '%'));
      else
        if @SubCode = '' then // paragraaf
          select IsNull(sum(SaldoDebetBasisDefinitief),0) into @Saldo
          from tabrekeningsaldo
          where RekSaldoPerNr = @PerNr and RekSaldoBjGid = @BjGid and RekSaldoRksGid in
            (Select RksGid from tabRekeningschema where RksInvoer like (@ParCode + '%'));
        else // subparagraaf
          select IsNull(sum(SaldoDebetBasisDefinitief),0) into @Saldo
          from tabrekeningsaldo
          where RekSaldoPerNr = @PerNr and RekSaldoBjGid = @BjGid and RekSaldoRksGid in
            (Select RksGid from tabRekeningschema where RksInvoer like (@ParCode + @SubCode + '%'));
        end if;
      end if;
    end if;
  end if;

  //call TraceEind ('Bud_BlSaldoDefinitief ------> @Saldo='+string(@Saldo));
  return (@Saldo);

end;


//----------  Geef het voorlopige debet of credit saldo van de grootboekrekening en
