end;


//$Workfile: Bud_CumPercentage.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

//----------- Geef het cummulatieve percentage terug van een budgetcode van een periode-range
if exists (select 1 from sys.sysProcedure where proc_name='Bud_CumPercentage') then
  drop function Bud_CumPercentage;
end if;

create function Bud_CumPercentage(in @BjGid integer, in @VanPerNr integer, in @TotPerNr integer, in @BudgetCode integer)
returns double
begin
  declare @cum double;

  //call TraceBegin ('Bud_CumPercentage (@BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @BudgetCode='+string(@BudgetCode)+')');

  select sum(Bud_PercAfronden(BudPerPercentage)) into @cum
    from tabBudgetCodePeriode
    where BudPerBjGid=@BjGid and (BudPerNr between @VanPerNr and @TotPerNr) and BudPerBudgetCode=@BudgetCode;

  //call TraceEind ('Bud_CumPercentage ------> @cum='+string(@cum));
  return (@cum)

end;


//$Workfile: Bud_KstpKstdSaldoDefinitief.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:53 $'

//----------  Geef het definitieve debet of credit saldo van een grootboekrekening
//            (lees kostenplaats/kostendrager) van een bepaalde periode terug in de basisvaluta
if exists (select 1 from sys.sysProcedure where proc_name='Bud_KstpKstdSaldoDefinitief') then
  drop function Bud_KstpKstdSaldoDefinitief;
end if;

create function Bud_KstpKstdSaldoDefinitief(in @BjGid integer, in @PerNr integer, in @DebetSaldo smallint,
                                            in @KstpKstdGid integer, in @KstpGidMee smallint)
returns numeric(15,2)
begin
  declare @Saldo numeric(15,2);

  //call TraceBegin ('Bud_KstpKstdSaldoDefinitief (@BjGid='+string(@BjGid)+', @Pernr='+string(@Pernr)+', @DebetSaldo='+string(@DebetSaldo)+', @KstpKstdGid='+string(@KstpKstdGid)+',@KstpGidMee='+string(@KstpGidMee)+')');

  if @KstpGidMee = 0 then
    if @DebetSaldo = 0 then
      select IsNull(sum(SaldoCreditBasisDefinitief),0) into @Saldo
      from tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksGid = RksGid)
      where RksKstdGid=@KstpKstdGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr;
    else
      select IsNull(sum(SaldoDebetBasisDefinitief),0) into @Saldo
      from tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksGid = RksGid)
      where RksKstdGid=@KstpKstdGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr;
    end if;
  else
    if @DebetSaldo = 0 then
      select IsNull(sum(SaldoCreditBasisDefinitief),0) into @Saldo
      from tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksGid = RksGid)
      where RksKstpGid=@KstpKstdGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr;
    else
      select IsNull(sum(SaldoDebetBasisDefinitief),0) into @Saldo
      from tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksGid = RksGid)
      where RksKstpGid=@KstpKstdGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr;
    end if;
  end if;

  //call TraceEind ('Bud_KstpKstdSaldoDefinitief ------> @Saldo='+string(@Saldo));
  return (@Saldo);

end;



//$Workfile: Bud_KstpKstdSaldoVoorlopig.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:53 $'

//----------  Geef het voorlopige debet of credit saldo van een grootboekrekening
//            (lees kostenplaats/kostendrager) van een bepaalde periode terug in de basisvaluta
if exists (select 1 from sys.sysProcedure where proc_name='Bud_KstpKstdSaldoVoorlopig') then
  drop function Bud_KstpKstdSaldoVoorlopig;
end if;

create function Bud_KstpKstdSaldoVoorlopig(in @BjGid integer, in @PerNr integer, in @DebetSaldo smallint,
                                           in @KstpKstdGid integer, in @KstpGidMee smallint)
returns numeric(15,2)
begin
  declare @Saldo numeric(15,2);

  //call TraceBegin ('Bud_KstpKstdSaldoVoorlopig (@BjGid='+string(@BjGid)+', @Pernr='+string(@Pernr)+'@DebetSaldo='+string(@DebetSaldo)+', @KstpKstdGid='+string(@KstpKstdGid)+',@KstpGidMee='+string(@KstpGidMee)+')');

  if @KstpGidMee = 0 then
    if @DebetSaldo = 0 then
       select IsNull(sum(SaldoCreditBasisVoorlopig),0) into @Saldo
       from tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksGid = RksGid)
       where RksKstdGid=@KstpKstdGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr;
    else
       select IsNull(sum(SaldoDebetBasisVoorlopig),0) into @Saldo
       from tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksGid = RksGid)
       where RksKstdGid=@KstpKstdGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr;
    end if;
  else
    if @DebetSaldo = 0 then
      select IsNull(sum(SaldoCreditBasisVoorlopig),0) into @Saldo
       from tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksGid = RksGid)
      where RksKstpGid=@KstpKstdGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr;
    else
      select IsNull(sum(SaldoDebetBasisVoorlopig),0) into @Saldo
       from tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksGid = RksGid)
      where RksKstpGid=@KstpKstdGid and @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr;
    end if;
  end if;

  //call TraceEind ('Bud_KstpKstdSaldoVoorlopig ------> @Saldo='+string(@Saldo));
  return (@Saldo);

end;


//$Workfile: Bud_PercAfronden.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:53 $'

//------------- Geef een percentage dat eindigt op .33, .34, .66,.67 terug als een breuk (bijv. 1/3 of 2/3)
if exists (select 1 from sys.sysProcedure where proc_name='Bud_PercAfronden') then
  drop procedure Bud_PercAfronden;
end if;

create function Bud_PercAfronden(in @percentage double)
returns double
begin

  //call TraceBegin('Bud_PercAfronden (@Percentage='+string(@Percentage)+')');

  //call TraceEind('Bud_PercAfronden');
  case round(@percentage-"truncate"(@percentage,0),2)
    when .33 then
      return "truncate"(@percentage,0)+0.33333333333333
    when .34 then
      return "truncate"(@percentage,0)+0.33333333333333
    when .66 then
      return "truncate"(@percentage,0)+0.66666666666666
    when .67 then
      return "truncate"(@percentage,0)+0.66666666666666
    else
      return @percentage
  end case


end;


create or replace function Bud_RksSaldoDefinitief(in @BjGid integer, in @PerNr integer, in @DebetSaldo smallint, in @RksGid integer)
returns numeric(15,2)
begin
  declare @Saldo        numeric(15,2);
  declare @SaldoDefault numeric(15,2);
  declare @RksValNummer integer;

  set @@ErrorTextProcedure = 'Bud_RksSaldoDefinitief > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BjGid = ' + string(@BjGid) + ', @Pernr = ' + string(@Pernr) + ', @DebetSaldo = ' + string(@DebetSaldo) + ', @RksGid = ' + string(@RksGid));

  // saldo ophalen in basisvaluta
  if @DebetSaldo = 0 then
    select IsNull((sum(SaldoCreditBasisDefinitief)),0) into @SaldoDefault
    from   tabrekeningsaldo
    where  @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr and @RksGid=RekSaldoRksGid;
  else
    select IsNull((sum(SaldoDebetBasisDefinitief)),0) into @SaldoDefault
    from   tabrekeningsaldo
    where  @BjGid=RekSaldoBjGid and @PerNr=RekSaldoPerNr and @RksGid=RekSaldoRksGid;
  end if;

  // omrekenen als nodig
  select RksValNummer into @RksValNummer from tabRekeningschema where RksGid = @RksGid;
  if @@BasisValutaNummer <> @RksValNummer then
    set @Saldo = (select ValutaOmrekenen(@@BasisValutaNummer, @SaldoDefault, @RksValNummer, @BjGid, @Pernr, 2));
  else
    set @Saldo = @SaldoDefault;
  end if;

  set @@ErrorTextProcedure = 'Bud_RksSaldoDefinitief';
  //call TraceEind (@@ErrorTextProcedure + ' > @Saldo = ' + string(@Saldo));

  return (@Saldo);
end;


