create or replace procedure CatalogusKopieren(
  in  @BronCatGid          integer,
  in  @DoelCatCode         nchar(10),
  in  @DoelCatOmschrijving nchar(40),
  out @DoelCatGid          integer)
begin
  //----- Procedure kopieert een volledige catalogus inclusief rubrieken, artikelen en teksten per taal
  //deze tijdelijke tabel houdt een lijst bij van de originele gidjes (bestaande catalogusrubrieken) en de gidjes die bij het kopieren zijn aangemaakt (nieuwe catalogusrubrieken).
  //Als de rubrieken eenmaal gekopieerd zijn kunnen de artikelen aan de hand van deze lijst onder de juiste rubrieken worden toegevoegd.
  declare local temporary table tmpCatrGidReferenties(//Voor oude/nieuwe gid
    TmpBronCatrGid integer,   //opslaan BronCatrGid van originele knoop
    TmpDoelCatrGid integer    //opslaan DoelCatrGid van kopie knoop
  ) on commit preserve rows;

  declare @TmpCatrParentGid integer;
  declare @CatrGid          integer;

  set @@ErrorTextProcedure = 'CatalogusKopieren > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BronCatGid = ' + string(@BronCatGid) + ', @DoelCatCode = ' + string(@DoelCatCode) + ', @DoelCatOmschrijving = ' + string(@DoelCatOmschrijving));

  //variabelen initialiseren
  set @DoelCatGid = null;

  //kopieren starten
  insert into tabCatalogus with auto name
  select
    @DoelCatCode         as CatCode,
    @DoelCatOmschrijving as CatOmschrijving
  from
    tabCatalogus
  where
    CatGid = @BronCatGid;

  //catalogus gekopieerd?
  if @@RowCount = 1 then
    //CatGid van nieuwe catalogus ophalen als het inserten gelukt is
    set @DoelCatGid = @@Identity;

    //rubrieken kopieren
    for @Cursor AS CURSOR_CatalogusRubriekCopyNodes CURSOR FOR
    select
      CatrGid             @CurCatrGid,
      CatrParentGid       @CurCatrParentGid,
      CatrOmschrijving    @CurCatrOmschrijving,
      CatrNiveau          @CurCatrNiveau,
      CatrCoderingRubKop  @CurCatrCoderingRubKop,
      CatrCoderingRubVoet @CurCatrCoderingRubVoet,
      CatrCoderingArt     @CurCatrCoderingArt,
      CatrAfbeelding1     @CurCatrAfbeelding1,
      CatrAfbeelding2     @CurCatrAfbeelding2,
      CatrAfbeelding3     @CurCatrAfbeelding3,
      CatrNieuwePagina    @CurCatrNieuwePagina,
      CatrUitklappen      @CurCatrUitklappen,
      CatrVolgnr          @CurCatrVolgnr
    from
      tabCatalogusRubriek
    where
     CatrCatGid = @BronCatGid
    order by
      CatrNiveau, CatrVolgnr
    for read only
    do
      //variabele resetten (wordt in cursorloop gebruikt)
      set @TmpCatrParentGid = null;

      if @CurCatrParentGid is not null then
        select TmpDoelCatrGid into @TmpCatrParentGid from tmpCatrGidReferenties where TmpBronCatrGid = @CurCatrParentGid;
      end if;

      //rubriek kopieren
      insert into tabCatalogusRubriek with auto name
      select
        @DoelCatGid             as CatrCatGid,
        @TmpCatrParentGid       as CatrParentGid,
        @CurCatrOmschrijving    as CatrOmschrijving,
        @CurCatrNiveau          as CatrNiveau,
        @CurCatrCoderingRubKop  as CatrCoderingRubKop,
        @CurCatrCoderingRubVoet as CatrCoderingRubVoet,
        @CurCatrCoderingArt     as CatrCoderingArt,
        @CurCatrAfbeelding1     as CatrAfbeelding1,
        @CurCatrAfbeelding2     as CatrAfbeelding2,
        @CurCatrAfbeelding3     as CatrAfbeelding3,
        @CurCatrNieuwePagina    as CatrNieuwePagina,
        @CurCatrUitklappen      as CatrUitklappen,
        @CurCatrVolgnr          as CatrVolgnr
      from
        Dummy;

      set @CatrGid = @@Identity;

      //kruisverwijzing onthouden
      insert into tmpCatrGidReferenties with auto name
      select
        @CurCatrGid as TmpBronCatrGid, //gidje originele rubriek
        @CatrGid    as TmpDoelCatrGid  //gidje kopierubriek
      from
        Dummy;

    end for;

    //artikelen kopieren
    insert into tabCatalogusRubriekArtikel (CataCatrGid, CataArtGid, CataVolgnr)
    select
      TmpDoelCatrGid,
      CataArtGid,
      CataVolgnr
    from
      tabCatalogusRubriekArtikel
      inner join tmpCatrGidReferenties on (CataCatrGid = TmpBronCatrGid);

    //teksten kopieren
    insert into tabCatalogusRubriekTekst (CattCatrGid, CattTaalGid, CattKoptekst, CattHoofdtekst, CattVoettekst)
    select
      TmpDoelCatrGid,
      CattTaalGid,
      CattKoptekst,
      CattHoofdtekst,
      CattVoettekst
    from
      tabCatalogusRubriekTekst
      inner join tmpCatrGidReferenties on (CattCatrGid = TmpBronCatrGid);

  end if;

  set @@ErrorTextProcedure = 'CatalogusKopieren';
  //call TraceEind(@@ErrorTextProcedure + ' > @DoelCatGid='+string(@DoelCatGid));
end;


//------------ Check of de datum van de voorraadmutatie na die van de laatste herwaardering ligt.
create or replace procedure CheckDatumVrdMutaties(in @VckGid integer,in @Datum date,out @Foutnummer integer, out @Foutmelding nchar(300))
begin
  declare @artCode nchar(20);
  declare @ArtPartijNummer nchar(20);
  declare @ArtVastDatumControleVrdMutaties integer;


  //Eerst geen foutmelding terugkijgen.
  Set @Foutnummer   = 0;
  Set @Foutmelding  = '';

  //Datum dient na de laatste herwaardering te liggen!.
  select First isnull(artCode,''),isnull(artPartijnummer,'')  into @Artcode,@ArtPartijNummer
            from tabVoorraadCorrectieKop
            inner join tabVoorraadCorrectieRegel on (VcrVckGid = VckGid)
            inner join tabArtikel on (ArtGid = VcrArtGid)
            left outer join tabArtikelPartij on (ArtPartijGid = VcrArtPartijGid)
            inner join tabprijswijzigingshistorie on pwhartgid = vcrartgid and pwhartpartijnummer = isnull(If (exists(select 1 from tabArtikel where ArtGid = VcrArtGid  and ArtIsPartijAparteKostPrijs = 0) and artpartijnummer <> '') Then '' else artpartijnummer Endif,'') and date(pwhdatum) > @Datum
            where VckGid=@VckGid;

  if (@artCode <> '') then
    set @Foutmelding  = _U('Voor een of meer artikelen is de kostprijs gewijzigd na de verwerkingsdatum van deze mutaties. Als u deze mutatie zou verwerken ontstaat een verschil tussen de grootboek- en voorraadadministratie m.b.t. de waarde van de voorraad.');

    //MR 09-sep-2008 bug #28998: En een extra stuk aan de melding
    select ArtVastDatumControleVrdMutaties into @ArtVastDatumControleVrdMutaties from tabArtikelVasteGegevens where ArtVastSoort = 2;

    Set @Foutnummer   = @ArtVastDatumControleVrdMutaties;

    if (@Foutnummer =1) then
      //Waarschuwing
      set @Foutmelding  = @Foutmelding + ' '+ _U('Wilt u deze verwerking toch voortzetten?')
    end if;
  end if;

  exception when others then resignal
end;


create or replace procedure CheckFixSpecregelLicentieZonderSpecregels(in @OrkGid integer)
begin
  //call TraceBegin('CheckFixSpecregelLicentieZonderSpecregels > @OrkGid = ' + string(@OrkGid)));

    for @RegelCursor AS CURSOR_OrderRegel CURSOR FOR
    select
      OrrGid @OrrGid,
      OrrMagGid @MagGid,
      IsNull((select ArtMagDefaultLocGid from tabArtikelMagazijn where ArtMagMagGid = OrrMagGid and ArtMagArtGid = OrrArtGid),
      (select first LocGid from tabLocatie where LocNaam='(Standaard)' and (LocMagGid = OrrMagGid))) @LocGid,
      (select VkeGid from tabVerkoopEenheid where VkeArtGid = OrrArtGid and VkeIsVoorraadEenheid = 1) @VoorraadEenheidVkeGid,
      OrrAantalBesteld @OrrAantalBesteld,
      OrrAantDecAantal @OrrAantDecAantal,
      OrrAantDecAantalVrrdEenh @OrrAantDecAantalVrrdEenh,
      OrrAantalLevering @OrrAantalLevering,
      OrrAantalLeveringVrrdEenh @OrrAantalLeveringVrrdEenh,
      OrrAantalGeleverd @OrrAantalGeleverd,
      OrrAantalGeleverdVrrdEenh @OrrAantalGeleverdVrrdEenh,
      OrrAantalGereserveerd @OrrAantalGereserveerd,
      (select IsNull(sum(OrlDezeLevering), 0.0) from tabOrderRegelLocatie where OrlOrrGid = OrrGid) @TotaalOrlDezeLevering,
      (select IsNull(sum(OrlDezeLeveringVrrdEenh), 0.0) from tabOrderRegelLocatie where OrlOrrGid = OrrGid) @TotaalOrlDezeLeveringVrrdEenh
    from tabOrderRegel
    where OrrOrkGid = @OrkGid
    and OrrRegelSoort = 2
    order by OrrRegelnr
    for read only do
    begin

      if (@TotaalOrlDezeLevering <> @OrrAantalLevering) or (@TotaalOrlDezeLeveringVrrdEenh <> @OrrAantalLeveringVrrdEenh) then
        // Aantallen kloppen niet, locatieregels verwijderen
        delete tabOrderRegelLocatie where OrlOrrGid = @OrrGid;
        // En een nieuwe toevoegen obv de orderregel
        insert into tabOrderRegelLocatie
          ( OrlOrrGid,
            OrlVkeGid,
            OrlMagGid,
            OrlLocGid,
            OrlAantDecAantal,
            OrlAantDecAantalVrrdEenh,
            OrlDezeLevering,
            OrlDezeLeveringVrrdEenh,
            OrlGeleverd,
            OrlGeleverdVrrdEenh,
            OrlAantalGereserveerd)
        values
         ( @OrrGid,
           @VoorraadEenheidVkeGid,
           @MagGid,
           @LocGid,
           @OrrAantDecAantal,
           @OrrAantDecAantalVrrdEenh,
           @OrrAantalLevering,
           @OrrAantalLeveringVrrdEenh,
           @OrrAantalGeleverd,
           @OrrAantalGeleverdVrrdEenh,
           @OrrAantalGereserveerd);
      end if;

    end;
  end for;

  //call TraceEind('CheckFixSpecregelLicentieZonderSpecregels');
end;


//------------ Check de historie van de prijswijzigingen
create or replace procedure CheckPrijswijzigingsHistorie(in @ArtGid Integer,in @Partijnummer nchar(20),in @Datum timestamp,out @Foutnummer integer, out @Foutmelding nchar(250))
begin
  declare @Aantal integer;
  //Eerst geen foutmelding terugkijgen.
  Set @Foutnummer   = 0;
  Set @Foutmelding  = '';

  set @@ErrorTextProcedure = 'CheckPrijswijzigingsHistorie > @ArtGid='+string(@ArtGid)+', @Partijnummer='+@Partijnummer+', @Datum='+string(@Datum);
  //call TraceBegin(@@ErrorTextProcedure);

  //Datum en tijd dient na de laatste verandering te liggen!.
  if exists(select 1 from tabPrijswijzigingsHistorie where pwhArtGid = @ArtGid and pwhArtPartijnummer = @Partijnummer and date(pwhDatum) > date(@Datum)) then
    Set @Foutnummer   = 1;
    Set @Foutmelding  = _U('Het is niet mogelijk de kostprijs te wijzigen, er is al een kostprijs vastgelegd op een latere datum');
  end if;

  if @Foutnummer = 0 then
    select count(*) into @Aantal from tabArtikelPartij where ArtPartijArtGid = @ArtGid;
    //Als het gaat om een artikel prijswijziging ook naar de partij (Standaard) kijken.
    if (@Partijnummer = '' and (exists(select 1 from tabArtikelPartij where ArtPartijArtGid=@Artgid and ArtPartijnummer = '(Standaard)') Or @Aantal=1)) then
      //Datum en tijd dient na de laatste verandering te liggen!.
      if exists(select 1 from tabPrijswijzigingsHistorie where pwhArtGid = @ArtGid and pwhArtPartijnummer = '(Standaard)' and date(pwhDatum) > date(@Datum)) then
        Set @Foutnummer   = 1;
        Set @Foutmelding  = _U('Het is niet mogelijk de kostprijs te wijzigen, er is al een kostprijs vastgelegd op een latere datum bij partij (Standaard)');
      end if;

      if @Foutnummer = 0 then
        if (exists(Select 1 from tabArtikelPartij Inner Join tabArtikel on ArtGid = ArtPartijArtGid and ArtIsPartijAparteKostPrijs = 1 Inner Join TabPrijswijzigingsHistorie On pwhArtGid = @ArtGid and date(pwhDatum) > date(@Datum) Where ArtPartijArtGid = @ArtGid) and @Aantal=1) then
          Set @Foutnummer   = 1;
          Set @Foutmelding  = _U('Het is niet mogelijk de kostprijs te wijzigen, er is al een kostprijs vastgelegd op een latere datum bij een partij');
        end if;
      end if;
    end if;

    if @Foutnummer = 0 then
      //In vaste gegevens artikelen kijken of we ook op datum moeten controleren
      if exists(select 1 from tabArtikelVasteGegevens where ArtVastSoort = 2 and ArtVastDatumControleVrdMutaties <> 0) then
        //Datum en tijd dient na de laatste voorraadmutatie te liggen!
        //MR 30-sep-2010: En alleen als het niet een directe levering is.
        if exists(select 1 from tabVoorraadMutatie inner join tabVoorraadMutatieLocatieSerie on (((VrdMutLocPartijNummer = @Partijnummer) or (IsNull(@Partijnummer,'') = '')) and VrdMutLocVrdMutGid = VrdMutGid) where vrdmutArtGid = @ArtGid and vrdmutDatum > Date(@Datum) and vrdMutSoort not in (11,12)) then
          Set @Foutnummer   = 2;
          Set @Foutmelding  = _U('Het is niet mogelijk de kostprijs te wijzigen, er zijn al voorraadmutaties vastgelegd op een latere datum');
        end if;
      end if;
    end if;
  end if;

  set @@ErrorTextProcedure = 'CheckPrijswijzigingsHistorie > @Foutnummer='+string(@Foutnummer);
  //call TraceEind(@@ErrorTextProcedure);
end;


//------- Controleer of tabRekeningsaldo en tabJournaalregel overeenkomen
create or replace procedure CheckRekeningsaldo(in @BjGid integer)
begin
  declare local temporary table tmpRekeningSaldo(
    RksInvoer nchar(28),
    JournaalSaldo numeric(15,2),
    Rekeningsaldo numeric(15,2),
    Verschil numeric(15,2));

  declare @IsolationLevel smallint;
  declare @RksGid integer;
  declare @RekSaldo numeric(15,2);
  declare @JournaalSaldo numeric(15,2);

  declare cursor_Rekeningschema dynamic scroll cursor for
    select RksGid from tabRekeningschema
  for read only;

  set @@ErrorTextProcedure = 'CheckRekeningsaldo > @BjGid='+string(@BjGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  open cursor_Rekeningschema;
  loopje:
  loop
    Fetch next cursor_Rekeningschema into @RksGid;
    if sqlstate = '02000' then
      leave loopje;
    end if;

    select sum((saldodebetbasisdefinitief + SaldoDebetBasisVoorlopig) - (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)) into @RekSaldo
    from   tabRekeningsaldo where RekSaldoRksGid = @RksGid and RekSaldoBjGid = @BjGid;

    select sum(if isCreditBoeking = 0 then JrBasisBedrag else -JrBasisBedrag endif) into @JournaalSaldo
    from   tabJournaalRegel where JrRksGid = @RksGid and JrBjGid = @BjGid;

    if IsNull(@RekSaldo, 0) <> IsNull(@JournaalSaldo, 0) then
      insert into tmpRekeningSaldo select RksInvoer, @JournaalSaldo, @RekSaldo, @JournaalSaldo-@RekSaldo from tabRekeningschema where RksGid=@RksGid;
    end if;

  end loop loopje;
  close cursor_Rekeningschema;

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  set @@ErrorTextProcedure = 'CheckRekeningsaldo';
  //call TraceEind(@@ErrorTextProcedure);
  select * from tmpRekeningSaldo;

end;


create or replace procedure CheckVrijeRubrieken()
result (tmpSoort smallint, tmpInfo nchar(120), tmpSqlStatement nchar(120))
begin
  declare @ArtikelBestandTekst long nvarchar;
  declare @NawBestandTekst long nvarchar;
  declare @ArtikelenTekst long nvarchar;

  declare local temporary table tmpVrijeRubrieken(
    tmpSoort smallint,    //0=velddefinitie (in tabVrijerubrieken) ontbreekt
                          //1=colum in tabVr... is niet meer aanwezig
    tmpInfo nchar(120),
    tmpSqlStatement nchar(120)) on commit preserve rows;

  set @@ErrorTextProcedure = 'CheckVrijeRubrieken > ';
  //call TraceBegin(@@ErrorTextProcedure);

  //call Trace('Nu de velden zoeken die in tabVrijeRubrieken staan, maar niet meer in tabVr...');

  set @ArtikelBestandTekst = _U('in artikelbestand');
  set @NawBestandTekst = _U('in NAW-bestand');
  set @ArtikelenTekst = _U('Artikelen');

  insert into tmpVrijeRubrieken(tmpSoort, tmpInfo, tmpSqlStatement)
  select      0,
              case VrBestandOms
                when 'ART' then        char(39)+VrLabel+char(39)+' '+ @ArtikelBestandTekst
                else           (select char(39)+VrLabel+char(39)+' '+ @NawBestandTekst +' '+ char(39)+(if FonId in ('D', 'C', 'B') then FonOms+'' else FonId+' '+FonOms endif)+char(39) from tabFileOfNaw where FonGId = VrGroepId)
              end,
             'delete tabVrijeRubrieken where VrGid = '+string(VrGid)
  from        tabVrijeRubrieken
  where       VrVeldNaam not in (select column_name from sys.syscolumn);

  //call Trace('Nu de velden zoeken die niet meer in tabVrijerubrieken staan, maar nog wel in tabVr...');
  insert into tmpVrijeRubrieken(tmpSoort, tmpInfo, tmpSqlStatement)
  select      1,
              case substr(table_name, 6, 3)
                when 'ART' then char(39)+@ArtikelenTekst+char(39)
                else           (select char(39)+(if FonId in ('D', 'C', 'B') then FonOms else FonId+' - '+FonOms endif)+char(39) from tabFileOfNaw where right('000'+string(FonGid),3) = right(table_name, 3))
              end,
             'alter table '+table_name+' drop '+column_name
  from        sys.systable inner join sys.syscolumn on (sys.syscolumn.table_id = sys.systable.table_id)
  where       (not table_name like 'tabVrijeRubrieken%')
              and (not table_name like '%_HIST')         // historietabellen mogen niet veranderd worden
              and (table_name like 'tabVr%')
              and (column_name like 'vr%veld%')
              and (column_name not in (select VrVeldNaam from tabVrijeRubrieken));

  select tmpSoort, tmpInfo, tmpSqlStatement from tmpVrijeRubrieken;

  set @@ErrorTextProcedure = 'CheckVrijeRubrieken';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: CleanRightclickPrijzenCache.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

//Vve 27-10-2006: Deze proc ruimt cacheitems op die over de houdbaarheidsdatum zijn.
//De levensduur wordt door de gebruiker ingesteld in de vastegegevens.
if exists (select 1 from sys.sysProcedure where proc_name='CleanRightclickPrijzenCache') then
  drop procedure CleanRightclickPrijzenCache;
end if;

create procedure CleanRightclickPrijzenCache()
begin
  declare @CacheLastCleanTime timestamp;
  declare @CacheLifetime  smallint;
  declare @AantalRecords  integer;
  declare @Overschot      integer;
  declare @THTDatum       datetime;

  set @@ErrorTextProcedure = 'CleanRightclickPrijzenCache';
  //call TraceBegin(@@ErrorTextProcedure);

  //Kijken hoe lang het geleden is dat we gecleaned hebben
  select VgrcCacheLifetime, vgrcCacheLastCleanTime into @CacheLifetime, @CacheLastCleanTime from tabVastegegevensRightclick;

  //Alle verlopen entries verwijderen.
  if @CacheLifeTime <> 4 then  //4=eeuwig dus niks automatisch verwijderen.
    select
      (case @CacheLifeTime
        when 0 then @CacheLastCleanTime           //0=geen cache -> dus alles is direct verlopen, dus alles gaat direct weg.
        when 1 then DateAdd(hour, -2, Now())
        when 2 then DateAdd(hour, -4, Now())
        when 3 then Date(Now())
      end
      )
      into @THTDatum;

      if @CacheLastCleanTime <= @THTDatum then
        //call trace('CleanRightclickPrijzenCache > We gaan cleanen! @CacheLastCleanTime='+ string(@CacheLastCleanTime) + '; @THTDatum='+string(@THTDatum));
        delete from tabPOSRightclickPrijzenCache where prpcCreated < @THTDatum;
        update tabVastegegevensRightclick set vgrcCacheLastCleanTime = Now();
      else
        //call trace('CleanRightclickPrijzenCache > Hoeft niet gecleaned te worden. @CacheLastCleanTime='+string(@CacheLastCleanTime)+'; @THTDatum='+string(@THTDatum));

      end if;
  end if;

  set @@ErrorTextProcedure = 'CleanRightclickPrijzenCache';
  //call TraceEind(@@ErrorTextProcedure);

end;


//---- Test of een bepaalde kolom bestaat in de database
create or replace procedure ColumnExist(in @TabelNaam nchar(40), in @Kolomnaam nchar(40), inout @Exists smallint)
begin
  set @@ErrorTextProcedure = 'ColumnExist > @TabelNaam='+@TabelNaam+', @Kolomnaam='+@Kolomnaam;
  //call TraceBegin(@@ErrorTextProcedure);

  select 1 into @Exists from Sys.SysTable inner join Sys.SysColumn on (SysColumn.table_id = Systable.table_id) where Table_Name = @TabelNaam and Column_Name = @Kolomnaam;
  set @Exists = IsNull(@Exists, 0);

  set @@ErrorTextProcedure = 'ColumnExist > @Exists='+string(@Exists);
  //call TraceEind(@@ErrorTextProcedure);

end;


// Compare unicode strings met sybase Compare() function. Wordt in binary search gebruikt.
// Aangeroepen via IShellDatabaseConnection.CompareStrings()

create or replace function CompareStrings(in @S1 nchar(255), in @S2 nchar(255)) returns integer
begin
  return(compare(@s1, @s2, 'nchar_collation'));
end;


create or replace function ContactPersoonHeeftSelectiecode(in @SlcGid integer, in @RelGid integer)
returns integer
begin
  declare @HeeftSelectie integer;

  //call TraceBegin('ContactPersoonHeeftSelectiecode ( @SlcGid = '+String(@SlcGid)+', @RelGid = '+ String(@RelGid) + ' ).');

  if @SlcGid is null then
    set @HeeftSelectie = 1;
  else
    set @HeeftSelectie = 0;
  end if;

  select 1 into @HeeftSelectie
  from tabSlcPerRelatie
  where SprSlcGid = @SlcGid
    and SprRelGID = @RelGid;


  //call TraceEind('ContactPersoonHeeftSelectiecode ------> @HeeftSelectie='+string(@HeeftSelectie));

  return(@HeeftSelectie);
  exception when others then resignal
end;


//$Workfile: ContactpersoonValtBinnenSelectie.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

//---- functie controleert of een contactpersoon binnen een selectie valt
if exists (select 1 from sys.sysProcedure where proc_name='ContactpersoonValtBinnenSelectie') then
  drop function ContactpersoonValtBinnenSelectie;
end if;

create function ContactpersoonValtBinnenSelectie(in @SelGid integer, in @RelGid integer)
returns integer
begin
  declare @SkGid      integer;
  declare @ValtBinnen integer;

  //call TraceBegin ('ContactpersoonValtBinnenSelectie');

  set @SkGid = null;
  select SelSkGid into @SkGid
  from   tabSelectie
  where  SelGid = @SelGid;

  if @SkGid is null then
    set @ValtBinnen = 1;
  else
    set @ValtBinnen = VoldoetAanKnoop(2, @SkGid, @RelGid, null);
  end if;

  //call TraceEind ('ContactpersoonValtBinnenSelectie ------> @ValtBinnen='+string(@ValtBinnen));
  return(@ValtBinnen);

end;


create or replace procedure ContributieOrdersVerwerken(
          in @DebSelectieOp smallint, in @VanDeb      nchar(10), in @TotDeb nchar(10),
          in @VanContCode   integer , in @TotContCode integer ,
          in @OrderDatum    date    , in @Leverdatum  date    ,
          in @VtgSetting    smallint, in @VtgCode     integer ,
          in @BtcSetting    smallint, in @BtcNummer   integer ,
          out @Resultaat    integer , out @EersteOrderNummer numeric(10,0), out @LaatsteOrderNummer numeric(10,0))
begin
  declare @OrderNummer               numeric(10,0);
  declare @OrrGid                    integer;
  declare @AantalRegels              integer;
  //vars voor vaste gegevens
  declare @Goedgekeurd               smallint;
  declare @VerzamellijstVerplicht    smallint;
  declare @VrijgegevenVoorFact       smallint;
  declare @VrijgegevenVoorLev        smallint;
  declare @VrijgegevenVoorVzl        smallint;

  declare @DeelLeveringToestaan      smallint;
  declare @OrderBevestigingsfunctie  integer;
  declare @CPApartAfdrukken          integer;
  declare @NaamAfdrukken             integer;
  declare @GegenereerdOrderNummerGebruikt smallint;
  declare @GebruikOrderkorting       smallint;
  declare @ReserveerNegatief         smallint;
  //nieuw in 5.30
  declare @OrderKopMagGid            integer;             //magazijn voor de orderkop
  //vars voor debiteuren-loop en debiteuren-gegevens
  declare @NawNummerZoekcode         nchar(20);            //20 om zoekcode+nummer in te passen
  declare @VorigeNawNummerZoekcode   nchar(20);
  declare @NawGid                    integer;
  declare @NawfilBtwCode             integer;
  declare @NawFilValNummer           integer;
  declare @NawContributieCode        integer;
  declare @NawTaalGid                integer;
  declare @NawOrderKorting           numeric(6,2);
  //vars voor contactpersonen-loop en cp-gegevens
  declare @RelNummer                 integer;
  declare @VorigeRelNummer           integer;
  declare @RelGid                    integer;
  declare @RelContributieCode        integer;
  declare @RelVoorNaam               nchar(40);
  declare @RelVolledigeNaam          nchar(40);
  declare @Filgid                    integer;
  declare @IsOrderSpecRegelActief    smallint;

  set @@ErrorTextProcedure = 'ContributieOrdersVerwerken > ';
  //call TraceBegin(@@ErrorTextProcedure + '@DebSelectieOp = ' + string(@DebSelectieOp) + ', @VanDeb = ' + @VanDeb+', @TotDeb = ' + @TotDeb);

  //Het resultaat gaat het totaal aangemaakte aantal orders bevatten
  set @GoedGekeurd             = 0;
  set @VerzamellijstVerplicht  = 0;
  set @IsOrderSpecRegelActief  = IsOrderSpecificatieregelActief();

  //Instelling voor de status order ophalen
  select cast(Contents as integer) into @Goedgekeurd from tabRegistry where RegKey = 'PERORDER_GOEDGEKEURD';
  select cast(Contents as integer) into @VerzamellijstVerplicht from tabRegistry where RegKey = 'PERORDER_VERZAMELLIJSTVERPLICHT';

  //Combobox waardes omzetten in orderstatus-waardes.
  set @VrijgegevenVoorFact     = 0;
  set @VrijgegevenVoorLev      = 0;
  set @VrijgegevenVoorVzl      = 0;
  if @GoedGekeurd in (3,4) then
    set @VrijgegevenVoorFact = 1;
  end if;
  if @GoedGekeurd in (2,4) then
    if @VerzamellijstVerplicht = 0 then
      set @VrijgegevenVoorLev = 1;
    else
      set @VrijgegevenVoorVzl = 1;
    end if;
  end if;
  if @GoedGekeurd > 0 then
    set @GoedGekeurd = 1;
  end if;


  set @Resultaat               = 0;
  set @EersteOrderNummer       = -1;
  set @LaatsteOrderNummer      = -1;
  set @GegenereerdOrderNummerGebruikt = 1;

  select cast(Contents as integer) into @CPApartAfdrukken from tabRegistry  where RegKey = 'PERORDER_APART_AFDRUKKEN';
  select cast(Contents as integer) into @NaamAfdrukken    from tabRegistry  where RegKey = 'PERORDER_NAAM_AFDRUKKEN';
  select DocFnCodeDefault into @OrderBevestigingsfunctie  from tabDocument  where DocSoort = 20;
  select first vofKopDefDeellevering, vofOrderKortingSoort, VofFactVoorraadReserverenNegatief into @DeelLeveringToestaan, @GebruikOrderkorting, @ReserveerNegatief from tabVasteGegevensOrdersFactureren;

  //Magazijn bepalen
  set @OrderKopMagGid = null;
  select ToeMagMagGid into @OrderKopMagGid from tabToegestaneMagazijnen inner join tabGebruiker on (GebruikerGid = ToeMagGebrGid) where NaamGebruiker = @@GebruikerCode and ToeMagToepassing = 10;
  if @OrderKopMagGid is null then
    select MagGid into @OrderKopMagGid from tabMagazijn where MagCode=1;
  end if;
  //call Trace('ContributieOrdersVerwerken >  @OrderKopMagGid = ' + string(@OrderKopMagGid));

  set @VorigeNawNummerZoekcode = '';
  //alle debiteuren aflopen
  LoopDebiteuren :
  loop
    //Zonder initialisatie stopt loop nooit!!!
    set @NawGid = null;

    //Zoek 'volgende' debiteur die een contributie-code binnen de cc-range heeft, OF (minimaal) een cp heeft die een cc heeft die binnen de cc-range ligt en niet geblokkerd is voor orderinvoer
    if @DebSelectieOp = 0 then     //op nummer doorlopen
      select first NawfilNummer,       NawGid,  NawfilBtwCode,  NawContributieCode,  NawTaalGid,  (if NawFilWelkeOrderkorting=0 then NawOrderKorting else DebGrpOrderKorting endif),  NawFilValNummer, NawfilGid
      into         @NawNummerZoekcode, @NawGid, @NawfilBtwCode, @NawContributieCode, @NawTaalGid, @NawOrderKorting, @NawFilValNummer, @FilGid
      from tabNaw inner join tabNawFile on (NawFilNawGid = NawGid)
      left outer join tabRelatie on RelNawGid = NawGid
      left outer join tabDebiteurgroepen on DebGrpGid = NawFilDebGrpGid
      where NawfilNummer > @VorigeNawNummerZoekcode
        and NawfilFonId = 'D'
        and NawfilNummer       between @VanDeb      and @TotDeb
        and NawBlokOrderInvoer = 0
        and ( ( NawContributieCode between @VanContCode and @TotContCode) or
              ( RelContributieCode between @VanContCode and @TotContCode) )
      order by NawfilNummer
    end if;
    if @DebSelectieOp = 1 then     //op zoekcode doorlopen (uniek maken met nummer erbij; eerst zoekcode uitvullen met spaties)
      select first left(nawfilZoekcode+replicate(' ', 10), 10)+nawfilNummer ZoekcodeEnNummer,
                                 NawGid,  NawfilBtwCode,  NawContributieCode,  NawTaalGid,  (if NawFilWelkeOrderkorting=0 then NawOrderKorting else DebGrpOrderKorting endif),  NawFilValNummer, NawfilGid
      into   @NawNummerZoekcode, @NawGid, @NawfilBtwCode, @NawContributieCode, @NawTaalGid, @NawOrderKorting, @NawFilValNummer, @FilGid
      from tabNaw inner join tabNawFile on (NawFilNawGid = NawGid)
      left outer join tabRelatie on RelNawGid = NawGid
      left outer join tabDebiteurgroepen on DebGrpGid = NawFilDebGrpGid
      where ZoekcodeEnNummer > @VorigeNawNummerZoekcode
        and NawfilFonId = 'D'
        and NawfilZoekcode     between @VanDeb      and @TotDeb
        and NawBlokOrderInvoer = 0
        and ( ( NawContributieCode between @VanContCode and @TotContCode) or
              ( RelContributieCode between @VanContCode and @TotContCode) )
      order by ZoekcodeEnNummer;
    end if;

    //call Trace('ContributieOrdersVerwerken > @NawNummerZoekcode = ' + @NawNummerZoekcode + ', @VorigeNawNummerZoekcode = ' + @VorigeNawNummerZoekcode);

    if @NawGid is null then
      leave LoopDebiteuren;
    end if;

    //Stel dat er een ordernummer is gegenereerd, maar er werden uiteindelijk geen orderregels aangemaakt,
    // dan is het StartNummer wel opgehoogd in Vaste gegevens. Om de ordernummers dus aaneengesloten te houden,
    // het ongebruikte ordernummer opnieuw gebruiken voor de volgende order.
    if @GegenereerdOrderNummerGebruikt = 1 then
      //Ordernummer genereren en onthouden
      set @OrderNummer  = GeefNieuwOrderNummer(0, 1);
      //Eerste ordernummer onthouden.
      if @EersteOrderNummer = -1 then
        set @EersteOrderNummer = @OrderNummer;
      end if;
      //Laatste ordernummer zetten.
      set @LaatsteOrderNummer = @OrderNummer;
    end if;

    //Nieuwe order => 0 regels dus
    set @AantalRegels = 0;
    //Voor deze debiteur een order beginnen.
    insert into tabOrderkop
        (OrkSoort, OrkInclBtw, OrkIsDeelLeveringToegestaan,
         OrkIsGeblokkeerdVoorMuteren,OrkBackTotaalInklBtw,OrkBackTotaalExklBtw,
         OrkGoedgekeurd,           OrkGoedgekeurdDatum,           OrkGoedgekeurdDoor,
         OrkVrijVoorFaktureren,    OrkVrijgegevenDatum,           OrkVrijgegevenDoor,
         OrkVrijVoorLevering,      OrkVrijVoorLeveringDatum,      OrkVrijVoorLeveringDoor,
         OrkVrijVoorVerzamelLijst, OrkVrijVoorVerzamelLijstDatum, OrkVrijVoorVerzamelLijstDoor,
         OrkDatum,OrkLeverdatum, OrkVtgCode,
         OrkNawGid,OrkApartFaktureren,OrkAdrGid,OrkVerzendAdres,OrkFactuurAdres,OrkBtcNummer,OrkLvcNummer,OrkValNummer,OrkNummer,OrkRelGid,OrkReferentie,
         OrkDefaultMagGid, OrkIsVerzamellijstGebruiken, OrkIncNawRekGid,
         OrkIsInkoopCombinatie, OrkFactuurNawGid, OrkNawGidOmzet, OrkNawGidPrijzen)
    select   0 /*Verkooporder*/, MainNaw.nawFacturerenInclBtw, @DeelLeveringToestaan,
           //Vlaggetjes vd order
             0, 0, 0,
           //goedgekeurd             //goedgekeurd datum                              //goedgekeurd gebruiker
             @Goedgekeurd,           if (@GoedGekeurd = 1)         then now(*) endif, if (@GoedGekeurd = 1)         then @@GebruikerCode endif,
           //vrij voor Fact          //vrijgegeven datum                              //vrijgegeven gebruiker
             @VrijgegevenVoorFact,   if (@VrijgegevenVoorFact = 1) then now(*) endif, if (@VrijgegevenVoorFact = 1) then @@GebruikerCode endif,
           //vrij voor lev.          //vrijgegeven datum                              //vrijgegeven gebruiker
             0, null, null, //5.30: deze zetten we beneden in de proc ivm partij/serienummers.
           //vrij voor verzamellijst //vrijgegeven datum                              //vrijgegeven gebruiker
             @VrijgegevenVoorVzl,    if (@VrijgegevenVoorVzl = 1)  then now(*) endif, if (@VrijgegevenVoorVzl = 1)  then @@GebruikerCode endif,
           //datums
             @OrderDatum, @Leverdatum,
           //vertegenwoordiger ophalen
             if @VtgSetting = 0 then //van debiteur, anders default
               IsNull(MainNaw.nawVertegenwCode, @VtgCode)
             else      //anders altijd de parameter gebruiken
               @VtgCode
             endif,
           //velden uit deb-gegevens...
             MainNaw.NawGid,
           //Vve 19-1-2006 Evt AparteFact en verzend adres van fact.deb overnemen
             IsNull((select FactuurDeb.NawAparteFacturen from tabNaw FactuurDeb where FactuurDeb.NawGid = MainNaw.NawIdFactDeb), MainNaw.NawAparteFacturen),
             IsNull((select FactuurDeb.NawGidVerzendAdres from tabNaw FactuurDeb where FactuurDeb.NawGid = MainNaw.NawIdFactDeb), MainNaw.NawGidVerzendAdres) VerzendAdresGid,
           //Vve 19-1-2006 bug 18501: Als er geen verzendadres is, dan schakelen we terug naar het juiste correspondentieadres
             (if VerzendAdresGid is null and MainNaw.NawVerzendAdres = 2 then
                0 //=corr. order deb
              else
              if VerzendAdresGid is null and MainNaw.NawVerzendAdres = 5 then
                3 //=corr. fact. deb.
              else
               MainNaw.NawVerzendAdres
              endif endif),
             MainNaw.NawFactuurAdres,
           //[rev. 1.04] betalingsconditie ophalen
           //Vve 19-1-2006 Evt. btc van fact.deb overnemen.
             (if @BtcSetting = 0 then
               IsNull((select FactuurDeb.NawFilBtcNummer from tabNawFile FactuurDeb where FactuurDeb.NawFilNawGid = MainNaw.NawIdFactDeb), MainNawFile.NawFilBtcNummer, @BtcNummer)
             else
               @BtcNummer
             endif) OrderkopBtcNummer,
             MainNawFile.NawFilLvcNummer, MainNawFile.NawFilValNummer,
           //Gegenereerd ordernummer
             @OrderNummer,
           //VoorkeurContactpersoon van functie die bij Orderbevestiging staat
             RelGid,
           //Referentietekst is al gekopieerd naar @@ParamLongVarchar
             @@ParamLongVarChar,
           //Magazijn
             @OrderKopMagGid, @VerzamellijstVerplicht,
           //Orderkop rekeningnummer [rev. 1.04]
             (if (select SoortFactuurBtc from tabBetalingsConditie where BtcNummer = OrderkopBtcNummer) = 3 then
                (select NawRekGid from tabNawRekening where NawRekNawGid = IsNull(MainNaw.NawIdFactDeb, MainNaw.NawGid) and Locate(NawRekSoort, 'I') <> 0)
              else
                null
              endif),
           //Vve 19-1-2006 Nieuw 5.40: Ook inkoopcominatieveldjes overnemen
             MainNaw.NawIsInkoopCombinatie, MainNaw.NawIdFactDeb, MainNaw.NawidDebOmzet, MainNaw.NawidDebPrijzen

             from tabNaw MainNaw inner join tabNawFile MainNawFile on (MainNawFile.NawFilNawGid = MainNaw.NawGid)
             left outer join tabContributieCode on ContributieCode = @NawContributieCode

             left outer join (tabScherm inner join tabFunctieContact on (SchermFnCode = FnCode )
                inner join ( tabRelatieFunctie inner join tabRelatie on(RelGid = FnRelGid and relNawGid = @NawGid ) ) on ( FnCode = RelFnCode and IsBelangrijkste = 1 )) on SchermSoort = 30

             where MainNaw.NawGid = @NawGid;



    //call Trace('ContributieOrdersVerwerken > Orderregels voor de debiteur aanmaken bij @ordernr: '+ String(@OrderNummer));
    //Checken of NAW een co heeft die binnen de selectie valt (je kan hier nl ook komen als cp een co heeft)
    if @NawContributieCode between @VanContCode and @TotContCode then
      FOR @Cursor AS CURSOR_NAWOrderRegels CURSOR FOR

        select
            OrkGid @OrrOrkGid,

            //Leverdatum null bij Tekstblokken
            if CorRegelSoort <> 0 then OrkLeverdatum endif @OrrLeverdatum,

            //regelnr leeglaten, moet worden gegenereerd.
            null @OrrRegelNr,

            //tabContributieOrderRegel
            CorAantDecAantal         @OrrAantDecAantal,
            CorAantDecBedrag         @OrrAantDecBedrag,
            ArtKostprijsEx           @OrrKostprijs,
            CorPrijsPer              @OrrPrijsPer,
            CorArtGid                @OrrArtGid,
            CorIsAantallen           @OrrIsAantallen,
            CorRegelSoort            @OrrRegelSoort,
            CorIsKortingsPercentage  @OrrIsKortingsPercentage,
            CorRegelKorting2         @OrrRegelKorting2,

            //Korting 1 omrekenen indien het een bedrag-korting is.
            if CorIsKortingsPercentage = 0 then
              ValutaOmrekenen(@@BasisValutaNummer, CorRegelkorting1, @NawFilValNummer, null, null, @OrrAantDecBedrag)
            else
              CorRegelKorting1
            endif @OrrRegelkorting1,

            //indien debiteur btw%=0 dan die nemen.
            if (@NawFilBtwCode is null) or ((select BtwPercentage from tabBtw where BtwCode = @NawFilBtwCode) <> 0) then CorBtwCode
            else @NawFilBtwCode
            endif @OrrBTWCode,

            //Prijzen evt. omrekenen: Naar in/ex btw: Indien debiteur btw% = 0 dan incl prijzen terugrekenen naar exclusief prijzen mbv CorBtwCode
            //   Ook omrekenen naar valuta van debiteur.
            ValutaOmrekenen(
              @@BasisValutaNummer,
               (if (@NawFilBtwCode is not null) and ((select BtwPercentage from tabBtw where BtwCode = @NawFilBtwCode) = 0) then
                  if (ContributieInclBtw = 1) then CorBrutoVerkoopPrijs * (1 / (1 + (select (BtwPercentage/100) from tabBtw where BtwCode = CorBtwCode)))
                  else CorBrutoVerkoopPrijs
                  endif
                else    //als debiteur geen 0% btw heeft, dan de prijzen omrekenen naar de btw-'format' van de order.
                  if OrkInclBtw = ContributieInclBtw then CorBrutoVerkoopPrijs
                    else if OrkInclBtw > ContributieInclBtw then CorBrutoVerkoopPrijs * (1 + (select (BtwPercentage/100) from tabBtw where BtwCode = CorBtwCode))
                      else if OrkInclBtw < ContributieInclBtw then CorBrutoVerkoopPrijs * (1 / (1 + (select (BtwPercentage/100) from tabBtw where BtwCode = CorBtwCode)))
                      endif
                    endif
                  endif
                endif),
              @NawfilValNummer,
              null,     //boekjaargid en periodenummer leeglaten, dan wordt verwerkingsdatum gebruikt bij omrekenen.
              null, @OrrAantDecBedrag) @OrrBrutoVerkoopPrijs,

            //tabArtikel
            ArtOpbrGrpGid              @OrrOpbrGrpGid,
            if CorRegelSoort = 2 then IsNull(ArtDefaultMagGid, @OrderKopMagGid) endif @OrrMagGid,
            ArtHeeftVoorraad           @ArtHeeftVoorraad,
            ArtIsPartijRegistreren     @ArtIsPartijRegistreren,
            ArtSerieNrRegistreren      @ArtSerieNrRegistreren,

            //tabContributieOrderRegelTeksten
            CortTekst                  @OrrTekstOpFactuur,

            //als coraantal nul is bij Art/Tar, dan op 1 zetten
            (if (CorAantalBesteld = 0) and (CorRegelSoort <> 0) then 1 else CorAantalBesteld endif) @OrrAantalBesteld,
            @OrrAantalBesteld          @OrrAantalDezeFacturering,
            @OrrAantalBesteld          @OrrAantalLevering,

            VkeGid                                    @VkeGid,
            VkeAantalVoorraadEenhedenInVerkoopEenheid @VkeAantalVoorraadEenhedenInVerkoopEenheid,
            VkeAantalKanVerschillen                   @VkeAantalKanVerschillen

        from tabContributieOrderRegel
             left outer join tabArtikel                    on (CorArtGid = ArtGid)
             left outer join tabVerkoopEenheid             on (VkeArtGid = ArtGid) and (VkeIsVoorraadEenheid = 1)
             left outer join tabOrderkop                   on (OrkNummer = @OrderNummer)
             left outer join tabContributieCode            on (ContributieCode = @NawContributieCode)
             left outer join tabContributieOrderRegelTekst on (CortCorGid = CorGid and CortTaalGid = @NawTaalGid)
        where (CorContributieCode = @NawContributieCode) and
              (NawValtBinnenSelectie(CorSelGid,@FilGid) = 1) and
              (NawHeeftSelectieCode (CorSlcGid,@FilGid,@NawGid) = 1) and
              (IsNull(ArtIsGeblokkeerd, 0) = 0)
        order by CorRegelNr
      FOR READ ONLY
      DO
        //De contributieorderregels kopieren naar de order, indien de DEBITEUR voldoet aan de selectie

        insert into tabOrderRegel
          (OrrOrkGid,OrrLeverDatum,OrrRegelnr,OrrAantDecAantal,OrrAantDecAantalVrrdEenh,OrrAantDecBedrag,OrrKostprijs,
           OrrPrijsPer,OrrArtGid,OrrIsAantallen,OrrRegelsoort,OrrIsKortingsPercentage,OrrRegelkorting2,
           OrrRegelKorting1,OrrBtwCode,OrrBrutoVerkoopPrijs,OrrOpbrGrpGid,OrrTekstOpFactuur,
           OrrVkeGid,OrrAantalVrrdEenhInVerkEenh, OrrAantalVrrdEenhInVerkEenhMagAfwijken,
           OrrAantalBesteld, OrrAantalBesteldVrrdEenh,
           OrrAantalDezeFacturering, OrrAantalDezeFactureringVrrdEenh,
           OrrAantalLevering, OrrAantalLeveringVrrdEenh,
           OrrMagGid, OrrReserveringNegatief)
        values
          (@OrrOrkGid,@OrrLeverDatum,@OrrRegelnr,@OrrAantDecAantal,@OrrAantDecAantal,@OrrAantDecBedrag,@OrrKostprijs,
           @OrrPrijsPer,@OrrArtGid,@OrrIsAantallen,@OrrRegelsoort,@OrrIsKortingsPercentage,@OrrRegelkorting2,
           @OrrRegelKorting1,@OrrBtwCode,@OrrBrutoVerkoopPrijs,@OrrOpbrGrpGid,@OrrTekstOpFactuur,
           @VkeGid, @VkeAantalVoorraadEenhedenInVerkoopEenheid, @VkeAantalKanVerschillen,
           @OrrAantalBesteld, @OrrAantalBesteld,
           @OrrAantalDezeFacturering, @OrrAantalDezeFacturering,
           @OrrAantalLevering, @OrrAantalLevering,
           @OrrMagGid, @ReserveerNegatief);

        set @OrrGid = @@Identity;

        //Nu moeten we een detail regel aanmaken zodat aantal gereserveerd overeen komt.
        // ACW 2023-04-04: specificatieregels invullen alsof we aan het invoeren zijn (of afhankelijk van orderstatus)
        if @OrrRegelSoort = 2 and @OrrAantalLevering<>0 and
           (@IsOrderSpecRegelActief = 1) then
          begin
            declare @HeeftSpecregelsZonderLocatie smallint;
            call OrderRegelSpecificaties_VulLocatiesAan(
              @OrrOrkGid,
              @OrrGid,
              @MatViewNummerVoorraadAantallen = '',
              @HeeftSpecregelsZonderLocatie=@HeeftSpecregelsZonderLocatie
            );
          end;
        end if;

      end FOR; //CURSOR_NAWOrderRegels

      //Nu alvast een lege tekstregel in de order plaatsen indien er net regels zijn toegevoegd
      if exists (select 1 from tabOrderRegel inner join tabOrderKop where OrkNummer = @OrderNummer) then
        insert into tabOrderRegel (OrrOrkGid, OrrRegelnr, OrrRegelsoort, OrrTekstOpFactuur)
        select OrkGid, null, 0, '' from tabOrderKop where OrkNummer = @OrderNummer;
      end if;

    end if;


    //Contactpersonen krijgen ook orderregels
    set @VorigeRelNummer = -1;

    LoopContactPersonen:
    loop
      //Zonder deze initialisatie stopt loop nooit!!!
      set @RelGid = null;
             //Zoek volgende cp bij deze naw die deze contributiecode heeft ingevuld
      select first RelNummer,  RelGid,  RelContributieCode,  RelVoorNaam,  RelVolledigeNaam
      into         @RelNummer, @RelGid, @RelContributieCode, @RelVoorNaam, @RelVolledigeNaam
      from   tabRelatie
      where  RelNummer > @VorigeRelNummer and
             RelNawGid = @NawGid and
             RelContributieCode between @VanContCode and @TotContCode
      order by RelNummer;

      if @RelGid is null then
        leave LoopContactPersonen;
      end if;

      if @CPApartAfdrukken = 1 then
        //Nu een tekstregel met de naam van de contactpersoon in de order plaatsen
        insert into tabOrderRegel (OrrOrkGid, OrrRegelnr, OrrRegelsoort, OrrTekstOpFactuur)
        select OrkGid, null, 0, if @NaamAfdrukken = 1 then @RelVoornaam else @RelVolledigeNaam endif
        from tabOrderKop where OrkNummer = @OrderNummer;
      end if;

      //Kijken hoeveel regels er nu in de order staan, zodat we na het volgende insert-statement kunnen zien of er regels zijn bijgekomen
      select count(*) into @AantalRegels
      from tabOrderRegel inner join tabOrderKop where OrkNummer = @OrderNummer;

      if @RelContributieCode between @VanContCode and @TotContCode then
        FOR @Cursor AS CURSOR_CPOrderRegels CURSOR FOR
          //De contributieorderregels kopieren naar de order, indien de CONTACTPERSOON voldoet aan de selectie
          select
              OrkGid @OrrOrkGid,
              //Leverdatum null bij Tekstblokken
              if CorRegelSoort <> 0 then OrkLeverdatum endif @OrrLeverdatum,

              //Regelnr leeglaten, moet worden gegenereerd.
              null @OrrRegelnr,

              //tabContributieOrderRegel
              CorAantDecAantal         @OrrAantDecAantal,
              CorAantDecBedrag         @OrrAantDecBedrag,
              ArtKostprijsEx           @OrrKostprijs,
              CorPrijsPer              @OrrPrijsPer,
              CorArtGid                @OrrArtGid,
              CorIsAantallen           @OrrIsAantallen,
              CorRegelSoort            @OrrRegelSoort,
              CorIsKortingsPercentage  @OrrIsKortingsPercentage,
              CorRegelKorting2         @OrrRegelKorting2,

              //Korting 1 omrekenen indien het een bedrag-korting is.
              if CorIsKortingsPercentage = 0 then
                ValutaOmrekenen(@@BasisValutaNummer, CorRegelkorting1, @NawFilValNummer, null, null, @OrrAantDecBedrag)
              else
                CorRegelKorting1
              endif @OrrRegelkorting1,

              //indien debiteur btw%=0 dan die nemen. Tevens deze code opslaan in alias zodat die prijsomrekeningen gelijk gebruikt kan worden.
              if (@NawFilBtwCode is null) or ((select BtwPercentage from tabBtw where BtwCode = @NawFilBtwCode) <> 0) then CorBtwCode
              else @NawFilBtwCode
              endif @OrrBTWCode,

              //Prijzen evt. omrekenen.
              //Indien debiteur btw% = 0 dan incl prijzen terugrekenen naar exclusief prijzen mbv CorBtwCode
              //   Ook omrekenen naar valuta van debiteur.
              ValutaOmrekenen(
                @@BasisValutaNummer,
                 (if (@NawFilBtwCode is not null) and ((select BtwPercentage from tabBtw where BtwCode = @NawFilBtwCode) = 0) then
                    if (ContributieInclBtw = 1) then CorBrutoVerkoopPrijs * (1 / (1 + (select (BtwPercentage/100) from tabBtw where BtwCode = CorBtwCode)))
                    else CorBrutoVerkoopPrijs
                    endif
                  else    //als debiteur geen 0% btw heeft, dan de prijzen omrekenen naar de btw-'format' van de order.
                    if OrkInclBtw = ContributieInclBtw then CorBrutoVerkoopPrijs
                      else if OrkInclBtw > ContributieInclBtw then CorBrutoVerkoopPrijs * (1 + (select (BtwPercentage/100) from tabBtw where BtwCode = CorBtwCode))
                        else if OrkInclBtw < ContributieInclBtw then CorBrutoVerkoopPrijs * (1 / (1 + (select (BtwPercentage/100) from tabBtw where BtwCode = CorBtwCode)))
                        endif
                      endif
                    endif
                  endif),
                @NawfilValNummer,
                null,     //boekjaargid en periodenummer leeglaten, dan wordt verwerkingsdatum gebruikt bij omrekenen.
                null, @OrrAantDecBedrag) @OrrBrutoVerkoopPrijs,

              //tabArtikel
              ArtOpbrGrpGid              @OrrOpbrGrpGid,
              if CorRegelSoort = 2 then IsNull(ArtDefaultMagGid, @OrderKopMagGid) endif @OrrMagGid,
              ArtHeeftVoorraad           @ArtHeeftVoorraad,
              ArtIsPartijRegistreren     @ArtIsPartijRegistreren,
              ArtSerieNrRegistreren      @ArtSerieNrRegistreren,

              //tabContributieOrderRegelTeksten
              CortTekst @OrrTekstOpFactuur,

              //als coraantal nul is bij Art/Tar, dan op 1 zetten
              (if (CorAantalBesteld = 0) and (CorRegelSoort <> 0) then 1 else CorAantalBesteld endif)  @OrrAantalBesteld,
              @OrrAantalBesteld          @OrrAantalDezeFacturering,
              @OrrAantalBesteld          @OrrAantalLevering,

              VkeGid                                    @VkeGid,
              VkeAantalVoorraadEenhedenInVerkoopEenheid @VkeAantalVoorraadEenhedenInVerkoopEenheid,
              VkeAantalKanVerschillen                   @VkeAantalKanVerschillen

          from tabContributieOrderRegel
              left outer join tabArtikel                    on (CorArtGid = ArtGid)
              left outer join tabVerkoopEenheid             on (VkeArtGid = ArtGid) and (VkeIsVoorraadEenheid = 1)
              left outer join tabOrderkop                   on (OrkNummer = @OrderNummer)
              left outer join tabContributieCode            on (ContributieCode = @RelContributieCode)
              left outer join tabContributieOrderRegelTekst on (CortCorGid = CorGid and CortTaalGid = @NawTaalGid)
          where (CorContributieCode = @RelContributieCode) and
                (ContactpersoonValtBinnenSelectie(CorSelGid, @RelGid) = 1) and
                (ContactPersoonHeeftSelectieCode (CorSlcGid, @RelGid) = 1) and
                (IsNull(ArtIsGeblokkeerd, 0) = 0)
          order by CorRegelNr
        FOR READ ONLY
        DO
          //De contributieorderregels kopieren naar de order, indien de CONTACTPERSOON voldoet aan de selectie

          insert into tabOrderRegel
            (OrrOrkGid,OrrLeverDatum,OrrRegelnr,OrrAantDecAantal,OrrAantDecBedrag,OrrKostprijs,
             OrrPrijsPer,OrrArtGid,OrrIsAantallen,OrrRegelsoort,OrrIsKortingsPercentage,OrrRegelkorting2,
             OrrRegelKorting1,OrrBtwCode,OrrBrutoVerkoopPrijs,OrrOpbrGrpGid,OrrTekstOpFactuur,
             OrrVkeGid,OrrAantalVrrdEenhInVerkEenh, OrrAantalVrrdEenhInVerkEenhMagAfwijken,
             OrrAantalBesteld,OrrAantalBesteldVrrdEenh,
             OrrAantalDezeFacturering,OrrAantalDezeFactureringVrrdEenh,
             OrrAantalLevering,OrrAantalLeveringVrrdEenh,
             OrrMagGid, OrrReserveringNegatief)
          values
            (@OrrOrkGid,@OrrLeverDatum,@OrrRegelnr,@OrrAantDecAantal,@OrrAantDecBedrag,@OrrKostprijs,
             @OrrPrijsPer,@OrrArtGid,@OrrIsAantallen,@OrrRegelsoort,@OrrIsKortingsPercentage,@OrrRegelkorting2,
             @OrrRegelKorting1,@OrrBtwCode,@OrrBrutoVerkoopPrijs,@OrrOpbrGrpGid,@OrrTekstOpFactuur,
             @VkeGid, @VkeAantalVoorraadEenhedenInVerkoopEenheid, @VkeAantalKanVerschillen,
             @OrrAantalBesteld, @OrrAantalBesteld,
             @OrrAantalDezeFacturering, @OrrAantalDezeFacturering,
             @OrrAantalLevering, @OrrAantalLevering,
             @OrrMagGid, @ReserveerNegatief);

          set @OrrGid = @@Identity;

          //Nu moeten we een detail regel aanmaken zodat aantal gereserveerd overeen komt.
        // ACW 2023-04-04: specificatieregels invullen alsof we aan het invoeren zijn (of afhankelijk van orderstatus)
          if @OrrRegelSoort = 2 and @OrrAantalLevering<>0 and
             (@IsOrderSpecRegelActief = 1) then
            begin
              declare @HeeftSpecregelsZonderLocatie smallint;
              call OrderRegelSpecificaties_VulLocatiesAan(
                @OrrOrkGid,
                @OrrGid,
                @MatViewNummerVoorraadAantallen = '',
                @HeeftSpecregelsZonderLocatie=@HeeftSpecregelsZonderLocatie
              );
            end;
          end if;

        end FOR; //CURSOR_CPOrderRegels
      end if;


      //Nu weer een lege tekstregel in de order plaatsen indien er net regels zijn toegevoegd
      if (select count(*) from tabOrderRegel inner join tabOrderKop where OrkNummer = @OrderNummer) > @AantalRegels then
        insert into tabOrderRegel (OrrOrkGid, OrrRegelnr, OrrRegelsoort, OrrTekstOpFactuur)
        select OrkGid, null, 0, '' from tabOrderKop where OrkNummer = @OrderNummer
      elseif @CPApartAfdrukken = 1 then
      // er zijn geen regels, gooi de cp-naam regel dus maar weer weg INDIEN die was ingevuld. Dit is de laatste regel (dus hoogste regelnummer).
        delete tabOrderRegel from tabOrderKop
        where  OrkGid = OrrOrkgid and OrkNummer = @OrderNummer and
               OrrRegelnr = (select Max(OrrRegelNr) from tabOrderKop A inner join taborderregel on (OrrOrkGid = A.OrkGid) where A.OrkNummer = @OrderNummer)
      end if;

      set @VorigeRelNummer = @RelNummer;

    end loop LoopContactPersonen;

    //Kijken of er nu uberhaupt regels zijn aangemaakt bij het ordernummer
    if not exists (select 1 from tabOrderRegel inner join tabOrderKop where OrkNummer = @OrderNummer) then
      delete from tabOrderKop where OrkNummer = @OrderNummer;
      set @GegenereerdOrderNummerGebruikt = 0;
    else

      set @Resultaat = @Resultaat + 1;

      begin
        declare @_OrderkortingTekst long nvarchar;
        if (@NawOrderKorting <> 0) and (@GebruikOrderkorting = 1)then
          set @_OrderkortingTekst = _A('Orderkorting');
          insert into tabOrderExtraRegel
             (OerOrkGid, OerBerekenOverToeslag,OerBerekenOverKorting,OerBerekenOverEmballage,OerBerekenOverArtikel,OerBerekenOverTarief,
              OerRegelnr,OerRegelSoort,OerOmschrijving,OerTekstOpFactuur,OerPerc)
          values
             ((select OrkGid from tabOrderkop where OrkNummer = @OrderNummer),
              1, 1, 2, 2, 2, 0, 0, @_OrderkortingTekst, @_OrderkortingTekst, @NawOrderKorting);
        end if;
      end;

      //nieuw 5.30: Als er artikelen met partijen/serienummer registratie zijn gebruikt, kan de order nooit op "Vrij voor leveren" komen.
      if not (exists (select 1 from tabOrderRegel inner join tabOrderKop left outer join tabArtikel on OrrArtGid = ArtGid where OrkNummer = @OrderNummer and OrrRegelSoort = 2 and (ArtIsPartijRegistreren = 1 or ArtSerieNrRegistreren = 1)))
         and @VrijgegevenVoorLev =1 then
        update tabOrderKop set
          OrkVrijVoorLevering = 1,
          OrkVrijVoorLeveringDatum = now(*),
          OrkVrijVoorLeveringDoor = @@GebruikerCode
        where OrkNummer = @OrderNummer;
      end if;

      //ALS er dus regels waren aangemaakt, was de laatste regel een lege tekstregel; die nog even verwijderen en dan isie klaar!
      delete tabOrderRegel from tabOrderKop
      where  OrkGid = OrrOrkgid and OrkNummer = @OrderNummer and
             OrrRegelnr = (select Max(OrrRegelNr) from tabOrderKop A inner join taborderregel on (OrrOrkGid = A.OrkGid) where A.OrkNummer = @OrderNummer);
      set @GegenereerdOrderNummerGebruikt = 1;
    end if;

    set @VorigeNawNummerZoekcode = @NawNummerZoekcode;

    commit;  //RB/18-02-2011: Ivm lockjes die bleven hangen

  end loop LoopDebiteuren;

  //Orderstartnummer terugzetten indien niet gebruikt.
  if @Resultaat > 1 and @GegenereerdOrderNummerGebruikt = 0 then
    call ResetGegenereerdOrderNummer(@OrderNummer);
  end if;

  set @@ParamLongVarChar = null;

  set @@ErrorTextProcedure = 'ContributieOrdersVerwerken';
  //call TraceEind(@@ErrorTextProcedure + ' > @Resultaat = ' + string(@Resultaat));
end;


create or replace procedure ControleerHistorischAdres(
  in    @AdrSoort  smallint,
  in    @NawGid    integer,
  in    @FkGid      integer,
  in    @FrefGid   integer,
  in    @AdresInstelling integer,
  inout @ErrorMask integer,
  out   @AdrGid    integer
  )
begin
  // ----------------------------------------------------------------------------------------
  // -------- ControleerHistorischAdres tbv Order aanmaken via Factuurhistorie---------------
  // ---- Controleert of het in de factuurhistorie opgeslagen adres nog bestaat voor NAW ----
  // ----------------------------------------------------------------------------------------

  set @@ErrorTextProcedure = 'ControleerHistorischAdres > @AdrSoort='+string(@AdrSoort)+', @NawGid='+string(@NawGid)+', @FkGid='+string(@FkGid)+', @FrefGid='+string(@FrefGid)+', @ErrorMask='+string(@ErrorMask);
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select 1 from tabFactuurAdres where @AdrSoort = faSoortAdres and ((@FkGid is not null and faFkGid = @FkGid) or (@FrefGid is not null and faFrefGid = @FrefGid))) then
    select
      first AdrGid into @AdrGid
    from tabFactuurAdres
    left outer join tabAdres on AdrNawGid = @NawGid
    left outer join tabLand  on AdrLndGid = LndGid
    where ( (@FkGid is not null and faFkGid = @FkGid) or
            (@FrefGid is not null and faFrefGid = @FrefGid) )
            and faSoortAdres = @AdrSoort
            and faNaam1      = AdrNaam1
            and faNaam2      = AdrNaam2
            and faStraat     = AdrStraat
            and faHuisnummer = AdrHuisnummer
            and faPlaats     = AdrPlaats
            and faPostcode   = AdrPostcode
            and faLand       = LndOms
            //RS 15-12-2014 #43967 Bij verzend en eindbestemmingadres (12,13) moet er een adres met een nummer gevonden worden, bij vestigings en corr. adres (1,2) maakt het niet uit
            //RS 26-05-2014 #45491 Bovenstaande is niet juist. Zou eerder (0,1) moeten zijn voor het vest. en corr. adres, maar ook hoort er naar de instellingen in de originele order gekeken te worden
            // 										 en daarvoor wordt nu de hist. instelling voor zowel het verz. als eindb. adres gebruikt. Is de historische entry specifiek gekozen, dan moet de AdrCode gevuld zijn.
            and ( (@AdrSoort in (0,1)) or
            		  ((@AdrSoort in (12) and (@AdresInstelling in (0,1) or AdrCode is not null))) or
            		  ((@AdrSoort in (13) and (@AdresInstelling in (0,1) or AdrCode is not null)))
            		);

    if @AdrGid is null then
      case @AdrSoort
         when  0 then set @ErrorMask = @ErrorMask +  32  //  32 - Correspondentie adres gewijzigd
         when  1 then set @ErrorMask = @ErrorMask +  64  //  64 - Factuur adres gewijzigd
         when 12 then set @ErrorMask = @ErrorMask + 128  // 128 - Verzend adres gewijzigd
         when 13 then set @ErrorMask = @ErrorMask + 256  // 256 - Eindbestemming adres gewijzigd
       end case;
    end if;
  else
    ////call Trace('Geen record voor adressoort in historische factuur');
  end if;

/* Eventueel uit te breiden met onderstaande

  faContactEmail
  faContactNaamAanhef
  faContactNaamAdres
  faContactNaamBrief
  faContactTelefax
  faContactTelefoon
  faEANcode
  faEmail
  faHuisnummer
  faHuisnummerPositie
  faLand
  faNaam1
  faNaam2
  faPlaats
  faPostcode
  faPostcodePositie
  faStraat
  faTelefax
  faTelefoon
*/
  set @@ErrorTextProcedure = @@ErrorTextProcedure +', @AdrGid='+string(@AdrGid);
  //call TraceEind(@@ErrorTextProcedure);

end;


//----------------------------------------------------------------------------------------
//------------------------------ Controleer marge per regel ------------------------------
//----------------------------------------------------------------------------------------
create or replace procedure ControleerMargePerOrderRegel(in @OrkGid integer, @MargeIsPercVanVerkoop Smallint, @MinMargePercentage numeric(5,2), @TestOpMinMarge Smallint)
begin
  declare @OrkValNummer   integer;
  declare @OrderKorting   numeric(15,2);
  declare @OrkInclBtw     smallInt;
  declare @BjGid          integer;
  declare @Pernr          integer;

  //call TraceBegin('ControleerMargePerOrderRegel');

  select OrkValNummer, OrkInclBtw into @OrkValNummer, @OrkInclBtw from tabOrderKop where (OrkGid = @OrkGid);

  Set @OrderKorting = 0;
  select IsNull(OerPerc, 0) into @OrderKorting   from tabOrderExtraRegel where (OerOrkGid = @OrkGid) and (OerRegelNr = 0);

  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid, @PerNr);

  select OrrRegelnr,
         ArtCode,
         (OrrAantalBesteldVrrdEenh) Aantal,
          //bepaal regel-verkoopprijs excl. BTW in basisvaluta
         (if (@@BasisValutaNummer = @OrkValNummer) then
            // order is in basisvaluta
            if (@OrkInclBtw = 1) then
              Round((OrrRegelTotaal / ( 100 + (Select IsNull(BtwPercentage,0) from tabBtw where BtwCode = orrBtwCode) ) * 100 ), 2)
            else
              Round(OrrRegelTotaal, 2)
            endif
          else
            // order is in andere valuta --> reken om naar basis
            if (@OrkInclBtw = 1) then
              ValutaOmrekenen(@OrkValNummer, Round((OrrRegelTotaal / ( 100 + (Select IsNull(BtwPercentage,0) from tabBtw where BtwCode = orrBtwCode) ) * 100 ), 2), @@BasisValutaNummer, @BjGid, @Pernr, 2)
            else
              ValutaOmrekenen(@OrkValNummer, Round(OrrRegelTotaal, 2), @@BasisValutaNummer, @BjGid, @Pernr, 2)
            endif
          endif) VerkPrijsExclOrderKort,
         (Round((VerkPrijsExclOrderKort * (100 - @OrderKorting ) / 100), 2)) VerkPrijsInclOrderKort,
          //totale kostprijs van regel
         (if (OrrKostprijs Is null) then
            round((Select IsNull(((if ArtIsPartijAparteKostPrijs = 0 or ArtIsPartijRegistreren = 0 or ArtPartijKostprijsEx is null then artKostprijsEx else ArtPartijKostprijsEx endif) / ArtPrijsPer), 0) From tabArtikel Where ArtGid = OrrArtgid) * Aantal , 2)
          else
            round(OrrKostprijs / OrrPrijsPer * Aantal ,2)
          endif) Kostprijs,
          // marge incl orderkortin
         (if ((@MargeIsPercVanVerkoop = 1) and (VerkPrijsInclOrderKort = 0)) or
             ((@MargeIsPercVanVerkoop = 0) and (Kostprijs = 0)) then
            0
          else
            if (@MargeIsPercVanVerkoop = 1) then
               Round(( VerkPrijsInclOrderKort - Kostprijs ) / Abs(VerkPrijsInclOrderKort) * 100,2)
            else
               Round(( VerkPrijsInclOrderKort - Kostprijs ) / KostPrijs * 100,2)
            endif
          endif) MargeInclOrderkorting,
          // marge excl orderkortin
         (if ((@MargeIsPercVanVerkoop = 1) and (VerkPrijsInclOrderKort = 0)) or
             ((@MargeIsPercVanVerkoop = 0) and (Kostprijs = 0)) then
            0
          else
            if (@MargeIsPercVanVerkoop = 1) then
               Round(( VerkPrijsExclOrderKort - Kostprijs ) / Abs(VerkPrijsExclOrderKort) * 100,2)
            else
               Round(( VerkPrijsExclOrderKort - Kostprijs ) / KostPrijs * 100,2)
            endif
          endif) MargeExclOrderkorting,
         (if (@MargeIsPercVanVerkoop = 1) then
            if (VerkPrijsInclOrderKort = 0) then
              if (KostPrijs <> 0) then
                1
              else
                0
              endif
            else
              if (MargeInclOrderkorting < @MinMargePercentage) then
                1
              else
                0
              endif
            endif
          else
            if (KostPrijs = 0) then
              0
            else
              if (MargeInclOrderkorting < @MinMargePercentage) then
                1
              else
                0
              endif
            endif
          endif) TeLageMarge
  from   tabOrderRegel inner join tabArtikel on (ArtGid = OrrArtGid)
                       left outer join tabArtikelPartij on (ArtPartijArtGid = ArtGid and ArtPartijGid = OrrArtPartijGid)
  where  (OrrRegelSoort in (1,2))
    and  (OrrOrkGid = @OrkGid)
    and  (OrrAantalBesteldVrrdEenh > 0)
    and ((@TestOpMinMarge = 0) or (TeLageMarge = 1))
  order by OrrRegelnr;

  //call TraceEind('ControleerMargePerOrderRegel');

end;


create or replace procedure ControleerVrijeVoorraadPerOrderRegel(in @OrkGid integer,in @AlleenNegatief Smallint)
begin

  //call TraceBegin('ControleerVrijeVoorraadPerOrderRegel');

  Select OrrRegelnr,
         ArtCode,
         ArtAantDecAantallen,
         IsNull(sum(calcMagazijnVoorraad), 0.00)      MagazijnVoorraad,
         IsNull(sum(calcGereserveerdLevering), 0.00)  GereserveerdLevering,
         IsNull(sum(calcGereserveerdBackorder), 0.00) GereserveerdBackOrder,
         IsNull(sum(calcVrijeVoorraad), 0.00)         VrijeVoorraad
  from   tabOrderRegel
         inner join tabArtikel          on (ArtGid = OrrArtGid and ArtHeeftVoorraad <> 0)
         inner join vwVoorraadAantallen on (calcArtGid = ArtGid)
  where  (OrrRegelSoort = 2)
    and  (OrrOrkGid = @OrkGid)
    and  (OrrAantalBesteld - OrrAantalGeleverd > 0)
  group by OrrRegelnr,
           ArtCode,
           ArtAantDecAantallen
  having ((VrijeVoorraad < 0) or (@AlleenNegatief = 0))

  order by OrrRegelnr;

  //call TraceEind('ControleerVrijeVoorraadPerOrderRegel');

end;


create or replace procedure ConversieRecalcValutaKoers()
begin
  //Voor elke koers in de administratie waarvoor een eurokoers is ingevuld *en* waarvoor de eurokoers van de basis is ingevuld
  //berekenen we de koers t.o.v. de basisvaluta
  //call TraceBegin('ConversieRecalcValutaKoers');
  if @@EuroValutaNummer is not null then
    //Update via eurovaluta
    update tabValutaKoers Orig
    set    Koers = ( select ( Basis.KrsKoersTovEuro / Orig.KrsKoersTovEuro * Orig.KrsEenheid / Basis.KrsEenheid )
                     from   tabValutaKoers Basis where  Basis.KrsValNummer=@@BasisValutaNummer and Basis.ValBjGid = Orig.ValBjGid and Basis.ValPerNr = Orig.ValPerNr )
    where  KrsKoersTovEuro is not null;

    //update tabValuta set NaarEuro = 1 where ValNummer in
    //  (select KrsValNummer from tabValutaKoers group by KrsValNummer having count(distinct Koers)=1)

  end if;

  //call TraceEind('ConversieRecalcValutaKoers');

end;


create or replace procedure ConverteerFactuurregelVrijeRubriekenArt(
  in @BatchSize  integer // Bepaalt de grootte van de batch van records die verwerkt moeten worden. De waarde null geeft aan dat alles verwerkt dient te worden.
)
begin
  declare @MergeFrvraGid integer;
  declare @HashedContent integer;
  declare @LoopCounter integer = 0;

  //call TraceBegin('ConverteerFactuurregelVrijeRubriekenArt(' + string (@BatchSize) + ')');

  // Deze tabel maken we aan om select min(frvraGid) over de giga tabel tabFactuurRegelVrijeRubriekArt te voorkomen
  if not exists(select 1 from sys.systable where table_name='tmpFactuurRegelVrijeRubriekArt') then
      create table tmpFactuurRegelVrijeRubriekArt (
        tmpFrVraGid           integer,      // PK van tabFactuurregelVrijeRubrieken
        tmpFrVraHashedContent integer,      // Hash van de overige velden van tabFactuurregelVrijeRubrieken
        tmpFrVraContent       long nvarchar // Ongehashde content van de overige velden van tabFactuurregelVrijeRubrieken
      );

    // Voeg de records die al in de nieuwe situatie zijn aangemaakt toe aan de temp table die we als lookup gaan gebruiken
    insert into tmpFactuurRegelVrijeRubriekArt (tmpFrVraGid, tmpFrVraContent, tmpFrVraHashedContent)
    select
      frvraGid,
      (string(frvraDecimalen, '|', '|', FrvraGrpNaam , '|', FrvraGrpVolgorde, '|', FrvraHint, '|', frvraInhoudChar, '|', frvraInhoudDate, '|',
      frvraInhoudNumeric, '|', frvraInhoudSelectie, '|', frvraInhoudTime, '|', FrvraLabel, '|', frvraLengte, '|', frvraSjabloon, '|', frvraType, '|',
      frvraVeldnaam, '|', FrvraVolgorde)) as frvraContent,
      HexToInt(Hash(frvraContent, 'CRC32')) as frvraHashedContent
  from tabFactuurRegelVrijeRubriekArt
    where
      frvraFrGid is null
  order by
      frvraGid desc;
  end if;

  commit;

  if not exists(select 1 from sys.sysindexes where tname = 'tmpFactuurRegelVrijeRubriekArt' and iname = 'Idx_tmpFrVraHashedContent') then
    create index Idx_tmpFrVraHashedContent on tmpFactuurRegelVrijeRubriekArt (tmpFrVraHashedContent);
  end if;

  for @Cursor as Cursor_FactuurRegelVrijeRubriekArt no scroll cursor for
    select
      frvraGid    as @frvraGid,
      frvraFrGid  as @frvraFrGid,
      (string(frvraDecimalen, '|', '|', FrvraGrpNaam , '|', FrvraGrpVolgorde, '|', FrvraHint, '|', frvraInhoudChar, '|', frvraInhoudDate, '|',
      frvraInhoudNumeric, '|', frvraInhoudSelectie, '|', frvraInhoudTime, '|', FrvraLabel, '|', frvraLengte, '|', frvraSjabloon, '|', frvraType, '|',
      frvraVeldnaam, '|', FrvraVolgorde)) as @frvraContent

    from tabFactuurRegelVrijeRubriekArt
    where
      frvraFrGid is not null // Filter de verwerkte records eruit
  order by
      frvraGid
  for update
  do
    if (@LoopCounter >= @BatchSize and @BatchSize is not null) then
      leave;
    end if;

    set @LoopCounter = @LoopCounter + 1;

    set @HashedContent = HexToInt(Hash(@frvraContent, 'CRC32'));

    // We gaan kijken of we zelf in de lookuptabel zitten
    set @MergeFrvraGid = null;
    // NOTE DG: Let op dubbele hash keys zijn mogelijk, maar ook dubbele key+waarde combinatie a.g.v. nieuwe routine in overnemen vrije rubrieken.
    select first tmpFrVraGid into @MergeFrvraGid from  tmpFactuurRegelVrijeRubriekArt  where tmpFrVraHashedContent = @HashedContent and tmpFrVraContent = @frvraContent;

    if @MergeFrvraGid is null then
      insert into tmpFactuurRegelVrijeRubriekArt (tmpFrVraGid, tmpFrVraHashedContent, tmpFrVraContent) values (@frvraGid, @HashedContent, @frvraContent);
      insert into tabFactuurRegelKoppelVrijeRubriekArt (FrkvrafrGid, FrkvrafrvraGid) values (@frvraFrGid, @frvraGid);
      // Dit record moet behouden blijven: verwijzing naar Factuurregel staat nu in de koppeltabel
      update tabFactuurRegelVrijeRubriekArt set frvraFrGid = null where current of Cursor_FactuurRegelVrijeRubriekArt;
    else
      insert into tabFactuurRegelKoppelVrijeRubriekArt (FrkvrafrGid, FrkvrafrvraGid) values (@frvraFrGid, @MergeFrvraGid);
      // Dit record kan nu weg: koppeltabel verwijst naar een ander, maar gelijkwaardig record
      delete tabFactuurRegelVrijeRubriekArt where current of Cursor_FactuurRegelVrijeRubriekArt;
    end if;

    // Om de 1000 records even committen ( is anders 33% van de tijd hiermee bezig volgens DbProfiler
    if MOD(@LoopCounter, 1000) = 0 then
      commit;
    end if;
  end for;

  // Check of we klaar zijn met de verwerking en zo ja dan drop de tmptable
  if not exists(select 1 from tabFactuurRegelVrijeRubriekArt where frvraFrGid is not null) then
    drop table KingSystem.tmpFactuurRegelVrijeRubriekArt;
  end if;
  //call TraceEind('ConverteerFactuurregelVrijeRubriekenArt(' + string (@BatchSize) + ')');
end;

create or replace procedure CreateStandaardLocatieVoorArtikelMagazijn(in @ArtGid integer, in @MagGid integer, out @LocGid integer)
begin

  set @@ErrorTextProcedure = 'CreateStandaardLocatieVoorArtikelMagazijn > ';
  //call TraceBegin(@@ErrorTextProcedure + '@ArtGid = ' + string(@ArtGid) + ', @MagGid = ' + string(@MagGid));

  set @LocGid = null;
  select ArtMagDefaultLocGid
  into   @LocGid
  from   tabArtikelMagazijn
  where  ArtMagArtGid = @ArtGid and ArtMagMagGid = @MagGid;

  // Deze heeft nog geen default locatie -> aanmaken!
  if @LocGid is null then
    // Lees default locatie van magazijn
    select LocGid
    into   @LocGid
    from   tabLocatie
    where  LocNaam = '(Standaard)' and LocMagGid = @MagGid;
    if @LocGid is null then
      insert into tabLocatie (LocMagGid, LocNaam) values (@MagGid, '(Standaard)');
      set @LocGid = @@Identity;
    end if;
  end if;

  set @@ErrorTextProcedure = 'CreateStandaardLocatieVoorArtikelMagazijn';
  //call TraceEind(@@ErrorTextProcedure + ' > @LocGid = '+string(@LocGid));
end;


create or replace procedure CreateVrijeRubriekenStoredProc(in @VrBestandOms nchar(3), in @VrGroepID integer, in @VrSubGroepId integer)
begin
  //Variabelen om select-statement mee op te bouwen
  declare @VrFieldList         long nvarchar;
  declare @VrResultList        long nvarchar;
  declare @TabelName           long nvarchar;
  declare @VrRecordId          nchar(40);
  declare @StoredProcRecordId  nchar(40);

  declare @VrStoredProcName    nchar(40);
  declare @VrStoredProcContent long nvarchar;  //De totale stored proc komt in deze var
  //Variabelen nodig voor cursor
  declare @VrVeldNaam          nchar(40);
  declare @VrLabel             nchar(40);
  declare @VrTypeString        nchar(40);
  declare @Stmt                nchar(200);

  declare cursor_VR cursor for
    //ACW 14-10-2011: Vervang aanhalingstekens door enkel-kwoot, omdat die aanhalingstekens niet voor mogen komen (velden worden met aanhalingstekens afgebakend)
    select VrveldNaam, replace(replace(VrLabel, char(34), ''''), '\', '_'), VrTypeString(VrType, VrLengte, VrDecimalen)
      from  tabvrijerubrieken
      where vrbestandoms = @VrBestandOms
      and   vrGroepId    = @VrGroepId
      and   vrSubgroepId = @VrSubGroepId
      order by VrVolgorde;

  //call TraceBegin('CreateVrijeRubriekenStoredProc > @VrBestandOms='+@VrBestandOms+ '; @VrGroepID='+string(@VrGroepId) + '; @VrSubGroepId='+string(@VrSubGroepId));


  //De ene is dus het veld uit de db: vrNAW001001RecordID
  //De stored proc id kolom is slechts: vrNAWRecordID.
  //Dat is makkelijk bij het joinen, want daardoor hoef je het fonid niet mee te parsen maar je weet zelf wel
  // welke gegevenssoort je wil joinen!
  set @VrRecordId   = VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);
  set @StoredProcRecordId = 'vr'+@VrBestandOms+'RecordId';

  set @VrFieldList = '';
  set @VrResultList = '';
  open cursor_VR;
  fetch cursor_VR into @VrVeldNaam, @VrLabel, @VrTypeString;
  while (@@sqlstatus = 0) loop
    set @VrFieldList  = @VrFieldList+', '+@VrVeldNaam+' "VR_'+@VrBestandOms+'_'+@VrLabel+'" ';
    set @VrResultList = @VrResultList+', "VR_'+@VrBestandOms+'_'+@VrLabel+'" '+@VrTypeString;
    fetch next cursor_VR into @VrVeldNaam, @VrLabel, @VrTypeString;
  end loop;
  close cursor_VR;

  if @VrFieldList = '' then
    //De stored proc moet altijd iets teruggeven
    set @VrFieldList  = ' null '    + @StoredProcRecordId;
    set @VrResultList = @StoredProcRecordId + ' integer ';
    set @TabelName    = ' Dummy ';
  else
    set @VrFieldList  = @VrRecordID + ' '+ @StoredProcRecordId + @VrFieldList;
    set @VrResultList = @StoredProcRecordId+' integer' + @VrResultList;
    set @TabelName    = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);
  end if;

  set @VrStoredProcName    = 'spSelectVr'+@VrBestandOms;
  //execute Trace 'Nieuwe stored proc opbouwen: '+@VrStoredProcName
  set @VrStoredProcContent = 'create temporary procedure '+@VrStoredProcName +'()\n';
  set @VrStoredProcContent = @VrStoredProcContent+'result('+@VrResultList+')\n';
  set @VrStoredProcContent = @VrStoredProcContent+'begin\n';
  set @VrStoredProcContent = @VrStoredProcContent+'  select '+@VrFieldList+' from '+@TabelName+'\n';
  set @VrStoredProcContent = @VrStoredProcContent+'end;\n';


  //Omdat we niet kunnen testen of de temporary stored procedure bestaat, proberen we m gewoon weg te gooien, en de exception dat de stored proc. evt niet bestaat, vangen we af
  set @Stmt = 'drop procedure '+ @VrStoredProcName;
  begin
    //ACW 14-10-2011 - Errors moeten wel zijn gedeclared!
    declare SQLE_PROCEDURE_NOT_FOUND EXCEPTION FOR SQLSTATE '52W09';
    execute immediate @Stmt
    exception
      when SQLE_PROCEDURE_NOT_FOUND then //;
      when others        then resignal;
  end;

  //call Trace('Nieuwe stored proc toevoegen, lengte @VrStoredProcContent='+String(Length(@VrStoredProcContent)));
  //call Trace(@VrStoredProcContent);
  //Voor debugging handig
  //  delete tmpDebug
  //  insert into tmpDebug (tmpProc) values (@VrStoredProcContent)

  execute immediate @VrStoredProcContent;

  //call TraceEind('CreateVrijeRubriekenStoredProc');

end;


create or replace function CrediteurKredietRuimte(in @NawGid integer, in @BstKopGid integer)
returns numeric(15,2)
begin
  declare @TotaalOpenstaand   numeric(15,2);
  declare @TotaalBestellingen numeric(15,2);
  declare @CredValNummer      integer;
  declare @BjGid              integer;
  declare @Pernr              integer;
  declare @RksGid             integer;
  declare @Kredietlimiet      numeric(15,2);
  declare @KredietRuimte      numeric(15,2);

  set @@ErrorTextProcedure = 'CrediteurKredietRuimte > @NawGid='+string(@NawGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //Kredietlimiet opvragen
  select NawFilKredLimiet, NawFilValNummer, NawFilRksGid into @Kredietlimiet, @CredValNummer, @RksGid
  from   tabNawFile
  where  NawFilNawGid=@NawGid;

  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid, @PerNr);

  //Geen 'eigen' Kredietlimiet -> standaard Kredietlimiet gebruiken
  if isnull(@Kredietlimiet, 0) = 0 then
    select if @@BasisValutaNummer = @CredValNummer then fonKredietlimiet else ValutaOmrekenen( @@BasisValutaNummer, fonKredietlimiet, @CredValNummer, @BjGid, @Pernr, 2) endif
    into   @Kredietlimiet
    from   tabFileOfNaw where  fonID='C';
  end if;
  //call Trace('Alg. KredLimiet='+string(@Kredietlimiet));

  //Openstaande posten
  select sum( if @CredValNummer = OspValNummer then (OspFactuurBedragDefinitief-OspBetaaldBedragDefinitief)+(OspFactuurBedragVoorlopig-OspBetaaldBedragVoorlopig) else ValutaOmrekenen( OspValNummer, (OspFactuurBedragDefinitief-OspBetaaldBedragDefinitief)+(OspFactuurBedragVoorlopig-OspBetaaldBedragVoorlopig), @CredValNummer, @BjGid, @Pernr, 2) endif)
  into   @TotaalOpenstaand
  from   tabOpenstaandePost
  where  OspRksGid = @RksGid and OspBjGid = @BjGid;

  //Openstaande bestellingen erbij tellen
  select sum( if @CredValNummer = BstKopValNummer then calcTotaalValutaIncl else ValutaOmrekenen(BstKopValNummer, calcTotaalValutaIncl, @CredValNummer, @BjGid, @Pernr, 2) endif)
  into   @TotaalBestellingen
  from   tabBestelKop
         inner join vwBestelKopTotalen on (calcBstKopGid = BstKopGid)
  where  BstKopNawGID = @NawGid and ((BstKopIsGoedgekeurd = 1 and BstKopIsVerwerkt = 0) or BstKopGid = @BstKopGid);

  //En het resultaat teruggeven
  set @KredietRuimte = IsNull(@KredietLimiet, 0) - IsNull(@TotaalOpenstaand, 0) - IsNull(@TotaalBestellingen, 0);

  set @@ErrorTextProcedure = 'CrediteurKredietRuimte';
  //call TraceEind (@@ErrorTextProcedure);

  return (@KredietRuimte);
end;


create or replace procedure CreeerMagazijnOntvangstObvBestelregelDetail(in @BstRglGid integer, in @MagOntGid integer, in @AantalNuOntvangen numeric(15,3))
begin
  //LET OP : Indien deze stored proc wijzigt, kijk dan ook of MagazijnOntvangstSpecObvBestelregelDetail aangepast moet worden
  declare @_DefaultLocGid integer = GeefLocatieVoorMagazijnOntvangst(Null, @BstRglGid, Null, @MagOntGid);
  declare @AantalCorrectie      numeric(15,3);
  declare @InsertedMagOntDetGid integer;
  declare @_MagVastDefLocatie                    smallint = 1;
  declare @_MagVastOntvangstRegistrerenOpLocatie smallint = 0;
  declare @_CrossDock_DirecteInkoop              integer = null;

  //call TraceBegin('CreeerMagazijnOntvangstObvBestelregelDetail > ' + '@BstRglGid = ' + string(@BstRglGid));

  //Instellingen tbv wijze van werken met ontvangstlocaties
  select MagVastDefLocatie, MagVastOntvangstRegistrerenOpLocatie
  into @_MagVastDefLocatie, @_MagVastOntvangstRegistrerenOpLocatie
  from tabMagazijnOntvangstenVasteGegevens;

  //bepalen crossdocklocatie directe inkoop van betreffende magazijn
  if (@_MagVastOntvangstRegistrerenOpLocatie = 0) and  /*voorkeurslocatie van artikel*/
     (@_MagVastDefLocatie = 1) /*Default voorkeurslocatie*/ then
    Select MagLocGidVoorkeurDirecteInkoop into @_CrossDock_DirecteInkoop
    from tabMagazijnOntvangsten
         inner join tabMagazijnOntvangstenKop on (MokGid=MagOntMokGid)
         inner join tabMagazijn on (MagGid=MokMagGid)
         inner join tabLocatie on (locGid=MagLocGidVoorkeurDirecteInkoop)
    where (MagontGid=@MagOntGid) and (LocBlokkade = 0);
  end if;

  // ******************
  // *** Variabelen ***
  // ******************
  // @AantalNuOntvangen -> Het aantal dat nu voor deze magazijnontvangstregel is/wordt ontvangen
  // @AantalCorrectie   -> Het aantal dat nu moet worden gecorrigeerd, omdat dat deel van de bestelregel niet meer zal worden ontvangen
  select -MagOntAantalCorrectie into @AantalCorrectie from tabMagazijnOntvangsten where MagOntGid = @MagOntGid;

  // Hier worden detail regels aan magazijnontvangstregel toegevoegd.
  // ********************************
  // *** Stap 1: Aantal ontvangen ***
  // ********************************
  //  Loop door besteldetailregels zolang @AantalOntvangen <> 0
  begin
    declare @MO_DetailAantalNuOntvangen numeric(15,3);
    declare @AantalDezeDetail           numeric(15,3);

    set @MO_DetailAantalNuOntvangen = @AantalNuOntvangen;

    //call trace('Stap 1: @MO_DetailAantalNuOntvangen = '+string(@MO_DetailAantalNuOntvangen));
    for @CursorNTO as Cursor_NogTeOntvangen CURSOR FOR
      // Lijst van detailregels van de bestelregel met het AantalNogTeOntvangen
      // Deze lijst wordt gebruikt om de magazijnontvangstdetailregels 1 op 1 aan te maken
      select   BrdGid @BrdGid,
               brdAantalNogTeOntvangen @DetailNTO,
               brdSoort @BrdSoort
      from     tabBestelRegelDetail
      where    BrdBstRglGid = @BstRglGid
           and brdAantalNogTeOntvangen <> 0
      order by
        /* Teken van ontvangst gelijk aan teken van bestelling -> eerst de 1=verkooporders en dan pas de 0=Magazijn worden verwerkt*/
        if sign(@AantalNuOntvangen) = sign(@DetailNTO) or (@DetailNTO >= 0 and @AantalNuOntvangen >= 0) then brdSoort endif DESC,
        /* Teken van ontvangst ongelijk aan teken van bestelling -> eerst de 0=Magazijn en dan pas de 1=verkooporders worden verwerkt*/
        brdSoort
    FOR READ ONLY
    DO

      // Wat kunnen we nog in deze detailregel opnemen als Ontvangen?
      set @AantalDezeDetail = lesser(@MO_DetailAantalNuOntvangen, @DetailNTO);

      // Detailregel altijd toevoegen, omdat we qua aantal altijd overeen moeten komen met de bestelregel
      insert into tabMagazijnOntvangstenDetail(MagOntDetBrdGid, MagOntDetMagOntGid, MagOntDetAantalCorrectie)
        values(                                @BrdGid,         @MagOntGid,         0);
      set @InsertedMagOntDetGid = @@Identity;

      //LocSerie record toevoegen met @AantalDezeDetail, als die <> 0 is
      if @AantalDezeDetail <> 0 then
        insert into tabMagazijnOntvangstLocatieSerie(MagOntLocMagOntDetGid, MagOntLocAantal,   MagOntLocIsSerieNetAangemaakt, MagOntLocLocGid)
          select                                     @InsertedMagOntDetGid, @AantalDezeDetail, 0,                             (if @BrdSoort=0 then  @_DefaultLocGid else Isnull(@_CrossDock_DirecteInkoop, @_DefaultLocGid) endif);
      end if;

      // En aangeven dat we dit aantal ontvangen hebben verwerkt.
      set @MO_DetailAantalNuOntvangen = @MO_DetailAantalNuOntvangen - @AantalDezeDetail;

    END FOR;
    //call trace('Stap 1: Lus is gestopt. Restant: @MO_DetailAantalNuOntvangen='+string(@MO_DetailAantalNuOntvangen));

    // ********************************************************
    // *** Stap 1b: Er is meer ontvangen dan verwacht       ***
    // *** Daarom de rest wegwerken op soort=Magazijn regel ***
    // ********************************************************
    if @MO_DetailAantalNuOntvangen <> 0 then
      begin
        declare @BrdGid integer;

        // Restant op een detailregel met magazijn zetten of, als die niet bestaat, die detailregel aanmaken
        set @InsertedMagOntDetGid = null;
        select first MagOntDetGid
        into   @InsertedMagOntDetGid
        from   tabMagazijnOntvangstenDetail
               left outer join tabBestelRegelDetail on (BrdGid = MagOntDetbrdGid)
        where  isnull(brdSoort, MagOntDetBrdSoort) = 0 /*Magazijn*/
           and MagOntDetMagOntGid = @MagOntGid;

        if @InsertedMagOntDetGid is null then

          // Regel toevoegen met locatieserie-regels eronder, liefst met koppeling naar eenzelfde magazijnregel in de bestelregeldetails
          set @BrdGid = null;
          select BrdGid
          into   @BrdGid
          from   tabBestelRegelDetail
          where  brdBstRglGid = @BstRglGid
             and brdSoort = 0 /*Magazijn*/;

          //Detailregel toevoegen
          insert into tabMagazijnOntvangstenDetail(MagOntDetBrdGid, MagOntDetMagOntGid, MagOntDetAantalCorrectie)
            values(                                @BrdGid,         @MagOntGid,         0);
          set @InsertedMagOntDetGid = @@Identity;

          //LocatieSerie (met aantal) toevoegen
          insert into tabMagazijnOntvangstLocatieSerie(MagOntLocMagOntDetGid, MagOntLocAantal,             MagOntLocIsSerieNetAangemaakt, MagOntLocLocGid)
            select                                     @InsertedMagOntDetGid, @MO_DetailAantalNuOntvangen, 0,                             @_DefaultLocGid;

        else
          begin
            declare @MagOntLocGid integer;

            // Eerste LocatieSerieregel van de gevonden regel updaten met het resterende aantal ontvangen
            select first MagOntLocGid into @MagOntLocGid
            from tabMagazijnOntvangstLocatieSerie where MagOntLocMagOntDetGid = @InsertedMagOntDetGid;
            if @MagOntLocGid is null then

              // LocatieSerieregel toevoegen
              insert into tabMagazijnOntvangstLocatieSerie(MagOntLocMagOntDetGid, MagOntLocAantal,             MagOntLocIsSerieNetAangemaakt, MagOntLocLocGid)
                select                                     @InsertedMagOntDetGid,        @MO_DetailAantalNuOntvangen, 0,                             @_DefaultLocGid;

            else

              // LocatieSerieregel updaten
              update tabMagazijnOntvangstLocatieSerie
              set    MagOntLocAantal = MagOntLocAantal + @MO_DetailAantalNuOntvangen
              where  MagOntLocGid = @MagOntLocGid;

            end if;
          end;
        end if;
      end;
    end if;
  end;


  //
  // ********************************
  // *** Stap 2: Aantal correctie ***
  // ********************************
  //  Loop door besteldetailregels zolang @Correctie <> 0
  //    Is er een MO.Detailregel aan de bestelregel gekoppeld?
  //    Ja: Pas de MO.Detailregel aan met aantal correctie, ten hoogste van het aantal nog te ontvangen
  //    Nee: Voeg een MO.Detailregel toe met aantal correctie, ten hoogste van het aantal nog te ontvangen van bestelregel
  if @AantalCorrectie <> 0 then
    begin
      declare @AantalCorrectieDezeDetail numeric(15,3);

      //call trace('Stap 2: @AantalCorrectie='+string(@AantalCorrectie));
      LusBestelregelDetailsTbvCorrectie:
      for @CursorCorrectie as CURSOR_Correctie CURSOR FOR
        select   brdGid                  @brdGid,
                 MagOntDetGid            @MagOntDetGid,
                 brdAantalNogTeOntvangen @brdAantalNogTeOntvangen
        from     tabBestelRegelDetail
                 left outer join tabMagazijnOntvangstenDetail on (MagOntDetbrdGid = BrdGid and MagOntDetMagOntGid = @MagOntGid)
        where    brdBstRglGid = @BstRglGid
        order by MagOntDetKoppeling, brdSoort /* Zodat eerst de koppeling 0=magazijn, dan de koppeling=1/besteldetail=magazijn en dan pas verkooporders worden gecorrigeerd*/
      FOR UPDATE
      DO

        // Wat kunnen we nog in deze detailregel opnemen als Ontvangen?
        if @AantalCorrectie < @brdAantalNogTeOntvangen then
          set @AantalCorrectieDezeDetail = -@AantalCorrectie
        else
          set @AantalCorrectieDezeDetail = @brdAantalNogTeOntvangen
        end if;

        if @AantalCorrectieDezeDetail <> 0 then

          if @MagOntDetGid is null then
            // Detailregel in magazijnontvangst bestaat niet, dus alsnog toevoegen met de correctie erin!

            insert into tabMagazijnOntvangstenDetail(MagOntDetBrdGid, MagOntDetMagOntGid, MagOntDetAantalCorrectie)
              values(                                @BrdGid,         @MagOntGid,         -@AantalCorrectieDezeDetail);

          else
            // Detailregel in magazijontvangst bestaat, dus die updaten met het aantal nu te corrigeren

            update tabMagazijnOntvangstenDetail
            set MagOntDetAantalCorrectie = MagOntDetAantalCorrectie - @AantalCorrectieDezeDetail
            where current of CURSOR_Correctie;

          end if;

          // Gedeelte correctie wat nu is verwerkt eraf halen
          set @AantalCorrectie = @AantalCorrectie - @AantalCorrectieDezeDetail;

          // Stukje optimalisatie: Niks meer te corrigeren, dan gewoon stoppen met de lus
          if @AantalCorrectie = 0 then
            Leave LusBestelregelDetailsTbvCorrectie;
          end if;

        end if;
      END FOR;
    end;

    // We kunnen niets overhouden om te corrigeren, anders was het correctieaantal in eerste instantie al fout, dus zijn we gelijk klaar
  end if;

  // Omdat het nu mogelijk is dat er records in tabMagazijnOntvangstenDetail staan die geen tabMagazijnOntvangstLocatieSerie hebben,
  // maken we de tabMagazijnOntvangstLocatieSerie records alsnog aan
  insert into tabMagazijnOntvangstLocatieSerie(MagOntLocMagOntDetGid, MagOntLocAantal, MagOntLocIsSerieNetAangemaakt, MagOntLocLocGid)
    select                                     MagOntDetGid,          0,               0,                             @_DefaultLocGid
    from tabMagazijnOntvangstenDetail
         inner join tabMagazijnOntvangsten on MagOntGid = MagOntDetMagOntGid and MagOntRegelsoort = 2 /*Artikel*/
    where MagOntDetMagOntGid = @MagOntGid
        and not exists(select first 1 from tabMagazijnOntvangstLocatieSerie where MagOntLocMagOntDetGid = MagOntDetGid);

  //call TraceEind('CreeerMagazijnOntvangstObvBestelregelDetail');
end;


create or replace procedure DagboekSaldo(in @BjGid integer, in @DgbGid integer, out @SaldoVoorlopig numeric(15,2),
                                        out @SaldoDefinitief numeric(15,2), out @AantalVoorlopig numeric(15,2),
                                        out @AantalDefinitief numeric(15,2))
begin
  declare @ValNummer integer;

  set @@ErrorTextProcedure = 'DagboekSaldo > @BjGid='+string(@BjGid)+', @DgbGid='+string(@DgbGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select RksValNummer into @ValNummer from tabDagboek inner join tabRekeningSchema on ( RksGid = DgbTegenRksGid ) where DgbGid = @DgbGid;

  select sum( if RekSaldoValnummer = @ValNummer then IsNull(SaldoDebetValutaVoorlopig,0)-IsNull(SaldoCreditValutaVoorlopig,0) else ValutaOmrekenen( RekSaldoValNummer, IsNull(SaldoDebetValutaVoorlopig,0)-IsNull(SaldoCreditValutaVoorlopig,0)    , @ValNummer, @BjGid, RekSaldoPerNr, 2) endif),
         sum( if RekSaldoValnummer = @ValNummer then IsNull(SaldoDebetValutaDefinitief,0)-IsNull(SaldoCreditValutaDefinitief,0) else ValutaOmrekenen( RekSaldoValNummer, IsNull(SaldoDebetValutaDefinitief,0)-IsNull(SaldoCreditValutaDefinitief,0)  , @ValNummer, @BjGid, RekSaldoPerNr, 2) endif),
         sum( IsNull(SaldoDebetAantalVoorlopig,0)-IsNull(SaldoCreditAantalVoorlopig,0)),
         sum( IsNull(SaldoDebetAantalDefinitief,0)-IsNull(SaldoCreditAantalDefinitief,0))
         into @SaldoVoorlopig, @SaldoDefinitief, @AantalVoorlopig, @AantalDefinitief
  from   tabRekeningsaldo, tabDagboek
  where  RekSaldoBjGid=@BjGid and DgbGid=@DgbGid and DgbTegenRksGid=RekSaldoRksGid;

  set @@ErrorTextProcedure = 'DagboekSaldo > ValNummer='+string(@ValNummer)+'; @SaldoVoorlopig='+string(@SaldoVoorlopig)+', @SaldoDefinitief='+string(@SaldoDefinitief)+' @AantalVoorlopig='+string(@AantalVoorlopig)+', @AantalDefinitief='+string(@AantalDefinitief);
  //call TraceEind(@@ErrorTextProcedure);

end;


//------- Vul de dagnamen met defaults
create or replace procedure DagenDefaultVullen(in @TaalGid integer, in @Default smallint)
begin
  declare @Teller smallint;
  declare @DagLang nchar(15);
  declare @DagKort nchar(5);

  set @@ErrorTextProcedure = 'DagenDefaultVullen > @TaalGid='+string(@TaalGid)+', @Default='+string(@Default);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Teller=1;
  while @Teller<=7 loop
    if @Default = 0 then //Nederlands
      //                        1234567890123456789012345678901234567890123456789012345678901234567890
      set @DagLang=Trim(substr('zondag    maandag   dinsdag   woensdag  donderdag vrijdag   zaterdag  ',(@Teller-1)*10+1,10));
      set @DagKort=Trim(substr('zon       maa       din       woe       don       vri       zat       ',(@Teller-1)*10+1,10));
    else
      if @Default = 1 then //Engels
        //                        1234567890123456789012345678901234567890123456789012345678901234567890
        set @DagLang=Trim(substr('sunday    monday    tuesday   wednesday thursday  friday    saturday  ',(@Teller-1)*10+1,10));
        set @DagKort=Trim(substr('sun       mon       tue       wed       thu       fri       sat       ',(@Teller-1)*10+1,10));
      else
        if @Default = 2 then //Duits
          //                        1234567890123456789012345678901234567890123456789012345678901234567890
          set @DagLang=Trim(substr('sonntag   montag    dienstag  mittwoch  donnerstagfreitag   samstag   ',(@Teller-1)*10+1,10));
          set @DagKort=Trim(substr('son       mon       die       mit       don       fre       sam       ',(@Teller-1)*10+1,10));
        else
          if @Default = 3 then //Frans
            //                        1234567890123456789012345678901234567890123456789012345678901234567890
            set @DagLang=Trim(substr('dimanche  lundi     mardi     mercredi  jeudi     vendredi  samedi    ',(@Teller-1)*10+1,10));
            set @DagKort=Trim(substr('dim       lun       mar       mer       jeu       ven       sam       ',(@Teller-1)*10+1,10));
          end if
        end if
      end if
    end if;
    update tabDagNaam set DagLang = @DagLang,DagKort = @DagKort where DagTaalGid = @TaalGid and DagId = @Teller;
    set @Teller=@Teller+1
  end loop;

  set @@ErrorTextProcedure = 'DagenDefaultVullen > @Daglang='+@Daglang+', @DagKort='+@DagKort;
  //call TraceBegin(@@ErrorTextProcedure);

end;


create or replace procedure DatabaseInit()
begin
  call sp_login_environment;   //Originele proc die ASA aanriep

  create or replace variable @@TraceTime          timestamp;
  create or replace variable @@Inspring           integer;       set @@Inspring           = 0;
  create or replace variable @@ErrorTextProcedure long nvarchar; set @@ErrorTextProcedure = 'DatabaseInit >';
  create or replace variable @@ErrorTextTrigger   long nvarchar; set @@ErrorTextTrigger   = '';

  if exists(select first 1 from sysprocedure where proc_name = 'CreateDynamicTriggersVars') then
    call CreateDynamicTriggersVars();
  end if;

  call CreateGlobalVariables;

  // Features in variablenames
  create or replace variable @@UseMaterializeViews                           smallint = 1; // Indien 0 dan worden er geen materialized views aangemaakt

  create or replace variable @@AllowChangingOspValuta                        smallint;
  create or replace variable @@AllowInsert                                   smallint;      set @@AllowInsert = 0;
  create or replace variable @@AsciiJournaalLineNumber                       integer;
  create or replace variable @@BasisValutaCode                               nchar(3);
  create or replace variable @@BasisValutaNummer                             integer;       select ValNummer, ValCode into @@BasisValutaNummer, @@BasisValutaCode from tabValuta where IsBasisValuta<>0;
  create or replace variable @@Banktransacties_LogVerboseBits                integer;       select Contents into @@Banktransacties_LogVerboseBits  from tabRegistry where RegKey = 'BANKTRANSACTIESVERWERKEN_LOGLEVEL'; if @@Banktransacties_LogVerboseBits is null then set @@Banktransacties_LogVerboseBits = 113; endif;
  create or replace variable @@Banktransacties_LastUnloadLog                 datetime;      set @@Banktransacties_LastUnloadLog = now();
  create or replace variable @@EuroValutaCode                                nchar(3);
  create or replace variable @@EuroValutaNummer                              integer;       select ValNummer, ValCode into @@EuroValutaNummer,  @@EuroValutaCode  from tabValuta where IsEuro<>0;
  create or replace variable @@BlockWebtriggers                              smallint;      set @@BlockWebtriggers = 0;
  create or replace variable @@BufMagOntDetGid                               integer;
  create or replace variable @@FiredByTriggerArtikel                         smallint;      set @@FiredByTriggerArtikel                         = 0;
  create or replace variable @@FiredByTriggerBalanscodeDetail                smallint;      set @@FiredByTriggerBalanscodeDetail                = 0;
  create or replace variable @@FiredByTriggerBoekingsgang                    smallint;      set @@FiredByTriggerBoekingsgang                    = 0;
  create or replace variable @@FiredByTriggerBoekjaar                        smallint;      set @@FiredByTriggerBoekjaar                        = 0;
  create or replace variable @@FiredByTriggerDeleteOrderKop                  smallint;      set @@FiredByTriggerDeleteOrderKop                  = 0;
  create or replace variable @@FiredByTriggerDeleteBestelregelDetail         smallint;      set @@FiredByTriggerDeleteBestelregelDetail         = 0;
  create or replace variable @@FiredByTriggerJournaalpost                    smallint;      set @@FiredByTriggerJournaalpost                    = 0;
  create or replace variable @@FiredByTriggerJournaalregel                   smallint;      set @@FiredByTriggerJournaalregel                   = 0;
  create or replace variable @@FiredByTriggerNawFile                         smallint;      set @@FiredByTriggerNawFile                         = 0;
  create or replace variable @@FiredByTriggerNawRekening                     smallint;      set @@FiredByTriggerNawRekening                     = 0;
  create or replace variable @@FiredByTriggerOrderKop                        smallint;      set @@FiredByTriggerOrderKop                        = 0;
  create or replace variable @@FiredByTriggerOrderRegel                      smallint;      set @@FiredByTriggerOrderRegel                      = 0;
  create or replace variable @@FiredByTriggerOrderRegelLocatie               smallint;      set @@FiredByTriggerOrderRegelLocatie               = 0;
  create or replace variable @@FiredByTriggerProjectboomUpdate               smallint;      set @@FiredByTriggerProjectboomUpdate               = 0;
  create or replace variable @@FiredByTriggerProjectFactuurVoorstelKopDelete smallint;      set @@FiredByTriggerProjectFactuurVoorstelKopDelete = 0;
  create or replace variable @@FiredByTriggerVoorraadMutatieLocatie          smallint;      set @@FiredByTriggerVoorraadMutatieLocatie          = 0;
  create or replace variable @@GebruikerNaam                                 nchar(40);
  create or replace variable @@Gebruikercode                                 nchar(20);     if left(User, 5) = 'KING_' then set @@GebruikerCode = substr(User, 6) else set @@GebruikerCode = User end if;
  create or replace variable @@GebruikerGid                                  integer;       select GebruikerGid into @@GebruikerGid from tabGebruiker where NaamGebruiker = @@Gebruikercode;
  create or replace variable @@GeenKoersCorrectie                            smallint;
  create or replace variable @@HerstelVoorraadAantallenInOrders              smallint;
  create or replace variable @@IgnoreProgressAdd                             smallint;      set @@IgnoreProgressAdd = 0;
  create or replace variable @@InFacturering                                 smallint;      set @@InFacturering     = 0; // Wordt ook gebruikt om aan te geven dat bijv. orders niet op IsGewijzigdNaAfdruk wordt gezet binnen facturering en levering
  create or replace variable @@InsertedBjGid                                 integer;
  create or replace variable @@ImportLogLevel                                smallint;      select Contents into @@ImportLogLevel from tabRegistry where RegKey = 'IMPORTLOG_LEVEL';
  create or replace variable @@JournaalVolgNummersNietVerlagen               smallint;      set @@JournaalVolgNummersNietVerlagen = 0;
  create or replace variable @@Konversie                                     integer;       set @@Konversie = 0;
  create or replace variable @@KostprijsWijzigenOokMetVoorraad               integer;       set @@KostprijsWijzigenOokMetVoorraad = 0;
  create or replace variable @@LocatieControleOverslaan                      smallint;      set @@LocatieControleOverslaan = 0;
  create or replace variable @@LogDetail                                     long nvarchar; set @@LogDetail = '';
  create or replace variable @@LoginTimeEx                                   timestamp;     set @@LoginTimeEx        = now();
  create or replace variable @@LoginTime                                     timestamp;     set @@LoginTime          = CAST( DATEFORMAT(@@LoginTimeEx, 'yyyy/mm/dd hh:nn:ss.sss' )  AS TIMESTAMP); // Now afronden op duizendsten, Dekphi kan niet verder
  create or replace variable @@Machinename                                   nchar(20);     set @@Machinename        = '';
  create or replace variable @@MutLogAppName                                 nchar(100);    set @@MutLogAppName      = '';  // Tbv mutatielog
  create or replace variable @@MutLogGebruikerCode                           nchar(20);     set @@MutLogGebruikerCode= '';  // Tbv mutatielog
  create or replace variable @@MutLogMachinename                             nchar(20);     set @@MutLogMachinename  = '';  // Tbv mutatielog
  create or replace variable @@MagOntWordVerwerkt                            smallint;      set @@MagOntWordVerwerkt = 0;
  create or replace variable @@ModuleCodes                                   long nvarchar; select Contents into @@ModuleCodes    from tabRegistry where RegKey = 'LAATSTE_INLOGMODULES';
  create or replace variable @@LicentieNummer                                nchar(10);     select Contents into @@LicentieNummer from tabRegistry where RegKey = 'LICENTIENUMMER';
  create or replace variable @@OldOrkGoedGekeurd                             smallint;
  create or replace variable @@OldOrkVrijVoorLevering                        smallint;
  create or replace variable @@OverruleOfferteversieBerekenTotalen           smallint;      set @@OverruleOfferteversieBerekenTotalen = 0;
  create or replace variable @@OverRuleCalcOrderTotalen                      smallint;      set @@OverRuleCalcOrderTotalen            = 0;
  create or replace variable @@OverRuleLock                                  smallint;      set @@OverRuleLock                        = 0;
  create or replace variable @@OverRuleOrderKopStatusWijziging               smallint;      set @@OverRuleOrderKopStatusWijziging     = 0;
  create or replace variable @@OverruleOrderregelLocatieAanvullen            smallint       = 0; //0 = niet overrulen, 1 = overrule, NIET aanvullen, -1 = overrule, ALTIJD aanvullen
  create or replace variable @@OverruleUserRights                            smallint       = (if @@GebruikerCode in ('KingGatewayUser', 'KingWebservice') then 1 else 0 endif); //Overrule rights voor speciale users
  create or replace variable @@ParamLongVarChar                              long nvarchar;
  create or replace variable @@PerNr                                         integer;
  create or replace variable @@TijdelijkeKoersen                             smallint;      set @@TijdelijkeKoersen            = 0;
  create or replace variable @@UpdateDuplicates                              smallint;      set @@UpdateDuplicates             = 0;
  create or replace variable @@Verwerkingsdatum                              date;          set @@Verwerkingsdatum             = date(now());
  create or replace variable @@VoorraadMutatieChangeAllowed                  integer;       set @@VoorraadMutatieChangeAllowed = 0;
  create or replace variable @@QuadPakGid                                    integer;
  create or replace variable @@QuadGesprekGid                                integer;
  create or replace variable @@QuadLicGid                                    integer;
  create or replace variable @@QuadLicOptGid                                 integer;
  create or replace variable @@QuadOptGid                                    integer;
  create or replace variable @@QuadPakVersieGid                              integer;
  create or replace variable @@QuadUitlGid                                   integer;
  create or replace variable @@QuadOptions                                   nchar(40);     set @@QuadOptions = '';
  create or replace variable @@QLTimeUnits                                   integer;
  create or replace variable @@PadErcLog                                     nchar(150);
  create or replace variable @@DeletePartijDoorDeleteSerienummers            smallint;      set @@DeletePartijDoorDeleteSerienummers = 0;
  create or replace variable @@VrttGid_Admin                                 integer;
  create or replace variable @@VrttGid_Gebruiker                             integer;
  create or replace variable @@VrttGid_Nederlands                            integer;       // hebben we nodig in de Raise.sp

  //ACW t.b.v. controleren of insert in tabNaw netjes via procedure NawInsert.sp wordt uitgevoerd
  create or replace variable @@FiredByProcNawInsert                          smallint;      set @@FiredByProcNawInsert = 0;

  call ModuleActiveResultCachen;

  //Iedere database heeft een Guid (unieke id). Als database nog geen nummer heeft of is hernoemd, dan krijgt de db een Guid toegewezen
  if left((select Contents from tabRegistry where RegKey = 'Database_GUID'), 8) <> left((select(db_property('Name')))+space(8),8) then
    update tabRegistry set Contents = (select Upper(left(db_property('Name')+space(8), 8)) + UuidToStr(NewId())) where RegKey = 'Database_GUID'
  end if;

  //@@PerNr zetten
  begin
    declare @tmpBjGid integer;
    call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @TmpBjGid, @@PerNr);
  end;

  // taalgids zetten
  select first VrttGid into @@VrttGid_Admin      from tabVertaal_Talen where VrttActieveAdministratieTaal = 1;
  select first VrttGid into @@VrttGid_Nederlands from tabVertaal_Talen where VrttCode = 'NL';

  if @@VrttGid_Admin is null then
    set @@VrttGid_Admin = @@VrttGid_Nederlands;
  end if;

  set @@VrttGid_Gebruiker = @@VrttGid_Admin;

  //TG/MV/RVL 05-03-2014: aanroepen van de placeholder voor maatwerkvariabelen e.d.
  call Maatwerk_DatabaseInit;

  call DatabaseInitValidateMirroring;

  set @@ErrorTextProcedure = 'DatabaseInit';
end;


create or replace procedure DatabaseInitValidateMirroring()
begin
  declare @MirrorMode nchar(20);
  set @@ErrorTextProcedure = '->DatabaseInitValidateMirroring';
  // Controleer of er mirror-eigenschappen zijn

  select db_property('mirrormode') into @MirrorMode;

  if exists(select first 1 from sysmirrorserver) and (@MirrorMode is not null) then
    // Ja, is met mirror. Is dan de optie wel beschikbaar?
    if IsModuleActive('sm' /*Sybase replication, mirroring*/) = 0 then
      // OEPS! Geen optie beschikbaar
      //Zijn we aan een update bezig?
      if exists(select first 1 from tabregistry where regkey='special_admin' and contents = '') then
        // Geen update
        if (select count(*) from sa_conn_info() tabConn inner join sa_db_list(-1) tabDb on tabConn.DBNumber = tabDb.Number) > 2 then
          // Alleen melding bij 3e en meer connecties (Stand alone in mirror staan we dus toe, al is dat eigenlijk onzin)
          call Raise(20694); //(20694) Deze licentie is niet geschikt om een mirrored database te openen!
        end if;
      end if;
    end if;
  end if;

  set @@ErrorTextProcedure = '<-DatabaseInitValidateMirroring';
end;


//---------------------------------------------------------------------------
//----------------------------DataRechtenboomChecken-------------------------
//---------------------------------------------------------------------------
//Procedure die rechtenboom controleerd na elke update, JV 18 jan 2005
//Dit voor alle gebruikers
//Tijdsduur bij 47 gebruikers, 428 rechten, 206 rapsoorten, 13 importsoorten en 33 expsoorten en als doorlopen alle rechten nodig is: 5 seconden
//Door inserten nieuwe rechten of rap/imp/exp soorten of updates(andere parent) in die tabellen kan de volgende situatie onstaan:
//Een (nieuw) recht is aan, terwijl de parent van dat recht, of de hele tak uit is voor een bepaalde gebruiker
//Daarom per gebruiker:
//-evt. rechtcode uitzetten als: rechtcode nog aanstaat maar parent wel uit is
//-evt. rechten van rapportsoorten uitzetten(als parentrechtcode uit), daardoor gaan via triggers ook de layouts mee
//-evt. rechten van importsoorten  uitzetten(als parentrechtcode uit), daardoor gaan via triggers ook de layouts mee
//-evt. rechten van exportsoorten  uitzetten(als parentrechtcode uit), daardoor gaan via triggers ook de layouts mee
//
//Andere oplossing zou zijn om in triggers van tabellen akties uit te voeren
//probleem hierbij is dat de volgorde van inserten nieuwe rechten door DBdelta nu onbepaald is
//daardoor zouden childs eerder geinsert kunnen worden dan de parents
//-------------------------------------------------------------------------------------------------------------------
create or replace procedure DataRechtenboomChecken()
begin
  declare @RechtGebruiksRechtCode     nchar(4);

  set @@ErrorTextProcedure = 'DataRechtenboomChecken';
  //call TraceBegin(@@ErrorTextProcedure);

  //Records met waarde 1 verwijderen(dan is recht aan, dus kan record verwijderd worden, zodat we verderop alleen met inserts kunnen werken:
  delete tabrechtpergebruiker where RechtGebrHeeftRecht=1;

  //rechtencodes die niet bestaan in tabrecht weggooien??

  //loop met alle gebruikers gidjes, waarvan er rechten uitgezet waren:
  FOR  GebruikersForLoop_Naampje AS GebruikersCursor_Naampje CURSOR FOR
    SELECT DISTINCT RechtGebrGebruikerGid @GebruikerGid  FROM  tabRechtPerGebruiker WHERE RechtGebrHeeftRecht=0
  FOR READ ONLY
  DO

    begin//evt. rechten uitzetten
      //Zoek 1e recht waarvan de data niet klopt
      set @RechtGebruiksRechtCode = '';
      select first IsNull(RechtGebruiksRechtCode,'') into @RechtGebruiksRechtCode
      from   tabRecht
      where      exists(select 1 from tabRechtPerGebruiker where RechtGebrGebruikerGid = @GebruikerGid and RechtGebrHeeftRecht = 0 and RechtGebrGebruikersRechtCode = RechtGebruiksParentRechtCode)//parentrechtcode is dus uit
             and
             not exists(select 1 from tabRechtPerGebruiker where RechtGebrGebruikerGid = @GebruikerGid and RechtGebrHeeftRecht = 0 and RechtGebrGebruikersRechtCode = RechtGebruiksRechtCode)//rechtcode zelf is dus aan
      order by RechtVolgorde;
      //loop die steeds recht uit zet en weer eerst volgende recht zoekt waarvan de data niet ok is:
      //door in juiste volgorde aflopen werkt het uitzetten van een recht door op de daarna komende childs etc.
      while @RechtGebruiksRechtCode <> '' loop
        //Data van dit recht aanpassen
        insert into tabRechtPerGebruiker (RechtGebrGebruikerGid,RechtGebrGebruikersRechtCode,RechtGebrHeeftRecht)
        values(@GebruikerGid, @RechtGebruiksRechtCode, 0);
        //Zoek weer 1e recht waarvan de data niet klopt
        set @RechtGebruiksRechtCode = '';//als select first niets vindt, dan blijft oude waarde in @RechtGebruiksRechtCode
        select first IsNull(RechtGebruiksRechtCode,'') into @RechtGebruiksRechtCode
        from   tabRecht
        where      exists(select 1 from tabRechtPerGebruiker where RechtGebrGebruikerGid = @GebruikerGid and RechtGebrHeeftRecht = 0 and RechtGebrGebruikersRechtCode = RechtGebruiksParentRechtCode)//parentrechtcode is dus uit
               and
               not exists(select 1 from tabRechtPerGebruiker where RechtGebrGebruikerGid = @GebruikerGid and RechtGebrHeeftRecht = 0 and RechtGebrGebruikersRechtCode = RechtGebruiksRechtCode)//rechtcode zelf is dus aan
        order by RechtVolgorde;
      end loop;
    end;//evt. rechten uitzetten

    begin//evt rapsoorten uitzetten
      //loop met alle soorten aflopen en kijken of de parent uit is en recht zelf aan is(voor uitvoeren en/of wijzigen):
      FOR  RapSoortenForLoop_Naampje AS RapSoortenCursor_Naampje CURSOR FOR
        select rasRapSoortID @RapSoortId, rasParentAfdrukRecht @ParentUitvoerRecht, rasParentLayoutsWijzigRecht @ParentWijzigRecht
        from   tabRapportSoort
        where     (    exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode=rasParentAfdrukRecht        and      RechtGebrHeeftRecht = 0) and
                   not exists(select 1 from tabRechtRapSoortPerGebr where RechtRapSGebrGebruikerGid = @GebruikerGid and RechtRapSGebrRapSoortID     =rasRapSoortID               and RechtRapSGebrAfdrukRecht = 0)
                  )
                  or
                  (    exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode=rasParentLayoutsWijzigRecht and      RechtGebrHeeftRecht = 0) and
                   not exists(select 1 from tabRechtRapSoortPerGebr where RechtRapSGebrGebruikerGid = @GebruikerGid and RechtRapSGebrRapSoortID     =rasRapSoortID               and RechtRapSGebrWijzigRecht = 0)
                  )
      FOR READ ONLY
      DO
        //uitvoerrecht(afdrukken/importeren/exporteren)
        if      exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode=@ParentUitvoerRecht  and      RechtGebrHeeftRecht = 0)//parentrechtcode is dus uit
            and
            not exists(select 1 from tabRechtRapSoortPerGebr where RechtRapSGebrGebruikerGid = @GebruikerGid and RechtRapSGebrRapSoortID     =@RapSoortID          and RechtRapSGebrAfdrukRecht = 0)//rechtcode zelf is dus aan
        then
          if exists(select 1 from tabRechtRapSoortPerGebr where RechtRapSGebrGebruikerGid = @GebruikerGid and RechtRapSGebrRapSoortId = @RapSoortId) then
            update tabRechtRapSoortPerGebr set RechtRapSGebrAfdrukRecht = 0 where RechtRapSGebrGebruikerGid = @GebruikerGid and RechtRapSGebrRapSoortId = @RapSoortId;
          else
            insert into tabRechtRapSoortPerGebr(RechtRapSGebrGebruikerGid, RechtRapSGebrRapSoortId, RechtRapSGebrAfdrukRecht) values (@GebruikerGid, @RapSoortId, 0);
          end if;
        end if;
        //wijzigrecht
        if      exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode=@ParentWijzigRecht   and      RechtGebrHeeftRecht = 0)//parentrechtcode is dus uit
            and
            not exists(select 1 from tabRechtRapSoortPerGebr where RechtRapSGebrGebruikerGid = @GebruikerGid and RechtRapSGebrRapSoortID     =@RapSoortID          and RechtRapSGebrWijzigRecht = 0)//rechtcode zelf is dus aan
        then
          if exists(select 1 from tabRechtRapSoortPerGebr where RechtRapSGebrGebruikerGid = @GebruikerGid and RechtRapSGebrRapSoortId = @RapSoortId) then
            update tabRechtRapSoortPerGebr set RechtRapSGebrWijzigRecht = 0 where RechtRapSGebrGebruikerGid = @GebruikerGid and RechtRapSGebrRapSoortId = @RapSoortId;
          else
            insert into tabRechtRapSoortPerGebr(RechtRapSGebrGebruikerGid, RechtRapSGebrRapSoortId, RechtRapSGebrWijzigRecht) values (@GebruikerGid, @RapSoortId, 0);
          end if;
        end if;
      END FOR;
    end;//evt rapsoorten uitzetten

    begin//evt Impsoorten uitzetten
      //loop met alle soorten aflopen en kijken of de parent uit is en recht zelf aan is(voor uitvoeren en/of wijzigen):
      FOR  ImpSoortenForLoop_Naampje AS ImpSoortenCursor_Naampje CURSOR FOR
        select ImpSoortGid @ImpSoortId, ImpSoortParentImportRecht @ParentUitvoerRecht, ImpSoortParentLayoutsWijzigRecht @ParentWijzigRecht
        from   tabImportSoort
        where     (    exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode =ImpSoortParentImportRecht        and      RechtGebrHeeftRecht = 0) and
                   not exists(select 1 from tabRechtImpSoortPerGebr where RechtImpSGebrGebruikerGid = @GebruikerGid and RechtImpSGebrImpSoortGid     =ImpSoortGid                      and RechtImpSGebrImportRecht = 0)
                  )
                  or
                  (    exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode =ImpSoortParentLayoutsWijzigRecht and      RechtGebrHeeftRecht = 0) and
                   not exists(select 1 from tabRechtImpSoortPerGebr where RechtImpSGebrGebruikerGid = @GebruikerGid and RechtImpSGebrImpSoortGid     =ImpSoortGid                      and RechtImpSGebrWijzigRecht = 0)
                  )
      FOR READ ONLY
      DO
        //uitvoerrecht(afdrukken/importeren/exporteren)
        if      exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode=@ParentUitvoerRecht  and      RechtGebrHeeftRecht = 0)//parentrechtcode is dus uit
            and
            not exists(select 1 from tabRechtImpSoortPerGebr where RechtImpSGebrGebruikerGid = @GebruikerGid and RechtImpSGebrImpSoortGid    =@ImpSoortID          and RechtImpSGebrImportRecht = 0)//rechtcode zelf is dus aan
        then
          if exists(select 1 from tabRechtImpSoortPerGebr where RechtImpSGebrGebruikerGid = @GebruikerGid and RechtImpSGebrImpSoortGid = @ImpSoortId) then
            update tabRechtImpSoortPerGebr set RechtImpSGebrImportRecht = 0 where RechtImpSGebrGebruikerGid = @GebruikerGid and RechtImpSGebrImpSoortGid = @ImpSoortId;
          else
            insert into tabRechtImpSoortPerGebr(RechtImpSGebrGebruikerGid, RechtImpSGebrImpSoortGid, RechtImpSGebrImportRecht) values (@GebruikerGid, @ImpSoortId, 0);
          end if;
        end if;
        //wijzigrecht
        if      exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode=@ParentWijzigRecht   and      RechtGebrHeeftRecht = 0)//parentrechtcode is dus uit
            and
            not exists(select 1 from tabRechtImpSoortPerGebr where RechtImpSGebrGebruikerGid = @GebruikerGid and RechtImpSGebrImpSoortGid    =@ImpSoortID          and RechtImpSGebrWijzigRecht = 0)//rechtcode zelf is dus aan
        then
          if exists(select 1 from tabRechtImpSoortPerGebr where RechtImpSGebrGebruikerGid = @GebruikerGid and RechtImpSGebrImpSoortGid = @ImpSoortId) then
            update tabRechtImpSoortPerGebr set RechtImpSGebrWijzigRecht = 0 where RechtImpSGebrGebruikerGid = @GebruikerGid and RechtImpSGebrImpSoortGid = @ImpSoortId;
          else
            insert into tabRechtImpSoortPerGebr(RechtImpSGebrGebruikerGid, RechtImpSGebrImpSoortGid, RechtImpSGebrWijzigRecht) values (@GebruikerGid, @ImpSoortId, 0);
          end if;
        end if;
      END FOR;
    end;//evt Impsoorten uitzetten

    begin//evt Expsoorten uitzetten
      //loop met alle soorten aflopen en kijken of de parent uit is en recht zelf aan is(voor uitvoeren en/of wijzigen):
      FOR  ExpSoortenForLoop_Naampje AS ExpSoortenCursor_Naampje CURSOR FOR
        select ExpSoortGid @ExpSoortId, ExpSoortParentExportRecht @ParentUitvoerRecht, ExpSoortParentLayoutsWijzigRecht @ParentWijzigRecht
        from   tabExportSoort
        where     (    exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode =ExpSoortParentExportRecht        and      RechtGebrHeeftRecht = 0) and
                   not exists(select 1 from tabRechtExpSoortPerGebr where RechtExpSGebrGebruikerGid = @GebruikerGid and RechtExpSGebrExpSoortGid     =ExpSoortGid                      and RechtExpSGebrExportRecht = 0)
                  )
                  or
                  (    exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode =ExpSoortParentLayoutsWijzigRecht and      RechtGebrHeeftRecht = 0) and
                   not exists(select 1 from tabRechtExpSoortPerGebr where RechtExpSGebrGebruikerGid = @GebruikerGid and RechtExpSGebrExpSoortGid     =ExpSoortGid                      and RechtExpSGebrWijzigRecht = 0)
                  )
      FOR READ ONLY
      DO
        //uitvoerrecht(afdrukken/importeren/exporteren)
        if      exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode=@ParentUitvoerRecht  and      RechtGebrHeeftRecht = 0)//parentrechtcode is dus uit
            and
            not exists(select 1 from tabRechtExpSoortPerGebr where RechtExpSGebrGebruikerGid = @GebruikerGid and RechtExpSGebrExpSoortGid    =@ExpSoortID          and RechtExpSGebrExportRecht = 0)//rechtcode zelf is dus aan
        then
          if exists(select 1 from tabRechtExpSoortPerGebr where RechtExpSGebrGebruikerGid = @GebruikerGid and RechtExpSGebrExpSoortGid = @ExpSoortId) then
            update tabRechtExpSoortPerGebr set RechtExpSGebrExportRecht = 0 where RechtExpSGebrGebruikerGid = @GebruikerGid and RechtExpSGebrExpSoortGid = @ExpSoortId;
          else
            insert into tabRechtExpSoortPerGebr(RechtExpSGebrGebruikerGid, RechtExpSGebrExpSoortGid, RechtExpSGebrExportRecht) values (@GebruikerGid, @ExpSoortId, 0);
          end if;
        end if;
        //wijzigrecht
        if      exists(select 1 from tabRechtPerGebruiker    where     RechtGebrGebruikerGid = @GebruikerGid and RechtGebrGebruikersRechtCode=@ParentWijzigRecht   and      RechtGebrHeeftRecht = 0)//parentrechtcode is dus uit
            and
            not exists(select 1 from tabRechtExpSoortPerGebr where RechtExpSGebrGebruikerGid = @GebruikerGid and RechtExpSGebrExpSoortGid    =@ExpSoortID          and RechtExpSGebrWijzigRecht = 0)//rechtcode zelf is dus aan
        then
          if exists(select 1 from tabRechtExpSoortPerGebr where RechtExpSGebrGebruikerGid = @GebruikerGid and RechtExpSGebrExpSoortGid = @ExpSoortId) then
            update tabRechtExpSoortPerGebr set RechtExpSGebrWijzigRecht = 0 where RechtExpSGebrGebruikerGid = @GebruikerGid and RechtExpSGebrExpSoortGid = @ExpSoortId;
          else
            insert into tabRechtExpSoortPerGebr(RechtExpSGebrGebruikerGid, RechtExpSGebrExpSoortGid, RechtExpSGebrWijzigRecht) values (@GebruikerGid, @ExpSoortId, 0);
          end if;
        end if;
      END FOR;
    end;//evt Expsoorten uitzetten

  END FOR;

  set @@ErrorTextProcedure = 'DataRechtenboomChecken';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function DateTimeConversieVoorWebServices(in @DatumTijd datetime, in @WaardeVeldInDatabase datetime)
returns datetime
begin

  if (@DatumTijd is null) then  //Gebruiker wil veld in de database ongemoeid laten
    return @WaardeVeldInDatabase
  elseif date(@DatumTijd) = '1899-01-01' then  //Gebruiker wil de waarde in de database leeg maken
    return null
  else
    return @DatumTijd
  end if;

end;

//-------  Formateer de datum naar een opgegeven formaat
create or replace procedure DatumFormat(in @Datum date, in @DatumMasker nchar(40), in @TaalGid integer, inout @FormatDate nchar(80))
begin
  declare @teller integer;
  declare @naam nchar(20);
  declare @week integer;
  declare @karakter nchar(1);
  declare @aantal integer;
  declare @hoofdletters integer;

  set @@ErrorTextProcedure = 'DatumFormat > @Datum='+string(@Datum)+', @DatumMasker='+@DatumMasker+', @TaalGid='+string(@TaalGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @teller=1;
  set @FormatDate='';
  while @teller <= length(@DatumMasker) loop
    set @hoofdletters=0;
    set @aantal=0;
    set @naam='';
    set @karakter=substr(@DatumMasker,@teller,1);
    if ucase(@karakter) in('@','D','M','W','J') then
      if ucase(@karakter) = '@' then
        set @FormatDate=@FormatDate+substr(@DatumMasker,@teller+1,1);
        set @teller=@teller+2
      end if;
      if ucase(@karakter) = 'D' then
        while substr(@DatumMasker,@teller,1) = 'd' and @aantal < 4 loop
          if ascii(substr(@DatumMasker,@teller,1)) = 68 then
            set @hoofdletters=@hoofdletters+1
          end if;
          set @aantal=@aantal+1;
          set @teller=@teller+1
        end loop;
        if @aantal = 1 then
          set @FormatDate=@FormatDate+convert(char(2),day(@Datum))
        else if @aantal = 2 then
            set @FormatDate=@FormatDate+"right"('0'+convert(char(2),day(@Datum)),2)
          else if @aantal = 3 then
              select Trim(DagKort) into @naam from tabDagnaam where @TaalGid = DagTaalGid and DagId = Dow(@Datum)
            else if @aantal = 4 then
                select Trim(DagLang) into @naam from tabDagnaam where @TaalGid = DagTaalGid and DagId = Dow(@Datum)
              end if
            end if
          end if
        end if
      end if;
      if ucase(@karakter) = 'M' then
        while substr(@DatumMasker,@teller,1) = 'M' and @aantal < 4 loop
          if ascii(substr(@DatumMasker,@teller,1)) = 77 then
            set @hoofdletters=@hoofdletters+1
          end if;
          set @aantal=@aantal+1;
          set @teller=@teller+1
        end loop;
        if @aantal = 1 then
          set @FormatDate=@FormatDate+convert(char(2),month(@Datum))
        else if @aantal = 2 then
            set @FormatDate=@FormatDate+"right"('0'+convert(char(2),month(@Datum)),2)
          else if @aantal = 3 then
              select Trim(MndKort) into @Naam from tabMaandnaam where @TaalGid = MndTaalGid and MndId = Month(@Datum)
            else if @aantal = 4 then
                select Trim(MndLang) into @Naam from tabMaandnaam where @TaalGid = MndTaalGid and MndId = Month(@Datum)
              end if
            end if
          end if
        end if
      end if;
      if ucase(@karakter) = 'W' then
        while ucase(substr(@DatumMasker,@teller,1)) = 'W' and @aantal < 2 loop
          set @aantal=@aantal+1;
          set @teller=@teller+1
        end loop;
        //06-07-2010, RvL Bug 32716/18606 : Verkeerde berekening weeknummer
        select DatePart(calWeekOfYear, @Datum) into @week;
        //set @week=(days(ymd(year(@Datum),1,1),@Datum)+dow(ymd(year(@Datum),1,1))-2)/7+1;
        //if days(@Datum,ymd(year(@Datum)+1,1,1)) < 7 and
        //  dow(ymd(year(@Datum)+1,1,1))-days(ymd(year(@Datum)+1,1,1),@Datum) > 0 then
        //  set @week=1
        //end if;
        if @aantal = 1 then
          set @FormatDate=@FormatDate+convert(char(2),@week)
        else if @aantal = 2 then
            set @FormatDate=@FormatDate+"right"('0'+convert(char(2),@week),2)
          end if
        end if
      end if;
      if ucase(@karakter) = 'J' then
        while ucase(substr(@DatumMasker,@teller,1)) = 'J' and @aantal < 4 loop
          set @aantal=@aantal+1;
          set @teller=@teller+1
        end loop;
        if @aantal <= 2 then
          set @FormatDate=@FormatDate+substr(string(year(@datum)),3,2)
        else
          set @FormatDate=@FormatDate+string(year(@datum))
        end if
      end if
    else
      set @FormatDate=@FormatDate+@karakter;
      set @teller=@teller+1
    end if;
    if IsNull(@naam,'') <> '' then
      if @hoofdletters = 0 then
        set @FormatDate=@FormatDate+lcase(@naam)
      else if @hoofdletters = 1 then
          set @FormatDate=@FormatDate+ucase("left"(@naam,1))+substr(@naam,2)
        else
          set @FormatDate=@FormatDate+ucase(@naam)
        end if
      end if
    end if
  end loop;

  set @@ErrorTextProcedure = 'DatumFormat > @FormatDate='+string(@FormatDate);
  //call TraceEind(@@ErrorTextProcedure);

end;


//-------  Formateer de datum naar een opgegeven formaat
create or replace procedure DatumFormatMetTaalRecord(in @Datum date, in @SoortMasker integer, in @TaalGid integer, inout @FormatDate nchar(80))
begin
  declare @DatumMasker nchar(40);

  set @@ErrorTextProcedure = 'DatumFormatMetTaalRecord > @Datum='+string(@Datum)+', @SoortMasker='+string(@SoortMasker)+', @TaalGid='+string(@TaalGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if @SoortMasker = 1 then
    select TaalDatumMiddel into @DatumMasker from tabTaal where TaalGid=@TaalGid;
  else
    if @SoortMasker = 2 then
      select TaalDatumLang into @DatumMasker from tabTaal where TaalGid=@TaalGid;
    else
      select TaalDatumKort into @DatumMasker from tabTaal where TaalGid=@TaalGid;
    end if;
  end if;

  call DatumFormat(@Datum, @DatumMasker, @TaalGid, @FormatDate);

  set @@ErrorTextProcedure = 'DatumFormatMetTaalRecord > @FormatDate='+string(@FormatDate);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function Days360(in @Begindatum Datetime, in @Einddatum Datetime)
returns integer
begin
//MR 05-dec-2012: Deze functie berekend het aantal dagen verschil tussen de Begindatum en Einddatum op basis van 360 dagen per jaar en waarbij elke maand 30 dagen lang is.
  declare @Dag_BeginDatum   integer;
  declare @Dag_EindDatum    integer;
  declare @Maand_BeginDatum integer;
  declare @Maand_EindDatum  integer;
  declare @Jaar_BeginDatum  integer;
  declare @Jaar_EindDatum   integer;
  declare @Verschil         integer;
  declare @DagVerschil      integer;

  //Begindatum gesplitst in dag, maand en jaar
  set @Maand_BeginDatum = MONTH(@Begindatum);
  set @Jaar_BeginDatum  = YEAR(@Begindatum);

  if MONTH(DateAdd(day,1,@Begindatum)) <> @Maand_BeginDatum then
    set @Dag_BeginDatum = 30;
  else
    set @Dag_BeginDatum   = DAY(@Begindatum);
  end if;

  //Einddatum gesplitst in dag, maand en jaar
  if MONTH(DateAdd(day,1,@Einddatum)) <> MONTH(@Einddatum) then
    set @Einddatum = DateAdd(day,1,@Einddatum);
    set @DagVerschil = 0;
  else
    set @DagVerschil = 1;
  end if;

  set @Dag_EindDatum    = DAY(@Einddatum);
  set @Maand_EindDatum  = MONTH(@Einddatum);
  set @Jaar_EindDatum   = YEAR(@Einddatum);

  set @Verschil = ((@Maand_EindDatum - @Maand_BeginDatum) * 30) + (@Dag_EindDatum - @Dag_BeginDatum) + @DagVerschil;

  RETURN ((@Jaar_EindDatum - @Jaar_BeginDatum) * 360) + @Verschil;
end;

create or replace procedure DebiteurKredietRuimte(in @NawGid integer, in @OrkGid integer, out @Kredietlimiet numeric(15,2), out @KredietRuimteDefinitief numeric(15,2), out @KredietRuimteVoorlopig numeric(15,2))
begin
  declare @TotaalDefinitief numeric(15,2);
  declare @TotaalVoorlopig  numeric(15,2);
  declare @DebValNummer     integer;
  declare @BjGid            integer;
  declare @Pernr            integer;
  declare @RksGid           integer;

  set @@ErrorTextProcedure = 'DebiteurKredietRuimte > ';
  //call TraceBegin(@@ErrorTextProcedure + '@NawGid = ' + string(@NawGid) + ', @OrkGid = ' + string(@OrkGid));

  //Kredietlimiet opvragen
  select NawFilKredLimiet, NawFilValNummer, NawFilRksGid into @Kredietlimiet, @DebValNummer, @RksGid
  from   tabNawFile
  where  NawFilNawGid = @NawGid;

  call BepaalBoekjaarEnPeriode( @@VerwerkingsDatum, @BjGid, @PerNr );

  //Geen 'eigen' Kredietlimiet -> standaard Kredietlimiet gebruiken
  if isnull( @Kredietlimiet,0) = 0 then
    select if @@BasisValutaNummer = @DebValNummer then fonKredietlimiet else ValutaOmrekenen( @@BasisValutaNummer, fonKredietlimiet, @DebValNummer, @BjGid, @Pernr, 2) endif
    into   @Kredietlimiet
    from   tabFileOfNaw
    where  fonID='D';
  end if;

  //Nu het 'gebruikte' vaststellen
  set @TotaalDefinitief=0;
  set @TotaalVoorlopig=0;

  //Openstaande posten
  select sum(if OspValNummer = @DebValNummer then OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief else ValutaOmrekenen( OspValNummer, OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief, @DebValNummer, @BjGid, @Pernr, 2)endif),
         sum(if OspValNummer = @DebValNummer then OspFactuurBedragVoorlopig  - OspBetaaldBedragVoorlopig  else ValutaOmrekenen( OspValNummer, OspFactuurBedragVoorlopig  - OspBetaaldBedragVoorlopig,  @DebValNummer, @BjGid, @Pernr, 2) endif)
    into @TotaalDefinitief, @TotaalVoorlopig
  from   tabOpenstaandePost
  where  OspRksGid = @RksGid and OspBjGid = @BjGid;

  set @KredietRuimteDefinitief = 0;

  //Openstaande orders erbij tellen
  if @OrkGid is null then
    select sum(if OrkValNummer = @DebValNummer then OrkTeFactTotaalInclBtw else ValutaOmrekenen( OrkValNummer, OrkTeFactTotaalInclBtw, @DebValNummer, @BjGid, @Pernr, 2) endif)
    into   @KredietRuimteDefinitief
    from   tabOrderKop
    where  OrkNawGID=@NawGid;
    set @KredietRuimteDefinitief= isnull(@TotaalDefinitief,0) + isnull( @KredietRuimteDefinitief, 0 );
  else
    //Tja, behalve dan 'deze' openstaande post!
    select sum(if OrkValNummer = @DebValNummer then OrkTeFactTotaalInclBtw else ValutaOmrekenen( OrkValNummer, OrkTeFactTotaalInclBtw, @DebValNummer, @BjGid, @Pernr, 2) endif)
    into   @KredietRuimteDefinitief
    from   tabOrderKop
    where  OrkNawGID=@NawGid and OrkGid <> @OrkGid;
    set @KredietRuimteDefinitief= isnull(@TotaalDefinitief,0) + isnull( @KredietRuimteDefinitief, 0 );
  end if;

  //En het resultaat teruggeven
  set @KredietRuimteVoorlopig = isnull(@TotaalVoorlopig,0);

  set @@ErrorTextProcedure = 'DebiteurKredietRuimte';
  //call TraceEind(@@ErrorTextProcedure + ' > @Kredietlimiet = ' + string(@Kredietlimiet));
end;


create or replace function DeelproductieBepaalToegestaneWaardeNuTeBoeken
(
 in  @VerwachtAantalNuTeBoeken            numeric(15,3), //Aantal dat berekend is zonder restricties
 in  @TotaalTeBoeken                      numeric(15,3), //Totaal op/af te boeken
 in  @AlGeboekt                           numeric(15,3), //Totaal op/af geboekt (bij componenten minus uitval)
 in  @NogTeBoeken                         numeric(15,3), //Totaal nog op te boeken
 in  @OverschrijdingGrenswaardeToegestaan smallint       //0=nee, 1=ja
 )
returns numeric(15,3)
begin
  //variabelen voor het bepalen van de minimum en maximum waarde die mag worden voorbereid
  declare @Bovengrens      numeric(15,3);
  declare @Ondergrens      numeric(15,3);
  declare @tmpBepaalGrens1 numeric(15,3);
  declare @tmpBepaalGrens2 numeric(15,3);
  declare @NieuweWaarde    numeric(15,3);

  set @@ErrorTextProcedure = 'DeelproductieBepaalToegestaneWaardeNuTeBoeken > @TotaalTeBoeken='+string(@TotaalTeBoeken)+', @AlGeboekt='+string(@AlGeboekt)+', @NogTeBoeken='+string(@NogTeBoeken);
  //call TraceBegin(@@ErrorTextProcedure);

  //eerste grens bepalen voor minimum/maximum toegestane voor te bereiden aantal
  if sign(@TotaalTeBoeken) <> sign(@AlGeboekt) then
    set @tmpBepaalgrens1 = 0
  else
    set @tmpBepaalgrens1 = @AlGeboekt * -1;
  end if;

  //tweede grens bepalen voor minimum/maximum toegestane voor te bereiden aantal
  if sign(@TotaalTeBoeken) <> sign(@NogTeBoeken) then
    set @tmpBepaalgrens2 = 0
  else
    set @tmpBepaalgrens2 = @NogTeBoeken;
  end if;

  //bepalen welke grenswaarde minimum en welke maximum is
  if @tmpBepaalgrens1 < @tmpBepaalgrens2 then
    set @Ondergrens = @tmpBepaalgrens1;
    set @Bovengrens = @tmpBepaalgrens2;
  else
    set @Ondergrens = @tmpBepaalgrens2;
    set @Bovengrens = @tmpBepaalgrens1;
  end if;

  //controleren of ondergrens overschreden wordt
  if @VerwachtAantalNuTeBoeken < @Ondergrens then
    if @OverschrijdingGrenswaardeToegestaan = 1 then
      set @NieuweWaarde = @Ondergrens;
    else
      set @NieuweWaarde = null; //niet aanpassen
    end if;
  //controleren of bovengrens overschreden wordt
  else if @VerwachtAantalNuTeBoeken > @Bovengrens then
    if @OverschrijdingGrenswaardeToegestaan = 1 then
      set @NieuweWaarde = @Bovengrens;
    else
      set @NieuweWaarde = null; //niet aanpassen
    end if;
  else
    //zo niet dan overschrijd de waarde de grenzen niet.
    set @NieuweWaarde = @VerwachtAantalNuTeBoeken;
  end if; end if;

  set @@ErrorTextProcedure = 'DeelproductieBepaalToegestaneWaardeNuTeBoeken > @NieuweWaarde='+string(@NieuweWaarde);
  //call TraceEind(@@ErrorTextProcedure);

  return(@NieuweWaarde)

end;


//$Workfile: DeelproductieVoorbereiden.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

//------------ Deelproductie voorbereiden: aantallen nu af/op te boeken invullen bij component- en eindproductregels
if exists (select 1 from sys.sysProcedure where proc_name='DeelproductieVoorbereiden') then
  drop procedure DeelproductieVoorbereiden;
end if;

create procedure DeelproductieVoorbereiden
(
 in  @PrdOkGid                          integer,       //productieorderkop-gid
 in  @AantalEenheden                    numeric(15,3), //aantal voor te bereiden productie-eenheden
 in  @ComponentregelsBijwerken          smallint,      //0=nee, 1=ja
 in  @EindproductregelsBijwerken        smallint,      //0=nee, 1=ja
 in  @ActieBijOverschrijdingGrenswaarde smallint,      //0=nee, 1=Nog te boeken invullen bij Nu te boeken of Al geboekt (afh van soort voorbereiding: boeking of correctieboeking)
 in  @ActieBijOverschrijvenNuTeBoeken   smallint       //0=nee, 1=Huidige Nu te boeken overschrijven met berekende waarde Nu te boeken, 2 = berekend aantal invullen (geen controles)
 )
begin
  declare @BerekendeWaarde numeric(15,3);
  declare @NieuweWaarde    numeric(15,3);
  declare @PrdOkAantalRcpt numeric(15,3);
  declare @PrdOkRcptSoort  smallint;

  declare @UpdatePrdOcsGid integer;
  declare @UpdatePrdOesGid integer;


  set @@ErrorTextProcedure = 'DeelproductieVoorbereiden(@PrdOkGid='+string(@PrdOkGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  select PrdOkAantalRcpt, PrdOkRcptSoort into @PrdOkAantalRcpt, @PrdOkRcptSoort from tabProductieOrderKop where PrdOkGid = @PrdOkGid;

  if (IsNull(@PrdOkRcptSoort, 0) = 0) then
    //Deelproductie is niet mogelijk bij het produceren van samenstellingen!
    call Raise(20293);
  end if;

  set @AantalEenheden                    = IsNull(@AantalEenheden, @PrdOkAantalRcpt, 0);
  set @ComponentregelsBijwerken          = IsNull(@ComponentregelsBijwerken, 0);
  set @EindproductregelsBijwerken        = IsNull(@EindproductregelsBijwerken, 0);
  set @ActieBijOverschrijdingGrenswaarde = IsNull(@ActieBijOverschrijdingGrenswaarde, 0);
  set @ActieBijOverschrijvenNuTeBoeken   = IsNull(@ActieBijOverschrijvenNuTeBoeken, 0);

  if @ComponentregelsBijwerken = 1 then

    for @Cursor AS CURSOR_ComponentRegelsBijwerken CURSOR FOR
      select
        PrdOcGid                                                                                     @CursPrdOcGid,
        PrdOcRegelNr                                                                                 @CursPrdOcRegelNr,
        PrdOcRcpAantal                                                                               @CursPrdOcRcpAantal,
        PrdOcRcpVerbruik                                                                             @CursPrdOcRcpVerbruik,
        PrdOcRcpVerbruikAantal                                                                       @CursPrdOcRcpVerbruikAantal,
        PrdOcAantalTotaalTeVerwerken - (PrdOcAantalReedsVerwerkt - PrdOcAantalUitvalInReedsVerwerkt) @CursPrdOcNogAfTeBoeken,
        PrdOcAantalTotaalTeVerwerken                                                                 @CursPrdOcTotaalAfTeBoeken,
        PrdOcAantalReedsVerwerkt - PrdOcAantalUitvalInReedsVerwerkt                                  @CursPrdOcAlAfgeboekt,
        PrdOcAantalDezeVerwerking                                                                    @CursPrdOcNuAfTeBoeken
      from
        tabProductieOrderComponent
      where PrdOcPrdOkGid = @PrdOkGid
        and PrdOcRegelSoort <> 0       /* Tekstregels niet opnieuw berekenen */
      order by
        PrdOcRegelNr
    for update
    do
      set @BerekendeWaarde = 0;
      set @NieuweWaarde    = null;
      set @UpdatePrdOcsGid = null;

      if @CursPrdOcRcpVerbruik <> -1 then  //directe/handmatige invoer
        if (@CursPrdOcNuAfTeBoeken = 0.0) or (@ActieBijOverschrijvenNuTeBoeken = 1) then

          case @CursPrdOcRcpVerbruik
            when 0 then set @BerekendeWaarde = @AantalEenheden * @CursPrdOcRcpAantal;
            when 1 then set @BerekendeWaarde = Sign(@AantalEenheden) * @CursPrdOcRcpAantal;
            when 2 then set @BerekendeWaarde = (Ceiling(@AantalEenheden / @CursPrdOcRcpVerbruikAantal) * @CursPrdOcRcpAantal);
          end case;

          //nu af te boeken op 0 zetten
          if @AantalEenheden = 0 then
            set @NieuweWaarde = 0;
          else
            //domweg overschrijden, geen controles dus
            if @ActieBijOverschrijdingGrenswaarde = 2 then
              set @NieuweWaarde = IsNull(@Berekendewaarde, 0);
            else
              select DeelproductieBepaalToegestaneWaardeNuTeBoeken(@BerekendeWaarde, @CursPrdOcTotaalAfTeBoeken, @CursPrdOcAlAfgeboekt, @CursPrdOcNogAfTeBoeken, if @ActieBijOverschrijdingGrenswaarde = 1 then 1 else 0 endif) into @NieuweWaarde;
            end if;
          end if;
        end if;
      else
        //directe invoer (handmatige invoer) - voorlopig niets mee doen!
      end if;

      //als waarde <> null is, dan is er iets ingevuld en moeten de regels bijgewerkt worden
      if @NieuweWaarde is not null then
        //Componentregel updaten
        update tabProductieOrderComponent
        set    PrdOcAantalDezeVerwerking         = @NieuweWaarde,
               PrdOcAantalUitvalInDezeVerwerking = 0
        where  current of CURSOR_ComponentRegelsBijwerken;

        //Componentspecificatieregel updaten
        select Max(PrdOcsGid) into @UpdatePrdOcsGid
        from   tabProductieOrderComponentSpec
        where      PrdOcsPrdOcGid             = @CursPrdOcGid
               and PrdOcsAantalDezeVerwerking = @CursPrdOcNuAfTeBoeken
        having Count(*) = 1 and Count(PrdOcsArtserieGid) = 0;

        if @UpdatePrdOcsGid is not null then
          update tabProductieOrderComponentSpec
          set    PrdOcsAantalDezeVerwerking         = @NieuweWaarde,
                 PrdOcsAantalUitvalInDezeVerwerking = 0
          where  PrdOcsGid = @UpdatePrdOcsGid;
        end if;
      end if;
    end for;
  end if;

  if @EindproductregelsBijwerken = 1 then

    for @Cursor AS CURSOR_EindproductRegelsBijwerken CURSOR FOR
      select
        PrdOeGid                                                @CursPrdOeGid,
        PrdOeRegelNr                                            @CursPrdOeRegelNr,
        PrdOeRcpAantal                                          @CursPrdOeRcpAantal,
        PrdOeIsReceptRegel                                      @CursPrdOeIsReceptRegel,
        PrdOeAantalTotaalTeVerwerken - PrdOeAantalReedsVerwerkt @CursPrdOeNogOpTeBoeken,
        PrdOeAantalTotaalTeVerwerken                            @CursPrdOeTotaalOpTeBoeken,
        PrdOeAantalReedsVerwerkt                                @CursPrdOeAlOpgeboekt,
        PrdOeAantalDezeVerwerking                               @CursPrdOeNuOpTeBoeken
      from
        tabProductieOrderEindproduct
      where PrdOePrdOkGid = @PrdOkGid
      order by
        PrdOeRegelNr
    for update
    do
      set @BerekendeWaarde = 0;
      set @NieuweWaarde    = null;
      set @UpdatePrdOesGid = null;

      if (@CursPrdOeIsReceptRegel = 1) then
        if (@CursPrdOeNuOpTeBoeken = 0.0) or (@ActieBijOverschrijvenNuTeBoeken = 1) then

          set @Berekendewaarde = @AantalEenheden * @CursPrdOeRcpAantal;

          //nu op te boeken op 0 zetten
          if @AantalEenheden = 0 then
            set @NieuweWaarde = 0;
          //domweg overschrijden, geen controles dus
          else
            if @ActieBijOverschrijdingGrenswaarde = 2 then
              set @NieuweWaarde = IsNull(@Berekendewaarde, 0);
            else
              select DeelproductieBepaalToegestaneWaardeNuTeBoeken(@BerekendeWaarde, @CursPrdOeTotaalOpTeBoeken, @CursPrdOeAlOpgeboekt, @CursPrdOeNogOpTeBoeken, if @ActieBijOverschrijdingGrenswaarde = 1 then 1 else 0 endif) into @NieuweWaarde;
            end if;

            //als waarde <> null is, dan is er iets ingevuld en moeten de regels bijgewerkt worden
            if @NieuweWaarde is not null then
              //Eindproductregel updaten
              update tabProductieOrderEindproduct
              set    PrdOeAantalDezeVerwerking         = @NieuweWaarde,
                     PrdOeAantalUitvalInDezeVerwerking = 0.0
              where  current of CURSOR_EindproductRegelsBijwerken;

              //Eindproductspecificatieregel updaten
              select Max(PrdOesGid) into @UpdatePrdOesGid
              from   tabProductieOrderEindproductSpec
              where      PrdOesPrdOeGid             = @CursPrdOeGid
                     and PrdOesAantalDezeVerwerking = @CursPrdOeNuOpTeBoeken
              having Count(*) = 1 and Count(PrdOesArtserieGid) = 0;

              if @UpdatePrdOesGid is not null then
                update tabProductieOrderEindproductSpec
                set    PrdOesAantalDezeVerwerking         = @NieuweWaarde,
                       PrdOesAantalUitvalInDezeVerwerking = 0
                where  PrdOesGid = @UpdatePrdOesGid;
              end if;
            end if;
          end if;
        end if;
      end if;
    end for;
  end if;

  set @@ErrorTextProcedure = 'DeelproductieVoorbereiden(@PrdOkGid='+string(@PrdOkGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


//---------- Bepaal default omschrijving voor een journaalregel
create or replace procedure DefaultOmsJournaalregel(in @JpGid integer, in @JrNummer integer, out @Oms nchar(40))
begin
  declare @DefOmschrijving smallint;

  //call TraceBegin('DefaultOmsJournaalregel (@JpGid='+string(@JpGid)+', @JrNummer='+string(@JrNummer)+')');


  set @Oms = '';
  select DefOmschrijving into @DefOmschrijving from tabDagboek inner join tabJournaalPost on (JpDgbGid = DgbGid and JpGid = @JpGid);
  case @DefOmschrijving
    when 1 then
      select first OmsJournaalregel into @Oms from tabJournaalRegel where JrJpGid = @JpGid and JrNummer < @JrNummer order by JrNummer desc
    when 2 then
      select OmsJournaalPost into @Oms from tabJournaalPost where JpGid = @JpGid;
    when 5 then
      select first RksNaam into @Oms from tabJournaalRegel inner join tabRekeningschema on (RksGid = JrRksGid) where JrJpGid = @JpGid and JrNummer < @JrNummer order by JrNummer desc
    when 6 then
      select first RksZoekcode into @Oms from tabJournaalRegel inner join tabRekeningschema on (RksGid = JrRksGid)where JrJpGid = @JpGid and JrNummer < @JrNummer order by JrNummer desc
  end case;

  //call TraceEind('DefaultOmsJournaalregel ------> @Oms='+string(@Oms));

end;


//------------ Geef de default rekeningnaam terug
create or replace procedure DefaultRekeningnaam(in @RksNummer nchar(10), in @KstpGid integer, in @KstdGid integer, out @RksGid integer, out @HoofdRekExist smallint, out @Naam nchar(40), out @Zoekcode nchar(10))
begin
  set @@ErrorTextProcedure = 'DefaultRekeningnaam > @RksNummer='+@RksNummer+', @KsptGid='+string(@KstpGid)+', @KstdGid='+string(@KstdGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //we bouwen achterstevoren de naam op, omdat de rekeningnaam zoveel mogelijk uitgevuld moet worden met
  //de naam van de hoofdrekening
  set @RksGid = null;
  set @Naam = '';
  set @HoofdRekExist = 0;

  if @KstdGid is not null then
    select '/'+KstdZoekcode into @Naam from tabKostendrager where KstdGid = @KstdGid;
  end if;

  if (@KstpGid is null) and (@KstdGid is not null) then
    set @Naam='/'+@Naam
  end if;

  if @KstpGid is not null then
    select '/'+KstpZoekcode+@Naam into @Naam from tabKostenplaats where KstpGid = @KstpGid;
  end if;


  if IsNull(@RksNummer,'')<>'' then
    if exists(select 1 from tabRekeningschema where RksKstpGid is null and RksKstdGid is null and RksNummer = @RksNummer) then
      select substr(RksNaam, 1, 40-length(@Naam))+@Naam, RksZoekcode, RksGid
      into   @Naam, @ZoekCode, @RksGid
      from   tabRekeningschema where RksKstpGid is null and RksKstdGid is null and RksNummer = @RksNummer;
      set @HoofdRekExist = 1;
    end if;
  end if;

  set @@ErrorTextProcedure = 'DefaultRekeningnaam > @HoofdRekExist='+string(@HoofdRekExist)+', @Naam='+@Naam+', @Zoekcode='+@Zoekcode;
  //call TraceEind(@@ErrorTextProcedure);

end;


//-------- Geef nummer en code van de defaultvaluta van een rekening terug
create or replace procedure DefaultValuta(in @RksGid integer, inout @ValNummer integer, inout @ValCode nchar(3))
begin

  set @@ErrorTextProcedure = 'DefaultValuta > @RksGid='+string(@RksGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select ValNummer, ValCode into @Valnummer, @ValCode from tabRekeningschema, tabValuta where ValNummer = RksValNummer and RksGid = @RksGid;

  set @@ErrorTextProcedure = 'DefaultValuta > @ValNummer='+string(@ValNummer)+', @ValCode='+@ValCode;
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function DezeOfVolgendeWerkdag(in @Date datetime, in @LndGid integer)
returns datetime
begin
  set @@ErrorTextProcedure = 'DezeOfVolgendeWerkdag > @Date= ' + string(@Date)+', @LndGid= ' + string(@LndGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsWerkdag(@Date, @LndGid) = 0 then
    set @Date = VolgendeWerkdag(@Date, @LndGid);
  end if;
  set @@ErrorTextProcedure = @@ErrorTextProcedure + ' -> ' + string(@Date);
  //call TraceEind(@@ErrorTextProcedure);
  // En weer terug geven
  return(@Date);
end;


create or replace function DezeOfVorigeWerkdag(in @Date datetime, in @LndGid integer)
returns datetime
begin
  set @@ErrorTextProcedure = 'DezeOfVorigeWerkdag > @Date= ' + string(@Date)+', @LndGid= ' + string(@LndGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsWerkdag(@Date, @LndGid) = 0 then
    set @Date = VorigeWerkdag(@Date, @LndGid);
  end if;
  set @@ErrorTextProcedure = @@ErrorTextProcedure + ' -> ' + string(@Date);
  //call TraceEind(@@ErrorTextProcedure);
  // En weer terug geven
  return(@Date);
end;


create or replace procedure DirecteLeveringBoeken (in @MokGid integer, in @MohkGid integer, in @Boekdatum date, in @Stuknummer numeric(10,0), inout @BoekgangGid integer, out @JpGid integer)
begin
  // *********************************************************************************************************
  // *** !!! LET OP!! Bij wijzigen controleren of ook MagazijnOntvangstBoeken.sp moet worden aangepast !!! ***
  // *********************************************************************************************************

  declare @Omschrijving     nchar(40);
  declare @MokBoekDatum     date;
  declare @temp             nchar(2);
  declare @BjGid            integer;
  declare @JrGid            integer;
  declare @PerNr            integer;
  //Variabelen tbv. Directe Levering (uitbreiding)
  declare @RksGIDTussenrekGefactureerdeGoederen integer;
  declare @RksGIDTussenrekTeFacturerenGoederen  integer;
  declare @MagVastOntvBoekenTegen integer; // Boeken tegen VVP (0) of werkelijke inkkoopprijs (1)
  declare @DagboekGid             integer; // Dagboek waarin de boekingen moeten komen -> van de directe levering!
  declare @Naam             nchar(40);
  declare @DirLeveringTekst    long nvarchar;
  declare @DirLevMeerdereTekst long nvarchar;

  declare local temporary table tmpMagOntRegel (
    tmpMagOntGid        integer,
    tmpOrkGid           integer,  //ACW 13-09-2010: uitbreiding DL
    tmpOrkEersteActie   integer,  //ACW 13-09-2010: uitbreiding DL tbv. bepalen keuze Tussenrekening Te factureren/Gefactureerde goederen
    tmpSignFactor       smallint,
    tmpRegelTotaalInInkoopPrijsOfVvp              numeric(15,3),            // ACW 15-09-2010: Indien boeken tegen VVP, dan deze gewoon berekenen obv. de VVP!
    tmpKostprijsVanOntvangstTotaal                numeric(15,3),
    tmpRegelTotaalInInkoopPrijsOfVvpInJuisteTeken numeric(15,3),
    tmpKostprijsVanOntvangstTotaalInJuisteTeken   numeric(15,3),
    tmpValNummerVanRegelTotaal                    integer
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'DirecteLeveringBoeken > ';
  //call TraceBegin(@@ErrorTextProcedure + '@MokGid =  ' + string(@MokGid));

  //ACW 13-09-2010: uitbreiding DL: tbv. boeking op tussenrekening verkopen
  select first vofGeFactureedeGoederenRksGid into @RksGIDTussenrekGefactureerdeGoederen from tabVasteGegevensOrdersFactureren;
  select first vofTeFacturerenGoederenRksGid into @RksGIDTussenrekTeFacturerenGoederen  from tabVasteGegevensOrdersFactureren;
  if @RksGIDTussenrekGefactureerdeGoederen is null or @RksGIDTussenrekTeFacturerenGoederen is null then
    call Raise(20349); //(20349) Tussenrekeningen Te factureren en/of Gefactureerde goederen in de vaste gegevens orders/facturering is/zijn niet ingevuld!
  end if;

  select MagVastOntvBoekenTegen, MagVastDgbGIDDirLev into @MagVastOntvBoekenTegen, @DagboekGid from tabMagazijnOntvangstenVasteGegevens;

  select
    AdrNaam1 into @Naam
  from
    tabNaw
    inner join tabAdres on (NawGid = AdrNawGid and NawGidVestiging = AdrGid)
    inner join tabMagazijnOntvangstenKop on (MokNawGid = NawGid and MokGid = @MokGid);

  set @DirLeveringTekst = _A('Directe levering %1!');
  set @DirLeveringTekst = _VervangMetRondeHaakjes(@DirLeveringTekst, 40, @Naam);

  //Als geen boekgangGid meegegeven, dan boekingsgang creeren en in gebruik nemen
  //uit gebruik nemen in programma afhandelen, zodat een groep van ontvangsten in 1 boekingsgang kan komen
  if @BoekgangGid is null then
    insert into tabBoekingsGang(BoekGangBjGid, BoekgangBronId, BronOms, BoekGangInGebruik, IsBoekGangDefinitief)
                       values(@@BjGid, 11, @DirLeveringTekst, 1, 0);
    set @BoekGangGid = @@Identity;
  else
    set @DirLevMeerdereTekst = _A('Directe levering meerdere leveranciers');

    //Bug#  23904: Als de boekingsgang bestaat uit meerdere leveranciers, dan niet de naam plaatsen van de leverancier, maar '(meerdere leveranciers)'
    update TabBoekingsGang
    set BronOms = @DirLevMeerdereTekst
    where boekganggid = @BoekGangGid
    and BronOms not in ( @DirLeveringTekst, @DirLevMeerdereTekst);
  end if;

  //tijdelijke tabel vullen met (zodat we deze berekening niet onnodig vaak hoeven uit hoeven te rekenen):
  //tmpRegelTotaalInInkoopPrijsOfVvp : aantal ontvangen tegen inkoopprijs  ACW 15-09-2010: Indien boeken teegn VVP, dan hier de VVP in zetten!
  //tmpKostprijsVanOntvangstTotaal   : aantal ontvangen tegen kostprijs VAN DE VERKOOPORDER ACW 13-09-2010: NIET meer de kostprijs van artikel, maar die rechtstreeks uit de verkooporderregel halen TENZIJ tarief
  insert into tmpMagOntRegel (tmpMagOntGid, tmpOrkGid, tmpOrkEersteActie, tmpSignFactor, tmpRegelTotaalInInkoopPrijsOfVvpInJuisteTeken, tmpKostprijsVanOntvangstTotaalInJuisteTeken, tmpRegelTotaalInInkoopPrijsOfVvp, tmpKostprijsVanOntvangstTotaal, tmpValNummerVanRegelTotaal)
  select
    MagOntGid,
    OrrOrkGid,
    OrkEersteActie,
    Sign(MagOntAantal) tmpSignFactor,
    //ACW 06-10-2009 - bug 30890 - Berekening opnieuw
    //RVL 25-10-2010 - bug 32287 - Berekening nogmaals opnieuw
    //ACW 15-09-2010: Uitbreiding DL: De VVP hierin onthouden, zodat die normaal kan worden verwerkt
    case @MagVastOntvBoekenTegen
    when 0 /*boeken tegen VVP, dus hier de VVP in zetten*/ then
      (MagOntAantal / ArtPrijsPer) * isnull(ArtPartijKostprijsEx, ArtKostprijsEx)
    when 1 /*boeken tegen werkelijke inkoopprijs, dus hier de inkoopsprijs in zetten*/ then
      if MagOntInkoopprijsPer = 1 /*X voorr.eenh.*/ then
        if MagOntPrijsPer = 0 then
          0
        else
          round(MagOntInkoopprijs * if MagOntKortingSoort = 1 /*Kortingsperc.*/  then (100 - MagOntKortingPercentage) / 100 else 1 endif -
                                    if MagOntKortingSoort = 0 /*Kortingsbedrag*/ then MagOntKortingBedrag / MagOntPrijsPer  else 0 endif
             , ArtAantDecPrijzen) * (MagOntAantal / MagOntPrijsPer)
        endif
      else /*inkoopeenheid*/
        round(round(MagOntInkoopprijs * if MagOntKortingSoort = 1 /*Kortingsperc.*/  then (100 - MagOntKortingPercentage) / 100 else 1 endif -
                                        if MagOntKortingSoort = 0 /*Kortingsbedrag*/ then MagOntKortingBedrag                   else 0 endif
                    , ArtAantDecPrijzen)
              * (ArtPrijsPer / MagOntVoorraadEenhedenInInkoopEenheid) * (MagOntAantal / MagOntPrijsPer)
             , ArtAantDecPrijzen)
      endif
    end NettoRegelTotaalInJuisteTeken,
  //ACW 13-09-2010: Uitbreiding DL: Haal de kostprijs uit de verkooporder ipv uit partij of artikel
  //round(if ArtPrijsPer = 0 then 0 else IsNull(ArtPartijKostprijsEx, ArtKostprijsEx) * (MagOntAantal / ArtPrijsPer) endif, ArtAantDecPrijzen) KostprijsVanOntvangstTotaalInJuisteTeken,
    round(if OrrPrijsPer = 0 then 0 else OrrKostprijs                                 * (MagOntAantal / OrrPrijsPer) endif, ArtAantDecPrijzen) as KostprijsVanOntvangstTotaalInJuisteTeken,
    NettoRegelTotaalInJuisteTeken * tmpSignFactor NettoRegelTotaal,
    KostprijsVanOntvangstTotaalInJuisteTeken * tmpSignFactor  KostprijsVanOntvangstTotaal,
    if @MagVastOntvBoekenTegen = 0 /*boeken tegen VVP*/ then @@BasisValutaNummer else MokValNummer endif tmpValNummerVanRegelTotaal
  from
    tabMagazijnOntvangsten
    inner join tabMagazijnOntvangstenKop         on (MokGid = MagOntMokGid)
    left outer join tabMagazijnOntvangstenDetail on (MagOntDetMagOntGid = MagOntGid) //Tariefregels hebben geen details!!
    left outer join tabBestelregelDetail         on (brdGid = MagOntDetbrdGid)
    left outer join (tabOrderRegel // Als tariefregel, dan WEL verwerken, maar zit dan niet in de verkooporder!
                     inner join tabOrderKop      on (OrkGid = OrrOrkGid)
                    ) on (OrrGid = isnull(brdOrrGid, MagOntDetOrrGid))
    inner join tabArtikel                        on (ArtGid = MagOntArtGid)
    left outer join tabArtikelPartij             on (ArtPartijGid = MagOntArtPartijGid and ArtIsPartijAparteKostPrijs <> 0)
  where
        MagOntMokGid     = @MokGid
    and MagOntRegelSoort = 2 /*Artikel*/
	group by // 55578 groeperen per magontvangstregel/orderregel
    MagOntGid, OrrOrkGid, OrkEersteActie, tmpSignFactor, MagOntAantal, NettoRegelTotaalInJuisteTeken, KostprijsVanOntvangstTotaalInJuisteTeken,
		NettoRegelTotaal, KostprijsVanOntvangstTotaal, tmpValNummerVanRegelTotaal;

  //call Trace('Journaalpost toevoegen');
  insert into tabJournaalpost(JpBoekGangGid, JpBjGID, JpIsInGebruik, JpDgbGID,
                              BoekstukNummer, OmsJournaalPost, BoekDatum)
  select @BoekGangGid, @@BjGid, 1, @DagboekGid,
         @Stuknummer, MokOmschrijving, @BoekDatum
  from   tabMagazijnOntvangstenKop
  where  MokGid = @MokGid;
  set    @JpGid = @@Identity;//komt in de voorraadmutaties

  update tabMagazijnOntvangstHistKop set MohkBoekdatum = @BoekDatum, MohkBoekStuknummer = @Stuknummer, MohkDagboek = (select DgbCode from tabDagboek where DgbGID = @DagboekGid) where MohkGid = @MohkGid;

  //ACW 20-09-2010: Omschrijving tbv. boekingen bepaald uit vaste gegevens
  set @Omschrijving = DirecteLeveringMaakJPOms(@MokGid);
  /*
  select
         MokOmschrijving, @BoekDatum
    into @Omschrijving  , @MokBoekDatum
  from
    tabMagazijnOntvangstenKop
  where
    MokGid = @MokGid;
  */
  //call Trace('genereren van journaalregels');

  //boeken tegen VVP of werkelijke inkoopprijs(<>0 is werkelijke inkoopprijs)
  //ACW 13-09-2010: Verschil in VVP of inkoopprijs is niet aanwezig, want dan staat de VVP al in het juiste tmpveld
  //gemeenschappelijk deel voor voorbeeld 1 + 2(werkelijke inkoopprijs, dus prijsverschillen ook boeken)

  //maak ontbrekende kosten- en prijsverschillenrekening per opbrengstgroep aan
  select  min(distinct OpbrengtGroepsoortenPerStuk(OpbrGrpGid, ParSoort)) into @temp
  from
    (tabParagraaf,
     tabmagazijnontvangsten
     inner join tabartikel on (ArtGid = MagOntArtGid)
     inner join TabOpbrengstGroep on (OpbrGrpGid = ArtOpbrGrpGid))
     left outer join tabOpbrengstGroepSoort on (GrpSoortParSoort = Parsoort and GrpSoortRksGID is null)
  where
    (ParSoort = 90 and ArtSoort = 2) //ACW 13-09-2010: Uitbreiding DL: Alleen prijsverschillen (we boeken niet op voorraad!)
    and MagOntMokGid = @MokGid;

  call BepaalBoekjaarEnPeriode(@MokBoekDatum, @BjGid, @PerNr);
  //call Trace('boeken van de voorraadgroepen en prijsverschillengroepen(per artikelgroep)');

  //Er worden 2 boekingen gedaan: 1 voorraadboeking en 1 prijsverschillen-boeking (middels group by op paragraafsoort)
  //ACW 13-09-2010: Per verkooporder!

  //Boeking op tussenrekening: Per verkooporder!!
  insert into tabJournaalRegel(JrJpGid, JrRksGid, OmsJournaalRegel, JrReferentie, SoortBoeking,
                              IsCreditBoeking,
                              JrValutaBedrag,
                              JrBasisBedrag, JrValNummer)
  select
    @JpGid,
    if tmpOrkEersteActie = 1 then @RksGIDTussenrekGefactureerdeGoederen else @RksGIDTussenrekTeFacturerenGoederen endif RksGid,
    @Omschrijving,
    OrkNummer,
    0, 0, sum(tmpKostprijsVanOntvangstTotaalInJuisteTeken) Bedrag, Bedrag, @@BasisValutaNummer
  from
    tabMagazijnOntvangstenKop
    inner join tabmagazijnontvangsten on (MagOntMokGid = MokGid)
    inner join tmpMagOntRegel on (tmpMagOntGid = MagOntGid)
    inner join tabArtikel on (ArtGid = MagOntArtGid)
    inner join tabOrderKop on (OrkGid = tmpOrkGid)
  where
    MagOntMokGid = @MokGid
    and MagOntRegelsoort = 2 /*Artikel*/
  group by
    MokValNummer, OrkNummer, tmpOrkGid, tmpOrkEersteActie
  having
    Bedrag <> 0;

  // Prijsverschil: Per ontvangstregel
  insert into tabJournaalRegel(JrJpGid, JrRksGid, OmsJournaalRegel, JrReferentie, SoortBoeking,
                              IsCreditBoeking,
                              JrValutaBedrag,
                              JrBasisBedrag, JrValNummer)
  select
    @JpGid,
    (select GrpSoortRksGID from tabOpbrengstGroep  inner join tabOpbrengstGroepSoort on (GrpSoortGrpGid = OpbrGrpGid) where OpbrGrpGid = ArtOpbrGrpGid and GrpSoortParSoort =90 /*Prijsverschil*/) RksGid,
    @Omschrijving, '', 0,
    //prijsverschilboeking; debet indien regeltotaal > aantal ontvangen * kostprijs, anders credit
    if
    (if tmpValNummerVanRegelTotaal = @@BasisValutaNummer then sum(tmpRegelTotaalInInkoopPrijsOfVvp) else ValutaOmrekenen(tmpValNummerVanRegelTotaal, sum(tmpRegelTotaalInInkoopPrijsOfVvp), @@BasisValutaNummer, @BjGid, @Pernr, 2) endif)
     > sum(tmpKostprijsVanOntvangstTotaal) then 0 else 1 endif Boekzijde,
    ((if tmpValNummerVanRegelTotaal = @@BasisValutaNummer then sum(tmpRegelTotaalInInkoopPrijsOfVvpInJuisteTeken) else ValutaOmrekenen(tmpValNummerVanRegelTotaal, sum(tmpRegelTotaalInInkoopPrijsOfVvpInJuisteTeken), @@BasisValutaNummer, @BjGid, @Pernr, 2) endif)
     - sum(tmpKostprijsVanOntvangstTotaalInJuisteTeken))
     * if Boekzijde = 0 then 1 else -1 endif Bedrag,
    Bedrag, @@BasisValutaNummer
  from
    tabMagazijnOntvangstenKop
    inner join tabmagazijnontvangsten on (MagOntMokGid = MokGid)
    inner join tmpMagOntRegel on (tmpMagOntGid = MagOntGid)
    inner join tabArtikel on (ArtGid = MagOntArtGid)

  where
    MagOntMokGid = @MokGid
    and MagOntRegelsoort = 2 /*Artikel*/
  group by
    tmpValNummerVanRegelTotaal, ArtOpbrGrpGid
  having
    Bedrag <> 0;

  //laatste deel voorbeeld 2(boeken op tussenrekening inkopen tegen werkelijke inkoopprijs)

  //call Trace('boeken op tussenrekening inkopen(tegen werkelijke inkoopprijs)');
  insert into tabJournaalRegel(
    JrJpGid,
    JrRksGid,
    OmsJournaalRegel,
    JrReferentie,
    SoortBoeking,
    IsCreditBoeking,
    JrValutaBedrag,
    JrBasisBedrag,
    JrValNummer)
  select
    /*JrJpGid,         */ @JpGid,
    /*JrRksGid,        */ (select MagVastInkRksGid from tabMagazijnOntvangstenVasteGegevens) RksGidTussenRek,
    /*OmsJournaalRegel,*/ @Omschrijving,
    /*JrReferentie,    */ if (select ReferentieVerplicht from tabRekeningSchema where RksGid = RksGidTussenRek) = 1 then MokFactuurNummer else '' endif,
    /*SoortBoeking,    */ 0,
    /*IsCreditBoeking, */ 1,
    /*JrValutaBedrag,  */ round(sum(tmpRegelTotaalInInkoopPrijsOfVvpInJuisteTeken),2) as BedragInValuta,
    /*JrBasisBedrag,   */ if tmpValNummerVanRegelTotaal = @@BasisValutaNummer
                            then BedragInValuta else ValutaOmrekenen(tmpValNummerVanRegelTotaal, BedragInValuta, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif,
    /*JrValNummer      */ tmpValNummerVanRegelTotaal
  from
    tabMagazijnontvangstenKop
    inner join tabmagazijnontvangsten on (MagOntMokGid = MokGid)
    inner join tmpMagOntRegel on (tmpMagOntGid = MagOntGid)
  where
        MagOntMokGid = @MokGid
    and MagOntRegelSoort = 2 /*Artikel*/
  group by
    tmpValNummerVanRegelTotaal, MokFactuurNummer
  having
    BedragInValuta <> 0;

  // Onthouden van bedrag dat op de tussenrekening inkopen is geboekt, t.b.v. aanmaken inkoopfactuur en prijsverschillen
  update tabMagazijnOntvangsten
  set    MagOntTussenrekeningTotaalGeboekt = tmpRegelTotaalInInkoopPrijsOfVvpInJuisteTeken
  from   tmpMagOntRegel
  inner join tabMagazijnontvangstenKop on MokGid = @MokGid
  where  tmpMagOntGid = MagOntGid;

  // Tussenrekeningbedrag (kostprijs of werkleijke inkoopprijs) overnemen naar historische ontvangst
  update tabMagazijnontvangstHistRegel
  set    MohrTussenrekeningTotaalGeboekt = MagOntTussenrekeningTotaalGeboekt
  from   tabmagazijnontvangsten
  where
    MagOntMokGid = @MokGid and
    MohrMohkGid  = @MohkGid and
    MohrRegelnr  = MagOntRegelnr; // Op basis van regelnummer i.c.m. MohkGid is dit wel over te nemen


  update tabJournaalPost set JpIsInGebruik=0 where JpGid = @JpGid;

  set @@ErrorTextProcedure = 'DirecteLeveringBoeken';
  //call TraceEind( @@ErrorTextProcedure + ' > @BoekgangGid = ' + string(@BoekgangGid));
end;

create or replace function DirecteLeveringMaakJPOms(in @MokGid integer) returns nchar(40)
begin
  declare @DirecteLeveringOmsJPWelke integer;
  declare @DirecteLeveringOmsJP      nchar(40);

  set @@ErrorTextProcedure = 'DirecteLeveringMaakJPOms(@MokGid='+string(@MokGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  select MagVastDirecteLeveringOmsJPWelke into @DirecteLeveringOmsJPWelke from tabMagazijnOntvangstenVastegegevens;

  case @DirecteLeveringOmsJPWelke
  when 0 then //Omschrijving directe levering
    select first MokOmschrijving into @DirecteLeveringOmsJP
    from tabMagazijnOntvangstenKop
    where MokGid = @MokGid;
  when 1 then //Tekst 'Directe levering'
    set @DirecteLeveringOmsJP = _A('Directe levering');
  when 2 then //Leveranciernaam
    select adrNaam1 into @DirecteLeveringOmsJP
    from tabMagazijnOntvangstenKop
    inner join tabNaw  on nawgid = MokNawGid
    inner join tabAdres on adrGID = nawGidVestiging
    where MokGid = @MokGid;
  when 3 then //tekst 'Directe levering' + nummer
    select _A('Directe levering %1!', string(MokNummer)) into @DirecteLeveringOmsJP
    from tabMagazijnOntvangstenKop
    where MokGid = @MokGid;
  when 4 then //tekst 'Directe levering' + nummer + Leveranciernaam
    select _A('Directe levering %1! %2!', string(MokNummer), adrNaam1) into @DirecteLeveringOmsJP
    from tabMagazijnOntvangstenKop
    inner join tabNaw  on nawgid = MokNawGid
    inner join tabAdres on adrGID = nawGidVestiging
    where MokGid = @MokGid;
  when 5 then //Anders ...
    select MagVastDirecteLeveringOmsJP into @DirecteLeveringOmsJP
    from tabMagazijnOntvangstenVastegegevens;
  end case;

  //call TraceEind(@@ErrorTextProcedure);
  return (@DirecteLeveringOmsJP);
end;


//---------------------------------------------------------------------------
//----------------------------Magazijnontvangst verwerken--------------------
//---------------------------------------------------------------------------
create or replace procedure DirecteLeveringVulHistorischeTabellen(in @MokGid integer, in @Boekdatum date, in @Stuknummer numeric(10,0), in @BoekgangGid integer, in @JpGid integer, in @RapNummer integer, inout @FbGid integer)
begin
  declare @ErrText          nchar(500);
  declare @TfoGid           integer;
  declare @Volgorde         integer;

  set @ErrText = 'DirecteLeveringVulHistorischeTabellen(@MokGid='+string(@MokGid)+')';
  set @@ErrorTextProcedure = '->' + @ErrText;
  //call TraceBegin(@@ErrorTextProcedure);

  // Eventueel eerst factuurbatch aanmaken en locken
  if @FbGid is null then
    insert into tabFactuurBatch(fbAangemaaktDoor, fbAangemaaktOp, fbSoortBatch,            fbBoekgangGid, fbIsVerwerkt, fbAcceptGiroAfgedrukt, fbPakbonAfgedrukt)
                         values(@@GebruikerCode,  now(),          35 /*Directe levering*/, @BoekgangGid,  1,            0,                     1 /*Pakbon gaat afgedrukt worden*/);
    set @fbGid = @@Identity;

    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid), 0);
  end if;

  // LET OP! Er is altijd een adres per verkooporder (waar de artikelen uiteindelijk naartoe moeten) en altijd een werkelijk afleveradres.
  // Nu wordt het werkelijke afleveradres gebruikt! Voorstel:
  // - Afleveradres = afleveradres volgens bestelling/verkooporder
  // - Eindbestemming = afleveradres van de verkooporder.



// Voor een gegeven @MokGid moeten we alle verkooporderregels op een rij hebben.
// Door gebruik te maken van FactStartMaakFacturen hoeven we niet zelf weer alles opnieuw te doen.
// Om die routine te gebruiken moeten we het volgende doen:
// - Maak een (nieuwe) factuurbatch aan
// - Vul tabTeFacturerenOrders met de verkooporders
// - Gebruik een detailtabel onder tabTeFacturerenOrders, namelijk: TeFacturerenOrderRegels Vul met OrrGid en AantalDezeLevering
// - Roep FactStartMaakFacturen aan met @SoortFact = 6 (DirecteLevering)
// - Aanpassen van FactStartMaakFacturen zodat dezelfde dingen worden gedaan voor soort=5 als voor soort=3 (pakbon)
// - Aanpassen van FacturerenToevoegenOrderRegelGegevens, zodat niet alle regels worden verwerkt, maar alleen de regels van betreffende verkooporder die in TeFacturerenOrderRegels zitten

  // Tussentabellen vullen voor de standaard verwerking
  set @Volgorde = 0;

  // Tabellen opschonen
  delete tabTeFacturerenOrders where TfoSessieFbGid = @FbGid;

  for @Cursor_PakbonPerOrder AS Cursor_PakbonPerOrder CURSOR FOR
    select distinct
      OrkGid @OrkGid, OrkNummer @OrkNummer
    from
      tabMagazijnOntvangsten
      inner join tabMagazijnOntvangstenDetail on (MagOntDetMagOntGid = MagOntGid)
      // Verkooporder ophalen, liefst uit bestellingregelspec., anders uit magazijndetail
      left outer join tabBestelRegelDetail on (BrdGid = MagOntDetBrdGid)
      inner join      (tabOrderRegel
                       inner join tabOrderKop on (OrkGid = OrrOrkGid)
                      ) on (OrrGid = isnull(brdOrrGid, MagOntDetOrrGid))
    where MagOntMokGid = @MokGid
      and OrkGid is not null
    order by OrkNummer
  FOR READ ONLY
  do
    set @Volgorde = @Volgorde + 1;
    insert into tabTeFacturerenOrders (TfoSessieFbGid, TfoTeFactVolgOrder, TfoTeFactOrkGid, TfoTeFactOrdNummer)
                               values (@FbGid, @Volgorde, @OrkGid, @OrkNummer);
    set @TfoGid = @@Identity;
    //call trace('Opnemen in TeFactureren! @TfoGid = ' + string(@TfoGid)+', @MokGid = '+string(@MokGid)+', @OrkGid='+string(@OrkGid));
    insert into tabTeFacturerenOrderRegels(tforTfoGid, tforOrrGid, tforAantalAflevering)
    select @TfoGid, OrrGid, sum(MagOntLocAantal)
    from
      tabMagazijnOntvangsten
      inner join tabMagazijnOntvangstenDetail     on (MagOntDetMagOntGid    = MagOntGid)
      inner join tabMagazijnOntvangstLocatieSerie on (MagOntLocMagOntDetGid = MagOntDetGid)
      // Verkooporder ophalen, liefst uit bestellingregelspec., anders uit magazijndetail
      left outer join tabBestelRegelDetail on (BrdGid = MagOntDetBrdGid)
      inner join      (tabOrderRegel
                       inner join tabOrderKop on (OrkGid = OrrOrkGid)
                      ) on (OrrGid = isnull(brdOrrGid, MagOntDetOrrGid))
    where MagOntMokGid = @MokGid
      and OrkGid = @OrkGid
    group by OrrGid;
  end for;

  // Standaard verwerking aanroepen met ander documentsoort
  call FactStartMaakFacturen(@FbGid,
                             6, /*DocSoort=DirecteLevering*/
                             35, /*Pakbon voor DL*/
                             1, /*Sorteer op debiteur*/
                             1, /*Ascending*/
                             @RapNummer, /*Layout. Indien nul, dan uit vaste gegevens*/
                             @BoekDatum,
                             null, /*Pakbon, dus dit is de t/m leverdatum*/
                             0, /*Bedrag betaald*/
                             0, /*Verschil afboeken*/
                             null /*OUT-variabele voor de @BjGid*/
                            );

  // En de tussentabel weer opruimen
//!@#Straks weer aan!  delete tabTeFacturerenOrders where TfoSessieFbGid = @FbGid;

  set @@ErrorTextProcedure = '<-' + @ErrText;
  //call TraceEind(@@ErrorTextProcedure);
end;

//$Workfile: DirLevVerwerkPakbonNummersInVoorrMut.sp $ $Revision: 1 $ $Modtime: 13-10-10 13:36 $'

if exists (select 1 from sys.sysProcedure where proc_name='DirLevVerwerkPakbonNummersInVoorrMut') then
  drop procedure DirLevVerwerkPakbonNummersInVoorrMut;
end if;

create procedure DirLevVerwerkPakbonNummersInVoorrMut(
  in @fbGid     integer,
  in @MokNummer numeric(10,0)
)
begin
  set @@ErrorTextProcedure = 'DirLevVerwerkPakbonNummersInVoorrMut( @fbGid='+string(@fbGid)+', @MokNummer = '+string(@MokNummer);
  //call TraceBegin( @@ErrorTextProcedure );

  set @@VoorraadMutatieChangeAllowed = isnull(@@VoorraadMutatieChangeAllowed, 0) + 1;
  update tabVoorraadMutatie
  set    VrdMutUitleverOntvangstNr = (select first FkFactuurNummer
                                      from   tabFactuurKop
                                             inner join tabFactuurReferentie on (frefFkGid = FkGid)
                                      where      FkFbGid = @FbGid
                                             and frefOrderNummer   = VrdMutOrderBestelNr
                                             and FkDirLevMokNummer = @MokNummer)
  where     VrdMutSoort = 12 /*DL-ontv.DoorDeb*/
        and VrdMutUitleverOntvangstNr = @MokNummer
        and vrdMutDirLevKenmerk = @MokNummer;
  set @@VoorraadMutatieChangeAllowed = @@VoorraadMutatieChangeAllowed - 1;

  //call TraceEind( @@ErrorTextProcedure );
end;

create or replace procedure DumpInfo()
begin
  declare local temporary table tmpProperties (PropId integer, PropName nchar(250), PropValue nchar(250));

  declare @Teller integer;

  set @@ErrorTextProcedure = 'DumpInfo';
  //call TraceBegin(@@ErrorTextProcedure);

  execute immediate 'unload select * from tabRegistry to ''c:\Quad_Regsitry.txt''';
  execute immediate 'unload select * from tabLicMask to ''c:\Quad_LicMask.txt''';
  execute immediate 'unload select * from tabLogLicentie to ''c:\Quad_LogLicentie.txt''';
  execute immediate 'unload select * from sysOptions to ''c:\Quad_Sysoptions.txt''';

  set @Teller = 1;
  while @Teller<=10000 loop
    if property_name(@Teller) is not null then
       if db_property(@Teller) is not null then
         insert into tmpProperties select @Teller, property_name(@Teller), db_property(@Teller)
       end if;
       if property(@Teller) is not null then
         insert into tmpProperties select @Teller, property_name(@Teller), property(@Teller)
       end if;
       if connection_property(@Teller) is not null then
         insert into tmpProperties select @Teller, property_name(@Teller), connection_property(@Teller)
       end if;
    end if;
    set @Teller = @Teller + 1;
  end loop;
  execute immediate 'unload select * from tmpProperties to ''c:\Quad_Properties.txt''';

  execute immediate 'unload select ''@@ModuleCodes'', @@ModuleCodes union select ''@@Gebruikercode'', @@Gebruikercode to ''c:\Quad_Variables.txt''';

  set @@ErrorTextProcedure = 'DumpInfo';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure EerstVolgendBoekjaar(in @BjGid integer, out @VolgendBjGid integer)
begin
  declare @MinGroterDatum date;

  set @@ErrorTextProcedure = 'EerstVolgendBoekjaar > @BjGid='+string(@BjGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @VolgendBjGid = null;

  select first BjGid into @VolgendBjGid
  from   tabBoekjaar
  where  BjBeginDatum > (select BjEindDatum from tabBoekjaar where BjGid = @BjGid)
  order by BjBeginDatum;

  set @@ErrorTextProcedure = 'EerstVolgendBoekjaar > @VolgendBjGid='+string(@VolgendBjGid);
  //call TraceBegin(@@ErrorTextProcedure);

end;


//Omdat er views van elkaar afhankelijk zijn, moeten we bij het maken van een nieuwe database, onderstaande stored procedure draaien nadat de views zijn gecreerd.
//Omdat sybase bijhoudt welke views van elkaar afhankelijk zijn, wordt er bij in de verkeerde volgorde toevoegen van views, op disabled gezet en kunnen de afhankelijkheden niet worden bepaald.
//Deze stored proc zorgt er dus voor dat dit bijgewerkt wordt.

create or replace procedure EnableViews()
begin
  set @@ErrorTextProcedure = 'Begin EnableViews';
  //call Trace(@@ErrorTextProcedure);

  for @Cursor AS CURSOR_views CURSOR FOR
    select     table_name @ViewName
    from       systable
    inner join sysobject on (systable.object_id = sysobject.object_id)
    inner join sysuser   on (creator = user_id and user_name = 'KingSystem')
    where      table_type = 'view' and status <> 1
  for read only
  do
    execute immediate 'alter view ' || @ViewName || ' enable';
  end for;

  set @@ErrorTextProcedure = 'Einde EnableViews';
  //call Trace(@@ErrorTextProcedure);
end;


create or replace Procedure EuroKonversieJournaal(in @VanafBjGid integer, in @BoekingenOmrekenen smallint, in @RksKoersVerschilGid integer)
begin
  declare @IsolationLevel smallint;
  declare @BoekGangGid integer;
  declare @JpGid integer;
  declare @OspGid integer;
  declare @JrGid integer;
  declare @BoekDatum DateTime;
  declare @BjGid integer;
  declare @DgbGid integer;
  declare @Pernr integer;
  declare @BeginDatum date;
  declare @IsGewijzigd smallint;
  declare @BedragErBij numeric(15,2);
  declare @BedragErBijBasis numeric(15,2);
  declare @ValNummer integer;
  declare @AantalJp integer;
  declare @Current integer;
  declare @BoekzijdeHulpRekening integer;
  declare @IsCreditBoeking integer;
  declare @DraaiOm integer;
  declare @LaatsteJrGid integer;
  declare @GegevenOms nchar(40);

  declare @EuroconversieAfrondingTekst long nvarchar;

  declare  cursor_Boekingsgangen dynamic scroll cursor for
    select BoekGangGid from tabBoekingsGang order by BoekGangGid;
  declare  cursor_JournaalPosten dynamic scroll cursor for
    select JpGid, JpBjGid, JpPernr, JpDgbGid from tabJournaalPost where JpBoekGangGid = @BoekGangGid and OrigineelJpId is null order by JpGid;
  declare  cursor_tabOpenstaandePosten dynamic scroll cursor for
    select OspGid, OspValNummer, (OspFactuurBedragVoorlopig + OspFactuurBedragDefinitief) - (OspBetaaldBedragVoorlopig + OspBetaaldBedragDefinitief)
    from   tabJournaalPost inner join tabJournaalregel on (JrJpGid = JpGid) inner join tabOpenstaandePost on (OspGid = JrOspGid), tmpOspGid where OspIsVervallen = 0 and OspGid = Gid and JpGid = @JpGid;

  declare local temporary table tmpOspGid (Gid integer, primary key(Gid));

  set @@ErrorTextProcedure = 'Begin EuroKonversieJournaal > @VanafBjGid='+string(@VanafBjGid)+', @BoekingenOmrekenen='+string(@BoekingenOmrekenen)+', @RksKoersVerschilGid='+string(@RksKoersVerschilGid);
  //call Trace(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  set @EuroconversieAfrondingTekst = _A('Euroconversie afronding');

  call ProgressSet(null, null, _U('Boekingsgangen'));

  set @BoekingenOmrekenen = IsNull(@BoekingenOmrekenen, 0);

  select DefaultBoekZijde into @BoekzijdeHulpRekening from tabRekeningschema where RksGid = @RksKoersVerschilGid; // Dit is de rekening waar de afrondingen op komen!

  set @@JournaalVolgNummersNietVerlagen = 1;

  if @BoekingenOmrekenen <> 0 then
    select count(*) into @AantalJp from tabJournaalPost;
    call ProgressCreate( 0, @AantalJp+2, _U('Converteren valuta naar euro'));
    //call Trace('@AantalJp='+string(@AantalJp));
  end if;

  //call Trace('Boekingsgang van laatste journaalregel in boekjaar zetten');
  update tabBoekjaar
  set    bjAfsluitJrGid = JpBoekgangGid
  from   tabJournaalRegel inner join tabJournaalpost on (JpJrGid = JrGid)
  where  JrGid = bjAfsluitJrGid;

  //call Trace('Bepaal de datum vanaf wanneer de boekingen omgerekend moeten worden naar de Euro');
  select BjBeginDatum into @BeginDatum from tabBoekjaar where BjGid = @VanafBjGid;

  set @@OverRuleLock = 1;
  set @@AllowChangingOspValuta = 1;

  //call Trace('Voordat we gaan omrekenen eerst bepalen welke openstaande posten zijn vervallen, om achteraf eventueel factuubedrag gelijk aan betaaldbedrag te maken');
  if @BoekingenOmrekenen <> 0 then
    insert into tmpOspGid(Gid) select OspGid from tabOpenstaandePost where OspIsVervallen <> 0;
  end if;

  //call Trace('Eerst alle regelnummers verwijderen');
  set @@FiredByTriggerJournaalregel = 1;
  update tabjournaalregel set regelnummer = null;
  set @@FiredByTriggerJournaalregel = 0;

  // Tijdelijk *geen* koerscoorectieboekingen maken (maken we op het laatst via herwaardering!)
  set @@GeenKoersCorrectie = 1;

  //call Trace('Alle boekingsgangen doorlopen');
  call ProgressSet(null, null, _U('Journaalposten'));
  set @BoekGangGid = 0;
  open cursor_Boekingsgangen;
  loopje1:
  loop
    Fetch next cursor_Boekingsgangen into @BoekgangGid;
    if sqlstate = '02000' then
      leave loopje1;
    end if;

    update tabBoekingsGang set BoekGangInGebruik = 1 where BoekGangGid = @BoekGangGid;

    //call Trace('Alle journaalposten in de boekingsgangen doorlopen');
    set @JpGid = 0;
    open cursor_JournaalPosten;
    loopje2:
    loop
      Fetch next cursor_JournaalPosten into @JpGid, @BjGid, @Pernr, @DgbGid ;
      if sqlstate = '02000' then
        leave loopje2;
      end if;

      if @BoekingenOmrekenen <> 0 then
        call ProgressAdd(1);
        select ProgressValue into @Current from tabprogress where progressconnid =connection_property('number');
        //call Trace('@Current='+string(@Current));
      end if;

      //call Trace('Controleren welk soort dagboek het is... Als het de beginbalans is, dan de 1e periode gebruiken');
      if exists(Select 1 from tabDagboek where DgbGid = @DgbGid and DagboekSoort = 5 ) then
        set @PerNr = 0
      end if;
      set @@IgnoreProgressAdd = 1;
      update tabJournaalPost set JpIsInGebruik=1 where JpGid=@JpGid;
      set @@IgnoreProgressAdd = 0;

      //call Trace('Als de boekingenomgerekend moeten worden en het boekjaar van deze journaalpost ligt na de meegegeven begindatum, dan ook boekbedrag omrekenen naar Euro valuta');
      if @BoekingenOmrekenen <> 0 then
        //call Trace('@BjGid='+string(@BjGid)+', @BeginDatum='+string(@BeginDatum));
        if exists (select 1 from tabBoekjaar where BjGid = @BjGid and BjBeginDatum >= @BeginDatum) then

          //call Trace('Boekbedragen van alle journaalregels in de journaalpost opnieuw berekenen');
          update tabJournaalRegel
          set    JrValNummer    = @@EuroValutaNummer,
                 JrValutaBedrag = ValutaOmrekenen(JrValNummer, JrValutaBedrag, @@EuroValutaNummer,  @BjGid, @Pernr, 2)
          from   tabValuta inner join tabHulpEuroValuta on (HlpEuroValNummer = ValNummer and HlpEuroValConverteer <> 0)
          where  JrJpGid = @JpGid and ValNummer = JrValNummer;

          //call Trace('Boekbedragen van alle hulprekeningen in de journaalpost opnieuw berekenen');
          update tabHulpRekening
          set    HulpRekValNummer           = @@EuroValutaNummer,
                 HulpRekValutaBedrag        = ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, @@EuroValutaNummer,  @BjGid, @Pernr, 2)
          from   tabJournaalRegel, tabValuta inner join tabHulpEuroValuta on (HlpEuroValNummer = ValNummer and HlpEuroValConverteer <> 0)
          where  JrJpGid = @JpGid and HulpRekJrGid = JrGid and HulpRekValNummer = ValNummer;

        end if;
      end if;

      //call Trace('Tegenwaarden van alle journaalregels in de journaalpost opnieuw berekenen');
      update tabJournaalRegel
      set    JrBasisBedrag = ValutaOmrekenen(JrValNummer, JrValutaBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2)
      where  JrJpGid = @JpGid;

      //call Trace('Tegenwaarden van alle hulprekeningen in de journaalpost opnieuw berekenen');
      update tabHulpRekening
      set    HulpRekBasisBedrag =         ValutaOmrekenen( HulpRekValNummer, HulpRekValutaBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2),
             HulpRekBedragInJrValNummer = ValutaOmrekenen( HulpRekValNummer, HulpRekValutaBedrag, JrValNummer,         @BjGid, @PerNr, 2)
      from   tabJournaalRegel
      where  JrJpGid = @JpGid and HulpRekJrGid = JrGid;

      set @@IgnoreProgressAdd = 1;
      update tabJournaalPost set JpIsInGebruik=0 where JpGid=@JpGid;
      set @@IgnoreProgressAdd = 0;

      // Bestaan er records in tabOpenstaandePost die niet vervallen zijn, maar wel in tmpOspGid staan
      // Dit betekent dat ze voor de conversie vervallen waren maar door een afrondingsverschil niet meer
      // Dus moeten we het betaald bedrag gelijk aan het faktuurbedrag maken en dit gaat door te kijken of
      // in de huidige JP de laatste betaling zit, zo ja dan moeten we deze betaling verhogen of verlagen.
      open cursor_tabOpenstaandePosten;
      loopje3:
      loop
        Fetch next cursor_tabOpenstaandePosten into @OspGid, @ValNummer, @BedragErBij;
        if sqlstate = '02000' then
          leave loopje3;
        end if;

        //call Trace('Kijk of er in de huidige journaalpost een journaalregel zit die een laatste betaling is van de huidige openstaande post');

        // Lees regel van laatste betaling
        set @LaatsteJrGid = null;
        select   first JrGid into @LaatsteJrGid
         from     tabBoekingsgang inner join tabJournaalPost on (JpBoekgangGid = BoekgangGid) inner join tabJournaalregel on (JrJpGid = JpGis)
         where    jpBjGid = @BjGid and JrOspGid=@OspGid //and IsBetaling(JrRksGid, IsCreditBoeking) = 1 ACW 27-11-2001: We moeten ook de correctieboekingen meenemen, dus NIET letten op isbetaling!!
         order by JpBoekganggid desc, JpGid desc, JrGid desc;

        set @JrGid = null;

        select JrGid, IsCreditBoeking into @JrGid, @IsCreditBoeking from tabJournaalRegel where JrJpGid = @JpGid and JrGid = @LaatsteJrGid;
        if @JrGid is not null then

          set @@IgnoreProgressAdd = 1;
          update tabJournaalPost set JpIsInGebruik=1 where JpGid = @JpGid;
          set @@IgnoreProgressAdd = 0;

          //update tabJournaalregel set JrValutaBedrag = JrValutaBedrag + @BedragErBij where JrGid = @JrGid;
          //ACW 23-11-2001: ipv. het boekbedrag van de betaling aan te passen maken we een nieuwe boekingsregel met hulprekening *betalingsverschil*

          if @ValNummer = @@BasisValutaNummer then
            set @BedragErBijBasis = @BedragErBij;
          else
            set @BedragErBijBasis = ValutaOmrekenen( @ValNummer, @BedragErBij, @@BasisValutaNummer, @BjGid, @Pernr, 2)
          end if;
          //call Trace('Bedrag dat extra moet worden geboekt; @JrGid='+string(@JrGid)+', @OspGid='+string(@OspGid)+', @BedragErBijBasis='+string(@BedragErBijBasis)+', @BedragErBij='+string(@BedragErBij)+', @ValNummer='+string(@ValNummer)+', @IsCreditBoeking='+string(@IsCreditBoeking));
          // Eerst de journaalregel toevoegen
          insert into tabJournaalregel(
            JrJpGID, JrRksGID, JrOspGid, OmsJournaalRegel,          JrReferentie, SoortBoeking, IsCreditBoeking,
            JrValNummer, JrValutaBedrag, JrBasisBedrag,  JrFactuurDatum, JrVervalDatum, JrBetalingsKenmerk)
          select
            JrJpGid, JrRksGid, JrOspGid, @EuroconversieAfrondingTekst, JrReferentie, 0, IsCreditBoeking,
            @ValNummer, @BedragErBij, @BedragErBijBasis, JrFactuurDatum, JrVervalDatum, JrBetalingsKenmerk
          from tabjournaalregel where jrGid = @JrGid;

          set @IsCreditBoeking = 1 - @IsCreditBoeking; // We moeten tegenboeken, dus omdraaien!
          set @DraaiOm = 0;
          // Bepalen wat we waar moeten boeken
          case @BoekzijdeHulpRekening
          when 0 then // Debet
            if @IsCreditBoeking = 1 then
              // Van creditboeking een debetboeking maken
              set @IsCreditBoeking  = 0;
              set @DraaiOm = 1;
            end if;
          when 1 then // Credit
            if @IsCreditBoeking = 0 then
              // Van debetboeking een creditboeking maken
              set @IsCreditBoeking  = 1;
              set @DraaiOm = 1;
            end if;
          else // geen voorkeur of afhankelijk van dagboek -> aan kant van saldo
            if @BedragErBijBasis < 0 then
              // Bedrag < 0, dus saldo staat aan de andere kant
              set @IsCreditBoeking  = 1 - @IsCreditBoeking;
              set @DraaiOm = 1;
            end if;
          end case;
          if @DraaiOm = 1 then
            set @BedragErBijBasis = -@BedragErBijBasis;
            set @BedragErBij      = -@BedragErBij;
          end if;

          //call Trace('Hulprekeningboeking; @BedragErBijBasis='+string(@BedragErBijBasis)+', @BedragErBij='+string(@BedragErBij)+', @ValNummer='+string(@ValNummer)+', @IsCreditBoeking='+string(@IsCreditBoeking));
          // Daarna de hulprekening toevoegen (zorgt ervoor dat het bedrag in basisvaluta weer wordt afgeboekt)
          insert into tabHulpRekening( HulpRekJrGid, HulpRekSoort,            HulpRekRksGid,        HulpRekValNummer,    HulpRekIsCredit,  HulpRekBasisBedrag, HulpRekValutaBedrag, HulpRekBedragInJrValnummer)
          values(                      @@JrGid,      2 /*betalingsverschil*/, @RksKoersVerschilGid, @@BasisValutaNummer, @IsCreditBoeking, @BedragErBijBasis,  @BedragErBijBasis,   @BedragErBij);

          // En journaalregel buiten gebruik nemen
          set @@IgnoreProgressAdd = 1;
          update tabJournaalPost set JpIsInGebruik=0 where JpGid=@JpGid;
          set @@IgnoreProgressAdd = 0;

        end if;
      end loop loopje3; //OpenstaandePosten-loop
      close cursor_tabOpenstaandePosten;
      call ProgressAdd( 1 );

    end loop loopje2; //JournaalPosten-loop
    close cursor_JournaalPosten;

    update tabBoekingsGang set BoekGangInGebruik = 0 where BoekGangGid = @BoekGangGid;

  end loop loopje1; //boekingsgangen-loop
  close cursor_Boekingsgangen;

  //call Trace('Laatste regel van de betreffende boekingsgang weer zetten');
  update tabBoekjaar
  set    bjAfsluitJrGid = JrGid
  from   tabJournaalRegel inner join tabJournaalpost OuterJp on (OuterJp.JpGid = JrJpGid)
  where  JpBoekgangGid = bjAfsluitJrGid
         and RegelNummer = (select max(RegelNummer) from tabJournaalRegel where JrJpGid = OuterJp.JpGid);
  if @BoekingenOmrekenen <> 0 then
    call ProgressAdd(1);
  end if;

  //Zo gooi nu alle lege rekeningsaldi weg, dit zijn dus alle valutas waarvan de boekingen geconverteerd zijn naar Euro in een of meerdere boekjaren
  call ProgressSet(null, null, _U('Rekeningsaldi'));
  if @BoekingenOmrekenen <> 0 then
    delete tabRekeningSaldo
    where  RekSaldoBjGid     in (select BjGid from tabBoekjaar where BjBeginDatum >= @BeginDatum) and
           RekSaldoValnummer in (select HlpEuroValNummer from tabHulpEuroValuta where HlpEuroValConverteer <> 0);
    call ProgressAdd(1);
  end if;
  delete tabHulpEuroKoers;
  delete tabHulpEuroValuta;

  set @@OverRuleLock = 0;
  set @@AllowChangingOspValuta = 0;

  set @@GeenKoersCorrectie = 0;

  set @@JournaalVolgNummersNietVerlagen = 0;


  // Als laatste in alle aangepaste boekjaren een herwaardering draaien
  //call Trace('Herwaarderen!!');
  call ProgressSet(null, null, _U('Herwaarderen'));

  if @BeginDatum is null then
    // Als we geen begindatum hadden, dan moeten we dus elk boekjaar doen!!
    select min(BjBeginDatum) into @BeginDatum from tabBoekjaar;
    set @GegevenOms = _A('tgv. wijzigen basisvaluta');
  else
    set @GegevenOms = _A('tgv. converteren valuta''s');
  end if;

  // Voor de zekerheid de oude valutakoersen verwijderen
  delete from tabHulpKoers;
  // En voor elk boekjaar in de range een herwaardering uitvoeren
  for @Cursor AS CURSOR_boekjaren CURSOR FOR
    select BjGid @BoekjaarGid from tabBoekjaar where BjBeginDatum >= @BeginDatum order by BjBeginDatum
  for read only
  do
    //call Trace('Herwaardering van @BoekjaarGid='+string(@BoekjaarGid));
    call Tijdelijkekoersen(@BoekjaarGid, null, 0);
    call ValutaHerberekenen(@BoekjaarGid, 1, @GegevenOms);
  end for;

  if @BoekingenOmrekenen <> 0 then
    call ProgressDelete;
  end if;


  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  set @@ErrorTextProcedure = 'Einde EuroKonversieJournaal';
  //call Trace(@@ErrorTextProcedure);
end;


create or replace procedure EuroKonversieTabellenAlleenVullen(in @BjGid integer)
begin
  set @@ErrorTextProcedure = 'EuroKonversieTabellenAlleenVullen > @BjGid='+string(@BjGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //Eventuele verwijderde valutaas weghalen uit hulptabel
  delete from tabHulpEuroValuta where hlpEuroValNummer not in (select valnummer from tabvaluta);
  delete from tabHulpEuroKoers where hlpEuroKrsValNummer not in (select valnummer from tabvaluta);

  //Eventuele toegevoegde valutaas toevoegen aan hulptabel
  insert into tabHulpEuroValuta(hlpEuroValNummer, hlpEuroValIsBasis, hlpEuroValIsVast, hlpEuroValKoersTovEuro, hlpEuroValVastVanDatum, hlpEuroValConverteer)
  select ValNummer, 0, NaarEuro, (if NaarEuro<>0 then ValKoersTovEuro endif), (if NaarEuro<>0 then ValEuroVanafDatum endif), 0 from tabValuta where ValNummer not in ( select hlpEuroValNummer from tabHulpEuroValuta );

  insert into tabHulpEuroKoers(hlpEuroKrsValNummer, hlpEuroKrsBjGid, hlpEuroKrsPerNr, hlpEuroKrsKoers, hlpEuroKrsKoersTOVeuro, hlpEuroKrsEenheid)
  select hlpEuroValNummer, ValBjGid, ValPernr, 1, krsKoersTovEuro, KrsEenheid from tabValutaKoers, tabHulpEuroValuta
  where  hlpEuroValNummer=KrsValNummer and ValBjGid=@BjGid and hlpEuroValNummer not in ( select hlpEuroKrsValNummer from tabHulpEuroKoers );

  set @@ErrorTextProcedure = 'EuroKonversieTabellenAlleenVullen';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure EuroKonversieTabellenVullen(in @BjGid integer)
begin
  set @@ErrorTextProcedure = 'EuroKonversieTabellenVullen > @BjGid='+string(@BjGid);
  //call TraceBegin(@@ErrorTextProcedure);

  delete tabHulpEuroKoers;
  delete tabHulpEuroValuta;

  call EuroKonversieTabellenAlleenVullen(@BjGid);

  set @@ErrorTextProcedure = 'EuroKonversieTabellenVullen';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: EuroKonversieValutaTabel.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

if exists (select 1 from sys.sysProcedure where proc_name='EuroKonversieValutaTabel') then
  drop procedure EuroKonversieValutaTabel;
end if;

create procedure EuroKonversieValutaTabel(in @BjGid integer, in @EuroValNummer integer, in @KoersVerschilRksGid integer )
begin
  //Let op: hier wordt 12x een ProgressAdd gedaan!! Als dit veranderd, dan in Delphi-source aanpassen!!
  declare @IsolationLevel    smallint;
  declare @OudeBasisValuta   integer;
  declare @NieuweBasisValuta integer;

  set @@ErrorTextProcedure = 'EuroKonversieValutaTabel > @BjGid='+string(@BjGid)+', @EuroValNummer='+String(@EuroValNummer)+', @KoersVerschilRksGid='+string(@KoersVerschilRksGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  //Alle records die nog niet in de tabel staan toevoegen (omdat we over meerdere jaren werken)
  call ProgressAdd( 1 );
  insert into tabHulpEuroKoers(hlpEuroKrsValNummer, hlpEuroKrsBjGid, hlpEuroKrsPerNr)
  select KrsValNummer, ValBjGid, ValPernr
  from   tabValutaKoers
  where  ValBjGid = @BjGid and KrsValNummer not in (select hlpeurokrsvalnummer from tabhulpeurokoers);


  call ProgressAdd( 1 );
  insert into tabHulpEuroKoers(hlpEuroKrsValNummer, hlpEuroKrsBjGid, hlpEuroKrsPerNr)
  select KrsValNummer, ValBjGid, ValPernr
  from   tabValutaKoers
  where  ValBjGid <> @BjGid;
  call ProgressAdd( 1 );

  select ValNummer        into @OudeBasisValuta    from tabvaluta         where IsBasisValuta     <> 0;
  select hlpEurovalnummer into @nieuwebasisvaluta  from tabHulpEuroValuta where hlpEuroValIsBasis <> 0;

  if @nieuwebasisvaluta is null then
    set @nieuwebasisvaluta = @OudeBasisValuta
  end if;

  if @OudeBasisValuta <> @nieuwebasisvaluta then
    //Reset de velden BasisValuta en WordtEuro
    update tabValuta set IsBasisValuta = 0, KoersVerschilRksGid = @KoersVerschilRksGid where IsBasisValuta <> 0;
    update tabValuta set IsBasisValuta = 0, NaarEuro = 0;

    //wijzig IsBasis naar de nieuwe basisvaluta
    update tabValuta set IsBasisValuta = 1, KoersVerschilRksGid = Null where ValNummer = @NieuweBasisValuta;

  end if;

  //Wijzig de WordtEuro naar de nieuwe WordtEuro met de datum
  update tabValuta
  set    NaarEuro = hlpEuroValIsVast,
         ValEuroVanafDatum = HlpEuroValVastVanDatum
  from   tabHulpEuroValuta
  where  ValNummer = hlpEuroValNummer;
  call ProgressAdd( 1 );

  if ( @EuroValNummer >= 0 ) then
    if exists( select 1 from tabvaluta where IsEuro=1 and ValNummer <> @EuroValNummer or 1 not in (Select IsEuro from tabvaluta)) then
      /*Wijzig de IsEuro eventueel naar de nieuwe IsEuro als er nog geen euro is of een andere is de euro*/
      update tabValuta set IsEuro = 0 where IsEuro <> 0;
    end if;
    update tabValuta set IsEuro = 1, NaarEuro = 1, ValKoersTovEuro = 1, ValEuroVanafDatum='1999-01-01' where ValNummer = @EuroValNummer;
    update tabHulpEuroKoers set hlpEuroKrskoerstoveuro = 1 where hlpEuroKrsValNummer = @EuroValNummer;
    update tabHulpEuroValuta set hlpEuroValKoersTovEuro=1 where hlpEuroValNummer = @EuroValNummer;
  end if;

  call ProgressAdd( 1 );

  //Koers van de euro tov. basis zelf instellen
  update tabHulpEuroKoers ValutaPer
  set    ValutaPer.hlpEuroKrskoers = BasisPer.hlpEuroKrskoerstoveuro
  from   tabHulpEuroKoers ValutaPer inner join tabHulpEuroKoers BasisPer on (BasisPer.HlpEuroKrsValNummer = @NieuweBasisValuta and ValutaPer.hlpEuroKrsBjGid = BasisPer.hlpEuroKrsBjGid and ValutaPer.hlpEuroKrsPerNr = BasisPer.hlpEuroKrsPerNr )
  where  ValutaPer.HlpEuroKrsValNummer = @EuroValNummer;

  call ProgressAdd( 1 );

  //De eurokoers van de EMU-valuta leegmaken indien deze moet worden berekend, juist vullen indien deze een vaste koers heeft
  //ACW 20-11-2000: Alleen op null zetten als het ook niet de (nieuwe) basisvaluta is!
  update tabHulpEurokoers
  set    hlpEuroKrskoerstoveuro = if begindatum < hlpEuroValVastVanDatum and hlpEuroKrsValNummer <> @NieuweBasisValuta then null else hlpEuroValKoersTovEuro endif
  from   tabPeriode, tabValuta, tabHulpEuroValuta
  where  PerBjGid = hlpEuroKrsBjGid and (PerNr=if hlpEuroKrsPerNr = 0 then 1 else hlpEuroKrsPerNr endif) and
         ValNummer = hlpEuroKrsValNummer and hlpEuroValNummer = hlpEuroKrsValNummer and hlpeurovalisvast = 1 and hlpEuroKrsValNummer<>@euroValNummer;

  call ProgressAdd( 1 );

  //Dan de koers tov. basis op basis van de ingevulde eurokoers of opnieuw berekenen
  update tabHulpEuroKoers DezeValutaPer
  set    DezeValutaPer.hlpEuroKrskoers = if isnull(DezeValutaPer.hlpEuroKrsKoersTovEuro,0)<>0 and isnull(NieuweBasisPer.hlpEuroKrsKoersTovEuro,0)<>0 then
                                          //Beide eurokoersen zijn bekend, dus de nieuwe koers via de euro berekenen
                                          lesser( 999999.99, DezeValutaPerOud.KrsEenheid * NieuweBasisPer.hlpEuroKrsKoersTovEuro / DezeValutaPer.hlpEuroKrsKoersTovEuro )
                                        else
                                          if @OudeBasisValuta <> @NieuweBasisValuta then
                                            //Basisvaluta is gewijzigd -> aanpassen van de valuta
                                            lesser( 999999.99, ( DezeValutaPerOud.Koers * nieuwebasisPerOud.Krseenheid ) / ( nieuwebasisperOud.koers ) )
                                          else
                                            //Geen wijziging
                                            DezeValutaPerOud.Koers
                                          endif
                                        endif
  from   tabHulpEurokoers            DezeValutaPer
         inner join tabValutaKoers   NieuweBasisPerOud on ( NieuweBasisPerOud.KrsValNummer     = @NieuweBasisValuta                and NieuweBasisPerOud.ValBjGid     = DezeValutaPer.hlpEuroKrsBjGid and NieuweBasisPerOud.ValPerNr     = DezeValutaPer.hlpEuroKrsPerNr )
         inner join tabHulpEuroKoers NieuweBasisPer    on ( NieuweBasisPer.hlpEuroKrsValNummer = @NieuweBasisValuta                and NieuweBasisPer.hlpEuroKrsBjGid = DezeValutaPer.hlpEuroKrsBjGid and NieuweBasisPer.hlpEuroKrsPerNr = DezeValutaPer.hlpEuroKrsPerNr )
         inner join tabValutaKoers   DezeValutaPerOud  on ( DezeValutaPerOud.KrsValNummer      = DezeValutaPer.hlpEuroKrsValNummer and DezeValutaPerOud.ValBjGid      = DezeValutaPer.hlpEuroKrsBjGid and DezeValutaPerOud.ValPerNr      = DezeValutaPer.hlpEuroKrsPerNr )
  order by if DezeValutaPer.hlpEuroKrsValNummer= @EuroValNummer then 0 else if DezeValutaPer.hlpEuroKrsValNummer= @NieuweBasisValuta then 2 else 1 endif endif;
  call ProgressAdd( 1 );

  //De koers tov. euro (als de koers nog niet bekend was)
  update tabHulpEuroKoers ValutaPer
  set    ValutaPer.hlpEuroKrskoerstoveuro = if ValutaPer.hlpEuroKrsValNummer = @EuroValNummer then
                                             1
                                           else
                                             if ValutaPer.hlpEuroKrsValNummer = @NieuweBasisValuta and isnull(EuroPer.hlpEuroKrskoers,0)<>0 then    //ACW 16-11-2000: Als basisvaluta, dan altijd de koers van de euro overnemen
                                               EuroPer.hlpEuroKrskoers / EuroPer.hlpEuroKrsEenheid
                                             else
                                               lesser( 999999.99, valutaPer.hlpEuroKrsEenheid * basisPer.hlpEuroKrskoerstoveuro / ValutaPer.hlpEuroKrskoers )
                                             endif
                                           endif
  from   tabHulpEuroKoers ValutaPer
         inner join tabHulpEuroKoers BasisPer on ( BasisPer.hlpEuroKrsValNummer = @NieuweBasisValuta and BasisPer.hlpEuroKrsBjGid = ValutaPer.hlpEuroKrsBjGid and BasisPer.hlpEuroKrsPerNr = ValutaPer.hlpEuroKrsPerNr )
         left outer join tabHulpEuroKoers EuroPer  on ( EuroPer.hlpEuroKrsValNummer = @euroValNummer      and EuroPer.hlpEuroKrsBjGid  = ValutaPer.hlpEuroKrsBjGid and EuroPer.hlpEuroKrsPerNr  = ValutaPer.hlpEuroKrsPerNr )
  where  isnull(ValutaPer.hlpEuroKrskoerstoveuro,0)=0
  order by if ValutaPer.hlpEuroKrsValNummer= @EuroValNummer then 2 else if ValutaPer.hlpEuroKrsValNummer= @NieuweBasisValuta then 0 else 0 endif endif;
  call ProgressAdd( 1 );

  //En natuurlijk de valutatabel zelf updaten
  update tabValutaKoers
  set    Koers = hlpEuroKrsKoers,
         KrsKoersTovEuro = hlpEuroKrsKoersTovEuro
  from   tabHulpEuroKoers
  where  hlpEuroKrsValNummer = KrsValNummer and ValBjGid = hlpEuroKrsBjGid and ValPerNr  = hlpEuroKrsPerNr;
  call ProgressAdd( 1 );

  //Voor alle valutas die naar de euro gaan de eenheid op 1 zetten als ook de basisvaluta de euro is/wordt
  if @NieuweBasisValuta = @EuroValNummer then
    //En de eenheid op 1 zetten als de basisvaluta ook de euro is.
    update tabvalutakoers
    set koers=koers/KrsEenheid
    from tabvaluta
    where valnummer=krsvalnummer;
    update tabValutaKoers
    set KrsEenheid=1;
  else
    if @NieuweBasisValuta <> @OudeBasisValuta and exists(select 1 from tabvaluta where IsEuro = 1) then
      //Update de eurokoers van de nieuwe basisvaluta
      update tabValutaKoers a
      set    a.KrsKoersTovEuro= b.Koers / b.KrsEenheid
      from   tabValutaKoers a, tabValutaKoers b
      where  a.KrsValNummer = @NieuweBasisValuta
             and b.KrsValNummer = (select valnummer from tabvaluta where IsEuro = 1);
    end if;
  end if;

  call ProgressAdd( 1 );

  update tabvalutakoers
  set    KrsKoersTovEuro=1
  from   tabValuta
  where  ValNummer = KrsValNummer
         and IsEuro=1;

  //Vergeten we vooral niet de 'vaste' koers van de eurovalutas te updaten
  update tabValuta
  set    ValKoersTovEuro = hlpEuroValKoersTovEuro
  from   tabValuta
         inner join tabHulpEuroValuta on ( hlpEuroValNummer = ValNummer )
  where  hlpEuroValIsVast = 1;

  //Als de basisvaluta is gewijzigd, dan moeten we ook de koersper van de (nieuwe) basisvaluta resetten
  update tabValutaKoers
  set    KrsEenheid = 1,
         Koers = 1
  from   tabValuta
  where  IsBasisValuta = 1 and ValNummer=KrsValNummer;
  call ProgressAdd( 1 );

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  set @@ErrorTextProcedure = 'EuroKonversieValutaTabel';
  //call TraceEind(@@ErrorTextProcedure);

end;


//----- Procedure kopieert een volledige catalogus inclusief rubrieken, artikelen en teksten per taal
create or replace procedure ExploitatieKopieren(
  in  @BronExplGid  integer,
  in  @DoelExplCode integer,
  in  @DoelExplOms  nchar(40),
  out @DoelExplGid  integer)
begin
  //deze tijdelijke tabel houdt een lijst bij van de originele gidjes (bestaande exploitatiedetails)
  //en de gidjes die bij het kopieren zijn aangemaakt (nieuwe exploitatiedetails).
  //Als de rubrieken eenmaal gekopieerd zijn kunnen de rekeningen aan de hand van deze lijst onder de juiste detail worden toegevoegd.
  declare local temporary table tmpExpdGidDetails(//Voor oude/nieuwe gid
    TmpBronExpdGid integer,   //opslaan BronExpdGid van originele detail
    TmpDoelExpdGid integer    //opslaan DoelExpdGid van kopie detail
  ) on commit preserve rows;

  declare @TmpExpdParentGid integer;

  set @@ErrorTextProcedure = 'ExploitatieKopieren > @BronExplGid=' + string(@BronExplGid) + ', @DoelExplCode=' + string(@DoelExplCode)+ ', @DoelExplOms='+string(@DoelExplOms);
  //call TraceBegin(@@ErrorTextProcedure);

  //variabelen initialiseren
  set @DoelExplGid = null;

  //kopieren starten
  insert into tabExploitatie with auto name
  select
    @DoelExplCode as ExplCode,
    @DoelExplOms  as ExplOms
  from
    tabExploitatie
  where
    ExplGid = @BronExplGid;

  //Exploitatie-indeling gekopieerd?
  if @@RowCount = 1 then
    //ExplGid van nieuwe exploitatie-indeling ophalen als het inserten gelukt is
    set @DoelExplGid = @@Identity;

    //rubrieken kopieren
    for @Cursor AS CURSOR_ExploitatieCopyDetails CURSOR FOR
    select
      ExpdGid        @CurExpdGid,
      ExpdParentGid  @CurExpdParentGid,
      ExpdExpanded   @CurExpdExpanded,
      ExpdLangeOms   @CurExpdLangeOms,
      ExpdNiveau     @CurExpdNiveau,
      ExpdOms        @CurExpdOms,
      ExpdVolgnr     @CurExpdVolgnr
    from
      tabExploitatieDetail
    where
     ExpdExplGid = @BronExplGid
    order by
      ExpdNiveau, ExpdVolgnr
    for read only
    do
      //variabele resetten (wordt in cursorloop gebruikt)
      set @TmpExpdParentGid = null;

      if @CurExpdParentGid is not null then
        select TmpDoelExpdGid into @TmpExpdParentGid from tmpExpdGidDetails where TmpBronExpdGid = @CurExpdParentGid;
      end if;

      //Detail kopieren
      insert into tabExploitatieDetail with auto name
      select
        @TmpExpdParentGid as ExpdParentGid,
        @DoelExplGid      as ExpdExplGid,
        @CurExpdExpanded  as ExpdExpanded,
        @CurExpdLangeOms  as ExpdLangeOms,
        @CurExpdNiveau    as ExpdNiveau,
        @CurExpdOms       as ExpdOms,
        @CurExpdVolgnr    as ExpdVolgnr
      from
        Dummy;

      //kruisverwijzing onthouden
      insert into tmpExpdGidDetails (TmpBronExpdGid,TmpDoelExpdGid) values(@CurExpdGid, @@Identity);
    end for;

    //Rekeningen kopieren
    insert into tabExploitatieRekening (ExprExpdGid, ExprRksGid, ExprSoort)
    select
      TmpDoelExpdGid,
      ExprRksGid,
      ExprSoort
    from
      tabExploitatieRekening
      inner join tmpExpdGidDetails on (ExprExpdGid = TmpBronExpdGid);
  end if;

  set @@ErrorTextProcedure = 'ExploitatieKopieren > @DoelExplGid='+string(@DoelExplGid);
  //call TraceEind(@@ErrorTextProcedure);

end;


//Creeert een balans met alle kolommen tbv export.
create or replace procedure ExportBalans(
  in @BjGid                  integer,
  in @SelecteerOp            smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
  in @VanRksInvoer           nchar(28), //van nummer
  in @TotRksInvoer           nchar(28), //t/m nummer
  in @VanRksZoekcode         nchar(10), //van zoekcode
  in @TotRksZoekcode         nchar(10), //t/m zoekcode
  in @VanRksNaam             nchar(40), //van rksnaam
  in @TotRksNaam             nchar(40), //t/m rksnaam
  in @VanPernr               smallint,
  in @TotPernr               smallint,
  in @SoortBoeking           smallint, //0=definitief, 1=voorlopig, 2=beide
  in @OokNulSaldi            smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
  in @BalansInValuta         smallint, //0=basisvaluta, 1=andere valuta.
  in @BalansValutaCode       nchar(3),  //Valutacode waarin balans moet worden afgedrukt
  in @Uitsplitsen            nchar(8))  //Uitsplitsen deb/cred/kp/kd

result (
  RksInvoer nchar(28), RksNaam nchar(40), RksZoekcode nchar(8), Valcode nchar(3),
  BeginBalansDebet  numeric(15,2), BeginBalansCredit numeric(15,2),  BeginBalansSaldo numeric(15,2),
  VorigBalansDebet  numeric(15,2), VorigBalansCredit numeric(15,2),  VorigBalansSaldo numeric(15,2),
  HuidigBalansDebet numeric(15,2), HuidigBalansCredit numeric(15,2), HuidigBalansSaldo numeric(15,2),
  ProefBalansDebet  numeric(15,2), ProefBalansCredit numeric(15,2),  ProefBalansSaldo numeric(15,2),
  SaldiBalansDebet  numeric(15,2), SaldiBalansCredit numeric(15,2),  SaldiBalansSaldo numeric(15,2),
  Verlies           numeric(15,2), Winst numeric(15,2),              ResultaatSaldo numeric(15,2),
  EindDebet         numeric(15,2), EindCredit numeric(15,2),         EindSaldo numeric(15,2)  )

begin
  declare @Koers               double;
  declare @BalansValutaNummer  integer;

  declare @ParagraafDeb     nchar(2);
  declare @ParagraafCred    nchar(2);
  declare @DebUitsplitsen   smallint; //0=nee, 1=ja
  declare @CredUitsplitsen  smallint; //0=nee, 1=ja
  declare @KstpUitsplitsen  smallint; //0=nee, 1=ja
  declare @KstdUitsplitsen  smallint; //0=nee, 1=ja

  declare @NumDeci          integer;  //0 of 2. Zoals ingesteld bij de gebruikte valuta.

  declare local temporary table tmpExpBalans(
    RksInvoer          nchar(28),
    RksNaam            nchar(40) default '',
    RksZoekcode        nchar(10) default '',
    RksNummer          nchar(10),
    DefaultSoort       smallint,
    KstpGid            integer,
    KstdGid            integer,
    BeginDebet         numeric(15,2),
    BeginCredit        numeric(15,2),
    VorigDebet         numeric(15,2),
    VorigCredit        numeric(15,2),
    HuidigDebet        numeric(15,2),
    HuidigCredit       numeric(15,2),
    ProefDebet         numeric(15,2),
    ProefCredit        numeric(15,2),
    SaldiDebet         numeric(15,2),
    SaldiCredit        numeric(15,2),
    Verlies            numeric(15,2),
    Winst              numeric(15,2),
    EindDebet          numeric(15,2),
    EindCredit         numeric(15,2)   )
   on commit preserve rows;

  create index idx_tmpExpBalansRksNummer  on tmpExpBalans (RksNummer);

  set @@ErrorTextProcedure = 'ExportBalans > @BjGid='+string(@BjGid)+', @Uitsplitsen='+@Uitsplitsen;
  //call TraceBegin(@@ErrorTextProcedure);

  if @BalansInValuta = 0 then
    set @BalansValutaCode = @@BasisValutaCode;
  end if;
  select ValNummer into @BalansValutaNummer from tabValuta where ValCode = @BalansValutaCode;
  select if DecimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @BalansValutaNummer;

  select Paragraaf into @ParagraafDeb  from tabParagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 10;
  select Paragraaf into @ParagraafCred from tabParagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 20;

  set @DebUitsplitsen  = (if Locate(@Uitsplitsen, '0') <> 0 then 1 else 0 endif);
  set @CredUitsplitsen = (if Locate(@Uitsplitsen, '1') <> 0 then 1 else 0 endif);
  set @KstpUitsplitsen = (if Locate(@Uitsplitsen, '2') <> 0 then 1 else 0 endif);
  set @KstdUitsplitsen = (if Locate(@Uitsplitsen, '3') <> 0 then 1 else 0 endif);
  //call Trace('@KstpUitsplitsen='+String(@KstpUitsplitsen));

  //call Trace('Stap 1a: tmpExpBalans vullen met alle rekeningen');

  insert into tmpExpBalans (
              RksInvoer, RksNaam, RksZoekcode, RksNummer, DefaultSoort, KstpGid, KstdGid,
              BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
              ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit)

  select
    RksInvoer,
    RksNaam,
    RksZoekcode,
    RksNummer,
    DefaultSoort,
    RksKstpGid,
    RksKstdGid,
    //Beginbalans
    ValutaOmrekenen(@@BasisValutaNummer, if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif, @BalansValutaNummer, @BjGid, @TotPernr, @NumDeci) BDebet,
    ValutaOmrekenen(@@BasisValutaNummer, if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif, @BalansValutaNummer, @BjGid, @TotPernr, @NumDeci) BCredit,

    //round(if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) / @Koers endif, @NUmDeci) BDebet,
    //round(if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) / @Koers endif, @NUmDeci) BCredit,
    //Vorige periodes
    ValutaOmrekenen(@@BasisValutaNummer, IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0), @BalansValutaNummer, @BjGid, @TotPernr, @NumDeci) VDebet,
    ValutaOmrekenen(@@BasisValutaNummer, IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0), @BalansValutaNummer, @BjGid, @TotPernr, @NumDeci) VCredit,
    //round(IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) / @Koers, @NUmDeci) VDebet,
    //round(IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) / @Koers, @NUmDeci) VCredit,
    //Huidige periode
    ValutaOmrekenen(@@BasisValutaNummer, IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0), @BalansValutaNummer, @BjGid, @TotPernr, @NumDeci) HDebet,
    ValutaOmrekenen(@@BasisValutaNummer, IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0), @BalansValutaNummer, @BjGid, @TotPernr, @NumDeci) HCredit,
    //Proefbalans
    VDebet  + HDebet tmpDebet,
    VCredit + HCredit tmpCredit,
    //Saldibalans
    if (AfdrukZijde = 0 or (AfdrukZijde=2 and tmpDebet >= tmpCredit)) then (tmpDebet  - tmpCredit) else 0 endif SaldiDebet,
    if (AfdrukZijde = 1 or (AfdrukZijde=2 and tmpDebet <  tmpCredit)) then (tmpCredit - tmpDebet)  else 0 endif SaldiCredit,
    //Verlies
    if DefaultSoort in (3,4,5) and  (AfdrukZijde = 0 or (AfdrukZijde=2 and (tmpDebet >= tmpCredit))) then (tmpDebet  - tmpCredit) else 0 endif Verlies,
    //Winst
    if DefaultSoort in (3,4,5) and  (AfdrukZijde = 1 or (AfdrukZijde=2 and (tmpDebet <  tmpCredit))) then (tmpCredit - tmpDebet)  else 0 endif Winst,
    //Eindbalans Debet
    if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 0 or (AfdrukZijde=2 and tmpDebet >= tmpCredit)) then (tmpDebet  - tmpCredit) else 0 endif EindDebet,
    //Eindbalans Credit
    if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 1 or (AfdrukZijde=2 and tmpDebet <  tmpCredit)) then (tmpCredit - tmpDebet)  else 0 endif EindCredit
  from
    tabRekeningschema
  where
    (RksGid in (select RksGid from tabRekeningschema where RksInvoer   between @VanRksInvoer   and @TotRksInvoer   and @SelecteerOp = 1) or
     RksGid in (select RksGid from tabRekeningschema where RksZoekcode between @VanRksZoekcode and @TotRksZoekcode and @SelecteerOp = 2) or
     RksGid in (select RksGid from tabRekeningschema where RksNaam     between @VanRksNaam     and @TotRksNaam     and @SelecteerOp = 3)) and
    (@OokNulSaldi=1 or
    (@OokNulSaldi=2 and (RksGid in //(select RekSaldoRksGid from tabRekeningsaldo where RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr))) or
                                   (select JrRksGid from tabJournaalRegel inner join tabJournaalpost on (JpGid = JrJpGid) inner join tabBoekingsgang on (BoekgangGid = JpBoekgangGid) where JrPerNr between @VanPerNr and @TotPerNr and JrBjGid = @BjGid and
                                   ((@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                                    (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                                    (@SoortBoeking = 2))))) or
    //0-saldi niet afdrukken, dus begin+vorige+huidige optellen en die vergelijken, ook beginbalans etc. apart testen!!
    (@OokNulSaldi=0 and (isnull(tmpDebet,0)-isnull(tmpCredit,0) <> 0 or
                         isnull(BDebet,0) - isnull(BCredit,0) <> 0 or
                         isnull(VDebet,0) - isnull(VCredit,0) <> 0 or
                         isnull(SaldiDebet,0) - isnull(SaldiCredit,0) <> 0 or
                         isnull(HDebet,0) - isnull(HCredit,0) <> 0)));


  if exists(select 1 from tmpExpBalans) then
    //call Trace('Stap 1b - tmpExpbalans is niet leeg');

    if @KstpUitsplitsen = 0 or @KstdUitsplitsen = 0 then
      //call Trace('Stap 2 - Kstp/Kstd comprimeren');

      //Zorg er eerst voor dat alle hoofdrekeningen aanwezig zijn
      insert into tmpExpBalans (RksInvoer, RksNummer, KstpGid, KstdGid, RksNaam, DefaultSoort)
      select                 RksInvoer, RksNummer, RksKstpGid, RksKstdGid, RksNaam, DefaultSoort
      from tabRekeningschema where RksKstpGid is null and RksKstdGid is null
           and RksInvoer in (select distinct RksNummer from tmpExpBalans where KstpGid is not null or KstdGid is not null)  //Geef de hoofdrekeningen terug van die rekening die een kostenplaats/drager hebben
           and RksInvoer not in (select RksInvoer from tmpExpBalans where KstpGid is null or KstdGid is null);           //Als de hoofdrekening alleen in de balans staat dan niet toevoegen

      //call Trace('Stap 2a: Alle hoofdrekeningen toegevoegd.');

      //Nu de hoofdrekening updaten a.d.h.v. de rekeningen met kostenplaatsen en/of kostendragers
      if @KstpUitsplitsen = 0 then
        update tmpExpBalans b
        set
          BeginDebet   = isnull(BeginDebet  ,0) + isnull((select sum(a.BeginDebet)   from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          BeginCredit  = isnull(BeginCredit ,0) + isnull((select sum(a.BeginCredit)  from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          VorigDebet   = isnull(VorigDebet  ,0) + isnull((select sum(a.VorigDebet)   from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          VorigCredit  = isnull(VorigCredit ,0) + isnull((select sum(a.VorigCredit)  from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          HuidigDebet  = isnull(HuidigDebet ,0) + isnull((select sum(a.HuidigDebet)  from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          HuidigCredit = isnull(HuidigCredit,0) + isnull((select sum(a.HuidigCredit) from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          SaldiDebet   = isnull(SaldiDebet  ,0) + isnull((select sum(a.SaldiDebet)   from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          SaldiCredit  = isnull(SaldiCredit ,0) + isnull((select sum(a.SaldiCredit)  from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          Verlies      = isnull(Verlies     ,0) + isnull((select sum(a.Verlies)      from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          Winst        = isnull(Winst       ,0) + isnull((select sum(a.Winst)        from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          EindDebet    = isnull(EindDebet   ,0) + isnull((select sum(a.EindDebet)    from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
          EindCredit   = isnull(EindCredit  ,0) + isnull((select sum(a.EindCredit)   from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0)
        where  KstpGid is null and KstdGid is null
              //extra om het wat sneller te laten gaan: Deb en Cred kunnen toch geen kp/kds hebben.
              and DefaultSoort <> 6 and DefaultSoort <> 7;

        delete tmpExpBalans where KstpGid is not null;
        //call Trace('Stap 2b: KP verdichten klaar.');
      end if;

      if @KstdUitsplitsen = 0 then
        //LET OP: iom. RB en ACW besloten om ook de kostendragers indien niet uitgesplitst direct op de kostensoort (de rekening) te zetten ipv. eerst te
        //        proberen of die op de kostenplaats kan worden gezet. (probleem: bestaat de kostenplaats wel? Zoniet, dan alsnog op de kostensoort boeken)
        update tmpExpBalans b
        set
          BeginDebet   = isnull(BeginDebet  ,0) + isnull((select sum(a.BeginDebet)   from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          BeginCredit  = isnull(BeginCredit ,0) + isnull((select sum(a.BeginCredit)  from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          VorigDebet   = isnull(VorigDebet  ,0) + isnull((select sum(a.VorigDebet)   from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          VorigCredit  = isnull(VorigCredit ,0) + isnull((select sum(a.VorigCredit)  from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          HuidigDebet  = isnull(HuidigDebet ,0) + isnull((select sum(a.HuidigDebet)  from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          HuidigCredit = isnull(HuidigCredit,0) + isnull((select sum(a.HuidigCredit) from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          SaldiDebet   = isnull(SaldiDebet  ,0) + isnull((select sum(a.SaldiDebet)   from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          SaldiCredit  = isnull(SaldiCredit ,0) + isnull((select sum(a.SaldiCredit)  from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          Verlies      = isnull(Verlies     ,0) + isnull((select sum(a.Verlies)      from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          Winst        = isnull(Winst       ,0) + isnull((select sum(a.Winst)        from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          EindDebet    = isnull(EindDebet   ,0) + isnull((select sum(a.EindDebet)    from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
          EindCredit   = isnull(EindCredit  ,0) + isnull((select sum(a.EindCredit)   from tmpExpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0)
        where  KstpGid is null and KstdGid is null
              //extra om het wat sneller te laten gaan: Deb en Cred kunnen toch geen kp/kds hebben.
              and DefaultSoort <> 6 and DefaultSoort <> 7;

        delete tmpExpBalans where KstdGid is not null;
        //call Trace('Stap 2c: KD verdichten klaar.');
      end if;

    end if;  //klaar met kp/kd comprimeren.


    if (@DebUitsplitsen = 0) then
      if exists (select 1 from tmpExpBalans where DefaultSoort = 6) then
        //call Trace('Stap 3a: Debiteuren groeperen en als paragraaf er tussen zetten');
        //Let op: als rekening tussenvoegen omdat de paragrafen zelf niet worden afgedrukt!!
        insert into tmpExpBalans
          (RksInvoer, RksNummer, RksNaam,
           BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
           ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit)
        select
          @ParagraafDeb, @ParagraafDeb, (select OmsBalansCodeDetails from tabparagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 10),
          sum(BeginDebet), sum(BeginCredit), sum(VorigDebet), sum(VorigCredit), sum(HuidigDebet), sum(HuidigCredit),
          sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit)
        from   tmpExpBalans where DefaultSoort = 6;
        delete tmpExpBalans where DefaultSoort = 6;
      end if;
    end if;

    if (@CredUitsplitsen = 0) then
      if exists (select 1 from tmpExpBalans where DefaultSoort = 7) then
        //call Trace('Stap 3a: Crediteuren groeperen en als paragraaf er tussen zetten');
        //Let op: als rekening tussenvoegen omdat de paragrafen zelf niet worden afgedrukt!!
        insert into tmpExpBalans
          (RksInvoer, RksNummer, RksNaam,
           BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
           ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit)
        select
          @ParagraafCred, @ParagraafCred, (select OmsBalansCodeDetails from tabparagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 20),
          sum(BeginDebet), sum(BeginCredit), sum(VorigDebet), sum(VorigCredit), sum(HuidigDebet), sum(HuidigCredit),
          sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit)
        from   tmpExpBalans where DefaultSoort = 7;
        delete tmpExpBalans where DefaultSoort = 7;
      end if;
    end if;

  end if; //alleen als er wel regels in staan, anders alles overgeslagen!

  set @@ErrorTextProcedure = 'ExportBalans';
  //call TraceEind(@@ErrorTextProcedure);

  select   RksInvoer, RksNaam, RksZoekcode, @BalansValutaCode,
           BeginDebet,  BeginCredit,  BeginDebet - BeginCredit BeginSaldo,
           VorigDebet,  VorigCredit,  VorigDebet - VorigCredit VorigCredit,
           HuidigDebet, HuidigCredit, HuidigDebet - HuidigCredit HuidigSaldo,
           ProefDebet,  ProefCredit,  ProefDebet - ProefCredit ProefSaldo,
           SaldiDebet,  SaldiCredit,  SaldiDebet - SaldiCredit SaldiSaldo,
           Verlies,     Winst,        Verlies - Winst ResultaatSaldo,
           EindDebet,   EindCredit,   EindDebet - EindCredit EindSaldo
  from     tmpExpBalans
  order by RksInvoer;


end;


create or replace procedure ExportSelectArtikelenMetVR(in @Selectie smallint,
                                            in @VanArtCode nchar(20), in @TotArtCode nchar(20),
                                            in @VanArtZoekcode nchar(20), in @TotArtZoekcode nchar(20),
                                            in @VanArtOms nchar(40), in @TotArtoms nchar(40),
                                            in @VanOpbrGrpNummer nchar(4), in @TotOpbrGrpNummer nchar(4),
                                            in @VanNawFilNummer nchar(10), in @TotNawFilNummer nchar(10),
                                            in @GeblokkeerdInkoop nchar(5), in @GeblokkeerdVerkoop nchar(5),
                                            in @ArtWebArtikel nchar(5), in @ArtTaalCode nchar(3),
                                            in @DefaultMagazijn smallint,
                                            in @SorteerVeld smallint, in @AscDesc smallint)
begin
  //call TraceBegin('ExportSelectArtikelenMetVR > @Selectie='+String(@Selectie)+'; @GeblokkeerdInkoop='+@GeblokkeerdInkoop);

  call CreateVrijeRubriekenStoredProc('ART', 0, 0);

  //call TraceEind('ExportSelectArtikelenMetVR');



  SELECT  ArtCode Artikelnummer,
          ArtZoekCode Zoekcode,
          ArtOms Omschrijving,
          OpbrGrpNummer Opbrengstgroep,
          ArtOmsEenheid Eenheid,
          ArtGewichtPer GewichtPer,
          ArtGewicht Gewicht,
          ArtVolumePer VolumePer,
          ArtVolume Volume,
          ArtIsGeblokkeerd GeblokkeerdVoorVerkoop,
          ArtIsGeblokkeerdInkoop GeblokkeerdVoorBestelling,
          ArtIsGeblokkeerdMagOntv GeblokkeerdVoorMagOntvangst,
          ArtBtwCodeInkoop BTWcodeInkoop,

          VkeIsGeblokkeerdVoorVerkoop VoorraadeenheidGeblokkeerdVoorVerkoop,
          if (artDefaultVerkoopeenheid = VkeVerkoopEenheid) then 1 else 0 endif VoorraadeenheidStandaardVerkoopeenheid,

          ArtBTWcode BTWcodeVerkoop,
          ArtBerekenPrijs        AutomPrijs,
          ArtBerekenPrijsVan     AutomPrijsVan,
          ArtBerekenPrijsMargeIs AutomPrijsMarge,
          ArtBerekenPrijsPerc    AutomPrijsPerc,
          ArtPrijsPer GeprijsdPer,
          ArtKostprijsEx KostprijsExBTW,
          (if ArtVerkprijsIsIncl=0 then ArtVerkPrijs else ArtVerkprijs * ( 100/( BtwPercentage+100) ) endif) VerkoopPrijsExBTW,
          (if ArtVerkprijsIsIncl=0 then ArtVerkprijs*( (100+BtwPercentage)/100) else ArtVerkprijs endif) VerkoopPrijsInBTW,

          PraKortingsPerc Kortingpercentage,
          PraKortingsBedrag     Kortingbedrag,

          (select ArtTekst from tabTaal left outer join tabArtikelTeksten on ArtGid = ArtTekstArtGid and ArtTaalGid = TaalGid where TaalCode = @ArtTaalCode and ArtTekstDocSoort = 50) TekstOpFactuur,
          // Standaard leverancier
          NawFilNummer Leveranciernummer,
          (select AdrNaam1 from tabNaw inner join tabAdres on AdrGid = nawGidVestiging where NawGid = NawFilnawGid) Leveranciernaam,
          // Standaard inkoopeenheid
          AldInkoopEenheid Inkoopeenheid,
          AldInkoopEenheidBijLeverancier InkoopeenheidBijLeverancier,
          AldVoorraadEenhedenInInkoopEenheid AantalInInkoopeenheid,
          AldAantalKanVerschillen AantalInInkoopeenheidKanVerschillen,
          AldArtCodeBijLeverancier ArtikelNummerBijLeverancier,
          (select ArtEanCode from tabArtikelEAN where ArtEanGid = AldArtEanGid) EANCodeInkoopeenheid,
          AldOmsBijLeverancier ArtikelOmschrijvingLeverancier,
          AldLevertijd LevertijdInDagen,
          AldKwaliteit InkoopKwaliteit,
          AldBestelGrootte Bestelgrootte,
          AldMinimumAfname Minimumafname,
          AldHeeftEigenInkoopprijs HeeftEigenInkoopprijs,
          AldInkoopPrijsPer InkoopprijsPer,
          (select ValCode from tabValuta where ValNummer = AldValNummer) ValutaInkoopprijs,
          AldInkoopPrijs InkoopprijsInValuta,
          AldKortingSoort SoortKortingInkoopprijs,
          AldKortingBedrag InkoopKortingsbedrag,
          AldKortingPercentage InkoopKortingspercentage,
          (select NstfKopCode from tabNawStaffelKop where NstfKopGid = AldNstfKopGid) InkoopStaffelCode,
          AldBerekeningKostprijs BerekeningKostprijsObvInkoopprijs,
          AldFactorKostprijs BerekeningKostprijsFactor,
          AldBedragToeslag BerekeningKostprijsToeslag,
          AldOpm OpmerkingenInkoopeenheid,

          ArtHeeftVoorraad  VoorraadArtikel,

          MagCode       DefaultMagazijnCode,
          MagZoekcode   DefaultMagazijnZoekcode,
          MagOms        DefaultMagazijnOmschrijving,
          ArtMagMinimumVoorraad DefaultMagazijnMinimumVoorraad,
          ArtMagMaximumVoorraad DefaultMagazijnMaximumVoorraad,
          LocNaam       DefaultLocatieNaam,
          LocOms        DefaultLocatieOmschrijving,

          (if ArtIsAdviesPrijsInclBtw=0 then ArtAdviesPrijs else ArtAdviesprijs * ( 100/( BtwPercentage+100) ) endif) AdviesPrijsExBTW,
          (if ArtIsAdviesPrijsInclBtw=0 then ArtAdviesprijs*( (100+BtwPercentage)/100) else ArtAdviesprijs endif) AdviesPrijsInBTW,
          ArtWebArtikel WebArtikel,
          ArtWebBestelGrootte WebBestelgrootte,
          ArtWebLevertijd WebLevertijd,
          ArtWebTonenVanaf WebTonenVanaf,
          ArtWebTonenTot  WebTonenTot,

          ArtAfbeeldingGroot AfbeeldingGroot,
          ArtAfbeeldingKlein AfbeeldingKlein,

          ArtMutatieInkoopBijhouden  MutatieInkoopBijhouden,
          ArtMutatieVerkoopBijhouden MutatieVerkoopBijhouden,
          ArtSerienrRegistreren SerienummersRegistreren,
          ArtIsPartijRegistreren PartijenRegistreren,
          CbsGcCode        CbsGoederenCode,
          ArtCbsMaatstaf   CbsMaatstaf,
          isnull((select first ArtEanCode from tabArtikelEan where ArtEanArtGid = ArtGid and ArtEanIsDefault = 1), (select min(ArtEanCode) from tabArtikelEan where ArtEanArtGid = ArtGid)) EanCode,

          ArtIsGebruikVoorBestelAdvies MeenemenInBestelAdvies,
          ArtIsGebruikVoorProductieAdvies MeenemenInProductieAdvies,
          ArtIsKostprijsWijzigenInOrder KostprijsWijzigenBijOrderinvoer,

          SomMinimumVoorraad,
          SomMaximumVoorraad,
          HuidigeVoorraad,
          GereserveerdVoorLevering,
          GereserveerdVoorBackOrder,
          InBestelling,
          InOntvangst,

          spSelectVrArt.*,

          case @SorteerVeld
          when 0 then ArtCode
          when 1 then ArtZoekcode
          when 2 then ArtOms
          when 3 then OpbrGrpNummer
          when 4 then NawFilNummer
          when 5 then AldArtCodeBijLeverancier
          end SorteerVeld,

          ArtBestellenViaDirecteInkoop,
          ArtOmsVerkooporderOvernemen

  from    tabArtikel
   inner join tabOpbrengstgroep          on (OpbrGrpGid = ArtOpbrGrpGid)
   inner join tabBtw                     on ArtBTWcode = BtwCode
   left outer join tabVerkoopeenheid     on VkeArtGid = ArtGid and VkeIsVoorraadEenheid = 1
   left outer join tabPrijsAfspraak      on ArtGid = PraArtGid and PraCombiSoort = 0
   left outer join (tabArtikelLeverancier inner join tabNawFile on ArtLevNawGid = NawFilNawGid and NawFilFonId='C') on ArtGid = ArtLevArtGid and ArtLevIsDefault = 1
   left outer join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid and AldIsDefaultInkoopEenheidBijLev = 1
   left outer join tabMagazijn on MagGid = ISNULL(ArtDefaultMagGid,(select maggid from tabmagazijn where magcode = @DefaultMagazijn))
   left outer join tabArtikelMagazijn on ArtMagArtGid = ArtGid and ArtMagMagGid = MagGid
   left outer join tabLocatie on LocGid = ArtMagDefaultLocGid
   left outer join tabCbsGoederenCodes on CbsGcGid = ArtCbsGcGid
   left outer join spSelectVrArt() on vrArtRecordID = ArtGid
   left outer join (select calcArtGid,
                           IsNull(sum(calcMinimumVoorraad), 0.00) SomMinimumVoorraad,
                           IsNull(sum(calcMaximumVoorraad), 0.00) SomMaximumVoorraad,
                           IsNull(sum(calcMagazijnVoorraad), 0.00)  HuidigeVoorraad,
                           IsNull(sum(calcGereserveerdLevering), 0.00) GereserveerdVoorLevering,
                           IsNull(sum(calcGereserveerdBackorder), 0.00) GereserveerdVoorBackOrder,
                           IsNull(sum(calcInBestellingVerwerkt), 0.00) InBestelling,
                           IsNull(sum(calcInMagOntvangst), 0.00) InOntvangst
                    from   vwVoorraadAantallen
                    group by calcArtGid) Sp on (calcArtGid = ArtGid)

  where
     ArtSoort = 2 and
     (
    (@Selectie=1 and ArtCode       between @VanArtcode       and @TotArtcode) or
    (@Selectie=2 and ArtZoekCode   between @VanArtZoekCode   and @TotArtZoekCode) or
    (@Selectie=3 and ArtOms        between @VanArtOms        and @TotArtOms) or
    (@Selectie=4 and OpbrGrpNummer between @VanOpbrGrpNummer and @TotOpbrGrpNummer) or
    (@Selectie=5 and NawFilNummer  between @VanNawfilnummer  and @TotNawfilnummer)
      )
   and (@GeblokkeerdInkoop  like '%' + string(ArtIsGeblokkeerdInkoop) + '%')
   and (@GeblokkeerdVerkoop like '%' + string(ArtIsGeblokkeerd) + '%')
   and (@ArtWebArtikel      like '%' + string(ArtWebArtikel) + '%')

  order by
    if @AscDesc = 1 then SorteerVeld else '' endif asc,
    if @AscDesc = 0 then SorteerVeld else '' endif desc,
    ArtCode;

end;

