//Deze proc geeft alle naw gegevens inclusief vrije rubrieken terug voor export.
//Zie $/app/sys/export/NawExportMetVr.sql voor uitgebreide toelichting.
create or replace procedure ExportSelectNAWMetVR(in @Fonid nchar(3),  in @Selectie smallint,
                                      in @VanNummer nchar(10),   in @TotNummer nchar(10),
                                      in @VanZoekCode nchar(10),   in @TotZoekCode nchar(10),
                                      in @FnCode integer, in @WebNaw nchar(10))
begin
  declare @FonGid         integer;

  //execute TraceBegin 'ExportSelectNAWMetVR > '+@FonId

  select FonGid into @FonGid from tabFileOfNaw where FonId = @FonId;
  //execute Trace 'Fongid='+string(@FonGid)

  //Zorgen voor 3 views met de actuele vrije rubrieken van deze fondid:
  call CreateVrijeRubriekenStoredProc('NAW', @FonGid, @FonGid);
  call CreateVrijeRubriekenStoredProc('CP',  @FonGid, @FonGid);
  call CreateVrijeRubriekenStoredProc('ADR', @FonGid, @FonGid);

  //execute TraceEind 'ExportSelectNAWMetVR'

  //Nu kunnen we die views meteen gebruiken in de volgende query:
  select
    NawFileMain.NawFilNummer   NawNummer,
    NawFileMain.NawFilZoekcode Zoekcode,

    //Vestigingsadres
    Vest.AdrNaam1         VestAdrNaam1,
    Vest.AdrNaam2         VestAdrNaam2,
    Vest.AdrStraat        VestAdrStraat,
    Vest.AdrHuisnummer    VestAdrHuisnummer,
    Vest.AdrPostcode      VestAdrPostcode,
    Vest.AdrPlaats        VestAdrPlaats,
    LandVest.LndEigenCode VestAdrLandcode,
    LandVest.LndOms       VestAdrLandOmschrijving,
    Vest.AdrTelefoon      VestAdrTelefoon,
    Vest.AdrTelefoon2     VestAdrTelefoon2,
    Vest.AdrTelefax       VestAdrTelefax,
    Vest.AdrEmail         VestAdrEmail,
    BouwKIXCode(Vest.AdrLndGid, Vest.AdrPostcode, Vest.AdrHuisnummer) VestAdrKIXcode,
    Vest.AdrEanCode       VestAdrEanCode,
    NawMain.NawWebsite    VestWebsite,

    //Correspondentieadres
    Cor.AdrNaam1         CorAdrNaam1,
    Cor.AdrNaam2         CorAdrNaam2,
    Cor.AdrStraat        CorAdrStraat,
    Cor.AdrHuisnummer    CorAdrHuisnummer,
    Cor.AdrPostcode      CorAdrPostcode,
    Cor.AdrPlaats        CorAdrPlaats,
    LandCor.LndEigenCode CorAdrLandcode,
    LandCor.LndOms       CorAdrLandOmschrijving,
    Cor.AdrTelefoon      CorAdrTelefoon,
    Cor.AdrTelefoon2     CorAdrTelefoon2,
    Cor.AdrTelefax       CorAdrTelefax,
    Cor.AdrEmail         CorAdrEmail,
    BouwKIXCode(Cor.AdrLndGid, Cor.AdrPostcode, Cor.AdrHuisnummer) CorAdrKIXcode,
    Cor.AdrEanCode       CorAdrEanCode,
    TaalCode              Taalcode,

    //Financiele settings
    NawFileMain.NawFilBtcNummer       Betalingsconditie,
    NawFileMain.NawFilLvcNummer       Leveringsconditie,
    ValCode                           Valutacode,
    NawFileMain.NawFilBtwCode         BTWcode,
    NawFileMain.NawFilKredLimiet      Kredietlimiet,
    RksTegen.RksInvoer                Tegenrekening,
    NawMain.NawAanmaningsType         AanmaningsType,
    NawMain.NawBtwNummer              BTWnummer,

    //Ordersettings
    NawMain.NawAparteFacturen           AparteFacturen,
    NawMain.NawFacturerenInclBtw        FacturenInExBtw,
    NawMain.NawFactuurAdres             FactuurAdres,
    NawMain.NawVerzendAdres             VerzendAdres,
    DebGrpNr                            Debiteurgroep,
    NawMain.NawVertegenwCode            Vertegenwoordiger,
    NawMain.NawContributieCode          DebContributiecode,
    RapExcl.RapNummer                   FactuurBatchLayoutExclBTW,
    RapIncl.RapNummer                   FactuurBatchLayoutInclBTW,
    NawMain.NawAantalKopieFacturen      AantalKopieFacturen,
    NawFileMain.NawFilWelkeOrderkorting WelkeOrderkorting,
    NawMain.NawOrderKorting             OrderKorting,
    NawMain.NawBlokOrderInvoer          BlokkerenVoorOrderinvoer,
    NawFileMain.NawFilWebNaw            Webklant,

    //Inkoopcombi
    NawMain.NawIsInkoopCombinatie   NawIsInkoopCombinatie,
    NawFileFactuur.NawFilNummer         Factuurdebiteurnummer,
    NawFileOmzet.NawFilNummer           Omzetdebiteurnummer,
    NawFilePrijs.NawFilNummer           Prijsdebiteurnummer,

    //Factuuradres volgens instelling
    Fact.AdrNaam1         FactAdrNaam1,
    Fact.AdrNaam2         FactAdrNaam2,
    Fact.AdrStraat        FactAdrStraat,
    Fact.AdrHuisnummer    FactAdrHuisnummer,
    Fact.AdrPostcode      FactAdrPostcode,
    Fact.AdrPlaats        FactAdrPlaats,
    LandFact.LndEigenCode FactAdrLandcode,
    LandFact.LndOms       FactAdrLandOmschrijving,
    Fact.AdrTelefoon      FactAdrTelefoon,
    Fact.AdrTelefoon2     FactAdrTelefoon2,
    Fact.AdrTelefax       FactAdrTelefax,
    Fact.AdrEmail         FactAdrEmail,
    BouwKIXCode(Fact.AdrLndGid, Fact.AdrPostcode, Fact.AdrHuisnummer) FactAdrKIXcode,
    Fact.AdrEanCode       FactAdrEanCode,

    //Verzendadres volgens instelling
    Verz.AdrCode          VerzAdrNummer,
    Verz.AdrOms           VerzAdrOmschrijving,
    Verz.AdrNaam1         VerzAdrNaam1,
    Verz.AdrNaam2         VerzAdrNaam2,
    Verz.AdrStraat        VerzAdrStraat,
    Verz.AdrHuisnummer    VerzAdrHuisnummer,
    Verz.AdrPostcode      VerzAdrPostcode,
    Verz.AdrPlaats        VerzAdrPlaats,
    LandVerz.LndEigenCode VerzAdrLandcode,
    LandVerz.LndOms       VerzAdrLandOmschrijving,
    Verz.AdrTelefoon      VerzAdrTelefoon,
    Verz.AdrTelefoon2     VerzAdrTelefoon2,
    Verz.AdrTelefax       VerzAdrTelefax,
    Verz.AdrEmail         VerzAdrEmail,
    BouwKIXCode(Verz.AdrLndGid, Verz.AdrPostcode, Verz.AdrHuisnummer) VerzAdrKIXcode,
    Verz.AdrEanCode       VerzAdrEanCode,

    NawMain.NawOnsDebiteurNummer    OnsDebiteurnummer,
    NawOpmOpmerking                 NAWOpmerking,

    //De cp volgens voorloopscherm
    RelNummer               CPNummer,
    RelAchternaam           CPAchternaam,
    RelVoorvoegsel          CPVoorvoegsel,
    RelVoorletters          CPVoorletters,
    RelVoornaam             CPVoornaam,
    RelTitel                CPTitel,
    RelAchtervoegsel        CPAchtervoegsel,
    RelVolledigeNaam        CPVolledigeNaam,
    RelGeslacht             CPGeslacht,
    RelTelefoon             CPTelefoon,
    RelTelefoon2            CPTelefoon2,
    RelTelefax              CPTelefax,
    RelEmail                CPEmailadres,
    RelContributieCode      CPContributiecode,
    RelNaamInAdres          CPNaamInAdres,
    RelNaamInAanhef         CPNaamInAanhef,
    RelNaamInBrief          CPNaamInBrief,
    RelOpmOpmerking         CPOpmerking,

    //De defaultbankrekening
    nawrekBankRekeningInvoer Bankrekeningnummer,
    nawrekNaamRekHouder      BankNaam,
    nawRekAdresRekHouder     BankAdres,
    nawRekPostcodeRekHouder  BankPostcode,
    nawrekPlaatsRekHouder    BankPlaats,
    LandBank.LndEigenCode 	 BankLandcode,
    if NawRekGid is not null then 0 endif BankIsZuiver, /*ACW defect 49623, alleen 0 teruggeven als er een bankrekening is*/

    // Leveranciergegevens
    (if LevGegGid is null then 0 else 1 endif)                                      LevGegInkoopgegevensBijhouden,
    LevGegBestellenGeblokkeerd                                                      LevGegBlokkeervoorBestellen,
    LevGegBestelAdres                                                               LevGegBestelAdres,
    (select AdrCode from tabAdres where AdrGid = LevGegAdrGidBestelAdres)           LevGegBestelAdresCode,
    (select RelNummer from tabRelatie where RelGid = LevGegRelGidInkoper)           LevGegRelNummerInkoper,
    (select ValCode from tabValuta where ValNummer = LevGegValNummerMinimumBedrag)  LevGegValCodeMinimumBestelBedrag,
    LevGegMinimumBedrag                                                             LevGegMinimumBestelbedrag,
    (select ValCode from tabValuta where ValNummer = LevGegValNummerKosten)         LevGegValCodeBestelKosten,
    LevGegKosten                                                                    LevGegKosten,
    LevGegKostenBijBestelTm                                                         LevGegKostenBijBestellingTM,
    LevGegKostenBijBestelVanaf                                                      LevGegKostenBijBestellingVanaf,
    LevGegLevertijd                                                                 LevGegLevertijd,
    LevGegKwaliteit                                                                 LevGegKwaliteit,
    LevGegInkoopPrijsPer                                                            LevGegInkoopprijsper,
    LevGegKorting                                                                   LevGegKortingspercentage,
    LevGegBerekeningKostprijs                                                       LevGegBerekeningKostprijs,
    LevGegFactorKostprijs                                                           LevGegFactor,
    LevGegDirLevGeschikt                                                            LevGegDirecteLeveringToegestaan,
    LevGegDirLevDefaultVoorIE                                                       LevGegDirecteLevering,
    //vrije rubrieken
    spSelectVrNAW.*,
    spSelectVrCP.*,
    spSelectVrADR.*

  from
    tabNaw NawMain
    left outer join tabNawFile NawFileMain on NawFileMain.NawFilNawGid = NawMain.NawGid

    //inkoopcombinatie-ellende. We moeten NawNummer hebben dus zowiezo alle tabNawFiles 3x
    //Voor Factuuradres logica hebben we ook tabNaw vd factuurdebiteur nog een keer nodig.
    left outer join tabNawFile NawFileFactuur on NawFileFactuur.NawFilNawGid = NawMain.NawIdFactDeb
    left outer join tabNaw     NawFactuur     on NawFactuur.NawGid           = NawMain.NawIdFactDeb
    left outer join tabNawFile NawFileOmzet   on NawFileOmzet.NawFilNawGid   = NawMain.NawidDebOmzet
    left outer join tabNawFile NawFilePrijs   on NawFilePrijs.NawFilNawGid   = NawMain.NawIdDebPrijzen

    //Adressen:
    left outer join tabAdres Vest on Vest.AdrGid  = NawMain.NawGidVestiging
    left outer join tabAdres Cor  on Cor.AdrGid   = NawMain.NawGidCorrespondentie
    left outer join tabAdres Fact on Fact.AdrGid  = (if IsNull(NawFactuur.NawFactuurAdres, NawMain.NawFactuurAdres) = 1 then
                                                        IsNull(NawFactuur.NawGidVestiging, NawMain.NawGidVestiging) else
                                                     if IsNull(NawFactuur.NawFactuurAdres, NawMain.NawFactuurAdres) = 0 then
                                                        IsNull(NawFactuur.NawGidCorrespondentie, NawMain.NawGidCorrespondentie) endif endif)

    left outer join tabAdres Verz on Verz.AdrGid  = (if NawMain.NawVerzendAdres = 1 then
                                                        NawMain.NawgidVestiging else
                                                     if NawMain.NawVerzendAdres = 0 then
                                                        NawMain.NawGidCorrespondentie else
                                                     if NawMain.NawVerzendAdres = 2 then
                                                        NawMain.NawGidVerzendAdres endif endif endif)

    left outer join tabLand LandVest on Vest.AdrLndGid = LandVest.LndGid
    left outer join tabLand LandCor  on Cor.AdrLndGid  = LandCor.LndGid
    left outer join tabLand LandFact on Fact.AdrLndGid = LandFact.LndGid
    left outer join tabLand LandVerz on Verz.AdrLndGid = LandVerz.LndGid

    left outer join tabDebiteurGroepen on NawFileMain.NawFilDebGrpGid = DebgrpGid
    left outer join tabTaal on NawMain.NawTaalGid = TaalGid
    left outer join tabValuta on NawFileMain.NawFilValNummer = ValNummer
    left outer join tabNawOpmerkingen on NawMain.NawGid = NawOpmNawGid

    left outer join tabRekeningschema RksMain on NawFileMain.NawFilRksGID = RksMain.RksGid
    left outer join tabRekeningschema RksTegen on RksMain.TegenRksgid     = RksTegen.RksGid

    left outer join tabNawRekening on (NawRekNawGid = NawMain.NawGid) and (locate(NawRekSoort, 'D')<>0)
    left outer join tabLand LandBank on NawRekLndGidRekHouder = LandBank.LndGid

    left outer join tabRelatie on RelGid = NawExportGeefJuisteCP(NawMain.NawGid, @FnCode)
    left outer join tabRelatieOpmerkingen on RelGid = RelOpmRelGid
    left outer join tabLeverancierGegevens on LevGegNawGid = NawMain.NawGid

    left outer join tabRapport RapExcl on RapExcl.RapGid = (select first NawDocRapGidExclBTW from tabNawDocument where NawDocNawGid=NawMain.NawGid and NawDocDocSoort=50 and NawDocRegelSoort=0)
    left outer join tabRapport RapIncl on RapIncl.RapGid = (select first NawDocRapGidInclBTW from tabNawDocument where NawDocNawGid=NawMain.NawGid and NawDocDocSoort=50 and NawDocRegelSoort=0)

    left outer join spSelectVrNAW() on vrNAWRecordID = NawMain.NawGid
    left outer join spSelectVrCP()  on vrCPRecordID  = RelGid
    left outer join spSelectVrAdr() on vrAdrRecordID = Verz.AdrGid

  where NawFileMain.NawFilFonId = @FonId and
          (
            (@Selectie=1 and (NawFileMain.NawFilNummer   between @VanNummer and @TotNummer)) or
            (@Selectie=2 and (NawFileMain.NawFilZoekcode between @VanZoekCode and @TotZoekCode))
          )
        and (@WebNAW like '%' + string(NawFileMain.NawFilWebNaw) + '%')
  order by NawFileMain.NawFilNummer;

end;


// Deze dient inmiddels enkel voor het aanmaken van de AcceptGiro, Factuurnummers worden tijdens verwerking van de factuur uitgegeven
create or replace procedure FactStartAanmakenAcceptGiro(
  in  @fbGid              integer,
  in  @ConnId             integer,
  in  @LoginTime          nchar(50),
  in  @SoortFact          smallint,
  in  @LayoutSoort        smallint,
  in  @SorteerOp          smallint,    //1 = deb.nummer; 2 = zoekcode
  in  @Ascending          smallint,    //0 = descending, 1=ascending
  in  @UseLockedOrkGid    integer,
  in  @BjGid		  integer,
  out @HeeftFacturen      smallint)
begin
  declare @DocOrdAfdrukkenFactuurAcceptgiro integer;

  //call TraceBegin('FactStartAanmakenAcceptGiro > @fbGid = ' + string(@fbGid) + ', @ConnId = ' + string(@ConnId) + ', @LoginTime = ' + string(@LoginTime) + ', @SoortFact = ' + string(@SoortFact) + ', @LayoutSoort = ' + string(@LayoutSoort) + ', @SorteerOp = ' + string(@SorteerOp) + ', @Ascending = ' + string(@Ascending) + ', @UseLockedOrkGid = ' + string(@UseLockedOrkGid) + ', @BjGid = ' + string(@BjGid));

  //Let op: deze moet voor de test staan of er nog facturen zijn!!
  call ProgressSet(null, null, _U('Aanmaken ordergegevens (uitdelen nummers)') );

  if IsModuleActive('ag') = 1 then
    // Er zijn facturen *en* we hebben de optie AcceptGiro
    select DocOrdAfdrukkenFactuurAcceptgiro into @DocOrdAfdrukkenFactuurAcceptgiro from tabDocument where DocSoort = @LayoutSoort;
    if isnull(@DocOrdAfdrukkenFactuurAcceptgiro,0) in (1,2) then
      // We moeten inderdaad een acceptgirobatch aanmaken zoals aangegeven in het soort document
      // Let op: deze routine kan overbodige facturen verwijderen uit de batch!
      call FacturerenCreateAcceptGiroBatch(@ConnId, @LoginTime, @fbGid, @LayoutSoort, @UseLockedOrkGid, @AcbGid);
    end if;
  end if;

  //Als er geen facturen in de batch zijn, dan de batch verwijderen
  if not exists( select 1 from tabFactuurKop where fkFbGid = @fbGid ) then
    //call Trace('Er zijn geen facturen meer over, dus batch verwijderen als er ook geen niet-gefactureerde zijn');
    if not exists( select 1 from tabFactuurNietGefactureerd where fngFbGid = @fbGid ) then
      call FacturerenOrdersAnnuleren( @fbGid,@UseLockedOrkGid);
      if @ConnId is not null then
        call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid));
      end if;
      set @fbGid = -1;
    end if;
    set @HeeftFacturen = 0;
  else
    //aangeven dat er inderdaad facturen (of andere documenten!!) zijn
    set @HeeftFacturen = 1;
  end if;
  call ProgressAdd( 2 );

  //call TraceEind('FactStartAanmakenAcceptGiro');
end;


create or replace procedure FactStartControles(
  in  @fbGid              integer,
  in  @SoortFact          smallint,
  in  @LayoutSoort        smallint,
  in  @SorteerOp          smallint,    //1 = deb.nummer; 2 = zoekcode
  in  @Ascending          smallint    //0 = descending, 1=ascending
)
// ---------------------------------  CONTROLES OP DE ORDERS DIE GEFACTUREERD MOETEN GAAN WORDEN  -----------------------------------------
begin
  //@SoortFact:
  // 0 = fact. Batch
  // 1 = fact. direct
  // 2 = orderbev. (dus orders niet samenvoegen, ook geen factuurnummer aanmaken)
  // 3 = Pakbon (let op: Levering!!!)
  // 4 = Proforma
  declare @OokLeverenBijFact           smallint; //0 = alleen factureren, 1 = leveren bij factureren

  //call TraceBegin('FactStartControles > @fbGid = ' + string(@fbGid) + ', @SoortFact = ' + string(@SoortFact) + ', @LayoutSoort = ' + string(@LayoutSoort) + ', @SorteerOp = ' + string(@SorteerOp) + ', @Ascending = ' + string(@Ascending));

  // Controleer of we bij facturering ook moeten leveren (i.v.m. levercontroles die dan ook moeten plaatsvinden!)
  case @SoortFact
  when 0 then // batch-facturering
    select first vofLeverenBijFactureren into @OokLeverenBijFact from tabVasteGegevensOrdersFactureren;
  else
    set @OokLeverenBijFact = 0;
  end case;

  //Document (evt.) niet dubbel afdrukken of in het geheel niet als andere docs nog niet zijn afgedrukt
  call FacturerenCheckPrintedDocuments(@fbGid, @SoortFact, @LayoutSoort);
  call ProgressAdd( 1 );
//  // Leveren tijdens facturering -> ook lever-documenten testen!
//  if @OokLeverenBijFact = 1 then
//    call FacturerenCheckPrintedDocuments(@fbGid, 3, 30);
//  end if;
  call ProgressAdd( 1 );

  // Orders die moeten worden geleverd maar waarvan een artikel nog geen ingevuld serienummer heeft eruithalen
  // Als leveren bij factureren, dan moeten we Levering simuleren!
  call FacturerenCheckSerienummersPartijen(@FbGid, (if @OokLeverenBijFact = 1 then 3 else @SoortFact endif));

  call ProgressAdd( 1 );

  call FacturerenCheckMagazijnVoorraad(@FbGid, (if @OokLeverenBijFact = 1 then 3 else @SoortFact endif));

  call ProgressAdd( 1 );

  call FacturerenBepaalVerzamelDocumenten(@LayoutSoort, @fbGid);

  call ProgressAdd( 1 );

  //Nu de juiste volgorde bepalen (volgorde: afhankelijk van de instellingen
  update   tabTeFacturerenOrders
  set      tfoTeFactVolgOrder=number()
  from     tabOrderKop
           inner join tabnaw     on (NawGid = OrkNawGid)
           inner join tabNawfile on NawFilNawGid = NawGid and NawFilFonId='D'
  where    OrkGid = tfoTeFactOrkGid and tfoSessieFbGid = @FbGid
  order by if @Ascending = 0 then if @SorteerOp = 1 then NawFilNummer else NawFilZoekCode endif else '' endif desc,
           if @SorteerOp = 1 then NawFilNummer else NawFilZoekCode endif asc;

  call ProgressAdd( 1 );

  // *** VANAF HIER MOGEN ANDEREN OOK FACTUREREN (Multi-user) ***

  //call TraceEind('FactStartControles');
end;


create or replace procedure FactStartMaakFacturen(
  in  @fbGid              integer,
  in  @SoortFact          smallint,       // 0 = fact. Batch, 1 = fact. direct, 2 = orderbev., 3 = Pakbon, 4 = Proforma, 5 = Projectfactuur, 6 = Directe levering (pakbon voor DL)
  in  @LayoutSoort        smallint,
  in  @SorteerOp          smallint,       //1 = deb.nummer; 2 = zoekcode
  in  @Ascending          smallint,       //0 = descending, 1=ascending
  in  @LayoutNummer       integer,        // Indien NULL, dan gewoon die van de vaste gegevens pakken, anders deze invullen
  in  @BoekDatum          date,
  in  @FactuurDatum       date,        //Indien @soortfact=pakbon (3 of 6), dan is dit de t/m leverdatum!
  in  @BedragBetaald      numeric(15,2),
  in  @VerschilAfboeken   smallint,
  out @BjGid		  integer
)
begin
  // -----------------------------------  FACTUREN AANMAKEN , FACTUURKOP VULLEN ETC -----------------------------------------
  declare @Stukskorting                smallint;
  declare @FrefGid                     integer;
  //Variabelen tbv. adresgegevens van de debiteur
  declare @OrkInclBtw                  smallint;
  declare @VerzendAdres                integer;
  declare @factuurgid                  integer;
  //Loopje orders
  declare @orknummer                   numeric(10,0);
  declare @VolgOrder                   integer;
  declare @VorigeVolgOrder             integer;
  declare @OrkGid                      integer;
  declare @PfvkGid		       					 integer;
  declare @ProjGid		       					 integer;
  declare @OrkNawGid                   integer;
  declare @OrkFactuurNawGid            integer;
  declare @OrkApartFactureren          smallint;
  declare @OrkVerzendadres             smallint;
  declare @VerzendAdresNummer          integer;
  declare @OrkFactuurAdres             smallint;
  declare @ValNummer                   integer;
  declare @BtcNummer                   integer;
  declare @DebTaalGid                  integer;
  declare @DefTaalGid                  integer;
  declare @DocSluitRegel               nchar(500);
  declare @AlgOrderKortingsOpm         nchar(500);
  declare @vofLevOokTarief             smallint;
  declare @vofLevOokTekst              smallint;
  declare @fkFactuurNummer             nchar(40);

  declare @IsRapNummerNodig            smallint;
  declare @ObvAantal                   smallint; //0 = obv. aantal besteld, 1 = obv. aantal deze factuur, 2 = obv. aantal deze levering
  declare @TotLeverDatum               Date;  //Om verwarring te voorkomen wordt deze gevuld indien nodig

  // Projecten
  declare @TijdVakAanduiding    			 smallint;
  declare @TijdvakBegin								 date;
  declare @TijdvakEind								 date;

  declare @VorigOrkFactuurNawGid       integer;
  declare @VorigOrkNawGid              integer;

  declare Cursor_TeFacturerenOrders no scroll cursor for
    select tfoFactNr, OrkGid, OrkPfvkGid, OrkNummer,  OrkNawGid,  OrkFactuurNawGid, OrkApartFaktureren,  OrkVerzendadres,  OrkAdrGid,           OrkFactuurAdres,  OrkValNummer , OrkBtcNummer
    from   tabTeFacturerenOrders
           inner join tabOrderKop on (OrkGid = tfoTeFactOrkGid)
           inner join tabNaw on ((if OrkFactuurNawGid is null then OrkNawGid else OrkFactuurNawGid endif) = NawGid)
           inner join tabNawFile on (NawFilNawGid = NawGid)
    where  exists(select 1
                  from   tabOrderRegel
                  where      (OrrOrkGid = OrkGid)
                         and ((OrrRegelSoort = 2) or //Artikel: altijd opnemen
                              (OrrRegelSoort = 1 and @vofLevOokTarief = 1) or //Tariefregel
                              (OrrRegelSoort = 0 and @vofLevOokTekst = 1)     //Tekstregel
                             )
                 )
           and tfoSessieFbGid = @FbGid
  order by if @Ascending = 0 then if @SorteerOp = 1 then NawFilNummer else NawFilZoekCode endif else '' endif desc,
           if @SorteerOp = 1 then NawFilNummer else NawFilZoekCode endif asc,
           tfoFactNr
  for read only;

  //call TraceBegin('FactStartMaakFacturen > @fbGid = ' + string(@fbGid) + ', @SoortFact = ' + string(@SoortFact) + ', @LayoutSoort = ' + string(@LayoutSoort) + ', @SorteerOp = ' + string(@SorteerOp) + ', @Ascending = ' + string(@Ascending)+', @LayoutNummer = ' + string(@LayoutNummer) + ', @BoekDatum = ' + string(@BoekDatum) + ', @FactuurDatum = ' + string(@FactuurDatum) + ', @BedragBetaald = ' + string(@BedragBetaald) + ', @VerschilAfboeken = ' + string(@VerschilAfboeken));

  select vofIsStukskorting into @Stukskorting from tabVasteGegevensOrdersFactureren;

  //Default taalcode opvragen voor als de tekst op factuur uit tarief/tekstblok moet komen
  select first vofTekstOpFactuurTaalGid into @DefTaalGid from tabVasteGegevensOrdersFactureren;
  //Ook de algemene kortingstekst voor die taal opvragen voor als de specifieke tekst voor de korting leeg is.
  select DocSluitRegel into @AlgOrderKortingsOpm from tabdocumentsluitregel where DocSluitDocSoort = 100 and DocSluitTaalGid = @DefTaalGid; //DocSoort=100 betekent: tekst voor korting

  //En de datum ophalen
  select PerBjGid into @BjGid from tabPeriode where @BoekDatum between BeginDatum and EindDatum;

  //Factuurkop toevoegen
  //call Trace('Facturen aanmaken');
  set @VorigeVolgOrder  = -1; //Bepaalt wanneer we een nieuw document gaan aanmaken (dus de 1e keer altijd!)
  set @FactuurGid       = null;

  // Bepaal of het nodig is om een layoutnummer te hebben
  set @IsRapNummerNodig = 1;

  // Betaald bedrag altijd vullen zodat te betalen ook wordt berekend
  set @BedragBetaald = isnull(@BedragBetaald,0);
  set @VerschilAfboeken = isnull(@VerschilAfboeken, 0);

  //tbv. overnemen tekst- en tariefregels
  if @SoortFact in (3, 6) then
    //Pakbon, dus alleen opnemen als zo in de vaste gegevens is aangegeven
    select first vofLevOokTarief, vofLevOokTekst into @vofLevOokTarief, @vofLevOokTekst from tabVasteGegevensOrdersFactureren;
    //Pakbon-> leverdatum is gelijk aan boekdatum, TotLeverdatum is ingegeven
    set @TotLeverDatum = @FactuurDatum;
    set @FactuurDatum = @BoekDatum;
    // Bepaal of een rapportnummer eigenlijk wel nodig is (niet indien de pakbon toch niet wordt afgedrukt)
    select first vofLevIsPakbonAfdrukken into @IsRapNummerNodig from tabVasteGegevensOrdersFactureren;
  else
    //Geen pakbon, dus altijd opnemen
    set @vofLevOokTarief = 1;
    set @vofLevOokTekst  = 1;
  end if;

  // Bepaal de regeltotaal, kortingen en nettoprijzen moeten worden berekend op welke totalen
  case @layoutsoort
  when 20 then // orderbev.
    set @ObvAantal = 0; // obv. aantal besteld
  when 30 then // pakbon
    set @ObvAantal = 2; // obv. aantal deze levering
  when 35 then // pakbon
    set @ObvAantal = 2; // obv. aantal deze levering (wordt berekend als Afgeleverd in DL)
  when 40 then // proforma
    // Bepaal uit de vaste gegevens
    select first vofProformaObv into @ObvAantal from tabVasteGegevensOrdersFactureren;
  when 50 then // factuur batch
    set @ObvAantal = 1; // obv. aantal deze factuur
  when 60 then // factuur direct
    set @ObvAantal = 1; // obv. aantal deze factuur
  when 65 then // factuur project
    set @ObvAantal = 1; // obv. aantal deze factuur
  else
    set @ObvAantal = 0; // obv. aantal besteld
  end case;

  call ProgressAdd( 1 );

  open Cursor_TeFacturerenOrders;
  LoopOrders:
  Loop
    set @VorigOrkNawGid = @OrkNawGid;
    set @VorigOrkFactuurNawGid = @OrkFactuurNawGid;
    fetch next Cursor_TeFacturerenOrders into @VolgOrder, @OrkGid, @PfvkGid, @OrkNummer, @OrkNawGid, @OrkFactuurNawGid, @OrkApartFactureren, @OrkVerzendadres, @VerzendAdresNummer, @OrkFactuurAdres, @ValNummer, @BtcNummer;
    if sqlstate = '02000' then
      leave LoopOrders;
    end if;
    //call Trace('FactuurKop; gevonden volgorde:'+string(@VolgOrder)+', order: '+string(@OrkNummer)+', OrkGid='+string(@OrkGid));
    call ProgressAdd( 1 );

    //Een nieuwe factuur aanmaken als de order voor een volgende factuur is
    if @VorigeVolgOrder is null or @VolgOrder is null or @VorigeVolgOrder <> @VolgOrder then
      set @VorigeVolgOrder = @VolgOrder;

      //call Trace('Factuurkop; nieuwe factuur aanmaken voor @OrkNummer='+string(@OrkNummer)+', @OrkGid='+string(@OrkGid));
      if @FactuurGid is not null then
        //Eerst van de af te sluiten (oude) factuur de juiste berekeningen plegen
        call FacturerenBerekenGegevens( @FactuurGid, @LayoutSoort, @BedragBetaald, @VerschilAfboeken );
        // Adresgegevens aan de factuurkop en referentie toevoegen
        call FactureringVulAdressenIn(@FactuurGid, @LayoutSoort, IsNull(@VorigOrkFactuurNawGid, @VorigOrkNawGid));
      end if;

      //Nieuwe factuur aanmaken
      set @FactuurGid = FacturerenMaakNieuweFactuur(@fbGid, @FactuurDatum, @LayoutSoort, @OrkGid, @BtcNummer, @LayoutNummer, @IsRapNummerNodig);
      if @FactuurGid is not null then
        select fkIsInclBtw into @OrkInclBtw from tabFactuurKop where FkGid = @FactuurGid;

        //Vrije rubrieken van de F A C T U U R D E B I T E U R
        //MR Bug# 25633: Alleen als je layoutsoort = pakbon altijd de order debiteur pakken.
        call FactureringOvernemenVrijeRubrieken(0, @FactuurGid, if @layoutsoort in (30, 35) then @OrkNawGid else if @OrkFactuurNawGid is null then @OrkNawGid else @OrkFactuurNawGid endif endif, 0);

        //Vrije rubrieken van het P R O J E C T
        if @LayoutSoort = 65 then
          select PfvkProjGid into @ProjGid from tabProjectFactuurVoorstelKop where PfvkGid = @PfvkGid;
          call FactureringOvernemenVrijeRubrieken(2, @FactuurGid, @ProjGid, 0);
        end if;

        //Taal van de debiteur
        select NawTaalGid into @DebTaalGid from tabOrderKop inner join tabNaw on (OrkNawGid = NawGid) where OrkNummer = @OrkNummer and OrkSoort = (if @LayoutSoort = 65 then 1 else 0 endif);
        //ACW 22-09-2010: Uitbreiding DL
        if @SoortFact = 6 /*Directe Levering*/ then
          // Leveranciersgegevens aan factuurkopgegevens toevoegen
          update tabFactuurkop
          set fkDirLevNummer       = NawFilNummer,
              FkDirLevZoekCode     = NawFilZoekCode,
              FkDirLevNaam         = AdrNaam1,
              FkDirLevBstKopNummer = BstKopNummer,
              FkDirLevMokNummer    = MokNummer,
              fkFactStatus         = 1 // Wordt anders niet geinitialiseerd!!
          from
            tabTeFacturerenOrders
            inner join tabTeFacturerenOrderRegels on (tforTfoGid = TfoGid)
            inner join tabOrderRegel on (OrrGid = tforOrrGid)
            // Opzoeken leverancier 'magazijnontvangst' van verkooporderregel via Bestelling of directe uit Magazijnontvangst
            left outer join (tabBestelRegelDetail
                             inner join tabBestelRegel on (BstRglGid = BrdBstRglGid)
                             inner join tabBestelKop   on (BstKopGid = BstRglBstKopGid)
                            ) on (BrdOrrGid = OrrGid)
            left outer join (tabMagazijnOntvangstenDetail
                             inner join tabMagazijnOntvangsten    on (MagOntGid = MagOntDetMagOntGid)
                             inner join tabMagazijnOntvangstenKop on (MokGid = MagOntMokGid)
                            ) on (   ((MagOntDetOrrGid is not null) and (MagOntDetOrrGid = OrrGid))  // Indien MagOntDetOrrGid<>Null, dan rechtstreeks de koppeling gevonden
                                  or ((MagOntDetOrrGid is     null) and (MagOntDetBrdGid = BrdGid))  // Indien MagOntDetOrrGid= Null, dan de koppeling via bestelling opzoeken
                                 )
            inner join tabNawFile on (NawFilNawGid = MokNawGid and NawFilFonID = 'C')
            inner join tabNaw     on (NawGid       = NawFilNawGid and nawGid = MokNawGid)
            inner join tabAdres   on (AdrGid       = NawGidVestiging)
          where FkGid = @FactuurGid and TfoSessieFbGid = @FbGid
             and OrrOrkGid = @OrkGid;
        end if;
      end if;

      //Teller voor de referentie (de orders) resetten
      set @FrefGid = 0;
    end if;

    // *** Deze order binnen deze groep in de betreffende factuur zetten ***
    if @FactuurGid is not null then
      //We hebben een geldige order toe te voegen
      //call Trace('Referentie toevoegen van order:'+string(@OrkGid)+'; factuurgid='+string(@FactuurGid));
      set @FrefGid = FacturerenMaakNieuweReferentie(@FactuurGid, @OrkGid);

      //Vrije rubrieken van de O R D E R K O P
      call FactureringOvernemenVrijeRubrieken(3, @FrefGid, @OrkGid, 0);

      //Vrije rubrieken van de O R D E R D E B I T E U R
      call FactureringOvernemenVrijeRubrieken(1, @FrefGid, @OrkNawGid, 0);

			//Ordercolli-regels overnemen bij alle documenten
			insert into tabFactuurColli (  FclfrefGid,    FclRegelNr,  FclColtCode, FclColtCodeVervoerder, FclColtOmschrijving, FclColtLengteEenheid, FclAantal, FclGewicht,  FclVolume,    FclHoogte, FclBreedte,   FclDiepte, FclTrackTraceCode, FclTrackTraceUrl, FclOpmerking)
	  														select @FrefGid,   OrclRegelNr,     ColtCode,    ColtCodeVervoerder,    ColtOmschrijving,    ColtLengteEenheid, OrclAantal, OrclGewicht, OrclVolume, OrclHoogte, OrclBreedte, OrclDiepte, OrclTrackTraceCode, OrclTrackTraceUrl, OrclOpmerking
	  														from tabOrderColli left outer join tabColliType on OrclColtGid = ColtGid where OrclOrkGid = @OrkGid;

      // *** orderregels ***

      //call Trace('Orderregels toevoegen van order:'+string(@OrkGid));
      call FacturerenToevoegenOrderRegelGegevens(@SoortFact, @FrefGid, @DebTaalGid, @DefTaalGid, @Stukskorting, @ObvAantal, @OrkGid, @vofLevOokTarief, @vofLevOokTekst, @FactuurDatum);

      //Tekst voor de orderkorting erbijzoeken
      select DocSluitRegel into @DocSluitRegel from tabdocumentsluitregel where DocSluitDocSoort = 100 and DocSluitTaalGid = @DebTaalGid;  //DocSoort=100 betekent: tekst voor korting

      //LET OP: We houden nu alleen rekening met orderkorting als extra regel! Dus: bereken over alleen alle regels en het is een % of een vast bedrag! geen rekening houdende met BTW!!!

      insert into tabFactuurExtraRegel( ferFrefGid,       ferRegelNummer, ferSoortRegel,      ferTekstOpFactuur,
                                        ferPercentage,    ferBasisBedrag, ferKortToeslBedrag, ferBtwCode,
                                        ferBtwPercentage, ferBtwBasis,    ferBtwBedrag,       ferRegelTotaal,
                                        ferBerekenOverTarief, ferBerekenOverArtikel, ferBerekenOverEmballage, ferBerekenOverKorting, ferBerekenOverToeslag )
      select @FrefGid, OerRegelNr, OerRegelSoort,
             if isnull(@DocSluitRegel,'')='' then @AlgOrderKortingsOpm else @DocSluitRegel endif TekstOpFactuur,
             OerPerc,
             isnull((select sum(frRegelTotaal) from tabFactuurRegel where frFrefGid = @FrefGid),0) BasisBedrag,
             if OerPerc is null then
               OerBedrag
             else
               OerPerc * BasisBedrag / 100
             endif KortingToeslagBedrag,
             OerBtwCode,
             BtwPercentage,
               OerPerc / 100 * sum(if @OrkInclBtw = 1 then frRegelTotaal / (100 + frBtwPercentage) * 100 else frRegelTotaal endif) BtwBasis,
               OerPerc / 100 * sum(if @OrkInclBtw = 1 then frRegelTotaal / (100 + frBtwPercentage) * 100 else frRegelTotaal endif * frBtwPercentage / 100) BtwBedrag,
             KortingToeslagBedrag RegelTotaal,
             2, 2, 2, 1, 1
      from   tabOrderExtraRegel
             left outer join tabBtw on (BtwCode = OerBtwCode)
             left outer join tabFactuurRegel on (frFrefGid = @FrefGid)
      where  OerOrkGid = @OrkGid
      group by OerRegelNr, OerRegelSoort, TekstOpFactuur, OerPerc, KortingToeslagBedrag, OerBtwCode, BtwPercentage, OerBedrag;

      // Projecten : Tijdvak invullen volgens instelling
      set @TijdvakBegin = null;
      set @TijdvakEind  = null;
		  set @TijdVakAanduiding = (select isnull(ProjVastDefaultFactTijdvakAanduiding, 0) from tabProjectVastegegevens);
		  if (@LayoutSoort = 65) and (@TijdvakAanduiding <> 0) then
				select
					if @TijdVakAanduiding = 1 then (select BeginDatum from tabPeriode where Min(PbrMutatieDatum) between BeginDatum and EindDatum ) else Min(PbrMutatieDatum) endif,
					if @TijdVakAanduiding = 1 then (select EindDatum  from tabPeriode where Max(PbrMutatieDatum) between BeginDatum and EindDatum ) else Max(PbrMutatieDatum) endif
					into @TijdvakBegin, @TijdvakEind
				from    tabFactuurReferentie
				  inner join tabProjectFactuurVoorstelKop on PfvkGid = frefPfvkGid
				  inner join tabProjectFactuurVoorstelRegel on PfvrPfvkGid = PfvkGid
				  inner join tabProjectFactuurvoorstelRealisatie on pfvlFvrGid = PfvrGid
				  inner join tabProjectBoekingsRegel on pfvlPbrGid = PbrGid
				where frefFkGid = @FactuurGid;
				update tabFactuurKop set FkTijdvakBegin = @TijdvakBegin, FkTijdvakEind = @TijdvakEind where FkGid = @FactuurGid;
		  end if;


      if @SoortFact = 6 /*Directe Levering*/ then
        // Factuurnummer maken
        // Dit moet achteraf, zodat de ordernummers bekend zijn (worden soms gebruikt als pakbonnummer!)
        set @fkFactuurNummer = GeefNieuwFactuurNummer( @BjGid, @FbGid, @FactuurGid, 35 /*Pakbon-DL*/ );
        update tabFactuurkop
        set    fkFactuurNummer = @fkFactuurNummer,
               fkFactuurNummer_Lengte = length(IsNull(@fkFactuurNummer, ''))
        where  FkGid = @FactuurGid;

      end if;

    else
      // FactuurGid is null, kan alleen als de eerste order van de verzamelfactuur geen layout heeft op dit punt,
      // de andere orders van deze fact dus ook als niettefact bestempelen
      insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
        select @fbGid, @OrkGid, 4, 1 where @OrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @FbGid);
    end if;

    //call Trace('Einde order in de factuur '+string(@FactuurGid) );
  End loop LoopOrders;
  close Cursor_TeFacturerenOrders;

  // *** Einde van de orderlus; alle facturen zijn nu aangemaakt ***

  //De laatste factuur netjes verwerken...
  if @FactuurGid is not null then
    //De laatste factuur is nog niet juist herberekend; dus alsnog doen!
     call FacturerenBerekenGegevens( @FactuurGid, @LayoutSoort, @BedragBetaald, @VerschilAfboeken );
      // Adresgegevens aan de factuurkop en referentie toevoegen
      call FactureringVulAdressenIn(@FactuurGid, @LayoutSoort, IsNull(@OrkFactuurNawGid, @OrkNawGid));
  end if;

  call ProgressAdd( 2 );

  //call TraceEind('FactStartMaakFacturen');
end;


// --------------------------- VERWIJDER FACTUREN ------------------------------
create or replace procedure FactStartVerwijderFacturen(
  in  @fbGid              integer,
  in  @ConnId             integer,
  in  @LoginTime          nchar(50),
  in  @SoortFact          smallint,
  in  @LayoutSoort        smallint,
  in  @SorteerOp          smallint,    //1 = deb.nummer; 2 = zoekcode
  in  @Ascending          smallint,    //0 = descending, 1=ascending
  in  @BedragenGroterDan  numeric(15,2),
  in  @UseLockedOrkGid    integer
)
begin
  declare @OrkGid            integer;
  declare @PfvkGid		       integer;
  declare @VorigeOrkGid      integer;
  declare @ControleerPakbonLayout smallint;

  //call TraceBegin('FactStartVerwijderFacturen > @fbGid = ' + string(@fbGid) + ', @ConnId = ' + string(@ConnId) + ', @LoginTime = ' + string(@LoginTime) + ', @SoortFact = ' + string(@SoortFact) + ', @LayoutSoort = ' + string(@LayoutSoort) + ', @SorteerOp = ' + string(@SorteerOp) + ', @Ascending = ' + string(@Ascending) + ', @BedragenGroterDan = ' + string(@BedragenGroterDan) + ', @UseLockedOrkGid = ' + string(@UseLockedOrkGid));

  call FacturerenVerwijderLegeFacturen(@FbGid, @LayoutSoort);
  call ProgressAdd( 2 );

  // *** LET OP : Hieronder volgt COMMIT ter voorkoming van een deadlock situatie
//  COMMIT;

  //Alle facturen die niet 'voldoende bedrag' en minder dan 5 orders hebben verwijderen, maar alleen als de order niet op 'aparte factuur=ja' staat
  if @BedragenGroterDan is not null and @LayoutSoort = 50 then
    //call Trace('FactStartVerwijderFacturen > Facturen waarvan totaalbedrag te laag in NietGefactureerd plaatsen');
    //orders worden niet afgedrukt
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, frefOrkGid, 3, 1 //'Totaalbedrag is te klein'
    from tabFactuurKop inner join tabFactuurReferentie on frefFkGid = FkGid inner join tabOrderkop on (OrkGid = frefOrkGid)
    where fkFbGid = @fbGid and //Facturen van deze batch
          fkFactTotInBtw < @BedragenGroterDan and //Bedrag is inderdaad te klein
          fkGid in (select FkGid from tabFactuurKop inner join tabFactuurReferentie where fkFbGid = @fbGid group by FkGid having count(*)<=4) //Heeft inderdaad minder dan 5 orders
          and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid) and //Komt inderdaad nog niet in de niet-te-factureren lijst voor
          OrkApartFaktureren <> 0; //Alleen als *apart factureren* niet op *Ja* staat.

    //Verwijderen uit factureringslijst
    //call Trace('FactStartVerwijderFacturen > Facturen verwijderen die in NietGefactureerd zitten');
    delete tabFactuurKop
    where fkFbGid = @fbGid and
          FkGid in (select frefFkGid
                    from tabFactuurReferentie
                         inner join tabFactuurNietGefactureerd on (fngorkgid = frefOrkGid and fngFbGid = @fbGid)
                    where frefFkGid = FkGid);
  end if;

  // *** LET OP : Hieronder volgt COMMIT ter voorkoming van een deadlock situatie
//  COMMIT;

  call ProgressAdd( 2 );

  //Facturen zonder factuurregels verwijderen (Wel eerst de orders ervan in de niet-gefact/gelev. lijst zetten)
  //call Trace('FactStartVerwijderFacturen > Facturen zonder factuurregels in NietGefactureerd plaatsen');
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
  select @FbGid, frefOrkGid, if @LayoutSoort = 30 then 10 else 9 endif, 1 //Heeft geen te factureren/leveren orderregels
  from   tabFactuurKop inner join tabFactuurReferentie on frefFkGid = FkGid
  where  fkFbGid = @fbGid and //Facturen van deze batch
         not exists (select first 1 from tabfactuurregel where frFrefGid=FrefGid)
         and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); //Komt inderdaad nog niet in de niet-te-factureren lijst voor

  //Nu die referenties zonder regels verwijderen
  //call Trace('FactStartVerwijderFacturen > Verwijderen referenties zonder orderregels');
  delete from tabfactuurreferentie
  where frefFkgid in (select FkGid from tabFactuurKop where FkFbGid = @FbGid) and
         not exists (select first 1 from tabfactuurregel where frFrefGid=FrefGid);
  //En de facturen zonder referentie verwijderen
  //call Trace('FactStartVerwijderFacturen > Verwijderen factuurkoppen zonder referenties');
  delete from tabfactuurkop where fkFbGid = @FbGid and not exists (select 1 from tabfactuurreferentie where frefFkGid = FkGid);

  // *** LET OP : Hieronder volgt COMMIT ter voorkoming van een deadlock situatie
//  COMMIT;

  // RS 5-4-2012 bug 34541: Sinds introductie projecten werd onterecht ook een pakbon afgedrukt obv batchfactuurinstellingen.
  // Kan nu niet ineens disabled worden, maar wel zorgen dat er netjes op de layout gecontroleerd wordt.
  set @ControleerPakbonLayout = 0;
  if @SoortFact = 0 then
    set @ControleerPakbonLayout = 1;
  elseif @SoortFact = 5 then
    set @ControleerPakbonLayout = (select vofLevOokTarief from tabVasteGegevensOrdersFactureren);
  end if;

  // Als we een pakbon afdrukken bij batchfacturering, dan alle facturen eruit halen waarvoor geen pakbonlayout bestaat
  if (@ControleerPakbonLayout = 1)  then
    // Ok, we hebben batchfacturering
    if exists(select 1 from tabVasteGegevensOrdersFactureren where vofPakbonBijFactureren = 1 and vofLeverenBijFactureren = 1) then
      // Ok, we moeten ook de pakbon afdrukken (en leveren) bij factureren, dus alle facturen ZONDER pakbonlayout eruit halen
      //call Trace('FactStartVerwijderFacturen > Check voor pakbonlayout per taal deel 1');

      insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
      select @FbGid, frefOrkGid, 15, 1 //Geen pakbonlayout ingegeven
      from   tabFactuurKop
             inner join tabFactuurReferentie on FrefFkGid = FkGid
             inner join tabTaal on (TaalCode = fkTaalCode)
             left outer join tabDocumentLayout on (DocLayTaalGid = TaalGid and DocLayDocSoort = 30)
      where  FkFbGid = @FbGid and    // Facturen van deze batch
             ((fkIsInclBtw = 0 and DocLayRapGidexcl is null) or  // Factuur excl. BTW -> indien pakbon excl. btw leeg *of*
              (fkIsInclBtw = 1 and DocLayRapGidIncl is null));   // Factuur incl. BTW -> indien pakbon incl. btw leeg
      //En de facturen van deze orders verwijderen
      delete from tabfactuurkop
      where fkFbGid = @FbGid
            and fkGid in (select frefFkGid
                          from tabFactuurReferentie
                               inner join tabFactuurNietGefactureerd on (frefOrkGid = fngOrkGid and fngFbGid = @fbGid)); // ACW1-11-2002: Ook @fbgid testen!!
    end if;
  end if;

  // *** LET OP : Hieronder volgt COMMIT ter voorkoming van een deadlock situatie
//  COMMIT;

  //De orderlocks van de niet-gefactureerde orders weer vrijgeven
  //Let op: dit MOET alvorens tabFactuurBatch op te schonen!!
  //Let op: Dit geldt alleen voor de orders waarvoor NIET geldt dat ze al gelocked zijn
  //call Trace('Locks van de orders die toch niet worden verwerkt weer vrijgeven');
  set @VorigeOrkGid = null;
  OrderLockLoop:
  loop
    set @OrkGid = null;
    select first fngOrkGid, OrkPfvkGid into @OrkGid, @PfvkGid from tabFactuurNietGefactureerd inner join tabOrderKop on fngOrkGid = OrkGid
    where fngFbGid = @FbGid and fngReden <> 6 and (@VorigeOrkGid is null or fngOrkGid > @VorigeOrkGid) and (@UseLockedOrkGid is null or fngOrkGid<>@UseLockedOrkGid) and fngLockedByMe = 1 order by fngOrkGid;
    if @OrkGid is null then
      leave OrderLockLoop;
    end if;
    set @VorigeOrkGid = @OrkGid;
    //call Trace('FactStartVerwijderFacturen > Vrijgeven order; @OrkGid = ' + string(@OrkGid) + ', @SoortFact = ' + string(@SoortFact));
    if @ConnId = null then
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
      if @SoortFact = 5 then  // ProjectFactuur
        //call Trace('FactStartVerwijderFacturen > LockReleaseProjectFactuurVoorstelKop - @SoortFact = ' + string(@SoortFact) + ', @@SpId = ' + string(@@SpId) + ', @PfvkGid = ' +string(@PfvkGid));
        call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabProjectFactuurVoorstelKop', @PfvkGid);
      end if;
    else
      call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid);
      if @SoortFact = 5 then  // ProjectFactuur
        //call Trace('FactStartVerwijderFacturen > LockReleaseProjectFactuurVoorstelKop - @SoortFact = ' + string(@SoortFact) + ', @ConnId = ' + string(@ConnId) + ', @PfvkGid = ' + string(@PfvkGid));
        call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabProjectFactuurVoorstelKop', @PfvkGid);
      end if;
    end if;
  end loop OrderLockLoop;

  //call TraceEind('FactStartVerwijderFacturen');
end;


create or replace procedure FactStartVulTussenTabel(
  in  @ConnId             integer,
  in  @LoginTime          nchar(50),
  in  @SoortFact          smallint,
  in  @SelecteerOp        smallint,    //1 = deb.nummer; 2 = zoekcode
  in  @VanDeb             nchar(10),    //Deb.nummer of -zoekcode
  in  @TotDeb             nchar(10),
  in  @SorteerOp          smallint,    //1 = deb.nummer; 2 = zoekcode
  in  @Ascending          smallint,    //0 = descending, 1=ascending
  in  @VanOrderNummer     numeric(10,0),
  in  @TotOrderNummer     numeric(10,0),
  in  @VanMagCode         nchar(3),
  in  @TotMagCode         nchar(3),
  in  @BoekDatum          date,
  in  @FactuurDatum       date,        //Indien @soortfact=pakbon (3), dan is dit de t/m leverdatum!
  in  @WijzigStatus       smallint,
  in  @UseLockedOrkGid    integer,
  out @LayoutSoort        integer,
  inout @fbGid            integer,
  in  @IndienGeenBackorders smallint,
  in  @JobImportVerwerkId integer,
  in  @NoPaperPrints      smallint default 0 )
begin
  //@SoortFact:
  // 0 = fact. Batch
  // 1 = fact. direct
  // 2 = orderbev. (dus orders niet samenvoegen, ook geen factuurnummer aanmaken)
  // 3 = Pakbon (let op: Levering!!!)
  // 4 = Proforma
  // 5 = fact. Project

  declare @ProgressToDo                integer;
  declare @AfdrukAcceptGiro            smallint;
  //variabelen tbv. bepalen welke orders wel en niet meegaan
  declare @FactNr                      integer;
  declare @TotLeverDatum               Date;  //Om verwarring te voorkomen wordt deze gevuld indien nodig
  //Orderlocks ongedaan maken
  declare @AcbGid                      integer;

  //call TraceBegin('FactStartVulTussenTabel > @SoortFact = ' + string(@SoortFact) + ', @SelecteerOp = ' + string(@SelecteerOp) + ', @VanDeb = ' + string(@VanDeb) + ', @TotDeb = ' + string(@TotDeb)+', @SorteerOp='+string(@SorteerOp)+', @Ascending='+string(@Ascending)+', @VanOrderNummer='+string(@VanOrderNummer)+', @TotOrderNummer='+string(@TotOrderNummer)+', @VanMagCode='+string(@VanMagCode)+', @TotMagCode='+string(@TotMagCode)+', @BoekDatum='+string(@BoekDatum)+', @FactuurDatum='+string(@FactuurDatum)+', @UseLockedOrkGid='+string(@UseLockedOrkGid));

  //Soort layout vast bepalen (makkelijk voor later)
  case @SoortFact
    when 0 then set @LayoutSoort = 50  //Batch
    when 1 then set @LayoutSoort = 60  //Direct
    when 2 then set @LayoutSoort = 20  //Orderbevestiging
    when 3 then set @LayoutSoort = 30  //Pakbon
    when 4 then set @LayoutSoort = 40  //Proforma
    when 5 then set @LayoutSoort = 65  //Project
  end case;

  if @LayoutSoort in (50,60,65) then
    // Factuur, dus acceptgiro is mogelijk
    select DocOrdAfdrukkenFactuurAcceptgiro into @AfdrukAcceptGiro from tabDocument where DocSoort = @LayoutSoort;
  else
    // Geen factuur, dus ook geen acceptgiro toestaan -> Alleen de factuur/pakbon/offerte/...
    set @AfdrukAcceptGiro = 0;
  end if;

  if @LayoutSoort <> 65 then  // De factuurbatch voor projectfacturen wordt aangemaakt in storedproc 'AanmakenProjectOrders'
    //Factuurbatch aanmaken
    insert into tabFactuurBatch (fbAangemaaktDoor, fbAangemaaktOp, fbSoortBatch, fbAcceptGiroAfgedrukt, fbPakbonAfgedrukt)
    values(@@GebruikerCode, now(), @LayoutSoort, @AfdrukAcceptGiro, if @LayoutSoort = 30 then (select vofLevIsPakbonAfdrukken from tabVasteGegevensOrdersFactureren) else 0 endif);

    set @fbGid = @@Identity;
    if @ConnId is null then
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid), 0);
    else
      call LockSetOnId(@ConnId, @LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid), 0);
    end if;
  end if;

  call ProgressCreate( 0, 1,_U('Aanmaken ordergegevens'));

  if @SoortFact = 3 then
    //Pakbon-> leverdatum is gelijk aan boekdatum, TotLeverdatum is ingegeven
    set @TotLeverDatum = @FactuurDatum;
    set @FactuurDatum = @BoekDatum;
  end if;

  //Eventuele data op 'nu' zetten (=systeemdatum)
  if @BoekDatum is null then
    set @BoekDatum = now();
  end if;
  if @FactuurDatum is null then
    set @FactuurDatum = now();
  end if;

  //Invoerranges eventueel aanpassen
  call FacturerenBepaalRange( @SelecteerOp, @VanDeb, @TotDeb, @VanOrderNummer, @TotOrderNummer, @VanMagCode, @TotMagCode );

  // Niet gefactureerd-tabel opschonen
  delete from tabFactuurNietgefactureerd
  where 'fbGid='+string(fngFbGid) not in (select qlockpkey from qtablock where qlocktablename='tabFactuurBatch');

  //De orders in de range opzoeken, eventueel al wat orders eruit knikkeren ivm. lock/niet vrijgegeven
  call FacturerenBepaalRangeVanOrders(@FbGid, @ConnId, @LoginTime, @UseLockedOrkGid, @SoortFact, @SelecteerOp, @SorteerOp, @VanDeb, @TotDeb, @Ascending, @VanOrderNummer, @TotOrderNummer, @VanMagCode, @TotMagCode, @TotLeverDatum, @LayoutSoort, @IndienGeenBackorders, @JobImportVerwerkId, @NoPaperPrints);

  //Aantal tbv. progress bijhouden
  select count(1) into @ProgressToDo from tabTeFacturerenOrders where tfoSessieFbGid = @FbGid;
  call ProgressSet(0, @ProgressToDo + 15, null );

  //call TraceEind('FactStartVulTussenTabel');
end;


create or replace procedure FactUnlockOrders(in @ConnId integer, in @LoginTime nchar(50), in @SoortBatch integer, in @FkGid integer, in @IgnoreOrkGid integer)
begin
  set @@ErrorTextProcedure = 'FactUnlockOrders > ';
  //call TraceBegin(@@ErrorTextProcedure + '@FkGid = ' + string(@FkGid));

  for @Cursor AS Cursor_OrdersFactuur cursor for
    select frefOrkGid @OrkGid, frefPfvkGid @PfvkGid from tabFactuurReferentie where frefFkGid = @FkGid
  for read only
  do
    if (@IgnoreOrkGid is null) or (@OrkGid <> @IgnoreOrkGid) then
      call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid);
    end if;

    if @SoortBatch = 65 then // Projectfactuur
    	delete tabOrderKop where OrkGid = @OrkGid;
      call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabProjectFactuurVoorstelKop', @PfvkGid);
    end if;

  end for;

  set @@ErrorTextProcedure = 'FactUnlockOrders';
  //call TraceEind( @@ErrorTextProcedure );
end;


create or replace procedure FacturerenAanmakenBoekingsgang( in @fbGid integer, in @BoekDatum date, in @LayoutSoort integer, in @ConnIdParam integer default null, in @LoginTimeParam datetime default null, out @BoekgangGid integer, out @BjGid integer, out @PerNr integer)
begin
  declare @ConnId integer;
  declare @LoginTime datetime;
  //Boeken van de hele facturering-batch
  //LET OP: Emballage nog niet geimplementeerd!!

  set @@ErrorTextProcedure = 'FacturerenAanmakenBoekingsgang( @fbGid='+string(@fbGid)+', @BoekDatum='+string(@BoekDatum)+', @LayoutSoort='+string(@LayoutSoort)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @ConnIdParam is null then
    set @ConnId = @@SpId;
    set @LoginTime = @@LoginTime;
  else
    set @ConnId = @ConnIdParam;
    set @LoginTime = @LoginTimeParam;
  end if;

  //call Trace('@ConnId='+string(@ConnId)+'; @ConnIdParam='+string(@ConnIdParam)+'; @@SpId='+string(@@SpId));

  //boekdatum leeg -> systeemdatum gebruiken
  if @BoekDatum is null then
    set @BoekDatum = now();
  end if;

  // *** vaste gegevens opvragen ***

  call BepaalBoekjaarEnPeriode( @BoekDatum, @BjGid, @PerNr );

  //Aanmaken van nieuwe boekingsgang en locken
  if @LayoutSoort = 50 then
    insert into tabBoekingsGang(BoekGangBjGid, BoekGangBronId, BronOms, BoekGangInGebruik, IsBoekGangDefinitief) values ( @BjGid, 19, _A('Factureren batch'),   1, 0);
    set @BoekgangGid = @@Identity;
  elseif @LayoutSoort = 65 then
    insert into tabBoekingsGang(BoekGangBjGid, BoekGangBronId, BronOms, BoekGangInGebruik, IsBoekGangDefinitief) values ( @BjGid, 26, _A('Factureren project'), 1, 0);
    set @BoekgangGid = @@Identity;
  else
    //Controleer of er al een boekingsgang tbv. baliefacturering bestaat. Zoja, dan die gebruiken, zonee, dan 1 aanmaken
    set @BoekgangGid = null;
    select qlockpkey into @BoekgangGid from qtablock where qlockconnection = @ConnId and qlocktablename = 'DirecteFacturering';
    if @BoekgangGid is null then
      insert into tabBoekingsGang(BoekGangBjGid, BoekGangBronId, BronOms, BoekGangInGebruik, IsBoekGangDefinitief) values ( @BjGid, 20, _A('Factureren direct'), 1, 0);
      set @BoekgangGid = @@Identity;

      // Bij directe fact locken we op de UI connectie. Via BG-trigger is de BG echter al gelocked op de verwerkconnectie, die releasen
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabBoekingsgang','BoekGangGid='+string(@BoekgangGid));
      // en nu op de UI connectie zetten
      call LockSetOnId(@ConnId, @LoginTime, 1, 'tabBoekingsgang','BoekGangGid='+string(@BoekgangGid), 0, 1);

      call LockSetOnId(@ConnId, @LoginTime, 1, 'DirecteFacturering', @BoekgangGid, 0);
    end if;
  end if;

  // Alvast een lock maken voor het factureeroverzicht
  call LockSetOnId(@ConnId, @LoginTime, 1, 'Factuuroverzicht', @FbGid, 0);

  //call TraceEind('FacturerenAanmakenBoekingsgang');

end;


create or replace procedure FacturerenBepaalRange( in @SelecteerOp integer, inout @VanDeb nchar(10), inout @TotDeb nchar(10), inout @VanOrderNummer nchar(10), inout @TotOrderNummer nchar(10), inout @VanMagCode nchar(3), inout @TotMagCode nchar(3))
begin

  set @@ErrorTextProcedure = 'FacturerenBepaalRange > @SelecteerOp='+string(@SelecteerOp)+', @VanDeb='+string(@VanDeb)+', @TotDeb='+string(@TotDeb)+', @VanOrderNummer='+string(@VanOrderNummer)+', @TotOrderNummer='+string(@TotOrderNummer)+', @VanMagCode='+string(@VanMagCode)+', @TotMagCode='+string(@TotMagCode);
  //call TraceBegin(@@ErrorTextProcedure);

  if @VanDeb is null then
    if @SelecteerOp = 1 then
      select first NawFilNummer   into @VanDeb from tabNawFile order by NawFilNummer;
    else
      select first NawFilZoekCode into @VanDeb from tabNawFile order by NawFilZoekCode;
    end if;
  end if;
  if @TotDeb is null then
    if @SelecteerOp = 1 then
      select first NawFilNummer   into @TotDeb from tabNawFile order by NawFilNummer   desc;
    else
      select first NawFilZoekCode into @TotDeb from tabNawFile order by NawFilZoekCode desc;
    end if;
  end if;
  if @VanOrderNummer is null then
    select first OrkNummer into @VanOrderNummer from tabOrderKop order by OrkNummer;
  end if;
  if @TotOrderNummer is null then
    select first OrkNummer into @TotOrderNummer from tabOrderKop order by OrkNummer desc;
  end if;

  if isnull(@VanMagCode, '') = '' then
    select first MagCode into @VanMagCode from tabMagazijn order by MagCode;
  end if;

  if isnull(@TotMagCode, '') = '' then
    select first MagCode into @TotMagCode from tabMagazijn order by MagCode desc;
  end if;

  set @@ErrorTextProcedure = 'FacturerenBepaalRange >  @VanDeb='+string(@VanDeb)+', @TotDeb='+string(@TotDeb)+', @VanOrderNummer='+string(@VanOrderNummer)+', @TotOrderNummer='+string(@TotOrderNummer)+', @VanMagCode='+string(@VanMagCode)+', @TotMagCode='+string(@TotMagCode);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure FacturerenBepaalRangeVanOrders(
  in @FbGid           integer,
  in @ConnId          integer,
  in @LoginTime       nchar(50),
  in @UseLockedOrkGid integer,
  in @SoortFact       integer,
  in @SelecteerOp     integer,
  in @SorteerOp       integer,
  in @VanDeb          nchar(10),
  in @TotDeb          nchar(10),
  in @Ascending       integer,
  in @VanOrderNummer  nchar(10),
  in @TotOrderNummer  nchar(10),
  in @VanMagCode      nchar(3),
  in @TotMagCode      nchar(3),
  in @TotLeverDatum   date,
  in @LayoutSoort     integer,
  in @IndienGeenBackorders  smallint,
  in @JobImportVerwerkId integer,
  in @NoPaperPrints   smallint default 0)
begin
  declare @OrkGid                     integer;
  declare @PfvkGid                    integer;
  declare @Result                     integer;
  declare @vofLevOokTarief            smallint;
  declare @vofLevOokTekst             smallint;
  declare @LeverenBijFactureren       integer;
  declare @PakbonAfdrukkenBijLeveren  smallint;
  declare @LockGid                    integer;

  declare local temporary table tmpTeFacturerenOrdersRange(
    tmpRangeOrkGid    integer,
    tmpNietFactureren integer   default 0, //Als 1, dan niet factureren/leveren etc. maar is wel gelocked, dus lock verwijderen!
    primary key (tmpRangeOrkGid)        //**RB** Opnemen in proc!!!!!
  ) on commit preserve rows;

  declare cursor_Orders_TeFactureren dynamic scroll cursor for
    select tmpRangeOrkGid from tmpTeFacturerenOrdersRange
  for read only;

  declare cursor_Orders_NietFactureren dynamic scroll cursor for
    select tmpRangeOrkGid, OrkPfvkGid from tmpTeFacturerenOrdersRange inner join tabOrderKop on tmpRangeOrkGid = OrkGid where tmpNietFactureren = 1
  for read only;

  set @@ErrorTextProcedure = 'Begin FacturerenBepaalRangeVanOrders > @FbGid='+string(@fbgid)+', @ConnId='+string(@ConnId)+', @LoginTime='+string(@LoginTime)+', @UseLockedOrkGid='+string(@UseLockedOrkGid)+', @SoortFact='+string(@SoortFact)+', @SelecteerOp='+string(@SelecteerOp)+', @VanDeb='+string(@VanDeb)+', @TotDeb='+string(@TotDeb)+', @VanOrderNummer='+string(@VanOrderNummer)+', @TotOrderNummer='+string(@TotOrderNummer)+', @VanMagCode='+string(@VanMagCode)+', @TotMagCode='+string(@TotMagCode)+', @TotLeverDatum='+string(@TotLeverDatum)+', @LayoutSoort='+string(@LayoutSoort);
  //call Trace(@@ErrorTextProcedure);

  // Controleer of we ook moeten leveren bij (balie)factureren
  set @LeverenBijFactureren = 0;
  set @PakbonAfdrukkenBijLeveren = 0;
  if @SoortFact = 0 then //Factuur
    if exists(select 1 from tabVasteGegevensOrdersFactureren where isnull(vofLeverenBijFactureren,0) = 1) then
      set @LeverenBijFactureren = 1;
    end if;
    select Isnull(vofPakbonBijFactureren, 0) into @PakbonAfdrukkenBijLeveren from tabVasteGegevensOrdersFactureren;
  end if;

  //Alle orders in de range onthouden
  if @JobImportVerwerkId = -1 then
	  insert into tmpTeFacturerenOrdersRange( tmpRangeOrkGid )
	  select   OrkGid
	  from     tabOrderKop
	  inner join tabNaw on (OrkNawGid = NawGid)
	  inner join tabNawFile on (NawFilNawGid = NawGid)
	  left outer join tabMagazijn on (MagGid = OrkDefaultMagGid)
	  where ((@LayoutSoort =  65 and OrkSoort = 1) or	 // Project order !
	  	     (@LayoutSoort <> 65 and OrkSoort = 0)) and	 // Verkoop order !
	  	    ((@SelecteerOp = 1 and nawFilNummer between @VanDeb and @TotDeb ) or
	         (@SelecteerOp = 2 and nawFilZoekCode between @VanDeb and @TotDeb ) ) and  //Alleen de debiteuren in de range
	        OrkNummer between @VanOrderNummer and @TotOrderNummer and                   //Alleen de orders in de range
	        MagCode between @VanMagCode and @TotMagCode;                                //Alleen de magazijnen in de range
	else
	  insert into tmpTeFacturerenOrdersRange( tmpRangeOrkGid )
	  select   OrkGid
	  from     tabOrderKop
	  inner join tabJobImportVerwerking on JobivImportRecordGid = OrkGid and JobivSoort = 3 /* qcImpLayoutXmlOrders */
	  where JobivJobVerwerkingId = @JobImportVerwerkId;
	end if;

  //Probeer de gevonden orders te locken (indien lock niet gelukt, dan vermelden op de afdruk en uit lijst verwijderen)
  open cursor_Orders_TeFactureren;
  OrderLoop:
  loop
    Fetch next cursor_Orders_TeFactureren into @OrkGid;
    if sqlstate = '02000' then
      leave OrderLoop;
    end if;

    //Probeer de order te locken; indien gelukt, dan opnemen, anders overslaan
    if (@orkgid = @UseLockedOrkGid) or (@LayoutSoort = 65) then
      //Vanuit de order zelf afdrukken, dus die is al door 'mij' gelocked, ff testen of de lock nog bestaat, zoniet, dan gaat er iets fout, dus niet overnemen
      // OF het is een projectorder, in dat geval is ie ook reeds gelockt door mij
      if @ConnId is null then
        set @result = 1 - LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
      else
        set @result = 1 - LockedById(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid);
      end if;
    else
      // Als we verwerken via jobs met een selectie, dan controleren op overneembare locks
      if @JobImportVerwerkId <> -1 then
        // Als er al een lock bestaat met vlaggetje qLockOvernemen overnemen aan, dan de lock overnemen
        select qLockGid into @LockGid from qtabLock where qLockTableName = 'tabOrderKop' and qLockSoort = 1 and qLockPkey = @OrkGid and qLockAutomatischOpruimen = 0 and qLockOvernemen = 1;
        if @LockGid is not null then
          update qtabLock set qLockConnection = @ConnId, qLockLoginTime = @LoginTime, qLockUser = @@GebruikerCode, qLockOvernemen = 0, qLockAutomatischOpruimen = 1 where qLockGid = @LockGid;
          set @Result = 0;
          //call Trace('FacturerenBepaalRangeVanOrders > Lock Overgenomen LockGid='+string(@LockGid));
        end if;
      end if;

      // Of niet via jobs, of geen overneembare lock, dan altijd zelf proberen te locken
      if @JobImportVerwerkId = -1 or @LockGid is null then
        call LockSetOnId(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid, @Result);
        //call Trace('FacturerenBepaalRangeVanOrders > Lock Zetten LockSetOnId='+string(@Result));
      end if;
    end if;

    if @Result <> 0 then
      //Lock is niet gelukt, dus verwijderen nadat die in de 'niet-gefactureerd'-tabel staat
      if not exists( select 1 from tabFactuurNietGefactureerd where fngFbGid = @fbGid and fngOrkGid = @OrkGid) then
        insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
        values( @fbGid, @OrkGid, 6, 0); //Order is in gebruik
      end if;
    end if;
  end loop OrderLoop;
  close cursor_Orders_TeFactureren;

  //Orders verwijderen die toch niet worden afgedrukt. Deze zijn nl. ook NIET gelocked!
  delete tmpTeFacturerenOrdersRange where tmpRangeOrkGid in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbGid);

  // @SoortFact:
  // 0: Batch
  // 1: Direct
  // 2: Orderbevestiging
  // 3: Pakbon
  // 4: Proforma
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe  )
  select @fbGid, OrkGid,
         case @SoortFact
           when 0 then if @LeverenBijFactureren = 1 and OrkVrijVoorLevering = 0 and OrkVrijVoorFaktureren <> 0 then 16 else 1 endif   // Orders niet vrijgegeven (voor facturering of levering)
           when 1 then if @LeverenBijFactureren = 1 and OrkVrijVoorLevering = 0 and OrkVrijVoorFaktureren <> 0 then 16 else 1 endif   // Orders niet vrijgegeven (voor facturering of levering)
           when 2 then 21   // Order niet goedgekeurd
           when 3 then 16   // Order niet voor leveren vrijgegeven
           //when 4 -> mag altijd worden afgedrukt
         end,
         1
  from   tmpTeFacturerenOrdersRange inner join tabOrderKop on (OrkGid = tmpRangeOrkGid) inner join tabNaw on (OrkNawGid = NawGid) inner join tabNawFile on (NawFilNawGid = NawGid)
  where  tmpNietFactureren = 0 and
         (( @SoortFact = 0 and OrkVrijVoorFaktureren = 0 ) or //facturering maar niet vrijgegeven voor facturering
          ( (@SoortFact = 3 or                                // Levering
             (@SoortFact = 0 and @LeverenBijFactureren = 1)   // OF leveren tijdens batchfactureren
            ) and OrkVrijVoorLevering = 0  )  or              // EN is niet vrijgegeven voor levering
          ( @SoortFact <> 4 and OrkGoedgekeurd = 0 ))         //Niet goedgekeurd, behalve als het een proforma betreft (die mag altijd worden afgedrukt)
         and OrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); //Komt inderdaad nog niet in de niet-te-factureren lijst voor

  if @SoortFact = 3 then
    select first vofLevOokTarief, vofLevOokTekst into @vofLevOokTarief, @vofLevOokTekst from tabVasteGegevensOrdersFactureren;
  else
    set @vofLevOokTarief = 1;
    set @vofLevOokTekst  = 1;
  end if;

  //Orders zonder orderregels worden er hier uitgefilterd
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
  select @FbGid, OrkGid, (if @SoortFact in (0,1) then 9 else if @SoortFact = 3 then 10 else 22 endif endif) Reden, 1 from tmpTeFacturerenOrdersRange inner join tabOrderKop on OrkGid = tmpRangeOrkGid
  where tmpNietFactureren = 0
        and (not exists(select 1 from tabOrderRegel where OrrOrkGid = OrkGid) or
             not exists(select 1 from tabOrderRegel where OrrOrkGid = OrkGid and ((OrrRegelSoort = 2) or (OrrRegelSoort = 1 and @vofLevOokTarief = 1) or (OrrRegelSoort = 0 and @vofLevOokTekst = 1)))
            )
  	and not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);

  //Orders zonder verzendadres worden er hier uitgefilterd; 30: Order heeft geen verzendadres
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
  select @FbGid, OrkGid, 30, 1 from tmpTeFacturerenOrdersRange inner join tabOrderKop on OrkGid = tmpRangeOrkGid
  where tmpNietFactureren = 0
        and (OrkVerzendAdres in (2,5) and OrkAdrGid is null)
  	and not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);

  //Orders zonder verzendadres worden er hier uitgefilterd; 31: Order heeft geen eindbestemming
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
  select @FbGid, OrkGid, 31, 1 from tmpTeFacturerenOrdersRange inner join tabOrderKop on OrkGid = tmpRangeOrkGid
  where tmpNietFactureren = 0
        and (OrkEindAdres = 2 and OrkAdrGidEindAdres is null)
  	and not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);

  // RS 27-9-2017: Wanneer verkoopeenheden aantallen niet kloppen orderverwerking blokkeren
  // 28=Aantallen verkoop- en voorraadeenheden zijn onjuist
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
  select distinct @FbGid, OrkGid, 28, 1
  from tmpTeFacturerenOrdersRange inner join  vwControleer_OrderRegels_VerkEenh_VrrdEenh_WijkenAf on OrkGid = tmpRangeOrkGid
  where not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);

  //Vve 13-7-2005: Check toegevoegd, als geen nawopdracht voldoet (wegens EDI ja/nee/nooit) dan gaan we niet door.
  // Dus kijken we bij debiteurinstellingen: Als er geen records in tabNawDocument staan, maw er is nooit iets ingevuld (bij oude debiteuren) dan gaatie normaal via papier, dus dat is goed.
  // Maar als er records staan in tabNawDocument, en geen daarvan voldoet, dan zal er geen factuur uitkomen, dus geven we op voorhand code 23 terug.
  // ACW deze routine aangepast, zodat de 2x exists eruit is.
/*
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
  select @FbGid, OrkGid, 23, 1 from tmpTeFacturerenOrdersRange inner join tabOrderKop on OrkGid = tmpRangeOrkGid
  where   (exists(select 1 from tabNawDocument where OrkNawGid = NawDocNawGid and NawDocDocSoort = @LayoutSoort))
      and (not exists(select 1 from tabNawDocument where OrkNawgid = NawDocNawGid and NawDocDocSoort = @LayoutSoort and
                               ( (NawDocAfdrukVoorwaarde = 0) or //altijd
                                 (NawDocAfdrukVoorwaarde = 1 and OrkIsEdiOrder=0) or //niet bij edi, en deze order is geen edi
                                 (NawDocAfdrukVoorwaarde = 2 and OrkIsEdiOrder=1))))   //wel bij edi, en deze order ook edi.
  	  and not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);
*/
  //Vve 9-8-2005: Uitbreiding: Als het om facturen gaat (0 en 1) of proformanota (4) en er is een factuurdebiteur, dan
  // gaan we de documentinstellingen van de factuurdebiteur gebruiken.
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
  select @FbGid, OrkGid, 23, 1
  from   tmpTeFacturerenOrdersRange
         inner join tabOrderKop on OrkGid = tmpRangeOrkGid
  where  isnull((select max(if (NawDocAfdrukVoorwaarde = 0) or                               // altijd
                               (NawDocAfdrukVoorwaarde = 1 and binnenOrk.OrkIsEdiOrder=0) or // niet bij edi, en deze order is geen edi
                               (NawDocAfdrukVoorwaarde = 2 and binnenOrk.OrkIsEdiOrder=1)    // wel bij edi, en deze order ook edi.
                            then 1 /*wordt afgedrukt*/ else 0 /*wordt niet afgedrukt*/ endif
                           )
                 from   tabNawDocument, tabOrderKop binnenOrk
                 where   NawDocNawGid = if  ((@SoortFact in (0, 1, 4)) and OrkFactuurNawGid is not null) then OrkFactuurNawGid else OrkNawgid endif
                       and binnenOrk.OrkGid = tmpRangeOrkGid
                       and NawDocDocSoort = @LayoutSoort
                       and (NawDocRegelSoort <> 0 or @NoPaperPrints = 0) // Papieren prints onderdrukken , default uit
                ), 1 // geen doc.instellingen, dus wel afdrukken
               ) = 0 // Als resultaat = 1 (afdrukken), dan NIET in deze NietTeFactureren tabel opnemen
   	   and not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);

  //UBL
  if @SoortFact in (0,1) then  // Factuur Batch Direct
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @FbGid, OrkGid, 29, 1
    from   tmpTeFacturerenOrdersRange
           inner join tabOrderKop on OrkGid = tmpRangeOrkGid
    where  exists (select 1
                   from   tabOrderKop binnenOrk
                   left outer join tabNawDocument on IsNull(OrkFactuurNawGid, OrkNawgid) = NawDocNawGid and NawDocDocSoort = @LayoutSoort
                   left outer join tabRapDocFormat on RdfGid = NawDocRdfGid
                   where binnenOrk.OrkGid = tmpRangeOrkGid
                     and (
                           (NawDocAfdrukVoorwaarde = 0) or                               // altijd
                           (NawDocAfdrukVoorwaarde = 1 and binnenOrk.OrkIsEdiOrder=0) or // niet bij edi, en deze order is geen edi
                           (NawDocAfdrukVoorwaarde = 2 and binnenOrk.OrkIsEdiOrder=1)    // wel bij edi, en deze order ook edi.
                          )
                     and (
                           IsNull(RdfUblAanmaken, 0) = 1 and (OrkInclBtw = 1)
                         )
                  )
         and not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);
  end if;

  //Verwijder alle toch-niet-te-factureren/leveren-orders (Let op: deze hier laten staan!)
  update tmpTeFacturerenOrdersRange set tmpNietFactureren = 1 where tmpRangeOrkGid in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @FbGid);

  // Orders zijn gelocked, voor de licenties zonder specregels controleren of de regels in de orders die we gaan leveren wel een correcte locatieregel hebben en zonodig corrigeren
  if ((@SoortFact = 3) or (@SoortFact in (0,1) and @LeverenBijFactureren = 1)) and (IsOrderSpecificatieregelActief() = 0) then
    open cursor_Orders_TeFactureren;
    OrderLoop:
    loop
      Fetch next cursor_Orders_TeFactureren into @OrkGid;
      if sqlstate = '02000' then
        leave OrderLoop;
      end if;
      call CheckFixSpecregelLicentieZonderSpecregels(@OrkGid);
    end loop OrderLoop;
    close cursor_Orders_TeFactureren;
  end if;

  // Orders waarvoor van artikelregels het aantal DezeLevering niet overeenkomt met het totaal DezeLevering van de verzamellijst-regels als niet-te-leveren markeren
  if  @SoortFact = 3 or                                // Levering
     (@SoortFact = 0 and @LeverenBijFactureren = 1)   // OF leveren tijdens factureren
  then
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe  )
    select @fbGid, OrkGid, 18, 1  // Aantal Deze levering is ongelijk aan het totaal van Deze Levering op de verzamellijst
    from   tmpTeFacturerenOrdersRange inner join tabOrderKop on (OrkGid = tmpRangeOrkGid)
    where  tmpNietFactureren = 0 and
           exists(select first 1                                   // EN aantal DezeLevering komt niet overeen met totaal van locatieregels
                  from   tabOrderRegel
                         inner join tabVerkoopEenheid on VkeArtGid = OrrArtGid and VkeGid = OrrVkeGid
                  where  OrrRegelsoort = 2 and
                         OrrOrkGid = OrkGid and
                         // ACW Defect 58843: Vrijgeven afhankelijk van verkoopeenheid (afwijking bij leveren/factureren, dan testen op aantallen verkoopeenheden, anders op aantallen voorraadeenheden)
                         //OrrAantalLeveringVrrdEenh <> isnull(OrrAantalTotaalLevVanDetail,0)
                         if VkeAantalKanVerschillen = 2 /*Verschillen bij lev/fact*/ then
                           // Aantal mag afwijken bij leveren of factureren? Dan moet sum(spec.AantalInVerkEenh) gelijk zijn aan regel.DezeLevInVerkEenh
                           if (OrrAantalTotaalLevVanDetail <> OrrAantalLeveringVrrdEenh) /*defect 58843: Verkoopeenheid mag hier niet afwijken, voorr.eenheden evt. wel, dus controleren we beide aantallen*/
                              or (select sum(OrlDezeLevering) from tabOrderRegelLocatie where OrlOrrGid = OrrGid) <> OrrAantalLevering then 1 else 0 endif
                         else
                           // Aantal mag niet afwijken of alleen bij besteld? Dan moet sum(spec.AantalInVoorrEenh) gelijk zijn aan regel.DezeLevInVoorrEenh
                           if OrrAantalTotaalLevVanDetail <> OrrAantalLeveringVrrdEenh then 1 else 0 endif
                         endif <> 0
                 )
           and OrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); //Komt inderdaad nog niet in de niet-te-factureren lijst voor
  end if;

  //Vve 9-8-2005: Extra check: Als je bij VGOrders hebt ingesteld datie bij BatchFacturering (0) gelijk moet leveren (3) EN pakbon afdrukken noodzakelijk is,
  //              dan controleren we of er bij de debiteur wel iets is ingesteld vwb pakbon.
  if @SoortFact = 0 and @LeverenBijFactureren = 1 and @PakbonAfdrukkenBijLeveren = 1 then
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @FbGid, OrkGid, 23, 1
    from   tmpTeFacturerenOrdersRange
           inner join tabOrderKop on OrkGid = tmpRangeOrkGid
    where  isnull((select max(if (NawDocAfdrukVoorwaarde = 0) or                               // altijd
                                 (NawDocAfdrukVoorwaarde = 1 and binnenOrk.OrkIsEdiOrder=0) or // niet bij edi, en deze order is geen edi
                                 (NawDocAfdrukVoorwaarde = 2 and binnenOrk.OrkIsEdiOrder=1)    // wel bij edi, en deze order ook edi.
                              then 1 /*wordt afgedrukt*/ else 0 /*wordt niet afgedrukt*/ endif
                             )
                   from   tabNawDocument, tabOrderKop binnenOrk
                   where     (OrkNawgid = NawDocNawGid) and binnenOrk.OrkGid = tmpRangeOrkGid
                         and (NawDocDocSoort = 30)
                  ), 1 // geen doc.instellingen, dus wel afdrukken
                 ) = 0 // Als resultaat = 1 (afdrukken), dan NIET in deze NietTeFactureren tabel opnemen
         and not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);
  end if;

  if @SoortFact = 3 then
    if (@IndienGeenBackorders = 1) then
      //MR 05-aug-2010 bug #32648: Als aangevinkt, orders met backorders eruithalen
      insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
      select @FbGid, OrkGid, 27, 1
      from tmpTeFacturerenOrdersRange
      inner join tabOrderKop on OrkGid = tmpRangeOrkGid
      where (0 <> (select isnull(sum(OrrAantalBackorder),0) from taborderregel where OrrOrkGid = OrkGid))
      and not exists(select 1 from tabFactuurNietGefactureerd where fngFbGid = @FbGid and fngOrkGid = OrkGid);
    end if;

    //Orders na de leverdatum
    /* Hoeft niet in de tabel van niet-geleverde orders te staan!
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe  )
    select @fbGid, OrkGid, 11, 1  //Leverdatum van de order ligt na de opgegeven leverdatum
    from   tmpTeFacturerenOrdersRange inner join tabOrderKop on (OrkGid = tmpRangeOrkGid) inner join tabNaw on (OrkNawGid = NawGid) key join tabNawFile
    where  OrkLeverDatum > @TotLeverDatum;
    delete from tmpTeFacturerenOrdersRange where tmpRangeOrkGid in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @FbGid);
    */
    update tmpTeFacturerenOrdersRange set tmpNietFactureren = 1 where tmpRangeOrkGid in (select OrkGid from tmpTeFacturerenOrdersRange inner join tabOrderkop on (OrkGid = tmpRangeOrkGid) where OrkLeverDatum > @TotLeverDatum);
  end if;


  //De niet-te-factureren/leveren orders unlocken
  open cursor_Orders_NietFactureren;
  OrderLoop:
  loop
    Fetch next cursor_Orders_NietFactureren into @OrkGid, @PfvkGid;
    if sqlstate = '02000' then
      leave OrderLoop;
    end if;

    //Probeer de order te locken; indien gelukt, dan opnemen, anders overslaan
    if @orkgid <> @UseLockedOrkGid then
      //Order niet vanui de order factureren/leveren, dus lock verwijderen
      call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid);
      if @SoortFact = 5 then  // ProjectFactuur
        call LockReleaseOnId(@ConnId, @@LoginTime, 1, 'tabProjectFactuurVoorstelKop', @PfvkGid);
      end if;
    end if;

  end loop OrderLoop;
  close cursor_Orders_NietFactureren;

  // Als we factureren met leveren (tegelijkertijd), dan de orders eruit waarvan 'aantal deze factuur' <> 'aantal deze levering'
  if @SoortFact = 0 then // Batch-factureren
    if @LeverenBijFactureren = 1 then
      insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe  )
      select      @fbGid, tmpRangeOrkGid, 17, 1  //Aantallen (deze factuur / deze levering) ongelijk
      from        tmpTeFacturerenOrdersRange
      where       exists( select 1 from tabOrderRegel where OrrOrkGid = tmpRangeOrkGid and OrrRegelsoort = 2 and ((OrrAantalDezeFacturering <> OrrAantalLevering) or (OrrAantalDezeFactureringVrrdEenh <> OrrAantalLeveringVrrdEenh)))
                  and tmpRangeOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); //Komt inderdaad nog niet in de niet-te-factureren lijst voor
                  // Dus als er regels bestaan waarvan de aantallen ongelijk zijn en het zijn tarief- of artikelregels
    end if;
  end if;

  //Volgorde van de orders bepalen en in de 'definitieve tabel' plaatsen
  insert into tabTeFacturerenOrders( tfoTeFactVolgOrder, tfoTeFactOrkGid, tfoOrderTotaal, tfoTeFactOrdNummer, tfoSessieFbGid )
  select   number(), OrkGid, OrkTotaalInclBtw, OrkNummer, @FbGid
  from     tmpTeFacturerenOrdersRange inner join tabOrderKop on (OrkGid = tmpRangeOrkGid) inner join tabNaw on (OrkNawGid = NawGid) inner join tabNawFile on (NawFilNawGid = NawGid and NawFilFonID='D')
  where    tmpNietFactureren = 0 and not exists(select 1 from tabTeFacturerenOrders where tfoTeFactOrkGid = OrkGid and tfoSessieFbGid = @FbGid)
  order by if @Ascending = 0 then if @SorteerOp = 0 then NawFilNummer else NawFilZoekCode endif else '' endif desc,
           if @Ascending = 1 then if @SorteerOp = 0 then NawFilNummer else NawFilZoekCode endif else '' endif,
           NawFilNummer, OrkApartFaktureren, OrkVerzendAdres, OrkBtcNummer, OrkNummer;

  set @@ErrorTextProcedure = 'Einde FacturerenBepaalRangeVanOrders';
  //call Trace(@@ErrorTextProcedure);
end;


//$Workfile: FacturerenBepaalVerzamelDocumenten.sp $ $Revision: 6 $ $Modtime: 8-10-09 14:57 $
create or replace procedure FacturerenBepaalVerzamelDocumenten(in @layoutsoort integer, in @fbGid integer)
begin
  declare @VolgOrder            integer;
  declare @VorigeVolgOrder      integer;
  declare @FactNr               integer; // Dit is GEEN factuurnummer, maar het nummer van de verzameling orders dat uiteindelijk in 1 factuur terecht zal komen
  declare @OrkNawGid            integer;
  declare @OrkApartFactureren   smallint;
  declare @OrkApartLeveren      smallint;
  declare @OrkVerzendadres      smallint;
  declare @VerzendAdresNummer   integer;
  declare @OrkFactuurAdres      smallint;
  declare @ValNummer            integer;
  declare @BtcNummer            integer;
  declare @OrkInclBtw           smallint;
  declare @OrdRelRelGid         integer;
  declare @FactNawGid           integer;
  declare @OrkIncNawRekGid 	    integer;
  declare @OrkIsEDIorder        smallint;
  declare @LeverenBijFact       smallint;
  declare @OrkIsAbcLevering     smallint;
  declare @OrkVrvGid					  integer;
  declare @LvcNummer            integer;
  declare @PakbonBatchFact      integer;
  declare @VerzOrderNawGid      integer;

  //call TraceBegin('FacturerenBepaalVerzamelDocumenten > @LayoutSoort = ' + string(@LayoutSoort));

  //ACW 05-07-2001: Let op: deze routine wordt uitgebreid als we ook andere documenten evt. samengevoegd kunnen afdrukken!
  if @LayoutSoort in (30,50,60) then
    //call Trace('Bepaal verzameling van facturen');
    //Factuur
    //LET OP! Deze routine NIET via een cursor doen omdat elke keer opnieuw de eerste niet-gevulde record moet worden bepaald
    set @FactNr = 0;
    set @LeverenBijFact = (select vofLeverenBijFactureren from tabVasteGegevensOrdersFactureren);
    set @PakbonBatchFact = (select vofPakbonBijFactureren from tabVasteGegevensOrdersFactureren);

    LoopBepaalVerzamel:
    Loop
      set @OrkNawGid = null;
      select first tfoTeFactVolgOrder, OrkNawGid,  OrkApartFaktureren,  OrkApartLeveren,  OrkVerzendadres,  OrkAdrGid,           OrkFactuurAdres,  OrkValNummer, OrkBtcNummer, OrkInclBtw,  OrdRelRelGid,  OrkFactuurNawGid, OrkIncNawRekGid,  OrkIsEDIorder, OrkIsAbcLevering,   OrkVrvGid, OrkLvcNummer
      into         @VolgOrder,         @OrkNawGid, @OrkApartFactureren, @OrkApartLeveren, @OrkVerzendadres, @VerzendAdresNummer, @OrkFactuurAdres, @ValNummer,   @BtcNummer,   @OrkInclBtw, @OrdRelRelGid, @FactNawGid,      @OrkIncNawRekGid, @OrkIsEDIorder, @OrkIsAbcLevering, @OrkVrvGid, @LvcNummer
      from         tabTeFacturerenOrders, tabOrderKop inner join tabNaw on (OrkNawGid = NawGid) left outer join tabOrderRelatieVoorDocument on (OrdRelOrkGid=OrkGid and OrdRelDocSoort=@layoutsoort)
      where        tfoFactNr is null and OrkGid = tfoTeFactOrkGid and tfoSessieFbGid = @FbGid
      order by     TfoTeFactOrdNummer;   //**RB**
      if @OrkNawGid is null then
        leave LoopBepaalVerzamel;
      end if;

      //Factuurverzamelingsnummer verhogen
      set @FactNr = @FactNr + 1;
      set @VerzOrderNawGid = (if @FactNawGid is null then @OrkNawGid else @FactNawGid endif);
      //In elk geval de gevonden order het verzamelingsnummer geven
      update tabTeFacturerenOrders set tfoFactNr = @FactNr where tfoTeFactVolgOrder = @VolgOrder and tfoSessieFbGid = @FbGid;
      //call Trace('@OrkApartFactureren='+string(@OrkApartFactureren)+', @OrkNawGid='+string(@OrkNawGid)+ ', @FactNawGid='+string(@FactNawGid));

      // F A C T U U R

      if (@LayoutSoort in (50,60)) and (@OrkApartFactureren <> 0 /*Ja*/) then
        //Alle overige orders 'van hetzelfde soort' het nummer geven; orders met andere factuurdeb. altijd apart!
        update tabTeFacturerenOrders
        set    tfoFactNr = @FactNr
        where  tfoSessieFbGid = @FbGid and
        	tfoTeFactVolgOrder in
               (select tfoTeFactVolgOrder from tabTeFacturerenOrders inner join tabOrderKop on (OrkGid = tfoTeFactOrkGid) inner join tabNaw on ((if OrkFactuurNawGid is null then OrkNawGid else OrkFactuurNawGid endif) = NawGid)
                inner join tabNawFile on (NawFilNawGid = NawGid and NawFilFonID='D') left outer join tabOrderRelatieVoorDocument on (OrdRelOrkGid=OrkGid and OrdRelDocSoort=@layoutsoort)
                left outer join (tabNawDocument inner join tabRapDocFormat on RdfGid = NawDocRdfGid) on IsNull(OrkFactuurNawGid, OrkNawgid) = NawDocNawGid and NawDocDocSoort = @LayoutSoort and
								((NawDocAfdrukVoorwaarde = 0) or (NawDocAfdrukVoorwaarde = 1 and OrkIsEdiOrder=0) or (NawDocAfdrukVoorwaarde = 2 and OrkIsEdiOrder=1)) and RdfUblAanmaken = 1

                where  ( // Controle op factuurdebiteur en, bij afdrukken pakbon, ook orderdebiteur
                           (isnull(OrkFactuurNawGid, OrkNawGid ) = @VerzOrderNawGid)                      // wel of Niet leveren, in ieder geval moet de NAW waar de factuur naartoe gaat gelijk zijn
                        or (@LeverenBijFact <> 0 and OrkNawGid = @VerzOrderNawGid)                        // Wel leveren, dan moet ook de ordernaw gelijk zijn
                       )
                       and (tfoSessieFbGid = @FbGid)                                                      // Alleen de orders van deze zelfde sessie bekijken
                       and (tfoFactNr is null)                                                            // Alleen als de order nog niet in een eerdere reeks is opgenomen
                       and (   (@LeverenBijFact = 0)                                                      // Niet leveren bij factureren, dan niks van leveren controleren
                            or (@LayoutSoort = 50 /*BatchFact*/ and @PakbonBatchFact = 0)                 // Als de pakbon niet wordt afgedukt bij batchfactureren, dan hoeven we verder geen adres te controleren
                            or (isnull(OrkFactuurNawGid, @FactNawGid - 1, 0) = isnull(@FactNawGid,0)      // Als er een FactDeb is, dan moet die gelijk zijn aan de andere orders
                                //and (@OrkApartLeveren <> 0)                                             // Als deze order apart leveren, dan niet conbineren met andere orders
                                and (OrkVerzendAdres = @OrkVerzendAdres)                                  // Verzendadressoort moet gelijk zijn
                                and (   (@OrkVerzendAdres not in (2 /*VerzAdr*/, 5 /*FactDeb-VerzAdr*/))  // Verzendadres is GEEN apart nummer
                                     or (isnull(@VerzendAdresNummer,-1) = isnull(OrkAdrGid,-1))           // OF juist wel, maar dan moet het adresnummer ook gelijk zijn
                                    )
                               )
                           )
                       and (@LeverenBijFact = 0 or isnull(OrkVrvGid,0) = isNull(@OrkVrvGid,0))            // indien leveren bij fact, dan ook zelfde vervoerder
                       and (OrkFactuurAdres = @OrkFactuurAdres)                             // zelfde factuuradres
                       and (OrkApartFaktureren = @OrkApartFactureren)                       // Alleen als gelijke soort 'apart factureren per'
                       and (   (OrkApartFaktureren = 1 /*Nee*/)                                        // niet apart factureren
                            or (OrkApartFaktureren = 2 /*Per Contactpers*/     and isnull(@OrdRelRelGid,-1) = isnull(OrdRelRelGid,-1))  //Per contactpersoon
                            or (OrkApartFaktureren = 3 /*Per Verzendadr*/      and @OrkVerzendadres = OrkVerzendadres and ((OrkVerzendadres in (0,1,2) and OrkNawGid = @OrkNawGid) or ((OrkVerzendadres in (3,4,5) and OrkFactuurNawGid = @FactNawGid))) and isnull(@VerzendAdresNummer,-1) = isnull(OrkAdrGid,-1))
                            or (OrkApartFaktureren = 4 /*Per contact+verzadr*/ and @OrkVerzendadres = OrkVerzendadres and ((OrkVerzendadres in (0,1,2) and OrkNawGid = @OrkNawGid) or ((OrkVerzendadres in (3,4,5) and OrkFactuurNawGid = @FactNawGid))) and isnull(@VerzendAdresNummer,-1) = isnull(OrkAdrGid,-1) and isnull(@OrdRelRelGid,-1) = isnull(OrdRelRelGid,-1))
                           )
                       and (OrkValNummer = @ValNummer)                                 // zelfde valuta
                       and (isnull(OrkBtcNummer,-1) = isnull(@BtcNummer,-1))           // zelfde bet.conditie
                       and (OrkInclBtw = @OrkInclBtw)                                  // zelfde 'type' btw
                       and (OrkIsEDIorder = @OrkIsEDIorder)                            // zelfde 'type' EDI-order (wel of niet)
                       and (OrkIsAbcLevering = @OrkIsAbcLevering)                      // zelfde 'type' ABC-levering (wel of niet)
                       and (   (IsModuleActive('n2') = 0)                              // Geen incassomodule, dan die gegevens ook niet controleren
                            or (OrkIncNawRekGid is null and @OrkIncNawRekGid is null) // Beiden geen incassobankrekening
                            or (OrkIncNawRekGid = @OrkIncNawRekGid)                   // Beiden Dezelfde incassorekening
                           )
                       and (IsNull(RdfUblAanmaken, 0) = 0)        										// UBL - Nooit verzamelen
               );
      end if;

      // L E V E R I N G
      if (@LayoutSoort = 30) and (@OrkApartLeveren <> 0 /*Ja*/) then
        //Alle overige orders 'van hetzelfde soort' het nummer geven; orders met andere factuurdeb. altijd apart!
        update tabTeFacturerenOrders
        set    tfoFactNr = @FactNr
        where  tfoSessieFbGid = @FbGid and
        	tfoTeFactVolgOrder in
               (select tfoTeFactVolgOrder from tabTeFacturerenOrders inner join tabOrderKop on (OrkGid = tfoTeFactOrkGid) inner join tabNaw on ((if OrkFactuurNawGid is null then OrkNawGid else OrkFactuurNawGid endif) = NawGid) inner join tabNawFile on (NawFilNawGid = NawGid and NawFilFonID='D') left outer join tabOrderRelatieVoorDocument on (OrdRelOrkGid=OrkGid and OrdRelDocSoort=@layoutsoort)
                where  (if OrkFactuurNawGid is null then OrkNawGid else OrkFactuurNawGid endif) = @VerzOrderNawGid and                                         // zelfde debiteur
                       tfoSessieFbGid = @FbGid and
                       (isnull(OrkFactuurNawGid,@FactNawGid - 1, 0) = isnull(@FactNawGid,0) and OrkNawGid = @OrkNawGid and OrkVerzendAdres = @OrkVerzendAdres and ((not OrkVerzendAdres in (2,5)) or isnull(@VerzendAdresNummer,-1) = isnull(OrkAdrGid,-1))) and
                       isnull(OrkVrvGid,0) = isNull(@OrkVrvGid,0) and	          // zelfde vervoerder
                       OrkFactuurAdres = @OrkFactuurAdres and                   // zelfde factuuradres
                       OrkApartFaktureren = @OrkApartFactureren and             // Alleen als gelijke soort 'apart factureren per'
                       (OrkApartLeveren = @OrkApartLeveren) and                 // Alleen als gelijke soort 'apart leveren per'
                       OrkValNummer = @ValNummer and                            // zelfde valuta
                       isnull(OrkLvcNummer,-1) = isnull(@LvcNummer,-1) and      // zelfde lev.conditie
                       OrkInclBtw = @OrkInclBtw and                             // zelfde 'type' btw
                       OrkIsEDIorder = @OrkIsEDIorder and                       // zelfde 'type' EDI-order (wel of niet)
                       tfoFactNr is null);
      end if;

    end loop LoopBepaalVerzamel;
  end if;

  //call TraceEind('FacturerenBepaalVerzamelDocumenten');

end;


create or replace procedure FacturerenBerekenGegevens(in @FactuurGid integer, in @LayoutSoort integer, in @BedragBetaald numeric(15,2), in  @VerschilAfboeken   smallint)
begin
  declare @frefGid                     integer;
  declare @fkIsInclBtw                 smallint;
  declare @KredBepPerc                 numeric(6,2);
  declare @KredBepRksInvoer            nchar(28);
  declare @KredBepBasisInBtw           numeric(15,2);
  declare @KredBepBasisExBtw           numeric(15,2);

  //tbv. BTW-regels
  declare @BtwCode                     integer;
  declare @VorigBtwCode                integer;
  declare @BtwPerc                     numeric(6,2);
  declare @BtwVerlegd                  smallint;
  //BTW-berekeningen
  declare @BtwBasisRegels              numeric(15,2);
  declare @BedragInclBtwRegels         numeric(15,2);
  declare @BtwBasisExtra               numeric(15,2);
  declare @TotaalInclBtwExtraZonder    numeric(15,2);
  declare @BedragInclBtwExtra          numeric(15,2);
  declare @BtwBedragExtraZonder        numeric(15,2);
  //Totaal van extra-regels zonder BTW-%
  declare @TotaalBtwBasisExtraZonder   numeric(15,2);
  declare @fkBtcSoort                  smallint;
  //tbv. correctie afrondingen van factuurtotaal
  declare @fbrGid                      integer;
  declare @fbrBtwPercentage						 numeric(6,2);
  declare @TotaalVolgensRegels         numeric(15,2);
  declare @TotaalVolgensBtw            numeric(15,2);
  declare @TotaalVolgensExtra          numeric(15,2);
  declare @KredBepVolgensBTW           numeric(15,2);
  declare @KredBepVolgensRegels        numeric(15,2);
  declare @KredBepKortingInclBtw       smallint;
  declare @BtwBasisZonderKredBep       numeric(15,2);

  declare @AantDeciBasis                integer;
  declare @AantDeciValuta               integer;

  set @@ErrorTextProcedure = 'FacturerenBerekenGegevens( @FactuurGid='+string(@FactuurGid)+', @LayoutSoort='+string(@LayoutSoort)+', @BedragBetaald='+string(@BedragBetaald)+', @VerschilAfboeken='+string(@VerschilAfboeken);

  //call Tracebegin(@@ErrorTextProcedure);

  select fkIsInclBtw, fkBtcSoort into @fkIsInclBtw, @fkBtcSoort from tabFactuurKop where fkGid = @FactuurGid;

//  select DecimalenRegel * 2 into @AantDeciBasis  from tabValuta where ValNummer = @@BasisValutaNummer;
  select DecimalenRegel * 2 into @AantDeciValuta from tabValuta where ValNummer = (select fkValNummer from tabFactuurKop where FkGid = @FactuurGid);

  //Bepaal van deze factuur eerst de betalingsconditie.
  //Kredietbeperking : verhoog de BTW-basis met de kredietbeperking (let op: als order incl.BTW, dan kred.bep.=incl.btw, anders kred.bep.=excl.btw)
  //Betalingskorting : niets doen
  //Overigen         : niets doen
  select Percentage, RksInvoer, BtcKredBepKortingInclBtw into @KredBepPerc, @KredBepRksInvoer, @KredBepKortingInclBtw /* alleen voor korting */
  from   tabBetalingsconditie
         inner join tabRekeningschema on RksGid = btcRksGid
         inner join tabFactuurKop on fkBtcNummer = BtcNummer
  where  fkGid = @FactuurGid and SoortFactuurBtc in (1,2);
  set @KredBepPerc = isnull( @KredBepPerc, 0 );


  // *** BTW-regels ***
  //Alle BTWs in ofwel orderregels, ofwel extra regels gebruiken
  //LET OP: de BTW van de extra regels worden over alle regels in de factuur berekend. De kortingsregels echter alleen over de betreffende referentie!!!
  //We moeten dus de totale BTW berekenen rekening houdend met de verdeling per orderreferentie.
  //Deze routine is deels gepikt van OrderBerekenBtwTotalen (alleen nu obv. deze factuur ipv. obv. opgegeven order)

  //call Trace('Alle BTWs doorlopen voor de BTW-regels');
  set @VorigBtwCode = -1;
  set @KredBepBasisInBtw = 0;
  set @KredBepBasisExBtw = 0;
  set @BtwBasisZonderKredBep = 0;
  loopBtw:
  Loop
    set @BtwCode = null;
    select first BtwCode, BtwPercentage, BtwVerlegd into @BtwCode, @BtwPerc, @BtwVerlegd from tabBtw where BtwCode > @VorigBtwCode and BtwCode in (select frBtwCode from tabFactuurRegel inner join tabFactuurReferentie on (FrefGid = frFrefGid) where frefFkGid = @FactuurGid ) or BtwCode in (select ferBtwCode from tabFactuurExtraRegel inner join tabFactuurReferentie on (frefGid = ferFrefGid) where frefFkGid = @FactuurGid ) order by BtwCode;
    if @BtwCode is null then
      leave loopBtw;
    end if;
    set @VorigBtwCode = @BtwCode;

    set @BedragInclBtwRegels = 0;
    set @BtwBasisRegels = 0;
    select sum(round(if @fkIsInclBtw =  0 then cast( frRegelTotaal * (100+@BtwPerc)/100 as numeric(15,2)) else frRegelTotaal endif, @AantDeciValuta)),
           sum(round(if @fkIsInclBtw <> 0 then cast( frRegelTotaal / (100+@BtwPerc)*100 as numeric(15,2)) else frRegelTotaal endif, @AantDeciValuta))
    into   @BedragInclBtwRegels, @BtwBasisRegels
    from   tabFactuurRegel inner join tabFactuurReferentie on (FrefGid = FrFrefGid)
    where  frBtwCode = @BtwCode and frefFkGid = @FactuurGid and frSoortRegel <> 0; //Geen tekstregels want die hebben geen regeltotaal!


    //call Trace('De ''extra'' regels');
    set @BedragInclBtwExtra = 0;
    set @BtwBasisExtra = 0;
    select sum(ferBtwBedrag+ferBtwBasis), sum( ferBtwBasis )
    into   @BedragInclBtwExtra, @BtwBasisExtra
    from   tabFactuurExtraRegel inner join tabFactuurReferentie on (FrefGid = ferFrefGid)
    where frefFkGid = @FactuurGid  and ferBtwCode = @BtwCode;

    //call Trace('De extra regels zonder BTW uitrekenen');
    call FactuurBerekenExtraBedragenZonderBtw( @FactuurGid, @fkIsInclBtw, @BtwCode, @BtwPerc, @TotaalBtwBasisExtraZonder, @TotaalInclBtwExtraZonder);

    //Bepaal het bedrag van de kredietbeperking
    set @KredBepBasisExBtw = isnull(@KredBepBasisExBtw,0) + isnull( @BtwBasisRegels, 0 ) + isnull( @BtwBasisExtra, 0 ) + isnull( @TotaalBtwBasisExtraZonder, 0 );
    set @KredBepBasisInBtw = isnull(@KredBepBasisInBtw,0) + isnull(@BedragInclBtwRegels,0) + isnull(@BedragInclBtwExtra,0) + isnull( @TotaalInclBtwExtraZonder, 0 );

    //Nu de BTW in BTW-regels van de factuur schrijven (incl. kredietbeperking indien nodig (dus NIET de betalingskorting!!))
    set @BtwBasisZonderKredBep = @BtwBasisZonderKredBep + isnull( @BtwBasisRegels, 0 ) + isnull( @BtwBasisExtra, 0 ) + isnull( @TotaalBtwBasisExtraZonder, 0 );

    if @fkIsInclBtw = 0 then
      set @BtwBasisRegels = ( isnull( @BtwBasisRegels, 0 ) + isnull( @BtwBasisExtra, 0 ) + isnull( @TotaalBtwBasisExtraZonder, 0 ) ); // * (if @fkBtcSoort=1 then (100+@KredBepPerc)/100 else 1 endif);
      set @BedragInclBtwRegels = round(@BtwBasisRegels * (100+@BtwPerc)/100, @AantDeciValuta);
    else
      set @BedragInclBtwRegels = (isnull(@BedragInclBtwRegels,0) + isnull(@BedragInclBtwExtra,0) + isnull(@TotaalInclBtwExtraZonder,0)); // * (if @fkBtcSoort=1 then (100+@KredBepPerc)/100 else 1 endif);
      set @BtwBasisRegels = round(@BedragInclBtwRegels / (100+@BtwPerc) * 100, @AantDeciValuta);
    end if;
    insert into tabFactuurBtwRegel( fbrBtwCode, fbrFkGid, fbrBtwPercentage, fbrBtwBasis, fbrBtwBedrag, fbrBtwVerlegd )
      values(@BtwCode, @FactuurGid, @BtwPerc, @BtwBasisRegels,  @BedragInclBtwRegels - @BtwBasisRegels, @BtwVerlegd );
  end loop loopBtw;

  //call Trace('Totalen volgens regels bepalen tbv. berekeningen op afrondingen');
  set    @TotaalVolgensRegels = 0;
  select sum( frRegelTotaal )
  into   @TotaalVolgensRegels
  from   tabFactuurRegel      inner join tabfactuurreferentie on (frefGid = FrFrefGid) where FrefFkGid = @FactuurGid;

  set    @TotaalVolgensExtra=0;
  select sum( if ferSoortRegel=0 then -1 else 1 endif * ferRegelTotaal )
  into   @TotaalVolgensExtra
  from   tabFactuurExtraRegel inner join tabfactuurreferentie on (frefGid = ferFrefGid and frefFkGid = @FactuurGid);

  set    @TotaalVolgensRegels = (isnull(@TotaalVolgensRegels,0) + isnull(@TotaalVolgensExtra,0)); //HIERO * (if @fkBtcSoort=1 then (100+@KredBepPerc)/100 else 1 endif);

  //call Trace('Als er een verschil bestaat tussen (totaal regels minus extra regels) en totaal btw-basis, dan dat verschil op de hoogste btw wegboeken');
  set @TotaalVolgensBtw=0;
  select sum(if @fkIsInclBtw = 0 then fbrBtwBasis else fbrBtwBasis+fbrBtwBedrag endif) into @TotaalVolgensBtw from tabfactuurbtwregel where fbrFkGid = @factuurGid;
  if @TotaalVolgensBtw<>@TotaalVolgensRegels then
    //Er is dus een verschil! -> BTW aanpassen
    select first fbrGid, fbrBtwPercentage into @fbrGid, @fbrBtwPercentage from tabFactuurBtwRegel where fbrFkGid = @factuurGid order by abs(fbrBtwBedrag) desc;
    //call Trace('@FkGid='+string(@FactuurGid)+'; @TotaalVolgensBtw='+string(@TotaalVolgensBtw)+'; @TotaalVolgensRegels='+string(@TotaalVolgensRegels));

    update tabFactuurBtwRegel
    set    fbrBtwBedrag = if @fkIsInclBtw = 0 then round((fbrBtwBasis + @TotaalVolgensRegels - @TotaalVolgensBtw) / 100 * @fbrBtwPercentage, @AantDeciValuta) else fbrBtwBedrag + @TotaalVolgensRegels - @TotaalVolgensBtw endif,
           fbrBtwBasis  = if @fkIsInclBtw = 0 then fbrBtwBasis + @TotaalVolgensRegels - @TotaalVolgensBtw else fbrBtwBasis endif
    where  fbrGid = @fbrGid;
  end if;


  //call Trace('Kredietbeperking volgens regels en volgens btw bepalen en (evt.) corrigeren');
  if @KredBepPerc is not null and @fkBtcSoort = 1 then
    //Afronding in kredietbeperking wegwerken (<kred.%>*<fact.bedrag excl.kred.bep.>-<kred.bep.per btw>)
    if @fkIsInclBtw = 0 then
      update tabFactuurBtwRegel
      set    fbrBtwBasis =  round((fbrBtwBasis *(100+@KredBepPerc)/100),@AantDeciValuta),
             fbrBtwBedrag = round((fbrBtwBasis *(100+@KredBepPerc)/100) *fbrBtwPercentage / 100,@AantDeciValuta)
      where  fbrFkGid = @FactuurGid;
    else
      update tabFactuurBtwRegel
      set    fbrBtwBasis =  round(round((fbrBtwBedrag + fbrBtwBasis) * (100+@KredBepPerc)/100,@AantDeciValuta) / (100+fbrBtwPercentage) * 100, @AantDeciValuta),
             fbrBtwBedrag = round(round((fbrBtwBedrag + fbrBtwBasis) * (100+@KredBepPerc)/100,@AantDeciValuta) / (100+fbrBtwPercentage) * fbrBtwPercentage, @AantDeciValuta)
      where  fbrFkGid = @FactuurGid;
    end if;
  end if;


  //call Trace('Bepaal het totaal volgens de regels en indien onjuist, dan factuurtotaal en btw aanpassen');
  if @KredBepPerc is not null and @fkBtcSoort = 1 then
    //KredietBeperking
    set @TotaalVolgensRegels = round(@TotaalVolgensRegels *(100+@KredBepPerc)/100,@AantDeciValuta);
  end if;
  //call Trace('Als er een verschil is tussen berekend factuurtotaal en volgens btw, dan het verschil bij de hoogste absolute BTW wegwerken');
  if @fkIsInclBtw = 1 then
    //Bepaal volgens BTW
    select sum( fbrBtwBasis + fbrBtwBedrag ) into @TotaalVolgensBtw from tabFactuurBtwRegel where fbrFkGid = @FactuurGid;
    if @TotaalVolgensRegels <> @TotaalVolgensBtw then
      //Bepaal hoogste BTW
      select first fbrGid into @fbrGid from tabFactuurBtwRegel where fbrFkGid = @FactuurGid order by abs(fbrBtwBedrag) desc, fbrBtwPercentage desc;
      update tabFactuurBtwRegel
      set    fbrBtwBasis = fbrBtwBasis + @TotaalVolgensRegels - @TotaalVolgensBtw
      where  fbrGid = @fbrGid;
    end if;
  else
    //call Trace('Bepaal volgens BTW');
    select sum( fbrBtwBasis) into @TotaalVolgensBtw from tabFactuurBtwRegel where fbrFkGid = @FactuurGid;
    if @TotaalVolgensRegels <> @TotaalVolgensBtw then
      //Bepaal hoogste BTW
      select first fbrGid into @fbrGid from tabFactuurBtwRegel where fbrFkGid = @FactuurGid order by abs(fbrBtwBedrag) desc, fbrBtwPercentage desc;
      update tabFactuurBtwRegel
      set    fbrBtwBasis = fbrBtwBasis + @TotaalVolgensRegels - @TotaalVolgensBtw
      where  fbrGid = @fbrGid;
    end if;
  end if;


  //call Trace('Factuurtotaal en betalingskonditie-gegevens');
  select sum( fbrBtwBasis ) into @BedragInclBtwRegels from tabFactuurBtwRegel where fbrFkGid = @FactuurGid;

  update tabFactuurKop
  set    fkSubTotExEmballage = isnull(( select sum( frRegelTotaal ) from tabFactuurRegel      inner join tabfactuurreferentie on (frefGid = frFrefGid ) where frefFkGid = @FactuurGid ),0) -
                               isnull(( select sum(ferRegelTotaal ) from tabFactuurExtraRegel inner join tabFactuurReferentie on (frefGid = ferFrefGid) where frefFkGid = @FactuurGid ),0),
         fkTotEmballage      = isnull(fkSubTotExEmballage,0),
         fkFactTotaalExBtw   = isnull(@BedragInclBtwRegels,0),
         fkFactTotInBtw      = isnull(( select sum( fbrBtwBasis + fbrBtwBedrag ) from tabFactuurBtwRegel where fbrFkGid = @FactuurGid ),0),
         fkBtcRksInvoer      = if @KredBepBasisExBtw <> 0 then @KredBepRksInvoer endif,
         fkBtcPerc           = @KredBepPerc,
         fkBtcBasis          = isnull(@KredBepBasisExBtw,0),
         fkBtcBedrag         = isnull(round(@KredBepBasisExBtw * @KredBepPerc/100, @AantDeciValuta),0),
         fkBtcBasisInBtw     = isnull(@KredBepBasisInBtw,0),
         fkBtcBedragInBtw    = isnull(round(@KredBepBasisInBtw * @KredBepPerc/100, @AantDeciValuta),0),
         //ACW 18-01-2001: als GEEN kred.bep. OF order is incl.BTW, dan incl. BTW-bedrag gebruiken, anders excl. BTW-bedrag gebruiken
         fkBtcOms            = LeesBtcExtraTekst(  fkBtcNummer, Nawtaalgid, fkValnummer, fkFactuurDatum, isnull(round(if (@fkBtcSoort <> 1 or @fkIsInclBtw = 1) and not (@fkBtcSoort = 2 and @KredBepKortingInclBtw = 0) then @KredBepBasisInBtw else @KredBepBasisExBtw endif * @KredBepPerc/100, @AantDeciValuta),0)),
         fkBtcTekstOpFactuur = LeesBtcFactuurTekst(fkBtcNummer, Nawtaalgid, fkValnummer, fkFactuurDatum, isnull(round(if (@fkBtcSoort <> 1 or @fkIsInclBtw = 1) and not (@fkBtcSoort = 2 and @KredBepKortingInclBtw = 0) then @KredBepBasisInBtw else @KredBepBasisExBtw endif * @KredBepPerc/100, @AantDeciValuta),0)),
         fkVervalDatum       = if isnull(@BedragInclBtwRegels,0) <0 then  //Creditnota?
                                 if isnull((select first vofIsCreditNotaDatumBtc from tabvastegegevensordersfactureren),0)=0 then  //Gebruik factuurdatum?
                                   fkFactuurDatum //Creditnota en ingesteld om dan fact.datum te gebruiken! dan vervaldatum=factuurdatum
                                 else
                                   fkVervalDatum //Creditnota conform bet.conditie
                                 endif
                               else
                                 fkVervalDatum //Geen creditnota
                               endif

  from   tabFactuurKop
         inner join tabNawFile   on (NawFilNummer = fkFactDebNummer)
         inner join tabFileOfNaw on (nawFilFonGid = FonGid and fonid='D')
         inner join tabNaw       on (NawGid = nawFilNawGid)
  where  fkGid = @FactuurGid;

  update tabFactuurKop
  set    fkBedragBetaald    = @BedragBetaald,
         fkBedragTeBetalen  = if @VerschilAfboeken = 0 then fkFactTotInBtw - @BedragBetaald else 0 endif,
         fkVerschilAfboeken = @VerschilAfboeken
  where fkGid = @FactuurGid and (@LayoutSoort in (50,60));



  if @fkBtcSoort = 2 then
    //call Trace('Factuur met betalingskorting, dus betalingskorting berekenen (ook obv. excl. btw?!?)');
    update tabFactuurKop
    set    fkBtcPerc           = @KredBepPerc,
           fkBtcBasis          = isnull(@KredBepBasisExBtw,0),
           fkBtcBedrag         = isnull(round(@KredBepBasisExBtw * @KredBepPerc/100, @AantDeciValuta),0),
           fkBtcBasisInBtw     = isnull(@KredBepBasisInBtw,0),
           fkBtcBedragInBtw    = isnull(round(@KredBepBasisInBtw * @KredBepPerc/100, @AantDeciValuta),0)
    where  fkGid = @FactuurGid;
  end if;

  //call TraceEind( 'FacturerenBerekenGegevens' )

end;


create or replace procedure FacturerenBerekenOpbrengst(in @fkGid integer, in @fkInclBtw integer, in @OpbrGrpGid integer, in @OpbrGrpNummer integer, in @KstpCode nchar(8), in @KstdCode nchar(8), in @RegelSoort integer, in @EersteActie integer, in @BtwCode integer, out @OpbrengstBedragBruto numeric(15,2), out @OpbrengstBedragNetto numeric(15,2), out @OpbrengstExtraBedragBruto numeric(15,2), out @OpbrengstExtraBedragNetto numeric(15,2), out @Kostprijs numeric(15,2), out @VoorraadPrijs numeric(15,2))
begin
  //@EersteActie: 0= maakt niet uit, 1=factureren, 2=leveren
  //MR 29-apr-2008 bug #27959: BtwCode word meegegeven voor de ict berekening
  declare @AantDecimalenFact  integer;
  declare @AantDecimalenBasis integer;
  set @@ErrorTextProcedure = 'FacturerenBerekenOpbrengst(@fkGid='+string(@fkGid)+', @fkInclBtw='+string(@fkInclBtw)+', @OpbrGrpGid='+string(@OpbrGrpGid)+', @OpbrGrpNummer='+string(@OpbrGrpNummer)+',@KstpCode='+string(@KstpCode)+',@KstdCode='+string(@KstdCode)+',@RegelSoort='+string(@RegelSoort)+', @EersteActie='+string(@EersteActie)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  //Opbrengst van de 'gewone' regels
  set @OpbrengstBedragBruto = null;
  set @OpbrengstBedragNetto = null;
  set @Kostprijs = null;

  select DecimalenBoeking*2 into @AantDecimalenBasis from tabvaluta where ValNummer=@@BasisValutaNummer;
  select DecimalenBoeking*2 into @AantDecimalenFact  from tabvaluta where ValNummer=(select FkValNummer from tabFactuurKop where FkGid = @FkGid);

  select //sum( round(frBrutoPrijsPeenheid/frPrijsPer * frAantalDezeFacturering, @AantDecimalenFact)
         sum( (if FrEenheidPrijsPer = 0 then
                 /*Verkoopeenheid*/
                 round(frBrutoPrijsPeenheid * frAantalDezeFacturering, @AantDecimalenFact)
               else
                 /*Voorraadeenheid*/
                 round(frBrutoPrijsPeenheid/frPrijsPer * FrAantalDezeFactureringVrrdEenh, @AantDecimalenFact)
               endif)
              / if @fkInclBtw = 0 then 1 else (100 + frBtwPercentage ) / 100 endif // ACW 18-01-2002: Hier stond * 100 ipv. / 100 wat fout was
            ),
         sum( if @fkInclBtw = 0 then frRegelTotaal else frRegelTotaal / (100 + frBtwPercentage ) * 100 endif ),
         sum( round(isnull(frKostprijs/frPrijsPer * FrAantalDezeFactureringVrrdEenh, 0), @AantDecimalenBasis) ) VolgensKostprijs,
         // ACW 25-09-2002: ivm. bug6794 alleen voorraadprijzen als het een artikel betreft. Anders die uit de order (bij goedkeuring vastgelegd)
         if @RegelSoort = 2 then
           sum( round((select (if ArtIsPartijAparteKostPrijs = 0 or ArtIsPartijRegistreren = 0 or ArtPartijKostprijsEx is null then artKostprijsEx else ArtPartijKostprijsEx endif)/ArtPrijsPer from tabArtikel where ArtCode = FrArtCode and ArtSoort = FrSoortRegel) * FrAantalDezeFactureringVrrdEenh, @AantDecimalenBasis) )
         else
           VolgensKostprijs
         endif
  into   @OpbrengstBedragBruto, @OpbrengstBedragNetto, @Kostprijs, @VoorraadPrijs
  from   tabFactuurRegel
         inner join tabFactuurReferentie on (frfrefgid = frefgid)
         inner join tabOpbrengstGroep on (frOpbrGrpNummer = OpbrGrpNummer)
         inner join taborderkop on (OrkGid = frefOrkGid)
         inner join tabOrderRegel on (OrrOrkGid = OrkGid and OrrRegelnr = frRegelNummer)
         inner join tabArtikel on (ArtGid = OrrArtGid)
         left outer join tabArtikelPartij on (ArtPartijGid = OrrArtPartijGid)
  where  frefFkGid = @fkGid and
         OpbrGrpGid = @OpbrGrpGid and
         IsNull(frKstpCode,'') = IsNull(@KstpCode,'') and
         IsNull(frKstdCode,'') = IsNull(@KstdCode,'') and
         frSoortRegel = @RegelSoort and  //of obv. levering MAAR soortregel = artikel (omdat bij leveren de tarieven NIET worden meegenomen!!)
         (isnull(OrkEersteActie,0) = @EersteActie or @EersteActie = 0 or (OrkEersteActie = 0 and @EersteActie = 1))
         and (@BtwCode is null or frBtwCode = @BtwCode);

  //call Trace('Opbrengstgroep='+ string(@OpbrGrpNummer) + ' Bedrag "gewone" regels: bruto='+string(@OpbrengstBedragBruto)+', netto='+string(@OpbrengstBedragNetto)+'!');
  //call Trace ('@Kostprijs='+string(@Kostprijs)+', @VoorraadPrijs='+string(@VoorraadPrijs));



  //Opbrengst van de extra regels
  set @OpbrengstExtraBedragBruto = null;
  set @OpbrengstExtraBedragNetto = null;
  select sum( ferPercentage /100 * ( if ferSoortRegel = 0 then -1 else 1 endif ) * //Toeslag/kort.percentage
              ( isnull(
                ( if ferBerekenOverTarief = 3 then 0
                  else
                    //Bereken over brutoregeltotalen (dus excl. regelkorting)
                    ( select sum(if @fkInclBtw = 0 then
                                    (if frEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                     *
                                     frBrutoPrijsPeenheid/frPrijsPer
                                 else
                                    (if frEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                     *
                                     (frBrutoPrijsPeenheid/frPrijsPer) / (100 + frBtwPercentage ) * 100
                                 endif )
                      from   tabFactuurRegel inner join tabFactuurReferentie on (frefGid = frFrefGid) inner join taborderkop on (OrkGid = FrefOrkGid)
                      left outer join tabKostenPlaats on (frKstpCode = KstpCode) left outer join tabKostenDrager on (frKstdCode = KstdCode)
                      where IsNull(KstpCode,'') = IsNull(@KstpCode,'') and IsNull(KstdCode,'') = IsNull(@KstdCode,'') and frefGid = ferFrefGid and frOpbrGrpNummer = @OpbrGrpNummer and frSoortRegel = 1 and frSoortRegel = @RegelSoort and (isnull(OrkEersteActie,0) = @EersteActie or @EersteActie = 0 or (OrkEersteActie = 0 and @EersteActie = 1)
                      and (@BtwCode is null or frBtwCode = @BtwCode))
                    )
                  endif ), 0 ) +
                isnull(
                ( if ferBerekenOverArtikel = 3 then 0
                  else
                    //Bereken over brutoregeltotalen (dus excl. regelkorting)
                    ( select sum( if @fkInclBtw = 0 then
                                    (if frEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                     *
                                    (frBrutoPrijsPeenheid/frPrijsPer)
                                  else
                                    (if frEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                     *
                                     (frBrutoPrijsPeenheid/frPrijsPer) / (100 + frBtwPercentage ) * 100
                                  endif )
                      from   tabFactuurRegel inner join tabFactuurReferentie on (frefGid = FrFrefGid) inner join taborderkop on (OrkGid = FrefOrkGid)
                      left outer join tabKostenPlaats on (frKstpCode = KstpCode) left outer join tabKostenDrager on (frKstdCode = KstdCode)
                      where IsNull(KstpCode,'') = IsNull(@KstpCode,'') and IsNull(KstdCode,'') = IsNull(@KstdCode,'') and frefGid = ferFrefGid and frOpbrGrpNummer = @OpbrGrpNummer and frSoortRegel = 2 and frSoortRegel = @RegelSoort and (isnull(OrkEersteActie,0) = @EersteActie or @EersteActie = 0 or (OrkEersteActie = 0 and @EersteActie = 1)
                      and (@BtwCode is null or frBtwCode = @BtwCode))
                    )
                endif ), 0 )
                //TODO: Emballage + korting/toeslag over korting/toeslag
            ) ),
         sum( ferPercentage /100 * ( if ferSoortRegel = 0 then -1 else 1 endif ) * //Toeslag/kort.percentage
              ( isnull(
                ( case ferBerekenOverTarief
                  when 1 then
                    //Bereken over brutoregeltotalen (dus excl. regelkorting)
                    ( select sum( if @fkInclBtw = 0 then
                                    (if frEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                     *
                                    (frBrutoPrijsPeenheid/frPrijsPer)
                                  else
                                    (if frEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                     *
                                    (frBrutoPrijsPeenheid/frPrijsPer) / (100 + frBtwPercentage ) * 100
                                  endif )
                      from   tabFactuurRegel inner join tabFactuurReferentie on (frefGid = frFrefGid) inner join taborderkop on (OrkGid = FrefOrkGid)
                      left outer join tabKostenPlaats on (frKstpCode = KstpCode) left outer join tabKostenDrager on (frKstdCode = KstdCode)
                      where IsNull(KstpCode,'') = IsNull(@KstpCode,'') and IsNull(KstdCode,'') = IsNull(@KstdCode,'') and frefGid = ferFrefGid and frOpbrGrpNummer = @OpbrGrpNummer and frSoortRegel = 1 and frSoortRegel = @RegelSoort and (isnull(OrkEersteActie,0) = @EersteActie or @EersteActie = 0 or (OrkEersteActie = 0 and @EersteActie = 1)
                      and (@BtwCode is null or frBtwCode = @BtwCode))
                    )
                  when 2 then
                    //Bereken over regeltotalen (dus incl. regelkorting)
                    ( select sum( if @fkInclBtw = 0 then frRegelTotaal else frRegelTotaal / (100 + frBtwPercentage ) * 100 endif )
                      from   tabFactuurRegel inner join tabFactuurReferentie on (frefGid = frFrefGid) inner join taborderkop on (OrkGid = FrefOrkGid)
                      left outer join tabKostenPlaats on (frKstpCode = KstpCode) left outer join tabKostenDrager on (frKstdCode = KstdCode)
                      where IsNull(KstpCode,'') = IsNull(@KstpCode,'') and IsNull(KstdCode,'') = IsNull(@KstdCode,'') and frefGid = ferFrefGid and frOpbrGrpNummer = @OpbrGrpNummer and frSoortRegel = 1 and frSoortRegel = @RegelSoort and (isnull(OrkEersteActie,0) = @EersteActie or @EersteActie = 0 or (OrkEersteActie = 0 and @EersteActie = 1)
                      and (@BtwCode is null or frBtwCode = @BtwCode) )
                    )
                  else 0
                  end ), 0 ) +
                isnull(
                ( case ferBerekenOverArtikel
                  when 1 then
                    //Bereken over brutoregeltotalen (dus excl. regelkorting)
                    ( select sum( if @fkInclBtw = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) * (frBrutoPrijsPeenheid/frPrijsPer) else (if frAantalBesteld=0 then 1 else frAantalBesteld endif) * (frBrutoPrijsPeenheid/frPrijsPer) / (100 + frBtwPercentage ) * 100 endif )
                      from   tabFactuurRegel inner join tabFactuurReferentie on (frefGid = frFrefGid) inner join taborderkop on (OrkGid = FrefOrkGid)
                      left outer join tabKostenPlaats on (frKstpCode = KstpCode) left outer join tabKostenDrager on (frKstdCode = KstdCode)
                      where IsNull(KstpCode,'') = IsNull(@KstpCode,'') and IsNull(KstdCode,'') = IsNull(@KstdCode,'') and frefGid = ferFrefGid and frOpbrGrpNummer = @OpbrGrpNummer and frSoortRegel = 2 and frSoortRegel = @RegelSoort and (isnull(OrkEersteActie,0) = @EersteActie or @EersteActie = 0 or (OrkEersteActie = 0 and @EersteActie = 1)
                      and (@BtwCode is null or frBtwCode = @BtwCode) )
                    )
                  when 2 then
                    //Bereken over regeltotalen (dus incl. regelkorting)
                    ( select sum( if @fkInclBtw = 0 then frRegelTotaal else frRegelTotaal / (100 + frBtwPercentage ) * 100 endif )
                      from   tabFactuurRegel inner join tabFactuurReferentie on (frefGid = frFrefGid) inner join taborderkop on (OrkGid = FrefOrkGid)
                      left outer join tabKostenPlaats on (frKstpCode = KstpCode) left outer join tabKostenDrager on (frKstdCode = KstdCode)
                      where IsNull(KstpCode,'') = IsNull(@KstpCode,'') and IsNull(KstdCode,'') = IsNull(@KstdCode,'') and  frefGid = ferFrefGid and frOpbrGrpNummer = @OpbrGrpNummer and frSoortRegel = 2 and frSoortRegel = @RegelSoort and (isnull(OrkEersteActie,0) = @EersteActie or @EersteActie = 0 or (OrkEersteActie = 0 and @EersteActie = 1)
                      and (@BtwCode is null or frBtwCode = @BtwCode) )
                    )
                  else 0
                  end ), 0 )
                //TODO: Emballage + korting/toeslag over korting/toeslag
            ) )
  into @OpbrengstExtraBedragBruto, @OpbrengstExtraBedragNetto
  from tabFactuurExtraRegel inner join tabFactuurReferentie on (frefGid = ferFrefGid) inner join tabOrderkop on (OrkGid = frefOrkGid)
  where frefFkGid = @FkGid and
        (OrkEersteActie = @EersteActie or @EersteActie = 0  or (OrkEersteActie = 0 and @EersteActie = 1) );


  set @Kostprijs = isnull(@Kostprijs, 0);

  //call TraceEind('FacturerenBerekenOpbrengst(@OpbrengstBedragBruto='+string(@OpbrengstBedragBruto)+',@OpbrengstBedragNetto='+string(@OpbrengstBedragNetto)+', @OpbrengstExtraBedragBruto='+string(@OpbrengstExtraBedragBruto )+',@OpbrengstExtraBedragNetto='+string(@OpbrengstExtraBedragNetto)+', @Kostprijs='+string(@Kostprijs)+', @VoorraadPrijs='+string(@VoorraadPrijs)+')');

end;


//$Workfile: FacturerenBerekenProjectOpbrengst.sp $ $Revision: 5 $ $Modtime: 29-07-09 16:06 $'

// Aparte variant van FacturerenBerekenOpbrengst voor berekenen van opbrengst PROJECT factuur
if exists (select 1 from sys.sysProcedure where proc_name='FacturerenBerekenProjectOpbrengst') then
  drop procedure FacturerenBerekenProjectOpbrengst;
end if;

create procedure FacturerenBerekenProjectOpbrengst(
	in @fkGid 						integer,
	in @fkInclBtw 				integer,
	in @ProjGrpGid 				integer,
	in @OpbrGrpGid 				integer,
	in @OprengstOpOpbrGrp smallint,
	in @KostPrOpOpbrGrp 	smallint,
	out @OpbrengstBedrag 	numeric(15,2),
	out @KostprijsBedrag 	numeric(15,2)
	)
begin
  declare @AantDecimalenBasis smallint;

  set @@ErrorTextProcedure = 'FacturerenBerekenProjectOpbrengst(@fkGid='+string(@fkGid)+', @ProjGrpGid='+string(@ProjGrpGid)+', @OpbrGrpGid='+string(@OpbrGrpGid)+', @OprengstOpOpbrGrp='+string(@OprengstOpOpbrGrp)+', @KostPrOpOpbrGrp='+string(@KostPrOpOpbrGrp);
  //call TraceBegin(@@ErrorTextProcedure);

  set @OpbrengstBedrag = null;
  set @KostprijsBedrag = null;

  select DecimalenBoeking*2 into @AantDecimalenBasis from tabvaluta where ValNummer=@@BasisValutaNummer;

	select sum(round(Opbrengst, @AantDecimalenBasis)) Opbr, sum(round(Kostprijs, @AantDecimalenBasis)) KostPr into @OpbrengstBedrag, @KostprijsBedrag from
	(  select
	    ( if (@ProjGrpGid is null and @OprengstOpOpbrGrp = 1) or (@ProjGrpGid is not null and @OprengstOpOpbrGrp = 0) then (if PfvkStatus = 3 then -PfvlAantal else PfvlAantal endif) * (if @fkInclBtw = 0 then PbrVerkoopprijs else PbrVerkoopprijs / (100 + BtwPercentage ) * 100 endif) / PbrPrijsPer else 0 endif ) Opbrengst,
      ( if (@ProjGrpGid is null and @KostPrOpOpbrGrp   = 1) or (@ProjGrpGid is not null and @KostPrOpOpbrGrp   = 0) then (if PfvkStatus = 3 then -PfvlAantal else PfvlAantal endif) * (if PbrDoorbelastPercentage is null or PbrDoorbelastPercentage > 100.00 then PbrPartFactEenheidFactor *  PbrKostprijs else PbrPartFactEenheidFactor * PbrDoorbelastPercentage / 100 *  PbrKostprijs endif) / PbrPrijsPer else 0 endif) Kostprijs
	    //( if (@ProjGrpGid is null and @KostPrOpOpbrGrp   = 1) or (@ProjGrpGid is not null and @KostPrOpOpbrGrp   = 0) then round((if PfvkStatus = 3 then -PfvlAantal else PfvlAantal endif) * ( PbrKostprijs ) / PbrPrijsPer, @AantDecimalenBasis) else 0 endif) Kostprijs

		  from  tabFactuurreferentie
	          inner join tabfactuurkop on (fkGid = frefFkGid)
	          inner join tabProjectFactuurVoorstelKop on PfvkGid = frefPfvkGid
	          inner join tabProjectFactuurVoorstelRegel on PfvrPfvkGid = PfvkGid
	          inner join tabProject on PfvkProjGid = ProjGid
	          inner join tabProjectGroep on ProjProjGrpGid = ProjGrpGid
	          inner join tabProjectFactuurVoorstelRealisatie on pfvlFvrGid = pfvrGid
	          inner join tabProjectBoekingsRegel on PfvlPbrGid = PbrGid
            left outer join tabBtw on pfvrBtwCode = BtwCode
	          inner join tabArtikel on PbrArtGid = ArtGid
	          inner join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGId)
	    where  (fkGid = @FkGid) and
	    			  ( (@ProjGrpGid is null     and OpbrGrpGid = @OpbrGrpGid)
	    			     or
	    			    (@ProjGrpGid is not null and ProjGrpGid = @ProjGrpGid)
	    			  )
	    group by PfvlPbrGid, PfvkStatus, ProjGrpGid, OpbrGrpNummer, OpbrGrpGid, PbrPrijsPer, PfvlAantal, PbrVerkoopprijs, PbrKostprijs, BtwPercentage, ArtAantDecPrijzen, PbrDoorbelastPercentage, PbrPartFactEenheidFactor, PbrAantalGefactureerd, PbrAantalDeclarabel
	) Tabel;

  //call Trace('Opbrengst='+string(@OpbrengstBedrag) + ', Kpostprijs='+string(@KostprijsBedrag));

  //call TraceEind('FacturerenBerekenProjectOpbrengst(@ProjGrpGid='+string(@ProjGrpGid)+', @OpbrGrpGid='+string(@OpbrGrpGid)+', @OpbrengstBedrag='+string( @OpbrengstBedrag )+',@KostprijsBedrag='+string(@KostprijsBedrag));

end;





create or replace procedure FacturerenBoekFactuur(
  in @fbGid            integer,
  in @fkGid            integer,
  in @fkFactuurNummer  nchar(40),
  in @fkFactDebNummer  nchar(10),
  in @LayoutSoort      integer,
  in @Boekdatum        date,
  in @BjGid            integer,
  in @PerNr            integer,
  in @BedragBetaald    numeric(15,2),
  in @VerschilAfboeken integer,
  in @BoekgangGid      integer,
  in @OokLeveren       integer
)
begin
  declare @Oms                    nchar(40);
  declare @nawgid                 integer;
  declare @DebRksGid              integer;
  declare @Bedrag                 numeric(15,2);
  declare @BasisBedrag            numeric(15,2);
  declare @HoogsteBedragOpbrGroep numeric(15,2);
  declare @HoogsteOpbrGroepRksGid integer;
  declare @HoogsteKstpCode        nchar(8);
  declare @HoogsteKstdCode        nchar(8);
  declare @HoogsteOpbrGrpGid      integer;
  declare @HoogsteOpbrIsGoed      smallint;
  declare @RegelSoort             integer;
  declare @frKstpCode		          nchar(8);
  declare @frKstdCode		          nchar(8);

  //Lus voor facturen in factuurbatch
  declare @fkInclBtw              smallint;
  declare @ValNummer              integer;
  declare @fkVerschilAfboeken     integer;
  declare @fkBedragBetaald        numeric(15,2);
  declare @fkKredBepBedrag        numeric(15,2);
  declare @fkKredBepRksInvoer     nchar(28);
  declare @fkKredBepDatum         date;
  declare @fkBtcSoort             smallint;    //0=normale factuur, 1=kred.bep., 2=bet.korting
  declare @fkBtcNummer            integer;
  declare @fkBtcBedragExBtw       numeric(15,2);
  declare @fkBtcBedragInBtw       numeric(15,2);
  declare @fkBtcBedragInExBtw     numeric(15,2);  // Alleen voor de betalingskorting, wordt gevuld met juiste bedrag obv in/ex
  declare @FkBtcKredBepKortingInclBtw smallint;
  declare @fkFactuurDatum         date;
  declare @fkVervalDatum          date;
  declare @fkIncassoDatum         date;
  declare @FactuurTotaalInBtw     numeric(15,2);
  declare @FkIsAbcLevering        smallint;

  //Lus voor BTW in factuur
  declare @fkBedragTeBetalen      numeric(15,2);
  declare @VorigBtwCode           integer;
  declare @BtwCode                integer;

  //Direct nodig voor boeken
  declare @DgbGid                 integer;
  declare @JpGid                  integer;
  declare @fbrBtwBasis            numeric(15,2);
  declare @fbrBtwBedrag           numeric(15,2);
  declare @BetVerschilRksGid      integer;
  declare @HulpRekGid             integer;
  declare @OpbrBoekenInValVanRek  smallint;
  declare @GrpSoortRksGID         integer;
  declare @OpbrNaarValNummer      integer;
  declare @RegelkortingApart      smallint;
  declare @TotaalRegelKorting     numeric(15,2);
  declare @BtwRekening            integer;
  declare @BtwValNummer           integer;
  declare @FkBetalingskenmerk     nchar(24);
  //Loop voor opbrengstgroepen
  declare @OpbrGrpNummer          nchar(4);
  declare @OpbrGrpGid             integer;
  declare @OpbrGrpIsGoed          smallint;
  declare @OpbrengstBedragNetto   numeric(15,2);
  declare @OpbrengstExtraBedragNetto numeric(15,2);
  declare @OpbrengstBedragBruto   numeric(15,2);
  declare @OpbrengstExtraBedragBruto numeric(15,2);
  declare @TotaalJr               numeric(15,2);
  declare @TotaalHulp             numeric(15,2);
  declare @Kostprijs              numeric(15,2);
  declare @VoorraadPrijs          numeric(15,2);
  declare @JrGid                  integer;
  declare @HulpBedrag             numeric(15,2);
  declare @fkBtcPerc              numeric(6,2);
  declare @EersteActie            smallint;
  declare @IsApartLeveren         smallint;
  declare @OrkNummer              nchar(10);

  declare @AantDecimalenBasis     integer;
  declare @VorigeIctBtwCode       integer;
  declare @IctBtwCode             integer;

  declare @VGRekeningBetalingen   integer;
  declare @TegenRekeningDagboek   integer;

  declare @VofBoekdatumFactuur    integer;
  declare @RksGidGefactOmzet      integer;
  declare @DatumFactuurBoeking    date;
  declare @PernrFactuurBoeking    integer;

  declare @SoortFactuurOverruled smallint = 0;

  declare local temporary table tmpRegelSoort
   (Rsoort integer null) on commit preserve rows;

  declare local temporary table tmpEersteActie
   (EersteActie integer null) on commit preserve rows;

  declare local temporary table tmpJrGid
   (JrGid integer not null) on commit preserve rows;

  declare cursor_Opbrengstgroep dynamic scroll cursor for
    select   Rsoort, EersteActie, OpbrGrpNummer,  OpbrGrpGid,  IsOpbrGrpGoederen, frKstpCode, frKstdCode
    from     tmpEersteActie, tabFactuurRegel inner join tabFactuurreferentie on (frefGid = frFrefGid) inner join tabfactuurkop on (fkGid = frefFkGid) inner join tabOpbrengstgroep on (OpbrGrpnummer = frOpbrGrpNummer)inner join tabOrderkop on (frefOrkGid = OrkGid), tmpRegelSoort
    where    (fkGid = @fkGid) and (Rsoort = frSoortRegel) and
             ((OrkEersteActie = EersteActie) or (EersteActie = 1 and OrkEersteActie = 0))
    group by EersteActie, OpbrGrpNummer,  Rsoort, OpbrGrpGid,  IsOpbrGrpGoederen, frKstpCode, frKstdCode
    order by EersteActie, OpbrGrpNummer,  Rsoort
  for read only;

  declare cursor_PerOrderKostprijs scroll cursor for
    select frefOrderNummer, sum( round(isnull(frKostprijs/frPrijsPer * FrAantalDezeFactureringVrrdEenh,0), @AantDecimalenBasis) )
    from   tabFactuurRegel inner join tabFactuurReferentie on (frfrefgid = frefgid) inner join taborderkop on (OrkGid = frefOrkGid)
    where  frefFkGid = @fkGid and
           frOpbrGrpNummer = @OpbrGrpNummer and
           frSoortRegel = @RegelSoort  and //of obv. levering MAAR soortregel = artikel (omdat bij leveren de tarieven NIET worden meegenomen!!)
           IsNull(frKstpCode,'') = IsNull(@frKstpCode,'') and    // RS: Toegevoegd kstp/kstd-controle
           IsNull(frKstdCode,'') = IsNull(@frKstdCode,'') and
            ((OrkEersteActie = @EersteActie) or (@EersteActie = 1 and OrkEersteActie = 0))
    group by frefOrderNummer
    order by frefOrderNummer
  for read only;

  set @@ErrorTextProcedure = 'FacturerenBoekFactuur > ';
  //call TraceBegin(@@ErrorTextProcedure + '@fbGid = ' + string(@fbGid) + ', @fkGid = ' + string(@fkGid) + ', @fkFactuurNummer = ' + string(@fkFactuurNummer) + ', @fkFactDebNummer = ' + string(@fkFactDebNummer) + ', @LayoutSoort = ' + string(@LayoutSoort) + ', @BoekDatum = ' + string(@BoekDatum) + ', @BjGid = ' + string(@BjGid) + ', @PerNr = ' + string(@PerNr) + ', @BedragBetaald = ' + string(@BedragBetaald) + ', @VerschilAfboeken = ' + string(@VerschilAfboeken) + ', @BoekgangGid = ' + string(@BoekgangGid) + ', @OokLeveren = ' + string(@OokLeveren));

  // Bij directe facturering is de lock op de BG gewijzigd naar de UI connectie, zodat we voor volgende directe facturen aan dezelfde BG kunnen blijven toevoegen.
  // In dat geval geen controle op gelocked zijn door de eigen connectie - die is vd achtergrondtaak namelijk
  if @LayoutSoort = 60 then
    set @@OverRuleLock = 1;
  end if;

  //Eerst dagboek tbv. factureren opvragen
  case @LayoutSoort
    when 50 then select first vofBatchDgbGid        into @DgbGid from tabVasteGegevensOrdersFactureren;
    when 60 then select first vofDirectDgbGid, vofContantBoekenOpRksGid, DgbTegenRksGid into @DgbGid, @VGRekeningBetalingen, @TegenRekeningDagboek from tabVasteGegevensOrdersFactureren inner join tabDagboek on vofDirectDgbGid = DgbGid;
    when 65 then select first ProjVastVerkoopDgbGid into @DgbGid from tabProjectVastegegevens;
  end case;

  //Regelsoorten apart verwerken ivm. boeking op de tussenrek. (voor artikelen) resp. opbrengst (tarieven)
  insert into tmpRegelSoort(Rsoort) values(1); //Regelsoort 1 = tarief
  insert into tmpRegelSoort(Rsoort) values(2); //Regelsoort 2 = artikel

  insert into tmpEersteActie(EersteActie) values(1); //Eerste actie 1 = Factureren
  insert into tmpEersteActie(EersteActie) values(2); //Eerste actie 2 = Leveren



  select DecimalenBoeking*2 into @AantDecimalenBasis from tabvaluta where ValNummer=@@BasisValutaNummer;

  //Opbrengstboekingen in basisvaluta of in valuta van opbr.rekening
  select vofIsBoekOpbrengstInValuta, vofIsRegelkortingApart into @OpbrBoekenInValVanRek, @RegelkortingApart from tabVasteGegevensOrdersFactureren;
  if not exists(select 1 from tabparagraaf where ParSoort = 60 and ParBlGid is not null /*verleende kortingen*/) then
    //Er is geen 'verleende kortingen'-paragraaf, dus toch maar niet apart boeken!
    set @RegelkortingApart = 0;
  end if;

  //Apart leveren? Alleen als we artikelen hebben *en* we gaan leveren apart verwerken
  if IsModuleActive('ar') = 1 and @OokLeveren = 0 then
    set @IsApartLeveren = 1;
  else
    set @IsApartLeveren = 0;
  end if;
  //call Trace('FacturerenBoekFactuur > @IsApartLeveren = ' + string(@IsApartLeveren));

  //NawGid opzoeken tbv. ICT en omzetten
  select NawGid into @nawgid
  from   tabNawFile inner join tabFileOfNaw on (fonGid = NawFilFonGid and FonId = 'D') inner join tabNaw on (NawGid = NawFilNawGid)
  where  NawFilNummer = @fkFactDebNummer;

  //Factuurgegevens opzoeken
select fkIsInclBtw, (select RksGid from tabrekeningschema where RksInvoer = fkFactDebNummer), fkValNummer, fkFactuurDatum,  fkVervalDatum,  fkVerschilAfboeken,  fkFactTotInBtw, fkBedragBetaald,  fkBtcBedrag,      fkBtcRksInvoer,      fkBtcDatum,      fkBtcSoort,  fkBtcNummer, fkBtcBedrag, fkBtcBedragInBtw, (if FkBtcKredBepKortingInclBtw = 0 then fkBtcBedrag else fkBtcBedragInBtw endif), fkBtcPerc, FkBtcKredBepKortingInclBtw, FkBetalingskenmerk, FkIsAbcLevering, fkIncassoDatum
  into   @fkInclBtw,  @DebRksGid, @ValNummer, @fkFactuurDatum, @fkVervalDatum, @fkVerschilAfboeken, @FactuurTotaalInBtw, @fkBedragBetaald, @fkKredBepBedrag, @fkKredBepRksInvoer, @fkKredBepDatum, @fkBtcSoort, @fkBtcNummer, @fkBtcBedragExBtw, @fkBtcBedragInBtw, @fkBtcBedragInExBtw, @fkBtcPerc, @FkBtcKredBepKortingInclBtw, @FkBetalingskenmerk, @FkIsAbcLevering, @fkIncassoDatum
  from   tabFactuurkop
  where  fkgid = @fkgid;

  // Moet de factuurboeking via een tussenrekening lopen, waardoor omzet in een andere periode (datum) geboekt kan worden
  select VofBoekdatumFactuur,
         if VofBoekdatumFactuur = 0 then @BoekDatum else @fkFactuurDatum endif,
         if @BoekDatum < @fkFactuurDatum then VofRksGIDAchterafGefactOmzet else VofRksGIDVooruitGefactOmzet endif VofRksGid
  into   @VofBoekdatumFactuur, @DatumFactuurBoeking, @RksGidGefactOmzet
  from   tabVasteGegevensOrdersFactureren;

  call BepaalBoekjaarEnPeriode(@DatumFactuurBoeking, 0, @PernrFactuurBoeking);

  // maak journaalpost aan
  select FactuurBoekMaakJpOms(@LayoutSoort, @fkGid, @fkFactuurNummer) into @Oms;
  insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum)
  select @BoekGangGid, 1, @DgbGid, @fkFactuurNummer, @Oms, @DatumFactuurBoeking;
  set @JpGid = @@Identity;

  // Journaalpost in de factuur onthouden
  update tabFactuurKop set FkJpGid = @JpGid where FkGid = @FkGid;

  //Maak journaalr. voor de debiteur (met btw-rek. als hulprek.)
  //(debiteur xxx      <bedrag incl.btw>; hulprek.: btw; bedrag: -btwbedrag)
  set @fkBedragTeBetalen = 0;
  set @VorigBtwCode      = -1;
  BtwLoop:
  Loop
    set @BtwCode = null;
    select first fbrBtwCode, fbrBtwBasis,  fbrBtwBedrag
    into         @BtwCode,   @fbrBtwBasis, @fbrBtwBedrag
    from     tabFactuurBtwRegel
    where    fbrFkGid = @FkGid and fbrBtwCode > @VorigBtwCode
    order by fbrBtwCode;
    if @BtwCode is null then
      leave BtwLoop;
    end if;
    set @VorigBtwCode = @BtwCode;

    //Factuurbedrag onthouden
    set @fkBedragTeBetalen = @fkBedragTeBetalen + @fbrBtwBasis + @fbrBtwBedrag;

    //Journaalregel per BTW van de debiteur

    set @bedrag = round(@fbrBtwBasis + @fbrBtwBedrag, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@valnummer));

    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                 IsCreditBoeking, SoortBoeking, JrValNummer, jrReferentie, jrFactuurDatum, jrVervalDatum, JrBetalingsKenmerk, JrBoekdatum)
      values( @JpGid, @DebRksGid, @bedrag, if @ValNummer = @@BasisValutaNummer then @Bedrag else ValutaOmrekenen(@ValNummer, @Bedrag, @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif, @oms,
              0, 0, @ValNummer, @fkFactuurNummer, @fkFactuurDatum, @fkVervalDatum, @FkBetalingskenmerk, @DatumFactuurBoeking);
    set @JrGid = @@Identity;

    //Factuuroverzicht onthouden: Valuta
    insert into tabFactuurOverzichtValuta( fovBoekgangGid, fovValNummer, fovBedragValuta, fovBedragBasis, fovFbGid )
    values( @BoekGangGid, @ValNummer, @bedrag, if @ValNummer = @@BasisValutaNummer then @Bedrag else ValutaOmrekenen(@ValNummer, @Bedrag, @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif, @FbGid );

    //BTW boeken in val.van BTW-rek.
    select BtwRksGid, RksValNummer into @BtwRekening, @BtwValNummer from tabBtw inner join tabRekeningSchema on (RksGid = BtwRksGid) where BtwCode = @BtwCode;
    set @HulpBedrag = round(if @ValNummer = @BtwValNummer then @fbrBtwBedrag else ValutaOmrekenen(@ValNummer, @fbrBtwBedrag, @BtwValNummer, @BjGid, @PernrFactuurBoeking, 2) endif, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@BtwValNummer));
    set @Bedrag = if @BtwValNummer = @@BasisValutaNummer then @HulpBedrag else ValutaOmrekenen(@BtwValNummer, @HulpBedrag, @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif;
    insert into tabHulprekening (hulprekBasisBedrag, hulprekValnummer, hulprekValutaBedrag, hulprekSoort, hulprekIsCredit, hulprekRksgid, HulprekBtwCode, hulprekJrGid)
    values (@Bedrag, @BtwValNummer, @HulpBedrag, 1, 1,  @BtwRekening, @BtwCode, @JrGid);

    //En onthouden tbv. factuuroverzicht: Btw-bedrag
    insert into tabFactuurOverzichtBtw( fobBoekgangGid, fobBtwCode, fobBedrag, fobFbGid ) values ( @BoekGangGid, @BtwCode, @Bedrag, @FbGid );

  end loop BtwLoop;

  //Als er geen enkele BTW is (dus geen bedragen!) dan toch een boeking van de OSP plegen
  if @VorigBtwCode = -1 then
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                 IsCreditBoeking, SoortBoeking, JrValNummer, jrReferentie, jrFactuurDatum, jrVervalDatum, JrBoekdatum)
    values( @JpGid, @DebRksGid, 0, 0, @oms, 0, 0, @ValNummer, @fkFactuurNummer, @fkFactuurDatum, @fkVervalDatum, @DatumFactuurBoeking);
    insert into tabFactuurOverzichtValuta( fovBoekgangGid, fovValNummer, fovBedragValuta, fovBedragBasis, fovFbGid )
    values( @BoekGangGid, @ValNummer, 0, 0, @FbGid );
  end if;

  //Kredietbeperking als aparte boeking maken
  if isnull(@fkKredBepBedrag,0) <> 0 and @fkKredBepRksInvoer is not null and @fkBtcSoort = 1 then
    //call Trace('FacturerenBoekFactuur > Kred.beperking = ' + string(@fkKredBepBedrag) + ', basis = ' + string(ValutaOmrekenen(@ValNummer, @fkKredBepBedrag, @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2)));
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag,
                                 JrBasisBedrag,
                                 OmsJournaalRegel, IsCreditBoeking, SoortBoeking, JrValNummer, jrFactuurDatum, jrVervalDatum, JrBoekdatum )
    values( @JpGid, ( select RksGid from tabRekeningSchema where RksInvoer = @fkKredBepRksInvoer ), round(@fkKredBepBedrag, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@valnummer)),
            if @ValNummer = @@BasisValutaNummer then @fkKredBepBedrag else ValutaOmrekenen(@ValNummer, @fkKredBepBedrag, @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif,
            @oms, 1, 0, @ValNummer, @fkFactuurDatum, @fkVervalDatum, @DatumFactuurBoeking);
/*Dit deel als de kred.bep. als hulprekening moet worden geboekt ipv. de bovenstaande regel
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel, IsCreditBoeking, SoortBoeking, JrValNummer, jrReferentie, jrFactuurDatum, jrVervalDatum )
    values( @JpGid, @DebRksGid, 0,   0, 'Kredietbep.'+@oms, 0, 0, @ValNummer, @fkFactuurNummer, @fkFactuurDatum, @fkVervalDatum);
    insert into tabHulprekening (hulprekBasisBedrag, hulprekValnummer, hulprekValutaBedrag, hulprekSoort, hulprekIsCredit,  hulprekRksgid, hulprekKredBepDatum, hulprekJrGid)
    values (ValutaOmrekenen(@ValNummer, @fkKredBepBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2), @Valnummer, @fkKredBepBedrag, 4, 1, ( select RksGid from tabRekeningSchema where RksInvoer = @fkKredBepRksInvoer ), @fkKredBepDatum, @JrGid );
*/
  end if;


  //TODO: NOG NIET GEIMPLEMENTEERD:
  //Loop extra orderregels die rekeningnummer hebben met vast bedrag
  //maak journaalregel aan: rekening = uit orderregel; bedrag = regelbedrag
  //einde loop extra orderregels

  //Loop opbrengstgroepen in de factuur
  set @HoogsteBedragOpbrGroep = -1;
  open cursor_Opbrengstgroep;
  LoopOpbrengstGroep:
  loop
    Fetch next cursor_Opbrengstgroep into @RegelSoort, @EersteActie, @OpbrGrpNummer, @OpbrGrpGid, @OpbrGrpIsGoed, @frKstpCode, @frKstdCode;
    if sqlstate = '02000' then
      leave LoopOpbrengstGroep;
    end if;
    //call Trace('FacturerenBoekFactuur > OpbrGrp lus; @RegelSoort = ' + string(@RegelSoort) + ', @EersteActie = ' + string(@EersteActie) + ', @OpbrGrpNummer = ' + string(@OpbrGrpNummer) + ', @OpbrGrpGid = ' + string(@OpbrGrpGid) + ', @OpbrGrpIsGoed = ' + string(@OpbrGrpIsGoed) + ', @frKstpCode = ' + string(@frKstpCode) + ', @frKstdCode = ' + string(@frKstdCode));
    //Er is nog geen 1e actie, dus dan houden we de huidige actie als eerste actie
    if isnull(@EersteActie,0) = 0 then
      set @EersteActie = 1; //Factureren
    end if;

    //Opbrengstbedragen berekenen, maar gesplitst naar artikel en tarief
    call FacturerenBerekenOpbrengst(@fkGid, @fkInclBtw, @OpbrGrpGid, @OpbrGrpNummer, @frKstpCode, @frKstdCode, @RegelSoort, @EersteActie, null, @OpbrengstBedragBruto, @OpbrengstBedragNetto, @OpbrengstExtraBedragBruto, @OpbrengstExtraBedragNetto, @Kostprijs, @VoorraadPrijs);

    set @TotaalRegelKorting = isnull(@OpbrengstBedragBruto, 0) - isnull(@OpbrengstBedragNetto, 0);

    if IsModuleActive('kv') = 1 and (select vofVerbijzOmzet from tabVasteGegevensOrdersFactureren) = 1 then
      //call Trace('FacturerenBoekFactuur > FacturerenLeverMaakRekeningObvOpbrGroepKpKd aangeroepen');
      call FacturerenLeverMaakRekeningObvOpbrGroepKpKd(@OpbrGrpGid, 30, @frKstpCode, @frKstdCode, @GrpSoortRksGID); //Opbrengst
    else
      call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 30, @GrpSoortRksGID); //Opbrengst
    end if;

    //En de boeking van de opbrengst maken...
    set @OpbrNaarValNummer = if @OpbrBoekenInValVanRek = 0 then
                               @@BasisValutaNummer
                             else
                               ( select RksValNummer from tabRekeningSchema where RksGid = @GrpSoortRksGID )
                             endif;

    set @BasisBedrag = if @ValNummer = @@BasisValutaNummer then isnull( if @RegelkortingApart = 0 then @OpbrengstBedragNetto else @OpbrengstBedragBruto endif,0 )+isnull(@OpbrengstExtraBedragNetto,0) else ValutaOmrekenen(@ValNummer, isnull( if @RegelkortingApart = 0 then @OpbrengstBedragNetto else @OpbrengstBedragBruto endif,0 )+isnull(@OpbrengstExtraBedragNetto,0), @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif;
    set @Bedrag      = round(if @@BasisValutaNummer = @OpbrNaarValNummer then @BasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, @BasisBedrag, @OpbrNaarValNummer , @BjGid, @Pernr, 2) endif, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@OpbrNaarValNummer));

    //call Trace('FacturerenBoekFactuur > @Bedrag = ' + string(@Bedrag) + ', @BasisBedrag = ' + string(@BasisBedrag));
    if @Bedrag <> 0 and @BasisBedrag <> 0 then
      //Boeken en onthouden als het bedrag<>0 is
      //call Trace('FacturerenBoekFactuur > Opbrengst; @Bedrag = ' +string(@Bedrag) + ', @BasisBedrag = ' + string(@BasisBedrag) +' Oms = ' + string(@Oms));
      insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                   IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum )
        values( @JpGid, @GrpSoortRksGID,  @Bedrag, @BasisBedrag, @oms, 1, 0, @OpbrNaarValNummer,@BoekDatum);
      set @JrGid = @@Identity;

      insert into tmpJrGid(JrGid) select @JrGid;

      //Factuuroverzicht onthouden: Opbrengst
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid ) values( @BoekGangGid, 0, @OpbrGrpGid, @GrpSoortRksGID, @frKstpCode, @frKstdCode, @BasisBedrag, @FbGid );
    end if;

    //Hoogste opbrengst onthouden
    if abs(@BasisBedrag)>@HoogsteBedragOpbrGroep then
      set @HoogsteBedragOpbrGroep = abs(@BasisBedrag);
      set @HoogsteOpbrGroepRksGid = @GrpSoortRksGID;
      set @HoogsteOpbrGrpGid      = @OpbrGrpGid;
      set @HoogsteOpbrIsGoed      = @OpbrGrpIsGoed;
      set @HoogsteKstpCode        = @frKstpCode;
      set @HoogsteKstdCode	      = @frKstdCode;
    end if;

    //De (evt.) regelkorting berekenen
    set @Bedrag = round(if @ValNummer = @@BasisValutaNummer then isnull( @TotaalRegelKorting,0 ) else ValutaOmrekenen(@ValNummer, isnull( @TotaalRegelKorting,0 ), @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@@BasisValutaNummer));

    //call Trace('FacturerenBoekFactuur > Regelkorting boeken');
    //De regelkorting boeken
    if @RegelkortingApart <> 0 and @Bedrag <> 0 then
      if IsModuleActive('kv') = 1 and (select vofVerbijzKorting from tabVasteGegevensOrdersFactureren) = 1 then
        //call Trace('FacturerenBoekFactuur > Kortingen = ' + string(@Bedrag));
        call FacturerenLeverMaakRekeningObvOpbrGroepKpKd(@OpbrGrpGid, 60, @frKstpCode, @frKstdCode, @GrpSoortRksGID); //Kortingen
      else
        call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 60, @GrpSoortRksGID); //Kortingen
      end if;
      //call Trace('FacturerenBoekFactuur > Regelkorting; basis = ' + string(@bedrag));
      insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                   IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum )
        values( @JpGid, @GrpSoortRksGID, @Bedrag, @Bedrag, @oms, 0, 0, @@BasisValutaNummer,@BoekDatum);
      set @JrGid = @@Identity;

      insert into tmpJrGid(JrGid) select @JrGid;

      //Factuuroverzicht onthouden: Korting
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid ) values( @BoekGangGid, 3 , @OpbrGrpGid, @GrpSoortRksGID, @frKstpCode, @frKstdCode, @Bedrag, @FbGid );
    end if;

    //call Trace('FacturerenBoekFactuur > Kostprijs boeken');
    //Alleen boeken als we een kleine versie hebben (dus geen aparte levering bij artikelen)

    set @kostprijs     = round(@Kostprijs,     @AantDecimalenBasis);
    set @VoorraadPrijs = round(@VoorraadPrijs, @AantDecimalenBasis);

    //call Trace('FacturerenBoekFactuur > Kostprijs = ' + string(@kostprijs) + ', @VoorraadPrijs = ' + string(@VoorraadPrijs));

    //Boeken: KOSTPRIJS ...
    if isnull(@Kostprijs,0) <> 0 then
      if IsModuleActive('kv') = 1 and (select vofVerbijzKostprijs from tabVasteGegevensOrdersFactureren) = 1 then
        //call Trace('FacturerenBoekFactuur > Kostprijs = ' + string(@Kostprijs));
        call FacturerenLeverMaakRekeningObvOpbrGroepKpKd(@OpbrGrpGid, 40, @frKstpCode, @frKstdCode, @GrpSoortRksGID); //Kostprijs
      else
      	call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 40, @GrpSoortRksGID); //Kostprijs
      end if;
      insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                   IsCreditBoeking, SoortBoeking, JrValNummer ,JrBoekdatum)
        values( @JpGid, @GrpSoortRksGID, @Kostprijs, @Kostprijs, @oms, 0, 0, @@BasisValutaNummer ,@BoekDatum);

      //Factuuroverzicht onthouden: Kostprijs
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid ) values( @BoekGangGid, 1 , @OpbrGrpGid, @GrpSoortRksGID, @frKstpCode, @frKstdCode, isnull(@Kostprijs,0), @FbGid );

    end if;

    //Rekening opvragen voor de voorraad-boeking (of tussenrekening)
    //call Trace('FacturerenBoekFactuur > @IsApartLeveren = ' + string(@IsApartLeveren) + ', @Regelsoort = ' + string(@Regelsoort));
    if  @IsApartLeveren <> 1 or @Regelsoort = 1 then
      //We hebben geen artikelen, dus ook niet apart leveren OF het betreft een tarief die dus toch niet apart kan worden geleverd
      //call Trace('FacturerenBoekFactuur > Voorraad boeken! @RegelSoort = ' + string(@RegelSoort));

      if IsModuleActive('ar') = 1 then
        // Boek alsof er voorraad is, dus evt. een verschil tussen orderkostprijs en voorraadkostprijs apart boeken
        if isnull(@VoorraadPrijs,0) <> 0 then

          //+++Boeken: AAN VOORRAAD ...
          call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 50, @GrpSoortRksGID); //Voorraad
          //En boeken...
          insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel, IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum)
            values( @JpGid, @GrpSoortRksGID, @VoorraadPrijs, @VoorraadPrijs, @oms, 1, 0, @@BasisValutaNummer, @BoekDatum);


          //Factuuroverzicht onthouden: Voorraad
          insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid ) values( @BoekGangGid, 2 , @OpbrGrpGid, @GrpSoortRksGID, @frKstpCode, @frKstdCode, isnull(@VoorraadPrijs,0), @FbGid );
        end if;

        //+++Boeken: (AAN) HERWAARDERING
        if isnull(@Kostprijs,0)<>isnull(@VoorraadPrijs,0) then
          call BoekHerwaardering(@OpbrGrpGid, @Voorraadprijs, @Kostprijs, @JpGid, @Oms);
          insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid ) values( @BoekGangGid, 6 , @OpbrGrpGid, (select GrpSoortRksGID from tabOpbrengstGroepSoort where GrpSoortGrpGid = @OpbrGrpGid and GrpSoortParSoort = 80), @frKstpCode, @frKstdCode, isnull(@VoorraadPrijs,0) - isnull(@Kostprijs,0), @FbGid );
        end if;
      else
        // Geen voorraad, dus de oorspronkelijke kostprijs boeken
        if isnull(@Kostprijs,0) <> 0 then

          //+++Boeken: AAN VOORRAAD ...
          call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 50, @GrpSoortRksGID); //Voorraad
          //En boeken...
          insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel, IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum )
            values( @JpGid, @GrpSoortRksGID, @Kostprijs, @Kostprijs, @oms, 1, 0, @@BasisValutaNummer, @BoekDatum);
          //Factuuroverzicht onthouden: Voorraad
          insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid ) values( @BoekGangGid, 2 , @OpbrGrpGid, @GrpSoortRksGID, @frKstpCode, @frKstdCode, isnull(@Kostprijs,0), @FbGid );
        end if;
      end if;

    else  //Boeken via de tussenrekening

      //call Trace('FacturerenBoekFactuur > Alleen factureren; voorraad boeken apart');
      if @EersteActie = 1 then //+++Rekening 'gefactureerde goederen'
        select first vofGeFactureedeGoederenRksGid into @GrpSoortRksGID from tabVasteGegevensOrdersFactureren;
      else                     //+++Rekening 'te factureren goederen'
        select first vofTeFacturerenGoederenRksGid into @GrpSoortRksGID from tabVasteGegevensOrdersFactureren;
      end if;
      //call Trace('FacturerenBoekFactuur > @EersteActie = ' + string(@EersteActie) + ', RksGid wordt: @GrpSoortRksGID = ' + string(@GrpSoortRksGID));

      //We boeken nu PER ORDER de kostprijs in

      //+++Boeken: TE FACTUREREN/LEVEREN GOEDEREN
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid ) values ( @BoekGangGid, 4 + if @EersteActie = 1 then 1 else 0 endif, @OpbrGrpGid, @GrpSoortRksGID, @frKstpCode, @frKstdCode, @Kostprijs, @FbGid );
      //Factuuroverzicht onthouden: Te factureren/Gefactureerde
      open cursor_PerOrderKostprijs;
      loop_PerOrderKostprijs:
      loop
        //call Trace('FacturerenBoekFactuur > In lus!');
        Fetch next cursor_PerOrderKostprijs into @OrkNummer, @Kostprijs;
        if sqlstate = '02000' then
          leave loop_PerOrderKostprijs;
        end if;
        //call Trace('FacturerenBoekFactuur > @OrkNummer = ' + string(@OrkNummer) + ', @Kostprijs = ' +string(@Kostprijs) + ', @OpbrGrpGid = ' + string(@OpbrGrpGid) + ', @RegelSoort = ' + string(@RegelSoort) + ', @OrkNummer = ' + string(@OrkNummer) + ', @Kostprijs = ' + string(@Kostprijs));
        if isnull(@Kostprijs,0) <> 0 then
          insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel, IsCreditBoeking, SoortBoeking, JrValNummer, JrReferentie, jrBoekdatum )
            values( @JpGid, @GrpSoortRksGID, @Kostprijs, @Kostprijs, @oms, 1, 0, @@BasisValutaNummer, @OrkNummer, @BoekDatum);
        end if;
      end loop loop_PerOrderKostprijs;
      close cursor_PerOrderKostprijs;
    end if;

    //TODO: Extra regels met vast bedrag op vaste rekening !!!! rekening = uit opbrengstgroep; bedrag = bedragopbrengst

    //Onthouden van de ICT-gegevens: opbrengst plus kredietbeperking
    //Maar dan alleen voor die bedragen zonder nul-BTW
    //MR 29-apr-2008 bug #27959: Ga per BtwCode dit doen
    set @VorigeIctBtwCode      = -1;
    IctBtwLoop:
    Loop
      set @IctBtwCode = null;

      select first fbrBtwCode into @IctBtwCode
        from     tabFactuurBtwRegel
        where    fbrFkGid = @FkGid and fbrBtwCode > @VorigeIctBtwCode
        order by fbrBtwCode;

      if @IctBtwCode is null then
        leave IctBtwLoop;
      end if;

      set @VorigeIctBtwCode = @IctBtwCode;

      //call Trace('FacturerenBoekFactuur > @BedraginIct = ' + string(@IctBtwCode));

      call FacturerenBerekenOpbrengst(@fkGid, @fkInclBtw, @OpbrGrpGid, @OpbrGrpNummer, @frKstpCode, @frKstdCode, @RegelSoort, @EersteActie, @IctBtwCode, @OpbrengstBedragBruto, @OpbrengstBedragNetto, @OpbrengstExtraBedragBruto, @OpbrengstExtraBedragNetto, @Kostprijs, @VoorraadPrijs);

      set @BasisBedrag = if @ValNummer = @@BasisValutaNummer then isnull( if @RegelkortingApart = 0 then @OpbrengstBedragNetto else @OpbrengstBedragBruto endif,0 )+isnull(@OpbrengstExtraBedragNetto,0) else ValutaOmrekenen(@ValNummer, isnull( if @RegelkortingApart = 0 then @OpbrengstBedragNetto else @OpbrengstBedragBruto endif,0 )+isnull(@OpbrengstExtraBedragNetto,0), @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif;
      set @Bedrag      = round(if @@BasisValutaNummer = @OpbrNaarValNummer then @BasisBedrag else ValutaOmrekenen(@@BasisValutaNummer, @BasisBedrag, @OpbrNaarValNummer , @BjGid, @Pernr, 2) endif, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@OpbrNaarValNummer));
      set @TotaalRegelKorting = isnull(@OpbrengstBedragBruto, 0) - isnull(@OpbrengstBedragNetto, 0);

      if @BasisBedrag <> 0 then
        //MR 29-apr-2008 bug #27959: BtwCode meegeven
        call ZetBedragInIct( @nawgid, @OpbrGrpIsGoed, @DatumFactuurBoeking, @BasisBedrag*(if @fkBtcSoort=1 then (100+@fkBtcPerc)/100 else 1 endif), @FkIsAbcLevering, @IctBtwCode);
      end if;
      //De (evt.) regelkorting berekenen en onthouden
      if @RegelkortingApart = 1 then
        set @Bedrag = round(if @ValNummer = @@BasisValutaNummer then isnull( @TotaalRegelKorting,0 ) else ValutaOmrekenen(@ValNummer, isnull( @TotaalRegelKorting,0 ), @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@@BasisValutaNummer));
        if @Bedrag <> 0 then
          //MR 29-apr-2008 bug #27959: BtwCode meegeven
          call ZetBedragInIct( @nawgid, @OpbrGrpIsGoed, @DatumFactuurBoeking, -@Bedrag, @FkIsAbcLevering, @IctBtwCode);
        end if;
      end if;

      //call Trace('FacturerenBoekFactuur > Eind@BedragInIct = ' + string(@BasisBedrag));
    end loop IctBtwLoop;

    //einde loop opbr.groepen
  end loop LoopOpbrengstGroep;
  //sluit journaalpost af

  call factuurBoekAfrondingsverschilBoeken(@fbgid, 0, @nawgid, @fkFactuurNummer, @oms, @HoogsteOpbrGrpGid, @HoogsteOpbrGroepRksGid, @HoogsteKstpCode, @HoogsteKstdCode, @HoogsteOpbrIsGoed, @Boekdatum, @DatumFactuurBoeking, @BoekGangGid, @JpGid);

  //Boeking maken op tussenrekening, afhankelijk of dit is ingesteld bij de vaste gegevens
  if @VofBoekdatumFactuur <> 0 and (@DatumFactuurBoeking <> @Boekdatum) then
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, IsCreditBoeking, SoortBoeking, OmsJournaalRegel, JrValNummer, JrBoekdatum)
      select @JpGid, @RksGidGefactOmzet, sum(if (IsCreditBoeking = 1) then JrBasisBedrag else -JrBasisBedrag endif),  sum(if (IsCreditBoeking = 1) then JrBasisBedrag else -JrBasisBedrag endif), 0, 0, @Oms, @@BasisValutaNummer, @Boekdatum
      from tabJournaalRegel
      where JrJpGid = @JpGid and JrGid in (select tmpJrGid.JrGid from tmpJrGid);

    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrBasisBedrag, JrValutaBedrag, IsCreditBoeking, SoortBoeking, OmsJournaalRegel, JrValNummer, JrBoekdatum )
      select @JpGid, @RksGidGefactOmzet, sum(if (IsCreditBoeking = 1) then JrBasisBedrag else -JrBasisBedrag endif), sum(if (IsCreditBoeking = 1) then JrBasisBedrag else -JrBasisBedrag endif), 1, 0, @Oms, @@BasisValutaNummer, @DatumFactuurBoeking
      from tabJournaalRegel
      where JrJpGid = @JpGid and JrGid in (select tmpJrGid.JrGid from tmpJrGid);
  end if;

  //Eventueel een afrondingsverschil wegboeken
  //Totaal van journaalregels

  // B E T A L I N G
  //call Trace('FacturerenBoekFactuur > Betaling');
  if isnull(@LayoutSoort,0) = 60 and @fkgid is not null and (@fkBedragTeBetalen <> 0 or @BedragBetaald <> 0) and ( @BedragBetaald <> 0 or @VerschilAfboeken = 1 or @fkBedragTeBetalen = (if @fkBtcSoort = 2 then @fkBtcBedragInExBtw else @fkBtcBedragExBtw endif) ) then

    //OSP afboeken
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                 IsCreditBoeking, SoortBoeking, JrValNummer, JrReferentie, jrFactuurDatum, jrVervalDatum, jrBetalingskenmerk, JrBoekdatum)
      values( @JpGid, @DebRksGid, if @VerschilAfboeken = 1 or ( @fkBedragTeBetalen - @BedragBetaald - (if @fkBtcSoort = 2 then @fkBtcBedragInExBtw else @fkBtcBedragExBtw endif) = 0 ) then @FactuurTotaalInBtw else @BedragBetaald endif,
              if @ValNummer = @@BasisValutaNummer then if @VerschilAfboeken = 1 or ( @fkBedragTeBetalen - @BedragBetaald - (if @fkBtcSoort = 2 then @fkBtcBedragInExBtw else @fkBtcBedragExBtw endif) = 0 ) then @FactuurTotaalInBtw else @BedragBetaald endif else ValutaOmrekenen(@ValNummer, if @VerschilAfboeken = 1 or ( @fkBedragTeBetalen - @BedragBetaald - (if @fkBtcSoort = 2 then @fkBtcBedragInExBtw else @fkBtcBedragExBtw endif) = 0 ) then @FactuurTotaalInBtw else @BedragBetaald endif, @@BasisValutaNummer, @BjGid, @PernrFactuurboeking, 2) endif, @oms,
              1, 0, @ValNummer, @fkFactuurNummer, @fkFactuurDatum, @fkVervalDatum, @FkBetalingskenmerk, @DatumFactuurBoeking);
    set @JrGid = @@Identity;

    //Evt. kredietbeperking misschien wegboeken als hulprekening!!
    if @fkBtcSoort = 1 and @fkBedragTeBetalen - @fkBtcBedragExBtw - @BedragBetaald = 0 and @fkKredBepRksInvoer is not null AND @fkBtcBedragExBtw <> 0 then
       insert into tabHulprekening (hulprekBasisBedrag, hulprekValnummer, hulprekValutaBedrag, hulprekSoort, hulprekIsCredit, hulprekRksgid, hulprekJrGid, HulpRekKredBepDatum)
       values (if @ValNummer = @@BasisValutaNummer then @fkBtcBedragExBtw else ValutaOmrekenen(@ValNummer, @fkBtcBedragExBtw, @@BasisValutaNummer, @BjGid, @PernrFactuurboeking, 2) endif, @Valnummer, @fkBtcBedragExBtw, if @fkBtcSoort=1 then 4 else 5 endif, 0,
              ( select RksGid from tabrekeningschema where RksInvoer = @fkKredBepRksInvoer ), @JrGid, @fkKredBepDatum);
    else
      //We doen alsof er geen korting is geweest omdat die toch niet kan worden afgeboekt bij de betaling
      set @fkBtcBedragInBtw = 0;
      set @fkBtcBedragExBtw = 0;
    end if;

    //Evt. betalingskorting misschien wegboeken als hulprekening!!
    //call Trace('Betalingskorting: @fkBedragTeBetalen='+string(@fkBedragTeBetalen) + ' @fkBtcBedragInExBtw='+string(@fkBtcBedragInExBtw) + ' @BedragBetaald='+string(@BedragBetaald));
    if @fkBtcSoort = 2 and @fkBedragTeBetalen - @fkBtcBedragInExBtw - @BedragBetaald = 0 and @fkKredBepRksInvoer is not null AND @fkBtcBedragInExBtw <> 0 then
       insert into tabHulprekening (hulprekBasisBedrag, hulprekValnummer, hulprekValutaBedrag, hulprekSoort, hulprekIsCredit, hulprekRksgid, hulprekJrGid, HulpRekKredBepDatum)
       values (if @ValNummer = @@BasisValutaNummer then @fkBtcBedragInExBtw else ValutaOmrekenen(@ValNummer, @fkBtcBedragInExBtw, @@BasisValutaNummer, @BjGid, @PernrFactuurboeking, 2) endif, @Valnummer, @fkBtcBedragInExBtw, if @fkBtcSoort=1 then 4 else 5 endif, 0,
              ( select RksGid from tabrekeningschema where RksInvoer = @fkKredBepRksInvoer ), @JrGid, @fkKredBepDatum);
    else
      //We doen alsof er geen korting is geweest omdat die toch niet kan worden afgeboekt bij de betaling
      set @fkBtcBedragInBtw = 0;
      set @fkBtcBedragExBtw = 0;
    end if;



    //call Trace('FacturerenBoekFactuur > Betalingsverschil wegboeken');
    //Betalingsverschil wegboeken
    if ( @fkVerschilAfboeken = 1 ) and @fkBedragTeBetalen - @fkBtcBedragInBtw - @fkBedragBetaald <> 0 then
      select RksGid into @BetVerschilRksGid from tabRekeningSchema inner join tabDagboek on DgbBetRksGid = RksGid where DgbGid = @DgbGid;
      if @BetVerschilRksGid is not null then
        insert into tabHulprekening (hulprekBasisBedrag, hulprekValnummer, hulprekValutaBedrag, hulprekSoort, hulprekIsCredit,
                                     hulprekRksgid, hulprekJrGid)
        values (if @ValNummer = @@BasisValutaNummer then @fkBedragTeBetalen - @fkBedragBetaald - @fkBtcBedragInBtw else ValutaOmrekenen(@ValNummer, @fkBedragTeBetalen - @fkBedragBetaald - @fkBtcBedragInBtw, @@BasisValutaNummer, @BjGid, @PernrFactuurboeking, 2) endif, @Valnummer, @fkBedragTeBetalen - @fkBedragBetaald - @fkBtcBedragInBtw, 2, 0,
               @BetVerschilRksGid, @JrGid );
      end if;
    end if;

    if @VGRekeningBetalingen <> @TegenRekeningDagboek then
      //Contante betaling boeken op <rekening volgens vaste gegevens order/fact.>
      //call Trace('FacturerenBoekFactuur > Contante betaling boeken');
      insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag,  OmsJournaalRegel,
                                   IsCreditBoeking, SoortBoeking, JrValNummer, JrReferentie, JrBoekdatum)
        values( @JpGid, ( select first vofContantBoekenOpRksGid from tabVasteGegevensOrdersFactureren ), @BedragBetaald,
                if @ValNummer = @@BasisValutaNummer then @BedragBetaald else ValutaOmrekenen(@ValNummer, @BedragBetaald, @@BasisValutaNummer, @BjGid, @PernrFactuurboeking, 2) endif, @oms,
                0, 0, @ValNummer, @fkFactuurNummer, @DatumFactuurBoeking);
    end if;
  end if;

  update tabJournaalPost set JpIsIngebruik = 0 where jpGid = @JpGid;

  //In OSP bijwerken...
  if (isnull(@fkKredBepBedrag,0) <> 0 and @fkKredBepRksInvoer is not null and @fkBtcSoort in (1,2)) or @fkBtcSoort = 3 then
    // RS 23-09-09 bug 17244, autom. incasso en non-euro valuta? dan standaard factuur van maken
    if @fkBtcSoort = 3 and not exists(select 1 from tabValuta where ValNummer = @ValNummer and IsEuro = 1) then
      set @fkBtcSoort = 0;
      set @SoortFactuurOverruled = 1;
    end if;

    update tabOpenstaandePost
    set      OspSoortFactuur = @fkBtcSoort,
//           OspKredietBeperkingsBedrag = OspKredietBeperkingsBedrag + if @fkInclBtw=0 then @fkBtcBedragExBtw else @fkBtcBedragInBtw endif,
           //bet.kortingsbedrag is altijd incl. BTW, kredietbep. soms incl, soms excl.
           OspKredietBeperkingsBedrag = OspKredietBeperkingsBedrag + if (@fkInclBtw=0 and @fkBtcSoort = 1) or (@fkBtcSoort = 2 and @FkBtcKredBepKortingInclBtw = 0) then @fkBtcBedragExBtw else @fkBtcBedragInBtw endif,
           OspKredietBeperkingsDatum = @fkKredBepDatum,
           OspKredietBeperkingsRksGid = ( select RksGid from tabRekeningSchema where RksInvoer = @fkKredBepRksInvoer ),
           OspIncNawRekGid = (if @fkBtcSoort = 3 then (select first OrkIncNawRekGid from tabOrderKop join tabFactuurReferentie on orkgid = freforkgid where freffkgid = @fkgid) else null endif),
           //ACW sinterklaasfeest 2012 onderdeel #54370: datum uit de factuur lezen
           OspIncDatum = (if @fkBtcSoort = 3 then @fkIncassoDatum else null endif) // Kan zijn gewijzigd, dan dus de incassodatum NIET overnemen
    where  OspGid = ( select first JrOspGid from tabJournaalRegel where JrJpGid = @JpGid and JrOspGid is not null );

    if @fkBtcSoort = 1 then
      //Kredietbeperking tbv. factuuroverzicht onthouden
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooKredBepRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid )
      values( @BoekGangGid, -1, ( select RksGid from tabRekeningSchema where RksInvoer = @fkKredBepRksInvoer ), @frKstpCode, @frKstdCode, if @ValNummer = @@BasisValutaNummer then @fkBtcBedragExBtw else ValutaOmrekenen(@ValNummer, @fkBtcBedragExBtw, @@BasisValutaNummer, @BjGid, @PernrFactuurBoeking, 2) endif, @FbGid );
    end if;

  end if;

  // Fiattering goed zetten
  begin
    // Bepaal of de journaalregel en openstaande post standaard gefiatteerd moet worden
    declare @Gefiatteerd integer;

    set @Gefiatteerd = (if @FkBtcNummer is null then (select Contents from tabRegistry where RegKey = 'STANDAARD_GEFIATTEERD_VERKOOP') else (select BtcStandaardGefiatteerd from tabBetalingsconditie where BtcNummer = @FkBtcNummer) endif);
    update tabOpenstaandePost
    set
      OspGefiatteerd  = @Gefiatteerd,
      OspBtcNummer    = if @SoortFactuurOverruled = 0 then @FkBtcNummer else null end if,
      OspSoortFactuur = if @FkBtcSoort = 0 then 0 /* standaard factuur */ else OspSoortFactuur end if
    where
      OspRksGID = @DebRksGid and OspBjGid = @BjGid and OspFactuurNummer = @fkFactuurNummer;
  end;

  set @@OverRuleLock = 0;

  set @@ErrorTextProcedure = 'FacturerenBoekFactuur';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure FacturerenBoekProjectFactuur(
  in @fbGid           integer,
  in @fkGid           integer,
  in @fkFactuurNummer nchar(40),
  in @fkFactDebNummer nchar(10),
  in @Boekdatum       date,
  in @BjGid           integer,
  in @PerNr           integer,
  in @BoekgangGid     integer
  )
begin
  declare @Oms                    nchar(40);
  declare @nawgid                 integer;
  declare @DebRksGid              integer;
  declare @Bedrag                 numeric(15,2);

  //Lus voor facturen in factuurbatch
  declare @fkInclBtw              smallint;
  declare @ValNummer              integer;

  declare @fkKredBepBedrag        numeric(15,2);
  declare @fkKredBepRksInvoer     nchar(28);
  declare @fkKredBepDatum         date;
  declare @fkBtcSoort             smallint;    //0=normale factuur, 1=kred.bep., 2=bet.korting
  declare @fkBtcBedragExBtw       numeric(15,2);
  declare @fkBtcBedragInBtw       numeric(15,2);
  declare @fkBtcNummer            integer;
  declare @FkBtcKredBepKortingInclBtw smallint;
  declare @fkFactuurDatum         date;
  declare @fkVervalDatum          date;
  declare @fkIncassoDatum         Date;
  declare @FactuurTotaalInBtw     numeric(15,2);

  declare @HoogsteBedragOpbrGroep numeric(15,2);
  declare @HoogsteOpbrGroepRksGid integer;
  declare @HoogsteOpbrGrpGid      integer;
  declare @HoogsteOpbrIsGoed      smallint;

  //Lus voor BTW in factuur
  declare @fkBedragTeBetalen      numeric(15,2);
  declare @BedragTeBetalenExBtw   numeric(15,2);
  declare @VorigBtwCode           integer;
  declare @BtwCode                integer;
  declare @JpGid                  integer;
  declare @JrNummer               integer;
  declare @HulpRekGid             integer;

  declare @VofBoekdatumFactuur    integer;
  declare @DatumFactuurBoeking    date;
  declare @RksGidGefactOmzet      integer;

  //Direct nodig voor boeken
  declare @DgbGid                 integer;
  declare @fbrBtwBasis            numeric(15,2);
  declare @fbrBtwBedrag           numeric(15,2);
  declare @GrpSoortRksGID         integer;
  declare @OpbrNaarValNummer      integer;
  declare @BtwRekening            integer;
  declare @BtwValNummer           integer;
  declare @FkBetalingskenmerk     nchar(40);
  declare @frRegelTotaal          numeric(15,2);
  //Loop voor opbrengstgroepen
  declare @tmpProjGrpGid          integer;
  declare @curProjGrpGid          integer;
  declare @IsTermijnRegel         smallint;
  declare @ProjGrpOpbrBoekenObvGroep smallint;
  declare @ProjGrpKostprijsBoekenObvGroep smallint;
  declare @ProjGrpDekkingTarievenObvGroep smallint;
  declare @OpbrGrpGid             integer;
  declare @OpbrGrpNummer          nchar(4);
  declare @OpbrGrpIsGoed          smallint;
  declare @OpbrengstBedrag        numeric(15,2);
  declare @TotaalOpbrengst        numeric(15,2);
  declare @TotaalJr               numeric(15,2);
  declare @TotaalHulp             numeric(15,2);
  declare @Kostprijs              numeric(15,2);
  declare @TotaalKostPrijs        numeric(15,2);
  declare @VoorraadPrijs          numeric(15,2);
  declare @JrGid                  integer;
  declare @HulpBedrag             numeric(15,2);
  declare @fkBtcPerc              numeric(6,2);
  declare @IsApartLeveren         smallint;
  declare @OrkNummer              nchar(10);
  declare @InProjectGroep         smallint;
  declare @IctIsAbcLevering       integer;
  // ProjectVelden
  declare @PfvkGid                integer;
  declare @pbfBoekGangNummer      integer;
  declare @pbfJpNummer            integer;
  declare @pbfJrNummer            integer;
  declare @pbfRksInvoer           nchar(28);
  declare @pbfIsCredit            smallint;
  declare @pbfBedrag              numeric(15,2);
  declare @pbfBjCode              nchar(10);
  declare @pbfDgbCode             nchar(10);

  //ICP
  declare @VorigeIctBtwCode       integer;
  declare @IctBtwCode             integer;
  declare @BasisBedrag            numeric(15,2);

  //Onderhanden werk referentie
  declare @ReferentieVerplichtOHW smallint; //MR 20-aug-2010 bug #32672: referentie ook bij ohw
  declare @ReferentieOHW          nchar(40); // In principe de projectcode of leeg. Is om JrReferentie te vullen bij boekingen

  declare @SoortFactuurOverruled smallint = 0;

  declare local temporary table tmpRegelSoort
   (Rsoort integer null) on commit preserve rows;

  // tbv. boeken in verschillende periodes
  declare local temporary table tmpJrGid
   (JrGid integer not null) on commit preserve rows;

  //TG 17-09-2009, 12:56u: oplossing voor incident #i03401; geen groupby op PfvrMutSoort, omdat er dan teveel regels komen waardoor boekingen dubbel gedaan
  //worden bij een combinatieproject van termijnen en regieonderdelen. In plaats daarvan een boolean-veldje (isTermijnRegel) gebruiken.
  declare cursor_OpbrengstProjectGroep dynamic scroll cursor for
    select if PfvrMutSoort = 99 then 1 else 0 endif IsTermijnRegel, ProjGrpGid, OpbrGrpGid, OpbrGrpNummer, ProjGrpOpbrBoekenObvGroep, ProjGrpKostprijsBoekenObvGroep, IsOpbrGrpGoederen
    from   tabFactuurRegel
           inner join tabFactuurreferentie on (frefGid = frFrefGid)
           inner join tabfactuurkop on (fkGid = frefFkGid)
           inner join tabProjectFactuurVoorstelKop on PfvkGid = frefPfvkGid
           inner join tabProjectFactuurVoorstelRegel on PfvrPfvkGid = PfvkGid
           inner join tabProject on PfvkProjGid = ProjGid
           inner join tabProjectGroep on ProjProjGrpGid = ProjGrpGid
           inner join tabProjectFactuurVoorstelRealisatie on  pfvlFvrGid = pfvrGid
           left outer join tabProjectBoekingsRegel on PfvlPbrGid = PbrGid
           left outer join tabArtikel on PbrArtGid = ArtGid
           left outer join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGId)
    where  (fkGid = @FkGid)
    group by IsTermijnRegel, ProjGrpGid, OpbrGrpGid, OpbrGrpNummer, ProjGrpOpbrBoekenObvGroep, ProjGrpKostprijsBoekenObvGroep,IsOpbrGrpGoederen
    order by OpbrGrpNummer
  for read only;

  set @@ErrorTextProcedure = 'FacturerenBoekProjectFactuur > ';
  //call TraceBegin(@@ErrorTextProcedure + '@fbGid = ' + string(@fbGid) + ', @fkGid = ' + string(@fkGid) + ', @fkFactuurNummer = ' + string(@fkFactuurNummer));

  //Eerst dagboek tbv. factureren opvragen
  select first ProjVastFacturenDgbGid into @DgbGid from tabProjectVastegegevens;

  //Regelsoorten apart verwerken ivm. boeking op de tussenrek. (voor artikelen) resp. opbrengst (tarieven)
  insert into tmpRegelSoort(Rsoort) values(1); //Regelsoort 1 = tarief
  insert into tmpRegelSoort(Rsoort) values(2); //Regelsoort 2 = artikel

  set @InProjectGroep  = 0;
  set @TotaalOpbrengst = 0;
  set @TotaalKostPrijs = 0;

  //NawGid opzoeken tbv. ICT en omzetten
  select NawGid into @nawgid
  from   tabNawFile inner join tabFileOfNaw on (fonGid = NawFilFonGid and FonId = 'D') inner join tabNaw on (NawGid = NawFilNawGid)
  where  NawFilNummer = @fkFactDebNummer;

  //Factuurgegevens opzoeken
  select fkIsInclBtw, (select RksGid from tabrekeningschema where RksInvoer = fkFactDebNummer), fkValNummer, fkFactuurDatum,  fkVervalDatum, fkFactTotInBtw,  fkBtcBedrag,      fkBtcRksInvoer,      fkBtcDatum,      fkBtcSoort, fkBtcNummer, fkBtcBedrag, fkBtcBedragInBtw, fkBtcPerc, FkBtcKredBepKortingInclBtw, FkBetalingskenmerk, fkIncassoDatum
  into   @fkInclBtw,  @DebRksGid, @ValNummer, @fkFactuurDatum, @fkVervalDatum, @FactuurTotaalInBtw, @fkKredBepBedrag, @fkKredBepRksInvoer, @fkKredBepDatum, @fkBtcSoort, @fkBtcNummer, @fkBtcBedragExBtw, @fkBtcBedragInBtw, @fkBtcPerc, @FkBtcKredBepKortingInclBtw, @FkBetalingskenmerk, @fkIncassoDatum
  from   tabFactuurkop
  where  fkgid = @fkgid;

  // Moet de factuurboeking via een tussenrekening lopen, waardoor omzet in een andere periode (datum) geboekt kan worden
  select VofBoekdatumFactuur,
         if VofBoekdatumFactuur = 0 then @BoekDatum else @fkFactuurDatum endif,
         if @BoekDatum < @fkFactuurDatum then VofRksGIDAchterafGefactOmzet else VofRksGIDVooruitGefactOmzet endif VofRksGid
  into   @VofBoekdatumFactuur, @DatumFactuurBoeking, @RksGidGefactOmzet
  from   tabVasteGegevensOrdersFactureren;

  // maak journaalpost aan
  //MR 20-aug-2010 bug #32672: lees ook referentie even in.
  select _A('Project %1! voorstelnr %2!', ProjCode, String(pfvkVoorstelNr)) , ProjCode, FrefPfvkGid into @Oms, @ReferentieOHW, @PfvkGid
  from tabFactuurKop
  inner join tabFactuurReferentie on freffkgid = fkgid
  inner join tabProjectFactuurVoorstelKop on frefPfvkGid = PfvkGid
  inner join tabProject on PfvkProjGid = ProjGid
  where FkGid = @FkGid;

  insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum)
  select @BoekGangGid, 1, @DgbGid, @fkFactuurNummer, @Oms, @DatumFactuurBoeking;
  set @JpGid = @@Identity;

  // Journaalpost in de factuur onthouden
  update tabFactuurKop set FkJpGid = @JpGid where FkGid = @FkGid;

  select BoekgangNummer,     JpNummer,      Code,       DgbCode
    into @pbfBoekGangNummer, @pbfJpNummer, @pbfBjCode, @pbfDgbCode
    from tabJournaalPost
         inner join tabBoekingsGang on JpBoekgangGid = BoekgangGid
         inner join tabBoekjaar on BjGid = JpBjGid
         inner join tabDagBoek on JpDgbGid = DgbGid
   where JpGid = @JpGid;

  //Maak journaalr. voor de debiteur (met btw-rek. als hulprek.)
  //(debiteur xxx      <bedrag incl.btw>; hulprek.: btw; bedrag: -btwbedrag)
  set @fkBedragTeBetalen    =  0;
  set @BedragTeBetalenExBtw =  0;
  set @VorigBtwCode         = -1;

  BtwLoop:
  Loop
    set @BtwCode = null;
    select first fbrBtwCode, fbrBtwBasis,  fbrBtwBedrag
    into         @BtwCode,   @fbrBtwBasis, @fbrBtwBedrag
    from     tabFactuurBtwRegel
    where    fbrFkGid = @FkGid and fbrBtwCode > @VorigBtwCode
    order by fbrBtwCode;
    if @BtwCode is null and @VorigBtwCode <> -1 then
      // Als de BTWcode niet meer is gevonden EN we zijn tenminste 1x de lus in geweest, dan afsluiten
      leave BtwLoop;
    end if;
    set @VorigBtwCode = isnull(@BtwCode, -2);
    set @fbrBtwBasis  = isnull(@fbrBtwBasis , 0);
    set @fbrBtwBedrag = isnull(@fbrBtwBedrag, 0);

    //Factuurbedrag onthouden
    set @fkBedragTeBetalen    = @fkBedragTeBetalen + @fbrBtwBasis + @fbrBtwBedrag;
    set @BedragTeBetalenExBtw = @BedragTeBetalenExBtw + @fbrBtwBasis;

    //call Trace('----------------->@fkBedragTeBetalen    ='+string(@fkBedragTeBetalen));
    //call Trace('----------------->@BedragTeBetalenExBtw ='+string(@BedragTeBetalenExBtw));


    //*** Journaalregel per BTW van de debiteur ***

    set @bedrag      = round(@fbrBtwBasis + @fbrBtwBedrag, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@valnummer));
    set @BasisBedrag = if @ValNummer = @@BasisValutaNummer then @bedrag else ValutaOmrekenen(@ValNummer, @bedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif;

    // Onthouden in journaalregel
    insert into tabJournaalRegel
           (JrJpGid, JrRksGid,   JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel, IsCreditBoeking, SoortBoeking, JrValNummer, jrReferentie,     JrBoekdatum,          jrFactuurDatum,  jrVervalDatum,  JrBetalingsKenmerk)
    values (@JpGid,  @DebRksGid, @bedrag,        @BasisBedrag,  @oms,             0,               0,            @ValNummer,  @fkFactuurNummer, @DatumFactuurBoeking, @fkFactuurDatum, @fkVervalDatum, @FkBetalingskenmerk);
    select JrGid, JrNummer into @JrGid, @JrNummer from tabJournaalregel where JrGid = @@Identity;

    // Onthouden in projectfactuurboeking
    insert into tabProjectBoekingFactuur
          (pbfPfvkGid,  pbfBoekGangNummer,  pbfJpNummer,  pbfJrNummer,  pbfRksInvoer,  pbfIsCredit,  pbfBedrag,    pbfBjCode,  pbfDgbCode )
    values(@PfvkGid,    @pbfBoekGangNummer, @pbfJpNummer, @JrNummer,    @DebRksGid,    0 /*Debet*/,  @BasisBedrag, @pbfBjCode, @pbfDgbCode);

    //Onthouden in factuuroverzicht (valutabedragen)
    insert into tabFactuurOverzichtValuta
           ( fovBoekgangGid, fovValNummer, fovBedragValuta, fovBedragBasis, fovFbGid )
    values ( @BoekGangGid,   @ValNummer,   @bedrag,         @BasisBedrag,   @FbGid );


    //*** BTW boeken in val.van BTW-rek. ***

    if @BtwCode is not null then
      begin
        // ACW 09-01-2017 #50649: Verkeerde veld werd in tabFactuurOverzichtBtw gezet;
        //                        nu verbeterde namen voor de variabelen gedefinieerd
        declare @BtwBedragInValutaVanBtwRekening numeric(15,3);
        declare @BtwBedragInBasisValuta numeric(15,3);

        select BtwRksGid, RksValNummer into @BtwRekening, @BtwValNummer from tabBtw inner join tabRekeningSchema on (RksGid = BtwRksGid) where BtwCode = @BtwCode;
        set @BtwBedragInValutaVanBtwRekening  = round(if @ValNummer = @BtwValNummer then @fbrBtwBedrag else ValutaOmrekenen(@ValNummer, @fbrBtwBedrag, @BtwValNummer, @BjGid, @Pernr, 2) endif, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@BtwValNummer));
        set @BtwBedragInBasisValuta           =       if @BtwValNummer = @@BasisValutaNummer then @BtwBedragInValutaVanBtwRekening else ValutaOmrekenen(@BtwValNummer, @BtwBedragInValutaVanBtwRekening, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif;
        // Onthouden in journaal hulprekening
        insert into tabHulprekening (hulprekBasisBedrag,      hulprekValnummer, hulprekValutaBedrag,              hulprekSoort, hulprekIsCredit, hulprekRksgid, HulprekBtwCode, hulprekJrGid)
                             values (@BtwBedragInBasisValuta, @BtwValNummer,    @BtwBedragInValutaVanBtwRekening, 1,            1,               @BtwRekening,  @BtwCode,       @JrGid);
        set @HulpRekGid = @@Identity;

        // Onthouden in projectfactuurboeking
        insert into tabProjectBoekingFactuur
               (pbfPfvkGid, pbfBoekGangNummer,  pbfJpNummer,  pbfJrNummer,  pbfRksInvoer,  pbfIsCredit, pbfBedrag,               pbfBjCode,  pbfDgbCode )
        values (@PfvkGid,   @pbfBoekGangNummer, @pbfJpNummer, @JrNummer,    @BtwRekening,  1,           @BtwBedragInBasisValuta, @pbfBjCode, @pbfDgbCode);

        // Onthouden in factuuroverzicht (Btw-bedrag)
        insert into tabFactuurOverzichtBtw( fobBoekgangGid, fobBtwCode, fobBedrag, fobFbGid )
        values ( @BoekGangGid, @BtwCode, @BtwBedragInBasisValuta, @FbGid );
      end;
    end if;

  end loop BtwLoop;

  //Kredietbeperking als aparte boeking maken
  if isnull(@fkKredBepBedrag,0) <> 0 and @fkKredBepRksInvoer is not null and @fkBtcSoort = 1 then
    //call Trace('Kred.beperking;'+string(@fkKredBepBedrag)+' basis='+string(ValutaOmrekenen(@ValNummer, @fkKredBepBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2)));
    set @BasisBedrag = if @ValNummer = @@BasisValutaNummer then @fkKredBepBedrag else ValutaOmrekenen(@ValNummer, @fkKredBepBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif;
    insert into tabJournaalRegel
           (JrJpGid, JrRksGid, JrValutaBedrag,
            JrBasisBedrag, OmsJournaalRegel, IsCreditBoeking, SoortBoeking, JrValNummer, jrFactuurDatum, jrVervalDatum, jrBoekdatum )
    values (@JpGid, ( select RksGid from tabRekeningSchema where RksInvoer = @fkKredBepRksInvoer ), round(@fkKredBepBedrag, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@valnummer)),
            @BasisBedrag, @oms, 1, 0, @ValNummer, @fkFactuurDatum, @fkVervalDatum, @DatumFactuurBoeking);
    select JrGid, JrNummer into @JrGid, @JrNummer from tabJournaalregel where JrGid = @@Identity;

    insert into tabProjectBoekingFactuur
           ( pbfPfvkGid, pbfBoekGangNummer,  pbfJpNummer,  pbfJrNummer,  pbfRksInvoer,        pbfIsCredit,  pbfBedrag,    pbfBjCode,  pbfDgbCode )
    values ( @PfvkGid,   @pbfBoekGangNummer, @pbfJpNummer, @JrNummer,    @fkKredBepRksInvoer, 1,            @BasisBedrag, @pbfBjCode, @pbfDgbCode);

  end if;

  //TODO: NOG NIET GEIMPLEMENTEERD:
  //Loop extra orderregels die rekeningnummer hebben met vast bedrag
  //maak journaalregel aan: rekening = uit orderregel; bedrag = regelbedrag
  //einde loop extra orderregels

  //Loop opbrengstgroepen in de factuur
  set @HoogsteBedragOpbrGroep = -1;
  open cursor_OpbrengstProjectGroep;
  LoopOpbrengstProjectGroep:
  loop
    Fetch next cursor_OpbrengstProjectGroep into @IsTermijnRegel, @tmpProjGrpGid, @OpbrGrpGid, @OpbrGrpNummer, @ProjGrpOpbrBoekenObvGroep, @ProjGrpKostprijsBoekenObvGroep,@OpbrGrpIsGoed;
    if @InProjectGroep = 1 then
      leave LoopOpbrengstProjectGroep;
    end if;
    if sqlstate = '02000' then  // Alle opbr.groepen gehad, dan nu als laatst de PROJECTgroep
      set @InProjectGroep = 1;
    else
      set @curProjGrpGid = @tmpProjGrpGid;
    end if;
    //call Trace('OpbrGrp lus; @OpbrGrpNummer='+string(@OpbrGrpNummer)+', @OpbrGrpGid='+string(@OpbrGrpGid)+', @OpbrGrpIsGoed='+string(@OpbrGrpIsGoed));

    //Opbrengstbedragen berekenen, maar gesplitst naar artikel en tarief
    call FacturerenBerekenProjectOpbrengst(@fkGid, @fkInclBtw, if @InProjectGroep = 1 then @curProjGrpGid else null endif, @OpbrGrpGid, @ProjGrpOpbrBoekenObvGroep, @ProjGrpKostprijsBoekenObvGroep, @OpbrengstBedrag, @Kostprijs);

    //call Trace(' Opbrengst='+string(@OpbrengstBedrag) + ', Kpostprijs='+string(@Kostprijs));


    // Totaal van opbrengst optellen, dit wordt als Gefactureerde projecttermijnen geboekt
    set @TotaalOpbrengst = @TotaalOpbrengst + IsNull(@OpbrengstBedrag,0);
    // Totaal van kostprijzen optellen, dit wordt als OHW geboekt
    set @TotaalKostPrijs = @TotaalKostPrijs + IsNull(@Kostprijs,0);

    //call Trace(' TotaalOpbrengst='+string(@TotaalOpbrengst) + ', TotaalKpostprijs='+string(@TotaalKostPrijs));

    if @InProjectGroep = 1 then
      call FacturerenMaakRekeningObvProjectGroep(@curProjGrpGid, 150, @GrpSoortRksGID);   // 150 Opbrengst Projecten obv Projectgroep
    else
      call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 180, @GrpSoortRksGID); // 180 Opbrengst Projecten obv Opbrengstgroep
    end if;

    if @OpbrengstBedrag <> 0 then
      //Boeken en onthouden als het bedrag<>0 is
      //call Trace('Opbrengst; Bedrag='+string(@OpbrengstBedrag));
      insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                   IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum )
        values( @JpGid, @GrpSoortRksGID,  @OpbrengstBedrag, @OpbrengstBedrag, @oms, 1, 0, @@BasisValutaNummer, @Boekdatum);
      set @JrGid = @@Identity;

      //Onthouden ivm boeken op verschillende datums
      insert into tmpJrGid(JrGid) select @JrGid;

      select BoekgangNummer,     JpNummer,     JrNummer,     JrRksInvoer,   IsCreditBoeking, JrBasisBedrag, Code,       DgbCode into
             @pbfBoekGangNummer, @pbfJpNummer, @pbfJrNummer, @pbfRksInvoer, @pbfIsCredit,    @pbfBedrag,   @pbfBjCode, @pbfDgbCode
       from tabJournaalRegel inner join tabJournaalPost on JrJpGid = JpGid inner join tabBoekingsGang on JpBoekgangGid = BoekgangGid  inner join tabBoekjaar on BjGid = JpBjGid inner join tabDagBoek on JpDgbGid = DgbGid where JrGid = @JrGid;

      insert into tabProjectBoekingFactuur ( pbfPfvkGid,  pbfBoekGangNummer,  pbfJpNummer,  pbfJrNummer,  pbfRksInvoer,  pbfIsCredit,  pbfBedrag,  pbfBjCode,  pbfDgbCode )
         values                            ( @PfvkGid,   @pbfBoekGangNummer, @pbfJpNummer, @pbfJrNummer, @pbfRksInvoer, @pbfIsCredit, @pbfBedrag, @pbfBjCode, @pbfDgbCode);

      //Factuuroverzicht onthouden: Opbrengst
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooProjGrpGid, fooRksGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 0, @OpbrGrpGid, if @InProjectGroep = 1 then @curProjGrpGid else null endif, @GrpSoortRksGID, @OpbrengstBedrag, @FbGid );
    end if;

    //Hoogste opbrengst onthouden
    if abs(@OpbrengstBedrag)>@HoogsteBedragOpbrGroep then
      set @HoogsteBedragOpbrGroep = abs(@OpbrengstBedrag);
      set @HoogsteOpbrGroepRksGid = @GrpSoortRksGID;
      set @HoogsteOpbrGrpGid      = @OpbrGrpGid;
      set @HoogsteOpbrIsGoed      = @OpbrGrpIsGoed;
    end if;

    //call Trace('Kostprijs='+string(@kostprijs)+', @VoorraadPrijs='+string(@VoorraadPrijs));

    //Boeken: KOSTPRIJS & OnderHanden Werken
    if isnull(@Kostprijs,0) <> 0 then

      // KOSTPRIJS
      if @InProjectGroep = 1 then
        call FacturerenMaakRekeningObvProjectGroep(@curProjGrpGid, 160, @GrpSoortRksGID);   // 160 Kosten Projecten obv Projectgroep
      else
        call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 190, @GrpSoortRksGID); // 190 Kosten Projecten obv Opbrengstgroep
      end if;
      //call Trace('Kosten; bedrag='+string(@Kostprijs));
      insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                   IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum )
        values( @JpGid, @GrpSoortRksGID, @Kostprijs, @Kostprijs, @oms, 0, 0, @@BasisValutaNummer, @Boekdatum);
      set @JrGid = @@Identity;

      select BoekgangNummer,     JpNummer,     JrNummer,     JrRksInvoer,   IsCreditBoeking, JrBasisBedrag, Code,       DgbCode into
             @pbfBoekGangNummer, @pbfJpNummer, @pbfJrNummer, @pbfRksInvoer, @pbfIsCredit,    @pbfBedrag,   @pbfBjCode, @pbfDgbCode
       from tabJournaalRegel inner join tabJournaalPost on JrJpGid = JpGid inner join tabBoekingsGang on JpBoekgangGid = BoekgangGid  inner join tabBoekjaar on BjGid = JpBjGid inner join tabDagBoek on JpDgbGid = DgbGid where JrGid = @JrGid;

      insert into tabProjectBoekingFactuur ( pbfPfvkGid,  pbfBoekGangNummer,  pbfJpNummer,  pbfJrNummer,  pbfRksInvoer,  pbfIsCredit,  pbfBedrag,  pbfBjCode,  pbfDgbCode )
         values                            ( @PfvkGid,   @pbfBoekGangNummer, @pbfJpNummer, @pbfJrNummer, @pbfRksInvoer, @pbfIsCredit, @pbfBedrag, @pbfBjCode, @pbfDgbCode);

      //Factuuroverzicht onthouden: Kostprijs
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooProjGrpGid, fooRksGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 1 , @OpbrGrpGid, if @InProjectGroep = 1 then @curProjGrpGid else null endif, @GrpSoortRksGID, isnull(@Kostprijs,0), @FbGid );
    end if;

    // GEFACTUREERDE PROJECTTERMIJNEN
    if @InProjectGroep = 0 then
      if (@IsTermijnRegel = 1) then
        call FacturerenMaakRekeningObvProjectGroep(@curProjGrpGid, 140, @GrpSoortRksGID);  // 140 Gefactureerde projecttermijnen
        //call Trace('Gefactureerde termijnen; bedrag='+string(@BedragTeBetalenExBtw));
        //PG/TG 30-07-2009: bij termijnen werd altijd factuurtotaal ex btw geboekt op gefactureerde projecttermijnen.
        //                  Omdat regie- en termijnprojecten nu samengevoegd zijn klopt(e) dat niet meer. Nu voortaan factuurregeltotaal van termijnen gebruiken (is de som van de gefactureerde termijnen).
        select
          sum(frRegelTotaal) into @frRegelTotaal
        from
          tabFactuurRegel
          inner join tabFactuurReferentie on (frefGid = frFrefGid)
          inner join tabfactuurKop on (fkGid = frefFkGid)
          inner join tabProjectFactuurVoorstelRegel on (PfvrGid = FrpfvrGid)
        where FkGid = @FkGid
          and PfvrMutSoort = 99;

        insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                     IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum )
        values( @JpGid, @GrpSoortRksGID,
                if @valNummer = @@BasisvalutaNummer then @frRegelTotaal else ValutaOmrekenen(@ValNummer, @frRegelTotaal, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif,
                if @valNummer = @@BasisvalutaNummer then @frRegelTotaal else ValutaOmrekenen(@ValNummer, @frRegelTotaal, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif,
                @oms, 1, 0, @@BasisValutaNummer, @Boekdatum);
        set @JrGid = @@Identity;

        //Onthouden ivm boeken op verschillende datums
        insert into tmpJrGid(JrGid) select @JrGid;


        select BoekgangNummer,     JpNummer,     JrNummer,     JrRksInvoer,   IsCreditBoeking, JrBasisBedrag, Code,       DgbCode into
               @pbfBoekGangNummer, @pbfJpNummer, @pbfJrNummer, @pbfRksInvoer, @pbfIsCredit,    @pbfBedrag,   @pbfBjCode, @pbfDgbCode
         from tabJournaalRegel inner join tabJournaalPost on JrJpGid = JpGid inner join tabBoekingsGang on JpBoekgangGid = BoekgangGid  inner join tabBoekjaar on BjGid = JpBjGid inner join tabDagBoek on JpDgbGid = DgbGid where JrGid = @JrGid;

        insert into tabProjectBoekingFactuur ( pbfPfvkGid,  pbfBoekGangNummer,  pbfJpNummer,  pbfJrNummer,  pbfRksInvoer,  pbfIsCredit,  pbfBedrag,  pbfBjCode,  pbfDgbCode )
           values                            ( @PfvkGid,   @pbfBoekGangNummer, @pbfJpNummer, @pbfJrNummer, @pbfRksInvoer, @pbfIsCredit, @pbfBedrag, @pbfBjCode, @pbfDgbCode);

        //MR 13-okt-2011 bug #33839: Bedrag was niet goed voor het overzicht
        //Factuuroverzicht onthouden: Kostprijs
        insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooProjGrpGid, fooRksGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 8 , @OpbrGrpGid, @curProjGrpGid, @GrpSoortRksGID, @frRegelTotaal, @FbGid );
      end if;
    end if;

    // ONDERHANDEN WERK
    if @InProjectGroep = 1 then
      if @TotaalKostprijs <> 0 then
        call FacturerenMaakRekeningObvProjectGroep(@curProjGrpGid, 130, @GrpSoortRksGID);// 130 Onderhanden werk

        //MR 20-aug-2010 bug #32672: Referentie vullen.
        select ReferentieVerplicht into @ReferentieVerplichtOHW from tabRekeningschema where RksGid = @GrpSoortRksGID;
        if (@ReferentieVerplichtOHW = 0) then set @ReferentieOHW = '' end if;

        //call Trace('Onderhanden werk; bedrag='+string(@TotaalKostPrijs));
        insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                     IsCreditBoeking, SoortBoeking, JrValNummer,JrReferentie, JrBoekdatum )
        values( @JpGid, @GrpSoortRksGID, @TotaalKostPrijs, @TotaalKostPrijs, @oms, 1, 0, @@BasisValutaNummer, @ReferentieOHW, @Boekdatum);
        set @JrGid = @@Identity;

        select BoekgangNummer,     JpNummer,     JrNummer,     JrRksInvoer,   IsCreditBoeking, JrBasisBedrag, Code,       DgbCode into
               @pbfBoekGangNummer, @pbfJpNummer, @pbfJrNummer, @pbfRksInvoer, @pbfIsCredit,    @pbfBedrag,   @pbfBjCode, @pbfDgbCode
         from tabJournaalRegel inner join tabJournaalPost on JrJpGid = JpGid inner join tabBoekingsGang on JpBoekgangGid = BoekgangGid  inner join tabBoekjaar on BjGid = JpBjGid inner join tabDagBoek on JpDgbGid = DgbGid where JrGid = @JrGid;

        insert into tabProjectBoekingFactuur ( pbfPfvkGid,  pbfBoekGangNummer,  pbfJpNummer,  pbfJrNummer,  pbfRksInvoer,  pbfIsCredit,  pbfBedrag,  pbfBjCode,  pbfDgbCode )
           values                            ( @PfvkGid,   @pbfBoekGangNummer, @pbfJpNummer, @pbfJrNummer, @pbfRksInvoer, @pbfIsCredit, @pbfBedrag, @pbfBjCode, @pbfDgbCode);

        //Factuuroverzicht onthouden: Kostprijs
        insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooProjGrpGid, fooRksGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 7 , @OpbrGrpGid, if @InProjectGroep = 1 then @curProjGrpGid else null endif, @GrpSoortRksGID, isnull(@TotaalKostPrijs,0), @FbGid );
      end if;
    end if;

    //MR 01-nov-2011 bug #33899: Vul de ICP voor projectfacturen
    set @VorigeIctBtwCode      = -1;
    IctBtwLoop:
    Loop
      set @IctBtwCode = null;
      select first fbrBtwCode into @IctBtwCode
        from     tabFactuurBtwRegel
        where    fbrFkGid = @FkGid and fbrBtwCode > @VorigeIctBtwCode
        order by fbrBtwCode;

      if @IctBtwCode is null then
        leave IctBtwLoop;
      end if;

      set @VorigeIctBtwCode = @IctBtwCode;

      //call Trace('@BedraginIct='+string(@IctBtwCode));

      call FacturerenBerekenProjectOpbrengst(@fkGid, @fkInclBtw, if @InProjectGroep = 1 then @curProjGrpGid else null endif, @OpbrGrpGid, @ProjGrpOpbrBoekenObvGroep, @ProjGrpKostprijsBoekenObvGroep, @OpbrengstBedrag, @Kostprijs);

      set @BasisBedrag = ValutaOmrekenen(@ValNummer, isnull(@OpbrengstBedrag,0 ), @@BasisValutaNummer, @BjGid, @Pernr, 2);

      if @BasisBedrag <> 0 then
        call ZetBedragInIct( @nawgid, @OpbrGrpIsGoed, @DatumFactuurBoeking, @BasisBedrag*(if @fkBtcSoort=1 then (100+@fkBtcPerc)/100 else 1 endif), 0 /*is GEEN abc-levering*/, @IctBtwCode);
      end if;
      //call Trace('eind@BedragInIct='+string(@BasisBedrag));
    end loop IctBtwLoop;

  //Einde loop opbr.groepen
  end loop LoopOpbrengstProjectGroep;
  //Sluit journaalpost af

  call factuurBoekAfrondingsverschilBoeken(@fbgid, 1, @nawgid, @fkFactuurNummer, @oms, @HoogsteOpbrGrpGid, @HoogsteOpbrGroepRksGid, '', '', @HoogsteOpbrIsGoed, @Boekdatum, @Boekdatum, @BoekGangGid, @JpGid);


  //Boeking maken op tussenrekening, afhankelijk of dit is ingesteld bij de vaste gegevens
  if @VofBoekdatumFactuur <> 0 and (@DatumFactuurBoeking <> @Boekdatum) then
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, IsCreditBoeking, SoortBoeking, OmsJournaalRegel, JrValNummer, JrBoekdatum)
      select @JpGid, @RksGidGefactOmzet, sum(if (IsCreditBoeking = 1) then JrBasisBedrag else -JrBasisBedrag endif),  sum(if (IsCreditBoeking = 1) then JrBasisBedrag else -JrBasisBedrag endif), 0, 0, @Oms, @@BasisValutaNummer, @Boekdatum
      from tabJournaalRegel
      where JrJpGid = @JpGid and JrGid in (select tmpJrGid.JrGid from tmpJrGid);

    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrBasisBedrag, JrValutaBedrag, IsCreditBoeking, SoortBoeking, OmsJournaalRegel, JrValNummer, JrBoekdatum )
      select @JpGid, @RksGidGefactOmzet, sum(if (IsCreditBoeking = 1) then JrBasisBedrag else -JrBasisBedrag endif), sum(if (IsCreditBoeking = 1) then JrBasisBedrag else -JrBasisBedrag endif), 1, 0, @Oms, @@BasisValutaNummer, @DatumFactuurBoeking
      from tabJournaalRegel
      where JrJpGid = @JpGid and JrGid in (select tmpJrGid.JrGid from tmpJrGid);
  end if;



  //TG 31-07-2006: Aangepast op aanraden van RS nav bug #21769.
  //In OSP bijwerken...
  if (isnull(@fkKredBepBedrag,0) <> 0 and @fkKredBepRksInvoer is not null and @fkBtcSoort in (1,2)) or @fkBtcSoort = 3 then
    // RS 23-09-09 bug 17244, autom. incasso en non-euro valuta? dan standaard factuur van maken
    if @fkBtcSoort = 3 and not exists(select 1 from tabValuta where ValNummer = @ValNummer and IsEuro = 1) then
      set @fkBtcSoort = 0;
      set @SoortFactuurOverruled = 1;
    end if;

    update tabOpenstaandePost
    set    OspSoortFactuur = @fkBtcSoort,
           //bet.kortingsbedrag is altijd incl. BTW, kredietbep. soms incl, soms excl.
           OspKredietBeperkingsBedrag = OspKredietBeperkingsBedrag + if (@fkInclBtw=0 and @fkBtcSoort = 1) or (@fkBtcSoort = 2 and @FkBtcKredBepKortingInclBtw = 0) then @fkBtcBedragExBtw else @fkBtcBedragInBtw endif,
           OspKredietBeperkingsDatum = @fkKredBepDatum,
           OspKredietBeperkingsRksGid = ( select RksGid from tabRekeningSchema where RksInvoer = @fkKredBepRksInvoer ),
           OspIncNawRekGid = (if @fkBtcSoort = 3 then (select first OrkIncNawRekGid from tabOrderKop join tabFactuurReferentie on orkgid = freforkgid where freffkgid = @fkgid) else null endif),
           //ACW sinterklaasfeest 2012 onderdeel #54370: datum uit de factuur lezen
           OspIncDatum = (if @fkBtcSoort = 3 then @fkIncassoDatum else null endif)
    where  OspGid = ( select first JrOspGid from tabJournaalRegel where JrJpGid = @JpGid and JrOspGid is not null );

    if @fkBtcSoort = 1 then
      //Kredietbeperking tbv. factuuroverzicht onthouden
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooKredBepRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid )
      values( @BoekGangGid, -1, ( select RksGid from tabRekeningSchema where RksInvoer = @fkKredBepRksInvoer ), '', '', ValutaOmrekenen(@ValNummer, @fkBtcBedragExBtw, @@BasisValutaNummer, @BjGid, @Pernr, 2), @FbGid );
    end if;
  end if;

  // DG 29-10-2007: Aangepast i.o.m. PG en RS  n.a.v. bug #27050
  // Vul boekdatum in factuurvoorstelkop
  update tabProjectFactuurVoorstelKop
  set PfvkBoekDatum = @BoekDatum
  where pfvkGid = @PfvkGid;

  // Fiattering goed zetten
  begin
    // Bepaal of de journaalregel en openstaande post standaard gefiatteerd moet worden
    declare @Gefiatteerd integer;

    set @Gefiatteerd = (if @FkBtcNummer is null then (select Contents from tabRegistry where RegKey = 'STANDAARD_GEFIATTEERD_VERKOOP') else (select BtcStandaardGefiatteerd from tabBetalingsconditie where BtcNummer = @FkBtcNummer) endif);
    update tabOpenstaandePost
    set
      OspGefiatteerd  = @Gefiatteerd,
      OspBtcNummer    = if @SoortFactuurOverruled = 0 then @FkBtcNummer else null end if,
      OspSoortFactuur = if @FkBtcSoort = 0 then 0 /* standaard factuur */ else OspSoortFactuur end if
    where
      OspRksGID = @DebRksGid and OspBjGid = @BjGid and OspFactuurNummer = @fkFactuurNummer;
  end;

  //call TraceEind('FacturerenBoekProjectFactuur');
end;




//$Workfile: FacturerenCheckMagazijnVoorraad.sp $ $Revision: 4 $ $Modtime: 27-02-08 13:37 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenCheckMagazijnVoorraad') then
  drop function FacturerenCheckMagazijnVoorraad;
end if;

create procedure FacturerenCheckMagazijnVoorraad(in @fbGid integer, in @SoortFact smallint)
begin
  //@SoortFact:
  //  0 = facturering Batch
  //  1 = facturering direct
  //  2 = orderbevestiging (dus orders niet samenvoegen en ook geen factuurnummer aanmaken)
  //  3 = Pakbon (let op: dit betekent een levering!!!)
  //  4 = Proforma

  declare @OrkGid integer;

  set @@ErrorTextProcedure = 'FacturerenCheckMagazijnVoorraad > @fbGid='+string(@fbGid)+', @SoortFact='+string(@SoortFact);
   //call TraceBegin(@@ErrorTextProcedure);

  if @SoortFact = 3 and (select IsModuleActive('vr')) <> 0 and (select first vofLevNegatieveMagVoorraad from tabVasteGegevensOrdersFactureren) = 0 then
    //Beperking alleen voor het leveren *EN* als de optie 'voorraad' geactiveerd is EN negatieve mag.voorraad niet is toegestaan
    // Eerst partijloos; vergelijken met tabArtikelMagazijn!
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
      // Artikelen ZONDER partijen
      select distinct @fbGid, tfoTeFactOrkGid, 20, 1 //Magazijnvoorraad niet toereikend
      from
        tabTeFacturerenOrders
        inner join tabOrderRegel on (OrrOrkGid = tfoTeFactOrkGid)
        inner join tabOrderRegelLocatie on (OrlOrrGid = OrrGid)
        inner join tabArtikel on ArtGid = OrrArtGid
        inner join ( // Combinatie van Art/Magazijn in de leverbatch waarvoor de magazijnvoorraad kleiner is dan de te leveren voorraad
                     select
                       OrrArtGid CombiArtGid,
                       OrlMagGid CombiMagGid,
                       (select sum(calcMagazijnVoorraad) from vwVoorraadAantallen where (calcMagGid = OrlMagGid and calcArtGid = OrrArtGid)) TotaalInVoorraad,
                       sum(OrlDezeLevering) TotaalLevering
                     from
                       tabOrderRegelLocatie
                       inner join taborderregel on (OrlOrrGid = OrrGid)
                       inner join tabArtikel on (ArtGid = OrrArtGid)
                     where
                       ArtHeeftVoorraad <> 0 and ArtIsPartijRegistreren = 0
                       //ACW 12-11-2018 Defect 52487: Niet testen op partijgid, omdat serienummers wel een partijgid hebben
                       //and OrlArtPartijGid is null
                       and OrrOrkGid in (select tfoTeFactOrkGid from tabTeFacturerenOrders)
                     group by
                       CombiArtGid, CombiMagGid
                     having
                       TotaalInVoorraad < TotaalLevering and TotaalLevering > 0
                   ) CombiTabel on CombiArtGid = OrrArtGid and CombiMagGid = OrlMagGid
      where
        tfoSessieFbGid = @FbGid
        //ACW 12-11-2018 Defect 52487: Niet testen op partijgid, omdat serienummers wel een partijgid hebben
        //and OrlArtPartijGid is null
        and ArtIsPartijRegistreren = 0
        and tfoTeFactOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid) // Komt inderdaad nog niet in de niet-te-factureren lijst voor

      UNION // Om zowel artikelen met (obv. tabArtikelMagazijn) als zonder partijregistratie te controleren

      // Artikelen MET partijregistratie
      select distinct @fbGid, tfoTeFactOrkGid, 20, 1 //Magazijnvoorraad niet toereikend
      from
        tabTeFacturerenOrders
        inner join tabOrderRegel on (OrrOrkGid = tfoTeFactOrkGid)
        inner join tabOrderRegelLocatie on (OrlOrrGid = OrrGid)
        inner join ( // Combinatie van Art/Partij/Magazijn in de leverbatch waarvoor de magazijnvoorraad kleiner is dan de te leveren voorraad
                     select
                       OrrArtGid CombiArtGid,
                       OrlArtPartijGid CombiArtPartijGid,
                       OrlMagGid CombiMagGid,
                       (select sum(calcMagazijnVoorraad) from vwVoorraadAantallen where (calcMagGid = OrlMagGid and calcArtPartijGid = OrlArtPartijGid)) TotaalInVoorraad,
                       sum(OrlDezeLevering) TotaalLevering
                     from
                       tabOrderRegelLocatie
                       inner join taborderregel on (OrlOrrGid = OrrGid)
                       inner join tabArtikel on (ArtGid = OrrArtGid)
                     where
                       ArtHeeftVoorraad <> 0 and ArtIsPartijRegistreren <> 0
                       and OrlArtPartijGid is not null
                       and OrrOrkGid in (select tfoTeFactOrkGid from tabTeFacturerenOrders)
                     group by
                       CombiArtGid, CombiArtPartijGid, CombiMagGid
                     having
                       TotaalInVoorraad < TotaalLevering and TotaalLevering > 0
                   ) CombiTabel on CombiArtGid       = OrrArtGid       and
                                   CombiArtPartijGid = OrlArtPartijGid and  // We weten dat hier partij al is ingevuld (verplicht bij leveren), dus vinkje Partijregistratie is niet nodig, scheelt weer een join met tabartikel
                                   CombiMagGid       = OrlMagGid
      where
       tfoSessieFbGid = @FbGid
       and tfoTeFactOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); // Komt inderdaad nog niet in de niet-te-factureren lijst voor;

  end if;
    // En verwijderen van orders die in de niet-te-leveren tabel zijn opgenomen
    delete from tabTeFacturerenOrders
    where tfoSessieFbGid = @FbGid and tfoTeFactOrkGid in (select fngorkgid from tabFactuurNietGefactureerd where fngFbGid = @fbGid);


   //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: FacturerenCheckPrintedDocuments.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenCheckPrintedDocuments') then
  drop function FacturerenCheckPrintedDocuments;
end if;

create procedure FacturerenCheckPrintedDocuments(in @fbGid integer, in @SoortFact smallint, in @LayoutSoort integer)
begin
  //@SoortFact:
  // 0 = facturering Batch
  // 1 = facturering direct
  // 2 = orderbevestiging (dus orders niet samenvoegen en ook geen factuurnummer aanmaken)
  // 3 = Pakbon (let op: dit betekent een levering!!!)
  // 4 = Proforma

  declare @OrkGid integer;

  //ACW 11-1-2001: cursor aangepast ivm. wijzigen van verplicht afdrukken van tabDocument naar tabVasteGegevensOrdersFactureren
  declare cursor_NietAfgedrukt dynamic scroll cursor for
    select tfoTeFactOrkGid
    from   tabTeFacturerenOrders, tabVasteGegevensOrdersFactureren
    where  (@SoortFact in (0,1) and
           (tfoSessieFbGid = @FbGid) and
            (vofFactIsOrderBevestigingVerplicht = 1 and
             not exists ( select 1 from tabOrderDocGegevens where OrdDocDocSoort = 20 and OrdDocOrkGid=tfoTeFactOrkGid and OrdDocGegGewijzigdNaAfdruk = 0 and OrdDocGegAfgedruktOp is not null)) or
            (@SoortFact in (0,1) and
             vofFactIsProformaNotaVerplicht = 1 and
             not exists ( select 1 from tabOrderDocGegevens where OrdDocDocSoort = 40 and OrdDocOrkGid=tfoTeFactOrkGid and OrdDocGegGewijzigdNaAfdruk = 0 and OrdDocGegAfgedruktOp is not null))
           ) or
           (@SoortFact = 3 and
            (vofLevIsOrderBevestigingVerplicht = 1 and
             not exists ( select 1 from tabOrderDocGegevens where OrdDocDocSoort = 20 and OrdDocOrkGid=tfoTeFactOrkGid and OrdDocGegGewijzigdNaAfdruk = 0 and OrdDocGegAfgedruktOp is not null)
            )
           )
    for read only;

  // Selecteer alle orders waarvan een document al is afgedrukt en de order in de tussentijd nog niet is gewijzigd
  declare cursor_AlAfgedrukt dynamic scroll cursor for
    select tfoTeFactOrkGid
    from   tabTeFacturerenOrders, tabDocument, tabOrderDocGegevens
    where  tfoSessieFbGid = @FbGid
    	   and DocOrdAfdrukkenEenKeer = 1
           and DocSoort = @LayoutSoort
           and OrdDocOrkGid = tfoTeFactOrkGid
           and OrdDocDocSoort = @LayoutSoort
           and (OrdDocGegAfgedruktOp is not null and // Let op: geen datum betekent nooit afgedrukt!
                OrdDocGegGewijzigdNaAfdruk = 0)      // maar de order mag ook nog NIET zijn gewijzigd na afdruk!
    for read only;


  set @@ErrorTextProcedure = 'FacturerenCheckPrintedDocuments > @fbGid='+string(@fbGid)+', @SoortFact='+string(@SoortFact);
  //call TraceBegin(@@ErrorTextProcedure);

  //niet-te-factureren-orders in de tabel van niet-gefactureerde orders zetten en uit de tijdelijke lijst halen
  if @SoortFact in (0, 3) then
    //call Trace('Order verwijderen als andere documenten nog niet zijn afgedrukt en dat is verplicht');
    open cursor_NietAfgedrukt;
    LoopOrders:
    loop
      Fetch next cursor_NietAfgedrukt into @OrkGid;

      if sqlstate = '02000' then
        leave LoopOrders;
      end if;

      if not exists( select 1 from tabFactuurNietGefactureerd where fngFbGid = @fbGid and fngOrkGid = @OrkGid) then
        insert into tabFactuurNietGefactureerd(fngFbGid, fngOrkGid, fngReden, fngLockedByMe) values(@fbGid, @OrkGid, 2, 1); //Ander document nog niet afgedrukt
      end if;

    end loop LoopOrders;
    close cursor_NietAfgedrukt;
  end if;

  //call Trace('Orders eruitgooien als het document al eerder is afgedrukt zonder dat dit is toegestaan en waarvoor de order nog niet is gewijzigd');
  open cursor_AlAfgedrukt;
  LoopOrders:
  loop
    Fetch Next cursor_AlAfgedrukt into @OrkGid;

    if sqlstate = '02000' then
      leave LoopOrders;
    end if;

    if not exists( select 1 from tabFactuurNietGefactureerd where fngFbGid = @fbGid and fngOrkGid = @OrkGid) then
      insert into tabFactuurNietGefactureerd(fngFbGid, fngOrkGid, fngReden, fngLockedByMe) values(@fbGid, @OrkGid, 5, 1);  //Dit document is al afgedrukt
    end if;

  end loop LoopOrders;
  close cursor_AlAfgedrukt;

  //En uit de te-factureren-lijst verwijderen wat nu in de niet-factureren-tabel zit
  delete from tabTeFacturerenOrders
  where tfoSessieFbGid = @FbGid and tfoTeFactOrkGid in (select fngorkgid from tabFactuurNietGefactureerd where fngFbGid = @fbGid);

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure FacturerenCheckSerienummersPartijen(in @fbGid integer, in @SoortFact smallint)
begin
  //@SoortFact:
  // 0 = facturering Batch
  // 1 = facturering direct
  // 2 = orderbevestiging (dus orders niet samenvoegen en ook geen factuurnummer aanmaken)
  // 3 = Pakbon (let op: dit betekent een levering!!!)
  // 4 = Proforma

  declare @OrkGid integer;

  set @@ErrorTextProcedure = 'FacturerenCheckSerienummersPartijen > @fbGid='+string(@fbGid)+', @SoortFact='+string(@SoortFact);
   //call TraceBegin(@@ErrorTextProcedure);

  if @SoortFact = 3 and @@ModuleP2 <> 0 then
    //Beperking alleen voor het leveren *EN* als de optie 'partijen' geactiveerd is
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, tfoTeFactOrkGid, 19, 1 //Partijnummer van een artikel is niet ingevuld
    from tabTeFacturerenOrders
    where tfoSessieFbGid = @fbGid and
    	  //Bestaat er een artikeregel zonder partij waarvoor de partij wel moet zijn ingegeven?
          exists( select 1
                  from   tabOrderRegel
                         inner join tabArtikel on (ArtGid = OrrArtGid)
                         left outer join tabOrderRegelLocatie on (OrlOrrGid = OrrGid)
                  where  OrrOrkGid = tfoTeFactOrkGid and           // Alleen van geselecteerde order
                         OrrRegelSoort = 2 and                     // Soort orderregel = Artikelregel
                         ArtIsPartijRegistreren = 1 and            // orderregel met artikel waarvoor partijen moeten worden geregistreerd
                         isnull(OrrAantalLevering, 0)<>0 and       // Aantal deze levering natuurlijk ongelijk aan 0!
                         (OrlArtPartijGid is null                  // Specificatieregel bevat geen partijnummer
                          /*or OrrArtPartijGid is null*/)          // OF orderregel zelf bevat geen partijnummer (Maar dat is nu toch niet verplicht!!)
                )
          and tfoTeFactOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); //Komt inderdaad nog niet in de niet-te-factureren lijst voor
  end if;

  if @SoortFact = 3 and @@ModuleS1 <> 0 then
    //Beperking alleen voor het leveren *EN* als de optie 'Serienummers' geactiveerd is
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, tfoTeFactOrkGid, 12, 1 //Serienummer van een artikel is niet ingevuld
    from tabTeFacturerenOrders
    where tfoSessieFbGid = @FbGid and
          //Bestaat er een artikeregel zonder serienummer waarvoor het serienummer wel moet zijn ingegeven?
          exists( select 1
                  from   tabOrderRegel
                         inner join tabArtikel on (ArtGid = OrrArtGid)
                         left outer join tabOrderRegelLocatie on (OrlOrrGid = OrrGid)
                  where  OrrOrkGid = tfoTeFactOrkGid and           // Alleen van geselecteerde order
                         OrrRegelSoort = 2 and                     // Soort orderregel = Artikelregel
                         ArtSerienrRegistreren = 1 and             // orderregel met artikel waarvoor serienummers moeten worden geregistreerd
                         isnull(OrrAantalLevering, 0)<>0 and       // Aantal deze levering natuurlijk ongelijk aan 0!
                         OrlArtSerieGid is null                    // Specificatieregel bevat geen serienummer

                )
          and tfoTeFactOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); //Komt inderdaad nog niet in de niet-te-factureren lijst voor
  end if;

   //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure FacturerenCreateAcceptGiroBatch(in @ConnId integer, in @LoginTime datetime, in @fbGid integer, in @LayoutSoort integer, in @UseLockedOrkGid integer, out @AcbGid integer)

begin
  //Eerst de acceptgirobatch aanmaken
  declare @AccIpvFactuur integer;
  declare @ErrText nchar(500);

  declare @OrkGid integer;
  declare @VorigeOrkGid integer;


  set @ErrText = 'FacturerenCreateAcceptGiroBatch(@fbGid='+string(@fbGid)+', @LayoutSoort='+string(@LayoutSoort)+')';
  set @@ErrorTextProcedure = @ErrText;

   //call TraceBegin(@@ErrorTextProcedure);

  set @AccIpvFactuur = if exists( select 1 from tabDocument where DocOrdAfdrukkenFactuurAcceptgiro = 1 and DocSoort = @LayoutSoort) then 1 else 0 endif;

  insert into tabAcceptGiroBatch(AcbAangemaaktDoor, AcbAangemaaktOp, AcbSoort, AcbOms,        AcbFbGid)
  values(                        @@GebruikerCode,   Now(),           0,        _A('Facturering'), @fbGid);

  set @AcbGid = @@Identity;

  //Locken van de acc.batch

   //call Trace(@ErrText + ' -> Lock!');
  if @ConnId is null then
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabAcceptGiroBatch', 'AcbGid='+string(@AcbGid), 0);
  else
    call LockSetOnId(@ConnId, @LoginTime, 1, 'tabAcceptGiroBatch', 'AcbGid='+string(@AcbGid), 0);
  end if;

  // Zet in de lijst die acceptgiros waarvoor de acc.giro in de valuta niet moet worden afgedrukt
  if @AccIpvFactuur = 1 then
   //call Trace(@ErrText + ' -> Insert naar NietGefactureerd!');
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, frefOrkGid, 14, 1
    from   tabFactuurKop
           inner join tabFactuurReferentie on (FrefFkGid = FkGid)
           inner join tabValuta on ValNummer = FkValNummer
    where  FkFbGid = @FbGid and PrintAcceptgiro = 0
           and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); // Komt inderdaad nog niet in de niet-te-factureren lijst voor
  end if;

  // Nu alle acceptgiros van de facturen overnemen waarvan een acceptgiro moet worden afgedrukt
   //call Trace(@ErrText + ' -> Batch vullen');
  insert into tabAcceptGiro(
         AccAcbGid, accRegelNummer, AccFkGid, AccDebNummer, accFactuurNummer,
         accFactuurDatum, accVervalDatum,
         accReferentie,
         accValNummer, AccValCode, accBedrag, accBtcNummer, AccBtcOms, accLvcNummer, AccLvcOms,

         AccCorrAdresNaam1,    AccCorrAdresNaam2,
         AccCorrAdresStraat,   AccCorrAdresHuisnummer,
         AccCorrAdresPostcode, AccCorrAdresPlaats,
         AccCorrAdresLndEigenCode, AccCorrAdresLndOms, AccCorrAdresLndPlaatsHuisnr,
         AccCorrAdresLndPlaatsPostcode, AccCorrAdresLndInNAWBlok,

         AccVestAdresNaam1, AccVestAdresNaam2,
         AccVestAdresStraat, AccVestAdresHuisnummer,
         AccVestAdresPostcode, AccVestAdresPlaats,
         AccVestAdresLndEigenCode, AccVestAdresLndOms, AccVestAdresLndPlaatsHuisnr,
         AccVestAdresLndPlaatsPostcode, AccVestAdresLndInNAWBlok,

         AccGebruikCorrespondentieAdres,

         AccBankRekBankRekening, AccBankRekNaamRekHouder,
         AccBankRekAdresRekHouder, accBankRekPostcodeRekHouder, AccBankRekPlaatsRekHouder,
         AccPrintBedragAcceptgiro,

         AccRapNummer,
         AccFormCode,
         AccDiversen,
         AccEigenRekening,
         AccBIC,
         AccBetalingskenmerk,
         AccTaalCode)
  select @AcbGid, number(), fkGid, fkDebNummer, fkFactuurNummer,
         fkFactuurDatum, fkVervalDatum,
         (select frefOms from tabFactuurReferentie where frefFkgid=FkGid and frefOrderNummer = (select min(frefOrderNummer) from tabFactuurReferentie where frefFkgid=FkGid) ),
         fkValNummer, ValCode, if fkBedragTeBetalen is null then fkFactTotInBtw else fkBedragTeBetalen endif,
         BtcNummer, BtcOms, LvcNummer, LvcOms,
         // Correspondentieadres
         Correspondentie.adrNaam1,    Correspondentie.adrNaam2,
         Correspondentie.adrStraat,   Correspondentie.adrHuisnummer,
         Correspondentie.adrPostcode, Correspondentie.adrPlaats,
         CorrLand.LndEigenCode,       CorrLand.LndOms,         CorrLand.LndPlaatsHuisnr,
         CorrLand.LndPlaatsPostcode,  CorrLand.LndInNAWBlok,
         // Vestigingsadres
         Vestiging.adrNaam1,         Vestiging.adrNaam2,
         Vestiging.adrStraat,        Vestiging.adrHuisnummer,
         Vestiging.adrPostcode,      Vestiging.adrPlaats,
         VestLand.LndEigenCode,      VestLand.LndOms,         VestLand.LndPlaatsHuisnr,
         VestLand.LndPlaatsPostcode, VestLand.LndInNAWBlok,

         if Correspondentie.AdrGid is null then 0 else 1 endif,

         // Bankrekening
//         nawRekBankRekening,   nawrekNaamRekHouder,
//         nawRekAdresRekHouder, nawrekPostcodeRekHouder, nawrekPlaatsRekHouder,
         fkBankRekNummer, fkBankRekNaam,
         fkBankRekAdres, fkBankRekPostcode, fkBankRekPlaats,

         fkPrintBedragAcceptGiro,

         // Rapportnummer
         (select RapNummer from tabDocumentLayout inner join tabRapport on RapGid = DocLayRapGidAcceptgiro where DocLayDocSoort = 70 /*@LayoutSoort*/ and DocLayTaalGid = nawTaalGid),

         // DOcumentgegevens
         fkOCRformcode,
         fkOCRdiversen,
         fkOCReigenrekening,
         fkOCRBIC,
         fkBetalingskenmerk,
         nawTaalGid

  from   tabFactuurKop
         inner join tabNawFile on (nawfilNummer = fkDebNummer and NawFilFonId='D')
         inner join tabNaw on (NawGid = NawFilNawGid)
         inner join      (tabAdres Vestiging
                          inner join tabLand VestLand on (VestLand.LndGid = Vestiging.AdrLndGid)
                         ) on (Vestiging.adrGid = NawGidVestiging)
         left outer join (tabAdres Correspondentie
                          inner join tabLand CorrLand on (CorrLand.LndGid = Correspondentie.AdrLndGid)
                         ) on (Correspondentie.adrGid = nawGidCorrespondentie)
         inner join tabValuta on ValNummer = FkValNummer
         left outer join tabBetalingsConditie on (BtcNummer = FkBtcNummer)
         left outer join tabLeveringsConditie on (LvcNummer = FkLvcNummer)
         left outer join tabNawRekening on ((nawRekNawGid = NawGid) and (nawRekSoort like '%D%'))
  where  FkFbGid = @FbGid and PrintAcceptgiro = 1;

  //call Trace('------------------------------------------>'+string(@AcbGid));

  // Als we acceptgiros ipv. facturen hebben, dan alle facturen uit de batch gooien waarvan we geen acceptgiro hebben.
  // Reden: - De acceptgiro-layout is niet ingesteld, of
  //        - de gebruiker wil geen acceptgiro voor die taal

  //call Trace('@AccIpvFactuur='+string(@AccIpvFactuur));

  // LET OP: Als een acceptgiro om welke reden dan ook niet kan worden afgedrukt,
  //         dan kan de factuur DUS ook niet worden afgedrukt !!!

  //if @AccIpvFactuur = 1 then
    // Punt 1: layout is niet ingevuld (Dit zijn de acceptgiros waarvan AccRapNummer leeg is)
    //call Trace('Niet-ingevulde acceptgirolayouts vermelden');

   //call Trace(@ErrText + ' -> Overigen niet te factureren plaatsen!');
  insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
  select @fbGid, frefOrkGid, 13, 1
  from   tabAcceptGiro inner join tabFactuurKop on (FkFbGid = @FbGid and AccFkGid = fkGid) inner join tabFactuurBatch on (FkFbGid = FbGid) inner join tabFactuurReferentie on (FrefFkGid = FkGid)
  where  accRapNummer is null
         and FbSoortBatch in (50,60)
         and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); // Komt inderdaad nog niet in de niet-te-factureren lijst voor
  //end if;

  if @AccIpvFactuur = 1 then
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, frefOrkGid, 14, 1
    from   tabFactuurKop
           inner join tabFactuurReferentie on (FrefFkGid = FkGid)
           inner join tabValuta on ValNummer = FkValNummer
    where  FkFbGid = @FbGid and PrintAcceptgiro = 0
           and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); // Komt inderdaad nog niet in de niet-te-factureren lijst voor
  end if;

  // TIJDELIJKE OPLOSSING IVM BUG 16219, code 13 wordt niet unlocked aangezien deze proc pas NA het unlocken van de andere niet gefact wordt aangeroepen.. moet nog een keer rechtgetrokken worden
  set @VorigeOrkGid = null;
  OrderLockLoop:
  loop
    set @OrkGid = null;
    select first fngOrkGid into @OrkGid from tabFactuurNietGefactureerd
    where fngFbGid = @FbGid and (fngReden in (13,14)) and (@VorigeOrkGid is null or fngOrkGid > @VorigeOrkGid) and (@UseLockedOrkGid is null or fngOrkGid<>@UseLockedOrkGid) and fngLockedByMe = 1 order by fngOrkGid;
    if @OrkGid is null then
      leave OrderLockLoop;
    end if;
    set @VorigeOrkGid = @OrkGid;
    //call Trace('Vrijgeven order; @OrkGid='+string(@OrkGid));
    if @ConnId = null then
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
    else
      call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid);
    end if;
  end loop OrderLockLoop;
  // TIJDELIJKE OPLOSSING IVM BUG 16219

  // Dan alle acceptgiros verwijderen die geen layout hebben (altijd verwijderen!)
   //call Trace('Niet-ingevulde acceptgirolayouts verwijderen');
  delete from tabAcceptGiro where AccRapNummer is null and AccAcbGid = @AcbGid;

  if @AccIpvFactuur = 1 then
    // Als acceptgiro wel en factuur niet wordt afgedrukt, dan orders NIET factureren waarvoor geen acceptgiro wordt
    // afgedrukt. We moeten tenslotte wel een bewijs van factureren hebben.

    // Punt 2: acceptgiro moet niet worden afgedrukt (dit zijn de facturen die niet in tabAcceptGiro staan en wel in tabFactuurKop
     //call Trace(@ErrText + ' -> Niet-af-te-drukken acceptgiros vermelden');
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, frefOrkGid, 13, 1
    from   tabFactuurKop inner join tabFactuurReferentie on (FrefFkGid = FkGid) left outer join tabAcceptGiro on (AccFkGid = fkGid and AccAcbGid = @AcbGid)
    where  FkFbGid = @FbGid   // Alleen van de factuurbatch
           and AccGid is null // die *niet* in deze acceptgirobatch staan
           and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); // Komt inderdaad nog niet in de niet-te-factureren lijst voor
  end if;

  // Vervolgens alle facturen verwijderen die in de niet-gefactureerd-tabel is toegevoegd
   //call Trace('Verwijder niet-te-factureren facturen');
  delete tabFactuurKop
  where fkFbGid = @fbGid and
        FkGid in (select frefFkGid
                  from tabFactuurReferentie
                       inner join tabFactuurNietGefactureerd on (fngorkgid = frefOrkGid and fngFbGid = @fbGid)
                  where frefFkGid = FkGid);

  // Als de acceptgirobatch leeg is, dan ook die verwijderen
  if not exists( select 1 from tabAcceptGiro where AccAcbGid = @AcbGid) then
    delete tabAcceptGiroBatch where AcbGid = @AcbGid;

    // De eventuele lock op acceptgirobatch verwijderen
    if @ConnId is null then
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabAcceptGiroBatch', 'AcbGid='+string(@AcbGid));
    else
      call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabAcceptGiroBatch', 'AcbGid='+string(@AcbGid));
    end if;

    set @AcbGid = null;
  end if;

   //call TraceEind(@@ErrorTextProcedure+'; @AcbGid='+string(@AcbGid));


end;


//$Workfile: FacturerenLeverMaakRekeningObvOpbrGroep.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:53 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenLeverMaakRekeningObvOpbrGroep') then
  drop procedure FacturerenLeverMaakRekeningObvOpbrGroep;
end if;

create procedure FacturerenLeverMaakRekeningObvOpbrGroep(in @OpbrGrpGid integer, in @ParSoort integer, out @GrpSoortRksGID integer)
begin
	set @@ErrorTextProcedure = 'FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid='+string(@OpbrGrpGid)+', @ParSoort='+string(@ParSoort)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  //Voorraadrekening opzoeken en evt. aanmaken
  set @GrpSoortRksGID = null;
  select GrpSoortRksGID into @GrpSoortRksGID from tabOpbrengstGroepSoort where GrpSoortGrpGid = @OpbrGrpGid and GrpSoortParSoort = @ParSoort;
  if @GrpSoortRksGID is null then
    //Aanmaken van de grootboekrekening voor kostprijs: <paragraaf>+<kostprijsgroep>
    call OpbrengtGroepsoortenPerStuk( @OpbrGrpGid, @ParSoort);
    select GrpSoortRksGID into @GrpSoortRksGID from tabOpbrengstGroepSoort where GrpSoortGrpGid = @OpbrGrpGid and GrpSoortParSoort = @ParSoort;
  end if;

  //call TraceEind('FacturerenLeverMaakRekeningObvOpbrGroep(@GrpSoortRksGID='+string(@GrpSoortRksGID)+')');

end;


// Is een variant op bovenstaande om tijdens facturering rekeningen met Kp/Kd aan te maken.
create or replace procedure FacturerenLeverMaakRekeningObvOpbrGroepKpKd(in @OpbrGrpGid integer, in @ParSoort integer, in @KstpCode nchar(8), in @KstdCode nchar(8), out @GrpSoortRksGID integer)
begin
  declare @KstpGid integer;
  declare @KstdGid integer;

  set @@ErrorTextProcedure = 'FacturerenLeverMaakRekeningObvOpbrGroepKpKd(@OpbrGrpGid='+string(@OpbrGrpGid)+', @ParSoort='+string(@ParSoort)+',@KstpCode='+string(@KstpCode)+',@KstdCode='+string(@KstdCode)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  //Voorraadrekening opzoeken en evt. aanmaken
  set @GrpSoortRksGID = null;
  select GrpSoortRksGID into @GrpSoortRksGID from tabOpbrengstGroepSoort where GrpSoortGrpGid = @OpbrGrpGid and GrpSoortParSoort = @ParSoort;
  if @GrpSoortRksGID is null then
    //Aanmaken van de grootboekrekening voor kostprijs: <paragraaf>+<kostprijsgroep>
    call OpbrengtGroepsoortenPerStuk( @OpbrGrpGid, @ParSoort);
    select GrpSoortRksGID into @GrpSoortRksGID from tabOpbrengstGroepSoort where GrpSoortGrpGid = @OpbrGrpGid and GrpSoortParSoort = @ParSoort;
  end if;

  // Alleen als er dus een KP/KD meegegeven wordt dan gaan we verder om er een op te zoeken en evt aan te maken
  if IsNull(@KstpCode,'') <> '' or IsNull(@KstdCode,'') <> '' then
    select KstpGid into @KstpGid from tabKostenPlaats where KstpCode = @KstpCode;
    select KstdGid into @KstdGid from tabKostenDrager where KstdCode = @KstdCode;
    //TG 27-08-2007: oude (eigen) code vervangen door de stored proc ivm bug #26434.
    call ZoekOfMaakRksMetKstpKstd(@GrpSoortRksGID, @KstpGid, @KstdGid, @GrpSoortRksGID);
  end if;

  //call TraceEind('FacturerenLeverMaakRekeningObvOpbrGroepKpKd(@GrpSoortRksGID='+string(@GrpSoortRksGID)+')');

end;


create or replace procedure FacturerenMaakKopieVoorLeveren(
in  @FbGid     integer,
in  @RapNummer integer,
out @NewFbGid  integer)
begin
  //Maak een kopie van een (balie)factureergang en markeer het als een lever-gang
  declare @FkGid              integer;
  declare @TmpFkGid           integer;
  declare @frefGid            integer;
  declare @TmpFrefGid         integer;
  declare @IsBatchFactuur     integer;
  declare @PakbonAfdrukken    integer;
  declare @TariefOpPakbon     integer;
  declare @TekstOpPakbon      integer;
  declare @IsRapNummerNodig   integer;
  declare @IngesteldRapNummer integer;
  declare @OrkNawGid          integer;
  declare @OrkFactuurNawGid   integer;
  declare @frefOrkGid         integer;
  declare @PakbonBatchFact    smallint;

  // LET OP: Dit is dezelfde tabel als bij facturering; moet opnieuw worden aangemaakt i.v.m. controles!

  declare cursor_Facturen dynamic scroll cursor for
    select FkGid from tabFactuurKop where FkFbGid = @FbGid;

  declare cursor_Referenties dynamic scroll cursor for
    select FrefGid from tabFactuurReferentie where FrefFkGid = @FkGid;

  set @@ErrorTextProcedure = 'FacturerenMaakKopieVoorLeveren >';
  //call TraceBegin(@@ErrorTextProcedure + ' @FbGid = ' +string(@FbGid));

  // Bepaal of het een batchfactuur of een baliefactuur is
  set @IsBatchFactuur = isnull((select 1 from tabFactuurBatch where fbGid = @FbGid and fbSoortBatch = 50 /*Batchfactuur*/),0);

  //Opvragen of de tekstregels en/of tariefregels op de pakbon moeten komen
  select first vofLevOokTarief, vofLevOokTekst into @TariefOpPakbon, @TekstOpPakbon from tabVasteGegevensOrdersFactureren;

  // Alf rapportnummer benodigd, dan dat opmerken (ivm. latere controle)
  set @IsRapNummerNodig = 0;
  if (@IsBatchFactuur = 0) and exists(select 1 from tabVasteGegevensOrdersFactureren where vofDirectIsLeverenBijDirecteFact <> 0 and vofDirectIsPakbonAfdrukkenBijLeveren <> 0)  or
     (@IsBatchFactuur = 1) and exists(select 1 from tabVasteGegevensOrdersFactureren where vofLeverenBijFactureren 	    <> 0 and vofPakbonBijFactureren <> 0) then
    set @IsRapNummerNodig = 1;
  end if;

  //call Trace('FacturerenMaakKopieVoorLeveren > Batch toevoegen; @IsRapNummerNodig='+string(@IsRapNummerNodig));
  //We maken er een pakbon-batch van, dus dan 30 als batchsoort opnemen!
  insert into tabFactuurbatch(fbAangemaaktDoor, fbAangemaaktOp, fbSoortBatch, fbPakbonAfgedrukt)
  select fbAangemaaktDoor, fbAangemaaktOp, 30, (if (select Fact.fbSoortBatch from tabFactuurBatch Fact where Fact.FbGid = @FbGid) = 50 then (select vofPakbonBijFactureren from tabVasteGegevensOrdersFactureren) else (select vofDirectIsPakbonAfdrukkenBijLeveren from tabVasteGegevensOrdersFactureren) endif) from tabFactuurbatch where FbGid = @fbGid;
  set @NewFbGid = @@Identity;

  // In de factuurbatch een ref naar de leverbatch opnemen
  update tabFactuurBatch set fbLeverbatchFbGid = @NewFbGid where FbGid = @FbGid;

  //call Trace('FacturerenMaakKopieVoorLeveren > FacturerenMaakKopieVoorLeveren - Referentie naar Leverbatch opgeslagen in Factuurbatch (@FbGid = ' + string(@FbGid) + ', @NewFbGid = ' + string(@NewFbGid));

  call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch', 'fbGid='+string(@NewFbGid), 0);

  open cursor_Facturen;
  loopje1:
  loop
    //Hier alle facturen overnemen
    Fetch next cursor_Facturen into @FkGid;
    if sqlstate = '02000' then
      leave loopje1;
    end if;
    //call Trace('FacturerenMaakKopieVoorLeveren > @NewFbGid = ' + string(@NewFbGid) + ', @FkGid = ' + string(@FkGid));

    select vofPakbonBijFactureren into @PakbonBatchFact from tabVasteGegevensOrdersFactureren;

    if @IsBatchFactuur =1 and @PakbonBatchFact = 0 then
      select
        first RapNummer, OrkNawGid, OrkFactuurNawGid into @IngesteldRapNummer,@OrkNawGid,@OrkFactuurNawGid
      from   tabFactuurKop
      inner join tabFactuurReferentie on frefFkGid = FkGid
      inner join tabOrderKop on frefOrkGid = OrkGid
      inner join tabNaw on NawGid = OrkNawGid
      left outer join tabDocumentLayout on  (DocLayDocSoort = 30 and DocLayTaalGid = NawTaalGid)
      left outer join tabNawDocument    on ((NawDocNawGid = NawGid) and NawDocRegelSoort = 0 and NawDocDocsoort = 30 )
      left outer join tabRapport        on  (RapGid = if fkIsInclBtw = 0 then isnull(NawDocRapgidExclBTW, DocLayRapGidExcl) else isnull(NawDocRapgidInclBTW,DocLayRapGidIncl) endif)
      where FkGid = @FkGid;
    else
      select
        distinct RapNummer, OrkNawGid, OrkFactuurNawGid into @IngesteldRapNummer,@OrkNawGid,@OrkFactuurNawGid
      from   tabFactuurKop
      inner join tabFactuurReferentie on frefFkGid = FkGid
      inner join tabOrderKop on frefOrkGid = OrkGid
      inner join tabNaw on NawGid = OrkNawGid
      left outer join tabDocumentLayout on  (DocLayDocSoort = 30 and DocLayTaalGid = NawTaalGid)
      left outer join tabNawDocument    on ((NawDocNawGid = NawGid) and NawDocRegelSoort = 0 and NawDocDocsoort = 30 )
      left outer join tabRapport        on  (RapGid = if fkIsInclBtw = 0 then isnull(NawDocRapgidExclBTW, DocLayRapGidExcl) else isnull(NawDocRapgidInclBTW,DocLayRapGidIncl) endif)
      where FkGid = @FkGid;
    end if;

    insert into tabFactuurKop(
      fkFbGid, fkDebNummer, fkFactDebNummer, fkFactDebZoekCode, fkFactDebTelefoon, fkFactDebTelefax,
      fkTekstOrigineelKopie, fkFactuurNummer, fkFactuurNummer_Lengte,
      fkVertCode, fkVertNaam, fkNawBtwNummer, fkTelefoon, fkTelefax, fkValNummer, fkValCode, fkValOms,
      fkOrderDatum, fkFactuurDatum, fkVervalDatum, fkIsInclBtw, fkLeverDatum, fkSubTotExEmballage,
      fkTotEmballage, fkFactTotaalExBtw, fkFactTotInBtw, fkBedragBetaald, fkBedragTeBetalen, fkVerschilAfboeken, fkBtcNummer, fkBtcOms, FkBtcKredBepKortingInclBtw,
      fkBtcTekstOpFactuur, fkBtcPerc, fkBtcRksInvoer, fkBtcSoort, fkBtcDatum, fkBtcBasis, fkBtcBedrag, fkBtcBasisInBtw,
      fkBtcBasisExBtw, fkBtcBedragInBtw, fkLvcNummer, fkLvcCode, fkLvcOms, fkLvcTekstOpFactuur, fkOpmRegel, fkTaalGid, fkTaalCode,
      fkRapNummer,
      fkBankRekNummer, fkBankRekNaam, fkBankRekAdres, fkBankRekPostcode,fkBankRekPlaats, fkEigenBankRekNummer, fkEigenBankRekNaam, fkEigenBankRekAdres, fkEigenBankRekPlaats,
      fkOCRformcode, fkOCRdiversen, fkOCReigenrekening, fkOCRBIC, fkPrintBedragAcceptGiro, fkJpGid, fkIsEdi, fkIsAbcLevering, fkMagCode, FkGewichtIn, FkVolumeIn)
    select
      @NewFbGid, fkDebNummer, fkFactDebNummer, fkFactDebZoekCode, fkFactDebTelefoon, fkFactDebTelefax,
      fkTekstOrigineelKopie, '', 0,
      fkVertCode, fkVertNaam, fkNawBtwNummer, fkTelefoon, fkTelefax, fkValNummer, fkValCode, fkValOms,
      fkOrderDatum, fkFactuurDatum, fkVervalDatum, fkIsInclBtw, fkLeverDatum, fkSubTotExEmballage,
      fkTotEmballage, fkFactTotaalExBtw, fkFactTotInBtw, fkBedragBetaald, fkBedragTeBetalen, fkVerschilAfboeken, fkBtcNummer, fkBtcOms, FkBtcKredBepKortingInclBtw,
      fkBtcTekstOpFactuur, fkBtcPerc, fkBtcRksInvoer, fkBtcSoort, fkBtcDatum, fkBtcBasis, fkBtcBedrag, fkBtcBasisInBtw,
      fkBtcBasisExBtw, fkBtcBedragInBtw, fkLvcNummer, fkLvcCode, fkLvcOms, fkLvcTekstOpFactuur, fkOpmRegel, fkTaalGid, fkTaalCode,
      IsNull(@RapNummer, @IngesteldRapNummer),
      fkBankRekNummer, fkBankRekNaam, fkBankRekAdres, fkBankRekPostcode, fkBankRekPlaats, fkEigenBankRekNummer, fkEigenBankRekNaam, fkEigenBankRekAdres, fkEigenBankRekPlaats,
      fkOCRformcode, fkOCRdiversen, fkOCReigenrekening, fkOCRBIC, fkPrintBedragAcceptGiro, fkJpGid, fkIsEdi, fkIsAbcLevering, fkMagCode, FkGewichtIn, FkVolumeIn
    from tabFactuurKop where FkGid = @FkGid;

    set @TmpFkGid = @@Identity;
    //MR Bug# 25633: Vrije rubrieken bij de kopie voor leveren plaatsen.
    call FactureringOvernemenVrijeRubrieken(0, @TmpFkGid, @OrkNawGid, 0);

    //call Trace('FacturerenMaakKopieVoorLeveren > @TmpFkGid = ' + string(@TmpFkGid));

    //Hier alle BTW-regels toevoegen
    insert into tabFactuurBtwRegel(
      fbrFkGid, fbrBtwCode, fbrBtwPercentage, fbrBtwBasis, fbrBtwBedrag, fbrBtwVerlegd)
    select
      @TmpFkGid, fbrBtwCode, fbrBtwPercentage, fbrBtwBasis, fbrBtwBedrag, fbrBtwVerlegd
    from
      tabFactuurBtwRegel
    where
      fbrFkGid = @FkGid;

/*  Kopieren van adressen verwijderd nav bug 15269, gebeurt nu met FactureringVulAdressenIn, laat commented voorlopig even staan in geval het nog anders moet..
    // Alle adressen van de kop overhalen
    insert into tabFactuurAdres(
      faFkGid, faFrefGid, faSoortAdres,
      faContactEmail, faContactNaamAanhef, faContactNaamAdres, faContactNaamBrief, faContactTelefax, faContactTelefoon,
      faEANcode, faEmail, faHuisnummer, faHuisnummerPositie, faLand, faLandAfdrukken, faLandCode,
      faNaam1, faNaam2, faOms, faOpm, faPlaats, faPostcode, faPostcodePositie, faStraat, faTelefax, faTelefoon, faTelefoon2 )
    select
      @tmpFkGid, null, faSoortAdres,
      faContactEmail, faContactNaamAanhef, faContactNaamAdres, faContactNaamBrief, faContactTelefax, faContactTelefoon,
      faEANcode, faEmail, faHuisnummer, faHuisnummerPositie, faLand, faLandAfdrukken, faLandCode,
      faNaam1, faNaam2, faOms, faOpm, faPlaats, faPostcode, faPostcodePositie, faStraat, faTelefax, faTelefoon, faTelefoon2
    from
      tabFactuurAdres
    where
      faFkGid = @fkGid; */


    //Hier alle referenties toevoegen
    open cursor_Referenties;
    loopje2:
    loop
      //Hier alle facturen overnemen
      Fetch next cursor_Referenties into @frefGid;
      if sqlstate = '02000' then
        leave loopje2;
      end if;

      select frefOrkGid into @frefOrkGid from tabFactuurReferentie where frefGid = @frefGid;

      //call Trace('FacturerenMaakKopieVoorLeveren > @frefGid = '+string(@frefGid)+', @TmpFkGid='+string(@TmpFkGid));
      insert into tabFactuurReferentie(
        frefFkGid, frefOrderNummer, frefOms, frefExternId, frefOffertenummer, frefOrkGid, frefContactVanOrder, frefOrderDatum, frefLeverdatum,
        frefVtgCode, frefVtgVoornaam, frefVtgNaam, frefVtgZoekCode, frefVtgTelefoon1, frefEdiBuffer,
        frefOrderReferentie, frefEmailExtraTekst, frefOrderOpmerking, frefLvcCode, frefLvcNummer, frefLvcOms, frefLvcTekstOpFactuur,
		frefOrderAangemaaktOp, frefOrderAangemaaktDoor,
        frefOrderDebNummer, frefOrderDebAdresNaam1, frefOrderDebAdresNaam2, frefOrderIsInkoopCombinatie, frefOrderFactDebNummer,
        frefOrderOmzDebNummer, frefOrderPrijzenDebNummer, frefOrderVerzendAdres, frefOrderFactuurAdres, frefOrderEindAdres,
        frefOrderOmzDebNaam, frefOrderPrijzenDebNaam, frefOrderTotaalIncBtw, frefOrderTotaalExBtw,
        FrefVrvNaam, FrefVrvIsAutoAfdrukken, FrefVrvRapNummer, FrefVervoerGewichtEenheid, FrefVervoerVolumeEenheid,
        FrefCbsMeenemenInAangifte, FrefCbsCoCode, FrefCbsGsCode, FrefCbsLandBestemLndEigenCode, FrefCbsLandBestemLndOms, FrefCbsVgCode, FrefCbsVgPlaatsnaam, FrefCbsSsCode, FrefCbsVwCode,
        FrefKMGecontroleerdDoorHandcomputer, FrefKMGecontroleerdDoorMedewerker, FrefKMGecontroleerdOp, FrefKMGeimporteerdOp, FrefKMGepicktDoorHandcomputer, FrefKMGepicktDoorMedewerker,
        FrefKMGepicktOp, FrefKMHandcomputer, FrefKMHeeftAfwijkingInControle, FrefKMInBehandelingTerControleOp, FrefKMInBehandelingVanaf, FrefKMIsAanvulOrder, FrefKMLocatieAanvulOrder,
        FrefKMPickorderStatus, FrefKMToegewezenOp, FrefKMToegewezenTerControleOp)
      select
        @TmpFkGid, frefOrderNummer, frefOms, frefExternId, frefOffertenummer, frefOrkGid, frefContactVanOrder, frefOrderDatum, frefLeverdatum,
        frefVtgCode, frefVtgVoornaam, frefVtgNaam, frefVtgZoekCode, frefVtgTelefoon1, frefEdiBuffer,
        frefOrderReferentie, frefEmailExtraTekst, frefOrderOpmerking, frefLvcCode, frefLvcNummer, frefLvcOms, frefLvcTekstOpFactuur,
		frefOrderAangemaaktOp, frefOrderAangemaaktDoor,
        frefOrderDebNummer, frefOrderDebAdresNaam1, frefOrderDebAdresNaam2, frefOrderIsInkoopCombinatie, frefOrderFactDebNummer,
        frefOrderOmzDebNummer, frefOrderPrijzenDebNummer, frefOrderVerzendAdres, frefOrderFactuurAdres, frefOrderEindAdres,
        frefOrderOmzDebNaam, frefOrderPrijzenDebNaam, frefOrderTotaalIncBtw, frefOrderTotaalExBtw,
        FrefVrvNaam, FrefVrvIsAutoAfdrukken, FrefVrvRapNummer, FrefVervoerGewichtEenheid, FrefVervoerVolumeEenheid,
        FrefCbsMeenemenInAangifte, FrefCbsCoCode, FrefCbsGsCode, FrefCbsLandBestemLndEigenCode, FrefCbsLandBestemLndOms, FrefCbsVgCode, FrefCbsVgPlaatsnaam, FrefCbsSsCode, FrefCbsVwCode,
        FrefKMGecontroleerdDoorHandcomputer, FrefKMGecontroleerdDoorMedewerker, FrefKMGecontroleerdOp, FrefKMGeimporteerdOp, FrefKMGepicktDoorHandcomputer, FrefKMGepicktDoorMedewerker,
        FrefKMGepicktOp, FrefKMHandcomputer, FrefKMHeeftAfwijkingInControle, FrefKMInBehandelingTerControleOp, FrefKMInBehandelingVanaf, FrefKMIsAanvulOrder, FrefKMLocatieAanvulOrder,
        FrefKMPickorderStatus, FrefKMToegewezenOp, FrefKMToegewezenTerControleOp
      from
        tabFactuurReferentie
      where
        frefGid = @frefGid;

      set @tmpFrefGid = @@Identity;
      //Bug# 15269: Vrije rubrieken bij de kopie voor leveren plaatsen.
      call FactureringOvernemenVrijeRubrieken(1, @tmpFrefGid, @OrkNawGid, 0);
      call FactureringOvernemenVrijeRubrieken(3, @tmpFrefGid, @frefOrkGid, 0);

			// Verzendgegevens overnemen
			insert into tabFactuurColli (  FclfrefGid, FclRegelNr,  FclColtCode, FclColtCodeVervoerder, FclColtOmschrijving, FclColtLengteEenheid, FclAantal, FclGewicht,  FclVolume,    FclHoogte, FclBreedte,   FclDiepte, FclTrackTraceCode, FclTrackTraceUrl, FclOpmerking)
														 select @tmpFrefGid, FclRegelNr,  FclColtCode, FclColtCodeVervoerder, FclColtOmschrijving, FclColtLengteEenheid, FclAantal, FclGewicht,  FclVolume,    FclHoogte, FclBreedte,   FclDiepte, FclTrackTraceCode, FclTrackTraceUrl, FclOpmerking
														 from tabFactuurColli where FclFrefGid = @FrefGid;

  /*    // Alle adressen van de referentie overhalen
      insert into tabFactuurAdres(
        faFkGid, faFrefGid, faSoortAdres,
        faContactEmail, faContactNaamAanhef, faContactNaamAdres, faContactNaamBrief, faContactTelefax, faContactTelefoon,
        faEANcode, faEmail, faHuisnummer, faHuisnummerPositie, faLand, faLandAfdrukken, faLandCode,
        faNaam1, faNaam2, faOms, faOpm, faPlaats, faPostcode, faPostcodePositie, faStraat, faTelefax, faTelefoon, faTelefoon2 )
      select
        null, @tmpFrefGid, faSoortAdres,
        faContactEmail, faContactNaamAanhef, faContactNaamAdres, faContactNaamBrief, faContactTelefax, faContactTelefoon,
        faEANcode, faEmail, faHuisnummer, faHuisnummerPositie, faLand, faLandAfdrukken, faLandCode,
        faNaam1, faNaam2, faOms, faOpm, faPlaats, faPostcode, faPostcodePositie, faStraat, faTelefax, faTelefoon, faTelefoon2
      from
        tabFactuurAdres
      where
        faFrefGid = @frefGid;
     */

      //Hier alle factuurregels van de referentie toevoegen
      //call Trace('FacturerenMaakKopieVoorLeveren > Referentieregels!');
      insert into tabFactuurRegel(
        frFrefGid, frOrrGid, FrExternID, frRegelNummer, frSoortRegel, frOrrVervolgMasterOrrGid, frTekstOpFactuur, frArtCode, frArtZoekCode, frArtOms, frOpbrGrpNummer, frOrrArtPartijNummer,
        frIsAantal, frAantalBesteld, frAantalGeleverd, frAantalDezeLevering, frAantalGefactureerd, frAantalDezeFacturering,
        frAantalInBackorder, FrAantalInBackorderVrrdEenh,
        FrVerkoopEenheid, FrEenheidPrijsPer, FrAantalVrrdEenhInVerkEenh, FrAantalVrrdEenhInVerkEenhMagAfwijken, FrAantDecAantalVrrdEenh, FrAantalBesteldVrrdEenh,
        FrAantalDezeFactureringVrrdEenh, FrAantalGefactureerdVrrdEenh, FrAantalDezeLeveringVrrdEenh, FrAantalGeleverdVrrdEenh,
        frBrutoPrijsPeenheid, frKorting1Bedrag, frKorting1Perc, frKorting2Perc, frNettoPrijsPeenheid, frBtwCode,
        frBtwPercentage, frRegelTotaal, frKostprijs, frPrijsPer, frOmsEenheid, frAantDecBedrag, frAantDecAantal, frLeverdatum,
        frLocatieNaam, frMagazijnCode, frMagazijnNaam, frAdviesPrijsInclBtw, frAdviesprijsExclBtw,
        frGewichtPer, frGewichtPeenheid, frGewichtPStuk, FrGewichtTotaalBesteld, FrGewichtTotaalLevering,
        frVolumePer,  frVolumePeenheid, frVolumePStuk, FrVolumeTotaalBesteld, FrVolumeTotaalLevering,
        frCbsGcCode, frCbsGcOmsVerkort, FrCbsLndEigenCodeOorsprong, FrCbsLndOmsOorsprong, frArtEANCode, frEdiBuffer,
        FrDirecteLevering, FrDirLevNummer, FrDirLevNaam1, FrDirLevNaam2, FrKMAantalGecontroleerd)
      select
        @tmpFrefGid, frOrrGid, FrExternID, frRegelNummer, frSoortRegel, frOrrVervolgMasterOrrGid, frTekstOpFactuur, frArtCode, frArtZoekCode, frArtOms, frOpbrGrpNummer, frOrrArtPartijNummer,
        frIsAantal, frAantalBesteld, frAantalGeleverd, frAantalDezeLevering, frAantalGefactureerd, frAantalDezeFacturering,
        frAantalInBackorder, FrAantalInBackorderVrrdEenh,
        FrVerkoopEenheid, FrEenheidPrijsPer, FrAantalVrrdEenhInVerkEenh, FrAantalVrrdEenhInVerkEenhMagAfwijken, FrAantDecAantalVrrdEenh, FrAantalBesteldVrrdEenh,
        FrAantalDezeFactureringVrrdEenh, FrAantalGefactureerdVrrdEenh, FrAantalDezeLeveringVrrdEenh, FrAantalGeleverdVrrdEenh,
        frBrutoPrijsPeenheid, frKorting1Bedrag, frKorting1Perc, frKorting2Perc, frNettoPrijsPeenheid, frBtwCode,
        frBtwPercentage, frRegelTotaal, frKostprijs, frPrijsPer, frOmsEenheid, frAantDecBedrag, frAantDecAantal, frLeverdatum,
        frLocatieNaam, frMagazijnCode, frMagazijnNaam, frAdviesPrijsInclBtw, frAdviesprijsExclBtw,
        frGewichtPer, frGewichtPeenheid, frGewichtPStuk, FrGewichtTotaalBesteld, FrGewichtTotaalLevering,
        frVolumePer,  frVolumePeenheid, frVolumePStuk, FrVolumeTotaalBesteld, FrVolumeTotaalLevering,
        frCbsGcCode, frCbsGcOmsVerkort, FrCbsLndEigenCodeOorsprong, FrCbsLndOmsOorsprong, frArtEANCode, frEdiBuffer,
        FrDirecteLevering, FrDirLevNummer, FrDirLevNaam1, FrDirLevNaam2, FrKMAantalGecontroleerd
      from
        tabFactuurRegel
      where
        frFrefGid = @frefGid and
        ((frSoortRegel = 0 and @TekstOpPakbon  = 1) or // Tekst-regels ook op pakbon?
         (frSoortRegel = 1 and @TariefOpPakbon = 1) or // Tariefregels ook op pakbon?
         (frSoortRegel = 2)
        );

      //MR Bug# 25633: Vrije rubrieken bij de kopie voor leveren plaatsen.
      for @Cursor AS CursorRegelsVrijeRubriek CURSOR FOR
        select frGid @frGid, ArtGid @ArtGid, ArtPartijGid @ArtPartijGid, frOrrGid @frOrrGid, frSoortRegel @frSoortRegel
        from   tabFactuurRegel left outer join tabArtikel on (ArtSoort = 2 and ArtCode = frArtCode) left outer join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijNummer = frOrrArtPartijNummer
        where  frFrefGid = @tmpFrefGid
      for read only
      do
        call FactureringOvernemenVrijeRubrieken(4, @FrGid, @frOrrGid, 0);
        if @frSoortRegel = 2 then
          call FactureringOvernemenVrijeRubriekenArt(@FrGid, @ArtGid, 0);
        end if;

       if @FrSoortRegel = 2 and @ArtPartijGid is not null then
          call FactureringOvernemenVrijeRubriekenPartij(0, @FrGid, @ArtPartijGid, 0);
        end if;
      end for;

      // Partij/Serienummer/Locatie/Magazijn/... records overnemen
      insert into tabFactuurRegelPartijSerie(frpsFrGid, frpsPartijNummer, frpsPartijOms, frpsPartijTHTdatum, frpsSerienummer, frpsAantalDezeLevering, frpsAantalGeleverd, frpsGarantieCode, frpsGarantieTmDatum, frpsGarantieBepaling, frpsMagCode, frpsMagOms, frpsLocNaam, frpsLocOms, FrpsKMGepicktOp, FrpsSSCCID, FrpsVerkoopEenheid, FrpsAantalDezeLeveringVrrdEenh, FrpsAantalGeleverdVrrdEenh, FrpsAantDecAantal, FrpsAantDecAantalVrrdEenh, FrpsVerkoopEenheidIsVoorraadEenheid, frpsPartijDatumProductie, FrpsPartijCbsLndEigenCodeOorsprong, FrpsPartijCbsLndOmsOorsprong)
      select      GeschrevenRegels.FrGid, frpsPartijNummer, frpsPartijOms, frpsPartijTHTdatum, frpsSerienummer, frpsAantalDezeLevering, frpsAantalGeleverd, frpsGarantieCode, frpsGarantieTmDatum, frpsGarantieBepaling, frpsMagCode, frpsMagOms, frpsLocNaam, frpsLocOms, FrpsKMGepicktOp, FrpsSSCCID, FrpsVerkoopEenheid, FrpsAantalDezeLeveringVrrdEenh, FrpsAantalGeleverdVrrdEenh, FrpsAantDecAantal, FrpsAantDecAantalVrrdEenh, FrpsVerkoopEenheidIsVoorraadEenheid, frpsPartijDatumProductie, FrpsPartijCbsLndEigenCodeOorsprong, FrpsPartijCbsLndOmsOorsprong
      from        tabFactuurRegelPartijSerie
                  inner join tabFactuurRegel GelezenRegels     on (GelezenRegels.frFrefGid = @FrefGid and frpsFrGid = frGid)
                  inner join tabFactuurRegel GeschrevenRegels on (GeschrevenRegels.FrFrefGid = @tmpFrefGid and GeschrevenRegels.frRegelNummer = GelezenRegels.frRegelNummer);

      //Hier alle extra regels toevoegen
      //call Trace('FacturerenMaakKopieVoorLeveren > Referentie-extraregels!');
      insert into tabFactuurExtraRegel(
        ferFrefGid, ferRegelNummer, ferSoortRegel, ferTekstOpFactuur, ferPercentage, ferBasisBedrag,
        ferKortToeslBedrag, ferBtwCode, ferBtwPercentage, ferBtwBasis, ferBtwBedrag, ferRegelTotaal,
        ferBerekenOverTarief, ferBerekenOverArtikel, ferBerekenOverEmballage, ferBerekenOverKorting, ferBerekenOverToeslag)
      select
        @tmpFrefGid, ferRegelNummer, ferSoortRegel, ferTekstOpFactuur, ferPercentage, ferBasisBedrag,
        ferKortToeslBedrag, ferBtwCode, ferBtwPercentage, ferBtwBasis, ferBtwBedrag, ferRegelTotaal,
        ferBerekenOverTarief, ferBerekenOverArtikel, ferBerekenOverEmballage, ferBerekenOverKorting, ferBerekenOverToeslag
      from
        tabFactuurExtraRegel
      where
        ferFrefGid = @frefGid;

      // Vrije rubrieken van de net toegevoegde locatieregels
      for @Cursor AS Cursor_LocatieRegelsVrijeRubriek CURSOR FOR
        select frpsGid @frpsGid, ArtPartijGid @ArtPartijGid
        from   tabFactuurRegelPartijSerie inner join tabFactuurRegel on (FrpsFrGid = FrGid and FrSoortRegel = 2) inner join tabArtikel on (ArtSoort = frSoortRegel and ArtCode = frArtCode) inner join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijNummer = frpsPartijNummer
        where  frFrefGid = @tmpFrefGid
      for read only
      do
        //Vrije rubrieken van de spec.regel partij
        if @ArtPartijGid is not null then
          call FactureringOvernemenVrijeRubriekenPartij(1, @FrpsGid, @ArtPartijGid, 0);
        end if;
      end for;

    end loop loopje2; //Referentie-loop
    close cursor_Referenties;
    call FactureringVulAdressenIn(@tmpFkGid, 30, IsNull(@OrkFactuurNawGid, @OrkNawGid));
  end loop loopje1; //Factuurkop-loop
  close cursor_Facturen;

  // Alle orders van facturen waarvan de pakbon niet kan worden afgedrukt (terwijl het wel moet) in de tabel van niet-gefactureerd zetten

  set @PakbonAfdrukken = 0;
  if @IsBatchFactuur <> 0 then
    // Batchfactuur
    if exists(select 1 from tabVasteGegevensOrdersFactureren where isnull(vofPakbonBijFactureren,0) = 1) then
      set @PakbonAfdrukken = 1;
    end if;
// ACW: Pakbonnummer wordt bij baliefactuur in het voorloopscherm ingevuld en hoeft hier dus niet te worden gecontrolerd.
//      Als de pakbon niet zou bestaan, dan is dat hier niet erg.
//  else
//    // Baliefactuur
//    if exists(select 1 from tabVasteGegevensOrdersFactureren where vofDirectIsPakbonAfdrukkenBijLeveren = 1) then
//      set @PakbonAfdrukken = 1;
//    end if;
  end if;

  // Extra lever-controles -> eventueel de niet-te-leveren orders opzijzetten in tabFactuurNietGefactureerd
//  call FacturerenCheckSerienummersPartijen(@FbGid, 3); Is niet nodig -> orders zijn al vrijgegeven voor levering
  // tmp-bestand weer aanmaken voor FacturerenCheckMagazijnVoorraad
  insert into tabTeFacturerenOrders (tfoTeFactVolgOrder, tfoTeFactOrkGid, tfoTeFactOrdNummer, tfoFactNr, tfoOrderTotaal, tfoSessieFbGid)
  select number(*), frefOrkGid, frefOrderNummer, fkFactuurNummer, 0, @FbGid
  from tabFactuurKop inner join tabFactuurReferentie on (frefFkGid = fkGid)
  where FkFbGid = @FbGid;
  // En de controle aanroepen
  call FacturerenCheckMagazijnVoorraad(@FbGid, 3);

  // Extra document-controle -> eventueel de niet-te-leveren orders (pakbon is niet af te drukken) in tabFactuurNietGefactureerd zetten
  if @PakbonAfdrukken = 1 then
    // We drukken ook een pakbon af, dus alle orders eruit waarvan het rapportnummer niet is ingevuld
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, frefOrkGid, 15, 1 //Geen pakbonlayout ingegeven
    from   tabFactuurKop inner join tabFactuurReferentie on frefFkGid = FkGid
    where  fkFbGid = @fbGid and
           ((FkRapNummer is null) or (@IsRapNummerNodig = 0))
           and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); //Komt inderdaad nog niet in de niet-te-factureren lijst voor
  end if;

  // En alle facturen verwijderen waarvan een order in de lijst van niet-te-factureren (leveren) orders is gezet
  // Order wordt in de lijst gezet a.g.v. voorraad- serie- en documentcontroles
  delete from tabfactuurkop
  where FkFbGid = @NewFbGid and
        FkGid in (select frefFkGid from  tabFactuurNietGefactureerd
                                     inner join tabFactuurReferentie on (fngOrkGid = FrefOrkGid)
                                     inner join tabFactuurKop binnen on binnen.fkGid = frefFkGid
                               where fngFbGid = @FbGid and binnen.FkFbGid = @NewFbGid);

  // Verwijderen van pakbonnen die geen regels bevatten ivm alleen tekst of tariefregels
  delete tabfactuurkop where FkFbGid = @NewFbGid
  	and not exists(select 1 from tabFactuurRegel inner join tabFactuurReferentie on frfrefGid = frefgid where FrefFkGid = fkgid);


  if not exists(select 1 from tabFactuurKop where FkFbGid = @NewFbGid) then
    delete from tabfactuurbatch where FbGid = @NewFbGid;
    call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@NewFbGid));
    set @NewFbGid = null;
  else
  end if;

  set @@ErrorTextProcedure = 'FacturerenMaakKopieVoorLeveren';
  //call TraceEind(@@ErrorTextProcedure + ' > @NewFbGid = ' +string(@NewFbGid));
end;


create or replace function FacturerenMaakNieuweFactuur(in @fbGid integer, in @FactuurDatum date, in @LayoutSoort integer, in @OrkGid integer, in @BtcNummer integer, in @LayoutNummer integer, in @IsRapNummerNodig integer) returns integer
begin
  declare @VervalDatum          date;
  declare @IncassoDatum         date;
  declare @KredBepVervalDatum   date;
  declare @FkGid                integer;
  declare @MetFactDeb           integer;

  set @@ErrorTextProcedure = 'FacturerenMaakNieuweFactuur > @fbGid='+string(@fbGid)+', @LayoutSoort='+string(@LayoutSoort)+', @OrkGid='+string(@OrkGid)+', @BtcNummer='+string(@BtcNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  //De factuurkop van de nieuwe factuur aanmaken met de 1e order als reference
  call BerekenVervalDatumFactuur( @FactuurDatum, @BtcNummer, @VervalDatum );
  call BerekenKredBepVervalDatumFactuur( @FactuurDatum, @BtcNummer, @KredBepVervalDatum );

  if exists(select first 1 from tabBetalingsconditie where BtcNummer = @BtcNummer and SoortFactuurBtc = 3 /*Via incasso*/) then
    call BerekenIncassoDatumFactuur(@Vervaldatum, null, @IncassoDatum);
  end if;

  set @MetFactDeb = IsModuleActive('i2'); //Inkoopcombinaties

  insert into tabFactuurkop( fkfbGid,         fkDebNummer,     fkFactDebNummer, fkFactuurNummer_Lengte,
                             fkFactDebZoekCode,
                             fkTekstOrigineelKopie, fkNawBtwNummer,
                             fkTelefoon,      fkTelefoon2,     fkTelefax,       fkFactDebTelefoon,     fkFactDebTelefax, fkEmail,
                             fkValNummer,     fkValCode,
                             fkValOms,        fkOrderDatum,
                             fkFactuurDatum,  fkVervalDatum,   fkIsInclBtw,           fkLeverDatum,
                             fkBtcNummer,     fkBtcPerc,       FkBtcKredBepKortingInclBtw,
                             fkLvcNummer,     fkLvcCode,       fkLvcOms,        fkLvcTekstOpFactuur,   fkOpmRegel,
                             fkBtcBedrag,     fkBtcDatum,      fkTaalGid,       fkTaalCode,            fkRapNummer, fkBtcSoort,
                             fkBankRekNummer, 	 fkBankRekNaam,         fkBankRekAdres,    fkBankRekPostcode,    fkBankRekPlaats,
                             fkIncassoRekNummer, fkIncassoRekNaam,      fkIncassoRekAdres, fkIncassoRekPostcode, fkIncassoRekPlaats,
                             fkIncassoDatum,
                             fkVertCode,          fkVertNaam,
                             fkOCRformcode,     fkOCRdiversen,   fkOCReigenrekening, fkOCRBIC,
                             fkPrintBedragAcceptGiro, fkIsEdi, fkIsAbcLevering, fkMagCode, FkAantalKopieBijFact, FkGewichtIn, FkVolumeIn)
  select  first @fbGid, NawFilDeb.nawfilnummer, NawFilFactDeb.nawfilnummer, 0,
          NawFilFactDeb.NawFilZoekCode,
          0, nawFactDeb.NawBtwNummer,
          AdrDeb.adrTelefoon, AdrDeb.adrTelefoon2, AdrDeb.adrTelefax, AdrFactDeb.adrTelefoon, AdrFactDeb.adrTelefax, AdrFactDeb.AdrEmail,
          OrkValNummer, ValCode,
          OmsValuta, OrkDatum,
          @FactuurDatum, @VervalDatum, OrkInclBtw, OrkLeverdatum,
          OrkBtcNummer, Percentage, BtcKredBepKortingInclBtw,
          LvcNummer, LvcCode, LvcOms, LvcFactuurTekst, DocSluitRegel,
          0, @KredBepVervalDatum, TaalGid, TaalCode, if @LayoutNummer is null then RapNummer else @LayoutNummer endif,
          isnull(SoortFactuurBtc,0),
          NawRek.nawrekBankRekening,
          NawRek.nawrekNaamRekHouder,
          NawRek.nawrekAdresRekHouder,
          NawRek.nawrekPostcodeRekHouder,
          NawRek.nawrekPlaatsRekHouder,
          IncRek.nawrekBankRekening,
          IncRek.nawrekNaamRekHouder,
          IncRek.nawrekAdresRekHouder,
          IncRek.nawrekPostcodeRekHouder,
          IncRek.nawrekPlaatsRekHouder,
          @IncassoDatum,
          vtgCode,
          relVolledigeNaam,
          vgaFormcode, vgaDiversen, vgaEigenrek, vgaBIC,
          PrintBedragAcceptGiro,
          OrkIsEDIorder, OrkIsAbcLevering, (select MagCode from tabMagazijn where MagGid = OrkDefaultMagGid), NawDeb.NawAantalKopieFacturen, ArtVastGewicht, ArtVastVolume

  from    tabOrderKop
          left outer join (tabVertegenwoordiger
          inner join tabRelatie on RelVtgCode = VtgCode) on VtgCode = OrkVtgCode
          // Orderdebiteur
          inner join tabNAW NawDeb on (OrkNawGid = NawDeb.NawGid)
          inner join tabNawFile NawFilDeb on (NawDeb.NawGid = NawFilDeb.NawFilNawGid)
          inner join tabAdres AdrDeb on ( AdrDeb.AdrGid = NawDeb.NawGidVestiging )
          // Factuurdebiteur
          inner join tabNAW NawFactDeb on (if @MetFactDeb = 0 or OrkFactuurNawGid is null then OrkNawGid else OrkFactuurNawGid endif = NawFactDeb.NawGid)
          inner join tabNawFile NawFilFactDeb on (NawFactDeb.NawGid = NawFilFactDeb.NawFilNawGid)
          inner join tabAdres AdrFactDeb on ( AdrFactDeb.AdrGid = NawFactDeb.NawGidVestiging )

          inner join tabValuta on ( ValNummer = OrkValNummer )
          left outer join tabBetalingsconditie     on ( BtcNummer = OrkBtcNummer )
          left outer join tabBetalingsconditieTaal on ( TaalBtcNummer = BtcNummer and BtcTaalGid = NawFactDeb.nawTaalGid )
          left outer join tabLeveringsConditie     on ( OrkLvcNummer = LvcNummer )
          left outer join tabLeveringsConditieTaal on ( TaalLvcNummer = LvcNummer and LvcTaalGid = NawFactDeb.nawTaalGid )
          left outer join tabTaal                  on ( TaalGid =  NawFactDeb.nawTaalGid )
          left outer join tabDocumentLayout        on ( DocLayDocSoort = @LayoutSoort and DocLayTaalGid = if @LayoutSoort in (40, 50, 60) then NawFactDeb.NawTaalGid else NawDeb.NawTaalGid endif)
          left outer join tabDocumentSluitRegel    on ( DocSluitDocSoort = @LayoutSoort and DocSluitTaalGid = NawFactDeb.NawTaalGid )
          left outer join tabNawRekening NawRek    on ( NawRek.NawRekNawGid = NawFactDeb.NawGid and NawRek.nawRekSoort like '%d%' )
          left outer join tabNawRekening IncRek    on ( IncRek.NawRekGid = OrkIncNawRekGid )
          left outer join tabArtikelVasteGegevens  on (artvastsoort    = 2)
// ACCW/VVE: NAW-rapporten worden nu uit de tabNawDocument-tabel gelezen i.p.v. direct uit tabNawFile
//          left outer join tabRapport               on (RapGid = ( if OrkInclBtw = 0 then if (@LayoutSoort in (50,60)) and (NawFilFactDeb.NawFilRapGidExclBtw is not null) then NawFilFactDeb.NawFilRapGidExclBtw else DocLayRapGidExcl endif
//                                                                                    else if (@LayoutSoort in (50,60)) and (NawFilFactDeb.NawFilRapGidInclBtw is not null) then NawFilFactDeb.NawFilRapGidInclBtw else DocLayRapGidIncl endif endif ) ),
          left outer join (tabNawDocument left outer join tabRapDocFormat on NawDocRdfGid = RdfGid)
          																				 on (NawDocNawGid = (if @LayoutSoort in (40, 50, 60) then NawFactDeb.NawGid else NawDeb.NawGid endif) and NawDocDocsoort = @LayoutSoort and
          																				     (NawDocAfdrukVoorwaarde = 0 or (NawDocAfdrukVoorwaarde = 1 and OrkIsEdiOrder = 1) or (NawDocAfdrukVoorwaarde = 2 and OrkIsEdiOrder = 0)) and
          																				     ((NawDocRegelSoort = 0 /* papier */) or
          																				      (NawDocRegelSoort = 2 /* uitvoer */ and rdfSoort  = 0 /* PDF */) or
          																				      (NawDocRegelSoort = 2 /* uitvoer */ and rdfSoort <> 0)
          																				      )
          																				     )
          left outer join tabRapport               on (RapGid = if OrkInclBtw = 0 then isnull(NawDocRapgidExclBTW, DocLayRapGidExcl) else isnull(NawDocRapgidInclBTW,DocLayRapGidIncl) endif),
          tabVasteGegevensAcceptGiro
  where       (OrkGid = @OrkGid)
          and (   (@IsRapNummerNodig = 0)
               or (RapNummer is not null or @LayoutNummer is not null) // Alleen als er ook echt een layout is ingevuld!
               or (@LayoutSoort = 35 /*DL-Pakbon*/) // Als Directe Levering, dan altijd opnemen ivm. historische tabellen
              )
	order by NawDocRegelSoort,rdfSoort;

  if @@rowcount <> 0 then
    set @FkGid = @@Identity;
  end if;

  // Bonnen waarvoor de layout toch niet is ingevuld rapporteren
  if @LayoutNummer is null and @IsRapNummerNodig <> 0 then
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, @OrkGid, 4, 1 // Geen layout ingegeven
    from   tabOrderKop
           inner join tabNAW     NawFactDeb    on (NawFactDeb.NawGid          = if @MetFactDeb = 0 or OrkFactuurNawGid is null then OrkNawGid else OrkFactuurNawGid endif)
           inner join tabNawFile NawFilFactDeb on (NawFilFactDeb.NawFilNawGid = NawFactDeb.NawGid)
           inner join tabNAW     NawDeb        on (OrkNawGid = NawDeb.NawGid)
           left outer join tabDocumentLayout   on ( DocLayDocSoort = @LayoutSoort and DocLayTaalGid = if @LayoutSoort in (40, 50, 60) then NawFactDeb.NawTaalGid else NawDeb.NawTaalGid endif)
//           left outer join tabRapport          on (RapGid = ( if OrkInclBtw = 0 then if (@LayoutSoort in (50,60)) and (NawFilFactDeb.NawFilRapGidExclBtw is not null) then NawFilFactDeb.NawFilRapGidExclBtw else DocLayRapGidExcl endif
//                                                                                else if (@LayoutSoort in (50,60)) and (NawFilFactDeb.NawFilRapGidInclBtw is not null) then NawFilFactDeb.NawFilRapGidInclBtw else DocLayRapGidIncl endif endif ) )
          left outer join tabNawDocument           on (NawDocNawGid = (if @LayoutSoort in (40, 50, 60) then NawFactDeb.NawGid else NawDeb.NawGid endif) and NawDocRegelSoort = 0 and NawDocDocsoort = @LayoutSoort )
          left outer join tabRapport               on (RapGid = if OrkInclBtw = 0 then isnull(NawDocRapgidExclBTW, DocLayRapGidExcl) else isnull(NawDocRapgidInclBTW,DocLayRapGidIncl) endif)
    where      (OrkGid = @OrkGid)
           and (@OrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid))
           and (RapNummer is null);
  end if;

  set @@ErrorTextProcedure = 'FacturerenMaakNieuweFactuur > @FkGid='+string(@FkGid);
  //call TraceEind(@@ErrorTextProcedure);
  return(@FkGid);
end;


create or replace function FacturerenMaakNieuweReferentie(in @fkGid integer, in @OrkGid integer)
returns integer
begin
  declare @frefGid integer;
  declare @OrkVerzendAdres integer;
  declare @GebrNaw integer;
  declare @GebrAdres integer;
  declare @VerzendAdresNummer integer;
  declare @AdresCorr integer;
  declare @AdresVest integer;
  declare @OrkNawGid integer;
  declare @ProjCode nchar(10);
  declare @ProjLeider nchar(40);
  declare @ProjSoort smallint;

  set @@ErrorTextProcedure = 'FacturerenMaakNieuweReferentie > @fkGid='+string(@fkGid)+', @OrkGid='+string(@OrkGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select (if OrkFactuurNawGid is null then OrkNawGid else OrkFactuurNawGid endif), OrkVerzendAdres, OrkAdrGid, OrkNawGid
  into   @GebrNaw, @OrkVerzendAdres, @VerzendAdresNummer, @OrkNawGid
  from tabOrderKop where OrkGid = @OrkGid;

  select nawGidCorrespondentie, NawGidVestiging
  into   @AdresCorr,            @AdresVest
  from   tabNaw
         inner join tabNawFile on (nawgid= nawfilnawgid and nawFilFonId='D')
  where  NawGid = @OrkNawGid;

  if (select fbSoortBatch from tabFactuurBatch where FbGid = (select FkFbGid from tabFactuurKop where FkGid = @FkGid) ) = 65 then
    select ProjCode, ProjSoort, RelVolledigeNaam into @ProjCode, @ProjSoort, @ProjLeider from tabOrderKop inner join tabProjectFactuurVoorstelKop on OrkPfvkGid = PfvkGid inner join tabProject on ProjGid = PfvkProjGid inner join tabRelatie on RelGid = ProjProjLeiderRelGid where OrkGid = @OrkGid;
  else
    set @ProjCode = null;
  end if;

  case @OrkVerzendadres
  when 0 then
    //Verzendadres = vestigingsadres
    set @GebrAdres = @AdresCorr
  when 1 then
    //Verzendadres = correspondentieadres
    set @GebrAdres = @AdresVest
  when 2 then
    //Verzendadres = verzendadres
    set @GebrAdres = @VerzendAdresNummer
  when 3 then
    set @GebrAdres = (select NawGidCorrespondentie from tabOrderKop inner join tabNaw on NawGid = OrkFactuurNawGid inner join tabNawFile on NawFilNawGid = NawGid where @OrkGid = OrkGid and NawFilFonId='D')
  when 4 then
    set @GebrAdres = (select NawGidVestiging from tabOrderKop inner join tabNaw on NawGid = OrkFactuurNawGid inner join tabNawFile on NawFilNawGid = NawGid where @OrkGid = OrkGid and NawFilFonId='D')
  when 5 then
    set @GebrAdres = @VerzendAdresNummer
  end case;

  //Eerst de referentieregel
  insert into tabFactuurReferentie( frefFkGid, frefOrkGid, frefPfvkGid, frefOrderNummer, frefOrderAangemaaktOp, frefOrderAangemaaktDoor, frefOrderDebNummer, frefOrderDebAdresNaam1, frefOrderDebAdresNaam2, frefContactVanOrder, frefOms, frefExternId, frefOffertenummer, frefOrderDatum, frefLeverDatum,
                                    frefVtgCode, frefVtgVoornaam, frefVtgNaam, frefVtgZoekCode, frefVtgTelefoon1, frefEdiBuffer, frefOrderFactDebNummer, frefOrderOmzDebNummer, frefOrderOmzDebNaam, frefOrderPrijzenDebNummer, frefOrderPrijzenDebNaam, frefOrderIsInkoopcombinatie, frefOrderVerzendAdres, frefOrderFactuurAdres, frefOrderEindAdres,
                                    frefOrderReferentie, frefEmailExtraTekst, frefOrderOpmerking, frefLvcCode, frefLvcNummer, frefLvcOms, frefLvcTekstOpFactuur, frefOrderTotaalExBtw, frefOrderTotaalIncBtw, frefProjCode, frefProjSoort, FrefProjLeiderRelVolledigeNaam, FrefVrvNaam, FrefVrvIsAutoAfdrukken, FrefVrvRapNummer, FrefVervoerGewichtEenheid, FrefVervoerVolumeEenheid,
                                    FrefCbsMeenemenInAangifte, FrefCbsCoCode, FrefCbsGsCode, FrefCbsLandBestemLndEigenCode, FrefCbsLandBestemLndOms, FrefCbsVgCode, FrefCbsVgPlaatsnaam, FrefCbsSsCode, FrefCbsVwCode,
                                    FrefKMGecontroleerdDoorHandcomputer, FrefKMGecontroleerdDoorMedewerker, FrefKMGecontroleerdOp, FrefKMGeimporteerdOp, FrefKMGepicktDoorHandcomputer, FrefKMGepicktDoorMedewerker,
                                    FrefKMGepicktOp, FrefKMHandcomputer, FrefKMHeeftAfwijkingInControle, FrefKMInBehandelingTerControleOp, FrefKMInBehandelingVanaf, FrefKMIsAanvulOrder, FrefKMLocatieAanvulOrder,
                                    FrefKMPickorderStatus, FrefKMToegewezenOp, FrefKMToegewezenTerControleOp, FrefNawBtwNummer)
  select    @FkGid, @OrkGid, OrkPfvkGid, OrkNummer, OrkAangemaaktOp, OrkAangemaaktDoor, OrkNawFile.NawFilNummer, OrkAdr.AdrNaam1, OrkAdr.AdrNaam2, relatie1.relVolledigeNaam, OrkReferentie, OrkExternId, OokOffertenummer, OrkDatum, OrkLeverDatum,
            vtgCode, Relatie2.relVoornaam, Relatie2.relVolledigeNaam, '', Relatie2.relTelefoon, OrkEDIBuffer, IsNull(FactNaw.NawFilNummer, OrkNawFile.NawFilNummer), OmzNawFile.NawFilNummer, OmzAdr.AdrNaam1, PrijsNawFile.NawFilNummer, PrijsAdr.AdrNaam1, OrkIsInkoopcombinatie, OrkVerzendAdres, OrkFactuurAdres, OrkEindAdres,
            OrkReferentie, OrkEmailExtraTekst, OrdOpmOpmerking, LvcCode, LvcNummer, LvcOms, LvcFactuurTekst, OrkTotaalExclBtw, OrkTotaalInclBtw, @ProjCode, @ProjSoort, @ProjLeider, VrvNaam, VrvIsAutoAfdrukken, RapNummer, ArtVastGewicht, ArtVastVolume,
            OrkCbsMeenemenInAangifte, CbsCoCode, CbsGsCode, CbsLandBestem.LndEigenCode, CbsLandBestem.LndOms, PtnCbsVerkeersGebied, PtnNaam, CbsSsCode, CbsVwCode,
            OrkKMGecontroleerdDoorHandcomputer, OrkKMGecontroleerdDoorMedewerker, OrkKMGecontroleerdOp, OrkKMGeimporteerdOp, OrkKMGepicktDoorHandcomputer, OrkKMGepicktDoorMedewerker,
            OrkKMGepicktOp, OrkKMHandcomputer, OrkKMHeeftAfwijkingInControle, OrkKMInBehandelingTerControleOp, OrkKMInBehandelingVanaf, OrkKMIsAanvulOrder, OrkKMLocatieAanvulOrder,
            OrkKMPickorderStatus, OrkKMToegewezenOp, OrkKMToegewezenTerControleOp, OrkNaw.NawBtwNummer
  from      tabOrderKop
            inner join (tabNaw OrkNaw
                        inner join tabNawFile OrkNawFile on OrkNawFile.NawFilNawGid = OrkNaw.NawGid and OrkNawFile.NawFilFonId = 'D'
            	        inner join tabAdres OrkAdr on OrkNaw.NawGidCorrespondentie = OrkAdr.AdrGid
            		)on OrkNawGid = OrkNaw.NawGid
            left outer join tabRelatie AS relatie1 on OrkRelGid = relatie1.RelGid
            left outer join (tabVertegenwoordiger
                             inner join tabRelatie AS relatie2 ON relatie2.RelVtgCode = VtgCode
                            ) on (VtgCode = OrkVtgCode)
            left outer join tabNawFile FactNaw  on  FactNaw.NawFilNawGid = OrkFactuurNawGid
            left outer join (tabNaw PrijsNaw
                             inner join tabNawFile PrijsNawFile on PrijsNawFile.NawFilNawGid = PrijsNaw.NawGid and PrijsNawFile.NawFilFonId = 'D'
                             inner join tabAdres PrijsAdr on PrijsNaw.NawGidVestiging = PrijsAdr.AdrGid
            		) on PrijsNaw.NawGid = OrkNawGidPrijzen
            left outer join (tabNaw OmzNaw
                             inner join tabNawFile OmzNawFile on OmzNawFile.NawFilNawGid = OmzNaw.NawGid and OmzNawFile.NawFilFonId = 'D'
                             inner join tabAdres OmzAdr on OmzNaw.NawGidVestiging = OmzAdr.AdrGid
            		)on   OmzNaw.NawGid = OrkNawGidOmzet
            left outer join tabOrderOpmerkingen on OrdOpmOrkGid = OrkGid
            left outer join tabLeveringsConditie     on ( OrkLvcNummer = LvcNummer )
            left outer join tabLeveringsConditieTaal on ( TaalLvcNummer = LvcNummer and LvcTaalGid = OrkNaw.nawTaalGid )
            left outer join tabVervoerder on (OrkVrvGid = VrvGid)
            left outer join tabRapport on (VrvRapGid = RapGid)
            left outer join tabArtikelVasteGegevens on (ArtVastSoort = 2)

            left outer join tabCbsContainer          on CbsCoGid = OrkCbsCoGid
            left outer join tabCbsGoederenStroom     on CbsGsGid = OrkCbsGsGid
            left outer join tabLand CbsLandBestem    on CbsLandBestem.LndGid = OrkCbslndGIDBestemming
            left outer join tabPlaatsnaam            on PtnGid = OrkCbsPtnGidVerkeersgebied
            left outer join tabCbsStatistischStelsel on CbsSsGid = OrkCbsSsGid
            left outer join tabCbsVervoerwijze       on CbsVwGid = OrkCbsVwGid

            left outer join tabOfferteOrderKoppeling on (OokOrkGid = OrkGid)
  where     OrkGid = @OrkGid;

  set @frefGid = @@Identity;
  //call Trace('@frefGid='+string(@frefGid));

  set @@ErrorTextProcedure = 'FacturerenMaakNieuweReferentie > @frefGid='+string(@frefGid);
  //call TraceEind(@@ErrorTextProcedure);

  return(@frefGid);


end;


//$Workfile: FacturerenMaakRekeningObvProjectGroep.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenMaakRekeningObvProjectGroep') then
  drop procedure FacturerenMaakRekeningObvProjectGroep;
end if;

create procedure FacturerenMaakRekeningObvProjectGroep(in @ProjGrpGid integer, in @ParSoort integer, out @ProjGrpSrtRksGid integer)
begin
	set @@ErrorTextProcedure = 'FacturerenMaakRekeningObvProjectGroep(@ProjGrpGid='+string(@ProjGrpGid)+', @ParSoort='+string(@ParSoort)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  //Voorraadrekening opzoeken en evt. aanmaken
  set @ProjGrpSrtRksGid = null;
  select ProjGrpSrtRksGid into @ProjGrpSrtRksGid from tabProjectGroepSoort where ProjGrpSrtProjGrpGid = @ProjGrpGid and ProjGrpSrtParSoort = @ParSoort;
  if @ProjGrpSrtRksGid is null then
    //Aanmaken van de grootboekrekening voor kostprijs: <paragraaf>+<kostprijsgroep>
    call ProjectGroepsoortenPerStuk( @ProjGrpGid, @ParSoort);
    select ProjGrpSrtRksGid into @ProjGrpSrtRksGid from tabProjectGroepSoort where ProjGrpSrtProjGrpGid = @ProjGrpGid and ProjGrpSrtParSoort = @ParSoort;
  end if;

  //call TraceEind('FacturerenMaakRekeningObvProjectGroep(@ProjGrpSrtRksGid='+string(@ProjGrpSrtRksGid)+')');

end;


create or replace procedure FacturerenNaLockFout(in @LockGid integer)
begin
  declare @Primkey nchar(20);
  declare @FbIsVerwerkt integer;

  //Als een gebruiker tijdens factureren, afdrukken pakbon / orderbevestiging of pro-formanota eruit geknald is, dan wordt
  //deze routine aangeroepen om de restjes op te lossen

  set @@ErrorTextProcedure = 'FacturerenNaLockFout > '+string(@LockGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select substr(qLockPKey, Locate(qLockPKey,'=')+1,10) into @PrimKey from qtabLock where qLockTableName='tabFactuurBatch' and qLockGid=@LockGid;

  //call Trace('FactuurBatchGid = '+string(@PrimKey));
  if @PrimKey is not null then

    update qtabLock set qLockConnection = @@spid, qLockLoginTime = @@LoginTime where qLockGid=@LockGid;
    select FbIsVerwerkt into @FbIsVerwerkt from tabFactuurBatch where FbGid = @PrimKey;
    if isnull(@FbIsVerwerkt,0) = 0 then
      // Is niet verwerkt -> annuleren
      call FacturerenOrdersAnnuleren( @PrimKey, null);
    else
      // Is wel al verwerkt -> doorgaan
      call FacturerenVerwijderFactuurLocks(@PrimKey, null, 0);
      call FacturerenOrdersVerwijderen(@PrimKey, null);
    end if;

    delete qtabLock where qLockGid=@LockGid;
  end if;

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure FacturerenOrdersAnnuleren( in @fbGid integer, in @IgnoreOrkGid integer)
begin
  //Een factuurbatch wordt geheel ongedaan gemaakt (dus ook de eventuele boekingsgang wordt verwijderd!)
  //(Deze wordt gebruikt als de gebruiker eruitgeknald is of als er niet is gefactureerd, maar een pakbon/proforma-nota/orderbevestiging is afgedrukt)
  //StProc geldt ook voor leveren!
  declare @OrkGid       integer;
  declare @VorigeOrkGid integer;
  declare @BoekgangGid  integer;
  declare @DocSoort     integer;
  declare @AcbGid       integer;
  declare @VerwerktCount integer = 0;

  set @@ErrorTextProcedure = 'FacturerenOrdersAnnuleren > @FbGid = '+string(@FbGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //Eventuele factuurboekingsgang verwijderen
  select fbboekganggid, fbSoortBatch into @Boekganggid, @DocSoort from tabFactuurBatch where fbGid = @fbGid;

  select count(1) into @VerwerktCount from tabFactuurKop inner join tabFactuurBatch on FkFbGid = FbGid where FbGid = @FbGid and FbSoortBatch in (30,35,50,60,65) and FkFactStatus in (1,2);

  if @VerwerktCount > 0 then
    // BEGIN Er is iets verwerkt, dat nooit weggooien!
    delete tabFactuurKop where FkFbGid = @FbGid and IsNull(FkFactStatus,0) = 0;
    delete tabAcceptGiro where exists(select 1 from tabFactuurBatch inner join tabAcceptGiroBatch on AcbFbGid = @FbGid where AcbGid = AccAcbGid) and not exists(select 1 from tabFactuurKop where FkFactuurNummer = AccFactuurNummer);
    update tabFactuurBatch set fbIsVerwerkt = 2 where fbGid = @FbGid and IsNull(fbIsVerwerkt,0) = 0 and FbSoortBatch = 30 and FbPakbonAfgedrukt = 0;
    update tabFactuurBatch set fbIsVerwerkt = 1 where fbGid = @FbGid and IsNull(fbIsVerwerkt,0) = 0;
    if exists(select 1 from tabFactuurBatch where FbGid = @FbGid and FbSoortBatch in (30,35,50,60,65) and FbIsVerwerkt = 1) then
      call FacturerenOrdersVerwijderen(@FbGid, null);
    end if;
	  //De orderlocks terugzetten
	  call FacturerenVerwijderFactuurLocks(@fbGid, @IgnoreOrkGid, 0);
    // END Er is iets verwerkt, dat nooit weggooien!
  else
    // BEGIN Er is niets verwerkt, alles wegggooien
    delete from tabfactuuroverzichtValuta where fovFbGid = @FbGid;
    delete from tabfactuuroverzichtBTW where fobFbGid = @FbGid;
    delete from tabfactuuroverzichtOpbrengstgroep where fooFbGid = @FbGid;
    update tabFactuurBatch set fbboekganggid = null where fbGid = @fbGid;
    if @boekganggid is not null then
	    delete from tabBoekingsgang where BoekgangGid = @boekganggid;
	  end if;
    call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'Factuuroverzicht', @FbGid);

    //De niet-bestaande statussen aanmaken
    insert into tabOrderDocGegevens(OrdDocDocSoort, OrdDocOrkGid, OrdDocGegAfgedrukt, OrdDocGegGewijzigdNaAfdruk, OrdDocLaatstGebruiktNr )
    select @DocSoort, frefOrkGid, 0, 0, fkFactuurNummer
    from   tabFactuurKop inner join tabFactuurReferentie on FrefFkGid = FkGid
    where  FkFbGid = @FbGid
           and not exists( select 1 from tabOrderDocGegevens where OrdDocOrkGid = frefOrkGid and OrdDocDocSoort = @DocSoort )
           and fkFactuurNummer is not null
           and frefOrkGid in (select OrkGid from tabOrderkop);

    // --- Acceptgiros ---
    select first AcbGid into @AcbGid from tabAcceptGiroBatch where AcbfbGid = @FbGid;
    //call Trace('@AcbGid='+string(@AcbGid));
    if @AcbGid is not null then
      // De acceptgirobatch verwijderen
      delete from tabAcceptGiroBatch where AcbGid = @AcbGid;
      // De eventuele lock op acceptgirobatch verwijderen
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabAcceptGiroBatch', 'AcbGid='+string(@AcbGid));
    end if;

	  //De orderlocks terugzetten
	  call FacturerenVerwijderFactuurLocks(@fbGid, @IgnoreOrkGid, 0);

  	//Ook de status van 'niet gefactureerde orders' weer verwijderen
	  delete from tabFactuurNietGefactureerd where fngFbGid = @fbGid;

    //En de factuurbatch verwijderen
    //call Trace('Verwijder batch');
    delete from tabFactuurBatch where fbGid = @fbGid;
    // END Er is niets verwerkt, alles wegggooien
  end if;

  //Als laatste de lock verwijderen
  //call Trace( 'Reset lock' );
  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid));

  //call TraceEind(@@ErrorTextProcedure);

end;

//$Workfile: FacturerenOrdersUpdateStatus.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenOrdersUpdateStatus') then
  drop procedure FacturerenOrdersUpdateStatus;
end if;

create procedure FacturerenOrdersUpdateStatus( in @fkGid integer )
begin
  //Een batch wordt in zijn geheel als 'afgedrukt' beschouwd.
  //We moeten dus de document-statussen van de orders updaten voor het betreffende soort document
  //en het gebruikte nummer onthouden, samen met de status als 'zijnde afgedrukt'
  //StProc geldt ook voor leveren!
  declare @DocSoort               integer;
  declare @OrkEersteActie         smallint;

  declare @vofStatusIsVrijNaFactureren  smallint;
  declare @vofStatusIsVrijNaleveren     smallint;

  set @@ErrorTextProcedure = 'FacturerenOrdersUpdateStatus > @FkGid = '+string(@FkGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //documentsoort ophalen
  select fbSoortBatch into @DocSoort from tabFactuurBatch where fbGid = (select fkfbgid from tabFactuurKop where fkgid = @FkGid);

  //De bestaande statussen updaten
  if @DocSoort <> 30 or isnull((select first vofLevIsPakbonAfdrukken from tabVasteGegevensOrdersFactureren),1) = 1 then
    //Alleen als het geen pakbon is OF de pakbon moest ook worden afgedrukt
    update tabOrderDocGegevens
    set    OrdDocGegAfgedrukt     = 1,
           OrdDocGegAfgedruktOp   = now(),
           OrdDocAfgedruktDoor    = @@Gebruikercode,
           OrdDocGegGewijzigdNaAfdruk = 0,
           OrdDocGewijzigdDoor    = '',
           OrdDocLaatstGebruiktNr = fkFactuurNummer
    from   tabFactuurKop inner join tabFactuurReferentie on ( FrefFkGid = FkGid )
    where  FkGid          = @FkGid
           and OrdDocOrkGid = frefOrkGid
           and OrdDocDocSoort  = @DocSoort;

//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen

    //De niet-bestaande statussen aanmaken
    insert into tabOrderDocGegevens(OrdDocDocSoort, OrdDocOrkGid, OrdDocGegAfgedrukt, OrdDocGegAfgedruktOp, OrdDocAfgedruktDoor, OrdDocGegGewijzigdNaAfdruk, OrdDocGewijzigdDoor, OrdDocLaatstGebruiktNr )
    select @DocSoort, frefOrkGid, 1, now(), @@Gebruikercode, 0, '', fkFactuurNummer
    from   tabFactuurKop inner join tabFactuurReferentie on FrefFkGid = FkGid inner join tabOrderkop on OrkGid = frefOrkGid
    where  FkGid = @FkGid
           and not exists( select 1 from tabOrderDocGegevens where OrdDocOrkGid = frefOrkGid and OrdDocDocSoort = @DocSoort );

//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen

  end if;

  //Update datum van levering (=docsoort 110)
  if @DocSoort = 30 then
    update tabOrderDocGegevens
    set    OrdDocGegAfgedrukt     = 1,
           OrdDocGegAfgedruktOp   = now(),
           OrdDocAfgedruktDoor    = @@Gebruikercode,
           OrdDocGegGewijzigdNaAfdruk = 0,
           OrdDocGewijzigdDoor    = '',
           OrdDocLaatstGebruiktNr = fkFactuurNummer
    from   tabFactuurKop inner join tabFactuurReferentie on ( FrefFkGid = FkGid )
    where  FkGid          = @FkGid
           and OrdDocOrkGid = frefOrkGid
           and OrdDocDocSoort  = 110;  //110 = Laatste levering

//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen

    insert into tabOrderDocGegevens(OrdDocDocSoort, OrdDocOrkGid, OrdDocGegAfgedrukt, OrdDocGegAfgedruktOp, OrdDocAfgedruktDoor, OrdDocGegGewijzigdNaAfdruk, OrdDocGewijzigdDoor, OrdDocLaatstGebruiktNr )
    select 110, frefOrkGid, 1, now(), @@Gebruikercode, 0, '', fkFactuurNummer
    from   tabFactuurKop inner join tabFactuurReferentie on FrefFkGid = FkGid inner join tabOrderkop on OrkGid = frefOrkGid
    where  FkGid = @FkGid
           and not exists( select 1 from tabOrderDocGegevens where OrdDocOrkGid = frefOrkGid and OrdDocDocSoort = 110 );

//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen

    //Orders vrijgeven voor factureren na 1e uitlevering van de order ?
    if exists(select 1 from tabvastegegevensordersfactureren where vofFactAutomVrijgeven = 3) then
      update tabOrderKop
      set    OrkVrijVoorFaktureren = 1
      where  OrkGid in (select frefOrkGid from tabFactuurReferentie inner join tabFactuurKop on (FkGid = FrefFkGid) where FkGid = @FkGid);
//      commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen
    end if;
  end if;

  //De 'eerste actie' aan de orders toevoegen als die nog niet bestond (ivm. vervolgacties)
  set @OrkEersteActie = 0; //geen actie
  if @DocSoort = 30 then //Pakbon
    set @OrkEersteActie = 2; //Leveren
  else
    if @DocSoort in (50,60) then //Factureren
      set @OrkEersteActie = 1; //Factureren
    end if;
  end if;
  //call Trace('Update de eerste actie van de order naar @OrkEersteActie='+string(@OrkEersteActie));
  if isnull(@OrkEersteActie,0) <> 0 then
    update taborderkop
    set    OrkEersteActie = @OrkEersteActie
    where  OrkEersteActie = 0 and
           OrkGid in (select frefOrkGid from tabFactuurReferentie inner join tabFactuurKop on (FkGid = FrefFkGid) where FkGid = @FkGid);
//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen
  end if;

  //Orders blokkeren voor muteren indien zo ingesteld voor het document (vanaf voorraadversie functioneel!)
  if exists( select 1 from tabDocument where DocSoort = @DocSoort and DocOrdMuterenGeblokkeerdNaAfdruk = 1 ) then
    update tabOrderKop
    set    OrkIsGeblokkeerdVoorMuteren = 1
    from   tabFactuurKop inner join tabFactuurReferentie on (FrefFkGid = FkGid)
    where fkGid = @FkGid and OrkGid = frefOrkGid;
//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen
  end if;

  select first vofStatusIsVrijNaFactureren, vofStatusIsVrijNaleveren into @vofStatusIsVrijNaFactureren, @vofStatusIsVrijNaleveren from tabVasteGegevensOrdersFactureren;
  if @DocSoort = 30 then //Pakbon
    // Geleverd, eventueel van vrijgave afhalen!

    update tabOrderKop
    set    OrkVrijVoorVerzamelLijst = if @vofStatusIsVrijNaleveren = 0 then 0 else 1 endif,
           OrkVerzamelLijstAfgedrukt = 0,
           OrkVerzamelLijstVerwerkt  = 0,
           OrkVrijVoorLevering = if (OrkIsVerzamellijstGebruiken = 1) or (@vofStatusIsVrijNaleveren = 0) then 0 else 1 endif
    from   tabFactuurKop inner join tabFactuurReferentie on (FrefFkGid = FkGid)
    where fkGid = @FkGid and OrkGid = frefOrkGid and exists(select 1 from tabOrderRegel where OrkGid = OrrOrkGid and OrrRegelSoort = 2 and OrrAantalBesteld <> OrrAantalGeleverd); // RS nav bug #12260 : Alleen orders waar nog iets te leveren valt de status van terugzetten ;
//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen
  end if;

  if @DocSoort in (50,60) then //Factuur
    // Gefactureerd, eventueel van vrijgave afhalen!
    update tabOrderKop
    set    OrkVrijVoorFaktureren = if @vofStatusIsVrijNaFactureren = 0 then 0 else 1 endif
    from   tabFactuurKop inner join tabFactuurReferentie on (FrefFkGid = FkGid)
    where fkGid = @FkGid and OrkGid = frefOrkGid;
//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen
  end if;

  // Als laatste meedelen dat de factureergang volledig is verwerkt
  update tabFactuurKop set fkFactStatus = 1 where FkGid = @FkGid;
//  commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure FacturerenOrdersVerwijderen(in @fbGid integer, in @IgnoreOrkGid integer )
begin
  //De orders die zijn gefactureerd/geleverd verwijderen (of in de historie zetten)
  //(Hiermee is de factureer- resp. leveringslag beeindigd)
  declare @FactuurSoort integer;
  declare @OrkGid       integer;
  declare @IsWegTekst   integer; //0=Niet, 1=na factureren, 2=na leveren, 3=na factureren *en* leveren
  declare @IsWegArtikel integer; //0=Niet, 1=na factureren
  declare @IsWegTarief  integer; //0=Niet, 1=na factureren, 3=na factureren *en* leveren
  declare @LevOokTekst  integer;
  declare @LevOokTarief integer;
  declare @tmp          integer;
  declare @OrderBestaat integer;
  declare @FkGid	      integer;

  declare cursor_FactuurKop dynamic scroll cursor for
    select FkGid from tabFactuurKop where fkFbGid = @FbGid
  for read only;

  for @Cursor AS cursor_Orders_NietGefact cursor for
    select fngOrkGid @fngOrkGid, OrkPfvkGid @PfvkGid
    from   tabFactuurNietGefactureerd inner join tabOrderKop on fngOrkGid = OrkGid
    where  fngFbGid = @FbGid and fngLockedByMe = 1 and fngOrkGid <> isnull(@IgnoreOrkGid,-1)
    for read only
  do
    call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @fngOrkGid);
    if (select fbSoortBatch from tabFactuurBatch where FbGid = @FbGid) = 65 then
      delete tabOrderKop where OrkGid = @fngOrkGid;
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabProjectFactuurVoorstelKop', @PfvkGid);
    end if;
  end for;

  set @@ErrorTextProcedure = 'Begin FacturerenOrdersVerwijderen > @fbGid = ' + string(@FbGid);
  //call Trace(@@ErrorTextProcedure);

  //Opvragen van het soort facturering
  select fbSoortBatch into @FactuurSoort from tabFactuurBatch where FbGid = @FbGid;

  // Voor de zekerheid gewoon de OrderUpdate aanroepen (ivm. directe facturering)
  //call Trace('!!!-> UpdateOrderAantallen komt uit FacturerenOrdersVerwijderen');
  open cursor_FactuurKop;
  LoopFacturen:
  Loop
    Fetch next cursor_FactuurKop into @FkGid;
    if (sqlstate = '02000') then
      leave LoopFacturen;
    end if;
    call FacturerenUpdateOrderAantallen(@FkGid, @IgnoreOrkGid);
    //call Trace('FacturerenUpdateOrderAantallen voor factuur->'+string(@FkGid));
  end loop LoopFacturen;
  close cursor_FactuurKop;

  call FacturerenOrdersVerwijderenBatch(@FbGid);

  //Als laatste de lock verwijderen
  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid));

  set @@ErrorTextProcedure = 'Einde FacturerenOrdersVerwijderen';
  //call Trace(@@ErrorTextProcedure);
end;


//$Workfile: FacturerenOrdersVerwijderenBatch.sp $ $Revision: 3 $ $Modtime: 1-10-10 8:50 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenOrdersVerwijderenBatch') then
  drop procedure FacturerenOrdersVerwijderenBatch;
end if;

create procedure FacturerenOrdersVerwijderenBatch(in @FbGid integer)
begin
  declare @FactuurSoort integer;
  declare @AcbGid       integer;


  set @@ErrorTextProcedure = 'FacturerenOrdersVerwijderenBatch > @fbGid='+string(@FbGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select fbSoortBatch into @FactuurSoort from tabFactuurBatch where FbGid = @FbGid;

  // Acceptgirobatch lezen
  select first AcbGid into @AcbGid from tabAcceptGiroBatch where AcbfbGid = @FbGid;

  // Factuurbatch verwijderen (Als het geen pakbon of factuurwas, dan is die al bij FacturerenOrdersVerwijderen verwijderd!!)
  if (@FactuurSoort in (50,60) and (select IsModuleActive('f3')) = 0) or  //Geen factuurhistorie?
     (@FactuurSoort in (30,35) and (select IsModuleActive('u1')) = 0)  then     //Geen leverhistorie? VOORLOPIG NOG DE VERKEERDE VERSIECODE!!!

    //Factuurbatch verwijderen als we geen factureerhistorie en/of uitlever- hebben
    //Nieuw per 16-2-05: Ook de factuurbatch wordt pas verwijderd op het moment dat de overzicthen zijn afgedrukt
    delete from tabfactuurbatch where fbGid = @fbGid and fbIsVerwerkt = 2;

    // Eventueel ook de bijbehorende acceptgirobatch verwijderen
    if @AcbGid is not null then
      // De acceptgirobatch verwijderen,, (alleen als bijbehorende factuurbatch al is verwijderd !)
      delete from tabAcceptGiroBatch where AcbGid = @AcbGid and not exists(select 1 from tabfactuurbatch where @FbGid = FbGid);
    end if;

  end if;

  // De eventuele lock op acceptgirobatch verwijderen
  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabAcceptGiroBatch', 'AcbGid='+string(@AcbGid));

  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: FacturerenSluitenBoekingsgang.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenSluitenBoekingsgang') then
  drop procedure FacturerenSluitenBoekingsgang;
end if;

create procedure FacturerenSluitenBoekingsgang(in @BoekgangGid integer, in @fbGid integer, in @LayoutSoort integer)
begin
	set @@ErrorTextProcedure = 'FacturerenSluitenBoekingsgang(@BoekgangGid='+string(@BoekgangGid)+', @fbGid='+string(@fbGid)+', @LayoutSoort='+string(@LayoutSoort)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @LayoutSoort <> 60 then
    //Afsluiten van boekingsgang indien batchfacturering
    //Baliefacturering blijft openstaan!!
    update tabBoekingsgang set BoekGangInGebruik = 0 where BoekgangGid = @BoekgangGid;
  end if;

  update tabFactuurBatch set fbBoekganggid = @BoekgangGid where fbGid = @fbGid;

  //call TraceEind('FacturerenSluitenBoekingsgang');

end;


create or replace procedure FacturerenToevoegenOrderRegelGegevens(
  in @SoortFact       smallint, // 0 = fact. Batch, 1 = fact. direct, 2 = orderbev., 3 = Pakbon, 4 = Proforma, 5 = Projectfactuur, 6 = Directe levering
  in @FrefGid         integer,
  in @DebTaalGid      integer,
  in @DefTaalGid      integer,
  in @Stukskorting    smallint,
  in @ObvAantal       smallint,
  in @OrkGid          integer,
  in @vofLevOokTarief smallint,
  in @vofLevOokTekst  smallint,
  in @LeverDatum      date
)
begin
  declare @frpsGarantieTmDatum  date;
  declare @frpsGarantieBepaling long nvarchar;
  declare @AantDeciValuta       integer;
  declare @FbGid                integer;
  declare @MoetDatumUpdaten    smallint;
  declare @MoetBepalingUpdaten smallint;

  declare @DLVrrdEenh        numeric(15,3);
  declare @DLVerkEenh        numeric(15,3);
  declare @DLVerkEenheidNaam nchar(20);
  declare @DLIsVrrdEenh      smallint;
  declare @DLFlooredVerkEenh numeric(15,3);
  declare @DLtp              numeric(15,3);
  declare @DLtmp             numeric(15,3);

  //constanten
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  //call Trace('Begin FacturerenToevoegenOrderRegelGegevens > @FrefGid=' + string(@FrefGid) + ', @DebTaalGid=' + string(@DebTaalGid)+', @DefTaalGid=' + string(@DefTaalGid)+', @Stukskorting=' + string(@Stukskorting) + ', @ObvAantal=' + string(@ObvAantal) + ', @OrkGid=' + string(@OrkGid) + ', @vofLevOokTarief=' + string(@vofLevOokTarief) + ', @vofLevOokTekst=' + string(@vofLevOokTekst));

  //ACW 17-09-2010: Uitbreiding DL: We hebben een FbGid nodig om de juiste verkooporderregels te pakken
  if @SoortFact = 6 then
    select FkFbGid into @FbGid from tabFactuurKop inner join tabFactuurReferentie on (FkGid = frefFkGid) where frefGid = @FrefGid;
  end if;

  select DecimalenRegel * 2 into @AantDeciValuta from tabValuta where ValNummer = (select fkValNummer from tabFactuurKop inner join tabFactuurReferentie on (frefFkGid = FkGid) where frefGid = @FrefGid);

  insert into tabFactuurRegel(
           frFrefGid, frOrrGid, FrPfvrGid, FrExternID, frRegelNummer, frSoortRegel, frOrrVervolgMasterOrrGid,
           frTekstOpFactuur,
           frArtCode, frArtZoekCode, frArtOms, frArtEanCode, frArtEanCodeVrrdEenh, frOpbrGrpNummer, frOrrArtPartijNummer, frIsAantal, frAantalBesteld, FrAantalBesteldVrrdEenh,
           FrVerkoopEenheid, FrVerkoopEenheidIsVoorraadEenheid, FrEenheidPrijsPer, FrAantalVrrdEenhInVerkEenh, FrAantalVrrdEenhInVerkEenhMagAfwijken, FrAantDecAantalVrrdEenh,
           frAantalGeleverd, frAantalDezeLevering, FrAantalDezeLeveringVrrdEenh, FrAantalGeleverdVrrdEenh, FrAantalInBackorderVrrdEenh,
           frAantalGefactureerd, frAantalDezeFacturering, FrAantalDezeFactureringVrrdEenh, FrAantalGefactureerdVrrdEenh,
           frAantalInBackorder,
           frBrutoPrijsPeenheid, frKostprijs, frPrijsPer, frOmsEenheid,
           frKorting1Bedrag,
           frKorting1Perc,
           frKorting2Perc,
           frBtwCode, frBtwPercentage,
           frRegelTotaal,
           frNettoPrijsPeenheid,
           frAantDecBedrag, frAantDecAantal, frLeverdatum,
           frLocatieNaam, frMagazijnCode, frMagazijnNaam, frAdviesPrijsInclBtw, frAdviesPrijsexclBtw,
           frGewichtPer, frGewichtPeenheid, frGewichtPStuk, FrGewichtTotaalBesteld, FrGewichtTotaalLevering,
           frVolumePer,  frVolumePeenheid,  frVolumePStuk, FrVolumeTotaalBesteld, FrVolumeTotaalLevering,
           frCbsTrCode, frCbsGcCode, frCbsGcOmsVerkort, FrCbsLndEigenCodeOorsprong, FrCbsLndOmsOorsprong, frKstpCode, frKstpNaam, frKstdCode, frKstdNaam, frEdiBuffer, frTijdvakBegin, frTijdvakEind, FrPbSoort, FrPrjAantalUur,
           FrDirecteLevering,FrDirLevNummer,FrDirLevNaam1,FrDirLevNaam2,
           FrfrGidOorsprong, FrKMAantalGecontroleerd)
  select   @frefGid, OrrGid, OrrPfvrGid, OrrExternId, OrrRegelNr, OrrRegelSoort, OrrVervolgMasterOrrGid,
           if orrArtGid is null or orrRegelSoort <> 0 then
             OrrTekstOpFactuur  //Als geen art.nr. opgegeven of art.regel of tariefregel dan de tekst van de order gebruiken
           else
             ( select ArtTekst from tabArtikelTeksten where ArtTekstArtGid = OrrArtGid and ArtTaalgid = if exists( select 1 from tabArtikelTeksten where ArtTekstArtGid = OrrArtGid and ArtTaalgid =  @DebTaalGid ) then @DebTaalGid else @DefTaalGid endif )
           endif,
           ArtCode, ArtZoekCode, ArtOms,
           (select ArtEancode from tabArtikelEan where ArtEanGid = VerkEenh.VkeArtEanGid) ArtEanCode,
           (select ArtEancode from tabArtikelEan where ArtEanGid = VrrdEenh.VkeArtEanGid) ArtEanCodeVrrdEenh,
           OpbrGrpNummer, ArtPartijNummer, OrrIsAantallen,
           if OrrRegelSoort <> 0 then round( OrrAantalBesteld, OrrAantDecAantal )        endif AantBesteld,
           if OrrRegelSoort <> 0 then round( OrrAantalBesteldVrrdEenh, OrrAantDecAantalVrrdEenh )        endif AantBesteldVrrdEenh,

           VerkEenh.VkeVerkoopEenheid, IsNull(VerkEenh.VkeIsVoorraadEenheid, 0) /*ivm tarief*/, OrrEenheidPrijsPer, OrrAantalVrrdEenhInVerkEenh, OrrAantalVrrdEenhInVerkEenhMagAfwijken, OrrAantDecAantalVrrdEenh,

           //ACW 17-09-2010: Uitbreiding DL: Als DiercteLevering, dan zit het aantal dat nu is geleverd al in Geleverd!
           if OrrRegelSoort <> 0 then round( OrrAantalGeleverd - if @SoortFact = 6 /*DirLev*/ then round( tforAantalAflevering / OrrAantalVrrdEenhInVerkEenh, OrrAantDecAantal ) else 0 endif, OrrAantDecAantal )       endif AantGeleverd,
           if OrrRegelSoort <> 0 then
             if @SoortFact = 6 /*DirecteLevering*/ then
               // Als directe levering, dan dit aantal uit de aflevering halen in plaats van uit de verkooporderregel (omdat het al direct als Geleverd wordt beschouwd)
               round( tforAantalAflevering / OrrAantalVrrdEenhInVerkEenh, OrrAantDecAantal )
             else
               round( OrrAantalLevering, OrrAantDecAantal )
             endif
           endif AantDezeLevering,

           if OrrRegelSoort <> 0 then
             if @SoortFact = 6 /*DirecteLevering*/ then
               // Als directe levering, dan dit aantal uit de aflevering halen in plaats van uit de verkooporderregel (omdat het al direct als Geleverd wordt beschouwd)
               round( tforAantalAflevering, OrrAantDecAantalVrrdEenh )
             else
               round( OrrAantalLeveringVrrdEenh, OrrAantDecAantalVrrdEenh )
             endif
           endif AantDezeLeveringVrrdEenh,
           if OrrRegelSoort <> 0 then round( OrrAantalGeleverdVrrdEenh - if @SoortFact = 6 /*DirLev*/ then tforAantalAflevering else 0 endif, OrrAantDecAantal ) endif AantGeleverdVrrdEenh,

           OrrAantalBackorderVrrdEenh,
           if OrrRegelSoort <> 0 then round( OrrAantalGefactureerd, OrrAantDecAantal)    endif AantGefactureerd,
           if OrrRegelSoort <> 0 then round( OrrAantalDezeFacturering, OrrAantDecAantal) endif AantDezeFactuur,

           if OrrRegelSoort <> 0 then round( OrrAantalDezeFactureringVrrdEenh, OrrAantDecAantalVrrdEenh )  endif AantDezeFactuurVrrdEenh,
           if OrrRegelSoort <> 0 then round( OrrAantalGefactureerdVrrdEenh, OrrAantDecAantalVrrdEenh )     endif AantGefactureerdVrrdEenh,

           if OrrRegelSoort <> 0 then round( OrrAantalBackorder, OrrAantDecAantal)       endif AantBackOrder,
           if OrrRegelSoort <> 0 then round( OrrBrutoVerkoopPrijs, OrrAantDecBedrag )    endif BrutoVerkPrijs,
           if OrrRegelSoort <> 0 then round( OrrKostprijs, OrrAantDecBedrag )            endif Kostprijs,
           if OrrRegelSoort <> 0 then OrrPrijsPer                                        endif PrijsPer,
           if OrrRegelSoort <> 0 then ArtOmsEenheid                                      endif OmsEenheid,

           if IsNull(OrrRegelKorting2,0) = 0 then
             if IsNull(OrrRegelKorting1, 0) = 0 then // RS 30-05-12 bug 34365: Korting1bedrag moet natuurlijk altijd 0.0 zijn als dat ook zo in de order staat
               0.0
             else
               if AantBesteld >= 0 then
                  //MR 03-aug-2010 bug #32682: Afronden op 2 decimalen, anders kan hier een afrondingsverschil in komen te staan.
                  round((OrrBrutoVerkoopPrijs / if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then 1 else OrrPrijsPer endif) *
                    (if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                      (case @ObvAantal when 0 then AantBesteld when 1 then AantDezeFactuur when 2 then AantDezeLevering when 3 then AantDezeLevering end)
                     else
                      (case @ObvAantal when 0 then AantBesteldVrrdEenh when 1 then AantDezeFactuurVrrdEenh when 2 then AantDezeLeveringVrrdEenh when 3 then AantDezeLeveringVrrdEenh end)
                     endif) - frRegelTotaal, 2)
               else
                  //MR 03-aug-2010 bug #32682: Afronden op 2 decimalen, anders kan hier een afrondingsverschil in komen te staan.
                  round(frRegelTotaal - (OrrBrutoVerkoopPrijs / if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then 1 else OrrPrijsPer endif) *
                    (if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                      (case @ObvAantal when 0 then AantBesteld when 1 then AantDezeFactuur when 2 then AantDezeLevering when 3 then AantDezeLevering end)
                     else
                      (case @ObvAantal when 0 then AantBesteldVrrdEenh when 1 then AantDezeFactuurVrrdEenh when 2 then AantDezeLeveringVrrdEenh when 3 then AantDezeLeveringVrrdEenh end)
                     endif), 2)
               endif
             endif
           else
             if OrrIsKortingsPercentage = _qcJA then
               //bereken kortingsbedrag obv. percentage
               if @Stukskorting = _qcNEE then
                 //Regelkorting
                 if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                   round(round(((OrrBrutoVerkoopPrijs / OrrPrijsPer)*abs(OrrAantalBesteld)), 2) * (OrrRegelKorting1/100), 2)
                 else
                   round(round(((OrrBrutoVerkoopPrijs / OrrPrijsPer)*abs(OrrAantalBesteldVrrdEenh)), 2) * (OrrRegelKorting1/100), 2)
                 endif
               else
                 //Stukskorting
                 if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                   round((round((OrrRegelKorting1/100) * BrutoVerkPrijs, OrrAantDecBedrag) / OrrPrijsPer) *abs(OrrAantalBesteld), 2)
                 else
                   round((round((OrrRegelKorting1/100) * BrutoVerkPrijs, OrrAantDecBedrag) / OrrPrijsPer) *abs(OrrAantalBesteldVrrdEenh), 2)
                 endif
               endif
             else
               if @Stukskorting = _qcNEE then
                 OrrRegelKorting1
               else
                OrrRegelKorting1*abs((if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then  OrrAantalBesteld else OrrAantalBesteldVrrdEenh endif) / OrrPrijsPer)
               endif
             endif / abs(if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then  OrrAantalBesteld else AantBesteldVrrdEenh endif) *
              (if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                (case @ObvAantal when 0 then AantBesteld when 1 then AantDezeFactuur when 2 then AantDezeLevering end)
              else
                (case @ObvAantal when 0 then AantBesteldVrrdEenh when 1 then AantDezeFactuurVrrdEenh when 2 then AantDezeLeveringVrrdEenh end)
              endif)
           endif Korting1Bedr,

           if OrrIsKortingsPercentage = _qcJA then OrrRegelKorting1 else null endif Korting1Perc,
           OrrRegelKorting2 Korting2Perc,
           OrrBtwCode, OrrBtw.BtwPercentage,

           round(
             case @ObvAantal
             when 0 then // AantalBesteld
                 OrrRegelTotaal // Kunnen we dus gewoon overnemen!
             when 1 then // AantalDezeFactuur
               //Regeltotaal opnieuw berekenen obv. factuurgegevens
               if @Stukskorting = _qcNEE then
                 //ACW 03-03-2008: AantalBesteld=0 -> regeltotaal houdt geen rekening met regelkorting!
                 if OrrAantalBesteld = 0 then
                   if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                     (OrrBrutoVerkoopPrijs / OrrPrijsPer) * AantDezeFactuur
                   else
                     (OrrBrutoVerkoopPrijs / OrrPrijsPer) * AantDezeFactuurVrrdEenh
                   endif
                 else
                   //Totaal obv. regelkortingen: Regeltotaal = (round[(Aantal * brutoprijs)]*(100-korting1%)-korting1)*(100-korting2%)
                   if OrrIsKortingsPercentage = _qcNEE then
                     if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                       round((((abs(OrrAantalBesteld) * OrrBrutoVerkoopPrijs) - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100) / abs(OrrAantalBesteld)) * AantDezeFactuur, 2)
                     else
                       round((((abs(OrrAantalBesteldVrrdEenh) * (OrrBrutoVerkoopPrijs / OrrPrijsPer)) - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100) / abs(OrrAantalBesteldVrrdEenh)) * AantDezeFactuurVrrdEenh, 2)
                     endif
                   else
                     if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                       round(((abs(OrrAantalBesteld) * OrrBrutoVerkoopPrijs) * ((100 - isnull(Korting1Perc,0))/100) * ((100 - isnull(Korting2Perc,0))/100) / abs(OrrAantalBesteld)) * AantDezeFactuur, 2)
                     else
                       round(((abs(OrrAantalBesteldVrrdEenh) * (OrrBrutoVerkoopPrijs / OrrPrijsPer)) * ((100 - isnull(Korting1Perc,0))/100) * ((100 - isnull(Korting2Perc,0))/100) / abs(OrrAantalBesteldVrrdEenh)) * AantDezeFactuurVrrdEenh, 2)
                     endif
                   endif
                 endif
               else
                 //Totaal obv. stukskortingen: Regeltotaal = FactAantal * round[(brutoprijs*(100-korting1%)-korting1)*(100-korting2%)]
                  if OrrIsKortingsPercentage = _qcNEE then
                    if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                      AantDezeFactuur * (round((BrutoVerkPrijs  - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag))
                    else
                      (AantDezeFactuurVrrdEenh / OrrPrijsPer) * (round((BrutoVerkPrijs  - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag))
                    endif
                  else
                    if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                      AantDezeFactuur * (round((BrutoVerkPrijs  * ((100 - OrrRegelKorting1) / 100)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag))
                    else
                      (AantDezeFactuurVrrdEenh / OrrPrijsPer) * (round((BrutoVerkPrijs  * ((100 - OrrRegelKorting1) / 100)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag))
                    endif
                  endif
               endif
             when 2 then // AantalDezeLevering
               //Regeltotaal opnieuw berekenen obv. factuurgegevens
               if @Stukskorting = _qcNEE then
                 //ACW 03-03-2008: AantalBesteld=0 -> regeltotaal houdt geen rekening met regelkorting!
                 if OrrAantalBesteld = 0 then
                    (OrrBrutoVerkoopPrijs / OrrPrijsPer) * AantDezeLevering
                 else
                   if OrrIsKortingsPercentage = _qcNEE then
                     if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                       round((((abs(OrrAantalBesteld) * OrrBrutoVerkoopPrijs) - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100) / abs(OrrAantalBesteld)) * AantDezeLevering, 2)
                     else
                       round((((abs(OrrAantalBesteldVrrdEenh) * (OrrBrutoVerkoopPrijs / OrrPrijsPer)) - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100) / abs(OrrAantalBesteldVrrdEenh)) * AantDezeLeveringVrrdEenh, 2)
                     endif
                   else
                     if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                       round(((abs(OrrAantalBesteld) * OrrBrutoVerkoopPrijs) * ((100 - isnull(Korting1Perc,0))/100) * ((100 - isnull(Korting2Perc,0))/100) / abs(OrrAantalBesteld)) * AantDezeLevering, 2)
                     else
                       round(((abs(OrrAantalBesteldVrrdEenh) * (OrrBrutoVerkoopPrijs / OrrPrijsPer)) * ((100 - isnull(Korting1Perc,0))/100) * ((100 - isnull(Korting2Perc,0))/100) / abs(OrrAantalBesteldVrrdEenh)) * AantDezeLeveringVrrdEenh, 2)
                     endif
                   endif
                 endif
               else
                 //Totaal obv. stukskortingen: Regeltotaal = Aantal * round[(brutoprijs*(100-korting1%)-korting1)*(100-korting2%)]
                 if OrrIsKortingsPercentage = _qcNEE then
                   if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                     AantDezeLevering * (round((BrutoVerkPrijs  - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag))
                   else
                     (AantDezeLeveringVrrdEenh / OrrPrijsPer) * (round((BrutoVerkPrijs  - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag))
                   endif
                 else
                   if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                     AantDezeLevering * (round((BrutoVerkPrijs  * ((100 - OrrRegelKorting1) / 100)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag))
                   else
                     (AantDezeLeveringVrrdEenh / OrrPrijsPer) * (round((BrutoVerkPrijs  * ((100 - OrrRegelKorting1) / 100)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag))
                   endif
                 endif
               endif
             end
           , @AantDeciValuta) frRegelTotaal,

           if isnull(OrrRegelKorting1,0) = 0 and isnull(Korting2Perc,0) = 0 then
             BrutoVerkPrijs
           else
             if @Stukskorting = _qcNEE then
               case @ObvAantal
               when 0 then // AantalBesteld
                 if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                   if OrrAantalBesteld = 0 then 0 else OrrRegelTotaal / OrrAantalBesteld endif
                 else
                   if OrrAantalBesteldVrrdEenh = 0 then 0 else OrrRegelTotaal / OrrAantalBesteldVrrdEenh  * OrrPrijsPer endif
                 endif
               when 1 then // AantalDezeFactuur
                 if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                   if isnull(OrrAantalDezeFacturering,0) = 0 then 0 else frRegelTotaal / OrrAantalDezeFacturering endif
                 else
                   if isnull(OrrAantalDezeFactureringVrrdEenh,0) = 0 then 0 else frRegelTotaal / OrrAantalDezeFactureringVrrdEenh * OrrPrijsPer endif
                 endif
               when 2 then // AantalDezeLevering
                   //ACW 17-09-2010: Uitbreiding DL: In plaats van OrrAantalLevering nu AantDezeLevering gebruikt (niet 2x hetzelfde berekenen)
                   if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                     if isnull(AantDezeLevering,0) = 0 then 0 else frRegelTotaal / AantDezeLevering endif
                   else
                     if isnull(AantDezeLeveringVrrdEenh,0) = 0 then 0 else frRegelTotaal / AantDezeLeveringVrrdEenh  * OrrPrijsPer endif
                   endif
               end
             else
              // RS 5-4-2012 bug 34365: Ook voor de nettoprijspereenheid geldt dat er een verschil is tussen stuks en regelkorting. In geval
              // van stukskorting moet dit veld natuurlijk niet obv het regeltotaal berekend worden.
               if OrrIsKortingsPercentage = _qcNEE then
              //   if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                   round((BrutoVerkPrijs  - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag)
              //   else
              //     round((BrutoVerkPrijs  - isnull(OrrRegelKorting1,0)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag) * OrrPrijsPer
              //   endif
               else
              //   if OrrEenheidPrijsPer = 0 /* VerkoopEenheid */ then
                   round((BrutoVerkPrijs  * ((100 - OrrRegelKorting1) / 100)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag)
              //   else
              //     round((BrutoVerkPrijs  * ((100 - OrrRegelKorting1) / 100)) * ((100 - isnull(Korting2Perc,0))/100), OrrAantDecBedrag) * OrrPrijsPer
              //   endif
               endif
             endif
           endif frNettoPrijsPeenheid,
           OrrAantDecBedrag, OrrAantDecAantal, OrrLeverDatum,
           // Selecteer de locatienaam van de standaard locatie van het artikel in het magazijn of (Standaard) indien die niet is ingevuld
           (select first LocNaam
            from   tabLocatie
            where  (LocGid = isnull((select ArtMagDefaultLocGid from tabArtikelMagazijn where ArtMagMagGid = OrrMagGid and ArtMagArtGid = OrrArtGid),  // Default locatie van dit artikel in het magazijn
                                    (select first LocGid from tabLocatie where LocNaam='(Standaard)' and (LocMagGid = OrrMagGid) )  // Standaard locatie
                                   )
                   )
            ),

           if (frDirLev = _qcNEE) then MagCode endif,
           if (frDirLev = _qcNEE) then MagOms endif,
           if (OrrEenheidPrijsPer = 0) /* VerkoopEenheid */ then
             if (VerkEenh.VkeHeeftAparteVerkoopPrijsOfKorting in (2)) /* Vke heeft eigen adviesprijs */ then
               if VerkEenh.VkeIsAdviesprijsInclusiefBTW = _qcJA then VerkEenh.VkeAdviesprijs else VerkEenh.VkeAdviesprijs * (100 + ArtBtw.BtwPercentage) / 100 endif // adviesprijs incl.BTW verkoopeenheid
             else
               (if ArtIsAdviesPrijsInclBtw = _qcJA then ArtAdviesPrijs else ArtAdviesPrijs * (100 + ArtBtw.BtwPercentage) / 100 endif) * OrrAantalVrrdEenhInVerkEenh // adviesprijs incl.BTW voorraadeenheid * Aantal vrrd in verkeenh
             endif
           else
             if ArtIsAdviesPrijsInclBtw = _qcJA then ArtAdviesPrijs else ArtAdviesPrijs * (100 + ArtBtw.BtwPercentage) / 100 endif // adviesprijs incl.BTW voorraadeenheid
           endif,
           if (OrrEenheidPrijsPer = 0) /* VerkoopEenheid */ then
             if (VerkEenh.VkeHeeftAparteVerkoopPrijsOfKorting in (2)) /* Vke heeft eigen adviesprijs */ then
               if VerkEenh.VkeIsAdviesprijsInclusiefBTW = _qcNEE then VerkEenh.VkeAdviesprijs else VerkEenh.VkeAdviesprijs / (100 + ArtBtw.BtwPercentage) * 100 endif // adviesprijs excl.BTW verkoopeenheid
             else
               (if ArtIsAdviesPrijsInclBtw = _qcNEE then ArtAdviesPrijs else ArtAdviesPrijs / (100 + ArtBtw.BtwPercentage) * 100 endif) * OrrAantalVrrdEenhInVerkEenh // adviesprijs excl.BTW voorraadeenheid
             endif
           else
             if ArtIsAdviesPrijsInclBtw = _qcNEE then ArtAdviesPrijs else ArtAdviesPrijs / (100 + ArtBtw.BtwPercentage) * 100 endif // adviesprijs excl.BTW voorraadeenheid
           endif,
           // Gewicht
           if (VerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA) then
             VerkEenh.VkeGewichtPer
           else
             VrrdEenh.VkeGewichtPer
           endif,

           if VerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA then
             round(VerkEenh.VkeGewicht / VerkEenh.VkeGewichtPer, 3)
           else
             round((VrrdEenh.VkeGewicht / VrrdEenh.VkeGewichtPer) * OrrAantalVrrdEenhInVerkEenh, 3)
           endif GewichtPeenheid,

           if VerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA then
             if VerkEenh.VkeAantalKanVerschillen = _qcNEE then
               round(VerkEenh.VkeGewicht / VerkEenh.VkeAantalVoorraadEenhedenInVerkoopEenheid, 3)
             else
               round(VerkEenh.VkeGewicht / OrrAantalVrrdEenhInVerkEenh, 3)
             endif
           else
             round(VrrdEenh.VkeGewicht / VrrdEenh.VkeGewichtPer, 3)
           endif GewichtPstuk,

          if VerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA then
            round(OrrAantalBesteld * VerkEenh.VkeGewicht / VerkEenh.VkeGewichtPer, 3)
          else
            round(OrrAantalBesteldVrrdEenh * VrrdEenh.VkeGewicht / VrrdEenh.VkeGewichtPer, 3)
          endif TotaalGewichtBesteld,

          ( select sum( if OrlVerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA then
                          OrlDezeLevering * OrlVerkEenh.VkeGewicht  / OrlVerkEenh.VkeGewichtPer
                        else
                          OrlDezeLeveringVrrdEenh * OrlVrrdEenh.VkeGewicht / OrlVrrdEenh.VkeGewichtPer
                        endif
                       )
              from tabOrderRegelLocatie
              inner join tabVerkoopEenheid OrlVerkEenh on OrlVkeGid = VkeGid
              inner join tabVerkoopEenheid OrlVrrdEenh on (ArtGid = OrlVrrdEenh.VkeArtGid and OrlVrrdEenh.VkeIsVoorraadEenheid = _qcJA)
              where OrlOrrGid = OrrGid) TotaalGewichtDezeLevering,

           //Volume
           if (VerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA) then
             VerkEenh.VkeVolumePer
           else
             VrrdEenh.VkeVolumePer
           endif,

           if VerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA then
             round(VerkEenh.VkeVolume / VerkEenh.VkeVolumePer, 3)
           else
             round((VrrdEenh.VkeVolume / VrrdEenh.VkeVolumePer) * OrrAantalVrrdEenhInVerkEenh, 3)
           endif VolumePeenheid,

           if VerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA then
             if VerkEenh.VkeAantalKanVerschillen = _qcNEE then
               round(VerkEenh.VkeVolume / VerkEenh.VkeAantalVoorraadEenhedenInVerkoopEenheid, 3)
             else
               round(VerkEenh.VkeVolume / OrrAantalVrrdEenhInVerkEenh, 3)
             endif
           else
             round(VrrdEenh.VkeVolume / VrrdEenh.VkeVolumePer, 3)
           endif VolumePstuk,

          if VerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA then
            round(OrrAantalBesteld * VerkEenh.VkeVolume / VerkEenh.VkeVolumePer, 3)
          else
            round(OrrAantalBesteldVrrdEenh * VrrdEenh.VkeVolume / VrrdEenh.VkeVolumePer, 3)
          endif TotaalVolumeBesteld,

          (select sum( if OrlVerkEenh.VkeIsAfwijkendGewichtOfVolume = _qcJA then
                          OrlDezeLevering * OrlVerkEenh.VkeVolume  / OrlVerkEenh.VkeVolumePer
                        else
                          OrlDezeLeveringVrrdEenh * OrlVrrdEenh.VkeVolume / OrlVrrdEenh.VkeVolumePer
                        endif
                       )
              from tabOrderRegelLocatie
              inner join tabVerkoopEenheid OrlVerkEenh on OrlVkeGid = VkeGid
              inner join tabVerkoopEenheid OrlVrrdEenh on (ArtGid = OrlVrrdEenh.VkeArtGid and OrlVrrdEenh.VkeIsVoorraadEenheid = _qcJA)
              where OrlOrrGid = OrrGid) TotaalVolumeDezeLevering,

           CbsTrCode, CbsGcCode, CbsGcOmsVerkort, CbsLandOorsprong.LndEigenCode, CbsLandOorsprong.LndOms, KstpCode, KstpNaam, KstdCode, KstdNaam, OrrEdiBuffer, OrrTijdvakBegin, OrrTijdvakEind, OrrPbSoort, OrrPrjAantalUur,

           /*ACW 08-12-2010 incident #4749: Geheel anders opgezet:
             Als bestelling op deze regel, dan DL +lev. daarvan overnemen
             anders als in verk.order 'Ja' of 'Nee' dan overnemen
             anders als in verk.order lev./IE ingevuld, dan daarvan overnemen
             anders default lev./IE overnemen
           */
           if BstKopAfleverAdres is not null then
             BstKopAfleverAdres  //0=Magazijn, DUS geen DirLev, 1 = Debiteur, dus WEL DirLev
           else
             // Er is nog geen bestelling voor, dus nu o.b.v. orderregel en/of gevonden leverancier/IE
             case OrrDirecteLevering
             when 0 /*Nee*/ then
               0 /*Volgens orderregel NIET via DL, dus ook niet doen*/
             when 1 /*ja*/ then
               // Alleen als het volgens artikel, lev. en/of IE ook wel mag
               if     (ArtBestellenVoorDirecteLevering <> _qcNEE)                                 // Volgens artikel mag het!
                  and (OrrDirecteInkoop = _qcJA)                                                      //De orderregel staat op directe inkoop
                  and (isnull(LevGegDirLevGeschikt, _qcNEE) = _qcJA /*DL is toegestaan*/)                  // Volgens leverancier mag het ook
                  and (isnull(AldDirecteLevering, _qcNEE) in (1, 2) /*IE Toegestaan en/of default*/) then  // Volgens IE mag het ook
                 _qcJA // Volgens artikel, orderregel, leverancier EN inkoopeenheid is het toegestaan,                // DUS DOEN!
               else
                 0 // Niet geheel toegestaan, dus alsnog NIET doen                                    // DUS NIET DOEN!
               endif
             when 2 /* volgens lev/IE*/ then
               if     (isnull(AldDirecteLevering, _qcNEE) = 2) /*IE Toegestaan en default*/
                  and (OrrDirecteInkoop = _qcJA)                     //De orderregel staat op directe inkoop
                  and (isnull(LevGegDirLevGeschikt, _qcNEE) = _qcJA /*DL is toegestaan*/)
                  and (ArtBestellenVoorDirecteLevering <> _qcNEE) then
                 _qcJA
               else
                 0
               endif
             end
           endif frDirLev,
           DirLevNawFile.NawFilNummer,
           DirLevAdres.AdrNaam1,
           DirLevAdres.AdrNaam2,
           if @SoortFact in (0, 1, 5) then //Alle vormen van facturering
             OrrfrGid
           else
             null
           endif,
           OrrKMAantalGecontroleerd
  from     tabOrderRegel
           left outer join tabArtikel                 on (ArtGid          = OrrArtGid )
           left outer join tabOpbrengstgroep          on (OpbrGrpGid      = ArtOpbrGrpGid)
           left outer join tabBtw OrrBtw              on (OrrBtw.BtwCode  = OrrBtwCode)
           left outer join tabBtw ArtBtw              on (ArtBtw.BtwCode  = ArtBtwCode)
           left outer join tabMagazijn                on (MagGid          = OrrMagGid )
           left outer join tabArtikelPartij           on (OrrArtPartijGid = ArtPartijGid)
           left outer join tabCbsGoederenCodes        on (CbsGcGid        = ArtCbsGcGid)
           left outer join tabCbsTransactie           on (CbsTrGid        = OrrCbsTrGid)
           left outer join tabLand CbsLandOorsprong   on (CbsLandOorsprong.LndGid = OrrLndGidCbsOorsprong)
           left outer join tabKostenplaats            on (OrrKstpGid      = KstpGid)
           left outer join tabKostendrager            on (OrrKstdGid      = KstdGid)
           left outer join (tabBestelRegelDetail
                            inner join tabBestelregel on (BstRglGid       = brdBstRglGid)
                            inner join tabBestelKop   on (BstKopGid       = BstRglBstKopGid)
                           ) on (brdOrrGid       = OrrGid)
           // Leverancier van bestelling OF orderergel OF de default van artikel
           left outer join tabArtikelLeverancier on (    (ArtLevArtGid = OrrArtGid)
                                                     and (   (isnull(BstKopNawGid, OrrNawGidDirecteInkoop) is null and ArtLevIsDefault = _qcJA)
                                                          or (ArtLevNawGid = isnull(BstKopNawGid, OrrNawGidDirecteInkoop))
                                                         )
                                                    )
           // Inkoopeenheid van bestelling OF orderregel OF de default van artikelleverancier
           left outer join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid
                                                           and (   (    (isnull(BstRglInkoopEenheid, OrrDirInkInkoopEenheid, '') = '')   // Niets ingevuld
                                                                    and (AldIsDefaultInkoopEenheidBijLev = _qcJA)
                                                                   )
                                                                or (AldInkoopEenheid = isnull(BstRglInkoopEenheid, OrrDirInkInkoopEenheid))
                                                               )
                                                          )
           // Liefst de NAW van de bestelling, als die er niet is, dan de NAW van de verkooporder, als die er niet is, de default NAW van artikel
           left outer join (tabNaw DirLevNaw
                            inner join tabAdres DirLevAdres On (DirLevAdres.adrNawGid = DirLevNaw.nawGid) and (DirLevAdres.adrGid = DirLevNaw.nawGidVestiging)
                            inner join tabNawFile DirLevNawFile on (DirLevNawFile.NawFilNawGid = DirLevNaw.NawGid and DirLevNawFile.NawFilFonId = 'C')
                           ) on DirLevNaw.NawGid = isnull(BstKopNawGid, OrrNawGidDirecteInkoop, ArtLevNawGid)
           left outer join tabLeverancierGegevens     on (LevGegNawGid = DirLevNaw.NawGid)
           left outer join tabVerkoopEenheid VerkEenh on (OrrVkeGid  = VerkEenh.VkeGid)
           left outer join tabVerkoopEenheid VrrdEenh on (ArtGid = VrrdEenh.VkeArtGid and VrrdEenh.VkeIsVoorraadEenheid = _qcJA)
           left outer join tabTeFacturerenOrders      on (@SoortFact = 6 and TfoSessieFbGid = @FbGid) //Alleen meenemen als soort = Directe Levering
           left outer join tabTeFacturerenOrderRegels on (@SoortFact = 6 and tforTfoGid = TfoGid and tforOrrGid = OrrGid)
  where    OrrOrkGid = @OrkGid and
            // ACW 17-09-2010: Uitbreiding DL: Alleen de regels die in de tussentabel staan
            (@SoortFact <> 6 /*DirLev*/ or tforOrrGid is not null)
           and
          ((OrrRegelSoort = 2) or //Artikel: altijd opnemen
           (OrrRegelSoort = 1 and @vofLevOokTarief = _qcJA) or //Tariefregel
           (OrrRegelSoort = 0 and @vofLevOokTekst = _qcJA)     //Tekstregel
          );

  // Vrije rubrieken van de net toegevoegde regels
  for @Cursor AS Cursor_RegelsVrijeRubriek CURSOR FOR
    select frGid @frGid, FrOrrGid @FrOrrGid, ArtGid @ArtGid, frSoortRegel @FrSoortRegel, ArtPartijGid @ArtPartijGid
    from   tabFactuurRegel left outer join tabArtikel on (ArtSoort = frSoortRegel and ArtCode = frArtCode) left outer join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijNummer = frOrrArtPartijNummer
    where  frFrefGid = @FrefGid
  for read only
  do
    //Vrije rubrieken van de ORDERREGEL
    call FactureringOvernemenVrijeRubrieken(4, @FrGid, @FrOrrGid, 0);

    //Vrije rubrieken van het ARTIKEL
    if @FrSoortRegel = 2 and @ArtGid is not null then
      call FactureringOvernemenVrijeRubriekenArt(@FrGid, @ArtGid, 0);
    end if;

    //Vrije rubrieken van de REGEL PARTIJ
    if @FrSoortRegel = 2 and @ArtPartijGid is not null then
      call FactureringOvernemenVrijeRubriekenPartij(0, @FrGid, @ArtPartijGid, 0);
    end if;
  end for;


  // Alle partij/serienummer-regels toevoegen
  // Het aantal is verzameld per: Partij + Serienummer, deze is niet van belang bij de factuur!
  // Als factuur -> alleen serienummers en aantal van de partij opnemen
  // Als pakbon  -> alleen de DezeLevering opnemen
  //ACW 17-09-2010: Uitbreiding DL: Als directe levering, dan de detailregels van de uitlevering overnemen ipv. uit verkooporder
  if @SoortFact = 6 /*Directe levering*/ then
    set @@ErrorTextProcedure = 'FacturerenToevoegenOrderRegelGegevens > Toevoegen PartijSerie-gegevens uit Directe Levering';
     //call Trace(@@ErrorTextProcedure);
    for @Cursor AS Cursor_DirLev CURSOR FOR
      select   FrGid                         @FrGid,
               ArtPartijNummer               @ArtPartijNummer,
               ArtPartijOms                  @ArtPartijOms,
               ArtPartijTHTdatum             @ArtPartijTHTdatum,
			   ArtPartijDatumProductie       @ArtPartijDatumProductie,
               ArtSerienummer                @ArtSerienummer,
               MagOntLocAantal               @MagOntLocAantal,
               GcCode                        @GcCode,
               ArtSerieGarantieTmDatum       @ArtSerieGarantieTmDatum,
               ArtSerieGarantieBepalingen    @ArtSerieGarantieBepalingen,
               VerkEenh.VkeVerkoopEenheid    @VerkEenhVkeVerkoopEenheid,
               VerkEenh.VkeIsVoorraadEenheid @VerkEenhVkeIsVoorraadEenheid,
               VerkEenh.VkeAantalDecimalen   @VerkEenhVkeAantalDecimalen,
               VrrdEenh.VkeVerkoopEenheid    @VrrdEenhVkeVerkoopEenheid,
               VrrdEenh.VkeAantalDecimalen   @VrrdEenhVkeAantalDecimalen,
               OrrAantalVrrdEenhInVerkEenh   @OrrAantalVrrdEenhInVerkEenh,
               OrrAantDecAantal              @OrrAantDecAantal,
               OrrAantDecAantalVrrdEenh      @OrrAantDecAantalVrrdEenh,
               LndEigenCode                  @LndEigenCode,
               LndOms                        @LndOms
      from     tabMagazijnOntvangsten
               inner join tabMagazijnOntvangstenDetail     on (MagOntDetMagOntGid    = MagOntGid)
               left outer join tabBestelRegelDetail        on (brdGid                = MagOntDetbrdGid)
               inner join tabOrderRegel                    on (OrrGid                = isnull(brdOrrGid, MagOntDetOrrGid))
               inner join tabMagazijnOntvangstLocatieSerie on (MagOntLocMagOntDetGid = MagOntDetGid)
               inner join tabArtikel                       on (ArtGid                = OrrArtGid)
               inner join tabFactuurRegel                  on (frRegelNummer         = OrrRegelnr and FrFrefGid = @FrefGid)
               left outer join tabArtikelPartij            on (ArtPartijGid          = MagOntArtPartijGid)
               left outer join tabLand                     on (LndGid                = ArtPartijLndGidCbsOorsprong)
               left outer join tabArtikelSerienummer       on (ArtSerieGid           = MagOntLocArtSerieGid)
               left outer join tabGarantieCode             on (GcGid                 = ArtGcGid)
               left outer join tabVerkoopEenheid VerkEenh  on (OrrVkeGid             = VerkEenh.VkeGid)
               left outer join tabVerkoopEenheid VrrdEenh  on (ArtGid = VrrdEenh.VkeArtGid and VrrdEenh.VkeIsVoorraadEenheid = 1)
      where    OrrOrkGid = @OrkGid
    for read only
    do
      if (@VerkEenhVkeIsVoorraadEenheid = 1) then
        set @DLVrrdEenh        = @MagOntLocAantal;
        set @DLVerkEenh        = @MagOntLocAantal;
        set @DLVerkEenheidNaam = @VrrdEenhVkeVerkoopEenheid;
        set @DLIsVrrdEenh      = 1;
        set @OrrAantDecAantal  = @OrrAantDecAantalVrrdEenh;
      else
        // Kopie van Delphi routine FloorWithDecimals voor omrekenen voorraadeenheden naar verkoopeenheden
        case @OrrAantDecAantal
          when 0 then set @DLtp = 1.0;
          when 1 then set @DLtp = 10.0;
          when 2 then set @DLtp = 100.0;
          when 3 then set @DLtp = 1000.0;
        else
          set @DLtp = power(10, @OrrAantDecAantal);
        end case;

        set @DLtmp = round(@MagOntLocAantal / (if @OrrAantalVrrdEenhInVerkEenh = 0 then 1 else @OrrAantalVrrdEenhInVerkEenh endif), 6);
        set @DLFlooredVerkEenh = Floor((@DLtmp * @DLtp) + 0.0000001) / @DLtp;
        // Einde FloorWithDecimals

        // Kijken of we geen restant overhouden, rekening houdend met decimalen instelling
        if @DLFlooredVerkEenh = round(@MagOntLocAantal / @OrrAantalVrrdEenhInVerkEenh, 3) then // Geen restant, verkoopeenheid gebruiken
          set @DLVrrdEenh        = @MagOntLocAantal;
          set @DLVerkEenh        = @DLFlooredVerkEenh;
          set @DLVerkEenheidNaam = @VerkEenhVkeVerkoopEenheid;
          set @DLIsVrrdEenh      = 0;
        else // Wel restant, dan maar de voorraadeenheid gebruiken
          set @DLVrrdEenh        = @MagOntLocAantal;
          set @DLVerkEenh        = @MagOntLocAantal;
          set @DLVerkEenheidNaam = @VrrdEenhVkeVerkoopEenheid;
          set @DLIsVrrdEenh      = 1;
          set @OrrAantDecAantal  = @OrrAantDecAantalVrrdEenh;
        end if;
      end if;

      insert into tabFactuurRegelPartijSerie(frpsFrGid, frpsPartijNummer, frpsPartijOms, frpsPartijTHTdatum, frpsSerienummer, frpsAantalDezeLevering, frpsAantalGeleverd, frpsGarantieCode, frpsGarantieTmDatum,      frpsGarantieBepaling,        FrpsVerkoopEenheid, FrpsVerkoopEenheidIsVoorraadEenheid, FrpsAantalDezeLeveringVrrdEenh, FrpsAantalGeleverdVrrdEenh, FrpsAantDecAantal, FrpsAantDecAantalVrrdEenh, frpsPartijDatumProductie, FrpsPartijCbsLndEigenCodeOorsprong, FrpsPartijCbsLndOmsOorsprong)
                                     select @FrGid,     @ArtPartijNummer, @ArtPartijOms, @ArtPartijTHTdatum, @ArtSerienummer, @DLVerkEenh,            null /*NVT*/,       @GcCode,          @ArtSerieGarantieTmDatum, @ArtSerieGarantieBepalingen, @DLVerkEenheidNaam, @DLIsVrrdEenh,                       @DLVrrdEenh,                    null /*NVT*/,               @OrrAantDecAantal, @OrrAantDecAantalVrrdEenh, @ArtPartijDatumProductie, @LndEigenCode,                      @LndOms
    end for;

  else
    set @@ErrorTextProcedure = 'FacturerenToevoegenOrderRegelGegevens > Toevoegen PartijSerie-gegevens uit verkooporder';
     //call Trace(@@ErrorTextProcedure);
    insert into tabFactuurRegelPartijSerie(frpsFrGid, frpsPartijNummer, frpsPartijOms, frpsPartijTHTdatum, frpsSerienummer, frpsAantalDezeLevering, frpsAantalGeleverd, frpsGarantieCode, frpsGarantieTmDatum, frpsGarantieBepaling,
             frpsMagCode, frpsMagOms, frpsLocNaam, frpsLocOms, FrpsKMGepicktOp, FrpsSSCCID, FrpsVerkoopEenheid, FrpsVerkoopEenheidIsVoorraadEenheid, FrpsAantalDezeLeveringVrrdEenh, FrpsAantalGeleverdVrrdEenh, FrpsAantDecAantal, FrpsAantDecAantalVrrdEenh, frpsPartijDatumProductie, FrpsPartijCbsLndEigenCodeOorsprong, FrpsPartijCbsLndOmsOorsprong)
    select   FrGid, ArtPartijNummer, ArtPartijOms, ArtPartijTHTdatum, ArtSerienummer, OrlDezeLevering, OrlGeleverd, GcCode, ArtSerieGarantieTmDatum, ArtSerieGarantieBepalingen,
             if isNull(FrDirecteLevering, _qcNEE) = _qcNEE then MagCode endif,
             if isNull(FrDirecteLevering, _qcNEE) = _qcNEE then MagOms endif,
             if isNull(FrDirecteLevering, _qcNEE) = _qcNEE then LocNaam endif,
             if isNull(FrDirecteLevering, _qcNEE) = _qcNEE then LocOms endif,
             OrlKMGepicktOp, OrlSSCCID, VkeVerkoopEenheid, VkeIsVoorraadEenheid, OrlDezeLeveringVrrdEenh, OrlGeleverdVrrdEenh, OrlAantDecAantal, OrlAantDecAantalVrrdEenh,
             ArtPartijDatumProductie,
             LndEigenCode,
             LndOms
    from     tabOrderRegelLocatie
             inner join tabOrderRegel              on (OrrGid        = OrlOrrGid)
             inner join tabArtikel                 on (ArtGid        = OrrArtGid)
             inner join tabFactuurRegel            on (frRegelNummer = OrrRegelnr and FrFrefGid = @FrefGid)
             left outer join tabArtikelMagazijn    on (ArtMagMagGid  = OrlMagGid  and ArtMagArtGid = OrrArtGid)
             left outer join tabArtikelPartij      on (ArtPartijGid  = OrlArtPartijGid)
             left outer join tabLand               on (LndGid        = ArtPartijLndGidCbsOorsprong)
             left outer join tabArtikelSerienummer on (ArtSerieGid   = OrlArtSerieGid)
             left outer join tabGarantieCode       on (GcGid         = ArtGcGid)
             left outer join tabMagazijn           on (MagGid        = OrlMagGid)
             left outer join tabLocatie            on (LocGid        =
              if (OrlLocGid is null) or (@@ModuleM1 = _qcNEE) then
                (select isnull(ArtMagDefaultLocGid ,  // Default locatie van dit artikel in het magazijn, of indien niet ingevuld
                               (select first LocGid from tabLocatie where LocNaam='(Standaard)' and (LocMagGid = OrlMagGid) )  // de standaard locatie
                              )
                )
              else
               OrlLocGid
              endif
             )
             left outer join tabVerkoopEenheid     on (OrlVkeGid    = VkeGid)
    where    OrrOrkGid = @OrkGid;
  end if;

  // Vrije rubrieken van de net toegevoegde locatieregels
  for @Cursor AS Cursor_LocatieRegelsVrijeRubriek CURSOR FOR
    select frpsGid @frpsGid, ArtPartijGid @ArtPartijGid
    from   tabFactuurRegelPartijSerie inner join tabFactuurRegel on (FrpsFrGid = FrGid and FrSoortRegel = 2) inner join tabArtikel on (ArtSoort = frSoortRegel and ArtCode = frArtCode) inner join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijNummer = frpsPartijNummer
    where  frFrefGid = @FrefGid
  for read only
  do
    //Vrije rubrieken van de spec.regel partij
    if @ArtPartijGid is not null then
      call FactureringOvernemenVrijeRubriekenPartij(1, @FrpsGid, @ArtPartijGid, 0);
    end if;
  end for;

  // Garantiebepalingen voor alle serienummers updaten (indien nodig!)
  //ACW 17-09-2010: Uitbreiding: OOK voor de directe leveringen de garantievoorwaarden overnemen
  if @SoortFact in (3, 6) then
    // Alleen bij levering, anders de bestaande waarden gewoon overnemen!!
    for @Cursor AS CURSOR_serienum CURSOR FOR
      select frpsGid @frpsGid, ArtSerieGid @SerieGid
      from   tabFactuurRegelPartijSerie
             inner join tabFactuurRegel on frGid = frpsFrGid
             inner join tabArtikel on (ArtCode = frArtCode and ArtSoort = 2)
             inner join tabArtikelSerieNummer on (ArtSerieArtGid = ArtGid and ArtSerieNummer = frpsSerienummer)
      where  frFrefGid = @FrefGid and frSoortRegel = 2
    for read only
    do
      call LeesUpdateGarantieSerieNummer(@SerieGid, @LeverDatum, 0, @frpsGarantieTmDatum, 0, 0, @frpsGarantieBepaling, @MoetDatumUpdaten, @MoetBepalingUpdaten);

      if (@MoetDatumUpdaten = _qcJA) or (@MoetBepalingUpdaten = _qcJA) then
        update tabFactuurRegelPartijSerie
        set frpsGarantieTmDatum = (if @MoetDatumUpdaten = _qcJA then @frpsGarantieTmDatum else frpsGarantieTmDatum endif),
          frpsGarantieBepaling = (if @MoetBepalingUpdaten = _qcJA then @frpsGarantieBepaling else frpsGarantieBepaling endif)
        where frpsGid = @frpsGid;
      end if;

    end for;
  end if;

  //call Trace('Einde FacturerenToevoegenOrderRegelGegevens');
end;


create or replace procedure FacturerenUitdelenFactuurNummers(
  in @FbGid               integer,
  in @FkGid               integer,
  in @LeverFkGid          integer,
  in @BjGid               integer,
  in @LayoutSoort         integer,     //50=factuur direct, 60=factuur batch, etc.
  in @UseLockedOrkGid     integer,
  in @ConnId              integer,
  in @LoginTime           datetime,
  out @FactuurFout	      smallint
 )
begin
  //Uitdelen van nummers aan de betreffende documenten; facturen, pakbonnen, ord.bev., etc.
  declare @factuurnummer    	 nchar(40);
  declare @OudeDocNummer    	 nchar(10);
  declare @Betalingskenmerk 	 nchar(24);
  declare @tmpBetalingskenmerk nchar(24);
  declare @valnummer        integer;
  declare @VorigeOrkGid     integer;
  declare @orkgid           integer;
  declare @fkFactdebnummer  nchar(10);
  declare @fouteValuta      smallint;
  declare @LayoutSoortVoorFactNummer integer;
  declare @DocOrdBijOpnieuwNummeren smallint; // 0 = Nummer overslaan, 1 = Zelfde nummer gebruiken (indien mogelijk, anders NIET afdrukken?)
  declare @BetKenmerkObv smallint; // tabVasteGegevensOrdersFactureren.vofDocVulBetKenmerkMet: 0=Debnr/factnr, 1=Factnr, 2=Extern ordernr

  set @@ErrorTextProcedure = 'FacturerenUitdelenFactuurNummers > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @fbGid = ' + string(@fbGid) + ', @fkGid = ' + string(@fkGid) + ', @LeverFkGid = ' +string(@LeverFkGid) + ', @BjGid = ' +string(@bjgid) + ', @LayoutSoort = ' + string(@LayoutSoort));

  //Dit deel moet uniek gelocked (met een wacht-lus)
  call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'FacturerenUitdelenFactuurNummers', '');

  select DocOrdBijOpnieuwNummeren into @DocOrdBijOpnieuwNummeren from tabdocument where DocSoort = @LayoutSoort;

  //LET OP: @LayoutSoortVoorFactNummer wordt later ook nog een keer gebruikt!!
  set @LayoutSoortVoorFactNummer = @LayoutSoort;
  if @LayoutSoort = 60 then
    //Het is een directe facturering, dus misschien voor het fact.nummer omschakelen naar batchfacturering
    if exists(select 1 from tabDocument where DocOrdNummering = 1 and DocSoort = 60) then
      set @LayoutSoortVoorFactNummer = 50; //Batchfacturering
    end if;
  end if;
  if @LayoutSoort = 65 then
    //Het is project facturering, dus misschien voor het fact.nummer omschakelen naar batchfacturering
    if exists(select 1 from tabDocument where DocOrdNummering = 1 and DocSoort = 65) then
      set @LayoutSoortVoorFactNummer = 50; //Batchfacturering
    end if;
  end if;

  //Oude factuurnummer van gebruikte factuursoort (volgens DocOrdNummering) onthouden voor als de batch niet doorgaat
  select DocOrdStartNummer into @OudeDocNummer from tabdocument where DocSoort = @LayoutSoortVoorFactNummer;

// de factuur ophalen
  select   fkValnummer, fkFactdebnummer into @valnummer, @fkFactdebnummer
  from     tabFactuurKop left outer join tabrekeningschema on (RksInvoer = fkFactDebNummer)
  where    FkGid = @FkGid;

  //call Trace('FacturerenUitdelenFactuurNummers > Gevonden: @fkgid = ' + string(@fkgid) + ', @valnummer = ' + string(@valnummer) + ', @fkFactdebnummer = ' +string(@fkFactdebnummer));
  //Oude factuurnummer onthouden
  select DocOrdStartNummer into @OudeDocNummer from tabdocument where DocSoort = @LayoutSoortVoorFactNummer;

  set @factuurnummer = GeefNieuwFactuurNummer( @BjGid, @FbGid, @fkgid, @LayoutSoort );

  // ACW 13-10-2006: aanpassing t.b.v. betalingskenmerk op acceptgiro
  // RS 13-07-2013: uitbreiding tbv extern ordernr (of anders debnr/factnr)
  // RS 11-03-2014: uitbreiding tbv extern ordernr of anders factuurnummer | ook voor bovenstaande nav defect 41325 gezorgd dat externordernr op de ocr regel komt
  select first vofDocVulBetKenmerkMet into @BetKenmerkObv from tabVasteGegevensOrdersFactureren;
  if @BetKenmerkObv = 1 then/* o.b.v. Factuurnummer */
  	// Factuurnummer, netjes geOCRred: de manier t.b.v. acceptgiros
    set @Betalingskenmerk = OCRBetalingskenmerk(right('0000000000' + string(cast(@FactuurNummer as numeric(10,0))), 10));

  elseif @BetKenmerkObv = 2 then /* Extern ordernummer of Debnr/factnr */
  	set @Betalingskenmerk = (select first frefExternId from tabFactuurReferentie where frefFkGid = @FkGid and IsNull(frefExternId,'') <> '' order by frefOrderNummer);
  	if IsNull(@Betalingskenmerk, '') = '' then  // geen extern ordernr? dan debnr/factnr
  	  set @Betalingskenmerk = string(@fkFactdebnummer)+'/'+string(cast(@FactuurNummer as numeric(10,0)));
  	else
  	  if IsNumeric(@Betalingskenmerk) = 1 and length(@Betalingskenmerk) <= 15 then // numeriek en niet te lang? dan OCR van maken..
  		  set @tmpBetalingskenmerk = @Betalingskenmerk;
  		  set @Betalingskenmerk = OCRBetalingskenmerk(right('0000000000' + string(cast(@Betalingskenmerk as numeric(15,0))), 15));

  		  if @Betalingskenmerk = '' then // Als er geen OCR-kenmerk uitkomt was er toch iets mis wat bijv. niet door de isnumeric is afgevangen, dan terugvallen op het originele extern ordernr.
  		  	set @Betalingskenmerk = @tmpBetalingskenmerk;
  		  end if;
  		end if;
  	end if

  elseif @BetKenmerkObv = 3 then /* Extern ordernummer of Factuurnr */
	  set @Betalingskenmerk = (select first frefExternId from tabFactuurReferentie where frefFkGid = @FkGid and IsNull(frefExternId,'') <> '' order by frefOrderNummer);
  	if IsNull(@Betalingskenmerk, '') = '' then // geen extern ordernr? dan Factnr
  		set @Betalingskenmerk = OCRBetalingskenmerk(right('0000000000' + string(cast(@FactuurNummer as numeric(10,0))), 10));
  	else
  		if IsNumeric(@Betalingskenmerk) = 1 and length(@Betalingskenmerk) <= 15 then // geen extern ordernr? dan debnr/factnr
  		  set @tmpBetalingskenmerk = @Betalingskenmerk;
				set @Betalingskenmerk = OCRBetalingskenmerk(right('0000000000' + string(cast(@Betalingskenmerk as numeric(15,0))), 15));

  		  if @Betalingskenmerk = '' then // Als er geen OCR-kenmerk uitkomt was er toch iets mis wat bijv. niet door de isnumeric is afgevangen, dan terugvallen op het originele extern ordernr.
  		  	set @Betalingskenmerk = @tmpBetalingskenmerk;
  		  end if;
			end if;
  	end if

  elseif @BetKenmerkObv = 4 then /* Extern ordernummer of Debnr/factnr */
  	set @Betalingskenmerk = (select first frefExternId from tabFactuurReferentie where frefFkGid = @FkGid and IsNull(frefExternId,'') <> '' order by frefOrderNummer);
  	if IsNull(@Betalingskenmerk, '') = '' then  // geen extern ordernr? dan debnr/factnr
  	  set @Betalingskenmerk = string(@fkFactdebnummer)+'/'+string(cast(@FactuurNummer as numeric(10,0)));
  	end if

  elseif @BetKenmerkObv = 5 then /* Extern ordernummer of Factuurnr */
	  set @Betalingskenmerk = (select first frefExternId from tabFactuurReferentie where frefFkGid = @FkGid and IsNull(frefExternId,'') <> '' order by frefOrderNummer);
  	if IsNull(@Betalingskenmerk, '') = '' then // geen extern ordernr? dan Factnr
  		set @Betalingskenmerk = string(cast(@FactuurNummer as numeric(10,0)));
  	end if

  else
    // Debiteurnummer/factuurnummer: de vroegere manier van vullen
    set @Betalingskenmerk = string(@fkFactdebnummer)+'/'+string(cast(@FactuurNummer as numeric(10,0)));
  end if;

  update tabFactuurKop
  set fkFactuurNummer        = IsNull(@factuurnummer, ''),
      fkFactuurNummer_Lengte = length(IsNull(@factuurnummer, '')),
      fkBetalingskenmerk     = @Betalingskenmerk
  where FkGid = @FkGid;

  //  Betalingskenmerk vd factuur obv factuurnummer kopieren naar acceptgiro, tbv OCR Regel
  if (select fbAcceptGiroAfgedrukt from tabFactuurBatch where FbGid = @FbGid) in (1,2) then
    update tabAcceptGiro set AccBetalingskenmerk = @BetalingsKenmerk where AccFkGid = @FkGid;
  end if;

  if @LayoutSoort in (50,60) then
    //Controle voor factuur

    //Controleer of de valuta correct is
    set @fouteValuta = 0;
    select first 1 into @fouteValuta from tabopenstaandepost inner join tabrekeningschema on (rksgid = osprksgid) where ospfactuurnummer=@factuurnummer and OspFactuurNummer_Lengte = length(@factuurnummer) and rksinvoer=@fkFactdebnummer and ospvalnummer <> @valnummer and DefaultSoort = 6 and OspBjGId = @@BjGid;
    //call Trace('FacturerenUitdelenFactuurNummers > @fouteValuta = ' + string(@fouteValuta));
    //Als foute debiteur of foute valuta dan de factuur verwijderen en de orders ervan in niet-gefactureerd zetten
    if isnull(@fouteValuta,0) = 1 then

      //factuurnummer van gebruikte fact.soort (volgens DocOrdNummering) terugzetten op oude waarde (het is ongeldig verhoogd!)
      update tabdocument set DocOrdStartNummer = @OudeDocNummer where DocSoort = @LayoutSoortVoorFactNummer;

      //Orders in tabel 'niet gefactureerd' opnemen
      insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
      select @fbGid, frefOrkGid, 7, 1  //Valuta niet gelijk
      from  tabfactuurreferentie inner join taborderkop on (frefordernummer=orknummer)
      where frefFkGid = @FkGid
            and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbGid);

      //Orders vrijgeven en factuur verwijderen
      //Let op: Dit geldt alleen voor de orders waarvoor NIET geldt dat ze al gelocked zijn
      set @VorigeOrkGid = null;
      OrderLockLoop:
      loop
        set @OrkGid = null;
        select first frefOrkGid into @OrkGid
        from   tabfactuurreferentie
        where  frefFkGid = @FkGid and
               (@VorigeOrkGid is null or frefOrkGid > @VorigeOrkGid) and
               (@UseLockedOrkGid is null or frefOrkGid<>@UseLockedOrkGid)
        order by frefOrkGid;
        if @OrkGid is null then
          leave OrderLockLoop;
        end if;
        set @VorigeOrkGid = @OrkGid;
        //call Trace('FacturerenUitdelenFactuurNummers > Vrijgeven order; @OrkGid = ' +string(@OrkGid));
        if @ConnId is null then
          call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
        else
          call LockReleaseOnId(@ConnId, @LoginTime, 1, 'tabOrderKop', @OrkGid);
        end if;
      end loop OrderLockLoop;

      //Factuur uit de lijst halen
      delete from tabfactuurkop where fkgid=@fkgid;

    end if;

  end if;

  // Alleen bij hoofddocument deze val vullen
  if @FactuurFout is null then
    set @FactuurFout = IsNull(@fouteValuta,0);
    //call Trace('FacturerenUitdelenFactuurNummers > In hoofddocument FactuurFout = '+string(@FactuurFout));
  end if;

  // De bij de factuur horende pakbon nummeren
  if (@LeverFkGid is not null) and (@FactuurFout = 0) then
    //call Trace('FacturerenUitdelenFactuurNummers > Ophalen pakbonnummer bij leveren bij facturering');
    set @factuurnummer = GeefNieuwFactuurNummer( @BjGid, (select fkFbGid from tabFactuurKop where FkGid = @LeverFkGid), @Leverfkgid, 30 );

    update tabFactuurKop
    set fkFactuurNummer        = IsNull(@factuurnummer, ''),
        fkFactuurNummer_Lengte = length(IsNull(@factuurnummer, '')),
        fkBetalingskenmerk     = @Betalingskenmerk // Overnemen van factuur
    where FkGid = @LeverFkGid;
  end if;

  //Uitdelen factuurnummers-lock weer vrijgeven
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'FacturerenUitdelenFactuurNummers', '');

  set @@ErrorTextProcedure = 'FacturerenUitdelenFactuurNummers';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure FacturerenUpdateOrderAantallen(in @fkGid integer, in @IgnoreOrkGid integer )
begin
  // Update de aantallen (deze factuur/gefactureerd, Deze levering/Geleverd)
  // per 1-2021 Verwijderen orderregels en orders verhuisd naar FacturerenVerwijderVerwerkteOrderRegels

  declare @ErrText      nchar(500);
  declare @FactuurSoort integer;
  declare @OrkGid       integer;
  declare @PfvkGid      integer;
  declare @PfvkStatus   smallint;
  declare @FrefGid		  integer;
  declare @fkFactuurNummer nchar(40);

  declare cursor_OrdersAantallenProjecten cursor for
  select frefOrkGid, frefPfvkGid, fkFactuurNummer, FrefGid, PfvkStatus
  from   tabFactuurReferentie inner join tabFactuurKop on frefFkGid = FkGid inner join tabProjectFactuurVoorstelKop on PfvkGid = frefPfvkGid
  where  FkGid = @FkGid
  for read only;

  //set @ErrText = 'FacturerenUpdateOrderAantallen(@fkGid='+string(@fkGid)+', @IgnoreOrkGid='+string(@IgnoreOrkGid);
  //set @@ErrorTextProcedure = @ErrText;
  //call TraceBegin(@@ErrorTextProcedure);

  //Opvragen van het soort facturering
  select fbSoortBatch into @FactuurSoort from tabFactuurBatch where FbGid = (select FkFbGid from tabFactuurKop where fkGid = @FkGid);

  if IsModuleActive('ar') = 1 then
    //We hebben artikelen, dus deelfacturering is mogelijk...

    //De orders doorlopen en 'aantal gefactureerd' met 'aantal deze facturering' verhogen
    //call Trace('Update orderregels');
    if @FactuurSoort in (50,60,65) then
      //Facturering, dus aantal gefactureerd updaten
      set @@InFacturering = @@InFacturering + 1;
      update tabOrderRegel
      set    OrrAantalGefactureerd = if OrrRegelSoort = 0 then 1 else isnull(OrrAantalGefactureerd,0) + isnull(OrrAantalDezeFacturering,0) endif,
             OrrAantalDezeFacturering = 0,
             OrrAantalGefactureerdVrrdEenh = if OrrRegelSoort = 0 then 1 else isnull(OrrAantalGefactureerdVrrdEenh,0) + isnull(OrrAantalDezeFactureringVrrdEenh,0) endif,
             OrrAantalDezeFactureringVrrdEenh = 0
      from   tabFactuurKop inner join tabFactuurReferentie on (frefFkGid = FkGid)
      where  FkGid = @FkGid and OrrOrkGid = frefOrkGid;
      set @@InFacturering = @@InFacturering - 1;
    end if;

  end if;

  //call Trace('Projectfacturen - projecten bijwerken');
  if @FactuurSoort = 65 then

    open cursor_OrdersAantallenProjecten;
    LoopOrdersProjecten:
    loop
      Fetch next cursor_OrdersAantallenProjecten into @OrkGid, @PfvkGid, @fkFactuurNummer, @FrefGid, @PfvkStatus;
      if sqlstate = '02000' then
        leave LoopOrdersProjecten;
      end if;

      if @PfvkStatus in (1,3) then   // ProjectFactuur, statuscheck nav bug 25217
        // FactuurVoorstel status updaten, factuurnummer invullen en linkje naar factuurhistorie
        update tabProjectFactuurVoorstelKop set
               pfvkStatus    = (if @PfvkStatus = 3 then 0 else 2 endif),                    // Credit -> Concept, Vrijgegeven -> Gefactureerd
               pfvkFactuurNr = (if @PfvkStatus = 3 then null else @fkFactuurNummer endif),  // Credit -> Leegmaken, Vrijgegeven -> FactNr vullen
               PfvkFrefGid   = (if @PfvkStatus = 3 then null else @FrefGid endif)           // Credit -> Ref leegmaken, Vrijgegeven -> Ref vullen
               where PfvkGid = @PfvkGid;

        // evt status van projecttermijnen op gefactureerd zetten
        update tabprojectfactuurvoorstelkop
          inner join tabprojectfactuurvoorstelregel on pfvkgid = pfvrpfvkgid
          inner join tabprojectfactuurvoorstelrealisatie on pfvlFvrGid = pfvrgid
          inner join tabProjectTermijn on pfvlPtmGid = PtmGid
          set   PtmStatus = (if @PfvkStatus = 3 then 2 else 3 endif)  // Credit -> terug Op voorstel, Vrijgegeven -> Gefactureerd
          where PfvkGid = @PfvkGid;

        // evt aantallen van mutaties bijwerken
        update tabprojectboekingsregel
          inner join tabProjectFactuurVoorstelRealisatie on pfvlPbrGid = PbrGid
          inner join tabprojectfactuurvoorstelregel on PfvlFvrGid = PfvrGid
          inner join tabprojectfactuurvoorstelkop on PfvrPfvkGid = PfvkGid
          set   PbrAantalGefactureerd      = (if @PfvkStatus = 3 then PbrAantalGefactureerd - pfvlAantal else PbrAantalGefactureerd + pfvlAantal endif),
                PbrAantalOpFactuurVoorstel = (if @PfvkStatus = 3 then PbrAantalOpFactuurVoorstel + pfvlAantal else PbrAantalOpFactuurVoorstel - pfvlAantal endif)
          where PfvkGid = @PfvkGid;

        call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabProjectFactuurVoorstelKop', @PfvkGid);
      end if;
    end loop LoopOrdersProjecten;
    close cursor_OrdersAantallenProjecten;
  end if;

  //set @@ErrorTextProcedure = @ErrText;
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure FacturerenVerwerkOmzetGegevens(in @FkGid integer, in @BoekDatum date)
begin
  //Zet omzetgegevens in de tabel; doorsneden: Naw, Artikel, Opbrengstgroep, VtgCode. Velden: Omzet, Marge, Aantal

  //Factuurkop
  declare @NawGid                        integer;
  declare @fkIsInclBtw                   integer;
  declare @fkValNummer                   integer;
  declare @fkFactuurdatum                date;
  declare @fkFactuurNummer               nchar(10);
  //Orderregels / omzetten
  declare @FrefGid                       integer;
  declare @ArtGid                        integer;
  declare @ArtSoort                      integer;
  declare @OpbrGrpGid                    integer;
  declare @Aantal                        numeric(15,3);
  declare @Kostprijs                     numeric(15,3);
  declare @Omzet                         numeric(15,2);
  declare @OmzetBasis                    numeric(15,2);
  declare @BrutoOmzet                    numeric(15,2);
  declare @VtgCode                       integer;
  declare @LvcCode                       nchar(10);
  declare @BjGid                         integer;
  declare @Pernr                         integer;
  declare @frSoortRegel                  integer;
  declare @frBtwPercentage               numeric(5,2);

  //CBS
  declare @IsModuleActiveCBS             integer;
  declare @OrkCbsMeenemenInAangifte      integer;
  declare @CbsVastNaarCbsIrisUitvoer     integer;
  declare @CbsVastExtraHandelNaarCbsIris integer;
  declare @OrkGid                        integer;//uit loop orderregels
  declare @OrrCbsTrGid                   integer;//uit loop orderregels
  declare @OrrLndGidCbsOorsprong         integer;//uit loop orderregels
  Declare @OrrCbsDouaneregeling          nchar(4);
  declare @VorigeOrkGid                  integer;
  declare @LndGidEigenLand               integer;
  declare @EuroValNummer                 integer;
  //extra gegevens uit orderkop voor CBS
  declare @OrkCbsGsGid                   integer;
  declare @OrkCbsSsGid                   integer;
  declare @OrkCbslndGIDBestemming        integer;
  declare @OrkCbsPtnGidVerkeersgebied    integer;
  declare @OrkCbsVwGid                   integer;
  declare @OrkCbsCoGid                   integer;
  declare @OrkNummer                     numeric(10,0);
  declare @NawBtwNummer                  nchar(15);//van factuurNaw als die er is!)
  declare @LndIsEGLid                    integer;

  declare Cursor_FactuurRegels dynamic scroll cursor for
  select FrefGid, frefVtgCode, frefLvcCode, ArtGid, ArtSoort,
         frAantalDezeFactureringVrrdEenh, frKostprijs/frPrijsPer * FrAantalDezeFactureringVrrdEenh,
         ArtOpbrGrpGId, frSoortRegel, frRegelTotaal,
         ((if FrEenheidPrijsPer = 0 then /*Verkoopeenheid*/ frAantalBesteld else frAantalBesteldVrrdEenh endif)  * frBrutoPrijsPeenheid/frPrijsPer),
         frBtwPercentage, OrkGid, IsNull(OrkNawGidOmzet,OrkNawGid), OrrCbsTrGid, OrrLndGidCbsOorsprong, OrrCbsDouaneregeling
    from   tabFactuurReferentie
           inner join tabFactuurRegel on (FrFrefGid = FrefGid)
           inner join tabArtikel      on (ArtCode = FrArtCode and ArtSoort = FrSoortRegel)
           inner join tabOrderKop     on (OrkGid = FrefOrkGid)
           inner join tabOrderRegel   on (OrrGid = frOrrGid) //OrrOrkGid = FrefOrkGid and OrrRegelnr = frRegelNummer)
    where FrefFkGid = @FkGid and
      (frSoortRegel = 2 or // Artikelregels altijd
      (frSoortRegel = 1 and @@ModuleOS = 1) // of tarief, maar dan moet de optie Omzet ook aanwezig zijn
      )
  for read only;

  //call TraceBegin('FacturerenVerwerkOmzetGegevens > ' + '@FkGid = ' + string(@FkGid)+', @BoekDatum = ' + string(@BoekDatum));

  call BepaalBoekjaarEnPeriode(@BoekDatum, @BjGid, @PerNr);

  //CBS
  set @IsModuleActiveCBS = IsModuleActive('c1');
  select  CbsVastNaarCbsIrisUitvoer, CbsVastExtraHandelNaarCbsIris
    into @CbsVastNaarCbsIrisUitvoer,@CbsVastExtraHandelNaarCbsIris
    from tabCbsVast;
  select DefaultLndGid into @LndGidEigenLand from tabVasteGegevens;
  set @VorigeOrkGid = -1;
  select  ValNummer  into @EuroValNummer from tabValuta where IsEuro <> 0;
  if @EuroValNummer is null then
   set @EuroValNummer = @@BasisValutaNummer;
  end if;

  select  fkIsInclBtw,  fkValNummer,  fkFactuurdatum,  fkFactuurNummer
  into   @fkIsInclBtw, @fkValNummer, @fkFactuurdatum, @fkFactuurNummer
  from    tabFactuurKop
  where   FkGid = @FkGid;

  //call Trace('FacturerenVerwerkOmzetGegevens > @FkGid = ' + string(@FkGid) + ', @fkIsInclBtw = ' + string(@fkIsInclBtw) + ', @fkValNummer = ' + string(@fkValNummer));

  //Alle regels van deze factuur doorlopen
  open Cursor_FactuurRegels;
  Regels:
  Loop
    Fetch next Cursor_FactuurRegels into @FrefGid, @VtgCode, @LvcCode, @ArtGid, @ArtSoort, @Aantal, @Kostprijs, @OpbrGrpGid, @frSoortRegel, @Omzet, @BrutoOmzet, @frBtwPercentage, @OrkGid, @NawGid, @OrrCbsTrGid, @OrrLndGidCbsOorsprong, @OrrCbsDouaneregeling;
    if sqlstate = '02000' then
      leave Regels;
    end if;

    //Als de optie vertegenwoordigers er niet is, dan ook geen vertegenwoordiger gebruiken
    if @@ModuleVT = 0 then
      set @VtgCode = null;
    end if;

    //Korting/toeslag berekenen
    call Bereken_Omzet_Inclusief_KortingToeslag_FactuurExtraRegels (@frSoortRegel, @FrefGid, @BrutoOmzet, @fkIsInclBtw, @frBtwPercentage, @Omzet);

    //Bedrag eventueel terugrekenen naar basisvaluta
    // ACW 21-03-2002: Omzet werd 2x BTW uitgehaald als valuta <> basisvaluta !!!
    if @fkValNummer <> @@BasisValutaNummer then
      set @OmzetBasis = ValutaOmrekenen(@fkValNummer, @Omzet, @@BasisValutaNummer, @BjGid, @Pernr, 2);
    else
      set @OmzetBasis = @Omzet;
    end if;

    if @Aantal <> 0 then
      //call Trace('FacturerenVerwerkOmzetGegevens > Omzetbedrag onthouden in omzetgegevens-tabel');
      insert into tabOmzet(OmzArtGid, OmzNawGid, OmzOpbrGrpGId, OmzVtgCode, OmzArtSoort, OmzDatum, OmzAantal, OmzValNummer, OmzMargeBasis, OmzOmzetBasis, OmzOmzetValuta, OmzMargeStandaardBasis, OmzOmzetStandaardBasis, OmzOmzetStandaardValuta)
      values(@ArtGid, @NawGid, @OpbrGrpGid, @VtgCode, @ArtSoort, @BoekDatum, @Aantal, @fkValNummer, IsNull(@OmzetBasis - @Kostprijs, 0), IsNull(@OmzetBasis, 0), IsNull(@Omzet, 0), 0, 0, 0);
	  end if;

    //CBS tabel vullen======================================================================================================================
    if @IsModuleActiveCBS <> 0 and @CbsVastNaarCbsIrisUitvoer <> 0  then
      //eerst orderkopgegevens ophalen
      if @OrkGid <> @VorigeOrkGid then
        set @VorigeOrkGid = @OrkGid;
        select OrkCbsGsGid, OrkCbsSsGid, OrkCbslndGIDBestemming, OrkCbsPtnGidVerkeersgebied, OrkCbsVwGid, OrkCbsCoGid, OrkNummer, LndIsEGLid, OrkCbsMeenemenInAangifte,
               if orkfactuurnawgid is null then
                  (select nawbtwnummer from tabnaw where nawgid = orknawgid )
               else
                  (select nawbtwnummer from tabnaw where nawgid = orkfactuurnawgid )
               endif
        into  @OrkCbsGsGid, @OrkCbsSsGid, @OrkCbslndGIDBestemming, @OrkCbsPtnGidVerkeersgebied, @OrkCbsVwGid, @OrkCbsCoGid, @OrkNummer, @LndIsEGLid, @OrkCbsMeenemenInAangifte,
              @NawBtwnummer
        from  tabOrderKop left outer join tabLand on (LndGid = OrkCbslndGIDBestemming)
        where OrkGid = @OrkGid;
      end if;
      //als artikel en als land bestemming verschilt van eigen landcode, en land bestemming is EU lid of extra handel,  dan CBS tabel vullen
      if (@frSoortRegel = 2) and (@CbsVastNaarCbsIrisUitvoer <> 0) and (@OrkCbsMeenemenInAangifte <> 0) then
        //call Trace('FacturerenVerwerkOmzetGegevens > CBS Regel toevoegen');
        insert into tabCbsAangifteExport
               (CbsAeOrderOfMagOntv,                                                                    //Algemeen 0=MagOnt, 1=Order
                CbsAeAdministratieNr, CbsAeTransactiePeriode, CbsAeHandelsPartner,                      //Orderkop
                CbsAeCbsGsGid, CbsAeCbsSsGid, CbsAeLandBestHerk, CbsPtnGid, CbsAeCbsVwGid,              //Orderkop, Cbs
                CbsAeCbsCoGid,                                                                          //Orderkop, Cbs, Extra handel
                CbsAeCbsGcGid, CbsAeEigenGoederencode, CbsAeMaatstaf, CbsAeGewicht, CbsAeFactuurWaarde, //Orderregel, Artikelgegevens
                CbsAeCbsTrGid,                                                                          //Orderregel, Cbs
                CbsAeLandOorsprong,                                                                     //Orderregel, Cbs
                CbsAeLeveringscode,                                                                     //OrderKop, Leveringsconditie
                CbsAeDouaneregeling,                                                                    //Orderregel, Douaneregeling
                CbsAeReedsVerstuurd)                                                                    //bij inserten altijd 0
        select  1,
                cast(@fkFactuurNummer as numeric(10,0)), @fkFactuurdatum, trim(@nawBtwNummer),//Als factuurnr ooit letters gaat bevatten, dan CBS tabel aanpassen !
                @OrkCbsGsGid, @OrkCbsSsGid, (select LndIso3 from tabLand where LndGid = @OrkCbsLndGidBestemming), @OrkCbsPtnGidVerkeersGebied, @OrkCbsVwGid,
                @OrkCbsCoGid,
                ArtCbsGcGid, ArtCode,
                if IsNull(ArtCbsMaatstaf,0)=0 then
                  null
                else
                  round(@Aantal * ArtCbsMaatstaf,0)
                endif,//King eenheid omrekenen naar cbs eenheid(maatstaf), alleen als omrekenfactor bij artikel is ingevuld
                if (@Aantal > 0) and round(@Aantal * (ArtGewicht/ArtGewichtPer),0) = 0 then
                  1
                else
                  round(@Aantal * (ArtGewicht/ArtGewichtPer),0)
                endif,//bij positieve aantallen: gewicht is 1 of meer
                if @@BasisValutaNummer <> @EuroValNummer then ValutaOmrekenen(@@BasisValutaNummer, @OmzetBasis, @EuroValNummer, @BjGid, @Pernr, 0) else round(@OmzetBasis,0) endif,
                //Factuurwaarde altijd in euros, als bedrag nul is, dan zal Iris bij importeren eventueel een melding geven
                @OrrCbsTrGid,
                (select LndIso3 from tabLand where LndGid = @OrrLndGidCbsOorsprong),
                @LvcCode,
                @OrrCbsDouaneregeling,
                0
        from    tabArtikel
        where   ArtGid = @ArtGid and IsNull(@Aantal,0.00) <> 0.00;
      end if;
    end if;
    //einde CBS tabel vullen================================================================================================================
  end loop Regels;
  close Cursor_FactuurRegels;

  //call TraceEind('FacturerenVerwerkOmzetGegevens');
end;


create or replace procedure FacturerenVerwijderDummy(in @fbGid integer)
begin
  //De dummy-factuurbatch wordt geheel ongedaan gemaakt

  set @@ErrorTextProcedure = 'FacturerenVerwijderDummy( @FbGid = '+string(@FbGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  //Factuurbatch verwijderen
  delete from tabFactuurBatch where fbGid = @fbGid;

  //Factuuroverzicht verwijderen
  delete from tabFactuurOverzichtValuta where fovFbGid = @fbGid;
  delete from tabFactuurOverzichtBtw where fobFbGid = @fbGid;
  delete from tabFactuurOverzichtOpbrengstGroep where fooFbGid = @fbGid;

  //Leveroverzicht verwijderen
  delete from tabLeverOverzichtOpbrengst where looFbGid = @fbGid;
  delete from tabLeverOverzichtTussenrekening where lotFbGid = @fbGid;

  //Status van 'niet gefactureerde orders' weer verwijderen
  delete from tabFactuurNietGefactureerd where fngFbGid = @fbGid;

  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid));
  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'Factuuroverzicht', @FbGid);

  //call TraceEind( 'FacturerenVerwijderDummy');

end;


//$Workfile: FacturerenVerwijderFactuurLocks.sp $ $Revision: 3 $ $Modtime: 1-10-10 8:46 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenVerwijderFactuurLocks') then
  drop procedure FacturerenVerwijderFactuurLocks;
end if;

create procedure FacturerenVerwijderFactuurLocks(in @fbGid integer, in @IgnoreOrkGid integer, in @OrdersUnlocken integer)
begin
  declare @VorigeOrkGid integer;
  declare @OrkGid       integer;
  declare @PfvkGid      integer;
  declare @DocSoort     integer;
  declare @AcbGid       integer;

  declare @vofStatusIsVrijNaFactureren smallint;
  declare @vofStatusIsVrijNaleveren    smallint;

  set @@ErrorTextProcedure = 'FacturerenVerwijderFactuurLocks > @FbGid='+string(@FbGid)+', @IgnoreOrkGid='+string(@IgnoreOrkGid)+', @OrdersUnlocken='+string(@OrdersUnlocken);
  //call TraceBegin(@@ErrorTextProcedure);

  //documentsoort ophalen
  select fbSoortBatch into @DocSoort from tabFactuurBatch where fbGid = @FbGid;

  // !!!!!! 27-3-2012 dit block wordt nu na verwerking PER FACTUUR gedaan zodat de openstaande orders eerder beschikbaar komen - FactUnlockOrders.sp
  // ALleen bij Previews moeten de orders weer unlocked worden, dan staat @OrdersUnlocken op 1
  set @VorigeOrkGid = null;
  if @OrdersUnlocken <> 1 then
    OrderLoop:
    loop
      set @OrkGid = null;
      select first frefOrkGid, frefPfvkGid into @OrkGid, @PfvkGid from tabFactuurReferentie inner join tabFactuurKop on (FkGid = frefFkGid) where fkFbGid=@fbGid and (@VorigeOrkGid is null or frefOrkGid > @VorigeOrkGid) and (@IgnoreOrkGid is null or frefOrkGid<>@IgnoreOrkGid) order by frefOrkGid;
      if @OrkGid is null then
        //call Trace('Vrijgeven orderloop is leeg !  -> Exit ');
        leave OrderLoop;
      end if;
      //call Trace('Vrijgeven order; @OrkGid='+string(@OrkGid));
      set @VorigeOrkGid = @OrkGid;
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
      if @DocSoort = 65 then // Projectfactuur
      	delete tabOrderKop where OrkGid = @OrkGid;
        //call Trace('Vrijgeven ProjectFactuurVoorstelKop; @PfvkGid='+string(@PfvkGid));
        call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabProjectFactuurVoorstelKop', @PfvkGid);
      end if;
    end loop OrderLoop;
  end if;

  if @DocSoort = 65 then
    //call Trace('Niet afgedrukte projectorders verwijderen');
    set @VorigeOrkGid = null;
    OrderLockLoop:
    loop
       set @OrkGid = null;
       select first fngOrkGid, OrkPfvkGid into @OrkGid, @PfvkGid from tabFactuurNietGefactureerd inner join tabOrderKop on fngOrkGid = OrkGid
        where fngFbGid = @FbGid and fngReden <> 6 and (@VorigeOrkGid is null or fngOrkGid > @VorigeOrkGid) and fngLockedByMe = 1 order by fngOrkGid;
       if @OrkGid is null then
	 leave OrderLockLoop;
       end if;
       set @VorigeOrkGid = @OrkGid;

       call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
       delete tabOrderKop where OrkGid = @OrkGid;
     end loop OrderLockLoop;
  end if;


  //En de factuurbatch verwijderen (Als het een pakbon of factuur is, dan wordt die bij FacturerenOrdersVerwijderen eventueel verwijderd!!)
  if @DocSoort not in (30,35,50,60,65) then
    // Factuurbatch verwijderen als het *geen* pakbon of factuur is.
    delete from tabFactuurBatch where fbGid = @fbGid and fbIsVerwerkt = 2;
  end if;

  // Lock van acceptgirobatch verwijderen
  select first AcbGid into @AcbGid from tabAcceptGiroBatch where AcbfbGid = @FbGid;
  if @AcbGid is not null then
    call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabAcceptGiroBatch', 'AcbGid='+string(@AcbGid));
  end if;

  // Lock van factuurbatch verwijderen
  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid));

  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: FacturerenVerwijderLegeFacturen.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='FacturerenVerwijderLegeFacturen') then
  drop procedure FacturerenVerwijderLegeFacturen;
end if;

create procedure FacturerenVerwijderLegeFacturen( in @FbGid integer, in @LayoutSoort integer)
begin
  //Facturen/leveringen die geen tekstregels hebben en ook geen artikel/tariefregels met een ingevuld aantal eruit halen
  declare @PakbonAfdruk integer;

  set @@ErrorTextProcedure = 'FacturerenVerwijderLegeFacturen > @FbGid='+string(@FbGid)+', @LayoutSoort='+string(@LayoutSoort);
  //call TraceBegin(@@ErrorTextProcedure);
  set @PakbonAfdruk = 0;
  if @Layoutsoort = 30 then
    //Opvragen of we voor de levering ook een pakbon moeten afdrukken
    select vofLevIsPakbonAfdrukken into @PakbonAfdruk from tabVastegegevensOrdersFactureren;
  end if;

  if @Layoutsoort <> 60 and (@Layoutsoort <> 30 or @PakbonAfdruk = 1) then
    //Facturen zonder rapportnummer als 'niet gefactureerd' beschouwen; Leveringen wel toestaan als een pakbon toch niet wordt afgedrukt!
    //(Als directe facturering, dan door laten gaan omdat de layout in voorloopscherm kan worden ingesteld)
    //call Trace('Facturen zonder layouts verwijderen?');
    if not exists(select 1 from tabDocument where DocOrdAfdrukkenFactuurAcceptgiro = 1 and DocSoort = @LayoutSoort) then
      // Alleen als we voor dit document niet alleen de acceptgiro afdrukken
      // (Dus als we alleen een acceptgiro afdrukken dan doet de layout hier niet ter zake)
      //call Trace('Ja: Facturen zonder layouts verwijderen! We hebben nl. niet alleen acceptgiros');

      insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
      select @fbGid, tfoTeFactOrkGid, 4, 1
      from   tabFactuurKop inner join tabFactuurReferentie on (frefFkGid = FkGid) inner join tabTeFacturerenOrders on ( tfoTeFactOrkGid = frefOrkGid )
      where  tfoSessieFbGid = @FbGid and
             fkRapNummer is null and fkfbGid = @fbGid
             and tfoTeFactOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid);
      delete from tabFactuurKop where fkRapNummer is null and fkfbGid = @fbGid;
    end if;
  end if;

  if @LayoutSoort in (30,50) then
    //Voor de levering: verwijder orders waarvoor geldt: heeft geen tekstregels, geen tariefregels *en* geen artikelregels met aantal te leveren
    //call Trace('Facturen zonder te factureren gegevens in de NietGefactureerd zetten');
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden, fngLockedByMe )
    select @fbGid, frefOrkGid, if @LayoutSoort = 50 then 9 else 10 endif, 1 //order heeft geen te factureren/leveren gegevens
    from tabFactuurKop inner join tabFactuurReferentie on frefFkGid = FkGid
    where fkFbGid = @fbGid and //Facturen van deze batch
          exists(select 1
                 from tabfactuurregel
                 where frFrefGid = FrefGid and
                       frSoortRegel <> 0) and   //Dus alleen tekstregel -> false, dus NIET verwijderen
          not exists(select 1
                     from tabfactuurregel
                     where frFrefGid = FrefGid and
                           // WAS: frSoortRegel in (1,2) and if @LayoutSoort = 30 then frAantalDezeLevering else frAantalDezeFacturering endif<>0)  //Artikelregel MET aantal deze levering/facturering
                          frSoortRegel in (1,2) and if @LayoutSoort = 30 then frAantalDezeLeveringVrrdEenh else (if FrEenheidPrijsPer = 0 /*Verkoopeenheid*/ then frAantalDezeFacturering else frAantalDezeFactureringVrrdEenh endif) endif<>0)  //Artikelregel MET aantal deze levering/facturering
         and frefOrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @fbgid); //Komt inderdaad nog niet in de niet-te-factureren lijst voor
    ;
  end if;

  //Orders verwijderen die niet worden afgedrukt
  //call Trace('Factuurreferenties zonder orderregels verwijderen uit factuurtabel');
  delete from tabFactuurReferentie
  where frefOrkGid in (select fngOrkGid from tabFactuurNietGefactureerd where fngFbGid = @FbGid) and
          frefFkGid in (select FkGid from tabFactuurKop where FkFbGid = @FbGid);

  //Facturen zonder orders verwijderen
  //call Trace('Lege facturen verwijderen uit factuurtabel');
  delete from tabFactuurKop where not exists( select 1 from tabFactuurReferentie where FrefFkGid = FkGid) and FkFbGid = @FbGid;

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure FacturerenVerwijderVerwerkteOrderRegels(in @fkGid integer, in @IgnoreOrkGid integer )
begin
  // Update de aantallen (deze factuur/gefactureerd, Deze levering/Geleverd)
  // Verwijder tevens de orders indien deze volledig zijn verwerkt

  declare @ErrText      nchar(500);
  declare @FactuurSoort integer;
  declare @OrkGid       integer;
  declare @IsWegTekst   integer; //0=Niet, 1=na factureren, 2=na leveren, 3=na factureren *en* leveren
  declare @IsWegArtikel integer; //0=Niet, 1=na factureren
  declare @IsWegTarief  integer; //0=Niet, 1=na factureren, 3=na factureren *en* leveren
  declare @LevOokTekst  integer;
  declare @LevOokTarief integer;
  declare @tmp          integer;
  declare @OrderBestaat integer;
  declare @PfvkGid      integer;
  declare @PfvkStatus   smallint;
  declare @FrefGid		  integer;
  declare @fkFactuurNummer nchar(40);

  declare cursor_OrdersAantallenUnlock cursor for
  select frefOrkGid, fkFactuurNummer, FrefGid
  from   tabFactuurReferentie inner join tabFactuurKop on frefFkGid = FkGid
  where  FkGid = @FkGid
  for read only;

  //set @ErrText = 'FacturerenVerwijderVerwerkteOrderRegels(@fkGid='+string(@fkGid)+', @IgnoreOrkGid='+string(@IgnoreOrkGid);
  //set @@ErrorTextProcedure = @ErrText;
  //call TraceBegin(@@ErrorTextProcedure);

  //Opvragen van het soort facturering
  select fbSoortBatch into @FactuurSoort from tabFactuurBatch where FbGid = (select FkFbGid from tabFactuurKop where fkGid = @FkGid);

  select first vofFactIsTekstRegelVerwijderen, vofFactIsTariefRegelVerwijderen, vofFactIsArtikelRegelVerwijderen, vofLevOokTekst, vofLevOokTarief into @IsWegTekst, @IsWegTarief, @IsWegArtikel, @LevOokTekst, @LevOokTarief from tabVasteGegevensOrdersFactureren;

  if IsModuleActive('ar') = 1 then
    //Regels verwijderen na factureren / levering:

    //call Trace('Te verwijderen orderregels bijeenzoeken');
    //call Trace('@IsWegTekst='+string(@IsWegTekst)+', @LevOokTekst='+string(@LevOokTekst)+', @IsWegTarief='+string(@IsWegTarief)+', @LevOokTarief='+string(@LevOokTarief)+', @IsWegArtikel='+string(@IsWegArtikel));

    //select count(1) into @tmp from taborderregel;
    //call Trace('Aantal regels ervoor: '+string(@tmp));

    set @@InFacturering = @@InFacturering + 1;
    delete from tabOrderRegel where OrrGid in
      (select binnen.OrrGid
       from   tabOrderRegel binnen
              inner join tabOrderKop on binnen.OrrOrkGid = OrkGid
              inner join tabFactuurReferentie on (frefOrkGid = binnen.OrrOrkGid)
              inner join tabFactuurKop on (fkgid = frefFkGid)
       where  FkGid = @FkGid
              and ( //Tekstregel: IsGefactureerd and (IsGeleverd or not TekstOokLeveren)
                   (binnen.OrrRegelSoort = 0 and
                     ((@IsWegTekst = 1 and binnen.OrrAantalGefactureerd <> 0 and binnen.OrrAantalGefactureerdVrrdEenh <> 0) or  //IsWeg=Na fact. *en* de regel is gefactureerd
                      (@IsWegTekst = 2 and binnen.OrrAantalGeleverd     <> 0 and binnen.OrrAantalGeleverdVrrdEenh     <> 0) or  //IsWeg=Na lev. *en* de regel is geleverd
                      (@IsWegTekst = 3 and binnen.OrrAantalGefactureerd <> 0 and binnen.OrrAantalGefactureerdVrrdEenh <> 0 and ((isnull(binnen.OrrAantalGeleverd,0)<>0 and isnull(binnen.OrrAantalGeleverdVrrdEenh,0)<>0) or @LevOokTekst = 0))      //IsWeg=Na fact.+lev. *en* de regel is gefactureerd *en* geleverd
                     )
                   ) or
                    //Tariefregel: Aantal gefact.=aantal besteld and (aantal gelev.<>0 or not TariefOokLeveren) and not TariefWegNaVolledigFactLever
                   (binnen.OrrRegelSoort = 1 and
                     ((@IsWegTarief = 1 and binnen.OrrAantalGefactureerd = binnen.OrrAantalBesteld and binnen.OrrAantalGefactureerdVrrdEenh = binnen.OrrAantalBesteldVrrdEenh) or  //IsWeg=Na factureren *en* er is evenveel gefactureerd als besteld
                      (@IsWegTarief = 3 and binnen.OrrAantalGefactureerd = binnen.OrrAantalBesteld and binnen.OrrAantalGefactureerdVrrdEenh = binnen.OrrAantalBesteldVrrdEenh and ((binnen.OrrAantalGeleverd <> 0 and binnen.OrrAantalGeleverdVrrdEenh <> 0) or @LevOokTarief = 0)) //IsWeg=Na fact+lev. *en* er is evenveel gefact. als besteld *en* er is geleverd (of tarieven worden niet geleverd)
                     )
                   ) or
                    //Artikelregel: Aantal gefact.=aantal gelev.=aantal besteld and not ArtikelWeg
                   (binnen.OrrRegelSoort = 2 and
                      @IsWegArtikel = 3 and
                      (
                        ( //Aantal mag niet afwijken (vast aantal)
                          (binnen.OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0) and
                          (binnen.OrrAantalGeleverdVrrdEenh = binnen.OrrAantalGefactureerdVrrdEenh) and (binnen.OrrAantalGefactureerdVrrdEenh = binnen.OrrAantalBesteldVrrdEenh)
                        ) or
                        ( //Aantal mag afwijken bij Aantal besteld
                          (binnen.OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1) and
                          (binnen.OrrAantalGeleverd = binnen.OrrAantalGefactureerd) and (binnen.OrrAantalGefactureerd = binnen.OrrAantalBesteld)
                        ) or
                        ( //Aantal mag afwijken bij Levering/Facturering
                          (binnen.OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2) and
                          (binnen.OrrAantalGeleverd = binnen.OrrAantalGefactureerd) and (binnen.OrrAantalGefactureerd = binnen.OrrAantalBesteld) and
                          (binnen.OrrAantalGeleverdVrrdEenh = binnen.OrrAantalGefactureerdVrrdEenh)
                        )
                      )
                    )
                  )
      );

    call Maatwerk_FacturerenLeverenOrderregelsZijnVerwijderd(@fkGid);

    set @@InFacturering = @@InFacturering - 1;

    //select count(1) into @tmp from taborderregel;
    //call Trace('Aantal regels erna  : '+string(@tmp));
    //select count(1) into @tmp from taborderkop;
    //call Trace('Aantal orders ervoor: '+string(@tmp));

    //Verwijder alle orders die nu geen regels meer hebben of die toch mogen vervallen
    //(dus tarief, tekst en artikel (die laatste alleen als alles gefact.+(evt.)geleverd)
    // Laat de orderkop staan indien:
    // - er een artikelregel is die nog niet geheel is geleverd of gefactureerd
    // - er een tariefregel is die nog niet geheel is geleverd
    // dus tekstregels en het nog niet geleverd zijn van tariefregels bepalen NIET dat een orderkop blijft staan!
    //call Trace('Verwijder onnodige orders');
    delete from tabOrderKop where OrkGid in
      (select frefOrkGid
       from   tabFactuurReferentie
              inner join tabOrderKop on frefOrkGid = OrkGid
              inner join tabFactuurKop on (fkGid = frefFkGid)
       where  fkGid = @FkGid
              and (not exists(select 1 //Bevat regels die moeten blijven staan?? (Dus artikelregel die nog niet geheel is geleverd/gefactureerd)
                             from   tabOrderRegel
                             where  OrrOrkGid = frefOrkGid and
                                    (
                                      //Tariefregel
                                     (OrrRegelSoort = 1 and
//                                      (OrrAantalGefactureerd <> OrrAantalBesteld or (OrrAantalGeleverd <> OrrAantalBesteld and @LevOokTarief = 1) )
                                      (OrrAantalGefactureerd <> OrrAantalBesteld) and
                                      (OrrAantalGefactureerdVrrdEenh <> OrrAantalBesteldVrrdEenh)
                                     ) or
                                      //Artikelregel: Aantal gefact.<>aantal gelev.<>aantal besteld
                                     (OrrRegelSoort = 2 and
                                      (
                                        ( /*Aantal mag niet afwijken (vast aantal)*/
                                          (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0) and
                                          not ((OrrAantalGeleverdVrrdEenh = OrrAantalGefactureerdVrrdEenh) and (OrrAantalGefactureerdVrrdEenh = OrrAantalBesteldVrrdEenh))
                                        ) or
                                        ( /*Aantal mag afwijken bij Aantal besteld*/
                                          (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1) and
                                          not ((OrrAantalGeleverd = OrrAantalGefactureerd) and (OrrAantalGefactureerd = OrrAantalBesteld))
                                        ) or
                                        ( /*Aantal mag afwijken bij Levering/Facturering*/
                                          (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2) and
                                          not ((OrrAantalGeleverd = OrrAantalGefactureerd) and (OrrAantalGefactureerd = OrrAantalBesteld) and
                                               (OrrAantalGeleverdVrrdEenh = OrrAantalGefactureerdVrrdEenh)
                                              )
                                        )
                                      )
                                     )
                                    )
                            )
                )
      );
    //select count(1) into @tmp from taborderkop;
    //call Trace('Aantal orders erna  : '+string(@tmp));
  else
    //We hebben geen artikelen, dus 'gewoon' de orders verwijderen
    delete from tabOrderKop where OrkGid in
      (select frefOrkGid
       from   tabFactuurReferentie
              inner join tabFactuurKop on (fkGid = frefFkGid)
       where  fkGid = @FkGid);
//    commit; // ACW/RVL 24-12-2003: Kans op Deadlock Detected verminderen

  end if;

  //De orderlocks terugzetten van (deels) verwijderde orders

  //call Trace('Locks vrijgeven');
  if @FactuurSoort in (30, 50, 60, 65) then
    //Lock weg als batchfactureren of als DIRECTE FACTURERING en order is geheel gefactureerd.
    open cursor_OrdersAantallenUnlock;
    LoopOrdersUnlock:
    loop
      Fetch next cursor_OrdersAantallenUnlock into @OrkGid, @fkFactuurNummer, @FrefGid;
      if sqlstate = '02000' then
        leave LoopOrdersUnlock;
      end if;
      //call Trace('Unlock order @OrkGid='+string(@OrkGid)+'? (@FactuurSoort='+string(@FactuurSoort)+')');
      set @OrderBestaat = 0;
      select first 1 into @OrderBestaat from tabOrderKop where OrkGid = @OrkGid;
      if (@FactuurSoort in (30, 50, 65)) or @OrderBestaat = 0 then
        //Factuur of pakbon OF order is verwijderd
        if @OrderBestaat = 0 or @OrkGid <> isnull(@IgnoreOrkGid,-1) then
          //De order is verwijderd of is niet dezelfde als die door de orderEdit taak in gebruik
          call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
        end if;
      end if;
    end loop LoopOrdersUnlock;
    close cursor_OrdersAantallenUnlock;
  end if;

  //set @@ErrorTextProcedure = @ErrText;
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure FactureringOvernemenVrijeRubrieken(in @KeySoort smallint, in @DoelGid integer, in @BronGid integer, in @IsDemo smallint)
begin
  declare @FonGid nchar(3);

  set @@ErrorTextProcedure = 'FactureringOvernemenVrijeRubrieken > @KeyGid='+string(@DoelGid);
  //call TraceBegin(@@ErrorTextProcedure);
  select right('000'+cast(FonGid as nchar(3)),3) into @FonGid from tabFileOfNaw where FonId='D';

  // BronGid   = Waar de VR aan gelinkt is..    NAWGid of ProjGid
  // DoelGid   = Waar de VR aan gelinkt wordt.. FkGid of FrefGid
  // @KeySoort = 0 - Factuurkop, 1 - Factuurreferentie, 2 - Project
  if (@KeySoort in (0,1) and @FonGid is not null) or (@KeySoort not in (0,1)) then
    case @KeySoort
      when 0 then call OvernemenVrijeRubrieken(@KeySoort, @DoelGid, @BronGid, 'NAW', @FonGid, @FonGid, 'tabFactuurVrijeRubriek',   'fvrFkGid', 'fvr', @IsDemo);
      when 1 then call OvernemenVrijeRubrieken(@KeySoort, @DoelGid, @BronGid, 'NAW', @FonGid, @FonGid, 'tabFactuurVrijeRubriek', 'fvrFrefGid', 'fvr', @IsDemo);
      when 2 then call OvernemenVrijeRubrieken(@KeySoort, @DoelGid, @BronGid, 'PRJ',   '000',  '000 ', 'tabFactuurVrijeRubriek',   'fvrFkGid', 'fvr', @IsDemo);
      when 3 then call OvernemenVrijeRubrieken(@KeySoort, @DoelGid, @BronGid, 'ORK',   '000',  '000 ', 'tabFactuurVrijeRubriek', 'fvrFrefGid', 'fvr', @IsDemo);
      when 4 then call OvernemenVrijeRubrieken(@KeySoort, @DoelGid, @BronGid, 'ORR',   '000',  '000 ', 'tabFactuurVrijeRubriek',   'fvrFrGid', 'fvr', @IsDemo);
    end case;
  end if;

  //call TraceEind(@@ErrorTextProcedure);


end;
//call FactureringOvernemenVrijeRubrieken(0, 0, 0);


create or replace procedure FactureringOvernemenVrijeRubriekenArt(
in @PrimGid integer,             // Verwijzing in @DstTableName naar record van parent (Bijv. frGid als het om tabFactuurRegelVrijeRubriekArt gaat)
in @SearchGid integer,           // Verwijzing van de source object (bijv, @ArtGid bij vrije rubrieken artikelen of @NawGid bij vrije rubrieken NAW)
in @IsDemo smallint)             // 1 = demonstratie-inhoud, 0= werkelijke inhoud vullen
begin
  set @@ErrorTextProcedure = 'FactureringOvernemenVrijeRubriekenArt > @PrimGid='+string(@PrimGid);
   //call TraceBegin(@@ErrorTextProcedure);
  call OvernemenVrijeRubrieken(-1, @PrimGid, @SearchGid, 'ART', '000', '000', 'tabFactuurRegelVrijeRubriekArt', 'frvraFrGid', 'frvra', @IsDemo);

  set @@ErrorTextProcedure = 'FactureringOvernemenVrijeRubriekenArt';
   //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure FactureringOvernemenVrijeRubriekenPartij(
in @BronSoort smallint, 				 // 0 FactuurRegel, 1 FactuurPartijSerie
in @PrimGid integer,             // Verwijzing in @DstTableName naar record van parent (Bijv. frGid als het om tabFactuurRegelVrijeRubriekArt gaat)
in @SearchGid integer,           // Verwijzing van de source object (bijv, @ArtGid bij vrije rubrieken artikelen of @NawGid bij vrije rubrieken NAW)
in @IsDemo smallint)             // 1 = demonstratie-inhoud, 0= werkelijke inhoud vullen
begin
  set @@ErrorTextProcedure = 'FactureringOvernemenVrijeRubriekenPartij > @PrimGid='+string(@PrimGid);
  //call TraceBegin(@@ErrorTextProcedure);
  if @BronSoort = 0 then
  	call OvernemenVrijeRubrieken(-1, @PrimGid, @SearchGid, 'PAR', '000', '000', 'tabFactuurRegelVrijeRubriekPartij', 'frvrpFrGid', 'frvrp', @IsDemo);
  else
    call OvernemenVrijeRubrieken(-1, @PrimGid, @SearchGid, 'PAR', '000', '000', 'tabFactuurRegelVrijeRubriekPartij', 'frvrpFrpsGid', 'frvrp', @IsDemo);
  end if;

  set @@ErrorTextProcedure = 'FactureringOvernemenVrijeRubriekenPartij';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure FactureringVulAdressenIn(in @FkGid integer, in @LayoutSoort integer, in @OrkFactuurNawGid integer)
begin
  declare @AdrGidFactuur          integer;  // Factuuradres van de factuurdebiteur
  declare @AdrGidVestOrderDeb     integer;  // Vestigingsadres orderdebiteur
  declare @AdrGidCorrOrderDeb     integer;  // Correspondentieadres orderdebiteur
  declare @AdrGidEindBestOrderDeb integer;  // Eindbestemmingsadres van de orderdebiteur
  declare @AdrGidVanVerzending    integer;  // Verzendadres order-/factuurdebiteur (volgens instellingen in de order; kan dus ook evt. van de factuurdebiteur zijn!!)
  declare @NawGidVanVerzending    integer;  // Verzendadres kan zowel van de factuurdebiteur als van de orderdebiteur zijn!!
  declare @OrkEindAdres           smallint;
  declare @EersteOrkGid           integer;  // Omdat helaas nog steeds enkele factuurkop-gegevens uit de eerste order komen ...
  declare @OrkFactuurAdres        smallint;
  declare @OrkVerzendadres        smallint;
  declare @OrkAdrGid              integer;
  declare @GebruikCorrAdresVanFactuurDeb smallint; // 0: corr.adres document = corr.adres van orderdeb.; 1: corr.adres document = corr.adres van factuurdeb.
  declare @AdresVest         integer;
  declare @fkFactDebNummer   nchar(10);
  declare @NawGidOrder       integer;

  declare @NawFactuurNawGidCorrespondentie integer;
  declare @NawFactuurNawGidVestiging       integer;

  set @@ErrorTextProcedure = 'FactureringVulAdressenIn(@FkGid='+string(@FkGid)+', @LayoutSoort='+string(@LayoutSoort)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  if isnull((select count(*) from tabFactuurReferentie where FrefFkGid = @FkGid), 0) = 1 then
    set @GebruikCorrAdresVanFactuurDeb = 0; // Gebruik van de orderdeb. want er is precies 1 order
  else
    set @GebruikCorrAdresVanFactuurDeb = 1; // Gebruik van de factuurdeb. want er zijn meer dan 1 order!
  end if;

  // Opvragen van het factuuradressoort en ordergidje van de eerste order in de factuur
  select first frefOrkGid into @EersteOrkGid    from tabFactuurReferentie where frefFkGid = @FkGid order by frefGid;
  select first OrkFactuurAdres  into @OrkFactuurAdres from tabOrderKop          where OrkGid = @EersteOrkGid;

  select First fkFactDebNummer into @fkFactDebNummer from tabfactuurkop where fkgid= @FkGid;

  // *** Opvragen van adresgegevens van de factuurdebiteur ***
  /*
    Per 5-4-2012 is hier verwijderd het ophalen van het gidje van de factuurdebiteur (indien niet ingevuld orderdebiteur)
    Om performanceredenen wordt deze nu meegestuurd vanuit de aanroepende proc (FactStartMaakFacturen.sp)
  */

  select First  NawGidCorrespondentie,            NawGidVestiging,            if @OrkFactuurAdres = 0 then nawGidCorrespondentie else NawGidVestiging endif
  into          @NawFactuurNawGidCorrespondentie, @NawFactuurNawGidVestiging, @AdrGidFactuur
  from   tabNaw
  where (nawgid= @OrkFactuurNawGid);

  // *** Adressen aan de factuurKOP plakken ***


  // Factuuradres van de factuurdebiteur invullen
  call VulFactuurAdres( 1, @FkGid, null, @EersteOrkGid, @AdrGidFactuur, @OrkFactuurNawGid, @LayoutSoort);
//  // Correspondentieadres factuurdebiteur invullen
//  call VulFactuurAdres( 2, @FkGid, null, @EersteOrkGid, @NawFactuurNawGidCorrespondentie,      @OrkFactuurNawGid,       @LayoutSoort);

  // *** Lusje per factuurreferentie ***
  for @FactRefCursor AS CURSOR_FactuurReferentie CURSOR FOR
    select frefGid @FrefGid, frefOrkGid @OrkGid, frefOrderDebNummer @frefOrderDebNummer
    from   tabFactuurReferentie
    where  frefFkGid = @FkGid
    order by frefGid
  for read only
  do

    if @frefOrderDebNummer = @fkFactDebNummer then
      //orderdebiteur is zelfde als factuurdebiteur, dus die gegevens kunnen gewoon gebruikt worden
      set @NawGidOrder          = @OrkFactuurNawGid;
      set @AdrGidCorrOrderDeb   = @NawFactuurNawGidCorrespondentie;
      set @AdrGidVestOrderDeb   = @NawFactuurNawGidVestiging;
    else
      // *** Opvragen van adresgegevens van de orderdebiteur ***
      select First NawGid,       nawGidCorrespondentie, NawGidVestiging
      into         @NawGidOrder, @AdrGidCorrOrderDeb,   @AdrGidVestOrderDeb
      from   tabNawFile
             inner join tabNaw on (nawgid= nawfilnawgid)
      where  (nawFilFonId='D') and (nawfilNummer = @frefOrderDebNummer);
    end if;

    // Opvragen order(kop) gegevens
    select First OrkVerzendadres,  OrkAdrGid,
                 OrkEindAdres,     OrkAdrGidEindAdres
    into         @OrkVerzendadres, @OrkAdrGid,
                 @OrkEindAdres,    @AdrGidEindBestOrderDeb
    from   tabOrderkop
    where  OrkGid = @OrkGid;

    case @OrkVerzendadres
      when 0 then
        //Verzendadres = correspondentieadres
        set @AdrGidVanVerzending = @AdrGidCorrOrderDeb;
        set @NawGidVanVerzending = @NawGidOrder;
      when 1 then
        //Verzendadres = vestigingsadres
        set @AdrGidVanVerzending = @AdrGidVestOrderDeb;
        set @NawGidVanVerzending = @NawGidOrder;
      when 2 then
        //Verzendadres = verzendadres
        set @AdrGidVanVerzending = @OrkAdrGid;
        set @NawGidVanVerzending = @NawGidOrder;
      when 3 then
        // Verzendadres = correspondentieadres factuurdebiteur
        set @AdrGidVanVerzending = @NawFactuurNawGidCorrespondentie;
        set @NawGidVanVerzending = @OrkFactuurNawGid;
      when 4 then
        // Verzendadres = vestigingsadres factuurdebiteur
        set @AdrGidVanVerzending = @NawFactuurNawGidVestiging;
        set @NawGidVanVerzending = @OrkFactuurNawGid;
      when 5 then
        // Verzendadres = verzendadres factuurdebiteur
        set @AdrGidVanVerzending = @OrkAdrGid;
        set @NawGidVanVerzending = @OrkFactuurNawGid;
    end case;

    // *** Opvragen van eindbestemmingsadres van de orderdebiteur ***
    case @OrkEindAdres
        when 0 then // Correspondentieadres orderdebiteur
          set @AdrGidEindBestOrderDeb = @AdrGidCorrOrderDeb
        when 1 then // Vestigingsadres orderdebiteur
          set @AdrGidEindBestOrderDeb = @AdrGidVestOrderDeb
        when 2 then // (opgegeven verzendadres) orderdebiteur
          set @AdrGidEindBestOrderDeb = @AdrGidEindBestOrderDeb; // Er verandert dus niks
        when 3  // Niet van toepassing
          then set @AdrGidEindBestOrderDeb = null;
    end case;

    // *** Adressen toevoegen ***
    // Correspondentieadres document (van orderdeb. of factuurdeb.!)
    if @GebruikCorrAdresVanFactuurDeb = 0 then
      call VulFactuurAdres( 0, null, @FrefGid, @OrkGid, @AdrGidCorrOrderDeb,     @NawGidOrder,         @LayoutSoort);
    else
      call VulFactuurAdres( 0, null, @FrefGid, @OrkGid, @NawFactuurNawGidCorrespondentie,      @OrkFactuurNawGid,       @LayoutSoort);
    end if;
//    // Correspondentieadres van de orderdebiteur invullen
//    call VulFactuurAdres(11, null,   @FrefGid, @OrkGid, @AdrGidCorrOrderDeb,     @NawGidOrder,         @LayoutSoort);
    // Verzendadres van de orderdebiteur invullen
    call VulFactuurAdres(12, null,   @FrefGid, @OrkGid, @AdrGidVanVerzending,    @NawGidVanVerzending, @LayoutSoort);
    // Eindbestemmingsadres van de orderdebiteur invullen
    call VulFactuurAdres(13, null,   @FrefGid, @OrkGid, @AdrGidEindBestOrderDeb, @NawGidVanVerzending, @LayoutSoort);
  end for;

  // *** Eigen bankrekening invullen ***
  // Eigenlijk moet het dit zijn:
  /*
  update tabFactuurkop
  set    fkEigenBankRekNummer = nawrekBankRekening,
         fkEigenBankRekNaam   = nawrekNaamRekHouder,
         fkEigenBankRekAdres  = nawRekAdresRekHouder,
         fkEigenBankRekPlaats = nawrekPlaatsRekHouder
  from   tabNawFile inner join tabNawRekening on NawRekNawGid = NawFilNawGid
  where  fkGid = @FkGid and NawFilFonId='B' and NawRekSoort like '%D%'; // Gebruik default bankrekening van ons bedrijf)
  */
  // Maar omdat we die gegevens NOG niet hebben, lezen we de vestigingsgegevens van het bedrijf uit en
  // gebruiken we de rekening van de OCR-regel van de vaste gegevens van de acceptgiro
  update tabFactuurkop
  set    fkEigenBankRekNummer = vgaEigenRek,
         fkEigenBankRekNaam   = AdrNaam1,
         fkEigenBankRekAdres  = AdrStraat + ' ' + AdrHuisnummer,
         fkEigenBankRekPlaats = AdrPlaats
  from   tabNawFile inner join tabNaw on NawGid = NawFilNawGid inner join tabAdres on (AdrGid = NawGidVestiging),
         tabVasteGegevensAcceptgiro
  where  fkGid = @FkGid and NawFilFonId='B';

  set @@ErrorTextProcedure = 'FactureringVulAdressenIn';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace function FactuurBedrag(in @Definitief numeric(15,2), in @Voorlopig numeric(15,2), in @VoorlopigMeenemen SmallInt)
returns numeric(15,2)
begin
  if @VoorlopigMeenemen <> 0 then
    return (@Definitief + @Voorlopig);
  else
    return (@Definitief);
  end if;

end;


create or replace procedure FactuurBerekenExtraBedragenZonderBtw( in @FactuurGid integer, in @fkIsInclBtw integer, in @BtwCode integer, in @BtwPerc numeric(6,2), out @TotaalBtwBasisExtraZonder numeric(15,2), out @TotaalInclBtwExtraZonder numeric(15,2))
begin
  declare @VorigeFrefOrderNummer nchar(10);
  declare @FrefOrderNummer nchar(10);
  declare @frefGid integer;
  declare @BtwBasisExtraZonder numeric(15,2);

  set @@ErrorTextProcedure = 'FacturerenBerekenGegevens( @FactuurGid='+string(@FactuurGid)+', @fkIsInclBtw='+string(@fkIsInclBtw)+', BtwCode'+string(@BtwCode)+', @BtwPerc='+string(@BtwPerc);
  //call TraceBegin(@@ErrorTextProcedure);

  set @TotaalBtwBasisExtraZonder  = 0;
  set @TotaalInclBtwExtraZonder   = 0;

  //De extra regels die niet zelf een btw% hebben (dus per referentie/order berekenen!)
  set @VorigeFrefOrderNummer = '';

  LoopReferentie:
  loop
    set @frefGid = null;
    select first frefGid, frefOrderNummer into @frefGid, @FrefOrderNummer from tabFactuurReferentie where frefFkGid = @FactuurGid and frefOrderNummer > @VorigeFrefOrderNummer order by frefOrderNummer;
    if @frefGid is null then
      leave LoopReferentie;
    end if;
    set @VorigeFrefOrderNummer = @FrefOrderNummer;




    set @BtwBasisExtraZonder = 0;
    select sum( ferPercentage/100 * ( isnull( if ferBerekenOverTarief = 1 then      //Bereken over bedrag zonder korting-aftrek
                                       (select sum(
                                                    (if FrEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                                     *
                                                     frBrutoPrijsPeenheid/frPrijsPer
                                                  ) from tabFactuurRegel where frFrefGid = @FrefGid and frSoortRegel = 1 and frBtwCode = @BtwCode
                                       )
                                    else if ferBerekenOverTarief = 2 then //Bereken over regeltotaal
                                       (select sum(frRegelTotaal) from tabFactuurRegel where frFrefGid = @FrefGid and frSoortRegel = 1 and frBtwCode = @BtwCode )
                                    else 0 endif endif,0) +
                            isnull( if ferBerekenOverArtikel = 1 then
                                      (select sum(
                                                  (if FrEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                                   *
                                                   frBrutoPrijsPeenheid/frPrijsPer
                                                  ) from tabFactuurRegel where frFrefGid = @FrefGid and frSoortRegel = 2 and frBtwCode = @BtwCode
                                      )
                                    else if ferBerekenOverArtikel = 2 then
                                      (select sum(frRegelTotaal) from tabFactuurRegel where frFrefGid = @FrefGid and frSoortRegel = 2 and frBtwCode = @BtwCode )
                                    else 0 endif endif,0) +

                            isnull( if ferBerekenOverEmballage = 1 then
                                       (select sum(
                                                   (if FrEenheidPrijsPer = 0 then (if frAantalBesteld=0 then 1 else frAantalBesteld endif) else (if frAantalBesteldVrrdEenh=0 then 1 else frAantalBesteldVrrdEenh endif) endif)
                                                    *
                                                    frBrutoPrijsPeenheid/frPrijsPer
                                                   ) from tabFactuurRegel where frFrefGid = @FrefGid and frSoortRegel = 3 and frBtwCode = @BtwCode
                                       )
                                    else if ferBerekenOverEmballage = 2 then
                                       (select sum(frRegelTotaal) from tabFactuurRegel where frFrefGid = @FrefGid and frSoortRegel = 3 and frBtwCode = @BtwCode )
                                   else 0 endif endif,0) -

                            if ferberekenOverKorting = 1 then
                              isnull((select sum( ferBtwBasis ) from tabFactuurExtraRegel binnen where binnen.ferFrefGid = @FrefGid and binnen.ferRegelNummer < buiten.ferRegelNummer and ferSoortRegel = 0),0)
                            else 0 endif +

                            if ferBerekenOverToeslag = 1 then
                              isnull((select sum( ferBtwBasis ) from tabFactuurExtraRegel binnen where binnen.ferFrefGid = @FrefGid and binnen.ferRegelNummer < buiten.ferRegelNummer and ferSoortRegel = 1),0)
                            else 0 endif
                          ) * if ferSoortRegel = 0 then -1 else 1 endif ) BtwBasis
    into   @BtwBasisExtraZonder
    from   tabFactuurExtraRegel buiten inner join tabFactuurReferentie on (frefGid = ferFrefGid)
    where  ferBtwCode is null and frefFkGid = @FactuurGid and ferPercentage is not null and frefgid = @frefgid
    group by ferRegelNummer
    order by ferRegelNummer;
    set @TotaalBtwBasisExtraZonder  = @TotaalBtwBasisExtraZonder + isnull(@BtwBasisExtraZonder,0);
  end loop LoopReferentie;

  if @fkIsInclBtw = 0 then
    set @TotaalInclBtwExtraZonder = @TotaalBtwBasisExtraZonder * (100+@BtwPerc)/100;
  else
    set @TotaalInclBtwExtraZonder = @TotaalBtwBasisExtraZonder;
    set @TotaalBtwBasisExtraZonder = @TotaalBtwBasisExtraZonder / (100+@BtwPerc)*100;
  end if;

  //call TraceEind('FactuurBerekenExtraBedragenZonderBtw');

end;


create or replace procedure FactuurBoekAfrondingsverschilBoeken( in @fbgid integer, in @IsProject smallint, in @nawgid integer, in @fkFactuurNummer nchar(40), in @oms nchar(40), in @HoogsteOpbrGrpGid integer, in @HoogsteOpbrGroepRksGid integer, in @HoogsteKstpCode nchar(8), in @HoogsteKstdCode nchar(8), in @HoogsteOpbrIsGoed smallint, in @Boekdatum date, in @DatumFactuurBoeking date, in @BoekGangGid integer, in @JpGid integer)
begin
  declare @TotaalJr   numeric(15,2);
  declare @TotaalHulp numeric(15,2);
  declare @JrGid      integer;
  declare @valnummer  integer;
  declare @vofIsAfrondingApart smallint;
  declare @vofBoekAfrondRksGid integer;

  set @@ErrorTextProcedure = 'FactuurBoekAfrondingsverschilBoeken > ';
  //call TraceBegin(@@ErrorTextProcedure + '@fbGid = ' + string(@fbgid) + ', @nawgid = ' + string(@nawgid) + ', @oms = ' + @oms + ', @HoogsteOpbrGrpGid = ' + string(@HoogsteOpbrGrpGid) + ', @HoogsteOpbrGroepRksGid = ' + string(@HoogsteOpbrGroepRksGid) + ', @HoogsteKstpCode = ' +string(@HoogsteKstpCode));

  set @TotaalJr = null;
  select sum( if IsCreditBoeking = 0 then JrBasisBedrag else -JrBasisBedrag endif )
  into @TotaalJr
  from tabJournaalRegel where JrJpGid = @JpGid;

  //Totaal van hulpregels
  set @TotaalHulp = null;
  select sum( if HulpRekIsCredit = 0 then HulpRekBasisBedrag else -HulpRekBasisBedrag endif )
  into @TotaalHulp
  from tabHulpRekening inner join tabJournaalRegel on (JrGid = HulprekJrGid) where JrJpGid = @JpGid;

  if isnull( @TotaalJr, 0 ) + isnull( @TotaalHulp, 0 ) <> 0 then
    set @TotaalJr = isnull( @TotaalJr, 0 ) + isnull( @TotaalHulp, 0 );

    select vofIsAfrondingApart, vofBoekAfrondRksGid into @vofIsAfrondingApart, @vofBoekAfrondRksGid from tabVasteGegevensOrdersFactureren;
    if (@vofIsAfrondingApart=1 and @vofBoekAfrondRksGid is not null) and (@IsProject = 0) then // RS Bug 30473 - bij projecten afrondingsverschil apart boeken

      insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                   IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum )
        values( @JpGid, ( select first vofBoekAfrondRksGid from tabVasteGegevensOrdersFactureren ), abs( @TotaalJr ),
                                   abs( @TotaalJr ), @oms,
                                   if @TotaalJr > 0 then 1 else 0 endif, 0, @@BasisValutaNummer, @Boekdatum);
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid )
      values( @BoekGangGid, 9 , null, @vofBoekAfrondRksGid, null, null, @TotaalJr, @FbGid );

    else
      //Niet apart boeken, dus boeken op de opbrengstrekening met hoogste absolute bedrag
      //Maar wel ALTIJD in de basisvaluta!!
      select first JrGid, jrValNummer into @JrGid, @valnummer from tabjournaalregel where JrJpGid = @JpGid and JrRksGid = @HoogsteOpbrGroepRksGid order by abs(jrBasisBedrag) desc;
      if @valnummer = @@BasisValutaNummer and @IsProject = 0 then
        //De opbrengstrekening is al in basisvaluta -> updaten!
        update tabJournaalRegel
        set    JrBasisBedrag  = JrBasisBedrag  + if IsCreditBoeking = 0 then - @TotaalJr else @TotaalJr endif,
               JrValutaBedrag = JrValutaBedrag + if IsCreditBoeking = 0 then - @TotaalJr else @TotaalJr endif
        where  JrGid = @JrGid;
      else
        if @IsProject = 1 then  // RS Bug 30473 - bij projecten afrondingsverschil apart boeken
          set @oms = _A('Afrondingsverschil');
        end if;
        //De opbrengstrekening is in andere valuta, dus extra regel toevoegen
        insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel, IsCreditBoeking, SoortBoeking, JrValNummer, jrReferentie, JrBoekdatum)
        values(@JpGid, @HoogsteOpbrGroepRksGid, abs(@TotaalJr), abs(@TotaalJr), @oms, if @TotaalJr<0 then 0 else 1 endif, 0, @@BasisValutaNummer, @fkFactuurNummer, @Boekdatum);
        set @JrGid = @@Identity;

        if @IsProject = 0 then
          insert into tmpJrGid(JrGid) select @JrGid;
        end if;
      end if;
      //Onthouden tbv. factuuroverzicht: Opbrengst
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGId, fooRksGid, fooKstpCode, fooKstdCode, fooBedrag, fooFbGid )
      values(@BoekGangGid, 9 , @HoogsteOpbrGrpGid, @HoogsteOpbrGroepRksGid, @HoogsteKstpCode, @HoogsteKstdCode, @TotaalJr, @FbGid );
    end if;
  end if;

  set @@ErrorTextProcedure = 'FactuurBoekAfrondingsverschilBoeken > ';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace function FactuurBoekMaakJpOms(in @LayoutSoort integer, in @fkGid integer, in @fkFactuurNummer nchar(40))
returns nchar(40)
begin
  declare @tempInt integer;
  declare @oms     nchar(40);

  //call TraceBegin('FactuurBoekMaakJpOms(@LayoutSoort='+string(@LayoutSoort)+', @fkGid='+string(@fkGid)+', @fkFactuurNummer='+@fkFactuurNummer+')');
  case @LayoutSoort
    when 50 then select vofBatchOmsWelke  into @tempInt from tabvasteGegevensOrdersFactureren;
    when 60 then select vofDirectOmsWelke into @tempInt from tabvasteGegevensOrdersFactureren;
  end case;

  case @tempInt
  when 0 then //OrderRef.
    select first frefOms into @Oms from tabFactuurKop inner join tabFactuurReferentie on (frefFkGid = FkGid) where fkGid = @fkGid order by frefOrderNummer;
  when 1 then //tekst 'Factuur'
    set @oms='Factuur';
  when 2 then //Debiteurnaam
    select faNaam1 into @Oms from tabFactuurAdres where FaFkGid = @fkGid;
  when 3 then //tekst 'Factuur' + nummer
    set @oms='Factuur ' + @fkFactuurNummer;
  when 4 then //tekst 'Factuur' + nummer + debiteurnaam
    select 'Factuur ' + @fkFactuurNummer + ' ' + faNaam1 into @Oms from tabFactuurAdres where FaFkGid = @fkGid;
  when 5 then //Anders
    case @LayoutSoort
      when 50 then select vofBatchOms into @Oms from tabvasteGegevensOrdersFactureren;
      when 60 then select vofDirectOms into @Oms from tabvasteGegevensOrdersFactureren;
    end case;
  end case;

  // CrLf in de omschrijving vervangen door een spatie ...
  set @oms = MultipleLinesToOneLine(@Oms);

  //call TraceEind('FactuurBoekMaakJpOms(@Oms='+@Oms+')');
  return (@oms);

end;


create or replace function FactuurCharToNumeric(in ch nchar(10))
returns numeric(10,0)
begin
  declare @hulp numeric(10,0);
  //call TraceBegin('FactuurCharToNumeric( ch='+ch+')');
  set @hulp=cast(ch as numeric(10,0));

  return(@hulp);
  //call TraceEind('FactuurCharToNumeric(return='+string(@hulp)+')');

  exception when others then
  begin
    //call Trace('FOUT bij converteren van'+ch+' naar numeric(10,0)');
    return(null);
  end;
//
end;


create or replace function FactuurNummerToCh(in @factuurnummer numeric(10,0), in @DocOrdUitvullen integer)
returns nchar(10)
begin
  declare @factuurnummerCh nchar(10);

  set @@ErrorTextProcedure = 'FactuurNummerToCh > @factuurnummer='+string(@factuurnummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if @DocOrdUitvullen = 0 then
    //Uitvullen met voorloopnullen
    set @factuurnummerCh = replicate( '0', 10-length( string( @factuurnummer ) ) ) + string( @factuurnummer );
  else
    //Uitvullen met voorloopspaties
    set @factuurnummerCh=string(@factuurnummer);
  end if;

  set @@ErrorTextProcedure = 'FactuurNummerToCh > ' + @factuurnummerCh;
  //call TraceEind(@@ErrorTextProcedure);
  return(@factuurnummerCh);


end;


create or replace function FactuurZitInAutomBoekBetalingsOpdracht(in @RksGid integer, in @FactuurNummer nchar(40))
returns integer
begin
  declare @Bestaat integer;

  set @@ErrorTextProcedure = 'FactuurZitInAutomBoekBetalingsOpdracht';
  //call TraceBegin(@@ErrorTextProcedure);

  // ACW 2007-09-07 project Bedrag Onderweg: Controleer onafhankelijk van het feit of een betalingsopdracht automatisch wordt afgeboekt of niet...
  if exists(select 1
            from  tabBetalingregel
                  left outer join tabBetalingVerzameld on (BetRglIsVerzameld = 1 and BetVerzBetRglGid = BetRglGid)
            where BetRglRksGid = @RksGid
              and BetRglStatus = 1
              and (   (BetRglFactuurNummer = @FactuurNummer and BetRglFactuurNummer_Lengte = length(@FactuurNummer))
                   OR (BetVerzFactuurNummer = @FactuurNummer and BetVerzFactuurnummer_Lengte = length(@FactuurNummer)))
           ) then
    set @Bestaat = 1
  else
    set @Bestaat = 0
  end if;

  //call TraceEind (@@ErrorTextProcedure);
  return(@Bestaat);

end;


//------------- Test of faktuurnummer al voorkomt in Osp (in dit boekjaar)
create or replace procedure FaktuurNummerBestaatAl(in @JpGid integer, in @JrGid integer, in @RksGid integer, in @Faktuurnr nchar(40), out @Meldingnr smallint)
begin
  declare @BjGid integer;
  declare @AndereRekeningSoort smallint;
  declare @RekeningSoort smallint;
  declare @DagboekSoort smallint;

  set @@ErrorTextProcedure = 'FaktuurNummerBestaatAl > @JpGid='+string(@JpGid)+', @JrGid='+string(@JrGid)+', @RksGid='+string(@RksGid)+', @Faktuurnr='+@Faktuurnr;
  //call TraceBegin(@@ErrorTextProcedure);

  //Geen melding geven
  set @Meldingnr = 0;

  select DefaultSoort into @RekeningSoort from tabRekeningschema where RksGid = @RksGid;

  if @JpGid is null then
    set @BjGid = @@BjGid;
  else
    select JpBjGid into @BjGid from tabJournaalPost where JpGid = @JpGid;
  end if;

  //ACW Defect #41055/41065: Juist trimmen, zodat die weer kan worden gevonden in onderstaande queries
  set @Faktuurnr = Trim(@faktuurnr); //right(Repeat(' ',40)+Trim(@faktuurnr),40);

  //Test of factuurnummer al voorkomt bij deze debiteur/crediteur
  if exists(select 1 from tabJournaalRegel inner join tabOpenstaandePost on (OspGid = JrOspGid) where @BjGid=OspBjGid and @Faktuurnr=OspFactuurNummer and length(@Faktuurnr)=OspFactuurNummer_Lengte and @RksGid=OspRksGid and ((@JpGid is null) or (@JpGid<>JrJpGid))) then
    if @RekeningSoort=6 then
      set @Meldingnr=3;    //Factuurnummer komt al bij deze debiteur voor
    else
      set @Meldingnr=4    //Factuurnummer komt al bij deze crediteur voor
    end if;
  else
    //Test of factuurnummer al voorkomt bij een andere debiteur/crediteur
    if exists(select 1 from tabJournaalRegel inner join tabOpenstaandePost on (OspGid = JrOspGid) where @BjGid=OspBjGid and @Faktuurnr=OspFactuurNummer and length(@Faktuurnr)=OspFactuurNummer_Lengte and @RksGid<>OspRksGid and ((@JrGid is null) or (@JrGid<>JrGid))) then
      if @RekeningSoort = 6 then
        select min(DefaultSoort) into @AndereRekeningSoort from tabJournaalRegel inner join tabOpenstaandePost on (OspGid = JrOspGid) inner join tabrekeningschema on (rksGid=OspRksGid) where @BjGid=OspBjGid and @Faktuurnr=OspFactuurNummer and length(@Faktuurnr)=OspFactuurNummer_Lengte and @RksGid<>OspRksGid and ((@JrGid is null) or (@JrGid<>JrGid));
        if @AndereRekeningSoort=6 then
          set @Meldingnr = 1;    //Factuurnummer komt al bij een andere debiteur voor
        end if;
      else
        select max(DefaultSoort) into @AndereRekeningSoort from tabJournaalRegel inner join tabOpenstaandePost on (OspGid = JrOspGid) inner join tabrekeningschema on (rksGid=OspRksGid) where @BjGid=OspBjGid and @Faktuurnr=OspFactuurNummer and length(@Faktuurnr)=OspFactuurNummer_Lengte and @RksGid<>OspRksGid and ((@JrGid is null) or (@JrGid<>JrGid));
        if @AndereRekeningSoort=7 then
          set @Meldingnr = 2;    //Factuurnummer komt al bij een andere crediteur voor
        end if;
      end if;
    end if;
  end if;

  set @@ErrorTextProcedure = 'FaktuurNummerBestaatAl';
  //call TraceEind(@@ErrorTextProcedure);

end;


//VvE 14-08-2017: Functie die FonId vertaald naar NawSoort
create or replace function FonIdNaarNawSoort(@FonId nchar(3))
returns smallint
begin
  declare @NawSoort smallint;

  set @NawSoort = (case @FonId
                     when 'D' then 0 /*Debiteuren*/
                     when 'C' then 1 /*Crediteuren*/
                     when 'B' then 2 /*Bedrijfsgegevens*/
                     else 3          /*Relatiebestand*/
                   end);

  return @NawSoort;
end;

