//$Workfile: FunBudgetBepaalWelkeVergelijk.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='FunBudgetBepaalWelkeVergelijk') then
  drop function FunBudgetBepaalWelkeVergelijk;
end if;

create function FunBudgetBepaalWelkeVergelijk(in @VergelijkenMetVanVoorloop integer, in @VergelijkenMetVanRekening integer, in @VergelijkenMetVanKstpd integer, in @tmpDefaultBoekzijde integer)
returns integer
begin
  declare @resultaat integer;

  //call traceBegin('FunBudgetBepaalWelkeVergelijk( @VergelijkenMetVanVoorloop='+string(@VergelijkenMetVanVoorloop)+', @VergelijkenMetVanRekening='+string(@VergelijkenMetVanRekening)+', @VergelijkenMetVanKstpd='+string(@VergelijkenMetVanKstpd)+', @tmpDefaultBoekzijde='+string(@tmpDefaultBoekzijde)+')');

  set @resultaat =
    if @VergelijkenMetVanVoorloop = 4 then // Vergelijk met budget
      if @VergelijkenMetVanRekening is null then
        //Rks heeft geen budget -> gebruik die van de kostenplaats/drager
        if isnull(@VergelijkenMetVanKstpd,0) < 3 then
          isnull(@VergelijkenMetVanKstpd,0) // saldo, debet of credit
        else
          if @VergelijkenMetVanKstpd in (3,4) then
            if @tmpDefaultBoekzijde between 0 and 1 then // def.boekzijde debet of credit
              @tmpDefaultBoekzijde + 1
            else
              0 // geen voorkeur ---> saldo
            endif
          else
            @VergelijkenMetVanKstpd // debet of credit
          endif
        endif
      else
        // Rks heeft wel budget, die dus gebruiken
        if isnull(@VergelijkenMetVanRekening,0) < 3 then
          isnull(@VergelijkenMetVanRekening,0) // saldo, debet of credit
        else
          if @VergelijkenMetVanRekening in (3,4) then
            if @tmpDefaultBoekzijde between 0 and 1 then // def.boekzijde debet of credit
              @tmpDefaultBoekzijde + 1
            else
              0 // geen voorkeur ---> saldo
            endif
          else
            @VergelijkenMetVanRekening // debet of credit
          endif
        endif
      endif
    else
      if isnull(@VergelijkenMetVanVoorloop,0) < 3 then
        isnull(@VergelijkenMetVanVoorloop,0) // saldo, debet of credit
      else
        if @VergelijkenMetVanVoorloop in (3,4) then
          if @tmpDefaultBoekzijde between 0 and 1 then // def.boekzijde debet of credit
            @tmpDefaultBoekzijde + 1
          else
            0 // geen voorkeur ---> saldo
          endif
        else
          @VergelijkenMetVanVoorloop // debet of credit
        endif
      endif
    endif
  ;

  //call traceEind('FunBudgetBepaalWelkeVergelijk( result='+string(@resultaat)+')');
  return @resultaat;



end;


//$Workfile: FuncVervalDatumFactuurMetRksGid.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//--------- Functie bereken de vervaldatum van de factuur aan de hand van de betalingsconditie via een RksGid
if exists (select 1 from sys.sysProcedure where proc_name='FuncVervalDatumFactuurMetRksGid') then
  drop function FuncVervalDatumFactuurMetRksGid;
end if;

create function FuncVervalDatumFactuurMetRksGid (in @FactuurDatum date, in @RksGid integer)
returns date
begin
  declare @RetVervalDatum date;

  set @@ErrorTextProcedure = 'FuncVervalDatumFactuurMetRksGid > @FactuurDatum='+string(@FactuurDatum)+', @RksGid='+string(@RksGid);
  //call TraceBegin(@@ErrorTextProcedure);

  call VervalDatumFactuurMetRksGid( @FactuurDatum, @RksGid, @RetVervalDatum );

  set @@ErrorTextProcedure = 'FuncVervalDatumFactuurMetRksGid > @RetVervaldatum='+string(@RetVervaldatum);
  //call TraceEind(@@ErrorTextProcedure);
  Return(@RetVervalDatum);

end;


//--------- Maak de gebruiker aan in tabGebruiker en in de database
create or replace procedure GebruikerAanmaken(in @Id integer, in @Gebruiker nchar(40), in @Wachtwoord nchar(22))
begin

  set @@ErrorTextProcedure = 'GebruikerAanmaken >';
  //call TraceBegin(@@ErrorTextProcedure);

  execute immediate 'grant connect to "' || @Gebruiker ||'" identified by "' || @Wachtwoord || '"';
  execute immediate 'grant membership in group KINGSYSTEM to "' || @Gebruiker || '"';
  execute immediate 'grant dba, resource to "' || @Gebruiker || '"';

  if left(@Gebruiker,5)='KING_' then
    insert into tabGebruiker (GebruikerGid, NaamGebruiker) values (@Id, substr(@Gebruiker, 6)); //KING_ eraf
  end if;

  set @@ErrorTextProcedure = 'GebruikerAanmaken';
  //call TraceEind(@@ErrorTextProcedure);
end;

alter procedure GebruikerAanmaken set hidden;


//------- Alle gebruikers verwijderen behalve Gebruik en Systeem
create or replace procedure GebruikersAllemaalVerwijderen()
begin
  declare @Dummy nchar(20);

  set @@ErrorTextProcedure = 'GebruikersAllemaalVerwijderen';
  //call TraceBegin(@@ErrorTextProcedure);

  select min(GebruikerVerwijderen('KING_'+NaamGebruiker)) into @Dummy from tabGebruiker where NaamGebruiker not in ('Gebruik', 'Systeem');

  set @@ErrorTextProcedure = 'GebruikersAllemaalVerwijderen';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure GebruikerVerwijderen(in @Gebruiker nchar(40))
begin
  declare @dummy smallint;

  set @@ErrorTextProcedure = 'GebruikerVerwijderen > @Gebruiker='+@Gebruiker;
  //call TraceBegin(@@ErrorTextProcedure);

  // Inloggen voorkomen

  begin
    declare err_SQLE_INVALID_PARAMETER exception for sqlstate value '08004'; // SQLE_INVALID_PARAMETER
    execute immediate 'revoke connect from "' || @Gebruiker || '"';
  exception

    when err_SQLE_INVALID_PARAMETER then
      select 1 into @dummy; // Negeer deze melding; alsnog de gebruiker uit de tabel verwijderen

    when others then
      resignal;
  end;


  // Verwijder gebruikersgegevens uit de administratie

  begin
    declare err_SQLE_INVALID_FOREIGN_KEY exception for sqlstate value '23503'; // SQLE_INVALID_FOREIGN_KEY
    delete from tabGebruiker where NaamGebruiker=substr(@Gebruiker, 6);  //KING_ eraf

    set @@ErrorTextProcedure = 'GebruikerVerwijderen';
    //call TraceEind(@@ErrorTextProcedure);

    exception

      when err_SQLE_INVALID_FOREIGN_KEY then
        select 1 into @dummy; // Negeer deze melding, want dan is tabExport van deze gebruiker bij tabJobRegel gebruikt

      when others then

        resignal;
  end;
end;


create or replace function GeefArtikelVoorraadOpDatum(in @ArtGid integer, in @PeilDatum date)
returns numeric(15,3)
begin
  declare @Result numeric(15,3);

  select Sum(Voorraad) Vrd into @Result from (
      select     ArtGid,  sum(ArtLocVoorraad) Voorraad
      from       tabArtikel
      inner join tabArtikelLocatie on (ArtLocArtGid = ArtGid)
      where      ArtGid = @ArtGid
      group by   ArtGid
      union all
      select     VrdMutArtGid, sum(-1 * VrdMutLocAantal) Voorraad
      from       tabVoorraadMutatie
      inner join tabVoorraadMutatieLocatieSerie on (VrdMutLocVrdMutGid = VrdMutGid)
      where      VrdMutArtGid = @ArtGid and VrdMutdatum > @PeilDatum
      group by   VrdMutArtGid) VoorraadPeilDatum;

  return @Result;
end;


create or replace function GeefBtwCodeVerkoop(
  in @NawGid integer,
  in @ArtGid integer,
  in @ArtPartijGid integer default null,
  in @AfleverLndGid integer default null,
  in @VerzendLndGid integer default null) returns integer
begin
  declare @AfstandsVerkopen smallint;
  declare @ResultBtwCode    integer;
  declare @NawBtwCode       integer;
  declare @NawBtwPerc       numeric(15,3);
  declare @ArtSoort         smallint;
  declare @ArtBtwCode       integer;
  declare @ArtPartijBtwCode integer;
  declare @EigenLndGid      integer;
  declare @IsOpbrGrpGoederen smallint; // 0 - Diensten, 1 - Goederen

  declare @EigenLandEULid   smallint;
  declare @AfleverLandEULid smallint;
  declare @VerzendLandEULid smallint;

  //call TraceBegin('GeefBtwCodeVerkoop > @NawGid = ' + string(@NawGid) + ', @ArtGid = ' + string(@ArtGid)+ ', @ArtPartijGid = ' + string(@ArtPartijGid)+ ', @AfleverLndGid = ' + string(@AfleverLndGid)+ ', @VerzendLndGid = ' + string(@VerzendLndGid));

  select cast(Contents as smallint) into @AfstandsVerkopen from tabRegistry where RegKey = 'AFSTANDSVERKOPEN';
  select BtwCode, BtwPercentage into @NawBtwCode, @NawBtwPerc from tabNawFile inner join tabBtw on BtwCode = NawFilBtwCode where NawFilNawGid = @NawGid;
  select ArtSoort, ArtBtwCode, IsNull(IsOpbrGrpGoederen, (if ArtSoort = 2 then 1 else 0 endif)) into @ArtSoort, @ArtBtwCode, @IsOpbrGrpGoederen from tabArtikel left outer join tabOpbrengstGroep on ArtOpbrGrpGid = OpbrGrpGid where ArtGid = @ArtGid;
  select ArtPartijVerkoopBTWCode into @ArtPartijBtwCode from tabArtikelPartij where ArtPartijGid = @ArtPartijGid;
  select LndGid, LndIsEGLid into @EigenLndGid, @EigenLandEuLid from tabLand inner join tabVasteGegevens on LndGid = DefaultLndGid where VastId = 1;
  select LndIsEGLid into @VerzendLandEULid from tabLand where LndGid = @VerzendLndGid;

  // Indien tarief en land van verzending niet meegegeven, eigen land gebruiken
  if @VerzendLndGid is null then
    //call Trace('GeefBtwCodeVerkoop > Verzendland NULL, Verzendland = Eigen land');
    set @VerzendLndGid = @EigenLndGid;
  else
    if (@AfstandsVerkopen = 1) and (not exists(select 1 from tabLand where LndGid = @VerzendLndGid)) then
       call Raise(20376); // (20376) Verzend-land is verplicht bij gebruik van afstandsverkopen!
    end if;
  end if;

  if @AfleverLndGid is not null then
    select LndIsEGLid into @AfleverLandEULid from tabLand where LndGid = @AfleverLndGid;
  else // Indien geen AfleverLndGid, dan vestigingsadres NAW
    select LndGid, LndIsEGLid into @AfleverLndGid, @AfleverLandEULid from tabNaw inner join tabAdres on NawGidVestiging = AdrGid inner join tabLand on AdrLndGid = LndGid where NawGid = @NawGid;
  end if;

  if (@AfstandsVerkopen = 0) or (@EigenLandEuLid = 0) then
    // GEEN afstandsverkopen, of we vallen zelf niet binnen EU
    if (@NawBtwCode is not null) and (@NawBtwPerc = 0.0) then
      //call Trace('GeefBtwCodeVerkoop > GEEN Afstandsverkopen of zelf GEEN EU-lid, NawBtw 0');
      set @ResultBtwCode = @NawBtwCode;
    else
      //call Trace('GeefBtwCodeVerkoop > GEEN Afstandsverkopen of zelf GEEN EU-lid, ArtBtw');
      set @ResultBtwCode = IsNull(@ArtPartijBtwCode, @ArtBtwCode);
    end if;
  else
    // WEL afstandsverkopen
    if (@NawBtwCode is not null) and (@NawBtwPerc = 0.0) then // Buitenlandse zakelijke debiteur
      //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, NawBtw 0');
      set @ResultBtwCode = @NawBtwCode;
    elseif (@NawBtwCode is not null) and (@NawBtwPerc <> 0.0) and (IsNull((select NawBtwNummer from tabNaw where NawGid = @NawGid), '') <> '') then // Binnenlandse zakelijke debiteur
      //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, NawBtw <> 0, BtwId, Binnenlandse zakelijke debiteur');
      set @ResultBtwCode = IsNull(@ArtPartijBtwCode, @ArtBtwCode);
    elseif @AfleverLndGid = @EigenLndGid then // vanuit ander land naar eigen land
      //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, import naar eigen land, ArtBtw');
      set @ResultBtwCode = IsNull(@ArtPartijBtwCode, @ArtBtwCode);
    else
      if @VerzendLndGid = @AfleverLndGid then
        if @AfleverLndGid = @EigenLndGid then // alle 3 hetzelfde
          //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, 3 x zelfde land, ArtBtw');
          set @ResultBtwCode = IsNull(@ArtPartijBtwCode, @ArtBtwCode);
        else
          if (@EigenLandEULid + @AfleverLandEULid + @VerzendLandEULid) = 3 then // Alle 3 EU-lid
            //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, alle 3 EU, Levering vanuit Land van aangifte');
            // BTW-code o.b.v. Levering vanuit 'Land van aangifte'
            set @ResultBtwCode = IsNull((select AbaBtwCodeVanuitLandVanAangifte from tabArtikelBTWAfstandsVerkopen where AbaArtGid = @ArtGid and AbaLndGid = @AfleverLndGid),
                                        (select LndBTWBtwCodeLeveringVanuitLandVanAangifte from tabLandBtw where LndBtwLndGid = @AfleverLndGid and LndBTWPrestatieSoort = @IsOpbrGrpGoederen));
          else
            //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, NIET alle 3 EU, ArtBtw');
            set @ResultBtwCode = IsNull(@ArtPartijBtwCode, @ArtBtwCode);
          end if;
        end if;
      elseif (@VerzendLndGid <> @AfleverLndGid) and (@AfleverLandEuLid = 1) then
        if @VerzendLndGid = @EigenLndGid then
          //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, Levering vanuit Eigen land (MSID)');
          //BTW-code o.b.v. Levering vanuit 'Eigen land (MSID)'
          set @ResultBtwCode = IsNull((select AbaBtwCodeVanuitEigenLand from tabArtikelBTWAfstandsVerkopen where AbaArtGid = @ArtGid and AbaLndGid = @AfleverLndGid),
                                      (select LndBTWBtwCodeLeveringVanuitEigenLand from tabLandBtw where LndBtwLndGid = @AfleverLndGid and LndBTWPrestatieSoort = @IsOpbrGrpGoederen));
        else
          if @VerzendLandEULid = 1 then
            //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, Levering vanuit Ander EU-land (MSEST)');
            //BTW-code o.b.v. Levering vanuit  'Ander EU-land (MSEST)'
            set @ResultBtwCode = IsNull((select AbaBtwCodeVanuitAnderEULand
                                         from tabArtikelBTWAfstandsVerkopen
                                         where AbaArtGid = @ArtGid and AbaLndGid = @AfleverLndGid),
                                        (select LndBTWBtwCodeLeveringVanuitAnderEULand
                                        from tabLandBtw
                                        where LndBtwLndGid = @AfleverLndGid
                                          and LndBTWPrestatieSoort = @IsOpbrGrpGoederen));

            //Als er een btwcode is, kijk dan of er een BTWcode is met zelfde credentials en het levering vanuit land.
            //Zoniet, niets teruggeven
            if (@ResultBtwCode is not null) then
              set @ResultBtwCode = IsNull(( select first LeveringVanuitBTW.BTWCode into @LeveringVanuitBTWCode
                                            from tabBTW ResultBTW, tabBTW LeveringVanuitBTW
                                            where ResultBTW.BTWCode = @ResultBtwCode
                                              and LeveringVanuitBTW.BtwPercentage = ResultBTW.BtwPercentage
                                              and LeveringVanuitBTW.BtwSoort = ResultBTW.BtwSoort
                                              and LeveringVanuitBTW.BtwLndGid = ResultBTW.BtwLndGid
                                              and LeveringVanuitBTW.BtwPrestatieSoort = ResultBTW.BtwPrestatieSoort
                                              and LeveringVanuitBTW.BtwLeveringVanuit = 1 /* Ander EU land (MSEST) */
                                              and LeveringVanuitBTW.BtwLndGidVanuit = @VerzendLndGid),
                                          ( select first LeveringVanuitBTW.BTWCode into @LeveringVanuitBTWCode
                                            from tabBTW ResultBTW, tabBTW LeveringVanuitBTW
                                            where ResultBTW.BTWCode = @ResultBtwCode
                                              and LeveringVanuitBTW.BtwPercentage = ResultBTW.BtwPercentage
                                              and LeveringVanuitBTW.BtwSoort = ResultBTW.BtwSoort
                                              and LeveringVanuitBTW.BtwLndGid = ResultBTW.BtwLndGid
                                              and LeveringVanuitBTW.BtwPrestatieSoort = ResultBTW.BtwPrestatieSoort
                                              and LeveringVanuitBTW.BtwLeveringVanuit = 1 /* Ander EU land (MSEST) */
                                              and LeveringVanuitBTW.BtwLndGidVanuit is null));
//            begin
//              declare @LeveringVanuitBTWCode integer;
//
//              select LeveringVanuitBTW.BTWCode into @LeveringVanuitBTWCode
//              from tabBTW ResultBTW, tabBTW LeveringVanuitBTW
//              where ResultBTW.BTWCode = @ResultBtwCode
//                and LeveringVanuitBTW.BtwPercentage = ResultBTW.BtwPercentage
//                and LeveringVanuitBTW.BtwSoort = ResultBTW.BtwSoort
//                and LeveringVanuitBTW.BtwLndGid = ResultBTW.BtwLndGid
//                and LeveringVanuitBTW.BtwPrestatieSoort = ResultBTW.BtwPrestatieSoort
//                and LeveringVanuitBTW.BtwLeveringVanuit = 1 /* Ander EU land (MSEST) */
//                and LeveringVanuitBTW.BtwLndGidVanuit = @VerzendLndGid;
//
//              set @ResultBtwCode = @LeveringVanuitBTWCode;
//            end;
            end if;
          else
            //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, VerzendLand NIET EU, Btw NIET-EU-land');
            set @ResultBtwCode = IsNull((select AbaBtwCodeVanuitNietEULand from tabArtikelBTWAfstandsVerkopen where AbaArtGid = @ArtGid and AbaLndGid = @AfleverLndGid),
                                        (select LndBTWBtwCodeLeveringVanuitNietEULand from tabLandBtw where LndBtwLndGid = @AfleverLndGid and LndBTWPrestatieSoort = @IsOpbrGrpGoederen));
          end if;
        end if;
      else
        //call Trace('GeefBtwCodeVerkoop > WEL Afstandsverkopen, geen conditie voldoet, ArtBtw');
        // Geen vd voorwaarden voldoet, dan artikel BTW
        set @ResultBtwCode = IsNull(@ArtPartijBtwCode, @ArtBtwCode);
      end if;
    end if;
  end if;

  // Geen vd voorwaarden voldoet, dan artikel BTW
  if @ResultBtwCode is null then
    //call Trace('GeefBtwCodeVerkoop - Niets gevonden > ArtPartijBtwCode/ArtBtwCode');
    set @ResultBtwCode = IsNull(@ArtPartijBtwCode, @ArtBtwCode);
  end if;

  //call TraceEind('GeefBtwCodeVerkoop > @AfstandsVerkopen='+string(@AfstandsVerkopen) + ' @ResultBtwCode='+string(@ResultBtwCode));

  return @ResultBtwCode;
end;


create or replace function GeefDebiteurIsKredietRuimteOverschreden(in @NawGid integer) returns smallint
begin
  declare @Kredietlimiet numeric(15,2);
  declare @KredietRuimteDefinitief numeric(15,2);
  declare @KredietRuimteVoorlopig numeric(15,2);

  call DebiteurKredietRuimte(@NawGid, null /*orkgid*/, @Kredietlimiet, @KredietRuimteDefinitief, @KredietRuimteVoorlopig);

  //call Trace('DebiteurKredietRuimteIsOverschreden - @NawGid='+string(@NawGid)+'; @Kredietlimiet='+string(@Kredietlimiet) + '; @KredietRuimteDefinitief='+string(@KredietRuimteDefinitief)+'; @KredietRuimteVoorlopig='+string(@KredietRuimteVoorlopig));

  if (@Kredietlimiet - @KredietRuimteDefinitief - @KredietRuimteVoorlopig) < 0 then
    return 1;
  else
    return 0;
  end if;
end;


