          set @BMCode = substring(@BMCode, 1, @Karakterpositie - 1) + char(substring(@Karakters, @KarakterNr * 4 + 2, 3)) + substring(@BMCode, @Karakterpositie + 1);
          //Als hoogste karakter was gevonden, dan ook het karakter ervoor verhogen (Z is dan namelijk A geworden etc.)
          if @Karakter in (',057,'/*9*/, ',122,'/*z*/, ',090,'/*Z*/) then
            // Wieletje is weer rond, dus karakter ervoor ook verhogen!
            set @KarakterPositie = @KarakterPositie - 1;
          else
            //Anders zijn we gelijk klaar
            leave lblKarakter
          end if;
        else
          // Geen ophoogbare karakter, dus doorgaan!
          set @KarakterPositie = @KarakterPositie - 1;
        end if;
        if @KarakterPositie = 0 then
          leave lblKarakter;
        end if;
      end loop lblKarakter;
      //Controleer of we een nieuw hebben en of die al bestaat
      if @KarakterPositie = 0 then
        // Er valt niets meer te verhogen, DUS verlaten van de routine!!
        leave lblOphogen;
      else
        if not exists(select first 1 from tabBedrijfsmiddel where BMCode = @Prefix + @BMCode) then
          // We hebben er 1 gevonden die nog niet bestaat, dus routine verlaten! (met @KarakterPositie<>0)
          leave lblOphogen;
        end if;
