// ---------------------------------------------------------------------------------------

create or replace function GetRekeningnummerFromIBAN(in @IBAN nchar(40))
returns nchar(40)
begin
  declare @Result nchar(40);

  set @@ErrorTextProcedure = 'GetRekeningnummerFromIBAN > IBAN = ' + @IBAN;
  //call TraceBegin(@@ErrorTextProcedure);

  //ACW 23-08-2012 bug #36112: Een rekeningnummer kan alleen eruit worden gehaald als het een Nederlandse IBAN is!
  if IsValidIBAN(@IBAN) = 1 and substr(@IBAN, 1, 2) = 'NL' then
    select substr(@IBAN, 9, 10) into @Result;
    //ACW 13-05-2013 defect #38259: Geen ltrimchar meer, maar rechtstreeks uitvoeren
    select right( @Result, length(@Result) + 1-PATINDEX( '%[^0]%', @Result+'!') ) into @Result;
    //select LTrimChar(@Result, '0') into @Result;
  else
    set @Result = '';
  end if;


  set @@ErrorTextProcedure = 'GetRekeningnummerFromIBAN > Result = ' + @Result;
  //call TraceEind(@@ErrorTextProcedure);
  return (@Result);
end;


