//Vve 01-12-2004: Wordt gebruikt in \k5\comp\tracer\databasetracer
//                Hulpschermpje voor ontwikkeling om de call tracesjes te volgen.
create or replace procedure GetServerMessages(in @StartNummer integer)
begin
  declare @row int;
  declare @maxrow int;
  declare @msg nchar(255);
  declare local temporary table tmpServerMessages
     ( C_Row int NOT NULL, C_Message nchar(255) NULL )
  in SYSTEM ON COMMIT PRESERVE ROWS;

  set @row = @StartNummer;
  set @maxrow = property( 'maxmessage' );

  lbl: loop
    if( @row >= @maxrow ) then
      leave lbl;
    end if;

    set @msg = property( 'Message', @row );
    if (@msg is not null) and (@msg <> '') then
      insert into tmpServerMessages values (@row, @msg);
    end if;

    set @row = @row + 1;
  end loop lbl;

  select C_Row, C_Message from tmpServerMessages;


end;


// *****************************************************************************************************
// Procnaam       : HerbouwProjectBoomPad
// Werking        : Verwijder alle projectboompad records en bouw het pad opnieuw op
// Reden bouw     : Initieel gebouwd omdat er twee foreign keys zijn toegevoegd aan de tabel tabProjectBoomPad.
//                  Omdat zonder foreign keys niet met 100% zekerheid gesteld kan worden dat de data uit
//                  tabProjectBoomPad bij klanten integer is, wordt bij de update naar Andorra bij alle projectklanten
//                  het projectboompad eenmalig opnieuw opgebouwd.
// Gebouwd door/op: TG 27-08-2007
// *****************************************************************************************************
if exists (select 1 from sys.sysProcedure where proc_name='HerbouwProjectBoomPad') then
  drop procedure HerbouwProjectBoomPad;
end if;

create procedure HerbouwProjectBoomPad()
begin
  set @@ErrorTextProcedure = 'HerbouwProjectBoomPad';
  //call TraceBegin(@@ErrorTextProcedure);

  //alle bestaande records verwijderen
  delete from tabProjectBoomPad;

  //op basis van tabProjectBoom het pad opnieuw vastleggen voor alle bestaande projecten
  for @Cursor AS CURSOR_HerbouwProjectBoomPad CURSOR FOR
    select
      PbGid         @PbGid,
      PbParentPbGid @PbParentPbGid
    from
      tabProjectBoom
    where
      PbGid <> 1
    order by
      PbLevel, PbVolgnr
  for read only
  do
    insert into tabProjectBoomPad(PbpPbGid, PbpParentPbGid)
       (select @PbGid, @PbParentPbGid
        union
        select @PbGid, PbpParentPbGid
        from   tabProjectBoomPad
        where  PbpPbGid = @PbParentPbGid);
  end for;

  set @@ErrorTextProcedure = 'HerbouwProjectBoomPad';
  //call TraceBegin(@@ErrorTextProcedure);


end;


//------- Herstellen van Journaal door van definitieve jp een voorlopige boekingsgang te maken en oude weg te gooien
create or replace procedure HerstelJournaal(in @BjGid integer, in @DefinitiefMaken smallint)
begin
  declare @IsolationLevel             smallint;
  declare @JpGid                      integer;
  declare @VorigJpGid                 integer;
  declare @RegelNummer                integer;
  declare @VorigRegelNummer           integer;

  declare @MaxRegelnummer             integer;
  declare @RegelNummerJP              integer;
  declare @NieuwJrGid                 integer;
  declare @IsVolledigAangesloten      smallint;
  declare @VolgendBoekjaarAangesloten smallint;

  declare local temporary table tmpJpGidjes (tmpJpGidOud integer, tmpJpGidNieuw integer) on commit preserve rows;

  set @@ErrorTextProcedure = 'HerstelJournaal > @BjGid='+string(@BjGid);
  //call traceBegin(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  // 20137 : Er zijn nog voorlopige boekingsgangen aanwezig
  if exists(select 1 from tabBoekingsgang where BoekGangBjGid = @BjGid and IsBoekGangDefinitief = 0) then
    call Raise(20137);
  end if;

  //TG 19-09-2006: bepalen of huidige boekjaar al is afgesloten naar een volgend boekjaar. (bug #4266)
  if exists(select 1 from tabBoekjaar where BjGid = @BjGid and BjAfsluitNaarBjGid is not null) then
    set @VolgendBoekjaarAangesloten = 1;
  else
    set @VolgendBoekjaarAangesloten = 0;
  end if;

  if (@VolgendBoekjaarAangesloten = 1) then
    //TG 19-09-2006: Regelnummer van JR bepalen dat opgeslagen is bij afsluiten boekjaar, en maximum regelnummer van dat boekjaar bepalen (bug #4266)
    select IsNull(RegelNummer, 0)      into @RegelNummerJP  from tabJournaalRegel where JrGid   = (select bjAfsluitJrGid from tabBoekjaar where BjGid=@BjGid);
    select IsNull(max(RegelNummer), 0) into @MaxRegelnummer from tabJournaalRegel where JrBjGid = @BjGid;

    //indien de regelnummers gelijk, dan is het vorige boekjaar volledig aangesloten.
    if (@RegelNummerJP = @MaxRegelnummer) then
      set @IsVolledigAangesloten = 1;
    else
      set @IsVolledigAangesloten = 0;
    end if;
    //call trace('@IsVolledigAangesloten='+string(@IsVolledigAangesloten)+', @RegelNummerJP='+string(@RegelNummerJP)+', @MaxRegelnummer'+string(@MaxRegelnummer));
  end if;

  //call trace('LET OP (1): Triggers gaan tijdelijk uit');
  set temporary option fire_triggers = 'off';

  //call trace('Bedrag in openstaandeposten op 0 zetten');
  update tabOpenstaandePost set OspFactuurBedragDefinitief = 0, OspBetaaldBedragDefinitief = 0, OspBtwBedragDefinitief = 0,
                                OspFactuurBedragVoorlopig  = 0, OspBetaaldBedragVoorlopig  = 0, OspBtwBedragVoorlopig  = 0,
                                OspKredietBeperkingsBedrag = 0, OspBedragOnderwegInValuta = 0
  where OspBjGid = @BjGid;

  delete tabRekeningSaldo where RekSaldoBjGid = @BjGid;

  //call trace('LET OP (1): Triggers gaan tijdelijk aan');
  set temporary option fire_triggers = 'on';

  // ACW 27-05-2004: Via herwaardering worden de andere koersen per rekening gecumuleerd
  //                 (in plaats van heel veel koerscorrecties omdat die per journaalpost zijn)
  set @@GeenKoersCorrectie = 1;

  //call trace('Boekingsgang aanmaken');
  insert into tabBoekingsGang(BoekGangBjGid, BoekgangBronId, BoekGangInGebruik, IsBoekGangDefinitief)
                       values(@BjGid, 6, 1, 0);

  set @VorigRegelNummer = 0;
  LoopJournaalPost:
  loop
    set @JpGid = null;
    select   first JpGid, RegelNummer into @JpGid, @RegelNummer
    from     tabJournaalpost inner join tabJournaalRegel on (JrJpGid = JpGid)
    where    JpBjGid = @BjGid and JpBoekGangGid <> @@BoekGangGid and SoortBoeking = 0 and RegelNummer > @VorigRegelNummer
    order by Regelnummer;

    if @JpGid is null then
      leave LoopJournaalPost
    end if;
    set @VorigJpGid = @JpGid;

    //call trace('Journaalpost toevoegen');
    insert into tabJournaalpost(JpBoekGangGid, JpBjGID, JpPerNr, JpIsInGebruik, JpDgbGID,
                                BoekstukNummer, OmsJournaalPost, BoekDatum, JpAlInBeginbalans)
    select @@BoekGangGid, @BjGid, JpPerNr, 1, JpDgbGid, BoekstukNummer, OmsJournaalPost, BoekDatum, JpAlInBeginbalans
    from   tabJournaalPost
    where  JpGid = @JpGid;

    //oude en nieuwe gidje opslaan
    insert into tmpJpGidjes (tmpJpGidOud, tmpJpGidNieuw) values (@JpGid, @@JpGid);

    LoopJournaalRegel:
    loop
      set @VorigRegelNummer = @RegelNummer;

      //call trace('Journaalregel toevoegen');
      insert into tabJournaalRegel(JrJpGid, JrRksGid, JrOspGid, StukVolgnr, OmsJournaalRegel, JrReferentie,
                                   SoortBoeking, IsCreditBoeking, Aantal, JrBasisBedrag, JrValutaBedrag,
                                   JrValNummer, JrFactuurDatum, JrVervalDatum, JrBetalingsKenmerk, JrIsViaIncasso, JrBoekdatum,
                                   JrTimeStamp, JrDarGid, JrBetRglGid, JrBetVerzGID, JrIncRglGid, JrIrvGid, JrPbrGid)
      select @@JpGid, JrRksGid, JrOspGid, StukVolgnr, OmsJournaalRegel, JrReferentie,
             SoortBoeking, IsCreditBoeking, Aantal,
             if JrValNummer = @@BasisValutaNummer then JrValutaBedrag else ValutaOmrekenen(JrValNummer, JrValutaBedrag, @@BasisValutaNummer, JrBjGid, JrPerNr, 2) endif,
             JrValutaBedrag, JrValNummer, JrFactuurDatum, JrVervalDatum, JrBetalingsKenmerk, JrIsViaIncasso, JrBoekdatum, JrTimeStamp, JrDarGid, JrBetRglGid, JrBetVerzGID, JrIncRglGid, JrIrvGid, JrPbrGid
      from   tabJournaalRegel
      where  JrJpGid = @JpGid and RegelNummer = @RegelNummer;

      //call trace('Hulprekening toevoegen');
      insert into tabHulpRekening(HulpRekJrGid, HulpRekSoort, HulpRekRksGid, HulpRekValNummer, HulpRekIsCredit,
                                  HulpRekBasisBedrag, HulpRekValutaBedrag,
                                  HulpRekBedragInJrValnummer, HulpRekBtwCode, HulpRekKredBepDatum)
      select @@JrGid, HulpRekSoort, HulpRekRksGid, HulpRekValNummer, HulpRekIsCredit,
             if HulpRekValNummer = @@BasisValutaNummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, @@BasisValutaNummer, JrBjGid, JrPerNr, 2) endif,
             HulpRekValutaBedrag,
             if HulpRekValNummer = JrValNummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValNummer, JrBjGid, JrPerNr, 2) endif,
             HulpRekBtwCode, HulpRekKredBepDatum
      from   tabJournaalRegel inner join tabHulpRekening on (HulpRekJrGid = JrGid)
      where  JrJpGid = @JpGid and RegelNummer = @RegelNummer;

      set @RegelNummer = null;
      select   first JrJpGid, RegelNummer into @JpGid, @RegelNummer
      from     tabJournaalRegel
      where    JrBjGid = @BjGid and SoortBoeking = 0 and RegelNummer > @VorigRegelNummer
      order by Regelnummer;

      if (@RegelNummer is null) or (@JpGid <> @VorigJpGid) then
        leave LoopJournaalRegel
      end if;

    end loop LoopJournaalRegel;

    //call trace('Journaalpost uit gebuik nemen');
    update tabJournaalpost set JpIsInGebruik = 0 where JpGid = @@JpGid;

  end loop LoopJournaalPost;

  //call trace('LET OP (2): Triggers gaan tijdelijk uit');
  set temporary option fire_triggers = 'off';

  delete tabLeverOverzichtOpbrengst      from tabBoekingsgang                                                  where BoekgangBjGid = @BjGid and   BoekGangGid <> @@BoekGangGid and LooBoekGangGid = BoekGangGid;
  delete tabLeverOverzichtTussenrekening from tabBoekingsgang                                                  where BoekgangBjGid = @BjGid and   BoekGangGid <> @@BoekGangGid and LotBoekGangGid = BoekGangGid;
  delete tabHulpRekening                 from tabJournaalPost inner join tabJournaalRegel on (JrJpGid = JpGid) where JpBjGid = @BjGid       and JpBoekGangGid <> @@BoekGangGid and HulpRekJrGid = JrGid;
  delete tabJournaalRegel                from tabJournaalPost                                                  where JpBjGid = @BjGid       and JpBoekGangGid <> @@BoekGangGid and JrJpGid      = JpGid;
  update tabJournaalPost    set OrigineelJpID=null                                                                       where JpBjGid = @BjGid       and JpBoekGangGid <> @@BoekGangGid;
  //TG 20-09-2006: velden niet updaten met NULL, maar vullen met nieuwe gidje obv temp kruistabel.
  update tabVoorraadmutatie         set VrdMutJpGid  = (select tmpJpGidNieuw from tmpJpGidjes where tmpJpGidOud = VrdMutJpGid) where exists(select 1 from tmpJpGidjes where tmpJpGidOud=VrdMutJpGid);
  //TG 20-09-2006: deze regel is volgens mij overbodig. Hij staat hierboven ook, de triggers staan uit
  //               (dus daar worden ook geen nieuwe regels aangemaakt) en een update statement in andere
  //               tabellen levert ook geen nieuwe regels op!
  //delete tabJournaalRegel from tabJournaalPost where JpBjGid = @BjGid and JpBoekGangGid <> @@BoekGangGid and JrJpGid      = JpGid;
  update tabFactuurKop              set FkJpGid      = (select tmpJpGidNieuw from tmpJpGidjes where tmpJpGidOud = FkJpGid) where exists(select 1 from tmpJpGidjes where tmpJpGidOud=FkJpGid);
  //VvE 25-1-2006 #19918: FK van tabProjectWinstneming ook op null zetten.
  //update tabProjectWinstneming set PwnJpGid  =null from tabJournaalPost                           where JpBjGid = @BjGid       and JpBoekGangGid <> @@BoekGangGid and PwnJpGid     = JpGid;
  update tabProjectWinstneming      set PwnJpGid  = (select tmpJpGidNieuw from tmpJpGidjes where tmpJpGidOud = PwnJpGid) where exists(select 1 from tmpJpGidjes where tmpJpGidOud=PwnJpGid);
  //TG 20-09-2006: bug #22641; ook de prijswijzigingshistorie bijwerken
  update tabprijswijzigingshistorie set pwhJpGid  = (select tmpJpGidNieuw from tmpJpGidjes where tmpJpGidOud = pwhJpGid) where exists(select 1 from tmpJpGidjes where tmpJpGidOud=pwhJpGid);

  //MR 28-mei-2008 bug #28395: Ook in deze tabel het nieuwe gidje hier zetten.
  update tabActivaMutatieHistorie set ActmhJpGID = (select tmpJpGidNieuw from tmpJpGidjes where tmpJpGidOud = ActmhJpGID) where exists(select 1 from tmpJpGidjes where tmpJpGidOud=ActmhJpGID);

  //MR 22-mar-2013 Autokosten: Ook in deze tabel het nieuwe gidje hier zetten.
  update tabVoertuigKosten set VrtKstJpGid = (select tmpJpGidNieuw from tmpJpGidjes where tmpJpGidOud = VrtKstJpGid) where exists(select 1 from tmpJpGidjes where tmpJpGidOud=VrtKstJpGid);

  delete tabJournaalPost where JpBjGid = @BjGid       and JpBoekGangGid <> @@BoekGangGid;
  delete tabBoekingsgang where BoekgangBjGid = @BjGid and   BoekGangGid <> @@BoekGangGid;

  //call trace('LET OP (2): Triggers weer aan');
  set temporary option fire_triggers = 'on';

  //if @DefinitiefMaken <> 0 then
  //  update tabBoekingsgang set BoekGangInGebruik = 0, IsBoekGangDefinitief = 1 where BoekGangGid = @@BoekGangGid;
  //else
    update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangGid = @@BoekGangGid;
  //end if;

  if @DefinitiefMaken <> 0 then
    call BoekingsGangVerwerken(@@BoekGangGid, null);
  end if;

  // ACW 27-05-2004: Weer wel koerscorrecties aanmaken
  set @@GeenKoersCorrectie = 0;

  call TijdelijkeKoersen(@BjGid, null, 0);
  call ValutaHerberekenen(@BjGid, 1, null);


  //TG 19-09-2006: alleen indien het huidige boekjaar al is afgesloten naar een volgend boekjaar het AfsluitJrGid invullen (bug #4266)
  if (@VolgendBoekjaarAangesloten = 1) then
    //TG 19-09-2006: Indien volledig aangesloten, dan slaan we JrGid van het hoogste regelnummer op in het boekjaar.
    if @IsVolledigAangesloten = 1 then
      select JrGid into @NieuwJrGid
      from   tabJournaalRegel
      where  JrBjGid = @BjGid and RegelNummer = (select Max(RegelNummer) from tabjournaalregel where JrBjGid = @BjGid);

      update tabBoekjaar
      set    BjAfsluitJrGid = @NieuwJrGid
      where  BjGid=@BjGid;
    else //zo niet, dan zetten we het JrGid op null
      update tabBoekjaar
      set    BjAfsluitJrGid = null
      where  BjGid=@BjGid;
    end if;
  end if;

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  call WriteLog(6, _A('Journaal hersteld'));

  set @@ErrorTextProcedure = 'HerstelJournaal';
  //call traceEind(@@ErrorTextProcedure);

end;


//------- Herstellen van tabRekeningsaldo en openstaande posten a.d.h.v. het journaal
create or replace procedure HerstelRekeningsaldo(in @BjGid integer)
begin
  declare @IsolationLevel smallint;
  declare @BoekGangGid    integer;
  declare @Dummy          nchar(40);

  declare local temporary table tmpOspFiat(
    tmpOspGid integer,
    tmpOspGefiatteerd             smallint,
    tmpOspFiatteringGewijzigdDoor nchar(40),
    tmpOspFiatteringGewijzigdOp   timestamp
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'HerstelRekeningsaldo > @BjGid='+string(@BjGid);
  //call TraceBegin(@@ErrorTextProcedure);

  update tabRegistry set Contents = 'Herstellen rekeningsaldo wordt uitgevoerd of is niet gelukt' where RegKey = 'SPECIAL_ADMIN';

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  //call Trace('Rekeningsaldi leeg maken');
  delete tabRekeningsaldo where (RekSaldoBjGid = @BjGid) or (@BjGid is null);

  //call Trace('Rekeningsaldi bijwerken');
  select min(RekeningSaldoUpdate (JrGid, JrBjGid, JrPerGid, JrPernr, JrValNummer, JrRksGid, IsBoekGangDefinitief, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, Aantal)) into @Dummy
  from   tabBoekingsgang inner join tabJournaalpost on (JpBoekgangGid = BoekgangGid) inner join tabJournaalregel on (JrJpGid = JpGid)
  where (BoekGangBjGid = @BjGid) or (@BjGid is null);

  //call trace('OSP: fiattering onthouden');
  insert into tmpOspFiat(tmpOspGid, tmpOspGefiatteerd, tmpOspFiatteringGewijzigdDoor, tmpOspFiatteringGewijzigdOp)
  select distinct OspGid, OspGefiatteerd, OspFiatteringGewijzigdDoor, OspFiatteringGewijzigdOp
  from   tabBoekingsgang inner join tabJournaalpost on (JpBoekgangGid = BoekgangGid) inner join tabjournaalregel on (jrJpGid = JpGid) inner join tabOpenstaandePost on (OspGid = JrOspGid)
  where (BoekGangBjGid = @BjGid) or (@BjGid is null);

  //call Trace('OSP: leeg maken');
  update tabOpenstaandePost set OspFactuurBedragVoorlopig = 0, OspFactuurBedragDefinitief = 0,
                                OspBetaaldBedragVoorlopig = 0, OspBetaaldBedragDefinitief = 0
  where (OspBjGid = @BjGid) or (@BjGid is null);

  //call Trace('OSP: bijwerken');
  select min(OpenstaandePostenBijwerken(0, JpGid, IsBoekGangDefinitief)) into @Dummy
  from   tabBoekingsgang inner join tabJournaalpost on (JpBoekgangGid = BoekgangGid)
  where (BoekGangBjGid = @BjGid) or (@BjGid is null);

  //call Trace('OSP: fiattering resetten');
  set temporary option fire_triggers = 'off';
  update tabOpenstaandePost
  set    OspGefiatteerd             = tmpOspGefiatteerd,
         OspFiatteringGewijzigdDoor = tmpOspFiatteringGewijzigdDoor,
         OspFiatteringGewijzigdOp   = tmpOspFiatteringGewijzigdOp
  from tmpOspFiat
  where OspGid = tmpOspGid;
  set temporary option fire_triggers = 'on';

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  update tabRegistry set Contents = '' where RegKey = 'SPECIAL_ADMIN';

  set @@ErrorTextProcedure = 'HerstelRekeningsaldo';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure HerstelRekeningsaldoVan1Rekening(
  in @BjGid integer,
  in @RksGid integer
)
begin
  // ACW: Wijziging: ipv reksaldo op 0 zetten wordt die nu verwijderd en opnieuw toegevoegd
  // Herstellen van tabRekeningsaldo en eventueel tabOpenstaandepPost, voor 1 rekening in 1 boekjaar
  // - tabRekeningsaldo wordt opnieuw opgebouwd voor 1 boekjaar voor 1 rekening;
  // - Er wordt rekening gehouden met de journaalposten die nog in gebruik zijn, oftewel die worden niet meegeteld;
  // - Als het om een debiteur/crediteur gaat dan worden de bedrag OspFactuurBedragVoorlopig, OspFactuurBedragDefinitief, OspBetaaldBedragVoorlopig & OspBetaaldBedragDefinitief bijgewerkt;
  // - Het bijwerken van tabOpenstaandePost gaat buiten de triggers om;
  // - Het vlaggetje OspIsVervallen wordt wel bijgewerkt;

  declare @IsolationLevel smallint;
  declare @RksSoort       smallint;

  set @@ErrorTextProcedure = 'HerstelRekeningsaldoVan1Rekening > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BjGid = ' + string(@BjGid) + ', @RksGid = ' + string(@RksGid));

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  //Eerst de betrefffende regels in tabRekeningsaldo verwijderen
  delete tabRekeningsaldo
  where  RekSaldoBjGid = @BjGid and RekSaldoRksGid = @RksGid;

  //Nu de betreffende regels in tabRekeninsaldi vullen a.d.h.v. tabJournaalregel
  insert into tabRekeningsaldo with auto name
  select
    JrBjGid     RekSaldoBjGid,
    JrPerGid    RekSaldoPerGid,
    JrPerNr     RekSaldoPerNr,
    @RksGid     RekSaldoRksGid,
    JrValNummer RekSaldoValNummer,
    sum(if RegelNummer is     null and IsCreditBoeking = 0 then JrBasisBedrag  else 0 endif) SaldoDebetBasisVoorlopig    ,
    sum(if RegelNummer is     null and IsCreditBoeking = 0 then JrValutaBedrag else 0 endif) SaldoDebetValutaVoorlopig   ,
    sum(if RegelNummer is     null and IsCreditBoeking = 0 then Aantal         else 0 endif) SaldoDebetAantalVoorlopig   ,
    sum(if RegelNummer is     null and IsCreditBoeking = 1 then JrBasisBedrag  else 0 endif) SaldoCreditBasisVoorlopig   ,
    sum(if RegelNummer is     null and IsCreditBoeking = 1 then JrValutaBedrag else 0 endif) SaldoCreditValutaVoorlopig  ,
    sum(if RegelNummer is     null and IsCreditBoeking = 1 then Aantal         else 0 endif) SaldoCreditAantalVoorlopig  ,
    sum(if RegelNummer is not null and IsCreditBoeking = 0 then JrBasisBedrag  else 0 endif) SaldoDebetBasisDefinitief   ,
    sum(if RegelNummer is not null and IsCreditBoeking = 0 then JrValutaBedrag else 0 endif) SaldoDebetValutaDefinitief  ,
    sum(if RegelNummer is not null and IsCreditBoeking = 0 then Aantal         else 0 endif) SaldoDebetAantalDefinitief  ,
    sum(if RegelNummer is not null and IsCreditBoeking = 1 then JrBasisBedrag  else 0 endif) SaldoCreditBasisDefinitief  ,
    sum(if RegelNummer is not null and IsCreditBoeking = 1 then JrValutaBedrag else 0 endif) SaldoCreditValutaDefinitief ,
    sum(if RegelNummer is not null and IsCreditBoeking = 1 then Aantal         else 0 endif) SaldoCreditAantalDefinitief
   from       tabJournaalRegel
   inner join tabJournaalPost on JpGid = JrJpGid
   where      JrBjGid       = @BjGid
          and JrRksGid      = @RksGid
          and JpIsInGebruik = 0
   group by   JrBjGid, JrPerGid, JrPerNr, JrValNummer;

  if @RksSoort in (6,7) then //Debiteur of crediteur
    //Openstaande posten bijwerken, zonder triggers aan!!!!
    set temporary option fire_triggers = 'off';

    //Nu de bedragen in de openstaande posten leegmaken
    update tabOpenstaandePost
    set    OspFactuurBedragVoorlopig  = 0,
           OspFactuurBedragDefinitief = 0,
           OspBetaaldBedragVoorlopig  = 0,
           OspBetaaldBedragDefinitief = 0
    where  OspBjGid = @BjGid and OspRksGid = @RksGid;

    //Bedragen vullen a.d.h.v. journaal
    update tabOpenstaandePost
    set    OspFactuurBedragVoorlopig  = OspFactuurBedragVoorlopig  + if IsDefinitief = 0 and IsFactuurBoeking = 1 then JrValutaBedrag else 0 endif,
           OspFactuurBedragDefinitief = OspFactuurBedragDefinitief + if IsDefinitief = 1 and IsFactuurBoeking = 1 then JrValutaBedrag else 0 endif,
           OspBetaaldBedragVoorlopig  = OspBetaaldBedragVoorlopig  + if IsDefinitief = 0 and IsFactuurBoeking = 0 then JrValutaBedrag else 0 endif,
           OspBetaaldBedragDefinitief = OspBetaaldBedragDefinitief + if IsDefinitief = 1 and IsFactuurBoeking = 0 then JrValutaBedrag else 0 endif
    from (
           select     JrOspGid, if (@RksSoort = 6 and IsCreditBoeking = 0) or (@RksSoort = 7 and IsCreditBoeking = 1) then 1 else 0 endif as IsFactuurBoeking,
                      if RegelNummer is null then 0 else 1 endif as IsDefinitief, sum(JrValutaBedrag) as JrValutaBedrag
           from       tabJournaalRegel
           inner join tabJournaalPost on (JpGid = JrJpGid)
           where      JrBjGid = @BjGid and JrRksGid = @RksGid and JrOspGid is not null and JpIsInGebruik = 0
           group by   JrOspGid, if (@RksSoort = 6 and IsCreditBoeking = 0) or (@RksSoort = 7 and IsCreditBoeking = 1) then 1 else 0 endif, if RegelNummer is null then 0 else 1 endif
         ) as
           JournaalRegels (JrOspGid, IsFactuurBoeking, IsDefinitief, JrValutaBedrag)
    where  OspBjGid = @BjGid and OspRksGid = @RksGid
    and    OspGid   = JrOspGid;

    //Vervallen vlaggetje in openstaande posten goed zetten
    update tabOpenstaandePost
    set    OspIsVervallen = if (OspFactuurBedragVoorlopig + OspFactuurBedragDefinitief) - (OspBetaaldBedragVoorlopig + OspBetaaldBedragDefinitief) = 0 then 1 else 0 endif
    where  OspBjGid = @BjGid and OspRksGid = @RksGid;

    set temporary option fire_triggers = 'on';
  end if;

  set temporary option Isolation_Level = @IsolationLevel;

  set @@ErrorTextProcedure = 'HerstelRekeningsaldoVan1Rekening';
  //call TraceEind(@@ErrorTextProcedure);
end;


//$Workfile: IclAangifteRegelsVullen.sp $ $Revision: 4 $ $Modtime: 23-10-09 8:53 $'

//------- IclAangifteRegelsVullen (IclAangifte)
if exists (select 1 from sys.sysProcedure where proc_name='IclAangifteRegelsVullen') then
  drop procedure IclAangifteRegelsVullen;
end if;

create procedure IclAangifteRegelsVullen(
  in @AangifteGid            Integer,  //AilKopGid
  in @RegelsPrestatie        SmallInt, //Regelsoort Prestatie vullen (1 = ja, anders = nee)
  in @RegelsAbcLevering      SmallInt, //Regelsoort ABC-levering vullen (1 = ja, anders = nee)
  in @RegelsCorrPrestatie    SmallInt, //Regelsoort Correctie prestatie vullen (1 = ja, anders = nee)
  in @RegelsCorrAbcLevering  SmallInt, //Regelsoort correctie ABC-levering vullen (1 = ja, anders = nee)
  in @CorrectiesVanafJaar    Integer,  //correctieregels aanmaken vanaf vanaf jaar ....
  in @CorrectiesVanafTijdvak SmallInt  //correctieregels aanmaken vanaf vanaf tijdvak ... (Zie Meta van AilRglTijdvak)
)
begin
  set @@ErrorTextProcedure = 'IclAangifteRegelsVullen > @AangifteGid='+string(@AangifteGid)+', @RegelsPrestatie='+string(@RegelsPrestatie)+', @RegelsAbcLevering='+string(@RegelsAbcLevering)+', @RegelsCorrPrestatie='+string(@RegelsCorrPrestatie)+', @RegelsCorrAbcLevering='+string(@RegelsCorrAbcLevering)+', @CorrectiesVanafJaar='+string(@CorrectiesVanafJaar)+', @CorrectiesVanafTijdvak='+string(@CorrectiesVanafTijdvak);
  //call TraceBegin(@@ErrorTextProcedure);

  //Moeten we uberhaupt regels aanmaken? als er geen enkele variabele 1 is, dan dus niet...
  if 1 in (@RegelsPrestatie, @RegelsAbcLevering, @RegelsCorrPrestatie, @RegelsCorrAbcLevering) then
    //Aanmaken Levering-regels
    if IsNull(@RegelsPrestatie, 0) = 1 then
      //call Trace('IclAangifteRegelsVullen > Aanmaken Prestatie-regels');
      call IclLeveringRegelAanmaken(@AangifteGid, 0);
    end if;

    //Aanmaken ABC-Levering-regels
    if IsNull(@RegelsAbcLevering, 0) = 1 then
      //call Trace('IclAangifteRegelsVullen > Aanmaken ABC-Levering-regels');
      call IclLeveringRegelAanmaken(@AangifteGid, 1);
    end if;

    //Aanmaken Correcties levering-regels
    if IsNull(@RegelsCorrPrestatie, 0) = 1 then
      //call Trace('IclAangifteRegelsVullen > Aanmaken Correctie levering-regels');
      call IclCorrectieRegelAanmaken(@AangifteGid, @CorrectiesVanafJaar, @CorrectiesVanafTijdvak, 0);
    end if;

    //Aanmaken Correcties ABC-levering-regels
    if IsNull(@RegelsCorrAbcLevering, 0) = 1 then
      //call Trace('IclAangifteRegelsVullen > Aanmaken Correctie ABC-levering-regels');
      call IclCorrectieRegelAanmaken(@AangifteGid, @CorrectiesVanafJaar, @CorrectiesVanafTijdvak, 1);
    end if;
  end if;

  set @@ErrorTextProcedure = 'IclAangifteRegelsVullen > @AangifteGid='+string(@AangifteGid)+', @RegelsPrestatie='+string(@RegelsPrestatie)+', @RegelsAbcLevering='+string(@RegelsAbcLevering)+', @RegelsCorrPrestatie='+string(@RegelsCorrPrestatie)+', @RegelsCorrAbcLevering='+string(@RegelsCorrAbcLevering)+', @CorrectiesVanafJaar='+string(@CorrectiesVanafJaar)+', @CorrectiesVanafTijdvak='+string(@CorrectiesVanafTijdvak);
  //call TraceEind(@@ErrorTextProcedure);


end;


//$Workfile: IclCorrectieRegelAanmaken.sp $ $Revision: 11 $ $Modtime: 13-11-09 15:31 $'

//------- IclCorrectieRegelAanmaken (IclAangifte)
if exists (select 1 from sys.sysProcedure where proc_name='IclCorrectieRegelAanmaken') then
  drop procedure IclCorrectieRegelAanmaken;
end if;

create procedure IclCorrectieRegelAanmaken(
  in @AangifteGid            Integer,  //AilKopGid
  in @CorrectiesVanafJaar    Integer,  //correctieregels aanmaken vanaf vanaf jaar ....
  in @CorrectiesVanafTijdvak SmallInt, //correctieregels aanmaken vanaf vanaf tijdvak ....(Zie Meta van AilRglTijdvak)
  in @IsCorrAbcLevering      SmallInt  //0 = prestatie, 1 = abc-levering
)
begin
  declare @AangifteJaar         Integer;  //Jaartal van de aangifte
  declare @AangifteTijdvak      SmallInt; //(Zie Meta van AilRglTijdvak)
  declare @eigenlandcode        Integer;  //Landcode die bij de bedrijfsgegevens is ingevuld (het land waar de belastingplichtige gevestigd is volgens de administratie)
  declare @regelSoort           SmallInt; //2 = correctie prestatie, 3 = correctie abc-levering
  Declare @AangifteJaarTijdvak  Integer;  //AangifteJaar en tijdvak (bijv. 200403)
  Declare @CorrectieJaarTijdvak Integer;  //Correctiejaar en tijdvak (bijv 200302)

  set @@ErrorTextProcedure = 'IclCorrectieRegelAanmaken > @AangifteGid='+string(@AangifteGid)+', @CorrectiesVanafJaar='+string(@CorrectiesVanafJaar)+', @CorrectiesVanafTijdvak='+string(@CorrectiesVanafTijdvak)+', @IsCorrAbcLevering='+string(@IsCorrAbcLevering);
  //call TraceBegin(@@ErrorTextProcedure);

  //Aangiftejaar en -tijdvak bepalen a.d.h.v. het aangiftegid (scheelt 2 params)
  select AilKopJaar, AilKopTijdvak into @AangifteJaar, @AangifteTijdvak from tabIclAangifteKop where AilKopGid = @AangifteGid;

  //Regelsoort instellen
  // als @IsCorrAbcLevering <> 0, 1, dan klappen we eruit in de trigger tb_tabIclAangifteRegel
  // regelsoort moet 2 of 3 zijn (dus @IsCorrAbcLevering + 2 > 2 = correctie prestatie, 3 = correctie abc-levering
  set @RegelSoort = if @IsCorrAbcLevering in (0, 1) then @IsCorrAbcLevering + 2 else -1 endif;

  //Correctiejaartijdvak variabele vullen
  set @CorrectieJaarTijdvak = (@CorrectiesVanafJaar * 100) + (select @beginmaand from IclTijdvaknaarBeginEindmaand(@CorrectiesVanafTijdvak));

  //jaar/tijdvak dat VOOR het jaar/tijdvak ligt van deze aangifte
  if @AangifteTijdvak in (40,100,101,113) then
    set @AangifteJaarTijdvak = ((@Aangiftejaar - 1) * 100) + 12;
  else
    set @AangifteJaarTijdvak = (@Aangiftejaar * 100) + (select @beginmaand from IclTijdvaknaarBeginEindmaand(@AangifteTijdvak))-1;
  end if;

  //eigen landcode vaststellen
  select DefaultLndGid into @EigenLandcode from tabVasteGegevens;

  //call trace('IclCorrectieRegelAanmaken > @AangifteJaar='+string(@AangifteJaar)+', @AangifteTijdvak='+string(@AangifteTijdvak)+', @eigenlandcode='+string(@eigenlandcode)+', @regelSoort='+string(@regelSoort)+', @AangifteJaarTijdvak='+string(@AangifteJaarTijdvak)+', @CorrectieJaarTijdvak='+string(@CorrectieJaarTijdvak));
  insert into tabICLAangifteRegel (AilRglAilKopGid, AilRglJaar, AilRglTijdVak, AilRglNawGid, AilRglBedragLevering, AilRglBedragDienst, AilRglNawObNummer, AilRglLandCode, AilRglSoort)

  //MR 29-apr-2008 bug #27959: BtwCode nu uit de tabIct halen ipv tabNawFile
  select
    @AangifteGid,
    AangifteJaar,
    AangifteTijdvak,
    AangifteNawGid,
    Sum(Floor(TotaalAanTeGeven)-ReedsAangegeven) as NogAanTeGeven,
    Sum(Floor(TotaalAanTeGevenDienst)-ReedsAangegevenDienst) as NogAanTeGevenDienst,
    if Left(NawBtwNummer, Length(LndCodeEu)) = LndCodeEu then REPLACE(SubString(NawBtwNummer, Length(LndCodeEu)+1), ' ', '') else REPLACE(NawBtwNummer, ' ', '') +'!' endif BtwNummer, //!@#
    LndCodeEU,
    @RegelSoort
  from (
    select
      NawGid               as AangifteNawGid,
      IctJaar              as AangifteJaar,
      isNull((select first AilRglTijdvak from tabIclaangifteregel where AilRglJaar = ictJaar
      and ictMaand between (select @Beginmaand from IclTijdvaknaarBeginEindmaand(AilRglTijdVak))
                      and (select @Eindmaand from IclTijdvaknaarBeginEindmaand(AilRglTijdVak))), (Round((ictMaand+2)/3,0)*100+ictMaand) ) as AangifteTijdvak,
      sum(if ((IctIsAbcLevering=1) and (@RegelSoort=2)) then 0 else ictbedraggoed endif) as TotaalAanTeGeven,
      0                    as ReedsAangegeven,
      sum(if ((AangifteJaar > 2009) and (@RegelSoort=2)) then IctBedragDienst else 0 endif) as TotaalAanTeGevenDienst,
      0                    as ReedsAangegevenDienst
    from
      tabNaw
      inner join tabNawFile on (NawFilNawGid = AangifteNawGid and NawFilFonId  = 'D')
      inner join tabAdres   on (adrNawGid = AangifteNawGid and adrGid = nawGidVestiging)
      inner join tabLand    on (LndGid = AdrLndGid and LndIsEgLid = 1 and LndGid <> @EigenLandcode)
      inner join (tabIct inner join tabBtw on (IctBtwCode = BtwCode)) on (IctNawGid = AangifteNawGid and IctIsLevering = 1
                                            and IctIsAbcLevering in (1,@IsCorrAbcLevering))
    where
          ((AangifteJaar*100) + IctMaand) between @CorrectieJaarTijdvak and @AangifteJaarTijdvak
      and BtwRubriekAangifte = 7
    group by
      AangifteNawGid, AangifteJaar, AangifteTijdvak

  UNION

    select
      NawGid                    as AangifteNawGid,
      AilRglJaar                as AangifteJaar,
      AilRglTijdvak             as AangifteTijdvak,
      0                         as TotaalAanTeGeven,
      sum(AilRglBedragLevering) as ReedsAangegeven,
      0                         as TotaalAanTeGevenDienst,
      sum(if ((@IsCorrAbcLevering = 0) and (AangifteJaar > 2009)) then AilRglBedragDienst else 0 endif) as ReedsAangegevenDienst
    from
      tabNaw
      inner join tabNawFile          on (NawFilNawGid = AangifteNawGid and NawFilFonId  = 'D')
      inner join tabIclaangifteregel on (AilRglNawGid = AangifteNawGid and AilRglSoort in (@IsCorrAbcLevering, @IsCorrAbcLevering + 2))
    where
      ((AangifteJaar*100) + (select @beginmaand from IclTijdvaknaarBeginEindmaand(AangifteTijdvak))) between @CorrectieJaarTijdvak and @AangifteJaarTijdvak
    group by
      AangifteNawGid, AangifteJaar, AangifteTijdvak
  )
  as DummyTableIclAangifte
     inner join tabNaw     on (NawGid       = AangifteNawGid)
     inner join tabNawFile on (NawFilNawGid = AangifteNawGid)
     inner join tabAdres   on (adrNawGid    = AangifteNawGid and adrGid = nawGidVestiging)
     inner join tabLand    on (LndGid       = AdrLndGid)
  where
    AangifteNawGid not in (select AilRglNawGid
                           from   tabIclAangifteRegel
                           where      AilRglAilKopGid = @AangifteGid
                                  and AilRglSoort     = @RegelSoort
                                  and AilRglTijdvak   = AangifteTijdvak
                                  and AilRglJaar      = AangifteJaar)
  group by
    AangifteNawGid, AangifteJaar, AangifteTijdvak, NawBtwNummer, LndCodeEU
  having NogAanTeGeven <> 0
  or NogAanTeGevenDienst <> 0;

  set @@ErrorTextProcedure = 'IclCorrectieRegelAanmaken > @AangifteGid='+string(@AangifteGid)+', @CorrectiesVanafJaar='+string(@CorrectiesVanafJaar)+', @CorrectiesVanafTijdvak='+string(@CorrectiesVanafTijdvak)+'@IsCorrAbcLevering='+string(@IsCorrAbcLevering)+', @AangifteJaar='+string(@AangifteJaar)+', @AangifteTijdvak='+string(@AangifteTijdvak)+', @eigenlandcode='+string(@eigenlandcode)+', @regelSoort='+string(@regelSoort)+', @AangifteJaarTijdvak='+string(@AangifteJaarTijdvak)+', @CorrectieJaarTijdvak='+string(@CorrectieJaarTijdvak);
  //call TraceEind(@@ErrorTextProcedure);


end;


//$Workfile: IclLeveringRegelAanmaken.sp $ $Revision: 9 $ $Modtime: 13-11-09 15:30 $'

//------- IclLeveringRegelAanmaken (IclAangifte)
if exists (select 1 from sys.sysProcedure where proc_name='IclLeveringRegelAanmaken') then
  drop procedure IclLeveringRegelAanmaken;
end if;

create procedure IclLeveringRegelAanmaken(
  in @AangifteGid           Integer,  //AilKopGid
  in @IsAbcLevering         SmallInt  //0 = prestatie, 1 = abc-levering
)
begin
  declare @AangifteJaar    Integer;  //Jaartal van de aangifte
  declare @AangifteTijdvak SmallInt; //correctieregels aanmaken vanaf vanaf tijdvak ....(Zie Meta van AilRglTijdvak)
  declare @EigenLandcode   Integer;  // Eigen landcode, om bedrijven uit datzelfde land te kunnen filteren (zijn geen icl aangiften voor nodig)
  declare @Beginmaand      SmallInt; // eerste  maand van het tijdvak
  declare @Eindmaand       SmallInt; // laatste maand van het tijdvak
  declare @RegelSoort      SmallInt; // 0 = Prestatie, 1 = AbcLevering

  set @@ErrorTextProcedure = 'IclLeveringRegelAanmaken > @AangifteGid='+string(@AangifteGid)+'@IsAbcLevering='+string(@IsAbcLevering);
  //call TraceBegin(@@ErrorTextProcedure);

  //Aangiftejaar en -tijdvak bepalen a.d.h.v. het aangiftegid (scheelt 2 params)
  select AilKopJaar, AilKopTijdvak into @AangifteJaar, @AangifteTijdvak from tabIclAangifteKop where AilKopGid = @AangifteGid;

  //Eigen landcode vaststellen.
  select DefaultLndGid into @EigenLandcode from tabVasteGegevens;

  //begin- en eindmaand van het tijdvak vaststellen.
  select @Beginmaand,@Eindmaand into @Beginmaand,@Eindmaand from IclTijdvaknaarBeginEindmaand(@AangifteTijdvak);

  //Regelsoort instellen
  set @RegelSoort = if @IsAbcLevering in (0, 1) then @IsAbcLevering else -1 endif; // als IsAbcLevering <> 0, 1, dan klappen we eruit in de trigger tb_tabIclAangifteRegel

  //call trace('IclLeveringRegelAanmaken > @AangifteJaar='+string(@AangifteJaar)+', @AangifteTijdvak='+string(@AangifteTijdvak)+', @EigenLandcode='+string(@eigenlandcode)+', @regelSoort='+string(@regelSoort)+', @Beginmaand='+string(@Beginmaand)+', @Eindmaand='+string(@Eindmaand));
  //MR 29-apr-2008 bug #27959: BtwCode nu uit de tabIct halen ipv tabNawFile

  insert into tabICLAangifteRegel (AilRglAilKopGid, AilRglJaar, AilRglTijdVak, AilRglNawGid, AilRglBedragLevering, AilRglBedragDienst, AilRglNawObNummer, AilRglLandCode, AilRglSoort)
  select
    @AangifteGid,
    AangifteJaar,
    AangifteTijdvak,
    AangifteNawGid,
    Sum(Floor(TotaalAanTeGeven)-ReedsAangegeven) as NogAanTeGeven,
    Sum(Floor(TotaalAanTeGevenDienst)-ReedsAangegevenDienst) as NogAanTeGevenDienst,
    if Left(NawBtwNummer, Length(LndCodeEu)) = LndCodeEu then REPLACE(SubString(NawBtwNummer, Length(LndCodeEu)+1), ' ', '') else REPLACE(NawBtwNummer, ' ', '') +'!' endif BtwNummer, //!@#
    LndCodeEU,
    @RegelSoort
  from (
    select
      NawGid               as AangifteNawGid,
      IctJaar              as AangifteJaar,
      @AangifteTijdvak     as AangifteTijdvak,
      sum(if ((IctIsAbcLevering=1) and (@RegelSoort=0)) then 0 else ictbedraggoed endif)   as TotaalAanTeGeven,
      0                    as ReedsAangegeven,
      sum(if ((@RegelSoort=0) and (AangifteJaar > 2009)) then ictbedragdienst else 0 endif) as TotaalAanTeGevenDienst,
      0                    as ReedsAangegevenDienst
    from
      tabNaw
      inner join tabNawFile on (NawFilNawGid = AangifteNawGid and NawFilFonId  = 'D')
      inner join tabAdres   on (adrNawGid = AangifteNawGid and adrGid = nawGidVestiging)
      inner join tabLand    on (lndGid = AdrLndGid and lndIsEgLid = 1 and LndGid <> @EigenLandcode)
      inner join (tabIct inner join tabBtw on (IctBtwCode = BtwCode)) on (AangifteNawGid = IctNawGid
      				and IctIsLevering = 1
      				and IctIsAbcLevering in (1,@IsAbcLevering)
              and ictJaar = @AangifteJaar
              and ictMaand between @Beginmaand and @Eindmaand
              // alleen die Naws toevoegen die nog in in een aangifteregel voorkomen...
              and IctNawGid not in (select AilRglNawGid from tabIclAangifteRegel where AilRglAilKopGid = @AangifteGid and AilRglSoort = @RegelSoort)
              )
    where
      BtwRubriekAangifte = 7
    group by
      AangifteNawGid, AangifteJaar, AangifteTijdvak

    UNION

    select
      NawGid                    as AangifteNawGid,
      AilRglJaar                as AangifteJaar,
      AilRglTijdvak             as AangifteTijdvak,
      0                         as TotaalAanTeGeven,
      sum(AilRglBedragLevering) as ReedsAangegeven,
      0                         as TotaalAanTeGevenDienst,
      sum(if ((@IsAbcLevering = 0) and (AangifteJaar > 2009)) then AilRglBedragDienst else 0 endif) as ReedsAangegevenDienst
    from
      tabNaw
      inner join tabNawFile          on (    NawFilNawGid = AangifteNawGid
                                         and NawFilFonId  = 'D'
                                        )
      inner join tabIclaangifteregel on (    AilRglNawGid  = AangifteNawGid
                                         and AilRglJaar    = @AangifteJaar
                                         and AilRglTijdVak = @AangifteTijdvak
                                         and AilRglSoort in (@IsAbcLevering, @IsAbcLevering + 2)
                                        )
    group by
      AangifteNawGid, AangifteJaar, AangifteTijdvak
  )
  as DummyTableIclAangifte
     inner join tabNaw     on (NawGid       = AangifteNawGid)
     inner join tabNawFile on (NawFilNawGid = AangifteNawGid)
     inner join tabAdres   on (adrNawGid    = AangifteNawGid and adrGid = nawGidVestiging)
     inner join tabLand    on (LndGid       = AdrLndGid)
  where
    AangifteNawGid not in (select AilRglNawGid
                           from   tabIclAangifteRegel
                           where      AilRglAilKopGid = @AangifteGid
                                  and AilRglSoort     = @RegelSoort
                                  and AilRglTijdvak   = AangifteTijdvak
                                  and AilRglJaar      = AangifteJaar)
  group by
    AangifteNawGid, AangifteJaar, AangifteTijdvak, NawBtwNummer, LndCodeEU
  having NogAanTeGeven <> 0
      or NogAanTeGevenDienst <> 0;

  set @@ErrorTextProcedure = 'IclLeveringRegelAanmaken > @AangifteGid='+string(@AangifteGid)+'@IsAbcLevering='+string(@IsAbcLevering)+', @AangifteJaar='+string(@AangifteJaar)+', @AangifteTijdvak='+string(@AangifteTijdvak)+', @EigenLandcode='+string(@eigenlandcode)+', @regelSoort='+string(@regelSoort)+', @Beginmaand='+string(@Beginmaand)+', @Eindmaand='+string(@Eindmaand);
  //call TraceEind(@@ErrorTextProcedure);
end;


if exists (select 1 from sys.sysProcedure where proc_name= 'IclTijdvaknaarBeginEindmaand') then
  drop procedure IclTijdvaknaarBeginEindmaand;
end if;

create procedure IclTijdvaknaarBeginEindmaand(in @Tijdvak smallint)
begin
  declare @Beginmaand smallint;
  declare @Eindmaand  smallint;
  //Berekend de beginmaand en eindmaand van de opgegeven ICP tijdvak.
  set @@ErrorTextProcedure = 'IclTijdvaknaarBeginEindmaand > @Tijdvak='+string(@Tijdvak);
  //call TraceBegin(@@ErrorTextProcedure);

  //Als het opgegeven tijdvak niet bestaat 0 teruggeven als maand.
  set @Beginmaand = 0;
  set @Eindmaand  = 0;

  case
  when @Tijdvak in (100,200,300,400) then       //Kwartaal
    set @Eindmaand  = (@Tijdvak/100) * 3;
    set @Beginmaand = @Eindmaand - 2;
  when right(@Tijdvak,2) between 1 and 12 then  //Maand
    //Het eerste cijfer representeerd het kwartaal, dus de maand dient hier wel in te liggen
    if right(@Tijdvak,2) between (left(@Tijdvak,1)*3-2) and (left(@Tijdvak,1)*3) then
      set @Beginmaand = right(@Tijdvak,2);
      set @Eindmaand  = @Beginmaand;
    end if;
  when @tijdvak = 40 then                       //Jaar
    set @Beginmaand = 1;
    set @Eindmaand  = 12;
  when right(@Tijdvak,2) = 13 then              //jan/feb
    set @Beginmaand = 1;
    set @Eindmaand  = 2;
  when right(@Tijdvak,2) = 14 then              //apr/mei
    set @Beginmaand = 4;
    set @Eindmaand  = 5;
  when right(@Tijdvak,2) = 15 then              //jul/aug
    set @Beginmaand = 7;
    set @Eindmaand  = 8;
  when right(@Tijdvak,2) = 16 then              //okt/nov
    set @Beginmaand = 10;
    set @Eindmaand  = 11;
  end case;

  set @@ErrorTextProcedure = 'IclTijdvaknaarBeginEindmaand > @Tijdvak='+string(@Tijdvak);
  //call TraceEind(@@ErrorTextProcedure);

  select @Beginmaand,@Eindmaand;
end;


create or replace procedure ImportLogDetail_Toevoegen(
  @iLogDetilogGid integer default null,
  @iLogDetItemNummer integer default null,
  @iLogDetReden nchar(250) default '',
  @iLogDetStatus integer default 0
)
begin
  /*Constanten*/
  declare _qcJa smallint = 1;
  declare _qcNee smallint = 0;

  declare _LEVEL_0 smallint = 0; /* leeg (niets loggen) */
  declare _LEVEL_1 smallint = 1; /* alleen fouten */
  declare _LEVEL_2 smallint = 2; /* fouten en waarschuwingen */
  declare _LEVEL_3 smallint = 3; /* alle bovenstaande + niet verwerkte zaken + records niet verwijderd/toegevoegd/verwijderd */
  declare _LEVEL_4 smallint = 4; /* alle bovenstaande + alle wel verwerkte acties + alle wel verwerkte records */

  declare @_Status array of integer;
  declare @_Index smallint = 1;

  //call TraceBegin('ImportLogDetail_Toevoegen > @iLogDetilogGid='+string(@iLogDetilogGid));

  //Bij Level 0 niets loggen.
  if (@@ImportLogLevel > _LEVEL_0) then
    if ((@@ImportLogLevel = _LEVEL_1) and (@iLogDetStatus = 6)) or /*6=Fout in record*/
    ((@@ImportLogLevel = _LEVEL_2) and (@iLogDetStatus in (5,6))) or /*Level 1 + 5=Waarschuwing*/
    ((@@ImportLogLevel = _LEVEL_3) and (@iLogDetStatus in (3,4,5,6,7,10))) or /*Level 2 + 3=Record is niet gewijzigd,4=Record kan niet worden verwijderd,7=Record is niet toegevoegd,10=Record is niet verwerkt*/
    (@@ImportLogLevel = _LEVEL_4) then /*Level 3 + 0=Record succesvol toegevoegd, 1=Record succesvol gewijzigd, 2=Record succesvol verwijderd, 8=Melding, 9=Record is verwerkt*/
        if @iLogDetItemNummer is null then
          set @iLogDetItemNummer = IsNull((select max(iLogDetItemNummer)+1 from tabImportLogDetail where iLogDetilogGid = @iLogDetilogGid), 1)
        end if;

        insert into tabImportLogDetail (iLogDetilogGid, iLogDetItemNummer, iLogDetReden, iLogDetStatus)
          values (@iLogDetilogGid, @iLogDetItemNummer, @iLogDetReden, @iLogDetStatus);
      end if;
  end if;

  //call TraceEind('ImportLogDetail_Toevoegen > @iLogDetilogGid='+string(@iLogDetilogGid));
end;


//$Workfile: IncassoZetIncRegelsOpdrAangemaakt.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// Incassoregels op status 1 (=Opdracht aangemaakt) zetten
if exists (select 1 from sys.sysProcedure where proc_name='IncassoZetIncRegelsOpdrAangemaakt') then
  drop procedure IncassoZetIncRegelsOpdrAangemaakt;
end if;

create procedure IncassoZetIncRegelsOpdrAangemaakt(
 in @IncKopID integer,
 in @BatchPer integer)    // 0 = datum; WORDT NOG NIKS MEE GEDAAN
begin
  declare @BatchNr integer;

  set @@ErrorTextProcedure = 'IncassoZetIncRegelsOpdrAangemaakt > @IncKopID='+string(@IncKopID);
  //call TraceBegin(@@ErrorTextProcedure);
  set @BatchNr = 1;

  for @Cursor AS CURSOR_IncData CURSOR FOR
    select   IncRglDatum @Datum
    from     tabIncassoRegel
    where    IncRglIncKopID = @IncKopID
    group by IncRglDatum
    order by IncRglDatum
  for read only
  do
    update tabIncassoRegel
    set    IncRglStatus = 1,
           IncRglBatchNr = @BatchNr
    where      (IncRglIncKopID = @IncKopID)
           and (IncRglDatum = @Datum);
    set @BatchNr = @BatchNr + 1;
  end for;

  //call TraceEind(@@ErrorTextProcedure);

end;


//---- Test of een bepaalde Index bestaat in de database
create or replace procedure IndexExist(in @Indexnaam nchar(40), inout @Exists smallint)
begin
  set @@ErrorTextProcedure = 'IndexExist > @IndexNaam='+@IndexNaam;
  //call TraceBegin(@@ErrorTextProcedure);

  select 1 into @Exists from sys.sysindex where index_name = @Indexnaam;
  set @Exists = IsNull(@Exists, 0);

  set @@ErrorTextProcedure = 'IndexExist > @Exists='+string(@Exists);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure InkoopfactuurAanmakenBtwBlok(in @IfkGid integer)
begin
  set @@ErrorTextProcedure = 'InkoopfactuurAanmakenBtwBlok';
  //call TraceBegin(@@ErrorTextProcedure);

  delete tabInkoopfactuurBtwblok where ifbIfkGid = @IfkGid;

  insert into tabInkoopfactuurBtwblok
  (
    IfbBtwCode,
    IfbGrondslagBedrag,
    IfbBtwBedrag,
    IfbIfkGid
   )
   select
     IfrBtwCode,
     Sum(IfrRegeltotaalExclBtw) as BtwBasisBedrag,
     round(BtwPercentage * BtwBasisBedrag / 100, 2) as BtwBedrag,
     IfrIfkGid
   from tabInkoopfactuurRegel
   inner join tabBtw on BtwCode = IfrBtwCode
   where
     IfrIfkGid = @IfkGid and IfrRegelSoort in (1,2) // Tarief- en artikelregel
   group by
     IfrIfkGid,
     IfrBtwCode,
     BtwPercentage;

  set @@ErrorTextProcedure = 'InkoopfactuurAanmakenBtwBlok';
  //call TraceEind(@@ErrorTextProcedure);
end;

//call InkoopfactuurAanmakenBtwBlok;

create or replace procedure InkoopfactuurAanmakenObvMagazijnOntvangst(in @MokGid integer, in @IsGoedgekeurd smallint, out @IfkGid integer)
begin
  set @@ErrorTextProcedure = 'InkoopfactuurAanmakenObvMagazijnOntvangst';
  //call TraceBegin(@@ErrorTextProcedure);

  insert into tabInkoopfactuurKop (
    IfkBerekenBtwBlokAutom,
    IfkBetalingskenmerk,
    IfkBtcNummer,
    IfkFactuurbedragExclBTW,
    IfkFactuurdatum,
    IfkFactuurNummer,
    IfkFactuurNummer_Lengte,
    IfkIsVerwerkt,
    IfkNawGid,
    IfkOmschrijving,
    IfkReferentienummer,
    IfkReferentienummer_Lengte,
    IfkTotaalBtw,
    IfkValNummer,
    IfkVervaldatum,
    IfkIsGoedgekeurd,
    IfkGoedgekeurdOp,
    IfkGoedgekeurdDoor
  )
  select
    1,  // BtwBlok automatisch bereken
    MokBetKenmerk,
    MokBtcNummer,
    0,  // Factuurbedrag
    MokFactuurdatum,
    MokFactuurnummer,
    Length(MokFactuurnummer),
    0, // Niet verwerkt
    MokNawGid,
    MokOmschrijving,
    MokFactuurnummer,
    Length(MokFactuurnummer),
    0,
    MokValNummer,
    MokVervaldatum,
    @IsGoedgekeurd,
    if (@IsGoedgekeurd = 1) then now(*) endif,
    if (@IsGoedgekeurd = 1) then @@GebruikerCode endif
  from tabMagazijnOntvangstenKop
  where MokGid = @MokGid;

  set @IfkGid = @@Identity;

  // Digitaal archiefstuk overnemen
  begin
    declare @IsFactuur smallint = 0;

    if (select count(*) from tabDigitaalArchiefMagazijnOntvangsten where DaMagOntMokGid = @MokGid) = 1 then
      set @IsFactuur = 1;
    end if;
    // Alleen overnemen als er precies 1 archiefstuk is
    insert into tabDigitaalArchiefInkoopfactuur(
           DaIfkIfkGid,
           DaIfkIsFactuur,
           DaIfkDarGid)
    select /*DaIfkIfkGid*/     @IfkGid,
           /*DaIfkIsFactuur*/  @IsFactuur,
           /*DaIfkDarGid*/     DaMagOntDarGid
    from   tabDigitaalArchiefMagazijnOntvangsten
    where  DaMagOntMokGid = @MokGid
  end;


  // Regels toevoegen
  insert into tabInkoopfactuurRegel (
    IfrIfkGid,
    IfrAantal,
    IfrAantalDecimalenVoorAantallen,
    IfrAantalDecimalenVoorPrijzen,
    IfrArtGid,
    IfrArtikelNummerLeverancier,
    IfrArtPartijGid,
    IfrBtwCode,
    IfrEANcode,
    IfrInkoopeenheid,
    IfrKortingBedrag,
    IfrKortingPercentage,
    IfrKortingSoort,
    IfrOms,
    IfrPrijs,
    IfrPrijsPer,
    IfrPrijsPerSoort,
    IfrReferentienummer,
    IfrReferentienummer_lengte,
    IfrRegelNr,
    IfrRegelSoort,
    IfrVoorraadeenhedenInInkoopeenheid,
    IfrTussenrekeningBedragInPrijsPer,
    IfrTussenrekeningPrijsPerAantal,
	IfrTussenrekeningValNummer
    )
  select
    @IfkGid,
    MagOntAantalInkoopEenheden,
    ArtAantDecAantallen,
    ArtAantDecPrijzen,
    MagOntArtGid,
    MagOntArtCodeBijLeverancier,
    MagOntArtPartijGid,
    MagOntBtwCode,
    MagOntEanCode,
    MagOntInkoopEenheid,
    MagOntKortingBedrag,
    MagOntKortingPercentage,
    MagOntKortingSoort,
    if MagOntBstRglGid is null then ArtOms else MagOntBstRglOms endif,
    MagOntInkoopprijs,
    MagOntPrijsPer,
    MagOntInkoopprijsPer,
    MokFactuurnummer,
    Length(MokFactuurnummer),
    MagOntRegelnr,
    MagOntRegelsoort,
    MagOntVoorraadEenhedenInInkoopEenheid,
    // ACW 22-04-2024 Defect 59316: Als tussenrekening niet bij MagOnt geboekt, dan dat hier ook niet als 0 doorgeven (null: niet geboekt, 0: prijs van 0,00)
    if MagOntTussenrekeningTotaalGeboekt is not null then
      IsNull(MagOntTussenrekeningTotaalGeboekt, 0) / if (MagOntAantalInkoopEenheden * MagOntVoorraadEenhedenInInkoopEenheid) = 0 then 1 else (MagOntAantalInkoopEenheden * MagOntVoorraadEenhedenInInkoopEenheid) endif * MagOntPrijsPer
    endif, // Als tegen werkelijke inkoopprijs geboekt, dan is het prijsverschil al bij de mag.ontv. geboekt; hier NIET afronden!
    MagOntPrijsPer,
	MokValNummer
  from tabMagazijnOntvangsten
  inner join tabMagazijnOntvangstenKop on MokGid = MagOntMokGid
  inner join tabArtikel on MagOntArtGid = ArtGid
  where MagOntMokGid = @MokGid;

  call InkoopfactuurAanmakenBtwBlok(@IfkGid);

  set @@ErrorTextProcedure = 'InkoopfactuurAanmakenObvMagazijnOntvangst';
  //call TraceEind(@@ErrorTextProcedure);
end;

//call InkoopfactuurAanmakenObvMagazijnOntvangst;

create or replace procedure InkoopfactuurAanvullenObvHistMagOntvangst(in @IfkGid integer, in @MohkGid integer)
begin atomic
  declare local temporary table tmpInkoopfactuurregels (
    tmpMohrGid integer,
    tmpIfrGid integer
  );
  declare @HeeftAlRegels        smallint;
  declare @ValutaNr             integer;
  declare @FactuurDatum         date;
  declare @BerekenBtwBlokAutom  smallint;
  declare @NawGid               integer;

  set @@ErrorTextProcedure = 'InkoopfactuurAanvullenObvHistMagOntvangst';
  //call TraceBegin(@@ErrorTextProcedure);

  select
    IfkValNummer,
    IfkFactuurdatum,
    IfkBerekenBtwBlokAutom,
    IfkNawGid
  into
    @ValutaNr,
    @FactuurDatum,
    @BerekenBtwBlokAutom,
    @NawGid
  from tabInkoopfactuurKop
  where IfkGid = @IfkGid;

  if @NawGid <> (
    select NawFilNawGid from tabMagazijnOntvangstHistKop
    inner join tabMagazijnOntvangstHistAdres on MohaGid = MohkMohaGidLeverancier
    inner join tabnawfile on nawfilnummer = mohanawfilnummer and nawfilfonid='C'
    where MohkGid = @MohkGid) then
    raiserror 20374;
  end if;

  if exists(select first 1 from tabInkoopfactuurRegel where IfrIfkGid = @IfkGid) then
    set  @HeeftAlRegels = 1;
  else
    set  @HeeftAlRegels = 0;
  end if;


  insert into tmpInkoopfactuurregels (
    tmpMohrGid,
    tmpIfrGid
  )
  select
    MohrGid,
    InkoopfactuurregelMakenUitHistorischeMagazijnOntvangstregel (@IfkGid, if @HeeftAlRegels = 1 then null else MohrRegelNr endif, MohrGid, 1 /* kop updaten*/, @ValutaNr, @FactuurDatum)
  from tabMagazijnontvangstHistRegel
  where MohrMohkGid = @MohkGid
  order by MohrRegelNr;

  if @BerekenBtwBlokAutom = 1 then
    call InkoopfactuurAanmakenBtwBlok(@IfkGid);
  end if;
end;

//call InkoopfactuurAanvullenObvHistMagOntvangst;

create or replace function InkoopfactuurDefaultBetalingskenmerk(
  in @Factuurnummer     nchar(40),
  in @OnsDebiteurNummer nchar(20),
  in @LeverancierNummer nchar(10)
) returns nchar(140)
begin
  declare @BetKenmerk           nchar(140);
  declare @MagVastDefBetKenmerk smallint;
  //call TraceBegin('InkoopfactuurDefaultBetalingskenmerk');

  set @Factuurnummer      = IsNull(@Factuurnummer, '');
  set @OnsDebiteurNummer  = IsNull(@OnsDebiteurNummer, '');
  set @LeverancierNummer  = IsNull(@LeverancierNummer, '');

  // ophalen vaste gegevens!
  select first MagVastDefBetKenmerk into @MagVastDefBetKenmerk from tabMagazijnOntvangstenVasteGegevens;

  case @MagVastDefBetKenmerk
    when 0 then /*Leeg*/
      set @BetKenmerk = '';

    when 1 then /*Ons_debiteurnummer_en_factuurnummer*/
      set @BetKenmerk = @OnsDebiteurNummer;
      if @Factuurnummer <> '' then
        if @BetKenmerk <> '' then
          set @BetKenmerk = @BetKenmerk + '/' + @Factuurnummer;
        else
          set @BetKenmerk = @Factuurnummer;
        end if;
      end if;

    when 2 then /*Crediteurnummer_en_factuurnummer */
      set @BetKenmerk = @LeverancierNummer;
      if @Factuurnummer <> '' then
        if @BetKenmerk <> '' then
          set @BetKenmerk = @BetKenmerk + '/' + @Factuurnummer;
        else
          set @BetKenmerk = @Factuurnummer;
        end if;
      end if;

    when 3 then /*Ons_debiteurnummer*/
      set @BetKenmerk = @OnsDebiteurNummer;

    when 4 then /*Crediteurnummer*/
      set @BetKenmerk = @LeverancierNummer;

    when 5 then /*factuurnummer*/
      set @BetKenmerk = @Factuurnummer;

  else
    set @BetKenmerk = '';
  end case;

  return @BetKenmerk;
  //call TraceEind('InkoopfactuurDefaultBetalingskenmerk');
end;
//select InkoopfactuurDefaultBetalingskenmerk('FactNr', 'OnsNr', 'CredNr')

Create or replace function InkoopfactuurregelMakenUitHistorischeMagazijnOntvangstregel(
  in  @IfkGid     integer,  // Inkoopfactuur waaraan deze regel wordt toegevoegd
  in  @IfrRegelNr integer,  // null -> achteraan toevoegen, anders tussenvoegen (de meegegeven regel + alle volgende schuiven op als het niet past)
  in  @MohrGid    integer,
  in  @UpdateIFkop smallint, //Om bijv. referentie te vullen; 0 = Niet updaten als er nog geen regels zijn, 1 = Wel updaten als er nog geen regels zijn
  in  @ValutaNr    integer,
  in  @FactuurDatum date
)
returns integer // Resultaat is het zojuist toegevoegde IfrGid
begin atomic
  declare @BjGid             integer;
  declare @PerNr             integer;
  declare @IsRegelToegevoegd smallint;

  set @@ErrorTextProcedure = 'InkoopfactuurregelMakenUitHistorischeMagazijnOntvangstregel';
  //call TraceBegin(@@ErrorTextProcedure);

  // Tbv omrekenen
  call BepaalBoekjaarEnPeriode (@FactuurDatum, @BjGid, @PerNr);

  // **************************
  // *** Bepaal regelnummer ***
  // **************************
  if @IfrRegelNr is null then
    // Geen regelnummer meegegeven, dus APPEND
    select max(IfrRegelNr) + 1 into @IfrRegelNr from tabInkoopfactuurRegel where IfrIfkGid = @IfkGid;
    if @IfrRegelNr is null then
      set @IfrRegelNr = 1;
    end if;
  else
    //Regelnummer meegegeven, dus INSERT (tussenschuiven op de plek van het regelnummer)
    if exists(select first 1 from tabInkoopfactuurRegel where IfrIfkGid = @IfkGid and IfrRegelNr = @IfrRegelNr) then
      //Regel bestaat, dus doorschuiven tot eerstvolgende lege plek
      begin
        declare @OpschuivenTotEnMet integer;

        //Bepaal tot waar we moeten opschuiven
        select min(IfrRegelNr)
        into   @OpschuivenTotEnMet
        from   tabInkoopfactuurRegel L
        where  not exists(select first 1 from tabInkoopfactuurRegel as R where R.IfrRegelNr = L.IfrRegelNr + 1 and R.IfrIfkGid = @IfkGid);

        //Opschuiven van de regels
        update tabInkoopfactuurRegel
        set   IfrRegelNr = IfrRegelNr + 1
        where IfrIfkGid = @IfkGid
          and IfrRegelNr between @IfrRegelNr and @OpschuivenTotEnMet
        order by IfrRegelNr desc;
      end;
    end if;
  end if;

  //Zijn er nog geen regels? Dan ook in de inkoopfactuurkop wat gegevens zetten
  if @UpdateIFkop <> 0 then
    if not exists(select first 1 from tabInkoopfactuurRegel where IfrIfkGid = @IfkGid) then
      update tabinkoopfactuurkop
      set    IfkReferentienummer        = MohkFactuurnummer,
             IfkReferentienummer_Lengte = MohkFactuurnummer_Lengte
      from   tabinkoopfactuurkop
      inner join tabMagazijnontvangstHistRegel on MohrGid = @MohrGid
      inner join tabMagazijnontvangstHistKop on mohkGid = mohrMohkGid
      where IfkGid = @IfkGid;
    end if;
  end if;

  insert into tabInkoopfactuurRegel (
    IfrIfkGid,
    IfrRegelNr,
    IfrRegelSoort,
    IfrAantal,
    IfrAantalDecimalenVoorAantallen,
    IfrAantalDecimalenVoorPrijzen,
    IfrArtGid,
    IfrArtikelNummerLeverancier,
    IfrArtPartijGid,
    IfrBtwCode,
    IfrEANcode,
    IfrInkoopeenheid,
    IfrKortingBedrag,
    IfrKortingPercentage,
    IfrKortingSoort,
    IfrOms,
    IfrPrijs,
    IfrPrijsPer,
    IfrPrijsPerSoort,
    IfrReferentienummer,
    IfrReferentienummer_lengte,
    IfrRegeltotaalExclBtw,
    IfrTussenrekeningBedragInPrijsPer,
    IfrTussenrekeningPrijsPerAantal,
	IfrTussenrekeningValNummer,
    IfrVoorraadeenhedenInInkoopeenheid
  )
  select
    /*IfrIfkGid = */                          @IfkGid,
    /*IfrRegelNr = */                         @IfrRegelNr,
    /*IfrRegelSoort = */                      MohrRegelSoort,
    /*IfrAantal = */                          MohrAantalInkoopEenheden,
    /*IfrAantalDecimalenVoorAantallen = */    MohrAantDecAantal,
    /*IfrAantalDecimalenVoorPrijzen = */      MohrAantDecBedrag,
    /*IfrArtGid = */                          ArtGid,
    /*IfrArtikelNummerLeverancier = */        MohrArtCodeBijLeverancier,
    /*IfrArtPartijGid = */                    ArtPartijGid,
    /*IfrBtwCode = */
    if MohrInkoopprijs is not null then
      MohrBtwCode
    else
      if BstRglGid is not null then
        BstRglBtwCode
      else
        if (NawFilBtwCode is not null and LevBtw.BtwPercentage = 0) then
          LevBtw.BtwCode
        else
          if ArtSoort = 2 then
            ArtBtwCodeInkoop
          else
            ArtBtwCode
          endif
        endif
      endif
    endif,
    /*IfrEANcode = */                         MohrEanCode,
    /*IfrInkoopeenheid = */                   MohrInkoopEenheid,
    /*IfrKortingBedrag = */
    if MohrInkoopprijs is not null then
      if @ValutaNr <> MohkValNummer then
        ValutaOmrekenen(MohkValNummer, MohrKortingBedrag,  @ValutaNr, @BjGid, @Pernr, MohrAantDecBedrag)
      else
        MohrKortingBedrag
      endif
    else
      if BstRglGid is not null then
        if @ValutaNr <> BstKopValNummer then
          ValutaOmrekenen(BstKopValNummer, BstRglKortingBedrag, @ValutaNr, @BjGid, @Pernr, MohrAantDecBedrag)
        else
          BstRglKortingBedrag
        endif
      else
        A.Kortingbedrag
      endif
    endif,
    /*IfrKortingPercentage = */               if MohrInkoopprijs is not null then MohrKortingPercentage  else if BstRglGid is not null then BstRglKortingPercentage  else A.KortingPercentage endif endif,
    /*IfrKortingSoort = */                    if MohrInkoopprijs is not null then MohrKortingSoort       else if BstRglGid is not null then BstRglKortingSoort       else A.KortingSoort endif endif,
    /*IfrOms = */                             if BstRglGid is null then MohrArtOms else MohrBstlRglOms endif,
    /*IfrPrijs = */
    if MohrInkoopprijs is not null then
      if @ValutaNr <> MohkValNummer then
        ValutaOmrekenen(MohkValNummer, MohrInkoopprijs,  @ValutaNr, @BjGid, @Pernr, MohrAantDecBedrag)
      else
        MohrInkoopprijs
      endif
    else
      if BstRglGid is not null then
        if @ValutaNr <> BstKopValNummer then
          ValutaOmrekenen(BstKopValNummer, BstRglprijs, @ValutaNr, @BjGid, @Pernr, MohrAantDecBedrag)
        else
          BstRglprijs
        endif
      else
        A.Inkoopprijs
    endif
  endif,
    /*IfrPrijsPer = */                        if MohrInkoopprijs is not null then MohrPrijsPer       else if BstRglGid is not null then BstRglPrijsPer      else ArtPrijsPer   endif endif,
    /*IfrPrijsPerSoort = */                   if MohrInkoopprijs is not null then MohrInkoopprijsPer else if BstRglGid is not null then BstRglPrijsPerSoort else A.PrijsPerSoort endif endif,
    /*IfrReferentienummer = */                MohkFactuurnummer,
    /*IfrReferentienummer_lengte = */         MohkFactuurnummer_Lengte,
    /*IfrRegeltotaalExclBtw = */              0, /* Wordt in de trigger berekend*/
                                              // ACW 22-04-2024 Defect 59316: Als tussenrekening niet bij MagOnt geboekt, dan dat hier ook niet als 0 doorgeven (null: niet geboekt, 0: prijs van 0,00)
    /*IfrTussenrekeningBedragInPrijsPer = */  if MohrTussenrekeningTotaalGeboekt is not null then
                                                MohrTussenrekeningTotaalGeboekt / if (MohrAantalInkoopEenheden * MohrVoorraadEenhedenInInkoopEenheid) = 0 then 1 else (MohrAantalInkoopEenheden * MohrVoorraadEenhedenInInkoopEenheid) endif * MohrPrijsPer // Als tegen werkelijke inkoopprijs geboekt, dan is het prijsverschil al bij de mag.ontv. geboekt; hier NIET afronden!
                                              endif,
    /*IfrTussenrekeningPrijsPerAantal = */    MohrPrijsPer,
	/*IfrTussenrekeningValNummer = */		  MohkValNummer,
    /*IfrVoorraadeenhedenInInkoopeenheid = */ MohrVoorraadEenhedenInInkoopEenheid
  from
    tabMagazijnontvangstHistRegel

    //t.b.v. bepalen van leverancier
    inner join tabmagazijnontvangsthistkop on mohkgid=mohrmohkgid
    inner join tabMagazijnOntvangstHistAdres on mohagid=MohkMohaGidLeverancier
    inner join tabnawfile on nawfilnummer = mohanawfilnummer and nawfilfonid='C'
    left outer join tabBtw as LevBtw on LevBtw.BtwCode = NawFilBtwCode
    // t.b.v. bepalen artikel
    inner join tabartikel on artcode=mohrartcode and artsoort=mohrregelsoort
    // t.b.v. bepalen partij
    left outer join tabartikelpartij on artpartijartgid = artgid and artpartijnummer=MohrArtPartijNummer
    left outer join tabBestelKop on BstKopNummer = MohrBstKopNummer
    // NOTE DG Alleen prijs van de bestelling overnemen als de inkoopeenheid gelijk is!
    left outer join tabBestelRegel on BstKopGid  = BstRglBstKopGid and BstRglNummer = MohrBstRglNummer and MohrInkoopEenheid = BstRglInkoopEenheid
    // t.b.v. bepalen default inkoopprijs (als tegen VVP was geboekt) of Inkoopeenheid van bestelregel vs ontvangen komt niet overeen
    , BepaalInkoopprijs(artgid, artpartijgid, MohrArtOmsEenheid, MohrVoorraadEenhedenInInkoopEenheid, nawfilnawgid, @ValutaNr, MohrAantalInkoopEenheden, @FactuurDatum) A
  where
    MohrGid = @MohrGid;

  set @IsRegelToegevoegd = @@RowCount;

  //call TraceEind(@@ErrorTextProcedure + ' > @Result = ' + string(IsNull(@Result,0)));
  if @IsRegelToegevoegd = 0 then
    return null //Niks toegevoegd!
  else
    return @@Identity; //van de inkoopfactuurregel
  end if;
end;


create or replace procedure InkoopfactuurVulBedragenKop (in @IfkGid integer)
begin
  //call TraceBegin('InkoopfactuurVulBedragenKop(@IfkGid='+string(@IfkGid)+')');
  update tabInkoopFactuurKop
  set
    IfkFactuurbedragExclBTW = IsNull((select Sum(IfrRegeltotaalExclBtw) from tabInkoopFactuurregel where IfrIfkGid = IfkGid and IfrRegelSoort in (1,2)), 0),
    IfkTotaalBtw = IsNull((select Sum(IfbBtwBedrag) from tabInkoopfactuurBtwblok where IfbIfkGid = IfkGid), 0)
  where
    IfkGid  = @IfkGid;
  //call TraceEind('InkoopfactuurVulBedragenKop(@IfkGid='+string(@IfkGid)+')');
end;

//------- Script dat gedraait moet worden na inloggen
create or replace procedure InLoggen(in @MachineName nchar(20))
begin
  declare @Datum nchar(10);

  set @@ErrorTextProcedure = 'Inloggen > @MachineName='+@MachineName+', @@GebruikerCode='+@@GebruikerCode;
  //call TraceBegin(@@ErrorTextProcedure);

  set @@MachineName = @MachineName;
  call WriteLog(0, '');
  if exists (select 1 from tabRegistry where RegKey = 'DATUM_EERSTE_KEER_INGELOGD' and Contents = '') then
    update tabRegistry set Contents = DateFormat(now(), 'yyyy-mm-dd') where RegKey = 'DATUM_EERSTE_KEER_INGELOGD'
  end if;
  select Contents into @Datum from tabRegistry where RegKey = 'DATUM_LAATSTE_KEER_INGELOGD';
  if (DateFormat(now(), 'yyyy-mm-dd') > @Datum) or (@Datum = '') then
    update tabRegistry set Contents = DateFormat(now(), 'yyyy-mm-dd') where RegKey = 'DATUM_LAATSTE_KEER_INGELOGD';
  end if;

  // ACW 1-3-2004: Zonder module Artikelen, dan ook geen pakbon kunnen afdrukken
  if IsModuleActive('ar') <> 1 then
   update tabVasteGegevensOrdersFactureren
   set VofLeverenBijFactureren = 0,
       vofPakbonBijFactureren = 0,
       vofDirectIsLeverenBijDirecteFact = 0,
       vofDirectIsPakbonAfdrukkenBijLeveren = 0
  end if;

  //RVL : Onderstaande trace ALTIJD aan laten staan, wordt gebruikt om bij een uitleverset te automatisch te controleren of de Trace het wel doet,
  //      maar dat er voor de rest geen Trace-commando''s voorbij komen. Op verzoek van StH ingebouwd.
  call Trace('### Trace activated ###');

  set @@ErrorTextProcedure = 'Inloggen';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure InvullenVoorkeursLocatieVanuitMagOntvangst(
  in @MagOntGid integer default null
)
begin
  //Constanten
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  //Variabelen
  declare @_ArtGid integer default null;
  declare @_LocGid integer default null;
  declare @_MagGid integer default null;
  declare @_ArtMagGid integer default null;
  declare @_ArtMagDefaultLocGid integer default null;
  declare @_ArtMagLocGidVoorkeurOntvangst integer default null;
  declare @_MagVastOntvangstEersteLocWordtVoorkeurVoorPlaatsen smallint = _qcNEE;
  declare @_MagVastOntvangstEersteLocatieWordtVoorkeurslocatie smallint = _qcNEE;

  //call TraceBegin('InvullenVoorkeursLocatieVanuitMagOntvangst > @MagOntGid='+string(@MagOntGid));

  //De vaste gegevens
  select MagVastOntvangstEersteLocWordtVoorkeurVoorPlaatsen, MagVastOntvangstEersteLocatieWordtVoorkeurslocatie
  into @_MagVastOntvangstEersteLocWordtVoorkeurVoorPlaatsen, @_MagVastOntvangstEersteLocatieWordtVoorkeurslocatie
  from tabMagazijnOntvangstenVasteGegevens;

  if (@_MagVastOntvangstEersteLocWordtVoorkeurVoorPlaatsen = _qcJa) or (@_MagVastOntvangstEersteLocatieWordtVoorkeurslocatie= _qcJa) then
    //Haal de eerste locatie op van de regel en de defaults van het artikel
    select first MagOntArtGid, MagOntLocLocGid, MokMagGid, ArtMagGid, ArtMagDefaultLocGid, ArtMagLocGidVoorkeurOntvangst
    into @_ArtGid, @_LocGid, @_MagGid, @_ArtMagGid, @_ArtMagDefaultLocGid, @_ArtMagLocGidVoorkeurOntvangst
    from tabMagazijnOntvangstLocatieSerie
    inner join tabMagazijnOntvangstenDetail on (MagOntDetGid = MagOntLocMagOntDetGid)
    inner join tabMagazijnOntvangsten on (MagOntGid = MagOntDetMagOntGid)
    inner join tabMagazijnOntvangstenKop on MokGid = MagontMokGid
    inner join tabLocatie on LocGid = MagOntLocLocGid
    left outer join tabartikelmagazijn on ArtMagArtGid = MagOntArtGid and ArtMagMagGid = MokMagGid
    where MagOntDetMagOntGid = @MagOntGid
      and LocLocatietype in (3 /*Bulk*/, 4 /*Pick*/)
      //and @OrrGid is not null /*Alleen records die aan orders gekoppeld zijn selecteren tbv directe inkoop*/
    order by MagOntLocGid;

    if @_LocGid is not null then
      //Maak record aan in tabArtikelMagazijn als nog niet bestaat
      if (@_ArtMagGid is null) and
         ( ((@_ArtMagDefaultLocGid is null) and (@_MagVastOntvangstEersteLocatieWordtVoorkeurslocatie = _qcJA)) or
           ((@_ArtMagLocGidVoorkeurOntvangst is null) and (@_MagVastOntvangstEersteLocWordtVoorkeurVoorPlaatsen = _qcJA))
         ) then
         insert into tabartikelmagazijn (ArtMagArtgid, ArtMagMagGid) values (@_ArtGid, @_MagGid );
      end if;

      //Vullen als er geen defaultlocatie voor picken is
      if (@_ArtMagDefaultLocGid is null) and (@_MagVastOntvangstEersteLocatieWordtVoorkeurslocatie = _qcJA) then
        update tabartikelmagazijn
        set ArtMagDefaultLocGid = @_LocGid
        where ArtMagArtGid = @_ArtGid
          and ArtMagMagGid = @_MagGid;
      end if;

      //Vullen als er geen defaultlocatie voor plaatsen is
      if (@_ArtMagLocGidVoorkeurOntvangst is null) and (@_MagVastOntvangstEersteLocWordtVoorkeurVoorPlaatsen = _qcJA) then
        update tabartikelmagazijn
        set ArtMagLocGidVoorkeurOntvangst = @_LocGid
        where ArtMagArtGid = @_ArtGid
          and ArtMagMagGid = @_MagGid;
      end if;
    end if;
  end if;
  //call TraceEind('InvullenVoorkeursLocatieVanuitMagOntvangst');
end;


create or replace function Is1VanDeModulesActief(in @ModuleCodes nchar(20))
returns smallint

//@Modulecodes kunnen 1 of meedere modulecodes bevatten. Modulecodes worden gewoon achter elkaar geplakt zonder een scheidingdteken
//Voorbeeld @ModuleCodes='b1a3u1'
begin
  declare @ModuleCode nchar(2);
  declare @Active     smallint;
  declare @Teller     smallint;

  //call traceBegin('Is1VanDeModulesActief(@ModuleCodes='+@ModuleCodes+')');

  //Als 1 van de modules in modulestring staat, dan @IsActive = true
  set @Active = 0;
  set @Teller = 0;
  while @Teller*2 < length(trim(@ModuleCodes)) and @Active = 0 loop
    set @ModuleCode = substr(@ModuleCodes, @Teller*2+1, 2);
    if locate(@@ModuleCodes, ','+@ModuleCode+',') <> 0 then
      set @Active = 1
    end if;
    set @Teller = @Teller + 1;
  end loop;

  //call traceEind('Is1VanDeModulesActief ------> @Active='+string(@Active));
  return(@Active)
end;



//VvE 31-03-2017: Voor controles of artsoort niet fout is.
//Mogelijke response (zou eigenlijk boolean zijn, maar heb maar smallint stijl gevolgd)
// 0 - false, is geen aartikel
// 1 - true, is wel een artikel
//Mogelijk inputs:
// geef je null mee, krijg je ook 0, want null is ook geen artikel.
// geef je een onbestaande artgid mee, krijg je ook 0, want dat is geen artikel.
create or replace function IsArtGidEenArtikel(in @ArtGid integer)
returns smallint
begin
  declare @Resultaat    smallint;
  set @@ErrorTextProcedure = 'IsArtGidEenArtikel > @Artgid = ' + string(@Artgid);
  //call TraceBegin(@@ErrorTextProcedure);

  if @ArtGid is null then
    set @Resultaat = 0
  else
    if exists(select 1 from tabArtikel where Artgid = @Artgid and Artsoort = 2) then
      set @Resultaat = 1;
    else
      set @Resultaat = 0;
    end if;
  end if;

  set @@ErrorTextProcedure = 'IsArtGidEenArtikel > @Resultaat = ' + string(@Resultaat);
  //call TraceEind(@@ErrorTextProcedure);
  return @Resultaat;
end;

