create or replace function IsArtLevDefaultDirecteLevering(in @NawGid integer default null, in @ArtGid integer, in @InkoopEenheid nchar(40) ) returns smallint
begin
  declare @result smallint;

  set @@ErrorTextProcedure = 'IsArtLevDefaultDirecteLevering > @NawGid = ' + string(@NawGid) + ', @ArtGid = ' + string(@ArtGid)+ ', @InkoopEenheid = ' + string(@InkoopEenheid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @result = 0;

  if @NawGid is null then
    select ArtLevNawGid into @NawGid from tabArtikelLeverancier where ArtLevArtGid = @ArtGid and ArtLevIsDefault = 1;
    //call Trace('IsArtLevDefaultDirecteLevering > NawGid='+string(@NawGid));
  end if;

  if (select LevGegDirLevGeschikt from tabLeverancierGegevens where LevGegNawGid = @NawGid) = 0 or (select ArtBestellenVoorDirecteLevering from tabArtikel where ArtGid = @ArtGid) = 0 then
    set @result = 0;
    //call Trace('IsArtLevDefaultDirecteLevering > Lev of Art geen DL');
  else
    if (select first AldDirecteLevering from tabArtikelLeverancier inner join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid and ( (@InkoopEenheid <> '' and AldInkoopEenheid = @InkoopEenheid) or (@InkoopEenheid = '' and AldIsDefaultInkoopEenheidBijLev = 1) ) where ArtLevArtGid = @ArtGid) = 2 then
      set @result = 1;
      //call Trace('IsArtLevDefaultDirecteLevering > ArtikelLeveerancierDetail DL = JA');
    else
      set @result = 0;
      //call Trace('IsArtLevDefaultDirecteLevering > ArtikelLeveerancierDetail DL = NEE');
    end if;
  end if;

  set @@ErrorTextProcedure = 'IsArtLevDefaultDirecteLevering > @NawGid = ' + string(@NawGid) + ', @ArtGid = ' + string(@ArtGid)+ ', @InkoopEenheid = ' + string(@InkoopEenheid)+', @result = ' + string(@result);
  //call TraceEind(@@ErrorTextProcedure);

  return @result;
end;


// Controleer of de meegegeven string een geldige Nederlandse bankrekening kan zijn
//Regel:    (Rekening is IBAN EN begint met 'NL')
//       OF (   Landcode = 'NL'
//           EN rekening bevat alleen cijfers
//           EN (rekeninglengte<9 OF Rekening voldoet aan 11-proef)
//          )

if exists (select 1 from sys.sysProcedure where proc_name='IsBankrekeningNederlands') then
  drop function IsBankrekeningNederlands;
end if;

create or replace function IsBankrekeningNederlands(in @Rekening nchar(40), in @LndIso2 nchar(2))
returns smallint
begin
  declare @Resultaat    smallint;
  declare @Rek          nchar(35);

  set @@ErrorTextProcedure = 'IsBankrekeningNederlands  > '+string(@Rekening)+'|' + @LndIso2 + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @Resultaat = 0;

  //Probeer alvast de nederlandse rekening eruit te halen
  select GetRekeningnummerFromIBAN(@Rekening) into @Rek;
  if @Rek <> '' then
    set @Rekening = @Rek;
  end if;

  //en test vervolgens of die goed is
  if    (    (IsValidIBAN(@Rekening) = 1)
         and (Substr(@Rekening, 1, 2) = 'NL')
        )
     or (    ((isnull(@LndIso2, '') = 'NL' ) or (isnull(@lndIso2, '') = ''))
         and (IsNumeric(@Rekening) = 1)
         and (length(@Rekening)<9 or IsValidElfProef(@Rekening) = 1)
        ) then
    set @Resultaat = 1;
  end if;

  set @@ErrorTextProcedure = 'IsBankrekeningNederlands > '+string(@Rekening)+'|' + @LndIso2 +')='+string(@Resultaat);
  //call TraceEind (@@ErrorTextProcedure);

  return(@Resultaat)
end;

create or replace function IsBetaling(in @RksGid integer, in @IsCreditBoeking smallint)
returns smallint
begin
  declare @RksSoort smallint;
  declare @IsBetaling smallint;

  //call TraceBegin('IsBetaling > @RksGid = ' + string(@RksGid) + ', @IsCreditBoeking = ' + string(@IsCreditBoeking));

  select DefaultSoort into @RksSoort from tabRekeningschema where RksGid = @RksGid;

  if ((@RksSoort = 6) and (@IsCreditBoeking <> 0)) or ((@RksSoort = 7) and (@IsCreditBoeking <> 1)) then
    set @IsBetaling = 1;
  else
    set @IsBetaling = 0;
  end if;

  //call TraceEind('IsBetaling > @IsBetaling = ' + string(@IsBetaling));
  return (@IsBetaling);
end;


//$Workfile: IsBoekGangEnJpGelocked.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----- Wordt gebruikt in triggers om te testen of boekingsgang en journaalpost netjes gelocked of in gebruik zijn genomen
if exists (select 1 from sys.sysProcedure where proc_name='IsBoekGangEnJpGelocked') then
  drop function IsBoekGangEnJpGelocked;
end if;

create function IsBoekGangEnJpGelocked(in @BoekGangGid integer, in @JpGid integer)
returns integer
begin
  declare @IsGelocked integer;

  //call TraceBegin('IsBoekGangEnJpGelocked (@BoekGangGid='+string(@BoekGangGid)+', JpGid='+string(@JpGid)+')');

  select IsBoekGangGelocked(@BoekGangGid) into @IsGelocked;
  if @IsGelocked = 1 then
    if not exists (select 1 from tabJournaalPost where JpGid=@JpGid and JpIsInGebruik<>0) then
      call Raise(20035);
    end if;
  end if;

  //call TraceEind('IsBoekGangEnJpGelocked(@IsGelocked='+string(@IsGelocked)+')');
  return @IsGelocked;

end;


create or replace function IsBoekGangGelocked(in @BoekGangGid integer)
returns integer
begin
  declare @IsGelocked integer;

  //call TraceBegin('IsBoekGangGelocked > @BoekGangGid = ' + string(@BoekGangGid));

  //20040 : Test of boekingsgang is gelocked (door deze gebruiker)
  if LockedById(@@SpId, @@LoginTime, 1, 'tabBoekingsgang', 'BoekgangGid='+string(@BoekGangGid)) = 0 then
    call Raise(20040);
  else
    select 1 into @IsGelocked;
  end if;

  //call TraceEind('IsBoekGangGelocked > @IsGelocked = ' + string(@IsGelocked));
  return @IsGelocked;
end;


