//------------- Bepaal of boeking een factuur boeking is (debiteur debet of crediteur credit)
create or replace function IsFactuurBoeking(in @RksGid integer, in @IsCreditBoeking smallint)
returns smallint
begin
  declare @RksSoort smallint;
  declare @IsFactuurBoeking smallint;

  //call TraceBegin('IsFactuurBoeking > @RksGid = ' + string(@RksGid) + ', @IsCreditBoeking = ' + string(@IsCreditBoeking));

  select DefaultSoort into @RksSoort from tabRekeningschema where RksGid = @RksGid;

