//----------- Geeft aan de hand van een meegegeven tekst (de landcode) een 1 (gevonden)
//----------- of 0 (niet gevonden) aan of deze landcode gebruikt mag worden in ICL-aangiften.
//----------- Deze functie kan t.z.t. aangevuld worden met nieuwe lidstaten (zoals
create or replace function IsIclLandcodeOK(in @IclLandcode nchar(2), in @InclEigenLand smallint)
returns SmallInt
begin

  declare @Gevonden SmallInt;

  set @@ErrorTextProcedure = 'IsIclLandcodeOK > @IclLandcode='+string(@IclLandcode)+', @InclEigenLand='+string(@InclEigenLand);
  //call TraceBegin(@@ErrorTextProcedure);

  set @InclEigenLand = IsNull(@InclEigenLand, 0);

  if exists(select 1 from tabLand where LndIsEGLid = 1 and LndCodeEU = @IclLandcode and (@InclEigenLand = 1 or lndGid <> (select first DefaultLndGid from tabVasteGegevens))) then
    set @Gevonden = 1;
  else
    set @Gevonden = 0;
  end if;

  set @@ErrorTextProcedure = 'IsIclLandcodeOK > @IclLandcode='+string(@IclLandcode)+', @InclEigenLand='+string(@InclEigenLand)+', @Gevonden='+String(@Gevonden);
  //call TraceEind(@@ErrorTextProcedure);

  return(@Gevonden)

end;


create or replace function IsLeapYear(in @aYear integer)
returns integer
begin
  //TG 01-04-2009: Proc gebouwd ter ondersteuning van de ISO8601 datum/tijd standaard. Mede door deze DatePart bug in Sybase: http://case-express.sybase.com/cx/caseSheet.do?caseNumber=11519935

  declare @IsLeapYear smallint;

  //call TraceBegin('IsLeapYear > @aYear = ' + string(@aYear));

  set @IsLeapYear = if (Mod(@aYear, 4) = 0) and ((Mod(@aYear, 100) <> 0) or (Mod(@aYear, 400) = 0)) then 1 else 0 endif;

  //call TraceEind('IsLeapYear > @IsLeapYear = ' + string(@IsLeapYear));
  return (@IsLeapYear);
end;

create or replace function IsModuleActive(in @ModuleCode nchar(4))
returns smallint
begin
  declare @Active smallint;

  //call TraceBegin('IsModuleActive > @ModuleCode = ' + @ModuleCode);

  if @@OverruleUserRights = 1 and length(@ModuleCode) = 4 then
    set @Active = 1;
  else
    //Als de module in modulestring staat
    if locate(@@ModuleCodes, ','+@ModuleCode+',') <> 0 then
      set @Active = 1;
    else
      set @Active = 0;
    end if;
  end if;

  //call TraceEind('IsModuleActive > @Active='+string(@Active));
  return(@Active)

end;


//---------- Controleert of we de huidige staffelregel mogen opslaan ----------
create or replace procedure IsNawStaffelRegelAanmakenOk(
  in  @NstfRglGid        integer,
  in  @NieuweVanafWaarde numeric(15,3),
  in  @ControleType      smallint, //0=aanpassen, 1=tussenvoegen, 2=toevoegen
  out @RegelAanmakenOk   integer,
  out @FoutTekst         nchar(200))
begin
  declare @VorigeVanafWaarde     numeric(15,3);
  declare @VolgendeVanafWaarde   numeric(15,3);
  declare @NstfKopGid            integer;

  set @@ErrorTextProcedure = 'IsNawStaffelRegelAanmakenOk > @NstfRglGid = ' + string(@NstfRglGid) + ', @NieuweVanafWaarde = ' + string(@NieuweVanafWaarde) + ', @ControleType = ' + string(@ControleType);
  //call TraceBegin(@@ErrorTextProcedure);

  //default gaat het fout
  set @RegelAanmakenOk = 0;

  //KopGid van huidige regel bepalen
  select NstfRglNstfKopGid into @NstfKopGid from tabNawStaffelRegel where NstfRglGid = @NstfRglGid;

 //Bepalen vorige en volgende waarde per soort controle.
 case @ControleType
 when 0 then //aanpassen huidige regel
   //bepalen vorige waarde
   select   first NstfRglVanafAantal into @VorigeVanafWaarde
   from     tabNawstaffelregel
   where    NstfRglNstfKopGid = @NstfKopGid and NstfRglVanafAantal < (select NstfRglVanafAantal from tabNawStaffelRegel where NstfRglGid = @NstfRglGid)
   order by NstfRglVanafAantal Desc;

   //indien we de korting van de staffel-0 regel aanpassen, dan kan de VanafWaarde niet aangepast worden. Om foutmeldingen te voorkomen is zijn voorliggende waarde altijd -1.
   set @VorigeVanafWaarde = IsNull(@VorigeVanafWaarde, -1);

   //bepalen volgende waarde
   select   first NstfRglVanafAantal into @VolgendeVanafWaarde
   from     tabnawstaffelregel
   where    NstfRglNstfKopGid = @NstfKopGid and NstfRglVanafAantal > (select NstfRglVanafAantal from tabNawStaffelRegel where NstfRglGid = @NstfRglGid)
   order by NstfRglVanafAantal;

   //indien we de laatste regel aanpassen, dan is er geen volgende waarde en is @VolgendeVanafWaarde null. Derhalve maximale limiet instellen.
   set @VolgendeVanafWaarde = IsNull(@VolgendeVanafWaarde, 999999999999.999);

 when 1 then //tussenvoegen nieuwe regel
   //bepalen volgende waarde
   select   first NstfRglVanafAantal into @VolgendeVanafWaarde
   from     tabNawStaffelRegel
   where    NstfRglGid = @NstfRglGid;

   //bepalen vorige waarde
   select   first NstfRglVanafAantal into @VorigeVanafWaarde
   from     tabNawstaffelregel
   where    NstfRglNstfKopGid = @NstfKopGid and NstfRglVanafAantal < @VolgendeVanafWaarde
   order by NstfRglVanafAantal desc;

 when 2 then //toevoegen nieuwe regel
   //bepalen vorige waarde
   select   first NstfRglVanafAantal into @VorigeVanafWaarde
   from     tabNawStaffelRegel
   where    NstfRglNstfKopGid = @NstfKopGid
   order by NstfRglVanafAantal desc;
   //TG 17-06-2005: where + order by ter vervanging van onderstaande. nav bug #17230
   //where    StfRglGid = @StfRglGid;

   //indien de nieuwe waarde de laatste in de staffeltabel wordt, dan de maximale grenswaarde gebruiken als volgende waarde.
   set @VolgendeVanafWaarde = 999999999999.999;
 end case;

 //Als de waarde tussen de vorige en volgende past, dan is toevoegen toegestaan.
 //call trace('@NieuweVanafWaarde='+string(@NieuweVanafWaarde)+', @VorigeVanafWaarde='+string(@VorigeVanafWaarde)+', @VolgendeVanafWaarde='+string(@VolgendeVanafWaarde));
 if @NieuweVanafWaarde > @VorigeVanafWaarde and @NieuweVanafWaarde < @VolgendeVanafWaarde then
   set @RegelAanmakenOk = 1;
 //Controleren of ingevoerde waarde kleiner is dan de vorige waarde
 else if @NieuweVanafWaarde <= @VorigeVanafWaarde then
   set @FoutTekst = _U('Aantal is kleiner of gelijk aan het vorige aantal!');
 //Controleren of ingevoerde waarde groter is dan de vorige waarde
 else if @NieuweVanafWaarde >= @VorigeVanafWaarde then
   set @FoutTekst = _U('Aantal is groter of gelijk aan het volgende aantal!');
 end if; end if; end if;

  set @@ErrorTextProcedure = 'IsStaffelRegelAanmakenOk > @NstfRglGid = ' + string(@NstfRglGid) + ', @NieuweVanafWaarde = ' + string(@NieuweVanafWaarde)+ ', @ControleType = ' + string(@ControleType) + ', @RegelAanmakenOk = ' + string(@RegelAanmakenOk);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function ISODayOfTheYearToDateTime(in @aYear integer, in @aDay integer)
returns DateTime
//TG 01-04-2009: Proc gebouwd ter ondersteuning van de ISO8601 datum/tijd standaard. Mede door deze DatePart bug in Sybase: http://case-express.sybase.com/cx/caseSheet.do?caseNumber=11519935
begin
  declare @aDateTime DateTime;

  //call TraceBegin('ISODayOfTheYearToDateTime > @aYear = ' + string(@aYear)+', @aDay = ' + string(@aDay));

  set @aDateTime = DateAdd(day, @aDay - 1, YMD(@aYear, 1, 1));
  //TG 01-04-2009: Dit had ook zo gekund:
  //set @aDateTime = YMD(@aYear, 1, @aDay);

  //call TraceEind('ISODayOfTheYearToDateTime > @aDateTime = ' + string(@aDateTime));
  return (@aDateTime);
end;

create or replace function ISODayOfWeek(in @aDateTime DateTime)
 returns smallint
//TG 01-04-2009: Proc gebouwd ter ondersteuning van de ISO8601 datum/tijd standaard. Mede door deze DatePart bug in Sybase: http://case-express.sybase.com/cx/caseSheet.do?caseNumber=11519935

begin
  declare @ISODayOfWeek smallint;

  //call TraceBegin('ISODayOfWeek > @aDateTime = ' + string(@aDateTime));

  set @ISODayOfWeek = Mod((DoW(@aDateTime) + 5), 7) + 1;

  //TG 01-04-2009: het had ook simpeler gekund:
  //declare @tempDayOfWeek smallint;
  //set @tempDayOfWeek = DoW(@aDateTime);
  //if @tempDayOfWeek = 1 then
  //  set @ISODayOfWeek = 7
  //else
  //  set @ISODayOfWeek = @tempDayOfWeek - 1
  //end if;

  //call TraceEind('ISODayOfWeek > @ISODayOfWeek = ' + string(@ISODayOfWeek));
  return (@ISODayOfWeek);
end;

create or replace function ISOIsLongYear(in @aYear integer)
returns smallint
begin
  //TG 01-04-2009: Proc gebouwd ter ondersteuning van de ISO8601 datum/tijd standaard. Mede door deze DatePart bug in Sybase: http://case-express.sybase.com/cx/caseSheet.do?caseNumber=11519935
  declare @IsLongYear  smallint;
  declare @TempWeekday integer;

  //call TraceBegin('ISOIsLongYear > @aYear = ' + string(@aYear));

  set @TempWeekday = ISODayOfWeek(ISODayOfTheYearToDateTime(@aYear, 1));

  //vaststellen of een ISO jaar normaal (52 weken) of lang (53 weken) is
  set @IsLongYear = if ((IsLeapYear(@aYear) = 1) and ((@TempWeekday = 3) or (@TempWeekday = 4))) or (@TempWeekday = 4) then 1 else 0 endif;

  //call TraceEind('ISOIsLongYear > @IsLongYear = ' + string(@IsLongYear));
  return (@IsLongYear);
end;


create or replace function ISONumberOfWeeksInYear(in @aYear integer)
returns integer
begin
  //TG 01-04-2009: Proc gebouwd ter ondersteuning van de ISO8601 datum/tijd standaard. Mede door deze DatePart bug in Sybase: http://case-express.sybase.com/cx/caseSheet.do?caseNumber=11519935
  declare @WeeksInYear integer;

  //call TraceBegin('ISONumberOfWeeksInYear > @aYear = ' + string(@aYear));

  if ISOIsLongYear(@aYear) = 1 then
    set @WeeksInYear = 53
  else
    set @WeeksInYear = 52;
  end if;

  //call TraceEind('ISONumberOfWeeksInYear > @WeeksInYear = ' + string(@WeeksInYear));

  return (@WeeksInYear);
end;

create or replace function IsOrderSpecificatieregelActief()
returns smallint
begin
  declare @Active smallint = 0;

  set @@ErrorTextProcedure = 'IsOrderSpecificatieregelActief >';
  //call TraceBegin(@@ErrorTextProcedure);

  if (@@ModuleM1 = 1) or (@@ModuleP2 = 1) or (@@ModuleS1 = 1) then
    set @Active = 1;
  else
    if (locate(@@ModuleCodes, ',d2,') <> 0) then
      set @Active = 1;
    else
      if (locate(@@ModuleCodes, ',v6,') <> 0) then
        set @Active = 1;
      end if;
    end if;
  end if;

  set @@ErrorTextProcedure = 'IsOrderSpecificatieregelActief > @Active='+string(@Active);
  //call TraceEind(@@ErrorTextProcedure);

  return(@Active);
end;

//$Workfile: IsOspTeLaat.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//-------- Bepaald of Osp buiten de peildatum valt
if exists (select 1 from sys.sysProcedure where proc_name='IsOspTeLaat') then
  drop function IsOspTeLaat;
end if;

create function IsOspTeLaat(in @OspGid integer, in @PeilDatum date, in @SoortAanmaning smallint)
returns smallint
begin
  declare @TeLaat smallint;
  declare @VanAanmaningNummer smallint;
  declare @TotAanmaningNummer smallint;

  set @@ErrorTextProcedure = 'IsOspTeLaat > @OspGid='+string(@OspGid)+', @PeilDatum='+string(@PeilDatum)+' @SoortAanmaning='+string(@SoortAanmaning);
  //call TraceBegin(@@ErrorTextProcedure);

  if (@SoortAanmaning = 0) or (@SoortAanmaning = 6) then   //alle aanmaningen en rekeningoverzichten
    set @VanAanmaningNummer = 1;
    set @TotAanmaningNummer = 4;
  else
    set @VanAanmaningNummer = @SoortAanmaning;
    set @TotAanmaningNummer = @SoortAanmaning;
  end if;

  set @TeLaat = 0;
  select 1 into @TeLaat
  from   tabOpenstaandepost, tabAanmaning
  where  OspGid=@OspGid and
       ((OspAanmaningTeller+1=AanmNummer) or (OspAanmaningTeller=0 and OspSoortFactuur = 3 and AanmNummer = 5)) and
        (if @SoortAanmaning = 0 then
           @Peildatum
         else
           if (OspAanmaningTeller+1>=@VanAanmaningNummer and OspAanmaningTeller+1<=@TotAanmaningNummer) then
             if IsNull(OspAanmaningTeller,0) = 0 then   //Bij de eerste aanmaning uitgaan van vervaldatum, daarna uitgaan van datum laatste aanmaning
               OspVervalDatum + IsNull(AanmAfdrukkenNa, 0)
             else
               OspLaatsteAanmaning + IsNull(AanmAfdrukkenNa,0)
             endif
           else
             @PeilDatum+1
           endif
         endif <= @PeilDatum);

  set @@ErrorTextProcedure = 'IsOspTeLaat > @TeLaat='+string(@TeLaat);
  //call TraceEind(@@ErrorTextProcedure);
  return(@TeLaat);

end;


create or replace function ISOWeekOfYear(in @aDateTime DateTime)
returns integer
begin
  //TG 01-04-2009: Proc gebouwd ter ondersteuning van de ISO8601 datum/tijd standaard. Mede door deze DatePart bug in Sybase: http://case-express.sybase.com/cx/caseSheet.do?caseNumber=11519935
  declare @ISOWeekNumber       integer;
  declare @ISOYearOfWeekNumber integer;

  //call TraceBegin('ISOWeekOfYear > @aDateTime = ' + string(@aDateTime));

  call ISOWeekOfYearAndYearOfWeek(@aDateTime, @ISOWeekNumber, @ISOYearOfWeekNumber);

  //call TraceEind('ISOWeekOfYear > @ISOWeekNumber = ' + string(@ISOWeekNumber) + ', @ISOYearOfWeekNumber = ' + string(@ISOYearOfWeekNumber));
  return (@ISOWeekNumber);
end;


create or replace procedure ISOWeekOfYearAndYearOfWeek(in @aDateTime DateTime, out @ISOWeekNumber integer, out @ISOYearOfWeekNumber integer)
begin
  //TG 01-04-2009: Proc gebouwd ter ondersteuning van de ISO8601 datum/tijd standaard. Mede door deze DatePart bug in Sybase: http://case-express.sybase.com/cx/caseSheet.do?caseNumber=11519935
  declare @TempYear    Integer;
  declare @January4th  DateTime;
  declare @FirstMonday DateTime;

  //call TraceBegin('ISOWeekOfYearAndYearOfWeek > @aDateTime = ' + string(@aDateTime));

  set @tempYear = DatePart(year, @aDateTime);

  // Jaar aanpassen als de datum tussen 29/12 en 31/12 ligt
  if (DatePart(Month, @aDateTime) = 12) and (DatePart(day, @aDateTime) >= 29) and (ISODayOfWeek(@aDateTime) <= 3) then
    set @TempYear = @TempYear + 1;
  end if;

  set @January4th  = ISODayOfTheYearToDateTime(@TempYear, 4);
  set @FirstMonday = @January4th + 1 - ISODayOfWeek(@January4th);

  // Als de meegeven datum kleiner is dan de datum van de eerste maandag van het jaar dan zitten we in de laatste week van het vorige jaar
  if @aDateTime < @FirstMonday then
    set @ISOWeekNumber       = ISONumberOfWeeksInYear(@TempYear - 1);
    set @ISOYearOfWeekNumber = @TempYear - 1;
  else
    set @ISOYearOfWeekNumber = @TempYear;
    set @ISOWeekNumber       = (Floor(Floor(@aDateTime - @FirstMonday) / 7)) + 1;

    if @ISOWeekNumber > ISONumberOfWeeksInYear(Year(@aDateTime)) then
      set @ISOWeekNumber = ISONumberOfWeeksInYear(Year(@aDateTime));
    end if;
  end if;

  //call TraceEind('ISOWeekOfYearAndYearOfWeek > @ISOWeekNumber = ' + string(@ISOWeekNumber) + ', @ISOYearOfWeekNumber = ' + string(@ISOYearOfWeekNumber));
end;


if exists (select 1 from sys.sysProcedure where proc_name='ISOWeekYearToDateTime') then
  drop function ISOWeekYearToDateTime;
end if;


create function ISOWeekYearToDateTime(
in @aYear integer, //jaar
in @aWeek integer, //week
in @aDay integer)  //dag van de week [1..7]
returns DateTime
begin
  //hulpvariabelen
  declare @tmpDate     DateTime;
  declare @January4th  DateTime;
  declare @FirstMonday DateTime;

  //call TraceBegin('ISOWeekToDateTime(@aYear='+string(@aYear)+', @aWeek='+string(@aWeek)+', @aDay='+string(@aDay)+')');

  set @January4th  = isoDayOfTheYearToDateTime(@aYear, 4);
  set @FirstMonday = @January4th + 1 - ISODayOfWeek(@January4th);
  set @tmpDate     = @FirstMonday + (@aWeek - 1) * 7 + (@aDay - 1);

  //call TraceEind('ISOWeekYearToDateTime ------> @tmpDate='+string(@tmpDate));
  return (@tmpDate);
end;


create or replace function ISOYearOfWeek(in  @aDateTime DateTime)
returns integer
begin
  //TG 01-04-2009: Proc gebouwd ter ondersteuning van de ISO8601 datum/tijd standaard. Mede door deze DatePart bug in Sybase: http://case-express.sybase.com/cx/caseSheet.do?caseNumber=11519935
  declare @ISOWeekNumber       integer;
  declare @ISOYearOfWeekNumber integer;

  //call TraceBegin('ISOYearOfWeek > @aDateTime = ' + string(@aDateTime));

  call ISOWeekOfYearAndYearOfWeek(@aDateTime, @ISOWeekNumber, @ISOYearOfWeekNumber);

  //call TraceEind('ISOYearOfWeek > @ISOWeekNumber = ' + string(@ISOWeekNumber) + ', @ISOYearOfWeekNumber = ' + string(@ISOYearOfWeekNumber));
  return (@ISOYearOfWeekNumber);
end;

//---------- Controleert of we de huidige staffelregel mogen opslaan ----------
create or replace procedure IsStaffelRegelAanmakenOk(in @StfRglGid integer,
                                           in @NieuweVanafWaarde numeric(15,3),
                                           in @ControleType smallint, //0=aanpassen, 1=tussenvoegen, 2=toevoegen
                                           out @RegelAanmakenOk integer,
                                           out @FoutTekst nchar(200))
begin
  declare @VorigeVanafWaarde     numeric(15,3);
  declare @VolgendeVanafWaarde   numeric(15,3);
  declare @StfKopGid             integer;

 set @@ErrorTextProcedure = 'IsStaffelRegelAanmakenOk > @StfRglGid = ' + string(@StfRglGid) + ', @NieuweVanafWaarde = ' + string(@NieuweVanafWaarde) + ', @ControleType = ' + string(@ControleType);
  //call TraceBegin(@@ErrorTextProcedure);

  //default gaat het fout
  set @RegelAanmakenOk = 0;

  //KopGid van huidige regel bepalen
  select StfRglStfKopGid into @StfKopGid from tabStaffelRegel where StfRglGid = @StfRglGid;

 //Bepalen vorige en volgende waarde per soort controle.
 case @ControleType
 when 0 then //aanpassen huidige regel
   //bepalen vorige waarde
   select   first StfRglVanafAantal into @VorigeVanafWaarde
   from     tabstaffelregel
   where    StfRglStfKopGid = @StfKopGid and StfRglVanafAantal < (select StfRglVanafAantal from tabStaffelRegel where StfRglGid = @StfRglGid)
   order by StfRglVanafAantal Desc;

   //indien we de korting van de staffel-0 regel aanpassen, dan kan de VanafWaarde niet aangepast worden. Om foutmeldingen te voorkomen is zijn voorliggende waarde altijd -1.
   set @VorigeVanafWaarde = IsNull(@VorigeVanafWaarde, -1);

   //bepalen volgende waarde
   select   first StfRglVanafAantal into @VolgendeVanafWaarde
   from     tabstaffelregel
   where    StfRglStfKopGid = @StfKopGid and StfRglVanafAantal > (select StfRglVanafAantal from tabStaffelRegel where StfRglGid = @StfRglGid)
   order by StfRglVanafAantal;

   //indien we de laatste regel aanpassen, dan is er geen volgende waarde en is @VolgendeVanafWaarde null. Derhalve maximale limiet instellen.
   set @VolgendeVanafWaarde = IsNull(@VolgendeVanafWaarde, 999999999999.999);

 when 1 then //tussenvoegen nieuwe regel
   //bepalen volgende waarde
   select   first StfRglVanafAantal into @VolgendeVanafWaarde
   from     tabStaffelRegel
   where    StfRglGid = @StfRglGid;

   //bepalen vorige waarde
   select   first StfRglVanafAantal into @VorigeVanafWaarde
   from     tabstaffelregel
   where    StfRglStfKopGid = @StfKopGid and StfRglVanafAantal < @VolgendeVanafWaarde
   order by StfRglVanafAantal desc;

 when 2 then //toevoegen nieuwe regel
   //bepalen vorige waarde
   select   first StfRglVanafAantal into @VorigeVanafWaarde
   from     tabStaffelRegel
   where    StfRglStfKopGid = @StfKopGid
   order by StfRglVanafAantal desc;
   //TG 17-06-2005: where + order by ter vervanging van onderstaande. nav bug #17230
   //where    StfRglGid = @StfRglGid;

   //indien de nieuwe waarde de laatste in de staffeltabel wordt, dan de maximale grenswaarde gebruiken als volgende waarde.
   set @VolgendeVanafWaarde = 999999999999.999;
 end case;

 //Als de waarde tussen de vorige en volgende past, dan is toevoegen toegestaan.
 if @NieuweVanafWaarde > @VorigeVanafWaarde and @NieuweVanafWaarde < @VolgendeVanafWaarde then
   set @RegelAanmakenOk = 1;
 //Controleren of ingevoerde waarde kleiner is dan de vorige waarde
 else if @NieuweVanafWaarde <= @VorigeVanafWaarde then
   set @FoutTekst = _U('Aantal is kleiner of gelijk aan het vorige aantal!');
 //Controleren of ingevoerde waarde groter is dan de vorige waarde
 else if @NieuweVanafWaarde >= @VorigeVanafWaarde then
   set @FoutTekst = _U('Aantal is groter of gelijk aan het volgende aantal!');
 end if; end if; end if;

  set @@ErrorTextProcedure = 'IsStaffelRegelAanmakenOk > @StfRglGid = ' + string(@StfRglGid) + ', @NieuweVanafWaarde = ' + string(@NieuweVanafWaarde)+ ', @ControleType = ' + string(@ControleType) + ', @RegelAanmakenOk = ' + string(@RegelAanmakenOk);
  //call TraceEind(@@ErrorTextProcedure);

end;


//---------- Test of string bestaat uit alleen de meegegeven karakters
create or replace function IsStringOk (in @StringToCheck nchar(40), in @ValidChars nchar(40))
returns smallint
begin
  declare @teller smallint;
  declare @IsOk smallint;

  set @@ErrorTextProcedure = 'IsStringOk > @StringToCheck='+@StringToCheck+', @ValidChars='+@ValidChars;
  //call TraceBegin(@@ErrorTextProcedure);

  set @Teller = 1;
  set @IsOk = 1;
  while @Teller<=length(@StringToCheck) loop
    if locate(@ValidChars, substr(@StringToCheck,@teller,1))=0 then
      set @IsOk = 0;
    end if;
    set @Teller = @Teller + 1;
  end loop;
  set @@ErrorTextProcedure = 'IsStringOk > @IsOk='+string(@IsOk);
  //call TraceEind(@@ErrorTextProcedure);

  return(@IsOk);

end;


// Controleer of de meegegeven string een geldige 11-proef is
create or replace function IsValidElfProef(in @Rekening nchar(40))
returns smallint
begin
  declare @Resultaat smallint;
  declare @teller    smallint;
  declare @hulp      smallint;
  declare @Getal     integer;
  declare @lengte    smallint;

  set @@ErrorTextProcedure = 'IsValidElfProef  > '+string(@Rekening)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @Resultaat = 1;

  set @lengte = length(@Rekening);
  if @lengte < 9 or @lengte > 10 or IsNumeric(@Rekening) = 0 then
    set @Resultaat = 0;
  else
    set @Getal = 0;
    set @teller = 1;
    while     (@teller <= @lengte)
          and (@Resultaat = 1)
    LOOP
      set @hulp = ascii(substr(@Rekening, @teller, 1));
      if @hulp < 48 or @hulp > 57 then
        //Niet tussen 0 en 9
        set @Resultaat = 0;
      else
        set @Getal = @Getal + ((@hulp - 48) * ((@lengte + 1) - @teller));
      end if;
      set @teller = @teller + 1;
    end loop;

    if @Resultaat = 1 and (mod(@getal, 11)) <> 0 then
      set @resultaat = 0;
    end if;
  end if;

  set @@ErrorTextProcedure = 'IsValidElfProef > '+string(@Rekening)+')='+string(@Resultaat);
  //call TraceEind (@@ErrorTextProcedure);

  return(@Resultaat)


end;
// Onderstaande moet geldig zijn!!
// call IsValidIBAN('IT82E0616002840000008387C00');


// Controleer of de meegegeven string een geldige 11-proef is
create or replace function IsValidElfProefMetControleGetal(in @CijferReeks nchar(40))
returns smallint
begin
  declare @Resultaat smallint;
  declare @teller    smallint;
  declare @hulp      smallint;
  declare @Getal     integer;
  declare @lengte    smallint;

  set @@ErrorTextProcedure = 'IsValidElfProefMetControleGetal  > '+string(@CijferReeks)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @Resultaat = 1;

  set @lengte = length(@CijferReeks);
  if @lengte < 2 or IsNumeric(@CijferReeks) = 0 then
    set @Resultaat = 0;
  else
    set @Getal = 0;
    set @teller = 1;
    while     (@teller <= @lengte)
          and (@Resultaat = 1)
    LOOP
      set @hulp = ascii(substr(@CijferReeks, @teller, 1));
      if @hulp < 48 or @hulp > 57 then
        //Niet tussen 0 en 9
        set @Resultaat = 0;
      else
      set @Getal = @Getal + ((@hulp - 48) * ((@lengte + 1) - @teller)) * if @teller = @lengte then -1 else 1 endif;
      end if;
      set @teller = @teller + 1;
    end loop;

    if @Resultaat = 1 and (mod(@getal, 11)) <> 0 then
      set @resultaat = 0;
    end if;
  end if;

  set @@ErrorTextProcedure = 'IsValidElfProefMetControleGetal > '+string(@CijferReeks)+')='+string(@Resultaat);
  //call TraceEind (@@ErrorTextProcedure);

  return(@Resultaat)

end;


// Controleer of de meegegeven string een geldige IBAN is
create or replace function IsValidIBAN(in @Rekening nchar(40))
returns smallint
begin
  declare @Resultaat smallint;
  declare @teller    integer;
  declare @hulp      integer; // Hulpvariabele
  declare @NieuweRek nchar(100);

  set @@ErrorTextProcedure = 'IsValidIBAN  > '+string(@Rekening)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @Resultaat = 1;

  set @Rekening = upper(@Rekening);                                   // Zet om in hoofdletters
  set @Rekening = substr(@Rekening, 5, 36) + substr(@Rekening, 1, 4); // Zet de eerste 4 posities achteraan

  set @teller = 1;
  if length(@Rekening) <= 10 then
    set @Resultaat = 0;
  end if;

  // Dit gaat sneller dan een loop!
  set @NieuweRek = replace(@rekening , 'A', '10');
  set @NieuweRek = replace(@NieuweRek, 'B', '11');
  set @NieuweRek = replace(@NieuweRek, 'C', '12');
  set @NieuweRek = replace(@NieuweRek, 'D', '13');
  set @NieuweRek = replace(@NieuweRek, 'E', '14');
  set @NieuweRek = replace(@NieuweRek, 'F', '15');
  set @NieuweRek = replace(@NieuweRek, 'G', '16');
  set @NieuweRek = replace(@NieuweRek, 'H', '17');
  set @NieuweRek = replace(@NieuweRek, 'I', '18');
  set @NieuweRek = replace(@NieuweRek, 'J', '19');
  set @NieuweRek = replace(@NieuweRek, 'K', '20');
  set @NieuweRek = replace(@NieuweRek, 'L', '21');
  set @NieuweRek = replace(@NieuweRek, 'M', '22');
  set @NieuweRek = replace(@NieuweRek, 'N', '23');
  set @NieuweRek = replace(@NieuweRek, 'O', '24');
  set @NieuweRek = replace(@NieuweRek, 'P', '25');
  set @NieuweRek = replace(@NieuweRek, 'Q', '26');
  set @NieuweRek = replace(@NieuweRek, 'R', '27');
  set @NieuweRek = replace(@NieuweRek, 'S', '28');
  set @NieuweRek = replace(@NieuweRek, 'T', '29');
  set @NieuweRek = replace(@NieuweRek, 'U', '30');
  set @NieuweRek = replace(@NieuweRek, 'V', '31');
  set @NieuweRek = replace(@NieuweRek, 'W', '32');
  set @NieuweRek = replace(@NieuweRek, 'X', '33');
  set @NieuweRek = replace(@NieuweRek, 'Y', '34');
  set @NieuweRek = replace(@NieuweRek, 'Z', '35');
  set @Resultaat = IsNumeric(@NieuweRek);

  if @Resultaat = 1 then
    // Nog steeds ok, dus nu de controles berekenen
    // ACW 23-01-2012 Precision=30, dus met meer cijfers eerst de lengte wat aanpassen (deels alvast de modulo bepalen en inkorten)
    if length(@NieuweRek) > 30 then
      set @teller = (length(@NieuweRek) / 2) * 2-2;
      while @teller > 0
      LOOP
        // Linker cijfers modulo 97 geconverteerd naar string (van 2 lang) weer in de string terugplaatsen
        set @NieuweRek = string(mod(convert(numeric(40,0), left(@NieuweRek, length(@NieuweRek)-@teller)), 97)) +
                        substr(@NieuweRek,length(@NieuweRek) - @teller + 1, @teller);
        // Niet meer converteren dan wat nodig is
        if length(@NieuweRek) <= 30 then
          set @teller = 0;
        else
          set @teller = @teller - 2;
        end if;
      end loop;
    end if;

    // Het resultaat moet rest 1 geven op de modulo 97
    if mod(convert(numeric(40,0), @NieuweRek), 97) <> 1 then
      set  @resultaat = 0;
    end if;
  end if;

  set @@ErrorTextProcedure = 'IsValidIBAN > '+string(@Rekening)+')='+string(@Resultaat);
  //call TraceEind (@@ErrorTextProcedure);

  return(@Resultaat)


end;
// Onderstaande moet geldig zijn!!
