// select IsValidIBAN('MT84MALT011000012345MTLCAST001S');
// select isvalidiban('NL15DEUT0265172608');


// ------------ Test of er in een bepaalde tekst alleen karakters voorkomen die in de meegegeven karakterset zitten -------------------
create or replace function IsValidString(in @Tekst nchar(255), in @ValidCharacterSet nchar(50))
returns smallint
begin
  declare @IsValid smallint;
  declare @Teller  integer;

  set @@ErrorTextProcedure = 'IsValidString > @Tekst = '+@Tekst+', @ValidCharacterSet = ' +@ValidCharacterSet;
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsValid = 1;
  set @Teller  = 1;
  while @Teller <= length(@Tekst) and @IsValid = 1 loop
    if locate(@ValidCharacterSet, substring(@Tekst, @Teller, 1)) = 0 then
      set @IsValid = 0;
    end if;
    set @Teller = @Teller + 1;
  end loop;

  set @@ErrorTextProcedure = 'IsValidString > @IsValid = '+string(@IsValid);
  //call TraceBegin(@@ErrorTextProcedure);

  return(@IsValid);
end;

create or replace function IsWerkdag(in @Date datetime, in @LndGid integer)
returns smallint //0 = Geen werkdag, 1 = Wel werkdag
begin
  declare @IsWerkdag smallint;
  set @@ErrorTextProcedure = 'IsWerkdag > @Date= ' + string(@Date)+', @LndGid= ' + string(@LndGid);
  //call TraceBegin(@@ErrorTextProcedure);
  set @IsWerkdag = if DATEPART(dw, @Date) in (1,7) then 0 else 1 endif;
  /*
  //Controleer of het op een feestdag valt
  if @IsWerkdag = 1 then
    if Exists(SELECT 1 FROM Holidays WHERE Holiday = @Date) then
      set @IsWerkdag = 0
    end if;
  end if;
  */

  set @@ErrorTextProcedure = @@ErrorTextProcedure + ' -> ' + string(@IsWerkdag);
  //call TraceEind(@@ErrorTextProcedure);
  return(@IsWerkdag);
end;


//------------ Geef een 'Ja' of 'Nee' terug
create or replace function JaNee(in @IsJa smallint)
returns nchar(3)
begin

  //call TraceBegin ('JaNee (@IsJa='+string(@IsJa)+')');

  //call TraceEind ('JaNee');
  if @IsJa=0 then
    return _U('Nee');
  elseif @IsJa=1 then
    return _U('Ja');
  else
    return '<>';
  end if;


end;


create or replace procedure JournaalOmschrijvingUpdate(in @JrGid integer, in @JpOms nchar(40), in @JrOms nchar(40))
begin

  //call TraceBegin('JournaalOmschrijvingUpdate(@JrGid = '+string(@JrGid)+', @JpOms='+@JpOms+', @JrOms='+@JrOms+')');

