  update tabJournaalPost  set OmsJournaalPost  = @JpOms from tabJournaalRegel where JrJpGid = JpGid and JrGid = @JrGid;
  update tabJournaalRegel set OmsJournaalRegel = @JrOms where JrGid = @JrGid;
  set @@FiredByTriggerJournaalregel = 0;
  set @@FiredByTriggerJournaalPost  = 0;
  set @@OverRuleLock                = 0;

  //call TraceEind('JournaalOmschrijvingUpdate');

end;


