create or replace procedure JournaalpostIsSaldoNul (in @JpGid integer, out @IsSaldoNul smallint, out @Saldo numeric(15,2), out @ValCode nchar(3))
begin
  declare @ValNummer integer;

  set @@ErrorTextProcedure = 'JournaalpostIsSaldoNul > ';
  //call TraceBegin(@@ErrorTextProcedure + '@JpGid = ' + string(@JpGid));

  select RksValNummer, ValCode into @ValNummer, @ValCode
  from   tabRekeningschema, tabJournaalpost, tabDagboek, tabValuta
  where  JpGid=@JpGid and JpDgbGid=DgbGid and DgbTegenRksGid=RksGid and ValNummer=RksValNummer;

  select sum(if JrValNummer = @Valnummer then if IsCreditBoeking = 0 then IsNull(JrValutaBedrag,0) else 0 endif else ValutaOmrekenen(JrValNummer, if IsCreditBoeking =0 then IsNull(JrValutaBedrag,0) else 0 endif, @ValNummer, JrBjGid, JrPerNr, 2 ) endif+
             if HulpRekValNummer is null then 0 else if HulpRekValNummer = @ValNummer then if IsNull(HulpRekisCredit,0) =0 then IsNull(HulpRekValutaBedrag,0) else 0 endif else ValutaOmrekenen(HulpRekValNummer, if IsNull(HulpRekisCredit,0) =0 then IsNull(HulpRekValutaBedrag,0) else 0 endif, @ValNummer, JrBjGid, JrPerNr, 2) endif endif) -
         sum(if JrValNummer = @Valnummer then if IsCreditBoeking<>0  then IsNull(JrValutaBedrag,0) else 0 endif else ValutaOmrekenen(JrValNummer, if IsCreditBoeking<>0 then IsNull(JrValutaBedrag,0) else 0 endif, @ValNummer, JrBjGid, JrPerNr, 2) endif +
             if HulpRekValNummer is null then 0 else if HulpRekValNummer = @ValNummer then if IsNull(HulpRekisCredit,0)<>0 then IsNull(HulpRekValutaBedrag,0) else 0 endif else ValutaOmrekenen(HulpRekValNummer, if IsNull(HulpRekisCredit,0)<>0 then IsNull(HulpRekValutaBedrag,0) else 0 endif, @ValNummer, JrBjGid, JrPerNr, 2) endif endif) into @Saldo
  from   tabJournaalregel left outer join tabHulprekening on (JrGid=HulpRekJrGid)
  where  JrJpGid=@JpGid;

  if IsNull(@Saldo,0) = 0 then
    set @IsSaldoNul = 1;
    set @Saldo      = 0;
  else
    set @IsSaldoNul = 0;
  end if;

  set @@ErrorTextProcedure = 'JournaalpostIsSaldoNul';
  //call TraceEind(@@ErrorTextProcedure + ' > @IsSaldoNul = ' + string(@IsSaldoNul) + ', @Saldo = ' + string(@Saldo) + ', @ValCode = ' + @Valcode);
end;


create or replace procedure JournaalpostOpenenOfSluiten(in @WordGeopend smallint, in @BjGid integer, in @BoekgangGid integer, in @JpGid integer, in @JpNummer integer, in @DgbGid integer)
begin
  declare @IsolationLevel smallint;
  declare @IsDefinitief   smallint;

  //call TraceBegin('JournaalpostOpenenOfSluiten > @WordGeopend = ' + string(@WordGeopend)+ ', @JpGid = ' + string(@JpGid));

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  select IsBoekGangDefinitief into @IsDefinitief
  from   tabBoekingsgang where BoekGangGid = @BoekGangGid;

  //Bij het openen werken we eerst de rekeningsaldi bij, alvorens de journaalregels te verwijderen.
  if @WordGeopend = 1 then
    call JournaalRegelsSaldiBijwerken(@WordGeopend, @JpGid, @IsDefinitief);
  end if;

  call OpenstaandePostenBijwerken(@WordGeopend, @JpGid, @IsDefinitief);
  call BoekingHulpRekening(@WordGeopend, @JpGid);
  call BoekingOpTegenRekening(@WordGeopend, @JpGid, @DgbGid);
  if (select Contents from tabRegistry where RegKey = 'HERWAARDERING_UITSCHAKELEN') <> '1' then
    if (IsNull(@@GeenKoersCorrectie,0) = 0) or (@WordGeopend = 1) then
      call KoersCorrectieBoekingen(@WordGeopend, @BjGid, @BoekGangGid, @JpGid, @JpNummer);
    end if;
  end if;

  //Bij het sluiten werken we de rekeningsaldi pas bij, nadat alle journaalregels zijn aangemaakt.
  if @WordGeopend = 0 then
    call JournaalRegelsSaldiBijwerken(@WordGeopend, @JpGid, @IsDefinitief);
  end if;

  if @@Isolation = 1 then // ACW 4=snapshot, dan dus niet locken!
    execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;
  end if;

  //call TraceEind('JournaalpostOpenenOfSluiten');
end;


create or replace procedure JournaalpostTussenvoegen(in @BoekgangGid integer, in @JpNummer integer, in @OokBoekStuknummers smallint)
begin
  set @@ErrorTextProcedure = 'JournaalpostTussenvoegen > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @JpNummer = ' + string(@JpNummer) + ', @OokBoekStuknummers = ' + string(@OokBoekStuknummers));

  set temporary option fire_triggers = 'off';
  if @OokBoekStuknummers<>0 then
    update tabJournaalpost set BoekStukNummer = BoekStukNummer + 1, JpNummer = JpNummer + 1 where JpNummer >= @JpNummer and JpBoekGangGid = @BoekGangGid order by JpNummer desc;
    update tabJournaalRegel set JrBoekStukNummer = JrBoekStukNummer + 1 where JrJpGid = New_Record.JpGid;
  else
    update tabJournaalpost set JpNummer = JpNummer + 1 where JpNummer >= @JpNummer and JpBoekGangGid = @BoekGangGid order by JpNummer desc;
  end if;
  set temporary option fire_triggers = 'on';

  set @@ErrorTextProcedure = 'JournaalpostTussenvoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


