create or replace procedure JournaalRegelNummersBijwerkenInBoekingsgang(in @BjGid integer, in @BoekGangGid integer)
begin
  declare @MaxJournaalRegelNummer integer;

  set @@ErrorTextProcedure = 'JournaalRegelNummersBijwerkenInBoekingsgang > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BjGid = ' + string(@BjGid) + ', @BoekGangGid = ' + string(@BoekGangGid));

  set temporary option fire_triggers = 'off';

  //Bepaal het hoogst uitgegeven regelnummer in het meegegeven boekjaar
  select IsNull(Max(RegelNummer),0) into @MaxJournaalRegelNummer from tabJournaalRegel where JrBjGid = @BjGid;

  update tabJournaalRegel set RegelNummer = @MaxJournaalRegelNummer + number()
  from   tabJournaalPost
  where  JpBoekGangGid = @BoekGangGid and JrJpGid = JpGid and RegelNummer is null order by JpNummer, JrNummer;

  set temporary option fire_triggers = 'on';

  set @@ErrorTextProcedure = 'JournaalRegelNummersBijwerkenInBoekingsgang';
  //call TraceEind(@@ErrorTextProcedure);
end;

//---------- Zoek factuurdatum, vervaldatum etc. op in huidige journaalpost of evt. openstaande posten
create or replace procedure JournaalRegelOspGegevens( in @BjGid integer, in @JpGid integer, in @ExJrGid integer, in @RksGid integer, in @FactuurNummer nchar(40), out @FactuurDatum Date,
                                           out @VervalDatum Date, out @BetalingsKenmerk nchar(24), out @IsViaIncasso integer,
                                           out @Valnummer integer, out @OpenstaandInclVoorl numeric(15,2), out @OpenstaandInclDef numeric(15,2),
                                           out @KredietbeperkingsBedrag numeric(15,2), out @KredietBeperkingsDatum date,
                                           out @KredietBeperkingsRksGid integer,
                                           out @IsGevonden smallint, out @SoortFactuur smallint, out @OspIsGeblokkeerd smallint,
                                           out @OspMeldingGeven smallint, out @OspGid integer, out @OspOms nchar(40), out @OspOpmerking long nvarchar)
begin
  declare @IsDefinitief smallint;
  declare @HulpBjGid integer;

  set @@ErrorTextProcedure = 'JournaalRegelOspGegevens > @JpGid='+string(@JpGid)+', @RksGid='+string(@RksGid)+', @FactuurNummer='+@FactuurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if @ExJrGid is not null then
    if exists(select 1 from tabJournaalregel where JrRksGid = @RksGid and JrReferentie = @FactuurNummer and JrReferentie_Lengte = Length(@FactuurNummer) and JrGid <> @ExJrGid) then
      set @IsGevonden = 1;
    else
      set @IsGevonden = 0;
    end if;
  else
    set @IsGevonden = 1;
  end if;
  if @IsGevonden = 1 then
    if @JpGid is null then
      set @HulpBjGid = @BjGid;
    else
      select IsBoekgangDefinitief, BoekGangBjGid into @IsDefinitief, @HulpBjGid from tabBoekingsgang inner join tabJournaalpost on (JpGid = @JpGid and JpBoekGangGid = BoekGangGid);
    end if;
    if (@JpGid is not null) and exists(select 1 from tabJournaalRegel where JrJpGid=@JpGid and JrRksGid=@RksGid and JrReferentie=@FactuurNummer and JrReferentie_Lengte = Length(@FactuurNummer)) then
       select first
              JrFactuurDatum,
              JrVervalDatum,
              JrBetalingsKenmerk,
              JrIsViaIncasso,
              JrValnummer,
              IsNull(OspFactuurBedragVoorlopig,0) - IsNull(OspBetaaldBedragVoorlopig,0) +   (select IsNull(sum(if ( a.IsCreditBoeking = 0 and RksA.DefaultSoort = 6 ) or ( a.IsCreditBoeking = 1 and RksA.DefaultSoort = 7 ) then a.JrValutaBedrag else -a.JrValutaBedrag endif),0) from tabJournaalRegel a inner join tabRekeningSchema rksA on (rksA.RksGid = a.JrRksGid) where a.JrJpGid=@JpGid and a.JrGid<>IsNull(@ExJrGid,0) and a.JrRksGid = @RksGid and a.JrReferentie = @FactuurNummer and a.JrReferentie_Lengte = Length(@FactuurNummer) and @IsDefinitief = 0),
              IsNull(OspFactuurBedragDefinitief,0) - IsNull(OspBetaaldBedragDefinitief,0) + (select IsNull(sum(if ( a.IsCreditBoeking = 0 and RksA.DefaultSoort = 6 ) or ( a.IsCreditBoeking = 1 and RksA.DefaultSoort = 7 ) then a.JrValutaBedrag else -a.JrValutaBedrag endif),0) from tabJournaalRegel a inner join tabRekeningSchema rksA on (rksA.RksGid = a.JrRksGid) where a.JrJpGid=@JpGid and a.JrGid<>IsNull(@ExJrGid,0) and a.JrRksGid = @RksGid and a.JrReferentie = @FactuurNummer and a.JrReferentie_Lengte = Length(@FactuurNummer) and @IsDefinitief <> 0),
              if OspSoortFactuur=1 or OspSoortFactuur=2 then IsNull(OspKredietbeperkingsBedrag,0) else 0 endif,
              OspKredietBeperkingsDatum,
              OspKredietBeperkingsRksGid,
              OspSoortFactuur,
              OspIsGeblokkeerd,
              OspMeldingGeven,
              OspGid,
              OspOms,
              OspOpmerking
       into   @FactuurDatum, @Vervaldatum, @BetalingsKenmerk, @IsViaIncasso, @ValNummer, @OpenstaandInclVoorl,
              @OpenstaandInclDef, @KredietbeperkingsBedrag, @KredietBeperkingsDatum, @KredietBeperkingsRksGid,
              @SoortFactuur, @OspIsGeblokkeerd, @OspMeldingGeven, @OspGid, @OspOms, @OspOpmerking
       from   tabJournaalRegel inner join tabOpenstaandePost on (OspGid = JrOspGid)
       where  JrJpGid = @JpGid and JrRksGid=@RksGid and JrReferentie=@FactuurNummer and JrReferentie_Lengte = Length(@FactuurNummer) order by JrTimeStamp desc;
    else
      if exists(select 1 from tabOpenstaandePost where OspBjGid = @HulpBjGid and OspRksGid=@RksGid and OspFactuurNummer=@FactuurNummer and OspFactuurNummer_Lengte=Length(@FactuurNummer)) then
        select OspFactuurDatum,
               OspVervalDatum,
               OspBetalingsKenmerk,
               0, //was OspIsViaIncasso maar veld is vervallen,
               OspValnummer,
               IsNull(OspFactuurBedragVoorlopig,0) - IsNull(OspBetaaldBedragVoorlopig,0),
               IsNull(OspFactuurBedragDefinitief,0) - IsNull(OspBetaaldBedragDefinitief,0),
               if OspSoortFactuur=1 or OspSoortFactuur=2 then IsNull(OspKredietbeperkingsBedrag, 0) else 0 endif,
               OspKredietBeperkingsDatum ,
               OspKredietBeperkingsRksGid ,
               OspSoortFactuur,
               OspIsGeblokkeerd,
               OspMeldingGeven,
               OspGid,
               OspOms,
               OspOpmerking
        into   @FactuurDatum, @Vervaldatum, @BetalingsKenmerk, @IsViaIncasso, @ValNummer, @OpenstaandInclVoorl,
               @OpenstaandInclDef, @KredietbeperkingsBedrag, @KredietBeperkingsDatum, @KredietBeperkingsRksGid,
               @SoortFactuur, @OspIsGeblokkeerd, @OspMeldingGeven, @OspGid, @OspOms, @OspOpmerking
        from   tabOpenstaandePost
        where  OspBjGid = @HulpBjGid and OspRksGid=@RksGid and OspFactuurNummer=@FactuurNummer and OspFactuurNummer_Lengte=Length(@FactuurNummer);
      else
        set @IsGevonden = 0;
      end if;
    end if;
  end if;
  if @IsGevonden = 0 then
    select BoekDatum into @FactuurDatum from tabJournaalPost where JpGid=@JpGid;
  end if;

  set @@ErrorTextProcedure = 'JournaalRegelOspGegevens > @FactuurDatum='+string(@FactuurDatum)+', @VervalDatum='+string(@VervalDatum)+', @BetalingsKenmerk='+@BetalingsKenmerk+', @IsViaIncasso='+string(@IsViaIncasso);
  //call TraceEind(@@ErrorTextProcedure);

end;


//---------- Doorloop de Journaalregels binnen een journaalpost en update de rekeningsaldi
create or replace procedure JournaalRegelsSaldiBijwerken(in @WordGeopend smallint, in @JpGid integer, in @IsDefinitief smallint)
begin
  //call TraceBegin('JournaalRegelsSaldiBijwerken > @WordGeopend = ' + string(@WordGeopend) + ', @JpGid = ' + string(@JpGid) + ', @IsDefinitief = ' + string(@IsDefinitief));

  for @Cursor AS Cursor_tabJournaal CURSOR FOR
    select JrGid @JrGid, JrJpGid @GelezenJpGid, JrBjGid @BjGid, JrPernr @JrPernr, JrPerGid @JrPerGid, JrRksGid @Rekening, JrValNummer @Valuta, JrBasisBedrag @BasisBedrag, JrValutaBedrag @ValutaBedrag, IsCreditBoeking @IsCredit, Aantal @Aantal
    from   tabJournaalregel
    where  (JrJpGid=@JpGid)
    union all
    select JrGid @JrGid, JpGid @GelezenJpGid, JrBjGid @BjGid, JrPernr @JrPernr, JrPerGid @JrPerGid, JrRksGid @Rekening, JrValNummer @Valuta, JrBasisBedrag @BasisBedrag, JrValutaBedrag @ValutaBedrag, IsCreditBoeking @IsCredit, Aantal @Aantal
    from   tabJournaalpost inner join tabJournaalregel on (JrJpGid = JpGid)
    where  (OrigineelJpId=@JpGid)
    order by 6
  for read only
  do

    //call Trace('JournaalRegelsSaldiBijwerken > Update rekeningsaldo');
    if @WordGeopend = 1 then
      call RekeningSaldoUpdate (@JrGid, @BjGid, @JrPerGid, @JrPernr, @Valuta, @Rekening, @IsDefinitief, @IsCredit, -@BasisBedrag, -@ValutaBedrag, -@Aantal)
    else
      call RekeningSaldoUpdate (@JrGid, @BjGid, @JrPerGid, @JrPernr, @Valuta, @Rekening, @IsDefinitief, @IsCredit,  @BasisBedrag,  @ValutaBedrag,  @Aantal);
    end if;
  end for;

  //call TraceEind('JournaalRegelsSaldiBijwerken');
end;


//$Workfile: JournaalregelTussenvoegen.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='JournaalregelTussenvoegen') then
  drop procedure JournaalregelTussenvoegen;
end if;

create procedure JournaalregelTussenvoegen( in @JpGid integer, in @JrNummer integer)
begin
  set @@ErrorTextProcedure = 'JournaalregelTussenvoegen > @JpGid='+string(@JpGid)+', @JrNummer='+string(@JrNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  set @@OverRuleLock=1;

  update tabJournaalregel set JrNummer = JrNummer + 1, StukVolgnr = StukVolgnr  + 1
  where  JrNummer >= @JrNummer and JrJpGid = @JpGid order by JrNummer desc;

  set @@OverRuleLock=0;

  set @@ErrorTextProcedure = 'JournaalregelTussenvoegen';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure JournaalregelVolgnummersVerlagen(in @JpGid integer, in @JrNummer integer)
begin
  //call TraceBegin('JournaalregelVolgnummersVerlagen > @JpGid = ' + string(@JpGid) + ', @JrNummer = ' + string(@JrNummer));

  update tabJournaalregel set JrNummer = JrNummer - 1, StukVolgnr = (if StukVolgnr >= 1 then StukVolgnr  - 1 else StukVolgnr endif)
  where  JrNummer >= @JrNummer and JrJpGid = @JpGid order by JrNummer;

  //call TraceEind('JournaalregelVolgnummersVerlagen');

end;


create or replace procedure KingMobile_UpdatePickorderStatus(out @VerwerkteOrders long varchar, out @NietGevondenOrders long varchar, out @GelockteOrders long varchar,
                                                             out @OrdersZonderControle long varchar)
//------------------------------------------------------------------------------
//-----Updaten pickorderstatus in order / factuurhistorie / uitleverhistorie----
//------------------------------------------------------------------------------
begin
  declare @frefGid                        integer;
  declare @OrkGid                         integer;
  declare @qLockGid                       integer;
  declare @LockResult                     smallint;
  declare @OrderIsInDezeProcedureGelocked smallint;
  declare @HistorieGevondenEnBijgewerkt   smallint;

  set @@ErrorTextProcedure = 'KingMobile_UpdatePickorderStatus >';
  //call TraceBegin(@@ErrorTextProcedure);

  set @VerwerkteOrders      = '';
  set @NietGevondenOrders   = '';
  set @GelockteOrders       = '';
  set @OrdersZonderControle = '';

  for @Cursor AS Cursor_PickOrderStatus CURSOR FOR
    select
      KmPosOrdernummer                    @KmPosOrdernummer,
      KmPosGeimporteerdOp                 @KmPosGeimporteerdOp,
      KmPosGecontroleerdDoorHandcomputer  @KmPosGecontroleerdDoorHandcomputer,
      KmPosGecontroleerdDoorMedewerker    @KmPosGecontroleerdDoorMedewerker,
      KmPosGecontroleerdOp                @KmPosGecontroleerdOp,
      KmPosGepicktDoorHandcomputer        @KmPosGepicktDoorHandcomputer,
      KmPosGepicktDoorMedewerker          @KmPosGepicktDoorMedewerker,
      KmPosGepicktOp                      @KmPosGepicktOp,
      KmPosIsGelockt                      @KmPosIsGelockt,
      KmPosHandcomputer                   @KmPosHandcomputer,
      KmPosHeeftAfwijkingInControle       @KmPosHeeftAfwijkingInControle,
      KmPosInBehandelingTerControleOp     @KmPosInBehandelingTerControleOp,
      KmPosInBehandelingVanaf             @KmPosInBehandelingVanaf,
      KmPosIsAanvulOrder                  @KmPosIsAanvulOrder,
      KmPosLocatieAanvulOrder             @KmPosLocatieAanvulOrder,
      KmPosPickorderstatus                @KmPosPickorderstatus,
      KmPosToegewezenOp                   @KmPosToegewezenOp,
      KmPosToegewezenTerControleOp        @KmPosToegewezenTerControleOp
    from
      tmp_KingMobile_PickOrderStatus
    order by
      KmPosGid
  for read only
  do
    set @HistorieGevondenEnBijgewerkt = 0;

    //@KmPosPickorderstatus = 0, pickorder wordt verwijderd
    //@KmPosPickorderstatus = 1, pickorder is zojuist geimporteerd
    //In beide gevallen kan er geen gebruik worden gemaakt van "@KmPosGeimporteerdOp" om order te zoeken
    //In het geval van 0 of 1 gaan we sowieso al niet zoeken in de uitleverhistorie
    if @KmPosPickorderstatus > 5 then
      update     tabFactuurReferentie
      set        FrefKMGecontroleerdDoorHandcomputer = @KmPosGecontroleerdDoorHandcomputer,
                 FrefKMGecontroleerdDoorMedewerker   = @KmPosGecontroleerdDoorMedewerker,
                 FrefKMGecontroleerdOp               = @KmPosGecontroleerdOp,
                 FrefKMGepicktDoorHandcomputer       = @KmPosGepicktDoorHandcomputer,
                 FrefKMGepicktDoorMedewerker         = @KmPosGepicktDoorMedewerker,
                 FrefKMGepicktOp                     = @KmPosGepicktOp,
                 FrefKMHandcomputer                  = @KmPosHandcomputer,
                 FrefKMHeeftAfwijkingInControle      = @KmPosHeeftAfwijkingInControle,
                 FrefKMInBehandelingTerControleOp    = @KmPosInBehandelingTerControleOp,
                 FrefKMInBehandelingVanaf            = @KmPosInBehandelingVanaf,
                 FrefKMIsAanvulOrder                 = @KmPosIsAanvulOrder,
                 FrefKMLocatieAanvulOrder            = @KmPosLocatieAanvulOrder,
                 FrefKMPickorderStatus               = @KmPosPickorderstatus,
                 FrefKMToegewezenOp                  = @KmPosToegewezenOp,
                 FrefKMToegewezenTerControleOp       = @KmPosToegewezenTerControleOp,
                 FrefKMGeimporteerdOp                = @KmPosGeimporteerdOp
      from       tabFactuurBatch
      inner join tabFactuurKop on (fkFbGid = FbGid)
      where      fbSoortBatch in (30, 35) and frefFkGid = FkGid and frefOrderNummer = @KmPosOrdernummer and FrefKMGeimporteerdOp = @KmPosGeimporteerdOp;

      if @@rowcount > 0 then
        set @HistorieGevondenEnBijgewerkt = 1;
      end if;
    end if;

    if @HistorieGevondenEnBijgewerkt = 1 then
      if @KmPosPickorderstatus = 9 then
        if not exists(select 1 from tmp_KingMobile_PickOrderControle where KmPocOrdernummer = @KmPosOrdernummer and KmPocGeimporteerdOp = @KmPosGeimporteerdOp) then
          set @OrdersZonderControle = @OrdersZonderControle + string(@KmPosOrdernummer) + ',';
        else
          update     tabFactuurRegel
          set        FrKMAantalGecontroleerd = IsNull((select KmPocAantalGecontroleerd from tmp_KingMobile_PickOrderControle where KmPocOrdernummer = @KmPosOrdernummer and KmPocGeimporteerdOp = @KmPosGeimporteerdOp and KmPocOrderRegelNr = frRegelNummer), FrKMAantalGecontroleerd)
          from       tabFactuurBatch
          inner join tabFactuurKop on (fkFbGid = FbGid)
          inner join tabFactuurReferentie on (frefFkGid = FkGid)
          where      fbSoortBatch in (30, 35) and frFrefGid = FrefGid and frefOrderNummer = @KmPosOrdernummer and FrefKMGeimporteerdOp = @KmPosGeimporteerdOp;
        end if;
      end if;

      if not exists(select 1 from tabOrderKop where OrkNummer = @KmPosOrdernummer and OrkKMGeimporteerdOp = @KmPosGeimporteerdOp) then
        set @VerwerkteOrders = @VerwerkteOrders + string(@KmPosOrdernummer) + ',';
      end if;

    end if;
    set @OrkGid = null;
    set @OrderIsInDezeProcedureGelocked = 0;
    select OrkGid into @OrkGid from tabOrderKop where OrkNummer = @KmPosOrdernummer and (OrkKMGeimporteerdOp = @KmPosGeimporteerdOp or @KmPosPickorderstatus <= 1); //0 of 1 betekent dat we niet kunnen testen op @KmPosGeimporteerdOp
    if @OrkGid is null then
      set @NietGevondenOrders = @NietGevondenOrders + string(@KmPosOrdernummer) + ',';
    else
      if @KmPosIsGelockt = 0 then
        call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @LockResult, 0);
        set @qLockGid = @@Identity;
        if @LockResult <> 0 then
          set @GelockteOrders = @GelockteOrders + string(@KmPosOrdernummer) + ',';  //Order is in gebruik!
        else
          set @OrderIsInDezeProcedureGelocked = 1;
        end if;
      end if;

      if (@KmPosIsGelockt = 1) or (@OrderIsInDezeProcedureGelocked = 1) then
        update     tabOrderKop
        set        OrkKMGecontroleerdDoorHandcomputer = @KmPosGecontroleerdDoorHandcomputer,
                   OrkKMGecontroleerdDoorMedewerker   = @KmPosGecontroleerdDoorMedewerker,
                   OrkKMGecontroleerdOp               = @KmPosGecontroleerdOp,
                   OrkKMGepicktDoorHandcomputer       = @KmPosGepicktDoorHandcomputer,
                   OrkKMGepicktDoorMedewerker         = @KmPosGepicktDoorMedewerker,
                   OrkKMGepicktOp                     = @KmPosGepicktOp,
                   OrkKMHandcomputer                  = @KmPosHandcomputer,
                   OrkKMHeeftAfwijkingInControle      = @KmPosHeeftAfwijkingInControle,
                   OrkKMInBehandelingTerControleOp    = @KmPosInBehandelingTerControleOp,
                   OrkKMInBehandelingVanaf            = @KmPosInBehandelingVanaf,
                   OrkKMIsAanvulOrder                 = @KmPosIsAanvulOrder,
                   OrkKMLocatieAanvulOrder            = @KmPosLocatieAanvulOrder,
                   OrkKMPickorderStatus               = @KmPosPickorderstatus,
                   OrkKMToegewezenOp                  = @KmPosToegewezenOp,
                   OrkKMToegewezenTerControleOp       = @KmPosToegewezenTerControleOp,
                   OrkKMGeimporteerdOp                = @KmPosGeimporteerdOp
        where OrkGid = @OrkGid;

        if @KmPosPickorderstatus = 9 then
          if not exists(select 1 from tmp_KingMobile_PickOrderControle where KmPocOrdernummer = @KmPosOrdernummer and KmPocGeimporteerdOp = @KmPosGeimporteerdOp) then
            set @OrdersZonderControle = @OrdersZonderControle + string(@KmPosOrdernummer) + ',';
          else
            update tabOrderRegel
            set    OrrKMAantalGecontroleerd = IsNull((select KmPocAantalGecontroleerd from tmp_KingMobile_PickOrderControle where KmPocOrdernummer = @KmPosOrdernummer and KmPocGeimporteerdOp = @KmPosGeimporteerdOp and KmPocOrderRegelNr = OrrRegelnr), OrrKMAantalGecontroleerd)
            from   tabOrderKop where OrrOrkGid = @OrkGid;
          end if;
        end if;

        //Lock vrijgeven als deze door deze stored proc is gezet
        if @OrderIsInDezeProcedureGelocked = 1 then
          delete qtabLock where qLockGid = @qLockGid;
          set @OrderIsInDezeProcedureGelocked = 0;
        end if;

        //Het kan zijn dat het ordernummer al op een eerder moment in @VerwerkteOrders is gezet, dan niet nogmaals erin zetten
        if locate(@VerwerkteOrders, string(@KmPosOrdernummer) + ',') = 0 then
          set @VerwerkteOrders = @VerwerkteOrders + string(@KmPosOrdernummer) + ',';
        end if;

      end if;

    end if;

  end for;

  //Nu nog beide tabellen leeg gooien
  delete tmp_KingMobile_PickOrderStatus;
  delete tmp_KingMobile_PickOrderControle;

  set @@ErrorTextProcedure = 'KingMobile_UpdatePickorderStatus';
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure KoersCorrectieBoekingen(in @WordGeopend smallint, in @BjGid integer, in @BoekGangGid integer, in @JpGid integer, @JpNummer integer)
begin
  declare @HuidigeKoers numeric(15,6);
  declare @JrValutaBedrag numeric(15,2);
  declare @Boekstuknummer numeric(10,0);
  declare @Boekdatum date;
  declare @DgbGid integer;
  declare @Periode integer;
  declare @VorigePeriode integer;
  declare @NewJpGid integer;
  declare @ValCode nchar(3);
  declare @Oms nchar(40);
  declare @NieuwBedrag numeric(15,2);
  declare @OudBedrag numeric(15,2);
  declare @teller integer; //ACW 31-01-2001 Tussenvoegen van journaalposten nu op de juiste locatie

  //call TraceBegin('KoersCorrectieBoekingen > @WordGeopend = ' + string(@WordGeopend) + ', @JpGid = ' + string(@JpGid));

  if @WordGeopend = 0 then
  begin
    declare @KoersCorrectieTekst long nvarchar;
    declare @KoersCorrTekst      long nvarchar;

    set @KoersCorrectieTekst = _A('Koerscorrectie');
    set @KoersCorrTekst      = _A('Koerscorr.');

    select DgbGidValuta into @DgbGid from tabVasteGegevens;
    //Genereer boekstuknummer
    call BoekstuknummerGenereren(@BjGid, @DgbGid, @BoekStukNummer);

    //Als boekstuknummer niet wordt gegenereerd volgens dagboek instelling, dan maar forceren
    if IsNull(@BoekStukNummer,0)=0 then
      call BoekstuknummerPlusEen (@BjGid, @DgbGid, 1, @BoekstukNummer);
    end if;


    for @Cursor AS CURSOR_Journaal NO SCROLL cursor for
      select distinct JrRksGid @RksGid, IsCreditBoeking @IsCredit, JrValNummer @ValNummer, KoersVerschilRksGid @KoersVerschilRksGid, JrRksInvoer @JrRksInvoer, JrPerGid @JrPerGid, JrPernr @JrPernr
      from     tabJournaalregel
               inner join tabRekeningschema on (RksGid = JrRksGid)
               inner join tabValuta on (ValNummer = JrValNummer)
      where    JrJpGid = @JpGid and JrValNummer <> @@BasisValutaNummer and (not DefaultSoort in (3,4,5))
      order by @ValNummer desc, @JrRksInvoer desc // Desc omdat de posten geinverteerd erin worden gezet!
    for read only
    do
      //Loop in journaalregels die een rekening hebben die niet in een voorgaande regel staat en aan dezelfde boekzijde (want die is al verwerkt)

      //call Trace('KoersCorrectieBoekingen > @RksGid = ' + string(@RksGid) + ', @IsCredit = ' + string(@IsCredit ) + ', @JpGid = ' + string(@JpGid ) + ', @ValNummer = ' + string(@ValNummer));
      select sum(JrValutaBedrag) into @JrValutaBedrag
      from   tabJournaalregel
      where  JrRksGid = @RksGid and IsCreditBoeking = @IsCredit and JrJpGid=@JpGid and JrValNummer = @ValNummer and JrPerGid = @JrPerGid;

      if @@TijdelijkeKoersen = 1 then
        select HlpKrsKoers into @HuidigeKoers from tabHulpKoers where HlpKrsValNummer=@ValNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@JrPerNr;
      else
        select Koers into @HuidigeKoers from tabValutaKoers where KrsValNummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@JrPerNr;
      end if;
      //call Trace('@BjGid='+string(@BjGid)+', @ValNummer='+string(@ValNummer)+', @HuidigeKoers='+string(@HuidigeKoers));
      //call Trace('Bedrag bepalen; @RksGid='+string(@RksGid)+', @IsCredit='+string(@IsCredit )+', @JpGid='+string(@JpGid )+', @ValNummer='+string(@ValNummer));

      set @Periode = @JrPernr;
      set @teller = 1;
      loopje2:
      loop
        set @VorigePeriode = @Periode;
        set @Periode = null;
        if @@TijdelijkeKoersen = 1 then
          select min(HlpKrsPernr) into @Periode from tabHulpKoers where HlpKrsValNummer=@ValNummer and HlpKrsBjGid=@BjGid and @HuidigeKoers<>HlpKrsKoers and HlpKrsPernr>@VorigePeriode;
        else
          select min(ValPernr) into @Periode from tabValutaKoers where KrsValNummer=@ValNummer and ValBjGid=@BjGid and @HuidigeKoers<>Koers and ValPernr>@VorigePeriode;
        end if;

        //call Trace('@BjGid='+string(@BjGid)+', @Periode='+string(@Periode));
        if @Periode is null then
          leave loopje2;
        end if;
        //ACW Defect #44918: Niet de einddatum van de volgende periode, maar de begindatum daarvan voor de correcieboeking
//        select EindDatum into @Boekdatum from tabPeriode where Pernr=@Periode and PerBjGid=@BjGid;
        select BeginDatum into @Boekdatum from tabPeriode where Pernr=@Periode and PerBjGid=@BjGid;
        //call Trace('In 2e lus, @Periode='+string(@Periode)+' @Boekdatum='+string(@Boekdatum));

        //We willen dat de volgende journaalpost een Jpnummer krijgt dat direct na de originele Jp ligt
        //if exists(select 1 from tabJournaalpost where JpBoekGangGid = @BoekGangGid and JpNummer = @JpNummer+@teller) then
        //  call JournaalpostTussenvoegen(@BoekgangGid, @JpNummer+@teller, 0);
        //end if;
        insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum, OrigineelJpId)
        select @BoekGangGid, 1, @DgbGid, @Boekstuknummer, @KoersCorrectieTekst, @Boekdatum, @JpGid;
        set @NewJpGid=@@Identity;

        // ACW 27-05-2004: Als basisvaluta = euro, dan de koers t.o.v. euro ipv. inverse koers doorgeven
        if @@tijdelijkeKoersen = 1 then
          select @KoersCorrTekst + ' ' + @ValCode+' : '+NumToStr(if @@BasisValutaNummer = @@EuroValutaNummer then HlpKrsKoersTovEuro else HlpKrsKoers endif, 6)+' -> ' into @Oms
          from   tabHulpKoers Oud
          where  HlpKrsBjGid=@BjGid and HlpKrsPernr=@Periode-1 and HlpKrsValNummer=@ValNummer;

          select @Oms+NumToStr(if @@BasisValutaNummer = @@EuroValutaNummer then HlpKrsKoersTovEuro else HlpKrsKoers endif, 6) into @Oms
          from   tabHulpKoers
          where  HlpKrsBjGid=@BjGid and HlpKrsPernr=@Periode and HlpKrsValNummer=@ValNummer;
        else
          select @KoersCorrTekst + ' ' + @ValCode+' : '+NumToStr(if @@BasisValutaNummer = @@EuroValutaNummer then KrsKoersTovEuro else Koers endif, 6)+' -> ' into @Oms
          from   tabValutaKoers Oud
          where  ValBjGid=@BjGid and ValPernr=@Periode-1 and KrsValNummer=@ValNummer;

          select @Oms+NumToStr(if @@BasisValutaNummer = @@EuroValutaNummer then KrsKoersTovEuro else Koers endif, 6) into @Oms
          from   tabValutaKoers
          where  ValBjGid=@BjGid and ValPernr=@Periode and KrsValNummer=@ValNummer;
        end if;
        select if @JrValutaBedrag = 0 then 0 else ValutaOmrekenen(@ValNummer, @JrValutaBedrag, @@BasisValutaNummer, @BjGid, @Periode - 1, 2) endif into @OudBedrag;
        select if @JrValutaBedrag = 0 then 0 else ValutaOmrekenen(@ValNummer, @JrValutaBedrag, @@BasisValutaNummer, @BjGid, @Periode, 2) endif     into @NieuwBedrag;
        //call Trace('@OudBedrag='+string(@OudBedrag)+', @NieuwBedrag='+string(@NieuwBedrag));

        insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, IsCreditBoeking, SoortBoeking, JrValNummer, OmsJournaalRegel, Aantal, JrBetalingsKenmerk, JrExternId, JrIsViaIncasso, JrNummer) select @NewJpGid, @RksGid, -@JrValutaBedrag,   -@OudBedrag, @IsCredit, 4, @ValNummer, @Oms, 0, '', '', 0, 0;
        insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, IsCreditBoeking, SoortBoeking, JrValNummer, OmsJournaalRegel, Aantal, JrBetalingsKenmerk, JrExternId, JrIsViaIncasso, JrNummer) select @NewJpGid, @RksGid,  @JrValutaBedrag,  @NieuwBedrag, @IsCredit, 4, @ValNummer, @Oms, 0, '', '', 0, 0;
        insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, IsCreditBoeking, SoortBoeking, JrValNummer, OmsJournaalRegel, Aantal, JrBetalingsKenmerk, JrExternId, JrIsViaIncasso, JrNummer) select @NewJpGid, @KoersVerschilRksGid,  @OudBedrag-@NieuwBedrag, @OudBedrag-@NieuwBedrag,  @IsCredit, 4, @@BasisValutaNummer, @Oms, 0, '', '', 0, 0;

        //Afsluiten van de correctie-journaalpost. In trigger wordt op OrigineelJpId getest
        update tabJournaalPost set JpIsIngebruik = 0 where JpGid = @NewJpGid;

        if @@TijdelijkeKoersen = 1 then
          select HlpKrsKoers into @HuidigeKoers from tabHulpKoers where HlpKrsValNummer=@ValNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Periode;
        else
          select Koers into @HuidigeKoers from tabValutaKoers where KrsValNummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Periode;
        end if;

        if @BoekStukNummer <> 9999999999 then
          set @BoekstukNummer = @BoekstukNummer + 1
        end if;

        set @teller = @teller + 1;

      end loop loopje2;


    end for;
  end
  else
//    delete tabJournaalregel from tabJournaalpost where (JrJpGid=@JpGid or OrigineelJpId=@JpGid) and JrJpGid=Jpgid and SoortBoeking=4;
    //ACW 2008-08-12 bug 28933: Deze regels NIET weggooien bij openen omdat na afsluiten dit bedrag plotseling op de tegenrekening zou worden geboekt
    //delete tabJournaalregel where JrJpGid=@JpGid and SoortBoeking=4;
    delete tabJournaalregel from tabJournaalpost where OrigineelJpId=@JpGid and JrJpGid=Jpgid and SoortBoeking=4;

    delete tabJournaalpost where OrigineelJpId=@JpGid;  //Koerscorrectiejournaalpost bij openen altijd weggooien
  end if;

  //call TraceEind('KoersCorrectieBoekingen');
end;


//$Workfile: KoersTovBasisValuta.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----------- Geef de koers van een valuta in een bepaalde periode (wordt altijd omgerekend per 1), rekeninghoudend met evt. Euro
if exists (select 1 from sys.sysProcedure where proc_name='KoersTovBasisValuta') then
  drop function KoersTovBasisValuta;
end if;

create function KoersTovBasisValuta (in @BjGid integer, in @Pernr integer, in @ValNummer integer)
returns numeric(15,6)
begin
  declare @Koers numeric(15,6);
  declare @VanKoers numeric(15,6);
  declare @NaarKoers numeric(15,6);

  set @@ErrorTextProcedure = 'KoersTovBasisValuta > @BjGid='+string(@BjGid)+', @Pernr='+string(@Pernr)+', @ValNummer='+string(@ValNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if @ValNummer = @@BasisValutaNummer then
    set @Koers = 1;
  else
    if @@EuroValutaNummer is not null then
      select KrsKoersTovEuro into @VanKoers from tabValutaKoers where KrsValnummer=@@BasisValutaNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
      if IsNull(@VanKoers, 0) <> 0 then
        select KrsKoersTovEuro into @NaarKoers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
      end if;
      if IsNull(@VanKoers,0) <> 0 and IsNull(@NaarKoers,0) <> 0 then      //Eurokoersen
        set @Koers = @VanKoers / @NaarKoers ;
      else
        select Koers/KrsEenheid into @Koers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
      end if
    else
      select   Koers/KrsEenheid into @Koers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
    end if;
  end if;

  set @@ErrorTextProcedure = 'KoersTovBasisValuta > @Koers='+string(@Koers);
  //call TraceEind(@@ErrorTextProcedure);
  Return(@Koers);

end;


//$Workfile: KoersTovBasisValutaDouble.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='KoersTovBasisValutaDouble') then
