end if;

create function KoersTovBasisValutaDouble (in @BjGid integer, in @Pernr integer, in @ValNummer integer)
returns double
begin
  declare @Koers double;
  declare @VanKoers double;
  declare @NaarKoers double;

  //call TraceBegin ('KoersTovBasisValutaDouble (@BjGid='+string(@BjGid)+', @Pernr='+string(@Pernr)+', @ValNummer='+string(@ValNummer)+')');

  if @ValNummer = @@BasisValutaNummer then
    set @Koers = 1;
  else
    if @@EuroValutaNummer is not null then
      select KrsKoersTovEuro into @VanKoers from tabValutaKoers where KrsValnummer=@@BasisValutaNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
      if IsNull(@VanKoers, 0) <> 0 then
        select KrsKoersTovEuro into @NaarKoers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
      end if;
      if IsNull(@VanKoers,0) <> 0 and IsNull(@NaarKoers,0) <> 0 then      //Eurokoersen
        set @Koers = @VanKoers / @NaarKoers ;
      else
        select Koers/KrsEenheid into @Koers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
      end if
    else
      select   Koers/KrsEenheid into @Koers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
    end if;
  end if;

  //call TraceEind ('KoersTovBasisValutaDouble ------> @Koers='+string(@Koers));

  Return(@Koers);

end;


//$Workfile: KoersTovBasisValutaMetTijdelijkeKoersen.sp $ $Revision: 3 $ $Modtime: 12-08-08 13:39 $'

// Let op: Deze routine is OUD. In plaats hiervan KoersTovBasisValutaMetTijdelijkeKoersenDouble gebruiken!

if exists (select 1 from sys.sysProcedure where proc_name='KoersTovBasisValutaMetTijdelijkeKoersen') then
  drop function KoersTovBasisValutaMetTijdelijkeKoersen;
end if;

create function KoersTovBasisValutaMetTijdelijkeKoersen (in @BjGid integer, in @Pernr integer, in @ValNummer integer)
returns numeric(15,6)
begin
  declare @Koers numeric(15,6);
  declare @VanKoers numeric(15,6);
  declare @NaarKoers numeric(15,6);

  set @@ErrorTextProcedure = 'KoersTovBasisValutaMetTijdelijkeKoersen > @BjGid='+string(@BjGid)+', @Pernr='+string(@Pernr)+', @ValNummer='+string(@ValNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if @ValNummer = @@BasisValutaNummer then
    set @Koers = 1;
  else
    if isnull(@@TijdelijkeKoersen,0)=0 then
      set @koers = KoersTovBasisValuta(@BjGid, @PerNr, @ValNummer);
    else
      if @@EuroValutaNummer is not null then
        select HlpKrsKoersTovEuro into @VanKoers from tabHulpKoers where HlpKrsValnummer=@@BasisValutaNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Pernr;
        if isnull(@VanKoers,0)=0 then
          select KrsKoersTovEuro into @VanKoers from tabValutaKoers where KrsValnummer=@@BasisValutaNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
        end if;
        if IsNull(@VanKoers, 0) <> 0 then
          select HlpKrsKoersTovEuro into @NaarKoers from tabHulpKoers where HlpKrsValnummer=@ValNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Pernr;
          if IsNull(@NaarKoers, 0) = 0 then
            select KrsKoersTovEuro into @NaarKoers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
          end if;
        end if;
        if IsNull(@VanKoers,0) <> 0 and IsNull(@NaarKoers,0) <> 0 then      //Eurokoersen
          set @Koers = @VanKoers / @NaarKoers ;
        else
          select HlpKrsKoers/HlpKrsEenheid into @Koers from tabHulpKoers where HlpKrsValnummer=@ValNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Pernr;
          if isnull(@koers,0)=0 then
            select Koers/KrsEenheid into @Koers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
          end if;
        end if
      else
        select   HlpKrsKoers/HlpKrsEenheid into @Koers from tabHulpKoers where HlpKrsValnummer=@ValNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Pernr;
        if isnull(@koers,0) = 0 then
          select   Koers/KrsEenheid into @Koers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
        end if;
      end if;
    end if;
  end if;

  set @@ErrorTextProcedure = 'KoersTovBasisValutaMetTijdelijkeKoersen > @Koers='+string(@Koers);
  //call TraceEind(@@ErrorTextProcedure);
  Return(@Koers);

end;


create or replace function KoersTovBasisValutaMetTijdelijkeKoersenDouble (in @BjGid integer, in @Pernr integer, in @ValNummer integer)
returns double
begin
  // ACW 27-05-2004: Koers als double teruggeven ipv. afgerond als numeric(15,6)
  declare @Koers     double;
  declare @VanKoers  double;
  declare @NaarKoers double;

  //call TraceBegin('KoersTovBasisValutaMetTijdelijkeKoersenDouble > @BjGid = ' + string(@BjGid) + ', @Pernr = ' + string(@Pernr) + ', @ValNummer = ' + string(@ValNummer));

  if @ValNummer = @@BasisValutaNummer then
    set @Koers = 1;
  else
    if isnull(@@TijdelijkeKoersen,0)=0 then
      set @koers = KoersTovBasisValutaDouble(@BjGid, @PerNr, @ValNummer);
    else
      if @@EuroValutaNummer is not null then
        select HlpKrsKoersTovEuro into @VanKoers from tabHulpKoers where HlpKrsValnummer=@@BasisValutaNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Pernr;
        if isnull(@VanKoers,0)=0 then
          select KrsKoersTovEuro into @VanKoers from tabValutaKoers where KrsValnummer=@@BasisValutaNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
        end if;
        if IsNull(@VanKoers, 0) <> 0 then
          select HlpKrsKoersTovEuro into @NaarKoers from tabHulpKoers where HlpKrsValnummer=@ValNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Pernr;
          if IsNull(@NaarKoers, 0) = 0 then
            select KrsKoersTovEuro into @NaarKoers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
          end if;
        end if;
        if IsNull(@VanKoers,0) <> 0 and IsNull(@NaarKoers,0) <> 0 then      //Eurokoersen
          set @Koers = @VanKoers / @NaarKoers ;
        else
          select HlpKrsKoers/HlpKrsEenheid into @Koers from tabHulpKoers where HlpKrsValnummer=@ValNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Pernr;
          if isnull(@koers,0)=0 then
            select Koers/KrsEenheid into @Koers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
          end if;
        end if
      else
        select   HlpKrsKoers/HlpKrsEenheid into @Koers from tabHulpKoers where HlpKrsValnummer=@ValNummer and HlpKrsBjGid=@BjGid and HlpKrsPernr=@Pernr;
        if isnull(@koers,0) = 0 then
          select   Koers/KrsEenheid into @Koers from tabValutaKoers where KrsValnummer=@ValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
        end if;
      end if;
    end if;
  end if;

  //call TraceBegin('KoersTovBasisValutaMetTijdelijkeKoersenDouble > @Koers = ' + string(@Koers));
  Return(@Koers);
end;



//$Workfile: KoersVerschillenRekeningValuta.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='KoersVerschillenRekeningValuta') then
  drop procedure KoersVerschillenRekeningValuta;
end if;

create procedure KoersVerschillenRekeningValuta(in @ValNummer integer, inout @RksGid integer)
begin

  set @@ErrorTextProcedure = 'KoersVerschillenRekeningValuta > @ValNummer='+string(@ValNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  select KoersVerschilRksGid into @RksGid from tabValuta where ValNummer = @ValNummer;

  set @@ErrorTextProcedure = 'KoersVerschillenRekeningValuta > @RksGid='+string(@RksGid);
  //call TraceBegin(@@ErrorTextProcedure);

end;


create or replace procedure KoerswijzigingsBoekingen(in @BjGid integer, in @Pernr integer, in @KoersCorrPerNr integer, in @JpGid integer, in @KoersCorrJpGid integer, in @ValNummer integer, in @Oms nchar(40), in @InvOms nchar(40), in @InclDezePer smallint)
begin
  // ACW 27-05-2004: Koers berekend als double ipv. als numeric(15,6)
  declare @SoortBoeking integer;
  declare @SomBasis numeric(15,2);
  declare @SomBasisBalans numeric(15,2);
  declare @Koers double;
  declare @KoersCorrPeriode double;

  declare local temporary table tmpKW (
    tmpRksGid              integer,
    tmpRksInvoer           nchar(28),
    tmpPerNr               integer,
    tmpDefaultSoort        smallint,
    tmpSaldoDebetBasis     numeric(15,2) default 0,
    tmpSaldoDebetVal       numeric(15,2) default 0,
    tmpSaldoCreditBasis    numeric(15,2) default 0,
    tmpSaldoCreditVal      numeric(15,2) default 0,
    tmpSaldoDebetBasisCum  numeric(15,2) default 0,
    tmpSaldoDebetValCum    numeric(15,2) default 0,
    tmpSaldoCreditBasisCum numeric(15,2) default 0,
    tmpSaldoCreditValCum   numeric(15,2) default 0,
    Primary key (tmpPernr, tmpRksGid)
  ) on commit preserve rows;

  declare local temporary table tmpTel (
    tmpTelTel integer,
    Primary key (tmpTelTel)
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'KoerswijzigingsBoekingen > @BjGid='+string(@BjGid)+' @Pernr='+string(@Pernr)+', @JpGid='+string(@JpGid)+', @KoersCorrJpGid='+string(@KoersCorrJpGid)+', @ValNummer='+string(@ValNummer)+ ', @Oms='+@oms+', @InclDezePer='+string(@InclDezePer);
  //call TraceBegin(@@ErrorTextProcedure);

  insert into tmpTel values(0); //Debet Oude waarde tegenboeken
  insert into tmpTel values(1); //Debet Nieuwe waarde opboeken
  insert into tmpTel values(2); //Credit Oude waarde tegenboeken
  insert into tmpTel values(3); //Credit Nieuwe waarde opboeken
  insert into tmpTel values(4); //Debetkoerscorrectie tegenboeken op de rekening
  insert into tmpTel values(5); //Debettkoerscorrectie opboeken op de rekening
  insert into tmpTel values(6); //Creditkoerscorrectie tegenboeken op de rekening
  insert into tmpTel values(7); //Creditkoerscorrectie op de rekening

  insert into tmpKW ( tmpRksGid, tmpRksInvoer, tmpPerNr, tmpDefaultSoort,
                      tmpSaldoDebetBasis, tmpSaldoDebetVal, tmpSaldoCreditBasis, tmpSaldoCreditVal )
  select RksGid, RksInvoer, RekSaldoPerNr, DefaultSoort,
         sum(SaldoDebetBasisDefinitief), sum(SaldoDebetValutaDefinitief), sum(SaldoCreditBasisDefinitief), sum(SaldoCreditValutaDefinitief)
  from   tabRekeningSaldo, tabRekeningSchema
  where  RekSaldoBjGid=@BjGid
         and ( RekSaldoPernr<@Pernr or ( @InclDezePer=1 and RekSaldoPernr=@Pernr ) )
         and RekSaldoValNummer=@ValNummer
         and RekSaldoRksGID=RksGid
  group by RksGid, RksInvoer, RekSaldoPerNr, DefaultSoort;


  //Indien een (geboekte) rekening nog niet in deze valuta heeft geboekt, dan voor deze periode de rekening toevoegen
  insert into tmpKW ( tmpRksGid, tmpRksInvoer, tmpPerNr, tmpDefaultSoort,
                      tmpSaldoDebetBasis, tmpSaldoDebetVal, tmpSaldoCreditBasis, tmpSaldoCreditVal )
  select distinct tmpRksGid, tmpRksInvoer, @PerNr, tmpDefaultSoort, 0, 0, 0, 0
  from tmpKW where tmpRksGid not in (select tmpRksGid from tmpKW where tmpPerNr = @PerNr);

  create index idx_tmpKW1 on tmpKW(tmpPernr, tmpRksGid);
  create index idx_tmpKW2 on tmpKW(tmpRksGid, tmpPernr);

  update tmpKW
  set    tmpSaldoDebetBasisCum =(select sum(andere.tmpSaldoDebetBasis)  from tmpKW Andere where andere.tmpRksGid = tmpKW.tmpRksGid ),
         tmpSaldoCreditBasisCum=(select sum(andere.tmpSaldoCreditBasis) from tmpKW Andere where andere.tmpRksGid = tmpKW.tmpRksGid ),
         tmpSaldoDebetValCum   =(select sum(andere.tmpSaldoDebetVal)    from tmpKW Andere where andere.tmpRksGid = tmpKW.tmpRksGid ),
         tmpSaldoCreditValCum  =(select sum(andere.tmpSaldoCreditVal)   from tmpKW Andere where andere.tmpRksGid = tmpKW.tmpRksGid )
  where  tmpPerNr=@PerNr;




  if @@TijdelijkeKoersen = 1 then
    set @SoortBoeking = 3
  else
    set @SoortBoeking = 4;
  end if;

  //Bepaal de koers van de @valnummer tov. basisvaluta
  set @Koers            =        KoersTovBasisValutaMetTijdelijkeKoersenDouble(@BjGid, @Pernr,          @ValNummer);
  set @KoersCorrPeriode = isnull(KoersTovBasisValutaMetTijdelijkeKoersenDouble(@BjGid, @KoersCorrPerNr, @ValNummer), 0);

  //Oude waarde tegenboeken (debetzijde), nieuwe waarde opboeken (debetzijde) en in de volgende periode (evt.) tegenovergesteld
  insert into tabJournaalregel( JrJpGid,
                                JrRksGid, StukVolgnr,
                                OmsJournaalRegel,
                                SoortBoeking, IsCreditBoeking,
                                JrValnummer,
                                JrBasisBedrag,
                                JrValutaBedrag)
  select   if tmpTelTel in (4,5,6,7) then @KoersCorrJpGid else @jpGid endif JpGid,
           tmpRksGid, StukvolgnrGenereerNieuw( JpGid, 1000),
           if tmpTelTel in (4,5,6,7) then @InvOms else @Oms endif,
           @SoortBoeking, if tmpTelTel in (0,1,4,5) then 0 else 1 endif,
           @ValNummer,
           if tmpDefaultSoort in (0,1,2,6,7) then
             case tmpTelTel
             when 0 then
               //Debet tegenboeken
               -tmpSaldoDebetBasisCum
             when 1 then
               //Debet opboeken
               round(tmpSaldoDebetValCum * @Koers, 2)
             when 2 then
               //Credit tegenboeken
               -tmpSaldoCreditBasisCum
             when 3 then
               //Credit opboeken
               round(tmpSaldoCreditValCum * @Koers, 2)
             when 4 then
               //Debetkoerscorrectie in de andere periode tegenboeken
               round(-tmpSaldoDebetValCum * @Koers, 2)
             when 5 then
               //Debetkoerscorrectie in de andere periode opboeken
               tmpSaldoDebetBasisCum
             when 6 then
               //Creditkoerscorrectie in de andere periode tegenboeken
               round(-tmpSaldoCreditValCum * @Koers, 2)
             else
               //Creditkoerscorrectie in de andere periode opboeken
               tmpSaldoCreditBasisCum
             end
           else
             case tmpTelTel
             when 0 then
               //Debet tegenboeken
               -tmpSaldoDebetBasis
             when 1 then
               //Debet opboeken
               round(tmpSaldoDebetVal * @Koers, 2)
             when 2 then
               //Credit tegenboeken
               -tmpSaldoCreditBasis
             when 3 then
               //Credit opboeken
               round(tmpSaldoCreditVal * @Koers, 2)
             when 4 then
               //Debetkoerscorrectie in de andere periode tegenboeken
               round(-tmpSaldoDebetVal * @Koers, 2)
             when 5 then
               //Debetkoerscorrectie in de andere periode opboeken
               tmpSaldoDebetBasis
             when 6 then
               //Creditkoerscorrectie in de andere periode tegenboeken
               round(-tmpSaldoCreditVal * @Koers, 2)
             else
               //Debetkoerscorrectie in de andere periode opboeken
               tmpSaldoCreditBasis
             end
           endif SomBasis,
           if tmpDefaultSoort in (0,1,2,6,7) then
             case tmpTelTel
             when 0 then
               //Debet tegenboeken
               -tmpSaldoDebetValCum
             when 1 then
               //Debet opboeken
                tmpSaldoDebetValCum
             when 2 then
               //Credit tegenboeken
               -tmpSaldoCreditValCum
             when 3 then
               //Credit opboeken
                tmpSaldoCreditValCum
             when 4 then
               //Debet in andere periode tegenboeken
                -tmpSaldoDebetValCum
             when 5 then
               //Debet in andere periode opboeken
                tmpSaldoDebetValCum
             when 6 then
               //Credit in andere periode tegenboeken
                -tmpSaldoCreditValCum
             when 7 then
               //Credit in andere periode opboeken
                tmpSaldoCreditValCum
             end
           else
             case tmpTelTel
             when 0 then
               //Debet tegenboeken
               -tmpSaldoDebetVal
             when 1 then
               //Debet opboeken
                tmpSaldoDebetVal
             when 2 then
               //Credit tegenboeken
               -tmpSaldoCreditVal
             when 3 then
               //Credit opboeken
                tmpSaldoCreditVal
             when 4 then
               //Debet in andere periode tegenboeken
                -tmpSaldoDebetVal
             when 5 then
               //Debet in andere periode opboeken
                tmpSaldoDebetVal
             when 6 then
               //Credit in andere periode tegenboeken
                -tmpSaldoCreditVal
             when 7 then
               //Credit in andere periode opboeken
                tmpSaldoCreditVal
             end
           endif SomVal
  from     tmpKW, tmpTel
  where    (SomBasis <> 0 or SomVal <> 0)  // ACW 23-11-2001: Alleen als een bedrag <> 0 dan de boeking maken
           and tmpPerNr=@PerNr
           and (
                 ( //Debet tegen- en opboeken
                   tmpTelTel in (0,1,4,5)
                   and ( ( tmpDefaultSoort in (0,1,2,6,7)
                           and ( tmpSaldoDebetBasisCum - round(tmpSaldoDebetValCum * @Koers, 2) <> 0 )
                         ) or
                         ( tmpDefaultSoort in (3,4,5)
                           and ( tmpSaldoDebetBasis    - round(tmpSaldoDebetVal * @Koers, 2) <> 0 )
                         )
                       )
                 ) or
                 ( //Credit tegen- en opboeken
                   tmpTelTel in (2,3,6,7)
                   and ( ( tmpDefaultSoort in (0,1,2,6,7)
                           and ( tmpSaldoCreditBasisCum - round(tmpSaldoCreditValCum * @Koers, 2) <> 0 )
                         ) or
                         ( tmpDefaultSoort in (3,4,5)
                           and ( tmpSaldoCreditBasis    - round(tmpSaldoCreditVal * @Koers, 2) <> 0 )
                         )
                       )
                 )
               )
           and ( //Verschil in andere periode boeken, maar alleen als er een verschil is en een andere periode om weg te boeken en geen RR
                 ( tmpTelTel in (0,1,2,3) ) or
                 (  tmpTelTel in (4,5,6,7)
                    and @KoersCorrJpGid is not null
                    and tmpDefaultSoort in (0,1,2,6,7)
                    //ACW 22-01-2015 defect #44450: Als de koers gelijk is, dan nog kan er een verschil zijn dat naar de koersverschillenrek. moet!
                    //and @Koers <> @KoersCorrPeriode //Als koersen gelijk, dan is er ook geen extra boeking nodig!
                 )
               )
  order by tmpRksInvoer, JpGid, tmpTelTel;

  //Als laatste koersverschil wegboeken naar de koersverschillenrekening van de valuta

  //Balansrekeningen: totaal t/m deze periode
  set @SomBasisBalans = 0;
  set @SomBasis = null;
  select   sum( tmpSaldoDebetBasisCum - tmpSaldoCreditBasisCum -
             round(tmpSaldoDebetValCum * @Koers, 2) +
             round(tmpSaldoCreditValCum * @Koers, 2)) into @SomBasisBalans
  from     tmpKW
  where    tmpPerNr=@PerNr and
           tmpDefaultSoort in (0,1,2,6,7)
           //ACW 22-01-2015 defect #44450: Als de koers gelijk is, dan nog kan er een verschil zijn dat naar de koersverschillenrek. moet!
           ;//and @Koers <> @KoersCorrPeriode; //Als koersen gelijk, dan is er ook geen extra boeking nodig!
  //Resultaatrekeningen: aleen deze periode
  select   sum( tmpSaldoDebetBasis - tmpSaldoCreditBasis -
             round(tmpSaldoDebetVal * @Koers, 2) +
             round(tmpSaldoCreditVal * @Koers, 2) )
           into @SomBasis
  from     tmpKW
  where    tmpPerNr=@PerNr and
           tmpDefaultSoort in (3,4,5);
  if @SomBasis is null then
    set @SomBasis = @SomBasisBalans;
  else
    set @SomBasis = @SomBasis + @SomBasisBalans;
  end if;


  //In de herwaarderingsjp
  if @SomBasis <> 0 and @Pernr <> 0 then
    insert into tabJournaalregel( JrJpGid, JrRksGid, StukVolgnr, OmsJournaalRegel,
                                  SoortBoeking, IsCreditBoeking,
                                  JrValnummer,
                                  JrBasisBedrag,
                                  JrValutaBedrag)
    select   @jpGid, RksGid, StukvolgnrGenereerNieuw( @JpGid, 1000), @Oms,
             @SoortBoeking, if DefaultBoekZijde in (0,1) then DefaultBoekZijde
                            else if @SomBasis > 0 then 0
                                 else 1
                                 endif
                            endif,
             @@BasisValutaNummer,
             if DefaultBoekZijde in (0,1) then @SomBasis
             else abs(@SomBasis)
             endif SomBasis,
             SomBasis
    from     tabValuta inner join tabRekeningSchema on (RksGid=KoersverschilRksGid)
    where    ValNummer=@ValNummer;
  end if;

  //In de koerscorrectiejp
  if (@KoersCorrJpGid is not null) and @SomBasisBalans<>0 then
    set @SomBasisBalans=-@SomBasisBalans;
    insert into tabJournaalregel( JrJpGid, JrRksGid, StukVolgnr, OmsJournaalRegel,
                                  SoortBoeking, IsCreditBoeking,
                                  JrValnummer,
                                  JrBasisBedrag,
                                  JrValutaBedrag)
    select   @KoersCorrJpGid, RksGid, StukvolgnrGenereerNieuw( @KoersCorrJpGid, 1000), @InvOms,
             @SoortBoeking,
             if DefaultBoekZijde in (0,1) then
                DefaultBoekZijde
             else
                if @SomBasisBalans > 0 then
                  0
                else
                  1
                endif
             endif,
             @@BasisValutaNummer,
             if DefaultBoekZijde in (0,1) then @SomBasisBalans
             else abs(@SomBasisBalans)
             endif SomBasis,
             SomBasis
    from     tabValuta inner join tabRekeningSchema on (RksGid=KoersverschilRksGid)
    where    ValNummer=@ValNummer;
  end if;

  //call TraceEind( 'KoerswijzigingsBoekingen');

end;


create or replace procedure KopierenOfferteversie
(
  in  @BronOfkGid   integer,
  in  @KopierenNaar smallint, /* 0=versie kopieren naar nieuwe offerte | 1=versie kopieren naar nieuwe versie binnen dezelfde offerte */
  out @DoelOffGid   integer,
  out @DoelOfkGid   integer
)
begin
  /* variabelen */
  declare @OverruleIsGewijzigd       bit           = 0;
  declare @BronOfkOffGid             integer       = null;
  declare @BronOfkOffertenummer      nchar(14)     = null;
  declare @AanmaakDatumTijd          DateTime      = now();
  declare @Offertenummer             numeric(10,0) = null;
  declare @NieuwVersienummer         integer       = null;
  declare @SamengesteldOffertenummer nchar(14)     = null;
  declare @AantalDagenGeldig         smallint      = null;
  declare @KostprijsTerugzetten      integer       = null;  // 0 = alle, 1 = alleen met niet wijzigbare kostprijs
  declare @ArtGidKortingstarief      integer       = null;
  declare @ArtGidInruiltarief        integer       = null;

  /* constanten */
  declare @qcLockTable               nchar(40)     = 'tabOfferte';

  //call TraceBegin('KopierenOfferteversie > @BronOfkGid = ' + string(@BronOfkGid));

  set @KopierenNaar = IsNull(@KopierenNaar, 0);
  select OfkOffGid, OfkOffertenummer into @BronOfkOffGid, @BronOfkOffertenummer  from tabOfferteKop where OfkGid = @BronOfkGid;

  if not exists(select 1 from tabOfferteKop where OfkGid = @BronOfkGid) then
    call Raise(20360);
  end if;

  if @KopierenNaar = 0 then /* versie kopieren naar nieuwe offerte */

    /* nieuw offertenummer genereren */
    set @Offertenummer = (select OfferteGenereerTrajectnummer());

    /* nieuwe offerte aanmaken */
    insert into tabOfferte with auto name
    select
      @Offertenummer as OffOffertenummer, /* nieuw offertenummer toekennen */
      0 as OffStatus,   /* de status altijd op openstaand zetten */
      OffNawGidDebiteur,
      OffRelGidDebiteur,
      OffFonGidRelatie,
      OffNawGidRelatie,
      OffRelGidRelatie,
      OffVtgCode,
      OffLeverdatum,
      OffScoringskans,
      OffDoorlooptijdAantal,
      OffDoorlooptijdPeriode,
      OffKstdGid,
      OffKstpGid,
      @@GebruikerCode as OffAangemaaktDoor, /* Code van de ingelogde gebruiker invullen */
      @AanmaakDatumTijd as OffAangemaaktDatum,  /* server datum invullen */
      null as OffEindstatusDatum, /* leeglaten -> de offerte is nog openstaand */
      null as OffEindstatusDoor, /* leeglaten -> de offerte is nog openstaand */
      OffReferentie,
      OffOpmerking,
      OffBerekenmethodeOffertetotaal,
      if OffBerekenmethodeOffertetotaal = 0 then OffOffertetotaal else 0 end if as OffOffertetotaal, /* alleen handmatig opgegeven bedrag kopieren -> in andere gevallen wordt de offerteversie niet in de berekenmethode meegenomen omdat de status nog concept is. */
      OffVerwachteOmzet,
      case OffDoorlooptijdPeriode
        when 3 then DateAdd(year, OffDoorlooptijdAantal, OffAangemaaktDatum)  /* jaren */
        when 2 then DateAdd(month, OffDoorlooptijdAantal, OffAangemaaktDatum) /* maanden */
        when 1 then DateAdd(week, OffDoorlooptijdAantal, OffAangemaaktDatum)  /* weken */
        else DateAdd(day, OffDoorlooptijdAantal, OffAangemaaktDatum)          /* dagen */
      end case as OffVerwachteScoringsdatum,
      OffMaevGid,
      OffBtwCode
    from
      tabOfferte
    where
      OffGid = @BronOfkOffGid;

    /* nieuwe Offertegidje ophalen */
    set @DoelOffGid = @@Identity;

    /* nieuwe offerte locken zodat een gebruiker er niet inkan tijdens het kopieerproces */
    call LockSetOnId(@@SpId, @@LoginTime, 1, @qcLockTable, string(@DoelOffGid), 0);

  else /* @KopierenNaar = 1; versie kopieren naar nieuwe versie binnen dezelfde offerte */
    set @DoelOffGid = @BronOfkOffGid;
    set @Offertenummer = (select OffOffertenummer from tabOfferte where OffGid = @DoelOffGid);

    /* 20366: Test of bestaande offerte is gelocked (door deze gebruiker). Bij het aanmaken van een nieuwe offerte is dit niet nodig. */
    if LockedById(@@SpId, @@LoginTime, 1, @qcLockTable, string(@DoelOffGid)) = 0 then
      call Raise(20366); /* (20366) Offerte moet gelocked zijn! */
    end if;

    /* 20362: er mag alleen binnen dezelfde offerte gekopieerd worden als deze nog openstaat */
    if (IsNull((select OffStatus from tabOfferte where OffGid = @DoelOffGid), -1) <> 0) then
      call Raise(20362); /* (20362) Offerte is reeds geaccepteerd of afgewezen! */
    end if;
  end if;


  /* Nummers Offerte en versie genereren */
  set @NieuwVersienummer = IsNull((select max(OfkVersienummer) from tabOfferteKop where OfkOffGid = @DoelOffGid),0)+1;
  set @SamengesteldOffertenummer = string(@Offertenummer) + '.' + string(@NieuwVersienummer); /* veld samenstellen uit offertenummer en versienummer. Offerte 10, versie 3 -> OfkOffertenummer wordt: 10.3 */

  /* Vaste gegevens ophalen */
  select first IsNull(OfvgDefaultAantalDagenGeldig, 14), OfvgArtGidKortingstarief,  OfvgArtGidInruiltarief,  OfvgKostprijsTerugzetten into
               @AantalDagenGeldig,                       @ArtGidKortingstarief, @ArtGidInruiltarief, @KostprijsTerugzetten from tabOfferteVasteGegevens;

  /* Versie kopieren */
  insert into tabOfferteKop with auto name
  select
    @DoelOffGid as OfkOffGid,
    @NieuwVersienummer as OfkVersienummer,
    @SamengesteldOffertenummer as OfkOffertenummer,
    0 as OfkStatus, /* altijd naar conceptstatus zetten */
    OfkIsInkoopCombinatie,
    OfkNawGidInkCombiFactuur,
    OfkNawGidInkCombiOmzet,
    OfkNawGidInkCombiPrijzen,
    OfkApartFactureren,
    OfkApartLeveren,
    OfkFactuurAdres,
    OfkVerzendAdres,
    OfkEindAdres,
    OfkAdrGidVerzendAdres,
    OfkAdrGidEindAdres,
    OfkTaalGid,
    @AanmaakDatumTijd as OfkAanmaakdatum, /* server datum invullen */
    OfkReferentie,
    OfkBtwStand,
    DateAdd(day, @AantalDagenGeldig, IsNull(OfkAanmaakdatum, @@Verwerkingsdatum)) as OfkGeldigheidsdatum, /* TG defect #47431: geldigheidsdatum opnieuw bepalen */
    OfkOpmerking,
    OfkBtcNummer,
    OfkLvcNummer,
    OfkValNummer,
    OfkOrderkorting,
    OfkAfdruk_Offertetotaal,
    OfkAfdruk_OffertetotaalAfgeleid,
    OfkAfdruk_OffertetotaalBruto,
    OfkAfdruk_OffertetotaalKorting1Deel,
    OfkAfdruk_OffertetotaalKorting2Deel,
    OfkAfdruk_OffertetotaalKostprijs,
    OfkAfdruk_OffertetotaalOrderkorting
  from
    tabOfferteKop
  where
    OfkGid = @BronOfkGid;

  /* nieuwe Offertegidje ophalen */
  set @DoelOfkGid = @@Identity;

  /* Statuslogregel aanmaken */
  insert into tabOfferteversieStatuslog with auto name
  select
    @@GebruikerCode as OfvsGebruikerCode,
    @DoelOfkGid     as OfvsOfkGid,
    0               as OfvsStatus,
  @AanmaakDatumTijd as OfvsTijdstip,
  _A('Kopie van %1!', + @BronOfkOffertenummer) as OfvsToelichting;

  /* omdat we zeer waarschijnlijk meerdere offerteregels toevoegen schakelen we het herberekenen van de totalen */
  /* van de versie (per regel) even uit en roepen we dat na het inserten van de regels handmatig eenmalig aan.  */
  set @@OverruleOfferteversieBerekenTotalen = @@OverruleOfferteversieBerekenTotalen + 1; /* overrule inschakelen. we updaten eenmalig nadat alle regels bijgewerkt zijn */
  set @OverruleIsGewijzigd = 1; /* variabele is aangepast, dus hier op 1 zetten */

  /* offerteregels overnemen */
  begin
    declare @OfrGidMaster integer = null;

    for @Cursor AS CURSOR_OfferteregelsZonderMaster CURSOR FOR
      select
        OfrGid as @OfrGid
      from
        tabOfferteregel
      where
        OfrOfkGid = @BronOfkGid and
        OfrOfrGidVolgregelMaster is null /* geen volgartikelen selecteren! */
      order by
        OfrRegelpositie, OfrGid
    for read only
    do
      insert into tabOfferteRegel with auto name
      select
        @DoelOfkGid as OfrOfkGid,
        OfrRegelpositie,
        OfrRegelsoort,
        OfrArtGidTekstblok,
        OfrArtGidTarief,
        OfrArtGidArtikel,
        null as OfrOfrGidVolgregelMaster,
        OfrVolgartikelFactor,
        OfrArtPartijGid,
        OfrBtwCode,
        OfrTekstOpOfferte,
        OfrAantalDecimalenVoorAantallen,
        OfrAantalDecimalenVoorPrijzen,
        OfrAantalTeOffreren,
        OfrGeprijsdPer,
        (if (@KostprijsTerugzetten = 0) or (ArtIsKostprijsWijzigenInOrder <> 1) then (if (ArtIsPartijAparteKostPrijs <> 0) and ArtPartijKostprijsEx is not null then ArtPartijKostprijsEx else ArtKostprijsEx endif) else OfrKostprijs endif) OfrKostprijs,
        OfrPrijs,
        OfrVkeGid,
        OfrEenheidPrijsPer,
        OfrAantalDecimalenVoorAantallenVrrdEenh,
        OfrAantalTeOffrerenVrrdEenh,
        OfrAantalVrrdEenhInVerkEenh,
        OfrAantalVrrdEenhInVerkEenhMagAfwijken,
        OfrRegelkorting1Bedrag,
        OfrRegelkorting1Percentage,
        OfrRegelkorting2Percentage,
        OfrStukskorting1Bedrag,
        OfrStukskorting1Percentage,
        OfrStukskorting2Percentage,
        OfrAfdruk_Regeltotaal,
        OfrAfdruk_RegeltotaalBruto,
        OfrAfdruk_RegeltotaalKorting1Deel,
        OfrAfdruk_RegeltotaalKorting2Deel,
        OfrAfdruk_RegeltotaalKostprijs,
        OfrAfdruk_RegeltotaalNettoPrijsPerGeprijsdPer,
        OfrAfdruk_RegeltotaalNettoPrijsPerStuk
      from
        tabOfferteregel
        left outer join tabArtikel on ArtGid = (case OfrRegelSoort
                                   when 1 then OfrArtGidTarief
                                   when 2 then OfrArtGidArtikel
                                   when 3 then @ArtGidKortingstarief
                                   when 4 then @ArtGidInruiltarief
                                  end)
        left outer join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijGid = OfrArtPartijGid
      where
        tabOfferteregel.OfrOfkGid = @BronOfkGid and/* TG: de tabelverwijzing is nodig, want ofrOfkGid wordt in de select gevuld en dan levert deze where vervolgens geen regels op */
        tabOfferteregel.OfrGid = @OfrGid
      order by
        OfrRegelpositie, OfrGid;

      /* nieuwe hoofdregel-gidje onthouden */
      set @OfrGidMaster = @@Identity;

      /* nu alle volgregels toevoegen aan de nieuwe hoofdregel */
      insert into tabOfferteRegel with auto name
      select
        @DoelOfkGid as OfrOfkGid,
        OfrRegelpositie,
        OfrRegelsoort,
        OfrArtGidTekstblok,
        OfrArtGidTarief,
        OfrArtGidArtikel,
        @OfrGidMaster as OfrOfrGidVolgregelMaster,
        OfrVolgartikelFactor,
        OfrArtPartijGid,
        OfrBtwCode,
        OfrTekstOpOfferte,
        OfrAantalDecimalenVoorAantallen,
        OfrAantalDecimalenVoorPrijzen,
        OfrAantalTeOffreren,
        OfrGeprijsdPer,
        (if (@KostprijsTerugzetten = 0) or (ArtIsKostprijsWijzigenInOrder <> 1) then (if (ArtIsPartijAparteKostPrijs <> 0) and ArtPartijKostprijsEx is not null then ArtPartijKostprijsEx else ArtKostprijsEx endif) else OfrKostprijs endif) OfrKostprijs,
        OfrPrijs,
        OfrVkeGid,
        OfrEenheidPrijsPer,
        OfrAantalDecimalenVoorAantallenVrrdEenh,
        OfrAantalTeOffrerenVrrdEenh,
        OfrAantalVrrdEenhInVerkEenh,
        OfrAantalVrrdEenhInVerkEenhMagAfwijken,
        OfrRegelkorting1Bedrag,
        OfrRegelkorting1Percentage,
        OfrRegelkorting2Percentage,
        OfrStukskorting1Bedrag,
        OfrStukskorting1Percentage,
        OfrStukskorting2Percentage,
        OfrAfdruk_Regeltotaal,
        OfrAfdruk_RegeltotaalBruto,
        OfrAfdruk_RegeltotaalKorting1Deel,
        OfrAfdruk_RegeltotaalKorting2Deel,
        OfrAfdruk_RegeltotaalKostprijs,
        OfrAfdruk_RegeltotaalNettoPrijsPerGeprijsdPer,
        OfrAfdruk_RegeltotaalNettoPrijsPerStuk
      from
        tabOfferteregel
        inner join tabArtikel on ArtGid = (case OfrRegelSoort
                                   when 1 then OfrArtGidTarief
                                   when 2 then OfrArtGidArtikel
                                   when 3 then @ArtGidKortingstarief
                                   when 4 then @ArtGidInruiltarief
                                  end)
        left outer join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijGid = OfrArtPartijGid
      where
        tabOfferteregel.OfrOfkGid = @BronOfkGid and /* TG: de tabelverwijzing is nodig, want ofrOfkGid wordt in de select gevuld en dan levert deze where vervolgens geen regels op */
        tabOfferteregel.OfrOfrGidVolgregelMaster = @OfrGid
      order by
        OfrRegelpositie, OfrGid;
    end for;
  end;

  set @@OverruleOfferteversieBerekenTotalen = @@OverruleOfferteversieBerekenTotalen - 1; /* overrule weer uitschakelen */
  set @OverruleIsGewijzigd = 0; /* overrule is weer hersteld, dus hier op 0 zetten */

  /* totalen en btwregels van gekopieerde versie berekenen omdat die overruled is bij het kopiÃ«ren van de regels */
  call OfferteversieBerekenTotalenEnBtwRegels(@DoelOfkGid);

  /* kopieren vrije rubrieken (wens #34755) */
  begin
    declare @VrBestandOms nchar(3) = 'OFK';
    declare @GroepsId integer = 0;
    call VrKopieerRecord(@VrBestandOms, @GroepsId, @GroepsId, @VrBestandOms, @GroepsId, @GroepsId, @BronOfkGid, @DoelOfkGid);
  end;


  /* bij kopieren naar nieuwe offerte is de lock door deze proc gezet, dus ook zelf vrijgeven */
  if @KopierenNaar = 0 then
    call LockReleaseOnId(@@spid, @@LoginTime , 1, @qcLockTable, string(@DoelOffGid));
  end if;

  //call TraceEind('KopierenOfferteversie > @DoelOffGid = ' + string(@DoelOffGid) + ', @DoelOfkGid = ' + string(@DoelOfkGid));

  exception
    when others then
      begin
        /* als de overrule niet hersteld is ivm een exception die ergens in de database opgetreden is, dan herstellen we de variabele zelf hier.        */
        /* Dit is omdat de exceptions worden afgevangen in Delphi (zie fOfferteversieKopieren) en daardoor worden er anders geen totalen meer berekend! */
        if @OverruleIsGewijzigd = 1 then
          set @@OverruleOfferteversieBerekenTotalen = @@OverruleOfferteversieBerekenTotalen - 1;
        end if;
        Resignal;
      end;
end;

//----------------------------------------------------------------------------------------------------
//------------------------ Kopieren Projectonderdeel incl. detail gegevens ---------------------------
//----------------------------------------------------------------------------------------------------
//call KopierenProjectOnderdeel(30028,30017,0,0,0,0,0,0);
create or replace procedure KopierenProjectOnderdeel(
in @BronPbGid                   integer,  //pbgid van knoop die we kopieren
in @DoelPbGid                   integer,  //pbgid waar we de knoop onder kopieren
in @DoelVolgNr                  smallint, //0 = als kind, anders (> 0) als broertje toevoegen aan boom (obv doelpbgid).
in @PrijsOpnieuwBepalen         smallint,
in @KopierenPrijsafspraak       smallint,
in @KopierenGebruiksToestemming smallint,
in @KopierenFactuurverdichting  smallint,
in @KopierenSelecties           smallint,
in @Factor                      numeric(15,3), //vermenigvuldigingsfactor
in @SessieNr                    integer,
in @AantalCats                  integer
)
begin
  //deze tijdelijke tabel houdt een lijst van van de PbGidjes van de bronknoop (de knoop die we kopieren) en het PbGidje
  //dat het nieuwe knoopje (de kopie) gekregen heeft. Hiermee kunnen we later de kinderen onder het knoopje met het nieuwe
  //PbGidje hangen.
  declare local temporary table tmpGidReferenties(      //Voor oude/nieuwe gid
    TmpGrOldGid integer,   //opslaan pbgid van originele knoop
    TmpGrNewGid integer    //opslaan pbgid van kopie knoop
  ) on commit preserve rows;

  declare @DoelProjGid               integer;
  declare @ParentPbGid               integer;
  declare @VolgNr                    integer;
  declare @NewZoekcodeSuffix         nchar(10);
  declare @HeleBoomstructuurKopieren smallint;

  //call TraceBegin('KopierenProjectOnderdeel > @BronPbGid='+String(@BronPbGid)+', @DoelPbGid='+String(@DoelPbGid)+', @DoelVolgNr='+String(@DoelVolgNr)+
  //                           ', @PrijsOpnieuwBepalen='+String(@PrijsOpnieuwBepalen)+', @KopierenPrijsafspraak='+String(@KopierenPrijsafspraak)+
  //                           ', @KopierenGebruiksToestemming='+String(@KopierenGebruiksToestemming)+', @KopierenFactuurverdichting='+String(@KopierenFactuurverdichting)+
  //                           ', @KopierenSelecties='+String(@KopierenSelecties));


  set @PrijsOpnieuwBepalen         = IsNull(@PrijsOpnieuwBepalen, 0);
  //mocht er een null-value meegegeven worden, dan gaan we er vanuit dat dat onderdeel niet gekopieerd moet worden.
  set @KopierenPrijsafspraak       = IsNull(@KopierenPrijsafspraak, 0);
  set @KopierenGebruiksToestemming = IsNull(@KopierenGebruiksToestemming, 0);
  set @KopierenFactuurverdichting  = IsNull(@KopierenFactuurverdichting, 0);
  set @KopierenSelecties           = IsNull(@KopierenSelecties, 0);
  set @Factor                      = IsNull(@Factor, 1);
  set @SessieNr                    = IsNull(@SessieNr, 0);
  set @AantalCats                  = IsNull(@AantalCats, 0);

  //Bronpbgid
  select if PbLevel <= 1 then 1 else 0 endif into @HeleBoomstructuurKopieren from tabProjectBoom where PbGid = @BronPbGid;

  //Doelprojectgid
  select PbProjGid into @DoelProjGid from tabProjectBoom where PbGid = @DoelPbGid;
  //call Trace('KopierenProjectOnderdeel > @DoelProjGid='+string(@DoelProjGid));

  //Deze cursor loop alle knopen die onder de bronknoop hangen (incl. de bronknoop zelf) af
  for @Cursor AS CURSOR_CopyNodes CURSOR FOR
    select
    PbGid                       @CurPbGid,
    PbBtwCodeAfwijkend          @CurPbBtwCodeAfwijkend,
    PbIsOfferteBedragAfwijkend  @CurPbIsOfferteBedragAfwijkend,
    PbIsOfferteTekstAfwijkend   @CurPbIsOfferteTekstAfwijkend,
    PbOfferteBedragAfwijkend    @CurPbOfferteBedragAfwijkend,
    PbOfferteTekstAfwijkend     @CurPbOfferteTekstAfwijkend,
    PbOmschr                    @CurPbOmschr,
    PbParentPbGid               @CurPbParentPbGid,
    PbUitsplitsen               @CurPbUitsplitsen,
    PbVolgNr                    @CurPbVolgNr,
    PbZoekcodeSuffix            @CurPbZoekcodeSuffix,
    PbLevel                     @CurPbLevel,
    PbSoort                     @CurPbSoort
  from
    tabProjectBoom
  where
   PbGid in (select PbpPbGid from tabProjectBoomPad where PbpParentPbGid=@BronPbGid union select @BronPbGid)
  order by
    pbLevel, pbVolgNr
  for read only
  do
    //het eerste record is de bron-knoop. Deze moet de bronknop (bij toevoegen onder) of de parent van de bronknoop
    //(bij toevoegen op zelfde niveau) krijgen
    if @CurPbGid = @BronPbGid then
      set @VolgNr      = @DoelVolgNr;
      //Als het volgnummer 0 is, dan voegen we de knopen toe als kind van DoelPbGid
      if @VolgNr = 0 then
        set @ParentPbGid = @DoelPbGid;
      //als het volgnummer <> 0 is, dan voegen we de knoop op hetzelfde niveau toe (en dus op hetzelfde niveau als het DoelPbGid).
      //derhalve kennen we de parent van DoelPbGid toe als parent voor de nieuwe knoop.
      else
        select PbParentPbGid into @ParentPbGid from tabProjectBoom where PbGid = @DoelPbGid;
      end if;

      //controleren of de zoekcode suffix al voorkomt in de tak, zo ja dan _x (x = volgnummer) toevoegen aan suffix.
      set @NewZoekcodeSuffix = GenereerNieuweProjectSuffix(@ParentPbGid, @CurPbZoekcodeSuffix);
    else
      //alle volgende records (na de eerste) moeten hun nieuwe parent opzoeken in de referentietabel.
      select TmpGrNewGid into @ParentPbGid from tmpGidReferenties where TmpGrOldGid = @CurPbParentPbGid;
      set @VolgNr = @CurPbVolgNr;
      //TG 03-12-2007: Als we het gehele project kopieren, dan kopieren we de projectnode niet en worden dus alle kindjes als eerste toegevoegd;
      //               In dat geval moeten we dus controleren of die knoop al unieke namen hebben, omdat ze naast bestaande nodes gekopieerd kunnen worden.
      //               De kinderen van deze knopen zijn wel uniek omdat hun parent net (uniek) is aangemaakt.
      if @HeleBoomstructuurKopieren = 1 and @CurPbLevel <= 2 then
        set @NewZoekcodeSuffix = GenereerNieuweProjectSuffix(@ParentPbGid, @CurPbZoekcodeSuffix);
      else
        set @NewZoekcodeSuffix = @CurPbZoekcodeSuffix;
      end if;
    end if;

    //projectonderdeel overnemen
    //call trace('KopierenProjectOnderdeel > Kopieren: @CurPbGid='+string(@CurPbGid)+', @NewZoekcodeSuffix='+@NewZoekcodeSuffix+', @ParentPbGid='+string(@ParentPbGid));

    if @HeleBoomstructuurKopieren = 0 or (@HeleBoomstructuurKopieren = 1 and @CurPbLevel > 1) then
      insert into tabProjectBoom(PbProjGid, PbSoort, PbBtwCodeAfwijkend, PbIsOfferteBedragAfwijkend,
                                 PbIsOfferteTekstAfwijkend, PbOfferteBedragAfwijkend, PbOfferteTekstAfwijkend,
                                 PbOmschr, PbParentPbGid, PbUitsplitsen, PbVolgNr, PbZoekcodeSuffix)
      values                    (@DoelProjGid, @CurPbSoort, @CurPbBtwCodeAfwijkend, @CurPbIsOfferteBedragAfwijkend,
                                 @CurPbIsOfferteTekstAfwijkend, round((@CurPbOfferteBedragAfwijkend * @Factor),2), @CurPbOfferteTekstAfwijkend,
                                 @CurPbOmschr, @ParentPbGid, @CurPbUitsplitsen, @VolgNr, @NewZoekcodeSuffix);
      //call trace('KopierenProjectOnderdeel > Gekopieerd');
      //nieuwe pbgid opslaan in de tijdelijke tabel zodat we de kindjes hierna ook kunnen toevoegen aan deze knoop.
      insert into tmpGidReferenties (TmpGrOldGid, TmpGrNewGid)
      values                        (@CurPbGid  , @@Identity);
    end if;
  end for;

  //---[ BELANGRIJK! ]----------------------------------------------------------------------------------------------------------------------------
  //op dit punt bevat de tabel tmpGidReferenties alle gidjes van de bronknoop (incl. kinderen). Deze tabel is dus overeenkomstig aan
  //de resultset van de select: "where PbGid in (select PbpPbGid from tabProjectBoomPad where PbpParentPbGid=@BronPbGid union select @BronPbGid)".
  //derhalve wordt deze where clausule niet meer gebruikt hieronder, maar een inner join op tmpGidReferenties!
  //----------------------------------------------------------------------------------------------------------------------------------------------

  //prijsafspraken ook kopieren?
  if @KopierenPrijsafspraak = 1 then
    //call trace('KopierenProjectOnderdeel > Kopieren Prijsafspraken');
    insert into tabProjectPrijsafspraak
      (ppaPbGid,  ppaArtGid, ppaRelGid, ppaVerkoopprijsExBtw)
    select
      TmpGrNewGid,  ppaArtGid, ppaRelGid, ppaVerkoopprijsExBtw
    from
      tmpGidReferenties
      inner join tabProjectPrijsafspraak on (ppaPbGid = TmpGrOldGid);
  end if;

  //gebruikstoestemmingen ook kopieren?
  if @KopierenGebruiksToestemming = 1 then
    //call trace('KopierenProjectOnderdeel > Kopieren gebruikstoestemmingen');
    insert into tabProjectPermissie
      (ppmPbGid, ppmArtGid, ppmRelGid, ppmPermissie)
    select
      TmpGrNewGid, ppmArtGid, ppmRelGid, ppmPermissie
    from
      tmpGidReferenties
      inner join tabProjectPermissie on (ppmPbGid = TmpGrOldGid);
  end if;

  //factuurverdichtingen ook kopieren?
  if @KopierenFactuurverdichting = 1 then
    //alleen kopieren indien het doelproject een regieproject is.
      //call trace('KopierenProjectOnderdeel > Kopieren factuurverdichtingen');
    insert into tabProjectFactuurVerdichting (
      PfvdPbGid, PfvdActPerOnderdeel, PfvdArtPerOnderdeel, PfvdMachPerOnderdeel,
      PfvdFactVerdActAct, PfvdFactVerdActMedew, PfvdFactVerdActOpbrGrp,
      PfvdFactVerdMachMach, PfvdFactVerdMachOpbrGrp, PfvdFactVerdArtArt, PfvdFactVerdArtOpbrGrp,
      PfvdActPerOnderdeelSpecAfdruk, PfvdArtPerOnderdeelSpecAfdruk, PfvdMachPerOnderdeelSpecAfdruk, PfvdTekstOpFactuur)
    select
      TmpGrNewGid, PfvdActPerOnderdeel, PfvdArtPerOnderdeel, PfvdMachPerOnderdeel,
      PfvdFactVerdActAct, PfvdFactVerdActMedew, PfvdFactVerdActOpbrGrp,
      PfvdFactVerdMachMach, PfvdFactVerdMachOpbrGrp, PfvdFactVerdArtArt, PfvdFactVerdArtOpbrGrp,
      PfvdActPerOnderdeelSpecAfdruk, PfvdArtPerOnderdeelSpecAfdruk, PfvdMachPerOnderdeelSpecAfdruk, PfvdTekstOpFactuur
    from
      tmpGidReferenties
      inner join tabProjectFactuurVerdichting on (PfvdPbGid = TmpGrOldGid);
  end if;

  //selecties ook kopieren?
  if @KopierenSelecties = 1 then
    //call trace('KopierenProjectOnderdeel > Kopieren selecties');
    //TG 03-11-2005: Dit wordt later geimplementeerd (in Fase II?).
  end if;

  //Voorcalculatieregels overnemen
  //call trace('KopierenProjectOnderdeel > Kopieren Voorcalculatieregels');
  insert into tabProjectVoorcalculatie(
    PvcArtGid,       PvcArtPartijGid,      PvcBudAantal,      PvcKostprijs,
    PvcMutSoort,     PvcOffAantal,         PvcOfferteBedrag,  PvcOmschr,     PvcPartFactEenheidFactor,
    PvcPbGid,        PvcPdosGid,           PvcPrijsPer,       PvcProjGid,    PvcRelGid,
    PvcVerkoopprijs, PvcVolgNr,            PvcSelectieCodes,  PvcIsDirecteInkoop, PvcLeverancierNawGid,
    PvcDoorbelastPercentage)
  select
    PvcArtGid, PvcArtPartijGid,
    Round(PvcBudAantal * if PvcDoorbelastPercentage is null then @Factor else 1 endif, (select ArtAantDecAantallen from tabArtikel where ArtGid = PvcArtGid)),
    if PvcDoorbelastPercentage is not null then PvcKostprijs * @Factor else if @PrijsOpnieuwBepalen = 1 then null else PvcKostprijs endif endif,
    PvcMutSoort,
    round(PvcOffAantal * if PvcDoorbelastPercentage is null then @Factor else 1 endif, (select ArtAantDecAantallen from tabArtikel where ArtGid = PvcArtGid)),
    if @PrijsOpnieuwBepalen = 1 or PvcDoorbelastPercentage is not null then null else round(PvcOfferteBedrag * round(PvcoffAantal * @Factor, (select ArtAantDecAantallen from tabArtikel where ArtGid = PvcArtGid))/(if isNull(PvcoffAantal,0) = 0 then 1 else PvcoffAantal endif),2) endif,
    PvcOmschr, PvcPartFactEenheidFactor, TmpGrNewGid, PvcPdosGid, PvcPrijsPer, @DoelProjGid, PvcRelGid,
    if @PrijsOpnieuwBepalen = 1 or PvcDoorbelastPercentage is not null then null else PvcVerkoopprijs endif,
    PvcVolgNr, PvcSelectieCodes, PvcIsDirecteInkoop, PvcLeverancierNawGid,
    if @PrijsOpnieuwBepalen = 1 then null else PvcDoorbelastPercentage endif
  from
    tmpGidReferenties
    inner join tabProjectVoorcalculatie on (PvcPbGid = TmpGrOldGid)
  where
    (
      (select count (*) from tabProjectSelectieCode inner join tmpProjSelCodes on tmpPscCode = PscCode and tmpPscSessieNr = @SessieNr WHERE PscPvcGid = PvcGid)
      >= @AantalCats
    )
  order by
    PvcVolgNr;

  //call TraceEind('KopierenProjectOnderdeel');
end;

//$Workfile: KopierenProjectVoorcalculatie.sp $ $Revision: 9 $ $Modtime: 17-09-09 14:24 $'

//----------------------------------------------------------------------------------------------------
//------------------------ Kopieren ProjectVoorcalculatie --------------------------------------------
//----------------------------------------------------------------------------------------------------
if exists(select 1 from sys.sysProcedure where proc_name='KopierenProjectVoorcalculatie') then
  drop procedure KopierenProjectVoorcalculatie;
end if;

create procedure KopierenProjectVoorcalculatie(
in @PvcGid                      integer,  //voorcalc die we kopieren
in @DoelPbGid                   integer,  //projectonderdeel waaronder de voorcalc. komt te hangen
in @DoelVolgNr                  smallint, //0 = als kind, anders (> 0) als broertje toevoegen aan boom (obv doelpbgid).
in @PrijsOpnieuwBepalen         smallint,
in @Factor                      numeric(15,3) //vermenigvuldigingsfactor
)
begin
  declare @DoelProjGid integer;

  set @@ErrorTextProcedure = 'KopierenProjectVoorcalculatie > @PvcGid='+String(@PvcGid)+', @DoelPbGid='+String(@DoelPbGid)+', @DoelVolgNr='+String(@DoelVolgNr)+', @PrijsOpnieuwBepalen='+String(@PrijsOpnieuwBepalen);
  //call TraceBegin(@@ErrorTextProcedure);

  //mocht er een null-value meegegeven worden, dan gaan we er vanuit dat dat onderdeel niet gekopieerd moet worden.
  set @DoelVolgNr          = IsNull(@DoelVolgNr, 0);
  set @PrijsOpnieuwBepalen = IsNull(@PrijsOpnieuwBepalen, 0);
  set @Factor              = IsNull(@Factor, 1);

  //Doelprojectgid
  select PbProjGid into @DoelProjGid from tabProjectBoom where PbGid = @DoelPbGid;
  //call Trace('KopierenProjectVoorcalculatie > @DoelProjGid='+string(@DoelProjGid));

  //Voorcalculatieregels overnemen
  //call trace('Kopieren Voorcalculatieregel');
  insert into tabProjectVoorcalculatie(
    PvcArtGid,       PvcArtPartijGid,            PvcBudAantal,      PvcKostprijs,
    PvcMutSoort,     PvcOffAantal,               PvcOfferteBedrag,  PvcOmschr,          PvcPartFactEenheidFactor,
    PvcPbGid,        PvcPdosGid,                 PvcPrijsPer,       PvcProjGid,         PvcRelGid,
    PvcVerkoopprijs, PvcVolgNr,                  PvcSelectieCodes,  PvcIsDirecteInkoop, PvcLeverancierNawGid,
    PvcDoorbelastPercentage)
  select
    PvcArtGid, PvcArtPartijGid,
    Round(PvcBudAantal * if PvcDoorbelastPercentage is null then @Factor else 1 endif, (select ArtAantDecAantallen from tabArtikel where ArtGid = PvcArtGid)),
    if PvcDoorbelastPercentage is not null then PvcKostprijs * @Factor else if @PrijsOpnieuwBepalen = 1 then null else PvcKostprijs endif endif,
    PvcMutSoort,
    round(PvcOffAantal * if PvcDoorbelastPercentage is null then @Factor else 1 endif, (select ArtAantDecAantallen from tabArtikel where ArtGid = PvcArtGid)),
    if @PrijsOpnieuwBepalen = 1 or PvcDoorbelastPercentage is not null then
      null
    else
      //TG 17-09-2009, 14:24u: oplossing voor bug 31108; delen door 0 kan niet; in dat geval is waarde dus gewoon 0.
      if PvcoffAantal = 0 then
        0
      else
        round(PvcOfferteBedrag * round(PvcoffAantal * @Factor, (select ArtAantDecAantallen from tabArtikel where ArtGid = PvcArtGid))/PvcOffAantal,2)
      endif
    endif,
    PvcOmschr, PvcPartFactEenheidFactor, @DoelPbGid, PvcPdosGid, PvcPrijsPer, @DoelProjGid, PvcRelGid,
    if @PrijsOpnieuwBepalen = 1 or PvcDoorbelastPercentage is not null then null else PvcVerkoopprijs endif,
    @DoelVolgNr, PvcSelectieCodes, PvcIsDirecteInkoop, PvcLeverancierNawGid,
    if @PrijsOpnieuwBepalen = 1 then null else PvcDoorbelastPercentage endif
  from
    tabProjectVoorcalculatie where PvcGid = @PvcGid;

  set @@ErrorTextProcedure = 'KopierenProjectVoorcalculatie';
  //call TraceEind(@@ErrorTextProcedure);


end;


