create or replace function LaatsteBetaling(in @BjGid integer, in @OspGid integer, in @SoortBoeking smallint)
returns integer
begin
  // Geef JrGid terug die als laatste betaling gebruikt is behorende bij een meegegeven OspGid
  declare @JrGid integer;
  //@SoortBoeking: 0=definitief, 1=voorlopig, 2=beide

  //call TraceBegin('LaatsteBetaling > @BjGid = ' + string(@BjGid) + ', @OspGid = ' + string(@OspGid));

  select first JrGid into @JrGid
  from         tabBoekingsgang
  inner join   tabJournaalPost on (JpBoekgangGid = BoekgangGid)
  inner join   tabJournaalregel on (JrJpGid = JpGid)
  where        BoekGangBjGid = @BjGid and JrOspGid = @OspGid and IsBetaling(JrRksGid, IsCreditBoeking) = 1 and
               (@SoortBoeking=2 or IsBoekgangDefinitief=1-@SoortBoeking)
  order by     JrBoekDatum desc, JrGid desc;

  //call TraceEind('LaatsteBetaling > @JrGid = ' + string(@JrGid));
  return(@JrGid)
end;


//---------- Toon laatste deelbetaling van een debiteur/crediteur
create or replace procedure LaatsteDeelbetaling(in @OspGid integer, in @BjGid integer, in @Status smallint)
result (BoekDatum date, Dgbcode nchar(10), Stukvolgnr nchar(16))
begin
  //call TraceBegin('LaatsteDeelbetaling (@OspGid='+string(@OspGid)+',@BjGid='+string(@BjGid)+', @Status='+string(@Status)+')');
  //call TraceEind('LaatsteDeelbetaling');

  if exists(select 1 from tabJournaalregel where JrBjGid=@BjGid and JrOspGid=@OspGid and IsBetaling(JrRksGid, IsCreditBoeking) = 1) then
    if @status = 0 then     //Definitieve
      select   first JrBoekdatum BoekDatum, JrDgbcode Dgbcode, string(JrBoekstukNummer)+'.'+Right(repeat('0',3)+string(StukVolgnr),3) Stukvolgnr
      from     tabJournaalregel
      where    JrBjGid = @BjGid and JrOspGid = @OspGid and IsBetaling(JrRksGid, IsCreditBoeking) = 1 and RegelNummer is not null
      order by JrBoekDatum desc, JrGid desc;
    else
      if @status=1 then     //Voorlopige bedragen
        select   first JrBoekdatum BoekDatum, JrDgbcode Dgbcode, string(JrBoekstukNummer)+'.'+Right(repeat('0',3)+string(StukVolgnr),3) Stukvolgnr
        from     tabJournaalregel
        where    JrBjGid = @BjGid and JrOspGid = @OspGid and IsBetaling(JrRksGid, IsCreditBoeking) = 1 and RegelNummer is null
        order by JrBoekDatum desc, JrGid desc;
      else                  //Definitieve + Voorlopige bedragen
        select   first JrBoekdatum BoekDatum, JrDgbcode Dgbcode, string(JrBoekstukNummer)+'.'+Right(repeat('0',3)+string(StukVolgnr),3) Stukvolgnr
        from     tabJournaalregel
        where    JrBjGid = @BjGid and JrOspGid = @OspGid and IsBetaling(JrRksGid, IsCreditBoeking) = 1
        order by JrBoekDatum desc, JrGid desc
      end if;
    end if;
  else
    select cast(null as Date) BoekDatum, cast( '' as nchar(10)) Dgbcode, cast('' as nchar(16)) Stukvolgnr
  end if;


end;


