create or replace function LeesArtikelTekst(
  in @ArtGid               integer,
  in @NawGid               integer,
  in @InkoopEenheid        nchar(20),
  in @ArtPartijGid         integer,
  in @TaalGid              integer,
  in @TbvInkoop            smallint //0 = ten behoeve van verkoop, 1 = ten behoeve van inkoop
)
  returns long nvarchar
begin
  declare @result long nvarchar;

  set @@ErrorTextProcedure = 'LeesArtikelTekst';
  //call TraceBegin(@@ErrorTextProcedure);

  if @TbvInkoop = 1 then
    // Omschrijving bij leverancier
    select first AldOmsBijLeverancier ArtTekst
    into   @result
    from   tabArtikelLeverancier
           inner join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid)
           inner join tabArtikel on (ArtGid = ArtLevArtGid)
    where  ArtGid              = @ArtGid
       and ArtLevNawGid        = @NawGid
       and AldInkoopEenheid    = @InkoopEenheid
       and isNull(ArtTekst,'') <> '';
  end if;

  if @result is null then
    select first ArtPartijTekstOpFactuur ArtTekst
    into   @result
    from   tabArtikelPartijTeksten
    where  ArtPartijTekstArtPartijGid = @ArtPartijGid
       and ArtPartijTekstTaalGid      = @TaalGid
       and isNull(ArtTekst,'') <> '';
  end if;

  if @result is null then
    SELECT first ArtPartijTekstOpFactuur ArtTekst
    into   @result
    FROM   tabArtikelPartijTeksten
           inner join tabVasteGegevens on (DefaultTaalGid=ArtPartijTekstTaalGid)
    WHERE  ArtPartijTekstArtPartijGid = @ArtPartijGid
       AND isNull(ArtTekst,'') <> '';
  end if;

  if @result is null then
    SELECT ArtTekst
    into   @result
    FROM   tabArtikelTeksten
    WHERE  ArtTekstArtGid = @ArtGid
       AND ArtTaalGid = @TaalGid
       AND isNull(ArtTekst,'') <> '';
  end if;

  if @result is null then
    // Tekst van artikel o.b.v. default taal
    SELECT ArtTekst
    into   @result
    FROM   tabArtikelTeksten
           inner join tabVasteGegevens on (DefaultTaalGid=ArtTaalGid)
    WHERE  ArtTekstArtGid = @ArtGid
    AND    isNull(ArtTekst,'') <> '';
  end if;

  if @result is null then
    // Partijomschrijving
    SELECT ArtPartijOms ArtTekst
    into   @result
    FROM   tabArtikelPartij
    WHERE  ArtPartijGid = @ArtPartijGid
       AND isNull(ArtTekst,'') <> '';
  end if;

  if @result is null then
    // Interne omschrijving van artikel
    SELECT ArtOms ArtTekst
    into   @result
    FROM   tabArtikel
    WHERE  ArtGID = @ArtGid;
  end if;

  //call TraceEind(@@ErrorTextProcedure);

  return @Result;
end;


create or replace function LeesBtcExtraTekst(in @BtcNummer integer, in @taalgid integer, in @valnummer integer, in @datum date, in @BtcBedrag numeric(15,2))
