//$Workfile: LeesCatalogusRubrieken.sp $ $Revision: 2 $ $Modtime: 3-07-09 13:37 $'

if exists (select 1 from sys.sysProcedure where proc_name='LeesCatalogusRubrieken') then
  drop procedure LeesCatalogusRubrieken;
end if;

//catalogusrubrieken platslaan en in de juiste volgorde in de printtabel zetten. deze functie roept zichzelf recursief aan.
create procedure LeesCatalogusRubrieken(in @CatGid integer, in @ParentCatrGid integer, in @LockNummer integer, in @StartNiveau integer, inout @prnCaruCatrGidNiveau1 integer, inout @prnCaruCatrGidNiveau2 integer, inout @prnCaruCatrGidNiveau3 integer, inout @prnCaruCatrGidNiveau4 integer, inout @prnCaruCatrGidNiveau5 integer)
begin
  declare @CatrGid             integer;
  declare @CatrCoderingRubKop  numeric(10,0);
  declare @CatrCoderingRubVoet numeric(10,0);
  declare @CatrNiveau          integer;

  declare cursor_Rubrieken dynamic scroll cursor for
    select   CatrGid, CatrCoderingRubKop, CatrCoderingRubVoet, (CatrNiveau - IsNull(@StartNiveau, 0))
    from     tabCatalogusRubriek
    where    CatrCatGid    = @CatGid
         and IsNull(CatrParentGid, -1) = IsNull(@ParentCatrGid,-1)
    order by CatrVolgnr
  for update;


  open cursor_Rubrieken;
  LoopRubriek:
  loop
    Fetch next cursor_Rubrieken into @CatrGid, @CatrCoderingRubKop, @CatrCoderingRubVoet, @CatrNiveau;
    if sqlstate = '02000' then
      leave LoopRubriek;
    end if;

    if @CatrNiveau < 1 then
      set @prnCaruCatrGidNiveau1 = null;
    else
      if @CatrNiveau = 1 then
        set @prnCaruCatrGidNiveau1 = @CatrGid;
      end if;
    end if;

    if @CatrNiveau < 2 then
      set @prnCaruCatrGidNiveau2 = null;
    else
      if @CatrNiveau = 2 then
        set @prnCaruCatrGidNiveau2 = @CatrGid;
      end if;
    end if;

    if @CatrNiveau < 3 then
      set @prnCaruCatrGidNiveau3 = null;
    else
      if @CatrNiveau = 3 then
        set @prnCaruCatrGidNiveau3 = @CatrGid;
      end if;
    end if;

    if @CatrNiveau < 4 then
      set @prnCaruCatrGidNiveau4 = null;
    else
      if @CatrNiveau = 4 then
        set @prnCaruCatrGidNiveau4 = @CatrGid;
      end if;
    end if;

    if @CatrNiveau < 5 then
      set @prnCaruCatrGidNiveau5 = null;
    else
      if @CatrNiveau = 5 then
        set @prnCaruCatrGidNiveau5 = @CatrGid;
      end if;
    end if;

    insert into prnCatalogusRubriek (prnCaruGid , prnCaruCatrGid, prnCaruVolgNr, prnCaruIsKop, prnCaruCoderingRubKop, prnCaruCoderingRubVoet, prnCaruCatrGidNiveau1, prnCaruCatrGidNiveau2, prnCaruCatrGidNiveau3, prnCaruCatrGidNiveau4, prnCaruCatrGidNiveau5)
    values                          (@LockNummer, @CatrGid      , (select IsNull(count(*), 0)+1 from prnCatalogusRubriek where PrnCaruGid = @LockNummer), 1, @CatrCoderingRubKop, -1, @prnCaruCatrGidNiveau1, @prnCaruCatrGidNiveau2, @prnCaruCatrGidNiveau3, @prnCaruCatrGidNiveau4, @prnCaruCatrGidNiveau5);

    call LeesCatalogusRubrieken(@CatGid, @CatrGid, @LockNummer, @StartNiveau, @prnCaruCatrGidNiveau1, @prnCaruCatrGidNiveau2, @prnCaruCatrGidNiveau3, @prnCaruCatrGidNiveau4, @prnCaruCatrGidNiveau5);

    insert into prnCatalogusRubriek (prnCaruGid , prnCaruCatrGid, prnCaruVolgNr, prnCaruIsKop, prnCaruCoderingRubKop, prnCaruCoderingRubVoet, prnCaruCatrGidNiveau1, prnCaruCatrGidNiveau2, prnCaruCatrGidNiveau3, prnCaruCatrGidNiveau4, prnCaruCatrGidNiveau5)
    values                          (@LockNummer, @CatrGid      , (select IsNull(count(*), 0)+1 from prnCatalogusRubriek where PrnCaruGid = @LockNummer), 0, -1, @CatrCoderingRubVoet, @prnCaruCatrGidNiveau1, @prnCaruCatrGidNiveau2, @prnCaruCatrGidNiveau3, @prnCaruCatrGidNiveau4, @prnCaruCatrGidNiveau5);

  end loop LoopRubriek;
  close cursor_Rubrieken;

end;


create or replace procedure LeesUpdateGarantieSerieNummer(
  in @SerieGid   integer,    // Te wijzigen serienummer
  in @VanAfDatum date,       // Leverdatum oid. De garantie t/m datum wordt berekend obv. deze begindatum
  in @ForceUpdate smallint,  // 0 = updaten volgens instelling bij artikel EN als garantiedatum nog niet was ingevuld
                             // 1 = updaten volgens instelling bij artikel, ongeacht of het al was gevuld
                             // 2 = altijd updaten, ongeacht instelling bij artikel en ongeacht of het al was ingevuld
  out @GarantieTMdatum date,
  out @TermijnEenheid smallint,
  out @TermijnAantal integer,
  out @Bepaling long nvarchar,
  out @MoetDatumUpdaten    smallint,
  out @MoetBepalingUpdaten smallint)
begin
  // Update de garantiebepalingen van het serienummer
  // Let op: het updaten van de garantiebepaling is altijd onafhankelijk van de instellingen bij het artikel! (Zie DO serienummers)
  declare @ErrText nchar(500);

  set @ErrText = 'LeesUpdateGarantieSerieNummer(@SerieGid='+string(@SerieGid)+')';
  set @@ErrorTextProcedure = @ErrText;
  //call TraceBegin(@@ErrorTextProcedure);

  set @MoetDatumUpdaten    = 0;
  set @MoetBepalingUpdaten = 0;

  select if (@ForceUpdate = 0 and ArtGarantieVullenBijLeveren <> 0 and ArtSerieGarantieTmDatum is null) or
            (@ForceUpdate = 1 and ArtGarantieVullenBijLeveren <> 0) or
            (@ForceUpdate = 2) then
            1
          else
            0
          endif,
          if (@ForceUpdate in (0,1) and ArtGarantieVullenBijLeveren <> 0 and ArtSerieGarantieBepalingen is null) or
             (@ForceUpdate = 1 and ArtGarantieVullenBijLeveren <> 0) or
             (@ForceUpdate = 2) then
            1
          else
            0
          endif,
          GcTermijnAantal,
          GcTermijnEenheid,
          GcOpmerking
  into @MoetDatumUpdaten, @MoetBepalingUpdaten, @TermijnAantal, @TermijnEenheid, @Bepaling
  from  tabArtikelSerienummer
        inner join tabArtikel on ArtGid = ArtSerieArtGid
        left outer join tabGarantieCode on (GcGid = ArtGcGid)
  where ArtSerieGid = @SerieGid;


  set @@ErrorTextProcedure = @ErrText + ' > @MoetDatumUpdaten='+string(@MoetDatumUpdaten)+', @MoetBepalingUpdaten='+string(@MoetBepalingUpdaten)+', @TermijnAantal='+string(@TermijnAantal)+', @TermijnEenheid='+string(@TermijnEenheid);
  //call Trace(@@ErrorTextProcedure);

  if @MoetDatumUpdaten <> 0 or @MoetBepalingUpdaten <> 0 then
    set @@ErrorTextProcedure = @@ErrorTextProcedure + ' > Update serienummer!';
    //call Trace(@@ErrorTextProcedure);

    select
    if @MoetDatumUpdaten <> 0 then
      case @TermijnEenheid
      when 0 then // Dagen
        dateadd(day,   @TermijnAantal, @VanAfDatum)
      when 1 then // maand(en)
        dateadd(month, @TermijnAantal, @VanAfDatum)
      when 2 then // jaar
        dateadd(year,  @TermijnAantal, @VanAfDatum)
      when null then // Geen garantiebepaling -> leegmaken!
        null
      end
    else
      ArtSerieGarantieTmDatum
    endif,
    if @MoetDatumUpdaten <> 0 then
      @TermijnEenheid
    else
      ArtSerieGarantieTermijnEenheid
    endif,
    if @MoetDatumUpdaten <> 0 then
      @TermijnAantal
    else
      ArtSerieGarantieTermijnAantal
    endif,
    if @MoetBepalingUpdaten <> 0 then
      @Bepaling
    else
      ArtSerieGarantieBepalingen
    endif
    into @GarantieTMdatum, @TermijnEenheid, @TermijnAantal, @Bepaling
    from   tabArtikelSerienummer
    where  ArtSerieGid = @SerieGid;
  end if;

   set @@ErrorTextProcedure = @ErrText + ' > @GarantieTMdatum='+string(@GarantieTMdatum)+', @TermijnEenheid='+string(@TermijnEenheid)+', @TermijnAantal='+string(@TermijnAantal)+', @Bepaling='+string(@Bepaling);
   //call Trace(@@ErrorTextProcedure);

  set @@ErrorTextProcedure = 'CreateSerieNummer(@SerieGid='+string(@SerieGid)+')';
   //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure LeverenAanmakenBoekingsgang( in @fbGid integer, in @BoekDatum date, out @BoekgangGid integer, out @DgbGid integer)
begin
  //Boeken van de hele facturering-batch
  //LET OP: Emballage nog niet geimplementeerd!!
  declare @BjGid                 integer;
  declare @PerNr                 integer;
  declare @fkGid                 integer;

  set @@ErrorTextProcedure = 'LeverenAanmakenBoekingsgang >';
  //call TraceBegin(@@ErrorTextProcedure + '@fbGid = ' + string(@fbGid) + ', @BoekDatum = ' + string(@BoekDatum));

  // *** vaste gegevens opvragen ***

  //Eerst dagboek tbv. leveren opvragen
  select first vofLevDgbGid into @DgbGid from tabVasteGegevensOrdersFactureren;

  // *** Nu boeken ***

  call BepaalBoekjaarEnPeriode( @BoekDatum, @BjGid, @PerNr );

  //Aanmaken van nieuwe boekingsgang en locken
  insert into tabBoekingsGang(BoekGangBjGid, BoekGangBronId, BronOms, BoekGangInGebruik, IsBoekGangDefinitief) values ( @BjGid, 21, _A('Leveren batch'), 1, 0 );
  set @BoekgangGid = @@Identity;

  //Aanmaken van de leveroverzicht-lock
  call LockSetOnId(@@SpId, @@LoginTime, 0, 'tabLeverOverzichtOpbrengst', string(@FbGid), 0);

  set @@ErrorTextProcedure = 'LeverenAanmakenBoekingsgang';
  //call TraceEind(@@ErrorTextProcedure + ' > @BoekgangGid = ' + string(@BoekgangGid));
end;


create or replace procedure LeverenBoekLevering(in @fbGid integer, in @fkGid integer, in @fkFactuurNummer nchar(40), in @DgbGid integer, in @Boekdatum date, in @BoekgangGid integer)
begin
  declare @Oms                   nchar(40);
  declare @JpGid                 integer;
  //Lus voor facturen in factuurbatch
  declare @fkInclBtw             smallint;

  //Direct nodig voor boeken
  declare @GrpSoortRksGID        integer;
  //Loop voor opbrengstgroepen
  declare @OrkNummer             nchar(10);
  declare @OpbrGrpNummer         nchar(4);
  declare @OpbrGrpGid            integer;
  declare @Kostprijs             numeric(15,2);
  declare @EersteActie           smallint;
  declare @VoorraadBedrag        numeric(15,2);
  declare @AantDecimalenBasis    integer;

  declare Cursor_tabOpbrengstgroep dynamic scroll cursor for
    select   EersteActie, OpbrGrpNummer,  OpbrGrpGid
    from     tmpEersteActie, tabFactuurRegel inner join tabFactuurreferentie on (frefGid = frFrefGid) inner join tabOpbrengstgroep on (OpbrGrpnummer = frOpbrGrpNummer) inner join tabOrderkop on (frefOrkGid = OrkGid)
    where    frefFkGid = @fkGid
    group by EersteActie, OpbrGrpNummer,  OpbrGrpGid
    order by EersteActie desc, OpbrGrpNummer
  for read only;
  declare Cursor_PerOrderKostprijzen scroll cursor for
    select sum( round(isnull(frKostprijs/frPrijsPer * frAantalDezeLeveringVrrdEenh, 0), @AantDecimalenBasis) )
    from   tabFactuurRegel inner join tabFactuurReferentie on (frfrefgid = frefgid) inner join taborderkop on (OrkGid = frefOrkGid)
    where  frefFkGid = @fkGid and
           frOpbrGrpNummer = @OpbrGrpNummer and
           ((OrkEersteActie = @EersteActie) or (@EersteActie = 2 and OrkEersteActie = 0)) and
           frSoortRegel = 2  //Alleen de artikelregels!!
  for read only;

  declare local temporary table tmpEersteActie
   (EersteActie integer null) on commit preserve rows;

  set @@ErrorTextProcedure = 'LeverenBoekLevering > ';
  //call TraceBegin(@@ErrorTextProcedure + '@fbGid = ' + string(@fbGid) + ', @fkGid = ' + string(@fkGid) + ', @fkFactuurNummer = ' + @fkFactuurNummer + ', @BoekgangGid = ' + string(@BoekgangGid));

  insert into tmpEersteActie(EersteActie) values(1); //Eerste actie 1 = Factureren
  insert into tmpEersteActie(EersteActie) values(2); //Eerste actie 2 = Leveren

  select DecimalenBoeking*2 into @AantDecimalenBasis from tabvaluta where ValNummer=@@BasisValutaNummer;

  //Opvragen of de factuur in- of excl. BTW is
  select fkIsInclBtw into @fkInclBtw from tabFactuurkop where fkgid = @fkgid;

  // maak journaalpost aan
  select LeverenBoekMaakJpOms(@fkGid, @fkFactuurNummer) into @Oms;
  insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum)
  select @BoekGangGid, 1, @DgbGid, @fkFactuurNummer, @Oms, @Boekdatum;
  set @JpGid = @@Identity;

  // Journaalpost in de levering onthouden
  update tabFactuurKop set FkJpGid = @JpGid where FkGid = @FkGid;

  // Hier de tussenrekening pas boeken, o.b.v. eerste rekening etc.
  begin
    declare @GeFactureedeGoederenRksGid integer;
    declare @TeFacturerenGoederenRksGid integer;

    select first vofGeFactureedeGoederenRksGid, vofTeFacturerenGoederenRksGid into @GeFactureedeGoederenRksGid, @TeFacturerenGoederenRksGid from tabVasteGegevensOrdersFactureren;

    // Per verkooporder apart (defect 57065), daarom niet meer in de lussen hierboven
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                 IsCreditBoeking, SoortBoeking, JrValNummer, JrReferentie )
    select @JpGid,
           if EersteActie = 1 /*factureren*/ then @GeFactureedeGoederenRksGid else @TeFacturerenGoederenRksGid endif RksGid,
           isnull(round(
             sum( round(isnull(frKostprijs/frPrijsPer * frAantalDezeLeveringVrrdEenh, 0), @AantDecimalenBasis) )
           , (select DecimalenBoeking*2 from tabvaluta where ValNummer=@@BasisValutaNummer)),0) Kostprijs,
           Kostprijs,
           @oms,
           0 /*Is debet boeking*/,
           0 /*Normale boeking*/,
           @@BasisValutaNummer,
           frefOrderNummer
    from   tmpEersteActie,
           tabFactuurRegel
           inner join tabFactuurReferentie on (frfrefgid = frefgid)
           inner join taborderkop on (OrkGid = frefOrkGid)
    where  frefFkGid = @fkGid and
           ((OrkEersteActie = EersteActie) or (EersteActie = 2 and OrkEersteActie = 0)) and
           frSoortRegel = 2  //Alleen de artikelregels!!
    group by frefOrderNummer, RksGid
    having Kostprijs <> 0
    order by frefOrderNummer;

  end;

  //Loop opbrengstgroepen in de factuur
  open Cursor_tabOpbrengstgroep;
  LoopOpbrengstGroep:
  loop
    Fetch next Cursor_tabOpbrengstgroep into @EersteActie, @OpbrGrpNummer, @OpbrGrpGid;
    if sqlstate = '02000' then
      leave LoopOpbrengstGroep;
    end if;
    if isnull(@EersteActie,0) = 0 then
      set @EersteActie = 2; //Leveren
    end if;

    select first frefOrderNummer into @OrkNummer from tabFactuurReferentie where FrefFkGid = @FkGid;

    //Kostprijs berekenen (gelijk aan de facturatie natuurlijk!)

    //Per order verwerken!
    open Cursor_PerOrderKostprijzen;
    loop_PerOrderKostprijs:
    loop
      //call Trace('In lus!');
      Fetch next Cursor_PerOrderKostprijzen into @Kostprijs;
      if sqlstate = '02000' then
        leave loop_PerOrderKostprijs;
      end if;
      //call Trace('@OrkNummer='+string(@OrkNummer)+', @Kostprijs='+string(@Kostprijs));

      //Voorraadbedrag berekenen
      select sum( round(isnull((if ArtIsPartijAparteKostPrijs = 0 or ArtIsPartijRegistreren = 0 or ArtPartijKostprijsEx is null then artKostprijsEx else ArtPartijKostprijsEx endif) * frAantalDezeLeveringVrrdEenh/ArtPrijsPer,0), @AantDecimalenBasis) )
      into   @VoorraadBedrag
      from   tabFactuurRegel
             inner join tabFactuurReferentie on (frfrefgid = frefgid)
             inner join tabOpbrengstGroep on (frOpbrGrpNummer = OpbrGrpNummer)
             inner join taborderkop on (OrkGid = frefOrkGid)
             inner join tabOrderRegel on (OrrOrkGid = OrkGid and OrrRegelnr = frRegelNummer)
             inner join tabArtikel on (ArtGid = OrrArtGid)
             left outer join tabArtikelPartij on (ArtPartijGid = OrrArtPartijGid)
      where  frefFkGid = @fkGid and
             frSoortRegel = 2 and //Alleen de artikelen boeken
             OpbrGrpGid = @OpbrGrpGid and
             (OrkEersteActie = @EersteActie or (OrkEersteActie = 0 and @EersteActie = 2));
      set @VoorraadBedrag = isnull(round(@VoorraadBedrag, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@@BasisValutaNummer)),0);

      //Boeking: Tussenrekening (oude kostprijs)... Aan voorraad (vvp) ... (aan) herwaardering

      //Boeken van Kostprijs ...
      set @kostprijs = isnull(round(@Kostprijs, (select DecimalenBoeking*2 from tabvaluta where ValNummer=@@BasisValutaNummer)),0);
      if @Kostprijs <> 0 then

        if @EersteActie = 1 then //+++Rekening 'te leveren goederen'
          select first vofGeFactureedeGoederenRksGid into @GrpSoortRksGID from tabVasteGegevensOrdersFactureren;
          //Leveroverzicht onthouden: tussenrekening Gefactureerde goederen
          insert into tabLeverOverzichtTussenrekening(lotBoekgangGid, lotBedragGefact, lotFbGid) values( @BoekGangGid, @Kostprijs, @FbGid );
        else                     //+++Rekening 'te factureren goederen'
          select first vofTeFacturerenGoederenRksGid into @GrpSoortRksGID from tabVasteGegevensOrdersFactureren;
          //Leveroverzicht onthouden: tussenrekening Te factureren goederen
          insert into tabLeverOverzichtTussenrekening(lotBoekgangGid, lotBedragTeFact, lotFbGid) values( @BoekGangGid, @Kostprijs, @FbGid );
        end if;

        //Leveroverzicht onthouden: Kostprijs
        insert into tabLeverOverzichtOpbrengst(LooOpbrGrpGid, LooRksGidKostprijs, LooBoekGangGID, looBedragKostprijs, looFbGid)
        values( @OpbrGrpGid, @GrpSoortRksGID, @BoekGangGid, @Kostprijs, @FbGid );


      end if;
      //!!! AAN VOORRAAD (tegen VVP)

      //Voorraadrekening opzoeken en evt. aanmaken
      call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 50, @GrpSoortRksGID); //Voorraad

      //En hier echt boeken
      if @VoorraadBedrag <> 0 then
        //call Trace('Boek AAN VOORRAAD: '+string(@VoorraadBedrag));
        insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel,
                                     IsCreditBoeking, SoortBoeking, JrValNummer )
          values( @JpGid, @GrpSoortRksGID, @VoorraadBedrag, @VoorraadBedrag, @oms, 1, 0, @@BasisValutaNummer);

        //Voorraadbedrag in leveroverzicht onthouden
        insert into tabLeverOverzichtOpbrengst(LooOpbrGrpGid, LooRksGidVvp, LooBoekGangGID, looBedragVvp, looFbGid)
        values( @OpbrGrpGid, @GrpSoortRksGID, @BoekGangGid, @VoorraadBedrag, @FbGid );
      end if;

      //Herwaardering
      if @VoorraadBedrag <> @Kostprijs then
        call BoekHerwaardering(@OpbrGrpGid, @VoorraadBedrag, @Kostprijs, @JpGid, @Oms);

        //Leveroverzicht: herwaardering onthouden
        insert into tabLeverOverzichtOpbrengst(LooOpbrGrpGid, LooRksGidHerwaardering, LooBoekGangGID, looBedragHerwaardering, looFbGid)
        values( @OpbrGrpGid, @GrpSoortRksGID, @BoekGangGid, @VoorraadBedrag - @Kostprijs, @FbGid );

      end if;
    end loop loop_PerOrderKostprijs;
    close Cursor_PerOrderKostprijzen;

    //einde loop opbr.groepen
  end loop LoopOpbrengstGroep;



  call Maatwerk_Levering(@fkGid);

  //sluit journaalpost af
  update tabJournaalPost set JpIsIngebruik = 0 where jpGid = @JpGid;

  set @@ErrorTextProcedure = 'LeverenBoekLevering';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace function LeverenBoekMaakJpOms(in @fkGid integer, in @LeverNummer nchar(40))
returns nchar(40)
begin
  declare @tempInt integer;
  declare @oms     nchar(40);

  set @@ErrorTextProcedure = 'LeverenBoekMaakJpOms(@fkGid='+string(@fkGid)+', @LeverNummer='+@LeverNummer+')';
  //call TraceBegin(@@ErrorTextProcedure);
  select vofLevOmsWelke  into @tempInt from tabvasteGegevensOrdersFactureren;
  case @tempInt
  when 0 then //OrderRef.
    select first frefOms into @Oms from tabFactuurKop inner join tabFactuurReferentie on (frefFkGid = FkGid) where fkGid = @fkGid order by frefOrderNummer;
  when 1 then //tekst 'Factuur'
    set @oms=_A('Levering');
  when 2 then //Debiteurnaam
    select first faNaam1 into @Oms from tabFactuurKop inner join tabFactuurReferentie on freffkgid = fkgid inner join tabFactuurAdres on fafrefGid = frefGid where faSoortAdres = 12 and fkGid = @FkGid;
  when 3 then //tekst 'Factuur' + nummer
    set @oms=_A('Levering %1!', @LeverNummer);
  when 4 then //tekst 'Factuur' + nummer + debiteurnaam
    select  first _A('Levering %1! %2!', @LeverNummer, faNaam1) into @Oms from tabFactuurKop inner join tabFactuurReferentie on freffkgid = fkgid inner join tabFactuurAdres on fafrefGid = frefGid where faSoortAdres = 12 and fkGid = @FkGid;
  when 5 then //Anders
    select vofLevOms into @Oms from tabvasteGegevensOrdersFactureren;
  end case;
  //call TraceEind(@@ErrorTextProcedure + '(=>@Oms='+@Oms+')');
  return (@oms);

end;


