if exists (select 1 from sys.sysProcedure where proc_name='LeverenSluitenBoekingsgang') then
  drop procedure LeverenSluitenBoekingsgang;
end if;

create procedure LeverenSluitenBoekingsgang(in @fbGid integer, inout @BoekgangGid integer)
begin
  //Boeken van de hele facturering-batch
  //LET OP: Emballage nog niet geimplementeerd!!

  set @@ErrorTextProcedure = 'LeverenSluitenBoekingsgang > @FbGid='+string(@FbGid);
	//call TraceBegin(@@ErrorTextProcedure);

  //Afsluiten van boekingsgang
  update tabBoekingsgang set BoekGangInGebruik = 0 where BoekgangGid = @BoekGangGid;

  //Ontkoppelen van de boekingsgang aan de factureerhistorie
  //update tabFactuurBatch set fbBoekganggid = null where fbGid = @fbGid; //Is geboekt, dus akkoord!

  //Als de boekingsgang leeg is (alleen tekstregels oid.) dan is die verwijderd, dus ook niet teruggeven
  if not exists(select 1 from tabBoekingsgang where BoekgangGid = @BoekGangGid) then
    // ACW 6-6-2002: Eerst de lock ongedaan maken
    call LockReleaseOnId(@@SpId, @@LoginTime, 0, 'tabLeverOverzichtOpbrengst', string(@FbGid));
    // Daarna doorgeven dat er GEEN boekingsgang (meer) is
    set @BoekGangGid = null;
    //call Trace('LeverenSluitenBoekingsgang -> Boekingsgang verwijderd!');
  end if;

  //call TraceEind('LeverenSluitenBoekingsgang');

end;


create or replace procedure LeverenUpdateVoorraadOrderAantallen(in @BoekDatum date, in @FkGid integer)
begin
  //Lever elke order in de batch; ook de orderaantallen van leveringen updaten
  declare @OrkGid integer;
  // NOTE DG: Let op hier komt FKFactuurnummer in die nchar(40) is. Maar in de praktijk max 10 chars bevat. Het aanroepen van OrderLeveren.sp heeft als param Numeric (10,0) maar gaat in
  // in voorraadmutatie VrdMutUitleverOntvangstNr die voorlopig nchar (10) blijft.
  // Overlegd en afgestemd met ACW.
  declare @UitleverNummer nchar(10);
  declare @FkJpGid integer;
  declare cursor_Orders_TeLeveren dynamic scroll cursor for
    select frefOrkGid, fkFactuurNummer, fkJpGid from tabFactuurKop inner join tabFactuurReferentie on (frefFkGid = FkGid) where FkGid = @FkGid
  for read only;

  set @@ErrorTextProcedure = 'Begin LeverenUpdateVoorraadOrderAantallen > @FkGid = ' + string(@FkGid);
  //call Trace(@@ErrorTextProcedure);

  open cursor_Orders_TeLeveren;
  loopje:
  loop
    Fetch next cursor_Orders_TeLeveren into @OrkGid, @UitleverNummer, @FkJpGid;
    if sqlstate = '02000' then
      leave loopje;
    end if;
    call OrderLeveren(@OrkGid, @BoekDatum, @UitleverNummer, @FkJpGid);
  end loop loopje;
  close cursor_Orders_TeLeveren;

  set @@ErrorTextProcedure = 'Einde LeverenUpdateVoorraadOrderAantallen';
  //call Trace('LeverenUpdateVoorraadOrderAantallen');
end;


//------------------------------------------------------------------
//  Quadrant maatwerk, Licenties, query voor Checksum of UBF mailing
//------------------------------------------------------------------
create or replace procedure LicentiesChecksumOfUbfMailing
(
  in @PktsGid                              integer,     //pakketsoort
  in @PktrGid                              integer,     //pakketrelease
  in @CommaSeperatedStringVersieGids       nchar(100),  //pakketversie
  in @CommaSeperatedStringLicOnderhoud     nchar(100),
  in @CommaSeperatedStringLicSoorten       nchar(100),  //0=standaard, etc        zie meta
  in @UitleverDatum                        DateTime,
  in @VloDefBeide                          smallint,    //0=Definitief, 1=voorlopig, 2=beide
  in @UpdateVia                            smallint,    //0=cd-rom, 1=download, 2=beide
  in @InclIncasso                          smallint,    //0=nee, 1=ja
  in @InclSupportBlokkade                  smallint,    //0=nee, 1=ja
  in @InclOnline                           smallint,    //0=offline, 1=online, 2=beide
  in @InclOptieTijdelijkeVersie            smallint,    //0=nee, 1=ja
  in @LicHosting                           nchar(40),   //hostingtekst
  in @MailCodeSelectie                     smallint,    //0=Afwezig zijn in notities, 1=Aanwezig zijn in notities, 2=beide
  in @mailcode                             nchar(40)    //bijvoorbeeld: %[[]QMailing0702]% \. Alleen gebruikt vanuit licentiemailing
)

result
(
  LicPktsGid                       integer,
  PktsCode				                 nchar(20),
  LicNummer				                 integer,
  LicNummerUitgevuld               integer,
  LicOnderhoud				             smallint,
  LicOnderhoudTm			             date,
  LicOnderhoudOpgezegdPer		       date,
  LicOnderhoudFormulierOntvangenOp date,
  LicSoort                         smallint,
  LicNawFilGid                     integer,
  NawFilNummer                     nchar(10),
  LicVervallenDoor                 nchar(10),
  LicVervallenOp                   date,
  LicCsNaam                        nchar(30),
  LicCsAdres                       nchar(30),
  LicCsPcw                         nchar(40),
  LicCsPktrGid                     integer,
  PktrCode                         nchar(10),
  pktvCode                         nchar(40),
  LicCsAantalGebruikers            integer,
  LicCsAantalWeken                 integer,
  LicCsChecksum                    nchar(30),
  LicCsCodeA                       nchar(40),
  LicCsCodeB                       nchar(40),
  LicCsIsDefinitief                smallint,
  LicCsOptieConfig                 nchar(161),
  LicCsOpties                      long nvarchar,
  LicGid                           integer,
  LicReserveVeld1                  nchar(40),
  LicReserveVeld2                  nchar(40),
  LicReserveVeld3                  nchar(40),
  LicCsPakketVersieID              smallint,
  LicCsPktvGid                     integer,
  LicEmailAdres                    nchar(80),
  LicUpdatesVia                    smallint,
  LicHosting                       nchar(40),
  LicCsHuurTm                      Date
)

begin
  declare @SelectieCode_AIC_Gid		           integer;
  declare @SelectieCode_AGU_Gid              integer;
  declare @CommaSeperatedStringVersieGids2   nchar(100);
  declare @CommaSeperatedStringLicSoorten2   nchar(100);
  declare @CommaSeperatedStringLicOnderhoud2 nchar(100);

  //call traceBegin('LicentiesChecksumOfUbfMailing');
  //call trace('@PktsGid                          ='+ string(@PktsGid));
  //call trace('@PktrGid                          ='+ string(@PktrGid));
  //call trace('@CommaSeperatedStringVersieGids   ='+ string(@CommaSeperatedStringVersieGids));
  //call trace('@CommaSeperatedStringLicOnderhoud ='+ string(@CommaSeperatedStringLicOnderhoud));
  //call trace('@CommaSeperatedStringLicSoorten   ='+ string(@CommaSeperatedStringLicSoorten));
  //call trace('@VloDefBeide                      ='+ string(@VloDefBeide));
  //call trace('@UpdateVia                        ='+ string(@UpdateVia));
  //call trace('@InclIncasso                      ='+ string(@InclIncasso));
  //call trace('@InclSupportBlokkade              ='+ string(@InclSupportBlokkade));
  //call trace('@InclOnline                       ='+ string(@InclOnline));
  //call trace('@InclOptieTijdelijkeVersie        ='+ string(@InclOptieTijdelijkeVersie));
  //call trace('@LicHosting                       ='+ string(@LicHosting));

  set @SelectieCode_AIC_Gid = null;
  set @SelectieCode_AGU_Gid = null;
  select slcGid into @SelectieCode_AIC_Gid from tabSelectiecodes where SlcCode = 'AIC' and SlcSltGid = (SELECT fonSltGid FROM tabFileOfNaw WHERE fonID = 'D');
  select slcGid into @SelectieCode_AGU_Gid from tabSelectiecodes where SlcCode = 'AGU' and SlcSltGid = (SELECT fonSltGid FROM tabFileOfNaw WHERE fonID = 'D');

  //2 input parameters: spaties weghalen, komma ervoor en erachter plakken, zodat locate in where goed werkt.
  set @CommaSeperatedStringVersieGids2   = ',' + replace(@CommaSeperatedStringVersieGids  ,' ','') + ',';
  set @CommaSeperatedStringLicSoorten2   = ',' + replace(@CommaSeperatedStringLicSoorten  ,' ','') + ',';
  set @CommaSeperatedStringLicOnderhoud2 = ',' + replace(@CommaSeperatedStringLicOnderhoud,' ','') + ',';

  //call traceEind('LicentiesChecksumOfUbfMailing');

select
  LicPktsGid,
  PktsCode,
  LicNummer,
  LicNummer LicNummerUitgevuld,
  LicOnderhoud,
  if ((Licsoort = 9) and (LicOnderhoudTm is null)) then LicCsHuurTm else LicOnderhoudTm endif, //Bij evaluatie is onderhoud t/m gelijk aan licentie t/m
  LicOnderhoudOpgezegdPer,
  LicOnderhoudFormulierOntvangenOp,
  LicSoort,
  LicNawFilGid,
  NawFilNummer,
  LicVervallenDoor,
  LicVervallenOp,
  LicCsNaam,
  LicCsAdres,
  LicCsPcw,
  LicCsPktrGid,
  PktrCode,
  pktvCode,
  LicCsAantalGebruikers,
  LicCsAantalWeken,
  LicCsChecksum,
  LicCsCodeA,
  LicCsCodeB,
  LicCsIsDefinitief,
  LicCsOptieConfig,
  LicCsOpties,
  LicGid,
  'LicRes1' LicReserveVeld1,
  'LicRes2' LicReserveVeld2,
  'LicRes3' LicReserveVeld3,
  LicCsPakketVersieID,
  LicCsPktvGid,
	LicEmailAdres,
  LicUpdatesVia,
  GetLicHosting(LicGid) as LicHosting,
  LicCsHuurTm,
  if EXISTS(SELECT 1 FROM tabLicentieOptiesCommercieel inner join tabOptiesCommercieel on (LicoOptcGid=OptcGid) WHERE OptcCode IN ('ASP','ASPLight') AND LicoLicGid=LicGid) then 1 else 0 endif IsOnlineLicentie
FROM tabLicentie left outer join tabPakketSoort   on pktsGid=LicPktsGid
                 left outer join tabPakketRelease on pktrGid=LicCsPktrGid
                 left outer join tabPakketversie  on pktvGid=LicCsPktvGid
                 left outer join (tabNawFile inner join tabNaw on NawGid=NawFilNawGid) on NawFilGid=LicNawFilGid
WHERE  (LicPktsGid   = @PktsGid)  //pakketsoort
  AND  (LicCsPktrGid = @PktrGid)  //pakketrelease
  AND  (LOCATE(@CommaSeperatedStringVersieGids2,(','+string(LicCsPktvGid)+','),1) <>0)//pakketversies
  AND  ((LOCATE(@CommaSeperatedStringLicOnderhoud2,(','+string(LicOnderhoud)+','),1) <>0)//Onderhoud Sab of Upa
         or ((LicOnderhoud = 0) and (LicSoort in (3,5))))  // Geen onderhoud maar licSoort = DealerDemo (3) of Verpl. dealerkit G-dealer (5)
  AND  (LOCATE(@CommaSeperatedStringLicSoorten2,(','+string(Licsoort)+','),1) <>0)//soorten
  AND  ((@VloDefBeide=0 and LicCsIsDefinitief=0) OR (@VloDefBeide=1 and LicCsIsDefinitief=1) OR (@VloDefBeide=2))//voorlopig/definitief/beide
       //===selectie eisen, niet op te geven in scherm========================================
  AND  (LicVervallenOp is null)//niet vervallen
//  AND  (LicOnderhoudOpgezegdPer is null or (IsOnlineLicentie=1 and LicOnderhoudTm > @UitleverDatum))
  AND  ((LicOnderhoudTm > @UitleverDatum) or ((LicOnderhoud = 0) and (LicOnderhoudTm is null)))
  AND  NOT EXISTS(SELECT 1 FROM tabSlcPerNaw WHERE (SpnSlcGid=@SelectieCode_AGU_Gid) and (SpnNawFilGid=LicNawFilGid))//naw met AGU (admin geen update) krijgen geen update
  AND  ((@InclIncasso <> 0) OR NOT EXISTS(SELECT 1 FROM tabSlcPerNaw WHERE (SpnSlcGid=@SelectieCode_AIC_Gid) and (SpnNawFilGid=LicNawFilGid)))//naw geen selcode AIC, ter incasso, alleen bij Checksum !!
  AND  (@InclSupportBlokkade <> 0 or NawBlokSupport <> 1)//naw geen supportblokkade
  AND  (@UpdateVia=2 or LicUpdatesVia=@UpdateVia) //parameter is 2, dan beide en in andere geval komt de variabele overeen met het veld uit de licentietabel
  AND
        //alleen geen onlines
    (   (@InclOnline = 0 and NOT EXISTS(SELECT 1 FROM tabLicentieOptiesCommercieel inner join tabOptiesCommercieel on (LicoOptcGid=OptcGid) WHERE OptcCode IN ('ASP','ASPLight') AND LicoLicGid=LicGid)//geen commerciele opties ASP(light) )
        //alleen onlines
     OR (@InclOnline = 1 and     EXISTS(SELECT 1 FROM tabLicentieOptiesCommercieel inner join tabOptiesCommercieel on (LicoOptcGid=OptcGid) WHERE OptcCode IN ('ASP','ASPLight') AND LicoLicGid=LicGid) and (IsNull(@LicHosting,'') = '' or LicHosting=@LicHosting))) //geen commerciele opties ASP(light)
        //zowel onlines als niet onlines
     OR (@InclOnline = 2)
    )
  AND  ((@InclOptieTijdelijkeVersie <> 0) OR NOT EXISTS(SELECT 1 FROM tabLicentieOptiesCommercieel inner join tabOptiesCommercieel on (LicoOptcGid=OptcGid) WHERE LicoLicGid=LicGid AND OptcCode = 'TijdelijkeVersie'))//geen commerciele optie TijdelijkeVersie
    // Controle op mailingcode
	AND (    (@MailCodeSelectie = 2)
       OR ((@MailCodeSelectie = 0) and ( NOT EXISTS(SELECT 1 FROM tabGespreksNotitie WHERE (GnotLicGid = LicGid) and (GnotNotitie like @mailcode)) ) )
       OR ((@MailCodeSelectie = 1) and (     EXISTS(SELECT 1 FROM tabGespreksNotitie WHERE (GnotLicGid = LicGid) and (GnotNotitie like @mailcode)) ) )
			)
ORDER BY PktsCode, PktrCode, pktvCode, LicNummer

end;
