//-------------------------------------------------------------------------------
//  Quadrant maatwerk, Licenties, query voor NAW data bij UBF en Checksum mailing
//-------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='LicentiesNAWdata') then
  drop procedure LicentiesNAWdata;
end if;

create procedure LicentiesNAWdata
(
  in @NawFilGid                            integer
)

result
(
  AdrNaam1				    nchar(40),
  AdrNaam2				    nchar(40),
  AdrStraat				    nchar(40),
  AdrHuisNummer				nchar(10),
  AdrPostcode				  nchar(40),
  AdrPlaats				    nchar(40),
  LndEigenCode				nchar(3),
  LndOms		          nchar(40),
  NawCP					      nchar(40),
  NawReserveVeld1			nchar(40),
  NawReserveVeld2			nchar(40),
  NawReserveVeld3			nchar(40),
  NawReserveVeld4			nchar(40),
  NawReserveVeld5			nchar(40),
  AdrEmail            nchar(80),
  CpEmail             nchar(80)
)

begin
  declare @FnCodeLicentie		integer;
  //ACW 09-11-2010: tbv. opzoeken vrije rubriek van een contactpersoon
  declare @FnCodeAdmin      integer;
  declare @DebFonGid   integer;
  declare @VeldNaamCP  nchar(40);
  declare @PrimKeyCP   nchar(40);
  declare @TabelnaamCP nchar(40);
  declare @ToExecute   nchar(500);
  declare local temporary table tmpVrCp(tmpNawFilGid integer, /*tmpRelGeslacht integer, */tmpVeldWaarde nchar(255)) on commit preserve rows;

  //call traceBegin('LicentiesNAWdata');

  set @FnCodeLicentie = null;
  select SchermFnCode into @FnCodeLicentie from tabScherm where SchermSoort = 900;

  // Opzoeken vrije rubriek *E-mail nieuwsbrief* contactpersonen (FonGid wordt als groepsID EN als subgroepsID gebruikt)
  select fongid into @DebFonGid from tabfileofnaw where fonid='d';
  select vrVeldnaam
  into   @VeldNaamCP
  from   tabVrijeRubrieken
  where  vrbestandoms = 'cp'
     and vrgroepid    = @DebFonGid
     and vrsubgroepid = @DebFonGid
     and vrlabel      = 'E-mail nieuwsbrief';
  //Opzoeken tabelnaam voor de vrije rubrieken van de contact
  set @PrimKeyCP = 'VrCP' + right('00' + string(@DebFonGid), 3) + right('00' + string(@DebFonGid), 3) + 'RecordId';
  set @TabelnaamCP = 'tabVrCP' + right('00' + string(@DebFonGid), 3) + right('00' + string(@DebFonGid), 3);

  //Opzoeken functie *Administratie*
  select FnCode into @FnCodeAdmin from tabFunctieContact where OmsFunctie = 'Administratie';

  // In de tabel @TabelnaamCP is de prim.key gelijk aan de relgid van de gevraagde contactpersoon.
  // Uit de tabel gebruiken we veld @VeldNaamCP
  // Dit doen we door de gegevens in een tijdelijke tabel te plaatsen en mee te linken
  if @FnCodeAdmin is not null and @VeldNaamCP is not null then
    set @ToExecute =  'insert into tmpVrCp(tmpNawFilGid, /*tmpRelGeslacht, */tmpVeldWaarde) ' +
                      'select NawFilGid, /*RelGeslacht, */' + @VeldNaamCP + ' ' +
                      'from tabRelatie ' +
                           'INNER JOIN tabNawFile on (RelNawGid = nawFilNawGid) ' +
                           'INNER JOIN tabRelatieFunctie on (RelGid = FnRelGid) ' +
                           'LEFT OUTER JOIN ' + @TabelnaamCP + ' on ' + @PrimKeyCP + ' = RelGid ' +
                      'where NawFilGid = @NawFilGid ' +
                        'and IsBelangrijkste = 1 ' +
                        'and relFnCode = @FnCodeAdmin ';
    //call trace(@ToExecute);
    execute immediate @ToExecute;
  end if;


  //call traceEind('LicentiesNAWdata');

SELECT
  AdrNaam1,
  AdrNaam2,
  AdrStraat,
  AdrHuisNummer,
  AdrPostcode,
  AdrPlaats,
  LndEigenCode,
  LndOms,
  IsNull((select  RelNaamInAdres from tabRelatie LEFT OUTER JOIN tabRelatieFunctie ON (RelGid = FnRelGid) WHERE (IsBelangrijkste = 1) AND (relNawGid = NawGid) AND (relFnCode = @FnCodeLicentie)),'') NawCP,
  AdrNaam1  NawReserveVeld1, //op verzoek EL door JV 29-08-05; adresnaam1
  AdrNaam2  NawReserveVeld2, //op verzoek EL door JV 29-08-05; adresnaam2
  IsNull((select  RelVolledigeNaam from tabRelatie LEFT OUTER JOIN tabRelatieFunctie ON (RelGid = FnRelGid) WHERE (IsBelangrijkste = 1) AND (relNawGid = NawGid) AND (relFnCode = @FnCodeLicentie)),'') NawReserveVeld3, //op verzoek EL door JV 29-08-05; relatie volledige naam
  isnull((select tmpVeldWaarde from tmpVrCp where tmpNawFilGid = @NawFilGid), '') NawReserveVeld4,                                                    // op verzoek EL door ACW 09-11-10; Vrije rubriek Email-nieuwsbrief van belangrijkste contactpersoon van functie 'Administratie'
  IsNull((select  case RelGeslacht when 1 then _U('Man') when 2 then _U('Vrouw') else _U('Onbekend') end from tabRelatie LEFT OUTER JOIN tabRelatieFunctie ON (RelGid = FnRelGid) WHERE (IsBelangrijkste = 1) AND (relNawGid = NawGid) AND (relFnCode = @FnCodeLicentie)),'') NawReserveVeld5, // op verzoek EL door ACW 09-11-10; Geslacht van de belangrijkste contactpersoon van afdeling Standaard (de functie van Licenties op scherm)
  if (isnull(AdrEmail, '') = '') and (NawGidCorrespondentie is not null) then  //op verzoek EL door ACW 16-11-2010; als email van correspondentie leeg, dan toch email van vestiging pakken
    (select tabEmail.AdrEmail from tabAdres tabEmail where tabEmail.AdrGid = NawGidVestiging)
  else
    AdrEmail
  endif AdrEmail,
  IsNull((select  RelEmail from tabRelatie LEFT OUTER JOIN tabRelatieFunctie ON (RelGid = FnRelGid) WHERE (IsBelangrijkste = 1) AND (relNawGid = NawGid) AND (relFnCode = @FnCodeLicentie)),'') CpEmail
FROM tabNawFile
              inner join tabNaw       on (NawGid = NawFilNawGid)
              inner join tabAdres     on (AdrGid = IsNull(NawGidCorrespondentie,  NawGidVestiging))
              inner join tabLand      on (LndGid = AdrLndGid)
WHERE (NawFilGid = @NawFilGid)



end;

