create or replace procedure LicentieWijzigVrijeRubriekenVeldnamenNaarInhoud(inout @Tekst long nvarchar, in @LicGid integer)
//Deze procedure analyseert een stuk tekst. Staan hier veldnamen tussen blokhaken in, dan worden deze vervangen met de waarde uit de vrijerubrieken van een licentie.
/*
begin
  declare @Tekst long nvarchar = 'De factuur 2 King Licentie [F2KLicCode1]';
  call LicentieWijzigVrijeRubriekenVeldnamenNaarInhoud(@Tekst, 19091);
  select @Tekst;
end;
*/
begin
  declare @StartBracePosition     integer;
  declare @EndBracePosition 	    integer;
  declare @NextStartBracePosition integer;
  declare @Veldnaam						    nchar(100);
  declare @VeldBestaat            nchar(100);
  declare @StartBrace             nchar(1) = '[';
  declare @EndBrace               nchar(1) = ']';
  declare @Waarde							    long nvarchar;

  set @StartBracePosition = locate( @Tekst, @StartBrace, 1 );

  while @StartBracePosition > 0
  loop
    set @EndBracePosition       = LOCATE( @Tekst, @EndBrace   , @StartBracePosition );
    set @NextStartBracePosition = LOCATE( @Tekst, @StartBrace , @StartBracePosition + 1 ); //De volgende startbrace moet na de eindbrace liggen

    if (@EndBracePosition > 0) and (@EndBracePosition < @NextStartBracePosition or @NextStartBracePosition = 0) then
      set @Veldnaam = substring(@Tekst,(@StartBracePosition+1),(@EndBracePosition - @StartBracePosition - 1));
      select VrVeldNaam('LIC', 0, 0, @Veldnaam) into @VeldBestaat;
      //set @Veldnaam = select VrVeldNaam('LIC', 0, 0,substring(@Tekst,(@StartBracePosition+1),(@EndBracePosition - @StartBracePosition - 1)));

      if (@VeldBestaat is not null ) then
        select VeldWaarde into @Waarde
        from VrGetContent('LIC', 0, 0, @Veldnaam, '', '') WITH (VrRecordId integer, VeldWaarde long nvarchar)
        where VrRecordId = @LicGid;

        set @Tekst = replace(@Tekst,substring(@Tekst,(@StartBracePosition),(@EndBracePosition-@StartBracePosition+1)),isNull(@Waarde,''));
      end if;
    end if;

    set @StartBracePosition = locate( @Tekst, @StartBrace, @StartBracePosition + 1 );
  end loop;

end;

alter procedure LicentieWijzigVrijeRubriekenVeldnamenNaarInhoud set hidden;


create or replace procedure LogfileTruncate()
begin
  set @@ErrorTextProcedure = 'LogfileTruncate >';
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select first 1 from sysmirrorserver) then
    begin
      // Database staat in mirror-mode, dus dan logfile hernoemen, MITS de admin naam en de foldernaam gelijk zijn
      declare @FullPathname long nvarchar;
      declare @DbName       long nvarchar;
      set @DbName       = db_property('name');
      set @FullPathname = db_property('file');
      //call trace('FullName='+@FullPathname);
      //call trace('DbName='+@DbName);
      if @FullPathname like '%' + @DbName + '\' + @DbName + '.db' then
        //call trace('Log hernoemen!');
        Backup database
        directory ''                 //Zelfde folder zonder hernoemen van file, zodat de log alleen wordt getrucate
        transaction log only         //Database ongemoeid laten
        transaction log rename      //Hier gaat het om: Hernoemen van transactielog
        history off;                 //Zodat de backup.syb file niet wordt aangemaakt/aangevuld
      else
        //call trace('Log hernoemen niet gelukt!');
        insert into tabLog(LogSoort, LogAdmCode, LogBjCode, LogUserName, LogMachineName, LogOmschrijving)
        values(15, Db_Name(), '', '', '', _A('Logfile hernoemen niet mogelijk: bestandslocatie onjuist!'));
      end if;
    end;
  else
    //call trace('Log verkleinen!');
    Backup database
    directory ''                 //Zelfde folder zonder hernoemen van file, zodat de log alleen wordt getrucate
    transaction log only         //Database ongemoeid laten
    transaction log truncate     //Hier gaat het om
    history off;                 //Zodat de backup.syb file niet wordt aangemaakt/aangevuld
  end if;

  set @@ErrorTextProcedure = 'LogfileTruncate';
  //call TraceEind(@@ErrorTextProcedure);
end;

