//------- Strip het opgegeven karakter links van string, en geef het resultaat terug
create or replace function LTrimChar(in @String nchar(250), in @Teken nchar(1))
returns nchar(250)
begin

  //call TraceBegin('LTrimChar(@String='+@String+')');
  if Left(@String, 1) = @Teken then
  begin
    declare @Resultaat nchar(250);
    declare @Teller    integer;
    set @Teller = 1;
    while (@Teller <= length(@String)) and (substr(@String, @Teller, 1) = @Teken) loop
      set @Teller = @Teller + 1;
    end loop;
    set @Resultaat = substr(@String, @Teller, 250);

    //call TraceEind('LTrimChar -------> @Resultaat='+@Resultaat);
    return(@Resultaat)
  end
  else
    return(@String)
  end if;

end;


