create or replace procedure MaakDummyAcceptGiroBatch(out @AcbGid integer)
begin

  set @@ErrorTextProcedure = 'MaakDummyAcceptGiroBatch > ';
  //call TraceBegin(@@ErrorTextProcedure);

  //AcceptGiro batch
  insert into tabAcceptGiroBatch (AcbAangemaaktDoor, AcbAangemaaktOp, AcbOms)
  Values                         (@@GebruikerCode,   Now(),          'Dummy');
  set @AcbGid = @@Identity;

  call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabAcceptGiroBatch','acbGid='+string(@AcbGid), 0);


  // 4 records inserten, zodat je overloop naar volgende regel goed kunt zien
  insert into tabAcceptGiro(
         AccAcbGid, accRegelNummer, AccDebNummer, accFactuurNummer,
         accFactuurDatum, accVervalDatum,
         accReferentie,
         accValNummer, AccValCode, accBedrag, accBtcNummer, AccBtcOms, accLvcNummer, AccLvcOms,

         AccCorrAdresNaam1,    AccCorrAdresNaam2,
         AccCorrAdresStraat,   AccCorrAdresHuisnummer,
         AccCorrAdresPostcode, AccCorrAdresPlaats,
         AccCorrAdresLndEigenCode, AccCorrAdresLndOms, AccCorrAdresLndPlaatsHuisnr,
         AccCorrAdresLndPlaatsPostcode, AccCorrAdresLndInNAWBlok,

         AccVestAdresNaam1, AccVestAdresNaam2,
         AccVestAdresStraat, AccVestAdresHuisnummer,
         AccVestAdresPostcode, AccVestAdresPlaats,
         AccVestAdresLndEigenCode, AccVestAdresLndOms, AccVestAdresLndPlaatsHuisnr,
         AccVestAdresLndPlaatsPostcode, AccVestAdresLndInNAWBlok,

         AccGebruikCorrespondentieAdres,

         AccBankRekBankRekening, AccBankRekNaamRekHouder,
         AccBankRekAdresRekHouder, AccBankRekPlaatsRekHouder,
         AccPrintBedragAcceptgiro,
         AccTaalCode)
  select  @AcbGid, row_num, '12345678', 12345678,
          now(), now(),
          _U('Referentie ...'),
          0, _U('EUR'), 123456.78, 1, _U('Betalingsconditie'), 1, _U('Leveringsconditie'),
          _U('Correspondentie Naamregel 1'), _U('Correspondentie Naamregel 2'),
          _U('Correspondentie Straat'), _U('Huisnr.'),
          '1234 AB', _U('Correspondentie Plaats'),
          _U('NL'), _U('Correspondentie Land'), 1,
          3, 1,

          _U('Vestiging Naamregel 1'), _U('Vestiging Naamregel 2'),
          _U('Vestiging Straat'), _U('Huisnr.'),
          '1234 AB', _U('Vestiging Plaats'),
          _U('NL'), _U('Vestiging Land'), 1,
          3, 1,

          1,

          'NL69INGB0123456789', _U('Naam Rekeninghouder'),
          _U('Adres rekeninghouder'), _U('Plaats rekeninghouder'),
          1,
          'N'
  from    rowgenerator
  where   row_num between 1 and 4;

  set @@ErrorTextProcedure = 'MaakDummyAcceptGiroBatch';
  //call TraceEind(@@ErrorTextProcedure + ' > Acbgid = ' + string(@Acbgid));
end;


create or replace procedure MaakDummyFactuurBatch(
  in  @LayoutSoort integer,   //50 = batchfact.; 60 = directefact.; 20 = orderbev.; 30 = Pakbon; 40 = Proforma
  out @FbGid       integer,
  out @boekganggid integer )
begin
  declare @BjGid          integer;
  declare @Pernr          integer;
  declare @BtwCode        integer;
  declare @OpbrGrpGid     integer;
  declare @FkGid          integer;
  declare @ReferentieGid  integer;
  declare @ValNummer      integer;
  declare @ValCode        nchar(3);
  declare @ValNaam        nchar(40);
  declare @OpbrGrpRksGid  integer;

  set @@ErrorTextProcedure = 'MaakDummyFactuurBatch( @LayoutSoort='+string(@LayoutSoort)+')';
   //call TraceBegin(@@ErrorTextProcedure);
  call BepaalBoekjaarEnPeriode( @@VerwerkingsDatum, @BjGid, @PerNr );

  //Factuurbatch
  insert into tabFactuurBatch (fbAangemaaktDoor, fbAangemaaktOp, fbSoortBatch)
  values(@@GebruikerCode, now(), @LayoutSoort);
  set @fbGid = @@Identity;
  call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabFactuurBatch','fbGid='+string(@fbGid), 0);

  select first valnummer, ValCode, OmsValuta into @valnummer, @ValCode, @ValNaam from tabvaluta;

  //Factuurkop aanmaken
  insert into tabFactuurkop( fkfbGid,         fkDebNummer,     fkFactDebNummer,       fkFactDebZoekCode, fkFactDebTelefoon, fkFactDebTelefax,
                             fkTekstOrigineelKopie, fkNawBtwNummer,
                             fkValNummer,           fkValCode,
                             fkValOms,        fkOrderDatum,    fkFactuurNummer, fkFactuurNummer_Lengte,
                             fkFactuurDatum,  fkVervalDatum,   fkIsInclBtw,           fkLeverDatum,
                             fkBtcNummer,     fkBtcOms,        fkBtcTekstOpFactuur,   fkBtcPerc, fkBtcBasis, fkBtcBasisInBtw, FkBtcKredBepKortingInclBtw,
                             fkLvcNummer,     fkLvcCode,       fkLvcOms,              fkLvcTekstOpFactuur,   fkOpmRegel,
                             fkBtcBedrag,     fkBtcBedragInBtw, fkBtcDatum,           fkTaalGid,             fkTaalCode,            fkRapNummer,
                             fkBtcSoort,      fkBankRekNummer, fkBankRekNaam,         fkBankRekAdres, fkBankRekPostcode, fkBankRekPlaats,
                             fkVertCode,      fkVertNaam,
                             fkSubtotExEmballage, fkTotEmballage, fkFactTotaalExBtw, fkFactTotInBtw, fkBedragBetaald, fkBedragTeBetalen,
                             fkVerschilAfboeken, fkEigenBankRekNummer, fkEigenBankRekNaam, fkEigenBankRekAdres, fkEigenBankRekPlaats,
                             fkOCRformcode,   fkOCRdiversen, fkOCReigenrekening, fkOCRBIC, fkPrintBedragAcceptGiro, fkIsEdi,
                             fkEmail,         fkTelefoon,      fkTelefoon2, fkTelefax,
                             fkIncassoDatum, FkIsAbcLevering, FkGewichtIn, FkVolumeIn)
  values( @fbgid, '12345678', '12345678', _U('Zoekcode'), '(0123) 45 67 89', '(0123) 45 67 89',
          0, '123456789012345',
          @ValNummer, @ValCode,
          @ValNaam, '2000-02-01', '1234567890', 10,
          '2000-02-01', '2000-02-01', 0, '2000-02-01',
          123, _U('Betalingsconditie'), _U('Tekst op factuur van betalingsconditie'), 123.12, 1234567890.12, 1234567890.12, 1,
          123, 123, _U('Leveringsconditie'), _U('Tekst op factuur van leveringsconditie'), _U('Sluitregel van deze factuur'),
          1234567890.12, 1234567890.12, '2000-02-01', (select DefaultTaalGid from tabvastegegevens), (select TaalCode from tabvastegegevens inner join tabTaal on (DefaultTaalGid = TaalGid)), 0,
          1, 'NL69INGB0123456789', _U('Naam rekeninghouder'), _U('Adres rekeninghouder'), _U('Postcode rek.h.'), _U('Plaats rekeninghouder'),
          '123', _U('Vertegenwoordiger'),
          123456789.12, 123456789.12, 123456789.12, 123456789.12, 123456789.12, 123456789.12,
          1, 'NL02ABNA0123456789', _U('Naam eigen rekeninghouder'), _U('Adres eigen rekeninghouder'), _U('Plaats eigen rekeninghouder'),
          '13', '12345', 'NL02ABNA0123456789', 'ABNANL2A', 1, 0,
          _U('Vest.adres e-mail'), _U('Vest.adres tel.'), _U('Vest.adres tel.2'), _U('Vest.adres fax.'),
          '2000-02-01', 0, _U('Kg'), _U('Liter'));
  set @FkGid = @@Identity;

  // Adressen invullen
  insert into tabFactuurAdres (
    faFkGid,               faFrefGid,         faSoortAdres,
    faNaam1,               faNaam2,           faStraat,
    faHuisnummer,          faHuisnummerPositie,
    faPostcode,            faPostcodePositie, faPlaats,
    faLandCode,            faLand,            faLandAfdrukken, faEANcode,
    faEmail,               faTelefoon,        faTelefoon2, 		 faTelefax,
    faContactNaamAdres,    faContactNaamAanhef, faContactNaamBrief,
    faContactTelefoon,     faContactTelefoon2, faContactTelefax,
    faOpm,                 faOms)
  values (
    @FkGid, null, 1, // Soort adres = Factuuradres factuurdebiteur
    _U('Factuuradres Naam1'), _U('Factuuradres naam2'), _U('Factuuradres straat'),
    '1234567890', 1,
    '1234 AB', 1, _U('Factuuradres plaats'),
    _U('NL'), _U('Factuuradres land'), 1, _U('Factadres EAN'),
    _U('Factuuradres e-mail'), _U('Fact.adres tel.'), _U('Fact.adres tel.2'), _U('Fact.adres fax.'),
    _U('Contact naam in adres'), _U('Contact naam in aanhef'), _U('Contact naam in brief'),
    _U('Contact telefoon 1'), _U('Contact telefoon 2'), _U('Contact fax'),
    _U('Factuuradres factuurdebiteur'), null
  );

  //Vrije rubrieken erbijzoeken
  call FactureringOvernemenVrijeRubrieken(0, @FkGid, null, 1);

  //Referentie erin (1 als orderbev., anders 2 stuks)
  insert into tabFactuurReferentie( frefFkGid, frefOrderNummer, frefOrderDebNummer, frefOms, frefExternId, frefOffertenummer, frefLeverDatum, frefOrderDatum,
                                    frefVtgCode, frefVtgZoekCode, frefVtgVoornaam, frefVtgNaam, frefVtgTelefoon1, frefEdiBuffer)
  values( @fkGid, '1234567890', '12345678', _U('Referentie order/factuur'), '2005_000034', '20050012.1', now(), now(),
          1, '', _U('Voornaam vertegenwoordiger 1'), _U('Naam vertegenwoordiger 1'), '(1234) 56 78 90', '<EDI>data 1</EDI>');
  set @ReferentieGid = @@Identity;
  call MaakDummyFactuurBatchRegels(@ReferentieGid);

  //2e referentie-order
  insert into tabFactuurReferentie( frefFkGid, frefOrderNummer, frefOms, frefExternId, frefOffertenummer, frefLeverDatum, frefOrderDatum,
                                    frefVtgCode, frefVtgZoekCode, frefVtgVoornaam, frefVtgNaam, frefVtgTelefoon1, frefEdiBuffer)
  values( @fkGid, '1234567891', _U('Referentie order/factuur'), '2005_000035', '20050013.1', now(), now(),
          2, '', _U('Voornaam vertegenwoordiger 2'), _U('Naam vertegenwoordiger 2'), '(1234) 56 78 90', '<EDI>data 2</EDI>' );
  set @ReferentieGid = @@Identity;

  //Vrije rubrieken erbijzoeken
  call FactureringOvernemenVrijeRubrieken(1, @ReferentieGid, null, 1);
  call FactureringOvernemenVrijeRubrieken(3, @ReferentieGid, null, 1);

  //Verzendgegevens
	insert into tabFactuurColli (FclfrefGid, FclRegelNr, FclColtCode, 			FclColtOmschrijving,  		 FclGewicht, 		 FclVolume, 		 FclTrackTraceCode, FclTrackTraceUrl, FclOpmerking)
	values 										  (@ReferentieGid,  1, 				 _U('Collo-type code'), _U('Collo-type omschrijving'), 1234567890.123, 1234567890.123, '3SPE1234567', 'http://www.vervoerder.nl/trackntrace?code=3xxxx1234567890', _U('Opmerking'));
	insert into tabFactuurColli (FclfrefGid, FclRegelNr, FclColtCode, 			FclColtOmschrijving,  		 FclGewicht, 		 FclVolume, 		 FclTrackTraceCode, FclTrackTraceUrl, FclOpmerking)
	values 											(@ReferentieGid,  2, 				 _U('Collo-type code'), _U('Collo-type omschrijving'), 1234567890.123, 1234567890.123, '3SPE1234567', 'http://www.vervoerder.nl/trackntrace?code=3xxxx1234567890', _U('Opmerking'));

  call MaakDummyFactuurBatchRegels(@ReferentieGid);

  //BTW-regels
  insert into tabFactuurBtwRegel( fbrFkGid, fbrBtwCode, fbrBtwPercentage, fbrBtwBasis, fbrBtwBedrag, fbrBtwVerlegd )
  values( @fkGid, 123, 12.34, 1234567890.12, 1234567890.12, 0 );
  insert into tabFactuurBtwRegel( fbrFkGid, fbrBtwCode, fbrBtwPercentage, fbrBtwBasis, fbrBtwBedrag, fbrBtwVerlegd )
  values( @fkGid, 123, 12.34, 1234567890.12, 1234567890.12, 0 );
  insert into tabFactuurBtwRegel( fbrFkGid, fbrBtwCode, fbrBtwPercentage, fbrBtwBasis, fbrBtwBedrag, fbrBtwVerlegd )
  values( @fkGid, 123, 0, 0, 0, 1 );  // Let op: Dit is een BTW-verlegd!!

  //Factureeroverzicht indien soort = factuur
  //ACW Pak wel de oudste a.u.b.
  select first BoekgangGid into @BoekGangGid from tabboekingsgang order by boekganggid;
  call LockSetOnId(@@SpId, @@LoginTime, 1, 'Factuuroverzicht', @FbGid, 0);

  if @layoutsoort in (50, 60) and @BoekGangGid is not null then
    //Valuta
    select first valnummer into @valnummer from tabvaluta where IsBasisValuta = 0;
    if @valnummer is not null then
      insert into tabFactuurOverzichtValuta( fovBoekgangGid, fovValNummer, fovBedragValuta, fovBedragBasis, fovFbGid )
      values( @BoekGangGid, @valnummer, 1234567890.12, 1234567890.12, @FbGid );
    end if;
    select first valnummer into @valnummer from tabvaluta where IsBasisValuta = 1;
    insert into tabFactuurOverzichtValuta( fovBoekgangGid, fovValNummer, fovBedragValuta, fovBedragBasis, fovFbGid )
    values( @BoekGangGid, @valnummer, 1234567890.12, 1234567890.12, @FbGid );

    //Btw-bedragen
    select first BtwCode into @BtwCode from tabBtw;
    if @BtwCode is not null then
      insert into tabFactuurOverzichtBtw( fobBoekgangGid, fobBtwCode, fobBedrag, fobFbGid ) values ( @BoekGangGid, @BtwCode, 1234567890.12, @FbGid );
    end if;
    if exists( select first BtwCode into @BtwCode from tabBtw where BtwCode <> @BtwCode ) then
      select first BtwCode into @BtwCode from tabBtw where BtwCode <> @BtwCode;
      insert into tabFactuurOverzichtBtw( fobBoekgangGid, fobBtwCode, fobBedrag, fobFbGid ) values ( @BoekGangGid, @BtwCode, 1234567890.12, @FbGid );
    end if;

    //Opbrengsten
    select first OpbrGrpGid into @OpbrGrpGid from tabOpbrengstgroep;
    if @OpbrGrpGid is not null then
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 0, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 1, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 2, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 3, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 4, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 5, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 6, @OpbrGrpGid, 1234567890.12, @FbGid );
    end if;
    if exists( select OpbrGrpGid from tabOpbrengstgroep where OpbrGrpGid <> @OpbrGrpGid ) then
      select first OpbrGrpGid into @OpbrGrpGid from tabOpbrengstgroep where OpbrGrpGid <> @OpbrGrpGid;
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 0, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 1, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 2, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 3, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 4, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 5, @OpbrGrpGid, 1234567890.12, @FbGid );
      insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooOpbrGrpGid, fooBedrag, fooFbGid ) values( @BoekGangGid, 6, @OpbrGrpGid, 1234567890.12, @FbGid );
    end if;
    insert into tabFactuurOverzichtOpbrengstGroep( fooBoekgangGid, fooSoort, fooKredBepRksGID, fooBedrag, fooFbGid ) values( @BoekGangGid, -1, (select first RksGid from tabrekeningschema), 1234567890.12, @FbGid );

    //Niet-gefactureerde orders
    // 1 = orders zijn niet vrijgegeven
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden )
    select first @fbGid, OrkGid, 1 from tabOrderkop;
    // 2 = van de orders zijn de juiste documenten nog niet afgedrukt
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden )
    select first @fbGid, OrkGid, 2 from tabOrderkop where OrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd );
    // 3 = er zijn wel orders, maar 'te weinig' of te klein (qua bedrag) om facturen te genereren
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden )
    select first @fbGid, OrkGid, 3 from tabOrderkop where OrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd );
    // 4 = er zijn geen factuurlayouts ingesteld
    insert into tabFactuurNietGefactureerd( fngFbGid, fngOrkGid, fngReden )
    select first @fbGid, OrkGid, 4 from tabOrderkop where OrkGid not in (select fngOrkGid from tabFactuurNietGefactureerd );
  end if;

  if @layoutsoort = 30 and @BoekGangGid is not null then
    //Pakbon, dus levering

    //Punt 1: Opbrengsten
    select first OpbrGrpGid, GrpSoortRksGID into @OpbrGrpGid, @OpbrGrpRksGid from tabOpbrengstgroep inner join tabOpbrengstgroepSoort on (GrpSoortGrpGid = OpbrGrpGid);
    if @OpbrGrpGid is not null then
      insert into tabLeverOverzichtOpbrengst(LooBoekGangGID, LooOpbrGrpGid,  LooRksGidKostprijs, looBedragKostprijs, LooRksGidVvp, looBedragVvp, LooRksGidHerwaardering, looBedragHerwaardering, looFbGid)
      values(@BoekGangGid, @OpbrGrpGid, @OpbrGrpRksGid, 1234567890.12, @OpbrGrpRksGid, 1234567890.12, @OpbrGrpRksGid, 1234567890.12, @FbGid);
    end if;

    //Punt 2: totalen
    insert into tabLeverOverzichtTussenrekening( LotBoekGangGID, lotBedragGefact, lotBedragTeFact, lotFbGid)
    values(@BoekGangGid, 1234567890.12, 1234567890.12, @FbGid);
  end if;

  set @@ErrorTextProcedure = 'MaakDummyFactuurBatch, fbgid='+string(@fbgid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;

//call MaakDummyFactuurBatch(50,0);


create or replace procedure MaakDummyFactuurBatchRegels(in @frefGid integer)
begin
  declare @FrGid   integer;
  declare @FrpsGid integer;
  // Maak adressen EN regels voor betreffende factuurreferentie aan
  set @@ErrorTextProcedure = 'MaakDummyFactuurBatchRegels > @frefGid='+string(@frefGid);
  //call TraceBegin(@@ErrorTextProcedure);

  // Adressen erin
  insert into tabFactuurAdres (
    faFkGid,               faFrefGid,         faSoortAdres,
    faNaam1,               faNaam2,           faStraat,
    faHuisnummer,          faHuisnummerPositie,
    faPostcode,            faPostcodePositie, faPlaats,
    faLandCode,            faLand,            faLandAfdrukken, faEANcode,
    faEmail,               faTelefoon,        faTelefoon2,     faTelefax,
    faContactNaamAdres,    faContactNaamAanhef, faContactNaamBrief,
    faContactTelefoon, faContactTelefax,
    faOpm,                 faOms)
  values (
    null, @frefGid, 0, // Soort adres = Correspondentieadres
    _U('Correspondentieadres Naam1'), _U('Correspondentieadres naam2'), _U('Correspondentieadres straat'),
    '1234567890', 1,
    '1234 AB', 1, _U('Correspondentieadres plaats'),
    _U('NL'), _U('Correspondentieadres land'), 1, _U('Corr.adres EAN'),
    _U('Correspondentieadres e-mail'), _U('Corr.adres tel.'), _U('Corr.adres tel.2'), _U('Corr.adres fax.'),
    _U('Contact naam in adres'), _U('Contact naam in aanhef'), _U('Contact naam in brief'),
    _U('Contact telefoon'), _U('Contact fax'),
    _U('Correspondentieadres'), null
  );

  insert into tabFactuurAdres (
    faFkGid,               faFrefGid,         faSoortAdres,
    faNaam1,               faNaam2,           faStraat,
    faHuisnummer,          faHuisnummerPositie,
    faPostcode,            faPostcodePositie, faPlaats,
    faLandCode,            faLand,            faLandAfdrukken, faEANcode,
    faEmail,               faTelefoon,        faTelefoon2,      faTelefax,
    faContactNaamAdres,    faContactNaamAanhef, faContactNaamBrief,
    faContactTelefoon, faContactTelefax,
    faOpm,                 faOms)
  values (
    null, @frefGid, 12, // Soort adres = Verzendadres order-/factuurdebiteur
    _U('Verzendadres Naam1'), _U('Verzendadres naam2'), _U('Verzendadres straat'),
    '1234567890', 1,
    '1234 AB', 1, _U('Verzendadres plaats'),
    _U('NL'), _U('Verzendadres land'), 1, _U('Verz.adres EAN'),
    _U('Verzendadres e-mail'), _U('Verz.adres tel.'), _U('Verz.adres tel.2'), _U('Verz.adres fax.'),
    _U('Contact naam in adres'), _U('Contact naam in aanhef'), _U('Contact naam in brief'),
    _U('Contact telefoon'), _U('Contact fax'),
    _U('Verzendadres orderdebiteur'), null
  );

  insert into tabFactuurAdres (
    faFkGid,               faFrefGid,         faSoortAdres,
