//VvE 17-07-2017 Incident I10818.
//aanmaken gekopieerd uit uitleverscript 5.55 Rks2Naw.sql
create or replace procedure MaakOntbrekendeNawAanVoorGrootboekrekening(in @RksGid integer)
begin
  //Grootboekrekening
	declare	@RksNummer  nchar(10);
	declare	@RksZoekcode nchar(10);
	declare @RksNaam nchar(40);
	declare	@RksValNummer integer;
  declare @DefaultSoort 	integer;

	//Vaste gegevens
	declare @FonNawSoort 	integer;

  //defaults
  declare @DefaultTaalGid             integer;
  declare @FonGid                     integer;
  declare @FonBtcNummer               integer;
  declare @FonLvcNummer               integer;
  declare @FonKredietLimiet           numeric(15,2);
  declare @FonBtwCode                 integer;
  declare @FonLndGid                  integer;
  declare @FonAanmaningType           smallint;
  declare @FonFactuurBTW              smallint;
  declare @FonApartFactureren         smallint;
  declare @FonApartLeveren            smallint;
  declare @FonAantKopieFacturen       smallint;
  declare @FonOrderKorting            numeric(6,2);
  declare @FonVtCode                  integer;
  declare @FonFactuurAdres            smallint;
  declare @FonVerzendAdres            smallint;
  declare @FonBlokOrderInvoer         smallint;
  declare @FonContributieCode         integer;
  declare @FonTegenRksGid             integer;
  declare @FonDebGrpGid               integer;
  declare @FonOrdKortingDebOfDebGroep smallint;
  declare @fonIsWebklant              smallint;
  declare @FonEindAdres               smallint;
  declare @FonVrvGid                  integer;

	//Output nawinsert
	declare @NawGid integer;
  declare @NawFilGid integer;
  declare @AdrGid integer;

	//Rekening moet bestaan
	if not exists (select 1 from tabRekeningschema where RksGid = @RksGid) then
    raiserror 17000;
	end if;

	//Ophalen rekening
	select RksNummer, RksZoekcode, RksNaam, RksValNummer, DefaultSoort into
	       @RksNummer, @RksZoekcode, @RksNaam, @RksValNummer, @DefaultSoort
	from tabRekeningschema where RksGid = @RksGid;

	//Checken rekeningsoort
	if not (@DefaultSoort = 6 or @DefaultSoort = 7) then
	  raiserror 17000;
	end if;

  //Bepaal NawSoort
	if @DefaultSoort = 6 then
    set @FonNawSoort = 0
  else
    set @FonNawSoort = 1;
	end if;

	//Default taal komt uit bedrijfsgegevens
	select first NawTaalGid into @DefaultTaalGid from tabNaw where NawSoort = 2 /*Bedrijfsgegevens*/;

	//Defaults opvragen voor juiste NAWsoort
	select  FonGid,  FonBtcNummer,  FonLvcNummer,  FonKredietLimiet,  FonBtwCode,  FonLndGid,  FonAanmaningType,  FonFactuurBTW,
					FonApartFactureren,  FonApartLeveren,  FonAantKopieFacturen,  FonOrderKorting,  FonVtCode,  FonFactuurAdres,  FonVerzendAdres,
					FonBlokOrderInvoer,  FonContributieCode,  FonTegenRksGid,  FonDebGrpGid,  FonOrdKortingDebOfDebGroep,  fonIsWebklant,
					FonEindAdres, FonVrvGid
	into   @FonGid, @FonBtcNummer, @FonLvcNummer, @FonKredietLimiet, @FonBtwCode, @FonLndGid, @FonAanmaningType, @FonFactuurBTW,
				 @FonApartFactureren, @FonApartLeveren, @FonAantKopieFacturen, @FonOrderKorting, @FonVtCode, @FonFactuurAdres, @FonVerzendAdres,
				 @FonBlokOrderInvoer, @FonContributieCode, @FonTegenRksGid, @FonDebGrpGid, @FonOrdKortingDebOfDebGroep, @fonIsWebklant,
				 @FonEindAdres, @FonVrvGid
	from tabFileOfNaw
	where FonNawSoort=@FonNawSoort;



	call NawInsert(
		@FonGid, //@nawfilFonGID integer,
		@RksNummer, //@nawfilNummer nchar(10),
		@RksZoekcode, //@nawfilZoekcode nchar(10),
		@RksGid, //@nawfilRksGID integer,
		@RksValNummer, //@nawfilValNummer integer,
		@FonBtcNummer, //@nawfilBtcNummer integer,
		@FonLvcNummer, //@nawfilLvcNummer integer,
		@FonKredietLimiet, //@nawfilKredLimiet double,
		null, //@nawfilAutoOSP smallint,
		@FonBtwCode, //@nawfilBTWcode integer,
		@RksNaam, //@adrNaam1 nchar(40),
		null, //@adrNaam2 nchar(40),
		null, //@adrStraat nchar(40),
		null, //@adrHuisnummer nchar(10),
		null, //@adrPostcode nchar(40),
		null, //@adrPlaats nchar(40),
		null, //@AdrEanCode nchar(13),
		@FonLndGid, //@adrLndGid integer,
		null, //@adrEMail nchar(80),
		null, //@adrTelefoon nchar(25),
		null, //@adrTelefax nchar(40),
		@DefaultTaalGid, // @nawTaalGid integer,
		null, //@nawGidVestiging integer,
		null, //@nawGidCorrespondentie integer,
		null, //@nawBtwNummer nchar(15),
		@FonAanmaningType, //@nawAanmaningsType smallint,
		null, //@nawOnsDebiteurNummer nchar(20),
		@FonFactuurBTW, //@nawFacturerenInclBtw smallint,
		@FonApartFactureren, //@nawAparteFacturen smallint,
		@FonApartLeveren, // @NawAparteLevering smallint,
		null, // @NawIsDeelLeveringToegestaan smallint,
		@FonAantKopieFacturen, //@nawAantalKopieFacturen integer,
		@FonOrderKorting, //@nawOrderKorting double,
		@FonVtCode, //@nawVertegenwCode integer,
		@FonFactuurAdres, //@nawFactuurAdres smallint,
		@FonVerzendAdres, //@nawVerzendAdres smallint,
		null, //@nawGidVerzendAdres integer,
		@FonBlokOrderInvoer, //@nawBlokOrderInvoer smallint,
		@FonContributieCode, //@nawContributieCode integer,
		@FonTegenRksGid, //@TegenRksGid integer,
		null, //@nawIdFactDeb integer,
		@FonDebGrpGid, //@NawFilDebGrpGid integer,
		@FonOrdKortingDebOfDebGroep, //@NawFilWelkeOrderkorting smallint,
		@fonIsWebklant, //@NawFilWebNaw smallint,
		null, //@NawidDebOmzet integer,
		null, //@NawidDebPrijzen integer,
		null, //@NawIsInkoopCombinatie smallint,
		null, //@NawKvkNummer nchar(40),
		null, //@NawBedrijfstak nchar(4),
		null, //@NawIncassantReferentie nchar(35),
		null, //@nawBlokSupport smallint,
		@FonEindAdres, //@NawEindAdres smallint,
		null, //@NawGidEindAdres integer,
		null, //@adrTelefoon2 nchar(25),
		null, //@NawWebsite nchar(250),
		@FonVrvGid,  //@NawVrvGid integer
		@NawGid,
		@NawFilGid,
		@AdrGid
	);


	// De RksGid wordt in NawInsert niet aan de NAW gekoppeld, dus dat alsnog doen
	update tabNawFile set NawFilRksGid = @RksGid where NawFilGid = @NawFilGid;

end;




create or replace procedure MaakOrderVanFactuur(
  in  @SoortKopie         smallint,  // 0 = Kopie obv Huidige prijzen , 1 = Kopie obv Historische prijzen, 2 = Credit (obv Historische prijzen)
  in  @VolgNr             integer,
