  declare @CbsVastCbsSsGidUitvoer integer;
  declare @CbsVastPtnGidUitvoer   integer;
  declare @CbsVastCbsVwGidUitvoer integer;
  declare @CbsVastCbsCoGidUitvoer integer;
  declare @CbsVastCbsTrGidUitvoer integer;

  //CBS
