  declare @OrkCbsVwGid              integer;
  declare @OrrCbsTrGid              integer;
  declare @OrrCbsLndGidOorsprong    integer;

  //NAW
  declare @DebGrpGid       integer;
  declare @DebBtwCode      integer;
  declare @DebBtwPerc      numeric(6,2);
  declare @NawIsInkoopCombinatie smallint;
  declare @NawFactDeb       integer;
