  declare @NawValuta        integer;
  declare @NawVertegenwCode integer;
  declare @NawApartFact     smallint;
  declare @NawIncRek        integer;
  declare @NawRelGid        integer;

  // Kop
  declare @OrkGid           integer;
  declare @OrkNummer        numeric(10,0);
  declare @OrkNawGid        integer;
  declare @OrkFactuurNawGid integer;
  declare @OrkOmzetNawGid   integer;
  declare @OrkPrijzenNawGid integer;
