  declare @VerzendAdres     integer;
  declare @EindAdres        integer;
  declare @OrkIsInclBtw     smallint;
  declare @OrkValNummer     integer;
  declare @OrkBtcNummer     integer;
  declare @OrkLvcNummer     integer;
  declare @OrkVtgCode       integer;
