  declare @OrkRelGid        integer;
  declare @OrkDefaultMagGid integer;
  declare @OrkMagGid        integer;
  declare @OrkVrvGid        integer;

  //Art
  declare @ArtIsPartij        smallint;
  declare @ArtIsSerie         smallint;
  declare @ArtPartijVerplicht smallint;
  declare @ArtBtwPerc         numeric(6,2);
  declare @ArtBtwCode         integer;
  Declare @KortingSoort       smallint;
