  declare @ArtBestellenViaDirecteInkoop smallint;
  declare @ArtProducerenViaDirecteProductie smallint;
  declare @ArtOmsVerkooporderOvernemen  smallint;
	declare @ArtHeeftVoorraad		smallint;
  //Regel
