	declare @VrijeVoorraad			        numeric(15,3);
  declare @BeschikbareVoorraad        numeric(15,3);
	declare @OrrVkeGid                  integer;
	declare @VkeAantalKanVerschillen    smallint;
  declare @VkeAantalVrdInVerkEenh     numeric(15,3);
  declare @WisselNaarVoorraadEenheid  smallint;
  declare @PrijzenPer                 smallint;
  declare @OrrVervolgMasterOrrGid     integer;
  declare @OrrDirecteInkoop						integer;
  declare @OrrProductie								integer;
  declare @OrrRcptGid									integer;
	//Artikel
  declare @ArtOpbrGrpGid          integer;
  //Prijsafspraak
  declare @PraGid                 integer;
  declare @PraIsInclBtw           integer;
  declare @PraValNummer           integer;
  declare @PraValcode             nchar(3);
  declare @TypeAfspraak           integer;
  //Detail
  declare @OrlGid                 integer;
  declare @OrlMagGid              integer;
  declare @OrlArtPartijGid        integer;
  declare @OrlArtSerieGid         integer;
  declare @OrlAantal              numeric(15,3);
  declare @OrlLocGid              integer;
  declare @OrlVkeGid              integer;
  declare @SpecificatieInvoer     smallint;

  // tbv eindoverzicht
  declare @OrrRegelExBtw   				numeric(15,3);
  declare @OrrRegelInBtw   				numeric(15,3);
	declare @OrrAantalGereserveerd 	numeric(15,3);
  declare @FrRegelExBtw    				numeric(15,3);
  declare @FrRegelInBtw    				numeric(15,3);

  // vrije rubrieken
  declare @VerplichteVRLeeg smallint;
  declare @OrkVrVeldnaam nchar(40);
  declare @OrkVrType Integer;
  declare @OrrVrVeldnaam nchar(40);
  declare @OrrVrType Integer;

  declare @VrObvHist smallint;  // 0 = nix, 1 = Vrije rubrieken uit historie overnemen bij KOPIE, 2 = bij CREDIT, 3 = bij beide

  declare cursor_Vrije_Rubrieken_OrderKop dynamic scroll cursor for
    select VrVeldNaam, VrType from tabVrijeRubrieken where  VrBestandOms = 'ORK' and VrGroepId = 0 and VrSubGroepId = 0 and VrVerplicht = 1
  for read only;

  declare cursor_Vrije_Rubrieken_OrderRegel dynamic scroll cursor for
    select VrVeldNaam, VrType from tabVrijeRubrieken where  VrBestandOms = 'ORR' and VrGroepId = 0 and VrSubGroepId = 0 and VrVerplicht = 1
  for read only;

  declare @NietGekopieerdTekst           long nvarchar;
  declare @VerplichteVRNietIngevuldTekst long nvarchar;
  declare @VoorraadAanwezigTekst         long nvarchar;

  set @@ErrorTextProcedure = 'MaakOrderVanFactuur > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @FkGid = ' + string(@FkGid) + ', @SoortKopie = ' + string(@SoortKopie) + ', @OrkGidIn = ' +string(@OrkGidIn));

  set @NietGekopieerdTekst           = _A('Niet gekopiëerd');
  set @VerplichteVRNietIngevuldTekst = _A('Verplichte vrije rubriek niet ingevuld');
  set @VoorraadAanwezigTekst         = _A('Let op: Er is voorraad aanwezig');

  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid, @PerNr);

  select IsNull(cast(Contents as smallint), 0) into @VrObvHist from tabRegistry where RegKey = 'FACTHISTKOPIEVROBVHIST';

  for @Cursor AS CURSOR_Order CURSOR FOR // OrderKop Begin
    select
      fkFactuurNummer             @fkFactuurNummer,
      fkDebNummer                 @fkDebNummer,
      fkFactuurDatum              @fkFactuurDatum,
      fkIsInclBtw                 @fkIsInclBtw,
      fkValNummer                 @fkValNummer,
      fkBtcNummer                 @fkBtcNummer,
      fkIncassoRekNummer          @fkIncassoRekNummer,
      FkIsAbcLevering             @FkIsAbcLevering,
      FkMagCode                   @FkMagCode,
      frefGid                     @frefGid,
      frefOrderDebNummer          @frefOrderDebNummer,
      frefOrderNummer             @frefOrderNummer,
      frefOrderDatum              @frefOrderDatum,
      frefVtgCode                 @frefVtgCode,
      frefVtgVoornaam             @frefVtgVoornaam,
      frefVtgNaam                 @frefVtgNaam,
      frefVtgTelefoon1            @frefVtgTelefoon1,
      frefOms                     @frefOms,
      ValNummer                   @ValutaNummer,
      frefOrderFactDebNummer      @frefOrderFactDebNummer,
      frefOrderOmzDebNummer       @frefOrderOmzDebNummer,
      frefOrderPrijzenDebNummer   @frefOrderPrijzenDebNummer,
      frefOrderFactuurAdres       @frefOrderFactuurAdres,
      frefOrderVerzendAdres       @frefOrderVerzendAdres,
      frefOrderEindAdres          @frefOrderEindAdres,
      frefOrderIsInkoopcombinatie @frefOrderIsInkoopcombinatie,
      frefLvcNummer               @frefLvcNummer,
      frefContactVanOrder         @frefContactVanOrder,
      FrefCbsMeenemenInAangifte   @FrefCbsMeenemenInAangifte,
      FrefCbsCoCode               @FrefCbsCoCode,
      FrefCbsGsCode               @FrefCbsGsCode,
      FrefCbsLandBestemLndEigenCode @FrefCbsLandBestemLndEigenCode,
      FrefCbsSsCode               @FrefCbsSsCode,
      FrefCbsVgCode               @FrefCbsVgCode,
      FrefCbsVwCode               @FrefCbsVwCode
    from       tabFactuurKop
    inner join tabFactuurReferentie on frefFkGid = FkGid
    inner join tmpFactuurNaarOrder on fnoSoort = 0 and fnoRefRegelGid = FrefGid and fnoVolgNr = @VolgNr and fnoVerwerken = 1
    inner join tabValuta on fkValNummer = ValNummer
    where  FkGid = @FkGid
    order by frefOrderNummer
  for read only
  do

    /* Errorcodes Kop
       0  - Alles OK
       1  - Oude King versie, controleer vaste gegevens
       2  - OrderDebiteur verwijderd
       4  - Factuurdebiteur verwijderd
       8  - Omzetdebiteur verwijderd
      16  - Prijzendebiteur verwijderd
      32  - Correspondentie adres gewijzigd
      64  - Factuur adres gewijzigd
     128  - Verzend adres gewijzigd
     256  - Eindbestemming adres gewijzigd
     512  - Vertegenwoordiger gewijzigd/verwijderd
    1024  - Probleem in de orderregels
    2048  - Betalingsconditie verwijderd
    4096  - Leveringsconditie verwijderd
    8192  - Incassorekening verwijderd
    16384 - Verplichte vrije rubriek niet ingevuld
   */
    set @KopError  = 0;

    // Geen OrkGid meegegeven -> Alle originele orders van deze factuur herstellen
    if @OrkGidIn is null then
      select  vofKopDefOrderDatum, vofKopDefLeverDatum, vofKopDefDeellevering, vofKopDefVtg, vofIsStukskorting, vofFactVoorraadReserveren, VofFactVoorraadReserverenNegatief, vofIsVerzamelLijstGebruiken, vofOrderKortingSoort, vofRegelDefNuLeveren, vofRegelDefNuFactureren
      into   @VGOrderdatum,       @VGLeverdatum,       @VGDeelLevering,       @VGVtg,       @VGStuksKorting,   @VGReservering,            @VGReserveringNegatief,            @VGIsVerzamellijstGebruiken, @VGOrderKortingSoort, @VGRegelDefNuLeveren, @VGRegelDefNuFactureren
      from tabVasteGegevensOrdersFactureren;

      select NawFilNawGid, NawFilDebGrpGid, NawFactuurAdres, NawVerzendAdres, NawGidVerzendAdres, NawEindAdres, NawGidEindAdres, NawIsInkoopCombinatie, NawIdFactDeb, NawidDebOmzet, NawidDebPrijzen, NawFilBtcNummer, NawFilLvcNummer, NawFilValNummer, NawFacturerenInclBtw, NawVertegenwCode, NawAparteFacturen, NawRekGid
          into @OrkNawGid, @DebGrpGid, @FactuurAdres, @VerzendAdres, @VerzAdr, @EindAdres, @EindAdr, @NawIsInkoopCombinatie, @NawFactDeb, @NawOmzDeb, @NawPrijsDeb, @NawBtcNummer, @NawLvcNummer, @NawValuta, @NawIsInclBtw, @NawVertegenwCode, @NawApartFact, @NawIncRek
          from tabNawFile inner join tabNaw on NawGid = NawFilNawGid left outer join tabNawRekening on (NawRekSoort like '%I%') and NawRekNawGid = NawGid where NawFilNummer = IsNull(@frefOrderDebNummer, @fkDebNummer) and NawFilFonId = 'D';

      select RelGid into @NawRelGid from (tabScherm inner join tabFunctieContact on (SchermFnCode = FnCode ) ) inner join ( tabRelatieFunctie inner join tabRelatie on (RelGid = FnRelGid and relNawGid = @OrkNawGid ) ) on ( FnCode = RelFnCode and IsBelangrijkste = 1 ) where SchermSoort=30;

      select BtwCode, BtwPercentage into @DebBtwCode, @DebBtwPerc from tabNawFile left outer join tabBtw on NawFilBtwCode = BtwCode where NawFilNawGid = @OrkNawGid and NawFilFonId = 'D';

      set @OrkDefaultMagGid = IsNull((select ToeMagMagGid into @OrkDefaultMagGid from tabToegestaneMagazijnen inner join tabGebruiker on ToeMagGebrGid = GebruikerGid where NaamGebruiker = @@GebruikerCode and ToeMagToepassing = 10),
                                     (select MagGid from tabMagazijn where MagCode = '001'));

      set @OrkMagGid = null;
      set @OrkMagGid = (select MagGid from tabMagazijn where MagCode = @FkMagCode);

      if @frefOrderDebNummer is null then
        // Voor 537
        set @KopError = @KopError + 1;
        set @frefOrderIsInkoopCombinatie = @NawIsInkoopCombinatie;
        set @OrkFactuurNawGid = @NawFactDeb;
        set @OrkOmzetNawGid   = @NawOmzDeb;
        set @OrkPrijzenNawGid = @NawPrijsDeb;
        //call Trace('VERSIE LAGER DAN 537');
      elseif @frefOrderFactDebNummer is null then
        // 537 en 540
        set @KopError = @KopError + 1;
        set @frefOrderIsInkoopCombinatie = @NawIsInkoopCombinatie;  // - Inkoopcombi: altijd huidige stamgegevens volgen
        set @OrkFactuurNawGid = @NawFactDeb;
        set @OrkOmzetNawGid   = @NawOmzDeb;
        set @OrkPrijzenNawGid = @NawPrijsDeb;
        //call Trace('VERSIE LAGER DAN 541');
      elseif ( @frefOrderDebNummer is not null ) and ( @frefOrderFactDebNummer is not null ) then // => 541
        // 541 of later
        select NawFilNawGid into @OrkFactuurNawGid from tabNawFile where NawFilNummer = @frefOrderFactDebNummer    and NawFilFonId = 'D';
        select NawFilNawGid into @OrkOmzetNawGid   from tabNawFile where NawFilNummer = @frefOrderOmzDebNummer     and NawFilFonId = 'D';
        select NawFilNawGid into @OrkPrijzenNawGid from tabNawFile where NawFilNummer = @frefOrderPrijzenDebNummer and NawFilFonId = 'D';
        if @SoortKopie = 0 then // Obv huidige gegevens, dus NAW-inkoopcombigegevens
          set @frefOrderIsInkoopCombinatie = @NawIsInkoopCombinatie;
          set @OrkFactuurNawGid = @NawFactDeb;
          set @OrkOmzetNawGid   = @NawOmzDeb;
          set @OrkPrijzenNawGid = @NawPrijsDeb;
        end if;
        //call Trace('VERSIE 541+');
      end if;

      if @SoortKopie = 0 then
        set @OrkBtcNummer = @NawBtcNummer;
        if exists(select 1 from tabBetalingsconditie where BtcNummer = @OrkBtcNummer and SoortFactuurBtc = 3) then
      	  set @OrkIncNawRekGid = @NawIncRek;
      	end if;
        set @OrkLvcNummer = @NawLvcNummer;
        set @OrkIsInclBtw = @NawIsInclBtw;
        set @OrkValNummer = @NawValuta;
/*        set @OrkRelGid = @NawRelGid;       <--- zowel vert als contpers, altijd bepalen obv huidige gegevens
        case @VGVtg
          when 0 then set @OrkVtgCode = null;
          when 1 then set @OrkVtgCode = (select RelVtgCode from tabgebruiker inner join tabrelatie on (RelGid = GebrRelGID)where NaamGebruiker = @@GebruikerCode);
          when 2 then set @OrkVtgCode = @NawVertegenwCode;
        end case; */
      else
        select IsNull(@frefOrderFactuurAdres, @FactuurAdres), IsNull(@frefOrderVerzendAdres, @VerzendAdres), IsNull(@frefOrderEindAdres, @EindAdres) into @FactuurAdres, @VerzendAdres, @EindAdres;
      	if exists(select 1 from tabBetalingsConditie where BtcNummer = @fkBtcNummer) or (@fkBtcNummer is null) then
      	  set @OrkBtcNummer = @fkBtcNummer;
     	  if exists(select 1 from tabBetalingsconditie where BtcNummer = @OrkBtcNummer and SoortFactuurBtc = 3) then
     	    set @OrkIncNawRekGid = null;
     	    select NawRekGid into @OrkIncNawRekGid from tabNawRekening where NawRekNawGid = IsNull(@OrkFactuurNawGid, @OrkNawGid) and NawRekBankRekening = @fkIncassoRekNummer;
     	    if @OrkIncNawRekGid is null then
     	      set @KopError = @KopError + 8192;
     	      set @OrkIncNawRekGid = @NawIncRek;
     	    end if;
     	  end if;
      	else
      	  set @KopError = @KopError + 2048;
      	  set @OrkBtcNummer = @NawBtcNummer;
      	  if exists(select 1 from tabBetalingsconditie where BtcNummer = @OrkBtcNummer and SoortFactuurBtc = 3) then
      	    set @OrkIncNawRekGid = @NawIncRek;
      	  end if;
      	end if;
      	if exists(select 1 from tabLeveringsConditie where LvcNummer = @frefLvcNummer) or (@frefLvcNummer is null) then
          set @OrkLvcNummer = @frefLvcNummer;
        else
          set @KopError = @KopError + 4096;
          set @OrkLvcNummer = @NawLvcNummer;
        end if;

        set @OrkIsInclBtw  = @fkIsInclBtw;
        set @OrkValNummer  = @fkValNummer;
        set @tmp = (if @VerzendAdres in (0,1,2) then @OrkNawGid else @OrkFactuurNawGid endif);
        call ControleerHistorischAdres( 0, @OrkNawGid,                              null,   @FrefGid, null,					 @KopError, @tmpAdrGid);
        call ControleerHistorischAdres( 1, IsNull(@OrkFactuurNawGid, @OrkNawGid), @FkGid,       null, null, 				 @KopError, @tmpAdrGid);
        call ControleerHistorischAdres(12, @tmp,                                    null,   @FrefGid, @VerzendAdres, @KopError, @VerzAdr);
        call ControleerHistorischAdres(13, @OrkNawGid,                              null,   @FrefGid, @EindAdres,    @KopError, @EindAdr);

        if @frefOrderIsInkoopcombinatie = 1 then
          if @OrkFactuurNawGid is null then
            set @KopError = @KopError + 4;
          end if;
          if @OrkOmzetNawGid is null then
            set @KopError = @KopError + 8;
          end if;
          if @OrkPrijzenNawGid is null then
            set @KopError = @KopError + 16;
          end if;
        end if;

      end if;  // soort in 1,2

      if @OrkNawGid is null then
        set @KopError = @KopError + 2;
      end if;

      if @KopError & 2 = 0 then
        if @frefOrderIsInkoopCombinatie = 0 then
          set @OrkFactuurNawGid = null;
          set @OrkOmzetNawGid   = null;
      	  set @OrkPrijzenNawGid = null;
        end if;

        call OrdersGenereerNieuwOrderNummer(0, 1, @OrkNummer);
        if @OrkNummerVan is null then
          set @OrkNummerVan = @OrkNummer
        end if;
        set @OrkNummerTot = @OrkNummer;

        case @VGOrderdatum
          when 1 then set @OrkOrderdatum = Now();
          when 2 then set @OrkOrderdatum = @@VerwerkingsDatum;
          when 0 then set @OrkOrderdatum = @@VerwerkingsDatum;  // Dit moet maar zo, aangezien deze mandatory is..
        end case;
        case @VGLeverdatum
          when 1 then set @OrkLeverdatum = Now();
          when 2 then set @OrkLeverdatum = @@VerwerkingsDatum;
          when 3 then set @OrkLeverdatum = @OrkOrderDatum;
          when 0 then set @OrkLeverDatum = null;
        end case;

        set @OrkRelGid = @NawRelGid;

        if @SoortKopie = 2 /* creditnota */ then
          if @frefVtgCode is not null then
            if exists(select VtgCode from tabVertegenwoordiger where VtgCode = @frefVtgCode) then
              set @OrkVtgCode = @frefVtgCode;
            else
              set @KopError = @KopError + 512;
            end if
          end if
        else
          case @VGVtg
            when 0 then set @OrkVtgCode = null;
            when 1 then set @OrkVtgCode = (select RelVtgCode from tabgebruiker inner join tabrelatie on (RelGid = GebrRelGID)where NaamGebruiker = @@GebruikerCode);
            when 2 then set @OrkVtgCode = @NawVertegenwCode;
          end case;
        end if;

        //        _____ ____   _____
        //       / ____|  _ \ / ____|
        //      | |    | |_) | (___
        //      | |    |  _ < \___ \
        //      | |____| |_) |____) |
        //       \_____|____/|_____/
        //
        // Voor CBS gegevens geldt dat bij kopiesoort
        // 0 (obv huidige gegevens)        : alles obv de defaults ingevuld wordt, zoals bij een normale invoer
        // 1,2 (obv hist gegevens, credit) : alles obv de historie opgezocht en ingevuld wordt
        //
        if (IsModuleActive('c1') = 1) then
          if (@SoortKopie = 0) then
            select CbsVastExtraHandelNaarCbsIris,  CbsVastCbsGsGidUitvoer,  CbsVastCbsSsGidUitvoer,  CbsVastPtnGidUitvoer,  CbsVastCbsVwGidUitvoer,  CbsVastCbsCoGidUitvoer,  CbsVastCbsTrGidUitvoer
             into  @CbsExtra,                     @CbsVastCbsGsGidUitvoer, @CbsVastCbsSsGidUitvoer, @CbsVastPtnGidUitvoer, @CbsVastCbsVwGidUitvoer, @CbsVastCbsCoGidUitvoer, @CbsVastCbsTrGidUitvoer
            from tabCbsVast;

            case @VerzendAdres
              when 0 then set @tmpAdrGid = (select NawGidCorrespondentie from tabNaw where NawGid = @OrkNawGid);
              when 1 then set @tmpAdrGid = (select NawGidVestiging from tabNaw where NawGid = @OrkNawGid);
              when 2 then set @tmpAdrGid = @VerzAdr;
              when 3 then set @tmpAdrGid = (select NawGidCorrespondentie from tabNaw where NawGid = @OrkFactuurNawGid);
              when 4 then set @tmpAdrGid = (select NawGidVestiging from tabNaw where NawGid = @OrkFactuurNawGid);
              when 5 then set @tmpAdrGid = @VerzAdr;
            end case;

            set @OrkCbslndGIDBestemming = (select AdrLndGid from tabAdres where AdrGid = @tmpAdrGid);

            // De vervoerder bepalen in volgorde van: debiteur, land, vaste geg
            select IsNull((select VrvGid from tabVervoerder inner join tabNaw on NawVrvGid = VrvGid where NawGid = (if @VerzendAdres in (0,1,2) then @OrkNawGid else @OrkFactuurNawGid endif)),
                          (select LndVrvGid from tabLand where LndGid = @OrkCbslndGIDBestemming),
                          (select VrvGid from tabVervoerder where VrvIsDefault = 1)) into @OrkVrvGid;

            set @OrkCbsMeenemenInAangifte = IsNull(if (@OrkCbslndGIDBestemming <> (select DefaultLndGid from tabVasteGegevens)) and
                                                   ((@CbsExtra <> 0) or (select LndIsEGLid from tabLand where LndGid = @OrkCbslndGIDBestemming) <> 0) then 1 else 0 endif, 0);

            if @OrkCbsMeenemenInAangifte = 0 then
              set @OrkCbsGsGid = null;
              set @OrkCbsSsGid = null;
              set @OrkCbsVgGid = null;
              set @OrkCbsVwGid = null;
              set @OrkCbsCoGid = null;
              set @OrrCbsTrGid = null;
              set @OrkCbslndGIDBestemming = null;
            else
              set @OrkCbsGsGid = @CbsVastCbsGsGidUitvoer;
              set @OrkCbsSsGid = @CbsVastCbsSsGidUitvoer;
              set @OrkCbsVgGid = @CbsVastPtnGidUitvoer;
              set @OrkCbsVwGid = @CbsVastCbsVwGidUitvoer;
              set @OrkCbsCoGid = @CbsVastCbsCoGidUitvoer;
              set @OrrCbsTrGid = @CbsVastCbsTrGidUitvoer;
              //set @OrkCbslndGIDBestemming = ZIE BOVEN
            end if;
          else
            // Soort kopie = obv historie, of credit
            set @OrkCbsMeenemenInAangifte = @FrefCbsMeenemenInAangifte;
            if @OrkCbsMeenemenInAangifte = 1 then
              set @OrkCbsCoGid = (select first CbsCoGid from tabCbsContainer          where CbsCoCode = @FrefCbsCoCode);
              set @OrkCbsGsGid = (select first CbsGsGid from tabCbsGoederenStroom     where CbsGsCode = @FrefCbsGsCode);
              set @OrkCbsSsGid = (select first CbsSsGid from tabCbsStatistischStelsel where CbsSsCode = @FrefCbsSsCode);
              set @OrkCbsVwGid = (select first CbsVwGid from tabCbsVervoerwijze       where CbsVwCode = @FrefCbsVwCode);
              set @OrkCbsVgGid = (select first PtnGid   from tabPlaatsNaam where PtnCbsVerkeersGebied = @FrefCbsVgCode);
              set @OrkCbsLndGidBestemming = (select first LndGid from tabLand where LndEigenCode = @FrefCbsLandBestemLndEigenCode);
            end if;
          end if;
        end if;

        insert into tabOrderKop (OrkSoort,  OrkNummer,   OrkInclBtw,        OrkDatum,  OrkLeverDatum, OrkNawGid, OrkValNummer, OrkBtcNummer,   OrkLvcNummer,   OrkVtgCode, OrkReferentie, OrkFactuurAdres, OrkVerzendAdres,  OrkApartFaktureren,         OrkIsInkoopCombinatie,  OrkFactuurNawGid,  OrkNawGidOmzet,  OrkNawGidPrijzen, OrkIsVerzamellijstGebruiken,

        			  OrkAdrGid, OrkEindAdres, OrkAdrGidEindAdres, OrkIsDeelLeveringToegestaan, OrkIncNawRekGid, OrkRelGid,
        			  OrkCbsMeenemenInAangifte, OrkCbslndGIDBestemming, OrkCbsGsGid, OrkCbsSsGid, OrkCbsPtnGidVerkeersgebied, OrkCbsVwGid, OrkCbsCoGid, OrkIsAbcLevering, OrkDefaultMagGid, OrkVrvGid)
                      values    (       0, @OrkNummer, @OrkIsInclBtw, @OrkOrderDatum, @OrkLeverDatum, @OrkNawGid, @OrkValNummer, @OrkBtcNummer, @OrkLvcNummer, @OrkVtgCode,      @frefOms,   @FactuurAdres,   @VerzendAdres,       @NawApartFact,  @frefOrderIsInkoopcombinatie, @OrkFactuurNawGid, @OrkOmzetNawGid, @OrkPrijzenNawGid, @VGIsVerzamellijstGebruiken,
                                  (if @VerzendAdres in (2,5) then @VerzAdr else null endif), @EindAdres, (if @EindAdres = 2 then @EindAdr else null endif), @VGDeelLevering, @OrkIncNawRekGid, @OrkRelGid,
                                  @OrkCbsMeenemenInAangifte, @OrkCbsLndGidBestemming, @OrkCbsGsGid, @OrkCbsSsGid, @OrkCbsVgGid, @OrkCbsVwGid, (if (@SoortKopie in (1,2) or @CbsExtra = 1) then @OrkCbsCoGid else null endif), @FkIsAbcLevering, IsNull(@OrkMagGid, @OrkDefaultMagGid), @OrkVrvGid);
        set @OrkGid = @@Identity;

        // begin vrije rubrieken
        // de storedproc voor het overnemen van de vrije rubrieken vd debiteur naar de order
        call OrdersOvernemenVrijeRubrieken(@OrkGid);
        if ((@SoortKopie in (0,1)) and (@VrObvHist & 1 <> 0)) or ((@SoortKopie = 2) and (@VrObvHist & 2) <> 0) then
          // de storedproc voor het overnemen van de vrije rubrieken vd historie naar de order
          call OrdersOvernemenVrijeRubriekenHistorie(@OrkGid, @frefGid);
        end if;
        // controleren of er verplichte vrije rubrieken zijn die geen waarde hebben
        set @VerplichteVrLeeg = 0;
        open cursor_Vrije_Rubrieken_OrderKop;
        VrOrderLoop:
        loop
          Fetch next cursor_Vrije_Rubrieken_OrderKop into @OrkVrVeldnaam, @OrkVrType;
          if sqlstate = '02000' then
            leave VrOrderLoop;
          end if;

          execute immediate 'set @VerplichteVrLeeg = (select
                            (if (not exists(select 1
                                            from tabVrORK000000
                                            where VrORK000000RecordId = ' + string(@OrkGid) + ') or ' +
                                    'exists(select 1
                                            from tabVrORK000000
                                            where VrORK000000RecordId = ' + string(@OrkGid) +
                                            ' and (' + string(@OrkVrVeldNaam) + ' is null' +
                                            ' or ((' + string(@OrkVrType) + ' not in (1,2,3)) and IsNull('+string(@OrkVrVeldNaam)+','''') = '''' )))' +
                                ') then 1 else 0 endif))';

          //call Trace('---------->@VerplichteVrLeeg='+string(@VerplichteVrLeeg));

          if @VerplichteVrLeeg = 1 then
            set @KopError = @KopError + 16384;
            leave VrOrderLoop;
          end if;

        end loop VrOrderLoop;
        close cursor_Vrije_Rubrieken_OrderKop;
    // einde vrije rubrieken

      else
        set @OrkGid = -1;
      end if;
      // Foutoverzicht invullen
      if @KopError & 1 <> 0 then
         insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid )                 Values ( @VolgNr, 1, @OrkGid, @FrefGid );
      else // Inkoopcombi wordt niet opgeslagen in de oude versies, dus hoeft ook niet op gecontroleerd te worden.
        if @KopError &   4 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr, 3, @OrkGid, @FrefGid, @fkDebNummer                ); end if;
        if @KopError &   8 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr, 4, @OrkGid, @FrefGid, @frefOrderOmzDebNummer     ); end if;
        if @KopError &  16 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr, 5, @OrkGid, @FrefGid, @frefOrderPrijzenDebNummer ); end if;
      end if;
      if @KopError &     2 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr,  2, @OrkGid, @FrefGid, @frefOrderDebNummer        ); end if;
      if @KopError &    32 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr,  6, @OrkGid, @FrefGid, _U('Corr.Adres gewijzigd')     ); end if;
      if @KopError &    64 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr,  7, @OrkGid, @FrefGid, _U('Fact.Adres gewijzigd')     ); end if;
      if @KopError &   128 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr,  8, @OrkGid, @FrefGid, _U('Verz.Adres gewijzigd')     ); end if;
      if @KopError &   256 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr,  9, @OrkGid, @FrefGid, _U('Eind.Adres gewijzigd')     ); end if;
      if @KopError &   512 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr, 10, @OrkGid, @FrefGid, _U('Vertegenw. gewijzigd/verwijderd')     ); end if;
      if @KopError &  2048 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr, 11, @OrkGid, @FrefGid, _U('Betalingsconditie verwijderd')); end if;
      if @KopError &  4096 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr, 12, @OrkGid, @FrefGid, _U('Leveringsconditie verwijderd')); end if;
      if @KopError &  8192 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr, 13, @OrkGid, @FrefGid, _U('Incasso-rekening verwijderd')); end if;
      if @KopError & 16384 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde ) Values ( @VolgNr, 14, @OrkGid, @FrefGid, _U('Verplichte vrije rubriek niet ingevuld')); end if;

    else
      // Wel OrkGid meegegeven -> Alleen de _regels_ van deze factuur toevoegen aan meegegeven order
      set @OrkGid = @OrkGidIn;
      select OrkInclBtw, OrkValNummer, IsNull(OrkFactuurNawGid, OrkNawGid) into @OrkIsInclBtw, @OrkValNummer, @OrkNawGid from tabOrderKop where OrkGid = @OrkGid;
      select BtwCode, BtwPercentage into @DebBtwCode, @DebBtwPerc from tabNawFile left outer join tabBtw on NawFilBtwCode = BtwCode where NawFilNawGid = @OrkNawGid and NawFilFonId = 'D';
      select vofFactVoorraadReserveren, VofFactVoorraadReserverenNegatief, vofOrderKortingSoort, vofRegelDefNuLeveren, vofRegelDefNuFactureren
        into @VGReservering, @VGReserveringNegatief, @VGOrderKortingSoort, @VGRegelDefNuLeveren, @VGRegelDefNuFactureren
      from tabVasteGegevensOrdersFactureren;
    end if;

    for @Cursor AS CURSOR_OrderRegels CURSOR FOR // OrderRegels Begin
      select
        frGid                           @frGid,
        frSoortRegel                    @frSoortRegel,
        frArtCode                       @frArtCode,
        frOpbrGrpNummer                 @frOpbrGrpNummer,
        frBtwCode                       @frBtwCode,
        frBtwPercentage                 @frBtwPercentage,
        frKstpCode                      @frKstpCode,
        frKstdCode                      @frKstdCode,
        frAantDecAantal                 @frAantDecAantal,
        frAantDecAantalVrrdEenh         @frAantDecAantalVrrdEenh,
        frAantDecBedrag                 @frAantDecBedrag,
        frIsAantal                      @frIsAantal,
        frPrijsPer                      @frPrijsPer,
        frMagazijnCode                  @frMagazijnCode,
        frOrrArtPartijNummer            @frOrrArtPartijNummer,
        frAantalBesteld                 @frAantalBesteld,
        frAantalBesteldVrrdEenh         @frAantalBesteldVrrdEenh,
        frAantalDezeLevering            @frAantalDezeLevering,
        frAantalDezeLeveringVrrdEenh    @frAantalDezeLeveringVrrdEenh,
        frAantalDezeFacturering         @frAantalDezeFacturering,
        frAantalDezeFactureringVrrdEenh @frAantalDezeFactureringVrrdEenh,
        frBrutoPrijsPEenheid            @frBrutoPrijsPEenheid,
        frNettoPrijsPeenheid            @frNettoPrijsPeenheid,
        frKorting1Bedrag                @frKorting1Bedrag,
        frKorting1Perc                  @frKorting1Perc,
        frKorting2Perc                  @frKorting2Perc,
        frTekstOpFactuur                @frTekstOpFactuur,
        frKostprijs                     @frKostprijs,
        frRegelTotaal                   @frRegelTotaal,
        FrEenheidPrijsPer               @FrEenheidPrijsPer,
        frVerkoopEenheid                @frVerkoopEenheid,
        FrAantalVrrdEenhInVerkEenh      @FrAantalVrrdEenhInVerkEenh,
        FrAantalVrrdEenhInVerkEenhMagAfwijken @FrAantalVrrdEenhInVerkEenhMagAfwijken,
        FrOrrVervolgMasterOrrGid        @FrOrrVervolgMasterOrrGid,
        FrOrrGid                        @FrOrrgid,
        FrCbsTrCode                     @FrCbsTrCode,
        FrCbsLndEigenCodeOorsprong      @FrCbsLndEigenCodeOorsprong
      from       tabFactuurReferentie
      inner join tabFactuurRegel on frFrefGid = @FrefGid
      inner join tmpFactuurNaarOrder on fnoSoort = 1 and fnoRefRegelGid = FrGid and fnoVolgNr = @VolgNr and fnoVerwerken = 1
      where @OrkGid <> -1     // Indien we de order niet toe kunnen voegen, dan ook geen orderregels selecteren
        and frefGid = @FrefGid
        and ((@frSoortRegel = 0) or ((@SoortKopie <> 2) or (@SoortKopie = 2 and @frAantalDezeFacturering <> 0))) // bug 25616
      order by frRegelNummer
    for read only
    do
    /*
      Regel Errorcodes
     0 - Alles OK
     1 - Artikel verwijderd
     2 - Partij verwijderd
     8 - Partijregistratie uitgezet
    16 - Kstp verwijderd
    32 - Kstd verwijderd
    64 - Geen verplichte partij in kunnen vullen, regel niet aangemaakt
   128 - Kostprijs is gewijzigd
   */
      set @RegelError = 0;
      // RS 31/08/07 : overige moeten natuurlijk ook gereset worden, toegevoegd nav bug 26762
      // RS 17/11/09 : alle variabelen moeten altijd gereset worden voor iedere regel, bug 31472
      set @OrrArtGid          = null;
      set @ArtIsPartij        = null;
      set @ArtIsSerie         = null;
      set @ArtPartijVerplicht = null;
      set @ArtBtwPerc         = null;
      set @ArtBtwCode         = null;
      set @OrrVkeGid          = null;
      set @WisselNaarVoorraadEenheid = 0;
      if IsNull(@frArtCode, '') <>  '' then
        //ACW 15-02-2010: bug 31522: Ook directe inkoopgegevens opvragen
        select ArtGid, ArtIsPartijRegistreren, ArtSerieNrRegistreren, ArtIsPartijNrBijLeverenVerplicht, BtwPercentage, BtwCode, ArtBestellenViaDirecteInkoop, ArtProducerenViaDirecteProductie, ArtOmsVerkooporderOvernemen, ArtHeeftVoorraad
        into @OrrArtGid, @ArtIsPartij, @ArtIsSerie, @ArtPartijVerplicht, @ArtBtwPerc, @ArtBtwCode, @ArtBestellenViaDirecteInkoop, @ArtProducerenViaDirecteProductie, @ArtOmsVerkooporderOvernemen, @ArtHeeftVoorraad
        from tabArtikel left outer join tabBtw on BtwCode = ArtBtwCode where ArtCode = @frArtCode and ArtSoort = @frSoortRegel;

        if @OrrArtGid is null then
          set @RegelError = @RegelError + 1
        end if;
      end if;

      if (@RegelError & 1 = 0) then  // Artikel kunnen achterhalen, regel toevoegen
        set @OrrMagGid     = null;
        set @OrrOpbrGrpGid = null;
        // Defect 53948 Wens: bij kopie uit historie de opbrengstgroep niet uit de historie maar uit het artikel halen
        select ArtOpbrGrpGid into @OrrOpbrGrpGid from tabArtikel where ArtGid = @OrrArtGid;
        //select OpbrGrpGid into @OrrOpbrGrpGid   from tabOpbrengstGroep where OpbrGrpNummer = @frOpbrGrpNummer;
        select MagGid     into @OrrMagGid       from tabMagazijn        where MagCode = @frMagazijnCode;
        set @OrrMagGid = IsNull(@OrrMagGid, (select ArtDefaultMagGid from tabArtikel where ArtGid = @OrrArtGid));

        if @ArtIsPartij <> 0 then
          call BepaalPartijObvNummer(@OrrArtGid, @frOrrArtPartijNummer, @OrrArtPartijGid, @RegelError);
        else
          set @OrrArtPartijGid = null;
          if (IsNull(@frOrrArtPartijNummer,'') <> '' and @ArtIsSerie = 0)  or
             (IsNull(@frOrrArtPartijNummer,'(Standaard)') <> '(Standaard)' and @ArtIsSerie = 1) then
            set @RegelError = @RegelError + 8;
          end if;
        end if;
        // Kan nog misgaan op verplicthe partij die niet gevonden kon worden
        if (((@RegelError & 8) <> 0) or (@OrrArtPartijGid is null)) and @ArtPartijVerplicht = 1 then
          set @RegelError = @RegelError + 64;
        end if;
      end if;

      if (@RegelError & 1 = 0) and (@RegelError & 64 = 0) then // Artikel kunnen achterhalen, regel toevoegen

        if @frSoortRegel in (1 /* tarief */, 2 /* artikel */ ) then
          select IsNull(ArtPartijKostprijsEx, ArtKostprijsEx) into @OrrKostPrijs from tabArtikel left outer join tabArtikelPartij on ArtPartijGid = @OrrArtPartijGid and ArtPartijArtGid = ArtGid where ArtGid = @OrrArtGid;
          if @SoortKopie = 2 and @OrrKostPrijs <> @frKostprijs then
            //set @RegelError = @RegelError + 128;
            set @OrrKostPrijs = @frKostprijs;                               //bug:54069
          end if;
        else
          set @OrrKostprijs = null;
        end if;

        if IsNull(@frKstpCode,'') <> '' then
          select KstpGid into @OrrKstpGid from tabKostenplaats where KstpCode = @frKstpCode;
          if @OrrkstpGid is null then
            set @RegelError = @RegelError + 16;
          end if;
        end if;

        if IsNull(@frKstdCode,'') <> '' then
          select KstdGid into @OrrKstdGid from tabKostendrager where KstdCode = @frKstdCode;
          if @OrrkstdGid is null then
            set @RegelError = @RegelError + 32;
          end if;
        end if;

        if IsNull(@FrVerkoopEenheid, '') <> '' then
          select VkeGid into @OrrVkeGid from tabVerkoopEenheid where VkeArtGid = @OrrArtGid and VkeVerkoopEenheid = @FrVerkoopEenheid;
          if @OrrVkeGid is null then
            set @RegelError = @RegelError + 1024;
            set @WisselNaarVoorraadEenheid = 1;
            //call Trace('Vke wissel naar voorraadeenheid 1024');
            select VkeGid into @OrrVkeGid from tabVerkoopEenheid where VkeArtGid = @OrrArtGid and VkeIsVoorraadEenheid = 1;
          end if;

          select VkeAantalKanVerschillen, VkeAantalVoorraadEenhedenInVerkoopEenheid into @VkeAantalKanVerschillen, @VkeAantalVrdInVerkEenh from tabVerkoopEenheid where VkeGid = @OrrVkeGid;

          if (@RegelError & 1024) = 0 then
            //call Trace('Vke - @OrrVkeGid='+string(@OrrVkeGid)+'; @VkeAantalKanVerschillen='+string(@VkeAantalKanVerschillen)+'; @FrAantalVrrdEenhInVerkEenhMagAfwijken='+string(@FrAantalVrrdEenhInVerkEenhMagAfwijken)+'; @VkeAantalVrdInVerkEenh='+string(@VkeAantalVrdInVerkEenh)+'; FrAantalVrrdEenhInVerkEenh='+string(@FrAantalVrrdEenhInVerkEenh)+';');
            if (@VkeAantalVrdInVerkEenh  <> @FrAantalVrrdEenhInVerkEenh) then
              set @RegelError = @RegelError + 2048;
              // Als de aantallen in de verkeenheid gewijzigd zijn dan is een 1 op 1 creditorder niet mogelijk als de verkeenheid aantallen niet mogen afwijken, dan de voorraadeenheid gebruiken
              if (@SoortKopie = 2) and (@VkeAantalKanVerschillen = 0) then
                set @WisselNaarVoorraadEenheid = 1;
                //call Trace('Vke wissel naar voorraadeenheid 2048');
                select VkeGid into @OrrVkeGid from tabVerkoopEenheid where VkeArtGid = @OrrArtGid and VkeIsVoorraadEenheid = 1;
              end if;
            end if;
          end if;
        end if;

        if @SoortKopie = 0 then
          // begin HUIDIG
          set @OrrAantal = @frAantalBesteld;
          set @OrrAantalVrrdEenh = @frAantalBesteldVrrdEenh;
          set @frKorting1Bedrag = null;
          set @frKorting1Perc   = null;
          set @frKorting2Perc   = null;
          if @VGOrderKortingSoort = 2 then //Orderkorting als regelkorting 2 opnemen
            select (if NawFilWelkeOrderKorting = 1 then DebGrpOrderKorting else NawOrderKorting endif) into @frKorting2Perc from tabNaw inner join tabNawFile on NawFilNawGid = NawGid and NawFilFonId = 'D' left outer join tabDebiteurGroepen on NawFilDebGrpGid = DebGrpGid where NawFilNawGid = IsNull(@OrkPrijzenNawGid, @OrkNawGid);
          end if;

          if @OrkGidIn is null then
            set @FkIsInclBtw = @OrkIsInclBtw;
            set @FkValNummer = @OrkValNummer;
          end if;

          if @DebBtwPerc = 0.00 then
            set @frBtwCode       =  @DebBtwCode;
            set @frBtwPercentage =  @DebBtwPerc;
          else
            if IsNull(@frArtCode, '') <>  '' then
              set @frBtwCode       =  @ArtBtwCode;
              set @frBtwPercentage =  @ArtBtwPerc;
            end if;
          end if;

          //ACW 12-05-2015 #45338: Als er een NawGid voor de prijzen is (inkoopcombinatie), dan die voor de prijsafspraak gebruiken
          call BepaalPrijsAfspraak(isnull(@OrkPrijzenNawGid,@OrkNawGid), @OrrArtGid, @OrrVkeGid, null, @DebGrpGid, @OrrArtPartijGid, @fkIsInclBtw, @fkValNummer, @frAantalBesteld, @frAantalBesteldVrrdEenh,
                                   @@BasisValutaNummer, @@BasisValutaCode, @@Verwerkingsdatum, @PraGid, @PraIsInclBtw, @PraValNummer, @PraValcode, @OrrVerkoopPrijs, @KortingSoort, @frKorting1Perc,
                                   @frKorting1Bedrag, @TypeAfspraak, null, @PrijzenPer);
          // eind HUIDIG
        elseif @SoortKopie = 1 then
          // begin HISTORIE
          set @OrrAantal = @frAantalBesteld;
          set @OrrAantalVrrdEenh = @frAantalBesteldVrrdEenh;
          set @OrrVerkoopPrijs = @frBrutoPrijsPEenheid;
        //  if @OrkGidIn is null then
            if @OrkValNummer <> @FkValNummer then
              set @OrrVerkoopPrijs = ValutaOmrekenen(@FkValNummer, @OrrVerkoopPrijs, @OrkValNummer, @BjGid, @PerNr, 4);
            end if;

            if @OrkIsInclBtw <> @FkIsInclBtw then
              if @OrkIsInclBtw = 0 then
                if (@DebBtwPerc = 0.00) and (@frBtwPercentage <> 0.0) then // Buitenlandse deb, eerder wel met btw gefactureerd, maar moet er obv de huidige naw-instelling toch weer af
                  set @OrrVerkoopPrijs = (@OrrVerkoopPrijs / Round(1+(@frBtwPercentage/100),4));
                  set @frBtwCode       =  @DebBtwCode;
                  set @frBtwPercentage =  @DebBtwPerc;
                else // Was Incl, wordt Excl
                  set @OrrVerkoopPrijs = (@OrrVerkoopPrijs / Round(1+(@frBtwPercentage/100),4));
                end if;
              else
                if @DebBtwPerc <> 0.00 then  // Buitenlandse deb, geen btw toevoegen
                  set @OrrVerkoopPrijs = (@OrrVerkoopPrijs * Round(1+(@frBtwPercentage/100),4));
                end if;
              end if;
            else  // else van Order <> Factuur
              if (@FkIsInclBtw = 1) and (@frBtwPercentage <> @ArtBtwPerc) and (@frBtwPercentage <> 0.0) then // Is het perc van de btw veranderd?
                set @OrrVerkoopPrijs = (@OrrVerkoopPrijs / Round(1+(@frBtwPercentage/100),4));  // oude btw eraf
                if @DebBtwPerc = 0.00 then // Geen nieuwe btw erbij, dus btwcode van deb overnemen
                  set @frBtwCode       =  @DebBtwCode;
                  set @frBtwPercentage =  @DebBtwPerc;
                else
                  if @OrkIsInclBtw = 1 then
                    set @OrrVerkoopPrijs = (@OrrVerkoopPrijs * Round(1+(@ArtBtwPerc/100),4));  // nieuwe btw erbij
                  end if;
                end if;
              elseif (@DebBtwPerc = 0.00) and (@frBtwPercentage <> 0.0) then  // Buitenlandse deb in de order, en btw in de factuur, die er dus afhalen
                if @FkIsInclBtw = 1 then // 34008, btw alleen aftrekken indien het hist. bedrag incl is
                  set @OrrVerkoopPrijs = (@OrrVerkoopPrijs / Round(1+(@frBtwPercentage/100),4));
                end if;
                set @frBtwCode       =  @DebBtwCode;
                set @frBtwPercentage =  @DebBtwPerc;
              end if;
            end if;
          // eind HISTORIE
        else
          // begin CREDIT
          set @OrrVerkoopPrijs =  @frBrutoPrijsPEenheid;
          //if @OrkGidIn is null then
            if @OrkValNummer <> @FkValNummer then
              set @OrrVerkoopPrijs = ValutaOmrekenen(@FkValNummer, @OrrVerkoopPrijs, @OrkValNummer, @BjGid, @PerNr, 4);
            end if;

            if @OrkIsInclBtw <> @FkIsInclBtw then   // RS 13-10-2009 bug 30964, bij gewijzigd nieuwe btw perc gebruiken
            // RS defect 59790 Geen rekening meer houden met buitenlandse debiteur in geval van creditorder, altijd de BTW vanuit de historie overnemen
              if @OrkIsInclBtw = 0 then
                set @OrrVerkoopPrijs = (@OrrVerkoopPrijs * Round(1+(@frBtwPercentage/100),4));
              end if;
            end if;
          //end if;
          set @OrrAantal = -@frAantalDezeFacturering;
          set @OrrAantalVrrdEenh = -@frAantalDezeFactureringVrrdEenh;
          // eind CREDIT
        end if;

        // Directe inkoop en productie
        set @OrrRcptGid = null;
        if @SoortKopie = 2 /*credit*/ then
        	set @OrrDirecteInkoop = 0;
        	set @OrrProductie 		= 0;
       	else
        	set @OrrDirecteInkoop = @ArtBestellenViaDirecteInkoop;
        	set @OrrProductie 		= @ArtProducerenViaDirecteProductie;
        	//Indien productie AAN, dan alleen het recept invullen als dat het enige recept is
        	if @OrrProductie <> 0 and (select count(1) from tabReceptuur inner join tabReceptuurEindProduct on RcpeRcptGid = RcptGid where RcpeArtGid = @OrrArtGid and RcptGeblokkeerd = 0) = 1 then
        		set @OrrRcptGid = (select first RcptGid from tabReceptuur inner join tabReceptuurEindProduct on RcpeRcptGid = RcptGid where RcpeArtGid = @OrrArtGid and RcptGeblokkeerd = 0);
        	end if;
       	end if;

        //ACW 15-02-2010: bug 31522: Bij directe inkoop de normale gegevens aanpassen
        if @OrrDirecteInkoop <> 0 and ((@OrrAantal > 0) or (@VkeAantalKanVerschillen = 2 and @OrrAantalVrrdEenh >0))  then
          set @OrrAantalLevering = 0; // Restant komt dan vanzelf in backorder
          set @OrrAantalLeveringVrrdEenh = 0; // Restant komt dan vanzelf in backorder
        else
          set @OrrAantalLevering = @OrrAantal;
          set @OrrAantalLeveringVrrdEenh = @OrrAantalVrrdEenh;
        end if;

				if (@SoortKopie = 0 and @Kortingsoort = 2) /*via BepaalPrijsAfspraak*/ or (@SoortKopie in (1,2) and @frKorting1Perc is null and @frKorting1Bedrag is not null) /*via historie*/ then
          set @IsKortPerc = 0;
          // RS 12-4-2011 bug 33493 - kortingsbdrag bij stukskorting terugrekenen van regel naar stuks
          if (@VGStuksKorting = 0) or ((@OrrAantal = 0) and (@OrrAantalVrrdEenh = 0)) or (@SoortKopie = 0) then
            set @Korting1   = @frKorting1Bedrag
          else
          set @Korting1   = round(@frKorting1Bedrag / (if @SoortKopie = 2 then (if @FrEenheidPrijsPer = 0 then -@OrrAantal else -@OrrAantalVrrdEenh endif) else (if @FrEenheidPrijsPer = 0 then @OrrAantal else @OrrAantalVrrdEenh endif) endif), 2);
          end if;
        else
          set @IsKortPerc = 1;
          set @Korting1   = @frKorting1Perc;
        end if;
        set @Korting2 = @frKorting2Perc;


				select sum(calcVrijeVoorraad), sum(calcBeschikbareVoorraad)
          into @VrijeVoorraad, @BeschikbareVoorraad
				from  vwVoorraadAantallen
				where (calcArtGid = @OrrArtGid)
          and (calcMagGid = @OrrMagGid)
          and (@OrrArtPartijGid is null or calcArtPartijGid = @OrrArtPartijGid);

        if @OrrDirecteInkoop <> 0 and @VrijeVoorraad > 0.0 then set @RegelError = @RegelError +  8192; endif;
        if @OrrProductie     <> 0 and @VrijeVoorraad > 0.0 then set @RegelError = @RegelError + 16384; endif;

        //call Trace('--->@OrrAantal='+string(@OrrAantal)+', @VGRegelDefNuLeveren='+string(@VGRegelDefNuLeveren)+', @ArtHeeftVoorraad='+string(@ArtHeeftVoorraad)+', @frSoortRegel='+string(@frSoortRegel));
				if (@OrrAantalVrrdEenh > 0.0) and (@VGRegelDefNuLeveren in (2, 3)) and (@ArtHeeftVoorraad = 1) and (@frSoortRegel = 2) then
					//MR 20-jun-2011 bug #33150: Bij deze instellingen in backorder zetten waar nodig
					//RS 27-2-2011 bug 34887: blok alleen uitvoeren bij aantal > 0 en geen null vars meer gebruiken
          //call Trace('----->>> @VrijeVoorraad='+string(@VrijeVoorraad)+', @OrrAantal='+string(@OrrAantal));

          //MR 19-jan-2021: Vaste gegevens staat op Vrije voorraad
          if (@VGRegelDefNuLeveren = 2) then
            if (@VrijeVoorraad < 0.0) then
              set @OrrAantalLeveringVrrdEenh = 0.0;
            else
              if (@VrijeVoorraad < @OrrAantal) then
                set @OrrAantalLeveringVrrdEenh = @VrijeVoorraad;
              else
                set @OrrAantalLeveringVrrdEenh = @OrrAantalVrrdEenh;
              end if;
            end if;
          end if;

          //MR 19-jan-2021: Vaste gegevens staat op beschikbare voorraad
          if (@VGRegelDefNuLeveren = 3) then
            if (@BeschikbareVoorraad < 0.0) then
              set @OrrAantalLeveringVrrdEenh = 0.0;
            else
              if (@BeschikbareVoorraad < @OrrAantal) then
                set @OrrAantalLeveringVrrdEenh = @BeschikbareVoorraad;
              else
                set @OrrAantalLeveringVrrdEenh = @OrrAantalVrrdEenh;
              end if;
            end if;
          end if;

          set @OrrAantalLevering = @OrrAantalLeveringVrrdEenh / @VkeAantalVrdInVerkEenh;

					// RS hieronder weggecomment - aantal backorder wordt autom. gevuld adhv verschil besteld en deze levering
					//set @OrrAantalBackorder = @OrrAantal - @OrrAantalGeleverd - @OrrAantalLevering;
				end if;

				set @OrrAantalFacturering = @OrrAantalLevering;
				set @OrrAantalFactureringVrrdEenh = @OrrAantalLeveringVrrdEenh;

				// RS 7-6-12 35680: voor aantal facturering rekening houden met de VG instelling
				case @VGRegelDefNuFactureren
					when 0 then
					  begin
					    set @OrrAantalFacturering = null;
					    set @OrrAantalFactureringVrrdEenh = null;
					  end
					when 1 then
					  begin
					    set @OrrAantalFacturering = @OrrAantal;
					    set @OrrAantalFactureringVrrdEenh = @OrrAantalVrrdEenh;
					  end;
				end case;

				if @WisselNaarVoorraadEenheid = 1 then // De verkoopeenheid bestaat niet meer of kan niet gebruikt worden, dan de voorraadeenheid gebruiken en de originele voorraadaantallen hanteren
				  //call Trace('Vke - gewisseld van verkoopeenheid naar voorraadeenheid');
				  set @OrrAantal = @OrrAantalVrrdEenh;
				  set @OrrAantalFacturering = @OrrAantalFactureringVrrdEenh;
				  set @OrrAantalLevering = @OrrAantalLeveringVrrdEenh;
			  end if;

        // De voorraadaantallen in de verkoopeenheid zijn mogelijk gewijzigd. Voorraadaantallen opnieuw berekenen
				if (@RegelError & 2048 <> 0) and (@WisselNaarVoorraadEenheid = 0) and (@SoortKopie in (0,1)) then
				  //call Trace('Vke - voorraadaantallen opnieuw berekenen');
				  set @FrAantalVrrdEenhInVerkEenh = @VkeAantalVrdInVerkEenh;
				  set @OrrAantalVrrdEenh = @OrrAantal * @VkeAantalVrdInVerkEenh;
				  set @OrrAantalFactureringVrrdEenh = @OrrAantalFacturering * @VkeAantalVrdInVerkEenh;
				  set @OrrAantalLeveringVrrdEenh = @OrrAantalLevering * @VkeAantalVrdInVerkEenh;
			  end if;

        //call Trace('MaakOrderVanFactuur - ORR INSERT -> @OrkGid='+string(@OrkGid)+', @OrrArtGid='+string(@OrrArtGid)+', @OrrMagGid='+string(@OrrMagGid)+', @OrrOpbrGrpGid='+string(@OrrOpbrGrpGid)+', @OrrArtPartijGid='+string(@OrrArtPartijGid)+', @OrrVerkoopPrijs='+string(@OrrVerkoopPrijs)+', @OrrAantal='+string(@OrrAantal)+'@RegelError='+string(@RegelError)+', @frIsAantal='+string(@frIsAantal));
        if (@FrOrrVervolgMasterOrrGid is not null) then
          Select orrGid into @OrrVervolgMasterOrrGid
          from tabOrderRegel
          where OrrFrGid = (select FrGid from tabFactuurRegel where frOrrGid = @FrOrrVervolgMasterOrrGid and frFrefGid = @FrefGid)
          and OrrOrkGid = @OrkGid;
        else
          set @OrrVervolgMasterOrrGid = null;
        end if;

        if @OrkCbsMeenemenInAangifte = 1 then
          if @SoortKopie = 0 then
            set @OrrCbsTrGid           = @CbsVastCbsTrGidUitvoer;
            set @OrrCbsLndGidOorsprong = (select first IsNull(ArtPartijLndGidCbsOorsprong, ArtLndGidCbsOorsprong) from tabArtikel left outer join tabArtikelPartij on ArtPartijArtGid = @OrrArtPartijGid where ArtGid = @OrrArtGid);
          else // Soort kopie obv historie, credit
            set @OrrCbsTrGid           = (select first CbsTrGid from tabCbsTransactie where CbsTrCode = @FrCbsTrCode);
            set @OrrCbsLndGidOorsprong = (select first LndGid from tabLand where LndEigenCode = @FrCbsLndEigenCodeOorsprong);
          end if;
        end if;

        insert into tabOrderRegel ( OrrOrkGid, OrrRegelSoort, OrrArtGid, OrrIsAantallen, OrrAantDecBedrag, OrrAantDecAantal, OrrAantDecAantalVrrdEenh, OrrReservering, OrrReserveringNegatief,
                                    OrrOpbrGrpGId, OrrBtwCode, OrrTekstOpFactuur, OrrMagGid, OrrArtPartijGid,
                                    OrrVkeGid, OrrEenheidPrijsPer, OrrAantalVrrdEenhInVerkEenh, OrrAantalVrrdEenhInVerkEenhMagAfwijken,
                                    OrrAantalBesteld, OrrAantalBesteldVrrdEenh, OrrAantalDezeFacturering, OrrAantalDezeFactureringVrrdEenh, OrrAantallevering, OrrAantalleveringVrrdEenh,
                                    OrrAantalGeleverd, OrrAantalGeleverdVrrdEenh, OrrAantalBackorder, OrrAantalBackorderVrrdEenh, OrrPrijsPer, OrrKostprijs,
                                    OrrBrutoVerkoopPrijs, OrrIsKortingsPercentage, OrrRegelKorting1, OrrRegelKorting2, OrrKstpGid, OrrKstdGid, OrrCbsTrGid, OrrLndGidCbsOorsprong,
                                    OrrDirecteInkoop, OrrProductie, OrrRcptGid, OrrOmsNaarBestelling, OrrFrGid, OrrVervolgMasterOrrGid)
                                    values
                                  ( @OrkGid, @frSoortRegel, @OrrArtGid, if @SoortKopie = 2 then 1 else @frIsAantal endif, @frAantDecBedrag, @frAantDecAantal, @frAantDecAantalVrrdEenh, if @frSoortRegel = 2 then @VGReservering else 0 endif, @VGReserveringNegatief,
                                    @OrrOpbrGrpGid, @frBtwCode, @frTekstOpFactuur, if @frSoortRegel = 2 then IsNull(@OrrMagGid, @OrkDefaultMagGid) endif, @OrrArtPartijGid,
                                    @OrrVkeGid, @FrEenheidPrijsPer, @FrAantalVrrdEenhInVerkEenh, @VkeAantalKanVerschillen,
                                    @OrrAantal, @OrrAantalVrrdEenh, @OrrAantalFacturering, @OrrAantalFactureringVrrdEenh, @OrrAantalLevering, @OrrAantalLeveringVrrdEenh,
                                    0, 0, null /*wordt gevuld in trigger*/, null /*wordt gevuld in trigger*/, @frPrijsPer, @OrrKostPrijs,
                                    @OrrVerkoopPrijs, @IsKortPerc, @Korting1, @Korting2, @OrrkstpGid, @OrrkstdGid, @OrrCbsTrGid, @OrrCbsLndGidOorsprong,
                                    @OrrDirecteInkoop, @OrrProductie, @OrrRcptGid, @ArtOmsVerkooporderOvernemen, @frGid, @OrrVervolgMasterOrrGid);
        set @OrrGid = @@Identity;

        // begin vrije rubrieken
        // de storedproc voor het overnemen van de vrije rubrieken vd debiteur naar de order
        call OrderRegelOvernemenVrijeRubrieken(@OrrGid);
        if ((@SoortKopie in (0,1)) and (@VrObvHist & 1 <> 0)) or ((@SoortKopie = 2) and (@VrObvHist & 2) <> 0) then
          // de storedproc voor het overnemen van de vrije rubrieken vd historie naar de order
          call OrderRegelOvernemenVrijeRubriekenHistorie(@OrrGid, @FrGid);
        end if;
        // controleren of er verplichte vrije rubrieken zijn die geen waarde hebben
        set @VerplichteVrLeeg = 0;
        open cursor_Vrije_Rubrieken_OrderRegel;
        VrOrderRegelLoop:
        loop
          Fetch next cursor_Vrije_Rubrieken_OrderRegel into @OrrVrVeldnaam, @OrrVrType;
          if sqlstate = '02000' then
            leave VrOrderRegelLoop;
          end if;

          execute immediate 'set @VerplichteVrLeeg = (select
                            (if (not exists(select 1
                                            from tabVrORR000000
                                            where VrORR000000RecordId = ' + string(@OrrGid) + ') or ' +
                                    'exists(select 1
                                            from tabVrORR000000
                                            where VrORR000000RecordId = ' + string(@OrrGid) +
                                            ' and (' + string(@OrrVrVeldNaam) + ' is null' +
                                            ' or ((' + string(@OrrVrType) + ' not in (1,2,3)) and IsNull('+string(@OrrVrVeldNaam)+','''') = '''' )))' +
                                            ') then 1 else 0 endif))';

          //call Trace('---------->@VerplichteVrLeeg='+string(@VerplichteVrLeeg));

          if @VerplichteVrLeeg = 1 then
            set @RegelError = @RegelError + 4096;
            leave VrOrderRegelLoop;
          end if;

        end loop VrOrderRegelLoop;
        close cursor_Vrije_Rubrieken_OrderRegel;
        // einde vrije rubrieken


        if (@SoortKopie in (1,2)) and (@frSoortRegel in (1,2)) then    // tbv overzichtje wijzigingen btwcodes/percentages

          select OrrRegelTotaal, OrrRegelTotaal, OrrAantalGereserveerd into @OrrRegelExBtw, @OrrRegelInBtw, @OrrAantalGereserveerd from tabOrderRegel where OrrGid = @OrrGid;
          if @OrkIsInclBtw = 1 then
            set @OrrRegelExBtw = (@OrrRegelExBtw / Round(1+((select BtwPercentage from tabOrderRegel inner join tabBtw on BtwCode = OrrBtwCode where OrrGid = @OrrGid)/100),4));
          else
            set @OrrRegelInBtw = (@OrrRegelInBtw * Round(1+((select BtwPercentage from tabOrderRegel inner join tabBtw on BtwCode = OrrBtwCode where OrrGid = @OrrGid)/100),4));
          end if;
          //call Trace('@OrrRegelExBtw='+string(@OrrRegelExBtw)+', @OrrRegelInBtw='+string(@OrrRegelInBtw));

          select @frRegelTotaal, @frRegelTotaal into @FrRegelExBtw, @FrRegelInBtw;
          if @FkIsInclBtw = 1 then
            set @FrRegelExBtw = (@FrRegelExBtw / Round(1+(@FrBtwPercentage/100),4));
          else
            set @FrRegelInBtw = (@FrRegelInBtw * Round(1+(@FrBtwPercentage/100),4));
          end if;
          //call Trace('@FrRegelExBtw='+string(@FrRegelExBtw)+', @FrRegelInBtw='+string(@FrRegelInBtw));

          if @SoortKopie = 2 then
            set @OrrRegelExBtw = -@OrrRegelExBtw;
            set @FrRegelInBtw  = -@FrRegelInBtw;
          end if;
          set @OrrRegelExBtw = round(@OrrRegelExBtw, @frAantDecBedrag);
          set @FrRegelExBtw  = round(@FrRegelExBtw, @frAantDecBedrag);
          set @OrrRegelInBtw = round(@OrrRegelInBtw, @frAantDecBedrag);
          set @FrRegelInBtw  = round(@FrRegelInBtw, @frAantDecBedrag);
          if @OrrRegelExBtw <> @FrRegelExBtw then
            set @RegelError = @RegelError + 256;
          end if;
          if @OrrRegelInBtw <> @FrRegelInBtw then
            set @RegelError = @RegelError + 512;
          end if;

        end if; // end tbv overzichtje
      else
      	// Artikel niet kunnen vinden, regel niet toevoegen
        set @OrrGid = -1;
      end if;

      if @RegelError <> 0 then
        if not exists(select 1 from tabFactuurKopieOverzicht where fkoVolgNr = @VolgNr and fkoFrefGid = @FrefGid) then
          insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrkGid, fkoFrefGid, fkoOudeWaarde )
                                        Values (   @VolgNr,           0,   @OrkGid,   @FrefGid, '');
        end if;
      end if;

      // Foutoverzicht invullen
      if @RegelError &     1 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 14, null, @FrGid, @frArtCode, @NietGekopieerdTekst );  end if;
      if @RegelError &     2 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 15, @OrrGid, @FrGid, @frOrrArtPartijNummer, (select ArtPartijNummer from tabArtikelPartij where ArtPartijGid = @OrrArtPartijGid) ); end if;
      //if @RegelError  &  4 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 16, null, @FrGid, , 'Niet gekopiëerd' );  end if;
      if @RegelError &     8 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 17, @OrrGid, @FrGid, @frOrrArtPartijNummer, @NietGekopieerdTekst ); end if;
      if @RegelError &    16 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 18, @OrrGid, @FrGid, @frKstpCode, @NietGekopieerdTekst ); end if;
      if @RegelError &    32 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 19, @OrrGid, @FrGid, @frKstdCode, @NietGekopieerdTekst ); end if;
      if @RegelError &    64 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 20, null, @FrGid, @frOrrArtPartijNummer, @NietGekopieerdTekst ); end if;
      if @RegelError &   128 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 26, @OrrGid, @FrGid, if BepaalProjectRecht('pkpi', null) = 1 then @frKostPrijs else null endif, if BepaalProjectRecht('pkpi', null) = 1 then @OrrKostPrijs else null endif); end if;
      if @RegelError &   256 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 27, @OrrGid, @FrGid, @FrRegelExBtw, @OrrRegelExBtw); end if;
      if @RegelError &   512 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 28, @OrrGid, @FrGid, @FrRegelInBtw, @OrrRegelInBtw); end if;
      if @RegelError &  1024 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 29, null, @FrGid, @frVerkoopEenheid, @NietGekopieerdTekst ); end if;
      if @RegelError &  2048 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 30, @OrrGid, @FrGid, @frVerkoopEenheid, ''); end if;
      if @RegelError &  4096 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 31, @OrrGid, @FrGid, @VerplichteVRNietIngevuldTekst, ''); end if;
      if @RegelError &  8192 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 32, @OrrGid, @FrGid, @VoorraadAanwezigTekst, ''); end if;
      if @RegelError & 16384 <> 0 then insert into tabFactuurKopieOverzicht ( fkoVolgNr, fkoFoutCode, fkoOrrGid, fkoFrGid, fkoOudeWaarde, fkoNieuweWaarde) Values ( @VolgNr, 33, @OrrGid, @FrGid, @NietGekopieerdTekst , ''); end if;

      // Nav bug 27071 is besloten niets meer over te nemen van historische spec.regels. Er wordt slechts een enkele aangemaakt obv de orderregel
      // ACW 2023-04-04: Specificatieregels vullen obv instellingen in VG
      if (@OrrGid <> -1) and (@frSoortRegel = 2) and ((select count(*) from tabOrderRegelLocatie where OrlOrrGid = @OrrGid) = 0) then
        begin
          declare @HeeftSpecregelsZonderLocatie smallint;
          call OrderRegelSpecificaties_VulLocatiesAan(
            @OrkGid,
            @OrrGid,
            @MatViewNummerVoorraadAantallen = '',
            @HeeftSpecregelsZonderLocatie=@HeeftSpecregelsZonderLocatie
          );
        end;
      end if;
    end for;  // OrderRegels Eind

    // Order Extra Regel inserten tbv OrderKorting,
    if (@OrkGidIn is null) then
      if @SoortKopie in (1,2) then
        insert into tabOrderExtraRegel (OerOrkGid, OerRegelNr, OerRegelSoort,       OerPerc, OerTekstOpFactuur,   OerOmschrijving,  OerBerekenOverTarief,   OerBerekenOverArtikel, OerBerekenOverEmballage, OerBerekenOverKorting, OerBerekenOverToeslag)
                                 select   @OrkGid,          0,             0, ferPercentage, ferTekstOpFactuur, ferTekstOpFactuur,  ferBerekenOverTarief,   ferBerekenOverArtikel, ferBerekenOverEmballage, ferBerekenOverKorting, ferBerekenOverToeslag
                                 from tabFactuurKop inner join tabFactuurReferentie on frefFkGid = FkGid inner join tabFactuurExtraRegel on ferFrefGid = FrefGid where FkGid = @FkGid and frefGid = @frefGid and ferSoortRegel = 0;
      else
        select (if NawFilWelkeOrderKorting = 1 then DebGrpOrderKorting else NawOrderKorting endif) into @OrderKorting from tabNaw inner join tabNawFile on NawFilNawGid = NawGid and NawFilFonId = 'D' left outer join tabDebiteurGroepen on NawFilDebGrpGid = DebGrpGid where NawFilNawGid = IsNull(@OrkPrijzenNawGid, @OrkNawGid);
        //RVL Bug 32981 : Bij Orderkorting als regelkorting 2, dan geen extra regel aanmaken
  	    if (IsNull(@OrderKorting, 0) <> 0) and (@VGOrderKortingSoort <> 2) then
          insert into tabOrderExtraRegel (OerOrkGid, OerRegelNr, OerRegelSoort,       OerPerc, OerTekstOpFactuur,   OerOmschrijving,  OerBerekenOverTarief,   OerBerekenOverArtikel, OerBerekenOverEmballage, OerBerekenOverKorting, OerBerekenOverToeslag)
          			values   (  @OrkGid,          0,             0, @OrderKorting, _U('Orderkorting'), _U('Orderkorting'),  2,   2, 2, 0, 0  );
	      end if;
      end if;
    end if;
  end for;   // OrderKop Eind

  set @@ErrorTextProcedure = 'MaakOrderVanFactuur';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure MaakUniekSessieNummer(out @SessieNummer integer)
begin
  declare @Result integer;

  set @@ErrorTextProcedure = 'MaakUniekSessieNummer >';
  //call TraceBegin(@@ErrorTextProcedure);

  //Zoek een willekeurige niet-gebruikte
  set @SessieNummer = rand()*1000;
  call LockSetOnId(@@SpId, @@LoginTime, 1, 'CreateSession', @SessieNummer, @Result);
  while @Result = 1 loop
    set @SessieNummer = @SessieNummer + 1;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'CreateSession', @SessieNummer, @Result);
  end loop;
  //De laatste is nu automatisch gelocked!!

  set @@ErrorTextProcedure = 'MaakUniekSessieNummer';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure MaakWerkbonObvProject(
in @BoekgangPwbkGid                        integer,
in @PvcGid                                 integer,
in @PbGid                                  integer,
in @RegelsSamenvoegen                      smallint,
in @VerlagenMetAantalInProjMutaties        smallint,
in @VerlagenMetAantalInbestaandeWerkbonnen smallint,
in @PrijsOpnieuwBepalen                    smallint,
in @MdwRelGid                              integer,
in @LevNawGid                              integer,
in @HeeftRechtUpmu                         smallint,
in @HeeftRechtUpmv                         smallint,
in @HeeftRechtUpmm                         smallint,
in @HeeftRechtUpma                         smallint,
in @SessieNr                               integer,
in @AantalCats                             integer
)
begin
  declare @RelGid integer;

  declare @PvcPbGid              integer;
  declare @PvcArtGid             integer;
  declare @PvcArtPartijGid       integer;
  declare @PvcRelGid             integer;
  declare @PvcIsDirecteInkoop    smallint;
  declare @PvcLeverancierNawGid  integer;
  declare @PvcPdosGid            integer;
  declare @PvcDoorbelastPerc     numeric(15,2);
  declare @PwbrRegelnr           numeric(10,0);

  declare local temporary table tmpPvcGidjes (tmpPvcGid integer)
  on commit preserve rows;

  set @@ErrorTextProcedure = 'MaakWerkbonObvProject > @BoekgangPwbkGid='+String(@BoekgangPwbkGid)+', @PvcGid='+String(@PvcGid)+', @PbGid='+string(@PbGid)+', @RegelsSamenvoegen='+string(@RegelsSamenvoegen)+', @VerlagenMetAantalInProjMutaties='+string(@VerlagenMetAantalInProjMutaties)+', @VerlagenMetAantalInbestaandeWerkbonnen='+string(@VerlagenMetAantalInbestaandeWerkbonnen)+', @LevNawGid='+string(@LevNawGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @HeeftRechtUpmu = IsNull(@HeeftRechtUpmu, 0);
  set @HeeftRechtUpmv = IsNull(@HeeftRechtUpmv, 0);
  set @HeeftRechtUpmm = IsNull(@HeeftRechtUpmm, 0);
  set @HeeftRechtUpma = IsNull(@HeeftRechtUpma, 0);


  if @PvcGid is not null then
    if @RegelsSamenvoegen = 1 then
      select PvcPbGid, PvcArtGid, PvcRelGid, PvcArtPartijGid, PvcIsDirecteInkoop, PvcLeverancierNawGid, PvcPdosGid, PvcDoorbelastPercentage
      into   @PvcPbGid, @PvcArtGid, @PvcRelGid, @PvcArtPartijGid, @PvcIsDirecteInkoop, @PvcLeverancierNawGid, @PvcPdosGid, @PvcDoorbelastPerc
      from   tabProjectVoorcalculatie
      where  PvcGid = @PvcGid;

      if @PvcDoorbelastPerc is null and @VerlagenMetAantalInProjMutaties = 1 then
        insert into tmpPvcGidjes (tmppvcgid)
        select pvcgid
        from tabprojectvoorcalculatie
        where PvcPbGid = @PvcPbGid and PvcArtGid = @PvcArtGid and IsNull(PvcArtPartijGid,0) = IsNull(@PvcArtPartijGid,0) and IsNull(PvcRelGid,0) = IsNull(@PvcRelGid,0) and PvcIsDirecteInkoop = @PvcIsDirecteInkoop and IsNull(PvcLeverancierNawGid,0) = IsNull(@PvcLeverancierNawGid,0) and IsNull(PvcPdosGid,0) = IsNull(@PvcPdosGid,0) and PvcDoorbelastPercentage is null;
      else
        insert into tmpPvcGidjes (tmppvcgid) values(@PvcGid);
      end if;
    else
      insert into tmpPvcGidjes (tmppvcgid) values(@pvcgid);
    end if;
  else
    // Vullen obv. de PbGid (de hele tak, afhankelijk van filter)
    insert into tmpPvcGidjes (tmppvcgid)
    select pvcgid
    from   tabprojectvoorcalculatie
    where
         @PbGid is not null
     and pvcPbGid in (select PbpPbGid from tabProjectBoomPad where PbpParentPbGid = @PbGid union select @PbGid)
     and (
          (select count (*) from tabProjectSelectieCode
                                 inner join tmpProjSelCodes on tmpPscCode = PscCode and tmpPscSessieNr = @SessieNr
           where PscPvcGid = PvcGid)
          >= @AantalCats
         )
  end if;

  //20306: U heeft onvoldoende rechten om een of meer werkbonregels in te voeren
  if exists(select 1
            from tmpPvcGidjes inner join tabProjectVoorcalculatie on (PvcGid = tmpPvcGid)
            where    (PvcMutSoort = 1 and @HeeftRechtUpmm = 0) //machines en geen recht invoeren machinemutaties
                  or (PvcMutSoort = 2 and @HeeftRechtUpma = 0) //artikelen en geen recht invoeren artikelmutaties
                  or (PvcMutSoort = 0 and @HeeftRechtUpmu = 0) //activiteiten en geen recht invoeren activiteiten
                  or (PvcMutSoort = 0 and @HeeftRechtUpmv = 0  //activeiten en geen recht invoeren activiteiten voor anderen
                      and (PvcRelGid <> IsNull((select first PmwRelGid from tabprojectMedewerker where pmwRelGid in (select GebrRelGid from tabgebruiker where GebruikerGid = @@GebruikerGid)), -1)))) then
    call Raise(20306);
  end if;

  select max(PwbrRegelnr) into @PwbrRegelnr from tabProjectWerkbonRegel where PwbrPwbkGid = @BoekgangPwbkGid;
  if @PwbrRegelnr is null then
    set @PwbrRegelnr = 0;
  end if;

  if @RegelsSamenvoegen = 1 then
    //call trace('Samengevoegd!');
    insert into tabProjectWerkbonRegel
     (PwbrPwbkGid          , PwbrPbGid        , PwbrRegelnr                 , PwbrArtGid         , PwbrArtPartijGid   , PwbrIsDirecteInkoop,
      PwbrMagGid           , PwbrLocGid       ,
      PwbrNawGidLeverancier, PwbrKostprijs    , PwbrKostprijsRegelTotaal    , PwbrMutSoort       ,
      PwbrOms              , PwbrVerkoopprijs , PwbrVerkoopprijsRegelTotaal , PwbrAantalGeboekt  ,
      PwbrAantalDeclarabel , PwbrPrijsPer     , PwbrPartFactEenheidFactor   , PwbrRelGid         , PwbrSelectieCodes,
      PwbrDoorbelastPercentage, PwbrUrenIngevoerdAls)
    select
      // Regel 1
      @BoekgangPwbkGid,
      PvcPbGid,
      number() + @PwbrRegelnr,
      PvcArtGid,
      IsNull(Max(PvcArtPartijGid), (select ArtPartijGid from tabArtikel inner join tabArtikelPartij on (ArtPartijArtGid = ArtGid) where ArtGid = PvcArtGid and ArtIsPartijRegistreren = 0 and ArtSerieNrRegistreren = 1)),
      PvcIsDirecteInkoop,
      // Regel 2
      if ArtSoort = 2 /*Artikel*/ and ArtHeeftVoorraad <> 0 and PvcIsDirecteInkoop = 0 then
        isnull(ArtDefaultMagGid,                                          // Default magazijn van het artikel
               (select ToeMagMagGid from tabToegestaneMagazijnen where ToeMagToepassing = 60 /*Projectmutaties*/ and ToeMagGebrGid = @@GebruikerGid), // Default magazijn voor deze gebruiker + toepassing
               (select first MagGid from tabMagazijn where MagCode = 1)) // Magazijn 001
      endif PwbrMagGid,
      if PwbrMagGid is not null then
        isnull((select ArtMagDefaultLocGid from tabartikelmagazijn where ArtMagMagGid = PwbrMagGid and ArtMagArtGid = PvcArtGid),
               (select LocGid from tabLocatie where LocMagGid = PwbrMagGid and LocNaam = '(Standaard)'))
      endif PwbrLocGid,
      // Regel 3
      IsNull(PvcLeverancierNawGid,@LevNawGid) as Lev,
      // bugdoc:27681 Kostprijs niet opnieuw bepalen als overige kosten/doorbelasting ingevuld
      if @PrijsOpnieuwBepalen=0 or PvcDoorbelastPercentage is not null then (sum(PvcKostprijsRegelTotaal) / sum(PvcBudAantal)) * PrijsPer endif as Kostprijs,
      ((Kostprijs * AantalTeBoeken) / PrijsPer) as KostprijsRegelTotaal,
      PvcMutSoort,
      // Regel 4
      Max(PvcOmschr),
      if @PrijsOpnieuwBepalen=0 then if Sum(PvcOffAantal) = 0 then sum(PvcVerkoopprijsRegelTotaal) else (sum(PvcVerkoopprijsRegelTotaal) / Sum(PvcOffAantal)) * PrijsPer endif endif Verkoopprijs,
      ((Verkoopprijs * AantalTeBoeken) / PrijsPer) / Max(PvcPartFactEenheidFactor)  as VerkoopprijsRegeltotaal,
      sum(PvcBudAantal) -
        if @VerlagenMetAantalInProjMutaties = 1 then
          // Verminderen met aantal in projectmutaties
          IsNull((select sum(PbrAantalGeboekt)
                  from   tabProjectBoekingsregel
                  where  PbrPbGid                       = PvcPbGid
                     and PbrArtgid                      = PvcArtGid
                     and IsNull(PbrArtPartijGid,0)      = IsNull(PvcArtPartijGid,0)
                     and IsNull(PbrRelGid,0)            = IsNull(Medewerker,0)
                     and PbrIsDirecteInkoop             = PvcIsDirecteInkoop
                     and IsNull(PbrLeverancierNawGid,0) = IsNull(Lev,0)
                 ), 0)
        else
          0
        endif -
        if @VerlagenMetAantalInbestaandeWerkbonnen = 1 then
          isnull((select sum(PwbrAantalGeboekt)
                  from   tabProjectWerkbonRegel
                  where  PwbrPbGid                       = PvcPbGid
                     and PwbrArtgid                      = PvcArtGid
                     and IsNull(PwbrArtPartijGid,0)      = IsNull(PvcArtPartijGid,0)
                     and IsNull(PwbrRelGid,0)            = IsNull(Medewerker,0)
                     and PwbrIsDirecteInkoop             = PvcIsDirecteInkoop
                     and IsNull(PwbrNawGidLeverancier,0) = IsNull(Lev,0)
                 ), 0)
        else
          0
        endif
        // Verminderen met aantallen op niet-afgehandelde werkbonnen
        as AantalTeBoeken,
      // Regel 5
      AantalTeBoeken / max(PvcPartFactEenheidFactor) as AantalDeclarabel,
      // Let op: in geval van Doorbelasting altijd 1, dus hoeft niet opnieuw bepaald te worden; anders wordt ook kostprijs niet goed berekend.
      if @PrijsOpnieuwBepalen=0 or PvcDoorbelastPercentage is not null then Max (PvcPrijsPer) endif as PrijsPer,
      if @PrijsOpnieuwBepalen=0 then Max(PvcPartFactEenheidFactor) endif,
      if PvcMutSoort=0 then IsNull(PvcRelGid, @MdwRelGid) endif as Medewerker,
      max(PvcSelectieCodes),
      // Regel 6
      if @PrijsOpnieuwBepalen=0 then PvcDoorbelastPercentage endif DoorbelastPercentage,
      0
    from
      tmpPvcGidjes
      inner join      tabProjectVoorcalculatie on (pvcGid = tmppvcgid)
      left outer join tabArtikel on (ArtGid = pvcArtGid)
    group by PvcProjGid, PvcPbGid, PvcArtGid, PvcArtPartijGid, ArtDefaultMagGid, ArtSoort, ArtHeeftVoorraad, Medewerker, PvcIsDirecteInkoop, Lev, PvcMutSoort,
             PvcDoorbelastPercentage, if PvcDoorbelastPercentage is not null then PvcGid endif //TG 15-10-2007: regels met een doorbelastingspercentage mogen nooit samengevoegd worden!
    //<>0 erbij ivm bug 29263
    having (@RegelsSamenvoegen=0 and AantalTeBoeken <> 0) or (@RegelsSamenvoegen=1 and AantalTeBoeken > 0);
  else
    //call trace('Losse regels!');
    insert into tabProjectWerkbonRegel
     (PwbrPwbkGid          , PwbrPbGid        , PwbrRegelnr                 , PwbrArtGid        , PwbrArtPartijGid  , PwbrIsDirecteInkoop,
      PwbrMagGid           , PwbrLocGid       ,
      PwbrNawGidLeverancier, PwbrKostprijs    , PwbrKostprijsRegelTotaal    , PwbrMutSoort      , /*PbrPdosGid        ,*/
      PwbrOms              , PwbrVerkoopprijs , PwbrVerkoopprijsRegelTotaal , PwbrAantalGeboekt ,
      PwbrAantalDeclarabel , PwbrPrijsPer     , PwbrPartFactEenheidFactor   , PwbrRelGid        , PwbrSelectieCodes,
      PwbrDoorbelastPercentage, PwbrUrenIngevoerdAls)
    select
      // Regel 1
      @BoekgangPwbkGid,
      PvcPbGid,
      number() + @PwbrRegelnr,
      PvcArtGid,
      IsNull(PvcArtPartijGid, (select ArtPartijGid from tabartikel inner join tabArtikelPartij on (ArtPartijArtGid = ArtGid) where ArtGid = PvcArtGid and ArtIsPartijRegistreren = 0 and ArtSerieNrRegistreren = 1)),
      PvcIsDirecteInkoop,
      // Regel 2
      if ArtSoort = 2 /*Artikel*/ and ArtHeeftVoorraad <> 0 and PvcIsDirecteInkoop = 0 then
        isnull(ArtDefaultMagGid,                                          // Default magazijn van het artikel
               (select ToeMagMagGid from tabToegestaneMagazijnen where ToeMagToepassing = 60 /*Projectmutaties*/ and ToeMagGebrGid = @@GebruikerGid), // Default magazijn voor deze gebruiker + toepassing
               (select first MagGid from tabMagazijn where MagCode = 1))  // Magazijn 001
      endif PwbrMagGid,
      if PwbrMagGid is not null then
        isnull((select ArtMagDefaultLocGid from tabartikelmagazijn where ArtMagMagGid = PwbrMagGid and ArtMagArtGid = PvcArtGid), (select LocGid from tabLocatie where LocMagGid = PwbrMagGid and LocNaam = '(Standaard)'))
      endif PwbrLocGid,
      // Regel 3
      IsNull(PvcLeverancierNawGid,@LevNawGid) as Lev,
      // bugdoc:27681 Kostprijs niet opnieuw bepalen als overige kosten/doorbelasting ingevuld
      if @PrijsOpnieuwBepalen=0 or PvcDoorbelastPercentage is not null then (PvcKostprijsRegelTotaal / PvcBudAantal) * PrijsPer endif as Kostprijs,
      ((Kostprijs * AantalTeBoeken) / PrijsPer) as KostprijsRegelTotaal,
      PvcMutSoort,
      // Regel 4
      PvcOmschr,
      if @PrijsOpnieuwBepalen=0 then if PvcOffAantal = 0 then PvcVerkoopprijsRegelTotaal else (PvcVerkoopprijsRegelTotaal / PvcOffAantal) * PrijsPer endif endif Verkoopprijs,
      ((Verkoopprijs * AantalTeBoeken) / PrijsPer) / PvcPartFactEenheidFactor as VerkoopprijsRegeltotaal,
      PvcBudAantal as AantalTeBoeken, // Let op: NIET de aantallen in projmutaties of bestaande werkbonnen eraf halen! (Dus losse regels ALTIJD opnemen)
      // Regel 5
      AantalTeBoeken / PvcPartFactEenheidFactor as AantalDeclarabel,
      // Let op: in geval van Doorbelasting altijd 1, dus hoeft niet opnieuw bepaald te worden; anders wordt ook kostprijs niet goed berekend.
      if @PrijsOpnieuwBepalen=0 or PvcDoorbelastPercentage is not null then PvcPrijsPer endif as PrijsPer,
      if @PrijsOpnieuwBepalen=0 then PvcPartFactEenheidFactor endif,
      if PvcMutSoort=0 then IsNull(PvcRelGid, @MdwRelGid) endif as Medewerker,
      PvcSelectieCodes,
      // Regel 6
      if @PrijsOpnieuwBepalen=0 then PvcDoorbelastPercentage endif DoorbelastPercentage,
      0
    from
      tmpPvcGidjes
      inner join      tabProjectVoorcalculatie on (pvcGid = tmppvcgid)
      left outer join tabArtikel on (ArtGid = pvcArtGid)
    where
       //<>0 erbij ivm bug 29263
      (@RegelsSamenvoegen=0 and AantalTeBoeken <> 0) or (@RegelsSamenvoegen=1 and AantalTeBoeken > 0);
  end if;

  set @@ErrorTextProcedure = 'MaakWerkbonObvProject > einde';
  //call TraceEind(@@ErrorTextProcedure);

end;


//-------  Vul de maandnamen met defaults
create or replace procedure MaandenDefaultVullen(in @TaalGid integer, in @Default smallint)
begin
  declare @Teller smallint;
  declare @MaandLang nchar(15);
  declare @MaandKort nchar(5);

  //call TraceBegin('MaandenDefaultVullen(@TaalGid='+string(@TaalGid)+', @Default='+string(@Default)+')');

  set @Teller=1;
  while @Teller<=12 loop
    if @Default = 0 then      //Nederlands
      //                          123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890
      select Trim(substr('januari   februari  maart     april     mei       juni      juli      augustus  september oktober   november  december  ',(@Teller-1)*10+1,10)) into @MaandLang;
      select Trim(substr('jan       feb       maa       apr       mei       jun       jul       aug       sep       okt       nov       dec       ',(@Teller-1)*10+1,10)) into @MaandKort;
    else
      if @Default=1 then   //Engels
        //                          123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890
        select Trim(substr('january   february  march     april     may       june      july      august    september october   november  december  ',(@Teller-1)*10+1,10)) into @MaandLang;
        select Trim(substr('jan       feb       mar       apr       may       jun       jul       aug       sep       oct       nov       dec       ',(@Teller-1)*10+1,10)) into @MaandKort;
      else
        if @Default=2 then  //Duits
          //                          123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890
          select Trim(substr('januar    februar   m\xe4rz      april     mai       juni      juli      august    september oktober   november  dezember  ',(@Teller-1)*10+1,10)) into @MaandLang;
          select Trim(substr('jan       feb       m\xe4r       apr       mai       jun       jul       aug       sep       okt       nov       dez       ',(@Teller-1)*10+1,10)) into @MaandKort;
        else
          if @Default=3 then  //Frans
            //                          123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890123456789012345678901234567890
            select Trim(substr('janvier   f\xe9vrier   mars      avril     mai       juin      juillet   ao\xfbt      septembre octobre   novembre  d\xe9cembre  ',(@Teller-1)*10+1,10)) into @MaandLang;
            select Trim(substr('jan       f\xe9v       mar       avr       mai       jun       jul       ao\xfb       sep       oct       nov       d\xe9c       ',(@Teller-1)*10+1,10)) into @MaandKort;
          end if;
        end if;
      end if;
    end if;
    update tabMaandNaam set MndLang=@MaandLang, MndKort=@MaandKort where MndTaalGid=@TaalGid and MndId=@Teller;
    set @Teller = @Teller + 1;
  end loop;

  //call TraceEind('MaandenDefaultVullen (@Maandlang='+@Maandlang+', @MaandKort='+@MaandKort+')');

end;


