create or replace procedure Maatwerk_ProManagement_NormaleBalans(in @BjGid integer, in @VanPernr smallint, in @TotPernr smallint,  in @SoortBoeking smallint)
result
(
  RksInvoer nchar(28),
  RksNummer nchar(10),
  RksNaam nchar(40),
  BeginBalansDebet numeric(15,2),
  BeginBalansCredit numeric(15,2),
  BeginBalansSaldo numeric(15,2),
  VorigePeriodesDebet numeric(15,2),
  VorigePeriodesCredit numeric(15,2),
  VorigePeriodesSaldo numeric(15,2),
  LaatstePeriodeDebet numeric(15,2),
  LaatstePeriodeCredit numeric(15,2),
  LaatstePeriodeSaldo numeric(15,2),
  ProefDebet numeric(15,2),
  ProefCredit numeric(15,2),
  ProefSaldo numeric(15,2),
  SaldiDebet numeric(15,2),
  SaldiCredit numeric(15,2),
  SaldiSaldo numeric(15,2),
  EindDebet numeric(15,2),
  EindCredit numeric(15,2),
  EindSaldo numeric(15,2)
)

begin

  select RksInvoer,
         RksNummer,
         RksNaam,
         BeginBalansDebet,
         BeginBalansCredit,
         BeginBalansSaldo,
         VorigePeriodesDebet,
         VorigePeriodesCredit,
         VorigePeriodesSaldo,
         LaatstePeriodeDebet,
         LaatstePeriodeCredit,
         LaatstePeriodeSaldo,
         ProefDebet,
         ProefCredit,
         ProefSaldo,
         SaldiDebet,
         SaldiCredit,
         SaldiSaldo,
         EindDebet,
         EindCredit,
         EindSaldo

  from   KingSystem.rapNormaleBalans( @BjGid, //in @BjGid integer,
                                      @VanPernr, //in @VanPernr smallint,
                                      @TotPernr, //in @TotPernr smallint,
                                      0, //in @SelecteerOp smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
                                      '0', //in @VanRks nchar(40), //van nummer/zoekcode/naam
                                      '999999999999', //in @TotRks nchar(40), //t/m nummer/zoekcode/naam
                                      @SoortBoeking, //in @SoortBoeking smallint, //0=definitief, 1=voorlopig, 2=beide
                                      2, //in @OokNulSaldi smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
                                      2, //in @ComprimeerBalans smallint, //0=nee, 1=ja, 2=conform balans
                                      1, //in @DebUitsplitsen smallint, //0=nee, 1=ja (werkt niet bij conform balans)
                                      1, //in @CredUitsplitsen smallint, //0=nee, 1=ja (werkt niet bij conform balans)
                                      1, //in @KstpUitsplitsen smallint, //0=nee, 1=ja (werkt niet bij conform balans)
                                      1, //in @KstdUitsplitsen smallint, //0=nee, 1=ja (werkt niet bij conform balans)
                                      2, //in @AantalCijfers smallint, //Aantal cijfers waarop getotaliseerd moet worden 1-5 (werkt niet bij conform balans)
                                      (select ValNummer from tabValuta where IsEuro = 1), //in @BalansInValuta integer, //Valutanummer waarin balans moet worden afgedrukt
                                      (select ValNummer from tabValuta where IsEuro = 1)  //in @TotalenInValuta integer )  //Valutanummer voor subtotalen
                                    )
  where  RegelSoort in (1,13);

end;



