create or replace procedure MagazijnOntvangstBoeken (in @MokGid integer, in @MohkGid integer, in @Boekdatum date, in @Stuknummer numeric(10,0), inout @BoekgangGid integer, out @JpGid integer)
begin
  // *******************************************************************************************************
  // *** !!! LET OP!! Bij wijzigen controleren of ook DirecteLeveringBoeken.sp moet worden aangepast !!! ***
  // *******************************************************************************************************

  declare @Omschrijving         nchar(40);
  declare @MokBoekDatum         date;
  declare @temp                 nchar(2);
  declare @BjGid                integer;
  declare @PerNr                integer;
  declare @Naam                 nchar(40);
  declare @DagboekGid           integer;
  declare @JrGid                integer;
  declare @MagOntvTekst         long nvarchar;
  declare @MagOntvMeerdereTekst long nvarchar;


  declare local temporary table tmpMagOntRegel (
    tmpMagOntGid integer,
    tmpSignFactor smallint,
    tmpNettoRegelTotaal numeric(15,3),
    tmpKostprijsVanOntvangstTotaal numeric(15,3),
    tmpNettoRegelTotaalInJuisteTeken numeric(15,3),
    tmpKostprijsVanOntvangstTotaalInJuisteTeken numeric(15,3)
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'MagazijnOntvangstBoeken > ';
  //call TraceBegin(@@ErrorTextProcedure + '@MokGid = ' + string(@MokGid));

  select
    AdrNaam1 into @Naam
  from
    tabNaw
    inner join tabAdres on (NawGid = AdrNawGid and NawGidVestiging = AdrGid)
    inner join tabMagazijnOntvangstenKop on (MokNawGid = NawGid and MokGid = @MokGid);

  //Als geen boekgangGid meegegeven, dan boekingsgang creeren en in gebruik nemen
  //uit gebruik nemen in programma afhandelen, zodat een groep van ontvangsten in 1 boekingsgang kan komen
  set @MagOntvTekst = _A('Magazijnontvangst %1!');
  set @MagOntvTekst = _VervangMetRondeHaakjes(@MagOntvTekst, 40, @Naam);

  if @BoekgangGid is null then
    insert into tabBoekingsGang(BoekGangBjGid, BoekgangBronId, BronOms,       BoekGangInGebruik, IsBoekGangDefinitief)
                       values(@@BjGid,         11,             @MagOntvTekst, 1,                 0);
    set @BoekGangGid = @@Identity;
  else
    //Bug#  23904: Als de boekingsgang bestaat uit meerdere leveranciers, dan niet de naam plaatsen van de leverancier, maar '(meerdere leveranciers)'
    set @MagOntvMeerdereTekst = _A('Magazijnontvangst meerdere leveranciers');
    update TabBoekingsGang
    set BronOms = @MagOntvMeerdereTekst
    where boekganggid = @BoekGangGid
    and BronOms not in (@MagOntvTekst, @MagOntvMeerdereTekst);
  end if;

  //tijdelijke tabel vullen met (zodat we deze berekening niet onnodig vaak hoeven uit hoeven te rekenen):
  //tmpNettoRegelTotaal            : aantal ontvangen tegen inkoopprijs
  //tmpKostprijsVanOntvangstTotaal : aantal ontvangen tegen kostprijs
  insert into tmpMagOntRegel (tmpMagOntGid, tmpSignFactor, tmpNettoRegelTotaalInJuisteTeken, tmpKostprijsVanOntvangstTotaalInJuisteTeken, tmpNettoRegelTotaal, tmpKostprijsVanOntvangstTotaal)
  select
    MagOntGid,
    Sign(MagOntAantal) tmpSignFactor,
    //ACW 06-10-2009 - bug 30890 - Berekening opnieuw
    //RVL 25-10-2010 - bug 32287 - Berekening nogmaals opnieuw
    if MagOntInkoopprijsPer = 1 /*X voorr.eenh.*/ then
      if MagOntPrijsPer = 0 then
        0
      else
        round(MagOntInkoopprijs * if MagOntKortingSoort = 1 /*Kortingsperc.*/  then (100 - MagOntKortingPercentage) / 100 else 1 endif -
                                  if MagOntKortingSoort = 0 /*Kortingsbedrag*/ then MagOntKortingBedrag / MagOntPrijsPer  else 0 endif
           , ArtAantDecPrijzen) * (MagOntAantal / MagOntPrijsPer)
      endif
    else /*inkoopeenheid*/
      round(round(MagOntInkoopprijs * if MagOntKortingSoort = 1 /*Kortingsperc.*/  then (100 - MagOntKortingPercentage) / 100 else 1 endif -
                                      if MagOntKortingSoort = 0 /*Kortingsbedrag*/ then MagOntKortingBedrag                   else 0 endif
                  , ArtAantDecPrijzen)
            * (ArtPrijsPer / MagOntVoorraadEenhedenInInkoopEenheid) * (MagOntAantal / MagOntPrijsPer)
           , ArtAantDecPrijzen)
    endif  NettoRegelTotaalInJuisteTeken,
    round(if ArtPrijsPer = 0 then 0 else IsNull(ArtPartijKostprijsEx, ArtKostprijsEx) * (MagOntAantal / ArtPrijsPer) endif, ArtAantDecPrijzen) KostprijsVanOntvangstTotaalInJuisteTeken,
    NettoRegelTotaalInJuisteTeken * tmpSignFactor NettoRegelTotaal,
    KostprijsVanOntvangstTotaalInJuisteTeken * tmpSignFactor  KostprijsVanOntvangstTotaal
  from
    tabMagazijnOntvangsten
    inner join tabArtikel on (ArtGid = MagOntArtGid)
    left outer join tabArtikelPartij on (ArtPartijGid = MagOntArtPartijGid and ArtIsPartijAparteKostPrijs <> 0)
  where
        MagOntMokGid     = @MokGid
    and MagOntRegelSoort = 2;

  select MagVastInkDgbGid into @DagboekGid from tabMagazijnOntvangstenVasteGegevens;

    //call Trace('Journaalpost toevoegen');
  insert into tabJournaalpost(JpBoekGangGid, JpBjGID, JpIsInGebruik, JpDgbGID,
                              BoekstukNummer, OmsJournaalPost, BoekDatum)
  select @BoekGangGid, @@BjGid, 1, @DagboekGid,
         @Stuknummer, MokOmschrijving, @BoekDatum
  from   tabMagazijnOntvangstenVasteGegevens,tabMagazijnOntvangstenKop
  where  MokGid = @MokGid;
  set    @JpGid = @@Identity;//komt in de voorraadmutaties

  update tabMagazijnOntvangstHistKop set MohkBoekdatum = @BoekDatum, MohkBoekStuknummer = @Stuknummer, MohkDagboek = (select DgbCode from tabDagboek where DgbGID = @DagboekGid) where MohkGid = @MohkGid;

  select
         MokOmschrijving, @BoekDatum
    into @Omschrijving  , @MokBoekDatum
  from
    tabMagazijnOntvangstenKop
  where
    MokGid = @MokGid;

  //call Trace('genereren van journaalregels');

  //boeken tegen VVP of werkelijke inkoopprijs(<>0 is werkelijke inkoopprijs)
  if exists(select 1 from tabMagazijnOntvangstenVasteGegevens where MagVastOntvBoekenTegen <> 0) then
    //gemeenschappelijk deel voor voorbeeld 1 + 2(werkelijke inkoopprijs, dus prijsverschillen ook boeken)

    //maak ontbrekende voorraadrekeningen en prijsverschillenrekening per opbrengstgroep aan
    select  min(distinct OpbrengtGroepsoortenPerStuk(OpbrGrpGid, ParSoort)) into @temp
    from
      (tabParagraaf,
       tabmagazijnontvangsten
       inner join tabartikel on (ArtGid = MagOntArtGid)
       inner join TabOpbrengstGroep on (OpbrGrpGid = ArtOpbrGrpGid))
       left outer join tabOpbrengstGroepSoort on (GrpSoortParSoort = Parsoort and GrpSoortRksGID is null)
    where
      (
        ParSoort in (50, 90) and ArtSoort = 2
      )
      and MagOntMokGid = @MokGid;

    call BepaalBoekjaarEnPeriode(@MokBoekDatum, @BjGid, @PerNr);
    //call Trace('boeken van de voorraadgroepen en prijsverschillengroepen(per artikelgroep)');

    //Er worden 2 boekingen gedaan: 1 voorraadboeking en 1 prijsverschillen-boeking (middels group by op paragraafsoort)
    insert into tabJournaalRegel(JrJpGid, JrRksGid, OmsJournaalRegel, JrReferentie, SoortBoeking,
                                IsCreditBoeking,
                                JrValutaBedrag,
                                JrBasisBedrag, JrValNummer)
    select
      @JpGid, GrpSoortRksGID, @Omschrijving, '', 0,
      case GrpSoortParSoort
      when 50 then
      //voorraadboeking, dus debet
        0
      when 90 then
      //prijsverschilboeking; debet indien regeltotaal > aantal ontvangen * kostprijs, anders credit
        if
        (if MokValNummer = @@BasisValutaNummer then sum(tmpNettoRegelTotaal) else ValutaOmrekenen(MokValNummer, sum(tmpNettoRegelTotaal), @@BasisValutaNummer, @BjGid, @Pernr, 2) endif)
         > sum(tmpKostprijsVanOntvangstTotaal) then 0 else 1 endif
      end Boekzijde,
      case GrpSoortParSoort
      when 50 then
      //voorraadboeking artikel
        sum(tmpKostprijsVanOntvangstTotaalInJuisteTeken)
      when 90 then
      //prijsverschilboeking
        ((if MokValNummer = @@BasisValutaNummer then sum(tmpNettoRegelTotaalInJuisteTeken) else ValutaOmrekenen(MokValNummer, sum(tmpNettoRegelTotaalInJuisteTeken), @@BasisValutaNummer, @BjGid, @Pernr, 2) endif)
         - sum(tmpKostprijsVanOntvangstTotaalInJuisteTeken))
         * if Boekzijde = 0 then 1 else -1 endif
      end ValutaBedrag,
      ValutaBedrag, @@BasisValutaNummer
    from
      tabMagazijnOntvangstenKop
      inner join tabmagazijnontvangsten on (MagOntMokGid = MokGid)
      inner join tmpMagOntRegel on (tmpMagOntGid = MagOntGid)
      inner join tabArtikel on (ArtGid = MagOntArtGid)
      inner join tabOpbrengstGroep on (OpbrGrpGid = ArtOpbrGrpGid)
      inner join tabOpbrengstGroepSoort on (GrpSoortGrpGid = OpbrGrpGId)
    where
      (GrpSoortParSoort in (50, 90) and ArtSoort = 2)
      and MagOntMokGid = @MokGid
    group by
      OpbrGrpNummer, GrpSoortRksGID, GrpSoortParSoort, MokValNummer
    having
      ValutaBedrag <> 0
    order by
      OpbrGrpNummer, GrpSoortParSoort;

    //laatste deel voorbeeld 2(boeken op tussenrekening inkopen tegen werkelijke inkoopprijs)

    //call Trace('boeken op tussenrekening inkopen(tegen werkelijke inkoopprijs)');
	//In de valuta van de magazijnontvangst geboekt
    insert into tabJournaalRegel(
      JrJpGid,
      JrRksGid,
      OmsJournaalRegel,
      JrReferentie,
      SoortBoeking,
      IsCreditBoeking,
      JrValutaBedrag,
      JrBasisBedrag,
      JrValNummer)
    select
      /*JrJpGid,         */ @JpGid,
      /*JrRksGid,        */ (select MagVastInkRksGid from tabMagazijnOntvangstenVasteGegevens) RksGidTussenRek,
      /*OmsJournaalRegel,*/ @Omschrijving,
      /*JrReferentie,    */ if (select ReferentieVerplicht from tabRekeningSchema where RksGid = RksGidTussenRek) = 1 then MokFactuurNummer else '' endif,
      /*SoortBoeking,    */ 0,
      /*IsCreditBoeking, */ 1,
      /*JrValutaBedrag,  */ round(sum(tmpNettoRegelTotaalInJuisteTeken),2) ValutaBedrag,
      /*JrBasisBedrag,   */ if not MokValNummer = @@BasisValutaNummer then ValutaOmrekenen(MokValNummer, ValutaBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2)
							else ValutaBedrag endif,
      /*JrValNummer      */ MokValNummer
    from
      tabMagazijnontvangstenKop
      inner join tabmagazijnontvangsten on (MagOntMokGid = MokGid)
      inner join tmpMagOntRegel on (tmpMagOntGid = MagOntGid)
    where
          MagOntMokGid = @MokGid
      and MagOntRegelSoort = 2
    group by
      MokValNummer, MokFactuurNummer
    having
      ValutaBedrag <> 0;

    // Nettoregeltotaal dat op de tussenrekening wordt geboekt hier alsnog in de historische magazijnontvangst onthouden (Die wordt overgenomen naar de historische magazijnontvangst),
    // zodat de bijbehorende inkoopfactuur later netjes die tussenrekening kan tegenboeken

    update tabMagazijnOntvangsten
    set    MagOntTussenrekeningTotaalGeboekt = tmpNettoRegelTotaalInJuisteTeken
    from   tmpMagOntRegel
    inner join tabMagazijnontvangstenKop on MokGid = @MokGid
    where
      tmpMagOntGid = MagOntGid;

  else
    //voorbeeld 3(magazijn ontvangst boeken tegen vaste verrekenprijs(VVP))

    //maak ontbrekende voorraad-/kostprijsrekeningen per opbrengstgroep aan
    select
      min(distinct OpbrengtGroepsoortenPerStuk(OpbrGrpGid, ParSoort)) into @temp
    from
      (tabParagraaf,
      tabMagazijnOntvangsten
      inner join tabartikel on (ArtGid = MagOntArtGid)
      inner join TabOpbrengstGroep on (ArtOpbrGrpGid = OpbrGrpGid))
      left outer join tabOpbrengstGroepSoort on (GrpSoortParSoort = 50 and GrpSoortRksGID is null)
    where
      (ParSoort = 50 and ArtSoort = 2)
      and MagOntMokGid = @MokGid;

    //boeken van de voorraadgroepen (per artikelgroep)
    insert into tabJournaalRegel(JrJpGid, JrRksGid, OmsJournaalRegel, JrReferentie,
                                 SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag,
                                 JrValNummer)
    select
      @JpGid, GrpSoortRksGID, @Omschrijving, '',
      0, 0, round(sum(tmpKostprijsVanOntvangstTotaalInJuisteTeken),2) ValutaBedrag, ValutaBedrag,
      @@basisValutaNummer
    from
      tabmagazijnontvangsten
      inner join tmpMagOntRegel on (tmpMagOntGid = MagOntGid)
      inner join tabartikel on (ArtGid = MagOntArtGid)
      inner join TabOpbrengstGroep on (OpbrGrpGid = ArtOpbrGrpGid)
      inner join tabOpbrengstGroepSoort on (GrpSoortGrpGid = OpbrGrpGid)
    where
      (GrpSoortParSoort = 50 and ArtSoort = 2)
      and MagOntMokGid = @MokGid
    group by
      OpbrGrpNummer, GrpSoortRksGID
    having
      ValutaBedrag <> 0
    order by
      OpbrGrpNummer;

    //boeken op tussenrekening inkopen (tegen vaste verreken prijs(VVP))
    insert into tabJournaalRegel(JrJpGid, JrRksGid, OmsJournaalRegel,
                                 JrReferentie,
                                 SoortBoeking, IsCreditBoeking, JrBasisBedrag, JrValutaBedrag, JrValNummer)
    select
      @JpGid, (select MagVastInkRksGid from tabMagazijnOntvangstenVasteGegevens) RksGidTussenRek, @Omschrijving,
      if (select ReferentieVerplicht from tabRekeningSchema where RksGid = RksGidTussenRek) = 1 then MokFactuurNummer else '' endif,
      0, 1, round(sum(tmpKostprijsVanOntvangstTotaalInJuisteTeken),2) ValutaBedrag, ValutaBedrag, @@basisValutaNummer
    from
      tabmagazijnontvangsten
      inner join tmpMagOntRegel on (tmpMagOntGid = MagOntGid)
      inner join tabMagazijnOntvangstenKop on (MokGid = MagOntMokGid)
    where
          MagOntMokGid = @MokGid
      and MagOntRegelSoort = 2
    group by
      MokFactuurNummer
    having
      ValutaBedrag <> 0;

    // VVP dat op de tussenrekening wordt geboekt hier alsnog in de historische magazijnontvangst onthouden (Die wordt overgenomen naar de historische magazijnontvangst),
    // zodat de bijbehorende inkoopfactuur later netjes die tussenrekening kan tegenboeken
    update tabMagazijnOntvangsten
    set    MagOntTussenrekeningTotaalGeboekt = tmpKostprijsVanOntvangstTotaalInJuisteTeken
    from   tmpMagOntRegel
    inner join tabMagazijnontvangstenKop on MokGid = @MokGid
    where  tmpMagOntGid = MagOntGid;
  end if;

  // Bijwerken MohrTussenrekeningTotaalGeboektInBasisValutahistorische op basis van magazijnontvangstregel
  update tabMagazijnontvangstHistRegel
  set    MohrTussenrekeningTotaalGeboekt = MagOntTussenrekeningTotaalGeboekt
  from   tabmagazijnontvangsten
  where
    MagOntMokGid = @MokGid and
    MohrMohkGid  = @MohkGid and
    MohrRegelnr  = MagOntRegelnr; // Op basis van regelnummer i.c.m. MohkGid is dit wel over te nemen

  update tabJournaalPost set JpIsInGebruik=0 where JpGid = @JpGid;

  set @@ErrorTextProcedure = 'MagazijnOntvangstBoeken';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace function MagazijnOntvangstHistorieVulAdres(
    @MohkGid                     integer,
    @MohaContactEmail            nchar(80),
    @MohaContactNaamAanhef       nchar(60),
    @MohaContactNaamAdres        nchar(60),
    @MohaContactNaamBrief        nchar(60),
    @MohaContactTelefax          nchar(25),
    @MohaContactTelefoon         nchar(25),
    @MohaContactTelefoon2        nchar(25),
    @MohaContactVolledigeNaam    nchar(40),
    @MohaEanCode                 nchar(14),
    @MohaEmail                   nchar(80),
    @MohaHuisnummer              nchar(10),
    @MohaHuisnummerPositie       smallint,
    @MohaLndEigenCode            nchar(3) ,
    @MohaLndInNAWBlok            smallint,
    @MohaLndOms                  nchar(40),
    @MohaNaam1                   nchar(40),
    @MohaNaam2                   nchar(40),
    @MohaNawFilNummer            nchar(10) ,
    @MohaNawFilZoekcode          nchar(10),
    @MohaPlaats                  nchar(40),
    @MohaPostcode                nchar(40),
    @MohaPostcodePositie         smallint,
    @MohaStraat                  nchar(40),
    @MohaTelefax                 nchar(25),
    @MohaTelefoon                nchar(25),
    @MohaTelefoon2               nchar(25))
returns integer
begin
  declare @MohaGid integer;
  declare @Doorgaan smallint = 0;

  set @@ErrorTextProcedure = 'MagazijnOntvangstHistorieVulAdres > ';
  //call TraceBegin(@@ErrorTextProcedure + '@MohaNawFilNummer = ' + @MohaNawFilNummer);

  /*
  //call Trace(
  //'@MohkGid='                   +string(@MohkGid)+
  //', @MohaContactEmail='        +string(@MohaContactEmail)+
  //', @MohaContactNaamAanhef='   +string(@MohaContactNaamAanhef)+
  //', @MohaContactNaamAdres='    +string(@MohaContactNaamAdres)+
  //', @MohaContactNaamBrief='    +string(@MohaContactNaamBrief)+
  //', @MohaContactTelefax='      +string(@MohaContactTelefax)+
  //', @MohaContactTelefoon='     +string(@MohaContactTelefoon));
  //call Trace(
  //', @MohaContactTelefoon2='    +string(@MohaContactTelefoon2)+
  //', @MohaContactVolledigeNaam='+string(@MohaContactVolledigeNaam)+
  //', @MohaEanCode='             +string(@MohaEanCode)+
  //', @MohaEmail='               +string(@MohaEmail)+
  //', @MohaHuisnummer='          +string(@MohaHuisnummer)+
  //', @MohaHuisnummerPositie='   +string(@MohaHuisnummerPositie));
  //call Trace(
  //', @MohaLndEigenCode='        +string(@MohaLndEigenCode)+
  //', @MohaLndInNAWBlok='        +string(@MohaLndInNAWBlok)+
  //', @MohaLndOms='              +string(@MohaLndOms)+
  //', @MohaNaam1='               +string(@MohaNaam1)+
  //', @MohaNaam2='               +string(@MohaNaam2)+
  //', @MohaNawFilNummer='        +string(@MohaNawFilNummer));
  //call Trace(
  //', @MohaNawFilZoekcode='      +string(@MohaNawFilZoekcode)+
  //', @MohaPlaats='              +string(@MohaPlaats)+
  //', @MohaPostcode='            +string(@MohaPostcode)+
  //', @MohaPostcodePositie='     +string(@MohaPostcodePositie)+
  //', @MohaStraat='              +string(@MohaStraat)+
  //', @MohaTelefax='             +string(@MohaTelefax)+
  //', @MohaTelefoon='            +string(@MohaTelefoon)+
  //', @MohaTelefoon2='           +string(@MohaTelefoon2));
  //call Trace(@@ErrorTextProcedure);
  */

  // todo- deze check moet nog anders, lang niet alles is echt null
  if not @MohaContactEmail         = '' or
     not @MohaContactNaamAanhef    = '' or
     not @MohaContactNaamAdres     = '' or
     not @MohaContactNaamBrief     = '' or
     not @MohaContactTelefax       = '' or
     not @MohaContactTelefoon      = '' or
     not @MohaContactTelefoon2     = '' or
     not @MohaContactVolledigeNaam = '' or
     not @MohaEanCode              = '' or
     not @MohaEmail                = '' or
     not @MohaHuisnummer           = '' or
     not @MohaLndEigenCode         = '' or
     not @MohaLndOms               = '' or
     not @MohaNaam1                = '' or
     not @MohaNaam2                = '' or
     not @MohaNawFilNummer         = '' or
     not @MohaNawFilZoekcode       = '' or
     not @MohaPlaats               = '' or
     not @MohaPostcode             = '' or
     not @MohaStraat               = '' or
     not @MohaTelefax              = '' or
     not @MohaTelefoon             = '' or
     not @MohaTelefoon2            = ''
  then
     set @Doorgaan = 1
  end if;

  if @Doorgaan = 1 then

    // Controleren of er een adres bestaat bij deze ontvangst met dezelfde gegevens
    select MohaGid into @MohaGid from tabMagazijnOntvangstHistAdres where
        MohaMohkGid              = @MohkGid
    and MohaContactEmail         = IsNull(@MohaContactEmail             , '')
    and MohaContactNaamAanhef    = IsNull(@MohaContactNaamAanhef        , '')
    and MohaContactNaamAdres     = IsNull(@MohaContactNaamAdres         , '')
    and MohaContactNaamBrief     = IsNull(@MohaContactNaamBrief         , '')
    and MohaContactTelefax       = IsNull(@MohaContactTelefax           , '')
    and MohaContactTelefoon      = IsNull(@MohaContactTelefoon          , '')
    and MohaContactTelefoon2     = IsNull(@MohaContactTelefoon2         , '')
    and MohaContactVolledigeNaam = IsNull(@MohaContactVolledigeNaam     , '')
    and MohaEanCode              = IsNull(@MohaEanCode                  , '')
    and MohaEmail                = IsNull(@MohaEmail                    , '')
    and MohaHuisnummer           = IsNull(@MohaHuisnummer               , '')
    and MohaLndEigenCode         = IsNull(@MohaLndEigenCode             , '')
    and MohaLndOms               = IsNull(@MohaLndOms                   , '')
    and MohaNaam1                = IsNull(@MohaNaam1                    , '')
    and MohaNaam2                = IsNull(@MohaNaam2                    , '')
    and MohaNawFilNummer         = IsNull(@MohaNawFilNummer             , '')
    and MohaNawFilZoekcode       = IsNull(@MohaNawFilZoekcode           , '')
    and MohaPlaats               = IsNull(@MohaPlaats                   , '')
    and MohaPostcode             = IsNull(@MohaPostcode                 , '')
    and MohaStraat               = IsNull(@MohaStraat                   , '')
    and MohaTelefax              = IsNull(@MohaTelefax                  , '')
    and MohaTelefoon             = IsNull(@MohaTelefoon                 , '')
    and MohaTelefoon2            = IsNull(@MohaTelefoon2                , '');

    // is die er nog niet, dan voegen we er een toe
    if @MohaGid is null then

      insert into tabMagazijnOntvangstHistAdres (
        MohaMohkGid,
        MohaContactEmail,
        MohaContactNaamAanhef,
        MohaContactNaamAdres,
        MohaContactNaamBrief,
        MohaContactTelefax,
        MohaContactTelefoon,
        MohaContactTelefoon2,
        MohaContactVolledigeNaam,
        MohaEanCode,
        MohaEmail,
        MohaHuisnummer,
        MohaHuisnummerPositie,
        MohaLndEigenCode,
        MohaLndInNAWBlok,
        MohaLndOms,
        MohaNaam1,
        MohaNaam2,
        MohaNawFilNummer,
        MohaNawFilZoekcode,
        MohaPlaats,
        MohaPostcode,
        MohaPostcodePositie,
        MohaStraat,
        MohaTelefax,
        MohaTelefoon,
        MohaTelefoon2)
      select
        @MohkGid,
        @MohaContactEmail,
        @MohaContactNaamAanhef,
        @MohaContactNaamAdres,
        @MohaContactNaamBrief,
        @MohaContactTelefax,
        @MohaContactTelefoon,
        @MohaContactTelefoon2,
        @MohaContactVolledigeNaam,
        @MohaEanCode,
        @MohaEmail,
        @MohaHuisnummer,
        @MohaHuisnummerPositie,
        @MohaLndEigenCode,
        @MohaLndInNAWBlok,
        @MohaLndOms,
        @MohaNaam1,
        @MohaNaam2,
        @MohaNawFilNummer,
        @MohaNawFilZoekcode,
        @MohaPlaats,
        @MohaPostcode,
        @MohaPostcodePositie,
        @MohaStraat,
        @MohaTelefax,
        @MohaTelefoon,
        @MohaTelefoon2;

      set @MohaGid = @@Identity;
    end if;
  else
    set @MohaGid = null;
  end if;

  set @@ErrorTextProcedure = 'MagazijnOntvangstHistorieVulAdres';
  //call TraceEind(@@ErrorTextProcedure);

  return @MohaGid;
end;

create or replace procedure MagazijnOntvangstMaakHistorisch(in @Verwerking smallint, in @JobVerwerkingId integer, in @Selectie smallint, in @SelMokSoort smallint, in @GoedGekeurd nchar(3), in @VanMagCode integer, in @TotMagCode integer, in @VanMokNummer numeric(10,0), in @TotMokNummer numeric(10,0),
                                                            in @VanNawNr nchar(10), in @TotNawNr nchar(10), in @VanNawZoekcode nchar(10), in @TotNawZoekcode nchar(10), in @VanMokOntvangstDatum date, in @TotMokOntvangstDatum date,
                                                            in @PreviewDesign smallint, out @MohbGid integer)
begin
  declare @MohkGid integer;
  declare @MohrGid integer;
  declare @MohdGid integer;
  declare @LoopCounter integer = 0;

  set @@ErrorTextProcedure = 'MagazijnOntvangstMaakHistorisch > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @Verwerking = ' + string(@Verwerking) + ', @Selectie = ' + string(@Selectie));

  insert into tabMagazijnOntvangstHistBatch (
    MohbSoort,
    MohbStatus,
    MohbAangemaaktOp,
    MohbAangemaaktDoor,
    MohbCbsVastExtraHandelNaarCbsIris  )
  select
    @SelMokSoort,
    0,
    Now(*),
    @@GebruikerCode,
    IsNull((select first CbsVastExtraHandelNaarCbsIris from tabCbsVast), 0);

  set @MohbGid = @@Identity;

  call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabMagazijnOntvangstHistBatch', string(@MohbGid), 0);

  MagOntvKop_Loop:
  for @Cursor as Cursor_MagOntvKop cursor for
    select
      MokGid                     @MokGid,
      MokSoort                   @MokSoort,
      0                          @MokVerwerkt,
      MokNummer                  @MokNummer,
      MokAangemaaktDoor          @MokAangemaaktDoor,
      MokAangemaaktOp            @MokAangemaaktOp,
      MokOntvangstDatum          @MokOntvangstDatum,
      MagCode                    @MagCode,
      MagOms                     @MagOms,

      CbsCoCode                  @CbsCoCode,
      CbsCoOms                   @CbsCoOms,
      CbsGsCode                  @CbsGsCode,
      CbsGsOms                   @CbsGsOms,
      CbsLand.LndEigenCode       @CbsLandLndEigenCode,
      CbsLand.LndOms             @CbsLandLndOms,
      PtnCbsVerkeersGebied       @CbsVgCode,
      PtnNaam                    @CbsVgPlaatsnaam,
      CbsSsCode                  @CbsSsCode,
      CbsSsOms                   @CbsSsOms,
      CbsVwCode                  @CbsVwCode,
      CbsVwOms                   @CbsVwOms,

      RksNaam                    @RksNaam,
      RelEmail                   @RelEmail,
      RelNaamInAanhef            @RelNaamInAanhef,
      RelNaamInAdres             @RelNaamInAdres,
      RelNaamInBrief             @RelNaamInBrief,
      RelVolledigeNaam           @RelVolledigeNaam,
      RelTelefax                 @RelTelefax,
      RelTelefoon                @RelTelefoon,
      RelTelefoon2               @RelTelefoon2,

      NawFilNummer               @NawFilNummer,
      NawFilZoekcode             @NawFilZoekcode,
      NawFilBtwCode              @NawFilBtwCode,
      AdrNaam1                   @AdrNaam1,
      AdrNaam2                   @AdrNaam2,
      adrStraat                  @adrStraat,
      adrHuisNummer              @adrHuisNummer,
      adrPostcode                @adrPostcode,
      adrPlaats                  @adrPlaats,
      NawLand.lndOms             @NawLandlndOms,
      NawLand.lndEigenCode       @NawLandlndEigenCode,
      NawLand.LndInNAWBlok       @NawLndInNAWBlok,
      AdrEmail                   @AdrEmail,
      AdrTelefax                 @AdrTelefax,
      AdrTelefoon                @AdrTelefoon,
      AdrTelefoon2               @AdrTelefoon2,
      NawLand.lndPlaatsHuisnr    @NawLandlndPlaatsHuisnr,
      NawLand.lndPlaatsPostcode  @NawLandlndPlaatsPostcode,
      AdrEanCode                 @AdrEanCode,

      MokOpm                     @MokOpm,
      ValCode                    @ValCode,
      ValNummer                  @ValNummer,
      OmsValuta                  @OmsValuta,

      MokBetKenmerk              @MokBetKenmerk,
      MokCbsMeenemenInAangifte   @MokCbsMeenemenInAangifte,
      MokInkoopfactuurAanmaken   @MokInkoopfactuurAanmaken,
      MokInkoopfactuurVerwerken  @MokInkoopfactuurVerwerken,
      MokFactuurdatum            @MokFactuurdatum,
      MokFactuurnummer           @MokFactuurnummer,
      MokFactuurnummer_Lengte    @MokFactuurnummer_Lengte,
      MokGoedGekeurd             @MokGoedGekeurd,
      MokOmschrijving            @MokOmschrijving,
      MokTeBoeken                @MokTeBoeken,
      MokVervaldatum             @MokVervaldatum,
      MokPakbonnummerLeverancier @MokPakbonnummerLeverancier,
      BtcNummer                  @MokBtcNummer,
      BtcOms                     @BtcOms,

      isnull((select sum(MagOntAantal) from tabMagazijnOntvangsten where MagOntMokGid = MokGid /*Artikelen en tarieven           */), 0) @AantalOntvangenInVoorraadEenheden,
      isnull((select sum(MagOntAantal) from tabMagazijnOntvangsten where MagOntMokGid = MokGid and MagOntRegelsoort = 2 /*Artikel*/), 0) @AantalOntvangenArtikelenInVoorraadEenheden,
      isnull((select sum(MagOntAantal) from tabMagazijnOntvangsten where MagOntMokGid = MokGid and MagOntRegelsoort = 1 /*Tarief */), 0) @AantalOntvangenTarievenInVoorraadEenheden,
      LocNaam @MokLocNaam,
      LocOms @MokLocOms
    from tabMagazijnOntvangstenKop
         inner join tabNawFile on  (NawFilNawGid = MokNawGid)
           left outer join tabBtw on (BtwCode = NawFilBtwCode)
             left outer join tabRekeningSchema on (BtwRksGID = RksGid)
         inner join tabNaw on (NawGid = MokNawGid)
         left outer join tabadres on (AdrGid = NawGidVestiging)
           left outer join tabland NawLand on (LndGid  = AdrLndGid)
         inner join tabValuta on (ValNummer = MokValNummer)
         left outer join tabMagazijn on (MagGid = MokMagGid)
         left outer join (tabRelatie
                          inner join tabRelatieFunctie on (FnRelGid=RelGid and IsBelangrijkste <>0)
                          inner join tabScherm on (SchermFnCode=RelFnCode and SchermSoort=40)
                          ) on (RelNawGid=MokNawGid)
         left outer join tabCbsContainer          on CbsCoGid = MokCbsCoGid
         left outer join tabCbsGoederenStroom     on CbsGsGid = MokCbsGsGid
         left outer join tabLand CbsLand          on CbsLand.LndGid = MokCbsLndGidHerkomst
         left outer join tabPlaatsnaam            on PtnGid = MokCbsPtnGidVerkeersGebied
         left outer join tabCbsStatistischStelsel on CbsSsGid = MokCbsSsGid
         left outer join tabCbsVervoerwijze       on CbsVwGid = MokCbsVwGid
         left outer join tabBetalingsconditie     on BtcNummer = MokBtcNummer
         left outer join tabJobImportVerwerking   on JobivImportRecordGid = MokGid and JobivJobVerwerkingId = @JobVerwerkingId and JobivSoort = (if @MokSoort = 0 then 20 /*ImpSoortGid magontv*/ else 28 /*ImpSoortGid dirlev*/ endif )
         left outer join tabLocatie on (LocGid = MokLocGidOntvangst)
    where
    (@Verwerking = 1  // Dit betreft verwerking
      and (MokGoedGekeurd = 1)
      and (MokNummer between @VanMokNummer and @TotMokNummer)
      and (MokSoort = @SelMokSoort)
      and (@SelMokSoort = 1 or MagCode between @VanMagCode and @TotMagCode)
      and (@JobVerwerkingId = -1) or (JobivImportRecordGid is not null)
     )
    or
    (@Verwerking = 0 // Dit betreft een afdruk(voorbeeld)
      and
      (((@Selectie=1 and NawFilNummer             between @VanNawNr and @TotNawNr)   or
        (@Selectie=2 and NawFilZoekCode           between @VanNawZoekcode and @TotNawZoekcode)   or
        (@Selectie in (3,5) and MokNummer         between @VanMokNummer and @TotMokNummer)   or
        (@Selectie in (4,6) and MokOntvangstdatum between @VanMokOntvangstDatum and @TotMokOntvangstDatum))
      and (MokSoort = @SelMokSoort)
      and (@Goedgekeurd like '%' + string(mokgoedgekeurd) + '%')))
    order by MokNummer asc
  for read only
  do

    insert into tabMagazijnOntvangstHistKop (
      MohkMokGid,
      MohkMohbGid,
      MohkStatus,
      MohkNummer,
      MohkAangemaaktDoor,
      MohkAangemaaktOp,
      MohkOntvangstDatum,
      MohkMagCode,
      MohkMagOms,

      MohkCbsCoCode,
      MohkCbsCoOms,
      MohkCbsGsCode,
      MohkCbsGsOms,
      MohkCbsHerkomstLndEigenCode,
      MohkCbsHerkomstLndOms,
      MohkCbsVgCode,
      MohkCbsVgPlaatsnaam,
      MohkCbsSsCode,
      MohkCbsSsOms,
      MohkCbsVwCode,
      MohkCbsVwOms,

      MohkNawFilBtwCode,
      MohkRksNaam,
      MohkOpm,
      MohkValCode,
      MohkValNummer,
      MohkValOms,

      MohkBetKenmerk,
      MohkCbsMeenemenInAangifte,
      MohkInkoopfactuurAanmaken,
      MohkInkoopfactuurVerwerken,
      MohkFactuurdatum,
      MohkFactuurnummer,
      MohkFactuurnummer_Lengte,
      MohkGoedGekeurd,
      MohkOmschrijving,
      MohkTeBoeken,
      MohkVervaldatum,
      MohkPakbonnummerLeverancier,
      MohkBtcNummer,
      MohkBtcOms,

      MohkAantalOntvangenInVoorraadEenheden,
      MohkAantalOntvangenArtikelenInVoorraadEenheden,
      MohkAantalOntvangenTarievenInVoorraadEenheden,
      MohkLocNaam,
      MohkLocOms)
    select
      @MokGid,
      @MohbGid,
      @MokVerwerkt,
      @MokNummer,
      @MokAangemaaktDoor,
      @MokAangemaaktOp,
      @MokOntvangstDatum,
      @MagCode,
      @MagOms,

      @CbsCoCode,
      @CbsCoOms,
      @CbsGsCode,
      @CbsGsOms,
      @CbsLandLndEigenCode,
      @CbsLandLndOms,
      @CbsVgCode,
      @CbsVgPlaatsnaam,
      @CbsSsCode,
      @CbsSsOms,
      @CbsVwCode,
      @CbsVwOms,

      @NawFilBtwCode,
      @RksNaam,
      @MokOpm,
      @ValCode,
      @ValNummer,
      @OmsValuta,

      @MokBetKenmerk,
      @MokCbsMeenemenInAangifte,
      @MokInkoopfactuurAanmaken,
      @MokInkoopfactuurVerwerken,
      @MokFactuurdatum,
      @MokFactuurnummer,
      @MokFactuurnummer_Lengte,
      @MokGoedGekeurd,
      @MokOmschrijving,
      @MokTeBoeken,
      @MokVervaldatum,
      @MokPakbonnummerLeverancier,
      @MokBtcNummer,
      @BtcOms,

      @AantalOntvangenInVoorraadEenheden,
      @AantalOntvangenArtikelenInVoorraadEenheden,
      @AantalOntvangenTarievenInVoorraadEenheden,
      @MokLocNaam,
      @MokLocOms;

      set @MohkGid = @@Identity;

      update tabMagazijnOntvangstHistKop set MohkMohaGidLeverancier =
        MagazijnOntvangstHistorieVulAdres(
          @MohkGid,
          @RelEmail,
          @RelNaamInAanhef,
          @RelNaamInAdres,
          @RelNaamInBrief,
          @RelTelefax,
          @RelTelefoon,
          @RelTelefoon2,
          @RelVolledigeNaam,
          @AdrEanCode,
          @AdrEmail,
          @adrHuisNummer,
          @NawLandlndPlaatsHuisnr,
          @NawLandlndEigenCode,
          @NawLndInNAWBlok,
          @NawLandlndOms,
          @AdrNaam1,
          @AdrNaam2,
          @NawFilNummer,
          @NawFilZoekcode,
          @adrPlaats,
          @adrPostcode,
          @NawLandlndPlaatsPostcode,
          @adrStraat,
          @AdrTelefax,
          @AdrTelefoon,
          @AdrTelefoon2) where MohkGid = @MohkGid;

      for @Cursor as Cursor_MagOntvRegels cursor for

        select
          MagOntGid             @MagOntGid,
          MagOntRegelsoort      @MohrRegelsoort,
          MagOntRegelnr         @MohrRegelnr,
          ArtGid                @ArtGid,
          ArtCode               @MohrArtCode,
          ArtZoekCode           @MohrArtZoekCode,
          ArtOms                @MohrArtOms,
          ArtAantDecAantallen   @MohrAantDecAantal,
          ArtAantDecPrijzen     @MohrAantDecBedrag,
          ArtKostprijsEx        @MohrArtKostprijsEx,
          ArtSerieNrRegistreren @MohrArtSerieNrRegistreren,
          ArtOmsEenheid         @MohrArtOmsEenheid,
          ArtIsGeblokkeerd      @MohrArtIsGeblokkeerd,
          ArtIsGeblokkeerdInkoop @MohrArtIsGeblokkeerdInkoop,
          ArtHeeftVoorraad       @MohrArtHeeftVoorraad,
          ArtGewichtPerEenheid   @MohrArtGewichtPerEenheid,
          ArtVolumePerEenheid    @MohrArtVolumePerEenheid,
          ArtIsPartijRegistreren @MohrArtIsPartijRegistreren,
          ArtAfbeeldingKlein     @MohrArtAfbeeldingKlein,
          ArtAfbeeldingGroot     @MohrArtAfbeeldingGroot,
          (select ArtTekst FROM tabArtikelTeksten WHERE ArtTaalGid is NULL and ArtTekstArtGid = ArtGid)    @MohrArtOpmerking,
          (select first ArtEanCode from tabArtikelEan where ArtEanArtGid = ArtGid and ArtEanIsDefault = 1) @MohrArtDefaultEanCode,
          ArtPartijNrBijLeverancier @MohrArtPartijNrBijLeverancier,
          ArtPartijOpm            @MohrArtPartijOpm,
          ArtPartijDatumOntvangst @MohrArtPartijDatumOntvangst,
          ArtPartijTHTdatum       @MohrArtPartijTHTdatum,
          ArtPartijVrijTmDatum    @MohrArtPartijVrijTmDatum,
          ArtPartijVrijVanafDatum @MohrArtPartijVrijVanafDatum,
          ArtPartijDatumProductie @MohrArtPartijDatumProductie,

          OpbrGrpNummer         @MohrOpbrGrpNummer,
          OpbrGrpOms            @MohrOpbrGrpOms,
          ArtPartijGid          @ArtPartijGid,
          ArtPartijNummer       @MohrArtPartijNummer,
          ArtPartijOms          @MohrArtPartijOms,
          ArtPartijKostprijsEx  @MohrArtPartijKostprijsEx,
          (SELECT FIRST LocNaam
      									 FROM tabMagazijnOntvangstenDetail
          										INNER JOIN (tabMagazijnOntvangstLocatieSerie INNER JOIN tabLocatie ON (LocGid = MagOntLocLocGid)) ON (MagOntLocMagOntDetGid = MagOntDetGid)
                              LEFT OUTER JOIN tabBestelRegelDetail on (brdGid = MagOntDetbrdGid)
      												LEFT OUTER JOIN (tabOrderRegel INNER JOIN tabOrderkop  ON (OrkGid = OrrOrkGid)) ON (OrrGid = BrdOrrGid)
      									 WHERE MagOntDetMagOntGid = MagOntGid ORDER BY MagOntDetBrdSoort DESC, isNull(OrkNummer, MagOntDetOrkNummer), LocNaam) @MohrEersteLocatie,
      	  BstKopNummer          @MohrBstKopNummer,
      	  BstKopReferentie      @MohrBstKopReferentie,
          BstRglNummer          @MohrBstRglNummer,
          BstRglOms             @MohrBstlRglOms,
          BtwCode               @MohrBtwCode,
          BtwPercentage         @MohrBtwPercentage,

          CbsLand.LndEigenCode                @MohrCbsOorsprongLndEigenCode,
          CbsLand.LndOms                      @MohrCbsOorsprongLndOms,
          CbsTrCode                   @MohrCbsTrCode,
          CbsTrOms                    @MohrCbsTrOms,
          MagOntCbsPreferentieCode    @MohrCbsPreferentieCode,
          MagOntCbsTaric              @MohrCbsTaric,
          MagOntAantal                @MohrAantal,
          MagOntAantalCorrectie       @MohrAantalCorrectie,
          MagOntAantalInkoopEenheden  @MohrAantalInkoopEenheden,
          MagOntArtCodeBijLeverancier @MohrArtCodeBijLeverancier,

          MagOntEanCode                 @MohrEanCode,
          MagOntInkoopEenheid           @MohrInkoopEenheid,
          MagOntInkoopprijs             @MohrInkoopprijs,
          MagOntInkoopprijsPer          @MohrInkoopprijsPer,
          MagOntIsPartijNetAangemaakt   @MohrIsPartijNetAangemaakt,
          MagOntKortingBedrag           @MohrKortingBedrag,
          MagOntKortingPercentage       @MohrKortingPercentage,
          MagOntKortingSoort            @MohrKortingSoort,
          MagOntPrijsPer                @MohrPrijsPer,
          MagOntVoorraadEenhedenInInkoopEenheid @MohrVoorraadEenhedenInInkoopEenheid,
          calcRegelTotaal               @MohrRegelTotaal,
          MagOntOpm                     @MohrOpm,

          // Odnerstaande velden zijn voor het etiketten rapport

          //BTW-code en percentage
          (if (IsNull(ArtIsPartijAparteVerkoopPrijs,1) = 1) then ArtPartijVerkoopBtwCode else ArtBtwCode endif) @MohrBtwCodeVerkoop,
          Isnull((select BtwPercentage from tabBTW where BtwCode = @MohrBtwCodeVerkoop),0.00)                   @MohrBtwPercVerkoop,

          //verkprijs in of ex BVTW?
           (if (IsNull(ArtIsPartijAparteVerkoopPrijs,1) = 1) then ArtPartijVerkoopPrijsIsIncl else ArtVerkprijsIsIncl endif) @MohrVerkoopPrijsIsInclBTW,

          //verkoopprijs excl. BTW
          (if (IsNull(ArtIsPartijAparteVerkoopPrijs,1) = 1)
           then IsNull((if @MohrVerkoopPrijsIsInclBTW = 0 then ArtPartijVerkoopPrijs else  (ArtPartijVerkoopPrijs * (100 / (@MohrBtwPercVerkoop + 100) )) endif), 0.00)
           else IsNull((if @MohrVerkoopPrijsIsInclBTW = 0 then ArtVerkprijs          else  (ArtVerkprijs * (100 / (@MohrBtwPercVerkoop + 100) )) endif), 0.00)
          endif) @MohrVerkoopPrijsExclusief,

          //verkoopprijs incl. BTW
          (if (IsNull(ArtIsPartijAparteVerkoopPrijs,1) = 1)
            then IsNull((if @MohrVerkoopPrijsIsInclBTW = 0 then ArtPartijVerkoopPrijs * ((100 + @MohrBtwPercVerkoop) / 100) else ArtPartijVerkoopPrijs endif), 0.00)
            else IsNull((if @MohrVerkoopPrijsIsInclBTW = 0 then ArtVerkprijs * ((100 + @MohrBtwPercVerkoop) / 100)          else ArtVerkprijs endif), 0.00)
          endif) @MohrVerkoopPrijsInclusief,

          //kortingspercentage of bedrag?
          (if (IsNull(ArtIsPartijAparteVerkoopPrijs,1) = 1)
            then (if ArtPartijKortingsBedrag is not null then 0 else 1 endif)
            else (if StfKopIsPercKorting is null
                then if PraKortingsBedrag is not null then 0 else 1 endif
                else StfKopIsPercKorting
              endif)
          endif) @MohrKortingSoortArtDef,

          //tijdelijk waarde van Kortingsbedrag (kan nog in- of exclusief BTW zijn)
          (if @MohrKortingSoortArtDef <> 1 then // korting van type bedrag
             (if (ArtIsPartijAparteVerkoopPrijs = 1)
                 then ArtPartijKortingsBedrag    // Bij aparte prijs per partij altijd deze gebruiken
                 else (if (StfKopIsPercKorting is null)
                         then IsNull(PraKortingsBedrag, 0.00)        //geen staffel, dus korting uit de prijsafspraak pakken
                         else IsNull(round((StfRglKorting * ArtPrijsPer), ArtAantDecPrijzen), 0.00)   //wel staffel, dus korting uit de staffel pakken
                       endif)
              endif)
           endif) @tmpKortingBedrag,

           // is korting in of ex BTW?
          (if @MohrKortingSoortArtDef <> 1 then // Wel korting van type bedrag
             (if (ArtIsPartijAparteVerkoopPrijs = 1)
                 then ArtPartijVerkoopPrijsIsIncl // Bij aparte prijs per partij altijd instelling uit partij gebruiken
                 else (if (StfKopIsPercKorting is null)
                         then IsNull(PraIsInclBtw, 0) //geen staffel, dus instelling uit de prijsafspraak pakken
                         else 0                       //wel staffel, kortingbedrag is altijd excl. BTW
                       endif)
              endif)
           endif) @tmpKortingBedragIsInclBtw,

          //Kortingsbedrag excl. BTW
          (if @MohrKortingSoortArtDef <> 1 then    // korting van type bedrag
             IsNull((if @tmpKortingBedragIsInclBtw = 0 then @tmpKortingBedrag else  (@tmpKortingBedrag * (100 / (@MohrBtwPercVerkoop + 100) )) endif), 0.00)
           endif) @MohrKortingsBedragExclusiefArtDef,

          //Kortingsbedrag incl. BTW
          (if @MohrKortingSoortArtDef <> 1 then    // korting van type bedrag
             IsNull((if @tmpKortingBedragIsInclBtw = 0 then @tmpKortingBedrag * ((100 + @MohrBtwPercVerkoop) / 100) else @tmpKortingBedrag endif), 0.00)
           endif) @MohrKortingsBedragInclusiefArtDef,

          //kortingspercentage indien van soort percentage : @MohrKortingSoortArtDef = 1 anders 0.00
          (if @MohrKortingSoortArtDef = 1  then  //kortingspercentage
             (if (IsNull(ArtIsPartijAparteVerkoopPrijs,1) = 1)
                      //Indien aparte verkprijs per partij, dan altijd korting van partij pakken
                 then ArtPartijKortingsPerc
                      //Geen aparte verkprijs per partij, dus korting uit standaardprijsafspraak of staffel pakken
                 else (if (StfKopIsPercKorting  is null)
                          then PraKortingsPerc
                          else StfRglKorting
                       endif)
              endif)
           endif) @MohrKortingsPercArtDef,

          // adviesprijs
          ArtIsAdviesPrijsInclBtw  @MohrArtIsAdviesPrijsInclBTW,
          (if ArtIsAdviesPrijsInclBtw <> 0
            then (ArtAdviesPrijs / (1+ (select BtwPercentage from tabBtw where ArtBtwCode = BtwCode) / 100))
            else ArtAdviesPrijs
          endif) @MohrAdviesPrijsExclusief,

          (if ArtIsAdviesPrijsInclBtw <> 0
            then ArtAdviesPrijs
            else ( ArtAdviesPrijs *(1+ (select BtwPercentage from tabBtw where ArtBtwCode = BtwCode)/100))
          endif) @MohrAdviesPrijsInclusief,
          RelEmail                             @RegelRelEmail,
          RelNaamInBrief                       @RegelRelNaamInBrief,
          RelNaamInAdres                       @RegelRelNaamInAdres,
          RelNaamInAanhef                      @RegelRelNaamInAanhef,
          RelTelefax                           @RegelRelTelefax,
          RelTelefoon                          @RegelRelTelefoon,
          RelTelefoon2                         @RegelRelTelefoon2,
          RelVolledigeNaam                     @RegelRelVolledigeNaam,
          NawFilNummer                         @RegelNawFilNummer,
          NawFilZoekcode                       @RegelNawFilZoekcode,
          AdrNaam1                             @RegelAdrNaam1,
          AdrNaam2                             @RegelAdrNaam2,
          AdrStraat                            @RegelAdrStraat,
          AdrHuisNummer                        @RegelAdrHuisNummer,
          AdrPostcode                          @RegelAdrPostcode,
          AdrPlaats                            @RegelAdrPlaats,
          AflLand.LndOms                       @RegelAflLandLndOms,
          AflLand.LndEigenCode                 @RegelAflLandLndEigenCode,
          AflLand.LndInNawBlok                 @RegelAflLandLndInNawBlok,
          AdrEmail                             @RegelAdrEmail,
          AdrTelefax                           @RegelAdrTelefax,
          AdrTelefoon                          @RegelAdrTelefoon,
          AdrTelefoon2                         @RegelAdrTelefoon2,
          AflLand.LndPlaatsHuisnr              @RegelAflLandLndPlaatsHuisnr,
          AflLand.LndPlaatsPostcode            @RegelAflLandLndPlaatsPostcode,
          AdrEanCode                           @RegelAdrEanCode
        from tabMagazijnOntvangsten
            inner join tabMagazijnOntvangstenKop on (MokGid = MagOntMokGid)
            inner join tabArtikel on(ArtGid = MagOntArtGid)
            inner join vwMagazijnOntvangstRegelTotalen on calcMagOntGid = MagOntGid
            left outer join tabMagazijn on (MokMagGid = MagGid)
            left outer join tabOpbrengstGroep on (OpbrGrpGId = ArtOpbrGrpGId)
            left outer join tabBtw on(BtwCode = MagOntBtwCode)
            left outer join tabArtikelPartij on (ArtPartijGid = MagOntArtPartijGid)
            left outer join tabBestelRegel on (BstRglGid = MagOntBstRglGid)
            left outer join tabBestelKop on (BstKopGid = BstRglBstKopGid)
            left outer join tabLand CbsLand on LndGid = MagOntCbsLndGidOorsprong
            left outer join tabCbsTransactie on CbsTrGid = MagOntCbsTrGid
            left outer join tabPrijsAfspraak on (PraArtGid = ArtGid and PraCombiSoort = 0)
            left outer join (tabStaffelKop inner join tabStaffelRegel on StfRglStfKopGid = StfKopGid and StfRglVanafAantal = 0.0) on (StfKopGid = PraStfKopGid) and (ArtIsPartijAparteVerkoopPrijs <> 1)
            left outer join (tabNaw inner join tabNawFile on NawFilNawGid = NawGid) on NawGid = BstKopNawGidAflevering
            //ACW 01-11-2011 Incident #05747: Als er geen bestelling aan is gekoppeld, dan het magazijnadres gebruiken!
            left outer join (tabAdres inner join tabLand AflLand on AdrLndGid = AflLand.LndGid) on AdrGid = (if isnull(BstKopAfleverAdres, 0) = 0 then
                                                                                                               MagAdrGid
                                                                                                             else
                                                                                                               case BstKopAfleverAdresNAW
                                                                                                                when 0 then NawGidCorrespondentie
                                                                                                                when 1 then NawGidVestiging
                                                                                                                when 2 then BstKopAdrGidAflevering
                                                                                                               end
                                                                                                             endif)
            left outer join tabRelatie on RelGid = BstKopRelGidAflevering
        where  MagOntMokGid = @MokGid

      for read only
      do
        insert into tabMagazijnOntvangstHistRegel (
          MohrMohkGid,
          MohrRegelsoort,
          MohrRegelnr,
          MohrArtCode,
          MohrArtZoekCode,
          MohrArtOms,
          MohrAantDecAantal,
          MohrAantDecBedrag,
          MohrArtKostprijsEx,
          MohrArtSerieNrRegistreren,
          MohrArtOmsEenheid,
          MohrArtIsGeblokkeerd,
          MohrArtIsGeblokkeerdInkoop,
          MohrArtHeeftVoorraad,
          MohrArtGewichtPerEenheid,
          MohrArtVolumePerEenheid,
          MohrArtIsPartijRegistreren,
          MohrArtAfbeeldingKlein,
          MohrArtAfbeeldingGroot,
          MohrArtOpmerking,
          MohrArtDefaultEanCode,
          MohrArtPartijNrBijLeverancier,
          MohrArtPartijOpm,
          MohrArtPartijDatumOntvangst,
          MohrArtPartijTHTdatum,
          MohrArtPartijVrijTmDatum,
          MohrArtPartijVrijVanafDatum,
          MohrArtPartijDatumProductie,

          MohrOpbrGrpNummer,
          MohrOpbrGrpOms,
          MohrArtPartijNummer,
          MohrArtPartijOms,
          MohrArtPartijKostprijsEx,
          MohrEersteLocNaam,
          MohrBstKopNummer,
          MohrBstKopReferentie,
          MohrBstRglNummer,
          MohrBstlRglOms,
          MohrBtwCode,
          MohrBtwPercentage,

          MohrCbsOorsprongLndEigenCode,
          MohrCbsOorsprongLndOms,
          MohrCbsTrCode,
          MohrCbsTrOms,
          MohrCbsPreferentieCode,
          MohrCbsTaric,
          MohrAantal,
          MohrAantalCorrectie,
          MohrAantalInkoopEenheden,
          MohrArtCodeBijLeverancier,

          MohrEanCode,
          MohrInkoopEenheid,
          MohrInkoopprijs,
          MohrInkoopprijsPer,
          MohrIsPartijNetAangemaakt,
          MohrKortingBedrag,
          MohrKortingPercentage,
          MohrKortingSoort,
          MohrPrijsPer,
          MohrVoorraadEenhedenInInkoopEenheid,
          MohrRegelTotaal,
          MohrOpm,

          MohrBtwCodeVerkoop,
          MohrBtwPercVerkoop,
          MohrVerkoopPrijsIsInclBTW,
          MohrVerkoopPrijsExclusief,
          MohrVerkoopPrijsInclusief,
          MohrKortingSoortArtDef,
          MohrKortingsBedragExclusiefArtDef,
          MohrKortingsBedragInclusiefArtDef,
          MohrKortingsPercArtDef,
          MohrArtIsAdviesPrijsInclBTW,
