          @MohrArtZoekCode,
          @MohrArtOms,
          @MohrAantDecAantal,
          @MohrAantDecBedrag,
          @MohrArtKostprijsEx,
          @MohrArtSerieNrRegistreren,
          @MohrArtOmsEenheid,
          @MohrArtIsGeblokkeerd,
          @MohrArtIsGeblokkeerdInkoop,
          @MohrArtHeeftVoorraad,
          @MohrArtGewichtPerEenheid,
          @MohrArtVolumePerEenheid,
          @MohrArtIsPartijRegistreren,
          @MohrArtAfbeeldingKlein,
          @MohrArtAfbeeldingGroot,
          @MohrArtOpmerking,
          @MohrArtDefaultEanCode,
          @MohrArtPartijNrBijLeverancier,
          @MohrArtPartijOpm,
          @MohrArtPartijDatumOntvangst,
          @MohrArtPartijTHTdatum,
          @MohrArtPartijVrijTmDatum,
          @MohrArtPartijVrijVanafDatum,
          @MohrArtPartijDatumProductie,

          @MohrOpbrGrpNummer,
          @MohrOpbrGrpOms,
          @MohrArtPartijNummer,
          @MohrArtPartijOms,
          @MohrArtPartijKostprijsEx,
          @MohrEersteLocatie,
          @MohrBstKopNummer,
          @MohrBstKopReferentie,
          @MohrBstRglNummer,
          @MohrBstlRglOms,
          @MohrBtwCode,
          @MohrBtwPercentage,

          @MohrCbsOorsprongLndEigenCode,
          @MohrCbsOorsprongLndOms,
          @MohrCbsTrCode,
