              @RegelAdrTelefoon,
              @RegelAdrTelefoon2) where MohrGid = @MohrGid;

          for @Cursor as Cursor_MagOntvDetail cursor for

            select
              MagOntDetGid              @MagOntDetGid,
              MagOntDetOrrGid           @MohdOrrGid,
              if MagOntDetBrdGid is null then MagOntDetOrkNummer     else if BrdOrrGid is null then BrdOrkNummer    else OrkNummer  endif endif   @MohdOrkNummer,
              if MagOntDetBrdGid is null then MagOntDetOrrRegelNr    else if BrdOrrGid is null then BrdOrrRegelnr   else OrrRegelNr endif endif   @MohdOrrRegelNr,
              if MagOntDetBrdGid is null then MagOntDetNawFilNummer  else if BrdOrrGid is null then brdNawFilNummer else NawFilNummer endif endif @MohdDebiteurNummer,
              if MagOntDetBrdGid is null then MagOntDetAdrNaam1      else if BrdOrrGid is null then brdAdrNaam1     else AdrNaam1 endif endif     @MohdDebiteurNaam,
              OrrAantalBackorder        @MohdAantalBackorder,
              isnull(OrrLeverDatum, OrkLeverdatum) @MohdLeverDatum,
              MagOntDetbrdGid           @MohdbrdGid,
              brdAantalBesteld          @MohdbrdAantalBesteld,
              brdAantalOntvangen        @MohdbrdAantalOntvangen,
              brdAantalOntvangen - brdAantalBesteld + brdAantalNogTeOntvangen @MohdbrdAantalCorrectie,
              brdAantalNogTeOntvangen   @MohdbrdAantalNogTeOntvangen,
          	  MagOntDetAantalCorrectie  @MohdAantalCorrectie,
