            from tabMagazijnOntvangstenDetail
                 left outer join tabBestelRegelDetail on (brdGid = MagOntDetbrdGid)
                 left outer join (tabOrderRegel
                     inner join tabOrderkop  on (OrkGid = OrrOrkGid)
                     inner join tabNaw       on (NawGid = OrkNawGid)
                     inner join tabNawFile   on (NawFilNawGid = OrkNawGid and NawFilFonID='D')
                     inner join tabAdres     on (AdrGid = NawGidVestiging)
                     inner join tabLand AdrLandTabel on (AdrLndGid = LndGid))
                     on (OrrGid = BrdOrrGid)
            where MagOntDetMagOntGid = @MagOntGid

          for read only
          do

            insert into tabMagazijnOntvangstHistDetail (
              MohdMohrGid,
              MohdOrrGid,
              MohdOrkNummer,
              MohdOrrRegelNr,
