              IsNull(@MohdbrdAantalCorrectie, 0),
              IsNull(@MohdbrdAantalNogTeOntvangen, 0),
              IsNull(@MohdAantalCorrectie, 0),
              IsNull(@MohdBrdSoort, 0);

              set @MohdGid = @@Identity;

              update tabMagazijnOntvangstHistDetail set MohdMohaGid =
                MagazijnOntvangstHistorieVulAdres(
                  @MohkGid,
                  null, //@RegelRelEmail,
                  null, //@RegelRelNaamInBrief,
                  null, //@RegelRelNaamInAdres,
                  null, //@RegelRelNaamInAanhef,
                  null, //@RegelRelTelefax,
