                  null, //@RegelRelTelefoon2,
                  null, //@RegelRelVolledigeNaam,
                  @MohdAdrEanCode,
                  @MohdAdrEmail,
                  @MohdAdrHuisnummer,
                  @MohdLndPlaatsHuisnr,
                  @MohdLndEigenCode,
                  @MohdLndInNawBlok,
                  @MohdLndOms,
                  @MohdDebiteurNaam,
                  @MohdAdrNaam2,
                  @MohdDebiteurNummer,
                  @MohdNawFilZoekcode,
                  @MohdAdrPlaats,
                  @MohdAdrPostcode,
                  @MohdLndPlaatsPostcode,
                  @MohdAdrStraat,
                  @MohdAdrTelefax,
                  @MohdAdrTelefoon,
                  @MohdAdrTelefoon2) where MohdGid = @MohdGid;

              for @Cursor as Cursor_MagOntvLocatieSerie cursor for

                select
                  LocNaam                       @MohlLocNaam,
                  LocOms                        @MohlLocOms,
                  ArtSerieNummer                @MohlArtSerieNummer,
                  MagOntLocAantal               @MohlAantal,
                  MagOntLocIsSerieNetAangemaakt @MohlIsSerieNetAangemaakt
                from tabMagazijnOntvangstLocatieSerie
                   left outer join tabLocatie on (LocGid = MagOntLocLocGid)
                   left outer join tabArtikelSerienummer on (ArtSerieGid = MagOntLocArtSerieGid)
                where
                	MagOntLocMagOntDetGid = @MagOntDetGid

              for read only
              do
                insert into tabMagazijnOntvangstHistLocatieSerie (
                  MohlMohdGid,
                  MohlLocNaam,
                  MohlLocOms,
                  MohlArtSerieNummer,
                  MohlAantal,
                  MohlIsSerieNetAangemaakt )
                select
                  @MohdGid,
                  @MohlLocNaam,
                  @MohlLocOms,
                  @MohlArtSerieNummer,
                  IsNull(@MohlAantal, 0),
                  IsNull(@MohlIsSerieNetAangemaakt, 0);

              end for;  // LocatieSerie

          end for; // Detail

          insert into tabMagazijnOntvangstHistRglArtTekst (
            MohratMohrGid,
            MohratTaalCode,
            MohratTekst )
          select
            @MohrGid,
            TaalCode,
            ArtTekst
          from tabArtikelTeksten inner join tabTaal on ArtTaalGid = TaalGid
          where ArtTekstArtGid = @ArtGid and ArtTekst <> '';

          insert into tabMagazijnOntvangstHistRglPartTekst (
            MohrptMohrGid,
            MohrptTaalCode,
            MohrptTekst )
          select
            @MohrGid,
            TaalCode,
            ArtPartijTekstOpFactuur
          from tabArtikelPartijTeksten inner join tabTaal on ArtPartijTekstTaalGid = TaalGid
          where ArtPartijTekstArtPartijGid = @ArtPartijGid and ArtPartijTekstOpFactuur <> '';

          call OvernemenVrijeRubrieken(-1, @MohrGid, @ArtGid, 'ART', '000', '000', 'tabMagazijnOntvangstHistRglVrRubrArt', 'MohvraMohrGid', 'Mohvra', 0);

          if @ArtPartijGid is not null then
            call OvernemenVrijeRubrieken(-1, @MohrGid, @ArtPartijGid, 'PAR', '000', '000', 'tabMagazijnOntvangstHistRglVrRubrPart', 'MohvrpMohrGid', 'Mohvrp', 0);
          end if;

      end for;  // Regel

      // de archiefstukken overnemen naar historie
      insert into tabDigitaalArchiefMagOntvHist (
        DaMohMohkGid,
        DaMohDarGid )
      select
        @MohkGid,
        DaMagOntDarGid
      from tabDigitaalArchiefMagazijnOntvangsten where DaMagOntMokGid = @MokGid;

      // Indien alle adressen in de regel hetzelfde, dan deze in de kop opslaan ovv Acw
      if (select count(*) from (select distinct MohrMohaGid from tabMagazijnontvangstHistRegel where MohrRegelSoort = 2 and MohrMohkGid = @MohkGid group by MohrMohaGid) as Dummy) = 1 then
        update tabMagazijnOntvangstHistKop set MohkMohaGidAflever = (select MohrMohaGid from tabMagazijnontvangstHistRegel where MohrRegelSoort = 2 and MohrMohkGid = @MohkGid group by MohrMohaGid) where MohkGid = @MohkGid;
      end if;


      //DG: Ten behoeve van #35800 in PreviewDesign alleen de eerste tien tonen.
      set @LoopCounter = @LoopCounter + 1;
      if @PreviewDesign = 1 and @LoopCounter >= 10 then
        LEAVE MagOntvKop_Loop;
      end if;

  end for MagOntvKop_Loop; // Kopf

  set @@ErrorTextProcedure = 'MagazijnOntvangstMaakHistorisch';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure MagazijnOntvangstNrGenereren(
  in  @Forceer    smallint,
  out @Nummer     numeric(10,0)
)
//---------------------------------------------------------------------------
//----------------------------Magazijnontvangst nummer genereren-------------
//---------------------------------------------------------------------------
begin
  declare @Genereren   numeric(10,0);
  declare @Startnummer numeric(10,0);
  declare @gevonden    integer;

  //set @@ErrorTextProcedure = 'MagazijnOntvangstNrGenereren > @Forceer='+string(@Forceer);
  //call TraceBegin(@@ErrorTextProcedure);

  set @nummer=0;
  if @Forceer = 1 then
    set @Genereren=1;
    select MagVastStartNummer into @startnummer from tabMagazijnOntvangstenVasteGegevens;
  else
    select MagVastDefOntvangstNummer, MagVastStartNummer into @Genereren, @startnummer from tabMagazijnOntvangstenVasteGegevens;
  end if;
  if @genereren=1 then
    call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'MagazijnOntvangstenGenereerNummer', '');
    set @gevonden=0;
    while @gevonden=0
    loop
      // Zoek eerstvolgende gat in de combinatie van magazijnotnvangsten en historisceh magazijontvangsten goter of gelijk aan startnummer
      if    not exists(select first 1 from tabMagazijnOntvangstenKop where MokNummer = @startnummer)
        and not exists(select first 1 from tabMagazijnOntvangstHistKop where MohkNummer = @startnummer) then
        set @nummer = @Startnummer;
        set @gevonden = 1;
      else
        select min(Nummer)+1
        into @Nummer
        from   (  select MokNummer nummer from tabMagazijnOntvangstenKop where MokNummer > @startnummer
                union all
                  select MohkNummer from tabMagazijnOntvangstHistKop where MohkNummer > @startnummer
                union all
                  select @startnummer
               ) Nummers
        where nummer <> 9999999999 // Voorkomt error Value out of range for destination
          and nummer+1 not in (  select MokNummer from tabMagazijnOntvangstenKop where MokNummer >= @startnummer
                               union all
                                 select MohkNummer from tabMagazijnOntvangstHistKop where MohkNummer >= @startnummer
                              );
        if @nummer is null then
          if @Startnummer = 1 then
            call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'MagazijnOntvangstenGenereerNummer', '');
            raiserror 20780, 'Aanmaken magazijnontvangstnummer', 'Alle nummers van 1 tot 9999999999 zijn gebruikt'; //(20780) %1! niet mogelijk: %2!.
          else
            set @Startnummer = 1; // Niet gevonden, dan vanaf begin zoeken
          end if;
        else
          set @gevonden = 1;
        end if;
      end if;

    end loop;
    if @nummer=9999999999 then
      update tabMagazijnOntvangstenVasteGegevens set MagVastStartNummer=1;
    else
      update tabMagazijnOntvangstenVasteGegevens set MagVastStartNummer=@nummer+1;
    end if;
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'MagazijnOntvangstenGenereerNummer', '');
  end if;

  //set @@ErrorTextProcedure = 'MagazijnOntvangstNrGenereren > @Nummer='+string(@Nummer);
  //call TraceEind(@@ErrorTextProcedure);

end;


//LET OP : Indien deze stored proc wijzigt, kijk dan ook of CreeerMagazijnOntvangstObvBestelRegelDetail aangepast moet worden.
create or replace procedure MagazijnOntvangstSpecObvBestelregelDetail(in @BstRglGid integer, in @MagGid integer, in @AantalNuOntvangen numeric(15,3), in @MagOntGid integer, in @MokGid integer)
Result (BrdGid integer, AantalOntvangen numeric(15,3), AantalCorrectie numeric(15,3), LocGid integer, brdSoort integer, brdAantalBesteld numeric(15,3))
begin
  declare local temporary table tmpBestelRegelDetail(
    BrdGid                   integer,
    AantalOntvangen          numeric(15,3),
    AantalCorrectie          numeric(15,3),
    LocGid                   integer,
    BrdSoort                 integer,
    BrdAantalBesteld         numeric(15,3))
  on commit preserve rows;

  declare @_DefaultLocGid integer = GeefLocatieVoorMagazijnOntvangst(@MagGid, @BstRglGid, null, @MagOntGid, @MokGid);
  declare @GebruikMeegegevenAantal  integer;
  declare @GebruikBestelAantal      integer;
  declare @AantalCorrectie          numeric(15,3);

  declare @_MagVastDefLocatie                    smallint = 1;
  declare @_MagVastOntvangstRegistrerenOpLocatie smallint = 0;
  declare @_CrossDock_DirecteInkoop              integer = null;

  //call TraceBegin('MagazijnOntvangstSpecObvBestelregelDetail > @BstRglGid='+string(@BstRglGid));

  //Instellingen tbv wijze van werken met ontvangstlocaties
  select MagVastDefLocatie, MagVastOntvangstRegistrerenOpLocatie
  into @_MagVastDefLocatie, @_MagVastOntvangstRegistrerenOpLocatie
  from tabMagazijnOntvangstenVasteGegevens;

  //bepalen crossdocklocatie directe inkoop van betreffende magazijn
  if (@_MagVastOntvangstRegistrerenOpLocatie = 0) and  /*voorkeurslocatie van artikel*/
     (@_MagVastDefLocatie = 1) /*Default voorkeurslocatie*/ then
    Select MagLocGidVoorkeurDirecteInkoop into @_CrossDock_DirecteInkoop
    from tabMagazijn
         inner join tabLocatie on (locGid=MagLocGidVoorkeurDirecteInkoop)
    where (MagGid=@MagGid) and (LocBlokkade = 0);
  end if;

  //Controleer of het aantal nu te ontvangen overeenkomt met hetgeen besteld is.
  set @GebruikMeegegevenAantal = 0;
  if (select sum(brdAantalNogTeOntvangen) from tabBestelRegelDetail where BrdBstRglGid = @BstRglGid) = @AantalNuOntvangen then
    set @GebruikBestelAantal = 1;
  else
    set @GebruikBestelAantal = 0;
    if (select count(*) from tabBestelRegelDetail where BrdBstRglGid = @BstRglGid) = 1 then  //Aantal is niet gelijk, maar er 1 maar 1 detailregel bij de bestelregel, dan aantal overnemen wat meegegeven is aan storedproc
      set @GebruikMeegegevenAantal = 1
    end if;
  end if;

  //call Trace('@GebruikMeegegevenAantal = ' + string(@GebruikMeegegevenAantal)+', @GebruikBestelAantal = ' + string(@GebruikBestelAantal));

  insert into tmpBestelRegelDetail(BrdGid, LocGid, BrdSoort, BrdAantalBesteld, AantalOntvangen, AantalCorrectie)

  select BrdGid, (if BrdSoort=0 then  @_DefaultLocGid else Isnull(@_CrossDock_DirecteInkoop, @_DefaultLocGid) endif), brdSoort, brdAantalBesteld,
         if (OrrGid is null or IsNull(OrrDirecteInkoop, 0) = 0) then @GebruikBestelAantal * brdAantalNogTeOntvangen + @GebruikMeegegevenAantal * @AantalNuOntvangen else if @GebruikBestelAantal * brdAantalNogTeOntvangen + @GebruikMeegegevenAantal * @AantalNuOntvangen > OrrAantalBackorderVrrdEenh then OrrAantalBackorderVrrdEenh else @GebruikBestelAantal * brdAantalNogTeOntvangen + @GebruikMeegegevenAantal * @AantalNuOntvangen endif endif,
         if (OrrGid is null or IsNull(OrrDirecteInkoop, 0) = 0) then 0 else if @GebruikBestelAantal * brdAantalNogTeOntvangen + @GebruikMeegegevenAantal * @AantalNuOntvangen > OrrAantalBackorderVrrdEenh then OrrAantalBackorderVrrdEenh - (@GebruikBestelAantal * brdAantalNogTeOntvangen + @GebruikMeegegevenAantal * @AantalNuOntvangen) else 0 endif endif
  from   tabBestelRegel
         inner join tabBestelRegelDetail on (BrdBstRglGid = BstRglGid)
         left outer join (tabOrderRegel
                          inner join tabOrderKop on (OrkGid = orrOrkGid)
                         ) on (OrrGid = brdOrrGid)
  where  BstRglGid = @BstRglGid and BstRglSoort = 2
  order by brdSoort desc,
        if BrdOrrGid is null then
          string(BrdOrkNummer) + '/' + (if BrdOrrRegelnr>999 then string(BrdOrrRegelnr) else right('000' + string(BrdOrrRegelnr), 3) endif)
        else
          string(OrkNummer) + '/' + (if OrrRegelnr>999 then string(OrrRegelnr) else right('000' + string(OrrRegelnr), 3) endif)
        endif; //OrderNr

  //Als het correctie aantal ongelijk aan 0 is, dan moeten we deze correctie tegenboeken op de magazijn
  set @AantalCorrectie = 0;
  select sum(AantalCorrectie) into @AantalCorrectie from tmpBestelRegelDetail;
  if @AantalCorrectie <> 0 then
    update tmpBestelRegelDetail set AantalOntvangen = AantalOntvangen - @AantalCorrectie, AantalCorrectie = -@AantalCorrectie
    where  BrdSoort = 0; /* magazijn */
    if @@rowcount = 0 then  //Als er niets geupdate is, dan was er dus geen record van het type magazijn, dus moeten we alsnog een insert doen. Vervolgens wordt in de trigger bestelregeldetail aangemaakt en hieraan gekopppeld
      insert into tmpBestelRegelDetail (BrdSoort, AantalOntvangen, AantalCorrectie)
      select 0 /*magazijn*/, -@AantalCorrectie, -@AantalCorrectie
    end if
  end if;

  select BrdGid, AantalOntvangen, AantalCorrectie, LocGid, brdSoort, brdAantalBesteld from tmpBestelRegelDetail;

  //call TraceEind('MagazijnOntvangstSpecObvBestelregelDetail');
end;


create or replace procedure MagazijnOntvangstVerwerken(in @MokGid integer, in @MohkGid integer, in @Boekdatum date, in @Stuknummer numeric(10,0), in @RapNummer integer, inout @BoekgangGid integer, inout @FbGid integer)
begin
  //Constanten
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  //declare @ErrText                nchar(500);
  //uit magontkop:
  declare @MokSoort               integer;
  declare @MokNawGid              integer;
  declare @MokOntvangstDatum      date;
  declare @MokNummer              numeric(10,0);
  declare @DirLevKenmerk          numeric(10,0); // Gevuld met MokNummer als het een DirLev betreft
  declare @MokValNummer           integer;
  declare @MokMagGid              integer;
  declare @MokCbsLndGidHerkomst   integer;

  declare @BjGid                  integer;
  declare @PerNr                  integer;
  declare @Dummy                  nchar(2);
  declare @MagVastOntvBoekenTegen integer;//0 = Vaste VerrekenPrijs, 1 = werkelijke inkoopprijs
  declare @JpGidOntvangst         integer;

  declare @LndGidEigenLand                integer;
  declare @EuroValNummer                  integer;
  declare @LocGid                         integer;
  declare @CbsVastNaarCbsIrisInvoer       integer;
  declare @CbsVastExtraHandelNaarCbsIris  integer;
  declare @LndIsEGLid                     integer;
  declare @CbsMeenemenInAangifte          integer;

  //ACW 06-03-2009: project Directe inkoop
  declare @vofRegelDefNuFactureren          smallint;
  declare @vofFactIsArtikelRegelVerwijderen smallint;
  declare @vofFactIsTariefRegelVerwijderen  smallint;
  declare @vofFactIsTekstRegelVerwijderen   smallint;
  declare @vofLevOokTarief                  smallint;
  declare @vofLevOokTekst                   smallint;
  declare @vofFactAutomVrijgeven            smallint;
  declare @OrlGid                           integer;

  declare @OrrAantalVrrdEenhInVerkEenh             numeric(15,3);
  declare @OrrAantalVrrdEenhInVerkEenhMagAfwijken  smallint;
  declare @OrrAantDecAantal                        smallint;
  declare @OrrAantDecAantalVrrdEenh                smallint;

  declare @OrrAantalLevering                       numeric(15,3);
  declare @OrrAantalLeveringVrrdEenh               numeric(15,3);
  declare @OrrAantalGeleverd                       numeric(15,3);
  declare @OrrAantalGeleverdVrrdEenh               numeric(15,3);
  declare @OrrAantalDezeFacturering                numeric(15,3);
  declare @OrrAantalDezeFactureringVrrdEenh        numeric(15,3);
  declare @OrrAantalNogTeFactureren                numeric(15,3);

  //hulpvariabelen
  declare @OldOrrAantal         numeric(15,3);
  declare @NewOrrAantal         numeric(15,3);
  declare @OldOrrAantalVrrdEenh numeric(15,3);

  // ACW 17-12-2010: project Directe levering
  declare @IsStuksKorting SmallInt;

  // DG 05-09-2017: project Inkoopfacturen
  declare @InkoopFactuurAanmaken smallint;
  declare @InkoopFactuurBoeken smallint;

  // tbv. verwijderen verkooporder(regel)s
  declare local temporary table tmpOrderKopEnRegels(
    tmpOrkGid integer,
    tmpOrrGid integer
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'MagazijnOntvangstVerwerken > ';
  //call TraceBegin(@@ErrorTextProcedure + '@MokGid = ' + string(@MokGid));

  select  ValNummer  into @EuroValNummer from tabValuta where IsEuro <> 0;
  if @EuroValNummer is null then
   set @EuroValNummer = @@BasisValutaNummer;
  end if;

  select  CbsVastNaarCbsIrisInvoer, CbsVastExtraHandelNaarCbsIris
    into @CbsVastNaarCbsIrisInvoer,@CbsVastExtraHandelNaarCbsIris
    from tabCbsVast;

  set @@MagOntWordVerwerkt = 1;

  //gegevens uit kop:
  //set @@ErrorTextProcedure = @ErrText + '>MagazijnOntvangstenKop uitlezen' ;
  //call Trace(@@ErrorTextProcedure);
  select  MokSoort,  MokNawGid,  MokOntvangstDatum,  MokNummer,  MokValNummer,  MokMagGid,  MokCbsLndGidHerkomst, MokCbsMeenemenInAangifte, if MokSoort = 1 /*Directe levering*/ then MokNummer endif,
     MokInkoopfactuurAanmaken, if MokInkoopfactuurAanmaken = 1 and MokInkoopfactuurVerwerken = 1 then 1 else 0 endif
  into   @MokSoort, @MokNawGid, @MokOntvangstDatum, @MokNummer, @MokValNummer, @MokMagGid, @MokCbsLndGidHerkomst, @CbsMeenemenInAangifte,   @DirLevKenmerk,
    @InkoopFactuurAanmaken, @InkoopFactuurBoeken
  from   tabMagazijnOntvangstenKop where  MokGid = @MokGid;

  // 28-05-2018 ACW Defect #53849 - Geen optie Inkoopfacturen, dan de aangemaakte altijd verwerken!
  if ((select IsModuleActive('if')) = 0) then
    set @InkoopFactuurBoeken = @InkoopFactuurAanmaken;
  end if;

  //set @@ErrorTextProcedure = @ErrText + '>Financiele gedeelte bijwerken' ;
  //call Trace(@@ErrorTextProcedure);
  //ACW 13-09-2010: Uitbreiding DL: Boeken apart verwerken
  case @MokSoort
    when 0 /*MagazijnOntvangst*/ then call MagazijnOntvangstBoeken(@MokGid, @MohkGid, @Boekdatum, @Stuknummer, @BoekgangGid, @JpGidOntvangst);
    when 1 /*Directe levering */ then call DirecteLeveringBoeken(@MokGid, @MohkGid, @Boekdatum, @Stuknummer, @BoekgangGid, @JpGidOntvangst);
  end case;

  if not exists(Select 1 from tabJournaalpost where JpGid = @JpGidOntvangst) then
    set @JpGidOntvangst = null;
  end if;

  if @InkoopFactuurAanmaken = 1 then
    begin
      declare @IfkGid integer;
      call InkoopfactuurAanmakenObvMagazijnOntvangst(@MokGid, @InkoopFactuurBoeken /* Gelijk goedkeuren*/,  @IfkGid);

      if @InkoopFactuurBoeken = 1 then
        call BoekInkoopfactuur(null, null, @IfkGid, @Boekdatum, 1, null /*@DgbGid, indien leeg dan uit vaste gegevens*/, @Stuknummer,@BoekgangGid);
      end if;
    end
  end if;

  call BepaalBoekjaarEnPeriode(@MokOntvangstdatum, @BjGid, @PerNr);

  //boeken tegen VVP of werkelijke inkoopprijs(<>0 is werkelijke inkoopprijs)
  //Ophalen vaste gegevens
  select first MagVastOntvBoekenTegen into @MagVastOntvBoekenTegen from tabMagazijnOntvangstenVasteGegevens;

  //ACW 06-03-2009: project Directe inkoop; later nodig
  select first vofRegelDefNuFactureren,  vofFactIsArtikelRegelVerwijderen,  vofFactIsTariefRegelVerwijderen,  vofFactIsTekstRegelVerwijderen,  vofLevOokTarief,  vofLevOokTekst,  vofFactAutomVrijgeven
    into @vofRegelDefNuFactureren, @vofFactIsArtikelRegelVerwijderen, @vofFactIsTariefRegelVerwijderen, @vofFactIsTekstRegelVerwijderen, @vofLevOokTarief, @vofLevOokTekst, @vofFactAutomVrijgeven
    from tabVasteGegevensOrdersFactureren;

  //Standaard locatie van magazijn uit de kop ophalen
  case @MokSoort
  when 0 /*Mag.ontvangst*/ then
    select first LocGid
    into   @LocGid
    from   tabLocatie
    where  LocNaam = '(Standaard)' and LocMagGid = @MokMagGid;
    if @LocGid is null then
      insert into tabLocatie (LocMagGid, LocNaam) values (@MokMagGid, '(Standaard)');
      set @LocGid = @@Identity;
    end if;
  when 1 /*Directe levering*/ then
    // Enkele extra gegevens tbv. verwerken van de directe levering
    Select first vofIsStukskorting into @IsStuksKorting from tabVasteGegevensOrdersFactureren;
  end case;

  //set @@ErrorTextProcedure = @ErrText + '>Voorraad bijwerken' ;
  //call Trace(@@ErrorTextProcedure);

  // Lus op magazijnontvangstregels
  // Variabelen beginnend met @Cur worden in deze cursor gedeclareerd en gevuld
  FOR @Cursor AS CURSOR_MagOntRegels CURSOR FOR
    select
      MagOntGid @CurMagOntGid,
      MagOntArtPartijGid @CurMagOntArtPartijGid,
      MagOntArtGid @CurMagOntArtGid,
      BstKopNummer @CurBstKopNummer,
      if (@MagVastOntvBoekenTegen <> 0) then MagOntPrijsPer else ArtPrijsPer endif @CurMagOntPrijsPer,
      if (@MagVastOntvBoekenTegen <> 0) then
        //ACW 24-11-2008 bug 29711: Als tegen inkoopeenheid, dan de nettoprijs terugrekenen naar X voorraadeenheden
        //ACW 25-11-2008 bug 29711: Ook de nettoprijs i.p.v. de brutoprijs
        if MagOntInkoopprijsPer = 1 /*X voorr.eenh.*/ then
          round(MagOntInkoopprijs * if MagOntKortingSoort = 1 /*Kortingsperc.*/  then (100 - MagOntKortingPercentage) / 100 else 1 endif -
                                    if MagOntKortingSoort = 0 /*Kortingsbedrag*/ then MagOntKortingBedrag                   else 0 endif
               , ArtAantDecPrijzen)
        else /*inkoopeenheid*/
          round(round(MagOntInkoopprijs * if MagOntKortingSoort = 1 /*Kortingsperc.*/  then (100 - MagOntKortingPercentage) / 100 else 1 endif -
                                          if MagOntKortingSoort = 0 /*Kortingsbedrag*/ then MagOntKortingBedrag                   else 0 endif
                      , ArtAantDecPrijzen)
                * ArtPrijsPer / MagOntVoorraadEenhedenInInkoopEenheid
               , ArtAantDecPrijzen)
        endif
      else IsNull(ArtPartijKostprijsEx, ArtKostprijsEx) endif @CurPrijsInValuta,
      IsNull(ArtPartijKostprijsEx, ArtKostprijsEx) @CurArtKostprijsEx,
      ArtMutatieInkoopBijhouden @ArtMutatieInkoopBijhouden,
      ArtMutatieVerkoopBijhouden @ArtMutatieVerkoopBijhouden
    from
      tabMagazijnOntvangsten
      inner join tabArtikel on (ArtGid = MagOntArtGid) and (ArtSoort = 2)
      left outer join (tabBestelKop inner join tabBestelRegel on (BstRglBstKopGid = BstKopGid)) on (MagOntBstRglGid = BstRglGid)
      left outer join tabArtikelPartij on (ArtPartijGid = MagOntArtPartijGid)
    where  (MagOntMokGid = @MokGid)
      and  (MagOntAantal <> 0)
    order by MagOntRegelNr
  FOR READ ONLY
  DO
    //MR 28-jun-2023 Project Locaties Inkoopkant
    //Als er voor het artikel geen default locaties zijn gebruik dan de eerste in rij.
    call InvullenVoorkeursLocatieVanuitMagOntvangst(@CurMagOntGid);

    //*****************************************//
    //ACW 06-03-2009: project Directe inkoop

    //ACW 02-09-2010: Koppeling Magazijnontvangst<->verkooporder: Kan ook rechtstreeks aan de mag.ontv. zijn gekoppeld
    //TG 07-07-2016: Sum van MagOntLocAantal is nodig omdat je bij serienummers meerdere regels uit onderstaande query krijgt en het is ook geen probleem, want het totaal moet opgeteld worden in de orderregel (specificatieregels worden later per stuk toegevoegd).
    FOR @DirInkCursor AS CURSOR_DirInkMagOntRegelSpec CURSOR FOR
      select   sum(MagOntLocAantal)                as @MagOntLocAantal,
               IsNull(BrdOrrGid,  MagOntDetOrrGid) as @OrrGid
      from     tabMagazijnOntvangstLocatieSerie
               inner join tabMagazijnOntvangstenDetail on (MagOntDetGid = MagOntLocMagOntDetGid)
               left outer join tabBestelregelDetail on (BrdGid = MagOntDetBrdGid)
      where    MagOntDetMagOntGid = @CurMagOntGid and @OrrGid is not null /*Alleen records die aan orders gekoppeld zijn selecteren tbv directe inkoop*/
      group by @OrrGid
    FOR READ ONLY
    DO
      select OrrAantalVrrdEenhInVerkEenh, OrrAantalVrrdEenhInVerkEenhMagAfwijken, OrrAantDecAantal, OrrAantDecAantalVrrdEenh,
             OrrAantalLevering, OrrAantalLeveringVrrdEenh, OrrAantalGeleverd, OrrAantalGeleverdVrrdEenh, OrrAantalDezeFacturering, OrrAantalDezeFactureringVrrdEenh,
             OrrAantalNogTeFactureren
      into   @OrrAantalVrrdEenhInVerkEenh, @OrrAantalVrrdEenhInVerkEenhMagAfwijken, @OrrAantDecAantal, @OrrAantDecAantalVrrdEenh,
             @OrrAantalLevering, @OrrAantalLeveringVrrdEenh, @OrrAantalGeleverd, @OrrAantalGeleverdVrrdEenh, @OrrAantalDezeFacturering, @OrrAantalDezeFactureringVrrdEenh,
             @OrrAantalNogTeFactureren
      from   tabOrderregel
      where  OrrGid = @OrrGid;

      case @OrrAantalVrrdEenhInVerkEenhMagAfwijken
      when 0 then /*geen afwijkend aantal (vast aantal)*/
        case @MokSoort
        when 0 then /*Magazijnontvangst*/
          set @OrrAantalLeveringVrrdEenh = @OrrAantalLeveringVrrdEenh  + @MagOntLocAantal;
          set @OldOrrAantal              = @OrrAantalLevering; //oude waarde onthouden t.b.v. nu te factureren
          set @OrrAantalLevering         = Round(@OrrAantalLeveringVrrdEenh / @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantal);
          set @NewOrrAantal              = @OrrAantalLevering; //nieuwe waarde onthouden t.b.v. nu te factureren (zojuist hierboven berekend)
        when 1 then /*Directe levering*/
          set @OrrAantalGeleverdVrrdEenh = @OrrAantalGeleverdVrrdEenh + @MagOntLocAantal;
          set @OldOrrAantal              = @OrrAantalGeleverd; //oude waarde onthouden t.b.v. nu te factureren
          set @OrrAantalGeleverd         = Round(@OrrAantalGeleverdVrrdEenh / @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantal);
          set @NewOrrAantal              = @OrrAantalGeleverd; //nieuwe waarde onthouden t.b.v. nu te factureren (zojuist hierboven berekend)
        end;
      when 1 then /*afwijkend aantal bij aantal besteld*/
        case @MokSoort
        when 0 then /*Magazijnontvangst*/
          set @OldOrrAantal              = @OrrAantalLevering; //oude waarde onthouden t.b.v. nu te factureren
          set @OrrAantalLevering         = @OrrAantalLevering + TruncNum(@MagOntLocAantal / @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantal);
          set @NewOrrAantal              = @OrrAantalLevering; //nieuwe waarde onthouden t.b.v. nu te factureren (zojuist hierboven berekend)
          set @OrrAantalLeveringVrrdEenh = Round(@OrrAantalLevering * @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantalVrrdEenh);
        when 1 then /*Directe levering*/
          set @OldOrrAantal              = @OrrAantalGeleverd; //oude waarde onthouden t.b.v. nu te factureren
          set @OrrAantalGeleverd         = @OrrAantalGeleverd  + if @MokSoort = 1 /*Directe levering*/ then TruncNum(@MagOntLocAantal / @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantal) else 0 endif;
          set @NewOrrAantal              = @OrrAantalGeleverd; //nieuwe waarde onthouden t.b.v. nu te factureren (zojuist hierboven berekend)
          set @OrrAantalGeleverdVrrdEenh = Round(@OrrAantalGeleverd * @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantalVrrdEenh);
        end;
      when 2 then /*afwijkend aantal bij deze lev/fact*/
        begin
          declare @TmpAantalVerkEenh numeric(15,3);

          case @MokSoort
          when 0 then /*Magazijnontvangst*/
            set @OldOrrAantalVrrdEenh      = @OrrAantalLeveringVrrdEenh;
            set @OrrAantalLeveringVrrdEenh = @OrrAantalLeveringVrrdEenh  + @MagOntLocAantal;
            set @TmpAantalVerkEenh         = Round(@MagOntLocAantal / @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantal);

            if (@OrrAantalLeveringVrrdEenh <> 0) and (@TmpAantalVerkEenh = 0) then
              set @TmpAantalVerkEenh = sign(@OrrAantalLeveringVrrdEenh); //TG: 1 bij ontvangst, -1 bij negatieve ontvangst.
            end if;

            set @OldOrrAantal      = @OrrAantalLevering; //oude waarde onthouden t.b.v. nu te factureren
            set @OrrAantalLevering = @OrrAantalLevering + @TmpAantalVerkEenh;
            set @NewOrrAantal      = @OrrAantalLevering; //nieuwe waarde onthouden t.b.v. nu te factureren (zojuist hierboven berekend)

          when 1 then /*Directe levering*/
            set @OldOrrAantalVrrdEenh      = @OrrAantalGeleverdVrrdEenh;
            set @OrrAantalGeleverdVrrdEenh = @OrrAantalGeleverdVrrdEenh  + @MagOntLocAantal;
            set @TmpAantalVerkEenh         = Round(@MagOntLocAantal / @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantal);

            if (@OrrAantalGeleverdVrrdEenh <> 0) and (@TmpAantalVerkEenh = 0) then
              set @TmpAantalVerkEenh = sign(@OrrAantalGeleverdVrrdEenh); //TG: 1 bij ontvangst, -1 bij negatieve ontvangst.
            end if;

            set @OldOrrAantal      = @OrrAantalGeleverd; //oude waarde onthouden t.b.v. nu te factureren
            set @OrrAantalGeleverd = @OrrAantalGeleverd + @TmpAantalVerkEenh;
            set @NewOrrAantal      = @OrrAantalGeleverd; //nieuwe waarde onthouden t.b.v. nu te factureren (zojuist hierboven berekend)
          end;
        end;
      end; /*case*/

      if @vofRegelDefNuFactureren = 2 then
        //TG: als het aantal levering wijzigt en het aantal nu te factureren was gelijk aan aantal deze levering dan nu te factureren ook bijwerken
        if (@NewOrrAantal <> @OldOrrAantal) and (@OrrAantalDezeFacturering = @OldOrrAantal) then
          //TG: als we meer dreigen te factureren dan er gefactureerd zou moeten worden dan het te factureren deel factureren, en anders ophogen met het aantal van de levering
          if abs(@OrrAantalDezeFacturering + @NewOrrAantal) > abs(@OrrAantalDezeFacturering + @OrrAantalNogTeFactureren) then
            set @OrrAantalDezeFacturering = @OrrAantalDezeFacturering + @OrrAantalNogTeFactureren;
          else
            begin
              declare @VerschilAantal numeric(15,3);
              set @VerschilAantal           = @NewOrrAantal - @OldOrrAantal;
              set @OrrAantalDezeFacturering = @OrrAantalDezeFacturering + @VerschilAantal;
            end;
          end if;

          if @OrrAantalVrrdEenhInVerkEenhMagAfwijken in (0, 1) then /*TG: vast aantal of afwijkend aantal bij aantal besteld; afwijkend aantal bij deze lev/fact wordt later los uitgevoerd */
            set @OrrAantalDezeFactureringVrrdEenh = Round(@OrrAantalDezeFacturering * @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantalVrrdEenh);
          end if;
        end if;
      end if;

      //Aantallen aanpassen in orderregel a.g.v. verwerking van deze magazijnontvangstregel
      update tabOrderRegel
      set    OrrAantalLevering                = @OrrAantalLevering,
             OrrAantalLeveringVrrdEenh        = @OrrAantalLeveringVrrdEenh,
             OrrAantalGeleverd                = @OrrAantalGeleverd,
             OrrAantalGeleverdVrrdEenh        = @OrrAantalGeleverdVrrdEenh,
             OrrAantalDezeFacturering         = @OrrAantalDezeFacturering,
             OrrAantalDezeFactureringVrrdEenh = @OrrAantalDezeFactureringVrrdEenh
      where  OrrGid = @OrrGid;

       //TG: deze facturering in voorraadeenheden bij afwijkend aantal bij deze lev/fact wordt pas na de update aangepast, zodat trigger van tabOrderregel alvast aantal backorder en nog te factureren aangepast heeft.
       if @vofRegelDefNuFactureren = 2 then /* 2 = aantal deze levering */
         if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2 then /*afwijkend aantal bij deze lev/fact*/
          update tabOrderregel
          set    OrrAantalDezeFactureringVrrdEenh = (if (OrrRegelsoort = 2) /*artikelregel*/ and (OrrAantalBackorder = 0) /* LeveringIsCompleet */ and (OrrAantalNogTeFactureren = 0) then /* GeenVerkeenhLaterTefactureren */
                                                      OrrAantalLeveringVrrdEenh + OrrAantalGeleverdVrrdEenh - OrrAantalGefactureerdVrrdEenh
                                                    else
                                                      if (OrrAantalDezeFactureringVrrdEenh = @OldOrrAantalVrrdEenh) then
                                                        @OrrAantalLeveringVrrdEenh
                                                      else
                                                        OrrAantalDezeFactureringVrrdEenh
                                                      end if
                                                    end if)
          where OrrGid = @OrrGid and ((OrrAantalNogTeFactureren = 0) /* GeenVerkeenhLaterTefactureren */ or (OrrAantalDezeFactureringVrrdEenh = @OldOrrAantalVrrdEenh)); /*AantalDezeFactIsAantalDezeLev*/
        end if;
      end if;
    end for;

    //ACW 04-05-2010: bug 32565 NIET de specificatieregel aanpassen als niet minstens 1 van de modules MeerdeMagazijnen, partijen en serienummers actief is
    //ACW 10-09-2010: Uitbreiding DL: Specificatieregels alleen aanpassen als het een magazijnontvangst betreft
    if @MokSoort = 0 /*MagazijnOntvangst*/ and (IsOrderSpecificatieregelActief() = 1) then

      // In de orderregelspecificatieregels ook gelijk wat zetten
      // Per mag.ontv.specregel doorlopen; (hieronder evt. partij mee laten zoeken)
      //  - als serienummer, dan serienummer in order opzoeken; gevonden, dan aantal updaten
      //  - als geen serienummer, dan magazijn in order opzoeken; gevonden, dan aantal updaten,
      //  - anders nieuwe detailregel
      FOR @specCursor AS CURSOR_MagOntRegelSpec CURSOR FOR
        select  OrrGid                                  @CurOrrGid,
                OrrArtGid                               @CurOrrArtGid,
                OrrVkeGid                               @CurOrrVkeGid,
                OrrAantalVrrdEenhInVerkEenh             @CurOrrAantalVrrdEenhInVerkEenh,
                OrrAantalVrrdEenhInVerkEenhMagAfwijken  @CurOrrAantalVrrdEenhInVerkEenhMagAfwijken,
                OrrAantDecAantal                        @CurOrrAantDecAantal,
                OrrAantDecAantalVrrdEenh                @CurOrrAantDecAantalVrrdEenh,
                MagOntLocAantal                         @CurMagOntLocAantalVrrdEenh,
                MagOntLocAantal                         @CurMagOntLocAantalVerkEenh, //TG: LET OP: dit veld wordt gevuld in de code hieronder en is hier alleen opgenomen als variabele declaratie.
                MagOntLocLocGid                         @CurMagOntLocLocGid,
                MagOntLocArtSerieGid                    @CurMagOntLocArtSerieGid
        from   tabMagazijnOntvangstenDetail
               inner join tabMagazijnOntvangstLocatieSerie on (MagOntLocMagOntDetGid = MagOntDetGid)
               //ACW 02-09-2010: Koppeling Magazijnontvangst<->verkooporder: Kan ook rechtstreeks aan de mag.ontv. zijn gekoppeld
               left outer join tabBestelregelDetail on (BrdGid = MagOntDetBrdGid)
               inner join tabOrderRegel on (OrrGid = isnull(brdOrrGid, MagOntDetOrrGid))
               inner join tabOrderKop on (Orkgid = OrrOrkGid)
        where  MagOntDetMagOntGid = @CurMagOntGid
      for read only
      do
        begin
          declare @TmpMagOntLocAantalVerkEenh numeric(15,3);
          declare @TmpMagOntLocAantalVrrdEenh numeric(15,3);

          case @CurOrrAantalVrrdEenhInVerkEenhMagAfwijken
          when 0 then /*geen afwijkend aantal (vast aantal)*/
            //stap 1/3: voorraadeenheden omrekenen naar verkoopeenheden en afronden volgens aantal decimalen van verkoopeenheid.
            set @TmpMagOntLocAantalVerkEenh = Round(@CurMagOntLocAantalVrrdEenh / @CurOrrAantalVrrdEenhInVerkEenh, @CurOrrAantDecAantal);
            //stap 2/3: afgerond berekend aantal verkoopeenheden weer terugrekenen  naar voorraadeenheden en afronden volgens aantal decimalen van voorraadeenheid.
            set @TmpMagOntLocAantalVrrdEenh = Round(@TmpMagOntLocAantalVerkEenh * @CurOrrAantalVrrdEenhInVerkEenh, @CurOrrAantDecAantalVrrdEenh);
            //stap 3/3: als het aantal afgeronde verkoopeenheden terug omgerekend naar voorraadeenheden gelijk is aan het originele aantal voorraadeenheden dan is het een geldige hoeveelheid
            //          voor de verkoopeenheid en mag deze worden ingevuld. Zo niet, dan vullen we de voorraadeenheid in en is het aantal verkoopeenheden gelijk aan het aantal voorraadeenheden.
            if (@CurMagOntLocAantalVrrdEenh = @TmpMagOntLocAantalVrrdEenh) then
              set @CurMagOntLocAantalVerkEenh = @TmpMagOntLocAantalVerkEenh;
            else
              set @CurOrrVkeGid = (select first VkeGid from tabVerkoopEenheid where VkeArtGid = @CurOrrArtGid and VkeIsVoorraadEenheid = 1);
              set @CurMagOntLocAantalVerkEenh = @CurMagOntLocAantalVrrdEenh;
            end if;
          when 1 then /*afwijkend aantal bij aantal besteld*/
            set @CurMagOntLocAantalVerkEenh = TruncNum(@CurMagOntLocAantalVrrdEenh / @CurOrrAantalVrrdEenhInVerkEenh, @CurOrrAantDecAantal);
            set @CurMagOntLocAantalVrrdEenh = Round(@CurMagOntLocAantalVerkEenh * @CurOrrAantalVrrdEenhInVerkEenh, @CurOrrAantDecAantalVrrdEenh);
          when 2 then /*afwijkend aantal bij deze lev/fact*/
            set @CurMagOntLocAantalVerkEenh = Round(@CurMagOntLocAantalVrrdEenh / @OrrAantalVrrdEenhInVerkEenh, @OrrAantDecAantal);

            if (@CurMagOntLocAantalVrrdEenh <> 0) and (@CurMagOntLocAantalVerkEenh = 0) then
              set @CurMagOntLocAantalVerkEenh = sign(@CurMagOntLocAantalVrrdEenh); //TG: 1 bij ontvangst, -1 bij negatieve ontvangst.
            end if;
          end; /*case*/
        end; /*begin*/

        //ACW 27-10-2009: Als er geen locatie is ingegeven in de spec.regel, dan alsnog de default in het magazijn gebruiken
        if @CurMagOntLocLocGid is null then
          // Default locatie van artikel in magazijn
          select ArtMagDefaultLocGid into @CurMagOntLocLocGid from tabartikelmagazijn where ArtMagArtGid = @CurMagOntArtGid and ArtMagMagGid = @MokMagGid;
          if @CurMagOntLocLocGid is null then
            // Nog geen default locatie in magazijn? -> pak default locatie in magazijn
            set @CurMagOntLocLocGid = @LocGid;
          end if;
        end if;

        begin
          declare @DoInsert       bit     = 0;    //inserten of updaten?
          declare @SerienummerGid integer = null; //evt. in te vullen serienummergidje bij insert.

          //TG: toevoegen van een regel met een serienummer is alleen toegestaan als er nog geen specificatieregel is met dat serienummer. komt het serienummer wel voor
          //    in de specificatieregel, dan inserten we een regel zonder serienummer zodat het aantal specificatieregels iig overeenkomt met het aantal in de orderregel.
          if (@CurMagOntLocArtSerieGid is not null) then
            set @DoInsert = 1; //als er een serienummer is ingevuld, dan moet het altijd een nieuwe regel worden.
            //als er nog geen regel bestaat met dit serienummer bestaat dan mag de regel toegevoegd worden met het serienummer. Komt het serienummer al wel voor, dan inserten we een regel zonder serienummer (zodat het totaal aantal van spec.regels overeenkomt met het aantal in de orderregel).
            if not exists(select first 1 from tabOrderRegelLocatie where OrlOrrGid = @CurOrrGid and OrlArtSerieGid = @CurMagOntLocArtSerieGid) then
               set @SerienummerGid = @CurMagOntLocArtSerieGid;
            end if;
          end if;

          if (@DoInsert = 0) then
            // Zoek een orderspecificatieregel zonder serienummer waarbij verkoopeenheid, partijnummer (indien opgegeven in magazijnontvangst, anders zoeken naar regel zonder partij), magazijn en locatie overeenkomen.
            set @OrlGid = null; // ACW 07-02-2019: Als niks is gevonden, dan blijft de oude waarde erin staan! Dat mag dus niet
            select first OrlGid
            into   @OrlGid
            from   tabOrderRegelLocatie
            where  OrlOrrGid                   = @CurOrrGid
               and OrlVkeGid                   = @CurOrrVkeGid
               and OrlMagGid                   = @MokMagGid
               and OrlLocGid                   = @CurMagOntLocLocGid
               and isnull(OrlArtPartijGid, -1) = isnull(@CurMagOntArtPartijGid, -1)
               and OrlArtSerieGid is null;

            if @OrlGid is null then
              set @DoInsert = 1;
            end if;
          end if;

          if (@DoInsert = 1) then
           insert into tabOrderRegelLocatie with auto name
           select
             @CurOrrGid                   as OrlOrrGid,
             @MokMagGid                   as OrlMagGid,
             @CurMagOntLocLocGid          as OrlLocGid,
             @CurMagOntArtPartijGid       as OrlArtPartijGid,
             @SerienummerGid              as OrlArtSerieGid,
             @CurOrrVkeGid                as OrlVkeGid,
             @CurOrrAantDecAantal         as OrlAantDecAantal,
             @CurOrrAantDecAantalVrrdEenh as OrlAantDecAantalVrrdEenh,
             @CurMagOntLocAantalVerkEenh  as OrlDezeLevering,
             @CurMagOntLocAantalVrrdEenh  as OrlDezeLeveringVrrdEenh;
          else
            update tabOrderRegelLocatie
            set    OrlDezeLevering         = OrlDezeLevering + @CurMagOntLocAantalVerkEenh,
                   OrlDezeLeveringVrrdEenh = OrlDezeLeveringVrrdEenh + @CurMagOntLocAantalVrrdEenh,
                   OrlMagGid               = @MokMagGid,
                   OrlLocGid               = @CurMagOntLocLocGid
            where  OrlGid = @OrlGid;
          end if;
        end;
      end for;
    end if; //Controle op modules/DirecteLevering

    //eind ACW 06-03-2009: project Directe inkoop
    //****************************************

    if @ArtMutatieInkoopBijhouden <> 0 then

      // Magazijnontvangstregel van deze ontvangst in voorraadmutatie toevoegen
      //set @@ErrorTextProcedure = @ErrText + '> Magazijnontvangstregel (@MagOntGid='+string(@CurMagOntGid)+') > Toevoegen aan tabVoorraadmutatie';
      //call Trace(@@ErrorTextProcedure);

      insert into tabVoorraadMutatie
             (vrdMutArtGid,              vrdMutNawGid,         vrdMutDatum,          vrdMutSoort,
              vrdMutUitleverOntvangstNr, vrdMutOrderBestelNr,  vrdMutValNummer,      vrdMutGeprijsdPer,
              vrdMutPrijsInValuta,       vrdMutHistKostprijs,  vrdMutGebruikerCode,  vrdMutJpGid,
              VrdMutDirLevKenmerk)
      values( @CurMagOntArtGid,          @MokNawGid,           @MokOntvangstDatum,   if @MokSoort = 0 /*Magazijnontvangst*/ then 0 else 11 /*DirLev Leverancier*/ endif,
              @MokNummer,                @CurBstKopNummer,     @MokValNummer,        @CurMagOntPrijsPer,
              @CurPrijsInValuta,         @CurArtKostprijsEx,   @@GebruikerCode,      @JpGidOntvangst,
              @DirLevKenmerk);

      //set @@ErrorTextProcedure = @ErrText + '> Magazijnontvangstregel (@MagOntGid='+string(@CurMagOntGid)+') > Toevoegen aan tabVoorraadmutatieLocatieSerie (Inkoop)';
      //call Trace(@@ErrorTextProcedure);
      // Magazijnontvangstregellocaties van deze magazijnontvangstregel in voorraadmutatie toevoegen
      insert into tabVoorraadMutatieLocatieSerie(VrdMutLocVrdMutGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer, VrdMutLocAantal)
      select @@Identity, IsNull(MagOntLocLocGid, @LocGid), ArtPartijNummer, ArtSerienummer, MagOntLocAantal
      from   tabMagazijnOntvangstenDetail
             inner join tabMagazijnOntvangstLocatieSerie on (MagOntLocMagOntDetGid = MagOntDetGid)
             left outer join tabArtikelPartij on (ArtPartijGid = @CurMagOntArtPartijGid)
             left outer join tabArtikelSerienummer on (ArtSerieGid = MagOntLocArtSerieGid)
      where  MagOntDetMagOntGid = @CurMagOntGid;
    end if;

    // Naast de 'ontvangst' van de leverancier ook de 'levering' aan de klant in de mutaties zetten. Dit is per verkooporder, die dus in de spec.regels apart staan!!
    if @MokSoort = 1 /*Directe levering*/ and @ArtMutatieVerkoopBijhouden <> 0 then
      for @VerkoopOrderRegelCursor AS CURSOR_VerkoopOrderRegel CURSOR FOR
        select MagOntDetGid @CurMagOntDetGid,
               OrkNummer    @CurOrkNummer,
               OrkValNummer @CurOrkValNummer,
               OrkNawGid    @CurOrkNawGid,
               OrrPrijsPer  @CurOrrPrijsPer,
               //ACW 17-12-2010 Incident #04816: Berekening overgenomen vanuit OrderLeveren

               Round((if (OrkInclBtw = 1) then
                       (if @IsStuksKorting = 1 then
                          //Stukskorting -> bereken via aantal-korting1-korting2
                          if (OrrIsKortingsPercentage = 0) then //Kortingsbedrag
                            ((OrrBrutoVerkoopPrijs - OrrRegelKorting1) * ((100 - OrrRegelKorting2) / 100))
                          else //Kortingspercentage
                            (OrrBrutoVerkoopPrijs * ((100 - OrrRegelKorting1) / 100) * ((100 - OrrRegelKorting2 ) / 100))
                          endif
                        else
                          //Regelkorting -> bereken via regeltotaal/aantal besteld
                          (OrrRegelTotaal / OrrAantalBesteld * OrrPrijsPer)
                        endif) / ( 100 + BtwPercentage) * 100
                      else
                       (if @IsStuksKorting = 1 then
                          //Stukskorting -> bereken via aantal-korting1-korting2
                          if (OrrIsKortingsPercentage = 0) then //Kortingsbedrag
                            ((OrrBrutoVerkoopPrijs - OrrRegelKorting1) * ((100 - OrrRegelKorting2) / 100))
                          else //Kortingspercentage
                            (OrrBrutoVerkoopPrijs * ((100 - OrrRegelKorting1) / 100) * ((100 - OrrRegelKorting2 ) / 100))
                          endif
                        else
                          //Regelkorting -> bereken via regeltotaal/aantalbesteld
                          (OrrRegelTotaal / OrrAantalBesteld * OrrPrijsPer)
                        endif)
                      endif), OrrAantDecBedrag)  @PrijsRegelInValuta,
                      if OrrEenheidPrijsPer = 0 /*VerkoopEenheid*/ then
                        Round(@PrijsRegelInValuta * OrrPrijsPer / OrrAantalVrrdEenhInVerkEenh, OrrAantDecBedrag)
                      else
                        Round(@PrijsRegelInValuta, OrrAantDecBedrag)
                      endif @PrijsInValuta
        from   tabMagazijnOntvangstenDetail
               left outer join tabBestelRegelDetail on (brdGid  = MagOntDetbrdGid)
               inner join tabOrderRegel             on (OrrGid  = isnull(brdOrrGid, MagOntDetOrrGid))
               inner join tabOrderKop               on (OrkGid  = OrrOrkGid)
               left outer join tabBTW               on (BtwCode = OrrBtwCode)
               inner join tabNaw on (NawGid = OrkNawGid)
        where  MagOntDetMagOntGid = @CurMagOntGid
      FOR READ ONLY
      DO
        insert into tabVoorraadMutatie
               (vrdMutArtGid,              vrdMutNawGid,         vrdMutDatum,          vrdMutSoort,
                vrdMutUitleverOntvangstNr, vrdMutOrderBestelNr,  vrdMutValNummer,      vrdMutGeprijsdPer,
                vrdMutPrijsInValuta,       vrdMutHistKostprijs,  vrdMutGebruikerCode,  vrdMutJpGid,
                VrdMutDirLevKenmerk)
        values( @CurMagOntArtGid,          @CurOrkNawGid,        @MokOntvangstDatum,   12 /*DirLev Debiteur*/,
                @MokNummer,                @CurOrkNummer,        @CurOrkValNummer,     @CurOrrPrijsPer,
                @PrijsInValuta,            @CurArtKostprijsEx,   @@GebruikerCode,      @JpGidOntvangst,
                @DirLevKenmerk);

        //set @@ErrorTextProcedure = @ErrText + '> Directe leverregel (@MagOntGid='+string(@CurMagOntGid)+', @CurOrkNummer=' + string(@CurOrkNummer)+') > Toevoegen aan tabVoorraadmutatieLocatieSerie (levering)';
        //call Trace(@@ErrorTextProcedure);
        // Magazijnontvangstregellocaties van deze magazijnontvangstregel in voorraadmutatie toevoegen
        //ACW 10-09-2010: Alleen de specificatieregels van de betreffende verkooporder toevoegen!
        insert into tabVoorraadMutatieLocatieSerie(VrdMutLocVrdMutGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer, VrdMutLocAantal)
        select @@Identity, IsNull(MagOntLocLocGid, @LocGid), ArtPartijNummer, ArtSerienummer, -MagOntLocAantal
        from   tabMagazijnOntvangstenDetail
               inner join tabMagazijnOntvangstLocatieSerie on (MagOntLocMagOntDetGid = MagOntDetGid)
               left outer join tabArtikelPartij on (ArtPartijGid = @CurMagOntArtPartijGid)
               left outer join tabArtikelSerienummer on (ArtSerieGid = MagOntLocArtSerieGid)
        where  MagOntDetGid = @CurMagOntDetGid;
      END FOR;
    end if;

  END FOR; // CURSOR_MagOntRegels

  //ACW 17-01-2012: Tabel vullen nu voor de magazijnontvangsten, zodat die het ook kan gebruiken
  //Alle orderregels (en -koppen) onthouden die in deze magazijnontvangst van toepassing zijn (direct of via bestelregels)
  insert into tmpOrderKopEnRegels(tmpOrkGid, tmpOrrGid)
    select   DISTINCT OrrOrkGid, OrrGid
    from     tabMagazijnOntvangsten
             inner      join tabMagazijnOntvangstenDetail on (MagOntDetMagOntGid = MagOntGid)
             left outer join tabBestelRegelDetail         on (BrdGid             = MagOntDetBrdGid)
             inner      join tabOrderRegel                on (OrrGid             = isnull(BrdOrrGid, MagOntDetOrrGid))
    where    MagOntMokGid = @MokGid;

  //RVL 17-03-2009 : Controleren of de aantallen in de specificatieregels overeenkomen met de orderregels. Zo niet, dan het vinkje "Vrijgegeven voor levering" weghalen
  //ACW 10-09-2010: Is niet van toepassing voor Directe Levering!
  if @MokSoort = 0 /*MagazijnOntvangst*/ then
    update tabOrderKop set OrkVrijVoorLevering = 0
    where  OrkVrijVoorLevering = 1
       and OrkGid in (select OrrOrkGid
                      from tmpOrderKopEnRegels
                           inner join taborderregel on (OrrGid = tmpOrrGid)
                           inner join tabOrderRegelLocatie on (OrlOrrGid = OrrGid)
                      group by OrrGid, orrOrkGid, OrrAantalLevering
                      having   Isnull(sum(OrlDezeLevering),0) <> OrrAantalLevering
                     );
  end if;

  //bijwerken serienummers(als ingevuld): InOntvangst -1, Ontvangen +1, bij negatief aantal precies andersom. Aantal is altijd 1 of -1 bij serienummers
  //InOntvangst wordt bijgewerkt door delete trigger van tabMagazijnOntvangstLocatieSerie(ontvangstregels  worden verwijderd na      het verwerken)
  //Ontvangen   wordt bijgewerkt door insert trigger van tabVoorraadMutatieLocatieSerie  (voorraadmutaties worden aangemaakt tijdens het verwerken)

  //set @@ErrorTextProcedure = @ErrText + '>invullen ontvangstdatum bij de partij' ;
  //call Trace(@@ErrorTextProcedure);

  update  tabartikelpartij
  set     ArtPartijDatumOntvangst = if (ArtPartijDatumOntvangst is null) or (MokOntvangstDatum < ArtPartijDatumOntvangst) then MokOntvangstDatum else ArtPartijDatumOntvangst endif
  from    tabMagazijnOntvangsten
             inner join tabMagazijnOntvangstenKop on (MokGid = MagOntMokGid)
  where   (MokGid = @MokGid) and (MagOntArtPartijGid = ArtPartijGid);

  //set @@ErrorTextProcedure = @ErrText + '>CBS tabel vullen';
  //call Trace(@@ErrorTextProcedure);
  //Cbs gegevens vullen
  //-alleen als optie cbs er is
  //-alleen als land herkomst verschilt van eigenlandcode en (Eu land of extrahandel)
  //-negatieve aantallen(dus maatstaf, gewicht, factuurwaarde) zijn toegestaan, transactie en goederenstroom niet veranderen
  //-kostprijs of werkelijke inkoopprijs als factuurwaarde(let op: bij VVP is de prijs niet in de magontregel ingevuld)
  //-regel skippen als factuurwaarde 0 is ? --> gewoon exporteren, in iris dan vanzelf een melding
  //-eventueel melding in programma als factuurwaarde nul is : import in iris ok als transactiecode op 3 staat(gratis levering)
  //-voor verwerken wordt er een check in programma gedaan of het Btw nummer van de leverancier niet meer dan 14 karakters bevat(veld is begrenst op 15)

  select DefaultLndGid into @LndGidEigenLand from tabVasteGegevens;
  select LndIsEGLid    into @LndIsEGLid      from tabLand where LndGid = @MokCbsLndGidHerkomst;
  if ((select IsModuleActive('c1')) <> 0) and (@CbsVastNaarCbsIrisInvoer <> 0) and (@CbsMeenemenInAangifte <> 0) then
    insert into tabCbsAangifteExport
           (CbsAeOrderOfMagOntv,                                                                    //Algemeen
            CbsAeAdministratieNr, CbsAeTransactiePeriode, CbsAeHandelsPartner,                      //Magazijnkop
            CbsAeCbsGsGid, CbsAeCbsSsGid, CbsAeLandBestHerk, CbsPtnGid, CbsAeCbsVwGid,              //Magazijnkop, Cbs
            CbsAeCbsCoGid,                                                                          //Magazijnkop, Cbs, Extra handel
            CbsAeCbsGcGid, CbsAeEigenGoederencode, CbsAeMaatstaf, CbsAeGewicht, CbsAeFactuurWaarde, //Magontregel, Artikelgegevens
            CbsAeCbsTrGid,                                                                          //MagOntRegel, Cbs
            CbsAeLandOorsprong, CbsAeTaric, CbsAePreferentie,                                       //MagOntRegel, Cbs, Extra handel
            CbsAeLeveringscode,                                                                     //MagazijnKop, Leveringsconditie
            CbsAeDouaneregeling,                                                                    //MagazijnRegel, douaneregeling
            CbsAeReedsVerstuurd)                                                                    //bij inserten altijd 0
    select  0,
            @MokNummer, @MokOntvangstDatum, trim(nawBtwNummer),
            MokCbsGsGid, MokCbsSsGid, (select LndIso3 from tabLand where LndGid = MokCbsLndGidHerkomst), MokCbsPtnGidVerkeersGebied, MokCbsVwGid,
            MokCbsCoGid,
            ArtCbsGcGid, ArtCode,
            if IsNull(ArtCbsMaatstaf,0)=0 then
              null
            else
              round(MagOntAantal * ArtCbsMaatstaf,0)
            endif,//King eenheid omrekenen naar cbs eenheid(maatstaf), alleen als omrekenfactor bij artikel is ingevuld
            if (MagOntAantal > 0) and round(MagOntAantal * (ArtGewicht/ArtGewichtPer),0) = 0 then
              1
            else
              round(MagOntAantal * (ArtGewicht/ArtGewichtPer),0)
            endif,//bij positieve aantallen: gewicht is 1 of meer
            if (@MagVastOntvBoekenTegen <> 0) then
               ValutaOmrekenen(@MokValNummer,
                 case MagOntInkoopprijsPer
                 when 0 /*Inkoopeenheid*/ then
                   (MagOntAantalInkoopEenheden * MagOntInkoopprijs) -       /*brutobedrag - */
                   if MagOntKortingSoort = 0 /*kortingsbedrag*/ then
                     round(MagOntAantalInkoopEenheden * MagOntKortingBedrag, ArtAantDecPrijzen) /*eenheidskorting*/
                   else
                     0
                   endif
                 when 1 /*X voorraadeenheden*/ then
                   if MagOntPrijsPer = 0 then
                     0
                   else
                     (MagOntAantal * MagOntInkoopprijs / MagOntPrijsPer)- /*Brutobedrag - */
                     if MagOntKortingSoort = 0 /*kortingsbedrag*/ then
                       round((MagOntAantal / MagOntPrijsPer) * MagOntKortingBedrag, ArtAantDecPrijzen) /*eenheidskorting*/
                     else
                       0
                     endif
                   endif
                 end
                 * if MagOntKortingSoort = 1 /*kortingspercentage*/ then
                   (100 - MagOntKortingPercentage) / 100
                   else
                   1 endif,
                @EuroValNummer, @BjGid, @Pernr, 0)
            else
              if ArtPrijsPer = 0 then
                0
              else
                ValutaOmrekenen(@MokValNummer, if ArtPrijsPer = 0 then 0 else (MagOntAantal * IsNull(ArtPartijKostprijsEx, ArtKostprijsEx))/ArtPrijsPer endif, @EuroValNummer, @BjGid, @Pernr, 0)
              endif
            endif,//Altijd in euros, als bedrag nul is, dan zal Iris bij importeren eventueel een melding geven
            MagOntCbsTrGid,
            (select LndIso3 from tabLand where LndGid = MagOntCbsLndGidOorsprong), MagOntCbsTaric, MagOntCbsPreferentieCode,
            (Select LvcCode from tabLeveringsconditie where LvcNummer = MokLvcNummer),
            MagOntCbsDouaneregeling,
            0
    from    tabMagazijnOntvangsten inner join tabMagazijnOntvangstenKop on (MokGid = MagOntMokGid)
                                   inner join tabArtikel on (ArtGid = MagOntArtGid) and (ArtSoort = 2)
                                   left outer join tabNaw on(NawGid = MokNawGid)
                                   left outer join tabArtikelPartij on (ArtPartijGid = MagOntArtPartijGid)
    where   MokGid = @MokGid
  end if;

  //ACW 13-09-2010: Uitbreiding DL: Vullen historische tabellen EN opschonen volledig verwerkte orderregels
  if @MokSoort = 1 /*Directe levering */ then
    call DirecteLeveringVulHistorischeTabellen(@MokGid, @Boekdatum, @Stuknummer, @BoekgangGid, @JpGidOntvangst, @RapNummer, @FbGid);

    // Na afloop de verkooporders verwijderen als deze volledig zijn verwerkt (geleverd+gefactureerd)
    // en het staat zo in de vaste gegevens aangegeven
    delete tabOrderRegel
    from   tmpOrderKopEnRegels
    where  (OrrGid = tmpOrrGid)
       and (( //Tekstregel: IsGefactureerd and (IsGeleverd or not TekstOokLeveren)
            (OrrRegelSoort = 0 and
              ((@vofFactIsTekstRegelVerwijderen = 1 and OrrAantalGefactureerd <> 0 and OrrAantalGefactureerdVrrdEenh <> 0) or //IsWeg=Na fact. *en* de regel is gefactureerd
               (@vofFactIsTekstRegelVerwijderen = 2 and OrrAantalGeleverd     <> 0 and OrrAantalGeleverdVrrdEenh     <> 0) or  //IsWeg=Na lev. *en* de regel is geleverd
               (@vofFactIsTekstRegelVerwijderen = 3 and OrrAantalGefactureerd <> 0 and OrrAantalGefactureerdVrrdEenh <> 0 and ((isnull(OrrAantalGeleverd,0)<>0 and isnull(OrrAantalGeleverdVrrdEenh,0)<>0) or @vofLevOokTekst = 0))      //IsWeg=Na fact.+lev. *en* de regel is gefactureerd *en* geleverd
              )
            ) or
             //Tariefregel: Aantal gefact.=aantal besteld and (aantal gelev.<>0 or not TariefOokLeveren) and not TariefWegNaVolledigFactLever
            (OrrRegelSoort = 1 and
              ((@vofFactIsTariefRegelVerwijderen = 1 and OrrAantalGefactureerd = OrrAantalBesteld and OrrAantalGefactureerdVrrdEenh = OrrAantalBesteldVrrdEenh) or  //IsWeg=Na factureren *en* er is evenveel gefactureerd als besteld
               (@vofFactIsTariefRegelVerwijderen = 3 and OrrAantalGefactureerd = OrrAantalBesteld and OrrAantalGefactureerdVrrdEenh = OrrAantalBesteldVrrdEenh and ((OrrAantalGeleverd <> 0 and OrrAantalGeleverdVrrdEenh <> 0) or @vofLevOokTarief = 0)) //IsWeg=Na fact+lev. *en* er is evenveel gefact. als besteld *en* er is geleverd (of tarieven worden niet geleverd)
              )
            ) or
             //Artikelregel: Aantal gefact.=aantal gelev.=aantal besteld and not ArtikelWeg
            (OrrRegelSoort = 2 and
              @vofFactIsArtikelRegelVerwijderen = 3 and
              (
                ( //Aantal mag niet afwijken (vast aantal)
                  (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0) and
                  (OrrAantalGeleverdVrrdEenh = OrrAantalGefactureerdVrrdEenh) and (OrrAantalGefactureerdVrrdEenh = OrrAantalBesteldVrrdEenh)
                ) or
                ( //Aantal mag afwijken bij Aantal besteld
                  (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1) and
                  (OrrAantalGeleverd = OrrAantalGefactureerd) and (OrrAantalGefactureerd = OrrAantalBesteld)
                ) or
                ( //Aantal mag afwijken bij Levering/Facturering
                  (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2) and
                  (OrrAantalGeleverd = OrrAantalGefactureerd) and (OrrAantalGefactureerd = OrrAantalBesteld) and
                  (OrrAantalGeleverdVrrdEenh = OrrAantalGefactureerdVrrdEenh)
                )
              )
            )
           )
          );


    // De verkooporders die inmiddels helemaal klaar zijn (dus geen nog te factureren of nog te leveren hebben) ook verwijderen
    delete tabOrderKop
    from   tmpOrderKopEnRegels
    where  OrkGid = tmpOrkGid
       // WAS: and (not exists(select first 1 from tabOrderRegel where OrrOrkGid = tmpOrkGid and (OrrAantalGefactureerd <> OrrAantalBesteld or OrrAantalGeleverd <> OrrAantalBesteld)));
       and (not exists(select first 1 from tabOrderRegel where OrrOrkGid = tmpOrkGid and
                                    (
                                      //Tariefregel
                                     (OrrRegelSoort = 1 and
                                      (OrrAantalGefactureerd <> OrrAantalBesteld) and
                                      (OrrAantalGefactureerdVrrdEenh <> OrrAantalBesteldVrrdEenh)
                                     ) or
                                      //Artikelregel: Aantal gefact.<>aantal gelev.<>aantal besteld
                                     (OrrRegelSoort = 2 and
                                      (
                                        ( /*Aantal mag niet afwijken (vast aantal)*/
                                          (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0) and
                                          not ((OrrAantalGeleverdVrrdEenh = OrrAantalGefactureerdVrrdEenh) and (OrrAantalGefactureerdVrrdEenh = OrrAantalBesteldVrrdEenh))
                                        ) or
                                        ( /*Aantal mag afwijken bij Aantal besteld*/
                                          (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1) and
                                          not ((OrrAantalGeleverd = OrrAantalGefactureerd) and (OrrAantalGefactureerd = OrrAantalBesteld))
                                        ) or
                                        ( /*Aantal mag afwijken bij Levering/Facturering*/
                                          (OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2) and
                                          not ((OrrAantalGeleverd = OrrAantalGefactureerd) and (OrrAantalGefactureerd = OrrAantalBesteld) and
                                               (OrrAantalGeleverdVrrdEenh = OrrAantalGefactureerdVrrdEenh)
                                              )
                                        )
                                      )
                                     )
                                    )
                      )
          );


    // Als in vaste gegevens facturering staat dat de order wordt vrijgegeven voor facturering na 1e (deel)levering, dan dat doen
    // Ook gelijk de eerste actie van die orders aanpassen
    update tabOrderKop
    set    OrkVrijVoorFaktureren = if @vofFactAutomVrijgeven = 3 /*na 1e levering*/ then 1 else OrkVrijVoorFaktureren endif,
           OrkEersteActie = 2 /*Geleverd*/
    where  OrkGid in (select tmpOrkGid from tmpOrderKopEnRegels)
       and OrkEersteActie = 0 /*Geen eerdere actie*/;

    // In de verkooporders van deze batch aangeven dat de DL-pakbon is afgedrukt
    FOR @CursorDocBijwerken AS CURSOR_OrderDocBijwerken CURSOR FOR
    select tmpOrkGid @OrkGid
    from   tmpOrderKopEnRegels
           // Hierboven kon de verkooporder al zijn verwijderd als die al volledig was gefactureerd!
           // Daarom ook testen of die nog wel bestaat
           inner join tabOrderKop on (OrkGid = tmpOrkGid)
    FOR READ ONLY
    DO
      //De niet-bestaande statussen aanmaken
      if not exists( select 1 from tabOrderDocGegevens where OrdDocOrkGid = @OrkGid and OrdDocDocSoort = 35 /*DL-pakbon*/ ) then
        insert into tabOrderDocGegevens(OrdDocDocSoort, OrdDocOrkGid, OrdDocGegAfgedrukt, OrdDocGegAfgedruktOp, OrdDocAfgedruktDoor, OrdDocGegGewijzigdNaAfdruk, OrdDocGewijzigdDoor, OrdDocLaatstGebruiktNr )
        values(35 /*DL-pakbon*/, @OrkGid, 1, now(), @@Gebruikercode, 0, '', @MokNummer)
      else
        update tabOrderDocGegevens
        set    OrdDocGegAfgedrukt     = 1,
               OrdDocGegAfgedruktOp   = now(),
               OrdDocAfgedruktDoor    = @@Gebruikercode,
               OrdDocGegGewijzigdNaAfdruk = 0,
               OrdDocGewijzigdDoor    = '',
               OrdDocLaatstGebruiktNr = @MokNummer
        where   OrdDocOrkGid = @OrkGid
               and OrdDocDocSoort  = 35; // DL-Pakbon
      end if;

		  // --- Verwijderen order-colli --- Zoals dat bij de normale levering gebeurt, moet dat ook bij directe levering - bug 35685
		  delete tabOrderColli where OrclOrkGid = @OrkGid;

    END FOR;

  end if;

  //RVL 02-03-2010 Bug 31607 : Toch mogelijk om bestellingen automatisch te verwijderen, ook bij directe inkoop. Maar dan moet er wel gelden dat er geen enkele koppeling meer is tussen
  //                           tabBestelRegelDetail en tabOrderRegel

  //TG 15-08-2008: Eventueel verwijderen van bestelkoppen en bestelregels. Bestellingen mogen alleen verwijderd worden als deze volledig ontvangen zijn
  //en als er geen andere magazijnontvangsten meer zijn waar regels van dezelfde bestelling in staan. Maw: als ik twee bestelregels in een bestelling heb
  //en ik maak voor elk van deze twee regels een ontvangst aan dan wordt de bestelling pas verwijderd als de 2e ontvangst verwerkt wordt.
  if exists (select 1 from tabVasteGegevensBestellingen where VgbBestellingAutomVerwijderen = 1) then
    delete tabBestelKop
    from   tabBestelKop inner join tabBestelRegel on (BstRglBstKopGid = BstKopGid)
                        inner join tabMagazijnOntvangsten on (MagOntBstRglGid = BstRglGid)
    where  (MagOntMokGid = @MokGid) and (BstKopIsVolledigOntvangen = 1)
           and not exists (select first 1 from tabMagazijnOntvangsten OntvangstBinnen
                           inner join tabBestelRegel BestelBinnen on (BestelBinnen.BstRglGid = OntvangstBinnen.MagOntBstRglGid)
                           where OntvangstBinnen.MagOntMokGid <> @MokGid and BestelBinnen.BstRglBstKopGid = BstKopGid
                          )
           and not exists (select first 1 from tabBestelRegel BestelBinnen
                           inner join tabBestelRegelDetail on (brdBstRglGid = BestelBinnen.BstRglGid and BestelBinnen.BstRglBstKopGid = BstKopGid)
                           where BrdOrrGid is not null);
  end if;

  delete tabMagazijnOntvangsten
  where (MagOntMokGid = @MokGid);

  delete tabMagazijnOntvangstenKop
  where (MokGid = @MokGid);

  set @@MagOntWordVerwerkt = 0;

  set @@ErrorTextProcedure = 'MagazijnOntvangstVerwerken';
  //call TraceEind(@@ErrorTextProcedure);
end;


//$Workfile: MagBoeken.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//-------- Mag er in een bepaalde periode geboekt worden (rekeninghoudend met blokkade voor een heel boekjaar)
if exists (select 1 from sys.sysProcedure where proc_name='MagBoeken') then
  drop procedure MagBoeken;
end if;

create procedure MagBoeken (in @BjGid integer, in @Datum Date, in @DgbGid integer, inout @IsToegestaan smallint, inout @Pernr integer)
begin
  declare @DagboekSoort integer;
  declare @IsGeblokkeerd smallint;

  set @@ErrorTextProcedure = 'MagBoeken > @BjGid='+string(@BjGid)+', @Datum='+string(@Datum)+', @DgbGid='+string(@DgbGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Pernr = null;
  select IsNull(BjIsGeblokkeerd,0) into @IsGeblokkeerd from tabBoekjaar where BjGid = @BjGid;
  if @IsGeblokkeerd=0 then
    if @DgbGid is not null then
      select DagboekSoort into @DagboekSoort from tabDagboek where DgbGid = @DgbGid;
    else
      set @DagboekSoort = 0;
    end if;

    //Bij dagboek van het type beginbalans (5), moet er naar periode 0 worden gekeken
    if @DagboekSoort = 5 then    //Dagboek van het type beginbalans
      select PerIsGeblokkeerd, @Pernr into @IsGeblokkeerd, @Pernr from tabPeriode where PerBjGid=@BjGid and Pernr=0;
    else
      select PerIsGeblokkeerd, Pernr into @IsGeblokkeerd, @Pernr from tabPeriode where PerBjGid=@BjGid and (@Datum between BeginDatum and EindDatum);
    end if;
  end if;

  if @IsGeblokkeerd = 0 then
    set @IsToegestaan = 1;
  else
    set @IsToegestaan = 0;
  end if;

  set @@ErrorTextProcedure = 'MagBoeken > @IsToegestaan='+string(@IsToegestaan)+', @Pernr='+string(@Pernr);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure MarkeerBoekgangVoorVerwerken(in @Volgnr integer, in @BjGid integer, in @BoekgangGid integer, in @Verwerken smallint)
begin

  set @@ErrorTextProcedure = 'MarkeerBoekgangVoorVerwerken >';
  //call TraceBegin(@@ErrorTextProcedure);

  //-1 betekent alle voorlopige boekingsgangen
  if @BoekgangGid = -1 then
  begin
    delete from tmpBoekingsgangenVerwerken where BgVwkVolgnr = @Volgnr;
    if @Verwerken = 1 then
      insert into tmpBoekingsgangenVerwerken (BgVwkVolgnr, BgVwkBoekgangGid, BgVwkVerwerken)
      select @Volgnr, BoekgangGid, 1 from tabBoekingsgang where BoekGangBjGid = @BjGid;
    end if;
  end
  else
    delete from tmpBoekingsgangenVerwerken where BgVwkVolgnr = @Volgnr and BgVwkBoekgangGid = @BoekgangGid;
    if @Verwerken = 1 then
      insert into tmpBoekingsgangenVerwerken (BgVwkVolgnr, BgVwkBoekgangGid, BgVwkVerwerken) values (@Volgnr, @BoekgangGid, 1);
    end if;
  end if;

  set @@ErrorTextProcedure = 'MarkeerBoekgangVoorVerwerken';
  //call TraceBegin(@@ErrorTextProcedure);
end;


//$Workfile: MarkeerFactuurVoorVerwerken.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// --------------------------------------------------------------------------------------------------------------
// ----------------- MarkeerFactuurVoorVerwerken - tbv kopieren orders uit factuurhistorie ----------------------
// ---- Middels deze routine worden refs naar de aangevinkte order(regels) in een tijdelijke tabel geplaatst ----
// --------------------------------------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='MarkeerFactuurVoorVerwerken') then
  drop procedure MarkeerFactuurVoorVerwerken;
end if;

create procedure MarkeerFactuurVoorVerwerken(in @Soort smallint, in @Volgnr integer, in @RefGid integer, in @Verwerken smallint)
begin
  declare @tmp integer;
  // Soort 0 = KOP , 1 = REGEL
  set @@ErrorTextProcedure = 'MarkeerFactuurVoorVerwerken @Soort='+string(@Soort)+',@Volgnr='+string(@Volgnr)+',@RefGid='+string(@RefGid)+',@Verwerken='+string(@Verwerken);
  //call TraceBegin(@@ErrorTextProcedure);

  delete from tmpFactuurNaarOrder where fnoSoort = @Soort and fnoVolgNr = @VolgNr and fnoRefRegelGid = @RefGid;
  if @Verwerken = 1 then
    insert into tmpFactuurNaarOrder (fnoSoort, fnoVolgNr, fnoRefRegelGid, fnoVerwerken) values (@Soort, @Volgnr, @RefGid, @Verwerken);
    if @Soort = 0 then
      // Kop
      //delete from tmpFactuurNaarOrder where fnoSoort = 1 and fnoVolgNr = @VolgNr and fnoRefRegelGid in (select frGid from tabFactuurRegel where FrFrefGid = @RefGid);
      if not exists(select 1 from tmpFactuurNaarOrder inner join tabFactuurRegel on FrGid = fnoRefRegelGid where fnoSoort = 1 and fnoVolgNr = @VolgNr and frFrefGid = @RefGid) then
      	// default alle regels aanzetten als de kop aangezet wordt
        insert into tmpFactuurNaarOrder (fnoSoort, fnoVolgNr, fnoRefRegelGid, fnoVerwerken)
                      select                    1,   @Volgnr,          frGid,            1 from tabFactuurRegel where FrFrefGid = @RefGid;
      end if;
    else
      // Regel
      select FrFrefGid into @tmp from tabFactuurRegel where FrGid = @RefGid;
      if not exists(select 1 from tmpFactuurNaarOrder where fnoSoort = 0 and fnoVolgNr = @VolgNr and fnoRefRegelGid = @tmp) then
        // kop ook aanzetten wanneer er een regel geselecteerd wordt
        insert into tmpFactuurNaarOrder(fnoSoort, fnoVolgNr, fnoRefRegelGid, fnoVerwerken) values (0, @VolgNr, @tmp, 1);
      end if;
    end if;
  else
    if @Soort = 0 then // Kop is geDEselecteerd, dus moeten de regels ook weg !
      delete from tmpFactuurNaarOrder where fnoSoort = 1 and fnoVolgNr = @VolgNr and fnoRefRegelGid in (select frGid from tabFactuurRegel where FrFrefGid = @RefGid);
    end if;
  end if;

  //call TraceEind('MarkeerFactuurVoorVerwerken');

end;


create or replace procedure MarkeerVrdMutVoorVerwerken( in @VolgNummer integer, in @vckGid integer, in @Verwerken smallint, in @Melding nchar(120))
begin
  //call TraceBegin('MarkeerVrdMutVoorVerwerken');

  if not exists(Select 1 from tmpVrdMutVerwerken where vmvVolgNummer = @VolgNummer and vmvVckGid = @vckGid) then
    insert into tmpVrdMutVerwerken (vmvVolgNummer, vmvVckGid, vmvVerwerken, vmvMelding) values (@VolgNummer, @vckGid, @Verwerken, @Melding);
	else
    update tmpVrdMutVerwerken set vmvVerwerken = @Verwerken, vmvMelding = IsNull(@Melding,vmvMelding) where vmvVolgNummer = @VolgNummer and vmvVckGid = @vckGid;
	end if;
  //call TraceEind('MarkeerVrdMutVoorVerwerken');
end;

CREATE or replace PROCEDURE MarketingeventCategorieGeefSubtree(in @MaevCatGid integer, in @Nodefilter smallint)
//@nodefilter:
// 0 alleen opgegeven node              || query: select * from MarketingeventCategorieGeefSubtree(1,0)  -> resultaat gidjes: 1
// 1 volledige subtree inclusief node   || query: select * from MarketingeventCategorieGeefSubtree(1,1)  -> resultaat gidjes: 1 t/m 14
// 2 volledige subtree zonder node      || query: select * from MarketingeventCategorieGeefSubtree(1,2)  -> resultaat gidjes: 2 t/m 14
// 3 directe kinderen, inclusief node   || query: select * from MarketingeventCategorieGeefSubtree(1,3)  -> resultaat gidjes: 1, 2, 8
// 4 directe kinderen, zonder node      || query: select * from MarketingeventCategorieGeefSubtree(1,4)  -> resultaat gidjes: 2, 8
//
// VOORBEELD-TREE:
// Hoofdcategorie (gid=1)
// + Radio (gid=2)
//   + Commerciele zenders(gid=3)
//     | Radio 538 (gid=4)
//     | BNR (Business Radio) (gid=5)
//   + Publieke zenders (gid=6)
//     | 3FM (gid=7)
// + TV (gid=8)
//   + Commerciele zenders (gid=9)
//     | RTL 4 (gid=10)
//     | SBS 6 (gid=11)
//   + Publieke zenders (gid=12)
//     | Nederland 1 (gid=13)
//     | Nederland 2 (gid=14)
BEGIN
  WITH RECURSIVE rectabMarketingeventCategorieSubtree
  (
    stMaevcatGid,
    stMaevcatMaevcatGidParent,
    stMaevcatLevel)
  AS
  (
    SELECT
      categorie.MaevcatGid              as stMaevcatGid,
      categorie.MaevcatMaevcatGidParent as stMaevcatMaevcatGidParent,
      cast(1 as integer)                as stMaevcatLevel
    FROM
      tabMarketingEventCategorie as categorie
    WHERE
     (@Nodefilter in (0,1,3) and categorie.MaevcatGid = @MaevCatGid) or (@Nodefilter in (2,3,4) and categorie.MaevcatMaevcatGidParent = @MaevCatGid)
    UNION ALL
    SELECT
      categorie.MaevcatGid,
      categorie.MaevcatMaevcatGidParent,
      rectabMarketingeventCategorieSubtree.stMaevcatLevel + 1
    FROM
      rectabMarketingeventCategorieSubtree
      INNER JOIN tabMarketingEventCategorie as categorie ON (categorie.MaevcatMaevcatGidParent = rectabMarketingeventCategorieSubtree.stMaevcatGid)
    WHERE
      categorie.MaevcatMaevcatGidParent is not null and @Nodefilter in (1,2)
  )
  SELECT
    stMaevcatGid
  FROM
    rectabMarketingeventCategorieSubtree
  ORDER BY
    stMaevcatLevel;
END;

create or replace procedure MatchEmail(
  in    @Email    nchar(80),
  in    @ZoekIn   nchar(100), // ZoekIn is nu nog leeg, kan later ter verfijning van de zoekacties worden gebruikt (bijv. alleen adressen, of alleen relatiebestand 001)
  in    @Filter   integer,   // 0 = niet filteren, 1 = wel filteren
  in    @OpschonenTemp integer,
  inout @SessieNr integer
)
begin
  declare @FnCodeLicenties     integer;
  declare @AantalNaw           integer;
  declare @AantalCP            integer;
  declare @AantalLicentie      integer;
  declare @AantalAdres         integer;

  declare @tmpMeGidVanLicentie integer;
  declare @tmpMeGidVanCP       integer;
  declare @tmpMeGidVanAdres    integer;
  declare @ErrText             nchar(250);

  set @ErrText = 'MatchEmail(@Email='+string(@Email)+', @ZoekIn='+string(@ZoekIn)+', @SessieNr='+string(@SessieNr)+')';
  set @@ErrorTextProcedure = @ErrText;
  //call TraceBegin(@@ErrorTextProcedure);

  // Sessie aanmaken om eindresultaat in op te slaan
  if @SessieNr is null then
    call MaakUniekSessieNummer(@SessieNr);
    set @OpschonenTemp = 1;
  end if;
  if @OpschonenTemp <> 0 then
    delete tmpMatchEmail where tmpMeSessieNr = @SessieNr;
  end if;

  // *** Zoeken in licenties (maatwerk Quadrant) ***
  if IsModuleActive('m8') <> 0 then // Maatwerk Quadrant
    set @@ErrorTextProcedure = @ErrText + '-> Zoek in licenties';
    // Ophalen functie tbv. belangrijkste contactpersoon van deze functie
    select SchermFnCode into @FnCodeLicenties from tabScherm where SchermSoort = 900; //qcSchermLicentieGegevens

    insert into tmpMatchEmail(tmpMeSessieNr, tmpMeGevondenIn, tmpMeEmail, tmpMeLicGid, tmpMeFonGid, tmpMeNawGid, tmpMeNawFilGid, tmpMeRelGid)
    select @SessieNr,
           0, //Licenties
           @Email,
           LicGid,
           NawFilFonGid,
           NawFilNawGid,
           NawFilGid,
           //i.o.m. GvK niet de default contactpersoon teruggeven
           null //(select RelGid from tabRelatieFunctie LEFT OUTER JOIN tabRelatie ON (RelGid = FnRelGid) WHERE (IsBelangrijkste = 1) AND (relNawGid = NawFilNawGid) AND (relFnCode = @FnCodeLicenties)) RelGid
    from   tabLicentie
           inner join tabNawFile on NawFilGid = LicNawFilGid
    where  LicEmailAdres = @Email;
  end if;

  // *** Zoeken in NAW-bestanden ***
  set @@ErrorTextProcedure = @ErrText + '-> Zoek in NAW-bestanden';
  insert into tmpMatchEmail(tmpMeSessieNr, tmpMeGevondenIn, tmpMeEmail, tmpMeFonGid, tmpMeNawGid, tmpMeNawFilGid, tmpMeRelGid, tmpMeAdrGid)
  select @SessieNr,
         1, // NAW-bestand
         @Email,
         NawFilFonGid,
         NawFilNawGid,
         NawFilGid,
         AdrRelGid,
         AdrGid
  from   tabAdres
         inner join tabNawFile on NawFilNawGid = AdrNawGid and NawFilFonId <> 'B'
  where AdrEmail = @Email;

  // *** Zoeken in contactpersonen ***
  set @@ErrorTextProcedure = @ErrText + '-> Zoek in contactpersonen';
  insert into tmpMatchEmail(tmpMeSessieNr, tmpMeGevondenIn, tmpMeEmail, tmpMeFonGid, tmpMeNawGid, tmpMeNawFilGid, tmpMeRelGid)
  select @SessieNr,
         2, // Contactpersonen
         @Email,
         NawFilFonGid,
         NawFilNawGid,
         NawFilGID,
         RelGid
  from   tabRelatie
         inner join tabNawFile on NawFilNawGid = RelNawGid and NawFilFonId <> 'B'
  where  RelEmail = @Email;

  // *** Zoeken in vrije rubrieken NAW/Relatiebestanden ***
  call MatchEmailVrijeRubrieken(@SessieNr, @Email, 3, 'NAW', '');

  // *** Zoeken in vrije rubrieken adressen ***
  call MatchEmailVrijeRubrieken(@SessieNr, @Email, 4, 'ADR', '');

  // *** Zoeken in vrije rubrieken contactpersonen ***
  call MatchEmailVrijeRubrieken(@SessieNr, @Email, 5, 'CP' , '');


  // *** Filteren **
  if @Filter <> 0 then
    // +++ Eerst controleren of we wel moeten filteren -> NIET als meerdere NAWs
    set @@ErrorTextProcedure = @ErrText + '-> Filteren';
    //call Trace(@@ErrorTextProcedure);

    select count(distinct tmpMeNawGid), count(distinct tmpMeRelGid), count(distinct tmpMeLicGid), count(distinct tmpMeAdrGid)
    into   @AantalNaw, @AantalCP, @AantalLicentie, @AantalAdres
    from   tmpMatchEmail
    where  tmpMeSessieNr = @SessieNr;
    set @@ErrorTextProcedure = @ErrText + '-> Filter; @AantalNaw='+string(@AantalNaw)+', @AantalCP='+string(@AantalCP)+', @AantalLicentie='+string(@AantalLicentie)+', @AantalAdres='+string(@AantalAdres);

    if     (@AantalNaw       = 1)
       and (@AantalCP       <= 1)
       and (@AantalLicentie <= 1) then

      //+++ Opzoeken adres, indien meerdere, dan liefst van licentie of relatie
      //    LET OP!! Het adres doet bij filteren niet ter zake, maar het is wel prettig om zoveel moeglijk het juiste adres terug te geven.
      //             Als er dus 2 adressen zijn, dan reduceren tot 1!
      if @AantalAdres >= 1 then
        select first tmpMeGid into @tmpMeGidVanAdres from tmpMatchEmail where tmpMeSessieNr = @SessieNr and tmpMeAdrGid is not null
        order by tmpMeRelGid desc, tmpMeLicGid desc;

        // Gevonden Adres in alle regels zetten, zodat als die worden gebruikt het adres i.i.g. wordt meegenomen
        if @tmpMeGidVanAdres is not null then
          update tmpMatchEmail
          set    tmpMeAdrGid = (select tmpMeAdrGid from tmpMatchEmail where tmpMeGid = @tmpMeGidVanAdres)
          where  tmpMeSessieNr = @SessieNr;
          set @AantalAdres = 1; // Aantal distinct adressen is nu nog maar 1
        end if;
      end if;

      // ***
      // Als ook het adres als filter-parameter moet worden getest, dan op deze plek testen op @AantalAdres<=1 en zoniet, dan stoppen met het filter
      // ***

      //+++ Opzoeken van 1 willekeurige regel met correcte contactpersoon, liefst met de licentie (0 of 1 licenties!)
      if @AantalCP = 1 then
        select first tmpMeGid into @tmpMeGidVanCP from tmpMatchEmail where tmpMeSessieNr = @SessieNr and tmpMeRelGid is not null
        order by tmpMeLicGid desc;

        if @tmpMeGidVanCP is not null then
          // Contactpersoon in alle regels zetten, zodat als die wordt gebruikt i.i.g. de contactpersoon mee gaat
          update tmpMatchEmail
          set    tmpMeRelGid = (select tmpMeRelGid from tmpMatchEmail where tmpMeGid = @tmpMeGidVanCP)
          where  tmpMeSessieNr = @SessieNr;
        end if;

      end if;

      // Maatwerk Quadrant: Indien licentie gevonden, dan die gebruiken (en straks de rest verwijderen)
      if IsModuleActive('m8') <> 0 and (@AantalLicentie = 1) then
        select first tmpMeGid into @tmpMeGidVanLicentie from tmpMatchEmail where tmpMeSessieNr = @SessieNr and tmpMeLicGid is not null;
        if @tmpMeGidVanLicentie is not null then
          // Licentie in alle regels zetten, zodat als die wordt gebruikt i.i.g. de licentie mee gaat
          update tmpMatchEmail
          set    tmpMeLicGid = (select tmpMeLicGid from tmpMatchEmail where tmpMeGid = @tmpMeGidVanLicentie)
          where  tmpMeSessieNr = @SessieNr;
        end if;
      end if;

      // Hier zijn alle gevonden regels qua GID aan elkaar gelijk, dus kunnen we nu heel eenvoudig alle regels behalve 1 verwijderen
      delete tmpMatchEmail
      where  (tmpMeSessieNr = @SessieNr)
         and (tmpMeGid <> (select first tmpMeGid from tmpMatchEmail where tmpMeSessieNr = @SessieNr));

    end if;

  end if;

  set @@ErrorTextProcedure = @ErrText;
  //call TraceEind(@@ErrorTextProcedure);
  //call MatchEmail('maatzn@hetnet.nl', '', 1, 1, 0);
  //select 'Klaar', tmpMeGid Gid, tmpMeGevondenIn Gevonden, tmpMeAdrGid AdrGid, tmpMeNawGid NawGid, tmpMeRelGid RelGid, tmpMeLicGid LicGid from tmpMatchEmail
end;


create or replace procedure MatchEmailVrijeRubrieken(
  in    @SessieNr     integer,
  in    @Email        nchar(80),
  in    @GevondenIn   integer,
  in    @VrBestandOms nchar(3), // NAW, CP of ADR
  in    @VrGroepIds   nchar(100) // Is nu nog leeg, kan later ter verfijning van de zoekacties worden gebruikt voor bepaalde NAWbestanden
)
begin
  declare @ZoekActie long nvarchar;

  set @@ErrorTextProcedure = 'MatchEmailVrijeRubrieken(@SessieNr='+string(@SessieNr)+', @Email='+string(@Email)+', @VrBestandOms='+string(@VrBestandOms)+', @VrGroepIds='+string(@VrGroepIds)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  // Opbouwen van zoekstring en uitwerken
  for @Cursor AS CURSOR_CurZoekVelden
  CURSOR FOR
    select 'Vr'+VrBestandOms + right(repeat('0', 3) + string(VrGroepId)   , 3) + right(repeat('0', 3) + string(VrSubGroepId)   , 3) @VrTabelNaam,
           VrVeldNaam @VrVeldNaam,
           VrLabel    @VrLabel,
           VrGroepId  @FonGid
    from   tabVrijeRubrieken
           //left outer join tabFileOfNaw on (FonID = VrGroepId)
    where  (VrBestandOms = @VrBestandOms)
       and (VrType = 6)
       and ((@VrGroepIds = '') or (@VrGroepIds like '%|'+right('00' + string(VrGroepId), 3)+'%'))
  FOR READ ONLY
  DO
    set @ZoekActie = 'insert into tmpMatchEmail(tmpMeSessieNr, tmpMeGevondenIn, tmpMeEmail, tmpMeVrLabel, tmpMeFonGid, tmpMeNawFilGid, tmpMeNawGid, tmpMeAdrGid, tmpMeRelGid)\n' +
                     'Select ' + string(@SessieNr)+ ', ' + string(@GevondenIn) + ', @Email, @VrLabel, @FonGid, NawFilGid, ' +
                     case @VrBestandOms
                       when 'NAW' then 'NawGid    koppelNawGid, null,   null  \n'
                       when 'ADR' then 'AdrNawGid koppelNawGid, AdrGid, null  \n'
                       when 'CP'  then 'RelNawGID koppelNawGid, null,   RelGid\n'
                       else            'null      koppelNawGid, null,   null  \n'
                     end +
                     'from   tab' + @VrTabelNaam + '\n' +
                     case @VrBestandOms
                       when 'NAW' then '       inner join tabNaw     on NawGid = ' + @VrTabelNaam + 'RecordId\n'
                       when 'ADR' then '       inner join tabAdres   on AdrGid = ' + @VrTabelNaam + 'RecordId\n'
                       when 'CP'  then '       inner join tabRelatie on RelGid = ' + @VrTabelNaam + 'RecordId\n'
                       else            ''
                     end +
                     '       left outer join tabNawFile on NawFilFonGid = @FonGid and NawFilNawGid = koppelNawGid\n' +
                     'where  ' + @VrVeldNaam + ' = @EMail';
    set @@ErrorTextProcedure = 'MatchEmailVrijeRubrieken->Execute immediate: ' + @ZoekActie;

    //call trace('\n' + @ZoekActie + '\n');
    Execute immediate @ZoekActie;

  END FOR;

  set @@ErrorTextProcedure = 'MatchEmailVrijeRubrieken(@SessieNr='+string(@SessieNr)+', @Email='+string(@Email)+', @VrBestandOms='+string(@VrBestandOms)+', @VrGroepIds='+string(@VrGroepIds)+')';
  //call TraceEind(@@ErrorTextProcedure);
//call MatchEmailVrijeRubrieken(0, 'maatzn@hetnet.nl', 3, 'NAW', '');
//call MatchEmailVrijeRubrieken(0, 'maatzn@hetnet.nl', 4, 'CP', '');
end;


