create or replace function MultipleLinesToOneLine(in @OriginalText nchar(250))
returns nchar(250)
begin
  // Let op: expres per onderdeel vervangen door spaties omdat het voorkomt dat slechts 1 van de Cr/Lf in de string staat!
  declare @TmpText   nchar(250);

  // CrLf vervangen door spatie
  set @TmpText = replace(@OriginalText, '\x13\x10', ' ');

  // NewLine vervangen door spatie
  set @TmpText = replace(@TmpText, '\x13', ' ');

  // Carriage return vervangen door spatie
  set @TmpText = replace(@TmpText, '\x10', ' ');

  return(@TmpText);


end;


//--- functie de een string retourneerd met een reeks van spaties vervangen door 1 spatie
create or replace function MultipleToSingleSpace(in @OriginalText nchar(250))
returns nchar(250)
begin
  //ACW: Sneller, maar nog maar niet geactiveerd
  //return (REPLACE(
  //                REPLACE(
  //                        REPLACE(myTextColumn, '  ', ' '+CHAR(1)) // Weinig kans dat char(1) in een tekst voorkomt
  //                ,CHAR(1)+' ','')
  //        ,CHAR(1),''));

  declare @TmpText   nchar(250);
  declare @NewText   nchar(250);
  declare @Position  integer;

  set @TmpText = @OriginalText;
  set @NewText = @OriginalText;
  While Locate(@TmpText, '  ', 1) > 0 loop
    //call Trace('@TmpText = >'+@TmpText+'<  ('+String(Locate(@TmpText, '  ', 1))+')');
    set @Position = 1;
    set @NewText  = '';
    while @Position <= length(@TmpText) loop
     //call Trace('@NewText = >'+@NewText+'<');
      if substr(@TmpText, @Position, 2) = '  ' then
        set @NewText  = @NewText  + ' ';
        set @Position = @Position + 2;
      else
        set @NewText  = @NewText  + substr(@TmpText, @Position, 1);
        set @Position = @Position + 1;
      end if;
    end loop;
    set @TmpText = @NewText;
  end loop;

  return(@NewText);


end;


//$Workfile: MuteerTabOpbrengstGroepSoorten.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//---------- Update, Insert en/of Delete Opbrengstgroepsoorten
if exists (select 1 from sys.sysProcedure where proc_name='MuteerTabOpbrengstGroepSoorten') then
  drop procedure MuteerTabOpbrengstGroepSoorten;
end if;

create procedure MuteerTabOpbrengstGroepSoorten(in @GrpGid integer, in @ParSoort integer, in @RksGid integer)
begin
  set @@ErrorTextProcedure = 'MuteerTabOpbrengstGroepSoorten > @GrpGid='+string(@GrpGid)+', @ParSoort='+string(@ParSoort)+', @RksGid='+string(@RksGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select 1 from tabOpbrengstGroepSoort where GrpSoortGrpGid=@GrpGid and GrpSoortParSoort=@ParSoort) then
    if @RksGid is null then
      delete tabOpbrengstGroepSoort where GrpSoortGrpGid=@GrpGid and GrpSoortParSoort=@ParSoort;
    else
      update tabOpbrengstGroepSoort set GrpSoortRksGid=@RksGid where GrpSoortGrpGid=@GrpGid and GrpSoortParSoort=@ParSoort;
    end if;
  else
    if @RksGid is not null then
      insert tabOpbrengstGroepSoort (GrpSoortGrpGid, GrpSoortParSoort, GrpSoortRksGid) values (@GrpGid, @ParSoort, @RksGid)
    end if;
  end if;

  set @@ErrorTextProcedure = 'MuteerTabOpbrengstGroepSoorten';
  //call TraceEind(@@ErrorTextProcedure);

end;


