create procedure MuteerTabProjectGroepSoorten(in @GrpGid integer, in @ParSoort integer, in @RksGid integer)
begin
  set @@ErrorTextProcedure = 'MuteerTabProjectGroepSoorten > @GrpGid='+string(@GrpGid)+', @ParSoort='+string(@ParSoort)+', @RksGid='+string(@RksGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select 1 from tabProjectGroepSoort where ProjGrpSrtProjGrpGid = @GrpGid and ProjGrpSrtParSoort = @ParSoort) then
    if @RksGid is null then
      delete tabProjectGroepSoort where ProjGrpSrtProjGrpGid = @GrpGid and ProjGrpSrtParSoort = @ParSoort;
