    end if;
  else
    if @RksGid is not null then
      insert tabProjectGroepSoort (ProjGrpSrtProjGrpGid, ProjGrpSrtParSoort, ProjGrpSrtRksGid) values (@GrpGid, @ParSoort, @RksGid);
    end if;
  end if;

