// Maak de koppeling tussen balanscode (rub/par/subpar) en VasteGegevens (FileOfNaw c.q. fonGid)
if exists (select 1 from sys.sysProcedure where proc_name='NawBalansCodeKoppelingUpdate') then
  drop procedure NawBalansCodeKoppelingUpdate;
end if;

create procedure NawBalansCodeKoppelingUpdate(in @fonGid integer, in @BalansCode integer, in @BlGid integer)
begin
  set @@ErrorTextProcedure = 'NawBalansCodeKoppelingUpdate > @fonGid='+string(@fonGid)+', @BalansCode='+string(@BalansCode)+', @BlGid='+string(@BlGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if @BlGid is null then
    delete from tabBalansCodeNaw where BalNawfonGid=@fonGid and BalNawBlCode=@BalansCode;
  else
    if exists (select 1 from tabBalansCodeNaw where BalNawBlCode=@BalansCode and BalNawfonGid=@fonGid) then
      update tabBalansCodeNaw set BalNawBlGid=@BlGid where BalNawBlCode=@BalansCode and BalNawfonGid=@fonGid;
    else
      insert into tabBalansCodeNaw (BalNawBlCode, BalNawfonGid, BalNawBlGid) values (@BalansCode, @fonGid, @BlGid);
    end if;
  end if;

  set @@ErrorTextProcedure = 'NawBalansCodeKoppelingUpdate';
  //call TraceEind(@@ErrorTextProcedure);

end;


