create or replace procedure NawDelete(in @NawfilGid integer, in @OokRksVerwijderen smallint default 1)
begin atomic
  declare @VrTableName      nchar(40);
  declare @VeldNaamRecordId nchar(40);
  declare @Found            smallint;
  declare @NawFilFonGid     integer;
  declare @NawGid           integer;
  declare @RksGid           integer;

  set @@ErrorTextProcedure = 'NawDelete > ';
  //call TraceBegin(@@ErrorTextProcedure + 'NawFilGid = ' + string(@NawFilGid) + ', @OokRksVerwijderen='+ string(@OokRksVerwijderen));
  if @OokRksVerwijderen is null then
    set @OokRksVerwijderen = 1;
  end if;

  select NawFilNawGid, NawFilFonGid, NawFilRksGid into @NawGid, @NawFilFonGid, @RksGid from tabnawFile where NawFilgid = @NawfilGid;

  delete tabNaw where NawGid = @NawGid;
  delete tabNawFile where NawFilGid = @NawFilGid;
  if @OokRksVerwijderen = 1 then //Alleen als we vanuit de trigger tdb_tabrekeningschema komen, dan is  @OokRksVerwijderen 0, verwijderen we hier niet de rekening uit tabRekeningschema. Wordt dan indirect afgehandeld door tdb_tabrekeningschema
    delete tabRekeningschema where RksGid = @RksGid;
  end if;

  //--- naam tabel samenstellen
  set @VrTableName      = 'tabVrNAW' + right(repeat('0', 3) + string(@NawFilFonGid)   , 3) +
                                       right(repeat('0', 3) + string(@NawFilFonGid)   , 3) ;
  //--- naam identifier-veld samenstellen
  set @VeldnaamRecordId = 'vrNAW'    + right(repeat('0', 3) + string(@NawFilFonGid)   , 3) +
                                       right(repeat('0', 3) + string(@NawFilFonGid)   , 3) + 'RecordId';

  //call Trace('NawDelete > Verwijderen vrije rubriektabel''NawDelete > Verwijderen vrije rubriektabel');
  execute immediate 'select 1 into @Found from sys.systable where table_name = ' + char(39) || @VrTableName || char(39) + '';
  if @Found = 1 then
    execute immediate 'delete from ' || @VrTableName ||' where ' || @VeldnaamRecordId || ' = @Nawgid ' ;
  end if;

  set @@ErrorTextProcedure = 'NawDelete';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure NawEtiket(
  in @FonId nchar(3),
  in @NawFilNummer nchar(10),
  in @Adres smallint,     //0 = Vestigingsadres, 1=Correspondentieadres, 2=Adres volgens @AdrCode
  in @AdrCode integer,
  in @EtiketVan smallint, //0 = contactpersoon @RelNummer, 1=voorkeurscontactpersoon van functie <@FnCode>, 2=Functie <@FnCode>
  in @RelNummer integer,
  in @FnCode integer)
result(
    NawGid integer, RelGid integer, AdrGid integer,
    NawFilNummer nchar(10), NawFilZoekCode nchar(10),
    AdrNaam1 nchar(40), AdrNaam2 nchar(40), AdrOms nchar(40), AdrStraat nchar(40), AdrHuisnummer nchar(10), AdrPostcode nchar(40), AdrPlaats nchar(40), AdrTelefoon nchar(25), AdrTelefoon2 nchar(25), AdrTelefax nchar(25), AdrEmail nchar(80),
    NawBtwNummer nchar(15),
    NawRekBankrekening nchar(34),
    //Voor wordkoppeling, alleen bij debiteur:
    NawVertegenwCode         integer,
    Naam_NawVertegenwCode    nchar(40),
    NawContributieCode       integer,
    Oms_NawContributieCode   nchar(40),
    RelContributieCode       integer,
    Oms_RelContributieCode   nchar(40),
    //Voor wordkoppeling, alleen bij crediteur:
    NawOnsDebiteurNummer nchar(20),

    NawWebsite nchar(250),
    relAchternaam nchar(40), relVoorvoegsel nchar(40), relVoorletters nchar(40), relVoornaam nchar(40), relTitel nchar(40), relAchtervoegsel nchar(40), relEmail nchar(80), relTelefax nchar(25), relTelefoon nchar(25), relTelefoon2 nchar(25), relGeslacht smallint,
    NaamInAdres nchar(60), NaamInAanhef nchar(60), NaamInBrief nchar(60), VolledigeNaam nchar(40),
    omsFunctie nchar(40), TaalCode nchar(3), TaalOms nchar(40), lndInNAWBlok smallint, LandAfdrukken smallint, KIXCode nchar(40), lndEigenCode nchar(3), lndOms nchar(40), lndPlaatsHuisnr smallint,lndPlaatsPostcode smallint, lndPostcodeMasker nchar(40),
	// TabFinancieel
	BtcOms nchar(40), LvcOms nchar(40), BtwPercentage numeric(6,2), NawFilKredLimiet numeric(15,2), ValCode nchar(3)
	)
begin
  //call TraceBegin('NawEtiket(@FonId='+@FonId+', @NawFilNummer='+@NawFilNummer+', @Adres='+string(@Adres)+', @AdrCode='+string(@AdrCode)+', @EtiketVan='+string(@EtiketVan)+', @RelNummer='+string(@RelNummer)+', @FnCode='+string(@FnCode)+')');

  //call TraceEind('NawEtiket');

  select
    NawGid,
    RelGid,
    AdrGid,
    NawFilNummer,
    NawFilZoekCode,
    AdrNaam1,
    AdrNaam2,
    AdrOms,
    AdrStraat,
    AdrHuisnummer,
    AdrPostcode,
    AdrPlaats,
    AdrTelefoon,
    AdrTelefoon2,
    AdrTelefax,
    AdrEmail,
    NawBtwNummer,
    NawRekBankrekening,
    //voor wordkoppeling, alleen bij debiteur:
    NawVertegenwCode,
    (select SubRelA.RelVolledigeNaam from tabRelatie SubRelA where SubRelA.RelVtgCode=NawVertegenwCode) Naam_NawVertegenwCode,
    NawContributieCode,
    (select ContributieOms from tabContributieCode where ContributieCode=NawContributieCode) Oms_NawContributieCode,
    RelContributieCode,
    (select ContributieOms from tabContributieCode where ContributieCode=RelContributieCode) Oms_RelContributieCode,
    //voor wordkoppeling, alleen bij crediteur:
    NawOnsDebiteurNummer,

    NawWebsite,
    relAchternaam,
    relVoorvoegsel,
    relVoorletters,
    relVoornaam,
    relTitel,
    relAchtervoegsel,
    relEmail,
    relTelefax,
    relTelefoon,
    relTelefoon2,
    relGeslacht,

    //nav bug 13559(als van contpers de aanhefteksten leeg zijn, neem dan die van de functie:
    // or (RelGid is not null and relNaamInAdres='')
    // or (RelGid is not null and relNaamInAanhef='')
    // or (RelGid is not null and relNaamInBrief='')
    //nav bug 18933(als er geen contpers is, dan VolledigeNaam leeglaten):VolledigeNaam=''

    //bepaal tekst als van functie geen contactpersoon is laat leeg voor verzendadressen en voor @EtiketVan = 0
    (if @EtiketVan = 2 or RelGid is null or (RelGid is not null and relNaamInAdres='') then fnTekstAdres  else relNaamInAdres   endif) NaamInAdres ,
    (if @EtiketVan = 2 or RelGid is null or (RelGid is not null and relNaamInAanhef='') then fnTekstAanhef else relNaamInAanhef  endif) NaamInAanhef,
    (if @EtiketVan = 2 or RelGid is null or (RelGid is not null and relNaamInBrief='') then fnTekstBrief  else relNaamInBrief   endif) NaamInBrief,
    (if @EtiketVan = 2 or RelGid is null then ''  else relVolledigeNaam endif) VolledigeNaam,
    omsFunctie,
    TaalCode,
    TaalOms,
    lndInNAWBlok,
    ( if lndInNAWblok = 1  then 1                        // bepaal of land moet worden afgedrukt
      else if lndgid = (select DefaultLndGid from tabVasteGegevens) then 0
           else 1
           endif
      endif) LandAfdrukken,
    BouwKIXCode(adrLndGid, AdrPostcode, AdrHuisnummer) as KIXCode,
    lndEigenCode,
    lndOms,
    lndPlaatsHuisnr,
    lndPlaatsPostcode,
    lndPostcodeMasker,
	// TabFinancieel
	BtcOms,
	LvcOms,
	BtwPercentage,
	NawFilKredLimiet,
	ValCode

  from   tabNaw inner join tabNawFile on (NawFilNawGid = NawGid and NawFilFonId = @FonId)
         inner join tabAdres on ((@Adres = 0 and AdrGid = NawGidVestiging) or
                                 (@Adres = 1 and AdrGid = if NawGidCorrespondentie is null then NawGidVestiging else NawGidCorrespondentie endif) or
                                 (@Adres = 2 and AdrNawGid = NawGid and AdrCode = @AdrCode))
         left outer join tabFunctieContact on (FnCode = @FnCode)
         left outer join tabRelatieFunctie on (@EtiketVan =  1 and IsBelangrijkste = 1 and RelFnCode = @FnCode)
         left outer join tabRelatie on (RelNawGid = NawGid and
                                        ((@EtiketVan = 0 and RelNummer = @RelNummer) or
                                         (@EtiketVan = 1 and RelGid = FnRelGid)))
         left outer join tabFunctieTaal on (TaalFnCode = FnCode and FnTaalGid = NawTaalGid)
         left outer join tabTaal on (TaalGid = nawTaalGid)
         left outer join tabLand on (lndGid = adrLndGid)

         left outer join tabNawRekening on (nawGid =nawRekNawGid and NawrekSoort like '%D%')
		 left outer join tabBetalingsconditie on (NawFilBtcNummer = BtcNummer)
		 left outer join tabLeveringsConditie on (NawFilLvcNummer = LvcNummer)
		 left outer join tabBtw on (NawFilBtwCode = BtwCode)
		 left outer join tabValuta on (NawFilValNummer = ValNummer)

  where  NawFilNummer = @NawFilNummer;


end;

