//$Workfile: NawExportGeefJuisteCP.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//Wordt gebruikt bij NAWExportDiv. Pakt voorkeur en anders degene met het laagste nummer binnen de opgegeven functie.
if exists (select 1 from sys.sysProcedure where proc_name='NawExportGeefJuisteCP') then
  drop function NawExportGeefJuisteCP;
end if;

create function NawExportGeefJuisteCP(in @RelNawGid integer, in @RelFnCode integer)
returns integer
begin
  declare @RelGid integer;

  set @@ErrorTextProcedure = 'NawExportGeefJuisteCP > @RelNawGid='+string(@RelNawGid)+', @RelFnCode='+string(@RelFnCode);
  //call TraceBegin(@@ErrorTextProcedure);

  set @RelGid = null;

  //Eerst de Voorkeur zoeken.
  //call Trace('NawExportGeefJuisteCP > Zoek voorkeur');
  select RelGid into @RelGid
  from tabRelatie
  inner join tabRelatieFunctie on RelGid = FnRelgid and RelFnCode = @RelFnCode and IsBelangrijkste=1
  where RelNawGID = @RelNawGid;

  if @RelGid is null then
  //call Trace('NawExportGeefJuisteCP > Zoek laagste nummer');
    select first RelGid into @RelGid
    from tabRelatie
    inner join tabRelatieFunctie on RelGid = FnRelgid and RelFnCode = @RelFnCode
    where RelNawGID = @RelNawGid
    order by RelNummer;
  end if;

  set @@ErrorTextProcedure = 'NawExportGeefJuisteCP > @RelGid='+string(@RelGid);
  //call TraceEind(@@ErrorTextProcedure);
  return(@RelGid)

end;


//$Workfile: NawGenereerAdresNummer.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//Vve: genereert nieuwe adresnummer voor een bepaalde naw, wat gebruikt kan worden om een nieuw verzendadres aan te maken.
// indien niet meer past of onbekende naw, dan krijg je -1 terug.
if exists (select 1 from sys.sysProcedure where proc_name='NawGenereerAdresNummer') then
  drop function NawGenereerAdresNummer;
end if;

create function NawGenereerAdresNummer (in @NawGid integer)
returns integer
begin
  declare @NewAdrCode integer;
  declare @BestaatAl integer;

  set @@ErrorTextProcedure = 'NawGenereerAdresNummer > @NawGid = '+string(@Nawgid) ;
  //call TraceBegin(@@ErrorTextProcedure);

  //eerst makkelijk proberen:
  Select IsNull(Max(AdrCode)+1, 0) into @NewAdrCode from tabAdres where AdrNawGid = @NawGid;

  //Alsie te groot wordt zoeken we nog naar een gaatje.
  if @NewAdrCode > 999 then
    set @BestaatAl = 1;
    set @NewAdrCode = 0;

    ZoekLoop:
    loop
      if exists(select 1 from tabAdres where AdrNawGid = @NawGid and AdrCode = @NewAdrCode) then
        set @BestaatAl = 1;
      else
        set @BestaatAl = 0;
      end if;

      if (@NewAdrCode > 999) or (@BestaatAl = 0) then
        leave ZoekLoop;
      end if;
      set @NewAdrCode = @NewAdrCode + 1;

    end loop ZoekLoop;

    //Helaas ook geen gaatjes meer
    if (@BestaatAl = 1) or (@NewAdrCode > 999) then
      set @NewAdrCode = -1;
    end if;

  end if;

  set @NewAdrCode = IsNull(@NewAdrCode, -1);

  set @@ErrorTextProcedure = 'NawGenereerAdresNummer';
  //call TraceEind (@@ErrorTextProcedure);
  return(@NewAdrCode);

end;


create or replace procedure NawGenereerNummer(in @fonGID integer, out @Nummer nchar(10), out @Startnummer nchar(10))
begin
  declare @Genereren    integer;
  declare @Soort        nchar(3);
  declare @stap         integer;
  declare @NieuwNummer  integer;      // 0 = nog niet, 1 = nieuw nummer, 2 = niet te genereren
  declare @lengte       integer;
  declare @NummerLengte smallint;
  declare @paragraaf    nchar(2);

  set @@ErrorTextProcedure = 'NawGenereerNummer > ';
  //call TraceBegin(@@ErrorTextProcedure + '@FonGid = ' + string(@FonGid));

  set @nummer       = '';
  set @NieuwNummer  = 0;

  //Dit deel moet uniek gelocked (met een wacht-lus)
  call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'NawGenereerNummer', '');

  select fonAutoGenereren, fonStartNummer, fonStapGrootte, fonId
  into   @Genereren,       @startnummer,   @Stap,          @Soort
  from   tabFileOfNaw
  where  fonGID=@fonGid;

  //call Trace('NawGenereerNummer > @Genereren = ' + String(@Genereren) + ', @Startnummer = ' + @Startnummer + ', @Stap = ' + String(@Stap) + ', @Soort = ' + @Soort);

  if @genereren=1 then
    set @paragraaf   = left(@startNummer, 2);

    if (@Soort <> 'C') and (@Soort <> 'D') then
      set @NummerLengte = 8; // Relatienummers blijven 8 lang!
      Set @Startnummer = Right('0000000000'+@startNummer, @NummerLengte); // ACW: Nu o.b.v. de vaste gegevens de lengte vastleggen
    else
      set @NummerLengte = 10; // deb.+cred. zijn max. 10 lang
    end if;

    set @lengte = Length(@Startnummer);

    //call TraceBegin('NawGenereerNummer > Start loop : @Paragraaf = ' + @Paragraaf + ', @Soort = ' + @Soort);
    //nadat het nieuwe nummer gevonden is, de lus nog eens doorlopen voor het nummer dat in de vaste gegevens word opgeslagen.
    while @NieuwNummer=0 loop
      if (length(@Startnummer) > @lengte) or ((left(@Startnummer, 2) <> @paragraaf) and ((@Soort='D') or (@Soort='C'))) then
        set @NieuwNummer = 2;      // Fout dus
        //call Trace('NawGenereerNummer > Fout nummer : @StartNummer = ' + @StartNummer +  ' -> zoeken stoppen');
      else
        if @nummer = '' and not exists (select 1 from tabNawFile, tabNaw where nawfilNummer=@Startnummer and nawfilFonGid=@fonGID) then
          //call Trace('NawGenereerNummer > Zoek nummer : @StartNummer = ' + @StartNummer + ' -> Niet gevonden');
          //Als nummer is gevuld
          set @Nummer  = @startnummer;
        else
          //---------- nummer kwam al voor --> verhogen ----------
          //call Trace('NawGenereerNummer > Zoek nummer : @StartNummer = ' + @StartNummer + ' -> Gevonden, dus verder zoeken naar vrij nummer');

          // Verhogen startnummer
          if (@Soort = 'C') or (@Soort = 'D') then
            set @Startnummer = String(cast(right(@Startnummer, @lengte - 2) as numeric(10,0)) + @stap); // ACW: cast niet naar integer, maar naar numeric(10,0)
            if length(@Startnummer) > @lengte - 2 then
              set @NieuwNummer = 2;      // Fout dus
            else
              Set @Startnummer = @paragraaf + Right('0000000000'+@startNummer,@lengte - 2);
            end if;
          else
            set @Startnummer = String(cast(@Startnummer as numeric(10,0)) + @stap); // ACW: cast niet naar integer, maar naar numeric(10,0)
            Set @Startnummer = Right('0000000000'+@startNummer, @NummerLengte);     // ACW: Nu o.b.v. lengte volgens vaste gegevens
          end if;

          if @NieuwNummer <> 2 and @nummer <> '' and not exists (select 1 from tabNawFile, tabNaw where nawfilNummer=@Startnummer and nawfilFonGid=@fonGID) then
            //@nummer word de nieuwe en @startnummer nieuwe in de vaste gegevens.
            set @NieuwNummer = 1;
          end if
        end if;
      end if;
    end loop;
    //call TraceEind('NawGenereerNummer > Einde loop');

    if @NieuwNummer=1 then
      //call Trace('NawGenereerNummer > Updaten nieuwe startnummer : @StartNummer = ' + @StartNummer);
      update tabFileOfNaw set fonStartNummer=@startnummer where fonGID=@fonGid;
    else
      //Het is niet goed gegaan. Zet daarom startnummer naar ''.
      set @startnummer = '';
    end if;
  end if;

  //NawGenereernummers-lock weer vrijgeven
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'NawGenereerNummer', '');

  set @@ErrorTextProcedure = 'NawGenereerNummer';
  //call TraceEind(@@ErrorTextProcedure + ' > @Nummer = ' + string(@Nummer));
end;


//$Workfile: NawHeeftSelectiecode.sp $ $Revision: 2 $ $Modtime: 2-04-08 12:45 $'

//---- Functie kijkt of een naw een bepaalde selectiecode heeft
if exists (select 1 from sys.sysProcedure where proc_name='NawHeeftSelectiecode') then
  drop function NawHeeftSelectiecode;
end if;

create function NawHeeftSelectiecode(in @SlcGid integer,in @FilGid integer,in @NawGid integer)
returns integer
begin
  declare @HeeftSelectie integer;

  //call TraceBegin('NawHeeftSelectiecode ( @SlcGid = '+String(@SlcGid)+', @FonGid = '+ String(@FonGid)+ ', @NawGid = '+ String(@NawGid) + ' ).');

  if @SlcGid is null then
    set @HeeftSelectie = 1;
  else
    set @HeeftSelectie = 0;
  end if;

  select 1 into @HeeftSelectie
  from tabSlcPerNaw
  where SpnnawfilGID    = @FilGid
    and SpnSlcGid       = @SlcGid;


  //call TraceEind('NawHeeftSelectiecode ------> @HeeftSelectie='+string(@HeeftSelectie));

  return(@HeeftSelectie);
  exception when others then resignal
end;


create or replace procedure NawImporteren(in @IelNummer integer, out @TotaalGeInsert integer, out @TotaalGeUpdate integer, in @ilogGid integer)
begin
  declare cursor_NawImport dynamic scroll cursor for
    select NiRegelNummer from tmpNawImport order by NiRegelNummer
    for read only;
  declare @HuidigRegelNummer         integer;
  declare @VorigRegelNummer          integer;

  //Variabelen om mee te geven aan NawInsert
  declare @NinawfilNummer            nchar(10);
  declare @NinawfilZoekcode          nchar(10);
  declare @NinawfilRksGID            integer;
  declare @NinawfilValNummer         integer;
  declare @NinawfilBtcNummer         integer;
  declare @NinawfilLvcNummer         integer;
  declare @NinawfilKredLimiet        numeric(15,2);
  declare @NinawfilBTWcode           integer;
  declare @NiNawBtwNummer            nchar(15);
  declare @NiNawOnsDebiteurNummer    nchar(20);
  declare @NiNawFilDebGrpGid         integer;
  declare @NiNawFilWelkeOrderkorting smallint;

  declare @NiNawAanmaningstype       smallint;
  declare @NiNawFacturerenInclBtw    smallint;
  declare @NiNawAparteFacturen       smallint;
  declare @NiNawAantalKopieFacturen  smallint;
  declare @NiNawOrderKorting         numeric(6,2);
  declare @NiNawVertegenwCode        integer;
  declare @NiNawFactuurAdres         smallint;
  declare @NiNawVerzendAdres         smallint;
  declare @NiNawBlokOrderInvoer      smallint;
  declare @NiNawContributieCode      integer;
  declare @NiTegenRksGid             integer;
  declare @NinawTaalGid              integer;
  declare @NinawrekBankRekening      nchar(34);
  //declare @NinawrekBankRekeningRekIsBuitenland smallint;
  declare @NinawrekIncassoRekening   nchar(34);
  //declare @NinawrekIncassoRekeningRekIsBuitenland smallint;

  declare @NiVestAdrNaam1            nchar(40);
  declare @NiVestAdrNaam2            nchar(40);
  declare @NiVestAdrStraat           nchar(40);
  declare @NiVestAdrHuisnummer       nchar(10);
  declare @NiVestAdrPostcode         nchar(40);
  declare @NiVestAdrPlaats           nchar(40);
  declare @NiVestAdrLndGid           integer;
  declare @NiVestAdrEMail            nchar(80);
  declare @NiVestAdrTelefoon         nchar(25);
  declare @NiVestAdrTelefoon2        nchar(25);
  declare @NiVestAdrTelefax          nchar(25);
  declare @NiNawWebsite              nchar(250);

  declare @NiCorAdrCode              integer;
  declare @NiCorAdrOms               nchar(40);
  declare @NiCorAdrNaam1             nchar(40);
  declare @NiCorAdrNaam2             nchar(40);
  declare @NiCorAdrStraat            nchar(40);
  declare @NiCorAdrHuisnummer        nchar(10);
  declare @NiCorAdrPostcode          nchar(40);
  declare @NiCorAdrPlaats            nchar(40);
  declare @NiCorAdrLndGid            integer;
  declare @NiCorAdrEMail             nchar(80);
  declare @NiCorAdrTelefoon          nchar(25);
  declare @NiCorAdrTelefoon2         nchar(25);
  declare @NiCorAdrTelefax           nchar(25);

  declare @NiVestAdrGid              integer;
  declare @NiCorAdrGid               integer;
  declare @NawGid                    integer;

  declare @IelFonGid                 integer;
  declare @IelNawGid                 integer;
  declare @IelNawsOverschrijven      smallint;

  //Vars om mooie update-statements mee op te bouwen:
  declare @UpdateNaw                nchar(2000);
  declare @UpdateRks                nchar(200);
  declare @UpdateNawFile            nchar(2000);
  declare @UpdateVestAdr            nchar(2000);
  declare @UpdateCorAdr             nchar(2000);
  declare @UpdateVerzAdr            nchar(2000);

  declare @StatementsGemaakt        smallint;
  declare @IelVeldnaam              nchar(40);      //nodig voor Update-loop
  declare @IelVorigeVeldnaam        nchar(40);      //nodig voor Update-loop
  declare @IelVeldDefaultWaardeOveralDoorvoeren  smallint;
  declare @IelVeldDefaultWaarde     smallint;      //nodig voor Update-loop

  declare @NAWNummerNietGegenereerdTekst long nvarchar;
  declare @NummerTekst                   long nvarchar;
  declare @NawNietOverschrevenTekst      long nvarchar;

  set @NAWNummerNietGegenereerdTekst = _A('NAW-nummer kan niet worden gegenereerd');
  set @NummerTekst                   = _A('Nummer %1!');
  set @NawNietOverschrevenTekst      = _A('NAW''s worden niet overschreven');

  //call Tracebegin('NawImporteren');

  set @TotaalGeInsert = 0;
  set @TotaalGeUpdate = 0;
  set @StatementsGemaakt = 0;


  if (@@ModuleD1 <> 0) then //Dealer Demo --> er mogen wel meer NAWs worden ingelezen
    Set @@AllowInsert = 1;
  end if;

  select IelFonGid,  IelNawGid,  IelNawsOverschrijven
   into  @IelFonGid, @IelNawGid, @IelNawsOverschrijven
   from  tabImportExportLayout
   where IelNummer = @IelNummer and IelSoort = 1;

  open cursor_NawImport;
  LoopRegels:
  loop
    //Deze volgende 2 statements bij elkaar houden want sqlState wordt na elk statement aangepast!
    Fetch next cursor_NawImport into @HuidigRegelNummer;
    if sqlstate = '02000' then
      leave LoopRegels;
    end if;

    //call Trace('@HuidigRegelNummer = ' + string(@HuidigRegelnummer));

    //1 record uit tmpNawImport in een berg variabelen zetten
    select NiNawfilNummer, NiNawfilZoekcode,
           NiNawfilValNummer, NiNawfilBtcNummer,
           NiNawfilLvcNummer, NiNawfilKredLimiet, NiNawfilBTWcode,
           NiVestadrNaam1, NiVestadrNaam2, NiVestadrStraat,
           NiVestadrHuisnummer, NiVestadrPostcode, NiVestadrPlaats,
           NiVestadrLndGid, NiVestadrEMail, NiVestadrTelefoon, NiVestadrTelefoon2, NiVestadrTelefax, NiNawWebsite,
           NiNawTaalGid, NiNawBtwNummer, NiNawAanmaningstype, NiNawOnsDebiteurNummer,
           NiNawFacturerenInclBtw, NiNawAparteFacturen,
           NiNawAantalKopieFacturen, NiNawOrderKorting, NiNawVertegenwCode,
           NiNawFactuurAdres, NiNawVerzendAdres,
           NiNawBlokOrderInvoer, NiNawContributieCode, NiTegenRksGid,
           NiCorAdrCode, NiCorAdrOms, NiCorAdrNaam1,  NiCorAdrNaam2, NiCorAdrStraat, NiCorAdrHuisnummer, NiCorAdrPostcode,
           NiCorAdrPlaats, NiCorAdrLndGid, NiCorAdrEMail, NiCorAdrTelefoon, NiCorAdrTelefoon2, NiCorAdrTelefax,
           NinawrekBankRekening, NinawrekIncassoRekening, NiNawFilDebGrpGid, NiNawFilWelkeOrderkorting //, NiNawRekBankRekeningIsBuitenland, NinawrekIncassoRekeningIsBuitenland
     into  @NiNawfilNummer, @NiNawfilZoekcode,
           @NiNawfilValNummer, @NiNawfilBtcNummer,
           @NiNawfilLvcNummer, @NiNawfilKredLimiet, @NiNawfilBTWcode,
           @NiVestAdrNaam1, @NiVestAdrNaam2, @NiVestAdrStraat,
           @NiVestAdrHuisnummer, @NiVestAdrPostcode, @NiVestAdrPlaats,
           @NiVestAdrLndGid, @NiVestAdrEMail, @NiVestAdrTelefoon, @NiVestAdrTelefoon2, @NiVestAdrTelefax, @NiNawWebsite,
           @NiNawTaalGid, @NiNawBtwNummer, @NiNawAanmaningstype, @NiNawOnsDebiteurNummer,
           @NiNawFacturerenInclBtw, @NiNawAparteFacturen,
           @NiNawAantalKopieFacturen, @NiNawOrderKorting, @NiNawVertegenwCode,
           @NiNawFactuurAdres, @NiNawVerzendAdres,
           @NiNawBlokOrderInvoer, @NiNawContributieCode, @NiTegenRksGid,
           @NiCorAdrCode, @NiCorAdrOms, @NiCorAdrNaam1,  @NiCorAdrNaam2, @NiCorAdrStraat, @NiCorAdrHuisnummer, @NiCorAdrPostcode,
           @NiCorAdrPlaats, @NiCorAdrLndGid, @NiCorAdrEMail, @NiCorAdrTelefoon, @NiCorAdrTelefoon2, @NiCorAdrTelefax,
           @NinawrekBankRekening, @NinawrekIncassoRekening, @NiNawFilDebGrpGid, @NiNawFilWelkeOrderkorting //, @NinawrekBankRekeningRekIsBuitenland, @NinawrekIncassoRekeningRekIsBuitenland
     from  tmpNawImport
     where NiRegelNummer = @HuidigRegelNummer;

    //eventueel zelf een nieuw nummer genereren
    if IsNull(@NiNawfilNummer, '') = '' then
    //call Trace('Nummer genereren..');
      call NawGenereerNummer(@IelFonGid, @NiNawFilNummer);
      //Als nummers op zijn, kunnen we niet meer verder inlezen. (bugid: 11146)
      if @NiNawFilNummer = '' then
        //call Trace('NAWNummer kan niet worden gegenereerd');
        call ImportLogDetail_Toevoegen(@ilogGid, @HuidigRegelNummer, @NAWNummerNietGegenereerdTekst, 6);
      end if;
    end if;

    //Als nawfilnummer nog steeds leeg is, doen we niets meer.
    if IsNull(@NiNawfilNummer, '') <> '' then
      //call Trace('Kijken of nummer ('+@NiNawFilNummer+') al bestaat in dit rel-bestand: @IelFonGid= '+ String(@IelFonGid));
      //Kijken of Naw al bestaat door RksGid op te zoeken (gelijk ook AdrGids ophalen voor de NAWUpdate)
      set @NawGid = null;
      select NawFilRksGid,    NawGidVestiging, NawGidCorrespondentie, NawGid
       into  @NiNawFilRksGid, @NiVestAdrGid,   @NiCorAdrGid, @NawGid
       from tabNawFile inner join tabNaw on (NawGid = NawFilNawGid)
       where NawFilNummer = @NiNawFilNummer and NawFilFonGid = @IelFonGid;
      //call Trace('na vullen variabelen van de naw.');

      //Notitie: (voorlopig) wordt bij het invoeren van adressen het AdrRelGid (contactpersoon) op null gezet, danwel met rust gelaten bij bestaande adressen.

      if @NawGid is null then
        //call Trace('Naw inserten Nummer: '+ @NiNawFilNummer);
        call NawInsert(@IelFonGID, @NiNawfilNummer, @NiNawfilZoekcode,
                       null, @NiNawfilValNummer, @NiNawfilBtcNummer,
                       @NiNawfilLvcNummer, @NiNawfilKredLimiet, 0, @NiNawfilBTWcode,
                       @NiVestAdrNaam1, @NiVestAdrNaam2, @NiVestAdrStraat,
                       @NiVestAdrHuisnummer, @NiVestAdrPostcode, @NiVestAdrPlaats, null,
                       @NiVestAdrLndGid, @NiVestAdrEMail, @NiVestAdrTelefoon, @NiVestAdrTelefax,
                       @NiNawTaalGid, null, null,
                       @NiNawBtwNummer, @NiNawAanmaningstype, @NiNawOnsDebiteurNummer,
                       @NiNawFacturerenInclBtw, @NiNawAparteFacturen, 0, null,
                       @NiNawAantalKopieFacturen, @NiNawOrderKorting, @NiNawVertegenwCode,
                       @NiNawFactuurAdres, @NiNawVerzendAdres, null,
                       @NiNawBlokOrderInvoer, @NiNawContributieCode, @NiTegenRksGid,
                       null, @NiNawFilDebGrpGid, @NiNawFilWelkeOrderkorting, null, null, null, null, null, null, null, null, null, null,
                       @NiVestAdrTelefoon2, @NiNawWebsite, null, @Nawgid);
                       // Vervoerder is er klaarblijkelijk bijgekomen zie #36631
        set @TotaalGeInsert = @TotaalGeInsert+1;
        //NawInsert maakt de naw en het vest-adres aan. Nu zelf een verzend of corresp-adres aanmaken:
        if @NiCorAdrCode is not null then
          if @NiCorAdrCode = 0 then
            //call Trace('Correspondentieadres aanmaken');
            //dan gaat het om een correspondentie adres --> AdrCode moet null zijn. Ook geen omschrijving.
            set @NiCorAdrCode = null;
            set @NiCorAdrOms  = '';
            insert into tabAdres (adrCode, adrEmail, adrHuisnummer, adrLndGid, adrNaam1, adrNaam2, adrNawGid, adrOms, adrPlaats, adrPostcode, adrRelGid, adrStraat, adrTelefax, adrTelefoon, adrTelefoon2)
                        values   (@NiCorAdrCode, @NiCorAdrEmail, @NiCorAdrHuisnummer, @NiCorAdrLndGid, @NiCorAdrNaam1, @NiCorAdrNaam2, @NawGid, @NiCorAdrOms, @NiCorAdrPlaats, @NiCorAdrPostcode, null, @NiCorAdrStraat, @NiCorAdrTelefax, @NiCorAdrTelefoon, @NiCorAdrTelefoon2);
            update tabNaw set nawGidCorrespondentie = @@Identity where NawGid = @NawGid;
          else
            //call Trace('Verzendadres aanmaken');
            //anders is het dus een verzendadres en staat het verder allemaal goed. Inserten die handel.
            insert into tabAdres (adrCode, adrEmail, adrHuisnummer, adrLndGid, adrNaam1, adrNaam2, adrNawGid, adrOms, adrPlaats, adrPostcode, adrRelGid, adrStraat, adrTelefax, adrTelefoon, adrTelefoon2)
                        values   (@NiCorAdrCode, @NiCorAdrEmail, @NiCorAdrHuisnummer, @NiCorAdrLndGid, @NiCorAdrNaam1, @NiCorAdrNaam2, @NawGid, @NiCorAdrOms, @NiCorAdrPlaats, @NiCorAdrPostcode, null, @NiCorAdrStraat, @NiCorAdrTelefax, @NiCorAdrTelefoon, @NiCorAdrTelefoon2);
          end if;
        end if;
        //Ook nog een bankrekening toevoegen indien die is ingelezen. Naam, Straat+Huisnr en Plaats overnemen uit vest-adres.
        if IsNull(@NinawrekBankRekening, '') <> '' then
          //call Trace('Bankrekening: '+String(@NiNawRekBankRekening)+ ' aanmaken bij nawgid: '+ String(@NawGid));
          insert into tabNawRekening (nawrekNaamRekHouder, NawRekAdresRekHouder, NawRekPostcodeRekHouder, NawRekLndGidRekHouder, nawrekBankRekeningInvoer, nawrekBankRekening, /*NawRekIsBuitenland, */nawrekNawGID, nawrekPlaatsRekHouder)
            select adrNaam1, adrStraat +' '+ adrHuisnummer, adrPostcode, adrLndGid, @NiNawRekBankRekening, BepaalNawRekBankRekening(@NiNawRekBankRekening), /*@NinawrekBankRekeningRekIsBuitenland,*/ @NawGid, adrPlaats from tabAdres where adrGid = (select nawGidVestiging from tabNaw where nawGid = @NawGid);
        end if;
        //Ook een incasso-bankrekening toevoegen op dezelfde manier, maar dan met 'I' in de RekSoort
        if IsNull(@NinawrekIncassoRekening, '') <> '' then
          //call Trace('Incassorekening: '+String(@NiNawRekIncassoRekening)+ ' aanmaken bij nawgid: '+ String(@NawGid));

          if not Exists(select 1 from tabNawRekening where nawrekBankRekeningInvoer = @NiNawRekIncassoRekening and NawRekNawgid = @NawGid) then
            //call Trace('Incassorekening: '+String(@NiNawRekIncassoRekening)+ ' aanmaken bij nawgid: '+ String(@NawGid));
            insert into tabNawRekening (nawrekNaamRekHouder, NawRekAdresRekHouder, NawRekPostcodeRekHouder, NawRekLndGidRekHouder, nawrekBankRekeningInvoer, nawrekBankRekening, /*nawRekIsBuitenland, */nawrekNawGID, nawrekPlaatsRekHouder, nawRekSoort)
              select adrNaam1, adrStraat +' '+ adrHuisnummer, adrPostcode, adrLndGid, @NiNawRekIncassoRekening, BepaalNawRekBankRekening(@NiNawRekIncassoRekening), /*@NinawrekIncassoRekeningRekIsBuitenland,*/ @NawGid, adrPlaats, 'I' from tabAdres where adrGid = (select nawGidVestiging from tabNaw where nawGid = @NawGid);
          //als deze incasso rekening al bestaat dan als Incasso rekening markeren zetten indien dat er nog niet bijstond
          else
            //call Trace('Incassorekening: '+String(@NiNawRekIncassoRekening)+ ' updaten bij nawgid: '+ String(@NawGid));
            update tabNawRekening set NawRekSoort = NawRekSoort + 'I' where (locate(IsNull(NawReksoort, ''), 'I')  = 0) and nawrekBankRekeningInvoer = @NiNawRekIncassoRekening and NawRekNawgid = @NawGid;
          end if;
        end if;
        //documenten overnemen van vaste gegevens:
        call VasteGegNawDocumentenOvernemen(@NawGid, @IelFonGid);
        //andere vaste gegevens, zoals betalingsconditie, btwcode worden niet overgenomen van vaste gegevens
        //wel evt van standaard naw, staat ook zo in ontwerp
        //documenten wel overgenomen, omdat die nooit in ascii bestand kunnen zitten, maar betalingsconditie/btwcode wel, JV 22 juni 2006
        //call Trace('Naw is geinsert -> log aanvullen');
        call ImportLogDetail_Toevoegen(@ilogGid, @HuidigRegelNummer, _P(@NummerTekst, @NiNawfilNummer), 0);

      else
        if @IelNawsOverschrijven = 1 then
          //note: bij updaten wordt correspondentie adres voorlopig met rust gelaten
          //call Trace('Naw updaten Nummer: '+ @NiNawFilNummer);

          //NawUpdate kunnen we niet gebruiken want we willen alleen die velden updaten die in de RecordLayout staan.
          //Dus nu zelf een updateStatement maken.
          if @StatementsGemaakt = 0 then

            //Nu alle ingelezen velden in het update-statement zetten
            set @IelVeldNaam = '';
            loopVelden :
            loop
              set @IelVorigeVeldnaam = @IelVeldNaam;

              set @IelVeldNaam = '';

              //call Trace('Zoek volgende veld in exportlayout');
              select  first IelVeldNaam,  IelVeldDefaultWaarde,  IelVeldDefaultWaardeOveralDoorvoeren
                into        @IelVeldNaam, @IelVeldDefaultWaarde, @IelVeldDefaultWaardeOveralDoorvoeren
              from  tabImportExportLayout left outer join tabImportExportLayoutVelden on IelVeldIelGid = IelGid
                where (IelNummer = @IelNummer) and (IelSoort = 1)
                  and (IelVeldDefaultWaarde > 0) and (IelVeldDefaultWaardeOveralDoorvoeren = 1)
                  and (IelVeldNaam > @IelVorigeVeldNaam)
                  and (IelVeldNaam <> 'NiNawRekBankRekening')
                  and (IelVeldNaam <> 'NiNawRekIncassoRekening')
                 order by IelVeldNaam;

              //call Trace('@IelveldNaam = '+ @ielVeldNaam + '; @IelVeldDefaultWaarde = '+String(@IelVeldDefaultWaarde));

              if IsNull(@IelVeldNaam, '') = '' then
                //call Trace('Breakie breakie...(loopVelden)');
                leave loopVelden;
              end if;

              //Nu kijken op welke tabel het gevonden veld betrekking heeft
              //Tegenrekening is weer eens een uitzondering...
              if @IelVeldNaam = 'NiTegenRksInvoer' then
                if (select FonId from tabFileOfNaw where FonGid = @IelFonGid) in ('D','C') then
                  set @UpdateRks = 'update tabRekeningschema set TegenRksGID = @NiTegenRksGid where RksGid = @NiNawfilRksGID';
                  // RS 14-10-09 bug 30387: de execute immediate verplaatst naar beneden
                end if;
              else
                //TaalCODE, ValCODE en LandOMS (2x) kunnen niet direct geupdate worden. Dit moet via de bijbehorende gidjes ipv codes.
                if left(@IelVeldNaam, 6) = 'NiVest' then //vestigingsadresveld
                  if @IelVeldNaam = 'NiVestLndOms' then
                    set @UpdateVestAdr = @UpdateVestAdr + 'AdrLndGid = @NiVestAdrLndGid,';
                  else
                    set @UpdateVestAdr = @UpdateVestAdr + substring(@IelVeldnaam,7) + ' = @' + @IelVeldNaam + ',';
                  end if;
                else
                  if left(@IelVeldNaam, 5) = 'NiCor' then  //correspondentieadres-veld
                    if @IelVeldNaam = 'NiCorLndOms' then
                      set @UpdateCorAdr = @UpdateCorAdr + 'AdrLndGid = @NiCorAdrLndGid,';
                    else
                      set @UpdateCorAdr = @UpdateCorAdr + substring(@IelVeldnaam,6) + ' = @' + @IelVeldNaam + ',';
                    end if;
                  else
                    if left(@IelVeldNaam, 8) = 'NiNawFil' then    //nawfile veld
                      set @UpdateNawFile = @UpdateNawFile + substring(@IelVeldnaam,3) + ' = @' + @IelVeldNaam + ',';
                    else   //dan is het tabnaw
                      if @IelVeldnaam = 'NiTaalCode' then
                        set @UpdateNaw = @UpdateNaw + 'NawTaalGid = @NiNawTaalGid,';
                      else
                        if @IelVeldnaam = 'NiValCode' then    //ValNummer zit echter weer in tabNawFile
                          set @UpdateNawFile = @UpdateNawFile + 'NawfilValNummer = @NiNawfilValNummer,';
                        else
                          if @IelVeldnaam = 'NiDebGrpNr' then    //NiNawFilDebGrpGid zit echter weer in tabNawFile
                            //MR 25-jan-2010 bug #31977: Wel naar tabNawFile kijken ipv tabNaw.
                            set @UpdateNawFile = @UpdateNawFile + 'NawFilDebGrpGid = @NiNawFilDebGrpGid,';
                          else
                            set @UpdateNaw = @UpdateNaw + substring(@IelVeldnaam,3) + ' = @' + @IelVeldNaam + ',';
                          end if;
                        end if;
                      end if;
                    end if;
                  end if;
                end if;
              end if;

            end loop loopVelden;

            //Nu update commandos erbij en de laatste komma aan het eind weghalen
            if @UpdateNaw <> '' then
              set @UpdateNaw = 'update tabNaw set ' + left(@UpdateNaw, length(@UpdateNaw)-1) + ' where NawGid = @nawGid';
            end if;
            if @UpdateNawFile <> '' then
              set @UpdateNawFile = 'update tabNawFile set ' + left(@UpdateNawFile, length(@UpdateNawFile)-1) + ' where NawFilNawGid = @nawGid';
            end if;
            if @UpdateVestAdr <> '' then
              set @UpdateVestAdr = 'update tabAdres set ' + left(@UpdateVestAdr, length(@UpdateVestAdr)-1) + ' where AdrGid = @NiVestAdrGid';
            end if;
            if @UpdateCorAdr <> '' then    //Verzend adres heeft iets andere where-part
              set @UpdateVerzAdr = @UpdateCorAdr;
              set @UpdateCorAdr  = 'update tabAdres set ' + left(@UpdateCorAdr, length(@UpdateCorAdr)-1) + ' where adrGid = @NiCorAdrGid';
              set @UpdateVerzAdr = 'update tabAdres set ' + left(@UpdateVerzAdr, length(@UpdateVerzAdr)-1) + ' where (adrCode = @NiCorAdrCode) and (adrNawGid = @NawGid)';
            end if;

            set @StatementsGemaakt = 1;
          end if;

        //call Trace('@UpdateRks='+@UpdateRks);
          execute immediate @UpdateRks;
        //call Trace('@UpdateNaw='+@UpdateNaw);
          execute immediate @UpdateNaw;
        //call Trace('@UpdateNawFile='+@UpdateNawFile);
          execute immediate @UpdateNawFile;
        //call Trace('@UpdateVestAdr='+@UpdateVestAdr);
          execute immediate @UpdateVestAdr;

          set @TotaalGeUpdate = @TotaalGeUpdate+1;
          //Bij bestaande naw, het corrsp-adres of verzendadres updaten als dat bestaat.
          if @NiCorAdrCode is not null then
            if @NiCorAdrCode = 0 then
              //dan gaat het om een correspondentie adres --> AdrCode moet null zijn. Ook geen omschrijving.
              set @NiCorAdrCode = null;
              set @NiCorAdrOms  = '';
              //Kijken of er een apart corresp-adres bestaat, dan die updaten.
              if exists(select 1 from tabNaw where (NawGidCorrespondentie <> NawGidVestiging) and (NawGid = @NawGid)) then
                //call Trace('Correspondentie adres updaten bij NawGid: '+String(@NawGid));
                //call Trace('@UpdateCorAdr=' + @UpdateCorAdr);
                execute immediate @UpdateCorAdr;
              else //anders is het vest-adres dus gelijk aan het corrsp-adres. Nu moeten we een nieuw adres aanmaken en als corresp-adres laten gelden:
                //call Trace('Correspondentie adres aanmaken');
                insert into tabAdres (adrCode, adrEmail, adrHuisnummer, adrLndGid, adrNaam1, adrNaam2, adrNawGid, adrOms, adrPlaats, adrPostcode, adrRelGid, adrStraat, adrTelefax, adrTelefoon, adrTelefoon2)
                            values   (@NiCorAdrCode, @NiCorAdrEmail, @NiCorAdrHuisnummer, @NiCorAdrLndGid, @NiCorAdrNaam1, @NiCorAdrNaam2, @NawGid, @NiCorAdrOms, @NiCorAdrPlaats, @NiCorAdrPostcode, null, @NiCorAdrStraat, @NiCorAdrTelefax, @NiCorAdrTelefoon, @NiCorAdrTelefoon2);
                //call Trace('Naw het nieuwe corrsp. adres geven');
                update tabNaw set nawGidCorrespondentie = @@Identity where NawGid = @NawGid;
              end if;
            else //anders is het een verzendadres.
              //kijken of dit verzendadres toevallig al bestaat, zoja updaten.
              if exists(select 1 from tabAdres where (adrNawGid = @NawGid) and (adrCode = @NiCorAdrCode)) then
                 //call Trace('Verzend adres updaten');
                 //call Trace('@UpdateVerzAdr='+@UpdateVerzAdr);
                 execute immediate @UpdateVerzAdr;
              else  //nieuw verzendadres inserten
                //call Trace('Verzend adres inserten');
                insert into tabAdres (adrCode, adrEmail, adrHuisnummer, adrLndGid, adrNaam1, adrNaam2, adrNawGid, adrOms, adrPlaats, adrPostcode, adrRelGid, adrStraat, adrTelefax, adrTelefoon, adrTelefoon2)
                            values   (@NiCorAdrCode, @NiCorAdrEmail, @NiCorAdrHuisnummer, @NiCorAdrLndGid, @NiCorAdrNaam1, @NiCorAdrNaam2, @NawGid, @NiCorAdrOms, @NiCorAdrPlaats, @NiCorAdrPostcode, null, @NiCorAdrStraat, @NiCorAdrTelefax, @NiCorAdrTelefoon, @NiCorAdrTelefoon2);
              end if;
            end if;
          end if;


          //Ook nog een bankrekening toevoegen indien die is ingelezen en nog niet bestaat. Naam, Straat+Huisnr en Plaats overnemen uit vest-adres.
          if IsNull(@NinawrekBankRekening, '') <> '' then
            //Kijken of bankrekening bestaat
            //VvE 18-11-2009: als we een IBAN inlezen kijken of die nog niet in de oude vorm bestaat
            if not Exists(select 1 from tabNawRekening where ((nawrekBankRekeningInvoer = @NiNawRekBankRekening) or (nawrekBankRekening = @NiNawRekBankRekening)) and NawRekNawgid = @NawGid) then
              //Vve: als we een oud nummer inlezen kijken of het nummer niet al als IBAN in de admin staat.
              if not Exists(select 1 from tabNawRekening where nawrekBankRekeningInvoer = BepaalNawRekBankRekening(@NiNawRekBankRekening) and NawRekNawGid = @NawGid) then
                //call Trace('Bankrekening: '+String(@NiNawRekBankRekening)+ ' aanmaken bij nawgid: '+ String(@NawGid));
                insert into tabNawRekening (nawrekNaamRekHouder, NawRekAdresRekHouder, NawRekPostcodeRekHouder, NawRekLndGidRekHouder, nawrekBankRekeningInvoer, nawrekBankRekening, /*NawRekIsBuitenland, */nawrekNawGID, nawrekPlaatsRekHouder)
                  select adrNaam1, adrStraat +' '+ adrHuisnummer, adrPostcode, adrLndGid, @NiNawRekBankRekening, BepaalNawRekBankRekening(@NiNawRekBankRekening), /*@NinawrekBankRekeningRekIsBuitenland,*/ @NawGid, adrPlaats from tabAdres where adrGid = (select nawGidVestiging from tabNaw where nawGid = @NawGid);
              end if;
            end if;
          end if;


          //En een incasso rekening toevoegen op dezelfde manier.
          if IsNull(@NinawrekIncassoRekening, '') <> '' then
            //Kijken of bankrekening bestaat
            if not Exists(select 1 from tabNawRekening where ((nawrekBankRekeningInvoer = @NiNawRekIncassoRekening) or (nawrekBankRekening = @NiNawRekIncassoRekening)) and NawRekNawgid = @NawGid) then
              //Vve: als we een oud nummer inlezen kijken of het nummer niet al als IBAN in de admin staat.
              if not Exists(select 1 from tabNawRekening where nawrekBankRekeningInvoer = BepaalNawRekBankRekening(@NiNawRekIncassoRekening) and NawRekNawGid = @NawGid) then
                //call Trace('Incassorekening: '+String(@NiNawRekIncassoRekening)+ ' aanmaken bij nawgid: '+ String(@NawGid));
                insert into tabNawRekening (nawrekNaamRekHouder, NawRekAdresRekHouder, NawRekPostcodeRekHouder, NawRekLndGidRekHouder, nawrekBankRekeningInvoer, nawrekBankRekening, /*NawRekIsBuitenland,*/ nawrekNawGID, nawrekPlaatsRekHouder, nawRekSoort)
                  select adrNaam1, adrStraat +' '+ adrHuisnummer, adrPostcode, adrLndGid, @NiNawRekIncassoRekening, BepaalNawRekBankRekening(@NiNawRekIncassoRekening), /*@NinawrekIncassoRekeningRekIsBuitenland,*/ @NawGid, adrPlaats, 'I' from tabAdres where adrGid = (select nawGidVestiging from tabNaw where nawGid = @NawGid);
              end if;
            //als deze incasso rekening al bestaat dan als Incasso rekening markeren zetten indien dat er nog niet bijstond
            else
              //call Trace('Incassorekening: '+String(@NiNawRekIncassoRekening)+ ' updaten bij nawgid: '+ String(@NawGid));
              //MR 25-jan-2010 bug #31576: kijk of I al in NawReksoort zit ipv of deze er wel in zit.
              update tabNawRekening set NawRekSoort = NawRekSoort + 'I' where (locate(IsNull(NawReksoort, ''), 'I') = 0) and ((nawrekBankRekeningInvoer = @NiNawRekIncassoRekening) or (nawrekBankRekening = @NiNawRekIncassoRekening)) and NawRekNawgid = @NawGid;
            end if;
          end if;
          //call Trace('Naw is geupdate -> log aanvullen');
          call ImportLogDetail_Toevoegen(@ilogGid, @HuidigRegelNummer, _P(@NummerTekst, @NiNawfilNummer), 1);
        else
          //call Trace('Naw is niet geupdate, want dat was zo ingesteld -> log aanvullen');
        call ImportLogDetail_Toevoegen(@ilogGid, @HuidigRegelNummer, @NawNietOverschrevenTekst, 3);
        end if;
      end if;
    end if;
  end loop LoopRegels;
  close cursor_NawImport;

  //tijdelijke records allemaal weggooien
  delete tmpNawImport;

  Set @@AllowInsert = 0;

  //call TraceEind('NawImporteren');

end;


create or replace procedure NawInsert(
  in @NawFilFonGID                  integer,
  in @nawfilNummer                  nchar(10),
  in @nawfilZoekcode                nchar(10),
  in @nawfilRksGID                  integer,
  in @nawfilValNummer               integer,
  in @nawfilBtcNummer               integer,
  in @nawfilLvcNummer               integer,
  in @nawfilKredLimiet              double,
  in @nawfilAutoOSP                 smallint,     // Obsolete
  in @nawfilBTWcode                 integer,
  in @adrNaam1                      nchar(40),
  in @adrNaam2                      nchar(40),
  in @adrStraat                     nchar(40),
  in @adrHuisnummer                 nchar(10),
  in @adrPostcode                   nchar(40),
  in @adrPlaats                     nchar(40),
  in @AdrEanCode                    nchar(13),
  in @adrLndGid                     integer,
  in @adrEMail                      nchar(80),
  in @adrTelefoon                   nchar(25),
  in @adrTelefax                    nchar(40),
  in @nawTaalGid                    integer,
  in @nawGidVestiging               integer,      // Wordt in NawInsert zelf al gevuld
  in @nawGidCorrespondentie         integer,      // Wordt in NawInsert zelf al gevuld
  in @nawBtwNummer                  nchar(15),
  in @nawAanmaningsType             smallint,
  in @nawOnsDebiteurNummer          nchar(20),
  in @nawFacturerenInclBtw          smallint,
  in @nawAparteFacturen             smallint,
  in @NawAparteLevering             smallint,
  in @NawIsDeelLeveringToegestaan   smallint,
  in @nawAantalKopieFacturen        integer,
  in @nawOrderKorting               double,
  in @nawVertegenwCode              integer,
  in @nawFactuurAdres               smallint,
  in @nawVerzendAdres               smallint,
  in @nawGidVerzendAdres            integer,
  in @nawBlokOrderInvoer            smallint,
  in @nawContributieCode            integer,
  in @TegenRksGid                   integer,
  in @nawIdFactDeb                  integer,
  in @NawFilDebGrpGid               integer,
  in @NawFilWelkeOrderkorting       smallint,
  in @NawFilWebNaw                  smallint,
  in @NawidDebOmzet                 integer,
  in @NawidDebPrijzen               integer,
  in @NawIsInkoopCombinatie         smallint,
  in @NawKvkNummer                  nchar(40),
  in @NawBedrijfstak                nchar(5),
  in @NawIncassantReferentie        nchar(35),
  in @nawBlokSupport                smallint,
  in @NawEindAdres                  smallint,
  in @NawGidEindAdres               integer,
  in @adrTelefoon2                  nchar(25),
  in @NawWebsite                    nchar(250),
  in @NawVrvGid                     integer,
 out @NawGid                        integer,
 out @NawFilGid                     integer,
 out @AdrGid                        integer,
  in @nawBtwNummerIsGeverifieerd    smallint default null,
  in @nawBtwNummerGeverifieerdOp    timestamp default null,
  in @nawBtwNummerNaam              nvarchar(40) default null,
  in @nawBtwNummerAdres             long nvarchar default null
)
//Vve: LET OP: Als hier parameters bijkomen, dan moeten programmas worden aangepast (NawImport ascii bijvoorbeeld). Zoek door de k5/app boom!
// Anders krijg je later uitklapper: "Invalid number of parameters calling 'NawInsert'!"
begin atomic
  declare @FonId  nchar(3);

  set @@ErrorTextProcedure = 'NawInsert > ';
  //call TraceBegin(@@ErrorTextProcedure + 'NawfilfonGID = ' + string(@NawFilFonGID) + ', NawFilNummer = ' + @NawFilNummer + ',adrNaam1 = ' + @adrNaam1 + ', adrLndGid = ' + string(@adrLndGid));

  select FonId into @FonId from tabFileOfNaw where FonGid = @NawFilFonGID;

  if @@FiredByProcNawInsert is null then
    set @@FiredByProcNawInsert = 1
  else
    set @@FiredByProcNawInsert = @@FiredByProcNawInsert + 1;
  end if;

  //call Trace('NawInsert > insert tabNaw');
  insert into tabNaw (nawTaalGid, nawGidVestiging, nawGidCorrespondentie, nawBtwNummer, nawBtwNummerIsGeverifieerd, nawBtwNummerGeverifieerdOp, nawBtwNummerNaam, nawBtwNummerAdres,
                      nawAanmaningsType, nawOnsDebiteurNummer, nawFacturerenInclBtw, nawAparteFacturen, NawAparteLevering, NawIsDeelLeveringToegestaan,
                      nawAantalKopieFacturen, nawOrderKorting, nawVertegenwCode, nawFactuurAdres,
                      nawVerzendAdres, nawGidVerzendAdres, nawBlokOrderInvoer, nawContributieCode, nawIdFactDeb,
                      NawidDebOmzet, NawidDebPrijzen, NawIsInkoopCombinatie, NawKvkNummer, NawBedrijfstak, NawIncassantReferentie,
                      NawBlokSupport, NawEindAdres, NawGidEindAdres, NawWebSite, NawVrvGid,
                      NawSoort)
              values (@nawTaalGid, @nawGidVestiging, @nawGidCorrespondentie, IsNull(@nawBtwNummer, ''), isNull(@nawBtwNummerIsGeverifieerd, 0), @nawBtwNummerGeverifieerdOp, @nawBtwNummerNaam, @nawBtwNummerAdres,
                      IsNull(@nawAanmaningsType, 1), IsNull(@nawOnsDebiteurNummer, ''), IsNull(@nawFacturerenInclBtw, 0), IsNull(@nawAparteFacturen, 0), IsNull(@NawAparteLevering, 0), IsNull(@NawIsDeelLeveringToegestaan, 2),
                      IsNull(@nawAantalKopieFacturen, 0), if @FonId = 'D' then IsNull(@nawOrderKorting, 0) else 0 endif, @nawVertegenwCode, IsNull(@nawFactuurAdres, 0),
                      IsNull(@nawVerzendAdres, 0), @nawGidVerzendAdres, IsNull(@nawBlokOrderInvoer, 0), @nawContributieCode, @nawIdFactDeb,
                      @NawidDebOmzet, @NawidDebPrijzen, IsNull(@NawIsInkoopCombinatie, 0), IsNull(@NawKvkNummer, ''), IsNull(@NawBedrijfstak, ''), IsNull(@NawIncassantReferentie, ''),
                      IsNull(@NawBlokSupport, 0), IsNull(@NawEindAdres, 3), @NawGidEindAdres, IsNull(@NawWebsite, ''), @NawVrvGid,
                      case @FonId when 'D' then 0 when 'C' then 1 when 'B' then 2 else 3 end);

  set @NawGid = @@Identity;

  //call Trace('NawInsert > insert tabNawFile');
  insert into tabNawFile (NawFilFonGID, NawFilFonId, nawfilNawGid, nawfilNummer, nawfilZoekcode, nawfilRksGID, nawfilValNummer,
                          nawfilBtcNummer, nawfilLvcNummer, nawfilKredLimiet, nawfilBTWcode,
                          NawFilDebGrpGid, NawFilWelkeOrderkorting, NawFilWebNaw)
              values     (@NawFilFonGID, @FonId, @NawGid, @nawfilNummer, @nawfilZoekcode, @nawfilRksGID, @nawfilValNummer, //ACW Vanuit Rks trigger aangemaakt, dan verwacht ik ook dat nawfilRksGid wordt gevuld, indien meegegeven
                          @nawfilBtcNummer, @nawfilLvcNummer, @nawfilKredLimiet, @nawfilBTWcode,
                          @NawFilDebGrpGid, @NawFilWelkeOrderkorting, @NawFilWebNaw);
  set @NawFilGid = @@Identity;

  //call Trace('NawInsert > insert tabAdres');
  insert into tabAdres   (adrNawGID, adrOms, adrNaam1, adrNaam2, adrStraat, adrHuisnummer, adrPostcode, adrPlaats,
                          adrTelefoon, adrTelefax, adrEmail, adrLndGID, AdrEanCode,
                          adrTelefoon2)
              values     (@Nawgid, 'Vestigingsadres', IsNull(@adrNaam1, ''), IsNull(@adrNaam2, ''), IsNull(@adrStraat, ''), IsNull(@adrHuisnummer, ''),
                          IsNull(@adrPostcode, ''), IsNull(@adrPlaats, ''), IsNull(@adrTelefoon, ''), IsNull(@adrTelefax, ''), IsNull(@adrEMail, ''), @adrLndGid, IsNull(@AdrEanCode, ''),
                          IsNull(@AdrTelefoon2, ''));
  set @AdrGid = @@Identity;

  //call Trace('NawInsert > update tabNaw');
  update tabNaw
  set    NawGidVestiging = @AdrGid, NawGidCorrespondentie = @AdrGid
  where  NawGid = @NawGid;

  if @FonId = 'D' or @FonId = 'C' then
    //call Trace('NawInsert > update tabRekeningschema');
    update tabRekeningSchema
    set    TegenRksGid = @TegenRksGid, RksNaam = @Adrnaam1
    where  (RksInvoer = @nawfilNummer)
       and (   isnull(TegenRksGid, '') <> isnull(@TegenRksGid, '')
            or isnull(RksNaam,     '') <> isnull(@Adrnaam1,    '')
           );
  end if;

  set @@FiredByProcNawInsert = @@FiredByProcNawInsert - 1;

  set @@ErrorTextProcedure = 'NawInsert';
  //call TraceEind(@@ErrorTextProcedure);
end;


  create or replace procedure NawUpdate(
    in @NawFilGid integer,
    in @nawfilFonGID integer,
    in @NawGID integer,
    in @adrGid integer,
    in @NawFilNummer nchar(10),
    in @NawFilZoekcode nchar(10),
    in @NawFilRksGid integer,
    in @nawfilValNummer integer,
    in @NawFilBtcNummer integer,
    in @nawfilLvcNummer integer,
    in @nawfilKredLimiet double,
    in @NawFilAutoOSP smallint,
    in @nawfilBTWcode integer,
    in @adrNaam1 nchar(40),
    in @AdrNaam2 nchar(40),
    in @adrStraat nchar(40),
    in @adrHuisnummer nchar(10),
    in @AdrPostcode nchar(40),
    in @adrPlaats nchar(40),
    in @AdrEanCode nchar(13),
    in @adrLndGid integer,
    in @adrEMail nchar(80),
    in @AdrTelefoon nchar(25),
    in @adrTelefax nchar(40),
    in @nawTaalGid integer,
    in @NawGidVestiging integer,
    in @nawGidCorrespondentie integer,
    in @nawBtwNummer nchar(15),
    in @NawAanmaningsType smallint,
    in @nawOnsDebiteurNummer nchar(20),
    in @NawFacturerenInclBtw smallint,
    in @nawAparteFacturen smallint,
    in @NawAparteLevering smallint,
    in @NawIsDeelLeveringToegestaan smallint,
    in @NawAantalKopieFacturen integer,
    in @nawOrderKorting double,
    in @nawVertegenwCode integer,
    in @NawFactuurAdres smallint,
    in @nawVerzendAdres smallint,
    in @nawGidVerzendAdres integer,
    in @NawBlokOrderInvoer smallint,
    in @nawContributieCode integer,
    in @TegenRksGid integer,
    in @nawIdFactDeb integer,
    in @NawFilDebGrpGid integer,
    in @NawFilWelkeOrderkorting smallint,
    in @NawFilWebNaw smallint,
    in @NawidDebOmzet integer,
    in @NawidDebPrijzen integer,
    in @NawIsInkoopCombinatie smallint,
    in @NawKvkNummer nchar(40),
    in @NawBedrijfstak nchar(5),
    in @NawIncassantReferentie nchar(35),
    in @NawBlokSupport smallint,
    in @NawEindAdres smallint,
    in @NawGidEindAdres integer,
    in @adrTelefoon2 nchar(25),
    in @NawWebsite nchar(250),
    in @NawVrvGid integer,
    in @nawBtwNummerIsGeverifieerd smallint default null,
    in @nawBtwNummerGeverifieerdOp timestamp default null,
    in @nawBtwNummerNaam nvarchar(40) default null,
    in @nawBtwNummerAdres long nvarchar default null
    )

  begin
    set @@ErrorTextProcedure = 'NawUpdate > ';
    //call TraceBegin(@@ErrorTextProcedure + '@NawFilGid = ' + string(@NawFilGid) + ', NawGid = ' + string(@NawGid) + ', @NawFilNummer = ' + @NawFilNummer + ', @NawFilZoekcode = ' + @NawFilZoekcode +', @NawFilRksGid = ' + string(@NawFilRksGid));

    update tabNaw
    set    nawTaalGid                  = @nawTaalGid,
           nawGidVestiging             = @nawGidVestiging,
           nawGidCorrespondentie       = @nawGidCorrespondentie,
           nawBtwNummer                = @nawBtwNummer,
           nawBtwNummerIsGeverifieerd  = isNull(@nawBtwNummerIsGeverifieerd, nawBtwNummerIsGeverifieerd),
           nawBtwNummerGeverifieerdOp  = isNull(@nawBtwNummerGeverifieerdOp, nawBtwNummerGeverifieerdOp),
           nawBtwNummerNaam            = isNull(@nawBtwNummerNaam, nawBtwNummerNaam),
           nawBtwNummerAdres           = isNull(@nawBtwNummerAdres, nawBtwNummerAdres),
           nawAanmaningsType           = @nawAanmaningsType,
           nawOnsDebiteurNummer        = @nawOnsDebiteurNummer,
           nawFacturerenInclBtw        = @nawFacturerenInclBtw,
           nawAparteFacturen           = @nawAparteFacturen,
           NawAparteLevering           = @NawAparteLevering,
           NawIsDeelLeveringToegestaan = @NawIsDeelLeveringToegestaan,
           nawAantalKopieFacturen      = @nawAantalKopieFacturen,
           nawOrderKorting             = @nawOrderKorting,
           nawVertegenwCode            = @nawVertegenwCode,
           nawFactuurAdres             = @nawFactuurAdres,
           nawVerzendAdres             = @nawVerzendAdres,
           nawGidVerzendAdres          = @nawGidVerzendAdres,
           nawBlokOrderInvoer          = @nawBlokOrderInvoer,
           nawContributieCode          = @nawContributieCode,
           nawIdFactDeb                = @nawIdFactDeb,
           NawidDebOmzet               = @NawidDebOmzet,
           NawidDebPrijzen             = @NawidDebPrijzen,
           NawIsInkoopCombinatie       = @NawIsInkoopCombinatie,
           NawKvkNummer                = @NawKvkNummer,
           NawBedrijfstak              = @NawBedrijfstak,
           NawIncassantReferentie      = @NawIncassantReferentie,
           NawBlokSupport              = @NawBlokSupport,
           NawEindAdres                = @NawEindAdres,
           NawGidEindAdres             = if NawEindAdres = 3 then null else @NawGidEindAdres endif,
           NawWebsite                  = @NawWebsite,
           NawVrvGid                   = @NawVrvGid
    where  nawGid = @nawGid;

    //call Trace('NawUpdate > update tabNawFile');
    update tabNawFile
    set    nawfilNummer                = @nawfilNummer,
           nawfilZoekcode              = @nawfilZoekcode,
           nawfilRksGID                = @nawfilRksGID,
           nawfilValNummer             = @nawfilValNummer,
           nawfilBtcNummer             = @nawfilBtcNummer,
           nawfilLvcNummer             = @nawfilLvcNummer,
           nawfilKredLimiet            = @nawfilKredLimiet,
           nawfilBTWcode               = @nawfilBTWcode,
           NawFilDebGrpGid             = @NawFilDebGrpGid,
           NawFilWelkeOrderkorting     = @NawFilWelkeOrderkorting,
           NawFilWebNaw                = @NawFilWebNaw
    where  nawfilGid = @nawfilGID;

    //call Trace('NawUpdate > update tabAdres');
    update tabAdres
    set    adrNaam1                    = @adrNaam1,
           adrNaam2                    = @adrNaam2,
           adrStraat                   = @adrStraat,
           adrHuisnummer               = @adrHuisnummer,
           adrPostcode                 = @adrPostcode,
           adrPlaats                   = @adrPlaats,
           adrLndGid                   = @adrLndGid,
           adrEMail                    = @adrEMail,
           adrTelefoon                 = @adrTelefoon,
           adrTelefoon2                = @adrTelefoon2,
           adrTelefax                  = @adrTelefax,
           adrEanCode                  = @adrEanCode
    where  adrGid = @adrGid;

    if (@NawFilRksGid is not null) then
      if (select IsNull(TegenRksGid, 0) from tabRekeningschema where RksGid = @NawFilRksGid) <> IsNull(@TegenRksGid, 0) then  //Als tegenrekening niet veranderd is, dan ook geen update doen
        //call Trace('NawUpdate > update tabRekeningschema');
        update tabRekeningSchema
        set    TegenRksGid = @TegenRksGid
        where  RksGid      = @NawFilRksGid
      end if;
    end if;

    set @@ErrorTextProcedure = 'NawUpdate';
    //call TraceEind('NawUpdate');
  end;


create or replace function NawValtBinnenSelectie(in @SelGid integer, in @NawFilGid integer )
returns integer
begin
  //---- functie controleert of een Naw binnen een selectie valt
  declare @SkGid      integer;
  declare @ValtBinnen integer;

  set @@ErrorTextProcedure = 'NawValtBinnenSelectie > ';
  //call TraceBegin(@@ErrorTextProcedure + 'SelGid = ' + string(@SelGid) + ', NawFilGid = ' + string(@NawFilGid));

  set @SkGid = null;
  select SelSkGid into @SkGid
  from   tabSelectie
  where  SelGid = @SelGid;

  if @SkGid is null then
    set @ValtBinnen = 1;
  else
    set @ValtBinnen = VoldoetAanKnoop(1, @SkGid, @NawFilGid, null);
  end if;

  set @@ErrorTextProcedure = 'NawValtBinnenSelectie';
  //call TraceEind(@@ErrorTextProcedure + ' > ValtBinnen = ' + string(@ValtBinnen));
  return(@ValtBinnen);
end;


create or replace function NumToStr(in @Num numeric(30,15), in @AantDec smallint)
returns nchar(30)
begin
  //Let op: de routines zijn maximaal 19 cijfers significant!!!!
  //Let op: maximaal aantal decimalen is 15!!!
  declare @Resultaat nchar(30);
  declare @hulp      nchar(20);

  //call TraceBegin('NumToStr > @Num = ' + string(@Num) + ', @AantDec = ' + string(@AantDec));
  set @resultaat='';
  if @AantDec=0 then
    //Geen fract, dus alleen 'voor de komma' rapporteren
    set @hulp=String( round( abs( @Num ), 0 ) ) ;
  else
    //fract bepalen
    if @AantDec > 15 then
      set @AantDec = 15;
    end if;
    set @hulp=string( round(@num,@AantDec) );
    if locate(@hulp,'.')<>0 then
      set @hulp=substr(@hulp, locate(@hulp,'.')+1);  //Alleen de fract
      set @Resultaat = left( @hulp+replicate( '0', @aantdec - length(@hulp) ), @AantDec );  //fract rechts uitgevuld met 0
    end if;
    //'voor de komma' bepalen
    set @hulp=String( floor( abs( @Num ) ) );
    set @hulp= left(@hulp, locate(@hulp+'.','.')-1); //omdat er soms decimalen achter komen, ondanks de floor!!
  end if;

  select if @Num < 0 then '-' endif + @hulp + if @AantDec > 0 then if TaalScheidingDecimalen=0 then '.' else if TaalScheidingDecimalen=1 then ',' else ' 'endif endif + @Resultaat endif into @Resultaat from tabVasteGegevens, tabTaal where TaalGid=DefaultTaalGid;

  //call TraceEind('NumToStr');
  return (@Resultaat)

end;


// ------------ OCR-berekeningen -------------------
create or replace function OCRBetalingskenmerk(in @BetKenmerk nchar(50))
  returns nchar(16)
begin
  declare @OCRbetKenmerk  nchar(16);
  declare @LengteCijfer   nchar(1);
  declare @ControleCijfer nchar(1);
  declare @IsValid        integer;
  declare @teller         integer;

  set @@ErrorTextProcedure = 'OCRBetalingskenmerk(@BetKenmerk='+@BetKenmerk + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  // Eerst controleren of het wel mogelijk is om deze om te zetten!
  set @IsValid = 1;
  set @teller = length(@BetKenmerk);
  while @teller >= 1 and @IsValid = 1 loop
    if locate('0123456789', substring(@BetKenmerk, @teller, 1)) = 0 then
      set @IsValid = 0;
    end if;
    set @teller = @teller - 1;
  end loop;


  if isnull(@BetKenmerk, '') = '' or @IsValid = 0 then
    set @OCRbetKenmerk = '';
  else
    // Eerst een lengtegetal ervoor plakken
    case
      when length(@BetKenmerk) > 15 then
        set @LengteCijfer = '';
        set @BetKenmerk   = '';
      when length(@BetKenmerk) = 15 then set @LengteCijfer = ''
      when length(@BetKenmerk) between 7 and 14 then set @LengteCijfer = right(string(length(@BetKenmerk)), 1);
      else
        set @LengteCijfer = '7';
        set @BetKenmerk = right('0000000' + @BetKenmerk, 7);
    end case;

    // Daarna controlegetal berekenen
    call OCRcalcControlecijfer(@LengteCijfer + @BetKenmerk, @ControleCijfer);

    // En indien mogelijk, alles aan elkaar plakken
    if @ControleCijfer = '' then
      set @OCRbetKenmerk = ''
    else
      set @OCRbetKenmerk = @ControleCijfer + @LengteCijfer + @BetKenmerk;
    end if;

  end if;

  set @@ErrorTextProcedure = 'OCRBetalingskenmerk(@BetKenmerk='+@BetKenmerk + ') => '+@OCRbetKenmerk;
  //call TraceEind(@@ErrorTextProcedure);

  return(@OCRbetKenmerk);


end;


create or replace procedure OCRcalcBetalingskenmerk(in @BetKenmerk nchar(50), out @OCRbetKenmerk nchar(16))
begin

  set @@ErrorTextProcedure = 'OCRcalcBetalingskenmerk(@BetKenmerk='+@BetKenmerk + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @OCRbetKenmerk = OCRBetalingskenmerk(@BetKenmerk);

  set @@ErrorTextProcedure = 'OCRcalcBetalingskenmerk(@BetKenmerk='+@BetKenmerk + ') => @OCRbetKenmerk=['+@OCRbetKenmerk+']';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure OCRcalcControlecijfer(in @Tekst nchar(50), out @Cijfer nchar(1))
begin

  declare @VeldLengte integer;
  declare @teller     integer;
  declare @som        integer;
  declare @resultaat  integer;

  declare @Gewicht    nchar(60);


  set @@ErrorTextProcedure = 'OCRcalcControlecijfer(@Tekst='+@Tekst + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  // Dit zijn de standaard gewichten gerekend vanaf de meest rechter karakter verlaagd met 1
  set @Gewicht = '1374986250';

  set @VeldLengte = length(@Tekst);
  set @som = 0;
  set @teller = @VeldLengte;
  while @teller >= 1 loop
    set @som = @som + cast(substring(@tekst, @VeldLengte - @teller + 1, 1) as integer) *
                      (1 + cast(substring(@Gewicht, mod(@teller - 1, 10) + 1, 1) as integer));
    //call trace(string(@teller)+' -> ' + substring(@tekst, @VeldLengte - @teller + 1, 1) + ' * ' + string((1 + cast(substring(@Gewicht, mod(@teller - 1, 10) + 1, 1) as integer))) + ' = ' + string(cast(substring(@tekst, @VeldLengte - @teller + 1, 1) as integer) * (1 + cast(substring(@Gewicht, mod(@teller - 1, 10) + 1, 1) as integer))));
    set @teller = @teller - 1;
  end loop;

  // Resultaat berekenen.
  // Indien 10, dan geldt: C=1
  // Indien 11, dan geldt: C=0
  // anders geldt: C = resultaat
  set @resultaat = 11 - mod(@som, 11);
  //call trace('Resultaat: 11 - ('+string(@som) + ' mod 11) = ' + string(@resultaat));
  case @resultaat
    when 10 then set @Cijfer = '1'
    when 11 then set @Cijfer = '0'
    else         set @Cijfer = String(@resultaat);
  end case;

  set @@ErrorTextProcedure = 'OCRcalcControlecijfer(@Tekst='+@Tekst + ') => @Cijfer=['+@Cijfer+']';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure OfferteAfwijzen(in @OffGid integer)
begin
  /* hulpvariabelen */
  declare @Tijdstip          DateTime   = Now();
  declare @RecordGevonden    bit        = 0;
  declare @OffStatus         smallint   = null;
  declare @OffOffertetotaal  numeric(15,2) = 0;

   /* constanten */
  declare @qcOffStatusOpenstaand smallint = 0;
  declare @qcOffStatusAfgewezen  smallint = 1;
  declare @qcOfkStatusVervallen  smallint = 5;

  declare @OfferteIsAfgewezenTekst long nvarchar;

  set @OfferteIsAfgewezenTekst = _A('Offerte is afgewezen.');

  //call TraceBegin('OfferteAfwijzen > @OffGid=' + string(@OffGid));

  /* benodigde gegevens ophalen */
  select               1, OffStatus,  OffOffertetotaal
  into   @RecordGevonden, @OffStatus, @OffOffertetotaal
  from   tabOfferte
  where OffGid = @OffGid;

  /* enkele essentiÃ«le controles uitvoeren */
  if @RecordGevonden <> 1 then
    call Raise(20365); /* (20365) Offerte is niet gevonden! */
  else
    if @OffStatus <> 0 then
      call Raise(20362); /* (20362) Offerte is reeds geaccepteerd of afgewezen! */
    end if;
  end if;

  /* laat alle nog niet vervallen versies van de meegegeven offerte vervallen en maak voor elk van de vervallen versies een logregel aan */
  insert into tabOfferteversieStatuslog with auto name
  select distinct
    updated_versies.OfkGid   as OfvsOfkGid,
    @@GebruikerCode          as OfvsGebruikerCode,
    @Tijdstip                as OfvsTijdstip,
    @OfferteIsAfgewezenTekst as OfvsToelichting,
    @qcOfkStatusVervallen    as OfvsStatus
  from
  ( update tabOfferteKop
       set OfkStatus = @qcOfkStatusVervallen
      from tabOfferte
     where OffGid = @OffGid and OfkOffGid = OffGid and /* update versies van meegegeven offerte */
           OffStatus = @qcOffStatusOpenstaand and /* alleen updaten als de offerte openstaand is */
           OfkStatus <> @qcOfkStatusVervallen /* en alle versies behalve reeds vervallen versies */
  ) REFERENCING (FINAL AS updated_versies);

  update tabOfferte
  set    OffStatus          = @qcOffStatusAfgewezen,
         OffEindstatusDoor  = @@GebruikerCode,
         OffEindstatusDatum = @Tijdstip,
         OffOffertetotaal   = IsNull(OffOffertetotaal, 0), /* offerte totaal moet gelijkblijven aan wat het was! */
         OffVerwachteOmzet  = 0 /* verwachte omzet op 0 zetten t.b.v. programma info marketing-events */
  where  OffGid = @OffGid;

  //call TraceEind('OfferteAfwijzen > @OffGid=' + string(@OffGid));
end;


create or replace procedure OfferteBepaalOffertetotaalObvBerekenmethode
(
 in  @OffGid integer,                       /* Offerte waarvoor de bedragen berekend moeten worden */
 in  @OverruleBerekenmethode smallint,      /* Indien overruled en een geldige waarde dan gebruiken we niet de waarde uit de database. Dit is voor als de waarde in de offerte in delphi wijzigt */
 in  @OverruleScoringskans   numeric(15,2), /* Indien overruled en een geldige waarde dan gebruiken we niet de waarde uit de database. Dit is voor als de waarde in de offerte in delphi wijzigt */
 out @BerekendOffertetotaal  numeric(15,2), /* Het berekende offertetotaal van de offerte obv de berekeningsmethode. */
 out @BerekendVerwachteOmzet numeric(15,2)  /* De berekende verwachte omzet van de offerte obv offertetotaal en de scoringskans */
)
begin
  /* variabelen t.b.v. recordwaarden */
  declare @OffStatus                      smallint      = -1; /* init met niet-bestaande waarde */
  declare @OffBerekenmethodeOffertetotaal smallint      = -1; /* init met niet-bestaande waarde */
  declare @OffOffertetotaal               numeric(15,2) = 0;  /* init */
  declare @OffScoringskans                numeric(15,2) = 100;/* init: 100% indien leeg */
  declare @OffVerwachteOmzet              numeric(15,2) = 0;  /* init */
  /* hulpvariabelen */
  declare @RecordGevonden                 bit           = 0;  /* default niet gevonden */
  declare @GeefHuidigeWaardenTerug        bit           = 0;  /* init; indien 1 dan geven we de bestaande waarden gewoon terug. */
  declare @AantDecTotalen                 smallint      = 2;  /* constante */
  declare @BjGid                          integer;
  declare @PerNr                          integer;

  /* tijdelijke tabellen */
  declare local temporary table tmpOverigeOpenstaandeOfferteversies
  (
    tmpOfkGid                   integer,
    tmpOfkStatus                smallint,
    tmpOfkVersienummer          smallint,
    tmpTotaalExBtwInBasisvaluta numeric(15,2)
  ) on commit preserve rows;

  //call TraceBegin('OfferteBepaalOffertetotaalObvBerekenmethode > @OffGid=' + string(@OffGid));

  /* Benodigde gegevens ophalen van de offerte. */
  select               1, OffStatus,  OffOffertetotaal,  OffScoringskans,  OffVerwachteOmzet,  OffBerekenmethodeOffertetotaal
    into @RecordGevonden, @OffStatus, @OffOffertetotaal, @OffScoringskans, @OffVerwachteOmzet, @OffBerekenmethodeOffertetotaal
    from tabOfferte
   where OffGid = @OffGid;

  /* Overrulen is mogelijk mits de waarde geldig is. Berekenmethode moet tussen 0 en 5 liggen (zie fieldcheck in metaeditor). Indien null dan -1, zodat deze een ongeldige waarde oplevert. */
  if IsNull(@OverruleBerekenmethode, -1) in (0,1,2,3,4,5) then
    set @OffBerekenmethodeOffertetotaal = @OverruleBerekenmethode;
  end if;

  /* Overrulen is mogelijk mits de waarde geldig is. Scoringskanspercentage moet tussen 0 en 100% liggen (zie check in delphi). Indien null dan -1, zodat deze een ongeldige waarde oplevert. */
  if IsNull(@OverruleScoringskans,-1) between 0 and 100 then
    set @OffScoringskans = @OverruleScoringskans;
  end if;

  /* boekjaar en periode bepalen t.b.v. omrekenen totalen in vreemde valuta naar basisvaluta. */
  call BepaalBoekjaarEnPeriode(@@Verwerkingsdatum, @BjGid, @PerNr);

  /* reken alle versietotalen om naar basisvaluta ex btw voor versies die goedgekeurd/uitgebracht zijn. */
  insert into tmpOverigeOpenstaandeOfferteversies with auto name
  select OfkGid          as tmpOfkGid,
         OfkStatus       as tmpOfkStatus,
         OfkVersienummer as tmpOfkVersienummer,
         if OfkValNummer <> @@BasisValutanummer then
           ValutaOmrekenen(OfkValNummer, if OfkBtwStand = 1 then OfkAfdruk_OffertetotaalAfgeleid else OfkAfdruk_Offertetotaal endif, @@BasisValutanummer, @BjGid, @PerNr, @AantDecTotalen)
         else
           if OfkBtwStand = 1 then OfkAfdruk_OffertetotaalAfgeleid else OfkAfdruk_Offertetotaal endif
         endif           as tmpTotaalExBtwInBasisvaluta
    from tabOfferteKop
   where OfkOffGid = @OffGid
     and OfkStatus in (1,2);

  if @RecordGevonden = 1 then
    /* berekenen op basis van de offertestatus */
    case @OffStatus
      when 2 then /* geaccepteerd: dit kan maar 1 record zijn. geen first: als er meer op geaccepteerd staan dan is de DB corrupt en is een uitklapper wenselijk. */
        set @BerekendOffertetotaal = (select tmpTotaalExBtwInBasisvaluta from tmpOverigeOpenstaandeOfferteversies where tmpOfkStatus = 3);
      when 1 then /* afgewezen: niets aanpassen, gewoon bestaande waarden teruggeven. */
        set @GeefHuidigeWaardenTerug = 1;
      else /* openstaand: berekenen obv berekenmethode: indien berekend, dan alleen over goedgekeurde en uitgebrachte versies van de offerte. */
        begin
          /* reken alle versietotalen om naar basisvaluta ex btw. LET OP: indien de tabel leeg is levert dit null-values op. later in de code dus eenmalig isnullen! */
          case @OffBerekenmethodeOffertetotaal
            when 1 then /* gemiddelde: alle versies omrekenen */
              set @BerekendOffertetotaal = (select Round(Avg(tmpTotaalExBtwInBasisvaluta), @AantDecTotalen) from tmpOverigeOpenstaandeOfferteversies);
            when 2 then /* laagste totaalbedrag: versie met het laatste offertetotaal excl btw in basis valuta pakken (eerste alle versies omrekenen naar ex btw in basisvaluta dus!) */
              set @BerekendOffertetotaal = (select first tmpTotaalExBtwInBasisvaluta from tmpOverigeOpenstaandeOfferteversies order by tmpTotaalExBtwInBasisvaluta);
            when 3 then /* hoogste totaalbedrag: versie met het hoogste offertetotaal excl btw in basis valuta pakken (eerste alle versies omrekenen naar ex btw in basisvaluta dus!) */
              set @BerekendOffertetotaal = (select first tmpTotaalExBtwInBasisvaluta from tmpOverigeOpenstaandeOfferteversies order by tmpTotaalExBtwInBasisvaluta desc);
            when 4 then /* eerste versie  : versie met laagste versienummer met status goedgekeurd/uitgebracht pakken. */
              set @BerekendOffertetotaal = (select first tmpTotaalExBtwInBasisvaluta from tmpOverigeOpenstaandeOfferteversies order by tmpOfkVersienummer, tmpOfkGid);
            when 5 then /* laatste versie : versie met hoogste versienummer met status goedgekeurd/uitgebracht pakken. */
              set @BerekendOffertetotaal = (select first tmpTotaalExBtwInBasisvaluta from tmpOverigeOpenstaandeOfferteversies order by tmpOfkVersienummer desc, tmpOfkGid desc);
            else /* 0 (= handmatig bedrag) of onbekende waarden: de huidige waarde teruggeven. */
              set @GeefHuidigeWaardenTerug = 1;
          end;
        end;
    end;
  end if;

  /* indien 1 dan gewoon de bestaande waarden teruggeven */
  if (@GeefHuidigeWaardenTerug = 1) then
    set @BerekendOffertetotaal  = IsNull(@OffOffertetotaal, 0);
    set @BerekendVerwachteOmzet = IsNull(@OffVerwachteOmzet, 0);
  else /* zelf berekend, dan nog even de verwachte omzet berekenen */
    set @BerekendOffertetotaal = IsNull(@BerekendOffertetotaal, 0);

    case @OffStatus
      when 2 then set @BerekendVerwachteOmzet = 0; /* indien geaccepteerd dan op 0 zetten */
      when 1 then set @BerekendVerwachteOmzet = IsNull(@OffVerwachteOmzet, 0); /* indien afgewezen dan intact laten */
      else        set @BerekendVerwachteOmzet = IsNull(Round((@BerekendOffertetotaal * (@OffScoringskans / 100)),@AantDecTotalen), 0); /* openstaand, uitrekenen dus */
    end;
  end if;

  //call TraceEind('OfferteBepaalOffertetotaalObvBerekenmethode > @OffGid=' + string(@OffGid));
end;

create or replace function OfferteGenereerTrajectnummer()
returns numeric(10,0)
begin
  declare @StartNummer numeric(10,0);
  declare @Gevonden    integer;
  declare @Nummer numeric(10,0);

  //call TraceBegin('OfferteGenereerTrajectnummer');

  set @Gevonden = 0;
  set @Nummer   = 1;

  select OfvgStartnummer into @StartNummer from tabOfferteVasteGegevens;

  while @Gevonden = 0
  loop
    set @Nummer = null;

    select Min(OffOffertenummer) into @Nummer from tabOfferte where OffOffertenummer >= @StartNummer;

    if @Nummer is null then
      set @Gevonden = 1;
      set @Nummer = @StartNummer;
    else
      if @Nummer = @StartNummer then

        // Dit nummer is er al, dus ophogen en weer opnieuw in loop (@Gevonden blijft 0)
        if @StartNummer = 9999999999 then
          set @StartNummer = 1;
        else
          set @StartNummer = @Nummer + 1;
        end if
      else
        // Eerstvolgende ligt toch hoger, dus we kunnen gewoon het StartNummer gebruiken
        set @Nummer = @StartNummer;
        set @Gevonden = 1;
      end if;
    end if;
  end loop;

  if @Nummer = 9999999999 then
    update tabOfferteVasteGegevens set OfvgStartnummer = 1;
  else
    update tabOfferteVasteGegevens set OfvgStartnummer = @Nummer + 1;
  end if;

  //call TraceEind('OfferteGenereerTrajectnummer');

  return(@Nummer);
end;

create or replace function OfferteregelBepaalDefaultTekstOpOfferte(
  in @ArtGid          integer,
  in @ArtPartijGid    integer,
  in @TaalGid         integer,
  in @SpecifiekeTekst smallint) /* 1=tekst van specifieke partij | 2=tekst van artikel in opgegeven taal | 3=tekst van artikel in default taal | 4=artikelomschrijving | andere waarden: de eerste die gevonden wordt. */
returns long nvarchar
begin
  declare @TekstOpOfferte long nvarchar = null;

  //call TraceBegin('OfferteregelBepaalDefaultTekstOpOfferte');

  if IsNull(@SpecifiekeTekst,-1) not in (1,2,3,4) then
    set @SpecifiekeTekst = -1;
  end if;

  select first TekstOpOfferte into @TekstOpOfferte
  from
    (
      /* TEKST OP FACTUUR VAN SPECIFIEKE PARTIJ (ALS VOOR PARTIJEN APARTE TEKSTEN BIJGEHOUDEN WORDEN */
      SELECT 1 as Volgnummer,
             ArtPartijTekstOpFactuur as TekstOpOfferte
      FROM   tabArtikelPartijTeksten
             inner join tabArtikelPartij on (ArtPartijGid=ArtPartijTekstArtPartijGid)
             inner join tabArtikel       on (ArtGid = @ArtGid and ArtGid=ArtPartijArtGid and ArtIsPartijAparteTekstOpFactuur=1)
      WHERE  ArtPartijTekstArtPartijGid = @ArtPartijGid and ArtPartijTekstTaalGid=@TaalGid and IsNull(ArtPartijTekstOpFactuur,'') <> ''
      UNION
      /* TEKST OP FACTUUR VAN ARTIKEL IN OPGEGEVEN TAAL */
      SELECT 2,
             ArtTekst
      FROM   tabArtikelTeksten
      WHERE  ArtTekstArtGid=@ArtGid and ArtTaalGid=@TaalGid and IsNull(ArtTekst,'') <> ''
      UNION
      /* TEKST OP FACTUUR VAN ARTIKEL IN DEFAULTTAAL */
      SELECT 3,
             ArtTekst
      FROM   tabArtikelTeksten inner join tabVasteGegevens on (DefaultTaalGid=ArtTaalGid)
      WHERE  ArtTekstArtGid = @ArtGid and IsNull(ArtTekst,'') <> ''
      UNION
      /* OMSCHRIJVING VAN ARTIKEL */
      SELECT 4,
             ArtOms
      FROM   tabArtikel
      WHERE  ArtGid = @ArtGid
      ORDER BY Volgnummer
    ) as TekstenOpOfferte
  where (@SpecifiekeTekst = -1 or Volgnummer=@SpecifiekeTekst)
  order by Volgnummer;

  return @TekstOpOfferte;

  //call TraceEind('OfferteregelBepaalDefaultTekstOpOfferte > @TekstOpOfferte=' + IsNull(@TekstOpOfferte, 'NULL'));
end;

create or replace procedure OfferteregelBerekenTotalen
(
  /* de scenarios die in deze procedure gebruikt worden zijn uitvoerig toegelicht op onderstaande wikipagina: */
  /* http://intranet.quadrant.local/wiki/index.php?title=Uitbreidingsmodel_op_Regeltotalen                    */

  /* inputparameters met waarden uit de offerteregel */
  in    @AantalTeOffreren                    numeric(15,3),
  in    @AantalTeOffrerenVrrdEenh            numeric(15,3),
  in    @AantalDecimalenVoorPrijzen          smallint,
  in    @Kostprijs                           numeric(15,3),
  in    @Prijs                               numeric(15,3),
  in    @GeprijsdPer                         numeric(15,3),
  in    @EenheidPrijsPer                     smallint,        //0=Verkoopeenheid, 1 = voorraadeenheid
  in    @Regelkorting1Bedrag                 numeric(15,2),
  in    @Regelkorting1Percentage             numeric(15,2),
  in    @Regelkorting2Percentage             numeric(15,2),
  in    @Stukskorting1Bedrag                 numeric(15,3),
  in    @Stukskorting1Percentage             numeric(15,2),
  in    @Stukskorting2Percentage             numeric(15,2),
  /* inout parameters die gevuld worden in deze proc */
  inout @Regeltotaal                         numeric(15,2),
  inout @RegeltotaalBruto                    numeric(15,2),
  inout @RegeltotaalKorting1Deel             numeric(15,2),
  inout @RegeltotaalKorting2Deel             numeric(15,2),
  inout @RegeltotaalKostprijs                numeric(15,2),
  inout @RegeltotaalNettoPrijsPerGeprijsdPer numeric(15,3),
  inout @RegeltotaalNettoPrijsPerStuk        numeric(15,3)
)
begin
  /* constanten */
  declare @qcAantalDecTotaalbedragen    smallint = 2;
  /* variabelen */
  declare @RegeltotaalScenario          smallint = -1; /* waarden die bepaald kunnen worden zijn 1 t/m 12; init met een waarde buiten de mogelijke keuzes dus! */
  declare @KostPrijsGeprijsdPer         numeric(15,3);     //De kostprijs geprijsd per is altijd geprijsd per. Geprijsd per word bij een prijs per verkoopeenheid gewijzigd. Deze dus hiervoor gelijkstellen aan de geprijsd per.

  //call TraceBegin('OfferteregelBerekenTotalen > @AantalTeOffreren=' + string(@AantalTeOffreren) + ', @AantalDecimalenVoorPrijzen=' + string(@AantalDecimalenVoorPrijzen) + ', @Kostprijs=' + string(@Kostprijs) + ', @Prijs=' + string(@Prijs) + ', @GeprijsdPer=' + string(@GeprijsdPer) + ', @Regelkorting1Bedrag=' + string(@Regelkorting1Bedrag) + ', @Regelkorting1Percentage=' + string(@Regelkorting1Percentage) + ', @Regelkorting2Percentage=' + string(@Regelkorting2Percentage) + ', @Stukskorting1Bedrag=' + string(@Stukskorting1Bedrag) + ', @Stukskorting1Percentage=' + string(@Stukskorting1Percentage) + ', @Stukskorting2Percentage=' + string(@Stukskorting2Percentage));

  /* init resultaatvelden */
  set @Regeltotaal                         = 0;
  set @RegeltotaalBruto                    = 0;
  set @RegeltotaalKorting1Deel             = 0;
  set @RegeltotaalKorting2Deel             = 0;
  set @RegeltotaalKostprijs                = 0;
  set @RegeltotaalNettoPrijsPerGeprijsdPer = 0;
  set @RegeltotaalNettoPrijsPerStuk        = 0;
  if @GeprijsdPer = 0 then
    set @GeprijsdPer = 1;
  end if;
  set @KostPrijsGeprijsdPer                = @GeprijsdPer;

  /* van toepassing zijnde regeltotaalscenario bepalen */
  begin
    declare @Korting1Waarde      smallint;
    declare @ManierWaarde        smallint;
    declare @Korting2Waarde      smallint;
    /* Het te gebruiken scenario wordt bepaald a.d.h.v. 3 inputs:                        */
    /* Korting1 is Nul (0), Bedrag (1) of Percentage (2)   weegfactor 1 */
    /* Manier   is Stuks (0) of Regel (1)                  weegfactor 3 */
    /* Korting2 is Nul (0) of Percentage (1)               weegfactor 6 */
    set @Korting1Waarde      = case when (@Stukskorting1Bedrag <> 0) or (@Regelkorting1Bedrag <> 0) then 1
                                    when (@Stukskorting1Percentage <> 0) or (@Regelkorting1Percentage <> 0) then 2
                                    else 0
                               end;

    set @ManierWaarde        = case when (@Regelkorting1Bedrag <> 0) or (@Regelkorting1Percentage <> 0) or (@Regelkorting2Percentage <> 0) then 1 /* één van de regelkortingvelden is gevuld -> regelkorting */
                                    when (@Stukskorting1Bedrag <> 0) or (@Stukskorting1Percentage <> 0) or (@Stukskorting2Percentage <> 0) then 0 /* één van de stukskortingvelden is gevuld -> stukskorting */
                                    else if IsNull((select first vofIsStukskorting from tabVasteGegevensOrdersFactureren), 0) = 1 then 0 else 1 endif /* geen kortingen ingevuld, dan in de vaste gegevens kijken wat de instelling is */
                               end;
    set @Korting2Waarde      = if (@Stukskorting2Percentage <> 0) or (@Regelkorting2Percentage <> 0) then 1 else 0 endif;

    /* JV gebruikte in de .net code een 0-based index. superirritant als je de situatiebeschrijvingen op de wiki ernaast legt die bij 1 begint, vandaar + 1 en een case die van 1 tot 12 loopt ipv 0 tot 11 zoals in .net*/
    set @RegeltotaalScenario = (@Korting1Waarde * 1) + (@ManierWaarde * 3) + (@Korting2Waarde * 6) + 1;
    //call Trace('OfferteregelBerekenTotalen > @RegeltotaalScenario='+string(@RegeltotaalScenario));
  end;

  /* Als de @EenheidPrijsPer per verkoopeenheid is gaan we de geprijsdPer aanpassen */
  if @EenheidPrijsPer = 1 then
    set @AantalTeOffreren = @AantalTeOffrerenVrrdEenh; //Als de regel prijs per voorraadeenheid is, dan de aantal te offreren aanpassen naar die van de voorraadeenheden
  else
    set @GeprijsdPer = 1; //Als per verkoopeenheid geprijs is, is dat altijd per 1 verkoopeenheid
  end if;

  /* regeltotaalbruto bepalen */
  set @RegeltotaalBruto = round(@AantalTeOffreren * (@Prijs / @GeprijsdPer), @qcAantalDecTotaalbedragen);

  /* bereken regeltotalen a.d.h.v. de bepaalde RegeltotaalScenario */
  case @RegeltotaalScenario
    when 1 then /* S01K1NulRekmStuksK2Nul */
      set @RegeltotaalNettoPrijsPerGeprijsdPer = @Prijs;
      set @Regeltotaal             = @RegeltotaalBruto;
      set @RegeltotaalKorting1Deel = 0;
      set @RegeltotaalKorting2Deel = 0;
    when 2 then /* S02K1BedRekmStuksK2Nul */
      set @RegeltotaalNettoPrijsPerGeprijsdPer = @Prijs - @Stukskorting1Bedrag;
      set @Regeltotaal             = round(@AantalTeOffreren * (@RegeltotaalNettoPrijsPerGeprijsdPer / @GeprijsdPer), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = @RegeltotaalBruto - @Regeltotaal;
      set @RegeltotaalKorting2Deel = 0;
    when 3 then /* S03K1PerRekmStuksK2Nul */
      set @RegeltotaalNettoPrijsPerGeprijsdPer = round(@Prijs * ((100 - @Stukskorting1Percentage) / 100), @AantalDecimalenVoorPrijzen);
      set @Regeltotaal             = round(@AantalTeOffreren * (@RegeltotaalNettoPrijsPerGeprijsdPer / @GeprijsdPer), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = @RegeltotaalBruto - @Regeltotaal;
      set @RegeltotaalKorting2Deel = 0;
    when 4 then /* S04K1NulRekmRegelK2Nul */
      set @Regeltotaal             = @RegeltotaalBruto;
      set @RegeltotaalKorting1Deel = 0;
      set @RegeltotaalKorting2Deel = 0;
      set @RegeltotaalNettoPrijsPerGeprijsdPer = if (@AantalTeOffreren = 0) then 0 else round(@Regeltotaal / (@AantalTeOffreren / @GeprijsdPer), @AantalDecimalenVoorPrijzen) endif;
    when 5 then /* S05K1BedRekmRegelK2Nul */
      /* .net note DG: aanpassing n.a.v. toestaan negatieve aantallen in het berekenen van regeltotalen in geval van regelkortingsbedragen. */
      set @Regeltotaal             = @RegeltotaalBruto - (sign(@AantalTeOffreren) * @Regelkorting1Bedrag); /* Regelkorting1Bedrag is altijd 2 dec, dus afronden is niet nodig */
      set @RegeltotaalKorting1Deel = @RegeltotaalBruto - @Regeltotaal;
      set @RegeltotaalKorting2Deel = 0;
      set @RegeltotaalNettoPrijsPerGeprijsdPer = if (@AantalTeOffreren = 0) then 0 else round(@Regeltotaal / (@AantalTeOffreren / @GeprijsdPer), @AantalDecimalenVoorPrijzen) endif;
    when 6 then /* S06K1PerRekmRegelK2Nul */
      set @Regeltotaal             = round((@AantalTeOffreren * (@Prijs / @GeprijsdPer)) * ((100 - @Regelkorting1Percentage) / 100), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = @RegeltotaalBruto - @Regeltotaal;
      set @RegeltotaalKorting2Deel = 0;
      set @RegeltotaalNettoPrijsPerGeprijsdPer = if @AantalTeOffreren = 0 then 0 else round(@Regeltotaal / (@AantalTeOffreren / @GeprijsdPer), @AantalDecimalenVoorPrijzen) endif;
    when 7 then /* S07K1NulRekmStuksK2Per */
      set @RegeltotaalNettoPrijsPerGeprijsdPer = round(@Prijs * ((100 - @Stukskorting2Percentage) / 100), @AantalDecimalenVoorPrijzen);
      set @Regeltotaal             = round(@AantalTeOffreren * (@RegeltotaalNettoPrijsPerGeprijsdPer / @GeprijsdPer), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = 0;
      set @RegeltotaalKorting2Deel = @RegeltotaalBruto - @Regeltotaal;
    when 8 then /* S08K1BedRekmStuksK2Per */
      set @RegeltotaalNettoPrijsPerGeprijsdPer = round((@Prijs - @Stukskorting1Bedrag) * ((100 - @Stukskorting2Percentage) / 100), @AantalDecimalenVoorPrijzen);
      set @Regeltotaal             = round(@AantalTeOffreren * (@RegeltotaalNettoPrijsPerGeprijsdPer / @GeprijsdPer), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = round(@AantalTeOffreren * (@Stukskorting1Bedrag / @GeprijsdPer), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting2Deel = @RegeltotaalBruto - @Regeltotaal - @RegeltotaalKorting1Deel;
    when 9 then /* S09K1PerRekmStuksK2Per */
      set @RegeltotaalNettoPrijsPerGeprijsdPer = round((@Prijs * ((100 - @Stukskorting1Percentage) / 100)) * ((100 - @Stukskorting2Percentage) / 100), @AantalDecimalenVoorPrijzen);
      set @Regeltotaal             = round(@AantalTeOffreren * (@RegeltotaalNettoPrijsPerGeprijsdPer / @GeprijsdPer), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = round(@AantalTeOffreren * (round(@Prijs * (@Stukskorting1Percentage / 100), @AantalDecimalenVoorPrijzen) / @GeprijsdPer), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting2Deel = @RegeltotaalBruto - @Regeltotaal - @RegeltotaalKorting1Deel;
    when 10 then /* S10K1NulRekmRegelK2Per */
      set @Regeltotaal             = round((@AantalTeOffreren * (@Prijs / @GeprijsdPer)) * ((100 - @Regelkorting2Percentage) / 100), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = 0;
      set @RegeltotaalKorting2Deel = @RegeltotaalBruto - @Regeltotaal;
      set @RegeltotaalNettoPrijsPerGeprijsdPer = if @AantalTeOffreren = 0 then 0 else round(@Regeltotaal / (@AantalTeOffreren / @GeprijsdPer), @AantalDecimalenVoorPrijzen) endif;
    when 11 then /* S11K1BedRekmRegelK2Per */
      /* .net note DG: aanpassing n.a.v. toestaan negatieve aantallen in het berekenen van regeltotalen in geval van regelkortingsbedragen. */
      set @Regeltotaal             = round(((@AantalTeOffreren * (@Prijs / @GeprijsdPer)) - (Sign(@AantalTeOffreren) * @Regelkorting1Bedrag)) * ((100 - @Regelkorting2Percentage) / 100), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = sign(@AantalTeOffreren) * @Regelkorting1Bedrag; /* Regelkorting1Bedrag is altijd 2 dec, dus afronden is niet nodig */
      set @RegeltotaalKorting2Deel = @RegeltotaalBruto - @Regeltotaal - @RegeltotaalKorting1Deel;
      set @RegeltotaalNettoPrijsPerGeprijsdPer = if @AantalTeOffreren = 0 then 0 else round(@Regeltotaal / (@AantalTeOffreren / @GeprijsdPer), @AantalDecimalenVoorPrijzen) endif;
    when 12 then /* S12K1PerRekmRegelK2Per */
      set @Regeltotaal             = round(((@AantalTeOffreren * (@Prijs / @GeprijsdPer)) * ((100 - @Regelkorting1Percentage) / 100)) * ((100 - @Regelkorting2Percentage) / 100), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting1Deel = round((@AantalTeOffreren * (@Prijs / @GeprijsdPer)) * (@Regelkorting1Percentage / 100), @qcAantalDecTotaalbedragen);
      set @RegeltotaalKorting2Deel = @RegeltotaalBruto - @Regeltotaal - @RegeltotaalKorting1Deel;
      set @RegeltotaalNettoPrijsPerGeprijsdPer = if @AantalTeOffreren = 0 then 0 else round(@Regeltotaal / (@AantalTeOffreren / @GeprijsdPer), @AantalDecimalenVoorPrijzen) endif;
    else
      raiserror 20361; /* (20361) Onbekend scenario voor berekenen totalen offerteregels! --> onduidelijk hoe totalen berekend moeten worden! */
  end; /* end case */

  /* overige velden berekenen */
  set @RegeltotaalNettoPrijsPerStuk = round(@RegeltotaalNettoPrijsPerGeprijsdPer / @GeprijsdPer, @AantalDecimalenVoorPrijzen);
  set @RegeltotaalKostprijs         = round(@AantalTeOffrerenVrrdEenh * (@Kostprijs / @KostPrijsGeprijsdPer), @qcAantalDecTotaalbedragen);

  //call TraceEind('OfferteregelBerekenTotalen > @Regeltotaal=' + string(@Regeltotaal) + ', @RegeltotaalBruto=' + string(@RegeltotaalBruto) + ', @RegeltotaalKorting1Deel=' + string(@RegeltotaalKorting1Deel) + ', @RegeltotaalKorting2Deel=' + string(@RegeltotaalKorting2Deel) + ', @RegeltotaalKostprijs=' + string(@RegeltotaalKostprijs) + ', @RegeltotaalNettoPrijsPerGeprijsdPer=' + string(@RegeltotaalNettoPrijsPerGeprijsdPer) + ', @RegeltotaalNettoPrijsPerStuk=' + string(@RegeltotaalNettoPrijsPerStuk));
end;


create or replace procedure OfferteRegelpositieVerschuiven(
 in @OfkGid         integer,
 in @StartOpPositie integer,   // Vanaf welk regelnummer doorschuiven (indien leeg, dan wordt 1 gebruikt!)
 in @Delta          integer    // Indien leeg, dan wordt 1 gebruikt (1 doorschuiven), maar nu kan ook worden teruggeschoven indien nodig (@delta=-1)
)
begin
  //call TraceBegin('OfferteRegelpositieVerschuiven(@OfkGid='+string(@OfkGid)+', @StartOpPositie='+string(@StartOpPositie)+', @Delta='+string(@Delta)+')');

  set @Delta = IsNull(@Delta, 1);
  set @StartOpPositie = IsNull(@StartOpPositie, 1);

  update tabOfferteregel
  set    OfrRegelpositie = OfrRegelpositie + @Delta
  where  OfrOfkGid = @OfkGid
     and OfrRegelpositie >= @StartOpPositie
  order by OfrRegelpositie * sign(@Delta) desc; // Bij negatief moeten we vanaf de kleinste werken, anders vanaf de grootste!

  //call TraceEind('OfferteRegelpositieVerschuiven(@OfkGid='+string(@OfkGid)+')');
end;

create or replace procedure OfferteRegelpositieWijzigen(
 in @OfrGid          integer,
 in @VerplaatsenNaar smallint, //0 = ga naar eerste regel, 1 = ga Ã©Ã©n positie omhoog, 2 = ga Ã©Ã©n positie omlaag, 3 = ga naar laatste regel, overig=ongeldige waarde
 out @NieuwePositie  smallint
)
begin
  declare @OfkGid                 integer;
  declare @MasterHuidigePositie   smallint;
  declare @MasterNieuwePositie    smallint;
  declare @MasterAantalVolgregels smallint;

  declare @LaatsteRegelpositie smallint;
  //call TraceBegin('OfferteRegelpositieWijzigen(@OfrGid=' + string(@OfrGid) + ', @VerplaatsenNaar=' + string(@VerplaatsenNaar) + ' (0=naar eerste regel, 1=een regel omhoog, 2=een regel omlaag, 3=naar laatste regel, overig=ongeldige waarde)');

  //bepalen of het een volgregel is, zo ja, dan master gidje als uitgangspunt gebruiken.
  set @OfrGid = IsNull((select OfrOfrGidVolgregelMaster from tabOfferteregel where OfrGid = @OfrGid), @OfrGid);
  //call Trace('definitieve @OfrGid=' + string(@OfrGid) + ' (= waarde hoofdregel (indien originele regel volgregel was)');

  //versiegidje en masterregel positie bepalen
  select OfrOfkGid, OfrRegelpositie into @OfkGid, @MasterHuidigePositie from tabOfferteregel where OfrGid = @OfrGid;
  //call Trace('@OfkGid=' + IsNull(string(@OfkGid), 'null') + ', @MasterHuidigePositie=' + IsNull(string(@MasterHuidigePositie),'null') + if (@OfkGid * @MasterHuidigePositie) is null then ' ==> PROCEDURE AFBREKEN: een of meer verplichte variabelen zijn null' endif);

  if @OfkGid is not null and @MasterHuidigePositie is not null then
    set @MasterAantalVolgregels = (select count(*) from tabOfferteregel where OfrOfrGidVolgregelMaster = @OfrGid);

    if not @VerplaatsenNaar between 0 and 3 then
      //call Trace('@VerplaatsenNaar=' + string(@VerplaatsenNaar) + ' ==> PROCEDURE AFBREKEN: ongeldige waarde @VerplaatsenNaar');
    else
      set @MasterNieuwePositie = (case @VerplaatsenNaar
                                   /*eerste regel */ when 0 then (select first OfrRegelpositie from tabOfferteregel where OfrOfkGid = @OfkGid and OfrOfrGidVolgregelMaster is null and OfrRegelpositie < @MasterHuidigePositie order by OfrRegelpositie)
                                   /*regel omhoog */ when 1 then (select first OfrRegelpositie from tabOfferteregel where OfrOfkGid = @OfkGid and OfrOfrGidVolgregelMaster is null and OfrRegelpositie < @MasterHuidigePositie order by OfrRegelpositie desc)
                                   /*regel omlaag */ when 2 then (select first OfrRegelpositie from tabOfferteregel where OfrOfkGid = @OfkGid and OfrOfrGidVolgregelMaster is null and OfrRegelpositie > @MasterHuidigePositie order by OfrRegelpositie)
                                   /*laatste regel*/ when 3 then (select first OfrRegelpositie from tabOfferteregel where OfrOfkGid = @OfkGid and OfrOfrGidVolgregelMaster is null and OfrRegelpositie > @MasterHuidigePositie order by OfrRegelpositie desc)
                                 end);
      //als het veld niet gevuld is dan is verplaatsen niet mogelijk en vullen we het huidige regelnummer in zodat er niets gebeurt.
      //call Trace(if @MasterNieuwePositie is null then '==> PROCEDURE AFBREKEN: @MasterNieuwePositie is null (waarschijnlijk was regel was al eerste of laatste regel)' else '@MasterNieuwePositie=' + string(@MasterNieuwePositie) endif);
    end if;

    set @MasterNieuwePositie = IsNull(@MasterNieuwePositie, @MasterHuidigePositie);

    if @MasterHuidigePositie <> @MasterNieuwePositie then
      //call Trace('de betreffende regel (en evt volgregels) uit de regelpositie verwijderen door regelpositie(s) negatief te maken');
      update tabOfferteregel
      set    OfrRegelpositie = -OfrRegelpositie
      where  OfrGid = @OfrGid
      or     OfrOfrGidVolgregelMaster = @OfrGid;

      if @MasterHuidigePositie > @MasterNieuwePositie then
        //call TraceBegin('Naar boven verplaatsen');
        update tabOfferteregel
        set    OfrRegelpositie = OfrRegelpositie + @MasterAantalVolgregels + 1
        where  OfrOfkGid = @OfkGid
           and OfrRegelpositie >= @MasterNieuwePositie
           and OfrRegelpositie <  @MasterHuidigePositie
        order by OfrRegelpositie desc;

        update tabOfferteregel
        set    OfrRegelpositie = @MasterNieuwePositie + number(*) - 1
        where  OfrGid = @OfrGid
        or     OfrOfrGidVolgregelMaster = @OfrGid
        order by OfrOfrGidVolgregelMaster, OfrRegelpositie desc;
        //call TraceEind('Naar boven verplaatsen');
      else
        //call TraceBegin('Naar beneden verplaatsen');
        begin
          declare @TargetOfrGid           integer;
          declare @TargetAantalVolgregels smallint;
          set @TargetOfrGid = (select first OfrGid from tabOfferteregel where OfrOfkGid = @OfkGid and OfrRegelpositie = @MasterNieuwePositie);
          set @TargetAantalVolgregels = (select count(*) from tabOfferteregel where OfrOfrGidVolgregelMaster = @TargetOfrGid);
          //call Trace('@TargetOfrGid=' + string(@TargetOfrGid) + ', @TargetAantalVolgregels=' + string(@TargetAantalVolgregels));

          //call Trace('update: volgende regel (en evt volgregels) omhoog schuiven');
          update tabOfferteregel
          set    OfrRegelpositie = OfrRegelpositie - @MasterAantalVolgregels - 1
          where  OfrOfkGid = @OfkGid
             and OfrRegelpositie >  @MasterHuidigePositie
             and OfrRegelpositie <= @MasterNieuwePositie + @TargetAantalVolgregels
          order by OfrRegelpositie;

          //call Trace('update: te verplaatsen regel (en evt volgregels) op nieuwe positie invoegen in range');
          update tabOfferteregel
          set    OfrRegelpositie = @MasterNieuwePositie - @MasterAantalVolgregels + @TargetAantalVolgregels + number(*) - 1
          where  OfrGid = @OfrGid
          or     OfrOfrGidVolgregelMaster = @OfrGid
          order by OfrOfrGidVolgregelMaster, OfrRegelpositie desc;
        end;
        //call TraceEind('Naar beneden verplaatsen');
      end if;
    end if;

    set @NieuwePositie = (select OfrRegelpositie from tabOfferteregel where OfrGid = @OfrGid);
  end if;

  //call TraceEind('OfferteRegelpositieWijzigen(@NieuwePositie=' + string(@NieuwePositie) + ')');
end;

create or replace procedure OfferteResetGegenereerdOffertenummer(in @Offertenummer numeric(10,0))
begin
  declare @Startnummer numeric(10,0);

  //call TraceBegin('OfferteResetGegenereerdOffertenummer');

  select OfvgStartnummer into @Startnummer from tabOfferteVasteGegevens;

  if (@Startnummer = @Offertenummer + 1) and (@Startnummer > 1) then
    update tabOfferteVasteGegevens set OfvgStartnummer=@Offertenummer;
  end if;

  //call TraceEind('OfferteResetGegenereerdOffertenummer');
end;

create or replace procedure OfferteversieAccepteren(in @OfkGid integer)
begin
  /* hulpvariabelen */
  declare @Tijdstip                  DateTime      = Now();
  declare @RecordGevonden            bit           = 0;
  declare @OffGid                    integer       = null;
  declare @OffStatus                 smallint      = null;
  declare @OfkStatus                 smallint      = null;
  declare @OfkOffertenummer          nchar(14)     = '';
  declare @OfkValNummer              integer       = null;
  declare @TotaalExBtwInVersieValuta numeric(15,2) = 0;

  /* constanten */
  declare @qcOffStatusGeaccepteerd   smallint = 2;
  declare @qcOfkStatusGeaccepteerd   smallint = 3;
  declare @qcOfkStatusVervallen      smallint = 5;

  /* tijdelijke tabellen */
  declare local temporary table tmpOverigeOpenstaandeOfferteversies (tmpOfkGid integer) on commit preserve rows;

  //call TraceBegin('OfferteversieAccepteren > @OfkGid=' + string(@OfkGid));

  /* benodigde gegevens ophalen */
  select               1, OffGid,  OffStatus,  OfkStatus,  OfkOffertenummer, OfkValNummer,   if OfkBtwStand = 1 then OfkAfdruk_OffertetotaalAfgeleid else OfkAfdruk_Offertetotaal endif
  into   @RecordGevonden, @OffGid, @OffStatus, @OfkStatus, @OfkOffertenummer, @OfkValNummer, @TotaalExBtwInVersieValuta
  from   tabOfferteKop
         inner join tabOfferte on (OffGid=OfkOffGid)
  where OfkGid = @OfkGid;

  /* enkele essentiÃ«le controles uitvoeren */
  if @RecordGevonden <> 1 then
    call Raise(20360); /* (20360) Offerteversie is niet gevonden! */
  else
    if @OffStatus <> 0 then
      call Raise(20362); /* (20362) Offerte is reeds geaccepteerd of afgewezen! */
    end if;
    if @OfkStatus <> 2 then
      call Raise(20363); /* (20363) Alleen uitgebrachte offerteversies mogen worden geaccepteerd! */
    end if;
  end if;

  /* zet alle andere offerteversies van dezelfde offerte die nog openstaan in een tijdelijke tabel. */
  insert into tmpOverigeOpenstaandeOfferteversies with auto name
  select OfkGid as tmpOfkGid from tabOfferteKop where OfkOffGid = @OffGid and OfkGid <> @OfkGid and OfkStatus not in (3, 5);

  /* wijzig de status van alle andere openstaande offerteversies naar vervallen. */
  update tabOfferteKop
  set    OfkStatus = @qcOfkStatusVervallen
  from   tmpOverigeOpenstaandeOfferteversies
  where  OfkGid = tmpOfkGid;

  /* maak statuslogregels aan voor de versies die nu zijn vervallen. */
  begin
    declare @StatusToelichting nchar(100);
    set @StatusToelichting = _A('Vervallen omdat versie %1! is geaccepteerd.', @OfkOffertenummer);

    insert into tabOfferteversieStatuslog with auto name
    select
      OfkGid                as OfvsOfkGid,
      @@GebruikerCode       as OfvsGebruikerCode,
      @Tijdstip             as OfvsTijdstip,
      @StatusToelichting    as OfvsToelichting,
      @qcOfkStatusVervallen as OfvsStatus
    from
      tmpOverigeOpenstaandeOfferteversies inner join tabOfferteKop on (tmpOfkGid=OfkGid and OfkStatus = @qcOfkStatusVervallen)
    where OfkOffGid = @OffGid and OfkGid <> @OfkGid;
  end;

  /* wijzig de status van de te accepteren offerteversie. */
  update tabOfferteKop
  set    OfkStatus = @qcOfkStatusGeaccepteerd
  where  OfkGid = @OfkGid;

  /* maak statuslogregel voor geaccepteerde versie aan */
  insert into tabOfferteversieStatuslog (OfvsOfkGid, OfvsGebruikerCode, OfvsTijdstip, OfvsToelichting, OfvsStatus)
  values (@OfkGid, @@GebruikerCode, @Tijdstip, '', @qcOfkStatusGeaccepteerd);



  /* offertetotaal ex btw in basisvaluta bepalen en update de offertestatus naar geaccepteerd. */
  begin
    declare @TotaalExBtwInBasisvaluta numeric(15,2) = 0;

    if @OfkValNummer <> @@BasisvalutaNummer then
      begin
        declare @AantDecTotalen smallint = 2; /*constante*/
        declare @BjGid integer;
        declare @PerNr integer;

        call BepaalBoekjaarEnPeriode(@@Verwerkingsdatum, @BjGid, @PerNr);
        set @TotaalExBtwInBasisvaluta = ValutaOmrekenen(@OfkValNummer, @TotaalExBtwInVersieValuta, @@BasisvalutaNummer, @BjGid, @PerNr, @AantDecTotalen);
      end
    else /* valuta versie is de basisvaluta, omrekenen niet nodig */
      set @TotaalExBtwInBasisvaluta = @TotaalExBtwInVersieValuta;
    end if;

    update tabOfferte
    set    OffStatus          = @qcOffStatusGeaccepteerd,
           OffEindstatusDoor  = @@GebruikerCode,
           OffEindstatusDatum = @Tijdstip,
           OffVerwachteOmzet  = 0, /* verwachte omzet op 0 zetten t.b.v. programma info marketing-events */
           OffOffertetotaal   = IsNull(@TotaalExBtwInBasisvaluta, 0) /* het regeltotaal van de geaccepteerde versie omgerekend naar ex btw in basisvaluta is het uiteindelijke offertetotaal */
    where  OffGid = @OffGid;
  end;

  //call TraceEind('OfferteversieAccepteren > @OfkGid=' + string(@OfkGid));
end;

create or replace procedure OfferteversieBerekenMarges
(
  /* input parameters */
  in  @OfkGid                                      integer,
  /* output parameters, berekend in deze proc */
  out @OffertetotaalVerkoopprijsExBtwInValuta      numeric(15,2),
  out @OffertetotaalVerkoopprijsExBtwInBasisvaluta numeric(15,2),
  out @OffertetotaalKostprijsExBtwInBasisvaluta    numeric(15,2),
  out @OffertetotaalMargebedragExBtwInBasisvaluta  numeric(15,2),
  out @OffertetotaalMargepercentageObvVerkoopprijs numeric(15,2),
  out @OffertetotaalMargepercentageObvKostprijs    numeric(15,2)
)
begin
  /* constanten */
  declare @qcAantalDecTotaalbedragen     smallint      = 2;
  /* variabelen obv offerteversierecord */

  declare @OfkBtwStand smallint;
  declare @OfkValNummer integer;
  declare @Offertetotaal numeric(15,2);
  declare @OffertetotaalAfgeleid numeric(15,2);
  declare @OffertetotaalKostprijs numeric(15,2);

  /* hulpvariabelen */
  declare @OfkGidBestaat smallint = 0;

  //call TraceBegin('OfferteversieBerekenMarges > @OfkGid=' + string(@OfkGid));

  /* init resultaatvelden */
  set @OffertetotaalVerkoopprijsExBtwInValuta       = 0;
  set @OffertetotaalVerkoopprijsExBtwInBasisvaluta  = 0;
  set @OffertetotaalKostprijsExBtwInBasisvaluta     = 0;
  set @OffertetotaalMargebedragExBtwInBasisvaluta   = 0;
  set @OffertetotaalMargepercentageObvVerkoopprijs  = 0;
  set @OffertetotaalMargepercentageObvKostprijs     = 0;

  /* benodigde gegevens van offerteversie ophalen */
  select 1, OfkBtwStand, OfkValNummer, OfkAfdruk_Offertetotaal, OfkAfdruk_OffertetotaalAfgeleid, OfkAfdruk_OffertetotaalKostprijs
   into @OfkGidBestaat, @OfkBtwStand, @OfkValNummer, @Offertetotaal, @OffertetotaalAfgeleid, @OffertetotaalKostprijs from tabOfferteKop where OfkGid = @OfkGid;

  /* marges berekenen als de offerteversie gevonden is */
  if @OfkGidBestaat = 1 then
    set @OffertetotaalVerkoopprijsExBtwInValuta = if (@OfkBtwStand = 1) then @OffertetotaalAfgeleid else @Offertetotaal endif;

    if (@OfkValNummer <> @@BasisValutaNummer) and (@OffertetotaalVerkoopprijsExBtwInValuta <> 0) then
      begin
        declare @BjGid integer;
        declare @PerNr integer;
        //call Trace('OffertetotaalBerekenMarges > Versie is in vreemde valuta -> reken totaalbedrag excl btw in vreemde valuta om naar totaalbedrag excl btw in basisvaluta.');
        call BepaalBoekjaarEnPeriode(@@Verwerkingsdatum, @BjGid, @PerNr);
        set @OffertetotaalVerkoopprijsExBtwInBasisvaluta = ValutaOmrekenen(@OfkValNummer, @OffertetotaalVerkoopprijsExBtwInValuta, @@BasisValutaNummer, @BjGid, @PerNr, @qcAantalDecTotaalbedragen);
      end;
    else
      set @OffertetotaalVerkoopprijsExBtwInBasisvaluta = @OffertetotaalVerkoopprijsExBtwInValuta;
    end if;


    set @OffertetotaalKostprijsExBtwInBasisvaluta   = @OffertetotaalKostprijs; /* TG 19-03-2012: de kostprijs is altijd ex btw en in basisvaluta, dus hoeft niet afh van btwstand berekend te worden. */
    set @OffertetotaalMargebedragExBtwInBasisvaluta = @OffertetotaalVerkoopprijsExBtwInBasisvaluta - @OffertetotaalKostprijsExBtwInBasisvaluta;

    /* OffertetotaalMargepercentageObvVerkoopprijs berekenen */
    if (@OffertetotaalVerkoopprijsExBtwInBasisvaluta = 0) then
      if (@OffertetotaalKostprijsExBtwInBasisvaluta = 0) then /* indien 0 */
        set @OffertetotaalMargepercentageObvVerkoopprijs = 0;
      else /* groter dan 0 (kleiner dan 0 kan niet, we staan geen negatieve prijzen in offertes toe) */
        set @OffertetotaalMargepercentageObvVerkoopprijs = -100;
      end if;
    else
      set @OffertetotaalMargepercentageObvVerkoopprijs = round((@OffertetotaalMargebedragExBtwInBasisvaluta / @OffertetotaalVerkoopprijsExBtwInBasisvaluta) * 100, @qcAantalDecTotaalbedragen);
    end if;


    /* OffertetotaalMargepercentageObvKostprijs berekenen */

    if (@OffertetotaalKostprijsExBtwInBasisvaluta = 0) then
      if (@OffertetotaalVerkoopprijsExBtwInBasisvaluta = 0) then /* indien 0 */
        set @OffertetotaalMargepercentageObvKostprijs = 0;
      else /* groter dan 0 (kleiner dan 0 kan niet, we staan geen negatieve prijzen in offertes toe) */
        set @OffertetotaalMargepercentageObvKostprijs = 100;
      end if;
    else
      set @OffertetotaalMargepercentageObvKostprijs = round((@OffertetotaalMargebedragExBtwInBasisvaluta / @OffertetotaalKostprijsExBtwInBasisvaluta) * 100, @qcAantalDecTotaalbedragen);
    end if;
  end if;

  //call TraceEind('OffertetotaalBerekenMarges > @OffertetotaalMargebedragExBtwInBasisvaluta=' + string(@OffertetotaalMargebedragExBtwInBasisvaluta) + ', @OffertetotaalMargepercentageObvVerkoopprijs=' + string(@OffertetotaalMargepercentageObvVerkoopprijs) + ', @OffertetotaalMargepercentageObvKostprijs=' + string(@OffertetotaalMargepercentageObvKostprijs));
end;

create or replace procedure OfferteversieBerekenTotalenEnBtwRegels(in @OfkGid integer)
begin
  /* constanten */
  declare @qcAantalDecTotaalbedragen smallint = 2;
  /* variabelen */
  declare @OfkBtwStand smallint;
  declare @OfkOrderKorting numeric(6,2);

  /* tabel om nieuwe btwregels tijdelijk in op te slaan. btwregel is een opsomming van de btwbedragen uit alle offerteregels van een versie, gegroepeerd per btwcode. */
  declare local temporary table tmpOfferteBtwRegel
  ( tmpGid                   integer         default autoincrement,
    tmpOfkGid                integer         not null,
    tmpBtwCode               integer         not null,
    tmpRegeltotaal           numeric(15,2)   not null, /*alleen opgeslagen zodat we hem niet 2x hoeven op te tellen t.b.v. berekenen bedragbtwdeel en btwgrondslag*/
    tmpBedragBtwDeel         numeric(15,2)   not null,
    tmpBedragBtwGrondslag    numeric(15,2)   not null
  ) on commit preserve rows;

  //call TraceBegin('OfferteversieBerekenTotalenEnBtwRegels > @OfkGid=' + string(@OfkGid));

  select OfkBtwStand, if exists(select 1 from tabVasteGegevensOrdersFactureren where vofOrderKortingSoort = 1 /* Als Orderkorting */) then OfkOrderKorting else 0 endif
    into @OfkBtwStand, @OfkOrderKorting
  from tabOfferteKop
  where OfkGid = @OfkGid  ;

  //call Trace('@OfkBtwStand=' + string(@OfkBtwStand));

  /* STAP 1: BEREKEN BTW-REGELS */
  //call Trace('Stap 1 van 2: bepaal BTW-regels en plaats in tijdelijke tabel.');
  insert into tmpOfferteBtwRegel with auto name
  select
    @OfkGid    as tmpOfkGid,
    OfrBtwCode as tmpBtwCode,
    round(sum(OfrAfdruk_Regeltotaal - (OfrAfdruk_Regeltotaal/100 * @OfkOrderKorting )), @qcAantalDecTotaalbedragen) as tmpRegeltotaal,
    if (@OfkBtwStand = 1) then /*incl btw*/
      round((tmpRegeltotaal / (100 + BtwPercentage)) * BtwPercentage, @qcAantalDecTotaalbedragen)
    else /* excl btw*/
      round((tmpRegeltotaal * (BtwPercentage / 100)), @qcAantalDecTotaalbedragen)
    endif as tmpBedragBtwDeel,
    if (@OfkBtwStand = 1) then /*incl btw*/
      round((tmpRegeltotaal / (100 + BtwPercentage)) * 100, @qcAantalDecTotaalbedragen)
    else /* excl btw*/
      tmpRegeltotaal
    endif as tmpBedragBtwGrondslag
  from
    tabofferteregel
    inner join tabBtw on (BtwCode=OfrBtwCode) /* inner join sluit offerteregels uit waarbij nog geen btw-code is ingevuld. deze worden pas meegenomen in de btwregels zodra deze ingevuld wordt */
  where OfrOfkGid = @OfkGid
  and   ofrRegelsoort in (1,2,3,4) /*alleen de bedragenregels, geen tekstregels meenemen. */
  group by OfrBtwCode, BtwPercentage;

  /* delete regels van niet meer voorkomende btw-codes uit de btwregels */
  //call Trace('Stap 1 van 2: delete regels van niet meer voorkomende btw-codes uit de btwregels.');
  delete from tabOfferteBtwRegel where OfbrOfkGid = @OfkGid and OfbrBtwCode not in (select tmpBtwCode from tmpOfferteBtwRegel where tmpOfkGid = @OfkGid);

  /* update bedragen van nog wel voorkomende btw-codes in de btwregels */
  //call Trace('Stap 1 van 2: update bedragen van nog wel voorkomende btw-codes in de btwregels.');
  update tabOfferteBtwRegel
     set OfbrBedragBtwDeel      = tmpBedragBtwDeel,
         OfbrBedragBtwGrondslag = tmpBedragBtwGrondslag
    from tmpOfferteBtwRegel
   where tmpOfkGid   = @OfkGid
     and OfbrOfkGid  = tmpOfkGid
     and OfbrBtwCode = tmpBtwCode;

  /* nog niet voorkomende btw-codes toevoegen aan de btwregels */
  //call Trace('Stap 1 van 2: nog niet voorkomende btw-codes toevoegen aan de btwregels.');
  insert into tabOfferteBtwRegel with auto name
  select
    tmpOfkGid  as OfbrOfkGid,
    tmpBtwCode as OfbrBtwCode,
    tmpBedragBtwDeel as OfbrBedragBtwDeel,
    tmpBedragBtwGrondslag as OfbrBedragBtwGrondslag
  from
    tmpOfferteBtwRegel
  where
    tmpOfkGid = @OfkGid and
    tmpBtwCode not in (select OfbrBtwCode from tabOfferteBtwRegel where OfbrOfkGid = @OfkGid and OfbrBtwCode = tmpBtwCode);

  /* STAP 2: OFFERTEVERSIETOTALEN BEREKENEN */
  begin
    declare @BtwRegelsBtwDeelTotaal    numeric(15,2) = 0;
    declare @Offertetotaal             numeric(15,2) = 0;
    declare @OffertetotaalAfgeleid     numeric(15,2) = 0;
    declare @OffertetotaalBruto        numeric(15,2) = 0;
    declare @OffertetotaalKorting1Deel numeric(15,2) = 0;
    declare @OffertetotaalKorting2Deel numeric(15,2) = 0;
    declare @OffertetotaalKostprijs    numeric(15,2) = 0;
    declare @OffertetotaalOrderkorting numeric(15,2) = 0;

    select
      sum(OfrAfdruk_Regeltotaal), sum(OfrAfdruk_RegeltotaalBruto),
      sum(OfrAfdruk_RegeltotaalKorting1Deel), sum(OfrAfdruk_RegeltotaalKorting2Deel),
      sum(OfrAfdruk_RegeltotaalKostprijs)
    into
      @Offertetotaal, @OffertetotaalBruto, @OffertetotaalKorting1Deel, @OffertetotaalKorting2Deel, @OffertetotaalKostprijs
    from
      tabOfferteregel
    where
      OfrOfkGid = @OfkGid
      and OfrRegelsoort in (1,2,3,4);

    /* TG 11-07-2011: voorheen werd OffertetotaalAfgeleid berekend als som van RegeltotaalAfgeleid, maar omdat de omrekening van incl naar excl BTW */
    /* en vice versa een afrondingsprobleem geeft wordt deze nu berekend op basis van de BTW-delen van de BTW-regels. (.net commentaar)             */
    set @BtwRegelsBtwDeelTotaal = IsNull((select sum(OfbrBedragBtwDeel) from tabOfferteBtwRegel where OfbrOfkGid = @OfkGid), 0);
    //call Trace('@BtwRegelsBtwDeelTotaal=' + string(@BtwRegelsBtwDeelTotaal));

    if exists(select 1 from tabVasteGegevensOrdersFactureren where vofOrderKortingSoort = 1 /* Als Orderkorting */) then
      set @OffertetotaalOrderkorting = (@Offertetotaal/100) * (select OfkOrderKorting from tabOfferteKop where OfkGid = @OfkGid);
      set @Offertetotaal = @Offertetotaal - @OffertetotaalOrderkorting;
    end if;

    set @OffertetotaalAfgeleid = if (@OfkBtwStand = 1) then /* incl btw */
                                   @Offertetotaal - @BtwRegelsBtwDeelTotaal /* offertetotaal is incl btw, dus btwdeel eraf */
                                 else
                                   @Offertetotaal + @BtwRegelsBtwDeelTotaal /* offertetotaal is excl btw, dus btwdeel erbij */
                                 end if;

    //call Trace('@OfkBtwStand=' + string(@OfkBtwStand) + ', @Offertetotaal=' + string(@Offertetotaal) + ', @OffertetotaalAfgeleid=' + string(@OffertetotaalAfgeleid) + ', @OffertetotaalBruto=' + string(@OffertetotaalBruto) + ', @OffertetotaalKorting1Deel=' + string(@OffertetotaalKorting1Deel) + ', @OffertetotaalKorting2Deel=' + string(@OffertetotaalKorting2Deel) + ', @OffertetotaalKostprijs=' + string(@OffertetotaalKostprijs));

    /* update totalen van offerteversie */
    //call Trace('Stap 2 van 2: Update totalen van offerteversie');
    update tabOfferteKop
       set OfkAfdruk_Offertetotaal             = IsNull(@Offertetotaal, 0),
           OfkAfdruk_OffertetotaalAfgeleid     = IsNull(@OffertetotaalAfgeleid, 0),
           OfkAfdruk_OffertetotaalBruto        = IsNull(@OffertetotaalBruto, 0),
           OfkAfdruk_OffertetotaalKorting1Deel = IsNull(@OffertetotaalKorting1Deel, 0),
           OfkAfdruk_OffertetotaalKorting2Deel = IsNull(@OffertetotaalKorting2Deel, 0),
           OfkAfdruk_OffertetotaalKostprijs    = IsNull(@OffertetotaalKostprijs, 0),
           OfkAfdruk_OffertetotaalOrderkorting = IsNull(@OffertetotaalOrderkorting, 0)
     where OfkGid = @OfkGid;
  end;

  //call TraceEind('OfferteversieBerekenTotalenEnBtwRegels');
end;


create or replace procedure OfferteversieRegelsBepaalKostPrijzenOpnieuw(in @OfkGid integer, in @Acceptatie bit)
begin
  declare @OfvgArtGidKortingstarief        integer = null;
  declare @OfvgArtGidInruiltarief          integer = null;
  declare @OfvgKostprijsTerugzetten        integer = null;
  declare @OfvgHuidigeKostprijzenNaarOrder integer = null;
  //call TraceBegin('OfferteversieRegelsBepaalKostPrijzenOpnieuw > @OfkGid=' + string(@OfkGid) + ', @Acceptatie=' + string(@Acceptatie));

  select OfvgArtGidKortingstarief,  OfvgArtGidInruiltarief,  OfvgKostprijsTerugzetten,  OfvgHuidigeKostprijzenNaarOrder
  into  @OfvgArtGidKortingstarief, @OfvgArtGidInruiltarief, @OfvgKostprijsTerugzetten, @OfvgHuidigeKostprijzenNaarOrder from tabOfferteVasteGegevens;

  update tabOfferteRegel
    inner join tabArtikel on ArtGid = (case OfrRegelSoort
                                       when 1 then OfrArtGidTarief
                                       when 2 then OfrArtGidArtikel
                                       when 3 then @OfvgArtGidKortingstarief
                                       when 4 then @OfvgArtGidInruiltarief
                                      end)
    left outer join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijGid = OfrArtPartijGid
  set OfrKostprijs = (if (ArtIsPartijAparteKostPrijs <> 0) and ArtPartijKostprijsEx is not null then ArtPartijKostprijsEx else ArtKostprijsEx endif)
  where OfrOfkGid = @OfkGid
    and OfrRegelSoort <> 0
    and ((@Acceptatie = 1 and @OfvgHuidigeKostprijzenNaarOrder = 1 and ArtIsKostprijsWijzigenInOrder = 0)
         or
         (@Acceptatie = 0 and ((@OfvgKostprijsTerugzetten = 0) or (@OfvgKostprijsTerugzetten = 1 and ArtIsKostprijsWijzigenInOrder = 0)))
        );

  //call TraceEind('OfferteversieRegelsBepaalKostPrijzenOpnieuw > @OfkGid=' + string(@OfkGid) + ', @Acceptatie=' + string(@Acceptatie));
end;

create or replace procedure OfferteversieRegelsBepaalPrijzenOpnieuw(in @OfkGid integer, @OfrGid integer default null, @UpdateAlleenBijStaffelkorting bit default 0)
begin
  /* hulpvariabelen */
  declare @RecordGevonden       bit           = 0;
  declare @UpdatesUitgevoerd    bit           = 0;
  declare @OffGid               integer       = null;
  declare @OffStatus            smallint      = null;
  declare @OfkStatus            smallint      = null;
  declare @OfkValNummer         integer       = null;
  declare @OfkBtwStand          smallint      = null;
  declare @GebruikBtwStand      smallint      = null;
  declare @GebruikNawGid        integer       = null;
  declare @BtwPercentage        numeric(6,2)  = null;
  declare @outPraVerkoopPrijs   numeric(15,3) = null;
  declare @outPraKortingsoort   smallint      = 0;
  declare @outPraKortingsPerc   numeric(6,2)  = null;
  declare @outPraKortingsBedrag numeric(15,3) = null;
  declare @outTypeAfspraak      integer       = null;
  declare @outPrijsPer          integer       = 1; //=default de prijs per voorraadeenheden
  declare @Prijs                numeric(15,3) = 0;
  declare @Kortingsperc         numeric(6,2)  = 0;
  declare @Kortingsbedrag       numeric(15,3) = 0;
  declare @IsStukskorting       smallint      = null;
  declare @ArtGid               integer       = null;
  declare @BtwCodeRegel         integer       = null;
  declare @BtwCodeFactDeb       integer       = null;
  declare @BtwPercFactDeb       numeric(6,2)  = null;

  //call TraceBegin('OfferteversieRegelsBepaalPrijzenOpnieuw > @OfkGid=' + string(@OfkGid) + ', @OfrGid=' + IsNull(string(@OfrGid), 'NULL') + ', @UpdateAlleenBijStaffelkorting=' + string(@UpdateAlleenBijStaffelkorting));

  /* benodigde gegevens ophalen; ivm defect #35894 wordt hier eerst gekeken of er een debiteur voor */
  /* prijzen is gespecificeerd bij de debiteur; zo ja, dan gebruiken we die voor de prijsafspraak   */
  select               1, OffGid, IsNull(OfkNawGidInkCombiPrijzen, OffNawGidDebiteur), OffStatus,  OfkStatus,  OfkValNummer,  OfkBtwStand,  BtwPercentage
  into   @RecordGevonden, @OffGid, @GebruikNawGid,                            @OffStatus, @OfkStatus, @OfkValNummer, @OfkBtwStand, @BtwPercentage
  from   tabOfferteKop
         inner join tabOfferte on (OffGid=OfkOffGid)
         left outer join (tabNawFile inner join tabNaw on (NawGid=NawFilNawGid)) on (NawFilNawGid=IsNull(OfkNawGidInkCombiPrijzen, OffNawGidDebiteur))
         left outer join tabBtw on (BtwCode=NawFilBtwCode)
  where OfkGid = @OfkGid;

  // Obv de factuurdebiteur (zoals bij orders) bepalen of het een NUL btwcode is
  select BtwCode,  BtwPercentage into @BtwCodeFactDeb, @BtwPercFactDeb
  from   tabOfferteKop
         inner join tabOfferte on (OffGid=OfkOffGid)
         left outer join (tabNawFile inner join tabNaw on (NawGid=NawFilNawGid)) on (NawFilNawGid=IsNull(OfkNawGidInkCombiFactuur, OffNawGidDebiteur))
         left outer join tabBtw on (BtwCode=NawFilBtwCode)
  where OfkGid = @OfkGid;

  /* kortingssoort instelling ophalen */
  set @IsStukskorting = (select first vofIsStukskorting from tabVasteGegevensOrdersFactureren);

  /* enkele essentiÃ«le controles uitvoeren */
  if @RecordGevonden <> 1 then
    call Raise(20360); /* (20360) Offerteversie is niet gevonden! */
  else
    if @OffStatus <> 0 then
      call Raise(20362); /* (20362) Offerte is reeds geaccepteerd of afgewezen! */
    end if;
    if @OfkStatus <> 0 then
      call Raise(20364); /* (20364) Alleen offerteversies met status ''Concept'' mogen worden gewijzigd! */
    end if;
  end if;

  /* TG 10-05-2012: uitleg wat hier gebeurt, en waarom:                                                                                        */
  /* Normaal gesproken wordt de BTW-stand van de offerteversie doorgegeven aan de prijsafspraken-stored proc. Er is echter 1 uitzondering:     */
  /* Als er een debiteur ingevuld is waarvan het default BTW-percentage 0% is, dan moet de prijs altijd op basis van exclusief BTW uitgerekend */
  /* worden, omdat het BTW-percentage (of de BTW-code) niet aan de stored proc kan worden meegegeven. Omdat het percentage in de regel 0% is,  */
  /* terwijl het artikel/tarief misschien ingevuld is met BTW hoog (momenteel 19%) dan zou het bedrag excl. btw verkeerd uitgerekend worden.   */
  /* LET OP: dit is geen eigen bedenksel, deze ietwat kromme oplossing zit ook in OrdersEdit in Delphi!!                                       */
  /* NB: dit is overgenomen commentaar uit .NET.                                                                                               */
  set @GebruikBtwStand = if IsNull(@BtwPercentage,-1) = 0 then 0 else @OfkBtwStand end if;

  /* Omdat we hier in een cursor meerdere regels van een offerteversie aanpassen willen we niet dat na elke wijziging van een regel */
  /* het versietotaal opnieuw berekend wordt. Dit doen we eenmalig zelf nadat alle regels geupdate zijn (= performance optimizer).  */
  set @@OverruleOfferteversieBerekenTotalen = @@OverruleOfferteversieBerekenTotalen + 1;

  for @Cursor AS CURSOR_BepaalPrijzenOpnieuw cursor for
    select OfrArtGidArtikel             as @OfrArtGidArtikel,
           OfrArtGidTarief              as @OfrArtGidTarief,
           OfrRegelsoort                as @OfrRegelsoort,
           OfrArtPartijGid              as @OfrArtPartijGid,
           OfrVkeGid                    as @OfrVkeGid,
           OfrAantalTeOffreren          as @OfrAantalTeOffreren,
           OfrAantalTeOffrerenVrrdEenh  as @OfrAantalTeOffrerenVrrdEenh
    from   tabOfferteregel
     where OfrOfkGid = @OfkGid /* alleen regels van opgegeven offerteversie */
       and (@OfrGid is null or (OfrGid = @OfrGid)) /* indien regelgid meegeven is dan die specifieke regel, en anders alle regels van de versie updaten */
       and OfrRegelsoort in (1,2) /* alleen tarief/artikelregels */
  for update
  do
    set @outPraVerkoopPrijs   = null;
    set @outPraKortingsPerc   = null;
    set @outPraKortingsBedrag = null;
    set @outTypeAfspraak      = null;
    set @outPrijsPer          = 1;
    set @Prijs                = 0;
    set @Kortingsperc         = 0;
    set @Kortingsbedrag       = 0;

    /* prijsafspraak ophalen */
    if @OfrRegelsoort = 2 then
      set @ArtGid = @OfrArtGidArtikel;
    else
      if @OfrRegelsoort = 1 then
        set @ArtGid = @OfrArtGidTarief;
      end if;
    end if;

    if @BtwPercFactDeb = 0.0 then
      select @BtwCodeFactDeb into @BtwCodeRegel
    else
      select ArtBtwCode into @BtwCodeRegel from tabArtikel where ArtGid = @ArtGid;
    end if;

    call BepaalPrijsAfspraak(/*input   */ @GebruikNawGid, @ArtGid, @OfrVkeGid, null, null, @OfrArtPartijGid, @GebruikBtwStand, @OfkValNummer,
                                          @OfrAantalTeOffreren, @OfrAantalTeOffrerenVrrdEenh, @@BasisValutaNummer, @@BasisvalutaCode, @@VerwerkingsDatum,
                             /* output */ null, null, null, null, /* <- deze outputs zijn niet nodig */
                                          @outPraVerkoopPrijs, @outPraKortingsoort, @outPraKortingsPerc, @outPraKortingsBedrag, @outTypeAfspraak, null, @outPrijsPer);

    /* indien we volgregels updaten vanuit trigger tua_tabOfferteregel dan moeten we de volgregels alleen aanpassen als er een staffelkorting actief is. */
    if (@UpdateAlleenBijStaffelkorting = 0) or Mod(@outTypeAfspraak, 10) = 1 then
      //call Trace('OfferteversieRegelsBepaalPrijzenOpnieuw > Staffelkorting gevonden -> offertevolgregel updaten');

      set @outPraVerkoopPrijs   = IsNull(@outPraVerkoopPrijs, 0);
      set @outPraKortingsBedrag = IsNull(@outPraKortingsBedrag, 0);
      set @outPraKortingsPerc   = IsNull(@outPraKortingsPerc, 0);

      /* -1- Negatieve brutoverkoopprijs --> ongeldig dus alles 0 laten zoals bij de declaratie van variabelen gedaan is. */
      //indien de bruto verkoopprijs negatief is, dan geven we alleen 0-waarden terug.
      if @outPraVerkoopPrijs >= 0 then
        /* -2- Op regelkorting en een Kortingsbedrag uit prijsafspraken --> maak hier kortingspercentage van, afgerond op 2 decimalen */
        if @IsStukskorting = 0 and (@outPraKortingsoort = 2) then
          set @outPraKortingsPerc   = if @outPraVerkoopPrijs = 0 then 0 else Round((@outPraKortingsBedrag / @outPraVerkoopPrijs) * 100, 2) end if;
          set @outPraKortingsBedrag = 0;
        end if;

        /* -3- Negatieve korting(percentage ) --> verwerk deze toeslag in de brutoverkoopprijs, en maak de korting 0. */
        if (@outPraKortingsPerc < -100.00) or (@outPraKortingsPerc > 100.00) then
          /* als de korting negatief is dan kunnen we dat niet kwijt in het domein. Derhalve wordt de korting direct opgeteld bij het bedrag.       */
          /* het is sowieso raar om op een offerte te zetten dat je -20% korting geeft, waardoor de klant meer dan de standaard prijs moet betalen. */
          /* Voorbeeld prijs = 100 euro, korting -20% => 100 * (100 - -20)/100 => 100 * (120/100) => 100 * 1.2 => 120 euro                          */
          set @Prijs    = @outPraVerkoopPrijs * ((100 - @outPraKortingsPerc) / 100);
          set @Kortingsperc = 0;
        else
          set @Prijs          = @outPraVerkoopPrijs;
          set @Kortingsbedrag = @outPraKortingsBedrag;
          set @Kortingsperc   = @outPraKortingsPerc;
        end if;
      end if;

      update tabOfferteregel
         set OfrPrijs = @Prijs,
             OfrBtwCode = @BtwCodeRegel,
             OfrRegelkorting1Bedrag     = if @IsStukskorting = 0 then @Kortingsbedrag else OfrRegelkorting1Bedrag endif,
             OfrRegelkorting1Percentage = if @IsStukskorting = 0 then @Kortingsperc   else OfrRegelkorting1Percentage endif,
             OfrStukskorting1Bedrag     = if @IsStukskorting = 1 then @Kortingsbedrag else OfrStukskorting1Bedrag endif,
             OfrStukskorting1Percentage = if @IsStukskorting = 1 then @Kortingsperc   else OfrStukskorting1Percentage endif,
             OfrEenheidPrijsPer         = @outPrijsPer
       where current of CURSOR_BepaalPrijzenOpnieuw;

      set @UpdatesUitgevoerd = 1; /* performance optimizer */
    end if;
  end for;

  // Evt de btwcodes bijwerken indien afstandsverkopen
  if exists(select 1 from tabRegistry where RegKey = 'AFSTANDSVERKOPEN' and Contents = '1') then
    call UpdateOfferteRegelsBtwCodeAfstandsVerkopen(null /*OffGid*/, @OfkGid, null /*AfleverLndGid*/);
  end if;

  /* overrule weer uitgeschakelen. */
  set @@OverruleOfferteversieBerekenTotalen = @@OverruleOfferteversieBerekenTotalen - 1;

  /* als er daadwerkelijk een of meer regels geupdate zijn dan moet het totaal hier herberekend worden. */
  if @UpdatesUitgevoerd = 1 then
    call OfferteversieBerekenTotalenEnBtwRegels(@OfkGid);
  end if;

  //call TraceEind('OfferteversieRegelsBepaalPrijzenOpnieuw > @OfkGid=' + string(@OfkGid) + ', @OfrGid=' + IsNull(string(@OfrGid), 'NULL') + ', @UpdateAlleenBijStaffelkorting=' + string(@UpdateAlleenBijStaffelkorting));
end;

create or replace function OmgerekendBtcRegel(in @regel nchar(1024), in @btcnummer integer, in @taalgid integer, in @valnummer integer, in @FactuurDatum date, in @BtcBedrag numeric(15,2))
returns nchar(1024)
begin
  declare @FormatDate nchar(80);
  declare @vervaldatum date;
  declare @incassodatum date;
  declare @FormatKort nchar(40);
  declare @formatMiddel nchar(40);
  declare @formatLang nchar(40);
  //De verschillende delen van de regel wijzigen

  //<P> Percentage van de betalingskorting
  set @regel = ReplaceInString(@regel, '<P>', NumToStr((select Percentage from tabBetalingsconditie where BtcNummer=@BtcNummer),2) );

  //<#> Bedrag van de betalingskorting
  set @regel = ReplaceInString(@regel, '<#>', NumToStr(@BtcBedrag,(select decimalenboeking*2 from tabvaluta where ValNummer=@ValNummer)) );

  // <DF-?> vervaldatum factuur
  if charindex( '<DF-', @regel ) <> 0 then
    call BerekenVervalDatumFactuur(@FactuurDatum, @BtcNummer, @VervalDatum);
    select TaalDatumKort, TaalDatumMiddel, TaalDatumLang into @FormatKort, @formatMiddel, @formatLang from tabTaal where TaalGid = @TaalGid;
    call DatumFormat(@VervalDatum, @FormatKort,   @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DF-k>', @FormatDate );
    call DatumFormat(@VervalDatum, @formatMiddel, @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DF-m>', @FormatDate );
    call DatumFormat(@VervalDatum, @formatLang,   @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DF-l>', @FormatDate );
  end if;

  // <DK-?> vervaldatum kredietbep./betalingskorting
  if charindex( '<DK-', @regel ) <> 0 then
    call BerekenKredBepVervalDatumFactuur(@FactuurDatum, @BtcNummer, @VervalDatum);
    select TaalDatumKort, TaalDatumMiddel, TaalDatumLang into @FormatKort, @formatMiddel, @formatLang from tabTaal where TaalGid = @TaalGid;
    call DatumFormat(@VervalDatum, @FormatKort,   @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DK-k>', @FormatDate );
    call DatumFormat(@VervalDatum, @formatMiddel, @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DK-m>', @FormatDate );
    call DatumFormat(@VervalDatum, @formatLang,   @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DK-l>', @FormatDate );
  end if;

  // <DI-?> incassodatum
  if charindex( '<DI-', @regel ) <> 0 then
    call BerekenVervalDatumFactuur(@FactuurDatum, @BtcNummer, @VervalDatum);
    call BerekenIncassoDatumFactuur(@VervalDatum, null,       @incassodatum);
    select TaalDatumKort, TaalDatumMiddel, TaalDatumLang into @FormatKort, @formatMiddel, @formatLang from tabTaal where TaalGid = @TaalGid;
    call DatumFormat(@incassodatum, @FormatKort,   @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DI-k>', @FormatDate );
    call DatumFormat(@incassodatum, @formatMiddel, @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DI-m>', @FormatDate );
    call DatumFormat(@incassodatum, @formatLang,   @TaalGid, @FormatDate); set @regel = ReplaceInString(@regel, '<DI-l>', @FormatDate );
  end if;

  //<V> Valutacode van de factuur
  set @regel = ReplaceInString(@regel, '<V>', (select ValCode from tabvaluta where ValNummer=@ValNummer) );

  return(@regel);

end;
