create or replace procedure OmschrijvingVorigeJournaalPost(in @BoekGangGid integer, in @DgbGid integer, in @JpNummer integer, inout @Omschrijving nchar(40))
begin

  //call TraceBegin('OmschrijvingVorigeJournaalPost(@BoekGangGid='+string(@BoekGangGid)+', @DgbGid='+string(@DgbGid)+', @JpNummer='+string(@JpNummer)+')');

  set @Omschrijving = null;

  select first OmsJournaalPost into @Omschrijving from tabJournaalpost
  where  JpBoekGangGid=@BoekGangGid and JpDgbGid=@DgbGid and JpNummer<@JpNummer order by JpNummer desc;

  if @Omschrijving is null then
    select first OmsJournaalPost into @Omschrijving from tabJournaalpost, tabBoekingsgang
    where BoekGangGid = @BoekGangGid and BoekGangBjGid = JpBjGid and JpDgbGid = @DgbGid order by Jpgid desc;  //Geen join tussen journaalpost en boekingsgang o.b.v. boekganggid. We hebben hier alleen maar het bjgidje nodig uit tabboekingsgang
  end if;

  //call TraceEind('OmschrijvingVorigeJournaalPost(@Omschrijving='+string(@Omschrijving)+')');

end;


create or replace procedure OmzetIndelingKopieren(
  in  @BronOikGid  integer,
  in  @DoelOikCode integer,
  in  @DoelOikOms  nchar(40),
  out @DoelOikGid  integer)
begin
  set @@ErrorTextProcedure = 'OmzetindelingKopieren < @BronOikGid='+string(@BronOikGid);

  //variabelen initialiseren
  set @DoelOikGid = null;

  //kopieren starten
  insert into tabOmzetIndelingKop with auto name
  select
    @DoelOikCode as OikCode,
    @DoelOikOms  as OikOms,
    OikRechtCode,
    OikVergelijkenVorigBoekjaar,
    OikKolomBreedten,
    OikKolomPosities,
    OikKolomZichtbaarheid
  from
    tabOmzetIndelingKop
  where
    OikGid = @BronOikGid;

  //Indeling gekopieerd?
  if @@RowCount = 1 then
    set @DoelOikGid = @@Identity;
    insert into tabOmzetIndelingRegel with auto name
    select
      @DoelOikGid as OirOikGid,
      OirAantallenOnderdrukken,
      OirFilterKolom,
      OirFilterOperator,
      OirFilterwaarde1,
      OirFilterwaarde2,
      OirKleur,
      OirKolom1,
      OirKolom2,
      OirKolom3,
      OirKolom4,
      OirNullBedragenOnderdrukken,
      OirPrefix,
      OirRubriek,
      OirSorteerkolom,
      OirSorteerVolgorde,
      OirTekstStijl,
      OirVolgNr
    from
      tabOmzetIndelingRegel Oude
    where
      Oude.OirOikGid = @BronOikGid
      and Oude.OirRubriek <> 0 /*Totaal*/;
  end if;

  set @@ErrorTextProcedure = 'OmzetindelingKopieren > @DoelOikGid='+string(@DoelOikGid);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure OnsDebiteurNummer(in @RksGid integer, inout @OnsDebiteurNummer nchar(20))
begin

  set @@ErrorTextProcedure = 'OnsDebiteurNummer > @RksGid='+string(@RksGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select nawOnsDebiteurNummer into @OnsDebiteurNummer from tabFileOfNaw, tabNawFile, tabNaw
