  //call TraceEind(@@ErrorTextProcedure);

end;


//----- Procedure wordt gebruikt om tabOpbrengsSoort te vullen en zonodig rekeningen aan te maken
create or replace procedure OpbrengtGroepsoortenPerStuk(in @OpbrengstgroepGid integer, in @SelectedParsoort integer)
begin
  declare @Opbrengstgroep nchar(4);
  declare @Paragraaf nchar(3);
  declare @Opbrnaam nchar(40);
  declare @OpbrnaamLower nchar(40);
  declare @Rksnaam nchar(40);
  declare @RksZoekCode nchar(10);
  declare @Soort smallint;
  declare @IsCredit smallint;

  set @@ErrorTextProcedure = 'OpbrengtGroepsoortenPerStuk > @OpbrengstgroepGid='+string(@OpbrengstgroepGid)+', @SelectedParsoort='+string(@SelectedParsoort);
  //call TraceBegin(@@ErrorTextProcedure);

  select OpbrGrpNummer, OpbrGrpOms into @Opbrengstgroep, @Opbrnaam from tabOpbrengstgroep where OpbrGrpGid = @OpbrengstgroepGid;
  set @OpbrnaamLower = Lower(@Opbrnaam);
  select Paragraaf into @Paragraaf from tabParagraaf, tabBalansCodeDetail where ParBlGid=BlGid and ParSoort=@SelectedParSoort;

  if @Opbrengstgroep is not null and @Paragraaf is not null then
    if not exists (select 1 from tabOpbrengstGroepSoort where GrpSoortGrpGid=@OpbrengstgroepGid and GrpSoortParSoort=@SelectedParSoort) then
      if not exists (select 1 from tabRekeningschema where RksInvoer = @Paragraaf+@Opbrengstgroep) then
        if @SelectedParSoort = 30 then
          set @RksNaam = 'Opbrengst '+@OpbrnaamLower;
          set @Soort = 5;
          set @IsCredit = 1;
        end if;
        if @SelectedParSoort = 40 then
          set @RksNaam = 'Kostprijs '+@OpbrnaamLower;
          set @Soort = 4;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 50 then
          set @RksNaam = 'Voorraad '+@OpbrnaamLower;
          set @Soort = 0;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 60 then
          set @RksNaam = 'Verleende korting '+@OpbrnaamLower;
          set @Soort = 3;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 70 then
          set @RksNaam = 'Ontvangen korting '+@OpbrnaamLower;
          set @Soort = 0;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 80 then
          set @RksNaam = 'Herwaardering '+@OpbrnaamLower;
          set @Soort = 0;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 90 then
          set @RksNaam = 'Prijsverschil '+@OpbrnaamLower;
          set @Soort = 3;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 100 then
          set @RksNaam = 'Voorraadverschil '+@OpbrnaamLower;
          set @Soort = 0;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 110 then
          set @RksNaam = 'Gecalculeerde inkoop '+@OpbrnaamLower;
          set @Soort = 0;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 120 then
          set @RksNaam = 'Gecalculeerde verkoop '+@OpbrnaamLower;
          set @Soort = 0;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 180 then
          set @RksNaam = 'Opbr. proj. '+@OpbrnaamLower;
          set @Soort = 5;
          set @IsCredit = 1;
        end if;
        if @SelectedParSoort = 190 then
          set @RksNaam = 'Kostpr. proj. '+@OpbrnaamLower;
          set @Soort = 4;
          set @IsCredit = 0;
        end if;
        if @SelectedParSoort = 200 then
          set @RksNaam = 'Dekking tarieven proj. '+@OpbrnaamLower;
          set @Soort = 4;
          set @IsCredit = 1;
        end if;
        //TG 02-01-2007: deze worden niet gebruikt (en ook niet aangemaakt in administraties)
        //if @SelectedParSoort = 210 then
        //  set @RksNaam = 'Kostpr. productie '+@OpbrnaamLower;
        //  set @Soort = 0;
        //  set @IsCredit = 0;
        //end if;
        //if @SelectedParSoort = 220 then
        //  set @RksNaam = 'Opbr. productie '+@OpbrnaamLower;
        //  set @Soort = 0;
        //  set @IsCredit = 1;
        //end if;
        if @SelectedParSoort = 230 then
          set @RksNaam = 'Dekking tarieven prod. '+@OpbrnaamLower;
          set @Soort = 4;
          set @IsCredit = 1;
        end if;
        if @SelectedParSoort = 240 then
          set @RksNaam = 'Uitval productie '+@OpbrnaamLower;
          set @Soort = 4;
          set @IsCredit = 0;
        end if;

	      set @RksZoekCode = @Opbrnaam;
        insert into tabRekeningschema(RksNummer, DefaultSoort, RksValNummer, DefaultBoekzijde, RksZoekCode, RksNaam)
        select @Paragraaf+@Opbrengstgroep, @Soort, ValNummer, @IsCredit, @RksZoekCode, @RksNaam from tabValuta where IsBasisValuta<>0;
      end if;
      insert into tabOpbrengstGroepSoort(GrpSoortGrpGid, GrpSoortParSoort, GrpSoortRksGid)
      select @OpbrengstgroepGid, @SelectedParSoort, RksGid from tabRekeningschema where RksInvoer=@Paragraaf+@Opbrengstgroep;
    end if;
  end if;

  set @@ErrorTextProcedure = 'OpbrengtGroepsoortenPerStuk';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure OpbrengtGroepsoortenVullen(in @OpbrengstgroepGid integer, in @SelectedParsoort integer)
begin
  declare @Opbrengstgroep nchar(4);
  declare @Paragraaf nchar(3);

  set @@ErrorTextProcedure = 'OpbrengtGroepsoortenVullen > @OpbrengstgroepGid='+string(@OpbrengstgroepGid)+', @SelectedParsoort='+string(@SelectedParsoort);
  //call TraceBegin(@@ErrorTextProcedure);

  if @SelectedParSoort is null then
    if (select IsModuleActive('og')) <> 0 then
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 30);
    end if;
    if (select IsModuleActive('fc')) <> 0 then
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 40);
    end if;
    if (select IsModuleActive('ta')) <> 0 then
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 50);
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 60);
    end if;
    if (select IsModuleActive('ar')) <> 0 then
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid,  80);
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid,  90);
    end if;
    if (IsModuleActive('1g')<>0 or IsModuleActive('1h')<>0 or IsModuleActive('1i')<>0) then
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 100);
   	end if;
    //if  .... then
    //  call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid,  70);
    //  call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 110);
    //  call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 120);
    //end if;
    if (select IsModuleActive('pr')) <> 0 then
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 180);
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 190);
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 200);
    end if;

    //productieorders wijzigen
    if (select IsModuleActive('rq')) <> 0 then
      //TG 02-01-2007: deze worden niet gebruikt (en ook niet aangemaakt in administraties)
      //call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 210);
      //call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 220);
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 240);
    end if;

    //productieorders (eenvoudig)
    if (select IsModuleActive('rp')) <> 0 then
      call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, 230);
    end if;
  else
    call OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, @SelectedParsoort);
  end if;

  set @@ErrorTextProcedure = 'OpbrengtGroepsoortenVullen';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure OpenBoekingsgangVoorProjectMutaties(
  in  @NieuwVolgnummer            numeric(10,0),
  in  @NieuweOmschrijving         nchar(40),
  in  @AanmakenIndienNietGevonden smallint,
  out @PbkGid                     integer,
  out @PbkGidAangemaakt           smallint
)

begin
  //call TraceBegin('OpenBoekingsgangVoorProjectMutaties > @NieuwVolgnummer = ' + String(@NieuwVolgnummer));

  //variabelen defaults geven voor in het geval ze niet ingevuld zijn.
  set @AanmakenIndienNietGevonden = IsNull(@AanmakenIndienNietGevonden, 0);
  set @NieuwVolgnummer            = IsNull(@NieuwVolgnummer, 0);
  set @NieuweOmschrijving         = IsNull(@NieuweOmschrijving, '');
  set @PbkGidAangemaakt           = 0;

  //als er al een boekingsgang met dit nummer bestaat, dan dit gidje terug geven.
  select PbkGid into @PbkGid from tabProjectBoekingsKop where PbkVolgnummer = @NieuwVolgnummer;

  //er is geen bestaande boekingsgang gevonden. Boekingsgang met het gewenste nummer aanmaken.
  if (@PbkGid is null) and (@AanmakenIndienNietGevonden = 1) then
    insert into tabProjectBoekingsKop (PbkVolgnummer, PbkOms)
    values (@NieuwVolgnummer, @NieuweOmschrijving);
    set @PbkGid = @@Identity;
    set @PbkGidAangemaakt = 1;
  end if;

  //call TraceEind('OpenBoekingsgangVoorProjectMutaties > @PbkGid =  ' + string(@PbkGid));
end;


//------- Afletteren van de openstaande posten
create or replace procedure OpenstaandePostenAfletteren(in @FactuurVolgorde smallint, in @CreditnotaVolgorde smallint,
                                             in @TeBoekenBedrag numeric(15,2), out @AantalVinkjes integer,
                                             out @GeboektBedrag numeric(15,2), out @VerschilBedrag numeric(15,2))

begin
  declare @tmpHulpTeBetalen numeric(15,2);
  declare @TeBetalenBasis numeric(15,2);
  declare @TeBetalen numeric(15,2);
  declare @Openstaand numeric(15,2);
  declare @TeBoekenVerschil numeric(15,2);
  declare @tmpGid integer;
  declare @tmpValutaNummer integer;
  declare @Geblokkeerd smallint;
  declare @Stoppen smallint;
  declare @SoortFactuur smallint;
  declare @BoekenAls smallint;
  declare @BjGid integer;
  declare @Pernr integer;

  //set @@ErrorTextProcedure = 'OpenstaandePostenAfletteren > @TeBoekenBedrag='+string(@TeBoekenBedrag)+', @FactuurVolgorde='+string(@FactuurVolgorde)+', @CreditnotaVolgorde='+string(@CreditnotaVolgorde);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Stoppen=0;
  set @GeboektBedrag=0;
  set @Verschilbedrag=0;
  if exists (select 1 from tmpAfletter where tmpBoeken<>0) then
    update tmpAfletter set tmpBoeken=0, tmpTeBetalen=0, tmpTeBoekenVerschil=0, tmpVerschilBoekenAls=0 where tmpBoeken<>0;
  end if;

  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid, @Pernr);

  while @Stoppen=0 loop
    set @tmpGid=null;
    //execute trace 'Stap 1'
    //call Trace('Stap 1');
    if @CreditnotaVolgorde = 0 then         // Creditnotas eerst
      if @FactuurVolgorde = 0 then         //'Vervaldatum'-volgorde
        select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and tmpFactuurBedrag<tmpBetaaldBedrag and tmpFactuurBedrag<0 and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpVervalDatum, tmpGid;
      else
        if @FactuurVolgorde = 1 then    //'Factuurdatum'-volgorde
          select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and tmpFactuurBedrag<tmpBetaaldBedrag and tmpFactuurBedrag<0 and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpFactuurDatum, tmpGid;
        else                                 //'Factuurnummer'-volgorde
          select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and tmpFactuurBedrag<tmpBetaaldBedrag and tmpFactuurBedrag<0 and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpFactuurNr_Lengte, tmpFactuurNr, tmpGid;
        end if;
      end if;
    end if;

    if @CreditnotaVolgorde = 1 or (@CreditnotaVolgorde = 0 and @tmpGid is null) then   //In geselecteerde volgorde of als er geen creditnotas meer zijn bij keuze 0 (eerste creditnotas)
      if @FactuurVolgorde = 0 then         //'Vervaldatum'-volgorde
        select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and (tmpFactuurBedrag>tmpBetaaldBedrag or (tmpFactuurBedrag<tmpBetaaldBedrag and tmpFactuurBedrag<0)) and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpVervalDatum, tmpGid;
      else
        if @FactuurVolgorde = 1 then        //'Factuurdatum'-volgorde
          select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and (tmpFactuurBedrag>tmpBetaaldBedrag or (tmpFactuurBedrag<tmpBetaaldBedrag and tmpFactuurBedrag<0)) and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpFactuurDatum, tmpGid;
        else                                 //'Factuurnummer'-volgorde
          select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and (tmpFactuurBedrag>tmpBetaaldBedrag or (tmpFactuurBedrag<tmpBetaaldBedrag and tmpFactuurBedrag<0)) and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpFactuurNr_Lengte, tmpFactuurNr, tmpGid;
        end if;
      end if;
    end if;

    if @CreditnotaVolgorde = 2 then             //Geen creditnotas
      if @FactuurVolgorde = 0 then             //'Vervaldatum'-volgorde
        select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and tmpFactuurBedrag>tmpBetaaldBedrag and tmpFactuurBedrag>=0 and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpVervalDatum, tmpGid;
      else
        if @FactuurVolgorde = 1 then        //'Factuurdatum'-volgorde
          select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and tmpFactuurBedrag>tmpBetaaldBedrag and tmpFactuurBedrag>=0 and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpFactuurDatum, tmpGid;
        else                                 //'Factuurnummer'-volgorde
          select First tmpGid into @tmpGid from tmpAfletter where tmpBoeken=0 and tmpIsGeblokkeerd=0 and tmpOpenstaand<>0 and tmpFactuurBedrag>tmpBetaaldBedrag and tmpFactuurBedrag>=0 and tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht = 0 order by tmpFactuurNr_Lengte, tmpFactuurNr, tmpGid;
        end if;
      end if;
    end if;

    //call Trace('Stap 2');
    if @tmpGid is not null then
      select 0, 0, 0, tmpOpenstaand, tmpHulpTeBetalen, tmpValutaNummer,
             tmpSoortFactuur, tmpKredBeprekeningGeblokkeerd
             into @TeBetalen, @BoekenAls, @TeBoekenVerschil, @Openstaand, @tmpHulpTeBetalen, @tmpValutaNummer,
             @SoortFactuur, @Geblokkeerd from tmpAfletter where tmpGid=@tmpGid;
      //call Trace('Stap 3');

      if @@BasisValutaNummer = @tmpValutaNummer then
        set @TeBetalenBasis = @tmpHulpTeBetalen;
      else
        call ValutaOmrekenenProc(@tmpValutaNummer, @tmpHulpTeBetalen, @@BasisValutaNummer, @BjGid, null, @Pernr, null, 2, @TeBetalenBasis);
      end if;

      if ((@TeBoekenBedrag) >= (@GeboektBedrag + @TeBetalenBasis + @VerschilBedrag) and @TeBoekenBedrag< 0) or
         ((@TeBoekenBedrag) <= (@GeboektBedrag + @TeBetalenBasis + @VerschilBedrag) and @TeBoekenBedrag>=0) then
        set @TeBetalenBasis = (@TeBoekenBedrag - @VerschilBedrag - @GeboektBedrag);    //dan maar een deelbetaling
        set @Stoppen = 1;
      else
        //call Trace('Stap 4');
        // hele bedrag afboeken. Als met kredietbeperking, dan tmpVerschilBoeken vullen
        if (@SoortFactuur between 1 and 2) and (@Geblokkeerd = 0) then
          set @BoekenAls=(@SoortFactuur + 3);   // zo komt tmpboekenals op de juiste waarde
          set @TeBoekenVerschil=(@tmpHulpTeBetalen - @Openstaand);
          if @@BasisValutaNummer = @tmpValutaNummer then
            set @TeBetalen = @Openstaand;
          else
            call ValutaOmrekenenProc(@tmpValutaNummer, @Openstaand, @@BasisValutaNummer, @BjGid, null, @Pernr, null, 2, @TeBetalen);
          end if;
        else
          set @TeBetalen = @TmpHulpTeBetalen;
        end if;
      end if;
      if @TeBetalen<>0 or (@Stoppen <> 0 and @TeBetalenBasis<>0) then  //bij deelbetaling is basis gevuld
        // @TeBetalenBasis is in basisvaluta,  tmpTeBetalen en @TeBetalen is in ospvaluta
        //call Trace('Stap 5');
        if @Stoppen <> 0 then                       //Bij deelbetaling moeten we van basis -> valuta, in andere geval altijd van valuta -> basis ivm afrondingsverschillen
          if @@BasisValutaNummer = @tmpValutaNummer then
            set @TeBetalen = @TeBetalenBasis;
          else
            call ValutaOmrekenenProc(@@BasisValutaNummer, @TeBetalenBasis, @tmpValutaNummer, @BjGid, null, @Pernr, null, 2, @TeBetalen);
          end if;
        end if;

        update tmpAfletter set tmpBoeken=1, tmpTeBetalen=@TeBetalen, tmpVerschilBoekenAls=@BoekenAls, tmpTeBoekenVerschil=@TeBoekenVerschil where tmpGid=@tmpGid;

        set @GeboektBedrag = @GeboektBedrag + @TeBetalenBasis;
        if @@BasisValutaNummer = @tmpValutaNummer then
          set @TeBetalenBasis = @TeBoekenVerschil;
        else
          call ValutaOmrekenenProc(@tmpValutaNummer, @TeBoekenVerschil, @@BasisValutaNummer, @BjGid, null, @Pernr, null, 2, @TeBetalenBasis);
        end if;
        //Bij omrekenen misbruiken we het veld @TeBetalenBasis even om het verschil om te kunnen rekenen
        set @VerschilBedrag = @VerschilBedrag + @TeBetalenBasis;
      end if;
    else
      set @Stoppen = 1;
    end if;
  end loop;

  select count(*) into @AantalVinkjes from tmpAfletter where tmpBoeken<>0;

  //set @@ErrorTextProcedure = 'OpenstaandePostenAfletteren > @AantalVinkjes='+string(@AantalVinkjes)+', @GeboektBedrag='+string(@GeboektBedrag);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure OpenstaandePostenBijwerken(in @WordGeopend smallint, in @JpGid integer, in @IsDefinitief smallint)
begin
  //call TraceBegin('OpenstaandePostenBijwerken > @WordGeopend = ' + string(@WordGeopend) + ', @JpGid = ' + string(@JpGid));

  // DG 14-07-2014 #42207 Zonder fiatteer-rechten kan nog worden geboekt op gefiatteerde OSP, waardoor bedrag wijzigt
  // We bewaren bij het openen de velden Openstaandbedrag en de fiattering in de "SAV" velden (zie verderop).
  // In de before update trigger van tabOpenstaande post gebruiken we deze velden om te bepalen of de fiattering aangepast moet worden.
  // Dit moet alleen gebeuren als het een te betalen bedrag is en dat dit bedrag groter is geworden.
  // We willen niet dat het tijdelijk af en opboeken van de openstaande post leidt tot het aanpassen van de fiattering.
  // Dus bij het sluiten van de journaalpost worden de bedragen bijgewerkt met de bedragen uit de journaalregels.
  // Als dan blijkt dat de openstaande post niet is gewijzigd t.o.v. openen of het openstaande bedrag juist kleiner is geworden, dan
  // zetten we fiatteringsgegevens terug van het moment van openen.

  //Test of boekingsgang voorlopig ge-update moet worden of definitief
  if @IsDefinitief = 0 then
    if @WordGeopend = 0 then
      //Debet op een debiteur geboekt of credit op een crediteur, dan factuurbedrag verhogen
      update tabOpenstaandePost
      set    OspValNummer              = JrValNummer,  //Express doen, hierdoor conroleert de trigger of de oude en nieuwe valuta overeenkomen
             OspValCode                = JrValCode,
             OspFactuurBedragVoorlopig = OspFactuurBedragVoorlopig + if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
             OspBetaaldBedragVoorlopig = OspBetaaldBedragVoorlopig + if IsBetaling      (JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
             OspBtwBedragVoorlopig     = OspBtwBedragVoorlopig     +
                                         if IsNull(HulpRekSoort,0) = 1 then
                                           if HulpRekIsCredit = 0 then
                                             (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                           else
                                             (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                           endif
                                          else
                                            0
                                          endif,
             OspKredietBeperkingsBedrag = OspKredietBeperkingsBedrag -
                                          if IsNull(HulpRekSoort,0) = 4 or IsNull(HulpRekSoort,0) = 5 then
                                            if HulpRekIsCredit = 0 then
                                              (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                            else
                                              (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                            endif
                                          else
                                            0
                                          endif,
             OspKredietbeperkingsDatum  = if (IsNull(HulpRekSoort,0) = 4 or IsNull(HulpRekSoort,0) = 5) and HulpRekKredBepDatum is not null then HulpRekKredBepDatum else OspKredietbeperkingsDatum endif,
             OspSoortFactuur            = if IsBetaling(JrRksGid, IsCreditBoeking) = 1 then OspSoortFactuur else if IsNull(HulpRekSoort,0) = 4 then 1 else if IsNull(HulpRekSoort,0) = 5 then 2 else OspSoortFactuur endif endif endif
      from   tabJournaalregel left outer join tabHulpRekening on (JrGid=HulpRekJrGid)
      where  JrJpGid = @JpGid and JrOspGid=OspGid;
    else
      //Debet op een debiteur geboekt of credit op een crediteur, dan factuurbedrag verlagen
      update tabOpenstaandePost
      set    OspValNummer              = JrValNummer,  //Express doen, hierdoor conroleert de trigger of de oude en nieuwe valuta overeenkomen
             OspValCode                = JrValCode,
             OspFactuurBedragVoorlopig = OspFactuurBedragVoorlopig - if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
             OspBetaaldBedragVoorlopig = OspBetaaldBedragVoorlopig - if IsBetaling      (JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
             OspBtwBedragVoorlopig     = OspBtwBedragVoorlopig     -
                                         if IsNull(HulpRekSoort,0) = 1 then
                                           if HulpRekIsCredit = 0 then
                                             (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                           else
                                             (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                           endif
                                         else
                                           0
                                         endif,
              OspKredietBeperkingsBedrag = OspKredietBeperkingsBedrag +
                                         if IsNull(HulpRekSoort,0) = 4 or IsNull(HulpRekSoort,0) = 5 then
                                           if HulpRekIsCredit = 0 then
                                             (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                           else
                                             (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                           endif
                                         else
                                           0
                                         endif,

                                         OspJpGIDSAV  = @JpGid,
              OspSAVGefiatteerd             = OspGefiatteerd,
              OspSAVFiatteringGewijzigdDoor = OspFiatteringGewijzigdDoor,
              OspSAVFiatteringGewijzigdOp   = OspFiatteringGewijzigdOp,
              OspSAVOpenstaandBedrag        = (OspFactuurBedragVoorlopig + OspFactuurBedragDefinitief) - (OspBetaaldBedragVoorlopig + OspBetaaldBedragDefinitief)
      from   tabJournaalregel left outer join tabHulpRekening on (JrGid=HulpRekJrGid)
      where  JrJpGid = @JpGid and JrOspGid = OspGid;
    end if;
  else
    if @WordGeopend=0 then
      //Debet op een debiteur geboekt of credit op een crediteur, dan factuurbedrag verhogen
      update tabOpenstaandePost
      set    OspValNummer               = JrValNummer,  //Express doen, hierdoor conroleert de trigger of de oude en nieuwe valuta overeenkomen
             OspValCode                 = JrValCode,
             OspFactuurBedragDefinitief = OspFactuurBedragDefinitief + if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
             OspBetaaldBedragDefinitief = OspBetaaldBedragDefinitief + if IsBetaling      (JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
             OspBtwBedragDefinitief = OspBtwBedragDefinitief + if IsNull(HulpRekSoort,0) = 1 then
                                             if HulpRekIsCredit = 0 then
                                               (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                             else
                                               (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                             endif
                                           else
                                             0
                                           endif,
             OspKredietBeperkingsBedrag = OspKredietBeperkingsBedrag -
                                           if IsNull(HulpRekSoort,0) = 4 or IsNull(HulpRekSoort,0) = 5 then
                                             if HulpRekIsCredit = 0 then
                                               (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                             else
                                               (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                             endif
                                           else
                                             0
                                           endif,
             OspKredietbeperkingsDatum =  if ( IsNull(HulpRekSoort,0) = 4 or IsNull(HulpRekSoort,0) = 5 ) and HulpRekKredBepDatum is not null then HulpRekKredBepDatum else OspKredietbeperkingsDatum endif,
             OspSoortFactuur = if IsBetaling(JrRksGid, IsCreditBoeking) = 1 then OspSoortFactuur else if IsNull(HulpRekSoort,0) = 4 then 1 else if IsNull(HulpRekSoort,0) = 5 then 2 else OspSoortFactuur endif endif endif
      from   tabJournaalregel left outer join tabHulpRekening on (JrGid=HulpRekJrGid)
      where  JrJpGid = @JpGid and JrOspGid=OspGid;
    else
      //Debet op een debiteur geboekt of credit op een crediteur, dan factuurbedrag verlagen
      update tabOpenstaandePost
      set    OspValNummer               = JrValNummer,  //Express doen, hierdoor conroleert de trigger of de oude en nieuwe valuta overeenkomen
             OspValCode                 = JrValCode,
             OspFactuurBedragDefinitief = OspFactuurBedragDefinitief - if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
             OspBetaaldBedragDefinitief = OspBetaaldBedragDefinitief - if IsBetaling      (JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif,
             OspBtwBedragDefinitief     = OspBtwBedragDefinitief     - if IsNull(HulpRekSoort,0) = 1 then
                                             if HulpRekIsCredit = 0 then
                                               (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                             else
                                               (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                             endif
                                           else
                                             0
                                           endif,
             OspKredietBeperkingsBedrag = OspKredietBeperkingsBedrag +
                                           if IsNull(HulpRekSoort,0) = 4 or IsNull(HulpRekSoort,0) = 5 then
                                             if HulpRekIsCredit = 0 then
                                               (if HulpRekValNummer = JrValnummer then HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                             else
                                               (if HulpRekValNummer = JrValnummer then -HulpRekValutaBedrag else ValutaOmrekenen(HulpRekValNummer, -HulpRekValutaBedrag, JrValnummer, JrBjGid, JrPernr, 2) endif)
                                             endif
                                           else
                                             0
                                           endif,
             OspSAVGefiatteerd             = OspGefiatteerd,
             OspSAVFiatteringGewijzigdDoor = OspFiatteringGewijzigdDoor,
             OspSAVFiatteringGewijzigdOp   = OspFiatteringGewijzigdOp,
             OspSAVOpenstaandBedrag        = (OspFactuurBedragVoorlopig + OspFactuurBedragDefinitief) - (OspBetaaldBedragVoorlopig + OspBetaaldBedragDefinitief)
      from   tabJournaalregel left outer join tabHulpRekening on (JrGid=HulpRekJrGid)
      where  JrJpGid = @JpGid and JrOspGid=OspGid;
    end if;
  end if;
  //Na het bijwerken van de bedragen, worden de velden factdatum, vervdatum, betkenmerk en viaIncasso teruggezet
  //Bij het openen van de JP worden bovenstaande velden teruggelezen van de vorige journaalregel die
  //ook dit OspGid gebruikt. Als deze er niet is, dan wordt er geen update gedaan.
  //Bij het sluiten worden de velden overgenomen van de bijbehorende nieuwste JournaalRegel
  if @WordGeopend = 1 then
    update tabOpenstaandePost set OspFactuurDatum    =VorigeRegel.JrFactuurDatum    , OspVervalDatum =VorigeRegel.JrVervalDatum,
                                  OspBetalingsKenmerk=VorigeRegel.JrBetalingsKenmerk
    from   tabJournaalregel HuidigeRegel, tabJournaalregel VorigeRegel
    where  HuidigeRegel.JrJpGid=@JpGid and
           HuidigeRegel.JrOspGid=OspGid and OspGid=VorigeRegel.JrOspGid and
           VorigeRegel.JrGid=(select OpenstaandePostVorigeJournaalRegel(OspGid, HuidigeRegel.JrGid));
  else
    update tabOpenstaandePost
    set
      OspJpGIDSAV  = null
      // Note Trigger zet de overige SAV velden op NULL
    where  OspJpGIDSAV = @JpGid;

    update tabOpenstaandePost set OspFactuurDatum    =VorigeRegel.JrFactuurDatum    , OspVervalDatum =VorigeRegel.JrVervalDatum,
                                  OspBetalingsKenmerk=VorigeRegel.JrBetalingsKenmerk
    from   tabJournaalregel HuidigeRegel, tabJournaalregel VorigeRegel
    where  HuidigeRegel.JrJpGid=@JpGid and
           HuidigeRegel.JrOspGid=OspGid and OspGid=VorigeRegel.JrOspGid and
           VorigeRegel.JrGid=(select OpenstaandePostVorigeJournaalRegel(OspGid, null));
  end if;

  //call TraceEind('OpenstaandePostenBijwerken');
end;


create or replace procedure OpenstaandePostenPerValuta(in @RksGid integer, in @BjGid integer, in @Status smallint)
//Result .... laten staan, je krijgt anders fouten als deze stored proc wordt opgevoerd via KING (via scripts)
result (Valuta nchar(3), FactuurBedrag numeric(15,2), DeelBetaling numeric(15,2), Openstaand numeric(15,2), Tegenwaarde numeric(15,2), Onderweg numeric(15,2))
begin
  //---------- Toon Openstaande posten van een debiteur/crediteur per valuta

  declare @BjGid2 integer;
  declare @Pernr integer;

  set @@ErrorTextProcedure = 'OpenstaandePostenPerValuta > ';
  //call TraceBegin(@@ErrorTextProcedure + '@RksGid = ' + string(@RksGid) + ', @BjGid = ' + string(@BjGid) + ', @Status = ' + string(@Status));

  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid2, @PerNr);

  set @@ErrorTextProcedure = 'OpenstaandePostenPerValuta';
  //call TraceEind(@@ErrorTextProcedure);

  if @status = 0 then       //Definitieve bedragen
    select OspValCode Valuta,
           sum(OspFactuurBedragDefinitief) FactuurBedrag,
           sum(OspBetaaldBedragDefinitief) DeelBetaling,
           FactuurBedrag - DeelBetaling Openstaand,
           ValutaOmrekenen(OspValnummer, Openstaand, @@BasisValutaNummer, @BjGid2, @Pernr, 2) Tegenwaarde,
           sum(ValutaOmrekenen(OspValnummerBedragOnderweg, OspBedragOnderwegInValuta, @@BasisValutaNummer, @BjGid2, @Pernr, 2)) Onderweg
    from   tabOpenstaandePost
    where  OspBjGid = @BjGid and OspRksGid=@RksGid and ((OspFactuurBedragDefinitief) - (OspBetaaldbedragDefinitief)<>0)
    group by OspValCode, OspValnummer;
  elseif @status=1 then     //Voorlopige bedragen
    select OspValCode Valuta,
           sum(OspFactuurBedragVoorlopig) FactuurBedrag,
           sum(OspBetaaldBedragVoorlopig) DeelBetaling,
           FactuurBedrag - DeelBetaling Openstaand,
           ValutaOmrekenen(OspValnummer, Openstaand, @@BasisValutaNummer, @BjGid2, @Pernr, 2) Tegenwaarde,
           sum(ValutaOmrekenen(OspValnummerBedragOnderweg, OspBedragOnderwegInValuta, @@BasisValutaNummer, @BjGid2, @Pernr, 2)) Onderweg
    from   tabOpenstaandePost
    where  OspBjGid = @BjGid and OspRksGid=@RksGid and ((OspFactuurBedragVoorlopig) - (OspBetaaldbedragVoorlopig)<>0)
    group by OspValCode, OspValnummer;
  else                      //Definitieve + Voorlopige bedragen
    select OspValCode Valuta,
           sum(OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) FactuurBedrag,
           sum(OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig) Deelbetaling,
           FactuurBedrag - DeelBetaling Openstaand,
           ValutaOmrekenen(OspValnummer, Openstaand, @@BasisValutaNummer, @BjGid2, @Pernr, 2) Tegenwaarde,
           sum(ValutaOmrekenen(OspValnummerBedragOnderweg, OspBedragOnderwegInValuta, @@BasisValutaNummer, @BjGid2, @Pernr, 2)) Onderweg
    from   tabOpenstaandePost
    where  OspBjGid = @BjGid and OspRksGid = @RksGid and OspIsVervallen = 0
    group by OspValCode, OspValnummer;
  end if;


end;


//$Workfile: OpenstaandePostIsGeblokkeerd.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//------------- Geef terug of de Openstaande post geblokkeerd is
if exists (select 1 from sys.sysProcedure where proc_name='OpenstaandePostIsGeblokkeerd') then
  drop procedure OpenstaandePostIsGeblokkeerd;
end if;

create procedure OpenstaandePostIsGeblokkeerd(in @OspGid integer, inout @IsGeblokkeerd integer)
begin

  set @@ErrorTextProcedure = 'OpenstaandePostIsGeblokkeerd > @OspGid='+string(@OspGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select OspIsGeblokkeerd into @IsGeblokkeerd from tabOpenstaandePost where OspGid=@OspGid;

  set @@ErrorTextProcedure = 'OpenstaandePostIsGeblokkeerd > @IsGeblokkeerd='+string(@IsGeblokkeerd);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure OpenstaandePostTotalen(in @RksGid integer, in @BjGid integer, in @Status smallint, in @InclusiefVolledigVerwerkt smallint,
                                                   out @FactuurBedrag numeric(15,2), out @Deelbetaling numeric(15,2),
                                                   out @Openstaand  numeric(15,2), out @Onderweg numeric(15,2))
begin
  declare @NewBjGid integer;
  declare @Pernr integer;

  set @@ErrorTextProcedure = 'OpenstaandePostTotalen >';
  //call TraceBegin(@@ErrorTextProcedure + '@RksGid = ' + string(@RksGid));

  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @NewBjGid, @PerNr);

  set @@ErrorTextProcedure = 'OpenstaandePostTotalen';
  //call TraceEind(@@ErrorTextProcedure);

  if @Status = 0 then         //Definitieve bedragen
    select sum(if OspValnummer = @@BasisValutaNummer then OspFactuurBedragDefinitief else ValutaOmrekenen(OspValnummer, OspFactuurBedragDefinitief, @@BasisValutaNummer, @NewBjGid, @Pernr, 2) endif) FactBedrag,
           sum(if OspValnummer = @@BasisValutaNummer then OspBetaaldBedragDefinitief else ValutaOmrekenen(OspValnummer, OspBetaaldBedragDefinitief, @@BasisValutaNummer, @NewBjGid, @Pernr, 2) endif) BetaaldBedrag,
           FactBedrag - BetaaldBedrag,
           sum(if OspValnummerBedragOnderweg = @@BasisValutaNummer then OspBedragOnderwegInValuta else ValutaOmrekenen(OspValnummerBedragOnderweg, OspBedragOnderwegInValuta, @@BasisValutaNummer, @NewBjGid, @Pernr, 2) endif)
    into   @FactuurBedrag, @Deelbetaling, @Openstaand, @Onderweg
    from   tabOpenstaandePost
    where  OspBjGid = @BjGid and OspRksGid=@RksGid and (@InclusiefVolledigVerwerkt = 1 or OspFactuurBedragDefinitief - OspBetaaldbedragDefinitief <> 0)
  elseif @status = 1 then     //Voorlopige bedragen
    select sum(if OspValnummer = @@BasisValutaNummer then OspFactuurBedragVoorlopig else ValutaOmrekenen(OspValnummer, OspFactuurBedragVoorlopig, @@BasisValutaNummer, @NewBjGid, @Pernr, 2) endif) FactBedrag,
           sum(if OspValnummer = @@BasisValutaNummer then OspBetaaldBedragVoorlopig else ValutaOmrekenen(OspValnummer, OspBetaaldBedragVoorlopig, @@BasisValutaNummer, @NewBjGid, @Pernr, 2) endif) BetaaldBedrag,
           FactBedrag - BetaaldBedrag,
           sum(if OspValnummerBedragOnderweg = @@BasisValutaNummer then OspBedragOnderwegInValuta else ValutaOmrekenen(OspValnummerBedragOnderweg, OspBedragOnderwegInValuta, @@BasisValutaNummer, @NewBjGid, @Pernr, 2) endif)
    into   @FactuurBedrag, @Deelbetaling, @Openstaand, @Onderweg
    from   tabOpenstaandePost
    where  OspBjGid = @BjGid and OspRksGid=@RksGid and (@InclusiefVolledigVerwerkt = 1 or OspFactuurBedragVoorlopig - OspBetaaldbedragVoorlopig <> 0)
  else                        //Definitieve + Voorlopige bedragen
    select sum(if OspValnummer = @@BasisValutaNummer then OspFactuurBedragDefinitief+OspFactuurBedragVoorlopig else ValutaOmrekenen(OspValnummer, OspFactuurBedragDefinitief+OspFactuurBedragVoorlopig, @@BasisValutaNummer, @NewBjGid, @Pernr, 2) endif) FactBedrag,
           sum(if OspValnummer = @@BasisValutaNummer then OspBetaaldBedragDefinitief+OspBetaaldBedragVoorlopig else ValutaOmrekenen(OspValnummer, OspBetaaldBedragDefinitief+OspBetaaldBedragVoorlopig, @@BasisValutaNummer, @NewBjGid, @Pernr, 2) endif) BetaaldBedrag,
           FactBedrag - BetaaldBedrag,
           sum(if OspValnummerBedragOnderweg = @@BasisValutaNummer then OspBedragOnderwegInValuta else ValutaOmrekenen(OspValnummerBedragOnderweg, OspBedragOnderwegInValuta, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif)
    into   @FactuurBedrag, @Deelbetaling, @Openstaand, @Onderweg
    from   tabOpenstaandePost
    where  OspBjGid = @BjGid and OspRksGid = @RksGid and (@InclusiefVolledigVerwerkt = 1 or OspIsVervallen = 0)
  end if;

end;

create or replace function OpenstaandePostVorigeJournaalRegel(in @OspGid integer, in @JrGid integer)
returns integer
begin
  declare @VorigJrId integer;

  //call TraceBegin('OpenstaandePostVorigeJournaalRegel > @OspGid = ' + string(@OspGid) + ', @JrGid = ' + string(@JrGid));

  select first JrGid into @VorigJrId
  from   tabJournaalRegel
  where  JrOspGid=@OspGid and ((JrGid<>@JrGid) or (@JrGid is null)) order by JrTimeStamp desc;

  //call TraceEind('OpenstaandePostVorigeJournaalRegel');
  return(@VorigJrId);
end;


//JV, 16 sept 08, voor maatwerk
//--- functie de een optienr lijst retourneerd
//--- input is OptcConfig string van tabOptiesCommercieel
//--- string is 161 karakters met 'D__D__________________________________'
//--- resultaat is dan deze lijst: 2: 0,3
//--- omdat er D staat op 0 en 3e positie en er 2 Ds in staan

create or replace function OptieNrlijstVanOptcConfig(in @InputString nchar(161))
returns nchar(200)
begin
  declare @NewText   nchar(200);
  declare @Count     integer;
  declare @Position  integer;

  set @Count    = 0;
  set @Position = 1;

  while @Position <= length(@InputString) loop
    if substr(@InputString, @Position, 1) = 'D' then
      if @NewText <>'' then
        set @NewText = @NewText+',';
      end if;
      set @Count    = @Count   + 1;
      set @NewText  = @NewText + string(@Position-1);
    end if;
    set @Position = @Position + 1;
  end loop;

  set @NewText  = string(@Count) + ': ' + @NewText;
  return(@NewText);

end;


create or replace procedure OrderBerekenExtraRegelBedragen(in @OrkGid integer)
begin
  declare @TotArtikelBruto             numeric(15,2);
  declare @BtwArtikelBruto             numeric(15,2);
  declare @BtwBasisArtikelBruto        numeric(15,2);
  //Van deze totalen zijn de regelkortingen wel al afgehaald
  declare @TotArtikelRegel             numeric(15,2);
  declare @BtwArtikelRegel             numeric(15,2);
  declare @BtwBasisArtikelRegel        numeric(15,2);
  declare @BtwKortingRegel             numeric(15,2);
  declare @BtwToeslagRegel             numeric(15,2);

  declare @TeFactTotKortingRegel       numeric(15,2);
  declare @TeFactBtwKortingRegel       numeric(15,2);
  declare @TeFactBtwBasisKortingRegel  numeric(15,2);
  declare @TeFactTotToeslagRegel       numeric(15,2);
  declare @TeFactBtwToeslagRegel       numeric(15,2);
  declare @TeFactBtwBasisToeslagRegel  numeric(15,2);

  declare @DezeFactTotKortingRegel       numeric(15,2);
  declare @DezeFactBtwKortingRegel       numeric(15,2);
  declare @DezeFactBtwBasisKortingRegel  numeric(15,2);
  declare @DezeFactTotToeslagRegel       numeric(15,2);
  declare @DezeFactBtwToeslagRegel       numeric(15,2);
  declare @DezeFactBtwBasisToeslagRegel  numeric(15,2);

  declare @TotKortingRegel             numeric(15,2);
  declare @TotToeslagRegel             numeric(15,2);
  declare @BtwBasisKortingRegel        numeric(15,2);
  declare @BtwBasisToeslagRegel        numeric(15,2);

  declare @OrkInclBtw                  smallint;
  declare @Oergid                      integer;
  declare @RegelSoort                  smallint;
  declare @Perc                        numeric(7,2);
  declare @Oerbedrag                   numeric(15,2);
  declare @BerekenOverArtikel          smallint;
  declare @OerBtwCode                  integer;
  declare @BtwPerc                     numeric(7,2);
  declare @basisbedrag                 numeric(15,2);
  declare @btwbasis                    numeric(15,2);
  declare @btwbedrag                   numeric(15,2);
  declare @bedrag                      numeric(15,2);
  declare @AantDeci                    smallint;
  //tbv. loopje
  declare @RegelNr                     integer;
  declare @VorigRegelNr                integer;
  declare @WatBerekenTeller            smallint;  //1=obv. besteld, 2=obv. te factureren

  declare @HeeftExtraRegel             integer;

  set @@ErrorTextProcedure = 'OrderBerekenExtraRegelBedragen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@OrkGid = ' + string(@OrkGid));

  select first 1 into @HeeftExtraRegel from tabOrderExtraRegel where oerOrkGid = @OrkGid;
  if IsNull(@HeeftExtraRegel, 0) = 1 then

    //Aantal decimalen benodigd voor afronden
    select DecimalenRegel*2, OrkInclBtw into @AantDeci, @OrkInclBtw from tabOrderKop inner join tabValuta on (ValNummer=OrkValNummer) where OrkGid = @OrkGid;

    //Let op: deze hele routine wordt 3x doorlopen: 1x voor aantal besteld, 1x vooraantal te factureren en 1x voor aantal deze factuur
    set @WatBerekenTeller = 1;
    LoopWatBerekenen:
    loop
      if @WatBerekenTeller > 3 then
        leave LoopWatBerekenen;
      end if;

      // In plaats van 3x apart, nu gewoon altijd over alles berekenen en dat in de Artikel-variabelen zetten
      call OrderExtraRegelBerekenTotalenNormaleRegels(@WatBerekenTeller, @OrkGid, null, @OrkInclBtw, @TotArtikelBruto, @TotArtikelRegel, @BtwArtikelBruto, @BtwArtikelRegel, @BtwBasisArtikelBruto, @BtwBasisArtikelRegel);
      set @TotKortingRegel      = 0;
      set @TotToeslagRegel      = 0;
      set @BtwBasisKortingRegel = 0;
      set @BtwBasisToeslagRegel = 0;
      set @TeFactTotKortingRegel      = 0;
      set @TeFactTotToeslagRegel      = 0;
      set @TeFactBtwBasisKortingRegel = 0;
      set @TeFactBtwBasisToeslagRegel = 0;
      set @DezeFactTotKortingRegel      = 0;
      set @DezeFactTotToeslagRegel      = 0;
      set @DezeFactBtwBasisKortingRegel = 0;
      set @DezeFactBtwBasisToeslagRegel = 0;

      //Vervolgens per extra orderregel doorrekenen in de regelnummer-volgorde
      set @VorigRegelNr = -1;
      LoopExtraRegelNr:
      loop
        set @RegelNr = null;
        select first OerGid, OerRegelNr, OerRegelSoort, OerPerc, OerBedrag,
                     OerBerekenOverArtikel, OerBtwCode
        into         @OerGid, @RegelNr, @RegelSoort, @Perc, @OerBedrag,
                     @BerekenOverArtikel, @OerBtwCode
        from   tabOrderExtraRegel
        where  OerOrkGid = @OrkGid and OerRegelNr > @VorigRegelNr order by OerRegelNr;
        if @RegelNr is null then
          leave LoopExtraRegelNr;
        end if;
        set @VorigRegelNr = @RegelNr;

        if @OerBtwCode is not null then
          //BtwPerc. erbijhalen
          select BtwPercentage into @BtwPerc from tabBtw where BtwCode = @OerBtwCode;
        else
          set @BtwPerc = null;
        end if;

        //Bereken het totaalbedrag voor deze regel obv. aantal besteld en aantal te factureren en aantal deze factuur
        set @BasisBedrag =
          if @Perc is null then
            @OerBedrag
          else
            case @BerekenOverArtikel
              when 1 then @TotArtikelBruto //Exclusief de regelkortingen
              when 2 then @TotArtikelRegel//Via regeltotalen
              else        0
            end
          endif;
        set @Bedrag =
          if @Perc is null then
            @OerBedrag
          else
            @Perc /100 * @BasisBedrag
          endif;


        set @BtwBasis =
          if @Perc is null then
            @OerBedrag
          else
            @Perc /100 *
             case @BerekenOverArtikel
               when 1 then @BtwBasisArtikelBruto//Exclusief de regelkortingen
               when 2 then @BtwBasisArtikelRegel//Via regeltotalen
               else        0
             end
          endif;
        set @BtwBedrag =
          if @BtwPerc is not null then
            //Als BTW-code niet is ingevuld, gebruik dan de BTW van de orderregels zelf
            if @OrkInclBtw = 0 then
              @Bedrag
            else
              isnull(@Bedrag/ (100 + @BtwPerc), 0)
            endif
          else
            if @Perc is null then
              @OerBedrag
            else
              @Perc /100 *
               case @BerekenOverArtikel
                 when 1 then @BtwArtikelBruto //Exclusief de regelkortingen
                 when 2 then @BtwArtikelRegel //Via regeltotalen
                 else        0
               end
            endif
          endif;

        set @Bedrag = isnull(round(@Bedrag,@AantDeci), 0);

        //Als laatste effe onthouwen in het record en voor de volgende regelberekeningen
        //call Trace('Onthouden! Regeltotaal= '+string(@Bedrag)+', BasisBedrag= '+string(@BasisBedrag)+', BtwBasis= '+string(@BtwBasis)+', BtwBedrag= '+string(@BtwBedrag));

        case @WatBerekenTeller
        when 1 then
          //En de regel updaten
          update tabOrderExtraRegel
          set    oerRegeltotaal = @Bedrag,
                 oerBasisBedrag = @BasisBedrag,
                 oerBtwBasis    = @BtwBasis,
                 oerBtwBedrag   = @BtwBedrag
          where  oerGid = @Oergid;
          case @RegelSoort
            when 0 then //Korting
              set @TotKortingRegel = @TotKortingRegel + @Bedrag;
              set @BtwKortingRegel = @BtwKortingRegel + @BtwBedrag;
              set @BtwBasisKortingRegel = @BtwBasisKortingRegel + @BtwBasis;
            when 1 then //Toeslag
              set @TotToeslagRegel = @TotToeslagRegel + @Bedrag;
              set @BtwToeslagRegel = @BtwToeslagRegel + @BtwBedrag;
              set @BtwBasisToeslagRegel = @BtwBasisToeslagRegel + @BtwBasis;
          end case;
        when 2 then
          //En de regel updaten
          update tabOrderExtraRegel
          set    oerTeFactRegeltotaal = @Bedrag,
                 oerTeFactBasisBedrag = @BasisBedrag,
                 oerTeFactBtwBasis    = @BtwBasis,
                 oerTeFactBtwBedrag   = @BtwBedrag
          where  oerGid = @Oergid;
          case @RegelSoort
            when 0 then //Korting
              set @TeFactTotKortingRegel      = @TeFactTotKortingRegel + @Bedrag;
              set @TeFactBtwKortingRegel      = @TeFactBtwKortingRegel + @BtwBedrag;
              set @TeFactBtwBasisKortingRegel = @TeFactBtwBasisKortingRegel + @BtwBasis;
            when 1 then //Toeslag
              set @TeFactTotToeslagRegel      = @TeFactTotToeslagRegel + @Bedrag;
              set @TeFactBtwToeslagRegel      = @TeFactBtwToeslagRegel + @BtwBedrag;
              set @TeFactBtwBasisToeslagRegel = @TeFactBtwBasisToeslagRegel + @BtwBasis;
          end case;
        when 3 then
          //En de regel updaten
          update tabOrderExtraRegel
          set    oerDezeFactRegeltotaal = @Bedrag,
                 oerDezeFactBasisBedrag = @BasisBedrag,
                 oerDezeFactBtwBasis    = @BtwBasis,
                 oerDezeFactBtwBedrag   = @BtwBedrag
          where  oerGid = @Oergid;
          case @RegelSoort
            when 0 then //Korting
              set @DezeFactTotKortingRegel      = @DezeFactTotKortingRegel + @Bedrag;
              set @DezeFactBtwKortingRegel      = @DezeFactBtwKortingRegel + @BtwBedrag;
              set @DezeFactBtwBasisKortingRegel = @DezeFactBtwBasisKortingRegel + @BtwBasis;
            when 1 then //Toeslag
              set @DezeFactTotToeslagRegel      = @DezeFactTotToeslagRegel + @Bedrag;
              set @DezeFactBtwToeslagRegel      = @DezeFactBtwToeslagRegel + @BtwBedrag;
              set @DezeFactBtwBasisToeslagRegel = @DezeFactBtwBasisToeslagRegel + @BtwBasis;
          end case;
        end case;
      end loop LoopExtraRegelNr;

      set @WatBerekenTeller = @WatBerekenTeller + 1;
    end loop LoopWatBerekenen;

  end if; // IsNull(@HeeftExtraRegel, 0) = 1

  set @@ErrorTextProcedure = 'OrderBerekenExtraRegelBedragen';
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure OrderExtraRegelBerekenTotalenNormaleRegels( in @ObvBesteldOfTeFact smallint, in @OrkGid integer, in @Regelsoort integer, in @OrkInclBtw integer, out @TotBruto numeric(15,2), out @TotRegel numeric(15,2), out @BtwBruto numeric(15,2), out @BtwRegel numeric(15,2), out @BtwBasisBruto numeric(15,2), out @BtwBasisRegel numeric(15,2) )
begin

  set @@ErrorTextProcedure = 'OrderExtraRegelBerekenTotalenNormaleRegels > ';
  //call TraceBegin(@@ErrorTextProcedure + '@ObvBesteldOfTeFact = ' + string(@ObvBesteldOfTeFact) + ', @OrkGid = ' + string(@OrkGid) + ', @Regelsoort = ' + string(@Regelsoort) + ', @OrkInclBtw = ' + string(@OrkInclBtw));

  case @ObvBesteldOfTeFact
  when 1 then //obv. aantal besteld
    if @OrkInclBtw = 1 then
      //Inclusief Btw; berekenen
    select isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld else OrrAantalBesteldVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ),0),
             isnull(sum( OrrRegelTotaal ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld else OrrAantalBesteldVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / (100+BtwPercentage )*BtwPercentage),0),
             isnull(sum( cast( OrrRegelTotaal / (100+BtwPercentage )*BtwPercentage as numeric(15,2) ) ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld else OrrAantalBesteldVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / ( 100 + BtwPercentage ) * 100  ), 0 ),
             isnull(sum( OrrRegelTotaal / ( 100 + BtwPercentage ) * 100 ), 0 )
      into   @TotBruto, @TotRegel, @BtwBruto, @BtwRegel, @BtwBasisBruto, @BtwBasisRegel
      from   tabOrderRegel inner join tabBtw on (BtwCode = OrrBtwCode)
      where  OrrOrkGid = @OrkGid and (OrrRegelSoort = @Regelsoort or @RegelSoort is null);
    else
      //Exclusief Btw; berekenen
      select isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld else OrrAantalBesteldVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ),0),
             isnull(sum( OrrRegelTotaal ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld else OrrAantalBesteldVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / 100 * BtwPercentage),0),
             isnull(sum( cast( ( OrrRegelTotaal / 100 ) * BtwPercentage as numeric(15,2) ) ), 0 ),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld else OrrAantalBesteldVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ), 0 ),
             isnull(sum( OrrRegelTotaal ), 0 )
      into   @TotBruto, @TotRegel, @BtwBruto, @BtwRegel, @BtwBasisBruto, @BtwBasisRegel
      from   tabOrderRegel inner join tabBtw on (BtwCode = OrrBtwCode)
      where  OrrOrkGid = @OrkGid and (OrrRegelSoort = @Regelsoort or @RegelSoort is null);
    end if;
  when 2 then //obv. aantal te fact.
    if @OrkInclBtw = 1 then
      //Inclusief Btw; berekenen
      select isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld - OrrAantalGefactureerd else OrrAantalBesteldVrrdEenh - OrrAantalGefactureerdVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ),0),
             isnull(sum( OrrTeFactRegelTotaal ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld - OrrAantalGefactureerd else OrrAantalBesteldVrrdEenh - OrrAantalGefactureerdVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / (100+BtwPercentage )*BtwPercentage),0),
             isnull(sum( cast( OrrTeFactRegelTotaal / (100+BtwPercentage )*BtwPercentage as numeric(15,2) ) ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld - OrrAantalGefactureerd else OrrAantalBesteldVrrdEenh - OrrAantalGefactureerdVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / ( 100 + BtwPercentage ) * 100  ), 0 ),
             isnull(sum( OrrTeFactRegelTotaal / ( 100 + BtwPercentage ) * 100 ), 0 )
      into   @TotBruto, @TotRegel, @BtwBruto, @BtwRegel, @BtwBasisBruto, @BtwBasisRegel
      from   tabOrderRegel inner join tabBtw on (BtwCode = OrrBtwCode)
      where  OrrOrkGid = @OrkGid and (OrrRegelSoort = @Regelsoort or @RegelSoort is null);
    else
      //Exclusief Btw; berekenen
      select isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld - OrrAantalGefactureerd else OrrAantalBesteldVrrdEenh - OrrAantalGefactureerdVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ),0),
             isnull(sum( OrrTeFactRegelTotaal ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld - OrrAantalGefactureerd else OrrAantalBesteldVrrdEenh - OrrAantalGefactureerdVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / 100 * BtwPercentage),0),
             isnull(sum( cast( ( OrrTeFactRegelTotaal / 100 ) * BtwPercentage as numeric(15,2) ) ), 0 ),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalBesteld - OrrAantalGefactureerd else OrrAantalBesteldVrrdEenh - OrrAantalGefactureerdVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ), 0 ),
             isnull(sum( OrrTeFactRegelTotaal ), 0 )
      into   @TotBruto, @TotRegel, @BtwBruto, @BtwRegel, @BtwBasisBruto, @BtwBasisRegel
      from   tabOrderRegel inner join tabBtw on (BtwCode = OrrBtwCode)
      where  OrrOrkGid = @OrkGid and (OrrRegelSoort = @Regelsoort or @RegelSoort is null);
    end if;
  when 3 then // obv. aantal deze facturering
    if @OrkInclBtw = 1 then
      //Inclusief Btw; berekenen
      select isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalDezeFacturering else OrrAantalDezeFactureringVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ),0),
             isnull(sum( OrrDezeFactRegelTotaal ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalDezeFacturering else OrrAantalDezeFactureringVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / (100+BtwPercentage )*BtwPercentage),0),
             isnull(sum( cast( OrrDezeFactRegelTotaal / (100+BtwPercentage )*BtwPercentage as numeric(15,2) ) ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalDezeFacturering else OrrAantalDezeFactureringVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / ( 100 + BtwPercentage ) * 100  ), 0 ),
             isnull(sum( OrrDezeFactRegelTotaal / ( 100 + BtwPercentage ) * 100 ), 0 )
      into   @TotBruto, @TotRegel, @BtwBruto, @BtwRegel, @BtwBasisBruto, @BtwBasisRegel
      from   tabOrderRegel inner join tabBtw on (BtwCode = OrrBtwCode)
      where  OrrOrkGid = @OrkGid and (OrrRegelSoort = @Regelsoort or @RegelSoort is null);
    else
      //Exclusief Btw; berekenen
      select isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalDezeFacturering else OrrAantalDezeFactureringVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ),0),
             isnull(sum( OrrDezeFactRegelTotaal ),0),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalDezeFacturering else OrrAantalDezeFactureringVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) / 100 * BtwPercentage),0),
             isnull(sum( cast( ( OrrDezeFactRegelTotaal / 100 ) * BtwPercentage as numeric(15,2) ) ), 0 ),
             isnull(sum( cast( (if OrrEenheidPrijsPer = 0 then OrrAantalDezeFacturering else OrrAantalDezeFactureringVrrdEenh endif) * OrrBrutoVerkoopprijs as numeric(15,2 ) ) ), 0 ),
             isnull(sum( OrrDezeFactRegelTotaal ), 0 )
      into   @TotBruto, @TotRegel, @BtwBruto, @BtwRegel, @BtwBasisBruto, @BtwBasisRegel
      from   tabOrderRegel inner join tabBtw on (BtwCode = OrrBtwCode)
      where  OrrOrkGid = @OrkGid and (OrrRegelSoort = @Regelsoort or @RegelSoort is null);
    end if;
  end case;

  set @@ErrorTextProcedure = 'OrderExtraRegelBerekenTotalenNormaleRegels';
  //call TraceEind(@@ErrorTextProcedure + ' > @TotBruto = ' + string(@TotBruto) + ', @TotRegel = ' + string(@TotRegel) + ', @BtwBruto = ' + string(@BtwBruto) + ', @BtwRegel = ' + string(@BtwRegel) + ', @BtwBasisBruto = ' + string(@BtwBasisBruto) + ', @BtwBasisRegel = ' + string(@BtwBasisRegel));
end;


create or replace procedure OrderLeveren(in @OrkGid integer, in @BoekDatum date, in @UitleverNummer numeric(10,0), in @JpGid integer)
begin

  declare @VorigeRegel    Integer;
  declare @HuidigeRegel   Integer;
  declare @MagGid         Integer;
  declare @BjGid          Integer;
  declare @PerNr          Integer;
  declare @IsStuksKorting SmallInt;
  declare @VrdMutGid      Integer;
  // Uit orderkop
  declare @OrkNawGid      Integer;
  declare @OrkNummer      numeric(10,0);
  declare @OrkValNummer   Integer;
  declare @OrkInclBtw     smallint;

  set @@ErrorTextProcedure = 'Begin OrderLeveren >  @OrkGid='+string(@OrkGid);
  //call Trace(@@ErrorTextProcedure);

  Set @MagGid = null;
  Set @BjGid  = null;
  Set @PerNr  = null;

  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid, @PerNr);

  Select first vofIsStukskorting into @IsStuksKorting from tabVasteGegevensOrdersFactureren;

  // Uitlezen velden uit orderkop
  select OrkNawGid, OrkNummer, OrkValNummer, OrkInclBtw
  into @OrkNawGid, @OrkNummer, @OrkValNummer, @OrkInclBtw
  from tabOrderkop
  where OrkGid = @OrkGid;

  // Lus op orderregels
  FOR @Cursor AS CURSOR_OrderRegelsLeveren CURSOR FOR
    select  OrrGid @OrrGid, OrrArtGid @OrrArtGid, OrrPrijsPer @OrrPrijsPer,
            (if (@OrkInclBtw = 1) then
              (if @IsStuksKorting = 1 then
                 //Stukskorting -> bereken via aantal-korting1-korting2
                 if (OrrIsKortingsPercentage = 0) then //Kortingsbedrag
                   ((OrrBrutoVerkoopPrijs - OrrRegelKorting1) * ((100 - OrrRegelKorting2) / 100))
                 else //Kortingspercentage
                   (OrrBrutoVerkoopPrijs * ((100 - OrrRegelKorting1) / 100) * ((100 - OrrRegelKorting2 ) / 100))
                 endif
               else
                 //Regelkorting -> bereken via regeltotaal/aantal besteld
                (OrrRegelTotaal / OrrAantalBesteld) * OrrPrijsPer
               endif) / ( 100 + BtwPercentage) * 100
             else
              (if @IsStuksKorting = 1 then
                 //Stukskorting -> bereken via aantal-korting1-korting2
                 if (OrrIsKortingsPercentage = 0) then //Kortingsbedrag
                   ((OrrBrutoVerkoopPrijs - OrrRegelKorting1) * ((100 - OrrRegelKorting2) / 100))
                 else //Kortingspercentage
                   (OrrBrutoVerkoopPrijs * ((100 - OrrRegelKorting1) / 100) * ((100 - OrrRegelKorting2 ) / 100))
                 endif
               else
                 //Regelkorting -> bereken via regeltotaal/aantalbesteld
                 (OrrRegelTotaal / OrrAantalBesteld) * OrrPrijsPer
               endif)
             endif) @PrijsRegelInValuta,
            if OrrEenheidPrijsPer = 0 /*VerkoopEenheid*/ then
              Round(@PrijsRegelInValuta * ArtPrijsPer / OrrAantalVrrdEenhInVerkEenh, OrrAantDecBedrag)
            else
              (if @IsStuksKorting = 1 then
                Round(@PrijsRegelInValuta , OrrAantDecBedrag)
               else
                Round(@PrijsRegelInValuta / OrrAantalVrrdEenhInVerkEenh, OrrAantDecBedrag)
               endif)
            endif @PrijsInValuta,
            (if (@OrkValNummer = @@BasisValutaNummer) then @PrijsInValuta else ValutaOmrekenen(@OrkValNummer, @PrijsInValuta, @@BasisValutaNummer, @BjGid, @PerNr, 2) endif) @PrijsInBasis,
            OrrKostprijs @OrrKostprijs,
            OrrAantalLeveringVrrdEenh @OrrAantalLeveringVrrdEenh,
            OrrAantalTotaalLevVanDetail @OrrAantalTotaalLevVanDetail
    from    tabArtikel inner join tabOrderRegel on (OrrArtGid = ArtGid) left outer join tabBtw on (BtwCode = OrrBtwCode)
    where  (OrrOrkGid = @OrkGid)
      and  (OrrRegelSoort = 2)
      and  (OrrAantalLeveringVrrdEenh <> 0) and (ArtMutatieVerkoopBijhouden <> 0)
  FOR READ ONLY
  DO
    //call Trace('@PrijsRegelInValuta='+string(@PrijsRegelInValuta)+' @PrijsInValuta='+string(@PrijsInValuta));

    // ACW Defect 59914: Bij leveren zeker weten dat we de spec.regels hebben (worden eventueel aangemaakt in de trigger van orderregel)
    if (@OrrAantalLeveringVrrdEenh <> @OrrAantalTotaalLevVanDetail) and (IsOrderSpecificatieregelActief() = 0) then
      update taborderregel set orrgid = orrgid where orrgid = @orrgid;
    end if;

    // Orderregel van deze order in voorraadmutatie toevoegen
    set @@ErrorTextProcedure = 'OrderLeveren > Orderregel (@OrrGid='+string(@OrrGid)+') > Toevoegen aan tabVoorraadmutatie';
    //call Trace(@@ErrorTextProcedure);
    insert into tabVoorraadMutatie
           (vrdMutArtGid,              vrdMutNawGid,        vrdMutDatum,          vrdMutSoort,
            VrdMutUitleverOntvangstNr, VrdMutOrderBestelNr, vrdMutValNummer,      vrdMutGeprijsdPer,
            vrdMutPrijsInValuta,       vrdMutPrijsInBasis,  vrdMutHistKostprijs,  vrdMutGebruikerCode,
            VrdMutJpGid)
    values( @OrrArtGid,                @OrkNawGid,          @BoekDatum,           1,
            @UitleverNummer,           @OrkNummer,          @OrkValNummer,        @OrrPrijsPer,
            @PrijsInValuta,            @PrijsInBasis,       @OrrKostprijs,        @@GebruikerCode,
            @JpGid);

    set @VrdMutGid = @@Identity;
    set @@ErrorTextProcedure = 'OrderLeveren > Orderregel (@OrrGid='+string(@OrrGid)+') > Toevoegen aan tabVoorraadmutatieLocatieSerie';
    //call Trace(@@ErrorTextProcedure);
    // Orderregellocaties van deze orderregel in voorraadmutatie toevoegen
    insert into tabVoorraadMutatieLocatieSerie(VrdMutLocVrdMutGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer, VrdMutLocAantal)
    select @VrdMutGid,
           if (OrlLocGid is null) or (@@ModuleM1 = 0) then
             (select isnull(ArtMagDefaultLocGid,  // Default locatie van dit artikel in het magazijn of, indien niet ingevuld
                            (select first LocGid from tabLocatie where LocNaam='(Standaard)' and (LocMagGid = OrlMagGid) )  // de standaard locatie
                           )
             )
           else
            OrlLocGid
           endif,
           ArtPartijNummer, ArtSerienummer, -OrlDezeLeveringVrrdEenh
    from   tabOrderRegelLocatie
           left outer join tabArtikelPartij on (ArtPartijGid = OrlArtPartijGid)
           left outer join tabArtikelSerienummer on (ArtSerieGid = OrlArtSerieGid)
           left outer join tabArtikelMagazijn    on (ArtMagMagGid = OrlMagGid and ArtMagArtGid = @OrrArtGid)
    where  (OrlOrrGid = @OrrGid)
      and  (OrlDezeLeveringVrrdEenh <> 0.00);   // RB / 10-11-03 : Toegevoegd. Anders werden oude deelleveringen nogmaals meegenomen in voorraadmutatie (met aantal 0.00)


  END FOR; // CURSOR_OrderRegelsLeveren

  // ACW 11-06-2003: Alle serienummers vullen met de juiste garantiegegevens bij leveren
  FOR @SerieCursor AS CURSOR_OrderRegelLocatie CURSOR FOR
    select OrlArtSerieGid @SerieGid
    from   tabOrderRegelLocatie
           inner join tabOrderRegel on (OrrGid = OrlOrrGid)
           inner join tabArtikel    on (ArtGid = OrrArtGid)
    where  OrrOrkGid = @OrkGid
           and OrrRegelSoort = 2 // Artikelen
           and ArtGarantieVullenBijLeveren <> 0
    FOR READ ONLY
  DO
    call UpdateGarantieSerieNummer(@SerieGid, @BoekDatum, 0);
  END FOR; // CURSOR_OrderRegelLocatie


  set @@ErrorTextProcedure = 'OrderLeveren > Bijwerken aantallen orderregels van order @orkgid='+string(@OrkGid);
  //call Trace(@@ErrorTextProcedure);
  set @@InFacturering = @@InFacturering + 1;

  update tabOrderRegel
  set    OrrAantalGeleverd = if OrrRegelSoort = 0 then 1 else isnull(OrrAantalGeleverd,0) + OrrAantalLevering endif,
         OrrAantalLevering = 0,
         OrrAantalGeleverdVrrdEenh = if OrrRegelSoort = 0 then 1 else isnull(OrrAantalGeleverdVrrdEenh,0) + OrrAantalLeveringVrrdEenh endif,
         OrrAantalLeveringVrrdEenh = 0
  from   tabOrderRegel
  where (OrrOrkGid = @OrkGid);

  set @@ErrorTextProcedure = 'OrderLeveren > Bijwerken aantallen orderregellocaties van order @orkgid='+string(@OrkGid);
  //call Trace(@@ErrorTextProcedure);

//  update tabOrderRegelLocatie
//  set    OrlGeleverd     = OrlGeleverd + OrlDezeLevering,
//         OrlDezeLevering = 0

   // --- Verwijderen geleverde specificatieregels
  // Daarvoor eerst aangeven dat de nummers niet autom. zijn aangemaakt (ivm. ongewenst verwijderen uit serienummertabel)
  update tabOrderRegelLocatie set OrlIsPartijNetAangemaakt = 0, OrlIsSerieNetAangemaakt = 0
  from   tabOrderRegelLocatie inner join tabOrderRegel
  where      (OrrOrkGid = @OrkGid)
         and (OrlDezeLevering <> 0)
         and (OrlDezeLeveringVrrdEenh <> 0)
         and (   (OrlIsPartijNetAangemaakt <> 0)
              or (OrlIsSerieNetAangemaakt <> 0)
             );
  // en daarna de regels weggooien
  delete from tabOrderRegelLocatie where OrlGid in (Select OrlGid FROM tabOrderRegelLocatie inner join tabOrderRegel
  where  OrrOrkGid = @OrkGid and OrlDezeLevering <> 0 and OrlDezeLeveringVrrdEenh <> 0);

  // --- Verwijderen order-colli ---
  delete tabOrderColli where OrclOrkGid = @OrkGid;

  call Maatwerk_LeveringOrderAantallenBijgewerkt(@OrkGid);

  set @@InFacturering = @@InFacturering - 1;

  set @@ErrorTextProcedure = 'Einde OrderLeveren > @OrkGid='+string(@OrkGid);
  //call Trace(@@ErrorTextProcedure);
end;


create or replace procedure OrderRegelOvernemenVrijeRubrieken(in @OrrGid integer)
begin
  declare @ArtGid             integer;
  declare @VeldNaam           nchar(20);
  declare @VeldInhoudChar     nchar(255);
  declare @VeldInhoudNumeric  numeric(16,5);
  declare @VeldInhoudSelectie smallint;
  declare @VeldInhoudDate     date;
  declare @VeldInhoudTime     time;
  declare @SrcVeldNaam        nchar(30);

  set @@ErrorTextProcedure = 'OrderRegelOvernemenVrijeRubrieken > @OrrGid='+string(@OrrGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select OrrArtGid into @ArtGid from tabOrderRegel where OrrGid = @OrrGid and OrrRegelSoort = 2;

  call VrijeRubriekenVulDefaults('ORR', 0, 0, @OrrGid, 0);

  if @ArtGid is not null then
    // De vrije rubrieken van artikel overnemen naar de orderregel
    for @Cursor AS cursor_VrijeRubriekenRegel CURSOR FOR
      select ORR.VrVeldNaam @OrrVrVeldNaam, ORR.VrLabel @OrrVrLabel, ORR.VrType @OrrVrVeldType, ORR.VrLengte @OrrVrLengte, ORR.VrDecimalen @OrrVrDecimalen, ORR.VrSjabloon @OrrVrSjabloon, ART.VrGid @ArtVrGid, ART.VrType @ArtVrType, ART.VrVeldnaam @ArtVrVeldNaam, ART.VrDefaultDate @ArtVrDefaultDate, ART.VrDefaultGetal @ArtVrDefaultGetal, ART.VrDefaultString @ArtVrDefaultString, ART.VrDefaultTime @ArtVrDefaultTime
      from   tabVrijeRubrieken ORR
      inner join tabVrijeRubrieken ART on ART.VrBestandOms = 'ART' and ART.VrGroepId = 0 and ART.VrSubGroepId = 0 and ART.VrLabel = ORR.VrLabel and ART.VrType = ORR.VrType and ART.VrLengte = ORR.VrLengte and ART.VrDecimalen = ORR.VrDecimalen and ART.VrSjabloon = ORR.VrSjabloon
      where  ORR.VrBestandOms = 'ORR'
    for read only
    do
      // Alle order vrije rubrieken doorlopen die ook als ART vrije rubriek voorkomen met dezelfde kenmerken
      //call Trace('---->@OrrVrLabel='+string(@OrrVrLabel)+', @OrrVrVeldNaam='+string(@OrrVrVeldNaam)+', @ArtVrVeldNaam='+string(@ArtVrVeldNaam));

      // Er is een vrije rubrieken record voor deze regel !
      if exists(select 1 from tabVrORR000000 where VrORR000000RecordId = @OrrGid) then
        //call Trace('update tabVrORR000000 set '+@OrrVrVeldNaam+' = (select '+string(@ArtVrVeldNaam)+' from tabVrArt000000 where VrArt000000RecordId = '+string(@ArtGid)+') where VrORR000000RecordId = @OrrGid;');
        execute immediate ('update tabVrORR000000 set '+string(@OrrVrVeldNaam)+' = (select '+string(@ArtVrVeldNaam)+' from tabVrArt000000 where VrArt000000RecordId = @ArtGid) where VrORR000000RecordId = @OrrGid;');
      else
        //call Trace('insert into tabVrORR000000 (VrORR000000RecordId, '+string(@OrrVrVeldNaam)+') values (@OrrGid, (select '+string(@ArtVrVeldNaam)+' from tabVrART000000 where VrArt000000RecordId = @ArtGid));');
        execute immediate ('insert into tabVrORR000000 (VrORR000000RecordId, '+string(@OrrVrVeldNaam)+') values (@OrrGid, (select '+string(@ArtVrVeldNaam)+' from tabVrArt000000 where VrArt000000RecordId = @ArtGid));');
      end if;
    end for;
  end if;

  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure OrderRegelOvernemenVrijeRubriekenHistorie(in @OrrGid integer, in @FrGid integer)
begin
  declare @ArtGid             integer;
  declare @VeldNaam           nchar(20);
  declare @VeldInhoudChar     nchar(255);
  declare @VeldInhoudNumeric  numeric(16,5);
  declare @VeldInhoudSelectie smallint;
  declare @VeldInhoudDate     date;
  declare @VeldInhoudTime     time;
  declare @SrcVeldNaam        nchar(30);

  set @@ErrorTextProcedure = 'OrderRegelOvernemenVrijeRubriekenHistorie > @OrrGid='+string(@OrrGid) + '; @FrGid='+string(@FrGid);
  //call TraceBegin(@@ErrorTextProcedure);

   for @Cursor AS cursor_VrijeRubrieken_Hist CURSOR FOR
    select
      FvrGid      @FvrGid,
      VrLabel     @VrLabel,
      VrVeldNaam  @VrVeldNaam,
      (case FvrType
        when 0 then 'FvrInhoudChar'
        when 5 then 'FvrInhoudChar'
        when 6 then 'FvrInhoudChar'
        when 7 then 'FvrInhoudChar'
        when 8 then 'FvrInhoudChar'
        when 9 then 'FvrInhoudChar'
        when 1 then 'FvrInhoudNumeric'
        when 2 then 'FvrInhoudDate'
        when 3 then 'FvrInhoudTime'
        when 4 then 'FvrInhoudSelectie'
      end) as     @FactHistVrVeldNaam
    from tabVrijeRubrieken
    inner join tabFactuurVrijeRubriek on VrVeldNaam = FvrVeldnaam and FvrFrGid = @FrGid and FvrSoort = 4
    where VrBestandOms = 'ORR' and ((FvrType in (0,5,6,7,8,9) and FvrInhoudChar is not null) or
                                                      (FvrType = 1 and FvrInhoudNumeric is not null) or
                                                      (FvrType = 2 and FvrInhoudDate is not null) or
                                                      (FvrType = 3 and FvrInhoudTime is not null) or
                                                      (FvrType = 4 and FvrInhoudSelectie is not null))
  for read only
  do
    // Alle historie vrije rubrieken doorlopen die bestaan als ORR vrije rubriek EN een historische waarde hebben
    //call Trace('---->@VrLabel='+string(@VrLabel)+', @VrVeldNaam='+string(@VrVeldNaam)+', @FvrGid='+string(@FvrGid));

    // Er is een vrije rubrieken record voor deze orderregel
    if exists(select 1 from tabVrORR000000 where VrORR000000RecordId = @OrrGid) then
      //call Trace('update tabVrORR000000 set '+string(@VrVeldNaam)+' = (select '+string(@FactHistVrVeldNaam)+' from tabFactuurVrijeRubriek where FvrGid = '+ string(@FvrGid)+') where VrORR000000RecordId = @OrrGid;');
      execute immediate ('update tabVrORR000000 set '+string(@VrVeldNaam)+' = (select '+string(@FactHistVrVeldNaam)+' from tabFactuurVrijeRubriek where FvrGid = '+string(@FvrGid)+') where VrORR000000RecordId = @OrrGid;');
    else
      //call Trace('insert into tabVrORR000000 (VrORR000000RecordId, '+string(@VrVeldNaam)+') values (@OrrGid, (select '+string(@FactHistVrVeldNaam)+' from tabFactuurVrijeRubriek where FvrGid = '+ string(@FvrGid)+');');
      execute immediate ('insert into tabVrORR000000 (VrORR000000RecordId, '+string(@VrVeldNaam)+') values (@OrrGid, (select '+string(@FactHistVrVeldNaam)+' from tabFactuurVrijeRubriek where FvrGid = '+string(@FvrGid)+');');
    end if;

  end for;

  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure OrderRegelpositieWijzigen(
 in @OrrGid          integer,
 in @VerplaatsenNaar smallint, //0 = ga naar eerste regel, 1 = ga een positie omhoog, 2 = ga een positie omlaag, 3 = ga naar laatste regel, overig=ongeldige waarde
 out @NieuwePositie  smallint
)
begin
  declare @OrkGid                 integer;
  declare @MasterHuidigePositie   smallint;
  declare @MasterNieuwePositie    smallint;
  declare @MasterAantalVolgregels smallint;

  declare @LaatsteRegelpositie smallint;
  //call TraceBegin('OrderRegelpositieWijzigen(@OrrGid=' + string(@OrrGid) + ', @VerplaatsenNaar=' + string(@VerplaatsenNaar) + ' (0=naar eerste regel, 1=een regel omhoog, 2=een regel omlaag, 3=naar laatste regel, overig=ongeldige waarde)');

  //bepalen of het een volgregel is, zo ja, dan master gidje als uitgangspunt gebruiken.
  set @OrrGid = IsNull((select OrrVervolgMasterOrrGid from tabOrderregel where OrrGid = @OrrGid), @OrrGid);
  //call Trace('definitieve @OrrGid=' + string(@OrrGid) + ' (= waarde hoofdregel (indien originele regel volgregel was)');

  //versiegidje en masterregel positie bepalen
  select OrrOrkGid, OrrRegelnr into @OrkGid, @MasterHuidigePositie from tabOrderregel where OrrGid = @OrrGid;
  //call Trace('@OrkGid=' + IsNull(string(@OrkGid), 'null') + ', @MasterHuidigePositie=' + IsNull(string(@MasterHuidigePositie),'null') + if (@OfkGid * @MasterHuidigePositie) is null then ' ==> PROCEDURE AFBREKEN: een of meer verplichte variabelen zijn null' endif);

  if @OrkGid is not null and @MasterHuidigePositie is not null then
    set @MasterAantalVolgregels = (select count(*) from tabOrderregel where OrrVervolgMasterOrrGid = @OrrGid);

    if not @VerplaatsenNaar between 0 and 3 then
      //call Trace('@VerplaatsenNaar=' + string(@VerplaatsenNaar) + ' ==> PROCEDURE AFBREKEN: ongeldige waarde @VerplaatsenNaar');
    else
      set @MasterNieuwePositie = (case @VerplaatsenNaar
                                   /*eerste regel */ when 0 then (select first OrrRegelnr from tabOrderregel where OrrOrkGid = @OrkGid and OrrVervolgMasterOrrGid is null and OrrRegelnr < @MasterHuidigePositie order by OrrRegelnr)
                                   /*regel omhoog */ when 1 then (select first OrrRegelnr from tabOrderregel where OrrOrkGid = @OrkGid and OrrVervolgMasterOrrGid is null and OrrRegelnr < @MasterHuidigePositie order by OrrRegelnr desc)
                                   /*regel omlaag */ when 2 then (select first OrrRegelnr from tabOrderregel where OrrOrkGid = @OrkGid and OrrVervolgMasterOrrGid is null and OrrRegelnr > @MasterHuidigePositie order by OrrRegelnr)
                                   /*laatste regel*/ when 3 then (select first OrrRegelnr from tabOrderregel where OrrOrkGid = @OrkGid and OrrVervolgMasterOrrGid is null and OrrRegelnr > @MasterHuidigePositie order by OrrRegelnr desc)
                                 end);
      //als het veld niet gevuld is dan is verplaatsen niet mogelijk en vullen we het huidige regelnummer in zodat er niets gebeurt.
      //call Trace(if @MasterNieuwePositie is null then '==> PROCEDURE AFBREKEN: @MasterNieuwePositie is null (waarschijnlijk was regel was al eerste of laatste regel)' else '@MasterNieuwePositie=' + string(@MasterNieuwePositie) endif);
    end if;

    set @MasterNieuwePositie = IsNull(@MasterNieuwePositie, @MasterHuidigePositie);

    //call Trace('@MasterHuidigePositie='+String(@MasterHuidigePositie) + '  @MasterNieuwePositie='+String(@MasterNieuwePositie));

    if @MasterHuidigePositie <> @MasterNieuwePositie then
      //call Trace('de betreffende regel (en evt volgregels) uit de regelpositie verwijderen door regelpositie(s) negatief te maken');
      update tabOrderregel
      set    OrrRegelnr = 0
      where  OrrGid = @OrrGid
      or     OrrVervolgMasterOrrGid = @OrrGid;

      if @MasterHuidigePositie > @MasterNieuwePositie then
        //call TraceBegin('Naar boven verplaatsen');
        update tabOrderregel
        set    OrrRegelnr = OrrRegelnr + @MasterAantalVolgregels + 1
        where  OrrOrkGid = @OrkGid
           and OrrRegelnr >= @MasterNieuwePositie
           and OrrRegelnr <  @MasterHuidigePositie
        order by OrrRegelnr desc;

        update tabOrderregel
        set    OrrRegelnr = @MasterNieuwePositie + number(*) - 1
        where  OrrGid = @OrrGid
        or     OrrVervolgMasterOrrGid = @OrrGid
        order by OrrVervolgMasterOrrGid, OrrRegelnr desc;
        //call TraceEind('Naar boven verplaatsen');
      else
        //call TraceBegin('Naar beneden verplaatsen');
        begin
          declare @TargetOrrGid           integer;
          declare @TargetAantalVolgregels smallint;
          declare @TargetLastRegelnr      integer;
          declare @TeVerplaatsenRegels    integer;

          set @TargetOrrGid = (select first OrrGid from tabOrderregel where OrrOrkGid = @OrkGid and OrrRegelnr = @MasterNieuwePositie);
          set @TargetAantalVolgregels = (select count(*) from tabOrderregel where OrrVervolgMasterOrrGid = @TargetOrrGid);
          if @TargetAantalVolgregels=0 then
            set @TargetLastRegelnr=@MasterNieuwePositie
          else
            set @TargetLastRegelnr = (select first OrrRegelnr from tabOrderregel where OrrOrkGid = @OrkGid and OrrVervolgMasterOrrGid = @TargetOrrGid order by OrrRegelnr desc);
          endif;

          //call Trace('@TargetOfrGid=' + string(@TargetOrrGid) + ', @TargetAantalVolgregels=' + string(@TargetAantalVolgregels) + '  @TargetLastRegelnr='+String(@TargetLastRegelnr) );

          //call Trace('update: volgende regel (en evt volgregels) omhoog schuiven');

          set @TeVerplaatsenRegels = (Select count(1)
                                      from tabOrderregel
                                      where  OrrOrkGid = @OrkGid
                                      and OrrRegelnr >  @MasterHuidigePositie
                                      and OrrRegelnr <= @TargetLastRegelnr);

          update tabOrderregel
          //set    OrrRegelnr = OrrRegelnr - @MasterAantalVolgregels - 1
          set    OrrRegelnr = @MasterHuidigePositie + number(*) - 1
          where  OrrOrkGid = @OrkGid
             and OrrRegelnr >  @MasterHuidigePositie
             and OrrRegelnr <= @TargetLastRegelnr  //@MasterNieuwePositie + @TargetAantalVolgregels
          order by OrrRegelnr;

          //call Trace('update: te verplaatsen regel (en evt volgregels) op nieuwe positie invoegen in range');
          update tabOrderregel
          //set    OrrRegelnr = @MasterNieuwePositie - @MasterAantalVolgregels + @TargetAantalVolgregels + number(*) - 1
          set    OrrRegelnr = @MasterHuidigePositie + @TeVerplaatsenRegels + number(*) -1
          where  OrrGid = @OrrGid
          or     OrrVervolgMasterOrrGid = @OrrGid
          order by OrrVervolgMasterOrrGid, OrrRegelnr desc;
        end;
        //call TraceEind('Naar beneden verplaatsen');
      end if;
    end if;

    set @NieuwePositie = (select OrrRegelnr from tabOrderregel where OrrGid = @OrrGid);
  end if;

  //call TraceEind('OrderRegelpositieWijzigen(@NieuwePositie=' + string(@NieuwePositie) + ')');
end;


//$Workfile: OrdersGenereerNieuwOrderNummer.sp $ $Revision: 3 $ $Modtime: 15-09-10 8:23 $'

if exists (select 1 from sys.sysProcedure where proc_name='OrdersGenereerNieuwOrderNummer') then
  drop procedure OrdersGenereerNieuwOrderNummer;
end if;

create procedure OrdersGenereerNieuwOrderNummer(in @OrkSoort smallint, in @Forceer smallint, out @Nummer numeric(10,0))
begin
  declare @Genereren numeric(10,0);
  declare @Startnummer numeric(10,0);
  declare @gevonden integer;
  declare @lockres integer;

  set @@ErrorTextProcedure = 'OrdersGenereerNieuwOrderNummer > @OrkSoort='+string(@OrkSoort) + ', @Forceer='+string(@Forceer);
  //call TraceBegin(@@ErrorTextProcedure);

 //MR 15-sep-2010 bug #32277: Lockloop ingebouwd zodat maar 1 nummer per keer word gegeven.
 //Dit deel moet uniek gelocked (met een wacht-lus)
  call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'OrdersGenereerNieuwOrderNummer','');

  set @nummer=0;
  if @Forceer = 1 or @OrkSoort <> 0 then
    set @Genereren=1;
    case @OrkSoort
      when 0 then select vofKopStartNummer into @startnummer from tabVasteGegevensOrdersFactureren;
      when 1 then select ProjVastOrderStartnummer into @startnummer from tabprojectVasteGegevens;
    end case;
  else
    select vofKopIsOrderNummerGenereren, vofKopStartNummer into @Genereren, @startnummer from tabVasteGegevensOrdersFactureren;
  end if;

  if @genereren=1 then
    set @gevonden=0;
    while @gevonden=0
    loop
      set @nummer = null;
      select min(OrkNummer) into @nummer from tabOrderKop where OrkNummer>=@startnummer and OrkSoort = @OrkSoort;
      if @nummer is null then
        set @gevonden=1;
        set @nummer=@startnummer;
      else
        if @nummer=@startnummer then
          if @startnummer=9999999999 then
            set @startnummer=1;
          else
            set @startnummer=@nummer+1;
          end if
        else
          // Eerstvolgende ligt toch hoger, dus we kunnen gewoon het startnummer gebruiken
          set @nummer=@startnummer;
          set @gevonden=1;
        end if;
      end if;
    end loop;
    if @OrkSoort = 0 then
      if @nummer=9999999999 then
        update tabVasteGegevensOrdersFactureren set vofKopStartNummer=1;
      else
        update tabVasteGegevensOrdersFactureren set vofKopStartNummer=@nummer+1;
      end if;
    end if;
    if @OrkSoort = 1 then
      if @nummer=9999999999 then
        update tabprojectVasteGegevens set ProjVastOrderStartnummer=1;
      else
        update tabprojectVasteGegevens set ProjVastOrderStartnummer=@nummer+1;
      end if;
    end if;
  end if;

  //NawGenereernummers-lock weer vrijgeven
  call LockreleaseOnId(@@SpId,@@LoginTime,1,'OrdersGenereerNieuwOrderNummer','');

  set @@ErrorTextProcedure = 'OrdersGenereerNieuwOrderNummer > @Nummer='+string(@Nummer);
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure OrdersOvernemenVrijeRubrieken(in @OrkGid integer)
begin
  declare @NawGid             integer;
  declare @VeldNaam           nchar(20);
  declare @VeldInhoudChar     nchar(255);
  declare @VeldInhoudNumeric  numeric(16,5);
  declare @VeldInhoudSelectie smallint;
  declare @VeldInhoudDate     date;
  declare @VeldInhoudTime     time;
  declare @SrcVeldNaam        nchar(30);

  set @@ErrorTextProcedure = 'OrdersOvernemenVrijeRubrieken > @OrkGid='+string(@OrkGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select OrkNawGid into @NawGid from tabOrderKop where OrkGid = @OrkGid;

  call VrijeRubriekenVulDefaults('ORK', 0, 0, @OrkGid, 0);

  for @Cursor AS cursor_VrijeRubrieken CURSOR FOR
    select ORK.VrVeldNaam @OrkVrVeldNaam, ORK.VrLabel @OrkVrLabel, ORK.VrType @OrkVrVeldType, ORK.VrLengte @OrkVrLengte, ORK.VrDecimalen @OrkVrDecimalen, ORK.VrSjabloon @OrkVrSjabloon, NAW.VrGid @NawVrGid, NAW.VrType @NawVrType, NAW.VrVeldnaam @NawVrVeldNaam, NAW.VrDefaultDate @NawVrDefaultDate, NAW.VrDefaultGetal @NawVrDefaultGetal, NAW.VrDefaultString @NawVrDefaultString, NAW.VrDefaultTime @NawVrDefaultTime
    from   tabVrijeRubrieken ORK
    inner join tabVrijeRubrieken NAW on NAW.VrBestandOms = 'NAW' and NAW.VrGroepId = 1 and NAW.VrSubGroepId = 1 and NAW.VrLabel = ORK.VrLabel and NAW.VrType = ORK.VrType and NAW.VrLengte = ORK.VrLengte and NAW.VrDecimalen = ORK.VrDecimalen and NAW.VrSjabloon = ORK.VrSjabloon
    where  ORK.VrBestandOms = 'ORK'
  for read only
  do
    // Alle order vrije rubrieken doorlopen die ook als NAW vrije rubriek voorkomen met dezelfde kenmerken
    //call Trace('---->@OrkVrLabel='+string(@OrkVrLabel)+', @OrkVrVeldNaam='+string(@OrkVrVeldNaam)+', @NawVrVeldNaam='+string(@NawVrVeldNaam));

    // Er is een vrije rubrieken record voor deze debiteur !
    if exists(select 1 from tabVrORK000000 where VrORK000000RecordId = @OrkGid) then
      //call Trace('update tabVrORK000000 set '+@OrkVrVeldNaam+' = (select '+string(@NawVrVeldNaam)+' from tabVrNAW001001 where VrNaw001001RecordId = '+string(@NawGid)+') where VrORK000000RecordId = @OrkGid;');
      execute immediate ('update tabVrORK000000 set '+string(@OrkVrVeldNaam)+' = (select '+string(@NawVrVeldNaam)+' from tabVrNAW001001 where VrNaw001001RecordId = @NawGid) where VrORK000000RecordId = @OrkGid;');
    else
      //call Trace('insert into tabVrORK000000 (VrORK000000RecordId, '+string(@OrkVrVeldNaam)+') values (@OrkGid, (select '+string(@NawVrVeldNaam)+' from tabVrNAW001001 where VrNaw001001RecordId = @NawGid));');
      execute immediate ('insert into tabVrORK000000 (VrORK000000RecordId, '+string(@OrkVrVeldNaam)+') values (@OrkGid, (select '+string(@NawVrVeldNaam)+' from tabVrNAW001001 where VrNaw001001RecordId = @NawGid));');
    end if;

  end for;

  //call TraceEind(@@ErrorTextProcedure);

end;
//call OrdersOvernemenVrijeRubrieken(0);


create or replace procedure OrdersOvernemenVrijeRubriekenHistorie(in @OrkGid integer, in @FrefGid integer)
begin
  declare @NawGid             integer;
  declare @VeldNaam           nchar(20);
  declare @VeldInhoudChar     nchar(255);
  declare @VeldInhoudNumeric  numeric(16,5);
  declare @VeldInhoudSelectie smallint;
  declare @VeldInhoudDate     date;
  declare @VeldInhoudTime     time;
  declare @SrcVeldNaam        nchar(30);

  set @@ErrorTextProcedure = 'OrdersOvernemenVrijeRubriekenHistorie > @OrkGid='+string(@OrkGid) +'; @FrefGid='+string(@FrefGid);
  //call TraceBegin(@@ErrorTextProcedure);

    for @Cursor AS cursor_VrijeRubrieken_Hist CURSOR FOR
    select
      FvrGid      @FvrGid,
      VrLabel     @VrLabel,
      VrVeldNaam  @VrVeldNaam,
      (case FvrType
        when 0 then 'FvrInhoudChar'
        when 5 then 'FvrInhoudChar'
        when 6 then 'FvrInhoudChar'
        when 7 then 'FvrInhoudChar'
        when 8 then 'FvrInhoudChar'
        when 9 then 'FvrInhoudChar'
        when 1 then 'FvrInhoudNumeric'
        when 2 then 'FvrInhoudDate'
        when 3 then 'FvrInhoudTime'
        when 4 then 'FvrInhoudSelectie'
      end) as     @FactHistVrVeldNaam
    from tabVrijeRubrieken
    inner join tabFactuurVrijeRubriek on VrVeldNaam = FvrVeldnaam and FvrFrefGid = @FrefGid and FvrSoort = 3
    where VrBestandOms = 'ORK' and ((FvrType in (0,5,6,7,8,9) and FvrInhoudChar is not null) or
                                                      (FvrType = 1 and FvrInhoudNumeric is not null) or
                                                      (FvrType = 2 and FvrInhoudDate is not null) or
                                                      (FvrType = 3 and FvrInhoudTime is not null) or
                                                      (FvrType = 4 and FvrInhoudSelectie is not null))
  for read only
  do
    // Alle historie vrije rubrieken doorlopen die bestaan als ORK vrije rubriek EN een historische waarde hebben
    //call Trace('---->@VrLabel='+string(@VrLabel)+', @VrVeldNaam='+string(@VrVeldNaam)+', @FvrGid='+string(@FvrGid));

    // Er is een vrije rubrieken record voor deze order
    if exists(select 1 from tabVrORK000000 where VrORK000000RecordId = @OrkGid) then
      //call Trace('update tabVrORK000000 set '+string(@VrVeldNaam)+' = (select '+string(@FactHistVrVeldNaam)+' from tabFactuurVrijeRubriek where FvrGid = '+ string(@FvrGid)+') where VrORK000000RecordId = @OrkGid;');
      execute immediate ('update tabVrORK000000 set '+string(@VrVeldNaam)+' = (select '+string(@FactHistVrVeldNaam)+' from tabFactuurVrijeRubriek where FvrGid = '+string(@FvrGid)+') where VrORK000000RecordId = @OrkGid;');
    else
      //call Trace('insert into tabVrORK000000 (VrORK000000RecordId, '+string(@VrVeldNaam)+') values (@OrkGid, (select '+string(@FactHistVrVeldNaam)+' from tabFactuurVrijeRubriek where FvrGid = '+ string(@FvrGid)+');');
      execute immediate ('insert into tabVrORK000000 (VrORK000000RecordId, '+string(@VrVeldNaam)+') values (@OrkGid, (select '+string(@FactHistVrVeldNaam)+' from tabFactuurVrijeRubriek where FvrGid = '+string(@FvrGid)+');');
    end if;

  end for;

  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure OrderVulBtwTotalen( in @OrkGid integer )
begin
  //Maakt de BTW-regels voor een order aan (inclusief eventuele kredietbeperking)
  declare @OrkInclBtw               smallint;
  declare @BtwCode                  integer;
  declare @VorigBtwCode             integer;
  declare @BtwPerc                  numeric(6,2);
  declare @TotaalRegels             numeric(15,2);
  declare @TeFactTotaalRegels       numeric(15,2);
  declare @BtwBasisRegels           numeric(15,2);
  declare @TeFactBtwBasisRegels     numeric(15,2);
  declare @TotaalInclBtwRegels      numeric(15,2); //Alleen geldig indien het een order incl.btw betreft!
  declare @TeFactTotaalInclBtwRegels numeric(15,2); //Alleen geldig indien het een order incl.btw betreft!
  declare @BtwBedragRegels          numeric(15,2);
  declare @BtwBasisExtra            numeric(15,2);
  declare @TeFactBtwBasisExtra      numeric(15,2);
  declare @TotaalInclBtwExtra       numeric(15,2); //Alleen geldig indien het een order incl.btw betreft!
  declare @TeFactTotaalInclBtwExtra numeric(15,2); //Alleen geldig indien het een order incl.btw betreft!
  declare @BtwBasisExtraZonder      numeric(15,2);
  declare @TotaalInclBtwExtraZonder numeric(15,2); //Alleen geldig indien het een order incl.btw betreft!
  declare @TeFactBtwBasisExtraZonder numeric(15,2);
  declare @TeFactTotaalInclBtwExtraZonder numeric(15,2);
  declare @DezeFactTotaalRegels       numeric(15,2);
  declare @DezeFactBtwBasisRegels     numeric(15,2);
  declare @DezeFactTotaalInclBtwRegels numeric(15,2); //Alleen geldig indien het een order incl.btw betreft!
  declare @DezeFactBtwBasisExtra      numeric(15,2);
  declare @DezeFactTotaalInclBtwExtra numeric(15,2); //Alleen geldig indien het een order incl.btw betreft!
  declare @DezeFactBtwBasisExtraZonder numeric(15,2);
  declare @DezeFactTotaalInclBtwExtraZonder numeric(15,2);

  declare @BtcSoort                 smallint;
  declare @KredBepPerc              numeric(6,2);
  declare @valnummer                integer;
  declare @TotaalBasisVolgensBtw    numeric(15,2);
  //tbv. kredietbeperking
  declare @KredBepVolgensBTW        numeric(15,2);
  declare @KredBepVolgensRegels     numeric(15,2);

  set @@ErrorTextProcedure = 'OrderVulBtwTotalen > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @OrkGid = ' + string(@OrkGid));

  delete from tmpOrkBtw where tmpOrkOrkGid = @OrkGid;
  select orkvalnummer, OrkInclBtw into @valnummer, @OrkInclBtw from taborderkop where orkgid=@orkgid;
  set @VorigBtwCode = -1;
  loopBtw:
  Loop
    set @BtwCode = null;
    select first BtwCode, BtwPercentage into @BtwCode, @BtwPerc from tabBtw where BtwCode > @VorigBtwCode and BtwCode in (select OrrBtwCode from tabOrderRegel where OrrOrkGid = @OrkGid ) or BtwCode in (select OerBtwCode from tabOrderExtraRegel where OerOrkGid = @OrkGid ) order by BtwCode;
    if @BtwCode is null then
      leave loopBtw;
    end if;
    set @VorigBtwCode = @BtwCode;

    //De 'gewone' regels
    //let op: @TotaalInclBtwRegels/@TeFactTotaalInclBtwRegels is onbepaald als het een order exclusief BTW is!!
    set @TotaalRegels = 0;
    set @TeFactTotaalRegels = 0;
    set @DezeFactTotaalRegels = 0;
    select sum(OrrRegelTotaal), sum(OrrTeFactRegelTotaal), sum(OrrDezeFactRegelTotaal)
    into   @TotaalRegels, @TeFactTotaalRegels, @DezeFactTotaalRegels
    from   tabOrderRegel
    where  OrrBtwCode = @BtwCode and OrrOrkGid = @OrkGid;

    //De 'extra' regels
    set @TotaalInclBtwExtra = 0;
    set @BtwBasisExtra = 0;
    set @TeFactTotaalInclBtwExtra = 0;
    set @TeFactBtwBasisExtra = 0;
    set @DezeFactTotaalInclBtwExtra = 0;
    set @DezeFactBtwBasisExtra = 0;


    select sum(oerRegelTotaal), sum( OerBtwBasis ), sum(oerTeFactRegelTotaal), sum(OerTeFactBtwBasis), sum(oerDezeFactRegelTotaal), sum(OerDezeFactBtwBasis)
    into   @TotaalInclBtwExtra, @BtwBasisExtra, @TeFactTotaalInclBtwExtra, @TeFactBtwBasisExtra, @DezeFactTotaalInclBtwExtra, @DezeFactBtwBasisExtra
    from   tabOrderExtraRegel
    where OerOrkGid = @OrkGid and OerBtwCode = @BtwCode;

    //De 'extra' regels die niet zelf een btw% hebben
    //RS 21-10-09 niet langer op null zetten ivm bug 31235
    set @BtwBasisExtraZonder              = 0;
    set @TotaalInclBtwExtraZonder         = 0;
    set @TeFactBtwBasisExtraZonder        = 0;
    set @TeFactTotaalInclBtwExtraZonder   = 0;
    set @DezeFactBtwBasisExtraZonder      = 0;
    set @DezeFactTotaalInclBtwExtraZonder = 0;

    iF exists (select 1 from tabOrderExtraRegel where OerBtwCode is null and OerOrkGid = @OrkGid and OerPerc is not null) then
      call BerekenOrdersBepaalExtraRegelsZonderBtw(1, @OrkGid, @OrkInclBtw, @BtwCode, @BtwPerc, @BtwBasisExtraZonder, @TotaalInclBtwExtraZonder);
      call BerekenOrdersBepaalExtraRegelsZonderBtw(2, @OrkGid, @OrkInclBtw, @BtwCode, @BtwPerc, @TeFactBtwBasisExtraZonder, @TeFactTotaalInclBtwExtraZonder);
      call BerekenOrdersBepaalExtraRegelsZonderBtw(3, @OrkGid, @OrkInclBtw, @BtwCode, @BtwPerc, @DezeFactBtwBasisExtraZonder, @DezeFactTotaalInclBtwExtraZonder);
    end if;

    //De BTW-bedragen onthouden in de tijdelijke tabel
    if @BtwBasisRegels is not null or @BtwBasisExtra is not null or @BtwBasisExtraZonder is not null or @TeFactBtwBasisExtraZonder is not null or @TeFactTotaalInclBtwExtraZonder is not null or @DezeFactBtwBasisExtraZonder is not null or @DezeFactTotaalInclBtwExtraZonder is not null then
      if @OrkInclBtw = 0 then
        set @BtwBasisRegels = isnull(@TotaalRegels,0) + isnull(@BtwBasisExtra,0) + isnull(@BtwBasisExtraZonder,0);
        set @TotaalInclBtwRegels = @BtwBasisRegels * (100+@BtwPerc)/100;
        set @TeFactBtwBasisRegels = isnull(@TeFactTotaalRegels,0) + isnull(@BtwBasisExtra,0) + isnull(@TeFactBtwBasisExtraZonder,0);
        set @TeFactTotaalInclBtwRegels = @TeFactBtwBasisRegels * (100+@BtwPerc)/100;
        set @DezeFactBtwBasisRegels = isnull(@DezeFactTotaalRegels,0) + isnull(@BtwBasisExtra,0) + isnull(@DezeFactBtwBasisExtraZonder,0);
        set @DezeFactTotaalInclBtwRegels = @DezeFactBtwBasisRegels * (100+@BtwPerc)/100;
      else
        set @TotaalInclBtwRegels = isnull(@TotaalRegels,0) + isnull(@TotaalInclBtwExtra,0) + isnull(@TotaalInclBtwExtraZonder,0);
        set @BtwBasisRegels = @TotaalInclBtwRegels / (100+@BtwPerc)*100;
        set @TeFactTotaalInclBtwRegels = isnull(@TeFactTotaalRegels,0) + isnull(@TotaalInclBtwExtra,0) + isnull(@TeFactTotaalInclBtwExtraZonder,0);
        set @TeFactBtwBasisRegels = @TeFactTotaalInclBtwRegels / (100+@BtwPerc)*100;
        set @DezeFactTotaalInclBtwRegels = isnull(@DezeFactTotaalRegels,0) + isnull(@TotaalInclBtwExtra,0) + isnull(@DezeFactTotaalInclBtwExtraZonder,0);
        set @DezeFactBtwBasisRegels = @DezeFactTotaalInclBtwRegels / (100+@BtwPerc)*100;
      end if;
      //call Trace('OrderVulBtwTotalen > @BtwBasisRegels = ' + string(@BtwBasisRegels) + ', @TotaalInclBtwRegels = ' + string(@TotaalInclBtwRegels) + ' , @TeFactBtwBasisRegels = ' + string(@TeFactBtwBasisRegels) + ', @TeFactTotaalInclBtwRegels = ' + string(@TeFactTotaalInclBtwRegels) + ', @TeFactBtwBasisRegels = ' + string(@TeFactBtwBasisRegels) + ', @DezeFactTotaalInclBtwRegels = ' + string(@DezeFactTotaalInclBtwRegels) + ', @DezeFactBtwBasisRegels = ' + string(@DezeFactBtwBasisRegels));

      insert into tmpOrkBtw( tmpOrkOrkGid, tmpOrkBtwCode, tmpOrkBtwPerc,
                             tmpOrkBtwBasis,              tmpOrkBedragInclBtw,
                             tmpOrkTeFactBtwBasis,        tmpOrkTeFactBedragInclBtw,
                             tmpOrkDezeFactBtwBasis,      tmpOrkDezeFactBedragInclBtw,
                             tmpOrkKredBepBedrag,         tmpOrkKredBepBedragInBtw,
                             tmpOrkTeFactKredBepBedrag,   tmpOrkTeFactKredBepBedragInBtw,
                             tmpOrkDezeFactKredBepBedrag, tmpOrkDezeFactKredBepBedragInBtw  )
      values( @OrkGid, @BtwCode, @BtwPerc,
              ValutaAfrondBoeken(@valnummer, @BtwBasisRegels),
              ValutaAfrondBoeken(@valnummer, @TotaalInclBtwRegels),
              ValutaAfrondBoeken(@valnummer, @TeFactBtwBasisRegels),
              ValutaAfrondBoeken(@valnummer, @TeFactTotaalInclBtwRegels),
              ValutaAfrondBoeken(@valnummer, @DezeFactBtwBasisRegels),
              ValutaAfrondBoeken(@valnummer, @DezeFactTotaalInclBtwRegels),
              0, 0, 0, 0, 0, 0 );
    end if;
  end loop loopBtw;

  //Alvast regeltotalen optellen (ivm. afrondingen)
  set @TotaalInclBtwRegels = 0;
  set @TeFactTotaalInclBtwRegels = 0;
  set @DezeFactTotaalInclBtwRegels = 0;
  select sum(OrrRegelTotaal), sum(OrrTeFactRegelTotaal), sum(OrrDezeFactRegelTotaal) into @TotaalInclBtwRegels, @TeFactTotaalInclBtwRegels, @DezeFactTotaalInclBtwRegels from tabOrderRegel where OrrOrkGid = @OrkGid;
  set @TotaalInclBtwExtra=0;
  set @TeFactTotaalInclBtwExtra=0;
  set @DezeFactTotaalInclBtwExtra=0;
  select sum(if oerRegelSoort=0 then -1 else 1 endif * oerRegelTotaal), sum(if oerRegelSoort=0 then -1 else 1 endif * oerTeFactRegelTotaal), sum(if oerRegelSoort=0 then -1 else 1 endif * oerDezeFactRegelTotaal)
  into   @TotaalInclBtwExtra, @TeFactTotaalInclBtwExtra, @DezeFactTotaalInclBtwExtra from tabOrderExtraRegel where OerOrkGid = @OrkGid;
  set @TotaalInclBtwRegels         = isnull(@TotaalInclBtwRegels,0) + isnull(@TotaalInclBtwExtra,0);
  set @TeFactTotaalInclBtwRegels   = isnull(@TeFactTotaalInclBtwRegels,0) + isnull(@TeFactTotaalInclBtwExtra,0);
  set @DezeFactTotaalInclBtwRegels = isnull(@DezeFactTotaalInclBtwRegels,0) + isnull(@DezeFactTotaalInclBtwExtra,0);

  //Als er een verschil bestaat tussen (totaal regels minus extra regels) en totaal btw-basis, dan dat verschil op de hoogste btw weg'boeken'
  set @TotaalBasisVolgensBtw=0;
  set @TotaalBasisVolgensBtw = isnull(@TotaalBasisVolgensBtw,0);
  select sum(if @OrkInclBtw = 0 then tmpOrkBtwBasis else tmpOrkBedragInclBtw endif) into @TotaalBasisVolgensBtw from tmpOrkBtw where tmpOrkOrkGid = @OrkGid;
  if @TotaalBasisVolgensBtw<>@TotaalInclBtwRegels then
    //Er is dus een verschil! -> BTW aanpassen
    select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkBedragInclBtw-tmpOrkBtwBasis) desc;
    update tmpOrkBtw
    set    tmpOrkBedragInclBtw = if @OrkInclBtw = 0 then tmpOrkBedragInclBtw else tmpOrkBedragInclBtw + @TotaalInclBtwRegels - @TotaalBasisVolgensBtw endif,
           tmpOrkBtwBasis      = if @OrkInclBtw = 0 then tmpOrkBtwBasis + @TotaalInclBtwRegels - @TotaalBasisVolgensBtw else tmpOrkBtwBasis endif
    where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;

    //BTW herberekenen obv het percentage (na deelcorrectie)
    if @OrkInclBtw = 0 then
      //excl. is goed -> incl. herberekenen
      update tmpOrkBtw
      set    tmpOrkBedragInclBtw=tmpOrkBtwBasis*(100+tmpOrkBtwPerc)/100
      where  tmpOrkOrkGid = @OrkGid;
    else
      //incl. is goed -> excl. herberekenen
      update tmpOrkBtw
      set    tmpOrkBtwBasis=tmpOrkBedragInclBtw/(100+tmpOrkBtwPerc)*100
      where  tmpOrkOrkGid = @OrkGid;
    end if;
  end if;
  //Eventueel ook van de te factureren totalen
  set @TotaalBasisVolgensBtw=0;
  select sum(if @OrkInclBtw = 0 then tmpOrkTeFactBtwBasis else tmpOrkTeFactBedragInclBtw endif) into @TotaalBasisVolgensBtw from tmpOrkBtw where tmpOrkOrkGid = @OrkGid;
  set @TotaalBasisVolgensBtw = isnull(@TotaalBasisVolgensBtw,0);
  if @TotaalBasisVolgensBtw<>@TeFactTotaalInclBtwRegels then
    //Er is dus een verschil! -> BTW aanpassen
    select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkTeFactBedragInclBtw-tmpOrkTeFactBtwBasis) desc;
    update tmpOrkBtw
    set    tmpOrkTeFactBedragInclBtw = if @OrkInclBtw = 0 then tmpOrkTeFactBedragInclBtw else tmpOrkTeFactBedragInclBtw + @TeFactTotaalInclBtwRegels - @TotaalBasisVolgensBtw endif,
           tmpOrkTeFactBtwBasis      = if @OrkInclBtw = 0 then tmpOrkTeFactBtwBasis + @TeFactTotaalInclBtwRegels - @TotaalBasisVolgensBtw else tmpOrkTeFactBtwBasis endif
    where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;

    //BTW herberekenen obv het percentage (na deelcorrectie)
    if @OrkInclBtw = 0 then
      //excl. is goed -> incl. herberekenen
      update tmpOrkBtw
      set    tmpOrkTeFactBedragInclBtw=tmpOrkTeFactBtwBasis*(100+tmpOrkBtwPerc)/100
      where  tmpOrkOrkGid = @OrkGid;
    else
      //incl. is goed -> excl. herberekenen
      update tmpOrkBtw
      set    tmpOrkTeFactBtwBasis=tmpOrkTeFactBedragInclBtw/(100+tmpOrkBtwPerc)*100
      where  tmpOrkOrkGid = @OrkGid;
    end if;
  end if;

  //Eventueel ook van de Deze facturering totalen
  set @TotaalBasisVolgensBtw=0;
  select sum(if @OrkInclBtw = 0 then tmpOrkDezeFactBtwBasis else tmpOrkDezeFactBedragInclBtw endif) into @TotaalBasisVolgensBtw from tmpOrkBtw where tmpOrkOrkGid = @OrkGid;
  set @TotaalBasisVolgensBtw = isnull(@TotaalBasisVolgensBtw,0);
  if @TotaalBasisVolgensBtw<>@DezeFactTotaalInclBtwRegels then
    //Er is dus een verschil! -> BTW aanpassen
    select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkDezeFactBedragInclBtw-tmpOrkDezeFactBtwBasis) desc;
    update tmpOrkBtw
    set    tmpOrkDezeFactBedragInclBtw = if @OrkInclBtw = 0 then tmpOrkDezeFactBedragInclBtw else tmpOrkDezeFactBedragInclBtw + @DezeFactTotaalInclBtwRegels - @TotaalBasisVolgensBtw endif,
           tmpOrkDezeFactBtwBasis      = if @OrkInclBtw = 0 then tmpOrkDezeFactBtwBasis + @DezeFactTotaalInclBtwRegels - @TotaalBasisVolgensBtw else tmpOrkDezeFactBtwBasis endif
    where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;

    //BTW herberekenen obv het percentage (na deelcorrectie)
    if @OrkInclBtw = 0 then
      //excl. is goed -> incl. herberekenen
      update tmpOrkBtw
      set    tmpOrkDezeFactBedragInclBtw=tmpOrkDezeFactBtwBasis*(100+tmpOrkBtwPerc)/100
      where  tmpOrkOrkGid = @OrkGid;
    else
      //incl. is goed -> excl. herberekenen
      update tmpOrkBtw
      set    tmpOrkDezeFactBtwBasis=tmpOrkDezeFactBedragInclBtw/(100+tmpOrkBtwPerc)*100
      where  tmpOrkOrkGid = @OrkGid;
    end if;
  end if;



  //BTW-bedrag berekenen obv. inclusief minus exclusief
  update tmpOrkBtw
  set    tmpOrkBtwBedrag         = tmpOrkBedragInclBtw         - tmpOrkBtwBasis,
         tmpOrkTeFactBtwBedrag   = tmpOrkTeFactBedragInclBtw   - tmpOrkTeFactBtwBasis,
         tmpOrkDezeFactBtwBedrag = tmpOrkDezeFactBedragInclBtw - tmpOrkDezeFactBtwBasis
  where  tmpOrkOrkGid = @OrkGid;

  //Kredietbeperking berekenen
  select SoortFactuurBtc, Percentage into @BtcSoort, @KredBepPerc from tabOrderkop inner join tabBetalingsConditie on (OrkBtcNummer = BtcNummer) where OrkGid = @OrkGid;
  set @KredBepVolgensRegels = 0;
  if @KredBepPerc is not null then
    case @BtcSoort
    when 1 then //KredietBeperking

      if @OrkInclBtw = 0 then
        update tmpOrkBtw
        set    tmpOrkKredBepBedrag      = @KredBepPerc / 100 * tmpOrkBtwBasis,
               tmpOrkKredBepBedragInBtw = @KredBepPerc / 100 * tmpOrkBedragInclBtw,
               tmpOrkBedragInclBtw      = round(tmpOrkBtwBasis * (100+@KredBepPerc) / 100,2) * (100+tmpOrkBtwPerc) / 100,
               tmpOrkBtwBasis           = tmpOrkBtwBasis * (100+@KredBepPerc) / 100,

               tmpOrkTeFactKredBepBedrag      = @KredBepPerc / 100 * tmpOrkTeFactBtwBasis,
               tmpOrkTeFactKredBepBedragInBtw = @KredBepPerc / 100 * tmpOrkTeFactBedragInclBtw,
               tmpOrkTeFactBedragInclBtw      = round(tmpOrkTeFactBtwBasis * (100+@KredBepPerc) / 100,2) * (100+tmpOrkBtwPerc) / 100,
               tmpOrkTeFactBtwBasis           = tmpOrkTeFactBtwBasis * (100+@KredBepPerc) / 100,

               tmpOrkDezeFactKredBepBedrag      = @KredBepPerc / 100 * tmpOrkDezeFactBtwBasis,
               tmpOrkDezeFactKredBepBedragInBtw = @KredBepPerc / 100 * tmpOrkDezeFactBedragInclBtw,
               tmpOrkDezeFactBedragInclBtw      = round(tmpOrkDezeFactBtwBasis * (100+@KredBepPerc) / 100,2) * (100+tmpOrkBtwPerc) / 100,
               tmpOrkDezeFactBtwBasis           = tmpOrkDezeFactBtwBasis * (100+@KredBepPerc) / 100

        where  tmpOrkOrkGid = @OrkGid;
      else
        update tmpOrkBtw
        set    tmpOrkKredBepBedrag      = @KredBepPerc / 100 * tmpOrkBtwBasis,
               tmpOrkKredBepBedragInBtw = @KredBepPerc / 100 * tmpOrkBedragInclBtw,
               tmpOrkBedragInclBtw      =  (100+@KredBepPerc) / 100 * tmpOrkBedragInclBtw,
               tmpOrkBtwBasis           = round(((100+@KredBepPerc) / 100 * tmpOrkBedragInclBtw),2)/(100+tmpOrkBtwPerc)*100,

               tmpOrkTeFactKredBepBedrag      = @KredBepPerc / 100 * tmpOrkTeFactBtwBasis,
               tmpOrkTeFactKredBepBedragInBtw = @KredBepPerc / 100 * tmpOrkTeFactBedragInclBtw,
               tmpOrkTeFactBedragInclBtw      =  (100+@KredBepPerc) / 100 * tmpOrkTeFactBedragInclBtw,
               tmpOrkTeFactBtwBasis           = round(((100+@KredBepPerc) / 100 * tmpOrkTeFactBedragInclBtw),2)/(100+tmpOrkBtwPerc)*100,

               tmpOrkDezeFactKredBepBedrag      = @KredBepPerc / 100 * tmpOrkDezeFactBtwBasis,
               tmpOrkDezeFactKredBepBedragInBtw = @KredBepPerc / 100 * tmpOrkDezeFactBedragInclBtw,
               tmpOrkDezeFactBedragInclBtw      =  (100+@KredBepPerc) / 100 * tmpOrkDezeFactBedragInclBtw,
               tmpOrkDezeFactBtwBasis           = round(((100+@KredBepPerc) / 100 * tmpOrkDezeFactBedragInclBtw),2)/(100+tmpOrkBtwPerc)*100
        where  tmpOrkOrkGid = @OrkGid;
      end if;

      update tmpOrkBtw
      set    tmpOrkBtwBedrag         = tmpOrkBedragInclBtw         - tmpOrkBtwBasis,
             tmpOrkTeFactBtwBedrag   = tmpOrkTeFactBedragInclBtw   - tmpOrkTeFactBtwBasis,
             tmpOrkDezeFactBtwBedrag = tmpOrkDezeFactBedragInclBtw - tmpOrkDezeFactBtwBasis
      where  tmpOrkOrkGid = @OrkGid;

      //BTW herberekenen
      if @OrkInclBtw = 0 then
        //excl. is goed -> incl. herberekenen
        update tmpOrkBtw
        set    tmpOrkBedragInclBtw         = tmpOrkBtwBasis         + tmpOrkBtwBedrag,
               tmpOrkTeFactBedragInclBtw   = tmpOrkTeFactBtwBasis   + tmpOrkTeFactBtwBedrag,
               tmpOrkDezeFactBedragInclBtw = tmpOrkDezeFactBtwBasis + tmpOrkDezeFactBtwBedrag
        where  tmpOrkOrkGid = @OrkGid;
      else
        //incl. is goed -> excl. herberekenen
        update tmpOrkBtw
        set    tmpOrkBtwBasis         = tmpOrkBedragInclBtw         - tmpOrkBtwBedrag,
               tmpOrkTeFactBtwBasis   = tmpOrkTeFactBedragInclBtw   - tmpOrkTeFactBtwBedrag,
               tmpOrkDezeFactBtwBasis = tmpOrkDezeFactBedragInclBtw - tmpOrkDezeFactBtwBedrag
        where  tmpOrkOrkGid = @OrkGid;
      end if;


      // --- Afronding in kredietbeperking wegwerken (<kred.%>*<fact.bedrag excl.kred.bep.>-<kred.bep.per btw>) ---

      //Eerst obv. aantal besteld
      select sum(if @OrkInclBtw = 0 then tmpOrkKredBepBedrag else tmpOrkKredBepBedragInBtw endif)
      into   @KredBepVolgensBTW
      from   tmpOrkBtw
      where  tmpOrkOrkGid = @OrkGid;
      set @KredBepVolgensRegels = @KredBepPerc * @TotaalInclBtwRegels/100;
      if isnull(@KredBepVolgensBTW,0) <> @KredBepVolgensRegels then
        //Verschil op hoogste absolute BTW-regel plaatsen
        select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkBedragInclBtw-tmpOrkBtwBasis) desc;
        set @KredBepVolgensBTW = @KredBepVolgensRegels - isnull(@KredBepVolgensBTW,0);
        update tmpOrkBtw
        set    tmpOrkKredBepBedrag      = tmpOrkKredBepBedrag      + @KredBepVolgensBTW,
               tmpOrkKredBepBedragInBtw = tmpOrkKredBepBedragInBtw + @KredBepVolgensBTW,
               tmpOrkBtwBasis           = tmpOrkBtwBasis           + @KredBepVolgensBTW,
               tmpOrkBedragInclBtw      = tmpOrkBedragInclBtw      + @KredBepVolgensBTW
        where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;
      end if;

      //En dan obv. aantal te factureren
      set @KredBepVolgensBTW = 0;
      select sum(if @OrkInclBtw = 0 then tmpOrkTeFactKredBepBedrag else tmpOrkTeFactKredBepBedragInBtw endif)
      into   @KredBepVolgensBTW
      from   tmpOrkBtw
      where  tmpOrkOrkGid = @OrkGid;
      set @KredBepVolgensRegels = @KredBepPerc * @TeFactTotaalInclBtwRegels/100;
      if isnull(@KredBepVolgensBTW,0) <> @KredBepVolgensRegels then
        //Verschil op hoogste absolute BTW-regel plaatsen
        select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkTeFactBedragInclBtw-tmpOrkTeFactBtwBasis) desc;
        set @KredBepVolgensBTW = @KredBepVolgensRegels - isnull(@KredBepVolgensBTW,0);
        update tmpOrkBtw
        set    tmpOrkTeFactKredBepBedrag      = tmpOrkTeFactKredBepBedrag      + @KredBepVolgensBTW,
               tmpOrkTeFactKredBepBedragInBtw = tmpOrkTeFactKredBepBedragInBtw + @KredBepVolgensBTW,
               tmpOrkTeFactBtwBasis           = tmpOrkTeFactBtwBasis           + @KredBepVolgensBTW,
               tmpOrkTeFactBedragInclBtw      = tmpOrkTeFactBedragInclBtw      + @KredBepVolgensBTW
        where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;
      end if;

      //En dan obv. aantal deze facturering
      set @KredBepVolgensBTW = 0;
      select sum(if @OrkInclBtw = 0 then tmpOrkDezeFactKredBepBedrag else tmpOrkDezeFactKredBepBedragInBtw endif)
      into   @KredBepVolgensBTW
      from   tmpOrkBtw
      where  tmpOrkOrkGid = @OrkGid;
      set @KredBepVolgensRegels = @KredBepPerc * @DezeFactTotaalInclBtwRegels/100;
      if isnull(@KredBepVolgensBTW,0) <> @KredBepVolgensRegels then
        //Verschil op hoogste absolute BTW-regel plaatsen
        select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkDezeFactBedragInclBtw-tmpOrkDezeFactBtwBasis) desc;
        set @KredBepVolgensBTW = @KredBepVolgensRegels - isnull(@KredBepVolgensBTW,0);
        update tmpOrkBtw
        set    tmpOrkDezeFactKredBepBedrag      = tmpOrkDezeFactKredBepBedrag      + @KredBepVolgensBTW,
               tmpOrkDezeFactKredBepBedragInBtw = tmpOrkDezeFactKredBepBedragInBtw + @KredBepVolgensBTW,
               tmpOrkDezeFactBtwBasis           = tmpOrkDezeFactBtwBasis           + @KredBepVolgensBTW,
               tmpOrkDezeFactBedragInclBtw      = tmpOrkDezeFactBedragInclBtw      + @KredBepVolgensBTW
        where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;
      end if;

    when 2 then //Bet.korting
        update tmpOrkBtw
        set    tmpOrkKredBepBedrag              = @KredBepPerc / 100 * tmpOrkBtwBasis,
               tmpOrkKredBepBedragInBtw         = @KredBepPerc / 100 * ( tmpOrkBtwBedrag + tmpOrkBtwBasis ),
               tmpOrkTeFactKredBepBedrag        = @KredBepPerc / 100 * tmpOrkTeFactBtwBasis,
               tmpOrkTeFactKredBepBedragInBtw   = @KredBepPerc / 100 * ( tmpOrkTeFactBtwBedrag + tmpOrkTeFactBtwBasis ),
               tmpOrkDezeFactKredBepBedrag      = @KredBepPerc / 100 * tmpOrkDezeFactBtwBasis,
               tmpOrkDezeFactKredBepBedragInBtw = @KredBepPerc / 100 * ( tmpOrkDezeFactBtwBedrag + tmpOrkDezeFactBtwBasis )
        where  tmpOrkOrkGid = @OrkGid;
    end case;
  end if;


  //Factuurtotaal berekenen obv. totaaltelling van de regels
  if @OrkInclBtw = 1 then

    if @KredBepPerc is not null and @BtcSoort = 1 then
      //Regeltotalen incl. kredietBeperking volgens regels
      set @TotaalInclBtwRegels         = @TotaalInclBtwRegels *(100+@KredBepPerc)/100;
      set @TeFactTotaalInclBtwRegels   = @TeFactTotaalInclBtwRegels *(100+@KredBepPerc)/100;
      set @DezeFactTotaalInclBtwRegels = @DezeFactTotaalInclBtwRegels *(100+@KredBepPerc)/100;
    end if;

    // --- Als er een verschil is tussen berekend factuurtotaal en volgens btw, dan het verschil bij de hoogste absolute BTW wegwerken ---
    select sum( tmpOrkBedragInclBtw ), sum( tmpOrkTeFactBedragInclBtw ), sum( tmpOrkDezeFactBedragInclBtw ) into @TotaalInclBtwExtra, @TeFactTotaalInclBtwExtra, @DezeFactTotaalInclBtwExtra from tmpOrkBtw where tmpOrkOrkGid = @OrkGid;
    //Eerst obv. aantal besteld
    if @TotaalInclBtwRegels <> @TotaalInclBtwExtra then
      select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkBedragInclBtw) desc;
      update tmpOrkBtw
      set    tmpOrkBedragInclBtw = tmpOrkBedragInclBtw + @TotaalInclBtwRegels - @TotaalInclBtwExtra,
             tmpOrkBtwBedrag     = tmpOrkBtwBedrag     + @TotaalInclBtwRegels - @TotaalInclBtwExtra
      where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;
    end if;
    //Dan obv. aantal te factureren
    if @TeFactTotaalInclBtwRegels <> @TeFactTotaalInclBtwExtra then
      select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkTeFactBedragInclBtw) desc;
      update tmpOrkBtw
      set    tmpTeFactOrkBedragInclBtw = tmpOrkTeFactBedragInclBtw + @TeFactTotaalInclBtwRegels - @TeFactTotaalInclBtwExtra,
             tmpTeFactOrkBtwBedrag     = tmpOrkTeFactBtwBedrag     + @TeFactTotaalInclBtwRegels - @TeFactTotaalInclBtwExtra
      where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;
    end if;
    //Dan obv. aantal deze facturering
    if @DezeFactTotaalInclBtwRegels <> @DezeFactTotaalInclBtwExtra then
      select first tmpOrkBtwCode into @BtwCode from tmpOrkBtw where tmpOrkOrkGid = @OrkGid order by abs(tmpOrkDezeFactBedragInclBtw) desc;
      update tmpOrkBtw
      set    tmpDezeFactOrkBedragInclBtw = tmpOrkDezeFactBedragInclBtw + @DezeFactTotaalInclBtwRegels - @DezeFactTotaalInclBtwExtra,
             tmpDezeFactOrkBtwBedrag     = tmpOrkDezeFactBtwBedrag     + @DezeFactTotaalInclBtwRegels - @DezeFactTotaalInclBtwExtra
      where  tmpOrkBtwCode = @BtwCode and tmpOrkOrkGid = @OrkGid;
    end if;

  end if;


  //En direct de orderkop updaten
  set @TotaalInclBtwRegels = 0;
  set @BtwBasisRegels = 0;
  set @TeFactTotaalInclBtwRegels = 0;
  set @TeFactBtwBasisRegels = 0;
  set @DezeFactTotaalInclBtwRegels = 0;
  set @DezeFactBtwBasisRegels = 0;

  select sum( tmpOrkBedragInclBtw ),
         sum( tmpOrkBtwBasis ),
         sum( tmpOrkTeFactBedragInclBtw ),
         sum( tmpOrkTeFactBtwBasis ),
         sum( tmpOrkDezeFactBedragInclBtw ),
         sum( tmpOrkDezeFactBtwBasis )
  into   @TotaalInclBtwRegels,
         @BtwBasisRegels,
         @TeFactTotaalInclBtwRegels,
         @TeFactBtwBasisRegels,
         @DezeFactTotaalInclBtwRegels,
         @DezeFactBtwBasisRegels
  from tmpOrkBtw
  where tmpOrkOrkGid = @OrkGid;

  Update tabOrderKop
  set    OrkTotaalInclBtw =         isnull( @TotaalInclBtwRegels, 0),
         OrkTotaalExclBtw =         isnull( @BtwBasisRegels, 0 ),
         OrkTeFactTotaalInclBtw =   isnull( @TeFactTotaalInclBtwRegels, 0),
         OrkTeFactTotaalExclBtw =   isnull( @TeFactBtwBasisRegels, 0 ),
         OrkDezeFactTotaalInclBtw = isnull( @DezeFactTotaalInclBtwRegels, 0),
         OrkDezeFactTotaalExclBtw = isnull( @DezeFactBtwBasisRegels, 0 )
  where  OrkGid = @OrkGid and
       ((OrkTotaalInclBtw <>        isnull( @TotaalInclBtwRegels, 0)) or
        (OrkTotaalExclBtw <>        isnull( @BtwBasisRegels, 0 )) or
        (OrkTeFactTotaalInclBtw <>  isnull( @TeFactTotaalInclBtwRegels, 0)) or
        (OrkTeFactTotaalExclBtw <>  isnull( @TeFactBtwBasisRegels, 0 )) or
        (OrkDezeFactTotaalInclBtw <>isnull( @DezeFactTotaalInclBtwRegels, 0)) or
        (OrkDezeFactTotaalExclBtw <>isnull( @DezeFactBtwBasisRegels, 0 )));

  set @@ErrorTextProcedure = 'OrderVulBtwTotalen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace function OspFiatterenToestaanControle(
  in @OspGid            integer,
  in @IsHandmatigeActie smallint default 1,         // 0 = automatisch (bijv. import), 1 = Handmatige actie
  in @OpenstaandBedrag  numeric(15,2) default null, // Als niet opgegeven, dan uit tabel lezen
  in @IsCrediteur       smallint default null,      // 0=deb., 1=cred.   Als niet opgegeven, dan uit tabel lezen
  in @Fiat              smallint default null       // 0 = Fiattering UITzetten, 1 = fiattering AAN zetten
)
returns smallint //0 = toegestaan om te fiatteren,
                 //1 = Warning: niet toegestaan want geen bankrekening gevonden
                 //102 = Fail: niet toegestaan, geen rechten om OSP te fiatteren
begin
  declare @result smallint = 0; // 0 = Is toegestaan
  declare @OspSoortFactuur smallint;

  // Gegevens uit OSP-record lezen, zijn niet meegegven maar wel belangrijk
  if (@OpenstaandBedrag is null) or (@IsCrediteur is null) then
    begin
      declare @OspOpenstaandBedrag numeric(15,2);
      declare @OspIsCrediteur      smallint;
      select OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig - OspBetaaldBedragDefinitief - OspBetaaldBedragVoorlopig,
             OspIsCrediteur, OspSoortFactuur
      into   @OspOpenstaandBedrag, @OspIsCrediteur, @OspSoortFactuur
      from   tabOpenstaandePost
      where  OspGid = @OspGid;
      if @OpenstaandBedrag is null then
        set @OpenstaandBedrag = @OspOpenstaandBedrag;
      end if;
      if @IsCrediteur is null then
        set @IsCrediteur = @OspIsCrediteur;
      end if;
    end;
  end if;

  // Controle op rechten: voor debiteur: module qcRecht_dopf_Fiatteren_verkoopfacturen
  //                      voor crediteur: module qcRecht_copf_Fiatteren_inkoopfacturen
  // Alleen indien van niet- naar wel gefiatteerd
  if @result = 0 then
    begin
      declare @HeeftRecht smallint = 0;
      if @Fiat is null then
        set @Fiat = (select first 1-OspGefiatteerd from tabOpenstaandePost where  OspGid = @OspGid);
      end if;

      if @Fiat = 1 then
        // Fiat AAN zetten
        if    @IsCrediteur = 0 then
          set @HeeftRecht = IsModuleActive('dopf');
        else
          set @HeeftRecht = IsModuleActive('copf');
        end if;
      else
        // Fiat UIT zetten
        if    @IsCrediteur = 0 then
          set @HeeftRecht = IsModuleActive('dopg');
        else
          set @HeeftRecht = IsModuleActive('copg');
        end if;
      end if;
      if @HeeftRecht = 0 then
        // Geen recht, dan vergelijken of vinkje van UIT naar AAN wordt gezet, oftewel, NU uit
        set @Result = 102; // Blokkade op rechten
      end if;
    end;
  end if;

  // Controle op bankrekening: Alleen als er betaald moet worden aan de NAW
  //if (@result = 0) and (((2*@IsCrediteur) - 1) * @OpenstaandBedrag > 0) then
    begin
      // Er moet worden betaald, kijken of er een bankrekening is...
      declare @vgControleerBankrekening smallint = 1; // altijd controleren
      declare @BankrekSoort nchar(1) = '';


      //select contents into @vgControleerBankrekening from tabRegistry where regkey= FIATTERING_CONTROLEEROPBANKREKENING;
      //Ook nog iets met @IsHandmatigeActie doen...
      if @vgControleerBankrekening > 0 then
        // Afhankelijk van NAW-soort, OSPbedrag en OSPsoort zoeken naar een bepaald soort rekening
        if @OspSoortFactuur is null then
          select OspSoortFactuur into @OspSoortFactuur from tabopenstaandepost where OspGid = @OspGid;
        end if;

        case
          when @IsCrediteur = 0 /*debiteur*/ and @OpenstaandBedrag > 0 and @OspSoortFactuur = 3 /*incasso*/ then
            // Debiteur, positief, dus incasso
            set @BankrekSoort = 'I'
          when @IsCrediteur = 0 /*debiteur*/ and @OpenstaandBedrag < 0 then
            // Creditnota, dut default bankrek.
            set @BankrekSoort = 'D'
          when @IsCrediteur = 1 /*crediteur*/ and @OpenstaandBedrag > 0 then
            // Crediteur, positief, dus betaling
            set @BankrekSoort = 'B'
          when @IsCrediteur = 1 /*crediteur*/ and @OpenstaandBedrag < 0 then
            // Creditnota van crediteur, krijgen we dus terug
            set @BankrekSoort = '';
        end case;

        if @BankrekSoort <> '' then
          if not exists(
            select first 1
            from   tabOpenstaandePost
                   inner join tabNawFile on NawFilRksGID = OspRksGID
                   inner join tabNawRekening on NawRekNawGid = NawFilNawGid
            where  OspGid = @OspGid and (NawRekSoort like '%' || @BankrekSoort || '%')
          ) then
              set @result = 1; // Geen bankrekening gevonden
          end if;
        end if;
      end if;
    end;
  //end if;


  return @result;
end;


create or replace procedure OspHistDeb(
in @BjGid             integer,    //Boekjaar van de OSPs
in @FonID             nchar(2),    //Standaard 'D' voor deb., 'C' voor crediteuren
in @StandPer          date,       //Indien leeg, dan alleen de beginbalans!
in @SoortBoeking      smallint,   //0=definitief, 1=voorlopig, 2=beide
in @SelecteerOp       smallint,   //1 = debnummer, 2=debzoekcode
in @VanDebCred        nchar(10),
in @TotDebCred        nchar(10),
in @SorteerOp         smallint,   //0= debnummer, 1=debzoekcode
in @Ascending         smallint,
in @VanOsp            nchar(40),
in @TotOsp            nchar(40),
in @VanVervalDatum    date,
in @TotVervalDatum    date
)
result(
  rksInvoer          nchar(28), RksGid              integer,  nawfilKredLimiet     numeric(15,2),
  adrNaam1           nchar(40), adrNaam2            nchar(40), adrStraat            nchar(40), adrHuisNummer         nchar(10), adrPostcode nchar(40), adrPlaats    nchar(40),
  adrTelefoon        nchar(25), adrTelefoon2        nchar(25), adrTelefax           nchar(25), adrEmail              nchar(80),
  lndGid             integer,  lndEigenCode        nchar(3),  lndIso2              nchar(2),  lndIso3               nchar(3),  lndOms      nchar(40),
  lndPlaatsHuisNr    smallint, lndPlaatsPostcode   smallint, lndInNAWblok         smallint,
  RelVolledigeNaam   nchar(40), relNaamInAdres      nchar(60), relNaamInAanhef      nchar(60), relNaamInBrief        nchar(60), ValNummer   integer,  ValCode      nchar(40),
  nawrekBankRekening nchar(34), nawrekNaamRekHouder nchar(40), nawrekAdresRekHouder nchar(40), nawrekPlaatsRekHouder nchar(40),
  nawBtwNummer       nchar(15), nawFilZoekCode      nchar(10), relEmail             nchar(80), relTelefax            nchar(25), relTelefoon nchar(25), relTelefoon2 nchar(25),
  relGeslacht        smallint, nawgid integer)
begin

  //call TraceBegin('OspHistDeb(@BjGid='+string(@BjGid)+', @FonID='+@FonID+', @StandPer='+string(@StandPer)+', @SoortBoeking='+string(@SoortBoeking)+', @SelecteerOp='+string(@SelecteerOp)+', @VanDebCred='+@VanDebCred+', @TotDebCred='+@TotDebCred+', ...');
  //call Trace('..., @VanOsp='+@VanOsp+', @TotOsp='+@TotOsp+', @SorteerOp='+string(@sorteerop)+', @Ascending='+string(@ascending)+', @VanVervalDatum='+string(@VanVervalDatum)+', @TotVervalDatum='+string(@TotVervalDatum)+')');

  //call TraceEind('OspHistDeb');

  select distinct rksInvoer, RksGid, nawfilKredLimiet, adrNaam1, adrNaam2, adrStraat, adrHuisNummer, adrPostcode, adrPlaats,
                  adrTelefoon, adrTelefoon2, adrTelefax, adrEmail, lndGid, lndEigenCode, lndIso2, lndIso3, lndOms, lndPlaatsHuisNr, lndPlaatsPostcode, lndInNAWblok,
                  RelVolledigeNaam, relNaamInAdres,
                  relNaamInAanhef, relNaamInBrief,
                  RksValNummer ValNummer,
                  (select ValCode from tabValuta a where a.ValNummer = RksValNummer) ValCode, nawrekBankRekening, nawrekNaamRekHouder, nawrekAdresRekHouder,
                  nawrekPlaatsRekHouder,
                  nawBtwNummer, nawFilZoekCode, relEmail, relTelefax, relTelefoon, relTelefoon2, relGeslacht, nawgid

  from     tabJournaalRegel
           inner join tabJournaalPost     on (JpGid = JrJpGid)
           inner join tabDagboek          on (JpDgbGid = DgbGid)
           inner join tabBoekingsgang     on (BoekgangGid = JpBoekgangGid)
           inner join tabRekeningSchema   on (RksGid = JrRksGid)
           inner join tabNawFile          on (NawFilRksGid = RksGid and NawFilFonId = @FonID)
           inner join tabNaw              on (NawGid = NawFilNawGid)
           inner join tabAdres            on (NawGidVestiging = AdrGid)
           inner join tabLand             on (LndGid = AdrLndGid)
           left outer join (tabRelatie
                            inner join tabScherm on (SchermSoort = 10)
                            inner join tabRelatieFunctie on (IsBelangrijkste = 1 and RelFnCode = SchermFnCode and FnRelGid = RelGid)
                           ) on (RelNawGid = NawGid)
           left outer join tabNawRekening on (NawRekNawGid = NawGid and nawRekSoort like '%D%')
  where    1 = (if (@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                   (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                   (@SoortBoeking = 2) then 1 else 0 endif)
           and JpBjGid = @BjGid                                                            //Alleen dit jaar
           and ((@StandPer is not null and JrBoekDatum <= @StandPer) or                      //Alleen TOT de @StandPer zoals opgegeven (als geen @standper opgegeven, dan dus alleen beginbalans)
                DagboekSoort = 5)                                                          //De beginbalans
           and
            //Alleen de OSPs tussen de factuurnummers
            // note DG: Factuurnummer wijziging; zoals afgesproken uitvullen met spaties en dan between selectie
            (Repeat(' ',40-jrReferentie_Lengte) + jrReferentie between Repeat(' ',40-length(@VanOsp)) + @VanOsp and Repeat(' ',40-length(@TotOsp)) + @TotOsp)

           and ((@SelecteerOp = 1 and rksInvoer between @VanDebCred and @TotDebCred) or    //Alleen de juiste debiteuren of crediteuren
                (@SelecteerOp = 2 and rksZoekCode between @VanDebCred and @TotDebCred))
           and (JrVervalDatum between @VanVervalDatum and @TotVervalDatum)                 //Alleen de OSPs tussen de vervaldata
  group by JrOspGid,                                                                       //Om 1 regel per OSP te krijgen met de totaalde en betaalde factuurbedragen
           rksInvoer, RksGid,nawfilKredLimiet, adrNaam1, adrNaam2, adrStraat, //En de select-lijst gewoon overnemen! (vergeet de order-by niet)
           adrHuisNummer, adrPostcode, adrPlaats, adrTelefoon, adrTelefoon2, adrTelefax,
           adrEmail, lndGid, lndEigenCode, lndIso2, lndIso3, lndOms,
           lndPlaatsHuisNr, lndPlaatsPostcode, lndInNAWblok,
           RelVolledigeNaam, relNaamInAdres, relNaamInAanhef, relNaamInBrief,
           ValNummer, ValCode, nawrekBankRekening, nawrekNaamRekHouder,
           nawrekAdresRekHouder, nawrekPlaatsRekHouder,
           nawBtwNummer, nawFilZoekCode, relEmail, relTelefax, relTelefoon, relTelefoon2, relGeslacht, nawgid
  having   isnull(sum(if IsCreditBoeking = 0 then JrValutaBedrag else 0 endif),0) <>
           isnull(sum(if IsCreditBoeking = 1 then JrValutaBedrag else 0 endif),0)         //Alleen de niet-vervallen OSPs
  order by if @Ascending = 0 then if @SorteerOp = 1 then nawFilZoekCode endif endif desc,
           if @Ascending = 1 then if @SorteerOp = 1 then nawFilZoekCode endif endif,
           if @Ascending = 0 then RksInvoer endif desc,
           if @Ascending = 1 then RksInvoer endif;

end;

//call OspHistDeb(2, 'D', '2000-12-31', 2, 1, '', '99999999', 0, 1, '', '9999999999', '2000-01-01', '2001-12-31');


create or replace procedure OspHistOsp(
in @BjGid             integer,    //Boekjaar van de OSPs
in @StandPer          date,       //Indien leeg, dan alleen de beginbalans!
in @SoortBoeking      smallint,   //0=definitief, 1=voorlopig, 2=beide
in @RksGid            integer,
in @VanOsp            nchar(40),
in @TotOsp            nchar(40),
in @VanVervalDatum    date,
in @TotVervalDatum    date,
in @OspBedragInValuta smallint,   //Totalen van de OSPs per debiteur: 0=in debiteur-valuta, 1=in val. van deb.+andere valuta
in @OspInDezeValuta   integer,    //Als @OspBedragnInValuta=1, dan hierin de andere valuta
in @SorteerOp         smallint,
in @Ascending         smallint,
in @PeilDatum         date,       // PeilDatum tbv ouderdomsanalyse - wens# 50263
in @Dagen1            smallint,   // tbv ouderdomsanalyse - wens# 50263
in @Dagen2            smallint,   // tbv ouderdomsanalyse - wens# 50263
in @Dagen3            smallint,   // tbv ouderdomsanalyse - wens# 50263
in @OuderdomObv       smallint    // tbv ouderdomsanalyse - wens# 50263, 0=vervaldatum, 1=factuurdatum
)

result(OspGid                      integer,       FactuurNummer               nchar(40),      FactuurDatum                   date,          VervalDatum                 date,
       BetalingsKenmerk            nchar(16),      Oms                         nchar(40),      ViaIncasso                     smallint,
       FactuurBedrag               numeric(15,2), BetaaldBedrag               numeric(15,2), OpenstaandBedrag               numeric(15,2),
       FactuurBedragInTotaalValuta numeric(15,2), BetaaldBedragInTotaalValuta numeric(15,2), OpenstaandBedragInTotaalValuta numeric(15,2),
       FactuurBedragInValutaVanDeb numeric(15,2), BetaaldBedragInValutaVanDeb numeric(15,2), OpenstaandBedragInValutaVanDeb numeric(15,2),
       ValNummer                   integer,       ValCode                     nchar(3),       LaatsteBetalingDatum           date,
       LaatsteBetalingBedrag       numeric(15,2), LaatsteBetalingDagboek      nchar(8),       LaatsteBetalingStukNr          nchar(14),
       OspGefiatteerd              smallint,      OspFiatteringGewijzigdDoor  nchar(40),      OspFiatteringGewijzigdOp       timestamp,
       Kolom1 numeric(15,2), Kolom2 numeric(15,2), Kolom3 numeric(15,2), Kolom4 numeric(15,2))

begin
  declare local temporary table HistOsp(
    OspGid integer,
    FactuurNummer nchar(40),
    AnalyseDatum date,
    FactuurDatum date,
    VervalDatum date,
    BetalingsKenmerk nchar(16),
    Oms nchar(40),
//    SoortFactuur smallint,                 //Is niet te achterhalen uit het journaal
    ViaIncasso smallint,
//    KredietBeperkingsBedrag numeric(15,2), //Is niet te achterhalen uit het journaal
//    KredietBeperkingsDatum date,           //Is niet te achterhalen uit het journaal
//    ValNummerBedragOnderweg integer,       //Is niet te achterhalen uit het journaal
//    BedragOnderwegInValuta numeric(15,2),  //Is niet te achterhalen uit het journaal
//    KredietbeperkingsRksGid integer,       //Is niet te achterhalen uit het journaal
    FactuurBedrag numeric(15,2),  //Altijd in de valuta van de OSP
    BetaaldBedrag numeric(15,2),  //Altijd in de valuta van de OSP
    FactuurBedragInTotaalValuta numeric(15,2),  // In de andere valuta
    BetaaldBedragInTotaalValuta numeric(15,2),
    FactuurBedragInValutaVanDeb numeric(15,2),  // In de valuta van debiteur
    BetaaldBedragInValutaVanDeb numeric(15,2),
    ValNummer integer,
    LaatsteBetalingDatum date,
    LaatsteBetalingBedrag numeric(15,2),
    LaatsteBetalingDagboek nchar(8),
    LaatsteBetalingStukNr  nchar(14),
//    BtwBedragVoorlopig numeric(15,2),           // Is niet te achterhalen uit het journaal
//    BtwBedragDefinitief numeric(15,2),          // Is niet te achterhalen uit het journaal
    OspGefiatteerd smallint,
    OspFiatteringGewijzigdDoor nchar(40),
    OspFiatteringGewijzigdOp timestamp,
    Kolom1 numeric(15,2),
    Kolom2 numeric(15,2),
    Kolom3 numeric(15,2),
    Kolom4 numeric(15,2)
    ) on commit preserve rows;

  //tbv. bepalen van de periode voor de koersberekeningen
  declare @BjGidStand       integer;
  declare @PerNr            integer;
  declare @IsFactuurBoeking smallint;

  //call TraceBegin('OspHistOsp(@BjGid='+string(@BjGid)+', @StandPer='+string(@StandPer)+', @SoortBoeking='+string(@SoortBoeking)+', @RksGid='+string(@RksGid)+', @VanOsp='+@VanOsp+', @TotOsp='+@TotOsp+', @VanVervalDatum='+string(@VanVervalDatum)+', @TotVervalDatum='+string(@TotVervalDatum)+', @OspBedragInValuta='+string(@OspBedragInValuta)+', @OspInDezeValuta='+string(@OspInDezeValuta)+')');

  set @VanOsp = Repeat(' ',40-length(@VanOsp))+Trim(@VanOsp);
  set @TotOsp = Repeat(' ',40-length(@TotOsp))+Trim(@TotOsp);

  set @dagen2 = @dagen1 + @dagen2;
  set @dagen3 = @dagen2 + @dagen3;

  //Bepaal de periode voor de koersberekening
  if @StandPer is null then
    //Koers van beginbalans gebruiken
    set @PerNr = 0;
  else
    //Geen beginbalans, dus bepaal periode obv. @StandPer
    //MR Bug# 25761 : waarom een dag eraf? call BepaalBoekjaarEnPeriode(DateAdd(day, -1, @StandPer), @BjGidStand, @PerNr);
    call BepaalBoekjaarEnPeriode(@StandPer, @BjGidStand, @PerNr);
    if @BjGidStand <> @BjGid then
      //De periode valt niet in dit boekjaar, dus blijkbaar was het de eerste dag van dit boekjaar, dus dan geldt de eerste periode als koersbepaling
      //Let op: als we een onzin-@StandPer meegeven tov. de @BjGid dan geven we toch periode 1 als koersperiode! (Anders zouden we een RaisError moeten geven)
      set @PerNr = 1;
    end if;
  end if;

  //Bepaal welke kant (obv. IsCreditBoeking) de factuur-opboeking is
  if exists(select 1 from tabRekeningSchema where RksGid = @RksGid and DefaultSoort = 6) then
    set @IsFactuurBoeking = 0
  else
    set @IsFactuurBoeking = 1
  end if;

  //Lijst van uit te zoeken OSPs aanmaken (gelijk de factuur- en betaalde bedragen onthouden)
  //MR 30-mei-2007 Bug# 25761: JrValutaBedrag eerst naar de basisvaluta in de periode omzetten en dan naar een andere koers
  insert into HistOsp(OspGid, AnalyseDatum, FactuurBedrag, BetaaldBedrag, FactuurBedragInValutaVanDeb, BetaaldBedragInValutaVanDeb, FactuurBedragInTotaalValuta, BetaaldBedragInTotaalValuta, ValNummer, OspGefiatteerd, OspFiatteringGewijzigdDoor, OspFiatteringGewijzigdOp)
  select   JrOspGid,
           (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) AnalyseDatum,
           //Factuurbedrag in valuta van de OSP
           sum(if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else 0 endif) FactuurBedrag,
           //Betaald bedrag in valuta van de OSP
           sum(if IsCreditBoeking <> @IsFactuurBoeking then JrValutaBedrag else 0 endif) BetaaldBedrag,
           //Factuurbedrag in valuta van de debiteur
           sum(if JrValNummer = RksValNummer then
                 if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else 0 endif
               else
                 if IsCreditBoeking = @IsFactuurBoeking then ValutaOmrekenen(JrValNummer, JrValutaBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2)  else 0 endif / KoersTovBasisValuta(@BjGid, @Pernr, RksValNummer)
               endif) FactuurBedragInValutaVanDeb,
           //betaald bedrag in valuta van de debiteur
           sum(if JrValNummer = RksValNummer then
                 if IsCreditBoeking <> @IsFactuurBoeking then JrValutaBedrag else 0 endif
               else
                 if IsCreditBoeking <> @IsFactuurBoeking then ValutaOmrekenen(JrValNummer, JrValutaBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2)  else 0 endif / KoersTovBasisValuta(@BjGid, @Pernr, RksValNummer)
               endif) BetaaldBedragInValutaVanDeb,
           //Factuurbedrag in opgegeven valuta
           if @OspBedragInValuta = 1 then
             isnull(sum(
                 if JrValNummer = @OspInDezeValuta then
                   if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else 0 endif
                 else
                   if IsCreditBoeking = @IsFactuurBoeking then ValutaOmrekenen(JrValNummer, JrValutaBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2)  else 0 endif / KoersTovBasisValuta(@BjGid, @Pernr, @OspInDezeValuta)
                  endif),0)
           else
             FactuurBedragInValutaVanDeb //Debiteur-bedrag overnemen
           endif FactuurBedragInTotaalValuta,
           //betaald bedrag in opgegeven valuta
           if @OspBedragInValuta = 1 then
             isnull(sum(
                 if JrValNummer = @OspInDezeValuta then
                   if IsCreditBoeking <> @IsFactuurBoeking then JrValutaBedrag else 0 endif
                 else
                   if IsCreditBoeking <> @IsFactuurBoeking then ValutaOmrekenen(JrValNummer, JrValutaBedrag, @@BasisValutaNummer, @BjGid, @Pernr, 2)  else 0 endif / KoersTovBasisValuta(@BjGid, @Pernr, @OspInDezeValuta)
                 endif),0)
           else
             BetaaldBedragInValutaVanDeb
           endif BetaaldBedragInTotaalValuta,
           OspValNummer,
           OspGefiatteerd,
           OspFiatteringGewijzigdDoor,
           OspFiatteringGewijzigdOp
  from     tabJournaalRegel
  inner join tabOpenstaandePost on OspGid = JrOspGid
  inner join tabJournaalPost on (JpGid = JrJpGid)
  inner join tabDagboek on (JpDgbGid = DgbGid)
  inner join tabBoekingsgang on (BoekgangGid = JpBoekgangGid)
  inner join tabRekeningSchema on (RksGid = JrRksGid)
  where    1 = (if (@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                   (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                   (@SoortBoeking = 2) then 1 else 0 endif)
           and JrRksGid = @RksGid                                                  //Alleen voor deze rekening
           and JrBjGid = @BjGid                                                    //Alleen dit jaar
           and ((@StandPer is not null and jrBoekDatum <= @StandPer) or            //Alleen TOT de @StandPer zoals opgegeven (als geen @standper opgegeven, dan dus alleen beginbalans)
                (@StandPer is null and DagboekSoort = 5))                                                  //De beginbalans
           and
            //Alleen de OSPs tussen de factuurnummers
            // note DG: Factuurnummer wijziging; zoals afgesproken uitvullen met spaties en dan between selectie
            ((Repeat(' ',40-jrReferentie_Lengte) + jrReferentie) between @VanOsp and @TotOsp)
           and (JrVervalDatum between @VanVervalDatum and @TotVervalDatum)         //Alleen de OSPs tussen de vervaldata
  group by JrOspGid, OspValNummer, OspGefiatteerd, OspFiatteringGewijzigdDoor, OspFiatteringGewijzigdOp, OspVervalDatum, OspFactuurDatum // Om 1 regel per OSP te krijgen met de totaalde en betaalde factuurbedragen
  having   FactuurBedrag <> BetaaldBedrag;                                         //Alleen de niet-vervallen OSPs

  //unload select * from HistOsp To 'C:\tmpHistOsp01.txt';

  //Gegevens van de laatste betaling onthouden
  update HistOsp
  set    LaatsteBetalingDatum  = JrBoekDatum,
         LaatsteBetalingBedrag = case @OspBedragInValuta
                                   when 0 then //In valuta van osp
                                     JrValutaBedrag
                                   when 1 then //In valuta van debiteur
                                     if JrValNummer = RksValNummer then
                                       JrValutaBedrag
                                     else
                                       JrValutaBedrag / KoersTovBasisValuta(@BjGid, @Pernr, RksValNummer)
                                      endif
                                   when 2 then  //In opgegeven valuta
                                     if JrValNummer = @OspInDezeValuta then
                                       JrValutaBedrag
                                     else
                                       JrValutaBedrag / KoersTovBasisValuta(@BjGid, @Pernr, @OspInDezeValuta)
                                     endif
                                   end,
         LaatsteBetalingDagboek = jpDgbCode,
         LaatsteBetalingStukNr  = string(BoekstukNummer)+'.'+right('000'+string(StukVolgnr),3),
         //Let op: de volgende gegevens worden waarschijnlijk later nog overschreven (alleen niet als het alleen een vooruitbetaling betreft)
         FactuurNummer    = JrReferentie,
         FactuurDatum     = JrFactuurDatum,
         VervalDatum      = JrVervalDatum,
         BetalingsKenmerk = JrBetalingsKenmerk, //?? Deze juist bij de laatste betaling??
         Oms              = OmsJournaalRegel,
         ViaIncasso       = JrIsViaIncasso
  from   HistOsp
         inner join tabJournaalRegel  on (JrGid = IsNull (GeefLaatsteDeelBetalingJrGidHist (OspGid, @BjGid, @SoortBoeking, @StandPer), 0))
         inner join tabJournaalPost   on (JpGid = JrJpGid)
         inner join tabDagboek        on (JpDgbGid = DgbGid)
         inner join tabBoekingsgang   on (BoekgangGid = JpBoekgangGid)
         inner join tabRekeningSchema on (RksGid = JrRksGid);

  //unload select * from HistOsp To 'C:\tmpHistOsp02.txt';
  //call TraceEind('OspHistOsp');

  //Gegevens van de laatste factuurboeking onthouden
  update HistOsp
  set    FactuurNummer    = JrReferentie,
         FactuurDatum     = JrFactuurDatum,
         VervalDatum      = JrVervalDatum,
         BetalingsKenmerk = JrBetalingsKenmerk, //?? Deze juist bij de laatste betaling??
         Oms              = OmsJournaalRegel,
         ViaIncasso       = JrIsViaIncasso
  from   HistOsp inner join tabJournaalRegel on (JrOspGid = OspGid)
         inner join tabJournaalPost on (JpGid = JrJpGid)
         inner join tabDagboek on (JpDgbGid = DgbGid)
         inner join tabBoekingsgang on (BoekgangGid = JpBoekgangGid)
         inner join tabRekeningSchema on (RksGid = JrRksGid)
  where  1 = (if @SoortBoeking = 0 and IsBoekgangDefinitief = 1 then 1 else      //Alleen voorl./definitief/beide zoals opgegeven
              if @SoortBoeking = 1 and IsBoekgangDefinitief = 0 then 1 else
              if @SoortBoeking = 2 then 1 else 0 endif endif endif)
         and JpBjGid = @BjGid                                                    //Alleen dit jaar
         and ((@StandPer is not null and jrBoekDatum <= @StandPer) or            //Alleen TOT de @StandPer zoals opgegeven (als geen @standper opgegeven, dan dus alleen beginbalans)
              (@StandPer is null and DagboekSoort = 5))                          //De beginbalans
//         and IsCreditBoeking = 0                                                 //'Gewone' factuurboeking
//MR 11-apr-2008 bug #28093: isCreditboeking weggehaald en bij de order by gezet zodat de factuurnummers van anderen ook gevuld worden.
  order by IsCreditBoeking desc,JrGid desc;                                                           //Nodig om de laatste data etc. te vinden!

// onderstaande update tbv ouderdomsanalyse - wens# 50263 - Kolom1 t/m Kolom4 vullen.

  update
    HistOsp
  set
    Kolom1 = (if @PeilDatum <= AnalyseDatum + @Dagen1                                     then isnull(FactuurBedrag, 0) - isnull(BetaaldBedrag, 0) endif),
    Kolom2 = (if @PeilDatum between AnalyseDatum + @Dagen1 + 1 and AnalyseDatum + @Dagen2 then isnull(FactuurBedrag, 0) - isnull(BetaaldBedrag, 0) endif),
    Kolom3 = (if @PeilDatum between AnalyseDatum + @Dagen2 + 1 and AnalyseDatum + @Dagen3 then isnull(FactuurBedrag, 0) - isnull(BetaaldBedrag, 0) endif),
    Kolom4 = (if @PeilDatum > AnalyseDatum  + @Dagen3                                     then isnull(FactuurBedrag, 0) - isnull(BetaaldBedrag, 0) endif)
  where  (1=1);

  //unload select * from HistOsp To 'C:\tmpHistOsp03.txt';
  //call TraceEind('OspHistOsp');

  select
    OspGid,
    FactuurNummer,
    FactuurDatum,
    VervalDatum,
    BetalingsKenmerk,
    Oms,
    ViaIncasso,
    FactuurBedrag,
    BetaaldBedrag,
    FactuurBedrag - BetaaldBedrag OpenstaandBedrag,
    FactuurBedragInTotaalValuta,
    BetaaldBedragInTotaalValuta,
    FactuurBedragInTotaalValuta - BetaaldBedragInTotaalValuta OpenstaandBedragInTotaalValuta,
    FactuurBedragInValutaVanDeb,
    BetaaldBedragInValutaVanDeb,
    FactuurBedragInValutaVanDeb - BetaaldBedragInValutaVanDeb OpenstaandBedragInValutaVanDeb,
    HistOsp.ValNummer,
    ValCode,
    LaatsteBetalingDatum,
    LaatsteBetalingBedrag,
    LaatsteBetalingDagboek,
    LaatsteBetalingStukNr,
    OspGefiatteerd,
    OspFiatteringGewijzigdDoor,
    OspFiatteringGewijzigdOp,
    Kolom1,
    Kolom2,
    Kolom3,
    Kolom4

  from HistOsp left outer join tabValuta on (tabValuta.ValNummer = HistOsp.ValNummer)
  order by
    if @Ascending = 0 then case @SorteerOp when 1 then Factuurdatum when 2 then Vervaldatum end endif desc,
    if @Ascending = 0 then case @SorteerOp when 3 then Factuurbedrag when 4 then OpenstaandBedrag end endif desc,
    if @Ascending = 0 and @SorteerOp = 5 then Valcode endif desc,
    if @Ascending = 0 then Length(FactuurNummer) endif desc,
    if @Ascending = 0 then FactuurNummer endif desc,
    if @Ascending = 1 then case @SorteerOp when 1 then Factuurdatum when 2 then Vervaldatum end endif asc,
    if @Ascending = 1 then case @SorteerOp when 3 then Factuurbedrag when 4 then OpenstaandBedrag end endif asc,
    if @Ascending = 1 and @SorteerOp = 5 then Valcode endif asc,
    if @Ascending = 1 then Length(FactuurNummer) endif asc,
    if @Ascending = 1 then FactuurNummer endif asc;
end;

// call OspHistOsp(5, '2000-12-31', 2, 114, '', '9999999999', '2000-01-01', '2001-12-31', 0, null)

// call OspHistOsp(
// 11,                         // @BjGid             int        // Boekjaar van de OSPs
// '2023-03-30',               // @StandPer          date,      // Indien leeg, dan alleen de beginbalans!
// 2,                          // @SoortBoeking      smallint,  // 0=definitief, 1=voorlopig, 2=beide
// 343,                        // @RksGid            integer,
// '27',                       // @VanOsp            nchar(40),
// '0099000050',               // @TotOsp            nchar(40),
// '2023-01-01',               // @VanVervalDatum    date,
// '2023-12-31',               // @TotVervalDatum    date,
// 0,                          // @OspBedragInValuta smallint,  // Totalen van de OSPs per debiteur: 0=in debiteur-valuta, 1=in val. van deb.+andere valuta
// 0,                          // @OspInDezeValuta   integer,   // Als @OspBedragnInValuta=1, dan hierin de andere valuta
// 0,                          // @SorteerOp         smallint,
// 1,                          // @Ascending         smallint,
// '2023-03-30',               // @PeilDatum         date,      // PeilDatum tbv ouderdomsanalyse - wens# 50263
// 30,                         // @Dagen1            smallint,  // tbv ouderdomsanalyse - wens# 50263
// 30,                         // @Dagen2            smallint,  // tbv ouderdomsanalyse - wens# 50263
// 30,                         // @Dagen3            smallint,  // tbv ouderdomsanalyse - wens# 50263
// 0                           // @OuderdomObv       smallint   // tbv ouderdomsanalyse - wens# 50263, 0=vervaldatum, 1=factuurdatum
// )


create or replace procedure OspHistVal(
in @BjGid             integer,    // Boekjaar van de OSPs
in @FonID             nchar(1),   // Standaard: 'D'=debiteuren, 'C'=crediteuren
in @StandPer          date,       // Indien leeg, dan alleen de beginbalans!
in @SoortBoeking      smallint,   // 0=definitief, 1=voorlopig, 2=beide
in @SelecteerOp       smallint,   // 1=debnummer,  2=debzoekcode
in @VanDebCred        nchar(10),
in @TotDebCred        nchar(10),
in @VanOsp            nchar(40),
in @TotOsp            nchar(40),
in @VanVervalDatum    date,
in @TotVervalDatum    date,
// tbv ouderdomsanalyse - wens# 50263 - Start
in @PeilDatum         date,
in @Dagen1            smallint,
in @Dagen2            smallint,
in @Dagen3            smallint,
in @AnalyseValNummer  integer,    // Als null, dan valuta van de regel, anders deze valuta
in @OuderdomObv       smallint    // 0=vervaldatum, 1=factuurdatum
// tbv ouderdomsanalyse - wens# 50263 - Eind

)
result (
  ValNummer integer,
  ValCode nchar(3),
  OmsValuta nchar(40),
  FactuurBedrag numeric(15,2),
  BetaaldBedrag numeric(15,2),
  Openstaand numeric(15,2),
  Tegenwaarde numeric(15,2),
// tbv ouderdomsanalyse - wens# 50263 - Start
  AnalyticValNummer integer,
  AnalyticValCode nchar(3),
  Kolom1 numeric(15,2),
  Kolom2 numeric(15,2),
  Kolom3 numeric(15,2),
  Kolom4 numeric(15,2),
  BasisCumKolom1 numeric(15,2), // Kolom 1+2+3+4
  BasisCumKolom2 numeric(15,2), // Kolom 2+3+4
  BasisCumKolom3 numeric(15,2), // Kolom 3+4
  BasisCumKolom4 numeric(15,2)  // Kolom 4
// tbv ouderdomsanalyse - wens# 50263 - Eind
  )
begin

  //tbv. bepalen van de periode voor de koersberekeningen
  declare @DefaultSoort     integer;
  declare @PerNr            integer;
  declare @IsFactuurBoeking smallint;
  declare @Selectieveld     varchar(128);
  declare @BasisDatumVeld   varchar(128);

  //call traceBegin('OspHistVal(@BjGid='+string(@BjGid)+', @FonID='+@FonID+', @StandPer='+string(@StandPer)+', @SoortBoeking='+string(@SoortBoeking)+', @SelecteerOp='+string(@SelecteerOp)+', @VanDebCred='+@VanDebCred+', @TotDebCred='+@TotDebCred+', @VanOsp='+@VanOsp+', @TotOsp='+@TotOsp+', @VanVervalDatum='+string(@VanVervalDatum)+', @TotVervalDatum='+string(@TotVervalDatum)+')');

  //Bepaal welke kant (obv. IsCreditBoeking) de factuur-opboeking is
  if (@FonID='D') then
  begin
    set @IsFactuurBoeking = 0;
    set @DefaultSoort = 6;
  end
  else
  begin
    set @IsFactuurBoeking = 1;
    set @DefaultSoort = 7;
  end
  end if;

  case @SelecteerOp
    when 1 /*nummer*/   then set @Selectieveld = 'rksInvoer'
    when 2 /*zoekcode*/ then set @Selectieveld = 'rksZoekCode'
    else set @Selectieveld = '';
  end case;

  case @OuderdomObv
    when 0 /*Vervaldatum*/  then set @BasisDatumVeld = 'OspVervalDatum'
    when 1 /*Factuurdatum*/ then set @BasisDatumVeld = 'OspFactuurDatum'
  end case;

  //Bepaal de termijnen.
  set @dagen2 = @dagen1 + @dagen2;
  set @dagen3 = @dagen2 + @dagen3;

  //Bepaal de periode voor de koersberekening
  if (@StandPer is null) then
  begin
    //Koers van beginbalans gebruiken
    set @PerNr = 0;
  end
  else
  begin
    // deze verder niet gebruiken, daarom naar dit level gehaald.
    declare @BjGidStand       integer;

    //Geen beginbalans, dus bepaal periode obv. @StandPer
    //MR Bug# 25761 : waarom een dag eraf? // call BepaalBoekjaarEnPeriode(DateAdd(day, -1, @StandPer), @BjGidStand, @PerNr);
    call BepaalBoekjaarEnPeriode(@StandPer, @BjGidStand, @PerNr);

    if (@BjGidStand <> @BjGid) then
      //De periode valt niet in dit boekjaar, dus blijkbaar was het de eerste dag van dit boekjaar, dus dan geldt de eerste periode als koersbepaling
      //Let op: als we een onzin-@StandPer meegeven tov. de @BjGid dan geven we toch periode 1 als koersperiode! (Anders zouden we een RaisError moeten geven)
      set @PerNr = 1;
    end if;
  end;
  end if;

  //call traceEind('OspHistVal');

  select   jrVal.ValNummer,
           jrVal.ValCode,
           jrVal.OmsValuta,
           //Factuurbedrag in valuta van de OSP
           sum(if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else 0 endif) FactuurBedrag,
           //Betaald bedrag in valuta van de OSP
           sum(if IsCreditBoeking <> @IsFactuurBoeking then JrValutaBedrag else 0 endif) BetaaldBedrag,
           FactuurBedrag - BetaaldBedrag Openstaand,
           if (jrVal.ValNummer = @@BasisValutaNummer) then
             Openstaand
           else
             ValutaOmrekenen(jrVal.ValNummer, Openstaand, @@BasisValutaNummer, @BjGid, @Pernr, 2)
           endif
             Tegenwaarde,

// tbv ouderdomsanalyse - wens# 50263 - Start

           AnalyticValuta.ValNummer AnalyticValNummer,
           AnalyticValuta.ValCode AnalyticValCode,
           sum(if @PeilDatum <=  `[@BasisDatumVeld]` + @dagen1 then
                 if (OspValNummer = AnalyticValuta.ValNummer) then
                   if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else -JrValutaBedrag endif
                 else
                   ValutaOmrekenen(OspValNummer, if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else  -JrValutaBedrag endif , AnalyticValuta.ValNummer, @BjGid, @PerNr, 2)
                 endif
               else
                 0
               endif
              ) Kolom1,
           sum(if @PeilDatum between `[@BasisDatumVeld]` + @dagen1 + 1 and `[@BasisDatumVeld]` + @dagen2 then
                 if (OspValNummer = AnalyticValuta.ValNummer) then
                   if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else -JrValutaBedrag endif
                 else
                   ValutaOmrekenen(OspValNummer, if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else  -JrValutaBedrag endif , AnalyticValuta.ValNummer, @BjGid, @PerNr, 2)
                 endif
               else
                 0
               end if
              ) kolom2,
           sum(if @PeilDatum between `[@BasisDatumVeld]` + @dagen2 + 1 and `[@BasisDatumVeld]` + @dagen3 then
                 if (OspValNummer = AnalyticValuta.ValNummer) then
                   if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else -JrValutaBedrag endif
                 else
                   ValutaOmrekenen(OspValNummer, if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else  -JrValutaBedrag endif , AnalyticValuta.ValNummer, @BjGid, @PerNr, 2)
                 endif
               else
                 0
               endif
              ) Kolom3,
           sum(if @PeilDatum > `[@BasisDatumVeld]` + @dagen3 then
                 if (OspValNummer = AnalyticValuta.ValNummer) then
                   if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else -JrValutaBedrag endif
                 else
                   ValutaOmrekenen(OspValNummer, if IsCreditBoeking = @IsFactuurBoeking then JrValutaBedrag else  -JrValutaBedrag endif , AnalyticValuta.ValNummer, @BjGid, @PerNr, 2)
                 endif
               else
                 0
               endif
              ) Kolom4,
           if (AnalyticValuta.ValNummer = @@BasisValutaNummer) then
             Kolom1 + Kolom2 + Kolom3 + Kolom4
           else
              ValutaOmrekenen(AnalyticValuta.ValNummer, Kolom1 + Kolom2 + Kolom3 + Kolom4, @@BasisValutaNummer, @BjGid, @Pernr, 2)
           endif BasisCumKolom1,
           if (AnalyticValuta.ValNummer = @@BasisValutaNummer) then
             Kolom2 + Kolom3 + Kolom4
           else
             ValutaOmrekenen(AnalyticValuta.ValNummer, Kolom2 + Kolom3 + Kolom4, @@BasisValutaNummer, @BjGid, @Pernr, 2)
           endif BasisCumKolom2,
           if (AnalyticValuta.ValNummer = @@BasisValutaNummer) then
             Kolom3 + Kolom4
           else
             ValutaOmrekenen(AnalyticValuta.ValNummer, Kolom3 + Kolom4, @@BasisValutaNummer, @BjGid, @Pernr, 2)
           endif BasisCumKolom3,
           if (AnalyticValuta.ValNummer = @@BasisValutaNummer) then
             Kolom4
           else
             ValutaOmrekenen(AnalyticValuta.ValNummer, Kolom4, @@BasisValutaNummer, @BjGid, @Pernr, 2)
           endif BasisCumKolom4

// tbv ouderdomsanalyse - wens# 50263 - Eind

  from     tabJournaalRegel
           inner join tabOpenstaandePost       on (OspGid = JrOspGid)
           inner join tabJournaalPost          on (JpGid = JrJpGid)
           inner join tabBoekingsgang          on (BoekgangGid = JpBoekgangGid)
           inner join tabRekeningSchema        on (RksGid = JrRksGid)
// tbv ouderdomsanalyse - wens# 50263
           inner join tabValuta jrVal          on (jrVal.ValNummer = jrValNummer)
           inner join tabValuta AnalyticValuta on (AnalyticValuta.ValNummer = if @AnalyseValNummer is null then jrValNummer else @AnalyseValNummer endif)
           //inner join tabNawFile          on (NawFilRksGid = RksGid and NawFilFonId = @FonID)
           //inner join tabNaw              on (NawGid = NawFilNawGid)
           //inner join tabAdres            on (NawGidVestiging = AdrGid)
           //inner join tabLand             on (LndGid = AdrLndGid)
           //left outer join tabRelatie     on (RelGid = AdrRelGid)
           //left outer join tabNawRekening on (NawRekNawGid = NawGid and nawRekSoort like '%D%')
  where    1 = (if (@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                   (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                   (@SoortBoeking = 2) then 1 else 0 endif)
           and JpBjGid = @BjGid                                          // Alleen dit jaar
           and ((@StandPer is not null and jrBoekDatum <= @StandPer) or  // Alleen TOT de @StandPer zoals opgegeven (als geen @standper opgegeven, dan dus alleen beginbalans)
                (@StandPer is null and jrPernr = 0))                     // De beginbalans
           and (`[@Selectieveld]` between @VanDebCred and @TotDebCred) and (DefaultSoort = @DefaultSoort) // Alleen de juiste debiteuren/crediteuren
           and  //Alleen de OSPs tussen de factuurnummers
            // note DG: Factuurnummer wijziging; zoals afgesproken uitvullen met spaties en dan between selectie
            (Repeat(' ',40-jrReferentie_Lengte) + jrReferentie between Repeat(' ',40-length(@VanOsp)) + @VanOsp and Repeat(' ',40-length(@TotOsp)) + @TotOsp)
           and (JrVervalDatum between @VanVervalDatum and @TotVervalDatum)         //Alleen de OSPs tussen de vervaldata
           and JrOspGid in
              (select   a.JrOspGid
              from     tabJournaalRegel a
              inner join tabJournaalPost b on (b.jpgid = a.jrjpgid)
              inner join tabBoekingsgang d on (d.boekganggid = b.jpboekganggid)
              inner join tabRekeningSchema e on (e.RksGid = a.JrRksGid)
              where    1 = (if (@SoortBoeking = 0 and d.IsBoekgangDefinitief = 1) or
                               (@SoortBoeking = 1 and d.IsBoekgangDefinitief = 0) or
                               (@SoortBoeking = 2) then 1 else 0 endif)
                       and b.JpBjGid = @BjGid
                       and ((@StandPer is not null and a.jrBoekDatum <= @StandPer) or
                            (@StandPer is null and a.jrPernr = 0))
                       and
                        //Alleen de OSPs tussen de factuurnummers
                        // note DG: Factuurnummer wijziging; zoals afgesproken uitvullen met spaties en dan between selectie
                        (Repeat(' ',40-a.jrReferentie_Lengte) + a.jrReferentie between Repeat(' ',40-length(@VanOsp)) + @VanOsp and Repeat(' ',40-length(@TotOsp)) + @TotOsp)
                       and (a.JrVervalDatum between @VanVervalDatum and @TotVervalDatum)
              group by a.JrOspGid
              having   sum(if a.IsCreditBoeking = @IsFactuurBoeking then a.JrValutaBedrag else 0 endif) <>
                       sum(if a.IsCreditBoeking <> @IsFactuurBoeking then a.JrValutaBedrag else 0 endif))
// tbv ouderdomsanalyse - wens# 50263 : extra group by velden
  group by jrVal.ValNummer,
           jrVal.ValCode,
           jrVal.OmsValuta,
           AnalyticValuta.ValNummer,
           AnalyticValuta.ValCode
  having   isnull(sum(if IsCreditBoeking = 0 then JrValutaBedrag else 0 endif),0) <>
           isnull(sum(if IsCreditBoeking = 1 then JrValutaBedrag else 0 endif),0)           //Alleen de niet-vervallen OSPs
  order by jrVal.valnummer;

/* laatst aangepast : 17/10/2023 DemoArt
call OspHistVal(
  11,            // Boekjaar van de OSPs
  'D',           // Standaard: 'D'=debiteuren, 'C'=crediteuren
  '2023-10-16',  // Indien leeg, dan alleen de beginbalans!
  2,             // 0=definitief, 1=voorlopig, 2=beide
  1,             // 0=debnummer, 1=debzoekcode
  '12000001',    // @VanDebCred
  '12023572',    // @TotDebCred
  '27',          // @VanOsp
  '0099000482',  // @TotOsp
  '2023-02-08',  // @VanVervalDatum
  '2023-09-01',  // @TotVervalDatum
  '2023-10-16',  // @Peildatum
  30,            // @Dagen1
  30,            // @Dagen2
  30,            // @Dagen3
  0,             // @AnalyseValNummer
  1);            // @OuderdomObv: 0=vervaldatum, 1=factuurdatum
 */

end;   //  OspHistVal





if exists (select 1 from sys.sysProcedure where proc_name='OSPzitinVerwerkteBetalingsOfIncassoOpdracht') then
  drop procedure OSPzitinVerwerkteBetalingsOfIncassoOpdracht;
end if;

create function OSPzitInVerwerkteBetalingsOfIncassoOpdracht(in @OspGid integer)
returns smallint  //0 = Niet, 1 = In betalingsopdracht, 2 = In incasso-opdracht, 3 = In beiden
begin
  declare @result smallint = 0;

  set @@ErrorTextProcedure = 'OSPzitInVerwerkteBetalingsOfIncassoOpdracht @OspGid = '+string(@OspGid);
  //call TraceBegin(@@ErrorTextProcedure);

  // Controle op incasso-opdracht
  if exists(select first 1
            from   tabIncassoRegel
                   left outer join tabIncassoRegelVerzameld on IrvIncRglGid = IncRglGid
                   inner join tabOpenstaandePost on (OspRksGid = IncRglRksGid)
                                                and (   (OspFactuurnummer_Lengte = IncRglFactuurNummer_Lengte and OspFactuurnummer = IncRglFactuurnummer)
                                                     or (OspFactuurnummer_Lengte = IrvFactuurnummer_Lengte    and OspFactuurnummer = IrvFactuurNummer)
                                                    )
            where
                  OspGid = @OspGid
              and IncRglStatus in (1 /*Opdracht aangemaakt*/, 4 /*Opdracht gestorneerd*/)
           ) then
    set @result = @result + 2;
  end if;

  // Controle op betalingsopdracht
  if exists(select first 1
            from   tabBetalingRegel
                   left outer join tabBetalingVerzameld on BetVerzBetRglGid = BetRglGid
                   inner join tabOpenstaandePost on (OspRksGid = BetRglRksGid)
                                                and (   (OspFactuurnummer_Lengte = BetRglFactuurNummer_Lengte  and OspFactuurnummer = BetRglFactuurNummer)
                                                     or (OspFactuurnummer_Lengte = BetVerzFactuurnummer_Lengte and OspFactuurnummer = BetVerzFactuurnummer)
                                                    )
            where
                   OspGid = @OspGid
               and BetRglStatus = 1 /*Opdracht aangemaakt*/
           ) then
    set @result = @result + 1;
  end if;

  set @@ErrorTextProcedure = @@ErrorTextProcedure + ' -> '+ string(@result);
  //call TraceEind(@@ErrorTextProcedure);

  return(@result);
end;


create or replace procedure OssAangifteCorrectieRegelsAanmaken(
  in @OssKopGid integer,  //OssKopGid
  in @OpBasisVan smallint, //In te vullen gegevens op basis van: (0 = definitief, 1 = voorlopig, 2 = beide)
  in @CorrectiesVanafJaar integer,  //correctieregels aanmaken vanaf vanaf jaar
  in @CorrectiesVanafTijdvak smallint, //correctieregels aanmaken vanaf vanaf tijdvak (100=1e,200=2e,300=3e,400=4e kwartaal)
  in @OmzetbedragenHerberekenenObvBTWBedrag smallint default 1 //omzetbedragen herberekenen obv BTW bedrag
)
begin
  declare @_AangifteJaar Integer;  //Jaartal van de aangifte
  declare @_AangifteTijdvak SmallInt; //(Zie Meta van AilRglTijdvak)
  declare @_EigenLndGID Integer;  //Landcode die bij de bedrijfsgegevens is ingevuld (het land waar de belastingplichtige gevestigd is volgens de administratie)
  declare @_AangifteJaarTijdvak integer;  //AangifteJaar en tijdvak (bijv. 2022300)
  declare @_CorrectieJaarTijdvak integer;  //Correctiejaar en tijdvak (bijv 2022100)

  //call TraceBegin('OssAangifteCorrectieRegelsAanmaken > @OssKopGid='+string(@OssKopGid));

  //Eigen landcode vaststellen.
  select DefaultLndGid into @_EigenLndGID from tabVasteGegevens;

  //Aangiftejaar en -tijdvak bepalen a.d.h.v. OssKopGid
  select OssKopAangifteJaar, OssKopAangifteTijdvak
    into @_AangifteJaar, @_AangifteTijdvak
  from tabOssAangifteKop
  where OssKopGid = @OssKopGid;

  //Correctiejaartijdvak variabele vullen
  set @_CorrectieJaarTijdvak = (@CorrectiesVanafJaar * 100) + (select @beginmaand from IclTijdvaknaarBeginEindmaand(@CorrectiesVanafTijdvak));

  //jaar/tijdvak dat VOOR het jaar/tijdvak ligt van deze aangifte
  if @_AangifteTijdvak = 100 then
    set @_AangifteJaarTijdvak = ((@_Aangiftejaar - 1) * 100) + 12;
  else
    set @_AangifteJaarTijdvak = (@_Aangiftejaar * 100) + (select @beginmaand from IclTijdvaknaarBeginEindmaand(@_AangifteTijdvak)) - 1;
  end if;

  insert into tabOssAangifteRegel(OssRglBtwCode,
                                  OssRglLndGidLeveringAan,
                                  OssRglLndGidVanuit,
                                  OssRglOssKopGid,
                                  OssRglOmzetBedragBerekend,
                                  OssRglOmzetBedragAndereAangifte,
                                  OssRglOmzetBedragAangifte,
                                  OssRglBTWPercentage,
                                  OssRglJaar,
                                  //OssRglLastModified,
                                  OssRglLeveringVanuit,
                                  OssRglBTWBedragBerekend,
                                  OssRglBTWBedragAndereAangifte,
                                  OssRglBTWBedragAangifte,
                                  OssRglPrestatieSoort,
                                  OssRglSoort,
                                  OssRglTariefSoort,
                                  OssRglTijdvak,
                                  OssRglVerschil)
  select
    AangifteBTW,
    AangifteLndGidVanAangifte,
    AangifteLndGidVanuit,
    @OssKopGid,
    sum(AangifteBedragAangifte),
    sum(AangifteBedragAndereAangifte),
    sum(AangifteBedragAangifte - AangifteBedragAndereAangifte),
    AangifteBTWPercentage,
    AangifteJaar,
    AangifteBTWLeveringVanuit,
    sum(AangifteBTWBedragAangifte),
    sum(AangifteBTWBedragAndereAangifte),
    sum(AangifteBTWBedragAangifte - AangifteBTWBedragAndereAangifte),
    AangifteBTWPrestatieSoort,
    1, //Regelsoort Correcties
    AangifteBTWTarief,
    AangifteTijdvak,
    max(AangifteVerschil)
  from
  ( select
      BtwCode as AangifteBTW,
      LandVanAangifte.LndGid as AangifteLndGidVanAangifte,
      LandVanuit.LndGid as AangifteLndGidVanuit,
      (if DefaultSoort in (6 /* debiteur */ ,7 /* crediteur */) then
           JrBasisBedrag * (2*IsCreditBoeking-1) /*Credit, dan x-1*/ -
           (HulpRekBasisBedrag * (1-2*HulpRekIsCredit) /*credit, dan x-1*/)
        else
           (JrBasisBedrag * (1-2*IsCreditBoeking) /*credit, dus x-1*/)
        endif * (if BtwSoort=1 then -1 else 1 endif)) as AangifteBedragAangifte,
      0 as AangifteBedragAndereAangifte,
      BtwPercentage as AangifteBTWPercentage,
      year(JrBoekdatum) as AangifteJaar,
      BtwLeveringVanuit as AangifteBTWLeveringVanuit,
      if AangifteBedragAangifte is not null then
        (HulpRekBasisBedrag * (1-2*HulpRekIsCredit) /*credit, dan x-1*/ * (if BtwSoort=1 then -1 else 1 endif))
      endif as AangifteBTWBedragAangifte,
      0 as AangifteBTWBedragAndereAangifte,
      BtwPrestatieSoort as AangifteBTWPrestatieSoort,
      BtwTarief as AangifteBTWTarief,
      (CEILING(month(JrBoekdatum)/3.0) * 100) as AangifteTijdvak,
      if (AangifteBTWBedragAangifte <> (TRUNCNUM(AangifteBedragAndereAangifte * (AangifteBTWPercentage/100),2)* (if BtwSoort=1 then -1 else 1 endif))) and
         (AangifteBTWBedragAangifte <> (round(AangifteBedragAndereAangifte * (AangifteBTWPercentage/100),2)* (if BtwSoort=1 then -1 else 1 endif))) then 1 else 0 endif  as AangifteVerschil
    from tabJournaalRegel
    inner join tabJournaalPost on (jpGid = jrJpGid)
    inner join tabBoekingsgang on (JpBoekgangGid = BoekgangGid)
    inner join tabHulpRekening on (JrGid = HulpRekJrGid)
    inner join tabBtw on BtwCode = HulpRekBtwCode
    left outer join tabLand LandVanAangifte on LandVanAangifte.LndGid = BtwLndGid
    left outer join tabLand LandVanuit on LandVanuit.LndGid = BtwLndGidVanuit
    inner join tabRekeningSchema on (rksGid = jrRksGid)
    where ((year(JrBoekdatum)*100) + month(JrBoekdatum)) between @_CorrectieJaarTijdvak and @_AangifteJaarTijdvak
      and ((@OpBasisVan = 0 and IsBoekGangDefinitief <> 0)
        or (@OpBasisVan = 1 and IsBoekGangDefinitief =  0)
        or (@OpBasisVan = 2)
          )
      and (BtwLndGid is not null and BtwLndGid <> @_EigenLndGID)
      and BtwLeveringVanuit in (0 /* Eigen land (MSID)*/ , 1 /* Ander EU-land (MSEST)*/)
    UNION ALL
    select
      OssRglBtwCode as AangifteBTW,
      OssRglLndGidLeveringAan as AangifteLndGidVanAangifte,
      OssRglLndGidVanuit as AangifteLndGidVanuit,
      0 as AangifteBedragAangifte,
      OssRglOmzetBedragAangifte as AangifteBedragAndereAangifte,
      OssRglBTWPercentage as AangifteBTWPercentage,
      if OssRglSoort = 0 then /*Periode*/ OssKopAangifteJaar else /*Correctie*/ OssRglJaar endif as AangifteJaar,
      OssRglLeveringVanuit as AangifteBTWLeveringVanuit,
      0 as AangifteBTWBedragAangifte,
      OssRglBTWBedragAangifte as AangifteBTWBedragAndereAangifte,
      OssRglPrestatieSoort as AangifteBTWPrestatieSoort,
      OssRglTariefSoort as AangifteBTWTarief,
      if OssRglSoort = 0 then /*Periode*/ OssKopAangifteTijdVak else /*Correctie*/ OssRglTijdvak endif as AangifteTijdvak,
      OssRglVerschil as AangifteVerschil
    from tabOssAangifteKop
    inner join tabOssAangifteRegel on OssRglOssKopGid = OssKopGid
    where ((AangifteJaar*100) + (select @beginmaand from IclTijdvaknaarBeginEindmaand(AangifteTijdvak))) between @_CorrectieJaarTijdvak and @_AangifteJaarTijdvak
    and (OssKopGid <> @OssKopGid or OssRglSoort = 1 /*Correcties van huidige aangifte wel meenemen*/)
    and ((OssKopAangifteJaar*1000) + OssKopAangifteTijdVak) <= (select ((OssKopAangifteJaar*1000) + OssKopAangifteTijdVak) from tabOssAangifteKop where OssKopGid=@OssKopGid)
  ) as DummyTableOssAangifte
  group by AangifteBTW, AangifteLndGidVanAangifte, AangifteLndGidVanuit, AangifteBTWPercentage, AangifteJaar, AangifteBTWLeveringVanuit, AangifteBTWPrestatieSoort, AangifteBTWTarief, AangifteTijdvak
  having (sum(AangifteBedragAangifte - AangifteBedragAndereAangifte) <> 0)
      or (sum(AangifteBTWBedragAangifte - AangifteBTWBedragAndereAangifte) <> 0);

  //Als aangegeven dat het omzetbedrag vanuit de btw berekend wordt bij een verschil
  if @OmzetbedragenHerberekenenObvBTWBedrag = 1 then
    update tabOssAangifteRegel
    set OssRglOmzetBedragBerekend = round(OssRglBTWBedragBerekend/(OssRglBTWPercentage/100),2),
        OssRglOmzetBedragAndereAangifte = round(OssRglBTWBedragAndereAangifte/(OssRglBTWPercentage/100),2),
        OssRglOmzetBedragAangifte = round(OssRglBTWBedragAangifte/(OssRglBTWPercentage/100),2),
        OssRglVerschil = 0
    where OssRglOssKopGid = @OssKopGid
      and OssRglVerschil = 1
      and OssRglSoort = 1 /*Correcties*/;
  end if;
  //call TraceEind('OssAangifteCorrectieRegelsAanmaken > @OssKopGid='+string(@OssKopGid));
end;


create or replace procedure OssAangifteRegelsAanmaken(
  in @OssKopGid integer,  //OssKopGid
  in @OpBasisVan smallInt, //In te vullen gegevens op basis van: (0 = definitief, 1 = voorlopig, 2 = beide)
  in @OmzetbedragenHerberekenenObvBTWBedrag smallint default 1 //omzetbedragen herberekenen obv BTW bedrag
)
begin
  declare @_AangifteJaar integer;  //Jaartal van de aangifte
  declare @_AangifteTijdvak smallint; //regels aanmaken voor tijdvak (100=1e,200=2e,300=3e,400=4e kwartaal)
  declare @_Beginmaand smallint; // eerste  maand van het tijdvak
  declare @_Eindmaand smallint; // laatste maand van het tijdvak
  declare @_BJGid integer;
  declare @_EigenLndGID integer;  // Eigen landcode

  //call TraceBegin('OssAangifteRegelsAanmaken > @OssKopGid='+string(@OssKopGid));

  //Aangiftejaar en -tijdvak bepalen a.d.h.v. OssKopGid
  select OssKopAangifteJaar, OssKopAangifteTijdvak
    into @_AangifteJaar, @_AangifteTijdvak
  from tabOssAangifteKop
  where OssKopGid = @OssKopGid;

  //Eigen landcode vaststellen.
  select DefaultLndGid into @_EigenLndGID from tabVasteGegevens;

  //begin- en eindmaand van het tijdvak vaststellen.
  select @Beginmaand,@Eindmaand
    into @_Beginmaand,@_Eindmaand
  from IclTijdvaknaarBeginEindmaand(@_AangifteTijdvak);

  //Het boekjaar obv het aangiftejaar en beginmaand van dat jaar
  select BjGID
    into @_BJGid
  from tabBoekjaar
  where DateAdd(Month, @_Beginmaand, YMD(@_AangifteJaar,1,1)) between BjBeginDatum and BjEindDatum;

  insert into tabOssAangifteRegel with auto name
  select
    BtwCode OssRglBtwCode,
    LandVanAangifte.LndGid OssRglLndGidLeveringAan,
    LandVanuit.LndGid OssRglLndGidVanuit,
    @OssKopGid OssRglOssKopGid,
    sum(if DefaultSoort in (6 /* debiteur */ ,7 /* crediteur */) then
           (JrBasisBedrag * (2*IsCreditBoeking-1) /*Credit, dan x-1*/) -
           (HulpRekBasisBedrag * (1-2*HulpRekIsCredit) /*credit, dan x-1*/)
        else
           (JrBasisBedrag * (1-2*IsCreditBoeking) /*credit, dus x-1*/)
        endif * (if BtwSoort=1 then -1 else 1 endif)) OssRglOmzetBedragBerekend ,
    OssRglOmzetBedragBerekend OssRglOmzetBedragAangifte,
    BtwPercentage OssRglBTWPercentage,
    @_AangifteJaar OssRglJaar,
    BtwLeveringVanuit OssRglLeveringVanuit,
    if OssRglOmzetBedragBerekend is not null then
      sum(HulpRekBasisBedrag * (1-2*HulpRekIsCredit) /*credit, dan x-1*/
          * (if BtwSoort=1 then -1 else 1 endif))
    endif OssRglBTWBedragBerekend,
    OssRglBTWBedragBerekend OssRglBTWBedragAangifte,
    BtwPrestatieSoort OssRglPrestatieSoort,
    0 OssRglSoort, //Regelsoort Periodes
    BtwTarief OssRglTariefSoort,
    @_AangifteTijdvak OssRglTijdvak,
    if ((OssRglBTWBedragBerekend <> (TRUNCNUM(OssRglOmzetBedragBerekend * (BtwPercentage/100), 2)* (if BtwSoort=1 then -1 else 1 endif))) and (OssRglBTWBedragBerekend <> (round(OssRglOmzetBedragBerekend * (BtwPercentage/100), 2))* (if BtwSoort=1 then -1 else 1 endif))) then 1 else 0 endif OssRglVerschil
  from tabJournaalRegel
  inner join tabJournaalPost on (jpGid = jrJpGid)
  inner join tabBoekingsgang on (JpBoekgangGid = BoekgangGid)
  inner join tabHulpRekening on (JrGid = HulpRekJrGid)
  inner join tabBtw on BtwCode = HulpRekBtwCode
  left outer join tabLand LandVanAangifte on LandVanAangifte.LndGid = BtwLndGid
  left outer join tabLand LandVanuit on LandVanuit.LndGid = BtwLndGidVanuit
  inner join tabRekeningSchema on (rksGid = jrRksGid)
  where (JrBjGid = @_BJGid)
    and (month(JrBoekdatum) between @_Beginmaand and @_Eindmaand)
    and ((@OpBasisVan = 0 and IsBoekGangDefinitief <> 0)
      or (@OpBasisVan = 1 and IsBoekGangDefinitief =  0)
      or (@OpBasisVan=2)
        )
    and (BtwLndGid is not null and BtwLndGid <> @_EigenLndGID)
    and BtwLeveringVanuit in (0 /* Eigen land (MSID)*/ , 1 /* Ander EU-land (MSEST)*/)
  group by BtwCode, LandVanAangifte.LndGid, LandVanuit.LndGid,BtwPercentage, BtwLeveringVanuit,BtwPrestatieSoort,BtwTarief,BtwSoort
  order by btwcode;

  //Als aangegeven dat het omzetbedrag vanuit de btw berekend wordt bij een verschil
  if @OmzetbedragenHerberekenenObvBTWBedrag = 1 then
    update tabOssAangifteRegel
    set OssRglOmzetBedragBerekend = round(OssRglBTWBedragBerekend/(OssRglBTWPercentage/100),2),
        OssRglOmzetBedragAangifte = round(OssRglBTWBedragAangifte/(OssRglBTWPercentage/100),2),
        OssRglVerschil = 0
    where OssRglOssKopGid = @OssKopGid
      and OssRglVerschil = 1
      and OssRglSoort = 0 /*Periodes*/;
  end if;
  //call TraceEind('OssAangifteRegelsAanmaken > @OssKopGid='+string(@OssKopGid));
end;

create or replace procedure OssAangifteRegelsVerwijderen(
  in @OssKopGid integer,  //OssKopGid
  in @OssRegelSoort smallint //0 = Periodes, 1 = Correcties, 2 = Beide)
)
begin
  //call TraceBegin('OssAangifteRegelsVerwijderen > @OssKopGid='+string(@OssKopGid));

  delete from tabOssAangifteRegel
  where OssRglOssKopGid = @OssKopGid
    and ((@OssRegelSoort = 2) or (OssRglSoort = @OssRegelSoort));

  //call TraceEind('OssAangifteRegelsVerwijderen > @OssKopGid='+string(@OssKopGid));
end;

create or replace procedure OssAangifteRegelsVullenobvAdmin(
  in @OssKopGid integer,  //OssKopGid
  in @OpBasisVan smallInt, //In te vullen gegevens op basis van: (0 = definitief, 1 = voorlopig, 2 = beide)
  in @AangiftePeriode smallint, //Regels uit aangifteperiode vullen. (1 = ja, anders = nee)
  in @CorrectiesUitVorigePerioden smallInt, //Correcties vullen (1 = ja, anders = nee)
  in @CorrectiesVanafJaar integer,  //Correctieregels aanmaken vanaf vanaf jaar
  in @CorrectiesVanafTijdvak smallint, //Correctieregels aanmaken vanaf vanaf tijdvak (100=1e,200=2e,300=3e,400=4e kwartaal)
  in @OmzetbedragenHerberekenenObvBTWBedrag smallint default 1 //omzetbedragen herberekenen obv BTW bedrag
)
begin
  //call TraceBegin('OssAangifteRegelsVullenobvAdmin > @OssKopGid='+string(@OssKopGid));
  declare _qcJa smallint = 1;
  declare _qcNee smallint = 0;

  //Aanmaken regels vanuit de aangifte periode
  if IsNull(@AangiftePeriode, _qcNee) = _qcJa then
    //call Trace('OssAangifteRegelsVullenobvAdmin > Aanmaken regels van de aangifte periode');
    call OssAangifteRegelsVerwijderen(@OssKopGid, 0 /*Periode*/);
    call OssAangifteRegelsAanmaken(@OssKopGid, @OpBasisVan, @OmzetbedragenHerberekenenObvBTWBedrag);
  end if;

  //Aanmaken Correcties levering-regels
  if IsNull(@CorrectiesUitVorigePerioden, _qcNee) = _qcJa then
    //call Trace('IclAangifteRegelsVullen > Aanmaken Correctie levering-regels');
    call OssAangifteRegelsVerwijderen(@OssKopGid, 1 /*Correctieregels*/);
    call OssAangifteCorrectieRegelsAanmaken(@OssKopGid, @OpBasisVan, @CorrectiesVanafJaar, @CorrectiesVanafTijdvak, @OmzetbedragenHerberekenenObvBTWBedrag);
  end if;

  //call TraceEind('OssAangifteRegelsVullenobvAdmin > @OssKopGid='+string(@OssKopGid));
end;

create or replace procedure OvernemenJaarBudgetten(
    in @BjGid integer,
    in @BjGidVorigJaar integer,
    in @OvernemenVan smallint,
    in @Van nchar(28),
    in @Tot nchar(28),
    in @BlCode integer
    )
begin
  //@OvernemenVan: 0=Rekeningen, 1=Balanscodes, 2=Kstp, 3=Kstd
  //@BlCode      : alleen geldig indien @OvernemenVan=1
  declare local temporary table temp(
    tmpGid            integer default autoincrement,
    tmpRksGid         integer,
    tmpKstpGid        integer,
    tmpKstdGid        integer,
    tmpBlGid          integer,
    tmpBudgetCode     integer,
    tmpVorigBudgetgid integer, //Budgetgid van vorig jaar
    tmpRubParSub      nchar(11)
  ) on commit preserve rows;

  declare @LaatstePeriode        integer;
  declare @BudgetCode            integer;
  declare @BaserenOp             integer;      //0=Budget van vorig jaar, 1=werkelijke saldi
  declare @OvernemenSaldo        integer;      //0=Saldo, 1=Default-boekzijde
  declare @Overschrijven         integer;      //0=Nee, 1=Ja
  declare @PercentageBij         numeric(6,2); //-100% - 999,99%
  declare @IndienBudgetVorigJaar smallint;     //0=Nee, voor alles een budget, 1=Nee, alleen indien vorig jaar GEEN budget, 2=Ja
  declare @AfrondenVan           smallint;     //0=Standaard, 1=Altijd omhoog, 2=Altijd omlaag
  declare @SoortBoeking          smallint;     // 0=definitief, 1=voorlopig, 2=beide
  declare @AantalTeDoen          integer;      //tbv. progress

  declare @PeriodesZijnGelijk    smallint;     //1 als aantal periodes van beide boekjaren gelijk

  declare @OvernemenBudgetTekst long nvarchar;

  //call TraceBegin('OvernemenJaarBudgetten(@BjGid='+string(@BjGid)+', @BjGidVorigJaar='+string(@BjGidVorigJaar)+', @OvernemenVan='+string(@OvernemenVan)+', @Van='+@Van+', @Tot='+@Tot+', @BlCode='+string(@BlCode)+')');

  set @OvernemenBudgetTekst = _U('Overnemen jaarbudget');

  call ProgressSet(0, 500, @OvernemenBudgetTekst);

  select first vastOjbBudgetCode, vastOjbBaserenOp, vastOjbOvernemenSaldo, vastOjbOverschrijven, vastOjbPercentageBij, vastOjbIndienBudgetVorigJaar, vastOjbAfrondenVan, VastOjbSaldoOpBasisVan
  into @BudgetCode, @BaserenOp, @OvernemenSaldo, @Overschrijven, @PercentageBij, @IndienBudgetVorigJaar, @AfrondenVan, @SoortBoeking
  from tabvastegegevensovernemenjaarbudget;

  call ProgressAdd(1);

  //---------- Vullen van de tussentabel (Bepalen van de van...tot) ----------

  //Eventuele beperking van indien alleen vorig jaar een budget is hier verwerkt
  case @OvernemenVan
  when 0 then //Rekeningen
    insert into temp(tmpRksGid, tmpBudgetCode, tmpVorigBudgetgid)
      select RksGid, if BudgetGid is null then @BudgetCode else BudBudgetCode endif, BudgetGid
      from   tabRekeningSchema left outer join tabBudget on (BudRksGid = RksGid and BudBjGid = @BjGidVorigJaar)
      where  RksInvoer between @Van and @Tot and //Selectie van rekeningen
             (@IndienBudgetVorigJaar=0 or (@IndienBudgetVorigJaar=1 and BudgetGid is null) or (@IndienBudgetVorigJaar=2 and BudgetGid is not null)) and //Selectie indien wel of juist geen budget vorig jaar
             (@Overschrijven = 1 or (@Overschrijven=0 and (select 1 from tabBudget binnen where binnen.BudRksGid = RksGid and binnen.BudBjGid = @BjGid) is null)); //Overschrijven?

  when 1 then //Balanscodes
    insert into temp(tmpBlGid, tmpBudgetCode, tmpVorigBudgetgid, tmpRubParSub)
      select BlGid, if BudgetGid is null then @BudgetCode else BudBudgetCode endif, BudgetGid, RubParSub
      from   tabBalanscodeDetail left outer join tabBudget on (BudBlGid = BlGid and BudBjGid = @BjGidVorigJaar)
      where  DetailBlCode = @BlCode and RubParSub between @Van and @Tot and  //Selectie van balanscodedetails
             (@IndienBudgetVorigJaar=0 or (@IndienBudgetVorigJaar=1 and BudgetGid is null) or (@IndienBudgetVorigJaar=2 and BudgetGid is not null)) and //Selectie indien wel of juist geen budget vorig jaar
             (@Overschrijven = 1 or (@Overschrijven=0 and (select 1 from tabBudget binnen where binnen.BudBlGid = BlGid and binnen.BudBjGid = @BjGid) is null)); //Overschrijven?

  when 2 then //Kstp
    insert into temp(tmpKstpGid, tmpBudgetCode, tmpVorigBudgetgid)
      select KstpGid, if BudgetGid is null then @BudgetCode else BudBudgetCode endif, BudgetGid
      from   tabKostenplaats left outer join tabBudget on (BudKstpGid = KstpGid and BudBjGid = @BjGidVorigJaar)
      where  KstpCode between @Van and @Tot and
             (@IndienBudgetVorigJaar=0 or (@IndienBudgetVorigJaar=1 and BudgetGid is null) or (@IndienBudgetVorigJaar=2 and BudgetGid is not null)) and //Selectie indien wel of juist geen budget vorig jaar
             (@Overschrijven = 1 or (@Overschrijven=0 and (select 1 from tabBudget binnen where binnen.BudKstpGid = KstpGid and binnen.BudBjGid = @BjGid) is null)); //Overschrijven?

  when 3 then //Kstd
    insert into temp(tmpKstdGid, tmpBudgetCode, tmpVorigBudgetgid)
      select KstdGid, if BudgetGid is null then @BudgetCode else BudBudgetCode endif, BudgetGid
      from tabKostendrager left outer join tabBudget on (BudKstdGid = KstdGid and BudBjGid = @BjGidVorigJaar)
      where KstdCode between @Van and @Tot and
             (@IndienBudgetVorigJaar=0 or (@IndienBudgetVorigJaar=1 and BudgetGid is null) or (@IndienBudgetVorigJaar=2 and BudgetGid is not null)) and //Selectie indien wel of juist geen budget vorig jaar
             (@Overschrijven = 1 or (@Overschrijven=0 and (select 1 from tabBudget binnen where binnen.BudKstdGid = KstdGid and binnen.BudBjGid = @BjGid) is null)); //Overschrijven?

  end case;

  select max(PerNr) into @LaatstePeriode from tabPeriode where PerBjGid = @BjGidVorigJaar;
  set @PeriodesZijnGelijk = if (select max(PerNr) from tabPeriode where PerBjGid = @BjGid) = @LaatstePeriode then 1 else 0 endif;

  if @PeriodesZijnGelijk = 0 then
    //Periodebudgetten worden toch maar niet overgenomen omdat het aantal periodes anders is
    delete temp where tmpBudgetCode is null;
  end if;

  call ProgressAdd(1);

  //---------- Oude budgetten optioneel verwijderen ----------

  //Ok, nu weten we voor welke rek/rubparsub/kstp/kstd we een budget moeten aanmaken. Nu eerst de oude budgetten verwijderen indien nodig
  if @Overschrijven = 1 then
    //Budgetten verwijderen indien nodig
    delete tabbudget
    where BudgetGid in (select BudgetGid from tabBudget inner join temp on (BudBjGid = @BjGid and isnull(tmpRksGid,0)=isnull(BudRksGid,0) and isnull(tmpBlGid,0)=isnull(BudBlGid,0) and isnull(tmpKstdGid,0)=isnull(BudKstdGid,0) and isnull(tmpKstpGid,0)=isnull(BudKstpGid,0)));
  end if;


  set @AantalTeDoen = (select count(*) from temp where tmpBudgetCode is not null) +
                      (select count(*) from temp where tmpBudgetCode is null) * (select count(*)-1 from tabperiode where PerBjGid=@BjGid);
  call ProgressDelete;
  call ProgressCreate(0, @AantalTeDoen, @OvernemenBudgetTekst);

  //---------- Aanmaken van budgetten op jaarbasis gebaseerd ----------

  //Verdeling van het jaarbedrag over de maanden is niet nodig!!
  if @BaserenOp = 0 then
    //Baseren op budget vorig jaar
    insert into tabbudget(BudBjGid, BudRksGid, BudBlGid, BudKstpGid, BudKstdGid, Jaarbudget, VergelijkenMet, BudMetVerdeling, budBudgetcode)
    select   @BjGid, tmpRksGid, tmpBlGid, tmpKstpGid, tmpKstdgid,
             (select AfrondingOvernemenJaarbudget(sum(Jaarbudget) * ((100+@PercentageBij)/100), @AfrondenVan)
              from   tabBudget
              where  (BudBjGid = @BjGidVorigJaar and BudgetGid=tmpVorigBudgetgid)
             ) Bedrag,
             //if tmpRksGid is null then 0 else if (DefaultSoort=6) then 1 else if (DefaultSoort=7) then 2 else 3 endif endif endif,
             if tmpRksGid is not null then 3 else 0 endif,  //Default boekzijde (indien grootboekrekening) of rekeningsaldo
             1, //Budget met verdeling
             tmpBudgetCode
    from     temp
    where    temp.tmpBudgetCode is not null // and Bedrag <> 0 (zie opmerking hieronder)
    group by tmpRksGid, tmpBlGid, tmpKstpGid, tmpKstdgid, tmpVorigBudgetgid, tmpBudgetCode, tmpRubParSub
    having   Bedrag <> 0;
    // TG 19-06-2003: Oplossing bug #9606: "Bedrag <> 0" moest in de HAVING. tmpVorigBudgetgid bleek NULL te
    // zijn in de subselect terwijl hij buiten de subselect wel een waarde had.
    // De test op een resultaat van een berekening met een veld dat in de group by wordt gebruikt moet altijd
    // in de HAVING (ipv de WHERE).
  else
    //Baseren op werkelijke saldo (van de rekeningen die binnen de balanscode/kostenplaats/-drager vallen)
    insert into tabbudget(BudBjGid, BudRksGid, BudBlGid, BudKstpGid, BudKstdGid, Jaarbudget, VergelijkenMet, BudMetVerdeling, budBudgetcode)
    select   @BjGid, tmpRksGid, tmpBlGid, tmpKstpGid, tmpKstdgid,
             (select AfrondingOvernemenJaarbudget(sum(
                        (if tempRks.DefaultBoekzijde = 3 then if tempRks.DefaultSoort in (2, 5, 7) then -1 else 1 endif else if tempRks.DefaultBoekzijde = 1 then -1 else 1 endif endif) * //ACW 22-11-2000: Rekening houden met soort rekening (debet of credit)
                        if @OvernemenVan = 0 and isnull(tempRks.RksValNummer,-1) = isnull(tempRks.RekSaldoValNummer,-1) then //Rekeningen overnemen in dezelfde valuta? Dan direct het bedrag overnemen
                          if @OvernemenSaldo=0 or tempRks.DefaultBoekzijde not in (0,1,3) then //Baseren op werkelijke bedragen of er is geen default-zijde ingesteld
                            isnull(tempRks.SaldoDebetValuta,0)-isnull(tempRks.SaldoCreditValuta,0)     //baseren op saldo
                          else
                            if (tempRks.DefaultBoekzijde=0) or (tempRks.DefaultSoort=6) then                               //baseren op default-boekzijde
                              isnull(tempRks.SaldoDebetValuta,0)                             //Boekzijde=debet & debiteuren
                            else
                              -isnull(tempRks.SaldoCreditValuta,0)                            //Boekzijde=credit & crediteuren
                            endif
                          endif
                        else
                          ValutaOmrekenen(@@BasisValutaNummer,
                                          if @OvernemenSaldo=0 or tempRks.DefaultBoekzijde not in (0,1,3) then //Baseren op werkelijke bedragen of er is geen default-zijde ingesteld
                                            tempRks.SaldoDebetBasis-tempRks.SaldoCreditBasis     //baseren op saldo
                                          else
                                            if (tempRks.DefaultBoekzijde=0) or (tempRks.DefaultSoort=6) then                  //baseren op default-boekzijde
                                              isnull(tempRks.SaldoDebetBasis,0)                              //Boekzijde=debet & debiteuren
                                            else
                                              -isnull(tempRks.SaldoCreditBasis,0)                            //Boekzijde=credit & crediteuren
                                            endif
                                          endif,
                                          if @OvernemenVan = 0 then tempRks.RksValNummer else @@BasisValutaNummer endif,  //Rekeningen overnemen, dus in de valuta van de rekening zetten (ipv. basis)
                                          @BjGidVorigJaar,
                                          @LaatstePeriode,
                                          2)
                        endif) * ((100+@PercentageBij)/100), @AfrondenVan)
              from
                (
                    select
                        DefaultBoekzijde,
                        DefaultSoort,
                        RksValNummer,
                        RekSaldoValNummer,
                        (case @SoortBoeking
                            when 0 then SaldoDebetValutaDefinitief
                            when 1 then SaldoDebetValutaVoorlopig
                            when 2 then SaldoDebetValutaDefinitief + SaldoDebetValutaVoorlopig
                        end) as SaldoDebetValuta,
                        (case @SoortBoeking
                            when 0 then SaldoCreditValutaDefinitief
                            when 1 then SaldoCreditValutaVoorlopig
                            when 2 then SaldoCreditValutaDefinitief + SaldoCreditValutaVoorlopig
                        end) as SaldoCreditValuta,
                        (case @SoortBoeking
                            when 0 then SaldoDebetBasisDefinitief
                            when 1 then SaldoDebetBasisVoorlopig
                            when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig
                        end) as SaldoDebetBasis,
                        (case @SoortBoeking
                            when 0 then SaldoCreditBasisDefinitief
                            when 1 then SaldoCreditBasisVoorlopig
                            when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig
                        end) as SaldoCreditBasis


                    from tabRekeningSchema
                    left outer join tabRekeningsaldo      on (RksGid = RekSaldoRksGid    and RekSaldoBjGid = @BjGidVorigJaar and RekSaldoPerNr <> 0)  //Let op: als we baseren op budget, dan maar 1x een tabrekeningschema-rekening gebruiken!
                    where  (@OvernemenVan = 0 and RksGid     = tmpRksGid                           ) or //Rekeningen
                         (@OvernemenVan = 1 and @BlCode =  0 and RksInvoer like tmpRubParSub+'%' ) or //Balanscodes, balanscode = 000
                         (@OvernemenVan = 1 and @BlCode <> 0 and rksgid in (select BlRksGid from tabBalansCodeRekening
                                                                            where  BlRekBlGid in (select BlGid from tabBalanscodeDetail
                                                                                                  where  detailBlCode = @BlCode and RubParSub like tmpRubParSub+'%'))) or //Balanscodes, balanscode <> 000
                         (@OvernemenVan = 2 and RksKstpGid = tmpKstpGid                          ) or //Kostenplaatsen
                         (@OvernemenVan = 3 and RksKstpGid = tmpKstdGid                          )    //Kostendragers
                 ) as tempRks
             ) Bedrag,
             if tmpRksGid is null then 0 else 3 endif, //Default boekzijde (indien grootboekrekening) of rekeningsaldo
             1, //Budget met verdeling
             tmpBudgetCode
    from     temp
    where    temp.tmpBudgetCode is not null // and Bedrag <> 0 (oplossing bug #9606)
    group by tmpRksGid, tmpBlGid, tmpKstpGid, tmpKstdgid, tmpVorigBudgetgid, tmpBudgetCode, tmpRubParSub
    having   Bedrag <> 0;
  end if;

  //---------- Aanmaken van budgetten op periode gebaseerd ----------

  //Eerst budget zelf plaatsen (jaarbudget wordt later bepaald!)
  if @PeriodesZijnGelijk = 1 then
    //Kan natuurlijk alleen als we gelijk aantal periodes hebben
    insert into tabbudget(BudBjGid, BudRksGid, BudBlGid, BudKstpGid, BudKstdGid, Jaarbudget, VergelijkenMet, BudMetVerdeling)
    select @BjGid, tmpRksGid, tmpBlGid, tmpKstpGid, tmpKstdgid, 0,
           if tmpRksGid is not null then 3 else 0 endif, //Default boekzijde (indien grootboekrekening) of rekeningsaldo
           0 //Budget zonder verdeling, dus geen budgetcode invullen
    from     temp
             left outer join tabRekeningschema on rksGid=tmpRksGid
    where    temp.tmpBudgetCode is null
    group by tmpRksGid, tmpBlGid, tmpKstpGid, tmpKstdgid;


    //Nu de periodes invullen
    if @BaserenOp = 0 then
      //Baseren op budget vorig jaar
      insert into tabbudgetBedrag(BudBedrBjGid, BudBedrPerNr, BudBedrBudgetGid, BudBedrag)
      select   @BjGid, PerNr, (select BudgetGid from tabBudget where BudBjGid=@BjGid and isnull(tmpRksGid,0)=isnull(BudRksGid,0) and isnull(tmpBlGid,0)=isnull(BudBlGid,0) and isnull(tmpKstdGid,0)=isnull(BudKstdGid,0) and isnull(tmpKstpGid,0)=isnull(BudKstpGid,0)),
               (select AfrondingOvernemenJaarbudget(isnull(sum(BudBedrag) * ((100+@PercentageBij)/100),0), @AfrondenVan)
                from   tabBudget
                       left outer join tabBudgetBedrag on (BudBedrBjGid = @BjGidVorigJaar and BudBedrPerNr=PerNr and BudBedrBudgetGid=BudgetGid)
                where  (BudBjGid = @BjGidVorigJaar and tmpVorigBudgetgid=BudgetGid)
               ) Bedrag
      from     temp, tabPeriode
      where    temp.tmpBudgetCode is null and PerBjGid=@BjGid and PerNr <> 0 // and Bedrag <> 0 (oplossing bug #9606)
      group by PerNr, tmpRksGid, tmpBlGid, tmpKstpGid, tmpKstdgid, tmpVorigBudgetgid, tmpBudgetCode, tmpRubParSub
      having   Bedrag <> 0;

      //Jaarbedrag berekenen
      update tabBudget set jaarbudget = (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid = @BjGid and BudBedrBudgetGid = BudgetGid)
      from   temp
      where  temp.tmpBudgetCode is null and isnull(tmpRksGid,0)=isnull(BudRksGid,0) and isnull(tmpBlGid,0)=isnull(BudBlGid,0) and isnull(tmpKstdGid,0)=isnull(BudKstdGid,0) and isnull(tmpKstpGid,0)=isnull(BudKstpGid,0);
    else
      //Baseren op werkelijk saldo (van de rekeningen die binnen de balanscode/kostenplaats/-drager vallen)

      insert into tabbudgetBedrag(BudBedrBjGid, BudBedrPerNr, BudBedrBudgetGid, BudBedrag)
      select   @BjGid, PerNr,
            (select BudgetGid from tabBudget where BudBjGid=@BjGid and isnull(tmpRksGid,0)=isnull(BudRksGid,0) and isnull(tmpBlGid,0)=isnull(BudBlGid,0) and isnull(tmpKstdGid,0)=isnull(BudKstdGid,0) and isnull(tmpKstpGid,0)=isnull(BudKstpGid,0)),
            (select AfrondingOvernemenJaarbudget(sum(
                        (if tempRks.DefaultBoekzijde = 3 then if tempRks.DefaultSoort in (2, 5, 7) then -1 else 1 endif else if tempRks.DefaultBoekzijde = 1 then -1 else 1 endif endif) * //ACW 22-11-2000: Rekening houden met soort rekening (debet of credit)
                        if @OvernemenVan = 0 and isnull(tempRks.RksValNummer,-1) = isnull(tempRks.RekSaldoValNummer,-1) then //Rekeningen overnemen in dezelfde valuta? Dan direct het bedrag overnemen
                          if @OvernemenSaldo=0 or tempRks.DefaultBoekzijde not in (0,1, 3) then //Baseren op werkelijke bedragen of er is geen default-zijde ingesteld
                            isnull(tempRks.SaldoDebetValuta,0)-isnull(tempRks.SaldoCreditValuta,0)     //baseren op saldo
                          else
                            if (tempRks.DefaultBoekzijde=0) or (tempRks.DefaultSoort=6) then                   //baseren op default-boekzijde
                              isnull(tempRks.SaldoDebetValuta,0)                              //Boekzijde=debet & Debiteuren
                            else
                              -isnull(tempRks.SaldoCreditValuta,0)                             //Boekzijde=credit & crediteuren
                            endif
                          endif
                        else
                          ValutaOmrekenen(@@BasisValutaNummer,
                                          if @OvernemenSaldo=0 or tempRks.DefaultBoekzijde not in (0,1, 3) then //Baseren op werkelijke bedragen of er is geen default-zijde ingesteld
                                            isnull(tempRks.SaldoDebetBasis,0)-isnull(tempRks.SaldoCreditBasis,0)     //baseren op saldo
                                          else
                                            if (tempRks.DefaultBoekzijde=0) or (tempRks.DefaultSoort=6) then                 //baseren op default-boekzijde
                                              isnull(tempRks.SaldoDebetBasis,0)                              //Boekzijde=debet & debiteuren
                                            else
                                              -isnull(tempRks.SaldoCreditBasis,0)                             //Boekzijde=credit & crediteuren
                                            endif
                                          endif,
                                          if @OvernemenVan = 0 then tempRks.RksValNummer else @@BasisValutaNummer endif,  //Rekeningen overnemen, dus in de valuta van de rekening zetten (ipv. basis)
                                          @BjGidVorigJaar,
                                          @LaatstePeriode,
                                          2)
                        endif) * ((100+@PercentageBij)/100), @AfrondenVan)
              from
                (
                    select
                        DefaultBoekzijde,
                        DefaultSoort,
                        RksValNummer,
                        RekSaldoValNummer,
                        (case @SoortBoeking
                            when 0 then SaldoDebetValutaDefinitief
                            when 1 then SaldoDebetValutaVoorlopig
                            when 2 then SaldoDebetValutaDefinitief + SaldoDebetValutaVoorlopig
                        end) as SaldoDebetValuta,
                        (case @SoortBoeking
                            when 0 then SaldoCreditValutaDefinitief
                            when 1 then SaldoCreditValutaVoorlopig
                            when 2 then SaldoCreditValutaDefinitief + SaldoCreditValutaVoorlopig
                        end) as SaldoCreditValuta,
                        (case @SoortBoeking
                            when 0 then SaldoDebetBasisDefinitief
                            when 1 then SaldoDebetBasisVoorlopig
                            when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig
                        end) as SaldoDebetBasis,
                        (case @SoortBoeking
                            when 0 then SaldoCreditBasisDefinitief
                            when 1 then SaldoCreditBasisVoorlopig
                            when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig
                        end) as SaldoCreditBasis


                    from tabRekeningSchema
                       left outer join tabRekeningsaldo      on (RksGid = RekSaldoRksGid    and RekSaldoBjGid = @BjGidVorigJaar and RekSaldoPerNr=PerNr)
                where  (@OvernemenVan = 0 and RksGid  = tmpRksGid                       ) or //Rekeningen
                       (@OvernemenVan = 1 and @BlCode =  0 and RksInvoer like tmpRubParSub+'%' ) or //Balanscodes, balanscode = 000
                       (@OvernemenVan = 1 and @BlCode <> 0 and rksgid in (select BlRksGid from tabBalansCodeRekening
                                                                          where  BlRekBlGid in (select BlGid from tabBalanscodeDetail
                                                                                                where  detailBlCode = @BlCode and RubParSub like tmpRubParSub+'%'))) or //Balanscodes, balanscode <> 000
                       (@OvernemenVan = 2 and RksKstpGid = tmpKstpGid                      ) or //Kostenplaatsen
                       (@OvernemenVan = 3 and RksKstpGid = tmpKstdGid                      )    //Kostendragers
                ) as tempRks
            ) Bedrag
      from     temp, tabPeriode
      where    temp.tmpBudgetCode is null and PerBjGid=@BjGid and PerNr <> 0 // and Bedrag <> 0 (oplossing bug #9606)
      group by PerNr, tmpRksGid, tmpBlGid, tmpKstpGid, tmpKstdgid, tmpVorigBudgetgid, tmpBudgetCode, tmpRubParSub
      having   Bedrag <> 0;

      //Jaarbedrag berekenen
      update tabBudget set jaarbudget = (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid = @BjGid and BudBedrBudgetGid = BudgetGid)
      from   temp
      where  temp.tmpBudgetCode is null and isnull(tmpRksGid,0)=isnull(BudRksGid,0) and isnull(tmpBlGid,0)=isnull(BudBlGid,0) and isnull(tmpKstdGid,0)=isnull(BudKstdGid,0) and isnull(tmpKstpGid,0)=isnull(BudKstpGid,0);
    end if;
  end if;

  //Verwijder alle budget-koppen waarvan geen enkel periodebedrag is ingevuld
  delete tabBudget where BudgetGid not in (select BudBedrBudgetGid from tabBudgetBedrag where BudBedrBjGid = @BjGid and BudBedrag <> 0) and BudBjGid = @BjGid and BudMetVerdeling = 0;

  //zet bij debiteuren/crediteuren Vergelijken op Debet/Credit-zijde indien deze staat op defaultboekzijde

  update tabbudget
  set VergelijkenMet = (if (DefaultSoort=6) then 1 else 2 endif)
  from tabBudget left outer join tabRekeningschema on (RksGid = BudRksGID)
  where  (BudRksGid is not null) and
         (BudBjGid = @@BjGid) and
        ((DefaultSoort = 6) or (DefaultSoort = 7)) and
         (VergelijkenMet = 3);

  //call TraceEind('OvernemenJaarBudgetten');


end;
//call OvernemenJaarBudgetten(2, 1, 0, '', 'z', null)


create or replace procedure OvernemenVrijeRubrieken(
in @VrSoort          smallint, // 0=FactuurNaw, 1=ReferentieNaw, 2=Project, 3=Orderkop, 4=Orderregel
in @PrimGid          integer,  // 'frGid'                           'fkGid'                  // Verwijzing in @DstTableName naar record van parent
in @SearchGid        integer,  // @ArtGid                           @NawGid                  // Verwijzing van de source object
in @BestOms          nchar(3),  // 'ART'                             'NAW'                    // Bestandsomschrijving in rav.rubr.
in @GroepId          nchar(3),  // '000'                             FonGid van FonID'D'      // GroepsID om tabVrijsRubriek te vinden
in @SubGroepId       nchar(3),  //                                                            // Altijd (?) gelijk aan de groepsID
in @DstTableName     nchar(40), // 'tabFactuurRegelVrijeRubriekArt'  'tabFactuurVrijeRubriek' // Naam van destinationtabel
in @PrimKeyFieldName nchar(20), // 'frvraFrGid'                      'fvrFkGid'               // Naam van Primary Key van @DstTableName
in @DstPreFieldName  nchar(10), // 'frvra'                           'fvr'                    // Begin van de veldnamen in de destinationtable
in @IsDemo smallint)           // 0                                 0                        // 1 = demonstratie-inhoud, 0= werkelijke inhoud vullen

begin
  declare @VeldNaam           nchar(20);
  declare @Voorloop           nchar(20);
  declare @VeldInhoudChar     nchar(255);
  declare @VeldInhoudNumeric  numeric(16,5);
  declare @VeldInhoudSelectie smallint;
  declare @VeldInhoudDate     date;
  declare @VeldInhoudTime     time;
  declare @SrcVeldNaam        nchar(30);
  declare @DstVeldNaam        nchar(30);

  declare @RubriekIngevuld    smallint;

  // *** Specifiek voor de afhandeling van tabFactuurRegelVrijeRubriekArt in een tussentabel
  declare @frvraGid           integer = null; // Gid van tabFactuurRegelVrijeRubriekArt
  declare @frvrpGid           integer = null; // Gid van tabFactuurRegelVrijeRubriekPartij
  declare @frGid              integer = null; // Gid van de factuurregel
  declare @frpsGid            integer = null; // Gid van de factuurpartijserieregel
  declare @PartijBron         smallint;       // 0 = factuurregel, 1 = factuurpartijserieregel
  // ***

  set @@ErrorTextProcedure = 'OvernemenVrijeRubrieken > ';
  //call TraceBegin(@@ErrorTextProcedure + '@VrSoort = ' + string(@VrSoort) + ', @PrimGid = ' + string(@PrimGid) + ', @SearchGid = ' + string(@SearchGid) + ', @BestOms = ' + @BestOms);

  if @DstTableName = 'tabFactuurRegelVrijeRubriekArt' then
    // NOTE @PrimGid bevat de verwijzing naar frGid in het geval van tabFactuurRegelVrijeRubriekArt
    // We zetten die op null zodat in de tabel tabFactuurRegelVrijeRubriekArt ook een null wordt ingevoegd
    // Het frGid hebben we wel nodig voor de koppeltabel, vandaar dat we deze bewaren in een andere variabele
    // Deze constructie moet buiten de loop, anders is @PrimGid null bij de tweede iteratie
    set @frGid = @PrimGid;
    set @PrimGid = null;
  end if;

  if @DstTableName = 'tabFactuurRegelVrijeRubriekPartij' then
    // NOTE @PrimGid bevat de verwijzing naar frGid OF FrpsGid in het geval van tabFactuurRegelVrijeRubriekPartij
    // We zetten die op null zodat in de tabel tabFactuurRegelVrijeRubriekPartij ook een null wordt ingevoegd
    // Het frGid OF FrpsGid hebben we wel nodig voor de koppeltabel, vandaar dat we deze bewaren in een andere variabele
    // Deze constructie moet buiten de loop, anders is @PrimGid null bij de tweede iteratie
     if @PrimKeyFieldName = 'frvrpFrGid' then
       //call Trace('VR Partij: Regel');
       set @PartijBron = 0;  // factuurregel
      set @frGid = @PrimGid;
      set @PrimGid = null;
    else
      //call Trace('VR Partij: SpecRegel');
      set @PartijBron = 1; // partijserieregel
      set @frpsGid = @PrimGid;
      set @PrimGid = null;
    end if;
  end if;

  set @voorloop = 'vr'+@BestOms + @GroepId + @SubgroepId;
  for @Cursor AS cursor_VrijeRubrieken CURSOR FOR
    select VrVeldNaam @VrVeldNaam, VrType @VeldType, VrLengte @Lengte, VrDecimalen @Decimalen, VrSjabloon @Sjabloon, VrLabel @Label, VrHint @Hint, VrVolgorde @Volgorde, VrGrpNaam @GrpNaam, VrGrpVolgorde @GrpVolgorde
    from   tabVrijeRubrieken
    left outer join tabVrijeRubriekenGroep on VrVrGrpGid = VrGrpGid
    where  VrBestandOms = @BestOms and VrGroepId = @GroepId and VrOpVerkoopDocument = 1
  for read only
  do
    set @VeldInhoudNumeric = null;
    set @VeldInhoudDate = null;
    set @VeldInhoudTime = null;
    set @VeldInhoudSelectie = null;
    set @VeldInhoudChar = null;

    case @VeldType
    when 1 then // getal
      set @Veldnaam = 'InhoudNumeric';
    when 2 then // datum
      set @VeldNaam = 'InhoudDate';
    when 3 then // tijd
      set @VeldNaam = 'InhoudTime';
    when 4 then // checkbox
      set @VeldNaam = 'InhoudSelectie';
    when 5 then // combobox
      set @VeldNaam = 'InhoudChar';
    else // 0=tekst, 6=email, 7=http:-adres, 8=bestand, 9=telefoon
      set @VeldNaam = 'InhoudChar';
    end case;
    set @SrcVeldNaam = '@Veld'          + @VeldNaam;
    set @DstVeldNaam = @DstPreFieldName + @VeldNaam;
    if @IsDemo = 0 then
      execute immediate ('Select ' + @VrVeldnaam + ' into ' + @SrcVeldNaam + ' from tab' + @voorloop + ' where '+@Voorloop+'RecordId = ' + string(@SearchGid));
    else
      set @VeldInhoudNumeric = 12345678.90;
      set @VeldInhoudDate = now();
      set @VeldInhoudTime = now();
      set @VeldInhoudSelectie = 1;
      set @VeldInhoudChar = 'Selectie';
      set @VeldInhoudChar = 'Vrije rubriek';
    end if;

    set @RubriekIngevuld = 0;
    execute immediate 'select 1 into @RubriekIngevuld where ' + @SrcVeldnaam + ' is not null or ' + string(@VeldType) + ' = 4';
    // Alleen vrije rubrieken wegschrijven die een waarde ingevuld hebben, OF een checkbox is (bug 35108)
    if @RubriekIngevuld = 1 then
      set @frvraGid = null;
      if @DstTableName = 'tabFactuurRegelVrijeRubriekArt' then
        // Controleren of er niet al een regel bestaat in tabFactuurRegelVrijeRubriekArt
        // Als bestaat dan dit record hergebruiken
        // Als niet bestaat dan alsnog invoegen tabFactuurRegelVrijeRubriekArt

        // In verband met de performance (zie #50076 Orders Afdruk voorbeeld op het scherm duurt veel te lang)
        // besloten tot een iets meer pramgatische benadering.
        // Bepaal het laats toegevoegde record met dezelfde veldnaam en waarde.
        // Kijk of de rest van de metadata overeenkomt en zo niet voeg deze alsnog toe.
        // In de praktijk blijkt dat de metadata maar zelfden wijzigt voor vrije velden en we zo dus alsnog een goede compressie verkrijgen.
        // Daarnaast is er een index toegevoegd op VrVeldNaam + frvraGid
        select first
          (if  (frvraDecimalen = @Decimalen                 or (frvraDecimalen is null      and @Decimalen is null)) and
                (frvraGrpNaam = @GrpNaam                    or (frvraGrpNaam is null        and @GrpNaam is null)) and
                (frvraGrpVolgorde = @GrpVolgorde            or (frvraGrpVolgorde is null    and @GrpVolgorde is null)) and
                (frvraHint = @Hint                          or (frvraHint is null           and @Hint is null)) and
                (frvraInhoudChar = @VeldInhoudChar          or (frvraInhoudChar is null     and @VeldInhoudChar is null)) and
                (frvraInhoudDate = @VeldInhoudDate          or (frvraInhoudDate is null     and @VeldInhoudDate is null)) and
                (frvraInhoudNumeric = @VeldInhoudNumeric    or (frvraInhoudNumeric is null  and @VeldInhoudNumeric is null)) and
                (frvraInhoudSelectie = @VeldInhoudSelectie  or (frvraInhoudSelectie is null and @VeldInhoudSelectie is null)) and
                (frvraInhoudTime = @VeldInhoudTime          or (frvraInhoudTime is null     and @VeldInhoudTime is null)) and
                (frvraLabel = @Label                        or (frvraLabel is null          and @Label is null)) and
                (frvraLengte = @lengte                      or (frvraLengte is null         and @lengte is null)) and
                (frvraSjabloon = @Sjabloon                  or (frvraSjabloon is null       and @Sjabloon is null)) and
                (frvraType = @VeldType                      or (frvraType is null           and @VeldType is null)) and
                (frvraVeldnaam = @VrVeldNaam                or (frvraVeldnaam is null       and @VrVeldNaam is null)) and
                (frvraVolgorde = @Volgorde                  or (frvraVolgorde is null       and @Volgorde is null))
          then
              frvraGid
          else
              null
          end if) into @frvraGid
        from tabFactuurRegelVrijeRubriekArt
        where
          frvraVeldnaam = @VrVeldNaam and (
            case
                when @VeldType in (0, 5, 6, 7, 8, 9) then if frvraInhoudChar = @VeldInhoudChar then 1 else 0 end if
                when @VeldType = 1 then if frvraInhoudNumeric = @VeldInhoudNumeric then 1 else 0 end if
                when @VeldType = 2 then if frvraInhoudDate = @VeldInhoudDate then 1 else 0 end if
                when @VeldType = 3 then if frvraInhoudTime = @VeldInhoudTime then 1 else 0 end if
                when @VeldType = 4 then if frvraInhoudSelectie = @VeldInhoudSelectie or (frvraInhoudSelectie is null and @VeldInhoudSelectie is null) then 1 else 0 end if
            else
                0
            end case
          ) = 1 and
          frvraFrGid is null
        order by frvraGid desc; // we pakken het laatst record obv gid
      end if;

      // Zelfde trucje voor partijen
      set @frvrpGid = null;
      if @DstTableName = 'tabFactuurRegelVrijeRubriekPartij' then
        select first
          (if  (frvrpDecimalen = @Decimalen                 or (frvrpDecimalen is null      and @Decimalen is null)) and
                (frvrpGrpNaam = @GrpNaam                    or (frvrpGrpNaam is null        and @GrpNaam is null)) and
                (frvrpGrpVolgorde = @GrpVolgorde            or (frvrpGrpVolgorde is null    and @GrpVolgorde is null)) and
                (frvrpHint = @Hint                          or (frvrpHint is null           and @Hint is null)) and
                (frvrpInhoudChar = @VeldInhoudChar          or (frvrpInhoudChar is null     and @VeldInhoudChar is null)) and
                (frvrpInhoudDate = @VeldInhoudDate          or (frvrpInhoudDate is null     and @VeldInhoudDate is null)) and
                (frvrpInhoudNumeric = @VeldInhoudNumeric    or (frvrpInhoudNumeric is null  and @VeldInhoudNumeric is null)) and
                (frvrpInhoudSelectie = @VeldInhoudSelectie  or (frvrpInhoudSelectie is null and @VeldInhoudSelectie is null)) and
                (frvrpInhoudTime = @VeldInhoudTime          or (frvrpInhoudTime is null     and @VeldInhoudTime is null)) and
                (frvrpLabel = @Label                        or (frvrpLabel is null          and @Label is null)) and
                (frvrpLengte = @lengte                      or (frvrpLengte is null         and @lengte is null)) and
                (frvrpSjabloon = @Sjabloon                  or (frvrpSjabloon is null       and @Sjabloon is null)) and
                (frvrpType = @VeldType                      or (frvrpType is null           and @VeldType is null)) and
                (frvrpVeldnaam = @VrVeldNaam                or (frvrpVeldnaam is null       and @VrVeldNaam is null)) and
                (frvrpVolgorde = @Volgorde                  or (frvrpVolgorde is null       and @Volgorde is null))
          then
              frvrpGid
          else
              null
          end if) into @frvrpGid
        from tabFactuurRegelVrijeRubriekPartij
        where
          frvrpVeldnaam = @VrVeldNaam and (
            case
                when @VeldType in (0, 5, 6, 7, 8, 9) then if frvrpInhoudChar = @VeldInhoudChar then 1 else 0 end if
                when @VeldType = 1 then if frvrpInhoudNumeric = @VeldInhoudNumeric then 1 else 0 end if
                when @VeldType = 2 then if frvrpInhoudDate = @VeldInhoudDate then 1 else 0 end if
                when @VeldType = 3 then if frvrpInhoudTime = @VeldInhoudTime then 1 else 0 end if
                when @VeldType = 4 then if frvrpInhoudSelectie = @VeldInhoudSelectie or (frvrpInhoudSelectie is null and @VeldInhoudSelectie is null) then 1 else 0 end if
            else
                0
            end case
          ) = 1 and
          frvrpFrGid is null
        order by frvrpGid desc; // we pakken het laatst record obv gid
      end if;

      //call Trace('VR @frvraGid='+string(@frvraGid)+'; @frvrpGid='+string(@frvrpGid));

      if @DstTableName = 'tabFactuurRegelVrijeRubriekArt' then
        //====== vrije rubrieken van artikelen
        if @frvraGid is null then
           //nieuw record voor nieuwe combi opslaan in tabFactuurRegelVrijeRubriekArt
           execute immediate ('insert into '+@DstTableName+'('+(if @VrSoort <> -1 then 'FvrSoort, ' endif)+@PrimKeyFieldName+', '+@DstPreFieldName+'VeldNaam, '+@DstPreFieldName+'Type, '+@DstPreFieldName+'Lengte, '+@DstPreFieldName+'Decimalen, ' + @DstVeldNaam + ', '+@DstPreFieldName+'Sjabloon, '+@DstPreFieldName+'Label, '+@DstPreFieldName+'Hint, '+@DstPreFieldName+'Volgorde, '+@DstPreFieldName+'GrpNaam, '+@DstPreFieldName+'GrpVolgorde) values ('+(if @VrSoort <> -1 then string(@VrSoort) + ', ' endif)+'@PrimGid, @VrVeldNaam , @VeldType, @Lengte, @Decimalen, ' + @SrcVeldnaam + ', @Sjabloon, @Label, @Hint, @Volgorde, @GrpNaam, @GrpVolgorde)');
           set @frvraGid = @@Identity;
        endif;
        //koppel record aanmaken
        insert into tabFactuurRegelKoppelVrijeRubriekArt (FrkvrafrGid, FrkvrafrvraGid) values (@frGid, @frvraGid);
      elseif @DstTableName = 'tabFactuurRegelVrijeRubriekPartij' then
        //====== vrije rubrieken van partijen
        if @frvrpGid is null then
           //nieuw record voor nieuwe combi opslaan in tabFactuurRegelVrijeRubriekPartij
           execute immediate ('insert into '+@DstTableName+'('+(if @VrSoort <> -1 then 'FvrSoort, ' endif)+@PrimKeyFieldName+', '+@DstPreFieldName+'VeldNaam, '+@DstPreFieldName+'Type, '+@DstPreFieldName+'Lengte, '+@DstPreFieldName+'Decimalen, ' + @DstVeldNaam + ', '+@DstPreFieldName+'Sjabloon, '+@DstPreFieldName+'Label, '+@DstPreFieldName+'Hint, '+@DstPreFieldName+'Volgorde, '+@DstPreFieldName+'GrpNaam, '+@DstPreFieldName+'GrpVolgorde) values ('+(if @VrSoort <> -1 then string(@VrSoort) + ', ' endif)+'@PrimGid, @VrVeldNaam , @VeldType, @Lengte, @Decimalen, ' + @SrcVeldnaam + ', @Sjabloon, @Label, @Hint, @Volgorde, @GrpNaam, @GrpVolgorde)');
           set @frvrpGid = @@Identity;
        endif;
        //koppel record aanmaken
        if @PartijBron = 0 then
          insert into tabFactuurRegelKoppelVrijeRubriekPartij (FrkvrpfrGid, FrkvrpfrvrpGid) values (@frGid, @frvrpGid);
        else
          insert into tabFactuurRegelKoppelVrijeRubriekPartij (FrkvrpfrpsGid, FrkvrpfrvrpGid) values (@frpsGid, @frvrpGid);
        end if;
      else
        //====== overige vrije rubrieken
        execute immediate ('insert into '+@DstTableName+'('+(if @VrSoort <> -1 then 'FvrSoort, ' endif)+@PrimKeyFieldName+', '+@DstPreFieldName+'VeldNaam, '+@DstPreFieldName+'Type, '+@DstPreFieldName+'Lengte, '+@DstPreFieldName+'Decimalen, ' + @DstVeldNaam + ', '+@DstPreFieldName+'Sjabloon, '+@DstPreFieldName+'Label, '+@DstPreFieldName+'Hint, '+@DstPreFieldName+'Volgorde, '+@DstPreFieldName+'GrpNaam, '+@DstPreFieldName+'GrpVolgorde) values ('+(if @VrSoort <> -1 then string(@VrSoort) + ', ' endif)+'@PrimGid, @VrVeldNaam , @VeldType, @Lengte, @Decimalen, ' + @SrcVeldnaam + ', @Sjabloon, @Label, @Hint, @Volgorde, @GrpNaam, @GrpVolgorde)');
      endif;

    end if;
  end for;

  set @@ErrorTextProcedure = 'OvernemenVrijeRubrieken';
  //call TraceEind(@@ErrorTextProcedure);
end;
