create or replace procedure ParagraafSoort (in @RksNummer nchar(10), in @ParSoort integer, inout @IsAkkoord integer)
begin
  declare @Paragraaf nchar(3);

  set @@ErrorTextProcedure = 'ParagraafSoort > @RksNummer='+@RksNummer+', @ParSoort='+string(@ParSoort);
  //call TraceBegin(@@ErrorTextProcedure);

  select Paragraaf into @Paragraaf
  from   tabParagraaf left outer join  tabBalansCodeDetail on (ParBlGid=BlGid)
  where ParSoort=@Parsoort;
  if left(@RksNummer,length(@Paragraaf))=@Paragraaf then
    set @IsAkkoord=1;
  else
    set @IsAkkoord=0;
  end if;

  set @@ErrorTextProcedure = 'ParagraafSoort > @IsAkkoord='+string(@IsAkkoord);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure PartijGeefOudste(
  in  @ArtGid                   integer,
  in  @MagGid                   integer,
  in  @VerkoopCheckOuderePartij integer /* 0 = productiedatum, 1 = ontvangstdatum, 2 = tht-datum */,
  out @PartijGid               integer)
begin
  select calcArtPartijGid into @PartijGid from
  (
    select first
      calcArtPartijGid,
      ArtPartijDatumProductie,
      ArtPartijDatumOntvangst,
      ArtPartijTHTDatum,

      IsNull (Sum (calcMagazijnVoorraad), 0.00)      InVoorraad,
      IsNull (Sum (calcGereserveerdBackorder), 0.00) GereserveerdBackorder,
      IsNull (Sum (calcGereserveerdLevering), 0.00)  GereserveerdLevering

    from
      vwVoorraadAantallen
      inner join tabArtikelPartij on ArtPartijGid = calcArtPartijGid
      inner join tabMagazijn      on MagGid = calcMagGid

    where
      calcArtGid = @ArtGid and
      calcMagGid = @MagGid and
      ArtPartijIsGeblokkeerdVoorVerkoop = 0 and
      (
        (@VerkoopCheckOuderePartij = 0 /* productiedatum */ and ArtPartijDatumProductie is not null) OR
        (@VerkoopCheckOuderePartij = 1 /* ontvangstdatum */ and ArtPartijDatumOntvangst is not null) OR
        (@VerkoopCheckOuderePartij = 2 /* tht-datum */      and ArtPartijTHTDatum is not null)
      )
    group by
      calcArtPartijGid,
      ArtPartijDatumProductie,
      ArtPartijDatumOntvangst,
      ArtPartijTHTDatum,
      ArtPartijNummer
    having
      (InVoorraad - GereserveerdBackorder - GereserveerdLevering) > 0
    order by
      if @VerkoopCheckOuderePartij = 0 /* productiedatum */ then ArtPartijDatumProductie endif asc,
      if @VerkoopCheckOuderePartij = 1 /* ontvangstdatum */ then ArtPartijDatumOntvangst endif asc,
      if @VerkoopCheckOuderePartij = 2 /* tht-datum      */ then ArtPartijTHTDatum endif asc,
      ArtPartijNummer asc
  ) as vw
end;

//------------------------------------------------------------------------------
//-----------------------Automatisch partijnummer genereren---------------------
//------------------------------------------------------------------------------
// genereert een nieuw partijnummer adhv instellingen bij Artikelen
create or replace procedure PartijGenereerNummer(in @ArtGid integer, in @Forceer smallint, out @Nummer nchar(20), out @NieuwVolgNr numeric(10,0), out @Status smallint)
begin
  declare @Startnummer      numeric(10,0);      // ArtPartijNrStartNummer       numeric (10,0)
  declare @NieuwNummer      nchar(20);
  declare @VolgNrUitvullen  smallint;           // ArtPartijNrVolgnrUitvullen   smallint
  declare @VolgNrLengte     integer;            // ArtPartijNrLengteVolgnr      integer
  declare @TekstVoor        nchar(10);           // ArtPartijNrTekstVoor         nchar(10)
  declare @TekstAchter      nchar(10);           // ArtPartijNrTekstAchter       nchar(10)
  declare @Genereren        smallint;           // ArtIsPartijNrGenereren       smallint
  declare @Resultaat        smallint;           // -3 = volgnummer langer dan langst mogelijke waarde (9.999.999.999)
                                                // -2 = partijnummer te lang
                                                // -1 = volgnr langer dan aantal uitvulposities
                                                //  0 = nog geen nieuw nummer
                                                //  1 = nieuw nummer

  set @@ErrorTextProcedure = 'PartijGenereerNummer > @ArtGid=' + string(@ArtGid) + ', @Forceer=' + string(@Forceer);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Nummer      = '';
  set @Resultaat   = 0;
  set @NieuwVolgNr = 0;
  set @Status      = @Resultaat;

  select ArtIsPartijNrGenereren , ArtPartijNrStartNummer, ArtPartijNrVolgnrUitvullen,
         ArtPartijNrLengteVolgnr, ArtPartijNrTekstVoor  , ArtPartijNrTekstAchter
  into   @Genereren             , @Startnummer          , @VolgNrUitvullen,
         @VolgNrLengte          , @TekstVoor            , @TekstAchter
  from   tabArtikel
  where  ArtGid = @ArtGid;

  //call Trace('@Genereren = ' + String(@Genereren) + ', @Forceer = ' + string(@Forceer) + ', @startnummer = ' + string(@startnummer) + ', @TekstVoor = ' + @TekstVoor + ', @TekstAchter = ' + @TekstAchter);
  if @Forceer = 1 then
    set @genereren = 1;
  end if;
  if @genereren = 1 then
    while @Resultaat = 0 and @Startnummer <= 9999999999 loop
      // Bepaal nieuw te gebruiken partijnummer o.b.v. @startnummer
      set @NieuwNummer = string(@Startnummer);

      // Evt. uitvullen van nummer
      if @VolgNrUitvullen = 1 then                   // uitvullen is aangevinkt.
        if Length(@NieuwNummer) > @VolgNrLengte then // als groter, dan zou er een stuk afgehakt worden bij Right().
          set @Resultaat = -1;                       // dus niet genereren, en gebruiker zelf in laten vullen.
        else
          set @NieuwNummer = Right('0000000000' + @NieuwNummer, @VolgNrLengte);
        end if;
      end if;

      if (@Resultaat = 0) and (Length(@TekstVoor + @NieuwNummer + @TekstAchter) > 20) then
        set @Resultaat = -2; // partijnummer te lang!
      else
        // lengte oke, dus geldig nummer fabriceren
        set @NieuwNummer = @TekstVoor + @NieuwNummer + @TekstAchter;
      end if;

      // Test of nieuwe partijnummer al bestaat
      if @Resultaat = 0 then
        if not exists (select 1 from tabArtikelPartij where ArtPartijArtGid = @ArtGid and ArtPartijNummer = @NieuwNummer) then
          set @Resultaat = 1;
        end if;
      end if;

      // Verhoog het startnummer
      if @Startnummer < 9999999999 then
        set @Startnummer = @Startnummer + 1;
      else
        if @Resultaat = 0 then
          set @Resultaat = -3;
        end if;
      end if;
    end loop;

    // het nieuwe nummer kan gebruikt worden. Nummer teruggeven en artikeltabel updaten met nieuwe volgnummer.
    if @Resultaat = 1 then
      //call Trace('Nieuw partijnummer: ' + @NieuwNummer);
      set @nummer = @NieuwNummer;

      if Length(@TekstVoor + string(@StartNummer) + @TekstAchter) < 21 then
        //call Trace('Updaten nieuwe startnummer: ' + string(@StartNummer));
        update tabArtikel set ArtPartijNrStartNummer = @Startnummer where ArtGid = @ArtGid;
        set @NieuwVolgNr = @Startnummer;
      end if;
    end if;
  end if;

  set @Status = @Resultaat;

  //call Trace('@Resultaat = ' + string(@Resultaat));
  //call TraceEind('PartijGenereerNummer (@Nummer = ''' + @Nummer + ''')');

end;


create or replace procedure PeriodeAantal(in @BjGid integer, inout @Aantal integer)
begin
