  //call TraceEind(@@ErrorTextProcedure);
end;


//$Workfile: PeriodeBepalen.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----------- Geef aan de hand van een meegegeven datum het periodenummer terug
if exists (select 1 from sys.sysProcedure where proc_name='PeriodeBepalen') then
  drop function PeriodeBepalen;
end if;

create function PeriodeBepalen(in @BjGid integer, in @Datum Date)
returns integer
begin
  declare @Periode integer;

  set @@ErrorTextProcedure = 'PeriodeBepalen > @Datum='+string(@Datum);
  //call TraceBegin(@@ErrorTextProcedure);

  select Pernr into @Periode from tabPeriode where @Datum between BeginDatum and EindDatum and PerBjGid = @BjGid;
  if @Periode is null then
    select 0 into @Periode from tabPeriode where @Datum < BeginDatum and PerNr=0 and PerBjGid=@BjGid;
    if @Periode is null then
      select max(PerNr) into @Periode from tabPeriode where PerBjGid=@BjGid;
    end if;
  end if;

  set @@ErrorTextProcedure = 'PeriodeBepalen';
  //call TraceEind(@@ErrorTextProcedure);
  return(@Periode)

end;


// ---------------------------------------------------------------------------------------
// ---------------- Deze bepaalt adhv instellingen de juiste rekening --------------------
// ---------------------------------------------------------------------------------------

/*
 Wat kan JournaalRegelSoort zijn:
 1 - Kostprijs
 2 - Omzetten
 3 - Kasmutaties
 4 - Afrondingsverschil
 en in combinatie met een betaalwijze (PobwNummer):
 5 - Betaling
 6 - Kluis
 7 - Kasverschil

 Je geeft de benodigde rekening mee en geeft de juiste rekening terug.
 Als er kp/kd''s nodig zijn, maakt hij zonodig de rekening eerst aan.

*/
create or replace function PosBepaalRekening(in @Werkplek nchar(20), in @JournaalRegelSoort smallint, in @RksGid integer, in @PobwNummer integer)
returns integer
begin
	declare @Uitsplitsen smallint;
	declare @Result integer;

	declare @KstpGid integer;
	declare @KstdGid integer;

  set @@ErrorTextProcedure = 'PosBepaalRekening > JRS = ' + string(@JournaalRegelSoort) + '; RksGid = ' + string(@RksGid) + '; PobwNummer='+string(@PobwNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  select PovgKstpGid, PovgKstdGid into @KstpGid, @KstdGid from tabPosVasteGegevens where PovgWerkplek = @Werkplek;

  case @JournaalRegelSoort
    when 1 then select PovgBoekingUitsplitsenKostprijs          into @Uitsplitsen from tabPosVasteGegevens where PovgWerkplek = @Werkplek;
    when 2 then select PovgBoekingUitsplitsenOmzet              into @Uitsplitsen from tabPosVasteGegevens where PovgWerkplek = @Werkplek;
    when 3 then select PovgBoekingUitsplitsenKasmutatie         into @Uitsplitsen from tabPosVasteGegevens where PovgWerkplek = @Werkplek;
    when 4 then select PovgBoekingUitsplitsenAfrondingsverschil into @Uitsplitsen from tabPosVasteGegevens where PovgWerkplek = @Werkplek;

    when 5 then select PobwBoekingUitsplitsenBetaling           into @Uitsplitsen from tabPosBetaalwijzen where PobwNummer = @PobwNummer;
    when 6 then select PobwBoekingUitsplitsenKluis              into @Uitsplitsen from tabPosBetaalwijzen where PobwNummer = @PobwNummer;
    when 7 then select PobwBoekingUitsplitsenKasverschil        into @Uitsplitsen from tabPosBetaalwijzen where PobwNummer = @PobwNummer;

    else raiserror 20323, @JournaalRegelSoort;

  end case;

  //call trace('Uitsplitsen = ' + string(@Uitsplitsen));

  case @Uitsplitsen
    when 0 then select @RksGid into @Result;
    when 1 then call ZoekOfMaakRksMetKstpKstd(@RksGid, @KstpGid, null, @Result);
    when 2 then call ZoekOfMaakRksMetKstpKstd(@RksGid, null, @KstdGid, @Result);
    when 3 then call ZoekOfMaakRksMetKstpKstd(@RksGid, @KstpGid, @KstdGid, @Result);
  end case;



  set @@ErrorTextProcedure = 'PosBepaalRekening > Result = ' + string(@Result);
  //call TraceEind(@@ErrorTextProcedure);

  return @Result;
end;


