create or replace procedure POSBonnummerUpdate(in @Werkplek nchar(20), in @PokGid integer)
begin
  declare @Klaar integer;
  declare @BonNummer numeric(10,0);

  set @@ErrorTextProcedure = 'POSBonnummerUpdate > @Werkplek='+@Werkplek+', @PokGid='+string(@PokGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Klaar = 0;
  while @Klaar = 0
  loop
   select POSGenereerBonnummer(@Werkplek) into @BonNummer;
   update tabPosKop set PokNummer = @BonNummer where PokGid = @PokGid;
   // Nu nog even testen of echt niemand anders dit nummer net in gebruik heeft genomen
   if (not exists(select 1 from tabPosKop where PokNummer = @BonNummer and PokGid <> @PokGid)) and
      (not exists(select 1 from tabPosHistorieKop where PohkNummer = @BonNummer)) then
     set @Klaar = 1
   end if;
  end loop;

  set @@ErrorTextProcedure = 'POSBonnummerUpdate > @BonNummer='+ String(@BonNummer);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure POSComprimeerBoekingsgang(in @BGGid integer, in @Werkplek nchar(20))
begin
  //@BgGid is de boekingsgang met een berg journaalposten die moeten worden gecomprimeerd.
  //We hebben deze bg reeds in gebruik.

  declare @BjGid  integer;
  declare @DgbGid integer;
  declare @JpGid  integer;
  declare @JrGid  integer;
  declare @Boekstuknummer numeric(10,0);
  declare @MaxBonNummer nchar(40);
  declare @MinBonNummer nchar(40);
  declare @MaxFactuurDatum date;

  declare @DCVNawGid integer; //Debiteur contante verkopen nawgid
  declare @DCVRksGid integer; //Debiteur contante verkopen rksgid
  declare @KBRksGid integer;  //Kasbetalingen rksgid
  declare @KBSaldoDebet numeric(15,3);
  declare @KBSaldoCredit numeric(15,3);

  declare @PosBereikTekst long nvarchar;

  set @PosBereikTekst = _A('POS-CV: bon %1! t/m %2!');

  //call TraceBegin('POSComprimeerBoekingsgang > @BGGid = ' + string(@BGGid));

  //Vve 4-11-2004: Vanwege lastige deadlock problemen, is besloten deze proc te serialiseren; maw: Er mag maar 1 taak tegelijk deze proc uitvoeren.
  call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'POSComprimeerBoekingsgang', '');



  select BoekGangBjGID into @BjGid from tabBoekingsgang where BoekgangGid = @BgGid;
  select povgDgbgid, povgDefNawGid into @DgbGid, @DCVNawGid from tabPOSVasteGegevens where povgWerkplek = @Werkplek;
  select NawFilRksGID into @DCVRksGid from tabNawFile where NawFilNawGid = @DCVNawGid;
  select pobwRksGid into @KBRksGid from tabPosBetaalwijzen where PobwIsKasRekening = 1;

  //call trace('POSComprimeerBoekingsgang > Hoogste en laagste bonnummer opzoeken');
  //let op: JrReferentie is een nchar(40) veld en hier geen Min/Max op plaatsvinden.
  // Het veld wordt ook niet meer uitgevuld met spaties in de triggers, dus een andere oplossing is nodig.
  set @MaxBonNummer = (
    select first jrReferentie
    from tabJournaalRegel
    inner join tabJournaalPost on jpgid = jrjpgid
    where JpBoekGangGID = @BgGid and JrRksGid=@DCVRksGid
    order by jrReferentie_Lengte desc, jrReferentie desc);

   set @MinBonNummer = (
    select first jrReferentie
    from tabJournaalRegel
    inner join tabJournaalPost on jpgid = jrjpgid
    where JpBoekGangGID = @BgGid and JrRksGid=@DCVRksGid
    order by jrReferentie_Lengte, jrReferentie);

   set @MaxFactuurDatum = (
    select max(JrFactuurdatum)
    from tabJournaalRegel
    inner join tabJournaalPost on jpgid = jrjpgid
    where JpBoekGangGID = @BgGid and JrRksGid=@DCVRksGid);

  //Als er helemaal geen boekingen zijn op de DVC hoeven we niets te comprimeren.
  if @MaxBonNummer is not null then

    //call trace('POSComprimeerBoekingsgang > Boekingen: Nieuwe journaalpost aanmaken');

    //Nieuw boekstuknummer nodig
    call BoekstuknummerGenereren(@BjGid, @DgbGid, @BoekStukNummer);
    insert into tabJournaalpost
      (Boekdatum, BoekstukNummer, JpBoekgangGid, JpDgbGid, JpIsInGebruik, OmsJournaalPost)
    select
       @MaxFactuurDatum, @BoekStukNummer, @BGGid, @DgbGid, 1, _A('POS-Gecomprimeerde journaalpost');
    set @JpGid = @@Identity;

    //Eerste zoeken we alle journaalposten waar de DebiteurContanteVerkopen in staat.
    //Dan pakken we alle regels die in die journaalposten staan, zonder de CJP-regels (Soort=0).
    //Dan gaan we alle bedragen (hoofd en hulp) bij elkaar optellen,
    //  en groupby-en we op Rekening, BTWcode en Debet/Credit.
    //Tevens voor de DCV regels een Factuurnummer en Factuurdatum teruggeven.
    // SorteerWaarde is ervoor om de Debiteurregels bovenin te krijgen (staat mooier volgens sommigen...)
    FOR @Cursor AS CURSOR_PosBonRegels CURSOR FOR
      select
        JrRksGid @JrRksGid, IsCreditBoeking @IsCreditBoeking,
        sum(JrValutaBedrag) @TotaalBedrag,
        HulpRekRksGid @HulpRekRksGid, HulpRekBtwCode @HulpRekBtwCode, HulpRekIsCredit @HulpRekIsCredit,
        sum(HulpRekValutaBedrag) @TotaalHulpBedrag,
        _P(@PosBereikTekst, @MinBonNummer, @MaxBonNummer) @JrOmschrijving,
        (if JrRksGid=@DCVRksGid then @MaxBonNummer else min(if ReferentieVerplicht= 1 then JrReferentie else null endif) endif) @Factuurnummer,
        (if JrRksGid=@DCVRksGid then @MaxFactuurDatum else null endif) @FactuurDatum,
        (if DefaultSoort=6 then 1 else 10 endif) SorteerWaarde
      from tabJournaalRegel
      inner join tabRekeningschema on (RksGid = JrRksGid)
      left outer join tabHulpRekening on HulpRekJrGid = JrGid
      where JrJpGid in
       (select JpGid
          from tabJournaalRegel inner join tabJournaalPost on jpgid = jrjpgid
         where JpBoekGangGID = @BgGid and JrRksGid= @DCVRksGid)
      and SoortBoeking=0
      group by
       JrRksGid, JrRksInvoer, IsCreditBoeking,
       HulpRekRksGid, HulpRekBtwCode, HulpRekIsCredit, SorteerWaarde
      order by SorteerWaarde, JrRksInvoer, IsCreditBoeking
    for read only
    DO
      //call trace('POSComprimeerBoekingsgang: Regel maken. JrRksGid='+String(@JrRksGid)+'; IsCredit='+string(@IsCreditBoeking)+'; Bedrag='+String(@TotaalBedrag)+'; Omschrijving='+string(@JrOmschrijving));

      insert into tabJournaalRegel
        (JrJpGID, JrRksGid, OmsJournaalRegel, JrReferentie,
         JrFactuurDatum, JrVervalDatum, JrBetalingskenmerk,
         IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
      select
         @JpGid, @JrRksGid, @JrOmschrijving,
         @Factuurnummer, @FactuurDatum, @FactuurDatum, '',
         @IsCreditBoeking, @@BasisValutaNummer, @TotaalBedrag, @TotaalBedrag;
      set @JrGid = @@Identity;

      //kijken of er ook een hulprekening gemaakt moet worden.
      if not @HulpRekRksGid is null then
        //call trace('POSComprimeerBoekingsgang > Hulpregel maken: HulpRekRksGid='+String(@HulpRekRksGid)+'; HulpRekIsCredit='+string(@HulpRekIsCredit)+'HulpRekBtwCode='+String(@HulpRekBtwCode)+'TotaalHulpBedrag='+String(@TotaalHulpBedrag));

        insert into tabHulprekening
          (hulprekJrGid, hulprekBasisBedrag, hulprekValutaBedrag, hulprekValnummer, hulprekSoort, hulprekIsCredit, hulprekRksgid, HulprekBtwCode)
        values (@JrGid, @TotaalHulpBedrag, @TotaalHulpBedrag, @@BasisValutaNummer, 1, @HulpRekIsCredit, @HulpRekRksGid, @HulpRekBtwCode);

      end if;
    END FOR;


    //Nu hebben we een nieuwe jp. Alle oude journaalposten moeten we nu weggooien.
    //Daarvoor moeten we ze eerst in gebruik nemen. NIET de nieuwe ook weggooien natuurlijk!
    //call trace('POSComprimeerBoekingsgang > Oude regels in gebruik nemen');
    update tabJournaalPost set JpIsInGebruik = 1
    where JpGid in
       (select JpGid
          from tabJournaalRegel inner join tabJournaalPost on jpgid = jrjpgid
         where JpBoekGangGID = @BgGid and JrRksGid= @DCVRksGid and JpGid <> @JpGid);

    //25-11-2003 Nieuw Vve: Er is nu ook een link met tabvoorraadmutatie. Daar staat een verwijzing naar de orignele jpgidjes.
    //                      Die updaten we nu naar de nieuwe gecomprimeerde journaalpost.
    //call trace('POSComprimeerBoekingsgang > JpGidjes in tabVoorraadMutatie updaten');
    set @@VoorraadMutatieChangeAllowed = 1;
    update tabVoorraadMutatie
    set vrdMutJpGid = @JpGid
    where vrdMutJpGid in
       (select JpGid
          from tabJournaalRegel inner join tabJournaalPost on jpgid = jrjpgid
         where JpBoekGangGID = @BgGid and JrRksGid= @DCVRksGid and JpGid <> @JpGid);
    set @@VoorraadMutatieChangeAllowed = 0;

    //call trace('POSComprimeerBoekingsgang > Oude regels verwijderen');
    delete tabJournaalPost
    where JpGid in
       (select JpGid
          from tabJournaalRegel inner join tabJournaalPost on jpgid = jrjpgid
         where JpBoekGangGID = @BgGid and JrRksGid= @DCVRksGid and JpGid <> @JpGid);

    //Kas rekening salderen onderdeel.
    //We willen altijd 1 regel overhouden met 1 positief bedrag (dat kan dus debet of credit staan).
    //call trace('POSComprimeerBoekingsgang: Kasrekening salderen');

    select JrValutaBedrag into @KBSaldoDebet from tabJournaalRegel where JrJpGid = @JpGid and JrRksGid = @KBRksGid and IsCreditBoeking = 0;
    select JrValutaBedrag into @KBSaldoCredit from tabJournaalRegel where JrJpGid = @JpGid and JrRksGid = @KBRksGid and IsCreditBoeking = 1;
    //call trace('POSComprimeerBoekingsgang > Saldi: KBSaldoDebet='+String(@KBSaldoDebet)+'; KBSaldoCredit='+String(@KBSaldoCredit));

    //Als ze allebei NULL zijn is er niets met de kas gebeurt. Hoeven we ook niets te doen
    if ((@KBSaldoDebet is null) and (@KBSaldoCredit is null)) then

    else
      //Als 1 van deze Saldi NULL is en de ander is positief of 0 dan hoeven we niks te doen
      if ( (@KBSaldoDebet is null) and (@KBSaldoCredit >= 0)) or  ( (@KBSaldoDebet >= 0) and (@KBSaldoCredit is null)) then

      else
        //Als ze allebei ongelijk null zijn gaan we ze samenvoegen tot 1 positieve regel.
        if (@KBSaldoDebet is not null) and (@KBSaldoCredit is not null) then
          //Als debet groter is aan credit trekken we het credit bedrag van de debet regel af.
          if @KBSaldoDebet > @KBSaldoCredit then

            //call trace('POSComprimeerBoekingsgang > Debetregel verlagen met creditbedrag');
            update tabJournaalRegel
               set JrValutaBedrag = @KBSaldoDebet - @KBSaldoCredit,
                   JrBasisBedrag  = @KBSaldoDebet - @KBSaldoCredit
             where JrJpGid = @JpGid and JrRksGid = @KBRksGid and IsCreditBoeking = 0;
            //dan kan de creditregel weg
            //call trace('POSComprimeerBoekingsgang > Creditregel weg');
            delete tabJournaalRegel
             where JrJpGid = @JpGid and JrRksGid = @KBRksGid and IsCreditBoeking = 1;

          else  //Credit is groter dan debet; dan trekken we debetbedrag van de creditregel af
            if @KBSaldoDebet < @KBSaldoCredit then

              //call trace('POSComprimeerBoekingsgang > Creditregel verlagen met debetbedrag');
              update tabJournaalRegel
                 set JrValutaBedrag = @KBSaldoCredit-@KBSaldoDebet,
                     JrBasisBedrag  = @KBSaldoCredit-@KBSaldoDebet
               where JrJpGid = @JpGid and JrRksGid = @KBRksGid and IsCreditBoeking = 1;
              //dan kan de debetregel weg
              //call trace('POSComprimeerBoekingsgang > Debetregel weg');
              delete tabJournaalRegel
               where JrJpGid = @JpGid and JrRksGid = @KBRksGid and IsCreditBoeking = 0;

            else //als debet precies gelijk is aan credit vallen ze tegen elkaar weg en kunnen beide regels weg

              //call trace('POSComprimeerBoekingsgang: Debet=credit dus beide regels weg');
              delete tabJournaalRegel
               where JrJpGid = @JpGid and JrRksGid = @KBRksGid;

            end if;

          end if;

        else //Nu is 1 van de 2 dus NULL en de ander is negatief. Dan draaien we die regel om maw debet<->credit en plus<->min.

          if @KBSaldoDebet < 0 then

            //call trace('POSComprimeerBoekingsgang > Debetregelmin wordt creditregelplus');
            update tabJournaalRegel
               set JrValutaBedrag = -JrValutaBedrag,
                   JrBasisBedrag  = -JrBasisBedrag,
                   IsCreditBoeking = 1
             where JrJpGid = @JpGid and JrRksGid = @KBRksGid and IsCreditBoeking = 0;

          else //anders is het dus de creditregel

            //call trace('POSComprimeerBoekingsgang > Creditregelmin wordt debetregelplus');
            update tabJournaalRegel
               set JrValutaBedrag = -JrValutaBedrag,
                   JrBasisBedrag  = -JrBasisBedrag,
                   IsCreditBoeking = 0
             where JrJpGid = @JpGid and JrRksGid = @KBRksGid and IsCreditBoeking = 1;

          end if;

        end if;
      end if;
    end if;
  end if;

  //call traceBegin('POSComprimeerBoekingsgang > Lock vrijgeven');
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'POSComprimeerBoekingsgang', '');

  //call Trace('POSComprimeerBoekingsgang');
end;


create or replace function POSGenereerBonnummer(in @Werkplek nchar(20))
returns numeric(10,0)
begin
  declare @Klaar smallint;
  declare @Bonnummer numeric(10,0);

  set @@ErrorTextProcedure = 'POSGenereerBonnummer: @Werkplek='+@Werkplek;
  //call TraceBegin(@@ErrorTextProcedure);

  set @Klaar = 0;

  select povgBonStartnummer into @Bonnummer from tabPosVasteGegevens where povgWerkplek = @Werkplek;

  while @Klaar = 0
  loop
    //call Trace('POSGenereerBonnummer; Loop; @Werkplek='+@Werkplek+'; Bonnummer='+string(@Bonnummer));
    if exists(select 1 from tabPosKop where PokNummer = @BonNummer) or exists(select 1 from tabPosHistorieKop where PohkNummer = @BonNummer) then
      set @BonNummer = @BonNummer + 1;
    else
      set @Klaar = 1;
    end if;
  end loop;

  update tabPosVasteGegevens set povgBonStartNummer = @BonNummer+1 where povgWerkplek = @Werkplek;

  set @@ErrorTextProcedure = 'POSGenereerBonnummer: @Werkplek='+@Werkplek+'; @Bonnummer='+String(@Bonnummer);
  //call TraceEind(@@ErrorTextProcedure);

  return(@Bonnummer);

end;


create or replace function POSMaakNieuweBon(in @Werkplek nchar(20), in @VtgCode integer)
returns integer //geeft meteen PokGid terug
begin
  declare @PokGid integer;

  set @@ErrorTextProcedure = 'POSMaakNieuweBon > @Werkplek='+@Werkplek+', @VtgCode='+string(@VtgCode);
  //call TraceBegin(@@ErrorTextProcedure);

  insert into tabPosKop (PokDatumTijd, PokNawGid, PokVtgCode, PokWerkplek, PokIsInclBtw)
              select  (@@Verwerkingsdatum + cast(now() as time)), PovgDefNawGid, @VtgCode, @Werkplek,
              if PovgBtwBerekening in (0,1) then
                PovgBtwBerekening
              else
                if PovgDefNawGid is not null then
                  (select NawFacturerenInclBtw from tabNaw where NawGid = PovgDefNawGid)
                else
                  1
                endif
              endif
              from tabPosVasteGegevens where PovgWerkplek = @Werkplek;
  set @PokGid = @@Identity;
  set @@ErrorTextProcedure = 'POSMaakNieuweBon > PokGid='+ String(@PokGid);
  //call TraceEind(@@ErrorTextProcedure);

  return(@PokGid);
end;


create or replace procedure POSPlaatsBonInHistorie(
    in @PokGid              integer,
    in @TotaalBedrag        numeric(15,3),
    in @TotaalBedragExclBtw numeric(15,3),
    in @BetaaldBedrag       numeric(15,3),
    in @WisselGeld          numeric(15,3),
    out @PohkGid            integer)
begin
  declare @AdrGid integer;

  set @@ErrorTextProcedure = 'POSPlaatsBonInHistorie > @PokGid='+string(@PokGid);
  //call traceBegin(@@ErrorTextProcedure);

  //#11865, Vve 4-11-2004: Als er iets fout gaat bij verwerkenbon, dan staat er al een bon in de historie.
  //                       Mensen probeerden dan opnieuw te verwerken en dan kreeg je "IGV: Index not unique."
  //                       Nu gooien we die oude bon eruit en voegen we deze opnieuw toe.

  delete tabPosHistorieKop where pohkNummer = (select pokNummer from tabPosKop where pokgid = @PokGid);

  select (if NawFactuurAdres = 1 then NawGidVestiging else NawGidCorrespondentie endif) into @AdrGid
  from tabPosKop left outer join tabNaw on NawGid = PokNawGid where PokGid = @PokGid;

  //call trace('Kop aanmaken');
  insert into tabPosHistorieKop
   (pohkNummer, pohkWerkplek, pohkDatumTijd, pohkKorting,
    pohkNawNaam1, pohkNawNaam2, pohkNawNummer, pohkNawZoekcode, PohkNawBTWNummer,
    PohkAdrEmail, PohkAdrHuisnummer, PohkAdrLandCode, PohkAdrLandOms, PohkAdrPlaats, PohkAdrPostcode, PohkAdrStraat, PohkAdrTelefax, PohkAdrTelefoon,
    PohkBtcNummer, PohkBtcSoort,
    PohkBtcTekst, PohkBtcExtraTekst,
    PohkVervalDatum,
    pohkVtgCode, pohkVtgGebruikerscode, pohkVtgNaam,
    pohkTotaalBedrag, PohkTotaalBedragExclBtw, pohkBetaaldBedrag, pohkWisselgeld,PohkAfrondingsVerschil, PohkIsInclBtw,
    pohkKstpCode,
    pohkKstpnaam,
    pohkKstdCode,
    pohkKstdNaam)
  select
    pokNummer, pokWerkplek, pokDatumTijd, pokKorting,
    AdrNaam1, AdrNaam2, NawFilNummer, NawFilZoekcode, NawBTWNummer,
    AdrEmail, AdrHuisnummer, LndEigenCode, LndOms, AdrPlaats, AdrPostcode, AdrStraat, AdrTelefax, AdrTelefoon,
    BtcNummer, SoortFactuurBtc,
    //evt kan Vervaldatum vantevoren worden uitgerekend... maar is niet zo''n complexe functie dus laat maar zo.
    LeesBtcFactuurTekst(BtcNummer, NawTaalGid, @@BasisValutaNummer, @@VerwerkingsDatum, 0),
    LeesBtcExtraTekst  (BtcNummer, NawTaalGid, @@BasisValutaNummer, @@VerwerkingsDatum, 0),
    FuncVervalDatumFactuurMetRksGid(@@VerwerkingsDatum, NawFilRksGid),
    PokVtgCode, @@Gebruikercode, RelVolledigeNaam,
    @TotaalBedrag, @TotaalBedragExclBtw, @BetaaldBedrag, @WisselGeld,PokAfrondingsVerschil, PokIsInclBtw,
    IsNull((select KstpCode from tabPosVasteGegevens left outer join tabKostenplaats on povgKstpGid = KstpGid where povgWerkplek = PokWerkplek), ''),
    IsNull((select KstpNaam from tabPosVasteGegevens left outer join tabKostenplaats on povgKstpGid = KstpGid where povgWerkplek = PokWerkplek), ''),
    IsNull((select KstdCode from tabPosVasteGegevens left outer join tabKostendrager on povgKstdGid = KstdGid where povgWerkplek = PokWerkplek), ''),
    IsNull((select KstdNaam from tabPosVasteGegevens left outer join tabKostendrager on povgKstdGid = KstdGid where povgWerkplek = PokWerkplek), '')
  from tabPosKop
  left outer join (tabNaw
                   inner join tabNawFile on (NawFilNawGid = NawGid)
                  ) on NawGid = PokNawGid
  left outer join tabBetalingsconditie on BtcNummer = NawFilBtcNummer
  left outer join tabRelatie on RelVtgCode = PokVtgCode
  left outer join tabAdres on AdrGid = @AdrGid
  left outer join tabLand on LndGid = AdrLndGid
  left outer join tabVertegenwoordiger on Vtgcode = PokVtgCode
  where PokGid = @PokGid;

  set @PohkGid = @@Identity;

  //call trace('Regels aanmaken');
  insert into tabPosHistorieRegel
   (pohrpohkGid,
    pohrRegelSoort, pohrAantalBesteld, pohrArtAantDecAantallen, pohrArtAantDecPrijzen,
    pohrArtCode, PohrArtEanCode, pohrArtOmschrijving, pohrArtOmsEenheid, pohrTekst,
    pohrArtOpbrGrpNummer, pohrArtOpbrGrpOmschrijving, pohrArtZoekcode, pohrBtwCode,
    pohrIsKortingsPercentage, pohrKorting, pohrPrijsPer, pohrVerkoopprijs,
    pohrRegelTotaal, pohrPartijNummer, pohrPartijOmschrijving, pohrSerieNummer,
    PohrBtwPercentage, pohrRegelnr, pohrIsAantallen,
    PohrAantalBesteldVrrdEenh, PohrVerkoopeenheidnaam, PohrVkeFactor, PohrVkeStandVoorEenheidVanPrijzen, PohrVkeIsDeVoorraadeenheid)
  select
    @pohkGid,
    porRegelSoort, porAantalBesteld, porAantDecAantallen, porAantDecPrijzen,
    IsNull(ArtCode, PorFactuurnummer), ArtEanCode, ArtOms, ArtOmsEenheid, porTekst,
    OpbrGrpNummer, OpbrGrpOms, ArtZoekcode, PorBtwCode,
    porIsKortingsPercentage, porKorting, ArtPrijsPer, porVerkoopprijs,
    porRegelTotaal, ArtPartijNummer, ArtPartijOms, ArtSerienummer,
    BTWPercentage, porRegelNr, porIsAantallen,
    PorAantalBesteldVrrdEenh, VkeVerkoopEenheid, PorVkeFactor, PorVkeStandVoorEenheidVanPrijzen, VkeIsVoorraadEenheid
  from tabPosRegel
  left outer join tabArtikel on ArtGid = porArtGid
  left outer join tabArtikelEAN on ArtEanArtGid = porArtGid and ArtEanIsDefault = 1
  left outer join tabBTW on PorBtwCode = BTWCode
  left outer join tabOpbrengstgroep on ArtOpbrGrpGid = OpbrGrpGid
  left outer join tabArtikelPartij on PorArtPartijGid = ArtPartijGid
  left outer join tabArtikelSerieNummer on PorArtSerieGid = ArtSerieGid
  left outer join tabVerkoopEenheid on VkeGid = PorVkeGid
  where porpokGid = @PokGid;

  //call trace('Afrekening aanmaken');
  insert into tabPosHistorieAfrekening
   (pohapohkGid,
    pohaBedragBetaald, pohaPobwNummer, pohaPobwZoekcode, pohaPobwOmschrijving, PohaPinEJournal, PohaPinTicketPrint, PohaPinTicketPrintMerchant,
    PohaPinReceiptCopies, PohaPinRequestIdentification, PohaPinRequestMerchantSignature, PohaPinRequestSignature)
  select
    @pohkGid,
    poaBedragBetaald, poaPobwNummer, PobwZoekcode, pobwOmschrijving, PoaPinEJournal, PoaPinTicketPrint, PoaPinTicketPrintMerchant,
    PoaPinReceiptCopies, PoaPinRequestIdentification, PoaPinRequestMerchantSignature, PoaPinRequestSignature
  from tabPosAfrekening
  left outer join tabPosBetaalwijzen on pobwNummer = poaPobwNummer
  where poapokGid = @PokGid;

  set @@ErrorTextProcedure = 'POSPlaatsBonInHistorie';
  //call traceEind(@@ErrorTextProcedure);
end;

create or replace procedure PostCodeFormatLandCode(in @LandCode nchar(3), out @Masker nchar(20))
begin
  set @@ErrorTextProcedure = 'PostCodeFormatLandCode > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @LandCode = ' + @LandCode);

  if isnull(@landCode,'')='' then
    //Eigen land gebruiken
    select lndPostcodeMasker into @masker from tabLand inner join tabVasteGegevens on ( lndgid = DefaultLndGid );
  else
    select lndPostcodeMasker into @masker from tabLand where LndEigenCode = @landCode;
  end if;

  set @@ErrorTextProcedure = 'PostCodeFormatLandCode';
  //call TraceEind(@@ErrorTextProcedure + ' > @Masker = ' + @Masker);
end;


//Verwerkt een afroming of bijvulling van een geldlade.
//Je moet een journaalpost meegeven die al ingebruik is.
//Hij haalt de verkoper op via de current gebruiker. In het programma wordt gecontroleerd of dit het geval is.
create or replace procedure POSVerwerkAfroming(in @JpGid integer, in @Werkplek nchar(20), in @VtgCode integer, @AfromenOfBijvullen smallint, @Betaalwijze integer, @Bedrag numeric(15,2))
begin
  declare @BetaalwijzeRksGid     integer;
  declare @KluisRksGid           integer;
  declare @Omschrijving          nchar(40);
  declare @Boekstuknummer        numeric(10,0);

  set @@ErrorTextProcedure = 'POSVerwerkAfroming > @BgGid='+string(@JpGid);
  //call traceBegin(@@ErrorTextProcedure);

  select PosBepaalRekening(@Werkplek, 5, pobwRksGid,      pobwNummer),   //betalingsrekening
         PosBepaalRekening(@Werkplek, 6, PobwRksGIDKluis, pobwNummer)    //kluisrekening
   into @BetaalwijzeRksGid, @KluisRksGid
   from tabPosBetaalwijzen where PobwNummer = @Betaalwijze;

  //boekstuknummer en omschrijving vd journaalpost overnemen naar kasmutatiehistorie
  select BoekstukNummer, OmsJournaalPost into @Boekstuknummer, @Omschrijving from tabjournaalpost where jpgid = @JpGid;

  set @@ErrorTextProcedure = 'POSVerwerkAfroming: record in kasmutatiehistorie aanmaken';
  //call trace(@@ErrorTextProcedure);
  insert into tabPosHistorieKasmutatie (PhkmBedrag, PhkmMutatieSoort, PhkmOmschrijving, PhkmPobwNummer, PhkmStuknummer, PhkmTegenpartij, PhkmVtgCode, PhkmWerkplek)
                                values (@Bedrag,    @AfromenOfBijvullen, @Omschrijving, @Betaalwijze,  @Boekstuknummer, 1,               @VtgCode, @Werkplek);


  set @@ErrorTextProcedure = 'POSVerwerkAfroming: Journaal regels aanmaken';
  //call trace(@@ErrorTextProcedure);

  insert into tabJournaalRegel (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
                      select   @JpGid, @KluisRksGid, @Omschrijving, @AfromenOfBijvullen, @@BasisValutaNummer, @Bedrag, @Bedrag;

  insert into tabJournaalRegel(JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
                      select   @JpGid, @BetaalwijzeRksGid, @Omschrijving, abs(@AfromenOfBijvullen-1), @@BasisValutaNummer, @Bedrag, @Bedrag;

  set @@ErrorTextProcedure = 'POSVerwerkAfroming: The end';
  //call traceEind(@@ErrorTextProcedure);

end;


create or replace procedure POSVerwerkBon(in @BGGid integer, in @PokGid integer, in @Werkplek nchar(20))
begin
  //POSVerwerkBon
  //Maakt boekingen van bon. Maakt omzet aan. Maakt voorraadmutaties aan.
  // BGGid  is de boekingsgang waarin de journaalposten moeten komen. Deze is in King al aangemaakt en in gebruik.
  // pokGid is de  bon waar het allemaal om draait.
  // Werkplek moet meegegeven worden om te bepalen welke vaste gegevens gelden.
  //Hoofdgegevens
  declare @BjGid                        integer;
  declare @DgbGid                       integer;
  declare @JpGid                        integer;
  declare @JrGid                        integer;
  declare @PokNummer                    integer;
  declare @NawGid                       integer;
  declare @NawFilNummer                 nchar(10);
  declare @NawRksGid                    integer;
  declare @PokDatumTijd                 timestamp;
  declare @VtgCode                      integer;
  declare @WisselGeldRksGid             integer;
  declare @Boekstuknummer               numeric(10,0);
  //vaste gegevens wegens voorraad en derlijke.
  declare @PovgMagGid                   integer;
  declare @DefaultLocatie               integer;

  //afronding
  declare @PovgAfrondenBontotaal        smallint;
  declare @PovgRksGIDAfrondingsVerschil integer;
  declare @AfrondingsVerschil           numeric(15,3);
  declare @tmpAfrondingsVerschil        numeric(15,3);
  declare @AfrondingsBoekZijde          integer;


  //Variabelen die bij meerdere boekingsregels worden gebruikt
  declare @VervalDatum             date;
  declare @Betalingskenmerk        nchar(24);

  //variabelen voor de btw-boekingen
  declare @BTWCode                 integer;
  declare @BTWRksGid               integer;
  declare @TotaalVerkochtPerBTW    numeric(15,2);
  declare @TotaalBTW               numeric(15,2);

  //variabelen voor de osp-regels
  declare @PorFactuurnummer        nchar(40);
  declare @PorTekst                nchar(40);
  declare @PorVerkoopPrijs     numeric(15,3);
  declare @OspFactuurDatum         date;
  declare @OspVervalDatum          date;
  declare @OspBetalingskenmerk     nchar(24);
  declare @MaxRegelSoort           integer;
  declare @TotaalAanOspBetalingen  numeric(15,3);

  //variabelen voor de opbrengstgroep-boekingen.
  declare @OpbrGrpGid              integer;
  declare @GroepTotaalBedrag       numeric(15,3);
  declare @OpbrGrpRksGid           integer;
  declare @KortingGrpRksGid        integer;
  declare @RegelkortingApart       smallint;
  declare @GroepsKorting           numeric(15,3);

  //variabelen voor de betalingen boekingen
  declare @PobwNummer              integer;
  declare @PobwRksGid              integer;
  declare @ReferentieVerplicht     integer;
  declare @BetaalwijzeBedrag       numeric(15,3);
  declare @TotaalContantBetaald    numeric(15,3);
  declare @TotaalOpRekeningBetaald numeric(15,3);
  declare @BonTotaal               numeric(15,3);
  declare @OSPAfboeken             numeric(15,3);
  declare @WisselGeld              numeric(15,3);

  //variabelen voor de correctieboekingen tgv afrondingsverschillen
  declare @DebetSaldo              numeric(15,2);
  declare @CreditSaldo             numeric(15,2);
  declare @HoogsteOpbrBedrag       numeric(15,3);
  //ACW 06-04-2011 Bug #33502: NIET meer grootboekrekeningnummer van de hoogste boeking onthouden, maar de journaalregel, zodat alleen die wordt geupdate bij een afrondingsverschil
  declare @HoogsteJrGid            integer;
  declare @VrdMutGid               integer;

  //variabelen voor de omzet
  declare @OmzAantal  numeric(15,3);
  declare @ArtGid     integer;
  declare @ArtSoort   smallint;
  declare @Omzet      numeric(15,3);
  declare @Marge      numeric(15,3);


  //Cursors gebruiken om door de regels te loopen.

  declare cursor_BTWBoekingen dynamic scroll cursor for
    //Alle verschillende btws pakken. Per btw het regeltotaal uitrekenen inclusief btw.
    //Daarna uitrekenen hoeveel btw hierover is betaald.
    //Geen nulboekingen maken dus testen op 0.
    select PorBtwCode, BtwRksGid,
           if PokIsInclBtw = 0 then sum(PorRegelTotaal) * ((100+BTWPercentage) / 100)  else sum(PorRegelTotaal) endif TotaalVerkochtPerBTW,
           TotaalVerkochtPerBTW * BTWPercentage/(100+BTWPercentage) TotaalBTW
    from  tabPosKop
    inner join tabPosRegel on (PorPokGid = PokGid and PorRegelSoort in (1,2))
    inner join tabArtikel on (ArtGid = PorArtGid)
    left outer join tabBtw on (PorBTWCode = BTWCode)
    where PokGid = @PokGid
    group by PokIsInclBtw, PorBtwCode, BtwRksGid, BTWPercentage
    having (IsNull(TotaalVerkochtPerBtw,0)<>0 or IsNull(TotaalBTW,0)<>0)
    order by PorBtwCode
  for read only;

  declare cursor_Opbrengsten dynamic scroll cursor for
    //Alle verschillende opbrengstgroepen pakken. Per groep de omzet optellen. Minus Regelkortingen. Met prijzen EXCL BTW.
    //Geen nulboekingen maken.
    //- De volgende berekening is onjuist: 100/119 * RegelTotaal. Hierdoor krijgen we afrondingsverschillen
    //  Daarom nu omslachtiger: Regeltotaal - Afronden( (19/119 * Regeltotaal)). Dus eerst btw uitrekenen en dat van het totaal AFTREKKEN.
    //- Nee, er kunnen nog steeds afrondingsverschillen ontstaan. Het probleem zit hem gewoon in het feit dat je op verschillende manieren
    //  optelt en vermenigvuldigt.
    //  Enige oplossing: achteraf zelf correctie plegen.
    //  Nu dus weer teruggezet naar 100/119*Regeltotaal (zo doet facturatie het ook in FacturerenBerekenOpbrengst.
    select OpbrGrpGid,
           if PokIsInclBtw = 0 then sum(PorRegelTotaal) else sum( (100 * PorRegelTotaal) / (100+BTWPercentage) ) endif GroepTotaal,
           if PokIsInclBtw = 0 then
             sum(if PorIsKortingsPercentage = 0 then //bedrag
                   PorKorting
                 else  //percentage
                   PorAantalBesteld * (PorVerkoopprijs/ArtPrijsPer)* (PorKorting/100)
                 endif)
           else
             sum(if PorIsKortingsPercentage = 0 then //bedrag
                   (100 * PorKorting) / (100+BTWPercentage)
                 else  //percentage
                   100 * (PorAantalBesteld * (PorVerkoopprijs/ArtPrijsPer)* (PorKorting/100)) / (100+BTWPercentage)
                 endif)
           endif GroepsKorting
    from  tabPosKop
    inner join tabPosRegel on (PorPokGid = PokGid and PorRegelSoort in (1,2))
    inner join tabArtikel on (ArtGid = PorArtGid) inner join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGid)
    left outer join tabBtw on PorBtwCode = BtwCode
    where PokGid = @PokGid
    group by PokIsInclBtw, OpbrgrpGid, OpbrGrpNummer
    having (IsNull(GroepTotaal,0) <> 0)
    order by OpbrGrpNummer
  for read only;

  declare cursor_OSPRegels dynamic scroll cursor for
    //Alle OSP regels zoeken uit de bon. Tevens de OSP informatie erbij halen
    select PorFactuurNummer, PorTekst, PorVerkoopPrijs,
      OspFactuurDatum, OspVervalDatum, OspBetalingsKenmerk
    from tabPosRegel
    inner join tabPosKop on PorPokGid=PokGid
    inner join tabNawFile on PokNawGid=NawFilNawGid
    left outer join tabOpenstaandePost on PorFactuurNummer_Lengte=OspFactuurnummer_Lengte and PorFactuurNummer=OspFactuurnummer and OspBjGid=@@BjGid and OspRksGid=NawFilRksGid
    where PorPokGid = @PokGid and PorRegelSoort=3
    order by PorRegelnr
  for read only;



  declare cursor_KostenVoorraad dynamic scroll cursor for
    //de verschillende opbrengstgroepen pakken. Per groep Kosten aan Voorraad boeken. Geen nulboekingen.
    //Als partij een kostprijs heeft, dan die gebruiken.
    select OpbrGrpGid,
           sum(PorAantalBesteld
               * (IsNull(ArtPartijKostprijsEx, ArtKostprijsEx))
               / ArtPrijsPer) GroepTotaal
    from tabPosRegel inner join tabArtikel on (ArtGid = PorArtGid) inner join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGid)
    left outer join tabartikelpartij on ArtPartijGid = PorArtPartijGid
    where PorPokGid = @PokGid and PorRegelSoort in (1, 2)
    group by OpbrgrpGid, OpbrGrpNummer
    having (IsNull(GroepTotaal,0)<>0)
    order by OpbrGrpNummer
  for read only;


  declare cursor_Betalingen dynamic scroll cursor for
    //Alle betalingen op deze bon ophalen, behalve OpRekening.
    select PobwNummer, PobwRksGid, PoaBedragBetaald, (select ReferentieVerplicht from tabRekeningschema where RksGid = PobwRksGid) ReferentieVerplicht
    from tabPosafrekening inner join tabPosBetaalwijzen on (PobwNummer = PoaPobwNummer)
    where PobwRksGid is not null and poaPokGid = @PokGid and PoaBedragBetaald <> 0
    order by PobwNummer
  for read only;

  declare cursor_Omzet dynamic scroll cursor for
    //Alle artikel en tarief regels pakken. Omzet uitrekenen. Marge uitrekenen. Prijzen EXCL BTW. Minus Regelkortingen.
    //Als partij eigen kostprijs heeft, wordt marge op basis van die kostprijs berekend.
    select PorArtGid, ArtSoort, ArtOpbrGrpGid, PorAantalBesteld,
           if PokIsInclBtw = 0 then PorRegelTotaal else round(PorRegelTotaal * 100/(100+BTWPercentage),2) endif Omzet,
           round((Omzet - ((PorAantalBesteld/ArtPrijsPer)*(IsNull(ArtPartijKostprijsEx, ArtKostprijsEx)))),2) Marge
    from  tabPosKop
    inner join tabPosRegel on (PorPokGid = PokGid and PorRegelSoort in (1,2))
    inner join tabArtikel on (ArtGid = porArtGid)
    left outer join tabBtw on PorBtwCode = BtwCode
    left outer join tabArtikelPartij on ArtPartijGid = PorArtPartijGid
    where PokGid = @PokGid
    order by PorRegelNr
  for read only;

  set @@ErrorTextProcedure = 'POSVerwerkBon > @PokGid='+string(@PokGid)+'; @BGGid='+string(@BGGid);
  //call TraceBegin(@@ErrorTextProcedure);

  set @@ErrorTextProcedure = 'POSVerwerkBon: Vaste gegevens ophalen';
  //call Trace(@@ErrorTextProcedure);
  select povgDgbgid, povgMagGid, PovgAfrondenBontotaal, PosBepaalRekening(@Werkplek, 4, PovgRksGIDAfrondingsVerschil, null) AfrondingsRekening, DefaultBoekzijde
  into @DgbGid, @povgMagGid, @PovgAfrondenBontotaal, @PovgRksGIDAfrondingsVerschil, @AfrondingsBoekZijde
  from tabPOSVasteGegevens
  left outer join tabRekeningschema on rksgid = AfrondingsRekening
  where povgWerkplek = @Werkplek;

  //RVL 15-04-2013: Korting wel/niet apart boeken
  select vofIsRegelkortingApart into @RegelkortingApart from tabVasteGegevensOrdersFactureren;
  if not exists(select 1 from tabparagraaf where ParSoort = 60 and ParBlGid is not null /*verleende kortingen*/) then
    //Er is geen 'verleende kortingen'-paragraaf, dus toch maar niet apart boeken!
    set @RegelkortingApart = 0;
  end if;

  //Vve 20-10-2008: Nieuw: evt. uitsplitsen naar kp/kd
  select PosBepaalRekening(@Werkplek, 5, pobwRksGid, PobwNummer) into @WisselGeldRksGid from tabPosBetaalwijzen where PobwIsKasRekening = 1;

  if @povgMagGid is null then
    //Dan maar Magazijn 1 pakken.
    select MagGid into @povgMagGid from tabMagazijn where MagCode = 1;
  end if;
  //Nu de default locatie van het magazijn ophalen.
  select LocGid into @DefaultLocatie from tabLocatie where LocMagGid = @povgMagGid and LocNaam='(Standaard)';
  //call Trace('POSVerwerkBon: Het gebruikte magazijn: @povgMagGid='+string(@povgMagGid)+'; @DefaultLocatie='+string(@DefaultLocatie));

  set @@ErrorTextProcedure = 'POSVerwerkBon: BonKopgegevens ophalen';
  //call Trace(@@ErrorTextProcedure);
  select NawfilRksGid, PokNummer, NawFilNummer, PokVtgCode, NawFilNawGid, PokDatumTijd, PokAfrondingsverschil
    into @NawRksGid, @PokNummer, @NawFilNummer, @VtgCode, @NawGid, @PokDatumTijd, @AfrondingsVerschil
    from tabNawFile inner join tabPosKop on pokNawgid = NawfilNawGid where pokGid = @PokGid;

  set @@ErrorTextProcedure = 'POSVerwerkBon: Bepalen of er op rekening is betaald om VervalDatum en Betalingskenmerk te vullen';
  //call Trace(@@ErrorTextProcedure);
  if exists(select 1 from tabPosAfrekening left outer join tabPosBetaalwijzen on PoaPobwNummer = PobwNummer where pobwRksGid is null and poaPokGid = @PokGid) then
    //Vervaldatum. Indien op rekening, vervaldatum uitrekenen. Kan alleen maar op rekening indien deb een btc heeft. Dit wordt in prog gechecked.
    set @VervalDatum = FuncVervalDatumFactuurMetRksGid(@@VerwerkingsDatum, @NawRksGid);
    //Betalingskenmerk. Indien op rekening, <debnummer>/<bonnummer>
    set @Betalingskenmerk = @NawFilNummer + '/' + string(@PokNummer);
  else
    //Vervaldatum. Indien contante betalingen, vullen met verwerkingsdatum
    set @VervalDatum = @@VerwerkingsDatum;
    //Indien contante betaling, betalingskenmerk leeg maken.
    set @Betalingskenmerk = '';
  end if;

  set @BonTotaal = 0;

  //---------------------------------------------------------------------------------------------//
  //-------  BOEKING MAKEN  ---------------------------------------------------------------------//
  //---------------------------------------------------------------------------------------------//

  set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Journaalpost aanmaken';
  //call Trace(@@ErrorTextProcedure);
  select BoekGangBjGID into @BjGid from tabBoekingsgang where BoekgangGid = @BgGid;
  call BoekstuknummerGenereren(@BjGid, @DgbGid, @BoekStukNummer);
  insert into tabJournaalpost
    (Boekdatum, BoekstukNummer, JpBoekgangGid, JpDgbGid, JpIsInGebruik, OmsJournaalPost)
  select
     @@VerwerkingsDatum, @BoekStukNummer, @BGGid, @DgbGid, 1, _A('POS-Journaalpost');
  set @JpGid = @@Identity;

  set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Journaal regels aanmaken met debiteur voor verkopen. @JpGid='+String(@JpGid);
  //call Trace(@@ErrorTextProcedure);

  begin
    declare @PosJournaalRegelDebiteurTekst long nvarchar;
    set @PosJournaalRegelDebiteurTekst = _A('POS-Journaalregel (debiteur)');

    open cursor_BTWBoekingen;
    LoopBTWBoekingen:
    loop
      Fetch cursor_BTWBoekingen into @BTWCode, @BTWRksGid, @TotaalVerkochtPerBTW, @TotaalBTW;
      if sqlstate = '02000' then
        leave LoopBTWBoekingen;
      end if;

      set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: BTWloop: BTWCode='+string(@BTWcode)+'; TotaalVerkochtPerBTW='+string(@TotaalVerkochtPerBTW)+'; TotaalBtw='+string(@TotaalBTW);
      //call Trace(@@ErrorTextProcedure);
      insert into tabJournaalRegel
        (JrJpGID, JrRksGid, OmsJournaalRegel, JrReferentie,
         JrFactuurDatum, JrVervalDatum, JrBetalingskenmerk,
         IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
      select
         @JpGid, @NawRksGid, @PosJournaalRegelDebiteurTekst, @pokNummer,
         @@VerwerkingsDatum, @VervalDatum, @Betalingskenmerk,
         0, @@BasisValutaNummer, @TotaalVerkochtPerBTW, @TotaalVerkochtPerBTW;
      set @JrGid = @@Identity;

      set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Hulprekening met BTWCode='+String(@BTWCode);
      //call Trace(@@ErrorTextProcedure);

      insert into tabHulprekening
        (hulprekJrGid, hulprekBasisBedrag, hulprekValutaBedrag, hulprekValnummer, hulprekSoort, hulprekIsCredit, hulprekRksgid, HulprekBtwCode)
      values (@JrGid, @TotaalBTW, @TotaalBTW, @@BasisValutaNummer, 1, 1,  @BtwRksGid, @BtwCode);

      //Totaalbedrag uitrekenen. Later nodig;
      set @BonTotaal = @BonTotaal + @TotaalVerkochtPerBTW;
    end loop LoopBTWBoekingen;
    close cursor_BTWBoekingen;
  end;

  set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Journaal regels aanmaken met debiteur voor osp-boekingen';
  //call Trace(@@ErrorTextProcedure);

  set @TotaalAanOspBetalingen = 0;

  begin
    declare @PosJournaalRegelOspRegelTekst long nvarchar;
    set @PosJournaalRegelOspRegelTekst = _A('POS-Journaalregel (ospregel)');

    open cursor_OSPRegels;
    LoopOSPRegels:
    loop
      Fetch cursor_OSPRegels into @PorFactuurnummer, @PorTekst, @PorVerkoopPrijs, @OspFactuurDatum, @OspVervalDatum, @OspBetalingskenmerk;
      if sqlstate = '02000' then
        leave LoopOSPRegels;
      end if;

      set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: OSPRegels: @PorFactuurnummer='+@PorFactuurnummer+'; @PorVerkoopPrijs='+String(@PorVerkoopprijs)+'; @OspFactuurDatum='+String(@OspFactuurDatum);
      //call Trace(@@ErrorTextProcedure);

      insert into tabJournaalRegel
        (JrJpGID, JrRksGid, OmsJournaalRegel, JrReferentie,
         JrFactuurDatum, JrVervalDatum, JrBetalingskenmerk,
         IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
      select
         @JpGid, @NawRksGid, @PosJournaalRegelOspRegelTekst, @PorFactuurnummer,
         @OspFactuurdatum, @OspVervalDatum, @OspBetalingskenmerk,
         1, @@BasisValutaNummer, @PorVerkoopPrijs, @PorVerkoopPrijs;

      //Totaalbedrag uitrekenen. Later nodig;
      set @BonTotaal = @BonTotaal + @PorVerkoopPrijs;
      set @TotaalAanOspBetalingen = @TotaalAanOspBetalingen + @PorVerkoopPrijs;
    end loop LoopOSPRegels;
    close cursor_OSPRegels;
  end;


  set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Opbrengstjournaalregels aanmaken voor elke opbrengstgroep die gebruikt is';
  //call Trace(@@ErrorTextProcedure);

  set @HoogsteOpbrBedrag = 0;

  begin
    declare @PosJournaalRegelOpbrengstTekst long nvarchar;
    declare @PosJournaalRegelKortingTekst   long nvarchar;

    set @PosJournaalRegelOpbrengstTekst = _A('POS-Journaalregel (opbrengst)');
    set @PosJournaalRegelKortingTekst   = _A('POS-Journaalregel (korting)');

    open cursor_Opbrengsten;
    LoopOpbrengstGroep:
    loop
      Fetch next cursor_Opbrengsten into @OpbrGrpGid, @GroepTotaalBedrag, @GroepsKorting;
      if sqlstate = '02000' then
        leave LoopOpbrengstGroep;
      end if;
      set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Opbrengstgroeploop; @OpbrGrpGid='+string(@OpbrGrpGid)+', @GroepTotaalBedrag='+string(@GroepTotaalBedrag);
      //call Trace(@@ErrorTextProcedure);

      //Opbrengstgroep rekening aanmaken/ophalen voor opbrengst.
      call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 30, @OpbrGrpRksGid);
      if @RegelkortingApart <> 0 then
        call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 60, @KortingGrpRksGid);
      end if;

      //Vve 20-10-2008: Nieuw: evt. uitsplitsen naar kp/kd
      select PosBepaalRekening(@Werkplek, 2, @OpbrGrpRksGid, null) into @OpbrGrpRksGid;

      insert into tabJournaalRegel
             (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
      values (@JpGid, @OpbrGrpRksGid, @PosJournaalRegelOpbrengstTekst, 1, @@BasisValutaNummer, @GroepTotaalBedrag + if @RegelkortingApart <> 0 then @GroepsKorting else 0 endif, @GroepTotaalBedrag + if @RegelkortingApart <> 0 then @GroepsKorting else 0 endif);
      set @JrGid = @@Identity;

      if (@RegelkortingApart <> 0) and (@GroepsKorting <> 0) then
        insert into tabJournaalRegel
               (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
        values (@JpGid, @KortingGrpRksGid, @PosJournaalRegelKortingTekst, 0, @@BasisValutaNummer, @GroepsKorting, @GroepsKorting);
        set @JrGid = @@Identity;
      end if;

      if  abs(@GroepTotaalBedrag) > @HoogsteOpbrBedrag then
        set @HoogsteOpbrBedrag = @GroepTotaalBedrag;
        //ACW 06-04-2011 Bug #33502: De journaalregel onthouden in plaats van de grootboekrekening (omdat op dezelfde rekening vaker kan worden geboekt!!)
        set @HoogsteJrGid = @JrGid;
      end if;
    end loop LoopOpbrengstGroep;
    close cursor_Opbrengsten;
  end;

  set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Kostprijs/Voorraadjournaal regels aanmaken voor elke opbrengstgroep die gebruikt is';
  //call Trace(@@ErrorTextProcedure);

  begin
    declare @PosJournaalRegelKostprijsTekst long nvarchar;
    declare @PosJournaalRegelVoorraadTekst  long nvarchar;

    set @PosJournaalRegelKostprijsTekst = _A('POS-Journaalregel (kostprijs)');
    set @PosJournaalRegelVoorraadTekst  = _A('POS-Journaalregel (voorraad)');

    open cursor_KostenVoorraad;
    LoopOpbrengstGroep2:
    loop
      Fetch next cursor_KostenVoorraad into @OpbrGrpGid, @GroepTotaalBedrag;
      if sqlstate = '02000' then
        leave LoopOpbrengstGroep2;
      end if;

      set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Opbrengstgroeploop2; @OpbrGrpGid='+string(@OpbrGrpGid)+', @GroepTotaalBedrag='+string(@GroepTotaalBedrag);
      //call Trace(@@ErrorTextProcedure);

      //Opbrengstgroep rekening aanmaken/ophalen voor kostprijzen.
      call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 40, @OpbrGrpRksGid);

      //Vve 20-10-2008: Nieuw: evt. uitsplitsen naar kp/kd
      select PosBepaalRekening(@Werkplek, 1, @OpbrGrpRksGid, null) into @OpbrGrpRksGid;

      insert into tabJournaalRegel
             (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
      values (@JpGid, @OpbrGrpRksGid, @PosJournaalRegelKostprijsTekst, 0, @@BasisValutaNummer, @GroepTotaalBedrag, @GroepTotaalBedrag);

      //Voorraad rekening aanmaken/ophalen voor kostprijzen.
      //Vve 20-10-2008: Deze hoeven NIET uitgesplitst te worden naar kp/kd!
      call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 50, @OpbrGrpRksGid);

      insert into tabJournaalRegel
             (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
      values (@JpGid, @OpbrGrpRksGid, @PosJournaalRegelVoorraadTekst, 1, @@BasisValutaNummer, @GroepTotaalBedrag, @GroepTotaalBedrag);

    end loop LoopOpbrengstGroep2;
    close cursor_KostenVoorraad;
  end;



  set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Journaalregels aanmaken voor de betalingen';
  //call Trace(@@ErrorTextProcedure);
  begin
    declare @PosJournaalRegelBetalingTekst long nvarchar;
    set @PosJournaalRegelBetalingTekst = _A('POS-Journaalregel (betaling)');

    open cursor_Betalingen;
    LoopBetalingen:
    loop
      Fetch next cursor_Betalingen into @PobwNummer, @PobwRksGid, @BetaalwijzeBedrag, @ReferentieVerplicht;
      if sqlstate = '02000' then
        leave LoopBetalingen;
      end if;

      //Vve 20-10-2008: Nieuw: evt. uitsplitsen naar kp/kd
      select PosBepaalRekening(@Werkplek, 5, @PobwRksGid, @PobwNummer) into @PobwRksGid;

      set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Betalingloop: PobwRksGid='+string(@PobwRksGid)+'; Bedrag='+String(@BetaalwijzeBedrag)+', @ReferentieVerplicht='+string(@ReferentieVerplicht);
      //call Trace(@@ErrorTextProcedure);

      insert into tabJournaalRegel
             (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag, JrReferentie)
      select @JpGid, @PobwRksGid, @PosJournaalRegelBetalingTekst, 0, @@BasisValutaNummer, @BetaalwijzeBedrag, @BetaalwijzeBedrag, if @ReferentieVerplicht = 1 then DateFormat(now(), 'yyyymmdd') else '' endif
    end loop LoopBetalingen;
    close cursor_Betalingen;
  end;

  //vve 29-1-2009: verplaatst naar buiten de btwloop!!
  //MR 15-sep-2008: Afrondingsverschil boeken, alleen als dit aan staat en het afrondingsverschil niet 0 is.
  if (@PovgAfrondenBontotaal = 1 and @AfrondingsVerschil <> 0) then

    case
      when @AfrondingsBoekZijde = 0 then   //Debit, dus afrondingsverschil
        set @tmpAfrondingsVerschil = @AfrondingsVerschil;
      when @AfrondingsBoekZijde = 1 then   //Credit, dus teken omdraaien
        set @tmpAfrondingsVerschil = - @AfrondingsVerschil;
      when @AfrondingsBoekZijde in (2,3) then // Geen voorkeur / afhankelijk van dagboek
        set @AfrondingsBoekZijde = (if @AfrondingsVerschil < 0 then 1 else 0 endif); //Als <0, dan credit, anders debet
        set @tmpAfrondingsVerschil = abs(@AfrondingsVerschil);
    end case;

    set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: afr-verschil: '+ string(@tmpAfrondingsVerschil);
    //call Trace(@@ErrorTextProcedure);

    insert into tabJournaalRegel
      (JrJpGID, JrRksGid, OmsJournaalRegel, JrReferentie,
       JrFactuurDatum, JrVervalDatum, JrBetalingskenmerk,
       IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
    select
       @JpGid, @PovgRksGIDAfrondingsVerschil, _A('POS-Journaalregel (afrondingsverschil)'), @pokNummer,
       @@VerwerkingsDatum, @VervalDatum, @Betalingskenmerk,
       @AfrondingsBoekZijde, @@BasisValutaNummer, @tmpAfrondingsVerschil, @tmpAfrondingsVerschil;
  end if;


  select sum(PoaBedragBetaald) into @TotaalContantBetaald
    from tabPosafrekening inner join tabPosBetaalwijzen on (PobwNummer = PoaPobwNummer)
    where PobwRksGid is not null and poaPokGid = @PokGid and PoaBedragBetaald <> 0;
  set @TotaalContantBetaald = IsNull(@TotaalContantBetaald,0);

  select sum(PoaBedragBetaald) into @TotaalOpRekeningBetaald
    from tabPosafrekening inner join tabPosBetaalwijzen on (PobwNummer = PoaPobwNummer)
    where PobwRksGid is null and poaPokGid = @PokGid and PoaBedragBetaald <> 0;
  set @TotaalOpRekeningBetaald = IsNull(@TotaalOpRekeningBetaald,0);


  //We hebben nu de volgende bedragen:
  //  - @BonTotaal                  Dit is het totaal van de verkochte artikelen.
  //  - @TotaalContantBetaald       Dit is wat de klant via de contante betaalwijzen heeft voldaan
  //  - @TotaalOpRekeningBetaald    Dit is wat de klant op rekening betaald.
  //
  //  TCB + TORB is samen minimaal zo groot als BT. (anders kan je de bon niet afrekenen in het programma).
  //  Alles wat groter is, wordt als wisselgeld uitgekeerd. Dus WG = BT - (TCB + TORB). Dit moet van de Kas afgeboekt worden.
  //
  //  Als er TORB groter is dan BT-TCB dan is er dus meer OpRekening betaald dan nodig was om het BonTotaal te voldoen.
  //  In dat geval heeft de winkelier blijkbaar extra wisselgeld gegeven aan een klant. Zijn OSP is hierdoor gestegen.
  //  Hiervoor maken we een aparte regel aan. Dit wordt erg lastig.
  //  ---> Dit is nu geblokkeerd in het programma. Je kan dus geen 'lening' meer afsluiten.
  //
  //  Je kan wel bijpinnen. Dit wordt uitgekeerd in wisselgeld.
  //  Enigszins rare situatie ontstaat als je een gedeelte op rekening wil betalen EN ook nog ss bij wil pinnen.
  //  Hij mag dan de OSP afboeken TOT het bedrag wat je op rekening betaald.

  // Bij een bon met OSP regels is er dus niets verkocht en is er geen OSP aangemaakt. Dan moet er hier dus ook
  // geen OSP afgeboekt te worden.

  select max(PorRegelSoort) into @MaxRegelSoort from tabPosRegel where PorPokGid=@PokGid;

  //Als er openstaande posten op de bon staan, dan weten we zeker dat er NIET op rekening is betaald
  if (@MaxRegelSoort>=3) then
    set @OSPAfboeken = @BonTotaal - @TotaalAanOspBetalingen;
  else
    set @OSPAfboeken = @BonTotaal - @TotaalOpRekeningBetaald;
  end if;

  if (@OSPAfboeken <> 0) then
    begin
      declare @OSPAfboekenTekst long nvarchar;
      set @OSPAfboekenTekst = _A('POS-Journaalregel (OSP afboeken)');

      set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: OSP afboeken: Bedrag='+String(@OSPAfboeken);

      //call Trace(@@ErrorTextProcedure);
      insert into tabJournaalRegel
        (JrJpGID, JrRksGid, OmsJournaalRegel, JrReferentie,
         JrFactuurDatum, JrVervalDatum, JrBetalingskenmerk,
         IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
      select
         @JpGid, @NawRksGid, @OSPAfboekenTekst, @pokNummer,
         @@VerwerkingsDatum, @VervalDatum, @Betalingskenmerk,
         1, @@BasisValutaNummer, @OSPAfboeken, @OSPAfboeken;
    end;
  end if;


  set @WisselGeld = @TotaalContantBetaald+@TotaalOpRekeningBetaald-(@BonTotaal - @AfrondingsVerschil);
  if @WisselGeld <> 0 then
    set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Wisselgeld: Bedrag='+String(@Wisselgeld);
    //call Trace(@@ErrorTextProcedure);

    insert into tabJournaalRegel
           (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
    values (@JpGid, @WisselGeldRksGid, _A('POS-Journaalregel (wisselgeld)'), 1, @@BasisValutaNummer, @Wisselgeld, @Wisselgeld);
  end if;

  //Nu zou in theorie de jp in evenwicht moeten zijn, maar door al die berekeningen kunnen er afrondingsverschillen
  // optreden. Die gaan we nu wegboeken op een opbrengstgroep.
  //Deze opbrengstgroep is de opbrengstgroep met het hoogste bedrag.
  select sum(JrValutaBedrag)
    into @DebetSaldo
    from tabJournaalRegel where JrJpGid = @JpGid and IsCreditBoeking = 0;
  select sum(JrValutaBedrag)
    into @CreditSaldo
    from tabJournaalRegel where JrJpGid = @JpGid and IsCreditBoeking = 1;
  //Let op: de cjpregels zijn nog niet gemaakt dus we moeten ook in tabHulpRekening kijken naar de saldi.
  select @DebetSaldo+IsNull(sum(HulpRekValutaBedrag),0)
    into @DebetSaldo
    from tabHulpRekening inner join tabJournaalRegel on jrgid = hulprekjrgid where JrJpGid = @JpGid and HulpRekIsCredit = 0;
  select @CreditSaldo+IsNull(sum(HulpRekValutaBedrag),0)
    into @CreditSaldo
    from tabHulpRekening inner join tabJournaalRegel on jrgid = hulprekjrgid where JrJpGid = @JpGid and HulpRekIsCredit = 1;


  set @@ErrorTextProcedure = 'POSVerwerkBon: Boekingen: Correctieregel. DebetSaldo='+String(@DebetSaldo)+'; CreditSald='+String(@CreditSaldo)+'; HoogsteJrGid='+String(@HoogsteJrGid);
  //call Trace(@@ErrorTextProcedure);
  if @DebetSaldo <> @CreditSaldo then
    //ACW 06-04-2011 Bug #33502: NIET meer o.b.v. grootboekrekening, maar de werkelijke journaalregel updaten! (Mag ook maar 1 regel updaten)
    update tabJournaalRegel
       set JrValutaBedrag = JrValutaBedrag + (@DebetSaldo-@CreditSaldo),
           JrBasisBedrag = JrBasisBedrag + (@DebetSaldo-@CreditSaldo)
     where JrJpGid = @JpGid and JrGid = @HoogsteJrGid; //JrRksGid = @HoogsteOpbrGrpRksGid;
  end if;

  //Journaalpost uit gebruik nemen
  update tabJournaalpost set JpIsIngebruik = 0 where JpGid = @JpGid;

  //---------------------------------------------------------------------------------------------//
  //-------  OMZET OPSLAAN  ---------------------------------------------------------------------//
  //---------------------------------------------------------------------------------------------//

  set @@ErrorTextProcedure = 'POSVerwerkBon: Omzet opslaan';
  //call Trace(@@ErrorTextProcedure);
  open cursor_Omzet;
  LoopOmzet:
  loop
    Fetch next cursor_Omzet into @ArtGid, @ArtSoort, @OpbrGrpGid, @OmzAantal, @Omzet, @Marge;
    if sqlstate = '02000' then
      leave LoopOmzet;
    end if;

    set @@ErrorTextProcedure = 'POSVerwerkBon: Omzetloop: ArtGid='+String(@ArtGid)+'; Omzet='+String(@Omzet)+'; Marge='+string(@Marge);
    //call Trace(@@ErrorTextProcedure);
    insert into tabOmzet
        (OmzArtGid, OmzNawGid, OmzOpbrGrpGid, OmzArtSoort, OmzVtgCode, OmzDatum, OmzAantal, OmzValNummer, OmzMargeBasis, OmzOmzetBasis, OmzOmzetValuta, OmzMargeStandaardBasis, OmzOmzetStandaardBasis, OmzOmzetStandaardValuta)
    values
        (@ArtGid, @NawGid, @OpbrGrpGid, @ArtSoort, @VtgCode, @PokDatumTijd, @OmzAantal, @@BasisvalutaNummer, @Marge, @Omzet, @Omzet, 0, 0, 0);
  end loop LoopOmzet;
  close cursor_Omzet;


 /*  //in trigger gevuld:
      set New_Record.OmzOmzetStandaardBasis  = round((if @ArtVerkprijsIsIncl = 0 then @ArtVerkprijs else round(@ArtVerkPrijs * (100 / (100 + @BtwPercentage)), @ArtAantDecPrijzen) endif) / @ArtPrijsPer * New_Record.OmzAantal, @ArtAantDecPrijzen);
      set New_Record.OmzOmzetStandaardValuta = round(if New_Record.OmzValNummer = @@BasisValutaNummer then New_Record.OmzOmzetStandaardBasis else ValutaOmrekenen(@@BasisValutaNummer, New_Record.OmzOmzetStandaardBasis, New_Record.OmzValNummer, New_Record.OmzFinBjGid, @Pernr, 2) endif, @ArtAantDecPrijzen);
      set New_Record.OmzMargeStandaardBasis  = New_Record.OmzOmzetStandaardBasis - Round(@ArtKostprijsEx / @ArtPrijsPer * New_Record.OmzAantal, @ArtAantDecPrijzen);

  //blijft over:
     OmzMargeBasis  = omzet - kostprijs
     OmzOmzetBasis  \ deze 2 zijn gelijk
     OmzOmzetValuta /

 */


  //---------------------------------------------------------------------------------------------//
  //-------  VOORRAADMUTATIES AANMAKEN  ---------------------------------------------------------//
  //---------------------------------------------------------------------------------------------//


  set @@ErrorTextProcedure = 'POSVerwerkbon: Voorraadmutaties: Cursor openen voor alle artikelregels';
  //call Trace(@@ErrorTextProcedure);

  //We moeten @Jpgid zien te vullen bij voorraadmutaties. Maar als er een 0,00 bon is verkocht, wordt bij uit gebruik nemen vd jp
  //  de hele jp verwijderd omdat er geen regels bij staan. Dan is @JpGid nog steeds gevuld, maar het record bestaat niet meer.
  if not exists(select 1 from tabjournaalpost where JpGid = @JpGid) then
    set @JpGid = null;
  end if;

  // Lus op bonregels. Verkoopprijs in voorraadmutatierecord moet EXCLUSIEF BTW zijn, MINUS KORTINGEN, PER PRIJSPER.
  FOR @Cursor AS CURSOR_BonRegels CURSOR FOR
    select  PorGid @PorGid, PorArtGid @PorArtGid, ArtPrijsPer @ArtPrijsPer,
            if PokIsInclBtw = 0 then
              round(PorRegelTotaal / PorAantalBesteld * ArtPrijsPer, ArtAantDecPrijzen)
            else
              round((100 * (PorRegelTotaal / PorAantalBesteld * ArtPrijsPer)) / (100 + BTWPercentage), ArtAantDecPrijzen)
            endif @NettoVerkoopPrijs,
            IsNull(ArtPartijKostprijsEx, ArtKostprijsEx) @ArtKostprijsEx,
            // RB Ontime 35621 POS pakt niet juiste locate indeen geen voorkeur
            // IsNull(ArtMagDefaultLocGid, @DefaultLocatie) @LocGid,
            IsNull(ArtMagDefaultLocGid, IsNull( (Select first ArtLocLocGid
                                                from tabArtikelLocatie
                                                Left Outer join tabLocatie on (LocGid=ArtLocLocGid)
                                                where (ArtLocArtGid=ArtGid) and (ArtLocMagGid=@povgMagGid)
                                                  and ((ArtPartijGid is Null) or (ArtLocPartijGid=ArtPartijGid))
                                                  and (LocLocatietype=4) /*Picklocatie*/
                                                 order by ArtLocVoorraad Desc)
                                                , @DefaultLocatie) ) @LocGid,
            PorAantalBesteld @PorAantalBesteld, ArtSerienummer @ArtSerieNummer,  IsNull(ArtPartijNummer, (if (ArtIsPartijRegistreren = 0) and (ArtSerieNrRegistreren <> 0) then '(Standaard)' else null endif)) @ArtPartijNummer
    from    tabPosKop
            inner join tabPosRegel on (PorPokGid = PokGid)
            inner join tabArtikel on (ArtGid = PorArtGid)
            left outer join tabBtw on (BtwCode = PorBtwCode)
            left outer join tabArtikelMagazijn on (ArtMagArtGid=ArtGid) and (ArtMagMagGid=@povgMagGid)
            left outer join tabArtikelSerienummer on (ArtSerieGid=PorArtSerieGid)
            left outer join tabArtikelPartij on (ArtPartijGid=PorArtPartijGid)
    where  (PokGid = @PokGid)
      and  (PorRegelSoort = 2)
      and  (ArtMutatieVerkoopBijhouden = 1)
  FOR READ ONLY
  DO
    // Bonregel van deze bon in voorraadmutatie toevoegen
    set @@ErrorTextProcedure = 'POSVerwerkbon: Voorraadmutaties: BonRegel (@PorGid='+string(@PorGid)+') toevoegen aan tabVoorraadmutatie';
    //call Trace(@@ErrorTextProcedure);
    insert into tabVoorraadMutatie
           (vrdMutArtGid,              vrdMutNawGid,        vrdMutDatum,          vrdMutSoort,
            VrdMutUitleverOntvangstNr, VrdMutOrderBestelNr, vrdMutValNummer,      vrdMutGeprijsdPer,
            vrdMutPrijsInValuta,       vrdMutHistKostprijs,  vrdMutGebruikerCode, vrdMutJpGid)
    values( @PorArtGid,         @NawGid,         @PokDatumTijd,        1,
            @PokNummer,         @PokNummer,      @@BasisValutaNummer,  @ArtPrijsPer,
            @NettoVerkoopPrijs, @ArtKostprijsEx, @@GebruikerCode,      @JpGid);
    set @VrdMutGid = @@Identity;

    // Nu de 'detail'-tabel vullen. Hierin staan de locatie, het aantal en eventueel 1 serienummer.
    set @@ErrorTextProcedure = 'POSVerwerkbon: Voorraadmutaties: Record in tabVoorraadMutatieLocatieSerie aanmaken. @VrdMutGid='+string(@VrdMutGid)+ '; @LocGid='+string(@LocGid)+'; @ArtSerieNummer='+string(@ArtSerieNummer);
    //call Trace(@@ErrorTextProcedure);
    insert into tabVoorraadMutatieLocatieSerie
                (VrdMutLocVrdMutGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer, VrdMutLocAantal)
         values (@VrdMutGid,         @LocGid,        @ArtPartijNummer,      @ArtSerieNummer,      -@PorAantalBesteld);

  END FOR; // CURSOR_BonRegels


  //---------------------------------------------------------------------------------------------//
  //-------  SERIENUMMERS -----------------------------------------------------------------------//
  //---------------------------------------------------------------------------------------------//

  //Alle serienummer die verwerkt zijn van "PorIsSerieNetAangemaakt" afhalen want als straks de bon incl regels
  //worden verwijderd, worden via de trigger de serienummers verwijderd die nog op 1 staan!
  update tabPosRegel
     set PorIsSerieNetAangemaakt=0
   where PorPokGid = @PokGid;


  //Bij serienummers kan je opgeven dat bij leveren de garantiedatum van het serienummer ingevuld wordt.
  //Dat gaan we hier doen.
  set @@ErrorTextProcedure = 'POSVerwerkbon: Serienummers updaten wegens garantiecode';
  //call Trace(@@ErrorTextProcedure);

  FOR @SerieCursor AS CURSOR_PosRegel CURSOR FOR
    select PorArtSerieGid @SerieGid
    from   tabPosRegel
           inner join tabArtikel on (ArtGid = PorArtGid)
    where  PorPokGid = @PokGid
           and PorRegelSoort = 2 // Artikelen
           and ArtGarantieVullenBijLeveren <> 0
    FOR READ ONLY
  DO
    call UpdateGarantieSerieNummer(@SerieGid, @@Verwerkingsdatum, 0);
  END FOR;


  //ACW 19-10-2010: wens 32914: POS ook in de ICP zetten; daarom een lus per OpbrGrp/BTW-code en de ex-bedragen opnemen
  FOR @POS2ICP AS CURSOR_Pos2Icp CURSOR FOR
    select PorBtwCode                                      @CurBtwCode,
           if PokIsInclBtw = 0 then
             sum(PorRegelTotaal)
           else
             (sum(PorRegelTotaal) * 100)/(100+BTWPercentage)
           endif @CurTotaalVerkochtEx,
           IsOpbrGrpGoederen                               @CurIsOpbrGrpGoederen
    from tabPosKop
         inner join tabPosRegel       on (PorPokGid  = PokGid)
         inner join tabArtikel        on (ArtGid     = PorArtGid)
         inner join tabOpbrengstGroep on (OpbrGrpGId = ArtOpbrGrpGId)
         inner join tabBtw            on (PorBTWCode = BTWCode)
    where PokGid = @PokGid and PorRegelSoort in (1,2)
    group by PokIsInclBtw, PorBtwCode, BTWPercentage, IsOpbrGrpGoederen
    having (@CurTotaalVerkochtEx <> 0)
    FOR READ ONLY
  DO
    // Bovenstaand worden de boekingen ook altijd op verwerkingsdatum ingeklopt, dus ook de ICP op deze verwerkingsdatum zetten
    call ZetBedragInIct(@nawgid, @CurIsOpbrGrpGoederen, @@VerwerkingsDatum, @CurTotaalVerkochtEx, 0 /*is GEEN abc-levering*/, @CurBtwCode);
  END FOR;

  // Bijwerken Incassogegevens als betalingsconditie van het type Incasso
  // Zie de volgende defects:
  // #35392 Verkoop op rekening met automatische incasso leidt tot standaardfactuur i.p.v. incassofactuur
  // #43121, 43122 Tijdens factureren wordt de OSP onterecht op Incasso gezet als de debiteur standaard een betalingsconditie heeft voor incasso
  if (select SoortFactuurBtc from tabNawFile inner join tabBetalingsconditie on NawFilBtcNummer = BtcNummer where NawFilRksGID = @NawRksGid) = 3 then
    update tabOpenstaandePost
    set
      OspSoortFactuur    = 3,
      OspIncDatum        = OspVervalDatum,
      OspIncOpdrachten   = 0,
      OspIncPogingenOver = IsNull((select fonIncMaxPogingen from tabFileOfNaw where FonId = 'D'), 3)
    where
      OspFactuurNummer = string(@Poknummer) and
      OspRksGID = @NawRksGid and
      OspBjGid = @@BjGid and
      isnull(
        (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) -  // Factuurbedrag -
        (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig) -  // Reeds betaalde bedrag -
        (OspBedragOnderwegInValuta)                                 // Bedrag onderweg van de OSP
        ,0) > 0;
  end if;

  set @@ErrorTextProcedure = 'POSVerwerkBon: The end';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure POSVerwerkKasmutatie( in @BgGid integer, in @KasmutatieGid integer, in @Werkplek nchar(20))
begin
  //Verwerkt meegegeven kasmutatie. (De mutatie wordt eerst opgeslagen in de historie en dan pas verwerkt op basis van dat record).
  //Maak boeking aan in meegegeven boekingsgang.
  //Soort: 0 betekent Uitgave (dus geld uit de kas), 1 betekent Ontvangst (dus geld in de kas)
  //       2 en 3 worden later andere soorten (afstorten la en aanvullen la bijvoorbeeld)
  declare @DgbGid                integer;
  declare @JpGid                 integer;
  declare @PovgKasMutatieRksGid  integer;
  declare @BetaalwijzeRksGid     integer;
  declare @DgbTegenRksGID        integer;
  declare @KluisRksGid           integer;
  declare @BoekenRksGid          integer;

  declare @phkmVtgCode           integer;
  declare @phkmVtgNaam           nchar(40);
  declare @phkmWerkplek          nchar(80);
  declare @phkmDatumTijd         datetime;
  declare @phkmOmschrijving      nchar(40);
  declare @phkmMutatieSoort      smallint;
  declare @phkmBedrag            numeric(15,3);
  declare @phkmStuknummer        numeric(10,0);
  declare @PhkmTegenpartij       smallint;

  //call TraceBegin('POSVerwerkKasmutatie > @BgGid = ' + string(@BgGid));

  select PhkmBedrag, PhkmDatumTijd, PhkmMutatieSoort, PhkmOmschrijving, PhkmStuknummer, PhkmVtgCode, PhkmVtgNaam, PhkmWerkplek, PhkmTegenpartij
    into @PhkmBedrag, @PhkmDatumTijd, @PhkmMutatieSoort, @PhkmOmschrijving, @PhkmStuknummer, @PhkmVtgCode, @PhkmVtgNaam, @PhkmWerkplek, @PhkmTegenpartij
    from tabPosHistorieKasmutatie where phkmGid = @KasmutatieGid;

  if @phkmMutatieSoort in (0,1) then
    //call trace('POSVerwerkKasmutaties > Vaste gegevens ophalen');
    select povgDgbgid, PosBepaalRekening(@Werkplek, 3, PovgKasMutatieRksGid, null), DgbTegenRksGID
      into @DgbGid, @PovgKasMutatieRksGid, @DgbTegenRksGID
      from tabPOSVasteGegevens
      inner join tabDagboek on DgbGid = povgDgbGid
      where povgWerkplek = @Werkplek;

    select PosBepaalRekening(@Werkplek, 5, pobwRksGid,      pobwNummer),   //betalingsrekening
           PosBepaalRekening(@Werkplek, 6, PobwRksGIDKluis, pobwNummer)    //kluisrekening
     into @BetaalwijzeRksGid, @KluisRksGid
     from tabPosBetaalwijzen where PobwIsKasRekening = 1;

    if @PhkmTegenpartij = 0 then   //onbekend oftewel normale kasmutatie. Boeken op tussenrekening
      set @BoekenRksGid = @PovgKasMutatieRksGid
    else
      if @PhkmTegenpartij = 1 then //kluis oftewel er is afgeroomd of bijgevuld. Boeken op rekening vd betaalwijze.
        set @BoekenRksGid = @KluisRksGid;
      end if;
    end if;


    //call trace('POSVerwerkKasmutaties > Journaalpost aanmaken');
    insert into tabJournaalpost
      (Boekdatum, BoekstukNummer, JpBoekgangGid, JpDgbGid, JpIsInGebruik, OmsJournaalPost)
    select
       @@VerwerkingsDatum, @phkmStuknummer, @BGGid, @DgbGid, 1, _A('Kasmutatie verkoper %1!', Right(repeat('0',3)+string(@phkmVtgCode),3));
    set @JpGid = @@Identity;

    //call trace('POSVerwerkKasmutaties > Journaal regels aanmaken');

    //Vve 11-12-2006 #23219: Zie verhaal in de bug. Als Kasmutatie-tussenrekening ingesteld is op de tegenrekening van het dagboek,
    // slaan we deze regel HIER over. Dat houdt in dat hij automatisch gemaakt wordt bij het vrijgeven vd journaalpost. Hieruit volgt
    // dan financieel gezien dezelfde boeking, alleen deze regel is dan een CJP-regel waardoor het in andere programmas weer beter gaat.
    //Dit is allemaal nodig omdat je nooit "Handmatig" mag boeken op de tegenrekening van het dagboek. Alleen de triggers van journaal
    // mogen hierop boeken. Deze POS-procedure valt dus ook onder "Handmatig".
    //Waarom dat eigenlijk ooit zo bedacht is, weet niemand (RB/EL/RvL) meer.
    if @PovgKasMutatieRksGid <> @DgbTegenRksGID then
      insert into tabJournaalRegel
        (JrJpGID, JrRksGid, OmsJournaalRegel,
         IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
      select
         @JpGid, @BoekenRksGid, @phkmOmschrijving,
         @phkmMutatieSoort, @@BasisValutaNummer, @phkmBedrag, @phkmBedrag;
    end if;

    insert into tabJournaalRegel
      (JrJpGID, JrRksGid, OmsJournaalRegel,
       IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
    select
       @JpGid, @BetaalwijzeRksGid, @phkmOmschrijving,
       abs(@phkmMutatieSoort-1), @@BasisValutaNummer, @phkmBedrag, @phkmBedrag;

    //Journaalpost uit gebruik nemen
    update tabJournaalpost set JpIsIngebruik = 0 where JpGid = @JpGid;

  end if;

  //call TraceEind('POSVerwerkKasmutatie');
end;


// ---------------------------------------------------------------------------------------
// ----------------        Deze maakt een boeking van een kasverschil  -------------------
// ---------------------------------------------------------------------------------------
//Een positief verschil is bijv. Geteld = 41, Verwacht = 40. Je hebt dus 1 euro "verdiend".
//Een negatief verschil is bijv. Geteld = 18, Verwacht = 20. Je hebt dan 2 euro verloren/gejat/kwijt.
//De betalingsrekening moet altijd overeen komen met het daadwerkelijke saldo (=Geteld).
//JpGid is een journaalpost waar dit kasverschil in weggeboekt moet worden. Deze moet al gelocked zijn.
create or replace procedure PosVerwerkKasverschil(in @JpGid integer, in @Werkplek nchar(20), in @Betaalwijze integer, in @Kasverschil numeric(15,2))
begin
	declare @RksGidBetaalwijze integer;
	declare @RksGidKasverschillen integer;
	declare @BoekZijde smallint;
  declare @Boekstuknummer numeric(10,0);

  declare @KasVerschilTekst long nvarchar;

  set @@ErrorTextProcedure = 'PosVerwerkKasverschil';
  //call TraceBegin(@@ErrorTextProcedure);

  select PosBepaalRekening(@Werkplek, 5, pobwRksGid, @Betaalwijze),
         PosBepaalRekening(@Werkplek, 7, PobwRksGIDKasverschil, @Betaalwijze)
    into @RksGidBetaalwijze, @RksGidKasverschillen from tabPosBetaalwijzen where PobwNummer = @Betaalwijze;


  //Er wordt gewenst dat de bedrag altijd positief zijn. Bij een negatief verschil dus debet/credit omwisselen.
  set @Boekzijde = 0; //debet
  if @Kasverschil < 0 then
    set @Boekzijde = 1; //credit
    set @Kasverschil = -@KasVerschil; //positief maken
  end if;

  set @KasVerschilTekst =  _A('Kasverschil POS');

  //Journaalregel aanmaken met betaalrekening vd betaalwijze
  insert into tabJournaalRegel (IsCreditBoeking, JrJpGID, JrRksGID, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel, JrValNummer)
                        values (@Boekzijde, @JpGID, @RksGidBetaalwijze, @Kasverschil, @Kasverschil, @KasVerschilTekst, @@BasisValutanummer);
  //Journaalregel aanmaken met kasverschillenrekening vd betaalwijze
  insert into tabJournaalRegel (IsCreditBoeking, JrJpGID, JrRksGID, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel, JrValNummer)
                        values (abs(@Boekzijde-1), @JpGID, @RksGidKasverschillen, @Kasverschil, @Kasverschil, @KasVerschilTekst, @@BasisValutanummer);


  set @@ErrorTextProcedure = 'PosVerwerkKasverschil';
  //call TraceEind(@@ErrorTextProcedure);
end;


//   call PosVerwerkKasverschil('vve-pc', 1, 4, 1)

//$Workfile: POSVulHardwareTabel.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='POSVulHardwareTabel') then
  drop procedure POSVulHardwareTabel;
end if;

create procedure POSVulHardwareTabel(in @PovgGid integer)
begin
  declare @DocSoort integer;

  set @@ErrorTextProcedure = 'POSVulHardwareTabel > @PovgGid='+string(@PovgGid);
  //call traceBegin(@@ErrorTextProcedure);

  //Voor de meegegeven werkplek 11 records aanmaken als die nog niet bestaan.
  set @DocSoort=0;
  LoopLayouts:
  loop
    set @DocSoort = @DocSoort + 1;
    if not exists(select 1 from tabPosHardware where PohwDocumentSoort = @DocSoort and pohwPovgGid = @PovgGid) then
      insert into tabPosHardware (pohwDocumentSoort, pohwPovgGid) values (@DocSoort, @PovgGid);
    end if;

    if @DocSoort = 11 then
      leave LoopLayouts;
    end if;

  end loop LoopLayouts;


  set @@ErrorTextProcedure = 'POSVulHardwareTabel';
  //call traceEind(@@ErrorTextProcedure);

end;


//-----------------------------------------------------------------------
//-------- Update prijsafspraak a.d.h.v. de opgegeven parameters --------
//-----------------------------------------------------------------------
create or replace procedure PrijsAfspraakUpdate ( in @PraArtGid         integer,       in @PraNawGid integer,
                                       in @PraDebGrpGid      integer,       in @PraOpbrGrpGid integer,
                                       in @PraIsInclBtw      integer,       in @PraValNummer integer,
                                       in @PraVerkoopPrijs   numeric(15,3), in @PraKortingsPerc numeric(5,2),
                                       in @PraKortingsBedrag numeric(15,3), in @PraOpm long nvarchar,
                                       in @PraSoort          smallint,      in @PraStfKopGid integer)
begin
  declare @PraGid integer;

  set @@ErrorTextProcedure = 'PrijsAfspraakUpdate > @PraArtGid='+string(@PraArtGid)+', @PraNawGid='+string(@PraNawGid)+', @PraDebGrpGid='+string(@PraDebGrpGid)+', @PraOpbrGrpGid='+string(@PraOpbrGrpGid)+ ', @PraKortingsPerc='+string(@PraKortingsPerc)+', @PraVerkoopprijs='+string(@PraVerkoopPrijs)+')';
  //call TraceBegin(@@ErrorTextProcedure);
  //call Trace('Test of er ge-update of ge-insert moet worden');
  set @PraGid = null;
  select PraGid into @PraGid from  tabPrijsAfspraak
   where ( ( (@PraArtGid is not null)     and (PraArtGid=@PraArtGid)         ) or ( (@PraArtGid is null)     and (PraArtGid is null)     and (PraVkeGid is null)    ) )
     and ( ( (@PraNawGid is not null)     and (PraNawGid=@PraNawGid)         ) or ( (@PraNawGid is null)     and (PraNawGid is null)     and (PraVkeGid is null) ) )
     and ( ( (@PraDebGrpGid is not null)  and (PraDebGrpGid=@PraDebGrpGid)   ) or ( (@PraDebGrpGid is null)  and (PraDebGrpGid is null)  and (PraVkeGid is null) ) )
     and ( ( (@PraOpbrGrpGid is not null) and (PraOpbrGrpGid=@PraOpbrGrpGid) ) or ( (@PraOpbrGrpGid is null) and (PraOpbrGrpGid is null) and (PraVkeGid is null)) );

  if @PraGid is not null then
    //call Trace('Update !');
    update tabPrijsAfspraak
    set    PraIsInclBtw     = @PraIsInclBtw,
           PraValNummer     = @PraValNummer,
           PraVerkoopPrijs  = @PraVerkoopPrijs,
           PraKortingsPerc  = @PraKortingsPerc,
           PraKortingsBedrag= @PraKortingsBedrag,
           PraOpbrGrpGid    = @PraOpbrGrpGid,
           PraDebGrpGid     = @PraDebGrpGid,
           PraOpm           = @PraOpm,
           PraSoort         = @PraSoort,
           PraStfKopGid     = @PraStfKopGid
    where (PraGid = @PraGid)
  else
    //call Trace('Inserten!');
    insert into tabPrijsAfspraak ( PraArtGid,  PraNawGid,  PraIsInclBtw,  PraValNummer,  PraVerkoopPrijs,  PraKortingsPerc,  PraKortingsBedrag,  PraOpm,  PraOpbrGrpGid,  PraDebGrpGid, PraSoort  ,PraStfKopGid)
                          values (@PraArtGid, @PraNawGid, @PraIsInclBtw, @PraValNummer, @PraVerkoopPrijs, @PraKortingsPerc, @PraKortingsBedrag, @PraOpm, @PraOpbrGrpGid, @PraDebGrpGid, @PraSoort ,@PraStfKopGid);
  end if;

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure PrijswijzigingenVerwerken(in @PwkId integer, in @DgbGid integer, in @StukNummer numeric(10,0), in @Omschrijving nchar(40), in @Boekdatum date, out @BoekGangGid integer)
begin
  declare @JournaalIngevuld integer;
  declare @DgbCode nchar(10);
  declare @UniekNummer nchar(20);
  declare @SqlStatement long nvarchar;

  //call Trace('Begin PrijswijzigingenVerwerken > @PwkId = ' + string(@PwkId) + ', @DgbGid = ' + string(@DgbGid));

  //MR 10-jan-2008 bug #27725:Als de module voorraad uit staat is er geen boekingsdatum. Vul deze paramater dan met de verwerkingsdatum
  if ((select IsModuleActive('vr')) = 0) then
    set @Boekdatum = @@Verwerkingsdatum;
  end if;

  //call TraceBegin('PrijswijzigingenVerwerken(@PwkId='+string(@PwkId)+')');

  delete tmpVoorraadHerwaardering;
  set @@KostprijsWijzigenOokMetVoorraad = 1;

  //Huidige prijs wordt oude prijs en nieuwe prijs wordt huidige prijs
  update tabArtikel
  set    ArtOudePrijsPer                      = ArtPrijsPer,
         ArtIngangsDatumOudeKostprijs         = if PwrKostPrijs    is null then ArtIngangsDatumOudeKostprijs        else ArtIngangsDatumHuidigeKostprijs endif,
         ArtOudeKostprijs                     = if PwrKostPrijs    is null then ArtOudeKostprijs                    else ArtKostprijsEx endif,
         ArtIngangsDatumOudeVerkoopprijsExcl  = if PwrVerkoopprijs is null then ArtIngangsDatumOudeVerkoopprijsExcl else ArtIngangsDatumHuidigeVerkoopprijsExcl endif,
         ArtIngangsDatumOudeVerkoopprijsIncl  = if PwrVerkoopprijs is null then ArtIngangsDatumOudeVerkoopprijsIncl else ArtIngangsDatumHuidigeVerkoopprijsIncl endif,
         ArtIngangsDatumOudeprijsper          = if Pwrprijsper     is null then ArtIngangsDatumOudeprijsper         else ArtIngangsDatumHuidigeprijsPer endif,
         ArtOudeVerkoopPrijs                  = if PwrVerkoopprijs is null then ArtOudeVerkoopPrijs                 else (if ArtVerkprijsIsIncl = PwrIsVerkoopprijsIncl then
                                                                                                                           ArtVerkprijs
                                                                                                                        else if ArtVerkprijsIsIncl = 0 then
                                                                                                                           Round(ArtVerkprijs * (1 + IsNull((Select BtwPercentage from tabBtw where BtwCode=ArtBtwCode),0) / 100), ArtAantDecPrijzen)
                                                                                                                        else
                                                                                                                           Round(ArtVerkprijs / (1 + IsNull((Select BtwPercentage from tabBtw where BtwCode=ArtBtwCode),0) / 100), ArtAantDecPrijzen)
                                                                                                                        endif endif) endif,
         ArtPrijsPer                            = PwrPrijsPer,
         ArtIngangsDatumHuidigeKostprijs        = if PwrKostPrijs    is null then ArtIngangsDatumHuidigeKostprijs         else @Boekdatum endif,
         ArtKostprijsEx                         = if PwrKostPrijs    is null then ArtKostprijsEx                          else PwrKostprijs endif,
         ArtIngangsDatumHuidigeVerkoopprijsExcl = if PwrVerkoopprijs is null then ArtIngangsDatumHuidigeVerkoopprijsExcl  else @Boekdatum endif,
         ArtIngangsDatumHuidigeVerkoopprijsIncl = if PwrVerkoopprijs is null then ArtIngangsDatumHuidigeVerkoopprijsIncl  else @Boekdatum endif,
         ArtIngangsDatumHuidigeprijsper         = if (Pwrprijsper    is null or PwrPrijsPer = ArtOudePrijsper)then ArtIngangsDatumHuidigeprijsper else @Boekdatum endif,
         ArtVerkPrijs                           = if PwrVerkoopprijs is null then ArtVerkPrijs                            else PwrVerkoopprijs endif,
         ArtVerkprijsIsIncl                     = if PwrVerkoopprijs is null then ArtVerkprijsIsIncl                      else PwrIsVerkoopprijsIncl endif
  from   tabPrijsWijzigingsregel
  where  PwrPwkId = @PwkId and Artgid = PwrArtgid;

  //call Trace('PrijswijzigingenVerwerken > tmpVoorraadHerwaardering eventueel vullen');
  if ((select IsModuleActive('vr')) <> 0) then
    call PooledMatViewUse(2, 1, @UniekNummer);

    set @SqlStatement = 'insert into tmpVoorraadHerwaardering (tmpVhOpbrGrpNummer, tmpVhBedrag) '+
                        'select     (select OpbrGrpNummer from tabOpbrengstGroep where ArtOpbrGrpGid = OpbrGrpGid), '+
                        '            sum(IsNull((calcMagazijnVoorraad * ArtKostprijsEx / ArtPrijsPer) - (calcMagazijnVoorraad * ArtOudeKostprijs / ArtOudePrijsPer),0)) '+
                        'from        tabPrijsWijzigingsregel '+
                        '            inner join tabArtikel on (PwrArtGid = ArtGid) '+
                        '            left outer join vwVoorraadAantallenKlein'+@UniekNummer+' on (calcArtGid = ArtGid) '+
                        'where       PwrPwkId = @PwkId and PwrKostPrijs is not null and not ArtIsPartijAparteKostprijs = 1 '+
                        'group by    ArtOpbrGrpGid, ArtKostprijsEx, ArtOudeKostprijs, ArtOudePrijsPer, ArtPrijsPer';

    execute immediate @SqlStatement;


    //call Trace('PrijswijzigingenVerwerken > Geef materialized view vrij');
    call PooledMatViewRelease(@UniekNummer);

    call VoorraadHerwaarderingsboekingen(@DgbGid, @StukNummer, @Omschrijving, @Boekdatum, @BoekGangGid);

    select DgbCode into @DgbCode from tabDagboek where DgbGid = @DgbGid;

    //call Trace('PrijswijzigingenVerwerken > update tabPrijswijzigingshistorie');
    update tabPrijswijzigingshistorie
    set pwhJpGid          = if @@JpGid is not null then @@JpGid endif,
        PwhBoekstuknummer = if @@JpGid is null then null else @StukNummer endif,
        PwhDgbCode        = if @@JpGid is null then '' else @DgbCode endif
    From TabArtikel Where artgid = pwhArtgid
    And pwhArtGID in (select artGID
        from        tabPrijsWijzigingsregel inner join tabArtikel on (PwrArtGid = ArtGid) inner join tabOpbrengstGroep on (ArtOpbrGrpGid = OpbrGrpGid)
        where       PwrPwkId = @PwkId and PwrKostPrijs is not null)
    and pwhNieuweKostprijs = ArtKostprijsEx
    and pwhNieuwePrijsPer = ArtPrijsPer
    and pwhOudeKostPrijs = ArtOudeKostprijs
    and pwhOudePrijsPer = ArtOudePrijsPer
    and pwhgid = (select Max(pwhgid)
      From tabprijswijzigingshistorie pw
      inner join TabArtikel on artgid = tabprijswijzigingshistorie.pwhArtgid
      And pwhArtGID = tabprijswijzigingshistorie.pwhArtgid
      And pwhArtPartijNummer = tabprijswijzigingshistorie.pwhArtPartijNummer
      and pwhNieuweKostprijs = ArtKostprijsEx
      and pwhNieuwePrijsPer = ArtPrijsPer
      and pwhOudeKostPrijs = ArtOudeKostprijs
      and pwhOudePrijsPer = ArtOudePrijsPer);
  end if;

  //Als er een standaard kortingsbedrag is en de btw stand is gewijzigd moet het bedrag ook inclusief of exclusief berekend worden.
  update tabPrijsafspraak
  set PraIsInclBtw = PwrIsVerkoopprijsIncl,
      PraKortingsBedrag = (
                          if ArtVerkprijsIsIncl = 1 then
                            Round(PraKortingsBedrag * (1 + IsNull((Select BtwPercentage from tabBtw where BtwCode=ArtBtwCode),0) / 100), ArtAantDecPrijzen)
                          else
                            Round(PraKortingsBedrag / (1 + IsNull((Select BtwPercentage from tabBtw where BtwCode=ArtBtwCode),0) / 100), ArtAantDecPrijzen)
                          endif
                          )
  from tabPrijsWijzigingsRegel
  inner join tabArtikel on ArtGid = pwrArtGid
  where praSoort = 1
  and PraCombisoort = 0
  and PraIsInclBtw <> PwrIsVerkoopprijsIncl
  and PwrVerkoopprijs is not null
  and PraArtgid = Artgid
  and PwrPwkId = @PwkId;

  //call Trace('PrijswijzigingenVerwerken > maak tabPrijsWijzigingsRegel leeg');
  delete tabPrijsWijzigingsRegel where PwrPwkId = @PwkId;

  set @@KostprijsWijzigenOokMetVoorraad = 0;

  //call Trace('Einde PrijswijzigingenVerwerken > @BoekGangGid = ' + string(@BoekGangGid));
end;


create or replace procedure ProjectAfspraken(in @soort smallint, in @relGid integer, @pbGid integer, @alles smallint, @Geblokkeerd smallint)
result (Code nchar(20), Oms nchar(40), ppaVerkoopprijsExBtw numeric(15,3), Eenheid nchar(10), PrijsPer numeric(15,3), VerkoopPrijsExBtw numeric(15,3), ppaGid integer, ArtGid integer, RelGid integer, PbGid integer)
// Resultaat bevat ook de GIDjes omdat er wellicht een record moet worden toegevoegd (o.b.v. ArtGid, PbGid en/of RelGid) of verwijderd (o.b.v. PpaGid)
begin
  declare @UrenTekst long nvarchar;

  /*
  Definitie (met soort ervoor):
  0 Activiteit = record in tabProjectArtikel met pArtsoort = 0
  1 Machine    = record in tabProjectArtikel met pArtsoort = 1
  2 Artikel    = record in tabArtikel        met ArtSoort = 2 (heeft GEEN record in tabProjectArtikel!)
  3 Medewerker = record in tabProjectMedewerker
  Mogelijke waarden meegeven:
   @pbGid = Projectboom (optioneel); indien meegegeven, dan alleen prijsafspraken voor dit (deel)project; indien NIET meegegeven, dan juist prijsafspraken zonder project tonen
   @relgid  = Medewerker (optioneel); indien meegegeven, dan alleen prijsafspraken voor deze medewerker; indien NIET meegegeven, dan juist prijsafspraken zonder medewerker tonen
  :Alles = 0 -> alleen tonen MET prijsafspraak-record
           1 -> Ook de regels tonen die geen prijsafspraak hebben
  Let op: het is verwarrend dat je (bijv.) een activiteitenbrowse kan hebben waarvoor een medewerker is opgegeven om de prijsafspraakgegevens op te vragen,
          terwijl er ook een medewerkerbrowse is, waarvoor dus GEEN medewerkerGid wordt doorgegeven omdat hier de prijsafspraak van de betreffende regel moet worden getoond
  */

  set @@ErrorTextProcedure = 'ProjectAfspraken > @soort='+string(@soort)+', @relGid='+string(@relgid)+', @pbGid='+string(@pbGid)+', @alles='+string(@alles);
  //call TraceBegin(@@ErrorTextProcedure);

  // Zorg ervoor dat er in ieder geval tijdens designtime iets terugkomt
  set @soort = isnull(@soort,0);

  //call TraceEind(@@ErrorTextProcedure);

  set @UrenTekst = _U('Uren');

  case // @soort
  when @soort in (0, 1) then // Activiteit / Machine
    select
     ArtCode Code,
     ArtOms Oms,
     ppaVerkoopprijsExBtw,
     pArtFactEenheid       Eenheid,
     ArtPrijsPer           PrijsPer,
     pArtVerkoopprijsExBtw VerkoopPrijsExBtw,
     ppaGid,
     ArtGid,
     null RelGid,
     null PbGid
    from
     // Selecteer als begintabel de artikelen (indien scherm<>medewerker) of de medewerkertabel (indien scherm=medewerker)
     tabArtikel left outer join tabBtw on BtwCode = ArtBtwCode
     left outer join tabprojectartikel       on (pArtArtGid = ArtGid)
     left outer join tabProjectPrijsafspraak on (// Controle op meegegeven project en/of medewerker

                                                     (   (@RelGid is null and ppaRelGid is null)
                                                      or
                                                         (@RelGid is not null and isnull(ppaRelGid, @RelGid-1) = @RelGid)
                                                     ) // Alleen prijsafspraken van de medewerker of zonder medewerker (indien NULL)
                                                 and (   (@pbGid is null and ppaPbGid is null)
                                                      or (ppaPbGid = @pbGid /*in (select PbGid from tabProjectBoom where PbProjGid = @projGid)*/)
                                                     )
                                                 // Selecteer de prijsafspraak voor de betreffende regel
                                                 and (   (ppaArtGid = ArtGid)    // Als soort <> medewerker, dan MOET het artikel overeenkomen
                                                     )
                                                )
    where
         // Controle op soort venster
         (partSoort = @soort) /* Activ./Machine */
         // Alleen met prijsafspraak of alle records
     and ((@Alles = 1 and IsNull(pArtBerekenVerkoopprijsObv,0) = 0) or ppaGid is not null)
     and (@Geblokkeerd = 1 or pArtIsGeblokkeerd = 0)
    order by
      Code;

  when @soort = 2 then // Artikel
    select
     ArtCode Code,
     ArtOms Oms,
     ppaVerkoopprijsExBtw,
     ArtOmsEenheid   Eenheid,
     ArtPrijsPer     PrijsPer,
     (if ArtVerkprijsIsIncl = 1 then (ArtVerkprijs / (100+BtwPercentage) * 100) else ArtVerkprijs endif) VerkoopPrijsExBtw,
     ppaGid,
     ArtGid,
     null RelGid,
     null PbGid
    from
     // Selecteer als begintabel de artikelen (indien scherm<>medewerker) of de medewerkertabel (indien scherm=medewerker)
     tabArtikel left outer join tabBtw on BtwCode = ArtBtwCode
     left outer join tabProjectPrijsafspraak on (// Controle op meegegeven project en/of medewerker
                                                     (isnull(ppaRelGid, @relgid, 0) = isnull(@relgid, 0)) // Alleen prijsafspraken van de medewerker of zonder medewerker (indien NULL)
                                                 and (   (@pbGid is null and ppaPbGid is null)
                                                      or (ppaPbGid = @pbGid /*in (select PbGid from tabProjectBoom where PbProjGid = @projGid)*/)
                                                     )
                                                 // Selecteer de prijsafspraak voor de betreffende regel
                                                 and (ppaArtGid = ArtGid)
                                                )
    where
         (ArtSoort = 2) // Alleen de echte artikelen
     // Alleen met prijsafspraak of alle records
     and (@Alles = 1 or ppaGid is not null)
     and (@Geblokkeerd = 1 or ArtIsGeblokkeerd = 0)
    order by
      Code;


  when @soort = 3 then // Medewerker

    select
     pmwZoekCode Code,
     RelVolledigeNaam Oms,
     ppaVerkoopprijsExBtw,
     @UrenTekst Eenheid,
     null PrijsPer,
     (if pmwHeeftVerkoopprijs <> 0 then pmwVerkoopprijsExBtw endif) VerkoopPrijsExBtw,
     ppaGid,
     null ArtGid,
     RelGid,
     null PbGid
    from
     // Selecteer als begintabel de artikelen (indien scherm<>medewerker) of de medewerkertabel (indien scherm=medewerker)
     tabProjectMedewerker
     inner join tabRelatie on (RelGid = pmwRelGid)
     left outer join tabProjectPrijsafspraak on (// Controle op meegegeven project en/of medewerker
                                                (   (@pbGid is null and ppaPbGid is null)
                                                 or (ppaPbGid = @pbGid /*in (select PbGid from tabProjectBoom where PbProjGid = @projGid)*/)
                                                )
                                            // Selecteer de prijsafspraak voor de betreffende regel
                                            and (ppaRelGid = relGid)    // Medewerker van de prijsafspraak moet overeenkomen met de medewerker van de regel
                                            and (ppaArtGid is null)     // Alleen prijsafspraken tonen die NIET aan een activiteit/machine/artikel hangen!
                                           )
    where
     // Alleen met prijsafspraak of alle records
         (   (@Alles = 1)
          or (ppaGid is not null))
     and (@Geblokkeerd = 1 or pmwIsGeblokkeerd = 0)
    order by
      Code;


  end case;

end;


//----------------------------------------------------------------------------------------------------
//--------- BEPALEN DEFAULT AANTALGEBOEKT (bij invoeren projectmutaties/boekingen en werkbonnen ------
//----------------------------------------------------------------------------------------------------
create or replace procedure ProjectBepaalDefaultAantalGeboekt(
in  @PbGid                 integer,
in  @ArtGid                integer,
in  @PmwRelGid             integer,      // kan null zijn
in  @IsDirecteInkoop       integer,
out @DefaultAantalGeboekt  numeric(20,8),
out @AantalBegroot         numeric(20,8),
out @AantalBesteed         numeric(20,8),
out @AantalInWerkbon       numeric(20,8),
out @SelectieCodes         long nvarchar)
begin
  declare @TotaalVoorcalculatieRegels numeric(20,8);
  declare @TotaalProjectMutatieRegels numeric(20,8);
  declare @TotaalProjectWerkbonRegels numeric(20,8);

  set @@ErrorTextProcedure = 'ProjectBepaalDefaultAantalGeboekt(@PbGid='+string(@PbGid)+', @ArtGid='+string(@ArtGid)+', @PmwRelGid='+string(@PmwRelGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @PmwRelGid is null or not exists(select 1 from tabProjectVoorcalculatie where PvcPbGid=@PbGid and PvcArtGid=@ArtGid and PvcRelGid=@PmwRelGid and PvcIsDirecteInkoop=@IsDirecteInkoop) then
    //Geen relGid of geen voorcalculatieregels van deze relGid: dan voor de totalen niet kijken naar de relgid
    select sum(PvcBudAantal)                into @TotaalVoorcalculatieRegels from tabProjectVoorcalculatie where PvcPbGid=@PbGid  and PvcArtGid=@ArtGid  and PvcIsDirecteInkoop=@IsDirecteInkoop;
    select sum(PbrAantalGeboekt)            into @TotaalProjectMutatieRegels from tabProjectBoekingsRegel  where PbrPbGid=@PbGid  and PbrArtGid=@ArtGid  and PbrIsDirecteInkoop=@IsDirecteInkoop;
    select first PvcSelectieCodes           into @SelectieCodes              from tabProjectVoorcalculatie where PvcPbGid=@PbGid  and PvcArtGid=@ArtGid  and PvcIsDirecteInkoop=@IsDirecteInkoop and PvcSelectieCodes <> '';
    select sum(IsNull(PwbrAantalGeboekt,0)) into @TotaalProjectWerkbonRegels from tabProjectWerkbonRegel   inner join tabProjectWerkbonKop on (PwbrPwbkGid=PwbkGid and PwbkStatus <> 3) where PwbrMutSoort <> 3 and PwbrPbGid=@PbGid and PwbrArtGid=@ArtGid and PwbrIsDirecteInkoop=@IsDirecteInkoop;
  else
    //Wel voorcalculatieregels van deze relGid: dan specifiek voor deze relgid de totalen bepalen
    select sum(PvcBudAantal)                into @TotaalVoorcalculatieRegels from tabProjectVoorcalculatie where PvcPbGid=@PbGid  and PvcArtGid=@ArtGid  and PvcIsDirecteInkoop=@IsDirecteInkoop  and PvcRelGid=@PmwRelGid;
    select sum(PbrAantalGeboekt)            into @TotaalProjectMutatieRegels from tabProjectBoekingsRegel  where PbrPbGid=@PbGid  and PbrArtGid=@ArtGid  and PbrIsDirecteInkoop=@IsDirecteInkoop  and PbrRelGid=@PmwRelGid;
    select first PvcSelectieCodes           into @SelectieCodes              from tabProjectVoorcalculatie where PvcPbGid=@PbGid  and PvcArtGid=@ArtGid  and PvcIsDirecteInkoop=@IsDirecteInkoop  and PvcRelGid=@PmwRelGid and PvcSelectieCodes <> '';
    select sum(IsNull(PwbrAantalGeboekt,0)) into @TotaalProjectWerkbonRegels from tabProjectWerkbonRegel   inner join tabProjectWerkbonKop on (PwbrPwbkGid=PwbkGid and PwbkStatus <> 3) where PwbrMutSoort <> 3 and PwbrPbGid=@PbGid and PwbrArtGid=@ArtGid and PwbrIsDirecteInkoop=@IsDirecteInkoop and PwbrRelGid=@PmwRelGid;
  end if;

  if @TotaalVoorcalculatieRegels is null then
    //Als er geen voorcalculatieregels zijn, dan met 1 komen, ongeacht de al aanwezige projectmutaties
    set @DefaultAantalGeboekt = 1;
  else
    //Als er wel voorcalculatieregels zijn, dan komen met verschil, echter geen negatief aantal
    set @DefaultAantalGeboekt = IsNull(@TotaalVoorcalculatieRegels, 0) - IsNull(@TotaalProjectMutatieRegels, 0) - IsNull(@TotaalProjectWerkbonRegels, 0);
    if @DefaultAantalGeboekt < 0 then
      set @DefaultAantalGeboekt = 0;
    end if;
  end if;

  set @AantalBegroot   = IsNull(@TotaalVoorcalculatieRegels, 0);
  set @AantalBesteed   = IsNull(@TotaalProjectMutatieRegels, 0);
  set @AantalInWerkbon = IsNull(@TotaalProjectWerkbonRegels, 0);

  set @@ErrorTextProcedure = 'ProjectBepaalDefaultAantalGeboekt(@AantalBegroot='+string(@AantalBegroot)+', @AantalBesteed='+string(@AantalBesteed)+', @TotaalProjectWerkbonRegels='+string(@TotaalProjectWerkbonRegels)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure ProjectBoekingsKopToevoegen(
  in @PbkVolgnummer numeric(10,0) default null,
  in @PbkRelGid integer default null, //Verplicht bij Herkomst 5 en 6
  in @PbkHerkomst smallint default 0, //0=inv projm mutaties , 1=imp proj mutaties , 2=via journaal , 3=Gekoppeld aan journaal , 4=via werkbon , 5=Inv weekstaat , 6=imp weekstaat
  in @PbkOms nchar(40) default '',
  in @PbkWeekJaar smallint default 0, //Verplicht bij Herkomst 5 en 6
  in @PbkWeeknr smallint default 0, //Verplicht bij Herkomst 5 en 6
  out @NieuwPbkGid integer)
begin
  declare @_NieuwVolgnummer numeric(10,0);

  //call TraceBegin('ProjectBoekingsKopToevoegen > @JpDgbCode = ' + @JpDgbCode + '@BoekstukNummer='+ @BoekstukNummer );

  // gebruiksrechten controleren
  if (isModuleActive('upmo') = 0 /*Nee*/) then // qcRecht_upmo_Projectmutaties_invoeren
    call Raise(20000, _U('Onvoldoende rechten om projectmutaties aan te maken!'));
  end if;

  //Volgnummer moet groter zijn dan 0. NULL zal verderop ervoor zorgen dat er een nieuw nummer word gegenereerd.
  if @PbkVolgnummer = 0 then
    call Raise(20285); //'(20285) Volgnummer moet 1 of hoger zijn!'
  else
    if (@PbkVolgnummer is not null) and exists(select 1 from tabProjectBoekingsKop where PbkVolgnummer = @PbkVolgnummer) then
      call Raise(20721,_U('Volgnummer')); //'(20721) %1! komt al voor!'
    else
      set @_NieuwVolgnummer = @PbkVolgnummer;
    end if;
  end if;

  //De herkomst op importeren weekstaat zetten als de weekstaat gegevens zijn ingevuld
  if (IsNull(@PbkWeekJaar, 0) <> 0) or (isNull(@PbkWeeknr, 0) <> 0) or (@PbkRelGid is not null) then
    if @PbkRelGid is Null then
      call Raise(20700,_U('Medewerker')); // (20700) Ongeldige waarde: %1!
    end if;
    if isNull(@PbkWeekJaar,0) = 0 or (@PbkWeekJaar >= 9999)then
      call Raise(20700,_U('Jaar')); // (20700) Ongeldige waarde: %1!
    end if;
    if isNull(@PbkWeeknr,0) = 0 then
      call Raise(20700,_U('Week')); // (20700) Ongeldige waarde: %1!
    end if;

    begin
      //Week moet wel een weeknummer zijn die bestaat.
      declare @_Eindweek integer;
      select ISOweekofYear(string(@PbkWeekJaar) + '-12-28') into @_Eindweek;
      if @PbkWeeknr not between 1 and @_Eindweek then
        call Raise(20700,_U('Week')); // (20700) Ongeldige waarde: %1!
      end if;
    end;
  else
    //Dit zorgt er voor dat deze gegevens bij een normale projectmutatie niet gevuld worden.
    set @PbkWeekJaar = 0;
    set @PbkWeeknr = 0;
    set @PbkRelGid = null;
  end if;


  if (@PbkHerkomst = 3 /* Gekoppeld aan journaal */) then
    select PbkGid into @NieuwPbkGid from tabProjectBoekingsKop where PbkOms = @PbkOms;
  end if;

  if @NieuwPbkGid is null then
    if @_NieuwVolgnummer is null then
      call VolgnummerProjectMutGenereren(/* Forceer =  */ 1, @PbkHerkomst, @_NieuwVolgnummer);
    end if;

    insert into tabProjectBoekingsKop with auto name
    select @_NieuwVolgnummer as 'PbkVolgnummer',
           @PbkRelGid as 'PbkRelGid',
           @PbkHerkomst as 'PbkHerkomst',
           @PbkOms as 'PbkOms',
           @PbkWeekJaar as 'PbkWeekJaar',
           @PbkWeeknr as 'PbkWeeknr';

    set @NieuwPbkGid = @@Identity;
  end if;

  //call TraceEind('ProjectBoekingsKopToevoegen');
end;


create or replace procedure ProjectBoekingsRegelToevoegenWijzigen(
  in @PbkGid integer default null, /* foreign key naar projectboekingskop */
  in @PbrGid integer default null, /* foreign key naar projectboekingsregel bij het wijzigen */
  in @Soort smallint default null, /* 0= Activiteit, 1= Ov. kosten, 2= Artikel*/
  in @ProjectCode nchar(10) default null,
  in @ProjectOnderdeel nchar(40) default null, /* indien leeg, dan wordt o.b.v. projectcode gezocht naar project */
  in @PmwRelGid integer default null,
  in @MutatieDatum date default null,
  in @ArtikelTarief nchar(20) default null,
  in @GekoppeldAanActiviteit nchar(20) default null, //Als ArtikelTarief een overige kosten is en het gaat om een weekstaat moet hier instaan aan welke activiteitsregel er gekoppeld moet worden.
  in @Omschrijving long nvarchar default null,
  in @Categorieen long nvarchar default null,
  in @Kostprijs numeric(15,3) default null,
  in @Verkoopprijs numeric(15,3) default null,
  in @Status smallint default null, /*0=Concept, 1=Ingeleverd, 2=Afgekeurd, 3=Geaccepteerd*/
  in @UrenIngevoerdAls smallint default null, /*0=Decimalen , 1=Tijdnotatie , 2=Begin/Eindtijd */
  in @AantalGeboekt numeric(20,8) default null,
  in @AantalGeboektBeginTijd time default null,
  in @AantalDeclarabel numeric(20,8) default null,
  in @DirecteInkoop smallint default null, /*0= Nee, 1= Ja*/
  in @LeverancierNawGid integer default null,
  in @MagGid integer default null,
  in @LocGid integer default null,
  in @PartijGid integer default null,
  in @Opmerking long nvarchar default null,
  inout @NieuwPbrGid integer default null)
begin
  //Constanten
  declare _qcJa smallint = 1;
  declare _qcNee smallint = 0;

  //Variabelen
  declare @_ProjGid integer;
  declare @_ArtGid integer;
  declare @_PbGid integer;
  declare @_PbrSelectieCodes long nvarchar;
  declare @_PbrOmschr long nvarchar;  //RB/04-09-2026 Ontime 60270 Omschrijving werd afgebroken
  declare @_PbrDoorbelastPercentage numeric(15,3);
  declare @_PbrVerkoopprijs numeric(15,3);
  declare @_PbrPartFactEenheidFactor numeric(4,2) default 1;
  declare @_PbrPrijsPer numeric(15,3) default 1;
  declare @_PbrWeekStaatRegelNr numeric(10,0) default 0;
  declare @_PbrRegelIsOnderdeelVan smallint default _qcNee;

  //call TraceBegin('ProjectBoekingsRegelToevoegenWijzigen > ' + ' @ProjectCode = ' + @ProjectCode);

  //Als pbrgid leeg is dan zit je in toevoegmode. Gebruik dan defaults
  if @PbrGid is null then
    set @Soort = isNull(@Soort, 0);
    set @ProjectCode = isNull(@ProjectCode, '');
    set @ProjectOnderdeel = isNull(@ProjectOnderdeel, '');
    set @ArtikelTarief = isNull(@ArtikelTarief, '');
    set @GekoppeldAanActiviteit = isNull(@GekoppeldAanActiviteit, '');
    set @Omschrijving = isNull(@Omschrijving, '');
    set @Categorieen = isNull(@Categorieen, '');
    set @Status = isNull(@Status, 0);
    set @UrenIngevoerdAls = isNull(@UrenIngevoerdAls, 0);
    set @AantalGeboekt = isNull(@AantalGeboekt, 1);
    set @AantalDeclarabel = isNull(@AantalDeclarabel, 1);
    set @DirecteInkoop = isNull(@DirecteInkoop, _qcNee);
    set @Opmerking = isNull(@Opmerking, '');
  end if;

  // gebruiksrechten controleren
  if (@Soort = 0 /*Activiteit*/) and (isModuleActive('upmu') = _qcNee) then // qcRecht_upmu_Activiteitmutaties_invoeren_muteren
    call Raise(20000, _U('Onvoldoende rechten om activiteitmutaties aan te maken!'));
  end if;

  if (@Soort = 1 /*Ov. kosten*/) and (isModuleActive('upmm') = _qcNee) then // qcRecht_upmm_Overigekosten_invoeren_muteren
    call Raise(20000, _U('Onvoldoende rechten om overige kosten mutaties aan te maken!'));
  end if;

  if (@Soort = 2/*Artikel*/) and not ((isModuleActive('upma') = _qcJa) and (isModuleActive('pa') = _qcJa)) then // qcRecht_upma_Artikelenmutaties_invoeren_muteren
    call Raise(20000, _U('Onvoldoende rechten om artikelenmutaties aan te maken!'));
  end if;

  if (@AantalGeboektBeginTijd is not null) and (@UrenIngevoerdAls <> 2 /*Begin/Eindtijd*/) then
    call Raise(20700,_U('Begintijd')); // (20700) Ongeldige waarde: %1!
  end if;

  call ProjectBoekingsRegel_Valideren(
          /*in*/
          @PbkGid = @PbkGid,
          @PbrGid = @PbrGid,
          @Soort = @Soort,
          @ProjectCode = @ProjectCode,
          @ProjectOnderdeel = @ProjectOnderdeel,
          @ArtikelTarief = @ArtikelTarief,
          @GekoppeldAanActiviteit = @GekoppeldAanActiviteit,
          @Omschrijving = @Omschrijving,
          @Categorieen = @Categorieen,
          @KostPrijs = @KostPrijs,
          @VerkoopPrijs = @VerkoopPrijs,
          @MutatieDatum = @MutatieDatum,
          @Status = @Status,
          @UrenIngevoerdAls = @UrenIngevoerdAls,
          /*out*/
          @ProjGid = @_ProjGid,
          @ArtGid = @_ArtGid,
          @PbGid = @_PbGid,
          @PbrOmschr = @_PbrOmschr,
          @PbrSelectieCodes = @_PbrSelectieCodes,
          @PbrDoorbelastPercentage = @_PbrDoorbelastPercentage,
          @PbrVerkoopprijs = @_PbrVerkoopprijs,
          @PbrPartFactEenheidFactor = @_PbrPartFactEenheidFactor,
          @PbrPrijsPer = @_PbrPrijsPer,
          @PbrWeekStaatRegelNr = @_PbrWeekStaatRegelNr);

  if @Soort = 0 /*Activiteit*/ then
  begin
    declare @_LeverancierVanuitExternMedewerker integer;
    declare @_DirecteInkoopVanuitExternMedewerker smallint;
    //als de medewerker een extern medewerker is, dan is directe inkoop 1 en de leverancier invullen
    select NawFilNawGid, 1
    into @_LeverancierVanuitExternMedewerker, @_DirecteInkoopVanuitExternMedewerker
    from tabRelatie
    inner join tabnawfile on NawFilNawGid = RelNawGid
    where RelGid = @PmwRelGid
    and NawFilFonId <> 'B';

    if (@_DirecteInkoopVanuitExternMedewerker = _qcJa) then
      set @LeverancierNawGid = @_LeverancierVanuitExternMedewerker;
      set @DirecteInkoop = @_DirecteInkoopVanuitExternMedewerker;
    end if;
  end;
  end if;

  if (@_PbrWeekStaatRegelNr <> 0) then
    set @_PbrRegelIsOnderdeelVan = _qcJa;
  end if;

  if @PbrGid is null then
    // boekingsregel toevoegen
    insert into tabProjectBoekingsRegel
           (PbrArtGid,
            PbrPbGid,
            PbrPbkGid,
            PbrProjGid,
            PbrRelgid,
            PbrUrenIngevoerdAls,
            PbrAantalGeboekt,
            PbrAantalGeboektBeginTijd,
            PbrAantalDeclarabel,
            PbrDoorbelastPercentage,
            PbrIsDirecteInkoop,
            PbrLeverancierNawGid,
            PbrMagGid,
            PbrLocGid,
            PbrArtPartijGid,
            PbrKostprijs,
            PbrMutatieDatum,
            PbrMutSoort,
            PbrOmschr,
            PbrPartFactEenheidFactor,
            PbrPrijsPer,
            PbrStatus,
            PbrVerkoopprijs,
            PbrSelectieCodes,
            PbrOpm,
            PbrWeekStaatRegelNr,
            PbrRegelIsOnderdeelVan
           )
    values (/* PbrArtGid                = */ @_ArtGid,
            /* PbrPbGid                 = */ @_PbGid,
            /* PbrPbkGid                = */ @PbkGid,
            /* PbrProjGid               = */ @_ProjGid,
            /* PbrRelgid                = */ @PmwRelGid,
            /* PbrUrenIngevoerdAls      = */ @UrenIngevoerdAls,
            /* PbrAantalGeboekt         = */ @AantalGeboekt,
            /* PbrAantalGeboektBeginTijd= */ @AantalGeboektBeginTijd,
            /* PbrAantalDeclarabel      = */ @AantalDeclarabel,
            /* PbrDoorbelastPercentage  = */ @_PbrDoorbelastPercentage,
            /* PbrIsDirecteInkoop       = */ @DirecteInkoop,
            /* PbrLeverancierNawGid     = */ @LeverancierNawGid,
            /* PbrMagGid                = */ @MagGid,
            /* PbrLocGid                = */ @LocGid,
            /* PbrArtPartijGid          = */ @PartijGid,
            /* PbrKostprijs             = */ @Kostprijs,
            /* PbrMutatieDatum          = */ @MutatieDatum,
            /* PbrMutSoort              = */ @Soort,
            /* PbrOmschr                = */ @_PbrOmschr,
            /* PbrPartFactEenheidFactor = */ @_PbrPartFactEenheidFactor,
            /* PbrPrijsPer              = */ @_PbrPrijsPer,
            /* PbrStatus                = */ @Status,
            /* PbrVerkoopprijs          = */ @_PbrVerkoopprijs,
            /* PbrSelectieCodes         = */ @_PbrSelectieCodes,
            /* PbrOpm                   = */ @Opmerking,
            /* PbrWeekStaatRegelNr      = */ @_PbrWeekStaatRegelNr,
            /* PbrRegelIsOnderdeelVan   = */ @_PbrRegelIsOnderdeelVan
            );

    set @NieuwPbrGid = @@Identity;
  else
    // boekingsregel wijzigen
    update tabProjectBoekingsRegel
    set PbrArtGid = @_ArtGid,
        PbrPbGid = @_PbGid,
        PbrProjGid = @_ProjGid,
        PbrRelgid = isNull(@PmwRelGid,PbrRelgid),
        PbrUrenIngevoerdAls = isNull(@UrenIngevoerdAls,PbrUrenIngevoerdAls),
        PbrAantalGeboekt = isNull(@AantalGeboekt,PbrAantalGeboekt),
        PbrAantalGeboektBeginTijd = isNull(@AantalGeboektBeginTijd,PbrAantalGeboektBeginTijd),
        PbrAantalDeclarabel = isNull(@AantalDeclarabel,PbrAantalDeclarabel),
        PbrDoorbelastPercentage = @_PbrDoorbelastPercentage,
        PbrIsDirecteInkoop = isNull(@DirecteInkoop,PbrIsDirecteInkoop),
        PbrLeverancierNawGid = if isNull(@DirecteInkoop,PbrIsDirecteInkoop) = 1 then isNull(@LeverancierNawGid,PbrLeverancierNawGid) else null endif,
        PbrMagGid = isNull(@MagGid,PbrMagGid),
        PbrLocGid = isNull(@LocGid,PbrLocGid),
        PbrArtPartijGid = isNull(@PartijGid,PbrArtPartijGid),
        PbrKostprijs = isNull(@Kostprijs,PbrKostprijs),
        PbrMutatieDatum = isNull(@MutatieDatum,PbrMutatieDatum),
        PbrMutSoort = isNull(@Soort,PbrMutSoort),
        PbrOmschr = @_PbrOmschr,
        PbrPartFactEenheidFactor = @_PbrPartFactEenheidFactor,
        PbrPrijsPer = @_PbrPrijsPer,
        PbrStatus = isNull(@Status,PbrStatus),
        PbrVerkoopprijs = @_PbrVerkoopprijs,
        PbrSelectieCodes = @_PbrSelectieCodes,
        PbrOpm = isNull(@Opmerking,PbrOpm),
        PbrWeekStaatRegelNr = @_PbrWeekStaatRegelNr,
        PbrRegelIsOnderdeelVan = @_PbrRegelIsOnderdeelVan
    where pbrGid = @PbrGid;

    set @NieuwPbrGid = @PbrGid;
  end if;

  //call TraceEind('ProjectBoekingsRegelToevoegenWijzigen');
end;


create or replace procedure ProjectBoekingsRegel_Valideren(
  in @PbkGid integer default null, /* foreign key naar projectboekingskop */
  in @PbrGid integer default null, /* foreign key naar projectboekingsRegel */
  in @Soort smallint default null, /* 0= Activiteit, 1= Ov. kosten, 2= Artikel*/
  in @ArtikelTarief nchar(20) default '',
  in @GekoppeldAanActiviteit nchar(20) default '', //Als ArtikelTarief een overige kosten is en het gaat om een weekstaat moet hier instaan aan welke activiteitsregel er gekoppeld moet worden.
  in @ProjectCode nchar(10) default '',
  in @ProjectOnderdeel nchar(40) default '',
  in @Omschrijving long nvarchar default '',
  in @Categorieen long nvarchar default '',
  in @Kostprijs numeric(15,3) default null,
  in @Verkoopprijs numeric(15,3) default null,
  in @MutatieDatum date default null,
  in @Status smallint default 0, /*0=Concept, 1=Ingeleverd, 2=Afgekeurd, 3=Geaccepteerd*/
  in @UrenIngevoerdAls smallint default 0, /*0=Decimalen , 1=Tijdnotatie , 2=Begin/Eindtijd*/
  out @ArtGid integer default null,
  out @ProjGid integer default null,
  out @PbGid integer default null,
  out @PbrOmschr long nvarchar default '',    //RB/04-09-2026 Ontime 60270 Omschrijving werd afgebroken
  out @PbrSelectieCodes long nvarchar default '',
  out @PbrDoorbelastPercentage numeric(15,3) default null,
  out @PbrVerkoopprijs numeric(15,3) default null,
  out @PbrPartFactEenheidFactor numeric(4,2) default 1,
  out @PbrPrijsPer numeric(15,3) default 1,
  out @PbrWeekStaatRegelNr numeric(10,0) default 0
  )
begin
  // Constanten
  declare _MutSoort_Activiteit smallint = 0;
  declare _MutSoort_OvKosten smallint = 1;
  declare _MutSoort_Artikel smallint = 2;

  declare _Artsoort_Tarief smallint = 1;
  declare _ArtSoort_Artikel smallint = 2;
  declare _qcTOEVOEGEN smallint = 1;
  declare _qcWIJZIGEN smallint = 0;
  declare _qcJa smallint = 1;
  declare _qcNee smallint = 0;

  declare @_Mode smallint = _qcTOEVOEGEN;
  declare @_VanuitJournaal smallint = _qcNee;
  declare @_IsWeekstaat smallint = _qcNee;

  declare @_ArtSoort smallint default _Artsoort_Tarief;

  declare @_ProjStatus integer;
  declare @_ArtBerekenVerkoopprijsObv integer;
  declare @_ArtIsGeblokkeerd integer;
  declare @_AantalProjectBoomRecords integer;
  declare @_ProjectHeeftPermissie integer;
  declare @_GekoppeldAanArtGid integer;
  declare @_PbrMutSoort smallint;


  //call TraceBegin('ProjectBoekingsRegel_Valideren > ' + ' @ProjectCode = ' + @ProjectCode);
  //Bestaat projectboekingskop o.b.v. PbkGid
  if not exists(select 1 from tabProjectBoekingsKop where PbkGid = @PbkGid) then
    call Raise(20720, 'PbkGid'); //(20720) %1! niet gevonden!
  end if;

  //Artsoort aanpassen als het om een artikel gaat. Anders is het de default van tarief.
  if (@Soort = _MutSoort_Artikel) then
    set @_ArtSoort = _ArtSoort_Artikel;
  end if;

  //Zijn we aan het toevoegen of wijzigen?
  if (@PbrGid is not null) then
    if not exists(select 1 from tabProjectBoekingsRegel where PbrGid = @PbrGid) then
      call Raise(20720, 'PbrGid'); //(20720) %1! niet gevonden!
    end if;

    //Als de regel status ingeleverd heeft mag er niets meer worden gewijzigd
    if exists(select 1 from tabProjectBoekingsRegel where PbrGid = @PbrGid and PbrStatus in (1/*=Ingeleverd*/, 3/*=Geaccepteerd*/)) then
      call Raise(20780, _U('Wijzigen'), _U('Projectmutatieregel moet de status ''Concept'' of ''Afgekeurd'' hebben!')); //(20780) %1! niet mogelijk: %2!.
    end if;

    set @_Mode = _qcWIJZIGEN;

    //Vul de waardes vanuit de tabel. Als ze niet wijzigen gaan we de huidige gegevens gebruiken
    select pbrArtGid, pbrProjGid, pbrPbGid, PbrMutSoort, pbrOmschr, PbrSelectieCodes, PbrDoorbelastPercentage, PbrVerkoopprijs, PbrPartFactEenheidFactor, PbrPrijsPer, PbrWeekStaatRegelNr
    into @ArtGid, @ProjGid, @PbGid, @_PbrMutSoort, @PbrOmschr, @PbrSelectieCodes, @PbrDoorbelastPercentage, @PbrVerkoopprijs, @PbrPartFactEenheidFactor, @PbrPrijsPer, @PbrWeekStaatRegelNr
    from tabProjectBoekingsRegel
    where PbrGid = @PbrGid;

    if (@PbrWeekStaatRegelNr = _qcJa) and (@Soort <> @_PbrMutSoort) then
      call Raise(20780,_U('Wijzigen'), _U('Soort mag niet aangepast worden bij een weekstaatregel!')); //(20780) %1! niet mogelijk: %2!.
    end if;

    if isNull(@ArtikelTarief, '') <> '' then
      if (@PbrWeekStaatRegelNr = _qcJa) then
      begin
        declare @_Artgid integer;

        select Artgid into @_Artgid from tabArtikel where (ArtCode = @ArtikelTarief) and (Artsoort = @_ArtSoort);

        if @_Artgid <> @ArtGid then
          call Raise(20780,_U('Wijzigen'), _U('ArtikelTarief mag niet aangepast worden bij een weekstaatregel!')); //(20780) %1! niet mogelijk: %2!.
        end if;
      end;
      else
        set @ArtGid = null;
      end if;
    end if;

    if isNull(@ProjectCode, '') <> '' then
      if (@PbrWeekStaatRegelNr = _qcJa) then
      begin
        declare @_ProjGid integer;

        select ProjGid into @_ProjGid from tabProject where ProjCode = @ProjectCode;

        if @_ProjGid <> @ProjGid then
          call Raise(20780,_U('Wijzigen'), _U('Projectcode mag niet aangepast worden bij een weekstaatregel!')); //(20780) %1! niet mogelijk: %2!.
        end if;
      end;
      else
        set @ProjGid = null;
      end if;
    end if;

    if isNull(@ProjectOnderdeel, '') <> '' then
      if (@PbrWeekStaatRegelNr = _qcJa) then
      begin
        declare @_PbGid integer;

        select PbGid into @_PbGid from tabProjectBoom where pbprojgid = @ProjGid and PbZoekCode = @ProjectOnderdeel;

        if @_PbGid <> @PbGid then
          call Raise(20780,_U('Wijzigen'), _U('Projectonderdeel mag niet aangepast worden bij een weekstaatregel!')); //(20780) %1! niet mogelijk: %2!.
        end if;
      end;
      else
        set @PbGid = null;
      end if;
    end if;

    set @Soort = isNull(@Soort, @_PbrMutSoort);

    if (@PbrWeekStaatRegelNr = _qcJa) and (@Soort <> @_PbrMutSoort) then
      call Raise(20780,_U('Wijzigen'), _U('Soort mag niet aangepast worden bij een weekstaatregel!')); //(20780) %1! niet mogelijk: %2!.
    end if;
  end if;

  select _qcJa into @_VanuitJournaal
  from tabProjectBoekingsKop
  where PbkGid = @PbkGid
    and PbkHerkomst in(2 /*Via Journaal*/, 3 /*Gekoppeld aan Journaal*/);

  //Soort check
  if @Soort not in (_MutSoort_Activiteit, _MutSoort_OvKosten, _MutSoort_Artikel) then
    call Raise(20700,_U('Soort')); // (20700) Ongeldige waarde: %1!
  end if;

  //Status
  if @Status not in (0/*=Concept*/, 1/*=Ingeleverd*/, 2/*=Afgekeurd*/, 3/*=Geaccepteerd*/) then
    call Raise(20700,_U('Status')); //(20700) Ongeldige waarde: %1!
  end if;

  //UrenIngevoerdAls
  if @UrenIngevoerdAls not in (0/*=Decimalen*/, 1/*=Tijdnotatie*/, 2/*=Begin/Eindtijd*/) or
  (@UrenIngevoerdAls in (1/*=Tijdnotatie*/, 2/*=Begin/Eindtijd*/) and @Soort <> _MutSoort_Activiteit) then
    call Raise(20700, _U('Uren ingevoerd als')); //(20700) Ongeldige waarde: %1!
  end if;

  //ArtikelTarief checken
  if (@_Mode = _qcTOEVOEGEN) and (isNull(@ArtikelTarief, '')  = '') then
    call Raise(20700, _U('ArtikelTarief')); // (20700) Ongeldige waarde: %1!
  end if;

  //ArtikelGegevens
  select ArtGid, ArtPrijsPer, pArtBerekenVerkoopprijsObv, pArtIsGeblokkeerd, isNull(pArtFactEenheidFactor,1),
         if pArtBerekenVerkoopprijsObv = 1 /*Doorbelasten tegen percentage van de kostprijs*/ then pArtDoorbelastPercentage else null endif
   into @ArtGid, @PbrPrijsPer, @_ArtBerekenVerkoopprijsObv, @_ArtIsGeblokkeerd, @PbrPartFactEenheidFactor, @PbrDoorbelastPercentage
  from tabArtikel
  left outer join tabProjectArtikel on PartArtGid = ArtGid
  where (ArtCode = @ArtikelTarief)
    and (Artsoort = @_ArtSoort);

  if (@ArtGid is null) then
    call Raise(20720, _U('ArtikelTarief')); //(20720) %1! niet gevonden!
  end if;

  //Projectcode checken
  select ProjGid, ProjStatus
    into @ProjGid, @_ProjStatus
  from tabProject
  where ProjCode = @ProjectCode;

  if @ProjGid is null then
    call Raise(20720, _U('Projectcode')); //(20720) %1! niet gevonden!
  end if;

  //Is het project muteerbaar
  if not @_ProjStatus in (1 /*in voorbereiding*/, 2 /*onderhanden*/) then
    call Raise(20780, _U('Toevoegen'), _U('Project moet de status ''In voorbereiding'' of ''Onderhanden'' hebben!')); //(20780) %1! niet mogelijk: %2!.
  end if;

  if (IsNull(@ProjectOnderdeel, '') = '') and (@_VanuitJournaal = _qcJa) then
    //Als vanuit het journaal alleen het project wordt meegegeven en er is 1 projectonderdeel, dan die selecteren.
    select count(pbprojgid) into @_AantalProjectBoomRecords
    from tabProjectBoom
    where pbprojgid = @ProjGid
      and PbLevel <> 1;

    if @_AantalProjectBoomRecords = 1 then
      select PbGid into @PbGid
      from tabProjectBoom
      where pbprojgid = @ProjGid
        and PbLevel <> 1;
    else
      if @_AantalProjectBoomRecords > 1 then
        call Raise(20780,_U('Ophalen projectonderdeel'), _U('Alleen mogelijk als er slechts 1 projectonderdeel binnen het project is!')); //(20780) %1! niet mogelijk: %2!.
      end if;
    end if;
  else
    select PbGid into @PbGid
    from tabProjectBoom
    where pbprojgid = @ProjGid
      and PbZoekCode = @ProjectOnderdeel;

    if (@PbGid is null) then
      call Raise(20720, _U('Projectonderdeel')); //(20720) %1! niet gevonden!
    end if;
  end if;

  if ProjectHeeftPermissie(@PbGid, null /* relgid */, @ArtGid) = _qcNee then
    call Raise(20256);
  end if;

  //In het geval van een activiteit of overige kosten moet er ook een record bestaan in tabProjectArtikel
  if @Soort in (_MutSoort_Activiteit, _MutSoort_OvKosten) then
    if not exists(select 1 from tabProjectArtikel where PartArtGid = @ArtGid) then
      call Raise(20700,_U('ArtikelTarief is geen projecttarief')); // (20700) Ongeldige waarde: %1!
    end if;

    //Alleen voor het toevoegen vanuit Journaalposten
    if (@_ArtBerekenVerkoopprijsObv <> _qcJa /*Doorbelasten tegen percentage van de kostprijs*/) and (@_VanuitJournaal = _qcJa) then
      call Raise(20700, _U('Tariefcode wordt niet doorbelast!'));
    end if;

    if (@_ArtIsGeblokkeerd <> _qcNee) then
      call Raise(20700, _U('ArtikelTarief is geblokkeerd voor gebruik in projecten!'));
    end if;

    select _qcJa into @_IsWeekstaat
    from tabProjectBoekingsKop
    where PbkGid = @PbkGid
      and PbkHerkomst in(5 /*Invoeren weekstaat*/, 6 /*Import weekstaat*/) ;

    if ((@_IsWeekstaat = _qcNee) or (@Soort <> _MutSoort_OvKosten)) and (isNull(@GekoppeldAanActiviteit,'') <> '') then
      call Raise(20700,'GekoppeldAanActiviteit'); // (20700) Ongeldige waarde: %1!
    end if;

    if (@_IsWeekstaat = _qcJa) and not ((@Soort = _MutSoort_OvKosten) and (isNull(@GekoppeldAanActiviteit,'') = '')) then
      if (@Soort = _MutSoort_OvKosten) and (isNull(@GekoppeldAanActiviteit,'') <> '') then
        select ArtGid into @_GekoppeldAanArtGid
        from tabArtikel
        where (ArtCode = @GekoppeldAanActiviteit)
          and (Artsoort = _Artsoort_Tarief);

        if @_GekoppeldAanArtGid is null then
          call Raise(20720, 'GekoppeldAanActiviteit'); //(20720) %1! niet gevonden!
        end if;
      end if;

      //Als het een weekstaat betreft gaan we een regelnummer toekennen
      if (@_Mode = _qcTOEVOEGEN) then
        if @Soort = _MutSoort_Activiteit then
          select Max(pbrWeekStaatRegelNr) into @PbrWeekStaatRegelNr
          from tabProjectBoekingsRegel
          where PbrRegelIsOnderdeelVan = _qcJa
            and PbrpbkGid = @PbkGid
            and PbrProjgid = @ProjGid
            and PbrPbGid = @PbGid
            and PbrArtGid = @ArtGid
            and PbrMutatieDatum <> @MutatieDatum
            and ((@Soort = _MutSoort_OvKosten) or  pbrWeekStaatRegelNr not in( select pbrWeekStaatRegelNr
                                                                                  from tabProjectBoekingsRegel
                                                                                  where PbrRegelIsOnderdeelVan = _qcJa
                                                                                    and PbrpbkGid = @PbkGid
                                                                                    and PbrProjgid = @ProjGid
                                                                                    and PbrPbGid = @PbGid
                                                                                    and PbrArtGid = @ArtGid
                                                                                    and PbrMutatieDatum = @MutatieDatum));

          if (@PbrWeekStaatRegelNr is null) then
            select IsNull(Max(pbrWeekStaatRegelNr) + 1, 1) into @PbrWeekStaatRegelNr
            from tabProjectBoekingsRegel
            where PbrRegelIsOnderdeelVan = 1
              and PbrpbkGid = @PbkGid;
          end if;
        else
          select Max(pbrWeekStaatRegelNr) into @PbrWeekStaatRegelNr
          from tabProjectBoekingsRegel
          where PbrRegelIsOnderdeelVan = _qcJa
            and PbrpbkGid = @PbkGid
            and PbrProjgid = @ProjGid
            and PbrPbGid = @PbGid
            and PbrArtGid = @_GekoppeldAanArtGid
            and PbrMutatieDatum = @MutatieDatum;

          //als de regel niet bestaat aanmaken.
          if (@PbrWeekStaatRegelNr is null) then
          begin
            declare @_PbrGid integer;
            declare @_PbkRelGid integer;

            select PbkRelGid into @_PbkRelGid
            from tabProjectBoekingsKop
            where pbkGid = @PbkGid;

            //Voeg de activiteitregel toe
            call ProjectBoekingsRegelToevoegenWijzigen(
              /*In*/
              @PbkGid = @PbkGid,
              @Soort = _MutSoort_Activiteit,
              @ProjectCode = @ProjectCode,
              @ProjectOnderdeel = @ProjectOnderdeel,
              @PmwRelGid = @_PbkRelGid,
              @MutatieDatum = @MutatieDatum,
              @ArtikelTarief = @GekoppeldAanActiviteit,
              @UrenIngevoerdAls = 0 /*Decimalen*/,
              @AantalGeboekt = 0,
              @AantalDeclarabel = 0,
              /*Out*/
              @NieuwPbrGid = @_PbrGid);

            select pbrWeekStaatRegelNr into @PbrWeekStaatRegelNr
            from tabProjectBoekingsRegel
            where PbrGid = @_PbrGid;
          end;
          end if;
        end if;
      end if;
    end if;
  end if;

  //Omschrijving
  if IsNull(@Omschrijving, '') <> '' then
    set @PbrOmschr = @Omschrijving;
  end if;

  if IsNull(@PbrOmschr, '') = '' then
    select first ArtTekst
    into @PbrOmschr
    from tabArtikelTeksten
    inner join tabArtikel on (ArtTekstArtGid = ArtGid)
    where ArtTekstArtGid = @ArtGid
      and ((ArtSoort = 2 /*Artikel*/ and ArtTekstDocSoort = 50 /*Factuur*/) or (ArtSoort <> 2 /*Artikel*/ and ArtTekstDocSoort is null))
      and (ArtTaalGid = (select DefaultTaalGid from tabVastegegevens) );
  end if;

  if IsNull(@PbrOmschr, '') = '' then
    select ArtOms into @PbrOmschr from tabArtikel where ArtGid = @ArtGid;
  end if;

  if @PbrOmschr is null then
    set @PbrOmschr = '';
  end if;

  //Selectiecodes
  set @PbrSelectieCodes = @Categorieen;

  if IsNull(@PbrSelectieCodes, '') = '' then
    select first PvcSelectieCodes
    into @PbrSelectieCodes
    from tabProjectVoorcalculatie
    where PvcProjGid = @ProjGid
      and PvcPbGid = @PbGid
      and PvcArtGid = @ArtGid
    order by PvcTimeStamp desc;
  end if;

  //Verkoopprijs
  //Verkoopprijs berekenen obv kostprijs
  if (@PbrDoorbelastPercentage is not null) and (@_ArtBerekenVerkoopprijsObv <> _qcJa /*Doorbelasten tegen percentage van de kostprijs*/) then
    set @PbrVerkoopprijs = @Kostprijs * (@PbrDoorbelastPercentage / 100.0);
  else
    set @PbrVerkoopprijs = isNull(@Verkoopprijs, @Kostprijs);
  end if;

  //call TraceEind('ProjectBoekingsRegel_Valideren');
end;


// ----------------------------------------------------------------------------------------
// -------- ProjectControleerWeekStaat tbv project weekstaat ---------------
// ---- Controleert:
// ----				- of er geen weekstaatregels zijn met verschillende project/projectonderdeel/activitit combinatie ----
// ----				- of er geen weekstaatregels zijn waar de datum buiten de weekstaat valt ----
// ----				- of er geen weekstaatregels zijn die voor een andere medewerker zijn ----
// ----------------------------------------------------------------------------------------
create or replace procedure ProjectControleerWeekStaat(
	in    @pbkGid    		integer,
  in    @Relgid     	integer,
  in    @BeginDatum 	DateTime,
  in    @EindDatum 		DateTime,
  in    @0RegelsOmzetten 		integer,
  out   @FoutMelding	nchar(150)
  )
begin

  set @@ErrorTextProcedure = 'ProjectControleerWeekStaat > @pbkGid='+string(@pbkGid)+', @RelGid='+string(@RelGid)+', @BeginDatum='+string(@BeginDatum)+', @EindDatum='+string(@EindDatum);
 	//call TraceBegin(@@ErrorTextProcedure);

	//Ga de projectweekstaatregelnrs 0 verwerken als dit is aangegeven.
	if (@0RegelsOmzetten = 1) then
    call ProjectGenereerWeekStaatRegelnrAct(@pbkGid,null,@Relgid,@BeginDatum,@EindDatum);

    call ProjectGenereerWeekStaatRegelnrOvKosten(@pbkGid,null,@Relgid,@BeginDatum,@EindDatum);
  end if;

 	set @FoutMelding = '';

 	if exists( 	select pbrweekstaatregelnr, count(distinct pbrprojgid) Project, count(distinct pbrpbgid) Onderdeel , count(distinct pbrartgid) Activiteit
							from tabProjectBoekingsRegel
							where pbrpbkGid = @pbkGid and pbrMutSoort = 0 and PbrRegelIsOnderdeelVan = 1
							group by pbrweekstaatregelnr
							having (Project > 1 or Onderdeel > 1 or Activiteit > 1))
	then
 		//Er is een regelnr met verschillende projecten/projectonderdelen/activiteiten
 		set @Foutmelding = _U('Er zijn mutaties die op dezelfde regel staan met afwijkende project, onderdeel en/of activiteit');
 	else if exists( select ov.pbrweekstaatregelnr, count(distinct ov.pbrprojgid) Project, count(distinct ov.pbrpbgid) Onderdeel, count(distinct act.pbrArtgid) koppeling
                  from tabProjectBoekingsRegel ov
                  left outer join tabprojectboekingsregel act on act.pbrpbkgid = ov.pbrpbkgid and
                                               act.pbrweekstaatregelnr = ov.pbrweekstaatregelnr and
                                               act.pbrmutatiedatum = ov.pbrmutatiedatum and
                                               act.pbrmutsoort = 0 and
                                               (act.pbrprojgid <> ov.pbrprojgid or
                                               act.pbrpbgid <> ov.  pbrpbgid)
                  where ov.pbrpbkGid = @pbkGid and ov.pbrMutSoort = 1 and ov.PbrRegelIsOnderdeelVan = 1
                  group by ov.pbrweekstaatregelnr,ov.pbrmutatiedatum
                  having (Project > 1 or Onderdeel > 1 or koppeling <> 0))
		then
 			//Er is een regelnr met verschillende projecten/projectonderdelen/activiteiten voor overige kosten
 			set @Foutmelding = _U('Er zijn overige kosten mutaties die op dezelfde regel staan met afwijkende project en/of onderdeel');
 		else if exists(select pbrweekstaatregelnr from tabProjectBoekingsRegel where pbrpbkGid = @pbkGid and pbrRelGid <> @RelGid and PbrRegelIsOnderdeelVan = 1)
 			then
 				//Er is een regel met een andere medewerker
 				set @Foutmelding = _U('Er zijn mutaties die een verkeerde medewerker hebben');
 			else if exists(select pbrweekstaatregelnr from tabProjectBoekingsRegel where pbrpbkGid = @pbkGid and pbrMutatieDatum not between @BeginDatum and @Einddatum and PbrRegelIsOnderdeelVan = 1)
 				then
 					//Er is een regel die buiten de week valt
 					set @Foutmelding = _U('Er zijn mutaties die buiten de week vallen');
				end if;
			end if;
		end if;
	end if;

  set @@ErrorTextProcedure = @@ErrorTextProcedure;
  //call TraceEind(@@ErrorTextProcedure);
end;



// ---------------------------------------------------------------------------------------------
// --------- Project accepteren mutaties: Maak boeking en voorraadmutaties per project ---------
// ---------------------------------------------------------------------------------------------
// Historie:
// TG 29-07-2009: Aanpassingen nav samenvoegen regie/termijnprojecten -> projectsoort naar projectonderdeelsoort omsleutelen.
// MR 02-04-2008: Nu per projectmutatiebestand een journaalpost aanmaken. (bug #28088).
// DG 16-10-2007: Nu ook kostprijs boeking in geval van Doorbelasting < 100% +
//                Onderhanden werk alleen corrigeren op doorbelasting voor regieprojecten.
// DG 09-10-2007: rev1.04 BedragOHW rekening houden met doorbelastingspercentage.
// DG 09-10-2007: rev1.04 Referentie vullen nu ook op project en mutatiebestand (afhankelijk v. vaste geg.)

create or replace procedure ProjectenAcceptatieMaakBoekingEnVoorraad(
  in  @SessieNr     integer,
  in  @ProjGid      integer,
  in  @PbrPbkGid    integer,
  in  @BoekgangGid  integer,
  in  @PerNr        integer,  // Periodenummer in het huidige boekjaar; alleen mutaties met een datum in deze periode boeken op de laatste datum in deze periode
  in  @IsAcceptatie integer, // 0 = terughalen, 1 = accepteren
  out @FoutNr       integer, // 0 = ok
  out @FoutCode     nchar(80) // 1 = Dagboek/Rek.tbv. OHW in vaste gegevens niet ingevuld
                             // 2 = Paragraaf of rekening OHW niet ingevuld
                             // 3 = Te boeken rekening is niet gevonden
)
begin
  declare @BoekDatum      date;
  declare @MinTeken       integer;  // -1 of 1; bedoeld als vermenigdvuldigingsfactor voor de aantallen/bedragen
  declare @VanDatum       date;     // Alleen regels binnen deze datumrange boeken!
  declare @TotDatum       date;
  // Boekingsgegevens
  declare @DgbGid         integer;
  declare @DgbCode        nchar(8);
  declare @BoekstukNummer numeric(10,0);
  declare @BjGid          integer;
  declare @JpGid          integer;  // Aangemaakte journaalpost voor deze projectboekingen
  declare @RefVullenMet   smallint; // Afhankelijk van deze waarden wordt ref gevuld met
                                    //0=crediteurnummer;1=Projectmutatienummer;2=Projectcode
  // Projectgegevens
  declare @ProjGrpGid     integer;   // Projectgroep van dit project
  declare @NawGidProject  integer;   // de NAW van het project (de debiteur)
  declare @ProjCode       nchar(10);  // Code van het project; alleen nodig voor de omschrijvingsregel van journaalpost/-regels
  declare @ProjOmschr     nchar (40); // Omschrijving van het project; alleen nodig voor de omschrijvingsregel van journaalpost/-regels
  declare @ProjStatus     smallint;  // Status van project 0=Concept, 1=In voorbereiding, 2=Onderhanden, 3=Afgesloten
  // Projectgroep-gegevens
  declare @BoekDekkingPerOpbrGrp     smallint; // 0 = dekkingen op deze projectgroep boeken, 1 = per opbrengstgroep apart boeken
  declare @BoekKostprijsPerOpbrGrp   smallint; // 0 = kostprijs (voor regie) op deze projectgroep boeken, 1 = per opbrengstgroep apart boeken
  // Benodigde grootboekrekeningen (cache, omdat deze per project(groep) zijn)
  declare @RksInvoerOHW              nchar(28); // Rekening t.b.v. onderhanden werk (uit vaste gegevens projecten)
  declare @ReferentieVerplichtOHW    smallint; //MR 20-aug-2010 bug #32672: als deze nodig is een referentie toevoegen
  declare @RksInvoerInkoopFact       nchar(28); // Rekening t.b.v. inkoopfacturen van crediteuren (voor externe activiteiten)
  declare @RksInvoerKostprijsProjGrp nchar(28); // Rekening t.b.v. kostprijs (alleen bij regieprojecten en kostprijsboekingen per projectgroep verwerken)
  declare @RksInvoerDekkingTarieven  nchar(28); // Rekening t.b.v. kostprijs (alleen bij dekkingen per projectgroep verwerken)
  // Hulpvariabelen
  declare @RksGid                    integer;  // Hulpvariabele om @RksInvoer... velden te vullen
  declare @RksInvoer                 nchar(28); // Hulpvariabele om rekening in tabProjectBoekingJournaal te zetten
  declare @RksInvoerHerwaardering    nchar(28); // Hulpvariabele om de herwaarderingsrekening te vinden
  declare @AantDecBedrag             integer;  // Bij afronding wordt dit aantal decimalen gebruikt
  declare @oms                       nchar(80); // Omschrijving van de journaalpost en -regels
  declare @BoekZijde                 smallint; // t.b.v. boeken in journaal
  declare @Referentie                nchar(40); // benodigd om de referentie in tabProjectBoekingJournaal te zetten (alleen voor externe activiteiten)
  declare @PartijNummer              nchar(20);
  declare @PbkVolgNummer             numeric(10,0); //MR 02-apr-2008 projectboekingkop volgnummer
  declare @PbkHerkomst               smallint; //MR 31-okt-2014 projectboekingkop herkomst
  declare @VrdMutGid                 integer;

    // t.b.v. herkenning van de regels
  declare @AangemaaktDoor nchar(10);
  declare @AangemaaktOp   DateTime;

  //call TraceBegin('ProjectenAcceptatieMaakBoekingEnVoorraad > @SessieNr = ' + String(@SessieNr) + ', @ProjGid = ' + string(@ProjGid) + ', @BoekgangGid = ' + string(@BoekgangGid));

  set @FoutNr = 0;
  set @FoutCode = '';
  set @MinTeken = if @IsAcceptatie = 0 then -1 else 1 endif; // Veld gebruiken om aantallen/bedragen maal -1 te doen bij terughalen

  set @AangemaaktDoor = @@gebruikercode;
  set @AangemaaktOp   = now();

  // Data bepalen; zowel de range als de boekdatum (=laatste dag in de periode)
  select BeginDatum, EindDatum into @VanDatum, @TotDatum from tabPeriode where PerBjGID = @@BjGid and PerNr = @PerNr;
  //MR 02-apr-2008 bug #28088: De boekdatum is de datum van de projectmutatie geworden met de hoogste datum.
  //set @BoekDatum = @TotDatum;
  //MR 07-apr-2008:  and tmpPgsStatus = 1 weggehaald omdat een regel met besteed 0 en serienummers een uitklapper veroorzaakt.
  select Max(PbrMutatieDatum) into @BoekDatum
  from tabProjectBoekingsRegel inner join tmpProjectGoedkeurSelectie on (tmpPgsPbrGid = PbrGid and tmpPgsSessie = @SessieNr)
  where PbrPbkGid = @PbrPbkGid and pbrProjGid = @ProjGid and pbrpernr = @PerNr;

  //call trace('@PerNr='+string(@PerNr)+', @VanDatum='+string(@VanDatum)+', @TotDatum='+string(@TotDatum)+', @BoekDatum='+string(@BoekDatum));

  //select DecimalenBoeking * 2 into @AantDecBedrag from tabValuta where ValNummer = @@BasisValutaNummer;
  set @AantDecBedrag = 2; // Is in valutacodetabel niet meer zichtbaar/wijzigbaar!


  // ### Uitlezen van de defaults ###
  // --------------------------------

  // --- Vaste gegevens projecten
  select first ProjVastDgbGid, DgbCode, ProjVastRksGid, IsNull (ProjVastReferentieVullenMet, 0)
  into @DgbGid, @DgbCode, @RksGid, @RefVullenMet
  from   tabProjectVastegegevens left outer join tabDagboek on (DgbGid = ProjVastDgbGid);
  if @DgbGid is null or @RksGid is null then
    //call trace('FOUT 1');
    set @FoutCode = if @DgbGid is null then _U('dagboek') else _U('rekening t.b.v. inkoopfacturen') endif;
    set @FoutNr = 1;
  end if;
  select RksInvoer into @RksInvoerInkoopFact from tabRekeningSchema where RksGid = @RksGid;

  // --- Project
  select ProjCode, ProjOmschr, ProjProjGrpGid, ProjNawGid, ProjStatus
  into   @ProjCode, @ProjOmschr, @ProjGrpGid, @NawGidProject, @ProjStatus
  from   tabProject where ProjGid = @ProjGid;
  // --- Projectgroep
  select ProjGrpDekkingTarievenObvGroep, ProjGrpKostprijsBoekenObvGroep
  into   @BoekDekkingPerOpbrGrp, @BoekKostprijsPerOpbrGrp
  from   tabProjectGroep
  where  ProjGrpGid = @ProjGrpGid;
  // --- Projectmutatiebestand volgnummer
  select PbkVolgNummer,pbkHerkomst into @PbkVolgNummer,@PbkHerkomst from tabProjectBoekingsKop where PbkGid = @PbrPbkGid;

  //call trace('ProjectGroep; @ProjGrpGid='+string(@ProjGrpGid)+', @BoekDekkingPerOpbrGrp='+string(@BoekDekkingPerOpbrGrp)+', @BoekKostprijsPerOpbrGrp='+string(@BoekKostprijsPerOpbrGrp));

  // Controleer projectstatus
  if (@FoutNr = 0) and (@ProjStatus = 3) then
    set @FoutNr = 5;
    set @FoutCode = _U('Project %1! is afgesloten', @ProjCode);
  end if;

  // ### Sommige rekeningen alvast lezen (die zijn per project gelijk) ###
  // ---------------------------------------------------------------------

  // Rekening *Kostprijs projecten o.b.v. projectgroep*
  if (@BoekKostprijsPerOpbrGrp = 0) and (@FoutNr = 0) then
    call ProjectLeesRekeningObvProjectGroep(     @ProjGrpGid,    160, @RksGid); // *Kostprijs projecten o.b.v. projectgroep*
    if @RksGid is null then
      set @FoutNr = 2;
      set @FoutCode = _U('paragraaf Kostprijs projecten o.b.v. projectgroep');
    end if;
    select RksInvoer into @RksInvoerKostprijsProjGrp from tabRekeningSchema where RksGid = @RksGid;
  end if;

  // Rekening *Dekking tarieven projecten o.b.v. projectgroep*
  if (@BoekDekkingPerOpbrGrp = 0) and (@FoutNr = 0) then
    call ProjectLeesRekeningObvProjectGroep(     @ProjGrpGid,    170, @RksGid); // *Dekking tarieven projecten o.b.v. projectgroep*
    if @RksGid is null then
      set @FoutNr = 2;
      set @FoutCode = _U('paragraaf Dekking tarieven projecten o.b.v. projectgroep') ;
    end if;
    select RksInvoer into @RksInvoerDekkingTarieven from tabRekeningSchema where RksGid = @RksGid;
  end if;

  // Rekening OHW
  if @FoutNr = 0 then
    call ProjectLeesRekeningObvProjectGroep(@ProjGrpGid, 130, @RksGid); // Onderhanden Werk
    if @RksGid is null then
      //call trace('FOUT 2; @ProjGrpGid='+string(@ProjGrpGid)+', ParagraafSoort=130');
      set @FoutCode = _U('paragraaf Onderhanden Werk');
      set @FoutNr = 2;
    end if;
    //MR 20-aug-2010 bug #32672: En ophalen of er een referentie dient te komen
    select RksInvoer , ReferentieVerplicht into @RksInvoerOHW,@ReferentieVerplichtOHW from tabRekeningSchema where RksGid = @RksGid;
  end if;


  // ### Maak journaalpost geopend aan ###
  // -------------------------------------
  if @FoutNr = 0 then
    //call trace('Maak JP');
    call BoekstuknummerGenereren(@@BjGid, @DgbGid, @BoekStukNummer);
    if IsNull(@BoekStukNummer, 0) = 0 then
      call BoekstuknummerPlusEen(@BjGid, @DgbGid, 1, @BoekstukNummer);
    end if;

    if @PbkHerkomst in (5,6) then
      set @Oms = if @IsAcceptatie = 0 then _A('Corr.') + ' ' else '' endif + _A('Project') + ' ' + Trim (@ProjCode) + if @IsAcceptatie = 0 then ' ' + _A('weekst') + ' '  else ' ' + _A('weekstaat')  + ' '   endif + String(@PbkVolgNummer);
    else
      set @Oms = if @IsAcceptatie = 0 then _A('Corr.') + ' ' else '' endif + _A('Project') + ' ' + Trim (@ProjCode) + if @IsAcceptatie = 0 then ' ' + _A('prjmut') +  ' ' else ' ' + _A('projmutatie') +  ' ' endif + String(@PbkVolgNummer);
    end if;

    // Hier ook al toevoegen, i.v.m. stuknummer verhoging
    insert into tabJournaalPost(JpBoekGangGid, JpBjGid, JpPerNr, JpDgbGid, BoekStukNummer,  OmsJournaalpost, BoekDatum,          JpIsInGebruik)
    values(                     @BoekGangGid,  @@BjGid, @PerNr,  @DgbGid,  @BoekStukNummer, @Oms,            @BoekDatum,         1            );
    set @JpGid = @@Identity;
    //call trace('@JpGid='+string(@JpGid)+', @BoekDatum='+string(@BoekDatum)+', @BjGid='+string(@BjGid)+', @PerNr='+string(@PerNr));
    //call trace('@BoekStukNummer='+string(@BoekStukNummer)+', @Oms='+@Oms);

    if @PbkHerkomst in (5,6) then
      set @Oms = _A('Project %1! weekstaat %2!',   Trim(@ProjCode), String(@PbkVolgNummer));
    else
      set @Oms = _A('Project %1! projmutatie %2!', Trim(@ProjCode), String(@PbkVolgNummer));
    end if;
  end if;


  // ##### Debetboekingen van de REGELS als totaal #####
  // --------------------------------------------------

  // ### Maak boeking ONDERHANDEN WERK (per opbrengstgroep i.v.m. herwaardering voorraad-afboeking!)
  if @FoutNr = 0 then
      insert into tabProjectBoekingJournaal(
            pbjPbrGid, PbjBoekDatum, PbjDagboekCode,       PbjStukNr,              PbjRekeningDebet,
            PbjAantalJournaalOHW,    PbjBedragJournaalOHW, PbjBedragHerwaardering,
            PbjAangemaaktDoor,       PbjAangemaaktOp)
      select PbrGid,   @BoekDatum,   @DgbCode,       @BoekstukNummer, @RksInvoerOHW,
             (if PbSoort = 0 /*Regie*/    then (PbrAantalDeclarabel * PbrPartFactEenheidFactor)
                             /*Overigen*/ else PbrAantalGeboekt endif
              // - PbrAantalOpFactuurVoorstel Deze moet er NIET af!
             ) * @MinTeken AantalOHW,
             round(
              (AantalOHW * PbrKostprijs   / PbrPrijsPer) *
              (if PbSoort = 0 /*Regie*/ and IsNull (PbrDoorbelastPercentage, 100) < 100 then (PbrDoorbelastPercentage / 100) else 1 endif),
              @AantDecBedrag
             ) BedragOHW,
             BedragOHW - round(AantalOHW * IsNull(ArtPartijKostprijsEx,ArtKostprijsEx) / ArtPrijsPer, @AantDecBedrag) BedragHerwaarderingOHW,
             @AangemaaktDoor, @AangemaaktOp
      from   tabProjectBoekingsRegel
             inner join tabProjectBoom on (PbGid = PbrPbGid)
             inner join tmpProjectGoedkeurSelectie on (tmpPgsPbrGid = PbrGid)
             left outer join tabArtikel on (ArtGid = PbrArtGid and PbrIsDirecteInkoop = 0 and PbrMutSoort = 2 /*artikel*/)
             left outer join tabArtikelPartij on  ArtPartijGid = PbrArtPartijGid and (ArtIsPartijRegistreren = 1 and ArtIsPartijAparteKostPrijs = 1)
      where  tmpPgsSessie = @SessieNr and tmpPgsStatus = 1 and PbrPbkGid = @PbrPbkGid and pbrProjGid = @ProjGid
             and (   (BedragOHW <> 0)
                  or (AantalOHW <> 0)
                  or (BedragHerwaarderingOHW <> 0)
                 )
             and (PbrMutatieDatum between @VanDatum and @TotDatum)
      group by
             PbrGid, AantalOHW, BedragOHW, BedragHerwaarderingOHW;

  end if;

  // ##### KOSTPRIJS en CREDITboekingen van de REGELS #####
  // ------------------------------------------------------
  // Definities:
  // @KostprijsRegelTotaal               = round(AantalGeboekt * PbrKostprijs / PbrPrijsPer) [is al in veld PbrKostprijsRegelTotaal opgeslagen!]
  // @AantalDeclarabelInArtEenheid       = Regieproject? -> round(PbrAantalDeclarabel * PbrPartFactEenheidFactor, ArtAantDecAantallen)
  //                                       anders?       -> PbrAantalGeboekt
  // @KostprijsOHW                       = round(@AantalDeclarabelInArtEenheid * PbrKostprijs / PbrPrijsPer)
  // @KostprijsKP                        = PbrKostprijsRegelTotaal - @KostprijsOHW
  // @KostprijsRegelTotaalInArtKostprijs = round(PbrAantalGeboekt * ArtKostprijs / ArtPrijsPer)
  // @HerwaarderingTotaal                = PbrKostprijsRegelTotaal - @KostprijsRegelTotaalInArtKostprijs
  // @HerwaarderingOHW                   = @KostprijsOHW - round(@AantalDeclarabelInArtEenheid * ArtKostprijs / ArtPrijsPer)
  // @HerwaarderingKP                    = @HerwaarderingTotaal - @HerwaarderingOHW

  //call trace('Start lus per regel');
  if @FoutNr = 0 then
    for @Cursor AS Cursor_ProjectRegels CURSOR FOR
      select
        PbrGid               @CurPbrGid,
        PbSoort              @CurPbSoort,
        PbrMutSoort          @CurPbrMutSoort,
        OpbrGrpNummer        @CurOpbrGrpNummer,
        ArtOpbrGrpGid        @CurOpbrGrpGid,
        NawFilFonID          @CurNawFilFonID,
        NawFilNummer         @CurNawFilNummer,
        PbrIsDirecteInkoop   @CurIsDirecteInkoop,
        PbkVolgnummer        @CurPbkVolgnummer,
        PbrLeverancierNawGid @CurLeverancierNawGid, /* t.b.v. directe inkoop */
        (PbrAantalGeboekt - (PbrAantalDeclarabel * PbrPartFactEenheidFactor)) * @MinTeken @CurAantalNietDeclarabel, // alleen t.b.v. boeken van de kostprijs (debet)
        (PbrKostprijsRegelTotaal -
          round(
           (PbrAantalDeclarabel * PbrPartFactEenheidFactor) *
           PbrKostprijs *
           (if PbSoort = 0 /*Regie*/ and IsNull (PbrDoorbelastPercentage, 100) < 100 then (PbrDoorbelastPercentage / 100) else 1 endif)
           / PbrPrijsPer,
          @AantDecBedrag)) * @MinTeken @CurBedragNietDeclarabel,
        RksInvoer            @CurRekeningHerwaardering,
        // Berekeningen t.b.v. herwaardering KP (Zie definities)
        round(if PbSoort = 0 /*Regie*/    then (PbrAantalDeclarabel * PbrPartFactEenheidFactor)
                             /*Overigen*/ else PbrAantalGeboekt endif
             ,ArtAantDecAantallen) * @MinTeken                                                                                                                                     @CurAantalDeclarabelInArtEenheid,
        round(@CurAantalDeclarabelInArtEenheid * PbrKostprijs / PbrPrijsPer, @AantDecBedrag)                                                                                       @CurKostprijsOHW,
        round(PbrAantalGeboekt * IsNull(ArtPartijKostprijsEx, ArtKostprijsEx) / ArtPrijsPer, @AantDecBedrag) * @MinTeken                                                                                         @CurKostprijsRegelTotaalInArtKostprijs,
        if PbrIsDirecteInkoop = 0 and PbrMutSoort = 2 then (PbrKostprijsRegelTotaal * @MinTeken - @CurKostprijsRegelTotaalInArtKostprijs) else 0 endif                             @CurHerwaarderingTotaal,
        if PbrIsDirecteInkoop = 0 and PbrMutSoort = 2 then @CurKostprijsOHW - round(@CurAantalDeclarabelInArtEenheid * IsNull(ArtPartijKostprijsEx, ArtKostprijsEx) / ArtPrijsPer, @AantDecBedrag) else 0 endif  @CurHerwaarderingOHW,
        @CurHerwaarderingTotaal - @CurHerwaarderingOHW                                                                                                                             @CurHerwaarderingKP
      from   tmpProjectGoedkeurSelectie
             inner join tabProjectBoekingsRegel on (pbrGid = tmpPgsPbrGid)
             inner join tabProjectBoom          on (PbGid = PbrPbGid)
             inner join tabProjectBoekingsKop   on (PbkGid = PbrPbkGid)
             inner join (tabArtikel
                        left outer join tabOpbrengstgroepSoort on (GrpSoortGrpGId = ArtOpbrGrpGId and GrpSoortParSoort = 80 /*herwaardering*/)
                        left outer join tabRekeningschema on (RksGid = GrpSoortRksGID)
                        ) on (ArtGid = PbrArtGid)
             left outer join tabArtikelPartij on  ArtPartijGid = PbrArtPartijGid and (ArtIsPartijRegistreren = 1 and ArtIsPartijAparteKostPrijs = 1)
             inner join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGid)
             left outer join tabRelatie   on (RelGid = PbrRelGid)
             left outer join tabNawFile   on (   (NawFilNawGid = RelNawGid and NawFilFonID='C')
                                              or (PbrIsDirecteInkoop = 1 and NawFilNawGid = PbrLeverancierNawGid and NawFilFonID='C'))

      where  tmpPgsSessie = @SessieNr and tmpPgsStatus = 1 and PbrPbkGid = @PbrPbkGid and PbrProjGid = @ProjGid
             and (PbrMutatieDatum between @VanDatum and @TotDatum)
    for read only
    do
      //call trace('In lus; @CurOpbrGrpGid='+string(@CurOpbrGrpGid));
      //call trace('@CurAantalDeclarabelInArtEenheid='+string(@CurAantalDeclarabelInArtEenheid)+', @CurKostprijsOHW='+string(@CurKostprijsOHW)+', @CurKostprijsRegelTotaalInArtKostprijs='+string(@CurKostprijsRegelTotaalInArtKostprijs)+', @CurHerwaarderingTotaal='+string(@CurHerwaarderingTotaal)+', @CurHerwaarderingOHW='+string(@CurHerwaarderingOHW)+', @CurHerwaarderingKP='+string(@CurHerwaarderingKP));


      // Herwaarderingsrekening uitlezen indien nodig (wordt later in de tussentabel gezet)
      // Uiteraard ALLEEN bij een echt artikel!
      if @CurHerwaarderingOHW <> 0 or @CurHerwaarderingKP <> 0 then
        call FacturerenLeverMaakRekeningObvOpbrGroep(@CurOpbrGrpGid, 80, @RksGid); // *Herwaardering* (o.b.v.opbrengstgroep van de artikelen)
        if @RksGid is null then
          set @FoutCode = _U('paragraaf t.b.v. herwaardering');
          set @FoutNr = 4; // Paragraaf ... niet gevonden
          //call trace('Oeps! Rekening voor de herwaardering is NIET gevonden!');
        end if;
        select RksInvoer into @RksInvoerHerwaardering from tabRekeningSchema where RksGid = @RksGid;
      else
        set @RksInvoerHerwaardering = null;
      end if;

      // ### Maak boeking KOSTPRIJS voor regieprojectonderdelen
      if (@CurPbSoort = 0) and (@FoutNr = 0) and ((@CurAantalNietDeclarabel <> 0) or (@CurBedragNietDeclarabel <> 0) or (@CurHerwaarderingKP <> 0)) then
        if @BoekKostprijsPerOpbrGrp = 0 then
          // Boeken per projectgroep
          set @RksInvoer = @RksInvoerKostprijsProjGrp;
        else
          call FacturerenLeverMaakRekeningObvOpbrGroep(@CurOpbrGrpGid, 190, @RksGid); // *Kostprijs projecten o.b.v. opbrengstgroep*
          if @RksGid is null then
            set @FoutNr = 2;
            set @FoutCode = _U('rekening kostprijs projecten o.b.v. opbrengstgroep %1!', @CurOpbrGrpNummer);
          end if;
          select RksInvoer into @RksInvoer from tabRekeningSchema where RksGid = @RksGid;
        end if;
        if @FoutNr = 0 then
          insert into tabProjectBoekingJournaal
                (pbjPbrGid,  PbjBoekDatum, PbjDagboekCode, PbjStukNr,       PbjRekeningDebet, PbjRekeningHerwaardering,  PbjAantalJournaalKP,      PbjBedragJournaalKP,      PbjBedragHerwaardering, PbjAangemaaktDoor, PbjAangemaaktOp)
          values(@CurPbrGid, @BoekDatum,   @DgbCode,       @BoekstukNummer, @RksInvoer,       @CurRekeningHerwaardering, @CurAantalNietDeclarabel, @CurBedragNietDeclarabel, @CurHerwaarderingKP,    @AangemaaktDoor,   @AangemaaktOp);
        end if;
      end if;

      // Opzoeken tegenrekening o.b.v. mutatiesoort en relatie (indien activiteit, eigen of extern)
      // volgorde:
      // Test Mutatiesoort = artikel -> gebruik rekening *voorraad van de opbrengstgroep*
      // Test Is extern (crediteur) -> gebruik rekening *Te Ontvangen Inkoopfacturen van de vaste gegevens projecten* (met ref. = crediteurnummer)      !@# HIERO!! DEZE IS BIJ AANMAKEN JOURNAALREGEL NIET MEER BEKEND
      // Anders -> gebruik rekening *Dekking activiteiten obv. opbr.groep* of *Dekking activiteiten obv. projectgroep*
      //call trace('Opzoeken tegenrekening');
      if @FoutNr = 0 then
        set @Referentie = '';
        set @RksInvoer = null;

        case
        when isnull(@CurNawFilFonID,'') = 'C' then // @CurIsDirecteInkoop <> 0 then
          // Directe inkoop OF externe medewerker -> ook als zodanig boeken op de tussenrekening met de leverancier als referentie.
          // rekening = TE ONTVANGEN INKOOPFACTUREN (o.b.v. activiteiten externe medewerkers OF activiteiten)
          set @RksInvoer = @RksInvoerInkoopFact;
          if @RksInvoer is null then set @FoutCode = _U('rekening t.b.v. te ontvangen inkoopfacturen (directe inkoop)') end if;
          case
          when @RefVullenMet = 0 then
            set @Referentie = @CurNawFilNummer;
          when @RefVullenMet = 1 then
            set @Referentie = @CurPbkVolgnummer;
          when @RefVullenMet = 2 then
            set @Referentie = @ProjCode;
          end case;
        when @CurPbrMutSoort = 2 then
          // GEEN directe inkoop, wel artikel, dus uit de voorraad plukken
          // Opzoeken rekening VOORRAAD
          call FacturerenLeverMaakRekeningObvOpbrGroep(@CurOpbrGrpGid, 50, @RksGid); // *Voorraden* (o.b.v.opbrengstgroep van de artikelen)
          if @RksGid is null then set @FoutCode = _U('paragraaf t.b.v. voorraden') end if;
          select RksInvoer into @RksInvoer from tabRekeningSchema where RksGid = @RksGid;
        else
          // Geen directe inkoop, ook GEEN artikel, dus uit dekking halen
          // rekening = DEKKING ACTIVITEITEN/MACHINES (per projectgroep OF per opbrengstgroep)
          if @BoekDekkingPerOpbrGrp = 0 then
            // Boeken per projectgroep
            set @RksInvoer = @RksInvoerDekkingTarieven;
          else
            call FacturerenLeverMaakRekeningObvOpbrGroep(@CurOpbrGrpGid, 200, @RksGid); // *Dekking tarieven projecten o.b.v. opbrengstgroep*
            if @RksGid is null then set @FoutCode = _U('paragraaf Dekking tarieven projecten o.b.v. opbrengstgroep') end if;
            select RksInvoer into @RksInvoer from tabRekeningSchema where RksGid = @RksGid;
          end if;
        end case;

        if @RksInvoer is null then
          set @FoutNr = 3; // Te boeken rekening is niet gevonden
        end if;
      end if;
      if @FoutNr = 0 then
        // tabProjectBoekingJournaal updaten
        update tabProjectBoekingJournaal
        set    PbjRekeningCredit        = @RksInvoer,
               PbjReferentie            = @Referentie,
               PbjRekeningHerwaardering = @RksInvoerHerwaardering
        where      (pbjPbrGid         = @CurPbrGid)
               and (PbjBoekDatum      = @BoekDatum)
               and (PbjDagboekCode    = @DgbCode)
               and (PbjStukNr         = @BoekstukNummer)
               and (PbjAangemaaktDoor = @AangemaaktDoor)
               and (PbjAangemaaktOp   = @AangemaaktOp);
      end if;
    // ### Eind lus regels
    end for;
  end if;

  // Boeken in journaalregels
  if @FoutNr = 0 then
    // DebetOHW-boeking EN DebetKP-boeking, daarna creditboeking
    // Referentie kan alleen bij een creditboeking (dus NIET bij de OHW- of KP-boeking)
    set @BoekZijde = 0;
    while @BoekZijde <= 1 loop
    //call trace('Boeken journaalregels!; @BoekZijde='+string(@BoekZijde));
      insert into tabJournaalRegel(
             JrJpGid, IsCreditBoeking, SoortBoeking, JrRksGid,
             JrValutaBedrag,
             JrBasisBedrag,
             JrValNummer,         OmsJournaalRegel, JrReferentie)
      select @JpGid,  @BoekZijde,      0,            RksGid,
             sum(isnull(PbjBedragJournaalOHW,0) + isnull(PbjBedragJournaalKP,0) - if @Boekzijde = 1 then isnull(PbjBedragHerwaardering, 0) else 0 endif),
             sum(isnull(PbjBedragJournaalOHW,0) + isnull(PbjBedragJournaalKP,0) - if @Boekzijde = 1 then isnull(PbjBedragHerwaardering, 0) else 0 endif),
             @@BasisValutaNummer, @Oms,             if @BoekZijde = 1 then PbjReferentie else if (PbjRekeningDebet=@RksInvoerOHW) and (@ReferentieVerplichtOHW=1) then @ProjCode endif endif Referentie
      from            tabProjectBoekingJournaal
           inner join tmpProjectGoedkeurSelectie on (tmpPgsPbrGid = pbjPbrGid)
           inner join tabProjectBoekingsRegel    on (PbrGid       = tmpPgsPbrGid)
           inner join tabRekeningSchema on (RksInvoer = if @BoekZijde = 0 then PbjRekeningDebet else PbjRekeningCredit endif)
      where  tmpPgsSessie = @SessieNr and tmpPgsStatus = 1 and PbrPbkGid = @PbrPbkGid and pbrProjGid = @ProjGid
             and (PbjBoekDatum      = @BoekDatum)
             and (PbjDagboekCode    = @DgbCode)
             and (PbjStukNr         = @BoekstukNummer)
             and (PbjAangemaaktDoor = @AangemaaktDoor)
             and (PbjAangemaaktOp   = @AangemaaktOp)
      group by RksInvoer, RksGid, Referentie
      order by RksInvoer, Referentie;
      set @BoekZijde = @BoekZijde + 1;
    end loop;
    // Als laatste alle herwaarderingsboekingen maken
    //call trace('Boeken herwaarderingsregels');
    insert into tabJournaalRegel(
           JrJpGid, IsCreditBoeking, SoortBoeking, JrRksGid, JrValutaBedrag,                                  JrBasisBedrag,               JrValNummer,         OmsJournaalRegel)
    select @JpGid,  1,               0,            RksGid,   sum(PbjBedragHerwaardering) BedragHerwaardering, sum(PbjBedragHerwaardering), @@BasisValutaNummer, @Oms
    from            tabProjectBoekingJournaal
         inner join tmpProjectGoedkeurSelectie on (tmpPgsPbrGid = pbjPbrGid)
         inner join tabProjectBoekingsRegel    on (PbrGid       = tmpPgsPbrGid)
         inner join tabRekeningSchema on (RksInvoer = PbjRekeningHerwaardering)
    where  tmpPgsSessie = @SessieNr and tmpPgsStatus = 1 and PbrPbkGid = @PbrPbkGid and pbrProjGid = @ProjGid
           and (PbjBoekDatum            = @BoekDatum)
           and (PbjDagboekCode          = @DgbCode)
           and (PbjStukNr               = @BoekstukNummer)
           and (PbjBedragHerwaardering <> 0)
           and (PbjAangemaaktDoor       = @AangemaaktDoor)
           and (PbjAangemaaktOp         = @AangemaaktOp)
    group by RksInvoer, RksGid
    having
           BedragHerwaardering <> 0
    order by RksInvoer;
  end if;


  // ##### Boekingen zijn klaar #####

  if @FoutNr = 0 then
    // ### Sluit journaalpost af
    //call trace('Sluit journaalpost');
    update tabJournaalPost
    set    JpIsInGebruik = 0
    where  JpGid = @JpGid;
    // Als er geen boekingen gemaakt zijn, is de journaalpost nu verdwenen, dus dit hier ook registreren!
    if not exists(select 1 from tabjournaalpost where jpgid = @JpGid) then
      set @JpGid = null;
    end if;
  end if;

  // ##### Voorraadmutaties #####
  // ----------------------------

  if @FoutNr = 0 then
    // ### Begin lus Artikel
    // Projectboekingsregels worden zoveel mogelijk per artikel samengevoegd.
    // Projectboekingsregels met detailregels worden altijd apart uitgevoerd.
    //call trace('Start lus artikel');
    for @Cursor AS CURSOR_Artikel CURSOR FOR
      select   ArtCode                                      @CurArtCode,
               ArtGid                                       @CurArtGid,
               PbrArtPartijGid                              @CurArtPartijGid,
               sum(PbrAantalGeboekt * @MinTeken)            @CurAantalGeboekt, // Moet hier nog een factor-correctie bij?
               ArtPrijsPer                                  @CurArtPrijsPer,
               IsNull(ArtPartijKostprijsEx,ArtKostprijsEx)  @CurArtKostprijsEx,
               PbrMagGid                                    @CurMagGid,
               isnull(PbrLocGid, (select first LocGid from tabLocatie where LocNaam='(Standaard)' and (LocMagGid = PbrMagGid) )) @CurLocGid,
               if exists(select first 1 from tabProjectBoekingsRegelDetail where PbrdPbrGid = PbrGid and PbrdAantal <> 0) then PbrGid endif @CurHeeftDetailRegelsPbrGid,
               PbkVolgnummer @CurPbkVolgnummer
      from     tmpProjectGoedkeurSelectie
               inner join tabProjectBoekingsRegel on (pbrGid = tmpPgsPbrGid)
               inner join tabArtikel              on (ArtGid = PbrArtGid)
               left outer join tabArtikelPartij   on  ArtPartijGid = PbrArtPartijGid and (ArtIsPartijRegistreren = 1 and ArtIsPartijAparteKostPrijs = 1)
               inner join tabProjectBoekingsKop   on (PbkGid = PbrPbkGid)
      where    tmpPgsSessie = @SessieNr and tmpPgsStatus = 1 and PbrPbkGid = @PbrPbkGid and PbrProjGid = @ProjGid
               and (PbrMutatieDatum between @VanDatum and @TotDatum)
               and (PbrMutSoort = 2) // Artikel
               and (PbrIsDirecteInkoop = 0) // GEEN directe inkoop
      group by ArtCode, ArtGid, PbrArtPartijGid, ArtPrijsPer, @CurArtKostprijsEx, PbkVolgnummer, PbrMagGid, @CurLocGid, @CurHeeftDetailRegelsPbrGid
      having   @CurAantalGeboekt <> 0
      order by ArtCode, @CurHeeftDetailRegelsPbrGid // In volgorde van opbrengstgroep verwerken
    for read only
    do
      // ### Verwerk voorraadmutatieregel voor betreffende artikel
      //call trace('@CurArtGid='+string(@CurArtGid)+', @CurArtPartijGid='+string(@CurArtPartijGid)+', @CurArtKostprijsEx='+string(@CurArtKostprijsEx)+', @CurHeeftDetailRegelsPbrGid='+string(@CurHeeftDetailRegelsPbrGid));

      if @CurArtPartijGid is not null then
        select ArtPartijNummer into @PartijNummer from tabArtikelPartij where ArtPartijGid = @CurArtPartijGid;
      end if;

      insert into tabVoorraadMutatie
             (vrdMutArtGid,        vrdMutDatum,         vrdMutSoort,
              VrdMutNawGid,        VrdMutUitleverOntvangstNr, VrdMutProjGid,       vrdMutValNummer,     vrdMutGeprijsdPer,
              vrdMutPrijsInValuta, vrdMutPrijsInBasis,  vrdMutHistKostprijs,
              vrdMutGebruikerCode, VrdMutJpGid)
      values( @CurArtGid,          @BoekDatum,          8,
              @NawGidProject,      @CurPbkVolgnummer,   @ProjGid,            @@BasisValutaNummer, @CurArtPrijsPer,
              @CurArtKostprijsEx,  @CurArtKostprijsEx,  @CurArtKostprijsEx,
              @@GebruikerCode,     @JpGid);
      set @VrdMutGid = @@Identity;

      if @CurHeeftDetailRegelsPbrGid is null then
        // Het aantal van de boekingsregel in dit magazijn en locatie plaatsen
        //call trace('GEEN detail; @CurArtPartijGid='+string(@CurArtPartijGid)+', @CurMagGid='+string(@CurMagGid)+', @CurLocGid='+string(@CurLocGid)+', @CurAantalGeboekt='+string(@CurAantalGeboekt));
        insert into tabVoorraadMutatieLocatieSerie(VrdMutLocVrdMutGid,    VrdMutLocMagGid,      VrdMutLocLocGid,
                                                   VrdMutLocPartijNummer, VrdMutLocAantal)
        values(@VrdMutGid,      @CurMagGid,        @CurLocGid,
               @PartijNummer, -@CurAantalGeboekt);
      else
        // De serienummers van alle boekingsregeldetails van de gevonden projectregel
        // in dit magazijn en locatie plaatsen
        //call trace('WEL detail; @CurArtPartijGid='+string(@CurArtPartijGid)+', @CurMagGid='+string(@CurMagGid)+', @CurLocGid='+string(@CurLocGid));
        insert into tabVoorraadMutatieLocatieSerie(VrdMutLocVrdMutGid,    VrdMutLocMagGid,      VrdMutLocLocGid,
                                                   VrdMutLocPartijNummer, VrdMutLocSerieNummer, VrdMutLocAantal)
        select @VrdMutGid, @CurMagGid, @CurLocGid,
               @PartijNummer, ArtSerienummer, -PbrdAantal * @MinTeken
        from   tabProjectBoekingsRegelDetail
               inner join tabArtikelSerienummer on (ArtSerieGid = PbrdArtSerieGid)
        where  (PbrdPbrGid = @CurHeeftDetailRegelsPbrGid)
          and  (PbrdAantal <> 0.00);


        for @cursor as CURSOR_RegelDetail cursor for
         select
           PbrdArtSerieGid  @CurSerieNummerGid,
           PbrMutatieDatum  @CurRegelMutatieDatum
         from tabProjectBoekingsRegelDetail
         inner join tabProjectBoekingsRegel on PbrGid = PbrdPbrGid
         where PbrdPbrGid = @CurHeeftDetailRegelsPbrGid

         for read only
         do
           // #21201
           call UpdateGarantieSerieNummer(@CurSerieNummerGid, @CurRegelMutatieDatum, 0);
         end for; // ### eind lus Boekingsregeldetail
      end if;

    // ### eind lus artikel
    end for;
  end if;

  if @FoutNr = 0 then

    // ### Alle geboekte regels in de correcte nieuwe status zetten EN aantal op factuurvoorstel aanpassen
    update tabProjectBoekingsRegel
    set    PbrIsGeboekt = if @MinTeken = 1 then 1 else 0 endif,
           PbrStatus    = if @MinTeken = 1 then 3 /*geaccepteerd*/ else 1 /*ingeleverd*/ endif,
           PbrAantalOpFactuurVoorstel = (select sum(pfvlAantal) from tabProjectFactuurVoorstelRealisatie inner join tabProjectFactuurVoorstelRegel on (PfvrGid = pfvlFvrGid) inner join tabProjectFactuurVoorstelKop on (PfvkGid = PfvrPfvkGid) where pfvlPbrGid = PbrGid and pfvkStatus <> 2 /*gefactureerd*/),
           PbrAantalGefactureerd      = (select sum(pfvlAantal) from tabProjectFactuurVoorstelRealisatie inner join tabProjectFactuurVoorstelRegel on (PfvrGid = pfvlFvrGid) inner join tabProjectFactuurVoorstelKop on (PfvkGid = PfvrPfvkGid) where pfvlPbrGid = PbrGid and pfvkStatus =  2 /*gefactureerd*/)
    where  PbrGid in (select tmpPgsPbrGid
                      from   tmpProjectGoedkeurSelectie
                      where      (tmpPgsSessie = @SessieNr and tmpPgsStatus = 1 )
                             and (PbrMutatieDatum between @VanDatum and @TotDatum)
                             and PbrPbkGid = @PbrPbkGid)
           and PbrProjGid = @ProjGid;

    // ### Alle correct verwerkte tmp-regels van dit project opschonen (= verwijderen)
    delete tmpProjectGoedkeurSelectie
    where  tmpPgsGid in (select tmpPgsGid
                         from   tmpProjectGoedkeurSelectie inner join tabProjectBoekingsRegel on (PbrGid = tmpPgsPbrGid)
                         where      (tmpPgsSessie = @SessieNr and tmpPgsStatus = 1 and PbrProjGid = @ProjGid and PbrPbkGid = @PbrPbkGid)
                                and (PbrMutatieDatum between @VanDatum and @TotDatum)
                                and (PbrStatus <> tmpPgsOrigPbrStatus and PbrIsGeboekt <> tmpPgsOrigPbrIsGeboekt)
                        );
  end if;

  //call TraceEind('ProjectenAcceptatieMaakBoekingEnVoorraad > @FoutNr = ' + string(@FoutNr) + ', @FoutCode = ' + @FoutCode);
end;


//$Workfile: ProjectenAcceptatieRegelsOpschonenBijInlog.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// ------------------------------------------------------------------------------------------------------------------
// --- Project accepteren mutaties: Bij inlogfout de veiliggestelde regels t.b.v. accepteren/terughalen opschonen ---
// ------------------------------------------------------------------------------------------------------------------

if exists (select 1 from sys.sysProcedure where proc_name='ProjectenAcceptatieRegelsOpschonenBijInlog') then
  drop procedure ProjectenAcceptatieRegelsOpschonenBijInlog;
end if;

create procedure ProjectenAcceptatieRegelsOpschonenBijInlog(
  in @SessieNr integer
)
begin
  // Bij inloggen is gebleken dat de sessie is verdwenen. Daarom moeten we
  // alle records van tmpProjectGoedkeurSelectie testen op de status.
  // Een status van 1 betekent dat de volgende dingen moeten gebeuren:
  // - Terugzetten van de status van tabProjectBoekingsRegel indien die status op 3 (geaccepteerd) staat
  // - Verwijderen van de tijdelijke regels (zodat dezen niet nogmaals ongedaan kunnen worden gemaakt)
  set @@ErrorTextProcedure = 'ProjectenAcceptatieRegelsOpschonenBijInlog > @SessieNr='+String(@SessieNr);
  //call TraceBegin(@@ErrorTextProcedure);

  // Terugzetten status van regels in tabProjectBoekingsRegel naar Ingeleverd
  update tabProjectBoekingsRegel
  set    PbrStatus    = tmpPgsOrigPbrStatus,
         PbrIsGeboekt = tmpPgsOrigPbrIsGeboekt
  from   tabProjectBoekingsRegel inner join tmpProjectGoedkeurSelectie on (tmpPgsPbrGid = PbrGid)
  where      (PbrStatus    = 3) // Geaccepteerd
         and (PbrIsGeboekt = 0) // maar nog niet geboekt
         and (tmpPgsSessie = @SessieNr and tmpPgsStatus = 1 /*Regel ingebruik genomen*/);

  // Verwijderen van alle regels uit tmpProjectGoedkeurSelectie van de verloren connectie
  delete tmpProjectGoedkeurSelectie where tmpPgsSessie = @SessieNr;

  set @@ErrorTextProcedure = 'ProjectenAcceptatieRegelsOpschonenBijInlog';
  //call TraceEind(@@ErrorTextProcedure);

end;


// --------------------------------------------------------------------------------------------------
// --------- Project accepteren mutaties: Veiligstellen regels t.b.v. accepteren/terughalen ---------
// --------------------------------------------------------------------------------------------------

create or replace procedure ProjectenAcceptatieRegelsVaststellen(
  in @SessieNr integer,
  in @IsAcceptatie integer, // 0 = terughalen, 1 = accepteren
  in @ProjLeiderRelGid integer,
  out @AantalRegelsNietGeselecteerd integer // Geeft het aantal regels aan dat niet kon worden geselecteerd (door anderen gewijzigd)
)

begin
  // Aanpassen van alle projectmutatieregels vanaf de (tijdelijke) vinkentabel:
  // Als geldt dat de status=Ingeleverd:
  //   Zet de status op Geaccepteerd (of andersom, afhankelijk van de keuze voor acceptatie of terughalen)
  declare @AantalRegels          integer;
  declare @VerwachtStatusOrig    smallint;
  declare @VerwachtIsGeboektOrig smallint;
  declare @TotaalGeboektInDetail numeric(20,8);
  declare @MinDatum              DateTime;
  declare @MaxDatum              DateTime;

  set @@ErrorTextProcedure = 'ProjectenAcceptatieRegelsVaststellen > @SessieNr='+String(@SessieNr)+', @IsAcceptatie='+string(@IsAcceptatie);
  //call TraceBegin(@@ErrorTextProcedure);

  // Initiele waarden zetten
  set @AantalRegelsNietGeselecteerd = 0;
  set @AantalRegels                 = 0;

  if @IsAcceptatie = 1 then
    // Acceptatie -> Originele status = concept, ingeleverd of afgekeurd, nieuwe status wordt geaccepteerd
    set @VerwachtStatusOrig = 1; // Hiermee wordt gekeken naar status 0, 1 en 2
    set @VerwachtIsGeboektOrig = 0;
  else
    // terughalen -> Originele status = geaccepteerd, nieuwe status wordt ingeleverd
    set @VerwachtStatusOrig = 3;
    set @VerwachtIsGeboektOrig = 1;
  end if;

  select min(Begindatum), max(einddatum) into @MinDatum, @MaxDatum from tabPeriode where PerBjGid = @@BjGid;

  //TG 08-01-2010: bug de cursor miste een INSENSITIVE keyword, waardoor de tabellen uit de cursor door het update-statement binnen de cursor gevoelig zijn voor aanpassingen.
  //MR 08-mei-2008 bug #27687: GebruikerGid invullen als het recht uitstaat.
  //MR 25-mar-2014 bug #37293: GebruikerGid vervangen door ProjLeiderRelGid.
  //call trace('@IsAcceptatie='+string(@IsAcceptatie)+', @VerwachtStatusOrig='+String(@VerwachtStatusOrig)+', @VerwachtIsGeboektOrig='+string(@VerwachtIsGeboektOrig));
  for @Regels AS CURSOR_ProjectMutRegels INSENSITIVE CURSOR FOR
    select tmpPgsGid @tmpPgsGid, tmpPgsPbrGid @PbrGid,
           PbrStatus @PbrStatus, PbrIsGeboekt @PbrIsGeboekt,
           PbrAantalGeboekt @PbrAantalGeboekt,
           if PbrIsDirecteInkoop = 1 or ArtSerieNrRegistreren = 0 then 0 else 1 endif @MetDetailRegels,
           if PbrIsDirecteInkoop = 0 and PbrArtPartijGid is null and ArtIsPartijRegistreren=1 then 1 else 0 endif @CurPartijOnGeldig
    from   tmpProjectGoedkeurSelectie
           left outer join (tabProjectBoekingsRegel  inner join tabProject on (ProjGid = pbrProjGid)
              and (@ProjLeiderRelGid = -1  or ProjProjLeiderRelGid = @ProjLeiderRelGid)
              ) on (pbrGid = tmpPgsPbrGid)
           left outer join tabArtikel on (ArtGid = PbrArtGid)
    where     (tmpPgsSessie = @SessieNr )
          and (tmpPgsStatus = 0)
          and not exists(select first 1 from tabProjectFactuurVoorstelRealisatie where pfvlPbrGid = PbrGid )
          and PbrMutatieDatum between @MinDatum and @MaxDatum
  for read only
  do
    if @MetDetailRegels = 0 then
      set @TotaalGeboektInDetail = @PbrAantalGeboekt;
    else
      select IsNull(sum(PbrdAantal),0) into @TotaalGeboektInDetail from tabProjectBoekingsRegelDetail where PbrdPbrGid = @PbrGid;
    end if;

    // Controleer eerst of de status goed is
    if     (   (@VerwachtStatusOrig = 1 and @PbrStatus in (0, 1, 2))  // Beperkende controles (stopt de verdere bewerking)
            or (@VerwachtStatusOrig = @PbrStatus))
       and (@PbrIsGeboekt = @VerwachtIsGeboektOrig)
       then
      // Status is goed!!
      // Onthouden dat de projectregel is genomen en de originele status van de projectregel
      if     (@PbrAantalGeboekt = @TotaalGeboektInDetail)             // Niet beperkende controles (alleen deze regel wordt niet geselecteerd; de rest  gaat door)
         and (@CurPartijOnGeldig = 0) then
       // Alleen in gebruik nemen als het aantal in de detailregels gelijk is aan geboekte
        update tmpProjectGoedkeurSelectie
        set    tmpPgsStatus = 1,                     // Regel ingebruik nemen gelukt
               tmpPgsOrigPbrStatus    = @PbrStatus,  // Oorspronkelijke status van de projectmutatieregel onthouden
               tmpPgsOrigPbrIsGeboekt = @PbrIsGeboekt
        where  tmpPgsGid = @tmpPgsGid;

        // status omgooien en regeltje aanmaken
        update tabProjectBoekingsRegel
        set    PbrStatus = 3,   // ALTIJD op geaccepteerd zetten (wordt eventueel teruggedraaid bij het eruit knallen)
               PbrIsGeboekt = 0 // ALtijd op niet-geboekt zetten (wordt eventueel teruggedraaid bij het eruit knallen)
        where  PbrGid = @PbrGid;
      end if;

    else
      // Status is niet goed!! -> regel van de vinkenlijst updaten met een status *selectie niet gelukt*
      update tmpProjectGoedkeurSelectie
      set    tmpPgsStatus = 0 /*Regel ingebruik nemen fout, dus weer op oorspronkelijk zetten*/
      where  tmpPgsGid = @tmpPgsGid;
      set @AantalRegelsNietGeselecteerd = @AantalRegelsNietGeselecteerd + 1;
    end if;
  end for;

  select count(tmpPgsSessie) into @AantalRegels
  from tmpProjectGoedkeurSelectie
  where tmpPgsSessie = @SessieNr;

  //MR 15-feb-2016 defect #47109: Alleen als alles fout gaat doorgeven.
  if @AantalRegels > @AantalRegelsNietGeselecteerd then
    set @AantalRegelsNietGeselecteerd = 0;
  end if;

  set @@ErrorTextProcedure = 'ProjectenAcceptatieRegelsVaststellen';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProjectenAfkeurenProjectMutaties.sp $ $Revision: 4 $ $Modtime: 11/07/07 1:42p $'

// ------------------------------------------------
// --------- Afkeuren van projectmutaties ---------
// ------------------------------------------------

if exists (select 1 from sys.sysProcedure where proc_name='ProjectenAfkeurenProjectMutaties') then
  drop procedure ProjectenAfkeurenProjectMutaties;
end if;

create procedure ProjectenAfkeurenProjectMutaties(
  in  @SessieNr     integer
)

begin
  set @@ErrorTextProcedure = 'ProjectenAfkeurenProjectMutaties';
  //call TraceBegin(@@ErrorTextProcedure);

  // Doorlopen van alle selectieregels van deze sessie en pas alle statussen aan indien mogelijk
  // Aanpassen van tabProjectBoekingsRegel mogelijk indien:
  // - Status = Ingeleverd
  // - er is GEEN tabProjectFactuurRegel aan de mutatieregel geknoopt
  // Als status aangepast, dan tmpProjectGoedkeurSelectie-regel verwijderen
  for @Cursor AS CURSOR_Boekingsregels CURSOR FOR
    select
      tmpPgsGid @CurtmpPgsGid,
      PbrGid    @CurPbrGid
    from   tmpProjectGoedkeurSelectie
           inner join tabProjectBoekingsRegel on (pbrGid = tmpPgsPbrGid)
    where  tmpPgsSessie = @SessieNr and pbrStatus = 1 /*ingeleverd*/ and pbrIsGeboekt = 0
           and tmpPgsStatus = 0
           and not exists(select first 1 from tabProjectFactuurVoorstelRealisatie where pfvlPbrGid = PbrGid)
           and not exists(select first 1 from tabJournaalregel                    where jrPbrGid   = PbrGid)

  for read only
  do
    Update tabProjectBoekingsRegel
    set    pbrStatus = 2 /*afgekeurd*/
    where  PbrGid = @CurPbrGid;

    delete tmpProjectGoedkeurSelectie where tmpPgsGid = @CurtmpPgsGid;

  end for;

  set @@ErrorTextProcedure = 'ProjectenAfkeurenProjectMutaties';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck.sp $ $Revision: 4 $ $Modtime: 30-06-09 13:36 $'

// *** Opnieuw invullen van Verkoopprijs, PrijsPer en Aantal in factuurvoorstelregel ***

if exists (select 1 from sys.sysProcedure where proc_name='ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck') then
  drop procedure ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck;
end if;

create procedure ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck(
  in  @PfvrGid integer
)
begin
  declare @Aantal             numeric(20,8); // Aantal stuks te verwerken
  declare @Verkoopprijs       numeric(15,3); // Tegen deze verkoopprijs (Alleen geldig indien @AantalVerkPrijzen=1)
  declare @PrijsPer           numeric(15,3); // en deze PrijsPer (Alleen geldig indien @AantalPrijzenPer=1)
  declare @VerkoopWaarde      numeric(15,3); // Regeltotaal van de voorstelregel [round(sum(aantal * verkoopprijs / PrijsPer), @AantDecBasisVal)]
  declare @AantalVerkPrijzen  integer;       // Aantal verschillende verkoopprijzen van de mutatieregels voor deze voorstelregel
  declare @AantalPrijzenPer   integer;       // Aantal verschillende prijs-per van de mutatieregels voor deze voorstelregel
  declare @MutSoort           smallint;      // Mutatiesoort van de voorstelregel
  declare @ArtGidVasteGeg     integer;       // Tarief uit de vaste gegevens van het mutatiesoort van de voorstelregel
  declare @AantDecPrijsVast   smallint;      // Aantal decimalen verkoopprijs van tarief uit vaste gegevens
  declare @AantDecAantalVast  smallint;      // Aantal decimalen aantal       van tarief uit vaste gegevens
  declare @AantDecBasisVal    smallint;      // Aantal decimalen regel van de basisvaluta (t.b.v. afronden van regeltotaal)
  declare @IsAantalEnPrijzenGeldig smallint; // Resultaat: 1 = er is 1 verkoopprijs EN 1 prijs-per EN maximum aantal decimalen past in aantal decimalen volgens vaste gegevens

  set @@ErrorTextProcedure = 'ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck > @PfvrGid='+String(@PfvrGid);
  //call TraceBegin(@@ErrorTextProcedure);

  // Aantal decimalen t.b.v. afronding van het regeltotaal
  select first DecimalenRegel*2 into @AantDecBasisVal from tabValuta where IsBasisValuta = 1;

  // Berekening van alle regelgegevens (Moet helaas in 2 aparte queries)
  select   count(distinct PbrVerkoopprijs) into @AantalVerkPrijzen from tabProjectFactuurVoorstelRealisatie inner join tabProjectBoekingsRegel on (pbrGid = pfvlPbrGid) where pfvlFvrGid = @PfvrGid;
  select   count(distinct PbrPrijsPer    ) into @AantalPrijzenPer  from tabProjectFactuurVoorstelRealisatie inner join tabProjectBoekingsRegel on (pbrGid = pfvlPbrGid) where pfvlFvrGid = @PfvrGid;

  // Meer dan 1 verkoopprijzen of prijs-per, dan kunnen de aantallen/prijzen nooit geldig zijn! Daarop controleren dus
  if isnull(@AantalVerkPrijzen, 0) > 1 or isnull(@AantalPrijzenPer, 0) > 1 then  // RS 17-2-06 : moest dat geen OR zijn dan... ?
    set @IsAantalEnPrijzenGeldig = 0
  else
    set @IsAantalEnPrijzenGeldig = 1;
  end if;

  // En dan nu de prijzen berekenen
  select   PbrMutSoort, sum(pfvlAantal), if @IsAantalEnPrijzenGeldig = 1 then min(PbrVerkoopprijs) endif, if @IsAantalEnPrijzenGeldig = 1 then min(PbrPrijsPer) endif, round(sum(pfvlAantal * PbrVerkoopprijs / PbrPrijsPer), @AantDecBasisVal)
  into     @MutSoort,   @Aantal,         @Verkoopprijs,        @PrijsPer,        @VerkoopWaarde
  from     tabProjectFactuurVoorstelRealisatie
           inner join tabProjectBoekingsRegel on (pbrGid = pfvlPbrGid)
  where    pfvlFvrGid = @PfvrGid
  group by PbrMutSoort;
  //call trace('@Aantal='+string(@Aantal)+', @Verkoopprijs='+string(@Verkoopprijs)+', @PrijsPer='+string(@PrijsPer)+', @PfvrGid='+string(@PfvrGid));


  // Aantal decimalen opvragen en vergelijken
  if @IsAantalEnPrijzenGeldig = 1 then

    // Eerst tarief uit vaste gegevens lezen
    select
      case @MutSoort
        when 0 then ProjVastArtGidActiviteit
        when 1 then ProjVastArtGidMachine
        when 2 then ProjVastArtGidArtikel
      end
    into  @ArtGidVasteGeg
    from
    tabProjectVastegegevens;
    if @ArtGidVasteGeg is null then
      // In vaste gegevens is geen tarief ingevuld! Voor de zekerheid hier dan geen decimalen
      set @AantDecPrijsVast  = 0;
      set @AantDecAantalVast = 0;
    else
      select ArtAantDecPrijzen, ArtAantDecAantallen into @AantDecPrijsVast, @AantDecAantalVast from tabArtikel where ArtGid = @ArtGidVasteGeg;
    end if;

    // Als aantal decimalen van vastegegevens-tarief < aantal decimalen van veld, dan UIT!
      // Decimalen aantal+prijs zijn gelijk aan of kleiner dan die van tarief van de vaste gegevens en ...
      // prijs * aantal afgerond op het aantal dec van de vaste gegevens leidt tot hetzelfde regeltotaal.
      // Maw: 00:20 (20 minuten) = 0.33333333 * 30 euro = 10.00, maar tarief vaste gegevens heeft max 3 dec,
      // dus 0.333 * 30 euro = 9,999. op factuur zou dus 0.333 * 30 euro = 10.000 komen te staan. En dat mag niet!
    set @IsAantalEnPrijzenGeldig = if    (@AantDecPrijsVast  < (select max(ArtAantDecPrijzen  )
                                                                from   tabProjectFactuurVoorstelRealisatie
                                                                       inner join tabProjectBoekingsRegel on (PbrGid = pfvlPbrGid)
                                                                       inner join  tabArtikel on (ArtGid = PbrArtGid)
                                                                where  pfvlFvrGid = @PfvrGid))
                                      or (@AantDecAantalVast < (select max(ArtAantDecAantallen)
                                                                from   tabProjectFactuurVoorstelRealisatie
                                                                       inner join tabProjectBoekingsRegel on (PbrGid = pfvlPbrGid)
                                                                       inner join  tabArtikel on (ArtGid = PbrArtGid)
                                                                where  pfvlFvrGid = @PfvrGid))
                                   or not (((round(round(@Aantal, @AantDecAantalVast) * round(@Verkoopprijs / @PrijsPer, @AantDecPrijsVast),2) = @VerkoopWaarde) and @MutSoort = 0) or (@MutSoort <> 0))
                                   then 0 else 1 endif;
  end if;

  update tabProjectFactuurVoorstelRegel
  set    pfvrAantal                  = @Aantal,
         pfvrVerkoopprijsExclBTW     = @Verkoopprijs,
         pfvrVerkoopWaarde           = @VerkoopWaarde,
         pfvrPrijsPer                = @PrijsPer,
         pfvrIsAantalEnPrijzenGeldig = @IsAantalEnPrijzenGeldig
  where  pfvrGid = @PfvrGid;

  set @@ErrorTextProcedure = 'ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck > @PfvrGid='+String(@PfvrGid);
  //call TraceEind(@@ErrorTextProcedure);

end;


// *********************************************
// ***** Vullen van projectfactuurvoorstel *****
// *********************************************
create or replace procedure ProjectenMaakFactuurVoorstelRegels(
  in  @SessieNr         integer,
  in  @ProjGid          integer,
  in  @PbGidDestination integer, // = NULL, dan volgens indeling van project, anders alle regels aan meegegeven PbGid knopen
                         // PbGid is alleen relevant voor regieprojecten.
  out @FoutNr           integer,
  out @FoutCode         nchar(100)
)
begin
  // Op basis van alle regels die in gebruik zijn genomen (in tmpProjectGoedkeurSelectie)
  // een aanvulling op het factuurvoorstel maken:
  // Zoek relevante regelgegevens op
  // Zoek foreign keys op
  // Zoek in het bestaande factuurvoorstel van het project/de projecten het soort verdichting (per soort regel!)
  // op niveau (dus op welk niveau de regel moet komen)
  // Bepaal o.b.v. de verdichting de benodigde factuurvoorstelregels
  // Indien bestaande factuurvoorstelregel is gevonden:
  // - Controleer of de prijs per eenheid gelijk is; zonee, prijs en aantal leegmaken en alleen het regeltotaal onthouden
  // - Aanvullen van de bestaande regel

  // Projectgegevens
  declare @ProjNawGid              integer;
  declare @TaalGid                 integer;

  // Gegevens voor de factuurvoorstelkop
  declare @pfvkGid                 integer;
  declare @pfvkStatus              integer;
  declare @pfvkVoorstelNr          numeric(10,0);
  declare @DefFactStatus           smallint;
  declare @BtcNummer               integer;
  declare @LvcNummer               integer;
  declare @IsInkoopCombinatie      integer;
  declare @nawGidFactuur           integer;
  declare @NawGidOmzet             integer;
  declare @NawGidPrijzen           integer;

  set @@ErrorTextProcedure = 'ProjectenMaakFactuurVoorstelRegels > @SessieNr='+String(@SessieNr);
  //call TraceBegin(@@ErrorTextProcedure);

  // Defaults instellen
  set @FoutNr = 0;

  // Projectgegevens uitlezen
  select ProjNawGid
  into   @ProjNawGid
  from   tabProject
  where  ProjGid = @ProjGid;

  // NAW-gegevens opvragen
  select NawTaalGid
  into   @TaalGid
  from   tabNaw
  where  NawGid = @ProjNawGid;

  // #######################################
  // ### Bepaal (nieuwe) factuurvoorstel ###
  // #######################################

  // Eerst opzoeken van een bestaande factuurvoorstel op het project
  // Indien het gevonden factuurvoorstel de status *Vrijgegeven* heeft, dan afbreken!
  // Negeer hierbij de al gefactureerde voorstellen (maak dan gewoon een nieuwe aan)
  // Indien niet gevonden, dan aanmaken
  select pfvkGid,  pfvkStatus,  pfvkVoorstelNr
  into   @pfvkGid, @pfvkStatus, @pfvkVoorstelNr
  from   tabProjectFactuurVoorstelKop
  where  pfvkProjGid = @ProjGid and not PfvkStatus in (2, 3);

  if @pfvkGid is null then
    // Bestaat niet -> factuurvoorstelkop aanmaken

    // Vervolgens het voorstel toevoegen
    select first ProjVastDefaultStatusFactuurVoorstel into @DefFactStatus from tabProjectVastegegevens;

    //Haal het BtcNummer en het LvcNummer op
    select isNull(ProjBtcNummer,NawFilBtcNummer), isNull(ProjLvcNummer,NawFilLvcNummer), ProjIsInkoopCombinatie, ProjnawGidFactuur, ProjNawGidOmzet, ProjNawGidPrijzen
    into @BtcNummer, @LvcNummer, @IsInkoopCombinatie, @nawGidFactuur, @NawGidOmzet, @NawGidPrijzen
    from tabProject
    inner join tabNaw on NawGid = ProjNawGid
    inner join tabNawFile on NawFilNawGid = NawGid
    where ProjGid = @ProjGid;

    insert into tabProjectFactuurVoorstelKop(pfvkNawGid, pfvkProjGid, pfvkStatus, pfvkAangemaaktDoor, pfvkAangemaaktOp, pfvkBtcNummer,pfvkLvcNummer, PfvkIsInkoopCombinatie, PfvknawGidFactuur, PfvkNawGidOmzet, PfvkNawGidPrijzen)
    values(@ProjNawGid, @ProjGid, @DefFactStatus, @@GebruikerCode, now(), @BtcNummer, @LvcNummer, @IsInkoopCombinatie, @nawGidFactuur, @NawGidOmzet, @NawGidPrijzen);
    set @pfvkGid = @@Identity;
  else
    // Controleer status; indien al Vrijgegeven, dan fout!!
    if @pfvkStatus = 1 then
        set @FoutNr = 1;
        set @FoutCode = _U('factuurvoorstel %1!', String(@pfvkVoorstelNr));
    end if;
  end if;

  // En hier de afsplitsing naar regie of termijnproject ..
  if @FoutNr = 0 then
    //TG 23-07-2009: Onderstaande functies allebei uitvoeren, aangezien een project nu uit zowel regie- als termijnonderdelen kan bestaan. ProjSoort doet niet meer ter zake.
    call ProjectenMaakFactuurVoorstelTermijnRegels(@SessieNr, @ProjGid, @ProjNawGid, @TaalGid, @pfvkGid, @FoutNr, @FoutCode);
    call ProjectenMaakFactuurVoorstelRegieRegels(  @SessieNr, @ProjGid, @ProjNawGid, @TaalGid, @pfvkGid, @PbGidDestination, @FoutNr, @FoutCode);
  end if;

//TG 30-06-2009: Dit kan uitgeschakeld worden (ovv PG), omdat de controles nu wel goed in ProjectenMaakFactuurVoorstelRegieRegels.sp uitgevoerd worden (en het achteraf dus overbodig geworden is).
/*
  if @ProjSoort = 0 then // 28827
    for @Cursor AS CURSOR_VoorstelRegels CURSOR FOR
      select  PfvrGid    @CurPfvrGid
        from  tabProjectFactuurVoorstelRegel
        where PfvrPfvkGid = @pfvkGid
      for read only
      do
        // nav bug 28763
        call  ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck(@CurPfvrGid);
     end for;
  end if;
*/
  set @@ErrorTextProcedure = 'ProjectenMaakFactuurVoorstelRegels';
  //call TraceEind(@@ErrorTextProcedure);
end;

// ********************************************************************************
// ***** Vullen van projectfactuurvoorstel met de geselecteerde mutatieregels *****
// ********************************************************************************
create or replace procedure ProjectenMaakFactuurVoorstelRegieRegels(
  in  @SessieNr   integer,
  in  @ProjGid    integer,
  in  @ProjNawGid integer,
  in  @TaalGid    integer,
  in  @pfvkGid    integer,
  in  @PbGidDestination integer,
  out @FoutNr     integer,
  out @FoutCode   nchar(100)
)
begin
  // Gegevens voor de factuurvoorstelregel
  declare @pfvrGid                     integer;
  declare @PbGidVoorFactRegel          integer;  // Gid waarvoor is gevonden dat de regel op de factuur apart moet worden afgedrukt
  declare @ApartAfdrukkenOpFactuur     integer;  // 0 = NIET apart afdrukken; 1 = wel apart afdrukken van dit regelsoort
  declare @Uitsplitsingsniveau         smallint; // 0 = niet uitgesplitst, 1 = uitgesplitst per opbrengstgroep, 2 = uitgesplitst per activiteit/machine/artikel
  declare @UitsplitsenMedewerker       smallint; // 0 = niet uitsplitsen, 1 = wel uitsplitsen per medewerker (voor deze medewerker)
  declare @FactOpbrGrpGid              integer;
  declare @FactArtGid                  integer;
  declare @FactArtPartijGid            integer;
  declare @FactRelGid                  integer;
  declare @FactBtwCode                 integer;
  declare @FactOms                     nchar(80);
  declare @TekstOpFactuur              long nvarchar;
  declare @RelVolledigeNaam            nchar(40);
  declare @IsEersteOpDezePb            smallint;
  declare @ArtGidVoorTekstOpFactuur    integer;
  // t.b.v. controle op aantal decimalen activiteit/machine/artikel t.o.v. die van de vaste gegevens
  declare @AantDecPrijsVast            smallint; // Aantal decimalen van tarief van vaste gegevens
  declare @AantDecAantalVast           smallint;
  declare @pfvrIsAantalEnPrijzenGeldig smallint;
  declare @tmpPfvrAantal               numeric(20,8);
  declare @tmpPfvrVerkoopprijsExclBTW  numeric(15,3);
  declare @tmpPfvrPrijsPer             numeric(15,3);

  declare @_AfleverLndGid integer;
  Select ProjLndGid into @_AfleverLndGid from tabProject where ProjGid = @ProjGid;

  set @@ErrorTextProcedure = 'ProjectenMaakFactuurVoorstelRegieRegels > @SessieNr='+String(@SessieNr);
  //call TraceBegin(@@ErrorTextProcedure);

  // ##########################################
  // ### Doorlopen van geselecteerde regels ###
  // ##########################################

  for @Cursor AS CURSOR_ProjectBoekingsRegels CURSOR FOR
    select tmpPgsGid       @CurtmpPgsGid,
           PbrGid          @CurPbrGid,
           IsNull(@PbGidDestination, PbrPbGid) @CurPbGid, // Prefereer vaste meegegeven PbGid!
           PbrMutSoort     @CurMutSoort,
           PbrRelGid       @CurRelGid,
           PbrArtGid       @CurArtGid,
           PbrArtPartijGid @CurArtPartijGid,
           PbrVerkoopprijs @CurVerkoopPrijsPeenheid,
           // ACW 04-04-2006 bug 21459: ook reeds gefactureerd eraf halen!
           round(PbrAantalDeclarabel - PbrAantalOpFactuurVoorstel - PbrAantalGefactureerd, 8) @CurTeFacturerenAantal,
           round(@CurTeFacturerenAantal / PbrPrijsPer * PbrVerkoopprijs, 2) @CurTeFacturerenBedrag,
           PbrPrijsPer   @CurPrijsPer,
           ArtOpbrGrpGId @CurOpbrGrpGid,
           ArtBtwCode    @CurBtwCode,
           ArtIsPartijRegistreren @ArtIsPartijRegistreren,
           ArtIsPartijAparteTekstOpFactuur @ArtIsPartijAparteTekstOpFactuur,
           ArtPartijAparteTekstOpFactuurDefault @ArtPartijAparteTekstOpFactuurDefault,
           ArtAantDecPrijzen @CurAantDecPrijsVoorstel,
           ArtAantDecAantallen @CurAantDecAantalVoorstel,
           (select AdrLndGid from tabMagazijn inner join tabAdres on MagAdrGid = AdrGid where MagGid = PbrMagGid) @CurVerzendLndGid
    from   tmpProjectGoedkeurSelectie
           inner join tabProjectBoekingsRegel on (pbrGid = tmpPgsPbrGid and pbrProjGid = @ProjGid and PbrStatus = 3)
           inner join tabArtikel              on (ArtGid = pbrArtGid)
    where  tmpPgsStatus = 0 and tmpPgsSessie = @SessieNr
           and not exists(select first 1  // Alleen regels die nog NIET aan deze factuur zijn gekoppeld
                          from   tabprojectfactuurvoorstelrealisatie
                                 inner join tabprojectfactuurvoorstelregel on (pfvrGid = pfvlFvrGid)
                          where  pfvrPfvkGid = @PfvkGid and PfvlPbrGid = PbrGid
                         )
  for read only
  do
    // Ok, we hebben de in-gebruik-genomen regel te pakken.

    // ############################################################
    // ### Bepaal juiste uitsplitsing en Boom voor factuurregel ###
    // ############################################################
    // Opzoeken van verdichting van de PbGid van de regel; indien niet gevonden, dan van een hogere PbGid
    // omhoog zoeken totdat van de projectboom geen parent meer is gevonden.
    // resultaat is afhankelijk van het soort mutatieregel: activiteit, machine of artikel
    // - Activiteiten/ machine of artikel apart op factuur afdrukken: 0 = niet, 1 = per activiteit of onderdeel part afdrukken
    // - Verdichting activiteit: 0 = niet uitgesplitst, 1 = uitgesplitst per opbrengstgroep, 2 = uitgesplitst per activiteit
    // - Verdichting machines  : 0 = niet uitgesplitst, 1 = uitgesplitst per opbrengstgroep, 2 = uitgesplitst per machine
    // - Verdichting artikel   : 0 = niet uitgesplitst, 1 = uitgesplitst per opbrengstgroep, 2 = uitgesplitst per artikel
    // Zou apart kunnen worden bepaald via deze routine (die nog niet bestaat):

    call ProjectFactuurVoorstelBepaalUitsplitsingsniveau(@CurPbGid, @CurMutSoort, @PbGidVoorFactRegel, @Uitsplitsingsniveau, @UitsplitsenMedewerker);

    if @PbGidDestination is not null then
      set @PbGidVoorFactRegel = @PbGidDestination
    end if;

    // ###########################
    // ### Bepaal uitsplitsing ###
    // ###########################

    // Bepaal bij welke voorstelregel van de gevonden @PbGidVoorFactRegel deze mutatieregel
    // moet worden toegevoegd (dus wel op dit niveau, maar wellicht samenvoegen met bestaande regels)
    case @Uitsplitsingsniveau
      when 0 then // NIET uitsplitsen
        set @FactOpbrGrpGid   = null;
        set @FactArtGid       = null;
        set @FactArtPartijGid = null;
      when 1 then  // uitsplitsen per opbrengstgroep
        set @FactOpbrGrpGid   = @CurOpbrGrpGid;
        set @FactArtGid       = null;
        set @FactArtPartijGid = null;
      when 2 then // uitsplitsen per artikel (+partij)
        set @FactOpbrGrpGid   = null;
        set @FactArtGid       = @CurArtGid;
        set @FactArtPartijGid = @CurArtPartijGid;
    end case;
    if @UitsplitsenMedewerker = 0 then
      set @FactRelGid = null
    else
      set @FactRelGid = @CurRelGid;
    end if;

    // #######################
    // ### Bepaal BTW-code ###
    // #######################
    // Indien BTW-code van de debiteur 0% is, dan deze nemen, anders gewoon de BTW-code van act/mach/art (de default BTWcode van tabArtikel)
    set @FactBtwCode = GeefBtwCodeVerkoop(@ProjNawGid, @CurArtGid, @CurArtPartijGid, @_AfleverLndGid, @CurVerzendLndGid);

    // #############################################################
    // ### Opzoeken van factuurvoorstelregel o.b.v. uitsplitsing ###
    // #############################################################
    // o.b.v. pfvkGid, PbGidVoorFactRegel, BtwCode, PmwGid, ArtGid, ArtPatijGid, OpbrGrpGid, MutSoort)
    set @pfvrGid = null;
    select pfvrGid
    into   @pfvrGid
    from   tabProjectFactuurVoorstelRegel
    where      (pfvrPfvkGid = @PfvkGid)
           and (PfvrPbGid = @PbGidVoorFactRegel)
           and (PfvrBtwCode = @FactBtwCode)
           and (IsNull(PfvrPmwGid, @FactRelGid-1, 0) = IsNull( @FactRelGid, PfvrPmwGid + 1, 0)) // Constructie nodig omdat geldt 1=1 maar ook NULL=NULL
           and (IsNull(PfvrArtGid, @FactArtGid-1, 0) = IsNull( @FactArtGid, PfvrArtGid + 1, 0))
           and (IsNull(PfvrArtPartijGid, @FactArtPartijGid-1, 0) = IsNull( @FactArtPartijGid, PfvrArtPartijGid + 1, 0))
           and (IsNull(PfvrOpbrGrpGid, @FactOpbrGrpGid-1, 0) = IsNull( @FactOpbrGrpGid, PfvrOpbrGrpGid + 1, 0))
           and (PfvrMutSoort = @CurMutSoort);


    // ****************************************************************
    // *** Bepaal tarief en aantal decimalen volgens vaste gegevens ***
    // ****************************************************************
    // Dit tarief wordt OOK gebruikt t.b.v. de tekst op factuur (afhankelijk van uitsplitsingsniveau)
    select
      case @CurMutSoort
        when 0 then ProjVastArtGidActiviteit
        when 1 then ProjVastArtGidMachine
        when 2 then ProjVastArtGidArtikel
      end into @ArtGidVoorTekstOpFactuur
    from
      tabProjectVastegegevens;

    if @ArtGidVoorTekstOpFactuur is null then
      set @AantDecPrijsVast = 2;
      set @AantDecAantalVast = 2;
    else
      select ArtAantDecPrijzen, ArtAantDecAantallen into @AantDecPrijsVast, @AantDecAantalVast from tabArtikel where ArtGid = @ArtGidVoorTekstOpFactuur;
    end if;
    //call trace('@AantDecPrijsVast='+string(@AantDecPrijsVast)+', @AantDecAantalVast='+string(@AantDecAantalVast));

    // ###########################
    // ### Bepaal omschrijving ###
    // ###########################
    if @pfvrGid is null then
      // Als er al een factuurregel is gevonden, dan hoeft de omschrijving niet meer te worden bepaald
      // Uitsplitsen naar niveau:
      // - niet uitsplitsen:
      //   - activiteit: *Uitgevoerde activiteiten*
      //   - machine:    *Gebruik machines*
      //   - artikel:    *Geleverde/verbruikte artikelen*
      // - Uitspl.perOpbr.groep: omschrijving van opbrengstgroep
      // - Uitspl. per artikel: tekst op factuur van tabArtikel
      //                        Indien specificatie per medewerker, van de oms. uitbreiden met */* + volledige naam medewerker
      // Indien medewerker uitsplitsen EN mutatiesoort = Activiteit:
      // - oms. uitbreiden met */* + volledige naam medewerker


      set @TekstOpFactuur = null;
      case @Uitsplitsingsniveau
        when 0 then // NIET uitsplitsen
          if @ArtGidVoorTekstOpFactuur is null then
            // Kan eigenlijk niet, maar omdat het veld in de vaste gegevens in beginsel leeg is, toch maar vullen!
            case @CurMutSoort
              when 0 then set @FactOms = _A('Uitgevoerde activiteiten')
              when 1 then set @FactOms = _A('Overige kosten')
              when 2 then set @FactOms = _A('Geleverde/verbruikte artikelen')
            end case;
          else
            // Omschrijving van dit artikel uitlezen
            select ArtOms into @FactOms from tabArtikel where ArtGid = @ArtGidVoorTekstOpFactuur;

            // Tekst op factuur van dit artikel uitlezen
            select first ArtTekst
            into   @TekstOpFactuur
            from   tabArtikelTeksten
            where  ArtTekstArtGid = @ArtGidVoorTekstOpFactuur and ArtTaalGid = @TaalGid and IsNull(ArtTekstDocSoort, 50) = 50 // Tekst op factuur van het artikel
            order by ArtTekstDocSoort desc; // Indien factuurtekst niet gevonden, dan de standaard tekst gebruiken!
          end if;
        when 1 then  // uitsplitsen per opbrengstgroep
          select OpbrGrpOms
          into   @FactOms
          from   tabOpbrengstGroep
          where  OpbrGrpGId = @CurOpbrGrpGid;
        when 2 then // uitsplitsen per artikel (+partij)
          // Probeer eerst de partijoms op te vragen
          if (@ArtIsPartijRegistreren = 1 and @ArtIsPartijAparteTekstOpFactuur = 1 and @ArtPartijAparteTekstOpFactuurDefault = 1 /* Tekst_op_factuur_van_artikel */ and @FactArtPartijGid is not null) then
            select ArtPartijOms into @FactOms from tabArtikelPartij where ArtPartijGid = @FactArtPartijGid;

            select first ArtPartijTekstOpFactuur
            into   @TekstOpFactuur
            from   tabArtikelPartijTeksten
            where  ArtPartijTekstArtPartijGid = @FactArtPartijGid and ArtPartijTekstTaalGid = @TaalGid;
          else
            select ArtOms into @FactOms from tabArtikel where ArtGid = @FactArtGid;
          end if;

          if (@ArtIsPartijRegistreren = 0 or @ArtIsPartijAparteTekstOpFactuur = 0 or @FactArtPartijGid is null or @TekstOpFactuur is null) then
            // Partij heeft geen eigen omschrijving OF er is geen partij -> gebruik artikeltekst
            select first ArtTekst
            into   @TekstOpFactuur
            from   tabArtikelTeksten
            where  ArtTekstArtGid = @FactArtGid and ArtTaalGid = @TaalGid and IsNull(ArtTekstDocSoort, 50) = 50 // Tekst op factuur van het artikel
            order by ArtTekstDocSoort desc; // Indien factuurtekst niet gevonden, dan de standaard tekst gebruiken!
          end if;
      end case;

      // Als tekst op factuur leeg is, vul deze dan met de omschrijving
      if IsNull(@TekstOpFactuur, '') = '' then
        set @TekstOpFactuur = @FactOms;
      end if;

      // Medewerkersnaam er eventueel aan toevoegen
      if @UitsplitsenMedewerker = 1 and @CurMutSoort = 0 then
        set @RelVolledigeNaam = '';
        select RelVolledigeNaam into @RelVolledigeNaam from tabRelatie where RelGid = @CurRelGid;
        if @RelVolledigeNaam <> '' and @FactOms <> '' then
          set @FactOms = @FactOms + ' / ';
        end if;
        set @FactOms = @FactOms + @RelVolledigeNaam;

        if @RelVolledigeNaam <> '' and @TekstOpFactuur <> '' then
          set @TekstOpFactuur = @TekstOpFactuur + ' / ';
        end if;
        set @TekstOpFactuur = @TekstOpFactuur + @RelVolledigeNaam;

      end if;
    end if;


    // #######################################
    // ### Factuurregel aanmaken/aanvullen ###
    // #######################################

    // Maak factuurregel waarvoor geldt:
    // - pfvrPfvkGid             = @PfvkGid
    // - pfvrPbGid               = @PbGidVoorFactRegel
    // - pfvrBtwCode             = @FactBtwCode
    // - pfvrPmwGid              = @FactRelGid (als @FactRelGid = NULL, dan moet ook gelden: pfvrPmwGid = NULL)
    // - pfvrArtGid              = @FactArtGid (als @FactArtGid = NULL, dan moet ook gelden: pfvrArtGid = NULL)
    // - pfvrArtPartijGid        = ??
    // - pfvrOpbrGrpGid          = @FactOpbrGrpGid (als @FactOpbrGrpGid = NULL, dan moet ook gelden: pfvrOpbrGrpGid = NULL)
    // - pfvrMutSoort            = @CurMutSoort
    // Hulpvar. @SpecsGevuld     = Als pfvrVerkoopprijsExclBTW = @CurVerkoopPrijsPeenheid EN pfvrPrijsPer = @CurPrijsPer dan 1 anders 0
    // - pfvrAantal              = Als @SpecsGevuld = 1, dan pfvrAantal + @CurTeFacturerenAantal anders leeg
    // - pfvrVerkoopprijsExclBTW = Als @SpecsGevuld = 1, dan @CurVerkoopPrijsPeenheid anders leeg
    // - pfvrPrijsPer            = Als @SpecsGevuld = 1, dan @CurPrijsPer anders leeg
    // - pfvrOms                 = @FactOms


    // --- Bepaal of prijzen en aantallen worden afgedrukt (afhankelijk van aantal decimalen)
    // (Als aantal decimalen aantal of prijs te groot, dan de prijs/aantal NIET afdrukken)
    if (@CurAantDecPrijsVoorstel <= @AantDecPrijsVast and @CurAantDecAantalVoorstel <= @AantDecAantalVast)
    and (((round(round(@CurTeFacturerenAantal, @AantDecAantalVast) * round(@CurVerkoopPrijsPeenheid / @CurPrijsPer, @AantDecPrijsVast),2) = @CurTeFacturerenBedrag) and @CurMutSoort = 0) or (@CurMutSoort <> 0)) then
      // Decimalen aantal+prijs zijn gelijk aan of kleiner dan die van tarief van de vaste gegevens en ...
      // prijs * aantal afgerond op het aantal dec van de vaste gegevens leidt tot hetzelfde regeltotaal.
      // Maw: 00:20 (20 minuten) = 0.33333333 * 30 euro = 10.00, maar tarief vaste gegevens heeft max 3 dec,
      // dus 0.333 * 30 euro = 9,999. op factuur zou dus 0.333 * 30 euro = 10.000 komen te staan. En dat mag niet!
      set @pfvrIsAantalEnPrijzenGeldig = 1;
    else
      set @pfvrIsAantalEnPrijzenGeldig = 0;
    end if;
    //call trace('1; IsGeldig='+ string(@pfvrIsAantalEnPrijzenGeldig)+', @CurVerkoopPrijsPeenheid='+string(@CurVerkoopPrijsPeenheid)+', @AantDecPrijsVast='+string(@AantDecPrijsVast));
    //call trace('1; IsGeldig='+ string(@pfvrIsAantalEnPrijzenGeldig)+', @CurTeFacturerenAantal='+string(@CurTeFacturerenAantal)+', @AantDecPrijsVast='+string(@AantDecAantalVast));


    // --- Toevoegen van of aanvullen aan factuurregel

    if @pfvrGid is null then
      // %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
      // %%% Toevoegen van de voorstelregel %%%
      // %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

      // Onthoud of er al een factuurvoorstelregel op dezelfde PbGid staat
      if exists(select first 1 from tabProjectFactuurVoorstelRegel where pfvrPbGid = @PbGidVoorFactRegel and pfvrPfvkGid = @PfvkGid) then
         set @IsEersteOpDezePb = 0;
       else
         set @IsEersteOpDezePb = 1;
       end if;

      // Factuurvoorstelregel (op deze PbGid) toevoegen
      insert into tabProjectFactuurVoorstelRegel
             (pfvrPfvkGid, PfvrPbGid,           PfvrBtwCode,  PfvrPmwGid,  PfvrArtGid,  PfvrArtPartijGid,  PfvrOpbrGrpGid,  PfvrMutSoort, PfvrAantal,             PfvrVerkoopprijsExclBTW,  PfvrPrijsPer, PfvrVerkoopwaarde,      pfvrIsAantalEnPrijzenGeldig,  PfvrOms,  PfvrTekstOpFactuur)
      values (@PfvkGid,    @PbGidVoorFactRegel, @FactBtwCode, @FactRelGid, @FactArtGid, @FactArtPartijGid, @FactOpbrGrpGid, @CurMutSoort, @CurTeFacturerenAantal, @CurVerkoopPrijsPeenheid, @CurPrijsPer, @CurTeFacturerenBedrag, @pfvrIsAantalEnPrijzenGeldig, @FactOms, @TekstOpFactuur);
      set @pfvrGid = @@Identity;

       // Is het de eerste factuurvoorstelregel op deze Pb? Dan de tekst op factuur OF de omschrijving van de Pb toevoegen
      if @IsEersteOpDezePb = 1 then
        set @TekstOpFactuur = '';
        select PfvdTekstOpFactuur into @TekstOpFactuur from tabProjectFactuurVerdichting where PfvdPbGid = @PbGidVoorFactRegel;
        if IsNull(@TekstOpFactuur,'') = '' then
          // Tekst op factuur is leeg; dan maar proberen om de omschrijving over te nemen
          select PbOmschr into @TekstOpFactuur from tabProjectBoom where PbGid = @PbGidVoorFactRegel;
        end if;
        if IsNull(@TekstOpFactuur,'') <> '' then
          insert into tabProjectFactuurVoorstelRegel
                 (pfvrPfvkGid, PfvrPbGid,           PfvrMutSoort, PfvrTekstOpFactuur)
          values (@PfvkGid,    @PbGidVoorFactRegel, -1,           @TekstOpFactuur);
        end if;

      end if;


      // En de link tussen mutatieregel en factuurvoorstelregel onthouden:
      insert into tabProjectFactuurVoorstelRealisatie
             (pfvlFvrGid, pfvlPbrGid, pfvlAantal)
      values (@PfvrGid,   @CurPbrGid, @CurTeFacturerenAantal);

    else
      // En de link tussen mutatieregel en factuurvoorstelregel onthouden:
      insert into tabProjectFactuurVoorstelRealisatie                           // Als verkoopprijs/prijs per anders zijn dan de regel, dan moet voor die regel
             (pfvlFvrGid, pfvlPbrGid, pfvlAantal)                               // de velden Aantal, PrijsPer en Verkooprijs per eenheid NIET meer worden onthouden
      values (@PfvrGid,   @CurPbrGid, @CurTeFacturerenAantal);


/*
PG/TG 23-12-2009, 14:22u: In verband met spoed tbv uitleveren 5.44 houden we het commentaar even onuitgewerkt:
      1: zijn alle prijzen/prijsper gelijk?
        ja: regeltotaal = som(aantal) * prijs
          is afgronde(som(aantal))*prijs gelijk aan som(aantal) * prijs
            ja: prijs blijft geldig
            nee: prijs is toch ongeldig

        nee regeltotaal som (aantal*prijs) (@CurTeFacturerenBedrag)
*/
      if (select count(distinct PbrVerkoopprijs) * count(distinct PbrPrijsPer) from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @pfvrGid) = 1 then
        update tabProjectFactuurVoorstelRegel
        set    PfvrAantal = round((select sum(pfvlaantal) from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @pfvrGid), @AantDecAantalVast),
               pfvrVerkoopWaarde = round((select sum(pfvlaantal) * (Avg(PbrVerkoopprijs) / Avg(PbrPrijsPer)) from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @pfvrGid), 2)
        where  pfvrGid = @pfvrGid;

        update tabProjectFactuurVoorstelRegel
        set    pfvrIsAantalEnPrijzenGeldig =  if (select round(round(sum(pfvlaantal), @AantDecAantalVast) * round(Avg(PbrVerkoopprijs) / Avg(PbrPrijsPer), @AantDecPrijsVast), 2)
                                                from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @pfvrGid) = PfvrVerkoopwaarde then 1 else 0 endif
        where  pfvrGid = @pfvrGid;
      else
        update tabProjectFactuurVoorstelRegel
        set    pfvrIsAantalEnPrijzenGeldig = 0,
               pfvrVerkoopWaarde = round((select sum(round(pfvlaantal * (PbrVerkoopprijs / PbrPrijsPer), 2))
                                          from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @pfvrGid), 2)
        where  pfvrGid = @pfvrGid;

      end if;


      select
        if max(pfvrIsAantalEnPrijzenGeldig) = 1 then round(sum(pfvlaantal), @AantDecAantalVast) else 0 endif,
        if max(pfvrIsAantalEnPrijzenGeldig) = 1 then round(Avg(PbrVerkoopprijs), @AantDecPrijsVast) else 0 endif,
        if max(pfvrIsAantalEnPrijzenGeldig) = 1 then Avg(PbrPrijsPer) else 0 endif into @tmpPfvrAantal, @tmpPfvrVerkoopprijsExclBTW, @tmpPfvrPrijsPer
      from   tabProjectFactuurVoorstelRegel
             inner join tabProjectFactuurVoorstelRealisatie on (pfvlFvrGid = pfvrGid)
             inner join tabProjectBoekingsRegel on (PbrGid = pfvlPbrGid)
      where  pfvrGid = @pfvrGid;

      update tabProjectFactuurVoorstelRegel
      set    pfvrAantal                  = @tmpPfvrAantal,
             pfvrVerkoopprijsExclBTW     = @tmpPfvrVerkoopprijsExclBTW,
             pfvrPrijsPer                = @tmpPfvrPrijsPer
      where  pfvrGid = @pfvrGid;
    end if;

    // Vervolgens in de mutatieregel onthouden welk aantal in het voorstel is gezet
    update tabProjectBoekingsRegel
    set    PbrAantalOpFactuurVoorstel = PbrAantalOpFactuurVoorstel + @CurTeFacturerenAantal
    where  pbrGid = @CurPbrGid;

    // Als laatste het vink-regeltje verwijderen
    delete tmpProjectGoedkeurSelectie where tmpPgsGid = @CurtmpPgsGid;

  end for;

  set @@ErrorTextProcedure = 'ProjectenMaakFactuurVoorstelRegieRegels';
  //call TraceEind(@@ErrorTextProcedure);

end;


// *************************************************************************
// ***** Vullen van projectfactuurvoorstel met geselecteerde termijnen *****
// *************************************************************************
create or replace procedure ProjectenMaakFactuurVoorstelTermijnRegels(
  in  @SessieNr   integer,
  in  @ProjGid    integer,
  in  @ProjNawGid integer,
  in  @TaalGid    integer,
  in  @pfvkGid    integer,
  out @FoutNr     integer,
  out @FoutCode   nchar(100)
)
begin
  declare @FactBtwCode       integer;
  // Artikelgegevens t.b.v. het tarief waarop de termijn wordt gefactureerd
  declare @ArtGidVoorTermijn integer;
  declare @FactOpbrGrpGid    integer;
  // FactuurRegel
  declare @pfvrGid           integer;
  declare @RootPbGid         integer; // Gebruik de root van het project om in de factuurregel te zetten

  declare @IsEersteOpDezePb  smallint;
  declare @TekstOpFactuur    long nvarchar;

  set @@ErrorTextProcedure = 'ProjectenMaakFactuurVoorstelTermijnRegels > @SessieNr='+String(@SessieNr);
  //call TraceBegin(@@ErrorTextProcedure);

  // Het betreft een termijnproject, dus het artikel t.b.v. termijnen op de factuur opvragen
  // ACW Pas bij facturering invullen!!
  // select first ArtGid, ArtOpbrGrpGid into @ArtGidVoorTermijn, @FactOpbrGrpGid from tabArtikel where ArtSoort = 1;
  set @ArtGidVoorTermijn = null;
  set @FactOpbrGrpGid = null;


  // Opzoeken van de roottree van het project
  select PbGid into @RootPbGid from tabProjectBoom where PbProjGid = @ProjGid and PbLevel = 1;

  // ##########################################
  // ### Doorlopen van geselecteerde regels ###
  // ##########################################

  for @Cursor AS CURSOR_TermijnRgls CURSOR FOR
    select tmpPgsGid         @CurtmpPgsGid,
           tmpPgsPtmGid      @CurPtmGid,
           PtmBtwCode        @CurBtwCode,
           PtmTekstOpFactuur @CurTekstOpFactuur,
           PtmTeFactureren   @CurTeFacturerenBedrag
    from   tmpProjectGoedkeurSelectie
           inner join tabProjectTermijn on (ptmGid = tmpPgsPtmGid and PtmProjGid = @ProjGid and PtmStatus = 1)
    where  tmpPgsStatus = 0 and tmpPgsSessie = @SessieNr
  for read only
  do
    // Tmp-tabel aflopen en elke regel van deze sessie toevoegen aan:
    // - factuurregel   tabProjectFactuurVoorstelRegel
    // - de tussentabel tabProjectFactuurVoorstelRealisatie

    // #######################
    // ### Bepaal BTW-code ###
    // #######################
    // Indien BTW-code van de debiteur 0% is, dan deze nemen, anders gewoon de BTW-code van de termijn
    // ACW: Bij termijnen moet de gebruiker maar de juiste BTW al opgeven (wordt gevuld o.b.v. de debiteur, dus
    //      bij vullen al op 0%-BTW letten)
    //set @FactBtwCode = null;
    //select NawFilBtwCode into @FactBtwCode
    //from   tabNawFile
    //       inner join tabBtw on (BtwCode = NawFilBtwCode)
    //where  NawFilFonID = 'D' and NawFilNawGid = @ProjNawGid and BtwPercentage = 0;
    //if @FactBtwCode is null then
      // Er is geen BTWcode van de debiteur gevonden met 0%, dus gewoon de BTWcode van het artikel gebruiken
      set @FactBtwCode = @CurBtwCode;
    //end if;

	//MR 06-feb-2009 bug #28565: toegevoegd voor tekst op factuur
	// Onthoud of er al een factuurvoorstelregel op dezelfde PbGid staat
	if exists(select first 1 from tabProjectFactuurVoorstelRegel where pfvrPbGid = @RootPbGid and pfvrPfvkGid = @PfvkGid) then
		set @IsEersteOpDezePb = 0;
	else
   		set @IsEersteOpDezePb = 1;
    end if;

    insert into tabProjectFactuurVoorstelRegel
           (pfvrPfvkGid, PfvrPbGid,  PfvrBtwCode,  PfvrArtGid,         PfvrOpbrGrpGid,  PfvrMutSoort, PfvrAantal, PfvrVerkoopprijsExclBTW, PfvrPrijsPer, PfvrVerkoopwaarde,      PfvrOms,            PfvrTekstOpFactuur)
    values (@PfvkGid,    @RootPbGid, @FactBtwCode, @ArtGidVoorTermijn, @FactOpbrGrpGid, 99,           0,          0.0,                     1,            @CurTeFacturerenBedrag, @CurTekstOpFactuur, @CurTekstOpFactuur);
    set @pfvrGid = @@Identity;

	//MR 06-feb-2009 bug #28565: toegevoegd voor tekst op factuur
	// Is het de eerste factuurvoorstelregel op deze Pb? Dan de tekst op factuur OF de omschrijving van de Pb toevoegen
	if @IsEersteOpDezePb = 1 then
		set @TekstOpFactuur = '';
		select PfvdTekstOpFactuur into @TekstOpFactuur from tabProjectFactuurVerdichting where PfvdPbGid = @RootPbGid;
		if isnull(@TekstOpFactuur,'') = '' then
			// Tekst op factuur is leeg; dan maar proberen om de omschrijving over te nemen
			select PbOmschr into @TekstOpFactuur from tabProjectBoom where PbGid = @RootPbGid;
		end if;
		if isnull(@TekstOpFactuur,'') <> '' then
			insert into tabProjectFactuurVoorstelRegel
		    	(pfvrPfvkGid, PfvrPbGid, PfvrMutSoort, PfvrTekstOpFactuur)
		  		values (@PfvkGid, @RootPbGid, -1, @TekstOpFactuur);
		end if;
	end if;

    // En de link tussen mutatieregel en factuurvoorstelregel onthouden:
    insert into tabProjectFactuurVoorstelRealisatie
           (pfvlFvrGid, pfvlPtmGid)
    values (@PfvrGid,   @CurPtmGid);

    // Daarna de termijn updaten:
    // - Status op 2 (op voorstel)

    update tabProjectTermijn
    set    PtmStatus = 2 /*Op voorstel*/
    where  PtmGid = @CurPtmGid;

    // Als laatste het vink-regeltje verwijderen
    delete tmpProjectGoedkeurSelectie where tmpPgsGid = @CurtmpPgsGid;

  end for;

  set @@ErrorTextProcedure = 'ProjectenMaakFactuurVoorstelTermijnRegels';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProjectenRollbackIngebruikGenomenRegels.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// ---------------------------------------------------------------------
// --------- Bij ingebruiknemingsfout de regels weer vrijgeven ---------
// ---------------------------------------------------------------------

if exists (select 1 from sys.sysProcedure where proc_name='ProjectenRollbackIngebruikGenomenRegels') then
  drop procedure ProjectenRollbackIngebruikGenomenRegels;
end if;

create procedure ProjectenRollbackIngebruikGenomenRegels(
  in  @SessieNr     integer
)
begin
  set @@ErrorTextProcedure = 'ProjectenRollbackIngebruikGenomenRegels > @SessieNr='+String(@SessieNr);
  //call traceBegin(@@ErrorTextProcedure);

  // Terugzetten van de status van de regels die niet zijn gelukt
  update tabProjectBoekingsRegel
  set    PbrStatus    = tmpPgsOrigPbrStatus,
         PbrIsGeboekt = tmpPgsOrigPbrIsGeboekt
  from   tabProjectBoekingsRegel
         inner join tmpProjectGoedkeurSelectie on (tmpPgsPbrGid = PbrGid)
  where      (tmpPgsSessie = @SessieNr and tmpPgsStatus = 1)
         and (PbrStatus    = 3)  // Geaccepteerd
         and (PbrIsGeboekt = 0); // maar nog niet geboekt

  // Reset de geselecteerde regels (Zet status van ~Regel in gebruik genomen~ terug op ~Geselecteerd in tree~)
  update tmpProjectGoedkeurSelectie
  set    tmpPgsStatus = 0
  from   tmpProjectGoedkeurSelectie
         inner join tabProjectBoekingsRegel on (PbrGid = tmpPgsPbrGid)
  where      (tmpPgsSessie = @SessieNr and tmpPgsStatus = 1);

  set @@ErrorTextProcedure = 'ProjectenRollbackIngebruikGenomenRegels';
  //call traceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProjectenVerwijderMutatieRegelUitFactuurVoorstelRegels.sp $ $Revision: 5 $ $Modtime: 26-08-10 10:14 $'

// -------------------------------------------
// --- Project verwijderen factuurvoorstel ---
// -------------------------------------------

if exists (select 1 from sys.sysProcedure where proc_name='ProjectenVerwijderMutatieRegelUitFactuurVoorstelRegels') then
  drop procedure ProjectenVerwijderMutatieRegelUitFactuurVoorstelRegels;
end if;

create procedure ProjectenVerwijderMutatieRegelUitFactuurVoorstelRegels(
  in  @SessieNr   integer,
  in  @ProjGid    integer,
  in  @pfvkGid    integer,
  in  @RegelSoort smallint //0 regieregels, 1 termijnregels
)
begin
  declare @ArtGidVoorTekstOpFactuur    integer;
  // t.b.v. controle op aantal decimalen activiteit/machine/artikel t.o.v. die van de vaste gegevens
  declare @AantDecPrijsVast            smallint; // Aantal decimalen van tarief van vaste gegevens
  declare @AantDecAantalVast           smallint;
  declare @tmpPfvrAantal               numeric(20,8);
  declare @tmpPfvrVerkoopprijsExclBTW  numeric(15,3);
  declare @tmpPfvrPrijsPer             numeric(15,3);

  set @@ErrorTextProcedure = 'ProjectenVerwijderMutatieRegelUitFactuurVoorstelRegels > @SessieNr='+String(@SessieNr);
  //call TraceBegin(@@ErrorTextProcedure);

  if @RegelSoort = 1 then
    // Termijnproject -> via termijnregels
    for @Cursor AS CURSOR_TermijnRegels CURSOR FOR
      select tmpPgsGid     @CurtmpPgsGid,
             PtmGid        @CurPtmGid,
             pfvlGid       @CurPfvlGid,
             pfvlFvrGid    @CurPfvrGid
      from   tmpProjectGoedkeurSelectie
             inner join tabProjectTermijn                   on (ptmGid = tmpPgsPtmGid)
             inner join tabProjectFactuurVoorstelRealisatie on (pfvlPtmGid = tmpPgsPtmGid)
             inner join tabProjectFactuurVoorstelRegel      on (pfvrGid = pfvlFvrGid)
      where  tmpPgsStatus = 0 and tmpPgsSessie = @SessieNr and PtmProjGid = @ProjGid and PtmStatus = 2 /*Op voorstel*/
             and pfvrPfvkGid = @PfvkGid
    for read only
    do

      // Verwijder realisatieregel
      delete tabProjectFactuurVoorstelRealisatie where pfvlGid = @CurPfvlGid;
      // Verwijder voorstelregel
      delete tabProjectFactuurVoorstelRegel where pfvrGid = @CurPfvrGid;

      // Update status van termijnregel
      update tabProjectTermijn
      set    PtmStatus = 1
      where  PtmGid = @CurPtmGid;
    end for;
  else
    // Regieproject -> via boekingsregels
    for @Cursor AS CURSOR_MutatieRegels CURSOR FOR
      select tmpPgsGid       @CurtmpPgsGid,
             PbrGid          @CurPbrGid,
             PbrPbGid        @CurPbGid,
             pfvlAantal      @CurTeFacturerenAantal,
             round(@CurTeFacturerenAantal / PbrPrijsPer * PbrVerkoopprijs, 2) @CurTeFacturerenBedrag,
             pfvlGid       @CurPfvlGid,
             pfvlFvrGid    @CurPfvrGid,
             PbrMutSoort   @CurMutSoort
      from   tmpProjectGoedkeurSelectie
             inner join tabProjectBoekingsRegel             on (pbrGid = tmpPgsPbrGid)
             inner join tabProjectFactuurVoorstelRealisatie on (pfvlPbrGid = tmpPgsPbrGid)
             inner join tabProjectFactuurVoorstelRegel      on (pfvrGid = pfvlFvrGid)
      where  tmpPgsStatus = 0 and tmpPgsSessie = @SessieNr and pbrProjGid = @ProjGid and PbrStatus = 3
             and pfvrPfvkGid = @PfvkGid
    for read only
    do

      // ****************************************************************
      // *** Bepaal tarief en aantal decimalen volgens vaste gegevens ***
      // ****************************************************************
      // Dit tarief wordt OOK gebruikt t.b.v. de tekst op factuur (afhankelijk van uitsplitsingsniveau)
      select
        case @CurMutSoort
          when 0 then ProjVastArtGidActiviteit
          when 1 then ProjVastArtGidMachine
          when 2 then ProjVastArtGidArtikel
        end  into  @ArtGidVoorTekstOpFactuur
      from
        tabProjectVastegegevens;

      if @ArtGidVoorTekstOpFactuur is null then
        set @AantDecPrijsVast = 2;
        set @AantDecAantalVast = 2;
      else
        select ArtAantDecPrijzen, ArtAantDecAantallen into @AantDecPrijsVast, @AantDecAantalVast from tabArtikel where ArtGid = @ArtGidVoorTekstOpFactuur;
      end if;

      // Verwijder realisatieregel
      delete tabProjectFactuurVoorstelRealisatie where pfvlGid = @CurPfvlGid;

      // Als er nog andere regels naar factuurvoorstelregel wijzen, dan aantal/waarde verlagen, anders de regel verwijderen
      if exists(select first 1 from tabProjectFactuurVoorstelRealisatie where pfvlFvrGid = @CurPfvrGid) then

        if (select count(distinct PbrVerkoopprijs) * count(distinct PbrPrijsPer) from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @CurPfvrGid) = 1 then
          update tabProjectFactuurVoorstelRegel
          set    PfvrAantal = round((select sum(pfvlaantal) from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @CurPfvrGid), @AantDecAantalVast),
                 pfvrVerkoopWaarde = round((select sum(pfvlaantal) * (Avg(PbrVerkoopprijs) / Avg(PbrPrijsPer)) from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @CurPfvrGid), 2)
          where  pfvrGid = @CurPfvrGid;

          update tabProjectFactuurVoorstelRegel
          set    pfvrIsAantalEnPrijzenGeldig =  if (select round(round(sum(pfvlaantal), @AantDecAantalVast) * round(Avg(PbrVerkoopprijs) / Avg(PbrPrijsPer), @AantDecPrijsVast), 2)
                                                    from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @CurPfvrGid) = PfvrVerkoopwaarde then 1 else 0 endif
          where  pfvrGid = @CurPfvrGid;
        else
          update tabProjectFactuurVoorstelRegel
          set    pfvrIsAantalEnPrijzenGeldig = 0,
                 pfvrVerkoopWaarde = round((select sum(round(pfvlaantal * (PbrVerkoopprijs / PbrPrijsPer), 2))
                                            from tabProjectBoekingsRegel inner join tabProjectFactuurVoorstelRealisatie on (PbrGid = pfvlPbrGid) where pfvlFvrGid = @CurPfvrGid), 2)
          where  pfvrGid = @CurPfvrGid;
        end if;


        select
          if max(pfvrIsAantalEnPrijzenGeldig) = 1 then round(sum(pfvlaantal), @AantDecAantalVast) else 0 endif,
          if max(pfvrIsAantalEnPrijzenGeldig) = 1 then round(Avg(PbrVerkoopprijs), @AantDecPrijsVast) else 0 endif,
          if max(pfvrIsAantalEnPrijzenGeldig) = 1 then Avg(PbrPrijsPer) else 0 endif into @tmpPfvrAantal, @tmpPfvrVerkoopprijsExclBTW, @tmpPfvrPrijsPer
        from   tabProjectFactuurVoorstelRegel
               inner join tabProjectFactuurVoorstelRealisatie on (pfvlFvrGid = pfvrGid)
               inner join tabProjectBoekingsRegel on (PbrGid = pfvlPbrGid)
        where  pfvrGid = @CurPfvrGid;

        update tabProjectFactuurVoorstelRegel
        set    pfvrAantal                  = @tmpPfvrAantal,
               pfvrVerkoopprijsExclBTW     = @tmpPfvrVerkoopprijsExclBTW,
               pfvrPrijsPer                = @tmpPfvrPrijsPer
        where  pfvrGid = @CurPfvrGid;

        // Eventueel de prijs en aantal weer vermelden, als alleen nog maar zelfde regels aan deze regel zijn gekoppeld.
        //PG/TG 23-12-2009: Deze code is overbodig geworden door de aanpassingen die hierboven ten behoeve van bug 31941 zijn gemaakt.
        //call ProjectenFactuurVoorstelRegelsVerkoopPrijsPerCheck(@CurPfvrGid);
      else
        // Was de laatste, dus voorstelregel verwijderen
        delete tabProjectFactuurVoorstelRegel where pfvrGid = @CurPfvrGid;
      end if;

      // Update aantalopfactuur van boekingsregel
      update tabProjectBoekingsRegel
      set    PbrAantalOpFactuurVoorstel = PbrAantalOpFactuurVoorstel - @CurTeFacturerenAantal
      where  pbrGid = @CurPbrGid;
    end for;
  end if;

  // Verwijder de tekstregel op PbGid-niveau als dat de enige regel is
  delete tabProjectFactuurVoorstelRegel
  where  pfvrMutSoort = -1
        and    pfvrPbGid not in (select pfvrPbGid from tabProjectFactuurVoorstelRegel where pfvrPfvkGid = @PfvkGid and pfvrMutSoort <> -1) // Alleen als er geen andere regels zijn
        and    pfvrPfvkGid = @PfvkGid; // En alleen van dit factuurvoorstel
  // Als er geen regels mee in het factuurvoorstel zijn, dan gewoon het hele voorstel verwijderen
  // ACW Factuurvoorstel kan nu leeg blijven!
  // if not exists(select 1 from tabProjectFactuurVoorstelRegel where pfvrPfvkGid = @PfvkGid and pfvrMutSoort <> -1) then
  //   delete tabProjectFactuurVoorstelKop where PfvkGid = @PfvkGid;
  // end if;

  set @@ErrorTextProcedure = 'ProjectenVerwijderMutatieRegelUitFactuurVoorstelRegels';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProjectFactuurVoorstelBepaalUitsplitsingsniveau.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// -----------------------------------------------------------------
// --- Project zoek uitsplitsing o voor aanmaken factuurvoorstel ---
// -----------------------------------------------------------------

if exists (select 1 from sys.sysProcedure where proc_name='ProjectFactuurVoorstelBepaalUitsplitsingsniveau') then
  drop procedure ProjectFactuurVoorstelBepaalUitsplitsingsniveau;
end if;

create procedure ProjectFactuurVoorstelBepaalUitsplitsingsniveau(
  in  @PbGid integer,
  in  @MutSoort integer,
  out @PbGidVoorFactuurRegel  integer,   // Voor deze PbGid is aangegeven dat voor het mutatiesoort apart moet worden afgedrukt, dus de factuurregel aan deze PbGid knopen
  out @Uitsplitsingsniveau    smallint,  // 0 = niet uitsplitsen, 1 = uitsplitsen per opbrengstgroep, 2 = uitsplitsen per act/mach/art (= per ArtGid)
  out @UitsplitsingMedewerker smallint   // 0 = niet, 1 = wel uitsplitsen per medewerker (indien mutatiesoort = Activiteit)
)
begin
  // - Voor bepalen van PbGid wordt de eerstvolgende hogere in de boom gezocht waarvoor
  //   het vinkje *...voor dit onderdeel apart afdrukken* aan staat
  // - Voor het bepalen van specificatie (voor medewerker, act/art/mach / opbrengstgroep)
  //   wordt het eerstgevonden record gebruikt hoger in de boom.

  set @@ErrorTextProcedure = 'ProjectFactuurVoorstelBepaalUitsplitsingsniveau -> @PbGid='+string(@PbGid)+', @MutSoort='+string(@MutSoort);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Uitsplitsingsniveau     = null;
  set @UitsplitsingMedewerker  = null;
  // Bepalen van de PbGid o.b.v. het vinkje *Apart afdrukken* van het mutatiesoort
  select first
         tmpVolgorde.PbGid
  into   @PbGidVoorFactuurRegel
  from   (select PbLevel, PbGid
          from   tabProjectboompad
                 inner join tabProjectboom on (PbGid=PbpParentPbGid)
          where  PbpPbGid=@PbGid
          union
          select 999 PbLevel, @PbGid
         ) tmpVolgorde
         inner join tabProjectFactuurVerdichting on (PfvdPbGid = tmpVolgorde.PbGid)
  where  case @MutSoort
           when 0 then PfvdActPerOnderdeel  // Activiteit (met medewerker)
           when 1 then PfvdMachPerOnderdeel // Machines
           when 2 then PfvdArtPerOnderdeel   // Artikel
         end <> 0 // HIER wordt dus bepaald dat het vinkje AAN moet staan om te stoppen met zoeken in de boom
  order by tmpVolgorde.PbLevel desc; //= PbLevel


  // Eerstvorige in de boom bepalen voor de uitsplitsing
  select first
         case @MutSoort
           when 0 then PfvdFactVerdActAct   * 2 + PfvdFactVerdActOpbrGrp
           when 1 then PfvdFactVerdMachMach * 2 + PfvdFactVerdMachOpbrGrp
           when 2 then PfvdFactVerdArtArt   * 2 + PfvdFactVerdArtOpbrGrp
         end Uitsplitsingsniveau,
         if @MutSoort = 0 then PfvdFactVerdActMedew else 0 endif
  into   @Uitsplitsingsniveau, @UitsplitsingMedewerker
  from   (select PbLevel, PbGid
          from   tabProjectboompad
                 inner join tabProjectboom on (PbGid=PbpParentPbGid)
          where  PbpPbGid=@PbGid
          union
          select 999 PbLevel, @PbGid
         ) tmpVolgorde
         inner join tabProjectFactuurVerdichting on (PfvdPbGid = tmpVolgorde.PbGid)
  order by tmpVolgorde.PbLevel desc; //= PbLevel

  set @@ErrorTextProcedure = 'ProjectFactuurVoorstelBepaalUitsplitsingsniveau -> @PbGidVoorFactuurRegel='+string(@PbGidVoorFactuurRegel)+', @Uitsplitsingsniveau='+string(@Uitsplitsingsniveau)+', @UitsplitsingMedewerker='+string(@UitsplitsingMedewerker);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure ProjectGenereerProjCode(out @ProjCode nchar(10), out @ProjVastStartNummerProjCode nchar(10))
begin
  declare @NieuweProjCode               nchar(10);
  declare @NieuweString                 nchar(1);
  declare @GenereerProjectCode          integer;      // 0 = nog niet, 1 = nieuwe projcode, 2 = niet te genereren
  declare @positie                      integer;

  set @@ErrorTextProcedure = 'ProjectGenereerProjCode';
  //call TraceBegin(@@ErrorTextProcedure);

  set @NieuweProjCode       = '';
  set @ProjCode             = '';
  set @ProjVastStartNummerProjCode = '';
  set @GenereerProjectCode  = 0;

  //Dit deel moet uniek gelocked (met een wacht-lus)
  call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'ProjectGenereerProjCode', '');

  select ProjVastStartNummerProjCode into @NieuweProjCode from tabProjectVastegegevens;

  if @NieuweProjCode <> '' then
    Set @Positie  = Length(@NieuweProjCode);

    //call Tracebegin('Start loop');
    while @GenereerProjectCode=0 loop
      if (length(@NieuweProjCode) > 10) then
        set @GenereerProjectCode = 2;      // Fout dus
        //call Trace('Foute projcode: '+ @NieuweProjCode+ '  --> zoeken stoppen');
      else
        if (@ProjCode = '') and (not exists (select 1 from tabProject where ProjCode=@NieuweProjCode)) then
          //call Trace('Zoek ProjCode '+ @NieuweProjCode +' --> Niet gevonden dus gebruiken');
          set @ProjCode = @NieuweProjCode;
          //call Trace('');
        else
          //---------- ProjCode kwam al voor --> verhogen ----------
          //call Trace('Zoek ProjCode '+ @NieuweProjCode +' --> Gevonden, dus verder zoeken naar vrij nummer');
          if (@Positie <> 0) then
            //Character zit in de range 0..9,A..Z,a..z?
            if ((SubString(@NieuweProjCode,@Positie,1) between 'A' and 'Y') or
                (SubString(@NieuweProjCode,@Positie,1) between 'a' and 'y') or
                (SubString(@NieuweProjCode,@Positie,1) between '0' and '8'))  then

              set @NieuweString   = char(ascii(SubString(@NieuweProjCode,@Positie,1))+1);
              set @NieuweProjCode = stuff(@NieuweProjCode, @Positie, 1, @NieuweString );
              if (@ProjCode = '') then
                if (not exists (select 1 from tabProject where ProjCode=@NieuweProjCode)) then
                  set @ProjCode = @NieuweProjCode;
                end if;
              else
                set @ProjVastStartNummerProjCode = @NieuweProjCode;
              end if;
            else
              //verander de positie naar voor de huidige en zet de huidige waarde naar de eerste waarde in de rij Z=A z=a 9=0
              case ASCII(SubString(@NieuweProjCode,@Positie,1))
              when 90 then  set @NieuweString = 'A'   //Z
              when 122 then set @NieuweString = 'a'   //z
              when 57 then  set @NieuweString = '0'   //9
              else  //andere tekens zo laten
                set @NieuweString = SubString(@NieuweProjCode,@Positie,1);
              end case;
              set @NieuweProjCode = stuff(@NieuweProjCode, @Positie, 1, @NieuweString );
              set @Positie        = @Positie - 1;
            end if;
          else
            set @GenereerProjectCode = 2; //Niet te maken
          end if;


          //call Trace('@ProjCode: '+ @ProjCode + '@ProjVastStartNummerProjCode: '+ @ProjVastStartNummerProjCode);
          //Als beide zijn opgehaald ga dan uit de loop.
          if (@ProjCode <> '') and (@ProjVastStartNummerProjCode <> '') then
            set @GenereerProjectCode = 1;
          end if;
        end if;
      end if;
    end loop;
    //call TraceEind('Einde loop');

    if @GenereerProjectCode=1 then
      //call Trace('Updaten nieuwe ProjCode in vaste gegevens: '+ @ProjVastStartNummerProjCode );
      update tabProjectVastegegevens set ProjVastStartNummerProjCode = @ProjVastStartNummerProjCode;
    end if;
  end if;

  //NawGenereernummers-lock weer vrijgeven
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'ProjectGenereerProjCode', '');

  set @@ErrorTextProcedure = 'ProjectGenereerProjCode';
  //call TraceEind(@@ErrorTextProcedure);
end;


// ----------------------------------------------------------------------------------------
// -------- ProjectGenereerWeekStaatRegelnrAct tbv project weekstaat activiteiten ---------
// ----------------------------------------------------------------------------------------

create or replace procedure ProjectGenereerWeekStaatRegelnrAct(
	in    @pbkGid    		integer,
	in    @pbrGid    		integer,
  in    @Relgid     	integer,
  in    @BeginDatum 	DateTime,
  in    @EindDatum 		DateTime
  )
begin
  declare @weekstaatregelnr numeric(11,0);

  set @@ErrorTextProcedure = 'Begin ProjectGenereerWeekStaatRegelnrAct > @pbkGid='+string(@pbkGid)+',@pbrGid='+string(@pbrGid)+', @RelGid='+string(@RelGid)+', @BeginDatum='+string(@BeginDatum)+', @EindDatum='+string(@EindDatum);
 	//call Trace(@@ErrorTextProcedure);

  FOR @Cursor AS Cursor_ProjBoekingsRegels CURSOR FOR
      select   pbrprojgid @ProjGid, pbrpbgid @pbGid, pbrartgid @ArtGid, pbrMutatieDatum @pbrMutatieDatum
      from     tabProjectBoekingsRegel
      where    pbrweekstaatregelnr = 0
      	and pbrMutatieDatum between @BeginDatum and @Einddatum
      	and (pbrpbkGid = @pbkGid and (pbrGid = @pbrGid or isNull(@pbrGid,0) = 0))
      	and pbrMutSoort = 0
      	and pbrRelGid = @Relgid
      order by pbrGid
  for update
  do
    set @weekstaatregelnr = 0;

    select first isNull(pbrweekstaatregelnr,0) into @weekstaatregelnr
    from tabprojectboekingsregel as AlleRegels
    where AlleRegels.PbrPbkGid  = @PbkGid
      and AlleRegels.PbrProjGid = @ProjGid
      and AlleRegels.PbrPbGid   = @PbGid
      and AlleRegels.PbrArtGid  = @ArtGid
      and AlleRegels.PbrRelGid  = @RelGid
      and AlleRegels.PbrWeekstaatRegelNr > 0
      and not exists (
          select 1
          from  tabprojectboekingsregel as TeZoekenRegel
          where TeZoekenRegel.PbrPbkGid           = AlleRegels.PbrPbkGid
            and TeZoekenRegel.PbrProjGid          = AlleRegels.PbrProjGid
            and TeZoekenRegel.PbrPbGid            = AlleRegels.PbrPbGid
            and TeZoekenRegel.PbrArtGid           = AlleRegels.PbrArtGid
            and TeZoekenRegel.PbrWeekstaatRegelNr = AlleRegels.pbrweekstaatregelnr
            and TeZoekenRegel.Pbrmutatiedatum     = @pbrMutatieDatum)
    order by pbrweekstaatregelnr;

 	  if (isNull(@weekstaatregelnr,0) = 0) then
		  select isnull(Max(pbrWeekStaatRegelNr) + 1,1) into @weekstaatregelnr
		  from tabProjectBoekingsRegel
		  where pbrpbkGid = @pbkGid
		  and PbrRegelIsOnderdeelVan = 1;
    end if;

	  //Een heel nieuw nummer.
	  if @weekstaatregelnr > 9999999999 then
	    RaisError 20332;
	  end if;

    update tabProjectBoekingsRegel
    set    pbrweekstaatregelnr = @weekstaatregelnr
    where  current of Cursor_ProjBoekingsRegels;
  end for;

  set @@ErrorTextProcedure = 'Einde ProjectGenereerWeekStaatRegelnrAct';
  //call Trace(@@ErrorTextProcedure);
end;



// ----------------------------------------------------------------------------------------
// -------- ProjectGenereerWeekStaatRegelnrOvKosten tbv project weekstaat overige kosten ---------
// ----------------------------------------------------------------------------------------

create or replace procedure ProjectGenereerWeekStaatRegelnrOvKosten(
	in    @pbkGid    		integer,
	in    @pbrGid    		integer,
  in    @Relgid     	integer,
  in    @BeginDatum 	DateTime,
  in    @EindDatum 		DateTime
  )
begin
  declare @weekstaatregelnr numeric(10,0);

  set @@ErrorTextProcedure = 'Begin ProjectGenereerWeekStaatRegelnrOvKosten > @pbkGid='+string(@pbkGid)+',@pbrGid='+string(@pbrGid)+', @RelGid='+string(@RelGid)+', @BeginDatum='+string(@BeginDatum)+', @EindDatum='+string(@EindDatum);
 	//call Trace(@@ErrorTextProcedure);

  FOR @Cursor AS Cursor_tabProjectBoekingsRegels CURSOR FOR
      select   pbrprojgid @ProjGid, pbrpbgid @pbGid, pbrartgid @ArtGid, pbrMutatieDatum @pbrMutatieDatum
      from     tabProjectBoekingsRegel
      where    pbrweekstaatregelnr = 0
      	and pbrMutatieDatum between @BeginDatum and @Einddatum
      	and (pbrpbkGid = @pbkGid and (pbrGid = @pbrGid or isNull(@pbrGid,0) = 0))
      	and pbrMutSoort = 1
      	and pbrRelGid = @RelGid
      order by  @ProjGid, @pbGid, @ArtGid, @pbrMutatieDatum
  for update
  do
  	//Selecteer een activiteitregel om het nieuwe weekstaatregelnr te bepalen
  	select isNull(max(pbrWeekStaatRegelnr),0) into @weekstaatregelnr
  	from tabProjectBoekingsRegel
    where pbrProjGid = @ProjGid
    	and	pbrPbGid = @pbGid
    	and pbrPbkGid = @pbkGid
    	and pbrRelGid = @RelGid
    	and pbrMutSoort = 0
    	and pbrMutatieDatum = @pbrMutatieDatum
    	and PbrRegelIsOnderdeelVan = 1
    	and pbrWeekStaatRegelnr > 0;

    if @weekstaatregelnr = 0 then
      //Als er op de dag geen uren staan maar wel een regelnummer is hierop zetten
    	select isNull(max(pbrWeekStaatRegelnr),0) into @weekstaatregelnr
    	from tabProjectBoekingsRegel
      where pbrProjGid = @ProjGid
      	and	pbrPbGid = @pbGid
      	and pbrPbkGid = @pbkGid
      	and pbrRelGid = @RelGid
      	and pbrMutSoort = 0
      	and PbrRegelIsOnderdeelVan = 1
      	and pbrWeekStaatRegelnr > 0;

  	  if (@weekstaatregelnr <> 0) then
  	  //Maak ook gelijk een 0-regel aan hiervoor dan
  	    insert into tabprojectBoekingsRegel
  	           (PbrPbkGid, PbrProjGid, PbrpbGid, PbrArtGid, pbrRelgid, pbrMutSoort,
  	            pbrWeekstaatRegelNr, pbrMutatieDatum,
  	            pbrOmschr, pbrOpm, pbrSelectieCodes)
  	    select  first PbrPbkGid, PbrProjGid, PbrpbGid, PbrArtGid, pbrRelgid, pbrMutSoort,
  	            pbrWeekstaatRegelNr, @pbrMutatieDatum,
  	            pbrOmschr, pbrOpm, pbrSelectieCodes
  	    from tabProjectBoekingsRegel
        where pbrProjGid = @ProjGid
      	 and	pbrPbGid = @pbGid
      	 and pbrPbkGid = @pbkGid
      	 and pbrRelGid = @RelGid
      	 and pbrMutSoort = 0
      	 and PbrRegelIsOnderdeelVan = 1
      	 and pbrWeekStaatRegelnr = @weekstaatregelnr;
      end if;
    end if;

    //Als er een Activiteitregel bestaat geef de overige kosten dan dit nummer
 	  if (@weekstaatregelnr <> 0) then
      update tabProjectBoekingsRegel
      set    pbrweekstaatregelnr = @weekstaatregelnr
      where  current of Cursor_tabProjectBoekingsRegels;
    end if;
  end for;

  set @@ErrorTextProcedure = 'Einde ProjectGenereerWeekStaatRegelnrOvKosten';
 	//call Trace(@@ErrorTextProcedure);
end;



create or replace procedure ProjectGroepsoortenPerStuk(in @ProjectgroepGid integer, in @SelectedParsoort integer)
begin
  declare @Projectgroep nchar(4);
  declare @Paragraaf    nchar(3);
  declare @ProjGrpnaam  nchar(40);
  declare @ProjectLower nchar(40);
  declare @Rksnaam      nchar(40);
  declare @RksZoekCode  nchar(10);
  declare @Soort        smallint;
  declare @IsCredit     smallint;

  set @@ErrorTextProcedure = 'ProjectGroepsoortenPerStuk > @ProjectgroepGid='+string(@ProjectgroepGid)+', @SelectedParsoort='+string(@SelectedParsoort);
  //call TraceBegin(@@ErrorTextProcedure);

  select ProjGrpGroep, ProjGrpOms into @Projectgroep, @ProjGrpnaam from tabProjectgroep where ProjGrpGid = @ProjectgroepGid;
  set @ProjectLower = Lower(@ProjGrpnaam);
  select Paragraaf into @Paragraaf from tabParagraaf, tabBalansCodeDetail where ParBlGid=BlGid and ParSoort=@SelectedParSoort;

  if @Projectgroep is not null and @Paragraaf is not null then
    if not exists (select 1 from tabProjectGroepSoort where ProjGrpSrtProjGrpGid = @ProjectgroepGid and ProjGrpSrtParSoort = @SelectedParSoort) then
      if not exists (select 1 from tabRekeningschema where RksInvoer = @Paragraaf + @Projectgroep) then
        case @SelectedParSoort
        when 130 then
          set @RksNaam = 'Onderhanden werk '+@ProjectLower;
          set @Soort = 1;
          set @IsCredit = 0;
        when 140 then
          set @RksNaam = 'Gefactureerde termijnen '+@ProjectLower;
          set @Soort = 2;
          set @IsCredit = 1;
        when 150 then
          set @RksNaam = 'Opbr. proj. '+@ProjectLower;
          set @Soort = 5;
          set @IsCredit = 1;
        when 160 then
          set @RksNaam = 'Kostpr. proj. '+@ProjectLower;
          set @Soort = 4;
          set @IsCredit = 0;
        when 170 then
          set @RksNaam = 'Dekking tarieven proj. '+@ProjectLower;
          set @Soort = 4;
          set @IsCredit = 1;
        end case;
	      set @RksZoekCode = @ProjGrpnaam;
        insert into tabRekeningschema(RksNummer, DefaultSoort, RksValNummer, DefaultBoekzijde, RksZoekCode, RksNaam)
        select @Paragraaf + @Projectgroep, @Soort, ValNummer, @IsCredit, @RksZoekCode, @RksNaam from tabValuta where IsBasisValuta<>0;
      end if;
      insert into tabProjectGroepSoort(ProjGrpSrtProjGrpGid, ProjGrpSrtParSoort, ProjGrpSrtRksGid)
      select @ProjectGroepGid, @SelectedParSoort, RksGid from tabRekeningschema where RksInvoer = @Paragraaf + @Projectgroep;
    end if;
  end if;

  set @@ErrorTextProcedure = 'ProjectGroepsoortenPerStuk';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure ProjectGroepsoortenVullen(in @ProjectgroepGid integer, in @SelectedParsoort integer)
begin
  declare @Projectgroep nchar(4);
  declare @Paragraaf nchar(3);

  set @@ErrorTextProcedure = 'ProjectGroepsoortenVullen > @ProjectgroepGid='+string(@ProjectgroepGid)+', @SelectedParsoort='+string(@SelectedParsoort);
  //call TraceBegin(@@ErrorTextProcedure);

  if @SelectedParSoort is null then
    call ProjectGroepsoortenPerStuk(@ProjectgroepGid, 130);
    call ProjectGroepsoortenPerStuk(@ProjectgroepGid, 140);
    call ProjectGroepsoortenPerStuk(@ProjectgroepGid, 150);
    call ProjectGroepsoortenPerStuk(@ProjectgroepGid, 160);
    call ProjectGroepsoortenPerStuk(@ProjectgroepGid, 170);
  else
    call ProjectGroepsoortenPerStuk(@ProjectgroepGid, @SelectedParsoort);
  end if;

  set @@ErrorTextProcedure = 'ProjectGroepsoortenVullen';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProjectHeeftPermissie.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='ProjectHeeftPermissie') then
  drop procedure ProjectHeeftPermissie;
end if;

create function ProjectHeeftPermissie (in @ProjectBoomGid int, in @RelGid int, in @ArtGid int)
returns smallint
  // Implementeert Processen, p1 Bepalen gebruikstoestemming uit do 633 Gebruikstoestemming
  // Parameters mogen null zijn.
begin
  declare @result smallint;

  set @@ErrorTextProcedure = 'ProjectHeeftPermissie';
  //call TraceBegin(@@ErrorTextProcedure + ' met de volgende parameters: @ProjectBoomGid=' + string (@ProjectBoomGid) + ';@RelGid=' + string(@RelGid) + ';@ArtGid=' + string (@ArtGid));

  set @result = 0;
  if @ArtGid is not null then
    if exists(select 1 from tabArtikel where ArtGid = @ArtGid and ArtSoort = 2) then
      set @result = 1;
      // WENS PG: Als er een Artgidje meekomt van een echt artikel dan altijd toestemming toekennen.
    end if;
  end if;

  if @result = 0 then
    if @ProjectBoomGid is null then
      // do 633  p1 Bepalen gebruikstoestemming:
      // ---------------------------------------
      // 2. Medewerker
      // 3. Activiteit
      // 4. Machine
      // 8. Medewerker en activiteit
      set @result = _ProjectHeeftMedewerkerTariefPermissie (@RelGid, @ArtGid);

      if @result is null then
        if @RelGid is not null and @ArtGid is not null then
          // 8. Medwerker en Activiteit
          if _ProjectHeeftMedewerkerTariefPermissie (null, @ArtGid) = 1 and _ProjectHeeftMedewerkerTariefPermissie (@RelGid, null) = 1 then
            set @result = 1;
          else
            set @result = 0;
          end if;
        else
          // 2. Medewerker
          // 3. Activiteit
          // 4. Machine

          // Database error!!!
          // Default permissie should have been found
        end if;
      end if;
    else
      // do 633  p1 Bepalen gebruikstoestemming:
      // ---------------------------------------
      // 1. ProjectOnderdeel
      // 2. Medewerker
      // 3. Activiteit
      // 4. Machine
      // 5. Projectonderdeel en medewerker
      // 6. Projectonderdeel en activiteit
      // 7. Projectonderdeel en machine
      // 8. Medewerker en activiteit
      // 9. Projectonderdeel, medewerker en activiteit

      set @result = _ProjectHeeftOnderdeelPermissie (@ProjectBoomGid, @RelGid, @ArtGid);
    end if;
  end if;

  //call TraceEind(@@ErrorTextProcedure + ' returns:' + string (@result));
  return (@result);

end;


create or replace procedure ProjectKopieren(
  in @ProjGidOrigineel       integer,
  in @ProjCodeKopie          nchar(10),
  in @ProjOmsKopie           nchar(80),
  in @PrijsafsprakenKopieren smallint,
  in @PermissiesKopieren     smallint,
  out @ProjGidKopie          integer)
begin
  declare @PbGidBronNiveau1 integer;
  declare @PbGidDoelNiveau1 integer;

  set @@ErrorTextProcedure = 'ProjectKopieren > @ProjGidOrigineel=' + string(@ProjGidOrigineel) + ', @ProjCodeKopie=' + string(@ProjCodeKopie)+ ', @ProjOmsKopie='+string(@ProjOmsKopie);
  //call TraceBegin(@@ErrorTextProcedure);

  //variabelen initialiseren
  set @ProjGidKopie     = null;
  set @PbGidBronNiveau1 = null;
  set @PbGidDoelNiveau1 = null;

  set @PrijsafsprakenKopieren = IsNull(@PrijsafsprakenKopieren, 0);
  set @PermissiesKopieren     = IsNull(@PermissiesKopieren, 0);

  //kopieren starten
  insert into tabProject with auto name
  select
    //== Niet overgenomen velden
    //ProjGid,
    //== Velden opgegeven door de gebruiker
    @ProjCodeKopie as ProjCode,
    @ProjOmsKopie as ProjOmschr,
    //== Velden overnemen uit originele record
    ProjHoofdProjGid,
    ProjOpm,
    ProjSoort,
    ProjBTWcode,
    ProjAfwBtwCode,
    ProjNawGid,
    ProjProjLeiderRelGid,
    ProjProjGrpGid,
    ProjDebContactPersRelGid,
    ProjVerkPrijsMedewPrevaleert,
    ProjKostPrijsMedewPrevaleert,
    ProjProjMutBoekenAlsDeclarabel,
    ProjUrenHeleFactuurEenheden,
    ProjBtcNummer,
    ProjLvcNummer,
    ProjIsInkoopCombinatie,
    ProjnawGidFactuur,
    ProjNawGidOmzet,
    ProjNawGidPrijzen,
    //== velden die gereset worden
    0 as ProjStatus,
    0 as ProjOfferteStatus,
    0 as ProjBegrotingsStatus
  from
    tabProject
  where
    ProjGid = @ProjGidOrigineel;

  //ProjGid van nieuwe project ophalen
  if @@RowCount = 1 then
    set @ProjGidKopie = @@Identity;

    select PbGid into @PbGidBronNiveau1 from tabProjectBoom where pblevel = 1 and PbProjGid = @ProjGidOrigineel;
    select PbGid into @PbGidDoelNiveau1 from tabProjectBoom where pblevel = 1 and PbProjGid = @ProjGidKopie;

    //call trace('@PbGidBronNiveau1='+string(@PbGidBronNiveau1)+', @PbGidDoelNiveau1='+string(@PbGidDoelNiveau1));

    //projectdefault gebruikstoestemming kopieren
    insert into tabProjectPermissie (ppmPbGid, ppmArtGid, ppmRelGid, ppmPermissie)
    select
      @PbGidDoelNiveau1,
      ppmArtGid,
      ppmRelGid,
      ppmPermissie
    from
      tabProjectPermissie
    where ppmPbGid = @PbGidBronNiveau1
      and ppmArtGid is null
      and ppmrelGid is null;
    //call trace('Aantal gebruikspermissies op projectniveau gekopieerd='+string(@@RowCount));

    //projectdefault factuurverdichting overnemen van bron- naar doelproject
    update tabProjectFactuurVerdichting PfvDoel
    set    PfvDoel.PfvdActPerOnderdeel            = PfvBron.PfvdActPerOnderdeel,
           PfvDoel.PfvdActPerOnderdeelSpecAfdruk  = PfvBron.PfvdActPerOnderdeelSpecAfdruk,
           PfvDoel.PfvdArtPerOnderdeel            = PfvBron.PfvdArtPerOnderdeel,
           PfvDoel.PfvdArtPerOnderdeelSpecAfdruk  = PfvBron.PfvdArtPerOnderdeelSpecAfdruk,
           PfvDoel.PfvdFactVerdActAct             = PfvBron.PfvdFactVerdActAct,
           PfvDoel.PfvdFactVerdActMedew           = PfvBron.PfvdFactVerdActMedew,
           PfvDoel.PfvdFactVerdActOpbrGrp         = PfvBron.PfvdFactVerdActOpbrGrp,
           PfvDoel.PfvdFactVerdArtArt             = PfvBron.PfvdFactVerdArtArt,
           PfvDoel.PfvdFactVerdArtOpbrGrp         = PfvBron.PfvdFactVerdArtOpbrGrp,
           PfvDoel.PfvdFactVerdMachMach           = PfvBron.PfvdFactVerdMachMach,
           PfvDoel.PfvdFactVerdMachOpbrGrp        = PfvBron.PfvdFactVerdMachOpbrGrp,
           PfvDoel.PfvdMachPerOnderdeel           = PfvBron.PfvdMachPerOnderdeel,
           PfvDoel.PfvdMachPerOnderdeelSpecAfdruk = PfvBron.PfvdMachPerOnderdeelSpecAfdruk,
           PfvDoel.PfvdTekstOpFactuur             = PfvBron.PfvdTekstOpFactuur
    from   tabProjectFactuurVerdichting PfvBron
    where  PfvBron.PfvdPbGid = @PbGidBronNiveau1
       and PfvDoel.PfvdPbGid = @PbGidDoelNiveau1;
    //call trace('Aantal factuurverdichtingen op projectniveau gekopieerd='+string(@@RowCount));

    //prijsafspraken op projectniveau kopieren (dus niet onderdeelniveau: dat gebeurt in de proc projectonderdelen kopieren)
    if @PrijsafsprakenKopieren = 1 then
      insert into tabProjectPrijsafspraak (ppaPbGid, ppaArtGid, ppaRelGid, ppaVerkoopprijsExBtw)
      select
        @PbGidDoelNiveau1,
        ppaArtGid,
        ppaRelGid,
        ppaVerkoopprijsExBtw
      from
        tabProjectPrijsafspraak
      where
        ppaPbGid = @PbGidBronNiveau1;
      //call trace('Aantal prijsafspraken op projectniveau gekopieerd='+string(@@RowCount));
    end if;

    //gebruikstoestemmingen op projectniveau kopieren (dus niet onderdeelniveau: dat gebeurt in de proc projectonderdelen kopieren)
    if @PermissiesKopieren = 1 then
      insert into tabProjectPermissie (ppmPbGid, ppmArtGid, ppmRelGid, ppmPermissie)
      select
        @PbGidDoelNiveau1,
        ppmArtGid,
        ppmRelGid,
        ppmPermissie
      from
        tabProjectPermissie
      where ppmPbGid = @PbGidBronNiveau1
        and (   ppmArtGid is not null
             or ppmrelGid is not null); //alles kopieren behalve de projectdefault; dat gebeurt al eerder in deze proc!
    end if;

  end if;

  //MR 16-aug-2012 bug #35878: Kopieer ook de vrije rubrieken mee.
  //call Trace('ProjectKopieren > Vrije rubrieken');
  call VrKopieerRecord('PRJ',0,0,'PRJ',0,0,@ProjGidOrigineel,@ProjGidKopie);

  set @@ErrorTextProcedure = 'ProjectKopieren > @ProjGidKopie='+string(@ProjGidKopie);
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProjectLeesRekeningObvProjectGroep.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// -----------------------------------------------------------------------
// --------- Lezen rekening van paragraafsoort voor projectgroep ---------
// -----------------------------------------------------------------------

if exists (select 1 from sys.sysProcedure where proc_name='ProjectLeesRekeningObvProjectGroep') then
  drop procedure ProjectLeesRekeningObvProjectGroep;
end if;

create procedure ProjectLeesRekeningObvProjectGroep(in @ProjGrpGid integer, in @ParSoort integer, out @RksGID integer)
begin

  //call TraceBegin('ProjectLeesRekeningObvProjectGroep(@ProjGrpGid='+string(@ProjGrpGid)+', @ParSoort='+string(@ParSoort)+')');

  //Rekening opzoeken in de groep
  set @RksGID = null;
  select ProjGrpSrtRksGid into @RksGID from tabProjectGroepSoort where ProjGrpSrtProjGrpGid = @ProjGrpGid and ProjGrpSrtParSoort = @ParSoort;

  if @RksGID is null then
    // Rekening bestaat nog niet? -> aanmaken dan!!
    call ProjectGroepsoortenVullen(@ProjGrpGid, @ParSoort);
    // En nogmaals opvragen
    select ProjGrpSrtRksGid into @RksGID from tabProjectGroepSoort where ProjGrpSrtProjGrpGid = @ProjGrpGid and ProjGrpSrtParSoort = @ParSoort;
  end if;

  //call TraceEind('ProjectLeesRekeningObvProjectGroep(@RksGID='+string(@RksGID)+')');

end;


