create procedure ProjectOntkoppelVanJournaalpost(in @PbkGid integer)
begin
  //call TraceBegin('LoskoppelenArchiefstukVanJournaalpost(@PbkGid = '+string(@PbkGid)+ ')' );

  set @@OverRuleLock                = 1;
  set @@FiredByTriggerJournaalRegel = 1;
  set @@FiredByTriggerJournaalPost  = 1;

  update tabJournaalRegel set JrPbrGid = null where JrPbrGid in (select PbrGid from tabProjectboekingsRegel where PbrPbkGid = @PbkGid);
  update tabProjectBoekingsKop set PbkHerkomst = 2 where PbkGid = @PbkGid;

  set @@FiredByTriggerJournaalregel = 0;
  set @@FiredByTriggerJournaalPost  = 0;
  set @@OverRuleLock                = 0;

  //call TraceEind('ProjectOntkoppelVanJournaalpost');
end;


//$Workfile: ProjectPermissieBijwerken.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// ------------------------------------------------------------------------
// --------- Bijwerken van Projectgebruikstoestemmingen           ---------
// ------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name= 'ProjectPermissieBijwerken') then
  drop procedure ProjectPermissieBijwerken;
end if;

create procedure ProjectPermissieBijwerken (in @PBoomGid int, in @RelGid int, in @ArtGid int, in @Permissie smallint)
begin
  declare @PermissieGid int;

  set @@ErrorTextProcedure = 'ProjectPermissieBijwerken';
  //call TraceBegin(@@ErrorTextProcedure);


  // Default permissies voor individuele projectonderdelen (bomen), project medewerkers en tarieven mogen niet worden verwijderd.
  // Het niet aanwezig zijn van deze records wordt beschouwd als een corrupte database.
  if  @Permissie is null then
    if (
      (@PBoomGid is not null and @RelGid is null and @ArtGid is null) or
      (@PBoomGid is null and @RelGid is not null and @ArtGid is null) or
      (@PBoomGid is null and @RelGid is null and @ArtGid is not null)
    ) then
      // OK dit is een van de default permissies, niets aan doen dus!!!!
    //call TraceEind(@@ErrorTextProcedure);
      return;
    end if;
  end if;

  // NOOT DG Altijd weggooien en afhankelijk van @Permissie toevoegen kan natuurlijk ook.
  select ppmGid into @PermissieGid from tabProjectPermissie
  where
   ((@PBoomGid is null and ppmPbGid is null) or (ppmPbGid = @PBoomGid)) and
   ((@RelGid is null and ppmRelGid is null) or (ppmRelGid = @RelGid)) and
   ((@ArtGid is null and ppmArtGid is null) or (ppmArtGid = @ArtGid))
  ;

  if @Permissie is null then
    if @PermissieGid is not null then
      delete from tabProjectPermissie where ppmGid = @PermissieGid
    end if;
  else
    if @PermissieGid is null then
      insert into tabProjectPermissie (ppmPbGid, ppmRelGid, ppmArtGid, ppmPermissie) values (@PBoomGid, @RelGid, @ArtGid, @Permissie);
    else
      update tabProjectPermissie set ppmPermissie = @Permissie where ppmGid = @PermissieGid;
    end if;
  end if;

//call TraceEind(@@ErrorTextProcedure);

end;


// ----------------------------------------------------------------------------------------
// -------- ProjectWeekStaatVerplaatsen tbv project weekstaat -----------------------------
// -------- Een weekstaat verplaatsen. Kan zijn andere medewerker, jaar en/of weeknummer --
// ----------------------------------------------------------------------------------------
create or replace procedure ProjectWeekStaatVerplaatsen(
  in    @PbkGid   integer,
  in    @Relgid   integer,
  in    @WeekJaar integer,
  in    @WeekNr   integer
)
begin
  declare @IncDays          integer;
  declare @OudeStartDatum   datetime;
  declare @NieuweStartDatum datetime;
  declare @pbkHerkomst      integer;

  set @@ErrorTextProcedure = 'ProjectWeekStaatVerplaatsen > @PbkGid='+string(@pbkGid)+',@Relgid='+string(@Relgid)+',@WeekJaar='+string(@WeekJaar)+',@WeekNr='+string(@WeekNr);
 	//call TraceBegin(@@ErrorTextProcedure);

  Select ISOWeekYearToDateTime(pbkWeekJaar, pbkWeeknr, 1), ISOWeekYearToDateTime(@Weekjaar, @WeekNr, 1), pbkHerkomst into @OudeStartDatum, @NieuweStartDatum, @pbkHerkomst
  from tabProjectBoekingsKop
  where pbkGid = @pbkGid;

  set @IncDays = DAYS(@OudeStartDatum, @NieuweStartDatum);

  //Wijzig de kop naar de nieuwe week.
  //Zet herkomst even op 0. Als de herkomst een weekstaat is word de info van week weer teruggezet naar de oude in de trigger.
  //Mischien kan de code in de trigger met de tijd wel weg.
  Update tabProjectBoekingsKop
  Set PbkHerkomst = 0,
      pbkRelGid   = @RelGid,
      pbkWeekJaar = @Weekjaar,
      pbkWeeknr   = @WeekNr
  where pbkGid = @pbkGid;

  //En de herkomst weer terug zetten
  Update tabProjectBoekingsKop
  Set PbkHerkomst = @pbkHerkomst
  where pbkGid = @pbkGid;

  //Tel het aantal dagen erbij op. Maar alleen voor de regels die tot de weekstaat behoren.
  Update tabProjectBoekingsRegel
  Set pbrRelGid   = @RelGid,
      PbrMutatieDatum = DATEADD( day, @IncDays, PbrMutatieDatum)
  where pbrpbkGid = @pbkGid
  and PbrRegelIsOnderdeelVan = 1;

  set @@ErrorTextProcedure = 'ProjectWeekStaatVerplaatsen > @PbkGid='+string(@pbkGid)+',@Relgid='+string(@Relgid)+',@WeekJaar='+string(@WeekJaar)+',@WeekNr='+string(@WeekNr);
  //call TraceEind(@@ErrorTextProcedure);
  //call ProjectWeekStaatVerplaatsen(24800012,5,2011,19);
end;

// ----------------------------------------------------------------------------------------
// -------- ProjectWeekStaatWijzigProjEnAct tbv project weekstaat -------------------------
// -------- Van een weekstaatregel project en activiteit wijzigen -------------------------
// ----------------------------------------------------------------------------------------
create or replace procedure ProjectWeekStaatWijzigProjEnAct(
  in    @PbkGid    		    integer,
  in    @OldProjGid    		integer,
  in    @OldPbGid    		  integer,
  in    @OldArtGid    		integer,
  in    @WeekstaatRegelnr integer,
  in    @NewProjGid    		integer,
  in    @NewPbGid    		  integer,
  in    @NewArtGid    		integer
  )
begin
  declare @ProjectVerkoopprijs      numeric(15,3); //De bepaalde verkoopprijs
  declare @ProjectKostprijs         numeric(15,3); //De bepaalde kostprijs
  declare @ProjectPbGid             integer;
  declare @ProjSoort                integer;
  declare @PbSoort                	integer;
  declare @DoorbelPerc              numeric(15,2);
  declare @NewartAantDecAantallen   integer;
  declare @NewPArtFactEenheidFactor numeric(4,2);
  declare @NewArtTekst   						long nvarchar;
  declare @NewArtOms   							nchar(40);
  set @@ErrorTextProcedure = 'ProjectWeekStaatWijzigProjEnAct > @PbkGid='+string(@pbkGid)+',@OldProjGid='+string(@pbkGid)+',@OldPbGid='+string(@pbkGid)+',@OldArtGid='+string(@pbkGid)+',@WeekstaatRegelnr='+string(@pbkGid)+',@NewProjGid='+string(@pbkGid)+',@NewPbGid='+string(@pbkGid)+',@NewArtGid='+string(@pbkGid);
 	//call TraceBegin(@@ErrorTextProcedure);

  //Het nieuwe aantal decimalen en PartFactEenheidFactor
  select artAantDecAantallen, PArtFactEenheidFactor, ArtTekst, ArtOms into @NewartAantDecAantallen, @NewPArtFactEenheidFactor, @NewArtTekst, @NewArtOms
  from tabartikel
  left outer join tabArtikelTeksten on (ArtTekstArtGid = ArtGid)
																		and ((ArtSoort = 2 and ArtTekstDocSoort = 50) or (ArtSoort <> 2 and ArtTekstDocSoort is null))
																		and (ArtTaalGid = (select DefaultTaalGid from tabVastegegevens))
	inner join tabProjectArtikel on pArtArtgid = ArtGid
  where artgid = @NewArtGid;

  select ProjSoort, PbSoort into @ProjSoort,@pbSoort
  from tabproject
  inner join tabProjectBoom on pbProjGid = projgid and pbGid = @NewPbGid
  where ProjGid = @NewProjGid;

  //Update alle bijbehorende records.
  FOR @Cursor AS CURSOR_Regels CURSOR FOR
  Select PbrProjGid @ProjGid,
         PbrPbGid @PbGid,
         PbrArtGid @ArtGid,
         PbrRelGid @RelGid,
         pbrMutSoort @pbrMutSoort,
         PbrArtPartijGid @PbrArtPartijGid,
         pbrAantalGeboekt @pbrAantalGeboekt,
         pbrAantalDeclarabel @pbrAantalDeclarabel,
         PbrIsDirecteInkoop @PbrIsDirecteInkoop,
         ArtIsPartijRegistreren @ArtIsPartijRegistreren,
         artAantDecAantallen @artAantDecAantallen,
         ArtAantDecPrijzen @ArtAantDecPrijzen,
         PbrDoorbelastPercentage @PbrDoorbelastPercentage,
         PbrKostprijs @PbrKostprijs,
         PbrVerkoopprijs @PbrVerkoopprijs,
         PArtSoort @pArtSoort,
         PbrPArtFactEenheidFactor @PArtFactEenheidFactor,
				 pbrOmschr @pbrOmschr,
				 ArtIsPartijAparteTekstOpFactuur @ArtIsPartijAparteTekstOpFactuur,
				 ArtTekst @ArtTekst,
				 ArtOms	@ArtOms
  from tabProjectBoekingsRegel
  inner join tabartikel on ArtGid = pbrArtGid
  left outer join tabArtikelTeksten on (ArtTekstArtGid = ArtGid)
																		and ((ArtSoort = 2 and ArtTekstDocSoort = 50) or (ArtSoort <> 2 and ArtTekstDocSoort is null))
																		and (ArtTaalGid = (select DefaultTaalGid from tabVastegegevens))
	inner join tabProjectArtikel on pArtArtgid = ArtGid
  where PbrRegelIsOnderdeelVan = 1
  and pbrpbkGid 	= @pbkgid
  and pbrProjgid 	= @OldProjGid
  and pbrpbgid 		= @OldpbGid
  and (pbrArtGid	= @OldArtGid or (pbrMutSoort <> 0 and @OldArtGid = @NewArtGid))
  and pbrWeekstaatRegelnr = @WeekstaatRegelNr
  for update
  do

    if @PbrMutSoort is null or
       @ProjGid is null or
       @PbGid is null or
       @ArtGid is null or
       ((@ArtIsPartijRegistreren = 1) and
        (@PbrArtPartijGid is null) and
        (@PbrIsDirecteInkoop = 0)) or
       ((@PbrMutSoort <> 2) and (@pArtSoort is null)) or
       ((@PbrMutSoort = 0) and (@pArtSoort  <> 0)) or
       ((@PbrMutSoort = 1) and (@pArtSoort  <> 1)) then
      //1 van de bovenstaande checks voldoet niet, dus GEEN prijs bepalen:
      //nav bug #21102 de prijzen op nul zetten:
      if (@PbrIsDirecteInkoop = 0) then//bij directe inkoop niet aanpassen als aantal veranderd, zie ontwerp rev 1.05
       set @PbrKostprijs = 0;
      end if;
      set @PbrVerkoopprijs = 0;
    else
      //nu door alle checks heen, dus echt prijs bepalen:
      //MR 07-mar-2011 bug #33348: Gebruik wel de @new velden voor de nieuwe verkoopenkostprijs.
      call BepaalProjectVerkoopEnKostprijs(@NewProjGid, @NewPbGid,(if @pbrMutSoort = 0 then @NewArtGid else @ArtGid endif), @PbrArtPartijGid, @RelGid, @PbrAantalDeclarabel,
                                           @ProjectVerkoopprijs,@ProjectKostprijs,@ProjectPbGid,@DoorbelPerc);

      set @PbrDoorbelastPercentage = @DoorbelPerc;

      if (@PbrDoorbelastPercentage is null) then
        set @PbrKostprijs   = round(@ProjectKostprijs, @ArtAantDecPrijzen);
        set @PbrVerkoopprijs  = round(@ProjectVerkoopprijs, @ArtAantDecPrijzen);
      end if ;
    end if;

    //En Opslaan
    update tabProjectBoekingsRegel
    set PbrProjGid = @NewProjGid,
	      PbrPbGid	 = @NewPbGid,
	      PbrArtGid	 = (if pbrMutSoort = 0 then @NewArtGid else @ArtGid endif),
        pbrAantalGeboekt    =(if (@artAantDecAantallen <> @NewartAantDecAantallen) then
                        	      round(@pbrAantalgeboekt,@NewartAantDecAantallen)
                      	      else
                        	      @pbrAantalgeboekt
                      	      endif),
        pbrAantalDeclarabel	=(if (@ProjSoort <> 3) then
                                if (@artAantDecAantallen <> @NewartAantDecAantallen) then
                                  if ((@PArtFactEenheidFactor <> @NewPArtFactEenheidFactor) and (@NewPArtFactEenheidFactor <> 0)) then
                          	        round(@pbrAantalgeboekt/@NewPArtFactEenheidFactor,@NewartAantDecAantallen)
                          	      else
                                    if ((@NewPArtFactEenheidFactor = 1)) then
                            	        round(@pbrAantalgeboekt,@NewartAantDecAantallen)
                                    else
                            	        round(@pbrAantalDeclarabel,@NewartAantDecAantallen)
                            	      endif
                          	      endif
                        	      else
                                  if ((@PArtFactEenheidFactor <> @NewPArtFactEenheidFactor) and (@NewPArtFactEenheidFactor <> 0)) then
                            	      round(@pbrAantalgeboekt/@NewPArtFactEenheidFactor,@NewartAantDecAantallen)
                            	    else
                                    if ((@NewPArtFactEenheidFactor = 1)) then
                            	        @pbrAantalgeboekt
                                    else
                                      if (@NewPArtFactEenheidFactor <> 0) then
                                	      round(@pbrAantalgeboekt/@NewPArtFactEenheidFactor,@NewartAantDecAantallen)
                                      else
                            	          @pbrAantalDeclarabel
                            	        endif
                            	      endif
                                  endif
                        	      endif
                      	      else
                      	        @pbrAantalDeclarabel
                      	      endif),
        PbrKostprijs = @PbrKostprijs,
        PbrVerkoopprijs = @PbrVerkoopprijs,
        PbrDoorbelastPercentage = @PbrDoorbelastPercentage,
        PbrPArtFactEenheidFactor = @NewPArtFactEenheidFactor,
				PbrOmschr = (if (@ArtIsPartijAparteTekstOpFactuur <> 1) then
											if (@ArtTekst = @PbrOmschr) or (@ArtOms = @PbrOmschr) then //Hetzelfde gebleven, dus haal de nieuwe op.
												if @NewArtTekst <> '' then
													@NewArtTekst
												else
													@NewArtOms
												endif
											else
												@PbrOmschr
											endif
										else
										 @PbrOmschr
										endif)
    where  current of CURSOR_Regels;
  end for;

  set @@ErrorTextProcedure = 'ProjectWeekStaatWijzigProjEnAct > @PbkGid='+string(@pbkGid)+',@OldProjGid='+string(@pbkGid)+',@OldPbGid='+string(@pbkGid)+',@OldArtGid='+string(@pbkGid)+',@WeekstaatRegelnr='+string(@pbkGid)+',@NewProjGid='+string(@pbkGid)+',@NewPbGid='+string(@pbkGid)+',@NewArtGid='+string(@pbkGid);
  //call TraceEind(@@ErrorTextProcedure);
end;

// **********************************************
// Projectwerkbonregel: doorschuiven regels
// **********************************************

if exists (select 1 from sys.sysProcedure where proc_name='ProjectWerkbonRegelDoorschuivenRegelNrs') then
  drop procedure ProjectWerkbonRegelDoorschuivenRegelNrs;
end if;

create procedure ProjectWerkbonRegelDoorschuivenRegelNrs(
 in @PwbkGid   integer,
 in @VanRegelNr integer,   // Vanaf welk regelnummer doorschuiven (indien leeg, dan wordt 1 gebruikt!)
 in @Delta      integer    // Indien leeg, dan wordt 1 gebruikt (1 doorschuiven), maar nu kan ook worden teruggescvhoven indien nodig (@delta=-1)
)
begin
  set @@ErrorTextProcedure = 'ProjectWerkbonRegelDoorschuivenRegelNrs(@PwbkGid='+string(@PwbkGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @Delta is null then
    set @Delta = 1;
  end if;
  if @VanRegelNr is null then
    set @VanRegelNr = 1
  end if;

  update tabProjectWerkbonRegel
  set    PwbrRegelNr = PwbrRegelNr + @Delta
  where  PwbrPwbkGid = @PwbkGid
     and PwbrRegelNr >= @VanRegelNr
  order by PwbrRegelNr * sign(@Delta) desc; // Bij negatief moeten we vanaf de kleinste werken, anders vanaf de grootste!

  set @@ErrorTextProcedure = 'ProjectWerkbonRegelDoorschuivenRegelNrs(@PwbkGid='+string(@PwbkGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


// ********************************************
// Projectwerkbonregel: verplaatsen regel
// ********************************************

if exists (select 1 from sys.sysProcedure where proc_name='ProjectWerkbonRegelVerplaatsRegelNr') then
  drop procedure ProjectWerkbonRegelVerplaatsRegelNr;
end if;

create procedure ProjectWerkbonRegelVerplaatsRegelNr(
 in @PwbkGid    integer,
 in @VanRegelNr  integer,   // Vanaf welk regelnummer verplaatsen
 in @NaarRegelNr integer    // Naar  welk regelnummer verplaatsen
)
begin
  set @@ErrorTextProcedure = 'ProjectWerkbonRegelVerplaatsRegelNr(@PwbkGid='+string(@PwbkGid)+', @VanRegelNr=' + string(@VanRegelNr)+', @NaarRegelNr=' + string(@NaarRegelNr) + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @VanRegelNr <> @NaarRegelNr then
    // Eerst de betreffende regel een speciaal nummer geven

    update tabProjectWerkbonRegel
    set    PwbrRegelNr = 1000000000
    where  PwbrPwbkGid = @PwbkGid
       and PwbrRegelNr = @VanRegelNr;

    if @VanRegelNr < @NaarRegelNr then
      // Naar beneden verplaatsen
      // Geef vanaf regel VanRegelNr+1 tot NaarRegelNr de regels 1 nummer lager
      update tabProjectWerkbonRegel
      set    PwbrRegelNr = PwbrRegelNr - 1
      where  PwbrPwbkGid = @PwbkGid
         and PwbrRegelNr >  @VanRegelNr
         and PwbrRegelNr <= @NaarRegelNr
      order by PwbrRegelNr ;
    else
      // Naar boven verplaatsen
      update tabProjectWerkbonRegel
      set    PwbrRegelNr = PwbrRegelNr + 1
      where  PwbrPwbkGid = @PwbkGid
         and PwbrRegelNr >= @NaarRegelNr
         and PwbrRegelNr <  @VanRegelNr
      order by PwbrRegelNr desc;
    end if;

    // Als laatste de hernoemde keurig in het rijtje zetten
    update tabProjectWerkbonRegel
    set    PwbrRegelNr = @NaarRegelNr
    where  PwbrPwbkGid = @PwbkGid
       and PwbrRegelNr = 1000000000;

  end if;

  set @@ErrorTextProcedure = 'ProjectWerkbonRegelVerplaatsRegelNr(@PwbkGid='+string(@PwbkGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


