create procedure ProjectWerkbonResetGegenereerdVolgnummer(in @Nummer numeric(10,0))
begin
  declare @HuidigeNummer numeric(10,0);

  set @@ErrorTextTrigger = 'ProjectWerkbonResetGegenereerdVolgnummer';
  //call TraceBegin(@@ErrorTextTrigger);

  select ProjVastStartNummerWerkbon into @HuidigeNummer from tabProjectVastegegevens;

  if (@HuidigeNummer = @Nummer + 1) and (@HuidigeNummer > 1) then
    update tabProjectVastegegevens set ProjVastStartNummerWerkbon = @Nummer;
  end if;

  set @@ErrorTextTrigger = 'ProjectWerkbonResetGegenereerdVolgnummer';
  //call TraceEind(@@ErrorTextTrigger);

end;


//---------------------------------------------------------------------
//----------------------------Volgnummer werkbon genereren-------------
//---------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='ProjectWerkbonVolgnummerGenereren') then
  drop procedure ProjectWerkbonVolgnummerGenereren;
end if;

create procedure ProjectWerkbonVolgnummerGenereren(in @Forceer smallint, out @Nummer numeric(10,0))
begin
  declare @Genereren   numeric(10,0);
  declare @StartNummer numeric(10,0);
  declare @Gevonden    integer;

  set @@ErrorTextTrigger = 'ProjectWerkbonVolgnummerGenereren';
  //call TraceBegin(@@ErrorTextTrigger);

  set @Nummer = 1;

  if @Forceer = 1 then
    set @Genereren = 1;
    select ProjVastStartNummerWerkbon into @StartNummer from tabProjectVasteGegevens;
  else
    select 1, ProjVastStartNummerWerkbon into @Genereren, @StartNummer from tabProjectVasteGegevens;
  end if;

  if @genereren = 1 then
    set @Gevonden = 0;

    while @Gevonden = 0
    loop
      set @Nummer = null;

      select Min(PwbkVolgnummer) into @Nummer from tabProjectWerkbonKop where PwbkVolgnummer >= @StartNummer;

      if @Nummer is null then
        set @Gevonden = 1;
        set @Nummer = @StartNummer;
      else
        if @Nummer = @StartNummer then
          // Dit Nummer is er al, dus ophogen en weer opnieuw in loop(@Gevonden blijft 0)
          if @StartNummer = 9999999999 then
            set @StartNummer = 1;
          else
            set @StartNummer = @Nummer + 1;
          end if
        else
          // Eerstvolgende ligt toch hoger, dus we kunnen gewoon het StartNummer gebruiken
          set @Nummer = @StartNummer;
          set @Gevonden = 1;
        end if;
      end if;
    end loop;

    if @Nummer = 9999999999 then
      update tabProjectVasteGegevens set ProjVastStartNummerWerkbon = 1;
    else
      update tabProjectVasteGegevens set ProjVastStartNummerWerkbon = @Nummer+1;
    end if;
  end if;

  set @@ErrorTextTrigger = 'ProjectWerkbonVolgnummerGenereren';
  //call TraceEind(@@ErrorTextTrigger);
end;


create or replace procedure ProjectWinstnemingenBoeken(in @ProjectGid         integer,
                                            in @DgbGid             integer,
                                            in @Boekdatum          date,
                                            in @Stuknummer         numeric(10,0),
                                            in @TeNemenKosten      numeric(15,3),
                                            in @TeNemenOpbrengsten numeric(15,3),
                                            inout @BoekgangGid     integer)
begin
  declare @PwnGid                 integer;
  declare @ProjGid                integer;
  declare @ProjGrpGid             integer;
  declare @JpGid                  integer;
  declare @ProjCode               nchar(10);
  declare @ProjOmschr             nchar(40);
  declare @RksGidGefactTerm       integer;
  declare @RksGidOmzetProj        integer;
  declare @RksGidKostprijsProj    integer;
  declare @RksGidOnderhanden      integer;
  declare @ReferentieVerplichtOHW smallint; //MR 20-aug-2010 bug #32672: als deze nodig is een referentie toevoegen
  declare @ReferentieOHW          nchar(10); //MR 20-aug-2010 bug #32672: Referentie is ProjCode als @ReferentieVerplichtOHW = 1
  declare @GenomenKosten          numeric(15,3);
  declare @GenomenOpbrengsten     numeric(15,3);
  declare @PwnVolgnr              integer; //MR 31-okt-2014 Volgnummer voor in de omschrijving van de boeking
  declare @ProjWinstnemingTekst   long nvarchar;

  set @@ErrorTextProcedure = 'ProjectWinstnemingenBoeken > ';
  //call TraceBegin(@@ErrorTextProcedure + '@DgbGid = ' + string(@DgbGid) + ', @Boekdatum = ' + string(@Boekdatum) + ', @Stuknummer = ' + string(@Stuknummer));

  set @ProjWinstnemingTekst = _A('Project %1! winstneming %2!');

  //call Trace('ProjectWinstnemingenBoeken >  Winstneming aanmaken');
  insert into tabProjectWinstneming (PwnProjGid, PwnDatum, PwnGenomenKosten, PwnGenomenOpbrengsten) values (@ProjectGid, @@VerwerkingsDatum, @TeNemenKosten, @TeNemenOpbrengsten);
  set @PwnGid = @@Identity;

  select ProjGid, ProjProjGrpGid, ProjCode, ProjOmschr, PwnGenomenKosten, PwnGenomenOpbrengsten, PwnVolgnr into @ProjGid, @ProjGrpGid, @ProjCode, @ProjOmschr, @GenomenKosten, @GenomenOpbrengsten, @PwnVolgnr
  from   tabProject inner join tabProjectWinstneming on (PwnProjGid = ProjGid and PwnGid = @PwnGid);

  //boekgang aanmaken indien dat nog niet gebeurd is
  if @BoekgangGid is null then
    insert into tabBoekingsGang(BoekGangBjGid, BoekgangBronId, BoekGangInGebruik, IsBoekGangDefinitief) values (@@BjGid, 24, 1, 0);
    set @BoekGangGid = @@Identity;
  end if;

  //call Trace('ProjectWinstnemingenBoeken > Journaalpost aanmaken');
  insert into tabJournaalPost (JpBoekGangGid, JpBjGid, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum,  JpIsInGebruik)
                       values (@BoekGangGid,  @@BjGid, @DgbGid,  @StukNummer,    _P(@ProjWinstnemingTekst, @ProjCode, string(@PwnVolgnr)), @BoekDatum, 1);
  set @JpGid = @@Identity;

  //Indien de module projecttermijnen niet actief is, dan kunnen we winstnemingopbrengsten paragrafen 140/150 overslaan.
  if IsModuleActive('pt') <> 0 then
    call ProjectGroepsoortenPerStuk(@ProjGrpGid, 140);
    select RksGid into @RksGidGefactTerm from tabRekeningschema
                       inner join (tabProjectGroepSoort
                                   inner join tabProject on (ProjGid = @ProjGid and ProjProjGrpGid = ProjGrpSrtProjGrpGid))
                                   on (ProjGrpSrtRksGid = RksGid and ProjGrpSrtParSoort = 140);

    call ProjectGroepsoortenPerStuk(@ProjGrpGid, 150);
    select RksGid into @RksGidOmzetProj from tabRekeningschema
                       inner join (tabProjectGroepSoort
                                   inner join tabProject on (ProjGid = @ProjGid and ProjProjGrpGid = ProjGrpSrtProjGrpGid))
                                   on (ProjGrpSrtRksGid = RksGid and ProjGrpSrtParSoort = 150);
  end if;

  call ProjectGroepsoortenPerStuk(@ProjGrpGid, 160);
  select RksGid into @RksGidKostprijsProj from tabRekeningschema
                     inner join (tabProjectGroepSoort
                                 inner join tabProject on (ProjGid = @ProjGid and ProjProjGrpGid = ProjGrpSrtProjGrpGid))
                                 on (ProjGrpSrtRksGid = RksGid and ProjGrpSrtParSoort = 160);

  call ProjectGroepsoortenPerStuk(@ProjGrpGid, 130);
  select RksGid, ReferentieVerplicht into @RksGidOnderhanden, @ReferentieVerplichtOHW from tabRekeningschema
                     inner join (tabProjectGroepSoort
                                 inner join tabProject on (ProjGid = @ProjGid and ProjProjGrpGid = ProjGrpSrtProjGrpGid))
                                 on (ProjGrpSrtRksGid = RksGid and ProjGrpSrtParSoort = 130);

  //Indien de module projecttermijnen niet actief is, dan kunnen we winstnemingopbrengsten paragrafen 140/150 overslaan.
  if IsModuleActive('pt') <> 0 then
    //call trace('ProjectWinstnemingenBoeken > Boeking gefactureerde projecttermijnen');
    insert into tabJournaalRegel
              (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer,  JrValutaBedrag, JrBasisBedrag)
       values ( @JpGid, @RksGidGefactTerm, _P(@ProjWinstnemingTekst, @ProjCode, string(@PwnVolgnr)), 0, @@BasisValutaNummer, @GenomenOpbrengsten, @GenomenOpbrengsten);

    //call trace('ProjectWinstnemingenBoeken > Boeking omzet projecten');
    insert into tabJournaalRegel
              (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
       values ( @JpGid, @RksGidOmzetProj, _P(@ProjWinstnemingTekst, @ProjCode, string(@PwnVolgnr)), 1, @@BasisValutaNummer, @GenomenOpbrengsten, @GenomenOpbrengsten);
  end if;

  //call trace('ProjectWinstnemingenBoeken > Boeking kostprijs projecten');
  insert into tabJournaalRegel
            (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag)
     values ( @JpGid, @RksGidKostprijsProj, _P(@ProjWinstnemingTekst, @ProjCode, string(@PwnVolgnr)), 0, @@BasisValutaNummer, @GenomenKosten, @GenomenKosten);

  //Referentie vullen als dit moet.
  if (@ReferentieVerplichtOHW = 1) then set @ReferentieOHW = @ProjCode end if;

  insert into tabJournaalRegel
            (JrJpGID, JrRksGid, OmsJournaalRegel, IsCreditBoeking, JrValNummer, JrValutaBedrag, JrBasisBedrag, JrReferentie)
     values ( @JpGid, @RksGidOnderhanden, _P(@ProjWinstnemingTekst, @ProjCode, string(@PwnVolgnr)), 1, @@BasisValutaNummer, @GenomenKosten, @GenomenKosten, @ReferentieOHW);

  //call Trace('ProjectWinstnemingenBoeken > Journaalpost afsluiten');
  update tabJournaalpost set JpIsInGebruik = 0 where JpGid = @JpGid;

  update tabProjectWinstneming set PwnJpGid = @JpGid, PwnBoekDatum = @Boekdatum where PwnGid = @PwnGid;

  set @@ErrorTextProcedure = 'ProjectWinstnemingenBoeken';
  //call TraceEind(@@ErrorTextProcedure);
end;


//$Workfile: RandomNumber2.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//TG 15-07-2005: Nieuwe randomNumber functie. RandomNumber genereert unieke nummers per connectie,
//maar bij 2 connecties krijg je dezelfde waarde terug. Dit risico wordt (aanzienlijk) verkleind
//als je gebruikt maakt van een seed. RANDOMNUMBER niet meer gebruiken!

//uit sybase newsgroups:
//While the object of rand() is to return a pseudo-random number, another
//of its characteristics is to have repeatable behaviour. rand() uses the
//same seed for each connection if a seed is not specified.

//We use   rand( datepart( ms, now() ))
//That's consistently random.
if exists (select 1 from sys.sysProcedure where proc_name='RandomNumber2') then
  drop procedure RandomNumber2;
end if;

create procedure RandomNumber2(out @Number integer)
begin
  //call TraceBegin('RandomNumber2');

  //MR Bug# 24073: in aanmaningen kwam het wel eens voor dat hetzelfde nummer teruggegeven werd.
  select DateDiff(millisecond, '00:00', now()) into @Number;
  //select cast(rand(datepart(ms, now()))*2000000000 as integer) into @Number;

  //call TraceEind('RandomNumber2(@Number='+string(@Number)+')');

end;


create or replace procedure rapBerekenVoertuigKosten(
                                          in @Selectie       smallint,  //0= Code, 1=ZoekCode
                                          in @BMCode_Van     nchar(20), //Van Code
                                          in @BMCode_Tot     nchar(20), //t/m Code
                                          in @BmZoekCode_Van nchar(20), //van zoekcode
                                          in @BmZoekCode_Tot nchar(20), //t/m zoekcode
                                          in @IsInclBTW      smallint,   //Bedragen incl of excl BTW
                                          in @VanDatum       date,      //Datum vanaf tonen
                                          in @TmDatum        date       //Datum tot en met tonen
                                          )

result (VrtGid                            integer,
        VrtKstVksGid                      integer,
        VksSoort                          smallint,
        VksCode                           nchar(20),
        VrtKstOmschrijving                nchar(40),
        KilometerIngebruikName            integer,
        VorigeKmStand                     integer,
        VrtKstKilometerstand              integer,
        VerredenKilometers                integer,
        VrtKstDatum                       date,
        VrtKstTijdvakBegin                date,
        VrtKstTijdvakEind                 date,
        VrtKstAantalDagen                 integer,
        AantalMaandenInGebruik            integer,
        AantalDagenInGebruik              integer,
        CumulatiefVerredenKilometers      integer,
        CumulatiefTankbeurten             integer,
        CumulatiefLiters                  numeric(15,3),
        CumulatiefBrandstofKosten         numeric(15,3),
        VrtKstIsIncBTW                    smallint,
        VrtKstBtwCode                     integer,
        BTWPerc                           numeric(15,3),
        VrtKstBedrag                      numeric(15,3),
        VasteKostenPerDag                 numeric(15,3),
        VasteKostenPerKM                  numeric(15,3),
        VasteKostenTotMetKostenDatum      numeric(15,3),
        VariabeleKostenPerKM              numeric(15,3),
        VariabeleKostenTotMetKostenDatum  numeric(15,3),
        VrtKstLiters                      numeric(15,3),
        PrijsPerLiter                     numeric(15,3),
        Verbruik                          numeric(15,3),
        GemiddeldVerbruik                 numeric(15,3),
        IsVerbruikAfwijkend               smallint,
        VrtKstBoekingMaken                smallint,
        VrtKstBoekDatum                   date,
        VrtKstRksGID                      integer,
        rksInvoer                         nchar(28),
        rksNaam                           nchar(40),
        VrtKstRksGIDTegen                 integer,
        rksInvoerTegen                    nchar(28),
        rksNaamTegen                      nchar(40),
        VrtKstJPGID                       integer,
        omsJournaalPost                   nchar(40)
        )

begin
  declare local temporary table tmpVoertuigKostenCalc(      //Voor opslag van data per voertuig
    tmpGid                              integer default autoincrement,
    tmpAantalMaandenInGebruik           integer,
    tmpAantalDagenInGebruik             integer,
    tmpCumulatiefTankbeurten            integer,
    tmpBTWPerc                          double,
    tmpKilometerIngebruikName           integer,
    tmpVrtKstBedrag                     double,
    tmpPrijsPerLiter                    double,
    tmpIsVerbruikAfwijkend              smallint,
    tmpCumulatiefLiters                 double,
    tmpCumulatiefBrandstofKosten        double,
    tmpCumulatiefVerredenKilometers     integer,
    tmpVasteKostenPerDag                double,
    tmpVasteKostenPerKM                 double,
    tmpVasteKostenTotMetKostenDatum     double,
    tmpVariabeleKostenPerKM             double,
    tmpVariabeleKostenTotMetKostenDatum double,
    tmpVerbruik                         double,
    tmpGemiddeldVerbruik                double,
    tmpVerredenKilometers               integer,
    tmpVorigeKmStand                    integer,
    tmpVrtKstBtwCode                    integer,
    tmpVrtKstDatum                      date,
    tmpVrtKstIsIncBTW                   smallint,
    tmpVrtKstKilometerstand             integer,
    tmpVrtKstLiters                     double,
    tmpVrtKstOmschrijving               nchar(40) default '',
    tmpVrtKstVksGid                     integer,
    tmpVrtKstTijdvakBegin               date,
    tmpVrtKstTijdvakEind                date,
    tmpVrtKstAantalDagen                integer,
    tmpIngebruikDatum                   date,
    tmpLaatsteTenaamstelling            date,
    tmpVrtGid                           integer,
    tmpVrtKstGid                        integer,
    tmpVksSoort                         smallint,
    tmpVrtKstBoekingMaken               smallint,
    tmpVrtKstBoekDatum                  date,
    tmpVrtKstRksGID                     integer,
    tmprksInvoer                        nchar(28),
    tmprksNaam                          nchar(40),
    tmpVrtKstRksGIDTegen                integer,
    tmprksInvoerTegen                   nchar(28),
    tmprksNaamTegen                     nchar(40),
    tmpVrtKstJPGID                      integer,
    tmpomsJournaalPost                  nchar(40),
    primary key (tmpGid))
  on commit preserve rows;

  declare @VorigVrtGid                          integer;
  declare @AantalTankbeurten                    integer;
  declare @CumulatiefLiters                     double;
  declare @CumulatiefVerbruikteLiters           double;
  declare @CumulatiefVerredenKilometers         integer;
  declare @tmpVorigeKmStand                     integer;
  declare @tmpVerredenKilometers                integer;
  declare @tmpVerbruik                          double;
  declare @tmpGemiddeldVerbruik                 double;
  declare @CumulatiefBrandstofKosten            double;
  declare @tmpVasteKostenPerKM                  double;
  declare @tmpVasteKostenPerDag                 double;
  declare @VasteKostenTotMetKostenDatum         double;
  declare @tmpVariabeleKostenPerKM              double;
  declare @tmpVariabeleKostenTotMetKostenDatum  double;
  declare @tmpPrijsPerLiter                     double;
  declare @tmpAantalDagenInGebruik              integer;

  set @@ErrorTextProcedure = 'rapBerekenVoertuigKosten > @Selectie='+string(@Selectie)+', @BMCode_Van='+string(@BMCode_Van)+', @BMCode_Tot='+string(@BMCode_Tot)+', @BmZoekCode_Van='+string(@BmZoekCode_Van)+', @BmZoekCode_Tot='+string(@BmZoekCode_Tot);
  //call TraceBegin(@@ErrorTextProcedure);

//  if @vksCodes <> '-1' then
//    set @vksCodes = ',' + @vksCodes + ','; //zet er standaard een , voor en achter zodat de where simpeler blijft. Anders moet je ook zoeken op degene aan het begin en het einde
//  end if;

  //Index aanmaken voor snelheid
  create index idx_tmp on tmpVoertuigKostenCalc (tmpVrtGid);

  //Ten eerste de voertuigkosten inlezen (incl activa)
  for @Cursor AS Cursor_tmpVoertuigKostenCalc_InclActiva CURSOR FOR
  select  BmIngebruikDatum          @tmpInGebruikDatum,
          BmLaatsteTenaamstelling   @tmpLaatsteTenaamstelling,
          VrtKilometerIngebruikName @tmpKilometerIngebruikName,
          VrtGid                    @tmpVrtGid,
          BmActkGid                 @tmpBmActkGid
  from tabBedrijfsmiddel
  inner join tabVoertuig on BMGid = VrtBmGid
  where (@Selectie = 0 and BmCode between @BMCode_Van and @BMCode_Tot) or
        (@Selectie = 1 and BmZoekCode between @BmZoekCode_Van and @BmZoekCode_Tot)
  order by BmCode, BmZoekCode
  for read only
  do
    insert into tmpVoertuigKostenCalc(tmpVrtKstBedrag, tmpVrtKstBtwCode, tmpVrtKstDatum,  tmpVrtKstIsIncBTW,
                                      tmpVrtKstKilometerstand, tmpVrtKstLiters, tmpVrtKstOmschrijving, tmpVrtKstVksGid,
                                      tmpVrtKstTijdvakBegin, tmpVrtKstTijdvakEind, tmpVrtKstAantalDagen, tmpInGebruikDatum, tmpLaatsteTenaamstelling, tmpKilometerIngebruikName,
                                      tmpBTWPerc, tmpVrtGid, tmpVrtKstGid, tmpVksSoort,
                                      tmpAantalDagenInGebruik,tmpAantalMaandenInGebruik,tmpVrtKstBoekingMaken, tmpVrtKstBoekDatum, tmpVrtKstRksGID, tmprksInvoer, tmprksNaam,
                                      tmpVrtKstRksGIDTegen, tmprksInvoerTegen, tmprksNaamTegen, tmpVrtKstJPGID, tmpomsJournaalPost)
    select
      if @IsInclBTW = 1 then VrtKstBedragIncl else VrtKstBedragExcl endif,
      VrtKstBtwCode,
      VrtKstDatum,
      VrtKstIsIncBTW,
      VrtKstKilometerstand,
      VrtKstLiters,
      VrtKstOmschrijving,
      VrtKstVksGid,
      VrtKstTijdvakBegin,
      VrtKstTijdvakEind,
      isNull(AantalDagen,0),
      @tmpInGebruikDatum,
      @tmpLaatsteTenaamstelling,
      @tmpKilometerIngebruikName,
      (select BTWPercentage from TabBTW where btwcode = VrtKstBtwCode),
       @tmpVrtGid,
       VrtKstGid,
       VksSoort,
       if days360(@tmpLaatsteTenaamstelling,VrtKstDatum) > 0 then days360(@tmpLaatsteTenaamstelling,VrtKstDatum) else 1 endif,
       (DATEDIFF(month, @tmpLaatsteTenaamstelling,VrtKstDatum) + 1),
       VrtKstBoekingMaken,
       VrtKstBoekDatum,
       VrtKstRksGID,
       Invoer.rksInvoer,
       Invoer.rksNaam,
       VrtKstRksGIDTegen,
       InvoerTegen.rksInvoer,
       InvoerTegen.rksNaam,
       VrtKstJPGID,
       omsJournaalPost
    from VoertuigKostenInclActiva(@tmpVrtGid,@tmpBmActkGid)
    left outer join tabVoertuigKostensoort on vksGid = VrtKstVksGid
    left outer join tabVoertuigRekeningen on VrtRekVksGid = vksGid and VrtRekVrtGid = @tmpVrtGid
    left outer join tabRekeningSchema Invoer on Invoer.rksGid = VrtKstRksGID
    left outer join tabRekeningSchema InvoerTegen on InvoerTegen.rksGid = VrtKstRksGIDTegen
    left outer join tabJournaalPost on JpGid = VrtKstJPGID
    //where ((@vksCodes = '-1') or (@vksCodes like '%,' +string(vksGid)+',%'))
    //where ((@vksCodes = '-1') or (@vksCodes like '%,' +string(vksGid)+',%') or (@vksCodes like string(vksGid)+',%') or (@vksCodes like '%,' + string(vksGid)) or (@vksCodes = string(vksGid)))
    where (isNull(VrtRekVksInGebruik,1) = 1 and isNull(VrtRekVksTonen,1) = 1) //Is hij in gebruik EN moet hij getoont worden, dan meenemen
    order by VrtKstDatum, VrtKstKilometerstand, VrtKstGid;
  end for;

  set @VorigVrtGid = 0;

  //Voertuigkosten vullen
  for @Cursor AS Cursor_tmpVoertuigKostenCalc CURSOR FOR
  select
    tmpGid                    @tmpGid,
    tmpVrtGid                 @tmpVrtGid,
    tmpVrtKstVksGid           @tmpVrtKstVksGid,
    tmpKilometerIngebruikName @tmpKilometerIngebruikName,
    tmpVrtKstKilometerstand   @tmpVrtKstKilometerstand,
    tmpVrtKstIsIncBTW         @tmpVrtKstIsIncBTW,
    tmpVrtKstBedrag           @tmpVrtKstBedrag,
    tmpBTWPerc                @tmpBTWPerc,
    tmpVrtKstLiters           @tmpVrtKstLiters,
    tmpVrtKstDatum            @tmpVrtKstDatum,
    tmpInGebruikDatum         @tmpInGebruikDatum,
    tmpLaatsteTenaamstelling  @tmpLaatsteTenaamstelling,
    tmpVrtKstTijdvakBegin     @tmpVrtKstTijdvakBegin,
    tmpVrtKstTijdvakEind      @tmpVrtKstTijdvakEind,
    tmpVksSoort               @tmpVksSoort
  from
    tmpVoertuigKostenCalc
  order by
    tmpVrtGid, tmpVrtKstDatum, tmpVrtKstKilometerstand
  for read only
  do
    if @tmpVrtGid <> @VorigVrtGid then
      //Variabelen per voertuig resetten
      set @AantalTankbeurten                    = 0;
      set @CumulatiefVerredenKilometers         = 0;
      set @CumulatiefLiters                     = 0;
      set @CumulatiefVerbruikteLiters           = 0;
      set @tmpVerredenKilometers                = 0;
      set @tmpVorigeKmStand                     = @tmpKilometerIngebruikName;
      set @CumulatiefBrandstofKosten            = 0;
      set @VasteKostenTotMetKostenDatum         = 0;
      set @tmpVasteKostenPerKM                  = 0;
      set @tmpVasteKostenPerDag                 = 0;
      set @tmpVariabeleKostenPerKM              = 0;
      set @tmpVariabeleKostenTotMetKostenDatum  = 0;
    end if;

//    set @tmpVrtKstBedragIncl      = @tmpVrtKstBedragExcl;
//    set @tmpAantalDagenInGebruik  = days360(@tmpLaatsteTenaamstelling,@tmpVrtKstTijdvakBegin);
    set @tmpPrijsPerLiter         = 0;
    set @tmpVerbruik              = 0;
//    set @tmpGemiddeldVerbruik     = 0;

    //Nettobedrag
//    if (isNull(@tmpVrtKstIsIncBTW,0) <> 0 ) then
//      set @tmpVrtKstBedragIncl = @tmpVrtKstBedragExcl / (100+ (@tmpBTWPerc) ) * 100;
//    end if;

    //Aantal maanden en dagen in gebruik
//    if (@tmpAantalDagenInGebruik <= 0) then
//      set @tmpAantalDagenInGebruik = 1;
//    end if;

    //Deze alvast updaten voor Variabele en vaste  kosten
//    update tmpVoertuigKostenCalc set tmpVrtKstBedragIncl = @tmpVrtKstBedragIncl where tmpGid = @tmpGid;

    //Vaste kosten
    select
     sum((tmpVrtKstBedrag / isNull(if tmpVrtKstAantalDagen > 0 then tmpVrtKstAantalDagen else 1 endif,1))
      * (if (@tmpVrtKstDatum between tmpVrtKstTijdvakBegin and tmpVrtKstTijdvakEind) then
              if (tmpVrtKstTijdvakBegin = @tmpVrtKstDatum) then 1 else days360(tmpVrtKstTijdvakBegin,@tmpVrtKstDatum) endif
         else days360(tmpVrtKstTijdvakBegin,tmpVrtKstTijdvakEind) endif)),
     sum(if (@tmpVrtKstDatum between tmpVrtKstTijdvakBegin and tmpVrtKstTijdvakEind) then
          (tmpVrtKstBedrag / isNull(if tmpVrtKstAantalDagen > 0 then tmpVrtKstAantalDagen else 1 endif,1))
         else 0 endif)
     into @VasteKostenTotMetKostenDatum,@tmpVasteKostenPerDag
    from tmpVoertuigKostenCalc
    where (tmpVrtGid = @tmpVrtGid)
    and  (tmpVrtKstTijdvakBegin <= IsNull(@tmpVrtKstTijdvakBegin,@tmpVrtKstDatum))
    and tmpVksSoort in (1,4);

      //Vaste kosten per kilometer
    if (@tmpVrtKstKilometerstand - @tmpKilometerIngebruikName > 0) then
      set @tmpVasteKostenPerKM = @VasteKostenTotMetKostenDatum / isnull((@tmpVrtKstKilometerstand - @tmpKilometerIngebruikName),1);
    end if;

    //Variabele kosten
    if @tmpVksSoort in (2) then
      select sum(tmpVrtKstBedrag) into @tmpVariabeleKostenTotMetKostenDatum
      from tmpVoertuigKostenCalc
      where (tmpVrtGid = @tmpVrtGid)
      and  (tmpVrtKstDatum <= @tmpVrtKstDatum)
      and (tmpVksSoort in (2,3));

      set @tmpVariabeleKostenPerKM = @tmpVariabeleKostenTotMetKostenDatum  /
                                  isNull((if (@tmpVrtKstKilometerstand - @tmpKilometerIngebruikName > 0) then (@tmpVrtKstKilometerstand - @tmpKilometerIngebruikName) endif),1);
    end if;

    //Prijs per liter
    if (@tmpVrtKstLiters > 0) then
      set @tmpPrijsPerLiter =  (@tmpVrtKstBedrag / @tmpVrtKstLiters);
    end if;

    //Verreden kilometers
    set @tmpVerredenKilometers = (@tmpVrtKstKilometerstand - @tmpVorigeKmStand);
    if @tmpVerredenKilometers < 0 then
      set @tmpVerredenKilometers = 0;
    end if;

    if  ((@VanDatum is null) or (@tmpVrtKstDatum >= @VanDatum) or (@tmpVrtKstTijdvakBegin >= @VanDatum) or (@tmpVrtKstTijdvakEind >= @VanDatum))
    and ((@TmDatum is null) or (@tmpVrtKstDatum <= @TmDatum) or (@tmpVrtKstTijdvakBegin <= @TmDatum) or (@tmpVrtKstTijdvakEind <= @TmDatum)) then
      //Cumulatiefulatieve aantal tankbeurten en liters
      if (@tmpVksSoort=2) then
        set @AantalTankbeurten = @AantalTankbeurten + 1;
        set @CumulatiefBrandstofKosten = @CumulatiefBrandstofKosten + @tmpVrtKstBedrag;
        set @CumulatiefLiters = @CumulatiefLiters + isNull(@tmpVrtKstLiters,0);
        set @CumulatiefVerredenKilometers = @CumulatiefVerredenKilometers + @tmpVerredenKilometers;
      end if;
    end if;

    if (@tmpVrtKstLiters > 0) then
      set @tmpVerbruik = (@tmpVerredenKilometers / @tmpVrtKstLiters)
    end if;

    //Gemiddeld verbruik
    if (@tmpVksSoort=2) then
      set @CumulatiefVerbruikteLiters = @CumulatiefVerbruikteLiters + isNull(@tmpVrtKstLiters,0);
    end if;

    if (@CumulatiefVerbruikteLiters > 0) and (@tmpVksSoort=2) then
      set @tmpGemiddeldVerbruik = (@tmpVrtKstKilometerstand-@tmpKilometerIngebruikName) / @CumulatiefVerbruikteLiters;
    end if;

    update tmpVoertuigKostenCalc
    set tmpCumulatiefTankbeurten            = @AantalTankbeurten,
        tmpCumulatiefLiters                 = @CumulatiefLiters,
        tmpCumulatiefVerredenKilometers     = @CumulatiefVerredenKilometers,
        tmpVorigeKmStand                    = @tmpVorigeKmStand,
        tmpVerbruik                         = @tmpVerbruik,
        tmpVerredenKilometers               = @tmpVerredenKilometers,
        tmpGemiddeldVerbruik                = @tmpGemiddeldVerbruik,
        tmpCumulatiefBrandstofKosten        = @CumulatiefBrandstofKosten,
        tmpVasteKostenTotMetKostenDatum     = @VasteKostenTotMetKostenDatum,
        tmpVasteKostenPerKM                 = @tmpVasteKostenPerKM,
        tmpVasteKostenPerDag                = @tmpVasteKostenPerDag,
        tmpVariabeleKostenPerKM             = @tmpVariabeleKostenPerKM,
        tmpVariabeleKostenTotMetKostenDatum = @tmpVariabeleKostenTotMetKostenDatum,
        tmpPrijsPerLiter                    = @tmpPrijsPerLiter
    where tmpGid = @tmpGid;

    if (@tmpVksSoort=2) then
      set @tmpVorigeKmStand = @tmpVrtKstKilometerstand;
    end if;

    set @VorigVrtGid = @tmpVrtGid;
  end for;

  select  tmpVrtGid, tmpVrtKstVksGid, tmpVksSoort, VksCode, tmpVrtKstOmschrijving,
          tmpKilometerIngebruikName, tmpVorigeKmStand, tmpVrtKstKilometerstand, tmpVerredenKilometers,
          tmpVrtKstDatum,
          tmpVrtKstTijdvakBegin, tmpVrtKstTijdvakEind, tmpVrtKstAantalDagen, tmpAantalMaandenInGebruik, tmpAantalDagenInGebruik,
          tmpCumulatiefVerredenKilometers,
          tmpCumulatiefTankbeurten,
          tmpCumulatiefLiters,
          tmpCumulatiefBrandstofKosten,
          tmpVrtKstIsIncBTW, tmpVrtKstBtwCode, tmpBTWPerc,
          tmpVrtKstBedrag, tmpVasteKostenPerDag, tmpVasteKostenPerKM, tmpVasteKostenTotMetKostenDatum,
          tmpVariabeleKostenPerKM, tmpVariabeleKostenTotMetKostenDatum,
          tmpVrtKstLiters, tmpPrijsPerLiter,tmpVerbruik, tmpGemiddeldVerbruik, tmpIsVerbruikAfwijkend,
          tmpVrtKstBoekingMaken, tmpVrtKstBoekDatum, tmpVrtKstRksGID, tmprksInvoer, tmprksNaam,
          tmpVrtKstRksGIDTegen, tmprksInvoerTegen, tmprksNaamTegen, tmpVrtKstJPGID, tmpomsJournaalPost
  from tmpVoertuigKostenCalc
  left outer join tabVoertuigKostensoort on vksGid = tmpVrtKstVksGid
  where ((@VanDatum is null) or
         (tmpVrtKstDatum >= @VanDatum and tmpVrtKstTijdvakBegin is null and tmpVrtKstTijdvakEind is null) or
         ((tmpVrtKstTijdvakBegin >= @VanDatum) or (tmpVrtKstTijdvakEind >= @VanDatum)))
  and   ((@TmDatum is null) or
         (tmpVrtKstTijdvakBegin is null and tmpVrtKstTijdvakEind is null and tmpVrtKstDatum <= @TmDatum) or
         ((tmpVrtKstTijdvakBegin <= @TmDatum) or (tmpVrtKstTijdvakEind <= @TmDatum)))
  order by  tmpVrtGid, tmpVrtKstDatum, tmpVrtKstKilometerstand;

  set @@ErrorTextProcedure = 'rapBerekenVoertuigKosten';
  //call TraceEind(@@ErrorTextProcedure);
end;
//call rapBerekenVoertuigKosten(0, '53-RH-XT', '53-RH-XT', '00000000', 'ZZZZZZZZ',0,'2010-01-01','2015-12-31');
//call rapBerekenVoertuigKosten(0, '53-RH-XT', '53-RH-XT', '00000000', 'ZZZZZZZZ',0,'2010-01-01','2015-12-31','49,47,7,46,27,45,8,9')


create or replace procedure rapBetAnalyseDebNaw(
  in @SorteerOp         integer,  //0=debnr, 1=zoekcode, 2=gem betoverschr betaalde. facturen, 3=gem bet.termijn betaalde. facturen, 4=perc. betaalde. fact. te laat betaald
  in @IsAscending       smallint, //0=descending, 1 ascending
  in @AfdrValDebTotalen smallint  //0=valuta van debiteur, 1=basisvaluta
  )

result(//naw nummer en zoekcode
       DebNummer nchar(10), DebZoekCode nchar(10),

       //gegevens naw vestigingsadres
       VestAdrNaam1 nchar(40), VestAdrNaam2 nchar(40),
       VestAdrStraat nchar(40), VestAdrHuisnummer nchar(10), VestAdrStraatEnHuisnr nchar(50),
       VestAdrPostcode nchar(40), VestAdrPlaats nchar(40),
       VestAdrLandNaam nchar(40), VestAdrLandCode nchar(3), VestAdrLandPostCode smallint, VestAdrLandHuisnr smallint, VastAdrLndInNAWBlok smallint,
       VestAdrEmail nchar(80), VestAdrTelefoon nchar(25), VestAdrTelefoon2 nchar(25), VestAdrFax nchar(25),

       //gegevens contactpersoon naw
       ContactpersoonNummer integer, ContactpersoonNaam nchar(40), ContactpersTelefoon nchar(25), ContactpersTelefoon2 nchar(25),  ContactpersFax nchar(25), ContactpersoonEmail nchar(80),
       TelContactpersOfVestAdres nchar(25), Tel2ContactpersOfVestAdres nchar(25), FaxContactpersOfVestAdres nchar(25),
       EmailContactpersOfVestAdres nchar(80),

       //gegevens betalingscondties naw
       BetalingsConditieCode integer,                 // btcNummer
       BetalingsConditieOms nchar(40),                 // btcOms
       BetalingsConditieAantDagenOfMaanden integer,   // AantalDgnMnd
       BetalingsConditieDagOfMaand smallint,          // DagenMaanden

       //credietlimiet en valuta
       KredietLimiet numeric (15,2),
       ValutaCodeDeb nchar(3),
       ValutaNummerDeb integer,
       AfdrukValutaCodeDebTotalen nchar(3), //van debiteur of basisvaluta,
       AfdrukValutaNrDebTotalen integer,

       //overig
       RksGid integer,

       //voor sortering: gemiddelde overschrijdingstermijn, Betalingstermijn en percentage betaalde facturen dat te laat is betaald
       GemBetalingsOverschr numeric(15,2),
       GemBetalingsTermijn numeric(15,2),
       PercentageBetaaldeFacturenTeLaatBetaald numeric(15,2),
       VertegenwoordigersCode integer,
       VertegenwoordigersNaam nchar(40),
       VertAchternaamSort     nchar(40)
)

begin
  //call traceBegin('rapBetAnalyseDebNaw');

  select
  NawFilNummer as DebNummer, NawFilZoekCode as DebZoekCode,
  //vestigings adres
  AdrNaam1 as VestAdrNaam1, AdrNaam2 as VestAdrNaam2,
  AdrStraat as VestAdrStraat, AdrHuisnummer as VestAdrHuisnummer, (AdrStraat + ' ' +AdrHuisnummer) as VestAdrStraatEnHuisnr,
  AdrPostcode as VestAdrPostcode, AdrPlaats as VestAdrPlaats,
  LndOms as VestAdrLandNaam, lndEigenCode as VestAdrLandCode, lndPlaatsPostcode as VestAdrLandPostCode,  lndPlaatsHuisnr as VestAdrLandHuisnr, LndInNAWBlok as VastAdrLndInNAWBlok,
  AdrEmail as VestAdrEmail, AdrTelefoon as VestAdrTelefoon, AdrTelefoon2 as VestAdrTelefoon2, AdrTelefax as VestAdrFax,
  //contactpersoon
  RelNummer as ContactpersoonNummer,

  if IsBelangrijkste is not null then  //volledige naam contactpersoon
    RelVolledigeNaam
  endif as ContactpersoonNaam,

  RelTelefoon as ContactpersTelefoon,
  RelTelefoon2 as ContactpersTelefoon2,
  RelTelefax as ContactpersFax,
  RelEmail as ContactpersoonEmail,

  // TelContactpersOfVestAdres -> als nummer van contactpersoon leeg is, van het vestigingsadres
  if IsBelangrijkste is null or isnull(RelTelefoon,'')='' then
    AdrTelefoon
  else
    RelTelefoon
  endif as TelContactpersOfVestAdres,

  if IsBelangrijkste is null or isnull(RelTelefoon2,'')='' then
    AdrTelefoon2
  else
    RelTelefoon2
  endif as Tel2ContactpersOfVestAdres,

  if IsBelangrijkste is null or isnull(RelTelefax,'')='' then
    AdrTelefax
  else
    RelTelefax
  endif as FaxContactpersOfVestAdres,


  if IsBelangrijkste is null or isnull(RelEmail,'')='' then
    AdrEmail
  else
    RelEmail
  endif as EmailContactpersOfVestAdres,

  BtcNummer    as BetalingsConditieCode,
  BtcOms       as BetalingsConditieOms,
  AantalDgnMnd as BetalingsConditieAantDagenOfMaanden,
  DagenMaanden as BetalingsConditieDagOfMaand,

  NawFilKredLimiet as KredietLimiet,

  (select ValCode from tabValuta where ValNummer = nawfilValNummer) as ValutaCodeDeb,

  nawfilValNummer as ValutaNummerDeb,

  // AfdrukValuta (van debiteur of basisvaluta)
  case @AfdrValDebTotalen
    when 0 then ValutaCodeDeb     //0 = van debiteur
    when 1 then @@BasisValutaCode //1 = basisvaluta
  end as AfdrukValutaCode,

  case @AfdrValDebTotalen
    when 0 then ValutaNummerDeb     //0 = van debiteur
    when 1 then @@BasisValutaNummer //1 = basisvaluta
  end as AfdrukValutaNr,


  RksGid,

  // GemBetalingsOverschr, GemBetalingsTermijn en PercentageBetaaldeFacturenTeLaatBetaald hier ook nodig voor sorteren op..
  //gemiddelde betalingsoverschrijding van de openstaandeposten van deze debiteur
  avg(if not(tmpOspBetalingstermijn is null) and
            (tmpOspIsGesloten   = 1) then
        tmpOspBetalingsOverschr
      endif) as GemBetalingsOverschr,


  //gemiddelde Betalingstermijn/betalingstermijn van de gesloten osps vandeze debiteur
  avg(if not(tmpOspBetalingstermijn is null) and
            (tmpOspIsGesloten   = 1) then
        tmpOspBetalingstermijn
      endif) as GemBetalingsTermijn,

   //Percentage betaalde facturen die te laat betaald zijn.
   //Hierin worden ook posten meegenomen die niet gesloten zijn, maar wel volledig (dus te veel) betaald.
   //Néé, toch maar weer niet: alléén over echt gesloten posten berekenen. IsGesloten = 1. Zucht. 16-1-03
  (IF ((select count(*)                                              //aantal te laat, maar volledig betaalde osp''s deze debiteur
        from tmpDebAnalyseOsps                                       //->  mag geen 0 zijn
        where (tmpOspRksGid = RksGid)
          and (tmpOspIsGesloten   = 1)
          and (tmpOspDatumLaatstePosCredBetaling > tmpOspVervaldatum)
       ) > 0  AND
       (select count(*)                                               //het aantal gesloten osp''s deze debiteur
        from tmpDebAnalyseOsps                                        //-> mag geen 0 zijn
        where (tmpOspRksGid = RksGid)
          and (tmpOspIsGesloten   = 1)
       ) > 0
      ) THEN

     (((select count(*)                                               //aantal te laat, maar volledig betaalde osp''s deze debiteur
        from tmpDebAnalyseOsps
        where (tmpOspRksGid = RksGid)
          and (tmpOspIsGesloten   = 1)
          and (tmpOspDatumLaatstePosCredBetaling > tmpOspVervaldatum)
       ) /                                                            //gedeeld door
       (select count(*)                                               //het aantal gesloten osp''s deze debiteur
        from tmpDebAnalyseOsps
        where (tmpOspRksGid = RksGid)
          and (tmpOspIsGesloten   = 1)
       )
      ) * 100
     )
   else
     0
   endif) as PercentageBetaaldeFacturenTeLaatBetaald,


   nawVertegenwCode as VertegenwoordigersCode,

//  (select (if relvoornaam = '' then relachternaam else (relachternaam + ', ' + relvoornaam) endif)
//   from tabRelatie
//   inner join tabNaw on (nawgid = relnawgid)
//   where relnawgid = (select NawFilNawGid
//                      from tabnawfile
//                      where NawFilFonId = 'B')
//   and RelVtgCode = VertegenwoordigersCode) as VertegenwoordigersNaam

   (select relVolledigeNaam
    from  tabRelatie
    inner join tabVertegenwoordiger on VtgRelGid = RelGid
    where RelVtgCode = VertegenwoordigersCode) as VertegenwoordigersNaam,

   (select RelAchternaam
    from  tabRelatie
    inner join tabVertegenwoordiger on VtgRelGid = RelGid
    where RelVtgCode = VertegenwoordigersCode) as VertAchternaamSort




  from tabNaw
       inner join (tabNawFile left outer join tabBetalingsConditie on nawfilBtcNummer = BtcNummer) on (NawGid = NawFilNawGid)
       left outer join (tabAdres as V inner join tabLand as VL on ( VL.lndGid = V.adrLndGid )) on ( NawGidVestiging = V.adrGid)  //vestigings adres, komt uit rapStamGeg
       inner join tabRekeningSchema on (nawfilRksGID = RksGid)
       inner join tabValuta on (ValNummer = nawfilValNummer )
       left outer join (tabRelatie
                        inner join tabRelatieFunctie on ((RelFnCode = (select SchermFnCode from tabScherm where SchermSoort = 10)) and IsBelangrijkste = 1))
                        on (RelNawGid = NawGid and RelGid = FnRelGid)
       // alleen de debiteuren van de osp''s uit de geselecteerde osp''s
       inner join tmpDebAnalyseOsps on (nawfilRksGID = tmpDebAnalyseOsps.tmpOspRksGid)

  group by
    NawFilNummer, NawFilZoekCode, NawfilValNummer, VertegenwoordigersCode, VertegenwoordigersNaam,
    AdrOms, AdrNaam1, AdrNaam2, AdrStraat, AdrHuisnummer, AdrPostcode, AdrPlaats,
    AdrTelefoon, AdrTelefoon2, AdrTelefax, AdrEmail,
    LndEigenCode, LndOms, LndInNAWBlok, LndPlaatsHuisnr, lndPlaatsPostcode,
    RksGid, RksInvoer, RksZoekcode, ValNummer, Valcode,
    RelTelefoon, RelTelefoon2, RelEmail, RelVolledigeNaam, IsBelangrijkste, NawFilKredLimiet,
    BtcNummer, BtcOms, GeldigAantal, DagenMaanden, AantalDgnMnd, RelNummer, RelTelefax

  order by
    if @SorteerOp = 1 and @IsAscending=1 then NawFilZoekcode endif asc,
    if @SorteerOp = 1 and @IsAscending=0 then NawFilZoekcode endif desc,
    if @SorteerOp = 2 and @IsAscending=1 then GemBetalingsOverschr endif asc,
    if @SorteerOp = 2 and @IsAscending=0 then GemBetalingsOverschr endif desc,
    if @SorteerOp = 3 and @IsAscending=1 then GemBetalingsTermijn endif asc,
    if @SorteerOp = 3 and @IsAscending=0 then GemBetalingsTermijn endif desc,
    if @SorteerOp = 4 and @IsAscending=1 then PercentageBetaaldeFacturenTeLaatBetaald endif asc,
    if @SorteerOp = 4 and @IsAscending=0 then PercentageBetaaldeFacturenTeLaatBetaald endif desc,
    if @SorteerOp = 5 and @IsAscending=0 then VertegenwoordigersCode endif desc,
    if @SorteerOp = 5 and @IsAscending=1 then VertegenwoordigersCode endif asc,
    if @SorteerOp = 6 and @IsAscending=0 then VertAchternaamSort endif desc,
    if @SorteerOp = 6 and @IsAscending=1 then VertAchternaamSort endif asc,

    //de eerste als laatste, zodat hij daar altijd (ook) op zal sorteren
    if @IsAscending=1 then NawFilNummer endif asc,
    if @IsAscending=0 then NawFilNummer endif desc
  ;

  //call TraceEind('rapBetAnalyseDebNaw');

end;


create or replace procedure rapBetAnalyseDebOsp(
  in @RksGid       integer,
  in @SorteerOp    smallint, //0=factuur/ref.nr, 1=factuurdatum, 2=vervaldatum, 3=factbedrag, 4=openst.bedrag, 5=valutacode
  in @IsAscending  smallint,  //0=descending, 1=ascending
  in @Peildatum    date
  )

result(OspGid integer, FactuurNummer nchar(40), OmsFactuur nchar(40), ValCodeFactuur nchar(3), ValNummerFactuur integer,
       FactuurDatum date, VervalDatumFactuur date, Geblokkeerd smallint,
       ValNrAfdrFactuur integer, ValCodeAfdrFactuur nchar(3), //valuta waarin de osp''s moeten worden afgedrukt
       DatumLaatstePosCredBetaling date,

       BetOverschrOpenstaandeFacturenInDagen numeric(15,2), BetOverschrBetaaldeFacturenInDagen numeric(15,2), BetOverschrTotaal numeric(15,2),
       BetalingstermijnOpenstaandeFacturenInDagen numeric(15,2), BetalingstermijnBetaaldeFacturenInDagen numeric(15,2), BetalingstermijnTotaal numeric(15,2),
       ToegestaneBetalingstermijnInDagen numeric(15,2),
       RenteverliesBetaaldeFacturenInBasisValuta numeric(15,2), RenteverliesOpenstaandeFacturenInBasisValuta numeric(15,2), RenteverliesTotaalInBasisValuta  numeric(15,2),

       FactuurBedragInAfdrukValuta numeric(15,2), BetaaldBedragInAfdrukValuta numeric(15,2), OpenstaandBedragInAfdrukValuta numeric(15,2),
       GeblokkeerdBedragInAfdrukValuta numeric(15,2), DirectTeVoldoenInAfdrukValuta numeric(15,2)
       ,Gesloten integer, Vervallen integer
)

begin
  set @@ErrorTextProcedure = 'rapBetAnalyseDebOsp > ';
  //call TraceBegin(@@ErrorTextProcedure + '@RksGid = ' + string(@RksGid));
  //call TraceEind(@@ErrorTextProcedure);

  select
    tmpOspGidje, tmpOspFactuurnummer, tmpOspOms, tmpOspValCode, tmpOspValNummer,
    tmpOspFactuurdatum, tmpOspVervaldatum, tmpOspIsGeblokkeerd,
    tmpOspValNrAfdrFact, tmpOspValCodeAfdrFact,
    tmpOspDatumLaatstePosCredBetaling,

    //zo krijg je een null op je scherm wanneer je waarden van gesloten posten toont en hij open is etc.
    //betalingsoverschrijding
    (if (tmpOspIsGesloten = 0) then
       tmpOspBetalingsOverschr
     endif) as BetOverschrOpenstaandeFacturenInDagen,

    (if (tmpOspIsGesloten = 1) then
       tmpOspBetalingsOverschr
     endif) as BetOverschrBetaaldeFacturenInDagen,

    (tmpOspBetalingsOverschr) as BetOverschrTotaal,

    //betalingstermijn / Betalingstermijn
    (if (tmpOspIsGesloten = 0) then
       tmpOspBetalingstermijn
     endif) as BetalingstermijnOpenstaandeFacturenInDagen,

    (if (tmpOspIsGesloten = 1) then
       tmpOspBetalingstermijn
     endif) as BetalingstermijnBetaaldeFacturenInDagen,

    (tmpOspBetalingstermijn) as BetalingstermijnTotaal,

    (tmpOspToegestaneBetalingstermijn) as ToegestaneBetalingstermijnInDagen,

    //renteverlies
    (if (tmpOspIsGesloten = 1) then
       //IsNull(tmpOspRenteverliesInAfdrValutaFact,0)
       IsNull(tmpOspRenteverliesInBasisvaluta,0)
     else
       0
     endif) as RenteverliesBetaaldeFacturenInBasisValuta,

    (if (tmpOspIsGesloten = 0) then
       //IsNull(tmpOspRenteverliesInAfdrValutaFact,0)
       IsNull(tmpOspRenteverliesInBasisvaluta,0)
     else
       0
     endif) as RenteverliesOpenstaandeFacturenInBasisValuta,

    //(tmpOspRenteverliesInAfdrValutaFact) as RenteverliesTotaalInBasisValuta,
    (tmpOspRenteverliesInBasisvaluta) as RenteverliesTotaalInBasisValuta,

    //alles in afdruk valuta
    tmpOspFactuurbedragInAfdrValFact, tmpOspBetaaldBedragInAfdrValFact, tmpOpenstaandBedragInAfdrValFact,
    tmpOspGeblokkeerdBedragInAfdrValFact, tmpOspDirectTeVoldoenInAfdrValFact

    //deze twee heb ik er even extra bijgedaan
    ,tmpOspIsGesloten,
    (if (tmpOspVervalDatum < @Peildatum) then
       1
     else
       0
     endif) as Vervallen

  from tmpDebAnalyseOsps

  where
   (tmpOspRksgid = @RksGid)

  order by
   if @SorteerOp = 1 and @IsAscending=1 then tmpOspFactuurdatum endif asc,
   if @SorteerOp = 1 and @IsAscending=0 then tmpOspFactuurdatum endif desc,
   if @SorteerOp = 2 and @IsAscending=1 then BetOverschrBetaaldeFacturenInDagen    endif asc,   //eerst de betaalde, dan de open posten
   if @SorteerOp = 2 and @IsAscending=1 then BetOverschrOpenstaandeFacturenInDagen endif asc,
   if @SorteerOp = 2 and @IsAscending=0 then BetOverschrBetaaldeFacturenInDagen    endif desc,
   if @SorteerOp = 2 and @IsAscending=0 then BetOverschrOpenstaandeFacturenInDagen endif desc,

   if @SorteerOp = 3 and @IsAscending=1 then BetalingstermijnBetaaldeFacturenInDagen    endif asc,        //eerst de betaalde, dan de open posten
   if @SorteerOp = 3 and @IsAscending=1 then BetalingstermijnOpenstaandeFacturenInDagen endif asc,
   if @SorteerOp = 3 and @IsAscending=0 then BetalingstermijnBetaaldeFacturenInDagen    endif desc,
   if @SorteerOp = 3 and @IsAscending=0 then BetalingstermijnOpenstaandeFacturenInDagen endif desc,

   //de eerste als laatste, zodat hij daar altijd (ook) op zal sorteren
   if @IsAscending=1 then tmpOspFactuurnummer endif asc,
   if @IsAscending=0 then tmpOspFactuurnummer endif desc;
end;


//Aanmaken tijdelijke tabel met Osp''s die getoond moeten worden.
//Op basis van deze tabel worden osp''s geselecteerd in andere stored procs
//op basis waarvan de berekening van de totalen voor de debiteuren analyse gedaan wordt

create or replace procedure rapBetAnalyseDebTmpTabVullen(
  in @Selectie                   smallint,
  in @VanDebNr                   nchar(40),
  in @TotDebNr                   nchar(40),

  in @VanDebZoekcode             nchar(40),
  in @TotDebZoekcode             nchar(40),
  in @VanVertCode                integer,
  in @TotVertCode                integer,
  in @VanVertNaam                nchar(40),
  in @TotVertNaam                nchar(40),

  in @VanFactuurDatum            date,
  in @TotFactuurDatum            date,

  in @AfdrNogOpenstaandePosten   smallint,
  in @AfdrGeblokkeerdePosten     smallint,
  in @AfdrNietVervallenPosten    smallint,
  in @DefOfVoorlopig             smallint,
  in @Peildatum                  date,
  in @RentePercentage            numeric(15,2),

  in @AfdrValutaDebOfBasisFact   smallint, //valuta van osp''s: 0=van factuur, 1=van debiteur, 2=basisvaluta
  in @AfdrValutaDebOfBasisDebTot smallint  //valuta van debiteurtotalen: 0=van debiteur, 1=basisvaluta

)


begin
  declare @HulpBjGid integer;
  declare @HulpPerNr integer;

//  call traceBegin('rapBetAnalyseDebTmpTabVullen');

  //tbv. omrekenen van valuta-omrekening
  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @HulpBjGid, @HulpPerNr);

  delete tmpDebAnalyseOsps;

  //NB 20-5-03: een post is gesloten als OP DE PEILDATUM Factuurbedrag - Betaaldbedrag = 0.
  //Oftwel: een sum op de factuurboekingen en betalingsboekingen op de peildatum... Zucht.
  insert into tmpDebAnalyseOsps(tmpOspGidje, tmpOspRksGid, tmpOspFactuurnummer, tmpOspOms, tmpOspValCode, tmpOspValNummer,
                                tmpOspFactuurdatum, tmpOspVervaldatum,  tmpOspIsGeblokkeerd,
                                tmpOspValNrAfdrFact, tmpOspValCodeAfdrFact, tmpOspValNrAfdrDebTot,
                                tmpOspFactuurbedrag, tmpOspBetaaldBedrag, tmpOpenstaandBedrag, tmpOspGeblokkeerdBedrag,
                                tmpOspIsGesloten,
                                tmpOspDatumLaatstePosCredBetaling,
                                tmpOspBetalingsOverschr, tmpOspBetalingstermijn, tmpOspToegestaneBetalingstermijn, tmpOspRenteverlies,

                                //alles in afdruk valuta factuur
                                tmpOspFactuurbedragInAfdrValFact, tmpOspBetaaldBedragInAfdrValFact, tmpOpenstaandBedragInAfdrValFact, tmpOspGeblokkeerdBedragInAfdrValFact,
                                tmpOspDirectTeVoldoenInAfdrValFact, tmpOspRenteverliesInBasisvaluta, //tmpOspRenteverliesInAfdrValutaFact,

                                //alles in afdruk valuta debiteur
                                tmpOspFactuurbedragInAfdrValDeb, tmpOspBetaaldBedragInAfdrValDeb, tmpOpenstaandBedragInAfdrValDeb, tmpOspGeblokkeerdBedragInAfdrValDeb,
                                tmpOspDirectTeVoldoenInAfdrValDeb, //tmpOspRenteverliesInAfdrValutaDeb,
                                tmpOspVertegenwCode, tmpOspVertegenwNaam
                                )
  select distinct
   //factuurbedrag en betaaldbedrag, aangepast in juiste keuze van voorlopig of defininitieve gegevens
    OspGid,
    OspRksGid,
    OspFactuurnummer,
    OspOms,
    OspValCode,
    OspValNummer,

    OspFactuurdatum,
    OspVervaldatum,
    OspIsGeblokkeerd as IsGeblokkeerd,

    //voor de totaal-berekeningen over alle osps van één debiteur de osp-bedragen omrekenen naar
    //eenzelfde valuta: de valuta waarin de debiteur totalen moeten worden afgedrukt
    //@AfdrValNrFactDebOfBasisFact -> de valuta waarin de debiteur totalen moeten
    //worden afgedrukt, in valuta van debiteur moet zijn of in basisvaluta
    (Case @AfdrValutaDebOfBasisFact
      when 0 then OspValNummer                                                             //valutanr van factuur
      when 1 then nawfilValNummer                                                          //val van debiteur
      when 2 then @@BasisValutaNummer                                                      //basisvalutanr
    end) as ValNrAfdrFact,

    (select valCode
     from tabValuta
     where valNummer = ValNrAfdrFact) as ValCodeAfdrFact,

    (if @AfdrValutaDebOfBasisDebTot = 0 then
      (nawfilValNummer)                                                                    //valutanr van debiteur
    else
      @@BasisValutaNummer                                                                  //basisvalutanr
    endif) as ValNrAfdrDebTot,

//    (case @DefOfVoorlopig
//       when 0 then  IsNull(OspFactuurBedragDefinitief,0)
//       when 1 then  IsNull(OspFactuurBedragVoorlopig ,0)
//       when 2 then (IsNull(OspFactuurBedragDefinitief,0) + IsNull(OspFactuurBedragVoorlopig,0))
//     end) as FactuurBedrag,
//    (case @DefOfVoorlopig
//       when 0 then  IsNull(OspBetaaldBedragDefinitief,0)
//       when 1 then  IsNull(OspBetaaldBedragVoorlopig ,0)
//       when 2 then (IsNull(OspBetaaldBedragDefinitief,0) + IsNull(OspBetaaldBedragVoorlopig,0))
//     end) as BetaaldBedrag,


    // NB tabJournaalRegel.RegelNammer <> '' -> Definitief, '' of null -> voorlopig

    (case @DefOfVoorlopig     //hier een subselect op de deelbetalingen van deze osp t/m de peildatum
       when 0 then  IsNull((select sum(JrValutaBedrag)
                            from tabJournaalregel
                            where (JrOspGid = OspGid)
                              and (IsNull(RegelNummer,'') <> '')                              //alleen definitief
                              and (IsCreditBoeking = 0)                                       //alleen rekeningen
                              and (JrBoekdatum <= @Peildatum)),0)                             //op of voor de peildatum
       when 1 then  IsNull((select sum(JrValutaBedrag)
                            from tabJournaalregel
                            where (JrOspGid = OspGid)
                              and (IsNull(RegelNummer,'') = '')                               //alleen voorlopig
                              and (IsCreditBoeking = 0)
                              and (JrBoekdatum <= @Peildatum)),0)
       when 2 then IsNull((select sum(JrValutaBedrag)
                            from tabJournaalregel
                            where (JrOspGid = OspGid)
                              and (IsCreditBoeking = 0)
                              and (JrBoekdatum <= @Peildatum)),0)                             //definitief en voorlopig
     end) as FactuurBedrag,

    (case @DefOfVoorlopig
       when 0 then IsNull((select sum(JrValutaBedrag)
                           from tabJournaalregel
                           where (JrOspGid = OspGid)
                             and (IsNull(RegelNummer,'') <> '')                               //alleen definitief
                             and (IsCreditBoeking = 1)                                        //alleen betalingen
                             and (JrBoekdatum <= @Peildatum)),0)                              //op of voor de peildatum
       when 1 then IsNull((select sum(JrValutaBedrag)
                           from tabJournaalregel
                           where (JrOspGid = OspGid)
                             and (IsNull(RegelNummer,'') = '')                               //alleen voorlopig
                             and (IsCreditBoeking = 1)
                             and (JrBoekdatum <= @Peildatum)),0)
       when 2 then IsNull((select sum(JrValutaBedrag)
                            from tabJournaalregel
                            where (JrOspGid = OspGid)
                              and (IsCreditBoeking = 1)
                              and (JrBoekdatum <= @Peildatum)),0)                             //voorlopig en definitief
     end) as BetaaldBedrag,


    (FactuurBedrag - BetaaldBedrag) as OpenstaandBedrag,

    //openstaand bedrag, alleen indien factuur geblokkeerd is
    (if IsGeblokkeerd = 1 then
       OpenstaandBedrag
     else
       0
     endif) as GeblokkeerdBedrag,

    (if FactuurBedrag = BetaaldBedrag then   //peildatum zit al in factuur- en betaaldbedrag verwerkt, hoeft hier niet nog eens
       1
     else
       0
     endif) as OspIsGesloten,

    (select max(JournaalLaatsteBetaling.JrBoekdatum)
     from   tabJournaalRegel JournaalLaatsteBetaling
     where  (JournaalLaatsteBetaling.JrRksGid = OspRksgid)              //naw-gid
        and (JournaalLaatsteBetaling.JrReferentie = OspFactuurNummer)   //factuurnummer
        and (JournaalLaatsteBetaling.JrReferentie_Lengte = OspFactuurNummer_Lengte)
        and (JournaalLaatsteBetaling.JrFactuurdatum = OspFactuurdatum) //datum, om unieke factuur terug te vinden , samen met naw-gid en factuurnummer
        and (JournaalLaatsteBetaling.IsCreditBoeking = 1)              //alleen creditboekingen
        and (JournaalLaatsteBetaling.JrValutaBedrag > 0)               //positieve creditboeking (dus geen terugbetaling door 'ons')
        and (JournaalLaatsteBetaling.JrBoekdatum <= @Peildatum)        //situatie t/m de peildatum; betalingen daarna tellen niet mee
      )
      as DatumLaatstePosCredBetaling,

    //tmpOspBetalingsOverschr -> hoe veel te laat iemand was met betalen
    //De betalingsoverschrijding kan ook niet negatief worden. Als de factuur binnen 14 dagen betaald
    //moet worden en je betaalt na 9, dan is de betalingsoverschrijding dus niet meer -5, maar 0.
    //Als je vooruit betaalt, dus vóór de factuurdatum, dan wordt de ook gewoon 0. Niets negatiefs.
    (if OspIsGesloten = 1 then
       if DatumLaatstePosCredBetaling is null then
         0
       else
         if (DatumLaatstePosCredBetaling <= OspVervaldatum) then   //als hij op tijd of vooruit is betaald wordt het 0
           0
         else
           (DatumLaatstePosCredBetaling - OspVervaldatum)          //als ie te laat betaald is: verschil tussen betalingsdatum en vervaldatum
         endif
       endif
     else
       //bij open posten is de betalingsoverschrijding verschil tussen vervaldatum en peildatum
       if (@Peildatum - OspVervalDatum) <= 0 then  //er is nog tijd om te betalen: dan 0
         0
       else
         (@Peildatum - OspVervalDatum)             //de vervaldatum is verstreken: hij is te laat
       endif
     endif) as OspBetalingsOverschr,

    //tmpOspBetalingstermijn -> hoe lang iemand er over heeft gedaan te betalen: ook wel 'betalingstermijn' genoemd
    //De betalingstermijn kan niet negatief worden. Als je 10 dagen vooruit
    //betaalt, dus vóór de factuurdatum, dan wordt de betalingstermijn dus 0 en niet -10.
    (if OspIsGesloten = 1 then
       if DatumLaatstePosCredBetaling is null then
        0
      else
        if (DatumLaatstePosCredBetaling < OspFactuurdatum) then  //als vooruit is betaald...
          0                                                      //wordt de betalingstermijn 0 en niet negatief.
        else
          (DatumLaatstePosCredBetaling - OspFactuurdatum)        //als na de factuurdatum is betaald, dan betalingsdatum - factuurdatum. Kan niet negatief worden.
        endif
      endif
    else
      //bij open posten is de Betalingstermijn het verschil tussen peildatum en factuurdatum
      if (@Peildatum - OspFactuurdatum) < 0 then
        0
      else
        (@Peildatum - OspFactuurdatum)
      endif
    endif) as OspBetalingstermijn,

    //de toegestane betalingstermijn: hoe lang iemand erover mag doen om te betalen
    (OspVervaldatum - OspFactuurdatum) as ToegestaneBetalingstermijn,

    //Renteverlies berekenen over: posten waar berekeningen over gemaakt moeten worden, en die te laat
    //betaald zijn (gesloten) of waarvan de peildatum na de vervaldatum ligt (open post).

    (if @RentePercentage= 0 then
       0.0
     else
       if (OspIsGesloten = 1) then
         if (DatumLaatstePosCredBetaling > OspVervaldatum) then //te laat betaald
           IsNull(RapBetAnalyseRenteVerliesOSPBerekenen(OspGid, OspIsGesloten, @DefOfVoorlopig, FactuurBedrag, OspVervaldatum, @RentePercentage, @Peildatum),0)
         else    //11
           0 //22
         endif
       else //post is dus open
         if (@Peildatum > OspVervaldatum) then //peildatum voorbij vervaldatum, dus te laat
           IsNull(RapBetAnalyseRenteVerliesOSPBerekenen(OspGid, OspIsGesloten, @DefOfVoorlopig, FactuurBedrag, OspVervaldatum, @RentePercentage, @Peildatum),0)
         else//33
           0 //44
         endif
        endif
       endif) as Renteverlies,


//------------------------------------------------------------------------------

    //ALLES OMREKENEN NAAR DE VALUTA VAN FACTUUR
    (if (@AfdrValutaDebOfBasisFact = 0) or (OspValNummer = ValNrAfdrFact) then
       Factuurbedrag
     else
       ValutaOmrekenen(OspValNummer, FactuurBedrag, ValNrAfdrFact, @HulpBjGid, @HulpPerNr, 2)
     endif) as FactuurbedragInAfdrValFact,

    (if (@AfdrValutaDebOfBasisFact = 0) or (OspValNummer = ValNrAfdrFact) then
       BetaaldBedrag
     else
       ValutaOmrekenen(OspValNummer, BetaaldBedrag, ValNrAfdrFact, @HulpBjGid, @HulpPerNr, 2)
     endif) as BetaaldBedragInAfdrValFact,

    (if (@AfdrValutaDebOfBasisFact = 0) or (OspValNummer = ValNrAfdrFact) then
       OpenstaandBedrag
     else
       ValutaOmrekenen(OspValNummer, OpenstaandBedrag, ValNrAfdrFact, @HulpBjGid, @HulpPerNr, 2)
     endif) as OpenstaandBedragInAfdrValFact,

     (if (@AfdrValutaDebOfBasisFact = 0) or (OspValNummer = ValNrAfdrFact) then
        GeblokkeerdBedrag
      else
        ValutaOmrekenen(OspValNummer, GeblokkeerdBedrag, ValNrAfdrFact, @HulpBjGid, @HulpPerNr, 2)
     endif) as GeblokkeerdBedragInAfdrValFact,


    //direct te voldoen: niet geheel betaalde facturen, die vervallen zijn
    (if (OspIsGesloten = 0) and
        (OspVervalDatum < @Peildatum) then (FactuurbedragInAfdrValFact - BetaaldBedragInAfdrValFact)
     else
       0
     endif) as DirectTeVoldoenInAfdrValFact,


    //renteverlies: is altijd in basisvaluta
    (if (@AfdrValutaDebOfBasisFact <> 2) then
       ValutaOmrekenen(OspValNummer, Renteverlies, @@BasisValutaNummer, @HulpBjGid, @HulpPerNr, 2)
     else
       Renteverlies
     endif) as RenteverliesInBasisvaluta,

//------------------------------------------------------------------------------

     //ALLES OMREKENEN NAAR DE VALUTA VAN DE DEBITEUR TOTALEN
     (if ValNrAfdrDebTot = OspValNummer then
        Factuurbedrag
      else
        if ValNrAfdrDebTot = ValNrAfdrFact then
          FactuurbedragInAfdrValFact
        else
          ValutaOmrekenen(OspValNummer, FactuurBedrag,ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)
        endif
      endif) as FactuurBedragInAfdrValDeb,

     (if ValNrAfdrDebTot = OspValNummer then
         BetaaldBedrag
       else
        if ValNrAfdrDebTot = ValNrAfdrFact then
          BetaaldBedragInAfdrValFact
        else
          ValutaOmrekenen(OspValNummer, BetaaldBedrag, ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)
        endif
      endif) as BetaaldBedragInAfdrValDeb,

     (if ValNrAfdrDebTot = OspValNummer then
        OpenstaandBedrag
      else
        if ValNrAfdrDebTot = ValNrAfdrFact then
          OpenstaandBedragInAfdrValFact
        else
          ValutaOmrekenen(OspValNummer, OpenstaandBedrag, ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)
        endif
      endif) as OpenstaandBedragInAfdrValDeb,

     (if ValNrAfdrDebTot = OspValNummer then
        GeblokkeerdBedrag
      else
        if ValNrAfdrDebTot = ValNrAfdrFact then
          GeblokkeerdBedragInAfdrValFact
        else
          ValutaOmrekenen(OspValNummer, GeblokkeerdBedrag, ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)
        endif
      endif) as GeblokkeerdBedragInAfdrValDeb,


     //direct te voldoen: niet geheel betaalde facturen, die vervallen zijn
    (if (OspIsGesloten = 0) and
        (OspVervalDatum < @Peildatum) then (FactuurBedragInAfdrValDeb - BetaaldBedragInAfdrValDeb)
     else
       0
     endif) as DirectTeVoldoenInAfdrValutaDeb,

//     (if ValNrAfdrDebTot = OspValNummer then
//        Renteverlies    //66
//      else
//        if ValNrAfdrDebTot = ValNrAfdrFact then
//          RenteverliesInAfdrValutaFact //77
//        else    //88
//          ValutaOmrekenen(OspValNummer, Renteverlies,    ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)    //deze gaan goed
//        endif
//      endif) as RenteverliesInAfdrValutaDeb,

    (select nawVertegenwCode
     from tabNaw
     where NawGid = NawFilNawGid
    ) as VertegenwCode,

//    (select RelAchternaam
//     from tabRelatie
//     right outer join tabnawfile on relnawgid = nawfilnawgid
//     where relVtgCode = VertegenwCode) as VertegenwNaam


     (select RelAchternaam //relVolledigeNaam
      from  tabRelatie
      inner join tabVertegenwoordiger on VtgRelGid = RelGid
      where RelVtgCode = VertegenwCode) as VertegenwNaam


  // de view slecteert van osp''s die er dubbel in zitten alleen die van het laatste boekjaar
  from tabOpenstaandePost
       inner join tabNawfile on (ospRksGid = nawfilRksGID)

        //alleen debiteuren
  where nawFilFonID = 'D'

            //binnen de range van factuurdatum
        AND (OspFactuurDatum between @VanFactuurDatum and @TotFactuurDatum)

            //binnen de range van de gekozen debiteuren
        AND ((@Selectie = 1 and NawFilNummer    between @VanDebNr       and @TotDebNr)       or
             (@Selectie = 2 and NawFilZoekcode  between @VanDebZoekcode and @TotDebZoekcode) or
             (@Selectie = 3 and VertegenwCode   between @VanVertCode    and @TotVertCode)    or
             (@Selectie = 4 and VertegenwNaam   between @VanVertNaam    and @TotVertNaam)
            )

            //facturen van na de peildatum doen niet mee
        AND (OspFactuurdatum <= @Peildatum)


            //als de niet-vervallen posten getoond moeten worden: alleen die waarvan de vervaldatum vóór de peildatum ligt.
        AND ( (@AfdrNietVervallenPosten = 1) or
             ((@AfdrNietVervallenPosten = 0) and (OspVervalDatum < @Peildatum)) )

            //zorgen dat je of alleen osp''s met in ieder geval definitieve of in ieder geval voorlopige gegevens hebt, of gewoon allemaal
        AND (FactuurBedrag <> 0 or BetaaldBedrag <> 0 or @DefOfVoorlopig = 2) //hier hoeft geen controle meer op @DefOfVoorlopig op: dat wordt boven al geregeld!

            //als alleen gesloten posten mee mogen, dan moet betaald bedrag precies 0 zijn, anders maakt het niet uit
        AND ( (@AfdrNogOpenstaandePosten = 1) or
             ((@AfdrNogOpenstaandePosten = 0) and (FactuurBedrag - BetaaldBedrag = 0)))

            //nooit creditnota''s tonen: factuurbedrag moet altijd positief zijn.
        AND (FactuurBedrag >= 0)

            //bij geen geblokkeerde posten meenemen: geblokkeerd = false, anders maakt het niet uit
        AND ( (@AfdrGeblokkeerdePosten = 1) or
             ((@AfdrGeblokkeerdePosten = 0) and (OspIsGeblokkeerd = 0)) )

        //van osp''s die er dubbel in zitten: alleen die nemen van het laatste boekjaar
        AND (OspGid not in (select
                            distinct NietGebruikteJournaalregel.JrOSPgid
                            from
                             tabJournaalregel NietGebruikteJournaalregel
                             inner join tabBoekjaar NietGebruiktBoekjaar on (NietGebruikteJournaalRegel.JrBjGid = NietGebruiktBoekjaar.BjGid)
                            where
                             JrOspGid is not null and
                            exists (select                      // Lees alle boekjaren waarvoor geldt dat de OSP een boeking heeft in een boekjaar NA dit boekjaar
                                     TestJournaalRegel.JrBjGid  // Gebruik ALLEEN journaalregels die NIET in dit gelezen boekjaar zitten
                                    from
                                     tabJournaalregel TestJournaalRegel
                                    inner join tabBoekjaar TestBoekjaar on (TestJournaalRegel.JrBjGid = TestBoekjaar.BjGid)
                                    where
                                     TestJournaalRegel.JrRksGid        = NietGebruikteJournaalregel.JrRksGid       and
                                     TestJournaalRegel.JrFactuurDatum  = NietGebruikteJournaalregel.JrFactuurDatum and
                                     TestJournaalRegel.JrReferentie    = NietGebruikteJournaalregel.JrReferentie   and
                                     TestJournaalRegel.JrReferentie_Lengte = NietGebruikteJournaalregel.JrReferentie_Lengte and
                                     TestBoekjaar.BjBeginDatum         > NietGebruiktBoekjaar.BjBeginDatum
            )              )       )
  ;
  ;


//  call traceEind('rapBetAnalyseDebTmpTabVullen');

end;




//$Workfile: rapBetAnalyseRenteVerliesOSPBerekenen.sp $ $Revision: 3 $ $Modtime: 1-04-08 14:59 $'

if exists(select 1 from sys.sysProcedure where proc_name='rapBetAnalyseRenteVerliesOSPBerekenen') then
  drop function rapBetAnalyseRenteVerliesOSPBerekenen;
end if;

create function rapBetAnalyseRenteVerliesOSPBerekenen(in @JrOspGid integer,
                                                      in @IsGesloten smallint,
                                                      in @DefOfVoorlopig smallint,
                                                      in @VolledigFactuurBedrag numeric(15,2),
                                                      in @OspVervalDatum date,
                                                      in @RentePercentage numeric(15,2),
                                                      in @Peildatum date
                                                     )
returns numeric (15,3)
begin
  //velden
  declare @JrGid                     integer;
  declare @JrBoekdatum               date;
  declare @DatumLaatsteBetaling      date;
  declare @JrValutaBedrag            numeric (15,2);
  declare @IsCreditboeking           smallint;

  //nieuwe variabelen
  declare @RenteOverEenJaar          numeric (15,2);
  declare @ResterendOpenstaandBedrag numeric (15,2);
  declare @NietBetaaldBedrag         numeric (15,2);
  declare @AantalDagen               numeric (15,2);

  declare @ErZijnDeelBetalingen      smallint;
  declare @AlleDeelbetalingenOpTijd  smallint;

  declare @TmpRenteverlies           numeric (15,2);
  declare @Renteverlies              numeric (15,2);
  declare @OpTijd                    smallint;

  //call TraceBegin('rapBetAnalyseRenteVerliesOSPBerekenen');

   //Berekening geleden renteverlies: alléén berekend indien de factuur niet vóór de vervaldatum is betaald.
   //Renteverlies berekend op basis van aantal dagen tussen de datum van de betalingen en de vervaldatum,
   //het openstaande bedrag en het rentepercentage. Moet per deelbetaling berekend worden omdat na de deelbetaling
   //het openstaand saldo verminderd.

   //Deze functie wordt aangeroepen als of:
   //-de post gesloten is, maar de laatste positieve creditbetaling was na de vervaldatum of:
   //-de post geopend is en de peildatum na de vervaldatum is

   //Als alleen definitieve gegevens getoond moeten worden, bereken je op elke deelbetaling, die Definitief is de rente.
   //Als er in dit geval ook Voorlopige deelbetalingen zijn, negeer je deze en behandeld je deze alsof deze er niet zijn.
   //Gevolg: je berekent over alle definitieve bedragen de rente en je berekent over het totale resterende bedrag (of dit
   //nou voorlopig was betaald, of helemaal niet) de rente uit, uitgaande van het verschil tussen peildatum en vervaldatum.

   //Bij alleen definitieve boekingen tonen: kijken of er voor deze osp ook voorlopige positieve creditboekingen zijn:
   //zo ja: het totaal van het betaald bedrag van de definitieve boekingen aftrekken van het totale openstaande bedrag (def+voorl).
   //Zo krijg je het restbedrag dat of voorlopig is betaald, of helemaal niet is betaald. Hier moet je rente over gaan berekenen
   //aan de hand van verschil peildatum en vervaldatum

   //NB: als een factuur 1 dag te laat is betaald, wordt er voor 1 dag renteverlies berekend. (Je gaat dus uit van de situatie die dag van s ochtends vroeg.)

  set @Renteverlies              = 0;
  set @TmpRenteverlies           = 0;
  set @AantalDagen               = 0;
  set @ResterendOpenstaandBedrag = @VolledigFactuurBedrag;
  set @RenteOverEenJaar          = 0;
  set @NietBetaaldBedrag         = 0;
  set @DatumLaatsteBetaling      = @OspVervaldatum;

   //zijn er voor deze osp deelbetalingen ja of nee?
  if (exists (select 1
              from tabJournaalregel
              where (JrOspGid = @JrOspGid)
                and (IsCreditboeking = 1)       //alleen de betalingen
                and (JrValutabedrag  > 0)       //die positief zijn
                and (JrBoekdatum <= @Peildatum) //die op of voor de peildatum zijn gedaan
             )
     ) then
    set @ErZijnDeelBetalingen = 1
  else
    set @ErZijnDeelBetalingen = 0
  end if;

  //als er deelbetalingen zijn, waren die dan allemaal op tijd betaald?
  if @ErZijnDeelBetalingen = 1 then
    if ((select max(JrBoekdatum)
         from tabJournaalregel
         where (JrOspGid = @JrOspGid)
           and (IsCreditboeking = 1)        //alleen de betalingen
           and (JrValutabedrag  > 0)        //die positief zijn  en die op of voor de peildatum zijn gedaan
           and (JrBoekdatum <= @Peildatum)
        ) <= @OspVervaldatum) then          //datum laatste boeking voor vervaldatum?
      set @AlleDeelbetalingenOpTijd = 1     //ja: allemaal op tijd
    else
      set @AlleDeelbetalingenOpTijd = 0
    end if;
  end if;

  //Als er deelbetalingen zijn, is er dan nog een niet betaald bedrag?
  //Als er geen deelbetalingen zijn, is het resterende bedrag waar eventueel renteverlies over moet worden berekend, het volledige factuur bedrag.
  if @ErZijnDeelBetalingen = 1 then
    set @NietBetaaldBedrag = (@VolledigFactuurBedrag - (select sum(JrValutabedrag)
                                                        from tabJournaalregel
                                                        where (JrOspGid = @JrOspGid)
                                                          and (IsCreditboeking = 1)        //alleen de betalingen
                                                          and (JrValutabedrag  > 0)        //die positief zijn
                                                          and (JrBoekdatum <= @Peildatum)  //die op of voor de peildatum zijn gedaan
                                                       )
                             );
  else
    set @NietBetaaldBedrag = @VolledigFactuurBedrag                                        //er is niets betaald: het volledige bedrag moet nog betaald worden.
  end if;




  BEGIN
    DECLARE cur_Rente CURSOR FOR
      SELECT JrGid, JrBoekdatum, JrValutaBedrag, IsCreditboeking
      FROM tabOpenstaandePost
      LEFT OUTER JOIN tabJournaalregel on jrOspGid = OspGid //jr
      WHERE                                                            //alle journaalregels van/met:
           (JrOspGid = @JrOspGid)                                      //deze osp
       //AND (IsCreditboeking = 1)                                     //alleen creditboekingen
       //AND (JrValutabedrag  > 0)                                     //alleen positieve boekingen: betalingen  //deze niet hier: anders komen de osps zonder betaling niet mee
       AND (((@DefOfVoorlopig = 0) and ((IsNull(RegelNummer,'') <> ''))) or  //alleen definitieve journaalregels
            ((@DefOfVoorlopig = 1) and ((IsNull(RegelNummer,'') = ''))) or  //alleen voorlopige journaalregels
             (@DefOfVoorlopig = 2)                                     //definitieve en voorlopige journaalregels
           )
       AND (JrBoekdatum <= @Peildatum)                                 //alleen die van op of voor de peildatum nemen
      ORDER BY JrBoekdatum, JrOspGid  //moet erbij omdat je aan de hand van boekdatum de som berekent van de tot dan toe betaalde bedragen
      ;

      OPEN cur_Rente;
      loopje1:
      LOOP

        //call trace('BEGIN LOOPJE');

        FETCH NEXT cur_Rente INTO @JrGid, @JrBoekdatum, @JrValutaBedrag, @IsCreditboeking;
        //als ie dit heeft bereikt (hetzelfde voor alle loopjes in king) dan is ie klaar en kan ie eruit springen
        if sqlstate = '02000' then
          leave loopje1;
        end if;



        if (@IsCreditboeking = 1) then
        begin
          //call trace('factuurbedrag = ' + string(@VolledigFactuurBedrag) + ', JrValutabedrag = ' + string(@JrValutabedrag) + ', resterend bedrag = ' + string(@ResterendOpenstaandBedrag) + ', isCreditboeking = ' + string(@IsCreditboeking));

          if @ErZijnDeelBetalingen = 1 then                       //er is iets betaald
          begin
            //call trace('  MET DEELBETALING - AlleDeelbetalingenOpTijd = ' + string(@AlleDeelbetalingenOpTijd) + ', @NietBetaaldBedrag = ' + string(@NietBetaaldBedrag) );
            if (@AlleDeelbetalingenOpTijd = 1) then               //alles op tijd betaald: geen renteverlies
              set @Renteverlies = 0;
              //call trace('geen renteverlies - alles op tijd betaald');
            else                                                  //niet alles op tijd betaald: renteverlies berekenen over alle deelbetalingen
              //call trace ('@JrBoekdatum > @OspVervaldatum = ' + string(@JrBoekdatum) + ' > ' + string(@Ospvervaldatum));

              if (@JrBoekdatum > @OspVervaldatum) then            //renteverlies alleen berekenen voor alle deelbetalingen die te laat waren
              begin
                //call trace('aantal dagen = ' + string(@aantaldagen));
                set @AantalDagen = (@JrBoekdatum - @DatumLaatsteBetaling) ;
                //call trace('aantal dagen = ' + string(@aantaldagen) + ', jrboekdatum - datum laatste betaling = ' + string(@JrBoekdatum) + ' - ' + string(@DatumLaatsteBetaling));
                set @RenteOverEenJaar = ((1 + (@RentePercentage/100)) * @ResterendOpenstaandBedrag - @ResterendOpenstaandBedrag);
                //call trace('rente over een jaar = ' + string(@Renteovereenjaar) + ', Rentepercentage = ' + string(@rentepercentage) + ', @ResterendOpenstaandBedrag = ' + string(@ResterendOpenstaandBedrag));
                set @Renteverlies = @Renteverlies + ((@RenteOverEenJaar / 365) * @AantalDagen);
                //call trace('Renteverlies = ' + string(@renteverlies) + ' - deelbetaling is te laat');
                set @DatumLaatsteBetaling = @JrBoekdatum;
              end
              end if;
            end if;
          end
          else
          begin //er is nog niets betaald
            //call trace('  ZONDER DEELBETALING');
            //mr 01-apr-2008 bug #28110: @ stond niet voor @ospVervaldatum??
            if (@Peildatum <= @OspVervaldatum) then
              set @OpTijd = 1
            else
              set @OpTijd = 0
            end if;

            if @OpTijd = 1 then
              set @Renteverlies = 0;
              //call trace('geen renteverlies - geen betalingen, maar nog voor vervaldatum');
            else //we zijn te laat: wel renteverlies berekenen, over het hele factuurbedrag
              begin
                //call trace('aantal dagen = ' + string(@aantaldagen));
                set @AantalDagen = (@JrBoekdatum - @DatumLaatsteBetaling);
                //call trace('aantal dagen = ' + string(@aantaldagen) + ', jrboekdatum - datum laatste betaling = ' + string(@JrBoekdatum) + ' - ' + string(@DatumLaatsteBetaling));
                set @RenteOverEenJaar = ((1 + (@RentePercentage/100)) * @VolledigFactuurBedrag - @VolledigFactuurBedrag);
                set @Renteverlies = @Renteverlies + ((@RenteOverEenJaar / 365) * @AantalDagen);
                //call trace('Renteverlies = ' + string(@renteverlies) + ' - niets betaald en voorbij vervaldatum');
                set @DatumLaatsteBetaling = @JrBoekdatum;
              end
            end if;
          end
          end if;

          set @ResterendOpenstaandBedrag = (@ResterendOpenstaandBedrag - @JrValutaBedrag); //het oude resterende bedrag min betaalde bedrag van deze journaalregel

        end
        end if; //if (@IsCreditboeking = 1) then
        //call trace('EINDE LOOPJE');


      END LOOP loopje1;
    CLOSE cur_Rente;
  END;


  //Tot slot de rente berekenen voor het helemaal niet betaalde bedrag, mits we na de vervaldatum zitten
  //call trace('           @NIETBETAALDBEDRAG = ' + string(@NietBetaaldBedrag) + ', @DatumLaatsteBetaling = ' + string(@DatumLaatsteBetaling) + ', peildatum > vervaldatum = ' + string(@Peildatum) + ' > ' + string(@ospvervaldatum));
  if (@NietBetaaldBedrag  > 0) and (@Peildatum > @OspVervaldatum) then
  begin
    set @AantalDagen = @Peildatum - @DatumLaatsteBetaling;
    set @RenteOverEenJaar = ((1 + (@RentePercentage/100)) * @NietBetaaldBedrag - @NietBetaaldBedrag);
    set @TmpRenteverlies = ((@RenteOverEenJaar / 365) * @AantalDagen);
    //call trace('AANTAL DAGEN = ' + string(@aantaldagen) + ', Rente over een jaar = ' + string(@renteovereenjaar) + ', tmpRenteverlies  = ' + string(@tmpRenteverlies) + ', renteverlies = ' + string(@Renteverlies));
    set @Renteverlies = @Renteverlies + @TmpRenteverlies;
    //call trace('Renteverlies  = ' + string(@Renteverlies));
  end
  end if;

  //call traceEind('rapBetAnalyseRenteVerliesOSPBerekenen');
  return (@Renteverlies);


end;


//$Workfile: rapBetAnalyseTotalenPerNaw.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists(select 1 from sys.sysProcedure where proc_name='rapBetAnalyseTotalenPerNaw') then
  drop procedure rapBetAnalyseTotalenPerNaw;
end if;

create procedure rapBetAnalyseTotalenPerNaw(
 in @RksGid                                integer,

 //Omdat het resultaat altijd uit één record bestaat, kun je dit beter in out-parameters
 //stoppen dan in een return-values. Zo kun je veel makkelijker waarden berekenen dmv verschillende queries.

 //NB: omdat van tmpOspFactuurbedragInAfdrValDeb en tmpOspBetaaldBedragInAfdrValDeb
 //gebruik is gemaakt, zijn de uitkomsten al in de juiste afdrukvaluta!

 //open posten
 out @TotFactuurbedragOpenstaandePosten      numeric(15,2), //T2
 out @TotBetaaldOpenPosten                   numeric(15,2), //T4
 out @TotOpenstaandSaldo                     numeric(15,2), //T5
 out @GemBetOverschrOpenPosten               numeric(15,2), //T7
 out @GemBetalingsTermijnOpenPosten          numeric(15,2), //T10
 out @LangsteBetalingstermijnOpenPosten      integer,       //T16
 out @RenteverliesOpenPosten                 numeric(15,2), //T23
 out @TotDirectTeVoldoen                     numeric(15,2), //T6
 out @LangsteBetOverschrOpenPosten           integer,       //T29
 out @TotGeblokkeerdBedrag                   numeric(15,2), //T30
 out @AantalNogOpenPosten                    integer,       //T18


 //overig 1 - open en gesloten, maar wel volledig (en te veel) betaald
 out @AantalGeslotenPostenTeLaatBetaald      numeric(15,2), //T35         //extra, makkelijk voor berekening, niet beschikbaar stellen in layout
 out @AantPostenBinnenTermijnVollBetaald     integer,       //T20

 //gesloten posten
 out @TotFactuurbedragBetaaldePosten         numeric(15,2), //T1
 out @GemBetOverschrGeslotenPosten           numeric(15,2), //T8
 out @GemBetalingstermijnGeslotenPosten      numeric(15,2), //T11
 out @RenteverliesGeslotenPosten             numeric(15,2), //T22
 out @AantalPostenVolledigBetaald            integer,       //T17
 out @KortsteBetOverschrijdingGeslotenPosten integer,       //T27
 out @LangsteOverschrijdingGeslotenPosten    integer,       //T28
 out @KortsteBetalingstermijnGeslotenPosten  integer,       //T14
 out @LangsteBetalingstermijnGeslotenPosten  integer,       //T15
 out @AantalBinnenToegBetTermijnBetaald      integer,       //T33
 out @AantalBinnenToegBetTermijnBetaaldPerc  numeric(15,2), //T34

 //algemeen
 out @PercGeslotenPostenTeLaatBetaald        numeric(15,2), //T13

 //totaal open en gesloten
 out @TotFactuurbedragTotaal                 numeric(15,2), //T3
 out @GemBetalingstermijnAllePosten          numeric(15,2), //T12
 out @GemBetOverschrAllePosten               numeric(15,2), //T9
 out @RenteverliesAllePosten                 numeric(15,2), //T24
 out @TotaalAantalPosten                     integer,       //T19
 out @GemToegestaneBetalingstermijn          numeric(15,2)  //T31

 //overig 2 - geheel of te veel betaald en binnen betalingstermijn volledig betaald
 //out @AantPostenBinnenTermijnVollBetaaldPerc integer      //T21
 )
begin
  //call traceBegin('rapBetAnalyseTotalenPerNaw');

  //NB: de hoofdqueries moeten in deze volgorde worden aangeroepen, omdat er een aantal variabelen wordt gevuld, dat verderop gebruikt wordt

  //BEREKENINGEN OVER OPENSTAANDE OSP''S
  //T2  - @TotFactuurbedragOpenstaandePosten  : totaal factuurbedrag nog openstaande posten
  //T4  - @TotBetaaldOpenPosten               : totaal betaald bedrag op nog openstaande posten
  //T5  - @TotOpenstaandSaldo                 : openstaand saldo (het openstaand bedrag)
  //T7  - @GemBetOverschrOpenPosten           : gemiddelde betalingsoverschrijding openstaande facturen in dagen
                                                //(alleen bij niet (geheel) betaalde OSP''s; verschil tussen vervaldatum en peildatum in dagen )
  //T10 - @GemBetalingsTermijnOpenPosten      : gemiddelde Betalingstermijn/betalingstermijn openstaande facturen in dagen (alleen bij niet (geheel) betaalde OSP''s;
  //T16 - @LangsteBetalingstermijnOpenPosten  : langste termijn nog openstaande posten (Het aantal dagen dat de oudste openstaande post openstaat)
                                                //verschil tussen factuurdatum en peildatum in dagen) , is dus gewoon die met de grootste/hoogste Betalingstermijn/betalingstermijn
  //T23 - @RenteverliesOpenPosten             : totaal renteverlies openstaande facturen
  //T6  - @TotDirectTeVoldoen                 : totaal direct te voldoen: niet geheel betaalde facturen, die vervallen zijn
  //T29 - @LangsteBetOverschrOpenPosten       : langste betalingsoverschrijding openstaande posten (het aantal dagen dat de vervaldatum is overschreden)
  //T30 - @TotGeblokkeerdBedrag               : totaal geblokkeerde bedrag
  select sum(tmpOspFactuurbedragInAfdrValDeb),
         sum(tmpOspBetaaldBedragInAfdrValDeb),
         sum(IsNull(tmpOspFactuurbedragInAfdrValDeb,0) - IsNull(tmpOspBetaaldBedragInAfdrValDeb,0)),
         avg(tmpOspBetalingsOverschr), //dit kan, want deze select heeft in de where dat de post open moet zijn
         avg(tmpOspBetalingstermijn),
         max(tmpOspBetalingstermijn),
//         (select count(*)),
         sum(tmpOspRenteverliesInBasisvaluta),
         sum(tmpOspDirectTeVoldoenInAfdrValDeb),
         max(tmpOspBetalingsOverschr),
         sum(tmpOspGeblokkeerdBedrag)
  into   @TotFactuurbedragOpenstaandePosten, @TotBetaaldOpenPosten, @TotOpenstaandSaldo,
         @GemBetOverschrOpenPosten, @GemBetalingsTermijnOpenPosten, @LangsteBetalingstermijnOpenPosten,
         @RenteverliesOpenPosten, @TotDirectTeVoldoen, @LangsteBetOverschrOpenPosten, @TotGeblokkeerdBedrag
  from   tmpDebAnalyseOsps
  where  (tmpOspRksGid = @RksGid)
     and (tmpOspIsGesloten = 0)
  ;

  //T18 - @AantalNogOpenPosten                : aantal nog openstaande openstaande posten
  set @AantalNogOpenposten = (select count(*)
                              from   tmpDebAnalyseOsps
                              where  (tmpOspRksGid = @RksGid)
                                 and (tmpOspIsGesloten = 0)
                             );


  //T20 aantal gesloten openstaande posten binnen de termijn volledig betaald, dus NIET als te veel is betaald
//  select count(*)
//  into   @AantPostenBinnenTermijnVollBetaald
//  from   tmpDebAnalyseOsps
//  where  (tmpOspRksGid = @RksGid)
//     and (tmpOspIsGesloten = 1)
//     and (tmpOspDatumLaatstePosCredBetaling <= tmpOspVervaldatum)
//  ;


  //BEREKENINGEN OVER GESLOTEN OSP''S
  //T1  - @TotFactuurbedragBetaaldePosten    : totaal factuurbedrag betaalde posten
  //T25 - @TotBetaaldbedragGeslotenPosten    : totaal betaaldbedrag betaalde posten
  //T8  - @GemBetOverschrGeslotenPosten      : gemiddelde betalingsoverschrijding betaalde facturen in dagen (aantal dagen tussen vervaldatum en laatste betaling) (alleen voor volledig betaalde facturen)
  //T11 - @GemBetalingstermijnGeslotenPosten : gemiddelde Betalingstermijn/betalingstermijn betaalde facturen in dagen (aantal dagen tussen factuurdatum en laatste betaling) (alleen voor volledig betaalde facturen)
  //T22 - @RenteverliesGeslotenPosten        : totaal renteverlies betaalde facturen
  //T17 - @AantalPostenVolledigBetaald : aantal facturen volledig betaald, dus NIET die waarvoor te veel is betaald, en die nog openstaand zijn
  //T27 - @KortsteBetOverschrijdingGeslotenPosten : Kortste betalingsoverschrijding gesloten posten. Laagste aantal dagen dat te laat is betaald.
  //T28 - @LangsteOverschrijdingGeslotenPosten    : Langste betalingsoverschrijding gesloten posten. Hoogste aantal dagen dat te laat is betaald.
  //T14 - @KortsteBetalingstermijnGeslotenPosten  : Kortste betalingstermijn (Het laagste aantal dagen dat een ost heeft
                                                  //opengestaan. Dit is exclusief de nog openstaande posten)            -> kleinste/laagste Betalingstermijn/betalingstermijn
  //T15 - @LangsteBetalingstermijnGeslotenPosten : Langste betalingstermijn (Het hoogste aantal dagen dat een ost heeft
                                                 //opengestaan. Dit is exclusief de nog openstaande posten)           -> grootste/hoogste Betalingstermijn/betalingstermijn
  select sum(tmpOspFactuurbedragInAfdrValDeb),
         avg(tmpOspBetalingsOverschr),  //dit kan, want in de voorwaarde van de select staat dat de osp gesloten moet zijn
         avg(tmpOspBetalingstermijn),
         sum(tmpOspRenteverliesInBasisvaluta),
         count(*),
         min(tmpOspBetalingsOverschr),
         max(tmpOspBetalingsOverschr),
         min(tmpOspBetalingstermijn),
         max(tmpOspBetalingstermijn)
  into   @TotFactuurbedragBetaaldePosten,  @GemBetOverschrGeslotenPosten, @GemBetalingstermijnGeslotenPosten,
         @RenteverliesGeslotenPosten, @AantalPostenVolledigBetaald, @KortsteBetOverschrijdingGeslotenPosten, @LangsteOverschrijdingGeslotenPosten,
         @KortsteBetalingstermijnGeslotenPosten, @LangsteBetalingstermijnGeslotenPosten
  from   tmpDebAnalyseOsps
  where  (tmpOspRksGid = @RksGid)
     and (tmpOspIsGesloten = 1)               //alleen gesloten posten
  ;


  //algemeen
  //T33 - @AantalBinnenToegBetTermijnBetaald
  select count(*)
  into   @AantalBinnenToegBetTermijnBetaald
  from   tmpDebAnalyseOsps
  where  (tmpOspRksGid = @RksGid)
     and (tmpOspIsGesloten = 1)                                   //alleen gesloten posten
     and (tmpOspDatumLaatstePosCredBetaling <= tmpOspVervaldatum) //op tijd betaald: voor de vervaldatum
  ;

  //T34 - @AantalBinnenToegBetTermijnBetaaldPerc: 'Aantal facturen binnen toegestane betalingstermijn volledig betaald/ Aantal facturen volledig betaald * 100'
  if ((@AantalPostenVolledigBetaald <= 0) or (@AantalBinnenToegBetTermijnBetaald <= 0)) then
    set @AantalBinnenToegBetTermijnBetaaldPerc = 0
  else
    set @AantalBinnenToegBetTermijnBetaaldPerc = ((@AantalBinnenToegBetTermijnBetaald / @AantalPostenVolledigBetaald) * 100)
  end if;

  //T35 - @AantalGeslotenPostenTeLaatBetaald
  set @AantalGeslotenPostenTeLaatBetaald = @AantalPostenVolledigBetaald - @AantalBinnenToegBetTermijnBetaald;

  //T13 - @PercGeslotenPostenTeLaatBetaald  : percentage van betaalde facturen te laat betaald:
  //(('Aantal betaalde facturen te laat betaald' / 'Aantal facturen volledig betaald') * 100%)
  if ((@AantalPostenVolledigBetaald <= 0) or (@AantalGeslotenPostenTeLaatBetaald <= 0)) then
    set @PercGeslotenPostenTeLaatBetaald = 0
  else
    set @PercGeslotenPostenTeLaatBetaald = ((@AantalGeslotenPostenTeLaatBetaald / @AantalPostenVolledigBetaald) * 100)
  end if;

  //algemeen
  //T13 - @PercGeslotenPostenTeLaatBetaald  : percentage van betaalde facturen te laat betaald:
  //(('Aantal betaalde facturen te laat betaald' / 'Aantal facturen volledig betaald') * 100%)
  //meegenomen worden waarbij te veel is betaald, en die daarom nog open staan)
  //Nee, nu worden weer de alleen echt gesloten posten meegenmen, niet die te veel betaald zijn en dus nog openstaan... zucht. 16/1/03
  //if @AantalPostenVolledigBetaald > 0 then
//  if ((select count(*)                                                  //aantal te laat, maar volledig betaalde osp''s deze debiteur
//        from tmpDebAnalyseOsps                                          //->  mag geen 0 zijn
//        where (tmpOspRksGid = @RksGid)
//          and (tmpOspIsGesloten   = 1)
//          and (tmpOspDatumLaatstePosCredBetaling > tmpOspVervaldatum)
//       ) > 0  AND
//       (select count(*)                                                 //het aantal gesloten osp''s deze debiteur
//        from tmpDebAnalyseOsps                                          //-> mag geen 0 zijn
//        where (tmpOspRksGid = @RksGid)
//          and (tmpOspIsGesloten   = 1)
//       ) > 0
//      ) then
//
//   set @PercGeslotenPostenTeLaatBetaald =  (((select count(*)           //aantal te laat, maar volledig betaalde osp''s deze debiteur
//                                              from tmpDebAnalyseOsps
//                                              where (tmpOspRksGid = @RksGid)
//                                                and (tmpOspIsGesloten   = 1)
//                                                and (tmpOspDatumLaatstePosCredBetaling > tmpOspVervaldatum)
//                                             ) /                        //gedeeld door
//                                             (select count(*)           //het aantal gesloten osp''s deze debiteur
//                                              from tmpDebAnalyseOsps
//                                              where (tmpOspRksGid = @RksGid)
//                                                and (tmpOspIsGesloten   = 1)
//                                             )
//                                            ) * 100
//                                           )
//   else
//     set @PercGeslotenPostenTeLaatBetaald = 0
//   end if;


  //TOTALEN OPEN EN GESLOTEN
  //T3  - @TotFactuurbedragTotaal        : totaal factuurbedrag betaalde en openstaande posten
  //T12 - @GemBetalingstermijnAllePosten : gemiddelde Betalingstermijn/betalingstermijn openstaande facturen in dagen van openstaande facturen + betaalde facturen
  //T9  - @GemBetOverschrAllePosten      : gemiddelde betalingsoverschrijding betaalde facturen in dagen van openstaande facturen + betaalde facturen
  //T24 - @RenteverliesAllePosten        : totaal renteverlies betaalde + openstaande facturen
  //T19 - @TotaalAantalPosten            : totaal aantal facturen
  //T31 - @GemToegestaneBetalingstermijn : gemiddelde van de toegestane betalingstermijnen
  set @TotFactuurbedragTotaal   = IsNull(@TotFactuurbedragBetaaldePosten,0) + IsNull(@TotFactuurbedragOpenstaandePosten,0);
  set @GemBetalingstermijnAllePosten    = (select avg(tmpOspBetalingstermijn)
                                           from   tmpDebAnalyseOsps
                                           where  (tmpOspRksGid = @RksGid)
                                          );

  set @GemBetOverschrAllePosten = (select avg(tmpOspBetalingsOverschr)
                                   from   tmpDebAnalyseOsps
                                   where  (tmpOspRksGid = @RksGid)
                                  );
  set @RenteverliesAllePosten   = IsNull(@RenteverliesGeslotenPosten,0) + IsNull(@RenteverliesOpenPosten,0);

  set @TotaalAantalPosten       = (select count(*)
                                   from tmpDebAnalyseOsps
                                   where (tmpOspRksGid = @RksGid)
                                  );

  set @GemToegestaneBetalingstermijn = (select avg(tmpOspToegestaneBetalingstermijn)
                                        from tmpDebAnalyseOsps
                                        where (tmpOspRksGid = @RksGid)
                                       );


  //overig 2 - geheel of te veel betaald en binnen betalingstermijn volledig betaald
  //T21 - @AantalBinnenToegBetTermijnBetaaldPerc : aantal facturen binnen betalingstermijn volledig betaald in %
  //(=('aantal facturen binnen betalingstermijn volledig betaald' / 'aantal facturen volledig betaald') *100% )
  if (@AantalBinnenToegBetTermijnBetaald <> 0) and //door 0 delen kan niet...
     (@AantalPostenVolledigBetaald        <> 0) then
    set @AantalBinnenToegBetTermijnBetaaldPerc = (@AantalBinnenToegBetTermijnBetaald / @AantalPostenVolledigBetaald) * 100;
  else
    set @AantalBinnenToegBetTermijnBetaaldPerc = 0
  end if;

  //call TraceEind('rapBetAnalyseTotalenPerNaw');


end;


//$Workfile: rapBoekingsgangTotalen.sp $ $Revision: 4 $ $Modtime: 7-07-08 7:49 $'

if exists (select 1 from sys.sysProcedure where proc_name='rapBoekingsgangTotalen') then
  drop procedure rapBoekingsgangTotalen;
end if;

create procedure rapBoekingsgangTotalen(
in @SoortBoeking                   smallint, // 0=definitief, 1=voorlopig, 2=beide
in @BjGid                          integer,
in @BoekgangGid                    integer,
in @DefValTegRekNummer             integer,
in @TotalenAfdrukkenIn             integer,  // 0=Default-valuta van tegenrekening van eerste dagboek van boekingsgang, 2=basisvaluta, 3=extra valuta
in @TotalenAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta.

result (
  TotaalDDefValTegRek numeric(15,2),
  TotaalCDefValTegRek numeric(15,2),
  SaldoDefValTegRek   numeric(15,2),
  TotaalDBasisVal     numeric(15,2),
  TotaalCBasisVal     numeric(15,2),
  SaldoBasisVal       numeric(15,2),
  TotaalDExtraVal     numeric(15,2),
  TotaalCExtraVal     numeric(15,2),
  SaldoExtraVal       numeric(15,2),
  TotaalDAfdrukVal    numeric(15,2),
  TotaalCAfdrukVal    numeric(15,2),
  SaldoAfdrukVal      numeric(15,2),
  TotaalDAantal       numeric(15,2),
  TotaalCAantal       numeric(15,2),
  SaldoAantal         numeric(15,2))

begin
   // Voorkomen van afrondingsverschillen
  declare @NumDeciDefValTegRek          integer;
  declare @NumDeciBasisVal              integer;
  declare @NumDeciExtraValTotalen       integer;

  //call TraceBegin('rapBoekingsgangTotalen (@SoortBoeking='+string(@SoortBoeking)+', @BjGid='+string(@BjGid)+', @BoekgangGid='+string(@BoekgangGid)+', @DefValTegRekNummer='+string(@DefValTegRekNummer)+', ...');
  //call Trace('..., @TotalenAfdrukkenIn='+string(@TotalenAfdrukkenIn)+', @TotalenAfdrukkenExtraValNummer='+string(@TotalenAfdrukkenExtraValNummer)+')');

  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciDefValTegRek from tabValuta where ValNummer = @DefValTegRekNummer;
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal     from tabValuta where ValNummer = @@BasisValutaNummer;
  if @TotalenAfdrukkenIn = 3 then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenAfdrukkenExtraValNummer;
  end if;

  //call TraceEind('rapBoekingsgangTotalen');

  select
    // ---------- Default-valuta van tegenrekening van dagboek ----------
    isnull(sum(round((if IsCreditBoeking = 0 then
                        if @DefValTegRekNummer = JrValNummer then
                          JrValutaBedrag
                        else
                          round(JrBasisBedrag, @NumDeciBasisVal)/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer)
                        endif
                      endif
                     ), @NumDeciDefValTegRek
                    )
               ), 0
          )TotaalDDefValTegRek,
    isnull(sum(round((if IsCreditBoeking = 1 then
                        if @DefValTegRekNummer = JrValNummer then
                          JrValutaBedrag
                        else
                          round(JrBasisBedrag, @NumDeciBasisVal)/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer)
                        endif
                      endif
                     ), @NumDeciDefValTegRek
                    )
               ), 0
          )TotaalCDefValTegRek,
    (TotaalDDefValTegRek - TotaalCDefValTegRek) SaldoDefValTegRek,

    // ---------- Basisvaluta ----------
    isnull(sum(round((if IsCreditBoeking = 0 then JrBasisBedrag endif), @NumDeciBasisVal)), 0) TotaalDBasisVal,
    isnull(sum(round((if IsCreditBoeking = 1 then JrBasisBedrag endif), @NumDeciBasisVal)), 0) TotaalCBasisVal,
    (TotaalDBasisVal - TotaalCBasisVal) SaldoBasisVal,

    // ---------- Eventuele extra valuta ----------
    if @TotalenAfdrukkenExtraValNummer is not null then
      isnull(sum(round((if IsCreditBoeking = 0 then
                          if @TotalenAfdrukkenExtraValNummer = JrValNummer then
                            JrValutaBedrag
                          else
                            round(JrBasisBedrag, @NumDeciBasisVal)/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer)
                          endif
                        endif
                       ), @NumDeciExtraValTotalen
                      )
                ), 0
            )
    endif TotaalDExtraVal,
    if @TotalenAfdrukkenExtraValNummer is not null then
      isnull(sum(round((if IsCreditBoeking = 1 then
                          if @TotalenAfdrukkenExtraValNummer = JrValNummer then
                            JrValutaBedrag
                          else
                            round(JrBasisBedrag, @NumDeciBasisVal)/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer)
                          endif
                        endif
                       ), @NumDeciExtraValTotalen
                      )
                ), 0
            )
    endif TotaalCExtraVal,
    (TotaalDExtraVal - TotaalCExtraVal) SaldoExtraVal,
    case @TotalenAfdrukkenIn
      when 0 then TotaalDDefValTegRek
      when 2 then TotaalDBasisVal
      when 3 then TotaalDExtraVal
    end TotaalDAfdrukVal,
    case @TotalenAfdrukkenIn
      when 0 then TotaalCDefValTegRek
      when 2 then TotaalCBasisVal
      when 3 then TotaalCExtraVal
    end TotaalCAfdrukVal,
    case @TotalenAfdrukkenIn
      when 0 then SaldoDefValTegRek
      when 2 then SaldoBasisVal
      when 3 then SaldoExtraVal
    end SaldoAfdrukVal,
    isnull(sum(if IsCreditBoeking = 0 then Aantal endif), 0) TotaalDAantal,
    isnull(sum(if IsCreditBoeking = 1 then Aantal endif), 0) TotaalCAantal,
    (TotaalDAantal - TotaalCAantal) SaldoAantal
  from
    tabJournaalPost
    inner join tabJournaalRegel on (JrJpGid = JpGid)
  where
    JpBjGid = @BjGid and
    JrBjGid = @BjGid and
    // Definitief, voorlopig of beide
    ( (@SoortBoeking = 0 and RegelNummer is not null) or
      (@SoortBoeking = 1 and RegelNummer is null) or
      (@SoortBoeking = 2)
    ) and
    JpBoekGangGid = @BoekgangGid;


end;

// call rapBoekingsgangTotalen(2, 5, 968, 1, 3, 1);


create or replace procedure rapBtwOverzicht(  in @BjGid           Integer,
                                              in @SorterenOp      smallint, //0=DgbCode, 1=Dagboeksoort, OmsDagboek
                                              in @IsAscending     smallint, //0=Descending, 1=ascending
                                              in @VanDagboek      nchar(10),
                                              in @TotDagboek      nchar(10),
                                              in @VanMaand        smallint,
                                              in @TotMaand        smallint,
                                              in @VanBtwCode      integer,
                                              in @TotBtwCode      integer,
                                              in @DagboekSoort    nchar(6),
                                              in @VoorlDef        smallInt, //0=Definitief, 1=Voorlopig, 2=Voorlopig en definitief
                                              in @SoortBtw        smallint, //2=Te verrekenen, 1=Af te dragen, 0=Beide)
                                              in @Facturen        smallint, //0=Facturen, 1=Creditnota''s, 2=beide
                                              in @AutomKolom      smallint, //0=nee, 1=ja
                                              in @OverigeKolom    smallint,
                                              in @TotalenInValuta smallint, //0=nee, 1=ja (totalen in andere valuta)
                                              in @Valnummer       integer)
//Result .... laten staan, je krijgt anders fouten als deze stored proc wordt opgevoerd via KING (via scripts)
result (tmpRegelSoort integer,
        tmpBtwSoort integer,
        tmpBoekingSoort integer,
        tmpDgbCode nchar(10),
        tmpOmsDagboek nchar(40),
        tmpDagboekSoort integer,
        tmpBoekStukdatum date,
        tmpBoekdatum date,
        tmpBoekStuknummer numeric(10,0),
        tmpStukVolgnr integer,
        tmpRksInvoer nchar(28),
        tmpRksNaam nchar(40),
        tmpBedragIncl numeric(15,2),
        tmpBedragExcl numeric(15,2),
        tmpBtwBedrag numeric(15,2),
        tmpBtwCode integer,
        tmpBtwRekening nchar(28),
        tmpBtwPerc numeric(15,2),
        tmpCollectiefBedrag numeric(15,2),
        tmpOverigBedrag numeric(15,2),
        tmpSortering nchar(100),
        tmpBtwRubriekAangifte integer,
        tmpBtwPercentageAangifte numeric(15,2),
        tmpBtwBedragAangifte numeric(15,2),
        tmpReferentie nchar(40),
        tmpOmschrijving nchar(40),
        tmpDagboekOfBtwTotalen integer,
        tmpBerekendBtwPerc numeric(15,2),
        tmpValutaNummer integer,
        tmpValutaCode nchar(3)
       )
begin
  declare @HulpBjGid integer;
  declare @HulpPernr integer;
  declare @Koers     double;
  declare @VanPer    integer;
  declare @TotPer    integer;
  declare @BerekenRekSaldoViaSaldi smallint;

  declare local temporary table tmpBtwOverzicht(
     tmpGid                integer default AutoIncrement,
     tmpRegelSoort         integer,
     tmpSoortRegel         integer,
     tmpBoekingsoort       integer,
     tmpBoekdatum          date,
     tmpBoekStukdatum      date,
     tmpDgbCode            nchar(10),
     tmpOmsDagboek         nchar(40),
     tmpDagboekSoort       smallint,
     tmpBoekstukNummer     numeric(10,0),
     tmpStukVolgnr         integer,
     tmpRksGid             integer,
     tmpRksInvoer          nchar(28),
     tmpRksNaam            nchar(40),
     tmpBedragIncl         numeric(15,2),
     tmpBedragExcl         numeric(15,2),
     tmpBtwBedrag          numeric(15,2),
     tmpBtwCode            integer,
     tmpBtwSoort           smallint,
     tmpBtwRekening        nchar(28),
     tmpBtwPerc            numeric(15,2),
     tmpBtwRubriekAangifte integer,
     tmpBtwPercentageAangifte numeric(15,2),
     tmpBtwBedragAangifte  numeric(15,2),
     tmpCollectiefBedrag   numeric(15,2),
     tmpOverigBedrag       numeric(15,2),
     tmpReferentie         nchar(40),
     tmpOmschrijving       nchar(40),
     tmpSortering          nchar(100),
     tmpDagboekOfBtwTotalen integer,
     tmpBerekendBtwPerc numeric(15,2),
     tmpValutaNummer integer,
     tmpValutaCode nchar(3)
  ) on commit preserve rows;

  create index idx_tmpBtwOverzicht on tmpBtwOverzicht (tmpDgbCode, tmpBoekStuknummer);
  create index idx_tmpRegelSoort   on tmpBtwOverzicht (tmpRegelSoort);
  create index idx_tmpSortering    on tmpBtwOverzicht (tmpSortering, tmpRegelSoort, tmpBtwSoort);

  //call TraceBegin('rapBtwOverzicht > @BjGid='+string(@BjGid)+', @SorterenOp='+string(@SorterenOp)+', @IsAscending='+string(@IsAscending)+', @VanDagboek='+@VanDagboek+', @TotDagboek='+@TotDagboek);
  //call trace('rapBtwOverzicht > @VanMaand='+string(@VanMaand)+', @TotMaand='+string(@TotMaand)+', @VanBtwCode='+string(@VanBtwCode)+', @TotBtwCode='+string(@TotBtwCode)+', @DagboekSoort='+@DagboekSoort+', @VoorlDef='+string(@VoorlDef));
  //call trace('rapBtwOverzicht > @SoortBtw='+string(@SoortBtw)+', @Facturen='+string(@Facturen)+', @AutomKolom='+string(@AutomKolom)+', @OverigeKolom='+string(@OverigeKolom)+', @TotalenInValuta='+string(@TotalenInValuta)+', @Valnummer='+string(@Valnummer));

  //BoekingSoort  -> 0 Factuur    (Debiteur-debet of Crediteur-credit)
  //     of       -> 1 Creditnota (Debiteur-debet min of Crediteur-credit min)
  //tmpSoortRegel -> 2 Collectieve BTW-boeking
  //              -> 3 Overig

  insert into tmpBtwOverzicht(tmpRegelSoort,
                              tmpSoortRegel,
                              tmpBoekingSoort,
                              tmpBoekDatum,
                              tmpBoekStukdatum,
                              tmpDgbCode,
                              tmpOmsDagboek,
                              tmpDagboekSoort,
                              tmpBoekStuknummer,
                              tmpStukVolgnr,
                              tmpRksInvoer,
                              tmpRksNaam,
                              tmpBedragIncl,
                              tmpBtwSoort,
                              tmpBtwCode,
                              tmpBtwBedrag,
                              tmpBedragExcl,
                              tmpBtwRekening,
                              tmpBtwPerc,
                              tmpCollectiefBedrag,
                              tmpOverigBedrag,
                              tmpReferentie,
                              tmpOmschrijving,
                              tmpSortering,
                              tmpDagboekOfBtwTotalen)
  select 10,
        (if ((HulpRekBtwCode is not null) or (JrRksGid in (select BtwRksGid from tabBtw) and SoortBoeking = 0)) and (@SoortBtw = 0 or (select BtwSoort from tabBtw where BtwCode = HulpRekBtwCode)= @SoortBtw) then
            if JrBasisBedrag >= 0 then 0 else 1 endif
         else
            if exists(select 1 from tabBtw where BtwRksGid = JrRksGid and BtwCode between @VanBtwCode and @TotBtwCode and (@SoortBtw = 0 or (BtwSoort = @SoortBtw))) then 2 else 3 endif
         endif) tmpSoortRegel,  //Factuur, creditnota of overig
        (if (@Facturen = 2) or (tmpSoortRegel = @Facturen) or (tmpSoortRegel = 2) then tmpSoortRegel else 3 endif) tmpBoekingSoort, //Als factuur is en geen facturen af willen drukken of creditnota en geen creditnota''s af willen drukken, dan is het een overig bedrag
         JrBoekDatum,
         Boekdatum,
         JrDgbCode,
         OmsDagboek,
         DagboekSoort,
         JrBoekStukNummer,
         StukVolgnr,
         JrRksInvoer,
         RksNaam,
        (if (tmpBoekingsoort in (0,1)) and (HulpRekBtwCode between @VanBtwCode and @TotBtwCode) then
            if DefaultSoort in (6,7) then
               if IsCreditBoeking = 0 then
                  JrBasisBedrag
               else
                 -JrBasisBedrag
               endif
            else
               if IsCreditBoeking = 0 then   //Debet
                 -(JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif)
               else
                  (JrBasisBedrag) + (if HulpRekIsCredit = 0 then -HulpRekBasisBedrag else HulpRekBasisBedrag endif)
               endif
            endif
         endif) tmpBedragIncl,
        (if HulpRekBtwCode is null then (select first BtwSoort from tabBtw where BtwRksGid = JrRksGid) else (select BtwSoort from tabBtw where BtwCode = HulpRekBtwCode) endif) tmpBtwSoort,
        (if tmpBedragIncl is not null then HulpRekBtwCode endif) tmpBtwCode,
        (if tmpBedragIncl is not null then
           if HulpRekIsCredit = 0 then
             HulpRekBasisBedrag
           else
             -HulpRekBasisBedrag
           endif
         endif) tmpBtwBedrag,
        (if tmpBedragIncl is not null then -tmpBtwBedrag - tmpBedragIncl endif) tmpBedragExcl,
        (if tmpBedragIncl is not null then (select RksInvoer from tabRekeningschema a where a.RksGid = HulpRekRksGid) endif),
        (if tmpBedragIncl is not null then if tmpBedragExcl<>0 then abs(tmpBtwBedrag) / abs(tmpBedragExcl) * 100 else 0 endif endif),
        (if tmpBoekingSoort = 2 then if IsCreditBoeking = 0 then JrBasisBedrag else -JrBasisBedrag endif endif) tmpCollectiefBedrag,
        (if tmpBedragIncl is null and tmpCollectiefBedrag is null then if IsCreditBoeking = 0 then JrBasisBedrag else -JrBasisBedrag endif endif) tmpOverigBedrag,
         JrReferentie,
         OmsJournaalRegel,
        (case @SorterenOp
          when 0 then '' //Dagboekcode
           when 1 then string(DagboekSoort)
           when 2 then left(OmsDagboek+repeat(' ',40),40)
         end
         + left(DgbCode+'          ',10) + right('0000000000'+string(JrBoekStuknummer),10)+right('000'+string(StukVolgnr),3))
         + string(Boekdatum) + string(JrJpGid),  // Bug:35294 Sortering uitgebreid (max. karakters blijft onder de 100)
         0
  from  tabBoekingsgang
        inner join tabjournaalpost on (JpBoekgangGid = BoekgangGid)
        inner join tabDagboek on (DgbGid = JpDgbGid)
        inner join tabJournaalRegel on (JrJpGid = JpGid)
        inner join tabRekeningschema on (JrRksGid=RksGid)
        left outer join tabHulpRekening on (JrGid = HulpRekJrGid)
  where  BoekGangBjGid = @BjGid
    and JpBjGid=@BjGid
    and JrBjGid = @BjGid
    and JrDgbCode between @VanDagboek and @TotDagboek
    and DgbCode = JrDgbCode
    and Locate(@DagboekSoort, string(DagboekSoort))<>0
    and month(JrBoekDatum) between @VanMaand and @TotMaand
    and ( (@VoorlDef=0 and IsBoekGangDefinitief<>0) or
           (@VoorlDef=1 and IsBoekGangDefinitief =0) or
           (@VoorlDef=2)
         )
    and (@AutomKolom = 1 or (@AutomKolom = 0 and tmpCollectiefBedrag is null))
    and (@OverigeKolom = 1 or (@OverigeKolom = 0 and tmpOverigBedrag is null));

  //call Trace('rapBtwOverzicht > Einde insert');
  //call Trace('rapBtwOverzicht > Totalen per dagboek in basisvaluta');

  insert into tmpBtwOverzicht(tmpRegelSoort, tmpDgbCode, tmpOmsDagboek, tmpBedragIncl, tmpBtwBedrag, tmpBedragExcl, tmpCollectiefBedrag, tmpOverigBedrag, tmpSortering, tmpDagboekOfBtwTotalen)
  select 20,
         tmpDgbCode,
         OmsDagboek,
         isnull(sum(tmpBedragIncl),0),
         isnull(sum(tmpBtwBedrag),0),
         isnull(sum(tmpBedragExcl),0),
         isnull(sum(tmpCollectiefBedrag),0),
         isnull(sum(tmpOverigBedrag),0),
        (if @IsAscending = 1 then max(tmpSortering) else min(tmpSortering) endif),
        0
  from   tmpBtwOverzicht, tabDagboek
  where  DgbCode = tmpDgbCode
  group by tmpDgbCode, DgbCode, DagboekSoort, OmsDagboek;

  if @TotalenInValuta = 1 then
    //call Trace('Totalen per dagboek in opgegeven valuta');
    call BepaalBoekjaarEnPeriode (@@VerwerkingsDatum, @HulpBjGid, @HulpPerNr);

    select KoersTovBasisValuta (@HulpBjGid, @HulpPernr, @Valnummer) into @Koers;

    insert into tmpBtwOverzicht(tmpRegelSoort,
                                tmpDgbCode,
                                tmpBedragIncl,
                                tmpBtwBedrag,
                                tmpBedragExcl,
                                tmpCollectiefBedrag,
                                tmpOverigBedrag,
                                tmpSortering,
                                tmpDagboekOfBtwTotalen)
    select   21,
             tmpDgbCode,
             ValutaOmrekenen(@@BasisValutaNummer, tmpBedragIncl, @ValNummer, @HulpBjGid, @HulpPernr, 2),
             ValutaOmrekenen(@@BasisValutaNummer, tmpBtwBedrag, @ValNummer, @HulpBjGid, @HulpPernr, 2),
             ValutaOmrekenen(@@BasisValutaNummer, tmpBedragExcl, @ValNummer, @HulpBjGid, @HulpPernr, 2),
             ValutaOmrekenen(@@BasisValutaNummer, tmpCollectiefBedrag, @ValNummer, @HulpBjGid, @HulpPernr, 2),
             ValutaOmrekenen(@@BasisValutaNummer, tmpOverigBedrag, @ValNummer, @HulpBjGid, @HulpPernr, 2),
             tmpSortering,
             0
    from     tmpBtwOverzicht
    where    tmpRegelSoort = 20;
  end if;

  //call Trace('rapBtwOverzicht > Totalen per BTW-rekening in basisvaluta');
  insert into tmpBtwOverzicht(tmpRegelSoort,
                              tmpRksGid,
                              tmpBtwRekening,
                              tmpOmsDagboek,
                              tmpBtwPerc,
                              tmpBtwSoort,
                              tmpBtwCode,
                              tmpBedragIncl,
                              tmpBtwBedrag,
                              tmpBedragExcl,
                              tmpBtwRubriekAangifte,
                              tmpBtwPercentageAangifte,
                              tmpBtwBedragAangifte,
                              tmpSortering,
                              tmpDagboekOfBtwTotalen)
  select   30+(tmpBtwSoort-1)*2,
           RksGid,
           RksInvoer,
           RksNaam,
           BtwPercentage,
           BtwSoort,
           BtwCode,
           sum(tmpBedragIncl),
           sum(tmpBtwBedrag),
           sum(tmpBedragExcl),
           BtwRubriekAangifte,
           if BtwRubriekAangifte in (5,9,10) then IsNull(BtwPercentageAangifte,0) else BtwPercentage endif,
           if BtwRubriekAangifte in (5,9,10) then(IsNull(BtwPercentageAangifte,0) * sum(tmpBedragExcl))/100 else sum(tmpBtwBedrag) endif,
           repeat('Z',51)+cast(BtwSoort as nchar(1)) + right('00'+cast(BtwCode as nchar(3)),3) + RksInvoer,
           if ((30+(tmpBtwSoort-1)*2) < 40) then 1 else 2 endif
  from     tabBtw
           left outer join tmpBtwOverzicht on (BtwCode = tmpBtwCode and tmpRegelSoort = 10 )
           left outer join tabRekeningSchema on ( RksInvoer = tmpBtwRekening )
  where    BtwCode between @VanBtwCode and @TotBtwCode and
           ((BtwSoort = @SoortBtw) or (@SoortBtw = 0)) and
           tmpBtwSoort is not null
  group by tmpBtwSoort, BtwCode, RksNaam, BtwSoort, BtwPercentage, RksInvoer, RksNaam, RksGid, tmpBtwRekening, BtwRubriekAangifte, BtwPercentageAangifte;

  //call Trace('rapBtwOverzicht > Als voor de totalen geen BtwRekening is ingegeven, dan deze alsnog vullen');
  update tmpBtwOverzicht
  set    tmpBtwRekening = RksInvoer,
         tmpRksGid = RksGid,
         tmpOmsDagboek  = RksNaam
  from   tabBtw
  inner join tabRekeningSchema on BtwRksGid = RksGid
  where  BtwCode = tmpBtwCode and tmpRegelSoort = 30 and tmpBtwRekening is null;

  //call Trace('rapBtwOverzicht > Werkelijke saldo van de rekening (wordt in tmpCollectiefBedrag gezet!');
  //Alleen als 1e dag van 'van maand' op het begin van een periode valt *en* als laatste dag van 'tot maand' op de laatste dag van een periode valt, anders via journaal berekenen
  set @BerekenRekSaldoViaSaldi = 0;
  select PerNr into @VanPer from tabPeriode where day(Begindatum)=1 and month(Begindatum)=@VanMaand and PerBjGid = @BjGid;
  if @VanPer is not null then
    select PerNr into @TotPer from tabPeriode where month(Einddatum)<>month(dateadd(day,1,einddatum)) and month(Einddatum)=@TotMaand and PerBjGid = @BjGid;
    if @TotPer is not null then
      //Ok, hier de rekeningsaldi bepalen, maar alleen voor de eerste 'occurrance' van de rekening in de totalen
      set @BerekenRekSaldoViaSaldi = 1;
    end if;
  end if;

  if @BerekenRekSaldoViaSaldi = 1 then
    //werkelijke saldo=saldo van de perioden uit rekeningensaldi (gaat iets sneller dan via het journaal)
    update tmpBtwOverzicht buiten
    set    tmpCollectiefBedrag = ( select sum( if @VoorlDef=0 then (SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief)
                                                  else if @VoorlDef=1 then (SaldoDebetBasisVoorlopig  - SaldoCreditBasisVoorlopig)
                                                    else ((SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief) + (SaldoDebetBasisVoorlopig  - SaldoCreditBasisVoorlopig))
                                                  endif
                                                endif
                                              )
                                   from   tabrekeningsaldo
                                   where  RekSaldoRksGid = buiten.tmpRksGid
                                    and   RekSaldoBjGid  = @BjGid
                                    and   RekSaldoPerNr between @VanPer and @TotPer
                                 ) / if tmpRegelsoort in (30, 32) then 1 else @Koers endif
    where  not exists( select tmpGid
                       from   tmpBtwOverzicht binnen
                       where  binnen.tmpRegelSoort = buiten.tmpRegelSoort
                        and   binnen.tmpBtwRekening = buiten.tmpBtwRekening
                        and   binnen.tmpBtwCode < buiten.tmpBtwCode )
                        and   tmpRegelsoort in (30, 32, 40, 42);
  else
    //werkelijke saldo=totaal saldo volgens journaal
    update tmpBtwOverzicht buiten
    set    tmpCollectiefBedrag = ( select sum( if IsCreditBoeking = 1 then -1 else 1 endif * jrBasisBedrag )
                                   from   tabjournaalregel
                                   where  jrRksGid = buiten.tmpRksGid
                                    and   jrBjGid  = @BjGid
                                    and   month(jrBoekDatum) between @VanMaand and @TotMaand
                                 ) / if tmpRegelsoort in (30, 32) then 1 else @Koers endif
    where  not exists( select tmpGid
                       from   tmpBtwOverzicht binnen
                       where  binnen.tmpRegelSoort = buiten.tmpRegelSoort
                        and   binnen.tmpBtwRekening = buiten.tmpBtwRekening
                        and   binnen.tmpBtwCode < buiten.tmpBtwCode )
                        and   tmpRegelsoort in (30, 32, 40, 42);
  end if;

  //call Trace('rapBtwOverzicht > Te betalen of te ontvangen BTW apart optellen');
  insert into tmpBtwOverzicht(tmpRegelSoort, tmpBtwSoort, tmpBedragIncl, tmpBtwBedrag, tmpBedragExcl, tmpCollectiefBedrag, tmpBtwBedragAangifte, tmpSortering, tmpDagboekOfBtwTotalen)
  select   tmpRegelSoort+1,
           tmpBtwSoort,
           sum(tmpBedragIncl),
           sum(tmpBtwBedrag),
           sum(tmpBedragExcl),
           sum(tmpCollectiefBedrag),
           sum(tmpBtwBedragAangifte),
           max(tmpSortering)+string(tmpBtwSoort),
           1
  from     tmpBtwOverzicht
  where    tmpRegelSoort in (30,32)
  group by tmpBtwSoort, tmpRegelSoort;

  //call Trace('rapBtwOverzicht > Eindtotaal totalen BTW');

  insert into tmpBtwOverzicht(tmpRegelSoort, tmpBedragIncl, tmpBtwBedrag, tmpBedragExcl, tmpCollectiefBedrag, tmpSortering, tmpDagboekOfBtwTotalen)
  select   35,
           sum(tmpBedragIncl),
           sum(tmpBtwBedrag),
           sum(tmpBedragExcl),
           sum(tmpCollectiefBedrag),
           max(tmpSortering),
           1
  from     tmpBtwOverzicht
  where    tmpRegelSoort in (31,33);

  if @TotalenInValuta = 1 then
    //call Trace('Totalen per BTW-rekening in valuta');
    //Let op: dgbcode wordt hier gevuld zodat die een volgende pagina verwerkt!!
    insert into tmpBtwOverzicht(tmpRegelSoort, tmpRksGid, tmpBtwRekening, tmpOmsDagboek, tmpBtwPerc, tmpBtwSoort, tmpBtwCode,
                                tmpBedragIncl, tmpBtwBedrag, tmpBedragExcl, tmpCollectiefBedrag, tmpBtwRubriekAangifte, tmpBtwPercentageAangifte, tmpBtwBedragAangifte, tmpDgbCode, tmpSortering, tmpDagboekOfBtwTotalen)
    select   40 + (tmpBtwSoort-1)*2,
             tmpRksGid,
             tmpBtwRekening,
             tmpOmsDagboek,
             tmpBtwPerc,
             tmpBtwSoort,
             tmpBtwCode,
             tmpBedragIncl / @Koers,
             tmpBtwBedrag / @Koers,
             tmpBedragExcl / @Koers,
             tmpCollectiefBedrag / @Koers,
             tmpBtwRubriekAangifte,
             tmpBtwPercentageAangifte,
             tmpBtwBedragAangifte / @Koers,
             _U('Volgende'),
             tmpSortering,
             2
    from     tmpBtwOverzicht
    where    tmpRegelSoort in (30, 32);

    //call Trace('rapBtwOverzicht > Te betalen of te ontvangen BTW apart optellen');
    insert into tmpBtwOverzicht(tmpRegelSoort, tmpBedragIncl, tmpBtwBedrag, tmpBedragExcl, tmpCollectiefBedrag, tmpBtwBedragAangifte, tmpDgbCode, tmpSortering, tmpDagboekOfBtwTotalen)
    select   tmpRegelSoort+1,
             sum(tmpBedragIncl),
             sum(tmpBtwBedrag),
             sum(tmpBedragExcl),
             sum(tmpCollectiefBedrag),
             sum(tmpBtwBedragAangifte),
             tmpDgbCode,
             max(tmpSortering)+string(tmpBtwSoort),
             2
    from     tmpBtwOverzicht
    where    tmpRegelSoort in (40,42)
    group by tmpBtwSoort, tmpRegelSoort, tmpDgbCode;

    //call Trace('rapBtwOverzicht > Eindtotaal totalen BTW');
    insert into tmpBtwOverzicht(tmpRegelSoort, tmpBedragIncl, tmpBtwBedrag, tmpBedragExcl, tmpCollectiefBedrag, tmpDgbCode, tmpSortering, tmpDagboekOfBtwTotalen)
    select   45,
             sum(tmpBedragIncl),
             sum(tmpBtwBedrag),
             sum(tmpBedragExcl),
             sum(tmpCollectiefBedrag),
             tmpDgbCode,
             max(tmpSortering),
             2
    from     tmpBtwOverzicht
    where    tmpRegelSoort in (41, 43)
    group by tmpDgbCode;
  end if;

  update tmpBtwOverzicht
  set    tmpOmsDagboek = (select min(DgbCode) from tabDagboek where dgbcode >= @VanDagboek and Locate(@DagboekSoort, string(DagboekSoort))<>0)+' '+ _U('t/m') + ' ' +
                         (select max(DgbCode) from tabDagboek where dgbcode <= @TotDagboek and Locate(@DagboekSoort, string(DagboekSoort))<>0),
         tmpBtwSoort = 5 + if tmpBtwBedrag < 0 then 1 else 2 endif,
         tmpBtwBedrag = abs(tmpBtwBedrag)
  where  tmpRegelSoort in (35,45);

  update tmpBtwOverzicht
  set    tmpBerekendBtwPerc = (tmpBtwBedrag/tmpBedragExcl) * 100
  where  (tmpRegelSoort in (30, 32, 40, 42))
    and  (tmpBedragExcl <> 0);

  update tmpBtwOverzicht
  set    tmpSortering = if @IsAscending = 1 then
                          'zzzzzzzzzzz' + string(tmpRegelSoort) + tmpSortering
                        else
                          ''
                        endif
  where  (tmpRegelSoort >= 30);

  update tmpBtwOverzicht set tmpValutaNummer = if tmpRegelSoort in (21, 40, 41, 42, 43, 45) then @Valnummer else @@BasisValutaNummer endif;
  update tmpBtwOverzicht set tmpValutaCode = (select ValCode from tabValuta where ValNummer = tmpValutaNummer);

  // *** Resultaat teruggeven ***
  //call TraceEind('rapBtwOverzicht');
  if @IsAscending = 1 then
    select   tmpRegelSoort, tmpBtwSoort, tmpBoekingSoort, tmpDgbCode, tmpOmsDagboek, tmpDagboekSoort, tmpBoekStukdatum, tmpBoekdatum, tmpBoekStuknummer, tmpStukVolgnr, tmpRksInvoer, tmpRksNaam,
             tmpBedragIncl, tmpBedragExcl, tmpBtwBedrag, tmpBtwCode,
             tmpBtwRekening, tmpBtwPerc, tmpCollectiefBedrag, tmpOverigBedrag, tmpSortering,
             tmpBtwRubriekAangifte, tmpBtwPercentageAangifte, tmpBtwBedragAangifte,
             tmpReferentie, tmpOmschrijving, tmpDagboekOfBtwTotalen, tmpBerekendBtwPerc, tmpValutaNummer, tmpValutaCode
    from     tmpBtwOverzicht
    order by tmpSortering,
             tmpRegelSoort,
             tmpBtwSoort
  else
    select   tmpRegelSoort, tmpBtwSoort, tmpBoekingSoort, tmpDgbCode, tmpOmsDagboek, tmpDagboekSoort, tmpBoekStukdatum, tmpBoekdatum, tmpBoekStuknummer, tmpStukVolgnr, tmpRksInvoer, tmpRksNaam,
             tmpBedragIncl, tmpBedragExcl, tmpBtwBedrag, tmpBtwCode,
             tmpBtwRekening, tmpBtwPerc, tmpCollectiefBedrag, tmpOverigBedrag, tmpSortering,
             tmpBtwRubriekAangifte, tmpBtwPercentageAangifte, tmpBtwBedragAangifte,
             tmpReferentie, tmpOmschrijving, tmpDagboekOfBtwTotalen, tmpBerekendBtwPerc, tmpValutaNummer, tmpValutaCode
    from     tmpBtwOverzicht
    order by tmpSortering,
             tmpRegelSoort,
             tmpBtwSoort;
  end if;

end;
//call rapBtwOverzicht(1, 0, 1, 'Bank', 'ZZZZ', 1, 12, 0, 6, '12345', 0, 2, 0, 0, 0, 1, 0)


create or replace procedure rapBudgetPerBalansCode(
in @BlCode            integer,
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @VanRubParSub      nchar(40), //!van nummer/zoekcode/naam
in @TotRubParSub      nchar(40), //!t/m nummer/zoekcode/naam
in @SoortBoeking      smallint, //0=definitief, 1=voorlopig, 2=beide
in @OokZonderbudget   smallint, //0=Nee (alleen rekeningen met budget), 1=Ja
in @VergelijkMet      smallint, //4=Zoals bij budget, 3=Default-boekzijde, 0=Saldo, 1=Debet, 2=Credit
in @ComprimeerBalans  smallint, //0=nee, 1=alleen rubrieken+paragrafen, 2=alleen rubrieken
in @OverzichtInValuta integer)  //!Valutanummer waarin bedragen moeten worden afgedrukt

result (RegelSoort integer, RubParSub nchar(11), Oms nchar(40), BudgetBedrag numeric(15,2), SaldoBedrag numeric(15,2), VerschilBedrag numeric(15,2), VerschilPerc numeric(6,2), OptelstreepBoven smallint, DubbelStreepBoven smallint, JaarBudgetBedrag numeric(15,2), BudgetCode integer, BudgetOms nchar(40))
begin

  declare @Koers             double;
  declare @Nivo              smallint; // 10=Rubriek, 20 = Paragraaf, 30 = Subparagraaf
  declare @NietVerbijzonderd nchar(40); // Tekst die in de balans wordt gebruikt als omschrijving van de niet-verbijzonderde bedragen
  declare @ErrorText         nchar(250);
  declare @TestLengte        smallint; // t.b.v. bepalen welk deel van RubparSub moet worden getest (is bij normale balans anders!)

  declare local temporary table tmpBudget(
    Sortering                    integer,
    nivo                         smallint,
    Oms                          nchar(40),
    Rub                          nchar(3),
    Par                          nchar(3),
    Sub                          nchar(3),
    Uitgesplitst                 smallint,
    JaarbudgetBedrag             numeric(15,2),
    JaarbudgetBedragOnderliggend numeric(15,2),
    BudgetBedrag                 numeric(15,2),
    BudgetTotaalOnderliggend     numeric(15,2),   // Is het bedrag dat bij budget moet worden opgeteld; berekend uit alles wat dieper is
    WerkelijkBedrag              numeric(15,2) default 0,
    tmpBlGid                     integer,
    OptelstreepBoven             smallint default 0,
    DubbelStreepOnder            smallint default 0
  ) on commit preserve rows;

  set @ErrorText = 'rapBudgetPerBalansCode -> ';
  set @@ErrorTextProcedure = @ErrorText + '(@BlCode='+string(@BlCode)+', @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @VanRubParSub='+@VanRubParSub+', @TotRubParSub='+@TotRubParSub+', @SoortBoeking='+string(@SoortBoeking)+', @OokZonderbudget='+string(@OokZonderbudget)+', @VergelijkMet='+string(@VergelijkMet)+', @ComprimeerBalans='+string(@ComprimeerBalans)+', @OverzichtInValuta='+string(@OverzichtInValuta)+')';
  //call traceBegin(@@ErrorTextProcedure);

  // *** Initieren variabelen
  select KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta) into @Koers;         // Koers bepalen
  set @TotRubParSub = @TotRubParSub + if @BlCode = 0 then '99999' else '.999.999' endif; // Zorg ervoor dat de t/m goed gaat
  set @NietVerbijzonderd = _U('Niet verbijzonderd');                                         // Tekst in de omschrijving voor de niet-verbijzonderd-regel


  // *** Toevoegen rub/par/sub ***
  // -----------------------------

  // Rubrieken toevoegen
  set @@ErrorTextProcedure = @ErrorText + 'Toevoegen rubrieken';
  //call trace(@@ErrorTextProcedure);
  set @TestLengte = if @BlCode = 0 then 1 else 3 endif;
  insert into tmpBudget(Nivo, Oms, Rub, Uitgesplitst, tmpBlGid)
  select
   10, OmsBalanscodeDetails, Rubriek, if @ComprimeerBalans = 2 then 0 else 1 endif, BlGid
  from
   tabbalanscodedetail
  where
       detailblcode = @BlCode
   and Paragraaf =''
   and Rubriek between left(@VanRubParSub, @TestLengte) and left(@TotRubParSub, @TestLengte);

  // Paragrafen toevoegen
  set @@ErrorTextProcedure = @ErrorText + 'Toevoegen paragrafen';
  //call trace(@@ErrorTextProcedure);
  set @TestLengte = if @BlCode = 0 then 2 else 7 endif;
  insert into tmpBudget(Nivo, Oms, Rub, Par, Uitgesplitst, tmpBlGid)
  select
   20, OmsBalanscodeDetails, Rubriek, Paragraaf, if @ComprimeerBalans = 0 then 1 else 0 endif, BlGid
  from
   tabbalanscodedetail,
   tmpBudget
  where
    Nivo = 10
    and detailblcode = @BlCode
    and Rubriek = Rub
    and isnull(Paragraaf,'') <> ''
    and isnull(SubParagraaf,'') = ''
   and if @BlCode = 0 then Paragraaf else rub + '.' + Paragraaf endif between left(@VanRubParSub, @TestLengte) and left(@TotRubParSub, @TestLengte);

  // Subparagrafen toevoegen
  set @@ErrorTextProcedure = @ErrorText + 'Toevoegen subparagrafen';
  //call trace(@@ErrorTextProcedure);
  insert into tmpBudget(Nivo, Oms, Rub, Par, Sub, Uitgesplitst, tmpBlGid)
  select
   30, OmsBalanscodeDetails, Rubriek, Paragraaf, Subparagraaf, 0, BlGid
  from
   tabbalanscodedetail,
   tmpBudget
  where
    Nivo = 20
    and detailblcode = @BlCode
    and Rubriek = Rub
    and Paragraaf = Par
    and SubParagraaf <> ''
    and if @BlCode = 0 then par + SubParagraaf else rub + '.' + par +'.' + SubParagraaf endif between @VanRubParSub and @TotRubParSub;


  // *** Index aan de tabel toevoegen ***
  // ------------------------------------
  create index idx_tmpBudgetNivo on tmpBudget (nivo, rub, par, sub);


  // *** Berekenen van de budgetbedragen van de balanscodes ***
  // ----------------------------------------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Bereken budgetbedragen';
  //call trace(@@ErrorTextProcedure);

  update tmpBudget
  set    BudgetBedrag =
                        IsNull((if BudMetVerdeling = 1 then
                                  (select sum((Bud_PercAfronden(BudPerPercentage) * Bud.Jaarbudget / 100)) from tabBudget Bud inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid) and (BudPerNr between @VanPernr and @TotPernr) and (BudPerBudgetCode = Bud.BudBudgetCode) where Bud.BudgetGid = BuitenBudget.BudgetGid)
                                else
                                   (select sum(BudBedrag) from tabBudgetBedrag where (BudBedrBudgetGid = BuitenBudget.BudgetGid) and (BudBedrPerNr between @VanPernr and @TotPernr))
                                endif) / @Koers, 0),
         JaarbudgetBedrag = if BudMetVerdeling = 1 then
                              Jaarbudget
                            else
                              (select sum(BudBedrag) from tabBudgetBedrag where (BudBedrBudgetGid = BudgetGid))
                            endif / @Koers
  from
    tabBudget BuitenBudget
  where
    BudBlGid = tmpBlGid and BudBjGid = @BjGid;


  // *** Berekening van budget- en saldibedragen van de gekoppelde rekeningen ***
  // ----------------------------------------------------------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Rekeningsaldi toevoegen';
  //call trace(@@ErrorTextProcedure);
  update tmpBudget
  set BudgetTotaalOnderliggend =
   (select sum(
    IsNull((if BudMetVerdeling = 1 then
              (select sum((Bud_PercAfronden(BudPerPercentage) * Bud.Jaarbudget / 100)) from tabBudget Bud inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid) and (BudPerNr between @VanPernr and @TotPernr) and (BudPerBudgetCode = Bud.BudBudgetCode) where Bud.BudgetGid = tabBudget.BudgetGid)
            else
               (select sum(BudBedrag) from tabBudget Bud inner join tabBudgetBedrag on (Bud.BudgetGid = BudBedrBudgetGid) and (BudBedrPerNr between @VanPernr and @TotPernr) where Bud.BudgetGid = tabBudget.BudgetGid)
            endif) *
            /* positief indien DEBET-rekening, Negatief indien CREDIT-rekening */
            (case DefaultBoekzijde
             when 3 /* afhankelijk van dagboek */ then if DefaultSoort in (2, 5, 7) /* passiva, opbrengsten of crediteur */ then -1 /*CREDIT*/ else 1 /*DEBET*/ endif
             when 2 /* geen voorkeur */ then 1 /*DEBET*/
             when 1 /* credit */ then -1       /*CREDIT*/
             when 0 /* debet */ then 1         /*DEBET*/
             else   /* voor de zekerheid */ 1  /*DEBET*/
             end
            ) / @Koers, 0)
           )
    from tabBudget
         inner join tabBalansCodeRekening on (BlRekBlCode = @BlCode and BlRekBlGid = tmpBlGid)
         inner join tabRekeningschema on (RksGid = BlRksGid)
    where     (BudBjGid  = @BjGid)   // Budget van het huidige jaar
          and (BudRksGid = BlRksGid) // Alleen budgetten van de rekeningen
   ),
   JaarbudgetBedragOnderliggend =
     (select sum(if BudMetVerdeling = 1 then Jaarbudget else BudBedrag endif  *
            /* positief indien DEBET-rekening, Negatief indien CREDIT-rekening */
            (case DefaultBoekzijde
             when 3 /* afhankelijk van dagboek */ then if DefaultSoort in (2, 5, 7) /* passiva, opbrengsten of crediteur */ then -1 /*CREDIT*/ else 1 /*DEBET*/ endif
             when 2 /* geen voorkeur */ then 1 /*DEBET*/
             when 1 /* credit */ then -1       /*CREDIT*/
             when 0 /* debet */ then 1         /*DEBET*/
             else   /* voor de zekerheid */ 1  /*DEBET*/
             end
            ) / @Koers)
        from tabBudget
             inner join tabBalansCodeRekening on (BlRekBlCode = @BlCode and BlRekBlGid = tmpBlGid)
             inner join tabRekeningschema on (RksGid = BlRksGid)
             left outer join tabBudgetBedrag on (BudBedrBudgetGid = BudgetGid )
        where     (BudBjGid  = @BjGid)   // Budget van het huidige jaar
              and (BudRksGid = BlRksGid) // Alleen budgetten van de rekeningen
     ),
   WerkelijkBedrag =
    if @BlCode = 0 then
      // Normale balans -> rekeningen opzoeken middels rekeningnummer vergelijken met balanscode
      (select sum(case (if @VergelijkMet = 4 then if VergelijkenMet is not null then VergelijkenMet else 0 endif else @VergelijkMet endif)
                    when 0 then //Saldo
                      case @SoortBoeking
                        when 0 then //Definitief
                          SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig) - (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)
                        end
                    when 1 then  //Debet
                      case @SoortBoeking
                        when 0 then //Definitief
                          SaldoDebetBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoDebetBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig)
                        end
                    when 2 then  //Credit
                      case @SoortBoeking
                        when 0 then //Definitief
                         SaldoCreditBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoCreditBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)
                        end
                    //when 3=default-boekzijde kan niet voor een balanscodebudget
                  end) / @koers
       from              tabRekeningschema
              inner join tabRekeningSaldo on (RekSaldoRksGid = RksGid)
              left outer join tabBudget             on (BudBjGid    = @BjGid  and BudBlGid  = tmpBlGid) // Dit is het budget van de balanscode!
       where      (RekSaldoBjGID  = @BjGid)
              and (RekSaldoPerNr between @VanPerNr and @TotPerNr)
              and (RksInvoer like if isnull(par,'')='' then isnull(rub,'') else isnull(par,'') endif + isnull(sub,'') +'%')
      )

    else
      // Variabele balans -> rekeningen opzoeken middels tabBalansCodeRekening
      (select sum(case (if @VergelijkMet = 4 then if VergelijkenMet is not null then VergelijkenMet else 0 endif else @VergelijkMet endif)
                    when 0 then //Saldo
                      case @SoortBoeking
                        when 0 then //Definitief
                          SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig) - (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)
                        end
                    when 1 then  //Debet
                      case @SoortBoeking
                        when 0 then //Definitief
                          SaldoDebetBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoDebetBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig)
                        end
                    when 2 then  //Credit
                      case @SoortBoeking
                        when 0 then //Definitief
                         SaldoCreditBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoCreditBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)
                        end
                    //when 3=default-boekzijde kan niet voor een balanscodebudget
                  end) / @koers
       from              tabRekeningSaldo
              inner join tabBalansCodeRekening on (BlRekBlCode = @BlCode and BlRekBlGid = tmpBlGid and BlRksgid = ReksaldoRksgid)
              left outer join tabBudget             on (BudBjGid    = @BjGid  and BudBlGid  = tmpBlGid) // Dit is het budget van de balanscode!
       where      (RekSaldoBjGID  = @BjGid)
              and (RekSaldoPerNr between @VanPerNr and @TotPerNr)
      )
    endif
   from tmpBudget;


  // *** Lege budgetregels vullen met totaal onderliggend budget ***
  // ---------------------------------------------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Onderliggend totaal als budget gebruiken';
  //call trace(@@ErrorTextProcedure);
  set @Nivo = 30; // vanaf paragraaf omhoog tellen
  while @Nivo > 0 LOOP

    // ACW bug 26292: Bij normale balans zijn hier de werkelijke bedragen al keurig aan de sub/par/rub toegevoegd, dus NIET nogmaals doen
    //                Bij de var.balansen is dit nog niet gebeurd, dus alsnog zo doen!
    update tmpBudget Hoger
    set BudgetTotaalOnderliggend     = isnull(BudgetTotaalOnderliggend,    0) + isnull(TotaalBudget,     0),
        JaarbudgetBedragOnderliggend = isnull(JaarbudgetBedragOnderliggend,0) + isnull(TotaalJaarBudget, 0),
        WerkelijkBedrag              = isnull(WerkelijkBedrag,             0) + if @BlCode = 0 then 0 else isnull(TotaalWerkelijk,  0) endif
    from tmpBudget Hoger,
         (select dieper.rub drub,
                 if @nivo in (20,30) then dieper.par else '-' endif dpar,               // Rub/Par teruggeven
                 sum(isnull(dieper.BudgetBedrag,     0)) TotaalBudget,                  // Totaal onderliggend budget voor de paragraaf resp. rubriek
                 sum(isnull(dieper.JaarBudgetBedrag, 0)) TotaalJaarBudget,              // Totaal onderliggend jaarbudget voor de paragraaf resp. rubriek
                 sum(isnull(dieper.WerkelijkBedrag,  0)) TotaalWerkelijk                // Totaal onderliggend werkelijk saldo voor de paragraaf resp. rubriek
          from   tmpBudget dieper
          where   nivo = @nivo + 10                                                     // Zie je wel? Totaal op 1 nivo dieper
          group by drub, dpar
         ) dieper
    where     (nivo = @nivo)                                                            // Per nivo berekenen i.v.m. doorrekenen!
          and (drub = rub)                                                              // En de rubriek moet gelijk zijn
          and (dpar = isnull(par,'-'));                                                 // Paragraaf is leeg als het een totaal van alles in een rubriek betreft


    // Voor alle balanscodes die zelf geen budget hebben het totaal onderliggend budgetbedrag als budgetbedrag gebruiken
    update tmpBudget
    set BudgetBedrag     = BudgetTotaalOnderliggend,
        JaarBudgetBedrag = JaarbudgetBedragOnderliggend
    where BudgetBedrag is null
          and nivo = @nivo
          and BudgetTotaalOnderliggend <> 0;

    set @nivo = @nivo - 10;
  END LOOP;


  // *** Verwijder regels zonder budget als die niet afgedrukt worden ***
  // --------------------------------------------------------------------

  if @OokZonderbudget = 0 then
    set @@ErrorTextProcedure = @ErrorText + 'Budgetloze regels verwijderen';
    //call trace(@@ErrorTextProcedure);
    delete tmpBudget where BudgetBedrag is null;
  end if;

  // Ok, nu het verschil bekijken en in de extra regel zetten
  set @@ErrorTextProcedure = @ErrorText + 'Verschillen in de Niet-Verbijzonderd-regel zetten';
  //call trace(@@ErrorTextProcedure);
  set @nivo = 21;
  WHILE @nivo > 1 LOOP
    insert into tmpBudget(Nivo, Oms, Rub, Par, sub, Uitgesplitst, BudgetBedrag, JaarBudgetBedrag, WerkelijkBedrag)
    select @nivo, @NietVerbijzonderd,
           Rub, if @nivo >= 20 then Par else '_NV' endif, if @nivo >= 30 then sub else '_NV' endif, 0,
           isnull(BudgetBedrag, 0)     - isnull(BudgetTotaalOnderliggend, 0),
           isnull(JaarBudgetBedrag, 0) - isnull(JaarbudgetBedragOnderliggend, 0),
            // Werkelijke bedrag dat al bij hetzelfde nivo staat
            WerkelijkBedrag
            // Totale werkelijke bedrag dat al bij het niveau dieper staat
            - isnull((select sum(binnen.WerkelijkBedrag) from tmpBudget binnen
                      where      (binnen.nivo = @nivo + 9)
                             and (binnen.rub=buiten.rub)
                             and (binnen.par is not null)
                             and (   (@nivo = 21 and binnen.par = buiten.par and binnen.sub is not null)
                                  or (@nivo <> 21)
                                 )
                     ),0) TotaalWerkelijkBedrag
    from tmpBudget buiten
    where     (   (BudgetTotaalOnderliggend <> BudgetBedrag)  // Alleen als bedrag niet overeenkomt
               or (JaarBudgetBedrag <> JaarbudgetBedragOnderliggend)
               or TotaalWerkelijkBedrag <> 0
              )
          and (nivo = @nivo - 1);
    set @nivo = @nivo - 10;

  END LOOP;



  //ACW/PG 18-08-2010: Deze code toch weer geactiveerd. Waarschijnlijk was dit weg om de klanten die slechts rubrieken en paragrafen
  //                   hebben en dus niet per paragraaf een NietVerbijzonderd regel willen.
  //                   Deze klanten dienen in het voorloopvenster het veld Specificeren op te wijzigen in Paragraaf.
  //                   Zie bug 30329.
  //                   Daarom ook comprimeren onder deze routine verplaatst, zodat de extra NV-regel niet wordt getoond,
  //                   terwijl het totaal ervan wel op een hoger niveau is meegerekend.
  // De niet-verbijzonderd-regel toevoegen van niveaus waarvoor geen dieper niveau is BEHALVE het diepste niveau
  set @@ErrorTextProcedure = @ErrorText + 'Niet-verbijzonderd-regels toevoegen als er geen dieper niveau meer is';
  //call trace(@@ErrorTextProcedure);
  insert into tmpBudget(Nivo, Oms, Rub, Par, sub, Uitgesplitst, BudgetBedrag, WerkelijkBedrag, JaarBudgetBedrag)
  select nivo + 1, @NietVerbijzonderd,
         Rub, if nivo >= 20 then Par else '_NV' endif, if nivo >= 30 then sub else '_NV' endif, 0,
         BudgetBedrag,
         WerkelijkBedrag,
         JaarBudgetBedrag
  from   tmpBudget buiten
  where      (   (nivo = 10 and @ComprimeerBalans <> 2) // 0=nee, 1=alleen rubrieken+paragrafen, 2=alleen rubrieken
              or (nivo = 20 and @ComprimeerBalans = 0)
             )
         and (not exists( select 1
                          from tmpBudget binnen
                          where     (binnen.rub = buiten.rub)
                                and (   (buiten.nivo = 10 and binnen.par is not null)
                                     or (buiten.nivo > 10 and binnen.par = buiten.par)
                                    )
                                and (   (buiten.nivo = 20 and binnen.sub is not null)
                                     or (buiten.nivo <> 20)
                                    )
                        )
             );

  // *** Comprimeren ***
  // -------------------
  if @ComprimeerBalans in (1,2) then
    // Alle subparagrafen en dieper verwijderen van niet-uitgesplitste rubrieken
    set @@ErrorTextProcedure = @ErrorText + 'Verwijder alle subparagrafen van verzamelde paragrafen';
    //call trace(@@ErrorTextProcedure);
    delete tmpBudget
    where nivo > 20;
    //De WHERE hieronder is niet nodig; wordt gebruikt als verzamelen dynamisch gebeurt o.b.v. instellingen in de balanscode
    //where     Rub in (Select Rub from tmpBudget where uitgesplitst = 0 and par is null)   // Alles in de rubriek
    //      and par is not null;                                                        // Behalve de rubriek-regel zelf
  end if;
  if @ComprimeerBalans = 2 then
    // Alle paragrafen verwijderen van niet-uitgesplitste paragrafen
    set @@ErrorTextProcedure = @ErrorText + 'Verwijder alle paragrafen van verzamelde rubrieken';
    //call trace(@@ErrorTextProcedure);
    delete tmpBudget
    where nivo > 10;
    //De WHERE hieronder is niet nodig; wordt gebruikt als verzamelen dynamisch gebeurt o.b.v. instellingen in de balanscode
    //where Rub+Par in (Select Rub+Par from tmpBudget where uitgesplitst = 0 and sub is null) // Alles in de paragraaf
    //      and Sub is not null;                                                              // Behalve de paragraaf-regel zelf
  end if;



  // *** Sortering ***
  // -----------------

  set @@ErrorTextProcedure = @ErrorText + 'Sortering';
  //call trace(@@ErrorTextProcedure);
  update tmpBudget
  set    Sortering = number(),
//         oms = string(nivo)+'|'+rub+'.'+par+'.'+sub+'|'+oms,
         nivo = ((nivo+9)/10) * 10
  from   tmpBudget
  order by Rub,
           if Par is null then 'BBB' else if Par = '_NV' then 'AAA' else Par endif endif,
           if Sub is null then 'BBB' else if Sub = '_NV' then 'AAA' else Sub endif endif,
           nivo;


  // *** Totaal generaal ***
  // -----------------------

  set @@ErrorTextProcedure = @ErrorText + 'Totaal generaal';
  //call trace(@@ErrorTextProcedure);
  if exists(select first 1 from tmpBudget) then
    insert into tmpBudget(Sortering, Nivo, Oms, Rub, Uitgesplitst, BudgetBedrag, WerkelijkBedrag, JaarbudgetBedrag, DubbelStreepOnder)
    select (select max(Sortering) from tmpBudget) + 1, 99, '', '', 1, sum(BudgetBedrag), sum(WerkelijkBedrag), sum(JaarbudgetBedrag), 0
    from   tmpBudget
    where  nivo = 10;
  end if;



  // *** Optelstrepen etc. ***
  // -------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Optel- en totaalstrepen';
  //call trace(@@ErrorTextProcedure);
  // Dubbele streep indien de regel hieronder van een dieper nivo is (bijv. Paragraaf onder Rubriek)
  set @nivo = 30;
  WHILE @nivo > 0 LOOP
    update tmpBudget buiten
    set DubbelStreepOnder = 1
    where nivo < (select binnen.nivo from tmpBudget binnen where binnen.sortering = buiten.sortering + 1)
          and nivo = @nivo;

    // Enkele streep als de regel hierboven geen dubbele streep heeft en van een dieper nivo is (bijv. Paragraaf boven Rubriek)
    update tmpBudget buiten
    set OptelstreepBoven  = 1,
        DubbelStreepOnder = 1
    where     nivo < (select binnen.nivo from tmpBudget binnen where binnen.sortering = buiten.sortering - 1 and binnen.DubbelStreepOnder = 0)
          and nivo = @nivo;
    set @nivo = @nivo - 10;
  end LOOP;


  // *** KLAAR ***
  // -------------

  set @@ErrorTextProcedure = @ErrorText + 'einde';
  //call traceEind(@@ErrorTextProcedure);

  select   nivo RegelSoort,
           if @BlCode = 0 then
             if Par = '_NV' or Par is null then Rub else Par+ if sub is null or sub = '_NV' then '' else Sub endif endif
           else
             (Rub + if Par is null or Par = '_NV' then '' else '.'+Par+ if sub is null or sub = '_NV' then '' else '.'+Sub endif endif)
           endif RubParSub,
           Oms,
           isnull(BudgetBedrag,0),
           isnull(WerkelijkBedrag,0) SaldoBedrag,
           isnull(WerkelijkBedrag,0) - isnull(BudgetBedrag,0) VerschilBedrag,
           if BudgetBedrag <> 0 then (isnull(WerkelijkBedrag,0) - BudgetBedrag) / BudgetBedrag * 100 endif VerschilPerc,
           OptelstreepBoven,
           DubbelStreepOnder DubbelStreepBoven,
           JaarBudgetBedrag,
           BudgetCode,
           BudgetOms
  from     tmpBudget
           left outer join tabBudget on (BudBlGid = tmpBlGid and BudBjGid = @BjGid)
           left outer join tabBudgetCode on BudgetCode = BudBudgetCode
  order by Sortering;


end;

//call rapBudgetPerBalansCode( 0, 2, 1, 12, '', '999.999.999', 2, 1, 0, 0, 0);


create or replace procedure rapBudgetPerBalansCodePeriodeNaast(
in @BlCode            integer,
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @VanRubParSub      nchar(40), //!van nummer/zoekcode/naam
in @TotRubParSub      nchar(40), //!t/m nummer/zoekcode/naam
in @SoortBoeking      smallint, //0=definitief, 1=voorlopig, 2=beide
in @OokZonderbudget   smallint, //0=Nee (alleen rekeningen met budget), 1=Ja
in @VergelijkMet      smallint, //4=Zoals bij budget, 3=Default-boekzijde, 0=Saldo, 1=Debet, 2=Credit
in @ComprimeerBalans  smallint, //0=nee, 1=alleen rubrieken+paragrafen, 2=alleen rubrieken
in @OverzichtInValuta integer,  //!Valutanummer waarin bedragen moeten worden afgedrukt
in @PlusMin1          numeric(6,2),//% voor +  of -
in @PlusMin2          numeric(6,2))//% voor ++ of --

result (RegelSoort integer, RubParSub nchar(11), Oms nchar(40), BudgetBedrag numeric(15,2), SaldoBedrag numeric(15,2), VerschilBedrag numeric(15,2), VerschilPerc numeric(6,2), OptelstreepBoven smallint, DubbelStreepBoven smallint,
        periode01 nchar(2), periode02 nchar(2), periode03 nchar(2), periode04 nchar(2), periode05 nchar(2), periode06 nchar(2), periode07 nchar(2), periode08 nchar(2), periode09 nchar(2), periode10 nchar(2), periode11 nchar(2), periode12 nchar(2), periode13 nchar(2))
begin

  declare @Koers             double;
  declare @Nivo              smallint; // 10=Rubriek, 20 = Paragraaf, 30 = Subparagraaf
  declare @NietVerbijzonderd nchar(40); // Tekst die in de balans wordt gebruikt als omschrijving van de niet-verbijzonderde bedragen
  declare @ErrorText         nchar(250);
  declare @TestLengte        smallint; // i.v.m. normale balans aangeven welke lengte moet worden gecontroleerd bij RubParSub-vergelijkingen

  declare local temporary table tmpBudget(
    tmpGid                       integer default autoincrement,
    Sortering                    integer,
    nivo                         smallint,
    Oms                          nchar(40),
    Rub                          nchar(3),
    Par                          nchar(3),
    Sub                          nchar(3),
    Uitgesplitst                 smallint,
//    JaarbudgetBedrag             numeric(15,2),    // *** Jaarbudget is hier overal gekwoot; wordt in de layout NIET gebruikt!!
//    JaarbudgetBedragOnderliggend numeric(15,2),
    BudgetBedrag                 numeric(15,2),
    BudgetTotaalOnderliggend     numeric(15,2),   // Is het bedrag dat bij budget moet worden opgeteld; berekend uit alles wat dieper is
    WerkelijkBedrag              numeric(15,2) default 0,
    tmpBlGid                     integer,
    OptelstreepBoven             smallint default 0,
    DubbelStreepOnder            smallint default 0
  ) on commit preserve rows;

  declare local temporary table tmpPeriode(
    perTmpGid                   integer,
    perPerNr                    integer,
    perBudgetBedrag             numeric(16,4),                // Let op: 2 extra decimalen i.v.m. afrondingen van het jaarbedrag!
    perBudgetTotaalOnderliggend numeric(16,4),   // Is het bedrag dat bij budget moet worden opgeteld; berekend uit alles wat dieper is
    perWerkelijkBedrag          numeric(15,2) default 0,
    perVerschilPerc             numeric(15,2),  // Let op: GEEN 6,2 i.v.m. te grote percentages!!
    perPlusMinTeken             nchar(2)
  ) on commit preserve rows;


  // *** ErrorText zetten ***
  // ------------------------

  set @ErrorText = 'rapBudgetPerBalansCodePeriodeNaast -> ';
  set @@ErrorTextProcedure = @ErrorText + '(@BlCode='+string(@BlCode)+', @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @VanRubParSub='+@VanRubParSub+', @TotRubParSub='+@TotRubParSub+', @SoortBoeking='+string(@SoortBoeking)+', @OokZonderbudget='+string(@OokZonderbudget)+', @VergelijkMet='+string(@VergelijkMet)+', @ComprimeerBalans='+string(@ComprimeerBalans)+', @OverzichtInValuta='+string(@OverzichtInValuta)+', @PlusMin1=' + string(@PlusMin1)+', @PlusMin2='+string(@PlusMin2) + ')';
  //call traceBegin(@@ErrorTextProcedure);


  // *** Initieren variabelen ***
  // ----------------------------

  select KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta) into @Koers;          // Koers bepalen
  set @TotRubParSub = @TotRubParSub + if @BlCode = 0 then '999999' else '.999.999' endif; // Zorg ervoor dat de t/m goed gaat
  set @NietVerbijzonderd = _U('Niet verbijzonderd');                                      // Tekst in de omschrijving voor de niet-verbijzonderd-regel
  if @VanPerNr > 13 then
    set @VanPerNr = 13   // We kunnen toch maar 13 periodes aan, dus ook niet meer berekenen!
  end if;
  if @TotPerNr > 13 then
    set @TotPerNr = 13   // We kunnen toch maar 13 periodes aan, dus ook niet meer berekenen!
  end if;


  // *** Toevoegen rub/par/sub ***
  // -----------------------------

  // --- Rubrieken toevoegen
  set @@ErrorTextProcedure = @ErrorText + 'Toevoegen rubrieken';
  //call trace(@@ErrorTextProcedure);
  set @TestLengte = if @BlCode = 0 then 1 else 3 endif;
  insert into tmpBudget(Nivo, Oms, Rub, Uitgesplitst, tmpBlGid)
  select
   10, OmsBalanscodeDetails, Rubriek, if @ComprimeerBalans = 2 then 0 else 1 endif, BlGid
  from
   tabbalanscodedetail
  where
       detailblcode = @BlCode
   and Paragraaf =''
   and Rubriek between left(@VanRubParSub, @TestLengte) and left(@TotRubParSub, @TestLengte);

  // --- Paragrafen toevoegen
  set @@ErrorTextProcedure = @ErrorText + 'Toevoegen paragrafen';
  //call trace(@@ErrorTextProcedure);
  set @TestLengte = if @BlCode = 0 then 2 else 7 endif;
  insert into tmpBudget(Nivo, Oms, Rub, Par, Uitgesplitst, tmpBlGid)
  select
   20, OmsBalanscodeDetails, Rubriek, Paragraaf, if @ComprimeerBalans = 0 then 1 else 0 endif, BlGid
  from
   tabbalanscodedetail,
   tmpBudget
  where
    Nivo = 10
    and detailblcode = @BlCode
    and Rubriek = Rub
    and isnull(Paragraaf,'') <> ''
    and isnull(SubParagraaf,'') = ''
   and if @BlCode = 0 then Paragraaf else rub + '.' + Paragraaf endif between left(@VanRubParSub, @TestLengte) and left(@TotRubParSub, @TestLengte);

  // --- Subparagrafen toevoegen
  set @@ErrorTextProcedure = @ErrorText + 'Toevoegen subparagrafen';
  //call trace(@@ErrorTextProcedure);
  insert into tmpBudget(Nivo, Oms, Rub, Par, Sub, Uitgesplitst, tmpBlGid)
  select
   30, OmsBalanscodeDetails, Rubriek, Paragraaf, Subparagraaf, 0, BlGid
  from
   tabbalanscodedetail,
   tmpBudget
  where
    Nivo = 20
    and detailblcode = @BlCode
    and Rubriek = Rub
    and Paragraaf = Par
    and SubParagraaf <> ''
    and if @BlCode = 0 then par + SubParagraaf else rub + '.' + par +'.' + SubParagraaf endif between @VanRubParSub and @TotRubParSub;


  // *** Index aan de tabel toevoegen ***
  // ------------------------------------
  create index idx_tmpBudgetNivo on tmpBudget (nivo, rub, par, sub);


  // *** Berekenen van budgetbedragen van balanscodes per periode ***
  // ----------------------------------------------------------------

  // Per periode
  set @@ErrorTextProcedure = @ErrorText + 'Bereken budgetbedragen';
  //call trace(@@ErrorTextProcedure);
  insert into tmpPeriode(perTmpGid, perPerNr, perBudgetBedrag)
  select
    tmpGid, PerNr,
    IsNull((if BudMetVerdeling = 1 then
              (select sum((Bud_PercAfronden(BudPerPercentage) * BinnenBudget.Jaarbudget / 100)) from tabBudget BinnenBudget inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid) and (BudPerNr = PerNr) and (BudPerBudgetCode = BinnenBudget.BudBudgetCode) where BinnenBudget.BudgetGid = BuitenBudget.BudgetGid)
            else
               (select sum(BudBedrag) from tabBudgetBedrag where (BudBedrBudgetGid = BuitenBudget.BudgetGid) and (BudBedrPerNr = PerNr))
            endif) / @Koers, 0) BudgetBedrag
  from
    tmpBudget tmpBuitenBudget
    left outer join tabBudget BuitenBudget on (BudBlGid = tmpBlGid and BudBjGid = @BjGid),
    tabPeriode
  where
    PerBjGid = @BjGid and PerNr between @VanPernr and @TotPernr ;


  // *** Berekening van budget- en saldibedragen van gekoppelde rekeningen per periode ***
  // -------------------------------------------------------------------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Rekeningbudgetten en -saldi toevoegen per periode';
  //call trace(@@ErrorTextProcedure);
  update tmpPeriode BuitenPeriode
  set perBudgetTotaalOnderliggend =
   (select sum(
           (if buitenBudget.BudMetVerdeling = 1 then
              (select sum((Bud_PercAfronden(BudPerPercentage) * BinnenBudget.Jaarbudget / 100)) from tabBudget BinnenBudget inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid) and (BudPerNr = perPerNr) and (BudPerBudgetCode = BinnenBudget.BudBudgetCode) where BinnenBudget.BudgetGid = buitenBudget.BudgetGid)
            else
              (select sum(BinnenBudgetBedrag.BudBedrag) from tabBudget BinnenBudget inner join tabBudgetBedrag BinnenBudgetBedrag on (BinnenBudget.BudgetGid = BinnenBudgetBedrag.BudBedrBudgetGid) and (BudBedrPerNr = perPerNr) where BinnenBudget.BudgetGid = buitenBudget.BudgetGid)
            endif) *
            /* positief indien DEBET-rekening, Negatief indien CREDIT-rekening */
            (case DefaultBoekzijde
             when 3 /* afhankelijk van dagboek */ then if DefaultSoort in (2, 5, 7) /* passiva, opbrengsten of crediteur */ then -1 /*CREDIT*/ else 1 /*DEBET*/ endif
             when 2 /* geen voorkeur */ then 1 /*DEBET*/
             when 1 /* credit */ then -1       /*CREDIT*/
             when 0 /* debet */ then 1         /*DEBET*/
             else   /* voor de zekerheid */ 1  /*DEBET*/
             end
            ) / @Koers
           )
    from tabBudget buitenBudget
         inner join tabBalansCodeRekening on (BlRekBlCode = @BlCode and BlRekBlGid = tmpBuitenBudget.tmpBlGid)
         inner join tabRekeningschema on (RksGid = BlRksGid)
    where     (buitenBudget.BudBjGid  = @BjGid)   // Budget van het huidige jaar
          and (buitenBudget.BudRksGid = BlRksGid) // Alleen budgetten van de rekeningen
   ),
   perWerkelijkBedrag =
    if @BlCode = 0 then
      // Normale balans -> rekeningen opzoeken middels rekeningnummer vergelijken met balanscode
      (select sum(case (if @VergelijkMet = 4 then if VergelijkenMet is not null then VergelijkenMet else 0 endif else @VergelijkMet endif)
                    when 0 then //Saldo
                      case @SoortBoeking
                        when 0 then //Definitief
                          SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig) - (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)
                        end
                    when 1 then  //Debet
                      case @SoortBoeking
                        when 0 then //Definitief
                          SaldoDebetBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoDebetBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig)
                        end
                    when 2 then  //Credit
                      case @SoortBoeking
                        when 0 then //Definitief
                         SaldoCreditBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoCreditBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)
                        end
                    //when 3=default-boekzijde kan niet voor een balanscodebudget
                  end) / @koers
       from              tabRekeningschema
              inner join tabRekeningSaldo on (RekSaldoRksGid = RksGid)
              left outer join tabBudget             on (BudBjGid    = @BjGid  and BudBlGid  = tmpBlGid) // Dit is het budget van de balanscode!
       where      (RekSaldoBjGID  = @BjGid)
              and (RekSaldoPerNr = perPerNr)
              and (RksInvoer like if isnull(par,'')='' then isnull(rub,'') else isnull(par,'') endif + isnull(sub,'') +'%')
      )
    else
      // Variabele balans -> rekeningen opzoeken middels tabBalansCodeRekening
      (select sum(case (if @VergelijkMet = 4 then if VergelijkenMet is not null then VergelijkenMet else 0 endif else @VergelijkMet endif)
                    when 0 then //Saldo
                      case @SoortBoeking
                        when 0 then //Definitief
                          SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig) - (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)
                        end
                    when 1 then  //Debet
                      case @SoortBoeking
                        when 0 then //Definitief
                          SaldoDebetBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoDebetBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig)
                        end
                    when 2 then  //Credit
                      case @SoortBoeking
                        when 0 then //Definitief
                         SaldoCreditBasisDefinitief
                        when 1 then //Voorlopig
                          SaldoCreditBasisVoorlopig
                        else        //Definitief + voorlopig
                          (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)
                        end
                    //when 3=default-boekzijde kan niet voor een balanscodebudget
                  end) / @koers
       from              tabRekeningSaldo
              inner join tabBalansCodeRekening on (BlRekBlCode = @BlCode and BlRekBlGid = tmpBlGid and BlRksgid = ReksaldoRksgid)
              left outer join tabBudget             on (BudBjGid    = @BjGid  and BudBlGid  = tmpBlGid) // Dit is het budget van de balanscode!
       where      (RekSaldoBjGID  = @BjGid)
              and (RekSaldoPerNr = perPerNr)
      )
    endif
  from tmpPeriode BuitenPeriode
       inner join tmpBudget tmpBuitenBudget on (PerTmpGid = tmpGid);


  // *** Jaarbudget per balanscode overnemen uit budget/onderliggend ***
  // -------------------------------------------------------------------

  // Jaarbudget overnemen; Deze laten we zo i.v.m. afrondingen bij de omrekening naar een andere valuta
  // We kunnen de jaarbudgetten ook niet uit tmpPeriode halen i.v.m. afdruk van slechts enkele periodes
  set @@ErrorTextProcedure = @ErrorText + 'Jaarbudgetten overnemen';
  //call trace(@@ErrorTextProcedure);
  // De budgetloze regels hebben hierna nog steeds een JaarbudgetBedrag=NULL
//  update tmpBudget
//  set    JaarbudgetBedrag = if BudMetVerdeling = 1 then
//                              Jaarbudget
//                            else
//                              (select sum(BudBedrag) from tabBudgetBedrag where (BudBedrBudgetGid = BudgetGid))
//                            endif / @Koers
//  from
//    tmpBudget
//    inner join tabBudget on (BudBlGid = tmpBlGid);
//
//  // Jaarbudget van onderliggende rekeningen bepalen en toevoegen per balanscode
//  set @@ErrorTextProcedure = @ErrorText + 'Jaarbudgetten overnemen van rekeningen per balanscode';
//  //call trace(@@ErrorTextProcedure);
//  update tmpBudget
//  set
//   JaarbudgetBedragOnderliggend =
//     (select sum(if BudMetVerdeling = 1 then Jaarbudget else BudBedrag endif *
//            /* positief indien DEBET-rekening, Negatief indien CREDIT-rekening */
//            (case DefaultBoekzijde
//             when 3 /* afhankelijk van dagboek */ then if DefaultSoort in (2, 5, 7) /* passiva, opbrengsten of crediteur */ then -1 /*CREDIT*/ else 1 /*DEBET*/ endif
//             when 2 /* geen voorkeur */ then 1 /*DEBET*/
//             when 1 /* credit */ then -1       /*CREDIT*/
//             when 0 /* debet */ then 1         /*DEBET*/
//             else   /* voor de zekerheid */ 1  /*DEBET*/
//             end
//            )/ @Koers)
//        from tabBudget
//             inner join tabBalansCodeRekening on (BlRekBlCode = @BlCode and BlRekBlGid = tmpBlGid)
//             inner join tabRekeningschema on (RksGid = BlRksGid)
//             left outer join tabBudgetBedrag on (BudBedrBudgetGid = BudgetGid )
//        where     (BudBjGid  = @BjGid)   // Budget van het huidige jaar
//              and (BudRksGid = BlRksGid) // Alleen budgetten van de rekeningen
//     )
//   from tmpBudget;



  // *** Lege budgetregels vullen met totaal onderliggend budget ***
  // ---------------------------------------------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Onderliggend totaal als budget/werkelijke bedrag gebruiken';
  //call trace(@@ErrorTextProcedure);
  set @Nivo = 30; // vanaf subparagraaf omhoog tellen (Let op! vanaf SUB i.v.m. doorrekenen van budgetloze (sub)paragrafen en rubrieken)
  while @Nivo > 0 LOOP

    set @@ErrorTextProcedure = @ErrorText + 'Onderliggend budget berekenen, onderliggend saldo bij totaalsaldo optellen (nivo='+string(@nivo)+', per periode)';
    // ACW bug 26292: Bij normale balans zijn hier de werkelijke bedragen al keurig aan de sub/par/rub toegevoegd, dus NIET nogmaals doen
    //                Bij de var.balansen is dit nog niet gebeurt, dus alsnog zo doen!
    update tmpPeriode Hoger
    set perBudgetTotaalOnderliggend     = isnull(perBudgetTotaalOnderliggend,    0) + isnull(TotaalBudget,     0),
        perWerkelijkBedrag              = isnull(perWerkelijkBedrag,             0) + if @BlCode = 0 then 0 else isnull(TotaalWerkelijk,  0) endif
    from tmpPeriode Hoger inner join tmpBudget on (perTmpGid = tmpGid),
         (select dieperBudget.rub drub, dieperPeriode.perPerNr dperpernr,
                 if @nivo in (20,30) then dieperBudget.par else '-' endif dpar,               // Rub/Par teruggeven
                 sum(isnull(dieperPeriode.perBudgetBedrag,     0)) TotaalBudget,                  // Totaal onderliggend budget voor de paragraaf resp. rubriek
                 sum(isnull(dieperPeriode.perWerkelijkBedrag,  0)) TotaalWerkelijk                // Totaal onderliggend werkelijk saldo voor de paragraaf resp. rubriek
          from   tmpPeriode dieperPeriode inner join tmpBudget dieperBudget on (dieperPeriode.PerTmpGid = dieperBudget.tmpGid)
          where   dieperBudget.nivo = @nivo + 10                                                     // Zie je wel? Totaal op 1 nivo dieper
          group by drub, dpar, dieperPeriode.perPerNr
         ) dieper
    where     (nivo = @nivo)                                                            // Per nivo berekenen i.v.m. doorrekenen!
          and (drub = rub)                                                              // En de rubriek moet gelijk zijn
          and (dpar = isnull(par,'-'))                                                  // Paragraaf is leeg als het een totaal van alles in een rubriek betreft
          and (dperpernr = perPerNr);                                                   // En per periode optellen!

    // Ook het jaarbudget even bepalen
    set @@ErrorTextProcedure = @ErrorText + 'Onderliggend budget als budget gebruiken (nivo='+string(@nivo)+', per balanscode)';
/*
    update tmpBudget Hoger
    set JaarbudgetBedragOnderliggend = isnull(JaarbudgetBedragOnderliggend,0) + isnull(TotaalJaarBudget, 0)
    from tmpBudget Hoger,
         (select dieper.rub drub,
                 if @nivo in (20,30) then dieper.par else '-' endif dpar,               // Rub/Par teruggeven
                 sum(isnull(dieper.JaarBudgetBedrag, 0)) TotaalJaarBudget//,              // Totaal onderliggend jaarbudget voor de paragraaf resp. rubriek
          from   tmpBudget dieper
          where   nivo = @nivo + 10                                                     // Zie je wel? Totaal op 1 nivo dieper
          group by drub, dpar
         ) dieper
    where     (nivo = @nivo)                                                            // Per nivo berekenen i.v.m. doorrekenen!
          and (drub = rub)                                                              // En de rubriek moet gelijk zijn
          and (dpar = isnull(par,'-'));                                                 // Paragraaf is leeg als het een totaal van alles in een rubriek betreft
*/
    // Voor de budgetloze balanscodes alle onderliggende periodebudgetten overnemen
    set @@ErrorTextProcedure = @ErrorText + 'Onderliggend budget als budget gebruiken (nivo='+string(@nivo)+', per periode)';
    //call trace(@@ErrorTextProcedure);
    update tmpPeriode
    set perBudgetBedrag = perBudgetTotaalOnderliggend
    from tmpPeriode Hoger inner join tmpBudget on (perTmpGid = tmpGid)
         left outer join tabBudget on (BudBjGid = @BjGid and BudBlGid = tmpBlGid)
    where BudgetGid is null and nivo = @nivo;

    set @nivo = @nivo - 10;
  END LOOP;


  // *** Comprimeren ***
  // -------------------

  if @ComprimeerBalans in (1,2) then
    // Alle subparagrafen en dieper verwijderen van niet-uitgesplitste rubrieken
    set @@ErrorTextProcedure = @ErrorText + 'Comprimeer='+string(@ComprimeerBalans)+', Verwijder alle subparagrafen';
    //call trace(@@ErrorTextProcedure);
    delete tmpBudget
    where nivo = 30;
    //De WHERE hieronder is niet nodig; wordt gebruikt als verzamelen dynamisch gebeurt o.b.v. instellingen in de balanscode
    //where     Rub in (Select Rub from tmpBudget where uitgesplitst = 0 and par is null)   // Alles in de rubriek
    //      and par is not null;                                                        // Behalve de rubriek-regel zelf
  end if;
  if @ComprimeerBalans = 2 then
    // Alle paragrafen verwijderen van niet-uitgesplitste paragrafen
    set @@ErrorTextProcedure = @ErrorText + 'Comprimeer='+string(@ComprimeerBalans)+', Verwijder alle paragrafen';
    //call trace(@@ErrorTextProcedure);
    delete tmpBudget
    where nivo = 20;
    //De WHERE hieronder is niet nodig; wordt gebruikt als verzamelen dynamisch gebeurt o.b.v. instellingen in de balanscode
    //where Rub+Par in (Select Rub+Par from tmpBudget where uitgesplitst = 0 and sub is null) // Alles in de paragraaf
    //      and Sub is not null;                                                              // Behalve de paragraaf-regel zelf
  end if;


  // *** Bedragen vanuit periodes overnemen naar RubParSub ***
  // ---------------------------------------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Bedragen vanuit periodes overnemen naar RubParSub';
  //call trace(@@ErrorTextProcedure);
  update tmpBudget
  set    BudgetBedrag             = (select sum(perBudgetBedrag            ) from tmpPeriode where perTmpGid = tmpGid),
         BudgetTotaalOnderliggend = (select sum(perBudgetTotaalOnderliggend) from tmpPeriode where perTmpGid = tmpGid),
         WerkelijkBedrag          = (select sum(perWerkelijkBedrag         ) from tmpPeriode where perTmpGid = tmpGid)
  from   tmpBudget;


  // *** Verwijder regels zonder budget als die niet afgedrukt worden ***
  // --------------------------------------------------------------------

  if @OokZonderbudget = 0 then
    set @@ErrorTextProcedure = @ErrorText + 'Budgetloze regels verwijderen';
    //call trace(@@ErrorTextProcedure);
    // 1. Verwijder de periodes van de balanscodes met budgetbedrag=0
    delete tmpPeriode
    where perTmpGid in (select tmpGid from tmpBudget where isnull(BudgetBedrag,0) = 0);
    // 2. Verwijder de balanscodes met budgetbedrag=0
    delete tmpBudget where isnull(BudgetBedrag,0) = 0;
  end if;


  // *** Niet-verbijzonderd-regels plaatsen met het verschil ***
  // -----------------------------------------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Verschillen in de Niet-verbijzonderd-regel zetten';
  //call trace(@@ErrorTextProcedure);
  // Jaarbudgetbedrag staat niet in de layout, zowel, dan deze hier weer activeren
  set @nivo = 21;
  WHILE @nivo > 1 LOOP
    // Toevoegen aan rub/par/sub
    insert into tmpBudget(Nivo, Oms, Rub, Par, sub, Uitgesplitst, BudgetBedrag, /*JaarBudgetBedrag, */WerkelijkBedrag)
    select @nivo, @NietVerbijzonderd,
           Rub, if @nivo >= 20 then Par else '_NV' endif, if @nivo >= 30 then sub else '_NV' endif, 0,
           BudgetBedrag     - BudgetTotaalOnderliggend NieuwBudgetBedrag,
//             JaarBudgetBedrag - JaarbudgetBedragOnderliggend NieuwJaarBudget,
            // Werkelijke bedrag dat al bij hetzelfde nivo staat
            WerkelijkBedrag
            // Totale werkelijke bedrag dat al bij het niveau dieper staat
            - isnull((select sum(binnen.WerkelijkBedrag) from tmpBudget binnen
                      where      (binnen.nivo = @nivo + 9)
                             and (binnen.rub=buiten.rub)
                             and (binnen.par is not null)
                             and (   (@nivo = 21 and binnen.par = buiten.par and binnen.sub is not null)
                                  or (@nivo <> 21)
                                 )
                     ),0) NieuwWerkelijkBedrag
    from tmpBudget buiten
    where     (   (isnull(NieuwBudgetBedrag,0)    <> 0)  // Alleen als bedrag niet overeenkomt
//                 or (isnull(NieuwJaarBudget,0)      <> 0)
               or (isnull(NieuwWerkelijkBedrag,0) <> 0)
              )
          and (nivo = @nivo - 1);

    // toevoegen aan periodes; We mogen ervan uit gaan dat de tmpBudget i.i.g. is gevuld voor de betreffende budgetten!
    insert into tmpPeriode(perTmpGid, perPerNr, perBudgetBedrag, perWerkelijkBedrag)
    select (select binnenBudget.tmpGid
            from   tmpBudget binnenBudget
            where      (binnenBudget.nivo = @nivo)
                   and (binnenBudget.rub  = BuitenBudget.Rub)
                   and (binnenBudget.Par  = if @nivo >= 20 then buitenBudget.Par else '_NV' endif)
                   and (binnenBudget.sub  = if @nivo >= 30 then buitenBudget.sub else '_NV' endif)
           ),
           perPerNr,
           perBudgetBedrag     - perBudgetTotaalOnderliggend NieuwBudgetBedrag,
            // Werkelijke bedrag dat al bij hetzelfde nivo staat
            perWerkelijkBedrag
            // Totale werkelijke bedrag dat al bij het niveau dieper staat
            - isnull((select sum(binnenPeriode.perWerkelijkBedrag) from tmpPeriode binnenPeriode inner join tmpBudget binnenBudget on (binnenPeriode.perTmpGid = binnenBudget.tmpGid)
                      where      (binnenPeriode.perPerNr = buitenPeriode.perPerNr)
                             and (binnenBudget.nivo = @nivo + 9)
                             and (binnenBudget.rub  = buitenBudget.rub)
                             and (binnenBudget.par is not null)
                             and (   (@nivo = 21 and binnenBudget.par = buitenBudget.par and binnenBudget.sub is not null)
                                  or (@nivo <> 21)
                                 )
                     ),0) NieuwWerkelijkBedrag
    from tmpBudget buitenBudget
         left outer join tmpPeriode buitenPeriode on buitenPeriode.perTmpGid = buitenBudget.tmpGid
    where
              (   (isnull(NieuwBudgetBedrag,0)    <> 0)  // Alleen als bedrag niet overeenkomt
               or (isnull(NieuwWerkelijkBedrag,0) <> 0)
              )
          and (nivo = @nivo - 1);

    set @nivo = @nivo - 10;

  END LOOP;


  // *** Niet-Verbijzonderd van nivos ZONDER dieper nivo toevoegen ***
  // -----------------------------------------------------------------

  // De niet-verbijzonderd-regel toevoegen van niveaus waarvoor geen dieper niveau is BEHALVE het diepste niveau
/*
  // Let op: Dit is overgenomen van de gewone balanscodebudgetten; hier moet nog de periode bij, indien het toch nodig blijkt te zijn.
  set @@ErrorTextProcedure = @ErrorText + 'Niet-verbijzonderd-regels toevoegen als er geen dieper niveau meer is';
  //call trace(@@ErrorTextProcedure);
  insert into tmpBudget(Nivo, Oms, Rub, Par, sub, Uitgesplitst, BudgetBedrag, WerkelijkBedrag, JaarBudgetBedrag)
  select nivo + 1, @NietVerbijzonderd,
         Rub, if nivo >= 20 then Par else '_NV' endif, if nivo >= 30 then sub else '_NV' endif, 0,
         BudgetBedrag,
         WerkelijkBedrag,
         JaarBudgetBedrag
  from   tmpBudget buiten
  where      (   (nivo = 10 and @ComprimeerBalans <> 2) // 0=nee, 1=alleen rubrieken+paragrafen, 2=alleen rubrieken
              or (nivo = 20 and @ComprimeerBalans = 0)
             )
         and (not exists( select 1
                          from tmpBudget binnen
                          where     (binnen.rub = buiten.rub)
                                and (   (buiten.nivo = 10 and binnen.par is not null)
                                     or (buiten.nivo > 10 and binnen.par = buiten.par)
                                    )
                                and (   (buiten.nivo = 20 and binnen.sub is not null)
                                     or (buiten.nivo <> 20)
                                    )
                        )
             );
*/


  // *** Sortering ***
  // -----------------

  set @@ErrorTextProcedure = @ErrorText + 'Sortering';
  //call trace(@@ErrorTextProcedure);
  update tmpBudget
  set    Sortering = number(),
//         oms = string(nivo)+'|'+rub+'.'+par+'.'+sub+'|'+oms,
         nivo = ((nivo+9)/10) * 10
  from   tmpBudget
  order by Rub,
           if Par is null then 'BBB' else if Par = '_NV' then 'AAA' else Par endif endif,
           if Sub is null then 'BBB' else if Sub = '_NV' then 'AAA' else Sub endif endif,
           nivo;


  // *** Totaal generaal ***
  // -----------------------

  set @@ErrorTextProcedure = @ErrorText + 'Totaal generaal';
  //call trace(@@ErrorTextProcedure);
  if exists(select first 1 from tmpBudget) then
    insert into tmpBudget(Sortering, Nivo, Oms, Rub, Uitgesplitst, BudgetBedrag, WerkelijkBedrag, /*JaarbudgetBedrag, */DubbelStreepOnder)
    select (select max(Sortering) from tmpBudget) + 1, 99, '', '', 1, sum(BudgetBedrag), sum(WerkelijkBedrag), /*sum(JaarbudgetBedrag),*/ 0
    from   tmpBudget
    where  nivo = 10;
    insert into tmpPeriode(perTmpGid, perPerNr, perBudgetBedrag, perWerkelijkBedrag)
    select
      (select first tmpGid from tmpBudget where nivo = 99) tmpBudgetGid,
      perPerNr,
      sum(perBudgetBedrag),
      sum(perWerkelijkBedrag)
    from tmpPeriode
    group by tmpBudgetGid, perPerNr;
  end if;



  // *** Optelstrepen etc. ***
  // -------------------------

  set @@ErrorTextProcedure = @ErrorText + 'Optel- en totaalstrepen';
  //call trace(@@ErrorTextProcedure);
  // Dubbele streep indien de regel hieronder van een dieper nivo is (bijv. Paragraaf onder Rubriek)
  set @nivo = 30;
  WHILE @nivo > 0 LOOP
    update tmpBudget buiten
    set DubbelStreepOnder = 1
    where nivo < (select binnen.nivo from tmpBudget binnen where binnen.sortering = buiten.sortering + 1)
          and nivo = @nivo;

    // Enkele streep als de regel hierboven geen dubbele streep heeft en van een dieper nivo is (bijv. Paragraaf boven Rubriek)
    update tmpBudget buiten
    set OptelstreepBoven  = 1,
        DubbelStreepOnder = 1
    where     nivo < (select binnen.nivo from tmpBudget binnen where binnen.sortering = buiten.sortering - 1 and binnen.DubbelStreepOnder = 0)
          and nivo = @nivo;
    set @nivo = @nivo - 10;
  end LOOP;


  // *** ++ en -- bepalen per periode ***
  // ------------------------------------

  // Update de percentages per periode
  set @@ErrorTextProcedure = @ErrorText + 'Verschilpercentages bepalen';
  //call trace(@@ErrorTextProcedure);
  update tmpPeriode
  set perVerschilPerc = if perBudgetBedrag <> 0 then (isnull(perWerkelijkBedrag,0) - perBudgetBedrag) / perBudgetBedrag * 100 endif;

  // Vervolgend de ++/--/+/- erin zetten
  set @@ErrorTextProcedure = @ErrorText + 'PlusMin-tekens plaatsen';
  //call trace(@@ErrorTextProcedure);
  update tmpPeriode
  set perPlusMinTeken = (case
                           when abs(perVerschilPerc) > @PlusMin2 then if perVerschilPerc > 0 then '++' else '--' endif
                           when abs(perVerschilPerc) > @PlusMin1 then if perVerschilPerc > 0 then '+'  else '-'  endif
                         end);


  // *** KLAAR ***
  // -------------

  set @@ErrorTextProcedure = @ErrorText + 'einde';
  //call traceEind(@@ErrorTextProcedure);

  select   nivo RegelSoort,
           if @BlCode = 0 then
              if Par = '_NV' or Par is null then Rub else Par+ if sub is null or sub = '_NV' then '' else Sub endif endif
           else
              (Rub + if Par is null or Par = '_NV' then '' else '.'+Par+ if sub is null or sub = '_NV' then '' else '.'+Sub endif endif)
           endif RubParSub,
           Oms,
           isnull(BudgetBedrag,0) Budgetbedrag,
           isnull(WerkelijkBedrag,0) SaldoBedrag,
           isnull(WerkelijkBedrag,0) - isnull(BudgetBedrag,0) VerschilBedrag,
           if BudgetBedrag <> 0 then (isnull(WerkelijkBedrag,0) - BudgetBedrag) / BudgetBedrag * 100 endif VerschilPerc,
           OptelstreepBoven,
           DubbelStreepOnder DubbelStreepBoven,
//           JaarBudgetBedrag,
//           BudgetCode,
//           BudgetOms,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  1)) periode01,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  2)) periode02,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  3)) periode03,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  4)) periode04,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  5)) periode05,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  6)) periode06,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  7)) periode07,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  8)) periode08,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr =  9)) periode09,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr = 10)) periode10,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr = 11)) periode11,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr = 12)) periode12,
           (select perPlusMinTeken from tmpPeriode where (perTmpGid = tmpGid) and (perPerNr = 13)) periode13
  from     tmpBudget
  //         left outer join tabBudget     on (BudBlGid = tmpBlGid and BudBjGid = @BjGid)
  //         left outer join tabBudgetCode on (BudgetCode = BudBudgetCode)
  order by Sortering;


end;

//call rapBudgetPerBalansCodePeriodeNaast( 1, 2, 1, 12, '000.000.000', '999.999.999', 2, 0, 0, 0, 0, 10, 20)


create or replace procedure rapBudgetPerKostendrager(
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @SelecteerOp       smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
in @VanKstd           nchar(40), //van nummer/zoekcode/naam
in @TotKstd           nchar(40), //t/m nummer/zoekcode/naam
in @SorterenOp        smallint, //0=Nummer, 1=Zoekcode, 2=Naam, 3=RekeningSoort
in @SoortBoeking      smallint, //0=definitief, 1=voorlopig, 2=beide
in @OokZonderbudget   smallint, //0=Nee (alleen rekeningen met budget), 1=Ja
in @VergelijkMet      smallint, //4=Zoals bij budget, 0=Saldo, 1=Debet, 2=Credit
in @OverzichtInValuta integer)  //Valutanummer waarin bedragen moeten worden afgedrukt


result (RegelSoort integer, KstdCode nchar(26), KstdNaam nchar(40), ValCode nchar(3), ValNummer Integer, Budget numeric(15,2),
        Saldo numeric(15,2), Verschil numeric(15,2), Percentage numeric(15,2),
        JaarBudget numeric(15,2), BudgetCode integer, BudgetOms nchar(40) )

begin

  declare @Teller smallint;
  declare @TotaalValCode nchar(3);
  declare @OverzichtValCode nchar(3);
  declare @koers numeric(9,6);

  declare local temporary table tmpBudget(
     tmpGid                  integer default AutoIncrement,
     KstdCode                nchar(26),
     KstdNaam                 nchar(40) default '',
     Valcode                 nchar(3) default  '',
     tmpValNummer            integer,
     SorteerVeld             nchar(40) default '',
     BudVergelijkenMet       smallint,
     BudgetInBasisValuta     numeric(15,2),
     BudgetInValuta          numeric(15,2),
     SaldoInBasisValuta      numeric(15,2),
     SaldoInValuta           numeric(15,2),
     Verschil                numeric(15,2),
     //VerschilTotaal        numeric(15,2) compute (if tmpDefaultBoekzijde = 1 then -(BudgetTotaal - SaldoTotaal) else (BudgetTotaal - SaldoTotaal) endif),
     Percentage              numeric(15,2),
     //PercentageTotaal      numeric(15,2) compute (if BudgetTotaal=0 then 0 else (VerschilTotaal / (if BudgetTotaal<0 and VerschilTotaal<0 then -BudgetTotaal else BudgetTotaal endif) * 100) endif),
     JaarBudgetInBasisValuta numeric(15,2),
     JaarBudgetInValuta      numeric(15,2),
     BudgetCode              integer,
     BudgetOms               nchar(40),
     RegelSoort              integer,
     primary key (tmpGid)
   ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapBudgetPerKostendrager > @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+',@VanKstd='+@VanKstd+', @TotKstd='+@TotKstd;
  //call TraceBegin(@@ErrorTextProcedure);
  //call trace('rapBudgetPerKostendrager > @SorterenOp='+string(@SorterenOp)+', @SoortBoeking='+string(@SoortBoeking)+',@OokZonderbudget='+string(@OokZonderbudget)+',@VergelijkMet='+string(@VergelijkMet)+',@OverzichtInValuta='+String(@OverzichtInValuta));

  Create index idx_tmpBudgetSoort     on tmpBudget (Regelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (SorteerVeld);

  //call Trace('Stap 1');
  set @koers = KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta);

  // gegevens per periode ophalen
  insert into tmpBudget (RegelSoort, KstdCode, KstdNaam, tmpValNummer, ValCode, BudVergelijkenMet,
                         BudgetInBasisValuta, BudgetInValuta, SaldoInBasisValuta, SaldoInValuta,
                         JaarBudgetInBasisValuta, JaarBudgetInValuta, BudgetCode, BudgetOms, SorteerVeld)
  select   1,
           KstdCode,
           KstdNaam,
          @OverzichtInValuta tmpValNummer,
          (select ValCode from tabValuta where ValNummer = tmpValNummer),
           if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then // saldo, debet of credit
             IsNull(VergelijkenMet,0)
           else
             if @VergelijkMet = 4 then
               0 // saldo
             else
               @VergelijkMet // debet of credit
             endif
           endif BudVergelijkenMet, //0=saldo, 1=debet, 2=credit
           // BedragInBasis :
           if BudgetGid is not null then
             // Kstp heeft een budget, die dus gebruiken!
             if BudMetVerdeling = 1 then
               // Kstp heeft een jaarbudget -> jaarbudget * (totaal budget% van de perioderange) berekenen
               round(JaarBudget * (Bud_CumPercentage(@BjGid, @VanPerNr, @TotPerNr, BudBudgetCode)/100),2)
             else
               // Kstp heeft budget per periode -> perioderange optellen
               (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = BudgetGid and BudBedrPerNr between @VanPerNr and @TotPerNr)
             endif
           else
             // Kstp heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstp (in basisvalua) berekenen
             sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                 ValutaOmrekenen(RksValNummer,
                                       (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                     // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                     round(tabRksBudget.JaarBudget * (Bud_CumPercentage(@BjGid, @VanPerNr, @TotPerNr, tabRksBudget.BudBudgetCode)/100),2)
                                                   else
                                                     // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                     (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = tabRksBudget.BudgetGid and BudBedrPerNr between @VanPerNr and @TotPerNr)
                                                   endif
                                                  )
                                        from      tabBudget tabRksBudget
                                        where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid) // ACW 01-10-2002: test op @BjGid toegevoegd
                                       , @@BasisValutaNummer, @BjGid, @TotPernr, 2
                                      )
                )
           endif BedragInBasisValuta,
           // BedragInValuta :
           if BudgetGid is not null then
              // Kstp heeft zelf een budget, dus gewoon omrekenen
              BedragInBasisValuta / @Koers
           else
             // Kstp heeft geen budget, dus rekeningtotalen nogmaals berekenen, nu naar afdrukvaluta
             sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                 ValutaOmrekenen(RksValNummer,
                                       (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                     // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                     round(tabRksBudget.JaarBudget * (Bud_CumPercentage(@BjGid, @VanPerNr, @TotPerNr, tabRksBudget.BudBudgetCode)/100),2)
                                                   else
                                                     // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                     (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = tabRksBudget.BudgetGid and BudBedrPerNr between @VanPerNr and @TotPerNr)
                                                   endif
                                                  )
                                        from      tabBudget tabRksBudget
                                        where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid) // ACW 01-10-2002: test op @BjGid toegevoegd
                                       , @OverzichtInValuta, @BjGid, @TotPernr, 2
                                      )
                )
           endif BedragInValuta,
           case @SoortBoeking
             when 0 then // Definitief
               case BudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0)
               end
             when 1 then  //Voorlopig
               case BudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
             else
               case BudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0) - IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
           end SaldoInBasisValuta,
           SaldoInBasisValuta / @Koers SaldoInValuta,
           // JaarbudgetInBasisValuta :
           IsNull(if BudgetGid is not null then
                    // Kstp heeft een budget
                    if BudMetVerdeling = 1 then
                      JaarBudget
                    else
                      (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = BudgetGid)
                    endif
                  else
                   // Kstp heeft geen budget, dus totaal jaarbudget van de rekeningen opvragen
                   sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                       ValutaOmrekenen(RksValNummer,
                                             (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                           // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                           tabRksBudget.JaarBudget
                                                         else
                                                           // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                           (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                         endif
                                                        )
                                              from      tabBudget tabRksBudget
                                              where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid) // ACW 01-10-2002: test op @BjGid toegevoegd
                                             , @@basisvalutanummer, @BjGid, @TotPernr, 2
                                            )
                      )
                  endif
                 , 0) JaarbudgetInBasisValuta,
           JaarBudgetInBasisValuta / @Koers JaarBudgetInValuta,
           BudBudgetCode,
          (select BudgetOms from tabBudgetCode where BudgetCode = BudBudgetCode) BudgetOms,
          (if @SorterenOp = 0 then KstdCode else if @SorterenOp = 1 then KstdZoekcode else KstdNaam endif endif)
  from     tabKostendrager
           left outer join tabBudget         BudgetBuiten on (BudKstdgid     = KstdGid and BudBjGid = @BjGid)
           left outer join (           tabRekeningschema RksBuiten
                            left outer join (select sum(SaldoDebetBasisDefinitief  ) SaldoDebetBasisDefinitief,
                                                    sum(SaldoDebetBasisVoorlopig   ) SaldoDebetBasisVoorlopig,
                                                    sum(SaldoDebetValutaDefinitief ) SaldoDebetValutaDefinitief,
                                                    sum(SaldoDebetValutaVoorlopig  ) SaldoDebetValutaVoorlopig,
                                                    sum(SaldoCreditBasisDefinitief ) SaldoCreditBasisDefinitief,
                                                    sum(SaldoCreditBasisVoorlopig  ) SaldoCreditBasisVoorlopig,
                                                    sum(SaldoCreditValutaDefinitief) SaldoCreditValutaDefinitief,
                                                    sum(SaldoCreditValutaVoorlopig ) SaldoCreditValutaVoorlopig,
                                                    RekSaldoRksGid
                                             from   tabRekeningsaldo
                                             where (RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
                                             group by RekSaldoRksGid
                                            ) RekSaldoTotaalPerKrs on (RekSaldoRksGid = RksGid)
                           ) on (    (RksKstdGid     = KstdGid)
                                 // ACW 15-03-2007: vinkje in voorloopscherm ook van invloed op Rks
                                 and (   (@OokZonderbudget = 1) // Alleen de rekening opnemen als ook zonder budgetten OF kstp heeft budget OF rekening heeft budget!!
                                      or (BudgetBuiten.BudKstdgid is not null)
                                      or (exists(select first 1 from tabBudget RksBudget where RksBudget.BudRksGid = RksGid and RksBudget.BudBjGid = @BjGid))
                                     )
                                )
  where  ((KstdCode     between @VanKstd and @TotKstd and @SelecteerOp = 0)  or
          (KstdZoekcode between @VanKstd and @TotKstd and @SelecteerOp = 1)  or
          (KstdNaam     between @VanKstd and @TotKstd and @SelecteerOp = 2))
  group by KstdCode, KstdZoekcode, KstdNaam, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid;

  set @@ErrorTextProcedure = 'rapBudgetPerKostendrager > Stap 4';
  //call Trace(@@ErrorTextProcedure);
  if @OokZonderbudget = 0 then
    delete tmpBudget
    where  kstdcode not in (select KstdCode from tabBudget inner join tabKostendrager on (KstdGid = BudKstdGid) where BudBjGid = @BjGid) and // Heeft zelf geen budget
           Kstdcode not in (select KstdCode from tabRekeningSchema inner join tabBudget on BudRksGid = RksGid inner join tabKostendrager on KstdGid = RksKstdGid where BudBjGid = @BjGid) // Heeft geen rekeningen met het budget
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerKostendrager > Totaal generaal';
  //call Trace(@@ErrorTextProcedure);
  if exists( select 1 from tmpBudget) then
    insert into tmpBudget (RegelSoort, SorteerVeld, KstdNaam, ValCode, tmpValNummer, BudgetInValuta, SaldoInValuta,
                           JaarBudgetInValuta)
    select   99,
             repeat('z',40),
             _U('Van kostenpl. %1! t/m %2!', @VanKstd, @TotKstd),
             (select ValCode from tabValuta where ValNummer = @OverzichtInValuta),
             @OverzichtInValuta,
             sum(BudgetInBasisValuta)     / @Koers tmpBudgetInValuta,
             sum(SaldoInBasisValuta)      / @Koers tmpSaldoInValuta,
             sum(JaarBudgetInBasisValuta) / @Koers tmpJaarbudgetInValuta
    from     tmpBudget where RegelSoort = 1;
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerKostendrager > Nu nog even percentage bepalen';
  //call Trace(@@ErrorTextProcedure);
  update tmpBudget set Verschil     = (isnull(SaldoInValuta,0) - isnull(BudgetInValuta,0)) * (if isnull(BudgetInValuta,0) < 0 then -1 else 1 endif);
  update tmpBudget set Percentage   = (if BudgetInValuta = 0 then 0 else abs(Verschil) / abs(BudgetInValuta) * if sign(Verschil)=-1 then -1 else 1 endif endif * 100);
  //call TraceEind(@@ErrorTextTrigger);

  select RegelSoort, KstdCode, KstdNaam, ValCode, tmpValNummer, BudgetInValuta Budget, SaldoInValuta Saldo, Verschil, Percentage,
         JaarBudgetInValuta JaarBudget, BudgetCode, BudgetOms
  from   tmpBudget
  order by SorteerVeld;


end;

//call rapBudgetPerKostendrager(2, 0, 12, 0, '00000000', '99999999', 0, 2, 0, 3, 0);


create or replace procedure rapBudgetPerKostendragerPerPeriode(
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @SelecteerOp       smallint,      //0 = kstdnummer, 1=kstdzoekcode, 2=kstdnaam
in @Vankstd           nchar(40),      //van nummer/zoekcode/naam
in @Totkstd           nchar(40),      //t/m nummer/zoekcode/naam
in @SorterenOp        smallint,      //0=Nummer, 1=Zoekcode, 2=Naam, 3=RekeningSoort
in @SoortBoeking      smallint,      //0=definitief, 1=voorlopig, 2=beide
in @OokZonderbudget   smallint,      //0=Nee (alleen rekeningen met budget), 1=Ja
in @VergelijkMet      smallint,      //4=Zoals bij budget, 0=Saldo, 1=Debet, 2=Credit
in @OverzichtInValuta integer,       //Valutanummer waarin bedragen moeten worden afgedrukt
in @1PlusMinTeken     numeric(6,2),  //Bij welke percentage een +  of -  afdrukken
in @2PlusMinTeken     numeric(6,2))  //Bij welke percentage een ++ of -- afdrukken

result (tmpRegelSoort integer, tmpkstdcode nchar(26), tmpkstdNaam nchar(40), tmpPernr integer, tmpBeginDatum date, tmpEindDatum date,
        tmpBudgetInValuta numeric(15,2), tmpBudgetPercentage numeric(6,2), tmpSaldoInValuta numeric(15,2),
        tmpVerschil numeric(15,2), tmpPercentage numeric(15,2), tmpPlusMinTeken nchar(2), tmpSorteerveld nchar(40), tmpStreepVoorPercentage smallint)

begin

  declare @Teller           smallint;
  declare @TotaalValCode    nchar(3);
  declare @OverzichtValCode nchar(3);
  declare @koers            double;
  declare @MaxPerNr         integer;
  declare @HeleJaar         smallint;

  declare local temporary table tmpBudget(
     tmpGid                  integer default AutoIncrement,
     tmpkstdcode             nchar(26),
     tmpkstdNaam             nchar(40) default '',
     tmpPernr                integer,
     tmpBeginDatum           date,
     tmpEindDatum            date,
     tmpBudgetInBasisValuta  numeric(15,2),
     tmpBudgetInValuta       numeric(15,2),
     tmpPlusMinTeken         nchar(2),
     tmpSaldoInValuta        numeric(15,2),
     tmpSaldoInBasisValuta   numeric(15,2),
     tmpVerschil             numeric(15,2),
     tmpPercentage           numeric(15,2),
     tmpSorteerVeld          nchar(40) default '',
     tmpBudgetPercentage     numeric(6,2),
     tmpRegelSoort           integer,
     tmpBudgetGid            integer,
     primary key (tmpGid)
   ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapBudgetPerKostendragerPerPeriode > @Vankstd='+@Vankstd+', @Totkstd='+@Totkstd;
  //call TraceBegin(@@ErrorTextProcedure);

  Create index idx_tmpBudgetSoort     on tmpBudget (tmpRegelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (tmpSorteerVeld);

  //call Trace('Stap 1');

  set @koers = KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta);

  select max(PerNr) into @MaxPerNr from tabPeriode where PerBjGid = @BjGid;
  set @HeleJaar = if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then 1 else 0 endif;

  // gegevens per periode ophalen
  insert into tmpBudget (tmpRegelSoort, tmpPernr, tmpBeginDatum, tmpEindDatum, tmpkstdcode, tmpkstdNaam,
                         tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpBudgetPercentage,
                         tmpSaldoInBasisValuta, tmpSaldoInValuta,
                         tmpSorteerVeld, tmpBudgetGid)
  select   1,
           Pernr,
           BeginDatum,
           EindDatum,
           kstdcode,
           kstdNaam,
           // tmpBudgetInBasisValuta :
           if BudgetGid is not null then
             // Kstd heeft een budget, die dus gebruiken!
             if BudMetVerdeling = 1 then
               // Kstd heeft een jaarbudget -> jaarbudget * (totaal budget% van de perioderange) berekenen
               if @HeleJaar = 1 and PerNr = @MaxPerNr then
                  JaarBudget - (select sum(round(BudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2))
                                from tabBudget BudgetBinnen inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr <> @MaxPerNr and BudPerBudgetCode = BudgetBinnen.BudBudgetCode)
                                where BudgetBinnen.BudgetGid = BudgetBuiten.BudgetGid)
               else
                 (select JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = BudBudgetCode)
               endif
             else
               // Kstd heeft budget per periode -> perioderange optellen
               (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = BudgetGid)
             endif
           else
             // Kstd heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstd (in basisvalua) berekenen
             sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                 ValutaOmrekenen(RksValNummer,
                                       (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                     // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                     if @HeleJaar = 1 and PerBinnen.PerNr = @MaxPerNr then
                                                       tabRksBudget.JaarBudget - (select sum(round(tabRksBudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2))
                                                                                  from tabBudget tabRksBudgetBinnen inner join tabBudgetCodePeriode on BudPerBjGid = @BjGid and BudPernr<>@MaxPernr and BudPerBudgetCode = tabRksBudgetBinnen.BudBudgetCode
                                                                                  where tabRksBudgetBinnen.BudgetGid = tabRksBudget.BudgetGid)
                                                     else
                                                       (select tabRksBudget.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                     endif
                                                   else
                                                     // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                     (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid = @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                   endif
                                                  )
                                        from      tabBudget tabRksBudget,
                                                  tabPeriode PerBinnen
                                        where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid
                                                  and PerBinnen.PerBjGid = @BjGid and PerBinnen.PerNr = PerBuiten.PerNr
                                        )
                                       , @@BasisValutaNummer, @BjGid, @TotPernr, 2
                                      )
                )
           endif tmpBudgetInBasisValuta,

           // tmpBudgetInValuta :
           if BudgetGid is not null then
             // Kstd heeft een budget, die dus gebruiken!
             tmpBudgetInBasisValuta / @koers
           else
             // Kstd heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstd (in basisvalua) berekenen
             sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                 ValutaOmrekenen(RksValNummer,
                                       (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                     // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                     if @HeleJaar = 1 and PerBinnen.PerNr = @MaxPerNr then
                                                       tabRksBudget.JaarBudget - (select sum(round(tabRksBudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2))
                                                                                  from tabBudget tabRksBudgetBinnen inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr<>@MaxPernr and BudPerBudgetCode = tabRksBudgetBinnen.BudBudgetCode)
                                                                                  where tabRksBudgetBinnen.BudgetGid = tabRksBudget.BudgetGid)
                                                     else
                                                       (select tabRksBudget.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                     endif
                                                   else
                                                     // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                     (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid = @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                   endif
                                                  )
                                        from      tabBudget tabRksBudget,
                                                  tabPeriode PerBinnen
                                        where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid
                                                  and PerBinnen.PerBjGid = @BjGid and PerBinnen.PerNr = PerBuiten.PerNr
                                        )
                                       , @OverzichtInValuta, @BjGid, @TotPernr, 2
                                      )
                )
           endif tmpBudgetInValuta,

          (if BudMetVerdeling = 1 then (select BudPerPercentage from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr =Pernr and BudPerBudgetCode = BudBudgetCode) endif) tmpBudgetPercentage,
           isnull(sum(
           case @SoortBoeking
             when 0 then // Definitief

               case (if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then IsNull(VergelijkenMet,0) else if @VergelijkMet = 4 then case DefaultBoekzijde when 0 then 1 when 1 then 2  else 0 end else @VergelijkMet endif endif)
                 when 0 then  //Saldo
                   SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief
                 when 1 then  //Debet
                   SaldoDebetBasisDefinitief
                 when 2 then  //Credit
                  -SaldoCreditBasisDefinitief
               end
             when 1 then  //Voorlopig
               case (if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then IsNull(VergelijkenMet,0) else if @VergelijkMet = 4 then case DefaultBoekzijde when 0 then 1 when 1 then 2  else 0 end else @VergelijkMet endif endif)
                 when 0 then  //Saldo
                   SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig
                 when 1 then  //Debet
                   SaldoDebetBasisVoorlopig
                 when 2 then  //Credit
                  -SaldoCreditBasisVoorlopig
               end
             else
               case (if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then IsNull(VergelijkenMet,0) else if @VergelijkMet = 4 then case DefaultBoekzijde when 0 then 1 when 1 then 2  else 0 end else @VergelijkMet endif endif)
                 when 0 then  //Saldo
                   SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief + (SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig)
                 when 1 then  //Debet
                   SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig
                 when 2 then  //Credit
                  -SaldoCreditBasisDefinitief - SaldoCreditBasisVoorlopig
               end
           end),0) tmpSaldoInBasisValuta,
           tmpSaldoInBasisValuta / @Koers tmpSaldoInValuta,
          (if @SorterenOp = 0 then kstdcode else if @SorterenOp = 1 then kstdZoekcode else kstdNaam endif endif),
           BudgetGid
  from     (tabPeriode PerBuiten,
           tabKostendrager)
           left outer join tabBudget         BudgetBuiten on (Budkstdgid     = kstdGid and BudBjGid = @BjGid)
           left outer join tabRekeningschema RksBuiten    on (    (RkskstdGid     = kstdGid)
                                                              // ACW 15-03-2007: vinkje in voorloopscherm ook van invloed op Rks
                                                              and (   (@OokZonderbudget = 1) // Alleen de rekening opnemen als ook zonder budgetten OF kstp heeft budget OF rekening heeft budget!!
                                                                   or (BudgetBuiten.BudKstdgid is not null)
                                                                   or (exists(select first 1 from tabBudget RksBudget where RksBudget.BudRksGid = RksGid and RksBudget.BudBjGid = @BjGid))
                                                                  )
                                                             )
           left outer join tabRekeningsaldo  on (RekSaldoRksGid = RksGid and RekSaldoBjGid=@BjGid and RekSaldoPernr=PerNr)
  where  ((kstdCode     between @Vankstd and @Totkstd and @SelecteerOp = 0)  or
          (kstdZoekcode between @Vankstd and @Totkstd and @SelecteerOp = 1)  or
          (kstdNaam     between @Vankstd and @Totkstd and @SelecteerOp = 2))
          and PerBjGid = @BjGid and Pernr between @VanPernr and @TotPernr
  group by KstdGid, kstdcode, Pernr, BeginDatum, EindDatum, kstdZoekcode, kstdNaam, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid;

  //Bereken voor de laatste periode opnieuw het percentage en totaal budget zodat het totaal overeenkomt met het jaarbudget
  //call trace('Bereken de laatste periode opnieuw?');
  if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then
    //Alleen indien alle periodes worden afgedrukt!
    //call trace('Ja, opnieuw berekenen!');
    update tmpBudget buiten
    set    tmpBudgetInBasisValuta = JaarBudget          - (select sum(tmpBudgetInBasisValuta) from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstdCode = buiten.tmpKstdCode),
           tmpBudgetInValuta      = JaarBudget / @koers - (select sum(tmpBudgetInValuta)      from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstdCode = buiten.tmpKstdCode),
           tmpBudgetPercentage    = 100                 - (select sum(tmpBudgetPercentage)    from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstdCode = buiten.tmpKstdCode)
    from   tabBudget
    where  tmpPerNr = @MaxPerNr and BudMetVerdeling = 1 and BudgetGid = tmpBudgetGid;
  end if;

  //Eventueel alles eruifilteren waarvoor geen budget is (totaal van budget=0)
  if @OokZonderbudget = 0 then
    delete tmpBudget
    where  tmpkstdcode not in (select KstdCode from tabBudget inner join tabKostendrager on (KstdGid = BudKstdGid) where BudBjGid = @BjGid) and // Heeft zelf geen budget
           tmpkstdcode not in (select KstdCode from tabRekeningSchema inner join tabBudget on BudRksGid = RksGid inner join tabKostendrager on KstdGid = RksKstdGid where BudBjGid = @BjGid) // Heeft geen rekeningen met het budget
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerKostendragerPerPeriode > Totaal per Kostendrager';
  //call Trace(@@ErrorTextProcedure);
  insert into tmpBudget (tmpRegelSoort, tmpkstdcode, tmpkstdNaam,
                         tmpBudgetInValuta, tmpBudgetInBasisValuta,
                         tmpSaldoInValuta, tmpSaldoInBasisValuta, tmpBudgetPercentage, tmpSorteerVeld)
  select   2,
           tmpkstdcode,
           tmpKstdNaam,
           sum(tmpBudgetInValuta) Budget,
           sum(tmpBudgetInBasisValuta),
           sum(tmpSaldoInValuta),
           sum(tmpSaldoInBasisValuta),
           sum(tmpBudgetPercentage),
           min(tmpSorteerVeld)
  from     tmpBudget
  group by tmpKstdcode, tmpKstdNaam;

  set @@ErrorTextProcedure = 'rapBudgetPerKostendragerPerPeriode > Totaal generaal';
  //call Trace(@@ErrorTextProcedure);
  if exists( select 1 from tmpBudget) then

    insert into tmpBudget (tmpRegelSoort, tmpSorteerVeld, tmpKstdNaam, tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpSaldoInBasisValuta, tmpSaldoInValuta)
    select   99,
             repeat('z',40),
             _U('Van kostenpl. %1! t/m %2!', @VanKstd, @TotKstd),
             sum(tmpBudgetInBasisValuta) tmpBudgetInBasisValuta,
             sum(tmpBudgetInValuta)      tmpBudgetInValuta,
             sum(tmpSaldoInBasisValuta)  tmpSaldoInBasisValuta,
             sum(tmpSaldoInValuta)       tmpSaldoInValuta
    from     tmpBudget where tmpRegelSoort = 2;
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerKostendragerPerPeriode > Nu nog even percentage bepalen';
  //call Trace(@@ErrorTextProcedure);
  update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
  update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
  update tmpBudget set tmpPlusMinTeken = if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif;

  //call TraceEind(@@ErrorTextProcedure);
  select tmpRegelSoort, tmpKstdcode, tmpKstdNaam, tmpPernr, tmpBeginDatum, tmpEindDatum,
         tmpBudgetInValuta,
         tmpBudgetPercentage, tmpSaldoInValuta, tmpVerschil, tmpPercentage, tmpPlusMinTeken,
         tmpSorteerveld, if tmpBudgetPercentage is null or tmpRegelSoort = 99 then 0 else 1 endif tmpStreepVoorPercentage
  from   tmpBudget order by tmpSorteerVeld, tmpRegelSoort, tmpPernr;


end;
//call rapBudgetPerKostendragerPerPeriode(2, 1, 12, 0, '00000000', '9999999', 0, 1, 0, 0, 0, 5, 20);


create or replace procedure rapBudgetPerKostenplaats(
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @SelecteerOp       smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
in @VanKstp           nchar(40), //van nummer/zoekcode/naam
in @TotKstp           nchar(40), //t/m nummer/zoekcode/naam
in @SorterenOp        smallint, //0=Nummer, 1=Zoekcode, 2=Naam, 3=RekeningSoort
in @SoortBoeking      smallint, //0=definitief, 1=voorlopig, 2=beide
in @OokZonderbudget   smallint, //0=Nee (alleen rekeningen met budget), 1=Ja
in @VergelijkMet      smallint, //4=Zoals bij budget, 0=Saldo, 1=Debet, 2=Credit
in @OverzichtInValuta integer)  //Valutanummer waarin bedragen moeten worden afgedrukt


result (RegelSoort integer, KstpCode nchar(26), KstpNaam nchar(40), ValCode nchar(3), ValNummer Integer, Budget numeric(15,2),
        Saldo numeric(15,2), Verschil numeric(15,2), Percentage numeric(15,2),
        JaarBudget numeric(15,2), BudgetCode integer, BudgetOms nchar(40) )

begin

  declare @Teller smallint;
  declare @TotaalValCode nchar(3);
  declare @OverzichtValCode nchar(3);
  declare @koers numeric(9,6);

  declare local temporary table tmpBudget(
     tmpGid                  integer default AutoIncrement,
     KstpCode                nchar(26),
     KstpNaam                nchar(40) default '',
     Valcode                 nchar(3) default  '',
     tmpValNummer            integer,
     SorteerVeld             nchar(40) default '',
     BudVergelijkenMet       smallint,
     BudgetInBasisValuta     numeric(15,2),
     BudgetInValuta          numeric(15,2),
     SaldoInBasisValuta      numeric(15,2),
     SaldoInValuta           numeric(15,2),
     Verschil                numeric(15,2),
     //VerschilTotaal        numeric(15,2) compute (if tmpDefaultBoekzijde = 1 then -(BudgetTotaal - SaldoTotaal) else (BudgetTotaal - SaldoTotaal) endif),
     Percentage              numeric(15,2),
     //PercentageTotaal      numeric(15,2) compute (if BudgetTotaal=0 then 0 else (VerschilTotaal / (if BudgetTotaal<0 and VerschilTotaal<0 then -BudgetTotaal else BudgetTotaal endif) * 100) endif),
     JaarBudgetInBasisValuta numeric(15,2),
     JaarBudgetInValuta      numeric(15,2),
     BudgetCode              integer,
     BudgetOms               nchar(40),
     RegelSoort              integer,
     primary key (tmpGid)
   ) on commit preserve rows;


  set @@ErrorTextProcedure = 'rapBudgetPerKostenplaats > @BjGid='+string(@BjGid)+',@VanPernr='+string(@VanPernr)+',@TotPernr='+string(@TotPernr)+',@SelecteerOp='+string(@SelecteerOp)+',@VanKstp='+@VanKstp+',@TotKstp='+@TotKstp;
  //call TraceBegin(@@ErrorTextProcedure);
  //call trace('rapBudgetPerKostenplaats > @SorterenOp='+string(@SorterenOp)+', @SoortBoeking='+string(@SoortBoeking)+',@OokZonderbudget='+string(@OokZonderbudget)+',@VergelijkMet='+string(@VergelijkMet)+',@OverzichtInValuta='+String(@OverzichtInValuta));

  Create index idx_tmpBudgetSoort     on tmpBudget (Regelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (SorteerVeld);

  set @@ErrorTextProcedure = 'rapBudgetPerKostenplaats > Stap 1';
  //call Trace(@@ErrorTextProcedure);
  set @koers = KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta);

  // gegevens per periode ophalen
  insert into tmpBudget (RegelSoort, KstpCode, KstpNaam, tmpValNummer, ValCode, BudVergelijkenMet,
                         BudgetInBasisValuta, BudgetInValuta, SaldoInBasisValuta, SaldoInValuta,
                         JaarBudgetInBasisValuta, JaarBudgetInValuta, BudgetCode, BudgetOms, SorteerVeld)
  select   1,
           KstpCode,
           KstpNaam,
          @OverzichtInValuta tmpValNummer,
          (select ValCode from tabValuta where ValNummer = tmpValNummer),
           if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then // saldo, debet of credit
             IsNull(VergelijkenMet,0)
           else
             if @VergelijkMet = 4 then
               0 // saldo
             else
               @VergelijkMet // debet of credit
             endif
           endif BudVergelijkenMet, //0=saldo, 1=debet, 2=credit
           // BedragInBasis :
           if BudgetGid is not null then
             // Kstp heeft een budget, die dus gebruiken!
             if BudMetVerdeling = 1 then
               // Kstp heeft een jaarbudget -> jaarbudget * (totaal budget% van de perioderange) berekenen
               round(JaarBudget * (Bud_CumPercentage(@BjGid, @VanPerNr, @TotPerNr, BudBudgetCode)/100),2)
             else
               // Kstp heeft budget per periode -> perioderange optellen
               (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = BudgetGid and BudBedrPerNr between @VanPerNr and @TotPerNr)
             endif
           else
             // Kstp heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstp (in basisvalua) berekenen
             sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                 ValutaOmrekenen(RksValNummer,
                                       (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                     // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                     round(tabRksBudget.JaarBudget * (Bud_CumPercentage(@BjGid, @VanPerNr, @TotPerNr, tabRksBudget.BudBudgetCode)/100),2)
                                                   else
                                                     // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                     (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = tabRksBudget.BudgetGid and BudBedrPerNr between @VanPerNr and @TotPerNr)
                                                   endif
                                                  )
                                        from      tabBudget tabRksBudget
                                        where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid) // ACW 01-10-2002: test op @BjGid toegevoegd
                                       , @@BasisValutaNummer, @BjGid, @TotPernr, 2
                                      )
                )
           endif BedragInBasisValuta,
           // BedragInValuta :
           if BudgetGid is not null then
              // Kstp heeft zelf een budget, dus gewoon omrekenen
              BedragInBasisValuta / @Koers
           else
             // Kstp heeft geen budget, dus rekeningtotalen nogmaals berekenen, nu naar afdrukvaluta
             sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                 ValutaOmrekenen(RksValNummer,
                                       (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                     // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                     round(tabRksBudget.JaarBudget * (Bud_CumPercentage(@BjGid, @VanPerNr, @TotPerNr, tabRksBudget.BudBudgetCode)/100),2)
                                                   else
                                                     // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                     (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = tabRksBudget.BudgetGid and BudBedrPerNr between @VanPerNr and @TotPerNr)
                                                   endif
                                                  )
                                        from      tabBudget tabRksBudget
                                        where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid) // ACW 01-10-2002: test op @BjGid toegevoegd
                                       , @OverzichtInValuta, @BjGid, @TotPernr, 2
                                      )
                )
           endif BedragInValuta,
           case @SoortBoeking
             when 0 then // Definitief
               case isnull(BudVergelijkenMet,0)
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0)
               end
             when 1 then  //Voorlopig
               case isnull(BudVergelijkenMet,0)
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
             else
               case isnull(BudVergelijkenMet,0)
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0) - IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
           end SaldoInBasisValuta,
           SaldoInBasisValuta / @Koers SaldoInValuta,
           // JaarbudgetInBasisValuta :
           IsNull(if BudgetGid is not null then
                    // Kstp heeft een budget
                    if BudMetVerdeling = 1 then
                      JaarBudget
                    else
                      (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = BudgetGid)
                    endif
                  else
                   // Kstp heeft geen budget, dus totaal jaarbudget van de rekeningen opvragen
                   sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                       ValutaOmrekenen(RksValNummer,
                                             (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                           // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                           tabRksBudget.JaarBudget
                                                         else
                                                           // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                           (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                         endif
                                                        )
                                              from      tabBudget tabRksBudget
                                              where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid) // ACW 01-10-2002: test op @BjGid toegevoegd
                                             , @@basisvalutanummer, @BjGid, @TotPernr, 2
                                            )
                      )
                  endif
                 , 0) JaarbudgetInBasisValuta,
          JaarBudgetInBasisValuta / @Koers JaarBudgetInValuta,
           BudBudgetCode,
          (select BudgetOms from tabBudgetCode where BudgetCode = BudBudgetCode) BudgetOms,
          (if @SorterenOp = 0 then KstpCode else if @SorterenOp = 1 then KstpZoekcode else KstpNaam endif endif)
  from     tabKostenplaats
           left outer join tabBudget         BudgetBuiten on (BudKstpgid     = KstpGid and BudBjGid = @BjGid)
           left outer join (           tabRekeningschema RksBuiten
                            left outer join (select sum(SaldoDebetBasisDefinitief  ) SaldoDebetBasisDefinitief,
                                                    sum(SaldoDebetBasisVoorlopig   ) SaldoDebetBasisVoorlopig,
                                                    sum(SaldoDebetValutaDefinitief ) SaldoDebetValutaDefinitief,
                                                    sum(SaldoDebetValutaVoorlopig  ) SaldoDebetValutaVoorlopig,
                                                    sum(SaldoCreditBasisDefinitief ) SaldoCreditBasisDefinitief,
                                                    sum(SaldoCreditBasisVoorlopig  ) SaldoCreditBasisVoorlopig,
                                                    sum(SaldoCreditValutaDefinitief) SaldoCreditValutaDefinitief,
                                                    sum(SaldoCreditValutaVoorlopig ) SaldoCreditValutaVoorlopig,
                                                    RekSaldoRksGid
                                             from   tabRekeningsaldo
                                             where (RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
                                             group by RekSaldoRksGid
                                            ) RekSaldoTotaalPerKrs on (RekSaldoRksGid = RksGid)
                           ) on (    (RksKstpGid     = KstpGid)
                                 // ACW 15-03-2007: vinkje in voorloopscherm ook van invloed op Rks
                                 and (   (@OokZonderbudget = 1) // Alleen de rekening opnemen als ook zonder budgetten OF kstp heeft budget OF rekening heeft budget!!
                                      or (BudgetBuiten.BudKstpgid is not null)
                                      or (exists(select first 1 from tabBudget RksBudget where RksBudget.BudRksGid = RksGid and RksBudget.BudBjGid = @BjGid))
                                     )
                                )

//           tabRekeningsaldo  on (RekSaldoRksGid = RksGid and RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
  where  ((KstpCode     between @VanKstp and @TotKstp and @SelecteerOp = 0)  or
          (KstpZoekcode between @VanKstp and @TotKstp and @SelecteerOp = 1)  or
          (KstpNaam     between @VanKstp and @TotKstp and @SelecteerOp = 2))
  group by KstpCode, kstpZoekcode, KstpNaam, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid;

  set @@ErrorTextProcedure = 'rapBudgetPerKostenplaats > Stap 4';
  //call Trace(@@ErrorTextProcedure);
  if @OokZonderbudget = 0 then
    delete tmpBudget
    where  kstpcode not in (select KstpCode from tabBudget inner join tabKostenplaats on (KstpGid = BudKstpGid) where BudBjGid = @BjGid) and // Heeft zelf geen budget
           Kstpcode not in (select KstpCode from tabRekeningSchema inner join tabBudget on BudRksGid = RksGid inner join tabKostenplaats on KstpGid = RksKstpGid where BudBjGid = @BjGid) // Heeft geen rekeningen met het budget
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerKostenplaats > Totaal generaal';
  //call Trace(@@ErrorTextProcedure);
  if exists( select 1 from tmpBudget) then
    insert into tmpBudget (RegelSoort, SorteerVeld, KstpNaam, ValCode, tmpValNummer, BudgetInValuta, SaldoInValuta,
                           JaarBudgetInValuta)
    select   99,
             repeat('z',40),
             _U('Van kostenpl. %1! t/m %2!', @VanKstp, @TotKstp),
             (select ValCode from tabValuta where ValNummer = @OverzichtInValuta),
             @OverzichtInValuta,
             sum(BudgetInBasisValuta)     / @Koers tmpBudgetInValuta,
             sum(SaldoInBasisValuta)      / @Koers tmpSaldoInValuta,
             sum(JaarBudgetInBasisValuta) / @Koers tmpJaarbudgetInValuta
    from     tmpBudget where RegelSoort = 1;
  end if;

  update tmpBudget set Verschil     = (isnull(SaldoInValuta,0) - isnull(BudgetInValuta,0)) * (if isnull(BudgetInValuta,0) < 0 then -1 else 1 endif);
  update tmpBudget set Percentage   = (if BudgetInValuta = 0 then 0 else abs(Verschil) / abs(BudgetInValuta) * if sign(Verschil)=-1 then -1 else 1 endif endif * 100);

  set @@ErrorTextProcedure = 'rapBudgetPerKostenplaats';
  //call TraceEind(@@ErrorTextProcedure);

  select RegelSoort, KstpCode, KstpNaam, ValCode, tmpValNummer, BudgetInValuta Budget, SaldoInValuta Saldo, Verschil, Percentage,
         JaarBudgetInValuta JaarBudget, BudgetCode, BudgetOms
  from   tmpBudget
  order by SorteerVeld;


end;

//call rapBudgetPerKostenplaats(3, 0, 12, 0, '00000000', '99999999', 0, 2, 1, 1, 5);
//call rapBudgetPerKostenplaats(2, 0, 12, 0, '00000000', '99999999', 0, 2, 0, 3, 0);


//$Workfile: rapBudgetPerkostenplaatsPerPeriode.sp $ $Revision: 4 $ $Modtime: 31-08-07 15:54 $

if exists (select 1 from sys.sysProcedure where proc_name='rapBudgetPerkostenplaatsPerPeriode') then
  drop procedure rapBudgetPerkostenplaatsPerPeriode;
end if;

create procedure rapBudgetPerkostenplaatsPerPeriode(
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @SelecteerOp       smallint,      //0 = kstpnummer, 1=kstpzoekcode, 2=kstpnaam
in @VanKstp           nchar(40),      //van nummer/zoekcode/naam
in @TotKstp           nchar(40),      //t/m nummer/zoekcode/naam
in @SorterenOp        smallint,      //0=Nummer, 1=Zoekcode, 2=Naam
in @SoortBoeking      smallint,      //0=definitief, 1=voorlopig, 2=beide
in @OokZonderbudget   smallint,      //0=Nee (alleen rekeningen met budget), 1=Ja
in @VergelijkMet      smallint,      //4=Zoals bij budget, 0=Saldo, 1=Debet, 2=Credit
in @OverzichtInValuta integer,       //Valutanummer waarin bedragen moeten worden afgedrukt
in @1PlusMinTeken     numeric(6,2),  //Bij welke percentage een +  of -  afdrukken
in @2PlusMinTeken     numeric(6,2))  //Bij welke percentage een ++ of -- afdrukken

result (tmpRegelSoort integer, tmpkstpcode nchar(26), tmpKstpNaam nchar(40), tmpPernr integer, tmpBeginDatum date, tmpEindDatum date,
        tmpBudgetInValuta numeric(15,2), tmpBudgetPercentage numeric(6,2), tmpSaldoInValuta numeric(15,2),
        tmpVerschil numeric(15,2), tmpPercentage numeric(15,2), tmpPlusMinTeken nchar(2), tmpSorteerveld nchar(40), tmpStreepVoorPercentage smallint)

begin

  declare @Teller           smallint;
  declare @TotaalValCode    nchar(3);
  declare @OverzichtValCode nchar(3);
  declare @koers            double;
  declare @MaxPerNr         integer;
  declare @HeleJaar         smallint;

  declare local temporary table tmpBudget(
     tmpGid                  integer default AutoIncrement,
     tmpkstpcode             nchar(26),
     tmpKstpNaam             nchar(40) default '',
     tmpPernr                integer,
     tmpBeginDatum           date,
     tmpEindDatum            date,
     tmpBudgetInBasisValuta  numeric(15,2),
     tmpBudgetInValuta       numeric(15,2),
     tmpPlusMinTeken         nchar(2),
     tmpSaldoInValuta        numeric(15,2),
     tmpSaldoInBasisValuta   numeric(15,2),
     tmpVerschil             numeric(15,2),
     tmpPercentage           numeric(15,2),
     tmpSorteerVeld          nchar(40) default '',
     tmpBudgetPercentage     numeric(6,2),
     tmpRegelSoort           integer,
     tmpBudgetGid            integer,
     primary key (tmpGid)
   ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapBudgetPerkostenplaatsPerPeriode > @VanKstp='+@VanKstp+', @TotKstp='+@TotKstp;
  //call TraceBegin(@@ErrorTextProcedure);

  Create index idx_tmpBudgetSoort     on tmpBudget (tmpRegelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (tmpSorteerVeld);

  set @@ErrorTextProcedure = 'rapBudgetPerkostenplaatsPerPeriode > Stap 1';
  //call Trace(@@ErrorTextProcedure);

  set @koers = KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta);

  select max(PerNr) into @MaxPerNr from tabPeriode where PerBjGid = @BjGid;
  set @HeleJaar = if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then 1 else 0 endif;

  // gegevens per periode ophalen
  insert into tmpBudget (tmpRegelSoort, tmpPernr, tmpBeginDatum, tmpEindDatum, tmpkstpcode, tmpKstpNaam,
                         tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpBudgetPercentage,
                         tmpSaldoInBasisValuta, tmpSaldoInValuta, tmpVerschil, tmpPercentage, tmpPlusMinTeken,
                         tmpSorteerVeld, tmpBudgetGid)
  select   1,
           Pernr,
           BeginDatum,
           EindDatum,
           kstpcode,
           KstpNaam,
//           IsNull(if BudMetVerdeling = 1 then (select JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = BudBudgetCode)
//                                         else (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = BudgetGid) endif, 0) tmpBudgetInBasisValuta,
           // tmpBudgetInBasisValuta :
           if BudgetGid is not null then
             // Kstp heeft een budget, die dus gebruiken!
             if BudMetVerdeling = 1 then
               // Kstp heeft een jaarbudget -> jaarbudget * (totaal budget% van de perioderange) berekenen
               if @HeleJaar = 1 and PerNr = @MaxPerNr then
                  JaarBudget - (select sum(round(BudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2))
                                from tabBudget BudgetBinnen inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr <> @MaxPerNr and BudPerBudgetCode = BudgetBinnen.BudBudgetCode)
                                where BudgetBinnen.BudgetGid = BudgetBuiten.BudgetGid)
                else
                 (select JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = BudBudgetCode)
                endif
             else
               // Kstp heeft budget per periode -> perioderange optellen
               (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = BudgetGid)
             endif
           else
             // Kstp heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstp (in basisvalua) berekenen
             sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                 ValutaOmrekenen(RksValNummer,
                                       (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                     // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                     if @HeleJaar = 1 and PerBinnen.PerNr = @MaxPerNr then
                                                       tabRksBudget.JaarBudget - (select sum(round(tabRksBudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2))
                                                                                  from tabBudget tabRksBudgetBinnen inner join tabBudgetCodePeriode on BudPerBjGid = @BjGid and BudPernr<>@MaxPernr and BudPerBudgetCode = tabRksBudgetBinnen.BudBudgetCode
                                                                                  where tabRksBudgetBinnen.BudgetGid = tabRksBudget.BudgetGid)
                                                     else
                                                       (select tabRksBudget.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                     endif
                                                   else
                                                     // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                     (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid = @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                   endif
                                                  )
                                        from      tabBudget tabRksBudget,
                                                  tabPeriode PerBinnen
                                        where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid
                                                  and PerBinnen.PerBjGid = @BjGid and PerBinnen.PerNr = PerBuiten.PerNr
                                        )
                                       , @@BasisValutaNummer, @BjGid, @TotPernr, 2
                                      )
                )
           endif tmpBudgetInBasisValuta,

           // tmpBudgetInValuta :
           if BudgetGid is not null then
             // Kstp heeft een budget, die dus gebruiken!
             tmpBudgetInBasisValuta / @koers
           else
             // Kstp heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstp (in basisvalua) berekenen
             sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                 ValutaOmrekenen(RksValNummer,
                                       (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                     // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                     if @HeleJaar = 1 and PerBinnen.PerNr = @MaxPerNr then
                                                       tabRksBudget.JaarBudget - (select sum(round(tabRksBudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2))
                                                                                  from tabBudget tabRksBudgetBinnen inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr<>@MaxPernr and BudPerBudgetCode = tabRksBudgetBinnen.BudBudgetCode)
                                                                                  where tabRksBudgetBinnen.BudgetGid = tabRksBudget.BudgetGid)
                                                     else
                                                       (select tabRksBudget.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                     endif
                                                   else
                                                     // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                     (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid = @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                   endif
                                                  )
                                        from      tabBudget tabRksBudget,
                                                  tabPeriode PerBinnen
                                        where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid
                                                  and PerBinnen.PerBjGid = @BjGid and PerBinnen.PerNr = PerBuiten.PerNr
                                        )
                                       , @OverzichtInValuta, @BjGid, @TotPernr, 2
                                      )
                )
           endif tmpBudgetInValuta,

          (if BudMetVerdeling = 1 then (select BudPerPercentage from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr =Pernr and BudPerBudgetCode = BudBudgetCode) endif) tmpBudgetPercentage,
           isnull(sum(
           case @SoortBoeking
             when 0 then // Definitief
               case (if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then IsNull(VergelijkenMet,0) else if @VergelijkMet = 4 then case DefaultBoekzijde when 0 then 1 when 1 then 2  else 0 end else @VergelijkMet endif endif)
                 when 0 then  //Saldo
                   isnull(SaldoDebetBasisDefinitief,0) - isnull(SaldoCreditBasisDefinitief,0)
                 when 1 then  //Debet
                   isnull(SaldoDebetBasisDefinitief,0)
                 when 2 then  //Credit
                  isnull(-SaldoCreditBasisDefinitief,0)
               end
             when 1 then  //Voorlopig
               case (if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then IsNull(VergelijkenMet,0) else if @VergelijkMet = 4 then case DefaultBoekzijde when 0 then 1 when 1 then 2  else 0 end else @VergelijkMet endif endif)
                 when 0 then  //Saldo
                   SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig
                 when 1 then  //Debet
                   SaldoDebetBasisVoorlopig
                 when 2 then  //Credit
                  -SaldoCreditBasisVoorlopig
               end
             else
               case (if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then IsNull(VergelijkenMet,0) else if @VergelijkMet = 4 then case DefaultBoekzijde when 0 then 1 when 1 then 2  else 0 end else @VergelijkMet endif endif)
                 when 0 then  //Saldo
                   SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief + (SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig)
                 when 1 then  //Debet
                   SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig
                 when 2 then  //Credit
                  -SaldoCreditBasisDefinitief - SaldoCreditBasisVoorlopig
               end
           end ),0) tmpSaldoInBasisValuta,
           tmpSaldoInBasisValuta / @Koers tmpSaldoInValuta,
           (tmpSaldoInValuta - tmpBudgetInValuta) tmpVerschil,
          (if tmpBudgetInValuta      = 0 then 0 else (tmpVerschil / tmpBudgetInValuta * 100) endif) tmpPercentage,
          (if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif) tmpPlusMinTeken,
          (if @SorterenOp = 0 then kstpcode else if @SorterenOp = 1 then KstpZoekcode else KstpNaam endif endif),
           BudgetGid
  from     (tabPeriode PerBuiten,
           tabKostenplaats)
           left outer join tabBudget         BudgetBuiten on (BudKstpgid     = KstpGid and BudBjGid = @BjGid)
           left outer join tabRekeningschema RksBuiten    on (    (RksKstpGid     = KstpGid)
                                                              // ACW 15-03-2007: vinkje in voorloopscherm ook van invloed op Rks
                                                              and (   (@OokZonderbudget = 1) // Alleen de rekening opnemen als ook zonder budgetten OF kstp heeft budget OF rekening heeft budget!!
                                                                   or (BudgetBuiten.BudKstpgid is not null)
                                                                   or (exists(select first 1 from tabBudget RksBudget where RksBudget.BudRksGid = RksGid and RksBudget.BudBjGid = @BjGid))
                                                                  )
                                                             )
           left outer join tabRekeningsaldo  on (RekSaldoRksGid = RksGid and RekSaldoBjGid=@BjGid and RekSaldoPernr=PerNr)
  where  ((KstpCode     between @VanKstp and @TotKstp and @SelecteerOp = 0)  or
          (KstpZoekcode between @VanKstp and @TotKstp and @SelecteerOp = 1)  or
          (KstpNaam     between @VanKstp and @TotKstp and @SelecteerOp = 2))
          and PerBjGid = @BjGid and Pernr between @VanPernr and @TotPernr
  group by kstpcode, Pernr, BeginDatum, EindDatum, KstpZoekcode, KstpNaam, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid;

  //Bereken voor de laatste periode opnieuw het percentage en totaal budget zodat het totaal overeenkomt met het jaarbudget
  //call trace('Bereken de laatste periode opnieuw?');

/* ACW 17-12-2004: Niet nodig; is hierboven al berekend
  if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then
    //Alleen indien alle periodes worden afgedrukt!
    //call trace('Ja, opnieuw berekenen!');
    update tmpBudget buiten
    set    tmpBudgetInBasisValuta = JaarBudget          - (select sum(tmpBudgetInBasisValuta) from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstpCode = buiten.tmpKstpCode),
           tmpBudgetInValuta      = JaarBudget / @koers - (select sum(tmpBudgetInValuta)      from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstpCode = buiten.tmpKstpCode),
           tmpBudgetPercentage    = 100                 - (select sum(tmpBudgetPercentage)    from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstpCode = buiten.tmpKstpCode)
//           tmpVerschil            = tmpSaldoInValuta - (JaarBudget / @koers - (select sum(tmpBudgetInValuta) from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstpCode = buiten.tmpKstpCode))
    from   tabBudget
    where  tmpPerNr = @MaxPerNr and BudMetVerdeling = 1 and BudgetGid = tmpBudgetGid;
  end if;
*/

  //Eventueel alles eruifilteren waarvoor geen budget is (totaal van budget=0)
  if @OokZonderbudget = 0 then
    delete tmpBudget
    where  tmpkstpcode not in (select KstpCode from tabBudget inner join tabKostenplaats on (KstpGid = BudKstpGid) where BudBjGid = @BjGid) and // Heeft zelf geen budget
           tmpkstpcode not in (select KstpCode from tabRekeningSchema inner join tabBudget on BudRksGid = RksGid inner join tabKostenplaats on KstpGid = RksKstpGid where BudBjGid = @BjGid) // Heeft geen rekeningen met het budget
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerkostenplaatsPerPeriode > Totaal per kostenplaats';
  //call Trace(@@ErrorTextProcedure);
  insert into tmpBudget (tmpRegelSoort, tmpkstpcode, tmpKstpNaam,
                         tmpBudgetInValuta, tmpBudgetInBasisValuta,
                         tmpSaldoInValuta, tmpSaldoInBasisValuta, tmpBudgetPercentage,
                         tmpSorteerVeld)
  select   2,
           tmpkstpcode,
           tmpKstpNaam,
           sum(tmpBudgetInValuta) Budget,
           sum(tmpBudgetInBasisValuta),
           sum(tmpSaldoInValuta),
           sum(tmpSaldoInBasisValuta),
           sum(tmpBudgetPercentage),
           min(tmpSorteerVeld)
  from     tmpBudget
  group by tmpkstpcode, tmpKstpNaam;

  set @@ErrorTextProcedure = 'rapBudgetPerkostenplaatsPerPeriode > Verwijderen rekeningen die geen budget hebben (als dit is meegegeven)';
  //call Trace(@@ErrorTextProcedure);
  if @OokZonderbudget = 0 then
    delete tmpBudget
    where  tmpkstpcode not in (select KstpCode from tabBudget inner join tabKostenplaats on (KstpGid = BudKstpGid) where BudBjGid = @BjGid) and // Heeft zelf geen budget
           tmpKstpcode not in (select KstpCode from tabRekeningSchema inner join tabBudget on BudRksGid = RksGid inner join tabKostenplaats on KstpGid = RksKstpGid where BudBjGid = @BjGid) // Heeft geen rekeningen met het budget
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerkostenplaatsPerPeriode > Totaal generaal';
  //call Trace(@@ErrorTextProcedure);
  if exists( select 1 from tmpBudget) then

    insert into tmpBudget (tmpRegelSoort, tmpSorteerVeld, tmpKstpNaam, tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpSaldoInBasisValuta, tmpSaldoInValuta)
    select   99,
             repeat('z',40),
             _U('Van kostenpl. %1! t/m %2!', @VanKstp, @TotKstp),
             sum(tmpBudgetInBasisValuta) tmpBudgetInBasisValuta,
             sum(tmpBudgetInValuta)      tmpBudgetInValuta,
             sum(tmpSaldoInBasisValuta)  tmpSaldoInBasisValuta,
             sum(tmpSaldoInValuta)       tmpSaldoInValuta
    from     tmpBudget where tmpRegelSoort = 2;
  end if;

  update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
  update tmpBudget set tmpPercentage   = (if isnull(tmpBudgetInValuta,0) = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
  update tmpBudget set tmpPlusMinTeken = if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif;

  //call TraceEind(@@ErrorTextTrigger);
  select tmpRegelSoort, tmpkstpcode, tmpKstpNaam, tmpPernr, tmpBeginDatum, tmpEindDatum,
         tmpBudgetInValuta,
         tmpBudgetPercentage, tmpSaldoInValuta, tmpVerschil, tmpPercentage, tmpPlusMinTeken,
         tmpSorteerveld, if tmpBudgetPercentage is null or tmpRegelSoort = 99 then 0 else 1 endif tmpStreepVoorPercentage
  from   tmpBudget order by tmpSorteerVeld, tmpRegelSoort, tmpPernr;


end;
//call rapBudgetPerkostenplaatsPerPeriode(2, 1, 12, 0, '00000000', '9999999', 0, 1, 0, 0, 0, 5, 20);


create or replace procedure rapBudgetPerKstdPerPeriodeNaastElkaar(
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @SelecteerOp       smallint,      //0 = KstdCode, 1=Kstdzoekcode, 2=Kstdnaam
in @VanKstd           nchar(40),      //van nummer/zoekcode/naam
in @TotKstd           nchar(40),      //t/m nummer/zoekcode/naam
in @SorterenOp        smallint,      //0=Nummer, 1=Zoekcode, 2=Naam
in @SoortBoeking      smallint,      //0=definitief, 1=voorlopig, 2=beide
in @OokZonderbudget   smallint,      //0=Nee (alleen Kostendragers met budget), 1=Ja
in @VergelijkMet      smallint,      //4=Zoals bij budget, 0=Saldo, 1=Debet, 2=Credit
in @OverzichtInValuta integer,       //Valutanummer waarin bedragen moeten worden afgedrukt
in @1PlusMinTeken     numeric(6,2),  //Bij welke percentage een +  of -  afdrukken
in @2PlusMinTeken     numeric(6,2))  //Bij welke percentage een ++ of -- afdrukken

result(tmpRegelSoort integer, tmpKstdCode nchar(26), tmpKstdNaam nchar(40), tmpPernr integer, tmpValCode nchar(3),
       tmpBudgetInValuta numeric(15,2), tmpSaldoInValuta numeric(15,2), tmpVerschil numeric(15,2), tmpPercentage numeric(15,2),
       tmpSorteerveld nchar(40), tmpPeriode1 nchar(2),
       tmpPeriode2 nchar(2), tmpPeriode3 nchar(2), tmpPeriode4 nchar(2), tmpPeriode5 nchar(2), tmpPeriode6 nchar(2),
       tmpPeriode7 nchar(2), tmpPeriode8 nchar(2), tmpPeriode9 nchar(2), tmpPeriode10 nchar(2), tmpPeriode11 nchar(2),
       tmpPeriode12 nchar(2), tmpPeriode13 nchar(2),tmpBudgetGid integer)

begin

  declare @Teller           smallint;
  declare @Koers            double;
  declare @OverzichtValCode nchar(3);
  declare @ValCode          nchar(3);
  declare @MaxPerNr         integer;
  declare @HeleJaar         smallint;

  declare local temporary table tmpBudget(
     tmpGid                     integer default AutoIncrement,
     tmpKstdCode                nchar(26),
     tmpKstdNaam                nchar(40) default '',
     tmpPernr                   integer,
     tmpBudgetInBasisValuta     numeric(15,2),
     tmpBudgetInValuta          numeric(15,2),
     tmpPlusMinTeken            nchar(2),
     tmpSaldoInValuta           numeric(15,2),
     tmpSaldoInBasisValuta      numeric(15,2),
     tmpVerschil                numeric(15,2),
     tmpPercentage              numeric(15,2),
     tmpSorteerVeld             nchar(40) default '',
     tmpRegelSoort              integer,
     tmpBudgetGid               integer,
     tmpPeriode1                nchar(2),
     tmpPeriode2                nchar(2),
     tmpPeriode3                nchar(2),
     tmpPeriode4                nchar(2),
     tmpPeriode5                nchar(2),
     tmpPeriode6                nchar(2),
     tmpPeriode7                nchar(2),
     tmpPeriode8                nchar(2),
     tmpPeriode9                nchar(2),
     tmpPeriode10               nchar(2),
     tmpPeriode11               nchar(2),
     tmpPeriode12               nchar(2),
     tmpPeriode13               nchar(2),
     primary key (tmpGid)
   ) on commit preserve rows;

  //call TraceBegin('rapBudgetPerKstdPerPeriodeNaastElkaar(@BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+', @VanKstd='+string(@VanKstd)+', @TotKstd='+string(@TotKstd)+', @SorterenOp='+string(@SorterenOp)+', @SoortBoeking='+string(@SoortBoeking)+', @OokZonderbudget='+string(@OokZonderbudget)+', @VergelijkMet='+string(@VergelijkMet)+', @OverzichtInValuta'+string(@OverzichtInValuta)+', @1PlusMinTeken='+string(@1PlusMinTeken)+', @2PlusMinTeken'+string(@2PlusMinTeken));

  Create index idx_tmpBudgetSoort     on tmpBudget (tmpRegelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (tmpSorteerVeld);
  Create index idx_tmpBudgetPernr     on tmpBudget (tmpKstdCode, tmpPernr);

  //call Trace('Stap 1');

  set @Koers = KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta);
  select max(PerNr) into @MaxPerNr from tabPeriode where PerBjGid = @BjGid;
  set @HeleJaar = if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then 1 else 0 endif;

//  if (@TotPernr - @VanPernr) <= 12 then
    // gegevens per periode ophalen
    insert into tmpBudget (tmpRegelSoort, tmpPernr, tmpKstdCode, tmpKstdNaam,
                           tmpBudgetInBasisValuta, tmpBudgetInValuta,
                           tmpSaldoInBasisValuta, tmpSaldoInValuta, tmpSorteerVeld, tmpBudgetGid)
    select   1,
             Pernr,
             KstdCode,
             KstdNaam,

             // tmpBudgetInBasisValuta :
             if BudgetGid is not null then
               // Kstd heeft een budget, die dus gebruiken!
               if BudMetVerdeling = 1 then
                 // Kstd heeft een jaarbudget -> jaarbudget * (totaal budget% van de perioderange) berekenen
                 if @HeleJaar = 1 and PerNr = @MaxPerNr then
                   Jaarbudget - (select sum(round(BudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2)) from
                   tabBudget BudgetBinnen inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr<>Pernr and BudPerBudgetCode = BudgetBinnen.BudBudgetCode) where BudKstdgid = KstdGid and BudBjGid = @BjGid)
                 else
                   (select JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = BudBudgetCode)
                 endif
               else
                 // Kstd heeft budget per periode -> perioderange optellen
                 (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = BudgetGid)
               endif
             else
               // Kstd heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstd (in basisvalua) berekenen
               sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                   ValutaOmrekenen(RksValNummer,
                                         (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                       // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                       if @HeleJaar = 1 and @MaxPerNr = PerBinnen.PerNr then
                                                         // Gehele jaar, dus budget laatste periode = Jaarbudget - andere periodes
                                                         tabRksBudget.JaarBudget - (select sum(round(/*tabRksBudgetBinnen.JaarBudget */ Bud_PercAfronden(0.25 /*BudPerPercentage*/) / 100,2)) from
                                                         tabBudget tabRksBudgetBinnen inner join tabBudgetCodePeriode PerBinnen on PerBinnen.BudPerBjGid = @BjGid and PerBinnen.BudPernr<>@TotPernr and PerBinnen.BudPerBudgetCode = tabRksBudgetBinnen.BudBudgetCode
                                                         where tabRksBudgetBinnen.BudgetGid = tabRksBudget.BudgetGid)
                                                       else
                                                         (select tabRksBudget.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                       endif
                                                     else
                                                       // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                       (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                     endif
                                                    )
                                          from      tabBudget tabRksBudget,
                                                    tabPeriode PerBinnen
                                          where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid
                                                    and PerBinnen.PerBjGid = @BjGid and PerBinnen.PerNr = PerBuiten.PerNr
                                          ) // ACW 01-10-2002: test op @BjGid toegevoegd

                                         , @@BasisValutaNummer, @BjGid, @TotPernr, 2
                                        )
               )
             endif tmpBudgetInBasisValuta,
             // tmpBudgetInValuta :
             if BudgetGid is not null then
               // Kstd heeft een budget, die dus gebruiken!
              tmpBudgetInBasisValuta / @Koers
             else
               // Kstd heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstd (in basisvalua) berekenen
               sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                   ValutaOmrekenen(RksValNummer,
                                         (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                       // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                       if @HeleJaar = 1 and PerNr = @MaxPerNr then
                                                         // Gehele jaar, dus budget laatste periode = Jaarbudget - andere periodes
                                                         tabRksBudget.JaarBudget - (select sum(round(tabRksBudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2)) from
                                                         tabBudget tabRksBudgetBinnen inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr<>Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                         where tabRksBudgetBinnen.BudgetGid = tabRksBudget.BudgetGid)
                                                       else
                                                         (select tabRksBudget.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                       endif
                                                     else
                                                       // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                       (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                     endif
                                                    )
                                          from      tabBudget tabRksBudget,
                                                    tabPeriode PerBinnen
                                          where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid
                                                    and PerBinnen.PerBjGid = @BjGid and PerBinnen.PerNr = PerBuiten.PerNr
                                          ) // ACW 01-10-2002: test op @BjGid toegevoegd
                                         , @OverzichtInValuta, @BjGid, @TotPernr, 2
                                        )
               )
             endif tmpBudgetInValuta,


             isnull(sum(
               case FunBudgetBepaalWelkeVergelijk(@VergelijkMet, (select BudgetRks.VergelijkenMet from tabBudget BudgetRks where BudRksGid = RksGid and BudBjGid = @BjGid), VergelijkenMet, DefaultBoekzijde) // ACW 01-10-2002: test op @BjGid toegevoegd
                 when 0 then // Saldo
                   case @SoortBoeking
                     when 0 then // Definitief
                         IsNull(SaldoDebetBasisDefinitief,0) - IsNull(SaldoCreditBasisDefinitief,0)
                     when 1 then // Voorlopig
                         IsNull(SaldoDebetBasisVoorlopig,0) - IsNull(SaldoCreditBasisVoorlopig,0)
                     else        // Definitief + Voorlopig
                         IsNull(SaldoDebetBasisDefinitief,0) - IsNull(SaldoCreditBasisDefinitief,0) + IsNull(SaldoDebetBasisVoorlopig,0) - IsNull(SaldoCreditBasisVoorlopig,0)
                   end
                 when 1 then // Debet
                   case @SoortBoeking
                     when 0 then // Definitief
                         SaldoDebetBasisDefinitief
                     when 1 then // Voorlopig
                         SaldoDebetBasisVoorlopig
                     else        // Definitief + Voorlopig
                         IsNull(SaldoDebetBasisDefinitief,0) + IsNull(SaldoDebetBasisVoorlopig,0)
                   end
                 when 2 then // Credit
                   case @SoortBoeking
                     when 0 then // Definitief
                        -SaldoCreditBasisDefinitief
                     when 1 then // Voorlopig
                        -SaldoCreditBasisVoorlopig
                     else        // Definitief + Voorlopig
                        -IsNull(SaldoCreditBasisDefinitief,0) - IsNull(SaldoCreditBasisVoorlopig,0)
                   end
               end
             ),0) tmpSaldoInBasisValuta,
             tmpSaldoInBasisValuta / @Koers tmpSaldoInValuta,
            (if @SorterenOp = 0 then KstdCode else if @SorterenOp = 1 then KstdZoekcode else KstdNaam endif endif),
             BudgetGid
    from    (tabPeriode PerBuiten,
             tabKostendrager)
             left outer join tabBudget         BudgetBuiten on (BudKstdgid = KstdGid and BudBjGid = @BjGid)
             left outer join tabRekeningschema RksBuiten    on (     (RksKstdGid = KstdGid)
                                                                 // ACW 15-03-2007: vinkje in voorloopscherm ook van invloed op Rks
                                                                 and (   (@OokZonderbudget = 1) // Alleen de rekening opnemen als ook zonder budgetten OF kstp heeft budget OF rekening heeft budget!!
                                                                      or (BudgetBuiten.BudKstdgid is not null)
                                                                      or (exists(select first 1 from tabBudget RksBudget where RksBudget.BudRksGid = RksGid and RksBudget.BudBjGid = @BjGid))
                                                                     )
                                                                )
             left outer join tabRekeningsaldo  on (RekSaldoBjGid=@BjGid and RekSaldoRksGid=RksGid and RekSaldoPernr = Pernr)
    where    PerBjGid = @BjGid and
           ((KstdCode     between @VanKstd and @TotKstd and @SelecteerOp = 0)  or
            (KstdZoekcode between @VanKstd and @TotKstd and @SelecteerOp = 1)  or
            (KstdNaam     between @VanKstd and @TotKstd and @SelecteerOp = 2)) and
             Pernr between @VanPernr and @TotPernr
    group by KstdGid, KstdCode, Pernr, KstdZoekcode, KstdNaam, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid;


    //Bereken voor de laatste periode opnieuw het percentage en totaal budget zodat het totaal overeenkomt met het jaarbudget
    //call trace('Bereken de laatste periode opnieuw?');
/* ACW 17-12-2004: Berekening is hierboven al opgenomen en dus niet meer nodig!
    if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then
      //Alleen indien alle periodes worden afgedrukt! Let op: in 3 stappen!!
      //call trace('Ja, opnieuw berekenen!');
      update tmpBudget buiten
      set    tmpBudgetInBasisValuta = JaarBudget -          (select sum(tmpBudgetInBasisValuta) from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstdCode = buiten.tmpKstdCode),
             tmpBudgetInValuta      = JaarBudget / @Koers - (select sum(tmpBudgetInValuta)      from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstdCode = buiten.tmpKstdCode)
      from   tabBudget
      where  tmpPerNr = @MaxPerNr and BudMetVerdeling = 1 and BudgetGid = tmpBudgetGid;
    end if;
*/

    //call Trace('Nu nog even percentage bepalen');
    update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
    update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
    update tmpBudget set tmpPlusMinTeken = if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif;

    //call Trace('Werk alle perioden bij');
    update tmpBudget set tmpPeriode1      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =     @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode2      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 1 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode3      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 2 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode4      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 3 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode5      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 4 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode6      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 5 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode7      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 6 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode8      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 7 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode9      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 8 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode10     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 9 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode11     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 10 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode12     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 11 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpPeriode13     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 12 + @VanPernr and a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpBudgetInValuta= (select sum(tmpBudgetInValuta) from tmpBudget a where a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpSaldoInValuta = (select sum(tmpSaldoInValuta)  from tmpBudget a where a.tmpKstdCode = tmpBudget.tmpKstdCode),
                         tmpVerschil      = (select sum(tmpVerschil)       from tmpBudget a where a.tmpKstdCode = tmpBudget.tmpKstdCode)
    where tmpPernr = @VanPernr;

    //call Trace('Verwijder alles dat ongelijk is aan VanPernr');
    delete tmpBudget where tmpPernr <> @VanPernr;

    //call Trace('Verwijderen Kostendragers die geen budget hebben (als dit is meegegeven)');
    if @OokZonderbudget = 0 then
      delete tmpBudget
      where  tmpKstdcode not in (select KstdCode from tabBudget inner join tabKostendrager on (KstdGid = BudKstdGid) where BudBjGid = @BjGid) and // Heeft zelf geen budget
             tmpKstdcode not in (select KstdCode from tabRekeningSchema inner join tabBudget on BudRksGid = RksGid inner join tabKostendrager on KstdGid = RksKstdGid where BudBjGid = @BjGid) // Heeft geen rekeningen met het budget
    end if;

    //call Trace('Nu nog even percentage bepalen');
    update tmpBudget set tmpPercentage = (if tmpBudgetInValuta = 0 then 0 else (tmpVerschil / tmpBudgetInValuta * 100) endif);

    //call Trace('Totaal generaal');

    if exists( select 1 from tmpBudget) then

      insert into tmpBudget (tmpRegelSoort, tmpSorteerVeld, tmpKstdCode, tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpSaldoInBasisValuta, tmpSaldoInValuta)
      select   99,
               repeat('z',40),
               _U('Van kostenpl. %1! t/m %2!', @VanKstd, @TotKstd),
               sum(tmpBudgetInBasisValuta) tmpBudgetInBasisValuta,
               sum(tmpBudgetInValuta)      tmpBudgetInValuta,
               sum(tmpSaldoInBasisValuta)  tmpSaldoInBasisValuta,
               sum(tmpSaldoInValuta)       tmpSaldoInValuta
      from     tmpBudget where tmpRegelSoort = 1;
    end if;

    select ValCode into @ValCode from tabValuta where ValNummer = @OverzichtInValuta;

    //call Trace('Nu nog even percentage bepalen');
    update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
    update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
    update tmpBudget set tmpPlusMinTeken = if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif;

    //call TraceEind('rapBudgetPerKstdPerPeriodeNaastElkaar');

    select   tmpRegelSoort, tmpKstdCode, tmpKstdNaam, tmpPernr, @ValCode tmpValCode, tmpBudgetInValuta,
             tmpSaldoInValuta, tmpVerschil, tmpPercentage,
             tmpSorteerveld,
             tmpPeriode1, tmpPeriode2, tmpPeriode3, tmpPeriode4, tmpPeriode5, tmpPeriode6,
             tmpPeriode7, tmpPeriode8, tmpPeriode9, tmpPeriode10, tmpPeriode11, tmpPeriode12, tmpPeriode13,tmpBudgetGid
    from     tmpBudget
    order by tmpSorteerVeld, tmpRegelSoort, tmpPernr;

//  else
//    select * from dummy where 1=0
//  end if;


end;

//call rapBudgetPerKstdPerPeriodeNaastElkaar(3, 1, 12, 0, '', '99999999', 0, 2, 1, 4, 5, 5, 20);


create or replace procedure rapBudgetPerKstpKstdPerRekening(
in @IsKstp            smallint,     //0 = Kstd, 1 = Kstp
in @KstpdCode         nchar(8),
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @SoortBoeking      smallint,      //0=definitief, 1=voorlopig, 2=beide
in @VergelijkMet      smallint,      //4=Zoals bij budget, 0=Saldo, 1=Debet, 2=Credit
in @OverzichtInValuta integer,       //Valutanummer waarin bedragen moeten worden afgedrukt
in @1PlusMinTeken     numeric(6,2),  //Bij welke percentage een +  of -  afdrukken
in @2PlusMinTeken     numeric(6,2),  //Bij welke percentage een ++ of -- afdrukken
in @OokZonderbudget   smallint)      //0=rekeningen zonder budget NIET meenemen, 1=rekeningen zonder budget toch meenemen


//result(RksInvoer nchar(28), RksNaam nchar(40), Saldo numeric(15,2))
begin
  declare @KstpdGid        integer;
  declare @Koers           double;
  declare @MaxPerNr        integer;
  // t.b.v. extra NietVerbijzonderen-regel
  declare @BudgetGid       integer;
  declare @BudMetVerdeling smallint;
  declare @JaarBudget      numeric(15,2);
  declare @BudBudgetCode   integer;


  declare local temporary table tmpBudget(
     tmpGid                  integer default AutoIncrement,
     tmpRksGid               integer,
     tmpDefaultBoekzijde     smallint,
     tmpPernr                integer,
     tmpPosOfNeg             smallint,
     tmpBudgetInRksValuta    numeric(15,2),
     tmpBudgetInBasisValuta  numeric(15,2),
     tmpBudgetInValuta       numeric(15,2),
     tmpPlusMinTeken         nchar(2),
     tmpSaldoInValuta        numeric(15,2),
     tmpSaldoInBasisValuta   numeric(15,2),
     tmpVerschil             numeric(15,2),
     tmpPercentage           numeric(15,2),
     tmpBudVergelijkenMet    smallint,
     tmpBudgetPercentage     numeric(6,2),
     tmpBudgetGid            integer,
     tmpPeriode1             nchar(2),
     tmpPeriode2             nchar(2),
     tmpPeriode3             nchar(2),
     tmpPeriode4             nchar(2),
     tmpPeriode5             nchar(2),
     tmpPeriode6             nchar(2),
     tmpPeriode7             nchar(2),
     tmpPeriode8             nchar(2),
     tmpPeriode9             nchar(2),
     tmpPeriode10            nchar(2),
     tmpPeriode11            nchar(2),
     tmpPeriode12            nchar(2),
     tmpPeriode13            nchar(2),
     primary key (tmpGid)
   ) on commit preserve rows;

  declare @VergelijkenMetVanKstpd integer; // Vergelijk budget met de rekening

  //call traceBegin('rapBudgetPerKstpKstdPerRekening(@IsKstp='+string(@IsKstp)+', @KstpdCode='+string(@KstpdCode)+', @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SoortBoeking='+string(@SoortBoeking)+', @VergelijkMet='+string(@VergelijkMet)+', @OverzichtInValuta='+string(@OverzichtInValuta)+', @1PlusMinTeken='+string(@1PlusMinTeken)+', @2PlusMinTeken='+string(@2PlusMinTeken)+')');

  Create index idx_tmpBudgetPernr     on tmpBudget (tmpRksGid, tmpPernr);

  set @Koers = KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta);

  select max(PerNr) into @MaxPerNr from tabPeriode where PerBjGid = @BjGid;

  if @IsKstp = 1 then
    select KstpGid into @KstpdGid from tabKostenplaats where KstpCode = @KstpdCode;
    if @VergelijkMet = 4 then // Als niet volgens budget, dan hoeven we helemaal niet op te halen hoe het budget moet worden aangegeven
      select VergelijkenMet into @VergelijkenMetVanKstpd from tabBudget where BudKstpGid = @KstpdGid and BudBjGid = @BjGid;
    end if;
  else
    select KstdGid into @KstpdGid from tabKostendrager where KstdCode = @KstpdCode;
    if @VergelijkMet = 4 then // Als niet volgens budget, dan hoeven we helemaal niet op te halen hoe het budget moet worden aangegeven
      select VergelijkenMet into @VergelijkenMetVanKstpd from tabBudget where BudKstdGid = @KstpdGid and BudBjGid = @BjGid;
    end if;
  end if;

  //call trace('@KstpdGid='+string(@KstpdGid)+', @VergelijkMet='+string(@VergelijkMet)+', @VergelijkenMetVanKstpd='+string(@VergelijkenMetVanKstpd));

  // Stap 1: Per rks + periode: een regel met daarin: - RksGid, Budget in periode, Saldo in periode
  // Stap 2: Daarna teruggeven: Rekening, Naam, sum(Budget), sum(saldo), sum(budget-saldo), sum(budget-saldo)/sum(budget), +- teken 1e periode, +- teken 2e periode, ...

  // Stap 1:
  insert into tmpBudget (tmpPernr, tmpRksGid, tmpDefaultBoekzijde, tmpPosOfNeg,
                         tmpBudVergelijkenMet,
                         tmpBudgetInRksValuta, tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpBudgetPercentage,
                         tmpSaldoInBasisValuta, tmpSaldoInValuta,
                         tmpBudgetGid)
  select   Pernr,
           RksGid,
           if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif tmpDefaultBoekzijde,
           if tmpDefaultBoekzijde = 1 then -1 else 1 endif tmpPosOfNeg,
           FunBudgetBepaalWelkeVergelijk(@VergelijkMet, VergelijkenMet, @VergelijkenMetVanKstpd, tmpDefaultBoekzijde) tmpBudVergelijkenMet,
           if BudgetGid is not null then
             tmpPosOfNeg * IsNull(if isnull(BudMetVerdeling,0) = 1 then (JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100)
                                                         else (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = BudgetGid) endif, 0)
           endif tmpBudgetInRksValuta,
          (if RksValNummer = @@BasisValutaNummer then tmpBudgetInRksValuta else tmpBudgetInRksValuta * KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) endif) tmpBudgetInBasisValuta,

          (if RksValNummer = @OverzichtInValuta then tmpBudgetInRksValuta else tmpBudgetInBasisValuta / @Koers endif) tmpBudgetInValuta,

          (if BudMetVerdeling = 1 then BudPerPercentage endif) tmpBudgetPercentage,
           case @SoortBoeking
             when 0 then // Definitief
               case tmpBudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0)
               end
             when 1 then  //Voorlopig
               case tmpBudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
             else
               case tmpBudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0) - IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
           end tmpSaldoInBasisValuta,
           tmpSaldoInBasisValuta / @Koers tmpSaldoInValuta,
           BudgetGid
  from    (tabPeriode,
           tabRekeningschema) left outer join tabBudget        on (BudBjGid = @BjGid and BudRksgid = RksGid)
                              left outer join tabRekeningsaldo on (RekSaldoBjGid=@BjGid and RekSaldoRksGid=RksGid and RekSaldoPernr = Pernr)
                              left outer join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr =Pernr and BudPerBudgetCode = BudBudgetCode)
  where    ((@IsKstp =  0 and RksKstdGid = @KstpdGid) or
            (@IsKstp <> 0 and RksKstpGid = @KstpdGid)) and
           PerBjGid = @BjGid and Pernr between @VanPernr and @TotPerNr
           and (   (@OokZonderbudget = 1)  // ACW 15-03-2007: Meenemen ook als rekening geen budget heeft of niet ...
                OR (BudgetGid is not null)
               )
  group by Pernr, RksGid, RKsInvoer, RksValNummer, DefaultBoekzijde, DefaultSoort, tmpDefaultBoekzijde, tmpPosOfNeg, tmpBudgetInRksValuta, tmpBudgetPercentage, BudgetGid, BudMetVerdeling, BudPerPercentage, Jaarbudget, VergelijkenMet;


  //Bereken voor de laatste periode opnieuw het percentage en totaal budget zodat het totaal overeenkomt met het jaarbudget
  if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then
    //Alleen indien alle periodes worden afgedrukt!
   //call Trace('Ja, opnieuw berekenen!');
    update tmpBudget buiten
    set    tmpBudgetInRksValuta   = tmpPosOfNeg * JaarBudget - (select sum(tmpBudgetInRksValuta)   from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksGid = buiten.tmpRksGid),
           tmpBudgetInBasisValuta = tmpPosOfNeg * JaarBudget * KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) - (select sum(tmpBudgetInBasisValuta) from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksGid = buiten.tmpRksGid),
           tmpBudgetInValuta      = (tmpPosOfNeg * JaarBudget * KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) / @koers ) - (select sum(tmpBudgetInValuta)      from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksGid = buiten.tmpRksGid),
           tmpBudgetPercentage    = 100 - (select sum(tmpBudgetPercentage)    from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksGid = buiten.tmpRksGid)
    from   tabBudget inner join tabRekeningschema on (RksGid = BudRksGid)
    where  tmpPerNr = @MaxPerNr and BudMetVerdeling = 1 and BudgetGid = tmpBudgetGid;
  end if;


  // Extra regel per kstp om het Niet-Verbijzonderd-budget te berekenen
  // NV. = budget van Kstp - Totaal budget van alle rekeningen van die Kstp

  // Bepaal het budget (soort)
  if @IsKstp = 1 then
    select BudgetGid, BudMetVerdeling, JaarBudget, BudBudgetCode into @BudgetGid, @BudMetVerdeling, @JaarBudget, @BudBudgetCode from tabBudget where BudKstpGid = @KstpdGid and BudBjGid = @BjGid;
  else
    select BudgetGid, BudMetVerdeling, JaarBudget, BudBudgetCode into @BudgetGid, @BudMetVerdeling, @JaarBudget, @BudBudgetCode from tabBudget where BudKstdGid = @KstpdGid and BudBjGid = @BjGid;
  end if;

  if @BudgetGid is not null then
    // Gehele jaar opnemen? Dan een correctie toepassen op de verdeling
    insert into tmpBudget (tmpPernr, tmpRksGid, tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpBudgetPercentage,
                           tmpSaldoInBasisValuta, tmpSaldoInValuta,
                           tmpBudgetGid)
    select tmpPerNr, NULL,
       isnull(
       if @BudMetVerdeling = 1 then         // budget van de kostenplaats/-drager
         // Kstp heeft een jaarbudget -> jaarbudget * (totaal budget% van de perioderange) berekenen
         if @VanPerNr = 1 and tmpPerNr = @MaxPerNr then
           // Laatate periode EN we hebben het hele jaar -> Deze periode is het restant (i.v.m. afrondingen) (Dus Jaarbedrag - Alle perioden EXCL. de laatste periode)
           @JaarBudget - (select sum(round(@JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2)) from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr<>tmpPernr and BudPerBudgetCode = @BudBudgetCode)
         else
           // Alleen deze periode
           (select @JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=tmpPernr and BudPerBudgetCode = @BudBudgetCode)
          endif
       else
         // Kstp heeft budget per periode -> perioderange optellen
         (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=tmpPernr and BudBedrBudgetGid = @BudgetGid)
       endif
       ,0) -
       isnull(sum(tmpBudgetInBasisValuta),0) NVbudgetInBasisValuta, // - Totaal van de rekeningen
       round(NVbudgetInBasisValuta / @Koers,2) tmpBudgetInValuta,
       null, null, null, null
    from   tmpBudget
    group by tmppernr
    having tmpBudgetInValuta <> 0; // Alleen een extra NV-regel als het bedrag <> 0 is

  end if;


    //LET OP: DEZE VOLGORDE ZO LATEN!!
    update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
    update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
    update tmpBudget set tmpPlusMinTeken = (if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif);

   //call Trace('Werk alle perioden bij');
    update tmpBudget set tmpPeriode1      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  0 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode2      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  1 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode3      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  2 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode4      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  3 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode5      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  4 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode6      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  5 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode7      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  6 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode8      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  7 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode9      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  8 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode10     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =  9 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode11     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 10 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode12     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 11 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpPeriode13     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 12 + @VanPernr and a.tmpRksGid = tmpBudget.tmpRksGid),
                         tmpBudgetInValuta= (select sum(tmpBudgetInValuta) from tmpBudget a where (a.tmpRksGid = tmpBudget.tmpRksGid) or (a.tmpRksGid is null and tmpBudget.tmpRksGid is null)),
                         tmpSaldoInValuta = (select sum(tmpSaldoInValuta)  from tmpBudget a where (a.tmpRksGid = tmpBudget.tmpRksGid) or (a.tmpRksGid is null and tmpBudget.tmpRksGid is null))
    where tmpPernr = @VanPernr;

  update tmpBudget set tmpVerschil = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);

  //call traceEind('rapBudgetPerKstpKstdPerRekening');

  select   if RksGid is not null then tabRekeningschema.RksInvoer endif RksInvoer,
           if RksGid is not null then tabRekeningschema.RksNaam else _U('Niet verbijzonderd') endif RksNaam,
           tmpBudgetInValuta,
           tmpSaldoInValuta,
           tmpVerschil,
           // ACW 15-07-2002: ipv. tmpPercentage over te nemen deze opnieuw berekenen (tmpVerschil wordt tenslotte ook opnieuw berekend!!)
           (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100) tmpPercentage,
           tmpPeriode1 ,
           tmpPeriode2 ,
           tmpPeriode3 ,
           tmpPeriode4 ,
           tmpPeriode5 ,
           tmpPeriode6 ,
           tmpPeriode7 ,
           tmpPeriode8 ,
           tmpPeriode9 ,
           tmpPeriode10,
           tmpPeriode11,
           tmpPeriode12,
           tmpPeriode13
  from     tmpBudget left outer join tabRekeningschema on (RksGid = tmpRksGid)
  where    tmpPernr = @VanPerNr
  order by if RksGid is null then 1 else 0 endif,  // De niet-verbijzonderd-regel onderaan tonen!
           RksInvoer;


end;

//call rapBudgetPerKstpKstdPerRekening(0, '1', 3, 1, 12, 2, 0, 5, 5, 10);


create or replace procedure rapBudgetPerKstpPerPeriodeNaastElkaar(
in @BjGid             integer,
in @VanPernr          smallint,
in @TotPernr          smallint,
in @SelecteerOp       smallint,      //0 = KstpCode, 1=Kstpzoekcode, 2=Kstpnaam
in @VanKstp           nchar(40),      //van nummer/zoekcode/naam
in @TotKstp           nchar(40),      //t/m nummer/zoekcode/naam
in @SorterenOp        smallint,      //0=Nummer, 1=Zoekcode, 2=Naam
in @SoortBoeking      smallint,      //0=definitief, 1=voorlopig, 2=beide
in @OokZonderbudget   smallint,      //0=Nee (alleen kostenplaatsen met budget), 1=Ja
in @VergelijkMet      smallint,      //4=Zoals bij budget, 0=Saldo, 1=Debet, 2=Credit
in @OverzichtInValuta integer,       //Valutanummer waarin bedragen moeten worden afgedrukt
in @1PlusMinTeken     numeric(6,2),  //Bij welke percentage een +  of -  afdrukken
in @2PlusMinTeken     numeric(6,2))  //Bij welke percentage een ++ of -- afdrukken

result(tmpRegelSoort integer, tmpKstpCode nchar(26), tmpKstpNaam nchar(40), tmpPernr integer, tmpValCode nchar(3),
       tmpBudgetInValuta numeric(15,2), tmpSaldoInValuta numeric(15,2), tmpVerschil numeric(15,2), tmpPercentage numeric(15,2),
       tmpSorteerveld nchar(40), tmpPeriode1 nchar(2),
       tmpPeriode2 nchar(2), tmpPeriode3 nchar(2), tmpPeriode4 nchar(2), tmpPeriode5 nchar(2), tmpPeriode6 nchar(2),
       tmpPeriode7 nchar(2), tmpPeriode8 nchar(2), tmpPeriode9 nchar(2), tmpPeriode10 nchar(2), tmpPeriode11 nchar(2),
       tmpPeriode12 nchar(2), tmpPeriode13 nchar(2),tmpBudgetGid integer)

begin

  declare @Teller           smallint;
  declare @Koers            double;
  declare @OverzichtValCode nchar(3);
  declare @ValCode          nchar(3);
  declare @MaxPerNr         integer;
  declare @HeleJaar         smallint;

  declare local temporary table tmpBudget(
     tmpGid                     integer default AutoIncrement,
     tmpKstpCode                nchar(26),
     tmpKstpNaam                nchar(40) default '',
     tmpPernr                   integer,
     tmpBudgetInBasisValuta     numeric(15,2),
     tmpBudgetInValuta          numeric(15,2),
     tmpPlusMinTeken            nchar(2),
     tmpSaldoInValuta           numeric(15,2),
     tmpSaldoInBasisValuta      numeric(15,2),
     tmpVerschil                numeric(15,2),
     tmpPercentage              numeric(15,2),
     tmpSorteerVeld             nchar(40) default '',
     tmpRegelSoort              integer,
     tmpBudgetGid               integer,
     tmpPeriode1                nchar(2),
     tmpPeriode2                nchar(2),
     tmpPeriode3                nchar(2),
     tmpPeriode4                nchar(2),
     tmpPeriode5                nchar(2),
     tmpPeriode6                nchar(2),
     tmpPeriode7                nchar(2),
     tmpPeriode8                nchar(2),
     tmpPeriode9                nchar(2),
     tmpPeriode10               nchar(2),
     tmpPeriode11               nchar(2),
     tmpPeriode12               nchar(2),
     tmpPeriode13               nchar(2),
     primary key (tmpGid)
   ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapBudgetPerKstpPerPeriodeNaastElkaar > @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+', @VanKstp='+string(@VanKstp)+', @TotKstp='+string(@TotKstp)+', @SorterenOp='+string(@SorterenOp)+', @SoortBoeking='+string(@SoortBoeking)+', @OokZonderbudget='+string(@OokZonderbudget)+', @VergelijkMet='+string(@VergelijkMet)+', @OverzichtInValuta'+string(@OverzichtInValuta)+', @1PlusMinTeken='+string(@1PlusMinTeken)+', @2PlusMinTeken'+string(@2PlusMinTeken);
  //call TraceBegin(@@ErrorTextProcedure);

  Create index idx_tmpBudgetSoort     on tmpBudget (tmpRegelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (tmpSorteerVeld);
  Create index idx_tmpBudgetPernr     on tmpBudget (tmpKstpCode, tmpPernr);

  set @@ErrorTextProcedure = 'rapBudgetPerKstpPerPeriodeNaastElkaar > Stap 1';
  //call Trace(@@ErrorTextProcedure);

  select max(PerNr) into @MaxPerNr from tabPeriode where PerBjGid = @BjGid;
  set @HeleJaar = if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then 1 else 0 endif;

  set @Koers = KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta);

//  if (@TotPernr - @VanPernr) <= 12 then
    // gegevens per periode ophalen
    insert into tmpBudget (tmpRegelSoort, tmpPernr, tmpKstpCode, tmpKstpNaam,
                           tmpBudgetInBasisValuta, tmpBudgetInValuta,
                           tmpSaldoInBasisValuta, tmpSaldoInValuta, tmpSorteerVeld, tmpBudgetGid)
    select   1,
             Pernr,
             KstpCode,
             KstpNaam,
             // tmpBudgetInBasisValuta :
             if BudgetGid is not null then
               // Kstp heeft een budget, die dus gebruiken!
               if BudMetVerdeling = 1 then
                 // Kstp heeft een jaarbudget -> jaarbudget * (totaal budget% van de perioderange) berekenen
                 if @HeleJaar = 1 and PerNr = @MaxPerNr then
                   Jaarbudget - (select sum(round(BudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2)) from
                   tabBudget BudgetBinnen inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr<>Pernr and BudPerBudgetCode = BudgetBinnen.BudBudgetCode) where BudKstpgid = KstpGid and BudBjGid = @BjGid)
                 else
                   (select JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = BudBudgetCode)
                 endif
               else
                 // Kstp heeft budget per periode -> perioderange optellen
                 (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = BudgetGid)
               endif
             else
               // Kstp heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstp (in basisvalua) berekenen
               sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                   ValutaOmrekenen(RksValNummer,
                                         (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                       // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                       if @HeleJaar = 1 and @MaxPerNr = PerBinnen.PerNr then
                                                         // Gehele jaar, dus budget laatste periode = Jaarbudget - andere periodes
                                                         tabRksBudget.JaarBudget - (select sum(round(/*tabRksBudgetBinnen.JaarBudget */ Bud_PercAfronden(0.25 /*BudPerPercentage*/) / 100,2)) from
                                                         tabBudget tabRksBudgetBinnen inner join tabBudgetCodePeriode PerBinnen on PerBinnen.BudPerBjGid = @BjGid and PerBinnen.BudPernr<>@TotPernr and PerBinnen.BudPerBudgetCode = tabRksBudgetBinnen.BudBudgetCode
                                                         where tabRksBudgetBinnen.BudgetGid = tabRksBudget.BudgetGid)
                                                       else
                                                         (select tabRksBudget.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                       endif
                                                     else
                                                       // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                       (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                     endif
                                                    )
                                          from      tabBudget tabRksBudget,
                                                    tabPeriode PerBinnen
                                          where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid
                                                    and PerBinnen.PerBjGid = @BjGid and PerBinnen.PerNr = PerBuiten.PerNr
                                          ) // ACW 01-10-2002: test op @BjGid toegevoegd
                                         , @@BasisValutaNummer, @BjGid, @TotPernr, 2
                                        )
               )
             endif tmpBudgetInBasisValuta,
             // tmpBudgetInValuta :
             if BudgetGid is not null then
               // Kstp heeft een budget, die dus gebruiken!
              tmpBudgetInBasisValuta / @Koers
             else
               // Kstp heeft geen budget, dus alle budgetbedragen volgens het totaal van de rekeningen in de kstp (in basisvalua) berekenen
               sum(if (if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif) = 1 then -1 else 1 endif * // ACW 22-10-2002: ook plus of min-teken verwerken!!
                   ValutaOmrekenen(RksValNummer,
                                         (select sum(if tabRksBudget.BudMetVerdeling = 1 then
                                                       // RksBudget is %-verdeling, dus bereken: jaarbudget * (totaal budget% in de perioderange)
                                                       if @HeleJaar = 1 and PerNr = @MaxPerNr then
                                                         // Gehele jaar, dus budget laatste periode = Jaarbudget - andere periodes
                                                         tabRksBudget.JaarBudget - (select sum(round(tabRksBudgetBinnen.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100,2)) from
                                                         tabBudget tabRksBudgetBinnen inner join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr<>Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                         where tabRksBudgetBinnen.BudgetGid = tabRksBudget.BudgetGid)
                                                       else
                                                         (select tabRksBudget.JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = tabRksBudget.BudBudgetCode)
                                                       endif
                                                     else
                                                       // RksBudget heeft periodebudget, dus totaal van het budget per periode berekenen
                                                       (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = tabRksBudget.BudgetGid)
                                                     endif
                                                    )
                                          from      tabBudget tabRksBudget,
                                                    tabPeriode PerBinnen
                                          where     tabRksBudget.BudRksGid = RksBuiten.RksGid and tabRksBudget.BudBjGid = @BjGid
                                                    and PerBinnen.PerBjGid = @BjGid and PerBinnen.PerNr = PerBuiten.PerNr
                                          ) // ACW 01-10-2002: test op @BjGid toegevoegd
                                         , @OverzichtInValuta, @BjGid, @TotPernr, 2
                                        )
               )
             endif tmpBudgetInValuta,

             isnull(sum(
               case FunBudgetBepaalWelkeVergelijk(@VergelijkMet, (select BudgetRks.VergelijkenMet from tabBudget BudgetRks where BudRksGid = RksGid and BudBjGid = @BjGid), VergelijkenMet, DefaultBoekzijde)
                 when 0 then // Saldo
                   case @SoortBoeking
                     when 0 then // Definitief
                         IsNull(SaldoDebetBasisDefinitief,0) - IsNull(SaldoCreditBasisDefinitief,0)
                     when 1 then // Voorlopig
                         IsNull(SaldoDebetBasisVoorlopig,0) - IsNull(SaldoCreditBasisVoorlopig,0)
                     else        // Definitief + Voorlopig
                         IsNull(SaldoDebetBasisDefinitief,0) - IsNull(SaldoCreditBasisDefinitief,0) + IsNull(SaldoDebetBasisVoorlopig,0) - IsNull(SaldoCreditBasisVoorlopig,0)
                   end
                 when 1 then // Debet
                   case @SoortBoeking
                     when 0 then // Definitief
                         SaldoDebetBasisDefinitief
                     when 1 then // Voorlopig
                         SaldoDebetBasisVoorlopig
                     else        // Definitief + Voorlopig
                         IsNull(SaldoDebetBasisDefinitief,0) + IsNull(SaldoDebetBasisVoorlopig,0)
                   end
                 when 2 then // Credit
                   case @SoortBoeking
                     when 0 then // Definitief
                        -SaldoCreditBasisDefinitief
                     when 1 then // Voorlopig
                        -SaldoCreditBasisVoorlopig
                     else        // Definitief + Voorlopig
                        -IsNull(SaldoCreditBasisDefinitief,0) - IsNull(SaldoCreditBasisVoorlopig,0)
                   end
               end
             ),0) tmpSaldoInBasisValuta,
             tmpSaldoInBasisValuta / @Koers tmpSaldoInValuta,
            (if @SorterenOp = 0 then KstpCode else if @SorterenOp = 1 then KstpZoekcode else KstpNaam endif endif),
             BudgetGid

    from    (tabPeriode PerBuiten,
             tabKostenplaats)
             left outer join tabBudget         BudgetBuiten on (BudKstpgid = KstpGid and BudBjGid = @BjGid)
             left outer join tabRekeningschema RksBuiten    on ((RksKstpGid = KstpGid)
                                                                // ACW 15-03-2007: vinkje in voorloopscherm ook van invloed op Rks
                                                                 and (   (@OokZonderbudget = 1) // Alleen de rekening opnemen als ook zonder budgetten OF kstp heeft budget OF rekening heeft budget!!
                                                                      or (BudgetBuiten.BudKstpgid is not null)
                                                                      or (exists(select first 1 from tabBudget RksBudget where RksBudget.BudRksGid = RksGid and RksBudget.BudBjGid = @BjGid))
                                                                     )
                                                                )
             left outer join tabRekeningsaldo               on (RekSaldoBjGid=@BjGid and RekSaldoRksGid=RksGid and RekSaldoPernr = Pernr)
    where    PerBjGid = @BjGid and
           ((KstpCode     between @VanKstp and @TotKstp and @SelecteerOp = 0)  or
            (KstpZoekcode between @VanKstp and @TotKstp and @SelecteerOp = 1)  or
            (KstpNaam     between @VanKstp and @TotKstp and @SelecteerOp = 2)) and
             Pernr between @VanPernr and @TotPernr
    group by KstpGid, KstpCode, Pernr, KstpZoekcode, KstpNaam, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid;

    //Bereken voor de laatste periode opnieuw het percentage en totaal budget zodat het totaal overeenkomt met het jaarbudget
    set @@ErrorTextProcedure = 'rapBudgetPerKstpPerPeriodeNaastElkaar > Bereken de laatste periode opnieuw?';
    //call Trace(@@ErrorTextProcedure);
/*
    if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then
      //Alleen indien alle periodes worden afgedrukt! Let op: in 3 stappen!!
      //call trace('Ja, opnieuw berekenen!');
      update tmpBudget buiten
      set    tmpBudgetInBasisValuta = JaarBudget -          (select sum(tmpBudgetInBasisValuta) from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstpCode = buiten.tmpKstpCode),
             tmpBudgetInValuta      = JaarBudget / @Koers - (select sum(tmpBudgetInValuta)      from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpKstpCode = buiten.tmpKstpCode)
      from   tabBudget
      where  tmpPerNr = @MaxPerNr and BudMetVerdeling = 1 and BudgetGid = tmpBudgetGid;
    end if;
*/

    update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
    update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
    update tmpBudget set tmpPlusMinTeken = if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif;

    set @@ErrorTextProcedure = 'rapBudgetPerKstpPerPeriodeNaastElkaar > Werk alle perioden bij';
    //call Trace(@@ErrorTextProcedure);
    update tmpBudget set tmpPeriode1      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr =     @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode2      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 1 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode3      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 2 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode4      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 3 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode5      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 4 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode6      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 5 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode7      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 6 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode8      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 7 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode9      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 8 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode10     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 9 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode11     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 10 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode12     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 11 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpPeriode13     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 12 + @VanPernr and a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpBudgetInValuta= (select sum(tmpBudgetInValuta) from tmpBudget a where a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpSaldoInValuta = (select sum(tmpSaldoInValuta)  from tmpBudget a where a.tmpKstpCode = tmpBudget.tmpKstpCode),
                         tmpVerschil      = (select sum(tmpVerschil)       from tmpBudget a where a.tmpKstpCode = tmpBudget.tmpKstpCode)
    where tmpPernr = @VanPernr;

    //call Trace('Verwijder alles dat ongelijk is aan VanPernr');
    delete tmpBudget where tmpPernr <> @VanPernr;

    //call Trace('Verwijderen kostenplaatsen die geen budget hebben (als dit is meegegeven)');
    if @OokZonderbudget = 0 then
      delete tmpBudget
      where  tmpKstpcode not in (select KstpCode from tabBudget inner join tabKostenplaats on (KstpGid = BudKstpGid) where BudBjGid = @BjGid) and // Heeft zelf geen budget
             tmpKstpcode not in (select KstpCode from tabRekeningSchema inner join tabBudget on BudRksGid = RksGid inner join tabKostenplaats on KstpGid = RksKstpGid where BudBjGid = @BjGid) // Heeft geen rekeningen met het budget
    end if;

    set @@ErrorTextProcedure = 'rapBudgetPerKstpPerPeriodeNaastElkaar > Totaal generaal';
    //call Trace(@@ErrorTextProcedure);

    if exists( select 1 from tmpBudget) then

      insert into tmpBudget (tmpRegelSoort, tmpSorteerVeld, tmpKstpCode, tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpSaldoInBasisValuta, tmpSaldoInValuta)
      select   99,
               repeat('z',40),
               _U('Van kostenpl. %1! t/m %2!', @VanKstp, @TotKstp),
               sum(tmpBudgetInBasisValuta) tmpBudgetInBasisValuta,
               sum(tmpBudgetInValuta)      tmpBudgetInValuta,
               sum(tmpSaldoInBasisValuta)  tmpSaldoInBasisValuta,
               sum(tmpSaldoInValuta)       tmpSaldoInValuta
      from     tmpBudget where tmpRegelSoort = 1;
    end if;

    set @@ErrorTextProcedure = 'rapBudgetPerKstpPerPeriodeNaastElkaar > Nu nog even percentage bepalen';
    //call Trace(@@ErrorTextProcedure);
    update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
    update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
    update tmpBudget set tmpPlusMinTeken = if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif;

    select ValCode into @ValCode from tabValuta where ValNummer = @OverzichtInValuta;

    //call TraceEind(@@ErrorTextProcedure);

    select   tmpRegelSoort, tmpKstpCode, tmpKstpNaam, tmpPernr, @ValCode tmpValCode, tmpBudgetInValuta,
             tmpSaldoInValuta, tmpVerschil, tmpPercentage,
             tmpSorteerveld,
             tmpPeriode1, tmpPeriode2, tmpPeriode3, tmpPeriode4, tmpPeriode5, tmpPeriode6,
             tmpPeriode7, tmpPeriode8, tmpPeriode9, tmpPeriode10, tmpPeriode11, tmpPeriode12, tmpPeriode13,tmpBudgetGid
    from     tmpBudget
    order by tmpSorteerVeld, tmpRegelSoort, tmpPernr;

//  else
//    select * from dummy where 1=0
//  end if;


end;
//call rapBudgetPerKstpPerPeriodeNaastElkaar(2, 1, 12, 0, '', '99999999', 0, 2, 0, 0, 0, 5, 20);


create or replace procedure rapBudgetPerRekening(in @SoortOverzicht    smallint, //0 = Budget per rekening, 1 = Budget per rekening per periode (periodes naast elkaar), 2 = Budget per rekening per periode (periodes onder elkaar)
                                      in @BjGid             Integer,
                                      in @VanPernr          smallint,
                                      in @TotPernr          smallint,
                                      in @SelecteerOp       smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
                                      in @VanRks            nchar(40), //van nummer/zoekcode/naam
                                      in @TotRks            nchar(40), //t/m nummer/zoekcode/naam
                                      in @SorterenOp        smallint, //0=Nummer, 1=Zoekcode, 2=Naam, 3=RekeningSoort
                                      in @SoortBoeking      smallint, //0=definitief, 1=voorlopig, 2=beide
            	                        in @OokZonderbudget   smallint, //0=Nee (alleen rekeningen met budget), 1=Ja
                            		      in @VergelijkMet      smallint, //4=Zoals bij budget, 3=Default-boekzijde, 0=Saldo, 1=Debet, 2=Credit
                                      in @ComprimeerBalans  smallint, //0=nee, 1=ja, 2=conform balans
                                      in @AantalCijfers     smallint, //Aantal cijfers waarop getotaliseerd moet worden 1-5 (werkt niet bij conform balans)
                                      in @ValutaVanRekening smallint, //0=Nee, 1=Ja (er wordt dan niet gekeken wat erbij @OverzichtInValuta staat)
                                      in @OverzichtInValuta integer,  //Valutanummer waarin bedragen moeten worden afgedrukt
                                      in @TotalenInValuta   integer)  //Valutanummer voor subtotalen

result (RegelSoort integer, RksInvoer nchar(28), RksNaam nchar(40), ValCode nchar(3), ValNummer Integer, Budget numeric(15,2),
        Saldo numeric(15,2), Verschil numeric(15,2), Percentage numeric(15,2),
        JaarBudget numeric(15,2), BudgetCode integer, BudgetOms nchar(40), BalVerdicht smallint, BalDecimalen smallint)

begin

  declare @Teller smallint;
  declare @TotaalValCode nchar(3);
  declare @OverzichtValCode nchar(3);

  declare local temporary table tmpBudget(
     tmpGid                  integer default AutoIncrement,
     RksInvoer               nchar(28),
     RksNaam                 nchar(40) default '',
     tmpDefaultBoekzijde     smallint,
     PosOfNeg                smallint,
     Valcode                 nchar(3) default  '',
     tmpValNummer            integer,
     SorteerVeld             nchar(40) default '',
     BudVergelijkenMet       smallint,
     BudgetInRksValuta       numeric(15,2),
     BudgetInBasisValuta     numeric(15,2),
     BudgetInValuta          numeric(15,2),
     SaldoInBasisValuta      numeric(15,2),
     SaldoInValuta           numeric(15,2),
     Verschil                numeric(15,2),
     Percentage              numeric(15,2),
     JaarBudgetInRksValuta   numeric(15,2),
     JaarBudgetInBasisValuta numeric(15,2),
     JaarBudgetInValuta      numeric(15,2),
     BudgetCode              integer,
     BudgetOms               nchar(40),
     RegelSoort              integer,
     BalGid                  integer,
     BalVerdicht             smallint default 0,
     BalDecimalen            smallint default 0,
     primary key (tmpGid)
   ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapBudgetPerRekening > @SoortOverzicht='+string(@SoortOverzicht)+', @VanRks='+@VanRks+', @TotRks='+@TotRks;
  //call TraceBegin(@@ErrorTextProcedure);

  Create index idx_tmpRksInvoer       on tmpBudget (RksInvoer);
  Create index idx_tmpBudgetSoort     on tmpBudget (Regelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (SorteerVeld);

  set @@ErrorTextProcedure = 'rapBudgetPerRekening > Stap 1';
  //call Trace(@@ErrorTextProcedure);

  // gegevens per periode ophalen
  insert into tmpBudget (RegelSoort, RksInvoer, RksNaam, tmpDefaultBoekzijde, PosOfNeg, tmpValNummer, ValCode, BudVergelijkenMet,
                         BudgetInRksValuta, BudgetInBasisValuta, BudgetInValuta, SaldoInBasisValuta, SaldoInValuta, Verschil, Percentage,
                         JaarBudgetInRksValuta, JaarBudgetInBasisValuta, JaarBudgetInValuta, BudgetCode, BudgetOms, SorteerVeld, BalDecimalen)
  select   1,
           RksInvoer,
           RksNaam,
           if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif tmpDefaultBoekzijde,
           if tmpDefaultBoekzijde = 1 then -1 else 1 endif PosOfNeg,
          (if @ValutaVanRekening=0 then @OverzichtInValuta else RksValNummer endif) tmpValNummer,
          (select ValCode from tabValuta where ValNummer = tmpValNummer),
           if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then // saldo, debet of credit
             IsNull(VergelijkenMet,0)
           else
             if @VergelijkMet in (3,4) then
               if tmpDefaultBoekzijde between 0 and 1 then // def.boekzijde debet of credit
                 tmpDefaultBoekzijde + 1
               else
                 0 // geen voorkeur ---> saldo
               endif
             else
               @VergelijkMet // debet of credit
             endif
           endif BudVergelijkenMet, //0=saldo, 1=debet, 2=credit
          (PosOfNeg * IsNull(if BudMetVerdeling = 1 then round(JaarBudget * (Bud_CumPercentage(@BjGid, @VanPerNr, @TotPerNr, BudBudgetCode)/100),2) else (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = BudgetGid and BudBedrPerNr between @VanPerNr and @TotPerNr) endif, 0)) BudgetInRksValuta,
           ValutaOmrekenen(RksValNummer, BudgetInRksValuta, @@BasisValutaNummer, @BjGid, @TotPernr, 2) BudgetInBasisValuta,
          (if RksValNummer = tmpValnummer then BudgetInRksValuta else ValutaOmrekenen(@@BasisValutaNummer, BudgetInBasisValuta, tmpValnummer, @BjGid, @TotPernr, 2) endif) BudgetInValuta,
           case @SoortBoeking
             when 0 then // Definitief
               case BudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0)
               end
             when 1 then  //Voorlopig
               case BudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
             else
               case BudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0) - IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
           end SaldoInBasisValuta,
           ValutaOmrekenen(@@BasisValutaNummer, SaldoInBasisValuta, tmpValNummer, @BjGid, @TotPernr, 2) SaldoInValuta,
           PosOfNeg * (SaldoInValuta - BudgetInValuta) Verschil,
          (if BudgetInValuta      = 0 then 0 else (Verschil / (if tmpDefaultBoekzijde = 1 then -BudgetInValuta else BudgetInValuta endif) * 100) endif) Percentage,
           PosOfNeg * IsNull(if BudMetVerdeling = 1 then JaarBudget else (select sum(BudBedrag) from tabBudgetBedrag where BudBedrBjGid=@BjGid and BudBedrBudgetGid = BudgetGid) endif, 0) JaarBudgetInRksValuta,
           ValutaOmrekenen(RksValNummer, JaarBudgetInRksValuta, @@BasisValutaNummer, @BjGid, @TotPernr, 2) JaarbudgetInBasisValuta,
          (if RksValNummer = tmpValnummer then JaarBudgetInRksValuta else ValutaOmrekenen(@@BasisValutaNummer, JaarbudgetInBasisValuta, tmpValnummer, @BjGid, @TotPernr, 2) endif) JaarBudgetInValuta,
           BudBudgetCode,
          (select BudgetOms from tabBudgetCode where BudgetCode = BudBudgetCode) BudgetOms,
          (if @SorterenOp = 0 then RksInvoer else if @SorterenOp = 1 then RksZoekcode else if @SorterenOp = 2 then RksNaam else string(DefaultSoort) endif endif endif),
           @AantalCijfers
  from     tabRekeningschema left outer join tabBudget        on (BudBjGid = @BjGid and BudRksgid = RksGid)
                             left outer join tabRekeningsaldo on (RekSaldoBjGid=@BjGid and RekSaldoRksGid=RksGid and RekSaldoPernr between @VanPernr and @TotPernr)
  where   (RksInvoer   between @VanRks and @TotRks and @SelecteerOp = 0)  or
          (RksZoekcode between @VanRks and @TotRks and @SelecteerOp = 1)  or
          (RksNaam     between @VanRks and @TotRks and @SelecteerOp = 2)
  group by RksInvoer, RksZoekcode, RksNaam, DefaultSoort, DefaultBoekzijde, RksValNummer, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid;


 //call Trace('Verwijderen rekeningen die geen budget hebben (als dit is meegegeven)');
  if @OokZonderbudget = 0 then
//    delete tmpBudget where tmpRksInvoer in (select tmpRksInvoer from tmpBudget where tmpRegelSoort = 2 and tmpBudgetInValuta = 0);
    delete tmpBudget where RksInvoer not in (select RksInvoer from tabBudget inner join tabRekeningschema on (RksGID = BudRksGID) where BudBjGid = @BjGid);
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerRekening > Stap 2';
  //call Trace(@@ErrorTextProcedure);

  if @ComprimeerBalans = 2 then  //Conform balans

    update tmpBudget set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
    from   tabBalansCodeDetail
    where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(RksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' and DecimalenSubTotalen<>0;

    update tmpBudget set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
    from   tabBalansCodeDetail
    where  BalGid is null and DetailBlCode=0 and Paragraaf = left(RksInvoer,2) and Trim(Paragraaf)<>'' and DecimalenSubTotalen<>0;

    update tmpBudget set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
    from   tabBalansCodeDetail
    where  BalGid is null and DetailBlCode=0 and Rubriek = left(RksInvoer,1) and Paragraaf='' and DecimalenSubTotalen<>0;

    update tmpBudget set BalGid = null;

    update tmpBudget set BalGid = BlGid, BalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(RksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' ;

    update tmpBudget set BalGid = BlGid, BalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  BalGid is null and DetailBlCode=0 and Paragraaf = left(RksInvoer,2) and Trim(Paragraaf)<>'';

    update tmpBudget set BalGid = BlGid, BalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  BalGid is null and DetailBlCode=0 and Rubriek = left(RksInvoer,1) and Paragraaf='';

  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerRekening > Stap 3';
  //call Trace(@@ErrorTextProcedure);

  //Subtotalen maken volgens aantal decimalen
  select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;
  set @Teller = 5;
  while @Teller > 0 loop

    insert into tmpBudget (RegelSoort, SorteerVeld, RksInvoer, RksNaam, ValCode, tmpValNummer, BudgetInValuta, SaldoInValuta,
                           JaarBudgetInValuta, BalVerdicht, BalDecimalen)

    select   15-@Teller,
             substr(RksInvoer, 1, @Teller)+'z' SorteerVeld,
             substr(RksInvoer, 1, @Teller)+' :' HulpRksInvoer,
             IsNull(OmsBalansCodeDetails, if @Teller = 1 then _U('Rubriek %1!', substr(RksInvoer, 1, 1)) else if @Teller = 2 then _U('Paragraaf %1!', substr(RksInvoer, 1, 2)) else _U('Subparagraaf %1!', substr(RksInvoer, 3, @Teller-2)) endif endif) BalOms,
             @TotaalValCode,
             @TotalenInValuta,
             ValutaOmrekenen(@@BasisValutaNummer, sum(if RegelSoort = 1 then BudgetInBasisValuta     else 0 endif), @TotalenInValuta, @BjGid, @TotPernr, 2) tmpBudgetInValuta,
             ValutaOmrekenen(@@BasisValutaNummer, sum(if RegelSoort = 1 then SaldoInBasisValuta      else 0 endif), @TotalenInValuta, @BjGid, @TotPernr, 2) tmpSaldoInValuta,
             ValutaOmrekenen(@@BasisValutaNummer, sum(if RegelSoort = 1 then JaarBudgetInBasisValuta else 0 endif), @TotalenInValuta, @BjGid, @TotPernr, 2) tmpJaarbudgetInValuta,
             IsNull(BalansVerdicht, max(BalVerdicht)),
             IsNull(DecimalenSubTotalen, max(BalDecimalen))
    from     tmpBudget left outer join tabBalanscodeDetail on (DetailBlCode = 0 and RubParSub = substr(RksInvoer, 1, @Teller) )
    where    length(RksInvoer)>=@Teller and RksInvoer in (select RksInvoer from tmpBudget where (RegelSoort=1 and BalDecimalen >= @Teller))
    group by HulpRksInvoer, SorteerVeld, BalOms, BalansVerdicht, DecimalenSubTotalen;

    set @Teller = @Teller - 1;

  end loop;

  set @@ErrorTextProcedure = 'rapBudgetPerRekening > Stap 4';
  //call Trace(@@ErrorTextProcedure);

  //Totaal generaal
  if exists( select 1 from tmpBudget) then
    insert into tmpBudget (RegelSoort, SorteerVeld, ValCode, tmpValNummer, BudgetInValuta, SaldoInValuta,
                           JaarBudgetInValuta)
    select   99,
             repeat('z',40),
             @TotaalValCode,
             @TotalenInValuta,
             ValutaOmrekenen(@@BasisValutaNummer, sum(BudgetInBasisValuta),     @TotalenInValuta, @BjGid, @TotPernr, 2) tmpBudgetInValuta,
             ValutaOmrekenen(@@BasisValutaNummer, sum(SaldoInBasisValuta),      @TotalenInValuta, @BjGid, @TotPernr, 2) tmpSaldoInValuta,
             ValutaOmrekenen(@@BasisValutaNummer, sum(JaarBudgetInBasisValuta), @TotalenInValuta, @BjGid, @TotPernr, 2) tmpJaarbudgetInValuta
    from     tmpBudget where RegelSoort = 1;
  end if;

  //Verdichten
  delete tmpBudget where BalVerdicht = 1 and RegelSoort = 1;


  if @ComprimeerBalans = 1 then  //comprimeren
    update tmpBudget set regelsoort = 5
    where  ( (@aantalcijfers = 5 and regelsoort = 10)
            or (@aantalcijfers=4 and regelsoort = 11)
            or (@aantalcijfers=3 and regelsoort = 12)
            or (@aantalcijfers=2 and regelsoort = 13)
            or (@aantalcijfers=1 and regelsoort = 14) );
  end if;

  update tmpBudget set Verschil     = (isnull(SaldoInValuta,0) - isnull(BudgetInValuta,0)) * (if isnull(BudgetInValuta,0) < 0 then -1 else 1 endif);
  update tmpBudget set Percentage   = (if BudgetInValuta = 0 then 0 else abs(Verschil) / abs(BudgetInValuta) * if sign(Verschil)=-1 then -1 else 1 endif endif * 100);

  //call TraceEind(@@ErrorTextProcedure);

  select RegelSoort, RksInvoer, RksNaam, ValCode, tmpValNummer, BudgetInValuta Budget, SaldoInValuta Saldo, Verschil, Percentage,
         JaarBudgetInValuta JaarBudget, BudgetCode, BudgetOms, BalVerdicht, BalDecimalen
  from   tmpBudget
  where  regelsoort <> 1 or @ComprimeerBalans in (0,2)
  order by SorteerVeld;


end;

//call rapBudgetPerRekening(0, 1, 0, 12, 0, '00000000', '99999999', 0, 2, 0, 3, 0, 2, 1, 0, 0);


create or replace procedure rapBudgetPerRekeningPerPeriode(in @BjGid             Integer,
                                                in @VanPernr          smallint,
                                                in @TotPernr          smallint,
                                                in @SelecteerOp       smallint,      //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
                                                in @VanRks            nchar(40),      //van nummer/zoekcode/naam
                                                in @TotRks            nchar(40),      //t/m nummer/zoekcode/naam
                                                in @SorterenOp        smallint,      //0=Nummer, 1=Zoekcode, 2=Naam, 3=RekeningSoort
                                                in @SoortBoeking      smallint,      //0=definitief, 1=voorlopig, 2=beide
            	                                  in @OokZonderbudget   smallint,      //0=Nee (alleen rekeningen met budget), 1=Ja
                            		                in @VergelijkMet      smallint,      //4=Zoals bij budget, 3=Default-boekzijde, 0=Saldo, 1=Debet, 2=Credit
                                                in @ComprimeerBalans  smallint,      //0=nee, 1=ja, 2=conform balans
                                                in @AantalCijfers     smallint,      //Aantal cijfers waarop getotaliseerd moet worden 1-5 (werkt niet bij conform balans)
                                                in @ValutaVanRekening smallint,      //0=Nee, 1=Ja (er wordt dan niet gekeken wat erbij @OverzichtInValuta staat)
                                                in @OverzichtInValuta integer,       //Valutanummer waarin bedragen moeten worden afgedrukt
                                                in @TotalenInValuta   integer,       //Valutanummer voor subtotalen
                                                in @1PlusMinTeken     numeric(6,2),  //Bij welke percentage een +  of -  afdrukken
                                                in @2PlusMinTeken     numeric(6,2))  //Bij welke percentage een ++ of -- afdrukken

result (tmpRegelSoort integer, tmpRksInvoer nchar(28), tmpRksNaam nchar(40), tmpPernr integer, tmpBeginDatum date, tmpEindDatum date,
        tmpValCode nchar(3), tmpBudgetInValuta numeric(15,2), tmpBudgetPercentage numeric(6,2), tmpSaldoInValuta numeric(15,2),
        tmpVerschil numeric(15,2), tmpPercentage numeric(15,2), tmpPlusMinTeken nchar(2), tmpBalVerdicht smallint, tmpBalDecimalen smallint,
        tmpSorteerveld nchar(40), tmpStreepVoorPercentage smallint)

begin

  declare @Teller           smallint;
  declare @Koers            double;
  declare @TotaalValCode    nchar(3);
  declare @OverzichtValCode nchar(3);
  declare @MaxPerNr         integer;

  declare local temporary table tmpBudget(
     tmpGid                  integer default AutoIncrement,
     tmpRksInvoer            nchar(28),
     tmpRksNaam              nchar(40) default '',
     tmpDefaultBoekzijde     smallint,
     tmpPernr                integer,
     tmpBeginDatum           date,
     tmpEindDatum            date,
     tmpPosOfNeg             smallint,
     tmpValcode              nchar(3) default  '',
     tmpValNummer            integer,
     tmpBudgetGid            integer,
     tmpBudgetInRksValuta    numeric(15,2),
     tmpBudgetInBasisValuta  numeric(15,2),
     tmpBudgetInValuta       numeric(15,2),
     tmpPlusMinTeken         nchar(2),
     tmpSaldoInValuta        numeric(15,2),
     tmpSaldoInBasisValuta   numeric(15,2),
     tmpVerschil             numeric(15,2),
     tmpPercentage           numeric(15,2),
     tmpSorteerVeld          nchar(40) default '',
     tmpBudVergelijkenMet    smallint,
     tmpBudgetPercentage     numeric(6,2),
     tmpRegelSoort           integer,
     tmpBalGid               integer,
     tmpBalVerdicht          smallint default 0,
     tmpBalDecimalen         smallint default 0,
     primary key (tmpGid)
   ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+', @VanRks='+@VanRks+', @TotRks='+@TotRks;
  //call Tracebegin(@@ErrorTextProcedure);
  //call Trace('rapBudgetPerRekeningPerPeriode > @SorterenOp='+string(@SorterenOp)+', @SoortBoeking='+string(@SoortBoeking)+', @OokZonderbudget='+string(@OokZonderbudget)+', @VergelijkMet='+string(@VergelijkMet)+', @ComprimeerBalans='+string(@ComprimeerBalans)+', @AantalCijfers='+string(@AantalCijfers)+', @ValutaVanRekening='+string(@ValutaVanRekening)+', @OverzichtInValuta='+string(@OverzichtInValuta)+', @TotalenInValuta='+string(@TotalenInValuta)+', @1PlusMinTeken='+string(@1PlusMinTeken)+', @2PlusMinTeken='+string(@2PlusMinTeken));

  Create index idx_tmpBudgetRksInvoer on tmpBudget (tmpRksInvoer);
  Create index idx_tmpBudgetSoort     on tmpBudget (tmpRegelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (tmpSorteerVeld);

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Stap 1: Alles bijeen zoeken';
  //call Trace(@@ErrorTextProcedure);

  select max(PerNr) into @MaxPerNr from tabPeriode where PerBjGid = @BjGid;

  // gegevens per periode ophalen
  insert into tmpBudget (tmpRegelSoort, tmpPernr, tmpBeginDatum, tmpEindDatum, tmpRksInvoer, tmpRksNaam, tmpDefaultBoekzijde, tmpPosOfNeg,
                         tmpValNummer, tmpValCode, tmpBudVergelijkenMet,
                         tmpBudgetInRksValuta, tmpBudgetInBasisValuta, tmpBudgetInValuta, tmpBudgetPercentage,
                         tmpSaldoInBasisValuta, tmpSaldoInValuta,
                         tmpSorteerVeld, tmpBalDecimalen, tmpBalVerdicht, tmpBudgetGid)
  select   1,
           Pernr,
           BeginDatum,
           EindDatum,
           RksInvoer,
           RksNaam,
           if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif tmpDefaultBoekzijde,
           if tmpDefaultBoekzijde = 1 then -1 else 1 endif tmpPosOfNeg,
          (if @ValutaVanRekening=0 then @OverzichtInValuta else RksValNummer endif) tmpValNummer,
          (select ValCode from tabValuta where ValNummer = tmpValNummer) tmpValCode,
           if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then // saldo, debet of credit
             IsNull(VergelijkenMet,0)
           else
             if @VergelijkMet in (3,4) then
               if tmpDefaultBoekzijde between 0 and 1 then // def.boekzijde debet of credit
                 tmpDefaultBoekzijde + 1
               else
                 0 // geen voorkeur ---> saldo
               endif
             else
               @VergelijkMet // debet of credit
             endif
           endif tmpBudVergelijkenMet, //0=saldo, 1=debet, 2=credit
           tmpPosOfNeg * IsNull(if BudMetVerdeling = 1 then (JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100)
                                                       else (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = BudgetGid) endif, 0) tmpBudgetInRksValuta,
          (if RksValNummer = @@BasisValutaNummer then tmpBudgetInRksValuta else tmpBudgetInRksValuta * KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) endif) tmpBudgetInBasisValuta,
          (if RksValNummer = tmpValnummer then tmpBudgetInRksValuta else tmpBudgetInBasisValuta / KoersTovBasisValuta(@BjGid, @TotPernr, tmpValnummer) endif) tmpBudgetInValuta,
          (if BudMetVerdeling = 1 then BudPerPercentage endif) tmpBudgetPercentage,
           case @SoortBoeking
             when 0 then // Definitief
               case tmpBudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0)
               end
             when 1 then  //Voorlopig
               case tmpBudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
             else
               case tmpBudVergelijkenMet
                 when 0 then  //Saldo
                   IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                 when 1 then  //Debet
                   IsNull(sum(SaldoDebetBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig),0)
                 when 2 then  //Credit
                  -IsNull(sum(SaldoCreditBasisDefinitief),0) - IsNull(sum(SaldoCreditBasisVoorlopig),0)
               end
           end tmpSaldoInBasisValuta,
           tmpSaldoInBasisValuta / KoersTovBasisValuta(@BjGid, @TotPernr, tmpValNummer) tmpSaldoInValuta,
          (if @SorterenOp = 0 then RksInvoer else if @SorterenOp = 1 then RksZoekcode else if @SorterenOp = 2 then RksNaam else string(DefaultSoort) endif endif endif),
           @AantalCijfers,
          (if @ComprimeerBalans = 1 then 1 else 0 endif),
           BudgetGid
  from    (tabPeriode,
           tabRekeningschema) left outer join tabBudget        on (BudBjGid = @BjGid and BudRksgid = RksGid)
                              left outer join tabRekeningsaldo on (RekSaldoBjGid=@BjGid and RekSaldoRksGid=RksGid and RekSaldoPernr = Pernr)
                              left outer join tabBudgetCodePeriode on (BudPerBjGid = @BjGid and BudPernr =Pernr and BudPerBudgetCode = BudBudgetCode)
  where  ((RksInvoer   between @VanRks and @TotRks and @SelecteerOp = 0)  or
          (RksZoekcode between @VanRks and @TotRks and @SelecteerOp = 1)  or
          (RksNaam     between @VanRks and @TotRks and @SelecteerOp = 2)) and
           PerBjGid = @BjGid and Pernr between @VanPernr and @TotPerNr
  group by RksInvoer, Pernr, BeginDatum, EindDatum, RksZoekcode, RksNaam, DefaultSoort, DefaultBoekzijde, RksValNummer, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid, BudPerPercentage;

  //Bereken voor de laatste periode opnieuw het percentage en totaal budget zodat het totaal overeenkomt met het jaarbudget
  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Bereken de laatste periode opnieuw?';
  //call Trace(@@ErrorTextProcedure);
  if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then
    //Alleen indien alle periodes worden afgedrukt!
   //call Trace('Ja, opnieuw berekenen!');
    update tmpBudget buiten
    set    tmpBudgetInRksValuta   = tmpPosOfNeg * JaarBudget - (select sum(tmpBudgetInRksValuta)   from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksInvoer = buiten.tmpRksInvoer),
           tmpBudgetInBasisValuta = tmpPosOfNeg * JaarBudget * KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) - (select sum(tmpBudgetInBasisValuta) from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksInvoer = buiten.tmpRksInvoer),
           tmpBudgetInValuta      = (tmpPosOfNeg * JaarBudget * if @ValutaVanRekening = 1 then 1 else KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) / KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta) endif) - (select sum(tmpBudgetInValuta)      from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksInvoer = buiten.tmpRksInvoer),
           tmpBudgetPercentage    = 100 - (select sum(tmpBudgetPercentage)    from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksInvoer = buiten.tmpRksInvoer)
    from   tabBudget inner join tabRekeningschema on (RksGid = BudRksGid)
    where  tmpPerNr = @MaxPerNr and BudMetVerdeling = 1 and BudgetGid = tmpBudgetGid;
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Totaal per rekening';
  //call Trace(@@ErrorTextProcedure);

  insert into tmpBudget (tmpRegelSoort, tmpRksInvoer, tmpRksNaam, tmpValNummer, tmpValCode,
                         tmpBudgetInValuta, tmpBudgetInBasisValuta,
                         tmpSaldoInValuta, tmpSaldoInBasisValuta, tmpBudgetPercentage,
                         tmpSorteerVeld, tmpBalDecimalen, tmpBalVerdicht)
  select   2,
           tmpRksInvoer,
           tmpRksNaam,
           tmpValNummer,
           tmpValCode,
           sum(tmpBudgetInValuta) Budget,
           sum(tmpBudgetInBasisValuta),
           sum(tmpSaldoInValuta),
           sum(tmpSaldoInBasisValuta),
           sum(tmpBudgetPercentage),
           min(tmpSorteerVeld),
           @AantalCijfers,
           tmpBalVerdicht
  from     tmpBudget
  group by tmpRksInvoer, tmpRksNaam, tmpDefaultBoekzijde, tmpValNummer, tmpValCode, tmpBalVerdicht;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Verwijderen rekeningen die geen budget hebben (als dit is meegegeven)';
  //call Trace(@@ErrorTextProcedure);
  if @OokZonderbudget = 0 then
    delete tmpBudget where tmpRksInvoer not in (select RksInvoer from tabBudget inner join tabRekeningschema on (RksGid = BudRksGID) where BudBjGid = @BjGid);
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Totaal per rekening in opgegeven valuta bij totaal';
  //call Trace(@@ErrorTextProcedure);
  if (@ValutaVanRekening <> 0) or (@OverzichtInValuta <> @TotalenInValuta) then
    insert into tmpBudget (tmpRegelSoort, tmpRksInvoer, tmpRksNaam, tmpValCode,
                           tmpBudgetInValuta,
                           tmpSaldoInValuta,
                           tmpSorteerVeld, tmpBalDecimalen, tmpBudgetPercentage, tmpPercentage, tmpBalVerdicht)
    select   3, tmpRksInvoer, tmpRksNaam, (select ValCode from tabValuta where ValNummer = @TotalenInValuta),
             ValutaOmrekenen(tmpValNummer, tmpBudgetInValuta, @TotalenInValuta, @BjGid, @TotPernr, 2),
             ValutaOmrekenen(tmpValNummer, tmpSaldoInValuta , @TotalenInValuta, @BjGid, @TotPernr, 2),
             tmpSorteerVeld,
             @AantalCijfers,
             tmpBudgetPercentage,
             tmpPercentage,
             tmpBalVerdicht
    from     tmpBudget
    where    tmpRegelSoort = 2;
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Conform balans';
  //call Trace(@@ErrorTextProcedure);
  if @ComprimeerBalans = 2 then  //Conform balans

    update tmpBudget set tmpBalGid = BlGid, tmpBalDecimalen = DecimalenSubTotalen
    from   tabBalansCodeDetail
    where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(tmpRksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' and DecimalenSubTotalen<>0;

    update tmpBudget set tmpBalGid = BlGid, tmpBalDecimalen = DecimalenSubTotalen
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=0 and Paragraaf = left(tmpRksInvoer,2) and Trim(Paragraaf)<>'' and DecimalenSubTotalen<>0;

    update tmpBudget set tmpBalGid = BlGid, tmpBalDecimalen = DecimalenSubTotalen
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=0 and Rubriek = left(tmpRksInvoer,1) and Paragraaf='' and DecimalenSubTotalen<>0;

    update tmpBudget set tmpBalGid = null;

    update tmpBudget set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(tmpRksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' ;

    update tmpBudget set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=0 and Paragraaf = left(tmpRksInvoer,2) and Trim(Paragraaf)<>'';

    update tmpBudget set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=0 and Rubriek = left(tmpRksInvoer,1) and Paragraaf='';

  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Subtotalen volgens meegegeven aantal decimalen';
  //call Trace(@@ErrorTextProcedure);
  select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;
  set @Koers = KoersTovBasisValuta(@BjGid, @TotPernr, @TotalenInValuta);

  set @Teller = 5;
  while @Teller > 0 loop

    insert into tmpBudget (tmpRegelSoort, tmpSorteerVeld, tmpRksInvoer, tmpRksNaam, tmpValCode, tmpBudgetInValuta, tmpSaldoInValuta,
                           tmpBalVerdicht, tmpBalDecimalen, tmpVerschil, tmpPercentage)

    select   15-@Teller,
             substr(tmpRksInvoer, 1, @Teller)+'z' tmpSorteerVeld,
             substr(tmpRksInvoer, 1, @Teller)+' :' HulpRksInvoer,
             IsNull(OmsBalansCodeDetails, if @Teller = 1 then _U('Rubriek %1!', substr(tmpRksInvoer, 1, 1)) else if @Teller = 2 then _U('Paragraaf %1!', substr(tmpRksInvoer, 1, 2)) else _U('Subparagraaf %1!', substr(tmpRksInvoer, 3, @Teller-2)) endif endif) BalOms,
             @TotaalValCode,
             sum(if tmpRegelSoort = 2 then tmpBudgetInBasisValuta else 0 endif) / @Koers tmpBudgetInValuta,
             sum(if tmpRegelSoort = 2 then tmpSaldoInBasisValuta  else 0 endif) / @Koers tmpSaldoInValuta,
             IsNull(BalansVerdicht, tmpBalVerdicht),
             IsNull(DecimalenSubTotalen, max(tmpBalDecimalen)),
             (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif) tmpVerschil,
            (if tmpBudgetInValuta=0 then 0 else (tmpVerschil / (if tmpBudgetInValuta<0 and tmpVerschil<0 then -tmpBudgetInValuta else tmpBudgetInValuta endif) * 100) endif)
    from     tmpBudget left outer join tabBalanscodeDetail on (DetailBlCode = 0 and RubParSub = substr(tmpRksInvoer, 1, @Teller))
    where    length(tmpRksInvoer)>=@Teller and tmpRksInvoer in (select tmpRksInvoer from tmpBudget where (tmpRegelSoort=2 and tmpBalDecimalen >= @Teller))
    group by HulpRksInvoer, tmpSorteerVeld, BalOms, BalansVerdicht, DecimalenSubTotalen, tmpBalVerdicht;

    set @Teller = @Teller - 1;

  end loop;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Totaal generaal';
  //call Trace(@@ErrorTextProcedure);
  if exists( select 1 from tmpBudget) then
    insert into tmpBudget (tmpRegelSoort, tmpSorteerVeld, tmpRksNaam, tmpValCode, tmpBudgetInValuta, tmpSaldoInValuta,
                           tmpVerschil, tmpPercentage)
    select   99,
             repeat('z',40),
             _U('Van rek. %1! t/m %2!', @VanRks, @TotRks),
             @TotaalValCode,
             sum(tmpBudgetInBasisValuta) / @Koers tmpBudgetInValuta,
             sum(tmpSaldoInBasisValuta)  / @Koers tmpSaldoInValuta,
             (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif) tmpVerschil,
            (if tmpBudgetInValuta=0 then 0 else tmpVerschil / if ((isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * sign(isnull(tmpBudgetInValuta,0))) = 0 then 1 else (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * sign(isnull(tmpBudgetInValuta,0)) * 100 endif endif)
    from     tmpBudget where tmpRegelSoort = 2;
  end if;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriode > Verdichten';
  //call Trace(@@ErrorTextProcedure);
  delete tmpBudget where tmpBalVerdicht = 1 and tmpRegelSoort in (1,2,3);

  if @ComprimeerBalans = 1 then  //comprimeren
    update tmpBudget set tmpregelsoort = 5
    where  ( (@aantalcijfers = 5 and tmpregelsoort = 10)
            or (@aantalcijfers=4 and tmpregelsoort = 11)
            or (@aantalcijfers=3 and tmpregelsoort = 12)
            or (@aantalcijfers=2 and tmpregelsoort = 13)
            or (@aantalcijfers=1 and tmpregelsoort = 14) );
  end if;

  //Verschil bepalen, Percentages voor elke regel bepalen en teken bepalen LET OP: DEZE VOLGORDE AANHOUDEN!!
  update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
  update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
  update tmpBudget set tmpPlusMinTeken = if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif;

  //call TraceEind(@@ErrorTextProcedure);
  select tmpRegelSoort, tmpRksInvoer, tmpRksNaam, tmpPernr, tmpBeginDatum, tmpEindDatum,
         tmpValCode, tmpBudgetInValuta,
         tmpBudgetPercentage, tmpSaldoInValuta, tmpVerschil, tmpPercentage, tmpPlusMinTeken,
         tmpBalVerdicht, tmpBalDecimalen, tmpSorteerveld, if tmpBudgetPercentage is null or tmpRegelSoort = 99 then 0 else 1 endif tmpStreepVoorPercentage
  from   tmpBudget order by tmpSorteerVeld, tmpRegelSoort, tmpPernr;


end;

//call rapBudgetPerRekeningPerPeriode(1, 1, 12, 0, '00000000', '10000000', 0, 2, 0, 3, 0, 2, 0, 2, 0, 5, 20);


create or replace procedure rapBudgetPerRekeningPerPeriodeNaastElkaar
                                               (in @BjGid             Integer,
                                                in @VanPernr          smallint,
                                                in @TotPernr          smallint,
                                                in @SelecteerOp       smallint,      //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
                                                in @VanRks            nchar(40),      //van nummer/zoekcode/naam
                                                in @TotRks            nchar(40),      //t/m nummer/zoekcode/naam
                                                in @SorterenOp        smallint,      //0=Nummer, 1=Zoekcode, 2=Naam, 3=RekeningSoort
                                                in @SoortBoeking      smallint,      //0=definitief, 1=voorlopig, 2=beide
                                                in @OokZonderbudget   smallint,      //0=Nee (alleen rekeningen met budget), 1=Ja
                                                in @VergelijkMet      smallint,      //4=Zoals bij budget, 3=Default-boekzijde, 0=Saldo, 1=Debet, 2=Credit
                                                in @ComprimeerBalans  smallint,      //0=nee, 1=ja, 2=conform balans
                                                in @AantalCijfers     smallint,      //Aantal cijfers waarop getotaliseerd moet worden 1-5 (werkt niet bij conform balans)
                                                in @ValutaVanRekening smallint,      //0=Nee, 1=Ja (er wordt dan niet gekeken wat erbij @OverzichtInValuta staat)
                                                in @OverzichtInValuta integer,       //Valutanummer waarin bedragen moeten worden afgedrukt
                                                in @TotalenInValuta   integer,       //Valutanummer voor subtotalen
                                                in @1PlusMinTeken     numeric(6,2),  //Bij welke percentage een +  of -  afdrukken
                                                in @2PlusMinTeken     numeric(6,2))  //Bij welke percentage een ++ of -- afdrukken

result(tmpRegelSoort integer, tmpRksInvoer nchar(28), tmpRksNaam nchar(40), tmpPernr integer, tmpValCode nchar(3),
       tmpBudgetInValuta numeric(15,2), tmpSaldoInValuta numeric(15,2), tmpVerschil numeric(15,2), tmpPercentage numeric(15,2),
       tmpBalVerdicht smallint, tmpBalDecimalen smallint, tmpSorteerveld nchar(40), tmpPeriode1 nchar(2),
       tmpPeriode2 nchar(2), tmpPeriode3 nchar(2), tmpPeriode4 nchar(2), tmpPeriode5 nchar(2), tmpPeriode6 nchar(2),
       tmpPeriode7 nchar(2), tmpPeriode8 nchar(2), tmpPeriode9 nchar(2), tmpPeriode10 nchar(2), tmpPeriode11 nchar(2),
       tmpPeriode12 nchar(2), tmpPeriode13 nchar(2))

begin

  declare @Teller smallint;
  declare @Koers double;
  declare @TotaalValCode nchar(3);
  declare @OverzichtValCode nchar(3);
  declare @MaxPerNr integer;

  declare local temporary table tmpBudget(
     tmpGid                     integer default AutoIncrement,
     tmpRksInvoer               nchar(28),
     tmpRksNaam                 nchar(40) default '',
     tmpDefaultBoekzijde        smallint,
     tmpPernr                   integer,
     tmpPosOfNeg                smallint,
     tmpValcode                 nchar(3) default  '',
     tmpValNummer               integer,
     tmpBudgetInRksValuta       numeric(15,2),
     tmpBudgetInBasisValuta     numeric(15,2),
     tmpBudgetInValuta          numeric(15,2),
     tmpPlusMinTeken            nchar(2),
     tmpSaldoInValuta           numeric(15,2),
     tmpSaldoInBasisValuta      numeric(15,2),
     tmpVerschil                numeric(15,2),
     tmpPercentage              numeric(15,2),
     tmpSorteerVeld             nchar(40) default '',
     tmpBudVergelijkenMet       smallint,
     tmpRegelSoort              integer,
     tmpBalGid                  integer,
     tmpBalVerdicht             smallint default 0,
     tmpBalDecimalen            smallint default 0,
     tmpBudgetGid               integer,
     tmpPeriode1                nchar(2),
     tmpPeriode2                nchar(2),
     tmpPeriode3                nchar(2),
     tmpPeriode4                nchar(2),
     tmpPeriode5                nchar(2),
     tmpPeriode6                nchar(2),
     tmpPeriode7                nchar(2),
     tmpPeriode8                nchar(2),
     tmpPeriode9                nchar(2),
     tmpPeriode10               nchar(2),
     tmpPeriode11               nchar(2),
     tmpPeriode12               nchar(2),
     tmpPeriode13               nchar(2),
     primary key (tmpGid)
   ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > @VanRks='+@VanRks+', @TotRks='+@TotRks;
  //call TraceBegin(@@ErrorTextProcedure);

  Create index idx_tmpBudgetSoort     on tmpBudget (tmpRegelsoort);
  Create index idx_tmpBudgetSortering on tmpBudget (tmpSorteerVeld);
  Create index idx_tmpBudgetPernr     on tmpBudget (tmpRksInvoer, tmpPernr);

  set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Stap 1';
  //call TraceBegin(@@ErrorTextProcedure);
  select max(PerNr) into @MaxPerNr from tabPeriode where PerBjGid = @BjGid;

//  if (@TotPernr - @VanPernr) <= 12 then
    // gegevens per periode ophalen
    insert into tmpBudget (tmpRegelSoort, tmpPernr, tmpRksInvoer, tmpRksNaam, tmpDefaultBoekzijde, tmpPosOfNeg,
                           tmpValNummer, tmpValCode, tmpBudVergelijkenMet,
                           tmpBudgetInRksValuta, tmpBudgetInBasisValuta, tmpBudgetInValuta,
                           tmpSaldoInBasisValuta, tmpSaldoInValuta,
                           tmpSorteerVeld, tmpBalDecimalen, tmpBalVerdicht, tmpBudgetGid)
    select   1,
             Pernr,
             RksInvoer,
             RksNaam,
           if DefaultBoekzijde = 3 then if DefaultSoort in (2, 5, 7) then 1 else 0 endif else DefaultBoekzijde endif tmpDefaultBoekzijde,
             if tmpDefaultBoekzijde = 1 then -1 else 1 endif tmpPosOfNeg,
            (if @ValutaVanRekening=0 then @OverzichtInValuta else RksValNummer endif) tmpValNummer,
            (select ValCode from tabValuta where ValNummer = tmpValNummer) tmpValCode,
             if @VergelijkMet = 4 and IsNull(VergelijkenMet,0) < 3 then // saldo, debet of credit
               IsNull(VergelijkenMet,0)
             else
               if @VergelijkMet in (3,4) then
                 if tmpDefaultBoekzijde between 0 and 1 then // def.boekzijde debet of credit
                   tmpDefaultBoekzijde + 1
                 else
                   0 // geen voorkeur ---> saldo
                 endif
               else
                 @VergelijkMet // debet of credit
               endif
             endif tmpBudVergelijkenMet, //0=saldo, 1=debet, 2=credit
             tmpPosOfNeg * IsNull(if BudMetVerdeling = 1 then (select JaarBudget * Bud_PercAfronden(BudPerPercentage) / 100 from tabBudgetCodePeriode where BudPerBjGid = @BjGid and BudPernr=Pernr and BudPerBudgetCode = BudBudgetCode)
                                                         else (select BudBedrag from tabBudgetBedrag where BudBedrBjGid= @BjGid and BudBedrPernr=Pernr and BudBedrBudgetGid = BudgetGid) endif, 0) tmpBudgetInRksValuta,
            (if RksValNummer = @@BasisValutaNummer then tmpBudgetInRksValuta else tmpBudgetInRksValuta * KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) endif) tmpBudgetInBasisValuta,
            (if RksValNummer = tmpValnummer then tmpBudgetInRksValuta else tmpBudgetInBasisValuta / KoersTovBasisValuta(@BjGid, @TotPernr, tmpValnummer) endif) tmpBudgetInValuta,
             case @SoortBoeking
               when 0 then // Definitief
                 case tmpBudVergelijkenMet
                   when 0 then  //Saldo
                     IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0)
                   when 1 then  //Debet
                     IsNull(sum(SaldoDebetBasisDefinitief),0)
                   when 2 then  //Credit
                    -IsNull(sum(SaldoCreditBasisDefinitief),0)
                 end
               when 1 then  //Voorlopig
                 case tmpBudVergelijkenMet
                   when 0 then  //Saldo
                     IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                   when 1 then  //Debet
                     IsNull(sum(SaldoDebetBasisVoorlopig),0)
                   when 2 then  //Credit
                    -IsNull(sum(SaldoCreditBasisVoorlopig),0)
                 end
               else
                 case tmpBudVergelijkenMet
                   when 0 then  //Saldo
                     IsNull(sum(SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig),0)
                   when 1 then  //Debet
                     IsNull(sum(SaldoDebetBasisDefinitief),0) + IsNull(sum(SaldoDebetBasisVoorlopig),0)
                   when 2 then  //Credit
                    -IsNull(sum(SaldoCreditBasisDefinitief),0) - IsNull(sum(SaldoCreditBasisVoorlopig),0)
                 end
             end tmpSaldoInBasisValuta,
             cast(tmpSaldoInBasisValuta / KoersTovBasisValuta(@BjGid, @TotPernr, tmpValNummer) as numeric(15,2)) tmpSaldoInValuta,
            (if @SorterenOp = 0 then RksInvoer else if @SorterenOp = 1 then RksZoekcode else if @SorterenOp = 2 then RksNaam else string(DefaultSoort) endif endif endif),
             @AantalCijfers,
            (if @ComprimeerBalans = 1 then 1 else 0 endif),
             BudgetGid
    from     (tabPeriode,
             tabRekeningschema) left outer join tabBudget        on (BudBjGid = @BjGid and BudRksgid = RksGid)
                                left outer join tabRekeningsaldo on (RekSaldoBjGid=@BjGid and RekSaldoRksGid=RksGid and RekSaldoPernr = Pernr)
    where    PerBjGid = @BjGid and
           ((RksInvoer   between @VanRks and @TotRks and @SelecteerOp = 0)  or
            (RksZoekcode between @VanRks and @TotRks and @SelecteerOp = 1)  or
            (RksNaam     between @VanRks and @TotRks and @SelecteerOp = 2)) and
             Pernr between @VanPernr and @TotPernr
    group by RksInvoer, Pernr, RksZoekcode, RksNaam, DefaultSoort, DefaultBoekzijde, RksValNummer, VergelijkenMet, BudMetVerdeling, BudBudgetCode, JaarBudget, BudgetGid;

    //Bereken voor de laatste periode opnieuw het percentage en totaal budget zodat het totaal overeenkomt met het jaarbudget
    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Bereken de laatste periode opnieuw?';
    //call Trace(@@ErrorTextProcedure);
    if @VanPerNr = 1 and @TotPerNr = @MaxPerNr then
      //Alleen indien alle periodes worden afgedrukt! Let op: in 3 stappen!!
     //call Trace('Ja, opnieuw berekenen!');
      update tmpBudget buiten
      set    tmpBudgetInRksValuta   = tmpPosOfNeg * JaarBudget - (select sum(tmpBudgetInRksValuta)   from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksInvoer = buiten.tmpRksInvoer),
             tmpBudgetInBasisValuta = tmpPosOfNeg * JaarBudget * KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) - (select sum(tmpBudgetInBasisValuta) from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksInvoer = buiten.tmpRksInvoer),
             tmpBudgetInValuta      = (tmpPosOfNeg * JaarBudget * if @ValutaVanRekening = 1 then 1 else KoersTovBasisValuta(@BjGid, @TotPernr, RksValNummer) / KoersTovBasisValuta(@BjGid, @TotPernr, @OverzichtInValuta) endif) - (select sum(tmpBudgetInValuta)      from tmpBudget binnen where binnen.tmpPerNr <> @maxPerNr and binnen.tmpRksInvoer = buiten.tmpRksInvoer)
      from   tabBudget inner join tabRekeningschema on (RksGid = BudRksGid)
      where  tmpPerNr = @MaxPerNr and BudMetVerdeling = 1 and BudgetGid = tmpBudgetGid;
    end if;

    //LET OP: DEZE VOLGORDE ZO LATEN!!
    update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
    update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
    update tmpBudget set tmpPlusMinTeken = (if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif);

    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Werk alle perioden bij';
    //call Trace(@@ErrorTextProcedure);
    update tmpBudget set tmpPeriode1      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 0 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode2      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 1 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode3      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 2 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode4      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 3 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode5      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 4 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode6      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 5 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode7      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 6 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode8      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 7 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode9      = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 8 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode10     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 9 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode11     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 10 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode12     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 11 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpPeriode13     = (select tmpPlusMinTeken from tmpBudget a where a.tmpPernr = 12 + @VanPernr and a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpBudgetInValuta= (select sum(tmpBudgetInValuta) from tmpBudget a where a.tmpRksInvoer = tmpBudget.tmpRksInvoer),
                         tmpSaldoInValuta = (select sum(tmpSaldoInValuta)  from tmpBudget a where a.tmpRksInvoer = tmpBudget.tmpRksInvoer)
    where tmpPernr = @VanPernr;

    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Verwijder alles dat ongelijk is aan VanPernr';
    //call Trace(@@ErrorTextProcedure);
    delete tmpBudget where tmpPernr <> @VanPernr;

    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Verwijderen rekeningen die geen budget hebben (als dit is meegegeven)';
    //call Trace(@@ErrorTextProcedure);
    if @OokZonderbudget = 0 then
      delete tmpBudget where tmpRksInvoer not in (select RksInvoer from tabBudget inner join tabRekeningschema on (RksGid = BudRksGID) where BudBjGid = @BjGid);
    end if;

    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Conform balans';
    //call Trace(@@ErrorTextProcedure);
    if @ComprimeerBalans = 2 then  //Conform balans

      update tmpBudget set tmpBalGid = BlGid, tmpBalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(tmpRksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' and DecimalenSubTotalen<>0;

      update tmpBudget set tmpBalGid = BlGid, tmpBalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  tmpBalGid is null and DetailBlCode=0 and Paragraaf = left(tmpRksInvoer,2) and Trim(Paragraaf)<>'' and DecimalenSubTotalen<>0;

      update tmpBudget set tmpBalGid = BlGid, tmpBalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  tmpBalGid is null and DetailBlCode=0 and Rubriek = left(tmpRksInvoer,1) and Paragraaf='' and DecimalenSubTotalen<>0;

      update tmpBudget set tmpBalGid = null;

      update tmpBudget set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(tmpRksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' ;

      update tmpBudget set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  tmpBalGid is null and DetailBlCode=0 and Paragraaf = left(tmpRksInvoer,2) and Trim(Paragraaf)<>'';

      update tmpBudget set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  tmpBalGid is null and DetailBlCode=0 and Rubriek = left(tmpRksInvoer,1) and Paragraaf='';

    end if;

    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Subtotalen volgens meegegeven aantal decimalen';
    //call Trace(@@ErrorTextProcedure);
    select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;
    set @Koers = KoersTovBasisValuta(@BjGid, @TotPernr, @TotalenInValuta);
    set @Teller = 5;
    while @Teller > 0 loop

      insert into tmpBudget (tmpRegelSoort, tmpSorteerVeld, tmpRksInvoer, tmpRksNaam, tmpValCode, tmpBudgetInValuta, tmpSaldoInValuta,
                             tmpBalVerdicht, tmpBalDecimalen)

      select   15-@Teller,
               substr(tmpRksInvoer, 1, @Teller)+'z' tmpSorteerVeld,
               substr(tmpRksInvoer, 1, @Teller)+' :' HulpRksInvoer,
               IsNull(OmsBalansCodeDetails, if @Teller = 1 then _U('Rubriek %1!', substr(tmpRksInvoer, 1, 1)) else if @Teller = 2 then _U('Paragraaf %1!', substr(tmpRksInvoer, 1, 2)) else _U('Subparagraaf %1!', substr(tmpRksInvoer, 3, @Teller-2)) endif endif) BalOms,
               @TotaalValCode,
               sum(ValutaOmrekenen(tmpValNummer, tmpBudgetInValuta, @TotalenInValuta, @BjGid, @TotPernr, 2)) BudgetInValuta,
               sum(ValutaOmrekenen(tmpValNummer, tmpSaldoInValuta,  @TotalenInValuta, @BjGid, @TotPernr, 2)) SaldoInValuta,
               IsNull(BalansVerdicht, max(tmpBalVerdicht)),
               IsNull(DecimalenSubTotalen, max(tmpBalDecimalen))
      from     tmpBudget left outer join tabBalanscodeDetail on (DetailBlCode = 0 and RubParSub = substr(tmpRksInvoer, 1, @Teller))
      where    length(tmpRksInvoer)>=@Teller and tmpRksInvoer in (select tmpRksInvoer from tmpBudget where (tmpRegelSoort=1 and tmpBalDecimalen >= @Teller))
      group by HulpRksInvoer, tmpSorteerVeld, BalOms, BalansVerdicht, DecimalenSubTotalen;

      set @Teller = @Teller - 1;

    end loop;

    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Totaal generaal';
    //call Trace(@@ErrorTextProcedure);

    if exists( select 1 from tmpBudget) then

      insert into tmpBudget (tmpRegelSoort, tmpSorteerVeld, tmpRksInvoer, tmpValCode, tmpBudgetInValuta, tmpSaldoInValuta,
                             tmpVerschil, tmpPercentage)
      select   99,
               repeat('z',40),
               'Van rek. '+@VanRks+' t/m '+@TotRks,
               @TotaalValCode,
               ROUND(sum(ValutaOmrekenen(tmpValNummer, tmpBudgetInValuta, @TotalenInValuta, @BjGid, @TotPernr, 2)), 2) tmpBudgetInValuta,
               ROUND(sum(ValutaOmrekenen(tmpValNummer, tmpSaldoInValuta,  @TotalenInValuta, @BjGid, @TotPernr, 2)), 2) tmpSaldoInValuta,
              (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif) tmpVerschil,
              (if tmpBudgetInValuta=0 then 0 else (tmpVerschil / (if tmpBudgetInValuta<0 and tmpVerschil<0 then -tmpBudgetInValuta else tmpBudgetInValuta endif) * 100) endif)
      from     tmpBudget where tmpRegelSoort = 1;
    end if;

    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Verdichten';
    //call Trace(@@ErrorTextProcedure);
    delete tmpBudget where tmpBalVerdicht = 1 and tmpRegelSoort = 1;

    if @ComprimeerBalans = 1 then  //comprimeren
      update tmpBudget set tmpRegelsoort = 5
      where  ( (@aantalcijfers = 5 and tmpregelsoort = 10)
              or (@aantalcijfers=4 and tmpregelsoort = 11)
              or (@aantalcijfers=3 and tmpregelsoort = 12)
              or (@aantalcijfers=2 and tmpregelsoort = 13)
              or (@aantalcijfers=1 and tmpregelsoort = 14) );
    end if;

    set @@ErrorTextProcedure = 'rapBudgetPerRekeningPerPeriodeNaastElkaar > Nu nog even percentage etc. voor elke regel bepalen';
    //call Trace(@@ErrorTextProcedure);
    update tmpBudget set tmpVerschil     = (isnull(tmpSaldoInValuta,0) - isnull(tmpBudgetInValuta,0)) * (if isnull(tmpBudgetInValuta,0) < 0 then -1 else 1 endif);
    update tmpBudget set tmpPercentage   = (if tmpBudgetInValuta = 0 then 0 else abs(tmpVerschil) / abs(tmpBudgetInValuta) * if sign(tmpVerschil)=-1 then -1 else 1 endif endif * 100);
    update tmpBudget set tmpPlusMinTeken = (if abs(tmpPercentage) > abs(@2PlusMinTeken) then (if tmpPercentage < 0 then '--' else '++' endif) else (if abs(tmpPercentage) > abs(@1PlusMinTeken) then (if tmpPercentage < 0 then '-' else '+' endif) endif) endif);

    //call TraceEind(@@ErrorTextProcedure);
    select tmpRegelSoort, tmpRksInvoer, tmpRksNaam, tmpPernr, tmpValCode, tmpBudgetInValuta,
           tmpSaldoInValuta, tmpVerschil, tmpPercentage,
           tmpBalVerdicht, tmpBalDecimalen, tmpSorteerveld,
           tmpPeriode1, tmpPeriode2, tmpPeriode3, tmpPeriode4, tmpPeriode5, tmpPeriode6,
           tmpPeriode7, tmpPeriode8, tmpPeriode9, tmpPeriode10, tmpPeriode11, tmpPeriode12, tmpPeriode13
    from   tmpBudget order by tmpSorteerVeld, tmpRegelSoort, tmpPernr;

//  else
//    select * from dummy where 1=0
//  end if;


end;

//call rapBudgetPerRekeningPerPeriodeNaastElkaar(1, 1, 12, 0, '40000000', '50000000', 0, 2, 0, 3, 0, 2, 0, 0, 0, 5, 20);


create or replace procedure rapDagboekMutatiesDagboeken(
in @BjGid               integer,
in @SelecteerOp         smallint,       //1 = DgbCode, 2 = DgbNaam
in @VanDagboek          nchar(40),
in @TotDagboek          nchar(40),
in @IsPerPeriode        smallint,       //0=mutaties per stuknummer, 1=mutaties per periode
in @VanPernrOfStuknr    numeric(10,0),  //Periodenr of stuknummer
in @TotPernrOfStuknr    numeric(10,0),
in @DagboekSoort        nchar(6),
in @SoortBoeking        smallint,      //0=definitief, 1=voorlopig, 2=beide
in @TotalenInValuta     smallint,      //0=Valuta van tegenrekening, 1=basis, 2=Ander valuta
in @ValutaNummer        integer)       //indien @TotalenInValuta = 2, dan hier valutanummer invullen
result( DgbGid integer, DgbCode nchar(15), OmsDagboek nchar(40), RksInvoer nchar(28), RksNaam nchar(40), ValNummer integer, ValCode nchar(3),
        SaldoBeginBedragInBasisVal numeric(15,2), SaldoEindBedragInBasisVal numeric(15,2),
        SaldoBeginBedragInValVanDagboek numeric(15,2), SaldoEindBedragInValVanDagboek numeric(15,2),
        SaldoBeginBedragInAndereVal numeric(15,2), SaldoEindBedragInAndereVal numeric(15,2),
        ValNummerTegenRekening integer, ValCodeTegenRekening nchar(3), DagboekSoort integer)
begin
  //Alle dagboeken die relevant zijn in de range en alleen met (relevante) mutaties
  //LET OP: Als valuta van de tegenrekening wordt gebruikt wat is ingesteld, dus de valuta van de tegenrekening, de basisvaluta of andere valuta
  declare @ValNummer integer;
  declare @ValCode   nchar(3);
  declare @PerNrVoorKoers integer;

  //call TraceBegin('rapDagboekMutatiesDagboeken(@BjGid='+string(@BjGid)+', @SelecteerOp='+string(@SelecteerOp)+', @VanDagboek='+@VanDagboek+', @TotDagboek='+@TotDagboek+', @IsPerPeriode='+string(@IsPerPeriode)+', @VanPernrOfStuknr='+string(@VanPernrOfStuknr)+', @TotPernrOfStuknr='+string(@TotPernrOfStuknr)+', @DagboekSoort='+@DagboekSoort+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call trace('... @TotalenInValuta='+string(@TotalenInValuta)+', @ValutaNummer='+string(@ValutaNummer)+')');

  if @IsPerPeriode = 1 then
    set @PerNrVoorKoers = @TotPernrOfStuknr; // ACW 23-09-2002: Hier stond @IsPerPeriode;
  else
    select max(PerNr) into @PerNrVoorKoers from tabperiode where PerBjGid = @BjGid;
  end if;

  case @TotalenInValuta
  when 1 then //Basisvaluta
    select ValNummer, ValCode into @ValNummer, @ValCode from tabValuta where ValNummer = @@BasisValutaNummer;
  when 2 then //Andere valuta
    select ValNummer, ValCode into @ValNummer, @ValCode from tabValuta where ValNummer = @ValutaNummer;
  end case;


  //call TraceEind( 'rapDagboekMutatiesDagboeken');

  select  distinct DgbGid, DgbCode, OmsDagboek, RksInvoer, RksNaam,
          if @TotalenInValuta = 0 then RksValNummer else @ValNummer endif,
          if @TotalenInValuta = 0 then ValCode      else @ValCode endif,
          //Beginbedrag in basisvaluta
          if @IsPerPeriode = 1 then
            isnull((select sum(case @SoortBoeking
                               when 0 then //Definitief
                                 SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief
                               when 1 then //Voorlopig
                                 SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig
                               when 2 then //Beide
                                 SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief - SaldoCreditBasisVoorlopig - SaldoCreditBasisDefinitief
                               end)
                    from   tabRekeningsaldo
                    where  RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr < if dagboeksoort<>5 and @VanPerNrOfStukNr = 0 then 1 else @VanPerNrOfStukNr endif
            ),0)
          endif SaldoBeginBedragInBasisVal,

          //Eindbedrag in basisvaluta
          if @IsPerPeriode = 1 then
            isnull((select sum(case @SoortBoeking
                               when 0 then //Definitief
                                 SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief
                               when 1 then //Voorlopig
                                 SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig
                               when 2 then //Beide
                                 SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief - SaldoCreditBasisVoorlopig - SaldoCreditBasisDefinitief
                               end)
                    from   tabRekeningsaldo
                    where  RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr <= @TotPerNrOfStukNr
             ),0)
           endif SaldoEindBedragInBasisVal,

          //Beginbedrag in valuta van afdruk van dagboek
          if @IsPerPeriode = 1 then
            isnull((select sum(case @SoortBoeking
                               when 0 then //Definitief
                                 if RekSaldoValNummer = if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif then
                                   SaldoDebetValutaDefinitief - SaldoCreditValutaDefinitief
                                 else
                                   cast((SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif) as numeric(15,2))
                                 endif
                               when 1 then //Voorlopig
                                 if RekSaldoValNummer = if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif then
                                   SaldoDebetValutaVoorlopig - SaldoCreditValutaVoorlopig
                                 else
                                   cast((SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif) as numeric(15,2))
                                 endif
                               when 2 then //Beide
                                 if RekSaldoValNummer = if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif then
                                   SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief - SaldoCreditValutaVoorlopig - SaldoCreditValutaDefinitief
                                 else
//                                   ValutaOmrekenen(RekSaldoValNummer, SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief - SaldoCreditValutaVoorlopig - SaldoCreditValutaDefinitief, if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif, @BjGid, RekSaldoPernr, 2)
                                   cast((SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief - SaldoCreditBasisVoorlopig - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif) as numeric(15,2))
                                 endif
                               end)
                    from   tabRekeningsaldo inner join tabRekeningschema a on (a.rksgid = reksaldorksgid)
                    where  RekSaldoRksGid = tabRekeningschema.RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr < if dagboeksoort<>5 and @VanPerNrOfStukNr = 0 then 1 else @VanPerNrOfStukNr endif
              ),0)
          else
            //Per stuknummer -> neem alle beginbalans-boekingen en de boekstuknummers lager dan de van-boekstuk van dit dagboek vanuit het journaal
            // ACW 23-09-2002: Beperking: voorl/definititef worden nu ook gecontroleerd (in de where-clausule!)
            isnull((select sum(if IsCreditBoeking = 1 then -1 else 1 endif *
                                if JrValNummer = if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif then
                                  jrValutaBedrag
                                else
                                  cast(jrBasisBedrag / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif) as numeric(15,2))
                                endif)
                    from (tabjournaalregel saldoJournaalRegel inner join tabjournaalpost saldoJournaalpost on (saldoJournaalpost.JpGid = saldoJournaalRegel.JrJpGid) inner join tabdagboek saldoDagboek on (saldoDagboek.DgbGid = saldoJournaalpost.JpDgbGid) inner join tabBoekingsgang saldoBoekgang on (saldoBoekgang.BoekgangGid = saldoJournaalpost.JpBoekgangGid))
                         inner join tabRekeningschema a on (JrRksGid = a.RksGid)
                    where JrRksGid = DitDagboek.DgbTegenRksGid and jpbjgid = @BjGid
                          and (boekstuknummer      < @VanPernrOfStuknr or saldoDagboek.dagboeksoort = 5) //Alleen lagere stuknummers + beginbalans
                          and (saldoDagboek.DgbGid = DitDagboek.DgbGid or saldoDagboek.dagboeksoort = 5) //Alleen dit dagboek + beginbalans
                          and ((@SoortBoeking = 0 and saldoBoekgang.IsBoekGangDefinitief = 1)
                               or (@SoortBoeking = 1 and saldoBoekgang.IsBoekGangDefinitief = 0)
                               or (@SoortBoeking = 2)
                              )
                   ),0)
          endif SaldoBeginBedragInValVanDagboek,

          //Eindbedrag in valuta van afdruk van dagboek
          if @IsPerPeriode = 1 then
            isnull((select sum(case @SoortBoeking
                               when 0 then //Definitief
                                 if RekSaldoValNummer = if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif then
                                   SaldoDebetValutaDefinitief - SaldoCreditValutaDefinitief
                                 else
                                   cast((SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif) as numeric(15,2))
                                 endif
                               when 1 then //Voorlopig
                                 if RekSaldoValNummer = if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif then
                                   SaldoDebetValutaVoorlopig - SaldoCreditValutaVoorlopig
                                 else
                                   cast((SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif) as numeric(15,2))
                                 endif
                               when 2 then //Beide
                                 if RekSaldoValNummer = if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif then
                                   SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief - SaldoCreditValutaVoorlopig - SaldoCreditValutaDefinitief
                                 else
                                   cast((SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief - SaldoCreditBasisVoorlopig - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, if @TotalenInValuta = 0 then a.RksValNummer else @ValNummer endif) as numeric(15,2))
//                                   ValutaOmrekenen(RekSaldoValNummer, SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief - SaldoCreditValutaVoorlopig - SaldoCreditValutaDefinitief, if @TotalenInValuta = 0 then RksValNummer else @ValNummer endif, @BjGid, RekSaldoPernr, 2)
                                 endif
                               end)
                    from   tabRekeningsaldo inner join tabRekeningschema a on (a.RksGid = RekSaldoRksGid)
                    where  RekSaldoRksGid = tabRekeningschema.RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr <= @TotPerNrOfStukNr
            ),0)
          else
            //Per stuknummer -> neem alle beginbalans-boekingen en de boekstuknummers lager dan de van-boekstuk van dit dagboek vanuit het journaal
            // ACW 23-09-2002: Beperking: voorl/definititef worden nu ook gecontroleerd (in de where-clausule!)
            isnull((select sum(if IsCreditBoeking=1 then -1 else 1 endif *
                                if JrValNummer = if @TotalenInValuta = 0 then SaldoRks.RksValNummer else @ValNummer endif then
                                  jrValutaBedrag
                                else
                                  cast(jrBasisBedrag / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, if @TotalenInValuta = 0 then SaldoRks.RksValNummer else @ValNummer endif) as numeric(15,2))
                                endif)
                    from tabrekeningschema saldoRks inner join tabjournaalregel saldoJournaalRegel on (saldoJournaalRegel.JrRksGid = saldoRks.RksGid) inner join tabjournaalpost saldoJournaalpost on (saldoJournaalpost.JpGid = saldoJournaalRegel.JrJpGid) inner join tabdagboek saldoDagboek on (saldoDagboek.DgbGid = saldoJournaalpost.JpDgbGid) inner join tabBoekingsgang saldoBoekgang on (saldoBoekgang.BoekgangGid = saldoJournaalpost.JpBoekgangGid)
                    where saldoRks.rksGid = DitDagboek.DgbTegenRksGid and jpbjgid=@BjGid
                          and (boekstuknummer     <= @TotPernrOfStuknr or saldoDagboek.dagboeksoort = 5) //Alleen lagere stuknummers + beginbalans
                          and (saldoDagboek.DgbGid = DitDagboek.DgbGid or saldoDagboek.dagboeksoort = 5) //Alleen dit dagboek + beginbalans
                          and ((@SoortBoeking = 0 and saldoBoekgang.IsBoekGangDefinitief = 1)
                               or (@SoortBoeking = 1 and saldoBoekgang.IsBoekGangDefinitief = 0)
                               or (@SoortBoeking = 2)
                              )
                   ),0)
          endif SaldoEindBedragInValVanDagboek,

          //Beginbedrag in andere valuta
          if @IsPerPeriode = 1 then
            isnull((select sum(case @SoortBoeking
                               when 0 then //Definitief
                                 if RekSaldoValNummer = @ValutaNummer then
                                   SaldoDebetValutaDefinitief - SaldoCreditValutaDefinitief
                                 else
                                   cast((SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @ValutaNummer) as numeric(15,2))
                                 endif
                               when 1 then //Voorlopig
                                 if RekSaldoValNummer = @ValutaNummer then
                                   SaldoDebetValutaVoorlopig - SaldoCreditValutaVoorlopig
                                 else
                                   cast((SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @ValutaNummer) as numeric(15,2))
                                 endif
                               when 2 then //Beide
                                 if RekSaldoValNummer = @ValutaNummer then
                                   SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief - SaldoCreditValutaVoorlopig - SaldoCreditValutaDefinitief
                                 else
                                   cast((SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief - SaldoCreditBasisVoorlopig - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @ValutaNummer) as numeric(15,2))
                                 endif
                               end)
                    from   tabRekeningsaldo
                    where  RekSaldoRksGid = tabRekeningschema.RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr < if dagboeksoort<>5 and @VanPerNrOfStukNr = 0 then 1 else @VanPerNrOfStukNr endif
              ),0)
          endif SaldoBeginBedragInAndereVal,

          //Eindbedrag in andere valuta
          if @IsPerPeriode = 1 then
            isnull((select sum(case @SoortBoeking
                               when 0 then //Definitief
                                 if RekSaldoValNummer = a.RksValNummer then
                                   SaldoDebetValutaDefinitief - SaldoCreditValutaDefinitief
                                 else
                                   cast((SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, a.RksValNummer) as numeric(15,2))
                                 endif
                               when 1 then //Voorlopig
                                 if RekSaldoValNummer = a.RksValNummer then
                                   SaldoDebetValutaVoorlopig - SaldoCreditValutaVoorlopig
                                 else
                                   cast((SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, a.RksValNummer) as numeric(15,2))
                                 endif
                               when 2 then //Beide
                                 if RekSaldoValNummer = a.RksValNummer then
                                   SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief - SaldoCreditValutaVoorlopig - SaldoCreditValutaDefinitief
                                 else
                                   cast((SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief - SaldoCreditBasisVoorlopig - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, a.RksValNummer) as numeric(15,2))
                                 endif
                               end)
                    from   tabRekeningsaldo inner join tabRekeningschema a on (a.RksGid = RekSaldoRksGid)
                    where  RekSaldoRksGid = tabRekeningschema.RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr <= @TotPerNrOfStukNr
            ),0)
          endif SaldoEindBedragInAndereVal,
          ValNummer ValNummerTegenRekening,
          ValCode ValCodeTegenRekening,
          DagboekSoort

  from    tabBoekingsgang
          inner join tabJournaalPost  on (JpBoekgangGid = BoekgangGid)
          inner join tabJournaalRegel on (JrJpGid = JpGid)
          inner join tabDagboek DitDagboek on (DitDagboek.DgbGid = JpDgbGid)
          inner join tabRekeningschema on (DgbTegenRksGid = RksGid)
          inner join tabValuta on (ValNummer = RksValNummer) //Valuta van het dagboek
  where ((@SelecteerOp  = 1 and DgbCode    between @VanDagboek and @TotDagboek) or
         (@SelecteerOp  = 2 and OmsDagboek between @VanDagboek and @TotDagboek)) and
          Locate(@DagboekSoort, string(DagboekSoort))<>0 and
        ((@SoortBoeking = 0 and IsBoekGangDefinitief =  1) or
         (@SoortBoeking = 1 and IsBoekGangDefinitief =  0) or
         (@SoortBoeking = 2)) and
        ((@IsPerPeriode <> 0 and JrPernr        between @VanPernrOfStuknr and @TotPernrOfStuknr) or
         (@IsPerPeriode = 0  and BoekstukNummer between @VanPernrOfStuknr and @TotPernrOfStuknr)) and
          JpBjGid = @BjGid //and JrBjGid = @BjGid
  order by DgbCode;


end;

//call rapDagboekMutatiesDagboeken(2, 0, '', 'zzzzzzzz', 0, 0, 12, '012345',2, 0, null);


//JV, 25 april 08, iom PG, nav bug 22104: zowel sorteren als afdrukken: de JrBoekdatum, niet de Boekdatum(van Journaalpost)
//beide datums nu ook in resultaatset, dus van post en regel
create or replace procedure rapDagboekMutatiesMutaties(
in @BjGid                  integer,
in @DgbGid                 integer,
in @IsPerPeriode           smallint,       //1=mutaties per periode, 0=mutaties per stuknummer
in @VanPernrOfStuknr       numeric(10,0),  //Periodenr of stuknummer
in @TotPernrOfStuknr       numeric(10,0),
in @SoortBoeking           smallint,       //0=definitief, 1=voorlopig, 2=beide
in @SubtotaalPerStukNr     smallint,       //0=geen subtotaal, 1=subtotalen per stuknummer
in @MutatiesAfdrukkenIn    smallint,       //0=valuta van mutatie, 1=valuta van dagboek, 2=In basisvaluta, 3=in andere valuta
in @MutatiesAfdrukkenInVal integer,        //0=valuta van mutatie, 1=valuta van dagboek, 2=in andere valuta
in @TotalenInValuta        smallint,       //0=Valuta van tegenrekening, 1=basis, 2=ander valuta)
in @TotalenAfdrukkenInVal  integer,        //indien @TotalenInValuta = 2, dan hier valutanummer invullen
in @OrderBy                integer,        //0 = factuurnummer, 1 = boekdatum, 2 = journaalregel, 3 = Stuknummer
in @Ascending              smallint)       //0 = Descending, 1 = Ascending

result (RegelNummer           integer,       BoekDatum           datetime, BoekStukNummer numeric(10,0),
        OmsJournaalPost       nchar(40),      VolgNummer          nchar(3),  StukVolgNummer nchar(19),
        JrRksInvoer           nchar(28),      RksZoekCode         nchar(10), RksNaam        nchar(40),
        JrReferentie          nchar(40),      OmsJournaalRegel    nchar(40),
        ValNummerMutatie      integer,       ValCodeMutatie      nchar(3),
        ValNummerAfdruk       integer,       ValCodeAfdruk       nchar(3),
        StukNummerGroep       numeric(10,0),
        DebetinBasisVal       numeric(15,2), CreditinBasisVal        numeric(15,2),
        DebetinMutatieVal     numeric(15,2), CreditinMutatieVal      numeric(15,2), //Deze wordt bij de mutatie afgedrukt!
        DebetinTegenVal       numeric(15,2), creditInTegenVal        numeric(15,2),
        DebetinAndereVal      numeric(15,2), creditInAndereVal       numeric(15,2),
        DebetInAfdruk         numeric(15,2), CreditInAfdruk          numeric(15,2),
        HulpRekRksNummer      nchar(28),      HulpRekRksNaam          nchar(40),
        HulpRekRksZoekCode    nchar(10),      HulpRekIsCredit         smallint,
        HulpRekBedragInTotaal numeric(15,2), HulpRekBedragInBasisVal numeric(15,2),
        HulpRekValNummer      integer,       HulpRekValutaBedrag     numeric(15,2),
        RunningSumBedrag      numeric(15,2), //Let op: HulprekBedrag en running-sum altijd in valuta van dagboektotaal!
        Aantal                numeric(15,3),
        BoekdatumJPost        datetime)
begin

  declare @DgbRksGid       integer;
  //Mutaties afdrukken in deze valuta
  declare @ValNummerAfdruk integer;
  declare @ValCodeAfdruk   nchar(3);
  //Totaal van dagboek afdrukken in deze valuta
  declare @ValNummerTotaal integer;
  //tbv. running-sum berekening
  declare @RunningSum      numeric(15,2);
  declare @MutGid          integer;
  declare @Totaal          numeric(15,2);
  declare @SoortDagboek    integer;
  declare @PerNrVoorKoers  integer;
  declare @KoersMutaties   float;
  declare @tmpPeriode      integer;

  declare local temporary table mutaties(
    MutGid              integer, // default autoincrement,
    JrGid               integer,
    MutJrRksGid         integer,
    StukVolgNummer      nchar(19),
    mutRegelNummer      integer,
    DebetinBasisVal     numeric(15,2), CreditinBasisVal   numeric(15,2),
    DebetinMutatieVal   numeric(15,2), CreditinMutatieVal numeric(15,2),
    DebetinTegenVal     numeric(15,2), creditInTegenVal   numeric(15,2),
    DebetinAndereVal    numeric(15,2), creditInAndereVal  numeric(15,2),
    DebetInAfdruk       numeric(15,2), CreditInAfdruk     numeric(15,2),
    HulpRekRksGid       integer,       HulpRekIsCredit    smallint,
    HulpRekBedrag       numeric(15,2), HulpRekInBasisVal  numeric(15,2),
    HulpRekValNummer    integer,
    HulpRekValutaBedrag numeric(15,2),
    RunningSumBedrag    numeric(15,2)
  ) on commit preserve rows;

  //Cursor voor running-sum maken
  declare cursor_RunningSum dynamic scroll cursor for
    select MutGid, RunningSumBedrag
    from   Mutaties
    where  MutJrRksGid <> @DgbRksGid
    order by MutGid
    for update;

  declare @KoersTovBasisVanTotaal  float;
  declare @KoersTovBasisVanDagboek float;
  declare @KoersTovBasisVanAfdruk  float;
  declare @ValNummerVanTegenRksGid integer;

  //call TraceBegin('rapDagboekMutatiesMutaties (@BjGid='+string(@BjGid)+', @DgbGid='+string(@DgbGid)+', @IsPerPeriode='+string(@IsPerPeriode)+', @VanPernrOfStuknr='+string(@VanPernrOfStuknr)+', @TotPernrOfStuknr='+string(@TotPernrOfStuknr)+', @SoortBoeking='+string(@SoortBoeking)+', @SubtotaalPerStukNr='+string(@SubtotaalPerStukNr)+', @MutatiesAfdrukkenIn='+string(@MutatiesAfdrukkenIn)+', ...');
  //call Trace('..., @MutatiesAfdrukkenInVal='+string(@MutatiesAfdrukkenInVal)+', @TotalenInValuta='+string(@TotalenInValuta)+', @TotalenAfdrukkenInVal='+string(@TotalenAfdrukkenInVal)+')');

  if @IsPerPeriode = 1 then
    set @PerNrVoorKoers = @TotPernrOfStuknr; //ACW 23-09-2002: Hier stond @IsPerPeriode;
  else
    select max(PerNr) into @PerNrVoorKoers from tabperiode where PerBjGid = @BjGid;
  end if;

  set @KoersMutaties = KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @MutatiesAfdrukkenInVal);

  case @MutatiesAfdrukkenIn
//when 0 then //Valuta van boeking
  when 1 then //Val. van dagboek
    select ValNummer, ValCode into @ValNummerAfdruk, @ValCodeAfdruk from tabDagboek inner join tabRekeningschema on DgbTegenRksGid = RksGid inner join tabValuta on RksValNummer = ValNummer where DgbGid = @DgbGid;
  when 2 then //Basisvaluta
    select ValNummer, ValCode into @ValNummerAfdruk, @ValCodeAfdruk from tabValuta where ValNummer = @@BasisValutaNummer;
  when 3 then //Andere valuta
    select ValNummer, ValCode into @ValNummerAfdruk, @ValCodeAfdruk from tabValuta where ValNummer = @MutatiesAfdrukkenInVal;
  end case;

  case @TotalenInValuta
  when 0 then //Valuta van tegenrekening
    select ValNummer into @ValNummerTotaal from tabDagboek inner join tabRekeningschema on DgbTegenRksGid = RksGid inner join tabValuta on RksValNummer = ValNummer where DgbGid = @DgbGid;
  when 1 then //basis
    set @ValNummerTotaal = @@BasisValutaNummer;
  when 2 then //ander valuta
    set @ValNummerTotaal = @TotalenAfdrukkenInVal;
  end case;

  set @KoersTovBasisVanTotaal = KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @ValNummerTotaal);

  select DgbTegenRksGid, DagboekSoort into @DgbRksGid, @SoortDagboek from tabDagboek where DgbGid = @DgbGid;
  select RksValNummer into @ValNummerVanTegenRksGid from tabRekeningSchema where RksGid = @DgbRksGid;

  set @KoersTovBasisVanDagboek = KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @ValNummerVanTegenRksGid);
  set @KoersTovBasisVanAfdruk  = KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @ValNummerAfdruk);

  insert into mutaties(MutGid, JrGid, mutRegelNummer, MutJrRksGid, StukVolgNummer,
        DebetinBasisVal, CreditinBasisVal, DebetinMutatieVal, CreditinMutatieVal,
        DebetinTegenVal, creditInTegenVal, DebetinAndereVal, creditInAndereVal,
        DebetInAfdruk, CreditInAfdruk, HulpRekRksGid, HulpRekIsCredit, HulpRekBedrag, HulpRekInBasisVal, HulpRekValNummer, HulpRekValutaBedrag, RunningSumBedrag)
  select  number(),
          JrGid,
          RegelNummer,
          JrRksGid,
          string(BoekstukNummer)+'.'+right('000'+string(StukVolgnr),3) StukVolgNummer,
          //Debetbedrag in basisvaluta
         (if IsCreditBoeking  = 0 then jrBasisBedrag endif) DebetinBasisVal,
          //Creditbedrag in basisvaluta
         (if IsCreditBoeking <> 0 then jrBasisBedrag endif) CreditinBasisVal,

          //Debetbedrag in valuta van mutatie-afdruk
         (if IsCreditBoeking  = 0 then
            case @MutatiesAfdrukkenIn
            when 0 then //Val van Mutatie
              jrValutaBedrag
            when 1 then //Val. van dagboek
              if @ValNummerVanTegenRksGid = JrValNummer then
                jrValutaBedrag
              else
                jrBasisBedrag / KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerVanTegenRksGid) //@KoersTovBasisVanDagboek
              endif
            when 2 then //Basisvaluta
              jrBasisBedrag
            when 3 then //Andere valuta
              if @MutatiesAfdrukkenInVal = JrValNummer then
                jrValutaBedrag
              else
                jrBasisBedrag / @KoersMutaties
              endif
            end
          endif) DebetinMutatieVal,
          //Creditbedrag in valuta van mutatie-afdruk
         (if IsCreditBoeking <> 0 then
            case @MutatiesAfdrukkenIn
            when 0 then //Val van Mutatie
              jrValutaBedrag
            when 1 then //Val. van dagboek
              if DgbRks.RksValNummer = JrValNummer then
                jrValutaBedrag
              else
                jrBasisBedrag / KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerVanTegenRksGid)//@KoersTovBasisVanDagboek
              endif
            when 2 then //Basisvaluta
              jrBasisBedrag
            when 3 then //Andere valuta
              if @MutatiesAfdrukkenInVal = JrValNummer then
                jrValutaBedrag
              else
                jrBasisBedrag / @KoersMutaties
              endif
            end
          endif) CreditinMutatieVal,

          //Debetbedrag in valuta van totalen
         (if IsCreditBoeking  = 0 then
            if @ValNummerTotaal = JrValNummer then
              jrValutaBedrag
            else
              jrBasisBedrag / if @TotalenInValuta = 0 then KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerVanTegenRksGid)/*@KoersTovBasisVanDagboek*/ else KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerTotaal)/*@KoersTovBasisVanTotaal*/ endif
            endif
          endif) DebetinTegenVal,
          //Creditbedrag in valuta van totalen
         (if IsCreditBoeking <> 0 then
            if @ValNummerTotaal = JrValNummer then
              jrValutaBedrag
            else
              jrBasisBedrag / if @TotalenInValuta = 0 then KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerVanTegenRksGid)/*@KoersTovBasisVanDagboek*/ else KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerTotaal)/*@KoersTovBasisVanTotaal*/ endif
            endif
          endif) creditinTegenVal,

          //Debetbedrag in andere valuta van totaal-valuta
         (if IsCreditBoeking  = 0 then
            if @ValNummerAfdruk = JrValNummer then
              jrValutaBedrag
            else
              jrBasisBedrag / KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerAfdruk)//@KoersTovBasisVanAfdruk
            endif
          endif) DebetinAndereVal,
          //Creditbedrag in andere valuta van totaal-valuta
         (if IsCreditBoeking <> 0 then
            if @ValNummerAfdruk = JrValNummer then
              jrValutaBedrag
            else
              jrBasisBedrag / KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerAfdruk)//@KoersTovBasisVanAfdruk
            endif
          endif) creditinAndereVal,

          //Debetbedrag in afdruk-valuta
          case @MutatiesAfdrukkenIn
          when 0 then //valuta van mutatie
            DebetInMutatieVal
          when 1 then //valuta van dagboek
            DebetInTegenVal
          when 2 then //Basisvaluta
            DebetinBasisVal
          when 3 then //in andere valuta
            DebetInAndereVal
          end DebetInAfdruk,
          //Creditbedrag in afdruk-valuta
          case @MutatiesAfdrukkenIn
          when 0 then //valuta van mutatie
            CreditInMutatieVal
          when 1 then //valuta van dagboek
            CreditInTegenVal
          when 2 then //Basisvaluta
            CreditinBasisVal
          when 3 then //in andere valuta
            CreditInAndereVal
          end CreditInAfdruk,

          HulpRekRksGid,
          HulpRekIsCredit,
          //Bedrag van hulprekening (in zelfde valuta als dagboek(sub)totalen)
          if HulpRekIsCredit = 1 then -1 else 1 endif *
            if @ValNummerTotaal = HulprekValNummer then
              HulpRekValutaBedrag
            else
              HulpRekBasisBedrag / KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerTotaal)//@KoersTovBasisVanTotaal
            endif HulpRekBedrag,
          HulpRekBasisBedrag HulpRekInBasisVal,
          HulpRekValNummer,
          HulpRekValutaBedrag,
          //Meelopend saldo
          if JrRksGid <> @DgbRksGid or SoortBoeking <> 1 then // Altijd een running sum als geen tegenboeking op tegenrek. van dagboek
            if @ValNummerTotaal = JrValNummer then
              jrValutaBedrag
            else
              jrBasisBedrag / KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerTotaal)//@KoersTovBasisVanTotaal
            endif
            * if IsCreditBoeking = 0 then -1 else 1 endif
          endif RunningSumBedrag
  from    tabBoekingsgang
          inner join tabJournaalPost          on (JpBoekgangGid = BoekgangGid and JpBjGid = @BjGid and JpDgbGid=@DgbGid)
          inner join tabDagboek               on (DgbGid = @DgbGid)
          inner join tabJournaalRegel         on (JrJpGid = JpGid and JrBjGid = @BjGid)
          inner join tabRekeningschema MutRks on (JrRksGid = MutRks.RksGid)
          inner join tabRekeningSchema DgbRks on (DgbRks.RksGid = DgbTegenRksGid)
          left outer join tabHulpRekening on (HulpRekJrGid = JrGid)
//          inner join tabvaluta on (ValNummer = if @MutatiesAfdrukkenIn = 0 then //in valuta van mutatie
//                                                 JrValNummer
//                                               else
//                                                @ValNummerAfdruk
//                                               endif)
  where ((@SoortBoeking = 0 and IsBoekGangDefinitief =  1) or
         (@SoortBoeking = 1 and IsBoekGangDefinitief =  0) or
         (@SoortBoeking = 2)) and
        ((@IsPerPeriode <> 0 and JrPernr        between @VanPernrOfStuknr and @TotPernrOfStuknr) or
         (@IsPerPeriode = 0  and BoekstukNummer between @VanPernrOfStuknr and @TotPernrOfStuknr))

//  order by right('                   '+StukVolgNummer,13), RegelNummer; oude situatie, voor bug 22104
    order by
      // Subtotaal per stuknummer, dan altijd eerst alleen op boekstuknummer(niet op stukvolgnummer) sorteren(binnen boekstuk weer sorteren op 1 van de 4 keuzen)
      if @Ascending = 0 and @SubtotaalPerStukNr <> 0 then BoekstukNummer endif desc,
      if @Ascending = 1 and @SubtotaalPerStukNr <> 0 then BoekstukNummer endif,
      if @Ascending = 0 and @OrderBy = 0 then JrReferentie_Lengte endif desc,
      if @Ascending = 0 and @OrderBy = 0 then JrReferentie endif desc,
      if @Ascending = 1 and @OrderBy = 0 then JrReferentie_Lengte endif,
      if @Ascending = 1 and @OrderBy = 0 then JrReferentie endif,
      if @Ascending = 0 and @OrderBy = 1 then JrBoekdatum endif desc,
      if @Ascending = 1 and @OrderBy = 1 then JrBoekdatum endif,
      if @Ascending = 0 and @OrderBy = 2 then Regelnummer endif desc,
      if @Ascending = 1 and @OrderBy = 2 then Regelnummer endif,
      if @Ascending = 0 and @OrderBy = 3 then right('                   '+StukVolgNummer,13) endif desc,
      if @Ascending = 1 and @OrderBy = 3 then right('                   '+StukVolgNummer,13) endif,
      // Secundaire sortering
      //default eerst definitief dan voorlopig, dus waarde 1 dan 0, dus vandaar desc terwijl @ascending=1(default waarde)
      if @Ascending = 0 then IsBoekgangDefinitief endif,
      if @Ascending = 1 then IsBoekgangDefinitief endif desc,
      //Als bijv. bij beginbalans alles op 1 datum valt, dan nasorteren op combinatie boekstuknummer/stukvolgnummer
      if @Ascending = 0 then right('                   '+StukVolgNummer,13) endif desc,
      if @Ascending = 1 then right('                   '+StukVolgNummer,13) endif,
      // Altijd nasorteren op basis van het 'regelnummer', zo was het vroeger ook
      if @Ascending = 0 then RegelNummer endif desc,
      if @Ascending = 1 then RegelNummer endif,
      //MR 28-jan-2010 bug #31864: als laatste het gidje sorteren
      if @Ascending = 0 then jrGid endif desc,
      if @Ascending = 1 then jrGid endif;


  create index idx_MutatiesMutGid on Mutaties (MutGid);

  //---------- Running sum bepalen ----------

  //Als het geen beginbalans-dagboek is, dan de eerste periode minimaal 1.
  if @SoortDagboek = 5 and @VanPerNrOfStukNr = 0 then
    set @VanPerNrOfStukNr = 1;
  end if;

  //Eerst het beginsaldo ophalen (in de dagboekvaluta)
  if @IsPerPeriode = 1 then
    //Per periode
    if @SoortDagboek = 5 then
      //Begin-dagboek, dus saldo is 0
      set @Totaal = 0;
    else
      //Geen begin-dagboek, dus saldo van voorgaande periodes bepalen (als periode=0, dan ook periode 0 meenemen, anders vanaf periode 1!)
      set @tmpPeriode = if @VanPerNrOfStukNr > 0 then @VanPerNrOfStukNr else 1 endif;
      select isnull(sum(case @SoortBoeking
                 when 0 then //Definitief
                   if RekSaldoValNummer = @ValNummerTotaal then
                     SaldoDebetValutaDefinitief - SaldoCreditValutaDefinitief
                   else
                     (SaldoDebetBasisDefinitief - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, RekSaldoPerNr, @ValNummerTotaal)//@KoersTovBasisVanTotaal
                   endif
                 when 1 then //Voorlopig
                   if RekSaldoValNummer = @ValNummerTotaal then
                     SaldoDebetValutaVoorlopig - SaldoCreditValutaVoorlopig
                   else
                     (SaldoDebetBasisVoorlopig - SaldoCreditBasisVoorlopig) / KoersTovBasisValuta(@BjGid, RekSaldoPerNr, @ValNummerTotaal)//@KoersTovBasisVanTotaal
                   endif
                 when 2 then //Beide
                   if RekSaldoValNummer = @ValNummerTotaal then
                     SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief - SaldoCreditValutaVoorlopig - SaldoCreditValutaDefinitief
                   else
                     (SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief - SaldoCreditBasisVoorlopig - SaldoCreditBasisDefinitief) / KoersTovBasisValuta(@BjGid, RekSaldoPerNr, @ValNummerTotaal)//@KoersTovBasisVanTotaal
                   endif
                 end),0)
      into   @Totaal
      from   tabRekeningsaldo
      where  RekSaldoRksGid = @DgbRksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr <  @tmpPeriode;
    end if;
  else
    //Per stuknummer
    select sum(if IsCreditBoeking = 1 then -1 else 1 endif *
               if JrValNummer = @ValNummerTotaal then
                 jrValutaBedrag
               else
                 cast(jrBasisBedrag / KoersTovBasisValuta(JrBjGid, JrPerNr, @ValNummerTotaal)/*@KoersTovBasisVanTotaal*/ as numeric(15,2))
               endif)
    into   @Totaal
    from  tabjournaalregel saldoJournaalRegel inner join tabjournaalpost saldoJournaalpost on (saldoJournaalpost.JpGid = saldoJournaalRegel.JrJpGid) inner join tabdagboek saldoDagboek on (saldoDagboek.DgbGid = saldoJournaalpost.JpDgbGid) inner join tabBoekingsgang on (BoekgangGid = saldoJournaalpost.JpBoekgangGid)
    where JrRksGid = @DgbRksGid and jpbjgid = @BjGid
          and (boekstuknummer      < @VanPernrOfStuknr or saldoDagboek.dagboeksoort = 5)  //Alleen lagere stuknummers + beginbalans
          and (saldoDagboek.DgbGid = @DgbGid           or saldoDagboek.dagboeksoort = 5)  //Alleen dit dagboek + beginbalans
          and ((@SoortBoeking = 0 and IsBoekGangDefinitief =  1) or                       //Vve 10-10-2003, 7560: Ook ff opletten welke gegevens we aan het afdrukken zijn!!!
               (@SoortBoeking = 1 and IsBoekGangDefinitief =  0) or
               (@SoortBoeking = 2))
  end if;

  // Totaal voorgaande periodes aan de 1e regel toevoegen
  if isnull(@Totaal,0) <> 0 then
    update Mutaties
    set    RunningSumBedrag = @Totaal + RunningSumBedrag
    where  MutGid = (select min(B.MutGid) from Mutaties B where b.RunningSumBedrag is not null);
  end if;

  //call TraceEind('rapDagboekMutaties');

  select
          RegelNummer,
          JrBoekDatum,
          BoekstukNummer,
          OmsJournaalPost,
          right('000'+string(StukVolgnr),3) VolgNummer,
          StukVolgNummer,
          JrRksInvoer,
          MutRks.RksZoekCode,
          MutRks.RksNaam,
          JrReferentie,
          OmsJournaalRegel,
          ValNummer ValNummerMutatie,
          ValCode   ValCodeMutatie,
          ValNummer ValNummerAfdruk,
          ValCode   ValCodeAfdruk,
/*
          if @MutatiesAfdrukkenIn = 0 then //Val van Mutatie
            ValNummer
          else //Val. van dagboek of Andere valuta
            @ValNummerAfdruk
          endif ValNummerAfdruk,
          if @MutatiesAfdrukkenIn = 0 then //Val van Mutatie
            ValCode
          else //Val. van dagboek of Andere valuta
            @ValCodeAfdruk
          endif ValCodeAfdruk,
*/
          if @SubtotaalPerStukNr = 1 then BoekstukNummer endif StukNummerGroep,
          DebetinBasisVal, CreditinBasisVal, DebetinMutatieVal, CreditinMutatieVal,
          DebetinTegenVal, creditInTegenVal, DebetinAndereVal, creditInAndereVal,
          DebetInAfdruk, CreditInAfdruk,
          HulpRks.RksInvoer HulpRekRksNummer,
          HulpRks.RksNaam HulpRekRksNaam,
          HulpRks.RksZoekCode HulpRekRksZoekCode,
          HulpRekIsCredit,
          HulpRekBedrag HulpRekBedragInTotaal, HulpRekInBasisVal, HulpRekValNummer, HulpRekValutaBedrag, RunningSumBedrag, Aantal,
          Boekdatum
  from    Mutaties
          inner join tabJournaalRegel on (Mutaties.JrGid = tabJournaalRegel.JrGid)
          inner join tabJournaalPost  on (JpGid = JrJpGid)
          inner join tabRekeningschema MutRks on (JrRksGid = MutRks.RksGid)
          inner join tabvaluta on (ValNummer = if @MutatiesAfdrukkenIn = 0 then //in valuta van mutatie
                                                 JrValNummer
                                               else
                                                 @ValNummerAfdruk
                                               endif)
          left outer join tabRekeningSchema HulpRks on (HulpRks.RksGid = HulpRekRksGid)
  order by MutGid; //right('                   '+StukVolgNummer,13), RegelNummer;


end;

//call rapDagboekMutatiesMutaties(2, 1, 0, 0, 12, 2, 1, 0, null, 0, null)


create or replace procedure rapDagboekMutatiesParagraaf(
in @BjGid                  integer,
in @DgbGid                 integer,
in @IsPerPeriode           smallint,       //0=mutaties per periode, 1=mutaties per stuknummer
in @VanPernrOfStuknr       numeric(10,0),  //Periodenr of stuknummer
in @TotPernrOfStuknr       numeric(10,0),
in @SoortBoeking           smallint,       //0=definitief, 1=voorlopig, 2=beide
in @TotalenInValuta        smallint,       //0|Valuta van tegenrekening|1|Valuta van tegenrekening + basisvaluta|2|Valuta van tegenrekening + basisvaluta + andere valuta|3|Geen totalen
in @ValutaNummer           integer)        //indien @TotalenInValuta = 2, dan hier valutanummer invullen

result(RubParSub        nchar(2),       OmsBalansCodeDetails nchar(40),
       DebetinTegenVal  numeric(15,2), creditinTegenVal     numeric(15,2),
       DebetinBasisVal  numeric(15,2), CreditinBasisVal     numeric(15,2),
       DebetinAndereVal numeric(15,2), creditinAndereVal    numeric(15,2))

begin
  declare @PerNrVoorKoers     integer;
  declare @KoersVanValNummer  double;
  declare @KoersVanDagboekVal double;
  declare @DgbRksValNummer    integer;

  declare local temporary table tmpMut(
    tmpSoort integer,  //0= regels, 10=verschil
    tmpParCode nchar(2),
    tmpParNaam nchar(40),
    tmpDebetinTegenVal  numeric(15,2), tmpCreditinTegenVal     numeric(15,2),
    tmpDebetinBasisVal  numeric(15,2), tmpCreditinBasisVal     numeric(15,2),
    tmpDebetinAndereVal numeric(15,2), tmpCreditinAndereVal    numeric(15,2)
  ) on commit preserve rows;

  //tbv. totalen
  declare @tmpDebetinTegenVal   numeric(15,2);
  declare @tmpCreditinTegenVal  numeric(15,2);
  declare @tmpDebetinBasisVal   numeric(15,2);
  declare @tmpCreditinBasisVal  numeric(15,2);
  declare @tmpDebetinAndereVal  numeric(15,2);
  declare @tmpCreditinAndereVal numeric(15,2);

  //call traceBegin('rapDagboekMutatiesParagraaf(@BjGid='+string(@BjGid)+', @DgbGid='+string(@DgbGid)+', @IsPerPeriode='+string(@IsPerPeriode)+', @VanPernrOfStuknr='+string(@VanPernrOfStuknr)+', @TotPernrOfStuknr='+string(@TotPernrOfStuknr)+', @SoortBoeking='+string(@SoortBoeking)+', @TotalenInValuta='+string(@TotalenInValuta)+', @ValutaNummer='+string(@ValutaNummer)+')');

  if @IsPerPeriode = 1 then
    set @PerNrVoorKoers = @IsPerPeriode;
  else
    select max(PerNr) into @PerNrVoorKoers from tabperiode where PerBjGid = @BjGid;
  end if;

  //Opvragen van de tegenrekening
  select RksValNummer into @DgbRksValNummer from tabDagboek inner join tabRekeningschema on (RksGid = DgbTegenRksGid) where DgbGid = @DgbGid;

  // Vaste koersen bepalen
  set @KoersVanValNummer  = KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @ValutaNummer);
  set @KoersVanDagboekVal = KoersTovBasisValuta(@BjGid, @PerNrVoorKoers, @DgbRksValNummer);

  insert into tmpMut(tmpSoort, tmpParCode, tmpParNaam, tmpDebetinTegenVal, tmpCreditinTegenVal, tmpDebetinBasisVal, tmpCreditinBasisVal, tmpDebetinAndereVal, tmpCreditinAndereVal)
  select 1,
         if RubParSub is null then left(MutRks.RksInvoer, 2) else RubParSub endif ParCode,
         if RubParSub is null then _U('Paragraaf ''%1''', left(MutRks.RksInvoer,2)+(if length(MutRks.RksInvoer)=1 then ' ' endif)) else OmsBalansCodeDetails endif ParNaam,
         //Debetbedrag  in valuta van tegenrekening
         sum(if IsCreditBoeking  = 0 then
               if @DgbRksValNummer  = JrValNummer then
                 jrValutaBedrag
               else
                 cast(jrBasisBedrag / @KoersVanDagboekVal as numeric(15,2))
               endif
             endif) DebetinTegenVal,
         //Creditbedrag in valuta van tegenrekening
         sum(if IsCreditBoeking <> 0 then
               if @DgbRksValNummer = JrValNummer then
                 jrValutaBedrag
               else
                 cast(jrBasisBedrag / @KoersVanDagboekVal as numeric(15,2))
               endif
             endif) creditinTegenVal,
         //Debetbedrag  in basisvaluta
         sum(if IsCreditBoeking  = 0 then jrBasisBedrag endif) DebetinBasisVal,
         //Creditbedrag in basisvaluta
         sum(if IsCreditBoeking <> 0 then jrBasisBedrag endif) CreditinBasisVal,
         //Debetbedrag  in andere valuta
         sum(if IsCreditBoeking  = 0 then
               if @ValutaNummer = JrValNummer then
                 jrValutaBedrag
               else
                 cast(jrBasisBedrag / @KoersVanValNummer as numeric(15,2))
               endif
             endif) DebetinAndereVal,
         //Creditbedrag in andere valuta
         sum(if IsCreditBoeking <> 0 then
               if @ValutaNummer = JrValNummer then
                 jrValutaBedrag
               else
                 cast(jrBasisBedrag / @KoersVanValNummer as numeric(15,2))
               endif
             endif) creditinAndereVal

  from    tabBoekingsgang
          inner join tabJournaalPost          on (JpBoekgangGid = BoekgangGid)
          inner join tabJournaalRegel         on (JrJpGid = JpGid)
          inner join tabRekeningschema MutRks on (JrRksGid = MutRks.RksGid)
          inner join tabvaluta on (ValNummer = if @TotalenInValuta in (0,1) then //in valuta van mutatie, evt. incl. basisvaluta
                                                 JrValNummer
                                               else
                                                @ValutaNummer
                                               endif)
          left outer join tabBalanscodeDetail on (MutRks.RksInvoer like paragraaf+'%' and DetailBlCode = 0 and isnull(Subparagraaf,'')='' and isnull(paragraaf,'')<>'')
  where ((@SoortBoeking = 0 and IsBoekGangDefinitief =  1) or
         (@SoortBoeking = 1 and IsBoekGangDefinitief =  0) or
         (@SoortBoeking = 2)) and
        ((@IsPerPeriode <> 0 and JrPernr        between @VanPernrOfStuknr and @TotPernrOfStuknr) or
         (@IsPerPeriode = 0  and BoekstukNummer between @VanPernrOfStuknr and @TotPernrOfStuknr)) and
          JpBjGid = @BjGid and JrBjGid = @BjGid and
          JpDgbGid = @DgbGid
  group by ParCode, ParNaam, BlGid;

  //Subtotaal bepalen en eventueel afrondingen onthouden

  select sum(tmpDebetinTegenVal), sum(tmpCreditinTegenVal), sum(tmpDebetinBasisVal), sum(tmpCreditinBasisVal), sum(tmpDebetinAndereVal), sum(tmpCreditinAndereVal)
  into @tmpDebetinTegenVal, @tmpCreditinTegenVal, @tmpDebetinBasisVal, @tmpCreditinBasisVal, @tmpDebetinAndereVal, @tmpCreditinAndereVal
  from tmpMut;

/*
  insert into tmpMut(tmpSoort, tmpParCode, tmpParNaam, tmpDebetinTegenVal, tmpCreditinTegenVal, tmpDebetinBasisVal, tmpCreditinBasisVal, tmpDebetinAndereVal, tmpCreditinAndereVal)
  values(5, '', 'Totaal',
  @tmpDebetinTegenVal, @tmpCreditinTegenVal, @tmpDebetinBasisVal, @tmpCreditinBasisVal, @tmpDebetinAndereVal, @tmpCreditinAndereVal);
*/

  if @tmpDebetinTegenVal <> @tmpCreditinTegenVal or @tmpDebetinBasisVal <> @tmpCreditinBasisVal or @tmpDebetinAndereVal <> @tmpCreditinAndereVal then
    insert into tmpMut(tmpSoort, tmpParCode, tmpParNaam, tmpDebetinTegenVal, tmpDebetinBasisVal, tmpDebetinAndereVal)
    values(10, '', _U('Valutaomrekenverschillen'),
           if @tmpCreditinTegenVal  - @tmpDebetinTegenVal  <> 0 then @tmpCreditinTegenVal - @tmpDebetinTegenVal endif,
           if @tmpCreditinBasisVal  - @tmpDebetinBasisVal  <> 0 then @tmpCreditinBasisVal - @tmpDebetinBasisVal endif,
           if @tmpCreditinAndereVal - @tmpDebetinAndereVal <> 0 then @tmpCreditinAndereVal - @tmpDebetinAndereVal endif);
  end if;

  //call traceEind('rapDagboekMutatiesParagraaf');

  //Resultaat teruggeven
  select
    tmpParCode,
    tmpParNaam,
    tmpDebetinTegenVal,  tmpCreditinTegenVal,
    tmpDebetinBasisVal,  tmpCreditinBasisVal,
    tmpDebetinAndereVal, tmpCreditinAndereVal
  from
    tmpMut
  order by tmpSoort, tmpParCode;


end;

//call rapDagboekMutatiesParagraaf( 2, 1, 0, 0, 12, 2, 0, null)


create or replace procedure rapGespreksNotitiesLijntjes(
 in @VanDatum        date,      // Controleer alleen notities binnen deze datumrange
 in @TotDatum        date,
 in @Medewerker      nchar(10),  // Optioneel; indien NULL, dan alle medewerkers
 in @FonId           nchar(3),   // Welke Naw bestand, indien leeg, dan debiteuren
 in @FnCode          integer,   // Alleen de gespreksnotities van deze functie (afdeling)
 in @ContactSoort    nchar(100),    //Geselecteerde contactsoorten, is deze leeg dan alle contactsoorten
 in @SecKolom1       integer,   // t.b.v. verdeling wachttijd en netto gesprekstijd
 in @SecKolom2       integer,
 in @SecKolom3       integer,
 in @SecKolom4       integer,
 in @SoortBeltZelf   smallint,
 in @SoortKlantBelt  smallint,
 in @IsTotaal        smallint   // 0 = Geen totaal, 1 = totaal per periode, 2 = totaal generaal
)
result(
 NaamGebruiker    nchar(10),
 InvoerDatum      Date,
 AantalLijntjes   integer,
 // Verdeling naar pakket/versie
 AantalLijntjesK5             integer,
 AantalLijntjesK4             integer,
 AantalLijntjesK3             integer,
 AantalLijntjesQ5             integer,
 AantalLijntjesQ4             integer,
 // AantalLijntjesQ3             integer,
 AantalLijntjesIn1Release        integer,
 AantalLijntjesInMeerPakketReleases integer,
 MaxWachttijd                 Time,
 GemWachttijd                 Time,
 TotWachttijdSec              numeric(15,0),
 MaxNettoLijnduur             Time,
 GemNettoLijnduur             Time,
 TotNettoLijnduurSec          numeric(15,0),
 // Verdeling naar wachttijd
 WachttijdAantalKolom1        Integer,
 WachttijdAantalKolom2        Integer,
 WachttijdAantalKolom3        Integer,
 WachttijdAantalKolom4        Integer,
 WachttijdAantalKolom5        Integer,
 // Verdeling naar netto gespreksduur
 NettotijdAantalKolom1        Integer,
 NettotijdAantalKolom2        Integer,
 NettotijdAantalKolom3        Integer,
 NettotijdAantalKolom4        Integer,
 NettotijdAantalKolom5        Integer
)
begin
/* Aan te roepen per dag per medewerker, maar ook als totaal van een dag (@Medewerker leeg laten) en ook als eindtotaal (niet gesplitst per dag) door @Totaal op te geven */
  set @@ErrorTextProcedure = 'rapGespreksNotitiesLijntjes(@VanDatum=' + string(@VanDatum)+', @TotDatum='+string(@TotDatum)+', @Medewerker='+@Medewerker+
                             ', @FnCode='+string(@FnCode)+', @ContactSoort='+string(@ContactSoort)+ ', @SecKolom1='+string(@SecKolom1)+', @SecKolom2='+string(@SecKolom2)+', @SecKolom3='+string(@SecKolom3)+
                             ', @SecKolom4='+string(@SecKolom4)+', @SoortBeltZelf='+string(@SoortBeltZelf)+', @SoortKlantBelt='+string(@SoortKlantBelt)+', @IsTotaal='+string(@IsTotaal)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  if IsNull(@FonId, '') = '' then
    set @FonId = 'D';
  end if;

  if not exists (select first tmpDateTime from tmpGespreksnotities) then
    call rapGespreksNotitiesLijntjesVoorbereiding();
  else
    if (select first tmpDateTime from tmpGespreksnotities) < now() - 0.02 then //Indien data ouder dan half uur is, dan opnieuw vullen
      call rapGespreksNotitiesLijntjesVoorbereiding();
    end if;
  end if;

  //call TraceEind(@@ErrorTextProcedure);

  select
    if @Medewerker is not null or @IsTotaal <> 0 then @Medewerker else GnotGebruiker endif NaamGebruiker, // Als totaal per datum of totaal generaal, dan GEEN gebruiker teruggeven
    if @IsTotaal <> 2 then GnotInvoerDatum endif InvoerDatum,                                             // Als totaal generaal, dan GEEN datum teruggeven
    count(distinct GnotGid) AantalLijntjes,
    // Verdeling naar pakket/versie
    isnull(sum(if tmpAantalPakketReleases = 1 and VanPakketRelease = 15 then 1 endif), 0) AantalLijntjesK5,
    isnull(sum(if tmpAantalPakketReleases = 1 and VanPakketRelease = 14 then 1 endif), 0) AantalLijntjesK4,
    isnull(sum(if tmpAantalPakketReleases = 1 and VanPakketRelease = 13 then 1 endif), 0) AantalLijntjesK3,
    isnull(sum(if tmpAantalPakketReleases = 1 and VanPakketRelease = 25 then 1 endif), 0) AantalLijntjesQ5,
    isnull(sum(if tmpAantalPakketReleases = 1 and VanPakketRelease = 24 then 1 endif), 0) AantalLijntjesQ4,
    AantalLijntjes - AantalLijntjesInMeerPakketReleases  AantalLijntjesIn1Release,
    AantalLijntjes - AantalLijntjesK5 - AantalLijntjesK4 - AantalLijntjesK3 - AantalLijntjesQ5 - AantalLijntjesQ4 AantalLijntjesInMeerPakketReleases,
    //isnull(sum(if tmpAantalPakketReleases > 1 then 1 endif), 0) AantalLijntjesInMeerPakketReleases,
    max(GnotWachttijd) MaxWachttijd,
    convert(time, DateAdd(second, avg(GnotWachttijdInSec), '00:00'), 14) GemWachttijd,
    sum(GnotWachttijdInSec) TotWachttijdInSec,
    convert(time, DateAdd(second, max(GnotNettoLijntijdInSec), '00:00'), 14) MaxNettoLijnduur,
    convert(time, DateAdd(second, avg(GnotNettoLijntijdInSec), '00:00'), 14) GemNettoLijnduur,
    sum(GnotNettoLijntijdInSec) TotNettoLijnduurSec,
    // Verdeling naar wachttijd
    sum( if GnotWachttijdInSec <= @SecKolom1                       then 1 else 0 endif) WachttijdAantalKolom1,
    sum( if GnotWachttijdInSec between @SecKolom1+1 and @SecKolom2 then 1 else 0 endif) WachttijdAantalKolom2,
    sum( if GnotWachttijdInSec between @SecKolom2+1 and @SecKolom3 then 1 else 0 endif) WachttijdAantalKolom3,
    sum( if GnotWachttijdInSec between @SecKolom3+1 and @SecKolom4 then 1 else 0 endif) WachttijdAantalKolom4,
    sum( if GnotWachttijdInSec > @SecKolom4                        then 1 else 0 endif) WachttijdAantalKolom5,
    // Verdeling naar netto lijntijd
    sum( if GnotNettoLijntijdInSec <= @SecKolom1                       then 1 else 0 endif) NettotijdAantalKolom1,
    sum( if GnotNettoLijntijdInSec between @SecKolom1+1 and @SecKolom2 then 1 else 0 endif) NettotijdAantalKolom2,
    sum( if GnotNettoLijntijdInSec between @SecKolom2+1 and @SecKolom3 then 1 else 0 endif) NettotijdAantalKolom3,
    sum( if GnotNettoLijntijdInSec between @SecKolom3+1 and @SecKolom4 then 1 else 0 endif) NettotijdAantalKolom4,
    sum( if GnotNettoLijntijdInSec > @SecKolom4                        then 1 else 0 endif) NettotijdAantalKolom5
  from
   tabGespreksnotitie inner join tabNawFile on (NawFilFonId = @FonId and NawFilGid = GnotNawFilGid)
   left outer join tmpGespreksnotities on (tmpPakketVersieGnotGid = GnotGid)
   left outer join tabContactSoort on CosGid = GnotCosGid
  where
    // Moet van de aangegeven functie (afdeling) zijn
    (exists(select 1
            from tabGebruiker
            inner join tabRelatieFunctie on (FnRelGID = GebrRelGID)
            where (NaamGebruiker = GnotGebruiker) and
                  (RelFnCode = @FnCode)
    ))
    // Als medewerker ingevuld, dan alleen zijn notities, anders alle notities
    and ((@Medewerker is null) or (GnotGebruiker = @Medewerker))
    and (GnotInvoerDatum between @VanDatum and @TotDatum)
    and ((@ContactSoort= '') or
    (
    (CharIndex(0, @ContactSoort)<>0  and CosCode = 'SupTelIn'  ) or
    (CharIndex(1, @ContactSoort)<>0  and CosCode = 'SupTelUit' ) or
    (CharIndex(2, @ContactSoort)<>0  and CosCode = 'TelIn'     ) or
    (CharIndex(3, @ContactSoort)<>0  and CosCode = 'TelUit'    ) or
    (CharIndex(4, @ContactSoort)<>0  and CosCode = 'Notitie'   )
    ))
  group by
    InvoerDatum, NaamGebruiker
  order by
    InvoerDatum, NaamGebruiker;

end;
//call rapGespreksNotitiesLijntjes('2013-01-01', '2013-12-31', null, null, 130, 'SupTelUit', 120, 300, 600, 900, 1, 1, 0);

create or replace procedure rapGespreksNotitiesLijntjesVoorbereiding()
begin
  declare @SelK5Van nchar(3);
  declare @SelK5Tot nchar(3);
  declare @SelK4Van nchar(3);
  declare @SelK4Tot nchar(3);
  declare @SelK3Van nchar(3);
  declare @SelK3Tot nchar(3);
  declare @PakketGidKing  integer;
  declare @PakketGidQueen integer;
  declare @DatumTijd DateTime;

  set @@ErrorTextProcedure = 'rapGespreksNotitiesLijntjesVoorbereiding';
  //call TraceBegin(@@ErrorTextProcedure);

  set @SelK5Van = '001'; set @SelK5Tot = '199'; // Selectiecodes K5: van 001 t/m 199
  set @SelK4Van = '201'; set @SelK4Tot = '299'; // Selectiecodes K4: van 201 t/m 299
  set @SelK3Van = '301'; set @SelK3Tot = '399'; // Selectiecodes K3: van 301 t/m 399
  select PktsGid into @PakketGidKing  from tabPakketSoort where PktsCode = 'King';
  select PktsGid into @PakketGidQueen from tabPakketSoort where PktsCode = 'Queen';

  set @DatumTijd = now();
  delete tmpGespreksnotities;

  insert into tmpGespreksnotities(tmpPakketVersieGnotGid, tmpAantalPakketReleases, VanPakketRelease, tmpDateTime)
  select
    tmpGespreksnotitie.GnotGid tmpPakketVersieGnotGid,
    isnull(count(distinct                                                     // Bepaal aantal unieke pakketReleases
           case LicPktsGid
             when @PakketGidKing  then 10                                     // King
             when @PakketGidQueen then 20                                     // Queen
             else                      00                                     // Overige
           end +
           case
             when isnull(SlcCode, '') between @SelK5Van and @SelK5Tot then 5  // Versie 5
             when isnull(SlcCode, '') between @SelK4Van and @SelK4Tot then 4  // Versie 4
             when isnull(SlcCode, '') between @SelK3Van and @SelK3Tot then 3  // Versie 3
             else                                                          0  // Onbekend
           end)
    , 0) tmpAantalPakketReleases,
    if tmpAantalPakketReleases > 1 then 6 else                                // 6 = In MEER dan 1 van de bekende ranges OF valt OOK buiten de range
      max(
          case LicPktsGid
            when @PakketGidKing  then 10                                      // 10 = King
            when @PakketGidQueen then 20                                      // 20 = Queen
            else                      00                                      // 00 = Overige
          end +
          case
            when SlcCode between @SelK5Van and @SelK5Tot then 5               // 5 = Versie 5
            when SlcCode between @SelK4Van and @SelK4Tot then 4               // 4 = Versie 4
            when SlcCode between @SelK3Van and @SelK3Tot then 3               // 3 = Versie 3
            else                                              0               // 0 = Onbekend
          end
         )
    endif VanPakketRelease, @DatumTijd
  from tabGespreksnotitie tmpGespreksnotitie
  inner join (tabSlcPerGespreksnotitie inner join tabSelectiecodes on (SlcGid = SpgSlcGid)) on (SpgGnotGid = tmpGespreksnotitie.GnotGid)  // Selectiecodes erbij zoeken t.b.v. versie
  inner join tabLicentie on (LicGid = tmpGespreksnotitie.GnotLicGid)                                                                      // licentie erbij zoeken t.b.v. pakketsoort
  group by GnotGid;

  //call TraceEind(@@ErrorTextProcedure);
end;

alter procedure rapGespreksNotitiesLijntjesVoorbereiding set hidden;


// Denk bij het aanpassen van deze procs eraan dat de procs behorende bij kostenplaatsen-/kostendragermutaties en saldoanalyse grote
// overeenkomsten vertonen met de procs behorende bij grootboekmutaties
create or replace procedure rapGrootboekMutatiesMaster(
in @BjGid             integer,
in @Selectie          smallint,
in @VanRks            nchar(40),
in @TotRks	           nchar(40),
in @VanPerNr          integer,
in @TotPerNr          integer,
in @SoortBoeking      smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @NulSaldiAfdrukken integer,
in @IsVerdicht        nchar(3), // '0,1' = Niet verdichten, '0' = crediteuren verdichten, '1' = debiteuren verdichten, '' = debiteuren en crediteuren verdichten
in @DParagraafNummer  nchar(3),
in @CParagraafNummer  nchar(3),
in @DParagraafNaam    nchar(40),
in @CParagraafNaam    nchar(40),
in @RekeningSoorten   nchar(10),
in @OrderBy           integer,  // Sorteren op: 0 = Nummer, 1 = Zoekcode
in @Ascending         integer)

result (
  Verdichten                         smallint, // Dit veld bevat de rekeningsoort die verdicht dient te worden
  RksGid			     integer,
  RekeningZoekCode                   nchar(10),
  RekeningNummer		     nchar(28),
  RekeningNaam			     nchar(40),
  RekeningValNummer		     integer,
  RekeningValCode	 	     nchar(3))

begin
  // Declareren van hulpvariabelen
  declare @VerdichtDeb integer;
  declare @VerdichtCred integer;

  // Deze tabel bevat de gewenste rekeningen
  declare local temporary table tmpRekeningen(
    tmpVerdichten   integer,
    tmpRksGid       integer,
    tmpRksZoekCode  nchar(10),
    tmpRksInvoer    nchar(28),
    tmpRksNaam      nchar(40),
    tmpRksValNummer    integer,
    tmpRksValCode      nchar(3),
    tmpEindSaldo    numeric(15,2)
  ) on commit preserve rows;

  //call TraceBegin('rapGrootboekMutatiesMaster (@BjGid='+string(@BjGid)+', @Selectie='+string(@Selectie)+', @VanRks='+string(@VanRks)+', @TotRks='+string(@TotRks)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', @NulSaldiAfdrukken='+string(@NulSaldiAfdrukken)+', @IsVerdicht='+string(@IsVerdicht)+', ...');
  //call trace('..., @DParagraafNummer='+string(@DParagraafNummer)+', @CParagraafNummer='+string(@CParagraafNummer)+', @DParagraafNaam='+string(@DParagraafNaam)+', @CParagraafNaam='+string(@CParagraafNaam)+', @RekeningSoorten='+string(@RekeningSoorten)+', @OrderBy='+string(@OrderBy)+', @Ascending='+string(@Ascending)+')');

  // Hulpvariabele gevuld met rekeningsoort indien er op deze rekeningsoort wordt verdicht, anders vullen met -1 (een niet-bestaande rekeningsoort!!)
  set @VerdichtDeb  = if (@IsVerdicht = '' or @IsVerdicht = '1') then 6 else -1 endif;
  set @VerdichtCred = if (@IsVerdicht = '' or @IsVerdicht = '0') then 7 else -1 endif;

    // Tijdelijke tabel vullen
  insert into tmpRekeningen(tmpVerdichten, tmpRksGid, tmpRksZoekCode, tmpRksInvoer, tmpRksNaam, tmpRksValNummer, tmpRksValCode, tmpEindSaldo)
  select
    case DefaultSoort
      when 6 then @VerdichtDeb
      when 7 then @VerdichtCred
      else -1
    end tmpVerdichten,

    if tmpVerdichten in (6,7) then -1 else RksGid endif tmpRksGid,// RksGid = -1 indien de defaultsoort of 6 of 7 is!!!

    case tmpVerdichten
      when 6 then @DParagraafNummer
      when 7 then @CParagraafNummer
      else RksZoekCode
    end tmpRksZoekCode,

    if tmpVerdichten in (6,7) then tmpRksZoekCode else RksInvoer endif tmpRksInvoer,

    case tmpVerdichten
      when 6 then @DParagraafNaam
      when 7 then @CParagraafNaam
      else RksNaam
    end tmpRksNaam,

    if tmpVerdichten in (6,7) then @@BasisValutaNummer else RksValNummer endif tmpRksValNummer,
    if tmpVerdichten in (6,7) then @@BasisValutaCode   else ValCode      endif tmpRksValCode,

    // Bepalen van eindsaldo per grootboekrekening. Dit is nodig voor de instelling in het voorloopscherm (Nulsaldi afdrukken)
    // Indien gekozen voor Nee (0)                                          -> alle grootboekrekeningen waarvan EindSaldo <> null en EindSaldo <> 0 <=> isnull(EindSaldo, 0) <> 0
    // Indien gekozen voor Ja, maar alleen rekeningen waarop geboekt is (1) -> alle grootboekrekeningen waarvan EindSaldo <> null                   <=> EindSaldo is not null
    // Indien gekozen voor Ja, alle rekeningen (2)                          -> alle grootboekrekeningen
    if @NulSaldiAfdrukken <> 2 then
      sum( JrBasisBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) )
    endif tmpEindSaldo

  from tabRekeningSchema
       inner join tabValuta on (ValNummer = RksValNummer)
       left outer join (tabJournaalRegel inner join tabJournaalPost on (JpGid = JrJpGid))
       on (JrRksGid = RksGid and
           JpBjGid = @BjGid  and
           JrBjGid = @BjGid and
           JrPerNr between @VanPerNr and @TotPerNr and
           ( (@SoortBoeking = 0 and RegelNummer is not null) or
             (@SoortBoeking = 1 and RegelNummer is null) or
             (@SoortBoeking = 2)
           )
          )
  where ( (@Selectie = 1 and RksInvoer   between @VanRks and @TotRks) or
          (@Selectie = 2 and RksZoekCode between @VanRks and @TotRks)
        ) and
        @RekeningSoorten like '%'+string(DefaultSoort)+'%'
  group by
    tmpRksGid,
    tmpVerdichten,
    tmpRksZoekCode,
    tmpRksInvoer,
    tmpRksNaam,
    tmpRksValNummer,
    tmpRksValCode
  having
    ( (@NulSaldiAfdrukken = 0 and isnull(tmpEindSaldo, 0) <> 0) or
      (@NulSaldiAfdrukken = 1 and tmpEindSaldo is not null) or
      (@NulSaldiAfdrukken = 2)
    );

  //select * from tmpRekeningen;

  create index idx_tmp on tmpRekeningen (tmpRksGid);

  //call TraceEind('rapGrootboekMutatiesMaster');

  select
    tmpVerdichten,
    tmpRksGid,
    tmpRksZoekCode,
    tmpRksInvoer,
    tmpRksNaam,
    tmpRksValNummer,
    tmpRksValCode
  from
    tmpRekeningen
  order by
    if @Ascending = 0 and @OrderBy = 0 then tmpRksInvoer endif desc, // Sorteren op nummer
    if @Ascending = 1 and @OrderBy = 0 then tmpRksInvoer endif,
    if @Ascending = 0 and @OrderBy = 1 then tmpRksZoekCode endif desc, // Sorteren op zoekcode
    if @Ascending = 1 and @OrderBy = 1 then tmpRksZoekCode endif,
    // Altijd nasorteren op basis van nummer
    if @Ascending = 0 then tmpRksInvoer endif desc,
    if @Ascending = 1 then tmpRksInvoer endif;



end;

// call rapGrootboekMutatiesMaster(1, 1, '000001', '1299999', 0, 12, 2, 0, '', 12, 17, 'Debiteuren', 'Crediteuren', '01234567', 0, 1)


create or replace procedure rapGrootboekMutatiesMutaties(
in @RksGid                          integer,
in @RekeningValNummer               integer,
in @BjGid                           integer,
in @VanPerNr                        integer,
in @TotPerNr                        integer,
in @SoortBoeking                    smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @BedragenAfdrukkenIn             integer,  // 0 = Valuta van grootboekrekening, 1 = boekvaluta, 2 = basisvaluta, 3 = andere valuta
in @BedragenAfdrukkenExtraValNummer integer,  // Indien gevuld, bedragen afdrukken in de extra ingegeven valuta
in @SaldoAfdrukkenIn                integer,  // 0=Default-valuta van tegenrekening van eerste dagboek van boekingsgang, 2=basisvaluta, 3=extra valuta, 4=valuta van referentie
in @SaldoAfdrukkenExtraValNummer    integer,  // Indien gevuld, ook saldo afdrukken in de extra ingegeven valuta.
in @OrderBy                         integer,  // Sorteren op: 0 = referentie, 1 = boekdatum, 2 = journaalregel
in @Ascending                       integer)

result (
  DagboekCode                    nchar(10),
  OmsDagboek                     nchar(40),
  BoekgangNummer                 integer,
  RegelNummer                    integer,
  StukVolgnr                     integer,
  BoekStukVolgNummer             nchar(14),
  JpNummer                       integer,
  Boekdatum                      date,
  OmsJournaalPost                nchar(40),
  JrBoekdatum                    date,
  JpPerNr                        integer,
  BeginBalans                    smallint,
  OmsJournaalRegel               nchar(40),
  JrReferentie                   nchar(40),
  IsCreditBoeking                smallint,
  RglBoekValNummer               integer,
  RglBoekValCode                 nchar(3),
  AfdrukValNummerBedragen        integer,       // Valuta waarin de bedragen dienen te worden afgedrukt
  AfdrukValCodeBedragen          nchar(3),
  JrBoekValBedrag                numeric(15,2),
  BoekValBoekingBedragD          numeric(15,2),
  BoekValBoekingBedragC          numeric(15,2),
  BoekValBoekingSaldo            numeric(15,2),
  BoekValRegelTotaalD            numeric(15,2),
  BoekValRegelTotaalC            numeric(15,2),
  BoekValRegelSaldo              numeric(15,2),
  JrBasisValBedrag               numeric(15,2),
  BasisValBoekingBedragD         numeric(15,2),
  BasisValBoekingBedragC         numeric(15,2),
  BasisValBoekingSaldo           numeric(15,2),
  BasisValRegelTotaalD           numeric(15,2),
  BasisValRegelTotaalC           numeric(15,2),
  BasisValRegelSaldo             numeric(15,2),
  JrFactuurdatum                 date,
  JrVervalDatum                  date,
  JrBetalingsKenmerk             nchar(24),
  HulpRekSoort                   smallint,
  HulpRekeningZoekCode           nchar(10),
  HulpRekeningInvoer             nchar(28),
  HulpRekeningNaam               nchar(40),
  HulpRekBtwCode                 integer,
  HulpRekIsCreditBoeking         smallint,
  HulpRekBoekValNummer           integer,
  HulpRekBoekValCode             nchar(3),
  HulpRekAfdrukValNummerBedragen integer,
  HulpRekAfdrukValCodeBedragen   nchar(3),
  HulpRekBoekValBedrag           numeric(15,2),
  HulpRekBasisValBedrag          numeric(15,2),
  AfdrukValBoekingCumBedragD     numeric(15,2),
  AfdrukValBoekingCumBedragC     numeric(15,2),
  AfdrukValBoekingCumSaldo       numeric(15,2),
  AfdrukValRegelCumSaldo         numeric(15,2),
  Aantal                         numeric(15,2))

begin

  // Voorkomen van afrondingsverschillen en tegelijkertijd de valutacodes ophalen
  declare @NumDeciBasisVal               integer;
  declare @RekeningValCode               nchar(3);
  declare @NumDeciRekeningVal            integer;
  declare @BedragenAfdrukkenExtraValCode nchar(3);
  declare @NumDeciExtraValSaldo          integer;

  declare @KoersTovBasisVanRekVal        float;
  declare @KoersTovBasisVanExtraVal      float;

  //call TraceBegin('rapGrootboekMutatiesMutaties (@RksGid='+string(@RksGid)+', @RekeningValNummer='+string(@RekeningValNummer)+', @BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call Trace('..., @BedragenAfdrukkenIn='+string(@BedragenAfdrukkenIn)+', @BedragenAfdrukkenExtraValNummer='+string(@BedragenAfdrukkenExtraValNummer)+', @SaldoAfdrukkenIn='+string(@SaldoAfdrukkenIn)+', @SaldoAfdrukkenExtraValNummer='+string(@SaldoAfdrukkenExtraValNummer)+', ...');
  //call Trace('..., @OrderBy='+string(@OrderBy)+', @Ascending='+string(@Ascending)+')');

  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;
  select ValCode, if DecimalenBoeking <> 0 then 2 else 0 endif into @RekeningValCode, @NumDeciRekeningVal from tabValuta where ValNummer = @RekeningValNummer;
  if @BedragenAfdrukkenIn = 3 then
    select ValCode into @BedragenAfdrukkenExtraValCode from tabValuta where ValNummer = @BedragenAfdrukkenExtraValNummer;
  end if;
  if @SaldoAfdrukkenIn = 3 then // Alleen gegevens ophalen indien ook daadwerkelijk een extra valuta is ingevoerd
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValSaldo  from tabValuta where ValNummer = @SaldoAfdrukkenExtraValNummer;
  end if;

  // Koersen opvragen
  if @RekeningValNummer = @@BasisValutanummer then
    set @KoersTovBasisVanRekVal   = 1;
  else
    set @KoersTovBasisVanRekVal   = KoersTovBasisValutaDouble(@BjGid, @TotPerNr, @RekeningValNummer);
  end if;

  if @RekeningValNummer <> @SaldoAfdrukkenExtraValNummer then
    if @SaldoAfdrukkenExtraValNummer = @@BasisValutanummer then
      set @KoersTovBasisVanExtraVal = 1
    else
      set @KoersTovBasisVanExtraVal = KoersTovBasisValutaDouble(@BjGid, @TotPerNr, @SaldoAfdrukkenExtraValNummer);
    end if;
  else
    set @KoersTovBasisVanExtraVal = @KoersTovBasisVanRekVal;
  end if;

  //call TraceEind('rapGrootboekMutatiesMutaties');

  select
    JrDgbCode DagboekCode,
    OmsDagboek,
    BoekGangNummer,
    RegelNummer,
    StukVolgnr,
    string(JrBoekstukNummer) + '.' + right('000' + string(StukVolgNr), 3) BoekStukVolgNummer,
    JpNummer,
    Boekdatum,
    OmsJournaalPost,
    JrBoekdatum,
    JrPerNr,
    if jrPerNr = 0 then 1 else 0 endif BeginBalans,
    OmsJournaalRegel,
    JrReferentie,
    IsCreditBoeking,
    JrValNummer RglBoekValNummer,
    JrValCode RglBoekValCode,
    case @BedragenAfdrukkenIn
      when 0 then @RekeningValNummer
      when 1 then RglBoekValNummer
      when 2 then @@BasisValutanummer
      when 3 then @BedragenAfdrukkenExtraValNummer
    end AfdrukValNummerBedragen,
    case @BedragenAfdrukkenIn
      when 0 then @RekeningValCode
      when 1 then RglBoekValCode
      when 2 then @@BasisValutaCode
      when 3 then @BedragenAfdrukkenExtraValCode
    end AfdrukValCodeBedragen,

    round(JrValutaBedrag, if ValRek.DecimalenBoeking <> 0 then 2 else 0 endif) JrBoekValBedrag,
    if IsCreditBoeking = 0 then JrBoekValBedrag endif BoekValBoekingBedragD,
    if IsCreditBoeking = 1 then JrBoekValBedrag endif BoekValBoekingBedragC,
    JrValutaBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) BoekValBoekingSaldo,

    // Uitsplitsing van regeltotaal (=geboekt bedrag + geboekt bedrag op de hulprekening) naar boekzijde
    if HulpRekValNummer is not null then
      if JrValNummer = HulpRekValNummer then
        if HulpRekIsCredit is not null and HulpRekIsCredit = 0 then isnull(BoekValBoekingBedragD, 0) + HulpRekBoekValBedrag else BoekValBoekingBedragD endif
      else
        if HulpRekIsCredit is not null and HulpRekIsCredit = 0 then isnull(BoekValBoekingBedragD, 0) + round((HulpRekBasisValBedrag/ (if JrValNummer <> @@BasisValutaNummer then KoersTovBasisValutaDouble(@BjGid, @TotPernr, JrValNummer) else 1 endif) ), if ValRek.DecimalenBoeking <> 0 then 2 else 0 endif) else BoekValBoekingBedragD endif
      endif
    else
      BoekValBoekingBedragD
    endif BoekValRegelTotaalD,

    if HulpRekValNummer is not null then
      if JrValNummer = HulpRekValNummer then
        if HulpRekIsCredit is not null and HulpRekIsCredit = 1 then isnull(BoekValBoekingBedragC, 0) + HulpRekBoekValBedrag else BoekValBoekingBedragC endif
      else
        if HulpRekIsCredit is not null and HulpRekIsCredit = 1 then isnull(BoekValBoekingBedragC, 0) + round((HulpRekBasisValBedrag/ (if JrValNummer <> @@BasisValutaNummer then KoersTovBasisValutaDouble(@BjGid, @TotPernr, JrValNummer) else 1 endif )), if ValRek.DecimalenBoeking <> 0 then 2 else 0 endif) else BoekValBoekingBedragC endif
      endif
    else
      BoekValBoekingBedragC
    endif BoekValRegelTotaalC,

    isnull(BoekValRegelTotaalD, 0) - isnull(BoekValRegelTotaalC, 0) BoekValRegelSaldo,
    round(JrBasisBedrag, @NumDeciBasisVal)      JrBasisValBedrag,
    if IsCreditBoeking = 0 then JrBasisValBedrag endif BasisValBoekingBedragD,
    if IsCreditBoeking = 1 then JrBasisValBedrag endif BasisValBoekingBedragC,

    JrBasisBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) BasisValBoekingSaldo,

    if HulpRekIsCredit is not null and HulpRekIsCredit = 0 then isnull(BasisValBoekingBedragD, 0) + HulpRekBasisValBedrag else BasisValBoekingBedragD endif BasisValRegelTotaalD,

    if HulpRekIsCredit is not null and HulpRekIsCredit = 1 then isnull(BasisValBoekingBedragC, 0) + HulpRekBasisValBedrag else BasisValBoekingBedragC endif BasisValRegelTotaalC,
    isnull(BasisValRegelTotaalD, 0) - isnull(BasisValRegelTotaalC, 0) BasisValRegelSaldo,

    JrFactuurDatum,
    JrVervalDatum,
    JrBetalingsKenmerk,
    HulpRekSoort,
    RksZoekCode HulpRekeningZoekCode,
    RksInvoer   HulpRekeningInvoer,
    RksNaam     HulpRekeningNaam,
    HulpRekBtwCode,
    HulpRekIsCredit HulpRekIsCreditBoeking,
    HulpRekValNummer HulpRekBoekValNummer,
    ValHulpRek.ValCode HulpRekBoekValCode,
    if HulpRekBoekValNummer is not null then
      case @BedragenAfdrukkenIn
        when 0 then @RekeningValNummer
        when 1 then HulpRekBoekValNummer
        when 2 then @@BasisValutanummer
        when 3 then @BedragenAfdrukkenExtraValNummer
      end
    endif HulpRekAfdrukValNummerBedragen,
    if HulpRekBoekValNummer is not null then
      case @BedragenAfdrukkenIn
        when 0 then @RekeningValCode
        when 1 then HulpRekBoekValCode
        when 2 then @@BasisValutaCode
        when 3 then @BedragenAfdrukkenExtraValCode
      end
    endif HulpRekAfdrukValCodeBedragen,

    round(HulpRekValutaBedrag, if ValHulpRek.DecimalenBoeking <> 0 then 2 else 0 endif ) HulpRekBoekValBedrag,
    round(HulpRekBasisBedrag, @NumDeciBasisVal) HulpRekBasisValBedrag,

    // Cumulatief
    if (not((@SaldoAfdrukkenIn <> 3 and @SaldoAfdrukkenIn = @BedragenAfdrukkenIn) or (@SaldoAfdrukkenIn = 3 and isnull(@SaldoAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) or (@SaldoAfdrukkenIn = 4)) then
      case @SaldoAfdrukkenIn
        when 0 then if JrValNummer = @RekeningValNummer then BoekValBoekingBedragD else round(BasisValBoekingBedragD/@KoersTovBasisVanRekVal, @NumDeciRekeningVal) endif
        when 2 then BasisValBoekingBedragD
        when 3 then if JrValNummer = @SaldoAfdrukkenExtraValNummer then BoekValBoekingBedragD else round(BasisValBoekingBedragD/@KoersTovBasisVanExtraVal, @NumDeciExtraValSaldo) endif
      end
    endif AfdrukValBoekingCumBedragD,

    if (not((@SaldoAfdrukkenIn <> 3 and @SaldoAfdrukkenIn = @BedragenAfdrukkenIn) or (@SaldoAfdrukkenIn = 3 and isnull(@SaldoAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) or (@SaldoAfdrukkenIn = 4)) then
      case @SaldoAfdrukkenIn
        when 0 then if JrValNummer = @RekeningValNummer then BoekValBoekingBedragC else round(BasisValBoekingBedragC/@KoersTovBasisVanRekVal, @NumDeciRekeningVal) endif
        when 2 then BasisValBoekingBedragC
        when 3 then if JrValNummer = @SaldoAfdrukkenExtraValNummer then BoekValBoekingBedragC else round(BasisValBoekingBedragC/@KoersTovBasisVanExtraVal, @NumDeciExtraValSaldo) endif
      end
    endif AfdrukValBoekingCumBedragC,

    if (not((@SaldoAfdrukkenIn <> 3 and @SaldoAfdrukkenIn = @BedragenAfdrukkenIn) or (@SaldoAfdrukkenIn = 3 and isnull(@SaldoAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) or (@SaldoAfdrukkenIn = 4)) then
      isnull(AfdrukValBoekingCumBedragD, 0) - isnull(AfdrukValBoekingCumBedragC, 0)
    endif AfdrukValBoekingCumSaldo,


    if (not((@SaldoAfdrukkenIn <> 3 and @SaldoAfdrukkenIn = @BedragenAfdrukkenIn) or (@SaldoAfdrukkenIn = 3 and isnull(@SaldoAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) or (@SaldoAfdrukkenIn = 4)) then
      case @SaldoAfdrukkenIn
        when 0 then
          if HulpRekValNummer is not null then
            if HulpRekValNummer = @RekeningValNummer then
              AfdrukValBoekingCumSaldo + HulpRekBoekValBedrag * (if HulpRekIsCredit = 1 then -1 else 1 endif)
            else
              AfdrukValBoekingCumSaldo + round((HulpRekBasisValBedrag/@KoersTovBasisVanRekVal), @NumDeciRekeningVal) * (if HulpRekIsCredit = 1 then -1 else 1 endif)
            endif
          else
            AfdrukValBoekingCumSaldo
          endif
        when 2 then BasisValRegelSaldo
        when 3 then
          if HulpRekValNummer is not null then
            if HulpRekValNummer = @SaldoAfdrukkenExtraValNummer then
              AfdrukValBoekingCumSaldo + HulpRekBoekValBedrag * (if HulpRekIsCredit = 1 then -1 else 1 endif)
            else
              AfdrukValBoekingCumSaldo + round((HulpRekBasisValBedrag/@KoersTovBasisVanExtraVal), @NumDeciExtraValSaldo) * (if HulpRekIsCredit = 1 then -1 else 1 endif)
            endif
          else
            AfdrukValBoekingCumSaldo
          endif
      end
    endif AfdrukValRegelCumSaldo,

    // Indien het geboekt aantal-veld een 0 bevat er van uit gaan dat er NIET geboekt is
    if Aantal <> 0 then Aantal endif
  from
    tabJournaalregel
    inner join tabJournaalPost on (JpGid = JrJpGid)
    inner join tabBoekingsgang on (BoekgangGid = JpBoekgangGid)
    inner join tabDagboek on (JpDgbGid = DgbGid)
    inner join tabValuta ValRek     on (ValRek.ValNummer = JrValNummer)
    left outer join (tabHulpRekening inner join tabRekeningschema on (RksGid = HulpRekRksGid) inner join tabValuta ValHulpRek on (ValHulpRek.ValNummer = HulpRekValNummer) )
    on (HulpRekJrGid = JrGid)
  where
    JrBjGid = @BjGid and
    ( (@SoortBoeking = 0 and RegelNummer is not null) or
      (@SoortBoeking = 1 and RegelNummer is null) or
      (@SoortBoeking = 2) ) and
    JrPerNr between @VanPerNr and @TotPerNr and
    JrRksGid = @RksGid
  order by
    BeginBalans desc,
    if @Ascending = 0 and @OrderBy = 0 then JrReferentie_Lengte endif desc,
    if @Ascending = 0 and @OrderBy = 0 then JrReferentie endif desc,
    if @Ascending = 1 and @OrderBy = 0 then JrReferentie_Lengte endif,
    if @Ascending = 1 and @OrderBy = 0 then JrReferentie endif,
    if @Ascending = 0 and @OrderBy = 1 then JrBoekdatum endif desc,
    if @Ascending = 1 and @OrderBy = 1 then JrBoekdatum endif,
    // Eerst definitieve mutaties, dan voorlopige mutaties
    if @Ascending = 0 then IsBoekgangDefinitief endif,
    if @Ascending = 1 then IsBoekgangDefinitief endif desc,
    // Altijd nasorteren op basis van het 'regelnummer'
    if @Ascending = 0 then RegelNummer endif desc,
    if @Ascending = 1 then RegelNummer endif,
    if @Ascending = 0 then BoekgangNummer endif desc,
    if @Ascending = 1 then BoekgangNummer endif,
    if @Ascending = 0 then JpNummer endif desc,
    if @Ascending = 1 then JpNummer endif,
    if @Ascending = 0 then JrNummer endif desc,
    if @Ascending = 1 then JrNummer endif;


end;

// call rapGrootboekMutatiesMutaties(1, 0, 1, 0, 12, 2, 1, 0, 3, 3, 2, 1);


create or replace procedure rapGrootboekMutatiesTotalenPerRekening(
in @RksGid                                    integer,
in @RekeningValNummer                         integer,
in @BjGid                                     integer,
in @VanPerNr                                  integer,
in @TotPerNr                                  integer,
in @SoortBoeking                              smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @Verdichten                                smallint, // -1 = niet verdichten, 6 = debiteuren verdichten en 7 = crediteuren verdichten
in @Selectie     	                            integer,  // Selecteren op: 1 = nummer, 2 = zoekcode
in @VanRks	                                  nchar(40),
in @TotRks 	                                  nchar(40),
in @SaldoAfdrukkenIn                          integer,  // 0 = valuta van grootboekrekening,                 2 = basisvaluta, 3 = andere valuta
in @SaldoAfdrukkenExtraValNummer              integer,  // Indien gevuld, saldo afdrukken in de extra ingegeven valuta
in @TotalenPerRekeningAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta

result (
  BeginTotaalDRekeningVal   numeric(15,2),
  BeginTotaalCRekeningVal   numeric(15,2),
  BeginSaldoRekeningVal     numeric(15,2),
  BeginTotaalDBasisVal      numeric(15,2),
  BeginTotaalCBasisVal      numeric(15,2),
  BeginSaldoBasisVal        numeric(15,2),
  BeginTotaalDExtraVal      numeric(15,2),
  BeginTotaalCExtraVal      numeric(15,2),
  BeginSaldoExtraVal        numeric(15,2),
  BeginTotaalDAfdrukVal     numeric(15,2),
  BeginTotaalCAfdrukVal     numeric(15,2),
  BeginSaldoAfdrukVal       numeric(15,2),
  BeginOmrekenVerschilD     numeric(15,2),
  BeginOmrekenVerschilC     numeric(15,2),
  BeginTotaalDAantal        numeric(15,2),
  BeginTotaalCAantal        numeric(15,2),
  BeginSaldoAantal          numeric(15,2),

  PeriodeTotaalDRekeningVal numeric(15,2),
  PeriodeTotaalCRekeningVal numeric(15,2),
  PeriodeSaldoRekeningVal   numeric(15,2),
  PeriodeTotaalDBasisVal    numeric(15,2),
  PeriodeTotaalCBasisVal    numeric(15,2),
  PeriodeSaldoBasisVal      numeric(15,2),
  PeriodeTotaalDExtraVal    numeric(15,2),
  PeriodeTotaalCExtraVal    numeric(15,2),
  PeriodeSaldoExtraVal      numeric(15,2),
  PeriodeTotaalDAfdrukVal   numeric(15,2),
  PeriodeTotaalCAfdrukVal   numeric(15,2),
  PeriodeSaldoAfdrukVal     numeric(15,2),
  PeriodeOmrekenVerschilD   numeric(15,2),
  PeriodeOmrekenVerschilC   numeric(15,2),
  PeriodeTotaalDAantal      numeric(15,2),
  PeriodeTotaalCAantal      numeric(15,2),
  PeriodeSaldoAantal        numeric(15,2),

  EindTotaalDRekeningVal    numeric(15,2),
  EindTotaalCRekeningVal    numeric(15,2),
  EindSaldoRekeningVal      numeric(15,2),
  EindTotaalDBasisVal       numeric(15,2),
  EindTotaalCBasisVal       numeric(15,2),
  EindSaldoBasisVal         numeric(15,2),
  EindTotaalDExtraVal       numeric(15,2),
  EindTotaalCExtraVal       numeric(15,2),
  EindSaldoExtraVal         numeric(15,2),
  EindTotaalDAfdrukVal      numeric(15,2),
  EindTotaalCAfdrukVal      numeric(15,2),
  EindSaldoAfdrukVal        numeric(15,2),
  EindTotaalDAantal         numeric(15,2),
  EindTotaalCAantal         numeric(15,2),
  EindSaldoAantal           numeric(15,2))

begin
  // Deze tabel bevat de gewenste rekeningen (gedaan voor optimalisatie)
  declare local temporary table tmpRekeningen(
    tmpRksGid integer
  ) on commit preserve rows;

  // Declareren van variabelen nodig het bepalen van de resultaatset
  declare @BeginTotaalDRekeningVal   numeric(15,2);
  declare @BeginTotaalCRekeningVal   numeric(15,2);
  declare @BeginTotaalDBasisVal      numeric(15,2);
  declare @BeginTotaalCBasisVal      numeric(15,2);
  declare @BeginTotaalDExtraVal      numeric(15,2);
  declare @BeginTotaalCExtraVal      numeric(15,2);
  declare @BeginTotaalDAfdrukVal     numeric(15,2);
  declare @BeginTotaalCAfdrukVal     numeric(15,2);
  declare @BeginOmrekenVerschilD     numeric(15,2);
  declare @BeginOmrekenVerschilC     numeric(15,2);
  declare @BeginTotaalDAantal        numeric(15,2);
  declare @BeginTotaalCAantal        numeric(15,2);

  declare @PeriodeTotaalDRekeningVal    numeric(15,2);
  declare @PeriodeTotaalCRekeningVal    numeric(15,2);
  declare @PeriodeTotaalDBasisVal       numeric(15,2);
  declare @PeriodeTotaalCBasisVal       numeric(15,2);
  declare @PeriodeTotaalDSaldoExtraVal  numeric(15,2);
  declare @PeriodeTotaalCSaldoExtraVal  numeric(15,2);
  declare @PeriodeTotaalDExtraVal       numeric(15,2);
  declare @PeriodeTotaalCExtraVal       numeric(15,2);
  declare @PeriodeTotaalDAfdrukVal      numeric(15,2);
  declare @PeriodeTotaalCAfdrukVal      numeric(15,2);
  declare @PeriodeOmrekenVerschilD      numeric(15,2);
  declare @PeriodeOmrekenVerschilC      numeric(15,2);
  declare @PeriodeTotaalDAantal         numeric(15,2);
  declare @PeriodeTotaalCAantal         numeric(15,2);

  // Achtereenvolgens de gegevens bepalen voor het begin en de perioden
  declare @Teller      integer;
  declare @tmpVanPerNr integer;
  declare @tmpTotPerNr integer;

  // Ophalen van het aantal decimalen waarin de valuta dient te worden verwerkt
  declare @NumDeciRekeningVal     integer;
  declare @NumDeciBasisVal        integer;
  declare @NumDeciExtraValTotalen integer;
  declare @NumDeciExtraValSaldo   integer;

  // Optimaliseren door koers één keer op te halen
  declare @KoersRekeningVal   double;
  declare @KoersExtraValSaldo double;
  declare @KoersExtraVal      double;

  //call TraceBegin('rapGrootboekMutatiesTotalenPerRekening (@RksGid='+string(@RksGid)+', @RekeningValNummer='+string(@RekeningValNummer)+', @BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', @Verdichten='+string(@Verdichten)+', ...');
  //call Trace('..., @Selectie='+string(@Selectie)+', @VanRks='+string(@VanRks)+', @TotRks='+string(@TotRks)+', @SaldoAfdrukkenIn='+string(@SaldoAfdrukkenIn)+', @SaldoAfdrukkenExtraValNummer='+string(@SaldoAfdrukkenExtraValNummer)+', @TotalenPerRekeningAfdrukkenExtraValNummer='+string(@TotalenPerRekeningAfdrukkenExtraValNummer)+')');

  // Indien er sprake is van verdichting, is de valuta van de rekening gelijk aan de basisvaluta
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciRekeningVal from tabValuta where ValNummer = @RekeningValNummer;
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal    from tabValuta where ValNummer = @@BasisValutaNummer;
  if @TotalenPerRekeningAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenPerRekeningAfdrukkenExtraValNummer;
  end if;
  if @SaldoAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValSaldo from tabValuta where ValNummer = @SaldoAfdrukkenExtraValNummer;
  end if;

  // Tijdelijke tabel vullen met de benodigde Rksgidjes
  if @Verdichten = -1 then
    insert into tmpRekeningen(tmpRksGid)
    values(@RksGid);
  else
    insert into tmpRekeningen(tmpRksGid)
    select RksGid
    from tabRekeningSchema
    where @Verdichten = DefaultSoort and
          ( (@Selectie = 1 and RksInvoer   between @VanRks and @TotRks) or
            (@Selectie = 2 and RksZoekCode between @VanRks and @TotRks)
          );
  end if;
  // Index aanmaken voor snelheid
  create index idx_tmp on tmpRekeningen (tmpRksGid);

  set @KoersRekeningVal   = KoersTovBasisValutaDouble(@BjGid, @TotPerNr, @RekeningValNummer);
  set @KoersExtraValSaldo = KoersTovBasisValutaDouble(@BjGid, @TotPerNr, @SaldoAfdrukkenExtraValNummer);
  set @KoersExtraVal      = KoersTovBasisValutaDouble(@BjGid, @TotPerNr, @TotalenPerRekeningAfdrukkenExtraValNummer);

  set @Teller = 0; // 0 = Beginmutaties, 1 = periodemutaties
  while @teller <= 1 loop

    if @teller = 0 then
      // Beginmutaties dienen in deze context gezien te worden als de mutaties op de beginbalans EN eventueel de mutaties TOT AAN @VanPerNR
      set @tmpVanPerNr = 0;
      set @tmpTotPerNr = if @VanPerNr = 0 then 0 else @VanPerNr - 1 endif;
    else
      // Periodemutaties dienen in deze context gezien te worden als de mutaties VAN AF @VanPerNr TOT EN MET @TotPerNR, EXCLUSIEF de mutaties op de beginbalans
      if @TotPerNr = 0 then
        set @tmpVanPerNr = -1;
        set @tmpTotPerNr = -1;
      else
        set @tmpVanPerNr = if @VanPerNr = 0 then 1 else @VanPerNr endif;
        set @tmpTotPerNr = @TotPerNr;
      end if;
    end if;

    select
      // Bepaling van totaal geboekt bedrag debet/credit in de basisvaluta
      isnull(round(sum((case @SoortBoeking
                          when 0 then SaldoDebetBasisDefinitief
                          when 1 then SaldoDebetBasisVoorlopig
                          when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig
                        end)), @NumDeciBasisVal), 0),
      isnull(round(sum((case @SoortBoeking
                          when 0 then SaldoCreditBasisDefinitief
                          when 1 then SaldoCreditBasisVoorlopig
                          when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig
                        end)), @NumDeciBasisVal), 0),

      // Bepaling van totaal geboekt bedrag debet/credit in de valuta van de grootboekrekening
      isnull(round(sum((case @SoortBoeking
                          when 0 then if @RekeningValNummer = RekSaldoValNummer then SaldoDebetValutaDefinitief                              else SaldoDebetBasisDefinitief/@KoersRekeningVal endif
                          when 1 then if @RekeningValNummer = RekSaldoValNummer then SaldoDebetValutaVoorlopig                               else SaldoDebetBasisVoorlopig/@KoersRekeningVal endif
                          when 2 then if @RekeningValNummer = RekSaldoValNummer then SaldoDebetValutaDefinitief + SaldoDebetValutaVoorlopig  else (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig)/@KoersRekeningVal endif
                        end)), @NumDeciRekeningVal), 0),
      isnull(round(sum((case @SoortBoeking
                          when 0 then if @RekeningValNummer = RekSaldoValNummer then SaldoCreditValutaDefinitief                               else SaldoCreditBasisDefinitief/@KoersRekeningVal endif
                          when 1 then if @RekeningValNummer = RekSaldoValNummer then SaldoCreditValutaVoorlopig                                else SaldoCreditBasisVoorlopig/@KoersRekeningVal endif
                          when 2 then if @RekeningValNummer = RekSaldoValNummer then SaldoCreditValutaDefinitief + SaldoCreditValutaVoorlopig  else (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)/@KoersRekeningVal endif
                        end)), @NumDeciRekeningVal), 0),

      // Bepaling van totaal geboekt bedrag debet/credit in de eventueel extra ingegeven valuta voor het saldo
      isnull(round(sum((case @SoortBoeking
                          when 0 then if @SaldoAfdrukkenExtraValNummer = RekSaldoValNummer then SaldoDebetValutaDefinitief                              else SaldoDebetBasisDefinitief/@KoersExtraValSaldo endif
                          when 1 then if @SaldoAfdrukkenExtraValNummer = RekSaldoValNummer then SaldoDebetValutaVoorlopig                               else SaldoDebetBasisVoorlopig/@KoersExtraValSaldo endif
                          when 2 then if @SaldoAfdrukkenExtraValNummer = RekSaldoValNummer then SaldoDebetValutaDefinitief + SaldoDebetValutaVoorlopig  else (SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig)/@KoersExtraValSaldo endif
                        end)), @NumDeciExtraValSaldo), 0),
      isnull(round(sum((case @SoortBoeking
                          when 0 then if @SaldoAfdrukkenExtraValNummer = RekSaldoValNummer then SaldoCreditValutaDefinitief                               else SaldoCreditBasisDefinitief/@KoersExtraValSaldo endif
                          when 1 then if @SaldoAfdrukkenExtraValNummer = RekSaldoValNummer then SaldoCreditValutaVoorlopig                                else SaldoCreditBasisVoorlopig/@KoersExtraValSaldo endif
                          when 2 then if @SaldoAfdrukkenExtraValNummer = RekSaldoValNummer then SaldoCreditValutaDefinitief + SaldoCreditValutaVoorlopig  else (SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig)/@KoersExtraValSaldo endif
                        end)), @NumDeciExtraValSaldo), 0),

      // Bepaling van totaal geboekt debet/credit aantal
      isnull(sum(case @SoortBoeking when 0 then SaldoDebetAantalDefinitief  when 1 then SaldoDebetAantalVoorlopig  when 2 then SaldoDebetAantalDefinitief  + SaldoDebetAantalVoorlopig  end), 0),
      isnull(sum(case @SoortBoeking when 0 then SaldoCreditAantalDefinitief when 1 then SaldoCreditAantalVoorlopig when 2 then SaldoCreditAantalDefinitief + SaldoCreditAantalVoorlopig end), 0)
    into
      @PeriodeTotaalDBasisVal,
      @PeriodeTotaalCBasisVal,
      @PeriodeTotaalDRekeningVal,
      @PeriodeTotaalCRekeningVal,
      @PeriodeTotaalDSaldoExtraVal,
      @PeriodeTotaalCSaldoExtraVal,
      @PeriodeTotaalDAantal,
      @PeriodeTotaalCAantal
    from
      tmpRekeningen inner join tabRekeningSaldo on (RekSaldoRksGid = tmpRksGid)
    where
      RekSaldoBjGid = @BjGid and
      RekSaldoPerNr between @tmpVanPerNr and @tmpTotPerNr;

   select
      // Bepaling van totaal geboekt bedrag debet/credit in de eventuele extra ingegeven valuta voor de totalen per rekening.
      // Hier wordt dezelfde berekeningswijze gehanteerd als bij balans.
      // !!! De totalen in deze extra valuta corresponderen dus met die van balans en kunnen dus verschillen van de totalen in de
      // valuta van de rekening indien deze toevallig gelijk is aan de extra ingegeven valuta !!!
      isnull(round((@PeriodeTotaalDBasisVal/@KoersExtraVal), @NumDeciExtraValTotalen), 0),
      isnull(round((@PeriodeTotaalCBasisVal/@KoersExtraVal), @NumDeciExtraValTotalen), 0),

      // Bepaling van totaal geboekt bedrag debet/credit in de afdrukvaluta voor het saldo
      isnull((case @SaldoAfdrukkenIn
                when 0 then @PeriodeTotaalDRekeningVal
                when 2 then @PeriodeTotaalDBasisVal
                when 3 then @PeriodeTotaalDSaldoExtraVal
              end
             ), 0),
      isnull((case @SaldoAfdrukkenIn
                when 0 then @PeriodeTotaalCRekeningVal
                when 2 then @PeriodeTotaalCBasisVal
                when 3 then @PeriodeTotaalCSaldoExtraVal
              end
             ), 0)
   into
      @PeriodeTotaalDExtraVal,
      @PeriodeTotaalCExtraVal,
      @PeriodeTotaalDAfdrukVal,
      @PeriodeTotaalCAfdrukVal;

    // Bepaling van de omrekenverschillen alleen indien de valuta van de rekening = valuta waarin het saldo wordt afgedrukt
    // Deze omrekenverschillen zijn het gevolg van het gebruik van tabjournaalregel voor de mutaties en tabrekeningsaldo voor de totalen
    // Bij de valutaconversie van de geboekte bedragen is de boekingskoers genomen
    select
      case @SaldoAfdrukkenIn
        when 0 then
          if @RekeningValNummer <> @@BasisValutaNummer then
            (@PeriodeTotaalDAfdrukVal -
             sum(
               if IsCreditBoeking = 0 then
                 if JrValNummer = @RekeningValNummer then
                   round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif)
                 else
                   round((round(JrBasisBedrag, @NumDeciBasisVal)/@KoersRekeningVal), @NumDeciRekeningVal)
                 endif
               endif
                )
            )
          endif
        when 3 then
          if (@SaldoAfdrukkenExtraValNummer <> @@BasisValutaNummer) and (@SaldoAfdrukkenExtraValNummer = @RekeningValNummer) then
            (@PeriodeTotaalDAfdrukVal -
             sum(
               if IsCreditBoeking = 0 then
                 if JrValNummer = @SaldoAfdrukkenExtraValNummer then
                   round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif)
                 else
                   round((round(JrBasisBedrag, @NumDeciBasisVal)/@KoersExtraValSaldo), @NumDeciExtraValSaldo)
                 endif
               endif
                )
            )
          endif
      end,
      case @SaldoAfdrukkenIn
        when 0 then
          if @RekeningValNummer <> @@BasisValutaNummer then
            (@PeriodeTotaalCAfdrukVal -
             sum(
               if IsCreditBoeking = 1 then
                 if JrValNummer = @RekeningValNummer then
                   round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif)
                 else
                   round((round(JrBasisBedrag, @NumDeciBasisVal)/@KoersRekeningVal), @NumDeciRekeningVal)
                 endif
               endif
                )
            )
          endif
        when 3 then
          if (@SaldoAfdrukkenExtraValNummer <> @@BasisValutaNummer) and (@SaldoAfdrukkenExtraValNummer = @RekeningValNummer) then
            (@PeriodeTotaalCAfdrukVal -
             sum(
               if IsCreditBoeking = 1 then
                 if JrValNummer = @SaldoAfdrukkenExtraValNummer then
                   round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif)
                 else
                   round((round(JrBasisBedrag, @NumDeciBasisVal)/@KoersExtraValSaldo), @NumDeciExtraValSaldo)
                 endif
               endif
                )
            )
          endif
      end
    into
      @PeriodeOmrekenVerschilD,
      @PeriodeOmrekenVerschilC
    from
      tabJournaalPost
      inner join tabJournaalRegel on (JrJpGid = JpGid)
      inner join tabValuta        on (ValNummer = JrValNummer)
      inner join tmpRekeningen    on (JrRksGid = tmpRksGid)
    where
      JpBjGid = @BjGid and
      JrBjGid = @BjGid and
      ( (@SoortBoeking = 0 and RegelNummer is not null) or
        (@SoortBoeking = 1 and RegelNummer is null) or
        (@SoortBoeking = 2) ) and
      JrPerNr between @tmpVanPerNr and @tmpTotPerNr;

    if @teller = 0 then
      set @BeginTotaalDRekeningVal = @PeriodeTotaalDRekeningVal;
      set @BeginTotaalCRekeningVal = @PeriodeTotaalCRekeningVal;
      set @BeginTotaalDBasisVal    = @PeriodeTotaalDBasisVal;
      set @BeginTotaalCBasisVal    = @PeriodeTotaalCBasisVal;
      set @BeginTotaalDExtraVal    = @PeriodeTotaalDExtraVal;
      set @BeginTotaalCExtraVal    = @PeriodeTotaalCExtraVal;
      set @BeginTotaalDAfdrukVal   = @PeriodeTotaalDAfdrukVal;
      set @BeginTotaalCAfdrukVal   = @PeriodeTotaalCAfdrukVal;
      set @BeginOmrekenVerschilD   = @PeriodeOmrekenVerschilD;
      set @BeginOmrekenVerschilC   = @PeriodeOmrekenVerschilC;
      set @BeginTotaalDAantal      = @PeriodeTotaalDAantal;
      set @BeginTotaalCAantal      = @PeriodeTotaalCAantal;
    end if;

    set @Teller = @Teller + 1;

  end loop;

  //call TraceEind('rapGrootboekMutatiesTotalenPerRekening');

  select
    @BeginTotaalDRekeningVal                              BeginTotaalDRekeningVal,
    @BeginTotaalCRekeningVal                              BeginTotaalCRekeningVal,
    BeginTotaalDRekeningVal - BeginTotaalCRekeningVal     BeginSaldoRekeningVal,
    @BeginTotaalDBasisVal                                 BeginTotaalDBasisVal,
    @BeginTotaalCBasisVal                                 BeginTotaalCBasisVal,
    BeginTotaalDBasisVal    - BeginTotaalCBasisVal        BeginSaldoBasisVal,
    @BeginTotaalDExtraVal                                 BeginTotaalDExtraVal,
    @BeginTotaalCExtraVal                                 BeginTotaalCExtraVal,
    BeginTotaalDExtraVal    - BeginTotaalCExtraVal        BeginSaldoExtraVal,
    @BeginTotaalDAfdrukVal                                BeginTotaalDAfdrukVal,
    @BeginTotaalCAfdrukVal                                BeginTotaalCAfdrukVal,
    BeginTotaalDAfdrukVal   - BeginTotaalCAfdrukVal       BeginSaldoAfdrukVal,
    isnull(@BeginOmrekenVerschilD, 0)                     BeginOmrekenVerschilD,
    isnull(@BeginOmrekenVerschilC, 0)                     BeginOmrekenVerschilC,
    @BeginTotaalDAantal                                   BeginTotaalDAantal,
    @BeginTotaalCAantal                                   BeginTotaalCAantal,
    @BeginTotaalDAantal     - @BeginTotaalCAantal         BeginSaldoAantal,

    @PeriodeTotaalDRekeningVal                            PeriodeTotaalDRekeningVal,
    @PeriodeTotaalCRekeningVal                            PeriodeTotaalCRekeningVal,
    PeriodeTotaalDRekeningVal - PeriodeTotaalCRekeningVal PeriodeSaldoRekeningVal,
    @PeriodeTotaalDBasisVal                               PeriodeTotaalDBasisVal,
    @PeriodeTotaalCBasisVal                               PeriodeTotaalCBasisVal,
    PeriodeTotaalDBasisVal    - PeriodeTotaalCBasisVal    PeriodeSaldoBasisVal,
    @PeriodeTotaalDExtraVal                               PeriodeTotaalDExtraVal,
    @PeriodeTotaalCExtraVal                               PeriodeTotaalCExtraVal,
    PeriodeTotaalDExtraVal    - PeriodeTotaalCExtraVal    PeriodeSaldoExtraVal,
    @PeriodeTotaalDAfdrukVal                              PeriodeTotaalDAfdrukVal,
    @PeriodeTotaalCAfdrukVal                              PeriodeTotaalCAfdrukVal,
    PeriodeTotaalDAfdrukVal   - PeriodeTotaalCAfdrukVal   PeriodeSaldoAfdrukVal,
    isnull(@PeriodeOmrekenVerschilD, 0)                   PeriodeOmrekenVerschilD,
    isnull(@PeriodeOmrekenVerschilC, 0)                   PeriodeOmrekenVerschilC,
    @PeriodeTotaalDAantal                                 PeriodeTotaalDAantal,
    @PeriodeTotaalCAantal                                 PeriodeTotaalCAantal,
    @PeriodeTotaalDAantal     - @PeriodeTotaalCAantal     PeriodeSaldoAantal,

    (BeginTotaalDRekeningVal + PeriodeTotaalDRekeningVal) EindTotaalDRekeningVal,
    (BeginTotaalCRekeningVal + PeriodeTotaalCRekeningVal) EindTotaalCRekeningVal,
    (BeginSaldoRekeningVal   + PeriodeSaldoRekeningVal)   EindSaldoRekeningVal,
    (BeginTotaalDBasisVal    + PeriodeTotaalDBasisVal)    EindTotaalDBasisVal,
    (BeginTotaalCBasisVal    + PeriodeTotaalCBasisVal)    EindTotaalCBasisVal,
    (BeginSaldoBasisVal      + PeriodeSaldoBasisVal)      EindSaldoBasisVal,
    (BeginTotaalDExtraVal    + PeriodeTotaalDExtraVal)    EindTotaalDExtraVal,
    (BeginTotaalCExtraVal    + PeriodeTotaalCExtraVal)    EindTotaalCExtraVal,
    (BeginSaldoExtraVal      + PeriodeSaldoExtraVal)      EindSaldoExtraVal,
    (BeginTotaalDAfdrukVal   + PeriodeTotaalDAfdrukVal)   EindTotaalDAfdrukVal,
    (BeginTotaalCAfdrukVal   + PeriodeTotaalCAfdrukVal)   EindTotaalCAfdrukVal,
    (BeginSaldoAfdrukVal     + PeriodeSaldoAfdrukVal)     EindSaldoAfdrukVal,
    (BeginTotaalDAantal      + PeriodeTotaalDAantal)      EindTotaalDAantal,
    (BeginTotaalCAantal      + PeriodeTotaalCAantal)      EindTotaalCAantal,
    (BeginSaldoAantal        + PeriodeSaldoAantal)        EindSaldoAantal;



end;

// call rapGrootboekMutatiesTotalenPerRekening(1, 0, 1, 2, 2, 2, -1, 1, '000001', '1010', 3, 3, 3)


create or replace procedure rapGrootboekMutatiesTotalenPerValuta(
in @BjGid                                   integer,
in @VanPerNr                                integer,
in @TotPerNr                                integer,
in @SoortBoeking                            smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @Selectie     	                          integer,  // Selecteren op: 1 = nummer, 2 = zoekcode
in @VanRks	                                nchar(40),
in @TotRks 	                                nchar(40),
in @RekeningSoorten                         nchar(10),
in @TotalenPerValutaAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta

result (
  BoekValutaNummer       integer,
  BoekValutaCode         nchar(3),
  BoekValutaOmschrijving nchar(40),
  TotaalDBasisVal        numeric(15,2),
  TotaalCBasisVal        numeric(15,2),
  SaldoBasisVal          numeric(15,2),
  TotaalDBoekVal         numeric(15,2),
  TotaalCBoekVal         numeric(15,2),
  SaldoBoekVal           numeric(15,2),
  TotaalDExtraVal        numeric(15,2),
  TotaalCExtraVal        numeric(15,2),
  SaldoExtraVal          numeric(15,2))

begin
  // Voorkomen van afrondingsverschillen
  declare @NumDeciBasisVal          integer;
  declare @NumDeciExtraValTotalen    integer;

  //call TraceBegin('rapGrootboekMutatiesTotalenPerValuta (@BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call Trace('..., @Selectie='+string(@Selectie)+', @VanRks='+string(@VanRks)+', @TotRks='+string(@TotRks)+', @RekeningSoorten='+string(@RekeningSoorten)+', @TotalenPerValutaAfdrukkenExtraValNummer='+string(@TotalenPerValutaAfdrukkenExtraValNummer)+')');

  if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenPerValutaAfdrukkenExtraValNummer;
  end if;
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;

  //call TraceEind('rapGrootboekMutatiesTotalenPerValuta');

  select
    RekSaldoValNummer BoekValutaNummer,
    ValCode BoekValutaCode,
    OmsValuta BoekValutaOmschrijving,
    isnull(sum(round((case @SoortBoeking when 0 then SaldoDebetBasisDefinitief when 1 then SaldoDebetBasisVoorlopig when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig end), @NumDeciBasisVal)), 0) TotaalDBasisVal,
    isnull(sum(round((case @SoortBoeking when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig end), @NumDeciBasisVal)), 0) TotaalCBasisVal,
    TotaalDBasisVal - TotaalCBasisVal,
    if BoekValutaNummer <> @@BasisValutaNummer then
      isnull(sum(round((case @SoortBoeking when 0 then SaldoDebetValutaDefinitief when 1 then SaldoDebetValutaVoorlopig when 2 then SaldoDebetValutaDefinitief + SaldoDebetValutaVoorlopig end), if DecimalenBoeking <> 0 then 2 else 0 endif)), 0)
    else
      TotaalDBasisVal
    endif TotaalDBoekVal,
    if BoekValutaNummer <> @@BasisValutaNummer then
      isnull(sum(round((case @SoortBoeking when 0 then SaldoCreditValutaDefinitief when 1 then SaldoCreditValutaVoorlopig when 2 then SaldoCreditValutaDefinitief + SaldoCreditValutaVoorlopig end), if DecimalenBoeking <> 0 then 2 else 0 endif)), 0)
    else
      TotaalCBasisVal
    endif TotaalCBoekVal,
    TotaalDBoekVal - TotaalCBoekVal,
    if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
      if @TotalenPerValutaAfdrukkenExtraValNummer = BoekValutaNummer then
        TotaalDBoekVal
      else
        isnull(sum(round(round((case @SoortBoeking when 0 then SaldoDebetBasisDefinitief when 1 then SaldoDebetBasisVoorlopig when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig end), @NumDeciBasisVal)/KoersTovBasisValutaDouble(@BjGid, @TotPerNr, @TotalenPerValutaAfdrukkenExtraValNummer), @NumDeciExtraValTotalen)), 0)
      endif
    endif TotaalDExtraVal,
    if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
      if @TotalenPerValutaAfdrukkenExtraValNummer = BoekValutaNummer then
        TotaalCBoekVal
      else
        isnull(sum(round(round((case @SoortBoeking when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig end), @NumDeciBasisVal)/KoersTovBasisValutaDouble(@BjGid, @TotPerNr, @TotalenPerValutaAfdrukkenExtraValNummer), @NumDeciExtraValTotalen)), 0)
      endif
    endif TotaalCExtraVal,
    TotaalDExtraVal - TotaalCExtraVal
  from
    tabRekeningSchema
    inner join tabRekeningSaldo on (RekSaldoRksGid = RksGid)
    inner join tabValuta on (ValNummer = BoekValutaNummer)
  where
    RekSaldoBjGid = @BjGid and
    RekSaldoPerNr between @VanPerNr and @TotPerNr and
    ( (@Selectie = 1 and RksInvoer   between @VanRks and @TotRks) or
      (@Selectie = 2 and RksZoekCode between @VanRks and @TotRks)
    ) and
    (@RekeningSoorten like '%'+string(DefaultSoort)+'%')
  group by
    BoekValutaNummer,
    BoekValutaCode,
    BoekValutaOmschrijving
  order by
    if BoekValutaNummer = @@BasisValutaNummer then 0 else 1 endif,
    BoekValutaCode;


end;

// call rapGrootboekMutatiesTotalenPerValuta(1, 0, 12, 0, 1, '000001', '000001', '01234567', 0)


create or replace procedure rapHistorischvoorraadOverzicht(in @ArtSelectie integer,     in @Art_Van nchar(50),     in @Art_Tot nchar(50),
                                                           in @MagSelectie integer,     in @Mag_Van nchar(50),     in @Mag_Tot nchar(50),
                                                           in @OpbrGrpSelectie integer, in @OpbrGrp_Van nchar(50), in @OpbrGrp_Tot nchar(50),
                                                           in @Peildatum date,          in @OrderBy integer,       in @Ascending Integer,
                                                           in @OrderByOpbrGrp integer,  in @AscendingOpbrGrp integer)
result(pwhgid integer, ArtGid integer, PwhDatum datetime, ArtCode nchar(20), ArtZoekCode nchar(20), ArtOms nchar(40), ArtAantDecAantallen smallint, ArtAantDecPrijzen smallint,
       ArtOmsEenheid nchar(20), PwhOpbrGrpNummer nchar(4), OpbrGrpOms nchar(40), Kostprijs numeric(15,3), PrijsPer numeric(15,3), MutAantal numeric(15,3),Boekwaarde numeric(15,3),
       ArtGewichtPerEenheid numeric(15,3), ArtVolumePerEenheid numeric(15,3), ArtIsPartijAparteKostPrijs smallint, pwhGeschat smallint)
begin
  declare @Pwhgid                 integer;
  declare @ArtGid                 integer;
  declare @Boekwaarde             numeric(15,3);
  declare @MutAantal              numeric(15,3);
  declare @NumDeci                integer;
  declare @IsolationLevel         smallint;

  declare local temporary table tmpVoorraadSnapshot(
    tmpVrdArtGid                  integer,
    tmpVrdMagGid                  integer,
    tmpVrdArtPartijNummer         nchar(20),
    tmpVrdAantal                  numeric(15,3)) on commit preserve rows;

  //Declare temporary table for the records
  declare local temporary table tmpHistorischvoorraadOverzicht(
    tmpPwhgid                     integer,
    tmpArtGid                     integer,
    tmpPwhDatum                   datetime,
    tmpArtCode                    nchar(20),
    tmpArtZoekCode                nchar(20),
    tmpArtOms                     nchar(40),
    tmpArtPartijGID               integer,
    tmpArtPartijNummer            nchar(20),
    tmpArtAantDecAantallen        smallint,
    tmpArtAantDecPrijzen          smallint,
    tmpArtOmsEenheid              nchar(20),
    tmpPwhOpbrGrpNummer           nchar(4),
    tmpOpbrGrpOms                 nchar(40),
    tmpkostprijs                  numeric(15,3),
    tmpPrijsPer                   numeric(15,3),
    tmpAantal                     numeric(15,3),
    tmpInVoorraad                 numeric(15,3),
    tmpMutAantal                  numeric(15,3),
    tmpBoekwaarde                 numeric(15,3),
    tmpArtGewichtPerEenheid       numeric(15,3),
    tmpArtVolumePerEenheid        numeric(15,3),
    tmpArtIsPartijAparteKostPrijs smallint,
    tmpMagGid                     integer,
    tmpPwhGeschat                 smallint) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapHistorischvoorraadOverzicht > ';
  //call TraceBegin(@@ErrorTextProcedure + '@SoortOpdracht = ' + string(@ArtSelectie));

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  //call Trace('rapHistorischvoorraadOverzicht > snapshot maken van de voorraad');
  insert into tmpVoorraadSnapshot(tmpVrdArtGid, tmpVrdMagGid, tmpVrdArtPartijNummer, tmpVrdAantal)
  select     ArtGid, (select ArtMagMagGid from tabArtikelMagazijn where ArtMagGid = ArtLocArtMagGid) MagGid, (select ArtPartijNummer from tabArtikelPartij where ArtPartijGid = ArtLocPartijGid) ArtPartijNummer, sum(ArtLocVoorraad)
  from       tabArtikel
  inner join tabArtikelLocatie on (ArtLocArtGid = ArtGid)
  group by   ArtGid, MagGid, ArtPartijNummer
  union all
  select     VrdMutArtGid, VrdMutLocMagGid, VrdMutLocPartijNummer, sum(-1 * VrdMutLocAantal)
  from       tabVoorraadMutatie
  inner join tabVoorraadMutatieLocatieSerie on (VrdMutLocVrdMutGid = VrdMutGid)
  where      VrdMutdatum > @PeilDatum
  group by   VrdMutArtGid, VrdMutLocMagGid, VrdMutLocPartijNummer;

  set temporary option isolation_level = @IsolationLevel;

  //call Trace('rapHistorischvoorraadOverzicht > aantal records toegevoegd : ' + string(@@rowcount));

  //call Trace('Haal de huidige voorraad op per art/partij/mag');
  insert into tmpHistorischvoorraadOverzicht(tmpArtGid, tmpArtCode, tmpArtZoekCode, tmpArtOms,  tmpArtAantDecAantallen, tmpArtAantDecPrijzen, tmpArtOmsEenheid,
                                             tmpKostprijs, tmpPrijsPer, tmpArtGewichtPerEenheid, tmpArtVolumePerEenheid, tmpArtIsPartijAparteKostPrijs,
                                             tmpArtPartijNummer, tmpPwhOpbrGrpNummer, tmpOpbrGrpOms, tmpMagGid, tmpInVoorraad, tmpAantal, tmpBoekwaarde, tmpPwhGeschat)
  select     ArtGid, ArtCode, ArtZoekcode, ArtOms, ArtAantDecAantallen, ArtAantDecPrijzen, ArtOmsEenheid,
             ArtKostPrijsEx, ArtPrijsPer, ArtGewichtPerEenheid, ArtVolumePerEenheid, ArtIsPartijAparteKostPrijs,
             isNull(tmpVrdArtPartijNummer,''), OpbrGrpNummer, OpbrGrpOms, MagGid, sum(tmpVrdAantal), 0, 0, 0
  from       tmpVoorraadSnapshot
  inner join tabArtikel        on (ArtGid = tmpVrdArtGid)
  inner join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGid)
  inner join tabMagazijn       on (MagGid = tmpVrdMagGid)
  where           ArtHeeftVoorraad = 1 and ArtSoort = 2
            and ((@ArtSelectie = 1     and ArtCode                        between @Art_Van     and @Art_Tot)     or
                 (@ArtSelectie = 2     and ArtZoekcode                    between @Art_Van     and @Art_Tot)     or
                 (@ArtSelectie = 3     and ArtOms                         between @Art_Van     and @Art_Tot))
            and ((@OpbrGrpSelectie = 1 and OpbrGrpNummer                  between @OpbrGrp_Van and @OpbrGrp_Tot) or
                 (@OpbrGrpSelectie = 2 and OpbrGrpOms                     between @OpbrGrp_Van and @OpbrGrp_Tot))
            and ((@MagSelectie = 1     and right('000'+string(MagCode),3) between @Mag_Van     and @Mag_Tot)     or
                 (@MagSelectie = 2     and MagZoekcode                    between @Mag_Van     and @Mag_Tot)     or
                 (@MagSelectie = 3     and MagOms                         between @Mag_Van     and @Mag_Tot))
  group by        ArtGid, ArtCode, ArtZoekcode, ArtOms, ArtAantDecAantallen, ArtAantDecPrijzen, ArtOmsEenheid,
                  ArtKostPrijsEx, ArtPrijsPer, ArtGewichtPerEenheid, ArtVolumePerEenheid, ArtIsPartijAparteKostPrijs,
                  tmpVrdArtPartijNummer, OpbrGrpNummer, OpbrGrpOms, MagGid, MagCode, MagZoekcode, MagOms;

  //call Trace('Indexen aanmaken');
  create index idx_tmpHistorischvoorraadOverzicht on tmpHistorischvoorraadOverzicht(tmpArtGid, tmpArtPartijNummer);

  update tmpHistorischvoorraadOverzicht set tmpArtPartijGid = ArtPartijGid, tmpkostprijs = if tmpArtIsPartijAparteKostPrijs = 0 then tmpkostprijs else isnull(artpartijkostprijsex,0) endif
  from   tabArtikelPartij where ArtPartijNummer = tmpArtPartijNummer and ArtPartijArtGid = tmpArtGid;

  //call Trace('Prijswijzigingen ophalen van partij artikelen.');
  update tmpHistorischvoorraadOverzicht
  set tmpPwhGid = pwhGid,
      tmpPwhDatum = pwhDatum,
      tmpPwhOpbrGrpNummer = pwhOpbrGrpNummer,
      tmpKostPrijs = PwhOudeKostprijs,
      tmpPrijsPer = PwhOudePrijsPer,
      tmpArtisPartijAparteKostPrijs = 1,
      tmppwhGeschat = pwhGeschat
  from tabPrijswijzigingsHistorie
  where PwhGid = (select first p.PwhGid
                  from   tabPrijswijzigingsHistorie p
                  Where  p.pwhartgid = tabPrijswijzigingsHistorie.pwhartgid
                     and p.pwhartpartijnummer = tabPrijswijzigingsHistorie.pwhartpartijnummer
                     and (   (PwhOudeKostprijs<>PwhNieuweKostprijs)
                          or (PwhOudePrijsPer<>PwhNieuwePrijsPer)
                         )
                     and date(p.pwhdatum) > @PeilDatum
                  order by p.pwhdatum)
  and tmpArtGid = pwhArtGid and tmpArtPartijNummer = pwhartpartijnummer and isNull(tmpArtPartijNummer,'') <> '';

  //call Trace('Als er 1 een aparte kostprijs per partij heeft, hebben ze het allemaal.');
  update tmpHistorischvoorraadOverzicht
  set tmpArtisPartijAparteKostPrijs = 1
  where tmpArtPartijNummer <> '' and tmpArtisPartijAparteKostPrijs = 0 and
  tmpArtGid in (select tmpArtGid from tmpHistorischvoorraadOverzicht where tmpArtisPartijAparteKostPrijs = 1);

  //call Trace('Prijswijzigingen ophalen van niet partij artikelen.');
  update tmpHistorischvoorraadOverzicht
  set tmpPwhGid = pwhGid,
      tmpPwhDatum = pwhDatum,
      tmpPwhOpbrGrpNummer = pwhOpbrGrpNummer,
      tmpKostPrijs = PwhOudeKostprijs,
      tmpPrijsPer = PwhOudePrijsPer,
      tmpPwhGeschat = pwhGeschat
  from tabPrijswijzigingsHistorie
  where PwhGid = (select first p.PwhGid
                  from   tabPrijswijzigingsHistorie p
                  Where  p.pwhartgid = tabPrijswijzigingsHistorie.pwhartgid
                     and isNull(p.pwhartpartijnummer,'') = ''
                     and date(p.pwhdatum) > @PeilDatum
                  order by p.pwhdatum)
  and tmpArtGid = pwhArtGid and isNull(pwhartpartijnummer,'') = ''
  and (   (isNull(tmpArtPartijNummer,'') = '')     //ACW Defect 47103: Dit geldt natuurlijk ALLEEN voor die artikelen waarvoor de partijen GEEN eigen kostprijs hanteert
       or (tmpArtisPartijAparteKostPrijs = 0)
      ) ;

  //call Trace('Mutatieaantal en Locatienaam invullen. Kostprijs word bij partijen op 0 gezet waar deze per partij apart zijn omdat deze kunnen verschillen.');
  update tmpHistorischvoorraadOverzicht set tmpMutAantal = isNull(tmpAantal,0) + tmpInVoorraad,
         tmpBoekwaarde=(isNull(tmpAantal,0) + tmpInVoorraad)/if isNull(tmpPrijsPer,0) = 0 then 1 else tmpPrijsPer endif * tmpKostprijs,
         tmpkostprijs = if tmpArtIsPartijAparteKostPrijs=1 then 0 else tmpkostprijs endif;

  select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = @@basisValutaNummer;

  set @@ErrorTextProcedure='rapHistorischVoorraadOverzicht';
  //call TraceEind(@@ErrorTextProcedure);

  select Max(tmpPwhgid) pwhGid,tmpArtGid ArtGid,max(tmpPwhDatum) pwhDatum,tmpArtCode ArtCode,tmpArtZoekCode ArtZoekCode,
    tmpArtOms ArtOms,tmpArtAantDecAantallen ArtAantDecAantallen,tmpArtAantDecPrijzen ArtAantDecPrijzen,tmpArtOmsEenheid ArtOmsEenheid,tmpPwhOpbrGrpNummer pwhOpbrGrpNummer,
    tmpOpbrGrpOms OpbrGrpOms,tmpkostprijs kostprijs,tmpPrijsPer prijsper,Sum(tmpMutAantal) MutAantal,Sum(Round(tmpBoekwaarde,@NumDeci)) BoekWaarde,tmpArtGewichtPerEenheid ArtGewichtPerEenheid,
    tmpArtVolumePerEenheid ArtVolumePerEenheid,tmpArtIsPartijAparteKostPrijs ArtIsPartijAparteKostPrijs,max(tmpPwhGeschat) pwhGeschat
  from tmpHistorischvoorraadOverzicht
  group By
    tmpArtGid,tmpArtCode,tmpArtZoekCode,
    tmpArtOms,tmpArtAantDecAantallen,tmpArtAantDecPrijzen,tmpArtOmsEenheid,tmpPwhOpbrGrpNummer,
    tmpOpbrGrpOms,tmpkostprijs,tmpPrijsPer,tmpArtGewichtPerEenheid,
    tmpArtVolumePerEenheid,tmpArtIsPartijAparteKostPrijs
  order By
    if @AscendingOpbrGrp = 1 then if @OrderByOpbrGrp=0 then tmpPwhOpbrGrpNummer endif endif asc,
    if @AscendingOpbrGrp = 0 then if @OrderByOpbrGrp=0 then tmpPwhOpbrGrpNummer endif endif desc,
    if @AscendingOpbrGrp = 1 then if @OrderByOpbrGrp=1 then tmpOpbrGrpOms endif endif asc,
    if @AscendingOpbrGrp = 0 then if @OrderByOpbrGrp=1 then tmpOpbrGrpOms endif endif desc,
    if @Ascending = 1 then if @OrderBy=0 then tmpArtCode endif endif asc,
    if @Ascending = 0 then if @OrderBy=0 then tmpArtCode endif endif desc,
    if @Ascending = 1 then if @OrderBy=1 then tmpArtZoekCode endif endif asc,
    if @Ascending = 0 then if @OrderBy=1 then tmpArtZoekCode endif endif desc,
    if @Ascending = 1 then if @OrderBy=2 then tmpArtOms endif endif asc,
    if @Ascending = 0 then if @OrderBy=2 then tmpArtOms endif endif desc;
end;


create or replace procedure rapHistorischvoorraadOverzichtMagazijn(in @ArtSelectie Integer,     in @Art_Van nchar(50),     in @Art_Tot nchar(50),
                                                                   in @MagSelectie Integer,     in @Mag_Van nchar(50),     in @Mag_Tot nchar(50),
                                                                   in @OpbrGrpSelectie integer, in @OpbrGrp_Van nchar(50), in @OpbrGrp_Tot nchar(50),
                                                                   in @Peildatum date,          in @OrderBy integer,       in @Ascending Integer)
result(MagCode integer, MagOms nchar(40), Boekwaarde numeric(15,3), pwhGeschat smallint)
begin
  declare @ArtGid                 integer;
  declare @MagCode                integer;
  declare @Boekwaarde             numeric(15,3);
  declare @NumDeci                integer;
  declare @IsolationLevel         smallint;

  declare local temporary table tmpVoorraadSnapshot(
    tmpVrdArtGid                  integer,
    tmpVrdMagGid                  integer,
    tmpVrdArtPartijNummer         nchar(20),
    tmpVrdAantal                  numeric(15,3)) on commit preserve rows;

  declare local temporary table tmpHistorischvoorraadOverzichtMagazijn(
    tmpArtGid                     integer,
    tmpArtPartijNummer            nchar(20),
    tmpArtPartijGid               integer,
    tmpArtisPartijAparteKostPrijs smallint,
    tmpkostprijs                  numeric(15,3),
    tmpPrijsPer                   numeric(15,3),
    tmpAantal                     numeric(15,3),
    tmpMutAantal                  numeric(15,3),
    tmpInVoorraad                 numeric(15,3),
    tmpBoekwaarde                 numeric(15,3),
    tmpMagGid                     integer,
    tmpMagCode                    integer,
    tmpMagZoekcode                nchar(10),
    tmpMagOms                     nchar(40),
    tmpPwhGeschat                 smallint) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapHistorischvoorraadOverzichtMagazijn > ';
  //call TraceBegin(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  //call Trace('rapHistorischvoorraadOverzichtMagazijn > snapshot maken van de voorraad');
  insert into tmpVoorraadSnapshot(tmpVrdArtGid, tmpVrdMagGid, tmpVrdArtPartijNummer, tmpVrdAantal)
  select     ArtGid, (select ArtMagMagGid from tabArtikelMagazijn where ArtMagGid = ArtLocArtMagGid) MagGid, (select ArtPartijNummer from tabArtikelPartij where ArtPartijGid = ArtLocPartijGid) ArtPartijNummer, sum(ArtLocVoorraad)
  from       tabArtikel
  inner join tabArtikelLocatie on (ArtLocArtGid = ArtGid)
  group by   ArtGid, MagGid, ArtPartijNummer
  union all
  select     VrdMutArtGid, VrdMutLocMagGid, VrdMutLocPartijNummer, sum(-1 * VrdMutLocAantal)
  from       tabVoorraadMutatie
  inner join tabVoorraadMutatieLocatieSerie on (VrdMutLocVrdMutGid = VrdMutGid)
  where      VrdMutdatum > @PeilDatum
  group by   VrdMutArtGid, VrdMutLocMagGid, VrdMutLocPartijNummer;

  set temporary option isolation_level = @IsolationLevel;

  //call Trace('rapHistorischvoorraadOverzichtMagazijn > aantal records toegevoegd : ' + string(@@rowcount));

  //Eerst alle Artikels ophalen. Degene met partijnummers geen kostprijs, boekwaarde en dergelijke geven
  insert into tmpHistorischvoorraadOverzichtMagazijn(tmpArtGid,tmpArtPartijNummer, tmpArtisPartijAparteKostPrijs, tmpKostprijs,tmpPrijsper,
                                                     tmpInVoorraad, tmpAantal, tmpMagGid, tmpMagCode, tmpMagZoekcode, tmpMagOms, tmpPwhGeschat)
  select ArtGid, isNull(tmpVrdArtPartijNummer,''), ArtIsPartijAparteKostPrijs, ArtKostprijsex, ArtPrijsPer,
         sum(tmpVrdAantal), 0, MagGid, MagCode, MagZoekCode, MagOms, 0
  from            tmpVoorraadSnapshot
       inner join tabArtikel        on (ArtGid = tmpVrdArtGid)
       inner join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGid)
       inner join tabMagazijn       on (MagGid = tmpVrdMagGid)
  where           ArtHeeftVoorraad = 1 and ArtSoort = 2
            and ((@ArtSelectie = 1     and ArtCode                        between @Art_Van     and @Art_Tot)     or
                 (@ArtSelectie = 2     and ArtZoekcode                    between @Art_Van     and @Art_Tot)     or
                 (@ArtSelectie = 3     and ArtOms                         between @Art_Van     and @Art_Tot))
            and ((@OpbrGrpSelectie = 1 and OpbrGrpNummer                  between @OpbrGrp_Van and @OpbrGrp_Tot) or
                 (@OpbrGrpSelectie = 2 and OpbrGrpOms                     between @OpbrGrp_Van and @OpbrGrp_Tot))
            and ((@MagSelectie = 1     and right('000'+string(MagCode),3) between @Mag_Van     and @Mag_Tot)     or
                 (@MagSelectie = 2     and MagZoekcode                    between @Mag_Van     and @Mag_Tot)     or
                 (@MagSelectie = 3     and MagOms                         between @Mag_Van     and @Mag_Tot))
  group by        ArtGid, ArtCode, ArtZoekcode, ArtOms, ArtOmsEenheid,
                  ArtKostPrijsEx, ArtPrijsPer, ArtIsPartijAparteKostPrijs,
                  tmpVrdArtPartijNummer, OpbrGrpNummer, OpbrGrpOms, MagGid, MagCode, MagZoekcode, MagOms;

  //call Trace('Indexen aanmaken');
  create index idx_tmpHistorischvoorraadOverzicht on tmpHistorischvoorraadOverzichtMagazijn(tmpArtGid, tmpArtPartijNummer);

  update tmpHistorischvoorraadOverzichtMagazijn set tmpArtPartijGid = ArtPartijGid, tmpkostprijs = if ArtIsPartijAparteKostPrijs = 0 then tmpkostprijs else isnull(artpartijkostprijsex,0) endif
  from   tabArtikelPartij
         inner join tabArtikel on (ArtGid = ArtPartijArtGid)
  where  ArtPartijNummer = tmpArtPartijNummer and ArtPartijArtGid = tmpArtGid;

  //Prijswijzigingen ophalen zonder partijen met eigen kostprijzen
  update tmpHistorischvoorraadOverzichtMagazijn
  set tmpKostPrijs = PwhOudeKostprijs,
      tmpPrijsPer = PwhOudePrijsPer,
      tmpPwhGeschat = PwhGeschat
  from tabPrijswijzigingsHistorie
  left outer join TabArtikelPartij On ArtPartijArtGID = pwhArtGID and isNull(artpartijnummer,'') = ''
  where PwhGid = (select first p.PwhGid from tabPrijswijzigingsHistorie p Where p.pwhartgid = tabPrijswijzigingsHistorie.pwhartgid and isNull(p.pwhartpartijnummer,'') = '' and date(p.pwhdatum) > @PeilDatum order by p.pwhdatum)
  and tmpArtGid = pwhArtGid and isNull(pwhartpartijnummer,'') = ''
  and (   (isNull(tmpArtPartijNummer,'') = '')     //ACW Defect 47103: Dit geldt natuurlijk ALLEEN voor die artikelen waarvoor de partijen GEEN eigen kostprijs hanteert
       or (tmpArtisPartijAparteKostPrijs = 0)
      ) ;

  //Prijswijzigingen ophalen van partijen
  update tmpHistorischvoorraadOverzichtMagazijn
  set tmpKostPrijs  = PwhOudeKostprijs,
      tmpPrijsPer   = PwhOudePrijsPer,
      tmpPwhGeschat = PwhGeschat
  from tabPrijswijzigingsHistorie
  where PwhGid = (select first p.PwhGid from tabPrijswijzigingsHistorie p Where p.pwhartgid = tabPrijswijzigingsHistorie.pwhartgid and p.pwhartpartijnummer = tabPrijswijzigingsHistorie.pwhartpartijnummer and ((PwhOudeKostprijs<>PwhNieuweKostprijs) or (PwhOudePrijsPer<>PwhNieuwePrijsPer)) and date(p.pwhdatum) > @PeilDatum order by p.pwhdatum)
  and tmpArtGid = pwhArtGid and tmpartpartijnummer = pwhartpartijnummer and isNull(tmpArtPartijNummer,'') <> '';

  //Mutatieaantal en Locatienaam invullen
  update tmpHistorischvoorraadOverzichtMagazijn set
         tmpMutAantal = isNull(tmpAantal,0) + tmpInVoorraad,
         tmpBoekwaarde=(isNull(tmpAantal,0) + tmpInVoorraad)/if isNull(tmpPrijsPer,0) = 0 then 1 else tmpPrijsPer endif * tmpKostprijs;

  select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = @@basisValutaNummer;

  set @@ErrorTextProcedure = 'rapHistorischVoorraadOverzichtMagazijn';
  //call TraceEind(@@ErrorTextProcedure);

  select   tmpMagCode MagCode, tmpMagOms MagOms, sum(Round(tmpBoekwaarde, @NumDeci)) as BoekWaarde, max(tmpPwhGeschat) pwhGeschat
  from     tmpHistorischvoorraadOverzichtMagazijn
  group by tmpMagCode,tmpMagZoekCode,tmpMagOms
  order by
  if @Ascending = 1 then if @OrderBy=0 then tmpMagCode endif endif asc,
  if @Ascending = 0 then if @OrderBy=0 then tmpMagCode endif endif desc,
  if @Ascending = 1 then if @OrderBy=1 then tmpMagZoekCode endif endif asc,
  if @Ascending = 0 then if @OrderBy=1 then tmpMagZoekCode endif endif desc,
  if @Ascending = 1 then if @OrderBy=2 then tmpMagOms endif endif asc,
  if @Ascending = 0 then if @OrderBy=2 then tmpMagOms endif endif desc;
end;


create or replace procedure rapIncassoOSPnaarVoorstel(
  in @SessieID                    integer,      // Elk record wordt met dit sessienummer gekenmerkt
  in @MetVoorlopigePost           smallint,     // 0 = alleen definitief, 1 = ook voorlopige posten
  in @MetIncDatum                 smallint,     // 0 = Geen incassodatum-test; 1 = post als met incassodatum
  in @ZonderIncDatum              smallint,     // 0 = Geen incassodatum-test; 1 = post als zonder incassodatum
  in @OverslaanAlsCreditNota      smallint,     // 0 = Geen Creditnota-test; 1 = Post overslaan als deb. een creditnota heeft
  in @OverslaanAlsVooruitbetaling smallint,     // 0 = Geen vooruitbetaling-test; 1 = Post overslaan als deb. een post met vooruitbetaling heeft
  in @OmsOvernemenOms             smallint,     // 0 = Omschrijving niet overnemen; 1 = Omschrijving overnemen
  in @OmsOvernemenRef             smallint,     // 0 = Referentie niet overnemen; 1 = Referentie overnemen (ref. = DebiteurNummer + spatie + factuurnummer)
  in @OmsTekstRef                 nchar(40),    // Tekst *voor* referentie (alleen als @OmsOvernemenRef=1)
  in @TeGebruikenIncDatum         date,         // NULL => Gebruik berekende inc.datum op de regel, anders altijd deze datum
  in @VanDebNummer                nchar(10),    // Vanaf debiteurnummer
  in @TotDebNummer                nchar(10),    // Tot   debiteurnummer
  in @VanFactNummer               nchar(40),    // Vanaf factuurnummer
  in @TotFactNummer               nchar(40),    // Tot   factuurnummer
  in @VanFactDatum                Date,         // Vanaf factuurdatum
  in @TotFactDatum                Date,         // Tot   factuurdatum
  in @VanVervalDatum              Date,         // Vanaf vervaldatum
  in @TotVervalDatum              Date,         // Tot   vervaldatum
  in @VanIncDatum                 Date,         // Vanaf incassodatum (Alleen relevant met @MetIncDatum=1)
  in @TotIncDatum                 Date,         // Tot   incassodatum (Alleen relevant met @MetIncDatum=1)
  in @MetNietGeldigeMachtiging    smallint,     // -1 = GEEN machtigingen opnemen (=Clieop), 0 = Alleen met geldige machtiging, 1 = ook met niet-geldige machtiging
  in @PostenZonderGeldigeBankrekening smallint, // 0 = alleen geldige bankrekeningen (Clieop, dan NL, PAIN, dan IBAN), 1 = ook met niet-geldige bankrekeningen
  in @Incassoschema                   smallint, // 0 = CORE, 1 = B2B
  in @MetCreditnotas                  smallint, // 1 = Verrekenen creditnotas
  in @MetTeveelBetalingen             smallint, // 1 = Verrekenen teveelbetalingen
  in @HeeftRechtdopb                  smallint  // 1 = Gebruiker Heeft rechten om CreditNotas te betalen. Als geen rechten en Openstaande post is CreditNota of TeveelBetaling, maar niet gefiatteerd, dan wordt de openstaande post niet opgenomen in voorstel!
)
/* Redenen voor het overslaan van een OSP:
   A = Geblokkeerd
   B = Valuta voldoet niet
   C = Bankrekening ongeldig
   D = Creditnota is niet gefiatteerd
   E = Debiteur overgeslagen omdat die creditnotas heeft
   F = Debiteur overgeslagen omdat die vooruitbetalingen heeft
   G = OSP al opgenomen in betalingsopdracht
   H = OSP al opgenomen in ander incassovoorstel
   I = Machtiging ongeldig
   J = Machtiging van juiste schema (CORE of B2B)
   K = Totaal te incasseren <= 0 (dus met creditnotas ed. wordt de verzamelincasso <= 0)
   L = Bedrag voor incassofactuur <= 0
   M = Aantal incassopogingen verbruikt
   N = Incassodatum niet gevuld
*/
result (
  Overslaan               smallint, //Resultaat is meer dan alleen een wel/niet overslaan, maar met reden, wordt niet teruggegeven, maar wel onthouden
  RksGid                  integer,
  OspGid                  integer,
  OspFactuurNummer        nchar(40),
  NawRekGid               integer,
  TeIncBedrag             numeric(15,2),
  IncassoDatumOpRegel     date,
  Betalingskenmerk        nchar(24),
  icmReferentie           nchar(35),
  Omschrijving            nchar(250),
  Gefiatteerd             smallint,
  FiatteringGewijzigdDoor nchar(40),
  FiatteringGewijzigdOp   timestamp
)
begin

  declare @Referentie nchar(35);

  declare local temporary table tmpGeldigeMachtigingen(
    tmpReferentie nchar(35)
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapIncassoOSPnaarVoorstel(@MetVoorlopigePost='+string(@MetVoorlopigePost)+', @MetIncDatum='+string(@MetIncDatum)+', @ZonderIncDatum='+string(@ZonderIncDatum)+', @OverslaanAlsCreditNota='+string(@OverslaanAlsCreditNota)+', @OverslaanAlsVooruitbetaling='+string(@OverslaanAlsVooruitbetaling)+'@OmsOvernemenOms='+string(@OmsOvernemenOms)+', @OmsOvernemenRef='+string(@OmsOvernemenRef)+', @OmsTekstRef='+@OmsTekstRef+', @TeGebruikenIncDatum='+string(@TeGebruikenIncDatum);
  //call trace(@@ErrorTextProcedure);
  //call trace(', @VanDebNummer='+@VanDebNummer+', @TotDebNummer='+@TotDebNummer+', @VanFactNummer='+@VanFactNummer+', @TotFactNummer='+@TotFactNummer+', @VanFactDatum='+string(@VanFactDatum)+', @TotFactDatum='+string(@TotFactDatum)+', @VanVervalDatum='+string(@VanVervalDatum)+', ');
  //call trace('@TotVervalDatum='+string(@TotVervalDatum)+', @VanIncDatum='+string(@VanIncDatum)+', @TotIncDatum='+string(@TotIncDatum)+', @Incassoschema='+string(@Incassoschema)+')');
  //call traceBegin(@@ErrorTextProcedure);

  //Table eerst opschonen
    //call trace('Table opschonen voor sessie '+string(@SessieID));
  delete tabIncassoVoorstelCreate
  where IvcUniekID = @SessieID;

   //call trace('Eerste insert');
  Insert into tabIncassoVoorstelCreate(IvcUniekID, IvcRksGid, IvcNawGid, IvcOspGid, IvcNawRekGid, IvcIncDatum, IvcTeIncBedrag, IvcIcmReferentie, IvcOverslaan, IvcIsCreditNota, IvcIsTeveelBetaling, IvcIsGefiatteerd, IvcFiatteringGewijzigdDoor, IvcFiatteringGewijzigdOp)
  select
    @SessieID,
    RksGid,
    (select NawFilNawGid from tabNawFile where NawFilFonID = 'D' and NawFilRksGid = RksGid),
    OspGid,
    if OspIncNawRekGid is null then
      // Bankrekening is leeg, dus probeer de default voor incasso van de NAW
     (select first NawRekGid
      from   tabNawRekening
             inner join tabNawFile on (NawFilNawGid = NawRekNawGid)
      where      (NawFilRksGid = RksGid)
             and (NawRekSoort like '%i%')
             //and (NawRekIsBuitenland = 0) Is in de where verwerkt...
     )
    else
     OspIncNawRekGid
    endif GebruikNawRekGid,
    if @TeGebruikenIncDatum is null then
     // Gebruik de incassodatum van de OSP; indien leeg OF voor de verwerkingsdatum, dan de verwerkingsdatum
     if isnull(OspIncDatum, OspVervalDatum) is null or (isnull(OspIncDatum, OspVervalDatum) < @@Verwerkingsdatum) then
       @@Verwerkingsdatum
     else
       isnull(OspIncDatum, OspVervalDatum)
     endif
    else
     @TeGebruikenIncDatum
    endif IncassoDatumOpRegel,
    OspFactuurBedragDefinitief + (@MetVoorlopigePost * OspFactuurBedragVoorlopig) -
    OspBetaaldBedragDefinitief - OspBetaaldBedragVoorlopig -
    OspBedragOnderwegInValuta -  // Bedrag onderweg tegenwoordig ook al testen!
    IsNull( // Bedrag in bestaande voorstellen
          (select sum(IncRglTeIncasseren)
           from tabIncassoRegel
           where     (IncRglRksGid = RksGid )
                 and (IncRglFactuurNummer_Lengte = OspFactuurNummer_Lengte)
                 and (IncRglFactuurNummer = OspFactuurNummer)
                 and (IncRglStatus = 0) // Alleen OSP in voorstelregels! (Als de opdracht nog niet is aangemaakt)
          ), 0) -
    IsNull( // Ook de verzamelregels meenemen
          (select Sum(IrvTeIncasseren)
           from tabIncassoRegelVerzameld
           inner join tabIncassoRegel on IncRglGid = IrvIncRglGid
           where    (IncRglRksGid = OspRksGid)
                and (IrvFactuurNummer_Lengte = OspFactuurNummer_Lengte)
                and (IrvFactuurNummer = OspFactuurNummer)
                and (IncRglStatus = 0)
          ), 0) TeIncBedrag,
    if @MetNietGeldigeMachtiging <> -1 then OspIcmReferentie endif,
    '', //Overslaan
    (if (OspFactuurBedragDefinitief + (@MetVoorlopigePost * OspFactuurBedragVoorlopig) < 0) then 1 else 0 endif) IsCreditNota,
    (if
      (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig > OspFactuurBedragDefinitief + (@MetVoorlopigePost * OspFactuurBedragVoorlopig))
      and (OspFactuurBedragDefinitief + (@MetVoorlopigePost * OspFactuurBedragVoorlopig) > 0)
      then 1 else 0 endif) IsTeveelBetaling,
    OspGefiatteerd,
    OspFiatteringGewijzigdDoor,
    OspFiatteringGewijzigdOp
  from
   tabopenstaandepost
   inner join tabRekeningschema   on (RksGid = OspRksGid)
   left outer join tabNawRekening on (NawRekGid = GebruikNawRekGid)
  where
       OspIsVervallen   = 0                                                            // Alleen de nog niet vervallen OSPs
   and OspBjGid         = @@BjGid                                                      // Alleen in DIT boekjaar testen
   and RksNummer        between @VanDebNummer   and @TotDebNummer                      // Alleen OSPs van de range debiteuren
   and
      // Alleen OSPs van de range factuurnummers
      // note DG: Factuurnummer wijziging; zoals afgesproken uitvullen met spaties en dan between selectie
      (Repeat(' ',40-OspFactuurNummer_Lengte) + OspFactuurNummer between Repeat(' ',40-length(@VanFactNummer)) + @VanFactNummer and Repeat(' ',40-length(@TotFactNummer)) + @TotFactNummer)
   and OspFactuurDatum  between @VanFactDatum   and @TotFactDatum                      // Alleen OSPs van de range factuurdata
   and OspVervalDatum   between @VanVervalDatum and @TotVervalDatum                    // Alleen OSPs van de range Vervaldata
   and (
        (@MetCreditNotas = 1 and IsCreditNota = 1 and TeIncBedrag <> 0) or
        (@MetTeveelBetalingen = 1 and IsTeveelBetaling = 1) or
        // Als het geen CreditNota of vooruibetaling is, dan moet TeIncasseren groter dan nul zijn en de factuur op Automatische Incasso staan
        (     (IsCreditNota = 0)
          and (IsTeveelBetaling = 0)
          and (OspSoortFactuur  = 3)    // Alleen OSPs die soort *Via incasso* hebben
        )
       )
   and (   (@MetIncDatum    = 1 and OspIncDatum between @VanIncDatum and @TotIncDatum) // Alleen in de range IncassoDatum
        or (OspIncDatum is null)
       )
   and
     //Alleen als Openstaande bedrag <> 0!
     (OspFactuurBedragDefinitief + (@MetVoorlopigePost * OspFactuurBedragVoorlopig) -
      OspBetaaldBedragDefinitief - OspBetaaldBedragVoorlopig -
      OspBedragOnderwegInValuta) <> 0
  order by
   OspRksGid,
   OspFactuurNummer_Lengte,
   OspFactuurNummer;

//ACW 29-06-2016 defect #49131: Facturen van soort Incasso NIET individueel valideren op bedrag, zodat die toch kunnen worden verrekend
//  // *** Controle: bedrag > 0 voor soorten via autom. incasso
//    call trace('Controle: Bedrag > 0 voor factuursoort=Autom.incasso');
//  update tabIncassoVoorstelCreate
//         inner join tabOpenstaandePost on OspGid = IvcOspGid
//  set    IvcOverslaan = IvcOverslaan + 'L'
//  where
//         IvcUniekID = @SessieID
//      and OspSoortFactuur  = 3
//      and IvcTeIncBedrag <= 0;


  // *** Controle: bedrag > 0 voor soorten via autom. incasso
  //call trace('Controle: Aantal incassopogingen niet verbruikt');
  update tabIncassoVoorstelCreate
         inner join tabOpenstaandePost on OspGid = IvcOspGid
  set    IvcOverslaan = IvcOverslaan + 'M'
  where
         IvcUniekID = @SessieID
     and OspIncPogingenOver <= 0;



  // *** Controle: bedrag > 0 voor soorten via autom. incasso
  //call trace('Controle: Incassodatum niet gevuld');
  update tabIncassoVoorstelCreate
         inner join tabOpenstaandePost on OspGid = IvcOspGid
  set    IvcOverslaan = IvcOverslaan + 'N'
  where
         IvcUniekID = @SessieID
     and @ZonderIncDatum = 0
     and OspIncDatum is null
     and IvcIsCreditNota = 0;

  // *** Controle: Blokkade
  //call trace('Controle: Blokkade');
  update tabIncassoVoorstelCreate
         inner join tabOpenstaandePost on OspGid = IvcOspGid
  set    IvcOverslaan = IvcOverslaan + 'A'
  where
         IvcUniekID = @SessieID
     and OspIsGeblokkeerd = 1;

  // *** Controle: Valuta
  //call trace('Controle: Valuta');
  update tabIncassoVoorstelCreate
         inner join tabOpenstaandePost on OspGid = IvcOspGid
  set    IvcOverslaan = IvcOverslaan + 'B'
  where
         IvcUniekID = @SessieID
     and OspValNummer  <> @@EuroValutaNummer;

  // *** Controle: Bankrekening
  if @PostenZonderGeldigeBankrekening = 0 then
    //call trace('Controle: Bankrekening');
    update tabIncassoVoorstelCreate
    set    IvcOverslaan = IvcOverslaan + 'C'
    from   tabNawRekening
    where  IvcUniekID = @SessieID
     and  (NawRekGid = IvcNawRekGid)
     and  (IvcNawRekGid is not null)  // Als een rekening is gevonden, dan moet die wel voldoen!!
     and  (1 <> if @MetNietGeldigeMachtiging = -1 then
                 //Clieop alleen Nederlandse rekeningen
                 IsBankrekeningNederlands(NawRekBankRekeningInvoer, (select LndIso2 from tabLand where LndGid = NawRekBankLndGid))
               else
                 //PAIN alleen IBAN-rekeningen
                 IsValidIBAN(NawRekBankRekeningInvoer)
               endif
          )
  end if;

  // Geen CreditNotas die niet gefiatteerd zijn en geen credit notas als geen recht
  if @HeeftRechtdopb = 0 then
    //call trace('Controle: Fiattering creditnotas');
    update tabIncassoVoorstelCreate
    set    IvcOverslaan = IvcOverslaan + 'D'
    where
           IvcUniekID = @SessieID
      and (IvcIsCreditNota = 1 or IvcIsTeveelBetaling = 1)
      and (IvcIsGefiatteerd = 0 or @HeeftRechtdopb = 0);
  end if;


  // Testen of CreditNota, Teveelbetaling gebruikt wordt in andere incassovoorstel om te verrekenen.
  if @MetCreditNotas = 1 or @MetTeveelBetalingen = 1 then
    //call trace('Controle: Test of creditnota/teveelbetaling al in ander incassovoorstel');
//    update tabIncassoVoorstelCreate
//           inner join tabOpenstaandePost on OspGid = IvcOspGid
//      set IvcOverslaan = IvcOverslaan + 'H'
delete tabIncassoVoorstelCreate
from tabOpenstaandePost
      where IvcUniekID = @SessieID
      and OspGid = IvcOspGid
       and (IvcIsCreditNota = 1 or IvcIsTeveelBetaling = 1)
            and (exists( select first
                      1
                     from tabIncassoRegel
                     where
                          IncRglFactuurnummer_Lengte = OspFactuurNummer_Lengte
                      and IncRglFactuurNummer = OspFactuurNummer
                      and IncRglRksGid=IvcRksGid
                      and IncRglStatus = 0
                      and IncRglIsVerzameld=0
                     )
               or
              exists (select first
                    1
                   from tabIncassoRegelVerzameld
                   inner join tabIncassoRegel on IncRglGid = IrvIncRglGid
                   where
                        IrvFactuurnummer_Lengte = OspFactuurNummer_Lengte
                    and IrvFactuurnummer = OspFactuurNummer
                    and IncRglRksGid=IvcRksGid
                    and IncRglStatus = 0
                    and IncRglIsVerzameld=1
                  )
              );
  end if;

  // Vervolgens gaan testen of al die OSPs eigenlijk o.b.v. andere OSPs van dezelfde debiteur moeten worden geselecteerd ...
  //call trace('Test of OSPs obv andeer OSPs moeten worden geselecteerd');
  // Test of openstaande post moet worden overgeslagen als de debiteur minimaal 1 creditnota heeft in DIT boekjaar
  if @OverslaanAlsCreditNota <> 0 then
    //call trace('Controle: Overslaan als deb. creditnotas heeft');
    update tabIncassoVoorstelCreate
    set    IvcOverslaan = IvcOverslaan + 'E'
    where  IvcUniekID = @SessieID
       and exists(select first
                   1
                  from
                   tabOpenstaandePost
                  where
                       OspIsVervallen = 0
                   and OspBjGid = @@BjGid
                   and OspRksGid = IvcRksGid
                   and (OspFactuurBedragDefinitief + (@MetVoorlopigePost * OspFactuurBedragVoorlopig  )) < 0
                  );
  end if;

  // Test of openstaande post moet worden overgeslagen als de debiteur minimaal 1 vooruitbetaling op een OSP heeft
  //call trace('Test op vooruitbetalingen');
  if @OverslaanAlsVooruitbetaling <> 0 then
    //call trace('Controle: Overslaan als deb. vooruitbetalingen heeft');
    update tabIncassoVoorstelCreate
    set    IvcOverslaan = IvcOverslaan + 'F'
    where  IvcUniekID = @SessieID
       and exists(select first
                   1
                  from
                   tabOpenstaandePost
                  where
                       OspIsVervallen = 0
                   and OspBjGid = @@BjGid
                   and OspRksGid = IvcRksGid
                   and OspFactuurBedragDefinitief + (@MetVoorlopigePost * OspFactuurBedragVoorlopig) = 0
                 );
  end if;

  // Testen of openstaande post opgenomen in betalingsvoorstel
  //call trace('Controle: Test OSP al in betalingsvoorstel');
  update  tabIncassoVoorstelCreate
          inner join tabOpenstaandePost on OspGid = IvcOspGid
    set   IvcOverslaan = IvcOverslaan + 'G'
    where IvcUniekID = @SessieID
      and (exists( select first
                    1
                   from tabBetalingRegel
                   where
                        BetRglFactuurnummer_Lengte = OspFactuurNummer_Lengte
                    and BetRglFactuurNummer = OspFactuurNummer
                    and BetRglRksGid=IvcRksGid
                    and BetRglStatus = 0
                    and BetRglIsVerzameld=0
          )
          or exists( select first
                    1
                   from tabBetalingVerzameld
                   inner join tabBetalingRegel on BetRglGid = BetVerzBetRglGid
                   where
                        BetVerzFactuurnummer_Lengte = OspFactuurNummer_Lengte
                    and BetVerzFactuurnummer = OspFactuurNummer
                    and BetRglRksGid=IvcRksGid
                    and BetRglStatus = 0
                    and BetRglIsVerzameld=1
                )
              );

  //Machtigingen opzoeken en eraan knopen; indien geen geldige machtiging, dan wellicht niet opnemen
  //call trace('Machtigingen lus');
  if @MetNietGeldigeMachtiging <> -1 then
      //call trace('Controle: Geldige machtigingen');
    for @Cursor AS CURSOR_OSPmachtigingen CURSOR FOR
      select IvcGid           @IvcGid,
             IvcIcmReferentie @IvcIcmReferentie,
             OspIncDatum      @OspIncDatum,
             IvcNawGid        @IvcNawGid,
             IvcNawRekGid     @IvcNawRekGid,
             IvcIncDatum      @IvcIncDatum,
             IvcTeIncBedrag   @IvcTeIncBedrag
      from   tabIncassoVoorstelCreate inner join tabOpenstaandePost on (OspGid = IvcOspGid)
      where  IvcUniekID = @SessieID
      order by IvcOspGid
    for READ ONLY DO
      if @IvcIcmReferentie = '' then
        // Nog geen geldige machtiging gevonden, DUS alsnog een GELDIGE erbij zoeken
        set @Referentie = null;

        delete from tmpGeldigeMachtigingen;

        insert into tmpGeldigeMachtigingen (tmpReferentie)
        select icmReferentie into @Referentie
        from tabIncassoMachtiging
        where  (icmNawRekGid = @IvcNawRekGid)                                                        // Machtiging moet van de juiste rekening zijn
           and (isnull(@IvcIncDatum, now()) >= icmDatumOndertekening)                                // Incassodatum NA ondertekening
           and (isnull(@IvcIncDatum, now()) <= isnull(icmLaatsteIncassoDatum, @IvcIncDatum, now()))  // Incassodatum op of voor laatste incassodatum
           and (icmMaximumBedrag = 0 or (icmMaximumBedrag >= @IvcTeIncBedrag))                       // Max.bedrag is optioneel!
           and (icmVervallen = 0)                                                                   // Machtiging NIET vervallen
           and (icmBevoegdheid = 0 /*doorlopend*/ or (    not exists(select first 1 from tabIncassoMachtigingGebruikt where imgicmGid = icmGid)
                                                      and not exists(select first 1 from tabIncassoVoorstelCreate tmpOspBinnen where tmpOspBinnen.IvcUniekID = @SessieID and tmpOspBinnen.IvcIcmReferentie = icmReferentie and tmpOspBinnen.IvcGid < @IvcGid)
                                                     ) // Doorlopend OF nog niet gebruikte 1-malige
               )
           and (icmIncassoSchema = @Incassoschema); // Zelfde incassoschema, CORE of B2B

        if (select Count(*) from tmpGeldigeMachtigingen) = 1 then
          select first tmpReferentie into @Referentie from tmpGeldigeMachtigingen;

          if @Referentie is not null then
            update tabIncassoVoorstelCreate
            set    IvcIcmReferentie = @Referentie
            where IvcGid = @IvcGid;
          end if;
        end if;
      else
        if @MetNietGeldigeMachtiging = 0 then
          //Er was al een machtiging, dus even controleren of die wel geldig is; zoniet, dan eruit knikkeren!
          if not exists(select first 1 from tabIncassoMachtiging
                                       where  (icmReferentie = @IvcIcmReferentie)                                                   // Alleen de gevonden machtiging controleren
                                          and (icmNawRekGid = @IvcNawRekGid)                                                        // Machtiging moet van de juiste rekening zijn
                                          and (isnull(@IvcIncDatum, now()) >= icmDatumOndertekening)                                // Incassodatum NA ondertekening
                                          and (isnull(@IvcIncDatum, now()) <= isnull(icmLaatsteIncassoDatum, @IvcIncDatum, now()))  // Incassodatum NA ondertekening
                                          and ((icmMaximumBedrag = 0) or (icmMaximumBedrag >= @IvcTeIncBedrag))
                                          and (icmVervallen = 0)                                                     // Machtiging NIET vervallen
                                          and (icmBevoegdheid = 0 /*doorlopend*/ or (    not exists(select first 1 from tabIncassoMachtigingGebruikt where imgicmGid = icmGid) // Doorlopend OF nog niet gebruikte 1-malige
                                                                                     and not exists(select first 1 from tabIncassoVoorstelCreate tmpOspBinnen where tmpOspBinnen.IvcUniekID = @SessieID and tmpOspBinnen.IvcIcmReferentie = icmReferentie and tmpOspBinnen.IvcGid < @IvcGid)
                                                                                    ) // Doorlopend OF nog niet gebruikte 1-malige
                                              )
                                          and (icmIncassoSchema = @Incassoschema) // Zelfde incassoschema, CORE of B2B
                       ) then
            update tabIncassoVoorstelCreate
            set    IvcOverslaan = IvcOverslaan + 'I'
            where IvcGid = @IvcGid;
          end if;
        end if;
      end if;
    end for;

    //Alles zonder machtiging wellicht ook NIET terug geven
    if @MetNietGeldigeMachtiging = 0 then
      update tabIncassoVoorstelCreate set IvcOverslaan = IvcOverslaan + 'I'
      where  IvcUniekID = @SessieID
         and isnull(IvcIcmReferentie, '') = '';
    end if;
  end if; //if @OverslaanAlsVooruitbetaling <> 0 then


  // Alleen die OSPs teruggeven als de gevonden machtiging overeenkomt qua incassoschema
  // Als ze dus geen machtiging hebben, dan zal het wel goed zijn
  // Echter, wel een machtiging ingevuld, dan i.i.g. altijd gelijk aan incassoschema van voorstel, zelfs als ook met niet-geldige machtigingen wordt opgenomen
    //call trace('Controle: Machtiging van juiste incassoschema');
  update tabIncassoVoorstelCreate
  set    IvcOverslaan = IvcOverslaan + 'J'
  where  IvcUniekID = @SessieID
     and isnull(IvcIcmReferentie, '') <> ''
     and isnull((select first icmIncassoSchema from tabIncassoMachtiging where icmReferentie = IvcIcmReferentie), -1) <> @Incassoschema;


  // A.g.v. de mogelijkheid om credit-notas en teveelbetalingen te verrekenen, mag TeIncasserenBedrag negatief zijn per regel.
  // Maar per verzameling Debiteur, Bankrekening en MachtingsRef moet het wel positief zijn.
  if @MetCreditNotas = 1 or @MetTeveelBetalingen = 1 then
      //call trace('Controle: Verrekenen creditnotas en teveelbetalingen in verzameling');
    update tabIncassoVoorstelCreate
    set IvcOverslaan = IvcOverslaan + 'K'
    from  tabIncassoVoorstelCreate tmpOsp1
    where  IvcUniekID = @SessieID
      and ( select Sum (tmpOsp2.IvcTeIncBedrag) from tabIncassoVoorstelCreate as tmpOsp2
                      where
                        tmpOsp2.IvcUniekID = @SessieID and
                        tmpOsp1.IvcRksGid = tmpOsp2.IvcRksGid and
                        IsNull(tmpOsp1.IvcNawRekGid, -1)  = IsNull(tmpOsp2.IvcNawRekGid, -1) and
                        tmpOsp1.IvcIcmReferentie = tmpOsp2.IvcIcmReferentie and
                        tmpOsp2.IvcOverslaan = ''
                      group by
                        tmpOsp2.IvcRksGid,
                        tmpOsp2.IvcNawRekGid,
                        tmpOsp2.IvcIcmReferentie
              ) <= 0;
  end if;

  // ACW 09-12-2016 Defects 50477 en 50478: Als bedrag precies 0, dan nooit opnemen
  update tabIncassoVoorstelCreate
  set IvcOverslaan = IvcOverslaan + 'K'
  from  tabIncassoVoorstelCreate tmpOsp1
  where  IvcUniekID = @SessieID
     and IvcTeIncBedrag = 0
     and IvcOverslaan = '';


  // ACW Defect 56353: Voorkom dat er meldingen komen op niet-incassofacturen
  // Verwijder alle OSPs die niet zelf een incassofactuur zijn maar wel op de meldingen-nominatie staat
  // Dat voorkomt meldingen op facturen die niet zelf geincasseerd zouden (kunnen) worden
    delete tabIncassoVoorstelCreate
    from    tabOpenstaandePost
    where  IvcUniekID = @SessieID
       and OspGid = IvcOspGid
       and IvcOverslaan <> '' /*Met melding*/
       and OspSoortFactuur <> 3 /*Incassofactuur*/;

  // Te incasseren bedrag is 0 en osp wordt overgeslagen, dan komt dat doordat er niks te verrekenen is.
  // Daarom daar geen melding over geven
    delete tabIncassoVoorstelCreate
    from   tabIncassoVoorstelCreate tmpOsp1
    where  IvcUniekID = @SessieID
      and IvcTeIncBedrag = 0
      and IvcOverslaan like '%K%'; // Melding bedrag <= 0

  //call traceEind(@@ErrorTextProcedure);

  // Teruggeven van alle niet-overgeslagen OSPs
      //call trace('Resultaat teruggeven');
  select
    0 Overslaan,
    IvcRksGid RksGid,
    OspGid,
    OspFactuurNummer,
    IvcNawRekGid NawRekGid,
    IvcTeIncBedrag      TeIncBedrag,
    IvcIncDatum         IncassoDatumOpRegel,
    OspBetalingskenmerk Betalingskenmerk,
    IvcIcmReferentie icmReferentie,
    // Omschrijving
    if @OmsOvernemenOms <> 0 then
     OspOms +
     isnull(if @OmsOvernemenRef <> 0 and OspOms <> '''' then char(13) + char(10) endif,'')
    else
     ''
    endif +
    if @OmsOvernemenRef <> 0 then
     @OmsTekstRef + ' ' +
     (select RksInvoer from tabRekeningschema where RksGid = IvcRksGid) + ' ' + trim(OspFactuurNummer)
    else
      ''
    endif Omschrijving,
    IvcIsGefiatteerd           Gefiatteerd,
    IvcFiatteringGewijzigdDoor FiatteringGewijzigdDoor,
    IvcFiatteringGewijzigdOp   FiatteringGewijzigdOp

   from  tabIncassoVoorstelCreate
         inner join tabOpenstaandePost on (OspGid = IvcOspGid)
   where IvcUniekID = @SessieID
     and IvcOverslaan = ''

  UNION ALL

  // en per RksGid 1 record als de OSPs zijn overgeslagen
  select DISTINCT
    1         Overslaan,
    IvcRksGid RksGid,
    null      OspGid,
    null      OspFactuurNummer,
    null      NawRekGid,
    0         TeIncBedrag,
    null      IncassoDatumOpRegel,
    ''        Betalingskenmerk,
    ''        icmReferentie,
    ''        Omschrijving,
    1         Gefiatteerd,
    ''        FiatteringGewijzigdDoor,
    null      FiatteringGewijzigdOp
  from  tabIncassoVoorstelCreate
  where  IvcUniekID = @SessieID
     and IvcOverslaan <> '';
end;

//call rapIncassoOSPnaarVoorstel( 100, 1, 1, 1, 0, 0, 1, 1, 'Onze ref.', null, '12000000', '12999999', '', '9999999999', '2000-01-01', '2013-12-31', '2000-01-01', '2013-12-31', '2000-01-01', '2013-12-31', 0,0,0, 1, 1, 0)


create or replace procedure rapJournaalBoekingsGang(
in @Rapport                         integer, // Rapportkeuze: 0=Journaal, 1=boekingsgangen
in @SoortBoeking                    smallint, // 0=definitief, 1=voorlopig, 2=beide
in @BjGid                           integer,
in @Selectie                        integer, // Selecteren op: 1=boekingsgang, 2=aanmaakdatum, 3=bronomschrijving
in @VanBoekGangNummer               integer,
in @TotBoekGangNummer               integer,
in @VanBoekGangAanmaakDatum         date,
in @TotBoekGangAanmaakDatum         date,
in @VanBoekGangOmschrijving         nchar(40),
in @TotBoekGangOmschrijving         nchar(40),
in @VanRegelNr                      integer,
in @TotRegelNr                      integer,
in @VanPerNr                        integer,
in @TotPerNr                        integer,
in @OrderBy                         integer, // Sorteren op: 0=boekingsgang, 1=aanmaakdatum, 2=bronomschrijving
in @Ascending                       integer)

result (
  tmpBoekGangGID                 integer,
  BoekGangNummer                 integer,
  BronOms                        nchar(40),
  BoekGangAanmaakDatum           date,
  BoekGangGebruikersNaam         nchar(40),
  DatumDefinitief                date,
  GebruikersNaamDefinitief       nchar(40),
  IsBoekGangDefinitief           smallint,
  DefValTegRekNummer             integer,
  DefValTegRekCode               nchar(3), // Default-valuta van tegenrekening van eerste dagboek van boekingsgang (=valuta van dagboek)
  AantalPosten                   integer,
  TotAantalRegels                integer,
  tmpEersteDgbCode               nchar(10),
  tmpEersteRegelNummer           integer)

begin
  declare local temporary table tmp(
    tmpBoekgangGid       integer,
    tmpEersteDgbCode     nchar(10),
    tmpEersteRegelNummer integer) on commit preserve rows;

  //call TraceBegin('rapJournaalBoekingsGang (@Rapport='+string(@Rapport)+', @SoortBoeking='+string(@SoortBoeking)+', @BjGid='+string(@BjGid)+', @Selectie='+string(@Selectie)+', @VanBoekGangNummer='+string(@VanBoekGangNummer)+', @TotBoekGangNummer='+string(@TotBoekGangNummer)+', ...');
  //call Trace('..., @VanBoekGangAanmaakDatum='+string(@VanBoekGangAanmaakDatum)+', @TotBoekGangAanmaakDatum='+string(@TotBoekGangAanmaakDatum)+', @VanBoekGangOmschrijving='+string(@VanBoekGangOmschrijving)+', @TotBoekGangOmschrijving='+string(@TotBoekGangOmschrijving)+', ...');
  //call Trace('..., @VanRegelNr='+string(@VanRegelNr)+', @TotRegelNr='+string(@TotRegelNr)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @OrderBy='+string(@OrderBy)+', @Ascending='+string(@Ascending)+')');

  insert into tmp(tmpBoekgangGid, tmpEersteDgbCode, tmpEersteRegelNummer)
  select distinct
    BoekgangGid,
    (select first JpDgbCode from tabjournaalpost where JpBoekgangGid=BoekgangGid order by JpNummer),
    if IsBoekgangDefinitief = 1 then (select min(RegelNummer) from tabJournaalPost inner join tabJournaalRegel on (JrJpGid = JpGid) where jpBoekgangGid=BoekgangGid) endif
  from
    tabBoekingsgang
    inner join tabJournaalpost  on (JpBoekgangGid = BoekgangGid)
    inner join tabJournaalregel on (JrJpGid = JpGid)
  where
    // Boekingsgang/Journaalpost/Journaalregel in juiste boekjaar
    BoekgangBjGid = @BjGid and
    JpBjGid = @BjGid and
    JrBjGid = @BjGid and
    // Definitief, voorlopig of beide
    ( (@SoortBoeking = 0 and IsBoekGangDefinitief = 1) or
      (@SoortBoeking = 1 and IsBoekGangDefinitief = 0) or
      (@SoortBoeking = 2)
    ) and
    ( (@Rapport = 0 and
       // Alleen journaalposten waarin de geselecteerde journaalregelnummers zitten
       ( (@SoortBoeking = 0 and RegelNummer between @VanRegelNr and @TotRegelNr ) or
         (@SoortBoeking = 1) or
         ((@SoortBoeking = 2 and RegelNummer between @VanRegelNr and @TotRegelNr) or IsBoekGangDefinitief = 0)
       ) and
       // Alleen de journaalposten die in de geselecteerde perioderange zitten
       JrPerNr between @VanPerNr and @TotPerNr
      ) or
      (@Rapport = 1 and
       // Selecteren van boekingsgangen op basis van selectie in voorloopscherm
       ( (@Selectie = 1 and BoekGangNummer       between @VanBoekGangNummer       and @TotBoekGangNummer) or
         (@Selectie = 2 and BoekGangAanmaakDatum between @VanBoekGangAanmaakDatum and @TotBoekGangAanmaakDatum) or
         (@Selectie = 3 and BronOms              between @VanBoekGangOmschrijving and @TotBoekGangOmschrijving)
       )
      )
    );

  //call TraceEind('rapJournaalBoekingsGang');

  select
    tmpBoekGangGid,
    BoekGangNummer,
    BronOms,
    BoekGangAanmaakDatum,
    BoekGangGebruikersNaam,
    DatumDefinitief,
    GebruikersNaamDefinitief,
    IsBoekGangDefinitief,
    if @Rapport = 1 then (select ValNummer from tabValuta inner join tabRekeningschema on (RksValNummer = ValNummer) inner join tabDagboek on (DgbTegenRksGid = RksGid) inner join tabJournaalpost on (JpDgbGid = DgbGid) where JpNummer = (select min(JpNummer) from tabJournaalpost where JpBoekgangGid = tmpBoekgangGid) and JpBoekgangGid = tmpBoekgangGid) endif DefValTegRekNummer,
    if @Rapport = 1 then (select ValCode from tabValuta where ValNummer = DefValTegRekNummer) endif DefValTegRekCode,
    (select count(*) from tabJournaalPost where JpBoekGangGid = tmpBoekGangGid) AantalPosten,
    (select count(*) from tabJournaalPost inner join tabJournaalRegel on (JrJpGid = JpGid) where JpBoekGangGID = tmpBoekGangGid) TotAantalRegels,
    tmpEersteDgbCode,
    tmpEersteRegelNummer
  from
    tmp
    inner join tabBoekingsGang on (BoekgangGid = tmpBoekgangGid)
  order by
    // Eerst definitieve boekingsgangen, dan voorlopige boekingsgangen
    if @Ascending = 0 then IsBoekGangDefinitief endif,
    if @Ascending = 1 then IsBoekGangDefinitief endif desc,
    // Sorteren van alle boekingsgangen op basis van het geselecteerde sorteerveld
    if @Ascending = 0 and @OrderBy = 0 then BoekgangNummer endif desc,
    if @Ascending = 1 and @OrderBy = 0 then BoekgangNummer endif,
    if @Ascending = 0 and @OrderBy = 1 then BoekgangAanmaakDatum endif desc,
    if @Ascending = 1 and @OrderBy = 1 then BoekgangAanmaakDatum endif,
    if @Ascending = 0 and @OrderBy = 2 then BronOms endif desc,
    if @Ascending = 1 and @OrderBy = 2 then BronOms endif,
    // Indien rapport = 0 dan altijd sorteren op eerste regelnummer van boekingsgang
    if @OrderBy = 3 then tmpEersteRegelNummer endif,
    // Altijd nasorteren op basis van het boekingsgangnummer
    if @Ascending = 0 then BoekgangNummer endif desc,
    if @Ascending = 1 then BoekgangNummer endif;


end;

// call rapJournaalBoekingsGang(1, 2, 1, 1, 470, 490, '2000-01-01', '2000-12-31', '', 'ZZZ', 0, 30, 0, 12, 0, 1);


create or replace procedure rapJournaalJournaalPost(
in @BoekGangGid                     integer,
in @Rapport                         integer, // Rapportkeuze: 0=Journaal, 1=boekingsgangen
in @SoortBoeking                    smallint, // 0=definitief, 1=voorlopig, 2=beide
in @VanRegelNr                      integer,
in @TotRegelNr                      integer,
in @VanPerNr                        integer,
in @TotPerNr                        integer)

result (
  JpGid             integer,
  JpNummer          integer,
  OmsJournaalPost   nchar(40),
  BoekstukNummer    nchar(10),
  BoekDatum         date,
  JpDgbCode         nchar(10),
  OmsDagboek        nchar(40),
  RegelInJournaal   integer,
  AantalRegels      integer)

begin
  //call TraceBegin('rapJournaalJournaalPost (@BoekGangGid='+string(@BoekGangGid)+', @Rapport='+string(@Rapport)+', @SoortBoeking='+string(@SoortBoeking)+', @VanRegelNr='+string(@VanRegelNr)+', @TotRegelNr='+string(@TotRegelNr)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+')');

  //call TraceEind('rapJournaalJournaalPost');

  select
    JpGid,
    JpNummer,
    OmsJournaalPost,
    string(BoekstukNummer),
    BoekDatum,
    JpDgbCode,
    (select OmsDagboek from tabDagboek where JpDgbGid = DgbGid) OmsDagboek,
    min(RegelNummer) RegelInJournaal,
    count(*) AantalRegels
  from
    tabJournaalPost inner join tabJournaalRegel on (JrJpGid = JpGid)
  where
    JpBoekGangGID = @BoekGangGID and
    ( (@Rapport = 0 and
       // Alleen journaalposten waarin de geselecteerde journaalregelnummers zitten
       ( (@SoortBoeking = 0 and RegelNummer between @VanRegelNr and @TotRegelNr) or
         (@SoortBoeking = 1) or
         (@SoortBoeking = 2 and (RegelNummer between @VanRegelNr and @TotRegelNr or RegelNummer is null))
       ) and
       // Alleen de journaalposten die in de geselecteerde perioderange zitten
       JrPerNr between @VanPerNr and @TotPerNr
      ) or
      (@Rapport = 1)
    )
  group by
    JpGid,
    JpNummer,
    OmsJournaalPost,
    JpDgbGid,
    BoekstukNummer,
    BoekDatum,
    JpDgbCode,
    OmsDagboek
  order by
    JpNummer asc;


end;

// call rapJournaalJournaalPost(813, 1, 2, 0, 30, 0, 12);


create or replace procedure rapJournaalJournaalRegel(
in @JpGid                           integer,
in @Rapport                         integer,       // Rapportkeuze: 0=Journaal, 1=boekingsgangen
in @SoortBoeking                    smallint,      // 0=definitief, 1=voorlopig, 2=beide
in @BjGid                           integer,
in @DefValTegRekNummer              integer,       // Default-valuta van tegenrekening van eerste dagboek van boekingsgang
in @VanRegelNr                      integer,
in @TotRegelNr                      integer,
in @VanPerNr                        integer,
in @TotPerNr                        integer,
in @BedragenAfdrukkenIn             integer,       // 0=Default-valuta van tegenrekening van eerste dagboek van boekingsgang, 1=boekvaluta, 2=basisvaluta, 3=extra valuta
in @BedragenAfdrukkenExtraValNummer integer,       // Indien gevuld, ook bedragen afdrukken in de extra ingegeven valuta.
in @TotalenAfdrukkenIn              integer,       // 0=Default-valuta van tegenrekening van eerste dagboek van boekingsgang, 2=basisvaluta, 3=extra valuta
in @TotalenAfdrukkenExtraValNummer  integer)       // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta.

result (
  RegelNummer                    integer,
  StukVolgnr                     integer,
  BoekStukVolgNummer             nchar(14),
  JrBoekdatum                    date,
  JpPerNr                        integer,
  OmsJournaalRegel               nchar(40),
  JrReferentie                   nchar(40),
  RglRksZoekCode                 nchar(10),
  RglRksInvoer                   nchar(28),
  RglRksNaam                     nchar(40),
  IsCreditBoeking                smallint,
  RglBoekValNummer               integer,
  RglBoekValCode                 nchar(3),
  AfdrukValNummerBedragen        integer,       // Valuta waarin de bedragen dienen te worden afgedrukt
  AfdrukValCodeBedragen          nchar(3),
  JrBoekValBedrag                numeric(15,2),
  BoekValBoekingBedragD          numeric(15,2),
  BoekValBoekingBedragC          numeric(15,2),
  BoekValBoekingSaldo            numeric(15,2),
  BoekValRegelTotaalD            numeric(15,2),
  BoekValRegelTotaalC            numeric(15,2),
  BoekValRegelSaldo              numeric(15,2),
  JrBasisValBedrag               numeric(15,2),
  BasisValBoekingBedragD         numeric(15,2),
  BasisValBoekingBedragC         numeric(15,2),
  BasisValBoekingSaldo           numeric(15,2),
  BasisValRegelTotaalD           numeric(15,2),
  BasisValRegelTotaalC           numeric(15,2),
  BasisValRegelSaldo             numeric(15,2),
  JrFactuurdatum                 date,
  JrVervalDatum                  date,
  JrBetalingsKenmerk             nchar(24),
  HulpRekSoort                   smallint,
  HulpRekeningZoekCode           nchar(10),
  HulpRekeningInvoer             nchar(28),
  HulpRekeningNaam               nchar(40),
  HulpRekBtwCode                 integer,
  HulpRekIsCreditBoeking         smallint,
  HulpRekBoekValNummer           integer,
  HulpRekBoekValCode             nchar(3),
  HulpRekAfdrukValNummerBedragen integer,
  HulpRekAfdrukValCodeBedragen   nchar(3),
  HulpRekBoekValBedrag           numeric(15,2),
  HulpRekBasisValBedrag          numeric(15,2),
  AfdrukValBoekingCumBedragD     numeric(15,2),
  AfdrukValBoekingCumBedragC     numeric(15,2),
  AfdrukValBoekingCumSaldo       numeric(15,2),
  AfdrukValRegelCumSaldo         numeric(15,2),
  Aantal                         numeric(15,2),
  /*tbv. projecten*/
  ProjCode                       nchar(10),
  ProjOmschr                     nchar(40),
  PbZoekCode                     nchar(40),
  PbOmschr                       nchar(80),
  ArtCode                        nchar(20),
  ArtOms                         nchar(40),
  pbrSelectieCodes               long nvarchar)

begin
  //tijdelijke tabel aanmaken
  declare local temporary table tmpExtraVelden(
    tmpGid                        integer default autoincrement,
    tmpJrGid                      integer,
    tmpBoekValKoers               numeric(15,6),
    tmpHulpRekBoekValNummer       integer,
    tmpHulpRekIsCredit            smallint,
    tmpHulpRekBasisValBedrag      numeric(15,2),
    tmpHulpRekBoekValBedrag       numeric(15,2),
    tmpHulpRekBedragInJrValNummer numeric(15,2),
    tmpBasisValBoekingBedragD     numeric(15,2),
    tmpBasisValBoekingBedragC     numeric(15,2),
    tmpBasisValBoekingSaldo       numeric(15,2),
    tmpBasisValRegelTotaalD       numeric(15,2),
    tmpBasisValRegelTotaalC       numeric(15,2),
    tmpBasisValRegelSaldo         numeric(15,2),
    tmpBoekValBoekingBedragD      numeric(15,2),
    tmpBoekValBoekingBedragC      numeric(15,2),
    tmpBoekValBoekingSaldo        numeric(15,2),
    tmpBoekValRegelTotaalD        numeric(15,2),
    tmpBoekValRegelTotaalC        numeric(15,2),
    tmpBoekValRegelSaldo          numeric(15,2),
    tmpAfdrukValBoekingCumBedragD numeric(15,2),
    tmpAfdrukValBoekingCumBedragC numeric(15,2),
    tmpAfdrukValBoekingCumSaldo   numeric(15,2),
    tmpAfdrukValRegelCumSaldo     numeric(15,2)
    ) on commit preserve rows;

  // Voorkomen van afrondingsverschillen en tegelijkertijd de valutacodes ophalen
  declare @NumDeciBasisVal               integer;
  declare @NumDeciDefValTegRek           integer;
  declare @DefValTegRekCode              nchar(3);
  declare @BedragenAfdrukkenExtraValCode nchar(3);
  declare @NumDeciExtraValTotalen        integer;

  //call TraceBegin('rapJournaalJournaalRegel (@JpGid='+string(@JpGid)+', @Rapport='+string(@Rapport)+', @SoortBoeking='+string(@SoortBoeking)+', @BjGid='+string(@BjGid)+', DefValTegRekNummer='+string(@DefValTegRekNummer)+', @VanRegelNr='+string(@VanRegelNr)+', @TotRegelNr='+string(@TotRegelNr)+', ...');
  //call Trace('..., @BedragenAfdrukkenIn='+string(@BedragenAfdrukkenIn)+', @BedragenAfdrukkenExtraValNummer='+string(@BedragenAfdrukkenExtraValNummer)+', @TotalenAfdrukkenIn='+string(@TotalenAfdrukkenIn)+', @TotalenAfdrukkenExtraValNummer='+string(@TotalenAfdrukkenExtraValNummer)+')');

  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;
  if @Rapport = 1 then // Alleen gegevens ophalen indien er gekozen is voor het rapport voor boekingsgangen. Binnen het journaal is geen sprake van de default valuta van de tegenrekening
    select ValCode, if DecimalenBoeking <> 0 then 2 else 0 endif into @DefValTegRekCode, @NumDeciDefValTegRek from tabValuta where ValNummer = @DefValTegRekNummer;
  end if;
  if @BedragenAfdrukkenIn = 3 then
    select ValCode into @BedragenAfdrukkenExtraValCode from tabValuta where ValNummer = @BedragenAfdrukkenExtraValNummer;
  end if;
  if @TotalenAfdrukkenIn = 3 then // Alleen gegevens ophalen indien ook daadwerkelijk een extra valuta is ingevoerd
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen  from tabValuta where ValNummer = @TotalenAfdrukkenExtraValNummer;
  end if;

  // Bedragen alleen afronden voor zover nodig. Groot gedeelte van de afronding vindt namelijk al in de dm zelf plaats (via ValutaInField)
  insert into tmpExtraVelden(tmpJrGid,
                             tmpBoekValKoers,
                             tmpHulpRekBoekValNummer,       tmpHulpRekIsCredit,
                             tmpHulpRekBasisValBedrag,      tmpHulpRekBoekValBedrag,       tmpHulpRekBedragInJrValNummer,
                             tmpBasisValBoekingBedragD,     tmpBasisValBoekingBedragC,     tmpBasisValBoekingSaldo,       tmpBasisValRegelTotaalD, tmpBasisValRegelTotaalC, tmpBasisValRegelSaldo,
                             tmpBoekValBoekingBedragD,      tmpBoekValBoekingBedragC,      tmpBoekValBoekingSaldo,        tmpBoekValRegelTotaalD,  tmpBoekValRegelTotaalC,  tmpBoekValRegelSaldo,
                             tmpAfdrukValBoekingCumBedragD, tmpAfdrukValBoekingCumBedragC,
                             tmpAfdrukValBoekingCumSaldo,   tmpAfdrukValRegelCumSaldo
                            )
  select JrGid,

         // Voor de snelheid het resultaat van de koersomrekeningen in velden zetten
         if JrValNummer <> @@BasisValutaNummer then KoersTovBasisValuta(JrBjGid, JrPernr, JrValNummer) else 1 endif tmpBoekValKoers,

         // Journaalposten die betrekking hebben op de automatische tegenboekingen op de hulprekeningen
         // (Dus de cjp-hulprekening, als hulprekening, tegenboeken)
         if SoortBoeking = 2 then JrValNummer                                                                   else HulpRekValNummer                                                                   endif tmpHulpRekBoekValNummer,
         if SoortBoeking = 2 then IsCreditBoeking                                                               else HulpRekIsCredit                                                                    endif tmpHulpRekIsCredit,
         if SoortBoeking = 2 then - round(JrBasisBedrag, @NumDeciBasisVal)                                      else round(HulpRekBasisBedrag, @NumDeciBasisVal)                                        endif tmpHulpRekBasisValBedrag,
         if SoortBoeking = 2 then - round(JrValutaBedrag, if Rek.DecimalenBoeking <> 0 then 2 else 0 endif)     else round(HulpRekValutaBedrag, if HulpRek.DecimalenBoeking <> 0 then 2 else 0 endif)   endif tmpHulpRekBoekValBedrag,       // In valuta waarin is geboekt op de hulprekening
         if SoortBoeking = 2 then - round(JrValutaBedrag, if Rek.DecimalenBoeking <> 0 then 2 else 0 endif)     else round(HulpRekBedragInJrValNummer,if Rek.DecimalenBoeking <> 0 then 2 else 0 endif) endif tmpHulpRekBedragInJrValNummer, // In valuta waarin is geboekt op de grootboekrekening

         // ---------- Basisvaluta ----------
         // Uitsplitsing van geboekt bedrag naar boekzijde
         if IsCreditBoeking = 0 then round(JrBasisBedrag, @NumDeciBasisVal) endif tmpBasisValBoekingBedragD,
         if IsCreditBoeking = 1 then round(JrBasisBedrag, @NumDeciBasisVal) endif tmpBasisValBoekingBedragC,
         JrBasisBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) tmpBasisValBoekingSaldo,
         // Uitsplitsing van regeltotaal (=geboekt bedrag + geboekt bedrag op de hulprekening) naar boekzijde
         if tmpHulpRekIsCredit is not null and tmpHulpRekIsCredit = 0 then isnull(tmpBasisValBoekingBedragD, 0) + tmpHulpRekBasisValBedrag else tmpBasisValBoekingBedragD endif tmpBasisValRegelTotaalD,
         if tmpHulpRekIsCredit is not null and tmpHulpRekIsCredit = 1 then isnull(tmpBasisValBoekingBedragC, 0) + tmpHulpRekBasisValBedrag else tmpBasisValBoekingBedragC endif tmpBasisValRegelTotaalC,
         isnull(tmpBasisValRegelTotaalD, 0) - isnull(tmpBasisValRegelTotaalC, 0) tmpBasisValRegelSaldo,

         // ---------- Boekvaluta ----------
         // Uitsplitsing van geboekt bedrag naar boekzijde
         if IsCreditBoeking = 0 then round(JrValutaBedrag, if Rek.DecimalenBoeking <> 0 then 2 else 0 endif) endif tmpBoekValBoekingBedragD,
         if IsCreditBoeking = 1 then round(JrValutaBedrag, if Rek.DecimalenBoeking <> 0 then 2 else 0 endif) endif tmpBoekValBoekingBedragC,
         JrValutaBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) tmpBoekValBoekingSaldo,
         // Uitsplitsing van regeltotaal (=geboekt bedrag + geboekt bedrag op de hulprekening) naar boekzijde
         if tmpHulpRekBoekValNummer is not null then
           if JrValNummer = tmpHulpRekBoekValNummer then
             if tmpHulpRekIsCredit is not null and tmpHulpRekIsCredit = 0 then isnull(tmpBoekValBoekingBedragD, 0) + tmpHulpRekBedragInJrValNummer else tmpBoekValBoekingBedragD endif
           else
             if tmpHulpRekIsCredit is not null and tmpHulpRekIsCredit = 0 then isnull(tmpBoekValBoekingBedragD, 0) + round((tmpHulpRekBasisValBedrag/tmpBoekValKoers), if Rek.DecimalenBoeking <> 0 then 2 else 0 endif)  else tmpBoekValBoekingBedragD endif
           endif
         else
           tmpBoekValBoekingBedragD
         endif tmpBoekValRegelTotaalD,
         if tmpHulpRekBoekValNummer is not null then
           if JrValNummer = tmpHulpRekBoekValNummer then
             if tmpHulpRekIsCredit is not null and tmpHulpRekIsCredit = 1 then isnull(tmpBoekValBoekingBedragC, 0) + tmpHulpRekBedragInJrValNummer else tmpBoekValBoekingBedragC endif
           else
             if tmpHulpRekIsCredit is not null and tmpHulpRekIsCredit = 1 then isnull(tmpBoekValBoekingBedragC, 0) + round((tmpHulpRekBasisValBedrag/tmpBoekValKoers), if Rek.DecimalenBoeking <> 0 then 2 else 0 endif) else tmpBoekValBoekingBedragC endif
           endif
         else
           tmpBoekValBoekingBedragC
         endif tmpBoekValRegelTotaalC,
         isnull(tmpBoekValRegelTotaalD, 0) - isnull(tmpBoekValRegelTotaalC, 0) tmpBoekValRegelSaldo,

         // ---------- Afdrukvaluta voor totalen ----------
         // Deze velden zijn nodig zodat de cumulatieven via het somcomponent enigzins corresponderen met de boekbedragen
         // Indien de valuta-instelling voor de bedragen gelijk is aan die voor de totalen dan kan het in de dm berekende veld (voor bedragen) worden genomen
         if not((@TotalenAfdrukkenIn <> 3 and @TotalenAfdrukkenIn = @BedragenAfdrukkenIn) or (@TotalenAfdrukkenIn = 3 and @BedragenAfdrukkenIn=3 and isnull(@TotalenAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) then
           case @TotalenAfdrukkenIn
             when 0 then if JrValNummer = @DefValTegRekNummer then tmpBoekValBoekingBedragD else round(tmpBasisValBoekingBedragD/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer), @NumDeciDefValTegRek) endif
             when 2 then tmpBasisValBoekingBedragD
             when 3 then if JrValNummer = @TotalenAfdrukkenExtraValNummer then tmpBoekValBoekingBedragD else round(tmpBasisValBoekingBedragD/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer), @NumDeciExtraValTotalen) endif
           end
         endif tmpAfdrukValBoekingCumBedragD,
         if not((@TotalenAfdrukkenIn <> 3 and @TotalenAfdrukkenIn = @BedragenAfdrukkenIn) or (@TotalenAfdrukkenIn = 3 and @BedragenAfdrukkenIn=3 and isnull(@TotalenAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) then
           case @TotalenAfdrukkenIn
             when 0 then if JrValNummer = @DefValTegRekNummer then tmpBoekValBoekingBedragC else round(tmpBasisValBoekingBedragC/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer), @NumDeciDefValTegRek) endif
             when 2 then tmpBasisValBoekingBedragC
             when 3 then if JrValNummer = @TotalenAfdrukkenExtraValNummer then tmpBoekValBoekingBedragC else round(tmpBasisValBoekingBedragC/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer), @NumDeciExtraValTotalen) endif
           end
         endif tmpAfdrukValBoekingCumBedragC,
         if not((@TotalenAfdrukkenIn <> 3 and @TotalenAfdrukkenIn = @BedragenAfdrukkenIn) or (@TotalenAfdrukkenIn = 3 and @BedragenAfdrukkenIn=3 and isnull(@TotalenAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) then
           isnull(tmpAfdrukValBoekingCumBedragD, 0) - isnull(tmpAfdrukValBoekingCumBedragC, 0)
         endif tmpAfdrukValBoekingCumSaldo,
         if not((@TotalenAfdrukkenIn <> 3 and @TotalenAfdrukkenIn = @BedragenAfdrukkenIn) or (@TotalenAfdrukkenIn = 3 and @BedragenAfdrukkenIn=3 and isnull(@TotalenAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) then
           case @TotalenAfdrukkenIn
             when 0 then
               if tmpHulpRekBoekValNummer is not null then
                 if JrValNummer = @DefValTegRekNummer and tmpHulpRekBoekValNummer = @DefValTegRekNummer then
                   tmpBoekValBoekingSaldo + tmpHulpRekBedragInJrValNummer * (if HulpRekIsCredit = 1 then -1 else 1 endif)
                 else if JrValNummer = @DefValTegRekNummer and tmpHulpRekBoekValNummer <> @DefValTegRekNummer then
                   tmpBoekValBoekingSaldo + round((tmpHulpRekBasisValBedrag/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer)), @NumDeciDefValTegRek) * (if HulpRekIsCredit = 1 then -1 else 1 endif)
                   else if JrValNummer <> @DefValTegRekNummer and tmpHulpRekBoekValNummer = @DefValTegRekNummer then
                     round(tmpBasisValBoekingSaldo/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer), @NumDeciDefValTegRek) + tmpHulpRekBoekValBedrag * (if HulpRekIsCredit = 1 then -1 else 1 endif)
                     else
                       round(tmpBasisValBoekingSaldo/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer), @NumDeciDefValTegRek) + round((tmpHulpRekBasisValBedrag/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer)), @NumDeciDefValTegRek) * (if HulpRekIsCredit = 1 then -1 else 1 endif)
                     endif
                   endif
                 endif
               else
                 if JrValNummer = @DefValTegRekNummer then
                   tmpBoekValBoekingSaldo
                 else
                   round(tmpBasisValBoekingSaldo/KoersTovBasisValuta(JrBjGid, JrPernr, @DefValTegRekNummer), @NumDeciDefValTegRek)
                 endif
               endif
             when 2 then tmpBasisValBoekingSaldo
             when 3 then
               if tmpHulpRekBoekValNummer is not null then
                 if JrValNummer = @TotalenAfdrukkenExtraValNummer and tmpHulpRekBoekValNummer = @TotalenAfdrukkenExtraValNummer then
                   tmpBoekValBoekingSaldo + tmpHulpRekBedragInJrValNummer * (if HulpRekIsCredit = 1 then -1 else 1 endif)
                 else if JrValNummer = @TotalenAfdrukkenExtraValNummer and tmpHulpRekBoekValNummer <> @TotalenAfdrukkenExtraValNummer then
                   tmpBoekValBoekingSaldo + round((tmpHulpRekBasisValBedrag/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer)), @NumDeciExtraValTotalen) * (if HulpRekIsCredit = 1 then -1 else 1 endif)
                   else if JrValNummer <> @TotalenAfdrukkenExtraValNummer and tmpHulpRekBoekValNummer = @TotalenAfdrukkenExtraValNummer then
                     round(tmpBasisValBoekingSaldo/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer), @NumDeciExtraValTotalen) + tmpHulpRekBoekValBedrag * (if HulpRekIsCredit = 1 then -1 else 1 endif)
                     else
                       round(tmpBasisValBoekingSaldo/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer), @NumDeciExtraValTotalen) + round((tmpHulpRekBasisValBedrag/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer)), @NumDeciExtraValTotalen) * (if HulpRekIsCredit = 1 then -1 else 1 endif)
                     endif
                   endif
                 endif
               else
                 if JrValNummer = @TotalenAfdrukkenExtraValNummer then
                   tmpBoekValBoekingSaldo
                 else
                   round(tmpBasisValBoekingSaldo/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer), @NumDeciExtraValTotalen)
                 endif
               endif
           end
         endif tmpAfdrukValRegelCumSaldo
    from
      tabJournaalPost
      inner join tabJournaalRegel on (JrJpGid = JpGid)
      inner join tabValuta Rek on (Rek.ValNummer = JrValNummer)
      left outer join (tabHulpRekening inner join tabValuta HulpRek on (HulpRek.ValNummer = HulpRekValNummer)) on (HulpRekJrGid = JrGid)
    where
      JpGid = @JpGid and
      (  (@Rapport = 0 and
          ( (@SoortBoeking = 0 and RegelNummer between @VanRegelNr and @TotRegelNr) or
            (@SoortBoeking = 1) or
            (@SoortBoeking = 2 and (RegelNummer between @VanRegelNr and @TotRegelNr or RegelNummer is null) )
          ) and
            JrPerNr between @VanPerNr and @TotPerNr
         ) or
         (@Rapport = 1)
      )
    order by
      RegelNummer,
      JrNummer;

  //call Trace('Stap 1');

  create index idx_tmpGid on tmpExtraVelden (tmpGid);

  //call TraceEind('rapJournaalJournaalRegel');

  select
    RegelNummer,
    StukVolgnr,
    string(JrBoekstukNummer) + '.' + right('000' + string(StukVolgNr), 3) BoekStukVolgNummer,
    JrBoekdatum,
    JrPernr,
    OmsJournaalRegel,
    JrReferentie,
    RksRegel.RksZoekCode RglRksZoekCode,
    RksRegel.RksInvoer RglRksInvoer,
    RksRegel.RksNaam RglRksNaam,
    IsCreditBoeking,
    JrValNummer RglBoekValNummer,
    JrValCode RglBoekValCode,
    case @BedragenAfdrukkenIn
      when 0 then @DefValTegRekNummer
      when 1 then RglBoekValNummer
      when 2 then @@BasisValutanummer
      when 3 then @BedragenAfdrukkenExtraValNummer
    end AfdrukValNummerBedragen,
    case @BedragenAfdrukkenIn
      when 0 then @DefValTegRekCode
      when 1 then RglBoekValCode
      when 2 then @@BasisValutaCode
      when 3 then @BedragenAfdrukkenExtraValCode
    end AfdrukValCodeBedragen,

    JrValutaBedrag JrBoekValBedrag,
    tmpBoekValBoekingBedragD BoekValBoekingBedragD,
    tmpBoekValBoekingBedragC BoekValBoekingBedragC,
    tmpBoekValBoekingSaldo BoekValBoekingSaldo,
    tmpBoekValRegelTotaalD BoekValRegelTotaalD,
    tmpBoekValRegelTotaalC BoekValRegelTotaalC,
    tmpBoekValRegelSaldo BoekValRegelSaldo,

    JrBasisBedrag JrBasisValBedrag,
    tmpBasisValBoekingBedragD BasisValBoekingBedragD,
    tmpBasisValBoekingBedragC BasisValBoekingBedragC,
    tmpBasisValBoekingSaldo BasisValBoekingSaldo,
    tmpBasisValRegelTotaalD BasisValRegelTotaalD,
    tmpBasisValRegelTotaalC BasisValRegelTotaalC,
    tmpBasisValRegelSaldo BasisValRegelSaldo,

    JrFactuurDatum,
    JrVervalDatum,
    JrBetalingsKenmerk,
    HulpRekSoort,
    if SoortBoeking = 2 then _U('Autom.')      else RksHulp.RksZoekCode endif HulpRekeningZoekCode,
    if SoortBoeking = 2 then _U('Autom.')      else RksHulp.RksInvoer   endif HulpRekeningInvoer,
    if SoortBoeking = 2 then _U('Automatisch') else RksHulp.RksNaam     endif HulpRekeningNaam,
    HulpRekBtwCode,
    tmpHulpRekIsCredit HulpRekIsCreditBoeking,
    tmpHulpRekBoekValNummer HulpRekBoekValNummer,
    (select ValCode from tabValuta where ValNummer = HulpRekBoekValNummer) HulpRekBoekValCode,
    if HulpRekBoekValNummer is not null then
      case @BedragenAfdrukkenIn
        when 0 then @DefValTegRekNummer
        when 1 then HulpRekBoekValNummer
        when 2 then @@BasisValutanummer
        when 3 then @BedragenAfdrukkenExtraValNummer
      end
    endif HulpRekAfdrukValNummerBedragen,
    if HulpRekBoekValNummer is not null then
      case @BedragenAfdrukkenIn
        when 0 then @DefValTegRekCode
        when 1 then HulpRekBoekValCode
        when 2 then @@BasisValutaCode
        when 3 then @BedragenAfdrukkenExtraValCode
      end
    endif HulpRekAfdrukValCodeBedragen,
    tmpHulpRekBoekValBedrag HulpRekBoekValBedrag,
    tmpHulpRekBasisValBedrag HulpRekBasisValBedrag,
    tmpAfdrukValBoekingCumBedragD AfdrukValBoekingCumBedragD,
    tmpAfdrukValBoekingCumBedragC AfdrukValBoekingCumBedragC,
    tmpAfdrukValBoekingCumSaldo AfdrukValBoekingCumSaldo,
    tmpAfdrukValRegelCumSaldo AfdrukValRegelCumSaldo,
    // Indien het geboekt aantal-veld een 0 bevat er van uit gaan dat er NIET geboekt is
    if Aantal <> 0 then Aantal endif,
    /*tbv. projecten*/
    ProjCode,
    ProjOmschr,
    PbZoekCode,
    PbOmschr,
    ArtCode,
    ArtOms,
    pbrSelectieCodes
  from
    tmpExtraVelden
    inner join tabJournaalregel               on (JrGid=tmpJrGid)
    inner join tabJournaalPost                on (JpGid = JrJpGid)
    inner join tabRekeningschema RksRegel     on (RksRegel.RksGid = JrRksGid)
    left outer join (tabHulpRekening inner join tabRekeningschema RksHulp on (RksHulp.RksGid = HulpRekRksGid)) on (HulpRekJrGid = JrGid)
    left outer join tabProjectBoekingsRegel   on PbrGid   = JrPbrGid
    left outer join tabProject                on ProjGid  = PbrProjGid
    left outer join tabProjectBoom            on PbGid    = PbrPbGid
    left outer join tabArtikel                on ArtGid   = PbrArtGid
  order by
    tmpGid;


end;

// call rapJournaalJournaalRegel(5446, 1, 2, 1, 0, 1, 30, 2, 1, 3, 3);


if exists (select 1 from sys.sysProcedure where proc_name='rapJournaalTotalen') then
  drop procedure rapJournaalTotalen;
end if;

create procedure rapJournaalTotalen(
in @SoortBoeking                    smallint, // 0=definitief, 1=voorlopig, 2=beide
in @BjGid                           integer,
in @VanRegelNr                      integer,
in @TotRegelNr                      integer,
in @VanPerNr                        integer,
in @TotPerNr                        integer,
in @TotalenAfdrukkenIn              integer,  // 2 = Basisvaluta 3 = extra valuta
in @TotalenAfdrukkenExtraValNummer  integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta.

result (
  TotaalDBasisVal    numeric(15,2),
  TotaalCBasisVal    numeric(15,2),
  SaldoBasisVal      numeric(15,2),
  TotaalDExtraVal    numeric(15,2),
  TotaalCExtraVal    numeric(15,2),
  SaldoExtraVal      numeric(15,2),
  TotaalDAfdrukVal   numeric(15,2),
  TotaalCAfdrukVal   numeric(15,2),
  SaldoAfdrukVal     numeric(15,2),
  TotaalDAantal      numeric(15,2),
  TotaalCAantal      numeric(15,2),
  SaldoAantal        numeric(15,2))

begin
   // Voorkomen van afrondingsverschillen
  declare @NumDeciBasisVal        integer;
  declare @NumDeciExtraValTotalen integer;

  //call TraceBegin('rapJournaalTotalen (@SoortBoeking='+string(@SoortBoeking)+', @BjGid='+string(@BjGid)+', @VanRegelNr='+string(@VanRegelNr)+', @TotRegelNr='+string(@TotRegelNr)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', ...');
  //call Trace('..., @TotalenAfdrukkenIn='+string(@TotalenAfdrukkenIn)+', @TotalenAfdrukkenExtraValNummer='+string(@TotalenAfdrukkenExtraValNummer)+')');

  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;
  if @TotalenAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen  from tabValuta where ValNummer = @TotalenAfdrukkenExtraValNummer;
  end if;

  //call TraceEind('rapJournaalTotalen');

  select
    // ---------- Basisvaluta ----------
    isnull(sum(round((if IsCreditBoeking = 0 then JrBasisBedrag endif), @NumDeciBasisVal)), 0) TotaalDBasisVal,
    isnull(sum(round((if IsCreditBoeking = 1 then JrBasisBedrag endif), @NumDeciBasisVal)), 0) TotaalCBasisVal,
    (TotaalDBasisVal - TotaalCBasisVal) SaldoBasisVal,

    // ---------- Eventuele extra valuta ----------
    if @TotalenAfdrukkenExtraValNummer is not null then
      isnull(sum(round((if IsCreditBoeking = 0 then
                          if JrValNummer = @TotalenAfdrukkenExtraValNummer then
                            JrValutaBedrag
                          else
                            round(JrBasisBedrag, @NumDeciBasisVal)/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer)
                          endif
                        endif
                       ), @NumDeciExtraValTotalen)
            ), 0)
    endif TotaalDExtraVal,
    if @TotalenAfdrukkenExtraValNummer is not null then
      isnull(sum(round((if IsCreditBoeking = 1 then
                          if JrValNummer = @TotalenAfdrukkenExtraValNummer then
                            JrValutaBedrag
                          else
                            round(JrBasisBedrag, @NumDeciBasisVal)/KoersTovBasisValuta(JrBjGid, JrPernr, @TotalenAfdrukkenExtraValNummer)
                          endif
                        endif
                       ), @NumDeciExtraValTotalen)
            ), 0)
    endif TotaalCExtraVal,
    (TotaalDExtraVal - TotaalCExtraVal) SaldoExtraVal,
    case @TotalenAfdrukkenIn
      when 2 then TotaalDBasisVal
      when 3 then TotaalDExtraVal
    end TotaalDAfdrukVal,
    case @TotalenAfdrukkenIn
      when 2 then TotaalCBasisVal
      when 3 then TotaalCExtraVal
    end TotaalCAfdrukVal,
    case @TotalenAfdrukkenIn
      when 2 then SaldoBasisVal
      when 3 then SaldoExtraVal
    end SaldoAfdrukVal,
    isnull(sum(if IsCreditBoeking = 0 then Aantal endif), 0) TotaalDAantal,
    isnull(sum(if IsCreditBoeking = 1 then Aantal endif), 0) TotaalCAantal,
    TotaalDAantal - TotaalCAantal SaldoAantal
  from
    tabJournaalPost
    inner join tabJournaalRegel on (JrJpGid = JpGid)
  where
    JpBjGid = @BjGid and
    JrBjGid = @BjGid and
    ( (@SoortBoeking = 0 and RegelNummer between @VanRegelNr and @TotRegelNr) or
      (@SoortBoeking = 1 and RegelNummer is null) or
      (@SoortBoeking = 2 and (RegelNummer between @VanRegelNr and @TotRegelNr or RegelNummer is null) )
    )and
    JrPerNr between @VanPerNr and @TotPerNr;


end;

// call rapJournaalTotalen(2, 1, 1, 30, 0, 12, 3, 1);


// Denk bij het aanpassen van deze procs eraan dat de procs behorende bij grootboekmutaties en saldoanalyse grote
// overeenkomsten vertonen met de procs behorende bij kostenplaatsen-/kostendragermutaties
create or replace procedure rapKostenDragerMutatiesGrootboekRekeningen(
in @BjGid             integer,
in @KstdGid           integer,
in @VanPerNr          integer,
in @TotPerNr          integer,
in @SoortBoeking      smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @NulSaldiAfdrukken integer,
in @OrderBy           integer,  // Sorteren op: 0 = Nummer, 1 = Zoekcode
in @Ascending         integer)

result (
  RksGid			     integer,
  RekeningZoekCode       nchar(10),
  RekeningNummer		 nchar(28),
  RekeningNaam			 nchar(40),
  RekeningValNummer		 integer,
  RekeningValCode	 	 nchar(3))

begin
  //call TraceBegin('rapKostenDragerMutatiesGrootboekRekeningen (@BjGid='+string(@BjGid)+', @KstdGid='+string(@KstdGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', @NulSaldiAfdrukken='+string(@NulSaldiAfdrukken)+', @OrderBy='+string(@OrderBy)+', @Ascending='+string(@Ascending)+')');;
  //call TraceEind('rapKostenDragerMutatiesGrootboekRekeningen');
  select
    RksGid,
    RksZoekCode,
    RksInvoer,
    RksNaam,
    RksValNummer,
    (select ValCode from tabValuta where ValNummer = RksValNummer) ValCode,
    // Bepalen van eindsaldo per grootboekrekening. Dit is nodig voor de instelling in het voorloopscherm (Nulsaldi afdrukken)
    // Indien gekozen voor Nee (0)                                          -> alle grootboekrekeningen waarvan EindSaldo <> null en EindSaldo <> 0 <=> isnull(EindSaldo, 0) <> 0
    // Indien gekozen voor Ja, maar alleen rekeningen waarop geboekt is (1) -> alle grootboekrekeningen waarvan EindSaldo <> null                   <=> EindSaldo is not null
    // Indien gekozen voor Ja, alle rekeningen (2)                          -> alle grootboekrekeningen
    if @NulSaldiAfdrukken <> 2 then
      ( select
          sum( JrBasisBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) )
        from
          tabJournaalPost
          inner join tabJournaalRegel on (JrJpGid = JpGid)
        where
          JpBjGid = @BjGid and
          JrBjGid = @BjGid and
          JrPerNr between @VanPerNr and @TotPerNr and
          JrRksGid = RksGid and
          ( (@SoortBoeking = 0 and RegelNummer is not null) or
            (@SoortBoeking = 1 and RegelNummer is null) or
            (@SoortBoeking = 2)
          )
      )
    endif EindSaldo
  from
    tabRekeningschema
  where
    RksKstdGid = @KstdGid and
    ( (@NulSaldiAfdrukken = 0 and isnull(EindSaldo, 0) <> 0) or
      (@NulSaldiAfdrukken = 1 and EindSaldo is not null) or
      (@NulSaldiAfdrukken = 2)
    )
  order by
    if @Ascending = 0 and @OrderBy = 0 then RksInvoer endif desc, // Sorteren op nummer
    if @Ascending = 1 and @OrderBy = 0 then RksInvoer endif,
    if @Ascending = 0 and @OrderBy = 1 then RksZoekcode endif desc, // Sorteren op zoekcode
    if @Ascending = 1 and @OrderBy = 1 then RksZoekcode endif,
    // Altijd nasorteren op basis van nummer
    if @Ascending = 0 then RksInvoer endif desc,
    if @Ascending = 1 then RksInvoer endif;



end;

// call rapKostenDragerMutatiesGrootboekRekeningen(1, 1, 0, 12, 2, 0, 1, 1)


if exists (select 1 from sys.sysProcedure where proc_name='rapKostenDragerMutatiesTotalenPerKostenDrager') then
  drop procedure rapKostenDragerMutatiesTotalenPerKostenDrager;
end if;

create procedure rapKostenDragerMutatiesTotalenPerKostenDrager(
in @KstdGid                                   integer,
in @BjGid                                     integer,
in @VanPerNr                                  integer,
in @TotPerNr                                  integer,
in @SoortBoeking                              smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @TotalenPerRekeningAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta

result (
  BeginTotaalDBasisVal      numeric(15,2),
  BeginTotaalCBasisVal      numeric(15,2),
  BeginSaldoBasisVal        numeric(15,2),
  BeginTotaalDExtraVal      numeric(15,2),
  BeginTotaalCExtraVal      numeric(15,2),
  BeginSaldoExtraVal        numeric(15,2),
  BeginTotaalDAantal        numeric(15,2),
  BeginTotaalCAantal        numeric(15,2),
  BeginSaldoAantal          numeric(15,2),
  PeriodeTotaalDBasisVal    numeric(15,2),
  PeriodeTotaalCBasisVal    numeric(15,2),
  PeriodeSaldoBasisVal      numeric(15,2),
  PeriodeTotaalDExtraVal    numeric(15,2),
  PeriodeTotaalCExtraVal    numeric(15,2),
  PeriodeSaldoExtraVal      numeric(15,2),
  PeriodeTotaalDAantal      numeric(15,2),
  PeriodeTotaalCAantal      numeric(15,2),
  PeriodeSaldoAantal        numeric(15,2),
  EindTotaalDBasisVal       numeric(15,2),
  EindTotaalCBasisVal       numeric(15,2),
  EindSaldoBasisVal         numeric(15,2),
  EindTotaalDExtraVal       numeric(15,2),
  EindTotaalCExtraVal       numeric(15,2),
  EindSaldoExtraVal         numeric(15,2),
  EindTotaalDAantal         numeric(15,2),
  EindTotaalCAantal         numeric(15,2),
  EindSaldoAantal           numeric(15,2))

begin
  // Declareren van variabelen nodig het bepalen van de resultaatset
  declare @BeginTotaalDBasisVal   numeric(15,2);
  declare @BeginTotaalCBasisVal   numeric(15,2);
  declare @BeginTotaalDExtraVal   numeric(15,2);
  declare @BeginTotaalCExtraVal   numeric(15,2);
  declare @BeginTotaalDAantal     numeric(15,2);
  declare @BeginTotaalCAantal     numeric(15,2);

  declare @PeriodeTotaalDBasisVal numeric(15,2);
  declare @PeriodeTotaalCBasisVal numeric(15,2);
  declare @PeriodeTotaalDExtraVal numeric(15,2);
  declare @PeriodeTotaalCExtraVal numeric(15,2);
  declare @PeriodeTotaalDAantal   numeric(15,2);
  declare @PeriodeTotaalCAantal   numeric(15,2);

  // Achtereenvolgens de gegevens bepalen voor het begin en de perioden
  declare @Teller                        integer;
  declare @tmpVanPerNr                   integer;
  declare @tmpTotPerNr                   integer;

  // Ophalen van het aantal decimalen waarin de valuta dient te worden verwerkt
  declare @NumDeciBasisVal               integer;
  declare @NumDeciExtraValTotalen        integer;

  //call TraceBegin('rapKostenDragerMutatiesTotalenPerKostenDrager (@KstdGid='+string(@KstdGid)+', @BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call Trace('..., @TotalenPerRekeningAfdrukkenExtraValNummer='+string(@TotalenPerRekeningAfdrukkenExtraValNummer)+')');

  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;
  if @TotalenPerRekeningAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenPerRekeningAfdrukkenExtraValNummer;
  end if;

  set @Teller = 0; // 0 = Beginmutaties, 1 = periodemutaties
  while @teller <= 1 loop

    if @teller = 0 then
      // Beginmutaties dienen in deze context gezien te worden als de mutaties op de beginbalans EN eventueel de mutaties TOT AAN @VanPerNR
      set @tmpVanPerNr = 0;
      set @tmpTotPerNr = if @VanPerNr = 0 then 0 else @VanPerNr - 1 endif;
    else
      // Periodemutaties dienen in deze context gezien te worden als de mutaties VAN AF @VanPerNr TOT EN MET @TotPerNR, EXCLUSIEF de mutaties op de beginbalans
      if @TotPerNr = 0 then
        set @tmpVanPerNr = -1;
        set @tmpTotPerNr = -1;
      else
        set @tmpVanPerNr = if @VanPerNr = 0 then 1 else @VanPerNr endif;
        set @tmpTotPerNr = @TotPerNr;
      end if;
    end if;

    select
      // Bepaling van totaal geboekt bedrag debet/credit in de basisvaluta
      isnull(round(sum((case @SoortBoeking when 0 then SaldoDebetBasisDefinitief when 1 then SaldoDebetBasisVoorlopig when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig end)), @NumDeciBasisVal), 0),
      isnull(round(sum((case @SoortBoeking when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig end)), @NumDeciBasisVal), 0),

      // Bepaling van totaal geboekt debet/credit aantal
      isnull(sum(case @SoortBoeking when 0 then SaldoDebetAantalDefinitief  when 1 then SaldoDebetAantalVoorlopig  when 2 then SaldoDebetAantalDefinitief  + SaldoDebetAantalVoorlopig  end), 0),
      isnull(sum(case @SoortBoeking when 0 then SaldoCreditAantalDefinitief when 1 then SaldoCreditAantalVoorlopig when 2 then SaldoCreditAantalDefinitief + SaldoCreditAantalVoorlopig end), 0)
    into
      @PeriodeTotaalDBasisVal,
      @PeriodeTotaalCBasisVal,
      @PeriodeTotaalDAantal,
      @PeriodeTotaalCAantal
    from
      tabRekeningSchema
      iner join tabRekeningSaldo on (RekSaldoRksGid = RksGid)
    where
      RekSaldoBjGid = @BjGid and
      RekSaldoPerNr between @tmpVanPerNr and @tmpTotPerNr and
      RksKstdGid = @KstdGid;

    // Bepaling van de totalen geboekt debet/credit
    // Bij de valutaconversie van de totalen is de TotPerNr-koers genomen en op soortgelijke wijze bepaald als gedaan bij de balansen (overeenstemming is hier namelijk vereist)
    select
      // Bepaling van totaal geboekt bedrag debet/credit in de valuta van de grootboekrekening
      isnull(round((@PeriodeTotaalDBasisVal/KoersTovBasisValuta(@BjGid, @TotPerNr, @TotalenPerRekeningAfdrukkenExtraValNummer)), @NumDeciExtraValTotalen), 0),
      isnull(round((@PeriodeTotaalCBasisVal/KoersTovBasisValuta(@BjGid, @TotPerNr, @TotalenPerRekeningAfdrukkenExtraValNummer)), @NumDeciExtraValTotalen), 0)
    into
      @PeriodeTotaalDExtraVal,
      @PeriodeTotaalCExtraVal;

    if @teller = 0 then
      set @BeginTotaalDBasisVal = @PeriodeTotaalDBasisVal;
      set @BeginTotaalCBasisVal = @PeriodeTotaalCBasisVal;
      set @BeginTotaalDExtraVal = @PeriodeTotaalDExtraVal;
      set @BeginTotaalCExtraVal = @PeriodeTotaalCExtraVal;
      set @BeginTotaalDAantal   = @PeriodeTotaalDAantal;
      set @BeginTotaalCAantal   = @PeriodeTotaalCAantal;
    end if;

    set @Teller = @Teller + 1;

  end loop;

  //call TraceEind('rapKostenDragerMutatiesTotalenPerKostenDrager');

  select
    @BeginTotaalDBasisVal                                 BeginTotaalDBasisVal,
    @BeginTotaalCBasisVal                                 BeginTotaalCBasisVal,
    BeginTotaalDBasisVal    - BeginTotaalCBasisVal        BeginSaldoBasisVal,
    @BeginTotaalDExtraVal                                 BeginTotaalDExtraVal,
    @BeginTotaalCExtraVal                                 BeginTotaalCExtraVal,
    BeginTotaalDExtraVal    - BeginTotaalCExtraVal        BeginSaldoExtraVal,
    @BeginTotaalDAantal                                   BeginTotaalDAantal,
    @BeginTotaalCAantal                                   BeginTotaalCAantal,
    @BeginTotaalDAantal     - @BeginTotaalCAantal         BeginSaldoAantal,

    @PeriodeTotaalDBasisVal                               PeriodeTotaalDBasisVal,
    @PeriodeTotaalCBasisVal                               PeriodeTotaalCBasisVal,
    PeriodeTotaalDBasisVal  - PeriodeTotaalCBasisVal      PeriodeSaldoBasisVal,
    @PeriodeTotaalDExtraVal                               PeriodeTotaalDExtraVal,
    @PeriodeTotaalCExtraVal                               PeriodeTotaalCExtraVal,
    PeriodeTotaalDExtraVal  - PeriodeTotaalCExtraVal      PeriodeSaldoExtraVal,
    @PeriodeTotaalDAantal                                 PeriodeTotaalDAantal,
    @PeriodeTotaalCAantal                                 PeriodeTotaalCAantal,
    @PeriodeTotaalDAantal   - @PeriodeTotaalCAantal       PeriodeSaldoAantal,

    (BeginTotaalDBasisVal    + PeriodeTotaalDBasisVal)    EindTotaalDBasisVal,
    (BeginTotaalCBasisVal    + PeriodeTotaalCBasisVal)    EindTotaalCBasisVal,
    (BeginSaldoBasisVal      + PeriodeSaldoBasisVal)      EindSaldoBasisVal,
    (BeginTotaalDExtraVal    + PeriodeTotaalDExtraVal)    EindTotaalDExtraVal,
    (BeginTotaalCExtraVal    + PeriodeTotaalCExtraVal)    EindTotaalCExtraVal,
    (BeginSaldoExtraVal      + PeriodeSaldoExtraVal)      EindSaldoExtraVal,
    (BeginTotaalDAantal      + PeriodeTotaalDAantal)      EindTotaalDAantal,
    (BeginTotaalCAantal      + PeriodeTotaalCAantal)      EindTotaalCAantal,
    (BeginSaldoAantal        + PeriodeSaldoAantal)        EindSaldoAantal;


end;

// call rapKostenDragerMutatiesTotalenPerKostenDrager(1, 1, 0, 12, 2, 2)


create or replace procedure rapKostenDragerMutatiesTotalenPerValuta(
in @BjGid                                   integer,
in @VanPerNr                                integer,
in @TotPerNr                                integer,
in @SoortBoeking                            smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @Selectie     	                          integer,  // Selecteren op: 1 = nummer, 2 = zoekcode
in @VanKstd                                 nchar(40),
in @TotKstd	                                nchar(40),
in @TotalenPerValutaAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta

result (
  BoekValutaNummer       integer,
  BoekValutaCode         nchar(3),
  BoekValutaOmschrijving nchar(40),
  TotaalDBasisVal        numeric(15,2),
  TotaalCBasisVal        numeric(15,2),
  SaldoBasisVal          numeric(15,2),
  TotaalDBoekVal         numeric(15,2),
  TotaalCBoekVal         numeric(15,2),
  SaldoBoekVal           numeric(15,2),
  TotaalDExtraVal        numeric(15,2),
  TotaalCExtraVal        numeric(15,2),
  SaldoExtraVal          numeric(15,2))

begin
  // Voorkomen van afrondingsverschillen
  declare @NumDeciBasisVal          integer;
  declare @NumDeciExtraValTotalen    integer;

  //call TraceBegin('rapKostenDragerMutatiesTotalenPerValuta (@BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call Trace('..., @Selectie='+string(@Selectie)+', @VanKstd='+string(@VanKstd)+', @TotKstd='+string(@TotKstd)+', @TotalenPerValutaAfdrukkenExtraValNummer='+string(@TotalenPerValutaAfdrukkenExtraValNummer)+')');

  if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenPerValutaAfdrukkenExtraValNummer;
  end if;
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;

  //call TraceEind('rapKostenDragerMutatiesTotalenPerValuta');

  select
    RekSaldoValNummer BoekValutaNummer,
    ValCode BoekValutaCode,
    OmsValuta BoekValutaOmschrijving,
    isnull(sum(round((case @SoortBoeking when 0 then SaldoDebetBasisDefinitief when 1 then SaldoDebetBasisVoorlopig when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig end), @NumDeciBasisVal)), 0) TotaalDBasisVal,
    isnull(sum(round((case @SoortBoeking when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig end), @NumDeciBasisVal)), 0) TotaalCBasisVal,
    TotaalDBasisVal - TotaalCBasisVal,
    if BoekValutaNummer <> @@BasisValutaNummer then
      isnull(sum(round((case @SoortBoeking when 0 then SaldoDebetValutaDefinitief when 1 then SaldoDebetValutaVoorlopig when 2 then SaldoDebetValutaDefinitief + SaldoDebetValutaVoorlopig end), if DecimalenBoeking <> 0 then 2 else 0 endif)), 0)
    else
      TotaalDBasisVal
    endif TotaalDBoekVal,
    if BoekValutaNummer <> @@BasisValutaNummer then
      isnull(sum(round((case @SoortBoeking when 0 then SaldoCreditValutaDefinitief when 1 then SaldoCreditValutaVoorlopig when 2 then SaldoCreditValutaDefinitief + SaldoCreditValutaVoorlopig end), if DecimalenBoeking <> 0 then 2 else 0 endif)), 0)
    else
      TotaalCBasisVal
    endif TotaalCBoekVal,
    TotaalDBoekVal - TotaalCBoekVal,
    if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
      if @TotalenPerValutaAfdrukkenExtraValNummer = BoekValutaNummer then
        TotaalDBoekVal
      else
        isnull(sum(round(round((case @SoortBoeking when 0 then SaldoDebetBasisDefinitief when 1 then SaldoDebetBasisVoorlopig when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig end), @NumDeciBasisVal)/KoersTovBasisValuta(@BjGid, @TotPerNr, @TotalenPerValutaAfdrukkenExtraValNummer), @NumDeciExtraValTotalen)), 0)
      endif
    endif TotaalDExtraVal,
    if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
      if @TotalenPerValutaAfdrukkenExtraValNummer = BoekValutaNummer then
        TotaalCBoekVal
      else
        isnull(sum(round(round((case @SoortBoeking when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig end), @NumDeciBasisVal)/KoersTovBasisValuta(@BjGid, @TotPerNr, @TotalenPerValutaAfdrukkenExtraValNummer), @NumDeciExtraValTotalen)), 0)
      endif
    endif TotaalCExtraVal,
    TotaalDExtraVal - TotaalCExtraVal
  from
    tabRekeningSchema
    inner join tabKostenDrager  on (KstdGid = RksKstdGid)
    inner join tabRekeningSaldo on (RekSaldoRksGid = RksGid)
    inner join tabValuta        on (ValNummer = BoekValutaNummer)
  where
    RekSaldoBjGid = @BjGid and
    RekSaldoPerNr between @VanPerNr and @TotPerNr and
    ( (@Selectie = 1 and KstdCode     between @VanKstd and @TotKstd) or
      (@Selectie = 2 and KstdZoekcode between @VanKstd and @TotKstd)
    )
  group by
    BoekValutaNummer,
    BoekValutaCode,
    BoekValutaOmschrijving;


end;

// call rapKostenDragerMutatiesTotalenPerValuta(1, 0, 12, 0, 1, '1', '3', 0)


// Denk bij het aanpassen van deze procs eraan dat de procs behorende bij grootboekmutaties en saldoanalyse grote
// overeenkomsten vertonen met de procs behorende bij kostenplaatsen-/kostendragermutaties
create or replace procedure rapKostenPlaatsMutatiesGrootboekRekeningen(
in @BjGid             integer,
in @KstpGid           integer,
in @VanPerNr          integer,
in @TotPerNr          integer,
in @SoortBoeking      smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @NulSaldiAfdrukken integer,  // 0 = Nee, 1 = Alleen rekeningen waarop is geboekt, 2 = Alle rekeningen
in @OrderBy           integer,  // Sorteren op: 0 = Nummer, 1 = Zoekcode
in @Ascending         integer)

result (
  RksGid			    integer,
  RekeningZoekCode      nchar(10),
  RekeningNummer		nchar(28),
  RekeningNaam			nchar(40),
  RekeningValNummer		integer,
  RekeningValCode	 	nchar(3))

begin
  //call TraceBegin('rapKostenPlaatsMutatiesGrootboekRekeningen (@BjGid='+string(@BjGid)+', @KstpGid='+string(@KstpGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', @NulSaldiAfdrukken='+string(@NulSaldiAfdrukken)+', @OrderBy='+string(@OrderBy)+', @Ascending='+string(@Ascending)+')');;
  //call TraceEind('rapKostenPlaatsMutatiesGrootboekRekeningen');
  select
    RksGid,
    RksZoekCode,
    RksInvoer,
    RksNaam,
    RksValNummer,
    (select ValCode from tabValuta where ValNummer = RksValNummer) ValCode
  from
    tabRekeningschema
  where
    RksKstpGid = @KstpGid and
    (case @NulSaldiAfdrukken
     when 0 then // alleen afdrukken indien saldo <> 0, dus saldo bepalen!
       ( select
           sum( JrBasisBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) )
         from
           tabJournaalRegel
         where
           JrBjGid = @BjGid and
           JrPerNr between @VanPerNr and @TotPerNr and
           JrRksGid = RksGid and
           ( (@SoortBoeking = 0 and RegelNummer is not null) or
             (@SoortBoeking = 1 and RegelNummer is null) or
             (@SoortBoeking = 2)
           )
       )
     when 1 then // afdrukken indien geboekt
       if exists(select 1 from tabJournaalRegel where JrBjGid = @BjGid and JrPerNr between @VanPerNr and @TotPerNr and JrRksGid = RksGid and ( (@SoortBoeking = 0 and RegelNummer is not null) or (@SoortBoeking = 1 and RegelNummer is null) or (@SoortBoeking = 2) ) ) then
         1
       else
         0
       endif
     when 2 then // altijd afdrukken
       1
     end
    ) <> 0
  order by
    if @Ascending = 0 and @OrderBy = 0 then RksInvoer endif desc, // Sorteren op nummer
    if @Ascending = 1 and @OrderBy = 0 then RksInvoer endif,
    if @Ascending = 0 and @OrderBy = 1 then RksZoekcode endif desc, // Sorteren op zoekcode
    if @Ascending = 1 and @OrderBy = 1 then RksZoekcode endif,
    // Altijd nasorteren op basis van nummer
    if @Ascending = 0 then RksInvoer endif desc,
    if @Ascending = 1 then RksInvoer endif;


end;

// call rapKostenPlaatsMutatiesGrootboekRekeningen(1, 1, 0, 12, 2, 0, 1, 1)


//$Workfile: rapKostenPlaatsMutatiesTotalenPerKostenPlaats.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $

if exists (select 1 from sys.sysProcedure where proc_name='rapKostenPlaatsMutatiesTotalenPerKostenPlaats') then
  drop procedure rapKostenPlaatsMutatiesTotalenPerKostenPlaats;
end if;

create procedure rapKostenPlaatsMutatiesTotalenPerKostenPlaats(
in @KstpGid                                   integer,
in @BjGid                                     integer,
in @VanPerNr                                  integer,
in @TotPerNr                                  integer,
in @SoortBoeking                              smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @TotalenPerRekeningAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta

result (
  BeginTotaalDBasisVal      numeric(15,2),
  BeginTotaalCBasisVal      numeric(15,2),
  BeginSaldoBasisVal        numeric(15,2),
  BeginTotaalDExtraVal      numeric(15,2),
  BeginTotaalCExtraVal      numeric(15,2),
  BeginSaldoExtraVal        numeric(15,2),
  BeginTotaalDAantal        numeric(15,2),
  BeginTotaalCAantal        numeric(15,2),
  BeginSaldoAantal          numeric(15,2),
  PeriodeTotaalDBasisVal    numeric(15,2),
  PeriodeTotaalCBasisVal    numeric(15,2),
  PeriodeSaldoBasisVal      numeric(15,2),
  PeriodeTotaalDExtraVal    numeric(15,2),
  PeriodeTotaalCExtraVal    numeric(15,2),
  PeriodeSaldoExtraVal      numeric(15,2),
  PeriodeTotaalDAantal      numeric(15,2),
  PeriodeTotaalCAantal      numeric(15,2),
  PeriodeSaldoAantal        numeric(15,2),
  EindTotaalDBasisVal       numeric(15,2),
  EindTotaalCBasisVal       numeric(15,2),
  EindSaldoBasisVal         numeric(15,2),
  EindTotaalDExtraVal       numeric(15,2),
  EindTotaalCExtraVal       numeric(15,2),
  EindSaldoExtraVal         numeric(15,2),
  EindTotaalDAantal         numeric(15,2),
  EindTotaalCAantal         numeric(15,2),
  EindSaldoAantal           numeric(15,2))

begin
  // Declareren van variabelen nodig het bepalen van de resultaatset
  declare @BeginTotaalDBasisVal   numeric(15,2);
  declare @BeginTotaalCBasisVal   numeric(15,2);
  declare @BeginTotaalDExtraVal   numeric(15,2);
  declare @BeginTotaalCExtraVal   numeric(15,2);
  declare @BeginTotaalDAantal     numeric(15,2);
  declare @BeginTotaalCAantal     numeric(15,2);

  declare @PeriodeTotaalDBasisVal numeric(15,2);
  declare @PeriodeTotaalCBasisVal numeric(15,2);
  declare @PeriodeTotaalDExtraVal numeric(15,2);
  declare @PeriodeTotaalCExtraVal numeric(15,2);
  declare @PeriodeTotaalDAantal   numeric(15,2);
  declare @PeriodeTotaalCAantal   numeric(15,2);

  // Achtereenvolgens de gegevens bepalen voor het begin en de perioden
  declare @Teller                        integer;
  declare @tmpVanPerNr                   integer;
  declare @tmpTotPerNr                   integer;

  // Ophalen van het aantal decimalen waarin de valuta dient te worden verwerkt
  declare @NumDeciBasisVal               integer;
  declare @NumDeciExtraValTotalen        integer;

  //call TraceBegin('rapKostenPlaatsMutatiesTotalenPerKostenPlaats (@KstpGid='+string(@KstpGid)+', @BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call Trace('..., @TotalenPerRekeningAfdrukkenExtraValNummer='+string(@TotalenPerRekeningAfdrukkenExtraValNummer)+')');

  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;
  if @TotalenPerRekeningAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenPerRekeningAfdrukkenExtraValNummer;
  end if;

  set @Teller = 0; // 0 = Beginmutaties, 1 = periodemutaties
  while @teller <= 1 loop

    if @teller = 0 then
      // Beginmutaties dienen in deze context gezien te worden als de mutaties op de beginbalans EN eventueel de mutaties TOT AAN @VanPerNR
      set @tmpVanPerNr = 0;
      set @tmpTotPerNr = if @VanPerNr = 0 then 0 else @VanPerNr - 1 endif;
    else
      // Periodemutaties dienen in deze context gezien te worden als de mutaties VAN AF @VanPerNr TOT EN MET @TotPerNR, EXCLUSIEF de mutaties op de beginbalans
      if @TotPerNr = 0 then
        set @tmpVanPerNr = -1;
        set @tmpTotPerNr = -1;
      else
        set @tmpVanPerNr = if @VanPerNr = 0 then 1 else @VanPerNr endif;
        set @tmpTotPerNr = @TotPerNr;
      end if;
    end if;

    select
      // Bepaling van totaal geboekt bedrag debet/credit in de basisvaluta
      isnull(round(sum((case @SoortBoeking when 0 then SaldoDebetBasisDefinitief when 1 then SaldoDebetBasisVoorlopig when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig end)), @NumDeciBasisVal), 0),
      isnull(round(sum((case @SoortBoeking when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig end)), @NumDeciBasisVal), 0),

      // Bepaling van totaal geboekt debet/credit aantal
      isnull(sum(case @SoortBoeking when 0 then SaldoDebetAantalDefinitief  when 1 then SaldoDebetAantalVoorlopig  when 2 then SaldoDebetAantalDefinitief  + SaldoDebetAantalVoorlopig  end), 0),
      isnull(sum(case @SoortBoeking when 0 then SaldoCreditAantalDefinitief when 1 then SaldoCreditAantalVoorlopig when 2 then SaldoCreditAantalDefinitief + SaldoCreditAantalVoorlopig end), 0)
    into
      @PeriodeTotaalDBasisVal,
      @PeriodeTotaalCBasisVal,
      @PeriodeTotaalDAantal,
      @PeriodeTotaalCAantal
    from
      tabRekeningSchema
      inner join tabRekeningSaldo on (RekSaldoRksGid = RksGid)
    where
      RekSaldoBjGid = @BjGid and
      RekSaldoPerNr between @tmpVanPerNr and @tmpTotPerNr and
      RksKstpGid = @KstpGid;

    // Bepaling van de totalen geboekt debet/credit
    // Bij de valutaconversie van de totalen is de TotPerNr-koers genomen en op soortgelijke wijze bepaald als gedaan bij de balansen (overeenstemming is hier namelijk vereist)
    select
      // Bepaling van totaal geboekt bedrag debet/credit in de valuta van de grootboekrekening
      isnull(round((@PeriodeTotaalDBasisVal/KoersTovBasisValuta(@BjGid, @TotPerNr, @TotalenPerRekeningAfdrukkenExtraValNummer)), @NumDeciExtraValTotalen), 0),
      isnull(round((@PeriodeTotaalCBasisVal/KoersTovBasisValuta(@BjGid, @TotPerNr, @TotalenPerRekeningAfdrukkenExtraValNummer)), @NumDeciExtraValTotalen), 0)
    into
      @PeriodeTotaalDExtraVal,
      @PeriodeTotaalCExtraVal;

    if @teller = 0 then
      set @BeginTotaalDBasisVal = @PeriodeTotaalDBasisVal;
      set @BeginTotaalCBasisVal = @PeriodeTotaalCBasisVal;
      set @BeginTotaalDExtraVal = @PeriodeTotaalDExtraVal;
      set @BeginTotaalCExtraVal = @PeriodeTotaalCExtraVal;
      set @BeginTotaalDAantal   = @PeriodeTotaalDAantal;
      set @BeginTotaalCAantal   = @PeriodeTotaalCAantal;
    end if;

    set @Teller = @Teller + 1;

  end loop;

  //call TraceEind('rapKostenPlaatsMutatiesTotalenPerKostenPlaats');

  select
    @BeginTotaalDBasisVal                                 BeginTotaalDBasisVal,
    @BeginTotaalCBasisVal                                 BeginTotaalCBasisVal,
    BeginTotaalDBasisVal    - BeginTotaalCBasisVal        BeginSaldoBasisVal,
    @BeginTotaalDExtraVal                                 BeginTotaalDExtraVal,
    @BeginTotaalCExtraVal                                 BeginTotaalCExtraVal,
    BeginTotaalDExtraVal    - BeginTotaalCExtraVal        BeginSaldoExtraVal,
    @BeginTotaalDAantal                                   BeginTotaalDAantal,
    @BeginTotaalCAantal                                   BeginTotaalCAantal,
    @BeginTotaalDAantal     - @BeginTotaalCAantal         BeginSaldoAantal,

    @PeriodeTotaalDBasisVal                               PeriodeTotaalDBasisVal,
    @PeriodeTotaalCBasisVal                               PeriodeTotaalCBasisVal,
    PeriodeTotaalDBasisVal  - PeriodeTotaalCBasisVal      PeriodeSaldoBasisVal,
    @PeriodeTotaalDExtraVal                               PeriodeTotaalDExtraVal,
    @PeriodeTotaalCExtraVal                               PeriodeTotaalCExtraVal,
    PeriodeTotaalDExtraVal  - PeriodeTotaalCExtraVal      PeriodeSaldoExtraVal,
    @PeriodeTotaalDAantal                                 PeriodeTotaalDAantal,
    @PeriodeTotaalCAantal                                 PeriodeTotaalCAantal,
    @PeriodeTotaalDAantal   - @PeriodeTotaalCAantal       PeriodeSaldoAantal,

    (BeginTotaalDBasisVal    + PeriodeTotaalDBasisVal)    EindTotaalDBasisVal,
    (BeginTotaalCBasisVal    + PeriodeTotaalCBasisVal)    EindTotaalCBasisVal,
    (BeginSaldoBasisVal      + PeriodeSaldoBasisVal)      EindSaldoBasisVal,
    (BeginTotaalDExtraVal    + PeriodeTotaalDExtraVal)    EindTotaalDExtraVal,
    (BeginTotaalCExtraVal    + PeriodeTotaalCExtraVal)    EindTotaalCExtraVal,
    (BeginSaldoExtraVal      + PeriodeSaldoExtraVal)      EindSaldoExtraVal,
    (BeginTotaalDAantal      + PeriodeTotaalDAantal)      EindTotaalDAantal,
    (BeginTotaalCAantal      + PeriodeTotaalCAantal)      EindTotaalCAantal,
    (BeginSaldoAantal        + PeriodeSaldoAantal)        EindSaldoAantal;


end;

// call rapKostenPlaatsMutatiesTotalenPerKostenPlaats(1, 1, 0, 12, 2, 2)


create or replace procedure rapKostenPlaatsMutatiesTotalenPerValuta(
in @BjGid                                   integer,
in @VanPerNr                                integer,
in @TotPerNr                                integer,
in @SoortBoeking                            smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @Selectie     	                          integer,  // Selecteren op: 1 = nummer, 2 = zoekcode
in @VanKstp                                 nchar(40),
in @TotKstp	                                nchar(40),
in @TotalenPerValutaAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta

result (
  BoekValutaNummer       integer,
  BoekValutaCode         nchar(3),
  BoekValutaOmschrijving nchar(40),
  TotaalDBasisVal        numeric(15,2),
  TotaalCBasisVal        numeric(15,2),
  SaldoBasisVal          numeric(15,2),
  TotaalDBoekVal         numeric(15,2),
  TotaalCBoekVal         numeric(15,2),
  SaldoBoekVal           numeric(15,2),
  TotaalDExtraVal        numeric(15,2),
  TotaalCExtraVal        numeric(15,2),
  SaldoExtraVal          numeric(15,2))

begin
  // Voorkomen van afrondingsverschillen
  declare @NumDeciBasisVal          integer;
  declare @NumDeciExtraValTotalen    integer;

  //call TraceBegin('rapKostenPlaatsMutatiesTotalenPerValuta (@BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call Trace('..., @Selectie='+string(@Selectie)+', @VanKstp='+string(@VanKstp)+', @TotKstp='+string(@TotKstp)+', @TotalenPerValutaAfdrukkenExtraValNummer='+string(@TotalenPerValutaAfdrukkenExtraValNummer)+')');

  if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenPerValutaAfdrukkenExtraValNummer;
  end if;
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;

  //call TraceEind('rapKostenPlaatsMutatiesTotalenPerValuta');

  select
    RekSaldoValNummer BoekValutaNummer,
    ValCode BoekValutaCode,
    OmsValuta BoekValutaOmschrijving,
    isnull(sum(round((case @SoortBoeking when 0 then SaldoDebetBasisDefinitief when 1 then SaldoDebetBasisVoorlopig when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig end), @NumDeciBasisVal)), 0) TotaalDBasisVal,
    isnull(sum(round((case @SoortBoeking when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig end), @NumDeciBasisVal)), 0) TotaalCBasisVal,
    TotaalDBasisVal - TotaalCBasisVal,
    if BoekValutaNummer <> @@BasisValutaNummer then
      isnull(sum(round((case @SoortBoeking when 0 then SaldoDebetValutaDefinitief when 1 then SaldoDebetValutaVoorlopig when 2 then SaldoDebetValutaDefinitief + SaldoDebetValutaVoorlopig end), if DecimalenBoeking <> 0 then 2 else 0 endif)), 0)
    else
      TotaalDBasisVal
    endif TotaalDBoekVal,
    if BoekValutaNummer <> @@BasisValutaNummer then
      isnull(sum(round((case @SoortBoeking when 0 then SaldoCreditValutaDefinitief when 1 then SaldoCreditValutaVoorlopig when 2 then SaldoCreditValutaDefinitief + SaldoCreditValutaVoorlopig end), if DecimalenBoeking <> 0 then 2 else 0 endif)), 0)
    else
      TotaalCBasisVal
    endif TotaalCBoekVal,
    TotaalDBoekVal - TotaalCBoekVal,
    if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
      if @TotalenPerValutaAfdrukkenExtraValNummer = BoekValutaNummer then
        TotaalDBoekVal
      else
        isnull(sum(round(round((case @SoortBoeking when 0 then SaldoDebetBasisDefinitief when 1 then SaldoDebetBasisVoorlopig when 2 then SaldoDebetBasisDefinitief + SaldoDebetBasisVoorlopig end), @NumDeciBasisVal)/KoersTovBasisValuta(@BjGid, @TotPerNr, @TotalenPerValutaAfdrukkenExtraValNummer), @NumDeciExtraValTotalen)), 0)
      endif
    endif TotaalDExtraVal,
    if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
      if @TotalenPerValutaAfdrukkenExtraValNummer = BoekValutaNummer then
        TotaalCBoekVal
      else
        isnull(sum(round(round((case @SoortBoeking when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then SaldoCreditBasisDefinitief + SaldoCreditBasisVoorlopig end), @NumDeciBasisVal)/KoersTovBasisValuta(@BjGid, @TotPerNr, @TotalenPerValutaAfdrukkenExtraValNummer), @NumDeciExtraValTotalen)), 0)
      endif
    endif TotaalCExtraVal,
    TotaalDExtraVal - TotaalCExtraVal
  from
    tabRekeningSchema
    inner join tabKostenPlaats on (KstpGid = RksKstpGid)
    inner join tabRekeningSaldo on (RekSaldoRksGid = RksGid)
    inner join tabValuta on (ValNummer = BoekValutaNummer)
  where
    RekSaldoBjGid = @BjGid and
    RekSaldoPerNr between @VanPerNr and @TotPerNr and
    ( (@Selectie = 1 and KstpCode     between @VanKstp and @TotKstp) or
      (@Selectie = 2 and KstpZoekcode between @VanKstp and @TotKstp)
    )
  group by
    BoekValutaNummer,
    BoekValutaCode,
    BoekValutaOmschrijving;


end;

// call rapKostenPlaatsMutatiesTotalenPerValuta(1, 0, 12, 0, 1, '1', '3', 0)


//rapMagOntEtiket.sp - magazijn ontvangst artikel etiketten
create or replace procedure rapMagOntEtiket(
  in @MohbGid                 integer,
  in @MohkGid                 integer,
  in @AantEtikLocMag          smallInt,   //0=geen, 1=één, 2=aantal inkoopeenheden, 3=aantal voorraadeenheden
  in @AantEtikLocOrd          smallInt,   //0=geen, 1=één, 2=aantal inkoopeenheden, 3=aantal voorraadeenheden
  in @AantEtikOrdMag          smallInt,   //0=geen, 1=één, 2=aantal inkoopeenheden, 3=aantal voorraadeenheden
  in @AantEtikOrdOrd          smallInt,   //0=geen, 1=één, 2=aantal inkoopeenheden, 3=aantal voorraadeenheden
  in @AantEtikOntvangstregel  smallInt,   //0=geen, 1=één, 2=aantal inkoopeenheden, 3=aantal voorraadeenheden
  in @TaalCodeSelectie        nchar(1))

result (
    SoortEtiket SmallInt,                 IsRestantEtiket SmallInt,
    //gegevens magazijnontvangstkop/regel
    MohkGid Integer,                      MokNummer Numeric(10,0),              MokOntvangstDatum DateTime,     MokOmschrijving nchar(40),
    MohrGid Integer,                      MagOntRegelNr Integer,
    //leveranciergegevens
    LevNummer nchar(10),                    LevZoekcode nchar(10),           LevNaam nchar(40),
    //Bestelgegeves
    BstKopNummer numeric(10,0),           BstRglNummer integer,                 BstRglOms Long nvarchar,         OmsBestelRegelOfArtikel Long nvarchar,
    //artikelgegevens
    ArtCode nchar(20),                     ArtZoekcode nchar(20),           ArtOms nchar(40),
    ArtAantDecAantallen Integer,          ArtAantDecPrijzen Integer,            ArtPrijsPer Numeric(15,3),
   	ArtIsGeblokkeerd SmallInt,            ArtIsGeblokkeerdInkoop SmallInt,      ArtOmsEenheid nchar(20),         ArtHeeftVoorraad SmallInt,
  	ArtGewichtPerEenheid Numeric(15,3),   ArtVolumePerEenheid Numeric(15,3),    ArtSerienrRegistreren SmallInt, ArtIsPartijRegistreren SmallInt,
    ArtAfbeeldingKlein nchar(80),          ArtAfbeeldingGroot nchar(80),          TekstOpFactuur Long nvarchar,    ArtOpmerking Long nvarchar,
   	OpbrGrpNummer nchar(4),                OpbrGrpOms nchar(40),                  DefaultEanCode nchar(30),
    MagOntArtCodeBijLeverancier nchar(20), MagOntEanCode nchar(30),
    //aantallen
    MagOntInkoopEenheid nchar(20),         MagOntVoorraadEenhedenInInkoopEenheid Numeric(15,3),                  InkEenhIsVrdEenh smallInt,
    MagOntAantalInkoopEenheden Numeric(15,3), MagOntAantalVoorraadEenheden  Numeric(15,3),
    AantalInkEenhEtiket Numeric(15,3),    AantalVrdkEenhEtiket Numeric(15,3),   //aantal eenheden per etiket

    //partijgegevens
    ArtPartijNummer nchar(20),             ArtPartijOms nchar(40),                ArtPartijNrBijLeverancier nchar(20),   ArtPartijOpm long nvarchar,
    ArtPartijDatumOntvangst DateTime,     ArtPartijTHTdatum DateTime,           ArtPartijVrijTmDatum DateTime,        ArtPartijVrijVanafDatum DateTime,
    ArtPartijDatumProductie DateTime,
    //Verkoopprijs artikel/partij
    BtwCodeVerkoop Integer,               BtwPercVerkoop Numeric(6,2),          VerkoopPrijsIsInclBTW SmallInt,
    VerkoopPrijsExclusief Numeric(15,3),  VerkoopPrijsInclusief Numeric(15,3),  SoortKorting SmallInt,
    KortingsBedragExclusief Numeric(15,3),KortingsBedragInclusief Numeric(15,3),KortingsPerc Numeric(5,2),
    //adviesprijs
    ArtIsAdviesPrijsInclBTW SmallInt,     AdviesPrijsExclusief Numeric(15,3),   AdviesPrijsInclusief Numeric(15,3),
    //cbs land oorsprong
    CbsOorsprongLndEigenCode nchar(3),    CbsOorsprongLndOms nchar(40),
    //order/magazijnregelgegevens
    MagOntDetBrdSoort smallInt,           OrderNummer numeric(10,0),            OrderRegelNr integer,                 BackorderAantal Numeric(15,3),   BackorderLeverdatum DateTime,

    DebiteurNummer nchar(10),              DebiteurZoekcode nchar(10),            DebiteurNaam1 nchar(40),               DebiteurNaam2 nchar(40),
    DebiteurStraat nchar(40),              DebiteurHuisnummer nchar(10),          DebiteurPostcode nchar(40),            DebiteurPlaats nchar(40),    DebiteurLand nchar(40),
    DebiteurTelefoon nchar(25),            DebiteurTelefoon2 nchar(25),           DebiteurTelefax nchar(25),             DebiteurEmail nchar(80),     DebiteurEanCode nchar(13),
    KoppelingVervallen integer,
    // Betalingsconditie
    BtcNummer Integer,
    BtcOms nchar(40),
    //gegevens locatie/serienummer
    LocNaam nchar(20),                     LocOms nchar(40),                      ArtSerieNummer nchar(20)
    )
begin
  declare @TestAantEtiket                 SmallInt;
  declare @AantalEtikHeel                 Integer;
  declare @AantalEtikRest                 Integer;
  declare @AantalInkoopEenhPerEtiket      Numeric(15,3);
  declare @AantalVoorraadEenhPerEtiket    Numeric(15,3);
  declare @AantalInkoopEenhRestEtiket     Numeric(15,3);
  declare @AantalVoorraadEenhRestEtiket   Numeric(15,3);

  declare @EtiketTeller                   Integer;

  declare local temporary table tmpMagOntEtiket(
    SoortEtiket   SmallInt,               IsRestantEtiket SmallInt,     //0=normaal etiket, 1= etiket met restant
    //gegevens magazijnontvangstkop/regel
    MohkGid Integer,                      MokNummer Numeric(10,0),              MokOntvangstDatum DateTime,     MokOmschrijving nchar(40),
    MohrGid Integer,                      MagOntRegelNr Integer,
    //leveranciergegevens
    LevNummer nchar(10),                    LevZoekcode nchar(10),           LevNaam nchar(40),
    //Bestelgegeves
    BstKopNummer numeric(10,0),           BstRglNummer integer,                 BstRglOms Long nvarchar,         OmsBestelRegelOfArtikel Long nvarchar,
    //artikelgegevens
    ArtCode nchar(20),                     ArtZoekcode nchar(20),           ArtOms nchar(40),
    ArtAantDecAantallen Integer,          ArtAantDecPrijzen Integer,            ArtPrijsPer Numeric(15,3),
   	ArtIsGeblokkeerd SmallInt,            ArtIsGeblokkeerdInkoop SmallInt,      ArtOmsEenheid nchar(20),         ArtHeeftVoorraad SmallInt,
  	ArtGewichtPerEenheid Numeric(15,3),   ArtVolumePerEenheid Numeric(15,3),    ArtSerienrRegistreren SmallInt, ArtIsPartijRegistreren SmallInt,
    ArtAfbeeldingKlein nchar(80),          ArtAfbeeldingGroot nchar(80),          TekstOpFactuur Long nvarchar,    ArtOpmerking Long nvarchar,
   	OpbrGrpNummer nchar(4),                OpbrGrpOms nchar(40),                  DefaultEanCode nchar(30),
    MagOntArtCodeBijLeverancier nchar(20), MagOntEanCode nchar(30),
    //aantallen
    MagOntInkoopEenheid nchar(20),         MagOntVoorraadEenhedenInInkoopEenheid Numeric(15,3),                  InkEenhIsVrdEenh smallInt,
    MagOntAantalInkoopEenheden Numeric(15,3), MagOntAantalVoorraadEenheden  Numeric(15,3),
    AantalInkEenhEtiket Numeric(15,3),    AantalVrdkEenhEtiket Numeric(15,3),   //aantal eenheden per etiket

    //partijgegevens
    ArtPartijNummer nchar(20),             ArtPartijOms nchar(40),                ArtPartijNrBijLeverancier nchar(20),   ArtPartijOpm long nvarchar,
    ArtPartijDatumOntvangst DateTime,     ArtPartijTHTdatum DateTime,           ArtPartijVrijTmDatum DateTime,        ArtPartijVrijVanafDatum DateTime,
    ArtPartijDatumProductie DateTime,
    //Verkoopprijs artikel/partij
    BtwCodeVerkoop Integer,               BtwPercVerkoop Numeric(6,2),          VerkoopPrijsIsInclBTW SmallInt,
    VerkoopPrijsExclusief Numeric(15,3),  VerkoopPrijsInclusief Numeric(15,3),  SoortKorting SmallInt,
    KortingsBedragExclusief Numeric(15,3),KortingsBedragInclusief Numeric(15,3),KortingsPerc Numeric(5,2),
    //adviesprijs
    ArtIsAdviesPrijsInclBTW SmallInt,     AdviesPrijsExclusief Numeric(15,3),   AdviesPrijsInclusief Numeric(15,3),
    // cbs oorsprong
    CbsOorsprongLndEigenCode nchar(3),    CbsOorsprongLndOms nchar(40),
    //order/magazijnregelgegevens
    MagOntDetBrdSoort smallInt,           OrderNummer numeric(10,0),            OrderRegelNr integer,                 BackorderAantal Numeric(15,3),   BackorderLeverdatum DateTime,
    DebiteurNummer nchar(10),              DebiteurZoekcode nchar(10),            DebiteurNaam1 nchar(40),               DebiteurNaam2 nchar(40),
    DebiteurStraat nchar(40),              DebiteurHuisnummer nchar(10),          DebiteurPostcode nchar(40),            DebiteurPlaats nchar(40),    DebiteurLand nchar(40),
    DebiteurTelefoon nchar(25),            DebiteurTelefoon2 nchar(25),           DebiteurTelefax nchar(25),             DebiteurEmail nchar(80),     DebiteurEanCode nchar(13),
    KoppelingVervallen integer,

    // Betalingsconditie
    BtcNummer Integer,
    BtcOms nchar(40),

    //gegevens lacatie/serienummer
    LocNaam nchar(20),                     LocOms nchar(40),                      ArtSerieNummer nchar(20)

  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'Begin rapMagOntEtiket > ';
  //call Trace(@@ErrorTextProcedure);

  //======================================================== alle ontvangstregels doorlopen ========================================================
  for @Cursor AS cursor_OntvangstRegels cursor for
    select
      MohkGid                 @curMohkGid,
      MohkNummer              @curMokNummer,
      MohkOntvangstDatum      @curMokOntvangstDatum,
      MohkOmschrijving        @curMokOmschrijving,
      MohkBtcNummer           @BtcNummer,
      MohkBtcOms              @BtcOms,
      MohrGid                 @curMohrGid,
      MohrRegelNr             @curMagOntRegelNr,
      //NawGid                  @curNawGid,
      MohaNawFilNummer        @curNawFilNummer,
      MohaNawFilZoekcode      @curNawFilZoekcode,
      MohaNaam1               @curNawNaam,
      MohrBstKopNummer        @BstKopNummer,
      MohrBstRglNummer        @BstRglNummer,
      MohrBstlRglOms          @BstRglOms,
      (if IsNull(MohrBstlRglOms,'')<>'' then MohrBstlRglOms else MohrArtOms endif) @OmsBestelRegelOfArtikel,
      MohrArtCode             @curArtCode,
      MohrArtZoekCode         @curArtZoekcode,
      MohrArtOms              @curArtOms,
      MohrAantDecAantal       @curArtAantDecAantallen,
      MohrAantDecBedrag       @curArtAantDecPrijzen,
    	MohrPrijsPer            @curArtPrijsPer,
     	MohrArtIsGeblokkeerd        @curArtIsGeblokkeerd,
      MohrArtIsGeblokkeerdInkoop  @curArtIsGeblokkeerdInkoop,
    	MohrArtOmsEenheid           @curArtOmsEenheid,
    	MohrArtHeeftVoorraad        @curArtHeeftVoorraad,
    	MohrArtGewichtPerEenheid    @curArtGewichtPerEenheid,
    	MohrArtVolumePerEenheid     @curArtVolumePerEenheid,
    	MohrArtSerieNrRegistreren   @curArtSerienrRegistreren,
    	MohrArtIsPartijRegistreren  @curArtIsPartijRegistreren,
      MohrArtAfbeeldingKlein      @curArtAfbeeldingKlein,
      MohrArtAfbeeldingGroot      @curArtAfbeeldingGroot,


      //tekst op factuur bepalen van artikel
      IsNull((select first MohratTekst from tabMagazijnOntvangstHistRglArtTekst where MohratMohrGid = MohrGid and MohratTaalCode = @TaalCodeSelectie),
             (select first MohratTekst from tabMagazijnOntvangstHistRglArtTekst where MohratMohrGid = MohrGid and MohratTaalCode = (select first TaalCode from tabVasteGegevensOrdersFactureren inner join tabTaal on TaalGid = vofTekstOpFactuurTaalGid))) @curTekstOpFactuurArtikel,
      /*
      (if (select first ArtTekst from tabArtikelTeksten right outer join tabTaal on ArtTaalGid = TaalGid where ArtTekstArtGid = ArtGid and TaalCode = @TaalCodeSelectie) is null
        then (select first ArtTekst from tabArtikelTeksten where ArtTekstArtGid = ArtGid and ArtTaalGid = (select first vofTekstOpFactuurTaalGid from tabVasteGegevensOrdersFactureren))
        else (select first ArtTekst from tabArtikelTeksten right outer join tabTaal on ArtTaalGid = TaalGid where ArtTekstArtGid = ArtGid and TaalCode = @TaalCodeSelectie)
      endif) @curTekstOpFactuurArtikel,
      */

      //tekst op factuur bepalen van partij
      IsNull((select first MohrptTekst from tabMagazijnOntvangstHistRglPartTekst where MohrptMohrGid = MohrGid and MohrptTaalCode = @TaalCodeSelectie),
             (select first MohrptTekst from tabMagazijnOntvangstHistRglPartTekst where MohrptMohrGid = MohrGid and MohrptTaalCode = (select first TaalCode from tabVasteGegevensOrdersFactureren inner join tabTaal on TaalGid = vofTekstOpFactuurTaalGid))) @curTekstOpFactuurPartij,
      /*
      (if (select first ArtPartijTekstOpFactuur from tabArtikelPartijTeksten right outer join tabTaal on ArtPartijTekstTaalGid = TaalGid where ArtPartijTekstArtPartijGid = ArtPartijGid and TaalCode = @TaalCodeSelectie) is null
        then (select first ArtPartijTekstOpFactuur from tabArtikelPartijTeksten where ArtPartijTekstArtPartijGid = ArtPartijGid and ArtPartijTekstTaalGid = (select first vofTekstOpFactuurTaalGid from tabVasteGegevensOrdersFactureren))
        else (select first ArtPartijTekstOpFactuur from tabArtikelPartijTeksten right outer join tabTaal on ArtPartijTekstTaalGid = TaalGid where ArtPartijTekstArtPartijGid = ArtPartijGid and TaalCode = @TaalCodeSelectie)
      endif) @curTekstOpFactuurPartij,
      */
      //tekst op factuur Partij/artikel
      IsNull(@curTekstOpFactuurPartij, @curTekstOpFactuurArtikel) @curTekstOpFactuur,

      //opmerking
      MohrArtOpmerking @curArtOpmerking,

      MohrOpbrGrpNummer       @curOpbrGrpNummer,
  	  MohrOpbrGrpOms          @curOpbrGrpOms,
      MohrArtDefaultEanCode  @curDefaultEanCode,

      MohrArtCodeBijLeverancier           @curMagOntArtCodeBijLeverancier,
      MohrEanCode                         @curMagOntEanCode,

      //aantallen
      MohrInkoopEenheid                   @curMagOntInkoopEenheid,
      MohrVoorraadEenhedenInInkoopEenheid @curMagOntVoorraadEenhedenInInkoopEenheid,
      (if (MohrInkoopEenheid = MohrArtOmsEenheid) and (MohrVoorraadEenhedenInInkoopEenheid = 1) then 1 else 0 endif) @curInkEenhIsVrdEenh,

      MohrAantalInkoopEenheden            @curMagOntAantalInkoopEenheden,
      MohrAantal                          @curMagOntAantalVoorraadEenheden,

      //partijgegevens
      MohrArtPartijNummer                       @curArtPartijNummer,
      MohrArtPartijOms                          @curArtPartijOms,
      MohrArtPartijNrBijLeverancier             @curArtPartijNrBijLeverancier,
      MohrArtPartijOpm                          @curArtPartijOpm,
      MohrArtPartijDatumOntvangst               @curArtPartijDatumOntvangst,
      MohrArtPartijTHTdatum                     @curArtPartijTHTdatum,
      MohrArtPartijVrijTmDatum                  @curArtPartijVrijTmDatum,
      MohrArtPartijVrijVanafDatum               @curArtPartijVrijVanafDatum,
      MohrArtPartijDatumProductie               @curArtPartijDatumProductie,


      //Verkoopprijs artikel/partij
      //Indien partij eigen verkoopprijs heeft, dan die prijsgegevens gebruiken ipv die van artikel

      //BTW-code en percentage
      MohrBtwCodeVerkoop @curBtwCodeVerkoop,
      MohrBtwPercVerkoop @curBtwPercVerkoop,

      //verkprijs in of ex BVTW?
      MohrVerkoopPrijsIsInclBTW @curVerkoopPrijsIsInclBTW,

       //verkoopprijs excl. BTW
      MohrVerkoopPrijsExclusief @curVerkoopPrijsExclusief,
       //verkoopprijs incl. BTW
      MohrVerkoopPrijsInclusief @curVerkoopPrijsInclusief,

      //kortingspercentage of bedrag?
      MohrKortingSoortArtDef @curSoortKorting,

      //Kortingsbedrag excl. BTW
      MohrKortingsBedragExclusiefArtDef @curKortingsBedragExclusief,
      //Kortingsbedrag incl. BTW
      MohrKortingsBedragInclusiefArtDef @curKortingsBedragInclusief,

      //kortingspercentage indien van soort percentage : @curSoortKorting = 1 anders 0.00
      MohrKortingsPercArtDef @curKortingsPerc,

      //adviesprijs
      MohrArtIsAdviesPrijsInclBtw @curArtIsAdviesPrijsInclBTW,

      MohrAdviesPrijsExclusief @curAdviesPrijsExclusief,

      MohrAdviesPrijsInclusief @curAdviesPrijsInclusief,

      MohrCbsOorsprongLndEigenCode @curCbsOorsprongLndEigenCode,
      MohrCbsOorsprongLndOms       @curCbsOorsprongLndOms

    from
      tabMagazijnOntvangstHistBatch
      inner join tabMagazijnOntvangstHistKop on (MohkMohbGid = MohbGid)
      inner join tabMagazijnontvangstHistRegel on (MohrMohkGid = MohkGid) and (MohrAantal > 0)
      left outer join tabMagazijnOntvangstHistAdres on (MohkMohaGidLeverancier = MohaGid)
    where (@MohbGid is not null and MohbGid = @MohbGid) or (MohkGid = @MohkGid)
    order by
      MohkNummer, MohrRegelnr
  for read only
  do

    //================================================ alle order/magazijnregels doorlopen ========================================================
    for @Cursor AS cursor_OrdersEnMagazijn cursor for
      select
        MohdGid                                     @MohdGid,
        MohdMohrGid                                 @MohdMohrGid,
        MohdBrdGid                                  @curMagOntDetBrdGid,
        MohdBrdSoort                                @curMagOntDetBrdSoort,
        MohdOrkNummer                               @curOrderNummer,
        MohdOrrRegelNr                              @curOrderRegelNr,
        MohdAantalBackorder                         @curBackorderAantal,
        MohdLeverDatum                              @curBackorderLeverdatum,
        MohaNawFilNummer                            @curDebiteurNummer,
        MohaNaam1                                   @curDebiteurNaam1,
        MohaNaam2                                   @curDebiteurNaam2,
        MohaNawFilZoekcode                          @curDebiteurZoekcode,
        MohaStraat                                  @curDebiteurStraat,
        MohaHuisnummer                              @curDebiteurHuisnummer,
        MohaPostcode                                @curDebiteurPostcode,
        MohaPlaats                                  @curDebiteurPlaats,
        MohaLndOms                                  @curDebiteurLand,
        MohaTelefoon                                @curDebiteurTelefoon,
        MohaTelefoon2                               @curDebiteurTelefoon2,
        MohaTelefax                                 @curDebiteurTelefax,
        MohaEmail                                   @curDebiteurEmail,
        MohaEanCode                                 @curDebiteurEanCode,
        (Select sum(MohlAantal) from tabMagazijnOntvangstHistLocatieSerie where MohlMohdGid = MohdGid) @curOrdMagAantalVoorraadeenheden,
        if ((BrdSoort = 1) or (MohdBrdSoort = 1)) and ((BrdOrrGid is null or MohdBrdSoort is null)) then 1 else 0 endif @curKoppelingVervallen
      from
        tabMagazijnOntvangstHistDetail
        left outer join tabBestelRegelDetail on (brdGid = MohdbrdGid)
        left outer join tabMagazijnOntvangstHistAdres on (MohdMohaGid = MohaGid)
      where
        MohdMohrGid = @curMohrGid
      order by
        @curMagOntDetBrdSoort DESC, @curOrderNummer, @curOrderRegelNr
    for read only
    do

      //================================================ alle locaties/serienummers doorlopen ========================================================
      for @Cursor AS cursor_LocatiesSerienummers cursor for
        Select
          MohlLocNaam           @curLocNaam,
          MohlLocOms            @curLocOms,
          MohlArtSerieNummer    @curArtSerieNummer,
          MohlAantal            @curMagOntLocAantalVoorraadEenheden
        From
          tabMagazijnOntvangstHistLocatieSerie
        Where
        	MohlMohdGid = @MohdGid
        order by
          @curLocNaam, @curArtSerieNummer
      for read only
      do

        //Locatie/serienummerregel(s) toevoegen
        Set @TestAantEtiket = (if @curMagOntDetBrdSoort = 1 then @AantEtikLocOrd else @AantEtikLocMag endif);  //1=verkooporder 0=magazijnregel

        set @AantalEtikHeel = 0;
        set @AantalEtikRest = 0;
        Set @AantalInkoopEenhPerEtiket    =(@curMagOntLocAantalVoorraadEenheden / @curMagOntVoorraadEenhedenInInkoopEenheid);
        Set @AantalVoorraadEenhPerEtiket  = @curMagOntLocAantalVoorraadEenheden;
        Set @AantalInkoopEenhRestEtiket   = 0;
        Set @AantalVoorraadEenhRestEtiket = 0;

        case @TestAantEtiket
          when 0 then       // geen etiket, alles staat al netjes op 0
          when 1 then       // één etiket
            begin
              set @AantalEtikHeel = 1;
              set @AantalEtikRest = 0;
              Set @AantalInkoopEenhPerEtiket    =(@curMagOntLocAantalVoorraadEenheden / @curMagOntVoorraadEenhedenInInkoopEenheid);
              Set @AantalVoorraadEenhPerEtiket  = @curMagOntLocAantalVoorraadEenheden;
              Set @AantalInkoopEenhRestEtiket   = 0;
              Set @AantalVoorraadEenhRestEtiket = 0;
            end;
          when 2 then       // één etiket per inkoopeenheid
            begin
              set @AantalEtikHeel = TruncNum((@curMagOntLocAantalVoorraadEenheden / @curMagOntVoorraadEenhedenInInkoopEenheid),0);
              set @AantalEtikRest = (if @AantalEtikHeel = Round((@curMagOntLocAantalVoorraadEenheden / @curMagOntVoorraadEenhedenInInkoopEenheid), @curArtAantDecAantallen) then 0 else 1 endif);
              Set @AantalInkoopEenhPerEtiket    = 1;
              Set @AantalVoorraadEenhPerEtiket  = @curMagOntVoorraadEenhedenInInkoopEenheid;
              Set @AantalInkoopEenhRestEtiket   = (if @AantalEtikRest = 0 then 0 else ((@curMagOntLocAantalVoorraadEenheden / @curMagOntVoorraadEenhedenInInkoopEenheid) - @AantalEtikHeel) endif);
              Set @AantalVoorraadEenhRestEtiket = (if @AantalEtikRest = 0 then 0 else (@curMagOntLocAantalVoorraadEenheden - (@AantalEtikHeel * @curMagOntVoorraadEenhedenInInkoopEenheid)) endif);
            end;
          when 3 then       // één etiket per voorraadeenheid
            begin
              set @AantalEtikHeel = TruncNum(@curMagOntLocAantalVoorraadEenheden,0);
              set @AantalEtikRest = (if @AantalEtikHeel = Round(@curMagOntLocAantalVoorraadEenheden, @curArtAantDecAantallen) then 0 else 1 endif);
              Set @AantalVoorraadEenhPerEtiket  = 1;
              Set @AantalInkoopEenhPerEtiket    = 1 / @curMagOntVoorraadEenhedenInInkoopEenheid;
              Set @AantalVoorraadEenhRestEtiket = (if @AantalEtikRest = 0 then 0 else (@curMagOntLocAantalVoorraadEenheden - @AantalEtikHeel) endif);
              Set @AantalInkoopEenhRestEtiket   = (if @AantalEtikRest = 0 then 0 else (@AantalVoorraadEenhRestEtiket / @curMagOntVoorraadEenhedenInInkoopEenheid) endif);
            end;
        end case;

        //Locatie/serienummerregel toevoegen van hele inkoop/voorraad eenheden?
        set @EtiketTeller = 1;
        while @EtiketTeller <= @AantalEtikHeel loop

          insert into tmpMagOntEtiket(
                    SoortEtiket, IsRestantEtiket, MohkGid, MokNummer, MokOntvangstDatum, MokOmschrijving, MohrGid, MagOntRegelNr,
                    LevNummer, LevZoekcode, LevNaam, BstKopNummer, BstRglNummer, BstRglOms, OmsBestelRegelOfArtikel,
                    ArtCode, ArtZoekcode, ArtOms, ArtAantDecAantallen, ArtAantDecPrijzen, ArtPrijsPer,
                    ArtIsGeblokkeerd, ArtIsGeblokkeerdInkoop, ArtOmsEenheid, ArtHeeftVoorraad, ArtGewichtPerEenheid, ArtVolumePerEenheid,
                    ArtSerienrRegistreren, ArtIsPartijRegistreren, ArtAfbeeldingKlein, ArtAfbeeldingGroot, TekstOpFactuur, ArtOpmerking,
                    OpbrGrpNummer, OpbrGrpOms, DefaultEanCode, MagOntArtCodeBijLeverancier, MagOntEanCode,
                    MagOntInkoopEenheid, MagOntVoorraadEenhedenInInkoopEenheid, InkEenhIsVrdEenh,
                    MagOntAantalInkoopEenheden, MagOntAantalVoorraadEenheden, AantalInkEenhEtiket, AantalVrdkEenhEtiket,
                    ArtPartijNummer, ArtPartijOms, ArtPartijNrBijLeverancier, ArtPartijOpm,
                    ArtPartijDatumOntvangst, ArtPartijTHTdatum, ArtPartijVrijTmDatum, ArtPartijVrijVanafDatum, ArtPartijDatumProductie,
                    BtwCodeVerkoop, BtwPercVerkoop, VerkoopPrijsIsInclBTW, VerkoopPrijsExclusief, VerkoopPrijsInclusief,
                    SoortKorting, KortingsBedragExclusief, KortingsBedragInclusief, KortingsPerc,
                    ArtIsAdviesPrijsInclBTW, AdviesPrijsExclusief, AdviesPrijsInclusief,
                    CbsOorsprongLndEigenCode, CbsOorsprongLndOms,
