                    @curMagOntDetBrdSoort, @curOrderNummer, @curOrderRegelNr, @curBackorderAantal, @curBackorderLeverdatum,
                    @curDebiteurNummer, @curDebiteurZoekcode, @curDebiteurNaam1, @curDebiteurNaam2, @curDebiteurStraat, @curDebiteurHuisnummer,
                    @curDebiteurPostcode, @curDebiteurPlaats, @curDebiteurLand, @curDebiteurTelefoon, @curDebiteurTelefoon2, @curDebiteurTelefax,  @curDebiteurEmail, @curDebiteurEanCode,
                    @curKoppelingVervallen,
                    // Betalingsconditie
                    @BtcNummer, @BtcOms,
                    //gegevens lacatie/serienummer
                    @curLocNaam, @curLocOms, @curArtSerieNummer);

          set @EtiketTeller = @EtiketTeller + 1;
        end loop;

        //Locatie/serienummerregel toevoegen van restant inkoop/voorraad eenheden?
        if @AantalEtikRest <> 0 then

          insert into tmpMagOntEtiket(
                    SoortEtiket, IsRestantEtiket, MohkGid, MokNummer, MokOntvangstDatum, MokOmschrijving, MohrGid, MagOntRegelNr,
                    LevNummer, LevZoekcode, LevNaam, BstKopNummer, BstRglNummer, BstRglOms, OmsBestelRegelOfArtikel,
                    ArtCode, ArtZoekcode, ArtOms, ArtAantDecAantallen, ArtAantDecPrijzen, ArtPrijsPer,
                    ArtIsGeblokkeerd, ArtIsGeblokkeerdInkoop, ArtOmsEenheid, ArtHeeftVoorraad, ArtGewichtPerEenheid, ArtVolumePerEenheid,
                    ArtSerienrRegistreren, ArtIsPartijRegistreren, ArtAfbeeldingKlein, ArtAfbeeldingGroot, TekstOpFactuur, ArtOpmerking,
