                    @curDebiteurPostcode, @curDebiteurPlaats, @curDebiteurLand, @curDebiteurTelefoon, @curDebiteurTelefoon2, @curDebiteurTelefax,  @curDebiteurEmail, @curDebiteurEanCode,
                    @curKoppelingVervallen,
                    // Betalingsconditie
                    @BtcNummer, @BtcOms,
                    //gegevens lacatie/serienummer
                    @curLocNaam, @curLocOms, @curArtSerieNummer);

        end if;

      end for;  //cursor_LocatiesSerienummers
      //------------------------------------------------ einde alle locaties/serienummers doorlopen --------------------------------------------------


      //Order/magazijn specificatieregel(s) toevoegen

      Set @TestAantEtiket = (if @curMagOntDetBrdSoort = 1 then @AantEtikOrdOrd else @AantEtikOrdMag endif);  //1=verkooporder 0=magazijnregel

      set @AantalEtikHeel = 0;
      set @AantalEtikRest = 0;
      Set @AantalInkoopEenhPerEtiket    =(@curOrdMagAantalVoorraadeenheden / @curMagOntVoorraadEenhedenInInkoopEenheid);
      Set @AantalVoorraadEenhPerEtiket  = @curOrdMagAantalVoorraadeenheden;
      Set @AantalInkoopEenhRestEtiket   = 0;
      Set @AantalVoorraadEenhRestEtiket = 0;

      case @TestAantEtiket
        when 0 then       // geen etiket, alles staat al netjes op 0
        when 1 then       // één etiket
          begin
            set @AantalEtikHeel = 1;
            set @AantalEtikRest = 0;
            Set @AantalInkoopEenhPerEtiket    =(@curOrdMagAantalVoorraadeenheden / @curMagOntVoorraadEenhedenInInkoopEenheid);
            Set @AantalVoorraadEenhPerEtiket  = @curOrdMagAantalVoorraadeenheden;
            Set @AantalInkoopEenhRestEtiket   = 0;
            Set @AantalVoorraadEenhRestEtiket = 0;
          end;
        when 2 then       // één etiket per inkoopeenheid
          begin
            set @AantalEtikHeel = TruncNum((@curOrdMagAantalVoorraadeenheden / @curMagOntVoorraadEenhedenInInkoopEenheid),0);
            set @AantalEtikRest = (if @AantalEtikHeel = Round((@curOrdMagAantalVoorraadeenheden / @curMagOntVoorraadEenhedenInInkoopEenheid), @curArtAantDecAantallen) then 0 else 1 endif);
            Set @AantalInkoopEenhPerEtiket    = 1;
            Set @AantalVoorraadEenhPerEtiket  = @curMagOntVoorraadEenhedenInInkoopEenheid;
            Set @AantalInkoopEenhRestEtiket   = (if @AantalEtikRest = 0 then 0 else ((@curOrdMagAantalVoorraadeenheden / @curMagOntVoorraadEenhedenInInkoopEenheid) - @AantalEtikHeel) endif);
            Set @AantalVoorraadEenhRestEtiket = (if @AantalEtikRest = 0 then 0 else (@curOrdMagAantalVoorraadeenheden - (@AantalEtikHeel * @curMagOntVoorraadEenhedenInInkoopEenheid)) endif);
          end;
        when 3 then       // één etiket per voorraadeenheid
          begin
            set @AantalEtikHeel = TruncNum(@curOrdMagAantalVoorraadeenheden,0);
            set @AantalEtikRest = (if @AantalEtikHeel = Round(@curOrdMagAantalVoorraadeenheden, @curArtAantDecAantallen) then 0 else 1 endif);
            Set @AantalVoorraadEenhPerEtiket  = 1;
            Set @AantalInkoopEenhPerEtiket    = 1 / @curMagOntVoorraadEenhedenInInkoopEenheid;
            Set @AantalVoorraadEenhRestEtiket = (if @AantalEtikRest = 0 then 0 else (@curOrdMagAantalVoorraadeenheden - @AantalEtikHeel) endif);
            Set @AantalInkoopEenhRestEtiket   = (if @AantalEtikRest = 0 then 0 else (@AantalVoorraadEenhRestEtiket / @curMagOntVoorraadEenhedenInInkoopEenheid) endif);
          end;
      end case;

      //order/magazijnregel toevoegen van hele inkoop/voorraad eenheden?
      set @EtiketTeller = 1;
      while @EtiketTeller <= @AantalEtikHeel loop

        insert into tmpMagOntEtiket(
                SoortEtiket, IsRestantEtiket, MohkGid, MokNummer, MokOntvangstDatum, MokOmschrijving, MohrGid, MagOntRegelNr,
                LevNummer, LevZoekcode, LevNaam, BstKopNummer, BstRglNummer, BstRglOms, OmsBestelRegelOfArtikel,
