                ArtPartijNummer, ArtPartijOms, ArtPartijNrBijLeverancier, ArtPartijOpm,
                ArtPartijDatumOntvangst, ArtPartijTHTdatum, ArtPartijVrijTmDatum, ArtPartijVrijVanafDatum, ArtPartijDatumProductie,
                BtwCodeVerkoop, BtwPercVerkoop, VerkoopPrijsIsInclBTW, VerkoopPrijsExclusief, VerkoopPrijsInclusief,
                SoortKorting, KortingsBedragExclusief, KortingsBedragInclusief, KortingsPerc,
                ArtIsAdviesPrijsInclBTW, AdviesPrijsExclusief, AdviesPrijsInclusief,
                //gegevens order/magazijnregel
                MagOntDetBrdSoort, OrderNummer, OrderRegelNr, BackorderAantal, BackorderLeverdatum,
                DebiteurNummer, DebiteurZoekcode, DebiteurNaam1, DebiteurNaam2, DebiteurStraat, DebiteurHuisnummer,
                DebiteurPostcode, DebiteurPlaats, DebiteurLand, DebiteurTelefoon, DebiteurTelefoon2, DebiteurTelefax,  DebiteurEmail, DebiteurEanCode,
                KoppelingVervallen,
                // Betalingsconditie
                BtcNummer, BtcOms,
                //gegevens lacatie/serienummer
                LocNaam, LocOms, ArtSerieNummer)
        values( 1, 0, @curMohkGid, @curMokNummer, @curMokOntvangstDatum, @curMokOmschrijving, @curMohrGid, @curMagOntRegelNr,
                @curNawFilNummer, @curNawFilZoekcode, @curNawNaam, @BstKopNummer, @BstRglNummer, @BstRglOms, @OmsBestelRegelOfArtikel,
                @curArtCode, @curArtZoekcode, @curArtOms, @curArtAantDecAantallen, @curArtAantDecPrijzen, @curArtPrijsPer,
