                @curKoppelingVervallen,
                // Betalingsconditie
                @BtcNummer, @BtcOms,
                //gegevens locatie/serienummer
                Null, Null, Null);
        set @EtiketTeller = @EtiketTeller + 1;
      end loop;

      //order/magazijnregel toevoegen van restant inkoop/voorraad eenheden?
      if @AantalEtikRest <> 0 then
        insert into tmpMagOntEtiket(
                SoortEtiket, IsRestantEtiket, MohkGid, MokNummer, MokOntvangstDatum, MokOmschrijving, MohrGid, MagOntRegelNr,
                LevNummer, LevZoekcode, LevNaam, BstKopNummer, BstRglNummer, BstRglOms, OmsBestelRegelOfArtikel,
                ArtCode, ArtZoekcode, ArtOms, ArtAantDecAantallen, ArtAantDecPrijzen, ArtPrijsPer,
                ArtIsGeblokkeerd, ArtIsGeblokkeerdInkoop, ArtOmsEenheid, ArtHeeftVoorraad, ArtGewichtPerEenheid, ArtVolumePerEenheid,
                ArtSerienrRegistreren, ArtIsPartijRegistreren, ArtAfbeeldingKlein, ArtAfbeeldingGroot, TekstOpFactuur, ArtOpmerking,
                OpbrGrpNummer, OpbrGrpOms, DefaultEanCode, MagOntArtCodeBijLeverancier, MagOntEanCode,
                MagOntInkoopEenheid, MagOntVoorraadEenhedenInInkoopEenheid, InkEenhIsVrdEenh,
                MagOntAantalInkoopEenheden, MagOntAantalVoorraadEenheden, AantalInkEenhEtiket, AantalVrdkEenhEtiket,
                ArtPartijNummer, ArtPartijOms, ArtPartijNrBijLeverancier, ArtPartijOpm,
                ArtPartijDatumOntvangst, ArtPartijTHTdatum, ArtPartijVrijTmDatum, ArtPartijVrijVanafDatum, ArtPartijDatumProductie,
                BtwCodeVerkoop, BtwPercVerkoop, VerkoopPrijsIsInclBTW, VerkoopPrijsExclusief, VerkoopPrijsInclusief,
                SoortKorting, KortingsBedragExclusief, KortingsBedragInclusief, KortingsPerc,
                ArtIsAdviesPrijsInclBTW, AdviesPrijsExclusief, AdviesPrijsInclusief,
