                DebiteurPostcode, DebiteurPlaats, DebiteurLand, DebiteurTelefoon, DebiteurTelefoon2, DebiteurTelefax,  DebiteurEmail, DebiteurEanCode,
                KoppelingVervallen,
                // Betalingsconditie
                BtcNummer, BtcOms,
                //gegevens locatie/serienummer
                LocNaam, LocOms, ArtSerieNummer)
        values( 1, 1, @curMohkGid, @curMokNummer, @curMokOntvangstDatum, @curMokOmschrijving, @curMohrGid, @curMagOntRegelNr,
                @curNawFilNummer, @curNawFilZoekcode, @curNawNaam, @BstKopNummer, @BstRglNummer, @BstRglOms, @OmsBestelRegelOfArtikel,
                @curArtCode, @curArtZoekcode, @curArtOms, @curArtAantDecAantallen, @curArtAantDecPrijzen, @curArtPrijsPer,
                @curArtIsGeblokkeerd, @curArtIsGeblokkeerdInkoop, @curArtOmsEenheid, @curArtHeeftVoorraad, @curArtGewichtPerEenheid, @curArtVolumePerEenheid,
                @curArtSerienrRegistreren, @curArtIsPartijRegistreren, @curArtAfbeeldingKlein, @curArtAfbeeldingGroot, @curTekstOpFactuur, @curArtOpmerking,
                @curOpbrGrpNummer, @curOpbrGrpOms, @curDefaultEanCode, @curMagOntArtCodeBijLeverancier, @curMagOntEanCode,
                @curMagOntInkoopEenheid, @curMagOntVoorraadEenhedenInInkoopEenheid, @curInkEenhIsVrdEenh,
                //!!!!!!!!!!!!!!!!!!!! Aantal stuks van order/magazijnregel !!!!!!!!!!!!!!!!!!!!
               (@curOrdMagAantalVoorraadeenheden / @curMagOntVoorraadEenhedenInInkoopEenheid), @curOrdMagAantalVoorraadeenheden, @AantalInkoopEenhRestEtiket, @AantalVoorraadEenhRestEtiket,
                @curArtPartijNummer, @curArtPartijOms, @curArtPartijNrBijLeverancier, @curArtPartijOpm,
                @curArtPartijDatumOntvangst, @curArtPartijTHTdatum, @curArtPartijVrijTmDatum, @curArtPartijVrijVanafDatum, @curArtPartijDatumProductie,
                @curBtwCodeVerkoop, @curBtwPercVerkoop, @curVerkoopPrijsIsInclBTW, @curVerkoopPrijsExclusief, @curVerkoopPrijsInclusief,
                @curSoortKorting, @curKortingsBedragExclusief, @curKortingsBedragInclusief, @curKortingsPerc,
                @curArtIsAdviesPrijsInclBTW, @curAdviesPrijsExclusief, @curAdviesPrijsInclusief,
                //gegevens order/magazijnregel
                @curMagOntDetBrdSoort, @curOrderNummer, @curOrderRegelNr, @curBackorderAantal, @curBackorderLeverdatum,
                @curDebiteurNummer, @curDebiteurZoekcode, @curDebiteurNaam1, @curDebiteurNaam2, @curDebiteurStraat, @curDebiteurHuisnummer,
                @curDebiteurPostcode, @curDebiteurPlaats, @curDebiteurLand, @curDebiteurTelefoon, @curDebiteurTelefoon2, @curDebiteurTelefax,  @curDebiteurEmail, @curDebiteurEanCode,
                @curKoppelingVervallen,
                // Betalingsconditie
                @BtcNummer, @BtcOms,
                //gegevens locatie/serienummer
                Null, Null, Null);
      end if;

    end for;  //cursor_OrdersEnMagazijn
    //------------------------------------------------- einde alle order/magazijnregels doorlopen -------------------------------------------------------

    set @AantalEtikHeel = 0;
    set @AantalEtikRest = 0;
    Set @AantalInkoopEenhPerEtiket    = @curMagOntAantalInkoopEenheden;
    Set @AantalVoorraadEenhPerEtiket  = @curMagOntAantalVoorraadEenheden;
    Set @AantalInkoopEenhRestEtiket   = 0;
    Set @AantalVoorraadEenhRestEtiket = 0;

    case @AantEtikOntvangstregel
      when 0 then       // geen etiket, alles staat al netjes op 0
      when 1 then       // één etiket
        begin
          set @AantalEtikHeel = 1;
          set @AantalEtikRest = 0;
          Set @AantalInkoopEenhPerEtiket    = @curMagOntAantalInkoopEenheden;
          Set @AantalVoorraadEenhPerEtiket  = @curMagOntAantalVoorraadEenheden;
          Set @AantalInkoopEenhRestEtiket   = 0;
          Set @AantalVoorraadEenhRestEtiket = 0;
        end;
      when 2 then       // één etiket per inkoopeenheid
        begin
          set @AantalEtikHeel = TruncNum(@curMagOntAantalInkoopEenheden,0);
          set @AantalEtikRest = (if @AantalEtikHeel = Round(@curMagOntAantalInkoopEenheden, @curArtAantDecAantallen) then 0 else 1 endif);
          Set @AantalInkoopEenhPerEtiket    = 1;
          Set @AantalVoorraadEenhPerEtiket  = @curMagOntVoorraadEenhedenInInkoopEenheid;
          Set @AantalInkoopEenhRestEtiket   = (if @AantalEtikRest = 0 then 0 else (@curMagOntAantalInkoopEenheden - @AantalEtikHeel) endif);
          Set @AantalVoorraadEenhRestEtiket = (if @AantalEtikRest = 0 then 0 else (@curMagOntAantalVoorraadEenheden - (@AantalEtikHeel * @curMagOntVoorraadEenhedenInInkoopEenheid)) endif);

        end;
      when 3 then       // één etiket per voorraadeenheid
        begin
          set @AantalEtikHeel = TruncNum(@curMagOntAantalVoorraadEenheden,0);
          set @AantalEtikRest = (if @AantalEtikHeel = Round(@curMagOntAantalVoorraadEenheden, @curArtAantDecAantallen) then 0 else 1 endif);
          Set @AantalVoorraadEenhPerEtiket  = 1;
          Set @AantalInkoopEenhPerEtiket    = 1 / @curMagOntVoorraadEenhedenInInkoopEenheid;
          Set @AantalVoorraadEenhRestEtiket = (if @AantalEtikRest = 0 then 0 else (@curMagOntAantalVoorraadEenheden - @AantalEtikHeel) endif);
          Set @AantalInkoopEenhRestEtiket   = (if @AantalEtikRest = 0 then 0 else (@AantalVoorraadEenhRestEtiket / @curMagOntVoorraadEenhedenInInkoopEenheid) endif);
        end;
    end case;

    //magazijnontvangstregel toevoegen van hele inkoop/voorraad eenheden?
    set @EtiketTeller = 1;
    while @EtiketTeller <= @AantalEtikHeel loop
      insert into tmpMagOntEtiket(
                  SoortEtiket, IsRestantEtiket, MohkGid, MokNummer, MokOntvangstDatum, MokOmschrijving, MohrGid, MagOntRegelNr,
                  LevNummer, LevZoekcode, LevNaam, BstKopNummer, BstRglNummer, BstRglOms, OmsBestelRegelOfArtikel,
                  ArtCode, ArtZoekcode, ArtOms, ArtAantDecAantallen, ArtAantDecPrijzen, ArtPrijsPer,
                  ArtIsGeblokkeerd, ArtIsGeblokkeerdInkoop, ArtOmsEenheid, ArtHeeftVoorraad, ArtGewichtPerEenheid, ArtVolumePerEenheid,
                  ArtSerienrRegistreren, ArtIsPartijRegistreren, ArtAfbeeldingKlein, ArtAfbeeldingGroot, TekstOpFactuur, ArtOpmerking,
                  OpbrGrpNummer, OpbrGrpOms, DefaultEanCode, MagOntArtCodeBijLeverancier, MagOntEanCode,
                  MagOntInkoopEenheid, MagOntVoorraadEenhedenInInkoopEenheid, InkEenhIsVrdEenh,
                  //Aantal stuks van magazijnontvangstregel
                  MagOntAantalInkoopEenheden, MagOntAantalVoorraadEenheden, AantalInkEenhEtiket, AantalVrdkEenhEtiket,
                  ArtPartijNummer, ArtPartijOms, ArtPartijNrBijLeverancier, ArtPartijOpm,
                  ArtPartijDatumOntvangst, ArtPartijTHTdatum, ArtPartijVrijTmDatum, ArtPartijVrijVanafDatum, ArtPartijDatumProductie,
                  BtwCodeVerkoop, BtwPercVerkoop, VerkoopPrijsIsInclBTW, VerkoopPrijsExclusief, VerkoopPrijsInclusief,
                  SoortKorting, KortingsBedragExclusief, KortingsBedragInclusief, KortingsPerc,
                  ArtIsAdviesPrijsInclBTW, AdviesPrijsExclusief, AdviesPrijsInclusief,
                  //gegevens order/magazijnregel
                  MagOntDetBrdSoort, OrderNummer, OrderRegelNr, BackorderAantal, BackorderLeverdatum,
                  DebiteurNummer, DebiteurZoekcode, DebiteurNaam1, DebiteurNaam2, DebiteurStraat, DebiteurHuisnummer,
                  DebiteurPostcode, DebiteurPlaats, DebiteurLand, DebiteurTelefoon, DebiteurTelefoon2, DebiteurTelefax,  DebiteurEmail, DebiteurEanCode,
                  KoppelingVervallen,
                  // Betalingsconditie
                  BtcNummer, BtcOms,
                  //gegevens lacatie/serienummer
                  LocNaam, LocOms, ArtSerieNummer)
          values( 0, 0, @curMohkGid, @curMokNummer, @curMokOntvangstDatum, _U('heel: %1!     Rest: %2!', @AantalEtikHeel, @AantalEtikRest), @curMohrGid, @curMagOntRegelNr,
                  @curNawFilNummer, @curNawFilZoekcode, @curNawNaam, @BstKopNummer, @BstRglNummer, @BstRglOms, @OmsBestelRegelOfArtikel,
                  @curArtCode, @curArtZoekcode, @curArtOms, @curArtAantDecAantallen, @curArtAantDecPrijzen, @curArtPrijsPer,
                  @curArtIsGeblokkeerd, @curArtIsGeblokkeerdInkoop, @curArtOmsEenheid, @curArtHeeftVoorraad, @curArtGewichtPerEenheid, @curArtVolumePerEenheid,
                  @curArtSerienrRegistreren, @curArtIsPartijRegistreren, @curArtAfbeeldingKlein, @curArtAfbeeldingGroot, @curTekstOpFactuur, @curArtOpmerking,
                  @curOpbrGrpNummer, @curOpbrGrpOms, @curDefaultEanCode, @curMagOntArtCodeBijLeverancier, @curMagOntEanCode,
                  @curMagOntInkoopEenheid, @curMagOntVoorraadEenhedenInInkoopEenheid, @curInkEenhIsVrdEenh,
                  //!!!!!!!!!!!!!!!!!!!! Aantal stuks van ontvangstregel !!!!!!!!!!!!!!!!!!!!
                  @curMagOntAantalInkoopEenheden, @curMagOntAantalVoorraadEenheden, @AantalInkoopEenhPerEtiket, @AantalVoorraadEenhPerEtiket,
                  @curArtPartijNummer, @curArtPartijOms, @curArtPartijNrBijLeverancier, @curArtPartijOpm,
                  @curArtPartijDatumOntvangst, @curArtPartijTHTdatum, @curArtPartijVrijTmDatum, @curArtPartijVrijVanafDatum, @curArtPartijDatumProductie,
                  @curBtwCodeVerkoop, @curBtwPercVerkoop, @curVerkoopPrijsIsInclBTW, @curVerkoopPrijsExclusief, @curVerkoopPrijsInclusief,
                  @curSoortKorting, @curKortingsBedragExclusief, @curKortingsBedragInclusief, @curKortingsPerc,
                  @curArtIsAdviesPrijsInclBTW, @curAdviesPrijsExclusief, @curAdviesPrijsInclusief,
                  //gegevens order/magazijnregel
                  Null, Null, Null, Null, Null,
                  Null, Null, Null, Null, Null, Null,
                  Null, Null, Null, Null, Null, Null, Null, Null,
                  Null,
                  // Betalingsconditie
                  @BtcNummer, @BtcOms,
                  //gegevens locatie/serienummer
                  Null, Null, Null);
      set @EtiketTeller = @EtiketTeller + 1;
    end loop;

    //magazijnontvangstregel toevoegen van restant inkoop/voorraad eenheden?
    if @AantalEtikRest <> 0 then
      insert into tmpMagOntEtiket(
                  SoortEtiket, IsRestantEtiket, MohkGid, MokNummer, MokOntvangstDatum, MokOmschrijving, MohrGid, MagOntRegelNr,
                  LevNummer, LevZoekcode, LevNaam, BstKopNummer, BstRglNummer, BstRglOms, OmsBestelRegelOfArtikel,
                  ArtCode, ArtZoekcode, ArtOms, ArtAantDecAantallen, ArtAantDecPrijzen, ArtPrijsPer,
                  ArtIsGeblokkeerd, ArtIsGeblokkeerdInkoop, ArtOmsEenheid, ArtHeeftVoorraad, ArtGewichtPerEenheid, ArtVolumePerEenheid,
                  ArtSerienrRegistreren, ArtIsPartijRegistreren, ArtAfbeeldingKlein, ArtAfbeeldingGroot, TekstOpFactuur, ArtOpmerking,
                  OpbrGrpNummer, OpbrGrpOms, DefaultEanCode, MagOntArtCodeBijLeverancier, MagOntEanCode,
                  MagOntInkoopEenheid, MagOntVoorraadEenhedenInInkoopEenheid, InkEenhIsVrdEenh,
                  //Aantal stuks van magazijnontvangstregel
                  MagOntAantalInkoopEenheden, MagOntAantalVoorraadEenheden, AantalInkEenhEtiket, AantalVrdkEenhEtiket,
                  ArtPartijNummer, ArtPartijOms, ArtPartijNrBijLeverancier, ArtPartijOpm,
                  ArtPartijDatumOntvangst, ArtPartijTHTdatum, ArtPartijVrijTmDatum, ArtPartijVrijVanafDatum, ArtPartijDatumProductie,
                  BtwCodeVerkoop, BtwPercVerkoop, VerkoopPrijsIsInclBTW, VerkoopPrijsExclusief, VerkoopPrijsInclusief,
                  SoortKorting, KortingsBedragExclusief, KortingsBedragInclusief, KortingsPerc,
                  ArtIsAdviesPrijsInclBTW, AdviesPrijsExclusief, AdviesPrijsInclusief,
                  //gegevens order/magazijnregel
                  MagOntDetBrdSoort, OrderNummer, OrderRegelNr, BackorderAantal, BackorderLeverdatum,
                  DebiteurNummer, DebiteurZoekcode, DebiteurNaam1, DebiteurNaam2, DebiteurStraat, DebiteurHuisnummer,
                  DebiteurPostcode, DebiteurPlaats, DebiteurLand, DebiteurTelefoon, DebiteurTelefoon2, DebiteurTelefax,  DebiteurEmail, DebiteurEanCode,
                  KoppelingVervallen,
                  // Betalingsconditie
                  BtcNummer, BtcOms,
                  //gegevens lacatie/serienummer
                  LocNaam, LocOms, ArtSerieNummer)
          values( 0, 1, @curMohkGid, @curMokNummer, @curMokOntvangstDatum, @curMokOmschrijving, @curMohrGid, @curMagOntRegelNr,
                  @curNawFilNummer, @curNawFilZoekcode, @curNawNaam, @BstKopNummer, @BstRglNummer, @BstRglOms, @OmsBestelRegelOfArtikel,
                  @curArtCode, @curArtZoekcode, @curArtOms, @curArtAantDecAantallen, @curArtAantDecPrijzen, @curArtPrijsPer,
                  @curArtIsGeblokkeerd, @curArtIsGeblokkeerdInkoop, @curArtOmsEenheid, @curArtHeeftVoorraad, @curArtGewichtPerEenheid, @curArtVolumePerEenheid,
                  @curArtSerienrRegistreren, @curArtIsPartijRegistreren, @curArtAfbeeldingKlein, @curArtAfbeeldingGroot, @curTekstOpFactuur, @curArtOpmerking,
                  @curOpbrGrpNummer, @curOpbrGrpOms, @curDefaultEanCode, @curMagOntArtCodeBijLeverancier, @curMagOntEanCode,
                  @curMagOntInkoopEenheid, @curMagOntVoorraadEenhedenInInkoopEenheid, @curInkEenhIsVrdEenh,
                  //!!!!!!!!!!!!!!!!!!!! Aantal stuks van ontvangstregel !!!!!!!!!!!!!!!!!!!!
                  @curMagOntAantalInkoopEenheden, @curMagOntAantalVoorraadEenheden, @AantalInkoopEenhRestEtiket, @AantalVoorraadEenhRestEtiket,
                  @curArtPartijNummer, @curArtPartijOms, @curArtPartijNrBijLeverancier, @curArtPartijOpm,
                  @curArtPartijDatumOntvangst, @curArtPartijTHTdatum, @curArtPartijVrijTmDatum, @curArtPartijVrijVanafDatum, @curArtPartijDatumProductie,
                  @curBtwCodeVerkoop, @curBtwPercVerkoop, @curVerkoopPrijsIsInclBTW, @curVerkoopPrijsExclusief, @curVerkoopPrijsInclusief,
                  @curSoortKorting, @curKortingsBedragExclusief, @curKortingsBedragInclusief, @curKortingsPerc,
                  @curArtIsAdviesPrijsInclBTW, @curAdviesPrijsExclusief, @curAdviesPrijsInclusief,
                  //gegevens order/magazijnregel
                  Null, Null, Null, Null, Null,
                  Null, Null, Null, Null, Null, Null,
                  Null, Null, Null, Null, Null, Null, Null, Null,
                  Null,
                  // Betalingsconditie
                  @BtcNummer, @BtcOms,
                  //gegevens locatie/serienummer
                  Null, Null, Null);
    end if;

  end for;    //cursor_OntvangstRegels
  //------------------------------------------------- einde alle ontvangstregels doorlopen -------------------------------------------------------



  //Geef resultaat terug
  SELECT
    SoortEtiket,
    IsRestantEtiket,

    //gegevens magazijnontvangstkop/regel
    MohkGid,
    MokNummer,
    MokOntvangstDatum,
    MokOmschrijving,
    MohrGid,
    MagOntRegelNr,

    //leveranciergegevens
  	LevNummer,
  	LevZoekcode,
    LevNaam,

    //Bestellinggegevens
    BstKopNummer,
    BstRglNummer,
    BstRglOms,
    OmsBestelRegelOfArtikel,

    //artikelgegevens
    ArtCode,
    ArtZoekcode,
    ArtOms,
    ArtAantDecAantallen,
    ArtAantDecPrijzen,
  	ArtPrijsPer,
   	ArtIsGeblokkeerd,
    ArtIsGeblokkeerdInkoop,
  	ArtOmsEenheid,
  	ArtHeeftVoorraad,
  	ArtGewichtPerEenheid,
  	ArtVolumePerEenheid,
  	ArtSerienrRegistreren,
  	ArtIsPartijRegistreren,
    ArtAfbeeldingKlein,
    ArtAfbeeldingGroot,
    TekstOpFactuur,
    ArtOpmerking,

   	OpbrGrpNummer,
  	OpbrGrpOms,
    DefaultEanCode,

    MagOntArtCodeBijLeverancier,
    MagOntEanCode,

    //aantallen
    MagOntInkoopEenheid,
    MagOntVoorraadEenhedenInInkoopEenheid,
    InkEenhIsVrdEenh,
    MagOntAantalInkoopEenheden,
    MagOntAantalVoorraadEenheden,
    //aantal eenheden per etiket
    AantalInkEenhEtiket,
    AantalVrdkEenhEtiket,

    //partijgegevens
    ArtPartijNummer,
    ArtPartijOms,
    ArtPartijNrBijLeverancier,
    ArtPartijOpm,
    ArtPartijDatumOntvangst,
    ArtPartijTHTdatum,
    ArtPartijVrijTmDatum,
    ArtPartijVrijVanafDatum,
    ArtPartijDatumProductie,

    //Verkoopprijs artikel/partij
    BtwCodeVerkoop,
  	BtwPercVerkoop,
    VerkoopPrijsIsInclBTW,
    VerkoopPrijsExclusief,
    VerkoopPrijsInclusief,
    SoortKorting,
    KortingsBedragExclusief,
    KortingsBedragInclusief,
  	KortingsPerc,

    ArtIsAdviesPrijsInclBTW,
    AdviesPrijsExclusief,
    AdviesPrijsInclusief,

    CbsOorsprongLndEigenCode,
    CbsOorsprongLndOms,

    //order/magazijn specificatieregel
    MagOntDetBrdSoort,
    OrderNummer,
    OrderRegelNr,
    BackorderAantal,
    BackorderLeverdatum,
    DebiteurNummer,
    DebiteurZoekcode,
    DebiteurNaam1,
    DebiteurNaam2,
    DebiteurStraat,
    DebiteurHuisnummer,
    DebiteurPostcode,
    DebiteurPlaats,
    DebiteurLand,
    DebiteurTelefoon,
    DebiteurTelefoon2,
    DebiteurTelefax,
    DebiteurEmail,
    DebiteurEanCode,
    KoppelingVervallen,
    // Betalingsconditie
    BtcNummer,
    BtcOms,

    //locatie/serienummerregel
    LocNaam,
    LocOms,
    ArtSerieNummer

  FROM
    tmpMagOntEtiket
  ORDER BY MokNummer, MagOntRegelNr, SoortEtiket, MagOntDetBrdSoort DESC, OrderNummer, OrderRegelNr, IsRestantEtiket, ArtSerieNummer;

  set @@ErrorTextProcedure = 'Einde rapMagOntEtiket > ';
  //call Trace(@@ErrorTextProcedure);

end;

//call rapMagOntEtiket('Ontvangstnummer', 0, 999999999, null, null, null, null, null, null, 1, 1, 1, 1, 1 ,'N');



create or replace procedure rapNawEtiket( in  @FonId           nchar(3),
                                          in  @SelecteerOp     smallint,  //0=nummer, 1=zoekcode, 2=land
                                          in  @VanNaw          nchar(10),
                                          in  @TotNaw          nchar(10),
                                          in  @EtikettenVan    smallint,  //debiteuren met    0=geen cp 1=voorkeur-cp, 2=alle cp van functie binnen selectie
                                                                          //                  3=alle cp van functie, 4=alle cp binnen selectie, 5=alle cp
                                          in  @AdresSoorten    smallint,  //0=Vestingsadres, 1=correspondentie-adres, 2=Vestings en verzendadres, 3=correspondentie en verzend-adres
                                          in  @SorterenOp      smallint,  //0=nummer, 1=zoekcode, 1=land, 2=postcode
                                          in  @ContPersFunctie Integer,
                                          in  @IsAscending     smallint,  // 0 = aflopend, 1 = oplopend
                                          in  @TestSelectie    smallint,  // Controleer selecties van 0=niet, 1=Naw, 2=Contactpersonen, 3=NAW + Contactpersonen
                                          in  @SelCode         nchar (10)  // Selectiegid om selecties mee te controleren
                             )

result ( NawFilNummer nchar(10), NawFilZoekCode nchar(10), NawGid Integer, AdrGid Integer,
         AdrNaam1 nchar(40), AdrNaam2 nchar(40), AdrOms nchar(40), AdrStraat nchar(40), AdrHuisnummer nchar(10),
         AdrPostcode nchar(40), AdrPlaats nchar(40), AdrTelefoon nchar(25), AdrTelefoon2 nchar(25), AdrTelefax nchar(25), AdrEmail nchar(80),
         AdrEanCode        nchar (13),
         NawRekBankrekening nchar(34),
         NawBtwNummer      nchar(15),
         NawWebsite        nchar(250),
         rksValNummer      Integer,
         rksBtwCode        Integer,
         ValCode           nchar(3),
         OmsValuta         nchar(40),
         relGid            integer,
         relAchternaam     nchar(40),
         relVoorvoegsel    nchar(40), relVoorletters nchar(15), relVoornaam nchar(40),
         relTitel          nchar(15), relAchtervoegsel nchar(15),
         relEmail          nchar(80), relTelefax nchar(25), relTelefoon nchar(25), relTelefoon2 nchar(25), relGeslacht smallint,
         NaamInAdres       nchar(60), NaamInAanhef nchar(60), NaamInBrief nchar(60), VolledigeNaam nchar(40),
         omsFunctie        nchar(40),
         TaalCode          nchar(3),
         TaalOms           nchar(40),
         lndInNAWBlok      smallint,
         LandAfdrukken     smallint,
         KIXCode           nchar(54),
         lndEigenCode      nchar(3),
         lndOms            nchar(40),
         lndPlaatsHuisnr   smallint,
         lndPlaatsPostcode smallint,
         lndPostcodeMasker nchar(40),
         //voor bestand van mailing, alleen bij debiteur:
         NawVertegenwCode         integer,
         Naam_NawVertegenwCode    nchar(40),
         NawContributieCode       integer,
         Oms_NawContributieCode   nchar(40),
         RelContributieCode       integer,
         Oms_RelContributieCode   nchar(40),
         //voor bestand van mailing, alleen bij crediteur:
         NawOnsDebiteurNummer nchar(20)
       )

begin
  declare @FonGid     integer;
  declare @SelGid     integer;
  declare @omsfunctie nchar(40);

  declare local temporary table tmpEtiketten(
    tmpNawFilgid  Integer,
    tmpNawGid     Integer,
    tmpAdrGid     Integer,
    tmpRelGid     Integer,
    tmpGeenOms    smallint default 0,
    tmpVoorSelect smallint default 0
    ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapNawEtiket > ';
  //call TraceBegin(@@ErrorTextProcedure + '@FonId = ' + @FonId + ', @SelecteerOp = ' + string(@SelecteerOp) + ', @VanNaw = ' + @VanNaw + ', @TotNaw = ' + @TotNaw + ', @EtikettenVan = ' + string(@EtikettenVan) + ', @ContPersFunctie = ' + string(@ContPersFunctie));

  if @EtikettenVan in (1,2,3) then
    select OmsFunctie into @omsfunctie from tabFunctieContact where fnCode = @ContPersFunctie; // Geeft de omschrijving van die functie als een contactpersoonfunctie is geselecteerd,
  end if;

  //Fongidje opvragen
  select FonGid into @fonGid from tabFileOfNaw where FonID=@FonID;
  select SelGid into @SelGid from tabSelectie where (SelCode = @SelCode) and (SelSltGid = (select fonSltGid from tabFileOfNaw where FonGid = @FonGid));

  if @selGid is not null or @testselectie = 0 then
    //call Trace('rapNawEtiket > toevoegen vestiging of corresp van betreffende naw s afhankelijk van @AdresSoorten');
    //  Alle debiteuren maximaal 1 keer geselecteerd.afhankelijk van selecties en @Van @Tot
    //  De debiteur wordt toegevoegd ook als hij een contactpersoon heeft die voldoet aan een selectie.
    //  --> Dit wil nog niet zeggen dat deze contactpersoons ook getoond wordt! Kijk maar: met tmpRelGid wordt hier niets gedaan.
    insert into tmpEtiketten (tmpNawFilGid, tmpNawGid, tmpAdrGid, tmpVoorSelect)
    select distinct NawFilGid, NawGid, AdrGid,1
    from tabnawfile inner join tabNaw on ( NawGid = NawFilNawGid and NawFilFonId = @FonId )
	  left outer join tabAdres on (AdrGid = if @AdresSoorten in (0,2) then nawgidvestiging else nawgidcorrespondentie endif)                //Vestigingsadres of Correspondentieadres
	  left outer join tabLand on LndGid = AdrLndGid
	  left outer join tabRelatie on (RelNawGid = NawGid and ( @TestSelectie in (0,1) or ContactpersoonValtBinnenSelectie(@SelGid, RelGid) <> 0 ))
    where (     (@SelecteerOp = 0 and nawfilnummer   between @VanNaw and @TotNaw)
             or (@SelecteerOp = 1 and nawfilZoekCode between @VanNaw and @TotNaw)
             or (@SelecteerOp = 2 and lndEigenCode   between @VanNaw and @TotNaw)
          )
          and
          (     (@TestSelectie = 0)
             or (@TestSelectie = 1 and  NawValtBinnenSelectie(@SelGid, NawFilGid) <> 0)
             or (@TestSelectie = 2 and  RelGid is not null)
             or (@TestSelectie = 3 and (RelGid is not null or NawValtBinnenSelectie(@SelGid, NawFilGid) <> 0 )) );

    //call Trace('rapNawEtiket > Indices aanmaken');

    Create index idx_tmpNawFilGid     on tmpEtiketten (tmpNawFilGid);
    Create index idx_tmpNawGid        on tmpEtiketten (tmpNawGid);

    //handig voor debugging!
    //unload select * from tmpEtiketten TO 'd:\tmpEtiketten1.txt'; //'\\\\vve-pc2\mail\tmpEtiketten1.txt';

    //call Trace('rapNawEtiket > Aantal records afhankelijk van te tonen contactpersonen');
    case @EtikettenVan //naw met gegevens van
      when 0 then // geen extra record''s, 0 = geen cp
        set @@ErrorTextProcedure = 'rapNawEtiket > Update 0';
        //call Trace(@@ErrorTextProcedure);

        update tmpEtiketten set tmpVoorSelect = 2    // wordt hier 2 omdat anders geen verzendadressen geselecteerd kunnen worden

      when 1 then  // 1 = voorkeur-cp,
        //call Trace('rapNawEtiket > Update 1');
        update tmpEtiketten
        set    tmpVoorSelect = 2,
               tmpRelGid = (select RelGid from tabRelatie inner join tabRelatieFunctie
                                          on ((FnRelGid = RelGid)
                                               and (IsBelangrijkste = 1) and (@ContPersFunctie = RelFnCode))
                                          where RelNawGid = tmpNawGid)

      when 2 then  // 2 = alle cp van functie binnen selectie
        //call Trace('rapNawEtiket > Insert 2');
        insert into tmpEtiketten (tmpNawFilGid, tmpNawGid, tmpAdrGid, tmpRelGid)
        select tmpNawFilGid, tmpNawGid, tmpAdrGid, RelGid
        from   tmpEtiketten
               left outer join (tabRelatie inner join tabRelatieFunctie
                                           on ((FnRelGid = RelGid)
                                               and ( @ContPersFunctie = RelFnCode)
                                               and ( ContactpersoonValtBinnenSelectie(@SelGid, RelGid) <> 0 )))
               on (RelNawGid = tmpNawGid)

      when 3 then  // 3 = alle cp van functie,
        //call Trace('rapNawEtiket > Insert 3');
        insert into tmpEtiketten (tmpNawFilGid, tmpNawGid, tmpAdrGid, tmpRelGid,tmpVoorSelect)
        select tmpNawFilGid, tmpNawGid, tmpAdrGid, RelGid, 0
        from   tmpEtiketten
               left outer join (tabRelatie inner join tabRelatieFunctie on ((FnRelGid = RelGid)
                                                                             and (@ContPersFunctie = RelFnCode)))
               on (RelNawGid = tmpNawGid)

      when 4 then  // 4 = alle cp binnen selectie,
        //call Trace('rapNawEtiket > Insert 4');
        insert into tmpEtiketten (tmpNawFilGid, tmpNawGid, tmpAdrGid, tmpRelGid)
        select tmpNawFilGid, tmpNawGid, tmpAdrGid, RelGid
        from   tmpEtiketten
               left outer join tabRelatie
               on ((RelNawGid = tmpNawGid)
                    and ( ContactpersoonValtBinnenSelectie(@SelGid, RelGid) <> 0 ))

      when 5 then  // 5 = alle cp
        //call Trace('rapNawEtiket > Insert 5');
        insert into tmpEtiketten (tmpNawFilGid, tmpNawGid, tmpAdrGid, tmpRelGid, tmpVoorSelect)
        select tmpNawFilGid, tmpNawGid, tmpAdrGid, RelGid, 0
        from   tmpEtiketten
               left outer join tabRelatie
               on (RelNawGid = tmpNawGid);
    end case;

    if @AdresSoorten in (2,3) then         //toevoegen verzend adressen
      //call Trace('rapNawEtiket > Insert verzendadressen');
      //MR 17-aug-2010 Bug #32743: tmpVoorSelect op 2 anders krijg je geen verzendadressen.
      insert into tmpEtiketten (tmpNawFilGid, tmpNawGid, tmpAdrGid, tmpRelGid, tmpGeenOms,tmpVoorSelect)
      select tmpNawFilGid, NawGid, AdrGid, RelGid, 1,2//tmpVoorSelect //, (if RelGid is not null then 1 endif)//als relgid is leeg dan geen omschrijving.
      from tmpEtiketten
           inner join tabNaw on (tmpNawGid = NawGid)
           inner join tabAdres on ((AdrNawGid = NawGid) and (adrgid <> nawgidvestiging) and (adrgid <> nawgidcorrespondentie))
           left outer join tabRelatie  on ((RelGid = AdrRelGid)
                                            and @EtikettenVan <> 0)
      where tmpVoorSelect in (1,2)
    end if;
  end if;

  //call Trace('rapNawEtiket > Create indices 2');

  Create index idx_tmpRelatieGid on tmpEtiketten (tmpRelGid);
  Create index idx_tmpAdresGid   on tmpEtiketten (tmpAdrGid);

  //unload select * from tmpEtiketten TO 'd:\tmpEtiketten2.txt'; //'\\\\vve-pc2\mail\tmpEtiketten1.txt';

  set @@ErrorTextProcedure = 'rapNawEtiket';
  //call TraceEind(@@ErrorTextProcedure);

  select
    NawFilNummer, NawFilZoekCode, NawGid,

    AdrGid, AdrNaam1, AdrNaam2, AdrOms, AdrStraat, AdrHuisnummer,
    AdrPostcode, AdrPlaats, AdrTelefoon, AdrTelefoon2, AdrTelefax, AdrEmail,
    AdrEanCode,

    NawRekBankrekening,
    NawBtwNummer,
    NawWebsite,

    RksValNummer, RksBtwCode,
    ValCode,
    OmsValuta,

    relGid, relAchternaam,
    relVoorvoegsel, relVoorletters, relVoornaam, relTitel, relAchtervoegsel,
    relEmail, relTelefax, relTelefoon, relTelefoon2, relGeslacht,

   //bepaal tekst als van functie geen contactpersoon is laat leeg voor verzend adressen en voor @EtikettenVan = 0
    (if @EtikettenVan <> 0 then (if  ((RelGid is null or (RelGid is not null and relNaamInAdres='')) and tmpGeenOms <> 1) then fnTekstAdres  else relNaamInAdres  endif)  endif) NaamInAdres ,
    (if @EtikettenVan <> 0 then (if  ((RelGid is null or (RelGid is not null and relNaamInAanhef='')) and tmpGeenOms <> 1) then fnTekstAanhef else relNaamInAanhef endif)  endif) NaamInAanhef,
    (if @EtikettenVan <> 0 then (if  ((RelGid is null or (RelGid is not null and relNaamInBrief='')) and tmpGeenOms <> 1) then fnTekstBrief  else relNaamInBrief  endif)  endif) NaamInBrief,
    (if @EtikettenVan <> 0 then (if  (RelGid is null and tmpGeenOms <> 1) then ''  else relVolledigeNaam endif) endif) VolledigeNaam,
    @omsFunctie omsFunctie,

    TaalCode,
    TaalOms,

    lndInNAWBlok,
    ( if lndInNAWblok = 1  then 1                        // bepaal of land moet worden afgedrukt
      else if lndgid = (select DefaultLndGid from tabVasteGegevens) then 0
           else 1
           endif
      endif) LandAfdrukken,

    BouwKIXCode(adrLndGid, AdrPostcode, AdrHuisnummer) as KIXCode,

    lndEigenCode,
    lndOms,
    lndPlaatsHuisnr,
    lndPlaatsPostcode,
    lndPostcodeMasker,
    //voor bestand van mailing, alleen bij debiteur:
    NawVertegenwCode,
    (select SubRelA.RelVolledigeNaam from tabRelatie SubRelA where SubRelA.RelVtgCode=NawVertegenwCode) Naam_NawVertegenwCode,
    NawContributieCode,
    (select ContributieOms from tabContributieCode where ContributieCode=NawContributieCode) Oms_NawContributieCode,
    RelContributieCode,
    (select ContributieOms from tabContributieCode where ContributieCode=RelContributieCode) Oms_RelContributieCode,
    //voor bestand van mailing, alleen bij crediteur:
    NawOnsDebiteurNummer,
    StripString(AdrHuisnummer, '0123456789') HuisnummerStrippedStr,
    (if HuisNummerStrippedStr <> '' then cast(HuisnummerStrippedStr as numeric(10,0)) else 0 endif) HuisnummerNumeriek
  from
    tmpEtiketten
    left outer join tabnawfile  on (tmpnawfilgid = NawFilGid)
    left outer join tabnaw on ( NawGid = NawFilNawGid )
    left outer join (tabAdres inner join tabLand on ( lndGid = adrLndGid )) on ( tmpAdrGid = adrGid)
    left outer join tabRelatie on ( tmpRelGid = RelGid )

    //Algemene functienaam
    left outer join
      tabFunctieTaal
    on ( fnTaalGid = NawTaalGid                                                // Omschrijving in taal Naw
         and taalfnCode = @ContPersFunctie                                     // Selecteer algemene tekst bij functie
       )

    left outer join
      tabTaal
    on (nawTaalGid=taalGid)                                    // voor ophalen taalcode
    left outer join
      tabNawRekening
    on (nawGid =nawRekNawGid and NawrekSoort like '%D%')

    left outer join
      tabRekeningschema
    on (RksGid = nawFilRksGid)

    left outer join
      tabValuta
    on (Valnummer = rksValnummer)

  where tmpVoorSelect <> 1

  order by
      // Naw nr
     (if @IsAscending = 1 and @SorterenOp = 0 then NawFilNummer endif) asc,
     (if @IsAscending = 0 and @SorterenOp = 0 then NawFilNummer endif) desc,
      // Zoekcode
     (if @IsAscending = 1 and @SorterenOp = 1 then NawFilZoekcode + space(10 - length (NawFilZoekcode)) + NawFilNummer endif) asc,
     (if @IsAscending = 0 and @SorterenOp = 1 then NawFilZoekcode + space(10 - length (NawFilZoekcode)) + NawFilNummer endif) desc,
      // Postcode en Land zijn hetzelfde
     (if @IsAscending = 1 and @SorterenOp in (2,3) then lndEigenCode endif) asc,
     (if @IsAscending = 0 and @SorterenOp in (2,3) then lndEigenCode endif) desc,
     (if @IsAscending = 1 and @SorterenOp in (2,3) then AdrPostcode endif) asc,
     (if @IsAscending = 0 and @SorterenOp in (2,3) then AdrPostcode endif) desc,
     (if @IsAscending = 1 and @SorterenOp in (2,3) then HuisnummerNumeriek endif) asc,
     (if @IsAscending = 0 and @SorterenOp in (2,3) then HuisnummerNumeriek endif) desc,
     (if @IsAscending = 1 and @SorterenOp in (2,3) then AdrHuisnummer endif) asc,
     (if @IsAscending = 0 and @SorterenOp in (2,3) then AdrHuisnummer endif) desc,
     (if @IsAscending = 1 then IsNull(AdrCode, -1) endif) asc,
     (if @IsAscending = 0 then IsNull(AdrCode, -1) endif) desc;
end;

//call rapNawEtiket('D', 0, '12000000', '12999999',0,0,0,0,0,0, '')


create or replace procedure rapNawLijst( in  @FonId           nchar(3),
                              in  @SelecteerOp     smallint,  //0=nummer, 1=zoekcode, 2=vertegenwoordiger
                              in  @VanNaw          nchar(10),
                              in  @TotNaw          nchar(10),
                              in  @SorterenOp      smallint,  //0=nummer, 1=zoekcode, 2=postcode vestigings adres, 3=postcode corresp. adres, 4=vertegenwoordiger
                              in  @Contactpers     smallint,   // 0 = geen contact persoon, 1 = één contactpersoon van functie naar keuze.
                              in  @ContPersFunctie Integer,
                              in  @TestSelectie    smallint,  // Controleer selecties van 0=niet, 1=Naw, 2=Contactpersonen, 3=NAW + Contactpersonen
                              in  @SelCode         nchar (10),  // Selectiegid om selecties mee te controleren
                              in  @IsAscending     smallint  // 0 = oplopend, 1 = aflopend
                             )

result ( NawFilNummer                      nchar(10),
         NawFilZoekCode                    nchar(10),
         NawGid                            Integer,
         NawOpmOpmerking                   long nvarchar,
         NawRekBankrekening                nchar(34),
         NawWebsite                        nchar(250),
         NawKvkNummer                      nchar(40),

         VAdrGid                           Integer,
         VAdrNaam1    nchar(40), VAdrNaam2  nchar(40), VAdrOms      nchar(40), VAdrStraat  nchar(40), VAdrHuisnummer nchar(10),
         VAdrPostcode nchar(40), VAdrPlaats nchar(40), VAdrTelefoon nchar(25), VAdrTelefoon2 nchar(25), VAdrTelefax nchar(25), VAdrEmail      nchar(80),
         VAdrEanCode  nchar(13),
         VlndInNAWBlok          smallint,
         VLandAfdrukken         smallint,
         VKIXCode               nchar(54),
         VlndEigenCode          nchar(3),
         VlndOms                nchar(40),
         VlndPlaatsHuisnr       smallint,
         VlndPlaatsPostcode     smallint,
         VlndPostcodeMasker     nchar(40),

         CAdrGid                Integer,
         CAdrNaam1    nchar(40), CAdrNaam2  nchar(40), CAdrOms      nchar(40), CAdrStraat  nchar(40), CAdrHuisnummer nchar(10),
         CAdrPostcode nchar(40), CAdrPlaats nchar(40), CAdrTelefoon nchar(25), CAdrTelefoon2 nchar(25), CAdrTelefax nchar(25), CAdrEmail      nchar(80),
         CAdrEanCode  nchar(13),
         ClndInNAWBlok          smallint,
         CLandAfdrukken         smallint,
         CKIXCode               nchar(54),
         ClndEigenCode          nchar(3),
         ClndOms                nchar(40),
         ClndPlaatsHuisnr       smallint,
         ClndPlaatsPostcode     smallint,
         ClndPostcodeMasker     nchar(40),

         relGid                 Integer,
         relAchternaam          nchar(40),
         relVoorvoegsel         nchar(40), relVoorletters   nchar(15), relVoornaam nchar(40),
         relTitel               nchar(15), relAchtervoegsel nchar(15),
         relEmail               nchar(80), relTelefax       nchar(25), relTelefoon nchar(25), relTelefoon2 nchar(25), relGeslacht   smallint,
         NaamInAdres            nchar(60), NaamInAanhef     nchar(60), NaamInBrief nchar(60), VolledigeNaam nchar(40),

         SelCodeLijst                      long nvarchar,
         SelCodeOmsLijst                   long nvarchar,

         orderGegNawAparteFacturen         smallint,  //hoe zit het trouwens met opties????    naamgeving voor verwerking naar de layout toe
         orderGegNawFacturerenInclBtw      smallint,
         orderGegNawFactuurAdres   	   smallint,
         orderGegVerzendAdresSoort         integer, //combobox
         orderGegVerzAdresOms              nchar(40),
         orderGegVerzendAdres              Integer,//niet gidje, maar evt adrescode

         orderGegDebiteurnrFactuur         nchar(10),
         orderGegDebiteurNaamFactuur       nchar(40),
         orderGegDebiteurnrOmzet           nchar(10),
         orderGegDebiteurNaamOmzet         nchar(40),
         orderGegDebiteurnrPrijzen         nchar(10),
         orderGegDebiteurNaamPrijzen       nchar(40),
         orderGegDebGrpNr                  smallInt,
         orderGegDebGrpOms                 nchar(40),
         orderGegVertegenwoordiger         smallInt,
         orderGegVertegenwoordigerNaam     nchar(40),

         orderGegRapNumIncl                Integer,
         orderGegRapNaamIncl               nchar(40),
         orderGegRapNumExcl                Integer,
         orderGegRapNaamExcl               nchar(40),
         orderGegNawAantalKopieFacturen    smallint,

         orderGegDebGrpKorting             numeric(15,2),
         orderGegWelkeKorting              smallInt,

         orderGegNawOrderKorting           numeric(6,2),
         orderGegNawContributieCode        Integer,// moet nog op optie nagekeken worden . hier of in de dm
         orderGegNawBlokOrderInvoer        smallint,

         orderGegWebNaw                    smallInt,

         FinGegBtcNummer                   Integer,
         FinGegBtcOms                      nchar(40),
         FinGegLvcNummer                   Integer,
         FinGegLvcOms                      nchar(40),
         FinGegNawFilValNummer             Integer,
         FinGegValCode                     nchar(3),
         FinGegOmsValuta                   nchar(40),
         FinGegBTWCode                     Integer,
         FinGegBtwOms                      nchar(40),
         FinGegTaalCode                    nchar(3),
         FinGegTaalOms                     nchar(40),
         FinGegNawfilKredLimiet            numeric (15,2),
         FinGegKredLimIsStandaard          smallint,
         FinGegTegRekNaam                  nchar(40),
         FinGegTegRekNummer                nchar(10),
         FinGegAanmaningsType              smallint,  // 0=geen / 1=aanmaning / 2=rekeningoverzicht
         FinGegnawBtwNummer                nchar(15),
         FinGegNawOnsDebiteurNummer        nchar(20),
         FinGegNawFilAutoOSP               smallint

      )

begin
  declare @FonGid integer;
  declare @SelGid integer;
  declare @defaultLndGid integer;
  declare @BjGid integer;
  declare @PerNr integer;

  declare @CorAdresTekst         long nvarchar;
  declare @VestAdresTekst        long nvarchar;
  declare @FactDebCorAdresTekst  long nvarchar;
  declare @FactDebVestAdresTekst long nvarchar;

  declare local temporary table tmpNawLijst(
    tmpNawFilGid       Integer,
    tmpNawGid          Integer,
    tmpVAdrGid         Integer,
    tmpCAdrGid         Integer,
    tmpRelGid          Integer,
    tmpNawIdFactDeb    Integer,
    tmpNawidDebOmzet   Integer,
    tmpNawidDebPrijzen Integer
    ) on commit preserve rows;

  call BepaalBoekjaarEnPeriode (@@VerwerkingsDatum, @BjGid, @PerNr);

  // Bug #30223, foutmelding bij selectie op zoekcode
  if @SelecteerOp = 2 then
    set @VanNaw = right('000' + string(cast(@VanNaw as integer)), 3);
    set @TotNaw = right('000' + string(cast(@TotNaw as integer)), 3);
  end if;

  //Fongidje opvragen
  select FonGid into @fonGid from tabFileOfNaw where FonID=@FonID;
  select SelGid into @SelGid from tabSelectie where (SelCode = @SelCode) and (SelSltGid = (select fonSltGid from tabFileOfNaw where FonGid = @FonGid));
  select DefaultLndGid into @DefaultLndGid from tabVasteGegevens;


  //selecteren van te tonen records
  if @selGid is not null or @testselectie =0 then
	      insert into tmpNawLijst (tmpNawFilGid, tmpNawGid, tmpVAdrGid, tmpCAdrGid, tmpNawIdFactDeb, tmpNawidDebOmzet, tmpNawidDebPrijzen)
	      select distinct NAWFIL.NawFilGid, NAW.NawGid, V.AdrGid, C.AdrGid, NawIdFactDeb, NawidDebOmzet, NawidDebPrijzen
	             from   tabnawfile AS NAWFIL inner join tabNaw AS NAW on ( NAW.NawGid = NAWFIL.NawFilNawGid and NAWFIL.NawFilFonId = @FonId )
	             inner join tabAdres as V on ( (V.AdrNawGid = NAW.NawGid) and ( V.AdrGid = NAW.nawgidvestiging) )                 //Vestigingsadres
	             inner join tabAdres as C on ( (C.AdrNawGid = NAW.NawGid) and ( C.AdrGid = NAW.nawgidcorrespondentie ) )        //Correspondentieadres
	             left outer join tabRelatie on (RelNawGid = NAW.NawGid and ( @TestSelectie in (0,1) or ContactpersoonValtBinnenSelectie(@SelGid, RelGid) <> 0 ) )
	      where  (    ( @SelecteerOp = 0 and NAWFIL.nawfilnummer   between @VanNaw and @TotNaw )
	                or( @SelecteerOp = 1 and NAWFIL.nawfilZoekCode between @VanNaw and @TotNaw )
	                or( @SelecteerOp = 2 and NAW.NawVertegenwCode is not null and right('000' + string(NAW.NawVertegenwCode), 3) between @VanNaw and @TotNaw )   )
	             and ( @TestSelectie = 0
                           or ( @TestSelectie = 1 and NawValtBinnenSelectie(@SelGid, NAWFIL.NawFilGid) <> 0)
                           or ( @TestSelectie = 2 and RelGid is not null)
                           or ( @TestSelectie = 3 and (NawValtBinnenSelectie(@SelGid, NAWFIL.NawFilGid) <> 0 or RelGid is not null)) );
  end if;

  //vullen RelGid voor te tonen contactpersoon
  if  @Contactpers = 1 then
    update tmpNawLijst set tmpRelGid = RelGid
    from   tabRelatie inner join tabRelatieFunctie on ( (FnRelGid = RelGid) and (IsBelangrijkste = 1) and (@ContPersFunctie = RelFnCode))
    where  (RelNawGid = tmpNawGid)
  end if;

  set @CorAdresTekst         = _U('Correspondentieadres');
  set @VestAdresTekst        = _U('Vestigingsadres');
  set @FactDebCorAdresTekst  = _U('Factuurdebiteur-Correspondentieadres');
  set @FactDebVestAdresTekst = _U('Factuurdebiteur-Vestigingsadres');

  select
    //-------------- algemene gegevens
    NawFilNummer,
    NawFilZoekCode,
    NawGid,
    NawOpmOpmerking,
    NawRekBankrekening,
    NawWebsite,
    NawKvkNummer,

    //-------------- vestigingsadres gegevens
    V.AdrGid VAdrGid,
    V.AdrNaam1 VAdrNaam1,
    V.AdrNaam2 VAdrNaam2,
    V.AdrOms VAdrOms,
    V.AdrStraat VAdrStraat,
    V.AdrHuisnummer VAdrHuisnummer,
    V.AdrPostcode VAdrPostcode,
    V.AdrPlaats VAdrPlaats,
    V.AdrTelefoon VAdrTelefoon,
    V.AdrTelefoon2 VAdrTelefoon2,
    V.AdrTelefax VAdrTelefax,
    V.AdrEmail VAdrEmail,
    V.AdrEanCode VAdrEanCode,

    VL.lndInNAWBlok VlndInNAWBlok,
    ( if VL.lndInNAWblok = 1  then 1                        // bepaal of land moet worden afgedrukt
      else if VL.lndgid = @DefaultLndGid then 0
           else 1
           endif
      endif) VLandAfdrukken,

    BouwKIXCode(V.adrLndGid, VAdrPostcode, VAdrHuisnummer) as VKIXCode,
    VL.lndEigenCode VlndEigenCode,
    VL.lndOms VlndOms,
    VL.lndPlaatsHuisnr VlndPlaatsHuisnr,
    VL.lndPlaatsPostcode VlndPlaatsPostcode,
    VL.lndPostcodeMasker VlndPostcodeMasker,

    //-------------- correspondentie adres gegevens
    C.AdrGid CAdrGid,
    C.AdrNaam1 CAdrNaam1,
    C.AdrNaam2 CAdrNaam2,
    C.AdrOms CAdrOms,
    C.AdrStraat CAdrStraat,
    C.AdrHuisnummer CAdrHuisnummer,
    C.AdrPostcode CAdrPostcode,
    C.AdrPlaats CAdrPlaats,
    C.AdrTelefoon CAdrTelefoon,
    C.AdrTelefoon2 CAdrTelefoon2,
    C.AdrTelefax CAdrTelefax,
    C.AdrEmail CAdrEmail,
    C.AdrEanCode CAdrEanCode,

    CL.lndInNAWBlok ClndInNAWBlok,
    ( if CL.lndInNAWblok = 1  then 1                        // bepaal of land moet worden afgedrukt
      else if CL.lndgid = @DefaultLndGid then 0
           else 1
           endif
      endif) CLandAfdrukken,
    BouwKIXCode(C.adrLndGid, CAdrPostcode, CAdrHuisnummer) as CKIXCode,
    CL.lndEigenCode ClndEigenCode,
    CL.lndOms ClndOms,
    CL.lndPlaatsHuisnr ClndPlaatsHuisnr,
    CL.lndPlaatsPostcode ClndPlaatsPostcode,
    CL.lndPostcodeMasker ClndPostcodeMasker,

    //-------------- contactpersoon gegevens
    relGid, relAchternaam,
    relVoorvoegsel, relVoorletters, relVoornaam, relTitel, relAchtervoegsel,
    relEmail, relTelefax, relTelefoon, relTelefoon2, relGeslacht,

    relNaamInAdres NaamInAdres ,
    relNaamInAanhef NaamInAanhef,
    relNaamInBrief NaamInBrief,
    relVolledigeNaam VolledigeNaam,

    //-------------- selectiecode gegevens
    (select list(SlcCode) from tabSelectiecodes inner Join tabSlcPerNaw on (SlcGid=SpnSlcGid) where (SpnNawFilGid = NawFilGid) ) SelCodeLijst,
    (select list(slcOms)  from tabSelectiecodes inner Join tabSlcPerNaw on (SlcGid=SpnSlcGid) where (SpnNawFilGid = NawFilGid) ) SelCodeOmsLijst,

    //-------------- order gegevens
    NawAparteFacturen orderGegNawAparteFacturen,
    NawFacturerenInclBtw orderGegNawFacturerenInclBtw,
    NawFactuurAdres orderGegNawFactuurAdres,
    NawVerzendAdres orderGegVerzendAdresSoort,
    (case NawVerzendAdres
     when 0 then
       @CorAdresTekst
     when 1 then
       @VestAdresTekst
     when 3 then
       @FactDebCorAdresTekst
     when 4 then
       @FactDebVestAdresTekst
     else//2: verzendadres, 5: factuurdebiteur-verzendadres
         O.adrOms
     end) orderGegVerzAdresOms,
    (if (NawVerzendAdres = 2) or (NawVerzendAdres = 5) then O.adrCode else null endif) orderGegVerzendAdres,

    //inkoopcombinatie
    (Select FACFILE.NawFilnummer From tabNawFile AS FACFILE where FACFILE.NawFilNawGid = tmpNawIdFactDeb)                                                                        orderGegDebiteurnrFactuur,
    (Select FACADRES.Adrnaam1    From tabNaw     AS FACNAW Inner join tabAdres As FACADRES On FACADRES.AdrGid = FACNAW.NawGidVestiging WHERE FACNAW.NawGid = tmpNawIdFactDeb)    orderGegDebiteurNaamFactuur,
    (Select OMZFILE.NawFilnummer From tabNawFile AS OMZFILE where OMZFILE.NawFilNawGid = tmpNawidDebOmzet)                                                                       orderGegDebiteurnrOmzet,
    (Select OMZADRES.Adrnaam1    From tabNaw     AS OMZNAW Inner join tabAdres As OMZADRES On OMZADRES.AdrGid = OMZNAW.NawGidVestiging WHERE OMZNAW.NawGid = tmpNawidDebOmzet)   orderGegDebiteurNaamOmzet,
    (Select PRSFILE.NawFilnummer From tabNawFile AS PRSFILE where PRSFILE.NawFilNawGid = tmpNawidDebPrijzen)                                                                     orderGegDebiteurnrPrijzen,
    (Select PRSADRES.Adrnaam1    From tabNaw     AS PRSNAW Inner join tabAdres As PRSADRES On PRSADRES.AdrGid = PRSNAW.NawGidVestiging WHERE PRSNAW.NawGid = tmpNawidDebPrijzen) orderGegDebiteurNaamPrijzen,

    //debiteurgroepen
    DebGrpNr  orderGegDebGrpNr,
    DebGrpOms orderGegDebGrpOms,

    //vertegenwoordiger
    NawVertegenwCode OrderGegVertegenwoordiger,
    (Select RelVtw.RelVolledigeNaam From tabrelatie as RelVtw where RelVtw.RelVtgCode = NawVertegenwCode) OrderGegVertegenwoordigerNaam,

    rapIncl.RapNummer orderGegRapNumIncl, rapIncl.RapNaam orderGegRapNaamIncl,
    rapExcl.RapNummer orderGegRapNumExcl, rapExcl.Rapnaam orderGegRapNaamExcl,
    NawAantalKopieFacturen orderGegNawAantalKopieFacturen,

    DebGrpOrderKorting orderGegDebGrpKorting,
    NawFilWelkeOrderkorting orderGegWelkeKorting,

    NawOrderKorting orderGegNawOrderKorting,
    NawContributieCode orderGegNawContributieCode,
    NawBlokOrderInvoer orderGegNawBlokOrderInvoer,

    // webklant??
    NawFilWebNaw orderGegWebNaw,

    //-------------- financiële gegevens
    nawfilBtcNummer FinGegBtcNummer,
    BtcOms FinGegBtcOms,
    nawfilLvcNummer FinGegLvcNummer,
    LvcOms FinGegLvcOms,
    NawFilValNummer FinGegNawFilValNummer,
    ValCode FinGegValCode,
    OmsValuta FinGegOmsValuta,
    NawfilBtwCode FinGegBTWCode,
    B.RksNaam FinGegBtwOms,
    TaalCode FinGegTaalCode,
    TaalOms FinGegTaalOms,
    ( if NawFilKredLimiet <> 0 then NawFilKredLimiet
      else ( select ValutaOmrekenen( @@BasisValutanummer, FonKredietLimiet, NawFilValNummer, @BjGid, @Pernr, 2)
             from tabFileOfNaw
             where FonGid = NawFilFonGid )
      endif ) FinGegNawfilKredLimiet,
    ( if tabNawFile.NawFilKredLimiet <> 0 then 0 else 1 endif ) FinGegKredLimIsStandaard,
    T.RksNaam FinGegTegRekNaam,
    T.RksNummer FinGegTegRekNummer,
    nawAanmaningsType FinGegAanmaningsType,
    nawBtwNummer FinGegnawBtwNummer,                       //verwar niet met BWTcodes e.d.
    nawOnsDebiteurNummer FinGegNawOnsDebiteurNummer,
    0 FinGegNawFilAutoOSP,
    (case @SorterenOp
       when 0 then
         NawFilNummer
       when 1 then
         NawFilZoekcode + space(10 - length (NawFilZoekcode)) + NawFilNummer
       when 2 then
         Left(VlndEigenCode + Space(3),3) + Left(VAdrPostcode + space(40), 40) + NawFilNummer
       when 3 then
         Left(ClndEigenCode + Space(3),3) + Left(CAdrPostcode + space(40), 40) + NawFilNummer
       else
         right('000' + string(IsNull(OrderGegVertegenwoordiger, -1)),3) + NawFilNummer
     end) as sorteerveld


  from
    tmpNawLijst inner join tabnawfile on ( tmpNawFilGid = NawFilGid )
    inner join tabnaw on (NawGid = NawFilNawGid)
    left outer join tabNawOpmerkingen on ( NawGid = NawOpmNawGid)
    left outer join tabDebiteurGroepen on (DebGrpGid = NawFilDebGrpGid)

    left outer join (tabAdres as V inner join tabLand as VL on ( VL.lndGid = V.adrLndGid )) on ( tmpVAdrGid = V.adrGid)  //vestigings adres
    left outer join (tabAdres as C inner join tabLand as CL on ( CL.lndGid = C.adrLndGid )) on ( tmpCAdrGid = C.adrGid)  //correspondentie adres
    left outer join tabAdres as O on ( O.adrGid = NawGidVerzendAdres)                                                    //order gegevens verzend-adres

    left outer join tabRelatie on ( tmpRelGid = RelGid )

    left outer join tabTaal on (nawTaalGid=taalGid)                                    // voor ophalen taalcode
    left outer join tabNawRekening on (nawGid =nawRekNawGid and NawrekSoort like '%D%')

    left outer join tabRekeningschema as F on (F.RksGid = nawFilRksGid)   // voor Financiële gegevens
    left outer join tabRekeningSchema as T on T.RksGid = F.TegenRksGid    // tegenrekening voor Financiële gegevens
    left outer join (tabRekeningSchema as B Inner join tabBtw on B.RksGid = BtwRksGid) on NawfilBtwCode = BtwCode    // Btw naam  voor Financiële gegevens

    left outer join tabValuta on (Valnummer = NawFilValnummer)

    left outer join tabRapport as RapIncl on RapIncl.RapGid = (select first NawDocRapGidInclBTW from tabNawDocument where NawDocNawGid=NawFilNawGid and NawDocDocSoort=50 and NawDocRegelSoort=0)
    left outer join tabRapport as RapExcl on RapExcl.RapGid = (select first NawDocRapGidExclBTW from tabNawDocument where NawDocNawGid=NawFilNawGid and NawDocDocSoort=50 and NawDocRegelSoort=0)

    left outer join tabBetalingsConditie on nawfilBtcNummer = BtcNummer
    left outer join tabLeveringsConditie on nawfilLvcNummer = LvcNummer

    order by
     (if @IsAscending <> 0 then Sorteerveld else '' endif),
     (if @IsAscending <> 0 then '' else Sorteerveld  endif) desc;


end;

//call rapNawLijst('D', 0, '12000000', '12999999',1, 0, 0, 0, 1, 0);


create or replace procedure rapNormaleBalans(
 in  @BjGid            Integer,
 in  @VanPernr         smallint,
 in  @TotPernr         smallint,
 in  @SelecteerOp      smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
 in  @VanRks           nchar(40), //van nummer/zoekcode/naam
 in  @TotRks           nchar(40), //t/m nummer/zoekcode/naam
 in  @SoortBoeking     smallint, //0=definitief, 1=voorlopig, 2=beide
 in  @OokNulSaldi      smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
 in  @ComprimeerBalans smallint, //0=nee, 1=ja, 2=conform balans
 in  @DebUitsplitsen   smallint, //0=nee, 1=ja (werkt niet bij conform balans)
 in  @CredUitsplitsen  smallint, //0=nee, 1=ja (werkt niet bij conform balans)
 in  @KstpUitsplitsen  smallint, //0=nee, 1=ja (werkt niet bij conform balans)
 in  @KstdUitsplitsen  smallint, //0=nee, 1=ja (werkt niet bij conform balans)
 in  @AantalCijfers    smallint, //Aantal cijfers waarop getotaliseerd moet worden 1-5 (werkt niet bij conform balans)
 in  @BalansInValuta   integer,  //Valutanummer waarin balans moet worden afgedrukt
 in  @TotalenInValuta  integer)  //Valutanummer voor subtotalen

result (
  RksInvoer nchar(28), RksNummer nchar(10), RksNaam nchar(40), ValNummer integer, Valcode nchar(3),
  BeginBalansDebet    numeric(15,2), BeginBalansCredit    numeric(15,2), BeginBalansSaldo    numeric(15,2),
  VorigePeriodesDebet numeric(15,2), VorigePeriodesCredit numeric(15,2), VorigePeriodesSaldo numeric(15,2),
  LaatstePeriodeDebet numeric(15,2), LaatstePeriodeCredit numeric(15,2), LaatstePeriodeSaldo numeric(15,2),
  ProefDebet          numeric(15,2), ProefCredit          numeric(15,2), ProefSaldo          numeric(15,2),
  SaldiDebet          numeric(15,2), SaldiCredit          numeric(15,2), SaldiSaldo          numeric(15,2),
  Verlies             numeric(15,2), Winst                numeric(15,2), ResultaatSaldo      numeric(15,2),
  EindDebet           numeric(15,2), EindCredit           numeric(15,2), EindSaldo           numeric(15,2),
  BalVerdicht smallint, BalDecimalen smallint, RegelSoort integer,
  OptelStreepBoven smallint, DubbeleStreepOnder smallint, RedenSubtotaal smallint)

begin
  declare @Teller smallint;
  declare @BalansValCode nchar(3);
  declare @TotaalValCode nchar(3);
  declare @Maximum integer; //tbv. dubbele regels verwijderen
  declare @maxdiepte smallint;
  declare @ParagraafDeb nchar(2);
  declare @ParagraafCred nchar(2);
  declare @SaldoWinst numeric(15,2);
  declare @Voorloop nchar(40);
  //tbv. omrekenverschillen
  declare @AfrondingB      numeric(15,2);
  declare @AfrondingV      numeric(15,2);
  declare @AfrondingH      numeric(15,2);
  declare @AfrondingP      numeric(15,2);
  declare @AfrondingR      numeric(15,2);
  declare @AfrondingE      numeric(15,2);
  declare @AfrondingS      numeric(15,2);
  declare @StreepBovenTotaalInBalansValuta smallint;
  declare @StreepBovenTotaalInTotaalValuta smallint;
  declare @GeheleRangeSelectie smallint;
  declare @NumDeci          integer;

  declare @tmpHulpVolgorde    integer;
  declare @RegelSoort         integer;
  declare @OptelStreepBoven   integer;
  declare @DubbeleStreepOnder integer;
  declare @Sortering          nchar(37);
  declare @ValNummer          integer;
  declare @tmpGid             integer;

  declare @VorigetmpHulpVolgorde    integer;
  declare @VorigeRegelSoort         integer;
  declare @VorigeOptelStreepBoven   integer;
  declare @VorigeDubbeleStreepOnder integer;
  declare @RedenSubtotaal           smallint;
  declare @IsolationLevel           smallint;

  declare @SaldoWinstTekst   long nvarchar;
  declare @SaldoVerliesTekst long nvarchar;

  declare @RubriekTekst      long nvarchar;
  declare @ParagraafTekst    long nvarchar;
  declare @SubParagraafTekst long nvarchar;

  declare @RekeningVanTm     long nvarchar;

  declare local temporary table tmpBalans(
     tmpGid               integer default AutoIncrement,
     tmpHulpVolgorde      integer,
     RksInvoer            nchar(28),
     RksNaam              nchar(40) default '',
     RksNummer            nchar(10),
     KstpGid              integer,
     KstdGid              integer,
     DefaultSoort         smallint,
     ValNummer            integer,
     Valcode              nchar(3) default '',
     BeginPeriodeDebet    numeric(15,2),
     BeginPeriodeCredit   numeric(15,2),
     VorigePeriodesDebet  numeric(15,2),
     VorigePeriodesCredit numeric(15,2),
     LaatstePeriodeDebet  numeric(15,2),
     LaatstePeriodeCredit numeric(15,2),
     ProefDebet           numeric(15,2),
     ProefCredit          numeric(15,2),
     ProefSaldo           numeric(15,2),
     SaldiDebet           numeric(15,2),
     SaldiCredit          numeric(15,2),
     Verlies              numeric(15,2),
     Winst                numeric(15,2),
     EindDebet            numeric(15,2),
     EindCredit           numeric(15,2),
     BalGid               integer,
     BalVerdicht          smallint default 0,
     BalDecimalen         smallint default 0,
     AfdrukZijde          smallint default 0,
     BerekendeZijde       smallint  compute (if (AfdrukZijde = 0 or (AfdrukZijde=2 and (VorigePeriodesDebet + LaatstePeriodeDebet >= VorigePeriodesCredit + LaatstePeriodeCredit))) then 0 else 1 endif),
     RegelSoort           integer,
     Sortering            nchar(37),
     OptelStreepBoven     smallint default 0,
     DubbeleStreepOnder   smallint default 0,
     RedenSubtotaal       smallint,
     primary key (tmpGid)
  ) on commit preserve rows;

  declare cursor_tmpHulpVolgorde cursor for
    select tmpGid, tmpHulpVolgorde, RegelSoort, OptelStreepBoven, DubbeleStreepOnder, ValNummer, Sortering
    from tmpBalans
    order by tmpHulpVolgorde
  for update;


  declare local temporary table tmpTeVerdichten(
    RksNummer nchar(10))
  on commit preserve rows;

  Create index idx_tmpBalansSoort     on tmpBalans (regelsoort);
  Create index idx_tmpBalansSortering on tmpBalans (Sortering);
  create index idx_tmpRksNummer       on tmpBalans(RksNummer);
  create index idx_tmpBal1            on tmpBalans (RksInvoer);
  Create index idx_tmpHulpVolgorde on tmpBalans (tmpHulpVolgorde);  //Let op: ivm. bug in ASA 6 EN 7 moet deze index hier staan, NIET na een delete!!
  create index idx_tmpKstpKstd        on tmpBalans (KstpGid,KstdGid);


  set @@ErrorTextProcedure = 'rapNormaleBalans > ';
  //call TraceBegin (@@ErrorTextProcedure + '@BjGid = ' + string(@BjGid) + ', @VanPernr = ' + string(@VanPernr) + ', @TotPernr = ' + string(@TotPernr) + ', @SelecteerOp = ' + string(@SelecteerOp) + ', @VanRks = ' + @VanRks+', @TotRks = ' + @TotRks);
  //call Trace('rapNormaleBalans > @SoortBoeking='+string(@SoortBoeking)+', @OokNulSaldi='+string(@OokNulSaldi)+', @ComprimeerBalans='+string(@ComprimeerBalans)+', @DebUitsplitsen='+string(@DebUitsplitsen)+', @CredUitsplitsen='+string(@CredUitsplitsen));
  //call Trace('rapNormaleBalans > @KstpUitsplitsen='+string(@KstpUitsplitsen)+', @KstdUitsplitsen='+string(@KstdUitsplitsen)+', @AantalCijfers='+string(@AantalCijfers)+', @BalansInValuta='+string(@BalansInValuta)+', @TotalenInValuta='+string(@TotalenInValuta));

  select Paragraaf into @ParagraafDeb  from tabParagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 10;
  select Paragraaf into @ParagraafCred from tabParagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 20;

  //Als we toch al minder dan 3 cijfers afdrukken zijn de deb./cred. al gecomprimeerd. Hiermee voorkomen we dat
  //de deb./cred. apart worden behandeld (met totaalstreep etc.)
  if @ComprimeerBalans = 1 and @AantalCijfers <= 2 then
    set @DebUitsplitsen  = 1;
    set @CredUitsplitsen = 1;
  end if;

  set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 1';
  //call Trace(@@ErrorTextProcedure);

  select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @BalansInValuta;

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  insert into tmpBalans (
              RegelSoort, Sortering, ValNummer, RksInvoer, RksNummer, KstpGid, KstdGid,
              RksNaam, DefaultSoort, AfdrukZijde,
              BeginPeriodeDebet,   BeginPeriodeCredit,
              VorigePeriodesDebet, VorigePeriodesCredit,
              LaatstePeriodeDebet, LaatstePeriodeCredit,
              ProefDebet, ProefCredit, ProefSaldo,
              SaldiDebet, SaldiCredit,
              Verlies, Winst, EindDebet, EindCredit, BalVerdicht, BalDecimalen)
  select
    1,
    RksInvoer,
    @BalansInValuta, //ACW 24-01-2001: hier stond eerst RksValNummer,
    RksInvoer,
    RksNummer,
    RksKstpGid,
    RksKstdGid,
    RksNaam,
    DefaultSoort,
    AfdrukZijde,
    // Proefbalans (verdeeld naar Beginbalans, vorige periodes (incl. beginbalans) en laatste periode
    if @BalansInValuta = @@BasisValutanummer then if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif, @BalansInValuta, @BjGid, @TotPernr, 2) endif BDebet,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif, @BalansInValuta, @BjGid, @TotPernr, 2) endif BCredit,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernr >= @TotPernr then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernr >= @TotPernr then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) endif, @BalansInValuta, @BjGid, @TotPernr, 2) endif VDebet,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernr >= @TotPernr then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernr >= @TotPernr then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) endif, @BalansInValuta, @BjGid, @TotPernr, 2) endif VCredit,
    if @BalansInValuta = @@BasisValutanummer then IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0) else ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0), @BalansInValuta, @BjGid, @TotPernr, 2) endif HDebet,
    if @BalansInValuta = @@BasisValutanummer then IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0) else ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0), @BalansInValuta, @BjGid, @TotPernr, 2) endif HCredit,

    // Proefbalans totaal en saldo
    VDebet     + HDebet      ProefDebet,
    VCredit    + HCredit     ProefCredit,
    ProefDebet - ProefCredit ProefSaldo,

    // Saldibalans
    if (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefSaldo >= 0)) then ProefSaldo else 0 endif SaldiDebet,
    if (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefSaldo <  0)) then -ProefSaldo  else 0 endif SaldiCredit,

    // Resultatenrekening
    if DefaultSoort in (3,4,5)     and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefSaldo >= 0)) then  ProefSaldo else 0 endif Verlies,
    if DefaultSoort in (3,4,5)     and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefSaldo <  0)) then -ProefSaldo else 0 endif Winst,

    // Eindbalans
    if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefSaldo >= 0)) then  ProefSaldo else 0 endif EindDebet,
    if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefSaldo <  0)) then -ProefSaldo else 0 endif EindCredit,

    // Comprimeren van deze regel?
    if @ComprimeerBalans <> 1 then
      if DefaultSoort=6 then
        abs(@DebUitSplitsen-1)
      else
        if DefaultSoort=7 then
          abs(@CredUitSplitsen-1)
        else
          if RksKstpGid is not null then
            abs(@KstpUitSplitsen-1)
          else
            if RksKstdGid is not null then
              abs(@KstdUitSplitsen-1)
            else
              (if @ComprimeerBalans = 1 then 1 else 0 endif)
            endif
          endif
        endif
      endif
    else
      1
    endif BalVerdicht,
    // Comprimeer evt. op dit aantal cijfers
    if ((DefaultSoort=6 and @DebUitSplitsen=0)
        or (DefaultSoort=7 and @CredUitSplitsen=0))
       and @AantalCijfers > 2 then
      2
    else
      if ((RksKstpGid is not null and @KstpUitSplitsen=0)
          or (RksKstdGid is not null and @KstdUitSplitsen=0))
       and @ComprimeerBalans=1
       and @AantalCijfers > 2 then
         2
       else
         @AantalCijfers
       endif
    endif BalDecimalen
  from
    tabRekeningschema
  where
    ((@SelecteerOp = 0 and RksInvoer   between @VanRks and @TotRks)  or
     (@SelecteerOp = 1 and RksZoekcode between @VanRks and @TotRks)  or
     (@SelecteerOp = 2 and RksNaam     between @VanRks and @TotRks))
   and
     (    @OokNulSaldi=1
      or (@OokNulSaldi=2 and (   (isnull(ProefSaldo,0) <> 0)
                              or (RksGid in (select JrRksGid
                                             from  tabJournaalRegel
                                             where JrPerNr between @VanPerNr and @TotPerNr
                                               and (JrBjGid = @BjGid)
                                               and ((@SoortBoeking = 0 and RegelNummer is not Null) or
                                                    (@SoortBoeking = 1 and RegelNummer is  Null) or
                                                    (@SoortBoeking = 2)
                                                   )
                                             )
                                  )
                             )
         )
      or  //RB 14-10-2003 : LET OP bedragen beginbalans, vorige periodes en huidige perides
          //                       APART testen anders zijn de totalen niet in evenwicht
         (@OokNulSaldi=0 and ( (isnull(BDebet,0) - isnull(BCredit,0) <> 0) or
                               (isnull(VDebet,0) - isnull(VCredit,0) <> 0) or
                               (isnull(HDebet,0) - isnull(HCredit,0) <> 0)
                             )
         )
         //0-saldi niet afdrukken, dus begin+vorige+huidige optellen en die vergelijken, ook beginbalans etc. apart testen!!
         //(@OokNulSaldi=0 and isnull(ProefSaldo,0) <> 0)   RB 14-10-2003 VERWIJDERD!!!!!

     );

  set temporary option isolation_level = @IsolationLevel;

  if exists(select 1 from tmpBalans) then
    set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 1b';
    //call Trace(@@ErrorTextProcedure);

    //Testen of we de gehele range hebben; zoniet, dan geen omrekenverschillen bepalen!
    set @GeheleRangeSelectie = 0;
    if not exists(select 1 from tabRekeningSchema where not
                    ((@SelecteerOp = 0 and RksInvoer between @VanRks and @TotRks) or
                     (@SelecteerOp = 1 and RksZoekCode between @VanRks and @TotRks) or
                     (@SelecteerOp = 2 and RksNaam between @VanRks and @TotRks))) then
      //Ok, alle rekeningen geselecteerd
      set @GeheleRangeSelectie = 1;
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 2';
    //call Trace(@@ErrorTextProcedure);

    if (@ComprimeerBalans in (0,1)) and (@KstpUitsplitsen = 0 or @KstdUitsplitsen = 0) then

      //Zorg er eerst voor dat alle hoofdrekeningen aanwezig zijn
      insert into tmpBalans (RegelSoort, Sortering, ValNummer, RksInvoer, RksNummer, KstpGid, KstdGid, RksNaam, DefaultSoort, AfdrukZijde, BalVerdicht, BalDecimalen)
      select 1, RksInvoer, RksValNummer, RksInvoer, RksNummer, RksKstpGid, RksKstdGid, RksNaam, DefaultSoort, AfdrukZijde, @ComprimeerBalans,
             if ((DefaultSoort=6 and @DebUitSplitsen=0) or (DefaultSoort=7 and @CredUitSplitsen=0) or (RksKstpGid is not null and @KstpUitSplitsen=0) or (RksKstdGid is not null and @KstdUitSplitsen=0)) and @ComprimeerBalans=1 and @AantalCijfers > 2 then 2 else @AantalCijfers endif
      from tabRekeningschema where RksKstpGid is null and RksKstdGid is null
           and RksInvoer in (select distinct RksNummer from tmpBalans where KstpGid is not null or KstdGid is not null)  //Geef de hoofdrekeningen terug van die rekening die een kostenplaats/drager hebben
           and RksInvoer not in (select RksInvoer from tmpBalans where KstpGid is null or KstdGid is null);           //Als de hoofdrekening alleen in de balans staat dan niet toevoegen


      set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 2a';
      //call Trace(@@ErrorTextProcedure);

      //Nu de hoofdrekening updaten a.d.h.v. de rekeningen met kostenplaatsen en/of kostendragers
      if @KstpUitsplitsen = 0 or @KstdUitsplitsen = 0 then
        //Alleen als 1 of beide inderdaadniet uitgesplitst is (dus er moet een optelling plaatsvinden)
        set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 2b';
        //call Trace(@@ErrorTextProcedure);

        if @KstpUitsplitsen = 0 then
          insert into tmpTeVerdichten(RksNummer)
          select distinct c.RksNummer from tmpBalans c where c.KstpGid is not null;
          update tmpBalans b
          set
            BeginPeriodeDebet    = isnull(BeginPeriodeDebet  ,0)   + isnull((select sum(a.BeginPeriodeDebet)     from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            BeginPeriodeCredit   = isnull(BeginPeriodeCredit ,0)   + isnull((select sum(a.BeginPeriodeCredit)    from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            VorigePeriodesDebet  = isnull(VorigePeriodesDebet  ,0) + isnull((select sum(a.VorigePeriodesDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            VorigePeriodesCredit = isnull(VorigePeriodesCredit ,0) + isnull((select sum(a.VorigePeriodesCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            LaatstePeriodeDebet  = isnull(LaatstePeriodeDebet ,0)  + isnull((select sum(a.LaatstePeriodeDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            LaatstePeriodeCredit = isnull(LaatstePeriodeCredit,0)  + isnull((select sum(a.LaatstePeriodeCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefDebet           = isnull(ProefDebet,0)            + isnull((select sum(a.ProefDebet)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefCredit          = isnull(ProefCredit,0)           + isnull((select sum(a.ProefCredit)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefSaldo           = isnull(ProefSaldo,0)            + isnull((select sum(a.ProefSaldo)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            SaldiDebet           = isnull(SaldiDebet  ,0)          + isnull((select sum(a.SaldiDebet)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            SaldiCredit          = isnull(SaldiCredit ,0)          + isnull((select sum(a.SaldiCredit)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            Verlies              = isnull(Verlies     ,0)          + isnull((select sum(a.Verlies)               from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            Winst                = isnull(Winst       ,0)          + isnull((select sum(a.Winst)                 from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            EindDebet            = isnull(EindDebet   ,0)          + isnull((select sum(a.EindDebet)             from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            EindCredit           = isnull(EindCredit  ,0)          + isnull((select sum(a.EindCredit)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0)
          from   tmpBalans b inner join tmpTeVerdichten on (tmpTeVerdichten.RksNummer = b.RksNummer)
          where  KstpGid is null and KstdGid is null;
//                 and RksNummer in ( select c.RksNummer from tmpBalans c where c.KstpGid is not null); -> DIT werkt dus niet, daarom de tmpTeVerdichten
          delete tmpBalans where KstpGid is not null;
        end if;

        if @KstdUitsplitsen = 0 then
          //LET OP: iom. RB en ACW besloten om ook de kostendragers indien niet uitgesplitst direct op de kostensoort (de rekening) te zetten ipv. eerst te
          //        proberen of die op de kostenplaats kan worden gezet. (probleem: bestaat de kostenplaats wel? Zoniet, dan alsnog op de kostensoort boeken)
          //Bepaal te verdichten rekeningen (apart ivm. bug in ASA6!!!)
          delete from tmpTeVerdichten;
          insert into tmpTeVerdichten(RksNummer)
          select distinct c.RksNummer from tmpBalans c where c.KstdGid is not null;

          update tmpBalans b
          set
            BeginPeriodeDebet    = isnull(BeginPeriodeDebet  ,0)   + isnull((select sum(a.BeginPeriodeDebet)     from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            BeginPeriodeCredit   = isnull(BeginPeriodeCredit ,0)   + isnull((select sum(a.BeginPeriodeCredit)    from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            VorigePeriodesDebet  = isnull(VorigePeriodesDebet  ,0) + isnull((select sum(a.VorigePeriodesDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            VorigePeriodesCredit = isnull(VorigePeriodesCredit ,0) + isnull((select sum(a.VorigePeriodesCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            LaatstePeriodeDebet  = isnull(LaatstePeriodeDebet ,0)  + isnull((select sum(a.LaatstePeriodeDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            LaatstePeriodeCredit = isnull(LaatstePeriodeCredit,0)  + isnull((select sum(a.LaatstePeriodeCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefDebet           = isnull(ProefDebet,0)            + isnull((select sum(a.ProefDebet)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefCredit          = isnull(ProefCredit,0)           + isnull((select sum(a.ProefCredit)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefSaldo           = isnull(ProefSaldo,0)            + isnull((select sum(a.ProefSaldo)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            SaldiDebet           = isnull(SaldiDebet  ,0)          + isnull((select sum(a.SaldiDebet)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            SaldiCredit          = isnull(SaldiCredit ,0)          + isnull((select sum(a.SaldiCredit)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            Verlies              = isnull(Verlies     ,0)          + isnull((select sum(a.Verlies)               from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            Winst                = isnull(Winst       ,0)          + isnull((select sum(a.Winst)                 from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            EindDebet            = isnull(EindDebet   ,0)          + isnull((select sum(a.EindDebet)             from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            EindCredit           = isnull(EindCredit  ,0)          + isnull((select sum(a.EindCredit)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0)
          from   tmpBalans b inner join tmpTeVerdichten on (tmpTeVerdichten.RksNummer = b.RksNummer)
          where  KstpGid is null and KstdGid is null;
//                 and RksNummer in ( select c.RksNummer from tmpBalans c where c.KstdGid is not null); -> DIT werkt dus niet, daarom de tmpTeVerdichten
          delete tmpBalans where KstdGid is not null;
        end if;

      end if;

    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 3';
    //call Trace(@@ErrorTextProcedure);

    set @Voorloop = 'ZZZZZZZZZZZZZZZZZZZZZZZZZ';

    if @ComprimeerBalans = 2 then  //Conform balans

      update tmpBalans set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(RksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' and DecimalenSubTotalen<>0;

      update tmpBalans set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  BalGid is null and DetailBlCode=0 and Paragraaf = left(RksInvoer,2) and Trim(Paragraaf)<>'' and DecimalenSubTotalen<>0;

      update tmpBalans set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  BalGid is null and DetailBlCode=0 and Rubriek = left(RksInvoer,1) and Paragraaf='' and DecimalenSubTotalen<>0;

      update tmpBalans set BalGid = null;

      update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(RksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' ;

      update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  BalGid is null and DetailBlCode=0 and Paragraaf = left(RksInvoer,2) and Trim(Paragraaf)<>'';

      update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  BalGid is null and DetailBlCode=0 and Rubriek = left(RksInvoer,1) and Paragraaf='';

      //RVL Bug 8750 : Als er voor een bepaalde rekening geen rubriek aanwezig was in de balanscodetabel en er hingen aan die rekeningen
      //               ook nog kostenplaatsen, dan werden de kostenplaatsen niet afgedrukt.
      //               Maar de bedragen die op die rekeningen stonden werden niet opgeteld bij de 'hoofdrekening'.
      //               Bij de totalen per paragraaf werden de bedragen wel meegenomen. Nu worden de kostenplaatsenrekeningen
      //               wel afgedrukt door BalVerdicht op 0 komt te zetten
      update tmpBalans set BalVerdicht = 0 where BalGid is null;
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 4';
    //call Trace(@@ErrorTextProcedure);

    //Subtotalen maken volgens aantal decimalen
    set @RubriekTekst      = _U('Rubriek %1!');
    set @ParagraafTekst    = _U('Paragraaf %1!');
    set @SubParagraafTekst = _U('Subparagraaf %1!');

    set @SaldoWinstTekst   = _U('Saldo winst');
    set @SaldoVerliesTekst = _U('Saldo verlies');

    select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;
    set @Teller = 5; //5 = subpar, 1=rubriek, 0=totaal generaal
    while @Teller > 0 loop

      insert into tmpBalans
        (RegelSoort, Sortering, RksInvoer, RksNaam, ValNummer, ValCode,
         BeginPeriodeDebet, BeginPeriodeCredit,
         VorigePeriodesDebet, VorigePeriodesCredit,
         LaatstePeriodeDebet, LaatstePeriodeCredit,
         ProefDebet, ProefCredit, ProefSaldo,
         SaldiDebet, SaldiCredit,
         Verlies, Winst,
         EindDebet, EindCredit,
         BalVerdicht, BalDecimalen)
      select
        15-@Teller,
        substr(RksInvoer, 1, @Teller)+'z' Sortering, //(sub)paragraaf ONDER de rekeningen!!!
        substr(RksInvoer, 1, @Teller)+' :' HulpRksInvoer,
        IsNull(OmsBalansCodeDetails, if @Teller = 1 then _P(@RubriekTekst, substr(RksInvoer, 1, 1)) else if @Teller = 2 then _P(@ParagraafTekst, substr(RksInvoer, 1, 2)) else _P(@SubParagraafTekst, substr(RksInvoer, 3, @Teller-2)) endif endif) BalOms,
        @BalansInValuta,
        @BalansValCode,
        sum(if RegelSoort = 1 then BeginPeriodeDebet    else 0 endif),
        sum(if RegelSoort = 1 then BeginPeriodeCredit   else 0 endif),
        sum(if RegelSoort = 1 then VorigePeriodesDebet  else 0 endif),
        sum(if RegelSoort = 1 then VorigePeriodesCredit else 0 endif),
        sum(if RegelSoort = 1 then LaatstePeriodeDebet  else 0 endif),
        sum(if RegelSoort = 1 then LaatstePeriodeCredit else 0 endif),
        sum(if RegelSoort = 1 then ProefDebet           else 0 endif),
        sum(if RegelSoort = 1 then ProefCredit          else 0 endif),
        sum(if RegelSoort = 1 then ProefSaldo           else 0 endif),
        sum(if RegelSoort = 1 then SaldiDebet           else 0 endif),
        sum(if RegelSoort = 1 then SaldiCredit          else 0 endif),
        sum(if RegelSoort = 1 then Verlies              else 0 endif),
        sum(if RegelSoort = 1 then Winst                else 0 endif),
        sum(if RegelSoort = 1 then EindDebet            else 0 endif),
        sum(if RegelSoort = 1 then EindCredit           else 0 endif),
        IsNull(BalansVerdicht, max(BalVerdicht)),
        IsNull(DecimalenSubTotalen, max(BalDecimalen))
      from     tmpBalans left outer join tabBalanscodeDetail on (DetailBlCode = 0 and RubParSub = substr(RksInvoer, 1, @Teller) )
      where    length(RksInvoer)>=@Teller and RksInvoer in (select RksInvoer from tmpBalans where (RegelSoort=1 and BalDecimalen >= @Teller))
      group by HulpRksInvoer, Sortering, BalOms, BalansVerdicht, DecimalenSubTotalen;

      set @Teller = @Teller - 1;

    end loop;

    if (@DebUitsplitsen = 0 and @ComprimeerBalans = 0) then
      if exists (select 1 from tmpBalans where DefaultSoort = 6) then
        set @@ErrorTextProcedure = 'rapNormaleBalans > Debiteuren groeperen en als paragraaf er tussen zetten';
        //call Trace(@@ErrorTextProcedure);
        //Let op: als rekening tussenvoegen omdat de paragrafen zelf niet worden afgedrukt!!
        insert into tmpBalans
          (RegelSoort, Sortering, ValNummer, RksInvoer, RksNummer,
           RksNaam, DefaultSoort, AfdrukZijde,
           BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
           ProefDebet, ProefCredit,
           SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, BalVerdicht, BalDecimalen)
        select
          1, @ParagraafDeb Paragraaf, @BalansInValuta,
          Paragraaf+' :', Paragraaf, (select OmsBalansCodeDetails from tabparagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 10), 6,
          min(AfdrukZijde), sum(BeginPeriodeDebet), sum(BeginPeriodeCredit), sum(VorigePeriodesDebet), sum(VorigePeriodesCredit), sum(LaatstePeriodeDebet),
          sum(LaatstePeriodeCredit), sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst),
          sum(EindDebet), sum(EindCredit), if @AantalCijfers < 2 then 0 else 1 endif, min(BalDecimalen)
        from   tmpBalans where DefaultSoort = 6 and Regelsoort = 1;
        delete tmpBalans where DefaultSoort = 6 and Regelsoort = 1 and RksInvoer <> @ParagraafDeb + ' :'
      end if;
    end if;

    if (@CredUitsplitsen = 0 and @ComprimeerBalans = 0 ) then
      if exists (select 1 from tmpBalans where DefaultSoort = 7) then
        set @@ErrorTextProcedure = 'rapNormaleBalans > Crediteuren groeperen en als paragraaf er tussen zetten';
        //call Trace(@@ErrorTextProcedure);
        //Let op: als rekening tussenvoegen omdat de paragrafen zelf niet worden afgedrukt!!
        insert into tmpBalans
          (RegelSoort, Sortering, ValNummer, RksInvoer, RksNummer,
           RksNaam, DefaultSoort, AfdrukZijde,
           BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
           ProefDebet, ProefCredit,
           SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, BalVerdicht, BalDecimalen)
        select
          1, @ParagraafCred Paragraaf, @BalansInValuta,
          Paragraaf+' :', Paragraaf, (select OmsBalansCodeDetails from tabparagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 20), 6,
          min(AfdrukZijde), sum(BeginPeriodeDebet), sum(BeginPeriodeCredit), sum(VorigePeriodesDebet), sum(VorigePeriodesCredit), sum(LaatstePeriodeDebet),
          sum(LaatstePeriodeCredit), sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst),
          sum(EindDebet), sum(EindCredit), if @AantalCijfers < 2 then 0 else 1 endif, min(BalDecimalen)
        from   tmpBalans where DefaultSoort = 7 and Regelsoort = 1;
        delete tmpBalans where DefaultSoort = 7 and Regelsoort = 1 and RksInvoer <> @ParagraafCred + ' :'
      end if;
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalans > Verdichten';
    //call Trace(@@ErrorTextProcedure);
    delete tmpBalans where BalVerdicht = 1 and RegelSoort = 1;

    set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 6';
    //call Trace(@@ErrorTextProcedure);

    //Subtotalen omrekenen naar juiste valuta
    select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;
    if @BalansInValuta <> @TotalenInValuta then
      select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @TotalenInValuta;
      insert into
        tmpBalans
        (RegelSoort, Sortering, RksInvoer, RksNaam, ValNummer, ValCode, BalVerdicht, BalDecimalen,
         BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
         ProefDebet, ProefCredit, ProefSaldo,
         SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit)
      select
        6+RegelSoort,
        Sortering+'z',
        RksInvoer,
        RksNaam,
        @TotalenInValuta,
        @TotaalValCode,
        BalVerdicht,
        BalDecimalen,
        ValutaOmrekenen(@BalansInValuta, BeginPeriodeDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, BeginPeriodeCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, VorigePeriodesDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, VorigePeriodesCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, LaatstePeriodeDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, LaatstePeriodeCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, ProefDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, ProefCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, ProefSaldo, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, SaldiDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, SaldiCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, Verlies, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, Winst, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, EindDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, EindCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci)
      from
        tmpBalans tmp where RegelSoort between 10 and 15;
    end if;

    //Opnieuw nummers uitdelen om dubbele strepen te zetten
    update tmpBalans
    set    tmpHulpVolgorde = number(*)
    order by Sortering;

    set @VorigetmpHulpVolgorde    = 0;
    set @VorigeRegelSoort         = 99;
    set @VorigeOptelStreepBoven   = 0;
    set @VorigeDubbeleStreepOnder = 0;

    open cursor_tmpHulpVolgorde;
    LoopVolgorde:
    loop
      Fetch next cursor_tmpHulpVolgorde into @tmpGid, @tmpHulpVolgorde, @RegelSoort, @OptelStreepBoven, @DubbeleStreepOnder, @ValNummer, @Sortering;
      if sqlstate = '02000' then
        leave LoopVolgorde;
      end if;
      //Als de vorige regel een kleinere regelsoort heeft *of* een enkele/dubbele streep, dan ook een dubbele streep zitten
      if @VorigeRegelSoort < @RegelSoort and (@ValNummer = @TotalenInValuta or @BalansInValuta = @TotalenInValuta) then
        set @DubbeleStreepOnder = 1;
      end if;
      if @VorigeRegelSoort < @RegelSoort and @VorigeDubbeleStreepOnder = 0 and @VorigeRegelSoort <> 99 and @ValNummer = @BalansInValuta then
        set @OptelStreepBoven = 1;
      end if;
      if @VorigeOptelStreepBoven + @VorigeDubbeleStreepOnder <> 0 and @VorigeRegelSoort <= @RegelSoort then
        set @DubbeleStreepOnder = 1;
      end if;

      // Als dit een subtotaaltje is dan een dubbele streep!
      //MR 18-jun-2007 Bug# 26270 : Maar wel alleen als niet gecomprimeerd afdrukken.
      if @Sortering like '%z' And @ComprimeerBalans <> 1 then
        set @DubbeleStreepOnder = 1;
      end if;

      if @OptelStreepBoven + @DubbeleStreepOnder <> 0 then
        update tmpBalans
        set    OptelStreepBoven = @OptelStreepBoven,
               DubbeleStreepOnder = @DubbeleStreepOnder
        where tmpGid = @tmpGid;
      end if;
      set @VorigetmpHulpVolgorde    = @tmpHulpVolgorde;
      set @VorigeRegelSoort         = @RegelSoort;
      set @VorigeOptelStreepBoven   = @OptelStreepBoven;
      set @VorigeDubbeleStreepOnder = @DubbeleStreepOnder;
    end loop LoopVolgorde;
    close cursor_tmpHulpVolgorde;

    // De laatste gewone regel moet altijd een dubbele streep hebben
    if @VorigeDubbeleStreepOnder = 0 then
      // Dus als die het nog niet had, dan toevoegen!
      update tmpBalans
      set    DubbeleStreepOnder = 1
      where tmpHulpVolgorde = (select max(a.tmpHulpVolgorde) from tmpBalans a);
    end if;


    //Kolommenbalans, Saldo winst/verlies bepalen voor de kolommenbalans
    select sum(Winst - Verlies) into @SaldoWinst from tmpBalans where regelsoort = 14;
    insert into tmpBalans(RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                          Verlies, Winst, EindDebet, EindCredit)
    values( 35 + if isnull(@SaldoWinst,0) < 0 then 1 else 0 endif, @Voorloop+'14F',
            if isnull(@SaldoWinst,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
            @BalansInValuta, @BalansValCode,
            if @SaldoWinst >= 0 then     @SaldoWinst endif,  if @SaldoWinst < 0 then abs(@SaldoWinst) endif,
            if @SaldoWinst <= 0 then abs(@SaldoWinst) endif, if @SaldoWinst > 0 then     @SaldoWinst  endif);
    if @BalansInValuta <> @TotalenInValuta then
      //Ook in andere valuta saldo winst/verlies bepalen
      select sum(Winst - Verlies) into @SaldoWinst from tmpBalans where regelsoort = 20;
      insert into tmpBalans(RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                            Verlies, Winst, EindDebet, EindCredit)
      values( 37 + if isnull(@SaldoWinst,0) < 0 then 1 else 0 endif, @Voorloop+'20F',
              if isnull(@SaldoWinst,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
              @TotalenInValuta, @TotaalValCode,
              if @SaldoWinst >= 0 then     @SaldoWinst endif,  if @SaldoWinst < 0 then abs(@SaldoWinst) endif,
              if @SaldoWinst <= 0 then abs(@SaldoWinst) endif, if @SaldoWinst > 0 then     @SaldoWinst  endif);
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalans > Stap 12';
    //call Trace(@@ErrorTextProcedure);

    //Bepaal omrekenverschillen en subtotalen agv. afdrukken in andere valuta
    set @RedenSubtotaal = 0; // 1: in balansvaluta een omrekening, 2= in andere val. een omrekening, 3=beide
    set @Teller = 1; //1=balansvaluta, 2=andere valuta
    while @Teller <= 2 loop
      if @GeheleRangeSelectie = 1 then
        select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = (if @teller = 1 then @BalansInValuta else @TotalenInValuta endif);

        set @AfrondingB = 0;
        set @AfrondingV = 0;
        set @AfrondingH = 0;
        set @AfrondingP = 0;
        set @AfrondingR = 0;
        set @AfrondingS = 0;
        set @AfrondingE = 0;
        select sum(round((isnull(BeginPeriodeDebet,0)-isnull(BeginPeriodeCredit,0)), @numDeci)),
               sum(round(VorigePeriodesDebet, @numDeci))  - sum(round(VorigePeriodesCredit, @numDeci)),
               sum(round(LaatstePeriodeDebet, @numDeci)) - sum(round(LaatstePeriodeCredit, @numDeci)),
               sum(round(Verlies, @numDeci))     - sum(round(Winst, @numDeci)),
               sum(round(ProefDebet, @numDeci)) - sum(round(ProefCredit, @numDeci)),
               sum(round(SaldiDebet, @numDeci)) - sum(round(SaldiCredit, @numDeci)),
               sum(round(EindDebet, @numDeci)) - sum(round(EindCredit, @numDeci))
        into   @AfrondingB, @AfrondingV, @AfrondingH, @AfrondingR, @AfrondingP, @AfrondingS, @AfrondingE
        from   tmpBalans
        where  (@teller = 1 and regelsoort in (14, 35, 36)) or
               (@teller = 2 and regelsoort in (20, 37, 38));
        set @AfrondingE = isnull(@AfrondingE,0) + isnull(@AfrondingR,0);

        set @@ErrorTextProcedure = 'rapNormaleBalans > @AfrondingB='+string(@AfrondingB)+', @AfrondingV='+string(@AfrondingV)+', @AfrondingH='+string(@AfrondingH)+', @AfrondingR='+string(@AfrondingR)+', @AfrondingS='+string(@AfrondingS)+', @AfrondingE='+string(@AfrondingE);
        //call Trace(@@ErrorTextProcedure);

        if isnull(@afrondingB,0) <> 0 or isnull(@afrondingV,0) <> 0 or isnull(@afrondingH,0) <> 0 or isnull(@AfrondingP,0) <> 0 or isnull(@AfrondingS,0) <> 0 or isnull(@AfrondingE,0) <> 0 then
          set @RedenSubtotaal = @RedenSubtotaal + @teller;
          if @teller = 1 then
            set @StreepBovenTotaalInBalansValuta = 1;
          else
            set @StreepBovenTotaalInTotaalValuta = 1;
          end if;

          insert into tmpBalans(
            RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
            BeginPeriodeDebet, BeginPeriodeCredit,
            VorigePeriodesDebet, VorigePeriodesCredit,
            LaatstePeriodeDebet, LaatstePeriodeCredit,
            ProefDebet, ProefCredit, ProefSaldo,
            SaldiDebet, SaldiCredit, EindDebet, EindCredit)
          values( if @teller = 1 then 39 else 40 endif, @Voorloop+if @teller = 1 then '14G' else '20G' endif,
                  _U('(Omrekenverschil)'),
                  if @teller = 1 then @BalansInValuta else @TotalenInValuta endif,
                  if @teller = 1 then @BalansValCode else @TotaalValCode endif,
                  if @AfrondingB < 0 then abs(@AfrondingB) endif, if @AfrondingB > 0 then @AfrondingB endif,
                  if @AfrondingV < 0 then abs(@AfrondingV) endif, if @AfrondingV > 0 then @AfrondingV endif,
                  if @AfrondingH < 0 then abs(@AfrondingH) endif, if @AfrondingH > 0 then @AfrondingH endif,
                  if @AfrondingP < 0 then abs(@AfrondingP) endif, if @AfrondingP > 0 then @AfrondingP endif, @AfrondingP,
                  if @AfrondingS < 0 then abs(@AfrondingS) endif, if @AfrondingS > 0 then @AfrondingS endif,
                  if @AfrondingE < 0 then abs(@AfrondingE) endif, if @AfrondingE > 0 then @AfrondingE endif);
        end if;
      end if;

      //Altijd subtotaal erbij (kolommenbalans of we hebben een omreken-afronding)
      insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                             BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
                             ProefDebet, ProefCredit, ProefSaldo, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, RedenSubtotaal)
      select   RegelSoort+10, @Voorloop+string(RegelSoort)+'E', _U('Subtotaal'),
               if RegelSoort = 14 then @BalansInValuta else @TotalenInValuta endif,
               if RegelSoort = 14 then @BalansValCode else @TotaalValCode endif,
               round(sum(BeginPeriodeDebet), @numDeci), round(sum(BeginPeriodeCredit), @numDeci), round(sum(VorigePeriodesDebet), @numDeci),
               round(sum(VorigePeriodesCredit), @numDeci), round(sum(LaatstePeriodeDebet), @numDeci), round(sum(LaatstePeriodeCredit), @numDeci),
               round(sum(ProefDebet), @numDeci), round(sum(ProefCredit), @numDeci), round(sum(ProefSaldo), @numDeci),
               round(sum(SaldiDebet), @numDeci), round(sum(SaldiCredit), @numDeci), round(sum(Verlies), @numDeci),
               round(sum(Winst), @numDeci), round(sum(EindDebet), @numDeci), round(sum(EindCredit), @numDeci),
               if @RedenSubtotaal in (1,3) and RegelSoort =  14 or
                  @RedenSubtotaal in (2,3) and RegelSoort <> 14 then
                 1 // Reden: omrekenverschil
               else
                 0 // reden: saldo winst/verlies
               endif
      from     tmpBalans
      where    (@teller = 1 and RegelSoort = 14) or
               (@teller = 2 and RegelSoort = 20)
      group by RegelSoort;

      set @Teller = @Teller + 1; //Let op: NIET optimaliseren (door direct op 3 te zetten) ivm. subtotaal!!
    end loop;

    set @RekeningVanTm = _U('%1! t/m %2!');

    if @BalansInValuta <> @TotalenInValuta then
      //Totaal generaal in andere valuta
      insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                             BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
                             ProefDebet, ProefCredit, ProefSaldo,
                             SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, OptelStreepBoven)
      select   99, @Voorloop+'20Z', _P(@RekeningVanTm, @VanRks, @TotRks),
               @TotalenInValuta,
               @TotaalValCode,
               sum(BeginPeriodeDebet), sum(BeginPeriodeCredit), sum(VorigePeriodesDebet), sum(VorigePeriodesCredit), sum(LaatstePeriodeDebet), sum(LaatstePeriodeCredit),
               sum(ProefDebet), sum(ProefCredit), sum(ProefSaldo), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit),
               0 // nooit een optelstreep! (wordt in layout opgelost)
      from     tmpBalans
      where    RegelSoort in (20, 37, 38, 40);
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalans > Totaal generaal';
    //call Trace(@@ErrorTextProcedure);

    insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                           BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
                           ProefDebet, ProefCredit, ProefSaldo, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, OptelStreepBoven)
    select   98 , @Voorloop+'14Z', _P(@RekeningVanTm, @VanRks, @TotRks),
             @BalansInValuta,
             @BalansValCode,
             sum(BeginPeriodeDebet), sum(BeginPeriodeCredit), sum(VorigePeriodesDebet), sum(VorigePeriodesCredit), sum(LaatstePeriodeDebet), sum(LaatstePeriodeCredit),
             sum(ProefDebet), sum(ProefCredit), sum(ProefSaldo), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit),
             0 // nooit een optelstreep! (wordt in layout opgelost)
    from     tmpBalans
    where    RegelSoort in (14, 35, 36, 39);
  end if; //alleen als er wel regels in staan, anders alles overgeslagen!

  set @@ErrorTextProcedure = 'rapNormaleBalans';
  //call TraceEind(@@ErrorTextProcedure);

  select   RksInvoer, RksNummer, RksNaam, ValNummer, Valcode,
           BeginPeriodeDebet BeginBalansDebet, BeginPeriodeCredit BeginBalansCredit, (isnull(BeginPeriodeDebet,0)-isnull(BeginPeriodeCredit,0)) BeginBalansSaldo,
           VorigePeriodesDebet, VorigePeriodesCredit, VorigePeriodesDebet - VorigePeriodesCredit VorigePeriodesSaldo,
           LaatstePeriodeDebet, LaatstePeriodeCredit, LaatstePeriodeDebet - LaatstePeriodeCredit LaatstePeriodeSaldo,
           ProefDebet,          ProefCredit,          ProefSaldo,
           SaldiDebet,          SaldiCredit,          SaldiDebet - SaldiCredit SaldiSaldo,
           Verlies,             Winst,                Verlies - Winst ResultaatSaldo,
           EindDebet,           EindCredit,           EindDebet - EindCredit EindSaldo,
           BalVerdicht, BalDecimalen, RegelSoort,
           OptelStreepBoven, DubbeleStreepOnder, RedenSubtotaal
 from      tmpBalans
 order by  Sortering;
end;

//call RapNormaleBalans(1, 0, 12, 0, '1010', '9910' , 0, 1, 0, 0, 0, 1, 10, 1, 0, 0)
//call RapNormaleBalans(1, 0, 12, 0, '', '99999999' , 0, 1, 0, 0, 0, 0, 0, 1, 0, 0)


create or replace procedure rapNormaleBalansMetAnderJaar(
  in @BjGid            Integer,
  in @VanPernr         smallint,
  in @TotPernr         smallint,
  in @SelecteerOp      smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
  in @VanRks           nchar(40), //van nummer/zoekcode/naam
  in @TotRks           nchar(40), //t/m nummer/zoekcode/naam
  in @SoortBoeking     smallint, //0=definitief, 1=voorlopig, 2=beide
  in @OokNulSaldi      smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
  in @ComprimeerBalans smallint, //0=nee, 1=ja, 2=conform balans
  in @DebUitsplitsen   smallint, //0=nee, 1=ja (werkt niet bij conform balans)
  in @CredUitsplitsen  smallint, //0=nee, 1=ja (werkt niet bij conform balans)
  in @KstpUitsplitsen  smallint, //0=nee, 1=ja (werkt niet bij conform balans)
  in @KstdUitsplitsen  smallint, //0=nee, 1=ja (werkt niet bij conform balans)
  in @AantalCijfers    smallint, //Aantal cijfers waarop getotaliseerd moet worden 1-5 (werkt niet bij conform balans)
  in @BalansInValuta   integer,  //Valutanummer waarin balans moet worden afgedrukt
  in @TotalenInValuta  integer,  //Valutanummer voor subtotalen
  in @AnderBjGid         integer,  //vergelijkend boekjaargid
  in @VanPernrAnderJaar  smallint, //van periode vergelijkend boekjaar
  in @TotPernrAnderJaar  smallint) //T/m periode vergelijkend boekjaar


result (
  RksInvoer nchar(28), RksNummer nchar(10), RksNaam nchar(40), ValNummer integer, Valcode nchar(3),
  BeginBalansDebet    numeric(15,2), BeginBalansCredit    numeric(15,2), BeginBalansSaldo    numeric(15,2),
  VorigePeriodesDebet numeric(15,2), VorigePeriodesCredit numeric(15,2), VorigePeriodesSaldo numeric(15,2),
  LaatstePeriodeDebet numeric(15,2), LaatstePeriodeCredit numeric(15,2), LaatstePeriodeSaldo numeric(15,2),
  ProefDebet          numeric(15,2), ProefCredit          numeric(15,2), ProefSaldo          numeric(15,2),
  SaldiDebet          numeric(15,2), SaldiCredit          numeric(15,2), SaldiSaldo          numeric(15,2),
  Verlies             numeric(15,2), Winst                numeric(15,2), ResultaatSaldo      numeric(15,2),
  EindDebet           numeric(15,2), EindCredit           numeric(15,2), EindSaldo           numeric(15,2),
  BeginBalansDebetAnderJaar    numeric(15,2), BeginBalansCreditAnderJaar    numeric(15,2), BeginBalansSaldoAnderJaar    numeric(15,2),
  VorigePeriodesDebetAnderJaar numeric(15,2), VorigePeriodesCreditAnderJaar numeric(15,2), VorigePeriodesSaldoAnderJaar numeric(15,2),
  LaatstePeriodeDebetAnderJaar numeric(15,2), LaatstePeriodeCreditAnderJaar numeric(15,2), LaatstePeriodeSaldoAnderJaar numeric(15,2),
  ProefDebetAnderJaar          numeric(15,2), ProefCreditAnderJaar          numeric(15,2), ProefSaldoAnderJaar          numeric(15,2),
  SaldiDebetAnderJaar          numeric(15,2), SaldiCreditAnderJaar          numeric(15,2), SaldiSaldoAnderJaar          numeric(15,2),
  VerliesAnderJaar             numeric(15,2), WinstAnderJaar                numeric(15,2), ResultaatSaldoAnderJaar      numeric(15,2),
  EindDebetAnderJaar           numeric(15,2), EindCreditAnderJaar           numeric(15,2), EindSaldoAnderJaar           numeric(15,2),
  BalVerdicht smallint, BalDecimalen smallint, RegelSoort integer,
  OptelStreepBoven smallint, DubbeleStreepOnder smallint, RedenSubtotaal smallint)

begin
  declare @Teller smallint;
  declare @BalansValCode nchar(3);
  declare @TotaalValCode nchar(3);
  declare @Maximum integer; //tbv. dubbele regels verwijderen
  declare @maxdiepte smallint;
  declare @ParagraafDeb nchar(2);
  declare @ParagraafCred nchar(2);
  declare @SaldoWinst numeric(15,2);
  declare @SaldoWinstAnderJaar numeric(15,2);
  declare @Voorloop nchar(40);
  //tbv. omrekenverschillen
  declare @AfrondingB      numeric(15,2);
  declare @AfrondingV      numeric(15,2);
  declare @AfrondingH      numeric(15,2);
  declare @AfrondingP      numeric(15,2);
  declare @AfrondingR      numeric(15,2);
  declare @AfrondingE      numeric(15,2);
  declare @AfrondingS      numeric(15,2);
  declare @AfrondingBAnderJaar      numeric(15,2);
  declare @AfrondingVAnderJaar      numeric(15,2);
  declare @AfrondingHAnderJaar      numeric(15,2);
  declare @AfrondingPAnderJaar      numeric(15,2);
  declare @AfrondingRAnderJaar      numeric(15,2);
  declare @AfrondingEAnderJaar      numeric(15,2);
  declare @AfrondingSAnderJaar      numeric(15,2);

  declare @StreepBovenTotaalInBalansValuta smallint;
  declare @StreepBovenTotaalInTotaalValuta smallint;
  declare @GeheleRangeSelectie smallint;
  declare @NumDeci          integer;

  declare @tmpHulpVolgorde    integer;
  declare @RegelSoort         integer;
  declare @OptelStreepBoven   integer;
  declare @DubbeleStreepOnder integer;
  declare @ValNummer          integer;
  declare @tmpGid             integer;

  declare @VorigetmpHulpVolgorde    integer;
  declare @VorigeRegelSoort         integer;
  declare @VorigeOptelStreepBoven   integer;
  declare @VorigeDubbeleStreepOnder integer;
  declare @RedenSubtotaal           smallint;
  declare @IsolationLevel           smallint;

  declare @SaldoWinstTekst      long nvarchar;
  declare @SaldoVerliesTekst    long nvarchar;
  declare @RubriekTekst         long nvarchar;
  declare @ParagraafTekst       long nvarchar;
  declare @SubParagraafTekst    long nvarchar;
  declare @OmrekenVerschilTekst long nvarchar;
  declare @RekeningVanTmTekst   long nvarchar;
  declare @SubtotaalTekst       long nvarchar;

  declare local temporary table tmpBalans(
     tmpGid               integer default AutoIncrement,
     tmpHulpVolgorde      integer,
     RksInvoer            nchar(28),
     RksNaam              nchar(40) default '',
     RksNummer            nchar(10),
     KstpGid              integer,
     KstdGid              integer,
     DefaultSoort         smallint,
     ValNummer            integer,
     Valcode              nchar(3) default '',
     BeginPeriodeDebet    numeric(15,2),
     BeginPeriodeCredit   numeric(15,2),
     VorigePeriodesDebet  numeric(15,2),
     VorigePeriodesCredit numeric(15,2),
     LaatstePeriodeDebet  numeric(15,2),
     LaatstePeriodeCredit numeric(15,2),
     ProefDebet           numeric(15,2),
     ProefCredit          numeric(15,2),
     ProefSaldo           numeric(15,2),
     SaldiDebet           numeric(15,2),
     SaldiCredit          numeric(15,2),
     Verlies              numeric(15,2),
     Winst                numeric(15,2),
     EindDebet            numeric(15,2),
     EindCredit           numeric(15,2),

     BeginPeriodeDebetAnderJaar    numeric(15,2),
     BeginPeriodeCreditAnderJaar   numeric(15,2),
     VorigePeriodesDebetAnderJaar  numeric(15,2),
     VorigePeriodesCreditAnderJaar numeric(15,2),
     LaatstePeriodeDebetAnderJaar  numeric(15,2),
     LaatstePeriodeCreditAnderJaar numeric(15,2),
     ProefDebetAnderJaar           numeric(15,2),
     ProefCreditAnderJaar          numeric(15,2),
     ProefSaldoAnderJaar           numeric(15,2),
     SaldiDebetAnderJaar           numeric(15,2),
     SaldiCreditAnderJaar          numeric(15,2),
     VerliesAnderJaar              numeric(15,2),
     WinstAnderJaar                numeric(15,2),
     EindDebetAnderJaar            numeric(15,2),
     EindCreditAnderJaar           numeric(15,2),

     BalGid               integer,
     BalVerdicht          smallint default 0,
     BalDecimalen         smallint default 0,
     AfdrukZijde          smallint default 0,
     BerekendeZijde       smallint  compute (if (AfdrukZijde = 0 or (AfdrukZijde=2 and (VorigePeriodesDebet + LaatstePeriodeDebet >= VorigePeriodesCredit + LaatstePeriodeCredit))) then 0 else 1 endif),
     RegelSoort           integer,
     Sortering            nchar(39),
     OptelStreepBoven     smallint default 0,
     DubbeleStreepOnder   smallint default 0,
     RedenSubtotaal       smallint,
     primary key (tmpGid)
  ) on commit preserve rows;

  declare cursor_tmpBalansVolgorde cursor for
    select tmpGid, tmpHulpVolgorde, RegelSoort, OptelStreepBoven, DubbeleStreepOnder, ValNummer
    from tmpBalans
    order by tmpHulpVolgorde
  for update;


  declare local temporary table tmpTeVerdichten(
    RksNummer nchar(10))
  on commit preserve rows;

  Create index idx_tmpBalansSoort     on tmpBalans (regelsoort);
  Create index idx_tmpBalansSortering on tmpBalans (Sortering);
  create index idx_tmpRksNummer       on tmpBalans(RksNummer);
  create index idx_tmpBal1            on tmpBalans (RksInvoer);
  Create index idx_tmpHulpVolgorde on tmpBalans (tmpHulpVolgorde);  //Let op: ivm. bug in ASA 6 EN 7 moet deze index hier staan, NIET na een delete!!
  create index idx_tmpKstpKstd        on tmpBalans (KstpGid,KstdGid);


  set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+', @VanRks='+@VanRks+', @TotRks='+@TotRks);

  //call Trace('rapNormaleBalansMetAnderBoekjaar > @SoortBoeking='+string(@SoortBoeking)+', @OokNulSaldi='+string(@OokNulSaldi)+', @ComprimeerBalans='+string(@ComprimeerBalans)+', @DebUitsplitsen='+string(@DebUitsplitsen)+', @CredUitsplitsen='+string(@CredUitsplitsen));
  //call Trace('rapNormaleBalansMetAnderBoekjaar > @KstpUitsplitsen='+string(@KstpUitsplitsen)+', @KstdUitsplitsen='+string(@KstdUitsplitsen)+', @AantalCijfers='+string(@AantalCijfers)+', @BalansInValuta='+string(@BalansInValuta)+', @TotalenInValuta='+string(@TotalenInValuta));

  select Paragraaf into @ParagraafDeb  from tabParagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 10;
  select Paragraaf into @ParagraafCred from tabParagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 20;

  //Als we toch al minder dan 3 cijfers afdrukken zijn de deb./cred. al gecomprimeerd. Hiermee voorkomen we dat
  //de deb./cred. apart worden behandeld (met totaalstreep etc.)
  if @ComprimeerBalans = 1 and @AantalCijfers <= 2 then
    set @DebUitsplitsen  = 1;
    set @CredUitsplitsen = 1;
  end if;

  set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 1';
  //call Trace(@@ErrorTextProcedure);

  select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @BalansInValuta;

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  select * into local temporary table tabRekeningsaldo2 from tabrekeningsaldo where RekSaldoBjGid = @AnderBjGid and RekSaldoPernr <= @TotPernrAnderJaar;
  create unique index idx_RekSaldoRksGID_RekSaldoBjGID_RekSaldoPerNr_RekSaldoValNummer2 on tabRekeningSaldo2 (RekSaldoRksGID, RekSaldoBjGID, RekSaldoPerNr, RekSaldoValNummer);

  insert into tmpBalans (
              RegelSoort, Sortering, ValNummer, RksInvoer, RksNummer, KstpGid, KstdGid,
              RksNaam, DefaultSoort, AfdrukZijde,
              BeginPeriodeDebet,   BeginPeriodeCredit,
              VorigePeriodesDebet, VorigePeriodesCredit,
              LaatstePeriodeDebet, LaatstePeriodeCredit,
              ProefDebet, ProefCredit, ProefSaldo,
              SaldiDebet, SaldiCredit,
              Verlies, Winst, EindDebet, EindCredit,
              BeginPeriodeDebetAnderJaar,   BeginPeriodeCreditAnderJaar,
              VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar,
              LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
              ProefDebetAnderJaar, ProefCreditAnderJaar, ProefSaldoAnderJaar,
              SaldiDebetAnderJaar, SaldiCreditAnderJaar,
              VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar, BalVerdicht, BalDecimalen)
  select
    1,
    RksInvoer,
    @BalansInValuta, //ACW 24-01-2001: hier stond eerst RksValNummer,
    RksInvoer,
    RksNummer,
    RksKstpGid,
    RksKstdGid,
    RksNaam,
    DefaultSoort,
    AfdrukZijde,
    // Proefbalans (verdeeld naar Beginbalans, vorige periodes (incl. beginbalans) en laatste periode
    if @BalansInValuta = @@BasisValutanummer then if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif, @BalansInValuta, @BjGid, @TotPernr, 2) endif BDebet,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif, @BalansInValuta, @BjGid, @TotPernr, 2) endif BCredit,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernr >= @TotPernr then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernr >= @TotPernr then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) endif, @BalansInValuta, @BjGid, @TotPernr, 2) endif VDebet,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernr >= @TotPernr then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernr >= @TotPernr then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) endif, @BalansInValuta, @BjGid, @TotPernr, 2) endif VCredit,
    if @BalansInValuta = @@BasisValutanummer then IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0) else ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0), @BalansInValuta, @BjGid, @TotPernr, 2) endif HDebet,
    if @BalansInValuta = @@BasisValutanummer then IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0) else ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0), @BalansInValuta, @BjGid, @TotPernr, 2) endif HCredit,

    // Proefbalans totaal en saldo
    VDebet     + HDebet      ProefDebet,
    VCredit    + HCredit     ProefCredit,
    ProefDebet - ProefCredit ProefSaldo,

    // Saldibalans
    if (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefSaldo >= 0)) then ProefSaldo else 0 endif SaldiDebet,
    if (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefSaldo <  0)) then -ProefSaldo  else 0 endif SaldiCredit,

    // Resultatenrekening
    if DefaultSoort in (3,4,5)     and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefSaldo >= 0)) then  ProefSaldo else 0 endif Verlies,
    if DefaultSoort in (3,4,5)     and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefSaldo <  0)) then -ProefSaldo else 0 endif Winst,

    // Eindbalans
    if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefSaldo >= 0)) then  ProefSaldo else 0 endif EindDebet,
    if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefSaldo <  0)) then -ProefSaldo else 0 endif EindCredit,

    // AnderJaar Proefbalans (verdeeld naar Beginbalans, vorige periodes (incl. beginbalans) en laatste periode
    if @BalansInValuta = @@BasisValutanummer then if @VanPernrAnderJaar>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr = 0), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernrAnderJaar>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr = 0), 0) endif,@BalansInValuta, @BjGid, @TotPernr, 2) endif AnderBDebet,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernrAnderJaar>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr = 0), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernrAnderJaar>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr = 0), 0) endif,@BalansInValuta, @BjGid, @TotPernr, 2) endif AnderBCredit,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernrAnderJaar >= @TotPernrAnderJaar then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr between @VanPernrAnderJaar and @TotPernrAnderJaar-1), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernrAnderJaar >= @TotPernrAnderJaar then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr between @VanPernrAnderJaar and @TotPernrAnderJaar-1), 0) endif,@BalansInValuta, @BjGid, @TotPernr, 2) endif AnderVDebet,
    if @BalansInValuta = @@BasisValutanummer then if @VanPernrAnderJaar >= @TotPernrAnderJaar then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr between @VanPernrAnderJaar and @TotPernrAnderJaar-1), 0) endif else ValutaOmrekenen(@@BasisValutanummer,if @VanPernrAnderJaar >= @TotPernrAnderJaar then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr between @VanPernrAnderJaar and @TotPernrAnderJaar-1), 0) endif,@BalansInValuta, @BjGid, @TotPernr, 2) endif AnderVCredit,
    if @BalansInValuta = @@BasisValutanummer then IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr = @TotPernrAnderJaar), 0) else ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr = @TotPernrAnderJaar), 0),@BalansInValuta, @BjGid, @TotPernr, 2) endif AnderHDebet,
    if @BalansInValuta = @@BasisValutanummer then IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr = @TotPernrAnderJaar), 0) else ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo2 where RekSaldoRksGid = RksGid and RekSaldoBjGid = @AnderBjGid and RekSaldoPernr = @TotPernrAnderJaar), 0),@BalansInValuta, @BjGid, @TotPernr, 2) endif AnderHCredit,

    // AnderJaar Proefbalans totaal en saldo
    AnderVDebet     + AnderHDebet      AnderProefDebet,
    AnderVCredit    + AnderHCredit     AnderProefCredit,
    AnderProefDebet - AnderProefCredit AnderProefSaldo,

    // AnderJaar Saldibalans
    if (AfdrukZijde = 0 or (AfdrukZijde=2 and AnderProefSaldo >= 0)) then AnderProefSaldo else 0 endif AnderSaldiDebet,
    if (AfdrukZijde = 1 or (AfdrukZijde=2 and AnderProefSaldo <  0)) then -AnderProefSaldo  else 0 endif AnderSaldiCredit,

    // AnderJaar Resultatenrekening
    if DefaultSoort in (3,4,5)     and (AfdrukZijde = 0 or (AfdrukZijde=2 and AnderProefSaldo >= 0)) then  AnderProefSaldo else 0 endif AnderVerlies,
    if DefaultSoort in (3,4,5)     and (AfdrukZijde = 1 or (AfdrukZijde=2 and AnderProefSaldo <  0)) then -AnderProefSaldo else 0 endif AnderWinst,

    // AnderJaar Eindbalans
    if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 0 or (AfdrukZijde=2 and AnderProefSaldo >= 0)) then  AnderProefSaldo else 0 endif AnderEindDebet,
    if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 1 or (AfdrukZijde=2 and AnderProefSaldo <  0)) then -AnderProefSaldo else 0 endif AnderEindCredit,

    // Comprimeren van deze regel?
    if @ComprimeerBalans <> 1 then
      if DefaultSoort=6 then
        abs(@DebUitSplitsen-1)
      else
        if DefaultSoort=7 then
          abs(@CredUitSplitsen-1)
        else
          if RksKstpGid is not null then
            abs(@KstpUitSplitsen-1)
          else
            if RksKstdGid is not null then
              abs(@KstdUitSplitsen-1)
            else
              (if @ComprimeerBalans = 1 then 1 else 0 endif)
            endif
          endif
        endif
      endif
    else
      1
    endif BalVerdicht,
    // Comprimeer evt. op dit aantal cijfers
    if ((DefaultSoort=6 and @DebUitSplitsen=0)
        or (DefaultSoort=7 and @CredUitSplitsen=0))
       and @AantalCijfers > 2 then
      2
    else
      if ((RksKstpGid is not null and @KstpUitSplitsen=0)
          or (RksKstdGid is not null and @KstdUitSplitsen=0))
       and @ComprimeerBalans=1
       and @AantalCijfers > 2 then
         2
       else
         @AantalCijfers
       endif
    endif BalDecimalen
  from
    tabRekeningschema
  where
    ((@SelecteerOp = 0 and RksInvoer   between @VanRks and @TotRks)  or
     (@SelecteerOp = 1 and RksZoekcode between @VanRks and @TotRks)  or
     (@SelecteerOp = 2 and RksNaam     between @VanRks and @TotRks))
   and
     (    @OokNulSaldi=1
      or (@OokNulSaldi=2 and (   (isnull(ProefSaldo,0) <> 0)
                              or (isnull(AnderProefSaldo,0) <> 0)
                              or (RksGid in (select JrRksGid
                                             from  tabJournaalRegel
                                             where JrPerNr between @VanPerNr and @TotPerNr
                                               and (JrBjGid = @BjGid)
                                               and ((@SoortBoeking = 0 and RegelNummer is not Null) or
                                                    (@SoortBoeking = 1 and RegelNummer is  Null) or
                                                    (@SoortBoeking = 2)
                                                   )
                                             )
                                  )
                              or (RksGid in (select JrRksGid
                                             from  tabJournaalRegel
                                             where JrPerNr between @VanPerNrAnderJaar and @TotPerNrAnderJaar
                                               and (JrBjGid = @AnderBjGid)
                                               and ((@SoortBoeking = 0 and RegelNummer is not Null) or
                                                    (@SoortBoeking = 1 and RegelNummer is  Null) or
                                                    (@SoortBoeking = 2)
                                                   )
                                             )
                                  )
                             )
         )
      or  //RB 14-10-2003 : LET OP bedragen beginbalans, vorige periodes en huidige perides
          //                       APART testen anders zijn de totalen niet in evenwicht
         (@OokNulSaldi=0 and ( (isnull(BDebet,0) - isnull(BCredit,0) <> 0) or
                               (isnull(VDebet,0) - isnull(VCredit,0) <> 0) or
                               (isnull(HDebet,0) - isnull(HCredit,0) <> 0)
                             )
         )
      or
         (@OokNulSaldi=0 and ( (isnull(AnderBDebet,0) - isnull(AnderBCredit,0) <> 0) or
                               (isnull(AnderVDebet,0) - isnull(AnderVCredit,0) <> 0) or
                               (isnull(AnderHDebet,0) - isnull(AnderHCredit,0) <> 0)
                             )
         )

     );

  set temporary option isolation_level = @IsolationLevel;

  if exists(select 1 from tmpBalans) then
    set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 1b';
    //call Trace(@@ErrorTextProcedure);

    //Testen of we de gehele range hebben; zoniet, dan geen omrekenverschillen bepalen!
    set @GeheleRangeSelectie = 0;
    if not exists(select 1 from tabRekeningSchema where not
                    ((@SelecteerOp = 0 and RksInvoer between @VanRks and @TotRks) or
                     (@SelecteerOp = 1 and RksZoekCode between @VanRks and @TotRks) or
                     (@SelecteerOp = 2 and RksNaam between @VanRks and @TotRks))) then
      //Ok, alle rekeningen geselecteerd
      set @GeheleRangeSelectie = 1;
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 2';
    //call Trace(@@ErrorTextProcedure);

    if (@ComprimeerBalans in (0,1)) and (@KstpUitsplitsen = 0 or @KstdUitsplitsen = 0) then

      //Zorg er eerst voor dat alle hoofdrekeningen aanwezig zijn
      insert into tmpBalans (RegelSoort, Sortering, ValNummer, RksInvoer, RksNummer, KstpGid, KstdGid, RksNaam, DefaultSoort, AfdrukZijde, BalVerdicht, BalDecimalen)
      select 1, RksInvoer, RksValNummer, RksInvoer, RksNummer, RksKstpGid, RksKstdGid, RksNaam, DefaultSoort, AfdrukZijde, @ComprimeerBalans,
             if ((DefaultSoort=6 and @DebUitSplitsen=0) or (DefaultSoort=7 and @CredUitSplitsen=0) or (RksKstpGid is not null and @KstpUitSplitsen=0) or (RksKstdGid is not null and @KstdUitSplitsen=0)) and @ComprimeerBalans=1 and @AantalCijfers > 2 then 2 else @AantalCijfers endif
      from tabRekeningschema where RksKstpGid is null and RksKstdGid is null
           and RksInvoer in (select distinct RksNummer from tmpBalans where KstpGid is not null or KstdGid is not null)  //Geef de hoofdrekeningen terug van die rekening die een kostenplaats/drager hebben
           and RksInvoer not in (select RksInvoer from tmpBalans where KstpGid is null or KstdGid is null);           //Als de hoofdrekening alleen in de balans staat dan niet toevoegen


      set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 2a';
      //call Trace(@@ErrorTextProcedure);

      //Nu de hoofdrekening updaten a.d.h.v. de rekeningen met kostenplaatsen en/of kostendragers
      if @KstpUitsplitsen = 0 or @KstdUitsplitsen = 0 then
        //Alleen als 1 of beide inderdaadniet uitgesplitst is (dus er moet een optelling plaatsvinden)
        set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 2b';
        //call Trace(@@ErrorTextProcedure);

        if @KstpUitsplitsen = 0 then
          insert into tmpTeVerdichten(RksNummer)
          select distinct c.RksNummer from tmpBalans c where c.KstpGid is not null;
          update tmpBalans b
          set
            BeginPeriodeDebet    = isnull(BeginPeriodeDebet  ,0)   + isnull((select sum(a.BeginPeriodeDebet)     from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            BeginPeriodeCredit   = isnull(BeginPeriodeCredit ,0)   + isnull((select sum(a.BeginPeriodeCredit)    from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            VorigePeriodesDebet  = isnull(VorigePeriodesDebet  ,0) + isnull((select sum(a.VorigePeriodesDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            VorigePeriodesCredit = isnull(VorigePeriodesCredit ,0) + isnull((select sum(a.VorigePeriodesCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            LaatstePeriodeDebet  = isnull(LaatstePeriodeDebet ,0)  + isnull((select sum(a.LaatstePeriodeDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            LaatstePeriodeCredit = isnull(LaatstePeriodeCredit,0)  + isnull((select sum(a.LaatstePeriodeCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefDebet           = isnull(ProefDebet,0)            + isnull((select sum(a.ProefDebet)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefCredit          = isnull(ProefCredit,0)           + isnull((select sum(a.ProefCredit)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefSaldo           = isnull(ProefSaldo,0)            + isnull((select sum(a.ProefSaldo)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            SaldiDebet           = isnull(SaldiDebet  ,0)          + isnull((select sum(a.SaldiDebet)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            SaldiCredit          = isnull(SaldiCredit ,0)          + isnull((select sum(a.SaldiCredit)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            Verlies              = isnull(Verlies     ,0)          + isnull((select sum(a.Verlies)               from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            Winst                = isnull(Winst       ,0)          + isnull((select sum(a.Winst)                 from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            EindDebet            = isnull(EindDebet   ,0)          + isnull((select sum(a.EindDebet)             from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            EindCredit           = isnull(EindCredit  ,0)          + isnull((select sum(a.EindCredit)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            BeginPeriodeDebetAnderJaar    = isnull(BeginPeriodeDebetAnderJaar  ,0)   + isnull((select sum(a.BeginPeriodeDebetAnderJaar)     from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            BeginPeriodeCreditAnderJaar   = isnull(BeginPeriodeCreditAnderJaar ,0)   + isnull((select sum(a.BeginPeriodeCreditAnderJaar)    from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            VorigePeriodesDebetAnderJaar  = isnull(VorigePeriodesDebetAnderJaar  ,0) + isnull((select sum(a.VorigePeriodesDebetAnderJaar)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            VorigePeriodesCreditAnderJaar = isnull(VorigePeriodesCreditAnderJaar ,0) + isnull((select sum(a.VorigePeriodesCreditAnderJaar)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            LaatstePeriodeDebetAnderJaar  = isnull(LaatstePeriodeDebetAnderJaar ,0)  + isnull((select sum(a.LaatstePeriodeDebetAnderJaar)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            LaatstePeriodeCreditAnderJaar = isnull(LaatstePeriodeCreditAnderJaar,0)  + isnull((select sum(a.LaatstePeriodeCreditAnderJaar)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefDebetAnderJaar           = isnull(ProefDebetAnderJaar,0)            + isnull((select sum(a.ProefDebetAnderJaar)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefCreditAnderJaar          = isnull(ProefCreditAnderJaar,0)           + isnull((select sum(a.ProefCreditAnderJaar)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            ProefSaldoAnderJaar           = isnull(ProefSaldoAnderJaar,0)            + isnull((select sum(a.ProefSaldoAnderJaar)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            SaldiDebetAnderJaar           = isnull(SaldiDebetAnderJaar  ,0)          + isnull((select sum(a.SaldiDebetAnderJaar)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            SaldiCreditAnderJaar          = isnull(SaldiCreditAnderJaar ,0)          + isnull((select sum(a.SaldiCreditAnderJaar)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            VerliesAnderJaar              = isnull(VerliesAnderJaar     ,0)          + isnull((select sum(a.VerliesAnderJaar)               from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            WinstAnderJaar                = isnull(WinstAnderJaar       ,0)          + isnull((select sum(a.WinstAnderJaar)                 from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            EindDebetAnderJaar            = isnull(EindDebetAnderJaar   ,0)          + isnull((select sum(a.EindDebetAnderJaar)             from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0),
            EindCreditAnderJaar           = isnull(EindCreditAnderJaar  ,0)          + isnull((select sum(a.EindCreditAnderJaar)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstpGid is not null ),0)
          from   tmpBalans b inner join tmpTeVerdichten on (tmpTeVerdichten.RksNummer = b.RksNummer)
          where  KstpGid is null and KstdGid is null;
//                 and RksNummer in ( select c.RksNummer from tmpBalans c where c.KstpGid is not null); -> DIT werkt dus niet, daarom de tmpTeVerdichten
          delete tmpBalans where KstpGid is not null;
        end if;

        if @KstdUitsplitsen = 0 then
          //LET OP: iom. RB en ACW besloten om ook de kostendragers indien niet uitgesplitst direct op de kostensoort (de rekening) te zetten ipv. eerst te
          //        proberen of die op de kostenplaats kan worden gezet. (probleem: bestaat de kostenplaats wel? Zoniet, dan alsnog op de kostensoort boeken)
          //Bepaal te verdichten rekeningen (apart ivm. bug in ASA6!!!)
          delete from tmpTeVerdichten;
          insert into tmpTeVerdichten(RksNummer)
          select distinct c.RksNummer from tmpBalans c where c.KstdGid is not null;

          update tmpBalans b
          set
            BeginPeriodeDebet    = isnull(BeginPeriodeDebet  ,0)   + isnull((select sum(a.BeginPeriodeDebet)     from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            BeginPeriodeCredit   = isnull(BeginPeriodeCredit ,0)   + isnull((select sum(a.BeginPeriodeCredit)    from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            VorigePeriodesDebet  = isnull(VorigePeriodesDebet  ,0) + isnull((select sum(a.VorigePeriodesDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            VorigePeriodesCredit = isnull(VorigePeriodesCredit ,0) + isnull((select sum(a.VorigePeriodesCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            LaatstePeriodeDebet  = isnull(LaatstePeriodeDebet ,0)  + isnull((select sum(a.LaatstePeriodeDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            LaatstePeriodeCredit = isnull(LaatstePeriodeCredit,0)  + isnull((select sum(a.LaatstePeriodeCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefDebet           = isnull(ProefDebet,0)            + isnull((select sum(a.ProefDebet)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefCredit          = isnull(ProefCredit,0)           + isnull((select sum(a.ProefCredit)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefSaldo           = isnull(ProefSaldo,0)            + isnull((select sum(a.ProefSaldo)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            SaldiDebet           = isnull(SaldiDebet  ,0)          + isnull((select sum(a.SaldiDebet)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            SaldiCredit          = isnull(SaldiCredit ,0)          + isnull((select sum(a.SaldiCredit)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            Verlies              = isnull(Verlies     ,0)          + isnull((select sum(a.Verlies)               from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            Winst                = isnull(Winst       ,0)          + isnull((select sum(a.Winst)                 from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            EindDebet            = isnull(EindDebet   ,0)          + isnull((select sum(a.EindDebet)             from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            EindCredit           = isnull(EindCredit  ,0)          + isnull((select sum(a.EindCredit)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            BeginPeriodeDebetAnderJaar    = isnull(BeginPeriodeDebetAnderJaar  ,0)   + isnull((select sum(a.BeginPeriodeDebetAnderJaar)     from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            BeginPeriodeCreditAnderJaar   = isnull(BeginPeriodeCreditAnderJaar ,0)   + isnull((select sum(a.BeginPeriodeCreditAnderJaar)    from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            VorigePeriodesDebetAnderJaar  = isnull(VorigePeriodesDebetAnderJaar  ,0) + isnull((select sum(a.VorigePeriodesDebetAnderJaar)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            VorigePeriodesCreditAnderJaar = isnull(VorigePeriodesCreditAnderJaar ,0) + isnull((select sum(a.VorigePeriodesCreditAnderJaar)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            LaatstePeriodeDebetAnderJaar  = isnull(LaatstePeriodeDebetAnderJaar ,0)  + isnull((select sum(a.LaatstePeriodeDebetAnderJaar)   from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            LaatstePeriodeCreditAnderJaar = isnull(LaatstePeriodeCreditAnderJaar,0)  + isnull((select sum(a.LaatstePeriodeCreditAnderJaar)  from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefDebetAnderJaar           = isnull(ProefDebetAnderJaar,0)            + isnull((select sum(a.ProefDebetAnderJaar)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefCreditAnderJaar          = isnull(ProefCreditAnderJaar,0)           + isnull((select sum(a.ProefCreditAnderJaar)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            ProefSaldoAnderJaar           = isnull(ProefSaldoAnderJaar,0)            + isnull((select sum(a.ProefSaldoAnderJaar)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            SaldiDebetAnderJaar           = isnull(SaldiDebetAnderJaar  ,0)          + isnull((select sum(a.SaldiDebetAnderJaar)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            SaldiCreditAnderJaar          = isnull(SaldiCreditAnderJaar ,0)          + isnull((select sum(a.SaldiCreditAnderJaar)           from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            VerliesAnderJaar              = isnull(VerliesAnderJaar     ,0)          + isnull((select sum(a.VerliesAnderJaar)               from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            WinstAnderJaar                = isnull(WinstAnderJaar       ,0)          + isnull((select sum(a.WinstAnderJaar)                 from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            EindDebetAnderJaar            = isnull(EindDebetAnderJaar   ,0)          + isnull((select sum(a.EindDebetAnderJaar)             from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0),
            EindCreditAnderJaar           = isnull(EindCreditAnderJaar  ,0)          + isnull((select sum(a.EindCreditAnderJaar)            from tmpBalans a where a.RksNummer = b.RksNummer and a.KstdGid is not null ),0)
          from   tmpBalans b inner join tmpTeVerdichten on (tmpTeVerdichten.RksNummer = b.RksNummer)
          where  KstpGid is null and KstdGid is null;
//                 and RksNummer in ( select c.RksNummer from tmpBalans c where c.KstdGid is not null); -> DIT werkt dus niet, daarom de tmpTeVerdichten
          delete tmpBalans where KstdGid is not null;
        end if;

      end if;

    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 3';
    //call Trace(@@ErrorTextProcedure);

    set @Voorloop = 'ZZZZZZZZZZZZZZZZZZZZZZZZZ';

    if @ComprimeerBalans = 2 then  //Conform balans

      update tmpBalans set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(RksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' and DecimalenSubTotalen<>0;

      update tmpBalans set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  BalGid is null and DetailBlCode=0 and Paragraaf = left(RksInvoer,2) and Trim(Paragraaf)<>'' and DecimalenSubTotalen<>0;

      update tmpBalans set BalGid = BlGid, BalDecimalen = DecimalenSubTotalen
      from   tabBalansCodeDetail
      where  BalGid is null and DetailBlCode=0 and Rubriek = left(RksInvoer,1) and Paragraaf='' and DecimalenSubTotalen<>0;

      update tmpBalans set BalGid = null;

      update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  DetailBlCode=0 and Paragraaf+SubParagraaf = left(RksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' ;

      update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  BalGid is null and DetailBlCode=0 and Paragraaf = left(RksInvoer,2) and Trim(Paragraaf)<>'';

      update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
      from   tabBalansCodeDetail
      where  BalGid is null and DetailBlCode=0 and Rubriek = left(RksInvoer,1) and Paragraaf='';

      //RVL Bug 8750 : Als er voor een bepaalde rekening geen rubriek aanwezig was in de balanscodetabel en er hingen aan die rekeningen
      //               ook nog kostenplaatsen, dan werden de kostenplaatsen niet afgedrukt.
      //               Maar de bedragen die op die rekeningen stonden werden niet opgeteld bij de 'hoofdrekening'.
      //               Bij de totalen per paragraaf werden de bedragen wel meegenomen. Nu worden de kostenplaatsenrekeningen
      //               wel afgedrukt door BalVerdicht op 0 komt te zetten
      update tmpBalans set BalVerdicht = 0 where BalGid is null;
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 4';
    //call Trace(@@ErrorTextProcedure);

    //Subtotalen maken volgens aantal decimalen
    set @RubriekTekst      = _U('Rubriek %1!');
    set @ParagraafTekst    = _U('Paragraaf %1!');
    set @SubParagraafTekst = _U('Subparagraaf %1!');

    select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;
    set @Teller = 5; //5 = subpar, 1=rubriek, 0=totaal generaal
    while @Teller > 0 loop

      insert into tmpBalans
        (RegelSoort, Sortering, RksInvoer, RksNaam, ValNummer, ValCode,
         BeginPeriodeDebet, BeginPeriodeCredit,
         VorigePeriodesDebet, VorigePeriodesCredit,
         LaatstePeriodeDebet, LaatstePeriodeCredit,
         ProefDebet, ProefCredit, ProefSaldo,
         SaldiDebet, SaldiCredit,
         Verlies, Winst,
         EindDebet, EindCredit,
         BeginPeriodeDebetAnderJaar, BeginPeriodeCreditAnderJaar,
         VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar,
         LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
         ProefDebetAnderJaar, ProefCreditAnderJaar, ProefSaldoAnderJaar,
         SaldiDebetAnderJaar, SaldiCreditAnderJaar,
         VerliesAnderJaar, WinstAnderJaar,
         EindDebetAnderJaar, EindCreditAnderJaar,
         BalVerdicht, BalDecimalen)
      select
        15-@Teller,
        substr(RksInvoer, 1, @Teller)+'z' Sortering, //(sub)paragraaf ONDER de rekeningen!!!
        substr(RksInvoer, 1, @Teller)+' :' HulpRksInvoer,
        IsNull(OmsBalansCodeDetails, if @Teller = 1 then _P(@RubriekTekst, substr(RksInvoer, 1, 1)) else if @Teller = 2 then _U(@ParagraafTekst, substr(RksInvoer, 1, 2)) else _U(@SubParagraafTekst, substr(RksInvoer, 3, @Teller-2)) endif endif) BalOms,
        @BalansInValuta,
        @BalansValCode,
        sum(if RegelSoort = 1 then BeginPeriodeDebet    else 0 endif),
        sum(if RegelSoort = 1 then BeginPeriodeCredit   else 0 endif),
        sum(if RegelSoort = 1 then VorigePeriodesDebet  else 0 endif),
        sum(if RegelSoort = 1 then VorigePeriodesCredit else 0 endif),
        sum(if RegelSoort = 1 then LaatstePeriodeDebet  else 0 endif),
        sum(if RegelSoort = 1 then LaatstePeriodeCredit else 0 endif),
        sum(if RegelSoort = 1 then ProefDebet           else 0 endif),
        sum(if RegelSoort = 1 then ProefCredit          else 0 endif),
        sum(if RegelSoort = 1 then ProefSaldo           else 0 endif),
        sum(if RegelSoort = 1 then SaldiDebet           else 0 endif),
        sum(if RegelSoort = 1 then SaldiCredit          else 0 endif),
        sum(if RegelSoort = 1 then Verlies              else 0 endif),
        sum(if RegelSoort = 1 then Winst                else 0 endif),
        sum(if RegelSoort = 1 then EindDebet            else 0 endif),
        sum(if RegelSoort = 1 then EindCredit           else 0 endif),
        sum(if RegelSoort = 1 then BeginPeriodeDebetAnderJaar    else 0 endif),
        sum(if RegelSoort = 1 then BeginPeriodeCreditAnderJaar   else 0 endif),
        sum(if RegelSoort = 1 then VorigePeriodesDebetAnderJaar  else 0 endif),
        sum(if RegelSoort = 1 then VorigePeriodesCreditAnderJaar else 0 endif),
        sum(if RegelSoort = 1 then LaatstePeriodeDebetAnderJaar  else 0 endif),
        sum(if RegelSoort = 1 then LaatstePeriodeCreditAnderJaar else 0 endif),
        sum(if RegelSoort = 1 then ProefDebetAnderJaar           else 0 endif),
        sum(if RegelSoort = 1 then ProefCreditAnderJaar          else 0 endif),
        sum(if RegelSoort = 1 then ProefSaldoAnderJaar           else 0 endif),
        sum(if RegelSoort = 1 then SaldiDebetAnderJaar           else 0 endif),
        sum(if RegelSoort = 1 then SaldiCreditAnderJaar          else 0 endif),
        sum(if RegelSoort = 1 then VerliesAnderJaar              else 0 endif),
        sum(if RegelSoort = 1 then WinstAnderJaar                else 0 endif),
        sum(if RegelSoort = 1 then EindDebetAnderJaar            else 0 endif),
        sum(if RegelSoort = 1 then EindCreditAnderJaar           else 0 endif),
        IsNull(BalansVerdicht, max(BalVerdicht)),
        IsNull(DecimalenSubTotalen, max(BalDecimalen))
      from     tmpBalans left outer join tabBalanscodeDetail on (DetailBlCode = 0 and RubParSub = substr(RksInvoer, 1, @Teller) )
      where    length(RksInvoer)>=@Teller and RksInvoer in (select RksInvoer from tmpBalans where (RegelSoort=1 and BalDecimalen >= @Teller))
      group by HulpRksInvoer, Sortering, BalOms, BalansVerdicht, DecimalenSubTotalen;

      set @Teller = @Teller - 1;

    end loop;

    if (@DebUitsplitsen = 0 and @ComprimeerBalans = 0) then
      if exists (select 1 from tmpBalans where DefaultSoort = 6) then
        set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Debiteuren groeperen en als paragraaf er tussen zetten';
        //call Trace(@@ErrorTextProcedure);
        //Let op: als rekening tussenvoegen omdat de paragrafen zelf niet worden afgedrukt!!
        insert into tmpBalans
          (RegelSoort, Sortering, ValNummer, RksInvoer, RksNummer,
           RksNaam, DefaultSoort, AfdrukZijde,
           BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
           ProefDebet, ProefCredit,
           SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit,
           BeginPeriodeDebetAnderJaar, BeginPeriodeCreditAnderJaar, VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar, LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
           ProefDebetAnderJaar, ProefCreditAnderJaar,
           SaldiDebetAnderJaar, SaldiCreditAnderJaar, VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar,
           BalVerdicht, BalDecimalen)
        select
          1, @ParagraafDeb Paragraaf, @BalansInValuta,
          Paragraaf+' :', Paragraaf, (select OmsBalansCodeDetails from tabparagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 10), 6, min(AfdrukZijde),
          sum(BeginPeriodeDebet), sum(BeginPeriodeCredit), sum(VorigePeriodesDebet), sum(VorigePeriodesCredit), sum(LaatstePeriodeDebet),
          sum(LaatstePeriodeCredit), sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst),
          sum(EindDebet), sum(EindCredit),
          sum(BeginPeriodeDebetAnderJaar), sum(BeginPeriodeCreditAnderJaar), sum(VorigePeriodesDebetAnderJaar), sum(VorigePeriodesCreditAnderJaar), sum(LaatstePeriodeDebetAnderJaar),
          sum(LaatstePeriodeCreditAnderJaar), sum(ProefDebetAnderJaar), sum(ProefCreditAnderJaar), sum(SaldiDebetAnderJaar), sum(SaldiCreditAnderJaar), sum(VerliesAnderJaar), sum(WinstAnderJaar),
          sum(EindDebetAnderJaar), sum(EindCreditAnderJaar),
          if @AantalCijfers < 2 then 0 else 1 endif, min(BalDecimalen)
        from   tmpBalans where DefaultSoort = 6 and Regelsoort = 1;
        delete tmpBalans where DefaultSoort = 6 and Regelsoort = 1 and RksInvoer <> @ParagraafDeb + ' :'
      end if;
    end if;

    if (@CredUitsplitsen = 0 and @ComprimeerBalans = 0 ) then
      if exists (select 1 from tmpBalans where DefaultSoort = 7) then
        set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Crediteuren groeperen en als paragraaf er tussen zetten';
        //call Trace(@@ErrorTextProcedure);
        //Let op: als rekening tussenvoegen omdat de paragrafen zelf niet worden afgedrukt!!
        insert into tmpBalans
          (RegelSoort, Sortering, ValNummer, RksInvoer, RksNummer,
           RksNaam, DefaultSoort, AfdrukZijde,
           BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
           ProefDebet, ProefCredit,
           SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit,
           BeginPeriodeDebetAnderJaar, BeginPeriodeCreditAnderJaar, VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar, LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
           ProefDebetAnderJaar, ProefCreditAnderJaar,
           SaldiDebetAnderJaar, SaldiCreditAnderJaar, VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar,
           BalVerdicht, BalDecimalen)
        select
          1, @ParagraafCred Paragraaf, @BalansInValuta,
          Paragraaf+' :', Paragraaf, (select OmsBalansCodeDetails from tabparagraaf inner join tabBalanscodeDetail on (BlGid = ParBlGid) where ParSoort = 20), 6, min(AfdrukZijde),
          sum(BeginPeriodeDebet), sum(BeginPeriodeCredit), sum(VorigePeriodesDebet), sum(VorigePeriodesCredit), sum(LaatstePeriodeDebet),
          sum(LaatstePeriodeCredit), sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst),
          sum(EindDebet), sum(EindCredit),
          sum(BeginPeriodeDebetAnderJaar), sum(BeginPeriodeCreditAnderJaar), sum(VorigePeriodesDebetAnderJaar), sum(VorigePeriodesCreditAnderJaar), sum(LaatstePeriodeDebetAnderJaar),
          sum(LaatstePeriodeCreditAnderJaar), sum(ProefDebetAnderJaar), sum(ProefCreditAnderJaar), sum(SaldiDebetAnderJaar), sum(SaldiCreditAnderJaar), sum(VerliesAnderJaar), sum(WinstAnderJaar),
          sum(EindDebetAnderJaar), sum(EindCreditAnderJaar),
          if @AantalCijfers < 2 then 0 else 1 endif, min(BalDecimalen)
        from   tmpBalans where DefaultSoort = 7 and Regelsoort = 1;
        delete tmpBalans where DefaultSoort = 7 and Regelsoort = 1 and RksInvoer <> @ParagraafCred + ' :'
      end if;
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Verdichten';
    //call Trace(@@ErrorTextProcedure);
    delete tmpBalans where BalVerdicht = 1 and RegelSoort = 1;

    set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 6';
    //call Trace(@@ErrorTextProcedure);

    //Subtotalen omrekenen naar juiste valuta
    select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;
    if @BalansInValuta <> @TotalenInValuta then
      select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @TotalenInValuta;
      insert into
        tmpBalans
        (RegelSoort, Sortering, RksInvoer, RksNaam, ValNummer, ValCode, BalVerdicht, BalDecimalen,
         BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
         ProefDebet, ProefCredit, ProefSaldo,
         SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit,
         BeginPeriodeDebetAnderJaar, BeginPeriodeCreditAnderJaar, VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar, LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
         ProefDebetAnderJaar, ProefCreditAnderJaar, ProefSaldoAnderJaar,
         SaldiDebetAnderJaar, SaldiCreditAnderJaar, VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar)
      select
        6+RegelSoort,
        Sortering+'z',
        RksInvoer,
        RksNaam,
        @TotalenInValuta,
        @TotaalValCode,
        BalVerdicht,
        BalDecimalen,
        ValutaOmrekenen(@BalansInValuta, BeginPeriodeDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, BeginPeriodeCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, VorigePeriodesDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, VorigePeriodesCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, LaatstePeriodeDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, LaatstePeriodeCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, ProefDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, ProefCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, ProefSaldo, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, SaldiDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, SaldiCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, Verlies, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, Winst, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, EindDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, EindCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),

        ValutaOmrekenen(@BalansInValuta, BeginPeriodeDebetAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, BeginPeriodeCreditAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, VorigePeriodesDebetAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, VorigePeriodesCreditAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, LaatstePeriodeDebetAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, LaatstePeriodeCreditAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, ProefDebetAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, ProefCreditAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, ProefSaldoAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, SaldiDebetAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, SaldiCreditAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, VerliesAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, WinstAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, EindDebetAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, EindCreditAnderJaar, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci)

      from
        tmpBalans tmp where RegelSoort between 10 and 15;
    end if;

    //Opnieuw nummers uitdelen om dubbele strepen te zetten
    update tmpBalans
    set    tmpHulpVolgorde = number(*)
    order by Sortering;

    set @VorigetmpHulpVolgorde    = 0;
    set @VorigeRegelSoort         = 99;
    set @VorigeOptelStreepBoven   = 0;
    set @VorigeDubbeleStreepOnder = 0;

    open cursor_tmpBalansVolgorde;
    LoopVolgorde:
    loop
      Fetch next cursor_tmpBalansVolgorde into @tmpGid, @tmpHulpVolgorde, @RegelSoort, @OptelStreepBoven, @DubbeleStreepOnder, @ValNummer;
      if sqlstate = '02000' then
        leave LoopVolgorde;
      end if;
      //Als de vorige regel een kleinere regelsoort heeft *of* een enkele/dubbele streep, dan ook een dubbele streep zitten
      if @VorigeRegelSoort < @RegelSoort and (@ValNummer = @TotalenInValuta or @BalansInValuta = @TotalenInValuta) then
        set @DubbeleStreepOnder = 1;
      end if;
      if @VorigeRegelSoort < @RegelSoort and @VorigeDubbeleStreepOnder = 0 and @VorigeRegelSoort <> 99 and @ValNummer = @BalansInValuta then
        set @OptelStreepBoven = 1;
      end if;
      if @VorigeOptelStreepBoven + @VorigeDubbeleStreepOnder <> 0 and @VorigeRegelSoort <= @RegelSoort then
        set @DubbeleStreepOnder = 1;
      end if;

      if @OptelStreepBoven + @DubbeleStreepOnder <> 0 then
        update tmpBalans
        set    OptelStreepBoven = @OptelStreepBoven,
               DubbeleStreepOnder = @DubbeleStreepOnder
        where tmpGid = @tmpGid;
      end if;
      set @VorigetmpHulpVolgorde    = @tmpHulpVolgorde;
      set @VorigeRegelSoort         = @RegelSoort;
      set @VorigeOptelStreepBoven   = @OptelStreepBoven;
      set @VorigeDubbeleStreepOnder = @DubbeleStreepOnder;
    end loop LoopVolgorde;
    close cursor_tmpBalansVolgorde;

    // De laatste gewone regel moet altijd een dubbele streep hebben
    if @VorigeDubbeleStreepOnder = 0 then
      // Dus als die het nog niet had, dan toevoegen!
      update tmpBalans
      set    DubbeleStreepOnder = 1
      where tmpHulpVolgorde = (select max(a.tmpHulpVolgorde) from tmpBalans a);
    end if;


    //Kolommenbalans, Saldo winst/verlies bepalen voor de kolommenbalans
    set @SaldoWinstTekst   = _U('Saldo winst');
    set @SaldoVerliesTekst = _U('Saldo verlies');

    select sum(Winst - Verlies), sum(WinstAnderJaar - VerliesAnderJaar) into @SaldoWinst, @SaldoWinstAnderJaar from tmpBalans where regelsoort = 14;
    insert into tmpBalans(RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                          Verlies, Winst, EindDebet, EindCredit,
                          VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar)
    values( 35 + if isnull(@SaldoWinst,0) < 0 then 1 else 0 endif, @Voorloop+'14F',
            if isnull(@SaldoWinst,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
            @BalansInValuta, @BalansValCode,
            if @SaldoWinst >= 0 then     @SaldoWinst endif,  if @SaldoWinst < 0 then abs(@SaldoWinst) endif,
            if @SaldoWinst <= 0 then abs(@SaldoWinst) endif, if @SaldoWinst > 0 then     @SaldoWinst  endif,
            if @SaldoWinstAnderJaar >= 0 then     @SaldoWinstAnderJaar endif,  if @SaldoWinstAnderJaar < 0 then abs(@SaldoWinstAnderJaar) endif,
            if @SaldoWinstAnderJaar <= 0 then abs(@SaldoWinstAnderJaar) endif, if @SaldoWinstAnderJaar > 0 then     @SaldoWinstAnderJaar  endif);
    if @BalansInValuta <> @TotalenInValuta then
      //Ook in andere valuta saldo winst/verlies bepalen
      select sum(Winst - Verlies), sum(WinstAnderJaar - VerliesAnderJaar) into @SaldoWinst, @SaldoWinstAnderJaar from tmpBalans where regelsoort = 20;
      insert into tmpBalans(RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                            Verlies, Winst, EindDebet, EindCredit,
                            VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar)
      values( 37 + if isnull(@SaldoWinst,0) < 0 then 1 else 0 endif, @Voorloop+'20F',
              if isnull(@SaldoWinst,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
              @TotalenInValuta, @TotaalValCode,
              if @SaldoWinst >= 0 then     @SaldoWinst endif,  if @SaldoWinst < 0 then abs(@SaldoWinst) endif,
              if @SaldoWinst <= 0 then abs(@SaldoWinst) endif, if @SaldoWinst > 0 then     @SaldoWinst  endif,
              if @SaldoWinstAnderJaar >= 0 then     @SaldoWinstAnderJaar endif,  if @SaldoWinstAnderJaar < 0 then abs(@SaldoWinstAnderJaar) endif,
              if @SaldoWinstAnderJaar <= 0 then abs(@SaldoWinstAnderJaar) endif, if @SaldoWinstAnderJaar > 0 then     @SaldoWinstAnderJaar  endif);
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Stap 12';
    //call Trace(@@ErrorTextProcedure);

    //Bepaal omrekenverschillen en subtotalen agv. afdrukken in andere valuta
    set @OmrekenVerschilTekst = _U('(Omrekenverschil)');
    set @SubTotaalTekst = _U('Subtotaal');

    set @RedenSubtotaal = 0; // 1: in balansvaluta een omrekening, 2= in andere val. een omrekening, 3=beide
    set @Teller = 1; //1=balansvaluta, 2=andere valuta
    while @Teller <= 2 loop
      if @GeheleRangeSelectie = 1 then
        select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = (if @teller = 1 then @BalansInValuta else @TotalenInValuta endif);

        set @AfrondingB = 0;
        set @AfrondingV = 0;
        set @AfrondingH = 0;
        set @AfrondingP = 0;
        set @AfrondingR = 0;
        set @AfrondingS = 0;
        set @AfrondingE = 0;
        set @AfrondingBAnderJaar = 0;
        set @AfrondingVAnderJaar = 0;
        set @AfrondingHAnderJaar = 0;
        set @AfrondingPAnderJaar = 0;
        set @AfrondingRAnderJaar = 0;
        set @AfrondingSAnderJaar = 0;
        set @AfrondingEAnderJaar = 0;
        select sum(round((isnull(BeginPeriodeDebet,0)-isnull(BeginPeriodeCredit,0)), @numDeci)),
               sum(round(VorigePeriodesDebet, @numDeci))  - sum(round(VorigePeriodesCredit, @numDeci)),
               sum(round(LaatstePeriodeDebet, @numDeci)) - sum(round(LaatstePeriodeCredit, @numDeci)),
               sum(round(Verlies, @numDeci))     - sum(round(Winst, @numDeci)),
               sum(round(ProefDebet, @numDeci)) - sum(round(ProefCredit, @numDeci)),
               sum(round(SaldiDebet, @numDeci)) - sum(round(SaldiCredit, @numDeci)),
               sum(round(EindDebet, @numDeci)) - sum(round(EindCredit, @numDeci)),
               sum(round((isnull(BeginPeriodeDebetAnderJaar,0)-isnull(BeginPeriodeCreditAnderJaar,0)), @numDeci)),
               sum(round(VorigePeriodesDebetAnderJaar, @numDeci))  - sum(round(VorigePeriodesCreditAnderJaar, @numDeci)),
               sum(round(LaatstePeriodeDebetAnderJaar, @numDeci)) - sum(round(LaatstePeriodeCreditAnderJaar, @numDeci)),
               sum(round(VerliesAnderJaar, @numDeci))     - sum(round(WinstAnderJaar, @numDeci)),
               sum(round(ProefDebetAnderJaar, @numDeci)) - sum(round(ProefCreditAnderJaar, @numDeci)),
               sum(round(SaldiDebetAnderJaar, @numDeci)) - sum(round(SaldiCreditAnderJaar, @numDeci)),
               sum(round(EindDebetAnderJaar, @numDeci)) - sum(round(EindCreditAnderJaar, @numDeci))
        into   @AfrondingB, @AfrondingV, @AfrondingH, @AfrondingR, @AfrondingP, @AfrondingS, @AfrondingE,
                @AfrondingBAnderJaar, @AfrondingVAnderJaar, @AfrondingHAnderJaar, @AfrondingRAnderJaar, @AfrondingPAnderJaar, @AfrondingSAnderJaar, @AfrondingEAnderJaar
        from   tmpBalans
        where  (@teller = 1 and regelsoort in (14, 35, 36)) or
               (@teller = 2 and regelsoort in (20, 37, 38));
        set @AfrondingE = isnull(@AfrondingE,0) + isnull(@AfrondingR,0);
        set @AfrondingEAnderJaar = isnull(@AfrondingEAnderJaar,0) + isnull(@AfrondingRAnderJaar,0);

        set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > @AfrondingB='+string(@AfrondingB)+', @AfrondingV='+string(@AfrondingV)+', @AfrondingH='+string(@AfrondingH)+', @AfrondingR='+string(@AfrondingR)+', @AfrondingS='+string(@AfrondingS)+', @AfrondingE='+string(@AfrondingE);
        //call Trace(@@ErrorTextProcedure);

        if isnull(@afrondingB,0) <> 0 or isnull(@afrondingV,0) <> 0 or isnull(@afrondingH,0) <> 0 or isnull(@AfrondingP,0) <> 0 or isnull(@AfrondingS,0) <> 0 or isnull(@AfrondingE,0) <> 0 then
          set @RedenSubtotaal = @RedenSubtotaal + @teller;
          if @teller = 1 then
            set @StreepBovenTotaalInBalansValuta = 1;
          else
            set @StreepBovenTotaalInTotaalValuta = 1;
          end if;

          insert into tmpBalans(
            RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
            BeginPeriodeDebet, BeginPeriodeCredit,
            VorigePeriodesDebet, VorigePeriodesCredit,
            LaatstePeriodeDebet, LaatstePeriodeCredit,
            ProefDebet, ProefCredit, ProefSaldo,
            SaldiDebet, SaldiCredit, EindDebet, EindCredit,
            BeginPeriodeDebetAnderJaar, BeginPeriodeCreditAnderJaar,
            VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar,
            LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
            ProefDebetAnderJaar, ProefCreditAnderJaar, ProefSaldoAnderJaar,
            SaldiDebetAnderJaar, SaldiCreditAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar)
          values( if @teller = 1 then 39 else 40 endif, @Voorloop+if @teller = 1 then '14G' else '20G' endif,
                  @OmrekenVerschilTekst,
                  if @teller = 1 then @BalansInValuta else @TotalenInValuta endif,
                  if @teller = 1 then @BalansValCode else @TotaalValCode endif,
                  if @AfrondingB < 0 then abs(@AfrondingB) endif, if @AfrondingB > 0 then @AfrondingB endif,
                  if @AfrondingV < 0 then abs(@AfrondingV) endif, if @AfrondingV > 0 then @AfrondingV endif,
                  if @AfrondingH < 0 then abs(@AfrondingH) endif, if @AfrondingH > 0 then @AfrondingH endif,
                  if @AfrondingP < 0 then abs(@AfrondingP) endif, if @AfrondingP > 0 then @AfrondingP endif, @AfrondingP,
                  if @AfrondingS < 0 then abs(@AfrondingS) endif, if @AfrondingS > 0 then @AfrondingS endif,
                  if @AfrondingE < 0 then abs(@AfrondingE) endif, if @AfrondingE > 0 then @AfrondingE endif,
                  if @AfrondingBAnderJaar < 0 then abs(@AfrondingBAnderJaar) endif, if @AfrondingBAnderJaar > 0 then @AfrondingBAnderJaar endif,
                  if @AfrondingVAnderJaar < 0 then abs(@AfrondingVAnderJaar) endif, if @AfrondingVAnderJaar > 0 then @AfrondingVAnderJaar endif,
                  if @AfrondingHAnderJaar < 0 then abs(@AfrondingHAnderJaar) endif, if @AfrondingHAnderJaar > 0 then @AfrondingHAnderJaar endif,
                  if @AfrondingPAnderJaar < 0 then abs(@AfrondingPAnderJaar) endif, if @AfrondingPAnderJaar > 0 then @AfrondingPAnderJaar endif, @AfrondingPAnderJaar,
                  if @AfrondingSAnderJaar < 0 then abs(@AfrondingSAnderJaar) endif, if @AfrondingSAnderJaar > 0 then @AfrondingSAnderJaar endif,
                  if @AfrondingEAnderJaar < 0 then abs(@AfrondingEAnderJaar) endif, if @AfrondingEAnderJaar > 0 then @AfrondingEAnderJaar endif);
        end if;
      end if;

      //Altijd subtotaal erbij (kolommenbalans of we hebben een omreken-afronding)
      insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                             BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
                             ProefDebet, ProefCredit, ProefSaldo, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit,
                             BeginPeriodeDebetAnderJaar, BeginPeriodeCreditAnderJaar, VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar, LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
                             ProefDebetAnderJaar, ProefCreditAnderJaar, ProefSaldoAnderJaar, SaldiDebetAnderJaar, SaldiCreditAnderJaar, VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar,
                             RedenSubtotaal)
      select   RegelSoort+10, @Voorloop+string(RegelSoort)+'E', @SubTotaalTekst,
               if RegelSoort = 14 then @BalansInValuta else @TotalenInValuta endif,
               if RegelSoort = 14 then @BalansValCode else @TotaalValCode endif,
               round(sum(BeginPeriodeDebet), @numDeci), round(sum(BeginPeriodeCredit), @numDeci), round(sum(VorigePeriodesDebet), @numDeci),
               round(sum(VorigePeriodesCredit), @numDeci), round(sum(LaatstePeriodeDebet), @numDeci), round(sum(LaatstePeriodeCredit), @numDeci),
               round(sum(ProefDebet), @numDeci), round(sum(ProefCredit), @numDeci), round(sum(ProefSaldo), @numDeci),
               round(sum(SaldiDebet), @numDeci), round(sum(SaldiCredit), @numDeci), round(sum(Verlies), @numDeci),
               round(sum(Winst), @numDeci), round(sum(EindDebet), @numDeci), round(sum(EindCredit), @numDeci),

               round(sum(BeginPeriodeDebetAnderJaar), @numDeci), round(sum(BeginPeriodeCreditAnderJaar), @numDeci), round(sum(VorigePeriodesDebetAnderJaar), @numDeci),
               round(sum(VorigePeriodesCreditAnderJaar), @numDeci), round(sum(LaatstePeriodeDebetAnderJaar), @numDeci), round(sum(LaatstePeriodeCreditAnderJaar), @numDeci),
               round(sum(ProefDebetAnderJaar), @numDeci), round(sum(ProefCreditAnderJaar), @numDeci), round(sum(ProefSaldoAnderJaar), @numDeci),
               round(sum(SaldiDebetAnderJaar), @numDeci), round(sum(SaldiCreditAnderJaar), @numDeci), round(sum(VerliesAnderJaar), @numDeci),
               round(sum(WinstAnderJaar), @numDeci), round(sum(EindDebetAnderJaar), @numDeci), round(sum(EindCreditAnderJaar), @numDeci),
               if @RedenSubtotaal in (1,3) and RegelSoort =  14 or
                  @RedenSubtotaal in (2,3) and RegelSoort <> 14 then
                 1 // Reden: omrekenverschil
               else
                 0 // reden: saldo winst/verlies
               endif
      from     tmpBalans
      where    (@teller = 1 and RegelSoort = 14) or
               (@teller = 2 and RegelSoort = 20)
      group by RegelSoort;

      set @Teller = @Teller + 1; //Let op: NIET optimaliseren (door direct op 3 te zetten) ivm. subtotaal!!
    end loop;

    set @RekeningVanTmTekst = _U('%1! t/m %2!');

    if @BalansInValuta <> @TotalenInValuta then
      //Totaal generaal in andere valuta
      insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                             BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
                             ProefDebet, ProefCredit, ProefSaldo,SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit,
                             BeginPeriodeDebetAnderJaar, BeginPeriodeCreditAnderJaar, VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar, LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
                             ProefDebetAnderJaar, ProefCreditAnderJaar, ProefSaldoAnderJaar, SaldiDebetAnderJaar, SaldiCreditAnderJaar, VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar,
                             OptelStreepBoven)
      select   99, @Voorloop+'20Z', _P(@RekeningVanTmTekst, @VanRks, @TotRks),
               @TotalenInValuta,
               @TotaalValCode,
               sum(BeginPeriodeDebet), sum(BeginPeriodeCredit), sum(VorigePeriodesDebet), sum(VorigePeriodesCredit), sum(LaatstePeriodeDebet), sum(LaatstePeriodeCredit),
               sum(ProefDebet), sum(ProefCredit), sum(ProefSaldo), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit),
               sum(BeginPeriodeDebetAnderJaar), sum(BeginPeriodeCreditAnderJaar), sum(VorigePeriodesDebetAnderJaar), sum(VorigePeriodesCreditAnderJaar), sum(LaatstePeriodeDebetAnderJaar), sum(LaatstePeriodeCreditAnderJaar),
               sum(ProefDebetAnderJaar), sum(ProefCreditAnderJaar), sum(ProefSaldoAnderJaar), sum(SaldiDebetAnderJaar), sum(SaldiCreditAnderJaar), sum(VerliesAnderJaar), sum(WinstAnderJaar), sum(EindDebetAnderJaar), sum(EindCreditAnderJaar),
               0 // nooit een optelstreep! (wordt in layout opgelost)
      from     tmpBalans
      where    RegelSoort in (20, 37, 38, 40);
    end if;

    set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar > Totaal generaal';
    //call Trace(@@ErrorTextProcedure);
    insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                           BeginPeriodeDebet, BeginPeriodeCredit, VorigePeriodesDebet, VorigePeriodesCredit, LaatstePeriodeDebet, LaatstePeriodeCredit,
                           ProefDebet, ProefCredit, ProefSaldo, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit,
                           BeginPeriodeDebetAnderJaar, BeginPeriodeCreditAnderJaar, VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar, LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar,
                           ProefDebetAnderJaar, ProefCreditAnderJaar, ProefSaldoAnderJaar, SaldiDebetAnderJaar, SaldiCreditAnderJaar, VerliesAnderJaar, WinstAnderJaar, EindDebetAnderJaar, EindCreditAnderJaar,
                           OptelStreepBoven)
    select   98 , @Voorloop+'14Z', _P(@RekeningVanTmTekst, @VanRks, @TotRks),
             @BalansInValuta,
             @BalansValCode,
             sum(BeginPeriodeDebet), sum(BeginPeriodeCredit), sum(VorigePeriodesDebet), sum(VorigePeriodesCredit), sum(LaatstePeriodeDebet), sum(LaatstePeriodeCredit),
             sum(ProefDebet), sum(ProefCredit), sum(ProefSaldo), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit),
             sum(BeginPeriodeDebetAnderJaar), sum(BeginPeriodeCreditAnderJaar), sum(VorigePeriodesDebetAnderJaar), sum(VorigePeriodesCreditAnderJaar), sum(LaatstePeriodeDebetAnderJaar), sum(LaatstePeriodeCreditAnderJaar),
             sum(ProefDebetAnderJaar), sum(ProefCreditAnderJaar), sum(ProefSaldoAnderJaar), sum(SaldiDebetAnderJaar), sum(SaldiCreditAnderJaar), sum(VerliesAnderJaar), sum(WinstAnderJaar), sum(EindDebetAnderJaar), sum(EindCreditAnderJaar),
             0 // nooit een optelstreep! (wordt in layout opgelost)
    from     tmpBalans
    where    RegelSoort in (14, 35, 36, 39);
  end if; //alleen als er wel regels in staan, anders alles overgeslagen!

  set @@ErrorTextProcedure = 'rapNormaleBalansMetAnderBoekjaar';
  //call TraceEind(@@ErrorTextProcedure);
  select   RksInvoer, RksNummer, RksNaam, ValNummer, Valcode,
           BeginPeriodeDebet BeginBalansDebet, BeginPeriodeCredit BeginBalansCredit, (isnull(BeginPeriodeDebet,0)-isnull(BeginPeriodeCredit,0)) BeginBalansSaldo,
           VorigePeriodesDebet, VorigePeriodesCredit, VorigePeriodesDebet - VorigePeriodesCredit VorigePeriodesSaldo,
           LaatstePeriodeDebet, LaatstePeriodeCredit, LaatstePeriodeDebet - LaatstePeriodeCredit LaatstePeriodeSaldo,
           ProefDebet,          ProefCredit,          ProefSaldo,
           SaldiDebet,          SaldiCredit,          SaldiDebet - SaldiCredit SaldiSaldo,
           Verlies,             Winst,                Verlies - Winst ResultaatSaldo,
           EindDebet,           EindCredit,           EindDebet - EindCredit EindSaldo,

           BeginPeriodeDebetAnderJaar BeginBalansDebetAnderJaar, BeginPeriodeCreditAnderJaar BeginBalansCreditAnderJaar, (isnull(BeginPeriodeDebetAnderJaar,0)-isnull(BeginPeriodeCreditAnderJaar,0)) BeginBalansSaldoAnderJaar,
           VorigePeriodesDebetAnderJaar, VorigePeriodesCreditAnderJaar, VorigePeriodesDebetAnderJaar - VorigePeriodesCreditAnderJaar VorigePeriodesSaldoAnderJaar,
           LaatstePeriodeDebetAnderJaar, LaatstePeriodeCreditAnderJaar, LaatstePeriodeDebetAnderJaar - LaatstePeriodeCreditAnderJaar LaatstePeriodeSaldoAnderJaar,
           ProefDebetAnderJaar,          ProefCreditAnderJaar,          ProefSaldoAnderJaar,
           SaldiDebetAnderJaar,          SaldiCreditAnderJaar,          SaldiDebetAnderJaar - SaldiCreditAnderJaar SaldiSaldoAnderJaar,
           VerliesAnderJaar,             WinstAnderJaar,                VerliesAnderJaar - WinstAnderJaar ResultaatSaldoAnderJaar,
           EindDebetAnderJaar,           EindCreditAnderJaar,           EindDebetAnderJaar - EindCreditAnderJaar EindSaldoAnderJaar,

           BalVerdicht, BalDecimalen, RegelSoort,
           OptelStreepBoven, DubbeleStreepOnder, RedenSubtotaal
 from      tmpBalans
 order by  Sortering;

end;

//call RapNormaleBalansMetAnderJaar(100002, 0, 12, 0, '1010', '9910' , 0, 1, 0, 0, 0, 1, 10, 1, 0, 0, 100001, 0, 12)
//call RapNormaleBalansMetAnderJaar(1, 0, 12, 0, '', '99999999' , 0, 1, 0, 0, 0, 0, 0, 1, 0, 0, 100001, 0, 12)


create or replace procedure rapNormaleBalansPerKstd(
 in  @BjGid            Integer,
 in  @VanPernr         smallint,
 in  @TotPernr         smallint,
 in  @SelecteerOp      smallint, //1=kstdnummer, 2=kstdzoekcode
 in  @VanKstd          nchar(40), //van nummer/zoekcode
 in  @TotKstd          nchar(40), //t/m nummer/zoekcode
 in  @SoortBoeking     smallint, //0=definitief, 1=voorlopig, 2=beide
 in  @OokNulSaldi      smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
 in  @ComprimeerBalans smallint, //0=nee, 1=ja, 2=conform balans
 in  @KstdUitsplitsen  smallint, //0=nee, 1=ja. Werkt alleen indien comprimeren <> 'ja' en er niet per kostendrager een nieuwe balans wordt opgesteld.
 in  @BalansPerKstd    smallint, //0=nee, 1=ja. Indien ja, dan wordt er als het ware per kostendrager een nieuwe balans opgesteld (op nieuwe pagina).
 in  @AantalCijfers    smallint, //Aantal cijfers waarop getotaliseerd moet worden 1-5 (werkt niet bij comprimeren conform balans)
 in  @BalansInValuta   integer,  //Valutanummer waarin balans moet worden afgedrukt
 in  @TotalenInValuta  integer)  //Valutanummer voor subtotalen

result (
  RksInvoer nchar(28),
  RksZoekCode nchar(10),
  RksNaam nchar(40),
  KstdCode nchar(8),
  ValNummer integer,
  Valcode nchar(3),
  BeginDebet numeric(15,2), BeginCredit numeric(15,2),
  VorigDebet numeric(15,2), VorigCredit numeric(15,2),
  HuidigDebet numeric(15,2), HuidigCredit numeric(15,2),
  ProefDebet numeric(15,2), ProefCredit numeric(15,2),
  SaldiDebet numeric(15,2), SaldiCredit numeric(15,2),
  Verlies numeric(15,2), Winst numeric(15,2),
  EindDebet numeric(15,2), EindCredit numeric(15,2),
  RegelSoort integer,
  OptelStreepBoven smallint,
  DubbeleStreepOnder smallint
)

begin
/*      Regelsoort:     Bevat:
        1               Rekeningen
        (2              tijdelijke hulpregelsoort, in geval kostendragers niet uitsplitsen)

        10              Subtotalen subparagraven xxx in basisvaluta
        11              Subtotalen subparagraven xx in basisvaluta
        12              Subtotalen subparagraven x in basisvaluta
        13              Subtotalen paragraven in basisvaluta
        14              Subtotalen rubrieken in basisvaluta

        16              Subtotalen subparagraven xxx in extra valuta
        17              Subtotalen subparagraven xx in extra valuta
        18              Subtotalen subparagraven x in extra valuta
        19              Subtotalen paragraven in extra valuta
        20              Subtotalen rubrieken in extra valuta

        24              Totaal in basis valuta
        30              Totaal in extra valuta

        35              Saldo winst in basis valuta
        36              Saldo verlies in basis valuta
        37              Saldo winst in extra valuta
        38              Saldo verlies in extra valuta

        98              Totaal generaal in basis valuta
        99              Totaal generaal in extra valuta
*/

  declare @Teller          smallint;
  declare @NumDeci         integer;
  declare @BalansValCode   nchar(3);
  declare @TotaalValCode   nchar(3);
  declare @StopWaarde      integer;
  declare @MaxHulpVolgorde integer;
  declare @StreepBovenTotaalInBalansValuta smallint;
  declare @StreepBovenTotaalInTotaalValuta smallint;
  declare @IsolationLevel           smallint;

  declare @SaldoWinstTekst        long nvarchar;
  declare @SaldoVerliesTekst      long nvarchar;
  declare @KostenDragerTekst      long nvarchar;
  declare @KostenDragerVanTmTekst long nvarchar;
  declare @SubtotaalTekst         long nvarchar;
  declare @RubriekTekst           long nvarchar;
  declare @ParagraafTekst         long nvarchar;
  declare @SubParagraafTekst      long nvarchar;

  declare local temporary table tmpBalans(
     tmpGid             integer default AutoIncrement,
     tmpHulpVolgorde    integer,
     RksInvoer          nchar(28),
     RksZoekCode        nchar(10),
     RksNaam            nchar(40) default '',
     RksNummer          nchar(10),
     KstdCode           nchar(8),
     DefaultSoort       smallint,
     ValNummer          integer,
     Valcode            nchar(3) default '',
     BeginDebet         double,
     BeginCredit        double,
     VorigDebet         double,
     VorigCredit        double,
     HuidigDebet        double,
     HuidigCredit       double,
     ProefDebet         double,
     ProefCredit        double,
     SaldiDebet         double,
     SaldiCredit        double,
     Verlies            double,
     Winst              double,
     EindDebet          double,
     EindCredit         double,
     BalGid             integer,
     BalVerdicht        smallint default 0,
     BalDecimalen       smallint default @AantalCijfers,
     AfdrukZijde        smallint default 0, // Geen verplicht veld
     RegelSoort         integer,
     Sortering          nchar(39),
     OptelStreepBoven   smallint default 0,
     DubbeleStreepOnder smallint default 0,
     WinstVerlies       double, // Uit optimalisatie overwegingen extra opgenomen veld
     primary key (tmpGid)
  ) on commit preserve rows;

  create index idx_tmpBalansSoort     on tmpBalans (regelsoort);
  create index idx_tmpBalansSortering on tmpBalans (Sortering);
  create index idx_tmpBal1 on tmpBalans (RksInvoer);

  set @@ErrorTextProcedure = 'rapNormaleBalansPerKstp > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BjGid = ' + string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+', @VanKstd='+string(@VanKstd)+', @TotKstd='+string(@TotKstd));
  //call Trace('..., @SoortBoeking='+string(@SoortBoeking)+', @OokNulSaldi='+string(@OokNulSaldi)+', @ComprimeerBalans='+string(@ComprimeerBalans)+', @KstdUitsplitsen='+string(@KstdUitsplitsen)+', @BalansPerKstd='+string(@BalansPerKstd)+', @AantalCijfers='+string(@AantalCijfers)+', @BalansInValuta='+string(@BalansInValuta)+', @TotalenInValuta='+string(@TotalenInValuta)+')');
  //call TraceEind('rapNormaleBalansPerKstd');

  //call Trace('Stap 1a Rekeninggegevens');
  select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @BalansInValuta;

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  insert into tmpBalans (
              RegelSoort, KstdCode, Sortering, ValNummer, RksInvoer, RksZoekCode, RksNaam, RksNummer,
              DefaultSoort, AfdrukZijde,
              BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
              ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit)
  select
    1,
    if @BalansPerKstd = 1 then (select KstdCode from tabKostendrager where KstdGid = RksKstdGid) endif HulpKstdCode,
    if @ComprimeerBalans = 0 then left(HulpKstdCode + '        ', 8) + left(substr(RksNummer, 1, @AantalCijfers) + 'ppppp', 5) + ' ' + left(RksInvoer + '                            ', 28) endif Sortering, // Sortering kostendragers, balanscode, rksinvoer (voor evt kostenplaatsen)
    @BalansInValuta, //ACW 24-01-2001: hier stond eerst RksValNummer,
    RksInvoer,
    RksZoekCode,
    RksNaam,
    RksNummer,
    DefaultSoort,
    AfdrukZijde,
    ValutaOmrekenen(@@BasisValutanummer,if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif,@BalansInValuta, @BjGid, @TotPernr, 2) BDebet,
    ValutaOmrekenen(@@BasisValutanummer,if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif,@BalansInValuta, @BjGid, @TotPernr, 2) BCredit,
    ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0),@BalansInValuta, @BjGid, @TotPernr, 2) VDebet,
    ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0),@BalansInValuta, @BjGid, @TotPernr, 2) VCredit,
    ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0),@BalansInValuta, @BjGid, @TotPernr, 2) HDebet,
    ValutaOmrekenen(@@BasisValutanummer,IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0),@BalansInValuta, @BjGid, @TotPernr, 2) HCredit,
    VDebet  + HDebet ProefDebet,
    VCredit + HCredit ProefCredit,
    if (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif SaldiDebet,
    if (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif SaldiCredit,
    if DefaultSoort in (3,4,5) and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif Verlies,
    if DefaultSoort in (3,4,5) and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif Winst,
    if DefaultSoort in (0,1,2) and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif EindDebet,
    if DefaultSoort in (0,1,2) and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif EindCredit
  from
    tabRekeningschema
  where
    (RksKstdGid in (select KstdGid from tabKostendrager where (KstdCode     between @VanKstd and @TotKstd and @SelecteerOp = 1) or
                                                              (KstdZoekcode between @VanKstd and @TotKstd and @SelecteerOp = 2)
                   )
    ) and
    (@OokNulSaldi=1 or
    (@OokNulSaldi=2 and (RksGid in //(select RekSaldoRksGid from tabRekeningsaldo where RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr))) or
                                   (select JrRksGid from tabJournaalRegel inner join tabJournaalpost on (JpGid = JrJpGid) inner join tabBoekingsgang on (BoekgangGid = JpBoekgangGid) where JrPerNr between @VanPerNr and @TotPerNr and JrBjGid = @BjGid and
                                   ((@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                                    (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                                    (@SoortBoeking = 2))))) or
    //0-saldi niet afdrukken, dus begin+vorige+huidige optellen en die vergelijken, ook beginbalans etc. apart testen!!
    (@OokNulSaldi=0 and (isnull(ProefDebet,0)-isnull(ProefCredit,0) <> 0 or
                         isnull(BDebet,0) - isnull(BCredit,0) <> 0 or
                         isnull(VDebet,0) - isnull(VCredit,0) <> 0 or
                         isnull(SaldiDebet,0) - isnull(SaldiCredit,0) <> 0 or
                         isnull(HDebet,0) - isnull(HCredit,0) <> 0))
    );

  set temporary option isolation_level = @IsolationLevel;

  if exists(select 1 from tmpBalans) then

    //call Trace('Stap 1b Kostendragers niet uitsplitsen');
    //Kostendragers niet uitsplitsen heeft alleen zin indien de checkbox balans per kostendrager uit staat
    //Zorg er eerst voor dat alle hoofdrekeningen aanwezig zijn
    if @KstdUitsplitsen = 0 and @BalansPerKstd = 0 then
      insert into tmpBalans (
                  RegelSoort, Sortering, ValNummer, RksInvoer, RksZoekCode, RksNaam, RksNummer,
                  DefaultSoort, AfdrukZijde)
      select
        2,
        if @ComprimeerBalans = 0 then '        ' + left(substr(RksNummer, 1, @AantalCijfers) + 'ppppp', 5) + ' ' + left(RksNummer + '          ', 10) endif Sortering, // Sortering kostendragers, balanscode, rksnummer
        @BalansInValuta,
        RksInvoer,
        RksZoekCode,
        RksNaam,
        RksNummer,
        DefaultSoort,
        AfdrukZijde
      from
        tabRekeningschema
      where
        RksNummer in (select distinct RksNummer from tmpBalans) and RksKstpgid is null and RksKstdGid is null;

      //Bedragen geboekt op verschillende kostendragers van een rekening totaliseren
      update tmpBalans b
      set
        BeginDebet   = isnull((select sum(a.BeginDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        BeginCredit  = isnull((select sum(a.BeginCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        VorigDebet   = isnull((select sum(a.VorigDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        VorigCredit  = isnull((select sum(a.VorigCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        HuidigDebet  = isnull((select sum(a.HuidigDebet)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        HuidigCredit = isnull((select sum(a.HuidigCredit) from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        ProefDebet   = isnull((select sum(a.ProefDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        ProefCredit  = isnull((select sum(a.ProefCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        SaldiDebet   = isnull((select sum(a.SaldiDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        SaldiCredit  = isnull((select sum(a.SaldiCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        Verlies      = isnull((select sum(a.Verlies)      from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        Winst        = isnull((select sum(a.Winst)        from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        EindDebet    = isnull((select sum(a.EindDebet)    from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        EindCredit   = isnull((select sum(a.EindCredit)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0)
      where RegelSoort = 2;
      //Rekeningen met kostendragres verwijderen
      delete tmpBalans where RegelSoort = 1;
      // Hulpregelsoort 2 weer veranderen in regelsoort 1
      update tmpBalans
      set
        RegelSoort = 1
      where
        RegelSoort = 2;
    end if;


    //call Trace('Stap 2 Updaten ingeval @ComprimeerBalans = 2');
    if @ComprimeerBalans = 2 then  //Conform balans
      // Verdichten en Subtotalen
      // Records behorende bij paragraaf en subparagraaf
      update
        tmpBalans
      set
        BalGid = BlGid,
        BalVerdicht = isnull(BalansVerdicht, 0),
        BalDecimalen =  if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif,
        Sortering = left(KstdCode + '        ', 8) + left(substr(RksNummer, 1, if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif) + 'ppppp', 5) + ' ' + left(RksInvoer + '                            ', 28) // Sortering kostendragers, balanscode, rksinvoer (voor evt kostenplaatsen)
      from tmpBalans left outer join tabBalansCodeDetail on (DetailBlCode=0 and Paragraaf+SubParagraaf = left(RksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'' );

      // Overgebleven records behorende bij paragraaf
      update tmpBalans
      set
        BalGid = BlGid,
        BalVerdicht = isnull(BalansVerdicht, 0),
        BalDecimalen = if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif,
        Sortering = left(KstdCode + '        ', 8) + left(substr(RksNummer, 1, if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif) + 'ppppp', 5) + ' ' + left(RksInvoer + '                            ', 28) // Sortering kostendragers, balanscode, rksinvoer (voor evt kostenplaatsen)
      from tmpBalans left outer join tabBalansCodeDetail on (DetailBlCode=0 and Paragraaf = left(RksInvoer,2) and Trim(Paragraaf)<>'')
      //ACW 23-08-2011 Bug #33901: Deze controles niet in de FROM (ivm. left-outer-join) maar hier in de where!
      where BalGid is null and BalVerdicht = 0;
      // Overgebleven records behorende bij rubriek
      update tmpBalans
      set
        BalGid = BlGid,
        BalVerdicht = isnull(BalansVerdicht, 0),
        BalDecimalen = if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif,
        Sortering = left(KstdCode + '        ', 8) + left(substr(RksNummer, 1, if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif) + 'ppppp', 5) + ' ' + left(RksInvoer + '                            ', 28) // Sortering kostendragers, balanscode, rksinvoer (voor evt kostenplaatsen)
      from tmpBalans left outer join tabBalansCodeDetail on (DetailBlCode=0 and Rubriek = left(RksInvoer,1) and Paragraaf='')
      //ACW 23-08-2011 Bug #33901: Deze controles niet in de FROM (ivm. left-outer-join) maar hier in de where!
      where BalGid is null and BalVerdicht = 0;
    end if;

   //select * from tmpBalans;

    select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;

    //call Trace('Stap 3 Subtotalen per balanscode');
    set @RubriekTekst      = _U('Rubriek %1!');
    set @ParagraafTekst    = _U('Paragraaf %1!');
    set @SubParagraafTekst = _U('Subparagraaf %1!');

    set @StopWaarde = (select max(BalDecimalen) from tmpBalans);
    set @Teller = 1; // Hoogste niveau starten = rubrieken
    while @Teller <= @StopWaarde loop
      insert into tmpBalans
        (RegelSoort, RksNaam, RksInvoer, KstdCode, Sortering, ValNummer, ValCode,
         BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
         ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst,
         EindDebet, EindCredit, DubbeleStreepOnder)
      select
        15 - @Teller,
        IsNull((select OmsBalansCodeDetails from tabBalansCodeDetail where (DetailBlCode = 0 and RubParSub = substr(RksNummer, 1, @Teller))), if @Teller = 1 then _P(@RubriekTekst, substr(RksNummer, 1, 1)) else if @Teller = 2 then _P(@ParagraafTekst, substr(RksNummer, 1, 2)) else _P(@SubParagraafTekst, substr(RksNummer, 3, @Teller - 2)) endif endif) BalOms,
        substr(RksNummer, 1, @Teller) + ' :' HulpRksInvoer,
        KstdCode,
        left(KstdCode + '        ', 8) + left(substr(RksNummer, 1, @Teller) + 'ppppp', 5) + 'q' Sortering, //(sub)paragraaf ONDER de rekeningen
        @BalansInValuta,
        @BalansValCode,
        sum(BeginDebet),
        sum(BeginCredit),
        sum(VorigDebet),
        sum(VorigCredit),
        sum(HuidigDebet),
        sum(HuidigCredit),
        sum(ProefDebet),
        sum(ProefCredit),
        sum(SaldiDebet),
        sum(SaldiCredit),
        sum(Verlies),
        sum(Winst),
        sum(EindDebet),
        sum(EindCredit),
        0
      from     tmpBalans left outer join tabBalanscodeDetail on (DetailBlCode = 0 and RubParSub = substr(RksNummer, 1, BalDecimalen) )
      where    length(RksNummer)>=@Teller and RksNummer in (select RksNummer from tmpBalans where (RegelSoort=1 and BalDecimalen >= @Teller))
      group by BalOms, HulpRksInvoer, KstdCode, Sortering;

      set @Teller = @Teller + 1;
    end loop;

    //call Trace('Stap 4 Verdichten');
    delete tmpBalans where (BalVerdicht = 1 and RegelSoort = 1);

    //call Trace('Stap 5 Subtotalen per balanscode in andere valuta');
    select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;

    if @BalansInValuta <> @TotalenInValuta then
      select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @TotalenInValuta;
      insert into
        tmpBalans
        (RegelSoort, KstdCode, Sortering, RksInvoer, RksNaam, ValNummer, ValCode,
         BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
         ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst,
         EindDebet, EindCredit, DubbeleStreepOnder)
      select
        6 + RegelSoort,
        KstdCode,
        Sortering + 'v',
        RksInvoer,
        RksNaam,
        @TotalenInValuta,
        @TotaalValCode,
        ValutaOmrekenen(@BalansInValuta, BeginDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, BeginCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, VorigDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, VorigCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, HuidigDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, HuidigCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, ProefDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, ProefCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, SaldiDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, SaldiCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, Verlies, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, Winst, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, EindDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, EindCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        1
      from
        tmpBalans tmp where RegelSoort between 9 and 14;
    end if;

    //call Trace('Stap 6 RegelSoort 1 verwijderen agv comprimeren = 1');
    if @ComprimeerBalans = 1 then
      delete tmpBalans where RegelSoort = 1
    end if;

    //call Trace('Stap 7 Nummers uitdelen om dubbele strepen te zetten');
    update tmpBalans
    set    tmpHulpVolgorde = number(*)
    order by Sortering;
    create index idx_tmpHulpVolgorde on tmpBalans (tmpHulpVolgorde);

    //call Trace('Stap 8a Plaatsen van dubbele strepen voor oplopend regelniveau');
    update tmpBalans buiten
    set buiten.DubbeleStreepOnder = 1
    where (buiten.RegelSoort not in (1, 14, 20) ) and ( 1 = (select first 1 from tmpBalans binnen where binnen.tmpHulpVolgorde = buiten.tmpHulpVolgorde - 1 and binnen.RegelSoort < buiten.RegelSoort));

    //call Trace('Stap 8b Plaatsen van dubbele strepen voor rubriekniveau');
    update tmpBalans buiten
    set buiten.DubbeleStreepOnder = 1
    where (buiten.RegelSoort in (14,20)) and (buiten.DubbeleStreepOnder = 0);

    //select RksInvoer,RegelSoort, DubbeleStreepOnder,OptelStreepBoven from tmpBalans order by Sortering;
    //call Trace('Stap 9 Plaatsen van enkele strepen');
    update tmpBalans buiten
    set buiten.OptelStreepBoven = 1
    where (buiten.DubbeleStreepOnder = 1) and ( 1 = (select first 1 from tmpBalans binnen where binnen.tmpHulpVolgorde = buiten.tmpHulpVolgorde - 1 and binnen.RegelSoort < buiten.RegelSoort and binnen.RegelSoort + 6 <> buiten.RegelSoort and binnen.DubbeleStreepOnder = 0));

    //call Trace('Stap 10 verwijderen van dubbele strepen behorende bij totalen in valuta van belans in geval van extra valuta');
    if @BalansInValuta <> @TotalenInValuta then
      update tmpBalans buiten
      set buiten.DubbeleStreepOnder = 0
      where (buiten.DubbeleStreepOnder = 1) and ( 1 = (select first 1 from tmpBalans binnen where binnen.tmpHulpVolgorde = buiten.tmpHulpVolgorde + 1 and binnen.RegelSoort = buiten.RegelSoort + 6));
    end if;

    //call Trace('Stap 11 Saldo winst/verlies voor de kolommenbalans bepalen');
    set @SaldoWinstTekst   = _U('Saldo winst');
    set @SaldoVerliesTekst = _U('Saldo verlies');

    set @KostenDragerTekst      = _U('kostendrager %1!');
    set @KostenDragerVanTmTekst = _U('van kostendrager %1! t/m %2!');

    insert into tmpBalans(WinstVerlies, RegelSoort, KstdCode, Sortering, RksNaam, ValNummer, ValCode,
                          Verlies, Winst, EindDebet, EindCredit)
    select
      sum(Winst - Verlies) WinstVerlies,
      35 + if isnull(WinstVerlies,0) < 0 then 1 else 0 endif,
      KstdCode,
      left(KstdCode + '        ', 8) + 'r2',
      if isnull(WinstVerlies,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
      @BalansInValuta, @BalansValCode,
      if WinstVerlies >= 0 then     WinstVerlies endif,  if WinstVerlies < 0 then abs(WinstVerlies) endif,
      if WinstVerlies <= 0 then abs(WinstVerlies) endif, if WinstVerlies > 0 then     WinstVerlies  endif
    from
      tmpBalans
    where
      RegelSoort = 14
    group by
      KstdCode;

    if @BalansInValuta <> @TotalenInValuta then
      insert into tmpBalans(WinstVerlies, RegelSoort, KstdCode, Sortering, RksNaam, ValNummer, ValCode,
                            Verlies, Winst, EindDebet, EindCredit)
      select
        //Ook in andere valuta saldo winst/verlies bepalen
        sum(Winst - Verlies) WinstVerlies,
        37 + if isnull(WinstVerlies,0) < 0 then 1 else 0 endif,
        KstdCode,
        left(KstdCode + '        ', 8) + 'v2',
        if isnull(WinstVerlies,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
        @TotalenInValuta, @TotaalValCode,
        if WinstVerlies >= 0 then     WinstVerlies endif,  if WinstVerlies < 0 then abs(WinstVerlies) endif,
        if WinstVerlies <= 0 then abs(WinstVerlies) endif, if WinstVerlies > 0 then     WinstVerlies  endif
      from
        tmpBalans
      where
        RegelSoort = 20
      group by
        KstdCode;
    end if;

    //call Trace('Stap 12 Kolommenbalans dus subtotaal erbij');
    set @SubtotaalTekst = _U('Subtotaal');

    set @Teller = 1; //1=balansvaluta, 2=andere valuta
    while @Teller <= 2 loop
      select if DecimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = (if @teller = 1 then @BalansInValuta else @TotalenInValuta endif);
      insert into tmpBalans (RegelSoort, KstdCode, Sortering, RksNaam, ValNummer, ValCode,
                             BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
                             ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit)
      select
        RegelSoort+10,
        KstdCode,
        left(KstdCode + '        ', 8) + (if @Teller = 1 then 'r1' else 'v1' endif),
        @SubtotaalTekst,
        if RegelSoort = 14 then @BalansInValuta else @TotalenInValuta endif,
        if RegelSoort = 14 then @BalansValCode else @TotaalValCode endif,
        round(sum(BeginDebet), @numDeci), round(sum(BeginCredit), @numDeci), round(sum(VorigDebet), @numDeci),
        round(sum(VorigCredit), @numDeci), round(sum(HuidigDebet), @numDeci), round(sum(HuidigCredit), @numDeci),
        round(sum(ProefDebet), @numDeci), round(sum(ProefCredit), @numDeci),
        round(sum(SaldiDebet), @numDeci), round(sum(SaldiCredit), @numDeci), round(sum(Verlies), @numDeci),
        round(sum(Winst), @numDeci), round(sum(EindDebet), @numDeci), round(sum(EindCredit), @numDeci)
      from
        tmpBalans
      where
        (@teller = 1 and RegelSoort = 14) or
        (@teller = 2 and RegelSoort = 20)
      group by
        RegelSoort, KstdCode;

      set @Teller = @Teller + 1; //Let op: NIET optimaliseren (door direct op 3 te zetten) ivm. subtotaal!!
    end loop;

    //call Trace('Stap 13 Totaal generaal');
    insert into tmpBalans (RegelSoort, KstdCode, Sortering, RksNaam, ValNummer, ValCode,
                           BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
                           ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, DubbeleStreepOnder)
    select
      98,
      KstdCode,
      left(KstdCode + '        ', 8) + 'r3',
      if @BalansPerKstd = 1 then _P(@KostenDragerTekst, KstdCode) else _P(@KostenDragerVanTmTekst, @VanKstd, @TotKstd) endif,
      @BalansInValuta,
      @BalansValCode,
      sum(BeginDebet), sum(BeginCredit), sum(VorigDebet), sum(VorigCredit), sum(HuidigDebet), sum(HuidigCredit),
      sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit),
      0
    from
      tmpBalans
    where
      RegelSoort in (24, 35, 36)
    group by
      KstdCode;

    if @BalansInValuta <> @TotalenInValuta then
      //Totaal generaal in andere valuta
      insert into tmpBalans (RegelSoort, KstdCode, Sortering, RksNaam, ValNummer, ValCode,
                             BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
                             ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, DubbeleStreepOnder)
      select
        99,
        KstdCode,
        left(KstdCode + '        ', 8) + 'v3',
        if @BalansPerKstd = 1 then _P(@KostenDragerTekst, KstdCode) else _P(@KostenDragerVanTmTekst, @VanKstd, @TotKstd) endif,
        @TotalenInValuta,
        @TotaalValCode,
        sum(BeginDebet), sum(BeginCredit), sum(VorigDebet), sum(VorigCredit), sum(HuidigDebet), sum(HuidigCredit),
        sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit),
        0
      from
        tmpBalans
      where
        RegelSoort in (30, 37, 38)
      group by
        KstdCode;
    end if;

  end if; //alleen als er wel regels in staan, anders alles overgeslagen!

  set @@ErrorTextProcedure = 'rapNormaleBalansPerKstd';
  //call TraceEind(@@ErrorTextProcedure);

  select    RksInvoer, RksZoekCode, RksNaam, KstdCode, ValNummer, Valcode, BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
            ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, RegelSoort,
            OptelStreepBoven, DubbeleStreepOnder
  from      tmpBalans
  order by  Sortering;

end;

//call rapNormaleBalansPerKstd(1, 0, 12, 1, '1', '2', 2, 0, 0, 1, 1, 2, 0, 0)


create or replace procedure rapNormaleBalansPerKstp(
  in @BjGid            Integer,
  in @VanPernr         smallint,
  in @TotPernr         smallint,
  in @SelecteerOp      smallint, //1=kstpnummer, 2=kstpzoekcode
  in @VanKstp          nchar(40), //van nummer/zoekcode
  in @TotKstp          nchar(40), //t/m nummer/zoekcode
  in @SoortBoeking     smallint, //0=definitief, 1=voorlopig, 2=beide
  in @OokNulSaldi      smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
  in @ComprimeerBalans smallint, //0=nee, 1=ja, 2=conform balans
  in @KstpUitsplitsen  smallint, //0=nee, 1=ja. Werkt alleen indien comprimeren <> 'ja' en er niet per kostenplaats een nieuwe balans wordt opgesteld.
  in @BalansPerKstp    smallint, //0=nee, 1=ja. Indien ja, dan wordt er als het ware per kostenplaats een nieuwe balans opgesteld (op nieuwe pagina).
  in @AantalCijfers    smallint, //Aantal cijfers waarop getotaliseerd moet worden 1-5 (werkt niet bij comprimeren conform balans)
  in @BalansInValuta   integer,  //Valutanummer waarin balans moet worden afgedrukt
  in @TotalenInValuta  integer)  //Valutanummer voor subtotalen

result (
  RksInvoer nchar(28),
  RksZoekCode nchar(10),
  RksNaam nchar(40),
  KstpCode nchar(8),
  ValNummer integer,
  Valcode nchar(3),
  BeginDebet numeric(15,2), BeginCredit numeric(15,2),
  VorigDebet numeric(15,2), VorigCredit numeric(15,2),
  HuidigDebet numeric(15,2), HuidigCredit numeric(15,2),
  ProefDebet numeric(15,2), ProefCredit numeric(15,2),
  SaldiDebet numeric(15,2), SaldiCredit numeric(15,2),
  Verlies numeric(15,2), Winst numeric(15,2),
  EindDebet numeric(15,2), EindCredit numeric(15,2),
  RegelSoort integer,
  OptelStreepBoven smallint,
  DubbeleStreepOnder smallint
)

begin
/*      Regelsoort:     Bevat:
        1               Rekeningen
        (2              tijdelijke hulpregelsoort, ingeval kostenplaatsen niet uitsplitsen)

        10              Subtotalen subparagraven xxx in basisvaluta
        11              Subtotalen subparagraven xx in basisvaluta
        12              Subtotalen subparagraven x in basisvaluta
        13              Subtotalen paragraven in basisvaluta
        14              Subtotalen rubrieken in basisvaluta

        16              Subtotalen subparagraven xxx in extra valuta
        17              Subtotalen subparagraven xx in extra valuta
        18              Subtotalen subparagraven x in extra valuta
        19              Subtotalen paragraven in extra valuta
        20              Subtotalen rubrieken in extra valuta

        24              Totaal in basis valuta
        30              Totaal in extra valuta

        35              Saldo winst in basis valuta
        36              Saldo verlies in basis valuta
        37              Saldo winst in extra valuta
        38              Saldo verlies in extra valuta

        98              Totaal generaal in basis valuta
        99              Totaal generaal in extra valuta
*/

  declare @Teller          smallint;
  declare @NumDeci         integer;
  declare @BalansValCode   nchar(3);
  declare @TotaalValCode   nchar(3);
  declare @StopWaarde      integer;
  declare @MaxHulpVolgorde integer;
  declare @StreepBovenTotaalInBalansValuta smallint;
  declare @StreepBovenTotaalInTotaalValuta smallint;
  declare @IsolationLevel           smallint;

  declare @SaldoWinstTekst        long nvarchar;
  declare @SaldoVerliesTekst      long nvarchar;
  declare @KostenplaatsTekst      long nvarchar;
  declare @KostenplaatsVanTMTekst long nvarchar;
  declare @SubtotaalTekst         long nvarchar;
  declare @RubriekTekst           long nvarchar;
  declare @ParagraafTekst         long nvarchar;
  declare @SubParagraafTekst      long nvarchar;

  declare local temporary table tmpBalans(
     tmpGid             integer default AutoIncrement,
     tmpHulpVolgorde    integer,
     RksInvoer          nchar(28),
     RksZoekCode        nchar(10),
     RksNaam            nchar(40) default '',
     RksNummer          nchar(10),
     KstpCode           nchar(8),
     DefaultSoort       smallint,
     ValNummer          integer,
     Valcode            nchar(3) default '',
     BeginDebet         double,
     BeginCredit        double,
     VorigDebet         double,
     VorigCredit        double,
     HuidigDebet        double,
     HuidigCredit       double,
     ProefDebet         double,
     ProefCredit        double,
     SaldiDebet         double,
     SaldiCredit        double,
     Verlies            double,
     Winst              double,
     EindDebet          double,
     EindCredit         double,
     BalGid             integer,
     BalVerdicht        smallint default 0,
     BalDecimalen       smallint default @AantalCijfers,
     AfdrukZijde        smallint default 0, // Geen verplicht veld
     RegelSoort         integer,
     Sortering          nchar(39),
     OptelStreepBoven   smallint default 0,
     DubbeleStreepOnder smallint default 0,
     WinstVerlies       double, // Uit optimalisatie overwegingen extra opgenomen veld
     primary key (tmpGid)
  ) on commit preserve rows;

  create index idx_tmpBalansSoort     on tmpBalans (regelsoort);
  create index idx_tmpBalansSortering on tmpBalans (Sortering);
  create index idx_tmpBal1 on tmpBalans (RksInvoer);

  set @@ErrorTextProcedure = 'rapNormaleBalansPerKstp > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BjGid = ' + string(@BjGid) + ', @VanPernr = ' + string(@VanPernr) + ', @TotPernr = ' + string(@TotPernr) + ', @SelecteerOp = ' + string(@SelecteerOp)+', @VanKstp='+string(@VanKstp)+', @TotKstp='+string(@TotKstp));
  //call Trace('..., @SoortBoeking='+string(@SoortBoeking)+', @OokNulSaldi='+string(@OokNulSaldi)+', @ComprimeerBalans='+string(@ComprimeerBalans)+', @KstpUitsplitsen='+string(@KstpUitsplitsen)+', @BalansPerKstp='+string(@BalansPerKstp)+', @AantalCijfers='+string(@AantalCijfers)+', @BalansInValuta='+string(@BalansInValuta)+', @TotalenInValuta='+string(@TotalenInValuta)+')');
  //call TraceEind('rapNormaleBalansPerKstp');

  //call Trace('Stap 1a Rekeninggegevens');
  select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @BalansInValuta;

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  insert into tmpBalans (
              RegelSoort, KstpCode, Sortering, ValNummer, RksInvoer, RksZoekCode, RksNaam, RksNummer,
              DefaultSoort, AfdrukZijde,
              BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
              ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit)
  select
    1,
    if @BalansPerKstp = 1 then (select KstpCode from tabKostenplaats where KstpGid = RksKstpGid) endif HulpKstpCode,
    if @ComprimeerBalans = 0 then left(HulpKstpCode + '        ', 8) + left(substr(RksNummer, 1, @AantalCijfers) + 'ppppp', 5) + ' ' + left(RksInvoer + '                            ', 28) endif Sortering, // Sortering kostenplaats, balanscode, rksinvoer (voor evt kostendragers)
    @BalansInValuta, //ACW 24-01-2001: hier stond eerst RksValNummer,
    RksInvoer,
    RksZoekCode,
    RksNaam,
    RksNummer,
    DefaultSoort,
    AfdrukZijde,
    ValutaOmrekenen(@@BasisValutanummer,if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif,@BalansInValuta, @BjGid, @TotPernr, 2) BDebet,
    ValutaOmrekenen(@@BasisValutanummer,if @VanPernr>0 then 0 else IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) endif ,@BalansInValuta, @BjGid, @TotPernr, 2) BCredit,
    ValutaOmrekenen(@@BasisValutanummer,isNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) ,@BalansInValuta, @BjGid, @TotPernr, 2) VDebet,
    ValutaOmrekenen(@@BasisValutanummer,isNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) ,@BalansInValuta, @BjGid, @TotPernr, 2) VCredit,
    ValutaOmrekenen(@@BasisValutanummer,isNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0) ,@BalansInValuta, @BjGid, @TotPernr, 2) HDebet,
    ValutaOmrekenen(@@BasisValutanummer,isNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0) ,@BalansInValuta, @BjGid, @TotPernr, 2) HCredit,
    VDebet  + HDebet ProefDebet,
    VCredit + HCredit ProefCredit,
    if (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif SaldiDebet,
    if (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif SaldiCredit,
    if DefaultSoort in (3,4,5) and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif Verlies,
    if DefaultSoort in (3,4,5) and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif Winst,
    if DefaultSoort in (0,1,2) and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif EindDebet,
    if DefaultSoort in (0,1,2) and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif EindCredit
  from
    tabRekeningschema
  where
    (RksKstpGid in (select KstpGid from tabKostenPlaats where (KstpCode     between @VanKstp and @TotKstp and @SelecteerOp = 1) or
                                                              (KstpZoekcode between @VanKstp and @TotKstp and @SelecteerOp = 2)
                   )
    ) and
    (@OokNulSaldi=1 or
    (@OokNulSaldi=2 and (RksGid in //(select RekSaldoRksGid from tabRekeningsaldo where RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr))) or
                                   (select JrRksGid from tabJournaalRegel inner join tabJournaalpost on (JpGid = JrJpGid) inner join tabBoekingsgang on (BoekgangGid = JpBoekgangGid) where JrPerNr between @VanPerNr and @TotPerNr and JrBjGid = @BjGid and
                                   ((@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                                    (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                                    (@SoortBoeking = 2))))) or
    //0-saldi niet afdrukken, dus begin+vorige+huidige optellen en die vergelijken, ook beginbalans etc. apart testen!!
    (@OokNulSaldi=0 and (isnull(ProefDebet,0)-isnull(ProefCredit,0) <> 0 or
                         isnull(BDebet,0) - isnull(BCredit,0) <> 0 or
                         isnull(VDebet,0) - isnull(VCredit,0) <> 0 or
                         isnull(SaldiDebet,0) - isnull(SaldiCredit,0) <> 0 or
                         isnull(HDebet,0) - isnull(HCredit,0) <> 0))
    );

  set temporary option isolation_level = @IsolationLevel;

  if exists(select 1 from tmpBalans) then

    //call Trace('Stap 1b Kostenplaatsen niet uitsplitsen');
    //Kostenplaatsen niet uitsplitsen heeft alleen zin indien de checkbox balans per kostenplaats uit staat
    //Zorg er eerst voor dat alle hoofdrekeningen aanwezig zijn
    if @KstpUitsplitsen = 0 and @BalansPerKstp = 0 then
      insert into tmpBalans (
                  RegelSoort, Sortering, ValNummer, RksInvoer, RksZoekCode, RksNaam, RksNummer,
                  DefaultSoort, AfdrukZijde)
      select
        2,
        if @ComprimeerBalans = 0 then '        ' + left(substr(RksNummer, 1, @AantalCijfers) + 'ppppp', 5) + ' ' + left(RksNummer + '          ', 10) endif Sortering, // Sortering kostenplaats, balanscode, rksnummer
        @BalansInValuta,
        RksInvoer,
        RksZoekCode,
        RksNaam,
        RksNummer,
        DefaultSoort,
        AfdrukZijde
      from
        tabRekeningschema
      where
        RksNummer in (select distinct RksNummer from tmpBalans) and RksKstpgid is null and RksKstdGid is null;

      //Bedragen geboekt op verschillende kostenplaasten van een rekening totaliseren
      update tmpBalans b
      set
        BeginDebet   = isnull((select sum(a.BeginDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        BeginCredit  = isnull((select sum(a.BeginCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        VorigDebet   = isnull((select sum(a.VorigDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        VorigCredit  = isnull((select sum(a.VorigCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        HuidigDebet  = isnull((select sum(a.HuidigDebet)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        HuidigCredit = isnull((select sum(a.HuidigCredit) from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        ProefDebet   = isnull((select sum(a.ProefDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        ProefCredit  = isnull((select sum(a.ProefCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        SaldiDebet   = isnull((select sum(a.SaldiDebet)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        SaldiCredit  = isnull((select sum(a.SaldiCredit)  from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        Verlies      = isnull((select sum(a.Verlies)      from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        Winst        = isnull((select sum(a.Winst)        from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        EindDebet    = isnull((select sum(a.EindDebet)    from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0),
        EindCredit   = isnull((select sum(a.EindCredit)   from tmpBalans a where a.RksNummer = b.RksNummer and a.RegelSoort = 1 ),0)
      where RegelSoort = 2;
      //Rekeningen met kostenplaatsen verwijderen
      delete tmpBalans where RegelSoort = 1;
      // Hulpregelsoort 2 weer veranderen in regelsoort 1
      update tmpBalans
      set
        RegelSoort = 1
      where
        RegelSoort = 2;
    end if;

    //call Trace('Stap 2 Updaten ingeval @ComprimeerBalans = 2');
    if @ComprimeerBalans = 2 then  //Conform balans

      // Verdichten en Subtotalen
      // Records behorende bij paragraaf en subparagraaf
      update
        tmpBalans
      set
        BalGid = BlGid,
        BalVerdicht = isnull(BalansVerdicht, 0),
        BalDecimalen =  if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif,
        Sortering = left(KstpCode + '        ', 8) + left(substr(RksNummer, 1, if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif) + 'ppppp', 5) + ' ' + left(RksInvoer + '                            ', 28) // Sortering kostenplaats, balanscode, rksinvoer (voor evt kostendragers)
      from tmpBalans left outer join tabBalansCodeDetail on (DetailBlCode=0 and Paragraaf+SubParagraaf = left(RksInvoer,length(Paragraaf+SubParagraaf)) and Trim(SubParagraaf)<>'') ;

      // Overgebleven records behorende bij paragraaf
      update tmpBalans
      set
        BalGid = BlGid,
        BalVerdicht = isnull(BalansVerdicht, 0),
        BalDecimalen = if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif,
        Sortering = left(KstpCode + '        ', 8) + left(substr(RksNummer, 1, if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif) + 'ppppp', 5) + ' ' + left(RksInvoer + '                            ', 28) // Sortering kostenplaats, balanscode, rksinvoer (voor evt kostendragers)
      from tmpBalans left outer join tabBalansCodeDetail on (DetailBlCode=0 and Paragraaf = left(RksInvoer,2) and Trim(Paragraaf)<>'')
      //ACW 23-08-2011 Bug #33901: Deze controles niet in de FROM (ivm. left-outer-join) maar hier in de where!
      where BalGid is null and BalVerdicht = 0;

      // Overgebleven records behorende bij rubriek
      update tmpBalans
      set
        BalGid = BlGid,
        BalVerdicht = isnull(BalansVerdicht, 0),
        BalDecimalen = if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif,
        Sortering = left(KstpCode + '        ', 8) + left(substr(RksNummer, 1, if isnull(DecimalenSubTotalen, 0) = 0 then 2 else DecimalenSubTotalen endif) + 'ppppp', 5) + ' ' + left(RksInvoer + '                            ', 28) // Sortering kostenplaats, balanscode, rksinvoer (voor evt kostendragers)
      from tmpBalans left outer join tabBalansCodeDetail on (DetailBlCode=0 and Rubriek = left(RksInvoer,1) and Paragraaf='')
      //ACW 23-08-2011 Bug #33901: Deze controles niet in de FROM (ivm. left-outer-join) maar hier in de where!
      where BalGid is null and BalVerdicht = 0;
    end if;

    select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;

    //call Trace('Stap 3 Subtotalen per balanscode');
    set @RubriekTekst      = _U('Rubriek %1!');
    set @ParagraafTekst    = _U('Paragraaf %1!');
    set @SubParagraafTekst = _U('Subparagraaf %1!');

    set @StopWaarde = (select max(BalDecimalen) from tmpBalans);
    set @Teller = 1; // Hoogste niveau starten = rubrieken
    while @Teller <= @StopWaarde loop
      insert into tmpBalans
        (RegelSoort, RksNaam, RksInvoer, KstpCode, Sortering, ValNummer, ValCode,
         BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
         ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst,
         EindDebet, EindCredit, DubbeleStreepOnder)
      select
        15 - @Teller,
        IsNull((select OmsBalansCodeDetails from tabBalansCodeDetail where (DetailBlCode = 0 and RubParSub = substr(RksNummer, 1, @Teller))), if @Teller = 1 then _P(@RubriekTekst, substr(RksNummer, 1, 1))else if @Teller = 2 then _P(@ParagraafTekst, substr(RksNummer, 1, 2)) else _P(@SubParagraafTekst, substr(RksNummer, 3, @Teller - 2)) endif endif) BalOms,
        substr(RksNummer, 1, @Teller) + ' :' HulpRksInvoer,
        KstpCode,
        left(KstpCode + '        ', 8) + left(substr(RksNummer, 1, @Teller) + 'ppppp', 5) + 'q' Sortering, //(sub)paragraaf ONDER de rekeningen
        @BalansInValuta,
        @BalansValCode,
        sum(BeginDebet),
        sum(BeginCredit),
        sum(VorigDebet),
        sum(VorigCredit),
        sum(HuidigDebet),
        sum(HuidigCredit),
        sum(ProefDebet),
        sum(ProefCredit),
        sum(SaldiDebet),
        sum(SaldiCredit),
        sum(Verlies),
        sum(Winst),
        sum(EindDebet),
        sum(EindCredit),
        0
      from     tmpBalans left outer join tabBalanscodeDetail on (DetailBlCode = 0 and RubParSub = substr(RksNummer, 1, BalDecimalen) )
      where    length(RksNummer)>=@Teller and RksNummer in (select RksNummer from tmpBalans where (RegelSoort=1 and BalDecimalen >= @Teller))
      group by BalOms, HulpRksInvoer, KstpCode, Sortering;

      set @Teller = @Teller + 1;
    end loop;

    //call Trace('Stap 4 Verdichten');
    delete tmpBalans where (BalVerdicht = 1 and RegelSoort = 1);

    //call Trace('Stap 5 Subtotalen per balanscode in andere valuta');
    select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;

    if @BalansInValuta <> @TotalenInValuta then
      select if decimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabvaluta where valnummer = @TotalenInValuta;
      insert into
        tmpBalans
        (RegelSoort, KstpCode, Sortering, RksInvoer, RksNaam, ValNummer, ValCode,
         BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
         ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst,
         EindDebet, EindCredit, DubbeleStreepOnder)
      select
        6 + RegelSoort,
        KstpCode,
        Sortering + 'v',
        RksInvoer,
        RksNaam,
        @TotalenInValuta,
        @TotaalValCode,
        ValutaOmrekenen(@BalansInValuta, BeginDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, BeginCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, VorigDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, VorigCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, HuidigDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, HuidigCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, ProefDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, ProefCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, SaldiDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, SaldiCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, Verlies, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, Winst, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        ValutaOmrekenen(@BalansInValuta, EindDebet, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci), ValutaOmrekenen(@BalansInValuta, EindCredit, @TotalenInValuta, @BjGid, @TotPernr, @NumDeci),
        1
      from
        tmpBalans tmp where RegelSoort between 9 and 14;
    end if;

    //call Trace('Stap 6 RegelSoort 1 verwijderen agv comprimeren = 1');
    if @ComprimeerBalans = 1 then
      delete tmpBalans where RegelSoort = 1
    end if;

    //call Trace('Stap 7 Nummers uitdelen om dubbele strepen te zetten');
    update tmpBalans
    set    tmpHulpVolgorde = number(*)
    order by Sortering;
    create index idx_tmpHulpVolgorde on tmpBalans (tmpHulpVolgorde);

    //call Trace('Stap 8a Plaatsen van dubbele strepen voor oplopend regelniveau');
    update tmpBalans buiten
    set buiten.DubbeleStreepOnder = 1
    where (buiten.RegelSoort not in (1, 14, 20) ) and ( 1 = (select first 1 from tmpBalans binnen where binnen.tmpHulpVolgorde = buiten.tmpHulpVolgorde - 1 and binnen.RegelSoort < buiten.RegelSoort));

    //call Trace('Stap 8b Plaatsen van dubbele strepen voor rubriekniveau');
    update tmpBalans buiten
    set buiten.DubbeleStreepOnder = 1
    where (buiten.RegelSoort in (14,20)) and (buiten.DubbeleStreepOnder = 0);

    //select RksInvoer,RegelSoort, DubbeleStreepOnder,OptelStreepBoven from tmpBalans order by Sortering;
    //call Trace('Stap 9 Plaatsen van enkele strepen');
    update tmpBalans buiten
    set buiten.OptelStreepBoven = 1
    where (buiten.DubbeleStreepOnder = 1) and ( 1 = (select first 1 from tmpBalans binnen where binnen.tmpHulpVolgorde = buiten.tmpHulpVolgorde - 1 and binnen.RegelSoort < buiten.RegelSoort and binnen.RegelSoort + 6 <> buiten.RegelSoort and binnen.DubbeleStreepOnder = 0));

    //call Trace('Stap 10 verwijderen van dubbele strepen behorende bij totalen in valuta van belans in geval van extra valuta');
    if @BalansInValuta <> @TotalenInValuta then
      update tmpBalans buiten
      set buiten.DubbeleStreepOnder = 0
      where (buiten.DubbeleStreepOnder = 1) and ( 1 = (select first 1 from tmpBalans binnen where binnen.tmpHulpVolgorde = buiten.tmpHulpVolgorde + 1 and binnen.RegelSoort = buiten.RegelSoort + 6));
    end if;

    //call Trace('Stap 11 Saldo winst/verlies voor de kolommenbalans bepalen');
    set @SaldoWinstTekst   = _U('Saldo winst');
    set @SaldoVerliesTekst = _U('Saldo verlies');

    set @KostenplaatsTekst      = _U('kostenplaats %1!');
    set @KostenplaatsVanTMTekst = _U('van kostenplaats %1! t/m %2!');

    insert into tmpBalans(WinstVerlies, RegelSoort, KstpCode, Sortering, RksNaam, ValNummer, ValCode,
                          Verlies, Winst, EindDebet, EindCredit)
    select
      sum(Winst - Verlies) WinstVerlies,
      35 + if isnull(WinstVerlies,0) < 0 then 1 else 0 endif,
      KstpCode,
      left(KstpCode + '        ', 8) + 'r2',
      if isnull(WinstVerlies,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
      @BalansInValuta, @BalansValCode,
      if WinstVerlies >= 0 then     WinstVerlies endif,  if WinstVerlies < 0 then abs(WinstVerlies) endif,
      if WinstVerlies <= 0 then abs(WinstVerlies) endif, if WinstVerlies > 0 then     WinstVerlies  endif
    from
      tmpBalans
    where
      RegelSoort = 14
    group by
      KstpCode;

    if @BalansInValuta <> @TotalenInValuta then
      insert into tmpBalans(WinstVerlies, RegelSoort, KstpCode, Sortering, RksNaam, ValNummer, ValCode,
                            Verlies, Winst, EindDebet, EindCredit)
      select
        //Ook in andere valuta saldo winst/verlies bepalen
        sum(Winst - Verlies) WinstVerlies,
        37 + if isnull(WinstVerlies,0) < 0 then 1 else 0 endif,
        KstpCode,
        left(KstpCode + '        ', 8) + 'v2',
        if isnull(WinstVerlies,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
        @TotalenInValuta, @TotaalValCode,
        if WinstVerlies >= 0 then     WinstVerlies endif,  if WinstVerlies < 0 then abs(WinstVerlies) endif,
        if WinstVerlies <= 0 then abs(WinstVerlies) endif, if WinstVerlies > 0 then     WinstVerlies  endif
      from
        tmpBalans
      where
        RegelSoort = 20
      group by
        KstpCode;
    end if;

    //call Trace('Stap 12 Kolommenbalans dus subtotaal erbij');
    set @SubtotaalTekst = _U('Subtotaal');
    set @Teller = 1; //1=balansvaluta, 2=andere valuta
    while @Teller <= 2 loop
      select if DecimalenBoeking = 1 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = (if @teller = 1 then @BalansInValuta else @TotalenInValuta endif);
      insert into tmpBalans (RegelSoort, KstpCode, Sortering, RksNaam, ValNummer, ValCode,
                             BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
                             ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit)
      select
        RegelSoort+10,
        KstpCode,
        left(KstpCode + '        ', 8) + (if @Teller = 1 then 'r1' else 'v1' endif),
        @SubtotaalTekst,
        if RegelSoort = 14 then @BalansInValuta else @TotalenInValuta endif,
        if RegelSoort = 14 then @BalansValCode else @TotaalValCode endif,
        round(sum(BeginDebet), @numDeci), round(sum(BeginCredit), @numDeci), round(sum(VorigDebet), @numDeci),
        round(sum(VorigCredit), @numDeci), round(sum(HuidigDebet), @numDeci), round(sum(HuidigCredit), @numDeci),
        round(sum(ProefDebet), @numDeci), round(sum(ProefCredit), @numDeci),
        round(sum(SaldiDebet), @numDeci), round(sum(SaldiCredit), @numDeci), round(sum(Verlies), @numDeci),
        round(sum(Winst), @numDeci), round(sum(EindDebet), @numDeci), round(sum(EindCredit), @numDeci)
      from
        tmpBalans
      where
        (@teller = 1 and RegelSoort = 14) or
        (@teller = 2 and RegelSoort = 20)
      group by
        RegelSoort, KstpCode;

      set @Teller = @Teller + 1; //Let op: NIET optimaliseren (door direct op 3 te zetten) ivm. subtotaal!!
    end loop;

    //call Trace('Stap 13 Totaal generaal');
    insert into tmpBalans (RegelSoort, KstpCode, Sortering, RksNaam, ValNummer, ValCode,
                           BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
                           ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, DubbeleStreepOnder)
    select
      98,
      KstpCode,
      left(KstpCode + '        ', 8) + 'r3',
      if @BalansPerKstp = 1 then _P(@KostenplaatsTekst, KstpCode) else _P(@KostenplaatsVanTMTekst, @VanKstp, @TotKstp) endif,
      @BalansInValuta,
      @BalansValCode,
      sum(BeginDebet), sum(BeginCredit), sum(VorigDebet), sum(VorigCredit), sum(HuidigDebet), sum(HuidigCredit),
      sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit),
      0
    from
      tmpBalans
    where
      RegelSoort in (24, 35, 36)
    group by
      KstpCode;

    if @BalansInValuta <> @TotalenInValuta then
      //Totaal generaal in andere valuta
      insert into tmpBalans (RegelSoort, KstpCode, Sortering, RksNaam, ValNummer, ValCode,
                             BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
                             ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, DubbeleStreepOnder)
      select
        99,
        KstpCode,
        left(KstpCode + '        ', 8) + 'v3',
        if @BalansPerKstp = 1 then _P(@KostenplaatsTekst, KstpCode) else _P(@KostenplaatsVanTMTekst, @VanKstp, @TotKstp)  endif,
        @TotalenInValuta,
        @TotaalValCode,
        sum(BeginDebet), sum(BeginCredit), sum(VorigDebet), sum(VorigCredit), sum(HuidigDebet), sum(HuidigCredit),
        sum(ProefDebet), sum(ProefCredit), sum(SaldiDebet), sum(SaldiCredit), sum(Verlies), sum(Winst), sum(EindDebet), sum(EindCredit),
        0
      from
        tmpBalans
      where
        RegelSoort in (30, 37, 38)
      group by
        KstpCode;
    end if;

  end if; //alleen als er wel regels in staan, anders alles overgeslagen!

  set @@ErrorTextProcedure = 'rapNormaleBalansPerKstp';
  //call TraceEind(@@ErrorTextProcedure);

  select    RksInvoer, RksZoekCode, RksNaam, KstpCode, ValNummer, Valcode, BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
            ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, RegelSoort,
            OptelStreepBoven, DubbeleStreepOnder
  from      tmpBalans
  order by  Sortering;

end;

//call rapNormaleBalansPerKstp(1, 0, 12, 1, '1', '2', 2, 0, 0, 1, 1, 2, 0, 0)


create or replace procedure rapOspNaw(
in @SoortOpdracht   smallint,  //0=Openstaande Posten (evt. met analyse), 1=Bellijst, 2=Alleen creditnotas, 3 = Verrekenbare Openstaande posten.
in @DebOfCred       smallint,  //6=Debiteur, 7=Crediteur
in @SelecterenOp    smallint,  //0=NawNummer, 1=NawZoekcode
in @VanNaw          nchar(10),
in @TotNaw          nchar(10),
in @VanFactuur      nchar(40),
in @TotFactuur      nchar(40),
in @VanVervalDatum  date,
in @TotVervalDatum  date,
in @BtcSelecterenOp smallint,
in @VanBtcNummer    integer,
in @TotBtcNummer    integer,
in @VanBtcOms       nchar(40),
in @TotBtcOms       nchar(40),
in @InclusiefPostenZonderBtc smallint,
in @SorterenOp      smallint,  //0=nummer, 1=zoekcode
in @IsAscending     smallint,  //0=descending, 1 ascending
in @SoortBoeking    smallint,  //0=Definitief, 1=Voorlopig, 2=beide
in @BjGid           integer,
in @Peildatum       date,      //datum tbv. bellijst (als aant. dagen tussen vervaldatum en peildatum hoger ligt dan volgens tabAanmaning, dan osp opnemen)
in @Aanmaningnr     smallint)  //0=rek.overzicht, 1..4=1e t/m 4e aanm., 5= alle aanmaningen
result(RksGid integer, RksInvoer nchar(28), RksZoekcode nchar(10), AdrNaam1 nchar(40), AdrNaam2 nchar(40), AdrStraat nchar(40), AdrHuisnummer nchar(10),
       AdrPostcode nchar(40), AdrPlaats nchar(40),
       LndEigenCode nchar(3), LndIso2 nchar(2), LndIso3 nchar(3), LndOms nchar(40), lndInNAWBlok smallint, lndPlaatsHuisnr smallint, lndPlaatsPostcode smallint,
       ValNummer integer, ValCode nchar(3), RelatieNaam nchar(40), OmsFunctie nchar(40),
       AdrTelefoon nchar(25), RelTelefoon nchar(25), BeideTelefoon nchar(25),
       AdrTelefoon2 nchar(25), RelTelefoon2 nchar(25), BeideTelefoon2 nchar(25),
       AdrTelefax nchar(25), RelTelefax nchar(25), BeideTelefax nchar(25),
       AdrEmail nchar(80), RelEmail nchar(80), BeideEmail nchar(80),
       NawRekBankRekening nchar(34), NawFilKredLimiet numeric(15,2), AlgKredLimiet numeric(15,2), BeideKredLimiet numeric(15,2),
       LaatsteBetaalDatum date, LaatsteBetaalBedrag numeric(15,2), HoogsteAanmaningNummer integer, HoogsteAanmaningDatum date, OudsteVervalDatum date,
       TotaalOpenstaandBedrag numeric(15,2), NawKvkNummer nchar(40), NawOnsDebiteurNummer nchar(20), NawGid integer)
begin
  //Selecteer elke debiteur die minimaal 1 osp heeft binnen de range

  declare @ContactVanFunctie     integer;
  declare @HulpBjGid             integer;
  declare @HulpPerNr             integer;
  declare @RksGid                integer;
  declare @RksValNummer          integer;
  declare @JrGid                 integer;
  declare @JrBjGid               integer;
  declare @JrPernr               integer;
  declare @JrValNummer           integer;
  declare @JrValutaBedrag        numeric(15,2);
  declare @HoogsteAanmaning      integer;
  declare @HoogsteAanmaningDatum date;
  declare @JrGidVerval              integer;
  declare @OudsteVervaldatum        date;
  declare @tmpBetaaldatum           date;
  declare @FonGid                   integer;
  declare @FonKredietLimiet         numeric(15,2);
  declare @TotaalOpenstaandBedrag   numeric(15,2);
  declare @MinVerrekenbaarbedrag    numeric(15,2);   //de volgende twee voor verrekenbare bedragen worden gebruikt om te kunnen zien of er een
  declare @MaxVerrekenbaarbedrag    numeric(15,2);  // positief en negatief bedrag is. Als het gaat om de verrekenbare rapportages, dan dient er een positieve en negatieve order te zijn.

  declare local temporary table tmpOSP(
  tmpGid                     integer default autoincrement,
  tmpRksGid                  integer,
  tmpOspGid                  integer,  //OSP in de valuta
  tmpJrGidLaatsteBetaling    integer,  //Laatste betaling
  tmpBetaaldatum             date,
  tmpBetaalregelNummer       integer,
  tmpBetaalJrNummer          integer,
  tmpHoogsteAanmaningNummer  integer,
  tmpHoogsteAanmaningDatum   date,
  tmpJrGidOudsteVerval       integer,  //JV, 22 aug 06, wordt verder niet nuttig gebruikt volgens mij
  tmpOudsteVervaldatum       date,
  tmpBjGidLaatsteBetaling        integer,
  tmpPernrLaatsteBetaling        integer,
  tmpValNummerLaatsteBetaling    integer,
  tmpValutaBedragLaatsteBetaling numeric(15,2),
  tmpRksInvoer                   nchar(28),
  tmpRksZoekcode                 nchar(10),
  tmpRksValnummer                integer,
  tmpTotaalOpenstaanbedrag       numeric(15,2)
  ) on commit preserve rows;

  declare cursor_Rks no scroll cursor for
    select   distinct tmpRksGid, tmpRksValNummer
    from     tmpOSP
    for read only;

  //MR 11-okt-2013: Opvullen tot 40 met spaties. Dit is gedaan omdat de zoek versneld word (Project Verlengen factuur- en NAW-nummers)
  set @VanFactuur = Repeat(' ',40-length(@VanFactuur))+Trim(@VanFactuur);
  set @TotFactuur = Repeat(' ',40-length(@TotFactuur))+Trim(@TotFactuur);

  set @@ErrorTextProcedure = 'rapOspNaw > ';
  //call TraceBegin(@@ErrorTextProcedure + '@SoortOpdracht = ' + string(@SoortOpdracht) + ', @DebOfCred = ' + string(@DebOfCred) + ', @SelecterenOp = ' + string(@SelecterenOp) + ', @VanNaw = ' + @VanNaw+', @TotNaw = ' + @TotNaw + ', @VanFactuur = ' + @VanFactuur + ', @TotFactuur = ' + @TotFactuur + ', @VanVervalDatum = ' + string(@VanVervalDatum) + ', @TotVervalDatum = ' + string(@TotVervalDatum) + ', @SorterenOp = ' + string(@SorterenOp) + ', @IsAscending = ' + string(@IsAscending) + ', @SoortBoeking = ' + string(@SoortBoeking) + ' , @BjGid = ' + string(@BjGid) + ', @Peildatum = ' + string(@Peildatum) + ', @Aanmaningnr = ' + string(@Aanmaningnr));

  //Welke functie moeten we voor de contactpersoon gebruiken?
  select SchermFnCode into @ContactVanFunctie from tabScherm where SchermSoort = if @DebOfCred = 6 then 10 else 20 endif;

  select FonGid, FonKredietLimiet into @FonGid, @FonKredietLimiet from tabFileOfNaw where FonId = (if @DebOfCred = 6 then 'D' else 'C' endif);
  //call Trace('rapOspNaw > FonGid = ' + string(@FonGid));

  //call Trace('rapOspNaw > @ContactVanFunctie = ' + string(@ContactVanFunctie));
  //tbv. omrekenen van kredietlimiet
  call BepaalBoekjaarEnPeriode (@@VerwerkingsDatum, @HulpBjGid, @HulpPerNr);


  //Eerst alle OSPs van de debiteuren opvragen
  //call Trace('rapOspNaw > Insert!');
  insert into tmpOSP(tmpRksGid, tmpOspGid, tmpJrGidLaatsteBetaling, tmpBetaaldatum, tmpBetaalregelNummer, tmpBetaalJrNummer, tmpHoogsteAanmaningNummer, tmpHoogsteAanmaningDatum,
                     tmpJrGidOudsteVerval, tmpOudsteVervaldatum,
                     tmpBjGidLaatsteBetaling, tmpPernrLaatsteBetaling, tmpValNummerLaatsteBetaling, tmpValutaBedragLaatsteBetaling,
                     tmpRksInvoer, tmpRksZoekcode, tmpRksValnummer)
  select
    OspRksGid, OspGid, JrGid, JrBoekdatum, RegelNummer, JrNummer, OspAanmaningTeller, OspLaatsteAanmaning,
    JrGid, if JrGid is null then OspVervalDatum else JrVervalDatum endif,//JV, 22 aug 06, zie bug 19338, bij osp zonder deelbetaling kwam er geen oudste vervaldatum op de layout(zie join met tabjournaalregel hieronder)
    JrBjGid, JrPernr, JrValNummer, JrValutaBedrag,
    RksInvoer, RksZoekcode, RksValnummer
  from
    tabOpenstaandePost
    inner join tabRekeningschema on (RksGid = OspRksGid)
    left outer join tabBetalingsconditie on OspBtcNummer = BtcNummer
    left outer join (tabJournaalregel)
      on (SoortBoeking=0 and JrOspGid = OspGid and JrBjGid = @BjGid and //Alleen journaalregels van de osp en in hetzelfde boekjaar
          (IsCreditBoeking=-@DebOfCred + 7) and //alleen betalingen
          (   (@SoortBoeking=0 and RegelNummer is not null)
           or (@SoortBoeking=1 and RegelNummer is     null)
           or (@SoortBoeking=2)
          )) //alleen voorlopig/definitief

  where DefaultSoort = @DebOfCred and                                          //Alleen de deb. of juist alleen de cred.
      ((@SelecterenOp = 0 and RksInvoer   between @VanNaw and @TotNaw) or    //Alleen naw binnen de range
       (@SelecterenOp = 1 and RksZoekCode between @VanNaw and @TotNaw)) and
      ((Repeat(' ',40-OspFactuurnummer_Lengte)+Trim(OspFactuurnummer)) between @VanFactuur and @TotFactuur) and //die binnen de factuurrange liggen
      (OspVervalDatum between @VanVervalDatum and @TotVervalDatum) //en binnen de vervaldatum-range liggen
      and   (
           (@BtcSelecterenOp = 0 and OspBtcNummer between @VanBtcNummer and @TotBtcNummer)
        or (@BtcSelecterenOp = 1 and BtcOms between @VanBtcOms and @TotBtcOms)
        or (@InclusiefPostenZonderBtc = 1 and OspBtcNummer is null)  )

      and OspBjGid=@BjGid                                          //en op dit boekjaar betrekking hebben
      and sign(case @SoortBoeking
               when 0 then OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief
               when 1 then OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig
               when 2 then (OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig) + (OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief)
               end) in (1, if @SoortOpdracht <> 1 then -1 else 1 endif) //Als bellijst, dan alleen 'te betalen' OSPs, anders elke OSP<>0

      //Creditnota of niet
      and
      (@SoortOpdracht <> 2 or
       (@SoortOpdracht = 2 and
        (case @SoortBoeking
         when 0 then OspFactuurBedragDefinitief
         when 1 then OspFactuurBedragVoorlopig
         when 2 then OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig
         end
        )< 0
       )
      )
      //Bellijst-verhaal!!
      and
      ((@SoortOpdracht<> 1) or                   //Geen bellijst
       (@SoortOpdracht = 1 and                   //Bellijst, dus rekening houden met aanmaningsnummer
        isnull(OspAanmaningTeller,0) >= @AanmaningNr //Aanmaningsnummer
        and
        @Peildatum - IsNull(OspLaatsteAanmaning, OspVervalDatum) >=
          if (@AanmaningNr = 0 or isnull(OspAanmaningTeller,0) = 0) then 0 else isnull((select AanmOpBellijstNa
                                          from tabAanmaning
                                          where AanmNummer = OspAanmaningTeller),0) endif
          and (case @SoortBoeking
               when 0 then OspFactuurBedragDefinitief
               when 1 then OspFactuurBedragVoorlopig
               when 2 then OspFactuurBedragVoorlopig + OspFactuurBedragDefinitief
               end) > 0 //Alleen als het een 'echte' factuur betreft; creditnota of 0-factuur worden nooit vermeld
       )
      );

  //Handig voor debugging:
  //unload select * from tmpOSP To 'C:\tmposp01.txt';


  //Laatste betaling, hoogste aanmaning en eerste vervaldatum van alle OSPs invullen
  //call Trace('rapOspNaw > Create index');
  Create index idx_tmpOSPRksGid      on tmpOSP (tmpRksGid);

  //call Trace('rapOspNaw > Open cursor');
  open cursor_Rks;
  LoopRks:
  loop
    fetch next cursor_Rks into @RksGid, @RksValNummer;
    if sqlstate = '02000' then
      leave LoopRks;
    end if;

    set @JrGid                 = null;
    set @tmpBetaaldatum        = null;
    set @HoogsteAanmaning      = null;
    set @HoogsteAanmaningDatum = null;
    set @JrGidVerval           = null;
    set @OudsteVervaldatum     = null;
    set @JrValutaBedrag        = null;

    //Ophalen laatste betaling journaalregel)
    select first tmpJrGidLaatsteBetaling, tmpBetaaldatum, tmpBjGidLaatsteBetaling, tmpPernrLaatsteBetaling, tmpValNummerLaatsteBetaling, tmpValutaBedragLaatsteBetaling
    into @JrGid, @tmpBetaaldatum, @JrBjGid, @JrPernr, @JrValNummer, @JrValutaBedrag
    from tmpOSP where tmpRksGid = @RksGid and tmpJrGidLaatsteBetaling is not null order by tmpBetaaldatum desc, tmpBetaalregelNummer desc, tmpBetaalJrNummer desc;
    //Ophalen hoogste aanmaningennummer
    select first tmpHoogsteAanmaningNummer, tmpHoogsteAanmaningDatum into @HoogsteAanmaning, @HoogsteAanmaningDatum from tmpOSP where tmpRksGid = @RksGid order by tmpHoogsteAanmaningNummer desc, tmpHoogsteAanmaningDatum desc;
    //Ophalen van de oudste vervaldatum
    select first tmpJrGidOudsteVerval, tmpOudsteVervaldatum into @JrGidVerval, @OudsteVervaldatum from tmpOSP where tmpRksGid = @RksGid and tmpOudsteVervaldatum is not null order by tmpOudsteVervaldatum;

    select sum(ValutaOmrekenen(OspValNummer,
                          case @SoortBoeking
                             when 0 then isnull(OspFactuurBedragDefinitief,0) - isnull(OspBetaaldBedragDefinitief,0)
                             when 1 then isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragVoorlopig,0)
                             when 2 then (isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragVoorlopig,0)) + (isnull(OspFactuurBedragDefinitief,0) - isnull(OspBetaaldBedragDefinitief,0))
                          end, @RksValNummer, @HulpBjGid, @HulpPernr, 2)) into @TotaalOpenstaandBedrag
               from   tabOpenstaandePost
               left outer join tabBetalingsconditie on OspBtcNummer = BtcNummer
               where  OspBjGid = @BjGid
                      and OspRksGid = @RksGid
                      and ((Repeat(' ',40-OspFactuurnummer_Lengte)+Trim(OspFactuurnummer)) between @VanFactuur and @TotFactuur) //die binnen de factuurrange liggen
                      and OspVervalDatum between @VanVervalDatum and @TotVervalDatum
                      and (
                           (@BtcSelecterenOp = 0 and OspBtcNummer between @VanBtcNummer and @TotBtcNummer)
                        or (@BtcSelecterenOp = 1 and BtcOms between @VanBtcOms and @TotBtcOms)
                        or (@InclusiefPostenZonderBtc = 1 and OspBtcNummer is null)  );

      if (@SoortOpdracht = 3) Then
        select min(ValutaOmrekenen(OspValNummer,
                  case @SoortBoeking
                     when 0 then isnull(OspFactuurBedragDefinitief,0) - isnull(OspBetaaldBedragDefinitief,0)
                     when 1 then isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragVoorlopig,0)
                     when 2 then (isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragVoorlopig,0)) + (isnull(OspFactuurBedragDefinitief,0) - isnull(OspBetaaldBedragDefinitief,0))
                  end, @RksValNummer, @HulpBjGid, @HulpPernr, 2)) into @MinVerrekenbaarbedrag
        from   tabOpenstaandePost
        left outer join tabBetalingsconditie on OspBtcNummer = BtcNummer
        where  OspBjGid = @BjGid
              and OspRksGid = @RksGid
              and ((Repeat(' ',40-OspFactuurnummer_Lengte)+Trim(OspFactuurnummer)) between @VanFactuur and @TotFactuur) //die binnen de factuurrange liggen
              and OspVervalDatum between @VanVervalDatum and @TotVervalDatum
              and (
                   (@BtcSelecterenOp = 0 and OspBtcNummer between @VanBtcNummer and @TotBtcNummer)
                or (@BtcSelecterenOp = 1 and BtcOms between @VanBtcOms and @TotBtcOms)
                or (@InclusiefPostenZonderBtc = 1 and OspBtcNummer is null)  );


        select max(ValutaOmrekenen(OspValNummer,
                  case @SoortBoeking
                     when 0 then isnull(OspFactuurBedragDefinitief,0) - isnull(OspBetaaldBedragDefinitief,0)
                     when 1 then isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragVoorlopig,0)
                     when 2 then (isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragVoorlopig,0)) + (isnull(OspFactuurBedragDefinitief,0) - isnull(OspBetaaldBedragDefinitief,0))
                  end, @RksValNummer, @HulpBjGid, @HulpPernr, 2)) into @MaxVerrekenbaarbedrag
        from   tabOpenstaandePost
        left outer join tabBetalingsconditie on OspBtcNummer = BtcNummer
        where  OspBjGid = @BjGid
            and OspRksGid = @RksGid
            and ((Repeat(' ',40-OspFactuurnummer_Lengte)+Trim(OspFactuurnummer)) between @VanFactuur and @TotFactuur) //die binnen de factuurrange liggen
            and OspVervalDatum between @VanVervalDatum and @TotVervalDatum
            and (
                 (@BtcSelecterenOp = 0 and OspBtcNummer between @VanBtcNummer and @TotBtcNummer)
              or (@BtcSelecterenOp = 1 and BtcOms between @VanBtcOms and @TotBtcOms)
              or (@InclusiefPostenZonderBtc = 1 and OspBtcNummer is null)  );


        if (@MinVerrekenbaarbedrag >= 0 Or @MaxVerrekenbaarbedrag < 0) then
            //Dit betekent dat er geen bedrag kleiner dan 0 is en geen groter dan 0. Deze dient dus verwijdert te worden.
            Delete from tmpOSP where tmpRksGid = @RksGid;
        end if;
      End if;

    //En wegschrijven van de gegevens
    update tmpOSP
    set tmpJrGidLaatsteBetaling   = @JrGid,
        tmpBetaaldatum            = @tmpBetaaldatum,
        tmpHoogsteAanmaningnummer = @HoogsteAanmaning,
        tmpHoogsteAanmaningDatum  = @HoogsteAanmaningDatum,
        tmpJrGidOudsteVerval      = @JrGidVerval,
        tmpOudsteVervaldatum      = @OudsteVervaldatum,
        tmpBjGidLaatsteBetaling        = @JrBjGid,
        tmpPernrLaatsteBetaling        = @JrPernr,
        tmpValNummerLaatsteBetaling    = @JrValNummer,
        tmpValutaBedragLaatsteBetaling = @JrValutaBedrag,
        tmpTotaalOpenstaanbedrag       = @TotaalOpenstaandBedrag
    where tmpRksGid = @RksGid;
  end loop LoopRks;
  close cursor_Rks;

  //Handig voor debugging:
  //unload select * from tmpOSP To 'C:\tmposp02.txt';

  set @@ErrorTextProcedure = 'rapOspNaw';
  //call TraceEind(@@ErrorTextProcedure);

  select distinct
       tmpRksGid,
       tmpRksInvoer,
       tmpRksZoekcode,
       AdrNaam1,
       AdrNaam2,
       AdrStraat,
       AdrHuisnummer,
       AdrPostcode,
       AdrPlaats,
       LndEigenCode,
       LndIso2,
       LndIso3,
       LndOms,
       lndInNAWBlok,
       lndPlaatsHuisnr,
       lndPlaatsPostcode,
       tmpRksValNummer ValNummer,
      (select ValCode from tabValuta where ValNummer = tmpRksValNummer) ValCode,
       if IsBelangrijkste is not null then
         RelVolledigeNaam
       endif RelatieNaam,
      (select OmsFunctie from tabFunctieContact where FnCode = RelFnCode) OmsFunctie,
       AdrTelefoon,
       RelTelefoon,
       if IsBelangrijkste is null or isnull(RelTelefoon,'')='' then
         AdrTelefoon
       else
         RelTelefoon
       endif BeideTelefoon,
       AdrTelefoon2,
       RelTelefoon2,
       if IsBelangrijkste is null or isnull(RelTelefoon2,'')='' then
         AdrTelefoon2
       else
         RelTelefoon2
       endif BeideTelefoon2,
       AdrTelefax,
       RelTelefax,
       if IsBelangrijkste is null or isnull(RelTelefax,'')='' then
         AdrTelefax
       else
          RelTelefax
       endif BeideTelefax,
       AdrEmail,
       RelEmail,
       if IsBelangrijkste is null or isnull(RelEmail,'')='' then
         AdrEmail
       else
         RelEmail
       endif BeideEmail,
      (select first NawRekBankRekening from tabNawRekening where NawrekNawGid = NawGid and NawrekSoort like '%D%') NawRekBankRekening,
       NawFilKredLimiet,
      (select ValutaOmrekenen(@@BasisValutaNummer, @FonKredietLimiet , tmpRksValNummer, @HulpBjGid, @HulpPernr, 2)) AlgKredLimiet,
       if NawFilKredLimiet <> 0 then NawFilKredLimiet else  AlgKredLimiet endif BeideKredLimiet,
       tmpBetaaldatum LaatsteBetaalDatum,
       if tmpValNummerLaatsteBetaling = ValNummer then tmpValutaBedragLaatsteBetaling else ValutaOmrekenen(tmpValNummerLaatsteBetaling, tmpValutaBedragLaatsteBetaling, ValNummer, tmpBjGidLaatsteBetaling, tmpPernrLaatsteBetaling, 2) endif LaatsteBetaalBedrag,
       tmpHoogsteAanmaningNummer HoogsteAanmaningNummer,
       tmpHoogsteAanmaningDatum HoogsteAanmaningDatum,
       tmpOudsteVervaldatum OudsteVervalDatum,
       tmpTotaalOpenstaanbedrag TotaalOpenstaandBedrag,
       NawKvkNummer,
       NawOnsDebiteurNummer,
       NawGid
  from  tmpOSP
        inner join tabNawFile              on (NawFilRksGid = tmpRksGid)
        inner join tabNaw                  on (NawGid = NawFilNawGid)
        inner join tabAdres                on (AdrGid = NawGidVestiging)
        inner join tabland                 on (LndGid = AdrLndGid)
        left outer join (tabRelatie
                         inner join tabRelatieFunctie on (RelFnCode = @ContactVanFunctie and IsBelangrijkste = 1))
                         on (RelNawGid = NawGid and RelGid = FnRelGid)
  order by
        if @IsAscending = 0 and @SorterenOp = 1 then tmpRksZoekCode endif DESC,
        if @IsAscending = 0 then tmpRksInvoer endif DESC,
        if @SorterenOp = 1 then tmpRksZoekCode endif ASC,
        tmpRksInvoer ASC;


end;

//Openstaande posten:
//call rapOspNaw(0, 6, 0, '', '99999999', '', 'zzzzzzzzzz', '2000-01-01', '2000-12-31', 0, 1, 2, 2, null, null);
//Bellijst:
//call rapOspNaw(1, 6, 0, '', '99999999', '', 'zzzzzzzzzz', '2000-01-01', '2000-12-31', 0, 1, 2, 2, '2001-01-01', 5);


create or replace procedure rapOspOsp (
in @SoortOpdracht   smallint,  //0=Openstaande Posten (evt. met analyse), 1=Bellijst, 2=Alleen creditnotas, 3 = Verrekenbare Openstaande posten.
in @RksGid          integer,
in @VanFactuur      nchar(40),
in @TotFactuur      nchar(40),
in @VanVervalDatum  date,
in @TotVervalDatum  date,
in @BtcSelecterenOp smallint,
in @VanBtcNummer    integer,
in @TotBtcNummer    integer,
in @VanBtcOms       nchar(40),
in @TotBtcOms       nchar(40),
in @InclusiefPostenZonderBtc smallint,
in @SorterenOpOsp   smallint, //0=factuur/ref.nr, 1=factuurdatum, 2=vervaldatum, 3=factbedrag, 4=openst.bedrag, 5=valutacode
in @IsAscendingOsp  smallint, //0=descending, 1 ascending
in @SoortBoeking    smallint, //0=Definitief, 1=Voorlopig, 2=beide
in @BjGid           integer,
in @PeilDatum       date,
//JV, 23 aug 06: nav bug 4820: alle osps afdrukken bij bellijst : daardoor zijn deze 2 parameters niet meer nodig:
in @Aanmaningnr     smallint, //0=rek.overzicht, 1..4=1e t/m 4e aanm., 5= alle aanmaningen
in @AllePosten      smallint,
//
in @Dagen1          smallint,
in @Dagen2          smallint,
in @Dagen3          smallint,
in @OuderdomObv     smallint) //nav wens 15850, 0=vervaldatum, 1=factuurdatum

result(OspFactuurNummer nchar(40), OspFactuurDatum date, ValNummer integer, ValCode nchar(3),
       OspFactuurBedrag numeric(15,2), OspBetaaldBedrag numeric(15,2), OspFactuurBedragBasis numeric(15,2), OspBetaaldBedragBasis numeric(15,2),
       LaatsteJrGid integer, LaatsteJpGid integer,
       OmsDagboek nchar(40), DgbCode nchar(10), BoekstukVolgNummer nchar(14), BoekstukNummerFactuur numeric(10,0), BoekDatum date, OspVervalDatum date, OspBetalingsKenmerk nchar(140),
       OspOms nchar(40), OspAanmaningTeller integer, OspLaatsteAanmaning date, OspIsGeblokkeerd smallint, OspMeldingGeven smallint, OspKredietBeperkingsDatum date,
       RksInvoerKredietBep nchar(28), Opmerking long nvarchar, OspKredietBeperkingsBedrag numeric(15,2),
       Kolom1 numeric(15,2), Kolom2 numeric(15,2), Kolom3 numeric(15,2), Kolom4 numeric(15,2), AantalDagenVervallen integer, VervallenPerPeilDatum numeric(15,2), VervallenPerPeilDatumBasis numeric(15,2),
       OspOpenstaand numeric(15,2), OspOpenstaandBasis numeric(15,2),
       OspIncDatum date, OspIncNawBankrekening nchar(34), OspIncOpdrachten integer, OspIncPogingenOver integer, OspViaIncasso smallint, ValNummerBedragOnderweg integer, OspBedragOnderwegInValutaOsp numeric(15,2), OspBedragOnderwegInValutaOsp2 numeric(15,2),
       OspGefiatteerd smallint, OspFiatteringGewijzigdDoor  nchar(40), OspFiatteringGewijzigdOp timestamp, OspBtcNummer integer, BtcOms nchar(40)
       )
begin
  declare @HulpBjGid integer;
  declare @Pernr integer;
  declare @RksValNummer integer;
  declare @defaultSoort smallint;

  //call TraceBegin('rapOspOsp (@SoortOpdracht='+string(@SoortOpdracht)+', @RksGid='+string(@RksGid)+', @VanFactuur='+@VanFactuur+', @TotFactuur='+@TotFactuur+', @VanVervalDatum='+string(@VanVervalDatum)+', @TotVervalDatum='+string(@TotVervalDatum)+', ...');
  //call Trace('..., @SorterenOpOsp='+string(@SorterenOpOsp)+', @IsAscendingOsp='+string(@IsAscendingOsp)+', @SoortBoeking='+string(@SoortBoeking)+', @BjGid='+string(@BjGid)+', @PeilDatum='+string(@PeilDatum)+', @Aanmaningnr='+string(@Aanmaningnr)+', ...');
  //call Trace('..., @Dagen1='+string(@Dagen1)+', @Dagen2='+string(@Dagen2)+', @Dagen3='+string(@Dagen3)+')');

  //MR 11-okt-2013: Opvullen tot 40 met spaties. Dit is gedaan omdat de zoek versneld word (Project Verlengen factuur- en NAW-nummers)
  set @VanFactuur = Repeat(' ',40-length(@VanFactuur))+Trim(@VanFactuur);
  set @TotFactuur = Repeat(' ',40-length(@TotFactuur))+Trim(@TotFactuur);

  call BepaalBoekjaarEnPeriode (@@VerwerkingsDatum, @HulpBjGid, @PerNr);

  //Bepaal de termijnen.
  set @dagen2 = @dagen1 + @dagen2;
  set @dagen3 = @dagen2 + @dagen3;

  //tbv. bedrag in valuta van deb. e.a.
  select RksValNummer, defaultSoort into @RksValNummer, @defaultSoort from tabrekeningschema where RksGid = @RksGid;


  //call TraceEind('rapOspOsp');

    //Opvragen van de info en doorgeven aan rapport
    select
      OspFactuurNummer,
      OspFactuurDatum,
      OspValNummer ValNummer,
      (select ValCode from tabValuta where ValNummer = OspValNummer) ValCode,
      case @SoortBoeking
        when 0 then OspFactuurBedragDefinitief
        when 1 then OspFactuurBedragVoorlopig
        else        OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig
      end OspFactuurBedrag,
      case @SoortBoeking
        when 0 then OspBetaaldBedragDefinitief
        when 1 then OspBetaaldBedragVoorlopig
        else        OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig
      end OspBetaaldBedrag,
      if OspValNummer = @@BasisValutaNummer then OspFactuurBedrag else ValutaOmrekenen(OspValNummer, OspFactuurBedrag, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) endif OspFactuurBedragBasis,
      if OspValNummer = @@BasisValutaNummer then OspBetaaldBedrag else ValutaOmrekenen(OspValNummer, OspBetaaldBedrag, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) endif OspBetaaldBedragBasis,
      JrGid LaatsteJrGid,
      JrJpGid LaatsteJpGid,
      (select OmsDagboek from tabDagboek where DgbCode = JrDgbCode) OmsDagboek,
      JrDgbCode,
      if StukVolgNr is not null then string(JrBoekstukNummer)+'.'+right('000'+string(StukVolgNr),3) endif BoekstukVolgNummer,
      //vr 14-04-04: Extra veld 'boekstuknummer van de factuur' ivm met bug 1897
     (select first JrBoekstuknummer from tabJournaalregel where JrBjGid = @BjGid and JrReferentie_Lengte = OspFactuurnummer_Lengte and JrReferentie = OspFactuurnummer and JrRksGid = @RksGid and IsBetaling(JrRksGid, IsCreditBoeking) = 0) BoekstukNummerFactuur,
      JrBoekDatum BoekDatum,
      OspVervalDatum,
      OspBetalingsKenmerk,
      OspOms,
      if OspLaatsteAanmaning is not null then OspAanmaningTeller endif,
      OspLaatsteAanmaning,
      OspIsGeblokkeerd,
      OspMeldingGeven,
      OspKredietBeperkingsDatum,
      (Select RksInvoer from tabRekeningSchema where RksGid=OspKredietBeperkingsRksGid) RksInvoerKredietBep,
      OspOpmerking Opmerking,
      OspKredietBeperkingsBedrag,
      //nav wens 15850 OspVervalDatum vervangen door (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif)
      (if @PeilDatum <= (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @Dagen1                                                                                           then isnull(OspFactuurBedrag,0) - isnull(OspBetaaldBedrag,0) endif) Kolom1,
      (if @PeilDatum between (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @Dagen1 + 1 and (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @Dagen2 then isnull(OspFactuurBedrag,0) - isnull(OspBetaaldBedrag,0) endif) Kolom2,
      (if @PeilDatum between (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @Dagen2 + 1 and (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @Dagen3 then isnull(OspFactuurBedrag,0) - isnull(OspBetaaldBedrag,0) endif) Kolom3,
      (if @PeilDatum >  (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @Dagen3                                                                                           then isnull(OspFactuurBedrag,0) - isnull(OspBetaaldBedrag,0) endif) Kolom4,
      datediff(day, OspVervalDatum, @PeilDatum) AantalDagenVervallen,
      (if datediff(day, OspVervalDatum, @PeilDatum) > 0 then isnull(OspFactuurBedrag,0) - isnull(OspBetaaldBedrag,0) endif) VervallenPerPeilDatum,
      if OspValNummer = @@BasisValutaNummer then VervallenPerPeilDatum else ValutaOmrekenen(OspValNummer, VervallenPerPeilDatum, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) endif VervallenPerPeilDatumBasis,
      OspFactuurBedrag - OspBetaaldBedrag OspOpenstaand,
      OspFactuurBedragBasis - OspBetaaldBedragBasis OspOpenstaandBasis,
      OspIncDatum,
      (select NawRekBankRekening from tabNawRekening where NawRekGid = OspIncNawRekGid) OspIncNawBankrekening,
      OspIncOpdrachten,
      OspIncPogingenOver,
      (if OspSoortFactuur = 3 then 1 else 0 endif) OspViaIncasso,
      (if OspValNummerBedragOnderweg is null then @@BasisValutaNummer else OspValNummerBedragOnderweg endif) ValNummerBedragOnderweg,
      (if ValNummerBedragOnderweg = OspValNummer then OspBedragOnderwegInValuta else ValutaOmrekenen(ValNummerBedragOnderweg, OspBedragOnderwegInValuta, OspValnummer, @BjGid, @PerNr, 2) endif) OspBedragOnderwegInValutaOsp,
       OspBedragOnderwegInValutaOsp OspBedragOnderwegInValutaOsp2,
			 OspGefiatteerd, OspFiatteringGewijzigdDoor, OspFiatteringGewijzigdOp,
       OspBtcNummer, BtcOms
  from  tabOpenstaandePost
       // In kader van Bug #25122 bepaling van laatste deelbetaling ahv bestaande functie GeefLaatsteDeelBetalingJrgid
       left outer join tabJournaalRegel   on (JrGid = GeefLaatsteDeelBetalingJrgid(OspGid, @HulpBjGid, @SoortBoeking))
       left outer join tabBetalingsconditie on OspBtcNummer = BtcNummer
  where
      OspRksGid = @RksGid and                                      //Alle osp van de NAW
      ((Repeat(' ',40-OspFactuurnummer_Lengte)+Trim(OspFactuurnummer)) between @VanFactuur and @TotFactuur) and //die binnen de factuurrange liggen
      (OspVervalDatum between @VanVervalDatum and @TotVervalDatum) //en binnen de vervaldatum-range liggen
      and   (
           (@BtcSelecterenOp = 0 and OspBtcNummer between @VanBtcNummer and @TotBtcNummer)
        or (@BtcSelecterenOp = 1 and BtcOms between @VanBtcOms and @TotBtcOms)
        or (@InclusiefPostenZonderBtc = 1 and OspBtcNummer is null)  )
      and OspBjGid=@BjGid                                          //en op dit boekjaar betrekking hebben
      and sign(OspFactuurBedrag - OspBetaaldBedrag) in (1, -1 ) //dus <> 0
      and
      //Creditnota of niet
      (@SoortOpdracht <> 2 or
       (@SoortOpdracht = 2 and (case @SoortBoeking when 0 then OspFactuurBedragDefinitief when 1 then OspFactuurBedragVoorlopig when 2 then OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig end)< 0)
      )
      //Bellijst-verhaal!!
      //JV, 23 aug 06: nav bug 4820: alle osps afdrukken bij bellijst
  order by
    // DG let op: sortering op factuurnummer fungeert altijd als secundaire sort!
    if @IsAscendingOsp = 0 and @SorterenOpOsp = 1 then OspFactuurDatum endif desc,                      // sorteren aflopend op factuurdatum
    if @IsAscendingOsp = 0 and @SorterenOpOsp = 2 then OspVervalDatum endif desc,                       // sorteren aflopend op vervaldatum
    if @IsAscendingOsp = 0 and @SorterenOpOsp = 3 then OspFactuurBedrag endif desc,                     // sorteren aflopend op factuurbedrag
    if @IsAscendingOsp = 0 and @SorterenOpOsp = 4 then OspFactuurBedrag - OspBetaaldBedrag endif desc,  // sorteren aflopend op openstaand bedrag
    if @IsAscendingOsp = 0 and @SorterenOpOsp = 5 then ValCode endif desc,                              // sorteren aflopend op valutacode
    // secundaire sortering aflopend op factuurnummer
    if @IsAscendingOsp = 0 then OspFactuurNummer_Lengte endif desc,
    if @IsAscendingOsp = 0 then OspFactuurNummer endif desc,

    // Oplopende sortering
    if @IsAscendingOsp = 1 and @SorterenOpOsp = 1 then OspFactuurDatum endif,                      // sorteren oplopend op factuurdatum
    if @IsAscendingOsp = 1 and @SorterenOpOsp = 2 then OspVervalDatum endif,                       // sorteren oplopend op vervaldatum
    if @IsAscendingOsp = 1 and @SorterenOpOsp = 3 then OspFactuurBedrag endif,                     // sorteren oplopend op factuurbedrag
    if @IsAscendingOsp = 1 and @SorterenOpOsp = 4 then OspFactuurBedrag - OspBetaaldBedrag endif,  // sorteren oplopend op openstaand bedrag
    if @IsAscendingOsp = 1 and @SorterenOpOsp = 5 then ValCode endif,                              // sorteren oplopend op valutacode
    // secundaire sortering aflopend op factuurnummer
    if @IsAscendingOsp = 1 then OspFactuurNummer_Lengte endif,
    if @IsAscendingOsp = 1 then OspFactuurNummer endif
end;

//Openstaande posten
//call rapOspOsp( 0, 114, '        ', '99999999', '20000101', '20001231', 0, 1, 2, 2, '20000101', null, 30, 30, 30)
//Bellijst
//call rapOspOsp( 1, 114, '        ', '99999999', '20000101', '20001231', 0, 1, 2, 2, '20000101', 0, 30, 30, 30)


create or replace procedure rapOspVal (
in @SoortOpdracht         smallint,  //0=Openstaande Posten (evt. met analyse), 1=Bellijst, 2=Alleen creditnotas
in @DebOfCred             smallint,  //6=Debiteur, 7=Crediteur
in @SelecterenOp          smallint,  //0=NawNummer, 1=NawZoekcode
in @VanNaw                nchar(10),
in @TotNaw                nchar(10),
in @VanFactuur            nchar(40),
in @TotFactuur            nchar(40),
in @VanVervalDatum        date,
in @TotVervalDatum        date,
in @BtcSelecterenOp       smallint,
in @VanBtcNummer          integer,
in @TotBtcNummer          integer,
in @VanBtcOms             nchar(40),
in @TotBtcOms             nchar(40),
in @InclusiefPostenZonderBtc smallint,
in @SoortBoeking          smallint,     //0=Definitief, 1=Voorlopig, 2=beide
in @BjGid                 integer,
in @PeilDatum             date,
//JV, 23 aug 06: nav bug 4820: alle osps afdrukken bij bellijst : daardoor zijn deze 2 parameters niet meer nodig:
in @Aanmaningnr           smallint, //0=rek.overzicht, 1..4=1e t/m 4e aanm., 5= alle aanmaningen
in @AllePosten            smallint,
//
in @Dagen1                smallint,
in @Dagen2                smallint,
in @Dagen3                smallint,
in @AnalyseValNummer      integer,      //Als null, dan valuta van de regel, anders deze valuta
in @OuderdomObv           smallint)     //nav wens 15850, 0=vervaldatum, 1=factuurdatum

//LET OP: Deze query wordt ook gebruikt om (per deb.) de totalen cumulatief weer te geven.
//Velden die dan niet geldig zijn (en dus NULL): FactuurBedrag, BetaaldBedrag en OpenstaandBedrag
result(ValNummer integer, ValCode nchar(3), OmsValuta nchar(40), FactuurBedrag numeric(15,2), FactuurBedragBasis numeric(15,2),
       BetaaldBedrag numeric(15,2), BetaaldBedragBasis numeric(15,2),
       AnalyseValNummer integer, AnalyseValCode nchar(3),
       Kolom1 numeric(15,2), Kolom2 numeric(15,2), Kolom3 numeric(15,2), Kolom4 numeric(15,2),
       BasisCumKolom1 numeric(15,2), BasisCumKolom2 numeric(15,2), BasisCumKolom3 numeric(15,2), BasisCumKolom4 numeric(15,2),
       VervallenBedrag numeric(15,2), VervallenBedragBasis numeric(15,2),
       OpenstaandBedrag numeric(15,2), OpenstaandBedragBasis numeric(15,2))
begin
  declare @HulpBjGid             integer;
  declare @Pernr                 integer;

  //call TraceBegin('rapOspVal(@SoortOpdracht='+string(@SoortOpdracht)+', @DebOfCred='+string(@DebOfCred)+', @SelecterenOp='+string(@SelecterenOp)+', @VanNaw='+@VanNaw+', @TotNaw='+@TotNaw+', @VanFactuur='+@VanFactuur+', @TotFactuur='+@TotFactuur+', @VanVervalDatum='+string(@VanVervalDatum)+', @TotVervalDatum='+string(@TotVervalDatum)+', ...');
  //call Trace('..., @SoortBoeking='+string(@SoortBoeking)+', @BjGid='+string(@BjGid)+', @PeilDatum='+string(@PeilDatum)+', @Aanmaningnr='+string(@Aanmaningnr)+', @Dagen1='+string(@Dagen1)+', @Dagen2='+string(@Dagen2)+', @Dagen3='+string(@Dagen3)+', @AnalyseValNummer='+string(@AnalyseValNummer)+')');

  //MR 11-okt-2013: Opvullen tot 40 met spaties. Dit is gedaan omdat de zoek versneld word (Project Verlengen factuur- en NAW-nummers)
  set @VanFactuur = Repeat(' ',40-length(@VanFactuur))+Trim(@VanFactuur);
  set @TotFactuur = Repeat(' ',40-length(@TotFactuur))+Trim(@TotFactuur);

  call BepaalBoekjaarEnPeriode (@@VerwerkingsDatum, @HulpBjGid, @PerNr);

  //Bepaal de termijnen.
  set @dagen2 = @dagen1 + @dagen2;
  set @dagen3 = @dagen2 + @dagen3;

  //call Trace('1');

  //call TraceEind('rapOspVal');

  select
    TotVal.ValNummer,
    TotVal.ValCode,
    TotVal.OmsValuta,
    sum(case @SoortBoeking
          when 0 then OspFactuurBedragDefinitief
          when 1 then OspFactuurBedragVoorlopig
          else        isnull(OspFactuurBedragDefinitief,0) + isnull(OspFactuurBedragVoorlopig,0)
        end)
    FactuurBedrag,
    ValutaOmrekenen(OspValNummer, FactuurBedrag, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) FactuurBedragBasis,
    sum(case @SoortBoeking
          when 0 then OspBetaaldBedragDefinitief
          when 1 then OspBetaaldBedragVoorlopig
          else        isnull(OspBetaaldBedragDefinitief,0) + isnull(OspBetaaldBedragVoorlopig,0)
        end)
    BetaaldBedrag,
    ValutaOmrekenen(OspValNummer, BetaaldBedrag, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) BetaaldBedragBasis,
    AnalVal.ValNummer AnalyseValNummer,
    AnalVal.ValCode   AnalyseValCode,
    //nav wens 15850 OspVervalDatum vervangen door (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif)
    sum(if @PeilDatum <= (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @dagen1                                                                                         then ValutaOmrekenen(OspValNummer, case @SoortBoeking when 0 then OspFactuurBedragDefinitief  - OspBetaaldBedragDefinitief when 1 then OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig else OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig - OspBetaaldBedragDefinitief - OspBetaaldBedragVoorlopig end, AnalVal.ValNummer, @HulpBjGid, @Pernr, 2) else 0 endif) Kolom1,
    sum(if @PeilDatum between (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @dagen1+1 and (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @dagen2 then ValutaOmrekenen(OspValNummer, case @SoortBoeking when 0 then OspFactuurBedragDefinitief  - OspBetaaldBedragDefinitief when 1 then OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig else OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig - OspBetaaldBedragDefinitief - OspBetaaldBedragVoorlopig end, AnalVal.ValNummer, @HulpBjGid, @Pernr, 2) else 0 endif) Kolom2,
    sum(if @PeilDatum between (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @dagen2+1 and (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @dagen3 then ValutaOmrekenen(OspValNummer, case @SoortBoeking when 0 then OspFactuurBedragDefinitief  - OspBetaaldBedragDefinitief when 1 then OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig else OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig - OspBetaaldBedragDefinitief - OspBetaaldBedragVoorlopig end, AnalVal.ValNummer, @HulpBjGid, @Pernr, 2) else 0 endif) Kolom3,
    sum(if @PeilDatum >  (if @OuderdomObv=0 then OspVervalDatum else OspFactuurDatum endif) + @dagen3                                                                                         then ValutaOmrekenen(OspValNummer, case @SoortBoeking when 0 then OspFactuurBedragDefinitief  - OspBetaaldBedragDefinitief when 1 then OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig else OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig - OspBetaaldBedragDefinitief - OspBetaaldBedragVoorlopig end, AnalVal.ValNummer, @HulpBjGid, @Pernr, 2) else 0 endif) Kolom4,
    ValutaOmrekenen(AnalVal.ValNummer, Kolom1 + Kolom2 + Kolom3 + Kolom4, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) BasisCumKolom1,
    ValutaOmrekenen(AnalVal.ValNummer,          Kolom2 + Kolom3 + Kolom4, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) BasisCumKolom2,
    ValutaOmrekenen(AnalVal.ValNummer,                   Kolom3 + Kolom4, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) BasisCumKolom3,
    ValutaOmrekenen(AnalVal.ValNummer,                            Kolom4, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) BasisCumKolom4,
    sum(if @PeilDatum - OspVervalDatum <= 0 then                          ValutaOmrekenen(OspValNummer, case @SoortBoeking when 0 then isnull(OspFactuurBedragDefinitief,0) - isnull(OspBetaaldBedragDefinitief,0) when 1 then isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragVoorlopig,0) else isnull(OspFactuurBedragDefinitief,0) + isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragDefinitief,0) - isnull(OspBetaaldBedragVoorlopig,0) end, AnalVal.ValNummer, @HulpBjGid, @Pernr, 2) endif) VervallenBedrag,
    sum(if @PeilDatum - OspVervalDatum <= 0 then                          ValutaOmrekenen(OspValNummer, case @SoortBoeking when 0 then isnull(OspFactuurBedragDefinitief,0) - isnull(OspBetaaldBedragDefinitief,0) when 1 then isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragVoorlopig,0) else isnull(OspFactuurBedragDefinitief,0) + isnull(OspFactuurBedragVoorlopig,0) - isnull(OspBetaaldBedragDefinitief,0) - isnull(OspBetaaldBedragVoorlopig,0) end, @@BasisValutaNummer, @HulpBjGid, @Pernr, 2) endif) VervallenBedragBasis,
    FactuurBedrag - BetaaldBedrag           OpenstaandBedrag,
    FactuurBedragBasis - BetaaldBedragBasis OpenstaandBedragBasis
  from
    tabOpenstaandePost
    inner join tabRekeningschema on (RksGid  = OspRksGid)
    inner join tabValuta TotVal  on (TotVal.ValNummer = OspValNummer)
    inner join tabValuta AnalVal on (AnalVal.ValNummer = if @AnalyseValNummer is null then TotVal.ValNummer else @AnalyseValNummer endif)
    left outer join tabBetalingsconditie on OspBtcNummer = BtcNummer
  where DefaultSoort = @DebOfCred and                                          //Alleen de deb. of juist alleen de cred.
      ((@SelecterenOp = 0 and RksInvoer   between @VanNaw and @TotNaw) or    //Alleen naw binnen de range
       (@SelecterenOp = 1 and RksZoekCode between @VanNaw and @TotNaw)) and
      ((Repeat(' ',40-OspFactuurnummer_Lengte)+Trim(OspFactuurnummer)) between @VanFactuur and @TotFactuur) and //die binnen de factuurrange liggen
      (OspVervalDatum between @VanVervalDatum and @TotVervalDatum) //en binnen de vervaldatum-range liggen
      and   (
           (@BtcSelecterenOp = 0 and OspBtcNummer between @VanBtcNummer and @TotBtcNummer)
        or (@BtcSelecterenOp = 1 and BtcOms between @VanBtcOms and @TotBtcOms)
        or (@InclusiefPostenZonderBtc = 1 and OspBtcNummer is null)  )
      and OspBjGid=@BjGid                                          //en op dit boekjaar betrekking hebben
      and sign(case @SoortBoeking
               when 0 then OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief
               when 1 then OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig
               when 2 then (OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig) + (OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief)
               end) in (1, -1) //dus <> 0

      //Creditnota of niet
      and
      (@SoortOpdracht <> 2 or
       (@SoortOpdracht = 2 and
        (case @SoortBoeking
         when 0 then OspFactuurBedragDefinitief
         when 1 then OspFactuurBedragVoorlopig
         when 2 then OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig
         end
        )< 0
       )
      )

      //Bellijst-verhaal!!
      //JV, 23 aug 06: nav bug 4820: alle osps afdrukken bij bellijst
  group by
    OspValNummer, TotVal.ValNummer, TotVal.ValCode, TotVal.OmsValuta, AnalVal.ValNummer, AnalVal.ValCode
  order by TotVal.ValNummer;


end;

//gewone totalen voor openstaande posten
//call rapOspVal( 0, 6, 0, 0, '', '99999999', '        ', '99999999', '20000101', '20001231', 2, 2, '2000-01-01', null, 30, 30, 30, null)

//gewone totalen voor bellijst
//call rapOspVal( 1, 6, 0, 0, '', '99999999', '        ', '99999999', '20000101', '20001231', 2, 2, '2000-01-01', 0, 30, 30, 30, null)


create or replace procedure rapPerSaldiPeriode( in @RksValNummer        Integer,  // indien niet uitsplitsen kostenplaats of drager dan valnummer van de hoofdrekening
                                     in @RksGID              Integer,  // @RksGid blijft leeg indien er niet opgesplitst wordt.
                                     in @RksNummer           nchar(10),  // in geval debiteuren of crediteuren niet Uisplitsen dan b.v '12Deb' of '17Cred'.
                                     in @VlsNulSaldi         smallint, // 0 = geen nulsaldi, 1 = aleen waarop geboekt, 2 = alle rekeningen
                                     in @VlsAfdrukBasis      smallint, // 0 = definitief, 1 = voorlopig, 2 = beide.
                                     in @VanPer              Integer,
                                     in @TotPer              Integer,
                                     in @BjGid               Integer,
                                     in @defaultsoort        smallint, // 6 = debiteuren, 7 = crediteuren, rest doet er niet toe
                                     in @vls_debUitsplitsen  smallint, // 0 = Nee, 1 = Ja
                                     in @vls_credUitsplitsen smallint, // 0 = Nee, 1 = Ja
                                     in @KstPUitsplitsen     smallint, // 0 = Nee, 1 = Ja
                                     in @KstpGid             Integer,
                                     in @KstDUitsplitsen     smallint, // 0 = Nee, 1 = Ja
                                     in @KstdGid             Integer
                                   )

result (Periode           nchar(7),
        SaldoDebetBasis   numeric(15,2),
        SaldoCreditBasis  numeric(15,2),
        SaldoDebetValuta  numeric(15,2),
        SaldoCreditValuta numeric(15,2),
        SaldoDebetAantal  numeric(15,2),
        SaldoCreditAantal numeric(15,2)
        )

begin
//  declare @BjGid integer;
  declare @NietAllesNul integer;
  declare @BeginTekst long nvarchar;

  declare local temporary table tmpPerSaldi( tmpPerNr Integer,
                                             tmpPeriode nchar(7),
                                             tmpSaldoDebetBasis numeric(15,2),
                                             tmpSaldoCreditBasis numeric(15,2),
                                             tmpSaldoDebetValuta numeric(15,2),
                                             tmpSaldoCreditValuta numeric(15,2),
                                             tmpSaldoDebetAantal numeric(15,2),
                                             tmpSaldoCreditAantal numeric(15,2),
                                             tmpNulTester smallint
                                           ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapPerSaldiPeriode > @RksValNummer='+string(@RksValNummer)+', @VanPer='+string(@VanPer)+', @TotPer='+string(@TotPer)+', @RksGID='+string(@RksGID);
  //call TraceBegin(@@ErrorTextProcedure);

  set @BeginTekst = _U('Begin');

  insert into  tmpPerSaldi( tmpPerNr, tmpPeriode,
                            tmpSaldoDebetBasis, tmpSaldoCreditBasis,
                            tmpSaldoDebetValuta, tmpSaldoCreditValuta,
                            tmpSaldoDebetAantal, tmpSaldoCreditAantal,
                            tmpNulTester )

  select
    Pernr,
    (if (Pernr = 0) then _@BeginTekst else String(Pernr) endif)tmpPeriode,
    isNull(SUM (case @VlsAfdrukBasis when 0 then SaldoDebetBasisDefinitief  when 1 then SaldoDebetBasisVoorlopig  when 2 then (SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief)   else 0 end ),0) tmpSaldoDebetBasis,
    isNull(SUM (case @VlsAfdrukBasis when 0 then SaldoCreditBasisDefinitief when 1 then SaldoCreditBasisVoorlopig when 2 then (SaldoCreditBasisVoorlopig + SaldoCreditBasisDefinitief) else 0 end )                                                                                                             ,0) tmpSaldoCreditBasis,
    isNull((if @RksGid is not null then (SUM (ValutaOmrekenen (RekSaldoValNummer,(case @VlsAfdrukBasis when 0 then SaldoDebetValutaDefinitief  when 1 then SaldoDebetValutaVoorlopig  when 2 then (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief  ) else 0 end), @RksValNummer, @BjGID, PerNr, 2)))else tmpSaldoDebetBasis  endif),0) tmpSaldoDebetValuta,
    isNull((if @RksGid is not null then (SUM (ValutaOmrekenen (RekSaldoValNummer,(case @VlsAfdrukBasis when 0 then SaldoCreditValutaDefinitief when 1 then SaldoCreditValutaVoorlopig when 2 then (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief) else 0 end), @RksValNummer, @BjGID, PerNr, 2))) else tmpSaldoCreditBasis endif),0) tmpSaldoCreditValuta,
    isNull(SUM (case @VlsAfdrukBasis when 0 then SaldoDebetAantalDefinitief  when 1 then SaldoDebetAantalVoorlopig  when 2 then (SaldoDebetAantalVoorlopig + SaldoDebetAantalDefinitief)   else 0 end ),0) tmpSaldoDebetAantal,
    isNull(SUM (case @VlsAfdrukBasis when 0 then SaldoCreditAantalDefinitief when 1 then SaldoCreditAantalVoorlopig when 2 then (SaldoCreditAantalVoorlopig + SaldoCreditAantalDefinitief) else 0 end ),0) tmpSaldoCreditAantal,
    (if (      (isNull(tmpSaldoDebetBasis,  0)<>0)
           and (isNull(tmpSaldoCreditBasis, 0)<>0)
           and (isNull(tmpSaldoDebetValuta, 0)<>0)
           and (isNull(tmpSaldoCreditValuta,0)<>0)
           and (isNull(tmpSaldoDebetAantal, 0)<>0)
           and (isNull(tmpSaldoCreditAantal,0)<>0)
         )then 1
     else 0
     endif)tmpNulTester   // 0 als inderdaad alles nul is

  from   tabPeriode
         left outer join tabRekeningSaldo  on ((rekSaldoPerNr = PerNr)  and (RekSaldoBjGID = @BjGid))
         left outer join tabrekeningschema on (rksgid = @rksgid)
  where  PerNr between @VanPer and @TotPer
         and PerBjGid = @BjGid
         and ((
              (rekSaldoRksGid = @RksGid  //Betreffende rekening
               or (@RksGid is null and rekSaldoRksGid in (select rksGid from tabRekeningSchema where defaultsoort =@defaultsoort)) //alle debiteuren/crediteuren indien geen rekening
              )
             and (( @defaultsoort = defaultsoort or (@defaultsoort=6 and @vls_debUitsplitsen=1 ))  //Debiteuren uitsplitsen?
                    or (@defaultsoort = defaultsoort or (@defaultsoort=7 and @vls_credUitsplitsen=1)))    //Crediteuren uitsplitsen?
             )
             or (rekSaldoRksGid in (select rksGid //Kostenplaatsen/dragers?
                                    from   tabRekeningSchema
                                    where  RksNummer=@RksNummer //Betreffende rekening
                                           and (( @KstPUitsplitsen=1 and rksKstpGid = @KstpGid )  //kostenplaatsen uitgesplitst
                                                  or ( @KstPUitsplitsen=0) )                             //Kostenplaatsen niet uitgesplitst
                                           and (( @KstDUitsplitsen=1 and rksKstdGid = @KstdGid ) //Kostendragers uitgeplitst
                                                  or ( @KstDUitsplitsen=0) )                            //Kostendragers niet uitgesplitst
                                   )
                )
              or ReksaldoRksGid is null)

  group by PerNr, tmpPeriode;//, tmpNulTester;  //, Nulsaldo

  create index idx_tmpPerNr on tmpPerSaldi( tmpPerNr);

  if @VlsNulSaldi = 1 then   //geen nulsaldi
    select sum(tmpNulTester)  into @NietAllesNul from tmpPerSaldi ;
  else
    select 1 into @NietAllesNul
  end if;

  //call TraceEind(@@ErrorTextProcedure);
  select tmpPernr, tmpPeriode,
         tmpSaldoDebetBasis, tmpSaldoCreditBasis,
         tmpSaldoDebetValuta, tmpSaldoCreditValuta,
         tmpSaldoDebetAantal, tmpSaldoCreditAantal


  from tmpPerSaldi

  where @NietAllesNul <> 0

  order by tmpPerNr;



end;


// call rapPerSaldiPeriode(0,null, '12', 0, 2, 0, 12, 1,6,0,1,1,1,1,1)
// @RksValNummer, @RksGID, @RksNummer, @VlsNulSaldi, @VlsAfdrukBasis, @VanPer, @TotPer, @BjCode, @defaultsoort,
// @vls_debUitsplitsen, @vls_credUitsplitsen smallint, @KstPUitsplitsen, @KstpGid, @KstDUitsplitsen, @KstdGid


//$Workfile: rapProjectStructuurReleaseLock.sp $ $Revision: 1 $ $Modtime: 24-01-07 9:13 $'

if exists (select 1 from sys.sysProcedure where proc_name='rapProjectStructuurReleaseLock') then
  drop procedure rapProjectStructuurReleaseLock;
end if;

//lock vrijgeven
create procedure rapProjectStructuurReleaseLock(in @LockNummer integer)
begin
  set @@ErrorTextProcedure = 'rapProjectStructuurReleaseLock';

  call LockReleaseOnId(@@spid, @@LoginTime , 1, 'prnProjectStructuur', @LockNummer);
end;


//$Workfile: rapProjectStructuurSetLock.sp $ $Revision: 1 $ $Modtime: 24-01-07 9:13 $'

if exists (select 1 from sys.sysProcedure where proc_name='rapProjectStructuurSetLock') then
  drop procedure rapProjectStructuurSetLock;
end if;

//set lock
create procedure rapProjectStructuurSetLock(out @LockNummer integer)
begin
  declare @Result       integer;

  set @@ErrorTextProcedure = 'rapProjectStructuurSetLock';

  LocknummerLoop:
  LOOP
    call RandomNumber2(@LockNummer);
    call LockSetOnId(@@spid, @@LoginTime , 1, 'prnProjectStructuur', @LockNummer, @Result);
    IF @Result = 0 THEN
      LEAVE LocknummerLoop;
    END IF;
  END LOOP LocknummerLoop;

end;


// Denk bij het aanpassen van deze procs eraan dat de procs behorende bij grootboekmutaties en kostenplaatsen-/kostendragermutaties grote
// overeenkomsten vertonen met de procs behorende bij saldoanalyse
create or replace procedure rapSaldoAnalyseMaster(
in @BjGid             integer,
in @Selectie          smallint,
in @VanRks            nchar(40),
in @TotRks	          nchar(40),
in @VanPerNr          integer,
in @TotPerNr          integer,
in @SoortBoeking      smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @NulsaldiBepalingObv smallint, // 0 = Alleen bedrag, 1 = Bedrag en aantal
in @NulSaldiAfdrukken integer,
in @RekeningSoorten   nchar(10),
in @OrderBy           integer,  // Sorteren op: 0 = Nummer, 1 = Zoekcode
in @Ascending         integer)

result (
  RksGid                 integer,
  RekeningZoekCode       nchar(10),
  RekeningNummer         nchar(28),
  RekeningNaam           nchar(40),
  RekeningValNummer      integer,
  RekeningValCode        nchar(3))

begin
  // Deze tabel bevat de gewenste rekeningen
  declare local temporary table tmpRekeningen(
    tmpRksGid       integer,
    tmpRksZoekCode  nchar(10),
    tmpRksInvoer    nchar(28),
    tmpRksNaam      nchar(40),
    tmpRksValNummer integer,
    tmpRksValCode   nchar(3),
    tmpEindSaldo    numeric(15,2),
    tmpEindAantal   numeric(15,2)
  ) on commit preserve rows;

  //call traceBegin('rapSaldoAnalyseMaster (@BjGid='+string(@BjGid)+', @Selectie='+string(@Selectie)+', @VanRks='+string(@VanRks)+', @TotRks='+string(@TotRks)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', @NulSaldiAfdrukken='+string(@NulSaldiAfdrukken)+', ...');
  //call trace('..., @RekeningSoorten='+string(@RekeningSoorten)+', @OrderBy='+string(@OrderBy)+', @Ascending='+string(@Ascending)+')');

    // Tijdelijke tabel vullen
  insert into tmpRekeningen(tmpRksGid, tmpRksZoekCode, tmpRksInvoer, tmpRksNaam, tmpRksValNummer, tmpRksValCode, tmpEindSaldo, tmpEindAantal)
  select
    RksGid,
    RksZoekCode,
    RksInvoer,
    RksNaam,
    RksValNummer,
    (select ValCode from tabValuta where (ValNummer = RksValNummer)) RksValCode,

    // Bepalen van eindsaldo per grootboekrekening. Dit is nodig voor de instelling in het voorloopscherm (Nulsaldi afdrukken)
    // Indien gekozen voor Nee (0)                                          -> alle grootboekrekeningen waarvan EindSaldo <> null en EindSaldo <> 0 <=> isnull(EindSaldo, 0) <> 0
    // Indien gekozen voor Ja, maar alleen rekeningen waarop geboekt is (1) -> alle grootboekrekeningen waarvan EindSaldo <> null                   <=> EindSaldo is not null
    // Indien gekozen voor Ja, alle rekeningen (2)                          -> alle grootboekrekeningen
    cast(if @NulSaldiAfdrukken <> 2 then
      sum((if @@BasisValutaNummer = JrValNummer then JrValutaBedrag else ValutaOmrekenen(JrValNummer, JrValutaBedrag, @@BasisValutaNummer, @BjGid, @TotPerNr, 2) endif) * (if IsCreditBoeking = 1 then -1 else 1 endif))
    endif as numeric(15,2)) tmpEindSaldo,
    sum(Aantal * (if IsCreditBoeking = 1 then -1 else 1 endif)) as tmpEindAantal

  from tabRekeningSchema
       left outer join tabJournaalRegel
       on (JrRksGid = RksGid and
           JrBjGid = @BjGid and
           JrPerNr between @VanPerNr and @TotPerNr and
           ( (@SoortBoeking = 0 and RegelNummer is not null) or
             (@SoortBoeking = 1 and RegelNummer is null) or
             (@SoortBoeking = 2)
           ) and
           JrReferentie_Lengte > 0
          )
  where ( (@Selectie = 1 and RksInvoer   between @VanRks and @TotRks) or
          (@Selectie = 2 and RksZoekCode between @VanRks and @TotRks)
        ) and
        @RekeningSoorten like '%'+string(DefaultSoort)+'%'
  group by
    RksGid,
    RksZoekCode,
    RksInvoer,
    RksNaam,
    RksValNummer,
    RksValCode
  having
    ( (@NulSaldiAfdrukken = 0 and (isnull(tmpEindSaldo, 0) <> 0 or (@NulsaldiBepalingObv = 1 and isnull(tmpEindAantal, 0) <> 0))) or
    //( (@NulSaldiAfdrukken = 0 and isnull(tmpEindSaldo, 0) <> 0 and tmpEindAantal <> 0) or
      (@NulSaldiAfdrukken = 1 and (tmpEindSaldo is not null or (@NulsaldiBepalingObv = 1 and tmpEindAantal is not null))) or
      (@NulSaldiAfdrukken = 2)
    );

  //select * from tmpRekeningen;

  //call traceEind('rapSaldoAnalyseMaster');

  select
    tmpRksGid,
    tmpRksZoekCode,
    tmpRksInvoer,
    tmpRksNaam,
    tmpRksValNummer,
    tmpRksValCode
  from
    tmpRekeningen
  order by
    if @Ascending = 0 and @OrderBy = 0 then tmpRksInvoer endif desc, // Sorteren op nummer
    if @Ascending = 1 and @OrderBy = 0 then tmpRksInvoer endif,
    if @Ascending = 0 and @OrderBy = 1 then tmpRksZoekCode endif desc, // Sorteren op zoekcode
    if @Ascending = 1 and @OrderBy = 1 then tmpRksZoekCode endif,
    // Altijd nasorteren op basis van nummer
    if @Ascending = 0 then tmpRksInvoer endif desc,
    if @Ascending = 1 then tmpRksInvoer endif;



end;

// call rapSaldoAnalyseMaster(1, 1, '000001', '1299999', 0, 12, 2, 0, 0, '01234567', 0, 1)


create or replace procedure rapSaldoAnalyseMutaties(
in @RksGid                          integer,
in @RekeningValNummer               integer,
in @ReferentieValNummer             integer,  // Nodig voor rapport voor Saldo-analyse. Valuta van referentie is valuta waarin het eerst geboekt is op dit referentienummer
in @BjGid                           integer,
in @Referentie                      nchar(40), // Referentie meegeven voor rapport Saldo-analyse
in @VanPerNr                        integer,
in @TotPerNr                        integer,
in @SoortBoeking                    smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @BedragenAfdrukkenIn             integer,  // 0 = Valuta van grootboekrekening, 1 = boekvaluta, 2 = basisvaluta, 3 = andere valuta
in @BedragenAfdrukkenExtraValNummer integer,  // Indien gevuld, bedragen afdrukken in de extra ingegeven valuta
in @SaldoAfdrukkenIn                integer,  // 0=Default-valuta van tegenrekening van eerste dagboek van boekingsgang, 2=basisvaluta, 3=extra valuta, 4=valuta van referentie
in @SaldoAfdrukkenExtraValNummer    integer,  // Indien gevuld, ook saldo afdrukken in de extra ingegeven valuta.
in @OrderBy                         integer,  // Sorteren op: 0 = referentie, 1 = boekdatum, 2 = journaalregel
in @Ascending                       integer)

result (
  DagboekCode                    nchar(10),
  OmsDagboek                     nchar(40),
  BoekgangNummer                 integer,
  RegelNummer                    integer,
  StukVolgnr                     integer,
  BoekStukVolgNummer             nchar(14),
  JpNummer                       integer,
  OmsJournaalPost                nchar(40),
  Boekdatum                      date,
  JrBoekdatum                    date,
  JpPerNr                        integer,
  BeginBalans                    smallint,
  OmsJournaalRegel               nchar(40),
  JrReferentie                   nchar(40),
  IsCreditBoeking                smallint,
  RglBoekValNummer               integer,
  RglBoekValCode                 nchar(3),
  AfdrukValNummerBedragen        integer,       // Valuta waarin de bedragen dienen te worden afgedrukt
  AfdrukValCodeBedragen          nchar(3),
  JrBoekValBedrag                numeric(15,2),
  BoekValBoekingBedragD          numeric(15,2),
  BoekValBoekingBedragC          numeric(15,2),
  BoekValBoekingSaldo            numeric(15,2),
  BoekValRegelTotaalD            numeric(15,2),
  BoekValRegelTotaalC            numeric(15,2),
  BoekValRegelSaldo              numeric(15,2),
  JrBasisValBedrag               numeric(15,2),
  BasisValBoekingBedragD         numeric(15,2),
  BasisValBoekingBedragC         numeric(15,2),
  BasisValBoekingSaldo           numeric(15,2),
  BasisValRegelTotaalD           numeric(15,2),
  BasisValRegelTotaalC           numeric(15,2),
  BasisValRegelSaldo             numeric(15,2),
  JrFactuurdatum                 date,
  JrVervalDatum                  date,
  JrBetalingsKenmerk             nchar(24),
  HulpRekSoort                   smallint,
  HulpRekeningZoekCode           nchar(10),
  HulpRekeningInvoer             nchar(28),
  HulpRekeningNaam               nchar(40),
  HulpRekBtwCode                 integer,
  HulpRekIsCreditBoeking         smallint,
  HulpRekBoekValNummer           integer,
  HulpRekBoekValCode             nchar(3),
  HulpRekAfdrukValNummerBedragen integer,
  HulpRekAfdrukValCodeBedragen   nchar(3),
  HulpRekBoekValBedrag           numeric(15,2),
  HulpRekBasisValBedrag          numeric(15,2),
  AfdrukValBoekingCumBedragD     numeric(15,2),
  AfdrukValBoekingCumBedragC     numeric(15,2),
  AfdrukValBoekingCumSaldo       numeric(15,2),
  AfdrukValRegelCumSaldo         numeric(15,2),
  Aantal                         numeric(15,2))

begin
  //tijdelijke tabel aanmaken
  declare local temporary table tmpExtraVelden(
    tmpGid                        integer default autoincrement,
    tmpJrGid                      integer,
    tmpBoekgangNummer             integer,
    tmpBasisValBoekingBedrag      numeric(15,2),
    tmpBasisValHulpRekBedrag      numeric(15,2),
    tmpBasisValBoekingBedragD     numeric(15,2),
    tmpBasisValBoekingBedragC     numeric(15,2),
    tmpBasisValBoekingSaldo       numeric(15,2),
    tmpBasisValRegelTotaalD       numeric(15,2),
    tmpBasisValRegelTotaalC       numeric(15,2),
    tmpBasisValRegelSaldo         numeric(15,2),
    tmpBoekValBoekingBedrag       numeric(15,2),
    tmpBoekValHulpRekBedrag       numeric(15,2),
    tmpJournaalValHulpRekBedrag   numeric(15,2),
    tmpBoekValBoekingBedragD      numeric(15,2),
    tmpBoekValBoekingBedragC      numeric(15,2),
    tmpBoekValBoekingSaldo        numeric(15,2),
    tmpBoekValRegelTotaalD        numeric(15,2),
    tmpBoekValRegelTotaalC        numeric(15,2),
    tmpBoekValRegelSaldo          numeric(15,2),
    tmpAfdrukValBoekingCumBedragD numeric(15,2),
    tmpAfdrukValBoekingCumBedragC numeric(15,2),
    tmpAfdrukValBoekingCumSaldo   numeric(15,2),
    tmpAfdrukValRegelCumSaldo     numeric(15,2)
  ) on commit preserve rows;

  // Voorkomen van afrondingsverschillen en tegelijkertijd de valutacodes ophalen
  declare @NumDeciBasisVal               integer;
  declare @RekeningValCode               nchar(3);
  declare @NumDeciRekeningVal            integer;
  declare @NumDeciReferentieVal          integer;
  declare @BedragenAfdrukkenExtraValCode nchar(3);
  declare @NumDeciExtraValSaldo          integer;

  //call traceBegin('rapSaldoAnalyseMutaties (@RksGid='+string(@RksGid)+', @RekeningValNummer='+string(@RekeningValNummer)+', @ReferentieValNummer='+string(@ReferentieValNummer)+', @BjGid='+string(@BjGid)+', @Referentie='+string(@Referentie)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call trace('..., @BedragenAfdrukkenIn='+string(@BedragenAfdrukkenIn)+', @BedragenAfdrukkenExtraValNummer='+string(@BedragenAfdrukkenExtraValNummer)+', @SaldoAfdrukkenIn='+string(@SaldoAfdrukkenIn)+', @SaldoAfdrukkenExtraValNummer='+string(@SaldoAfdrukkenExtraValNummer)+', ...');
  //call trace('..., @OrderBy='+string(@OrderBy)+', @Ascending='+string(@Ascending)+')');

  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;
  select ValCode, if DecimalenBoeking <> 0 then 2 else 0 endif into @RekeningValCode, @NumDeciRekeningVal from tabValuta where ValNummer = @RekeningValNummer;
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciReferentieVal from tabValuta where ValNummer = @ReferentieValNummer;
  if @BedragenAfdrukkenIn = 3 then
    select ValCode into @BedragenAfdrukkenExtraValCode from tabValuta where ValNummer = @BedragenAfdrukkenExtraValNummer;
  end if;
  if @SaldoAfdrukkenIn = 3 then // Alleen gegevens ophalen indien ook daadwerkelijk een extra valuta is ingevoerd
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValSaldo  from tabValuta where ValNummer = @SaldoAfdrukkenExtraValNummer;
  end if;

  insert into tmpExtraVelden(tmpJrGid,                      tmpBoekgangNummer,
                             tmpBasisValBoekingBedrag,      tmpBasisValHulpRekBedrag,                                   tmpBasisValBoekingBedragD,   tmpBasisValBoekingBedragC, tmpBasisValBoekingSaldo, tmpBasisValRegelTotaalD, tmpBasisValRegelTotaalC, tmpBasisValRegelSaldo,
                             tmpBoekValBoekingBedrag,       tmpBoekValHulpRekBedrag,       tmpJournaalValHulpRekBedrag, tmpBoekValBoekingBedragD,    tmpBoekValBoekingBedragC,  tmpBoekValBoekingSaldo,  tmpBoekValRegelTotaalD,  tmpBoekValRegelTotaalC,  tmpBoekValRegelSaldo,
                             tmpAfdrukValBoekingCumBedragD, tmpAfdrukValBoekingCumBedragC,
                             tmpAfdrukValBoekingCumSaldo,   tmpAfdrukValRegelCumSaldo
                            )

  select JrGid,
         BoekGangNummer tmpBoekgangNummer,

         // ---------- Basisvaluta ----------
         round(JrBasisBedrag, @NumDeciBasisVal)      tmpBasisValBoekingBedrag,
         round(HulpRekBasisBedrag, @NumDeciBasisVal) tmpBasisValHulpRekBedrag,
         // Uitsplitsing van geboekt bedrag naar boekzijde
         if IsCreditBoeking = 0 then tmpBasisValBoekingBedrag endif tmpBasisValBoekingBedragD,
         if IsCreditBoeking = 1 then tmpBasisValBoekingBedrag endif tmpBasisValBoekingBedragC,
         JrBasisBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) tmpBasisValBoekingSaldo,
         // Uitsplitsing van regeltotaal (=geboekt bedrag + geboekt bedrag op de hulprekening) naar boekzijde
         if HulpRekIsCredit is not null and HulpRekIsCredit = 0 then isnull(tmpBasisValBoekingBedragD, 0) + tmpBasisValHulpRekBedrag else tmpBasisValBoekingBedragD endif tmpBasisValRegelTotaalD,
         if HulpRekIsCredit is not null and HulpRekIsCredit = 1 then isnull(tmpBasisValBoekingBedragC, 0) + tmpBasisValHulpRekBedrag else tmpBasisValBoekingBedragC endif tmpBasisValRegelTotaalC,
         isnull(tmpBasisValRegelTotaalD, 0) - isnull(tmpBasisValRegelTotaalC, 0) tmpBasisValRegelSaldo,

         // ---------- Boekvaluta ----------
         round(JrValutaBedrag, if ValRek.DecimalenBoeking <> 0 then 2 else 0 endif) tmpBoekValBoekingBedrag,
         round(HulpRekValutaBedrag, (select if ValHulpRek.DecimalenBoeking <> 0 then 2 else 0 endif from tabHulpRekening HulpRekening inner join tabValuta ValHulpRek on (ValHulpRek.ValNummer = HulpRekening.HulpRekValNummer) where HulpRekening.HulpRekJrGid=JrGid) ) tmpBoekValHulpRekBedrag,
         round(HulpRekBedragInJrValnummer, if ValRek.DecimalenBoeking <> 0 then 2 else 0 endif) tmpJournaalValHulpRekBedrag,
         // Uitsplitsing van geboekt bedrag naar boekzijde
         if IsCreditBoeking = 0 then tmpBoekValBoekingBedrag endif tmpBoekValBoekingBedragD,
         if IsCreditBoeking = 1 then tmpBoekValBoekingBedrag endif tmpBoekValBoekingBedragC,
         JrValutaBedrag * (if IsCreditBoeking = 1 then -1 else 1 endif) tmpBoekValBoekingSaldo,
         // Uitsplitsing van regeltotaal (=geboekt bedrag + geboekt bedrag op de hulprekening) naar boekzijde
         if HulpRekValNummer is not null and HulpRekIsCredit = 0 then isnull(tmpBoekValBoekingBedragD, 0) + tmpJournaalValHulpRekBedrag else tmpBoekValBoekingBedragD endif tmpBoekValRegelTotaalD,
         if HulpRekValNummer is not null and HulpRekIsCredit = 1 then isnull(tmpBoekValBoekingBedragC, 0) + tmpJournaalValHulpRekBedrag else tmpBoekValBoekingBedragC endif tmpBoekValRegelTotaalC,
         isnull(tmpBoekValRegelTotaalD, 0) - isnull(tmpBoekValRegelTotaalC, 0) tmpBoekValRegelSaldo,

         // ---------- Afdrukvaluta voor saldo ----------
         // Deze velden zijn nodig zodat de cumulatieven via het somcomponent enigzins corresponderen met de boekbedragen
         // Indien de valuta-instelling voor de bedragen gelijk is aan die voor de saldi dan kan het in de dm berekende veld (voor bedragen) worden genomen
         if (not((@SaldoAfdrukkenIn <> 3 and @SaldoAfdrukkenIn = @BedragenAfdrukkenIn) or (@SaldoAfdrukkenIn = 3 and isnull(@SaldoAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) or (@SaldoAfdrukkenIn = 4)) then
           case @SaldoAfdrukkenIn
             when 0 then round(if JrValNummer = @RekeningValNummer            or tmpBoekValBoekingBedragD = 0 then tmpBoekValBoekingBedragD else ValutaOmrekenen(JrValNummer, tmpBoekValBoekingBedragD, @RekeningValNummer, @BjGid, @TotPerNr, 2)            endif, @NumDeciRekeningVal)
             when 3 then round(if JrValNummer = @SaldoAfdrukkenExtraValNummer or tmpBoekValBoekingBedragD = 0 then tmpBoekValBoekingBedragD else ValutaOmrekenen(JrValNummer, tmpBoekValBoekingBedragD, @SaldoAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif, @NumDeciExtraValSaldo)
             when 4 then round(if JrValNummer = @ReferentieValNummer          or tmpBoekValBoekingBedragD = 0 then tmpBoekValBoekingBedragD else ValutaOmrekenen(JrValNummer, tmpBoekValBoekingBedragD, @ReferentieValNummer, @BjGid, @TotPerNr, 2)          endif, @NumDeciReferentieVal)
             when 2 then tmpBasisValBoekingBedragD
           end
         endif tmpAfdrukValBoekingCumBedragD,
         if (not((@SaldoAfdrukkenIn <> 3 and @SaldoAfdrukkenIn = @BedragenAfdrukkenIn) or (@SaldoAfdrukkenIn = 3 and isnull(@SaldoAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) or (@SaldoAfdrukkenIn = 4)) then
           case @SaldoAfdrukkenIn
             when 0 then round(if JrValNummer = @RekeningValNummer            or tmpBoekValBoekingBedragC = 0 then tmpBoekValBoekingBedragC else ValutaOmrekenen(JrValNummer, tmpBoekValBoekingBedragC, @RekeningValNummer, @BjGid, @TotPerNr, 2)            endif, @NumDeciRekeningVal)
             when 3 then round(if JrValNummer = @SaldoAfdrukkenExtraValNummer or tmpBoekValBoekingBedragC = 0 then tmpBoekValBoekingBedragC else ValutaOmrekenen(JrValNummer, tmpBoekValBoekingBedragC, @SaldoAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif, @NumDeciExtraValSaldo)
             when 4 then round(if JrValNummer = @ReferentieValNummer          or tmpBoekValBoekingBedragC = 0 then tmpBoekValBoekingBedragC else ValutaOmrekenen(JrValNummer, tmpBoekValBoekingBedragC, @ReferentieValNummer, @BjGid, @TotPerNr, 2)          endif, @NumDeciReferentieVal)
             when 2 then tmpBasisValBoekingBedragC
           end
         endif tmpAfdrukValBoekingCumBedragC,

         if (not((@SaldoAfdrukkenIn <> 3 and @SaldoAfdrukkenIn = @BedragenAfdrukkenIn) or (@SaldoAfdrukkenIn = 3 and isnull(@SaldoAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) or (@SaldoAfdrukkenIn = 4)) then
           isnull(tmpAfdrukValBoekingCumBedragD, 0) - isnull(tmpAfdrukValBoekingCumBedragC, 0)
         endif tmpAfdrukValBoekingCumSaldo,

         if (not((@SaldoAfdrukkenIn <> 3 and @SaldoAfdrukkenIn = @BedragenAfdrukkenIn) or (@SaldoAfdrukkenIn = 3 and isnull(@SaldoAfdrukkenExtraValNummer, 0) = isnull(@BedragenAfdrukkenExtraValNummer, 0))) or (@SaldoAfdrukkenIn = 4)) then
           case @SaldoAfdrukkenIn
             when 0 then
               if HulpRekValNummer is not null then
                 tmpAfdrukValBoekingCumSaldo + round(if HulpRekValNummer = @RekeningValNummer            or tmpBoekValHulpRekBedrag = 0 then tmpBoekValHulpRekBedrag else ValutaOmrekenen(HulpRekValNummer, tmpBoekValHulpRekBedrag, @RekeningValNummer,            @BjGid, @TotPerNr, 2) endif, @NumDeciRekeningVal)   * (if HulpRekIsCredit = 1 then -1 else 1 endif)
               else
                 tmpAfdrukValBoekingCumSaldo
               endif
             when 2 then tmpBasisValRegelSaldo
             when 3 then
               if HulpRekValNummer is not null then
                 tmpAfdrukValBoekingCumSaldo + round(if HulpRekValNummer = @SaldoAfdrukkenExtraValNummer or tmpBoekValHulpRekBedrag = 0 then tmpBoekValHulpRekBedrag else ValutaOmrekenen(HulpRekValNummer, tmpBoekValHulpRekBedrag, @SaldoAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif, @NumDeciExtraValSaldo) * (if HulpRekIsCredit = 1 then -1 else 1 endif)
               else
                 tmpAfdrukValBoekingCumSaldo
               endif
             when 4 then
               if HulpRekValNummer is not null then
                 tmpAfdrukValBoekingCumSaldo + round(if HulpRekValNummer = @ReferentieValNummer          or tmpBoekValHulpRekBedrag = 0 then tmpBoekValHulpRekBedrag else ValutaOmrekenen(HulpRekValNummer, tmpBoekValHulpRekBedrag, @ReferentieValNummer,          @BjGid, @TotPerNr, 2) endif, @NumDeciReferentieVal) * (if HulpRekIsCredit = 1 then -1 else 1 endif)
               else
                 tmpAfdrukValBoekingCumSaldo
               endif
           end
         endif tmpAfdrukValRegelCumSaldo
    from
      tabBoekingsgang
      inner join tabJournaalPost      on (jpBoekgangGid = BoekgangGid)
      inner join tabJournaalRegel     on (JrJpGid = JpGid)
      inner join tabValuta ValRek     on (ValRek.ValNummer = JrValNummer)
      left outer join tabHulpRekening on (HulpRekJrGid = JrGid)
    where
      JpBjGid = @BjGid and
      JrBjGid = @BjGid and
      ( (@SoortBoeking = 0 and IsBoekGangDefinitief = 1) or
        (@SoortBoeking = 1 and IsBoekGangDefinitief = 0) or
        (@SoortBoeking = 2) ) and
      JrPerNr between @VanPerNr and @TotPerNr and
      JrRksGid = @RksGid and
      JrReferentie = @Referentie and JrReferentie_Lengte = length(@Referentie)

    order by
      if @Ascending = 0 and @OrderBy = 0 then Repeat(' ', 40 - JrReferentie_Lengte) + JrReferentie endif desc,
      if @Ascending = 1 and @OrderBy = 0 then Repeat(' ', 40 - JrReferentie_Lengte) + JrReferentie endif,
      if @Ascending = 0 and @OrderBy = 1 then JrBoekdatum endif desc,
      if @Ascending = 1 and @OrderBy = 1 then JrBoekdatum endif,
      // Rapport voor saldo-anlyse sorteert binnen de referentie op boekdatum oplopend
      JrBoekdatum,
      // Eerst definitieve mutaties, dan voorlopige mutaties
      if @Ascending = 0 then IsBoekGangDefinitief endif,
      if @Ascending = 1 then IsBoekGangDefinitief endif desc,
      // Altijd nasorteren op basis van het 'regelnummer'
      if @Ascending = 0 then RegelNummer endif desc,
      if @Ascending = 1 then RegelNummer endif,
      if @Ascending = 0 then BoekgangNummer endif desc,
      if @Ascending = 1 then BoekgangNummer endif,
      if @Ascending = 0 then JpNummer endif desc,
      if @Ascending = 1 then JpNummer endif,
      if @Ascending = 0 then JrNummer endif desc,
      if @Ascending = 1 then JrNummer endif;


  //call trace('Stap 1');

  create index idx_tmpGid on tmpExtraVelden (tmpGid);

  //call traceEind('rapSaldoAnalyseMutaties');

  select
    JrDgbCode DagboekCode,
    (select OmsDagboek from tabDagboek where JpDgbGid = DgbGid) OmsDagboek,
    tmpBoekGangNummer BoekGangNummer,
    RegelNummer,
    StukVolgnr,
    string(JrBoekstukNummer) + '.' + right('000' + string(StukVolgNr), 3) BoekStukVolgNummer,
    JpNummer,
    OmsJournaalPost,
    Boekdatum,
    JrBoekdatum,
    JrPerNr,
    if JrPerNr = 0 then 1 else 0 endif BeginBalans,
    OmsJournaalRegel,
    JrReferentie,
    IsCreditBoeking,
    JrValNummer RglBoekValNummer,
    JrValCode RglBoekValCode,
    case @BedragenAfdrukkenIn
      when 0 then @RekeningValNummer
      when 1 then RglBoekValNummer
      when 2 then @@BasisValutanummer
      when 3 then @BedragenAfdrukkenExtraValNummer
    end AfdrukValNummerBedragen,
    case @BedragenAfdrukkenIn
      when 0 then @RekeningValCode
      when 1 then RglBoekValCode
      when 2 then @@BasisValutaCode
      when 3 then @BedragenAfdrukkenExtraValCode
    end AfdrukValCodeBedragen,

    tmpBoekValBoekingBedrag JrBoekValBedrag,
    tmpBoekValBoekingBedragD BoekValBoekingBedragD,
    tmpBoekValBoekingBedragC BoekValBoekingBedragC,
    tmpBoekValBoekingSaldo BoekValBoekingSaldo,
    tmpBoekValRegelTotaalD BoekValRegelTotaalD,
    tmpBoekValRegelTotaalC BoekValRegelTotaalC,
    tmpBoekValRegelSaldo BoekValRegelSaldo,

    tmpBasisValBoekingBedrag JrBasisValBedrag,
    tmpBasisValBoekingBedragD BasisValBoekingBedragD,
    tmpBasisValBoekingBedragC BasisValBoekingBedragC,
    tmpBasisValBoekingSaldo BasisValBoekingSaldo,
    tmpBasisValRegelTotaalD BasisValRegelTotaalD,
    tmpBasisValRegelTotaalC BasisValRegelTotaalC,
    tmpBasisValRegelSaldo BasisValRegelSaldo,

    JrFactuurDatum,
    JrVervalDatum,
    JrBetalingsKenmerk,
    HulpRekSoort,
    RksZoekCode HulpRekeningZoekCode,
    RksInvoer   HulpRekeningInvoer,
    RksNaam     HulpRekeningNaam,
    HulpRekBtwCode,
    HulpRekIsCredit HulpRekIsCreditBoeking,
    HulpRekValNummer HulpRekBoekValNummer,
    (select ValCode from tabValuta where ValNummer = HulpRekBoekValNummer) HulpRekBoekValCode,
    if HulpRekBoekValNummer is not null then
      case @BedragenAfdrukkenIn
        when 0 then @RekeningValNummer
        when 1 then HulpRekBoekValNummer
        when 2 then @@BasisValutanummer
        when 3 then @BedragenAfdrukkenExtraValNummer
      end
    endif HulpRekAfdrukValNummerBedragen,
    if HulpRekBoekValNummer is not null then
      case @BedragenAfdrukkenIn
        when 0 then @RekeningValCode
        when 1 then HulpRekBoekValCode
        when 2 then @@BasisValutaCode
        when 3 then @BedragenAfdrukkenExtraValCode
      end
    endif HulpRekAfdrukValCodeBedragen,
    tmpBoekValHulpRekBedrag      HulpRekBoekValBedrag,
    tmpBasisValHulpRekBedrag     HulpRekBasisValBedrag,
    tmpAfdrukValBoekingCumBedragD AfdrukValBoekingCumBedragD,
    tmpAfdrukValBoekingCumBedragC AfdrukValBoekingCumBedragC,
    tmpAfdrukValBoekingCumSaldo AfdrukValBoekingCumSaldo,
    tmpAfdrukValRegelCumSaldo AfdrukValRegelCumSaldo,
    // Indien het geboekt aantal-veld een 0 bevat er van uit gaan dat er NIET geboekt is
    if Aantal <> 0 then Aantal endif
  from
    tmpExtraVelden
    inner join tabJournaalregel on (JrGid=tmpJrGid)
    inner join tabJournaalPost  on (JpGid = JrJpGid)
    left outer join (tabHulpRekening inner join tabRekeningschema on (RksGid = HulpRekRksGid)) on (HulpRekJrGid = JrGid)
  order by
    tmpGid;


end;

// call rapSaldoAnalyseMutaties(1, 0, 0, 1, '', 0, 12, 2, 1, 0, 3, 3, 2, 1);


create or replace procedure rapSaldoAnalyseReferenties(
in @RksGid                      integer,
in @BjGid                       integer,
in @VanPerNr                    integer,
in @TotPerNr                    integer,
in @SoortBoeking                smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @NulsaldiBepalingObv         smallint, // 0 = Alleen bedrag, 1 = Bedrag en aantal
in @NulSaldiReferentieAfdrukken integer,  // 0 = Nee, 1 = Ja
in @Ascending                   smallint)

result (
  AantalMutaties      integer,
  Referentie          nchar(40),
  ReferentieValNummer integer,
  ReferentieValCode   nchar(3),
  EindSaldo           numeric(15,2))

begin
  //call traceBegin('rapSaldoAnalyseReferenties (@RksGid='+string(@RksGid)+', @BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', @NulSaldiReferentieAfdrukken='+string(@NulSaldiReferentieAfdrukken)+', @Ascending='+string(@Ascending)+')');

  //call traceEind('rapSaldoAnalyseReferenties');
  select
    if isnull(count(*), 0) > 1 then 1 else 0 endif AantalMutaties,
    JrReferentie Referentie,
    ReferentieValNummer,
    (select ValCode from tabValuta where ValNummer = ReferentieValNummer) ReferentieValCode,
    cast(if @NulSaldiReferentieAfdrukken = 0 then
      sum((if ReferentieValNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, JrValutaBedrag, ReferentieValNummer, @BjGid, @TotPerNr, 2) endif)
          * (if IsCreditBoeking = 1 then -1 else 1 endif))
    endif as numeric(15,2)) EindSaldo,
    sum(Aantal * (if IsCreditBoeking = 1 then -1 else 1 endif)) as EindAantal
  from
    tabJournaalRegel,
    (select RegelBinnen.JrReferentie, RegelBinnen.JrReferentie_Lengte, Min(JrValNummer)
     from
       tabJournaalRegel RegelBinnen
     where
       RegelBinnen.JrBjGid = @BjGid and
       RegelBinnen.JrPerNr between @VanPerNr and @TotPerNr and
       RegelBinnen.JrRksGid = @RksGid and
       ( (@SoortBoeking = 0 and RegelBinnen.RegelNummer is not null) or
         (@SoortBoeking = 1 and RegelBinnen.RegelNummer is null) or
         (@SoortBoeking = 2)
       )
     group by RegelBinnen.JrReferentie, RegelBinnen.JrReferentie_Lengte
    )  as Binnen (BinnenReferentie, BinnenReferentie_Lengte, ReferentieValNummer)
  where
    BinnenReferentie = Referentie and BinnenReferentie_Lengte = JrReferentie_Lengte and
    JrBjGid = @BjGid and
    JrPerNr between @VanPerNr and @TotPerNr and
    JrRksGid = @RksGid and
    ( (@SoortBoeking = 0 and RegelNummer is not null) or
      (@SoortBoeking = 1 and RegelNummer is null) or
      (@SoortBoeking = 2)
    ) and
    JrReferentie_Lengte > 0
  group by
    JrReferentie, JrReferentie_Lengte, ReferentieValNummer
  having
//    ( (@NulSaldiReferentieAfdrukken = 0 and isnull(EindSaldo, 0) <> 0 and isnull(EindAantal,0) <> 0) or
    ( (@NulSaldiReferentieAfdrukken = 0 and (isnull(EindSaldo, 0) <> 0 or (@NulsaldiBepalingObv = 1 and isnull(EindAantal, 0) <> 0))) or
      (@NulSaldiReferentieAfdrukken = 1)
    )
  order by
    if @Ascending=0 then Repeat(' ', 40 - JrReferentie_Lengte) + JrReferentie endif desc,
    if @Ascending=1 then Repeat(' ', 40 - JrReferentie_Lengte) + JrReferentie endif;



end;

// call rapSaldoAnalyseReferenties(13, 1, 0, 12, 2, 1, 0, 1)


create or replace procedure rapSaldoAnalyseTotalenPerRekening(
in @RksGid                                    integer,
in @RekeningValNummer                         integer,
in @BjGid                                     integer,
in @VanPerNr                                  integer,
in @TotPerNr                                  integer,
in @SoortBoeking                              smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @NulSaldiReferentieAfdrukken               integer,  // 0 = Nee, 1 = Ja
in @SaldoAfdrukkenIn                          integer,  // 0 = valuta van grootboekrekening,                 2 = basisvaluta, 3 = andere valuta
in @SaldoAfdrukkenExtraValNummer              integer,  // Indien gevuld, saldo afdrukken in de extra ingegeven valuta
in @TotalenPerRekeningAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta

result (
  TotaalDBasisVal      numeric(15,2),
  TotaalCBasisVal      numeric(15,2),
  SaldoBasisVal        numeric(15,2),
  TotaalDAantal        numeric(15,2),
  TotaalCAantal        numeric(15,2),
  SaldoAantal          numeric(15,2),
  TotaalDRekeningVal   numeric(15,2),
  TotaalCRekeningVal   numeric(15,2),
  SaldoRekeningVal     numeric(15,2),
  TotaalDExtraVal      numeric(15,2),
  TotaalCExtraVal      numeric(15,2),
  SaldoExtraVal        numeric(15,2),
  TotaalDAfdrukVal     numeric(15,2),
  TotaalCAfdrukVal     numeric(15,2),
  SaldoAfdrukVal       numeric(15,2)
  )

begin
  //Tussentabel die gevuld wordt met een subset van tabJournaalRegels. Deze tabel wordt gebruikt ivm performance
  declare local temporary table tmpJournaalRegels(
    tmpJrReferentie        nchar(40),
    tmpJrValNummer         integer,
    tmpJrValutaBedrag      numeric(15,2),
    tmpJrNaarValNummer     integer
  ) on commit preserve rows;

  // Deze tabel bevat de gewenste referenties
  declare local temporary table tmpReferenties(
    tmpReferentie          nchar(40),
    tmpEindSaldo           numeric(15,2)
  ) on commit preserve rows;

  // Ophalen van het aantal decimalen waarin de valuta dient te worden verwerkt
  declare @NumDeciRekeningVal     integer;
  declare @NumDeciBasisVal        integer;
  declare @NumDeciExtraValTotalen integer;
  declare @NumDeciExtraValSaldo   integer;

  //call traceBegin('rapSaldoAnalyseTotalenPerRekening (@RksGid='+string(@RksGid)+', @RekeningValNummer='+string(@RekeningValNummer)+', @BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', @NulSaldiReferentieAfdrukken='+string(@NulSaldiReferentieAfdrukken)+', ...');
  //call trace('..., @SaldoAfdrukkenIn='+string(@SaldoAfdrukkenIn)+', @SaldoAfdrukkenExtraValNummer='+string(@SaldoAfdrukkenExtraValNummer)+', @TotalenPerRekeningAfdrukkenExtraValNummer='+string(@TotalenPerRekeningAfdrukkenExtraValNummer)+')');


  // Indien er sprake is van verdichting, is de valuta van de rekening gelijk aan de basisvaluta
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciRekeningVal from tabValuta where ValNummer = @RekeningValNummer;
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal    from tabValuta where ValNummer = @@BasisValutaNummer;
  if @TotalenPerRekeningAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenPerRekeningAfdrukkenExtraValNummer;
  end if;
  if @SaldoAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValSaldo from tabValuta where ValNummer = @SaldoAfdrukkenExtraValNummer;
  end if;

  //Ivm performance issues vullen we de tijdelijk tabel met een subset van het jouraal en gaan daar vervolgens mee aan de slag
  insert into tmpJournaalRegels(tmpJrReferentie, tmpJrValNummer, tmpJrValutaBedrag)
  select JrReferentie, JrValNummer, sum(if IsCreditBoeking = 1 then -JrValutaBedrag else JrValutaBedrag endif) Bedrag
  from
    tabJournaalRegel
  where
    JrBjGid = @BjGid and
    JrPerNr between @VanPerNr and @TotPerNr and
    JrRksGid = @RksGid and
    ( (@SoortBoeking = 0 and RegelNummer is not null) or
      (@SoortBoeking = 1 and RegelNummer is null) or
      (@SoortBoeking = 2)
    ) and
    JrReferentie_Lengte > 0
  group by JrReferentie, JrValNummer
  having Bedrag <> 0;

  create unique index idx_tmpJrRegels on tmpJournaalRegels(tmpJrReferentie, tmpJrValNummer);

  //Bepalen per referentie in welke valuta we gaan testen of het totaal bedrag dat geboekt is op een bepaalde referentie 0 is
  update tmpJournaalRegels
  set    tmpJrNaarValNummer = (select min(a.tmpJrValNummer) from tmpJournaalRegels a where a.tmpJrReferentie = tmpJournaalRegels.tmpJrReferentie);

  //Nu die referenties overnemen waarvan het saldo ongelijk aan 0 is of alle referenties als we ook nulsaldi willen afdrukken
  insert into tmpReferenties (tmpReferentie, tmpEindSaldo)
  select tmpJrReferentie, sum(if tmpJrValNummer = tmpJrNaarValNummer then tmpJrValutaBedrag else ValutaOmrekenen(tmpJrValNummer, tmpJrValutaBedrag, tmpJrNaarValNummer, @BjGid, @TotPerNr, 2) endif) Bedrag
  from tmpJournaalRegels
  group by tmpJrReferentie
  having Bedrag <> 0 or (@NulSaldiReferentieAfdrukken = 1);

  create unique index idx_tmpReferenties on tmpReferenties(tmpReferentie);

  //call traceEind('rapSaldoAnalyseTotalenPerRekening');

  select
    // Bepaling van totaal geboekt bedrag debet/credit en saldo in de basisvaluta
    isnull(round(sum(if IsCreditBoeking = 0 then (if @@BasisValutaNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @@BasisValutaNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciBasisVal), 0) TotaalDBasisVal,
    isnull(round(sum(if IsCreditBoeking = 1 then (if @@BasisValutaNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @@BasisValutaNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciBasisVal), 0) TotaalCBasisVal,
    TotaalDBasisVal - TotaalCBasisVal SaldoBasisVal,

    // Bepaling van totaal geboekt bedrag debet/credit en saldo aantal
    isnull(sum(if IsCreditBoeking = 0 then Aantal endif), 0) TotaalDAantal,
    isnull(sum(if IsCreditBoeking = 1 then Aantal endif), 0) TotaalCAantal,
    TotaalDAantal - TotaalCAantal SaldoAantal,

    // Bepaling van totaal geboekt bedrag debet/credit en saldo in de valuta van de grootboekrekening
    isnull(round(sum(if IsCreditBoeking = 0 then (if @RekeningValNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @RekeningValNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciRekeningVal), 0) TotaalDRekeningVal,
    isnull(round(sum(if IsCreditBoeking = 1 then (if @RekeningValNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @RekeningValNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciRekeningVal), 0) TotaalCRekeningVal,
    TotaalDRekeningVal - TotaalCRekeningVal SaldoRekeningVal,

    // Bepaling van totaal geboekt bedrag debet/credit en saldo in de eventuele extra ingegeven valuta voor de totalen per rekening.
    isnull(round(sum(if IsCreditBoeking = 0 then (if @TotalenPerRekeningAfdrukkenExtraValNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @TotalenPerRekeningAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciExtraValTotalen), 0) TotaalDExtraVal,
    isnull(round(sum(if IsCreditBoeking = 1 then (if @TotalenPerRekeningAfdrukkenExtraValNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @TotalenPerRekeningAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciExtraValTotalen), 0) TotaalCExtraVal,
    TotaalDExtraVal - TotaalCExtraVal SaldoExtraVal,

    // Bepaling van totaal geboekt bedrag debet/credit en saldo in de afdrukvaluta voor het saldo
    isnull((case @SaldoAfdrukkenIn
              when 0 then TotaalDRekeningVal
              when 2 then TotaalDBasisVal
              when 3 then round(sum(if IsCreditBoeking = 0 then (if @SaldoAfdrukkenExtraValNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @SaldoAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciExtraValSaldo)
            end
           ), 0) TotaalDAfdrukVal,
    isnull((case @SaldoAfdrukkenIn
              when 0 then TotaalCRekeningVal
              when 2 then TotaalCBasisVal
              when 3 then round(sum(if IsCreditBoeking = 1 then (if @SaldoAfdrukkenExtraValNummer = JrValNummer or JrValutaBedrag = 0 then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @SaldoAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciExtraValSaldo)
            end
           ), 0) TotaalCAfdrukVal,
    TotaalDAfdrukVal - TotaalCAfdrukVal SaldoAfdrukVal
  from
    tabJournaalRegel
    inner join tmpReferenties on (tmpReferentie = JrReferentie)
    inner join tabValuta      on (ValNummer     = JrValNummer)
  where
    JrBjGid = @BjGid and
    JrRksGid = @RksGid and
    ( (@SoortBoeking = 0 and RegelNummer is not null) or
      (@SoortBoeking = 1 and RegelNummer is null) or
      (@SoortBoeking = 2) ) and
    JrPerNr between @VanPerNr and @TotPerNr;


end;

// call rapSaldoAnalyseTotalenPerRekening(1, 1, 1, 2, 2, 2, 0, 0, 0, 0)


create or replace procedure rapSaldoAnalyseTotalenPerValuta(
in @BjGid                                   integer,
in @VanPerNr                                integer,
in @TotPerNr                                integer,
in @SoortBoeking                            smallint, // 0 = Definitief, 1 = voorlopig, 2 = beide
in @Selectie     	                          integer,  // Selecteren op: 1 = nummer, 2 = zoekcode
in @VanRks	                                nchar(40),
in @TotRks 	                                nchar(40),
in @RekeningSoorten                         nchar(10),
in @TotalenPerValutaAfdrukkenExtraValNummer integer)  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta

result (
  BoekValutaNummer       integer,
  BoekValutaCode         nchar(3),
  BoekValutaOmschrijving nchar(40),
  TotaalDBasisVal        numeric(15,2),
  TotaalCBasisVal        numeric(15,2),
  SaldoBasisVal          numeric(15,2),
  TotaalDBoekVal         numeric(15,2),
  TotaalCBoekVal         numeric(15,2),
  SaldoBoekVal           numeric(15,2),
  TotaalDExtraVal        numeric(15,2),
  TotaalCExtraVal        numeric(15,2),
  SaldoExtraVal          numeric(15,2))

begin
  // Voorkomen van afrondingsverschillen
  declare @NumDeciBasisVal          integer;
  declare @NumDeciExtraValTotalen    integer;

  //call traceBegin('rapSaldoAnalyseTotalenPerValuta (@BjGid='+string(@BjGid)+', @VanPerNr='+string(@VanPerNr)+', @TotPerNr='+string(@TotPerNr)+', @SoortBoeking='+string(@SoortBoeking)+', ...');
  //call trace('..., @Selectie='+string(@Selectie)+', @VanRks='+string(@VanRks)+', @TotRks='+string(@TotRks)+', @RekeningSoorten='+string(@RekeningSoorten)+', @TotalenPerValutaAfdrukkenExtraValNummer='+string(@TotalenPerValutaAfdrukkenExtraValNummer)+')');

  if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciExtraValTotalen from tabValuta where ValNummer = @TotalenPerValutaAfdrukkenExtraValNummer;
  end if;
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeciBasisVal from tabValuta where ValNummer = @@BasisValutaNummer;

  //call traceEind('rapSaldoAnalyseTotalenPerValuta');

  select
    JrValNummer BoekValutaNummer,
    ValCode BoekValutaCode,
    OmsValuta BoekValutaOmschrijving,

    isnull(sum(round((if IsCreditBoeking = 0 then (if @@BasisValutaNummer = JrValNummer then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @@BasisValutaNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciBasisVal)), 0) TotaalDBasisVal,
    isnull(sum(round((if IsCreditBoeking = 1 then (if @@BasisValutaNummer = JrValNummer then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @@BasisValutaNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciBasisVal)), 0) TotaalCBasisVal,
    TotaalDBasisVal - TotaalCBasisVal,

    isnull(sum(round((if IsCreditBoeking = 0 then JrValutaBedrag endif), if DecimalenBoeking <> 0 then 2 else 0 endif)), 0) TotaalDBoekVal,
    isnull(sum(round((if IsCreditBoeking = 1 then JrValutaBedrag endif), if DecimalenBoeking <> 0 then 2 else 0 endif)), 0) TotaalCBoekVal,
    TotaalDBoekVal - TotaalCBoekVal,

    if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
      isnull(sum(round((if IsCreditBoeking = 0 then (if @TotalenPerValutaAfdrukkenExtraValNummer = JrValNummer then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @TotalenPerValutaAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciExtraValTotalen)), 0)
    endif TotaalDExtraVal,
    if @TotalenPerValutaAfdrukkenExtraValNummer is not null then
      isnull(sum(round((if IsCreditBoeking = 1 then (if @TotalenPerValutaAfdrukkenExtraValNummer = JrValNummer then JrValutaBedrag else ValutaOmrekenen(JrValNummer, round(JrValutaBedrag, if DecimalenBoeking <> 0 then 2 else 0 endif), @TotalenPerValutaAfdrukkenExtraValNummer, @BjGid, @TotPerNr, 2) endif) endif), @NumDeciExtraValTotalen)), 0)
    endif TotaalCExtraVal,
    TotaalDExtraVal - TotaalCExtraVal

  from
    tabJournaalRegel
    inner join tabRekeningSchema on (RksGid = JrRksGid)
    inner join tabValuta on (ValNummer = BoekValutaNummer)
  where
    JrBjGid = @BjGid and
    JrPerNr between @VanPerNr and @TotPerNr and
    ( (@Selectie = 1 and RksInvoer   between @VanRks and @TotRks) or
      (@Selectie = 2 and RksZoekCode between @VanRks and @TotRks)
    ) and
    (@RekeningSoorten like '%'+string(DefaultSoort)+'%') and
    ( (@SoortBoeking = 0 and RegelNummer is not null) or
      (@SoortBoeking = 1 and RegelNummer is null) or
      (@SoortBoeking = 2)
    ) and
    JrReferentie_Lengte > 0
  group by
    BoekValutaNummer,
    BoekValutaCode,
    BoekValutaOmschrijving
  order by
    if BoekValutaNummer = @@BasisValutaNummer then 0 else 1 endif,
    BoekValutaCode;

end;

// call rapSaldoAnalyseTotalenPerValuta(1, 0, 12, 0, 1, '000001', '000001', '01234567', 0)


create or replace procedure rapScontroBalans(
//  @SoortBalans      smallint, //0=liggend (zonder dubbele strepen), 1=staand (met dubbele strepen)
 in  @Zijde            smallint, //0 = Verlies, 1=Winst, 2=Debet, 3=Credit
 in  @BjGid            Integer,
 in  @VanPernr         smallint,
 in  @TotPernr         smallint,
 in  @SelecteerOp      smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
 in  @VanRks           nchar(40), //van nummer/zoekcode/naam
 in  @TotRks           nchar(40), //t/m nummer/zoekcode/naam
 in  @BalCode          integer , //balanscode
 in  @VanRubParSub     nchar(11) , //van rub+par+sub; elementen die leeg zijn
 in  @TotRubParSub     nchar(11) , //van rub+par+sub; elementen die leeg zijn -> uitvullen met 3 spaties
 in  @SoortBoeking     smallint, //0=definitief, 1=voorlopig, 2=beide
 in  @OokNulSaldi      smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
 in  @Specificatie     smallint, //0=Grootboekrekening, 1=subparagraaf, 2=paragraaf, 3=rubriek, 4=conform balans
 in  @BalansInValuta   integer,  //Valutanummer waarin balans moet worden afgedrukt
 in  @TotalenInValuta  integer,  //Valutanummer voor subtotalen
 in  @RekZonderBalCode smallint) //Rekening zonder balanscode ook afdrukken (0=nee 1=ja)

result (tmpGid integer, tmpRubParSub nchar(11), tmpRksInvoer nchar(28), tmpRksNaam nchar(40), tmpValNummer integer,
        tmpValcode nchar(3), tmpBedrag numeric(15,2), tmpBalGid integer, tmpBalVerdicht smallint,
        tmpBerekendeZijde smallint, tmpRegelSoort integer,
        OptelStreepBoven smallint, DubbeleStreepOnder smallint, LegeRegelOnder smallint)

begin
  declare @tmpGid integer;
  declare @Teller smallint;
  declare @BalansValCode nchar(3);
  declare @TotaalValCode nchar(3);
  declare @AantalDecimalen integer;
  declare @Dummy nchar(30);
  declare @RegelSoort integer;
  declare @VorigeRegelSoort integer;
  declare @VorigeRksInvoer nchar(28);
  declare @RksInvoer nchar(28);
  declare @OptelStreepBoven integer;
  declare @VorigeOptelStreepBoven integer;
  declare @IsolationLevel         smallint;

  declare @RubriekTekst         long nvarchar;
  declare @ParagraafTekst       long nvarchar;
  declare @SubParagraafTekst    long nvarchar;
  declare @GeenRubParSubTekst   long nvarchar;
  declare @DirectGekoppeldTekst long nvarchar;

  declare local temporary table tmpBalans(
     tmpGid                integer default AutoIncrement,
     tmpRubParSub          nchar(11),
     tmpRksInvoer          nchar(28),
     tmpRksNaam            nchar(40) default '',
     tmpRksGid             integer,
     tmpValNummer          integer,
     tmpValcode            nchar(3) default '',
     tmpHulpVoorlBedrag    numeric(15,2),
     tmpHulpDefBedrag      numeric(15,2),
     tmpHulpBedrag         numeric(15,2),
     tmpBedrag             numeric(15,2),
     tmpBalGid             integer,
     tmpBalVerdicht        smallint default 0,
     tmpBerekendeZijde     smallint,  //compute (if (tmpAfdrukZijde = 0 or (tmpAfdrukZijde=2 and (VorigDebet + HuidigDebet >= VorigCredit + HuidigCredit))) then 0 else 1 endif),
     tmpRegelSoort         integer,   // LET OP   900=totaal generaal!!!
     tmpSortering          nchar(39),
     OptelStreepBoven      smallint default 0,
     DubbeleStreepOnder    smallint default 0,
     LegeRegelOnder        smallint default 0,
     tmpHulpSortering      integer
  ) on commit preserve rows;

  declare cursor_tmpSorteringVolgorde cursor for
    select tmpGid, tmpRegelSoort
    from tmpBalans
    order by tmpSortering
  for update;

  declare cursor_tmpSorteringLegeRegels cursor for
    select tmpRegelSoort, tmpRksInvoer, OptelStreepBoven
    from tmpBalans
    order by tmpSortering desc
  for update;

  set @@ErrorTextProcedure = 'rapScontroBalans > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Zijde = ' +string(@Zijde)+', @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+', @VanRks='+string(@VanRks)+', @TotRks='+string(@TotRks)+', @BalCode='+string(@BalCode)+', @VanRubParSub='+string(@VanRubParSub)+', @TotRubParSub='+string(@TotRubParSub)+', @SoortBoeking='+string(@SoortBoeking));
  //call trace('rapScontroBalans > @OokNulSaldi='+string(@OokNulSaldi)+', @Specificatie='+string(@Specificatie)+', @BalansInValuta='+string(@BalansInValuta)+', @TotalenInValuta='+string(@TotalenInValuta)+', @RekZonderBalCode='+string(@RekZonderBalCode));

  //Versnellen van de volgende processen
  Create index idx_tmpBalansSoort     on tmpBalans (tmpregelsoort);
  //Create index idx_tmpBalansSortering on tmpBalans (tmpSortering); (helaas; deze werkt niet...... geeft een foutmelding bij eerstvolgende select)
  create index idx_tmpBal1 on tmpBalans (tmpRksInvoer);

  set @@ErrorTextProcedure = 'rapScontroBalans > Ervoor: @VanRubParSub=['+@VanRubParSub+'], @TotRubParSub=['+@TotRubParSub+']';
  //call Trace(@@ErrorTextProcedure);

  if isnull(trim(@TotRubParSub) ,'') = '' then
    set @TotRubParSub = '999.999.999'
  else
    set @TotRubParSub = left(trim(@TotRubParSub)+'.999.999.999', 11);
  end if;
  set @@ErrorTextProcedure = 'rapScontroBalans > Erna  : @VanRubParSub=['+@VanRubParSub+'], @TotRubParSub=['+@TotRubParSub+']';
  //call Trace(@@ErrorTextProcedure);

  select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;
  set @AantalDecimalen = 3;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 2';
  //call Trace(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  insert into tmpBalans (tmpRegelSoort, tmpSortering, tmpRksInvoer, tmpRksNaam, tmpRksGid, tmpValNummer, tmpValcode, tmpRubParSub, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpBedrag, tmpBalVerdicht)
  select   1,
           isnull(left(RubParSub + '.   .   .   ', 11),'===')+RksInvoer,
           RksInvoer,
           RksNaam,
           RksGid,
           @BalansInValuta,
           @BalansValCode,
           IsNull(RubParSub, '   '),
           IsNull(sum(SaldoDebetBasisVoorlopig)  - sum(SaldoCreditBasisVoorlopig),0)  tmpHulpVoorlBedrag,
           IsNull(sum(SaldoDebetBasisDefinitief) - sum(SaldoCreditBasisDefinitief),0) tmpHulpDefBedrag,
           ValutaOmrekenen(@@BasisValutanummer,
                           IsNull((if @SoortBoeking = 0 then tmpHulpDefBedrag else if @SoortBoeking = 1 then tmpHulpVoorlBedrag else tmpHulpDefBedrag + tmpHulpVoorlBedrag endif endif), 0),
                           @BalansInValuta, @BjGid, @TotPernr, 2) test,
          (if @Zijde = 1 or @Zijde = 3 then -1 else 1 endif) *  test tmpBedrag,
          (if ((@Specificatie = 1) or (@Specificatie = 2) or (@Specificatie = 3)) then 1 else 0 endif)
  from     tabRekeningschema left outer join (tabBalansCodeRekening inner join tabBalansCodeDetail on (BlRekBlGid = BlGid)) on (BlRksGid = RksGid and DetailBlCode = @BalCode)
           left outer join tabRekeningSaldo on (RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
  where   ((RubParSub between @VanRubParSub and @TotRubParSub) or
           (@RekZonderBalCode = 1 and RubParSub is null)) and
          ( (@SelecteerOp = 0 and RksInvoer   between @VanRks and @TotRks ) or
            (@SelecteerOp = 1 and RksZoekcode between @VanRks and @TotRks ) or
            (@SelecteerOp = 2 and RksNaam     between @VanRks and @TotRks ) )
  group by RksGid, RksInvoer, RksNaam, RubParSub;

  set temporary option isolation_level = @IsolationLevel;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 3';
  //call Trace(@@ErrorTextProcedure);

  case @Zijde
  when 0 then
    delete tmpBalans from tabRekeningschema where tmpRksGid = RksGid and not (DefaultSoort in (3, 4, 5)       and (AfdrukZijde = 0 or (AfdrukZijde = 2 and tmpHulpBedrag >= 0)));
  when 1 then
    delete tmpBalans from tabRekeningschema where tmpRksGid = RksGid and not (DefaultSoort in (3, 4, 5)       and (AfdrukZijde = 1 or (AfdrukZijde = 2 and tmpHulpBedrag <  0)));
  when 2 then
    delete tmpBalans from tabRekeningschema where tmpRksGid = RksGid and not (DefaultSoort in (0, 1, 2, 6, 7) and (AfdrukZijde = 0 or (AfdrukZijde = 2 and tmpHulpBedrag >= 0)));
  when 3 then
    delete tmpBalans from tabRekeningschema where tmpRksGid = RksGid and not (DefaultSoort in (0, 1, 2, 6, 7) and (AfdrukZijde = 1 or (AfdrukZijde = 2 and tmpHulpBedrag <  0)));
  end case;


  if @RekZonderBalCode = 0 then
    delete tmpBalans where trim(tmpRubParSub) = '';
  end if;

  case @OokNulSaldi
  when 0 then
    delete tmpBalans where tmpBedrag = 0
  when 2 then
    delete tmpBalans where tmpRksGid not in //(select RekSaldoRksGid from tabRekeningsaldo where RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
                                   (select JrRksGid from tabJournaalRegel inner join tabJournaalpost on (JpGid = JrJpGid) inner join tabBoekingsgang on (BoekGangGID = JpBoekGangGID) where JrPerNr between @VanPerNr and @TotPerNr and JrBjGid = @BjGid and
                                   ((@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                                   (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                                   (@SoortBoeking = 2)))

  end case;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 4';
  //call Trace(@@ErrorTextProcedure);
  //Subtotalen maken volgens aantal specificatie
  //select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;

  set @RubriekTekst         = _U('Rubriek');
  set @ParagraafTekst       = _U('Paragraaf');
  set @SubParagraafTekst    = _U('Subparagraaf');
  set @GeenRubParSubTekst   = _U('(Geen rub/par/sub)');
  set @DirectGekoppeldTekst = _U('(Direct gekoppeld)');

  set @Teller = 3;
  while @Teller > 0 loop

    insert into tmpBalans (tmpRegelSoort, tmpSortering, tmpRubParSub, tmpRksInvoer, tmpRksNaam, tmpValnummer, tmpValCode,
                           tmpBedrag, tmpBalVerdicht)
    select   13-@Teller DezeRegelSoort,
             IsNull(tabBalanscodeDetail.RubParSub,'===')+'z' Sortering,
             IsNull(tabBalanscodeDetail.RubParSub,'   '),
             tabBalanscodeDetail.RubParSub HulpRksInvoer,
             if DetailBlCode is null then
               if @teller = 1 then
                 @GeenRubParSubTekst
               else
                 @DirectGekoppeldTekst
               endif
             else
               if IsNull(OmsBalansCodeDetails, '' ) = '' then
                 case DezeRegelSoort
                 when 10 then
                   @SubParagraafTekst
                 when 11 then
                   @ParagraafTekst
                 else
                   @RubriekTekst
                 end
               else
                 OmsBalansCodeDetails
               endif
             endif BalOms,
             @BalansInValuta,
             @BalansValCode,
             sum(tmpBedrag),
            (if (@Specificatie = 2 and length(IsNull(tabBalanscodeDetail.RubParSub,'   '))=11) or (@Specificatie = 3 and length(IsNull(tabBalanscodeDetail.RubParSub,'   '))>=7) then 1 else 0 endif)
    from     tmpBalans left outer join tabBalanscodeDetail on (DetailBlCode = @BalCode and RubParSub = substr(tmpRubParSub, 1, (@Teller*4)-1))
    where    length(tmpRubParSub)>=(@Teller*4)-1 and (tmpRksInvoer <> tmpRubParSub or tmpRegelSoort = 1) and ((tmpRegelSoort=1) or (tmpRegelSoort = 12-@Teller)) //HulpRksInvoer is not null
    group by HulpRksInvoer, Sortering, BalOms, BalansVerdicht;

    set @Teller = @Teller - 1;

  end loop;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 5';
  //call Trace(@@ErrorTextProcedure);

  if @Specificatie = 4 then  //Conform balans

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  DetailBlCode=@BalCode and (tmpRubParSub = RubParSub or (tmpRubParSub is null and tmpRksInvoer = RubParSub)) and trim(IsNull(tmpRubParSub,'.'))<>'';  //Alle rubparsub die '' zijn niet overschrijven, wel rubparsub die null zijn

    set @@ErrorTextProcedure = 'rapScontroBalans > Stap 5a';
    //call Trace(@@ErrorTextProcedure);

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=@BalCode and Rubriek = left(RubParSub,3) and Paragraaf = substr(RubParSub,4,3) and trim(IsNull(tmpRubParSub,'.'))<>'';

    set @@ErrorTextProcedure = 'rapScontroBalans > Stap 5b';
    //call Trace(@@ErrorTextProcedure);

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=@BalCode and Rubriek = left(RubParSub,3) and Paragraaf='' and trim(IsNull(tmpRubParSub,'.'))<>'';

  end if;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 6';
  //call Trace(@@ErrorTextProcedure);

  delete tmpBalans where tmpBalVerdicht = 1 and (tmpRegelSoort=1 or (@Specificatie<>4));

  //Als er een subparagraaf voor een rekeningregel staat van dezelfde paragraaf maar de rekening zelf valt niet in een subparagraaf, dan subparagraaf-regel tussenvoegen onder de regel
  //Hetzelfde geldt voor andere niveaus (dus 2x de lus uitvoeren: 1x voor rek. -> sub en 1x voor sub. -> par.!)
  set @Teller = 0;
  while @Teller < 2 loop
    set @@ErrorTextProcedure = 'rapScontroBalans > Stap 6a, teller='+string(@teller);
    //call Trace(@@ErrorTextProcedure);

    insert into tmpBalans (tmpRegelSoort, tmpRubParSub, tmpSortering, tmpRksNaam, tmpValNummer, tmpValcode, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpBedrag)
    select if tmpRegelsoort = 1 then 10 else tmpRegelSoort + 1 endif Ditregelsoort,
           tmpRubParSub  RubriekOfParagraafNr,
           left(RubriekOfParagraafNr+'.   .   .   ', 11)+'zz'+string(@teller) Volgorde,
           '('+
           case Ditregelsoort
           when 10 then @SubParagraafTekst
           when 11 then @ParagraafTekst
           when 12 then @RubriekTekst
           end + ' ' + if Ditregelsoort <> 10 then tmpRubParSub+'.   )' else tmpRubParSub+'.   .   )' endif,
           tmpValNummer,
           tmpValcode,
           sum(tmpHulpVoorlBedrag), sum(tmpHulpDefBedrag), sum(tmpHulpBedrag), sum(tmpBedrag)
    from   tmpBalans buiten
    where  exists (select 1
                   from   tmpBalans binnen
                   where  binnen.tmpSortering < buiten.tmpSortering and
                          binnen.tmpRubParSub like buiten.tmpRubParSub+'%' and
                          binnen.tmpRegelsoort > buiten.tmpRegelsoort) //ok, bestaat ervoor!

           and //Er bestaat geen next-dieper niveau van?
           not exists (select 1
                   from    tmpBalans binnen
                   where   binnen.tmpSortering > buiten.tmpSortering and
                           binnen.tmpRubParSub like  buiten.tmpRubParSub+'%' and
                           binnen.tmpRegelsoort = if buiten.tmpRegelsoort = 1 then 10 else buiten.tmpRegelsoort+1 endif) //bestaat niet erna!
           and tmpRubParSub is not null
    group by RubriekOfParagraafNr, tmpRubParSub, tmpRegelSoort, tmpValNummer, tmpValcode;

    //Rekeningen die direct aan een paragraaf/rubriek zijn geknoopt terwijl er ook subpar/paragrafen in de par/rubriek zijn
    insert into tmpBalans (tmpRegelSoort, tmpRubParSub, tmpSortering, tmpRksInvoer, tmpRksNaam, tmpValNummer, tmpValcode, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpBedrag, OptelstreepBoven)
    select 10+@teller Ditregelsoort,
           left(tmpRubParSub, if @teller = 1 then 3 else 7 endif) RubriekOfParagraafNr,
           left(RubriekOfParagraafNr+'.   .   .   ', 11)+'xz'+string(@teller) Volgorde,
           RubriekOfParagraafNr+' ' Invoer,
           @DirectGekoppeldTekst,
           @BalansInValuta,
           @BalansValCode,
           sum(tmpHulpVoorlBedrag),
           sum(tmpHulpDefBedrag  ),
           sum(tmpHulpBedrag     ),
           sum(tmpBedrag         ),
           1
    from   tmpBalans buiten
    where  tmpRegelsoort = 1  //11+@teller //Alleen voor paragrafen en rubrieken!
           and exists(select 1  //Er zijn rekeningen aan de rubriek/par. geknoopt
                      from tmpBalans binnen
                      where binnen.tmpRegelsoort=1   //Het zijn rekeningen
                            and binnen.tmprubparsub = RubriekOfParagraafNr) //aan deze rubriek(teller=0)/paragraaf(teller=1) geknoopt
           and exists(select 1  //Er zijn ook nog andere subpar./par. aan de rubriek of par. geknoopt
                      from tmpBalans binnen
                      where binnen.tmpRegelsoort<>1
                            and binnen.tmpRubParSub like RubriekOfParagraafNr+'.%')
           and length(tmpRubParSub) = if @teller = 1 then 3 else 7 endif
    group by length(tmpRubParSub), RubriekOfParagraafNr, Volgorde, Invoer, tmpValNummer, tmpValcode;

    set @Teller = @Teller + 1;

  end loop;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 7';
  //call Trace(@@ErrorTextProcedure);


  //Subtotalen omrekenen naar juiste valuta
  select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;
  if @BalansInValuta <> @TotalenInValuta then
    insert into tmpBalans (tmpRegelSoort, tmpSortering, tmpRksInvoer, tmpRksNaam, tmpValNummer, tmpValCode, tmpBalVerdicht, tmpBedrag)
    select   6 + tmpRegelSoort,
             tmpSortering+'z',
             tmpRksInvoer,
             tmpRksNaam,
             @TotalenInValuta,
             @TotaalValCode,
             tmpBalVerdicht,
             ValutaOmrekenen(@BalansInValuta, tmpBedrag, @TotalenInValuta, @BjGid, @TotPernr, 2)
    from     tmpBalans where tmpRegelSoort between 10 and 13;

  end if;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 8';
  //call Trace(@@ErrorTextProcedure);

  //---------- Optelstrepen zetten ----------

  //Als de vorige een ondieper niveau is (dus lager regelsoort), dan een optelstreep
  Set @VorigeRegelSoort = 999;
  Set @RegelSoort = null;

  open cursor_tmpSorteringVolgorde;
  loopVolgorde:
  loop
    Fetch next cursor_tmpSorteringVolgorde into @tmpGid, @RegelSoort;
    if sqlstate = '02000' then
      leave LoopVolgorde;
    end if;
    if (@RegelSoort > @VorigeRegelSoort) then
      update tmpBalans set OptelStreepBoven = 1 where tmpGid = @tmpGid
    //else
    //  update tmpBalans set OptelStreepBoven = 0 where tmpGid = @tmpGid;
    end if;
    set @VorigeRegelSoort=@RegelSoort;
  end loop loopVolgorde;
  close cursor_tmpSorteringVolgorde;


  //---------- Dubbele totaalstrepen zetten ----------
  update tmpBalans
  set DubbeleStreepOnder = 1
  where OptelStreepBoven <> 0
        and not (@BalansInValuta <> @TotalenInValuta and tmpValCode <> @TotaalValCode); //Alleen voor de onderste (sub)totaalregel

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 9';
  //call Trace(@@ErrorTextProcedure);
  //Alle regels waarvoor geldt dat een dieper niveau al een enkele of een dubbele streep heeft krijgt ook een dubbele streep
  set @Teller = 1; //@AantalCijfers-1;
  while @Teller <= 12 loop
    if exists( select 1 from tmpBalans where tmpRegelSoort = @teller) then
      update tmpBalans buiten
      set    DubbeleStreepOnder = 1
      where  1=(select first 1
                from tmpBalans binnen
                where (binnen.tmpRegelsoort =  1 or isnull(binnen.tmpRksInvoer,'') like isnull(buiten.tmpRksInvoer,'')+ '%') and
                      (isnull(binnen.tmpRubParSub,'') like isnull(buiten.tmpRksInvoer,'')+ '%' or isnull(binnen.tmpRksInvoer,'') like isnull(buiten.tmpRksInvoer,'')+ '%') and
                      binnen.tmpValcode = @BalansValCode and
                      binnen.tmpGid <> buiten.tmpGid
                //where ((binnen.tmpRegelsoort =  1 and isnull(binnen.tmpRubParSub,'') like isnull(buiten.tmpRksInvoer,'')+ '%') or
                //       (binnen.tmpRegelsoort <> 1 and isnull(binnen.tmpRksInvoer,'') like isnull(buiten.tmpRksInvoer,'')+ '%') and binnen.tmpValcode = @BalansValCode)
                //      and binnen.tmpGid <> buiten.tmpGid
             and (binnen.OptelStreepBoven <> 0 or binnen.DubbeleStreepOnder <> 0))
             and tmpRegelsoort <> 1
             and (@BalansInValuta = @TotalenInValuta or tmpValCode = @TotaalValCode); //Alleen voor de onderste (sub)totaalregel
    end if;
    if @teller = 1 then
      set @Teller = 10
    else
      set @Teller = @Teller + 1;
    end if;
  end loop;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 10';
  //call Trace(@@ErrorTextProcedure);
  if @BalansInValuta <> @TotalenInValuta then
    //Eventueel nog wat enkele streepjes verwijderen als op een dieper niveau toch enkele of dubbele strepen staan
    update tmpBalans buiten
    set OptelStreepBoven =
       if 1 = isnull((select first 1
               from   tmpBalans binnen
               where  ((binnen.tmpRegelsoort =  1 and isnull(binnen.tmpRubParSub,'') like isnull(buiten.tmpRksInvoer,'')+ '%') or
                       (binnen.tmpRegelsoort <> 1 and isnull(binnen.tmpRksInvoer,'') like isnull(buiten.tmpRksInvoer,'')+ '%') and binnen.tmpValcode = @BalansValCode)
                      and binnen.tmpGid <> buiten.tmpGid
                      and (binnen.OptelStreepBoven <> 0 or binnen.DubbeleStreepOnder <> 0)
              ),0) then 0 else 1 endif
    where OptelStreepBoven <> 0
          and tmpRegelsoort <> 1
          and tmpValCode = @BalansValCode; //Alleen indien saldo in zelfde valuta als balans
  end if;

  //Zet een enkele streep onderaan als er geen dubbele streep staat
  if exists(select 1 from tmpBalans   where  tmpSortering = (select max(tmpSortering) from tmpBalans) and DubbeleStreepOnder = 0) then
    insert into tmpBalans(tmpRegelSoort, tmpSortering, OptelStreepBoven)
    values((select tmpRegelSoort from tmpBalans where  tmpSortering = (select max(tmpSortering) from tmpBalans)), 'zzzzzzzzzzzzzzzzzzzzz', 1);
  end if;

  //Hulpsortering ivm. strepen bepalen
  update tmpBalans set tmpHulpSortering=number() order by tmpSortering;

  //We moeten een enkele streep, nu bepalen op welk nivo: hetzelfde als het nivo van de regel erboven
  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 11';
  //call Trace(@@ErrorTextProcedure);

  // Voor elke optelstreep die 1 is geldt: optelstreep = regelsoort van de vorige regel
  update tmpBalans tmp
  set OptelStreepBoven =
                (select binnen.tmpRegelSoort
                 from   tmpBalans binnen
                 where  binnen.tmpHulpSortering = tmp.tmpHulpSortering - 1)
  where OptelStreepBoven <> 0;

  Set @VorigeRegelSoort = 0;
  Set @RegelSoort = null;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 12';
  //call Trace(@@ErrorTextProcedure);
  //Hier bepalen we het echte niveau: 1=rekening, 2=sub, 3=par, 4=rub
  update tmpBalans tmp
  set OptelStreepBoven =
                case OptelStreepBoven
                when 1 then
                  1 //Optelstreep op rekening-niveau
                when 10 then
                  2 //Optelstreep op subparagraaf-niveau
                when 16 then
                  2 //Optelstreep op subparagraaf-niveau (andere valuta)
                when 11 then
                  3 //Optelstreep op paragraaf-niveau
                when 17 then
                  3 //Optelstreep op paragraaf-niveau (andere valuta)
                when 12 then
                  4 //Optelstreep op rubriek-niveau
                when 18 then
                  4 //Optelstreep op rubriek-niveau (andere valuta)
                else
                  0
                end
  where OptelStreepBoven <> 0;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 13';
  //call Trace(@@ErrorTextProcedure);
  //En voor de dubbele streep ook; dat is het niveau van de huidige regel
  update tmpBalans tmp
  set DubbeleStreepOnder =
                case tmpRegelSoort
                when 1 then
                  1 //Optelstreep op rekening-niveau
                when 10 then
                  2 //Optelstreep op subparagraaf-niveau
                when 16 then
                  2 //Optelstreep op subparagraaf-niveau (andere valuta)
                when 11 then
                  3 //Optelstreep op paragraaf-niveau
                when 17 then
                  3 //Optelstreep op paragraaf-niveau (andere valuta)
                when 12 then
                  4 //Optelstreep op rubriek-niveau
                when 18 then
                  4 //Optelstreep op rubriek-niveau (andere valuta)
                else
                  0
                end
  where DubbeleStreepOnder <> 0;

  Select count(1) into @regelsoort from tmpBalans;

  //Lege ruimte onder de regels: alleen als de regel erna van een ander niveau is
  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 14, Aantal records ='+String(@Regelsoort);
  //call Trace(@@ErrorTextProcedure);

  update tmpBalans buiten
  set    LegeRegelOnder = 1
  where  exists(select 1
                from   tmpBalans binnen
                where  binnen.tmpRegelsoort<> buiten.tmpRegelsoort and //Alleen als het een ander regelsoort betreft, dus geen lege regels tussen de rekeningen in
                       isnull(binnen.tmpRksInvoer,'') <> isnull(buiten.tmpRksInvoer,'') and  //Alleen als het een andere rekening/rubriek is ivm. andere valuta
                       binnen.OptelstreepBoven = 0 and                 //Als er een optelstreep volgt, dan geen lege ruimte!!
                       binnen.tmpHulpSortering = buiten.tmpHulpSortering + 1); //En natuurlijk alleen de eerstvolgende regel testen


  //---------- Einde optelstrepen zetten ----------


  insert into tmpBalans (tmpSortering, tmpRegelSoort, tmpBedrag)
    Select '', 900, Sum(tmpBedrag) from tmpBalans where tmpRegelSoort=12;

  set @@ErrorTextProcedure = 'rapScontroBalans';
  //call TraceEind(@@ErrorTextProcedure);

  select   tmpGid, tmpRubParSub, tmpRksInvoer, tmpRksNaam, tmpValNummer, tmpValcode, tmpBedrag, tmpBalGid, tmpBalVerdicht,
           tmpBerekendeZijde, tmpRegelSoort,
           OptelStreepBoven, DubbeleStreepOnder, LegeRegelOnder
  from     tmpBalans
  order by tmpSortering;
end;

//call RapScontroBalans(2, 1, 0, 12, 0, '1010', '9910', 1, '         ', '999999999', 0, 0, 0, 0, 1, 1)
//call RapScontroBalans(2, 1, 0, 12, 0, '1010', '9910', 1, '         ', '999999999', 0, 0, 0, 0, 1, 1)


create or replace procedure rapScontroBalansMetAnderJaar(
//  @SoortBalans      smallint, //0=liggend (zonder dubbele strepen), 1=staand (met dubbele strepen)
 in  @Zijde              smallint, //0 = Verlies, 1=Winst, 2=Debet, 3=Credit
 in  @BjGid              Integer,
 in  @VanPernr           smallint,
 in  @TotPernr           smallint,
 in  @SelecteerOp        smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
 in  @VanRks             nchar(40), //van nummer/zoekcode/naam
 in  @TotRks             nchar(40), //t/m nummer/zoekcode/naam
 in  @BalCode            integer , //balanscode
 in  @VanRubParSub       nchar(11) , //van rub+par+sub; elementen die leeg zijn
 in  @TotRubParSub       nchar(11) , //van rub+par+sub; elementen die leeg zijn -> uitvullen met 3 spaties
 in  @SoortBoeking       smallint, //0=definitief, 1=voorlopig, 2=beide
 in  @OokNulSaldi        smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
 in  @Specificatie       smallint, //0=Grootboekrekening, 1=subparagraaf, 2=paragraaf, 3=rubriek, 4=conform balans
 in  @BalansInValuta     integer,  //Valutanummer waarin balans moet worden afgedrukt
 in  @TotalenInValuta    integer,  //Valutanummer voor subtotalen
 in  @RekZonderBalCode   smallint, //Rekening zonder balanscode ook afdrukken (0=nee 1=ja)
 in  @AnderBjGid         Integer,  //vergelijkend boekjaargid
 in  @VanPernrAnderJaar  smallint, //van periode vergelijkend boekjaar
 in  @TotPernrAnderJaar  smallint) //T/m periode vergelijkend boekjaar

result (tmpGid integer, tmpRubParSub nchar(11), tmpRksInvoer nchar(28), tmpRksNaam nchar(40), tmpValNummer integer,
        tmpValcode nchar(3), tmpBedrag numeric(15,2), tmpBedragAnderJaar numeric(15,2),
        tmpVerschilBedrag numeric(15,2), tmpVerschilPercentage numeric(15,2), tmpBalGid integer,
        tmpBalVerdicht smallint, tmpBerekendeZijde smallint, tmpRegelSoort integer,
        OptelStreepBoven smallint, DubbeleStreepOnder smallint, LegeRegelOnder smallint)

begin
  declare @tmpGid integer;
  declare @Teller smallint;
  declare @BalansValCode nchar(3);
  declare @TotaalValCode nchar(3);
  declare @AantalDecimalen integer;
  declare @Dummy nchar(30);
  declare @RegelSoort integer;
  declare @VorigeRegelSoort integer;
  declare @VorigeRksInvoer nchar(28);
  declare @RksInvoer nchar(28);
  declare @OptelStreepBoven integer;
  declare @VorigeOptelStreepBoven integer;
  declare @IsolationLevel         smallint;

  declare @RubriekTekst         long nvarchar;
  declare @ParagraafTekst       long nvarchar;
  declare @SubParagraafTekst    long nvarchar;
  declare @GeenRubParSubTekst   long nvarchar;
  declare @DirectGekoppeldTekst long nvarchar;

  declare local temporary table tmpBalans(
     tmpGid                       integer default AutoIncrement,
     tmpRubParSub                 nchar(11),
     tmpRksInvoer                 nchar(28),
     tmpRksNaam                   nchar(40) default '',
     tmpRksGid                    integer,
     tmpValNummer                 integer,
     tmpValcode                   nchar(3) default '',
     tmpHulpVoorlBedrag           numeric(15,2),
     tmpHulpDefBedrag             numeric(15,2),
     tmpHulpBedrag                numeric(15,2),
     tmpBedrag                    numeric(15,2),
     tmpHulpVoorlBedragAnderJaar  numeric(15,2),
     tmpHulpDefBedragAnderJaar    numeric(15,2),
     tmpHulpBedragAnderJaar       numeric(15,2),
     tmpBedragAnderJaar           numeric(15,2),
     tmpBalGid                    integer,
     tmpBalVerdicht               smallint default 0,
     tmpBerekendeZijde            smallint,  //compute (if (tmpAfdrukZijde = 0 or (tmpAfdrukZijde=2 and (VorigDebet + HuidigDebet >= VorigCredit + HuidigCredit))) then 0 else 1 endif),
     tmpRegelSoort                integer,   // LET OP   900=totaal generaal!!!
     tmpSortering                 nchar(39),
     OptelStreepBoven             smallint default 0,
     DubbeleStreepOnder           smallint default 0,
     LegeRegelOnder               smallint default 0,
     tmpHulpSortering             integer
  ) on commit preserve rows;

  declare cursor_Volgorde cursor for
    select tmpGid, tmpRegelSoort
    from tmpBalans
    order by tmpSortering
  for update;

  declare cursor_LegeRegels cursor for
    select tmpRegelSoort, tmpRksInvoer, OptelStreepBoven
    from tmpBalans
    order by tmpSortering desc
  for update;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Zijde='+string(@Zijde)+', @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+', @VanRks='+string(@VanRks)+', @TotRks='+string(@TotRks)+', @BalCode='+string(@BalCode)+', @VanRubParSub='+string(@VanRubParSub)+', @TotRubParSub='+string(@TotRubParSub)+', @SoortBoeking='+string(@SoortBoeking));
  //call trace('rapScontroBalansMetAnderJaar > @OokNulSaldi='+string(@OokNulSaldi)+', @Specificatie='+string(@Specificatie)+', @BalansInValuta='+string(@BalansInValuta)+', @TotalenInValuta='+string(@TotalenInValuta)+', @RekZonderBalCode='+string(@RekZonderBalCode));


  //Versnellen van de volgende processen
  Create index idx_tmpBalansSoort     on tmpBalans (tmpregelsoort);
  //Create index idx_tmpBalansSortering on tmpBalans (tmpSortering); (helaas; deze werkt niet...... geeft een foutmelding bij eerstvolgende select)
  create index idx_tmpBal1 on tmpBalans (tmpRksInvoer);

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Ervoor: @VanRubParSub=['+@VanRubParSub+'], @TotRubParSub=['+@TotRubParSub+']';
  //call Trace(@@ErrorTextProcedure);

  if isnull(trim(@TotRubParSub) ,'') = '' then
    set @TotRubParSub = '999.999.999'
  else
    set @TotRubParSub = left(trim(@TotRubParSub)+'.999.999.999', 11);
  end if;
  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Erna  : @VanRubParSub=['+@VanRubParSub+'], @TotRubParSub=['+@TotRubParSub+']';
  //call Trace(@@ErrorTextProcedure);

  select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;
  set @AantalDecimalen = 3;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 2';
  //call Trace(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  insert into tmpBalans (tmpRegelSoort, tmpSortering, tmpRksInvoer, tmpRksNaam, tmpRksGid, tmpValNummer, tmpValcode, tmpRubParSub, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpBedrag, tmpHulpVoorlBedragAnderJaar, tmpHulpDefBedragAnderJaar, tmpHulpBedragAnderJaar, tmpBedragAnderJaar, tmpBalVerdicht)
  select   1,
           isnull(left(RubParSub + '.   .   .   ', 11),'===')+RksInvoer,
           RksInvoer,
           RksNaam,
           RksGid,
           @BalansInValuta,
           @BalansValCode,
           IsNull(RubParSub, '   '),
           //saldo dit jaar
           (select IsNull(sum(SaldoDebetBasisVoorlopig)  - sum(SaldoCreditBasisVoorlopig), 0) from tabRekeningSaldo where (RekSaldoRksGid= RksGid) and (RekSaldoBjGid = @BjGid) and (RekSaldoPernr between @VanPernr and @TotPernr)) tmpHulpVoorlBedrag,
           (select IsNull(sum(SaldoDebetBasisDefinitief) - sum(SaldoCreditBasisDefinitief),0) from tabRekeningSaldo where (RekSaldoRksGid= RksGid) and (RekSaldoBjGid = @BjGid) and (RekSaldoPernr between @VanPernr and @TotPernr)) tmpHulpDefBedrag,
           ValutaOmrekenen(@@BasisValutanummer,
                           IsNull((if @SoortBoeking = 0 then tmpHulpDefBedrag else if @SoortBoeking = 1 then tmpHulpVoorlBedrag else tmpHulpDefBedrag + tmpHulpVoorlBedrag endif endif), 0),
                           @BalansInValuta, @BjGid, @TotPernr, 2) test,
          (if @Zijde = 1 or @Zijde = 3 then -1 else 1 endif) *  test tmpBedrag,
           //saldo vergelijkend jaar
           (select IsNull(sum(SaldoDebetBasisVoorlopig)  - sum(SaldoCreditBasisVoorlopig), 0) from tabRekeningSaldo where (RekSaldoRksGid= RksGid) and (RekSaldoBjGid = @AnderBjGid) and (RekSaldoPernr between @VanPernrAnderJaar and @TotPernrAnderJaar)) tmpHulpVoorlBedragAnderJaar,
           (select IsNull(sum(SaldoDebetBasisDefinitief) - sum(SaldoCreditBasisDefinitief),0) from tabRekeningSaldo where (RekSaldoRksGid= RksGid) and (RekSaldoBjGid = @AnderBjGid) and (RekSaldoPernr between @VanPernrAnderJaar and @TotPernrAnderJaar)) tmpHulpDefBedragAnderJaar,
           ValutaOmrekenen(@@BasisValutanummer,
                           IsNull((if @SoortBoeking = 0 then tmpHulpDefBedragAnderJaar else if @SoortBoeking = 1 then tmpHulpVoorlBedragAnderJaar else tmpHulpDefBedragAnderJaar + tmpHulpVoorlBedragAnderJaar endif endif), 0),
                           @BalansInValuta, @AnderBjGid, @TotPernrAnderJaar, 2) testAnderJaar,
          (if @Zijde = 1 or @Zijde = 3 then -1 else 1 endif) *  testAnderJaar tmpBedragAnderJaar,
          (if ((@Specificatie = 1) or (@Specificatie = 2) or (@Specificatie = 3)) then 1 else 0 endif)
  from     tabRekeningschema left outer join (tabBalansCodeRekening inner join tabBalansCodeDetail on (BlRekBlGid = BlGid)) on (BlRksGid = RksGid and DetailBlCode = @BalCode)
  where   ((RubParSub between @VanRubParSub and @TotRubParSub) or
           (@RekZonderBalCode = 1 and RubParSub is null)) and
          ( (@SelecteerOp = 0 and RksInvoer   between @VanRks and @TotRks ) or
            (@SelecteerOp = 1 and RksZoekcode between @VanRks and @TotRks ) or
            (@SelecteerOp = 2 and RksNaam     between @VanRks and @TotRks ) );

  set temporary option isolation_level = @IsolationLevel;

//  @AnderBjGid         Integer,  //vergelijkend boekjaargid
//  @VanPernrAnderJaar  smallint, //van periode vergelijkend boekjaar
//  @TotPernrAnderJaar  smallint) //T/m periode vergelijkend boekjaar

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 3';
  //call Trace(@@ErrorTextProcedure);

  case @Zijde
    when 0 then
      delete tmpBalans from tabRekeningschema where tmpRksGid = RksGid and not (DefaultSoort in (3, 4, 5)       and (AfdrukZijde = 0 or (AfdrukZijde = 2 and (tmpHulpBedrag >= 0))));
    when 1 then
      delete tmpBalans from tabRekeningschema where tmpRksGid = RksGid and not (DefaultSoort in (3, 4, 5)       and (AfdrukZijde = 1 or (AfdrukZijde = 2 and (tmpHulpBedrag <  0))));
    when 2 then
      delete tmpBalans from tabRekeningschema where tmpRksGid = RksGid and not (DefaultSoort in (0, 1, 2, 6, 7) and (AfdrukZijde = 0 or (AfdrukZijde = 2 and (tmpHulpBedrag >= 0))));
    when 3 then
      delete tmpBalans from tabRekeningschema where tmpRksGid = RksGid and not (DefaultSoort in (0, 1, 2, 6, 7) and (AfdrukZijde = 1 or (AfdrukZijde = 2 and (tmpHulpBedrag <  0))));
  end case;


  if @RekZonderBalCode = 0 then
    delete tmpBalans where trim(tmpRubParSub) = '';
  end if;

  case @OokNulSaldi
  when 0 then
    delete tmpBalans where tmpBedrag = 0 and tmpBedragAnderJaar = 0
  when 2 then
    delete tmpBalans
     where (tmpRksGid not in //(select RekSaldoRksGid from tabRekeningsaldo where RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
                           (select JrRksGid from tabJournaalRegel inner join tabJournaalpost on (JpGid = JrJpGid) inner join tabBoekingsgang on (BoekGangGID = JpBoekGangGID)
                            where  JrPerNr between @VanPerNr and @TotPerNr and JrBjGid = @BjGid
                              and ((@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                                   (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                                   (@SoortBoeking = 2))))
      and (tmpRksGid not in //(select RekSaldoRksGid from tabRekeningsaldo where RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
                           (select JrRksGid from tabJournaalRegel inner join tabJournaalpost on (JpGid = JrJpGid) inner join tabBoekingsgang on (BoekGangGID = JpBoekGangGID)
                            where  JrPerNr between @VanPerNrAnderJaar and @TotPerNrAnderJaar and JrBjGid = @AnderBjGid
                              and ((@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                                   (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                                   (@SoortBoeking = 2))))
  end case;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 4';
  //call Trace(@@ErrorTextProcedure);
  //Subtotalen maken volgens aantal specificatie
  //select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;
  set @RubriekTekst         = _U('Rubriek');
  set @ParagraafTekst       = _U('Paragraaf');
  set @SubParagraafTekst    = _U('Subparagraaf');
  set @GeenRubParSubTekst   = _U('(Geen rub/par/sub)');
  set @DirectGekoppeldTekst = _U('(Direct gekoppeld)');

  set @Teller = 3;
  while @Teller > 0 loop

    insert into tmpBalans (tmpRegelSoort, tmpSortering, tmpRubParSub, tmpRksInvoer, tmpRksNaam, tmpValnummer, tmpValCode,
                           tmpBedrag, tmpBedragAnderJaar, tmpBalVerdicht)
    select   13-@Teller DezeRegelSoort,
             IsNull(tabBalanscodeDetail.RubParSub,'===')+'z' Sortering,
             IsNull(tabBalanscodeDetail.RubParSub,'   '),
             tabBalanscodeDetail.RubParSub HulpRksInvoer,
             if DetailBlCode is null then
               if @teller = 1 then
                 @GeenRubParSubTekst
               else
                 @DirectGekoppeldTekst
               endif
             else
               if IsNull(OmsBalansCodeDetails, '' ) = '' then
                 case DezeRegelSoort
                 when 10 then
                   @SubParagraafTekst
                 when 11 then
                   @ParagraafTekst
                 else
                   @RubriekTekst
                 end
               else
                 OmsBalansCodeDetails
               endif
             endif BalOms,
             @BalansInValuta,
             @BalansValCode,
             sum(tmpBedrag),
             sum(tmpBedragAnderJaar),
            (if (@Specificatie = 2 and length(IsNull(tabBalanscodeDetail.RubParSub,'   '))=11) or (@Specificatie = 3 and length(IsNull(tabBalanscodeDetail.RubParSub,'   '))>=7) then 1 else 0 endif)
    from     tmpBalans left outer join tabBalanscodeDetail on (DetailBlCode = @BalCode and RubParSub = substr(tmpRubParSub, 1, (@Teller*4)-1))
    where    length(tmpRubParSub)>=(@Teller*4)-1 and (tmpRksInvoer <> tmpRubParSub or tmpRegelSoort = 1) and ((tmpRegelSoort=1) or (tmpRegelSoort = 12-@Teller)) //HulpRksInvoer is not null
    group by HulpRksInvoer, Sortering, BalOms, BalansVerdicht;

    set @Teller = @Teller - 1;

  end loop;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 5';
  //call Trace(@@ErrorTextProcedure);

  if @Specificatie = 4 then  //Conform balans

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  DetailBlCode=@BalCode and (tmpRubParSub = RubParSub or (tmpRubParSub is null and tmpRksInvoer = RubParSub)) and trim(IsNull(tmpRubParSub,'.'))<>'';  //Alle rubparsub die '' zijn niet overschrijven, wel rubparsub die null zijn

    set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 5a';
    //call Trace(@@ErrorTextProcedure);

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=@BalCode and Rubriek = left(RubParSub,3) and Paragraaf = substr(RubParSub,4,3) and trim(IsNull(tmpRubParSub,'.'))<>'';

    set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 5b';
    //call Trace(@@ErrorTextProcedure);

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=@BalCode and Rubriek = left(RubParSub,3) and Paragraaf='' and trim(IsNull(tmpRubParSub,'.'))<>'';

  end if;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 6';
  //call Trace(@@ErrorTextProcedure);

  delete tmpBalans where tmpBalVerdicht = 1 and (tmpRegelSoort=1 or (@Specificatie<>4));

  //Als er een subparagraaf voor een rekeningregel staat van dezelfde paragraaf maar de rekening zelf valt niet in een subparagraaf, dan subparagraaf-regel tussenvoegen onder de regel
  //Hetzelfde geldt voor andere niveaus (dus 2x de lus uitvoeren: 1x voor rek. -> sub en 1x voor sub. -> par.!)
  set @Teller = 0;
  while @Teller < 2 loop
    set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 6a, teller='+string(@teller);
    //call Trace(@@ErrorTextProcedure);

    insert into tmpBalans (tmpRegelSoort, tmpRubParSub, tmpSortering, tmpRksNaam, tmpValNummer, tmpValcode, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpBedrag, tmpHulpVoorlBedragAnderJaar, tmpHulpDefBedragAnderJaar, tmpHulpBedragAnderJaar, tmpBedragAnderJaar)
    select if tmpRegelsoort = 1 then 10 else tmpRegelSoort + 1 endif Ditregelsoort,
           tmpRubParSub  RubriekOfParagraafNr,
           left(RubriekOfParagraafNr+'.   .   .   ', 11)+'zz'+string(@teller) Volgorde,
           '('+
           case Ditregelsoort
           when 10 then @SubParagraafTekst
           when 11 then @ParagraafTekst
           when 12 then @RubriekTekst
           end + ' ' + if Ditregelsoort <> 10 then tmpRubParSub+'.   )' else tmpRubParSub+'.   .   )' endif,
           tmpValNummer,
           tmpValcode,
           sum(tmpHulpVoorlBedrag), sum(tmpHulpDefBedrag), sum(tmpHulpBedrag), sum(tmpBedrag),
           sum(tmpHulpVoorlBedragAnderJaar), sum(tmpHulpDefBedragAnderJaar), sum(tmpHulpBedragAnderJaar), sum(tmpBedragAnderJaar)
    from   tmpBalans buiten
    where  exists (select 1
                   from   tmpBalans binnen
                   where  binnen.tmpSortering < buiten.tmpSortering and
                          binnen.tmpRubParSub like buiten.tmpRubParSub+'%' and
                          binnen.tmpRegelsoort > buiten.tmpRegelsoort) //ok, bestaat ervoor!

           and //Er bestaat geen next-dieper niveau van?
           not exists (select 1
                   from    tmpBalans binnen
                   where   binnen.tmpSortering > buiten.tmpSortering and
                           binnen.tmpRubParSub like  buiten.tmpRubParSub+'%' and
                           binnen.tmpRegelsoort = if buiten.tmpRegelsoort = 1 then 10 else buiten.tmpRegelsoort+1 endif) //bestaat niet erna!
           and tmpRubParSub is not null
    group by RubriekOfParagraafNr, tmpRubParSub, tmpRegelSoort, tmpValNummer, tmpValcode;

    //Rekeningen die direct aan een paragraaf/rubriek zijn geknoopt terwijl er ook subpar/paragrafen in de par/rubriek zijn
    insert into tmpBalans (tmpRegelSoort, tmpRubParSub, tmpSortering, tmpRksInvoer, tmpRksNaam, tmpValNummer, tmpValcode, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpBedrag, tmpHulpVoorlBedragAnderJaar, tmpHulpDefBedragAnderJaar, tmpHulpBedragAnderJaar, tmpBedragAnderJaar, OptelstreepBoven)
    select 10+@teller Ditregelsoort,
           left(tmpRubParSub, if @teller = 1 then 3 else 7 endif) RubriekOfParagraafNr,
           left(RubriekOfParagraafNr+'.   .   .   ', 11)+'xz'+string(@teller) Volgorde,
           RubriekOfParagraafNr+' ' Invoer,
           @DirectGekoppeldTekst,
           @BalansInValuta,
           @BalansValCode,
           sum(tmpHulpVoorlBedrag),
           sum(tmpHulpDefBedrag  ),
           sum(tmpHulpBedrag     ),
           sum(tmpBedrag         ),
           sum(tmpHulpVoorlBedragAnderJaar),
           sum(tmpHulpDefBedragAnderJaar),
           sum(tmpHulpBedragAnderJaar),
           sum(tmpBedragAnderJaar),
           1
    from   tmpBalans buiten
    where  tmpRegelsoort = 1  //11+@teller //Alleen voor paragrafen en rubrieken!
           and exists(select 1  //Er zijn rekeningen aan de rubriek/par. geknoopt
                      from tmpBalans binnen
                      where binnen.tmpRegelsoort=1   //Het zijn rekeningen
                            and binnen.tmprubparsub = RubriekOfParagraafNr) //aan deze rubriek(teller=0)/paragraaf(teller=1) geknoopt
           and exists(select 1  //Er zijn ook nog andere subpar./par. aan de rubriek of par. geknoopt
                      from tmpBalans binnen
                      where binnen.tmpRegelsoort<>1
                            and binnen.tmpRubParSub like RubriekOfParagraafNr+'.%')
           and length(tmpRubParSub) = if @teller = 1 then 3 else 7 endif
    group by length(tmpRubParSub), RubriekOfParagraafNr, Volgorde, Invoer, tmpValNummer, tmpValcode;

    set @Teller = @Teller + 1;

  end loop;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 7';
  //call Trace(@@ErrorTextProcedure);


  //Subtotalen omrekenen naar juiste valuta
  select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;
  if @BalansInValuta <> @TotalenInValuta then
    insert into tmpBalans (tmpRegelSoort, tmpSortering, tmpRksInvoer, tmpRksNaam, tmpValNummer, tmpValCode, tmpBalVerdicht, tmpBedrag, tmpBedragAnderJaar)
    select   6 + tmpRegelSoort,
             tmpSortering+'z',
             tmpRksInvoer,
             tmpRksNaam,
             @TotalenInValuta,
             @TotaalValCode,
             tmpBalVerdicht,
             ValutaOmrekenen(@BalansInValuta, tmpBedrag, @TotalenInValuta, @BjGid, @TotPernr, 2),
             ValutaOmrekenen(@BalansInValuta, tmpBedragAnderJaar, @TotalenInValuta, @AnderBjGid, @TotPernrAnderJaar, 2)
    from     tmpBalans where tmpRegelSoort between 10 and 13;

  end if;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 8';
  //call Trace(@@ErrorTextProcedure);

  //---------- Optelstrepen zetten ----------

  //Als de vorige een ondieper niveau is (dus lager regelsoort), dan een optelstreep
  Set @VorigeRegelSoort = 999;
  Set @RegelSoort = null;

  open cursor_Volgorde;
  loopVolgorde:
  loop
    Fetch next cursor_Volgorde into @tmpGid, @RegelSoort;
    if sqlstate = '02000' then
      leave LoopVolgorde;
    end if;
    if (@RegelSoort > @VorigeRegelSoort) then
      update tmpBalans set OptelStreepBoven = 1 where tmpGid = @tmpGid
    //else
    //  update tmpBalans set OptelStreepBoven = 0 where tmpGid = @tmpGid;
    end if;
    set @VorigeRegelSoort=@RegelSoort;
  end loop loopVolgorde;
  close cursor_Volgorde;


  //---------- Dubbele totaalstrepen zetten ----------
  update tmpBalans
  set DubbeleStreepOnder = 1
  where OptelStreepBoven <> 0
        and not (@BalansInValuta <> @TotalenInValuta and tmpValCode <> @TotaalValCode); //Alleen voor de onderste (sub)totaalregel

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 9';
  //call Trace(@@ErrorTextProcedure);
  //Alle regels waarvoor geldt dat een dieper niveau al een enkele of een dubbele streep heeft krijgt ook een dubbele streep
  set @Teller = 1; //@AantalCijfers-1;
  while @Teller <= 12 loop
    if exists( select 1 from tmpBalans where tmpRegelSoort = @teller) then
      update tmpBalans buiten
      set    DubbeleStreepOnder = 1
      where  1=(select first 1
                from tmpBalans binnen
                where (binnen.tmpRegelsoort =  1 or isnull(binnen.tmpRksInvoer,'') like isnull(buiten.tmpRksInvoer,'')+ '%') and
                      (isnull(binnen.tmpRubParSub,'') like isnull(buiten.tmpRksInvoer,'')+ '%' or isnull(binnen.tmpRksInvoer,'') like isnull(buiten.tmpRksInvoer,'')+ '%') and
                      binnen.tmpValcode = @BalansValCode and
                      binnen.tmpGid <> buiten.tmpGid
                //where ((binnen.tmpRegelsoort =  1 and isnull(binnen.tmpRubParSub,'') like isnull(buiten.tmpRksInvoer,'')+ '%') or
                //       (binnen.tmpRegelsoort <> 1 and isnull(binnen.tmpRksInvoer,'') like isnull(buiten.tmpRksInvoer,'')+ '%') and binnen.tmpValcode = @BalansValCode)
                //      and binnen.tmpGid <> buiten.tmpGid
             and (binnen.OptelStreepBoven <> 0 or binnen.DubbeleStreepOnder <> 0))
             and tmpRegelsoort <> 1
             and (@BalansInValuta = @TotalenInValuta or tmpValCode = @TotaalValCode); //Alleen voor de onderste (sub)totaalregel
    end if;
    if @teller = 1 then
      set @Teller = 10
    else
      set @Teller = @Teller + 1;
    end if;
  end loop;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 10';
  //call Trace(@@ErrorTextProcedure);
  if @BalansInValuta <> @TotalenInValuta then
    //Eventueel nog wat enkele streepjes verwijderen als op een dieper niveau toch enkele of dubbele strepen staan
    update tmpBalans buiten
    set OptelStreepBoven =
       if 1 = isnull((select first 1
               from   tmpBalans binnen
               where  ((binnen.tmpRegelsoort =  1 and isnull(binnen.tmpRubParSub,'') like isnull(buiten.tmpRksInvoer,'')+ '%') or
                       (binnen.tmpRegelsoort <> 1 and isnull(binnen.tmpRksInvoer,'') like isnull(buiten.tmpRksInvoer,'')+ '%') and binnen.tmpValcode = @BalansValCode)
                      and binnen.tmpGid <> buiten.tmpGid
                      and (binnen.OptelStreepBoven <> 0 or binnen.DubbeleStreepOnder <> 0)
              ),0) then 0 else 1 endif
    where OptelStreepBoven <> 0
          and tmpRegelsoort <> 1
          and tmpValCode = @BalansValCode; //Alleen indien saldo in zelfde valuta als balans
  end if;

  //Zet een enkele streep onderaan als er geen dubbele streep staat
  if exists(select 1 from tmpBalans   where  tmpSortering = (select max(tmpSortering) from tmpBalans) and DubbeleStreepOnder = 0) then
    insert into tmpBalans(tmpRegelSoort, tmpSortering, OptelStreepBoven)
    values((select tmpRegelSoort from tmpBalans where  tmpSortering = (select max(tmpSortering) from tmpBalans)), 'zzzzzzzzzzzzzzzzzzzzz', 1);
  end if;

  //Hulpsortering ivm. strepen bepalen
  update tmpBalans set tmpHulpSortering=number() order by tmpSortering;

  //We moeten een enkele streep, nu bepalen op welk nivo: hetzelfde als het nivo van de regel erboven
  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 11';
  //call Trace(@@ErrorTextProcedure);

  // Voor elke optelstreep die 1 is geldt: optelstreep = regelsoort van de vorige regel
  update tmpBalans tmp
  set OptelStreepBoven =
                (select binnen.tmpRegelSoort
                 from   tmpBalans binnen
                 where  binnen.tmpHulpSortering = tmp.tmpHulpSortering - 1)
  where OptelStreepBoven <> 0;

  Set @VorigeRegelSoort = 0;
  Set @RegelSoort = null;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 12';
  //call Trace(@@ErrorTextProcedure);
  //Hier bepalen we het echte niveau: 1=rekening, 2=sub, 3=par, 4=rub
  update tmpBalans tmp
  set OptelStreepBoven =
                case OptelStreepBoven
                when 1 then
                  1 //Optelstreep op rekening-niveau
                when 10 then
                  2 //Optelstreep op subparagraaf-niveau
                when 16 then
                  2 //Optelstreep op subparagraaf-niveau (andere valuta)
                when 11 then
                  3 //Optelstreep op paragraaf-niveau
                when 17 then
                  3 //Optelstreep op paragraaf-niveau (andere valuta)
                when 12 then
                  4 //Optelstreep op rubriek-niveau
                when 18 then
                  4 //Optelstreep op rubriek-niveau (andere valuta)
                else
                  0
                end
  where OptelStreepBoven <> 0;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar > Stap 13';
  //call Trace(@@ErrorTextProcedure);
  //En voor de dubbele streep ook; dat is het niveau van de huidige regel
  update tmpBalans tmp
  set DubbeleStreepOnder =
                case tmpRegelSoort
                when 1 then
                  1 //Optelstreep op rekening-niveau
                when 10 then
                  2 //Optelstreep op subparagraaf-niveau
                when 16 then
                  2 //Optelstreep op subparagraaf-niveau (andere valuta)
                when 11 then
                  3 //Optelstreep op paragraaf-niveau
                when 17 then
                  3 //Optelstreep op paragraaf-niveau (andere valuta)
                when 12 then
                  4 //Optelstreep op rubriek-niveau
                when 18 then
                  4 //Optelstreep op rubriek-niveau (andere valuta)
                else
                  0
                end
  where DubbeleStreepOnder <> 0;

  Select count(1) into @regelsoort from tmpBalans;

  //Lege ruimte onder de regels: alleen als de regel erna van een ander niveau is
  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaarMetAnderJaar > Stap 14, Aantal records ='+String(@Regelsoort);
  //call Trace(@@ErrorTextProcedure);

  update tmpBalans buiten
  set    LegeRegelOnder = 1
  where  exists(select 1
                from   tmpBalans binnen
                where  binnen.tmpRegelsoort<> buiten.tmpRegelsoort and //Alleen als het een ander regelsoort betreft, dus geen lege regels tussen de rekeningen in
                       isnull(binnen.tmpRksInvoer,'') <> isnull(buiten.tmpRksInvoer,'') and  //Alleen als het een andere rekening/rubriek is ivm. andere valuta
                       binnen.OptelstreepBoven = 0 and                 //Als er een optelstreep volgt, dan geen lege ruimte!!
                       binnen.tmpHulpSortering = buiten.tmpHulpSortering + 1); //En natuurlijk alleen de eerstvolgende regel testen


  //---------- Einde optelstrepen zetten ----------


  insert into tmpBalans (tmpSortering, tmpRegelSoort, tmpBedrag, tmpBedragAnderJaar)
    Select '', 900, Sum(tmpBedrag), Sum(tmpBedragAnderJaar) from tmpBalans where tmpRegelSoort=12;

  set @@ErrorTextProcedure = 'rapScontroBalansMetAnderJaar';
  //call TraceEind(@@ErrorTextProcedure);

  select   tmpGid, tmpRubParSub, tmpRksInvoer, tmpRksNaam, tmpValNummer, tmpValcode, tmpBedrag, tmpBedragAnderJaar,
           cast(tmpBedrag - tmpBedragAnderJaar as numeric(15,2)), //tmpVerschilBedrag,
           cast(if tmpBedragAnderJaar = 0.00 then if (tmpBedrag - tmpBedragAnderJaar) = 0.00 then null else 100.00 endif else (tmpBedrag - tmpBedragAnderJaar) / (tmpBedragAnderJaar/100) endif as numeric(15,2)), //tmpVerschilPercentage
           tmpBalGid, tmpBalVerdicht,
           tmpBerekendeZijde, tmpRegelSoort,
           OptelStreepBoven, DubbeleStreepOnder, LegeRegelOnder
  from     tmpBalans
  order by tmpSortering;
end;

//call RapScontroBalansMetAnderJaar(2, 1, 0, 12, 0, '0100', '9900', 1, '         ', '999999999', 0, 0, 0, 0, 1, 1, 1, 0, 12)


create or replace procedure rapScontroZelfdeHoogte(
 in @BalSoort         smallint, //0 = Verlies/Winst, 1=Debet/Credit
 in @BjGid            Integer,
 in @VanPernr         smallint,
 in @TotPernr         smallint,
 in @SelecteerOp      smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
 in @VanRks           nchar(40), //van nummer/zoekcode/naam
 in @TotRks           nchar(40), //t/m nummer/zoekcode/naam
 in @BalCode          integer , //balanscode
 in @VanRubParSub     nchar(11) , //van rub+par+sub; elementen die leeg zijn
 in @TotRubParSub     nchar(11) , //van rub+par+sub; elementen die leeg zijn -> uitvullen met 3 spaties
 in @SoortBoeking     smallint, //0=definitief, 1=voorlopig, 2=beide
 in @OokNulSaldi      smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
 in @Specificatie     smallint, //0=Grootboekrekening, 1=subparagraaf, 2=paragraaf, 3=rubriek, 4=conform balans
 in @InValuta         integer,  //Valutanummer waarin balans/totalen moet worden afgedrukt
 in @RekZonderBalCode smallint) //Rekening zonder balanscode ook afdrukken (0=nee 1=ja)

result (LregelSoort integer, LrubParSub nchar(11), LrksInvoer nchar(28), LrksNaam nchar(40), Lbedrag numeric(15,2), LbalGid integer, LoptelStreepBoven integer, LlegeRegelOnder integer, LbalansVerdicht integer,
        RregelSoort integer, RrubParSub nchar(11), RrksInvoer nchar(28), RrksNaam nchar(40), Rbedrag numeric(15,2), RbalGid integer, RoptelStreepBoven integer, RlegeRegelOnder integer, RbalansVerdicht integer)


begin
  declare @tmpGid integer;
  declare @Teller integer;
  declare @AantalDecimalen integer;
  declare @Dummy nchar(30);
  declare @RegelSoort integer;
  declare @VorigeRegelSoort integer;
  declare @VorigeRksInvoer nchar(28);
  declare @RksInvoer nchar(28);
  declare @OptelStreepBoven integer;
  declare @VorigeOptelStreepBoven integer;

  // tbv. naast elkaar zetten
  declare @LeesL                 integer;
  declare @LeesR                 integer;
  declare @tmpGidL               integer;
  declare @tmpGidR               integer;
  declare @tmpRubParSubL         nchar(30);
  declare @tmpRubParSubR         nchar(30);
  declare @tmpRegelSoortL        integer;
  declare @tmpRegelSoortR        integer;
  declare @VorigetmpRubParSubL   nchar(11);
  declare @VorigetmpRubParSubR   nchar(11);
  declare @VorigetmpRegelSoortL  integer;
  declare @VorigetmpRegelSoortR  integer;
  declare @vorigetmpOptelStreepL integer;
  declare @vorigetmpOptelStreepR integer;

  // Even tbv. uitlezen van resultaatset
  declare @tmpOptelStreepL          integer;
  declare @tmpOptelStreepR          integer;
  declare @tmpLegeRegelOnderL       smallint;
  declare @tmpLegeRegelOnderR       smallint;
  declare @Spaties                  nchar(100);
  declare @restspaties              nchar(100);

  declare @RubriekTekst         long nvarchar;
  declare @ParagraafTekst       long nvarchar;
  declare @SubParagraafTekst    long nvarchar;
  declare @GeenRubParSubTekst   long nvarchar;
  declare @DirectGekoppeldTekst long nvarchar;

  declare local temporary table tmpBalans(
     tmpGid                integer default AutoIncrement,
     tmpRubParSub          nchar(11),
     tmpRksInvoer          nchar(28),
     tmpRksNaam            nchar(40) default '',
     tmpRksGid             integer,
     tmpHulpVoorlBedrag    numeric(15,2),
     tmpHulpDefBedrag      numeric(15,2),
     tmpHulpBedrag         numeric(15,2),
     tmpBedrag             numeric(15,2),
     tmpBalGid             integer,
     tmpBalVerdicht        smallint default 0,
     tmpRegelSoort         integer,   // LET OP   900=totaal generaal!!!
     tmpSortering          nchar(39),
     tmpZijde              integer,  // Geeft 0=links of 1=rechts aan
     tmpHulpSortering      integer
  ) on commit preserve rows;

  declare local temporary table tmpBeide(
    tmpBgid                integer default autoincrement,
    tmpVolgorde            integer,
    tmpGidL                integer,
    tmpGidR                integer,
    tmpOptelStreepL        smallint default 0,
    tmpOptelStreepR        smallint default 0,
    tmpLegeRegelOnderL     smallint default 0,
    tmpLegeRegelOnderR     smallint default 0,
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'rapScontroZelfdeHoogte > @BalSoort='+string(@BalSoort)+', @BjGid='+string(@BjGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @SelecteerOp='+string(@SelecteerOp)+', @VanRks='+string(@VanRks)+', @TotRks='+string(@TotRks)+', @BalCode='+string(@BalCode)+', @VanRubParSub='+string(@VanRubParSub)+', @TotRubParSub='+string(@TotRubParSub)+', @SoortBoeking='+string(@SoortBoeking);
  //call TraceBegin(@@ErrorTextProcedure);
  //call trace('rapScontroBalans > @OokNulSaldi='+string(@OokNulSaldi)+', @Specificatie='+string(@Specificatie)+', @InValuta='+string(@InValuta)+', @RekZonderBalCode='+string(@RekZonderBalCode));


  //Versnellen van de volgende processen
  Create index idx_tmpBalansSoort     on tmpBalans (tmpregelsoort);
  //Create index idx_tmpBalansSortering on tmpBalans (tmpSortering); (helaas; deze werkt niet...... geeft een foutmelding bij eerstvolgende select)
  create index idx_tmpBal1 on tmpBalans (tmpRksInvoer);

  set @@ErrorTextProcedure = 'rapScontroBalans > Ervoor: @VanRubParSub=['+@VanRubParSub+'], @TotRubParSub=['+@TotRubParSub+']';
  //call Trace(@@ErrorTextProcedure);

  if isnull(trim(@TotRubParSub) ,'') = '' then
    set @TotRubParSub = '999.999.999'
  else
    set @TotRubParSub = left(trim(@TotRubParSub)+'.999.999.999', 11);
  end if;
  set @@ErrorTextProcedure = 'rapScontroBalans > Erna  : @VanRubParSub=['+@VanRubParSub+'], @TotRubParSub=['+@TotRubParSub+']';
  //call Trace(@@ErrorTextProcedure);

  set @AantalDecimalen = 3;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 2';
  //call Trace(@@ErrorTextProcedure);

  // Links EN rechts tegelijkertijd toevoegen
  insert into tmpBalans (tmpRegelSoort, tmpSortering, tmpRksInvoer, tmpRksNaam, tmpRksGid, tmpRubParSub, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpZijde, tmpBedrag, tmpBalVerdicht)
  select   1,
           isnull(left(RubParSub + '.   .   .   ', 11),'===')+RksInvoer,
           RksInvoer,
           RksNaam,
           RksGid,
           IsNull(RubParSub, '   '),
           IsNull(sum(SaldoDebetBasisVoorlopig)  - sum(SaldoCreditBasisVoorlopig),0)  tmpHulpVoorlBedrag,
           IsNull(sum(SaldoDebetBasisDefinitief) - sum(SaldoCreditBasisDefinitief),0) tmpHulpDefBedrag,
           ValutaOmrekenen(@@BasisValutanummer,
                           IsNull((if @SoortBoeking = 0 then tmpHulpDefBedrag else if @SoortBoeking = 1 then tmpHulpVoorlBedrag else tmpHulpDefBedrag + tmpHulpVoorlBedrag endif endif), 0),
                           @InValuta, @BjGid, @TotPernr, 2) test,
           case
             when DefaultSoort in (1,4,6) then 0
             when DefaultSoort in (2,4,7) then 1
             else
              case
                when AfdrukZijde = 0 then 0
                when AfdrukZijde = 1 then 1
                else
                  if test>0 then
                    0
                  else
                    1
                  endif
              end
           end tmpZijde,
           (if tmpZijde = 0 then 1 else -1 endif) * test tmpBedrag,
          (if ((@Specificatie = 1) or (@Specificatie = 2) or (@Specificatie = 3)) then 1 else 0 endif)
  from     tabRekeningschema left outer join (tabBalansCodeRekening inner join tabBalansCodeDetail on (BlGid = BlRekBlGid)) on (BlRksGid = RksGid and DetailBlCode = @BalCode)
           left outer join tabRekeningSaldo on (RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
  where   ((RubParSub between @VanRubParSub and @TotRubParSub) or
           (@RekZonderBalCode = 1 and RubParSub is null)) and
          ( (@SelecteerOp = 0 and RksInvoer   between @VanRks and @TotRks ) or
            (@SelecteerOp = 1 and RksZoekcode between @VanRks and @TotRks ) or
            (@SelecteerOp = 2 and RksNaam     between @VanRks and @TotRks ) )
           and // Rekeningsoort keuze maken
          ( (@BalSoort = 0 and DefaultSoort in (3, 4, 5)) or
            (@BalSoort = 1 and DefaultSoort in (0, 1, 2, 6, 7)) )
  group by RksGid, RksInvoer, RksNaam, DefaultSoort, AfdrukZijde, RubParSub;


  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 3';
  //call Trace(@@ErrorTextProcedure);

  case @OokNulSaldi
  when 0 then
    delete tmpBalans where tmpBedrag = 0
  when 2 then
    delete tmpBalans where tmpRksGid not in //(select RekSaldoRksGid from tabRekeningsaldo where RekSaldoBjGid=@BjGid and RekSaldoPernr between @VanPernr and @TotPernr)
                                   (select JrRksGid from tabJournaalRegel inner join tabJournaalpost on (JpGid = JrJpGid) inner join tabBoekingsgang on (BoekgangGid = JpBoekgangGid) where JrPerNr between @VanPerNr and @TotPerNr and JrBjGid = @BjGid and
                                   ((@SoortBoeking = 0 and IsBoekgangDefinitief = 1) or
                                   (@SoortBoeking = 1 and IsBoekgangDefinitief = 0) or
                                   (@SoortBoeking = 2)))

  end case;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 4';
  //call Trace(@@ErrorTextProcedure);
  //Subtotalen maken volgens aantal specificatie voor beide zijden
  set @RubriekTekst         = _U('Rubriek');
  set @ParagraafTekst       = _U('Paragraaf');
  set @SubParagraafTekst    = _U('Subparagraaf');
  set @GeenRubParSubTekst   = _U('(Geen rub/par/sub)');
  set @DirectGekoppeldTekst = _U('(Direct gekoppeld)');

  set @Teller = 3;
  while @Teller > 0 loop

    insert into tmpBalans (tmpRegelSoort, tmpSortering, tmpRubParSub, tmpRksInvoer, tmpRksNaam,
                           tmpBedrag, tmpZijde, tmpBalVerdicht)
    select   13-@Teller DezeRegelSoort,
             IsNull(tabBalanscodeDetail.RubParSub,'===')+'z' Sortering,
             IsNull(tabBalanscodeDetail.RubParSub,'   '),
             tabBalanscodeDetail.RubParSub HulpRksInvoer,
             if DetailBlCode is null then
               if @teller = 1 then
                 @GeenRubParSubTekst
               else
                 @DirectGekoppeldTekst
               endif
             else
               if IsNull(OmsBalansCodeDetails, '' ) = '' then
                 case DezeRegelSoort
                 when 10 then
                   @GeenRubParSubTekst
                 when 11 then
                   @ParagraafTekst
                 else
                   @RubriekTekst
                 end
               else
                 OmsBalansCodeDetails
               endif
             endif BalOms,
             sum(tmpBedrag),
             tmpZijde,
            (if (@Specificatie = 2 and length(IsNull(tabBalanscodeDetail.RubParSub,'   '))=11) or (@Specificatie = 3 and length(IsNull(tabBalanscodeDetail.RubParSub,'   '))>=7) then 1 else 0 endif)
    from     tmpBalans left outer join tabBalanscodeDetail on (DetailBlCode = @BalCode and RubParSub = substr(tmpRubParSub, 1, (@Teller*4)-1))
    where    length(tmpRubParSub)>=(@Teller*4)-1 and (tmpRksInvoer <> tmpRubParSub or tmpRegelSoort = 1) and ((tmpRegelSoort=1) or (tmpRegelSoort = 12-@Teller)) //HulpRksInvoer is not null
    group by HulpRksInvoer, Sortering, BalOms, BalansVerdicht, tmpZijde;

    set @Teller = @Teller - 1;

  end loop;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 5';
  //call Trace(@@ErrorTextProcedure);

  if @Specificatie = 4 then  //Conform balans

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  DetailBlCode=@BalCode and (tmpRubParSub = RubParSub or (tmpRubParSub is null and tmpRksInvoer = RubParSub)) and trim(IsNull(tmpRubParSub,'.'))<>'';  //Alle rubparsub die '' zijn niet overschrijven, wel rubparsub die null zijn

    set @@ErrorTextProcedure = 'rapScontroBalans > Stap 5a';
    //call Trace(@@ErrorTextProcedure);

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=@BalCode and Rubriek = left(RubParSub,3) and Paragraaf = substr(RubParSub,4,3) and trim(IsNull(tmpRubParSub,'.'))<>'';

    set @@ErrorTextProcedure = 'rapScontroBalans > Stap 5b';
    //call Trace(@@ErrorTextProcedure);

    update tmpBalans set tmpBalGid = BlGid, tmpBalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  tmpBalGid is null and DetailBlCode=@BalCode and Rubriek = left(RubParSub,3) and Paragraaf='' and trim(IsNull(tmpRubParSub,'.'))<>'';

  end if;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 6';
  //call Trace(@@ErrorTextProcedure);

  delete tmpBalans where tmpBalVerdicht = 1 and (tmpRegelSoort=1 or (@Specificatie<>4));


  //Als er een subparagraaf voor een rekeningregel staat van dezelfde paragraaf maar de rekening zelf valt niet in een subparagraaf, dan subparagraaf-regel tussenvoegen onder de regel
  //Hetzelfde geldt voor andere niveaus (dus 2x de lus uitvoeren: 1x voor rek. -> sub en 1x voor sub. -> par.!)
  set @Teller = 0;
  while @Teller < 2 loop
    set @@ErrorTextProcedure = 'rapScontroBalans > Stap 6a, teller='+string(@teller);
    //call Trace(@@ErrorTextProcedure);

    insert into tmpBalans (tmpRegelSoort, tmpRubParSub, tmpSortering, tmpRksNaam, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpBedrag)
    select if tmpRegelsoort = 1 then 10 else tmpRegelSoort + 1 endif Ditregelsoort,
           tmpRubParSub  RubriekOfParagraafNr,
           left(RubriekOfParagraafNr+'.   .   .   ', 11)+'zz'+string(@teller) Volgorde,
           '('+
           case Ditregelsoort
           when 10 then @SubParagraafTekst
           when 11 then @ParagraafTekst
           when 12 then @RubriekTekst
           end + ' ' + if Ditregelsoort <> 10 then tmpRubParSub+'.   )' else tmpRubParSub+'.   .   )' endif,
           sum(tmpHulpVoorlBedrag), sum(tmpHulpDefBedrag), sum(tmpHulpBedrag), sum(tmpBedrag)
    from   tmpBalans buiten
    where  exists (select 1
                   from   tmpBalans binnen
                   where  binnen.tmpSortering < buiten.tmpSortering and
                          binnen.tmpRubParSub like buiten.tmpRubParSub+'%' and
                          binnen.tmpRegelsoort > buiten.tmpRegelsoort) //ok, bestaat ervoor!

           and //Er bestaat geen next-dieper niveau van?
           not exists (select 1
                   from    tmpBalans binnen
                   where   binnen.tmpSortering > buiten.tmpSortering and
                           binnen.tmpRubParSub like  buiten.tmpRubParSub+'%' and
                           binnen.tmpRegelsoort = if buiten.tmpRegelsoort = 1 then 10 else buiten.tmpRegelsoort+1 endif) //bestaat niet erna!
           and tmpRubParSub is not null
    group by RubriekOfParagraafNr, tmpRubParSub, tmpRegelSoort;

    //Rekeningen die direct aan een paragraaf/rubriek zijn geknoopt terwijl er ook subpar/paragrafen in de par/rubriek zijn
    insert into tmpBalans (tmpRegelSoort, tmpRubParSub, tmpSortering, tmpRksInvoer, tmpRksNaam, tmpHulpVoorlBedrag, tmpHulpDefBedrag, tmpHulpBedrag, tmpBedrag)
    select 10+@teller Ditregelsoort,
           left(tmpRubParSub, if @teller = 1 then 3 else 7 endif) RubriekOfParagraafNr,
           left(RubriekOfParagraafNr+'.   .   .   ', 11)+'xz'+string(@teller) Volgorde,
           RubriekOfParagraafNr+' ' Invoer,
           @DirectGekoppeldTekst,
           sum(tmpHulpVoorlBedrag),
           sum(tmpHulpDefBedrag  ),
           sum(tmpHulpBedrag     ),
           sum(tmpBedrag         )
    from   tmpBalans buiten
    where  tmpRegelsoort = 1  //11+@teller //Alleen voor paragrafen en rubrieken!
           and exists(select 1  //Er zijn rekeningen aan de rubriek/par. geknoopt
                      from tmpBalans binnen
                      where binnen.tmpRegelsoort=1   //Het zijn rekeningen
                            and binnen.tmprubparsub = RubriekOfParagraafNr) //aan deze rubriek(teller=0)/paragraaf(teller=1) geknoopt
           and exists(select 1  //Er zijn ook nog andere subpar./par. aan de rubriek of par. geknoopt
                      from tmpBalans binnen
                      where binnen.tmpRegelsoort<>1
                            and binnen.tmpRubParSub like RubriekOfParagraafNr+'.%')
           and length(tmpRubParSub) = if @teller = 1 then 3 else 7 endif
    group by length(tmpRubParSub), RubriekOfParagraafNr, Volgorde, Invoer;

    set @Teller = @Teller + 1;

  end loop;

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 7';
  //call Trace(@@ErrorTextProcedure);


/*
  update tmpBalans buiten
  set    LegeRegelOnder = 1
  where  exists(select 1
                from   tmpBalans binnen
                where  binnen.tmpRegelsoort<> buiten.tmpRegelsoort and //Alleen als het een ander regelsoort betreft, dus geen lege regels tussen de rekeningen in
                       isnull(binnen.tmpRksInvoer,'') <> isnull(buiten.tmpRksInvoer,'') and  //Alleen als het een andere rekening/rubriek is ivm. andere valuta
                       binnen.OptelstreepBoven = 0 and                 //Als er een optelstreep volgt, dan geen lege ruimte!!
                       binnen.tmpHulpSortering = buiten.tmpHulpSortering + 1); //En natuurlijk alleen de eerstvolgende regel testen
*/

  //---------- Einde optelstrepen zetten ----------

  set @@ErrorTextProcedure = 'rapScontroBalans > Stap 16';
  //call Trace(@@ErrorTextProcedure);

  //call traceEind('rapScontroBalans');
    // 2 cursors. Verwerking als volgt:
/*
    Open cursor L
    Open cursor R
    set L moet worden gelezen
    set R moet worden gelezen
    LUS
      Als L moet worden gelezen
        Lees L
        set L moet niet worden gelezen
      Als R moet worden gelezen
        Lees R
        set R moet niet worden gelezen
      Als L leeg EN R leeg
        Verlaat lus
      Als L.rubparsub=R.rubparsub EN L.soort=R.soort
        Insert L+R
        set L moet worden gelezen
        set R moet worden gelezen
      Als L.rubparsub<=R.rubparsub of R is leeg
        Insert L
        set L moet worden gelezen
      Als R.rubparsub<=L.rubparsub of L is leeg
        Insert R
        set R moet worden gelezen
    EIND LUS
    Sluit cursor R
    Sluit cursor L

Test gelijk/groter/kleiner:
Maak rubparsub altijd met punten tot '000.ZZZ.ZZZ'
vergelijk nu
*/
    begin
      declare cursor_L cursor for
        select tmpGid, tmpRubParSub, tmpRegelSoort from tmpBalans where tmpZijde = 0 order by tmpSortering
      for read only;
      declare cursor_R cursor for
        select tmpGid, tmpRubParSub, tmpRegelSoort from tmpBalans where tmpZijde = 1 order by tmpSortering
      for read only;

      set @vorigetmpOptelStreepL = 0;
      set @vorigetmpOptelStreepR = 0;

      set @teller = 1;
      set @LeesL = 1;
      set @LeesR = 1;
      open cursor_L;
      open cursor_R;
      LoopNaastElkaar:
      loop
        if @LeesL = 1 then
          fetch next cursor_L into @tmpGidL, @tmpRubParSubL, @tmpRegelSoortL;
          if sqlstate = '02000' then
            set @tmpRubParSubL = null;
          end if;
          set @LeesL = 0;
        end if;
        if @LeesR = 1 then
          fetch next cursor_R into @tmpGidR, @tmpRubParSubR, @tmpRegelSoortR;
          if sqlstate = '02000' then
            set @tmpRubParSubR = null;
          end if;
          set @LeesR = 0;
        end if;
        if @tmpRubParSubL is null and @tmpRubParSubR is null then
          leave LoopNaastElkaar;
        end if;
        // Wegschrijven van links, rechts of beiden
        case
          when @tmpRubParSubL = @tmpRubParSubR and @tmpRegelSoortL = @tmpRegelSoortR then
            // Beiden zijn gelijk -> allebei schrijven, allebei verder lezen
            insert into tmpBeide(tmpVolgorde, tmpGidL, tmpGidR)
            values(@teller, @tmpGidL, @tmpGidR);
            set @LeesL = 1;
            set @LeesR = 1;
          //call Trace(string(@teller)+'|LR| |'+@tmpRubParSubL +'|=|'+ @tmpRubParSubR+'|');
          when left(@tmpRubParSubL+'.ZZZ.ZZZ.ZZZ', 11) <= left(@tmpRubParSubR+'.ZZZ.ZZZ.ZZZ', 11) or @tmpRubParSubR is null then
            // Links kleiner, dus alleen links schrijven en verder lezen
            insert into tmpBeide(tmpVolgorde,tmpGidL)
            values(@teller, @tmpGidL);
            set @LeesL = 1;
          //call Trace(string(@teller)+'|L_| |'+@tmpRubParSubL +'|<|'+ @tmpRubParSubR+'|');
          when left(@tmpRubParSubR+'.ZZZ.ZZZ.ZZZ', 11) <= left(@tmpRubParSubL+'.ZZZ.ZZZ.ZZZ', 11) or @tmpRubParSubL is null then
            // Rechts kleiner, dus alleen rechts schrijven en verder lezen
            insert into tmpBeide(tmpVolgorde, tmpGidR)
            values(@teller, @tmpGidR);
            set @LeesR = 1;
          //call Trace(string(@teller)+'|_R| |'+@tmpRubParSubL +'|>|'+ @tmpRubParSubR+'|');
        end case;

        // ---------- STREPEN ----------

        // Als deze regelsoort> vorige regelsoort, dan op deze regel een enkele streep zetten
        // Echter, NIET als de vorige gegel ook al een enkele streep had!

        if @LeesL = 1 then
          if @tmpRegelSoortL < @VorigetmpRegelSoortL then
            update tmpBeide set tmpLegeRegelOnderL = 1
            where tmpVolgorde = @teller  and tmpGidL is not null;
          end if;
          if @tmpRegelSoortL > @VorigetmpRegelSoortL then
            update tmpBeide set tmpOptelStreepL = @VorigetmpRegelSoortL
            where tmpVolgorde = @teller and tmpGidL is not null;
            set @vorigetmpOptelStreepL = @VorigetmpRegelSoortL;
          else
            set @vorigetmpOptelStreepL = 0;
          end if;
        end if;
        if @LeesR = 1 then
          if @tmpRegelSoortR < @VorigetmpRegelSoortR then
            update tmpBeide set tmpLegeRegelOnderR = 1
            where tmpVolgorde = @teller  and tmpGidR is not null;
          end if;
          if @tmpRegelSoortR > @VorigetmpRegelSoortR then
            update tmpBeide set tmpOptelStreepR = @VorigetmpRegelSoortR
            where tmpVolgorde = @teller and tmpGidR is not null;
            set @vorigetmpOptelStreepR = 1;
          else
            set @vorigetmpOptelStreepR = 0;
          end if;
        end if;

        // Lus voortzetten na onthouden van waarden
        set @teller = @teller + 1;
        if @LeesL = 1 then
          set @VorigetmpRubParSubL  = isnull(@tmpRubParSubL, @VorigetmpRubParSubL);
          set @VorigetmpRegelSoortL = isnull(@tmpRegelSoortL, @VorigetmpRegelSoortL);
        end if;
        if @LeesR = 1 then
          set @VorigetmpRubParSubR  = isnull(@tmpRubParSubR, @VorigetmpRubParSubR);
          set @VorigetmpRegelSoortR = isnull(@tmpRegelSoortR, @VorigetmpRegelSoortR);
        end if;
      end loop LoopNaastElkaar;
      close cursor_L;
      close cursor_R;
    end;

  // Totaal Generaal voor links EN rechts
  insert into tmpBalans (tmpZijde, tmpSortering, tmpRegelSoort, tmpBedrag)
    Select 0, '', 900, Sum(tmpBedrag) from tmpBalans where tmpRegelSoort=12 and tmpZijde = 0;
  set @tmpOptelStreepL = @@Identity;
  insert into tmpBalans (tmpZijde, tmpSortering, tmpRegelSoort, tmpBedrag)
    Select 1, '', 900, Sum(tmpBedrag) from tmpBalans where tmpRegelSoort=12 and tmpZijde = 1;
  set @tmpOptelStreepR = @@Identity;
  insert into tmpBeide(tmpVolgorde, tmpGidL, tmpGidR)
  values(-1, @tmpOptelStreepL, @tmpOptelStreepR);


  // Resultaat teruggeven
  select
    L.tmpRegelSoort LregelSoort, L.tmpRubParSub LrubParSub, L.tmpRksInvoer LrksInvoer, L.tmpRksNaam LrksNaam, L.tmpBedrag Lbedrag, L.tmpBalGid LbalGid, tmpOptelStreepL LoptelStreepBoven, tmpLegeRegelOnderL LlegeRegelOnder, L.tmpBalVerdicht LbalansVerdicht,
    R.tmpRegelSoort RregelSoort, R.tmpRubParSub RrubParSub, R.tmpRksInvoer RrksInvoer, R.tmpRksNaam RrksNaam, R.tmpBedrag Rbedrag, R.tmpBalGid RbalGid, tmpOptelStreepR RoptelStreepBoven, tmpLegeRegelOnderR RlegeRegelOnder, R.tmpBalVerdicht RbalansVerdicht
  from
    tmpBeide
    left outer join tmpBalans L on (L.tmpGid = tmpGidL)
    left outer join tmpBalans R on (R.tmpGid = tmpGidR)
  order by
    tmpVolgorde;



end;

//call rapScontroZelfdeHoogte(0, 1, 0, 12, 0, '1010', '9910', 1, '         ', '999999999', 0, 0, 0, 0, 1)
//call rapScontroZelfdeHoogte(0, 1, 0, 12, 0, '1010', '9910', 1, '         ', '999999999', 0, 0, 0, 0, 1)


create or replace procedure rapStamGeg( in @FonId           nchar(3),
                                        in @AfdrukkenAlle   smallint,           // 0 = alleen Naw volgens @AfdrukkenSel / 1 = alle
                                        in @AfdrukkenSel    nchar(10),           // Alleen Naw met: 0|Contactpersonen|1|Bestel/verzendadressen|2|Bankrekeningen|3|Opmerkingen|4|Selecties
                                        in @SelecteerOp     smallint,  //0=nummer, 1=zoekcode
                                        in @VanNaw          nchar(10),
                                        in @TotNaw          nchar(10),
                                        in @SorterenOp      smallint,  //0=nummer, 1=zoekcode  2=postcode vestigings adres, 3=postcode corresp. adres, 4=vertegenwoordiger
                                        in @IsAscending     smallint  // 0 = aflopend, 1 = oplopend
                           )

result ( NawFilGid              Integer,
         NawFilNummer           nchar(10),
         NawFilZoekCode         nchar(10),
         NawGidje               Integer,
         Website                nchar(250),
         KvkNummer              nchar(40),
         NawOpmNawGid           Integer,
         NawOpmOpmerking        long nvarchar,
         VertegenWoordigerCode  Integer,
         VertegenWoordigerNaam  nchar(40),

         VAdrGid                Integer,
         VAdrNaam1              nchar(40), VAdrNaam2  nchar(40), VAdrOms      nchar(40), VAdrStraat  nchar(40), VAdrHuisnummer nchar(10),
         VAdrPostcode           nchar(40), VAdrPlaats nchar(40),
         VAdrStraatRegel        nchar(50),
         VAdrTelefoon           nchar(25), VAdrTelefoon2 nchar(25), VAdrTelefax nchar(25), VAdrEmail      nchar(80), VAdrEanCode nchar(13),
         VlndInNAWBlok          smallint,
         VLandAfdrukken         smallint,
         VKIXCode               nchar(54),
         VlndEigenCode          nchar(3),
         VlndOms                nchar(40),
         VlndPlaatsHuisnr       smallint,
         VlndPlaatsPostcode     smallint,
         VlndPostcodeMasker     nchar(40),

         CAdresGelijk           smallint,
         CAdrGid                Integer,
         CAdrNaam1              nchar(40), CAdrNaam2  nchar(40), CAdrOms      nchar(40), CAdrStraat  nchar(40), CAdrHuisnummer nchar(10),
         CAdrPostcode           nchar(40), CAdrPlaats nchar(40),
         CAdrStraatRegel        nchar(50),
         CAdrTelefoon           nchar(25), CAdrTelefoon2 nchar(25), CAdrTelefax nchar(25), CAdrEmail      nchar(80), CAdrEanCode nchar(13),
         ClndInNAWBlok          smallint,
         CLandAfdrukken         smallint,
         CKIXCode               nchar(54),
         ClndEigenCode          nchar(3),
         ClndOms                nchar(40),
         ClndPlaatsHuisnr       smallint,
         ClndPlaatsPostcode     smallint,
         ClndPostcodeMasker     nchar(40),

         SelCode                nchar(3),

         orderGegNawAparteFacturen         smallint,  //hoe zit het trouwens met opties????    naamgeving voor verwerking naar de layout toe
         orderGegNawFacturerenInclBtw      smallint,
         orderGegNawFactuurAdres           smallint,
         orderGegVerzendAdresSoort         Integer, //combobox
         orderGegVerzAdresOms              nchar(40),
         orderGegVerzendAdres              Integer, //niet gidje, maar evt adrescode
         orderGegEindAdresSoort            Integer, //combobox
         orderGegEindAdresOms              nchar(40),
         orderGegEindAdres                 Integer, //niet gidje, maar evt adrescode
         orderGegNawAantalKopieFacturen    smallint,
         orderGegNawOrderKorting           numeric(6,2),
         orderGegNawContributieCode        Integer,// moet nog op optie nagekeken worden . hier of in de dm
         orderGegNawContributieOms         nchar(40),
         orderGegNawBlokOrderInvoer        smallint,
         orderGegRapNumIncl                Integer,
         orderGegRapNaamIncl               nchar(40),
         orderGegRapNumExcl                Integer,
         orderGegRapNaamExcl               nchar(40),
         orderGegWebNaw                    smallInt,
         orderGegDebGrpNr                  smallInt,
         orderGegDebGrpOms                 nchar(40),
         orderGegDebGrpKorting             numeric(15,2),
         orderGegWelkeKorting              smallInt,
         orderGegDebNummerFactuur          nchar(10),
         orderGegDebOmsFactuur             nchar(40),
         orderGegDebOmsFactuur2            nchar(40),
         orderGegDebNummerOmzet            nchar(10),
         orderGegDebOmsOmzet               nchar(40),
         orderGegDebOmsOmzet2              nchar(40),
         orderGegDebNummerPrijzen          nchar(10),
         orderGegDebOmsPrijzen             nchar(40),
         orderGegDebOmsPrijzen2            nchar(40),

         FinGegBtcNummer                   Integer,
         FinGegBtcOms                      nchar(40),
         FinGegLvcNummer                   Integer,
         FinGegLvcOms                      nchar(40),
         FinGegNawFilValNummer             Integer,
         FinGegValCode                     nchar(3),
         FinGegOmsValuta                   nchar(40),
         FinGegBTWCode                     Integer,
         FinGegBtwOms                      nchar(40),
         FinGegTaalCode                    nchar(3),
         FinGegTaalOms                     nchar(40),
         FinGegNawfilKredLimiet            numeric (15,2),
         FinGegKredLimIsStandaard          smallint,
         FinGegTegenRekening               nchar(28),
         FinGegTegRekNaam                  nchar(40),
         FinGegAanmaningsType              smallint,  // 0=geen / 1=aanmaning / 2=rekeningoverzicht
         FinGegnawBtwNummer                nchar(15),
         FinGegOBNummer                    nchar(15),
         FinGegNawOnsDebiteurNummer        nchar(20),
         FinGegNawFilAutoOSP               smallint,
         FinGegNawIncassantReferentie      nchar(35),
         FinGegNawBedrijfstak              nchar(5)
       )


begin
	declare @Rel smallint;
  declare @defaultLndGid integer;

  declare @BjGid integer;
  declare @PerNr integer;

  declare @CorAdresTekst          long nvarchar;
  declare @VestAdresTekst         long nvarchar;
  declare @FactDebCorAdresTekst   long nvarchar;
  declare @FactDebVestAdresTekst  long nvarchar;
  declare @NietVanToepassingTekst long nvarchar;

  set @CorAdresTekst          = _U('Correspondentieadres');
  set @VestAdresTekst         = _U('Vestigingsadres');
  set @FactDebCorAdresTekst   = _U('Factuurdebiteur-Correspondentieadres');
  set @FactDebVestAdresTekst  = _U('Factuurdebiteur-Vestigingsadres');
  set @NietVanToepassingTekst = _U('Niet van toepassing');

  call BepaalBoekjaarEnPeriode (@@VerwerkingsDatum, @BjGid, @PerNr);

  select (if @fonId in ('D', 'C') then 0 else 1 endif) into @Rel;   //@Rel geeft aan dat het om Relaties gaat
  select DefaultLndGid into @DefaultLndGid from tabVasteGegevens;

  select
    NawFilGid,
    NawFilNummer, NawFilZoekCode,
    NAW.NawGid NawGidje,
    NAW.NawWebsite Website,
    NAW.NawKvkNummer KvkNummer,
    (select NawOpmNawGid from tabNawOpmerkingen where  NAW.NawGid = NawOpmNawGid) NawOpmNawGid,
    (select NawOpmOpmerking from tabNawOpmerkingen where  NAW.NawGid = NawOpmNawGid) NawOpmOpmerking,
    NAW.NawVertegenwCode VertegenWoordigerCode,
    (select relVolledigeNaam from tabRelatie where RelVtgCode = NAW.nawVertegenwCode) VertegenWoordigerNaam,

    //-------------- vestigingsadres gegevens
    V.AdrGid VAdrGid,
    V.AdrNaam1 VAdrNaam1,
    V.AdrNaam2 VAdrNaam2,
    V.AdrOms VAdrOms,
    V.AdrStraat VAdrStraat,
    V.AdrHuisnummer VAdrHuisnummer,
    V.AdrPostcode VAdrPostcode,
    V.AdrPlaats VAdrPlaats,
    (if (VL.LndPlaatsHuisNr <> 1) then trim(V.AdrHuisNummer +' ' + V.AdrStraat) else trim(V.AdrStraat + ' ' + V.AdrHuisnummer) endif) VAdrStraatRegel,
    V.AdrTelefoon VAdrTelefoon,
    V.AdrTelefoon2 VAdrTelefoon2,
    V.AdrTelefax VAdrTelefax,
    V.AdrEmail VAdrEmail,
    V.AdrEanCode VAdrEanCode,

    VL.lndInNAWBlok VlndInNAWBlok,
    ( if VL.lndInNAWblok = 1  then 1                        // bepaal of land moet worden afgedrukt
      else if VL.lndgid = @DefaultLndGid then 0
           else 1
           endif
      endif) VLandAfdrukken,

    BouwKIXCode(V.adrLndGid, VAdrPostcode, VAdrHuisnummer) as VKIXCode,
    VL.lndEigenCode VlndEigenCode,
    VL.lndOms VlndOms,
    VL.lndPlaatsHuisnr VlndPlaatsHuisnr,
    VL.lndPlaatsPostcode VlndPlaatsPostcode,
    VL.lndPostcodeMasker VlndPostcodeMasker,

    //-------------- correspondentie adres gegevens
    (if NAW.NawGidVestiging = NAW.NawGidCorrespondentie then 1 else 0 endif) CAdresGelijk,
    C.AdrGid CAdrGid,
    C.AdrNaam1 CAdrNaam1,
    C.AdrNaam2 CAdrNaam2,
    C.AdrOms CAdrOms,
    C.AdrStraat CAdrStraat,
    C.AdrHuisnummer CAdrHuisnummer,
    C.AdrPostcode CAdrPostcode,
    C.AdrPlaats CAdrPlaats,
    (if (CL.LndPlaatsHuisNr <> 1) then trim(C.AdrHuisNummer +' ' + C.AdrStraat) else trim(C.AdrStraat + ' ' + C.AdrHuisnummer) endif) CAdrStraatRegel,
    C.AdrTelefoon CAdrTelefoon,
    C.AdrTelefoon2 CAdrTelefoon2,
    C.AdrTelefax CAdrTelefax,
    C.AdrEmail CAdrEmail,
    C.AdrEanCode CAdrEanCode,

    CL.lndInNAWBlok ClndInNAWBlok,
    ( if CL.lndInNAWblok = 1  then 1                        // bepaal of land moet worden afgedrukt
      else if CL.lndgid = @DefaultLndGid then 0
           else 1
           endif
      endif) CLandAfdrukken,
    BouwKIXCode(C.adrLndGid, CAdrPostcode, CAdrHuisnummer) as CKIXCode,
    CL.lndEigenCode ClndEigenCode,
    CL.lndOms ClndOms,
    CL.lndPlaatsHuisnr ClndPlaatsHuisnr,
    CL.lndPlaatsPostcode ClndPlaatsPostcode,
    CL.lndPostcodeMasker ClndPostcodeMasker,

    // ----------test of er selecties zijn
    (select first SlcCode from tabSelectiecodes inner Join tabSlcPerNaw on (SlcGid=SpnSlcGid) where (SpnNawFilGid = NawFilGid) ) SelCode,


    //-------------- order gegevens
    NAW.NawAparteFacturen orderGegNawAparteFacturen,
    NAW.NawFacturerenInclBtw orderGegNawFacturerenInclBtw,
    NAW.NawFactuurAdres orderGegNawFactuurAdres,
    //---verzendadres
    NAW.NawVerzendAdres orderGegVerzendAdresSoort,
    ( if @Rel= 0 then
        case NAW.NawVerzendAdres
        when 0 then
          @CorAdresTekst
        when 1 then
          @VestAdresTekst
        when 3 then
          @FactDebCorAdresTekst
        when 4 then
          @FactDebVestAdresTekst
        else//2: verzendadres, 5: factuurdebiteur-verzendadres
          (select adrOms from tabAdres where adrGid = NAW.NawGidVerzendAdres)
        end
      else null
      endif ) orderGegVerzAdresOms,
    ( if @Rel= 0 then
        if (NAW.NawVerzendAdres = 2) or (NAW.NawVerzendAdres = 5) then
          (select adrCode from tabAdres where adrGid = NAW.NawGidVerzendAdres)
        else null
        //else (1000+NAW.NawVerzendAdres)
        //JV,26 juli 2006: In dm werd gecheckt op getallen boven 1000, en weer een calculated field(qryStamKopcalcOrdGegVerzendAdres) bepaald
        //Dit werkt nu niet meer, dus veld NAW.NawVerzendAdres gaat nu mee in resultaatset(orderGegVerzendAdresSoort)
        endif
      else null
      endif ) orderGegVerzendAdres,
    //---eindbestemmingsadres
    NAW.NawEindAdres orderGegEindAdresSoort,
    ( if @Rel= 0 then
        case NAW.NawEindAdres
        when 0 then
          @CorAdresTekst
        when 1 then
          @VestAdresTekst
        when 3 then
          @NietVanToepassingTekst
        else//2: verzendadress
          (select adrOms from tabAdres where adrGid = NAW.NawGidEindAdres)
        end
      else null
      endif ) orderGegEindAdresOms,
    ( if @Rel= 0 then
        if (NAW.NawEindAdres = 2) then
          (select adrCode from tabAdres where adrGid = NAW.NawGidEindAdres)
        else null
        endif
      else null
      endif ) orderGegEindAdres,

    NAW.NawAantalKopieFacturen orderGegNawAantalKopieFacturen,
    NAW.NawOrderKorting orderGegNawOrderKorting,
    NAW.NawContributieCode orderGegNawContributieCode,
    (select ContributieOms from tabContributieCode where ContributieCode = NAW.NawContributieCode) orderGegNawContributieOms,
    NAW.NawBlokOrderInvoer orderGegNawBlokOrderInvoer,

    ( if @Rel= 0 then
      ( select first RapNummer from tabRapport join tabNawDocument on (rapGid=NawDocRapGidInclBTW) where NawDocNawGid=NawFilNawGid and NawDocDocSoort=50 and NawDocRegelSoort=0)
          else null
      endif ) orderGegRapNumIncl,
    ( if @Rel= 0 then
      ( select first Rapnaam   from tabRapport join tabNawDocument on (rapGid=NawDocRapGidInclBTW) where NawDocNawGid=NawFilNawGid and NawDocDocSoort=50 and NawDocRegelSoort=0)
      else null
      endif ) orderGegRapNaamIncl,

    ( if @Rel= 0 then
      ( select first RapNummer from tabRapport join tabNawDocument on (rapGid=NawDocRapGidExclBTW) where NawDocNawGid=NawFilNawGid and NawDocDocSoort=50 and NawDocRegelSoort=0)
      else null
      endif ) orderGegRapNumExcl,
    ( if @Rel= 0 then
      ( select first Rapnaam   from tabRapport join tabNawDocument on (rapGid=NawDocRapGidExclBTW) where NawDocNawGid=NawFilNawGid and NawDocDocSoort=50 and NawDocRegelSoort=0)
      else null
      endif ) orderGegRapNaamExcl,
    NawFilWebNaw orderGegWebNaw,
    DebGrpNr  orderGegDebGrpNr,
    DebGrpOms orderGegDebGrpOms,
    DebGrpOrderKorting orderGegDebGrpKorting,
    NawFilWelkeOrderkorting orderGegWelkeKorting,
    (Select DebNrFact.NawFilNummer from tabNawFile AS DebNrFact WHERE DebNrFact.NawfilnawGid          = NAW.NawIdFactDeb)    AS orderGegDebNummerFactuur,
    DebNaamFactuur.AdrNaam1 orderGegDebOmsFactuur,
    DebNaamFactuur.AdrNaam2 orderGegDebOmsFactuur2,
    (Select DebNrOmzet.NawFilNummer from tabNawFile AS DebNrOmzet WHERE DebNrOmzet.NawfilnawGid       = NAW.NawidDebOmzet)   AS orderGegDebNummerOmzet,
    DebNaamOmzet.AdrNaam1 orderGegDebOmsOmzet,
    DebNaamOmzet.AdrNaam2 orderGegDebOmsOmzet2,
    (Select DebNrPrijzen.NawFilNummer from tabNawFile AS DebNrPrijzen WHERE DebNrPrijzen.NawfilnawGid = NAW.NawidDebPrijzen) AS orderGegDebNummerPrijzen,
    DebNaamPrijzen.AdrNaam1 orderGegDebOmsPrijzen,
    DebNaamPrijzen.AdrNaam2 orderGegDebOmsPrijzen2,

    //-------------- financiële gegevens
    ( if @Rel= 0 then
      ( select nawfilBtcNummer from tabBetalingsConditie where nawfilBtcNummer = BtcNummer )
      else null
      endif ) FinGegBtcNummer,
    ( if @Rel= 0 then
      ( select BtcOms from tabBetalingsConditie where nawfilBtcNummer = BtcNummer )
      else null
      endif ) FinGegBtcOms,

    ( if @Rel= 0 then
      ( select nawfilLvcNummer from tabLeveringsConditie where nawfilLvcNummer = LvcNummer )
      else null
      endif ) FinGegLvcNummer,
    ( if @Rel= 0 then
      ( select LvcOms from tabLeveringsConditie where nawfilLvcNummer = LvcNummer )
      else null
      endif ) FinGegLvcOms,

    NawFilValNummer FinGegNawFilValNummer,
    ( if @Rel= 0 then
      ( select ValCode   from tabValuta where Valnummer = NawFilValnummer )
      else null
      endif ) FinGegValCode,
    ( if @Rel= 0 then
      ( select OmsValuta from tabValuta where Valnummer = NawFilValnummer )
      else null
      endif ) FinGegOmsValuta,
    NawfilBtwCode FinGegBTWCode,

    ( if @Rel= 0 then
      ( select RksNaam from tabRekeningSchema Inner join tabBtw on RksGid = BtwRksGid where  NawfilBtwCode = BtwCode )
      else null
      endif ) FinGegBtwOms,
    ( select TaalCode from tabTaal where NAW.nawTaalGid=taalGid )FinGegTaalCode,
    ( select TaalOms from tabTaal where NAW.nawTaalGid=taalGid ) FinGegTaalOms,

    ( if @Rel= 0 then
      ( if NawFilKredLimiet <> 0 then NawFilKredLimiet
        else ( select ValutaOmrekenen( @@BasisValutanummer, FonKredietLimiet, NawFilValNummer, @BjGid, @Pernr, 2)
               from tabFileOfNaw
               where FonGid = NawFilFonGid )
       endif)
      else null
      endif ) FinGegNawfilKredLimiet,

    ( if @Rel= 0 then
      ( if tabNawFile.NawFilKredLimiet <> 0 then 0 else 1 endif )
      else null
      endif ) FinGegKredLimIsStandaard,

    ( if @Rel= 0 then
      ( select T.RksNummer
        from ( tabRekeningSchema as F left outer join tabRekeningSchema as T  On T.RksGid = F.TegenRksGid )
        where F.RksGid = nawFilRksGid )
      else null
      endif ) FinGegTegenRekening,

    ( if @Rel= 0 then
      ( select T.RksNaam
        from ( tabRekeningSchema as F left outer join tabRekeningSchema as T  On T.RksGid = F.TegenRksGid )
        where F.RksGid = nawFilRksGid )
      else null
      endif ) FinGegTegRekNaam,

    NAW.nawAanmaningsType FinGegAanmaningsType,
    NAW.nawBtwNummer FinGegnawBtwNummer,                       //verwar niet met BWTcodes e.d.
		(if @FonId = 'B' then
				(select VgbaWaarde from tabVasteGegevensBelastingAangiftes where VgbaParameter = 'OBNummer')
    	else null
			endif) FinGegOBNummer,
    NAW.nawOnsDebiteurNummer FinGegNawOnsDebiteurNummer,
    0 FinGegNawFilAutoOSP,
		NAW.NawIncassantReferentie FinGegNawIncassantReferentie, NAW.NawBedrijfstak FinGegNawBedrijfstak,
    (case @SorterenOp
       when 0 then
         NawFilNummer
       when 1 then
         NawFilZoekcode + space(10 - length (NawFilZoekcode)) + NawFilNummer
       when 2 then
         Left(VlndEigenCode + Space(3),3) + Left(VAdrPostcode + space(40), 40) + NawFilNummer
       when 3 then
         Left(ClndEigenCode + Space(3),3) + Left(CAdrPostcode + space(40), 40) + NawFilNummer
       else
         right('000' + string(IsNull(VertegenWoordigerCode, -1)),3) + NawFilNummer
     end) sorteerveld
  from
    tabnawfile
    inner join tabnaw AS NAW on ( NAW.NawGid = NawFilNawGid )
    inner join tabFileOfNaw on ( FonId = @FonId and NawFilFonGid = FonGid )
    left outer join tabDebiteurGroepen on (DebGrpGid = NawFilDebGrpGid)

    left outer join (tabAdres as V inner join tabLand as VL on ( VL.lndGid = V.adrLndGid )) on ( NawGidVestiging = V.adrGid)        //vestigings adres
    left outer join (tabAdres as C inner join tabLand as CL on ( CL.lndGid = C.adrLndGid )) on ( nawgidcorrespondentie = C.adrGid)  //correspondentie adres
    left outer join (tabNaw AS DebNawFactuur inner join tabAdres AS DebNaamFactuur ON DebNaamFactuur.adrgid = DebNawFactuur.NawGidVestiging) ON DebNawFactuur.nawGid = NAW.NawIdFactDeb
    left outer join (tabNaw AS DebNawOmzet   inner join tabAdres AS DebNaamOmzet   ON DebNaamOmzet.adrgid   = DebNawOmzet.NawGidVestiging)   ON DebNawOmzet.nawGid   = NAW.NawidDebOmzet
    left outer join (tabNaw AS DebNawPrijzen inner join tabAdres AS DebNaamPrijzen ON DebNaamPrijzen.adrgid = DebNawPrijzen.NawGidVestiging) ON DebNawPrijzen.nawGid = NAW.NawidDebPrijzen

  where
    (( @SelecteerOp = 0 and nawfilnummer between @VanNaw and @TotNaw ) or ( @SelecteerOp = 1 and nawfilZoekCode between @VanNaw and @TotNaw ))
    and ( ( @AfdrukkenAlle = 1)
            or (
                  ( ( NAW.nawGid in (select distinct relNawGid from  tabrelatie )                        ) or ( locate ( @AfdrukkenSel,'0') = 0 ) )
              and ( ( NAW.nawGid in (select distinct adrNawGid from  tabadres where adrCode is not null) ) or ( locate ( @AfdrukkenSel,'1') = 0 ) )
              and ( ( NAW.nawGid in (select distinct nawRekNawGid from tabNawRekening)                   ) or ( locate ( @AfdrukkenSel,'2') = 0 ) )
              and ( (  NawOpmOpmerking <> ''                                                             ) or ( locate ( @AfdrukkenSel,'3') = 0 ) )
              and ( ( SelCode is not null                                                                ) or ( locate ( @AfdrukkenSel,'4') = 0 ) )
               )
         )

  order by
   (if @IsAscending <> 0 then Sorteerveld else '' endif),
   (if @IsAscending <> 0 then '' else Sorteerveld  endif) desc;


end;

//call rapStamGeg('D',1,1,0,'12000000','12000000',0,0)


create or replace procedure rapVariabeleBalans(
  in @BjGid            Integer,
  in @VanPernr         smallint,
  in @TotPernr         smallint,
  in @SelecteerOp      smallint, //0 = rksnummer, 1=rkszoekcode, 2=rksnaam
  in @VanRks           nchar(40), //van nummer/zoekcode/naam
  in @TotRks           nchar(40), //t/m nummer/zoekcode/naam
  in @BalCode          integer , //balanscode
  in @VanRubParSub     nchar(11), //van rub+par+sub; elementen die leeg zijn
  in @TotRubParSub     nchar(11), //van rub+par+sub; elementen die leeg zijn -> uitvullen met 3 spaties
  in @SoortBoeking     smallint, //0=definitief, 1=voorlopig, 2=beide
  in @OokNulSaldi      smallint, //0=Geen nulsaldi, 1=alle rekeningen, 2=als er geboekt is <>0
  in @Specificatie     smallint, //0=Grootboekrekening, 1=subparagraaf, 2=paragraaf, 3=rubriek, 4=conform balans
  in @BalansInValuta   integer,  //Valutanummer waarin balans moet worden afgedrukt
  in @TotalenInValuta  integer,  //Valutanummer voor subtotalen
  in @RekZonderBalCode smallint) //Rekening zonder balanscode ook afdrukken (0=nee 1=ja)

result (RubParSub nchar(20), OmsBalansCodeDetails nchar(40), LabelOmschrijving nchar(32), LabelBeginSaldo nchar(32), LabelEindSaldo nchar(32),
        RksInvoer nchar(28), RksNaam nchar(40), ValNummer integer, Valcode nchar(3),
        BeginBalansDebet numeric(15,2), BeginBalansCredit numeric(15,2), BeginBalansSaldo numeric(15,2),
        VorigDebet numeric(15,2),       VorigCredit numeric(15,2),       VorigSaldo numeric(15,2),
        HuidigDebet numeric(15,2),      HuidigCredit numeric(15,2),      HuidigSaldo numeric(15,2),
        ProefDebet numeric(15,2),       ProefCredit numeric(15,2),       ProefSaldo numeric(15,2),
        SaldiDebet numeric(15,2),       SaldiCredit numeric(15,2),       SaldiSaldo numeric(15,2),
        Verlies numeric(15,2),          Winst numeric(15,2),             ResultaatSaldo numeric(15,2),
        EindDebet numeric(15,2),        EindCredit numeric(15,2), EindSaldo numeric(15,2),
        RegelSoort integer, OptelStreepBoven smallint, DubbeleStreepOnder smallint, RedenSubtotaal smallint)

begin
  declare @Teller          smallint;
  declare @Koers           double;
  declare @BalansValCode   nchar(3);
  declare @TotaalValCode   nchar(3);
  declare @AantalDecimalen integer;
  declare @Dummy           nchar(11);
  declare @SaldoWinst      numeric(15,2);
  declare @OrigVanRubParSub nchar(11);
  declare @OrigTotRubParSub nchar(11);
  declare @Voorloop        nchar(40);
  declare @AfrondingB      numeric(15,2);
  declare @AfrondingV      numeric(15,2);
  declare @AfrondingH      numeric(15,2);
  declare @AfrondingR      numeric(15,2);
  declare @AfrondingE      numeric(15,2);
  declare @AfrondingP      numeric(15,2);
  declare @AfrondingS      numeric(15,2);
  declare @GeheleRangeSelectie smallint;
  declare @NumDeci integer;
  declare @SubTotaalAgvOmrekening smallint;
  declare @IsolationLevel         smallint;

  declare @SaldoWinstTekst      long nvarchar;
  declare @SaldoVerliesTekst    long nvarchar;
  declare @RubriekTekst         long nvarchar;
  declare @ParagraafTekst       long nvarchar;
  declare @SubParagraafTekst    long nvarchar;
  declare @GeenRubParSubTekst   long nvarchar;
  declare @DirectGekoppeldTekst long nvarchar;
  declare @OmrekenVerschil      long nvarchar;
  declare @VanRekTotRekTekst    long nvarchar;
  declare @SubtotaalTekst       long nvarchar;

  declare local temporary table tmpBalans(
     tmpGid                integer default AutoIncrement,
     RubParSub             nchar(11),
     RksInvoer             nchar(28),
     RksNaam               nchar(40) default '',
     DefaultSoort          smallint,
     ValNummer             integer,
     Valcode               nchar(3) default '',
     BeginDebet            numeric(15,2),
     BeginCredit           numeric(15,2),
     VorigDebet            numeric(15,2),
     VorigCredit           numeric(15,2),
     HuidigDebet           numeric(15,2),
     HuidigCredit          numeric(15,2),
     ProefDebet            numeric(15,2),
     ProefCredit           numeric(15,2),
     ProefSaldo            numeric(15,2),
     SaldiDebet            numeric(15,2),
     SaldiCredit           numeric(15,2),
     Verlies               numeric(15,2),
     Winst                 numeric(15,2),
     EindDebet             numeric(15,2),
     EindCredit            numeric(15,2),
     BalGid                integer,
     BalVerdicht           smallint default 0,
     AfdrukZijde           smallint default 0,
     BerekendeZijde        smallint  compute (if (AfdrukZijde = 0 or (AfdrukZijde=2 and (VorigDebet + HuidigDebet >= VorigCredit + HuidigCredit))) then 0 else 1 endif),
     RegelSoort            integer,
     Sortering             nchar(39),
     OptelStreepBoven      smallint default 0,
     DubbeleStreepOnder    smallint default 0,
     AltijdVanRubParSub    nchar(11),
     RedenSubtotaal        smallint,
     tmpHulpVolgorde       integer
  ) on commit preserve rows;


  set @@ErrorTextProcedure = 'rapVariabeleBalans > ';
  //call TraceBegin(@@ErrorTextProcedure + '@BjGid = ' + string(@BjGid) + ', @VanPernr = ' + string(@VanPernr) + ', @TotPernr = ' +string(@TotPernr));
  //call Trace('rapVariabeleBalans > @SelecteerOp='+string(@SelecteerOp)+', @VanRks='+@VanRks+', @TotRks='+@TotRks+', @BalCode='+string(@BalCode)+', @VanRubParSub='+@VanRubParSub+', @TotRubParSub='+@TotRubParSub);
  //call Trace('rapVariabeleBalans > @SoortBoeking='+string(@SoortBoeking)+', @OokNulSaldi='+string(@OokNulSaldi)+', @Specificatie='+string(@Specificatie)+', @BalansInValuta='+string(@BalansInValuta)+', @TotalenInValuta='+string(@TotalenInValuta)+', @RekZonderBalCode='+string(@RekZonderBalCode));

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 1';
  //call Trace(@@ErrorTextProcedure);

  set @OrigVanRubParSub = @VanRubParSub;
  set @OrigTotRubParSub = @TotRubParSub;
  set @TotRubParSub     = left(@TotRubParSub+'.999.999.999', 11);

  set @Koers = KoersTovBasisValuta(@BjGid, @TotPernr, @BalansInValuta);
  select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = @BalansInValuta;
  set @AantalDecimalen = 3;

  set @GeheleRangeSelectie = 0;
  if not exists(select 1 from tabRekeningSchema where not
                  ((@SelecteerOp = 0 and RksInvoer between @VanRks and @TotRks) or
                   (@SelecteerOp = 1 and RksZoekCode between @VanRks and @TotRks) or
                   (@SelecteerOp = 2 and RksNaam between @VanRks and @TotRks))) then
    //Ok, alle rekeningen geselecteerd
    if not exists(select 1 from tabBalanscodeDetail where DetailBlCode = @BalCode and (RubParSub < @OrigVanRubParSub)) then
      //call trace('Geen kleinere!');
      if not exists(select 1 from tabBalanscodeDetail where DetailBlCode = @BalCode and (RubParSub > @OrigTotRubParSub)) then
        set @@ErrorTextProcedure = 'rapVariabeleBalans > Geen grotere';
        //call Trace(@@ErrorTextProcedure);

        //Ok, alle balanscodes geselecteerd
        if @RekZonderBalCode = 1 then
          //Ook alle rekeningen zonder balanscodes
          set @GeheleRangeSelectie = 1;
        else
          //Niet alle rekeningen, dus controleren of er rekeningen zijn zonder balanscodes
          if not exists( select 1 from tabrekeningschema
                         where RksGid not in (select BlRksGid from tabBalansCodeRekening inner join tabBalansCodeDetail on (BlRekBlGid = BlGid)
                                              where BlRekBlCode = @BalCode and RubParSub between @VanRubParSub and @TotRubParSub)) then
            set @GeheleRangeSelectie = 1;
          end if;
        end if;
      end if;
    end if;
  end if;
  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 2, @GeheleRangeSelectie='+string(@GeheleRangeSelectie);
  //call Trace(@@ErrorTextProcedure);

  set @IsolationLevel = @@Isolation;
  set temporary option isolation_level = 'statement-snapshot';

  insert into tmpBalans (RegelSoort, Sortering, ValNummer, RksInvoer, RksNaam, DefaultSoort, AfdrukZijde, RubParSub,
                         BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit, ProefDebet, ProefCredit,
                         SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, BalVerdicht, AltijdVanRubParSub)
  select   1,
           left(isnull(RubParSub,'')+'.   .   .   ', 11)+RksInvoer,
           @BalansInValuta,
           RksInvoer,
           RksNaam,
           DefaultSoort,
           AfdrukZijde,
           IsNull(RubParSub, '   '),
           if @VanPernr>0 then 0 else round(IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) / @Koers, @NumDeci) endif BDebet,
           if @VanPernr>0 then 0 else round(IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = 0), 0) / @Koers, @NumDeci) endif BCredit,
           round(IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) / @Koers, @NumDeci) VDebet,
           round(IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr between @VanPernr and @TotPernr-1), 0) / @Koers, @NumDeci) VCredit,
           round(IsNull((select if @SoortBoeking = 0 then sum(SaldoDebetBasisDefinitief)  else if @SoortBoeking = 1 then sum(SaldoDebetBasisVoorlopig)  else sum(SaldoDebetBasisDefinitief) +sum(SaldoDebetBasisVoorlopig)  endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0) / @Koers, @NumDeci) HDebet,
           round(IsNull((select if @SoortBoeking = 0 then sum(SaldoCreditBasisDefinitief) else if @SoortBoeking = 1 then sum(SaldoCreditBasisVoorlopig) else sum(SaldoCreditBasisDefinitief)+sum(SaldoCreditBasisVoorlopig) endif endif from tabRekeningsaldo where RekSaldoRksGid = RksGid and RekSaldoBjGid = @BjGid and RekSaldoPernr = @TotPernr), 0) / @Koers, @NumDeci) HCredit,
           VDebet  + HDebet  ProefDebet,
           VCredit + HCredit ProefCredit,
           if (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif SaldiDebet,
           if (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif SaldiCredit,
           if DefaultSoort in (3,4,5)     and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif Verlies,
           if DefaultSoort in (3,4,5)     and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif Winst,
           if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 0 or (AfdrukZijde=2 and ProefDebet >= ProefCredit)) then (ProefDebet  - ProefCredit) else 0 endif EindDebet,
           if DefaultSoort in (0,1,2,6,7) and (AfdrukZijde = 1 or (AfdrukZijde=2 and ProefDebet <  ProefCredit)) then (ProefCredit - ProefDebet)  else 0 endif EindCredit,
          (if ((@Specificatie = 1) or (@Specificatie = 2) or (@Specificatie = 3)) then 1 else 0 endif) BalVerdicht,
           IsNull(RubParSub, '') AltijdVanRubParSub
  from     tabRekeningschema left outer join (tabBalansCodeRekening inner join tabBalansCodeDetail on (BlRekBlGid = BlGid)) on (BlRksGid = RksGid and DetailBlCode = @BalCode)
  where  (((RubParSub between @VanRubParSub and @TotRubParSub) and RubParSub is not null) or (@RekZonderBalCode = 1 and RubParSub is null)) and
          ((@SelecteerOp = 0 and RksInvoer   between @VanRks and @TotRks) or
           (@SelecteerOp = 1 and RksZoekcode between @VanRks and @TotRks) or
           (@SelecteerOp = 2 and RksNaam     between @VanRks and @TotRks))
            and
          ((@OokNulSaldi=1) or
           (@OokNulSaldi=2 and (RksGid in (select JrRksGid from tabJournaalRegel where JrPerNr between @VanPerNr and @TotPerNr and JrBjGid = @BjGid and
                                          ((@SoortBoeking = 0 and RegelNummer is not null) or
                                          (@SoortBoeking = 1 and RegelNummer is null) or
                                          (@SoortBoeking = 2))))) or
           //0-saldi niet afdrukken, dus begin+vorige+huidige optellen en die vergelijken, ook beginbalans etc. apart testen!!
           (@OokNulSaldi=0 and (isnull(ProefDebet,0)-isnull(ProefCredit,0) <> 0 or
                                isnull(BDebet,0) - isnull(BCredit,0) <> 0 or
                                isnull(VDebet,0) - isnull(VCredit,0) <> 0 or
                                isnull(SaldiDebet,0) - isnull(SaldiCredit,0) <> 0 or
                                isnull(HDebet,0) - isnull(HCredit,0) <> 0))
          );

  set temporary option isolation_level = @IsolationLevel;

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 3';
  //call Trace(@@ErrorTextProcedure);

  Create index idx_tmpBalansSoort     on tmpBalans (regelsoort);
  Create index idx_tmpBalansSortering on tmpBalans (Sortering);
  create index idx_tmpBal1 on tmpBalans (RksInvoer);

  //Subtotalen maken volgens aantal specificatie
  set @RubriekTekst         = _U('Rubriek');
  set @ParagraafTekst       = _U('Paragraaf');
  set @SubParagraafTekst    = _U('Subparagraaf');
  set @GeenRubParSubTekst   = _U('(Geen rub/par/sub)');
  set @DirectGekoppeldTekst = _U('(Direct gekoppeld)');

  select ValCode into @BalansValCode from tabValuta where ValNummer=@BalansInValuta;
  set @Teller = 3;
  while @Teller > 0 loop

    insert into tmpBalans (RegelSoort, Sortering, RubParSub, RksInvoer, RksNaam, ValNummer, ValCode,
                           BeginDebet, BeginCredit,
                           VorigDebet, VorigCredit,
                           HuidigDebet, HuidigCredit,
                           ProefDebet, ProefCredit,
                           SaldiDebet, SaldiCredit,
                           Verlies, Winst,
                           EindDebet, EindCredit, BalVerdicht, AltijdVanRubParSub)
    select   13-@Teller DezeRegelSoort,
             IsNull(tabBalanscodeDetail.RubParSub,'===')+'z' Sortering,
             IsNull(tabBalanscodeDetail.RubParSub,''),
             isnull(tabBalanscodeDetail.RubParSub,'') HulpRksInvoer,
             if DetailBlCode is null then
               if @teller = 1 then
                 @GeenRubParSubTekst
               else
                 @DirectGekoppeldTekst
               endif
             else
               if IsNull(OmsBalansCodeDetails, '' ) = '' then
                 case DezeRegelSoort
                 when 10 then
                   @SubParagraafTekst
                 when 11 then
                   @ParagraafTekst
                 else
                   @RubriekTekst
                 end
               else
                 OmsBalansCodeDetails
               endif
             endif BalOms,
             @BalansInValuta,
             @BalansValCode,
             sum(BeginDebet),   sum(BeginCredit),
             sum(VorigDebet),   sum(VorigCredit),
             sum(HuidigDebet),  sum(HuidigCredit),
             sum(ProefDebet),   sum(ProefCredit),
             sum(SaldiDebet),   sum(SaldiCredit),
             sum(Verlies),      sum(Winst),
             sum(EindDebet),    sum(EindCredit),
            (if (@Specificatie = 2 and length(IsNull(tabBalanscodeDetail.RubParSub,'   '))=11) or (@Specificatie = 3 and length(IsNull(tabBalanscodeDetail.RubParSub,'   '))>=7) then 1 else 0 endif),
             IsNull(tabBalanscodeDetail.RubParSub,'')
    from     tmpBalans
             left outer join tabBalanscodeDetail on (DetailBlCode = @BalCode and
                                                     tabBalanscodeDetail.RubParSub = substr(tmpBalans.RubParSub, 1, (@Teller*4)-1))
    where    length(tmpBalans.RubParSub)>=(@Teller*4)-1 and RegelSoort = 1
    group by HulpRksInvoer, tabBalanscodeDetail.RubParSub, BalOms, BalansVerdicht, DetailBlCode;

    set @Teller = @Teller - 1;

  end loop;

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 4';
  //call Trace(@@ErrorTextProcedure);

  if @Specificatie = 4 then  //Conform balans

    update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  DetailBlCode=@BalCode and tmpBalans.RubParSub=tabBalansCodeDetail.RubParSub and trim(IsNull(tmpBalans.RubParSub,'.'))<>'';  //Alle rubparsub die '' zijn niet overschrijven, wel rubparsub die null zijn

    update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  DetailBlCode=@BalCode and tmpBalans.RubParSub is null and RksInvoer=tabBalansCodeDetail.RubParSub and trim(IsNull(tmpBalans.RubParSub,'.'))<>'';  //Alle rubparsub die '' zijn niet overschrijven, wel rubparsub die null zijn

    set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 4a';
    //call Trace(@@ErrorTextProcedure);

    update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  BalGid is null and DetailBlCode=@BalCode and Rubriek = left(tabBalansCodeDetail.RubParSub,3) and Paragraaf = substr(tabBalansCodeDetail.RubParSub,4,3) and trim(IsNull(tmpBalans.RubParSub,'.'))<>'';

    set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 4b';
    //call Trace(@@ErrorTextProcedure);

    update tmpBalans set BalGid = BlGid, BalVerdicht = BalansVerdicht
    from   tabBalansCodeDetail
    where  BalGid is null and DetailBlCode=@BalCode and Rubriek = left(tabBalansCodeDetail.RubParSub,3) and Paragraaf='' and trim(IsNull(tmpBalans.RubParSub,'.'))<>'';

  end if;

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 5';
  //call Trace(@@ErrorTextProcedure);
  delete tmpBalans where BalVerdicht = 1 and (RegelSoort=1 or (@Specificatie<>4));

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 6';
  //call Trace(@@ErrorTextProcedure);

  //Als er een subparagraaf voor een rekeningregel staat van dezelfde paragraaf maar de rekening zelf valt niet in een subparagraaf, dan subparagraaf-regel tussenvoegen onder de regel
  //Hetzelfde geldt voor andere niveaus (dus 2x de lus uitvoeren: 1x voor rek. -> sub en 1x voor sub. -> par.!)
  set @RubriekTekst      = _U('Rubriek %1!');
  set @ParagraafTekst    = _U('Par. %1!');
  set @SubParagraafTekst = _U('Subpar. %1!');

  set @Teller = 0;
  while @Teller < 2 loop
    insert into tmpBalans (RegelSoort, Sortering, RubParSub, RksNaam, ValNummer, Valcode,
           VorigDebet, VorigCredit,
           HuidigDebet, HuidigCredit,
           ProefDebet, ProefCredit,
           SaldiDebet, SaldiCredit,
           Verlies, Winst,
           EindDebet, EindCredit,
           BeginDebet, BeginCredit,
           OptelStreepBoven, AltijdVanRubParSub)
    select min(if Regelsoort = 1 then 10 else RegelSoort + 1 endif) Ditregelsoort,
           AltijdVanRubParSub+'zz'+string(@teller),
           RubParSub,
           '('+
           case Ditregelsoort
           when 10 then _P(@RubriekTekst,      left(RubParSub,11))
           when 11 then _P(@ParagraafTekst,    left(RubParSub,7))
           when 12 then _P(@SubParagraafTekst, left(RubParSub,3))
           end+')',
           ValNummer,
           Valcode,
           sum(VorigDebet  ), sum(VorigCredit ),
           sum(HuidigDebet ), sum(HuidigCredit),
           sum(ProefDebet  ), sum(ProefCredit ),
           sum(SaldiDebet  ), sum(SaldiCredit ),
           sum(Verlies     ), sum(Winst       ),
           sum(EindDebet   ), sum(EindCredit  ),
           sum(BeginDebet  ), sum(BeginCredit ),
           if DitRegelSoort = 10 then 1 else 0 endif, //Alleen indien subparagraaf toegevoegd, anders geen streep
           RubParSub

    from   tmpBalans buiten
    where  exists (select 1
                   from   tmpBalans binnen
                   where  binnen.Sortering < buiten.Sortering and
                          binnen.RksInvoer like buiten.AltijdVanRubParSub+'%' and
                          binnen.Regelsoort > buiten.Regelsoort) //ok, bestaat ervoor!
           and //Er bestaat geen next-dieper niveau van?
           not exists (select 1
                   from    tmpBalans binnen
                   where   binnen.Sortering > buiten.Sortering and
                           binnen.AltijdVanRubParSub like buiten.RubParSub+'%' and
                           binnen.Regelsoort >= if buiten.Regelsoort = 1 then 10 else buiten.Regelsoort+1 endif) //bestaat niet erna!
    group by AltijdVanRubParSub, RubParSub, ValNummer, Valcode;

    //Rekeningen die direct aan een paragraaf/rubriek zijn geknoopt terwijl er ook subpar/paragrafen in de par/rubriek zijn
    insert into tmpBalans (RegelSoort, RubParSub, Sortering, RksInvoer, RksNaam, ValNummer, Valcode,
           VorigDebet, VorigCredit,
           HuidigDebet, HuidigCredit,
           ProefDebet, ProefCredit,
           SaldiDebet, SaldiCredit,
           Verlies, Winst,
           EindDebet, EindCredit,
           BeginDebet, BeginCredit,
           AltijdVanRubParSub, OptelstreepBoven)
    select 11+@teller Ditregelsoort,
           left(AltijdVanRubParSub, case Ditregelsoort when 12 then 3 else 7 end) RubriekOfParagraafNr,
           left(RubriekOfParagraafNr+'.   .   .   ', 11)+'xz'+string(@teller) Volgorde,
           RubriekOfParagraafNr+' ' Invoer,
           if Ditregelsoort = 0 then // Niet aan een regel gekoppeld, dus ook niet aan een rub/par/sub gekoppeld
             @GeenRubParSubTekst
           else
             @DirectGekoppeldTekst
           endif,
           @BalansInValuta,
           @BalansValCode,
           sum(VorigDebet  ), sum(VorigCredit ),
           sum(HuidigDebet ), sum(HuidigCredit),
           sum(ProefDebet  ), sum(ProefCredit ),
           sum(SaldiDebet  ), sum(SaldiCredit ),
           sum(Verlies     ), sum(Winst       ),
           sum(EindDebet   ), sum(EindCredit  ),
           sum(BeginDebet  ), sum(BeginCredit ),
           RubriekOfParagraafNr AltijdRubParSubInvoegen,
           1
    from   tmpBalans buiten
    where  Regelsoort = 1  //11+@teller //Alleen voor paragrafen en rubrieken!
           and exists(select 1  //Er zijn rekeningen aan de rubriek/par. geknoopt
                      from tmpBalans binnen
                      where binnen.regelsoort=1   //Het zijn rekeningen
                            and length(binnen.AltijdVanRubParSub)= length(RubriekOfParagraafNr)  //geknoopt aan rubriek(teller=0)/paragraaf(teller=1)
                            and binnen.rubparsub = RubriekOfParagraafNr) //aan deze rubriek(teller=0)/paragraaf(teller=1) geknoopt
           and exists(select 1  //Er zijn ook nog andere subpar./par. aan de rubriek of par. geknoopt
                      from tmpBalans binnen
                      where binnen.regelsoort<>1
                            and binnen.AltijdVanRubParSub like RubriekOfParagraafNr+'.%')
                            and length(AltijdVanRubParSub) = case Ditregelsoort when 12 then 3 else 7 end
    group by length(AltijdVanRubParSub), RubriekOfParagraafNr, Volgorde, Invoer, ValNummer, Valcode, AltijdRubParSubInvoegen;

    set @Teller = @Teller + 1;

  end loop;
  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 7';
  //call Trace(@@ErrorTextProcedure);

  //Subtotalen omrekenen naar juiste valuta
  select ValCode into @TotaalValCode from tabValuta where ValNummer=@TotalenInValuta;
  if @BalansInValuta <> @TotalenInValuta then
    set @Koers = KoersTovBasisValuta(@BjGid, @TotPernr, @BalansInValuta) / KoersTovBasisValuta(@BjGid, @TotPernr, @TotalenInValuta);
    select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = @TotalenInValuta;
    insert into tmpBalans (RegelSoort, Sortering, RubParSub, AltijdVanRubParSub, RksInvoer, RksNaam, ValNummer, ValCode, BalVerdicht,
                           BeginDebet, BeginCredit,
                           VorigDebet, VorigCredit,
                           HuidigDebet, HuidigCredit,
                           ProefDebet, ProefCredit,
                           SaldiDebet, SaldiCredit,
                           Verlies, Winst,
                           EindDebet, EindCredit)
    select   6+RegelSoort,
             Sortering+'z',
             RubParSub,
             AltijdVanRubParSub,
             RksInvoer,
             RksNaam,
             @TotalenInValuta,
             @TotaalValCode,
             BalVerdicht,
             round(@Koers * BeginDebet,   @NumDeci), round(@Koers * BeginCredit,  @NumDeci),
             round(@Koers * VorigDebet,   @NumDeci), round(@Koers * VorigCredit,  @NumDeci),
             round(@Koers * HuidigDebet,  @NumDeci), round(@Koers * HuidigCredit, @NumDeci),
             round(@Koers * ProefDebet,   @NumDeci), round(@Koers * ProefCredit,  @NumDeci),
             round(@Koers * SaldiDebet,   @NumDeci), round(@Koers * SaldiCredit,  @NumDeci),
             round(@Koers * Verlies,      @NumDeci), round(@Koers * Winst,        @NumDeci),
             round(@Koers * EindDebet,    @NumDeci), round(@Koers * EindCredit,   @NumDeci)
    from     tmpBalans
    where    RegelSoort between 10 and 15;

  end if;

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 8';
  //call Trace(@@ErrorTextProcedure);

  //---------- Optelstrepen zetten ----------
  //Hoe? -> Bepaal per regel alles wat eronder zit. Als het dezelfde diepte heeft en de diepte is niet gelijk aan de huidige regel, dan een streep
  update tmpBalans tmp
  set OptelStreepBoven =
     if 1 =(select count(distinct if binnen.Regelsoort = 1 then 99 else 30+length(binnen.RksInvoer) endif)
             from   tmpBalans binnen
             where  ((binnen.AltijdVanRubParSub =  '' and tmp.RksInvoer =  '') or
                     (binnen.AltijdVanRubParSub <> '' and tmp.RksInvoer <> '' and binnen.AltijdVanRubParSub like tmp.RksInvoer + '%'))
                    and binnen.valnummer = @BalansInValuta
                    and binnen.tmpGid <> tmp.tmpGid
            ) then 1 else 0 endif
  where regelsoort <> 1 and OptelStreepBoven=0
        and valnummer = @BalansInValuta; //Alleen indien saldo in zelfde valuta als balans

  //---------- Dubbele totaalstrepen zetten ----------

  //Opnieuw nummers uitdelen om dubbele strepen te zetten
  update tmpBalans
  set    tmpHulpVolgorde = number(*)
  order by Sortering;
  Create index idx_tmpHulpVolgorde on tmpBalans (tmpHulpVolgorde);

  //Als volgende regel een DIEPER niveau heeft, dan dubbele streep zetten
  update tmpBalans buiten
  set    buiten.DubbeleStreepOnder = 1
  where  buiten.DubbeleStreepOnder = 0 and
         (valnummer <> @BalansInValuta or //Als dit een andere valuta is, dan altijd een dubbele streep
          1=(select first 1
             from   tmpBalans volgende
             where  volgende.tmpHulpVolgorde=buiten.tmpHulpVolgorde+1 and
                    if volgende.Regelsoort = 1 then 99 else 30+length(volgende.RksInvoer) endif > if buiten.Regelsoort = 1 then 99 else 30+length(buiten.RksInvoer) endif)
         );

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 9';
  //call Trace(@@ErrorTextProcedure);

  //Alle regels waarvoor geldt dat een dieper niveau al een enkele of een dubbele streep heeft krijgt ook een dubbele streep
  //Let op: dit MOET meerdere malen worden uitgevoerd, dus niet optimaliseren tot 1 query!
  set @Teller = 1;
  while @Teller <= 12 loop //Alleen de 'gewone' valutaregels; er zijn toch maximaal evenveel andere valuta-regels
    if exists( select first 1 from tmpBalans where regelsoort = @teller) then
      update tmpBalans buiten
      set    DubbeleStreepOnder = 1
      where
             1=isnull((select first 1
                       from tmpBalans binnen
                       where ((binnen.AltijdVanRubParSub =  '' and buiten.RksInvoer =  '') or
                              (binnen.AltijdVanRubParSub <> '' and buiten.RksInvoer <> '' and binnen.AltijdVanRubParSub like buiten.rksinvoer+'%'))
                             and binnen.OptelStreepBoven + binnen.DubbeleStreepOnder >= 1
                             and binnen.regelsoort <> 1
                      ),0)
             and regelsoort <> 1
             and ValNummer = @TotalenInValuta; //Alleen voor de onderste (sub)totaalregel (let op: ook als er maar 1 valuta is werkt dit!)

    end if;
    if @teller = 1 then
      set @Teller = 10
    else
      set @Teller = @Teller + 1;
    end if;
  end loop;

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 10';
  //call Trace(@@ErrorTextProcedure);
  if @BalansInValuta <> @TotalenInValuta then
    //Eventueel nog wat enkele streepjes verwijderen als op een dieper niveau toch enkele of dubbele strepen staan
    update tmpBalans buiten
    set OptelStreepBoven =
       if 1 = isnull((select first 1
               from   tmpBalans binnen
               where  ((binnen.AltijdVanRubParSub =  '' and buiten.RksInvoer =  '') or
                       (isnull(binnen.AltijdVanRubParSub,'') <> '' and buiten.RksInvoer <> '' and binnen.AltijdVanRubParSub like buiten.RksInvoer + '%'))
                      and binnen.tmpGid <> buiten.tmpGid
                      and not (binnen.RksInvoer = buiten.RksInvoer and binnen.rksnaam = buiten.rksnaam) //Als het dezelfde regel maar een andere valuta betreft, dan niet meetellen!
                      and (binnen.OptelStreepBoven = 1 or binnen.DubbeleStreepOnder = 1)
              ),0) then 0 else 1 endif
    where OptelStreepBoven = 1
          and regelsoort <> 1
          and valnummer = @BalansInValuta; //Alleen indien saldo in zelfde valuta als balans (andere regels kunnen nooit een optelstreep hebben
  end if;

  set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 11';
  //call Trace(@@ErrorTextProcedure);

  //de allerlaatste regel ook een dubbele streep
  update tmpBalans
  set DubbeleStreepOnder = 1
  where Sortering = (select max(Sortering) from tmpBalans);

  set @Voorloop = 'ZZZZZZZZZZZZZZZZZZZZZZZZZ';

  //De rest alleen als er regels zijn!
  if exists(select 1 from tmpBalans) then
    //Saldo winst bepalen voor de kolommenbalans
    set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 11a';
    //call Trace(@@ErrorTextProcedure);
    //Saldo winst/verlies
    set @SaldoWinstTekst   = _U('Saldo winst');
    set @SaldoVerliesTekst = _U('Saldo verlies');

    select sum(Winst - Verlies) into @SaldoWinst from tmpBalans where regelsoort = 12 and ((RksNaam <> @GeenRubParSubTekst) and RksNaam <> @DirectGekoppeldTekst or RksInvoer = '');

    insert into tmpBalans(RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                          Verlies, Winst, EindDebet, EindCredit)
    values( 35 + if isnull(@SaldoWinst,0) < 0 then 1 else 0 endif, @Voorloop+'12E',
            if isnull(@SaldoWinst,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
            @BalansInValuta, @BalansValCode,
            if @SaldoWinst >= 0 then     @SaldoWinst endif,  if @SaldoWinst < 0 then abs(@SaldoWinst) endif,
            if @SaldoWinst <= 0 then abs(@SaldoWinst) endif, if @SaldoWinst > 0 then     @SaldoWinst  endif);
    if @BalansInValuta <> @TotalenInValuta then
      //Ook in andere valuta
      select sum(Winst - Verlies) into @SaldoWinst from tmpBalans where regelsoort = 18 and ((RksNaam <>  @GeenRubParSubTekst and RksNaam <> @DirectGekoppeldTekst) or RksInvoer = '');
      insert into tmpBalans(RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                            Verlies, Winst, EindDebet, EindCredit)
      values( 37 + if isnull(@SaldoWinst,0) < 0 then 1 else 0 endif, @Voorloop+'18E',
              if isnull(@SaldoWinst,0) >= 0 then @SaldoWinstTekst else @SaldoVerliesTekst endif,
              @TotalenInValuta, @TotaalValCode,
              if @SaldoWinst >= 0 then     @SaldoWinst endif,  if @SaldoWinst < 0 then abs(@SaldoWinst) endif,
              if @SaldoWinst <= 0 then abs(@SaldoWinst) endif, if @SaldoWinst > 0 then     @SaldoWinst  endif);
    end if;

    set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 12';
    //call Trace(@@ErrorTextProcedure);

    //Bepaal omrekenverschillen agv. afdrukken in andere valuta
    set @OmrekenVerschil = _U('(Omrekenverschil)');
    set @SubtotaalTekst  = _U('Subtotaal');

    set @Teller = 1; //1=balansvaluta, 2=andere valuta
    while @Teller <= 2 loop
      set @AfrondingB = 0;
      set @AfrondingV = 0;
      set @AfrondingH = 0;
      set @AfrondingR = 0;
      set @AfrondingP = 0;
      set @AfrondingS = 0;
      set @AfrondingE = 0;
      if @BalansInValuta <> @@BasisValutaNummer or @TotalenInValuta <> @BalansInValuta then
        select if DecimalenBoeking <> 0 then 2 else 0 endif into @NumDeci from tabValuta where ValNummer = (if @teller = 1 then @BalansInValuta else @TotalenInValuta endif);
        if @GeheleRangeSelectie = 1 then
          select sum(round(isnull(BeginDebet,0)-isnull(BeginCredit,0), @numDeci)),
                 sum(round(vorigdebet,  @numDeci)) - sum(round(vorigcredit,  @numDeci)),
                 sum(round(huidigDebet, @numDeci)) - sum(round(HuidigCredit, @numDeci)),
                 sum(round(ProefDebet,  @numDeci)) - sum(round(ProefCredit,  @numDeci)),
                 sum(round(Verlies,     @numDeci)) - sum(round(Winst,        @numDeci)),
                 sum(round(SaldiDebet,  @numDeci)) - sum(round(SaldiCredit,  @numDeci)),
                 sum(round(EindDebet,   @numDeci)) - sum(round(EindCredit,   @numDeci))
          into   @AfrondingB, @AfrondingV, @AfrondingH, @AfrondingP, @AfrondingR, @AfrondingS, @AfrondingE
          from   tmpBalans
          where  ((@teller = 1 and regelsoort in (12, 35, 36)) or
                  (@teller = 2 and regelsoort in (18, 37, 38)))
                 and ((RksNaam <> _@GeenRubParSubTekst and RksNaam <> @DirectGekoppeldTekst) or RksInvoer = '');
          set @AfrondingE = isnull(@AfrondingE,0) + isnull(@AfrondingR,0);
          //call Trace('@teller='+string(@Teller)+', @numDeci='+string(@numDeci)+', @AfrondingB='+string(@AfrondingB)+', @AfrondingV='+string(@AfrondingV)+', @AfrondingH='+string(@AfrondingH)+', @AfrondingR='+string(@AfrondingR)+', @AfrondingS='+string(@AfrondingS)+', @AfrondingE='+string(@AfrondingE));

          if isnull(@afrondingB,0) <> 0 or isnull(@afrondingV,0) <> 0 or isnull(@afrondingH,0) <> 0 or isnull(@AfrondingP,0) <> 0 or isnull(@AfrondingS,0) <> 0 or isnull(@AfrondingE,0) <> 0 then

            insert into tmpBalans(
              RegelSoort,  Sortering, RksNaam, ValNummer, ValCode,
              BeginDebet,  BeginCredit,
              vorigdebet,  vorigcredit,
              huidigDebet, HuidigCredit,
              ProefDebet,  ProefCredit,
              SaldiDebet,  SaldiCredit,
              EindDebet,   EindCredit)
            values( if @teller = 1 then 39 else 40 endif, @Voorloop+if @teller = 1 then '12G' else '18G' endif,
                    @OmrekenVerschil,
                    if @teller = 1 then @BalansInValuta else @TotalenInValuta endif,
                    if @teller = 1 then @BalansValCode else @TotaalValCode endif,
                    if @AfrondingB < 0 then abs(@AfrondingB) endif, if @AfrondingB > 0 then @AfrondingB endif,
                    if @AfrondingV < 0 then abs(@AfrondingV) endif, if @AfrondingV > 0 then @AfrondingV endif,
                    if @AfrondingH < 0 then abs(@AfrondingH) endif, if @AfrondingH > 0 then @AfrondingH endif,
                    if @AfrondingP < 0 then abs(@AfrondingP) endif, if @AfrondingP > 0 then @AfrondingP endif,
                    if @AfrondingS < 0 then abs(@AfrondingS) endif, if @AfrondingS > 0 then @AfrondingS endif,
                    if @AfrondingE < 0 then abs(@AfrondingE) endif, if @AfrondingE > 0 then @AfrondingE endif);
          end if;
        end if;

      end if; // Berekening omrekenverschillen

      // Subtotaal toevoegen
      set @SubTotaalAgvOmrekening = 0;
      if isnull(@afrondingB,0) <> 0 or isnull(@afrondingV,0) <> 0 or isnull(@afrondingH,0) <> 0 or isnull(@AfrondingP,0) <> 0 or isnull(@AfrondingS,0) <> 0 or isnull(@AfrondingE,0) <> 0 then
        set @SubTotaalAgvOmrekening = 1;
      end if;
      //kolommenbalans of we hebben een omreken-afronding, maar altijd het subtotaal erbij
      insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                             BeginDebet, BeginCredit, VorigDebet, VorigCredit, HuidigDebet, HuidigCredit,
                             ProefDebet, ProefCredit, SaldiDebet, SaldiCredit, Verlies, Winst, EindDebet, EindCredit, RedenSubtotaal)
      select   RegelSoort+10, @Voorloop+string(RegelSoort)+'D', @SubtotaalTekst,
               if RegelSoort = 12 then @BalansInValuta else @TotalenInValuta endif,
               if RegelSoort = 12 then @BalansValCode else @TotaalValCode endif,
               round(sum(BeginDebet),  @numDeci), round(sum(BeginCredit),  @numDeci),
               round(sum(VorigDebet),  @numDeci), round(sum(VorigCredit),  @numDeci),
               round(sum(HuidigDebet), @numDeci), round(sum(HuidigCredit), @numDeci),
               round(sum(ProefDebet),  @numDeci), round(sum(ProefCredit),  @numDeci),
               round(sum(SaldiDebet),  @numDeci), round(sum(SaldiCredit),  @numDeci),
               round(sum(Verlies),     @numDeci), round(sum(Winst),        @numDeci),
               round(sum(EindDebet),   @numDeci), round(sum(EindCredit),   @numDeci),
               @SubTotaalAgvOmrekening
      from     tmpBalans
      where    (@teller = 1 and RegelSoort = 12) or
               (@teller = 2 and RegelSoort = 18)
               and ((RksNaam <> @GeenRubParSubTekst and RksNaam <> @DirectGekoppeldTekst) or RksInvoer = '')
      group by RegelSoort;

      set @Teller = @Teller + 1;
    end loop;

    set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 13';
    //call Trace(@@ErrorTextProcedure);

    set @VanRekTotRekTekst = _U('van rek. %1! t/m %2!');
    if @BalansInValuta <> @TotalenInValuta then
      //Totaal generaal in andere valuta
      insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                             BeginDebet,  BeginCredit,
                             VorigDebet,  VorigCredit,
                             HuidigDebet, HuidigCredit,
                             ProefDebet,  ProefCredit,
                             SaldiDebet,  SaldiCredit,
                             Verlies,     Winst,
                             EindDebet,   EindCredit,
                             OptelStreepBoven)
      select   99, @Voorloop+'18Z', _P(@VanRekTotRekTekst, @VanRks, @TotRks),
               @TotalenInValuta,
               @TotaalValCode,
               sum(BeginDebet),  sum(BeginCredit),
               sum(VorigDebet),  sum(VorigCredit),
               sum(HuidigDebet), sum(HuidigCredit),
               sum(ProefDebet),  sum(ProefCredit),
               sum(SaldiDebet),  sum(SaldiCredit),
               sum(Verlies),     sum(Winst),
               sum(EindDebet),   sum(EindCredit),
               0
      from     tmpBalans
      where    RegelSoort in (18, 37, 38, 40)
               and ((RksNaam <> @GeenRubParSubTekst and RksNaam <> @DirectGekoppeldTekst) or RksInvoer = '')
    end if;

    set @@ErrorTextProcedure = 'rapVariabeleBalans > Stap 14';
    //call Trace(@@ErrorTextProcedure);

    //Totaal generaal
    insert into tmpBalans (RegelSoort, Sortering, RksNaam, ValNummer, ValCode,
                           BeginDebet,  BeginCredit,
                           VorigDebet,  VorigCredit,
                           HuidigDebet, HuidigCredit,
                           ProefDebet,  ProefCredit,
                           SaldiDebet,  SaldiCredit,
                           Verlies,     Winst,
                           EindDebet,   EindCredit,
                           OptelStreepBoven)
    select   98 , @Voorloop+'12Z', _P(@VanRekTotRekTekst, @VanRks, @TotRks),
             @BalansInValuta,
             @BalansValCode,
             sum(BeginDebet),  sum(BeginCredit),
             sum(VorigDebet),  sum(VorigCredit),
             sum(HuidigDebet), sum(HuidigCredit),
             sum(ProefDebet),  sum(ProefCredit),
             sum(SaldiDebet),  sum(SaldiCredit),
             sum(Verlies),     sum(Winst),
             sum(EindDebet),   sum(EindCredit),
             0
    from     tmpBalans
    where    RegelSoort in (12, 35, 36, 39)
             and ((RksNaam <> @GeenRubParSubTekst and RksNaam <> @DirectGekoppeldTekst) or RksInvoer = '')
  end if; //Einde 'als er regels zijn'

  set @@ErrorTextProcedure = 'rapVariabeleBalans';
  //call TraceEind(@@ErrorTextProcedure);

  select tmp.RubParSub RubParSub, OmsBalansCodeDetails, LabelOmschrijving, LabelBeginSaldo, LabelEindSaldo,
         RksInvoer, RksNaam, ValNummer, Valcode,
         BeginDebet BeginBalansDebet, BeginCredit BeginBalansCredit, isnull(BeginDebet,0)-isnull(BeginCredit,0) BeginBalansSaldo,
         VorigDebet,  VorigCredit,  VorigDebet  - VorigCredit  VorigSaldo,
         HuidigDebet, HuidigCredit, HuidigDebet - HuidigCredit HuidigSaldo,
         ProefDebet,  ProefCredit,  ProefDebet  - ProefCredit  ProefSaldo,
         SaldiDebet,  SaldiCredit,  SaldiDebet  - SaldiCredit  SaldiSaldo,
         Verlies,     Winst,        Verlies     - Winst        ResultaatSaldo,
         EindDebet,   EindCredit,   EindDebet   - EindCredit   EindSaldo,
         RegelSoort, OptelStreepBoven, DubbeleStreepOnder, RedenSubtotaal
  from   tmpBalans tmp
  left outer join tabBalansCodeDetail BCD on BCD.DetailBlCode = @BalCode and tmp.RubParSub = BCD.RubParSub
  order by Sortering;


end;

//call RapVariabeleBalans(1, 0, 12, 0, '0', '1199999', 2, '         ', '999999999', 0, 0, 0, 0, 1, 1)


//$Workfile: ReceptComponentVerplaatsRegelNr.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// **********************************************
// Recept: Component: verplaatsen regel
// **********************************************

if exists (select 1 from sys.sysProcedure where proc_name='ReceptComponentVerplaatsRegelNr') then
  drop procedure ReceptComponentVerplaatsRegelNr;
end if;

create procedure ReceptComponentVerplaatsRegelNr(
 in @RcptGid    integer,
 in @VanRegelNr  integer,   // Vanaf welk regelnummer verplaatsen
 in @NaarRegelNr integer    // Naar  welk regelnummer verplaatsen
)
begin
  set @@ErrorTextProcedure = 'ReceptComponentVerplaatsRegelNr(@RcptGid='+string(@RcptGid)+', @VanRegelNr=' + string(@VanRegelNr)+', @NaarRegelNr=' + string(@NaarRegelNr) + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @VanRegelNr <> @NaarRegelNr then
    // Eerst de betreffende regel een speciaal nummer geven

    update tabReceptuurComponent
    set    RcpcRegelNr = 999999
    where  RcpcRcptGid = @RcptGid
       and RcpcRegelNr = @VanRegelNr;

    if @VanRegelNr < @NaarRegelNr then
      // Naar beneden verplaatsen
      // Geef vanaf regel VanRegelNr+1 tot NaarRegelNr de regels 1 nummer lager
      update tabReceptuurComponent
      set    RcpcRegelNr = RcpcRegelNr - 1
      where  RcpcRcptGid = @RcptGid
         and RcpcRegelNr >  @VanRegelNr
         and RcpcRegelNr <= @NaarRegelNr
      order by RcpcRegelNr ;
    else
      // Naar boven verplaatsen
      update tabReceptuurComponent
      set    RcpcRegelNr = RcpcRegelNr + 1
      where  RcpcRcptGid = @RcptGid
         and RcpcRegelNr >= @NaarRegelNr
         and RcpcRegelNr <  @VanRegelNr
      order by RcpcRegelNr desc;
    end if;

    // Als laatste de hernoemde keurig in het rijtje zetten
    update tabReceptuurComponent
    set    RcpcRegelNr = @NaarRegelNr
    where  RcpcRcptGid = @RcptGid
       and RcpcRegelNr = 999999;

  end if;

  set @@ErrorTextProcedure = 'ReceptComponentVerplaatsRegelNr(@RcptGid='+string(@RcptGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ReceptEindproductVerplaatsRegelNr.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// **********************************************
// Recept: Eindproduct: verplaatsen regel
// **********************************************

if exists (select 1 from sys.sysProcedure where proc_name='ReceptEindproductVerplaatsRegelNr') then
  drop procedure ReceptEindproductVerplaatsRegelNr;
end if;

create procedure ReceptEindproductVerplaatsRegelNr(
 in @RcptGid    integer,
 in @VanRegelNr  integer,   // Vanaf welk regelnummer verplaatsen
 in @NaarRegelNr integer    // Naar  welk regelnummer verplaatsen
)
begin
  set @@ErrorTextProcedure = 'ReceptEindproductVerplaatsRegelNr(@RcptGid='+string(@RcptGid)+', @VanRegelNr=' + string(@VanRegelNr)+', @NaarRegelNr=' + string(@NaarRegelNr) + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @VanRegelNr <> @NaarRegelNr then
    // Eerst de betreffende regel een speciaal nummer geven

    update tabReceptuurEindproduct
    set    RcpeRegelNr = 999999
    where  RcpeRcptGid = @RcptGid
       and RcpeRegelNr = @VanRegelNr;

    if @VanRegelNr < @NaarRegelNr then
      // Naar beneden verplaatsen
      // Geef vanaf regel VanRegelNr+1 tot NaarRegelNr de regels 1 nummer lager
      update tabReceptuurEindproduct
      set    RcpeRegelNr = RcpeRegelNr - 1
      where  RcpeRcptGid = @RcptGid
         and RcpeRegelNr >  @VanRegelNr
         and RcpeRegelNr <= @NaarRegelNr
      order by RcpeRegelNr ;
    else
      // Naar boven verplaatsen
      update tabReceptuurEindproduct
      set    RcpeRegelNr = RcpeRegelNr + 1
      where  RcpeRcptGid = @RcptGid
         and RcpeRegelNr >= @NaarRegelNr
         and RcpeRegelNr <  @VanRegelNr
      order by RcpeRegelNr desc;
    end if;

    // Als laatste de hernoemde keurig in het rijtje zetten
    update tabReceptuurEindproduct
    set    RcpeRegelNr = @NaarRegelNr
    where  RcpeRcptGid = @RcptGid
       and RcpeRegelNr = 999999;

  end if;

  set @@ErrorTextProcedure = 'ReceptEindproductVerplaatsRegelNr(@RcptGid='+string(@RcptGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure ReceptKopieren
(
  in  @BronRcptGid           integer,
  in  @NieuwRcptCode	       nchar(20),
  in  @ComponentenKopieren   smallint,
  in  @EindproductenKopieren smallint,
  out @NieuwRcptGid          integer
)
begin
  // *********************************************************************************************
  // Recept: kopieren naar de opgegeven receptcode.
  // *********************************************************************************************

  //call TraceBegin('ReceptKopieren > @BronRcptGid = ' + string(@BronRcptGid) + ', @NieuwRcptCode = ' + @NieuwRcptCode);

  //TG 06-11-2006: Vooralsnog alles gewoon altijd kopieren!
  set @ComponentenKopieren   = 1;
  set @EindproductenKopieren = 1;

  if not exists(select 1 from tabReceptuur where RcptGid = @BronRcptGid) then
    Raiserror 20292;
  end if;

  insert into tabReceptuur with auto name
  select
    @NieuwRcptCode RcptCode,
    RcptZoekcode,
    RcptSoort,
    RcptGeblokkeerd,
    RcptOmschrijving,
    RcptOpmerking,
    RcptDocument,
    RcptBatchDefault,
    RcptBatchMaximum,
    RcptBatchMinimum,
    RcptPrijsBatchAantal,
    RcptPrijsBatchGrootte,
    RcptRksGid,
    RcptDefaultProductieOrderStatus,
    RcptVulAantalDezeVerwerkingComponent,
    RcptVulAantalDezeVerwerkingEindproduct,
    RcptAparteProductieOrdersPerRecept,
	RcptBatchProductieGrootte
  from
    tabReceptuur
  where
    tabReceptuur.RcptGid = @BronRcptGid;

  //nieuwe RcptGid 'onthouden'.
  set @NieuwRcptGid = @@Identity;

  if @ComponentenKopieren = 1 then
    //call Trace('ReceptKopieren > tabReceptuurComponent');
    insert into tabReceptuurComponent with auto name
    select
      @NieuwRcptGid RcpcRcptGid,
      RcpcArtGid,
      RcpcOmschrijving,
      RcpcRegelNr,
      RcpcRegelsoort,
      RcpcAantal,
      RcpcVerbruik,
      RcpcVerbruikAantal
    from
      tabReceptuurComponent
    where
      tabReceptuurComponent.RcpcRcptGid = @BronRcptGid;
  end if;

  if @EindproductenKopieren = 1 then
    //call Trace('ReceptKopieren > tabReceptuurEindproduct');
    insert into tabReceptuurEindproduct with auto name
    select
      @NieuwRcptGid RcpeRcptGid,
      RcpeArtGid,
      RcpeAantal,
      RcpeRegelNr,
      RcpeBerekenArtKostprijsBerekening,
      RcpeBerekenArtKostprijsPercentage,
      RcpeBerekenArtVerkoopprijsBerekening,
      RcpeBerekenArtVerkoopprijsPercentage
    from
      tabReceptuurEindproduct
    where
      tabReceptuurEindproduct.RcpeRcptGid = @BronRcptGid;
  end if;

  begin
    declare @VrBestandOms nchar(3) = 'RCP';
    declare @GroepsId integer = 0;
    call VrKopieerRecord(@VrBestandOms, @GroepsId, @GroepsId, @VrBestandOms, @GroepsId, @GroepsId, @BronRcptGid, @NieuwRcptGid);
  end;


  //call TraceEind('ReceptKopieren > @NieuwRcptCode = ' + @NieuwRcptCode);
end;


//$Workfile: ReceptPrijsInformatie.sp $ $Revision: 4 $ $Modtime: 31-08-07 15:54 $'

//TG 13-06-2006: Berekenen prijsinformatie van opgegeven recept
//MR 11-jun-2007 Bug# 26234: Er werd te vroeg afgerond. deze weggehaald en op de goede plek gedaan.
if exists (select 1 from sys.sysProcedure where proc_name='ReceptPrijsInformatie') then
  drop procedure ReceptPrijsInformatie;
end if;

create procedure ReceptPrijsInformatie(
in @RcptGid              integer,
in @RcptPrijsBatchAantal numeric(15,3))  // Indien gevuld, ook totalen afdrukken in de extra ingegeven valuta.

result (
  //totaal eindproducten
  EindProdKostPrijs         numeric(15,3),
  EindProdVerkPrijs         numeric(15,3),
  EindProdMarge             numeric(15,3),

  //totaal componenten
  CompTotaalKostPrijs       numeric(15,3),
  CompTotaalVerkPrijs       numeric(15,3),
  CompTotaalMarge           numeric(15,3),

  //subtotaal componenten per recept
  CompPerReceptKostPrijs    numeric(15,3),
  CompPerReceptVerkPrijs    numeric(15,3),
  CompPerReceptMarge        numeric(15,3),

  //subtotaal componenten per X recepten
  CompPerXReceptenKostPrijs numeric(15,3),
  CompPerXReceptenVerkPrijs numeric(15,3),
  CompPerXReceptenMarge     numeric(15,3),

  //subtotaal componenten per verwerking (batch)
  CompPerVerwKostPrijs      numeric(15,3),
  CompPerVerwVerkPrijs      numeric(15,3),
  CompPerVerwMarge          numeric(15,3),

  //totaal eindproducten+componenten
  TotaalKostPrijs           numeric(15,3),
  TotaalVerkPrijs           numeric(15,3),
  TotaalMarge               numeric(15,3) )
begin
  Declare @EindProdKostPrijs         numeric(15,3);
  Declare @EindProdVerkPrijs         numeric(15,3);
  Declare @EindProdMarge             numeric(15,3);
  Declare @CompTotaalKostPrijs       numeric(15,3);
  Declare @CompTotaalVerkPrijs       numeric(15,3);
  Declare @CompTotaalMarge           numeric(15,3);
  Declare @CompPerReceptKostPrijs    numeric(15,3);
  Declare @CompPerReceptVerkPrijs    numeric(15,3);
  Declare @CompPerReceptMarge        numeric(15,3);
  Declare @CompPerXReceptenKostPrijs numeric(15,3);
  Declare @CompPerXReceptenVerkPrijs numeric(15,3);
  Declare @CompPerXReceptenMarge     numeric(15,3);
  Declare @CompPerVerwKostPrijs      numeric(15,3);
  Declare @CompPerVerwVerkPrijs      numeric(15,3);
  Declare @CompPerVerwMarge          numeric(15,3);
  Declare @TotaalKostPrijs           numeric(15,3);
  Declare @TotaalVerkPrijs           numeric(15,3);
  Declare @TotaalMarge               numeric(15,3);

  set @@ErrorTextProcedure = 'ReceptPrijsInformatie > @VanDatum = '+string(@RcptGid)+', @RcptPrijsBatchAantal = '+string(@RcptPrijsBatchAantal);
  //call TraceBegin(@@ErrorTextProcedure);

  //totaal eindproducten
  select
    @RcptPrijsBatchAantal * sum(IsNull((RcpeAantal * ArtKostprijsEx / ArtPrijsPer),0)) Kostprijs,
    @RcptPrijsBatchAantal * sum(IsNull((RcpeAantal * (if ArtVerkprijsIsIncl = 0 then ArtVerkprijs else (ArtVerkprijs / (100 + BtwPercentage) * 100) endif) / ArtPrijsPer),0)) Verkoopprijs,
    if Verkoopprijs <> 0 then (Verkoopprijs - Kostprijs) / Verkoopprijs *100 endif Marge
  into
    @EindProdKostPrijs, @EindProdVerkPrijs, @EindProdMarge
  from
    tabReceptuurEindproduct
    inner join tabArtikel on (ArtGid  = RcpeArtGid)
    inner join tabBtw     on (BtwCode = ArtBtwCode)
  where
    RcpeRcptGid = @RcptGid;

  set @EindProdKostPrijs = IsNull(round(@EindProdKostPrijs,2) , 0);
  set @EindProdVerkPrijs = IsNull(round(@EindProdVerkPrijs,2) , 0);

  //subtotaal componenten per recept
  select
    sum(IsNull(@RcptPrijsBatchAantal * (RcpcAantal * ArtKostprijsEx / ArtPrijsPer),0)) Kostprijs,
    sum(IsNull(@RcptPrijsBatchAantal * (RcpcAantal * (if ArtVerkprijsIsIncl = 0 then ArtVerkprijs else (ArtVerkprijs / (100 + BtwPercentage) * 100) endif) / ArtPrijsPer),0)) Verkoopprijs,
    if Verkoopprijs <> 0 then (Verkoopprijs - Kostprijs) / Verkoopprijs *100 endif Marge
  into
    @CompPerReceptKostPrijs, @CompPerReceptVerkPrijs, @CompPerReceptMarge
  from
    tabReceptuurComponent
    inner join tabArtikel on (ArtGid  = RcpcArtGid)
    inner join tabBtw     on (BtwCode = ArtBtwCode)
  where
        RcpcRcptGid  = @RcptGid
    and RcpcVerbruik = 0;

  set @CompPerReceptKostPrijs = IsNull(round(@CompPerReceptKostPrijs,2), 0);
  set @CompPerReceptVerkPrijs = IsNull(round(@CompPerReceptVerkPrijs,2), 0);

  //subtotaal componenten per X recepten
  select
    sum(isnull((((ceiling(@RcptPrijsBatchAantal / RcpcVerbruikAantal) * RcpcAantal) / ArtPrijsPer) * ArtKostprijsEx),0)) Kostprijs,
    sum(isnull((((ceiling(@RcptPrijsBatchAantal / RcpcVerbruikAantal) * RcpcAantal) / ArtPrijsPer) * (if ArtVerkprijsIsIncl = 0 then ArtVerkprijs else (ArtVerkprijs / (100 + BtwPercentage) * 100) endif)),0)) Verkoopprijs,
    if Verkoopprijs <> 0 then (Verkoopprijs - Kostprijs) / Verkoopprijs *100 endif Marge
  into
    @CompPerXReceptenKostPrijs, @CompPerXReceptenVerkPrijs, @CompPerXReceptenMarge
  from
    tabReceptuurComponent
    inner join tabArtikel on (ArtGid  = RcpcArtGid)
    inner join tabBtw     on (BtwCode = ArtBtwCode)
  where
        RcpcRcptGid  = @RcptGid
    and RcpcVerbruik = 2;

  set @CompPerXReceptenKostPrijs = IsNull(round(@CompPerXReceptenKostPrijs,2), 0);
  set @CompPerXReceptenVerkPrijs = IsNull(round(@CompPerXReceptenVerkPrijs,2), 0);

  //subtotaal componenten per verwerking (batch)
  select
    sum(isnull(RcpcAantal * ArtKostprijsEx / ArtPrijsPer,0)) Kostprijs,
    sum(isnull(RcpcAantal * (if ArtVerkprijsIsIncl = 0 then ArtVerkprijs else (ArtVerkprijs / (100 + BtwPercentage) * 100 ) endif) / ArtPrijsPer,0)) Verkoopprijs,
    if Verkoopprijs <> 0 then (Verkoopprijs - Kostprijs) / Verkoopprijs *100 endif Marge
  into
    @CompPerVerwKostPrijs, @CompPerVerwVerkPrijs, @CompPerVerwMarge
  from
    tabReceptuurComponent
    inner join tabArtikel on (ArtGid  = RcpcArtGid)
    inner join tabBtw     on (BtwCode = ArtBtwCode)
  where
        RcpcRcptGid  = @RcptGid
    and RcpcVerbruik = 1;

  set @CompPerVerwKostPrijs = IsNull(round(@CompPerVerwKostPrijs,2), 0);
  set @CompPerVerwVerkPrijs = IsNull(round(@CompPerVerwVerkPrijs,2), 0);

  //totaal componenten
  set @CompTotaalKostPrijs = @CompPerReceptKostPrijs + @CompPerXReceptenKostPrijs + @CompPerVerwKostPrijs;
  set @CompTotaalVerkPrijs = @CompPerReceptVerkPrijs + @CompPerXReceptenVerkPrijs + @CompPerVerwVerkPrijs;

  if @CompTotaalVerkPrijs <> 0 then
    set @CompTotaalMarge = round((@CompTotaalVerkPrijs - @CompTotaalKostPrijs) / @CompTotaalVerkPrijs * 100.0,2);
  end if;

  //totaal eindproducten+componenten
  set @TotaalKostPrijs = @EindProdKostPrijs - @CompTotaalKostPrijs;
  set @TotaalVerkPrijs = @EindProdVerkPrijs - @CompTotaalVerkPrijs;
  if @TotaalVerkPrijs <> 0 then
    set @TotaalMarge = round((@TotaalVerkPrijs - @TotaalKostPrijs) / @TotaalVerkPrijs * 100.0,2);
  end if;

  set @@ErrorTextProcedure = 'ReceptPrijsInformatie > @VanDatum = '+string(@RcptGid)+', @RcptPrijsBatchAantal = '+string(@RcptPrijsBatchAantal);
  //call TraceEind(@@ErrorTextProcedure);

  //resultset klaarzetten
  select
    @EindProdKostPrijs,
    @EindProdVerkPrijs,
    @EindProdMarge,
    @CompTotaalKostPrijs,
    @CompTotaalVerkPrijs,
    @CompTotaalMarge,
    @CompPerReceptKostPrijs,
    @CompPerReceptVerkPrijs,
    @CompPerReceptMarge,
    @CompPerXReceptenKostPrijs,
    @CompPerXReceptenVerkPrijs,
    @CompPerXReceptenMarge,
    @CompPerVerwKostPrijs,
    @CompPerVerwVerkPrijs,
    @CompPerVerwMarge,
    @TotaalKostPrijs,
    @TotaalVerkPrijs,
    @TotaalMarge;


end;


//------------------------------------------------------------------------------
//----- LayoutExportEdit: exportlayoutrechten overnemen bij nieuwe layout ------
//------------------------------------------------------------------------------

create or replace procedure RechtenNweExpLayout(
  in @IsKopie             smallint, //true=het is een kopie van een andere layout, false=het is een volkomen nieuwe layout
  in @NweLayoutGid        integer,  //het gidje van de net toegevoegde layout
  in @KopieVanLayoutGid   integer,  //Het ExpGidje waarvan een layout eventueel van gekopieerd is
  in @ExpSoort            integer   //het ExportSoortnr
)

begin
  //zorgen dat bij het aanmaken of kopiëren van een layout de juiste rechten worden overgenomen, voor alle gebruikers.
  //Kopiëeren: neem de rechten over van de layout die gekopiëerd wordt - voor iedere gebruiker
  //Een geheel nieuwe layout maken: neem de afdrukrechten van de gehele ExporSoort over.

  declare @ExportRecht  smallint; //ExportRecht dat genomen moet worden
  declare @GebruikerGid integer;  //gebruikersgid dat uit de loop komt

  set @@ErrorTextProcedure = 'Begin RechtenNweExpLayout > @IsKopie = '+string(@IsKopie)+', @NweLayoutGid = '+string(@NweLayoutGid);
  //call Trace(@@ErrorTextProcedure);

  BEGIN
  DECLARE cursor_Layouts CURSOR FOR
    SELECT GebruikerGid
    FROM tabGebruiker;

    OPEN cursor_Layouts;
    loopje1:
    LOOP

      FETCH NEXT cursor_Layouts INTO @GebruikerGid;
      //als ie dit heeft bereikt (hetzelfde voor alle loopjes in king) dan is ie klaar en kan ie eruit springen
      if sqlstate = '02000' then
        leave loopje1;
      end if;

      //voor allebei de situtaties, kopie of nieuw:
      if exists (select 1
                 from   tabRechtExpSoortPerGebr
                 where  RechtExpSGebrExpSoortGid = @ExpSoort
                   and  RechtExpSGebrGebruikerGid = @GebruikerGid) then
        set @ExportRecht = (select RechtExpSGebrExportRecht
                           from    tabRechtExpSoortPerGebr
                           where   RechtExpSGebrExpSoortGid  = @ExpSoort
                             and   RechtExpSGebrGebruikerGid = @GebruikerGid)
      else
        set @ExportRecht = 1;
      end if;

      if @IsKopie = 1 then
        //Het is een kopie: neem die rechten over voor iedere gebruiker van de layout waar hij van gekopieerd wordt
        //Eerst testen of de gebruikers wel export recht hebben voor de deze exportsoort: zo nee, dan ook niet voor deze layout
        //Zo ja: testen op recht van de gebruikers op deze layout
        if @ExportRecht = 1 then
          if exists (select 1
                     from  tabRechtExpLayoutPerGebr
                     where RechtExpLGebrGebruikerGid = @GebruikerGid
                       and RechtExpLGebrExpGid = @KopieVanLayoutGid) then
            set @ExportRecht = (select RechtExpLGebrExportRecht
                                from   tabRechtExpLayoutPerGebr
                                where  RechtExpLGebrGebruikerGid = @GebruikerGid
                                  and  RechtExpLGebrExpGid = @KopieVanLayoutGid)
          end if;
        end if;
      end if;

      if exists (select 1                                              //als er voor de combi layoutgid + gebruiker al een rechten-record is,
                 from  tabRechtExpLayoutPerGebr                        //dat updaten, anders er een toevoegen
                 where RechtExpLGebrExpGid = @NweLayoutGid
                   and RechtExpLGebrGebruikerGid = @GebruikerGid) then
        update tabRechtExpLayoutPerGebr
        set
          RechtExpLGebrExpGid       = @NweLayoutGid,
          RechtExpLGebrGebruikerGid = @GebruikerGid,
          RechtExpLGebrExportRecht  = @ExportRecht
        from tabRechtExpLayoutPerGebr
        where RechtExpLGebrExpGid       = @NweLayoutGid
          and RechtExpLGebrGebruikerGid = @GebruikerGid;
      else
       insert into tabRechtExpLayoutPerGebr(RechtExpLGebrExpGid, RechtExpLGebrGebruikerGid, RechtExpLGebrExportRecht)
         values(@NweLayoutGid, @GebruikerGid, @ExportRecht)


    end if;

    END LOOP loopje1;
    CLOSE cursor_Layouts;
  END;

  set @@ErrorTextProcedure = 'Einde RechtenNweExpLayout';
  //call Trace(@@ErrorTextProcedure);
end;


//------------------------------------------------------------------------------
//---- LayoutImportEdit: Importlayoutrechten overnemen bij nieuwe layout -----
//------------------------------------------------------------------------------

create or replace procedure RechtenNweImpLayout(
  in @NweLayoutGid        integer,  //het gidje van de net toegevoegde layout
  in @ImpSoort            integer   //het ImpSoortnr
)

begin
  //zorgen dat bij het aanmaken of kopiëren van een layout de juiste rechten worden overgenomen, voor alle gebruikers.
  //Een geheel nieuwe layout maken: neem de afdrukrechten van de gehele ImportSoort over.

  declare @ImportRecht  smallint; //ImportRecht dat genomen moet worden
  declare @GebruikerGid integer;  //gebruikersgid dat uit de loop komt

  set @@ErrorTextProcedure = 'Begin RechtenNweImpLayout > @NweLayoutGid='+string(@NweLayoutGid)+ '; @ImpSoort='+string(@ImpSoort);
  //call Trace(@@ErrorTextProcedure);

  BEGIN
  DECLARE cursor_ImpLayouts CURSOR FOR
    SELECT GebruikerGid
    FROM tabGebruiker;

    OPEN cursor_ImpLayouts;
    loopje1:
    LOOP

      FETCH NEXT cursor_ImpLayouts INTO @GebruikerGid;
      //als ie dit heeft bereikt (hetzelfde voor alle loopjes in king) dan is ie klaar en kan ie eruit springen
      if sqlstate = '02000' then
        leave loopje1;
      end if;

      //bepalen wat de importsoort rechten zijn voor iedere gebruiker: deze nemen voor de nieuwe layout
      if exists (select 1
                 from   tabRechtImpSoortPerGebr
                 where  RechtImpSGebrImpSoortGid = @ImpSoort
                   and  RechtImpSGebrGebruikerGid = @GebruikerGid) then
        set @ImportRecht = (select RechtImpSGebrImportRecht
                           from    tabRechtImpSoortPerGebr
                           where   RechtImpSGebrImpSoortGid  = @ImpSoort
                             and   RechtImpSGebrGebruikerGid = @GebruikerGid)
      else
        set @ImportRecht = 1; //er bestaat geen rechtenrecord, dus recht is true
      end if;

      if exists (select 1                                              //als er voor de combi layoutgid + gebruiker al een rechten-record is,
                 from  tabRechtImpLayoutPerGebr                        //dat updaten, anders er een toevoegen
                 where RechtImpLGebrIelGid = @NweLayoutGid
                   and RechtImpLGebrGebruikerGid = @GebruikerGid) then
        update tabRechtImpLayoutPerGebr
        set
          RechtImpLGebrIelGid       = @NweLayoutGid,
          RechtImpLGebrGebruikerGid = @GebruikerGid,
          RechtImpLGebrImportRecht  = @ImportRecht
        from tabRechtImpLayoutPerGebr
        where RechtImpLGebrIelGid       = @NweLayoutGid
          and RechtImpLGebrGebruikerGid = @GebruikerGid;
      else
       insert into tabRechtImpLayoutPerGebr(RechtImpLGebrIelGid, RechtImpLGebrGebruikerGid, RechtImpLGebrImportRecht)
         values(@NweLayoutGid, @GebruikerGid, @ImportRecht)


    end if;

    END LOOP loopje1;
    CLOSE cursor_ImpLayouts;
  END;

  set @@ErrorTextProcedure = 'Einde RechtenNweImpLayout';
  //call Trace(@@ErrorTextProcedure);
end;


//$Workfile: RechtenNweLayout.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//------------------------------------------------------------------------------
//----------- LayoutBrowse: layoutrechten overnemen bij nieuwe layout ----------
//------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='RechtenNweLayout') then
  drop procedure RechtenNweLayout;
end if;

create procedure RechtenNweLayout(
  in @IsKopie             smallint, //true=het is een kopie van een andere layout, false=het is een volkomen nieuwe layout
  in @NweRapGid           integer,  //het gidje van de net toegevoegde layout
  in @KopieVanRapGid      integer,  //Het RapGidje waarvan een layout eventueel van gekopieerd is
  in @RapSoort            integer   //het rapportsoortnr
)

begin
  //zorgen dat bij het aanmaken of kopiëren van een layout de juiste rechten worden overgenomen, voor alle gebruikers.
  //Kopiëeren: neem de rechten over van de layout die gekopiëerd wordt - voor iedere gebruiker
  //Een geheel nieuwe layout maken: neem de afdrukrechten van de gehele rapporsoort over.

  declare @AfdrukRecht  smallint; //afdrukrecht dat genomen moet worden
  declare @GebruikerGid integer;  //gebruikersgid dat uit de loop komt

  set @@ErrorTextProcedure = 'RechtenNweLayout > @IsKopie='+string(@IsKopie)+', @NweRapGid='+string(@NweRapGid);
  //call TraceBegin(@@ErrorTextProcedure);

  BEGIN
  DECLARE cur_Layouts CURSOR FOR
    SELECT GebruikerGid
    FROM tabGebruiker;

    OPEN cur_Layouts;
    loopje1:
    LOOP

      FETCH NEXT cur_Layouts INTO @GebruikerGid;
      //als ie dit heeft bereikt (hetzelfde voor alle loopjes in king) dan is ie klaar en kan ie eruit springen
      if sqlstate = '02000' then
        leave loopje1;
      end if;

      if @IsKopie = 1 then
        //het is een kopie: neem die rechten over...
        if exists (select 1                                                       //is er al een recht toegekend aan de te kopiëren layout?
                   from   tabRechtRapLayoutPerGebr
                   where  RechtRapLGebrRapGid       = @KopieVanRapGid
                     and  RechtRapLGebrGebruikerGid = @GebruikerGid) then
          set @AfdrukRecht = (select RechtRapLGebrAfdrukRecht                     //zo ja, neem dat recht over
                              from   tabRechtRapLayoutPerGebr
                              where  RechtRapLGebrRapGid       = @KopieVanRapGid
                                and  RechtRapLGebrGebruikerGid = @GebruikerGid);  //zo nee, zet afdrukrecht op True
        else
          set @AfdrukRecht = 1;
        end if;

      else
        //een geheel nieuwe layout
        if exists (select 1
                   from   tabRechtRapSoortPerGebr                                 //is er al een afdrukrecht aan de rapportsoort toegeken?
                   where  RechtRapSGebrRapSoortID   = @RapSoort
                     and  RechtRapSGebrGebruikerGid = @GebruikerGid) then
          set @AfdrukRecht = (select RechtRapSGebrAfdrukRecht                     //zo ja, neem dat over
                              from   tabRechtRapSoortPerGebr
                              where  RechtRapSGebrRapSoortID   = @RapSoort
                                and  RechtRapSGebrGebruikerGid = @GebruikerGid)
        else
          set @AfdrukRecht = 1;                                                   //zo nee, zet afdrukrecht op True
        end if;
      end if;

      if exists (select 1                                                         //als er voor de combi layoutgid + gebruiker al een rechten-record is,
                 from  tabRechtRapLayoutPerGebr                                   //dat updaten, anders er een toevoegen
                 where RechtRapLGebrRapGid = @NweRapGid
                   and RechtRapLGebrGebruikerGid = @GebruikerGid) then
        update tabRechtRapLayoutPerGebr
        set
          RechtRapLGebrRapGid       = @NweRapGid,
          RechtRapLGebrGebruikerGid = @GebruikerGid,
          RechtRapLGebrAfdrukRecht  = @AfdrukRecht
        from tabRechtRapLayoutPerGebr
        where RechtRapLGebrRapGid       = @NweRapGid
          and RechtRapLGebrGebruikerGid = @GebruikerGid;
      else
       insert into tabRechtRapLayoutPerGebr(RechtRapLGebrRapGid, RechtRapLGebrGebruikerGid, RechtRapLGebrAfdrukRecht)
         values(@NweRapGid, @GebruikerGid, @AfdrukRecht)


    end if;

    END LOOP loopje1;
    CLOSE cur_Layouts;
  END;

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure RecompileStoredProcs()
begin
  set @@ErrorTextProcedure = 'RecompileStoredProcs';
  //call TraceBegin(@@ErrorTextProcedure);

  for @Cursor AS CURSOR_StoredProcs CURSOR FOR
    select proc_name @proc from sysprocedure inner join sysuserperm on (User_Id = Creator and User_name = 'KingSystem') where proc_name not in ('RecompileStoredProcs')
  for read only
  do
    set @@ErrorTextProcedure = 'RecompileStoredProcs -> Procedure ' + @Proc;
    //call Trace(@@ErrorTextProcedure);
    execute immediate 'alter procedure KingSystem.' || @proc || ' recompile';
  end for;

  set @@ErrorTextProcedure = 'RecompileStoredProcs';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure RefreshRechtenPerGebruikersTabel()
begin
  declare _PROGRAM          smallint = 0; // User rights on forms etc., just one right
  declare _ARCHIVE          smallint = 1; // Digital archive types, just one right
  declare _REPORT           smallint = 10; // With rights for use and edit
  declare _REPORT_LAYOUT    smallint = 11;
  declare _IMPORT           smallint = 20; // With rights for use and edit
  declare _IMPORT_LAYOUT    smallint = 21;
  declare _EXPORT           smallint = 30; // With rights for use and edit
  declare _EXPORT_LAYOUT    smallint = 31;
  declare _RUNBROWSE        smallint = 40; // Runbrowse types, just one right

  // Fixed right
  declare _ParentRight_DigiArch  nchar(4)  = 'sadr';
  declare _ParentRight_RunBrowse nchar(4) = 'ovrv';

  declare @corrections integer = 0;

  // Ook import, export en rapporten toevoegen:
  // - tabRechtImpLayoutPerGebr
  // - tabRechtExpLayoutPerGebr
  // - Rapportage
  //   - rapportsoorten
  // select rasParentAfdrukRecht, rasParentLayoutsWijzigRecht from tabRapportSoort order by RasBoomVolgordeAfdrRecht
  // - parentrecht = rasParentAfdrukRecht en rasParentLayoutsWijzigRecht, beiden los verwerken:
  //   recht = (1000 + RasRapSoortID)
  //   Voor elk rapport waarvoor geen record bestaat in tabRechtRapSoortPerGebr, maar met parent wel, moet een record worden toegevoegd

  //Lus voor iedere gebruiker in tabGebruiker:
  //- Lus voor elk 'record' in de lijst (gesorteerd op index ASC) die een parentrechtcode heeft
  //  - Zoek in tabRechtPerGebruiker naar record met RechtGebrGebruikersRechtCode=@rechtcode
  //  - Als NIET gevonden, zoek dan naar record met RechtGebrGebruikersRechtCode=@parentrechtcode
  //  - Als die WEL is gevonden, voeg dan een record aan tabRechtPerGebruiker toe met:
  //    - RechtGebrGebruikerGid = tabGebruiker.GebruikerGid
  //    - RechtGebrGebruikersRechtCode = @rechtcode
  //    - RechtGebrHeeftRecht = 0
  //
  //Stel:
  //recht   parent
  //C       -
  //B       C
  //A       B
  //Een parent recht staat altijd boven een child recht.
  //
  //Recht B en A zijn toegevoegd.
  //De volgorde moet van 1e naar laatste zijn:
  //1e regel -> overgeslagen (parent=null)
  //2e regel -> controleer; als record C bestaat, maar B niet, dan B aanmaken
  //3e regel -> B was al aangemaakt, dus als A niet bestaat, maar B wel, dan alsnog A aanmaken


  for gebruikers as @gebruikers cursor for
    select GebruikerGid @GebruikerGid
    from tabGebruiker
  for read only
  do
    for rechten as @rechten cursor for
      // Het recht van een parent code staat ALTIJD voor het gebruik als parentcode, dus oplopend doorlopen,
      // zodat een parentrecord altijd al eventueel is aangemaakt voordat erop wordt gecontroleerd.

        // Program rights first
        select
          _PROGRAM @type, RechtVolgorde @order, RechtGebruiksRechtCode @rechtcode, RechtGebruiksParentRechtCode @parentrechtcodeUse, null @parentrechtcodeEdit
        from tabRecht
        where @parentrechtcodeUse is not null

      union all
        // Digital archive types
        select _ARCHIVE       @type, -1                        @order, string(DasGid)        @rechtcode, _ParentRight_DigiArch     @parentrechtcodeUse, null                             @parentrechtcodeEdit from tabDigitaalArchiefSoort

      union all
        // Reports rights: use/change layoutsoort
        select _REPORT        @type , RasBoomVolgordeAfdrRecht @order, string(RasRapSoortID) @rechtcode, rasParentAfdrukRecht      @parentrechtcodeUse, rasParentLayoutsWijzigRecht      @parentrechtcodeEdit from tabRapportSoort

      union all
        // Reports rights: use layout
        select _REPORT_LAYOUT @type, RasBoomVolgordeAfdrRecht @order, string(RapGid)         @rechtcode, rasParentAfdrukRecht      @parentrechtcodeUse, null                            @parentrechtcodeEdit from tabRapport inner join tabRapportSoort on  rasRapSoortID = RapSoort

      union all
        // Import rights: use/change layoutsoort
        select _IMPORT        @type, -1                       @order, string(ImpSoortGid)    @rechtcode, ImpSoortParentImportRecht @parentrechtcodeUse, ImpSoortParentLayoutsWijzigRecht @parentrechtcodeEdit from tabImportSoort

      union all
        // Import rights: use layout
        select _IMPORT_LAYOUT @type, -1                       @order, string(IelGid)         @rechtcode, ImpSoortParentImportRecht @parentrechtcodeUse, ImpSoortParentLayoutsWijzigRecht @parentrechtcodeEdit from tabImportExportLayout inner join tabImportSoort on ImpSoortGid = IelSoort

      union all
        // Export rights: use/change layout
        select _EXPORT        @type, -1                      @order, string(ExpSoortGid)     @rechtcode, ExpSoortParentExportRecht @parentrechtcodeUse, ExpSoortParentLayoutsWijzigRecht @parentrechtcodeEdit from tabExportSoort

      union all
        // Export rights: use/change layout
        select _EXPORT_LAYOUT @type, -1                      @order, string(ExpGid)          @rechtcode, ExpSoortParentExportRecht @parentrechtcodeUse, ExpSoortParentLayoutsWijzigRecht @parentrechtcodeEdit from tabExport inner join tabExportSoort on ExpSoortGid = ExpExpSoortGid

      union all
        // Runbrowse rights: use layout
        select _RUNBROWSE     @type, -1                   @order, string(RbdGid)          @rechtcode, _ParentRight_RunBrowse    @parentrechtcodeUse, null                             @parentrechtcodeEdit from tabRunBrowseDef

      order by 1, 2

    for read only
    do
      case
        when @type = _PROGRAM then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename           = 'tabRechtPerGebruiker',
            @primKey             = 'RechtGebrGid',
            @GebruikersGidField  = 'RechtGebrGebruikerGid',
            @ThisRechtTypeField  = 'RechtGebrGebruikersRechtCode',
            @RechtUseField       = 'RechtGebrHeeftRecht',
            @RechtEditField      = null,
            @GebruikerGid        = @GebruikerGid,
            @rechtcode           = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = null,
            @corrections         = @corrections
          );

        when @type = _ARCHIVE then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename          = 'tabRechtDigiArchSoortPerGebr',
            @primKey            = 'RdarGid',
            @GebruikersGidField = 'RdarGebruikerGid',
            @ThisRechtTypeField = 'RdarDasGid',
            @RechtUseField      = 'RdarInzienRecht',
            @RechtEditField     = null,
            @GebruikerGid       = @GebruikerGid,
            @rechtcode          = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = null,
            @corrections         = @corrections
          );

        when @type = _REPORT then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename           = 'tabRechtRapSoortPerGebr',
            @primKey             = 'RechtRapSGebrGid',
            @GebruikersGidField  = 'RechtRapSGebrGebruikerGid',
            @ThisRechtTypeField  = 'RechtRapSGebrRapSoortID',
            @RechtUseField       = 'RechtRapSGebrAfdrukRecht',
            @RechtEditField      = 'RechtRapSGebrWijzigRecht',
            @GebruikerGid        = @GebruikerGid,
            @rechtcode           = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = @parentrechtcodeEdit,
            @corrections         = @corrections
          );

        when @type = _REPORT_LAYOUT then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename           = 'tabRechtRapLayoutPerGebr',
            @primKey             = 'RechtRapLGebrGid',
            @GebruikersGidField  = 'RechtRapLGebrGebruikerGid',
            @ThisRechtTypeField  = 'RechtRapLGebrRapGid',
            @RechtUseField       = 'RechtRapLGebrAfdrukRecht',
            @RechtEditField      = null,
            @GebruikerGid        = @GebruikerGid,
            @rechtcode           = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = null,
            @corrections         = @corrections
          );

        when @type = _IMPORT then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename           = 'tabRechtImpSoortPerGebr',
            @primKey             = 'RechtImpSGebrGid',
            @GebruikersGidField  = 'RechtImpSGebrGebruikerGid',
            @ThisRechtTypeField  = 'RechtImpSGebrImpSoortGid',
            @RechtUseField       = 'RechtImpSGebrImportRecht',
            @RechtEditField      = 'RechtImpSGebrWijzigRecht',
            @GebruikerGid        = @GebruikerGid,
            @rechtcode           = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = @parentrechtcodeEdit,
            @corrections         = @corrections
          );

        when @type = _IMPORT_LAYOUT then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename           = 'tabRechtImpLayoutPerGebr',
            @primKey             = 'RechtImpLGebrGid',
            @GebruikersGidField  = 'RechtImpLGebrGebruikerGid',
            @ThisRechtTypeField  = 'RechtImpLGebrIelGid',
            @RechtUseField       = 'RechtImpLGebrImportRecht',
            @RechtEditField      = null,
            @GebruikerGid        = @GebruikerGid,
            @rechtcode           = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = null,
            @corrections         = @corrections
          );

        when @type = _EXPORT then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename           = 'tabRechtExpSoortPerGebr',
            @primKey             = 'RechtExpSGebrGid',
            @GebruikersGidField  = 'RechtExpSGebrGebruikerGid',
            @ThisRechtTypeField  = 'RechtExpSGebrExpSoortGid',
            @RechtUseField       = 'RechtExpSGebrExportRecht',
            @RechtEditField      = 'RechtExpSGebrWijzigRecht',
            @GebruikerGid        = @GebruikerGid,
            @rechtcode           = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = @parentrechtcodeEdit,
            @corrections         = @corrections
          );

        when @type = _EXPORT_LAYOUT then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename           = 'tabRechtExpLayoutPerGebr',
            @primKey             = 'RechtExpLGebrGid',
            @GebruikersGidField  = 'RechtExpLGebrGebruikerGid',
            @ThisRechtTypeField  = 'RechtExpLGebrExpGid',
            @RechtUseField       = 'RechtExpLGebrExportRecht',
            @RechtEditField      = null,
            @GebruikerGid        = @GebruikerGid,
            @rechtcode           = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = null,
            @corrections         = @corrections
          );

        when @type = _RUNBROWSE then
          call RefreshRechtenPerGebruikerstabel_setRights(
            @tablename          = 'tabRechtRunBrowsePerGebr',
            @primKey            = 'RrbGid',
            @GebruikersGidField = 'RrbGebruikerGid',
            @ThisRechtTypeField = 'RrbRbdGid',
            @RechtUseField      = 'RrbInzienRecht',
            @RechtEditField     = null,
            @GebruikerGid       = @GebruikerGid,
            @rechtcode          = @rechtcode,
            @parentRechtcodeUse  = @parentrechtcodeUse,
            @parentRechtcodeEdit = null,
            @corrections         = @corrections
          );

      end; //case
    end for;
  end for;
  if @corrections <> 0 then
    insert into tabLog(LogSoort, LogAdmCode, LogBjCode, LogUserName, LogMachineName, LogOmschrijving)
    values(6 /*reparatie*/, Db_Name(), '', '', '', _A('Correcties in rechtenboom: ' || @corrections));
  end if;
// *** EXCEPTIONS
exception
  when others then
    // Ignore exceptions
    insert into tabLog(LogSoort, LogAdmCode, LogBjCode, LogUserName, LogMachineName, LogOmschrijving)
    values(6 /*reparatie*/, Db_Name(), '', '', '', _A('Fout bij controle rechten: ' || error_message()));
end;





create or replace procedure RefreshRechtenPerGebruikerstabel_setRights(
  in @tablename           nchar(100),         // e.g. tabRechtImpSoortPerGebr
  in @primKey             nchar(100),         // e.g. RechtImpSGebrGid
  in @GebruikersGidField  nchar(100),         // e.g. RechtImpSGebrGebruikerGid
  in @ThisRechtTypeField  nchar(100),         // e.g. RechtImpSGebrImpSoortGid
  in @RechtUseField       nchar(100),         // e.g. RechtImpSGebrImportRecht
  in @RechtEditField      nchar(100),         // e.g. RechtImpSGebrWijzigRecht, NULL when not used!
  in @GebruikerGid        integer,
  in @rechtcode           nchar(10), // either a string of 4 positions, or reference to prim key, is used for field @ThisRechtTypeField
  in @parentRechtcodeUse  nchar(10),
  in @parentRechtcodeEdit nchar(10),
  inout @corrections      integer
)
begin
  declare @sql long nvarchar;
  declare @PrimKeyValue integer;
  declare @hasParentUseRecord smallint; // Having the record means the user has NO right to use
  declare @hasParentEditRecord smallint;// Having the record means the user has NO right to edit
  declare @activeRechtUse smallint;     // Active right for use, default 1 (no record means user has rights)
  declare @activeRechtEdit smallint;
  declare @revokeUse smallint;  // 1 means we have to REVOKE the rights (either add a record, or set the right to false)
  declare @revokeEdit smallint;
  // disright record of parent exists, so we should NOT have the right for read or edit, that means we should have a disrights record for this with both rights OFF.
  // (It is not possible to already have a record for this right when the report type was just added, so test for existence of the record is enough)
  // In that case, add the disright record (both rights OFF) when it does not yet exist.

  -- Defaults: if no record exists, treat as having rights
  set @PrimKeyValue  = null;
  set @activeRechtUse    = 1;
  set @activeRechtEdit   = 1;

  //call trace('RefreshRechtenPerGebruikerstabel_setRights(' ||
  //'@tablename = ' ||          @tablename            ||
  //', @primKey = ' ||            @primKey            ||
  //', @GebruikersGidField = ' || @GebruikersGidField ||
  //', @ThisRechtTypeField = ' || @ThisRechtTypeField ||
  //', @RechtUseField = ' ||      @RechtUseField      ||
  //', @RechtEditField = ' ||     @RechtEditField     ||
  //', @GebruikerGid = ' ||       @GebruikerGid       ||
  //', @rechtcode = ' ||          @rechtcode
  //);


  set @sql =
    'select ' || @primKey || ', ' || @RechtUseField || if @RechtEditField is not null then ', ' || @RechtEditField endif ||
    ' into @PrimKeyValue, @activeRechtUse'    || if @RechtEditField is not null then ', @activeRechtEdit' endif ||
    ' from ' || @tablename ||
    ' where ' || @GebruikersGidField || ' = @GebruikerGid and ' || @ThisRechtTypeField || ' = @rechtcode';
  execute immediate @sql;

  // Parent existence checks
  set @hasParentUseRecord  =
    if exists(
      select 1
      from tabRechtPerGebruiker
      where RechtGebrGebruikerGid         = @GebruikerGid
        and RechtGebrGebruikersRechtCode  = @parentRechtcodeUse
    ) then 1 else 0 endif;

  set @hasParentEditRecord =
    if @RechtEditField is null then null
    else
      if exists(
        select 1
        from tabRechtPerGebruiker
        where RechtGebrGebruikerGid         = @GebruikerGid
          and RechtGebrGebruikersRechtCode  = @parentRechtcodeEdit
      ) then 1 else 0 endif
    endif;

  // We should revoke when the parent record exists (meaning no rights) and the actual right is 1 (has right or record not existing)
  set @revokeUse  = if @hasParentUseRecord  = 1 and @activeRechtUse  = 1 then 1 else 0 endif;
  set @revokeEdit = if @hasParentEditRecord = 1 and @activeRechtEdit = 1 and @RechtEditField is not null then 1 else 0 endif;

  // If nothing to do: skip
  if @revokeUse = 1 or @revokeEdit = 1 then
    set @corrections = @corrections + 1;

    // Revoking, so at least the record should exist
    if @PrimKeyValue is null then
      set @sql =
        'insert into ' || @tablename || '(' || @GebruikersGidField || ', ' || @ThisRechtTypeField || ', ' || @RechtUseField || if @RechtEditField is not null then ', ' || @RechtEditField endif|| ')' ||
        ' values (' ||
          @GebruikerGid ||
          ', @rechtcode' ||
          ', if @revokeUse  = 1 then 0 /*revoke, therefor no right*/ else 1 endif' ||
          if @RechtEditField is not null then ', if @revokeEdit = 1 then 0 /*revoke, therefor no right*/ else 1 endif' endif ||
        ')';
      execute immediate @sql;
    else
      set @sql =
        'update ' || @tablename || ' set ' ||
        @RechtUseField || ' = (1-@revokeUse)  * ' || @RechtUseField ||
        if @RechtEditField is not null then ', ' ||
          @RechtEditField || ' = (1-@revokeEdit)  * ' || @RechtEditField
        endif ||
        ' where ' || @primKey || ' = @PrimKeyValue';
      execute immediate @sql;
    end if;

  end if;
end;


//$Workfile: RegelsHernummeren.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----------------------------------------------------------------------------------------------------
//------------------------ RegelsHernummeren (bij invoeren projectmutaties/boekingen ----------------
//----------------------------------------------------------------------------------------------------
//nav bug 19595, tussenvoegen regels in cached query werkt niet als niet alle regels getoond worden.
//daarom in deze storedproc regels opschuiven
//regelnummers van 001 ...9999
if exists (select 1 from sys.sysProcedure where proc_name='RegelsHernummeren') then
  drop procedure RegelsHernummeren;
end if;

create procedure RegelsHernummeren(
in     @Aktie                    integer,//0=hernummeren, 1=Verhogen, 2=Verlagen
inout  @HuidigeRegelNr           integer,//in: regelnummer waarvoor moet worden ingevoegd; out: regelnummer die toegevoegd kan worden OF -1: niets tussen kunnen voegen
in     @MasterGid                integer,
inout  @TotEnMetRegelNr          integer)//in: t/m dit regelnummer verlagen; out: t/m dit regelnummer is er verhoogd
//tzt tabelnaam meegeven?, voorlopig voor projectmutaties!

begin
  declare @RegelNrVoorHuidigeRegel     integer;
  declare @Opschuiven                  smallint;
  declare @OpschuivenTotEnMetRegelNr   integer;

  set @@ErrorTextProcedure = 'RegelsHernummeren(@HuidigeRegelNr='+string(@HuidigeRegelNr)+', @MasterGid='+string(@MasterGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @Aktie = 0 then
    update  tabProjectBoekingsRegel set PbrRegelNr = Number ( * )  where PbrPbkGid = @MasterGid order by PbrRegelNr;
  end if;

  if exists(select 1 from tabProjectBoekingsRegel where PbrPbkGid = @MasterGid and PbrRegelNr = @HuidigeRegelNr) and (@HuidigeRegelNr > 0) then

    if @Aktie = 1 then//Verhogen: Als er geen gat voor huidige regelnummer is, dan regels vanaf huidige RegelNr tot evt volgend RegelNr gat opschuiven
      if @HuidigeRegelNr = 1 then
        set @Opschuiven = 1;
      else
        //bepaal de RegelNr die voor de huidige regel staat:(kan null zijn bij leeg resultaat)
        select first PbrRegelNr into @RegelNrVoorHuidigeRegel from tabprojectboekingsregel where pbrpbkgid = @MasterGid and PbrRegelNr < @HuidigeRegelNr order by PbrRegelNr desc;
        if @RegelNrVoorHuidigeRegel is null then
          //er zijn geen regels voor huidige RegelNr
          set @Opschuiven = 0;
          set @HuidigeRegelNr  = 1;//begin bij 1
          set @TotEnMetRegelNr = -1;
        else
          if @RegelNrVoorHuidigeRegel <= 0 then
            //RegelNr ervoor is een ongeldig nr.
            set @Opschuiven = 0;
            set @HuidigeRegelNr  = -1;
            set @TotEnMetRegelNr = -1;
          else
            if @RegelNrVoorHuidigeRegel = @HuidigeRegelNr - 1 then
              set @Opschuiven = 1;
            else
              //er zit een regelnummer gat voor huidige RegelNr
              set @Opschuiven = 0;
              set @HuidigeRegelNr  = @RegelNrVoorHuidigeRegel + 1;//doornummeren vanaf gat
              set @TotEnMetRegelNr = -1;
            end if;
          end if;
        end if;
      end if;
      if @Opschuiven = 1 then
        //bepalen tot en met welke regel er opgeschoven moet worden
        //kijken of er een regelnummer gat is na de huidige regel(anders laatste regel teruggeven)
        select first X.PbrRegelNr
        into         @OpschuivenTotEnMetRegelNr
        from         tabProjectBoekingsRegel X
        where        X.PbrPbkGid   = @MasterGid and
                     X.PbrRegelNr >= @HuidigeRegelNr and
                     not exists(select 1 from tabProjectBoekingsRegel Y  where Y.PbrPbkGid = @MasterGid and Y.PbrRegelNr =  X.PbrRegelNr + 1)
        order by     X.PbrRegelNr;
        if @OpschuivenTotEnMetRegelNr >= 9999 then
          set @HuidigeRegelNr  = -1;
          set @TotEnMetRegelNr = -1;
        else
          update tabProjectBoekingsRegel set PbrRegelNr = PbrRegelNr + 1 where PbrPbkGid = @MasterGid and PbrRegelNr between @HuidigeRegelNr and @OpschuivenTotEnMetRegelNr;
          set @HuidigeRegelNr  = @HuidigeRegelNr;//als output huidige regelnummer, want die wordt het nieuwe regelnummer, de oorspronkelijke regel is hierboven verhoogd.
          set @TotEnMetRegelNr = @OpschuivenTotEnMetRegelNr;
        end if;
      end if;//opschuiven
    end if;//@Aktie = 1

    if @Aktie = 2 then//Verlagen: regelnummers weer verlagen
      //vanaf @HuidigeRegelNr tot en met @TotEnMetRegelNr alle regelnummers met 1 verlagen
      //voor de zekerheid testen of regelnummer ervoor niet bestaat:
      if not exists(select 1 from tabProjectBoekingsRegel where PbrPbkGid = @MasterGid and PbrRegelNr = @HuidigeRegelNr - 1) then
        update tabProjectBoekingsRegel set PbrRegelNr = PbrRegelNr - 1 where PbrPbkGid = @MasterGid and PbrRegelNr between @HuidigeRegelNr and @TotEnMetRegelNr;
      end if;
    end if;//@Aktie = 2

  end if;//geldig RegelNr meegegeven
  //call TraceEind('RegelsHernummeren');

end;


//$Workfile: RekeningIsGeblokkeerd.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//------------- Geef terug of het rekeningnummer geblokkeerd is
if exists (select 1 from sys.sysProcedure where proc_name='RekeningIsGeblokkeerd') then
