create procedure RekeningIsGeblokkeerd(in @RksGid integer, inout @IsGeblokkeerd integer)
begin
  set @@ErrorTextProcedure = 'RekeningIsGeblokkeerd > @RksGid='+string(@RksGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select IsRksGeblokkeerd into @IsGeblokkeerd from tabRekeningschema where RksGid=@RksGid;

  set @@ErrorTextProcedure = 'RekeningIsGeblokkeerd > @IsGeblokkeerd='+string(@IsGeblokkeerd);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure RekeningSaldoUpdate(in @JrGid integer, in @BjGid integer, in @PerGid integer, in @Pernr integer, in @Valuta integer, in @RksGid integer,
                                                in @IsDefinitief integer, in @IsCredit integer, in @BasisBedrag double,
                                                in @ValutaBedrag double, in @Aantal numeric(15,2))
begin
  declare index_not_unique exception for sqlstate '23505';
  declare @IsOk smallint;

  //RVL 08-06-2007 LET OP : @JrGid wordt als parameter meegestuurd, maar er wordt in deze stored proc niets meegedaan.
  // Maar in GEEN geval weghalen, omdat stored procs die aangeroepen worden binnen een "select" gecached worden indien de paramters
  // hetzelfde zijn als bij de vorige aanroep. Aangezien deze storedproc wordt aangeroepen binnen een "select" zie stored proc HerstelRekeningsaldo
  // zijn de parameters ald uniek doordat JrGid erbij staat

  //call TraceBegin('RekeningSaldoUpdate > @JrGid = ' + string(@JrGid) + ', @BjGid = ' + string(@BjGid) + ', @PerGid = ' + string(@PerGid) + ', @RksGid = ' + string(@RksGid) + ', @Valuta = ' + string(@Valuta));

  set @IsOk = 0;
  while @IsOk = 0 loop
    if @IsDefinitief=0 then
      //call Trace('RekeningSaldoUpdate > Bedragen voorlopig debet en credit bijwerken');
      update tabRekeningSaldo
      set    SaldoDebetBasisVoorlopig   = SaldoDebetBasisVoorlopig     + if @IsCredit=0  then @BasisBedrag  else 0 endif,
             SaldoDebetValutaVoorlopig  = SaldoDebetValutaVoorlopig    + if @IsCredit=0  then @ValutaBedrag else 0 endif,
             SaldoDebetAantalVoorlopig  = SaldoDebetAantalVoorlopig    + if @IsCredit=0  then @Aantal       else 0 endif,
             SaldoCreditBasisVoorlopig  = SaldoCreditBasisVoorlopig    + if @IsCredit<>0 then @BasisBedrag  else 0 endif,
             SaldoCreditValutaVoorlopig = SaldoCreditValutaVoorlopig   + if @IsCredit<>0 then @ValutaBedrag else 0 endif,
             SaldoCreditAantalVoorlopig = SaldoCreditAantalVoorlopig   + if @IsCredit<>0 then @Aantal       else 0 endif
      where  RekSaldoPerGid = @PerGid and RekSaldoRksGid = @RksGid and RekSaldoValNummer = @Valuta;
    else
      //call Trace('RekeningSaldoUpdate > Bedragen definitief debet en credit bijwerken');
      update tabRekeningSaldo
      set    SaldoDebetBasisDefinitief   = SaldoDebetBasisDefinitief   + if @IsCredit=0  then @BasisBedrag  else 0 endif,
             SaldoDebetValutaDefinitief  = SaldoDebetValutaDefinitief  + if @IsCredit=0  then @ValutaBedrag else 0 endif,
             SaldoDebetAantalDefinitief  = SaldoDebetAantalDefinitief  + if @IsCredit=0  then @Aantal       else 0 endif,
             SaldoCreditBasisDefinitief  = SaldoCreditBasisDefinitief  + if @IsCredit<>0 then @BasisBedrag  else 0 endif,
             SaldoCreditValutaDefinitief = SaldoCreditValutaDefinitief + if @IsCredit<>0 then @ValutaBedrag else 0 endif,
             SaldoCreditAantalDefinitief = SaldoCreditAantalDefinitief + if @IsCredit<>0 then @Aantal       else 0 endif
      where  RekSaldoPerGid = @PerGid and RekSaldoRksGid = @RksGid and RekSaldoValNummer = @Valuta;
    end if;

    if @@rowcount <> 0 then
      // Ok, update is gelukt!
      set @IsOk = 1;
    else
      //call Trace('RekeningSaldoUpdate > update is NIET gelukt -> probeer een insert');
      begin // Try ... except!
        //call Trace('RekeningSaldoUpdate > Update niet gelukt -> insert proberen!');
        if @IsDefinitief=0 then
          //call Trace('RekeningSaldoUpdate > Bedragen voorlopig inserten');
          if @IsCredit=0 then
            insert tabRekeningSaldo (RekSaldoBjGid, RekSaldoPerGid, RekSaldoPernr, RekSaldoRksGid, RekSaldoValNummer, SaldoDebetBasisVoorlopig, SaldoDebetValutaVoorlopig, SaldoDebetAantalVoorlopig)
            values (@BjGid, @PerGid, @Pernr, @RksGid, @Valuta, @BasisBedrag, @ValutaBedrag, @Aantal);
          else
            insert tabRekeningSaldo (RekSaldoBjGid, RekSaldoPerGid, RekSaldoPernr, RekSaldoRksGid, RekSaldoValNummer, SaldoCreditBasisVoorlopig, SaldoCreditValutaVoorlopig, SaldoCreditAantalVoorlopig)
            values (@BjGid, @PerGid, @Pernr, @RksGid, @Valuta, @BasisBedrag, @ValutaBedrag, @Aantal);
          end if;
        else
          //call Trace('RekeningSaldoUpdate > Bedragen definitief inserten');
          if @IsCredit=0 then
            insert tabRekeningSaldo (RekSaldoBjGid, RekSaldoPerGid, RekSaldoPernr, RekSaldoRksGid, RekSaldoValNummer, SaldoDebetBasisDefinitief, SaldoDebetValutaDefinitief, SaldoDebetAantalDefinitief)
            values (@BjGid, @PerGid, @Pernr, @RksGid, @Valuta, @BasisBedrag, @ValutaBedrag, @Aantal);
          else
            insert tabRekeningSaldo (RekSaldoBjGid, RekSaldoPerGid, RekSaldoPernr, RekSaldoRksGid, RekSaldoValNummer, SaldoCreditBasisDefinitief, SaldoCreditValutaDefinitief, SaldoCreditAantalDefinitief)
            values (@BjGid, @PerGid, @Pernr, @RksGid, @Valuta, @BasisBedrag, @ValutaBedrag, @Aantal);
          end if;
        end if;
        //Vve 23-2-2004: Tot hier geen exception -> insert is gelukt!
        set @IsOk = 1;

      exception
        when index_not_unique then
          // Oeps; insert niet gelukt -> probeer een update!
          set @IsOk = 0;
          //call Trace('RekeningSaldoUpdate > niet gelukt, nogmaals proberen!');
        when others then
          resignal;
      end;
    end if; // insert
  end loop; // try-loop

  //call TraceEind('RekeningSaldoUpdate');
end;


