create or replace procedure ReleaseLocksOnTableWithoutConnection(in @TableName nchar(40))
begin
  declare @ConnId integer;
  declare local temporary table tmpConnection
   (ConnId integer null) on commit preserve rows;

  set @@ErrorTextProcedure = 'Begin ReleaseLocksOnTableWithoutConnection > @@Spid='+string(@@SpId)+', @@LoginTime='+string(@@LoginTime);
  //call Trace(@@ErrorTextProcedure);

  set @ConnId=next_connection(null);
  while @ConnId is not null loop
    //Test op Db_id is niet nodig. De "Next_Connection" zonder 2e parameter geeft alleen connecties terug van de huidige database
    //if connection_property('DBNumber',@ConnId) = Db_Id() then
    insert into tmpConnection values(@ConnId);  //Zet alleen die id''s er in die deze database gebruiken
    //end if;
    set @ConnId=next_connection(@ConnId);
  end loop;

  delete qtablock
  where qLockConnection not in (select ConnId from tmpConnection)
    and qLockTableName = @TableName
    and qLockAutomatischOpruimen = 1;

  set @@ErrorTextProcedure = 'Einde ReleaseLocksOnTableWithoutConnection';
  //call Trace(@@ErrorTextProcedure);
end;

create or replace procedure RenameRksInvoer(in @RksInvoer nchar(28), in @RksNummer nchar(10), in @KstpCode nchar(8), in @KstdCode nchar(8))
begin
  declare @NewRksInvoer nchar(28);

  //call TraceBegin('RenameRksInvoer(@RksInvoer='+@RksInvoer+', @RksNummer='+@RksNummer+')');

  //call Trace('Eerst evt. kostenplaats aanmaken');
  if IsNull(@KstpCode, '') <> '' then
    if not exists(select 1 from tabKostenplaats where KstpCode = @KstpCode) then
      insert into tabKostenPlaats(KstpCode) values (@KstpCode);
    end if;
  end if;

  //call Trace('Eerst evt. kostendrager aanmaken');
  if IsNull(@KstdCode, '') <> '' then
    if not exists(select 1 from tabKostendrager where KstdCode = @KstdCode) then
      insert into tabKostendrager(KstdCode) values (@KstdCode);
    end if;
  end if;

  //Als hoofdrekening niet bestaat dan eerst de hoofdrekening aanmaken in het geval dat we een rekening met kostenplaats en/of kostendrager aan gaan maken
  if IsNull(@KstpCode, '') <> '' or IsNull(@KstdCode, '') <> '' then
    if not exists(select 1 from tabRekeningschema where RksNummer = @RksNummer and RksKstpGid is null and RksKstdGid is null) then
      insert into tabRekeningschema(RksNummer, RksZoekCode, RksNaam, DefaultSoort, RksValNummer, AfdrukZijde, RksBtwCode, ReferentieVerplicht, GebruikAantallen)
                            select @RksNummer, RksZoekCode, RksNaam, DefaultSoort, RksValNummer, AfdrukZijde, RksBtwCode, ReferentieVerplicht, GebruikAantallen from tabRekeningschema where RksInvoer = @RksInvoer;
    end if;
  end if;

  set @NewRksInvoer = @RksNummer +
                      IsNull((select '.'+KstpCode from tabKostenplaats where KstpCode=@KstpCode), '')+
                     (if IsNull(@KstpCode, '') = '' and IsNull(@KstpCode, '') <> '' then '.' else '' endif)+
                      IsNull((select '.'+KstdCode from tabKostendrager where KstdCode=@KstdCode), '');

  //call Trace('@NewRksInvoer='+@NewRksInvoer);
  //call Trace('LET OP : Triggers gaan tijdelijk uit');
  set temporary option fire_triggers = 'off';

  update tabRekeningschema set RksNummer  = @RksNummer,
                               RksKstpGid = (select KstpGid from tabKostenplaats where KstpCode = @KstpCode),
                               RksKstdGid = (select KstdGid from tabKostendrager where KstdCode = @KstdCode),
                               RksInvoer  = @NewRksInvoer
  where  RksInvoer = @RksInvoer;

  //call Trace('Update factuurkop');
  update tabFactuurKop      set fkBtcRksInvoer = @NewRksInvoer where fkBtcRksInvoer = @RksInvoer;

  //call Trace('Update openstaandeposten');
  update tabOpenstaandePost set OspRksInvoer   = @NewRksInvoer where OspRksInvoer   = @RksInvoer;

  //call Trace('Update journaalregel');
  update tabJournaalRegel   set JrRksInvoer    = @NewRksInvoer where JrRksInvoer    = @RksInvoer;

  //call Trace('LET OP : Triggers gaan weer aan');
  set temporary option fire_triggers = 'on';

  //call TraceEind('RenameRksInvoer(@RksInvoer='+@RksInvoer+', @RksNummer='+@RksNummer+')');
  exception when others then resignal
end;


