//----------------------------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='RepareerLevels') then
  drop procedure RepareerLevels;
end if;

create procedure RepareerLevels(in @Level Integer)
begin
  declare @newlevel integer;

  set @Level = IsNull(@Level, 0);
  set @newlevel = @level + 1;

  //call trace('level = ' + string(@level));

  set temporary option fire_triggers = 'off';

  update tabprojectBoom X
  set X.PbLevel = @newlevel
  where     X.pbparentPbGid in (select Y.PbGid from tabprojectboom Y where Y.PbLevel = @Level)
        and X.PbParentPbGid <> X.PbGid;

  set temporary option fire_triggers = 'on';

  //als er op het volgende level nog kindjes zijn dan gaan we een niveau dieper, zo niet dan zijn we klaar.
  if exists(select 1 from tabprojectBoom X where X.pbparentPbGid in (select Y.PbGid from tabprojectboom Y where Y.PbLevel = @newlevel)) then
    call RepareerLevels(@NewLevel);
  end if;
end;


