//--- functie de een string retourneerd met bepaalde tekens vervangen door andere
create or replace function ReplaceChars(in @OriginalText nchar(512), in @TextToReplace nchar(10), in @ReplaceWithText nchar(10))
returns nchar(512)
begin
  declare @NewText   nchar(512);
  declare @Position  integer;

  set @Position = 1;

  while @Position <= length(@OriginalText) loop
    if substr(@OriginalText, @Position, length(@TextToReplace)) = @TextToReplace then
      set @NewText  = @NewText + @ReplaceWithText;
      set @Position = @Position + length(@TextToReplace);
    else
      set @NewText  = @NewText + substr(@OriginalText, @Position, 1);
      set @Position = @Position + 1;
    end if;
  end loop;

  return(@NewText);

end;


create or replace function ReplaceInString( in @regel nchar(1024), in @ToReplace nchar(40), in @ToReplaceWith nchar(80))
returns nchar(1024)
begin
  declare @positie integer;

  //call TraceBegin( 'ReplaceInString(@regel='+@regel+', @ToReplace='+@ToReplace+', @ToReplaceWith='+@ToReplaceWith+')');
  set @positie = charindex( @ToReplace, @regel );
  while @positie<>0 loop
    set @regel = stuff(@regel, @positie, length(@ToReplace), @ToReplaceWith);
    set @positie = charindex( @ToReplace, @regel );
  end loop;

  //call TraceEind( 'ReplaceInString @regel='+@regel);
  return(@regel);

end;


//--- Vervangen string door een andere string
create or replace procedure ReplaceString(in @Tekst nchar(40), in @Zoek nchar(10), in @VervangenDoor nchar(10), inout @NieuweTekst nchar(80))
begin
  declare @Teller integer;

  set @@ErrorTextProcedure = 'ReplaceString > @Tekst='+@Tekst+', @Zoek='+@Zoek+', @VervangenDoor='+@VervangenDoor;
  //call TraceBegin(@@ErrorTextProcedure);

  select ReplaceChars(@Tekst, @Zoek, @VervangenDoor) into @NieuweTekst;

  set @@ErrorTextProcedure = 'ReplaceString > @NieuweTekst='+@NieuweTekst;
  //call TraceBegin(@@ErrorTextProcedure);

end;


