//---------------------------------------------------------------------------
create or replace procedure ResetGegenereerdVolgNummerProjectMut(in @Nummer numeric(10,0), in @Herkomst smallint)
begin
  declare @HuidigeNummer numeric(10,0);
  declare @StartNrVeld nchar(40);

  case @Herkomst
    when 0 then set @StartNrVeld = 'ProjVastStartnummer';
    when 1 then set @StartNrVeld = 'ProjVastStartNummerImportMutaties';
    when 2 then set @StartNrVeld = 'ProjVastStartNummerViaJournaal';
    when 3 then set @StartNrVeld = 'ProjVastStartNummerGekoppeldAanJournaal';
    when 4 then set @StartNrVeld = 'ProjVastStartnummerViaWerkbon';
    when 5 then set @StartNrVeld = 'ProjVastStartnummerViaWeekstaat';
  end case;

  //call TraceBegin('ResetGegenereerdVolgNummerProjectMut');
  execute immediate 'select ' || @StartNrVeld || ' into @HuidigeNummer from tabProjectVastegegevens;';

  if @HuidigeNummer = 0 then
    set @StartNrVeld = 'ProjVastStartnummer';
    execute immediate 'select ' || @StartNrVeld || ' into @HuidigeNummer from tabProjectVastegegevens;';
  end if;

  if (@HuidigeNummer = @Nummer + 1) and (@HuidigeNummer > 1) then
    execute immediate 'update tabProjectVastegegevens set ' || @StartNrVeld || ' =@Nummer;';
  end if;

  //call TraceEind('ResetGegenereerdVolgNummerProjectMut');

end;


