create or replace procedure ResetIdentity()
begin
  declare @MaxGid          integer;
  declare @CurrentIdentity integer;
  declare @Statement       nchar(250);

  set @@ErrorTextProcedure = 'ResetIdentity > ';
  //call TraceBegin(@@ErrorTextProcedure);

  set @MaxGid = 50000000;

  for @Cursor AS CURSOR_Table CURSOR FOR
    select table_name @table, column_name @column
    from  systable
    inner join syscolumn on (systable.table_id = syscolumn.table_id and pkey = 'y' and "default"='autoincrement')
    inner join sysuserperm on (User_Id = Creator and User_name = 'KingSystem')
    where  table_type in ('base', 'gbl temp') and (not table_name in ('tabFileOfNaw', 'tabRapport', 'tabRechtRapLayoutPerGebr'))
    order by table_name
  for read only
  do
    set @Statement = 'set @CurrentIdentity = IsNull((select max(' + @column +') from ' + @table +'), 0)';
    //call trace('ResetIdentity > ' + @Statement);
    execute immediate @Statement;
    //call Trace('ResetIdentity > @Table = ' + string(@Table) + ', @CurrentIdentity = ' + string(@CurrentIdentity));
    if @CurrentIdentity < 10000 then
      set @Statement = 'call sa_reset_identity(''' + @Table + ''', ''KingSystem'', ' + string(@MaxGid) + ')';
      //call trace('ResetIdentity > ' + @Statement);
      execute immediate @Statement;
      set @MaxGid = @MaxGid + 10000;
    else
      set @Statement = 'call sa_reset_identity(''' + @Table + ''', ''KingSystem'', ' + string(@CurrentIdentity+1) + ')';
      //call trace('ResetIdentity > ' + @Statement);
      execute immediate @Statement;
    end if;
  end for;

  set @@ErrorTextProcedure = 'ResetIdentity';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace function SearchCaseSensitive(in @Uniek nchar(80), in @Tekst nchar(40), in @SearchAscValue smallint)
returns smallint
begin
  declare @Position        integer;
  declare @FoundAtPosition smallint;

  set @FoundAtPosition = 0;
  set @Position = 1;
  while @Position <= length(@Tekst) loop
     if Ascii(substr(@Tekst, @Position, 1)) = @SearchAscValue then
       set @FoundAtPosition = @Position;
       set @Position = length(@Tekst);
     end if;
    set @Position = @Position + 1;
  end loop;

  return(@FoundAtPosition)

end;


create or replace procedure SelectieBoomChangeOperator(in @SkGid integer, in @Aanwezig integer, in @AlleenIndienAlle integer)
begin
  declare @Operator integer;

  set @@ErrorTextProcedure = 'SelectieBoomChangeOperator > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @SkGid = ' + string(@SkGid));

  // operator bepalen
  if @Aanwezig = 1 then
    if @AlleenIndienAlle = 1 then
      set @Operator = 1; // and
    else
      set @Operator = 3; // or
    end if;
  else
    if @AlleenIndienAlle = 1 then
      set @Operator = 4; // nor
    else
      set @Operator = 2; // nand
    end if;
  end if;

  // update uitvoeren
  update tabSelectieKnoop set SkOperator = @Operator where SkGid = @SkGid;

  set @@ErrorTextProcedure = 'SelectieBoomChangeOperator';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure SelectieBoomFindNodes(in @SelGid integer, out @AfwezigSkGid integer, out @AanwezigSkGid integer,
                                                  out @AlleenIndienAlleAfwezig integer, out @AlleenIndienAlleAanwezig integer)
begin
  declare @RootGid  integer;
  declare @Operator integer;

  set @@ErrorTextProcedure = 'SelectieBoomFindNodes > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @SelGid = ' + string(@SelGid));

  select SelSkGid into @RootGid
  from   tabSelectie
  where  SelGid = @SelGid;

  //--- gegevens ophalen
  set @AanwezigSkGid = null;
  set @AlleenIndienAlleAanwezig = null;
  select SkGid, skOperator into @AanwezigSkGid, @Operator
  from   tabSelectieKnoop
  where  skParentSkGid = @RootGid and ((skOperator = 1) or (skOperator = 3));

  //--- kijken of 'alleen indien alle'
  if @AanwezigSkGid is not null then
    if @Operator = 1 then // 1 = and
      set @AlleenIndienAlleAanwezig = 1;
    else                  // 3 = or
      set @AlleenIndienAlleAanwezig = 0;
    end if;
  end if;

  //--- gegevens ophalen
  set @AfwezigSkGid = null;
  set @AlleenIndienAlleAfwezig = null;
  select SkGid, skOperator into @AfwezigSkGid, @Operator
  from   tabSelectieKnoop
  where  skParentSkGid = @RootGid and ((skOperator = 2) or (skOperator = 4));

  //--- kijken of 'alleen indien alle'
  if @AfwezigSkGid is not null then
    if @Operator = 2 then // 2 = nand
      set @AlleenIndienAlleAfwezig = 0;
    else                  // 4 = nor
      set @AlleenIndienAlleAfwezig = 1;
    end if;
  end if;

  set @@ErrorTextProcedure = 'SelectieBoomFindNodes';
  //call TraceEind(@@ErrorTextProcedure + ' > @AfwezigSkGid = ' + string(@AfwezigSkGid) + ', @AanwezigSkGid = ' + string(@AanwezigSkGid));
end;


create or replace procedure SelectieBoomInsertLeaf(in @ParentSkGid integer, in @SlcGid integer)
begin
  set @@ErrorTextProcedure = 'SelectieBoomInsertLeaf > ';
  //call TraceBegin(@@ErrorTextProcedure + '@ParentSkGid = ' + string(@ParentSkGid));

  // toevoegen van de knoop --> operator = none --> leaf-node
  insert into tabSelectieKnoop (skOperator, skSlcGid, skParentSkGid) values (0, @SlcGid, @ParentSkGid);

  set @@ErrorTextProcedure = 'SelectieBoomInsertLeaf';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure SelectieBoomInsertTop(out @RootSkGid integer, out @AfwezigSkGid integer, out @AanwezigSkGid integer)
begin
  set @@ErrorTextProcedure = 'SelectieBoomInsertTop > ';
  //call TraceBegin(@@ErrorTextProcedure);

  // toevoegen van de root-knoop --> operator = and
  insert into tabSelectieKnoop (skOperator, skSlcGid, skParentSkGid) values (1, null, null);
  set @RootSkGid = @@Identity;

  // toevoegen aanwezig-knoop --> operator = or
  insert into tabSelectieKnoop (skOperator, skSlcGid, skParentSkGid) values (3, null, @RootSkGid);
  set @AanwezigSkGid = @@Identity;

  // toevoegen afwezig-knoop --> operator = nand
  insert into tabSelectieKnoop (skOperator, skSlcGid, skParentSkGid) values (2, null, @RootSkGid);
  set @AfwezigSkGid = @@Identity;

  set @@ErrorTextProcedure = 'SelectieBoomInsertTop';
  //call TraceEind(@@ErrorTextProcedure + ' > @RootSkGid = ' + string(@RootSkGid));
end;


create or replace procedure SelectieBoomRemoveLeaf(in @SkGid integer)
begin
  declare @Exists integer;

  set @@ErrorTextProcedure = 'SelectieBoomRemoveLeaf > ';
  //call TraceBegin(@@ErrorTextProcedure + '@SkGid = ' + string(@SkGid));

  // controleren of de knoop verwijderd kan worden
  set @Exists = null;
  select first 1 into @Exists
  from   tabSelectieKnoop
  where  skParentSkGid = @SkGid;

  if @Exists is null then
    delete from tabSelectieKnoop where SkGid = @SkGid;
  end if;

  set @@ErrorTextProcedure = 'SelectieBoomRemoveLeaf';
  //call TraceEind(@@ErrorTextProcedure);
end;


//$Workfile: SerieNrVerwijderen.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//------------------------------------------------------------------------------------
//-----------------------Serienummer verwijderen of anders updaten--------------------
//------------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='SerieNrVerwijderen') then
  drop procedure SerieNrVerwijderen;
end if;

create procedure SerieNrVerwijderen(in @ArtSerieGid integer, in @Aantal numeric(15,3), in @WelkAantal smallint)
//@WelkAantal=0 --> AantalInOntvangst eventueel updaten
//@WelkAantal=1 --> AantalInOrder     eventueel updaten

//------------------LET OP !!!!!!!!!!!!!!!!!!-------JV 24-06-03-----------------------
//Deze procedure functioneert niet goed met cascaded delete
//De exception afhandeling werkt dan niet correct
//Cascaded delete dan vervangen door delete in de before delete trigger
//Zie bijvoorbeeld 'tdb_tabMagazijnOntvangstenKop' en 'tdb_tabMagazijnOntvangsten'
//In after delete van tabMagazijnOntvangstLocatieSerie wordt SerieNrVerwijderen namelijk weer aangeroepen
//------------------------------------------------------------------------------------


begin
  declare @Cannot_Delete_1 EXCEPTION FOR SQLSTATE '23W05'; // Primary key for row in table '%1' is referenced by foreign key '%2' in table '%3'
  declare @Cannot_Delete_2 EXCEPTION FOR SQLSTATE '23503'; // No primary key value for foreign key '%1' in table '%2'

  set @@ErrorTextProcedure = 'SerieNrVerwijderen > @ArtSerieGid='+string(@ArtSerieGid)+', @Aantal='+string(@Aantal)+', @WelkAantal='+string(@WelkAantal);
  //call TraceBegin(@@ErrorTextProcedure);

  //call trace('Probeer te verwijderen!');
  begin
    delete from tabArtikelSerienummer where ArtSerieGid = @ArtSerieGid;
    //call trace('Verwijderen gelukt');
    exception  when @Cannot_Delete_1,@Cannot_Delete_2 then
    begin
      //Serienummer kan niet weg, dus dan maar het aantal updaten!
      //call trace('Verwijderen NIET gelukt -> updaten!');
      if @WelkAantal = 0 then
        update tabArtikelSerienummer set ArtSerieAantalInOntvangst = ArtSerieAantalInOntvangst - @Aantal  where ArtSerieGid = @ArtSerieGid;
      else
        update tabArtikelSerienummer set ArtSerieAantalInOrder     = ArtSerieAantalInOrder     - @Aantal  where ArtSerieGid = @ArtSerieGid;
      end if;
    end;
  end;
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: SerienummerAantalWisselen.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='SerienummerAantalWisselen') then
  drop procedure SerienummerAantalWisselen;
end if;

create procedure SerienummerAantalWisselen(in @SoortAantal smallint, in @OudeArtSerieGid integer, in @OudeAantal numeric(15,3), in @NieuweArtSerieGid integer, in @NieuweAantal numeric(15,3))
begin
  // @SoortAantal: 0 = InOrder
  //               1 = InOntvangst
  //               2 = InProductieComponent (Let op: deze is precies tegenovergesteld, omdat InProd. als verhoging wordt gezien, terwijl Componentengebruik juist een verbruik betreft)
  //               3 = InProductieEindproduct
  //               4 = InProjectmutatie
  //               5 = InCorrectie
  //               6 = Geleverd
  //               7 = Ontvangen
  //               8 = Gecorrigeerd
  set @@ErrorTextProcedure = 'SerienummerAantalWisselen(@OudeArtSerieGid='+string(@OudeArtSerieGid) + '  @OudeAantal='+string(@OudeAantal)+', @NieuweArtSerieGid='+string(@NieuweArtSerieGid)+', @NieuweAantal='+string(@NieuweAantal);
  //call TraceBegin(@@ErrorTextProcedure);

  // Test oude serienummer
  // Oude aantal is 0? dan hoeven we het oude serienummer nooit te verlagen!
  if @OudeAantal = 0 then                // Oude serienummer is gevuld! Als aantal leeg, dan de oude NIET updaten
    set @OudeArtSerieGid = null;         // oftewel, gewoon serienummergid leeg halen
  end if;

  // Test nieuwe serienummer
  if @NieuweArtSerieGid is not null then
    if @OudeArtSerieGid is not null and @OudeArtSerieGid = @NieuweArtSerieGid then
      // Nieuwe serie is ZELFDE als oude, dus nieuwe aantal is het verschil!
      // EN de oude hoeven we NIET meer aan te passen (2 vliegen in 1 klap)
      set @NieuweAantal = @NieuweAantal - @OudeAantal;
      set @OudeArtSerieGid = null;
    end if;
  end if;

  // Is nieuwe aantal 0? dan hoeven we het nieuwe serienummer nooit te verhogen!
  if @NieuweAantal = 0 then
    set @NieuweArtSerieGid = null;
  end if;

  // Oude serienummer updaten (verlagen met OUDE aantal)
  if @OudeArtSerieGid is not null then
    update tabArtikelSerienummer
    set    ArtSerieAantalInOrder          = ArtSerieAantalInOrder          - if @SoortAantal = 0 then @OudeAantal else 0 endif,
           ArtSerieAantalInOntvangst      = ArtSerieAantalInOntvangst      - if @SoortAantal = 1 then @OudeAantal else 0 endif,
           ArtSerieAantalInProductie      = ArtSerieAantalInProductie      + if @SoortAantal = 2 then @OudeAantal else 0 endif
                                                                           - if @SoortAantal = 3 then @OudeAantal else 0 endif,
           ArtSerieAantalInProjectMutatie = ArtSerieAantalInProjectMutatie - if @SoortAantal = 4 then @OudeAantal else 0 endif,
           ArtSerieAantalInCorrectie      = ArtSerieAantalInCorrectie      - if @SoortAantal = 5 then @OudeAantal else 0 endif,
           ArtSerieAantalGeleverd         = ArtSerieAantalGeleverd         - if @SoortAantal = 6 then @OudeAantal else 0 endif,
           ArtSerieAantalOntvangen        = ArtSerieAantalOntvangen        - if @SoortAantal = 7 then @OudeAantal else 0 endif,
           ArtSerieAantalGecorrigeerd     = ArtSerieAantalGecorrigeerd     - if @SoortAantal = 8 then @OudeAantal else 0 endif
    where  ArtSerieGid = @OudeArtSerieGid;
  end if;

  // Nieuwe (of zelfde!) serienummer updaten (verhogen met NIEUWE aantal)
  if @NieuweArtSerieGid <> 0 then
    update tabArtikelSerienummer
    set    ArtSerieAantalInOrder          = ArtSerieAantalInOrder          + if @SoortAantal = 0 then @NieuweAantal else 0 endif,
           ArtSerieAantalInOntvangst      = ArtSerieAantalInOntvangst      + if @SoortAantal = 1 then @NieuweAantal else 0 endif,
           ArtSerieAantalInProductie      = ArtSerieAantalInProductie      - if @SoortAantal = 2 then @NieuweAantal else 0 endif
                                                                           + if @SoortAantal = 3 then @NieuweAantal else 0 endif,
           ArtSerieAantalInProjectMutatie = ArtSerieAantalInProjectMutatie + if @SoortAantal = 4 then @NieuweAantal else 0 endif,
           ArtSerieAantalInCorrectie      = ArtSerieAantalInCorrectie      + if @SoortAantal = 5 then @NieuweAantal else 0 endif,
           ArtSerieAantalGeleverd         = ArtSerieAantalGeleverd         + if @SoortAantal = 6 then @NieuweAantal else 0 endif,
           ArtSerieAantalOntvangen        = ArtSerieAantalOntvangen        + if @SoortAantal = 7 then @NieuweAantal else 0 endif,
           ArtSerieAantalGecorrigeerd     = ArtSerieAantalGecorrigeerd     + if @SoortAantal = 8 then @NieuweAantal else 0 endif
    where  ArtSerieGid = @NieuweArtSerieGid;
  end if;


  set @@ErrorTextProcedure = 'SerienummerAantalWisselen';
  //call TraceEind(@@ErrorTextProcedure);

end;


//------------------------------------------------------------------------------
//-----------------------Automatisch serienummer genereren----------------------
//------------------------------------------------------------------------------
create or replace procedure SerienummerGenereerNummer(in @ArtGid integer,
                                           in @ForceerGenereren smallint,
                                           out @Nummer nchar(20),
                                           out @FoutNr integer,
                                           out @FoutBericht nchar(256),
                                           out @NieuwVolgNr numeric(10,0))
begin
  declare @Startnummer      numeric(10,0);      // ArtPartijNrStartNummer       numeric (10,0)
  declare @NieuwNummer      nchar(20);
  declare @VolgNrUitvullen  smallint;           // ArtPartijNrVolgnrUitvullen   smallint
  declare @VolgNrLengte     integer;            // ArtPartijNrLengteVolgnr      integer
  declare @TekstVoor        nchar(10);           // ArtPartijNrTekstVoor         nchar(10)
  declare @TekstAchter      nchar(10);           // ArtPartijNrTekstAchter       nchar(10)
  declare @Genereren        smallint;           // ArtIsPartijNrGenereren       smallint
  declare @Resultaat        smallint;           // -1 = niet te genereren | 0 = nog geen nieuw nummer | 1 = nieuw nummer

  set @@ErrorTextProcedure = 'SerienummerGenereerNummer > @ArtGid=' + string(@ArtGid) + ', @ForceerGenereren=' + string(@ForceerGenereren);
  //call TraceBegin(@@ErrorTextProcedure);

  set @nummer      = '';
  set @Resultaat   = 0;
  set @FoutNr      = -1;
  set @FoutBericht = '';

  select ArtSerieNrGenereren   , ArtSerieNrStartNummer, ArtSerieNrVolgnrUitvullen,
         ArtSerieNrLengteVolgnr, ArtSerieNrTekstVoor  , ArtSerieNrTekstAchter
  into   @Genereren            , @Startnummer         , @VolgNrUitvullen,
         @VolgNrLengte         , @TekstVoor           , @TekstAchter
  from   tabArtikel
  where  ArtGid = @ArtGid;


  //call Trace('@Genereren = ' + String(@Genereren) + ', @startnummer = ' + string(@startnummer) + ', @TekstVoor = ' + @TekstVoor + ', @TekstAchter = ' + @TekstAchter);
  //wanneer een serienummer normaal gesproken niet automatisch een serienr genereert, maar in dit specifieke geval wel.
  if @ForceerGenereren = 1 then
    set @Genereren = 1;
  end if;

  if @Genereren = 0 then
    set @Resultaat = -1;
    set @FoutNr =  0;
  else // @Genereren = 1 then
    while @Resultaat = 0 and @Startnummer <= 9999999999 loop
      // Bepaal nieuw te gebruiken serienummer o.b.v. @startnummer
      set @NieuwNummer = string(@Startnummer);

      // Evt. uitvullen van nummer
      if @VolgNrUitvullen = 1 then                    // uitvullen is aangevinkt.
        if Length(@NieuwNummer) > @VolgNrLengte then  // als groter, dan zou er een stuk afgehakt worden bij Right().
          set @Resultaat = -1;                        // dus niet genereren, en gebruiker zelf in laten vullen.
          set @FoutNr    =  1;
        else
          set @NieuwNummer = Right('0000000000' + @NieuwNummer, @VolgNrLengte);
        end if;
      end if;

      if (@Resultaat = 0) and (Length(@TekstVoor + @NieuwNummer + @TekstAchter) > 20) then
        set @Resultaat = -1; // serienummer te lang!
        set @FoutNr    =  2;
      else
        // lengte oke, dus geldig nummer fabriceren
        set @NieuwNummer = @TekstVoor + @NieuwNummer + @TekstAchter;
      end if;

      // Test of nieuwe serienummer al bestaat
      if @Resultaat = 0 then
        if not exists (select 1
                       from   tabArtikelSerienummer
                       inner  join tabArtikelPartij on ArtSeriePartijGid = ArtPartijGid
                       where  ArtPartijArtGid = @ArtGid
                         and  ArtSerienummer  = @NieuwNummer) then
          set @Resultaat = 1;
        end if;
      end if;

      // Verhoog het startnummer
      if @Startnummer < 9999999999 then
        set @Startnummer = @Startnummer + 1;
      else
        if @Resultaat = 0 then
          set @Resultaat = -1;
          set @FoutNr    = 3;
        end if;
      end if;
    end loop;

    // het nieuwe nummer kan gebruikt worden. Nummer teruggeven en artikeltabel updaten met nieuwe volgnummer.
    if @Resultaat = 1 then
      //call Trace('Nieuw serienummer: ' + @NieuwNummer);
      set @Nummer = @NieuwNummer;

      if Length(@TekstVoor + string(@StartNummer) + @TekstAchter) < 21 then
        //call Trace('Updaten nieuwe startnummer: ' + string(@StartNummer));
        update tabArtikel set ArtSerieNrStartNummer = @Startnummer where ArtGid = @ArtGid;
        set @NieuwVolgNr = @Startnummer;
      end if;
    end if;
  end if;

  //foutbericht maken over de fout
  case @FoutNr
    when 0 then set @FoutBericht = _U('Serienummer genereren niet gelukt: \nVoor dit artikel wordt niet automatisch een serienummer aangemaakt! \nGa naar programma Artikelen om de instelling ''automatisch genereren serienummer'' te wijzigen.');
    when 1 then set @FoutBericht = _U('Serienummer genereren niet gelukt: \nHet volgnummer van het serienummer wordt te groot! Voer een ander serienummer in of verhoog in programma Artikelen de ''Lengte'' van het volgnummer.');
    when 2 then set @FoutBericht = _U('Serienummer genereren niet gelukt: \nHet serienummer wordt te lang!');
    when 3 then set @FoutBericht = _U('Serienummer genereren niet gelukt: \nHet hoogste volgnummer is bereikt: %1!!', '9.999.999.999');
  end case;

  set @@ErrorTextProcedure = 'SerienummerGenereerNummer > @nummer=' + @nummer + ', @FoutNr=' + string(@FoutNr) + ', @FoutBericht=' + string(@FoutBericht) + ', @NieuwVolgNr=' + string(@NieuwVolgNr);
  //call TraceEind(@@ErrorTextProcedure);

end;


//ACW 24-09-2015 wens #45632: Database automatisch verkleinen
create or replace procedure SetEventTruncateLog(in @Aan integer)
//@Aan: 0 = UIT zetten, 1 = AAN zetten, iets anders = REFRESH
begin
  declare @IsNuAan integer;

  set @@ErrorTextProcedure = 'SetEventTruncateLog. Aan=' + string(@Aan);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Aan = isnull(@Aan, 2); // Leeg? Dat is dus een refresh

  call IsEventTruncateLogAAN(@IsNuAan);
  if @IsNuAan = 1 then
    drop event TruncateLog;
  end if;

  if (@Aan = 1) or (@Aan <> 0 and @IsNuAan = 1) then
    //AAN zetten of REFRESHen
    execute immediate '
/* Cerate or replace werkt niet!! */
create event TruncateLog
schedule start time ''00:19'' every 3 hours
handler
begin
  declare @UrenGeleden              integer;
  declare @DatumTijdLaatstGedraaid  datetime;
  declare @EventOmschrijving        nchar(160);
  declare @LogGid                   integer;
  declare @DbSize                   numeric(15,0);
  declare @LogSize                  numeric(15,0);


  call DatabaseInit();
  //create variable @@ErrorTextProcedure nchar(500);

  set @UrenGeleden       = 24;                                      /*Minimaal aantal uren dat verstreken moet zijn, voordat daadwerkelijk de inhoud van het event wordt uitgevoerd*/
  set @EventOmschrijving = ''TruncateLog : log-bestand verkleinen'';  /*String wordt gebruikt om terug te zoeken in het log wanneer voor het laatst gedraaid is*/

  /*Laatste keer dat event daadwerkelijk is uitgevoerd*/
  select max(LogTimeStamp) into @DatumTijdLaatstGedraaid from tabLog where LogSoort = 15 and LogOmschrijving like @EventOmschrijving+''%'';

  /*Laatste keer event was max. ?? uur geleden?*/
  if abs(datediff(hour, isnull(@DatumTijdLaatstGedraaid, ''2010-01-01''), now())) > @UrenGeleden then

    set @DbSize  = Db_property(''filesize'') * Db_Property(''pagesize'') / 1024000;                       /*Grootte van database file in MBs*/
    set @LogSize = Db_Extended_Property(''filesize'', ''translog'') * Db_Property(''pagesize'') / 1024000;  /*Grootte van log file in MBs*/

    if ((@DbSize <  10000) and (@LogSize / @DbSize > 0.20)) or    /*Database <  10GB en logfile > 20% van database, dan truncate*/
       ((@DbSize >= 10000) and (@LogSize / @DbSize > 0.10)) then  /*Database >= 10GB en logfile > 10% van database, dan truncate*/

      insert into tabLog(LogSoort, LogAdmCode, LogBjCode, LogUserName, LogMachineName, LogOmschrijving)
      values(15, Db_Name(), '''', '''', '''', @EventOmschrijving + '' wordt uitgevoerd (logfile was '' + string(@LogSize) + '' MB).'');
      commit; /* Omdat anders het log niet wordt bijgewerkt na een fout!*/
      set @LogGid = @@Identity;

      call LogfileTruncate();

      /*En log updaten om aan te geven dat het was gelukt*/
      update tabLog
      set    LogOmschrijving = @EventOmschrijving + '' is uitgevoerd (logfile was '' + string(@LogSize) + '' MB).''
      where  LogGid = @LogGid;
    end if;
  end if;
exception
  when others then
    rollback;
    insert into tabLog(LogSoort, LogAdmCode, LogBjCode, LogUserName, LogMachineName, LogOmschrijving)
    values(15, Db_Name(), '''', '''', '''', ''TruncateLog: Fout '' + SQLSTATE + '' in '' + Error_Procedure()+ '', regel '' + string(Error_line()) + '': '' + CAST(ERROR_MESSAGE() AS VARCHAR(50)));
    commit; /* Omdat anders het log niet wordt bijgewerkt na een fout!*/
end;

    ';

  end if;

  // Onthouden in de vaste gegevens!
  update tabVasteGegevens set VgLogfileVerkleinen = @aan where VastId = 1 and VgLogfileVerkleinen <> @aan;

  set @@ErrorTextProcedure = 'SetEventTruncateLog';
  //call TraceEind(@@ErrorTextProcedure);
END;



create or replace procedure SetOrderGewijzigdNaAfdruk(in @OrkGid integer, in @Soort nchar(1))
begin
  // Instelling in vaste geg ord/fact: 'Markeren als gewijzigd na wijziging van'
  // @soort:   A  = regel- of ordertotaal
  // 	       B  = aantal deze levering
  // 	       C  = aantal nu te factureren
  // 	       D  = kop- of vaste gegevens
  // 	       E  = gegevens orderregel
  // 	       F  = contactpersoon
  // 	       G  = CBS-gegevens
  // 	       H  = status 'goedgekeurd'
  // 	       I  = opmerking

  // Docsoort: 10 = Offerte
  //           20 = Orderbevestiging
  //           30 = Pakbon
  //           40 = Proforma-nota
  //           50 = Factuur 'batch'
  //           60 = Factuur 'direct'
  //           70 = Acceptgiro
  //           80 = Aanmaning/Rek.overzicht
  set @@ErrorTextProcedure = 'SetOrderGewijzigdNaAfdruk > OrkGid='+string(@OrkGid);
  //call TraceBegin(@@ErrorTextProcedure);
  if @@InFacturering = 0 then
    UPDATE tabOrderDocGegevens
    SET    OrdDocGegGewijzigdNaAfdruk = 1,
           OrdDocGewijzigdDoor = @@gebruikercode
    WHERE (OrdDocOrkGid = @OrkGid) AND (OrdDocGegAfgedrukt=1) AND
    	  // Zit de veranderingssoort in de instellingen?
    	  (Locate((SELECT DocOrdGewijzigdNa FROM tabDocument WHERE DocSoort = OrdDocDocSoort), @soort, 1) > 0);
  end if;

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace function SomRekeningNummer(
  in @BankRekening nchar(35),
  in @NederlandseIBANalsBBAN smallint) //1 = Probeer van een geldige Nederlandse IBAN de BBAN te lezen en gebruik die in de berekening
returns numeric(10,0)
begin
  declare @teller integer;
  declare @Result numeric(10,0);
  declare @HulpChar nchar(1);

  set @@ErrorTextProcedure = 'SomRekeningNummer > ' + @BankRekening;
  //call TraceBegin(@@ErrorTextProcedure);

  // Indien alleen numeriek, dan de waarde teruggeven, anders omrekenen
  set @result = 0;

  // In Clieop proberen om de som toch o.b.v. de BBAN te doen
  if @NederlandseIBANalsBBAN = 1 then
    if IsValidIBAN(@BankRekening) = 1 and Substr(@BankRekening, 1, 2) = 'NL' and IsNumeric(SubStr(@BankRekening, 9, 10)) = 1 then
      set @BankRekening = SubStr(@BankRekening, 9, 10);
    end if;
  end if;

  if isnull(@BankRekening, '') <> '' then
    if IsNumeric(@BankRekening) <> 0 and length(@BankRekening) <= 10 then
      set @result = @BankRekening
    else
      // Berekening om alfanumeriek te verkleinen
      // Voor elk karakter:
      //  Is cijfer? -> Cijfer * oorspronkelijke positie in string
      //  Is alfabetisch? -> (10 + plaats in alfabet) * oorspronkelijke positie in string
      // Tel alles bij elkaar op
      //
      // Hoogste waar is dus de Z + 10 = 36. Als alle karakters een Z is, dan is het totaal: 22680.
      // Berekening: 1+2+3+...+35 = (35(35+1)) / 2 = (35+1) boven 2
      // Maximum = 36 * 1 + 36 * 2 + 36 * 3 + ... + 36 * 35 = 36 * (1+2+3..+35) = 36* ((35*(35+1))/2) = 36 * 630 = 22680
      set @teller = 1;
      while @teller <= length(@Bankrekening) loop
        set @HulpChar = substr(@Bankrekening, @teller, 1);
        set @result = @result + Locate('1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ', @HulpChar) * @teller;
        //call trace('|' +@HulpChar+'|'+string(@result) + ' = ' + string(@teller) + ' * ' + string(Locate('1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ', @HulpChar)) + ' = ' + string(Locate('1234567890ABCDEFGHIJKLMNOPQRSTUVWXYZ', @HulpChar) * @teller) + ' cumulatief: ' + string(@result));
        set @teller = @teller + 1;
      end loop;
    end if;
  end if;


  set @@ErrorTextProcedure = 'SomRekeningNummer > Result = ' + string(@Result);
  //call TraceEind(@@ErrorTextProcedure);
  return (@Result);

end;

create or replace procedure sqlAanmaningenTabelVullenVoorInstellenLayout(inout @Id integer, in @BjGid integer, out @AcbGid integer)
begin
  //-------------------------------------------------------------------------
  //-------- Vul tijdelijke tabel tbv instellen layout aanmaningen ----------
  //-------------------------------------------------------------------------
  declare @NawFilNummer nchar(10);

  set @@ErrorTextProcedure = 'sqlAanmaningenTabelVullenVoorInstellenLayout > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Id = '  + string(@Id) + ', @BjGid = ' + string(@BjGid));

  set @NawFilNummer = null;

  if @Id is null then
    call RandomNumber2(@Id);
    call LockSetOnId(@@SpId, @@LoginTime, 0, 'tabAanmaningLayoutInstellen', 'AanmAfdrId='+string(@Id), 0);
  end if;

  delete tabAanmaningAfdrukken where AanmAfdrId = @Id;

  // voor het instellen van de layout gebruiken we hier de debiteur met de meeste openstaande posten, en deze drukken we allemaal af !!!
  select  first NawFilNummer
  into    @NawFilNummer
  from    tabOpenstaandePost inner join (tabNawFile inner join tabNaw on (NawGid = NawFilNawGid) inner join tabFileOfNaw on (FonGid = NawFilFonGid)) on (NawFilRksGid = OspRksGid)
  where  (fonID='D')
    and  (OspBjGid = @BjGid)
    and  (OspValNummer=@@BasisValutaNummer)
    and  OspIsVervallen = 0
  group by NawFilNummer
  order by count(OspGid) desc;

  //call Trace('Ga vullen');
  insert into tabAanmaningAfdrukken(AanmAfdrId, AanmAfdrRksNummer, AanmAfdrRksZoekcode, AanmAfdrOspGid,
                                    AanmAfdrTaalGid, AanmAfdrAanmDatum, AanmAfdrVervaldatum, AanmAfdrIsAfgedrukt,
                                    AanmAfdrHoogstNrPerDebPerValuta, AanmAfdrAanmnr,
                                    AanmAfdrOpenstaandBedrag, AanmAfdrVervallenBedrag, AanmAfdrValNummer, AanmAfdrIsGeblokkeerd,
                                    AanmAfdrFaktuurnr, AanmAfdrFaktuurnr_Lengte, AanmAfdrFaktuurDatum, AanmAfdrBetkenmerk, AanmAfdrOms, AanmAfdrFaktuurBedrag,
                                    AanmAfdrBetaaldBedrag, AanmAfdrValCode, AanmAfdrDatumLaatsteAanmaning)
  select  @Id, NawFilNummer, NawFilZoekcode, OspGid,
          NawTaalGid, @@VerwerkingsDatum, OspVervaldatum, 0,
          1,
          OspAanmaningTeller+1 AanmAfdrAanmnr,
         (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig),
         (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig),
          OspValNummer, OspIsGeblokkeerd,
          OspFactuurNummer, OspFactuurNummer_Lengte, OspFactuurDatum, OspBetalingsKenmerk, OspOms, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig),
          (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), OspValCode, OspLaatsteAanmaning
  from    tabOpenstaandePost inner join (tabNawFile inner join tabNaw on (NawGid = NawFilNawGid) inner join tabFileOfNaw on (FonGid = NawFilFonGid)) on (NawFilRksGid = OspRksGid)
  where   (OspBjGid = @BjGid)
    and   (fonID='D')
    and  (NawFilNummer = @NawFilNummer)
    and  (OspValNummer=@@BasisValutaNummer)
    and   OspIsVervallen = 0;

  // Als laatste een acceptgirotabel aanmaken o.b.v. dit bestand
  call AanmaningCreateAcceptGiroBatch(@Id, 0, 1, 0, 0, @AcbGid);

  set @@ErrorTextProcedure = 'sqlAanmaningenTabelVullenVoorInstellenLayout';
  //call TraceEind(@@ErrorTextProcedure);
end;


//$Workfile: StartRepareerLevelsEnVolgNummers.sp $ $Revision: 1 $ $Modtime: 5-02-07 6:58 $'

if exists (select 1 from sys.sysProcedure where proc_name='StartRepareerLevelsEnVolgNummers') then
  drop procedure StartRepareerLevelsEnVolgNummers;
end if;

create procedure StartRepareerLevelsEnVolgNummers()
begin
  declare @newlevel integer;

  //levels opnieuw bepalen.
  set temporary option fire_triggers = 'off';
  update tabprojectboom set PbLevel = null, PbVolgnr = null;
  update tabprojectboom set PbLevel = 0 where PbGid = pbparentPbGid;
  call repareerlevels(0);
  set temporary option fire_triggers = 'on';

  //volgnummers opnieuw bepalen.
  update tabprojectboom set PbVolgnr = 0 order by pbomschr;
end;


create or replace function StripString (in @StringToCheck nchar(40), in @ValidChars nchar(80))

returns nchar(40)
begin
  declare @teller smallint;

  set @Teller = 1;

  while @Teller<=length(@StringToCheck) loop
    if locate(@ValidChars, substr(@StringToCheck,@Teller,1))=0 then
      set @StringToCheck = substr(@StringToCheck, 1,(@Teller - 1 )) + substr(@StringToCheck, (@Teller + 1));
    else
      set @Teller = @Teller + 1;
    end if;
  end loop;

  return(@StringToCheck);

end;


//$Workfile: StukvolgnrGenereerNieuw.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//----------- Geef nieuw gegenereerd stukvolgnummer terug
if exists (select 1 from sys.sysProcedure where proc_name='StukvolgnrGenereerNieuw') then
  drop function StukvolgnrGenereerNieuw;
end if;

create function StukvolgnrGenereerNieuw( in @JpGid integer, in @JrNummer integer)
returns integer
begin
  declare @StukVolgnr integer;

  set @@ErrorTextProcedure = 'StukvolgnrGenereerNieuw > @JpGid='+string(@JpGid)+', @JrNummer='+string(@JrNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  call StukvolgnrGenereren( @JpGid, @JrNummer, @StukVolgnr);

  set @@ErrorTextProcedure = 'StukvolgnrGenereerNieuw > @StukVolgnr='+string(@StukVolgnr);
  //call TraceEind(@@ErrorTextProcedure);
  return(@StukVolgnr);

end;


//$Workfile: StukvolgnrGenereren.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='StukvolgnrGenereren') then
  drop procedure StukvolgnrGenereren;
end if;

create procedure StukvolgnrGenereren(in @JpGid integer, in @JrNummer integer, out @StukVolgnr integer)
begin
  set @@ErrorTextProcedure = 'StukvolgnrGenereren > @JpGid='+string(@JpGid)+', @JrNummer='+string(@JrNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if exists (select 1 from tabJournaalregel where JrJpGid=@JpGid and JrNummer<@JrNummer) then
    select first IsNull(StukVolgnr,0)+1 into @StukVolgnr from tabJournaalregel where JrJpGid=@JpGid and JrNummer<@JrNummer order by JrNummer desc;
  else
    set @StukVolgnr=1;
  end if;

  if @StukVolgnr > 999 then
    set @StukVolgnr = 999;
  end if;

  set @@ErrorTextProcedure = 'StukvolgnrGenereren > @StukVolgnr='+string(@StukVolgnr);
  //call TraceEind(@@ErrorTextProcedure);

end;


//------------------------------------------------------
//  Bepalen gegevens tn behoeve van de sybaseafdracht //
//------------------------------------------------------
create or replace procedure SybaseAfdracht(in @VanDatum Date, in @TotDatum Date)

result(AangemaaktOpNieuw  date,     Pakket            nchar(20), Licentienr           Integer,
       ReleaseOud         nchar(10), ReleaseNieuw      nchar(10), GebruikersOud        integer,  GebruikersNieuw   integer,
       Licentiesoort      nchar(40), Selecties         nchar(80), AangemaaktDoorNieuw  nchar(10),
       AangemaaktOpOud    date,     AangemaaktDoorOud nchar(10))
begin
  declare @tmpSaPktsGid             integer;
  declare @tmpSaLicGid              integer;
  declare @tmpSaLicNawFilGid        integer;
  declare @tmpSaNewRelease          nchar(10);
  declare @tmpSaNewAantalGebruikers integer;
  declare @tmpSaNewAangemaaktOp     Date;
  declare @tmpSaNewAangemaaktDoor   nchar(10);
  declare @tmpSaOldRelease          nchar(10);
  declare @tmpSaOldAantalGebruikers integer;
  declare @tmpSaOldAangemaaktOp     Date;
  declare @tmpSaOldAangemaaktDoor   nchar(10);
  declare @tmpSaDebSelecties        nchar(80);

  declare @LicNewRelease            nchar(10);
  declare @LicNewAantalGebruikers   integer;
  declare @LicNewAangemaaktOp       Date;
  declare @LicNewAangemaaktDoor     nchar(10);

  declare @HistNewRelease           nchar(10);
  declare @HistNewAantalGebruikers  integer;
  declare @HistNewAangemaaktOp      Date;
  declare @HistNewAangemaaktDoor    nchar(10);

  declare @SlcGidExQueen            integer;
  declare @SlcGidTijdelijkeUpdate   integer;
  declare @SlcGidKingMobile         integer;

  declare @aantalLics integer;

  declare @StandaardTekst        long nvarchar;
  declare @AccountantTekst       long nvarchar;
  declare @EducatiefTekst        long nvarchar;
  declare @DealerDemoTekst       long nvarchar;
  declare @DealerGebruikTekst    long nvarchar;
  declare @VerplichteDealerTekst long nvarchar;
  declare @CursusTekst           long nvarchar;
  declare @PromotieMetEvalTekst  long nvarchar;
  declare @PromotieZonEvalTekst  long nvarchar;
  declare @EvaluatieTekst        long nvarchar;

  declare local temporary table tmpSybaseAfdracht(
    tmpSaPktsGid              integer,
    tmpSaLicGid               Integer,
    tmpSaLicNummer            Integer,
    tmpSaLicNawFilGid         Integer,
    tmpSaLicSoort             Integer,
    tmpSaDebSelecties         nchar(80),
    tmpSaOldRelease           nchar(10),
    tmpSaOldAantalGebruikers  integer,
    tmpSaOldAangemaaktOp      date,
    tmpSaOldAangemaaktDoor    nchar(10),
    tmpSaNewRelease           nchar(10),
    tmpSaNewAantalGebruikers  integer,
    tmpSaNewAangemaaktOp      date,
    tmpSaNewAangemaaktDoor    nchar(10),
    primary key (tmpSaPktsGid, tmpSaLicNummer)
  ) on commit preserve rows;

  declare cursor_TmpSybaseVul cursor for
    select tmpSaPktsGid,    tmpSaLicGid, tmpSaLicNawFilGid
    from tmpSybaseAfdracht
    order by tmpSaPktsGid, tmpSaLicNummer
  for update;

  set @@ErrorTextProcedure = 'SybaseAfdracht > @VanDatum='+string(@VanDatum)+' @TotDatum='+string(@TotDatum);
  //call TraceBegin(@@ErrorTextProcedure);

  set @SlcGidExQueen = null;
  set @SlcGidTijdelijkeUpdate = null;
  set @SlcGidKingMobile = null;
  select slcGid into @SlcGidExQueen           from tabSelectiecodes where SlcCode = 'VXQ' and SlcSltGid = (SELECT fonSltGid FROM tabFileOfNaw WHERE fonID = 'D');
  select slcGid into @SlcGidTijdelijkeUpdate  from tabSelectiecodes where SlcCode = 'KT2' and SlcSltGid = (SELECT fonSltGid FROM tabFileOfNaw WHERE fonID = 'D');
  select slcGid into @SlcGidKingMobile        from tabSelectiecodes where SlcCode = 'KHM' and SlcSltGid = (SELECT fonSltGid FROM tabFileOfNaw WHERE fonID = 'D');

  //-------------------------------------------------------------------------------
  //  Eerst alle licentienumemrs toevoegen die binnen de periode zijn gewijzigd  //
  //-------------------------------------------------------------------------------
  set @@ErrorTextProcedure = 'SybaseAfdracht : Vul tmpSybaseAfdracht met licentienummers';
  //call Trace(@@ErrorTextProcedure);

  insert into tmpSybaseAfdracht(  tmpSaPktsGid,       tmpSaLicGid,              tmpSaLicNummer,
                                  tmpSaLicNawFilGid,  tmpSaLicSoort,            tmpSaDebSelecties,
                                  tmpSaOldRelease,    tmpSaOldAantalGebruikers, tmpSaOldAangemaaktOp, tmpSaOldAangemaaktDoor,
                                  tmpSaNewRelease,    tmpSaNewAantalGebruikers, tmpSaNewAangemaaktOp, tmpSaNewAangemaaktDoor)
  select                          LicPktsGid,         LicGid,                   LicNummer,
                                  LicNawFilGid,       LicSoort,                 '',
                                  null,               null,                     null,                 null,
                                  null,               null,                     null,                 null
  from  tabLicentie
        left outer join tabLicentieChecksum on (LchkLicGid=LicGid)
  where (LicNummer <> 0)
    and (
         ((LicCsAangemaaktOp >= @vandatum) and (LicCsAangemaaktOp <(@TotDatum+1)))
     or  (( LchkAangemaaktOp >= @vandatum) and ( LchkAangemaaktOp <(@TotDatum+1)) and (LicCsAangemaaktOp >=(@TotDatum+1)))
        )
  group by LicPktsGid, LicGid, LicNummer, LicNawFilGid, LicSoort;


  set @@ErrorTextProcedure = 'SybaseAfdracht : Aanmaken index';
  //call Trace(@@ErrorTextProcedure);
  Create index idx_tmpSybaseAfdracht on tmpSybaseAfdracht (tmpSaPktsGid, tmpSaLicGid);


  //-------------------------------------------------
  //  Updaten tijdelijke tabel met juiste waardes  //
  //-------------------------------------------------
  Select count(1) into @aantalLics from tmpSybaseAfdracht;
  set @@ErrorTextProcedure = 'SybaseAfdracht : Update tmpSybaseAfdracht met cheksumgegevens. Aantal records : '+String(@aantalLics);
  //call Trace(@@ErrorTextProcedure);

  open cursor_TmpSybaseVul;
  LoopVolgende:
  loop
    Fetch next cursor_TmpSybaseVul into @tmpSaPktsGid, @tmpSaLicGid, @tmpSaLicNawFilGid;

    if sqlstate = '02000' then
      leave LoopVolgende;
    end if;

    set @tmpSaNewRelease          = null;
    set @tmpSaNewAantalGebruikers = null;
    set @tmpSaNewAangemaaktOp     = null;
    set @tmpSaNewAangemaaktDoor   = null;
    set @LicNewRelease            = null;
    set @LicNewAantalGebruikers   = null;
    set @LicNewAangemaaktOp       = null;
    set @LicNewAangemaaktDoor     = null;
    set @HistNewRelease           = null;
    set @HistNewAantalGebruikers  = null;
    set @HistNewAangemaaktOp      = null;
    set @HistNewAangemaaktDoor    = null;
    set @tmpSaOldRelease          = null;
    set @tmpSaOldAantalGebruikers = null;
    set @tmpSaOldAangemaaktOp     = null;
    set @tmpSaOldAangemaaktDoor   = null;
    set @tmpSaDebSelecties        = null;

    // Ophalen huidige checksumgegevens uit licentie
    select  PktrCode, LicCsAantalGebruikers,   LicCsAangemaaktOp, LicCsAangemaaktDoor
    into   @LicNewRelease, @LicNewAantalGebruikers, @LicNewAangemaaktOp, @LicNewAangemaaktDoor
    From   tabLicentie left outer join tabPakketRelease on (pktrGid=LicCsPktrGid)
    where  LicGid=@tmpSaLicGid;

    // Ophalen Laatste gegevens uit checksumhistorie
    select  First PktrCode,   LchkAantalGebruikers,   LchkAangemaaktOp, LchkAangemaaktDoor
    into   @HistNewRelease, @HistNewAantalGebruikers, @HistNewAangemaaktOp, @HistNewAangemaaktDoor
    From   tabLicentieChecksum left outer join tabPakketRelease on (pktrGid=LchkPktrGid)
    where  (LchkLicGid=@tmpSaLicGid)
      and  (LchkAangemaaktOp >= @vandatum) and (LchkAangemaaktOp <(@TotDatum+1))
    order by LchkAangemaaktOp desc;

    // welke nieuwe gegevens zijn de juiste?
    if ((@LicNewAangemaaktOp >= @vandatum) and (@LicNewAangemaaktOp <(@TotDatum+1))) then
      set @tmpSaNewRelease            = @LicNewRelease;
      set @tmpSaNewAantalGebruikers   = @LicNewAantalGebruikers;
      set @tmpSaNewAangemaaktOp       = @LicNewAangemaaktOp;
      set @tmpSaNewAangemaaktDoor     = @LicNewAangemaaktDoor;
    else
      set @tmpSaNewRelease            = @HistNewRelease;
      set @tmpSaNewAantalGebruikers   = @HistNewAantalGebruikers;
      set @tmpSaNewAangemaaktOp       = @HistNewAangemaaktOp;
      set @tmpSaNewAangemaaktDoor     = @HistNewAangemaaktDoor;
    end if;

    //Bepaal oude gegevens. Dit is de laatste uit de historie van vóór @vandatum
    select  First PktrCode, LchkAantalGebruikers,   LchkAangemaaktOp, LchkAangemaaktDoor
    into   @tmpSaOldRelease, @tmpSaOldAantalGebruikers, @tmpSaOldAangemaaktOp, @tmpSaOldAangemaaktDoor
    From   tabLicentieChecksum left outer join tabPakketRelease on (pktrGid=LchkPktrGid)
    where  (LchkLicGid=@tmpSaLicGid)
      and  (LchkAangemaaktOp <@vandatum)
    order by LchkAangemaaktOp desc;

    //Bepaal belangrijke selecties bij debiteur
    set @tmpSaDebSelecties='';
    if exists (select(1) from tabSlcPerNaw where (spnNawFilGid=@tmpSaLicNawFilGid) and (SpnSlcGid=@SlcGidExQueen)) then
      set @tmpSaDebSelecties=@tmpSaDebSelecties+'Ex Queen';
    end if;
    if exists (select(1) from tabSlcPerNaw where (spnNawFilGid=@tmpSaLicNawFilGid) and (SpnSlcGid=@SlcGidTijdelijkeUpdate)) then
      if @tmpSaDebSelecties <> '' then
        set @tmpSaDebSelecties=@tmpSaDebSelecties+' / ';
      end if;
      set @tmpSaDebSelecties=@tmpSaDebSelecties+_U('Tijdelijke update');
    end if;
    if exists (select(1) from tabSlcPerNaw where (spnNawFilGid=@tmpSaLicNawFilGid) and (SpnSlcGid=@SlcGidKingMobile)) then
      if @tmpSaDebSelecties <> '' then
        set @tmpSaDebSelecties=@tmpSaDebSelecties+' / ';
      end if;
      set @tmpSaDebSelecties=@tmpSaDebSelecties+'King Mobile';
    end if;


    // Wegschrijven nieuwste gegevens
    update tmpSybaseAfdracht
    set    tmpSaOldRelease           = @tmpSaOldRelease,
           tmpSaOldAantalGebruikers  = @tmpSaOldAantalGebruikers,
           tmpSaOldAangemaaktOp      = @tmpSaOldAangemaaktOp,
           tmpSaOldAangemaaktDoor    = @tmpSaOldAangemaaktDoor,
           tmpSaNewRelease           = @tmpSaNewRelease,
           tmpSaNewAantalGebruikers  = @tmpSaNewAantalGebruikers,
           tmpSaNewAangemaaktOp      = @tmpSaNewAangemaaktOp,
           tmpSaNewAangemaaktDoor    = @tmpSaNewAangemaaktDoor,
           tmpSaDebSelecties         = @tmpSaDebSelecties
    where (tmpSaPktsGid=@tmpSaPktsGid) and (tmpSaLicGid=@tmpSaLicGid);

  end loop;


  //-----------------------------------------------------
  //  Verwijder alle regels die neit versie '5%' zijn  //
  //-----------------------------------------------------
  set @@ErrorTextProcedure = 'SybaseAfdracht : Verwijder regels van versie <> 5%';
  //call Trace(@@ErrorTextProcedure);

  Delete tmpSybaseAfdracht
  from tmpSybaseAfdracht
  where ((IsNull(tmpSaOldRelease,'') not Like '5%') and (IsNull(tmpSaNewRelease,'') not Like '5%'))
     or (     (IsNull(tmpSaNewRelease, '')         = IsNull(tmpSaOldRelease,''))
          and (IsNull(tmpSaNewAantalGebruikers, 0) = IsNull(tmpSaOldAantalGebruikers,''))
        ) ;

  //--------------------------
  //  Resultaat teruggeven  //
  //--------------------------
  Select count(1) into @aantalLics from tmpSybaseAfdracht;
  set @@ErrorTextProcedure = 'SybaseAfdracht > @VanDatum='+string(@VanDatum)+' @TotDatum='+string(@TotDatum)+')  Aantal records : '+String(@aantalLics);
  //call traceEind(@@ErrorTextProcedure);

  //Resultaat teruggeven
  set @StandaardTekst       = _U('Standaard');
  set @AccountantTekst      = _U('Accountant');
  set @EducatiefTekst       = _U('Educatief');
  set @DealerDemoTekst      = _U('Dealer demo');
  set @DealerGebruikTekst   = _U('Dealer (eigen gebruik)');
  set @VerplichteDealer     = _U('Verplichte dealerkit G-dealer');
  set @CursusTekst          = _U('Cursus');
  set @PromotieMetEvalTekst = _U('Promotie met evaluatiebeperkingen');
  set @PromotieZonEvalTekst = _U('Promotie zonder evaluatiebeperkingen');
  set @EvaluatieTekst       = _U('Evaluatie');

  select
    tmpSaNewAangemaaktOp,
    PktsCode,
    tmpSaLicNummer,
    tmpSaOldRelease,
    tmpSaNewRelease,
    tmpSaOldAantalGebruikers,
    tmpSaNewAantalGebruikers,
    case tmpSaLicSoort
      when 0 then @StandaardTekst
      when 1 then @AccountantTekst
      when 2 then @EducatiefTekst
      when 3 then @DealerDemoTekst
      when 4 then @DealerGebruikTekst
      when 5 then @VerplichteDealer
      when 6 then @CursusTekst
      when 7 then @PromotieMetEvalTekst
      when 8 then @PromotieZonEvalTekst
      when 9 then @EvaluatieTekst
      else ''
    end,
    tmpSaDebSelecties,
    String(
					(Select Max(LchkAantalGebruikers)
         				 from   tabLicentieChecksum
                				inner join tabPakketSoort on pktsGid=tmpSaPktsGid
                				inner join tabpakketversie on pktvGid=lchkpktvgid
                				inner join tabpakketRelease on pktrGid=lchkpktrgid
	       				 where LchkLicGid=tmpSaLicGid and pktrCode>='5.54')
          ) tmpSaNewAangemaaktDoor, /*Geeft nu max aantal gebruikers door vanaf 5.54 */
    tmpSaOldAangemaaktOp,
    String(
					(Select Max(LchkAantalGebruikers)
         				 from   tabLicentieChecksum
                				inner join tabPakketSoort on pktsGid=tmpSaPktsGid
                				inner join tabpakketversie on pktvGid=lchkpktvgid
                				inner join tabpakketRelease on pktrGid=lchkpktrgid
	       				 where LchkLicGid=tmpSaLicGid)
          ) tmpSaOldAangemaaktDoor /*Geeft nu max aantal gebruikers door*/
  from
    tmpSybaseAfdracht
    inner join tabPakketSoort on tmpSaPktsGid = PktsGid
  order by tmpSaNewAangemaaktOp, tmpSaPktsGid, tmpSaLicNummer;


end;
