create or replace procedure Trace(in @Melding nchar(500))
begin
  declare @TijdVerschil nchar(250);
  declare @PC           nchar(40);
  declare @Connectie    nchar(40);
  declare @DBNaam       nchar(40);
  declare @PreMelding   nchar(100);

  if @@TraceTime is not null then
    set @TijdVerschil = 'Tijd='+string(datediff(ss, @@TraceTime, now()))+'.'+right('000'+string(datediff(ms, @@TraceTime, now())),3)+'sec,';
  end if;
  set @@TraceTime = now();

  //Vve uitgebreide trace
  if @@MachineName = '' then
    set @PC = '';
  else
    set @PC = 'PC='+@@MachineName+',';
  end if;

  set @Connectie = 'CID='+string(@@Spid)+',';

  set @DBNaam = 'DB='+ db_property('Name')+',';

  if left(@Melding, 6) = 'Einde ' then
    set @@Inspring = @@Inspring - 3;
    if @@Inspring < 0 then
      set @@Inspring = 0;
    end if;
  end if;

  set @PreMelding = @PC + @Connectie + @DBNaam + @TijdVerschil;

  message @PreMelding + repeat(' ', @@Inspring + ((length(@PreMelding)+9)/10)*10 - length(@PreMelding)) + @Melding;

  if left(@Melding, 6) = 'Begin ' then
    set @@Inspring = @@Inspring + 3;
  end if;

end;


create or replace procedure TraceBegin(in @Melding nchar(500))
begin

call Trace('Begin '+@Melding);   //Let op : voor "call Trace" geen spaties zetten, ivm zoek en vervangen om Trace aan/uit te kunnen schakelen

end;


create or replace procedure TraceEind(in @Melding nchar(500))
begin

call Trace('Einde '+@Melding);   //Let op : voor "call Trace" geen spaties zetten, ivm zoek en vervangen om Trace aan/uit te kunnen schakelen

end;


//FUNCTIE TBV AANVRAAG UBF-UPDATE VIA WEBSITE! (maatwerk AJ)
//TG 20-04-2006: deze functie geeft het gidje van een King- of Queenlicentie terug; andere pakketsoorten geven een foutmelding!
create or replace function UBFWebBepaalLicGid(in @PakketNaam  nchar(20), // pakketnaam (King of Queen)
                                              in @Serienummer integer)  // serienummer licentie
returns integer
begin
  declare @LicGid      integer;
  declare @PktsGid     integer;
  declare @RecordCount integer;

  set @@ErrorTextProcedure = 'UBFWebBepaalLicGid > @PakketNaam='+@PakketNaam+', @Serienummer='+string(@Serienummer);
  //call TraceBegin(@@ErrorTextProcedure);

  set @Serienummer = IsNull(@Serienummer, -1);

  select PktsGid into @PktsGid from tabPakketSoort where PktsCode = @PakketNaam;

  //controleren of PakketsoortGid bepaald kon worden en of dit het gid is van pakketsoort King of Queen (is er een ander gid gevonden, dan klopt de pakketnaam niet!)
  if @PktsGid is null or not @PktsGid in (select PktsGid from tabPakketSoort where PktsCode = 'King' or PktsCode = 'Queen') then
    call Raise(20282);
  end if;

  //serienummer moet ingevuld zijn en geldig zijn.
  select count(*) into @RecordCount from tabLicentie where LicNummer = @Serienummer and LicPktsGid = @PktsGid;

  //0 of meer dan 1 licentie gevonden; dat mag niet!
  if @RecordCount <> 1 then
    call Raise(20283);
  else
    //1 licentierecord gevonden; gidje vaststellen
    select LicGid into @LicGid from tabLicentie where LicNummer = @Serienummer and LicPktsGid = @PktsGid;

    //gid toch niet vast kunnen stellen; licentie dus niet bepaald!
    if @LicGid is null then
      call Raise(20283);
    end if;
  end if;

  set @@ErrorTextProcedure = 'UBFWebBepaalLicGid > @LicGid='+string(@LicGid);
  //call TraceEind(@@ErrorTextProcedure);

  return(@LicGid);

end;

alter procedure UBFWebBepaalLicGid set hidden;


//FUNCTIE TBV AANVRAAG UBF-UPDATE VIA WEBSITE! (maatwerk AJ)
//TG 20-04-2006: deze procedure update de UBF-ontvangststatus van een licentie
create or replace procedure UBFWebOntvangstVerwerken(in @PakketNaam       nchar(20), // pakketnaam (King of Queen)
                                          in @Serienummer      integer , // serienummer licentie
                                          in @DatumBinnenkomst date)
begin
  declare @LicGid      integer;
  declare @LockResult  integer;

  set @@ErrorTextProcedure = 'UBFWebOntvangstVerwerken > @PakketNaam='+@PakketNaam+', @Serienummer='+string(@Serienummer)+', @DatumBinnenkomst='+string(@DatumBinnenkomst);
  //call TraceBegin(@@ErrorTextProcedure);

  //licentiegid bepalen; licentie geeft 1 gid terug, anders klapt de proc eruit!
  select UBFWebBepaalLicGid(@PakketNaam, @Serienummer) into @LicGid;

  call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabLicentie', string(@LicGid), @LockResult);
  //locken is mislukt indien <> 0
  if @LockResult <> 0 then
    call Raise(20284);
  end if;

  //alles ok, dus update uitvoeren!
  update tabLicentie
  set    LicUbfStatus     = 8, //8 = In access (metavalue)
         LicUbfRetourOp   = @DatumBinnenkomst,
         LicGewijzigdDoor = @@GebruikerCode,
         LicGewijzigdOp   = Now()
  where  LicGid = @LicGid;

  //lock vrijgeven
  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabLicentie', string(@LicGid));

  set @@ErrorTextProcedure = 'UBFWebOntvangstVerwerken > @LicGid='+string(@LicGid);
  //call TraceEind(@@ErrorTextProcedure);

end;

alter procedure UBFWebOntvangstVerwerken set hidden;


//FUNCTIE TBV AANVRAAG UBF-UPDATE VIA WEBSITE! (maatwerk AJ)
//TG 20-04-2006: deze procedure update de UBF-uitleverstatus van een licentie
create or replace procedure UBFWebUitleverenVerwerken(in @PakketNaam         nchar(20), // pakketnaam (King of Queen)
                                                      in @Serienummer        integer,  // serienummer licentie
                                                      in @StatusUBFDatum     date,     // datum waarop gebruiker de UBF uitgeleverd heeft
                                                      in @StatusUBFInitialen nchar(10)) // initialen van gebruiker die UBF uitgeleverd heeft
begin
  declare @LicGid      integer;
  declare @LockResult  integer;

  set @@ErrorTextProcedure = 'UBFWebUitleverenVerwerken > @PakketNaam='+@PakketNaam+', @Serienummer='+string(@Serienummer)+', @DatumBinnenkomst='+string(@StatusUBFDatum)+', @StatusUBFInitialen='+@StatusUBFInitialen;
  //call TraceBegin(@@ErrorTextProcedure);

  //licentiegid bepalen; licentie geeft 1 gid terug, anders klapt de proc eruit!
  select UBFWebBepaalLicGid(@PakketNaam, @Serienummer) into @LicGid;

  call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabLicentie', string(@LicGid), @LockResult);
  //locken is mislukt indien <> 0
  if @LockResult <> 0 then
    call Raise(20284);
  end if;

  //alles ok, dus update uitvoeren!
  update tabLicentie
  set    LicUbfStatus       = 4, //4 = afgehandeld (metavalue)
         LicUitgeleverdOp   = @StatusUBFDatum,
         LicUitgeleverdDoor = @StatusUBFInitialen,
         LicGewijzigdDoor   = @@GebruikerCode,
         LicGewijzigdOp     = Now()
  where  LicGid = @LicGid;

  //lock vrijgeven
  call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabLicentie', string(@LicGid));

  set @@ErrorTextProcedure = 'UBFWebUitleverenVerwerken > @LicGid='+string(@LicGid);
  //call TraceEind(@@ErrorTextProcedure);

end;

alter procedure UBFWebUitleverenVerwerken set hidden;


