//$Workfile: UpdateDragDropProjBoom.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----------------------------------------------------------------------------------------------------
//------------------------------ UpdateDragDropProjBoom ----------------------------------------------
//----------------------------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='UpdateDragDropProjBoom') then
  drop procedure UpdateDragDropProjBoom;
end if;

create procedure UpdateDragDropProjBoom(
  in @SourceGid          integer, //Gid van de node die verplaats is
  in @SourceParent       integer, //parent van de node die verplaats is
  in @SourceNieuweParent integer, //nieuwe parent
  in @SourceOudVolgNr    integer, //oorspronkelijke volgnr van de node die verplaats is
  in @SourceNieuwVolgNr  integer, //nieuwe volgnr
  in @MoveIsBoomGid      smallint //uit welke tabel de verplaatste record is: 1=tabProjectboom record, 2=voorcalc record
)

begin
  //De gegevens in de database in overeenstemming brengen met wat er in projecten-tree is gebeurd
  //na een verschuiving binnen de boom (op eenzelfde scherm). Dit wordt voor iedere individuele node aangeroepen

  set @@ErrorTextProcedure = 'UpdateDragDropProjBoom > @SourceGid='+string(@SourceGid)+', @SourceParent='+string(@SourceParent)+', @SourceNieuweParent='+string(@SourceNieuweParent)+', @SourceOudVolgNr='+string(@SourceOudVolgNr)+', @SourceNieuwVolgNr='+string(@SourceNieuwVolgNr)+', @MoveIsBoomGid='+string(@MoveIsBoomGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if (@SourceParent <> @SourceNieuweParent) and (@SourceOudVolgNr <> @SourceNieuwVolgNr) then
  begin
    case @MoveIsBoomGid
      when 1 then  update tabProjectboom
                   set PbParentPbGid = @SourceNieuweParent,
                       PbVolgnr = @SourceNieuwVolgNr
                   where PbGid  = @SourceGid;

      when 2 then  update tabProjectVoorcalculatie
                   set PvcPbGid  = @SourceNieuweParent,
                       PvcVolgNr = @SourceNieuwVolgNr
                   where PvcGid  = @SourceGid;
    end case
  end
  //alleen parent is veranderd
  elseif @SourceParent <> @SourceNieuweParent then
  begin
    case @MoveIsBoomGid
      when 1 then update tabProjectboom
                  set PbParentPbGid = @SourceNieuweParent
                  where PbGid  = @SourceGid;
      when 2 then update tabProjectVoorcalculatie
                  set PvcPbGid = @SourceNieuweParent
                  where PvcGid = @SourceGid;
    end case
  end
    //alleen volgnummer is veranderd
  elseif @SourceOudVolgNr <> @SourceNieuwVolgNr then
  begin
    case @MoveIsBoomGid
      when 1 then update tabProjectBoom
                  set PbVolgnr = @SourceNieuwVolgNr
                  where PbGid  = @SourceGid;

      when 2 then update tabProjectVoorcalculatie
                  set PvcVolgNr = @SourceNieuwVolgNr
                  where PvcGid  = @SourceGid;
    end case
  end
  end if;                                         //end if niet aan elkaar, want is if statement, niet if expression

  set @@ErrorTextProcedure = 'UpdateDragDropProjBoom';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: UpdateGarantieSerieNummer.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='UpdateGarantieSerieNummer') then
  drop procedure UpdateGarantieSerieNummer;
end if;

create procedure UpdateGarantieSerieNummer(
  in @SerieGid   integer,    // Te wijzigen serienummer
  in @VanAfDatum date,       // Leverdatum oid. De garantie t/m datum wordt berekend obv. deze begindatum
  in @ForceUpdate smallint)  // 0 = updaten volgens instelling bij artikel EN als garantiedatum nog niet was ingevuld
                             // 1 = updaten volgens instelling bij artikel, ongeacht of het al was gevuld
                             // 2 = altijd updaten, ongeacht instelling bij artikel en ongeacht of het al was ingevuld
begin
  // Update de garantiebepalingen van het serienummer
  // Let op: het updaten van de garantiebepaling is altijd onafhankelijk van de instellingen bij het artikel! (Zie DO serienummers)
  declare @ErrText nchar(500);
  declare @MoetDatumUpdaten    smallint;
  declare @MoetBepalingUpdaten smallint;
  declare @TermijnAantal       integer;
  declare @TermijnEenheid      smallint;
  declare @Bepaling            long nvarchar;

  set @ErrText = 'UpdateGarantieSerieNummer(@SerieGid='+string(@SerieGid)+')';
  set @@ErrorTextProcedure = @ErrText;
   //call TraceBegin(@@ErrorTextProcedure);

  set @MoetDatumUpdaten    = 0;
  set @MoetBepalingUpdaten = 0;

  select if (@ForceUpdate = 0 and ArtGarantieVullenBijLeveren <> 0 and ArtSerieGarantieTmDatum is null) or
            (@ForceUpdate = 1 and ArtGarantieVullenBijLeveren <> 0) or
            (@ForceUpdate = 2) then
            1
          else
            0
          endif,
          if (@ForceUpdate in (0,1) and ArtGarantieVullenBijLeveren <> 0) or
             (@ForceUpdate = 1 and ArtGarantieVullenBijLeveren <> 0) or
             (@ForceUpdate = 2) then
            1
          else
            0
          endif,
          GcTermijnAantal,
          GcTermijnEenheid,
          GcOpmerking
  into @MoetDatumUpdaten, @MoetBepalingUpdaten, @TermijnAantal, @TermijnEenheid, @Bepaling
  from  tabArtikelSerienummer
        inner join tabArtikel on ArtGid = ArtSerieArtGid
        left outer join tabGarantieCode on (GcGid = ArtGcGid)
  where ArtSerieGid = @SerieGid;


  set @@ErrorTextProcedure = @ErrText + ' > @MoetDatumUpdaten='+string(@MoetDatumUpdaten)+', @MoetBepalingUpdaten='+string(@MoetBepalingUpdaten)+', @TermijnAantal='+string(@TermijnAantal)+', @TermijnEenheid='+string(@TermijnEenheid);
   //call Trace(@@ErrorTextProcedure);

  if @MoetDatumUpdaten <> 0 or @MoetBepalingUpdaten <> 0 then
    set @@ErrorTextProcedure = @@ErrorTextProcedure + ' > Update serienummer!';
     //call Trace(@@ErrorTextProcedure);

    update tabArtikelSerienummer
    set    ArtSerieGarantieTmDatum        = if @MoetDatumUpdaten <> 0 then
                                              case @TermijnEenheid
                                              when 0 then // Dagen
                                                dateadd(day,   @TermijnAantal, @VanAfDatum)
                                              when 1 then // maand(en)
                                                dateadd(month, @TermijnAantal, @VanAfDatum)
                                              when 2 then // jaar
                                                dateadd(year,  @TermijnAantal, @VanAfDatum)
                                              when null then // Geen garantiebepaling -> leegmaken!
                                                null
                                              end
                                            else
                                              ArtSerieGarantieTmDatum
                                            endif,
           ArtSerieGarantieTermijnEenheid = if @MoetDatumUpdaten <> 0 then
                                              @TermijnEenheid
                                            else
                                              ArtSerieGarantieTermijnEenheid
                                            endif,
           ArtSerieGarantieTermijnAantal  = if @MoetDatumUpdaten <> 0 then
                                              @TermijnAantal
                                            else
                                              ArtSerieGarantieTermijnAantal
                                            endif,
           ArtSerieGarantieBepalingen     = if @MoetBepalingUpdaten <> 0 then
                                              @Bepaling
                                            else
                                              ArtSerieGarantieBepalingen
                                            endif
    from   tabArtikelSerienummer
    where  ArtSerieGid = @SerieGid;
  end if;

  set @@ErrorTextProcedure = 'CreateSerieNummer(@SerieGid='+string(@SerieGid)+')';
   //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure UpdateOfferteRegelsBtwCodeAfstandsVerkopen(in @OffGid integer default null, in @OfkGid integer default null, in @AfleverLndGid integer default null)
begin
  declare @DefaultMagazijn integer;
  declare @KortingsTarief  integer;
  declare @InruilTarief    integer;
  declare @NewBtwCode      integer;
  declare @NewBtwPerc      numeric(15,3);
  declare @PrijzenHerberekenen smallint;

  select IsNull( (select ToeMagMagGid from tabToegestaneMagazijnen inner join tabGebruiker on (GebruikerGid = ToeMagGebrGid) where NaamGebruiker = @@GebruikerCode and ToeMagToepassing = 10),
                 (select MagGid from tabMagazijn where MagCode='001') ) into @DefaultMagazijn;

  select OfvgArtGidKortingsTarief, OfvgArtGidInruilTarief, OfvgIsAfstandsVerkHerberekenenInclBtwPrijs into @KortingsTarief, @InruilTarief, @PrijzenHerberekenen  from tabOfferteVasteGegevens;

  for @Cursor as Cursor_OfferteVersies cursor for
    select  OfkGid                        @CurOfkGid,
            OfkBtwStand                   @OfkBtwStand,
            IsNull((if OfkIsInkoopCombinatie = 1 then OfkNawGidInkCombiFactuur else null endif), OffNawGidDebiteur, OffNawGidRelatie) @NawGid,
            OfkVerzendAdres               @OfkVerzendAdres,
            OfkAdrGidVerzendAdres         @OfkAdrGidVerzendAdres,
            OffNaw.NawGidCorrespondentie  @OffNawGidCorrespondentie,
            OffNaw.NawGidVestiging        @OffNawGidVestiging,
            FactNaw.NawGidCorrespondentie @FactNawGidCorrespondentie,
            FactNaw.NawGidVestiging       @FactNawGidVestiging
    from tabOfferteKop
      inner join tabOfferte on OfkOffGid = OffGid
      inner join tabNaw OffNaw on OffNaw.NawGid = IsNull(OffNawGidDebiteur, OffNawGidRelatie)
      left outer join tabNaw FactNaw on FactNaw.NawGid = OfkNawGidInkCombiFactuur
    where  (@OffGid is not null and OffGid = @OffGid and OfkStatus = 0) // alle concept versies binnen offerte
        or (@OfkGid is not null and OfkGid = @OfkGid)                   // of 1 specifieke versie
    order by OfkGid
  for update
    do
      // Alleen verder als er uberhaupt een NAW is
      if @NawGid is not null then

        // Als we alle versies bijwerken dan het afleverlandgid voor deze versie bepalen, voor een enkele versie wordt ie al meegegeven
        if (@OffGid is not null and @OfkGid is null) or (@AfleverLndGid is null) then
          select AdrLndGid into @AfleverLndGid from tabAdres where AdrGid =  (case @OfkVerzendAdres
                                                                                when 0 then @OffNawGidCorrespondentie
                                                                                when 1 then @OffNawGidVestiging
                                                                                when 2 then @OfkAdrGidVerzendAdres
                                                                                when 3 then @FactNawGidCorrespondentie
                                                                                when 4 then @FactNawGidVestiging
                                                                                when 5 then @OfkAdrGidVerzendAdres
                                                                              end case);
        end if;

        for @Cursor as Cursor_Offerteregels cursor for
            select  OfrGid                        @OfrGid,
                    OfrRegelSoort                 @OfrRegelSoort,
                    case OfrRegelSoort
                      when 1 then OfrArtGidTarief
                      when 2 then OfrArtGidArtikel
                      when 3 then @KortingsTarief
                      when 4 then @InruilTarief
                      else null
                    end case                      @ArtGid,
                    OfrArtPartijGid               @ArtPartijGid,
                    OfrBtwCode                    @OldBtwCode,
                    BtwPercentage                 @OldBtwPerc,
                    OfrPrijs                      @OfrPrijs,
                    OfrRegelkorting1Bedrag        @OfrRegelkorting1Bedrag,
                    (select AdrLndGid from tabMagazijn inner join tabAdres on MagAdrGid = AdrGid where MagGid = IsNull((if OfrRegelSoort = 2 then (select ArtDefaultMagGid from tabArtikel where ArtGid = OfrArtGidArtikel) else null endif), @DefaultMagazijn)) @VerzendLndGid
            from tabOfferteRegel inner join tabOfferteKop on OfkGid = OfrOfkGid inner join tabBtw on OfrBtwCode = BtwCode
            where OfrOfkGid = @CurOfkGid and OfrRegelSoort in (1,2,3,4)
            order by OfrGid
          for update
          do
            set @NewBtwCode = GeefBtwCodeVerkoop(@NawGid, @ArtGid, @ArtPartijGid, @AfleverLndGid, @VerzendLndGid);

            if @NewBtwCode <> @OldBtwCode then
              select BtwPercentage into @NewBtwPerc from tabBtw where BtwCode = @NewBtwCode;

              if @OfkBtwStand = 0 or @PrijzenHerberekenen = 0 then
                update tabOfferteRegel set OfrBtwCode = @NewBtwCode where OfrGid = @OfrGid;
              else
                update tabOfferteRegel set
                  OfrBtwCode = @NewBtwCode,
                  OfrPrijs = round( round(((OfrPrijs / (100+@OldBtwPerc )) * 100), OfrAantalDecimalenVoorPrijzen)  * (100+@NewBtwPerc ) / 100, OfrAantalDecimalenVoorPrijzen),
                  OfrRegelkorting1Bedrag = round(round((OfrRegelkorting1Bedrag / (100+@OldBtwPerc )) * 100, OfrAantalDecimalenVoorPrijzen) * (100+@NewBtwPerc ) / 100, OfrAantalDecimalenVoorPrijzen)
                where OfrGid = @OfrGid;
              end if;
            end if;
          end for;
      end if; // naw is not null
    end for;
end;


create or replace procedure UpdateOrderRegelsBtwCodeAfstandsVerkopen(in @OrkGid integer, in @AfleverLndGid integer, in @OrkMagGid integer default null, in @AlleenTarieven smallint default 0)
begin
  declare @NawGid     integer;
  declare @OrkInclBtw integer;
  declare @NewBtwCode integer;
  declare @NewBtwPerc numeric(15,3);
  declare @PrijzenHerberekenen smallint;

  select VofIsAfstandsVerkHerberekenenInclBtwPrijs into @PrijzenHerberekenen from tabVasteGegevensOrdersFactureren;

  select IsNull(OrkFactuurNawGid, OrkNawGid), OrkInclBtw into @NawGid, @OrkInclBtw from tabOrderKop where OrkGid = @OrkGid;

  for @Cursor AS Cursor_Orderregels cursor for
      select  OrrGid                  @OrrGid,
              OrrRegelSoort           @OrrRegelSoort,
              OrrArtGid               @ArtGid,
              OrrArtPartijGid         @ArtPartijGid,
              OrrBtwCode              @OldBtwCode,
              BtwPercentage           @OldBtwPerc,
              OrrBrutoVerkoopPrijs    @OrrBrutoVerkoopPrijs,
              OrrIsKortingsPercentage @OrrIsKortingsPercentage,
              OrrRegelkorting1        @OrrRegelkorting1,
              (if OrrRegelSoort = 2 then // artikel
                if OrrDirecteInkoop = 0 or OrrDirecteLevering = 0 or not IsArtLevDefaultDirecteLevering(OrrNawGidDirecteInkoop, OrrArtGid, OrrDirInkInkoopEenheid) = 1 then
                  (select AdrLndGid from tabMagazijn inner join tabAdres on MagAdrGid = AdrGid where MagGid = IsNull(OrrMagGid, @OrkMagGid, OrkDefaultMagGid))
                else
                 (select IsNull(BestelAdres.AdrLndGid,  CorrVestAdres.AdrLndGid) LevVerzAdresLndGid from tabNaw
                  left outer join tabLeverancierGegevens on LevGegNawGid = NawGid
                  left outer join tabAdres BestelAdres on LevGegAdrGidBestelAdres = BestelAdres.AdrGid
                  left outer join tabAdres CorrVestAdres on CorrVestAdres.AdrGid = (case IsNull(LevGegBestelAdres, 1) when 0 then NawGidCorrespondentie when 1 then NawGidVestiging end)
                  where (OrrNawGidDirecteInkoop is not null and NawGid = OrrNawGidDirecteInkoop)
                         or
                        (OrrNawGidDirecteInkoop is null) and (NawGid = (select ArtLevNawGid from tabArtikelLeverancier where ArtLevArtGid = OrrArtGid and ArtLevIsDefault = 1 )) )

                endif
              else // tarief
                (select AdrLndGid from tabMagazijn inner join tabAdres on MagAdrGid = AdrGid inner join tabOrderKop on OrkGid = OrrOrkGid where MagGid = IsNull(@OrkMagGid, OrkDefaultMagGid))
              endif
             )                       @VerzendLndGid
      from tabOrderRegel inner join tabBtw on OrrBtwCode = BtwCode inner join tabOrderKop on OrrOrkGid = OrkGid
      where OrrOrkGid = @OrkGid
        and ((@AlleenTarieven = 0 and OrrRegelSoort in (1,2)) or (@AlleenTarieven = 1 and OrrRegelSoort = 1))
      order by OrrGid
    for update
    do
      set @NewBtwCode = GeefBtwCodeVerkoop(@NawGid, @ArtGid, @ArtPartijGid, @AfleverLndGid, @VerzendLndGid);

      if @NewBtwCode <> @OldBtwCode then
        select BtwPercentage into @NewBtwPerc from tabBtw where BtwCode = @NewBtwCode;

        if @OrkInclBtw = 0 or @PrijzenHerberekenen = 0 then
          update tabOrderRegel set OrrBtwCode = @NewBtwCode where OrrGid = @OrrGid;
        else
          update tabOrderRegel set
            OrrBtwCode = @NewBtwCode,
            OrrBrutoVerkoopPrijs = round( round(((OrrBrutoVerkoopPrijs / (100+@OldBtwPerc )) * 100), OrrAantDecBedrag)  * (100+@NewBtwPerc ) / 100, OrrAantDecBedrag),
            OrrRegelkorting1 = (if OrrIsKortingsPercentage = 1 then OrrRegelkorting1 else round(round((OrrRegelkorting1 / (100+@OldBtwPerc )) * 100, OrrAantDecBedrag) * (100+@NewBtwPerc ) / 100, OrrAantDecBedrag) endif)
          where OrrGid = @OrrGid;
        end if;
      end if;
    end for;

  call OrderBerekenExtraRegelBedragen(@OrkGid);
  call OrderVulBtwTotalen(@OrkGid);
end;


