if exists (select 1 from sys.sysProcedure where proc_name='UpdatePrijsWijziging') then
  drop procedure UpdatePrijsWijziging;
end if;

create procedure UpdatePrijsWijziging(in @PwrPwkId integer,                    in @PwrArtGid integer,
                                      in @PwrPrijsPer numeric(15,3),           in @PwrKostprijs numeric(15,3),
                                      in @PwrIsVerkoopprijsIncl numeric(15,3), in @PwrVerkoopprijs numeric(15,3))
begin
  //call TraceBegin( 'UpdatePrijsWijziging(@PwrPwkId='+string(@PwrPwkId)+', @PwrArtGid='+string(@PwrArtGid)+')');
  if exists(select 1 from tabPrijswijzigingsRegel where (PwrPwkId = @PwrPwkId) and (PwrArtGid = @PwrArtGid) ) then
    //call Trace('Update prijswijziging');
    update  tabPrijswijzigingsRegel
    set     PwrPrijsPer = @PwrPrijsPer,
            PwrKostprijs = @PwrKostprijs,
            PwrIsVerkoopprijsIncl = @PwrIsVerkoopprijsIncl,
            PwrVerkoopprijs = @PwrVerkoopprijs
    where  (PwrPwkId = @PwrPwkId) and (PwrArtGid = @PwrArtGid);
  else
    //call Trace('Insert prijswijziging');
    insert into tabPrijswijzigingsRegel ( PwrPwkId,  PwrArtGid,  PwrPrijsPer,  PwrKostprijs,  PwrIsVerkoopprijsIncl,  PwrVerkoopprijs)
                                 values (@PwrPwkId, @PwrArtGid, @PwrPrijsPer, @PwrKostprijs, @PwrIsVerkoopprijsIncl, @PwrVerkoopprijs);
  end if;

  //call TraceEind( 'UpdatePrijsWijziging');

end;


// *** Splitsen van de SelectieCodes velden in tabProjectBoekingsregel en tabProjectVoorcalculatie
create or replace function UpdateProjectSelectieCodes(in @SelectieCodes long nvarchar, in @Gid integer, in @PbGid integer, in @TableType smallint)
returns long nvarchar
// @TableType: 0 = tabProjectBoekingsRegel; 1=tabProjectVoorcalculatieRegel; 2=tabProjectWerkbonRegel
begin
  declare @PbrGid    integer; //mutatieregel
  declare @PvcGid    integer; //voorcalculatie
  declare @PwbrGid   integer; //werkbon
  declare @Idx       integer;
  declare @LstIdx    integer;
  declare @SelCode   nchar(40);
  declare @Resultaat long nvarchar;

  set @@ErrorTextProcedure = 'UpdateProjectSelectieCodes > @SelectieCodes='+ @SelectieCodes + ' @Gid=' + String(@Gid) + ' @PbGid=' + String (@PbGid) + ' @TableType=' + String (@TableType);
  //call TraceBegin(@@ErrorTextProcedure);

  //velden initialiseren
  set @PbrGid  = null;
  set @PvcGid  = null;
  set @PwbrGid = null;

  // verwijder eerst alle selectiecodes van de betreffende regel...
  case @TableType
    when 0 then
      set @PbrGid = @Gid;
      delete from tabProjectSelectieCode where PscPbrGid  = @PbrGid;
    when 1 then
      set @PvcGid = @Gid;
      delete from tabProjectSelectieCode where PscPvcGid  = @PvcGid;
    when 2 then
      set @PwbrGid = @Gid;
      delete from tabProjectSelectieCode where PscPwbrGid = @PwbrGid;
  end case;

  //...om ze daarna opnieuw toe te voegen
  set @Idx    = 1;
  set @LstIdx = 1;

  set @SelectieCodes = @SelectieCodes + ';';
  while @Idx <= Length(@SelectieCodes) loop
    // parse tot het scheidingsteken ';'
    if SubStr(@SelectieCodes, @Idx, 1) = ';' then
      set @SelCode = Trim (SubStr(@SelectieCodes, @LstIdx, (@Idx - @LstIdx)));
      if @SelCode <> '' then
        insert into tabProjectSelectieCode (PscCode, PscPbrGid, PscPvcGid, PscPwbrGid, PscPbGid) values (@SelCode, @PbrGid, @PvcGid, @PwbrGid, @PbGid);
      end if;
      set @LstIdx = @Idx + 1;
    end if;
    set @Idx = @Idx + 1;
  end loop;

  // nu teruglezen in alfabetische volgorde met spatie tussen ';' en code
  /*
  set @Resultaat = '';
  for @Teruglezen AS CURSOR_SelectieCodes cursor for
    select distinct
      PscCode @CurPscCode
    from tabProjectSelectieCode
    where
      IsNull(PscPbrGid, 0)=IsNull(@PbrGid,  0) and
      IsNull(PscPvcGid, 0)=IsNull(@PvcGid,  0) and
      IsNull(PscPwbrGid,0)=IsNull(@PwbrGid, 0)
    order by PscCode
  for read only do
    if @Resultaat = '' then
      set @Resultaat = @CurPscCode;
    else
      set @Resultaat = @Resultaat + '; ' + @CurPscCode;
    end if;
  end for;
  */

  select
    list (distinct PscCode, '; ') into @Resultaat
  from tabProjectSelectieCode
  where
    IsNull(PscPbrGid ,0)=IsNull(@PbrGid,  0) and
    IsNull(PscPvcGid ,0)=IsNull(@PvcGid,  0) and
    IsNull(PscPwbrGid,0)=IsNull(@PwbrGid, 0);

  return @Resultaat;

  set @@ErrorTextProcedure = 'UpdateProjectSelectieCodes > @SelectieCodes='+ @SelectieCodes + ' @Gid=' + String(@Gid) + ' @PbGid=' + String (@PbGid) + ' @TableType=' + String (@TableType);
  //call TraceEind(@@ErrorTextProcedure);
end;


