//$Workfile: UpdateTmpAsciiJournaal.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----- Controleer van te voren of het ingelezen ASCII (journaal)-bestand goed is
if exists (select 1 from sys.sysProcedure where proc_name='UpdateTmpAsciiJournaal') then
  drop procedure UpdateTmpAsciiJournaal;
end if;

create procedure UpdateTmpAsciiJournaal(in @LayoutSoort smallint)
begin
  set @@ErrorTextProcedure = 'UpdateTmpAsciiJournaal > @LayoutSoort='+String(@LayoutSoort);
  //call TraceBegin(@@ErrorTextProcedure);

  //call Trace('Bepaal BoekjaarGid');
  update tmpAsciiJournaal set tmpAjBoekBjgid = BjGid
  from   tabboekjaar where tmpAjBoekDatum between BjBegindatum and BjEinddatum;

  //call Trace('Bepaal periode');
  update tmpAsciiJournaal set tmpAjPeriode = PerNr
  from   tabPeriode where tmpAjBoekDatum between Begindatum and Einddatum;

  //call Trace('Bepaal DgbGid');
  update tmpAsciiJournaal set tmpAjDGBgid = DgbGid
  from   tabDagboek where tmpAjDagBoekCode = DgbCode;

  //call Trace('Zet Huidig bjgid als dagboeksoort begin');
  update tmpAsciiJournaal set tmpAjBoekBjgid = @@BJGid
  from   tmpasciijournaal, tabdagboek
  where  tmpAjDGBgid = DgbGid and dagboeksoort = 5;

  //call Trace('Bepaal RksGid');
  if @LayoutSoort = 0 then //King 4 layout haalt valuta bij rekening vandaan
    update tmpAsciiJournaal set tmpAjRksGid = RksGid, tmpAjValCode = ValCode, tmpAjValNummer = RksValNummer, tmpAjDefaultSoort = DefaultSoort
    from   tabRekeningschema, tabvaluta where tmpAjRekeningNrtext = RksInvoer and RksValnummer = ValNummer;
  else  //King 5 layout:
    update tmpAsciiJournaal set tmpAjRksGid = RksGid, tmpAjDefaultSoort = DefaultSoort
    from   tabRekeningschema where tmpAjRekeningNrtext = RksInvoer;
    //Zoek ValNummer bij ValCode
     //call Trace('Zoek valnummer bij valcode voor hoofdrekening');
    update tmpAsciiJournaal set tmpAjValNummer = ValNummer
    from   tabValuta where tmpAjValCode = ValCode;
     //call Trace('Zoek valnummer bij valcode voor hulprekening');
    update tmpAsciiJournaal set tmpAjHulpRekValNummer = ValNummer
    from   tabValuta where tmpAjHulpRekValCode = ValCode;
  end if;

   //call Trace('Bereken BasisBedrag');
  update tmpAsciiJournaal set tmpAjBasisBedrag = ValutaOmrekenen(ValNummer, tmpAJValutaBedrag, @@BasisValutaNummer, tmpAJBoekBjGid, tmpAjPeriode, 2)
  from   tmpAsciiJournaal, tabvaluta
  where  tmpAjValCode = ValCode and tmpAjBoekBjGid is not null and tmpAjPeriode is not null;

   //call Trace('Bepaal RksGid voor hulprekening');
  if @LayoutSoort = 0 then //King4 layout;
    update tmpAsciiJournaal set tmpajHulpRekRksGID = RksGid, tmpajHulpRekValCode = ValCode,
                                tmpAJHulpRekDefaultS = DefaultSoort, tmpAJHulpRekIsCredit = 0
    from   tabRekeningschema, tabvaluta
    where  tmpAjHulpRekeningNrtext = RksInvoer and RksValnummer = ValNummer;
  else                      //bij King 5 layout is valuta al gevuld evenals HulpRekIsCredit;
    update tmpAsciiJournaal set tmpajHulpRekRksGID = RksGid, tmpAJHulpRekDefaultS = DefaultSoort
    from   tabRekeningschema
    where  tmpAjHulpRekeningNrtext = RksInvoer;
  end if;

// Minteken en boekzijde van hulprekening zit nu helemaal in het programma.
//   //call Trace('Bepaal IsCredit voor hulprekening');
//  if @LayoutSoort = 0 then //King4 layout;
//    update tmpAsciiJournaal set tmpAJHulpRekIsCredit = 1,tmpAjHulpRekBasisBedrag = -tmpAjHulpRekBasisBedrag, tmpAJHulpRekValutaBedrag = -tmpAJHulpRekValutaBedrag
//    where                       (tmpAJHulpRekValutaBedrag < 0) and tmpAJHulpRekDefaults in (0,2,3,5);
//  end if;

   //call Trace('Bereken basisbedrag voor hulprekening');
  update tmpAsciiJournaal set tmpAjHulpRekBasisBedrag = ValutaOmrekenen(ValNummer, tmpAJHulpRekValutaBedrag, @@BasisValutaNummer, tmpAjBoekBjGID, tmpAjPeriode, 2)
  from   tmpAsciiJournaal, tabvaluta
  where  tmpAjHulpRekValCode = ValCode and tmpAjBoekBjGid is not null and tmpAjPeriode is not null and tmpAjHulpRekRksGid is not null and tmpAjHulpRekValutaBedrag is not null;

   //call Trace('Bepaal BTW-code voor hulprekening');
  update tmpAsciiJournaal set tmpAjHulpRekBtwCode = BtwCode, tmpAjHulpRekSoort = 1
  from   tabBtw where tmpAjHulpRekRksGid is not null and tmpAjHulpRekRksGid = BtwRksGid;

   //call Trace('Zet factuurdatum');
  update tmpAsciiJournaal set tmpAjFactuurDatum = TmpAjBoekDatum
  from   tmpAsciiJournaal
  where  tmpAjDefaultSoort in (6,7) and
         tmpAjFactuurDatum is null; // King 5 layoutjes hebben wel al een factuurdatum iit King 4 layouts


   //call Trace('Bepaal vervaldatum');
  update tmpAsciiJournaal set tmpAjVervalDatum = funcVervalDatumFactuurMetRksGid(TmpAjFactuurDatum, tmpAjRksGid)
  from   tmpAsciiJournaal
  where  tmpAjVervalDatum is null and tmpAjDefaultSoort in (6,7);

   //call Trace('Zet Boekgangnummer op 0 indien null');
  update tmpAsciiJournaal set tmpAJBoekgangnummer = 0
  where  tmpAJBoekgangnummer is null;

  set @@ErrorTextProcedure = 'UpdateTmpAsciiJournaal';
  //call TraceEind(@@ErrorTextProcedure);

end;


//@Previewmode    :  0-false, 1-true
//@IelNummer      :  Gebruikte importlayout
//@ilogGid        :  LogGid waarin we mogen loggen
create or replace procedure UpdateTmpNawImport(in @PreviewMode smallint, in @IelNummer integer, in @ilogGid integer, out @TotaalVerwijderd integer)
begin
  declare @IelVeldnaam                           nchar(40);      //nodig voor Update-loop
  declare @IelVorigeVeldnaam                     nchar(40);      //nodig voor Update-loop
  declare @IelVeldDefaultWaarde                  smallint;      //nodig voor Update-loop
  declare @SjabloonNawGidVestiging               integer;       //nodig voor Update-loop bij adressen
  declare @SjabloonNawGidCorrespondentie         integer;       //nodig voor Update-loop bij adressen

  declare @Statement                             nchar(500);     //om statement op te bouwen
  declare @ExtraWhereClause                      nchar(150);

  declare @IelFonGid                             integer;       //gegevens vd importlayout
  declare @IelNawGid                             integer;
  declare @IelVeldDefaultWaardeOveralDoorvoeren  smallint;
  declare @IelVerwijderCode                      nchar(20);
  declare @IelVerwijdercodePositie               integer;

  declare @NawFilGid                             integer;        //nodig voor NawDelete
  declare @NawFilNummer                          nchar(10);      //nodig voor verwijderloop
  declare @VorigNawFilNummer                     nchar(10);      //nodig voor verwijderloop
  declare @NiRegelNummer                         integer;        //nodig bij loggen

  declare @NAW_in_gebruik1  exception for SQLSTATE '23W05';        //'primary key referenced in another tabel'
  declare @NAW_in_gebruik2  exception for SQLSTATE '23503';        //'No primary key value for blablabla' (tabRekeningsaldo werkt niet mee)
  declare @NAW_in_gebruik3  exception for SQLSTATE 'WW012';        //'De voorraadmutatieregels kunnen niet worden gewijzigd!'

  declare @NummerVerwijderdTekst long nvarchar;
  declare @NummerInGebruikTekst  long nvarchar;

  set @NummerVerwijderdTekst = _A('Nummer %1! is verwijderd');
  set @NummerInGebruikTekst  = _A('Nummer %1! is in gebruik');

  //call Tracebegin('UpdateTmpNawImport : @PreviewMode = '+ String(@PreviewMode));
  set @TotaalVerwijderd = 0;

  //call Trace('Importlayout variabelen vullen');
  select first IelFonGid,  IelNawGid,  IelVerwijderCode, IelVerwijdercodePositie
   into  @IelFonGid, @IelNawGid, @IelVerwijderCode, @IelVerwijdercodePositie
   from  tabImportExportLayout
   where (IelNummer = @IelNummer) and (IelSoort = 1);


  //Vve 8-1-2008: Ivm meta-aanpassing zijn NiVerwijderenCode en IelVerwijderenCode nu allebei '' als je er niks mee gedaan hebt. Daardoor
  //              werden ineens alle debiteuren verwijderd bij een defaultlayout.
  //              Iom RB/EL/GvK nu zo gebouwd dat hij alleen verwijdert als het veldnummer > 0 is. Veld 0 bestaat namelijk niet; voor de eindgebruiker
  //              begint een csv bestand bij 1.
  //              Let op: het was al niet mogelijk om op basis van een leeg veld debiteuren te verwijderen. Deze test zit ook in het programma.
  //              Daarom hier ook overgenomen.
  if (@PreviewMode = 0) and (@IelVerwijdercodePositie > 0) and (@IelVerwijderCode <> '') then
    //Begin een loop om alle Naws te verwijderen
    //call Trace('Naws verwijderen');

    set @VorigNawFilNummer = '';
    loopVerwijderen :
    loop
      set @NawFilNummer = '';
      //Zoek nu de volgende NawNummer waarbij de verwijdercode in het aangegeven veld staat:
      select first NiNawFilNummer, NiRegelNummer into @NawFilNummer, @NiRegelNummer from tmpNawImport where (NiVerwijderenCode = @IelVerwijderCode) and (NiNawFilNummer is not null) and (NiNawFilNummer > @VorigNawFilNummer) order by NiNawFilNummer;

      if IsNull(@NawFilNummer, '') = '' then
        //call Trace('Breakie breakie...(loopVerwijderen)');
        leave loopVerwijderen;
      end if;
      //call Trace('Volgende @NawFilNummer gevonden: '+ @NawFilNummer);

      //Nu het nawgidje bij het nummer zoeken, zodat we die aan de proc NawDelete mee kunnen geven
      select NawFilGid into @NawFilGid from tabNawFile where (NawFilNummer = @NawFilNummer) and (NawFilFonGid = @IelFonGid);
      //call Trace('NawDelete aanroepen met Fongid = '+ String(@IelFonGid) + ' en NawFilGid = ' + String(@NawFilGid));
      begin
        call NawDelete(@NawFilGid);
        //call Trace('Naw is verwijderd -> log aanvullen');
        call ImportLogDetail_Toevoegen(@ilogGid, @NiRegelNummer, _P(@NummerVerwijderdTekst, @NawFilNummer), 2);

        set @TotaalVerwijderd = @TotaalVerwijderd + 1;
        exception when @NAW_in_gebruik1, @NAW_in_gebruik2, @NAW_in_gebruik3 then
        begin
          //call Trace('Naw is niet verwijderd -> log aanvullen');
          call ImportLogDetail_Toevoegen(@ilogGid, @NiRegelNummer, _P(@NummerInGebruikTekst, @NawFilNummer), 4);
        end;
      end;

      set @VorigNawFilNummer = @NawFilNummer;
    end loop loopVerwijderen;

    //Nu ook alle records uit tmpNawImport verwijderen die we nu afgehandeld hebben (anders worden de naws zometeen gelijk weer toegevoegd)
    delete from tmpNawImport where NiVerwijderenCode = @IelVerwijderCode;
    //call Trace('LoopVerwijderen is afgelopen');
  end if;

  //call Trace('Sjabloon-naw variabelen vullen');
  select NawGidVestiging, NawGidCorrespondentie
    into @SjabloonNawGidVestiging, @SjabloonNawGidCorrespondentie
    from tabNaw
    where NawGid = @IelNawGid;

  //Voor elk veld in de exportlayout, het betreffende veld in tmpNawImport vullen met sjabloonwaarde:
  set @IelVeldNaam = '';
  loopVelden :
  loop
    set @IelVorigeVeldnaam = @IelVeldNaam;

    set @IelVeldNaam = '';

    //call Trace('Zoek volgende veld in exportlayout');
    select  first IelVeldNaam,  IelVeldDefaultWaarde,  IelVeldDefaultWaardeOveralDoorvoeren
      into        @IelVeldNaam, @IelVeldDefaultWaarde, @IelVeldDefaultWaardeOveralDoorvoeren
      from  tabImportExportLayout left outer join tabImportExportLayoutVelden on IelVeldIelGid = IelGid
      where (IelNummer = @IelNummer) and (IelSoort = 1) and (IelVeldDefaultWaarde > 1) and
            (IelVeldNaam > @IelVorigeVeldNaam)
      order by IelVeldNaam;

    //call Trace('@IelveldNaam = '+ @ielVeldNaam + '; @IelVeldDefaultWaarde = '+String(@IelVeldDefaultWaarde));

    if IsNull(@IelVeldNaam, '') = '' then
      //call Trace('Breakie breakie...(loopVelden)');
      leave loopVelden;
    end if;

    if @IelVeldDefaultWaarde = 2 then //alleen sjabloonwaarde indien veld leeg
      set @ExtraWhereClause = ' where IsNull('+ @IelVeldNaam +', '''') = '''' ';
    else //anders istie 3 -> altijd sjabloonwaarde gebruiken.
      set @ExtraWhereClause = ' where 1 = 1 ';
    end if;

    if @IelVeldDefaultWaardeOveralDoorvoeren = 0 then //niet updaten bij bestaande naw''s.
      set @ExtraWhereClause = @ExtraWhereClause + ' and not(Exists(select 1 from tabNawFile where NawFilNummer = NiNawFilNummer and NawFilFonGid = ' + String(@IelFonGid) + '))';
    end if;
    //call Trace('De @ExtraWhereClause = ' + @ExtraWhereClause);

    //call Trace('Voor opbouwen Statement.');
    //Tegenrekening is weer eens een uitzondering...
    if @IelVeldNaam = 'NiTegenRksInvoer' then
      set @Statement = 'update tmpNawImport set NiTegenRksInvoer = (select Tegen.RksInvoer from tabNawFile inner join tabRekeningschema Main on (Main.RksGid = NawFilRksGid) left outer join tabRekeningschema Tegen on Tegen.RksGid = Main.TegenRksGid where NawfilNawGid = ' || @IelNawGid || ')' || @ExtraWhereClause;
    else
      if left(@IelVeldNaam, 6) = 'NiVest' then //vestigingsadresveld
        set @Statement = 'update tmpNawImport set ' || @IelVeldNaam || ' = (select ' || substring (@IelVeldNaam, 7) || ' from tabAdres inner join tabLand on (LndGid = AdrLndGid) where AdrGid = ' || @SjabloonNawGidVestiging || ') ' || @ExtraWhereClause;
      else
        if left(@IelVeldNaam, 5) = 'NiCor' then  //correspondentieadres-veld
          set @Statement = 'update tmpNawImport set ' || @IelVeldNaam || ' = (select ' || substring (@IelVeldNaam, 6) || ' from tabAdres inner join tabLand on (LndGid = AdrLndGid) where AdrGid = ' || @SjabloonNawGidCorrespondentie || ')' || @ExtraWhereClause;
        else  //dan is de prefix 'Ni', dan komt het veld uit tabNaw, tabNawFile, tabTaal, tabValuta of tabDebiteurGroepen (let op: relaties hebben geen valuta/tabDebiteurGroepen)
          set @Statement = 'update tmpNawImport set ' || @IelVeldNaam || ' = (select ' || substring (@IelVeldNaam, 3) || ' from tabNaw inner join tabNawFile on (NawFilNawGid = NawGid) inner join tabTaal on (TaalGid = NawTaalGid) left outer join tabValuta on nawfilValNummer = ValNummer left outer join tabDebiteurGroepen on NawFilDebGrpGid = DebGrpGid where NawGid = ' || @IelNawGid || ')' || @ExtraWhereClause;
        end if;
      end if;
    end if;

    //call Trace('@Statement = '+ left(@Statement, 80));
    //call Trace('@Statement, vervolg = '+ substring(@Statement, 81));
    execute immediate @Statement;
  end loop loopVelden;

  //call Trace('"Simpele" velden updaten...');
  //In programma is al gecontroleerd of deze items bestaan.
  update tmpNawImport set
    //Valuta zoeken in ValCODE en ValNummer
    NiNawFilValNummer = (select IsNull(
                                       (select ValNummer from tabValuta where ValCode = NiValCode),
                                       (select ValNummer from tabValuta where Right(Repeat('0', 3) + Trim(NiValCode) ,3) = Right(Repeat('0', 3) + cast(ValNummer as nchar(3)) ,3))
                                      )
                        ),
    //CorrespondentieAdres: Landgid bij lndcode zoeken
    NiCorAdrLndGid    = (select first LndGid from tabLand where NiCorLndOms in (LndEigenCode, LndOms)),
    //VestigingsAdres: Landgid bij lndcode zoeken
    NiVestAdrLndGid   = (select first LndGid from tabLand where NiVestLndOms in (LndEigenCode, LndOms)),
    //TaalGid bij TaalCode zoeken
    NiNawTaalGid      = (select TaalGid from tabTaal where TaalCode = NiTaalCode),
    //TegenrksGid opzoeken bij RksInvoer
    NiTegenRksGid     = (select RksGid from tabRekeningschema where RksInvoer = NiTegenRksInvoer),
    //DebGrpGid opzoeken bij DebGrpNr
    NiNawFilDebGrpGid = (select DebGrpGid from tabDebiteurGroepen where DebGrpNr = NiDebGrpNr);

  //Nu nog even zorgen dat de ECHTE valcode erin staat.
  update tmpNawImport set
    NiValCode = (select Valcode from tabValuta where Valnummer = NiNawFilValNummer);

  //call TraceEind('UpdateTmpNawImport');

end;


//$Workfile: ValutaAfrondBoeken.sp $ $Revision: 3 $ $Modtime: 14-04-08 8:27 $'

if exists (select 1 from sys.sysProcedure where proc_name='ValutaAfrondBoeken') then
  drop function ValutaAfrondBoeken;
end if;

create function ValutaAfrondBoeken( in @ValNummer integer, in @bedrag numeric(17,4) )
returns numeric(15,2)
begin
  declare @Result numeric(15,2);

  //call TraceBegin( 'ValutaAfrondBoeken( ValNummer='+string(@valnummer)+', @bedrag='+string(@bedrag)+')');
  if exists( select 1 from tabvaluta where valnummer=@valnummer and decimalenBoeking=1 ) then
    set @Result = @bedrag
  else
    set @Result = cast( @bedrag as numeric(13,0));
  end if;
  //call TraceEind( 'ValutaAfrondBoeken. @Resultaat='+string(@Result));

  return(@Result);

end;


create or replace function ValutaBedragOmrekenen(in @VanValNummer integer, in @Bedrag numeric(15,2), in @NaarValnummer integer, in @BjGid integer, in @Pernr integer)
returns numeric(15,2)
begin
  //---------- OUDE PROCEDURES, DEZE NIET MEER GEBRUIKEN --------------
  declare @VanKoers double;
  declare @NaarKoers double;
  declare @ValutaBedrag numeric(15,2);

  //call TraceBegin('ValutaBedragOmrekenen > VanValNummer = ' + string(@VanValNummer) + ', @Bedrag = ' + string(@Bedrag) + ', @NaarValnummer = ' + string(@NaarValnummer) + ', @BjGid = ' + string(@BjGid) + ', @Pernr = ' + string(@Pernr));
  //call Trace('ValutaBedragOmrekenen > OUDE PROCEDURES, DEZE NIET MEER GEBRUIKEN!');

  //Nieuw functie aanroepen om afrondingsproblemen te voorkomen
  select ValutaOmrekenen(@VanValNummer, @Bedrag, @NaarValnummer, @BjGid, @Pernr, 2) into @ValutaBedrag;

  //call TraceEind('ValutaBedragOmrekenen > @ValutaBedrag = ' + string(@ValutaBedrag));
  return(@ValutaBedrag);
end;


//$Workfile: ValutaBedragOmrekenenAfgerond.sp $ $Revision: 4 $ $Modtime: 31-08-07 15:54 $'

//---------- OUDE PROCEDURES, DEZE NIET MEER GEBRUIKEN --------------
//------------ Bereken bedrag om naar een andere valuta en rond af volgens instellingen in tabValuta
if exists (select 1 from sys.sysProcedure where proc_name='ValutaBedragOmrekenenAfgerond') then
  drop procedure ValutaBedragOmrekenenAfgerond;
end if;

create procedure ValutaBedragOmrekenenAfgerond(in @VanValNummer integer,in @Bedrag numeric(15,2),in @NaarValnummer integer,in @BjGid integer,in @Datum date,in @Periode integer,inout @ValutaBedrag numeric(15,2))
begin
  declare @VanEuroKoers double;
  declare @NaarEuroKoers double;
  declare @VanKoers double;
  declare @NaarKoers double;
  declare @Decimalen integer;
  declare @Pernr integer;

  //Call TraceBegin('ValutaBedragOmrekenenAfgerond (@VanValNummer='+string(@VanValNummer)+', @Bedrag='+string(@Bedrag)+', @NaarValnummer='+string(@NaarValnummer)+', @BjGid='+string(@BjGid)+', @Datum='+string(@Datum)+', @Periode='+string(@Periode)+')');
  set @ValutaBedrag=0;
  if(@VanValNummer = @NaarValNummer) or(@VanValNummer is null and @NaarValNummer is null) or @Bedrag = 0 then
    set @ValutaBedrag=@Bedrag
  else
    if @Datum is not null then
      call BepaalBoekjaarEnPeriode(@Datum,@BjGid,@PerNr)
    else
      if @Periode is not null then
        set @Pernr=@Periode
      else
        call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum,@BjGid,@PerNr)
      end if
    end if;
    if @Pernr is not null then
      if @VanValNummer is null then
        set @VanValNummer=@@BasisValutaNummer
      end if;
      if @NaarValNummer is null then
        set @NaarValNummer=@@BasisValutaNummer
      end if;
      if @@TijdelijkeKoersen = 1 then
        //Let op: deze routine is zo omslachtig omdat de tijdelijkekoersen bijna altijd op 0 staat
        select HlpKrsKoersTovEuro,HlpKrsKoers/HlpKrsEenheid into @VanEuroKoers,@VanKoers from tabHulpKoers where HlpKrsValNummer = @VanValNummer and HlpKrsBjGid = @BjGid and HlpKrsPerNr = @Pernr;
        if @VanKoers is null then
          select KrsKoersTovEuro,Koers/KrsEenheid into @VanEuroKoers,@VanKoers from tabValutaKoers where KrsValnummer = @VanValNummer and ValBjGid = @BjGid and ValPernr = @Pernr
        end if;
        if @VanValNummer = @@BasisValutaNummer then
          set @VanKoers=1
        end if;
        select HlpKrsKoersTovEuro,HlpKrsKoers/HlpKrsEenheid into @NaarEuroKoers,@NaarKoers from tabHulpKoers where HlpKrsValNummer = @NaarValNummer and HlpKrsBjGid = @BjGid and HlpKrsPerNr = @Pernr;
        if @@EuroValutaNummer is null then
          set @NaarEuroKoers=null;
          set @VanEuroKoers=null
        end if;
        if @NaarKoers is null then
          select KrsKoersTovEuro,Koers/KrsEenheid into @NaarEuroKoers,@NaarKoers from tabValutaKoers where KrsValnummer = @NaarValNummer and ValBjGid = @BjGid and ValPernr = @Pernr
        end if;
        if @NaarValNummer = @@BasisValutaNummer then
          set @NaarKoers=1
        end if;
        if isnull(@VanEuroKoers,0) <> 0 and isnull(@NaarEuroKoers,0) <> 0 then
          set @ValutaBedrag=(@Bedrag*@NaarEuroKoers/@VanEuroKoers)
        else
          set @ValutaBedrag=(@Bedrag*@VanKoers/@NaarKoers)
        end if
      else
        if @@EuroValutaNummer is not null then
          select KrsKoersTovEuro into @VanEuroKoers from tabValutaKoers where krsValnummer = @VanValNummer and ValBjGid = @BjGid and ValPernr = @Pernr;
          if isnull(@VanEuroKoers,0) <> 0 then
            select KrsKoersTovEuro into @NaarEuroKoers from tabValutaKoers where krsValnummer = @NaarValNummer and ValBjGid = @BjGid and ValPernr = @Pernr
          end if
        end if;
        if isnull(@VanEuroKoers,0) <> 0 and isnull(@NaarEuroKoers,0) <> 0 then
          set @ValutaBedrag=(@Bedrag*@NaarEuroKoers/@VanEuroKoers)
        else
          select Koers/KrsEenheid into @VanKoers from tabValutaKoers where KrsValnummer = @VanValNummer and ValBjGid = @BjGid and ValPernr = @Pernr;
          select Koers/KrsEenheid into @NaarKoers from tabValutaKoers where KrsValnummer = @NaarValNummer and ValBjGid = @BjGid and ValPernr = @Pernr;
          set @ValutaBedrag=(@Bedrag*@VanKoers/@NaarKoers)
        end if
      end if
    end if;
    //call Trace('VanKoers='+string(@vankoers)+', NaarKoers='+string(@NaarKoers)+', VanBedrag='+string(@Bedrag)+', NaarBedrag='+string(@ValutaBedrag));
  end if;
  //Call TraceEind('ValutaBedragOmrekenenAfgerond ------> @ValutaBedrag='+string(@ValutaBedrag));

end;


//$Workfile: ValutaBijwerkenEuroKoersen.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

if exists (select 1 from sys.sysProcedure where proc_name='ValutaBijwerkenEuroKoersen') then
  drop procedure ValutaBijwerkenEuroKoersen;
end if;

create Procedure ValutaBijwerkenEuroKoersen(in @IsEuroKoers smallint, in @hlpkrsGid integer, in @Welke integer, in @EuroKoers numeric(15,6), in @OldKoers numeric(15,6) )
begin
  declare @BjGid integer;
  declare @PerNr integer;
  declare @valNummer integer;

  set @@ErrorTextProcedure = 'ValutaBijwerkenEuroKoersen > @HlpkrsGid='+string(@HlpkrsGid)+', @Welke='+string(@Welke)+', @Eurokoers='+String(@Eurokoers);
  //call TraceBegin(@@ErrorTextProcedure);

  select HlpKrsValNummer, HlpKrsBjGid, HlpKrsPerNr into @ValNummer, @BjGid, @PerNr from tabHulpKoers where HlpKrsGid=@HlpKrsGid;

  if @IsEuroKoers = 1 then
    case @Welke
      when 0 then
        //Gehele boekjaar
        update tabHulpKoers
        set    HlpKrsKoersTovEuro = @EuroKoers,
               HlpKrsGewijzigd= 1
        where  HlpKrsValNummer = @ValNummer and HlpKrsBjGid = @BjGid;
      when 1 then
        //Vanaf periode @PerNr
        update tabHulpKoers
        set    HlpKrsKoersTovEuro = @EuroKoers,
               HlpKrsGewijzigd= 1
        from   tabHulpKoers OrigPer
        where  HlpKrsValNummer = @ValNummer and HlpKrsBjGid = @BjGid and HlpKrsPerNr >= @PerNr;
      when 2 then
        //Alleen periode PerNr
        update tabHulpKoers
        set    HlpKrsKoersTovEuro = @EuroKoers,
               HlpKrsGewijzigd= 1
        where  HlpKrsValNummer = @ValNummer and HlpKrsBjGid = @BjGid and HlpKrsPerNr = @PerNr;
      when 3 then
        //Tot aan de volgende geboekte periode of waarvan de koers anders is
        update tabHulpKoers
        set    HlpKrsKoersTovEuro = @EuroKoers,
               HlpKrsGewijzigd= 1
        where  HlpKrsValNummer = @ValNummer and
               HlpKrsBjGid = @BjGid and
               HlpKrsPerNr < isnull((
                 SELECT
                        min(RekSaldoPerNr)
                 FROM tabRekeningsaldo
                 WHERE
                        RekSaldoValNummer=@ValNummer and
                        RekSaldoBjGid=@BjGid and
                        RekSaldoPerNr >@Pernr
                 ),999)
                 and
                 HlpKrsPerNr < isnull((
                   SELECT
                     min(Tussen.HlpKrsPerNr)
                   FROM
                   tabHulpKoers Tussen
                 where
                   Tussen.HlpKrsValNummer=@ValNummer and
                   Tussen.HlpKrsBjGid=@BjGid and
                   Tussen.HlpKrsPerNr > @Pernr
                   and Tussen.HlpKrsKoersTovEuro <> @OldKoers),999)
             and
               HlpKrsPerNr >=@Pernr;
    end case;
  else
    //De 'normale' koers
    case @Welke
      when 0 then
        //Gehele boekjaar
        update tabHulpKoers
        set    HlpKrsKoers = @EuroKoers,
               HlpKrsGewijzigd= 1
        where  HlpKrsValNummer = @ValNummer and HlpKrsBjGid = @BjGid;
      when 1 then
        //Vanaf periode @PerNr
        update tabHulpKoers
        set    HlpKrsKoers = @EuroKoers,
               HlpKrsGewijzigd= 1
        from   tabHulpKoers OrigPer
        where  HlpKrsValNummer = @ValNummer and HlpKrsBjGid = @BjGid and HlpKrsPerNr >= @PerNr;
      when 2 then
        //Alleen periode PerNr
        update tabHulpKoers
        set    HlpKrsKoers = @EuroKoers,
               HlpKrsGewijzigd= 1
        where  HlpKrsValNummer = @ValNummer and HlpKrsBjGid = @BjGid and HlpKrsPerNr = @PerNr;
      when 3 then
        //Tot aan de volgende geboekte periode of waarvan de koers anders is
        update tabHulpKoers
        set    HlpKrsKoers = @EuroKoers,
               HlpKrsGewijzigd= 1
        where  HlpKrsValNummer = @ValNummer and
               HlpKrsBjGid = @BjGid and
               HlpKrsPerNr < isnull((
                 SELECT
                        min(RekSaldoPerNr)
                 FROM tabRekeningsaldo
                 WHERE
                        RekSaldoValNummer=@ValNummer and
                        RekSaldoBjGid=@BjGid and
                        RekSaldoPerNr >@Pernr
                 ),999)
                 and
                 HlpKrsPerNr < isnull((
                   SELECT
                     min(Tussen.HlpKrsPerNr)
                   FROM
                   tabHulpKoers Tussen
                 where
                   Tussen.HlpKrsValNummer=@ValNummer and
                   Tussen.HlpKrsBjGid=@BjGid and
                   Tussen.HlpKrsPerNr > @Pernr
                   and Tussen.HlpKrsKoers <> @OldKoers),999)
             and
               HlpKrsPerNr >=@Pernr;
    end case;
  end if;

  set @@ErrorTextProcedure = 'ValutaBijwerkenEuroKoersen';
  //call TraceEind(@@ErrorTextProcedure);

end;


//------------- Herberekenen van de (valuta)koersen
create or replace procedure ValutaHerberekenen(in @BjGid integer, in @Alles smallint, in @GegevenOms nchar(40))
begin
  declare @IsolationLevel       smallint;
  declare @DgbGidValuta         integer;
  declare @DgbGidValutaBegin    integer;
  declare @DgbGid               integer;
  declare @BoekStuknummer       decimal(10);
  declare @ValNummer            integer;
  declare @ValCode              nchar(3);
  declare @JpPernr              integer;
  declare @boekPerNr            integer;
  declare @NieuweKoers          decimal(15,6);
  declare @OudeKoers            decimal(15,6);
  declare @NieuweEenheid        integer;
  declare @OudeEenheid          integer;
  declare @NieuweKoersTOVeuro   double;
  declare @OudeKoersTOVeuro     double;
  declare @VorigeValNummer      integer;
  declare @correctieKoersTovEuro double;
  declare @correctieKoers        double;
  declare @InGebruik            integer;
  declare @ProgressToDo         integer;
  declare @oms                  nchar(40);
  declare @InvOms               nchar(40);
  declare @BasisValutaIsEmu     integer;
  declare @TeBoekenBedrag       decimal(15,2);
  declare @jpgid                integer;
  declare @tmpGid               integer;
  declare @JpDgbGid             integer;
  declare @JpInGebruik          smallint;
  declare @IsBasisValuta        smallint;
  declare @ValNrVanDagboek      integer;
  declare @KoersCorrPerNr       integer;
  declare @BufferBoekgangGid    integer; //om oude @@boekganggid terug te zetten!!
  declare @bufferJpGid          integer;
  declare @hulpbedrag           decimal(15,2);
  declare @HlpKrsBjGid          integer;
  declare @HlpKrsPerNr          integer;
  declare @KoersIsVeranderd     smallint;

  declare @CorrJpGid            integer;
  declare @HerwJpGid            integer;
  declare @BufIgnoreProgressAdd smallint;
  //Om boeking op tegenrek. in vreemde valuta te corrigeren
  declare @OpTegenRekValuta      integer;
  declare @OpTegenRekValBedrag   numeric(15,2);
  declare @OpTegenRekBasisBedrag numeric(15,2);
  declare @OpTegenRekIsCredit    smallint;
  declare @temp                  integer;
  declare @temp2                 numeric(15,6);
  declare @MaakBoekingen         smallint;

  declare @HerwaardParameterTekst long nvarchar;
  declare @HerwaarderingTekst     long nvarchar;

  //Cursors voor de herberekeningslussen
  //Eerst de voorlopige boekingsgangen
  declare cursor_VoorlopigeBoekingsgangen dynamic scroll cursor for
    select   distinct BoekgangGid, BoekgangInGebruik
    from     tabBoekingsGang
             inner join tabJournaalpost on (JpBoekGangGID = BoekGangGid)
             inner join tabJournaalRegel on (JrJpGid = JpGid and JrValNummer <> @@BasisValutaNummer)
    where    IsBoekgangDefinitief = 0 and BoekgangBjGid = @BjGid
    order by BoekgangGid
  for update;

  //De journaalposten in een voorlopige boekingsgang
  declare cursor_VoorlopigeJournaalPosten dynamic scroll cursor for
    select   JpGid, JpDgbGid, JpIsInGebruik, JrPerNr, RksValNummer
    from     tabJournaalpost
             inner join tabJournaalRegel on (JrJpGid = JpGid and JrValNummer <> @@BasisValutaNummer)
             inner join tabDagboek on (DgbGid = JpDgbGid)
             inner join tabRekeningschema on (RksGid = DgbTegenRksGID)
    where    JpBoekGangGid = @@BoekgangGid and jpIsInGebruik=0 and OrigineelJpId is null
    group by JpGid, JpDgbGid, JpIsInGebruik, JpNummer, JrPerNr, RksValNummer
    order by JpNummer
  for update;

  declare cursor_KoersenVoorDefinitieveBoekingsgangen cursor for
    select   hlpkrsGid, HlpKrsValNummer, HlpKrsPerNr, HlpKrsEenheid, HlpKrsKoers, HlpKrsKoersTovEuro, HlpKrsBjGid, HlpKrsPerNr
    from     tabHulpKoers
    where    HlpKrsBjGid = @BjGid and HlpKrsGewijzigd <> 0
    // ACW 27-05-2004: periodenummer in de volgorde toegevoegd, zodat in de juiste periodevolgorde wordt verwerkt
    order by HlpKrsGewijzigd desc, hlpkrsPerNr, hlpkrsGid asc //Om de euro eerst te laten berekenen wordt HlpKrsGewijzigd = 2 gebruikt (ipv. HlpKrsGewijzigd = 1)
  for read only;


  //call TraceBegin('ValutaHerberekenen > @BjGid = ' + string(@BjGid));

  set @IsolationLevel = @@Isolation;
  if @@Isolation < 1 then
    set temporary option Isolation_Level = 1;
  end if;

  set @HerwaardParameterTekst = _A('Herwaard. %1!');

  set @BufIgnoreProgressAdd = @@IgnoreProgressAdd;

  //RVL 07-10-2016 : #49913 Voordat we gaan herberekenen moet we zorgen dat alle valuta's en de koersen in tabHulpKoers staan. Door onderstaande proc uit te voeren worden de ontbrekende valuta's alsnog toegevoegd
  call Tijdelijkekoersen(@Bjgid, null, 0);

  //Alles (handmatig herwaarderen), dan ook alles doen!
  if @Alles=1 then
    update tabHulpKoers set HlpKrsGewijzigd = 1;
  end if;

  //Voor 1 klant is een stukje maatwerk ingebouwd. Bij het wijzigen van de koersen wil de klant GEEN herwaarderingsboekingen. Deze klant heeft iedere
  //dag koerswijzigingen en iedere dag is een periode. Als gevolg hiervan krijgt deze klant enorm veel boekingen. Afgesproken is dat er alleen
  //herwaarderingsboekingen worden gemaakt als de klant zelf op de herwaarderings-button heeft gedrukt ("@Alles=1")
  //Bij de klant staat 'HERWAARDERING_UITSCHAKELEN' staat op '1'.
  set @MaakBoekingen = 1;
  if (@Alles <> 1) and ((select Contents from tabRegistry where RegKey = 'HERWAARDERING_UITSCHAKELEN') = '1') then
    set @MaakBoekingen = 0;
  end if;

  //voorlopig (= aantal journaalposten die misschien worden gewijzigd)
  set @ProgressToDo = 0;
  select  count(*) into @ProgressToDo
  from    tabBoekingsGang inner join tabJournaalpost on JpBoekGangGid = BoekGangGid
  where   IsBoekgangDefinitief = 0 and BoekgangBjGid = @BjGid and jpIsInGebruik=0 and OrigineelJpId is null;
  //+definitief
  select  count(*) into @temp
  from    tabHulpKoers
  where   HlpKrsBjGid = @BjGid and HlpKrsGewijzigd <> 0;

  set @ProgressToDo = isnull(@ProgressToDo,0)+isnull(@temp,0);

  //Bij afsluiten journaalpost wordt de progress 4x geupdate + hier nog een keer=5x !!!
  call ProgressCreate( 0, @ProgressToDo, _U('Herwaarderen'));

  set @BufferBoekgangGid = @@boekganggid;
  set @bufferjpgid = @@JpGid;

  select DgbGidValuta, DgbGidValutaBegin into @DgbGidValuta, @DgbGidValutaBegin from tabVasteGegevens;

  //Bepaal of een wijziging van de Eurokoers ook een herberekening tot gevolg heeft
  //(alleen als de basisvaluta ook een EMU-valuta is)
  set @BasisValutaIsEmu = 0;
  select 1 into @BasisValutaIsEmu from tabvaluta where IsBasisValuta <> 0 and ( NaarEuro <> 0 or IsEuro <> 0 );


  //Als een periode van de euro-valuta is aangepast, dan moet dezelfde periode van alle valutas worden aangepast als deze een
  //eurovalutakoers bevatten en de basisvaluta heeft ook een eurokoers!


  // ****************************
  // *** voorlopige boekingen ***
  // ****************************
  //Loop alle boekingsgangen door

  //call Trace('ValutaHerberekenen > Voorlopige boekingen');

  //LET OP: @TijdelijkeKoersen zorgt ervoor dat de tabHulpKoers wordt gebruikt ipv. de 'echte' koersen
  set @@TijdelijkeKoersen = 1;
  set @JpInGebruik        = 0;

  call ProgressSet(null, null, _U('Herwaarderen (voorlopig)'));

  // *** Voor de valutas die niet in tabjournaal voorkomen alleen de valutatabel updaten, niet het journaal erop controleren ***

  //Zoek de valutas op die wel zijn gewijzigd maar niet in tabjournaalregel zitten of basisvaluta zijn
  update tabHulpKoers
  set    HlpKrsGewijzigd = 3
  where  HlpKrsGewijzigd <> 0 and
         HlpKrsBjGid = @BjGid and
         ( HlpKrsValNummer = @@BasisValutaNummer or
           HlpKrsValNummer not in (select JrValNummer from tabJournaalregel where jrBjGid = @BjGid)
         );

  update tabValutaKoers
  set    Koers           = HlpKrsKoers,
         krsKoersTovEuro = HlpKrsKoersTovEuro
  from   tabHulpKoers
  where  HlpKrsGewijzigd = 3 and
         KrsValNummer    = HlpKrsValNummer and
         ValBjGid        = @BjGid and
         ValPernr        = HlpKrsPernr;
  //Update ook direct de eenheid in tabValuta
  update tabValutaKoers
  set    KrsEenheid = HlpKrsEenheid
  from   tabHulpKoers
  where  HlpKrsGewijzigd = 3 and
         KrsValNummer    = HlpKrsValNummer and
         ValBjGid        = @BjGid and
         HlpKrsPernr     = 0; //Haal de eenheid uit periode 0!!
  //En als laatste de 'koers gewijzigd' uitzetten
  update tabHulpKoers
  set    HlpKrsGewijzigd = 0
  where  HlpKrsGewijzigd = 3;

  //Progress updaten want misschien is er een aantal regels niet meer te doen.
  set @ProgressToDo = @ProgressToDo - @@rowcount;
  call ProgressSet(null, @ProgressToDo, null);

  if @MaakBoekingen = 1 then
    open cursor_VoorlopigeBoekingsgangen;
    loopje1:
    loop
      Fetch next cursor_VoorlopigeBoekingsgangen into @@BoekgangGid, @InGebruik;
      if sqlstate = '02000' then
        leave loopje1;
      end if;

      //call Trace( 'Voorlopige boeking: ' + string( @@BoekgangGid ) );

      if @InGebruik = 0 then
        //call Trace('Boekingsgang was niet gelocked, dus nu doen!');
        update tabBoekingsGang set BoekgangInGebruik = 1  where BoekgangGid = @@BoekgangGid;
      else
        set @@OverRuleLock = 1;
        //call Trace('Boekingsgang was al gelocked, ignore locks!');
      end if;

      //Loop alle journaalposten door in de boekingsgang
      open cursor_VoorlopigeJournaalPosten;
      loopje2:
      loop
        Fetch next cursor_VoorlopigeJournaalPosten into @JpGid, @JpDgbGid, @JpInGebruik, @JpPerNr, @ValNrVanDagboek;
        if sqlstate = '02000' then
          leave loopje2;
        end if;

        call ProgressAdd( 1 );

        if @JpInGebruik = 0 then

          //Eerst de journaalpost in gebruik nemen (indien het een vorige periode is, dan ook openen!!!!)
          update tabJournaalPost set JpIsInGebruik = 1 where JpGid = @JpGid;

          // ACW 2008-08-13 Meerdere boekdata per journaalpost -> Extra lus per periode
          for @Cursor_JPperiodes as PeriodesInJournaalpostCursor cursor for
            select JrPerNr @JrPerNr,
                   max(jrboekdatum) @HoogsteBoekdatum
            from   tabJournaalregel
            where  JrJpGid = @JpGid
            group by JrPerNr
            order by JrPerNr
          do
            //Bepaal het bedrag en de valuta van de boeking op de tegenrekening als die in een andere valuta staat
            set @OpTegenRekValuta      = null;
            set @OpTegenRekValBedrag   = null;
            set @OpTegenRekBasisBedrag = null;
            set @OpTegenRekIsCredit    = null;
  /*ACW 2008-08-13: Dit werkt niet NA het openen van de journaalregel!
                  ivm. project meerdere data per journaalpost dit verwijderd
                  omdat anders deze gegevens in een tijdelijke tabel moeten worden gezet
            select JrValNummer, JrValutaBedrag, JrBasisBedrag, IsCreditBoeking
            into   @OpTegenRekValuta, @OpTegenRekValBedrag, @OpTegenRekBasisBedrag, @OpTegenRekIsCredit
            from   tabjournaalregel
            where  jrJpGid = @JpGid and SoortBoeking = 1 and JrValNummer <> @@BasisValutaNummer;
  */

            for @CursorKoersen as cursor_Koersen dynamic scroll cursor for
              select HlpKrsValNummer @curValNummer,
                     HlpKrsKoers @curNieuweKoers,
                     HlpKrsKoersTovEuro @curNieuweKoersTOVeuro
              from   tabHulpKoers
              where  HlpKrsBjGid=@BjGid and
                     HlpKrsPerNr=@JrPerNr and
                     //HlpKrsGewijzigd <> 0 and  //RVL 07-10-2016 : #49913
                     HlpKrsValNummer <> @@BasisValutaNummer and
                     ( HlpKrsValNummer = @OpTegenRekValuta
                       or HlpKrsValNummer in ( select jrValNummer from tabJournaalRegel where JrJpGid=@JpGid and JrPerNr = @JrPerNr)
                       or HlpKrsValNummer in ( select HulpRekValNummer from tabjournaalregel inner join tabhulprekening on (HulpRekJrGid = JrGid) where JrJpGid=@JpGid and JrPerNr = @JrPerNr) //Let op: de jp is al geopend als deze cursor wordt geopend!!
                     )
              order by HlpKrsValNummer, HlpKrsBjGid, HlpKrsPerNr
            do
              //De oude koersen erbij plukken
              select   Koers, krsKoersTOVeuro
              into     @OudeKoers, @OudeKoersTOVeuro
              from     tabValutaKoers
              where    ValBjGid     = @BjGid and
                       ValPerNr     = @JrPerNr and
                       KrsValNummer = @curValNummer;

              //'Totaal te boeken' obv. nieuwe koersen bepalen
              select sum(ValutaOmrekenen(@curValNummer, if IsCreditBoeking <> 0 then JrValutaBedrag else -JrValutaBedrag endif, @@BasisValutaNummer, JrBjGid, JrPerNr, 2) - if IsCreditBoeking <> 0 then JrBasisBedrag else -JrBasisBedrag endif)
              into   @TeBoekenBedrag
              from   tabJournaalRegel
              where  JrJpGid=@JpGid and JrValNummer=@curValNummer and JrPerNr = @JrPerNr;

              select sum(ValutaOmrekenen(@curValNummer, if IsCreditBoeking <> 0 then HulpRekValutaBedrag else -HulpRekValutaBedrag endif, @@BasisValutaNummer, JrBjGid, JrPerNr, 2) - if IsCreditBoeking <> 0 then HulpRekBasisBedrag else -HulpRekBasisBedrag endif)
              into   @hulpbedrag
              from   tabHulprekening
                     inner join tabJournaalRegel on (JrGid = HulpRekJrGid)
              where JrJpGid=@JpGid and HulpRekValNummer=@curValNummer and JrPerNr = @JrPerNr;

              set @TeBoekenBedrag = isnull(@TeBoekenBedrag,0) - isnull(@hulpbedrag,0);

              //Correctie voor boeken op tegenrekening
  /* ACW 2008-08-13: Dit kan niet omdat @OpTegenRekValBedrag altijd NULL is!
              if ( @curValNummer = @OpTegenRekValuta ) and ( @OpTegenRekValBedrag is not null ) then
                set @TeBoekenBedrag = @TeBoekenBedrag + ValutaOmrekenen(@curValNummer, if @OpTegenRekIsCredit <> 0 then @OpTegenRekValBedrag else -@OpTegenRekValBedrag endif, @@BasisValutaNummer, @BjGid, @JrPerNr, 2)
                                                      - if @OpTegenRekIsCredit <> 0 then @OpTegenRekBasisBedrag else -@OpTegenRekBasisBedrag endif;
              end if;
  */

              //Voor elke regel met de valuta opnieuw de tegenwaarde berekenen
              //LET OP: de valutacodetabel is nog niet overgenomen!!!
              //We moeten dus de koers berekenen obv. de TIJDELIJKE tabel !!!
              update tabJournaalRegel
              set    JrBasisBedrag = ValutaOmrekenen(@curValNummer, JrValutaBedrag, @@BasisValutaNummer, JrBjGid, JrPerNr, 2)
              where  JrJpGid = @JpGid and JrValNummer = @curValNummer and JrPerNr = @JrPerNr;


              update tabHulpRekening
              set    HulpRekBasisBedrag =         if HulpRekValNummer = @curValNummer then ValutaOmrekenen(@curValNummer, HulpRekValutaBedrag, @@BasisValutaNummer, JrBjGid, JrPerNr, 2) else HulpRekBasisBedrag endif,
                     HulpRekBedragInJrValNummer = if JrValNummer =      @curValNummer then ValutaOmrekenen(@curValNummer, HulpRekValutaBedrag, JrValNummer,         JrBjGid, JrPerNr, 2) else HulpRekBedragInJrValNummer endif
              from   tabJournaalRegel
              where  JrJpGid = @JpGid and HulpRekJrGid = JrGid and (HulpRekValNummer = @curValNummer or JrValNummer = @curValNummer ) and JrPerNr = @JrPerNr;

              //Als koersverschil <> 0 dan toevoegen van extra regel als koersverschillenrekening van valuta
              if @TeBoekenBedrag <> 0 and @JrPerNr <> 0 and @ValNrVanDagboek <> @curValNummer then
                //Niet voor de beginbalans!! -> deze gaat naar de tegenrekening bij afsluiten van de journaalpost
                if @GegevenOms is not null then
                  set @oms= @GegevenOms;
                else
                  if /* ACW 27-05-2004: alleen op IsEmu testen!( @OudeKoersTOVeuro <> @curNieuweKoersTOVeuro ) and*/ ( @BasisValutaIsEmu <> 0 ) then
                    set @Oms = @ValCode+' : '+NumToStr(@OudeKoersTOVeuro, 6)+' -> '+NumToStr(@curNieuweKoersTOVeuro, 6);
                  else
                    set @Oms = @ValCode+' : '+NumToStr(@OudeKoers, 6)+' -> '+NumToStr(@curNieuweKoers, 6);
                  end if;
                end if;
                //call Trace('Insert into tabJournaalregel '+@oms);
                insert into tabJournaalregel(
                         JrJpGid, jrBoekdatum, JrRksGid, StukVolgnr,
                         OmsJournaalRegel,
                         SoortBoeking, IsCreditBoeking, JrValnummer,
                         JrBasisBedrag, JrValutaBedrag)
                select   @JpGid, @HoogsteBoekdatum, KoersverschilRksGID, StukvolgnrGenereerNieuw( @JpGid, 1000),
                         _P(@HerwaardParameterTekst, @Oms),
                         4, if @TeBoekenBedrag<0 then 1 else 0 endif, @@BasisValutaNummer,
                         abs( @TeBoekenBedrag ), abs( @TeBoekenBedrag )
                from     tabValuta inner join tabValutaKoers on ( ValNummer = KrsValNummer )
                where    ValNummer=@curValNummer and ValBjGid = @BjGid and ValPerNr = @JrPerNr;
              end if;

            end for; //valuta-loop

          end for; // Lus periodes binnen journaalpost

          set @@IgnoreProgressAdd = 1;
          update tabJournaalPost set JpIsInGebruik = 0 where JpGid = @JpGid;
          set @@IgnoreProgressAdd = @BufIgnoreProgressAdd;


          //Eventueel de tegenwaarde wederom zetten NA!! sluiten van de post
  /* ACW 2008-08-13: Omdat het opvragen van de velden na het openen van de JP niet werkt, hier ook
                     de update-routine verwijderd (want dit kan zo niet werken)
          set @@OverRuleLock = 1;
          update tabjournaalregel
          set    JrValutaBedrag = @OpTegenRekValBedrag
          where jrJpGid = @JpGid and SoortBoeking = 1 and JrValNummer = @OpTegenRekValuta;
          if @InGebruik = 0 then
            //Overrule weer ongedaan maken als die niet voor de boekingsgang nodig is
            set @@OverRuleLock = 0;
          end if;
  */
        end if;

      end loop loopje2; //journaalpost-loop
      close cursor_VoorlopigeJournaalPosten;

      //geef de boekingsgang weer vrij
      if @InGebruik = 0 then
        //call Trace('Boekingsganglock verwijderen');
        update tabBoekingsGang set BoekgangInGebruik = 0 where BoekgangGid = @@BoekgangGid;
      else
        //call Trace('Ignore lock verwijderen');
        set @@OverRuleLock = 0;
      end if;

    end loop loopje1; //boekingsgang-loop
    close cursor_VoorlopigeBoekingsgangen;

  end if;

  set @@TijdelijkeKoersen = 1;

  // *****************************
  // *** Definitieve boekingen ***
  // *****************************

  //Yep, geen koerscorrectie maken; dit handelen wij zelf wel af
  set @@GeenKoersCorrectie = 1;

  //Maak boekingsgang aan (voor de definitieve boekingsgangen)
  if @MaakBoekingen = 1 then
    call ProgressSet(null, null, _U('Herwaarderen (definitief)'));
    insert into tabBoekingsGang(BoekGangBjGid, BoekgangBronId, BoekGangInGebruik, IsBoekGangDefinitief)
    values(@BjGid,3,1,1);
  end if;

  set @IsBasisValuta = -1;
  set @VorigeValNummer = -1;

  //De euro moet als eerste worden gedaan, dus voor de euro dan maar een extra aanvulling maken:
  update tabHulpKoers
  set    HlpKrsGewijzigd = 2
  where  HlpKrsGewijzigd = 1 and
         HlpKrsBjGid = @BjGid and
         HlpKrsValNummer = @@EuroValutaNummer;

  open cursor_KoersenVoorDefinitieveBoekingsgangen with hold;
  defloopje1:
  loop
    fetch next cursor_KoersenVoorDefinitieveBoekingsgangen into @TmpGid, @ValNummer, @JpPernr, @NieuweEenheid, @NieuweKoers, @NieuweKoersTOVeuro, @HlpKrsBjGid, @HlpKrsPerNr;
    if sqlstate = '02000' then
      leave defloopje1;
    end if;
    call ProgressAdd( 1 );

    //Oude koersen erbij plukken
    select   Koers, krsKoersTOVeuro
    into     @OudeKoers, @OudeKoersTOVeuro
    from     tabValutaKoers
    where    KrsValNummer = @ValNummer and
             ValBjGid     = @HlpKrsBjGid and
             ValPerNr     = @HlpKrsPerNr;

    //call Trace( 'Definitieve boeking: Valuta ' + string(@ValNummer) );

    //Alleen als we van valuta veranderen, dan de @oudeEenheid vullen. Dit omdat bij de eerste update van een
    //koers (in een bepaalde periode) de eenheid in tabvaluta wordt weggeschreven.
    if @ValNummer <> @VorigeValNummer then
      select KrsEenheid into @OudeEenheid from tabValutaKoers where KrsValNummer=@ValNummer and ValBjGid=@BjGid and ValPerNr=0;
      select IsBasisValuta, ValCode into @IsBasisValuta, @ValCode from tabValuta where ValNummer=@ValNummer;
    end if;

    if (@OudeKoers<>@NieuweKoers) or (@OudeEenheid<>@NieuweEenheid) or (isnull(@OudeKoersTOVeuro,0)<>isnull(@NieuweKoersTOVeuro,0)) then
      set @KoersIsVeranderd = 1;
    else
      set @KoersIsVeranderd = 0;
    end if;

    if @Alles = 1 or @KoersIsVeranderd = 1 then
      set @HerwaarderingTekst = _A('Herwaardering');

      // *** valutatabel updaten ***

      if @KoersIsVeranderd = 1 then
        update tabValutaKoers
        set    Koers           = @NieuweKoers,
               krsKoersTovEuro = @NieuweKoersTovEuro
        where  ValBjGid = @BjGid and ValPernr = @JpPernr and KrsValNummer = @ValNummer;
        //Update ook direct de eenheid in tabValuta
        if @ValNummer<>IsNull(@VorigeValNummer,0) then
          update tabValutaKoers set KrsEenheid = @NieuweEenheid where KrsValNummer = @ValNummer;
        end if;
      end if;

      // *** Boekingen ***

      if (@MaakBoekingen = 1) and (@IsBasisValuta = 0) and (@KoersIsVeranderd = 1 or @alles = 1) then
        if @GegevenOms is not null then
          set @oms= @GegevenOms;
          set @Invoms= @GegevenOms;
        else
          if /*ACW 27-05-2004: alleen op IsEmu testen! ( @OudeKoersTOVeuro <> @NieuweKoersTOVeuro ) and */ ( @BasisValutaIsEmu <> 0 ) then
            set @oms    = @ValCode+' : '+NumToStr(@OudeKoersTOVeuro,6)+' -> '+NumToStr(@NieuweKoersTOVeuro,6);
            set @InvOms = @ValCode+' : '+NumToStr(@NieuweKoersTOVeuro,6)+' -> '+NumToStr(@OudeKoersTOVeuro,6)
          else
            set @oms    = @ValCode+' : '+NumToStr(@OudeKoers,6)+' -> '+NumToStr(@NieuweKoers,6);
            set @InvOms = @ValCode+' : '+NumToStr(@NieuweKoers,6)+' -> '+NumToStr(@OudeKoers,6);
          end if;
        end if;

        if @JpPernr=0 then
          set @DgbGid=@DgbGidValutaBegin;
        else
          set @DgbGid=@DgbGidValuta;
        end if;

        //Genereer boekstuknummer
        call BoekstuknummerGenereren (@BjGid,@DgbGid,@BoekStukNummer);

        //Als boekstuknummer niet wordt gegenereerd volgens dagboek instelling, dan maar forceren
        if IsNull(@BoekStukNummer,0)=0 then
          call BoekstuknummerPlusEen( @BjGid,@DgbGid,1,@BoekstukNummer );
        end if;

        //Maak journaalpost aan voor koerswijzigingsboekingen
        insert into tabJournaalPost(JpBoekGangGid,JpBjGid,JpDgbGid,BoekStukNummer,OmsJournaalpost,BoekDatum,JpIsInGebruik)
           select @@BoekGangGid,@BjGid,@DgbGid,@BoekStukNummer,@HerwaarderingTekst,if @JpPernr=0 then BeginDatum else EindDatum endif,1
           from tabPeriode where PerBjGid=@BjGid and Pernr=if @JpPernr=0 then 1 else @JpPerNr endif;
        set @HerwJpGid=@@JpGid;

        set @@IgnoreProgressAdd = 1;

        //Maak journaalpost aan voor (eventuele) koerscorrecties in de eerstvolgende periode waarin geboekt of andere (oude!!!) koers
        set @CorrJpGid      = null;
        set @KoersCorrPerNr = -1;
        select min(ValPerNr) into @KoersCorrPerNr
        from   tabValutaKoers, tabHulpKoers
        where  ValBjGid        = @BjGid and         //In 'dit' boekjaar
               KrsValNummer    = @ValNummer and
               HlpKrsValNummer = @ValNummer and
               HlpKrsBjGid     = @BjGid and
               HlpKrsPerNr     = ValPerNr and //ACW 21-01-2015 Defect #44442: NIET @JpPerNr, omdat we de NIEUWE koersen in de komende periodes moeten vergelijken
               ValPerNr > @JpPerNr and         //Correctie in een periode NA deze periode
               ( ( Koers <> @NieuweKoers and     //Correctie alleen in een periode waarvan de OUDE koers anders is dan de huidige NIEUWE koers
                   exists(select 1 from tabjournaalregel where JrBjGid = @BjGid and JrPerNr = ValPerNr and JrValNummer = @ValNummer) //EN waarin ook geboekt is IN DIE VALUTA
                 ) or //OF de nieuwe koers ongelijk aan de huidige nieuwe koers
                 ( HlpKrsKoers <> @NieuweKoers )
               );
        if @KoersCorrPerNr > 0 then
          //ACW defect #44918: Niet de einddatum, maar de begindatum pakken voor de correctie in een volgende periode
          insert into tabJournaalPost(JpBoekGangGid,JpBjGid,JpDgbGid,BoekStukNummer,OmsJournaalpost,BoekDatum,JpIsInGebruik)
             select @@BoekGangGid,@BjGid,@DgbGidValuta,@BoekStukNummer,@HerwaarderingTekst,BeginDatum,1
             from tabPeriode where PerBjGid=@BjGid and Pernr=@KoersCorrPerNr;
          set @CorrJpGid = @@JpGid;
        end if;

        call  KoerswijzigingsBoekingen( @BjGid, @JpPernr, @KoersCorrPerNr, @HerwJpGid, @CorrJpGid, @ValNummer, _P(@HerwaardParameterTekst, @Oms), _P(@HerwaardParameterTekst, @InvOms), 1);

        // *** Einde koerswijzigingsregels ***

        //Neem journaalposten weer uit gebruik
        update tabJournaalPost set JpIsInGebruik=0 where JpGid=@HerwJpGid;
        if @CorrJpGid is not null then
          update tabJournaalPost set JpIsInGebruik=0 where JpGid=@CorrJpGid;
        end if;

        set @@IgnoreProgressAdd = @BufIgnoreProgressAdd;

      end if;
    end if;

    set @VorigeValNummer = @ValNummer; //bufferen om niet alles opnieuw op te vragen
  end loop defloopje1;
  close cursor_KoersenVoorDefinitieveBoekingsgangen;

  //Definitieve boekingsgang afsluiten
  if @MaakBoekingen = 1 then
    call ProgressSet(null, null, _U('Herwaarderen (afsluiten boekingsgang)'));
    update tabBoekingsGang set BoekGangInGebruik=0 where BoekGangGid=@@BoekGangGid;
  end if;

  //Meta-instellingen terugzetten
  set @@TijdelijkeKoersen  = 0;
  set @@GeenKoersCorrectie = 0;

  //Gebufferde gegevens terugzetten
  set @@boekganggid = @BufferBoekgangGid;
  set @@JpGid       = @bufferjpgid;

  //We zijn klaar met de procesgang
  call ProgressDelete;

  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;

  //call TraceEind('ValutaHerberekenen');
end;


//$Workfile: ValutaKoers.sp $ $Revision: 3 $ $Modtime: 14-04-08 6:48 $'

//----------- Geef de koers van een valuta in een bepaalde periode (wordt altijd omgerekend per 1)
if exists (select 1 from sys.sysProcedure where proc_name='ValutaKoers') then
  drop function ValutaKoers;
end if;

create function ValutaKoers (in @BjGid integer, in @Pernr integer, in @Valnr integer)
returns double
begin
  declare @ResKoers double;

  set @@ErrorTextProcedure = 'ValutaKoers > @BjGid='+string(@BjGid)+', @Pernr='+string(@Pernr)+', @Valnr='+string(@Valnr);
  //call TraceBegin(@@ErrorTextProcedure);

  select(Koers/KrsEenheid) into @ResKoers from tabValutaKoers
  where ValBjGid=@BjGid and ValPernr=@Pernr and KrsValnummer=@Valnr;

  set @@ErrorTextProcedure = 'ValutaKoers > Koers='+string(IsNull(@ResKoers,1));
  //call TraceEind(@@ErrorTextProcedure);
  return (IsNull(@ResKoers,1));

end;


create or replace function ValutaOmrekenen(in @VanValNummer integer, in @Bedrag double, in @NaarValnummer integer, in @BjGid integer, in @Pernr integer, in @AantalDecimalen smallint)
returns double
begin
  declare @VanKoers      double;
  declare @NaarKoers     double;
  declare @VanEuroKoers  double;
  declare @NaarEuroKoers double;
  declare @ValutaBedrag  double;

  //call TraceBegin('ValutaOmrekenen > @VanValNummer = ' + string(@VanValNummer) + ', @NaarValnummer = ' + string(@NaarValnummer) + ', @Bedrag = ' + string(@Bedrag) + ', @BjGid = ' + string(@BjGid) + ', @Pernr = ' + string(@Pernr) + ', @AantalDecimalen = ' + string(@AantalDecimalen));

  set @Bedrag = round(@Bedrag, @AantalDecimalen);
  if @VanValNummer = @NaarValNummer or @Bedrag = 0 then
    //call Trace('ValutaOmrekenen > VAN EN NAAR VALUTA IS GELIJK OF BEDRAG IS 0!!!! DIT KAN GEOPTIMALISEERD WORDEN');
    set @ValutaBedrag=@Bedrag
  else
    if @@TijdelijkeKoersen = 1 then
      //call Trace('ValutaOmrekenen > Tijdelijkekoersen');
      select HlpKrsKoersTovEuro, HlpKrsKoers/HlpKrsEenheid into @VanEuroKoers, @VanKoers from tabHulpKoers where HlpKrsValNummer=@VanValNummer and HlpKrsBjGid=@BjGid and HlpKrsPerNr=@Pernr;

      if @VanKoers is null then
        select KrsKoersTovEuro, Koers/KrsEenheid into @VanEuroKoers, @VanKoers from tabValutaKoers where KrsValnummer=@VanValNummer  and ValBjGid=@BjGid and ValPernr=@Pernr;
      end if;
      if @VanValNummer  = @@BasisValutaNummer then
        set @VanKoers = 1;
      end if;

      select HlpKrsKoersTovEuro, HlpKrsKoers/HlpKrsEenheid into @NaarEuroKoers, @NaarKoers from tabHulpKoers where HlpKrsValNummer=@NaarValNummer and HlpKrsBjGid=@BjGid and HlpKrsPerNr=@Pernr;
      if @@EuroValutaNummer is null then
        set @NaarEuroKoers = null;
        set @VanEuroKoers  = null;
      end if;
      if @NaarKoers is null then
        select KrsKoersTovEuro, Koers/KrsEenheid into @NaarEuroKoers, @NaarKoers from tabValutaKoers where KrsValnummer=@NaarValNummer  and ValBjGid=@BjGid and ValPernr=@Pernr;
      end if;
      if @NaarValNummer  = @@BasisValutaNummer then
        set @NaarKoers = 1;
      end if;

      if isnull( @VanEuroKoers, 0 ) <> 0 and isnull( @NaarEuroKoers, 0 ) <> 0 then
        set @ValutaBedrag = (@Bedrag * @NaarEuroKoers / @VanEuroKoers);
      else
        set @ValutaBedrag = (@Bedrag * @VanKoers / @NaarKoers);
      end if;
    else
      //call Trace('ValutaOmrekenen > Geen tijdelijkekoersen');
      if @BjGid is null or @PerNr is null then
        call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid, @PerNr);
      end if;
      if @@EuroValutaNummer is not null then
        //Misschien de eurokoersen gebruiken? -> Altijd de eurokoers gebruiken als die is ingevuld!!
        //if not exists(select 1 from tabValuta where (ValNummer=@VanValNummer or ValNummer=@NaarValNummer) and NaarEuro=0) then
          //Alleen indien beide valutas een 'naar euro' vinkje hebben, anders negeren en van de gewone koersen uitgaan
          select KrsKoersTovEuro into @VanKoers    from tabValutaKoers where KrsValnummer=@VanValNummer  and ValBjGid=@BjGid and ValPernr=@Pernr;
          if IsNull(@VanKoers,0) <> 0 then
            select KrsKoersTovEuro into @NaarKoers from tabValutaKoers where krsValnummer=@NaarValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
          end if;
        //end if;
      end if;
      //call Trace('ValutaOmrekenen > @VanKoers = ' + string(@VanKoers) + ', @NaarKoers = ' +string(@NaarKoers) + ', @Bedrag = ' + string(@Bedrag));
      if IsNull(@VanKoers,0) <> 0 and IsNull(@NaarKoers,0) <> 0 then      //Eurokoersen
        set @ValutaBedrag = (@Bedrag * @NaarKoers / @VanKoers);
      else
        if @VanValNummer = @@BasisValutaNummer then
          //call Trace('ValutaOmrekenen > @VanValNummer = @@BasisValutaNummer');
          select if KrsKoersTovEuro is not null then @Bedrag*KrsKoersTovEuro/KrsEenheid else @Bedrag/Koers*KrsEenheid endif into @ValutaBedrag from tabValutaKoers where KrsValnummer=@NaarValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
        else
          if @NaarValNummer = @@BasisValutaNummer then
            //call Trace('ValutaOmrekenen > @NaarValNummer = @@BasisValutaNummer');
            select if KrsKoersTovEuro is not null then @Bedrag/KrsKoersTovEuro/KrsEenheid else @Bedrag/KrsEenheid * Koers endif into @ValutaBedrag from tabValutaKoers where KrsValnummer=@VanValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
          else
            //call Trace('ValutaOmrekenen > @VanValNummer en @NaarValNummer <> @@BasisValutaNummer');
            select if KrsKoersTovEuro is not null then (1/KrsKoersTovEuro)*KrsEenheid else Koers/KrsEenheid endif into @VanKoers from tabValutaKoers where KrsValnummer=@VanValNummer  and ValBjGid=@BjGid and ValPernr=@Pernr;
            select if KrsKoersTovEuro is not null then KrsKoersTovEuro/KrsEenheid else Koers/KrsEenheid endif into @NaarKoers from tabValutaKoers where KrsValnummer=@NaarValNummer and ValBjGid=@BjGid and ValPernr=@Pernr;
            set @ValutaBedrag = (@Bedrag * @VanKoers / @NaarKoers);
          end if;
        end if;
      end if;
    end if;
  end if;
  set @ValutaBedrag = round(@ValutaBedrag, @AantalDecimalen);

  //call TraceEind('ValutaOmrekenen > @ValutaBedrag = ' + string(@ValutaBedrag));

  return(@ValutaBedrag);
end;


create or replace function ValutaOmrekenenAfgerond(@VanValNummer integer, @Bedrag numeric(15,2), @NaarValnummer integer, @BjGid integer, @Datum date, @Periode integer)
returns numeric(15,2)
begin
  //---------- OUDE PROCEDURES, DEZE NIET MEER GEBRUIKEN --------------
  declare @ResultBedrag numeric(15,2);

  //call TraceBegin('ValutaOmrekenenAfgerond > @VanValNummer = ' + string(@VanValNummer) + ', @Bedrag = ' + string(@Bedrag) + ', @NaarValnummer = ' + string(@NaarValnummer) + ', @BjGid = ' + string(@BjGid) + ', @Periode = ' + string(@Periode));
  //call Trace('ValutaOmrekenenAfgerond > OUDE PROCEDURES, DEZE NIET MEER GEBRUIKEN');

  call ValutaBedragOmrekenenAfgerond(@VanValNummer, @Bedrag, @NaarValnummer, @BjGid, @Datum, @Periode, @ResultBedrag);

  //call TraceEind('ValutaOmrekenenAfgerond > @ResultBedrag = ' + string(@ResultBedrag));
  return(@ResultBedrag);
end;


//$Workfile: ValutaOmrekenenProc.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//------------ Bereken bedrag om naar een andere valuta via functie 'ValutaOmrekenen'
if exists (select 1 from sys.sysProcedure where proc_name='ValutaOmrekenenProc') then
  drop procedure ValutaOmrekenenProc;
end if;

create procedure ValutaOmrekenenProc(in @VanValNummer integer, in @Bedrag double, in @NaarValnummer integer, in @BjGid integer, in @Datum date, in @Pernr integer, in @DgbGid integer, in @AantalDecimalen smallint, out @ValutaBedrag double)
begin
  declare @DgbExists smallint;

  //call traceBegin ('ValutaOmrekenenProc (VanValNummer='+string(@VanValNummer)+', @Bedrag='+string(@Bedrag)+', @NaarValnummer='+string(@NaarValnummer)+', @BjGid='+string(@BjGid)+', @Datum='+string(@Datum)+', @Pernr='+string(@Pernr)+')');

  set @Bedrag = round(@Bedrag, @AantalDecimalen);
  if (@VanValNummer=@NaarValNummer) or (@VanValNummer is null and @NaarValNummer is null) or @Bedrag=0 then
    set @ValutaBedrag = @Bedrag;
  else
    if @Datum is not null then
      call BepaalBoekjaarEnPeriode(@Datum, @BjGid, @PerNr);
    else
      if @BjGid is null or @PerNr is null then
        call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @BjGid, @PerNr);
      end if;
    end if;

    if @DgbGid is not null then
      set @DgbExists=0;
      select 1 into @DgbExists from tabDagboek where DgbGid=@DgbGid and Dagboeksoort=5;
      if @DgbExists=1 then
        set @PerNr=0;
      end if;
    end if;
    select ValutaOmrekenen(@VanValNummer, @Bedrag, @NaarValnummer, @BjGid, @Pernr, @AantalDecimalen) into @ValutaBedrag;
  end if;
  set @ValutaBedrag = round(@ValutaBedrag, @AantalDecimalen);

  //call traceEind ('ValutaOmrekenenProc ------> @ValutaBedrag='+string(@ValutaBedrag));

end;


create or replace procedure VasteGegNawDocumentenOvernemen(in @NawGid integer, in @FonGid integer)
begin
  declare @fonEmailGebruikenVan integer;

  set @@ErrorTextProcedure = 'VasteGegNawDocumentenOvernemen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@NawGid = ' + string(@NawGid) + ', @FonGid = ' + string(@FonGid));

  delete tabNawDocument where NawDocNawGid = @NawGid;//voor de zekerheid, deze proc zal alleen aangeroepen worden bij nieuwe naw, dan zijn er geen bestaande records.

  //MR 25-jul-2007 Bug #26482: fonEmailGebruikenVan toegevoegd welke uit de vaste gegevens van de naw komt ipv de documenten. Alleen als regelsoort boven de 1 ligt (geen papier)
  select fonEmailGebruikenVan into @fonEmailGebruikenVan from tabFileOfNaw where FonGid = @FonGid;

  insert into tabNawDocument ( NawDocAfdrukVoorwaarde,  NawDocDocSoort, NawDocEmailTo, NawDocIsAfdrukNaarPapier,
                               NawDocNawGid, NawDocRapGidExclBTW,  NawDocRapGidInclBTW,  NawDocRdfGid,
                               NawDocRegelSoort )
  select                       NawVastDocAfdrukVoorwaarde, NawVastDocDocSoort,  (if NawVastDocRegelSoort > 1 then @fonEmailGebruikenVan else NawVastDocEmailTo endif),
                               NawVastDocIsAfdrukNaarPapier,
                               @NawGid, NawVastDocRapGidExclBTW,  NawVastDocRapGidInclBTW, NawVastDocRdfGid,
                               NawVastDocRegelSoort
  from tabNawVasteGegevensDocument where NawVastDocFonGid = @FonGid;

  set @@ErrorTextProcedure = 'VasteGegNawDocumentenOvernemen';
  //call TraceEind(@@ErrorTextProcedure);
end;

//$Workfile: VaststellenProjectBegroting.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----------------------------------------------------------------------------------------------------
//------------------------ VASTSTELLEN BEGROTING PROJECT ---------------------------------------------
//----------------------------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='VaststellenProjectBegroting') then
  drop procedure VaststellenProjectBegroting;
end if;

create procedure VaststellenProjectBegroting(in @PbGid integer)
begin
  set @@ErrorTextProcedure = 'VaststellenProjectBegroting > @PbGid='+String(@PbGid);
  //call traceBegin(@@ErrorTextProcedure);

  update tabProjectVoorcalculatie
  set    PvcVastgesteldBegrootBedrag = PvcKostprijsRegelTotaal,
         PvcVastgesteldBudAantal     = PvcBudAantal
  where  PvcPbGid = @PbGid;

  update tabProjectVoorcalculatie
  set    PvcVastgesteldBegrootBedrag = PvcKostprijsRegelTotaal,
         PvcVastgesteldBudAantal     = PvcBudAantal
  where  PvcPbGid in (select PbpPbgid
                      from   tabProjectBoompad
                      where  PbpParentPbGid = @PbGid);

  set @@ErrorTextProcedure = 'VaststellenProjectBegroting';
  //call traceEind(@@ErrorTextProcedure);


end;


//$Workfile: VaststellenProjectOfferte.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----------------------------------------------------------------------------------------------------
//------------------------ VASTSTELLEN OFFERTE PROJECT -----------------------------------------------
//----------------------------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='VaststellenProjectOfferte') then
  drop procedure VaststellenProjectOfferte;
end if;

create procedure VaststellenProjectOfferte(in @PbGid integer)
begin
  set @@ErrorTextProcedure = 'VaststellenProjectOfferte > @PbGid='+String(@PbGid);
  //call traceBegin(@@ErrorTextProcedure);

  // Projectonderdeelregels bijwerken
  update tabProjectBoom
  set    PbUitsplitsenVastgesteld     = PbUitsplitsen,
         PbBtwCodeVastgesteld         = PbBtwCodeAfwijkend,
         PbOfferteBedragVastgesteld   = PbOfferteBedragAfwijkend,
         PbIsOfferteBedragVastgesteld = PbIsOfferteBedragAfwijkend,
         PbOfferteTekstVastgesteld    = PbOfferteTekstAfwijkend,
         PbIsOfferteTekstVastgesteld  = PbIsOfferteTekstAfwijkend
  where  PbGid = @PbGid;

  update tabProjectBoom
  set    PbUitsplitsenVastgesteld     = PbUitsplitsen,
         PbBtwCodeVastgesteld         = PbBtwCodeAfwijkend,
         PbOfferteBedragVastgesteld   = PbOfferteBedragAfwijkend,
         PbIsOfferteBedragVastgesteld = PbIsOfferteBedragAfwijkend,
         PbOfferteTekstVastgesteld    = PbOfferteTekstAfwijkend,
         PbIsOfferteTekstVastgesteld  = PbIsOfferteTekstAfwijkend
  where  PbGid in (select PbpPbgid
                   from   tabProjectBoompad
                   where  PbpParentPbGid = @PbGid);

  // Voorcalculatieregels bijwerken
  update tabProjectVoorcalculatie
  set    PvcVastgesteldOfferteBedrag = PvcOfferteBedrag,
         PvcVastgesteldOffAantal     = PvcOffAantal,
         PvcVastgesteldOmschr        = PvcOmschr
  where  PvcPbGid = @PbGid;

  update tabProjectVoorcalculatie
  set    PvcVastgesteldOfferteBedrag = PvcOfferteBedrag,
         PvcVastgesteldOffAantal     = PvcOffAantal,
         PvcVastgesteldOmschr        = PvcOmschr
  where  PvcPbGid in (select PbpPbgid
                      from   tabProjectBoompad
                      where  PbpParentPbGid = @PbGid);

  set @@ErrorTextProcedure = 'VaststellenProjectOfferte';
  //call traceEind(@@ErrorTextProcedure);


end;


create or replace procedure VCAanmakenmMeerdereArtikelLocaties(
  in @MagazijnNummer integer
)
//----------------------------------------------------
//------- AANMAKEN MEERDERE ARTIKEL LOCATIES ---------
//----------------------------------------------------
begin
  declare @ArtLocGid    integer;
  declare @vrcArtGid    integer;
  declare @vrcLocGid    integer;
  declare @vrcNweLocGid integer;
  declare @vrcArtLocGid integer;
  declare @vrcMagGid    integer;
//declare @vrcGid       integer; //voor de trace call

  //call TraceBegin('VCAanmakenmMeerdereArtikelLocaties');

  DECLARE cur_VC CURSOR FOR
    SELECT vrcArtGid, vrcLocGid, vrcNweLocGid, vrcArtLocGid, vrcMagGid //, vrcGid
    FROM tabVoorraadCorrectie
    JOIN tabLocatie ON (vrcLocGid=LocGid)
    WHERE LocMagGid = @MagazijnNummer;


    OPEN cur_VC;
    loopje1:
    LOOP
      FETCH NEXT cur_VC INTO @vrcArtGid, @vrcLocGid, @vrcNweLocGid, @vrcArtLocGid, @vrcMagGid; //, @vrcGid;
      //als ie dit heeft bereikt (hetzelfde voor alle loopjes in king) dan is ie klaar en kan ie eruit springen
      if sqlstate = '02000' then
        leave loopje1;
      end if;

      if @vrcMagGid = @MagazijnNummer then
      BEGIN

        if @vrcNweLocGid Is Null then
          //er is geen nieuwe locatie gekozen, dus artloc met OUDE LOCATIE aanmaken of aanpassen
          begin
            //lock mutex MutArtikelLocatie;
            if not exists(select 1 from tabArtikelLocatie
                                   left outer join tabLocatie on (ArtLocLocGid=LocGid)
                                   where ((ArtLocArtGid = @vrcArtGid) and (LocMagGid = @MagazijnNummer)))then
              //er was nog geen ArtLocGid met dit artikel: aanmaken en de oude locatie erin zetten
                insert into tabArtikelLocatie (ArtLocArtGid, ArtLocLocGid)
                                       values (@vrcArtGid,   @vrcLocGid);
            else
              begin
                //er bestond al een ArtLocGid met dit artikel: de locatie ervan eventueel vervangen
                update tabArtikelLocatie
                left outer join tabLocatie on (ArtLocLocGid = LocGid)
                set    ArtLocLocGid = @vrcLocGid
                where (ArtLocArtGid = @vrcArtGid) and (LocMagGid = @MagazijnNummer);
              end;
            end if;
            //de betreffende ArtLocGid in tabVoorraadCorrectie zetten
            select ArtLocGid into @ArtLocGid from tabArtikelLocatie where (ArtLocArtGid = @vrcArtGid) and (ArtLocLocGid = @vrcLocGid);
            // Een transactie-mutex mag niet worden gereleased binnen een transactie
            //release mutex MutArtikelLocatie;
          end;
        else
          //artloc met de NIEUWE LOCATIE maken
          begin
            //kijken of artikel + magazijnnummer al voorkomen in tabArtikelLocatie
            //lock mutex MutArtikelLocatie;
            if not exists(select 1 from tabArtikelLocatie
                                   left outer join tabLocatie on (ArtLocLocGid=LocGid)
                                   where (ArtLocArtGid = @vrcArtGid) and (LocMagGid = @MagazijnNummer)) then
              begin
                insert into tabArtikelLocatie (ArtLocArtGid, ArtLocLocGid)
                                       values (@vrcArtGid,   @vrcNweLocGid);
              end
            else
              //als er wel een artlocgid bestond met dit artikel, oude loc door nieuwe vervangen
              begin
                update tabArtikelLocatie
                left outer join tabLocatie on (ArtLocLocGid=LocGid)
                set    ArtLocLocGid = @vrcNweLocGid
                where (ArtLocArtGid = @vrcArtGid) and (LocMagGid = @MagazijnNummer);
              end;
            end if;
            //de betreffende ArtLocGid in tabVoorraadCorrectie zetten
            select ArtLocGid into @ArtLocGid
            from tabArtikelLocatie
            left outer join tabLocatie on (ArtLocLocGid = LocGid)
            where (ArtLocArtGid = @vrcArtGid) and (ArtLocLocGid = @vrcNweLocGid) and (LocMagGid = @MagazijnNummer);
            //Een transactie-mutex mag niet worden gereleased binnen een transactie
            //release mutex MutArtikelLocatie;
          end;

        end if;  //if @vrcNweLocGid Is Null then
       end;

      END IF; //if @vrcMagGid = @MagazijnNummer then
    END LOOP loopje1;
  CLOSE cur_VC;


  //call TraceEind('VCAanmakenmMeerdereArtikelLocaties');

end;


//$Workfile: VCArtikelLocatieVervangen.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//------------------------------------------------------------------------------
//-------------- VOORRAADCORRECTIES: ARTIKEL LOCATIE VERVANGEN------------------
//------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='VCArtikelLocatieVervangen') then
  drop function VCArtikelLocatieVervangen;
end if;

create function VCArtikelLocatieVervangen(in @ArtGid integer,
                                          in @LocGid integer,
                                          in @OudeArtLocGid integer)
  returns integer
begin
  declare @NieuweArtLocGid integer;
  //call TraceBegin('VCArtikelLocatieVervangen');

  // 1. Nieuwe artikellocatie aanmaken
  // 2. Alle serienummers zoeken die gekoppeld zijn aan oude artikellocatie  -> dit komt pas later, als dat serienr spul gemaakt is in de db
  // 3. Bij die serienummers de oude artloc vervangen door je nieuwe artloc
  // 4. De voorraadcorectie met de oude artloc -> die vervangen door de nieuwe artloc. Als er geen OudeArtLoc was, dan nieuw VCrecord invoeren
  // 5. Mocht in de toekomst ooit de sleutel ArtLoc nog in een andere tabel voorkomen, daar ook de oude artloc door de nieuwe vervangen
  // 6. Nu zijn alle referenties in andere tabellen naar de oude ArtLoc weg, dus kan hij gedelete worden. - als hij überhaupt een oude artloc had

  // 1.
  if not exists(select 1 from tabArtikelLocatie where ArtLocArtGid = @ArtGid and ArtLocLocGid=@LocGid)  then
    insert into tabArtikelLocatie (ArtLocArtGid, ArtLocLocGid)
                           values (@ArtGid,      @LocGid);
  end if;

  select ArtLocGid into @NieuweArtLocGid from tabArtikelLocatie where (ArtLocArtGid = @ArtGid) and (ArtLocLocGid=@LocGid);


  // 2.
  // 3.

  // 4.
  if @OudeArtLocGid > 0 then
    update tabVoorraadCorrectie
    set    vrcArtLocGid = @NieuweArtLocGid
    where  vrcArtLocGid = @OudeArtLocGid
  end if;

  // 5.

  // 6.
  if @OudeArtLocGid > 0 then
    delete from tabArtikelLocatie
    where       ArtLocGid = @OudeArtLocGid
  end if
  ;

  return @NieuweArtLocGid;

  //call TraceEind('VCArtikelLocatieVervangen');

end;


//-------------------------------------------------------------------------------------------
//---------- VOORRAADCORRECTIES / Delete / Alle zichtbare artikelen op alle locaties ----------------------
//-------------------------------------------------------------------------------------------
create or replace procedure VCDeleteAlleArtAlleLoc(in @iSelecteerOp integer,
                                        in @iExtraSelectie integer,
                                        in @sVan nchar(80),
                                        in @sTot nchar(80),
                                        in @MagazijnNummer integer
                                       )
  //@iSelecteerOp = 1 = artCode                            //@iExtraSelectie = 1 = toon alles
  //@iSelecteerOp = 2 = artZoekcode                        //@iExtraSelectie = 2 = toon alleen die met voorraadcorrecties (dus met een vrcGid)
  //@iSelecteerOp = 3 = leverancier  =   NawFilNummer      //@iExtraSelectie = 3 = toon alleen met voorraad > 0
  //@iSelecteerOp = 4 = opbrengsgroep                      //@iExtraSelectie = 4 = toon alleen met voorraad = 0
  //@iSelecteerOp = 5 = locatie                            //@iExtraSelectie = 5 = toon alleen met voorraad < 0

begin
  //call TraceBegin( 'VCDeleteAlleArtAlleLoc');
  begin
  delete from tabVoorraadCorrectie
  where tabvoorraadcorrectie.VrcGid in(select abc.VrcGid
                                       from tabVoorraadCorrectie abc inner join tabArtikel on vrcArtGid=ArtGid inner join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGid)
                                       left outer join (tabartikelleverancier inner join tabnaw on (NawGid = ArtLevNawGid) inner join tabNawFile on (NawFilNawGid = NawGid)
                                       inner join tabAdres on (AdrGid  = NawGidVestiging))
                                       left outer join tabLocatie on vrcLocGid=LocGid and (LocMagGid = 1)
                                       left outer join tabArtikelLocatie on (vrcArtGid=ArtLocArtGid) and (vrcLocGid=ArtLocLocGid)
                                       where (((@iSelecteerOp = 1) and (ArtCode       between @sVan and @sTot))  or
                                              ((@iSelecteerOp = 2) and (left(ArtZoekcode + Replicate(' ', 40), 40)+ArtCode between @sVan and @sTot)) or
                                              ((@iSelecteerOp = 3) and (NawFilNummer  between @sVan and @sTot))  or
                                              ((@iSelecteerOp = 4) and (OpbrGrpNummer between @sVan and @sTot))  or
                                              ((@iSelecteerOp = 5) and (LocNaam       between @sVan and @sTot))) AND
                                             ( (@iExtraSelectie = 1) or
                                              ((@iExtraSelectie = 2) and (VrcGid is not null))            or
                                              ((@iExtraSelectie = 3) and (IsNull(artLocVoorraad,0) > 0) ) or
                                              ((@iExtraSelectie = 4) and (IsNull(artLocVoorraad,0) = 0) ) or
                                              ((@iExtraSelectie = 5) and (IsNull(artLocVoorraad,0) < 0) )))      AND
                                             (  vrcMagGid = @MagazijnNummer)
                                       end;

  //call TraceEind( 'VCDeleteAlleArtAlleLoc');


end;


