//$Workfile: VCUpdate.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//----------------------------------------------------
//---------- VOORRAADCORRECTIES / Update -------------
//----------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='VCUpdate') then
  drop function VCUpdate;
end if;

create function VCUpdate(in @VrcArtLocGid integer,
                         in @VrcArtGid integer,
                         in @VrcLocGid integer,
                         in @VrcVerandering numeric(15,3),
                         in @VrcAbs smallint,
                         in @VrcNweLocGid integer,
                         in @VrcMagGid integer,
                         in @MeerdereMagazijnen integer
                        )
returns integer
begin
  declare @vrcGid integer;

  //call TraceBegin( 'VCUpdate(@VrcArtLocGid='+string(@VrcArtLocGid)+', @VrcArtGid='+string(@VrcArtGid)+', @VrcLocGid='+string(@VrcLocGid)+', @VrcVerandering='+string(@VrcVerandering)+', @VrcAbs='+string(@VrcAbs)+', @VrcNweLocGid='+string(@VrcNweLocGid)+', @MeerdereMagazijnen='+string(@MeerdereMagazijnen)+')');
  if exists(select 1 from tabVoorraadCorrectie where (VrcArtGid = @VrcArtGid) and (VrcLocGid = @VrcLocGid) ) then
    update  tabVoorraadCorrectie
    set     VrcArtGid      = @VrcArtGid,
            VrcLocGid      = @VrcLocGid,
            VrcVerandering = @VrcVerandering,
            VrcAbs         = @VrcAbs,
            VrcNweLocGid   = if @MeerdereMagazijnen = 0 then @VrcNweLocGid else null endif
    where  (VrcArtGid = @VrcArtGid) and (VrcLocGid = @VrcLocGid);
  else
    insert into tabVoorraadCorrectie ( VrcArtGid,  VrcLocGid,  VrcVerandering,  VrcAbs,  VrcNweLocGid,  VrcMagGid)
                              values (@VrcArtGid, @VrcLocGid, @VrcVerandering, @VrcAbs, @VrcNweLocGid, @VrcMagGid);
  end if;

  //call TraceEind('Einde VCUpdate');


end;


//-------------------------------------------------------------------------------------------
//---VOORRAADCORRECTIES / Update / Nul stellen alle artikelen op alle weergegeven locaties---
//-------------------------------------------------------------------------------------------
create or replace procedure VCUpdateNulAlleArtAlleLoc(in @iSelecteerOp integer,
                                           in @iExtraSelectie integer,
                                           in @sVan nchar(80),
                                           in @sTot nchar(80),
                                           in @MeerdereMagazijnen smallint,
                                           in @MagazijnNummer integer
                                           )
begin
  //call TraceBegin( 'VCUpdateNulAlleArtAlleLoc()');

  //@iSelecteerOp = 1 = artCode                          //@iExtraSelectie = 1 = toon alles
  //@iSelecteerOp = 2 = artZoekcode                      //@iExtraSelectie = 2 = toon alleen die met voorraadcorrecties (dus met een vrcGid)
  //@iSelecteerOp = 3 = leverancier  =  NawFilNummer     //@iExtraSelectie = 3 = toon alleen met voorraad > 0
  //@iSelecteerOp = 4 = opbrengsgroep                    //@iExtraSelectie = 4 = toon alleen met voorraad = 0
  //@iSelecteerOp = 5 = locatie                          //@iExtraSelectie = 5 = toon alleen met voorraad < 0

  //Voorraadcorrecties doorlopen. Als er een bijbehorende ArtLoc is, kijken wat de ArtLocVoorraad is.
  //Als deze Null was, (of er was geen ArtLoc) dan wordt de verandering null, anders 0-ArtLocVoorraad.
  update tabVoorraadCorrectie
  set    vrcVerandering = if ArtLocVoorraad Is Null then null else (0 - ArtLocVoorraad) endif,
         vrcAbs         = 0
  from tabVoorraadCorrectie abc inner join tabArtikel on vrcArtGid=ArtGid inner join tabOpbrengstgroep on (OpbrGrpGid = ArtOpbrGrpGid)
  left outer join (tabartikelleverancier inner join tabnaw on (NawGid = ArtLevNawGid) inner join tabNawFile on (NawFilNawGid = NawGid)
  inner join tabAdres on (AdrGid  = NawGidVestiging))
  left outer join tabLocatie on vrcLocGid=LocGid and (LocMagGid = @MagazijnNummer)
  left outer join tabArtikelLocatie on (vrcArtGid=ArtLocArtGid) and (vrcLocGid=ArtLocLocGid)
  where (((@iSelecteerOp = 1) and (ArtCode       between @sVan and @sTot))  or
         ((@iSelecteerOp = 2) and (left(ArtZoekcode + Replicate(' ', 40), 40)+ArtCode between @sVan and @sTot)) or
         ((@iSelecteerOp = 3) and (NawFilNummer  between @sVan and @sTot))  or
         ((@iSelecteerOp = 4) and (OpbrGrpNummer between @sVan and @sTot))  or
         ((@iSelecteerOp = 5) and (LocNaam       between @sVan and @sTot))) AND
        ( (@iExtraSelectie = 1) or
         ((@iExtraSelectie = 2) and (VrcGid is not null))            or
         ((@iExtraSelectie = 3) and (IsNull(artLocVoorraad,0) > 0) ) or
         ((@iExtraSelectie = 4) and (IsNull(artLocVoorraad,0) = 0) ) or
         ((@iExtraSelectie = 5) and (IsNull(artLocVoorraad,0) < 0) ))       AND
        (  vrcMagGid = @MagazijnNummer);

  //call TraceEind( 'VCUpdateNulAlleArtAlleLoc');

end;


//$Workfile: VCUpdateNulDitArtAlleLoc.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//-------------------------------------------------------------------------------------------
//---------- VOORRAADCORRECTIES / Update / Nul stellen dit artikel op alle locaties ---------
//-------------------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='VCUpdateNulDitArtAlleLoc') then
  drop procedure VCUpdateNulDitArtAlleLoc;
end if;

create procedure VCUpdateNulDitArtAlleLoc(in @VrcArtGid integer)
begin
  //call TraceBegin( 'VCUpdateNulDitArtAlleLoc(@VrcArtGid='+string(@VrcArtGid)+')');

  //call Trace( 'Delete tabVoorraadCorrectie');
  delete from tabVoorraadCorrectie where (VrcArtGid = @VrcArtGid);

  //call Trace( 'Insert tabVoorraadCorrectie');
  insert into tabVoorraadCorrectie (VrcArtGid, vrcLocGid, vrcArtLocGid, vrcAbs, VrcVerandering)
    select ArtLocArtGid, ArtLocLocGid, ArtLocGid, 0, (0-ArtLocVoorraad)
    from  tabArtikelLocatie
    where (ArtLocArtGid=@VrcArtGid)
    and   (ArtLocVoorraad <> 0);

  //call TraceEind( 'VCUpdateNulDitArtAlleLoc');

end;


//$Workfile: VCUpdateNulDitArtDezeLoc.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

//-------------------------------------------------------------------------------------------
//---------- VOORRAADCORRECTIES / Update / Nul stellen dit artikel op deze locatie ----------
//-------------------------------------------------------------------------------------------
if exists (select 1 from sys.sysProcedure where proc_name='VCUpdateNulDitArtDezeLoc') then
  drop procedure VCUpdateNulDitArtDezeLoc;
end if;

create procedure VCUpdateNulDitArtDezeLoc(in @VrcArtGid integer,
                                          in @VrcLocGid integer,
                                          in @OudeMagVr numeric(15,3),
                                          in @MagazijnNummer integer)
begin
  //call TraceBegin( 'VCUpdateNulDitArtDezeLoc(@VrcArtGid='+string(@VrcArtGid)+', @MagazijnNummer='+string(@MagazijnNummer)+', @OudeMagVr='+string(@OudeMagVr)+')');

  if exists(select 1 from tabVoorraadCorrectie where (VrcArtGid = @VrcArtGid) and (vrcMagGid = @MagazijnNummer) ) then
    begin

      //als de oude mag voorraad = 0 dan het voorraadcorrectie-record weggooien, anders updaten en v.verschil op 0 zetten en nieuwe magvoorraad berekenen
      if @OudeMagVr = 0 then
        begin
          delete from tabVoorraadCorrectie
          where (VrcArtGid = @VrcArtGid) and (VrcMagGid = @MagazijnNummer)
        end
      else
        begin
          update  tabVoorraadCorrectie
          set     VrcArtGid      = @VrcArtGid,
                  VrcMagGid      = @MagazijnNummer,
                  VrcVerandering = 0 - @OudeMagVr,
                  VrcAbs         = 0
          where  (VrcArtGid = @VrcArtGid)
          and    (VrcMagGid = @MagazijnNummer);
        end;
      end if;

    end;
  else
    begin
      //er bestond geen VCrecord met dit artikel en dit magazijn: dus nieuwe maken
      if not (@OudeMagVr Is null) and not (@OudeMagVr = 0) then
        insert into tabVoorraadCorrectie(vrcArtGid, vrcLocGid, vrcMagGid, vrcVerandering, vrcAbs)
        values(@VrcArtGid, @VrcLocGid, @MagazijnNummer, 0 - @OudeMagVr, 0);
      end if;
    end;

  end if;
  //call TraceEind( 'VCUpdateNulDitArtDezeLoc');

end;



create or replace procedure VerbijzonderenKostensoorten(in @BjGid integer, in @VanRksInvoer nchar(28), in @TotRksInvoer nchar(28),
                                             in @VanPernr integer, in @TotPernr integer, in @DgbCode nchar(10),
                                             in @Boekstuknummer numeric(10,0), in @BoekDatum date, in @BoekenInPeriode integer,
                                             out @BoekgangGid integer, out @RksGeblokkeerd integer)
begin
  declare @HuidigRksInvoer nchar(28);
  declare @VorigRksInvoer  nchar(28);
  declare @RksGid          integer;
  declare @VorigePeriode   integer;
  declare @Periode         integer;

  set @@ErrorTextProcedure = 'VerbijzonderenKostensoorten > ';
  //call TraceBegin(@@ErrorTextProcedure + '@bjgid = ' + string(@bjgid) + ', @VanRksInvoer = ' + @VanRksInvoer + ', @TotRksInvoer = ' + @TotRksInvoer + ', @VanPerNr = ' + string(@VanPerNr) + ', @TotPerNr = ' + string(@TotPerNr) + ', @DgbCode = ' + @DgbCode + ', @Boekstuknummer = ' + string(@Boekstuknummer) + ', @BoekDatum = ' + string(@BoekDatum) + ', @BoekenInPeriode = ' + string(@BoekenInPeriode));

  insert into tabBoekingsGang(BoekGangBjGid, BoekgangBronId, BoekGangInGebruik, IsBoekGangDefinitief)
  values(@BjGid, 8, 1, 0);

  //Resultaatwaarde onthouden
  set @BoekgangGid = @@Identity;

  //Vullen van de van/t/m velden
  if isnull(@VanRksInvoer,'') = '' then
    select first RksGid into @VanRksInvoer from tabKostenSoortVerdeling inner join tabRekeningschema on (RksGid = KostVerdRksGID) order by RksInvoer;
  end if;

  if isnull(@TotRksInvoer,'') = '' then
    select first RksGid into @TotRksInvoer from tabKostenSoortVerdeling inner join tabRekeningschema on (RksGid = KostVerdRksGID) order by RksInvoer desc;
  end if;

  if isnull(@VanPerNr,'')='' then
    select first PerNr into @vanPerNr from tabPeriode where PerBjGid = @BjGid order by PerNr;
  end if;

  if isnull(@TotPerNr,'')='' then
    select first PerNr into @TotPerNr from tabPeriode where PerBjGid = @BjGid order by PerNr desc;
  end if;

  //Blokkade? Zoja, dan doorgeven ivm. een melding in het programma
  if exists(select 1 from tabRekeningSchema where  RksInvoer between @VanRksInvoer and @TotRksInvoer and IsRksGeblokkeerd<>0) then
    set @RksGeblokkeerd = 1
  else
    set @RksGeblokkeerd = 0;
  end if;

  //Per rekening verwerken
  set @VorigRksInvoer = '';
  loopje:
  loop
    set @HuidigRksInvoer = null;

    select min(RksInvoer) into @HuidigRksInvoer
    from   tabRekeningschema inner join tabKostensoortVerdeling on (RksGid = KostVerdRksGID)
    where  RksInvoer > @VorigRksInvoer and RksInvoer between @VanRksInvoer and @TotRksInvoer and IsRksGeblokkeerd=0;

    if @HuidigRksInvoer is null then
      leave loopje;
    end if;

    set @VorigRksInvoer = @HuidigRksInvoer;
    select RksGid into @RksGid from tabRekeningSchema where RksInvoer = @HuidigRksInvoer;

    if @BoekenInPeriode = 1 then
      //Lusje per periode en de datum vastleggen
      set @VorigePeriode = @VanPernr - 1;
      PeriodeLoop:
      loop
        set @Periode = null;
        select first PerNr, EindDatum into @Periode, @BoekDatum from tabPeriode where PerNr > @VorigePeriode and PerNr <= @TotPernr and PerBjGid = @BjGid order by pernr;
        if @Periode is null then
          leave PeriodeLoop;
        end if;
        set @VorigePeriode = @Periode;

        //Boek in juiste periode
        call VerbijzonderenKostensoortenLus(@BjGid, @RksGid, @BoekstukNummer, @Periode, @Periode, @DgbCode, @BoekDatum);
      end loop PeriodeLoop;
    else
      //Verbijzonder naar 1 datum
      //Boek gelijk alles weg
      call VerbijzonderenKostensoortenLus(@BjGid, @RksGid, @BoekstukNummer, @VanPernr, @TotPernr, @DgbCode, @BoekDatum);
    end if;

  end loop loopje;

  update tabBoekingsGang set BoekGangInGebruik = 0 where BoekgangGid = @BoekGangGid;

  //Als we niks hebben geboekt, dan ook geen boekgangnummer teruggeven
  if not exists(select 1 from tabboekingsgang where boekganggid=@boekgangGid) then
    set @BoekgangGid = null;
  end if;

  set @@ErrorTextProcedure = 'VerbijzonderenKostensoorten';
  //call TraceEind(@@ErrorTextProcedure + ' > @BoekGangGid = ' + string(@BoekGangGid));
end;


create or replace procedure VerbijzonderenKostensoortenLus(in @BjGid integer, in @RksGid integer, inout @BoekstukNummer numeric(10,0), in @VanPernr integer, in @TotPernr integer, in @DgbCode nchar(10),
                                                in @BoekDatum date)
begin
  declare @VorigValNummer  integer;
  declare @ValNummer       integer;
  declare @KostVerdGid     integer;
  declare @KostVerdBoekzijde integer;
  declare @BjGidBoekDatum  integer;
  declare @PerNrBoekDatum  integer;
  declare @Bedrag          numeric(15,2);
  declare @Aantal          numeric(15,2);
  declare @GeboektBedrag   numeric(15,2);
  declare @GeboektAantal   numeric(15,2);
  declare @HoogsteGid      integer;
  declare @JpAangemaakt    smallint;
  declare @TeVerdelen      smallint; //0=alleen bedragen, 1=alleen aantallen, 3=bedragen en aantallen

  declare @VerbijzonderenTekst long nvarchar;

  //call TraceBegin('VerbijzonderenKostensoortenLus( @BjGid='+string(@BjGid)+', @RksGid='+string(@RksGid)+', @VanPernr='+string(@VanPernr)+', @TotPernr='+string(@TotPernr)+', @DgbCode='+@DgbCode+', @BoekDatum='+string(@BoekDatum)+')');
  set @VerbijzonderenTekst = _A('Verbijzonderen kostensoorten');

  call BepaalBoekjaarEnPeriode( @BoekDatum, @BjGidBoekDatum, @PerNrBoekDatum);
  select KostVerdGid, KostVerdTeVerdelen, KostVerdBoekzijde into @KostVerdGid, @TeVerdelen, @KostVerdBoekzijde from tabKostenSoortVerdeling where KostVerdRksGID = @RksGid;

  //call Trace('Bepaal de laatste (hoogste) rekening in de verdeling');
  select max(KostVerdPercGid) into @HoogsteGid from tabKostenSoortVerdelingPercentage where KostVerdPercKostVerdGid = @KostVerdGid;

  if @TeVerdelen in (0,3) then
    set @VorigValNummer = -1;

    //Loopje per valuta!
    LoopValuta:
    loop
      set @ValNummer = null;
      select   first RekSaldoValNummer into @ValNummer
      from     tabRekeningSaldo
      where    RekSaldoValNummer > @VorigValNummer and RekSaldoRksGid = @RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr between @VanPerNr and @TotPerNr order by RekSaldoValNummer;
      if @ValNummer is null then
        leave LoopValuta;
      end if;
      set @VorigValNummer = @ValNummer;

      set @bedrag = 0;
      set @aantal = 0;

      select sum(SaldoDebetValutaDefinitief-SaldoCreditValutaDefinitief), sum(SaldoDebetAantalDefinitief-SaldoCreditAantalDefinitief)
      into   @bedrag, @Aantal
      from   tabRekeningSaldo
      where  RekSaldoRksGid = @RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr between @VanPerNr and @TotPerNr and RekSaldoValNummer=@ValNummer;

      if @TeVerdelen = 0 then
        //Geen aantallen verbijzonderen? Dan ook niet boeken
        set @Aantal = 0;
      end if;
      if @KostVerdBoekzijde = 0 then
        //Debet boeken, dus saldo negatief maken
        set @bedrag = -@bedrag;
        set @Aantal = -@Aantal;
      end if;

      //call Trace('Valuta gevonden: '+string(@ValNummer)+' Totaal bedrag definitief:'+string(@bedrag));

      if isnull(@bedrag,0) <> 0 or isnull(@Aantal,0) <> 0 then

        if isnull(@JpAangemaakt,0)=0 then
          set @JpAangemaakt = 1;
          //Aanmaken journaalpost
          insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum)
          select @@BoekGangGid, 1, DgbGid, @Boekstuknummer, @VerbijzonderenTekst, @Boekdatum from tabDagboek where DgbCode = @DgbCode;
          set @Boekstuknummer = @Boekstuknummer + 1;
        end if;

        //De rekening zelf afboeken
        insert into tabjournaalregel(JrJpGid, JrRksGid, JrValNummer, JrValutaBedrag, JrBasisBedrag, Aantal, IsCreditBoeking, SoortBoeking, OmsJournaalRegel)
        select @@JpGid, KostVerdRksGid, @ValNummer, @bedrag, ValutaOmrekenen( @ValNummer, @bedrag, @@BasisValutaNummer, @BjGidBoekDatum, @PernrBoekDatum, 2), @Aantal,
               KostVerdBoekzijde, 0, @VerbijzonderenTekst
        from tabKostenSoortVerdeling where KostVerdRksGid = @RksGid;

        //En op alle aangegeven rekeningen (behalve de laatste) boeken
        insert into tabjournaalregel(JrJpGid, JrRksGid, JrValNummer, JrValutaBedrag, JrBasisBedrag, Aantal, IsCreditBoeking, SoortBoeking, OmsJournaalRegel)
        select @@JpGid, KostVerdPercRksGid, @ValNummer,
               KostVerdPercPercentage/100 * @bedrag * (if @KostVerdBoekzijde=KostVerdPercBoekzijde then -1 else 1 endif),
               ValutaOmrekenen( @ValNummer, KostVerdPercPercentage/100 * @bedrag * (if @KostVerdBoekzijde=KostVerdPercBoekzijde then -1 else 1 endif), @@BasisValutaNummer, @BjGidBoekDatum, @PernrBoekDatum, 2),
               KostVerdPercPercentage/100 * @Aantal * (if @KostVerdBoekzijde=KostVerdPercBoekzijde then -1 else 1 endif),
               KostVerdPercBoekzijde, 0, @VerbijzonderenTekst
        from   tabKostenSoortVerdelingPercentage
        where  KostVerdPercKostVerdGid= @KostVerdGid and KostVerdPercGid <> @HoogsteGid
        order by KostVerdPercGid;

        //Bepaal geboekte bedrag
        select sum(round(KostVerdPercPercentage/100 * @bedrag,2)), sum(round(KostVerdPercPercentage/100 * @Aantal,2)) into @GeboektBedrag, @GeboektAantal
        from   tabKostenSoortVerdelingPercentage
        where  KostVerdPercKostVerdGid= @KostVerdGid and KostVerdPercGid <> (select max(KostVerdPercGid) from tabKostenSoortVerdelingPercentage where KostVerdPercKostVerdGid = @KostVerdGid);
        set    @GeboektBedrag=isnull(@GeboektBedrag,0); //Omdat er misschien maar 1 verdelingsregel is (dus hier nog geen boeking!)
        set    @GeboektAantal=isnull(@GeboektAantal,0);

        //De laatste boeken als @bedrag-@geboektBedrag
        insert into tabjournaalregel(JrJpGid, JrRksGid, JrValNummer, JrValutaBedrag, JrBasisBedrag, Aantal, IsCreditBoeking, SoortBoeking, OmsJournaalRegel)
        select @@JpGid, KostVerdPercRksGid, @ValNummer,
               (@bedrag - @GeboektBedrag) * (if @KostVerdBoekzijde=KostVerdPercBoekzijde then -1 else 1 endif), //Dus niet: KostVerdPercPercentage/100 * @bedrag
               ValutaOmrekenen( @ValNummer, (@bedrag - @GeboektBedrag) * (if @KostVerdBoekzijde=KostVerdPercBoekzijde then -1 else 1 endif), @@BasisValutaNummer, @BjGidBoekDatum, @PernrBoekDatum, 2),
               (@Aantal - @GeboektAantal) * (if @KostVerdBoekzijde=KostVerdPercBoekzijde then -1 else 1 endif),
               KostVerdPercBoekzijde, 0, @VerbijzonderenTekst
        from   tabKostenSoortVerdelingPercentage
        where  KostVerdPercKostVerdGid= @KostVerdGid and KostVerdPercGid = @HoogsteGid;
      end if;

    end loop LoopValuta;
  else
    //Alleen aantallen verbijzonderen, dus direct alles wegboeken
    select sum(SaldoDebetAantalDefinitief-SaldoCreditAantalDefinitief)
    into   @Aantal
    from   tabRekeningSaldo
    where  RekSaldoRksGid = @RksGid and RekSaldoBjGid = @BjGid and RekSaldoPerNr between @VanPerNr and @TotPerNr;
    if @Aantal <> 0 then

      if @KostVerdBoekzijde = 0 then
        //Debet boeken, dus saldo negatief maken
        set @Aantal = -@Aantal;
      end if;

      //Aanmaken journaalpost
      insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum)
      select @@BoekGangGid, 1, DgbGid, @Boekstuknummer, @VerbijzonderenTekst, @Boekdatum from tabDagboek where DgbCode = @DgbCode;
      set @Boekstuknummer = @Boekstuknummer + 1;

      //De rekening zelf afboeken
      insert into tabjournaalregel(JrJpGid, JrRksGid, JrValNummer, JrValutaBedrag, JrBasisBedrag, Aantal, IsCreditBoeking, SoortBoeking, OmsJournaalRegel)
      select @@JpGid, KostVerdRksGid, @@basisValutaNummer, 0, 0, @Aantal, KostVerdBoekzijde, 0, @VerbijzonderenTekst
      from tabKostenSoortVerdeling where KostVerdRksGid = @RksGid;

      //Aantallen wegboeken
      insert into tabjournaalregel(JrJpGid, JrRksGid, JrValNummer, JrValutaBedrag, JrBasisBedrag, Aantal, IsCreditBoeking, SoortBoeking, OmsJournaalRegel)
      select @@JpGid, KostVerdPercRksGid, @@basisValutaNummer, 0, 0, KostVerdPercPercentage/100 * @Aantal * (if @KostVerdBoekzijde = KostVerdPercBoekzijde then -1 else 1 endif),
             KostVerdPercBoekzijde, 0, @VerbijzonderenTekst
      from   tabKostenSoortVerdelingPercentage
      where  KostVerdPercKostVerdGid= @KostVerdGid and KostVerdPercGid <> @HoogsteGid
      order by KostVerdPercGid;

      //Bepaal geboekte aantal
      select sum(round(KostVerdPercPercentage/100 * @Aantal,2)) into @GeboektAantal
      from   tabKostenSoortVerdelingPercentage
      where  KostVerdPercKostVerdGid= @KostVerdGid and KostVerdPercGid <> (select max(KostVerdPercGid) from tabKostenSoortVerdelingPercentage where KostVerdPercKostVerdGid = @KostVerdGid);
      set    @GeboektAantal=isnull(@GeboektAantal,0); //Omdat er misschien maar 1 verdelingsregel is (dus hier nog geen boeking!)

      //Laatste regel afboeken ivm. afrondingen
      insert into tabjournaalregel(JrJpGid, JrRksGid, JrValNummer, JrValutaBedrag, JrBasisBedrag, Aantal, IsCreditBoeking, SoortBoeking, OmsJournaalRegel)
      select @@JpGid, KostVerdPercRksGid, @@basisValutaNummer, 0, 0, (@Aantal-@GeboektAantal) * (if @KostVerdBoekzijde=KostVerdPercBoekzijde then -1 else 1 endif),
             KostVerdPercBoekzijde, 0, @VerbijzonderenTekst
      from   tabKostenSoortVerdelingPercentage
      where  KostVerdPercKostVerdGid= @KostVerdGid and KostVerdPercGid = @HoogsteGid;
    end if;
  end if;

  if isnull(@JpAangemaakt,0)=1 then
    update tabJournaalPost set JpIsIngebruik= 0 where JpGid = @@JpGid;
  end if;


  //call TraceEind('VerbijzonderenKostensoortenLus');

end;


create or replace function VerkoopEenheidInGebruik(in @VkeGid integer)
// 0 = niet in gebruik, 1 en hoger is in gebruik, waarbij je aan het getal kan achterhalen in welke tabel deze wordt gebruikt
returns smallint
begin
  declare @IsInGebruik integer;

  set @IsInGebruik = (select first 1 from tabOrderRegel where OrrVkeGid = @VkeGid);
  if (@IsInGebruik is null) then
    set @IsIngebruik = (select first 2 from tabOrderRegelLocatie where OrlVkeGid = @VkeGid);
  end if;

  set @IsInGebruik = IsNull(@IsInGebruik, 0);
  return @IsInGebruik;
end;


//---- procedure retourneert of voor elk record van een nawsoort een record is in de tabel 'tabelnaam'
create or replace procedure VerschilInRecords(in @TabelNaam nchar(30), in @VeldnaamFonGid nchar(20), in @VeldnaamNawgid nchar(20), in @FonGid integer, out @AantalMeerInNawFile integer)
begin
  declare @AantalInNawFile   integer;
  declare @AantalInTabelnaam integer;
  declare @Exists            integer;

  set @@ErrorTextProcedure = 'VerschilInRecords > @TabelNaam='+@TabelNaam+', @VeldNaamFongid='+string(@VeldnaamFongid)+', @VeldnaamNawgid='+string(@VeldnaamNawgid)+', @FonGid='+string(@Fongid);
  //call TraceBegin(@@ErrorTextProcedure);

  call TableExist(@TabelNaam, @Exists);

  if @Exists <> 0 then
    execute immediate 'select IsNull((select count(*) from tabNawFile, '||@Tabelnaam||' where NawFilFonGid=@FonGid '+
                      'and NawFilFonGid='||@VeldnaamFongid||' and nawfilnawgid='||@VeldnaamNawgid||'),0) into @AantalInTabelnaam';
  else
    set @AantalInTabelnaam=0;
  end if;

  select IsNull((select count(*) from tabNawFile where NawFilFonGid=@FonGid), 0) into @AantalInNawFile;

  set @AantalMeerInNawFile = @AantalInNawFile - @AantalInTabelnaam;

  set @@ErrorTextProcedure = 'VerschilInRecords > @AantalMeerInNawFile='+string(@AantalMeerInNawFile);
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: VervalDatumFactuurMetRksGid.sp $ $Revision: 3 $ $Modtime: 31-08-07 15:54 $'

//--------- Bereken de vervaldatum van de factuur aan de hand van de betalingsconditie via een RksGid
if exists (select 1 from sys.sysProcedure where proc_name='VervalDatumFactuurMetRksGid') then
  drop procedure VervalDatumFactuurMetRksGid;
end if;

create procedure VervalDatumFactuurMetRksGid (in @FactuurDatum date, in @RksGid integer, inout @VervalDatum date)
begin
  declare @BtcNummer integer;

  set @@ErrorTextProcedure = 'VervalDatumFactuurMetRksGid > @FactuurDatum='+string(@FactuurDatum)+', @RksGid='+string(@RksGid);
  //call TraceBegin(@@ErrorTextProcedure);

  select nawfilBtcNummer into @BtcNummer from tabNawFile where NawFilRksGid = @RksGid;
  if @BtcNummer is not null then
    call BerekenVervalDatumFactuur(@FactuurDatum, @BtcNummer, @VervalDatum);
  end if;

  set @@ErrorTextProcedure = 'VervalDatumFactuurMetRksGid > @Vervaldatum='+string(@Vervaldatum);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure VerwerkenVoorraadMutaties(in @VckGid integer,
                                           in @DgbGid integer,
                                           in @Boekdatum date,
                                           in @Stuknummer numeric(10,0),
                                           in @Omschrijving nchar(40),
                                           in @TegenBoekenOp integer,
                                           in @TegenRksGid integer,
                                           in @Mutsoort smallint,
                                           in @OpEnAfboekingen smallInt,
                                           in @CheckOpDubbelBoeknummer integer,
                                           inout @BoekgangGid integer)
begin
  //------------Voorraadcorrecties: voorraadaantallen bijwerken-------------------
  declare @JpGid              Integer;
  declare @AantalSerienummers Integer;
  declare @fNummer            Integer;
  declare @fMelding           nchar(250);
  declare @VrdMutGid          integer;

  set @@ErrorTextProcedure = 'VerwerkenVoorraadMutaties > ';
  //call TraceBegin(@@ErrorTextProcedure + '@VckGid = ' + string(@VckGid) + ', @DgbGid = ' + string(@DgbGid) + ', @Boekdatum = ' + string(@Boekdatum) + ', @Stuknummer = ' + string(@Stuknummer) + ', @TegenBoekenOp = ' + string(@TegenBoekenOp) + ', @TegenRksGid = ' + string(@TegenRksGid) + ', @TegenRksGid = ' + string(@CheckOpDubbelBoeknummer));

  //Hier eerst controleren of de @boekdatum voor de voorraadmutaties na de laatste herwaardering valt van het betreffende artikel.
  //Als dit niet zo is, ga er dan uit.
  call CheckDatumVrdMutaties(@VckGID, @Boekdatum, @fNummer, @fMelding);

  //MR 16-sep-2008 bug # 28998: Hier alleen eruit knallen met melding 2
  If (@fNummer = 2) then
    call Raise(20001, @fMelding);
  end if;

  call VerwerkenVoorraadMutatiesBoekingen(@VckGid, @DgbGid, @Boekdatum, @Stuknummer, @Omschrijving, @TegenBoekenOp, @TegenRksGid, @Mutsoort, @OpEnAfboekingen, @CheckOpDubbelBoeknummer, @BoekgangGid, @JpGid);

  if not exists(Select 1 from tabJournaalpost where JpGid = @JpGid) then
    set @JpGid       = null;
    set @BoekgangGid = null;
  end if;

  FOR @Cursor AS cursor_Voorraadmutaties CURSOR FOR
    //de verschillende opbrengstgroepen pakken.
    select  VckNummer @VckNummer, VcrAantal @VcrAantal, VcrArtGid @VcrArtGid, VcrArtPartijGid @VcrArtPartijGid, VcrGid @VcrGid,
            VcrLocGid @VcrLocGid, VcrMagGid @VcrMagGid, VcrRegelNummer  @VcrRegelNummer,  VcrVckGid @VcrVckGid, ArtPrijsPer @ArtPrijsPer,
           (if (ArtIsPartijRegistreren = 1) and (ArtIsPartijAparteKostPrijs = 1) then ArtPartijKostprijsEx else ArtKostprijsEx endif) @Kostprijs,
            ArtPartijNummer @ArtPartijNummer, VckGebruiker @VckGebruiker, VckMutatieSoortCode @VckMutatieSoortCode
    from tabVoorraadCorrectieKop inner join tabVoorraadCorrectieRegel on (VcrVckGid = VckGid) inner join tabArtikel on (ArtGid = VcrArtGid) left outer join tabArtikelPartij on (ArtPartijGid = VcrArtPartijGid)
    where VckGid=@VckGid and VcrVckGid=@VckGid
    order by VcrRegelNummer
  FOR READ ONLY
  DO
    insert into tabVoorraadMutatie
           (vrdMutArtGid,              vrdMutNawGid,        vrdMutDatum,          vrdMutSoort,
            VrdMutUitleverOntvangstNr, VrdMutOrderBestelNr, vrdMutValNummer,      vrdMutGeprijsdPer,
            vrdMutPrijsInValuta,       VrdMutPrijsInBasis,  vrdMutHistKostprijs,  vrdMutGebruikerCode,
            VrdMutJpGid,               VrdMutOmschrijving,  VrdMutGebruikerVrdCorrectieIngevoerd, vrdMutMutatieSoortCode)
    values( @VcrArtGid,         Null,            @Boekdatum,           @Mutsoort,
            @VckNummer,         @VckNummer,      @@BasisValutaNummer,  @ArtPrijsPer,
            @Kostprijs,         @Kostprijs,      @Kostprijs,           @@GebruikerCode,
            @JpGid,             @Omschrijving,   @VckGebruiker,        @VckMutatieSoortCode);
    set @VrdMutGid = @@Identity;

    // Nu de 'detail'-tabel vullen. Hierin staan de locatie, het aantal en eventueel 1 serienummer.
    insert into tabVoorraadMutatieLocatieSerie
               (VrdMutLocVrdMutGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer, VrdMutLocAantal)
         select @VrdMutGid,        @VcrLocGid,      (if IsNull(@ArtPartijNummer,'') = '' then '(standaard)' else @ArtPartijNummer endif),     (SELECT ArtSerienummer FROM tabArtikelSerienummer WHERE ArtSerieGid = VcsArtSerieGid), (if @VcrAantal > 0 then 1 else -1 endif)
         from   tabVoorraadCorrectieSerienummer
         where  VcsVcrGid = @VcrGid;

    select count(*) into @AantalSerienummers from tabVoorraadCorrectieSerienummer where VcsVcrGid = @VcrGid;
  	if @VcrAantal < 0 then
      set @AantalSerienummers = -@AantalSerienummers;
    end if;

    if (@AantalSerienummers <> @VcrAantal) OR (@VcrAantal=0) then
      insert into tabVoorraadMutatieLocatieSerie
                  (VrdMutLocVrdMutGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer, VrdMutLocAantal)
          values (@VrdMutGid,        @VcrLocGid,      @ArtPartijNummer,      Null,      @VcrAantal - @AantalSerienummers)
    end if;

  end for;  //CURSOR cursor_Voorraadmutaties

  delete from tabVoorraadCorrectieKop where VckGid = @VckGid;

  set @@ErrorTextProcedure = 'VerwerkenVoorraadMutaties';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure VerwerkenVoorraadMutatiesBoekingen(in @VckGid integer,
                                                    in @DgbGid integer,
                                                    in @Boekdatum date,
                                                    in @Stuknummer numeric(10,0),
                                                    in @Omschrijving nchar(40),
                                                    in @TegenBoekenOp integer,
                                                    in @TegenRksGid integer,
                                                    in @Mutsoort smallint,
                                                    in @OpEnAfboekingen smallInt,
                                                    in @CheckOpDubbelBoeknummer integer,
                                                    inout @BoekgangGid integer,
                                                    inout @JpGid integer)
begin
  //------------------------------------------------------------------------------
  //--------------------VOORRAADCORRECTIEBOEKSOORT--------------------------------
  //------------------------------------------------------------------------------

  declare @OpbrGrpGid         integer;
  declare @OpbrGrpNr          nchar(4);
  declare @OpbrGrpRksGid      Integer;
  declare @Bedrag             Float;
  declare @AfBoeking          SmallInt;
  declare @TotaalAf           Float;
  declare @TotaalBij          Float;
  declare @AantDecimalenBasis SmallInt;
  declare @IsGebruikt         integer;

  declare local temporary table tmpVoorraadMutatieJP (
    tmpOpbrGroepGid integer,
    tmpOpbrGroepNr  nchar(4),
    tmpBedrag       numeric(15,2),
    tmpAfBoeking    integer,
    Primary key (tmpOpbrGroepNr, tmpAfBoeking)
  );

  declare cursor_OpbrengstGroepen dynamic scroll cursor for
    //de verschillende opbrengstgroepen pakken.
    select tmpOpbrGroepGid, tmpOpbrGroepNr, tmpBedrag, tmpAfBoeking
    from tmpVoorraadMutatieJP
    order by tmpOpbrGroepNr
  for read only;


  set @@ErrorTextProcedure = 'VerwerkenVoorraadMutatiesBoekingen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@VckGid = ' + string(@VckGid) + ', @DgbGid = ' + string(@DgbGid) + ', @Boekdatum = ' + string(@Boekdatum) + ', @Stuknummer = ' + string(@Stuknummer) + ', @TegenBoekenOp = ' + string(@TegenBoekenOp)+ ', @TegenRksGid =' + string(@TegenRksGid));

  select DecimalenBoeking*2 into @AantDecimalenBasis from tabvaluta where ValNummer=@@BasisValutaNummer;

  if @OpEnAfboekingen = 1 then
    if ((select IsModuleActive('vr')) <> 0) then   //'vr' = module voorraad
      insert into tmpVoorraadMutatieJP(tmpOpbrGroepGid, tmpOpbrGroepNr, tmpBedrag, tmpAfBoeking)
      select      OpbrGrpGid,
                  OpbrGrpNummer,
                  Sum(Round(IsNull(VcrAantal  * (if (ArtIsPartijRegistreren = 1) and (ArtIsPartijAparteKostPrijs = 1) then ArtPartijKostprijsEx else ArtKostprijsEx endif)  / ArtPrijsPer ,0.00),@AantDecimalenBasis)) bedrag,
                  (if bedrag < 0 then 1 else 0 endif) AfBoeking
      from        tabVoorraadCorrectieRegel inner join tabArtikel on (ArtGid = VcrArtGid) inner join tabOpbrengstGroep on (ArtOpbrGrpGid = OpbrGrpGid) left outer join tabartikelpartij on (ArtPartijGid = VcrArtPartijGid)
      where       VcrVckGid = @VckGid
      group by    OpbrGrpGid, OpbrGrpNummer
    end if;
  else
    if ((select IsModuleActive('vr')) <> 0) then   //'vr' = module voorraad
      insert into tmpVoorraadMutatieJP(tmpOpbrGroepGid, tmpOpbrGroepNr, tmpBedrag, tmpAfBoeking)
      select      OpbrGrpGid,
                  OpbrGrpNummer,
                  Sum(Round(IsNull(VcrAantal  * (if (ArtIsPartijRegistreren = 1) and (ArtIsPartijAparteKostPrijs = 1) then ArtPartijKostprijsEx else ArtKostprijsEx endif)  / ArtPrijsPer ,0.00),@AantDecimalenBasis)) bedrag,
                  (if VcrAantal < 0 then 1 else 0 endif) AfBoeking
      from        tabVoorraadCorrectieRegel inner join tabArtikel on (ArtGid = VcrArtGid) inner join tabOpbrengstGroep on (OpbrGrpGid = ArtOpbrGrpGid) left outer join tabartikelpartij on (ArtPartijGid = VcrArtPartijGid)
      where       VcrVckGid = @VckGid
      group by    OpbrGrpGid, OpbrGrpNummer, AfBoeking
    end if;
  end if;


  insert into tabBoekingsGang(BoekGangBjGid, BoekgangBronId, BoekGangInGebruik, IsBoekGangDefinitief)
                      values (@@BjGid,                   10,                 1, 0);
  set @BoekGangGid = @@Identity;

  insert into tabJournaalPost (JpBoekGangGid, JpBjGid, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum,  JpIsInGebruik)
                       values (@BoekGangGid,  @@BjGid, @DgbGid,  @StukNummer,    @Omschrijving,   @BoekDatum, 1);
  set @JpGid = @@Identity;

  // Check of dubbel boekstuknummers als @CheckOpDubbelBoeknummer = 1 anders niet checken maar gewoon doorgaan
  if @CheckOpDubbelBoeknummer = 1 then

    Call WordStuknummerAlGebruikt(@@BjGid, @DgbGid, @JpGid, @Stuknummer, @IsGebruikt);

    while @IsGebruikt = 1 and (@StukNummer <> 9999999999) loop
      call BoekstuknummerPlusEen(@@BjGid, @DgbGid, 1, @StukNummer);
      //vervangen in tabJournaalPost
      update tabJournaalPost
      set BoekStukNummer   = @StukNummer
      where JpGid = @JpGid;
      Call WordStuknummerAlGebruikt(@@BjGid, @DgbGid, @JpGid, @StukNummer, @IsGebruikt);
    end loop;

  end if;

  set @TotaalAf  = 0.00;
  set @TotaalBij = 0.00;

  open cursor_OpbrengstGroepen;
  LoopOpbrengstGroep:
  loop
    Fetch next cursor_OpbrengstGroepen into @OpbrGrpGid, @OpbrGrpNr, @Bedrag, @AfBoeking;
    if sqlstate = '02000' then
      leave LoopOpbrengstGroep;
    end if;

    if @Bedrag <> 0.00 then
      //Totaal bedrag af/bij bijwerken indien op aparte rekening geboekt moet worden
      if @Afboeking = 1 then
        set @TotaalAf  = @TotaalAf  + @Bedrag;
      else
        set @TotaalBij = @TotaalBij + @Bedrag;
      end if;

      call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 50, @OpbrGrpRksGid);

      insert into tabJournaalRegel
             (JrJpGID, JrRksGid,       OmsJournaalRegel, IsCreditBoeking,                    JrValNummer,         JrValutaBedrag, JrBasisBedrag)
      values ( @JpGid, @OpbrGrpRksGid, @Omschrijving, if @AfBoeking = 1 then 1 else 0 endif, @@BasisValutaNummer, if @AfBoeking = 1 then -@Bedrag else @Bedrag endif, if @AfBoeking = 1 then -@Bedrag else @Bedrag endif);

      if @TegenBoekenOp = 0 then
        call FacturerenLeverMaakRekeningObvOpbrGroep(@OpbrGrpGid, 100, @OpbrGrpRksGid);

        insert into tabJournaalRegel
               (JrJpGID, JrRksGid,       OmsJournaalRegel, IsCreditBoeking,                    JrValNummer,         JrValutaBedrag, JrBasisBedrag)
        values ( @JpGid, @OpbrGrpRksGid, @Omschrijving, if @AfBoeking = 1 then 0 else 1 endif, @@BasisValutaNummer, if @AfBoeking = 1 then -@Bedrag else @Bedrag endif, if @AfBoeking = 1 then -@Bedrag else @Bedrag endif);
      end if;
    end if;

  end loop LoopOpbrengstGroep;

  if @TegenBoekenOp = 2 then

    if @OpEnAfboekingen = 1 then
      if (@TotaalBij + @TotaalAf) = 0.00 then
        Set @TotaalBij = 0.00;
        Set @TotaalAf  = 0.00;
      else
        if (@TotaalBij + @TotaalAf) > 0 then
          Set @TotaalBij = (@TotaalBij + @TotaalAf);
          Set @TotaalAf  = 0.00;
        else
          Set @TotaalAf  = (@TotaalBij+@TotaalAf);
          Set @TotaalBij = 0.00;
        end if;
      end if;
    end if;

    if @TotaalBij <> 0.00 then
      insert into tabJournaalRegel
             (JrJpGID, JrRksGid,     OmsJournaalRegel, IsCreditBoeking, JrValNummer,         JrValutaBedrag, JrBasisBedrag)
      values ( @JpGid, @TegenRksGid, @Omschrijving,    1,               @@BasisValutaNummer, @TotaalBij,        @TotaalBij);
    end if;

    if @TotaalAf <> 0.00 then
      insert into tabJournaalRegel
             (JrJpGID, JrRksGid,     OmsJournaalRegel, IsCreditBoeking, JrValNummer,         JrValutaBedrag, JrBasisBedrag)
      values ( @JpGid, @TegenRksGid, @Omschrijving,    0,               @@BasisValutaNummer, -@TotaalAf,        -@TotaalAf);
    end if;
  end if;

  close cursor_OpbrengstGroepen;

  update tabJournaalpost set JpIsInGebruik = 0 where JpGid = @JpGid;

  update tabBoekingsGang set BoekGangInGebruik = 0 where BoekGangGid = @BoekGangGid;

  set @@ErrorTextProcedure = 'VerwerkenVoorraadMutatiesBoekingen';
  //call TraceEind(@@ErrorTextProcedure + ' > @BoekGangGid = ' + string(@BoekGangGid));
end;


create or replace procedure VerwerkVoorraadMutatieLocatieRegel(in @VrdMutGid integer, in @LocGid integer, in @PartijNummer nchar(20), in @SerieNummer nchar(20), in @Aantal numeric(15,3))
begin
  declare @ArtGid                 integer;
  declare @ArtPartijGid           integer;
  declare @ArtSerieGid            integer;
  declare @MagGid                 integer;
  declare @ArtIsPartijRegistreren smallint;
  declare @ArtSerieNrRegistreren  smallint;
  declare @ArtHeeftVoorraad       smallint; // 0 = GEEN voorraadartikel, 1 = WEL voorraadartikel
  declare @SoortMutatie           smallint;
  declare @Mutatiedatum           Date;

  set @@ErrorTextProcedure = 'VerwerkVoorraadMutatieLocatieRegel > ';
  //call TraceBegin(@@ErrorTextProcedure + '@VrdMutGid = ' + string(@VrdMutGid) + ', @SerieNummer = ' + @SerieNummer);

  // (20204) VoorraadMutatiedetail mag niet direct worden aangeroepen!
  if @@FiredByTriggerVoorraadMutatieLocatie = 0 then
    raiserror 20204;
  end if;

  // ACW: Nog rekening houden met een andere (hist.) kostprijs ivm. andere partij?
  update tabVoorraadMutatie
  set    VrdMutAantal = VrdMutAantal + @Aantal
  where  VrdMutGid = @VrdMutGid;

  // Opzoeken magazijn uit de locatietabel
  select LocMagGid into @MagGid from tabLocatie where LocGid = @LocGid;

  // Opzoeken van artikel uit de mutaties
  select VrdMutArtGid, VrdMutSoort, VrdMutDatum into @ArtGid, @SoortMutatie, @Mutatiedatum from tabVoorraadMutatie where VrdMutGid = @VrdMutGid;
  select  ArtHeeftVoorraad,  ArtIsPartijRegistreren,  ArtSerieNrRegistreren
  into   @ArtHeeftVoorraad, @ArtIsPartijRegistreren, @ArtSerieNrRegistreren
  from tabArtikel where ArtGid = @ArtGid;

  // Opvragen partijgid van betreffende partij van dit artikel
  if (IsNull(@PartijNummer,'') <> '') and ((@ArtIsPartijRegistreren <> 0) or (@ArtSerieNrRegistreren <> 0)) then
    select ArtPartijGid into @ArtPartijGid from tabArtikelPartij where ArtPartijNummer = @PartijNummer and ArtPartijArtGid = @ArtGid;
    if @ArtPartijGid is null then
      // 20183: De partij van de voorraadmutatie is niet ingevuld of onbekend!
      raiserror 20183;
    end if;
  end if;


  if isnull(@SerieNummer, '') = '' then
    set @ArtSerieGid = null;
  else
    select ArtSerieGid into @ArtSerieGid from tabArtikelSerienummer where ArtSeriePartijGid = @ArtPartijGid and ArtSerienummer = @SerieNummer;
    //(20207) Serienummer van de voorraadmutaties niet bij de artikelgegevens gevonden!
    if @ArtSerieGid is null then
      raiserror 20207;
    end if;
  end if;

  if @ArtHeeftVoorraad <> 0 then
    call BijwerkenVoorraadAantallen(@ArtGid, @MagGid, @LocGid, @ArtPartijGid, @ArtSerieGid, @Aantal, @SoortMutatie, @Mutatiedatum);
  end if;

  set @@ErrorTextProcedure = 'VerwerkVoorraadMutatieLocatieRegel';
  //call TraceEind(@@ErrorTextProcedure);
end;


//$Workfile: VerwijderAcceptGiroTabel.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// ---------- Acceptgirotabel verwijderen met zijn eigen lock ----------
