create procedure VerwijderAcceptGiroTabel(in @AcbGid integer)
begin
   set @@ErrorTextProcedure = 'VerwijderAcceptGiroTabel > @AcbGid='+string(@AcbGid);
  //call TraceBegin(@@ErrorTextProcedure);
  // Header van de acc.girotabel verwijderen (regels zijn cascaded delete)
