  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure VerwijderDubbeleBankrekeningen()
//ACW 19-12-2013 i.o.m. RB/BS: DubRek.erc hierin gehangen
//                             Wel met een extra EXCEPTION controle, zodat de fire_triggers wel weer aan gaat
begin
  declare @VorigeBBANNawRekGid  integer;
  declare @BBANNawRekGid        integer;
  declare @IBANNawRekGid        integer;
  declare @BBANNawRekSoort      char(8);
  declare @IBANNawRekSoort      char(8);
  declare @BBANrekening         char(34);
  declare @NewNawReksoort       char(8);
  declare @IsIBANechtIban       smallint;
  declare @NawGid               integer;
  declare @NawNummer            char(10);
  declare @OnbekendTekst        long nvarchar;

  set temporary option fire_triggers = 'off';

  set @@ErrorTextProcedure = 'VerwijderDubbeleBankrekeningen';
  //call TraceBegin(@@ErrorTextProcedure);

  //Cursor om de oude BankRekening op te halen.
  set @BBANNawRekGid       = 0;
  set @VorigeBBANNawRekGid = -1;
  LoopDubbeleBankRekening:
  while @VorigeBBANNawRekGid <> @BBANNawRekGid LOOP
    set @VorigeBBANNawRekGid = @BBANNawRekGid;
    set @BBANNawRekGid = null;
    Select first BBAN.NawRekNawGid, BBAN.NawRekGid, IBAN.NawRekGid, BBAN.NawRekSoort, IBAN.NawRekSoort, IBAN.NawRekisIBAN, BBAN.NawRekBankRekeningInvoer
    into @NawGid, @BBANNawRekGid, @IBANNawRekGid, @BBANNawRekSoort, @IBANNawRekSoort, @IsIBANechtIban, @BBANrekening
    from tabNawRekening BBAN
    inner join tabNawRekening IBAN on  IBAN.NawRekNawGid = BBAN.NawRekNawGid  // Natuurlijk van dezelfde NAW
                                    and IBAN.NawRekGid <> BBAN.NawRekGid      // en natuurlijk zeker niet hetzelfde record
                                    and (   (IBAN.NawRekisIBAN = 1 and GetRekeningnummerFromIBAN(IBAN.NawRekBankRekeningInvoer) = ltrimchar(BBAN.NawRekBankRekeningInvoer, '0'))  // Als IBAN, dan de IBAN vergelijken met de gestripte BBAN
                                         or (IBAN.NawRekisIBAN = 0 and ltrimchar(IBAN.NawRekBankRekeningInvoer, '0') = ltrimchar(BBAN.NawRekBankRekeningInvoer, '0'))             // Als BBAN, dan de gestripte BBAN vergelijken met de gestripte BBAN
                                        )
    where BBAN.NawRekisIBAN = 0;

    //Contructie gewijzigd, zodat steeds opnieuw wordt gezocht. De database wordt namelijk veranderd, dus is het prettig om niet te cachen m.b.v. een cursor
    if @BBANNawRekGid is null or @VorigeBBANNawRekGid = isnull(@BBANNawRekGid, @VorigeBBANNawRekGid) then
      leave LoopDubbeleBankRekening;
    end if;

    //Opzoeken van de juiste NAW bij dit rekeningnummer obv gid
    select first NawFilNummer into @NawNummer from tabNawFile where NawFilNawGid = @NawGid;

    //IncassoMachtiging updaten naar IBAN
    update tabIncassoMachtiging set icmNawRekGid = @IBANNawRekGid where icmNawRekGid = @BBANNawRekGid;

    //IncassoRegel updaten naar IBAN
    update tabIncassoRegel set incRglNawRekGid = @IBANNawRekGid where incRglNawRekGid = @BBANNawRekGid;

    //Openstaande post updaten naar IBAN
    update tabOpenstaandePost set OspIncNawRekGid = @IBANNawRekGid where OspIncNawRekGid = @BBANNawRekGid;

    //OrderKop updaten naar IBAN
    update tabOrderKop set OrkIncNawRekGid = @IBANNawRekGid where OrkIncNawRekGid = @BBANNawRekGid;

    //Als de rekening Defaults heeft updaten naar IBAN
    if (@BBANNawRekSoort <> '') then
      //Extra conrole om ervoor te zorgen dat iedere code maar max. 1 keer in NawRekSoort terecht komt
      set @NewNawReksoort = '';
      if (locate(@BBANNawRekSoort, 'D') <> 0) or (locate(@IBANNawRekSoort, 'D') <> 0) then
        set @NewNawReksoort = @NewNawReksoort + 'D';
      end if;
      if (locate(@BBANNawRekSoort, 'I') <> 0) or (locate(@IBANNawRekSoort, 'I') <> 0) then
        set @NewNawReksoort = @NewNawReksoort + 'I';
      end if;
      if (locate(@BBANNawRekSoort, 'G') <> 0) or (locate(@IBANNawRekSoort, 'G') <> 0) then
        set @NewNawReksoort = @NewNawReksoort + 'G';
      end if;
      if (locate(@BBANNawRekSoort, 'B') <> 0) or (locate(@IBANNawRekSoort, 'B') <> 0) then
        set @NewNawReksoort = @NewNawReksoort + 'B';
      end if;

      update tabNawRekening
      Set NawRekSoort = @NewNawReksoort
      where NawRekGid = @IBANNawRekGid;
    end if;

    //En als laatste de rekening verwijderen
    delete from tabNawRekening where NawRekGid = @BBANNawRekGid;

    // Nu ook gelijk voorloop-0 en spaties van de IBAN verwijderen (de IBAN kan toch een BBAN zijn)
    if @IsIBANechtIban = 0 then
      update tabNawRekening buiten
      Set    NawRekBankRekeningInvoer = upper(right( NawRekBankRekeningInvoer, length(NawRekBankRekeningInvoer) + 1-PATINDEX( '%[^ 0.]%', NawRekBankRekeningInvoer) ))
      where  NawRekGid = @IBANNawRekGid
             and not exists(select first 1 from tabNawRekening binnen
                            where  binnen.NawRekBankRekeningInvoer = right( NawRekBankRekeningInvoer, length(NawRekBankRekeningInvoer) + 1-PATINDEX( '%[^ 0.]%', NawRekBankRekeningInvoer) )
                               and binnen.nawreknawgid = @IBANNawRekGid
                           );
    end if;
  end loop; // LoopDubbeleBankRekening;
  set temporary option fire_triggers = 'on';

  set @@ErrorTextProcedure = 'VerwijderDubbeleBankrekeningen';
  //call TraceEind(@@ErrorTextProcedure);

  EXCEPTION
  WHEN OTHERS THEN
    set temporary option fire_triggers = 'on';
    set OnbekendTekst = _A('<onbekend>');
    set @@LogDetail = _A('Fout tijdens opschonen van bankrekening %1! van NAW %2!.', isnull(@BBANrekening, OnbekendTekst), isnull(@NawNummer, OnbekendTekst) );
    resignal;
end;


// ---------- Verwijderen van machtigingsgebruik gegevens ----------
create or replace procedure VerwijderGebruikVanMachtigingMetGid(in @icmGid integer, in @isTest integer, out @result nchar(250))
begin
  declare @Referentie nchar(35);

  declare @Fout smallint = 0;
  declare @AantalGewijzigd             integer;

  declare @IncKopId integer;

  set @result = '';
  select upper(icmReferentie) into @Referentie from tabIncassoMachtiging where icmGid = @icmGid;

  //Mag wel gewoon in een opdracht zitten; kan niet erg veel kwaad; moet de gebruiker maar wel opletten
  //select first IncKopId into @IncKopId
  //from   tabIncassoRegel
  //       inner join tabIncassoKop on (IncKopId = IncRglIncKopId)
  //where  IncKopStatus <> 0 /*Voorstel*/
  //   and IncRglIcmReferentie = @Referentie;
  //
  ////Controle op in gebruik zijn van de machtiging
  //if @IncKopId is not null then
  //  set @Result = 'Machtiging ''' + @Referentie + ''' wordt gebruikt in incasso-opdracht ' + right('000' + string(@IncKopId), 3) + '!';
  //  set @Fout = 1;
  //end if;

  //De regel die deze machtiging gebruikt moet alleen niet als Opdracht staan
  select first IncKopId into @IncKopId
  from   tabIncassoRegel
         inner join tabIncassoKop on (IncKopId = IncRglIncKopId)
  where  IncRglStatus = 1 /*Opdracht*/
     and IncRglIcmReferentie = @Referentie;

  //Controle op in gebruik zijn van de machtiging
  if @IncKopId is not null then
    set @Result = _U('Machtiging ''%1!'' wordt gebruikt in een incassoregel van opdracht %2! !\nWijzig eerst de status van de opdrachtregel.', @Referentie, right('000' + string(@IncKopId), 3));
    set @Fout = 1;
  end if;


  //Controler of de machtiging bestaat
  if @fout = 0 then
    if not exists(select first 1 from tabIncassoMachtiging where icmReferentie = @Referentie) then
      set @Result = _U('Machtiging ''%1!'' komt niet voor in deze administratie!', @Referentie);
      set @Fout = 1;
    end if;
  end if;


  //Controleer of de machtiging gebruikshistorie heeft
  if @fout = 0 then
    if not exists(select first 1 from tabIncassoMachtiging inner join tabIncassoMachtigingGebruikt on imgicmGid = icmGid where icmReferentie = @Referentie) then
      set @Result = _U('Machtiging ''%1!'' bestaat in deze administratie, maar is nog niet gebruikt!', @Referentie);
      set @Fout = 1;
    end if;
  end if;

  if @fout = 0 then
    if @isTest = 0 then
      //Gebruikshistorie van de machtigingen verwijderen
      delete tabIncassoMachtigingGebruikt
      where imgicmGid in (select icmGid from tabIncassoMachtiging where icmReferentie = @Referentie);
      set @AantalGewijzigd = @@rowcount;

      // Vermelden in log
      insert into tablog (LogSoort, LogAdmCode, LogBjCode, LogUserName, LogMachineName, LogOmschrijving, LogTimeStamp)
      select 6,
             db_property('alias'),
	     '',
	     @@Gebruikercode,
	     @@Machinename,
	     _A('Gebruikshistorie incassomachtiging ''%1!'' is geannuleerd. (%2! keer gebruikt)', @Referentie, string(@AantalGewijzigd)),
	     now();
      set @Result = _U('Gebruikshistorie van machtiging %1! is geannuleerd. De machtiging was %2! keer gebruikt.', @Referentie, string(@AantalGewijzigd));
    end if;
  end if;
end;


//$Workfile: VerwijderHistorischeMagazijnOntvangsten.sp $ $Revision: 1 $ $Modtime: 03-10-11 8:22 $'

// ---------- historische magazijnontvangsten/directe leveringen verwijderen t/m ontvangstdatum ----------
if exists (select 1 from sys.sysProcedure where proc_name='VerwijderHistorischeMagazijnOntvangsten') then
  drop procedure VerwijderHistorischeMagazijnOntvangsten;
end if;

create procedure VerwijderHistorischeMagazijnOntvangsten(in @OntvangstDatum  datetime)
begin
  set @@ErrorTextProcedure = 'VerwijderHistorischeMagazijnOntvangsten > @OntvangstDatum ='+string(@OntvangstDatum );
  //call TraceBegin(@@ErrorTextProcedure);

	delete from tabMagazijnOntvangstHistBatch
	where MohbStatus in (1,2)
	and MohbGid in (select MohkMohbGid
									from tabMagazijnOntvangstHistKop
									where MohkOntvangstDatum <= @OntvangstDatum);

  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure VerwijderMachtigingsGebruikUitIncassoRegel(in @IncKopId integer)
begin
  //declare @DatumGebruik Date;
  set @@ErrorTextProcedure = 'VerwijderMachtigingsGebruikUitIncassoRegel > @InkKopId  = ' + string(@IncKopId);
  //call TraceBegin(@@ErrorTextProcedure);

  //ACW 27-11-2012 onderdeel #54317: De incassodatum is van belang, niet de incassodatum!
  //De aanmaakdatum is van belang!! dat is de datum waarop de machtiging wordt gebruikt
  //select IncKopOpdrachtDatum into @DatumGebruik from tabIncassoKop where IncKopId = @IncKopId;

  for @OpschonenMachtigingen as CURSOR_OpschonenMachtigingen CURSOR FOR
    select IncRglIcmGid @icmGid,
           IncRglDatum @DatumGebruik
    from   tabIncassoRegel
    where  IncRglIncKopId = @IncKopId
    order by @icmGid
  for read only do
    //Datum verwijderen
    delete first tabIncassoMachtigingGebruikt
    where imgicmGid = @icmGid
      and date(imgDatumGebruikt) = @DatumGebruik
     order by imgDatumGebruikt desc;
  end for;
  // En uit incassoregeltabel halen
  update tabIncassoRegel
  set    IncRglIcmGid = null
  where  IncRglIncKopId = @IncKopId;
  //call TraceEind(@@ErrorTextProcedure);
end;


// ---------- Prijsafspraken verwijderen van een bepaalde combi ----------
create or replace procedure VerwijderPrijsAfspraken(in @PraCombisoort smallint, in @PraArtGid integer, in @PraNawGid integer, in @PraDebgrpGid integer, in @PraOpbrGrpGid integer)
begin
  declare @WhereClause nchar(255);

  set @@ErrorTextProcedure = 'VerwijderPrijsAfspraken > @PraCombisoort='+string(@PraCombisoort)+
                                                      ' @PraArtGid='+string(@PraArtGid)+
                                                      ' @PraNawGid='+string(@PraNawGid)+
                                                      ' @PraDebgrpGid='+string(@PraDebgrpGid)+
                                                      ' @PraOpbrGrpGid='+string(@PraOpbrGrpGid);
  //call TraceBegin(@@ErrorTextProcedure);

  case @PraCombisoort
    when 1 then   //prijsafspraak debiteurgroep/opbrengstgroep
      if isNull(@PraDebgrpGid,0) <> 0 then   set @WhereClause = ' and PraDebgrpGid = @PraDebgrpGid' end if;
      if isNull(@PraOpbrGrpGid,0) <> 0 then set @WhereClause = ' and PraOpbrGrpGid = @PraOpbrGrpGid' end if;
    when 2 then   //prijsafspraak debiteurgroep/artikel
      if isNull(@PraDebgrpGid,0) <> 0 then   set @WhereClause = ' and PraDebgrpGid = @PraDebgrpGid' end if;
      if isNull(@PraArtGid,0) <> 0 then     set @WhereClause = ' and PraArtGid = @PraArtGid' end if;
    when 3 then   //prijsafspraak debiteur/opbrengstgroep
      if isNull(@PraNawGid,0) <> 0 then     set @WhereClause = ' and PraNawGid = @PraNawGid' end if;
      if isNull(@PraOpbrGrpGid,0) <> 0 then set @WhereClause = ' and PraOpbrGrpGid = @PraOpbrGrpGid' end if;
    when 4 then   //prijsafspraak debiteur/artikel
      if isNull(@PraNawGid,0) <> 0 then     set @WhereClause = ' and PraNawGid = @PraNawGid' end if;
      if isNull(@PraArtGid,0) <> 0 then     set @WhereClause = ' and PraArtGid = @PraArtGid' end if;
    end case;

  execute immediate 'delete from tabPrijsAfspraak where PraCombiSoort = @PraCombisoort' || @WhereClause;

  //call TraceEind(@@ErrorTextProcedure);
end;


