create or replace procedure VerzamelTabelLegen(in @SessieNummer integer)
begin

  set @@ErrorTextProcedure = 'Begin VerzamelTabelLegen(SessieNummer='+string(@SessieNummer);
  //call Trace(@@ErrorTextProcedure);

  // orders zoeken en eventueel unlocken
  for @Cursor AS CURSOR_VerzamelLijst CURSOR FOR
      select vnaOrkGid @vnaOrkGid, vnaLockedByMe @vnaLockedByMe
      from   tabVerzamelNietAfgedrukt
      where  vnaSessieNummer = @SessieNummer
  for read only
  do
      delete from tabVerzamelNietAfgedrukt where vnaOrkGid = @vnaOrkGid and vnaSessieNummer =  @SessieNummer;
      if @vnaLockedByMe = 1 then
       call LockReleaseOnId(@@spid, @@LoginTime , 1, 'tabOrderKop', @vnaOrkGid );
      end if;
  end for;

  call LockReleaseOnId(@@spid, @@LoginTime , 1, 'tabVerzamelNietAfgedrukt', @SessieNummer );

  set @@ErrorTextProcedure = 'Einde VerzamelTabelLegen';
  //call Trace(@@ErrorTextProcedure);
end;


create or replace procedure VerzamelTabelVullen(
  in @AfdrukPer integer,  // 1 = Afdruk per order, 2 = Afdruk per locatie
  in @VanMag integer,
  in @TotMag integer,
  in @VanLoc nchar(20),
  in @TotLoc nchar(20),
  in @VanOrk numeric(10,0),
  in @TotOrk numeric(10,0),
  in @EersteDatum date,
  in @LaatsteDatum date,
  in @selectie integer,  // 1 = NAW-nummer, 2 = NAW-zoekcode, 3 = NAW-naam
  in @VanNaw nchar(40),
  in @TotNaw nchar(40),
  in @VerzamellijstGebruiken integer,  // 0 = maakt niet uit, 1 = alleen orders met verzamellijst gebruiken
  in @AlreadyLockedOrkGid integer,
  in @JobVerwerkingId integer,
  out @SessieNummer integer,
  in @OokLegeLocatie smallint default 1)
begin

  declare @Result integer;

  set @@ErrorTextProcedure = 'VerzamelTabelVullen(@AfdrukPer='+string(@AfdrukPer)+',@VanMag='+string(@VanMag)+', @TotMag='+String(@TotMag)+',@VanLoc='+string(@VanLoc)+',@TotLoc='+string(@TotLoc)+', @VanOrk='+string(@VanOrk)+',@TotOrk='+string(@TotOrk)+',@EersteDatum='+string(@EersteDatum)+', @LaatsteDatum='+string(@LaatsteDatum)+', @selectie='+string(@selectie)+', @VanNaw='+string(@VanNaw)+', @TotNaw='+string(@TotNaw)+', @VerzamellijstGebruiken='+string(@VerzamellijstGebruiken)+', @AlreadyLockedOrkGid='+string(@AlreadyLockedOrkGid)+', @SessieNummer='+string(@SessieNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  // Nieuw Sessienummer aanmaken
  SessieNummerLoop:
  loop
    call RandomNumber2(@SessieNummer);
    call LockSetOnId(@@spid, @@LoginTime , 1, 'tabVerzamelNietAfgedrukt', @SessieNummer, @Result );
    if @Result = 0 then
      leave SessieNummerLoop;
    end if;
  end loop SessieNummerLoop;

  // Opzoeken van de af te drukken orders
  insert into tabVerzamelNietAfgedrukt (vnaSessieNummer, vnaOrkGid, vnaReden, vnaLockedByMe)
  select distinct
    @SessieNummer,
    OrkGid,
    (if OrkGoedGekeurd = 0 then
       1 // Order niet goedgekeurd
    else
      if (OrkVrijVoorVerzamellijst = 0) and (Isnull(OrkIsVerzamellijstGebruiken, 0) <> 0) then
        2 // Order nog niet vrij voor verzamellijst
      else
        if (OrkVerzamellijstAfgedrukt <> 0) and (Isnull(OrkIsVerzamellijstGebruiken, 0) <> 0) then
           3 // Order reeds afgedrukt
        else
          if (select count(*) from tabOrderRegel where OrrOrkGid = OrkGid) = 0 then
            5
          else
           0
          endif
        endif
      endif
    endif) Reden,
    0
  from
    tabOrderKop
    inner join tabNaw               		on (OrkNawGid = NawGid)
    inner join tabNawFile           		on (NAWFilNawGid = NawGid and NAWFilFonId = 'D')
    left outer join tabOrderRegel        	on  OrrOrkGid = OrkGid
    left outer join tabOrderRegelLocatie 	on  OrlOrrGid = OrrGid
    left outer join tabLocatie           	on  OrlLocGid = LocGId
    inner join tabAdres             		on (AdrGid = NawGidVestiging)
    left outer join tabMagazijn          	on (MagGid = (if @AfdrukPer = 1 then OrkDefaultMagGid else isnull(OrlMagGid, OrrMagGid) endif) )
    left outer join tabJobImportVerwerking on JobivJobVerwerkingId = @JobVerwerkingId and OrkGid = JobivImportRecordGid
  where
//     exists(select 1 from tabOrderRegel where OrrOrkGid = OrkGid) // ook orderregelsoort anders dan artikel meenemen
//     and
    OrkSoort = 0
    and
    (
      (@JobVerwerkingId <> -1 and JobivGid is not null) // Via jobs allemaal!
      or
      ( // Niet via jobs, dus selecteren
        (@JobVerwerkingId = -1)
        and
        (  // Van t/m leverdatum
          ((@EersteDatum  is null or OrkLeverDatum >= @EersteDatum) and
           (@LaatsteDatum is null or OrkLeverDatum <= @LaatsteDatum)) or
            OrkLeverdatum is null
        )
        and
        ( // Afdruk = per order -> van t/m ordernummer
          // Afdruk = per locatie -> van t/m magazijn, als range van 1 magazijn, dan van t/m locatie
          (@AfdrukPer = 1 and OrkNummer between @VanOrk  and @TotOrk ) or
          (@AfdrukPer = 2 and @VanMag = @TotMag and ((@OokLegeLocatie = 1 and LocNaam is null) or LocNaam between @VanLoc and @TotLoc)) or
          (@AfdrukPer = 2 and @VanMag <> @TotMag )
        )
        and
        (  // Lege orders en
           // orders met tarief/teisktregels en
           // gevulde orders met magazijn van specificatieregel (of, indien geen spec.regels, de orderregel) en
          not exists(select 1 from tabOrderRegel where OrrOrkGid = OrkGid) or 		// Order zonder orderregels ook selecteren
          (MagCode between @VanMag and @TotMag) or
          (OrrRegelSoort <> 2)  		      // Order met orderregels
        )
        and
        (  // Selectie van t/m debiteur
          (@selectie = 1 and NawFilNummer   between @VanNaw and @TotNaw) or
          (@selectie = 2 and NawFilZoekcode between @VanNaw and @TotNaw) or
          (@selectie = 3 and AdrNaam1       between @VanNaw and @TotNaw)
        )
        and
        ( // keuze zonder verzamellijst -> geen verzamellijst-beperking
          // keuze verzamellijst verplicht -> alleen orders met verzamellijst gebruiken
          (@VerzamellijstGebruiken = 0) or
          (@VerzamellijstGebruiken = 1 and Isnull(OrkIsVerzamellijstGebruiken,0) = 1)
        )
      )
    );

  // Gevonden orders proberen te locken
  for @Cursor AS CURSOR_VerzLijst cursor for
      select vnaOrkGid @vnaOrkGid
      from   tabVerzamelNietAfgedrukt
      where  vnaSessieNummer = @SessieNummer
  for update
  do
    if (@AlreadyLockedOrkGid is null) OR (@AlreadyLockedOrkGid <> @vnaOrkGid) then
      call LockSetOnId(@@spid, @@LoginTime , 1, 'tabOrderKop', @vnaOrkGid, @Result );
      if @Result = 0 then
        update tabVerzamelNietAfgedrukt set vnaLockedByMe = 1 where current of CURSOR_VerzLijst
      else
        update tabVerzamelNietAfgedrukt set vnaReden = 4      where current of CURSOR_VerzLijst; // Order is in gebruik
      end if;
    end if;
  end for;

  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure VoertuigkostenAanmakenBoeking(
  in @vrtKstGid integer,
  in @BoekgangGid integer
)
begin
  declare @BjGid                                integer;
  declare @BoekstukNummer                       numeric(10,0);
  declare @PeriodeNummmerVoertuigKostenBoeking  integer;
  declare @ValNummer                            integer;
  declare @Bedrag                               numeric(15,2);
  declare @BTWBedrag                            numeric(15,2);
  declare @BasisBedrag                          numeric(15,2);
  declare @BasisBTWBedrag                       numeric(15,2);
  declare @HulpBedrag                           numeric(15,2);
  declare @BoekingsOmschrijving                 nchar(40);

  declare @BMCode                               nchar(20);
  declare @VrtKstBedrag                         numeric(15,2);
  declare @VrtKstBtwCode                        integer;
  declare @BoekDatum                            date;
  declare @VrtKstIsIncBTW                       integer;
  declare @VrtKstOmschrijving                   nchar(40);
  declare @BTWPercentage                        numeric(6,2);
  declare @VksDefBoekingsOmschrijving           nchar(40);
  declare @VrtKstJPGID                          integer;
  declare @VrtKstpGid                           integer;
  declare @VrtKstdGid                           integer;
  declare @RksGid                               integer;
  declare @RksGidTegen                          integer;

  declare @DgbGid                               integer;
  declare @VrtVgDefBoekstuknummer               smallint;

  declare @AantDecimalenBasis                   integer;

  declare @BtwRekening                          integer;
  declare @BtwValNummer                         integer;
  declare @DarGid                               integer;

  set @@ErrorTextProcedure = 'Begin VoertuigkostenAanmakenBoeking > @vrtKstGid='+string(@vrtKstGid)+', @BoekgangGid='+string(@BoekgangGid);
  //call Trace(@@ErrorTextProcedure);

  //Ophalen informatie uit de voertuigkosten
  select
    BmCode,
    VrtKstBedrag,             //Omschrijving van de voertuigkosten
    VrtKstBtwCode,            //BTW code van de voertuigkosten
    VrtKstBoekDatum,          //Datum waarop de voertuigkosten zijn gemaakt
    VrtKstIsIncBTW,           //Voertuigkosten zijn wel/niet inclusief BTW
    VrtKstOmschrijving,       //Omschrijving van de journaalpost
    BtwPercentage,
    VksDefBoekingsOmschrijving,
    VrtKstJPGID,                  //Er is aan een boeking gedaan. Tegenboeken en nieuwe aanmaken
    VrtKstpGid,
    VrtKstdGid,
    VrtKstRksGID,      //Rekening van autoKosten
    VrtKstRksGidTegen,  //TegenRekening van autoKosten
    VrtKstDarGid        // Digitaal archief
  into @BMCode, @VrtKstBedrag, @VrtKstBtwCode, @BoekDatum, @VrtKstIsIncBTW, @VrtKstOmschrijving, @BTWPercentage, @VksDefBoekingsOmschrijving, @VrtKstJPGID, @VrtKstpGid, @VrtKstdGid, @RksGid, @RksGidTegen, @DarGid
  from tabVoertuigKosten
  inner join tabVoertuigKostenSoort on VksGid = VrtKstVksGid
  inner join (tabVoertuig inner join tabBedrijfsMiddel on BMGid = VrtBMGid) on vrtGid = VrtKstVrtGid
  left outer join tabBTW on Btwcode = VrtKstBtwCode
  where VrtKstGid = @VrtKstGid;

  set @BoekingsOmschrijving = replace(replace(@VksDefBoekingsOmschrijving, '<KENTEKEN>', @BMCode), '<OMS>', @VrtKstOmschrijving);

  // Alleen als er dus een KP/KD meegegeven wordt dan gaan we verder om er een op te zoeken en evt aan te maken
  if not(@VrtKstpGid is null) or not(@VrtKstdGid is null) then
    call ZoekOfMaakRksMetKstpKstd(@RksGid, @VrtKstpGid, @VrtKstdGid, @RksGid);
    //call ZoekOfMaakRksMetKstpKstd(@RksGidTegen, @VrtKstpGid, @VrtKstdGid, @RksGidTegen);
  end if;

  //Bepaal de periode voor boeken
  call BepaalBoekjaarEnPeriode(@BoekDatum, @BjGid, @PeriodeNummmerVoertuigKostenBoeking);

  //Dagboek en boekstuknummer opvragen uit de vaste gegevens
  select first VrtVgDgbGid,VrtVgDefBoekstuknummer into @DgbGid,@VrtVgDefBoekstuknummer from tabVoertuigVasteGegevens;

  call BoekstuknummerPlusEen(@BjGid, @DgbGid, @VrtVgDefBoekstuknummer, @BoekstukNummer);

  //Aantal decimalen bij boeking in de basisvaluta
  select DecimalenBoeking*2 into @AantDecimalenBasis from tabvaluta where ValNummer=@@BasisValutaNummer;

  //Als er een @VrtKstJPGID is ingevuld, maak dan eerst hiervan een tegenboeking.
  if not @VrtKstJPGID is null then
    call VoertuigkostenAanmakenTegenBoeking(@BoekGangGid,@BoekStukNummer,@BoekDatum,@VrtKstJPGID);
    update tabVoertuigKosten set VrtKstJpGID = null where VrtKstGid = @VrtKstGid;
  end if;

  //Bedrag en basisbedrag berekenen Excl. BTW wel
  set @ValNummer    = @@BasisValutaNummer; //Nu is het valuta gewoon de basisvaluta

  if (@VrtKstIsIncBTW = 1) then   //Inclusief BTW
    set @BTWBedrag  = round(((@VrtKstBedrag / (100+ (@BTWPercentage))) * @BTWPercentage), @AantDecimalenBasis);
    set @Bedrag     = round((@VrtKstBedrag / (100+ (isnull(@BTWPercentage,0)))) * 100, @AantDecimalenBasis);
  else                            //Exclusief BTW
    set @BTWBedrag  = round((@VrtKstBedrag / 100) * @BTWPercentage, @AantDecimalenBasis);
    set @Bedrag     = round(@VrtKstBedrag, @AantDecimalenBasis);
  end if;

  set @BasisBTWBedrag = round(ValutaOmrekenen(@ValNummer, @BTWBedrag, @@BasisValutaNummer , @BjGid, @PeriodeNummmerVoertuigKostenBoeking, 2), @AantDecimalenBasis);
  set @BasisBedrag    = round(ValutaOmrekenen(@ValNummer, @Bedrag   , @@BasisValutaNummer , @BjGid, @PeriodeNummmerVoertuigKostenBoeking, 2), @AantDecimalenBasis);

  if (@Bedrag <> 0) then
    // maak journaalpost aan
    insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum)
    select @BoekGangGid, 1, @DgbGid, @BoekstukNummer, @BoekingsOmschrijving, @BoekDatum;

    //Maak journaalregel aan
    insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel   , IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum, JrDarGid)
                          values(@@JpGid, @RksGid , @Bedrag       , @BasisBedrag , @BoekingsOmschrijving, 0              , 0           , @ValNummer , @BoekDatum, @DarGid);


  /*  //BTW??? Hulprekening
  Deze word nu nog niet gedaan. Dit omdat je met je inkoop zit die al incl btw boekt.
    if not(@VrtKstBtwCode is null) then
      select BtwRksGid, RksValNummer into @BtwRekening, @BtwValNummer from tabBtw inner join tabRekeningSchema on (RksGid = BtwRksGid) where BtwCode = @VrtKstBtwCode;
      set @HulpBedrag = round(ValutaOmrekenen(@ValNummer, @BTWBedrag, @BtwValNummer, @BjGid, @PeriodeNummmerVoertuigKostenBoeking, 2), (select DecimalenBoeking*2 from tabvaluta where ValNummer=@BtwValNummer));
    //  set @Bedrag = ValutaOmrekenen(@BtwValNummer, @HulpBedrag, @@BasisValutaNummer, @BjGid, @PeriodeNummmerVoertuigKostenBoeking, 2);
      insert into tabHulprekening (hulprekBasisBedrag, hulprekValnummer, hulprekValutaBedrag, hulprekSoort, hulprekIsCredit, hulprekRksgid, HulprekBtwCode, hulprekJrGid)
                           values (@BasisBTWBedrag   , @BtwValNummer   , @HulpBedrag        , 1           , 1              ,  @BtwRekening, @VrtKstBtwCode, @@JrGid);
    end if;
  */

    //Boeking maken op tussenrekening.
    if not(@RksGidTegen is null) then
      insert into tabJournaalRegel(JrJpGid, JrRksGid    , JrValutaBedrag       , JrBasisBedrag                  , OmsJournaalRegel   , IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum)
                            values(@@JpGid, @RksGidTegen, (@Bedrag), (@BasisBedrag), @BoekingsOmschrijving, 1              , 0           , @ValNummer , @BoekDatum);
    end if;

    //JpGId bij de voertuigkosten zetten
    update tabVoertuigKosten set VrtKstJpGID = @@JpGid where VrtKstGid = @VrtKstGid;

    //Journaalpost is niet meer in gebruik...
    update tabJournaalPost set JpIsIngebruik = 0 where jpGid = @@JpGid;
  end if;

  set @@ErrorTextProcedure = 'Einde VoertuigkostenAanmakenBoeking';
  //call Trace(@@ErrorTextProcedure);
end;


create or replace procedure VoertuigkostenAanmakenBoekingsgang( in @VrtKstGid integer, in @BoekDatum date, out @BoekgangGid integer, out @BjGid integer, out @PerNr integer)
begin
  //Aanmaken boeking voor de voertuigkosten
  set @@ErrorTextProcedure = 'VoertuigkostenAanmakenBoekingsgang > ';
  //call TraceBegin(@@ErrorTextProcedure + '@VrtKstGid = ' + string(@VrtKstGid) + ', @BoekDatum = ' + string(@BoekDatum));

  //boekdatum leeg -> systeemdatum gebruiken
  if @BoekDatum is null then
    set @BoekDatum = now();
  end if;

  //Vaste gegevens opvragen
  call BepaalBoekjaarEnPeriode(@BoekDatum, @BjGid, @PerNr);

  //Aanmaken van nieuwe boekingsgang en locken
  //Controleer of er al een boekingsgang tbv. voertuigkosten bestaat. Zoja, dan die gebruiken, zoniet dan 1 aanmaken
  set @BoekgangGid = null;
  select qlockpkey into @BoekgangGid from qtablock where qlockconnection = @@spid and qlocktablename = 'Voertuigkosten';

  if @BoekgangGid is null then
    insert into tabBoekingsGang(BoekGangBjGid, BoekGangBronId, BronOms, BoekGangInGebruik, IsBoekGangDefinitief) values (@BjGid, 35, _A('Autokosten'), 1, 0);
    set @BoekgangGid = @@Identity;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'Voertuigkosten', @BoekgangGid, 0);
  end if;

  set @@ErrorTextProcedure = 'VoertuigkostenAanmakenBoekingsgang';
  //call TraceEind('VoertuigkostenAanmakenBoekingsgang');
end;

create or replace procedure  VoertuigkostenAanmakenTegenBoeking(
  in @BoekGangGid     integer,
  in @BoekstukNummer  numeric(10,0),
  in @BoekDatum       date,
  in @VrtKstJPGID     integer
)

begin
  declare @BjGid                                integer;
  declare @PeriodeNummmerVoertuigKostenBoeking  integer;
  declare @DgbGid                               integer;
  declare @VrtVgDefBoekstuknummer               smallint;


  set @@ErrorTextProcedure = 'Begin VoertuigkostenAanmakenTegenBoeking > @BoekGangGid='+string(@BoekGangGid)+',@BoekStukNummer='+string(@BoekStukNummer)+',@BoekDatum='+string(@BoekDatum)+',@VrtKstJPGID='+string(@VrtKstJPGID);
  //call Trace(@@ErrorTextProcedure);

  if @BoekstukNummer is null then
    //Bepaal de periode voor boeken
    call BepaalBoekjaarEnPeriode(@BoekDatum, @BjGid, @PeriodeNummmerVoertuigKostenBoeking);

    //Dagboek en boekstuknummer opvragen uit de vaste gegevens
    select first VrtVgDgbGid,VrtVgDefBoekstuknummer into @DgbGid,@VrtVgDefBoekstuknummer from tabVoertuigVasteGegevens;

    call BoekstuknummerPlusEen(@BjGid, @DgbGid, @VrtVgDefBoekstuknummer, @BoekstukNummer);
  end if;

  // maak journaalpost aan
  insert into tabJournaalPost(JpBoekGangGid, JpIsIngebruik, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum)
  select @BoekGangGid, 1, JpDgbGid, @BoekStukNummer, OmsJournaalpost, @BoekDatum
  from tabJournaalPost
  where JpGid = @VrtKstJPGID;

  //Maak journaalregel aan
  insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, OmsJournaalRegel   , IsCreditBoeking, SoortBoeking, JrValNummer, JrBoekdatum, jrDarGid)
  select @@JpGid, JrRksGid, -JrValutaBedrag, -JrBasisBedrag, OmsJournaalRegel   , IsCreditBoeking, SoortBoeking, JrValNummer, @BoekDatum, JrDarGid
  from tabJournaalRegel
  where JrJpGid = @VrtKstJPGID;

  //JpGId bij de voertuigkosten zetten
  update tabVoertuigKosten set VrtKstJpGID = null where VrtKstJPGid = @VrtKstJPGID;

  //Journaalpost is niet meer in gebruik...
  update tabJournaalPost set JpIsIngebruik = 0 where jpGid = @@JpGid;

  set @@ErrorTextProcedure = 'Einde VoertuigkostenAanmakenTegenBoeking';
  //call Trace(@@ErrorTextProcedure);
end;

create or replace procedure VoertuigKostenInclActiva(in @VrtKstVrtGid integer, in @ActkGid integer)
result (
  VrtKstBedragExcl        numeric(15,3),
  VrtKstBedragIncl        numeric(15,3),
  VrtKstBtwCode           integer,
  VrtKstDatum             date,
  VrtKstGid               integer,
  VrtKstIsIncBTW          smallint,
  VrtKstKilometerstand    integer,
  VrtKilometerEersteToelating  integer,
  VrtKstTijdvakBegin      date,
  VrtKstTijdvakEind       date,
  AantalDagen             integer,
  VrtKstLiters            numeric(15,3),
  VrtKstOmschrijving      nchar(40),
  VrtKstVksGid            integer,
  VksCode                 nchar(20),
  VrtKstVrtGid            integer,
  ActmhMutatiesoort       smallInt,
  VrtKstBoekingMaken      smallint,
  VrtKstBoekDatum         date,
  VrtKstRksGID            integer,
  VrtKstRksGIDTegen       integer,
  VrtKstJPGID             integer,
  VrtKstDarGid            integer
)

begin
  declare local temporary table tmpVoertuigKosten(
  VrtKstBedragExcl        numeric(15,3),
  VrtKstBedragIncl        numeric(15,3),
  VrtKstBtwCode           integer,
  VrtKstDatum             date,
  VrtKstGid               integer,
  VrtKstIsIncBTW          smallint,
  VrtKstKilometerstand    integer,
  VrtKilometerEersteToelating  integer,
  VrtKstTijdvakBegin      date,
  VrtKstTijdvakEind       date,
  AantalDagen             integer,
  VrtKstLiters            numeric(15,3),
  VrtKstOmschrijving      nchar(40),
  VrtKstVksGid            integer,
  VksCode                 nchar(20),
  VrtKstVrtGid            integer,
  ActmhMutatiesoort       smallInt,
  VrtKstBoekingMaken      smallint,
  VrtKstBoekDatum         date,
  VrtKstRksGID            integer,
  VrtKstRksGIDTegen       integer,
  VrtKstJPGID             integer,
  VrtKstDarGid            integer)
  on commit preserve rows;

  declare @BmAfschrijvingInclBTW  smallint;
  declare @vksGidActiva           integer;
  declare @vksCodeActiva          nchar(20);

  declare @ActivaAfschrijvingTekst   long nvarchar;

  set @@ErrorTextProcedure = 'VoertuigKostenInclActiva > Inlezen VoertuigKosten';
  //call Trace(@@ErrorTextProcedure);

  set @ActivaAfschrijvingTekst = _U('Activa Afschr termijn: %1!');

  //Afschrijvingen inclusief BTW?
  select BmAfschrijvingInclBTW into @BmAfschrijvingInclBTW from tabBedrijfsMiddel inner join tabVoertuig on vrtBmGid = bmgid where VrtGid = @VrtKstVrtGid;

  select isNull(vksGid,999),vksCode into @vksGidActiva,@vksCodeActiva from tabVoertuigKostenSoort where vksSoort = 4; //Activa vksGid

  insert into tmpVoertuigKosten(VrtKstBedragExcl, VrtKstBedragIncl, VrtKstBtwCode, VrtKstDatum, VrtKstGid, VrtKstIsIncBTW, VrtKstKilometerstand, VrtKilometerEersteToelating,
    VrtKstTijdvakBegin, VrtKstTijdvakEind, AantalDagen, VrtKstLiters, VrtKstOmschrijving, VrtKstVksGid, VksCode, VrtKstVrtGid,
    VrtKstBoekingMaken, VrtKstBoekDatum, VrtKstRksGID, VrtKstRksGIDTegen, VrtKstJPGID, VrtKstDarGid)
  select
    VrtKstBedrag - (if VrtKstIsIncBTW = 1 then VrtKstBedragBTW else 0 endif),   //Exclusief BTW
    VrtKstBedrag + (if VrtKstIsIncBTW = 0 then VrtKstBedragBTW else 0 endif),   //Inclusief BTW
    VrtKstBtwCode,
    VrtKstDatum,
    VrtKstGid,
    VrtKstIsIncBTW,
    VrtKstKilometerstand,
    VrtKilometerEersteToelating,
    //if vksSoort in (2,3) then VrtKstDatum else VrtKstTijdvakBegin endif,
    VrtKstTijdvakBegin,
    VrtKstTijdvakEind,
    Days360(VrtKstTijdvakBegin,VrtKstTijdvakEind) Aantaldagen,
    //isNull(VrtKstTijdvakEind-VrtKstTijdvakBegin,0) AantalDagen,
    VrtKstLiters,
    VrtKstOmschrijving,
    VrtKstVksGid,
    VksCode,
    VrtKstVrtGid,
    VrtKstBoekingMaken,
    VrtKstBoekDatum,
    VrtKstRksGID,
    VrtKstRksGIDTegen,
    VrtKstJPGID,
    VrtKstDarGid
  from tabVoertuigKosten
  inner join tabVoertuigKostenSoort on (VksGid = VrtKstVksGid)
  inner join tabVoertuig on (VrtGid = VrtKstVrtGid)
  left outer join TabBTW on (BtwCode = VrtKstBtwCode)
  where VrtKstVrtGid = @VrtKstVrtGid;

  set @@ErrorTextProcedure = 'VoertuigKostenInclActiva > Inlezen Activa';
  //call Trace(@@ErrorTextProcedure);

  insert into tmpVoertuigKosten(VrtKstVrtGid, VrtKstVksGid, VksCode, VrtKstBedragExcl, VrtKstBedragIncl, VrtKstDatum, VrtKstOmschrijving, ActmhMutatiesoort,VrtKstKilometerstand, VrtKstTijdvakBegin, VrtKstTijdvakEind, AantalDagen)
  select
    @VrtKstVrtGid,
    @vksGidActiva,
    @vksCodeActiva,
    ActatBedragAfschrijving,
    if @BmAfschrijvingInclBTW = 1 then ActatBedragAfschrijving endif,
    ActatDatumAfschrijving,
    _P(@ActivaAfschrijvingTekst, string(ActatNummer)),
    ActmhMutatiesoort,
    0,
    ActatDatumAfschrijving as VrtKstTijdvakBegin,
    case ActkAfschrBoekenPer
      when 0 then dateadd(day, -1 , dateadd(year  , 1, ActatDatumAfschrijving))
      when 1 then dateadd(day, -1 , dateadd(month , 3, ActatDatumAfschrijving))
      when 2 then dateadd(day, -1 , dateadd(month , 1, ActatDatumAfschrijving))
      when 3 then dateadd(day, -1 , dateadd(week  , 4, ActatDatumAfschrijving))
    end as VrtKstTijdvakEind,
    Days360(VrtKstTijdvakBegin,VrtKstTijdvakEind) Aantaldagen
//    isNull(VrtKstTijdvakEind-VrtKstTijdvakBegin,0) AantalDagen
  from (
     select
      ActatDatumAfschrijving,
      4 ActmhMutatiesoort,
      ActatNummer,
      ActatBedragAfschrijving,
      ActkAfschrBoekenPer
    from tabActivaAfschrijvingstermijn
    inner join tabActivaKop on ActkGid = ActatActkGid
    left outer join tabActivaMutatieHistorie on ActmhActkGid = ActatActkGid  and ActatActmhGid = ActmhGid
    where ActatActkGid = @ActkGid
   ) TabAfschr;

  select  VrtKstBedragExcl,
          VrtKstBedragIncl,
          VrtKstBtwCode,
          VrtKstDatum,
          VrtKstGid,
          VrtKstIsIncBTW,
          VrtKstKilometerstand,
          VrtKilometerEersteToelating,
          VrtKstTijdvakBegin,
          VrtKstTijdvakEind,
          AantalDagen,
          VrtKstLiters,
          VrtKstOmschrijving,
          VrtKstVksGid,
          VksCode,
          VrtKstVrtGid,
          ActmhMutatiesoort,
          VrtKstBoekingMaken,
          VrtKstBoekDatum,
          VrtKstRksGID,
          VrtKstRksGIDTegen,
          VrtKstJPGID,
          VrtKstDarGid
  from tmpVoertuigKosten;

  set @@ErrorTextProcedure = 'VoertuigKostenInclActiva';
  //call TraceEind(@@ErrorTextProcedure);
end;
//call VoertuigKostenInclActiva(19,8);

create or replace function VoldoetAanKnoop(in @Bestand integer, in @SkGid integer, in @EersteGid integer, in @TweedeGid integer)
returns integer
begin
  //---- functie controleert of een Naw of Contactpersoon voldoet aan de eisen van de knoop
  declare @Operator               integer;
  declare @SlcGid                 integer;
  declare @VoldoetAanKnoop        integer;
  declare @CodeAanwezig           integer;
  declare @HuidigeKnoop           integer;
  declare @VorigeKnoop            integer;
  declare @VoldoetAanHuidigeKnoop integer;

  set @@ErrorTextProcedure = 'VoldoetAanKnoop > ';
  //call TraceBegin(@@ErrorTextProcedure + 'Bestand = ' + string(@Bestand) + ', SkGid = ' + string(@SkGid));

  // Betekenis van @Bestand en @EersteGid en @TweedeGid
  //
  // bij Bestand = 1 --> Naws            --> @EersteGid = NawFilGid, @TweedeGid = Niet Gebruikt
  // bij Bestand = 2 --> Contactpersonen --> @EersteGid = RelGid, @TweedeGid = Niet Gebruikt

  //gegevens van de knoop ophalen
  set @Operator  = null;
  set @Slcgid    = null;
  select skOperator, skSlcGid into @Operator, @SlcGid
  from   tabSelectieKnoop
  where  SkGid = @SkGid;

  // kijken naar de soort knoop
  if @Operator is null then   // geen knoop
    set @VoldoetAanKnoop = 1;
  else
    if @Operator = 0 then     // blad

      // kijken of code aanwezig is
      set @CodeAanwezig = null;
      // query hangt af van bestand
      if @Bestand = 1 then   // 1 = Naws
        select first 1 into @CodeAanwezig
        from   tabnawfile inner join tabSlcPerNaw on SpnNawFilGid = NawFilGid
        where  NawFilGid = @EersteGid and SpnSlcGid = @SlcGid;
      else                   // 2 = Contactpersonen
        select first 1 into @CodeAanwezig
        from   tabSlcPerRelatie
        where  SprRelGid = @EersteGid and SprSlcGid = @SlcGid;
      end if;

      if @CodeAanwezig is null then
        set @VoldoetAanKnoop = 0;
      else
        set @VoldoetAanKnoop = 1;
      end if;

    else

      case @Operator
        when 1 then // and
          begin
            // om te voldoen moet aan ALLE knopen onder deze moet VOLDAAN worden
            // knopen doorlopen en stoppen als er een gevonden is die NIET voldoet, dan niet voldaan
            set @VoldoetAanKnoop = 1; // voldoet indien geen knopen
            set @VorigeKnoop = null;
            AndKnopenAflopen:
            loop
              set @HuidigeKnoop = null;
              // onderhangende knoop zoeken
              select min(SkGid) into @HuidigeKnoop
              from   tabSelectieKnoop
              where  (skParentSkGid = @SkGid) and ((@VorigeKnoop is null) or (SkGid > @VorigeKnoop));

              // zijn er geen onderliggende knopen meer?
              if @HuidigeKnoop is null then
                if @VorigeKnoop is not null then
                  set @VoldoetAanKnoop = 1;       // geen ontkenning gevonden
                end if;
                leave AndKnopenAflopen;
              end if;

              // controleren of er aan de onderliggende knoop voldaan is
              set @VoldoetAanHuidigeKnoop = VoldoetAanKnoop(@Bestand, @HuidigeKnoop, @EersteGid, @TweedeGid);

              // als niet voldaan aan onderhangende knoop, dan niet voldaan aan deze knoop
              if @VoldoetAanHuidigeKnoop = 0 then
                set @VoldoetAanKnoop = 0;
                leave AndKnopenAflopen;
              end if;

              // @VorigeKnoop vullen met @HuidigeKnoop zodat de volgende gevonden kan worden
              set @VorigeKnoop = @HuidigeKnoop;

            end loop AndKnopenAflopen;
          end;

        when 2 then // nand
          begin
            // om te voldoen moet aan MINSTENS EEN van de knopen onder deze NIET VOLDAAN worden
            // knopen doorlopen en stoppen als er een gevonden is die NIET voldoet, dan wel voldaan
            set @VoldoetAanKnoop = 1; // voldoet indien geen knopen
            set @VorigeKnoop = null;
            NandKnopenAflopen:
            loop
              set @HuidigeKnoop = null;
              // onderhangende knoop zoeken
              select min(SkGid) into @HuidigeKnoop
              from   tabSelectieKnoop
              where  (skParentSkGid = @SkGid) and ((@VorigeKnoop is null) or (SkGid > @VorigeKnoop));

              // geen knopen meer?
              if @HuidigeKnoop is null then
                if @VorigeKnoop is not null then
                  set @VoldoetAanKnoop = 0;       // geen bevestiging gevonden
                end if;
                leave NandKnopenAflopen;
              end if;

              // controleren of er aan de onderliggende knoop voldaan is
              set @VoldoetAanHuidigeKnoop = VoldoetAanKnoop(@Bestand, @HuidigeKnoop, @EersteGid, @TweedeGid);

              // als niet voldaan aan onderhangende knoop, dan voldaan aan deze knoop
              if @VoldoetAanHuidigeKnoop = 0 then
                set @VoldoetAanKnoop = 1;
                leave NandKnopenAflopen;
              end if;

              // @VorigeKnoop vullen met @HuidigeKnoop zodat de volgende gevonden kan worden
              set @VorigeKnoop = @HuidigeKnoop;

            end loop NandKnopenAflopen;
          end;

        when 3 then // or
          begin
            // om te voldoen moet aan MINSTENS EEN van de knopen onder deze VOLDAAN worden
            // knopen doorlopen en stoppen als er een gevonden is die WEL voldoet, dan wel voldaan
            set @VoldoetAanKnoop = 1; // voldoet indien geen knopen
            set @VorigeKnoop = null;
            OrKnopenAflopen:
            loop
              set @HuidigeKnoop = null;
              // onderhangende knoop zoeken
              select min(SkGid) into @HuidigeKnoop
              from   tabSelectieKnoop
              where  (skParentSkGid = @SkGid) and ((@VorigeKnoop is null) or (SkGid > @VorigeKnoop));

              // geen knopen meer?
              if @HuidigeKnoop is null then
                if @VorigeKnoop is not null then
                  set @VoldoetAanKnoop = 0;       // geen bevestiging gevonden
                end if;
                leave OrKnopenAflopen;
              end if;

              // controleren of er aan de onderliggende knoop voldaan is
              set @VoldoetAanHuidigeKnoop = VoldoetAanKnoop(@Bestand, @HuidigeKnoop, @EersteGid, @TweedeGid);

              // als voldaan aan onderhangende knoop, dan voldaan aan deze knoop
              if @VoldoetAanHuidigeKnoop = 1 then
                set @VoldoetAanKnoop = 1;
                leave OrKnopenAflopen;
              end if;

              // @VorigeKnoop vullen met @HuidigeKnoop zodat de volgende gevonden kan worden
              set @VorigeKnoop = @HuidigeKnoop;

            end loop OrKnopenAflopen;
          end;

        when 4 then // nor
          begin
            // om te voldoen mag aan GEEN van de knopen onder deze VOLDAAN worden
            // knopen doorlopen en stoppen als er een gevonden is die WEL voldoet, dan niet voldaan
            set @VoldoetAanKnoop = 1; // voldoet indien geen knopen
            set @VorigeKnoop = null;
            NorKnopenAflopen:
            loop
              set @HuidigeKnoop = null;
              // onderhangende knoop zoeken
              select min(SkGid) into @HuidigeKnoop
              from   tabSelectieKnoop
              where  (skParentSkGid = @SkGid) and ((@VorigeKnoop is null) or (SkGid > @VorigeKnoop));

              // geen knopen meer?
              if @HuidigeKnoop is null then
                if @VorigeKnoop is not null then
                  set @VoldoetAanKnoop = 1;       // geen ontkenning gevonden
                end if;
                leave NorKnopenAflopen;
              end if;

              // controleren of er aan de onderliggende knoop voldaan is
              set @VoldoetAanHuidigeKnoop = VoldoetAanKnoop(@Bestand, @HuidigeKnoop, @EersteGid, @TweedeGid);

              // als voldaan aan onderhangende knoop, dan niet voldaan aan deze knoop
              if @VoldoetAanHuidigeKnoop = 1 then
                set @VoldoetAanKnoop = 0;
                leave NorKnopenAflopen;
              end if;

              // @VorigeKnoop vullen met @HuidigeKnoop zodat de volgende gevonden kan worden
              set @VorigeKnoop = @HuidigeKnoop;

            end loop NorKnopenAflopen;
          end;

      end case;
    end if;
  end if;

  set @@ErrorTextProcedure = 'VoldoetAanKnoop';
  //call TraceEind(@@ErrorTextProcedure);
  return(@VoldoetAanKnoop);
end;


create or replace function VolgendeWerkdag(in @Date datetime, in @LndGid integer)
returns datetime
begin
  set @@ErrorTextProcedure = 'VolgendeWerkdag > @date= ' + string(@Date)+', @LndGid= ' + string(@LndGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //Eerst 1 dag erbij
  set @Date = DateAdd(day, 1, @Date);

  //Afhankelijk van dag in de week alsnog opschuiven; 1e dag in de week=Zondag!
  set @Date = CASE DATEPART(dw, @Date)
                WHEN 1 THEN DateAdd(day, 1, @Date) // Oeps, valt op zondag, dus 1 dag erbij
                WHEN 7 THEN DateAdd(day, 2, @Date) // Oeps, valt op zaterdag, dus 2 dagen erbij
                ELSE @Date
              END;

  // Hier eventueel nog controleren of de datum een vakantiedag is? (bijv. kerst, nieuwjaarsdag)
/*
  while IsWorkingDay(@Date, @LndGid) = 0
  loop
    set @Date = DATEADD(day, 1, @Date);
  end loop;
*/
  set @@ErrorTextProcedure = @@ErrorTextProcedure + ' -> ' + string(@Date);
  //call TraceEind(@@ErrorTextProcedure);
  // En weer terug geven
  return(@Date);
end;


create or replace function VolgendJrnummer(in @JpGid integer)
returns integer
begin
  declare @Jrnummer integer;

  //call TraceBegin('VolgendJrnummer > @JpGid = ' + string(@JpGid));

  select IsNull(max(JrNummer),0)+1 into @JrNummer from tabJournaalregel where JrJpGid=@JpGid;

  //call TraceEind('VolgendJrnummer > @JrNummer = ' + string(@JrNummer));
  return(@Jrnummer);

end;


create or replace function VolgendStukVolgnummer(in @JpGid integer)
returns integer
begin
  declare @StukVolgnummer integer;

  //call TraceBegin('VolgendStukVolgnummer > @JpGid = ' + string(@JpGid));

  select IsNull(max(StukVolgnr),0)+1 into @StukVolgnummer from tabJournaalregel where JrJpGid=@JpGid;

  if @StukVolgnummer > 999 then
    set @StukVolgnummer=999;
  end if;

  //call TraceEind('VolgendStukVolgnummer > @StukVolgnummer = ' + string(@StukVolgnummer););
  return(@StukVolgnummer);

end;


//---------------------------------------------------------------------------
//----------------------------Volgnummer projectmutatie genereren-------------
//---------------------------------------------------------------------------
create or replace procedure VolgnummerProjectMutGenereren(in @Forceer smallint, in @Herkomst smallint, out @Nummer numeric(10,0))
begin
  declare @Genereren numeric(10,0);
  declare @Startnummer numeric(10,0);
  declare @Volgendnummer numeric(10,0);
  declare @gevonden integer;
  declare @StartNrVeld nchar(40);

  //call TraceBegin('VolgnummerProjectMutGenereren');

  case @Herkomst
    when 0 then set @StartNrVeld = 'ProjVastStartnummer';
    when 1 then set @StartNrVeld = 'ProjVastStartNummerImportMutaties';
    when 2 then set @StartNrVeld = 'ProjVastStartNummerViaJournaal';
    when 3 then set @StartNrVeld = 'ProjVastStartNummerGekoppeldAanJournaal';
    when 4 then set @StartNrVeld = 'ProjVastStartnummerViaWerkbon';
    when 5 then set @StartNrVeld = 'ProjVastStartnummerViaWeekstaat';
    when 6 then set @StartNrVeld = 'ProjVastStartNummerImportMutaties';
  end case;

  // Als startnummer leeg, dan volgens Invoeren projectmutaties (dus eerste veld)
  execute immediate 'select ' || @StartNrVeld || ' into @Startnummer from tabProjectVastegegevens;';

  if @Startnummer = 0 then
    set @StartNrVeld = 'ProjVastStartnummer';
  end if;

  set @nummer=1;
  if @Forceer = 1 then
    set @Genereren=1;
    execute immediate 'select ' || @StartNrVeld || ' into @Startnummer from tabProjectVastegegevens;';
  else
    execute immediate 'select 1,' || @StartNrVeld || ' into @Genereren, @Startnummer from tabProjectVastegegevens;';
  end if;

  if @genereren=1 then
    set @gevonden=0;
    while @gevonden=0
    loop
      set @nummer = null;
      select min(PbkVolgnummer) into @nummer from tabProjectBoekingsKop where PbkVolgnummer>=@startnummer;
      if @nummer is null then
        set @gevonden=1;
        set @nummer=@startnummer;
      else
        if @nummer=@startnummer then
          // Dit nummer is er al, dus ophogen en weer opnieuw in loop(@gevonden blijft 0)
          if @startnummer=9999999999 then
            set @startnummer=1;
          else
            set @startnummer=@nummer+1;
          end if
        else
          // Eerstvolgende ligt toch hoger, dus we kunnen gewoon het startnummer gebruiken
          set @nummer=@startnummer;
          set @gevonden=1;
        end if;
      end if;
    end loop;

    if @nummer=9999999999 then
      set @VolgendNummer = 1;
    else
      set @VolgendNummer = @nummer + 1;
    end if;

    execute immediate 'update tabProjectVastegegevens set ' || @StartNrVeld || ' = ' || @Volgendnummer;
  end if;

  //call TraceEind('VolgnummerProjectMutGenereren (@Nummer='+string(@Nummer)+')');
end;


create or replace procedure VoorraadHerwaarderingsboekingen(in @DgbGid integer, in @StukNummer numeric(10,0), in @Omschrijving nchar(40), in @Boekdatum date, out @BoekGangGid integer)
begin
  declare @JpGid integer;
  declare @Dummy nchar(20);

  declare @VoorraadTekst      long nvarchar;
  declare @HerwaarderingTekst long nvarchar;

  set @@ErrorTextProcedure = 'VoorraadHerwaarderingsboekingen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@DgbGid = ' + string(@DgbGid) + ', @StukNummer = ' + string(@StukNummer));

  //Boekingsgang aanmaken
  insert into tabBoekingsGang(BoekGangBjGid, BoekgangBronId, BoekGangInGebruik, IsBoekGangDefinitief)
  values(@@BjGid, 9, 1, 0);
  set @BoekGangGid = @@Identity;

  //Journaalpost aanmaken
  insert into tabJournaalPost (JpBoekGangGid, JpBjGid, JpDgbGid, BoekStukNummer, OmsJournaalpost, BoekDatum,  JpIsInGebruik)
                       values (@BoekGangGid,  @@BjGid, @DgbGid,  @StukNummer,    @Omschrijving,   @BoekDatum, 1);
  set @JpGid = @@Identity;

  //Ontbrekende grootboekrekeningen aanmaken
  select min(OpbrengtGroepsoortenPerStuk(OpbrGrpGid, ParSoort)) into @Dummy
  from   tmpVoorraadHerwaardering, (tabOpbrengstGroep, tabParagraaf) left outer join tabOpbrengstGroepSoort  on (OpbrGrpGid = GrpSoortGrpGid and GrpSoortParSoort = ParSoort)
  where  tmpVhOpbrGrpNummer = OpbrGrpNummer and ParSoort in (50, 80) and GrpSoortGrpGid is null;

  //Daadwerkelijke boeking
  //    <Reknr> Voorraad groep xxxx            100,-
  //Aan <Reknr> Herwaardering groep xxxx                 100,-
  set @VoorraadTekst      = _A('Voorraad groep %1!');
  set @HerwaarderingTekst = _A('Herwaardering groep %1!');

  insert into tabJournaalRegel(JrJpGid, JrRksGid, JrValutaBedrag, JrBasisBedrag, IsCreditBoeking, SoortBoeking, JrValNummer, OmsJournaalRegel)
  select   @JpGid, GrpSoortRksGid, sum(tmpVhBedrag), sum(tmpVhBedrag), (if GrpSoortParSoort = 50 then 0 else 1 endif), 0,
           @@BasisValutaNummer, (if GrpSoortParSoort = 50 then _P(@VoorraadTekst, OpbrGrpNummer) else _P(@HerwaarderingTekst, OpbrGrpNummer) endif)
  from     tmpVoorraadHerwaardering, tabOpbrengstGroep inner join tabOpbrengstGroepSoort on (GrpSoortGrpGId = OpbrGrpGId and GrpSoortParSoort in (50, 80))
  where    tmpVhOpbrGrpNummer = OpbrGrpNummer
  group by OpbrGrpNummer, GrpSoortRksGid, GrpSoortParSoort
  having   sum(tmpVhBedrag) <> 0;

  update tabJournaalpost set JpIsInGebruik     = 0 where JpGid       = @JpGid;
  update tabBoekingsGang set BoekGangInGebruik = 0 where BoekGangGid = @BoekGangGid;

  if not exists(Select 1 from tabjournaalpost where jpgid = @@jpgid) then
    set @@jpgid = NULL;
  end if;

  delete tmpVoorraadHerwaardering;

  set @@ErrorTextProcedure = 'VoorraadHerwaarderingsboekingen';
  //call TraceBegin(@@ErrorTextProcedure + ' > @BoekGangGid = ' + string(@BoekGangGid));
end;


create or replace procedure VoorraadMutatieBestandNrGenereren(in @VmsCode Integer, out @Nummer numeric(10,0))
begin
  declare @Genereren   numeric(10,0);
  declare @Startnummer numeric(10,0);
  declare @Gevonden    integer;

  set @@ErrorTextProcedure = 'VoorraadMutatieBestandNrGenereren > @VmsCode='+string(@VmsCode);
  //call TraceBegin(@@ErrorTextProcedure);

  //Dit deel moet uniek gelocked (met een wacht-lus)
  call LockWaitAndSetForUniqueLock(@@SpId,@@LoginTime, 'VoorraadCorrectieKopGenereerNummer', '');

  set @nummer=0;
  SELECT VmsStartNummer into @startnummer FROM  tabVoorraadMutatieSoorten WHERE VmsCode=@VmsCode;

  set @gevonden=0;
  while @gevonden=0
  loop
    set @nummer = null;
    select min(VckNummer) into @nummer from tabVoorraadCorrectieKop where VckNummer>=@startnummer;
    if @nummer is null then
      set @gevonden=1;
      set @nummer=@startnummer;
    else
      if @nummer=@startnummer then
        // Dit nummer is er al, dus ophogen en weer opnieuw in loop(@gevonden blijft 0)
        if @startnummer=9999999999 then
          set @startnummer=1;
        else
          set @startnummer=@nummer+1;
        end if
      else
        // Eerstvolgende ligt toch hoger, dus we kunnen gewoon het startnummer gebruiken
        set @nummer=@startnummer;
        set @gevonden=1;
      end if;
    end if;
  end loop;
  if @nummer=9999999999 then
    update tabVoorraadMutatieSoorten set VmsStartNummer=1 WHERE VmsCode=@VmsCode;
  else
    update tabVoorraadMutatieSoorten set VmsStartNummer=@nummer+1 WHERE VmsCode=@VmsCode;
  end if;

  //VoorraadCorrectieKopGenereerNummer-lock weer vrijgeven
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'VoorraadCorrectieKopGenereerNummer', '');

  set @@ErrorTextProcedure = 'VoorraadMutatieBestandNrGenereren > @Nummer='+string(@Nummer);
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure VoorraadVerplaatsen(
  in @Artcode nchar(20),
  in @MagCodeVan nchar(3),
  in @LocNaamVan nchar(20),
  in @Aantal numeric(15,3),
  in @MagCodeNaar nchar(3),
  in @LocNaamNaar nchar(20),
  in @ArtPartijnummer nchar(20),
  in @ArtSerienummer nchar(20),
  in @VrdMutOmschrijving nchar(40) default '',
  in @VrdMutUitleverOntvangstNr numeric(10,0) default null)
begin
  //---------------------------------------------------------------------------
  //----------------------------Voorraad verplaatsen--------------------
  // Word gebruikt door KingMobile om de voorraad te verplaatsen tussen 2 locaties van een magazijn.
  // Er wordt geen financiele boeking gemaakt.
  //---------------------------------------------------------------------------
  declare @tmpLocGid integer;
  declare @_ArtGid integer;
  declare @_VrdMutGid integer;
	declare @_Kostprijs numeric(15,3);
	declare @_PrijsPer numeric(15,3);
  declare @_MagGidVan integer;
  declare @_LocGidVan integer;
  declare @_MagGidNaar integer;
  declare @_LocGidNaar integer;
  declare @_LocBlokkade smallint;
  declare @_ArtPartijGid integer;
  declare @_ArtSerieGid integer;
  declare @_ArtIsPartijRegistreren smallint;
  declare @_ArtSerieNrRegistreren smallint;

  //call TraceBegin('VoorraadVerplaatsen > ' + '@Artcode='+string(@ArtCode)+',@MagCodeVan='+string(@MagCodeVan)+',@LocNaamVan='+string(@LocNaamVan)+',@Aantal='+string(@Aantal)+',@MagCodeNaar='+string(@MagCodeNaar)+',@LocNaamNaar='+string(@LocNaamNaar)+',@ArtPartijnummer='+string(@ArtPartijnummer)+',@ArtSerienummer='+string(@ArtSerienummer));

	//call Trace('ArtGid ophalen');
	select ArtGid, ArtIsPartijRegistreren, ArtSerieNrRegistreren
    into @_ArtGid, @_ArtIsPartijRegistreren, @_ArtSerieNrRegistreren
  from tabArtikel
  where ArtCode = @ArtCode
    and artSoort = 2;

  if @_ArtGid is null then
    call Raise(20700, _U('Artikelcode'));
  end if;

  //call Trace('Partijnummer ophalen');
	if @ArtPartijNummer <> '' then
		select ArtPartijGid into @_ArtPartijGid from tabArtikelPartij where ArtPartijArtGid = @_ArtGid and ArtPartijNummer = @ArtPartijNummer;
	end if;

  //call Trace('Serienummer ophalen');
  if @ArtSerieNummer <> '' then
    select ArtSerieGid into @_ArtSerieGid from tabArtikelSerienummer where ArtSerieArtGid = @_ArtGid and ArtSerieNummer = @ArtSerieNummer;
    if @_ArtSerieGid is null then
      call Raise(20700, _U('Artikelserienummer'));
    end if;
  end if;

  if (@_ArtIsPartijRegistreren = 1) and (@_ArtPartijGid is null) then
    raiserror 20000 _U('Partij niet meegegeven en/of niet gevonden!')
  end if;

  if (@_ArtIsPartijRegistreren = 0) and (IsNull(@ArtPartijNummer, '') <> '') then
    raiserror 20000 _U('Partij meegegeven aan een artikel zonder partijen registratie!')
  end if;

  //Indien serienummer registrerend artikel is, maar geen partij registrerend artikel, dan pakken we de default partij die gebruikt wordt van het serienummer
  if (@_ArtSerieNrRegistreren = 1) and (@_ArtIsPartijRegistreren = 0) then
    select first ArtPartijNummer, ArtSeriePartijGid into @ArtPartijNummer, @_ArtPartijGid from tabArtikelSerienummer inner join tabArtikelPartij on (ArtSeriePartijGid = ArtPartijGid) where ArtSerieArtGid = @_ArtGid;
  end if;

	//Kostprijs en prijsper nog ophalen. Dit ivm eventuele kostprijs per partij
	select (if ArtIsPartijAparteKostPrijs = 0 then ArtKostprijsEx else ArtPartijKostprijsEx endif),ArtPrijsPer
	into @_Kostprijs, @_PrijsPer
	from tabArtikel
	left outer join tabArtikelPartij on (ArtPartijGid = @_ArtPartijGid)
	where ArtGid = @_ArtGid;

  //call Trace('MagGid van en naar ophalen');
	select first MagGid into @_MagGidVan  from tabMagazijn where MagCode = @MagCodeVan;

  if @_MagGidVan is null  then
    call Raise(20700, _U('Magazijncode van'));
  end if;

  select first MagGid into @_MagGidNaar from tabMagazijn where MagCode = @MagCodeNaar;

  if @_MagGidNaar is null then
    call Raise(20700, _U('Magazijncode naar'));
  end if;

  //call Trace('LocGid van en naar ophalen en evt toevoegen');
	//Van locatie
  if IsNull(@LocNaamVan, '') = '' then
    call Raise(20700, _U('Locatie van'));
  end if;

	select LocGid into @_LocGidVan from tabLocatie where (LocMagGid = @_MagGidVan) and (LocNaam = @LocNaamVan);

	if @_LocGidVan is null then
		insert into tabLocatie (LocMagGid, LocNaam) values (@_MagGidVan, @LocNaamVan);
		set @_LocGidVan = @@Identity;
	end if;

	//Naar locatie
  if IsNull(@LocNaamNaar, '') = '' then
    call Raise(20700, _U('Locatie naar'));
  end if;

	select LocGid, LocBlokkade
    into @_LocGidNaar, @_LocBlokkade
  from tabLocatie
  where LocMagGid = @_MagGidNaar
    and LocNaam = @LocNaamNaar;

	if @_LocGidNaar is null then
		insert into tabLocatie (LocMagGid, LocNaam) values (@_MagGidNaar, @LocNaamNaar);
		set @_LocGidNaar = @@Identity;
	end if;

  if @_LocBlokkade = 1 then
    //Locatie is geblokkeerd voor het plaatsen van artikelen!
    call Raise(20780,_U('Locatie naar gebruiken is'),_U('locatie is geblokkeerd voor het plaatsen van artikelen'));     // (20780) %1! niet mogelijk: %2!
  end if;

	//Bijwerken Voorraad van -Aantal en naar +Aantal
	//call Trace('Voorraadmutatie van -Aantal');
	insert into tabVoorraadMutatie (VrdMutArtGid, VrdMutAantal, VrdMutDatum, VrdMutGebruikerCode, VrdMutSoort, VrdMutValNummer, VrdMutPrijsInBasis, VrdMutPrijsInValuta, VrdMutGeprijsdPer, VrdMutOmschrijving, VrdMutUitleverOntvangstNr)
	values (@_ArtGid, -@Aantal, now(), @@GebruikerCode, 6, @@BasisValutaNummer, @_Kostprijs, @_Kostprijs, @_PrijsPer, @VrdMutOmschrijving, @VrdMutUitleverOntvangstNr);
  set @_VrdMutGid = @@Identity;

	insert into tabVoorraadMutatieLocatieSerie (VrdMutLocVrdMutGid, VrdMutLocAantal, VrdMutLocMagGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer)
	values (@_VrdMutGid, -@Aantal, @_MagGidVan, @_LocGidVan, @ArtPartijnummer, @ArtSerieNummer);

	//call Trace('Voorraadmutatie van Aantal');
	insert into tabVoorraadMutatie (VrdMutArtGid, VrdMutAantal, VrdMutDatum, VrdMutGebruikerCode, VrdMutSoort, VrdMutValNummer, VrdMutPrijsInBasis, VrdMutPrijsInValuta, VrdMutGeprijsdPer, VrdMutOmschrijving, VrdMutUitleverOntvangstNr)
	values (@_ArtGid, @Aantal, now(), @@GebruikerCode, 6, @@BasisValutaNummer, @_Kostprijs, @_Kostprijs, @_PrijsPer, @VrdMutOmschrijving, @VrdMutUitleverOntvangstNr);
  set @_VrdMutGid = @@Identity;

	insert into tabVoorraadMutatieLocatieSerie (VrdMutLocVrdMutGid, VrdMutLocAantal, VrdMutLocMagGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer)
	values (@_VrdMutGid, @Aantal, @_MagGidNaar, @_LocGidNaar, @ArtPartijnummer, @ArtSerieNummer);

  //call TraceBegin('VoorraadVerplaatsen');
end;


create or replace procedure VorigeJournaalRegelGegevens(in @JpGid integer, in @JrNummer integer, out @Volgnr integer,
                                                        out @RksInvoer nchar(28), out @JrOms nchar(40), out @JrReferentie nchar(40),
                                                        out @JrFactuurDatum date, out @JrVervalDatum date, out @JrBetalingsKenmerk nchar(24),
                                                        out @Aantal numeric(15,2), out @JrValutaBedrag numeric(15,2), out @HulpRekening nchar(10),
                                                        out @HulpRekValutaBedrag numeric(15,2), out @RksZoekcode nchar(10), out @RksNaam nchar(40),
                                                        out @ValNummer integer, out @HulpRekValNummer integer, out @HulpRekSoort smallint, out @BtwCode integer,
                                                        out @JrBoekdatum date, out @JrDarGid integer)
begin
  set @@ErrorTextProcedure = 'VorigeJournaalRegelGegevens > ';
  //call TraceBegin(@@ErrorTextProcedure + '@JpGid = ' + string(@JpGid) + ', @JrNummer = ' + string(@JrNummer));

  set @Volgnr              = null;
  set @RksInvoer           = null;
  set @JrOms               = null;
  set @JrReferentie        = null;
  set @JrFactuurDatum      = null;
  set @JrVervaldatum       = null;
  set @JrBetalingskenmerk  = null;
  set @Aantal              = null;
  set @JrValutaBedrag      = null;
  set @HulpRekening        = null;
  set @HulpRekValutaBedrag = null;
  set @RksZoekcode         = null;
  set @RksNaam             = null;
  set @ValNummer           = null;
  set @HulpRekValNummer    = null;
  set @HulpRekSoort        = null;
  set @BtwCode             = null;
  set @JrBoekdatum         = null;
  set @JrDarGid            = null;
  if @JrNummer <> 1 then
    select first
           StukVolgnr, HoofdRekening.RksInvoer, OmsJournaalRegel, JrReferentie, JrFactuurDatum, JrVervaldatum,
           JrBetalingskenmerk, Aantal, JrValutaBedrag, HulpRekening.RksNummer, HulpRekValutaBedrag,
           HoofdRekening.RksZoekcode, HoofdRekening.RksNaam, JrValNummer, HulpRekValNummer, HulpRekSoort, HulpRekBtwCode, JrBoekDatum, JrDarGid
     into  @Volgnr, @RksInvoer, @JrOms, @JrReferentie, @JrFactuurDatum, @JrVervaldatum,
           @JrBetalingskenmerk, @Aantal, @JrValutaBedrag, @HulpRekening, @HulpRekValutaBedrag,
           @RksZoekcode, @RksNaam, @ValNummer, @HulpRekValNummer, @HulpRekSoort, @BtwCode, @JrBoekDatum, @JrDarGid
    from   tabRekeningschema HoofdRekening inner join
           tabJournaalregel on (JrRksGid = HoofdRekening.RksGid) left outer join (tabHulpRekening inner join tabRekeningschema HulpRekening on (HulpRekening.RksGid = HulpRekRksGid)) on JrGid = HulpRekJrGid
    where  JrJpGid = @JpGid and JrNummer < @JrNummer order by JrNummer desc;
  else
    //bug 7916 Bij de eerste journaalregel, moeten we toch bepalen wat de omschrijving was van de laatste journaalregel van het vorige boekstuk/journaalpost
    select   first OmsJournaalRegel into @JrOms
    from     tabJournaalRegel inner join tabJournaalpost on (JrJpGid = JpGid)
    where    JpGid < @JpGid and JpBoekGangGid in (select a.JpBoekgangGid from tabJournaalPost a where a.JpGid = @JpGid)
    order by JpGid desc, JrNummer desc
  end if;

  //call TraceEind('VorigeJournaalRegelGegevens > @Volgnr = ' + string(@Volgnr) + ', @RksInvoer = ' + @RksInvoer + ', @JrOms = ' + @JrOms + ', @JrReferentie = ' + @JrReferentie);
end;


create or replace function VorigeWerkdag(in @Date datetime, in @LndGid integer)
returns datetime
begin
  set @@ErrorTextProcedure = 'VorigeWerkdag > @date= ' + string(@Date)+', @LndGid= ' + string(@LndGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //Eerst 1 dag erbij
  set @Date = DateAdd(day, -1, @Date);

  //Afhankelijk van dag in de week alsnog opschuiven; 1e dag in de week=Zondag!
  set @Date = CASE DATEPART(dw, @Date)
                WHEN 1 THEN DateAdd(day, -2, @Date) // Oeps, valt op zondag, dus 2 dagen eraf
                WHEN 7 THEN DateAdd(day, -1, @Date) // Oeps, valt op zaterdag, dus 1 dag eraf
                ELSE @Date
              END;

  // Hier eventueel nog controleren of de datum een vakantiedag is? (bijv. kerst, nieuwjaarsdag)
/*
  while IsWorkingDay(@Date, @LndGid) = 0
  loop
    set @Date = DATEADD(day, -1, @Date);
  end loop;
*/
  set @@ErrorTextProcedure = @@ErrorTextProcedure + ' -> ' + string(@Date);
  //call TraceEind(@@ErrorTextProcedure);
  // En weer terug geven
  return(@Date);
end;


create or replace procedure VrdMutVerwerkenVoorraadControle(
  @VckGid integer
)
result (
  VcrArtGid            integer,
  VcrArtPartijGid      integer,
  VcrMagGid            integer,
  LocatieGid           integer,
  MutatieAantal        numeric(15,3),
  LocatieVoorraad      numeric(15,3),
  NieuweVoorraad       numeric(15,3),
  LocatieIsGeblokkeerd smallint
)
begin
  // ACW Deze routine is afkomstig uit de Delphi-code, waar geen scheiding was tussen partijregistratie en/of module m1
  // Veld LocatieVoorraad had eerder een andere inhoud, waar alles werd opgeteld. Nu wordt afhankelijk van wat code andere dingen gedaan.
  // In theorie kan het resultaat afwijken, namelijk als VcrArtPartijGid = NULL terwijl het WEL een partijregistrerend artikel is.
  // Maar dat zou niet mogen (partij is verplicht bij partijregistratie)
  // Oorspronkelijke code van veld LocatieVoorraad:
  //  (
  //      SELECT IsNull(SUM(ArtLocVoorraad),0.00)
  //      FROM   tabArtikelLocatie
  //      WHERE
  //            (ArtLocArtGid = VcrArtGid)                // Artikel
  //        AND (                                         // Partij (of niet-partijregistrerend)
  //                (ArtLocPartijGid = VcrArtPartijGid)
  //             OR (VcrArtPartijGid IS NULL)
  //            )
  //        AND (ArtLocMagGid = VcrMagGid)                // Magazijn
  //        AND (                                         // Locatie (of zonder meer magazijnen-module)
  //                (ArtLocLocGid = LocatieGid)
  //             OR (@IsModuleActiveMagazijnen = 0)
  //            )
  //  ) as LocatieVoorraad,

  declare @IsModuleActiveMagazijnen smallint = (select IsModuleActive('m1'));

  SELECT
    VcrArtGid,
    VcrArtPartijGid,
    VcrMagGid,
    (if @IsModuleActiveMagazijnen <> 0 then VcrLocGid endif) LocatieGid,
    SUM(VcrAantal) MutatieAantal,
    IsNull(
      if (@IsModuleActiveMagazijnen = 0) then
        if VcrArtPartijGid is null then
          ( // Partijregistrerende artikelen, zonder module Meerdere magazijnen
              SELECT SUM(ArtLocVoorraad)
              FROM   tabArtikelLocatie
              WHERE
                    (ArtLocArtGid = VcrArtGid)                // Artikel
                AND (ArtLocMagGid = VcrMagGid)                // Magazijn
          )
        else
          ( // NIET-partijregistrerende artikelen, zonder module Meerdere magazijnen
              SELECT SUM(ArtLocVoorraad)
              FROM   tabArtikelLocatie
              WHERE
                    (ArtLocArtGid = VcrArtGid)                // Artikel
                AND (ArtLocPartijGid = VcrArtPartijGid)       // Partij (Dus partijregistrerend))
                AND (ArtLocMagGid = VcrMagGid)                // Magazijn
          )
        endif
      else
        if VcrArtPartijGid is null then
          ( // Partijregistrerende artikelen, met module Meerdere magazijnen
            SELECT SUM(ArtLocVoorraad)
            FROM   tabArtikelLocatie
            WHERE
                  (ArtLocArtGid = VcrArtGid)                // Artikel
              AND (ArtLocMagGid = VcrMagGid)                // Magazijn
              AND (ArtLocLocGid = LocatieGid)               // Locatie
          )
        else
          ( // NIET-partijregistrerende artikelen, met module Meerdere magazijnen
            SELECT SUM(ArtLocVoorraad)
            FROM   tabArtikelLocatie
            WHERE
                  (ArtLocArtGid = VcrArtGid)                // Artikel
              AND (ArtLocPartijGid = VcrArtPartijGid)       // Partij (Dus partijregistrerend))
              AND (ArtLocMagGid = VcrMagGid)                // Magazijn
              AND (ArtLocLocGid = LocatieGid)               // Locatie
          )
        endif
      endif
      , 0) LocatieVoorraad,
    (LocatieVoorraad + MutatieAantal) NieuweVoorraad,
    if LocatieGid is not null then (select 1 from tabLocatie where LocGid = LocatieGid and LocBlokkade = 1) endif LocatieIsGeblokkeerd
  FROM
    tabVoorraadCorrectieRegel
    INNER JOIN tabArtikel ON (ArtGid = VcrArtGid and ArtHeeftVoorraad = 1)
  WHERE
    VcrVckGid = @VckGid
  GROUP BY
    VcrArtGid, VcrArtPartijGid, VcrMagGid, LocatieGid, LocatieVoorraad
  HAVING
    (NieuweVoorraad < 0) and (NieuweVoorraad < LocatieVoorraad)
end;


//Deze proc maakt voor een meegegeven importlayout de detail-records aan, waarin de eindgebruiker de recordindeling
// van het ascii-bestand kan vastleggen.
create or replace procedure VulArtikelAsciiImportVelden(in @IelGid integer)
begin
  declare @VolgordeTeller integer;
  declare @FieldPos integer;
  declare @Fields long nvarchar;
  declare @CurrentField nchar(40);

  declare @DescriptionPos integer;
  declare @Descriptions long nvarchar;
  declare @CurrentDescription nchar(40);

  set @@ErrorTextProcedure = 'VulArtikelAsciiImportVelden > @IelGid='+string(@IelGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //Als er nieuwe velden bijmoeten, hoeven alleen maar @Fields en @Descriptions uitgebreid te worden.
  //Eindig de strings wel altijd met een komma! (anders komt de laatste niet mee..)

  //Hoofdvelden
  set @Fields = 'ArtCode,ArtZoekcode,ArtOms,';
  set @Descriptions = _U('Artikelnummer,Artikelzoekcode,Artikelomschrijving,');

  //Velden op 1e tabje Algemeen, linkerrijtje
  set @Fields = @Fields + 'ArtOpbrGrpGid,ArtAantDecAantallen,ArtAantDecPrijzen,ArtOmsEenheid,ArtGewichtPer,ArtGewicht,ArtVolumePer,ArtVolume,';
  set @Descriptions = @Descriptions + _U('Opbrengstgroep,Aantal decimalen aantallen,Aantal decimalen prijzen,Eenheid,Gewicht per,Gewicht,Volume per,Volume,');
  //CBS optie code velden
  if (select IsModuleActive('c1')) <> 0 then
    set @Fields = @Fields + 'ArtCbsGcGid,ArtCbsMaatstaf,';
    set @Descriptions = @Descriptions + _U('CBS-goederencode,CBS-maatstaf,');
  end if;

  //velden op 1e tabje Algemeen, rechterrijtje
  //let op verkoopprijs. Deze is incl of excl in te lezen. In de Artikelquery worden deze 2 velden gefabriceerd. Net als adviesprijs.
  set @Fields = @Fields + 'ArtBtwCodeInkoop,ArtBtwCode,ArtBerekenPrijs,ArtBerekenPrijsVan,ArtBerekenPrijsMargeIs,ArtBerekenPrijsPerc,ArtPrijsPer,ArtKostprijsEx,ArtVerkprijsEx,ArtVerkprijsIn,PraKortingsBedrag,PraKortingsPerc,ArtAdviesPrijsEx,ArtAdviesPrijsIn,';
  set @Descriptions = @Descriptions + _U('BTW-code inkoop,BTW-code verkoop,Prijzen autom. berekenen,Berekenen van,Marge,Percentage,Geprijsd per,Kostprijs,Verkoopprijs excl. BTW,Verkoopprijs incl. BTW,Kortingsbedrag,Kortingspercentage,Adviesprijs excl. BTW,Adviesprijs incl. BTW,');

  //velden op 2e tabje - Omschrijving. Alleen de TOF in de basistaal is in te lezen.
  set @Fields = @Fields + 'ArtInvTekstOpFactuur,ArtTekst,';
  set @Descriptions = @Descriptions + _U('Tekst op factuur wijzigen,Tekst op factuur,');

  //Nieuw 5.35: EAN codes ook importeren
  if (select IsModuleActive('ec')) <> 0 then
    set @Fields = @Fields + 'ArtEanCode,';
    set @Descriptions = @Descriptions + _U('EAN-code,');
  end if;

  //velden op 3e tabje - Inkoop / leverancier
  //ArtLevHeeftEigenInkoopprijs: Veldje is er later bijgekomen, nu nog niet in te lezen met XML. Staat dus nog niet erbij.
  set @Fields = @Fields + 'NawFilNummer,ArtLevArtCodeBijLeverancier,ArtLevLevertijd,ArtLevBestelGrootte,ArtLevMinimumAfname,Valcode,ArtLevInkoopPrijs,';
  set @Descriptions = @Descriptions + _U('Leverancier,Artikelnummer bij leverancier,Levertijd,Bestelgrootte,Minimumafname,Valutacode,Inkoopprijs,');

  //velden op 4e tabje: - Voorraad j/n
  if (select IsModuleActive('vr')) <> 0 then
    set @Fields = @Fields + 'ArtHeeftVoorraad,';
    set @Descriptions = @Descriptions + _U('Voorraadartikel,');
  end if;

  //velden op 5e tabje: vinkjes
  set @Fields = @Fields + 'ArtIsGeblokkeerd,ArtIsGeblokkeerdInkoop,ArtMutatieVerkoopBijhouden,ArtMutatieInkoopBijhouden,ArtIsKostprijsWijzigenInOrder,';
  set @Descriptions = @Descriptions + _U('Geblokkeerd voor verkoop,Geblokkeerd voor inkoop,Verkoopmutaties bijhouden,Inkoopmutaties bijhouden,Kostprijs wijzigen bij orderinvoer,');

  //velden op 5e tabje: webartikel
  if (select IsModuleActive('w1')) <> 0 then
    set @Fields = @Fields + 'ArtWebArtikel,ArtWebBestelGrootte,ArtWebLevertijd,ArtWebTonenVanaf,ArtWebTonenTot,';
    set @Descriptions = @Descriptions + _U('Webartikel,Webartikel bestelgrootte,Webartikel levertijd,Webartikel Tonen vanaf,Webartikel Tonen t/m,');
  end if;

  //velden op 5e tabje: Besteladvies
  if (select IsModuleActive('be')) <> 0 then
    set @Fields = @Fields + 'ArtIsGebruikVoorBestelAdvies,';
    set @Descriptions = @Descriptions + _U('Meenemen in besteladviezen,');
  end if;

  //velden op 5e tabje: Productieadvies
  if (select IsModuleActive('rp')) <> 0 then
    set @Fields = @Fields + 'ArtIsGebruikVoorProductieAdvies,';
    set @Descriptions = @Descriptions + _U('Meenemen in productie-adviezen,');
  end if;


  //velden op 6e tabje: Afbeelding.
  set @Fields = @Fields + 'ArtAfbeeldingKlein,ArtAfbeeldingGroot,';
  set @Descriptions = @Descriptions + _U('Afbeelding klein,Afbeelding groot,');

  //Opmerkingsveld. Let op: ArtOpmerking bestaat niet, maar ArtTekst is al in gebruik wegens TOF. Wordt in programma opgelost.
  set @Fields = @Fields + 'ArtOpmerking,';
  set @Descriptions = @Descriptions + _U('Opmerkingen,');



  /*
  //velden
  set @Fields = @Fields + '';
  set @Descriptions = @Descriptions + '';
 //kies uit:
 ArtAantallen,
 ArtDefaultMagGid, ArtGarantieVullenBijLeveren, ArtGcGid, ArtGereserveerd,
  ArtIngangsDatumHuidigeKostprijs, ArtIngangsdatumHuidigeVerkoopPrijs, ArtIngangsDatumOudeKostprijs,
 ArtIngangsDatumOudeVerkoopPrijs, , ArtIsAdviesPrijsInclBtw,
 ArtIsPartijAparteKostPrijs, ArtIsPartijAparteTekstOpFactuur, ArtIsPartijAparteVerkoopPrijs, ArtIsPartijNrBijLeverenVerplicht,
 ArtIsPartijNrGenereren, ArtIsPartijRegistreren, ArtIsPartijVerkoopCheckOuderePartijOp,
 ArtIsSerieNrBijVerkoopZoeken, ArtIsSerieNrBijVrijgaveVerplicht, ArtKmcGarcGid,
ArtOudeKostprijs, ArtOudePrijsPer, ArtOudeVerkoopPrijs,
ArtPartijAparteKostPrijsDefault, ArtPartijAparteTekstOpFactuurDefault, ArtPartijAparteVerkoopPrijsDefault, ArtPartijNrLengteVolgnr,
ArtPartijNrStartNummer, ArtPartijNrTekstAchter, ArtPartijNrTekstVoor, ArtPartijNrVolgnrUitvullen, ArtPartijVerkoopCheckOuderePartij,
ArtSerieNrAanmakenBij, ArtSerieNrBijVerkoopAanmaken, ArtSerieNrGenereren, ArtSerieNrLengteVolgnr, ArtSerieNrRegistreren,
 ArtSerieNrStartNummer, ArtSerieNrTekstAchter, ArtSerieNrTekstVoor, ArtSerieNrVolgnrUitvullen, ArtSoort, ArtTimeStamp, ,
  ArtVerkprijsIsIncl, ArtVoorraad,
*/

  set @VolgordeTeller = 0;
  set @FieldPos = 0;
  set @DescriptionPos = 0;
  set @CurrentField = '';
  set @CurrentDescription = '';

  //Homemade CommaText functie begint hier.
  lpVelden : loop
    //zoek positie vd komma
    select locate(@Fields, ',') into @FieldPos;
    //geen kommas meer? Dan zijn we klaar.
    if @FieldPos = 0 then
      leave lpVelden;
    end if;
    //Het stukje totaan de komma is het nieuwe veld
    select left(@Fields, @FieldPos-1) into @CurrentField;
    //Het stuk vanaf de komma bewaren we voor de volgende ronde.
    set @Fields = Substring(@Fields, @FieldPos+1);

    //Nu bijhorende Description opzoeken volgens hetzelfde principe:
    select locate(@Descriptions, ',') into @DescriptionPos;
    if @DescriptionPos = 0 then
      //is er iets mis want er moeten evenveel velden in beide strings staan. raisen?
    end if;
    select left(@Descriptions, @DescriptionPos-1) into @CurrentDescription;
    set @Descriptions = Substring(@Descriptions, @DescriptionPos+1);

    set @VolgordeTeller = @VolgordeTeller + 1;

    //Nu kunnen we (eindelijk) een record toevoegen in tabImportExportLayoutVelden!
    //call trace('@CurrentField = '+@CurrentField + '; @CurrentDescription = '+@CurrentDescription);
    if not exists (select 1 from tabImportExportLayoutVelden where IelVeldIelGid = @IelGid and IelVeldNaam = @CurrentField) then
      insert into tabImportExportLayoutVelden (IelVeldnaam, IelVeldDisplayNaam, IelVeldIelGid, IelVeldVolgorde)
                                       values (@CurrentField, @CurrentDescription, @IelGid, @VolgordeTeller);
    end if;


  end loop lpVelden;

  set @@ErrorTextProcedure = 'VulArtikelAsciiImportVelden';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure VulFactuurAdres(
  in @AdresSoort  smallint,
  in @FkGid       integer,
  in @FrefGid     integer,
  in @OrkGid      integer,
  in @AdrGid      integer,
  in @NawGid      integer,
  in @LayoutSoort smallint)
begin
  declare @AdresDocSoort integer;

  set @@ErrorTextProcedure = 'VulFactuurAdres > ';
  //call TraceBegin(@@ErrorTextProcedure + '@AdresSoort = ' + string(@AdresSoort) + ', @FkGid = ' + string(@FkGid) + ', @FrefGid = ' + string(@FrefGid) + ', @OrkGid = ' + string(@OrkGid) + ', @AdrGid = ' + string(@AdrGid) + ', @NawGid = ' + string(@NawGid) + ', @LayoutSoort = ' + string(@LayoutSoort));

  // RS 29-08-2007: Nav bug 26437, contpers obv adressoort ipv layoutsoort
  // RS 20-03-2008: Nav bug 28086, correctie voor projectfacturen
  case @AdresSoort
    when  0 then set @AdresDocSoort = 20;                                                               // Correspondentie-adres        -> Orderbevestiging
    when  1 then set @AdresDocSoort = (if @LayoutSoort in (40,60,65) then @LayoutSoort else 50 endif);  // Factuuradres factuurdebiteur -> Factuur Batch
    when 12 then set @AdresDocSoort = 30;                                                               // Verzendadres                 -> Pakbon
    when 13 then set @AdresDocSoort = 30;                                                               // Eindbestemmingsadres         -> Pakbon
  end case;

  insert into tabFactuurAdres(
  faFkGid,            faFrefGid,           faSoortAdres,
  faNaam1,            faNaam2,
  faStraat,           faHuisnummer,        faHuisnummerPositie,
  faPostcode,         faPostcodePositie,   faPlaats,
  faLand,             faLandAfdrukken,     faLandCode, 					faLandEULid,
  faTelefoon,         faTelefoon2,				 faTelefax,           faEmail,
  faEANcode,
  faContactNaamAdres, faContactNaamAanhef, faContactNaamBrief,
  faContactEmail,     faContactTelefoon,   faContactTelefoon2,  faContactTelefax,
  faOms,              faOpm,               faRelGid
   )
  select @FkGid,         @frefGid,              @AdresSoort, // Opgegeven adressoort (factuur- vestiging- correspondentie- verzend- etc. adres)
         AdrNaam1,       AdrNaam2,
         AdrStraat,      AdrHuisnummer,         lndPlaatsHuisnr,
         AdrPostcode,    lndPlaatsPostcode,     AdrPlaats,
         lndOms,         lndInNAWblok,          lndEigenCode,   LndIsEGLid, //Land alleen afdrukken als het een eigen land is *en* land toch afdrukken, *of* land is niet eigen land
         AdrTelefoon,    AdrTelefoon2,					AdrTelefax,     AdrEmail,
         AdrEanCode,
         isnull(relNaamInAdres,  FnTekstAdres),
         isnull(relNaamInAanhef, FnTekstAdres),
         isnull(relNaamInBrief,  FnTekstAdres),
         RelEmail,       RelTelefoon,           RelTelefoon2,   RelTelefax,
         AdrOms,         AdrOpmOpmerking,       RelGid
  from   tabAdres
         left outer join tabAdresOpmerkingen on (AdrOpmAdrGid = AdrGid)
         left outer join tabOrderRelatieVoorDocument on (OrdRelOrkGid = @OrkGid and OrdRelDocSoort = @AdresDocSoort)
         left outer join tabRelatie on ( RelGid = ( if @AdresSoort = 12 and AdrRelGid is not null then AdrRelGid else OrdRelRelGid endif ) )
         left outer join tabLand on ( LndGid = AdrLndGid )
         left outer join (tabNaw
                          inner join tabDocument on (DocSoort = @AdresDocSoort)
                          inner join tabFunctieTaal on (TaalFnCode = DocFnCodeDefault and FnTaalGid = nawTaalGid)
                         ) on (NawGid = @NawGid)
  where  AdrGid = @AdrGid;

  set @@ErrorTextProcedure = 'VulFactuurAdres';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure VulPrnCatalogusRubriekTabel(in @CatGid integer, in @StartCatrGid integer, out @LockNummer integer)
begin
  declare @Result       integer;
  declare @StartNiveau  integer;
  declare @CatrGidStart integer;

  set @@ErrorTextProcedure = 'VulPrnCatalogusRubriekTabel(@CatGid='+string(@CatGid)+', @StartCatrGid='+String(@StartCatrGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  //TG 03-07-2009: door een aanpassing ivm een andere bug kon hier nu een null value binnenkomen, terwijl die vroeger vervangen werd door -1. nu dus even zelf doen.
  set @StartCatrGid = IsNull(@StartCatrGid, -1);
  set @CatrGidStart = @StartCatrGid;

  LocknummerLoop:
  LOOP
    call RandomNumber2(@LockNummer);
    call LockSetOnId(@@spid, @@LoginTime , 1, 'prnCatalogusRubriek', @LockNummer, @Result);
    IF @Result = 0 THEN
      LEAVE LocknummerLoop;
    END IF;
  END LOOP LocknummerLoop;

  //call Trace('VulPrnCatalogusRubriekTabel > @LockNummer='+String(@LockNummer));

  insert into prnCatalogusRubriek
         (prnCaruGid , prnCaruCatrGid, prnCaruVolgNr, prnCaruIsKop, prnCaruCoderingRubKop, prnCaruCoderingRubVoet, prnCaruCatrGidNiveau1)
  select  @LockNummer, @CatrGidStart , 1            , 1           , CatrCoderingRubKop   , -1                    , CatrGid
  from   tabCatalogusRubriek
  where  CatrGid = @CatrGidStart;

  select CatrNiveau - 1 into @StartNiveau from tabCatalogusRubriek where CatrGid = @StartCatrGid;

  call LeesCatalogusRubrieken(@CatGid, @StartCatrGid, @LockNummer, @StartNiveau, @StartCatrGid, null, null, null, null);

  insert into prnCatalogusRubriek
         (prnCaruGid , prnCaruCatrGid, prnCaruVolgNr, prnCaruIsKop, prnCaruCoderingRubKop, prnCaruCoderingRubVoet, prnCaruCatrGidNiveau1)
  select  @LockNummer, @CatrGidStart , (select IsNull(count(*), 0)+1 from prnCatalogusRubriek where PrnCaruGid = @LockNummer), 0 , -1, CatrCoderingRubVoet, CatrGid
  from   tabCatalogusRubriek
  where  CatrGid = @CatrGidStart;


  set @@ErrorTextProcedure = 'VulPrnCatalogusRubriekTabel(@CatGid='+string(@CatGid)+', @StartCatrGid='+String(@StartCatrGid)+')';
  //call TraceEind(@@ErrorTextProcedure);
end;


//project-tree in de juiste volgorde in de printtabel zetten m.b.v. volgnummers (bijv. 1.07.054.15)
create or replace procedure VulPrnProjectStructuur(in @ProjGid integer, in @LockNummer integer, in @TotEnMetLevelNr integer, in @InclVoorcalculaties smallint)
begin
  declare @MaxVolgNrDitLevel integer; // Nodig om te bepalen uit hoeveel cijfers alle volgnummers van dit level moeten bestaan. bijv. als max = 124 dan krijgt volgnummer 6 de waarde 006
  declare @MaxVolgNrDitLevelProjectBoom integer;
  declare @MaxVolgNrDitLevelVoorcalculatie integer;
  declare @AantalLevels integer;
  declare @CurrentLevel integer;
  declare @PbGid integer;
  declare @MaxLengthVolgNrDitLevel integer;

  set @@ErrorTextProcedure='VulPrnProjectStructuur';
  //call TraceBegin(@@ErrorTextProcedure);

  //indien null dan default op 1 (beter teveel dan te weinig data)
  set @InclVoorcalculaties = IsNull(@InclVoorcalculaties, 1);

  // maximum aantal levels van dit project bepalen
  select isnull(max(PbLevel),0) into @AantalLevels
  from tabProjectBoom
  where PbProjGid = @ProjGid;

  // voor eventuele voorcalculaties onder het laagste projectonderdeel 1 erbij optellen
  set @AantalLevels=@AantalLevels+1;

  if @TotEnMetLevelNr < @AantalLevels then
    set @AantalLevels=@TotEnMetLevelNr
  end if;

  // PbGid van project ophalen
  select PbGid into @PbGid
  from tabProjectBoom
  where (PbProjGid = @ProjGid) and(PbLevel = 1);

  set @CurrentLevel=1;

  insert into prnProjectStructuur(PrnPsLockId,PrnPsProjGid,PrnPsVolgNrString,PrnPsPbGid,PrnPsLevel,PrnPsPvcGid,PrnPsSpecificerenOpOfferte,PrnPsAfdrukken,PrnPsIsOfferteBedragAfwijkend,PrnPsBedragenZijnRelevant, PrnSpecificerenEnBedragenRelev, PrnPrijsPerEenheidIsRelevant)
                           values(@LockNummer,@ProjGid    ,'1'              ,@PbGid    ,1         ,null       ,1                         ,1             ,0                            ,1                        , 1                             , 0                           );

  while @CurrentLevel < @AantalLevels loop

    set @CurrentLevel=@CurrentLevel+1;

    // maximum volgnummer van dit level bepalen, elk volgnummer wordt eventueel aangevuld met voorloopnullen zodat alles goed gesorteerd kan worden.
    select isnull(max(PbVolgNr),0) into @MaxVolgNrDitLevelProjectBoom
    from tabProjectBoom
    where (PbProjGid = @ProjGid) and PbLevel = @CurrentLevel;

    select isnull(max(PvcVolgNr),0) into @MaxVolgNrDitLevelVoorcalculatie
    from tabProjectBoom inner join tabProjectVoorcalculatie on PvcPbGid = PbGid
    where (PvcProjGid = @ProjGid) and PbLevel = (@CurrentLevel-1);

    if @MaxVolgNrDitLevelProjectBoom > @MaxVolgNrDitLevelVoorcalculatie then
      set @MaxVolgNrDitLevel=@MaxVolgNrDitLevelProjectBoom
    else
      set @MaxVolgNrDitLevel=@MaxVolgNrDitLevelVoorcalculatie
    end if;

    set @MaxLengthVolgNrDitLevel=LENGTH(STRING(@MaxVolgNrDitLevel));

    // Alle projectonderdelen van dit level inserten
    insert into prnProjectStructuur(PrnPsLockId,PrnPsProjGid,PrnPsVolgNrString,PrnPsPbGid,PrnPsLevel,PrnPsPvcGid,PrnPsSpecificerenOpOfferte,PrnPsAfdrukken,PrnPsIsOfferteBedragAfwijkend,PrnPsBedragenZijnRelevant, PrnSpecificerenEnBedragenRelev, PrnPrijsPerEenheidIsRelevant)
      select @LockNummer,
             @ProjGid,
             PrnPsVolgNrString+'.'+REPEAT('0',@MaxLengthVolgNrDitLevel-LENGTH(STRING(PbVolgNr)))+STRING(PbVolgNr),
             PbGid,
             PbLevel,
             null,
             if(PrnPsSpecificerenOpOfferte = 1 and PbUitsplitsen = 1) then 1 else 0 endif, //PrnPsSpecificerenOpOfferte
             if PrnPsSpecificerenOpOfferte = 1 then 1 else 0 endif, //PrnPsAfdrukken,
             if PrnPsIsOfferteBedragAfwijkend = 1 then 1 else PbIsOfferteBedragAfwijkend endif, //PrnPsIsOfferteBedragAfwijkend,
             if PrnPsIsOfferteBedragAfwijkend = 1 then 0 else 1 endif,  //PrnPsBedragenZijnRelevant
             if(PrnPsSpecificerenOpOfferte = 1 and PbUitsplitsen = 1 and PrnPsIsOfferteBedragAfwijkend = 0) then 1 else 0 endif, //PrnSpecificerenEnBedragenRelev
             0 //PrnPrijsPerEenheidIsRelevant
        from prnProjectStructuur
        inner join tabProjectBoom on PbParentPbGid = prnPsPbGid
        where (PrnPsLockId = @LockNummer) and(PrnPsProjGid = @ProjGid)
          and (PbLevel = @CurrentLevel) and(PrnPsLevel = (@CurrentLevel-1));

    if @InclVoorcalculaties = 1 then
      // Alle voorcalculaties van dit level inserten
      insert into prnProjectStructuur(PrnPsLockId,PrnPsProjGid,PrnPsVolgNrString,PrnPsPbGid,PrnPsLevel,PrnPsPvcGid,PrnPsSpecificerenOpOfferte,PrnPsAfdrukken,PrnPsIsOfferteBedragAfwijkend,PrnPsBedragenZijnRelevant, PrnSpecificerenEnBedragenRelev, PrnPrijsPerEenheidIsRelevant)
        select @LockNummer,
               @ProjGid,
               PrnPsVolgNrString+'.'+REPEAT('0',@MaxLengthVolgNrDitLevel-LENGTH(STRING(PvcVolgNr)))+STRING(PvcVolgNr),
               null,
               @CurrentLevel,
               PvcGid,
               0, //PrnPsSpecificerenOpOfferte
               if PrnPsSpecificerenOpOfferte = 1 then 1 else 0 endif, //PrnPsAfdrukken,
               0, //PrnPsIsOfferteBedragAfwijkend
               if PrnPsIsOfferteBedragAfwijkend = 1 then 0 else 1 endif,  //PrnPsBedragenZijnRelevant
               0, //PrnSpecificerenEnBedragenRelev
               if PrnPsIsOfferteBedragAfwijkend = 1 then 0 else (if PvcOfferteBedrag = PvcVerkoopprijsRegelTotaal then 1 else 0 endif) endif //PrnPrijsPerEenheidIsRelevant
          from prnProjectStructuur
          inner join tabProjectVoorcalculatie on PvcPbGid = prnPsPbGid
          where (PrnPsLockId = @LockNummer) and(PrnPsProjGid = @ProjGid)
            and (PvcProjGid = @ProjGid) and(PrnPsLevel = (@CurrentLevel-1));
    end if;
  end loop;

  set @@ErrorTextProcedure='VulPrnProjectStructuur';
  //call TraceEind(@@ErrorTextProcedure);
end;


// ------------------------------------------------------------------------
// --------- Vullen tussentabel voor goedkeuren projecturenbrowse ---------
// ------------------------------------------------------------------------
create or replace procedure VulProjectUrenBrowse(
 inout @Sessie              integer,   // Unieke sessienumer; indien al bestaat, dan wordt deze alsnog verwijderd!
 in    @StartDatum          date,      // NULL = huidige verwerkingsdatum; Mutaties vanaf deze datum (wordt eerst afgerond op week/maand indien nodig!)
 in    @EindDatum           date,      // NULL = huidige verwerkingsdatum; <>NULL: mutaties t/m deze datum
 in    @TonenPer            integer,   // 1 = dag, 2 = week, 3 = maand
 in    @SoortMedewerker     smallint,  // 0 = alle medewerkers; 1 = eigen medewerkers; 2 = externe medewerkers
 in    @Geblokkeerd         smallint,  // 0 = alle; 1 = alleen de niet-geblokkeerde; 2 = alleen de geblokkeerde;
 in    @GekoppeldeGebruiker smallint,  // 0 = alle; 1 = alleen gekoppeld; 2 = alleen niet-gekoppeld aan gebruiker
 in    @VanTeamLeiderRelGid integer,   // NULL = alle medewerkers; <>NULL = alleen medewerkers met deze RelGid als teamleider
 in    @GoedTeKeuren        smallint,  // 0 = alle; 1 = alleen goed te keuren; 2  alleen goedgekeurde mutaties; -1 = GEEN resultaat terugsturen (i.v.m. rechten)
 in    @PbrStatus           char(4)    //geeft de PbrStatus aan  (0,1,2,3) waar vanaf gezocht word. 0 = concept en 1 = ingeleverd
)
begin

  declare @WerkDatum date;
  declare @ToonDatum nchar(7);

  // @GoedTeKeuren =-1: Toon geen enkele regel
  // @GoedTeKeuren = 0: Toon alle regels in de datumrange, ongeacht of er mutaties zijn of niet. Aantal uren = totaal aantal uren in de regel
  // @GoedTeKeuren = 1: Toon alle regels in de datumrange met niet-goedgekeurde mutaties en ZONDER mutaties. Aantal uren = niet-goedgekeurde uren
  // @GoedTeKeuren = 2: Toon alleen regels in de datumrange met goedgekeurde mutaties. Aantal uren = wel-goedgekeurde uren

  set @@ErrorTextProcedure = 'VulProjectUrenBrowse > @StartDatum='+string(@StartDatum)+', @EindDatum='+string(@EindDatum)+', @GoedTeKeuren='+string(@GoedTeKeuren);
  //call traceBegin(@@ErrorTextProcedure);


  if @Sessie is null then
    // Nieuw sessienummer opvragen ...
    call RandomNumber2(@Sessie);
    call LockSetOnId(@@SpId, @@LoginTime, 0, 'prnProjectUrenBrowse', string(@Sessie), 0);
  else
    delete prnProjectUrenBrowse where prnPubUniekID = @Sessie;
  end if;

  // StartDatum invullen en omlaag afronden op week/maand
  set @StartDatum = isnull(@StartDatum, @@Verwerkingsdatum);
  case @TonenPer
    when 2 then set @StartDatum = DateAdd(week,  DateDiff(week,  '1500-01-06', @StartDatum), '1500-01-06'); // 1500-01-06 = zondag!
    when 3 then set @StartDatum = DateAdd(month, DateDiff(month, '1500-01-01', @StartDatum), '1500-01-01');
  end case;

  // EindDatum (eventueel) invullen en omhoog afronden
  set @EindDatum = isnull(@EindDatum, @@Verwerkingsdatum);
  case @TonenPer
    when 2 then set @EindDatum = DateAdd(day, -1, DateAdd(week,  DateDiff(week,  '1500-01-06', @EindDatum)+1, '1500-01-06')); // 1500-01-06 = zondag!
    when 3 then set @EindDatum = DateAdd(day, -1, DateAdd(month, DateDiff(month, '1500-01-01', @EindDatum)+1, '1500-01-01'));
  end case;

//call trace('@StartDatum='+string(@StartDatum)+', @EindDatum='+string(@EindDatum));

  set @WerkDatum = @StartDatum;


  while @WerkDatum <= @EindDatum loop
    // Bepaal de string om te tonen (afhankelijk van per dag/week/maand tonen)
    case @TonenPer
      when 1 then set @ToonDatum = ''; //@WerkDatum;
      when 2 then set @ToonDatum = string(datepart(cyr,  @WerkDatum)) + '-' + right('0' + string(datepart(cwk,   @WerkDatum)), 2);
      when 3 then set @ToonDatum = string(datepart(year, @WerkDatum)) + '-' + right('0' + string(datepart(month, @WerkDatum)), 2);
    end case;

    insert into prnProjectUrenBrowse(
      prnPubUniekID, prnPubRelgid,
      //pmwZoekcode, relVolledigeNaam,
      prnPubCredNummer,
      prnPubDag, prnPubWeek, prnPubMaand, prnPubAantalGeboekt, prnPubMinUren, prnPubMaxUren,
      prnPubOpm)
    select
      @Sessie,
      relgid,
//      pmwZoekcode,
//      relVolledigeNaam,
      (select if NawFilFonId = 'B' then '' else NawFilNummer endif from tabNawFile where NawFilNawGid = RelNawGid) CredNummer,
      if @TonenPer = 1 then @WerkDatum else now() endif Datum,
      if @TonenPer = 2 then @ToonDatum            endif Week,
      if @TonenPer = 3 then @ToonDatum            endif maand,
      isnull(sum(PbrAantalGeboekt),0.0) AantalGeboekt,
      case @TonenPer when 1 then pmwMinUrenDag when 2 then pmwMinUrenWeek end MinUren,
      case @TonenPer when 1 then pmwMaxUrenDag when 2 then pmwMaxUrenWeek end MaxUren,

      if    (@TonenPer = 1 and PmwControleUrenDag <> 0)
         or (@TonenPer = 2 and PmwControleUrenWeek <> 0)
      then
        if AantalGeboekt < MinUren then 'A' else '' endif + // Te weinig uren ingevoerd
        if AantalGeboekt > MaxUren then 'B' else '' endif  // Te veel uren ingevoerd
      else ''
      endif +
      if min(PbrMutatieDatum) < PmwStartDatum then 'C' else '' endif + // Nog niet in dienst
      if max(PbrMutatieDatum) > PmwEindDatum  then 'D' else '' endif   // Reeds uit dienst
    from
     tabRelatie
     inner join tabProjectMedewerker on (pmwRelGid = RelGid)
     left outer join tabGebruiker on (GebrRelGid = RelGid)
     left outer join tabProjectBoekingsregel on (PbrRelGid = RelGid and
                                                 (   (@TonenPer = 1 and @WerkDatum = PbrMutatieDatum)
                                                  or (@TonenPer = 2 and @ToonDatum = string(datepart(cyr, PbrMutatiedatum)) + '-' + right('0' + string(datepart(cwk,  PbrMutatiedatum)), 2) )
                                                  or (@TonenPer = 3 and @ToonDatum = string(datepart(year, PbrMutatiedatum)) + '-' + right('0' + string(datepart(Month, PbrMutatiedatum)), 2) )
                                                 )
                                                )
    where
      // Eigen / externe medewerkers
      (   (@SoortMedewerker = 0)
       or (@SoortMedewerker = 1 and CredNummer = '')
       or (@SoortMedewerker = 2 and CredNummer <> '')
      )
      and
      // Wel/niet geblokkeerde medewerkers
      (   (@Geblokkeerd = 0)
       or (@Geblokkeerd = 1 and pmwIsGeblokkeerd = 0)
       or (@Geblokkeerd = 2 and pmwIsGeblokkeerd = 1)
      )
      and
      // Wel/niet gekoppelde gebruiker
      (   (@GekoppeldeGebruiker = 0)
       or (@GekoppeldeGebruiker = 1 and GebruikerGid is not null)
       or (@GekoppeldeGebruiker = 2 and GebruikerGid is     null)
      )
      and
      // Met deze teamleider of allemaal
      (   (@VanTeamLeiderRelGid is null)
       or (pmwTeamLeiderRelGid = @VanTeamLeiderRelGid)
      )
      and
      // Goed te keuren mutaties (Let op de aanvulling in de having...)
      (   (@GoedTeKeuren = 0)                          //Alles tonen ook als er in de range niks is gevonden
       or (@GoedTeKeuren = 1 and (PbrAkkoordTL = 0))   // Indien alleen nog goed te keuren, dan MOET de mutatie bestaan
       or (@GoedTeKeuren = 2 and PbrAkkoordTL <> 0)   // Indien alleen goedgekeurde, dan MOET de mutatie bestaan!
      )
      and
      // Alleen opnemen indien werkdatum  binnen de werkdatum-range van de medewerker valt of er zijn mutaties
      (
           (@werkdatum >= isnull(PmwStartDatum, @werkdatum) and @werkdatum <= isnull(PmwEindDatum, @werkdatum))
        or (PbrGid is not null)

      )
      and
      //Of alle pbrStatus meenemen of Nog niet ingeleverde niet tonen
      (
        (@PbrStatus like '%' + string(isNull(PbrStatus,0)) + '%')
//        (isNull(PbrStatus,@VanafPbrStatus) >= @VanafPbrStatus)
      )
      and
      //En alleen als de mutatiesoort activiteit is.
      (isNull(PbrMutSoort,0) = 0)

    group by
      RelGid, RelNawGid, PmwStartDatum, PmwEindDatum, PmwControleUrenDag, PmwControleUrenWeek, Datum, Week, Maand, MinUren, MaxUren;
//    having
      // Goed te keuren mutaties: alle, alleen goed te keuren OF er is helemaal geen mutatie gevonden (ook dan opnemen)
//      @GoedTeKeuren in (1, 2) or
//      count(if PbrAkkoordTL <> 0 then PbrGid endif) = 0;

    case @TonenPer
      when 1 then set @WerkDatum = DateAdd(day,   1, @WerkDatum);
      when 2 then set @WerkDatum = DateAdd(week,  1, @WerkDatum);
      when 3 then set @WerkDatum = DateAdd(month, 1, @WerkDatum);
    end case;

  end loop;

  set @@ErrorTextProcedure = 'VulProjectUrenBrowse';
  //call traceEind(@@ErrorTextProcedure);

end;


create or replace procedure VulSelectieCodeTabel(in @Aantal integer, in @Code nchar(10))
begin
  declare @Teller integer;

  set @@ErrorTextProcedure = 'VulSelectieCodeTabel > @Aantal='+string(@Aantal)+', @Code='+@Code;
  //call TraceBegin(@@ErrorTextProcedure);

  set @Teller=1;
  while @Teller<=@Aantal loop
    insert into tabSelectiecodeTabel( SltCodeTabel) values (@Code + ' '+string(@Teller));
    set @Teller = @Teller + 1;
  end loop;

  set @@ErrorTextProcedure = 'VulSelectieCodeTabel';
  //call TraceBegin(@@ErrorTextProcedure);

end;


create or replace procedure VulTmpAfletter(in  @BjGid integer, in @DgbGid integer, in @RksGid integer, in @Status smallint, in @BoekDatum date, in @JpGid integer,
                                out @Openstaand numeric(15,2), out @ValCode nchar(3), out @InGebruik smallint)
begin
  declare @Pernr integer;
  declare @BetVersGid integer;

  //call TraceBegin('VulTmpAfletter (@BjGid='+string(@BjGid)+', @RksGid='+string(@RksGid)+', @Status='+string(@Status)+', @BoekDatum='+string(@BoekDatum)+', @JpGid='+string(@JpGid)+')');

  select PeriodeBepalen(@BjGid, @BoekDatum) into @Pernr;
  if @DgbGid is not null then
    select DgbBetRksGid into @BetVersGid from tabDagboek where DgbGid = @DgbGid;
  else
    select DgbBetRksGid into @BetVersGid from tabJournaalPost inner join tabDagboek on (DgbGid = JpDgbGid) where JpGid = @JpGid;
  end if;

  if exists(select 1 from tmpAfletter) then
    set @InGebruik = 1;
  else
    set @InGebruik = 0;
    // 1 regel toevoegen om ervoor te zorgen dat we later kunnen zien dat een connectie bezig is, ook als het resultaat leeg is.
    insert into tmpAfletter(tmpGid, tmpRksGid, tmpOspGid, tmpBoeken, tmpFactuurNr, tmpFactuurDatum, tmpVervalDatum) values (-1, -1, -1, 0, '', date(now()), date(now()));
    if @Status = 0 then // voorlopig
      insert into tmpAfletter( tmpRksGid, tmpOspGid, tmpBoeken, tmpFactuurNr, tmpFactuurDatum, tmpVervalDatum, tmpOms, tmpBetKenmerk,
                               tmpValuta, tmpOpenstaand, tmpTegenwaarde, tmpTeBetalen, tmpIsGeblokkeerd, tmpMeldingGeven,
                               tmpNotitie, tmpHulpTeBetalen, tmpKredietBeperkingsBedrag, tmpKredietBeperkingsDatum,
                               tmpVerschilBoekenAls, tmpTeBoekenVerschil, tmpSoortFactuur, tmpFactuurBedrag, tmpBetaaldBedrag, tmpValutaNummer,
                               tmpKredBepRekeningGeblokkeerd, tmpKredBepRksGid, tmpBetVersGeblokkeerd, tmpBetVersRksGid, tmpAlOpmerking,tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht)
      select @RksGid, Ospgid, 0, OspFactuurNummer, OspFactuurDatum, OspVervalDatum, OspOms, OspBetalingsKenmerk, OspValCode,
             IsNull(OspFactuurBedragVoorlopig,0) - IsNull(OspBetaaldBedragVoorlopig,0) Openstaand,
             if OspValnummer = @@BasisValutaNummer then Openstaand else ValutaOmrekenen(OspValnummer, Openstaand, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif,
             0, OspIsGeblokkeerd, OspMeldingGeven,
            (if IsNull(OspOpmerking, '') <> '' then 1 else 0 endif),
             if (OspSoortFactuur between 1 and 2) then
               if @BoekDatum<=OspKredietBeperkingsDatum then
                 OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig - OspKredietBeperkingsBedrag
               else
                 OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig
               endif
             else
               OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig
             endif,
             OspKredietBeperkingsBedrag, OspKredietBeperkingsDatum, 0, 0,
             //VR 08-10-04: ivm bug 15614, gewoon direct OspSoortFactuur overnemen.
             OspSoortFactuur,
             //(if (OspSoortFactuur between 1 and 2) and (@BoekDatum<=OspKredietBeperkingsDatum) then OspSoortFactuur else 0 endif),
             IsNull(OspFactuurBedragVoorlopig,0), IsNull(OspBetaaldBedragVoorlopig,0), OspValNummer, KredBep.IsRksGeblokkeerd, OspKredietBeperkingsRksGid,
            (select IsRksGeblokkeerd from tabRekeningschema where RksGid = @BetVersGid),
            @BetVersGid, OspOpmerking, OSPzitInVerwerkteBetalingsOfIncassoOpdracht(Ospgid)
     from   tabOpenstaandePost left outer join tabRekeningschema KredBep on (OspKredietBeperkingsRksGid=KredBep.RksGid)
     where  OspBjGid=@BjGid and OspRksGid=@RksGid and
           (OspFactuurBedragVoorlopig - OspBetaaldBedragVoorlopig)<>0
    else
      if @Status=1 then // definitief
        insert into tmpAfletter( tmpRksGid, tmpOspGid, tmpBoeken, tmpFactuurNr, tmpFactuurDatum, tmpVervalDatum, tmpOms, tmpBetKenmerk,
                                 tmpValuta, tmpOpenstaand, tmpTegenwaarde, tmpTeBetalen, tmpIsGeblokkeerd, tmpMeldingGeven,
                                 tmpNotitie, tmpHulpTeBetalen, tmpKredietBeperkingsBedrag, tmpKredietBeperkingsDatum,
                                 tmpVerschilBoekenAls, tmpTeBoekenVerschil, tmpSoortFactuur, tmpFactuurBedrag, tmpBetaaldBedrag, tmpValutaNummer,
                                 tmpKredBepRekeningGeblokkeerd, tmpKredBepRksGid, tmpBetVersGeblokkeerd, tmpBetVersRksGid, tmpAlOpmerking, tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht)
        select @RksGid, OspGid, 0, OspFactuurNummer, OspFactuurDatum, OspVervalDatum, OspOms, OspBetalingsKenmerk, OspValCode,
               IsNull(OspFactuurBedragDefinitief,0) - IsNull(OspBetaaldBedragDefinitief,0) Openstaand,
               if OspValnummer = @@BasisValutaNummer then Openstaand else ValutaOmrekenen(OspValnummer, Openstaand, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif,
               0, OspIsGeblokkeerd, OspMeldingGeven,
              (if IsNull(OspOpmerking, '') <> '' then 1 else 0 endif),
               if (OspSoortFactuur between 1 and 2) then
                  if @BoekDatum<=OspKredietBeperkingsDatum then
                     OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief - OspKredietBeperkingsBedrag
                  else
                     OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief
                  endif
               else
                  OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief
               endif,
               OspKredietBeperkingsBedrag, OspKredietBeperkingsDatum, 0, 0,
               //VR 08-10-04: ivm bug 15614, gewoon direct OspSoortFactuur overnemen.
               OspSoortFactuur,
               //(if (OspSoortFactuur between 1 and 2) and (@BoekDatum<=OspKredietBeperkingsDatum) then OspSoortFactuur else 0 endif),
               IsNull(OspFactuurBedragDefinitief,0), IsNull(OspBetaaldBedragDefinitief,0), OspValNummer, KredBep.IsRksGeblokkeerd, OspKredietBeperkingsRksGid,
              (select IsRksGeblokkeerd from tabRekeningschema where RksGid = @BetVersGid),
               @BetVersGid, OspOpmerking, OSPzitInVerwerkteBetalingsOfIncassoOpdracht(Ospgid)
        from   tabOpenstaandePost left outer join tabRekeningschema KredBep on (OspKredietBeperkingsRksGid=KredBep.RksGid)
        where  OspBjGid=@BjGid and OspRksGid=@RksGid and
              (OspFactuurBedragDefinitief - OspBetaaldBedragDefinitief)<>0;

      else // beide
        insert into tmpAfletter( tmpRksGid, tmpOspGid, tmpBoeken, tmpFactuurNr, tmpFactuurDatum, tmpVervalDatum, tmpOms, tmpBetKenmerk,
                                 tmpValuta, tmpOpenstaand, tmpTegenwaarde, tmpTeBetalen, tmpIsGeblokkeerd, tmpMeldingGeven,
                                 tmpNotitie, tmpHulpTeBetalen, tmpKredietBeperkingsBedrag, tmpKredietBeperkingsDatum,
                                 tmpVerschilBoekenAls, tmpTeBoekenVerschil, tmpSoortFactuur, tmpFactuurBedrag, tmpBetaaldBedrag, tmpValutaNummer,
                                 tmpKredBepRekeningGeblokkeerd, tmpKredBepRksGid, tmpBetVersGeblokkeerd, tmpBetVersRksGid, tmpAlOpmerking, tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht)
        select @RksGid, OspGid, 0, OspFactuurNummer, OspFactuurDatum, OspVervalDatum, OspOms, OspBetalingsKenmerk, OspValCode,
               (IsNull(OspFactuurBedragVoorlopig,0) + IsNull(OspFactuurBedragDefinitief,0)) - (IsNull(OspBetaaldBedragVoorlopig,0) + IsNull(OspBetaaldBedragDefinitief,0)) Openstaand,
               if OspValnummer = @@BasisValutaNummer then Openstaand else ValutaOmrekenen(OspValnummer, Openstaand, @@BasisValutaNummer, @BjGid, @Pernr, 2) endif,
               0, OspIsGeblokkeerd, OspMeldingGeven,
              (if IsNull(OspOpmerking, '') <> '' then 1 else 0 endif),
               if (OspSoortFactuur between 1 and 2) then
                  if @BoekDatum<=OspKredietBeperkingsDatum then
                     (IsNull(OspFactuurBedragDefinitief,0) - IsNull(OspBetaaldBedragDefinitief,0) ) +
                     (IsNull(OspFactuurBedragVoorlopig,0) - IsNull(OspBetaaldBedragVoorlopig,0) ) - IsNull(OspKredietBeperkingsBedrag,0)
                  else
                     (IsNull(OspFactuurBedragDefinitief,0) - IsNull(OspBetaaldBedragDefinitief,0)) +
                     (IsNull(OspFactuurBedragVoorlopig,0) - IsNull(OspBetaaldBedragVoorlopig,0))
                  endif
               else
                     (IsNull(OspFactuurBedragDefinitief,0) - IsNull(OspBetaaldBedragDefinitief,0)) +
                     (IsNull(OspFactuurBedragVoorlopig,0) - IsNull(OspBetaaldBedragVoorlopig,0))
               endif,
               IsNull(OspKredietBeperkingsBedrag,0), OspKredietBeperkingsDatum, 0, 0,
               //VR 08-10-04: ivm bug 15614, gewoon direct OspSoortFactuur overnemen.
               OspSoortFactuur,
               //(if (OspSoortFactuur between 1 and 2) and (@BoekDatum<=OspKredietBeperkingsDatum) then OspSoortFactuur else 0 endif),
               IsNull(OspFactuurBedragDefinitief,0)+IsNull(OspFactuurBedragVoorlopig,0), IsNull(OspBetaaldBedragDefinitief,0)+IsNull(OspBetaaldBedragVoorlopig,0),
               OspValNummer, KredBep.IsRksGeblokkeerd, OspKredietBeperkingsRksGid,
              (select IsRksGeblokkeerd from tabRekeningschema where RksGid = @BetVersGid),
               @BetVersGid, OspOpmerking, OSPzitInVerwerkteBetalingsOfIncassoOpdracht(Ospgid)
        from   tabOpenstaandePost left outer join tabRekeningschema KredBep on (OspKredietBeperkingsRksGid=KredBep.RksGid)
        where  OspBjGid = @BjGid and OspRksGid = @RksGid and OspIsVervallen = 0;
      end if;
    end if;
    //Ook nog even de journaalregels in deze journaalpost erbij zetten, behalve diegene die al in tmpAfletter staan
    insert into tmpAfletter( tmpRksGid, tmpOspGid, tmpBoeken, tmpFactuurNr, tmpFactuurDatum, tmpVervalDatum, tmpOms, tmpBetKenmerk,
                             tmpValuta, tmpOpenstaand, tmpTegenwaarde, tmpTeBetalen, tmpIsGeblokkeerd, tmpMeldingGeven,
                             tmpNotitie, tmpHulpTeBetalen, tmpKredietBeperkingsBedrag, tmpKredietBeperkingsDatum,
                             tmpVerschilBoekenAls, tmpTeBoekenVerschil, tmpSoortFactuur, tmpFactuurBedrag, tmpValutaNummer,
                             tmpKredBepRekeningGeblokkeerd, tmpKredBepRksGid, tmpBetVersGeblokkeerd, tmpBetVersRksGid, tmpAlOpmerking, tmpAlOSPzitInVerwerkteBetalingsOfIncassoOpdracht)
    select JrRksGid, JrOspGid, 0, OspFactuurNummer, OspFactuurDatum, OspVervalDatum, OspOms, OspBetalingsKenmerk,
           OspValCode, 0, 0, 0, 0, 0, 0, 0, 0, null, 0, 0, 0, 0, OspValNummer, 0, null, 0, null, OspOpmerking, OSPzitInVerwerkteBetalingsOfIncassoOpdracht(JrOspGid)
    from   tabBoekingsgang inner join tabJournaalPost on (JpBoekgangGid = BoekgangGid) inner join tabJournaalregel on (JrJpGid = JpGid) inner join tabOpenstaandePost on (OspGid = JrOspGid)
    where  JrJpGid=@JpGid and (IsBoekgangDefinitief=@Status or @Status=2) and JrRksGid=@RksGid and
      not (JrRksGid in (select tmpRksGid from tmpAfletter) and JrReferentie in (select tmpFactuurNr from tmpAfletter))
      and JpIsInGebruik = 1 //ACW: Alleen opnemen als de journaalpost in gebruik is, anders is het al in de OSP verwerkt
    group by JrRksGid, OspFactuurNummer, JrOspGid, OspFactuurDatum, OspVervalDatum, OspOms, OspBetalingsKenmerk, OspValCode, OspValNummer, OspOpmerking;

    //Bedrag bijwerken met bedragen uit huidige journaalpost waar gebruiker in bezig is
    //ACW: Maar dan alleen als de journaalpost in gebruik is
    update tmpAfletter set tmpOpenstaand = tmpOpenstaand + (if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif) - (if IsBetaling(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif),
                           tmpTegenwaarde = ValutaOmrekenen(JrValnummer, tmpOpenstaand + (if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif) - (if IsBetaling(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif), @@BasisValutaNummer, @BjGid, @Pernr, 2),
                           tmpHulpTeBetalen = tmpHulpTeBetalen + (if IsFactuurBoeking(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif) - (if IsBetaling(JrRksGid, IsCreditBoeking) = 1 then JrValutaBedrag else 0 endif)
    from tabBoekingsgang, tabJournaalpost, tabJournaalregel where BoekGangGid=JpBoekGangGid and JpGid=JrJpGid and (IsBoekgangDefinitief=@Status or @Status=2) and JpGid=@JpGid and tmpRksGid=JrRksGid and tmpFactuurNr=JrReferentie and JpIsInGebruik = 1;

    delete tmpAfLetter where tmpOpenstaand=0 and tmpGid<>-1;
    select sum(tmpTegenwaarde) into @Openstaand from tmpAfletter;
    select ValCode into @Valcode from tabValuta where IsBasisValuta<>0;

  end if;

  //call TraceEind('VulTmpAfletter');

end;


create or replace procedure VulXmlImportVelden(in @IelGid integer)
begin
  declare @IelSoort integer;

  set @@ErrorTextProcedure = 'VulXmlImportVelden > @IelGid='+string(@IelGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //TfrmXmlImportlayoutsEdit.FormReceiveAction ook aanpassen om paneel voor nieuwe importsoort zichtbaar te maken


  select IelSoort into @IelSoort from tabImportExportLayout where IelGid = @IelGid;

  if @IelSoort = 4 then //=artikelen
    if not exists (select 1 from tabImportExportLayoutVelden where IelVeldIelGid = @IelGid and IelVeldNaam = 'ART_ZOEKCODE') then
      insert into tabImportExportLayoutVelden (IelVeldIelGid, IelVeldDefaultWaardeOveralDoorvoeren, IelVeldNaam, IelVeldDisplayNaam)
                  values (@IelGid, 1, 'ART_ZOEKCODE', _A('Zoekcode'));
    end if;
    if not exists (select 1 from tabImportExportLayoutVelden where IelVeldIelGid = @IelGid and IelVeldNaam = 'ART_OMSCHRIJVING') then
      insert into tabImportExportLayoutVelden (IelVeldIelGid, IelVeldDefaultWaardeOveralDoorvoeren, IelVeldNaam, IelVeldDisplayNaam)
                  values (@IelGid, 1, 'ART_OMSCHRIJVING', _A('Omschrijving'));
    end if;
    if not exists (select 1 from tabImportExportLayoutVelden where IelVeldIelGid = @IelGid and IelVeldNaam = 'ART_OPBRENGSTGROEP') then
      insert into tabImportExportLayoutVelden (IelVeldIelGid, IelVeldDefaultWaardeOveralDoorvoeren, IelVeldNaam, IelVeldDisplayNaam)
