create or replace procedure WebQueueOpruimen()
begin
  // Ruimt de dubbele records in tabWebQueue op

  //call TraceBegin('WebQueueOpruimen');

  delete tabWebQueue where WqActie <> 7 and WqGid not in (select Min(Sub.WqGid) from tabWebQueue Sub group by Sub.wqActie, Sub.wqRecordId, Sub.wqRecordSoort, Sub.wqExternId, Sub.WqWscGid); // 7 = Verwerken (bijv. 2 te verwerken naw-wijzigingen)

  //call TraceEind('WebQueueOpruimen');
end;


create or replace procedure WebSvcProcMaatwerk_ChecksumToevoegen(in @LicNummer nchar(10), in @LchkVersie nchar(10), in @LchkAantalGebruikers integer, in @LchkOpties long nvarchar, in @LchkNaam nchar(30), in @LchkAdres nchar(30), in @LchkPlaats nchar(30))
begin
  declare @CmdCommand nchar(5000);
  declare @ErrorValue integer;
  declare @ErrorText  nchar(255);
  declare @iLogGid    integer;

  set @@ErrorTextProcedure = 'WebSvcProcMaatwerk_ChecksumToevoegen';
  //call TraceBegin(@@ErrorTextProcedure);

  insert into tabImportLog(iLogProgramma, iLogResultaat) values('WebSvcProcMaatwerk_ChecksumToevoegen', _A('%1! wordt uitgevoerd', 'WebSvcProcMaatwerk_ChecksumToevoegen'));
  set @iLogGid = @@Identity;

  call ImportLogDetail_Toevoegen(@iLogDetilogGid = @iLogGid,
                                 @iLogDetReden = _A('Webservice gestart'),
                                 @iLogDetStatus = 8);

  if IsModuleActive('m8') <> 0 then //Alleen voor intern gebruik
    //Commando eerst opslaan om bij evt. fout in taak weer te geven, en vervolgens uitvoeren
    set @CmdCommand = 'call xp_cmdshell(F:\Progra~1\King\KingLicGen.exe LICNUMMER ' + @LicNummer + ' LICVERSIE ' + @LchkVersie + ' LICAANTALGEB ' +cast(@LchkAantalGebruikers as nchar)+ '  LICOPTIES ' + @LchkOpties  + ' LICNAAM ' + @LchkNaam + ' LICADRES ' + @LchkAdres + ' LICPLAATS ' + @LchkPlaats + ', no_output)';

    call ImportLogDetail_Toevoegen(@iLogDetilogGid = @iLogGid,
                                   @iLogDetReden = @CmdCommand,
                                   @iLogDetStatus = 8);

    @ErrorValue = call xp_cmdshell('F:\Progra~1\King\KingLicGen.exe LICNUMMER ' + @LicNummer + ' LICVERSIE ' + @LchkVersie + ' LICAANTALGEB ' +cast(@LchkAantalGebruikers as nchar)+ '  LICOPTIES ' + @LchkOpties + ' LICNAAM ' + @LchkNaam + ' LICADRES ' + @LchkAdres + ' LICPLAATS ' + @LchkPlaats , 'no_output');

    call ImportLogDetail_Toevoegen(@iLogDetilogGid = @iLogGid,
                                   @iLogDetReden =  _A('Terugkeer vanuit %1!', 'KingLicGen.exe'),
                                   @iLogDetStatus = 8);

    case @ErrorValue
      when  0 then set @ErrorText = ''; //aanmaken gelukt
      when  1 then set @ErrorText = _A('%1! niet gevonden', 'KingLicGen.exe');
      when  2 then set @ErrorText = _A('De checksum kan niet worden berekend, omdat 1 of meer verplichte velden zijn niet ingevuld');
      when  3 then set @ErrorText = _A('Opslaan is niet goed gegaan');
      when  4 then set @ErrorText = _A('Optiecode bestaat niet');
      when  5 then set @ErrorText = _A('Geen uitbreidingen gevonden voor licentie');
      when  6 then set @ErrorText = _A('De gegevens zijn in gebruik');
      when  7 then set @ErrorText = _A('Kan geen verbinding maken met Quadrant.db');
      when  8 then set @ErrorText = _A('Aanmaken licentie niet gelukt');
      when  9 then set @ErrorText = _A('Onbekende pakket versie');
      when 10 then set @ErrorText = _A('Ongeldig aantal gebruikers');
      when 11 then set @ErrorText = _A('Ongeldig licentienummer meegegeven');
      when 12 then set @ErrorText = _A('Combinatie van pakket, release en versie is onbekend of niet (volledig) ingevuld! Controleer de gegevens en probeer opnieuw');
      when 13 then set @ErrorTest = _A('Domeinnaam klopt niet');
      when 14 then set @ErrorTest = _A('Kan domeinnaam niet opvragen');
      else         set @ErrorText = _A('Onbekende fout opgetreden');
    end; //end case

    call ImportLogDetail_Toevoegen(@iLogDetilogGid = @iLogGid,
                                   @iLogDetReden = ('KingLicGen.exe -> @ErrorValue = ' + string(@ErrorValue) + ' - ' + @ErrorText),
                                   @iLogDetStatus = (if @ErrorValue = 0 then 8 else 6 endif));

    //Bij fout tabel vullen en fout teruggeven
    if isnull(@ErrorText,'') <> '' then
      insert into tab_KTC_ChecksumAanmaken (ChksAanmLicNr, ChksAanmCmdCommand, ChksAanmResultCode, ChksAanmResultOms)
                                    values (@LicNummer,    @CmdCommand,        @ErrorValue,        @ErrorText);
      select string(@ErrorValue) + ' - ' + @ErrorText as ReturnValue;
    end if;

  else
    call ImportLogDetail_Toevoegen(@iLogDetilogGid = @iLogGid,
                                   @iLogDetReden = _A('Deze webservice is niet geschikt voor uw licentie!'),
                                   @iLogDetStatus = 6);

    call Raise(20588); //Deze webservice is niet geschikt voor uw licentie!
  end if;

  call ImportLogDetail_Toevoegen(@iLogDetilogGid = @iLogGid,
                                 @iLogDetReden = _A('Webservice uitgevoerd'),
                                 @iLogDetStatus = 8);

  update tabImportLog set iLogResultaat = _A('%1! uitgevoerd', 'WebSvcProcMaatwerk_ChecksumToevoegen') where iLogGid = @iLogGid;

  set @@ErrorTextProcedure = 'WebSvcProcMaatwerk_ChecksumToevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;

alter procedure WebSvcProcMaatwerk_ChecksumToevoegen set hidden;

//----------------------------------------------------
//  Naam samenstellen voor gegenereerde webtriggers,
//  Trigger-naam mag van Sybase precies 128 zijn.
//----------------------------------------------------
create or replace function WebTriggerNaam(in @TableName nchar(40), in @ExportSoort nchar(80))
  returns nchar(128)
begin
  declare @TriggerName nchar(128);

  set @@ErrorTextProcedure = 'WebTriggerNaam(@TableName='+@TableName+', @ExportSoort='+@ExportSoort+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @TriggerName = 'ta_' + @TableName + '_Web_' + @ExportSoort;

  return @TriggerName;

  //call TraceEind(@@ErrorTextProcedure);
end;


// -------------------------------------------------------------------------------------
// ---------------- Toevoegen dynamische triggers tgv webshop --------------------------
// -------------------------------------------------------------------------------------
create or replace procedure WebTriggerToevoegen(in @TableName nchar(40), in @ExportVlsNaam nchar(80), in @TriggerOrder smallint, in @SelectInsert long nvarchar, in @SelectUpdate long nvarchar, in @SelectDelete long nvarchar)
begin
  declare @TriggerName      nchar(128);
  declare @TriggerStatement long nvarchar;

  set @@ErrorTextProcedure = 'WebTriggerToevoegen(@TableName='+@TableName+', @ExportVlsNaam='+@ExportVlsNaam+', @SelectInsert='+@SelectInsert+', @SelectUpdate='+@SelectUpdate+', @SelectDelete='+@SelectDelete+');';
  //call TraceBegin(@@ErrorTextProcedure);

  set @TriggerName = WebTriggerNaam(@TableName, @ExportVlsNaam);

  set @TriggerStatement = 'create trigger ' + @TriggerName + ' after insert, update, delete order ' + string(@TriggerOrder) + ' on ' + @TableName + char(13) +
                          'referencing old as Old_Record new as New_Record for each row ' + char(13) +
                          'begin ' + char(13) +
                          '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                          '  //call TraceBegin(@@ErrorTextTrigger);' + char(13) +

                          '  if @@BlockWebtriggers = 0 then ' + char(13) +
                          '    if inserting then ' + char(13) +
                          '      insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, WqWscGid) ' + char(13) +
                          '        ' + @SelectInsert + '; ' + char(13) +
                          '    elseif updating then ' + char(13) +
                          '      insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, WqWscGid) ' + char(13) +
                          '        ' + @SelectUpdate + '; ' + char(13) +
                          '    elseif deleting then ' + char(13) +
                          '      insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, WqWscGid) ' + char(13) +
                          '        ' + @SelectDelete + '; ' + char(13) +
                          '    end if; ' + char(13) +
			                    '  end if; ' + char(13) +

                          '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                          '  //call TraceEind(@@ErrorTextTrigger);' + char(13) +
                          'end;';

  //execute immediate 'unload select @TriggerStatement to ''C:\WebTrigger\'+@TriggerName+'.tr'' escapes off quotes off';

  execute immediate @TriggerStatement;

  //call TraceEind(@@ErrorTextProcedure);
end;


// -------------------------------------------------------------------------------------
// ------------- verwijderen dynamisch aangemaakte triggers tbv webshop ----------------
// -------------------------------------------------------------------------------------
create or replace procedure WebTriggerVerwijderen(in @TableName nchar(40), in @ExportSoort nchar(80))
begin
  declare @TriggerName         nchar(128);
  declare @DelTriggerStatement long nvarchar;

  set @@ErrorTextProcedure = 'WebTriggerVerwijderen(@TableName='+@TableName+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @TriggerName = WebTriggerNaam(@TableName, @ExportSoort);

  set @DelTriggerStatement = 'if exists (select 1 from sys.sysTrigger where trigger_name=''' + @TriggerName + ''') then '+
                             '  drop trigger ' + @TriggerName + '; '+
                             'end if; ';
  //call Trace(@DelTriggerStatement);
  execute immediate @DelTriggerStatement;

  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebVoorraadQueueBijwerken(in @WscGid integer)
begin
  // -------------------------------------------------------------------------------------
  // Vergelijkt de huidige voorraadgegevens van artikel/magazijncombinatie met de vorige
  // voorraadgegevens en plaatst het artikel in tabWebQueue indien er wijzigingen zijn
  // -------------------------------------------------------------------------------------
  declare local temporary table tmpWebVoorraad(
    twvGid  integer not null default autoincrement,
    twvWscGid integer not null,
    twvArtGid integer not null,
    twvArtCode nchar(20) not null,
    twvMagGid integer not null,
    twvMagazijnVoorraad numeric(15,3),
    twvVrijeVoorraad numeric(15,3),
    twvEconomischeVoorraad numeric(15,3)
  ) on commit preserve rows;

  set @@ErrorTextProcedure = 'WebVoorraadQueueBijwerken > ';
  //call TraceBegin(@@ErrorTextProcedure);

  //Toevoegen huidige voorraad naar tmpWebVoorraad
  insert into tmpWebVoorraad (twvWscGid, twvArtGid, twvArtCode, twvMagGid, twvMagazijnVoorraad, twvVrijeVoorraad, twvEconomischeVoorraad)
  select @WscGid, ArtGid, ArtCode, calcMagGid, sum(calcMagazijnVoorraad) MagazijnVoorraad, sum(calcVrijeVoorraad) VrijeVoorraad, sum(calcEconomischeVoorraad) EconomischeVoorraad
  from vwVoorraadAantallen
  inner join tabArtikel on calcArtGid = ArtGid and ArtWebArtikel = 1 inner join tabWebArtikel on WArtArtGid = ArtGid and WArtWscGid = @WscGid
  where calcMagGid is not null
  group by ArtGid, ArtCode, calcMagGid;

  //call Trace('WebVoorraadQueueBijwerken > Aantal records toegevoegd aan tmpWebVoorraad : ' + string(@@RowCount));

  create unique index idx_twvWscArtMagMagVrdVrVrdEcVrd on tmpWebVoorraad (TwvWscGid, TwvArtGid, TwvMagGid, TwvMagazijnVoorraad, TwvVrijeVoorraad, TwvEconomischeVoorraad) with nulls not distinct;

  //Toevoegen uit de oude voorraad alles wat gewijzigd is sinds de vorige keer
  insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, wqWscGid)
  select 0, wvArtCode, 7, @WscGid
  from tabWebVoorraad
  where WvWscGid = @WscGid
  and not exists( select 1
                    from tmpWebVoorraad
                    where twvWscGid = wvWscGid
                    and twvArtGid = wvArtGid
                    and twvMagGid = wvMagGid
                    and twvMagazijnVoorraad = wvMagazijnVoorraad
                    and twvVrijeVoorraad = wvVrijeVoorraad
                    and twvEconomischeVoorraad = wvEconomischeVoorraad)
  and not exists( select 1
                  from tabWebQueue
                  where wqWscGid = wvWscGid
                  and wqRecordSoort = 7
                  and wqActie = 0
                  and wqRecordId = wvArtCode);

  //call Trace('WebVoorraadQueueBijwerken > Aantal records toegevoegd aan tabWebQueue : ' + string(@@RowCount));

  //Toevoegen uit huidige voorraad voor de verwijderde.
  insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, wqWscGid)
  select 0, twvArtCode, 7, @WscGid
  from tmpWebVoorraad
  where twvWscGid = @WscGid
  and not exists( select 1
                    from tabWebVoorraad
                    where wvWscGid = twvWscGid
                    and wvArtGid = twvArtGid
                    and wvMagGid = twvMagGid
                    and wvMagazijnVoorraad = twvMagazijnVoorraad
                    and wvVrijeVoorraad = twvVrijeVoorraad
                    and wvEconomischeVoorraad = twvEconomischeVoorraad)
  and not exists( select 1
                  from tabWebQueue
                  where wqWscGid = twvWscGid
                  and wqRecordSoort = 7
                  and wqActie = 0
                  and wqRecordId = twvArtCode);

  //call Trace('WebVoorraadQueueBijwerken > Aantal records gewijzigd in tabWebQueue : ' + string(@@RowCount));

  //Update huidige records
  update tabWebvoorraad
  set wvMagazijnVoorraad    = twvMagazijnVoorraad ,
      wvVrijeVoorraad       = twvVrijeVoorraad,
      wvEconomischeVoorraad = twvEconomischeVoorraad
  from tmpWebVoorraad
  where twvWscGid = @WscGid
  and twvWscGid = wvWscGid
  and twvArtGid = wvArtGid
  and twvMagGid = wvMagGid
  and (twvMagazijnVoorraad <> wvMagazijnVoorraad or twvVrijeVoorraad <> wvVrijeVoorraad or twvEconomischeVoorraad <> wvEconomischeVoorraad);

  //call Trace('WebVoorraadQueueBijwerken > Aantal records gewijzigd in tabWebvoorraad : ' + string(@@RowCount));

  //Toevoegen nieuwe records
  insert into tabWebVoorraad (wvWscGid, wvArtGid, wvArtCode, wvMagGid, wvMagazijnVoorraad, wvVrijeVoorraad, wvEconomischeVoorraad)
  select twvWscGid, twvArtGid, twvArtCode, twvMagGid, twvMagazijnVoorraad, twvVrijeVoorraad, twvEconomischeVoorraad
  from tmpWebVoorraad
  where twvWscGid = @WscGid
  and not exists( select 1
                    from tabWebVoorraad
                    where wvWscGid = twvWscGid
                    and wvArtGid = twvArtGid
                    and wvMagGid = twvMagGid);

  //call Trace('WebVoorraadQueueBijwerken > Aantal records toegevoegd aan tabWebVoorraad : ' + string(@@RowCount));

  //Verwijderen verwijderde artikelen of magazijnen.
  delete from tabWebVoorraad
  where WvWscGid = @WscGid
  and not exists( select 1
                    from tmpWebVoorraad
                    where twvWscGid = wvWscGid
                    and twvArtGid = wvArtGid
                    and twvMagGid = wvMagGid);

  //call Trace('WebVoorraadQueueBijwerken > Aantal records verwijderd in tabWebVoorraad : ' + string(@@RowCount));

  update tabWebVoorraadArtikelLocatie set WvlVoorraad = ArtLocVoorraad
  from   tabArtikelLocatie
  inner join tabWebVoorraad on WvArtGid = ArtLocArtGid
  where  WvlWscGid       = @WscGid
    and  WvlArtGid       = ArtLocArtGid
    and  WvlArtMagGid    = ArtLocArtMagGid
    and  WvlLocGid       = ArtLocLocGid
    and  IsNull(WvlArtPartijGid, -1) = IsNull(ArtLocPartijGid, -1)
    and  WvlVoorraad    <> ArtLocVoorraad;

  //call Trace('WebVoorraadQueueBijwerken > Aantal records gewijzigd in tabWebVoorraadArtikelLocatie : ' + string(@@RowCount));

  insert into tabWebVoorraadArtikelLocatie(WvlWscGid, WvlArtGid, WvlArtMagGid, WvlLocGid, WvlArtPartijGid, WvlVoorraad)
  select @WscGid, ArtLocArtGid, ArtLocArtMagGid, ArtLocLocGid, ArtLocPartijGid, ArtLocVoorraad
  from tabArtikelLocatie
  inner join tabWebVoorraad on WvArtGid = ArtLocArtGid and WvWscGid = @WscGid
  // 2024-02-26 defect 59698: Hier werd helemaal geen join op magazijn gemaakt!
  inner join tabArtikelMagazijn on ArtMagGid = ArtLocArtMagGid and ArtMagMagGid = wvmagGid
  where not exists(select 1
                     from  tabWebVoorraadArtikelLocatie
                    where  WvlWscGid       = @WscGid
                      and  WvlArtGid       = ArtLocArtGid
                      and  WvlArtMagGid    = ArtLocArtMagGid
                      and  WvlLocGid       = ArtLocLocGid
                      and  IsNull(WvlArtPartijGid, -1) = IsNull(ArtLocPartijGid, -1));

  //call Trace('WebVoorraadQueueBijwerken > Aantal records toegevoegd in tabWebVoorraadArtikelLocatie : ' + string(@@RowCount));

  delete tabWebVoorraadArtikelLocatie
  where WvlWscGid = @WscGid
        and not exists(select     1
                       from       tabArtikelLocatie
                       inner join tabWebVoorraad on WvArtGid = ArtLocArtGid
                       where      WvlArtGid       = ArtLocArtGid
                         and      WvlArtMagGid    = ArtLocArtMagGid
                         and      WvlLocGid       = ArtLocLocGid
                         and      IsNull(WvlArtPartijGid, -1) = IsNull(ArtLocPartijGid, -1));

  //call Trace('WebVoorraadQueueBijwerken > Aantal records verwijderd in tabWebVoorraadArtikelLocatie : ' + string(@@RowCount));

  set @@ErrorTextProcedure = 'WebVoorraadQueueBijwerken';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebwinkelMaakJob(in @WscGid integer)
begin
  declare @JobkGid integer;
  declare @JobkNummer integer;
  set @@ErrorTextProcedure = 'WebwinkelMaakJob';
  //call TraceBegin(@@ErrorTextProcedure);

  select JobkGid into @JobkGid from tabJobKop where jobkWscGid = @WscGid and jobkSoort = 1;
  if @JobkGid is null then
    set @JobkNummer = -1;
    // Multi-shop: iedere shop zijn eigen job. Beginnend bij -1, dan -2, -3 etc
    while exists(select 1 from tabJobKop where JobkNummer = @JobkNummer)
    loop
      set @JobkNummer = @JobkNummer - 1;
    end loop;
    insert into tabJobKop (jobkNummer, jobkOmschrijving, jobkSoort, jobkWscGid )
                  values (@JobkNummer, _A('Webwinkel job'), 1, @WscGid);
    set @JobkGid = @@Identity;
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 18) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (18, @JobkGid, 1, _A('Export artikelen'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 46) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (46, @JobkGid, 13, _A('Export tarieven'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 20) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (20, @JobkGid, 2, _A('Export debiteuren'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 60) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (60, @JobkGid, 12, _A('Export debiteurgroepen'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 41) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (41, @JobkGid, 3, _A('Export voorraadaantallen'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 50) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (50, @JobkGid, 6, _A('Export staffeltabellen'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 51) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (51, @JobkGid, 7, _A('Export prijsafspraken'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 56) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (56, @JobkGid, 8, _A('Export btwcodes'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 57) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (57, @JobkGid, 9, _A('Export opbrengstgroepen'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 58) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (58, @JobkGid, 10, _A('Export valutas'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrExpSoortGid = 62) then
    insert into tabJobRegel (jobrExpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                     values (62, @JobkGid, 14, _A('Export vaste gegevens BTW'), 0, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrImpSoortGid = 5) then
    insert into tabJobRegel (jobrImpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                   values (5, @JobkGid, 4, _A('Import debiteuren'), 1, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrImpSoortGid = 3) then
    insert into tabJobRegel (jobrImpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                   values (3, @JobkGid, 5, _A('Import orders'), 1, 0);
  end if;

  if not exists(select 1 from tabJobRegel where JobrJobkGid = @JobkGid and JobrImpSoortGid = 22) then
    insert into tabJobRegel (jobrImpSoortGid, jobrJobkGid, jobrNummer, jobrOmschrijving, jobrSoort, jobrEnabled)
                   values (22, @JobkGid, 11, _A('Import orderwijzigingen'), 1, 0);
  end if;

  set @@ErrorTextProcedure = 'WebwinkelMaakJob';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WijzigenKostprijsPartijBoeken(in @BoekgangGid integer, in @ArtOpbrGrpGid integer, in @BedragMutatie Numeric(15,2), in @JPOmschrijving nchar(40), In @ArtGid integer, In @ArtPartijNummer nchar(20))
begin
  declare @JpGid                  integer;
  declare @DgbGid                 integer;
  declare @Boekstuknummer         numeric(10,0);
  declare @RksGrpGid              integer;
  declare @Boekzijde              smallint;
  declare @JRBedrag               Numeric(15,2);

  set @@ErrorTextProcedure = 'WijzigenKostprijsPartijBoeken > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @BoekgangGid = ' + string(@BoekgangGid) + ', @ArtOpbrGrpGid = ' + string(@ArtOpbrGrpGid) + ', @BedragMutatie = ' + string(@BedragMutatie) + ', @JPOmschrijving = ' + @JPOmschrijving);

  // DagboekGid ophalen
  select ArtVastPrijsWijzDgbGid into @DgbGid from tabArtikelVasteGegevens where ArtVastSoort = 2;

  // Boekstuknummer genereren
  call BoekstuknummerGenereren(@@BjGid, @DgbGid, @Boekstuknummer);

  // Journaalpost aanmaken
  insert into tabJournaalPost (JpBoekGangGid, JpBjGid, JpDgbGid, BoekStukNummer , OmsJournaalpost, BoekDatum,          JpIsInGebruik)
                       values (@BoekGangGid , @@BjGid, @DgbGid , @Boekstuknummer, @JPOmschrijving, @@Verwerkingsdatum, 1);
  set @JpGid = @@Identity;

  // JournaalpostRegels aanmaken

  // Verschillen boeken
  //     <Reknr> Voorraad      partij groep xxxx    100,-
  // Aan <Reknr> Herwaardering partij groep xxxx             100,-

  // bepaal rekeningnummer groep 50 / voorraad
  call GeefRksUitOpbrGroepEnPar(@ArtOpbrGrpGid, 50, @RksGrpGid);

  // boekzijde Voorraad uitlezen
  select DefaultBoekZijde into @Boekzijde from tabRekeningschema where RksGid = @RksGrpGid;

  // Te boeken bedrag bepalen obv de boekzijde
  case @Boekzijde
  when 0 then set @JRBedrag = @BedragMutatie;
  when 1 then set @JRBedrag = -@BedragMutatie;
  when 2 then
    // 0 en groter is positief, < 0 is negatief
    if @BedragMutatie < 0 then
      set @JRBedrag = -@BedragMutatie;
      set @Boekzijde = 1;
    else
      set @JRBedrag = @BedragMutatie;
      set @Boekzijde = 0;
    end if;
  end case;

  // Journaalregel aanmaken
  insert into tabJournaalRegel(JrJpGid, JrRksGid  , JrValutaBedrag, JrBasisBedrag, IsCreditBoeking, SoortBoeking, JrValNummer        , OmsJournaalRegel)
  select                       @JpGid , @RksGrpGid, @JRBedrag     , @JRBedrag    , @Boekzijde     , 0           , @@BasisValutaNummer, @JPOmschrijving;

  //Zet hier het jpGid voor de prijswijziging.
  update tabprijswijzigingshistorie
    set pwhJpGid = @JpGid
    where PwhArtGID = @artGid
    And PwhArtPartijnummer = @ArtPartijNummer
    And PwhDatum = (select Max(pwhdatum) from tabprijswijzigingshistorie where PwhArtGID = @artGid
    And PwhArtPartijnummer = @ArtPartijNummer);

  // bepaal rekeningnummer groep 80 / Herwaardering
  call GeefRksUitOpbrGroepEnPar(@ArtOpbrGrpGid, 80, @RksGrpGid);

  // boekzijde Herwaardering uitlezen
  select DefaultBoekZijde into @Boekzijde from tabRekeningschema where RksGid = @RksGrpGid;

  // Te boeken bedrag bepalen obv de boekzijde
  case @Boekzijde
  when 0 then set @JRBedrag = -@BedragMutatie;
  when 1 then set @JRBedrag =  @BedragMutatie;
  when 2 then
    // 0 en groter is positief, < 0 is negatief
    if @BedragMutatie < 0 then
      set @JRBedrag  = @BedragMutatie;
      set @Boekzijde = 1;
    else
      set @JRBedrag  = -@BedragMutatie;
      set @Boekzijde = 0;
    end if;
  end case;

  // Journaalregel aanmaken
  insert into tabJournaalRegel(JrJpGid, JrRksGid  , JrValutaBedrag, JrBasisBedrag, IsCreditBoeking, SoortBoeking, JrValNummer        , OmsJournaalRegel)
  select                       @JpGid , @RksGrpGid, @JRBedrag     , @JRBedrag    , @Boekzijde     , 0           , @@BasisValutaNummer, @JPOmschrijving;

  // Journaalpost vrijgegeven
  update tabJournaalpost set JpIsInGebruik = 0 where JpGid = @JpGid;

  set @@ErrorTextProcedure = 'WijzigenKostprijsPartijBoeken';
  //call TraceEind(@@ErrorTextProcedure);
end;


//VvE 17-07-2017 Incident I10818 was aanleiding.
//Functie waarmee je toch grootboekrekeningnummer kan aanpassen. Hij past zoveel mogelijk redundante velden aan.
create or replace procedure WijzigGrootboekrekeningNummer(in @RksGid integer, in @NieuweRksNummer nchar(10))
begin atomic

  update tabRekeningschema  set RksNummer    = @NieuweRksNummer,
	                              RksInvoer    = @NieuweRksNummer where RksGid = @RksGid;

  set temporary option fire_triggers = 'off';
  update tabJournaalRegel   set JrRksInvoer  = @NieuweRksNummer where JrRksGid = @RksGid;
  set temporary option fire_triggers = 'on';

  update tabOpenstaandePost set OspRksInvoer = @NieuweRksNummer where OspRksGid = @RksGid;


end;

//call WijzigGrootboekrekeningNummer(1, '1020')

create or replace function WijzigRksNummer(
  in @RksNummerOud     nchar(28),
  in @RksNummerNieuw   nchar(28),
  in @DoInternalUpdate smallint default 0
)
returns integer //Aantal hernummerde rekeningen
  // Functie hernummert een grootboekrekening en alle onderliggende rekeningen met kostenplaats en -drager.
  // Het is NIET de bedoeling om zelf alleen een kostenplaats- of -dragerrekening te hernummeren! Dat gebeurt al vanzelf, omdat dat altijd een set vormt
  // Deze functie roept zichzelf aan met een @DoInternalUpdate=1 zodat het ook de kostenplaats- en -dragerreken ing kan omnummeren

begin
  declare @RksNummerNieuwPlain nchar(10);
  declare @AantalHernummerd    integer;

  if isnull(@DoInternalUpdate, 0) = 0 and (@RksNummerOud + @RksNummerNieuw) like '%.%' then
    call Raise(20677, _U('Een grootboekrekening met kostenplaats of -drager mag niet zelf worden hernummerd.')); //(20677) Ongeldige waarde: %1!
  end if;

  if isnull(@DoInternalUpdate, 0) <> 0 and (@RksNummerOud + @RksNummerNieuw) not like '%.%' then
    call Raise(20677, _U('Grootboekrekeningnummer moet een kostenplaats of -drager bevatten om intern om te nummeren.')); //(20677) Ongeldige waarde: %1!
  end if;

  if exists(select first 1 from tabrekeningschema where rksinvoer = @RksNummerNieuw) then
    call Raise(20677, _U('Grootboekrekeningnummer %1 komt al voor.',  @RksNummerNieuw)); //(20677) Ongeldige waarde: %1!
  end if;

  set @RksNummerNieuwPlain = left(@RksNummerNieuw, locate(@RksNummerNieuw + '.', '.') - 1);

  set @AantalHernummerd = 0;
  select count(*) into @AantalHernummerd from tabrekeningschema where rksinvoer = @RksNummerOud;
  if @AantalHernummerd <> 0 then
    // Update alle plekken waar deze rekening voorkomt
    set temporary option fire_triggers='off';
    begin try
    //call trace(space(@DoInternalUpdate * 2) + @RksNummerOud + '->' + @RksNummerNieuw);
      update tabNawFile                     set NawFilNummer              = @RksNummerNieuw where NawFilNummer              = @RksNummerOud;
      update tabBestelRegelDetail           set brdNawFilNummer           = @RksNummerNieuw where brdNawFilNummer           = @RksNummerOud;
      update tabMagazijnOntvangstenDetail   set MagOntDetNawFilNummer     = @RksNummerNieuw where MagOntDetNawFilNummer     = @RksNummerOud;
      update tabMagazijnOntvangstHistAdres  set MohaNawFilNummer          = @RksNummerNieuw where MohaNawFilNummer          = @RksNummerOud;
      update tmpNawImport                   set NiNawFilNummer            = @RksNummerNieuw where NiNawFilNummer            = @RksNummerOud;
      update tabRekeningSchema              set rksInvoer                 = @RksNummerNieuw,
                                                rksNummer                 = @RksNummerNieuwPlain where rksInvoer            = @RksNummerOud;
      update tabDagboek                     set DgbDefaultRksInvoer       = @RksNummerNieuw where DgbDefaultRksInvoer       = @RksNummerOud;
      update tabActivaMutatieHistorie       set ActmhRksInvoerVervr       = @RksNummerNieuw where ActmhRksInvoerVervr       = @RksNummerOud;
      update tabFactuurKop                  set fkBtcRksInvoer            = @RksNummerNieuw where fkBtcRksInvoer            = @RksNummerOud;
      update tabFactuurKop                  set fkDebNummer               = @RksNummerNieuw where fkDebNummer               = @RksNummerOud;
      update tabFactuurKop                  set fkFactDebNummer           = @RksNummerNieuw where fkFactDebNummer           = @RksNummerOud;
      update tabJournaalRegel               set JrRksInvoer               = @RksNummerNieuw where JrRksInvoer               = @RksNummerOud;
      update tabOpenstaandePost             set OspRksInvoer              = @RksNummerNieuw where OspRksInvoer              = @RksNummerOud;
      update tabProjectBoekingFactuur       set PbfRksInvoer              = @RksNummerNieuw where PbfRksInvoer              = @RksNummerOud;
      update tmpNawImport                   set NiTegenRksInvoer          = @RksNummerNieuw where NiTegenRksInvoer          = @RksNummerOud;
      update prnExploitatieOverzicht        set PrnExpRksInvoer           = @RksNummerNieuw where PrnExpRksInvoer           = @RksNummerOud;
      update tabAcceptGiro                  set AccDebNummer              = @RksNummerNieuw where AccDebNummer              = @RksNummerOud;
      update tabFactuurReferentie           set frefOrderDebNummer        = @RksNummerNieuw where frefOrderDebNummer        = @RksNummerOud;
      update tabFactuurReferentie           set frefOrderFactDebNummer    = @RksNummerNieuw where frefOrderFactDebNummer    = @RksNummerOud;
      update tabFactuurReferentie           set frefOrderOmzDebNummer     = @RksNummerNieuw where frefOrderOmzDebNummer     = @RksNummerOud;
      update tabFactuurReferentie           set frefOrderPrijzenDebNummer = @RksNummerNieuw where frefOrderPrijzenDebNummer = @RksNummerOud;
      update tabPOSHistorieKop              set PohkNawNummer             = @RksNummerNieuw where PohkNawNummer             = @RksNummerOud;

      set temporary option fire_triggers='on';
    end try
    begin catch
      set temporary option fire_triggers='on';
      resignal;
    end catch;

    if @DoInternalUpdate = 0 then
      begin
        // Eventuele kostenplaats- en kostendragerrekeningen ook allemaal omnummeren
        declare @tmpAantalHernummerd integer;

        select sum(WijzigRksNummer(RksInvoer, @RksNummerNieuwPlain + '.' + KstpCode + '.' + KstdCode, 1)) into @tmpAantalHernummerd
        from tabrekeningschema
        left outer join tabKostenPlaats on KstpGid = RksKstpGid
        left outer join tabKostenDrager on KstdGid = RksKstdGid
        where  rksNummer = @RksNummerOud // Plain dus!
          and (RksKstpGid is not null or RksKstdGid is not null);

        set @AantalHernummerd = @AantalHernummerd + isnull(@tmpAantalHernummerd, 0);
      end;
    end if;
  end if;

    return(@AantalHernummerd);
end;


create or replace procedure WordStuknummerAlGebruikt(in @BjGid integer, in @DgbGid integer, in @JpGid integer, in @BoekStuknummer numeric(10,0), inout @IsGebruikt smallint)
begin
  declare @DefBoekdatum smallint;

  set @@ErrorTextProcedure = 'WordStuknummerAlGebruikt > @BjGid='+string(@BjGid)+', @DgbGid='+string(@DgbGid)+', @JpGid='+string(@JpGid)+', @BoekStuknummer='+string(@BoekStuknummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select 1 from tabJournaalpost where JpBjGid=@BjGid and (@JpGid<>JpGid or @JpGid is null) and JpDgbGid=@DgbGid and BoekStuknummer=@BoekStuknummer) then
    set @IsGebruikt=1;
  else
    set @IsGebruikt=0;
  end if;

  set @@ErrorTextProcedure = 'WordStuknummerAlGebruikt > @IsGebruikt='+string(@IsGebruikt);
  //call TraceEind(@@ErrorTextProcedure);

end;


//-------  Schrijf naar tabLog
create or replace procedure WriteLog(
  in @LogSoort smallint,            //  0 = Inloggen
                                    //  1 = Uitloggen
                                    //  2 = Fout
                                    //  3 = Venster openen
                                    //  4 = Mutatie
                                    //  5 = Melding
                                    //  6 = Reparatie
                                    //  7 = update
                                    //  8 = import logbestand
                                    //  9 = reorganiseren
                                    // 10 = backup maken
                                    // 11 = backup terugzetten
                                    // 12 = toegang andere licentie
                                    // 13 = logbestand verkleinen
                                    // 14 = POS E-journal
                                    // 15 = systeem event
  in @LogOms nchar(250),
  in @PrimKey nchar(40) default '',
  in @Overschrijf smallint default 0 // 0 = altijd gewoon aanvullen
                                     // 1 = Overschrijf alleen als de laatste melding hetzelfde is
                                     // 2 = Overschrijf de vorige zelfde melding (update datum/tijd)
                                     // 3 = Negeer als de melding al eerder voorkomt (ongeacht datum/tijd)
)
begin
  declare @Gebruiker     nchar(40);
  declare @LogGid        integer;
  declare @DoActie smallint = 1; // 0 = overschrijven, 1 = toevoegen, 3 = negeren

  if @@GebruikerCode = 'KingSystem' then
    set @Gebruiker = ''
  else
    set @Gebruiker = @@GebruikerCode
  end if;
  //De tekst 'administratie ge-update naar King ....' maar 1 keer opnemen in logboek
  if @LogSoort = 7 then
    set @Overschrijf = 3 /*Negeer als al voorkomt*/
  end if;

  if @Overschrijf in (1, 2, 3) then
    select max(LogGid) into @LogGid from tabLog where LogOmschrijving = @LogOms and LogSoort = @LogSoort OPTION (Isolation_level=0);
  end if;

  if @LogGid is null then
    set @DoActie = 1 /*Toevoegen*/ //want bestaat niet (of is niet relevant)
  else
    case @Overschrijf
      when 0 /*ALtijd aanvullen*/ then
        set @DoActie = 1 /*Toevoegen*/;
      when 1 /*Overschrijf alleen als het de laatste is, anders alsnog toevoegen*/ then
        if not exists(select first 1 from tabLog having max(LogGid) = @LogGid) then
          set @DoActie = 1 /*Toevoegen*/; // Het is niet de laatste, dus alsnog toevoegen
        else
          set @DoActie = 0 /*Overschrijven*/;
        end if;
      when 2 /*Overschrijf vorige melding*/ then
        set @DoActie = 0 /*Overschrijven*/;
      when 3 /*Negeer als melding al voorkomt*/ then
        set @DoActie = 3 /*Negeren*/;
    end case;
  end if;


  case @DoActie
    when 0 /*Overschrijven*/ then
      update tablog set logtimestamp = now() where LogGid = @LogGid OPTION (Isolation_level=0); // Update de datum/tijd
      if @@LogDetail <> ''  then
        insert into tabLogDetail(LogDetLogGid, LogDetExtraInfo) select @LogGid, @@LogDetail;
        set @@LogDetail = '';
      end if;
    when 1 /*Toevoegen*/ then
      insert into tabLog(LogSoort, LogAdmCode, LogBjCode, LogUserName, LogMachineName, LogOmschrijving, LogPrimaryKey)
      select @LogSoort, Db_Name(), (select Code from tabBoekjaar where BjGid = @@BjGid), @Gebruiker, @@MachineName, @LogOms, @PrimKey OPTION (Isolation_level=0);
      set @LogGid = @@Identity;
      if @@LogDetail <> ''  then
        insert into tabLogDetail(LogDetLogGid, LogDetExtraInfo) select @LogGid, @@LogDetail;
        set @@LogDetail = '';
      end if;
    //when 3 /*Negeren*/ then
  end case;

end;


create or replace procedure ZetBedragInIct( in @nawgid integer, in @OpbrGrpIsGoed smallint, in @Boekdatum date, in @BasisBedrag numeric(15,2), in @IctIsAbcLevering smallint, in @IctBTWCode integer )
begin
  set @@ErrorTextProcedure = 'ZetBedragInIct > @NawGid = '+string(@NawGid)+', @OpbrGrpIsGoed='+string(@OpbrGrpIsGoed)+', @Boekdatum='+string(@Boekdatum)+', @BasisBedrag='+string(@BasisBedrag)+', @BTWCode='+string(@IctBtwCode);
  //call TraceBegin(@@ErrorTextProcedure);

  if (select IsModuleActive('b1')) <> 0 then //Alleen met module qcMod_Icl
    if exists(select 1 from tabICT where IctNawGid = @nawgid and IctIsLevering=1 and IctJaar=Year(@Boekdatum) and IctMaand=Month(@Boekdatum) and IctIsAbcLevering=@IctIsAbcLevering and IctBTWCode=@IctBTWCode) then
      //Bedrag optellen bij de bestaande
      update tabICT
      set    IctBedragGoed   = IctBedragGoed   + if @OpbrGrpIsGoed = 1 then @BasisBedrag else 0 endif,
             IctBedragDienst = IctBedragDienst + if @OpbrGrpIsGoed = 1 then 0 else @BasisBedrag endif
      where  IctNawGid = @nawgid and IctIsLevering=1 and IctJaar=Year(@Boekdatum) and IctMaand=Month(@Boekdatum) and IctIsAbcLevering=@IctIsAbcLevering and IctBTWCode=@IctBTWCode;
    else
      //Bedrag toevoegen
      insert into tabICT(IctNawGid, IctIsLevering, IctJaar, IctMaand, IctBedragGoed, IctBedragDienst, IctIsAbcLevering, IctBtwCode )
      values( @nawgid, 1, Year(@Boekdatum), Month(@Boekdatum), (if @OpbrGrpIsGoed = 1 then @BasisBedrag else 0 endif), (if @OpbrGrpIsGoed = 1 then 0 else @BasisBedrag endif), @IctIsAbcLevering,@IctBtwCode );
    end if;
  end if;

  set @@ErrorTextProcedure = 'ZetBedragInIct';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure ZetDefaultArtikelLocatie(in @ArtCode nchar(20), in @MagCode integer, in @LocNaam nchar(20))
begin
  declare @MagGid    integer;
  declare @ArtGid    integer;
  declare @LocGid    integer;
  declare @ArtMagGid integer;

  set @@ErrorTextProcedure = 'ZetDefaultArtikelLocatie > @ArtCode = '+@ArtCode+', @MagCode = '+string(@MagCode)+', @LocNaam = '+@LocNaam;
  //call TraceBegin(@@ErrorTextProcedure);

  select MagGid into @MagGid from tabMagazijn where MagCode = @MagCode;
  select ArtGid into @ArtGid from tabArtikel  where ArtCode = @ArtCode and ArtSoort = 2;
  select LocGid into @LocGid from tabLocatie  where LocNaam = @LocNaam and LocMagGid = @MagGid;

  set @ArtMagGid = null;
  select ArtMagGid into @ArtMagGid from tabArtikelMagazijn where ArtMagMagGid = @MagGid and ArtMagArtGid = @ArtGid;
  if @ArtMagGid is null then
    insert into tabArtikelMagazijn(ArtMagMagGid, ArtMagArtGid, ArtMagDefaultLocGid) values (@MagGid, @ArtGid, @LocGid);
  else
    update tabArtikelMagazijn set ArtMagDefaultLocGid = @LocGid where ArtMagGid = @ArtMagGid;
  end if;

  set @@ErrorTextProcedure = 'ZetDefaultArtikelLocatie';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure ZoekExternFactuurnummer(
  in @RksGid integer,
  in @Factuurnummer nchar(40),
  in @Omschrijving nchar(140),
  out @ExternFactuurnummer nchar(40),
  out @RestOmschrijving nchar(40))
begin
  declare @_ScheidingTekens nchar(40);
  declare @_Positie integer;
  declare @_Teller integer;
  declare @_BegPos integer;
  declare @_Crediteurnummer nchar(28);
  declare @_OnsDebnummer nchar(28);

  //call TraceBegin('ZoekFactuurnummer');

  set @_ScheidingTekens = ' /.,-*:'+char(13)+char(10);
  select RksInvoer into @_Crediteurnummer from tabRekeningschema where RksGid = @RksGid;
  select NawOnsDebiteurnummer into @_OnsDebnummer from tabNawfile inner join tabNaw on (NawGid = NawFilNawGid) where NawFilRksGid = @RksGid;

  set @_Positie = Length(@Omschrijving);

  while @_Positie >= 1 loop
    if locate(@_ScheidingTekens, substr(@Omschrijving, @_Positie, 1))=0 then
      //call Trace('iets anders dan scheidingsteken gevonden ---> pak stuk tot volgende scheidingsteken');
      set @ExternFactuurnummer = '';
      set @_BegPos = 0;
      set @_Teller = @_Positie;

      while @_Teller >= 1 loop
        if locate(@_ScheidingTekens, substr(@Omschrijving, @_Teller, 1)) <> 0 then
          set @_BegPos = @_Teller;
          set @_Teller = 1;
        end if;
        set @_Teller = @_Teller - 1;
      end loop;

      select LtrimChar(substr(@Omschrijving, @_BegPos + 1, @_Positie - @_BegPos), '0') into @ExternFactuurnummer;

      if (@ExternFactuurnummer <> @_Crediteurnummer) and (@ExternFactuurnummer <> @_OnsDebnummer) then
        if (@ExternFactuurnummer <> @FactuurNummer) then
          if (Length(@ExternFactuurnummer) > 0) and (Length(@ExternFactuurnummer) < 41) then
            set @_Positie = 0;
          else
            set @_Positie = @_BegPos;
          end if;
        else
          //call Trace('Ons factuurnummer gevonden');
          set @_Positie = 0;
        end if;
      else
        //call Trace('Crediteurnummer/OnsDebiteurnummer gevonden');
        set @_Positie = @_BegPos;
      end if;
    end if;
      set @_Positie = @_Positie - 1;
  end loop;

  set @RestOmschrijving = left(@Omschrijving, @_BegPos-1);

  //call TraceEind('ZoekFactuurnummer');
end;


create or replace procedure ZoekOfMaakRksMetKstpKstd(in @RksGid integer, in @KstpGid integer, in @KstdGid Integer, out @RksGIDmetKstpKstd integer)
begin
  // Zoek van een gegeven grootboekrekening de juiste rekening met kstp/kstd op.
  // Indien niet gevonden, maak die rekening dan aan met dezelfde gegevens als de hoofdrekening.
  declare @RksNaamKpKd   nchar(40);
  declare @RksNaam       nchar(40);

  declare @RksNummer     nchar(10);
  declare @RksInvoerKpKd nchar(28);

  declare @RksKstpGid    integer;
  declare @RksKstdGid    integer;
  declare @KstpCode      nchar(8);
  declare @KstdCode      nchar(8);
  declare @KstpZoekcode  nchar(40);
  declare @KstdZoekcode  nchar(40);

  set @@ErrorTextProcedure = 'ZoekOfMaakRksMetKstpKstd > ';
  //call TraceBegin(@@ErrorTextProcedure + '@RksGid = ' + string(@RksGid) + ', @KstpGid = ' + string(@KstpGid) + ', @KstdGid = ' + string(@KstdGid));

  //Hoofdrekening opzoeken
  select RksNummer, RksNaam, RksKstpGid, RksKstdGid into @RksNummer, @RksNaam, @RksKstpGid, @RksKstdGid from tabRekeningschema where RksGid = @RksGid;

  if @RksKstpGid is not null or @RksKstdGid is not null then
    // Oeps! De rekening had al een kstp en/of kstd, dus gelijk eruit!
    set @RksGIDmetKstpKstd = @RksGid;
  else

    // Bestaat de rekening met kstp/kstd?
    set @RksGIDmetKstpKstd = null;
    select RksGid into @RksGIDmetKstpKstd
    from   tabRekeningschema
    where  RksNummer = @RksNummer
       and (RksKstpGid = @KstpGid or (@KstpGid is null and RksKstpGid is null))
       and (rksKstdgid = @KstdGid or (@KstdGid is null and RksKstdGid is null));
    if @RksGIDmetKstpKstd is null then
      // Oeps! Bestaat niet, dus alsnog aanmaken
      select KstpCode, KstpZoekcode into @KstpCode, @KstpZoekcode from tabKostenPlaats where KstpGid = @KstpGid;
      select KstdCode, KstdZoekcode into @KstdCode, @KstdZoekcode from tabKostenDrager where KstdGid = @KstdGid;
      set @RksNaamKpKd = @RksNaam+IsNull('/'+@KstpZoekcode,'')+IsNull('/'+@KstdZoekcode,'');
      set @RksInvoerKpKd = @RksNummer + IsNull('.' + string(@KstpCode),'') + IsNull('.' + string(@KstdCode),'');

      insert into tabRekeningschema(RksNummer,  RksInvoer,     RksZoekCode,  RksNaam,     DefaultSoort, RksValNummer, AfdrukZijde, RksBtwCode, ReferentieVerplicht, GebruikAantallen, RksKstpGid, RksKstdGid)
                            select @RksNummer, @RksInvoerKpKd, RksZoekCode, @RksNaamKpKd, DefaultSoort, RksValNummer, AfdrukZijde, RksBtwCode, ReferentieVerplicht, GebruikAantallen, @KstpGid,   @KstdGid from tabRekeningschema where RksGid = @RksGid;

      set @RksGIDmetKstpKstd = @@Identity;

      // Voeg balanscodes toe
      // #38043 : Wens : Variabele balanscode overnemen van hoofdrekening tijdens facturering
      insert into tabBalansCodeRekening(BlRksGid, BlRekBlGid, BlRekBlCode)
        select @RksGIDmetKstpKstd, BlRekBlGid, BlRekBlCode
       from tabBalansCodeRekening
       where BlRksGid = @RksGid;

    end if;
  end if;

  set @@ErrorTextProcedure = 'ZoekOfMaakRksMetKstpKstd';
  //call traceEind(@@ErrorTextProcedure + ' > @RksGIDmetKstpKstd = ' + string(@RksGIDmetKstpKstd));
end;


create or replace procedure ZoekOudsteAutomBoekBetalingsOpdrachtVanFactuur(in @DgbGid integer, in @RksGid integer, in @FactuurNummer nchar(40), in @Bedrag numeric(15,2), out @BetRglGid  integer, out @BetVerzGid integer)
begin


  set @@ErrorTextProcedure = 'ZoekOudsteAutomBoekBetalingsOpdrachtVanFactuur(@DgbGid='+string(@DgbGid)+', @RksGid='+string(@RksGid)+', @FactuurNummer='+@FactuurNummer+', @Bedrag='+string(@Bedrag)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @BetRglGid  = null;
  set @BetVerzGid = null;
  select    first
            BetRglGid, BetVerzGid
  into      @BetRglGid, @BetVerzGid
  from      tabBetalingKop
            inner join (tabBetalingregel
                        left outer join tabBetalingVerzameld on (BetRglIsVerzameld = 1 and BetVerzBetRglGid = BetRglGid and BetVerzIsAfgeboekt = 0)
                       ) on BetKopId = BetRglBetKopId
  where     BetRglRksGid = @RksGid
       and (   (BetRglFactuurNummer = @FactuurNummer  and length(@FactuurNummer) = BetRglFactuurNummer_Lengte)
            or (BetVerzFactuurNummer = @FactuurNummer and length(@FactuurNummer) = BetVerzFactuurnummer_Lengte))
       and (   (@Bedrag is null)
            or (BetRglTeBetalenInValOsp  + BetRglVerschilAfboeken  * BetRglVerschilAfboekenBedragInValOsp  = @Bedrag)
            or (BetVerzTeBetalenInValOsp + BetVerzVerschilAfboeken * BetVerzVerschilAfboekenBedragInValOsp = @Bedrag))
       and (BetRglStatus = 1 /*Opdracht*/)
       and (BetKopDgbGid = isnull(@DgbGid, BetKopDgbGid))
  order by isnull(BetVerzBetaalDatum, BetRglBetaalDatum) asc;

  set @@ErrorTextProcedure = 'ZoekOudsteAutomBoekBetalingsOpdrachtVanFactuur(@DgbGid='+string(@DgbGid)+', @RksGid='+string(@RksGid)+', @FactuurNummer='+@FactuurNummer+', @BetRglGid='+string(@BetRglGid)+', @BetVerzGid='+string(@BetVerzGid)+')';
  //call TraceEind (@@ErrorTextProcedure);
end;


create or replace procedure ZoekOudsteIncassoOpdrachtVanFactuur(in @DgbGid integer, in @RksGid integer, in @FactuurNummer nchar(40), in @Bedrag numeric(15,2), out @IncRglGid  integer, out @IrvGid integer)
begin
  set @@ErrorTextProcedure = 'ZoekOudsteIncassoOpdrachtVanFactuur(@DgbGid='+string(@DgbGid)+', @RksGid='+string(@RksGid)+', @FactuurNummer='+@FactuurNummer+', @Bedrag='+string(@Bedrag)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @IncRglGid = null;
  set @IrvGid    = null;

  select    first
            IncRglGid, IrvGid
  into      @IncRglGid, @IrvGid
  from      tabIncassoKop
            inner join (tabIncassoRegel
              left outer join tabIncassoRegelVerzameld on (IncRglIsVerzameld = 1 and IrvIncRglGid = IncRglGid and IrvIsAfgeboekt = 0)
                       ) on IncKopId = IncRglIncKopId

  where    (IncRglRksGid = @RksGid)
       and (
            (IncRglFactuurNummer = @FactuurNummer and length(@FactuurNummer) = IncRglFactuurNummer_Lengte)
        or  (IrvFactuurNummer = @FactuurNummer and length(@FactuurNummer) = IrvFactuurNummer_Lengte)
        )
       and (    (@Bedrag is null)
             or (IncRglTeIncasseren  = @Bedrag )
             or (IrvTeIncasseren = @Bedrag)
       )
       and (IncRglStatus = 1 /*Opdracht aangemaakt*/)
       and (IsNull(IncKopDgbGID, @DgbGid, -1) = isnull(@DgbGid, IncKopDgbGID, -1)) /* Alleen indien zelfde dagboek OF geen dagboek ingevuld */
  order by  IncRglDatum asc;

  set @@ErrorTextProcedure = 'ZoekOudsteIncassoOpdrachtVanFactuur(@RksGid='+string(@RksGid)+', @FactuurNummer='+@FactuurNummer+', @IncRglGid='+string(@IncRglGid)+')';
  //call TraceEind (@@ErrorTextProcedure);
end;


create or replace procedure ZoekPrijsafspraakViaProjectboom(
in  @PbGid                 integer,
in  @ArtGid                integer,
in  @PmwRelGid             integer,
out @ProjectVerkoopprijs   numeric(15,3), //De bepaalde verkoopprijs
out @ProjectPbGid          integer,      //indien niet null, dan prijsafspraak gevonden. Indien ongelijk aan
                                          //@PBGid dan alleen afspraak gevonden op hoger gelegen onderdeel
out @ProjectArtGid         integer,
out @ProjectRelGid         integer)

begin
  //als het gidje anders is dan @PbGid is, dan is het een prijsafspraak op een hoger niveau.
  // [-] Project               pbgid: 10000 | situatie 1             | situatie 2
  //  |-[-] Level 1            pbgid: 10001 | prijsafspraak: 10 euro | prijsafspraak: 15 euro
  //     |---- Level 1.1       pbgid: 10017 |                        |
  //     |---- Level 1.2       pbgid: 10018 |                        |
  //     |-[-] Level 1.3       pbgid: 10029 |                        |
  //        |---- Level 1.3.1  pbgid: 10045 |                        | prijsafspraak: 18 euro
  //
  // situatie 1: @ProjectVerkoopprijs = 10, @ProjectPbGid = 10001 (geen prijsafspraak op projectonderdeel, wel op hoger gelegen projectonderdeel)
  // situatie 2: @ProjectVerkoopprijs = 18, @ProjectPbGid = 10045 (prijsafspraak op projectonderdeel zelf)

  set @@ErrorTextProcedure = 'ZoekPrijsafspraakViaProjectboom(@PbGid='+string(@PbGid)+'@ArtGid='+string(@ArtGid)+'@PmwRelGid='+string(@PmwRelGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @ProjectVerkoopprijs = Null;
  set @ProjectPbGid = Null;
  set @ProjectArtGid = Null;
  set @ProjectRelGid = Null;

  select   first ppaPbGid, ppaVerkoopprijsExBtw,ppaArtGid,ppaRelGid into @ProjectPbGid, @ProjectVerkoopprijs, @ProjectArtGid, @ProjectRelGid
  from     tabProjectBoom
           inner join tabProjectPrijsafspraak on (    ppaPbGid = PbGid
                                                  and (ppaArtGid = @ArtGid or (@ArtGid is null and ppaArtGid is null))
                                                  and (ppaRelGid = @PmwRelGid or (@PmwRelGid is null and ppaRelGid is null)))
  where    PbGid in (select PbpParentPbGid from tabProjectBoomPad where PbpPbGid = @PbGid union select @PbGid)
  order by PbLevel desc;

  set @@ErrorTextProcedure = 'ZoekPrijsafspraakViaProjectboom(@ProjectVerkoopprijs='+string(@ProjectVerkoopprijs)+'@ProjectPbGid='+string(@ProjectPbGid)+'@ProjectArtGid='+string(@ProjectArtGid)+'@ProjectRelGid='+string(@ProjectRelGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


