create or replace function _ProjectHeeftMedewerkerTariefPermissie (in @RelGid int, in @ArtGid int)
// ---------------------------------------------------------------------------------------------------------------------------
// --------- Bepaling of combinatie van projectonderdeel, tarief, machine, medewerker toestemming voor gebruik heeft ---------
// ---------------------------------------------------------------------------------------------------------------------------
// NOOT Niet rechtstreeks gebruiken vanuit KING, gebruik stored function: ProjectHeeftPermissie
  // do 633  p1 Bepalen gebruikstoestemming:
  // ---------------------------------------
  // 2. Medewerker
  // 3. Activiteit
  // 4. Machine
  // 8. Medwerker en Activiteit
returns smallint
begin
  declare @result smallint;

  set @@ErrorTextProcedure = '_ProjectHeeftMedewerkerTariefPermissie > ';
  //call TraceBegin(@@ErrorTextProcedure + '@RelGid = ' + string(@RelGid) + ', @ArtGid=' + string (@ArtGid));

  select first tabProjectPermissie.ppmPermissie into @result
  from tabProjectPermissie
  where
    isnull(ppmArtGid, @ArtGid + 1, 0) = isnull(@ArtGid, ppmArtGid - 1, 0) and
    isnull(ppmRelGid, @RelGid + 1, 0) = isnull(@RelGid, ppmRelGid - 1, 0) and
    (ppmPbGid is null);

  set @@ErrorTextProcedure = '_ProjectHeeftMedewerkerTariefPermissie';
  //call TraceEind(@@ErrorTextProcedure + ' > @Result = ' + string(IsNull(@Result,0)));
  return @result;
end;


create or replace function _ProjectHeeftOnderdeelPermissie (in @ProjectBoomGid int, in @RelGid int, in @ArtGid int)
// NOOT Niet rechtstreeks gebruiken vanuit KING, gebruik ProjectHeeftPermissie
  // do 633  p1 Bepalen gebruikstoestemming:
  // ---------------------------------------
  // 1. ProjectOnderdeel
  // 5. Projectonderdeel en medewerker
  // 6. Projectonderdeel en activiteit
  // 7. Projectonderdeel en machine
  // 9. Projectonderdeel, medewerker en activiteit
returns smallint
begin
  declare @result       smallint;
  declare @resultRelArt smallint;
  declare @ppmLevel     integer;

  set @@ErrorTextProcedure = '_ProjectHeeftOnderdeelPermissie > ';
  //call TraceBegin(@@ErrorTextProcedure + ' @ProjectBoomGid = ' + string(@ProjectBoomGid) + ', @RelGid = ' + string(@RelGid) + ', @ArtGid = ' + string(@ArtGid));

  select first ppmpermissie ,ppmLevel
    into       @result      ,@ppmLevel
  from (
    //Parent niveau
    select  ppmPermissie,
            (     if (ppmRelGid is not null and ppmArtgid is not null)  then 9
             else if (ppmRelGid is null     and ppmArtgid is not null)  then 6
             else if (ppmRelGid is not null and ppmArtgid is null)      then 5
             else if (ppmRelGid is null     and ppmArtgid is null)      then 1
             endif endif endif endif) as ppmLevel,
            pblevel
    from tabProjectBoomPad
    inner join tabProjectBoom      on pbGid = pbpParentPbGid and (pbLevel > 0)
    inner join tabProjectPermissie on ppmPBGid = PbGid
    where   pbpPbGid = @ProjectBoomGid
      and   (ppmRelGid = @RelGid or ppmRelGid is null)
      and   (ppmArtgid = @ArtGid or ppmArtGid is null)
  union
    //Eigen nveau
    select  ppmPermissie,
            (     if (ppmRelGid is not null and ppmArtgid is not null)  then 9
             else if (ppmRelGid is null     and ppmArtgid is not null)  then 6
             else if (ppmRelGid is not null and ppmArtgid is null)      then 5
             else if (ppmRelGid is null     and ppmArtgid is null)      then 1
             endif endif endif endif) as ppmLevel,
            pblevel
    from tabProjectPermissie
    inner join tabProjectBoom on PbGid = ppmPBGid and (pbLevel > 0)
    where   ppmPBGid = @ProjectBoomGid
      and   (ppmRelGid = @RelGid or ppmRelGid is null)
      and   (ppmArtgid = @ArtGid or ppmArtGid is null)
  /*
  union
  //children niveau is niet nodig!!!
    select  ppmpermissie= (tabProjectPermissie.ppmPermissie),
            ppmLevel    = (     if (ppmRelGid is not null and ppmArtgid is not null)  then 9
                           else if (ppmRelGid is null     and ppmArtgid is not null)  then 6
                           else if (ppmRelGid is not null and ppmArtgid is null)      then 5
                           else if (ppmRelGid is null     and ppmArtgid is null)      then 1
                           endif endif endif endif),
            pblevel     = (select pbLevel from tabProjectBoom where pbgid = pbpPbGid)
    from tabProjectBoomPad
    inner join tabProjectPermissie on ppmPBGid = pbpPbGid
    where   ppmPBGid = @ProjectBoomGid
      and   (ppmRelGid = @RelGid or ppmRelGid is null)
      and   (ppmArtgid = @ArtGid or ppmArtGid is null)
  */
  ) as tabelPermissie
  order by pbLevel desc ,ppmLevel desc;

  if (@result is not null and @ppmLevel=9) then
    //Dit is 9. Dus je hoeft niets meer te doen.
  else
    if (@RelGid is not null and @ArtGid is not null) then
      //8. testen
      set @resultRelArt = _ProjectHeeftMedewerkerTariefPermissie (@RelGid, @ArtGid);
    else
      set @resultRelArt = null;
    end if;

    if (@resultRelArt is not null)
    then
      set @result = @resultRelArt;
    else
      //Niet 8. Maar het kan zijn dat 5,6 of 7 gevonden zijn
      if (@result is not null) and (@ppmLevel >= 5) then
        //5,6, of 7 recht gevonden
      else
        if (@ArtGid is not null) then //3 of 4 testen
          set @result = _ProjectHeeftMedewerkerTariefPermissie (null, @ArtGid);
        else
          if (@RelGid is not null) then //2 testen
            set @result = _ProjectHeeftMedewerkerTariefPermissie (@RelGid, null);
          else
            if (@result is not null) and (@ppmLevel = 1) then
              //1. ProjectOnderdeel
            else
              //Dit betekent dus geen recht op 2,3, of 4 of je db is corrupt.
              set @result = 0;
            end if;
          end if;
        end if;
      end if;
    end if
  end if;

  set @@ErrorTextProcedure = '_ProjectHeeftOnderdeelPermissie';
  //call TraceEind(@@ErrorTextProcedure + ' > @Result = ' + string(IsNull(@Result,0)));
  return (isnull(@result,0));
end;

create or replace procedure AdminOnderhoud_Banktransacties_RepairFatalErrors(in @Info smallint default 0, out @Description nchar(200) default '')
begin
  if @Info = 1 then
    set @Description = _U('Banktransacties: Herstel locks');
  else
    // Just to be sure we haev no left-overs
    call Banktransacties_RepairFatalErrors();
  end if;
end;


// Bij inlog, nog voordat locks worden vrijgegeven etc. een db-haakje inbouwen
// Indien nodig, kan dat db-haakje worden gebruikt voor opruimen banktransactielocks (de adminonderhoud)
// Dan via adminonderhoud mogelijkheid om view allemaal op te ruimen.
create or replace procedure AdminOnderhoud_Banktransactie_CleanMatViews(
  in @Info smallint default 0,
  out @Description nchar(200) default ''
)
begin
  declare @_BoekgangGid integer;
  if @Info = 1 then
    set @Description = _U('Banktransacties: materialized views opschonen (let op: kan lang duren)');
  else
    begin
      declare @qlockgid   integer;
      declare @pmvgid     integer;
      declare @table_name nchar(250);
      declare @MatViewNr  numeric(10,0);
      declare @LastmatViewNr numeric(10,0) = -1;

      call AdminOnderhoud_Banktransacties_RepairFatalErrors();

      loop
        set @matViewNr = null;
        select first
          table_name,
          cast(regexp_substr(table_name, '[0-9]+$') as numeric(10,0)) MatViewNr,
          pmvgid,
          qlockgid
        into @table_name, @MatViewNr, @pmvgid, @qlockgid
        from systable inner join sysusers on uid = creator
        left outer join tabPooledMaterializedView on pmvUniekNummer = MatViewNr and pmvSoortView = 4 /*vwMeestRecenteOpenstaandePosten*/
        left outer join qtablock on qlocktablename='tabPooledMaterializedView' and qlockpkey = 'pmvgid='||pmvgid
        where table_type = 'mat view'
          and name = 'KingSystem'
          and table_name like 'vwMeestRecenteOpenstaandePosten%'
          and isnull(pmvingebruik,0)=0
          and qlockgid is null // Alleen indien niet meer in gebruik
          and MatViewNr > @LastmatViewNr
        order by MatViewNr; // order by tablename does not work, because that is a string-order

        if @matViewNr is null then
          leave;
        end if;

        call trace('@LastmatViewNr='||@LastmatViewNr||', @matViewNr='||@matViewNr);
        execute immediate 'drop materialized view if exists kingsystem.'||@table_name;
        delete tabPooledMaterializedView where PmvGid = @PmvGid;
        delete qtablock where qlockgid = @qlockgid;
        commit;

        set @LastmatViewNr = @matViewNr;
      end loop;
    end;
  end if;
end;


create or replace procedure AdminOnderhoud_BoekingsgangRecreateLocks(
  in @Info smallint default 0,
  out @Description nchar(200) default ''
)
//Ontime defect 59924: nieuw tbv boekingsgangen die in gebruik blijven
begin
  declare @_BoekgangGid integer;
  if @Info = 1 then
    set @Description = _U('Boekingsgangen zonder lock maar wel in gebruik herstellen (Melding bij inlog)');
  else
    begin
      declare @LockToegevoegd integer = 0;

      // Voor elke journaalpost die in gebruik is de boekingsgang in gebruik nemen, als er geen lock op staat
      set @Description = '';
      set temporary option fire_triggers = 'off';
      update tabboekingsgang
      set BoekGangInGebruik = 1
      from tabboekingsgang
           inner join tabJournaalpost on JpBoekgangGid = BoekgangGid
      where JpIsInGebruik = 1
           and BoekGangInGebruik = 0
           and not exists(select first 1 from qtablock where qlocktablename = 'tabBoekingsgang' and substr(qLockPKey, locate(qLockPKey, '=')+1) = BoekgangGid);
      if @@rowcount > 0 then
        set @Description = @@rowcount || 'boekingsgang' || if @@rowcount > 1 then 'en' endif || ' in gebruik genomen. ';
      end if;

      set temporary option fire_triggers = 'on';

      // Voor elke boekingsgang waar geen lock voor is alsnog de lock zetten
      for @CursorBoekgangLocks AS CURSOR_BoekgangLocks CURSOR FOR
        select BoekgangGid @BoekgangGid
        from tabboekingsgang
        where BoekGangInGebruik = 1
           and not exists(select first 1
                          from qtablock
                          where qlocktablename = 'tabBoekingsgang'
                            and substr(qLockPKey, locate(qLockPKey, '=')+1) = BoekgangGid
                            and qLockDateTime < dateadd(minute, -10, now())
                         )
      for update do
        // Add lock
        call LockSetOnId(0 /*@@SpId, make sure the connection is gone*/, @@LoginTime, 1, 'tabBoekingsgang','BoekGangGid='+string(@BoekgangGid), 0, 1, @LockUser = 'AdminOnderhoud-correcties');
        set @LockToegevoegd = @LockToegevoegd + 1;
      end for;
      if @LockToegevoegd > 0 then
        set @Description = @Description || @LockToegevoegd || ' lock' || if @LockToegevoegd > 1 then 's' endif || ' toegevoegd.';
      end if;
    exception
    when others then
      rollback;
      set temporary option fire_triggers = 'on';
      resignal; // Fout doorgeven naar boven
    end;
  end if;
end;


create or replace procedure AdminOnderhoud_ClearWebserviceBoekingsgang(in @Info smallint default 0, out @Description nchar(200) default '')
begin
  declare @_BoekgangGid integer;
  if @Info = 1 then
    set @Description = _U('Opschonen van lege door webservices aangemaakte boekingsgangen');
  else

    // ***********************************************
    // *** Stap 1: verwijderen van lege boekingsgangen
    // ***********************************************

    // Per lock doorlopen:
    // - Lock wordt niet automatisch verwijderd (dus van webservice)
    // - is van boekingsgangen
    // - Boekingsgang bestaat niet of heeft geen journaalREGELS
    // - lock is langer dan een uur eerder aangemaakt
    //
    begin
      set temporary option fire_triggers = 'off';
      for @CursorBoekgangLocks AS CURSOR_BoekgangLocks CURSOR FOR
        select substr(qLockPKey, locate(qLockPKey, '=')+1) @PKey
        from qtablock
        where qlocktablename = 'tabBoekingsgang'
          and qlockAutomatischOpruimen = 0 /*niet autom.opruimen*/
          and qLockDateTime < dateadd(hour, -2, now()) // Langer dan 2 uur geleden
          and isnumeric(@PKey)=1
          and @PKey <> ''
      for update do
        set @_BoekgangGid = @PKey;

        // Controleer of de boekingsgang journaalREGELS heeft, zo niet, dan boekingsgang+lock verwijderen
        if not exists(select first 1 from tabJournaalpost inner join tabJournaalregel on JrJpGid = JpGid where JpBoekgangGid = @_BoekgangGid) then
          // Boekingsgang sluiten
          delete tabjournaalpost where JpBoekgangGid = @_BoekgangGid;
          delete tabBoekingsgang where BoekgangGid = @_BoekgangGid;
          delete qtablock where current of CURSOR_BoekgangLocks;
        end if;

      end for;
    exception
    when others then
      rollback;
      set temporary option fire_triggers = 'on';
      resignal; // Fout doorgeven naar boven
    end;

    // **********************************************
    // *** Stap 2: Aanpassen locks naar TeVerwijderen
    // **********************************************

    // Als geldt dat:
    // - lock is van boekingsgangen
    // - lock wordt niet autom. opgeschoond
    // - lock staat langer dan 10 uur open
    // Pas dan de lock aan dat die automatisch wordt opgeschoond (merkbaar eerstvolgende keer dat iemand inlogt)
    // Specifiek zo gedaan, omdat hier de boekingsgang wel regels heeft en dus netjes opgeruimd moet worden
    update qtablock
    set    qlockAutomatischOpruimen = 1
    where qlocktablename = 'tabBoekingsgang'                     // Lock is van boekingsgangen
      and qlockAutomatischOpruimen = 0 /*niet autom.opruimen*/   // wordt niet autom. opgeruimd
      and qLockDateTime < dateadd(hour, -10, now());             // ouder dan 10 uur
  end if;
end;


