create or replace procedure EnumerateAdminonderhoud()
result (
  Id nchar(80),
  Naam nchar(100)
)
begin
  declare @naam nchar(100);
  declare local temporary table tmpErs(
    ersId nchar(80),
    ersNaam nchar(100)
  ) on commit preserve rows;

  // Vullen tabel met gevonden procedures
  insert into tmpErs(ersId)
  select proc_name from sys.sysprocedure where proc_name like 'AdminOnderhoud[_]%';

  // Gebruiksvriendelijke naam ophalen
  for @Cursor AS CURSOR_Enumerating CURSOR for
    select ersId @ersId,
          if Params.proc_id is null then 0 else 1 endif @HeeftInfo
    from   tmpErs
           inner join sys.sysprocedure Procs on proc_name = ersId
           left outer join  SYS.SYSPROCPARM Params on Params.proc_id = Procs.proc_id and parm_name = '@info'

    FOR UPDATE
  do
    set @naam = null;
    if @HeeftInfo = 1 then
      execute immediate 'call ' || @ersId || '(1, @Naam)';
    else
      if @Naam is null then
        set @naam = substring(@ersId, length('AdminOnderhoud_') + 1);
        if isnumeric(substring(@naam, 1, 8)) = 1 then
          set @naam = substring(@naam, 10);
        end if;
      end if;
    end if;
    if isnull(@naam, '') <> '' then
      update tmpErs set ersNaam = @naam where current of CURSOR_Enumerating;
    end if;
  end for;

  // Als er nu dubbele namen in staan, dan die uniek maken door te nummeren
  update tmpErs tmpErsBuiten
  set ersNaam = NieuweNaam
  from
   (
    select tmpErsBinnen.ErsId,
           case
             //when ErsId like 'MAATWERK[_]%' then 1     // Liefst de licentiehoudende met MAATWERK_ teruggeven
             //when ErsId like 'JOBSCRIPT[_]%' then 2  // De niet-licentiehoudende met JOBSCRIPT_ als tweede teruggeven
             when ErsId like 'AdminOnderhoud[_][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][_]%' then 3  // De niet-licentiehoudende administratieonderhoud
             when ErsId like 'AdminOnderhoud[_]%' then 4  // De niet-licentiehoudende administratieonderhoud
             else 5                                    // Als de gebruiksvriendelijke naam overeenkomt, dan die toch als laatste
           end Volgorde,
           ROW_NUMBER(*) over ZelfdeNamen Nummer,
           if Nummer > 1 then ersNaam || ' (' || Nummer - 1 || ')'  else ersNaam endif NieuweNaam
    from tmpErs tmpErsBinnen
    where ErsNaam is not null
    window ZelfdeNamen as (PARTITION BY ErsNaam
                           ORDER BY     ErsNaam, Volgorde, ErsId
                          )
  ) tmpErsBinnen
  where tmpErsBuiten.ersId = tmpErsBinnen.ersId and tmpErsBuiten.ersNaam is not null;

  // En resultaat teruggeven
  select ersId, ersNaam
  from tmpErs
  where ersNaam is not null
  order by ersNaam;

end;


create or replace procedure ExecuteAdminOnderhoud(@Id nchar(80))
begin
  if exists(select first 1 from sys.sysprocedure where proc_name = @Id) then
    execute immediate 'call ' || @Id || '()';
  else
    call Raise(20371, 'AdminOnderhoud identifier ''' || @Id || ''''); //20371) %1! niet gevonden!
  end if;
end;


create or replace procedure App__KingERP_MagazijnOntvangstDigitaalArchief(
  in @OntvangstNummer integer
)
result(
  OntvangstNummer integer,
  DarNummer       nchar(20),
  DarDatum        date,
  DarOpmerking    long nvarchar
)
begin
  select
    MokNummer as OntvangstNummer,
    DarNummer,
    DarDatum,
    DarOpmerking
  from
    tabDigitaalArchiefMagazijnOntvangsten
    inner join tabMagazijnOntvangstenKop on MokGid = DaMagOntMokGid
    inner join tabDigitaalArchief        on DarGid = DaMagOntDarGid
  where
    MokNummer = @OntvangstNummer

  union all

  select
    MohkNummer as OntvangstNummer,
    DarNummer,
    DarDatum,
    DarOpmerking
  from
    tabDigitaalArchiefMagOntvHist
    inner join tabMagazijnOntvangstHistKop on MohkGid = DaMohMohkGid
    inner join tabDigitaalArchief          on DarGid  = DaMohDarGid
  where
    MohkNummer = @OntvangstNummer;
end;


create or replace procedure App__KingERP_MagazijnOntvangstRegel(
  in @OntvangstNummer integer,
  in @Regelnummer     integer default null
)
result(
  MagOntRglGid                             integer,
  MagOntRglSoort                           smallint,
  MagOntRglHistorie                        smallint,
  MagOntNummer                             integer,
  MagOntRglValNummer                       integer,
  MagOntRglRegelnr                         integer,
  MagOntRglRegelsoort                      smallint,
  MagOntRglArtCode                         nchar(20),
  MagOntRglArtOms                          nchar(40),
  MagOntRglArtCodeBijLeverancier           nchar(20),
  MagOntRglEanCode                         nchar(30),
  MagOntRglBstKopNummer                    integer,
  MagOntRglBstRglNummer                    integer,
  MagOntRglArtPartijNummer                 nchar(20),
  MagOntRglArtPartijOms                    nchar(40),
  MagOntRglArtOmsEenheid                   nchar(20),
  MagOntRglArtPrijsPer                     numeric(15,3),
  MagOntRglInkoopEenheid                   nchar(20),
  MagOntRglAantalInkoopEenheden            numeric(15,3),
  MagOntRglVoorraadEenhedenInInkoopEenheid numeric(15,3),
  MagOntRglInkoopprijs                     numeric(15,3),
  MagOntRglInkoopprijsPer                  smallint,
  MagOntRglPrijsPer                        numeric(15,3),
  MagOntRglArtKostprijsEx                  numeric(15,3),
  MagOntRglKortingSoort                    smallint,
  MagOntRglKortingBedrag                   numeric(15,3),
  MagOntRglKortingPercentage               numeric(15,2),
  MagOntRglAantal                          integer,
  MagOntRglAantalCorrectie                 integer,
  MagOntRglBtwCode                         integer,
  MagOntRglBtwPerc                         numeric(6,2),
  MagOntRglCbsTrCode                       nchar(2),
  MagOntRglCbsTrOms                        nchar(250),
  MagOntRglCbsLandCode                     nchar(3),
  MagOntRglCbsLandOms                      nchar(40),
  MagOntRglCbsTaric                        nchar(2),
  MagOntRglCbsPreferentieCode              nchar(3),
  MagOntRglCbsDouaneregeling               nchar(4),
  MagOntRglCbsMeenemenInAangifte           smallint,
  MagOntRglOpm                             long nvarchar
)
begin
  declare @MokGid         integer;
  declare @MokSoort       smallint;
  declare @MokCbsMeenemen smallint;
  declare @MokValNummer   integer;

  select MokGid,  MokSoort,  MokCbsMeenemenInAangifte, MokValNummer
  into  @MokGid, @MokSoort, @MokCbsMeenemen,          @MokValNummer
  from  tabMagazijnOntvangstenKop
  where MokNummer = @OntvangstNummer;

  if @MokGid is not null then
    Select
      MagOntGid                             as MagOntRglGid,
      @MokSoort                             as MagOntRglSoort,
      0 /* nog niet verwerkt */             as MagOntRglHistorie,
      @OntvangstNummer                      as MagOntNummer,
      @MokValNummer                         as MagOntRglValNummer,
      MagOntRegelnr                         as MagOntRglRegelNr,
      MagOntRegelsoort                      as MagOntRglRegelsoort,
      ArtCode                               as MagOntRglArtCode,
      ArtOms                                as MagOntRglArtOms,
      MagOntArtCodeBijLeverancier           as MagOntRglArtCodeBijLeverancier,
      MagOntEanCode                         as MagOntRglEanCode,
      BstKopNummer                          as MagOntRglBstKopNummer,
      BstRglNummer                          as MagOntRglBstRglNummer,
      ArtPartijNummer                       as MagOntRglArtPartijNummer,
      ArtPartijOms                          as MagOntRglArtPartijOms,
      ArtOmsEenheid                         as MagOntRglArtOmsEenheid,
      ArtPrijsPer                           as MagOntRglArtPrijsPer,
      MagOntInkoopEenheid                   as MagOntRglInkoopEenheid,
      MagOntAantalInkoopEenheden            as MagOntRglAantalInkoopEenheden,
      MagOntVoorraadEenhedenInInkoopEenheid as MagOntRglVoorraadEenhedenInInkoopEenheid,
      MagOntInkoopprijs                     as MagOntRglInkoopprijs,
      MagOntInkoopprijsPer                  as MagOntRglInkoopprijsPer,
      MagOntPrijsPer                        as MagOntRglPrijsPer,
      ArtKostprijsEx                        as MagOntRglArtKostprijsEx,
      MagOntKortingSoort                    as MagOntRglKortingSoort,
      MagOntKortingBedrag                   as MagOntRglKortingBedrag,
      MagOntKortingPercentage               as MagOntRglKortingPercentage,
      MagOntAantal                          as MagOntRglAantal,
      MagOntAantalCorrectie                 as MagOntRglAantalCorrectie,
      MagOntBtwCode                         as MagOntRglBtwCode,
      BtwPercentage                         as MagOntRglBtwPerc,
      CbsTrCode                             as MagOntRglCbsTrCode,
      CbsTrOms                              as MagOntRglCbsTrOms,
      LndEigenCode                          as MagOntRglCbsHerkomstLndCode,
      LndOms                                as MagOntRglCbsHerkomstLndOms,
      MagOntCbsTaric                        as MagOntRglCbsTaric,
      MagOntCbsPreferentieCode              as MagOntRglCbsPreferentieCode,
      MagOntCbsDouaneregeling               as MagOntRglCbsDouaneregeling,
      @MokCbsMeenemen                       as MagOntRglCbsMeenemenInAangifte,
      MagOntOpm                             as MagOntRglOpm

    from tabMagazijnOntvangsten
    inner join      tabArtikel       on ArtGid       = MagOntArtGid
    left outer join tabArtikelPartij on ArtPartijGid = MagOntArtPartijGid
    left outer join tabBestelRegel   on BstRglGid    = MagOntBstRglGid
    left outer join tabBestelKop     on BstKopGid    = BstRglBstKopGid
    left outer join tabBtw           on BtwCode      = MagOntBtwCode
    left outer join tabCbsTransactie on CbsTrGid     = MagOntCbsTrGid
    left outer join tabLand          on LndGid       = MagOntCbsLndGidOorsprong
    where MagOntMokGid = @MokGid
          and (@Regelnummer is null or MagOntRglRegelnr = @Regelnummer)

  else
    select MohkGid, MohbSoort, MohkCbsMeenemenInAangifte, MohkValnummer
    into @MokGid, @MokSoort, @MokCbsMeenemen, @MokValNummer
    from  tabMagazijnOntvangstHistKop
    left outer join tabMagazijnOntvangstHistBatch on MohbGid = MohkMohbGid
    where MohkNummer = @OntvangstNummer;

    if @MokGid is not null then
      select
        MohrGid                             as MagOntRglGid,
        @MokSoort                           as MagOntRglSoort,
        1 /* verwerkt */                    as MagOntRglHistorie,
        @OntvangstNummer                    as MagOntNummer,
        @MokValNummer                       as MagOntRglValNummer,
        MohrRegelnr                         as MagOntRglRegelnr,
        MohrRegelsoort                      as MagOntRglRegelsoort,
        MohrArtCode                         as MagOntRglArtCode,
        MohrArtOms                          as MagOntRglArtOms,
        MohrArtCodeBijLeverancier           as MagOntRglArtCodeBijLeverancier,
        MohrEanCode                         as MagOntRglEanCode,
        MohrBstKopNummer                    as MagOntRglBstKopNummer,
        MohrBstRglNummer                    as MagOntRglBstRglNummer,
        MohrArtPartijNummer                 as MagOntRglArtPartijNummer,
        MohrArtPartijOms                    as MagOntRglArtPartijOms,
        MohrArtOmsEenheid                   as MagOntRglArtOmsEenheid,
        null                                as MagOntRglArtPrijsPer,
        MohrInkoopEenheid                   as MagOntRglInkoopEenheid,
        MohrAantalInkoopEenheden            as MagOntRglAantalInkoopEenheden,
        MohrVoorraadEenhedenInInkoopEenheid as MagOntRglVoorraadEenhedenInInkoopEenheid,
        MohrInkoopprijs                     as MagOntRglInkoopprijs,
        MohrInkoopprijsPer                  as MagOntRglInkoopprijsPer,
        MohrPrijsPer                        as MagOntRglPrijsPer,
        MohrArtKostprijsEx                  as MagOntRglArtKostprijsEx,
        MohrKortingSoort                    as MagOntRglKortingSoort,
        MohrKortingBedrag                   as MagOntRglKortingBedrag,
        MohrKortingPercentage               as MagOntRglKortingPercentage,
        MohrAantal                          as MagOntRglAantal,
        MohrAantalCorrectie                 as MagOntRglAantalCorrectie,
        MohrBtwCode                         as MagOntRglBtwCode,
        MohrBtwPercentage                   as MagOntRglBtwPerc,
        MohrCbsTrCode                       as MagOntRglCbsTrCode,
        MohrCbsTrOms                        as MagOntRglCbsTrOms,
        MohrCbsOorsprongLndEigenCode        as MagOntRglCbsHerkomstLndCode,
        MohrCbsOorsprongLndOms              as MagOntRglCbsHerkomstLndOms,
        MohrCbsTaric                        as MagOntRglCbsTaric,
        MohrCbsPreferentieCode              as MagOntRglCbsPreferentieCode,
        null                                as MagOntRglCbsDouaneregeling,
        @MokCbsMeenemen                     as MagOntRglCbsMeenemenInAangifte,
        MohrOpm as MagOntRglOpm
      from
        tabMagazijnOntvangstHistRegel
      where
        MohrMohkGid = @MokGid
        and (@Regelnummer is null or MagOntRglRegelnr = @Regelnummer)

    else

      call "Raise"(20700,"_U"('OntvangstNummer')); // (20700) Invalid value: %1!

    endif;

  endif;
end;


create or replace procedure App__KingERP_MagazijnOntvangstRegelSpec(
  in @RegelGid integer,  // MagOntGid of MohrGid, afhankelijk van @Historie
  in @Historie smallint  // 0 = niet-verwerkte MO/DirLev, 1 = verwerkte (historische) MO/DirLev
)
result(
  SpecGid               integer,  // MagOntDetGid of Mohdgid
  Historie              smallint,
  Soort                 smallint,
  OrderNr               numeric(10,0),
  OrderRegelNr          integer,
  AantalBesteld         numeric(15,3),
  AantalOntvangen       numeric(15,3),
  AantalCorrectie       numeric(15,3),
  DebiteurNr            nchar(10),
  DebiteurNaam          nchar(40),
  AfleverAdresGid       integer,
  AfleverStraat         nchar(40),
  AfleverHuisnummer     nchar(10),
  AfleverPostcode       nchar(40),
  AfleverPlaats         nchar(40),
  AfleverContactpersoon nchar(40),
  AfleverEmail          nchar(80)
)
begin
  if @Historie = 1 then
    select
      MohdGid as SpecGid,
      1 /* verwerkt */         as Historie,
      MohdBrdSoort             as Soort,
      MohdOrkNummer            as OrderNr,
      MohdOrrRegelnr           as OrderRegelNr,
      MohdBrdAantalBesteld     as AantalBesteld,
      MohdBrdAantalOntvangen   as AantalOntvangen,
      MohdBrdAantalCorrectie   as AantalCorrectie,
      MohaNawFilNummer         as DebiteurNr,
      MohaNaam1                as DebiteurNaam,
      MohaGid                  as AfleverAdresGid,
      MohaStraat               as AfleverStraat,
      MohaHuisnummer           as AfleverHuisnummer,
      MohaPostcode             as AfleverPostcode,
      MohaPlaats               as AfleverPlaats,
      MohaContactVolledigeNaam as AfleverContactpersoon,
      MohaEmail                as AfleverEmail
    from
      tabMagazijnOntvangstHistDetail
      left outer join tabMagazijnOntvangstHistAdres on (MohaGid = MohdMohaGid)
    where
      MohdMohrGid = @RegelGid;

  else

    SELECT
      MagOntDetGid              as SpecGid,
      0 /* nog niet verwerkt */ as Historie,
      MagOntDetBrdSoort         as Soort,
      isnull(OrkNummer,  if MagOntDetBrdGid is null then MagOntDetOrkNummer  else BrdOrkNummer  endif) as OrderNr,
      isnull(OrrRegelNr, if MagOntDetBrdGid is null then MagOntDetOrrRegelNr else BrdOrrRegelnr endif) as OrderRegelNr,
      brdAantalBesteld          as AantalBesteld,
      isnull((select sum(MagOntLocAantal) from tabMagazijnOntvangstLocatieSerie where MagOntLocMagOntDetGid = MagOntDetGid), 0) as AantalOntvangen,
      MagOntDetAantalCorrectie  as AantalCorrectie,
      if MagOntDetBrdGid is null then MagOntDetNawFilNummer  else if BrdOrrGid is null then brdNawFilNummer else NawFilNummer  endif endif DebiteurNr,
      if MagOntDetBrdGid is null then MagOntDetAdrNaam1      else if BrdOrrGid is null then brdAdrNaam1     else AdrNaam1      endif endif DebiteurNaam,
      NawGidVestiging           as afleverAdresGid,
      AdrStraat                 as AfleverStraat,
      AdrHuisnummer             as AfleverHuisnummer,
      AdrPostcode               as AfleverPostcode,
      AdrPlaats                 as AfleverPlaats,
      RelVolledigeNaam          as AfleverContactpersoon,
      AdrEmail                  as AfleverEmail
    FROM
      tabMagazijnOntvangstenDetail
      left outer join tabBestelRegelDetail on (brdGid = MagOntDetbrdGid)
      left outer join (tabOrderRegel
                       inner join tabOrderkop  on (OrkGid = OrrOrkGid)
                       inner join tabNaw       on (NawGid = OrkNawGid)
                       inner join tabNawFile   on (NawFilNawGid = OrkNawGid and NawFilFonID='D')
                       inner join tabAdres     on (AdrGid = NawGidVestiging)
                       left outer join tabRelatie on (RelGid = AdrRelGid)
                      )
                      on (OrrGid = isnull(BrdOrrGid, MagOntDetOrrGid))

    where
      MagOntDetMagOntGid = @RegelGid;
  endif
end;


create or replace procedure App__KingERP_MagazijnOntvangstRegelSpecLocatieSerie(
  in @SpecGid  integer, // MagOntDetGid of MohdGid, afhankelijk van @Historie
  in @Historie smallint // 0 = niet-verwerkte MO/DirLev, 1 = verwerkte (historische) MO/DirLev
)
result(
  LocGid      integer,
  Serienummer nchar(20),
  Aantal      numeric(15,3),   // Ontvangen aantal voor deze locatie
  LocNaam     nchar(20),       // Naam van locatie (obv historisch, anders LocGid)
  LocOms      nchar(40)        // Omschr.  locatie (obv historisch, anders LocGid)
)
begin
  if @Historie = 1 /* verwerkt */ then
    select
      NULL as LocGid,
      MohlArtSerienummer as Serienummer,
      MohlAantal as aantal,
      MohlLocNaam as locnaam,
      MohlLocOms as LocOms
    from tabMagazijnOntvangstHistLocatieSerie
    where MohlMohdGid = @SpecGid;
  else /* nog niet verwerkt */
    select
      MagOntLocGid as LocGid,
      ArtSerieNummer as SerieNummer,
      MagOntLocAantal as aantal,
      LocNaam,
      LocOms
    from tabMagazijnOntvangstLocatieSerie
    left outer join tabArtikelSerienummer on (ArtSerieGid = MagOntLocArtSerieGid)
    left outer join tabLocatie on (tabLocatie.LocGid = MagOntLocLocGid)
    where MagOntLocMagOntDetGid = @SpecGid;
  end if;
end;


create or replace procedure Banktransacties_BoekingsgangGebruiken(
  in    @BjGid          integer,
  inout @BoekgangGid    integer,
  out   @result         integer
)
/*
  Als er nog geen boekingsgang is, dan die aanmaken.
  Als boekingsgang al is meegegeven, dan die in gebruik nemen mits:
  - zelfde boekjaar
  - niet in gebruik
  - van soort Verwerken banktransacties
  Maakt nieuwe aan als de boekingsgang die is meegegeven niet kan worden gebruikt

  //TODO!! Controles nog toevoegen
*/

begin
  declare @__Result_OK smallint = 0;
  declare @__Result_NieuweBoekingsgangGegenereerd smallint = 100;

  declare @DoCommit smallint = 0;

  call Banktransacties_Log('//Banktransacties_BoekingsgangGebruiken; @BoekgangGid='+string(@BoekgangGid), 3);
  set @Result = @__Result_OK;

  if @BoekgangGid is not null then
  begin
    declare @IsGoed smallint = 0;

    // Boekingsgang eventueel in gebruik nemen
    //- Controleren op zelfde boekjaar
    //- Boekjaar niet geblokkeerd
    select first 1 into @IsGoed
    from
      tabBoekingsgang
      inner join tabBoekjaar on BjGid = BoekGangBjGID
    where
      BoekgangGid = @BoekgangGid
      and BoekGangBjGID = @BjGid // Moet in zelfde boekjaar als deze transactie, anders is het niet goed en maken we een nieuwe boekingsgang in het juiste boekjaar aan
      and BjIsGeblokkeerd = 0; // Is eigenlijk al eerder gecontroleerd, boekjaar was 0,01 seconden geleden nog niet geblokkeerd


    // Huidige UIT GEBRUIK halen
    if @IsGoed = 0 then
      update tabBoekingsgang
      set    BoekGangInGebruik = 0
      where  BoekGangInGebruik = 1
         and BoekgangGid = @BoekgangGid;
      // Gewoon doen alsof we nog niks hebben
      set @BoekgangGid = null;
    end if;
  end;
  end if;

  // ACW Verplaatst, de eventuele gesloten boekingsgang committen we (incl. al het werk in de banktransacties) als er een andere BG wordt gebruikt
  commit;

  // Boekingsgang (evt) aanmaken of in gebruik nemen
  if @BoekgangGid is null then

    // Nieuwe boekingsgang aanmaken
    insert into tabBoekingsGang(BoekGangBjGid, BoekGangBronId,                   BronOms,                      BoekGangInGebruik, IsBoekGangDefinitief)
                        values (@BjGid,        39 /*Verwerken banktransacties*/, 'Verwerken banktransacties',  1,                 0);
    set @BoekgangGid = @@Identity;
  else
    update tabBoekingsgang
    set    BoekGangInGebruik = 1
    where  BoekGangInGebruik = 0
       and BoekgangGid = @BoekgangGid;
  end if;

end;


create or replace procedure Banktransacties_calcOperand(
  in @OperandType integer,
  in @OperandValue long nvarchar,
  in @OperandPrefix nchar(40),
  in @OperandPostfix nchar(40),
  out @_Operand long nvarchar
)
begin
  declare @_OperandValue long nvarchar;

  if @OperandType = 0 /*geen*/ then
    set @_Operand = '';
    return; //procedure;
  end if;

  case @OperandType
  when 1 /*veld uit transactie*/ then
    set @_Operand = @OperandValue;
  when 2 /*tekstwaarde*/ then
    set @_OperandValue = Replace(@OperandValue, '''', '''''');
    if @OperandPrefix is not null then
      set @_Operand = '''' + @OperandPrefix + @_OperandValue;
    else
      set @_Operand = '''' + @_OperandValue;
    end if;
      if @OperandPostfix is not null then
        set @_Operand = @_Operand + @OperandPostfix + '''';
      else
        set @_Operand = @_Operand + '''';
      end if;

  when 3 /*getalwaarde*/ then
    set @_OperandValue = Replace(@OperandValue, '''', ''''''); // Voor de zekerheid toch de kwootjes verdubbelen
    if @OperandPrefix is not null then
      set @_Operand = @OperandPrefix + @_OperandValue;
    else
      set @_Operand = @_OperandValue;
    end if;
      if @OperandPostfix is not null then
        set @_Operand = @_Operand + @OperandPostfix;
      else
        set @_Operand = @_Operand;
      end if;

  when 4 /*Veld uit database*/ then
    if @OperandPrefix is not null then
      set @_Operand = '''' + @OperandPrefix + ''' + ' + @OperandValue;
    else
      set @_Operand = @OperandValue;
    end if;
    if @OperandPostfix is not null then
      set @_Operand = @_Operand + ' + ''' + @OperandPostfix + '''';
    end if;

  when 5 /*Berekening*/ then
    // TODO Best gevaarlijk ivm SQL-injection
    set @_Operand = @OperandValue;
  when 6 /*Set*/ then
    // Komma-delimited begint met haakje openen, eindigt met haakje sluiten
    set @_Operand = Replace(@OperandValue, '''', '''''');
  when 7 /*Partition name*/ then
    set @_Operand = @OperandValue;

  else
      call Banktransacties_Log('Invalid operand type ' + string(@OperandType), 1);
    call Raise(20700, 'Operand type ' + string(@OperandType)); //(20700) Ongeldige waarde: %1!
  end case;
end;


create or replace procedure Banktransacties_Cleanup(
  inout @SessieNr            integer,
  inout @RakGid              integer,
  inout @BoekgangGid         integer,
  inout @MatViewUniekNummers ROW(
          vwVoorraadaantallen             integer,
          vwBackorderAantallen            integer,
          vwVoorraadAantallenKlein        integer,
          vwBestelKopTotalen              integer,
          vwMeestRecenteOpenstaandePosten integer
        )
)
begin

  call Banktransacties_Log('//Cleanup started for session ' || @SessieNr || ': Rak=' || @RakGid || ', boekingsgang=' || @BoekgangGid, 2);

  // Release all used materialized views
  call Banktransacties_MatViewOrganize(@MatViewUniekNummers,0 /*ReleaseAll*/);

  if @RakGid is not null then
    call Banktransacties_Unlock(@RakGid);
    set @RakGid = null;
  end if;

  if @SessieNr is not null then
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'CreateSession', @SessieNr);
    set @SessieNr = null;
  end if;

  // Boekingsgang uit gebruik halen
  if @BoekgangGid is not null then
    update tabBoekingsgang
    set    BoekGangInGebruik = 0
    where  BoekGangInGebruik = 1
       and BoekgangGid = @BoekgangGid;
  end if;


  // Just to be sure we haev no left-overs
  call Banktransacties_RepairFatalErrors();

  call Banktransacties_Log('//Cleanup done for session ' || @SessieNr, 2);

  // make sure the cleanup cannot be undone by a rollback
  // (because a part of this execution is already committed due to creating/updating the materialized view)
  commit;

end;


create or replace procedure Banktransacties_Event_DoVerwerken(@a nchar(80))
begin
  declare @DoVerwerken smallint;
  declare @StartDatumTijd DateTime = now();
  declare @ConnId integer;
  declare @ConnDateTime DateTime;
  declare @Result integer;

  declare @__REGKEY_LASTSUCCESS nchar(80) = 'BanktransactiesVerwerken_LastSuccess';
  declare @__REGKEY_CANSTART nchar(80)  = 'BanktransactiesVerwerken_CanStart'; //0/null=nee, 1=Ja, als er nieuwe transacties zijn, 2=altijd
  declare @__REGKEY_SPECIAL_ADMIN nchar(80) = 'SPECIAL_ADMIN';
  declare @__LOCK_PROCESS nchar(40) = 'BanktransactiesVerwerken';


  declare @__DOVERWERKEN_NIET smallint = 0;
  declare @__DOVERWERKEN_NIEUWE smallint = 1; // Alleen verwerken als er transacties zijn NA de laatste keer autom.verwerken
  declare @__DOVERWERKEN_ALTIJD smallint = 2; // Altijd (proberen te) verwerken, ongeacht nieuwste datumtijd van transacties

  declare @__Result_OK                                  smallint = 0;
  declare @__Result_LockNietGelukt                      smallint = 1;
  declare @__Result_Geblokkeerd                         smallint = 2;
  declare @__Result_PeriodeNietGevonden                 smallint = 3;
  declare @__Result_BoekingsgangKanNietWordenAangemaakt smallint = 4;
  declare @__Result_StoppedBeforeEnd                    smallint = 5;
  declare @__Result_CircularReferenceInRegels           smallint = 10;
  declare @__Result_NieuweBoekingsgangGegenereerd       smallint = 100;
  declare @__Result_FoutBijBoekreferentie               smallint = 101;


  declare @__Result_GeneralFailure smallint = 999;

  declare @__SecondsToPassAfterInsertedTransaction smallint = 60; // Aantal seconden dat er geen wijziging meer mag zijn geweest in de transacties, omdat
                                                        // waarschijnlijk nu nog wordt toegevoegd; safety margin om een heel blok toch te kunnen verwerken

  // ***********************************
  // *** Initialiseren van connectie ***
  // ***********************************
  call DatabaseInit();
  set @ConnId = connection_property('number');
  set @ConnDateTime = connection_property('LoginTime');
  call SetMutatieLogVars('Verwerken banktransacties');

  //Welke @@Gebruikercode??? (Er moet ook een @@GebruikerGid voor zijn gevonden!)

  call Banktransacties_Log('//!!!!Verwerken banktransacties - FiredByTrigger ' + @a + ' at ' + string(now()), 2);
  call Banktransacties_LogToGebruikersLog(_A('Verwerken banktransacties'), _A('Gebeurtenis ''%1!'' gestart',  @a));

  // ***********************************
  // *** Kan actie worden opgestart? ***
  // ***********************************
  set @DoVerwerken = @__DOVERWERKEN_NIEUWE; // Default WEL verwerken
  if exists(select first 1 from tabregistry where regkey = @__REGKEY_SPECIAL_ADMIN and isnull(contents, '')<>'') then
    set @DoVerwerken = @__DOVERWERKEN_NIET;
      call Banktransacties_Log('//!!!!Verwerken banktransacties - FiredByTrigger ' + @a + '; Database wordt geupdatet!', 3);
  else
    set @DoVerwerken = @__DOVERWERKEN_NIEUWE; // Default WEL verwerken
    select if isnumeric(Contents) = 1 then Contents else @__DOVERWERKEN_NIET endif
    into @DoVerwerken
    from tabRegistry
    where Regkey = @__REGKEY_CANSTART;
  end if;
  if @DoVerwerken = @__DOVERWERKEN_NIET then
    call Banktransacties_Log('//!!!!Verwerken banktransacties - FiredByTrigger ' + @a + '; finished prematurely, action shall not start!', 2);
    return; // Gelijk stoppen!
  end if;


  // *************************
  // *** Actie lock zetten ***
  // *************************
  begin
    declare @LockGelukt smallint;
    call LockWaitAndSetForUniqueLock(@ConnId, @ConnDateTime, @__LOCK_PROCESS, '', 2 /*seconden*/, @LockGelukt);
    if @LockGelukt = 0 then
      call Banktransacties_Log('//!!!!Verwerken banktransacties - FiredByTrigger ' + @a + '; finished prematurely, lock failed!', 2);
      call Banktransacties_LogToGebruikersLog(_A('Verwerken banktransacties'), _A('niet gestart; proces wordt al uitgevoerd (lock niet gelukt)'));
      //set @DoVerwerken = 0;
      return; // Gelijk stoppen!
    end if;
  end;


  // ***********************************************************
  // *** Actie afhankelijk van datum/tijd nieuwe transacties ***
  // ***********************************************************
  if @DoVerwerken = @__DOVERWERKEN_NIEUWE then
    begin
      declare @VorigeVerwerkDatumTijd DateTime;

      //Test op nieuwe transacties
      // Lees laast gelukte datumtijd
      select if isdate(contents) = 1 then contents endif into @VorigeVerwerkDatumTijd from tabregistry where Regkey = @__REGKEY_LASTSUCCESS;

      // Controleer of er transacties NA de vorige verwerking zijn
      begin
        declare @NieuwsteRar DateTime;

        select max(RarLastModified) into @NieuwsteRar from tabRekeningafschriftRegel;

        // Controle: Als er geen RarDatum is gevonden, dan zijn er geen transacties, dus dan hoeven we ook niks te doen
        if @NieuwsteRar is null then
          set @DoVerwerken = @__DOVERWERKEN_NIET;
          call Banktransacties_Log('!!!!Verwerken banktransacties - FiredByTrigger ' + @a + '; finished prematurely, no transactions found', 2);
          call Banktransacties_LogToGebruikersLog(_A('Verwerken banktransacties'), _A('niet gestart; geen banktransacties gevonden'));
        end if;

        // Als de Rardatum binnen X seconden voor de huidige datum+tijd valt, dan skippen we deze ronde
        if @NieuwsteRar > dateadd(second, -@__SecondsToPassAfterInsertedTransaction, now()) then
          set @DoVerwerken = @__DOVERWERKEN_NIET;
          call Banktransacties_Log('//!!!!Verwerken banktransacties - FiredByTrigger ' + @a + '; finished prematurely, last update within cool-down period', 2);
          call Banktransacties_LogToGebruikersLog(_A('Verwerken banktransacties'), _A('niet gestart; meest recente transactie binnen de cool-down periode'));
        end if;

        // Als de nieuwste Rardatum kleiner is dan de laatste verwerkingsdatum, dan is er niks nieuws, dus niet uitvoeren
        if (@NieuwsteRar < isnull(@VorigeVerwerkDatumTijd, @NieuwsteRar)) then
          set @DoVerwerken = @__DOVERWERKEN_NIET;
          call Banktransacties_Log('//!!!!Verwerken banktransacties - FiredByTrigger ' + @a + '; finished prematurely, already up-to-date!', 2);
          call Banktransacties_LogToGebruikersLog(_A('Verwerken banktransacties'), _A('niet gestart; reeds up-to-date'));
        end if;
      end;

    end;
  end if;

  // **********************************
  // *** Actie starten indien nodig ***
  // **********************************
  if @DoVerwerken > @__DOVERWERKEN_NIET then
      call Banktransacties_Log('//!!!!Verwerken banktransacties - FiredByTrigger ' + @a + '; DO VERWERKEN, PROCEDURES AANROEPEN!', 3);

    // +++++++++++++++++++++++++++++++
    // +++ Aanroepen verwerkproces +++
    // +++++++++++++++++++++++++++++++
    begin
      declare @Foutmelding nchar(250);
      call Banktransacties_VerwerkTransacties(null, @Result);
      call Banktransacties_LogToGebruikersLog(_A('Verwerken banktransacties'),
        case @Result
          when @__Result_OK                                  then _A('Klaar')
          when @__Result_LockNietGelukt                      then _A('Melding: Lock is niet gelukt')
          when @__Result_Geblokkeerd                         then _A('Melding: Boekjaar of periode is geblokkeerd')
          when @__Result_PeriodeNietGevonden                 then _A('Melding: Periode is niet gevonden')
          when @__Result_BoekingsgangKanNietWordenAangemaakt then _A('Melding: Boekingsgang kan niet worden aangemaakt')
          when @__Result_StoppedBeforeEnd                    then _A('Melding: Afgebroken ivm stoppen van achtergrondtaken')
          when @__Result_CircularReferenceInRegels           then _A('Melding: Circular reference in matching-regels')
          when @__Result_NieuweBoekingsgangGegenereerd       then _A('Melding: Klaar; nieuwe boekingsgang gegenereerd')
          when @__Result_FoutBijBoekreferentie               then _A('Melding: Fout bij genereren boekreferentie')
          else _A('onbekend (%1!)', string(@Result))
        end, if @Result = @__Result_OK then 0 /*info*/ else 1 /*fout*/ endif);
      exception
      when others then
        begin
          declare @err_code  integer   = SQLCODE;
          declare @err_state char(5)   = SQLSTATE;
          declare @err_msg   long nvarchar = error_message();
          rollback;
          call Banktransacties_LogToGebruikersLog(_A('Fout bij automatisch verwerken banktransacties'),
            @err_code || '|' || @err_state || '|' || @err_msg
            , 1 /*Fout*/);
          commit; // Make sure everything is stored safely
          if @Result = @__Result_OK then
            set @Result = @__Result_GeneralFailure;
          end if;

          //resignal; // Kan dit wel? Zo wordt logboek ook ongedaan gemaakt
        end;

    end;

    // ++++++++++++++++++++++++++++++++++++++++++++
    // +++ Onthouden laatste geslaagde datetime +++
    // ++++++++++++++++++++++++++++++++++++++++++++
    // Eventueel nog op specifieke fouten testen later, maar voor nu: niet OK = niet bijwerken
    if @Result = @__Result_OK then
      if not exists(select first 1 from tabregistry where Regkey = @__REGKEY_LASTSUCCESS) then
        insert into tabRegistry(Regkey, Contents, SoortVeld)
        values(@__REGKEY_LASTSUCCESS, @StartDatumTijd, 3 /*Date*/);
      else
        update tabRegistry set Contents = @StartDatumTijd where Regkey = @__REGKEY_LASTSUCCESS;
      end if;
    end if;

  end if;

  // *******************
  // *** Remove lock ***
  // *******************
  call LockReleaseOnId(@ConnId, @ConnDateTime, 1 /*write-lock*/, @__LOCK_PROCESS, '');

end;


create or replace procedure Banktransacties_JournaalpostAanmaken(
  in  @BoekGangGid                     integer,
  in  @Instelling_Stuknummer           smallint,
  in  @transactie_Afschriftnr          integer,
  in  @Omschrijving                    long nvarchar,
  in  @Boekdatum                       Date,
  in  @TeBoekenInBjGid                 integer,
  in  @TeBoekenInPerNr                 integer,
  in  @DgbGidEigenBankrekening         integer,
  out @NieuweJPGid                     integer
)
begin
  declare @Boeking_Afschriftnr numeric(10,0);
    // Journaalpost aanmaken (Opzoeken van bestaande van deze transactie???)

    // Bepaal afschriftnummer voor boeking
    case @Instelling_Stuknummer
      when 0 /*Afschriftnummer*/ then
        set @Boeking_Afschriftnr = @transactie_Afschriftnr;
      when 1 /*conform dagboekinstelling*/ then
        // ACW 16-09-2020 Defect 55937: Eerst zoeken naar journaalpost gekoppeld aan banktransacties voor deze dag en dan hoogstge stuknummer gebruiken
        select max(BoekStukNummer) into @Boeking_Afschriftnr
        from tabjournaalpost inner join tabjournaalregel on jrjpgid = jpgid
        where JpDgbGid = @DgbGidEigenBankrekening
          and JpBjGid = @TeBoekenInBjGid
          and JrRarGid is not null
          and BoekDatum = @BoekDatum;
        if @Boeking_Afschriftnr  is null then
          call BoekstuknummerGenereren(@TeBoekenInBjGid, @DgbGidEigenBankrekening, @Boeking_Afschriftnr);
        end if;
    end case;

    insert into tabJournaalPost WITH AUTO NAME
    select
      @BoekGangGid AS JpBoekGangGid,
      @TeBoekenInBjGid AS JpBjGid,
      @DgbGidEigenBankrekening AS JpDgbGid,
      //JpDgbCode
      @Boeking_Afschriftnr AS BoekStukNummer,
      @Omschrijving AS OmsJournaalpost,
      @Boekdatum AS BoekDatum,
      1 AS JpIsInGebruik,
      //JpNummer
      @TeBoekenInPerNr AS JpPerNr
    ;
    set @NieuweJPGid = @@Identity;
      call Banktransacties_Log('//Journaalpost aangemaakt. JpGid='+string(@NieuweJPGid), 3);
end;

create or replace procedure Banktransacties_JournaalRegelAanmakenVoorGrootboekRekening(
  in @JpGid integer,
  in @Rargid integer,
  in @Boekdatum date,
  in @RksGid integer,
  in @IsCredit smallint,
  in @bedrag numeric(15,3),
  in @Valnummer integer,
  in @Referentie nchar(40),
  in @Omschrijving long nvarchar,
  in @IsInclBtw smallint, // 1 = incl. BTW, dus extra BTW-boeking maken als rekening een BTW heeft
  out @GeboektIsCredit smallint,
  out @GeboektBedragInRarVal numeric(15,2)
)
begin

  // tbv. boeken van vreemde valuta
  declare @BjGid integer;
  declare @PerNr integer;
  declare @BtwCode integer;
  declare @BtwRksGid integer;
  declare @BtwBedragValuta numeric(15,2) = 0;
  declare @BtwBedragBasis numeric(15,2) = 0;
  declare @BtwPercentage numeric(10,3) = 0;

  if @Valnummer <> @@Basisvalutanummer then
    // Andere valuta, dus juiste boekjaar+periode opvragen tbv omrekenen
    select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
  end if;

  if exists(select 1 from tabrekeningschema where rksgid = @rksgid and IsRksGeblokkeerd = 1) then
    set @GeboektIsCredit  = 0;
    set @GeboektBedragInRarVal = 0;
    return;
  end if;

  // BTW uitrekenen
  if @IsInclBtw = 1 then
    select RksBtwCode, BtwPercentage, BtwRksGid
    into @BtwCode, @BtwPercentage, @BtwRksGid
    from tabRekeningSchema
         inner join tabBTW on BtwCOde = RksBtwCode
    where RksGid = @RksGid;

    if @BtwCode is not null then
      set @BtwBedragValuta = @bedrag / (100 + @BtwPercentage) * @BtwPercentage;
      if @Valnummer <> @@Basisvalutanummer then
        set @BtwBedragBasis = ValutaOmrekenen(@Valnummer, @BtwBedragValuta, @@Basisvalutanummer, @BjGid, @PerNr, 2)
      else
        set @BtwBedragBasis = @BtwBedragValuta;
      end if;
    end if;
  end if;


  insert into tabJournaalregel WITH AUTO NAME
  select
    @JpGid AS JrJpGid,
    @Rargid AS JrRargid,
    @Boekdatum AS JrBoekdatum,
    Banktransacties_VolgendStukVolgnummer(@JpGid) AS StukVolgnr,
    @RksGid AS JrRksGID,
    @IsCredit IsCreditBoeking,
    @Valnummer AS JrValNummer,
    @bedrag - @BtwBedragValuta AS JrValutaBedrag,
    if @Valnummer = @@Basisvalutanummer then
      @bedrag - @BtwBedragValuta
    else
      ValutaOmrekenen(@Valnummer, @bedrag - @BtwBedragValuta, @@BasisValutaNummer, @BjGid, @PerNr, 2)
    endif AS JrBasisBedrag,
    @Referentie AS JrReferentie,
    @Omschrijving AS OmsJournaalRegel;

  if @BtwCode is not null then
    insert into tabHulprekening WITH AUTO NAME
    select
      @@Identity AS HulprekJrGid,
      1 /*BTW-rekening*/ AS HulpRekSoort,
      @BtwRksGid AS HulprekRksGid,
      @IsCredit AS HulpRekIsCredit,
      @Valnummer AS HulpRekValNummer,
      @BtwBedragBasis AS HulpRekBasisBedrag,
      @BtwBedragValuta AS HulpRekValutaBedrag,
      @BtwCode AS HulpRekBtwCode;
  end if;

  set @GeboektIsCredit = @IsCredit;
  set @GeboektBedragInRarVal = @bedrag;
end;


create or replace procedure Banktransacties_LeesOfGenereerBoekReferentie(
  in @Rargid integer,
  out @BoekReferentie nchar(40),
  out @Result smallint
)
begin
  declare @__Prefix nchar(40) = ''; // Was eerst 'Bank_', nu geen prefix meer; begint gewoon met de boekdatum

  declare @__Result_OK smallint = 0;
  declare @__Result_FoutBijBoekreferentie smallint = 101;

  declare @LockIsGelukt smallint;
  declare @Boekdatum date;
  declare @@PrefixWithDate nchar(40);

  set @Result = @__Result_OK;

  select RarBoekreferentie, RarBoekdatum into @BoekReferentie, @Boekdatum from tabRekeningafschriftregel where Rargid = @Rargid;
  set @@PrefixWithDate = @__Prefix + DateFormat(@Boekdatum, 'yyyymmdd_');

  if isnull(@BoekReferentie, '') = '' then
    //Thread-safe!
    call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'Banktransacties_GenereerBoekReferentie', @@PrefixWithDate, 10 /*seconden*/, @LockIsGelukt);
    if @LockIsGelukt = 0 then
      set @Result = @__Result_FoutBijBoekreferentie;
      return;
    end if;

    // Nogmaals proberen om referentie op te vragen
    select RarBoekreferentie into @BoekReferentie from tabRekeningafschriftregel where Rargid = @Rargid;

    // Nog geen boekreferentie, dan genereren
    if isnull(@BoekReferentie, '') = '' then
      select first RarBoekreferentie into @BoekReferentie from tabRekeningafschriftregel where RarBoekdatum = @Boekdatum order by length(RarBoekreferentie) desc, RarBoekreferentie desc;
      if isnull(@BoekReferentie, '')  = '' then
        set @BoekReferentie = @@PrefixWithDate + '00'; // In principe 2 groot; als meer dan 99 dan wordt het vanzelf breder
      end if;
      call VerhoogAlfaNummer(@@PrefixWithDate, @BoekReferentie, 1 /*Mag verlengen*/, @BoekReferentie);
      update tabRekeningafschriftregel set RarBoekReferentie = @BoekReferentie where Rargid = @Rargid;
    end if;
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'Banktransacties_GenereerBoekReferentie', @@PrefixWithDate);
  end if;
end;



create or replace procedure Banktransacties_Lock(
  in @Rakgid integer,
  out @LockIsGelukt smallint) // 0 = false, 1 = true
begin
  call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'tabRekeningAfschriftKop', @RakGid, 10 /*seconden*/, @LockIsGelukt);
end;


create or replace procedure Banktransacties_Log(
  in @Text long nvarchar,
  in @Verboselevel integer default 2 //0 = nooit tonen, 1 = Error, 2 = Info, 3 = Info detail, 4 = Info uitgebreide detail, 5 = SQL-resultaat, 6 = Transactie-details
)
begin
  declare @Filename nchar(100) = replace(DB_EXTENDED_PROPERTY( 'File' ), '.db', '_Verwerk_Banktransacties.txt');

  if @@Banktransacties_LogVerboseBits & power(2,@Verboselevel-1) <> 0 then

    if @@Banktransacties_LogVerboseBits & 1024 <> 0 then

      if datediff(millisecond,isnull(@@Banktransacties_LastUnloadLog, '2020-01-01'), now()) < 100 then
        waitfor delay '00:00:00:100'; // OS cannot handle appends quickly enough
      end if;

      unload select @Text
      to @Filename APPEND ON QUOTE '' FORMAT text ESCAPES off DELIMITED BY '';

      set @@Banktransacties_LastUnloadLog = now();

    end if;

    if @@Banktransacties_LogVerboseBits & 16384 <> 0 then
      begin
        if exists(select first 1 from sysprocedure where proc_name = 'http_banktransacties_log2http') then
          call http_banktransacties_log2http( now() || ' | ' || @Text);
        end if;
      exception when others then
      end;
    end if;


    if @@Banktransacties_LogVerboseBits & 4096 <> 0 then
      call trace(@Text);
    end if;

    if @@Banktransacties_LogVerboseBits & 8192 <> 0 then
      call Banktransacties_LogToGebruikersLog(@Text, '', if @Verboselevel = 1 /*Error*/ then 1 /*fout*/ else 0 /*melding*/ endif);
    end if;

  end if;

  //@@Banktransacties_LogVerboseBits:
  // Bit  0 (   1) = Level 1: Error
  // Bit  1 (   2) = Level 2: Info
  // Bit  2 (   4) = Level 3: Info detail
  // Bit  3 (   8) = Level 4: Info uitgebriede detail
  // Bit  4 (  16) = Level 5: SQL-resultaat
  // Bit  5 (  32) = Level 6: Transactieinfo (t.b.v. reproduceren met zelfde gegevens)
  // Bit  6 (  64) = Level 7: namen van regels + criteria
  // Bit  7 ( 128) = Level 8: Tijd tussen begin- en einde uitvoeren query
  // Bit 10 (1024) = Log to file
  // Bit 11 (2048) = Zet matchregelnaam in de transactieomschrijving
  // Bit 12 (4096) = Log to console
  // Bit 13 (8192) = Log to gebruikerslogboek
  // Bit 14 (16384)= Log to http listener on 0.0.0.0:8080/log
  //
  // Minimum verbose = 0 (niks)
  // Gebruikelijk voor development: 2048+1024+128+64+32+16+1 vul regel in de transactie en log regels+criteria en SQL met transactiedetail + fouten
  // Gebruikelijk voor debug: 1024+128+64+32+16+1 alleen namen van regels+criteria en SQL met transactiedetail + fouten
  // Gebruikelijk voor uitlevering: 8193 (errors loggen in gebruikerslogboek)
  // Misschien later nog een bit om fouten op te slaan in het gebruikerslogboek?
  //update tabregistry set contents=1024+128+64+32+16+1 where regkey = 'BanktransactiesVerwerken_Loglevel';

  // Ongedaan maken van de gevulde RARomschrijvingen:
  // update tabrekeningafschriftregel set raroms = substring(raroms, 1, locate(raroms+'||', '||') - 1)
end;



create or replace procedure Banktransacties_LogToGebruikersLog(
  in @Foutmelding long nvarchar,
  in @Detail long nvarchar default '',
  in @Niveau smallint default 0 // 0 = info, 1 = fout
)
begin
  declare @FoutLogGid integer;
  declare @LogSoort smallint;
  declare @Melding long nvarchar;

  //call trace('LOGGEN: ' + @Foutmelding + ' -|- ' + @Detail);
  set @LogSoort = if @Niveau = 1 then 2 /*Fout*/ else 5 /*melding*/ endif;

  if (@@Banktransacties_LogVerboseBits & 8192 /*Log to gebruikerslog*/ <> 0)
    and (   (@Niveau = 1 /*fout*/ and @@Banktransacties_LogVerboseBits & 1 /*fout*/ <> 0)
         or (@Niveau = 0 /*info*/ and @@Banktransacties_LogVerboseBits & 2 /*info*/ <> 0)) then
    if substr(@Foutmelding, 1, 11) = '//  @Having' then
      set @Foutmelding = @Foutmelding;
    end if;
    if isnull(@detail, '') = '' then
      set @Melding = @Foutmelding
    else
      set @Melding = @Foutmelding || ' - ' || /*string(now()) || ' ' ||*/ @Detail
    end if;

    begin
      select first LogGid into @FoutLogGid from tabLog where LogSoort = @LogSoort and LogOmschrijving like substr(@Foutmelding, 1, 50) || '%' order by loggid desc;
    exception when others then
      set @FoutLogGid = null;
    end;

    if @FoutLogGid is null or (@FoutLogGid <> (select max(LogGid) from tabLog where logsoort not in (0 /*inloggen*/, 1 /*uitloggen*/))) then
      insert into tabLog(LogSoort, LogAdmCode, LogBjCode, LogUserName, LogMachineName, LogOmschrijving)
        values(@LogSoort, Db_Name(), '', '', '', @Melding);
      set @FoutLogGid = @@Identity;
    else
      update tabLog set LogTimestamp = now(), LogOmschrijving = @Melding where LogGid = @FoutLogGid;
    end if;
    //Helaas, logboek kan geen stringdetails aan, daarom in 1e melding opgenomen
    //if isnull(@Detail, '') <> '' then
    //  insert into tabLogDetail(LogDetLogGid, LogDetExtraInfo)
    //  values(@FoutLogGid, string(now()) + ' ' + @Detail);
    //end if;
  end if;
end;


create or replace function Banktransacties_MatchMoetWordenVerwerkt(
  in @EigenBankrekening  nchar(34),
  in @Kwaliteit integer
)
returns smallint
begin
  /*
  Kwaliteit verwijst nu naar de vinkjes in de eigen bankrekening:
  999 = Boeking op de tussenrekening, dus altijd goed!
  100 = Betalings- of incassoopdracht
        Kan ook betrekking hebben op een betalings-/incassoregel ivm stornering
  90 = Betalingskenmerk
  80 = Bankrekening en NAW-nummer en factuurnummer en bedrag
  70 = (Bankrekening of NAW-nummer) en factuurnummer en bedrag
  60 = (Bankrekening of NAW-nummer) en factuurnummer
  50 = (Bankrekening of NAW-nummer) en bedrag
  40 = Factuurnummer en bedrag
  */
  declare @__NietAutomatischBoeken smallint = 0;
  declare @__MagAutomatischWordenGeboekt smallint = 1;

  declare @MagBoeken smallint;

    call Banktransacties_Log('//PROC: Banktransacties_MatchMoetWordenVerwerkt', 4);

  if @Kwaliteit = 999 then
    return @__MagAutomatischWordenGeboekt;
  end if;

  select
    //EbrAutomVerwerken * ACW Verwijderd, vinkje doet er niet toe, zie defect 56154
      case @Kwaliteit
        when 100 then 1 // Betalings-incassoopdracht altijd boeken
        when  90 then EbrBetalingskenmerk
        when  80 then EbrBankEnNawEnFactEnBedrag
        when  70 then EbrBankOfNawEnFactEnBedrag
        when  60 then EbrBankOfNawEnFact
        when  50 then EbrBankOfNawEnBedrag
        when  40 then EbrFactEnBedrag
      end
  into
    @MagBoeken
  from
    tabEigenBankRekening
  where
    EbrBankRekeningNummer = @EigenBankrekening;

    call Banktransacties_Log('//Kan worden verwerkt? Bankrek.=' + @EigenBankrekening + '; @Kwaliteit=' + string(@Kwaliteit)+'; @MagBoeken='+string(@MagBoeken), 3);

  if @MagBoeken = 1 then
    // Gevonden en vinkje aan, dus mag boeken
    return @__MagAutomatischWordenGeboekt;
  end if;

  // Vinkje uit of niks gevonden? Dan niet autom. boeken
  return @__NietAutomatischBoeken;
end;


create or replace procedure Banktransacties_MatViewOrganize
(
  inout @MatViewUniekNummers ROW(
          vwVoorraadaantallen             integer,
          vwBackorderAantallen            integer,
          vwVoorraadAantallenKlein        integer,
          vwBestelKopTotalen              integer,
          vwMeestRecenteOpenstaandePosten integer
        ),
  in @Action smallint, //0 = Release all, 1 = resolve, refresh the SQLs that are needed in SQL, 2 = just resolve SQLs that are needed, no refresh!
  in @Soort smallint default null,
  inout @Sql ROW(
    MatchregelName nchar(80),
    Take                        smallint,
    TakeNumber                  integer,
    TakeDistinct                smallint, // 0= Zonder distinct, 1= Met distinct
    Totalfrom long nvarchar,
    TotalFromOuterJoin long nvarchar,
    Totalwhere long nvarchar,
    TotalHaving long nvarchar,
    TotalPartitionWhere long nvarchar,
    TotalPartitionSelect long nvarchar,
    TotalPartitionOp2Fieldnames long nvarchar,
    Precondition long nvarchar
  ) default null
)
begin
  //Numbers matching the tabPooledMaterializedView.pmvSoortView
  declare @views long nvarchar = '0=vwVoorraadaantallen,1=vwBackorderAantallen,2=vwVoorraadAantallenKlein,3=vwBestelKopTotalen,4=vwMeestRecenteOpenstaandePosten';

  for Views_resolve AS CURSOR_Views_resolve CURSOR FOR
    select substring(@view, locate(@view, '=')+1) @ViewName,
           left(@view,locate(@view, '=')-1) @ViewNr
    from OPENSTRING( VALUE @views)
         WITH (@view VARCHAR(100)) OPTION ( ROW DELIMITED BY ',' delimited by '') AS dummy
    where isnull(@Soort, @ViewNr) = @ViewNr
  for read only
  do
    begin
      declare @UniekNummer nchar(20);
      declare @SqlHasView smallint = 0;
      execute immediate ('set @UniekNummer = @MatViewUniekNummers.' || @ViewName);
      if @sql is not null then
        set @SqlHasView = if (locate(@sql.Totalfrom, @ViewName) > 0) or (locate(@sql.TotalfromOuterJoin, @ViewName) > 0) then 1 else 0 endif;
      end if;
      case

        when @action in (1 /*resolve+refresh*/, 2 /*Resolve, no refresh*/) and @SqlHasView = 1 then
          if @UniekNummer is null then
            call PooledMatViewUse(@ViewNr, 1 /*create+refresh*/, @UniekNummer);
            execute immediate ('set @MatViewUniekNummers.' || @ViewName || ' = @UniekNummer');
          else if @action = 1 then
              call PooledMatViewRefresh(@ViewNr, @UniekNummer);
            end if;
          end if;
          set @sql.Totalfrom          = replace(@sql.Totalfrom,          @ViewName, @ViewName || @UniekNummer);
          set @sql.TotalFromOuterJoin = replace(@sql.TotalFromOuterJoin, @ViewName, @ViewName || @UniekNummer);
          // Het is nu mogelijk dat de view 2x het nummer bevat, dus dat weer terugzetten
          set @sql.Totalfrom          = replace(@sql.Totalfrom,          @ViewName || @UniekNummer || @UniekNummer, @ViewName || @UniekNummer);
          set @sql.TotalFromOuterJoin = replace(@sql.TotalFromOuterJoin, @ViewName || @UniekNummer || @UniekNummer, @ViewName || @UniekNummer);

        when @action = 0 /*Release*/ and  @UniekNummer is not null then
          call PooledMatViewRelease(@UniekNummer);
          execute immediate ('set @MatViewUniekNummers.' || @ViewName || ' = null');

      end case;
    end;
  end for;


end;

create or replace procedure Banktransacties_RepairFatalErrors()
begin
  //StoredProc (via event) om symptomen van uitgeknalde BanktransactiesVerwerken te bestrijden
  //- locks van niet-meer-bestaande connecties
  //  - boekingsgang (alleen voor juiste bron)
  //  - pooled mat view
  //  - era-bestanden
  //  - banktransactiesverwerken
  //- boekingsgangen wel in gebruik, maar geen lock (voor juiste bron)
  //- mat.views die geen pooled-record hebben: verwijderen
  declare @key nchar(20);

  // Boekingsgangen wel in gebruik maar zonder lock een lock geven (op een niet-bestaande connectie, zodat die straks wordt opgeruimd)
  // Vorlopig overgeslagen, eventueel zou dat nog via AdminOnderhoud_BoekingsgangRecreateLocks kunnen, maar is traag

  // Opruimen van (een beperkt setje aan) locks
  if LocksWithoutConnectionExist() = 1 then
    begin
      // Er zijn locks zonder connecties, dus die opruimen als het betreft:
      // - boekingsgang van bronsoort 39 (verwerken banktransacties-automatisch)
      // - pooled mat view van soort 4 (vwMeestRecenteOpenstaandePosten)
      // - era-bestand
      // - lock BanktransactiesVerwerken (algemene lock)

      declare @listBG long nvarchar = '';
      declare @listMV long nvarchar = '';
      declare @listRak long nvarchar = '';

      for @LocksCursor AS CURSOR_Locks CURSOR FOR
        select qlockGid @qlockGid, qlockPkey @qlockPkey, qlockSoort @qlockSoort, qLockTableName @qLockTableName
        from LocksWithoutConnection('')
      for read only do
        // Boekingsgang (boekingsgang uit gebruik halen)
        if @qLockTableName = 'tabboekingsgang' then
          set @key = substring(@qlockPkey, locate(@qlockPkey, '=')+ 1);
          if isnumeric(@key) = 1
            and (   exists(select first 1 from tabBoekingsgang where BoekgangGid = @key and BoekGangBronId = 39 /*Verwerken banktransacties(automatisch)*/)
                 or not exists(select first 1 from tabBoekingsgang where BoekgangGid = @key)
            ) then
            call BoekingsgangVerwerkenSpeciaal(@qlockGid);
            delete qtablock where qlockgid = @qlockGid;
            set @listBG = @listBG || (if @listBG <> '' then ', ' endif) || @key;
          end if;
        end if;

        // Pooled materialized view (mat.view vrijgeven en lock verwijderen)
        if @qLockTableName = 'tabPooledMaterializedView' then
          set @key = substring(@qlockPkey, locate(@qlockPkey, '=')+ 1);
          if isnumeric(@key) = 1
            and (   exists(select first 1 from tabPooledMaterializedView where pmvGid = @key and pmvSoortView = 4 /*vwMeestRecenteOpenstaandePosten*/)
                 or not exists(select first 1 from tabPooledMaterializedView where pmvGid = @key)
                ) then
            update tabPooledMaterializedView set pmvInGebruik = 0 where pmvGid = @key;
            delete qtablock where qlockgid = @qlockGid;
            set @listMV = @listMV || (if @listMV <> '' then ', ' endif) || @key;
          end if;
        end if;

        // ERA-bestand (alleen lock verwijderen))
        if @qLockTableName = 'tabRekeningafschriftKop' then
          set @key = @qlockPkey;
          if isnumeric(@key) = 1 then //and exists(select first 1 from tabRekeningafschriftKop where RakGid = @key) then
            delete qtablock where qlockgid = @qlockGid;
            set @listRak = @listRak || (if @listRak <> '' then ', ' endif) || @key;
          end if;
        end if;

        // BanktransactiesVerwerken (alleen lock verwijderen)
        if @qLockTableName = 'BanktransactiesVerwerken' then
            delete qtablock where qlockgid = @qlockGid;
            insert into tablog (LogSoort, LogAdmCode, LogUserName, LogMachineName, LogOmschrijving, LogTimeStamp)
              select 6, db_property('alias'), 'Quadrant', '', 'BTR: Automatisch banktransacties verwerken vrijgegeven', now();
        end if;
      end for;

      // Log result
      if @listBG <> '' or @listMV <> '' or @listRak <> '' then
        insert into tablog (LogSoort, LogAdmCode, LogUserName, LogMachineName, LogOmschrijving, LogTimeStamp)
          select 6, db_property('alias'), 'Quadrant', '',
            'BTR: Locks vrijgegeven:' ||
            if @listBG <> '' then ' BG: ' || @listBG endif ||
            if @listMV <> '' then ' MatView: ' || @listMV endif ||
            if @listRak <> '' then ' Rak: ' || @listRak endif,
            now();
      end if;
    end;
  end if;

  // Materialized views wel in gebruik maar zonder lock uit gebruik halen
  update tabPooledMaterializedView
  set pmvInGebruik = 0
  where pmvInGebruik = 1 and pmvSoortView = 4 /*vwMeestRecenteOpenstaandePosten*/
     and not exists(select first 1 from qtablock where qLockTableName = 'tabPooledMaterializedView' and qlockPKey = 'pmvGid='||pmvGid);
  if @@rowcount > 0 then
    insert into tablog (LogSoort, LogAdmCode, LogUserName, LogMachineName, LogOmschrijving, LogTimeStamp)
      select 6, db_property('alias'), 'Quadrant', '', 'BTR: MatView records vrijgegeven, aantal: ' || @@rowcount, now();
  end if;

end;


create or replace procedure Banktransacties_SplitText(
  in @text long nvarchar
)
begin
  // Splits de omschrijving in losse delen:
  // - Tekst doorlopen met CrLf EN waarbij de CrLf (of Cr of Lf) zijn verwijderd
  // - Getallen, waarbij de punt wordt genegeerd: 123.456.789AB -> 123456789
  // - Bankrekeningen (Gaat in King5 nog fout!): XX11XXXX<getal>ab -> Als IBAN, dan onthouden
  // - Alle teksten splitsen obv scheidingstekens:
  //   Spatie, Deelteken, Punt, Komma, Minteken, Sterretje, Dubbele punt, Cr, Lf
  //   Alleen opnemen als lengte van gevonden deel kleiner of gelijk aan 40 posities is
  declare @StartPos integer = 1;
  declare @TextLength integer = length(@text) + 1; //1 erbij ivm delimiter die we straks toevoegen
  declare @char nchar(1);
  declare @number nchar(41) = '';
  declare @Extranumber nchar(41) = '';
  declare @word nchar(81) = '';
  declare @partialword nchar(81) = '';
  declare @DELIMITERS nchar(40) = ' /.,;-*:\x0d\x0a\x09';
  declare @OPTIONALDELIMITERS nchar(40) = '_'; // Makes separate words, but also joined. so ABCD_EFGH will created words ABCD, EFGH and ABCD_EFGH
  declare @ALFA nchar(26) = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  declare @NUMERIC nchar(10) = '1234567890';
  declare @IBAN nchar(40) = '';
  declare @ALLDELIMITERS nchar(100) = @DELIMITERS || @OPTIONALDELIMITERS;
  declare @IsDelimiter integer;
  declare @IsOptionalDelimiter integer;

  declare local temporary table tmpSplittedText(
    tmpText nchar(40),
    primary key (tmpText)
  ) on commit preserve rows;
  //create unique index idx_tmpSplittedText on tmpSplittedText(tmpText);

  set @text = @text + ' ;'; // Eindigt op delimiter, zodat laatste deel nog wordt meegenomen, GEEN punt of spatie ivm volgende controles!

  while @StartPos <= @TextLength loop
    set @char = substring(@text, @StartPos, 1);

    // Toevoegen aan getal?
    case
      when locate(@NUMERIC, @char) > 0 then
        set @number = @number + @char;
      when @char <> '.' then // De punt mag in een nummer zitten, die negeren we gewoon
        // Number toevoegen?
        if @number <> '' and length(@number) between 5 and 40 then
          //call Banktransacties_Log('Toevoegen number: ' + @number, 4);
          insert into tmpSplittedText (tmpText) on existing skip values(@number);
          // Als het een geldig getal met controlecijfer is, dan het getal daarbinnen ook opnemen
          insert into tmpSplittedText (tmpText) on existing skip
            select LeesNummerUitNederlandsBetalingskenmerk(@number) @InnerNumber where @InnerNumber is not null;
        end if;
        set @Extranumber = @Extranumber + @number; // Nummer toevoegen aan voorgaande, zodat 123 456 789 uiteindelijk 123456789 wordt
        if @char <> ' ' then
          if @Extranumber <> '' then
            if length(@Extranumber) between 5 and 40 then
              //call Banktransacties_Log('Toevoegen number: ' + @number, 4);
              insert into tmpSplittedText (tmpText) on existing skip values(@Extranumber);
              // Als het een geldig getal met controlecijfer is, dan het getal daarbinnen ook opnemen
              insert into tmpSplittedText (tmpText) on existing skip
                select LeesNummerUitNederlandsBetalingskenmerk(@Extranumber) @InnerNumber where @InnerNumber is not null;
            end if;
            set @Extranumber = '';
          end if;
        end if;
        set @number = '';
      else // char = '.'
        if @Extranumber <> '' then
          if length(@Extranumber) between 5 and 40 then
            //call Banktransacties_Log('Toevoegen number: ' + @number, 4);
            insert into tmpSplittedText (tmpText) on existing skip values(@Extranumber);
            // Als het een geldig getal met controlecijfer is, dan het getal daarbinnen ook opnemen
            insert into tmpSplittedText (tmpText) on existing skip
              select LeesNummerUitNederlandsBetalingskenmerk(@Extranumber) @InnerNumber where @InnerNumber is not null;
          end if;
        end if;

    end case;

    // Toevoegen aan woord?
    set @IsDelimiter = locate(@DELIMITERS, @char);
    set @IsOptionalDelimiter = locate(@OPTIONALDELIMITERS, @char);


    // Partial word?
    if @IsOptionalDelimiter > 0 then
      // optional word delimiter, so partial word is empty
      if (length(@partialword) between 5 and 40) and @IsDelimiter <= 0 then
        // Also insert partial word
        insert into tmpSplittedText (tmpText) on existing skip values(@partialword);
      end if;
      set @partialword = '';
    end if;

    // Whole word?
    if @IsDelimiter > 0 then
      // Word delimiter, so insert both partial word and word and go for next word
      if length(@word) between 5 and 40 then
        //call Banktransacties_Log('Toevoegen word: ' + @word, 4);
        insert into tmpSplittedText (tmpText) on existing skip values(@word);
      end if;
      if @partialword <> @word and (length(@partialword) between 5 and 40) then
        // Also insert partial word
        insert into tmpSplittedText (tmpText) on existing skip values(@partialword);
      end if;
      set @word = '';
      set @partialword = '';
    end if;

    // No delimiter, so add to (partial)words
    if @IsDelimiter <= 0 then
      set @word = @word + @char;
    end if;
    if @IsDelimiter + @IsOptionalDelimiter <= 0 then
      set @partialword = @partialword + @char;
    end if;

    // Toevoegen aan IBAN?
    // kenmerk IBAN: 2 alfatekens, dan 2 cijfers, dan restant totdat controleberekening klopt
    // Wellicht de spatie en de punt negeren?
    case
      when @char = '.' then
        // Negeer de punt, want die kan in een (niet geldige) IBAN zitten
      when locate(@ALLDELIMITERS, @char) > 0 and length(@IBAN) > 0 then
        // IBAN controleren en indien goed, dan toevoegen
        if length(@IBAN) > 10 then
          if IsValidIBAN(@IBAN) = 1 then
            //call Banktransacties_Log('Toevoegen IBAN: ' + @IBAN, 4);
            insert into tmpSplittedText (tmpText) on existing skip values(@IBAN);
          end if;
        end if;

        set @IBAN = ''; // Gevonden of niet, iig met een nieuwe IBAN beginnen
      when locate(@ALFA, @char) > 0 and length(@IBAN) <= 2 then
        case length(@IBAN)
          when 2 then
            // alfa op positie 3, dus niet goed! 1 opschuiven
            set @IBAN = substring(@IBAN, 2, 1) + @char;
          when 1 then
            // alfa in 1e 2 posities is goed
            set @IBAN = @IBAN + @char;
          when 0 then
            // alfa in 1e 2 posities is goed
            set @IBAN = @IBAN + @char;
        end case;
      else
        if length(@IBAN) = 40 then
          set @IBAN = '';
        else
          // Gewoon toevoegen, we zien wel of het goed is
          set @IBAN = @IBAN + @char;
          if length(@IBAN) > 10 then
            if IsValidIBAN(@IBAN) = 1 then
              //call Banktransacties_Log('Toevoegen IBAN: ' + @IBAN, 4);
              insert into tmpSplittedText (tmpText) on existing skip values(@IBAN);
              set @IBAN = ''; // Gevonden, dus weer overnieuw beginnen
            end if;
          end if;
        end if;
    end case;


      //call Banktransacties_Log(string(@StartPos) + '; @number=|' + @number + '| @word=|' + @word + '| @IBAN=|'+@IBAN+'|', 4);
    //call Banktransacties_Log(string(@StartPos) + '; @IBAN=|'+@IBAN+'|', 4);
    set @StartPos = @StartPos + 1;
  end loop;

  if @Extranumber <> '' then
    if length(@Extranumber) between 5 and 40 then
      //call Banktransacties_Log('Toevoegen number: ' + @number, 4);
      insert into tmpSplittedText (tmpText) on existing skip values(@Extranumber);
      // Als het een geldig getal met controlecijfer is, dan het getal daarbinnen ook opnemen
      insert into tmpSplittedText (tmpText) on existing skip
        select LeesNummerUitNederlandsBetalingskenmerk(@Extranumber) @InnerNumber where @InnerNumber is not null;
    end if;
  end if;

  select tmpText WordPartOfText from tmpSplittedText order by tmpText;
end;


create or replace procedure Banktransacties_Unlock(
  in @Rakgid integer)
begin
  if @RakGid is not null then
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabRekeningAfschriftKop', @RakGid);
  end if;
end;


create or replace procedure Banktransacties_VerwerkCriteriaPerMatchregel(
  in    @BtmrGid integer,
  out   @Result integer,
  inout  @Sql ROW(
        MatchregelName              nchar(80),
        Take                        smallint,
        TakeNumber                  integer,
        TakeDistinct                smallint, // 0= Zonder distinct, 1= Met distinct
        Totalfrom                   long nvarchar,
        TotalFromOuterJoin          long nvarchar,
        Totalwhere                  long nvarchar,
        TotalHaving                 long nvarchar,
        TotalPartitionWhere         long nvarchar,
        TotalPartitionSelect        long nvarchar,
        TotalPartitionOp2Fieldnames long nvarchar,
        Precondition long nvarchar
      ),
  in    @AndOrVanDeelregel smallint default null,
  in    @BeginhaakjesVanDeelregel smallint default 0,
  in    @EindhaakjesVanDeelregel  smallint default 0,
  in    @Levelcounter smallint default 1
)
begin
  declare @__Result_OK smallint = 0;
  declare @__Result_CircularReferenceInRegels smallint = 10;
  declare @__Tabsize smallint = 4;
  declare @IndentWhere smallint;
  declare @IndentPartitionedWhere smallint;

  declare @from long nvarchar;
  declare @FromOuterJoin long nvarchar;
  declare @where long nvarchar;
  declare @Having long nvarchar;
  declare @PartitionWhere long nvarchar;
  declare @partitionSelect long nvarchar;
  declare @PartitionOp2Fieldname long nvarchar;
  declare @hlp long nvarchar;

  set @IndentWhere = @LevelCounter * @__Tabsize;
  set @IndentPartitionedWhere = @LevelCounter * @__Tabsize;

  set @Result = @__Result_OK;
  for @@CriteriaPerMatchregel AS CURSOR_CriteriaPerMatchregel CURSOR FOR
    select BtcpmrBtmcGid @BtcpmrBtmcGid,
           BtcpmrBtmrGidDeelregel @BtcpmrBtmrGidDeelregel,
           BtcpmrBeginHaakjes + if BtcpmrVolgorde = 1 then @BeginhaakjesVanDeelregel else 0 endif @BtcpmrBeginHaakjes,
           BtcpmrEindHaakjes + if BtcpmrVolgorde = (select max(b.BtcpmrVolgorde) from tabBanktransacties_CriteriaPerMatchregel b where b.BtcpmrBtmrGid = @BtmrGid) then @EindhaakjesVanDeelregel else 0 endif @BtcpmrEindHaakjes,
           if BtcpmrVolgorde = 1 then isnull(@AndOrVanDeelregel, BtcpmrAndOr) else BtcpmrAndOr endif @BtcpmrAndOr
    from
      tabBanktransacties_CriteriaPerMatchregel
    where BtcpmrBtmrGid = @BtmrGid
    order by BtcpmrVolgorde
  for read only
  do
    case // Soorten criteriaPerMatchregel Verwerken
      when @BtcpmrBtmcGid is not null then
        call Banktransacties_VerwerkCriterium(
          @BtcpmrBtmcGid, @from, @FromOuterJoin, @where, @Having,
          @PartitionWhere, @partitionSelect, @PartitionOp2Fieldname
        );

        // ********************************************
        // *** TOEVOEGEN AAN BESTAANDE SQL-CLAUSULE ***
        // ********************************************
        if @from <> '' then
          set @Sql.Totalfrom = JoinList(@Sql.Totalfrom, @from);
        end if;

        if @FromOuterJoin <> '' then
          set @Sql.TotalFromOuterJoin = @Sql.TotalFromOuterJoin + @FromOuterJoin
        end if;

        if @where <> '' then
          set @hlp = @Sql.Totalwhere;
          call Banktransacties_VerwerkCriteriaPerMatchregel_ResolveWhereClause(@LevelCounter, @where, @BtcpmrAndOr, @BtcpmrBeginHaakjes, @BtcpmrEindHaakjes, @IndentWhere, @hlp);
          set @Sql.Totalwhere = @hlp;
        end if;

        if @having <> '' then
          if @Sql.TotalHaving <> '' then
            set @Sql.TotalHaving = @Sql.TotalHaving + '\n  ' + if @BtcpmrAndOr = 0 then 'and ' else 'or ' endif;
          else
            set @Sql.TotalHaving = '\n      ';
          end if;
          set @Sql.TotalHaving = @Sql.TotalHaving + repeat('(', @BtcpmrBeginHaakjes + 1) + @having + repeat(')', @BtcpmrEindHaakjes + 1);
        end if;

        if @PartitionWhere <> '' then
          set @hlp = @Sql.TotalPartitionWhere;
          call Banktransacties_VerwerkCriteriaPerMatchregel_ResolveWhereClause(@LevelCounter, @PartitionWhere, @BtcpmrAndOr, @BtcpmrBeginHaakjes, @BtcpmrEindHaakjes, @IndentPartitionedWhere, @hlp);
          set @Sql.TotalPartitionWhere = @hlp;
        end if;
        if @partitionSelect <> '' then
          set @Sql.TotalPartitionSelect = @Sql.TotalPartitionSelect + if @Sql.TotalPartitionSelect = '' then '' else ', ' endif + @partitionSelect;
        end if;
        if @PartitionOp2Fieldname <> '' then
          set @Sql.TotalPartitionOp2Fieldnames = JoinList(@Sql.TotalPartitionOp2Fieldnames, @PartitionOp2Fieldname);
        end if;

      when @BtcpmrBtmrGidDeelregel is not null then

        if @Levelcounter > 10 then
          set @result = @__Result_CircularReferenceInRegels;
          call Banktransacties_Log('ERROR: Circular reference found!', 1);
          return;
        else
          call Banktransacties_VerwerkCriteriaPerMatchregel(
            @BtcpmrBtmrGidDeelregel,
            @Result,
            @Sql,
            @BtcpmrAndOr, // Zodat de deelregel op de juiste manier eraan wordt geplakt
            @BtcpmrBeginHaakjes,
            @BtcpmrEindHaakjes,
            @Levelcounter + 1
          );
        end if;
    end case;
  end for;
end;

create or replace procedure Banktransacties_VerwerkCriteriaPerMatchregel_ResolveWhereClause(
  in @LevelCounter integer,
  in @where long nvarchar,
  in @BtcpmrAndOr smallint,
  in @BtcpmrBeginHaakjes integer,
  in @BtcpmrEindHaakjes integer,
  inout @Indent integer,
  inout @TotalWhere long nvarchar
)
begin
  declare @__Tabsize smallint = 4;

  if @TotalWhere <> '' then
    set @TotalWhere = @TotalWhere + '\n' + repeat(' ', @Indent - 2*@__Tabsize) + if @BtcpmrAndOr = 0 then 'and ' else 'or  ' endif;
  end if;
  set @TotalWhere = @TotalWhere + '\n' + repeat(' ', @Indent - @__Tabsize);
  set @TotalWhere = @TotalWhere + repeat('(\n' + repeat(' ', @Indent), @BtcpmrBeginHaakjes);
  set @Indent = @Indent + @BtcpmrBeginHaakjes * @__Tabsize;
  set @TotalWhere = @TotalWhere + '(' + @where + ')';
  set @TotalWhere = @TotalWhere + repeat('\n' + + repeat(' ', @Indent - @__Tabsize) + ')', @BtcpmrEindHaakjes);
  set @Indent = @Indent - @BtcpmrEindHaakjes * @__Tabsize;
  if @Indent < @LevelCounter * @__Tabsize then
    set @TotalWhere = @TotalWhere + '/*** NUMBER OF BRACKETS MIGHT BE INCORRECT! ***/';
    set @Indent = @LevelCounter * @__Tabsize;
  end if;
end;



create or replace procedure Banktransacties_VerwerkCriterium(
  in  @BtmcGid             integer,
  out @from           long nvarchar,
  out @FromOuterJoin  long nvarchar,
  out @where          long nvarchar,
  out @Having         long nvarchar,
  out @PartitionWhere long nvarchar,
  out @partitionSelect long nvarchar,
  out @PartitionOp2Fieldname long nvarchar
)
begin
  declare @CriteriumNaam nchar(80);
  declare @SqlPlace      smallint;
  declare @Op1Type       smallint;
  declare @Op1Value      long nvarchar;
  declare @Operator      smallint;
  declare @Op2Type       smallint;
  declare @Op2Value      long nvarchar;

  declare @_from     long nvarchar;
  declare @_Operator long nvarchar;
  declare @_where  long nvarchar;
  declare @_having long nvarchar;
  declare @_OperandPrefix nchar(10);  // null = Geen prefix
  declare @_OperandPostfix nchar(10); // null = Geen postfix
  declare @_swapOperands smallint = 0;
  declare @_Operand1 long nvarchar;
  declare @_Operand2 long nvarchar;
  declare @Operand1Name nchar(40);
  declare @Operand2Name nchar(40);
  declare @PartitionOver long nvarchar;
  declare @SkipInInnerWhere integer;

  select
    BtmcNaam,
    BtmcSqlPlace,
    BtmcOperand1Name, BtmcOperand1Type, BtmcOperand1Value,
    BtmcOperator,
    BtmcOperand2Name, BtmcOperand2Type, BtmcOperand2Value,
    BtmcFrom,
    BtmcPartitionOver,
    BtmcIsBuitenPartition
  into
    @CriteriumNaam,
    @SqlPlace,
    @Operand1Name, @Op1Type, @Op1Value,
    @Operator,
    @Operand2Name, @Op2Type, @Op2Value,
    @from,
    @PartitionOver,
    @SkipInInnerWhere
  from
    tabBanktransacties_Criterium
  where BtmcGid = @BtmcGid;

    call Banktransacties_Log('//Criterium ''' + @CriteriumNaam + '''', 7);
    call Banktransacties_Log(
      '//IN (via Select):\n' ||
      '//  @SqlPlace     = ' || string(@SqlPlace)    || '\n' ||
      '//  @Operand1Name = ' || string(@Operand1Name)|| '\n' ||
      '//  @Op1Type      = ' || string(@Op1Type)     || '\n' ||
      '//  @Op1Value     = ' || string(@Op1Value)    || '\n' ||
      '//  @Operator     = ' || string(@Operator)    || '\n' ||
      '//  @Operand2Name = ' || string(@Operand2Name)|| '\n' ||
      '//  @Op2Type      = ' || string(@Op2Type)     || '\n' ||
      '//  @Op2Value     = ' || string(@Op2Value)
    , 4);


  case @Operator
  when 1 /*is gelijk aan*/ then
    set @_Operator = ' = ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 2 /*is ongelijk aan*/ then
    set @_Operator = ' <> ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 3 /*is groter dan*/ then
    set @_Operator = ' < ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 4 /*is kleiner dan*/ then
    set @_Operator = ' > ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 5 /*is groter of gelijk aan*/ then
    set @_Operator = ' >= ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 6 /*is kleiner of gelijk aan*/ then
    set @_Operator = ' <= ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 7 /*bevat*/ then
    set @_Operator = ' like ';
    set @_OperandPrefix = '%';
    set @_OperandPostfix = '%';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 8 /*bevat niet*/ then
    set @_Operator = ' not like ';
    set @_OperandPrefix = '%';
    set @_OperandPostfix = '%';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 9 /*bevat (met scheidingsteken)*/ then
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, null, null, @_Operand2);
    set @_Operator = 'exists(select first 1 from banktransacties_SplitText(' + @_Operand1 + ') where WordPartOfText = ' + @_Operand2 + ')';
    set @_Operand1 = '';
    set @_Operand2 = '';

  when 10 /*bevat niet (met scheidingsteken)*/ then
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, null, null, @_Operand2);
    set @_Operator = 'not exists(select first 1 from banktransacties_SplitText(' + @_Operand1 + ') where WordPartOfText = ' + @_Operand2 + ')';
    set @_Operand1 = '';
    set @_Operand2 = '';

  when 11 /*is leeg*/ then
    set @_Operator = ' is null ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 12 /*is niet leeg*/ then
    set @_Operator = ' is not null ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);

  when 13 /*in set*/ then
    set @_Operator = ' in ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);
    // Eventueel de set nog voorzien van haakjes
    if @_Operand2 not like '(%)' then
      set @_Operand2 = '(' + @_Operand2 + ')';
    end if;

  when 14 /*not in set*/ then
    set @_Operator = ' not in ';
    call Banktransacties_calcOperand(@Op1Type, @Op1Value, null, null, @_Operand1);
    call Banktransacties_calcOperand(@Op2Type, @Op2Value, @_OperandPrefix, @_OperandPostfix, @_Operand2);
    // Eventueel de set nog voorzien van haakjes
    if @_Operand2 not like '(%)' then
      set @_Operand2 = '(' + @_Operand2 + ')';
    end if;

  end case;


  // een berekening moet altijd een naam hebben
  if @Op1Type = 5 /*berekening*/ and @Operand1Name = '' then
    begin
      declare @nr integer;
      call RandomNumber2(@nr);
      set @Operand1Name = 'calc' + string(@nr);
    end;
  end if;
  if @Op2Type = 5 /*berekening*/ and @Operand2Name = '' then
    begin
      declare @nr integer;
      call RandomNumber2(@nr);
      set @Operand2Name = 'calc' + string(@nr);
    end;
  end if;

  // de where clausule opbouwen
  case @SqlPlace
    when 0 /*Where*/ then
      if @SkipInInnerWhere = 1 then
        set @PartitionWhere = if @Operand1Name = '' then @_Operand1 else @Operand1Name endif + @_Operator + @_Operand2;
        set @partitionSelect = '\n' + @_Operand1 + if @_Operand1 = @Operand1Name or @Operand1Name ='' then '' else ' AS ' + @Operand1Name endif;
      else
        set @where = @_Operand1 + @_Operator + @_Operand2;
      end if;

    when 1 /*Having */ then
      set @having = @_Operand1 + @_Operator + @_Operand2;

    when 2 /*Partition*/ then
      set @partitionSelect = '\n' + @_Operand1 + ' over (partition by ' + @PartitionOver + ') AS ' + @Operand1Name;
      case
        when @Operand2Name <> '' then
          set @partitionSelect = @partitionSelect + ',\n' + @_Operand2 + ' AS '  + @Operand2Name;
        when @Op2Type in (4 /*veld uit database*/, 5 /*berekening*/) then
          set @partitionSelect = @partitionSelect + ',\n' + @_Operand2
      end; //Anders is het een constante of uit de transactie, dus gelijk in de outer where opnemen in plaats van de inner
      set @PartitionWhere = @Operand1Name + @_Operator + if @Operand2Name = '' then @_Operand2 else @Operand2Name endif;
      set @PartitionOp2Fieldname = @Operand2Name; //TODO Is deze @PartitionOp2Fieldname nodig?
    when 3 /*outer-join*/ then
      set @FromOuterJoin = ' left outer join ' + @from + ' on (' + @_Operand1 + @_Operator + @_Operand2 + ')';
      set @from = '';
  end case;

    call Banktransacties_Log(
      '//OUT:\n' ||
      '//  @from                  = ' || @from                  ||
      '//  @FromOuterJoin         = ' || @FromOuterJoin         ||
      '//  @where                 = ' || @where                 ||
      '//  @Having                = ' || @Having                ||
      '//  @PartitionWhere        = ' || @PartitionWhere        ||
      '//  @partitionSelect       = ' || @partitionSelect       ||
      '//  @PartitionOp2Fieldname = ' || @PartitionOp2Fieldname
    , 4);


end;


/*
begin
  declare @Totalfrom long nvarchar = '';
  declare @Totalwhere long nvarchar = '';
  declare @Totalhaving long nvarchar = '';

  call Banktransacties_VerwerkCriterium(
  0, // Where-clausule
  1, //@Operand1Type        smallint, // 1 = Transactieveld, 2 = waarde, 3= veld uit database, 4=berekening
  '@Transactieveld', //@Operand1Value
  1, //@Operator            integer, // Is, Bevat,
  2, //@Operand2Type
  'Waarde', //@Operand2Value
  '', //@_from
  @Totalfrom,
  @Totalwhere,
  @Totalhaving
  );
  select @Totalfrom, @Totalwhere, @Totalhaving;

end;
