create or replace procedure Banktransacties_VerwerkGevondenBetOpdr(
  in @JpGid integer,
  in @RksgidTegenrek integer,
  in @RksgidBetalingsverschil integer,
  in @Rargid integer,
  in @Boekdatum date,
  in @BetKopId integer,
  in @BatchNummer integer,
  in @Omschrijving long nvarchar,
  out @IsCreditGeboekt smallint,
  out @GeboektBedrag numeric(15,2),
  out @result smallint //0 = OK, 1 = LOck niet gelukt
)
begin
  declare @BjGid integer;
  declare @PerNr integer;
  declare @TeBoekenBedragVanFactuurInBasisVal numeric(15,2);
  declare @TeBoekenBedragVanFactuurInValOsp numeric(15,2);
  declare @TeBoekenBedragVerschilInBasisVal numeric(15,2);
  declare @JrGid integer;

  declare @__Result_OK             smallint = 0;
  declare @__Result_LockNietGelukt smallint = 1;

    call Banktransacties_Log('//Verwerk gevonden betalingsopdracht; @BetKopId='+string(@BetKopId)+'; @BatchNummer='+string(@BatchNummer), 3);

  set @result = @__Result_OK;

  set @IsCreditGeboekt = 0; // Een betaling van crediteur altijd debet

  set @GeboektBedrag = 0; // Wordt hieronder berekend

  // Probeer te locken
  begin
    declare @LockIsGelukt smallint;
    call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'tabBetalingKop', @BetKopId, 10 /*seconden*/, @LockIsGelukt);
    if @LockIsGelukt = 0 then
      set @result = @__Result_LockNietGelukt;
      return;
    end if;
  end;

  // Journaalregels aanmaken
  FOR @@FORLOOP_Regels AS @@CURSOR_Regels CURSOR FOR
    select
      BetRglGid @BetRglGid,
      BetVerzGID @BetVerzGID,
      if BetRglIsVerzameld = 0 then BetRglFactuurNummer else BetVerzFactuurnummer endif @FactuurNummer,
      OspFactuurDatum @Factuurdatum,
      OspVervalDatum @Vervaldatum,
      if BetRglIsVerzameld = 0 then BetRglTeBetalen else BetVerzTeBetalen endif @TeBetalenInValOpdracht,
      if BetRglIsVerzameld = 0 then BetRglFactuurNummer_Lengte else BetVerzFactuurnummer_Lengte endif @FactuurNummer_Lengte,
      if BetRglIsVerzameld = 0 then BetRglTeBetalenInValOsp else BetVerzTeBetalenInValOsp endif @BedragInValOsp, /*TODO Corrigeren voor bet.verschil?*/
      //if BetRglIsVerzameld = 0 then BetRglTeBetalenInValDgb else
      BetRglValNummer @ValNummer,
      BetRglRksGid @RksGid,
      if BetRglIsVerzameld = 0 then BetRglVerschilAfboeken else BetVerzVerschilAfboeken endif @IsVerschilAfboeken,
      if BetRglIsVerzameld = 0 then BetRglVerschilAfboekenBedragInValOsp else BetVerzVerschilAfboekenBedragInValOsp endif @TeBoekenBedragVerschilInOspVal,
      if BetRglIsVerzameld = 0 then BetRglBetKenmerk else BetVerzBetKenmerk endif @Betalingskenmerk
    from
      tabBetalingKop
      inner join tabBetalingRegel on BetRglBetKopId = BetKopId
      left outer join tabBetalingVerzameld on BetVerzBetRglGid = BetRglGid
      inner join tabOpenstaandePost on (OspRksGid = @RksGid and OspFactuurnummer_Lengte = @FactuurNummer_Lengte and OspFactuurNummer = @FactuurNummer )
      inner join vwMeestRecenteOpenstaandePosten on calcOspGid = OspGid
    where
      BetKopId = @BetKopId
      and BetRglBatchNr = @BatchNummer
      and BetRglStatus = 1 /*Opdracht*/
    order by
      BetRglRksGid, BetVerzBetRglGid
    for read only
  do

    //Als @IsVerschilAfboeken=0 dan alleen het bedrag volgens de opdrachtregel boeken op de factuur
    //Als @IsVerschilAfboeken=1 dan TeBetalen+VerschilBedrag afboeken en hulprekening voor verschilbedrag, zelfde boekzijde, teken omkeren

    // Bepaal of we een verschilbedrag als betalingsverschil moeten boeken
    if @IsVerschilAfboeken = 0 then
      set @TeBoekenBedragVerschilInOspVal = 0;
      set @TeBoekenBedragVanFactuurInValOsp = @BedragInValOsp;
    else
      set @TeBoekenBedragVanFactuurInValOsp = @BedragInValOsp + @TeBoekenBedragVerschilInOspVal;
    end if;


    // Bereken bedragen naar basisvaluta
    if @Valnummer = @@Basisvalutanummer then
      set @TeBoekenBedragVanFactuurInBasisVal = @TeBoekenBedragVanFactuurInValOsp;
      set @TeBoekenBedragVerschilInBasisVal = @TeBoekenBedragVerschilInOspVal;
    else
      // Andere valuta, dus juiste boekjaar+periode opvragen tbv omrekenen
      if @BjGid is null then
        select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
      end if;
      set @TeBoekenBedragVanFactuurInBasisVal = ValutaOmrekenen(@Valnummer, @BedragInValOsp, @@BasisValutaNummer, @BjGid, @PerNr, 2);
      if @TeBoekenBedragVerschilInOspVal = 0 then
        set @TeBoekenBedragVerschilInBasisVal = 0.00;
      else
        set @TeBoekenBedragVerschilInBasisVal = ValutaOmrekenen(@Valnummer, @TeBoekenBedragVerschilInOspVal, @@BasisValutaNummer, @BjGid, @PerNr, 2);
      end if;
    end if;
      call Banktransacties_Log('JR! Bedrag: Basis='+string(@TeBoekenBedragVanFactuurInBasisVal)+', ValOsp=' +string(@BedragInValOsp)+'; RksGid=' + string(@RksGid)+ '; Factuurnr='+@FactuurNummer, 4);

    // ACW TODO: Nuancering van verschillende valutabedragen
    // OSP-bedragen omrekenen naar BetalingsopdrachtValuta
    // Factuur tegen OSP-bedragen wegboeken
    // Tegenrekening tegen basisvaluta wegboeken (via CJP)
    // Koersverschil boeken als factuurboeking in basisvaluta afwijkt van tegenrek. in basisvaluta


    // Journaalregel toevoegen (OOK als bedragen 0,00 zijn!)
    insert into tabJournaalregel WITH AUTO NAME
    select
      @JpGid AS JrJpGid,
      @Rargid AS JrRargid,
      @Boekdatum AS JrBoekdatum,
      @Factuurdatum AS JrFactuurDatum,
      @Vervaldatum AS JrVervalDatum,
      Banktransacties_VolgendStukVolgnummer(@JpGid) AS StukVolgnr,
      @RksGid AS JrRksGID,
      @IsCreditGeboekt IsCreditBoeking,
      @Valnummer AS JrValNummer,
      @TeBoekenBedragVanFactuurInValOsp AS JrValutaBedrag,
      @TeBoekenBedragVanFactuurInBasisVal AS JrBasisBedrag,
      @FactuurNummer AS JrReferentie,
      @Omschrijving AS OmsJournaalRegel,
      @BetRglGid as JrBetRglGid,
      @BetVerzGID JrBetVerzGID;
    set @JrGid = @@Identity;

    // Eventueel een betalingsverschil boeken
    if @TeBoekenBedragVerschilInOspVal <> 0 then
      // verschil als hulprekening afboeken: Zelfde boekzijde, teken omdraaien
      insert into tabHulpRekening WITH AUTO NAME
      select
        -@TeBoekenBedragVerschilInBasisVal AS HulpRekBasisBedrag,
        -@TeBoekenBedragVerschilInOspVal AS HulpRekBedragInJrValnummer,
        @IsCreditGeboekt AS HulpRekIsCredit,
        @JrGid AS HulpRekJrGid,
        //HulpRekKredBepDatum,
        @RksgidBetalingsverschil AS HulpRekRksGid,
        2 /*Bet.verschil*/ AS HulpRekSoort,
        @Valnummer AS HulpRekValNummer,
        -@TeBoekenBedragVerschilInOspVal AS HulpRekValutaBedrag
      ;
    end if;


    // Als BetRglTeBetalenInValOsp omgerekend ongelijk is aan BedragInValDgb (dus in valuta van transactie) dan een stukje koersverschil boeken
/*
    if @Valnummer <> @ValNummerDgb then
      set @boekbedragOmgerekendNaarDgbValnummer = ??
      if @boekbedragOmgerekendNaarDgbValnummer <> @BetRglTeBetalenInValDgb then
        // Verschil als koersverschil boeken, zodat de tegenrekening alsnog voor het @BetRglTeBetalenInValDgb bedrag wordt geboekt
        set @KoersverschilBedragIn??val = @KoersverschilBedragIn??val + (@boekbedragOmgerekendNaarDgbValnummer - @BetRglTeBetalenInValDgb);
        // Na afloop van de betalingsopdrachtregels het @KoersverschilBedragIn??val nog wegboeken?
      end if;
    end if;
*/

    set @GeboektBedrag = @GeboektBedrag + @TeBetalenInValOpdracht;

  end for;


  // Status betalingsopdrachten/-regels wijzigen
  //ACW: Wordt NIET via journaalregel geregeld
  update tabBetalingRegel
  set BetRglStatus = 3 /*Afgeboekt*/
  where BetRglStatus = 1 /*Opdracht*/
  and BetRglBetKopId = @BetKopId
  and BetRglBatchNr = @BatchNummer;

  // Betalingsopdracht als geheel geboekt zien als alle regels tenminste geboekt (of geweigerd/afgewezen/gestorneerd) zijn
  //if not exists(select first 1 from tabBetalingRegel where BetRglBetKopId = @BetKopId and BetRglStatus in (0 /*Voorstel*/, 1 /*Opdracht*/)) then
    update tabBetalingKop
    set BetKopGeboektDoor = @@Gebruikercode,
        BetKopGeboektDatum = now()
    where BetKopId = @BetKopId;
  //end if;

  // Unlock
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabBetalingKop', @BetKopId);

end;


create or replace procedure Banktransacties_VerwerkGevondenBetOpdrStornering(
  in @JpGid integer,
  in @RksgidTegenrek integer,
  in @RksgidBetalingsverschil integer,
  in @Rargid integer,
  in @Boekdatum date,
  in @BetRglGid integer,
  in @Omschrijving long nvarchar,
  out @IsCreditGeboekt smallint,
  out @GeboektBedrag numeric(15,2),
  out @Result smallint
)
begin
  declare @BjGid integer;
  declare @PerNr integer;
  declare @TeBoekenBedragVanFactuurInBasisVal numeric(15,2);
  declare @TeBoekenBedragVanFactuurInValOsp numeric(15,2);
  declare @TeBoekenBedragVerschilInBasisVal numeric(15,2);
  declare @JrGid integer;
  declare @BetKopId integer;

  declare @__Result_OK                                  smallint = 0;
  declare @__Result_LockNietGelukt                      smallint = 1;

    call Banktransacties_Log('//Verwerk gevonden betalingsopdrachtstornering; @BetRglGid='+string(@BetRglGid), 3);

  set @result = @__Result_OK;

  set @IsCreditGeboekt = 0; // Een betaling of stornering van crediteur altijd debet

  set @GeboektBedrag = 0; // Wordt hieronder berekend

  select BetRglBetKopId into @BetKopId from tabbetalingregel where BetRglGid = @BetRglGid;

  // Probeer te locken
  begin
    declare @LockIsGelukt smallint;
    call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'tabBetalingKop', @BetKopId, 10 /*seconden*/, @LockIsGelukt);
    if @LockIsGelukt = 0 then
      set @result = @__Result_LockNietGelukt;
      return;
    end if;
  end;

  // Journaalregels aanmaken
  FOR @@FORLOOP_Regels AS @@CURSOR_Regels CURSOR FOR
    select
      BetVerzGID @BetVerzGID,
      if BetRglIsVerzameld = 0 then BetRglFactuurNummer else BetVerzFactuurnummer endif @FactuurNummer,
      OspFactuurDatum @Factuurdatum,
      OspVervalDatum @Vervaldatum,
      if BetRglIsVerzameld = 0 then BetRglTeBetalen else BetVerzTeBetalen endif @TeBetalenInValOpdracht,
      if BetRglIsVerzameld = 0 then BetRglFactuurNummer_Lengte else BetVerzFactuurnummer_Lengte endif @FactuurNummer_Lengte,
      if BetRglIsVerzameld = 0 then BetRglTeBetalenInValOsp else BetVerzTeBetalenInValOsp endif @BedragInValOsp, /*TODO Corrigeren voor bet.verschil?*/
      //if BetRglIsVerzameld = 0 then BetRglTeBetalenInValDgb else
      BetRglValNummer @ValNummer,
      BetRglRksGid @RksGid,
      if BetRglIsVerzameld = 0 then BetRglVerschilAfboeken else BetVerzVerschilAfboeken endif @IsVerschilAfboeken,
      if BetRglIsVerzameld = 0 then BetRglVerschilAfboekenBedragInValOsp else BetVerzVerschilAfboekenBedragInValOsp endif @TeBoekenBedragVerschilInOspVal,
      if BetRglIsVerzameld = 0 then BetRglBetKenmerk else BetVerzBetKenmerk endif @Betalingskenmerk
    from
      tabBetalingKop
      inner join tabBetalingRegel on BetRglBetKopId = BetKopId
      left outer join tabBetalingVerzameld on BetVerzBetRglGid = BetRglGid
      inner join tabOpenstaandePost on (OspRksGid = @RksGid and OspFactuurnummer_Lengte = @FactuurNummer_Lengte and OspFactuurNummer = @FactuurNummer )
      inner join vwMeestRecenteOpenstaandePosten on calcOspGid = OspGid
    where
          BetRglGid = @BetRglGid
      and BetRglStatus = 3 /*Afgeboekt*/
    order by
      BetRglRksGid, BetVerzBetRglGid
    for read only
  do

    //Als @IsVerschilAfboeken=0 dan alleen het bedrag volgens de opdrachtregel boeken op de factuur
    //Als @IsVerschilAfboeken=1 dan TeBetalen+VerschilBedrag afboeken en hulprekening voor verschilbedrag, zelfde boekzijde, teken omkeren

    // Bepaal of we een verschilbedrag als betalingsverschil moeten boeken
    if @IsVerschilAfboeken = 0 then
      set @TeBoekenBedragVerschilInOspVal = 0;
      set @TeBoekenBedragVanFactuurInValOsp = @BedragInValOsp;
    else
      set @TeBoekenBedragVanFactuurInValOsp = @BedragInValOsp + @TeBoekenBedragVerschilInOspVal;
    end if;


    // Bereken bedragen naar basisvaluta
    if @Valnummer = @@Basisvalutanummer then
      set @TeBoekenBedragVanFactuurInBasisVal = @TeBoekenBedragVanFactuurInValOsp;
      set @TeBoekenBedragVerschilInBasisVal = @TeBoekenBedragVerschilInOspVal;
    else
      // Andere valuta, dus juiste boekjaar+periode opvragen tbv omrekenen
      if @BjGid is null then
        select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
      end if;
      set @TeBoekenBedragVanFactuurInBasisVal = ValutaOmrekenen(@Valnummer, @BedragInValOsp, @@BasisValutaNummer, @BjGid, @PerNr, 2);
      if @TeBoekenBedragVerschilInOspVal = 0 then
        set @TeBoekenBedragVerschilInBasisVal = 0.00;
      else
        set @TeBoekenBedragVerschilInBasisVal = ValutaOmrekenen(@Valnummer, @TeBoekenBedragVerschilInOspVal, @@BasisValutaNummer, @BjGid, @PerNr, 2);
      end if;
    end if;
      call Banktransacties_Log('JR! Bedrag: Basis='+string(-@TeBoekenBedragVanFactuurInBasisVal)+', ValOsp=' +string(-@BedragInValOsp)+'; RksGid=' + string(@RksGid)+ '; Factuurnr='+@FactuurNummer, 4);

    // ACW TODO: Nuancering van verschillende valutabedragen
    // OSP-bedragen omrekenen naar BetalingsopdrachtValuta
    // Factuur tegen OSP-bedragen wegboeken
    // Tegenrekening tegen basisvaluta wegboeken (via CJP)
    // Koersverschil boeken als factuurboeking in basisvaluta afwijkt van tegenrek. in basisvaluta


    // Journaalregel toevoegen (OOK als bedragen 0,00 zijn!)
    insert into tabJournaalregel WITH AUTO NAME
    select
      @JpGid AS JrJpGid,
      @Rargid AS JrRargid,
      @Boekdatum AS JrBoekdatum,
      @Factuurdatum AS JrFactuurDatum,
      @Vervaldatum AS JrVervalDatum,
      Banktransacties_VolgendStukVolgnummer(@JpGid) AS StukVolgnr,
      @RksGid AS JrRksGID,
      @IsCreditGeboekt IsCreditBoeking,
      @Valnummer AS JrValNummer,
      -@TeBoekenBedragVanFactuurInValOsp AS JrValutaBedrag,
      -@TeBoekenBedragVanFactuurInBasisVal AS JrBasisBedrag,
      @FactuurNummer AS JrReferentie,
      @Omschrijving AS OmsJournaalRegel,
      @BetRglGid as JrBetRglGid,
      @BetVerzGID JrBetVerzGID;
    set @JrGid = @@Identity;

    // Eventueel een betalingsverschil boeken
    if @TeBoekenBedragVerschilInOspVal <> 0 then
      // verschil als hulprekening afboeken: Zelfde boekzijde, teken omdraaien
      insert into tabHulpRekening WITH AUTO NAME
      select
        @TeBoekenBedragVerschilInBasisVal AS HulpRekBasisBedrag,
        @TeBoekenBedragVerschilInOspVal AS HulpRekBedragInJrValnummer,
        @IsCreditGeboekt AS HulpRekIsCredit,
        @JrGid AS HulpRekJrGid,
        //HulpRekKredBepDatum,
        @RksgidBetalingsverschil AS HulpRekRksGid,
        2 /*Bet.verschil*/ AS HulpRekSoort,
        @Valnummer AS HulpRekValNummer,
        @TeBoekenBedragVerschilInOspVal AS HulpRekValutaBedrag
      ;
    end if;


    // Als BetRglTeBetalenInValOsp omgerekend ongelijk is aan BedragInValDgb (dus in valuta van transactie) dan een stukje koersverschil boeken
/*
    if @Valnummer <> @ValNummerDgb then
      set @boekbedragOmgerekendNaarDgbValnummer = ??
      if @boekbedragOmgerekendNaarDgbValnummer <> @BetRglTeBetalenInValDgb then
        // Verschil als koersverschil boeken, zodat de tegenrekening alsnog voor het @BetRglTeBetalenInValDgb bedrag wordt geboekt
        set @KoersverschilBedragIn??val = @KoersverschilBedragIn??val + (@boekbedragOmgerekendNaarDgbValnummer - @BetRglTeBetalenInValDgb);
        // Na afloop van de betalingsopdrachtregels het @KoersverschilBedragIn??val nog wegboeken?
      end if;
    end if;
*/
    // Let op! Stornering, dus bedrag AF halen
    set @GeboektBedrag = @GeboektBedrag - @TeBetalenInValOpdracht;
  end for;


  // Status betalingsopdrachten/-regels wijzigen
  // Wordt NIET via journaalregel verwerkt
  update tabBetalingRegel
  set BetRglStatus = 2 /*Geweigerd*/
  where BetRglGid = @BetRglGid
  and BetRglStatus = 3 /*Afgeboekt*/;

  // Betalingsopdracht van Geheel geboekt halen
  update tabBetalingKop
  set BetKopGeboektDoor = @@Gebruikercode,
      BetKopGeboektDatum = now()
  where BetKopId = (select BetRglBetKopId from tabBetalingRegel where BetRglGid = @BetRglGid);

  // Unlock
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabBetalingKop', @BetKopId);

end;


create or replace procedure Banktransacties_VerwerkGevondenFactuur(
  in @JpGid integer,
  in @RksgidTegenrek integer,
  in @RksgidBetalingsverschil integer,
  in @Rargid integer,
  in @Boekdatum date,
  in @IsBijboeking smallint,
  in @RarBedrag numeric(15,2),
  in @RarValnummer integer,
  in @RksGid integer,
  in @OspGid integer,
  in @Omschrijving long nvarchar,
  in @AantalNogTeVerwerkenPosten integer,
  out @GeboektIsCredit smallint,
  out @GeboektBedragInRarVal numeric(15,2)
)
begin
  declare @BjGid integer;
  declare @PerNr integer;
  declare @TeBoekenBedragVanFactuurInValOsp numeric(15,2);
  declare @JrGid integer;
  declare @RarBedragInValOsp numeric(15,2);
  declare @IsBijboekingTeken smallint; // -1, 1
  declare @GeboektIsCreditTeken smallint;
  declare @IsFactuurPositief smallint;
  declare @IsLaatsteFactuur smallint;

  //OSP variabelen
  declare @IsDebiteur smallint;
  declare @FactuurDatum date;
  declare @Vervaldatum  date;
  declare @BetalingsKenmerk nvarchar(140);
  declare @IsViaIncasso smallint;
  declare @OspValnummer integer;
  declare @OspFactuurbedrag      numeric(15,2);
  declare @OspBetaaldbedrag      numeric(15,2);
  declare @OspOpenstaandBedrag   numeric(15,2);
  declare @KredietbeperkingsBedragInValOsp  numeric(15,2);
  declare @KredietbeperkingsBedragInValBasis numeric(15,2);
  declare @KredietBeperkingsDatum  date;
  declare @KredietBeperkingsRksGid integer;
  declare @FactuurNummer nvarchar(40);
  declare @SoortFactuur smallint;
  declare @OspIsGeblokkeerd smallint;
  declare @OspMeldingGeven smallint;
  declare @OspOms nvarchar(40);

  call Banktransacties_Log('//Verwerk gevonden factuur; @OspGid='+string(@OspGid)+'; @RksGid='+string(@RksGid));

  set @GeboektBedragInRarVal = null; // Indien leeg, dan straks berekenen uit TeBoekenOpOsp

  // TODO: Locking?


  // *** Opzoeken factuurgegevens ***
  select OspFactuurDatum,
         OspVervalDatum,
         OspBetalingsKenmerk,
         0, //was OspIsViaIncasso maar veld is vervallen,
         OspValnummer,
         (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) Factuurbedrag,
         (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig) BetaaldBedrag,
         Factuurbedrag - BetaaldBedrag /*FactuurBedrag-BetaaldBedrag=OpenstaandBedrag*/,
         if OspSoortFactuur=1 or OspSoortFactuur=2 then IsNull(OspKredietbeperkingsBedrag, 0) else 0 endif,
         OspKredietBeperkingsDatum,
         OspKredietBeperkingsRksGid,
         OspFactuurNummer,
         OspSoortFactuur,
         OspIsGeblokkeerd,
         OspMeldingGeven,
         OspOms,
         OspRksGid,
         if (OspIsCrediteur = 0) then 1 else 0 endif  // Een betaling van debiteur altijd beokzijde credit anders debet
  into   @FactuurDatum, @Vervaldatum, @BetalingsKenmerk, @IsViaIncasso, @OspValnummer,
         @OspFactuurbedrag, @OspBetaaldbedrag,
         @OspOpenstaandBedrag,
         @KredietbeperkingsBedragInValOsp, @KredietBeperkingsDatum, @KredietBeperkingsRksGid,
         @FactuurNummer, @SoortFactuur, @OspIsGeblokkeerd, @OspMeldingGeven,@OspOms, @RksGid, @IsDebiteur
  from   tabOpenstaandePost
  where  OspGid = @OspGid;

  // Hulp
  set @GeboektIsCreditTeken = 1 - @IsDebiteur * 2; // -1=credit, 1=debet, dus relateer aan DEBET als je hiermee vermenigvuldigt
  set @IsBijboekingTeken = @IsBijboeking * 2 - 1; // -1=afboeking, 1=bijboeken, dus relateer aan DEBET
  set @IsLaatsteFactuur = if @AantalNogTeVerwerkenPosten = 0 then 1 else 0 endif;

  // *** Opzoeken boekjaar tbv valutaomrekeningen ***
  select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;


  // *** Betalingstoeslag/korting obv datum bepalen ***
  //Er is geen kredietbeperkingsbedrag bij soort factuur Kredietbeperking/Betalingskorting als de boekdatum voorbij de beperkingsdatum ligt of als soort factuur Contant/Incasso-factuur
  if (@SoortFactuur in (0 /*Standaard factuur*/ ,3 /*Automatische incasso*/))
  or ((@SoortFactuur in (1 /*Kredietbeperking*/, 2 /*Betalingskorting*/)) and (@Boekdatum > @KredietBeperkingsDatum)) then
    set @KredietbeperkingsBedragInValOsp = 0;
  end if;

  // *** Omreken OSP-bedragen naar basisvaluta ***
  if @OspValnummer <> @@Basisvalutanummer then
    // Andere valuta, dus juiste boekjaar+periode opvragen tbv omrekenen
    if @BjGid is null then
      select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
    end if;

  end if;

  // *** Omrekenen transactiebedrag naar valuta van factuur
  if @RarValnummer = @OspValnummer or @RarBedrag = 0 Then
    set @RarBedragInValOsp = @RarBedrag;
  else
    set @RarBedragInValOsp = ValutaOmrekenen(@RarValnummer, @RarBedrag, @OspValnummer, @BjGid, @PerNr, 2);
  end if;

  set @IsFactuurPositief = if (@OspOpenstaandBedrag - @KredietbeperkingsBedragInValOsp) > 0 then 1 else 0 endif;

  case

    // -------- Bijboeking op debiteuren of afboeking op crediteur EN positieve factuurbedrag --------
    when @IsBijboeking = @IsDebiteur and @IsFactuurPositief = 1 Then
        // Boek minimum(openstaandbedrag, transactiebedrag)
      case
        when @RarBedragInValOsp = @OspOpenstaandBedrag and @IsLaatsteFactuur = 1 then
          // Precies gelijk betaald aan openstaand, dus geen kredietbeperking
          call Banktransacties_Log('//CASE! 1a; Bij op Deb. of Af op cred. EN +factuurbedrag, precies openstaand betaald');
          set @TeBoekenBedragVanFactuurInValOsp = @OspOpenstaandBedrag;
          set @KredietbeperkingsBedragInValOsp = 0;

        when @RarBedragInValOsp >= @OspOpenstaandBedrag then
          // Meer betaald dan openstaand, dus geen kredeitbeperking
          call Banktransacties_Log('//CASE! 1a; Bij op Deb. of Af op cred. EN +factuurbedrag, Meer betaald dan openstaat');
          set @TeBoekenBedragVanFactuurInValOsp = @OspOpenstaandBedrag;
          //set @KredietbeperkingsBedragInValOsp = 0;//HOEZO? Hier moet gewoon kredietbep. eraf worden gehaald

        when @RarBedragInValOsp >= @OspOpenstaandBedrag - @KredietbeperkingsBedragInValOsp then
          // Meer betaald dan openstaand-kredietbeperking, maar minder dan openstaand, dus openstaand afboeken, restant op kredietbeperking
          // (Dit werkt het nu anders dan bij de handmatige, want bij een teveelbetaling wordt daar gestopt (user interactie)
          call Banktransacties_Log('//CASE! 1b; Bij op Deb. of Af op cred. EN +factuurbedrag, Meer betaald dan openstaat+kredietbeperking');
          set @TeBoekenBedragVanFactuurInValOsp = @OspOpenstaandBedrag;
          // Kredietbeperking = deels betaald (als volledig, dan was dat in de vorige when-clausule al verwerkt)
          set @KredietbeperkingsBedragInValOsp = @OspOpenstaandBedrag - @RarBedragInValOsp;

        else
          // Betaald < openstaand-kred.bep. (dus deelbetaling), dus openstaande deels afboeken, geen kredietbeperking
          call Banktransacties_Log('//CASE! 1c; Bij op Deb. of Af op cred. EN +factuurbedrag, Minder betaald dan openstaat-kredietbeperking');
          set @TeBoekenBedragVanFactuurInValOsp  = @RarBedragInValOsp;
          set @KredietbeperkingsBedragInValOsp   = 0;
          set @GeboektBedragInRarVal             = @RarBedrag; //ivm afrondingen het bedrag hier overnemen ipv straks terugrekenen
      end;

    // -------- Bijboeking op debiteur of afboeking op crediteur EN negatieve factuurbedrag EN er volgen nog meer facturen --------
    when @IsBijboeking = @IsDebiteur and @IsFactuurPositief = 0 and @IsLaatsteFactuur = 0 Then
      // Openstaande bedrag kleiner dan 0, gewoon verder afboeken met het transactiebedrag
      call Banktransacties_Log('//CASE! 2; Bij op Deb. of Af op Cerd. EN -factuurbedrag EN er volgen nog meer facturen');
      set @TeBoekenBedragVanFactuurInValOsp  = @OspOpenstaandBedrag; // Dit bedrag wordt met de volgende OSPs weer verwerkt
      // Eigenlijk mag het te verrekenen bedrag maximaal het bedrag zijn dat op komende facturen nog kan worden geboekt.
      set @KredietbeperkingsBedragInValOsp   = 0;   // creditnotas hebben geen kredietbeperking

    // -------- Bijboeking op debiteur of afboeking op crediteurEN negatieve factuurbedrag EN het is de laatste factuur --------
    when @IsBijboeking = @IsDebiteur and @IsFactuurPositief = 0 and @IsLaatsteFactuur = 1 Then
      call Banktransacties_Log('//CASE! 3; Bij op Deb. of Af op Cerd. EN -factuurbedrag EN het is de laatste factuur');
      // Dit zou het negatieve factuurbedrag nog negatiever maken, daarom niet boeken
      set @TeBoekenBedragVanFactuurInValOsp  = 0; // Niet boeken
      set @KredietbeperkingsBedragInValOsp   = 0;
      set @GeboektBedragInRarVal             = 0;

    // -------- Afboeking op positieve debiteurenfactuur OF bijboeking op positieve crediteurenfactuur --------
    when @IsBijboeking <> @IsDebiteur and @IsFactuurPositief = 1 Then
      // Dit is een terugbetaling van een debiteurenfactuur of ontvangst op cred.factuur, dus gewoon het bedrag boeken
      call Banktransacties_Log('//CASE! 4; Af op Deb. of Bij op Cred. EN +factuurbedrag');
      set @TeBoekenBedragVanFactuurInValOsp  = -@RarBedragInValOsp;
      set @KredietbeperkingsBedragInValOsp   = 0;   // creditnotas hebben geen kredietbeperking
      set @GeboektBedragInRarVal             = -@RarBedrag; //ivm afrondingen het bedrag hier overnemen ipv straks terugrekenen

    // -------- Afboeking op negatieve debiteurenfactuur OF bijboeking op negatieve crediteurenfactuur --------
    when @IsBijboeking <> @IsDebiteur and @IsFactuurPositief = 0 Then
      // Dit is waarschijnlijk een dubbele betaling, dus hooguit het betalingsbedrag of het openstaande bedrag
      call Banktransacties_Log('//CASE! 5; Af op Deb. of Bij op Cred. EN -factuurbedrag');
      set @TeBoekenBedragVanFactuurInValOsp  = -1 * if @RarBedragInValOsp < -@OspOpenstaandBedrag then @RarBedragInValOsp else -@OspOpenstaandBedrag endif;
      set @KredietbeperkingsBedragInValOsp   = 0;   // creditnotas hebben geen kredietbeperking
      set @GeboektBedragInRarVal             = -1 * if @RarBedragInValOsp < -@OspOpenstaandBedrag then @RarBedrag endif;
  end;
  call Banktransacties_Log('//Resultaat Boeken: ' + string(@TeBoekenBedragVanFactuurInValOsp) + ', Kredietbeperking: '+string(@KredietbeperkingsBedragInValOsp));


  // Omrekenen van te boeken bedrag naar valuta van transactie (als dat nog niet bekend is)
  if @GeboektBedragInRarVal is null then
    // Teruggeven van het geboekte bedrag in de juiste valuta, kon nog niet worden berekend
    set @GeboektBedragInRarVal = if @OspValnummer = @RarValnummer or  (@TeBoekenBedragVanFactuurInValOsp -@KredietbeperkingsBedragInValOsp) = 0 then
      (@TeBoekenBedragVanFactuurInValOsp - @KredietbeperkingsBedragInValOsp)
    else
      ValutaOmrekenen(@OspValnummer, (@TeBoekenBedragVanFactuurInValOsp - @KredietbeperkingsBedragInValOsp), @RarValnummer, @BjGid, @PerNr, 2)
    endif;
  end if;


  begin // Wegboeken van de bedragen
    declare @TeBoekenBedragVanFactuurInValBasis numeric(15,2);

    //Valutaomrekening: Boekbedrag in basisvaluta
    if @TeBoekenBedragVanFactuurInValOsp = 0 or @OspValnummer = @@Basisvalutanummer then
      set @TeBoekenBedragVanFactuurInValBasis = @TeBoekenBedragVanFactuurInValOsp;
    else
      set @TeBoekenBedragVanFactuurInValBasis = ValutaOmrekenen(@OspValnummer, @TeBoekenBedragVanFactuurInValOsp, @@BasisValutaNummer, @BjGid, @PerNr, 2);
    end if;


    call Banktransacties_Log('JR! Bedrag: Basis='+string(@TeBoekenBedragVanFactuurInValBasis)+', ValOsp=' +string(@OspOpenstaandBedrag)+'; RksGid=' + string(@RksGid)+ '; Factuurnr='+@FactuurNummer+'; GeboektInRarValuta='+string(@GeboektBedragInRarVal), 4);


    set @GeboektIsCredit = @IsDebiteur;

    // Journaalregel toevoegen
    if @TeBoekenBedragVanFactuurInValOsp <> 0 or @TeBoekenBedragVanFactuurInValBasis <> 0 or @KredietbeperkingsBedragInValOsp <> 0 then
      insert into tabJournaalregel WITH AUTO NAME
      select
        @JpGid AS JrJpGid,
        @Rargid AS JrRargid,
        @Boekdatum AS JrBoekdatum,
        @Factuurdatum AS JrFactuurDatum,
        @Vervaldatum AS JrVervalDatum,
        Banktransacties_VolgendStukVolgnummer(@JpGid) AS StukVolgnr,
        @RksGid AS JrRksGID,
        @IsDebiteur AS IsCreditBoeking, //Debiteur altijd credit boeken, crediteur altijd debet boeken
        @OspValnummer AS JrValNummer,
        @TeBoekenBedragVanFactuurInValOsp AS JrValutaBedrag,
        @TeBoekenBedragVanFactuurInValBasis AS JrBasisBedrag,
        @FactuurNummer AS JrReferentie,
        @Omschrijving AS OmsJournaalRegel,
        @BetalingsKenmerk AS JrBetalingsKenmerk;

      set @JrGid = @@Identity;

      //Hulprekening toevoegen
      if @KredietbeperkingsBedragInValOsp <> 0 then
        begin
          declare @HulpRekSoort smallint;

          // Tegenwaarde kredietbeperking berekenen
          if (@OspValnummer <> @@Basisvalutanummer) or @KredietbeperkingsBedragInValOsp = 0 Then
            set @KredietbeperkingsBedragInValBasis = 0.00;
          else
            set @KredietbeperkingsBedragInValBasis = ValutaOmrekenen(@OspValnummer, @KredietbeperkingsBedragInValOsp, @@Basisvalutanummer, @BjGid, @PerNr, 2);
          end if;


          if @SoortFactuur = 1 /*Kredietbeperking*/ then
            Set @HulpRekSoort = 4 /*Kredietbeperking*/;
          else                  /*Betalingskorting*/
            Set @HulpRekSoort = 5 /*Betalingskorting*/;
          end if;

          insert into TabHulpRekening  WITH AUTO NAME
          select
            @JrGid AS HulpRekJrGid,
            @HulpRekSoort AS HulpRekSoort,
            @KredietBeperkingsRksGid AS HulpRekRksGid,
            @IsDebiteur AS HulpRekIsCredit,
            @OspValnummer AS HulpRekValNummer,
            -@KredietbeperkingsBedragInValOsp AS HulpRekValutaBedrag,
            -@KredietbeperkingsBedragInValBasis AS HulpRekBasisBedrag,
            null AS HulpRekBtwCode,
            @KredietBeperkingsDatum AS HulpRekKredBepDatum;
        end;
      end if;

    else
      set @GeboektBedragInRarVal = 0;
    end if;
  end;
end;


create or replace procedure Banktransacties_VerwerkGevondenIncOpdr(
  in @JpGid integer,
  in @RksgidTegenrek integer,
  in @RksgidBetalingsverschil integer,
  in @Rargid integer,
  in @Boekdatum date,
  in @IncKopId integer,
  in @BatchNummer integer,
  in @Omschrijving long nvarchar,
  out @IsCreditGeboekt smallint,
  out @GeboektBedrag numeric(15,2),
  out @result smallint //0 = OK, 1 = LOck niet gelukt
)
begin
  declare @BjGid integer = null; // Gebruikt voor valutaomrekeningen op 1 datum
  declare @PerNr integer;
  declare @TeBoekenBedragVanFactuurInBasisVal numeric(15,2);
  declare @TeBoekenBedragVanFactuurInValOsp numeric(15,2);
  declare @TeBoekenBedragVerschilInBasisVal numeric(15,2);
  declare @JrGid integer;

  declare @__Result_OK             smallint = 0;
  declare @__Result_LockNietGelukt smallint = 1;

    call Banktransacties_Log('//Verwerk gevonden incassoopdracht; @IncKopId='+string(@IncKopId)+'; @BatchNummer='+string(@BatchNummer), 3);

  set @result = @__Result_OK;

  set @IsCreditGeboekt = 1; // Een betaling van debiteur altijd credit

  set @GeboektBedrag = 0; // Wordt hieronder berekend

  // Probeer te locken
  begin
    declare @LockIsGelukt smallint;
    call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'tabIncassoKop', @IncKopId, 10 /*seconden*/, @LockIsGelukt);
    if @LockIsGelukt = 0 then
      set @result = @__Result_LockNietGelukt;
      return;
    end if;
  end;

  // Journaalregels aanmaken
  FOR @@FORLOOP_Regels AS @@CURSOR_Regels CURSOR FOR
    select
      IncRglGid @IncRglGid,
      IrvGid @IrvGid,
      if IncRglIsVerzameld = 0 then IncRglFactuurNummer else IrvFactuurnummer endif @FactuurNummer,
      OspFactuurDatum @Factuurdatum,
      OspVervalDatum @Vervaldatum,
      if IncRglIsVerzameld = 0 then IncRglFactuurNummer_Lengte else IrvFactuurnummer_Lengte endif @FactuurNummer_Lengte,
      if IncRglIsVerzameld = 0 then IncRglTeIncasseren else IrvTeIncasseren endif @BedragInValInc, /*TODO Corrigeren voor bet.verschil?*/
      //if IncRglIsVerzameld = 0 then IncRglTeBetalenInValDgb else
      @@EuroValutaNummer @ValNummer,
      OspValnummer @ValnummerOsp,
      IncRglRksGid @RksGid,
      if IncRglIsVerzameld = 0 then IncRglBetKenmerk else IrvBetKenmerk endif @Betalingskenmerk
    from
      tabIncassoKop
      inner join tabIncassoRegel on IncRglIncKopId = IncKopId
      left outer join tabIncassoregelVerzameld on IrvIncRglGid = IncRglGid
      inner join tabOpenstaandePost on (OspRksGid = @RksGid and OspFactuurnummer_Lengte = @FactuurNummer_Lengte and OspFactuurNummer = @FactuurNummer )
      inner join vwMeestRecenteOpenstaandePosten on calcOspGid = OspGid
    where
      IncKopId = @IncKopId
      and IncRglBatchNr = @BatchNummer
      and IncRglStatus = 1 /*Opdracht*/
    order by
      IncRglRksGid, IrvGid
    for read only
  do

    // Bereken bedragen naar valuta van OSP

    if @ValNummer = @ValnummerOsp or @BedragInValInc = 0 then
      set @TeBoekenBedragVanFactuurInValOsp = @BedragInValInc;
    else
      // Andere valuta, dus juiste boekjaar+periode opvragen tbv omrekenen
      if @BjGid is null then
        select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
      end if;
      set @TeBoekenBedragVanFactuurInValOsp = ValutaOmrekenen(@ValNummer, @BedragInValInc, @ValnummerOsp, @BjGid, @PerNr, 2);
    end if;

    // Bereken bedragen naar basisvaluta
    if @ValnummerOsp = @@Basisvalutanummer then
      set @TeBoekenBedragVanFactuurInBasisVal = @TeBoekenBedragVanFactuurInValOsp;
    else
      if @BjGid is null then
        select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
      end if;
      set @TeBoekenBedragVanFactuurInBasisVal = ValutaOmrekenen(@ValnummerOsp, @TeBoekenBedragVanFactuurInValOsp, @@BasisValutaNummer, @BjGid, @PerNr, 2);
    end if;
      call Banktransacties_Log('JR! Bedrag: Basis='+string(@TeBoekenBedragVanFactuurInBasisVal)+', ValOsp=' +string(@TeBoekenBedragVanFactuurInValOsp)+'; RksGid=' + string(@RksGid)+ '; Factuurnr='+@FactuurNummer, 4);

    // ACW TODO: Nuancering van verschillende valutabedragen
    // OSP-bedragen omrekenen naar BetalingsopdrachtValuta
    // Factuur tegen OSP-bedragen wegboeken
    // Tegenrekening tegen basisvaluta wegboeken (via CJP)
    // Koersverschil boeken als factuurboeking in basisvaluta afwijkt van tegenrek. in basisvaluta


    // Journaalregel toevoegen (OOK als bedragen 0,00 zijn!)
    insert into tabJournaalregel WITH AUTO NAME
    select
      @JpGid AS JrJpGid,
      @Rargid AS JrRargid,
      @Boekdatum AS JrBoekdatum,
      @Factuurdatum AS JrFactuurDatum,
      @Vervaldatum AS JrVervalDatum,
      Banktransacties_VolgendStukVolgnummer(@JpGid) AS StukVolgnr,
      @RksGid AS JrRksGID,
      @IsCreditGeboekt IsCreditBoeking,
      @ValnummerOsp AS JrValNummer,
      @TeBoekenBedragVanFactuurInValOsp AS JrValutaBedrag,
      @TeBoekenBedragVanFactuurInBasisVal AS JrBasisBedrag,
      @FactuurNummer AS JrReferentie,
      @Omschrijving AS OmsJournaalRegel,
      @IncRglGid As JrIncRglGid,
      @IrvGid as JrIrvGid;
    set @JrGid = @@Identity;

    // Als IncRglTeBetalenInValOsp omgerekend ongelijk is aan BedragInValDgb (dus in valuta van transactie) dan een stukje koersverschil boeken
/*
    if @ValnummerOsp <> @ValNummerDgb then
      set @boekbedragOmgerekendNaarDgbValnummer = ??
      if @boekbedragOmgerekendNaarDgbValnummer <> @IncRglTeBetalenInValDgb then
        // Verschil als koersverschil boeken, zodat de tegenrekening alsnog voor het @IncRglTeBetalenInValDgb bedrag wordt geboekt
        set @KoersverschilBedragIn??val = @KoersverschilBedragIn??val + (@boekbedragOmgerekendNaarDgbValnummer - @IncRglTeIncasserenInValDgb);
        // Na afloop van de betalingsopdrachtregels het @KoersverschilBedragIn??val nog wegboeken?
      end if;
    end if;
*/

    set @GeboektBedrag = @GeboektBedrag + @BedragInValInc;

  end for;


  // Status betalingsopdrachten/-regels wijzigen
  // Dit Wordt niet via journaalregel verwerkt!
  update tabIncassoRegel
  set IncRglStatus = 3 /*Afgeboekt*/
  where IncRglStatus = 1 /*Opdracht*/
  and IncRglIncKopId = @IncKopId
  and IncRglBatchNr = @BatchNummer;

  // Incassoopdracht als geheel geboekt zien als alle regels tenminste geboekt (of geweigerd/afgewezen/gestorneerd) zijn
  if not exists(select first 1 from tabIncassoRegel where IncRglIncKopId = @IncKopId and IncRglStatus in (0 /*Voorstel*/, 1 /*Opdracht*/, 2 /*Geweigerd*/, 4 /*Gestorneerd*/)) then
    update tabIncassoKop
    set //IncKopGeboektDoor = @@Gebruikercode, Onbekend bij incasso!
        IncKopGeboektDatum = now()
    where IncKopId = @IncKopId;
  end if;

  // Unlock
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabIncassoKop', @IncKopId);

end;


create or replace procedure Banktransacties_VerwerkGevondenIncOpdrStornering(
  in @JpGid integer,
  in @RksgidTegenrek integer,
  in @RksgidBetalingsverschil integer,
  in @Rargid integer,
  in @Boekdatum date,
  in @IncRglGid integer,
  in @Omschrijving long nvarchar,
  out @IsCreditGeboekt smallint,
  out @GeboektBedrag numeric(15,2),
  out @result smallint //0 = OK, 1 = LOck niet gelukt
)
begin
  declare @BjGid integer = null; // Gebruikt voor valutaomrekeningen op 1 datum
  declare @PerNr integer;
  declare @TeBoekenBedragVanFactuurInBasisVal numeric(15,2);
  declare @TeBoekenBedragVanFactuurInValOsp numeric(15,2);
  declare @TeBoekenBedragVerschilInBasisVal numeric(15,2);
  declare @JrGid integer;
  declare @IncKopId integer;

  declare @__Result_OK             smallint = 0;
  declare @__Result_LockNietGelukt smallint = 1;

    call Banktransacties_Log('//Verwerk gevonden stornering incassoopdrachtregel; @IncRglGid='+string(@IncRglGid), 3);

  set @result = @__Result_OK;

  set @IsCreditGeboekt = 1; // Een betaling/stornering van debiteur altijd credit

  set @GeboektBedrag = 0; // Wordt hieronder berekend

  select IncRglIncKopId into @IncKopId from tabincassoregel where IncRglGid = @IncRglGid;

  // Probeer te locken
  begin
    declare @LockIsGelukt smallint;
    call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'tabIncassoKop', @IncKopId, 10 /*seconden*/, @LockIsGelukt);
    if @LockIsGelukt = 0 then
      set @result = @__Result_LockNietGelukt;
      return;
    end if;
  end;

  // Journaalregels aanmaken
  FOR @@FORLOOP_Regels AS @@CURSOR_Regels CURSOR FOR
    select
      IrvGid @IrvGid,
      if IncRglIsVerzameld = 0 then IncRglFactuurNummer else IrvFactuurnummer endif @FactuurNummer,
      OspFactuurDatum @Factuurdatum,
      OspVervalDatum @Vervaldatum,
      if IncRglIsVerzameld = 0 then IncRglFactuurNummer_Lengte else IrvFactuurnummer_Lengte endif @FactuurNummer_Lengte,
      if IncRglIsVerzameld = 0 then IncRglTeIncasseren else IrvTeIncasseren endif @BedragInValInc,
      //if IncRglIsVerzameld = 0 then IncRglTeBetalenInValDgb else
      @@EuroValutaNummer @ValNummer,
      OspValnummer @ValnummerOsp,
      IncRglRksGid @RksGid,
      if IncRglIsVerzameld = 0 then IncRglBetKenmerk else IrvBetKenmerk endif @Betalingskenmerk
    from
      tabIncassoRegel
      left outer join tabIncassoregelVerzameld on IrvIncRglGid = IncRglGid
      inner join tabOpenstaandePost on (OspRksGid = @RksGid and OspFactuurnummer_Lengte = @FactuurNummer_Lengte and OspFactuurNummer = @FactuurNummer )
      inner join vwMeestRecenteOpenstaandePosten on calcOspGid = OspGid
    where
      IncRglGid = @IncRglGid
      and IncRglStatus in (3 /*Afgeboekt*/, 4 /*Gestorneerd*/)
    order by
      IncRglRksGid, IrvGid
    for read only
  do

    // Bereken bedragen naar valuta van OSP

    if @ValNummer = @ValnummerOsp or @BedragInValInc = 0 then
      set @TeBoekenBedragVanFactuurInValOsp = @BedragInValInc;
    else
      // Andere valuta, dus juiste boekjaar+periode opvragen tbv omrekenen
      if @BjGid is null then
        select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
      end if;
      set @TeBoekenBedragVanFactuurInValOsp = ValutaOmrekenen(@ValNummer, @BedragInValInc, @ValnummerOsp, @BjGid, @PerNr, 2);
    end if;

    // Bereken bedragen naar basisvaluta
    if @ValnummerOsp = @@Basisvalutanummer then
      set @TeBoekenBedragVanFactuurInBasisVal = @TeBoekenBedragVanFactuurInValOsp;
    else
      if @BjGid is null then
        select PerBjGID, PerNr into @BjGid, @PerNr from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
      end if;
      set @TeBoekenBedragVanFactuurInBasisVal = ValutaOmrekenen(@ValnummerOsp, @TeBoekenBedragVanFactuurInValOsp, @@BasisValutaNummer, @BjGid, @PerNr, 2);
    end if;
      call Banktransacties_Log('JR! Bedrag: Basis='+string(@TeBoekenBedragVanFactuurInBasisVal)+', ValOsp=' +string(@TeBoekenBedragVanFactuurInValOsp)+'; RksGid=' + string(@RksGid)+ '; Factuurnr='+@FactuurNummer, 4);

    // ACW TODO: Nuancering van verschillende valutabedragen
    // OSP-bedragen omrekenen naar BetalingsopdrachtValuta
    // Factuur tegen OSP-bedragen wegboeken
    // Tegenrekening tegen basisvaluta wegboeken (via CJP)
    // Koersverschil boeken als factuurboeking in basisvaluta afwijkt van tegenrek. in basisvaluta


    // Journaalregel toevoegen (OOK als bedragen 0,00 zijn!)
    insert into tabJournaalregel WITH AUTO NAME
    select
      @JpGid AS JrJpGid,
      @Rargid AS JrRargid,
      @Boekdatum AS JrBoekdatum,
      @Factuurdatum AS JrFactuurDatum,
      @Vervaldatum AS JrVervalDatum,
      Banktransacties_VolgendStukVolgnummer(@JpGid) AS StukVolgnr,
      @RksGid AS JrRksGID,
      @IsCreditGeboekt IsCreditBoeking,
      @ValnummerOsp AS JrValNummer,
      -@TeBoekenBedragVanFactuurInValOsp AS JrValutaBedrag,
      -@TeBoekenBedragVanFactuurInBasisVal AS JrBasisBedrag,
      @FactuurNummer AS JrReferentie,
      @Omschrijving AS OmsJournaalRegel,
      @IncRglGid As JrIncRglGid,
      @IrvGid as JrIrvGid;
    set @JrGid = @@Identity;

    // Als IncRglTeBetalenInValOsp omgerekend ongelijk is aan BedragInValDgb (dus in valuta van transactie) dan een stukje koersverschil boeken
/*
    if @ValnummerOsp <> @ValNummerDgb then
      set @boekbedragOmgerekendNaarDgbValnummer = ??
      if @boekbedragOmgerekendNaarDgbValnummer <> @IncRglTeBetalenInValDgb then
        // Verschil als koersverschil boeken, zodat de tegenrekening alsnog voor het @IncRglTeBetalenInValDgb bedrag wordt geboekt
        set @KoersverschilBedragIn??val = @KoersverschilBedragIn??val + (@boekbedragOmgerekendNaarDgbValnummer - @IncRglTeIncasserenInValDgb);
        // Na afloop van de betalingsopdrachtregels het @KoersverschilBedragIn??val nog wegboeken?
      end if;
    end if;
*/

    // Let op! Stornering, dus bedrag AF halen
    set @GeboektBedrag = @GeboektBedrag - @BedragInValInc;

  end for;


  // Status betalingsopdrachten/-regels wijzigen
  // Wordt NIET via journaalregel verwerkt
  update tabIncassoRegel
  set IncRglStatus = 5 /*Afgeboekt*/
  where IncRglStatus in (3 /*Afgeboekt*/, 4 /*Gestorneerd*/)
  and IncRglGid = @IncRglGid;

  // Incassoopdracht als geheel geboekt zien als alle regels tenminste geboekt (of geweigerd/afgewezen/gestorneerd) zijn
  update tabIncassoKop
  set //IncKopGeboektDoor = @@Gebruikercode, Onbekend bij incasso!
      IncKopGeboektDatum = now()
  where IncKopId = (select IncRglIncKopId from tabIncassoRegel where IncRglGid = @IncRglGid);

  // Unlock
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabIncassoKop', @IncKopId);

end;


create or replace procedure Banktransacties_VerwerkGevondenMatches(
  in    @SessieNr integer,
  inout @BoekGangGid integer,
  inout @Transactie ROW(
          Rargid             Integer,
          EigenBankrekening  nchar(34),
          BankrekeningTegenpartij nchar(34),
          NaamTegenpartij         nchar(40),
          Boekdatum          DateTime,
          Afschriftnummer    integer,
          Postnummer         integer,
          E2E                nchar(40),
          Betalingskenmerk   nchar(40),
          Batch_AantalRegels integer,
          Bedrag             numeric(15,2),
          Valnummer          integer,
          IsBijboeking       smallint,
          TussenRksGid       integer,
          Boekreferentie     nchar(40),
          Omschrijving       long nvarchar,
          OmschrijvingZonderCrLf long nvarchar
        ),
  in    @Instelling_Stuknummer smallint,
  in    @Instelling_Volgnummer smallint,
  in    @Instelling_JournaalpostOmschrijving smallint,
  in    @TeBoekenInBjGid integer,
  in    @TeBoekenInPerNr integer,
  in    @DgbGidEigenBankrekening integer,
  out   @result integer
)
begin
  declare @__Result_OK smallint = 0;
  declare @__Result_NieuweBoekingsgangGegenereerd smallint = 100;

  declare @JPGid integer;
  declare @DgbRksGidTegenrekening integer;
  declare @DgbRksGidBetalingsverschil integer;
  declare @GeboektIsCredit smallint;
  declare @GeboektBedrag numeric(15,2);
  declare @JpOmschrijving nchar(80);
  declare @AantalGevondenPosten integer;

    call Banktransacties_Log('//PROC: Banktransacties_VerwerkGevondenMatches; Te boeken bedrag='+string(@Transactie.Bedrag), 4);

  select count(1) into @AantalGevondenPosten // Als 0 gevonden, dan zijn we gelijk al klaar
  from tabBanktransacties_Resultaat
  where BtresSessieNr = @SessieNr;

  if (@AantalGevondenPosten > 0) or (@transactie.TussenRksGid is not null and @Transactie.Bedrag <> 0) then
    //***Boekingsgang aanmaken of hergebruiken
    call Banktransacties_BoekingsgangGebruiken(
      @TeBoekenInBjGid,
      @BoekgangGid,
      @result
    );

    if @result = @__Result_NieuweBoekingsgangGegenereerd then
      // We mogen negeren dat er een nieuwe boekingsgang is aangemaakt
      set @result = @__Result_OK;
    end if;

    if @result <> @__Result_OK then
        call Banktransacties_Log('//Fout bij gebruiken boekingsgang. @result='+string(@result), 4);
      return;
    end if;

    for @CursorMatcht AS Cursor_tmpGematcht CURSOR FOR
      select
        1 @Regelsoort,
        BtresGid @BtresGid,
        BtresBtmrGid @BtmrGid,
        BtresOspGid @OspGid,
        BtresRksGid @RksGid,
        BtresBetKopId @BetKopId,
        BtresIncKopId @IncKopId,
        BtresBatchNummer @BatchNummer, // Alleen voor de betalings- en incassobatches
        BtresBetRglGid @BetRglGid,
        BtresIncRglGid @IncRglGid,
        BtresValnummer @TeBoekenInValnummer,
        BtresBedrag @TeBoekenBedrag,
        BtResJrOmschrijving @JrOmschrijving,
        BtresKwaliteit @Kwaliteit,
        row_number() over (order by @Regelsoort, @Kwaliteit desc, @BtresGid) @ordernumber,
        @AantalGevondenPosten - @ordernumber @AantalNogTeVerwerkenPosten

      from tabBanktransacties_Resultaat
      where BtresSessieNr = @SessieNr
      union all
      select
        99, // Als laatste de tussenrekening
        null @BtresGid,
        null @BtmrGid,
        null @OspGid,
        @transactie.TussenRksGid @RksGid,
        null @BetKopId,
        null @IncKopId,
        null @BatchNummer, // Alleen voor de betalings- en incassobatches
        null @BetRglGid,
        null @IncRglGid,
        @@Basisvalutanummer,
        null, // Bedrag wordt dynamisch berekend
        null, // Journaalregelomschrijving = transactieoms.
        999, //Waarde, ALTIJD VERWERKEN
        @AantalGevondenPosten @ordernumber,
        0 @AantalNogTeVerwerkenPosten

      from tabRekeningafschriftRegel
      where Rargid = @Transactie.Rargid
        and @RksGid is not null
      order by @Regelsoort, @Kwaliteit desc, @BtresGid // Eerst die met de hoogste waarde
    for read only
    do
        call Banktransacties_Log('//Verwerken gematchte regel! @Regelsoort='+ string(@Regelsoort)+'; @OspGid='+string(@OspGid)+'; @RksGid='+string(@RksGid)+'; @BetKopId='+string(@BetKopId) + '; @IncKopId='+string(@IncKopId)+'; @BatchNummer='+string(@BatchNummer)+'; @BetRglGid='+string(@BetRglGid)+'; @IncRglGid='+string(@IncRglGid)+ '; @TeBoekenInValnummer='+string(@TeBoekenInValnummer) + '; @TeBoekenBedrag=' + string(@TeBoekenBedrag)+'; @Kwaliteit='+string(@Kwaliteit), 3);

      if @@Banktransacties_LogVerboseBits & 2048 <> 0 and @BtmrGid is not null then
        update tabRekeningafschriftRegel
        set RarOms = RarOms + '||\n' + (select BtmrNaam from tabBanktransacties_Matchregel where BtmrGid = @BtmrGid)
        where RarGid = @Transactie.RarGid;
      end if;

      // Bepaal default omschrijving voor boeking;
      case @Instelling_JournaalpostOmschrijving
      when 0 /*Omschrijving transactie*/ then
        set @JpOmschrijving = @Transactie.Omschrijving;
      when 1 /*Nummer en naam tegenrekeninghouder*/ then
        set @JpOmschrijving = @Transactie.BankrekeningTegenpartij + ' ' + @Transactie.NaamTegenpartij;
      end case;

      //*** Journaalpost ophalen of aanmaken
      if @JPGid is null then
      begin

        call Banktransacties_JournaalpostAanmaken(
          @BoekGangGid,
          @Instelling_Stuknummer,
          @transactie.Afschriftnummer,
          @JpOmschrijving,
          @transactie.Boekdatum,
          @TeBoekenInBjGid,
          @TeBoekenInPerNr,
          @DgbGidEigenBankrekening,
          @JPGid
        );
        // Dagboekgegevens hier pas ophalen, is niet eerder nodig
        select DgbTegenRksGID, DgbBetRksGID
        into @DgbRksGidTegenrekening, @DgbRksGidBetalingsverschil
        from tabDagboek
        where DgbGid = @DgbGidEigenBankrekening;
      end;
      end if;
      case

        // *** Tussenrekening verwerken ***
        when @Regelsoort = 99 then
          // Let op: De controle als 1e ivm gevulde overige velden
          //         Verwerking als laatste zodat restantbedrag is berekend
            call Banktransacties_Log('//Tussenrekeningbedrag=' + string(@Transactie.Bedrag), 4);
          if @Transactie.Bedrag <> 0 then
            call Banktransacties_JournaalRegelAanmakenVoorGrootboekRekening(
              @JpGid,
              @Transactie.Rargid,
              @transactie.Boekdatum,
              @RksGid,
              @Transactie.IsBijboeking,
              @Transactie.Bedrag,
              @Transactie.Valnummer,
              @transactie.BoekReferentie,
              isnull(@JrOmschrijving, @JpOmschrijving),
              0, //IsExclBTW
              @GeboektIsCredit,
              @GeboektBedrag
            );
          end if;

        // *** Betalingsopdracht verwerken ***
        when @BetKopId is not null then
          call Banktransacties_VerwerkGevondenBetOpdr(
            @JpGid,
            @DgbRksGidTegenrekening,
            @DgbRksGidBetalingsverschil,
            @Transactie.Rargid,
            @transactie.Boekdatum,
            @BetKopId,
            @BatchNummer,
              isnull(@JrOmschrijving, @JpOmschrijving),
            @GeboektIsCredit,
            @GeboektBedrag,
            @Result
          );

        // *** Stornering van een betalingsopdrachtregel verwerken ***
        when @BetRglGid is not null then
          call Banktransacties_VerwerkGevondenBetOpdrStornering(
            @JpGid,
            @DgbRksGidTegenrekening,
            @DgbRksGidBetalingsverschil,
            @Transactie.Rargid,
            @transactie.Boekdatum,
            @BetRglGid,
              isnull(@JrOmschrijving, @JpOmschrijving),
            @GeboektIsCredit,
            @GeboektBedrag,
            @Result
          );

        // *** Incassoopdracht verwerken ***
        when @IncKopId is not null then
          call Banktransacties_VerwerkGevondenIncOpdr(
            @JpGid,
            @DgbRksGidTegenrekening,
            @DgbRksGidBetalingsverschil,
            @Transactie.Rargid,
            @transactie.Boekdatum,
            @IncKopId,
            @BatchNummer,
              isnull(@JrOmschrijving, @JpOmschrijving),
            @GeboektIsCredit,
            @GeboektBedrag,
            @Result
          );

        // *** Stortnering van een incassoopdrachtregel verwerken ***
        when @IncRglGid is not null then
          call Banktransacties_VerwerkGevondenIncOpdrStornering(
            @JpGid,
            @DgbRksGidTegenrekening,
            @DgbRksGidBetalingsverschil,
            @Transactie.Rargid,
            @transactie.Boekdatum,
            @IncRglGid,
              isnull(@JrOmschrijving, @JpOmschrijving),
            @GeboektIsCredit,
            @GeboektBedrag,
            @Result
          );

        // *** Factuur van deb/cred verwerken ***
        when @OspGid is not null then
          call Banktransacties_VerwerkGevondenFactuur(
            @JpGid,
            @DgbRksGidTegenrekening,
            @DgbRksGidBetalingsverschil,
            @Transactie.Rargid,
            @Transactie.Boekdatum,
            @Transactie.IsBijboeking,
            isnull(@TeBoekenBedrag, @Transactie.Bedrag),
            isnull(@TeBoekenInValnummer, @Transactie.Valnummer),
            @RksGid,
            @OspGid,
              isnull(@JrOmschrijving, @JpOmschrijving),
            @AantalNogTeVerwerkenPosten,
            @GeboektIsCredit,
            @GeboektBedrag
          );

        // *** Grootboekrekening verwerken ***
        when @RksGid is not null then
          if isnull(@TeBoekenBedrag, @Transactie.Bedrag) <> 0 then
            call Banktransacties_JournaalRegelAanmakenVoorGrootboekRekening(
              @JpGid,
              @Transactie.Rargid,
              @transactie.Boekdatum,
              @RksGid,
              @Transactie.IsBijboeking,
              isnull(@TeBoekenBedrag, @Transactie.Bedrag),
              isnull(@TeBoekenInValnummer, @Transactie.Valnummer),
              '', //Referentie
              isnull(@JrOmschrijving, @JpOmschrijving),
              1, //IsInclBTW (indien mogelijk een extra BTW-boeking maken)
              @GeboektIsCredit,
              @GeboektBedrag
            );
          end if;

      end case;

      // Om voor de volgende boeking het bedrag goed te krijgen, passen we nu het NogTeBoekenBedrag van de transactie aan (o.b.v. bij- of afboeking)
      if @GeboektBedrag <> 0 and @TeBoekenInValnummer is not null and @TeBoekenInValnummer <> @Transactie.Valnummer then
        set @GeboektBedrag = ValutaOmrekenen(@TeBoekenInValnummer, @GeboektBedrag, @Transactie.Valnummer, @TeBoekenInBjGid, @TeBoekenInPerNr, 2);
      end if;
      set @Transactie.Bedrag = @Transactie.Bedrag - @GeboektBedrag * (if @GeboektIsCredit = @Transactie.IsBijboeking then 1 else -1 endif);

      call banktransacties_log('@Transactie.Bedrag=' + string(@Transactie.Bedrag), 4);

      if @result <> @__Result_OK then
        // Deze transactie wordt afgebroken!
          call Banktransacties_Log('//Fout bij verwerken matches. @result='+string(@result), 4);
        return;
      end if;

    end for;
  end if;

  call Banktransacties_Log(' ', 4);

  // Journaalpost uit gebruik zetten
  if @JPGid is not null then
      call banktransacties_log('Sluit journaalpost JpGid=' + string(@JPGid), 4);
    update tabJournaalpost set JpIsInGebruik = 0 where JpIsInGebruik = 1 and JPGid = @JPGid;
  end if;

end;


create or replace procedure Banktransacties_VerwerkMatchregels(
  in    @Transactie ROW(
          Rargid             integer,
          EigenBankrekening  nchar(34),
          BankrekeningTegenpartij nchar(34),
          NaamTegenpartij         nchar(40),
          Boekdatum          DateTime,
          Afschriftnummer    integer,
          Postnummer         integer,
          E2E                nchar(40),
          Betalingskenmerk   nchar(40),
          Batch_AantalRegels integer,
          Bedrag             numeric(15,2),
          Valnummer          integer,
          IsBijboeking       smallint,
          TussenRksGid       integer,
          Boekreferentie     nchar(40),
          Omschrijving       long nvarchar,
          OmschrijvingZonderCrLf long nvarchar
        ),
  in    @SessieNr integer,
  inout @MatViewUniekNummers ROW(
          vwVoorraadaantallen             integer,
          vwBackorderAantallen            integer,
          vwVoorraadAantallenKlein        integer,
          vwBestelKopTotalen              integer,
          vwMeestRecenteOpenstaandePosten integer
        ),
  out   @Result integer
)
begin
  declare @__Result_StoppedBeforeEnd smallint = 5;

  declare @Sql ROW(
    MatchregelName nchar(80),
    Take                        smallint,
    TakeNumber                  integer,
    TakeDistinct                smallint, // 0= Zonder distinct, 1= Met distinct
    Totalfrom long nvarchar,
    TotalFromOuterJoin long nvarchar,
    Totalwhere long nvarchar,
    TotalHaving long nvarchar,
    TotalPartitionWhere long nvarchar,
    TotalPartitionSelect long nvarchar,
    TotalPartitionOp2Fieldnames long nvarchar,
    Precondition long nvarchar
  );

  declare @AantalGevonden integer;

    call Banktransacties_Log('//Banktransacties_VerwerkMatchregels: Begin', 3);

  delete tabBanktransacties_Resultaat where BtresSessieNr = @SessieNr;

  for MatchRegels AS CURSOR_Regels CURSOR FOR
    select
      BtmrGid @BtmrGid,
      BtmrKwaliteit @RegelKwaliteit,
      BtmrNaam @RegelNaam,
      BtmrTake @Take,
      BtmrTakeNumber @TakeNumber,
      BtmrTakeDistinct @TakeDistinct,
      BtmrPrecondition @_Precondition,
      if BtmrSelectBetKopId    <> '' then BtmrSelectBetKopId    + ', ' else '' endif +
      if BtmrSelectBetRglGid   <> '' then BtmrSelectBetRglGid   + ', ' else '' endif +
      if BtmrSelectIncKopId    <> '' then BtmrSelectIncKopId    + ', ' else '' endif +
      if BtmrSelectIncRglGid   <> '' then BtmrSelectIncRglGid   + ', ' else '' endif +
      if BtmrSelectBatchnummer <> '' then BtmrSelectBatchnummer + ', ' else '' endif +
      if BtmrSelectRksGid      <> '' then BtmrSelectRksGid      + ', ' else '' endif +
      if BtmrSelectOspGid      <> '' then BtmrSelectOspGid      + ', ' else '' endif +
      if BtmrSelectBedrag      <> '' then BtmrSelectBedrag      + ', ' else '' endif +
      if BtmrSelectValnummer   <> '' then BtmrSelectValnummer   + ', ' else '' endif +
      if BtmrSelectJrOmschrijving <> '' then BtmrSelectJrOmschrijving + ', ' else 'NULL, ' endif
      @Select,
      if BtmrSelectBetKopId    <> '' then 'BtresBetKopId, ' else '' endif +
      if BtmrSelectBetRglGid   <> '' then 'BtresBetRglGid, ' else '' endif +
      if BtmrSelectIncKopId    <> '' then 'BtresIncKopId, ' else '' endif +
      if BtmrSelectIncRglGid   <> '' then 'BtresIncRglGid, ' else '' endif +
      if BtmrSelectBatchnummer <> '' then 'BtresBatchNummer, ' else '' endif +
      if BtmrSelectRksGid      <> '' then 'BtresRksGID, ' else '' endif +
      if BtmrSelectOspGid      <> '' then 'BtresOspGid, ' else '' endif +
      if BtmrSelectBedrag      <> '' then 'BtresBedrag, ' else '' endif +
      if BtmrSelectValnummer   <> '' then 'BtresValnummer, ' else '' endif +
      'BtresJrOmschrijving, ' // Altijd opgenomen, eventueel met NULL
      @Into,
      BtmrOrderBy @OrderBy
    from  tabBanktransacties_Matchregel
    where BtmrSoort = 0 /*Hoofdregel*/
          and BtmrStatus = 1 /*Actief*/
    order by BtmrVolgorde
  for read only
  do
    call Banktransacties_Log('//------------', 4);

    // Test of het wenselijk is om verwerking te stoppen (we gaan dan de volgende keer wel weer verder)
    if exists(select first 1 from systable where table_name = 'tabConvertDisabledEvents') then
      if exists(select first 1 from tabConvertDisabledEvents where cdeEventName = 'OnSelectedInterval_BanktransactiesVerwerken') then
        set @Result = @__Result_StoppedBeforeEnd;
        call Banktransacties_Log('//WARNING Stopped executing due to disabling events');
        leave;
      end if;
    end if;





    if Banktransacties_MatchMoetWordenVerwerkt(@Transactie.EigenBankrekening, @RegelKwaliteit) <> 0 then /*Moet volgens instellingen worden geboekt*/
      call Banktransacties_Log('//Verwerken van matchRegel ''' + @RegelNaam + '''', 7);
      call Banktransacties_Log(
        '//@Select= ''' || @Select || '''\n' ||
        '//@Into= ''' || @Into || ''''
      , 4);

      // Laatste komma verwijderen
      set @Select = substring(@Select, 1, length(@Select) - 2);
      set @Into   = substring(@Into  , 1, length(@Into  ) - 2);

      set @Sql.MatchregelName = @RegelNaam;
      set @Sql.Take = @Take;
      set @Sql.TakeNumber = @TakeNumber;
      set @Sql.TakeDistinct = @TakeDistinct;
      set @Sql.Precondition = @_Precondition;

      //Opschonen
      set @Sql.Totalfrom = '';
      set @Sql.TotalFromOuterJoin = '';
      set @Sql.Totalwhere = '';
      set @Sql.TotalHaving = '';
      set @Sql.TotalPartitionWhere = '';
      set @Sql.TotalPartitionSelect = '';
      set @Sql.TotalPartitionOp2Fieldnames = '';

      call Banktransacties_VerwerkCriteriaPerMatchregel(
        @BtmrGid,
        @Result,
        @Sql,
      );

      call Banktransacties_MatViewOrganize(
        @MatViewUniekNummers,
        @Action = 2 /*Resolve in SQL*/,
        @sql=@Sql);

      call Banktransacties_VerwerkMatchregelSql(@SessieNr, @RegelKwaliteit, @BtmrGid, @Transactie, @Select, @Into, @OrderBy, @Sql, @AantalGevonden);

      // Stoppen als we iets hebben gevonden
      if @AantalGevonden > 0 then
        leave; //MatchRegels
      end if;
    else
      call Banktransacties_Log('//MatchRegel ivm vinkjes bij eigen bankrekening overgeslagen: ''' + @RegelNaam + '''', 7);
    end if;

  end for;

    call Banktransacties_Log('//Banktransacties_VerwerkMatchregels: Done', 3);
end;

/*
begin
  declare @result integer;
  declare @rargid integer;
  declare @sessienr integer;

  select first rargid into @rargid from tabrekeningafschriftregel;

  call Banktransacties_VerwerkMatchregels(
    ROW(
      @rargid,
      ...
    ),
    @sessienr,
    @result
  );

  select
    @sessienr, @result;
end;
*/

create or replace procedure Banktransacties_VerwerkMatchregelSql(
  in  @SessieNr    integer,
  in  @Kwaliteit   integer,
  in  @BtmrGid     integer,
  in  @Transactie ROW(
        Rargid             integer,
        EigenBankrekening  nchar(34),
        BankrekeningTegenpartij nchar(34),
        NaamTegenpartij         nchar(40),
        Boekdatum          DateTime,
        Afschriftnummer    integer,
        Postnummer         integer,
        E2E                nchar(40),
        Betalingskenmerk   nchar(40),
        Batch_AantalRegels integer,
        Bedrag             numeric(15,2),
        Valnummer          integer,
        IsBijboeking       smallint,
        TussenRksGid       integer,
        Boekreferentie     nchar(40),
        Omschrijving       long nvarchar,
        OmschrijvingZonderCrLf long nvarchar
      ),
  in @TotalSelect long nvarchar,
  in @TotalInto   long nvarchar,
  in @OrderBy     long nvarchar,
  in  @Sql ROW(
        MatchregelName              nchar(80),
        Take                        smallint,
        TakeNumber                  integer,
        TakeDistinct                smallint, // 0= Zonder distinct, 1= Met distinct
        Totalfrom                   long nvarchar,
        TotalFromOuterJoin          long nvarchar,
        Totalwhere                  long nvarchar,
        TotalHaving                 long nvarchar,
        TotalPartitionWhere         long nvarchar,
        TotalPartitionSelect        long nvarchar,
        TotalPartitionOp2Fieldnames long nvarchar,
        Precondition long nvarchar
      ),
  out @AantalGevonden integer
)
begin
  declare @cmd long nvarchar;
  declare @begintijd DateTime;
  declare @eindtijd DateTime;
  // ivm. ASA-defect de aanroep vervangen door een temp table
  declare s long nvarchar = 'banktransacties_SplitText(@Transactie.Betalingskenmerk + '' '' + @Transactie.Omschrijving)';
  declare l integer;
  declare @PrepareCmd long nvarchar;
  declare @PreConditionAchieved smallint default 1;


    call Banktransacties_Log('//Banktransacties_VerwerkMatchregelSql: Begin', 4);

  set @AantalGevonden = 0;

  if @Sql.Precondition = '' then
    set @PreConditionAchieved = 1; // No precondition, so its ok to continue
  else
    begin
      // Let op, dit werkt doordat het 1 statement is en daardoor in de scope van deze procedure werkt.
      // Als dit wordt aangepast, bijv. naar een if... constructie, dan is het buiten deze scope en is de variabele onvindbaar
      set @AantalGevonden = 0;
      set @begintijd = now();
      execute immediate with batch off 'set @PreConditionAchieved = if ' || @Sql.Precondition || ' then 1 else 0 endif';
      set @eindtijd = now();
    exception
    when others then
      set @PreConditionAchieved = 1; // Precondition contains error, so just continue
    end;
  end if;

  if @PreConditionAchieved = 1 then
    set @cmd = Banktransacties_VerwerkMatchregelSql_CalculateSql(
      @BtmrGid,
      @Kwaliteit,
      @TotalSelect,
      @Totalinto,
      @OrderBy,
      @sql
    );
  end if;



  if @@Banktransacties_LogVerboseBits & power(2,6-1) <> 0 then
    call Banktransacties_Log(
      '//Begin\n' ||
      '//  declare @SessieNr integer = -1;' ||
      '//  declare @Transactie ROW(\n' ||
      '//    Rargid             Integer,\n' ||
      '//    EigenBankrekening  nchar(34),\n' ||
      '//    BankrekeningTegenpartij nchar(34),\n' ||
      '//    Boekdatum          DateTime,\n' ||
      '//    Afschriftnummer    integer,\n' ||
      '//    Postnummer         integer,\n' ||
      '//    E2E                nchar(40),\n' ||
      '//    Betalingskenmerk   nchar(40),\n' ||
      '//    Batch_AantalRegels integer,\n' ||
      '//    Bedrag             numeric(15,2),\n' ||
      '//    Valnummer          integer,\n' ||
      '//    IsBijboeking       smallint,\n' ||
      '//    TussenRksGid       integer,\n' ||
      '//    Boekreferentie     nchar(40),\n' ||
      '//    Omschrijving       long nvarchar,\n' ||
      '//    OmschrijvingZonderCrLf long nvarchar\n' ||
      '//);'
    , 6);

    call Banktransacties_Log(
      '//  set @Transactie.Rargid                  = '   || @Transactie.Rargid                 || ';\n' ||
      '//  set @Transactie.EigenBankrekening       = ''' || @Transactie.EigenBankrekening      || ''';\n' ||
      '//  set @Transactie.BankrekeningTegenpartij = ''' || @Transactie.BankrekeningTegenpartij|| ''';\n' ||
      '//  set @Transactie.Boekdatum               = ''' || @Transactie.Boekdatum              || ''';\n' ||
      '//  set @Transactie.Afschriftnummer         = '   || @Transactie.Afschriftnummer        || ';\n' ||
      '//  set @Transactie.Postnummer              = '   || @Transactie.Postnummer             || ';\n' ||
      '//  set @Transactie.E2E                     = ''' || @Transactie.E2E                    || ''';\n' ||
      '//  set @Transactie.Betalingskenmerk        = ''' || @Transactie.Betalingskenmerk       || ''';\n' ||
      '//  set @Transactie.Batch_AantalRegels      = '   || @Transactie.Batch_AantalRegels     || ';\n' ||
      '//  set @Transactie.Bedrag                  = '   || @Transactie.Bedrag                 || ';\n' ||
      '//  set @Transactie.Valnummer               = '   || @Transactie.Valnummer              || ';\n' ||
      '//  set @Transactie.IsBijboeking            = '   || @Transactie.IsBijboeking           || ';\n' ||
      '//  set @Transactie.TussenRksGid            = '   || isnull(string(@Transactie.TussenRksGid), 'null') + ';\n' ||
      '//  set @Transactie.Boekreferentie          = ''' || @Transactie.Boekreferentie         || ''';\n' ||
      '//  set @Transactie.Omschrijving            = ''' || @Transactie.OmschrijvingZonderCrLf || '''; //ivm CrLf nu de ZonderCrLf gebruikt\n' ||
      '//  set @Transactie.OmschrijvingZonderCrLf  = '''  || @Transactie.OmschrijvingZonderCrLf || ''';'
    , 6);
  end if;


  if @PreConditionAchieved = 0 then
    if @@Banktransacties_LogVerboseBits & power(2,5-1) <> 0 then
      call Banktransacties_Log('// //Precondition not matched: ' || @Sql.Precondition, 5);
    end if;
  else
    // *** Prepare ***
    //TODO Hier wordt nu een soort pre-uitvoering gepleegd, om te voorkomen dat door een defect in ASA de banktransacties_SplitText voor elke NAW wordt aangeroepen.
    set l = locate(@cmd, s);
    if l > 0 then
      set @PrepareCmd = 'declare local temporary table tmpSplitText(WordPartOfText nchar(100)) on commit preserve rows';
      call Banktransacties_Log('//' + @PrepareCmd + ';', 6);
      execute immediate with batch off @PrepareCmd;
      set @PrepareCmd = 'insert into tmpSplitText select WordPartOfText from banktransacties_SplitText(@Transactie.Betalingskenmerk + '' '' + @Transactie.Omschrijving)';
      call Banktransacties_Log('//' + @PrepareCmd + ';', 6);
      execute immediate with batch off @PrepareCmd;
      set @cmd = replace(@cmd, s, 'tmpSplitText');
    end if;

    if @@Banktransacties_LogVerboseBits & power(2,5-1) <> 0 then
      call Banktransacties_Log(@cmd, 5);
    end if;

    call Banktransacties_Log('//Start match: ' + @sql.MatchregelName, 8);
    set @begintijd = now();
    begin
      // LET OP, deze SQL moet single-statement zijn, anders is de scope onjuist!
      execute immediate with batch off @cmd;
      select @@rowcount into @AantalGevonden;
    exception
      when others then
        call Banktransacties_LogToGebruikersLog(_A('Fout bij automatisch verwerken banktransacties (query)'), error_message(), 1 /*Fout*/);
        set @AantalGevonden = 0;
    end;
    set @eindtijd = now();
  end if;

  call Banktransacties_Log('//Milliseconds: ' + string(datediff(millisecond,  @begintijd, @eindtijd)) + '; found: ' + string(@AantalGevonden) + '; Query: ' + @sql.MatchregelName, 8);
  call Banktransacties_Log('//Aantal: ' + string(@AantalGevonden) + if @AantalGevonden > 0 then ' MatchGevonden!\n' else '\n' endif, 5);

  call Banktransacties_Log('//Banktransacties_VerwerkMatchregelSql: Einde', 4);

  // Update statistics per matchregel
  update tabBanktransacties_Matchregel
  set BtmrStatistics_QueryTimeLastExecuted = datediff(millisecond,  @begintijd, @eindtijd),
      BtmrStatistics_AvgQueryTime = (BtmrStatistics_AvgQueryTime * BtmrStatistics_TimesExecuted + datediff(millisecond,  @begintijd, @eindtijd)) / (BtmrStatistics_AvgQueryTime + 1),
      BtmrStatistics_TimesExecuted = BtmrStatistics_TimesExecuted + 1,
      BtmrStatistics_TotalRecordsFound = BtmrStatistics_TotalRecordsFound + @AantalGevonden
  where BtmrGid = @BtmrGid;

end;


create or replace function Banktransacties_VerwerkMatchregelSql_CalculateSql(
  in @BtmrGid integer,
  in @Kwaliteit integer,
  in @TotalSelect long nvarchar,
  in @Totalinto long nvarchar,
  in @OrderBy   long nvarchar,
  in @Sql ROW(
       MatchregelName              nchar(80),
       Take                        smallint,
       TakeNumber                  integer,
       TakeDistinct                smallint, // 0= Zonder distinct, 1= Met distinct
       Totalfrom                   long nvarchar,
       TotalFromOuterJoin          long nvarchar,
       Totalwhere                  long nvarchar,
       TotalHaving                 long nvarchar,
       TotalPartitionWhere         long nvarchar,
       TotalPartitionSelect        long nvarchar,
       TotalPartitionOp2Fieldnames long nvarchar,
       Precondition long nvarchar
     ),
  in @SoortRegel smallint default 0 /*Startregel*/
)
  returns long nvarchar
begin
  declare @_Tabsize nchar(4) = ''; //Default geen tab. Alleen bij preconditie een tab van 4

  declare @_cmd long nvarchar = '';
  declare @_SqlRest long nvarchar = '';
  declare @_Distinct nchar(80);
  declare @_Take nchar(80);

  call Banktransacties_Log('Banktransacties_VerwerkMatchregelSql_CalculateSql', 3);
  //call Banktransacties_Log('@TotalSelect                     = ' + @TotalSelect, 4);
  //call Banktransacties_Log('@TotalInto                       = ' + @TotalInto, 4);
  //call Banktransacties_Log('@Sql.Totalfrom                   = ' + @Sql.Totalfrom                  , 4);
  //call Banktransacties_Log('@Sql.Totalwhere                  = ' + @Sql.Totalwhere                 , 4);
  //call Banktransacties_Log('@Sql.TotalHaving                 = ' + @Sql.TotalHaving                , 4);
  //call Banktransacties_Log('@Sql.TotalPartitionWhere         = ' + @Sql.TotalPartitionWhere        , 4);
  //call Banktransacties_Log('@Sql.TotalPartitionSelect        = ' + @Sql.TotalPartitionSelect       , 4);
  //call Banktransacties_Log('@Sql.TotalPartitionOp2Fieldnames = ' + @Sql.TotalPartitionOp2Fieldnames, 4);

  if @SoortRegel <> 0 then
    set @_cmd = @_cmd + @_Tabsize + '/*Deelregel*/\n';
  else
    set @_cmd = @_cmd + '\n' + @_Tabsize + 'INSERT INTO tabBanktransacties_Resultaat(\n' +
                @_Tabsize + 'BtresSessieNr, BtresBtmrGid, BtresKwaliteit, ' + @Totalinto + '\n' + @_Tabsize + ')';
  end if;

  if @Sql.TotalFrom <> '' then
    set @_SqlRest = @_SqlRest + '\n' + @_Tabsize + 'FROM (' + @Sql.TotalFrom + ') ';
  end if;
  if @Sql.TotalfromOuterJoin <> '' then
    set @_SqlRest = @_SqlRest + @Sql.TotalfromOuterJoin;
  end if;

  if @Sql.TotalWhere <> '' then
    set @_SqlRest = @_SqlRest + '\n' + @_Tabsize + 'WHERE ' + replace(@Sql.TotalWhere, '\n', '\n' + @_Tabsize);
  end if;

  if @Sql.Totalhaving <> '' then
    set @_SqlRest = @_SqlRest +
      '\n' + @_Tabsize + 'GROUP BY\n  ' + @TotalSelect +
      '\n' + @_Tabsize + 'HAVING' + @Sql.TotalHaving;
  end if;

  set @_Distinct = if @OrderBy = '' and @Sql.TakeDistinct = 1 then 'DISTINCT ' else '' endif;

  case @Sql.Take
    when 0 then // Alles
      set @_Take = '';
    when 1 then // First
      set @_Take = 'First';
    when 2 then // last
      set @_Take = 'Last';
    when 3 then // Top ...
      set @_Take = 'Top ' + string(@sql.TakeNumber);
    when 4 then // Bottom ...
      set @_Take = 'Bottom ' + string(@sql.TakeNumber);
  end case;

// Bij een normale query, dan is de TotalSelect goed. Anders moet deze worden gesplitst:
// De velden met een naam moeten in de PartitionSelect alleen de naam, in de innerselect de hele berekening incl. naam
// Als de naam al voorkomt, dan niet opnemen in de innerselect!

  // partitioned? Dan met WITH table werken!
  if @Sql.TotalPartitionWhere <> '' or @Sql.TotalPartitionSelect <> '' then
    begin
      // We gebruiken een partition, dus een soort temporary table.
      // De selectie daarbuiten wordt dan de PartitionSelect (dus de select uit die partitie)
      // terwijl in die partitie de meeste restricties worden geplaatst
      // Restricties die expliciet buiten die partitie moeten plaatsvinden staan in de @Sql.TotalPartitionWhere
      declare @InnerSelect long nvarchar;
      declare @OrderByToSelection long nvarchar = '';
      declare @OrderByToOrderBy long nvarchar = '';

      // Alleen de namen overnemen in de outer select
      set @InnerSelect = @TotalSelect;
      select list(code, ',') into @InnerSelect from splitCode(@TotalSelect, ',') where code <> 'NULL'; // Fiets NULL values eruit, horen niet in de inner
      select list(substring(code, locate(code, ' ', -1)), ',') into @TotalSelect from splitCode(@TotalSelect, ',');

      // De OrderBy excl. ASC/DESC, waarbij de velden altijd een automatische naam krijgen
      select list(Value + ' ' + Name, ',\n'),
             list(Name + AscDesc, ', ')
      into @OrderByToSelection, @OrderByToOrderBy
      from (
        select
          case
            when right(Code, 4) =' ASC' then length(Code) - 4
            when right(Code, 5) =' DESC' then length(Code) - 5
            when right(Code, 4) ='\x09ASC' then length(Code) - 4
            when right(Code, 5) ='\x09DESC' then length(Code) - 5
            else length(Code)
          end AscDescPos,
        left(Code, AscDescPos) Value,
        substring(Code, AscDescPos + 1) AscDesc,
        'OrderBy_' + string(ListGid) Name
        from
          SplitCode(@OrderBy, ',')
      ) A;

      set @_cmd = @_cmd + '\n' + @_Tabsize + 'WITH PartitionedTable AS(\n';
      set @_cmd = @_cmd + @_Tabsize + '  SELECT ' + @InnerSelect;
      if @Sql.TotalPartitionSelect <> '' then
        set @_cmd = @_cmd + ',\n' + @_Tabsize + replace(@Sql.TotalPartitionSelect, '\n', '\n' + @_Tabsize);
      end if;

      if @OrderBy <> '' then
        set @_cmd = @_cmd + ',\n\n' + @_Tabsize + replace(@OrderByToSelection, '\n', '\n' + @_Tabsize);
      end if;

      set @_cmd = @_cmd + '\n' + @_SqlRest + '\n' + @_Tabsize + ')\n';
      set @_cmd = @_cmd + '\n' + @_Tabsize + 'SELECT ' + @_Distinct + @_Take + ' @SessieNr, ' + string(@BtmrGid) + ', ' + string(@Kwaliteit) + ', ' + @TotalSelect;
      set @_cmd = @_cmd + '\n' + @_Tabsize + 'FROM PartitionedTable';

      if @Sql.TotalPartitionWhere <> '' then
        set @_cmd = @_cmd + '\n' + @_Tabsize + 'WHERE ' + replace(@Sql.TotalPartitionWhere, '\n', '\n' + @_Tabsize);
      end if;
      if @OrderBy <> '' then
        set @_cmd = @_cmd + '\n' + @_Tabsize + 'ORDER BY ' + @OrderByToOrderBy;
      end if;
    end;
  else
    set @_cmd = @_cmd + '\n' + @_Tabsize + 'SELECT ' + @_Distinct + @_Take + ' @SessieNr, ' + string(@BtmrGid) + ', ' + string(@Kwaliteit) + ', ' + @TotalSelect + @_SqlRest;
    if @OrderBy <> '' then
      set @_cmd = @_cmd + '\n' + @_Tabsize + 'ORDER BY ' + @OrderBy;
    end if;
  end if;

  return @_cmd;
end;


create or replace procedure Banktransacties_VerwerkTransactie(
  in    @SessieNr integer,
  in    @RarGid integer,
  in    @DgbGidEigenBankrekening integer,
  inout @BoekgangGid integer,
  inout @MatViewUniekNummers ROW(
          vwVoorraadaantallen             integer,
          vwBackorderAantallen            integer,
          vwVoorraadAantallenKlein        integer,
          vwBestelKopTotalen              integer,
          vwMeestRecenteOpenstaandePosten integer
        ),
  out   @Result smallint // 0 = OK, 1 = Boekjaar/periode gelokkeerd
)
begin
  // Resultaten
  declare @__Result_OK smallint = 0;
  //declare @__Result_LockNietGelukt smallint = 1; // hier niet gebruikt, zie Banktransacties_VerwerkTransacties
  declare @__Result_Geblokkeerd smallint = 2;
  declare @__Result_PeriodeNietGevonden smallint = 3;
  declare @__Result_BoekingsgangKanNietWordenAangemaakt smallint = 4;

  // Gegevens uit formaat
  declare @Instelling_Stuknummer smallint; // 0 = Stuknummer=afschriftnummer, 1 = volgens dagboekinstelling
  declare @Instelling_Volgnummer smallint; // 0 = Postnummer afschrift, 1 = Autom. genereren
  declare @Instelling_JournaalpostOmschrijving smallint; // 0 = transactieomschrijving, 1 = nummer+naam tegenrekening

  // Boekgegevens
  declare @TeBoekenInBjGid integer;
  declare @TeBoekenInPerNr integer;

  // Gegevens uit de transactie
  declare @Transactie ROW(
    Rargid             Integer,
    EigenBankrekening  nchar(34),
    BankrekeningTegenpartij nchar(34),
    NaamTegenpartij         nchar(40),
    Boekdatum          DateTime,
    Afschriftnummer    integer,
    Postnummer         integer,
    E2E                nchar(40),
    Betalingskenmerk   nchar(40),
    Batch_AantalRegels integer,
    Bedrag             numeric(15,2),
    Valnummer          integer,
    IsBijboeking       smallint,
    TussenRksGid       integer,
    Boekreferentie     nchar(40),
    Omschrijving       long nvarchar,
    OmschrijvingZonderCrLf long nvarchar
  );

    call Banktransacties_Log('//Banktransacties_VerwerkTransactie: Begin; @Rargid='+string(@Rargid), 3);

  set @result = @__Result_OK;


  // Transactiegegevens lezen
  // Keuzes qua boekdatum van JP, boekdatum van JR, Stuk- en volgnummer en Omschrijving journaalregel moeten hier ergens komen

  select Rargid,
         RakBankGiro,
         RarBankGiro,
         RarNaamRekhouder,
         isnull(RarBoekdatum, RarValutadatum),
         RarAfschriftnr,
         RarPostnr,
         EbrRksGID,
         RarBoekReferentie,
         RarE2E,
         RarBetKenmerk,
         RarBatchTransacties,
         RarBedrag - RarBedragAlGeboekt,
         RarValNummer,
         RarIsErbij,
         1 /*Geen instelling, maar altijd conform dagboekinstelling*/,
         1 /*Geen instelling, maar altijd autom.genereren*/,
         EbrBoekOmschrijving, /*0=transactieomschrijving, 1=nr+naam tegenrekeninghouder*/
         RarOms,
         replace(replace(replace(RarOms, '\n', ' '), char(13), ' '), char(10), ' ')
  into   @transactie.Rargid,
         @transactie.EigenBankrekening,
         @transactie.BankrekeningTegenpartij,
         @transactie.NaamTegenpartij,
         @transactie.Boekdatum,
         @transactie.Afschriftnummer,
         @transactie.Postnummer,
         @transactie.TussenRksGid,
         @transactie.BoekReferentie,
         @transactie.E2E,
         @transactie.Betalingskenmerk,
         @transactie.Batch_AantalRegels,
         @transactie.Bedrag,
         @transactie.Valnummer,
         @transactie.IsBijboeking,
         @Instelling_Stuknummer,
         @Instelling_Volgnummer,
         @Instelling_JournaalpostOmschrijving,
         @transactie.Omschrijving,
         @transactie.OmschrijvingZonderCrLf
  from    tabRekeningafschriftRegel
          inner join tabRekeningafschriftKop on Rakgid = RarRakgid
          //inner join tabTelebankFormaten on TbfId = RakBankFormaat
          inner join tabEigenBankRekening on EbrBankRekeningNummer = RakBankGiro
  where Rargid = @Rargid;

  // Boekreferentie op de transactie bepalen als die leeg was
  if isnull(@transactie.BoekReferentie, '') = '' then
    call Banktransacties_LeesOfGenereerBoekReferentie(@Rargid, @transactie.BoekReferentie, @Result);
    if @Result <> @__Result_OK then
      call Banktransacties_Log('//ERROR result LeesOfGenereerBoekReferentie='+string(@Result), 1);
      return;
    end if;
  end if;

  // Boekjaar/periode opzoeken
  call Banktransacties_ZoekBoekjaar(
    @transactie.Boekdatum,
    @TeBoekenInBjGid,
    @TeBoekenInPerNr,
    @result
  );
  if @result <> @__Result_OK then
    // Logging is al in ZoekBoekjaar doorgevoerd
    //call Banktransacties_Log('//ERROR result ZoekBoekjaar='+string(@Result), 1);
    return;
  end if;

  // Eerst van alles gaan zoeken
  call Banktransacties_VerwerkMatchregels(@Transactie, @SessieNr, @MatViewUniekNummers, @Result);

  if @result <> @__Result_OK then
    call Banktransacties_Log('//ERROR bij verwerken van de matchregels='+string(@Result), 1);
    return;
  end if;

  // Daarna controleren of wat is gevonden voldoende match heeft om automatisch te boeken


  // Doorlopen van de gematchte regels en boeken in journaalpost
    call Banktransacties_Log('//Banktransacties_VerwerkTransactie: call Banktransacties_VerwerkGevondenMatches', 4);
  call Banktransacties_VerwerkGevondenMatches(
    @SessieNr,
    @BoekGangGid,
    @transactie,
    @Instelling_Stuknummer,
    @Instelling_Volgnummer,
    @Instelling_JournaalpostOmschrijving,
    @TeBoekenInBjGid,
    @TeBoekenInPerNr,
    @DgbGidEigenBankrekening,
    @Result
  );

  call Banktransacties_Log('//Banktransacties_VerwerkTransactie: Einde; @Rargid='+string(@Rargid), 3);

/*
begin
  declare @Rargid integer;
  declare @DgbGid integer;
  declare @BoekgangGid integer;
  declare @result integer;

  select first rargid into @Rargid from tabRekeningafschriftRegel;
  select DgbGid into @DgbGid from tabDagboek where DgbCode='bank';

  call trace(' ');
  call trace(' ');
  call trace(' ');
  call trace(' *** STARTEN ZOEKROUTINE ***');
  call trace(' ');
  call trace(' ');
  call trace(' ');
  call Banktransacties_VerwerkTransactie(
    @Rargid,
    @DgbGid, //@DgbGidEigenBankrekening integer,
    @BoekgangGid,
    @Result
  );
  select @Result, @BoekgangGid;
end;
*/

end;



create or replace procedure Banktransacties_VerwerkTransacties(
  in @Rakgid integer default null,
  out @Result smallint) // 0 = OK, 1 = set lock fail
begin
  declare @BoekgangGid integer = null; // Wordt indien nodig aangemaakt in VerwerkTransactie
  declare @LastLockedRakGid integer = null;
  declare @LastEigenBankrekening nchar(40) = '';
  declare @FailedLockRakGid integer = null; // Niet eindeloos dezelfde Rak proberen te locken
  declare @LockIsGelukt smallint;
  declare @SessieNr integer;
  declare @MatViewUniekNummers ROW(
          vwVoorraadaantallen             integer,
          vwBackorderAantallen            integer,
          vwVoorraadAantallenKlein        integer,
          vwBestelKopTotalen              integer,
          vwMeestRecenteOpenstaandePosten integer
          );

  // Hieronder alle gebruikte resultaten
  declare @__Result_OK                                  smallint = 0;
  declare @__Result_LockNietGelukt                      smallint = 1;
  declare @__Result_Geblokkeerd                         smallint = 2;
  declare @__Result_PeriodeNietGevonden                 smallint = 3;
  declare @__Result_BoekingsgangKanNietWordenAangemaakt smallint = 4;
  declare @__Result_StoppedBeforeEnd                    smallint = 5;
  declare @__Result_CircularReferenceInRegels           smallint = 10;
  declare @__Result_NieuweBoekingsgangGegenereerd       smallint = 100;
  declare @__Result_FoutBijBoekreferentie               smallint = 101;

  set @Result = @__Result_OK;

  begin // for exception handling

  // Sessienummer controleren of aanmaken
  call MaakUniekSessieNummer(@SessieNr);

  FOR @@FORLOOP_Transacties AS @@CURSOR_Transacties CURSOR FOR
    select
      RakBankGiro @EigenBankrekening,
      Rargid @RarGid,
      RarRakgid @RarRakGid,
      EbrDgbGid @DgbGid,
      RarBedrag - RarBedragAlGeboekt @BedragNogTeBoekenOpTegenrekening,
      RarBedrag - RarBedragAlGeboekt +
      // Saldo van wat op de tussenrekening is geboekt voor dezelfde referentie als deze transactie
      // Bijboeking? Dan creditboekingen erbij, debetboekingen eraf en vice versa
      isnull(
        if EbrRksGID is not null and RarBoekreferentie <> '' then
          (RarIsErbij*2-1) * (select sum(JrBasisBedrag * (IsCreditBoeking*2-1)) from tabJournaalRegel where JrRksGID = EbrRksGID and JrReferentie = RarBoekreferentie)
        endif
      ,0) @BedragTeBoeken
    from
      tabRekeningAfschriftRegel
      inner join tabRekeningafschriftKop on Rakgid = RarRakgid
      inner join tabEigenBankrekening on EbrBankrekeningNummer = RakBankGiro  // Alleen die transacties waar ook een eigen bankrekening met dagboek voor is gevonden
    where
      (@BedragNogTeBoekenOpTegenrekening <> 0
       or @BedragTeBoeken <> 0)
      and @DgbGid is not null /*Geen dagboek, dan niet boeken!*/
      and (@Rakgid is null or Rakgid = @Rakgid) // Als we een Rakgid hebben, dan alleen de regels van die batch verwerken
      and EbrAutomBoekenNaOntvangst = 1 // Alleen autom. boeken als dat zo hoort volgens de eigen bankrekening
      and isnull(RarBoekdatum, RarValutadatum) >= EbrAutomBoekenNaOntvangstDatumVanaf // En alleen vanaf de opgegeven datum (geen datum=niks boeken)
    order by
      @RarGid
  for read only
  do
    // Test of het wenselijk is om verwerking te stoppen (we gaan dan de volgende keer wel weer verder)
    if exists(select first 1 from systable where table_name = 'tabConvertDisabledEvents') then
      if exists(select first 1 from tabConvertDisabledEvents where cdeEventName = 'OnSelectedInterval_BanktransactiesVerwerken') then
        set @Result = @__Result_StoppedBeforeEnd;
        call Banktransacties_Log('//WARNING Stopped executing due to disabling events');
        leave;
      end if;
    end if;


    // Locking
    if (@LastLockedRakGid is null or @RarRakGid <> @LastLockedRakGid) and (@FailedLockRakGid is null or @RarRakGid <> @FailedLockRakGid) then
      // Als het een ANDERE eigen bankrekening is, dan ook de boekingsgang vrijgeven, zodat we een nieuwe openen
      if @EigenBankrekening <> @LastEigenBankrekening and @BoekgangGid is not null then
        update tabBoekingsgang
        set    BoekGangInGebruik = 0
        where  BoekGangInGebruik = 1
           and BoekgangGid = @BoekgangGid;
           set @BoekgangGid = null;
      end if;

      if @LastLockedRakGid is not null then
        call Banktransacties_Unlock(@LastLockedRakGid);
        set @LastLockedRakGid = null;
      end if;

      call Banktransacties_Lock(@RarRakGid, @LockIsGelukt);
      case @LockIsGelukt
        when 0 then // NIET gelukt
          if @Result = @__Result_OK then
            set @Result = @__Result_LockNietGelukt;
          end if;
          set @FailedLockRakGid = @RarRakGid;
          call Banktransacties_Log('//ERROR LockWaitSet Banktransacties_Verwerken(Rak:'+string(@RarRakGid)+')='+string(@Result), 1);
        when 1 then // WEL gelukt
          set @LastLockedRakGid = @RarRakGid;
          set @FailedLockRakGid = null;
      end case;
    end if;

    set @LastEigenBankrekening = @EigenBankrekening;

    if @LockIsGelukt = 1 then
      begin
        declare @TransactieResult smallint;

        call Banktransacties_VerwerkTransactie(@SessieNr, @RarGid, @DgbGid, @BoekgangGid, @MatViewUniekNummers, @TransactieResult);

        // if @TransactieResult... Stoppen als result fout? Of afhankelijk van soort fout?
        if @TransactieResult <> @__Result_OK then
          call Banktransacties_Log('//ERROR result Banktransacties_VerwerkTransactie(Rar:'+string(@RarGid)+')='+string(@TransactieResult), 1);

          if @Result = @__Result_OK and @TransactieResult not in (
            /*Deze fouten worden genegeerd, zodat alsnog wordt doorgegeven dat het allemaal is gelukt*/
            @__Result_Geblokkeerd,
            @__Result_PeriodeNietGevonden,
            @__Result_NieuweBoekingsgangGegenereerd
          ) then
            set @Result = @TransactieResult;
          end if;
        end if;
      end;
    end if;

  end for;

  // ACW Make sure all locks etc. are released on exceptions (Events should always leave a clean desk)
  // However, if the connection is terminated, this clean-up will not be executed, leaving a dirty desk for someone else to cleanup...
  exception when others then
    call Banktransacties_Cleanup(@SessieNr, @LastLockedRakGid, @BoekgangGid, @MatViewUniekNummers);
    resignal;
  end;
  call Banktransacties_Cleanup(@SessieNr, @LastLockedRakGid, @BoekgangGid, @MatViewUniekNummers);

end;


create or replace function Banktransacties_VolgendStukVolgnummer(in @JpGid integer)
returns integer
begin
  declare @Stuknummer integer;
  declare @StukVolgnummer integer;
  declare @DgbGid integer;
  declare @BjGid integer;

  //call TraceBegin('VolgendStukVolgnummer > @JpGid = ' + string(@JpGid));

  // Opzoeken gegevens journaalpost
  select BoekStukNummer, JpDgbGid, JpBjGid into @Stuknummer, @DgbGid, @BjGid from tabJournaalpost where JpGid = @JpGid;

  //Opzoeken hoogste stukvolgnummer met zelfde stuknummer etc.
  select first StukVolgnr + 1
  into   @StukVolgnummer
  from   tabjournaalregel
         inner join tabjournaalpost JpBuiten on JpGid = JrJpGid
  where  JpBjGid = @BjGid
     and JpDgbGid = @DgbGid
     and BoekStukNummer = @Stuknummer
     and exists(select first 1 from tabjournaalregel JrBinnen where JrBinnen.JrRargid is not null and JrBinnen.JrJpGid = JpBuiten.JpGid)
  order by stukvolgnr desc;

  if @StukVolgnummer is null then
    set @StukVolgnummer = VolgendStukVolgnummer(@JpGid);
  end if;

  if @StukVolgnummer > 999 then
    set @StukVolgnummer=999;
  end if;

  //call TraceEind('VolgendStukVolgnummer > @StukVolgnummer = ' + string(@StukVolgnummer););
  return(@StukVolgnummer);

end;


create or replace procedure Banktransacties_ZoekBankrekening(
  in @BankRekeningBinnen nchar(34)
)
result (
  NawRekBankRekening    nchar(34),
  NawRekSoort           nchar(8),
  NawRekNaamRekHouder   nchar(70),
  NawRekPlaatsRekHouder nchar(70),
  NawFilNummer          nchar(10))
begin
  select     NawRekBankRekening, NawRekSoort, NawRekNaamRekHouder, NawRekPlaatsRekHouder, NawFilNummer
  from       TabNawRekening
  inner join TabNawFile on NawFilNawGid = NawRekNawGid
  where      (NawFilFonId in ('D','C'))
             and (NawRekBankRekening = @BankRekeningBinnen)
             and (length(@BankRekeningBinnen) > 2);
end;


create or replace procedure Banktransacties_ZoekBoekjaar(
  in @transactie_Boekdatum date,
  out @TeBoekenInBjGid     integer,
  out @TeBoekenInPerNr     integer,
  out @result              integer
)
begin
  declare @__Result_OK smallint = 0;
  declare @__Result_Geblokkeerd smallint = 2;
  declare @__Result_PeriodeNietGevonden smallint = 3;

  declare @TeBoekenIsGeblokkeerd smallint;

  set @result = @__Result_OK;

  select BjGID, PerNr, BjIsGeblokkeerd+PerIsGeblokkeerd
  into @TeBoekenInBjGid, @TeBoekenInPerNr, @TeBoekenIsGeblokkeerd
  from tabBoekjaar
       inner join tabPeriode on PerBjGid = BjGid
  where @transactie_Boekdatum between BjBeginDatum and BjEindDatum
    and @transactie_Boekdatum between BeginDatum and EindDatum;
  if @TeBoekenInBjGid is null then
    set @result = @__Result_PeriodeNietGevonden;
    call Banktransacties_Log('Fout in ZoekBoekjaar, Periode niet gevonden! Boekdatum: ' +string(@transactie_Boekdatum), 1);
    return;
  end if;
  if @TeBoekenIsGeblokkeerd > 0 then
    set @result = @__Result_Geblokkeerd;
    call Banktransacties_Log('Periode/Boekjaar is geblokkeerd! Boekdatum: ' +string(@transactie_Boekdatum), 2);
    return;
  end if;

end;


create or replace procedure Banktransacties_tool_BerekenSqlVoorMatchregel(
  in    @BtmrGid integer
)
result
(
  Result integer,
  SqlTake                        smallint,
  SqlTakeNumber                  integer,
  SqlTakeDistinct                smallint,
  SqlTotalfrom                   long nvarchar,
  SqlTotalfromOuterJoin          long nvarchar,
  SqlTotalwhere                  long nvarchar,
  SqlTotalHaving                 long nvarchar,
  SqlTotalPartitionWhere         long nvarchar,
  SqlTotalPartitionSelect        long nvarchar,
  SqlTotalPartitionOp2Fieldnames long nvarchar,
  Precondition long nvarchar
)
begin
  declare @_Sql ROW(
        MatchregelName nchar(80),
        Take smallint,
        TakeNumber integer,
        TakeDistinct smallint, // 0= Zonder distinct, 1= Met distinct
        Totalfrom long nvarchar,
        TotalFromOuterJoin long nvarchar,
        Totalwhere long nvarchar,
        TotalHaving long nvarchar,
        TotalPartitionWhere long nvarchar,
        TotalPartitionSelect long nvarchar,
        TotalPartitionOp2Fieldnames long nvarchar,
        Precondition long nvarchar
      );
  declare @_Result integer;

  declare @_BtmrTake, @_BtmrTakeNumber, @_BtmrTakeDistinct integer;
  declare @_BtmrPreCondition long nvarchar;

  call traceBegin('Banktransacties_tool_BerekenSqlVoorMatchregel');

  select BtmrTake, BtmrTakeNumber, BtmrTakeDistinct, BtmrPrecondition
  into @_BtmrTake, @_BtmrTakeNumber, @_BtmrTakeDistinct, @_BtmrPreCondition
  from tabBanktransacties_Matchregel
  where BtmrGid = @BtmrGid;

  set @_Sql.Take = @_BtmrTake;
  set @_Sql.TakeNumber = @_BtmrTakeNumber;
  set @_Sql.TakeDistinct = @_BtmrTakeDistinct;

  set @_Sql.Totalfrom = '';
  set @_Sql.TotalFromOuterJoin = '';
  set @_Sql.Totalwhere = '';
  set @_Sql.TotalHaving = '';
  set @_Sql.TotalPartitionWhere = '';
  set @_Sql.TotalPartitionSelect = '';
  set @_Sql.TotalPartitionOp2Fieldnames = '';

  set @_Sql.Precondition = @_BtmrPreCondition;

  call Banktransacties_VerwerkCriteriaPerMatchregel(
    @BtmrGid,
    @_Result,
    @_Sql,
    1 //@Levelcounter
  );

  select  @_Result,
          @_Sql.Take,
          @_Sql.TakeNumber,
          @_Sql.TakeDistinct,
          @_Sql.Totalfrom,
          @_Sql.TotalFromOuterJoin,
          @_Sql.Totalwhere,
          @_Sql.TotalHaving,
          @_Sql.TotalPartitionWhere,
          @_Sql.TotalPartitionSelect,
          @_Sql.TotalPartitionOp2Fieldnames,
          @_Sql.Precondition;

  call traceEind('Banktransacties_tool_BerekenSqlVoorMatchregel');
end;


create or replace function Banktransacties_tool_CalculateSql(
  in @BtmrGid integer,
  in @Kwaliteit integer,
  in @TotalSelect long nvarchar,
  in @Totalinto long nvarchar,
  in @SqlTake                        smallint,
  in @SqlTakeNumber                  integer,
  in @SqlTakeDistinct                smallint,
  in @SqlTotalfrom                   long nvarchar,
  in @SqlTotalFromOuterJoin          long nvarchar,
  in @SqlTotalwhere                  long nvarchar,
  in @SqlTotalHaving                 long nvarchar,
  in @SqlTotalPartitionWhere         long nvarchar,
  in @SqlTotalPartitionSelect        long nvarchar,
  in @SqlTotalPartitionOp2Fieldnames long nvarchar,
  in @SoortRegel smallint default 0, /*Startregel*/
  in @Precondition long nvarchar default ''
)
  returns long nvarchar
begin
  declare @_OrderBy long nvarchar;

  declare @_Sql ROW(
        MatchregelName              nchar(80),
        Take                        smallint,
        TakeNumber                  integer,
        TakeDistinct                smallint, // 0= Zonder distinct, 1= Met distinct
        Totalfrom                   long nvarchar,
        TotalFromOuterJoin          long nvarchar,
        Totalwhere                  long nvarchar,
        TotalHaving                 long nvarchar,
        TotalPartitionWhere         long nvarchar,
        TotalPartitionSelect        long nvarchar,
        TotalPartitionOp2Fieldnames long nvarchar,
        Precondition long nvarchar
      );
  set @_Sql.MatchregelName = 'Tool: calculating SQL';
  set @_Sql.Take                        = @SqlTake                       ;
  set @_Sql.TakeNumber                  = @SqlTakeNumber                 ;
  set @_Sql.TakeDistinct                = @SqlTakeDistinct               ;
  set @_Sql.Totalfrom                   = @SqlTotalfrom                  ;
  set @_Sql.TotalfromOuterJoin          = @SqlTotalfromOuterJoin         ;
  set @_Sql.Totalwhere                  = @SqlTotalwhere                 ;
  set @_Sql.TotalHaving                 = @SqlTotalHaving                ;
  set @_Sql.TotalPartitionWhere         = @SqlTotalPartitionWhere        ;
  set @_Sql.TotalPartitionSelect        = @SqlTotalPartitionSelect       ;
  set @_Sql.TotalPartitionOp2Fieldnames = @SqlTotalPartitionOp2Fieldnames;
  set @_Sql.Precondition = @Precondition; //'@Transactie.BankrekeningTegenpartij <> '''''

  select BtmrOrderBy into @_OrderBy
  from tabBanktransacties_Matchregel
  where BtmrGid = @BtmrGid;

  return Banktransacties_VerwerkMatchregelSql_CalculateSql(
    @BtmrGid,
    @Kwaliteit,
    @TotalSelect,
    @Totalinto,
    @_OrderBy,
    @_Sql,
    @SoortRegel
  );

end;


create or replace procedure Dashboard_Artikel_Aantal_Per_Kwartaal(in @ArtGid integer)
result(Boekjaar nchar(10), Kwartaal1 numeric(15,3), Kwartaal2 numeric(15,3), Kwartaal3 numeric(15,3), Kwartaal4 numeric(15,3), Totaal numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select Code as BoekJaar,
         //1e kwartaal
         IsNull(sum(if ((OmzDatum >= BjBeginDatum)                     and (OmzDatum < DATEADD( month,  3, BjBeginDatum))) then OmzAantal else 0.00 endif), 0.00) as Kwartaal1,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 3, BjBeginDatum)) and (OmzDatum < DATEADD( month,  6, BjBeginDatum))) then OmzAantal else 0.00 endif), 0.00) as Kwartaal2,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 6, BjBeginDatum)) and (OmzDatum < DATEADD( month,  9, BjBeginDatum))) then OmzAantal else 0.00 endif), 0.00) as Kwartaal3,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 9, BjBeginDatum)) and (OmzDatum < DATEADD( month, 12, BjBeginDatum))) then OmzAantal else 0.00 endif), 0.00) as Kwartaal4,
         IsNull(Kwartaal1 + Kwartaal2 + Kwartaal3 + Kwartaal4, 0.00) as Totaal
  from   tabBoekjaar
         left outer join tabOmzet on (OmzFinBjGid = bjGid) and (OmzArtGid = @ArtGid)
  where BjGid in (select top 5 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
  group by BjBeginDatum, BoekJaar
  order by BjBeginDatum, BoekJaar;
end;


create or replace procedure Dashboard_Artikel_Aantal_Per_Periode(in @ArtGid integer)
result(BoekjaarCode nchar(10), PerNr smallint, Aantal numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select Code, PerNr, IsNull(sum(OmzAantal), 0 )
  from   tabBoekjaar
  inner join tabPeriode on (PerBjGid = BjGid)
  left outer join tabOmzet on (OmzFinBjGid = bjGid and OmzFinPerNr = PerNr and OmzArtGid = @ArtGid)
  where BjGid in (select top 3 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
  group by Code, PerNr
  having PerNr <> 0
  order by Code, PerNr
end;


create or replace procedure Dashboard_Artikel_Debiteuren_Hoogste_Omzet(in @ArtGid integer)
result(NawGid integer, NawNummer nchar(20), NawNaam nchar(40), Omzet numeric(15,3), Percentage numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr       smallint;
  declare @OmzetTotaal Numeric(15,3);

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  //bepaal totale omzet van artikel van afgelopen 12 maanden
  select SUM(OmzOmzetBasis) into @OmzetTotaal from tabOmzet where (OmzArtGid = @ArtGid) and (OmzArtSoort <> 0) and ((omzDatum > DATEADD( month, -12, @Peildatum)) and (omzDatum <=@Peildatum));

  //ophalen top 10 debiteuren met meeste omzet
  select top 10
         NawGid,
         NawFilNummer,
         AdrNaam1,
   		   SUM(OmzOmzetBasis) as Omzet,
         (if @OmzetTotaal <> 0.0 then cast((Omzet/(@OmzetTotaal/100)) as numeric (15,3)) else 0.0 endif) as Percentage
  from   tabOmzet
  inner join (tabNaw inner join tabNawFile on NawFilNawGid = NawGid inner join tabAdres on AdrGid = NawGidVestiging) on NawGid = OmzNawGid and NawFilFonId = 'D'
  where (OmzArtGid = @ArtGid)
         and (OmzArtSoort <> 0)
		 and ((omzDatum > DATEADD( month, -12, @Peildatum)) and (omzDatum <=@Peildatum))
  group by NawGid, NawFilNummer, AdrNaam1
  order by Omzet Desc, NawFilNummer Desc
end;


create or replace procedure Dashboard_Artikel_Debiteuren_Meest_verkocht(in @ArtGid integer)
result(NawGid integer, NawNummer nchar(20), NawNaam nchar(40), AantalVerkocht numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr       smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select top 10
     NawGid,
     NawFilNummer,
		 AdrNaam1,
   	 SUM(omzAantal) Aantal

  from   tabOmzet
    inner join (tabNaw inner join tabNawFile on NawFilNawGid = NawGid inner join tabAdres on AdrGid = NawGidVestiging) on NawGid = OmzNawGid and NawFilFonId = 'D'
  where (OmzArtGid = @ArtGid)
		 and ((omzDatum > DATEADD( month, -12, @Peildatum)) and (omzDatum <=@Peildatum))
  group by NawGid, NawFilNummer, AdrNaam1
  order by Aantal Desc, NawFilNummer Desc
end;



create or replace procedure Dashboard_Artikel_Mutaties_12Maanden(in @ArtGid integer)
result(BoekjaarCode nchar(10), PerNr smallint, AantalOpboeking numeric(15,3), AantalAfboeking numeric(15,3), AantalCorrectie numeric(15,3), AantalVoorraad numeric(15,3))
begin
  declare @Peildatum     date;
  declare @HuidigBjGid   integer;
  declare @Pernr         smallint;

  declare @Id            integer;
  declare @Delta         numeric(15,3);

  declare @CumVoorraad   numeric(15,3);

  //declare @ArtGid integer = 44;

  declare local temporary table tmpMutaties12Maanden
  ( Id              integer default autoincrement,
    Code            nchar(10),
    PerNr           smallint,
    AantalOpboeking numeric(15,3),
    AantalAfboeking numeric(15,3),
    AantalCorrectie numeric(15,3),
    AantalVoorraad  numeric(15,3),
    IsBerekend      smallint,
    primary key (Id)
  ) on commit preserve rows;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  insert into tmpMutaties12Maanden (Code, PerNr, AantalOpboeking, AantalAfboeking, AantalCorrectie, AantalVoorraad, IsBerekend)
    select Code, PerNr, // Alleen bij 6 en 7 is het teken van belang
      sum(if IsNull(VrdMutSoort,-1) in (-1,0,6,7,10,11)    and (not IsNull(VrdMutSoort,-1) in (6,7) or IsNull(VrdMutAantal,0) > 0) then  IsNull(VrdMutAantal,0) else 0 endif) AantalOpboeking,
      sum(if IsNull(VrdMutSoort,-1) in (-1,1,4,6,7,8,9,12) and (not IsNull(VrdMutSoort,-1) in (6,7) or IsNull(VrdMutAantal,0) < 0) then -IsNull(VrdMutAantal,0) else 0 endif) AantalAfboeking,
      sum(if IsNull(VrdMutSoort,-1) in (-1,2,3,5)                                                                        then  IsNull(VrdMutAantal,0) else 0 endif) AantalCorrectie,
      0 AantalVoorraad,
      0 IsBerekend
    from   tabBoekjaar
    inner join tabPeriode on (PerBjGid = BjGid) and (BeginDatum >= DATEADD( month, -12, @Peildatum)) and (BeginDatum < @Peildatum)
    left outer join tabVoorraadMutatie on (VrdMutPerLogBjGid = bjGid and VrdMutPerLogPernr = PerNr and VrdMutArtGid = @ArtGid)
    group by Code, PerNr, BeginDatum, Einddatum
    having PerNr <> 0
    order by BeginDatum;

    // Bepaal de beginvoorraad op de dag vÃ³Ã³r de 1e dag van de 1e getoonde periode
    set @CumVoorraad = GeefArtikelVoorraadOpDatum(@ArtGid, (SELECT MIN(BeginDatum)-1
														    FROM tabBoekjaar
															inner join tabPeriode on (PerBjGid = BjGid) and
																					 (BeginDatum >= DATEADD( month, -12, @Peildatum)) and
																					 (BeginDatum < @Peildatum)
															)
												 );

    LoopBijwerkenVoorraad:
    Loop
      if exists(select 1 from tmpMutaties12Maanden where IsBerekend = 0) then
        select first  Id,  (AantalOpboeking + AantalCorrectie - AantalAfboeking) Delta into @Id, @Delta from tmpMutaties12Maanden where IsBerekend = 0 order by Id;
      else
        leave LoopBijwerkenVoorraad;
      end if;

      set @CumVoorraad = @CumVoorraad + @Delta;

      update tmpMutaties12Maanden set AantalVoorraad = @CumVoorraad, IsBerekend = 1 where Id = @Id;

    end loop LoopBijwerkenVoorraad;

    select Code, PerNr, AantalOpboeking, AantalAfboeking, AantalCorrectie, AantalVoorraad from tmpMutaties12Maanden order by Id;

end;

/*
  //Bron: qdmeta://tabVoorraadMutatie.VrdMutSoort (type: smallint)
  qcFDV_VrdMutSoort_Magazijnontvangst                            = 0;
  qcFDV_VrdMutSoort_Levering                                     = 1;
  qcFDV_VrdMutSoort_Beginvoorraad                                = 2;
  qcFDV_VrdMutSoort_Inventarisatie                               = 3;
  qcFDV_VrdMutSoort_Intern_gebruik                               = 4;
  qcFDV_VrdMutSoort_Uitval                                       = 5;
  qcFDV_VrdMutSoort_Magazijnverplaatsing                         = 6;
  qcFDV_VrdMutSoort_Overig                                       = 7;
  qcFDV_VrdMutSoort_Project                                      = 8;
  qcFDV_VrdMutSoort_Productie_component                          = 9;
  qcFDV_VrdMutSoort_Productie_eindproduct                        = 10;
  qcFDV_VrdMutSoort_Directe_levering_afgeleverd_door_leverancier = 11;
  qcFDV_VrdMutSoort_Directe_levering_ontvangen_door_debiteur     = 12;
  qcFDV_VrdMutSoort_Partij_Registratie_Aangezet                  = 13;

*/

create or replace procedure Dashboard_Artikel_Omzet_Per_Kwartaal(in @ArtGid integer)
result(Boekjaar nchar(10), Kwartaal1 numeric(15,3), Kwartaal2 numeric(15,3), Kwartaal3 numeric(15,3), Kwartaal4 numeric(15,3), Totaal numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select Code as BoekJaar,
         //1e kwartaal
         IsNull(sum(if ((OmzDatum >= BjBeginDatum)                     and (OmzDatum < DATEADD( month,  3, BjBeginDatum))) then OmzOmzetBasis else 0.00 endif), 0.00) as Kwartaal1,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 3, BjBeginDatum)) and (OmzDatum < DATEADD( month,  6, BjBeginDatum))) then OmzOmzetBasis else 0.00 endif), 0.00) as Kwartaal2,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 6, BjBeginDatum)) and (OmzDatum < DATEADD( month,  9, BjBeginDatum))) then OmzOmzetBasis else 0.00 endif), 0.00) as Kwartaal3,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 9, BjBeginDatum)) and (OmzDatum < DATEADD( month, 12, BjBeginDatum))) then OmzOmzetBasis else 0.00 endif), 0.00) as Kwartaal4,
         IsNull(Kwartaal1 + Kwartaal2 + Kwartaal3 + Kwartaal4, 0.00) as Totaal
  from   tabBoekjaar
         left outer join tabOmzet on (OmzFinBjGid = bjGid) and (OmzArtGid = @ArtGid)
  where BjGid in (select top 5 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
  group by BjBeginDatum, BoekJaar
  order by BjBeginDatum, BoekJaar;
end;


create or replace procedure Dashboard_Artikel_Omzet_Per_Periode(in @ArtGid integer)
result(BoekjaarCode nchar(10), PerNr smallint, Bedrag numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

