create or replace procedure Dashboard_Artikel_OpenstaandeBestellingen(in @ArtGid Integer)
result(BstKopGid integer, BstKopNummer numeric(10,0), BstRglGid integer, BstKopAfleverDatum date, BstKopReferentie Long nvarchar, Eenheid nchar(40),
       BstRglAantalNogTeOntvangen numeric(15,2), BstRglAantalNogTeOntvangenInVoorrEenh numeric(15,2), AantDec smallint
      )
begin

  //Bestellingen van artikel ophalen
  SELECT
    BstKopGid,
    BstKopNummer,
    BstRglGid,
    BstKopAfleverDatum,
    BstKopReferentie,
    BstRglInkoopEenheid,
    round(BstRglAantalNogTeOntvangenInVoorrEenh / BstRglVoorraadEenhedenInInkoopEenheid, AantDec) TeOntvangen,
    BstRglAantalNogTeOntvangenInVoorrEenh TeOntvangenVrrdEenh,
    VrrdEenh.VkeAantalDecimalen AantDec
  FROM  tabBestelRegel
  inner join tabBestelKop on BstRglBstKopGid = BstKopGid
  inner join tabArtikel on ArtGid = BstRglArtgid inner join tabVerkoopEenheid VrrdEenh on VrrdEenh.VkeArtGid = ArtGid and VrrdEenh.VkeIsVoorraadEenheid = 1
  WHERE (BstRglArtgid = @ArtGid) and (TeOntvangenVrrdEenh <> 0)
  ORDER BY BstKopAfleverDatum desc, BstKopNummer;

end;


create or replace procedure Dashboard_Artikel_OpenstaandeOffertes(in @ArtGid Integer)
result(OffGid integer, OfkGid integer, OfrGid integer, OfferteVersie nchar(15), OfkDatum date, OfkReferentie Long nvarchar, Eenheid nchar(40),
       AantalVerkEenh numeric(15,2), AantalVrrdEenh numeric(15,2), AantDecVrrdEenh smallint, AantDecVerkEenh smallint
      )
begin

  //offertes van artikel ophalen
  SELECT
    OffGid,
    OfkGid,
    OfrGid,
    string(OffOffertenummer)+'.'+string(ofkversienummer) OfferteVersie,
    OfkAanmaakDatum,
    OfkReferentie,
    VerkEenh.VkeVerkoopEenheid VerkoopEenheid,
    OfrAantalTeOffreren AantalVerkEenh,
    OfrAantalTeOffrerenVrrdEenh AantalVrrdEenh,
    VrrdEenh.VkeAantalDecimalen AantDecVrrd,
    if VerkEenh.VkeAantalDecimalen = 4 then VrrdEenh.VkeAantalDecimalen else VerkEenh.VkeAantalDecimalen endif AantDecVerk
  FROM  tabOfferteRegel
  inner join tabOfferteKop on OfrOfkGid = OfkGid inner join tabOfferte on OfkOffGid = OffGid inner join tabVerkoopEenheid VerkEenh on VerkEenh.VkeGid = OfrVkeGid
  inner join tabArtikel on ArtGid = OfrArtgidArtikel inner join tabVerkoopEenheid VrrdEenh on VrrdEenh.VkeArtGid = ArtGid and VrrdEenh.VkeIsVoorraadEenheid = 1
  WHERE (OfrArtgidArtikel = @ArtGid) and OfkStatus in (0,1,2)
  ORDER BY OfkAanmaakDatum desc, OffOffertenummer, OfkVersienummer;

end;


create or replace procedure Dashboard_Artikel_OpenstaandeOrders(in @ArtGid Integer)
result(OrkGid integer, OrkNummer numeric(10,0), OrrRegelNr integer, OrkDatum date, OrkReferentie Long nvarchar, Eenheid nchar(40),
       NogTeLeverenVerkEenh numeric(15,2), NogTeLeverenVrrdEenh numeric(15,2), AantDecVrrdEenh smallint, AantDecVerkEenh smallint
      )
begin

  //orders van artikel ophalen
  SELECT
    OrkGid,
    OrkNummer,
    OrrRegelNr,
    OrkDatum,
    OrkReferentie,
    VerkEenh.VkeVerkoopEenheid VerkoopEenheid,
    (OrrAantalBesteld - OrrAantalGeleverd) NogTeLeverenVerkEenh,
    (OrrAantalBesteldVrrdEenh - OrrAantalGeleverdVrrdEenh) NogTeLeverenVrrdEenh,
    VrrdEenh.VkeAantalDecimalen AantDecVrrd,
    if VerkEenh.VkeAantalDecimalen = 4 then VrrdEenh.VkeAantalDecimalen else VerkEenh.VkeAantalDecimalen endif AantDecVerk
  FROM  tabOrderRegel
  inner join tabOrderKop on OrrOrkGid = OrkGid inner join tabVerkoopEenheid VerkEenh on VerkEenh.VkeGid = OrrVkeGid
  inner join tabArtikel on ArtGid = OrrArtgid inner join tabVerkoopEenheid VrrdEenh on VrrdEenh.VkeArtGid = ArtGid and VrrdEenh.VkeIsVoorraadEenheid = 1
  WHERE (OrrArtGid = @ArtGid) and ( ((OrrAantalBesteld - OrrAantalGeleverd) <> 0) or ((OrrAantalBesteldVrrdEenh - OrrAantalGeleverdVrrdEenh) <> 0) )
  ORDER BY OrkDatum desc, OrkNummer;

end;


create or replace procedure Dashboard_Artikel_Verbruik_Per_Kwartaal(in @ArtGid integer)
result(Boekjaar nchar(10), Kwartaal1 numeric(15,3), Kwartaal2 numeric(15,3), Kwartaal3 numeric(15,3), Kwartaal4 numeric(15,3), Totaal numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  //declare @ArtGid integer = 44;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select Code as BoekJaar,
         //1e kwartaal
         IsNull(sum(if ((VrdMutDatum >= BjBeginDatum)                     and (VrdMutDatum < DATEADD( month,  3, BjBeginDatum))) and (not IsNull(VrdMutSoort,-1) in (3,7) or IsNull(VrdMutAantal,0) < 0) then -VrdMutAantal else 0.00 endif), 0.00) as Kwartaal1,
         IsNull(sum(if ((VrdMutDatum >= DATEADD( month, 3, BjBeginDatum)) and (VrdMutDatum < DATEADD( month,  6, BjBeginDatum))) and (not IsNull(VrdMutSoort,-1) in (3,7) or IsNull(VrdMutAantal,0) < 0) then -VrdMutAantal else 0.00 endif), 0.00) as Kwartaal2,
         IsNull(sum(if ((VrdMutDatum >= DATEADD( month, 6, BjBeginDatum)) and (VrdMutDatum < DATEADD( month,  9, BjBeginDatum))) and (not IsNull(VrdMutSoort,-1) in (3,7) or IsNull(VrdMutAantal,0) < 0) then -VrdMutAantal else 0.00 endif), 0.00) as Kwartaal3,
         IsNull(sum(if ((VrdMutDatum >= DATEADD( month, 9, BjBeginDatum)) and (VrdMutDatum < DATEADD( month, 12, BjBeginDatum))) and (not IsNull(VrdMutSoort,-1) in (3,7) or IsNull(VrdMutAantal,0) < 0) then -VrdMutAantal else 0.00 endif), 0.00) as Kwartaal4,
         IsNull(Kwartaal1 + Kwartaal2 + Kwartaal3 + Kwartaal4, 0.00) as Totaal
  from   tabBoekjaar
  inner join tabPeriode on (PerBjGid = BjGid)
  left outer join tabVoorraadMutatie on (VrdMutPerLogBjGid = bjGid and VrdMutPerLogPernr = PerNr and VrdMutArtGid = @ArtGid)
  where BjGid in (select top 5 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
   and (IsNull(VrdMutSoort,-1) in (-1,1,3,4,5,7,8,9,12))
  group by BjBeginDatum, BoekJaar
  order by BjBeginDatum, BoekJaar;

end;


create or replace procedure Dashboard_Artikel_Verbruik_Per_Periode(in @ArtGid integer)
result(BoekjaarCode nchar(10), PerNr smallint, Aantal numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr       smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select Code, PerNr,
    sum(if not IsNull(VrdMutSoort,-1) in (3,7) or IsNull(VrdMutAantal,0) < 0 then -IsNull(VrdMutAantal,0) else 0 endif) Aantal
  from   tabBoekjaar
  inner join tabPeriode on (PerBjGid = BjGid)
  left outer join tabVoorraadMutatie on (VrdMutPerLogBjGid = bjGid and VrdMutPerLogPernr = PerNr and VrdMutArtGid = @ArtGid)
  where BjGid in (select top 3 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
   and (IsNull(VrdMutSoort,-1) in (-1,1,3,4,5,7,8,9,12))
  group by Code, PerNr
  having PerNr <> 0
  order by Code, PerNr
end;

