*/

create or replace procedure Dashboard_Crediteur_Artikelen_Hoogste_Inkoopomzet(in @NawGid integer)
result(ArtGid integer, ArtSoort smallint, ArtikelNummer nchar(20), ArtikelOmschrijving nchar(40), Inkoopomzet numeric(15,3), Percentage numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr       smallint;
  declare @OmzetTotaal Numeric(15,3);

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  // bepaal totale inkoopomzet bij crediteur van afgelopen 12 maanden
  select SUM(IndBedragInBasisValuta) into @OmzetTotaal from tabInkoopData where (IndNawGid = @NawGid) and (IndArtSoort <> 0) and ((IndDatum > DATEADD( month, -12, @Peildatum)) and (IndDatum <= @Peildatum));

  // ophalen top 10 artikelen/tarieven met hoogste inkoopomzet
  select top 10
    a.ArtGid,
    a.ArtSoort,
    a.Artcode,
    a.ArtOms,
    SUM(ind.IndBedragInBasisValuta) as Inkoopomzet,
    cast((Inkoopomzet/(if @OmzetTotaal <> 0 then (@OmzetTotaal/100) else 1 endif)) as numeric (15,3)) as Percentage
  from
    tabInkoopData as ind
  inner join
    tabArtikel as a on (a.ArtGid = ind.IndArtGid) and (a.ArtSoort <> 0) //alleen artikelen/tarieven
  where
    (ind.IndNawGid = @NawGid) and (ind.IndArtSoort <> 0) and ((ind.IndDatum > DATEADD( month, -12, @Peildatum)) and (ind.IndDatum <=@Peildatum))
  group by
    a.ArtSoort, a.Artcode, a.ArtOms, a.ArtGid
  order by
    Inkoopomzet Desc, a.Artcode
end;


create or replace procedure Dashboard_Crediteur_Artikelen_Meest_Ingekocht(in @NawGid integer)
result(ArtGid integer, ArtikelNummer nchar(20), ArtikelOmschrijving nchar(40), AantalIngekocht numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select top 10
     a.ArtGid,
     a.Artcode,
	 a.ArtOms,
   	 SUM(ind.IndAantal) as Aantal
  from
	 tabInkoopData as ind
	 inner join tabArtikel as a on (a.ArtGid = ind.IndArtGid) and (a.ArtSoort = 2) //alleen artikelen
  where
     (ind.IndNawGid = @NawGid) and ((ind.IndDatum > DATEADD( month, -12, @Peildatum)) and (ind.IndDatum <=@Peildatum))
  group by
     a.Artcode, a.ArtOms, a.ArtGid
  order by
     Aantal Desc, Artcode
end;



create or replace procedure Dashboard_Crediteur_Inkoopomzet_Per_Kwartaal(in @NawGid integer)
result(Boekjaar nchar(10), Kwartaal1 numeric(15,3), Kwartaal2 numeric(15,3), Kwartaal3 numeric(15,3), Kwartaal4 numeric(15,3), Totaal numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select Code as BoekJaar,
    IsNull(sum(if ((ind.IndDatum >= bj.BjBeginDatum)                     and (ind.IndDatum < DATEADD( month,  3, bj.BjBeginDatum))) then ind.IndBedragInBasisValuta else 0.00 endif), 0.00) as Kwartaal1,
    IsNull(sum(if ((ind.IndDatum >= DATEADD( month, 3, bj.BjBeginDatum)) and (ind.IndDatum < DATEADD( month,  6, bj.BjBeginDatum))) then ind.IndBedragInBasisValuta else 0.00 endif), 0.00) as Kwartaal2,
    IsNull(sum(if ((ind.IndDatum >= DATEADD( month, 6, bj.BjBeginDatum)) and (ind.IndDatum < DATEADD( month,  9, bj.BjBeginDatum))) then ind.IndBedragInBasisValuta else 0.00 endif), 0.00) as Kwartaal3,
    IsNull(sum(if ((ind.IndDatum >= DATEADD( month, 9, bj.BjBeginDatum)) and (ind.IndDatum < DATEADD( month, 12, bj.BjBeginDatum))) then ind.IndBedragInBasisValuta else 0.00 endif), 0.00) as Kwartaal4,
    IsNull(Kwartaal1 + Kwartaal2 + Kwartaal3 + Kwartaal4, 0.00) as Totaal
  from
	tabBoekjaar as bj
  left outer join
    tabInkoopData as ind on (ind.IndBjGid = bj.bjGid) and (ind.IndNawGid = @NawGid)
  where BjGid in (select top 5 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
  group by
    bj.BjBeginDatum, BoekJaar
  order by
    bj.BjBeginDatum, BoekJaar;
end;


create or replace procedure Dashboard_Crediteur_Inkoopomzet_Per_Periode(in @NawGid integer)
result(BoekjaarCode nchar(10), PerNr smallint, Inkoopomzet numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select
    bj.Code as BoekJaar,
	bp.PerNr,
	IsNull(sum(ind.IndBedragInBasisValuta), 0 ) as Inkoopomzet
  from
    tabBoekjaar as bj
    inner join tabPeriode as bp on (bp.PerBjGid = bj.BjGid)
    left outer join tabInkoopData as ind on (ind.IndBjGid = bj.bjGid and ind.IndPerNr = bp.PerNr and ind.IndNawGid = @NawGid)
  where
     bj.BjGid in (select top 3 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
  group by
     BoekJaar, bp.PerNr
  having
     (bp.PerNr <> 0)
  order by
     BoekJaar, bp.PerNr
end;


create or replace procedure Dashboard_Crediteur_OpenstaandeBestellingen(in @NawGid Integer)
result(BstKopGid integer, bstKopNummer numeric(10,0), BstKopBestelDatum date, BstKopReferentie Long nvarchar, BstKopOpm long nvarchar ,
       ValCode nchar(3), calcTotaalExclBtw numeric(15,2), calcTotaalInclBtw numeric(15,2), calcTotaalBtwBedrag numeric(15,2), Status nvarchar(20) )
begin

	SELECT
	  bk.BstKopGid,
	  bk.BstKopNummer,
	  bk.BstKopBestelDatum,
	  bk.BstKopReferentie,
	  bk.BstKopOpm,
	  val.ValCode,
	  bkt.calcTotaalValutaExcl,
	  bkt.calcTotaalValutaIncl,
	  bkt.calcTotaalValutaBtwBedrag,
      (case
         when (bk.BstKopIsGoedgekeurd = 0) then _U('Concept')
         when (bk.BstKopIsGoedgekeurd = 1 ) and (bk.BstKopIsVerwerkt = 0) then _U('Goedgekeurd')
         when (bk.BstKopIsGoedgekeurd = 1 ) and (bk.BstKopIsVerwerkt = 1) then _U('Verwerkt')
         end ) AS Status
	FROM
	  tabBestelKop AS bk
	  INNER JOIN vwBestelKopTotalen AS bkt ON (bk.BstKOPGid = bkt.calcBstKopGid)
	  INNER JOIN tabValuta val ON (val.ValNummer = bk.BstKopValNummer)
	WHERE
	  (bkt.calcBestellingIsVolledigOntvangen = 0)
        AND
	  (bk.BstKopNawGid  = @NawGid)
	ORDER BY
	  bk.BstKopBestelDatum DESC,
	  bk.BstKopNummer

end;

create or replace procedure Dashboard_Crediteur_OSP_OuderdomsAnalyse(in @NawGid Integer)
result(OuderdomsRange integer, LabelOuderdomsRange nchar(20), AantalOpenstaandePosten integer, AantalVervallenPosten integer, ValCode nchar(3), OpenstaandBedrag numeric(15,2), VervallenBedrag numeric(15,2))
begin
  declare @Dagen1    smallint;
  declare @Dagen2    smallint;
  declare @Dagen3    smallint;
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;
  declare @RksGID    integer;
  declare @ValNummer smallint;
  declare @ValCode   nchar(3);

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //ophalen indeling ouderdomsanalyse OSP crediteuren
  select Contents into @Dagen1 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_EERSTE';
  select Contents into @Dagen2 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_TWEEDE';
  select Contents into @Dagen3 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_DERDE';
  set @Dagen2 = @Dagen2 + @Dagen1;
  set @Dagen3 = @Dagen3 + @Dagen2;

  //gegegens van crediteur ophalen
  SELECT NawFilRksGID, NawFilValNummer, ValCode
  INTO   @RksGID,      @ValNummer,      @ValCode
  FROM   tabNawFile
  INNER JOIN tabValuta ON (ValNummer = NawFilValNummer)
  WHERE NawFilNawGid=@NawGid;

  //haal gegevens openstaande posten op
  SELECT
	OuderdomsRange,

    Case OuderdomsRange
      when 1 then '0-' + string(@Dagen1)
      when 2 then string(@Dagen1 + 1) + '-' + string(@Dagen2)
      when 3 then string(@Dagen2 + 1) + '-' + string(@Dagen3)
      when 4 then string(@Dagen3 + 1) + '+'
    end case as LabelOuderdomsRange,

    SUM(AantalOpenstaandePosten),
    SUM(AantalVervallenPosten),

    @Valcode as ValCode,

    SUM(OpenstaandBedrag),
    SUM(VervallenBedrag)
  FROM
  (
    //openstaande posten van meegegeven debiteur
    select
      // NR ouderdomsrange
      (if @PeilDatum <= (OspFactuurDatum) + @Dagen1 then 1
       else if @PeilDatum between (OspFactuurDatum) + @Dagen1 + 1 and (OspFactuurDatum) + @Dagen2 then 2
       else if @PeilDatum between (OspFactuurDatum) + @Dagen2 + 1 and (OspFactuurDatum) + @Dagen3 then 3
       else 4
       endif endif endif
      ) as OuderdomsRange,

      //aantal openstaande posten
      sum(1) as AantalOpenstaandePosten,

      //aantal vervallen posten posten
      sum(if OspVervalDatum < @PeilDatum then 1 else 0 endif) as AantalVervallenPosten,

      //Bedrag aan openstaande posten
      sum(IsNull((if OspValNummer = @ValNummer then
                     (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                      ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @ValNummer, @BjGid, @PerNr, 2)
                  endif), 0.00)) as OpenstaandBedrag,

      //vervallen bedrag
      sum(if OspVervalDatum < @PeilDatum then
            IsNull((if OspValNummer = @ValNummer then
                     (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                    else
                      ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @ValNummer, @BjGid, @PerNr, 2)
                    endif), 0.00)
          else
        0.00 endif) as VervallenBedrag

    from tabOpenstaandePost
    where
      OspRksGid = @RksGid
      and (OspIsCrediteur   = 1)       //Alleen osp van crediteuren
      and (OspIsVervallen   = 0)      //alleen nog openstaande posten
      and (OspIsGeblokkeerd = 0)      //alleen niet geblokkeerde posten ?
      and OspBjGid          = @BjGid  //en op dit boekjaar betrekking hebben
    group by OuderdomsRange

    //Eventuele lege ranges opnemen
    Union all
      Select 1,0,0,0,0
    Union all
      Select 2,0,0,0,0
    Union all
      Select 3,0,0,0,0
    Union all
      Select 4,0,0,0,0
  ) A
  GROUP BY OuderdomsRange
  ORDER BY OuderdomsRange

end;


create or replace procedure Dashboard_Crediteur_OSP_OudstePosten(in @NawGid Integer)
result(OspFactuurNummer nchar(40), OspFactuurDatum date, OspVervalDatum date, OspValCode nchar(3),
       Factuurbedrag numeric(15,2), OpenstaandBedrag numeric(15,2), OspBedragOnderwegInValuta numeric(15,2),
	   OspSoortFactuur smallint, OspIsGeblokkeerd smallint, VervaldatumVerstreken smallInt)
begin
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;
  declare @RksGID    integer;
  declare @ValNummer smallint;
  declare @ValCode   nchar(3);

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //gegegens van crediteur ophalen
  SELECT NawFilRksGID, NawFilValNummer, ValCode
  INTO   @RksGID,      @ValNummer,      @ValCode
  FROM   tabNawFile
  INNER JOIN tabValuta ON (ValNummer = NawFilValNummer)
  WHERE NawFilNawGid=@NawGid;


  SELECT TOP(10)
		OspFactuurNummer,
		OspFactuurDatum,
        OspVervalDatum,
		OspValCode,
		(OspFactuurBedragDefinitief+OspFactuurBedragVoorlopig), //Factuurbedrag
		(OspFactuurBedragDefinitief+OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief+OspBetaaldBedragVoorlopig), //Openstaand
        OspBedragOnderwegInValuta,
		OspSoortFactuur,
		OspIsGeblokkeerd,
		(IF OspVervaldatum < @peildatum then 1 else 0 endif)
  FROM  tabOpenstaandePost
  WHERE (OspRksGID = @RksGid)  //geslecteerde crediteur
    AND (OspBjGid  = @BjGid)   //huidig boekjaar
	AND (OspIsVervallen = 0)   //Niet volledig betaald
  ORDER BY OspFactuurDatum, OspFactuurNummer;

end;

