create or replace procedure Dashboard_Debiteur_Artikelen_Hoogste_Omzet(in @NawGid integer)
result(ArtGid integer, ArtSoort smallint, ArtikelNummer nchar(20), ArtikelOmschrijving nchar(40), Omzet numeric(15,3), Percentage numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr       smallint;
  declare @OmzetTotaal Numeric(15,3);

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  //bepaal totale omzet van debiteur van afgelopen 12 maanden
  select SUM(OmzOmzetBasis) into @OmzetTotaal from tabOmzet where (OmzNawGid = @NawGid) and (OmzArtSoort <> 0) and ((omzDatum > DATEADD( month, -12, @Peildatum)) and (omzDatum <=@Peildatum));

  //ophalen top 10 artikelen/tarieven met meeste omzet
  select top 10
    ArtGid,
    ArtSoort,
    Artcode,
    ArtOms,
    SUM(OmzOmzetBasis) as Omzet,
    cast((Omzet/(if @OmzetTotaal <> 0 then (@OmzetTotaal/100) else 1 endif)) as numeric (15,3)) as Percentage
  from   tabOmzet
		 inner join tabArtikel on (ArtGid=omzArtGid) and (ArtSoort <> 0) //alleen artikelen/tarieven
  where (OmzNawGid = @NawGid)
    and (OmzArtSoort <> 0)
		and ((omzDatum > DATEADD( month, -12, @Peildatum)) and (omzDatum <=@Peildatum))
  group by ArtSoort, Artcode, ArtOms, ArtGid
  order by Omzet Desc, Artcode
end;


create or replace procedure Dashboard_Debiteur_Artikelen_Meest_verkocht(in @NawGid integer)
result(ArtGid integer, ArtikelNummer nchar(20), ArtikelOmschrijving nchar(40), AantalVerkocht numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select top 10
     ArtGid,
     Artcode,
		 ArtOms,
   	 SUM(omzAantal) Aantal

  from   tabOmzet
		 inner join tabArtikel on (ArtGid=omzArtGid) and (ArtSoort=2) //alleen artikelen
  where (OmzNawGid = @NawGid)
		 and ((omzDatum > DATEADD( month, -12, @Peildatum)) and (omzDatum <=@Peildatum))
  group by Artcode, ArtOms, ArtGid
  order by Aantal Desc, Artcode
end;



create or replace procedure Dashboard_Debiteur_BetaalAnalyse(in @NawGid Integer)
result(
  Open_TotaalFactuurBedrag               numeric(15,2),
  Open_TotaalBetaaldBedrag               numeric(15,2),
  Open_TotaalOpenstaandBedrag            numeric(15,2),
  Open_TotaalDirectTeVoldoen             numeric(15,2),
  Open_TotaalGeblokkeerdBedrag           numeric(15,2),
  Open_AantalPosten                      integer,
  Open_AantalPostenTeLaatBetaald         integer,
  Open_PercTeLaatBetaald                 numeric(15,2),
  Open_KortsteBetalingstermijn           integer,
  Open_LangsteBetalingstermijn           integer,
  Open_GemBetalingsTermijn               numeric(15,2),
  Open_LangsteBetOverschrijding          integer,
  Open_GemBetOverschrijding              numeric(15,2),
  Open_BedragRenteverlies                numeric(15,2),
  Open_GemToegestaneBetalingstermijn     numeric(15,2),

 //gesloten posten = volledig betaald
  Betaald_TotFactuurbedrag               numeric(15,2),
  Betaald_AantalPosten                   integer,
  Betaald_AantalPostenOpTijdBetaald      integer,
  Betaald_AantalPostenTeLaatBetaald      integer,
  Betaald_PercOpTijdBetaald              numeric(15,2),
  Betaald_PercTeLaatBetaald              numeric(15,2),
  Betaald_KortsteBetalingstermijn        integer,
  Betaald_LangsteBetalingstermijn        integer,
  Betaald_GemBetalingstermijn            numeric(15,2),
  Betaald_KortsteBetOverschrijding       integer,
  Betaald_LangsteBetOverschrijding       integer,
  Betaald_GemBetOverschrijding           numeric(15,2),
  Betaald_BedragRenteverlies             numeric(15,2),
  Betaald_GemToegestaneBetalingstermijn  numeric(15,2),

 //totaal open en gesloten
  Totaal_TotaalFactuurBedrag             numeric(15,2),
  Totaal_AantalPosten                    integer,
  Totaal_GemBetalingstermijn             numeric(15,2),
  Totaal_GemBetOverschrijding            numeric(15,2),
  Totaal_BedragRenteverlies              numeric(15,2),
  Totaal_GemToegestaneBetalingstermijn   numeric(15,2),

  valCode				 nchar(3),
  BtcNummer				 smallInt,
  AantalDgnMnd                           smallInt,
  DagenMaanden  			 smallInt
)

begin
  declare @RksGID    	  integer;
  declare @debiteurNummer nchar(10);
  declare @AantalDebet    integer;
  declare @AantalCredit   integer;
  declare @BedragDebet    numeric(15,2);
  declare @BedragCredit   numeric(15,2);
  declare @ValNummer      smallint;
  declare @ValCode        nchar(3);
  declare @Peildatum 	  Date;
  declare @BjGid          integer;
  declare @Pernr          smallint;

  //openstaande posten
  declare @Open_TotaalFactuurBedrag               numeric(15,2);
  declare @Open_TotaalBetaaldBedrag               numeric(15,2);
  declare @Open_TotaalOpenstaandBedrag            numeric(15,2);
  declare @Open_TotaalDirectTeVoldoen             numeric(15,2);
  declare @Open_TotaalGeblokkeerdBedrag           numeric(15,2);
  declare @Open_AantalPosten                      integer;
  declare @Open_AantalPostenTeLaatBetaald         integer;
  declare @Open_PercTeLaatBetaald                 numeric(15,2);
  declare @Open_KortsteBetalingstermijn           integer;
  declare @Open_LangsteBetalingstermijn           integer;
  declare @Open_GemBetalingsTermijn               numeric(15,2);
  declare @Open_LangsteBetOverschrijding          integer;
  declare @Open_GemBetOverschrijding              numeric(15,2);
  declare @Open_BedragRenteverlies                numeric(15,2);
  declare @Open_GemToegestaneBetalingstermijn     numeric(15,2);

  //gesloten posten = volledig betaald
  declare @Betaald_TotaalFactuurbedrag            numeric(15,2);
  declare @Betaald_AantalPosten                   integer;
  declare @Betaald_AantalPostenOpTijdBetaald      integer;
  declare @Betaald_AantalPostenTeLaatBetaald      integer;
  declare @Betaald_PercOpTijdBetaald              numeric(15,2);
  declare @Betaald_PercTeLaatBetaald              numeric(15,2);
  declare @Betaald_KortsteBetalingstermijn        integer;
  declare @Betaald_LangsteBetalingstermijn        integer;
  declare @Betaald_GemBetalingstermijn            numeric(15,2);
  declare @Betaald_KortsteBetOverschrijding       integer;
  declare @Betaald_LangsteBetOverschrijding       integer;
  declare @Betaald_GemBetOverschrijding           numeric(15,2);
  declare @Betaald_BedragRenteverlies             numeric(15,2);
  declare @Betaald_GemToegestaneBetalingstermijn  numeric(15,2);

  //totaal open en gesloten
  declare @Totaal_TotaalFactuurBedrag             numeric(15,2);
  declare @Totaal_AantalPosten                    integer;
  declare @Totaal_GemBetalingstermijn             numeric(15,2);
  declare @Totaal_GemBetOverschrijding            numeric(15,2);
  declare @Totaal_BedragRenteverlies              numeric(15,2);
  declare @Totaal_GemToegestaneBetalingstermijn   numeric(15,2);

  //Betalingsconditiegegevens
  declare @BtcNummer				  smallInt;
  declare @AantalDgnMnd                           smallInt;
  declare @DagenMaanden  			  smallInt;

  //Aanmaken tijdelijke tabel mbt
  declare local temporary table tmpDashboardDebBetAnalyse
   (
    tmpOspGidje                             integer         not null default autoincrement,
    tmpOpenstaandBedrag                     numeric(15,2),
    tmpOpenstaandBedragInAfdrValDeb         numeric(15,2),
    tmpOpenstaandBedragInAfdrValFact        numeric(15,2),
    tmpOspBetaaldBedrag                     numeric(15,2),
    tmpOspBetaaldBedragInAfdrValDeb         numeric(15,2),
    tmpOspBetaaldBedragInAfdrValFact        numeric(15,2),
    tmpOspBetalingsOverschr                 numeric(15,2),
    tmpOspBetalingstermijn                  numeric(15,2),
    tmpOspDatumLaatstePosCredBetaling       date,
    tmpOspDirectTeVoldoenInAfdrValDeb       numeric(15,2),
    tmpOspDirectTeVoldoenInAfdrValFact      numeric(15,2),
    tmpOspFactuurBedrag                     numeric(15,2),
    tmpOspFactuurbedragInAfdrValDeb         numeric(15,2),
    tmpOspFactuurbedragInAfdrValFact        numeric(15,2),
    tmpOspFactuurdatum                      date,
    tmpOspFactuurnummer                     nchar(40),
    tmpOspFactuurnummer_Lengte              integer         not null,
    tmpOspGeblokkeerdBedrag                 numeric(15,2),
    tmpOspGeblokkeerdBedragInAfdrValDeb     numeric(15,2),
    tmpOspGeblokkeerdBedragInAfdrValFact    numeric(15,2),
    tmpOspIsGeblokkeerd                     smallint                 check(tmpOspIsGeblokkeerd in (0,1)),
    tmpOspIsGesloten                        smallint                 check(tmpOspIsGesloten in (0,1)),
    tmpOspOms                               nchar(40),
    tmpOspRenteverlies                      numeric(15,2),
    tmpOspRenteverliesInBasisvaluta         numeric(15,2),
    tmpOspRksGid                            integer,
    tmpOspToegestaneBetalingstermijn        numeric(15,2),
    tmpOspValCode                           nchar(3),
    tmpOspValCodeAfdrFact                   nchar(3),
    tmpOspValNrAfdrDebTot                   integer                  check(tmpOspValNrAfdrDebTot >= 0 and tmpOspValNrAfdrDebTot <= 999),
    tmpOspValNrAfdrFact                     integer                  check(tmpOspValNrAfdrFact >= 0 and tmpOspValNrAfdrFact <= 999),
    tmpOspValNummer                         integer                  check(tmpOspValNummer >= 0 and tmpOspValNummer <= 999),
    tmpOspVervaldatum                       date,
    primary key (tmpOspGidje)
  ) on commit preserve rows;

  create index Idx_tmpOspRksGid on tmpDashboardDebBetAnalyse(tmpOspRksGid);

  //call traceBegin('Dashboard_Debiteur_BetaalAnalyse');

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //------ gegegens van debiteur ophalen
  select NawFilNummer,    NawFilRksGID, NawFilValNummer, ValCode,   btcNummer,  AantalDgnMnd,  DagenMaanden
  into   @debiteurNummer, @RksGID,      @ValNummer,      @ValCode , @btcNummer, @AantalDgnMnd, @DagenMaanden
  from   tabNawFile
         left outer join tabValuta on (ValNummer = NawFilValNummer)
         left outer join tabBetalingsconditie on (btcNummer = nawFilBtcNummer)
  where  (NawFilNawGid = @NawGid);

  //------ Vul tijdelijke tabel
  call dashboard_Debiteur_BetAnalyseDebTmpTabVullen(
    @NawGid,
    DATEADD( month, -12, @Peildatum), 	//@VanFactuurDatum
    @peildatum,	   	    		//@TotFactuurDatum
    1,					//@AfdrNogOpenstaandePosten
    1,					//@AfdrGeblokkeerdePosten
    1, 					//@AfdrNietVervallenPosten
    @peildatum,		                //@Peildatum
    0.00,				//@RentePercentage
    1,					//@AfdrValutaDebOfBasisFact 	0=van OSP, 1=van debiteur, 2=basisvaluta
    0					//@AfdrValutaDebOfBasisDebTot	0=van debiteur, 1=basisvaluta
   );

  //------ Bereken totalen o.b.v. tijdelijke tabel
  call Dashboard_Debiteur_BetAnalyseBepaalTotalen(
        @RksGID,
        @Peildatum,
        //openstaande posten
        @Open_TotaalFactuurBedrag,
        @Open_TotaalBetaaldBedrag,
        @Open_TotaalOpenstaandBedrag,
        @Open_TotaalDirectTeVoldoen,
        @Open_TotaalGeblokkeerdBedrag,
        @Open_AantalPosten,
        @Open_AantalPostenTeLaatBetaald,
        @Open_PercTeLaatBetaald,
        @Open_KortsteBetalingstermijn,
        @Open_LangsteBetalingstermijn,
        @Open_GemBetalingsTermijn,
        @Open_LangsteBetOverschrijding,
        @Open_GemBetOverschrijding,
        @Open_BedragRenteverlies,
        @Open_GemToegestaneBetalingstermijn,

        //gesloten posten = volledig betaald
        @Betaald_TotaalFactuurbedrag,
        @Betaald_AantalPosten,
        @Betaald_AantalPostenOpTijdBetaald,
        @Betaald_AantalPostenTeLaatBetaald,
        @Betaald_PercOpTijdBetaald,
        @Betaald_PercTeLaatBetaald,
        @Betaald_KortsteBetalingstermijn,
        @Betaald_LangsteBetalingstermijn,
        @Betaald_GemBetalingstermijn,
        @Betaald_KortsteBetOverschrijding,
        @Betaald_LangsteBetOverschrijding,
        @Betaald_GemBetOverschrijding,
        @Betaald_BedragRenteverlies,
        @Betaald_GemToegestaneBetalingstermijn,

        //totaal open en gesloten
        @Totaal_TotaalFactuurBedrag,
        @Totaal_AantalPosten,
        @Totaal_GemBetalingstermijn,
        @Totaal_GemBetOverschrijding,
        @Totaal_BedragRenteverlies,
        @Totaal_GemToegestaneBetalingstermijn
  );

  //------ geef berekende gegevens terug
  Select
        //openstaande posten
        @Open_TotaalFactuurBedrag,
        @Open_TotaalBetaaldBedrag,
        @Open_TotaalOpenstaandBedrag,
        @Open_TotaalDirectTeVoldoen,
        @Open_TotaalGeblokkeerdBedrag,
        @Open_AantalPosten,
        @Open_AantalPostenTeLaatBetaald,
        @Open_PercTeLaatBetaald,
        @Open_KortsteBetalingstermijn,
        @Open_LangsteBetalingstermijn,
        @Open_GemBetalingsTermijn,
        @Open_LangsteBetOverschrijding,
        @Open_GemBetOverschrijding,
        @Open_BedragRenteverlies,
        @Open_GemToegestaneBetalingstermijn,

        //gesloten posten = volledig betaald
        @Betaald_TotaalFactuurbedrag,
        @Betaald_AantalPosten,
        @Betaald_AantalPostenOpTijdBetaald,
        @Betaald_AantalPostenTeLaatBetaald,
        @Betaald_PercOpTijdBetaald,
        @Betaald_PercTeLaatBetaald,
        @Betaald_KortsteBetalingstermijn,
        @Betaald_LangsteBetalingstermijn,
        @Betaald_GemBetalingstermijn,
        @Betaald_KortsteBetOverschrijding,
        @Betaald_LangsteBetOverschrijding,
        @Betaald_GemBetOverschrijding,
        @Betaald_BedragRenteverlies,
        @Betaald_GemToegestaneBetalingstermijn,

        //totaal open en gesloten
        @Totaal_TotaalFactuurBedrag,
        @Totaal_AantalPosten,
        @Totaal_GemBetalingstermijn,
        @Totaal_GemBetOverschrijding,
        @Totaal_BedragRenteverlies,
        @Totaal_GemToegestaneBetalingstermijn,

        //Betalingsconditiegegevens
        @valCode,
        @BtcNummer,
        @AantalDgnMnd,
        @DagenMaanden;

  //call traceEind('Dashboard_Debiteur_BetaalAnalyse');

end;

//13601
//select * from tabopenstaandepost inner join tabnawfile on nawfilrksgid=osprksgid
//select * from tabNawFile where nawfilNummer='1305560001'
//select * from tmpDebAnalyseOsps;
//  call Dashboard_Debiteur_BetaalAnalyse(13601);
//select * from tabnawfile where nawfilnawgid=13601 = 1303120000


//Aanmaken tijdelijke tabel met Osp''s die getoond moeten worden.
//Op basis van deze tabel worden osp''s geselecteerd in andere stored procs
//op basis waarvan de berekening van de totalen voor de debiteuren analyse gedaan wordt

create or replace procedure Dashboard_Debiteur_BetAnalyseBepaalTotalen(
 in @RksGid                                       integer,
 in @peildatum					  date,

 //Omdat het resultaat altijd uit één record bestaat, kun je dit beter in out-parameters
 //stoppen dan in een return-values. Zo kun je veel makkelijker waarden berekenen dmv verschillende queries.

  //openstaande posten
  @Open_TotaalFactuurBedrag               numeric(15,2),        //totaal factuurbedrag nog openstaande posten
  @Open_TotaalBetaaldBedrag               numeric(15,2),        //totaal betaald bedrag op nog openstaande posten
  @Open_TotaalOpenstaandBedrag            numeric(15,2),        //openstaand saldo (het openstaand bedrag)
  @Open_TotaalDirectTeVoldoen             numeric(15,2),        //totaal direct te voldoen: niet geheel betaalde facturen, die vervallen zijn
  @Open_TotaalGeblokkeerdBedrag           numeric(15,2),        //totaal geblokkeerde bedrag
  @Open_AantalPosten                      integer,              //aantal nog openstaande openstaande posten
  @Open_AantalPostenTeLaatBetaald         integer,              //aantal openstaande posten waarvan vervaldatum al verstreken is
  @Open_PercTeLaatBetaald                 numeric(15,2),        //Percentage posten wat al te laat is (vervaldatum verstreken)
  @Open_KortsteBetalingstermijn           integer,              //Kortste termijn nog openstaande posten (Het aantal dagen dat de oudste openstaande post openstaat)
  @Open_LangsteBetalingstermijn           integer,              //langste termijn nog openstaande posten (Het aantal dagen dat de oudste openstaande post openstaat)
  @Open_GemBetalingsTermijn               numeric(15,2),        //gemiddelde Betalingstermijn/betalingstermijn openstaande facturen in dagen
  @Open_LangsteBetOverschrijding          integer,              //langste betalingsoverschrijding openstaande posten (het aantal dagen dat de vervaldatum is overschreden)
  @Open_GemBetOverschrijding              numeric(15,2),        //gemiddelde betalingsoverschrijding openstaande facturen in dagen
  @Open_BedragRenteverlies                numeric(15,2),        //totaal renteverlies openstaande facturen
  @Open_GemToegestaneBetalingstermijn     numeric(15,2),        //Toegestane betalingstermijn openstaande facturen

  //gesloten posten = volledig betaald
  @Betaald_TotaalFactuurbedrag            numeric(15,2),        //totaal factuurbedrag betaalde posten
  @Betaald_AantalPosten                   integer,              //aantal facturen volledig betaald, dus NIET die waarvoor te veel is betaald, en die nog openstaand zijn
  @Betaald_AantalPostenOpTijdBetaald      integer,              //aantal van afgehandelde facturen dat optijd betaald is
  @Betaald_AantalPostenTeLaatBetaald      integer,              //aantal van afgehandelde facturen dat te laat betaald is
  @Betaald_PercOpTijdBetaald              numeric(15,2),        //percentage van afgehandelde facturen dat op tijd betaald is
  @Betaald_PercTeLaatBetaald              numeric(15,2),        //percentage van afgehandelde facturen dat te laat betaald is
  @Betaald_KortsteBetalingstermijn        integer,              //Kortste termijn dat betaalde factuur heeft opengestaan
  @Betaald_LangsteBetalingstermijn        integer,              //Langste termijn dat betaalde factuur heeft opengestaan
  @Betaald_GemBetalingstermijn            numeric(15,2),        //gemiddelde termijn dat betaalde factuur heeft opengestaan
  @Betaald_KortsteBetOverschrijding       integer,              //Kortste betalingsoverschrijding gesloten posten
  @Betaald_LangsteBetOverschrijding       integer,              //Langste betalingsoverschrijding gesloten posten
  @Betaald_GemBetOverschrijding           numeric(15,2),        //gemiddelde betalingsoverschrijding gesloten posten
  @Betaald_BedragRenteverlies             numeric(15,2),        //totaal renteverlies betaalde facturen
  @Betaald_GemToegestaneBetalingstermijn  numeric(15,2),        //Toegestane betalingstermijn betaalde facturen

  //totaal open en gesloten
  @Totaal_TotaalFactuurBedrag             numeric(15,2),        //totaal factuurbedrag betaalde en openstaande posten
  @Totaal_AantalPosten                    integer,              //totaal aantal betaalde en openstaande posten
  @Totaal_GemBetalingstermijn             numeric(15,2),        //gemiddelde betalingstermijn in dagen van openstaande facturen + betaalde facturen
  @Totaal_GemBetOverschrijding            numeric(15,2),        //gemiddelde betalingsoverschrijding in dagen van openstaande facturen + betaalde facturen
  @Totaal_BedragRenteverlies              numeric(15,2),        //totaal renteverlies betaalde + openstaande facturen
  @Totaal_GemToegestaneBetalingstermijn   numeric(15,2)         //gemiddelde van de toegestane betalingstermijnen
  )
begin
  //call traceBegin('Dashboard_Debiteur_BetAnalyseBepaalTotalen');

  //call trace('Peildatum: ' + String(@Peildatum));

  //de hoofdqueries moeten in deze volgorde worden aangeroepen, omdat er een aantal variabelen wordt gevuld, dat verderop gebruikt wordt

  //------------------------------------------------
  //----- berekeningen over openstaande posten -----
  //------------------------------------------------
  select sum(tmpOspFactuurbedragInAfdrValDeb),
         sum(tmpOspBetaaldBedragInAfdrValDeb),
         sum(IsNull(tmpOspFactuurbedragInAfdrValDeb,0) - IsNull(tmpOspBetaaldBedragInAfdrValDeb,0)),
         sum(tmpOspDirectTeVoldoenInAfdrValDeb),
         sum(tmpOspGeblokkeerdBedrag),
         count(1),
         sum(if @peildatum > tmpOspVervaldatum then 1 else 0 endif),
         min(tmpOspBetalingstermijn),  max(tmpOspBetalingstermijn), avg(tmpOspBetalingstermijn),
         max(tmpOspBetalingsOverschr), avg(tmpOspBetalingsOverschr),
         sum(tmpOspRenteverliesInBasisvaluta),
         avg(tmpOspToegestaneBetalingstermijn)
  into   @Open_TotaalFactuurBedrag,
         @Open_TotaalBetaaldBedrag,
         @Open_TotaalOpenstaandBedrag,
         @Open_TotaalDirectTeVoldoen,
         @Open_TotaalGeblokkeerdBedrag,
         @Open_AantalPosten,
         @Open_AantalPostenTeLaatBetaald,
         @Open_KortsteBetalingstermijn,  @Open_LangsteBetalingstermijn, @Open_GemBetalingsTermijn,
         @Open_LangsteBetOverschrijding, @Open_GemBetOverschrijding,
         @Open_BedragRenteverlies,
         @Open_GemToegestaneBetalingstermijn
  from   tmpDashboardDebBetAnalyse
  where  (tmpOspRksGid = @RksGid)
     and (tmpOspIsGesloten = 0);

  //percentage te laat betaald berekenen
  if (@Open_AantalPostenTeLaatBetaald <> 0) and (@Open_AantalPosten <> 0) then //door 0 delen kan niet...
    set @Open_PercTeLaatBetaald = (CAST(@Open_AantalPostenTeLaatBetaald  as numeric(15,2)) / @Open_AantalPosten) * 100;
  else
    set @Open_PercTeLaatBetaald = 0
  end if;

  //---------------------------------------------
  //----- berekeningen over betaalde posten -----
  //---------------------------------------------
  select sum(tmpOspFactuurbedragInAfdrValDeb),
         count(*),
         sum(if (tmpOspDatumLaatstePosCredBetaling <= tmpOspVervaldatum) then 1 else 0 endif),  //optijd betaald
         sum(if (tmpOspDatumLaatstePosCredBetaling <= tmpOspVervaldatum) then 0 else 1 endif),  //telaat betaald
         min(tmpOspBetalingstermijn),  max(tmpOspBetalingstermijn),  avg(tmpOspBetalingstermijn),
         min(tmpOspBetalingsOverschr), max(tmpOspBetalingsOverschr), avg(tmpOspBetalingsOverschr),
         sum(tmpOspRenteverliesInBasisvaluta),
         avg(tmpOspToegestaneBetalingstermijn)
  into   @Betaald_TotaalFactuurbedrag,
         @Betaald_AantalPosten,             @Betaald_AantalPostenOpTijdBetaald, @Betaald_AantalPostenTeLaatBetaald,
         @Betaald_KortsteBetalingstermijn,  @Betaald_LangsteBetalingstermijn,   @Betaald_GemBetalingstermijn,
         @Betaald_KortsteBetOverschrijding, @Betaald_LangsteBetOverschrijding,  @Betaald_GemBetOverschrijding,
         @Betaald_BedragRenteverlies,
         @Betaald_GemToegestaneBetalingstermijn
  from   tmpDashboardDebBetAnalyse
  where  (tmpOspRksGid = @RksGid)
     and (tmpOspIsGesloten = 1);               //alleen gesloten posten

  //percentage te laat betaald berekenen
  if ((@Betaald_AantalPosten <> 0) and (@Betaald_AantalPostenTeLaatBetaald <> 0)) then
    set @Betaald_PercTeLaatBetaald = ((CAST(@Betaald_AantalPostenTeLaatBetaald as numeric(15,2)) / @Betaald_AantalPosten)  * 100)
  else
    set @Betaald_PercTeLaatBetaald = 0
  end if;

  //percentage op tijd betaald berekenen
  set @Betaald_PercOpTijdBetaald = 100 - @Betaald_PercTeLaatBetaald;

  //-------------------
  //----- totalen -----
  //-------------------
  set @Totaal_TotaalFactuurBedrag   = IsNull(@Betaald_TotaalFactuurBedrag, 0.00) + IsNull(@Open_TotaalFactuurBedrag, 0.00);
  set @Totaal_AantalPosten          = IsNull(@Betaald_AantalPosten, 0)           + IsNull(@Open_AantalPosten, 0);
  set @Totaal_BedragRenteverlies    = IsNull(@Betaald_BedragRenteverlies, 0.00)  + IsNull(@Open_BedragRenteverlies, 0.00);

  select avg(tmpOspBetalingstermijn), avg(tmpOspBetalingsOverschr), avg(tmpOspToegestaneBetalingstermijn)
    into @Totaal_GemBetalingstermijn, @Totaal_GemBetOverschrijding, @Totaal_GemToegestaneBetalingstermijn
  from tmpDashboardDebBetAnalyse
  where (tmpOspRksGid = @RksGid);

  //call traceEind('Dashboard_Debiteur_BetAnalyseBepaalTotalen');

end;



//Aanmaken tijdelijke tabel met Osp''s die getoond moeten worden.
//Op basis van deze tabel worden osp''s geselecteerd in andere stored procs
//op basis waarvan de berekening van de totalen voor de debiteuren analyse gedaan wordt

create or replace procedure Dashboard_Debiteur_BetAnalyseDebTmpTabVullen(
  in @NawGid Integer,
  in @VanFactuurDatum            date,
  in @TotFactuurDatum            date,
  in @AfdrNogOpenstaandePosten   smallint,
  in @AfdrGeblokkeerdePosten     smallint,
  in @AfdrNietVervallenPosten    smallint,
  in @Peildatum                  date,
  in @RentePercentage			 numeric(15,3),
  in @AfdrValutaDebOfBasisFact   smallint, //valuta van facturen: 0=van OSP, 1=van debiteur, 2=basisvaluta
  in @AfdrValutaDebOfBasisDebTot smallint  //valuta van debiteurtotalen: 0=van debiteur, 1=basisvaluta
)

begin
  declare @HulpBjGid 	integer;
  declare @HulpPerNr 	integer;
  declare @RksGid	 	integer;
  declare @NawValNummer integer;


//  call traceBegin('Dashboard_Debiteur_BetAnalyseDebTmpTabVullen');

  //tbv. omrekenen van valuta-omrekening
  call BepaalBoekjaarEnPeriode(@@VerwerkingsDatum, @HulpBjGid, @HulpPerNr);

  select nawfilRksGID, nawFilValNummer into @RksGid, @NawValNummer from tabNawfile where nawFilNawGid=@NawGid;

  //NB 20-5-03: een post is gesloten als OP DE PEILDATUM Factuurbedrag - Betaaldbedrag = 0.
  //Oftwel: een sum op de factuurboekingen en betalingsboekingen op de peildatum... Zucht.
  insert into tmpDashboardDebBetAnalyse(
								tmpOspGidje, tmpOspRksGid, tmpOspFactuurnummer, tmpOspFactuurnummer_Lengte, tmpOspOms, tmpOspValCode, tmpOspValNummer,
                                tmpOspFactuurdatum, tmpOspVervaldatum,  tmpOspIsGeblokkeerd,
                                tmpOspValNrAfdrFact, tmpOspValCodeAfdrFact, tmpOspValNrAfdrDebTot,
                                tmpOspFactuurbedrag, tmpOspBetaaldBedrag, tmpOpenstaandBedrag, tmpOspGeblokkeerdBedrag,
                                tmpOspIsGesloten,
                                tmpOspDatumLaatstePosCredBetaling,
                                tmpOspBetalingsOverschr, tmpOspBetalingstermijn, tmpOspToegestaneBetalingstermijn, tmpOspRenteverlies,

                                //alles in afdruk valuta factuur
                                tmpOspFactuurbedragInAfdrValFact, tmpOspBetaaldBedragInAfdrValFact, tmpOpenstaandBedragInAfdrValFact, tmpOspGeblokkeerdBedragInAfdrValFact,
                                tmpOspDirectTeVoldoenInAfdrValFact, tmpOspRenteverliesInBasisvaluta,

                                //alles in afdruk valuta debiteur
                                tmpOspFactuurbedragInAfdrValDeb, tmpOspBetaaldBedragInAfdrValDeb, tmpOpenstaandBedragInAfdrValDeb, tmpOspGeblokkeerdBedragInAfdrValDeb,
                                tmpOspDirectTeVoldoenInAfdrValDeb
                                )
  select distinct
   //factuurbedrag en betaaldbedrag, aangepast in juiste keuze van voorlopig of defininitieve gegevens
    OspGid,
	OspRksGid,
    OspFactuurnummer,
	OspFactuurNummer_Lengte,
    OspOms,

    OspValCode,
    OspValNummer,

    OspFactuurdatum,
    OspVervaldatum,
    OspIsGeblokkeerd as IsGeblokkeerd,

    //voor de totaal-berekeningen over alle osps van één debiteur de osp-bedragen omrekenen naar
    //eenzelfde valuta: de valuta waarin de debiteur totalen moeten worden afgedrukt
    //@AfdrValNrFactDebOfBasisFact -> de valuta waarin de debiteur totalen moeten
    //worden afgedrukt, in valuta van debiteur moet zijn of in basisvaluta
    (Case @AfdrValutaDebOfBasisFact
      when 0 then OspValNummer                                                             //valutanr van factuur
      when 1 then @nawValNummer                                                            //val van debiteur
      when 2 then @@BasisValutaNummer                                                      //basisvalutanr
    end) as ValNrAfdrFact,

    (select valCode from tabValuta where valNummer = ValNrAfdrFact) as ValCodeAfdrFact,

    (if @AfdrValutaDebOfBasisDebTot = 0 then
      (@nawValNummer)                                                                    //valutanr van debiteur
    else
      @@BasisValutaNummer                                                                  //basisvalutanr
    endif) as ValNrAfdrDebTot,

    (IsNull((select sum(JrValutaBedrag)
			 from tabJournaalregel
			 where (JrOspGid = OspGid) and (IsCreditBoeking = 0) and (JrBoekdatum <= @Peildatum)),0)
	) as FactuurBedrag,

	(IsNull((select sum(JrValutaBedrag)
			 from tabJournaalregel
             where (JrOspGid = OspGid) and (IsCreditBoeking = 1) and (JrBoekdatum <= @Peildatum)),0)
    ) as BetaaldBedrag,

    (FactuurBedrag - BetaaldBedrag) as OpenstaandBedrag,

    //openstaand bedrag, alleen indien factuur geblokkeerd is
    (if IsGeblokkeerd = 1 then OpenstaandBedrag else 0 endif) as GeblokkeerdBedrag,

	//peildatum zit al in factuur- en betaaldbedrag verwerkt, hoeft hier niet nog eens
    (if FactuurBedrag = BetaaldBedrag then 1 else 0 endif) as OspIsGesloten,

    (select max(JournaalLaatsteBetaling.JrBoekdatum)
     from   tabJournaalRegel JournaalLaatsteBetaling
     where  (JournaalLaatsteBetaling.JrRksGid = OspRksgid)              //naw-gid
        and (JournaalLaatsteBetaling.JrReferentie = OspFactuurNummer)   //factuurnummer
        and (JournaalLaatsteBetaling.JrReferentie_Lengte = OspFactuurNummer_Lengte)
        and (JournaalLaatsteBetaling.JrFactuurdatum = OspFactuurdatum) //datum, om unieke factuur terug te vinden , samen met naw-gid en factuurnummer
        and (JournaalLaatsteBetaling.IsCreditBoeking = 1)              //alleen creditboekingen
        and (JournaalLaatsteBetaling.JrValutaBedrag > 0)               //positieve creditboeking (dus geen terugbetaling door 'ons')
        and (JournaalLaatsteBetaling.JrBoekdatum <= @Peildatum)        //situatie t/m de peildatum; betalingen daarna tellen niet mee
      )
      as DatumLaatstePosCredBetaling,

    //tmpOspBetalingsOverschr -> hoe veel te laat iemand was met betalen
    //De betalingsoverschrijding kan ook niet negatief worden. Als de factuur binnen 14 dagen betaald
    //moet worden en je betaalt na 9, dan is de betalingsoverschrijding dus niet meer -5, maar 0.
    //Als je vooruit betaalt, dus vóór de factuurdatum, dan wordt de ook gewoon 0. Niets negatiefs.
    (if OspIsGesloten = 1 then
       if DatumLaatstePosCredBetaling is null then
         0
       else
         if (DatumLaatstePosCredBetaling <= OspVervaldatum) then   //als hij op tijd of vooruit is betaald wordt het 0
           0
         else
           (DatumLaatstePosCredBetaling - OspVervaldatum)          //als ie te laat betaald is: verschil tussen betalingsdatum en vervaldatum
         endif
       endif
     else
       //bij open posten is de betalingsoverschrijding verschil tussen vervaldatum en peildatum
       if (@Peildatum - OspVervalDatum) <= 0 then  //er is nog tijd om te betalen: dan 0
         0
       else
         (@Peildatum - OspVervalDatum)             //de vervaldatum is verstreken: hij is te laat
       endif
     endif) as OspBetalingsOverschr,

    //tmpOspBetalingstermijn -> hoe lang iemand er over heeft gedaan te betalen: ook wel 'betalingstermijn' genoemd
    //De betalingstermijn kan niet negatief worden. Als je 10 dagen vooruit
    //betaalt, dus vóór de factuurdatum, dan wordt de betalingstermijn dus 0 en niet -10.
    (if OspIsGesloten = 1 then
       if DatumLaatstePosCredBetaling is null then
        0
      else
        if (DatumLaatstePosCredBetaling < OspFactuurdatum) then  //als vooruit is betaald...
          0                                                      //wordt de betalingstermijn 0 en niet negatief.
        else
          (DatumLaatstePosCredBetaling - OspFactuurdatum)        //als na de factuurdatum is betaald, dan betalingsdatum - factuurdatum. Kan niet negatief worden.
        endif
      endif
    else
      //bij open posten is de Betalingstermijn het verschil tussen peildatum en factuurdatum
      if (@Peildatum - OspFactuurdatum) < 0 then
        0
      else
        (@Peildatum - OspFactuurdatum)
      endif
    endif) as OspBetalingstermijn,

    //de toegestane betalingstermijn: hoe lang iemand erover mag doen om te betalen
    (OspVervaldatum - OspFactuurdatum) as ToegestaneBetalingstermijn,

    //Renteverlies berekenen over: posten waar berekeningen over gemaakt moeten worden, en die te laat
    //betaald zijn (gesloten) of waarvan de peildatum na de vervaldatum ligt (open post).
    (if @RentePercentage= 0 then
       0.0
     else
       if (OspIsGesloten = 1) then
         if (DatumLaatstePosCredBetaling > OspVervaldatum) then //te laat betaald
           IsNull(RapBetAnalyseRenteVerliesOSPBerekenen(OspGid, OspIsGesloten, 2, FactuurBedrag, OspVervaldatum, @RentePercentage, @Peildatum),0)
         else    //11
           0 //22
         endif
       else //post is dus open
         if (@Peildatum > OspVervaldatum) then //peildatum voorbij vervaldatum, dus te laat
           IsNull(RapBetAnalyseRenteVerliesOSPBerekenen(OspGid, OspIsGesloten, 2, FactuurBedrag, OspVervaldatum, @RentePercentage, @Peildatum),0)
         else//33
           0 //44
         endif
        endif
       endif) as Renteverlies,

//------------------------------------------------------------------------------

    //ALLES OMREKENEN NAAR DE VALUTA VAN FACTUUR
    (if (@AfdrValutaDebOfBasisFact = 0) or (OspValNummer = ValNrAfdrFact) then
       Factuurbedrag
     else
       ValutaOmrekenen(OspValNummer, FactuurBedrag, ValNrAfdrFact, @HulpBjGid, @HulpPerNr, 2)
     endif) as FactuurbedragInAfdrValFact,

    (if (@AfdrValutaDebOfBasisFact = 0) or (OspValNummer = ValNrAfdrFact) then
       BetaaldBedrag
     else
       ValutaOmrekenen(OspValNummer, BetaaldBedrag, ValNrAfdrFact, @HulpBjGid, @HulpPerNr, 2)
     endif) as BetaaldBedragInAfdrValFact,

    (if (@AfdrValutaDebOfBasisFact = 0) or (OspValNummer = ValNrAfdrFact) then
       OpenstaandBedrag
     else
       ValutaOmrekenen(OspValNummer, OpenstaandBedrag, ValNrAfdrFact, @HulpBjGid, @HulpPerNr, 2)
     endif) as OpenstaandBedragInAfdrValFact,

     (if (@AfdrValutaDebOfBasisFact = 0) or (OspValNummer = ValNrAfdrFact) then
        GeblokkeerdBedrag
      else
        ValutaOmrekenen(OspValNummer, GeblokkeerdBedrag, ValNrAfdrFact, @HulpBjGid, @HulpPerNr, 2)
     endif) as GeblokkeerdBedragInAfdrValFact,

    //direct te voldoen: niet geheel betaalde facturen, die vervallen zijn
    (if (OspIsGesloten = 0) and (OspVervalDatum < @Peildatum) then
	   (FactuurbedragInAfdrValFact - BetaaldBedragInAfdrValFact)
     else
       0
     endif) as DirectTeVoldoenInAfdrValFact,

    //renteverlies: is altijd in basisvaluta
    (if (@AfdrValutaDebOfBasisFact <> 2) then
       ValutaOmrekenen(OspValNummer, Renteverlies, @@BasisValutaNummer, @HulpBjGid, @HulpPerNr, 2)
     else
       Renteverlies
     endif) as RenteverliesInBasisvaluta,

//------------------------------------------------------------------------------

     //ALLES OMREKENEN NAAR DE VALUTA VAN DE DEBITEUR TOTALEN
     (if ValNrAfdrDebTot = OspValNummer then
        Factuurbedrag
      else
        if ValNrAfdrDebTot = ValNrAfdrFact then
          FactuurbedragInAfdrValFact
        else
          ValutaOmrekenen(OspValNummer, FactuurBedrag,ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)
        endif
      endif) as FactuurBedragInAfdrValDeb,

     (if ValNrAfdrDebTot = OspValNummer then
         BetaaldBedrag
       else
        if ValNrAfdrDebTot = ValNrAfdrFact then
          BetaaldBedragInAfdrValFact
        else
          ValutaOmrekenen(OspValNummer, BetaaldBedrag, ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)
        endif
      endif) as BetaaldBedragInAfdrValDeb,

     (if ValNrAfdrDebTot = OspValNummer then
        OpenstaandBedrag
      else
        if ValNrAfdrDebTot = ValNrAfdrFact then
          OpenstaandBedragInAfdrValFact
        else
          ValutaOmrekenen(OspValNummer, OpenstaandBedrag, ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)
        endif
      endif) as OpenstaandBedragInAfdrValDeb,

     (if ValNrAfdrDebTot = OspValNummer then
        GeblokkeerdBedrag
      else
        if ValNrAfdrDebTot = ValNrAfdrFact then
          GeblokkeerdBedragInAfdrValFact
        else
          ValutaOmrekenen(OspValNummer, GeblokkeerdBedrag, ValNrAfdrDebTot, @HulpBjGid, @HulpPerNr, 2)
        endif
      endif) as GeblokkeerdBedragInAfdrValDeb,

     //direct te voldoen: niet geheel betaalde facturen, die vervallen zijn
     (if (OspIsGesloten = 0) and (OspVervalDatum < @Peildatum) then
		(FactuurBedragInAfdrValDeb - BetaaldBedragInAfdrValDeb)
      else
        0
      endif) as DirectTeVoldoenInAfdrValutaDeb

//--------------------------------------------------------------------------------------------

  // de view slecteert van osp''s die er dubbel in zitten alleen die van het laatste boekjaar
  from  tabOpenstaandePost

  where
        (ospRksGid = @RksGID)

            //binnen de range van factuurdatum
        AND (OspFactuurDatum between @VanFactuurDatum and @TotFactuurDatum)

            //facturen van na de peildatum doen niet mee
        AND (OspFactuurdatum <= @Peildatum)

            //als de niet-vervallen posten getoond moeten worden: alleen die waarvan de vervaldatum vóór de peildatum ligt.
        AND ( (@AfdrNietVervallenPosten = 1) or ((@AfdrNietVervallenPosten = 0) and (OspVervalDatum < @Peildatum)) )

            //als alleen gesloten posten mee mogen, dan moet betaald bedrag precies 0 zijn, anders maakt het niet uit
        AND ( (@AfdrNogOpenstaandePosten = 1) or ((@AfdrNogOpenstaandePosten = 0) and (FactuurBedrag - BetaaldBedrag = 0)))

            //nooit creditnota''s tonen: factuurbedrag moet altijd positief zijn.
        AND (FactuurBedrag >= 0)

            //bij geen geblokkeerde posten meenemen: geblokkeerd = false, anders maakt het niet uit
        AND ( (@AfdrGeblokkeerdePosten = 1) or ((@AfdrGeblokkeerdePosten = 0) and (OspIsGeblokkeerd = 0)) )

        //van osp''s die er dubbel in zitten: alleen die nemen van het laatste boekjaar
        AND (OspGid not in (select
                              distinct NietGebruikteJournaalregel.JrOSPgid
                            from
                              tabJournaalregel NietGebruikteJournaalregel
                              inner join tabBoekjaar NietGebruiktBoekjaar on (NietGebruikteJournaalRegel.JrBjGid = NietGebruiktBoekjaar.BjGid)
                            where
                              JrOspGid is not null and
                              NietGebruikteJournaalregel.JrRksGid = @RksGID and
                            exists (select                       // Lees alle boekjaren waarvoor geldt dat de OSP een boeking heeft in een boekjaar NA dit boekjaar
                                      TestJournaalRegel.JrBjGid  // Gebruik ALLEEN journaalregels die NIET in dit gelezen boekjaar zitten
                                    from
                                      tabJournaalregel TestJournaalRegel
                                    inner join tabBoekjaar TestBoekjaar on (TestJournaalRegel.JrBjGid = TestBoekjaar.BjGid)
                                    where
                                      TestJournaalRegel.JrRksGid        = NietGebruikteJournaalregel.JrRksGid       and
                                      TestJournaalRegel.JrFactuurDatum  = NietGebruikteJournaalregel.JrFactuurDatum and
                                      TestJournaalRegel.JrReferentie    = NietGebruikteJournaalregel.JrReferentie   and
                                      TestJournaalRegel.JrReferentie_Lengte = NietGebruikteJournaalregel.JrReferentie_Lengte and
                                      TestBoekjaar.BjBeginDatum         > NietGebruiktBoekjaar.BjBeginDatum
            )              )       )
  ;



//  call traceEind('Dashboard_Debiteur_BetAnalyseDebTmpTabVullen');

end;




create or replace procedure Dashboard_Debiteur_Omzet_Per_Kwartaal(in @NawGid integer)
result(Boekjaar nchar(10), Kwartaal1 numeric(15,3), Kwartaal2 numeric(15,3), Kwartaal3 numeric(15,3), Kwartaal4 numeric(15,3), Totaal numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select Code as BoekJaar,
         //1e kwartaal
         IsNull(sum(if ((OmzDatum >= BjBeginDatum)                     and (OmzDatum < DATEADD( month,  3, BjBeginDatum))) then OmzOmzetBasis else 0.00 endif), 0.00) as Kwartaal1,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 3, BjBeginDatum)) and (OmzDatum < DATEADD( month,  6, BjBeginDatum))) then OmzOmzetBasis else 0.00 endif), 0.00) as Kwartaal2,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 6, BjBeginDatum)) and (OmzDatum < DATEADD( month,  9, BjBeginDatum))) then OmzOmzetBasis else 0.00 endif), 0.00) as Kwartaal3,
         IsNull(sum(if ((OmzDatum >= DATEADD( month, 9, BjBeginDatum)) and (OmzDatum < DATEADD( month, 12, BjBeginDatum))) then OmzOmzetBasis else 0.00 endif), 0.00) as Kwartaal4,
         IsNull(Kwartaal1 + Kwartaal2 + Kwartaal3 + Kwartaal4, 0.00) as Totaal
  from   tabBoekjaar
         left outer join tabOmzet on (OmzFinBjGid = bjGid) and (OmzNawGid = @NawGid)
  where BjGid in (select top 5 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
  group by BjBeginDatum, BoekJaar
  order by BjBeginDatum, BoekJaar;
end;


create or replace procedure Dashboard_Debiteur_Omzet_Per_Periode(in @NawGid integer)
result(BoekjaarCode nchar(10), PerNr smallint, Bedrag numeric(15,3))
begin
  declare @Peildatum   date;
  declare @HuidigBjGid integer;
  declare @Pernr      smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  select Code, PerNr, IsNull(sum(OmzOmzetBasis), 0 )
  from   tabBoekjaar
  inner join tabPeriode on (PerBjGid = BjGid)
  left outer join tabOmzet on (OmzFinBjGid = bjGid and OmzFinPerNr = PerNr and OmzNawGid = @NawGid)
  where BjGid in (select top 3 BjGid from tabBoekjaar where BjGid = @HuidigBjGid or @PeilDatum > BjEindDatum order by BjEindDatum desc)
  group by Code, PerNr
  having PerNr <> 0
  order by Code, PerNr
end;


create or replace procedure Dashboard_Debiteur_OpenstaandeOffertes(in @NawGid Integer)
result(offGid integer, ofkGid integer, OfkOffertenummer nchar(14), OfkAanmaakdatum date, OfkReferentie Long nvarchar,
	   OfkStatus smallint, OfkGeldigheidsdatum date, GeldigheidVerlopen smallint)
begin
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //offertes van  debiteur ophalen
  SELECT
        offGid,
        ofkGid,
		OfkOffertenummer,
		OfkAanmaakdatum,
		(If IsNull(OfkReferentie,'') = '' then OffReferentie else OfkReferentie endif),
		OfkStatus,
		OfkGeldigheidsdatum,
		(if OfkGeldigheidsdatum < @Peildatum then 1 else 0 endif)
  FROM  tabOfferte
		INNER JOIN tabOffertekop ON (OfkOffGid = OffGid)
  WHERE (OffNawGidDebiteur = @NawGid)  //geslecteerde debiteur
	AND OfkStatus in (0,1,2) //Openstaande offertes
  ORDER BY OfkGeldigheidsdatum, OffOffertenummer, OfkVersienummer;

end;
//call Dashboard_Debiteur_OpenstaandeOffertes((select first nawfilnawgid from tabNawFile where nawFilNummer=12001613));

create or replace procedure Dashboard_Debiteur_OpenstaandeOrders(in @NawGid Integer)
result(OrkGid integer, OrkNummer numeric(10,0), OrkDatum date, OrkLeverDatum date, OrkReferentie Long nvarchar,
       ValCode nchar(3), OrkTotaalExclBtw numeric(15,2), OrkTotaalInclBtw numeric(15,2),
	   RegelsMetBackorders integer)
begin

  //orders van  debiteur ophalen
  SELECT
    OrkGid,
		OrkNummer,
		OrkDatum,
    OrkLeverDatum,
		OrkReferentie,
		ValCode,
		OrkTotaalExclBtw,
		OrkTotaalInclBtw,
		(select count(1) from tabOrderregel where (orrOrkGid=OrkGid) and (OrrRegelsoort=2) and ((OrrAantalBackorder<>0) or (OrrAantalBackorderVrrdEenh<>0)) )
  FROM  tabOrderKop
  INNER JOIN tabValuta ON (ValNummer = OrkValNummer)
  WHERE (OrkNawGid = @NawGid)  //geslecteerde debiteur
  ORDER BY OrkDatum desc, OrkNummer;

end;


create or replace procedure Dashboard_Debiteur_OSP_OuderdomsAnalyse(in @NawGid Integer)
result(OuderdomsRange integer, LabelOuderdomsRange nchar(20), AantalOpenstaandePosten integer, AantalVervallenPosten integer, ValCode nchar(3), OpenstaandBedrag numeric(15,2), VervallenBedrag numeric(15,2))
begin
  declare @Dagen1    smallint;
  declare @Dagen2    smallint;
  declare @Dagen3    smallint;
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;
  declare @RksGID    integer;
  declare @ValNummer smallint;
  declare @ValCode   nchar(3);

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //ophalenn indeling ouderdomsanalyse OSP debiteuren
  select Contents into @Dagen1 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_EERSTE';
  select Contents into @Dagen2 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_TWEEDE';
  select Contents into @Dagen3 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_DERDE';
  set @Dagen2 = @Dagen2 + @Dagen1;
  set @Dagen3 = @Dagen3 + @Dagen2;

  //gegegens van debiteur ophalen
  SELECT NawFilRksGID, NawFilValNummer, ValCode
  INTO   @RksGID,      @ValNummer,      @ValCode
  FROM   tabNawFile
  INNER JOIN tabValuta ON (ValNummer = NawFilValNummer)
  WHERE NawFilNawGid=@NawGid;

  //haal gegevens openstaande posten op
  SELECT
	OuderdomsRange,

    Case OuderdomsRange
      when 1 then '0-' + string(@Dagen1)
      when 2 then string(@Dagen1 + 1) + '-' + string(@Dagen2)
      when 3 then string(@Dagen2 + 1) + '-' + string(@Dagen3)
      when 4 then string(@Dagen3 + 1) + '-'
    end case as LabelOuderdomsRange,

    SUM(AantalOpenstaandePosten),
    SUM(AantalVervallenPosten),

    @Valcode as ValCode,

    SUM(OpenstaandBedrag),
    SUM(VervallenBedrag)
  FROM
  (
    //openstaande posten van meegegeven debiteur
    select
      // NR ouderdomsrange
      (if @PeilDatum <= (OspFactuurDatum) + @Dagen1 then 1
       else if @PeilDatum between (OspFactuurDatum) + @Dagen1 + 1 and (OspFactuurDatum) + @Dagen2 then 2
       else if @PeilDatum between (OspFactuurDatum) + @Dagen2 + 1 and (OspFactuurDatum) + @Dagen3 then 3
       else 4
       endif endif endif
      ) as OuderdomsRange,

      //aantal openstaande posten
      sum(1) as AantalOpenstaandePosten,

      //aantal vervallen posten posten
      sum(if OspVervalDatum < @PeilDatum then 1 else 0 endif) as AantalVervallenPosten,

      //Bedrag aan openstaande posten
      sum(IsNull((if OspValNummer = @ValNummer then
                     (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                      ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @ValNummer, @BjGid, @PerNr, 2)
                  endif), 0.00)) as OpenstaandBedrag,

      //vervallen bedrag
      sum(if OspVervalDatum < @PeilDatum then
            IsNull((if OspValNummer = @ValNummer then
                     (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                    else
                      ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @ValNummer, @BjGid, @PerNr, 2)
                    endif), 0.00)
          else
        0.00 endif) as VervallenBedrag

    from tabOpenstaandePost
    where
      OspRksGid = @RksGid
      //OspIsCrediteur        = 0       //Alleen osp van debiteuren
      and (OspIsVervallen   = 0)      //alleen nog openstaande posten
      and (OspIsGeblokkeerd = 0)      //alleen niet geblokkeerde posten ?
      and OspBjGid          = @BjGid  //en op dit boekjaar betrekking hebben
    group by OuderdomsRange

    //Eventuele lege ranges opnemen
    Union all
      Select 1,0,0,0,0
    Union all
      Select 2,0,0,0,0
    Union all
      Select 3,0,0,0,0
    Union all
      Select 4,0,0,0,0
  ) A
  GROUP BY OuderdomsRange
  ORDER BY OuderdomsRange

end;


create or replace procedure Dashboard_Debiteur_OSP_OudstePosten(in @NawGid Integer)
result(OspFactuurNummer nchar(40), OspFactuurDatum date, OspVervalDatum date, OspValCode nchar(3),
       Factuurbedrag numeric(15,2), OpenstaandBedrag numeric(15,2), OspBedragOnderwegInValuta numeric(15,2),
	   OspSoortFactuur smallint, OspIsGeblokkeerd smallint, VervaldatumVerstreken smallInt)
begin
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;
  declare @RksGID    integer;
  declare @ValNummer smallint;
  declare @ValCode   nchar(3);

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //gegegens van debiteur ophalen
  SELECT NawFilRksGID, NawFilValNummer, ValCode
  INTO   @RksGID,      @ValNummer,      @ValCode
  FROM   tabNawFile
  INNER JOIN tabValuta ON (ValNummer = NawFilValNummer)
  WHERE NawFilNawGid=@NawGid;


  SELECT TOP(10)
		OspFactuurNummer,
		OspFactuurDatum,
        OspVervalDatum,
		OspValCode,
		(OspFactuurBedragDefinitief+OspFactuurBedragVoorlopig), //Factuurbedrag
		(OspFactuurBedragDefinitief+OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief+OspBetaaldBedragVoorlopig), //Openstaand
        OspBedragOnderwegInValuta,
		OspSoortFactuur,
		OspIsGeblokkeerd,
		(IF OspVervaldatum < @peildatum then 1 else 0 endif)
  FROM  tabOpenstaandePost
  WHERE (OspRksGID = @RksGid)  //geslecteerde debiteur
    AND (OspBjGid  = @BjGid)   //huidig boekjaar
	AND (OspIsVervallen = 0)   //Niet volledig betaald
  ORDER BY OspFactuurDatum, OspFactuurNummer;

end;

//call Dashboard_Debiteur_OSP_OudstePosten(1048814);

create or replace procedure Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(out @PeilDatum date, out @BjGid integer, out @PerNr smallint)
begin
  declare @BjBeginDatum Date;
  declare @BjEindDatum  Date;

  //bepaal begin/einddata geselecteerde boekjaar
  select  BjBeginDatum,  BjEindDatum
    into @BjBeginDatum, @BjEindDatum
    from tabBoekjaar
    where @@Verwerkingsdatum between BjBeginDatum and BjEindDatum;

  // Als peildatum wordt de huidige systeemdatum gebruikt. Alleen in het geval dat de verwerkingsdatum in een vorig boekjaar valt, dan gebruiken we als peildatum de laatste datum van dat jaar.
  set @PeilDatum = Today();

  //als @peildatum > laatste datum van geselecteerde boekjaar, dan als @Peildatum is laatste datum boekjaar
  if @Peildatum > @BjEindDatum then
    set @Peildatum = @BjEindDatum
  else if @Peildatum < @BjBeginDatum then
    set @Peildatum = @BjBeginDatum
  endif endif;

  //bepaal boekjaar en periode o.b.v. peildatum
  call BepaalBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

//  call trace('@@Verwerkingsdatum : '+String(@@Verwerkingsdatum));
//  call trace('@Peildatum: '+String(@Peildatum));
//  call trace('@BjGid: '+String(@BjGid));
//  call trace('@PerNr: '+String(@PerNr));

end;


create or replace procedure Dashboard_Liquiditeit()
result(Volgorde integer, IsTotaalTelling smallint, Label nchar(40), Bedrag numeric(15,3))
begin
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;

  declare local temporary table tmpLiquiditeit
  ( Volgorde        smallint,
    IsTotaalTelling smallint,
    Label           nchar(40),
    Bedrag          numeric(15,3),
    primary key (Volgorde)
  ) on commit preserve rows;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //Kas/bank
  insert into tmpLiquiditeit(Volgorde, IsTotaalTelling, Label, Bedrag)
  select   10 + if DagboekSoort = 4 then 1 else 2 endif,
           0,
           if DagboekSoort = 3 then _U('Saldo kas') else _U('Saldo bank') endif,
           sum((SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief) - (SaldoCreditBasisVoorlopig + SaldoCreditBasisDefinitief))
  from     tabDagboek inner join tabRekeningsaldo on (RekSaldoRksgid = DgbTegenRksGid)
  where    RekSaldoBjGid = @BjGid and DagboekSoort in (3,4)
  group by Dagboeksoort;

  if not exists(select 1 from tmpLiquiditeit where Volgorde = 11) then
    insert into tmpLiquiditeit(Volgorde, IsTotaalTelling, Label, Bedrag)
    select 11, 0, _U('Saldo bank'), 0;
  end if;

  if not exists(select 1 from tmpLiquiditeit where Volgorde = 12) then
    insert into tmpLiquiditeit(Volgorde, IsTotaalTelling, Label, Bedrag)
    select 12, 0, _U('Saldo kas'), 0;
  end if;

  //Debiteuren/crediteuren
  insert into tmpLiquiditeit(Volgorde, IsTotaalTelling, Label, Bedrag)
  select   20 + if Defaultsoort = 6 then 1 else 2 endif,
           0,
           if Defaultsoort = 6 then _U('Saldo debiteuren') else _U('Saldo crediteuren') endif,
           sum((SaldoDebetBasisVoorlopig + SaldoDebetBasisDefinitief) - (SaldoCreditBasisVoorlopig + SaldoCreditBasisDefinitief))
  from     tabRekeningschema inner join tabRekeningsaldo on (RekSaldoRksgid = RksGid)
  where    RekSaldoBjGid = @BjGid and Defaultsoort in (6,7)
  group by DefaultSoort;

  if not exists(select 1 from tmpLiquiditeit where Volgorde = 21) then
    insert into tmpLiquiditeit(Volgorde, IsTotaalTelling, Label, Bedrag)
    select 21, 0, _U('Saldo debiteuren'), 0;
  end if;

  if not exists(select 1 from tmpLiquiditeit where Volgorde = 22) then
    insert into tmpLiquiditeit(Volgorde, IsTotaalTelling, Label, Bedrag)
    select 22, 0, _U('Saldo crediteuren'), 0;
  end if;

  insert into tmpLiquiditeit(Volgorde, IsTotaalTelling, Label, Bedrag)
  select 19, 1, _U('Totaal bank/kas'), sum(Bedrag) from tmpLiquiditeit where Volgorde in (11, 12);

  insert into tmpLiquiditeit(Volgorde, IsTotaalTelling, Label, Bedrag)
  select 99, 1, _U('Totaal'), sum(Bedrag) from tmpLiquiditeit where IsTotaalTelling = 0;

  select Volgorde, IsTotaalTelling, Label, Bedrag
  from tmpLiquiditeit
  order by 1;

end;


create or replace procedure Dashboard_Liquiditeit_Prognose30dagen()
result(Serie SmallInt, Datum date, Bedrag numeric(15,3))
begin
  declare @Peildatum  date;
  declare @BjGid      integer;
  declare @Pernr      smallint;
  declare @BeginSaldo numeric(15,3);
  declare @Dagen      smallint;
  declare @OspSaldoDebReedsVervallenVoorPeilDatum numeric(15,3);
  declare @OspSaldoCredReedsVervallenVoorPeilDatum numeric(15,3);

  declare local temporary table tmp30Dagen
  ( Serie         smallint,
    Datum         date,
    MutatieBedrag numeric(15,3) default 0,
    primary key (Serie, Datum)
  ) on commit preserve rows;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //Vul tabel met de mutaties obv de openstaande posten, posten die op de betreffende dag vervallen
  insert into tmp30Dagen(Serie, Datum, MutatieBedrag)
  select 1, OspVervalDatum,
         IsNull(sum(if OspValNummer = @@BasisValutaNummer then
                     (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                    else
                      ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                    endif * if OspIsCrediteur = 1 then -1 else 1 endif), 0)
    from tabOpenstaandePost
    where OspVervalDatum between @PeilDatum and @PeilDatum + 30
    and (OspIsVervallen = 0)
    and (OspIsGeblokkeerd = 0)
    and (OspBjGid       = @BjGid)
  group by OspVervalDatum;

  //Tabel vullen met de "ontbrekende" dagen
  insert into tmp30Dagen(Serie, Datum) on existing skip select 1, @PeilDatum + row_num -1 from RowGenerator where row_num <= 30;

  //Huidige saldo bepalen van bank en kasrekeningen
  select isnull(sum(if RekSaldoValnummer = @@BasisValutaNummer then
               (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief) - (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief)
             else
                ValutaOmrekenen(RekSaldoValNummer, (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief) - (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief), @@BasisValutaNummer, @BjGid, RekSaldoPerNr, 2)
             endif), 0.00) into @BeginSaldo
  from   tabDagboek inner join tabRekeningsaldo on (RekSaldoRksgid = DgbTegenRksGid)
  where  RekSaldoBjGid = @BjGid and DagboekSoort in (3,4);

  //Beginsaldo op de eerste dag in de tabel plaatsen
  update tmp30Dagen set MutatieBedrag = MutatieBedrag + @BeginSaldo where Datum = @PeilDatum;

  //De 1e serie is nu bepaald, nu gaan we de 2e serie opbouwen.
  //De 2e serie heeft de 1e serie als basis, met als aanvulling dat we het saldo van de OSPs die al vervallen zijn VOOR de peildatum, maar niet eerder vervallen
  //zijn dan de eerste kolom uit de vaste gegvens van de OSPs, mee worden geteld.

  //Dupliceren de bestaande records voor de 2e serie
  insert into tmp30Dagen(Serie, Datum, MutatieBedrag)
  select 2, Datum, MutatieBedrag from tmp30Dagen;

  //Bepaal saldo van de opstaande posten van de debiteuren, die al vervallen zijn voor de peildatum (=eerste dag van liq. prognose)
  select Contents into @Dagen from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_EERSTE';
  select IsNull(sum(if OspValNummer = @@BasisValutaNummer then
                     (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                    else
                      ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                    endif), 0) into @OspSaldoDebReedsVervallenVoorPeilDatum
  from tabOpenstaandePost
  where OspVervalDatum between @PeilDatum - @Dagen and @PeilDatum - 1
  and (OspIsCrediteur   = 0)
  and (OspIsVervallen   = 0)
  and (OspIsGeblokkeerd = 0)
  and (OspBjGid         = @BjGid);

  //Bepaal saldo van de opstaande posten van de crediteuren, die al vervallen zijn voor de peildatum (=eerste dag van liq. prognose)
  select Contents into @Dagen from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_EERSTE';
  select IsNull(sum(if OspValNummer = @@BasisValutaNummer then
                     (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                    else
                      ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                    endif), 0) into @OspSaldoCredReedsVervallenVoorPeilDatum
  from tabOpenstaandePost
  where OspVervalDatum between @PeilDatum - @Dagen and @PeilDatum - 1
  and (OspIsCrediteur   = 1)
  and (OspIsVervallen   = 0)
  and (OspIsGeblokkeerd = 0)
  and (OspBjGid         = @BjGid);

  //Beide saldi in de tabel bijwerken
  update tmp30Dagen set MutatieBedrag = MutatieBedrag + @OspSaldoDebReedsVervallenVoorPeilDatum - @OspSaldoCredReedsVervallenVoorPeilDatum where Datum = @PeilDatum and Serie = 2;

  //Cummulatief teruggeven van alle mutaties
  select Serie, Datum, sum(MutatieBedrag) over (order by Serie, Datum rows unbounded preceding) as Bedrag
  from tmp30Dagen
  where Serie = 1
  union all
  select Serie, Datum, sum(MutatieBedrag) over (order by Serie, Datum rows unbounded preceding) as Bedrag
  from tmp30Dagen
  where Serie = 2
  order by 1,2;

end;


create or replace procedure Dashboard_Omzet_Per_Periode()
result(Soort nchar(12), BoekjaarCode nchar(10), PerNr smallint, Bedrag numeric(15,3))
begin
  declare @Peildatum    date;
  declare @HuidigBjGid  integer;
  declare @VorigBjGid1  integer;
  declare @VorigBjGid2  integer;
  declare @Pernr        smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @HuidigBjGid, @PerNr);

  //Bepaald nu BjGid van vorige boekjaar
  select first BjGid into @VorigBjGid1 from tabBoekjaar where BjGid <> @HuidigBjGid and @PeilDatum > BjEindDatum order by BjEindDatum desc;
  select first BjGid into @VorigBjGid2 from tabBoekjaar where BjGid <> @HuidigBjGid and @PeilDatum > BjEindDatum and BjGid <> @VorigBjGid1 order by BjEindDatum desc;

  // huidig jaar
  select          'Serie 1', Code, PerNr, IsNull(sum(OmzOmzetBasis), 0 )
  from            tabBoekjaar
  inner join      tabPeriode on (PerBjGid = BjGid)
  left outer join tabOmzet on (OmzFinBjGid = @HuidigBjGid and OmzFinPerNr = PerNr)
  where           BjGid = @HuidigBjGid
  group by        Code, PerNr

  union all

  // vorig jaar
  select          'Serie 2', Code, PerNr, IsNull(sum(OmzOmzetBasis), 0 )
  from            tabBoekjaar
  inner join      tabPeriode on (PerBjGid = BjGid)
  left outer join tabOmzet on (OmzFinBjGid = @VorigBjGid1 and OmzFinPerNr = PerNr)
  where           BjGid = @VorigBjGid1
  group by        Code, PerNr

  union all

  // jaar voor vorig jaar
  select          'Serie 3', Code, PerNr, IsNull(sum(OmzOmzetBasis), 0 )
  from            tabBoekjaar
  inner join      tabPeriode on (PerBjGid = BjGid)
  left outer join tabOmzet on (OmzFinBjGid = @VorigBjGid2 and OmzFinPerNr = PerNr)
  where           BjGid = @VorigBjGid2
  group by        Code, PerNr
  order by        1, 2, 3;

end;


create or replace procedure Dashboard_OSP_Crediteuren_AantalDagenOpen()
result(MaxDagen integer, DagenGemiddeld integer)
begin
  declare @Dagen     smallint;
  declare @MaxDagen  integer;
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  set @MaxDagen = 0;
  select Contents into @Dagen from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_EERSTE';
  set @MaxDagen = @MaxDagen + @Dagen;
  select Contents into @Dagen from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_TWEEDE';
  set @MaxDagen = @MaxDagen + @Dagen;
  select Contents into @Dagen from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_DERDE';
  set @MaxDagen = @MaxDagen + @Dagen;

  select first MaxDagen, DagenGemiddeld
  from (
        select if DagenGemiddeld > @MaxDagen then DagenGemiddeld else @MaxDagen endif as MaxDagen, cast(Avg(@PeilDatum - OspFactuurDatum) as numeric(9,0)) as DagenGemiddeld
        from  tabOpenstaandePost
        where
          OspIsCrediteur      = 1       //Alleen osp van crediteuren
          and (OspIsVervallen = 0)      //alleen nog openstaande posten
          and (OspIsGeblokkeerd = 0)    //alleen niet geblokkeerde posten
          and OspBjGid        = @BjGid  //en op dit boekjaar betrekking hebben
        union all
        select @MaxDagen, 0
        ) as T
   order by 1 desc
end;


create or replace procedure Dashboard_OSP_Crediteuren_OuderdomsAnalyse_Aantal()
result(Legenda1 nchar(10), Legenda2 nchar(10), Legenda3 nchar(10), Legenda4 nchar(10),
       Aantal1  integer,   Aantal2  integer,   Aantal3  integer,   Aantal4  integer)
begin
  declare @Dagen1    smallint;
  declare @Dagen2    smallint;
  declare @Dagen3    smallint;
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  select Contents into @Dagen1 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_EERSTE';
  select Contents into @Dagen2 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_TWEEDE';
  select Contents into @Dagen3 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_DERDE';

  set @Dagen2 = @Dagen2 + @Dagen1;
  set @Dagen3 = @Dagen3 + @Dagen2;

  select
    '0-' + string(@Dagen1)                      as Legenda1,
    string(@Dagen1 + 1) + '-' + string(@Dagen2) as Legenda2,
    string(@Dagen2 + 1) + '-' + string(@Dagen3) as Lengeda3,
    string(@Dagen3 + 1) + '-'                   as Legenda4,
    sum(if @PeilDatum <= (OspFactuurDatum) + @Dagen1                                          then 1 else 0 endif) as Aantal1,
    sum(if @PeilDatum between (OspFactuurDatum) + @Dagen1 + 1 and (OspFactuurDatum) + @Dagen2 then 1 else 0 endif) as Aantal2,
    sum(if @PeilDatum between (OspFactuurDatum) + @Dagen2 + 1 and (OspFactuurDatum) + @Dagen3 then 1 else 0 endif) as Aantal3,
    sum(if @PeilDatum > (OspFactuurDatum) + @Dagen3                                           then 1 else 0 endif) as Aantal4
  from  tabOpenstaandePost
  where
    OspIsCrediteur        = 1       //Alleen osp van crediteuren
    and (OspIsVervallen   = 0)      //alleen nog openstaande posten
    and (OspIsGeblokkeerd = 0)      //alleen niet geblokkeerde posten
    and OspBjGid          = @BjGid  //en op dit boekjaar betrekking hebben
end;


create or replace procedure Dashboard_OSP_Crediteuren_OuderdomsAnalyse_Bedrag()
result(Legenda1 nchar(10),     Legenda2 nchar(10),     Legenda3 nchar(10),     Legenda4 nchar(10),
       Bedrag1  numeric(15,3), Bedrag2  numeric(15,3), Bedrag3  numeric(15,3), Bedrag4 numeric(15,3))
begin
  declare @Dagen1    smallint;
  declare @Dagen2    smallint;
  declare @Dagen3    smallint;
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  select Contents into @Dagen1 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_EERSTE';
  select Contents into @Dagen2 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_TWEEDE';
  select Contents into @Dagen3 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_CRED_DERDE';

  set @Dagen2 = @Dagen2 + @Dagen1;
  set @Dagen3 = @Dagen3 + @Dagen2;

  select
    '0-' + string(@Dagen1)                      as Legenda1,
    string(@Dagen1 + 1) + '-' + string(@Dagen2) as Legenda2,
    string(@Dagen2 + 1) + '-' + string(@Dagen3) as Lengeda3,
    string(@Dagen3 + 1) + '-'                   as Legenda4,
    sum(if @PeilDatum <= (OspFactuurDatum) + @Dagen1 then
          IsNull((if OspValNummer = @@BasisValutaNummer then
                   (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                    ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                  endif), 0)
        else
          0
        endif) as Bedrag1,

    sum(if @PeilDatum between (OspFactuurDatum) + @Dagen1 + 1 and (OspFactuurDatum) + @Dagen2 then
          IsNull((if OspValNummer = @@BasisValutaNummer then
                   (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                    ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                  endif), 0)
        else
          0
        endif) as Bedrag2,

    sum(if @PeilDatum between (OspFactuurDatum) + @Dagen2 + 1 and (OspFactuurDatum) + @Dagen3 then
          IsNull((if OspValNummer = @@BasisValutaNummer then
                   (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                    ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                  endif), 0)
        else
          0
        endif) as Bedrag3,

    sum(if @PeilDatum > (OspFactuurDatum) + @Dagen3 then
          IsNull((if OspValNummer = @@BasisValutaNummer then
                   (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                    ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                  endif), 0)
        else
          0
        endif) as Bedrag4
  from  tabOpenstaandePost
  where
    OspIsCrediteur        = 1       //Alleen osp van crediteuren
    and (OspIsVervallen   = 0)      //alleen nog openstaande posten
    and (OspIsGeblokkeerd = 0)      //alleen niet geblokkeerde posten
    and OspBjGid          = @BjGid  //en op dit boekjaar betrekking hebben
end;


create or replace procedure Dashboard_OSP_Crediteuren_Vervallenposten_Perc()
result(Percentage numeric(6,2))
begin
