create or replace procedure Dashboard_OSP_Debiteuren_AantalDagenOpen()
result(MaxDagen integer, DagenGemiddeld integer)
begin
  declare @Dagen     smallint;
  declare @MaxDagen  integer;
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  set @MaxDagen = 0;
  select Contents into @Dagen from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_EERSTE';
  set @MaxDagen = @MaxDagen + @Dagen;
  select Contents into @Dagen from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_TWEEDE';
  set @MaxDagen = @MaxDagen + @Dagen;
  select Contents into @Dagen from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_DERDE';
  set @MaxDagen = @MaxDagen + @Dagen;

  select first MaxDagen, DagenGemiddeld
  from (
        select if DagenGemiddeld > @MaxDagen then DagenGemiddeld else @MaxDagen endif as MaxDagen, cast(Avg(@PeilDatum - OspFactuurDatum) as numeric(9,0)) as DagenGemiddeld
        from  tabOpenstaandePost
        where
          OspIsCrediteur      = 0       //Alleen osp van crediteuren
          and (OspIsVervallen = 0)      //alleen nog openstaande posten
          and (OspIsGeblokkeerd = 0)    //alleen niet geblokkeerde posten
          and OspBjGid        = @BjGid  //en op dit boekjaar betrekking hebben
        union all
        select @MaxDagen, 0
        ) as T
   order by 1 desc
end;


create or replace procedure Dashboard_OSP_Debiteuren_OuderdomsAnalyse_Aantal()
result(Legenda1 nchar(10), Legenda2 nchar(10), Legenda3 nchar(10), Legenda4 nchar(10),
       Aantal1  integer,   Aantal2  integer,   Aantal3  integer,   Aantal4  integer)
begin
  declare @Dagen1    smallint;
  declare @Dagen2    smallint;
  declare @Dagen3    smallint;
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  select Contents into @Dagen1 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_EERSTE';
  select Contents into @Dagen2 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_TWEEDE';
  select Contents into @Dagen3 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_DERDE';

  set @Dagen2 = @Dagen2 + @Dagen1;
  set @Dagen3 = @Dagen3 + @Dagen2;

  select
    '0-' + string(@Dagen1)                      as Legenda1,
    string(@Dagen1 + 1) + '-' + string(@Dagen2) as Legenda2,
    string(@Dagen2 + 1) + '-' + string(@Dagen3) as Lengeda3,
    string(@Dagen3 + 1) + '-'                   as Legenda4,
    sum(if @PeilDatum <= (OspFactuurDatum) + @Dagen1                                          then 1 else 0 endif) as Aantal1,
    sum(if @PeilDatum between (OspFactuurDatum) + @Dagen1 + 1 and (OspFactuurDatum) + @Dagen2 then 1 else 0 endif) as Aantal2,
    sum(if @PeilDatum between (OspFactuurDatum) + @Dagen2 + 1 and (OspFactuurDatum) + @Dagen3 then 1 else 0 endif) as Aantal3,
    sum(if @PeilDatum > (OspFactuurDatum) + @Dagen3                                           then 1 else 0 endif) as Aantal4
  from  tabOpenstaandePost
  where
    OspIsCrediteur        = 0       //Alleen osp van debiteuren
    and (OspIsVervallen   = 0)      //alleen nog openstaande posten
    and (OspIsGeblokkeerd = 0)      //alleen niet geblokkeerde posten
    and OspBjGid          = @BjGid  //en op dit boekjaar betrekking hebben
end;


create or replace procedure Dashboard_OSP_Debiteuren_OuderdomsAnalyse_Bedrag()
result(Legenda1 nchar(10),     Legenda2 nchar(10),     Legenda3 nchar(10),     Legenda4 nchar(10),
       Bedrag1  numeric(15,3), Bedrag2  numeric(15,3), Bedrag3  numeric(15,3), Bedrag4 numeric(15,3))
begin
  declare @Dagen1    smallint;
  declare @Dagen2    smallint;
  declare @Dagen3    smallint;
  declare @Peildatum date;
  declare @BjGid     integer;
  declare @Pernr     smallint;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  select Contents into @Dagen1 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_EERSTE';
  select Contents into @Dagen2 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_TWEEDE';
  select Contents into @Dagen3 from tabregistry where RegKey = 'OSP_OUDERDOMSAN_DEB_DERDE';

  set @Dagen2 = @Dagen2 + @Dagen1;
  set @Dagen3 = @Dagen3 + @Dagen2;

  select
    '0-' + string(@Dagen1)                      as Legenda1,
    string(@Dagen1 + 1) + '-' + string(@Dagen2) as Legenda2,
    string(@Dagen2 + 1) + '-' + string(@Dagen3) as Lengeda3,
    string(@Dagen3 + 1) + '-'                   as Legenda4,
    sum(if @PeilDatum <= (OspFactuurDatum) + @Dagen1 then
          IsNull((if OspValNummer = @@BasisValutaNummer then
                   (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                    ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                  endif), 0)
        else
          0
        endif) as Bedrag1,

    sum(if @PeilDatum between (OspFactuurDatum) + @Dagen1 + 1 and (OspFactuurDatum) + @Dagen2 then
          IsNull((if OspValNummer = @@BasisValutaNummer then
                   (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                    ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                  endif), 0)
        else
          0
        endif) as Bedrag2,

    sum(if @PeilDatum between (OspFactuurDatum) + @Dagen2 + 1 and (OspFactuurDatum) + @Dagen3 then
          IsNull((if OspValNummer = @@BasisValutaNummer then
                   (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                    ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                  endif), 0)
        else
          0
        endif) as Bedrag3,

    sum(if @PeilDatum > (OspFactuurDatum) + @Dagen3 then
          IsNull((if OspValNummer = @@BasisValutaNummer then
                   (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig) - (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig)
                  else
                    ValutaOmrekenen(OspValNummer, (OspFactuurBedragDefinitief + OspFactuurBedragVoorlopig)- (OspBetaaldBedragDefinitief + OspBetaaldBedragVoorlopig), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                  endif), 0)
        else
          0
        endif) as Bedrag4
  from  tabOpenstaandePost
  where
    OspIsCrediteur        = 0       //Alleen osp van debiteuren
    and (OspIsVervallen   = 0)      //alleen nog openstaande posten
    and (OspIsGeblokkeerd = 0)      //alleen niet geblokkeerde posten
    and OspBjGid          = @BjGid  //en op dit boekjaar betrekking hebben
end;


