create or replace procedure Dashboard_Winst_Verlies()
result(Soort nchar(12), PerNr smallint, Bedrag numeric(15,3))
begin
  declare @Peildatum  date;
  declare @BjGid      integer;
  declare @Pernr      smallint;
  declare @BeginSaldo numeric(15,3);

  declare local temporary table tmpWV
  ( PerNr      smallint,
    Soort      nchar(12)     check (Soort in (_U('Opbrengsten'), _U('Kosten'), _U('Resultaat'))),
    Bedrag     numeric(15,3) default 0
  ) on commit preserve rows;

  call Dashboard_GeefPeilDatumInclusiefBoekjaarEnPeriode(@PeilDatum, @BjGid, @PerNr);

  //Opbrengsten
  insert into tmpWV(PerNr, Soort, Bedrag)
  select            PerNr,
                    _U('Opbrengsten'),
                    sum(IsNull((if RekSaldoValNummer = @@BasisValutaNummer then
                                 (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief) - (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief)
                                else
                                  ValutaOmrekenen(RekSaldoValNummer, (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief) - (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                                endif), 0))
  from               tabPeriode
  left outer join   (tabRekeningsaldo
                     inner join tabRekeningschema on (RksGid = RekSaldoRksGid and (DefaultSoort = 5 or (DefaultSoort = 3 and AfdrukZijde = 1)))
                    ) on (RekSaldoPerGid = PerGid)
  where              PerBjGid = @BjGid
  group by           PerNr;

  //Kosten
  insert into tmpWV(PerNr, Soort, Bedrag)
  select            PerNr,
                    _U('Kosten'),
                    sum(IsNull((if RekSaldoValNummer = @@BasisValutaNummer then
                                 (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief) - (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief)
                                else
                                  ValutaOmrekenen(RekSaldoValNummer, (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief) - (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                                endif), 0))
  from               tabPeriode
  left outer join   (tabRekeningsaldo
                     inner join tabRekeningschema on (RksGid = RekSaldoRksGid and (DefaultSoort = 4 or (DefaultSoort = 3 and AfdrukZijde = 0)))
                    ) on (RekSaldoPerGid = PerGid)
  where              PerBjGid = @BjGid
  group by           PerNr;

  //Resultatenrekeningen met als afdrukzijde 'afhankelijk van saldo'
  insert into tmpWV(PerNr, Soort, Bedrag)
  select            PerNr,
                    _U('Resultaat'),
                    sum(IsNull((if RekSaldoValNummer = @@BasisValutaNummer then
                                 (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief) - (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief)
                                else
                                  ValutaOmrekenen(RekSaldoValNummer, (SaldoDebetValutaVoorlopig + SaldoDebetValutaDefinitief) - (SaldoCreditValutaVoorlopig + SaldoCreditValutaDefinitief), @@BasisValutaNummer, @BjGid, @PerNr, 2)
                                endif), 0)) as Bedrag
  from               tabPeriode
  left outer join   (tabRekeningsaldo
                     inner join tabRekeningschema on (RksGid = RekSaldoRksGid and (DefaultSoort = 3 and AfdrukZijde = 2))
                    ) on (RekSaldoPerGid = PerGid)
  where              PerBjGid = @BjGid
  group by           PerNr, RksGid;

  //Afhankelijk van een positief of negatief bedrag bepalen welk Soort het is en het bedrag eventueel positief maken
  update tmpWV
  set    Bedrag = abs(Bedrag),
         Soort  = if Bedrag >= 0 then _U('Kosten') else _U('Opbrengsten') endif
  where  Soort = _U('Resultaat');

  //Nu kunnen we het definitieve resultaat bepalen
  insert into tmpWV(PerNr, Soort, Bedrag)
  select   PerNr, _U('Resultaat'), sum(if Soort = _U('Opbrengsten') then Bedrag else 0 endif) - sum(if Soort = _U('Kosten') then Bedrag else 0 endif)
  from     tmpWV
  group by PerNr;

  select   Soort, PerNr, sum(Bedrag)
  from     tmpWV
  group by Soort, PerNr
  order by Soort, PerNr;
end;


create or replace procedure CreateAndGrantRightsOnProcedure(in @ProcNaam nchar(255))
begin
  call CreateRightsOnProcedure(@ProcNaam);
  call RefreshAllUserRights();
end;


create or replace procedure CreateRightsOnProcedure(in @ProcNaam nchar(255))
begin
  declare @PrcGid integer;
  select PrcGid into @PrcGid from tabProcedure where prcNaam = @ProcNaam;

  if @PrcGid is null then
    insert into tabProcedure(prcNaam, prcExecODBC)
    values(@ProcNaam, 1);
  else
    update tabProcedure
    set    prcExecODBC = 1
    where  PrcGid = @PrcGid;
  end if;
end;


create or replace procedure CreateUserExtern(in @User nchar(40), in @Password nchar(40))
begin
  declare @ModuleCodes long nvarchar;

  set @@ErrorTextProcedure = 'CreateUserExtern > ';
  //call TraceBegin(@@ErrorTextProcedure + '@User = ' + @User +', @Password = ' + @Password);

  // *************************************
  // *** Huidige gebruiker verwijderen ***
  // *************************************
  call DeleteUserExtern(@User);

  // **************************************
  // *** Login voor gebruiker toevoegen ***
  // **************************************
  execute immediate 'grant connect to "' || @User || '" identified by "' || @Password || '"';
  execute immediate 'comment on user "' || @User || '" is "Externe user #218123"';  //Nummer staat er allee bij om commentaar te kunnen herkennen om gebruiker weg te kunnen gooien

  // ***************************
  // *** Gebruiker onthouden ***
  // ***************************
  // RVL 19-05-2016: Externe gebruiker op slaan in de database, maar wel met ecrypt wachtwoord
  insert into tabUserExtern(ueName, ueWachtwoord, ueCreatedDate) select @User, EncWachtwoord, now() from WachtwoordEncrypt(@Password);

  // ****************************************
  // *** Leesrechten op tabellen uitdelen ***
  // ****************************************
  for @Cursor AS CURSOR_object1 CURSOR FOR
    select table_name @table from systable inner join sysuserperm on (User_Id = Creator and User_name = 'KingSystem') where table_type in ('base', 'gbl temp', 'view')
  for read only
  do
    set @@ErrorTextProcedure = 'CreateUserExtern -> Leesrechten op ' + @table + ' geven';
    //call trace(@@ErrorTextProcedure);
    execute immediate 'grant select on KingSystem.' || @table || ' to "' || @User ||'"'
  end for;

  // ****************************************
  // *** Leesrechten op tabellen ontnemen ***
  // ****************************************
  //Tabellen en definities zijn wel zichtbaar, maar eventuele data is onzichtbaar. De tabel onzchtbaar maken, dat gaat helaas niet.
  //m8 = Maatwerk Quadrant
  if IsModuleActive('m8') = 0 then
    set @@ErrorTextProcedure = 'CreateUserExtern -> Leesrechten ontnemen op bepaalde tabellen';
    //call trace(@@ErrorTextProcedure);
    for @Cursor AS CURSOR_RevokeTables CURSOR FOR
      select table_name @table_name
      from systable
           inner join sysusers on (uid = creator and name = 'KingSystem')
      where table_name in ('tabLicentie',
                           'tabLicentieChecksum',
                           'tabLicentieChecksumOptiesCommercieel',
                           'tabLicentieOptiesCommercieel',
                           'tabLicMask',
                           'tabLogLicentie',
                           'tabModule',
                           'tabOptiesCommercieel',
                           'tabProcedure',
                           'tabUserExtern',
                           'tabWebserviceVasteGegevens'
                          )
    for read only
    do
      execute immediate 'revoke all on KingSystem.' || @table_name || ' from "' || @User || '"' ;
    end for;
  end if;

  // ***************************************************************
  // *** Rechten op (door ODBC) uitvoerbare procedures toekennen ***
  // ***************************************************************

  // +++ Uitzonderingsprocedures opvoeren +++
  for @Cursor AS CURSOR_StoredProcsFromTable CURSOR FOR
    select prcNaam @Naam
    from   tabProcedure
           inner join sysProcedure on Proc_Name = substring(prcNaam, greater(0,locate(prcNaam, '.') + 1))
           inner join sysUserperm on (
             User_Id = Creator and
             User_name =
               if locate(prcNaam, '.') < 1
                 then 'KingSystem'
                 else substring(prcNaam, 1, locate(prcNaam, '.') - 1)
               endif
           )

    where PrcExecODBC = 1
  for read only
  do
    execute immediate 'grant execute on ' || @Naam  || ' to "' || @User || '"'
  end for;

  // +++ KTC-procedures opvoeren +++
  for @Cursor AS CURSOR_StoredProcs CURSOR FOR
    select Proc_Name @Proc from sysProcedure inner join sysUserperm on (User_Id = Creator and User_name = 'KingSystem' and Proc_Name like 'KTC[_]%')
  for read only
  do
    execute immediate 'grant execute on ' || @Proc || ' to "' || @User || '"'
  end for;

  set @@ErrorTextProcedure = 'CreateUserExtern';
  //call TraceEind(@@ErrorTextProcedure);
end;

alter procedure CreateUserExtern set hidden;


create or replace procedure DeleteUserExtern(in @User nchar(40))
begin
  set @@ErrorTextProcedure = 'DeleteUserExtern > ';
  //call TraceBegin(@@ErrorTextProcedure);

  if @User = '' then
    select first ueName into @User from tabUserExtern;
  end if;

  if exists(select 1 from sysuserperm where User_Name = @User) then
    execute immediate 'revoke connect from "' || @User ||'"';
  end if;

  // ACW 24-11-2005: ook uit de nieuwe tabel verwijderen
  // TG  15-09-2006: de userperms moeten éérst gezet worden, daarna mag de user pas gedelete worden. Soms lukt het revoken nl. niet (zie bug #21162)
  delete tabUserExtern where ueName = @User;

  set @@ErrorTextProcedure = 'DeleteUserExtern';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure GrantProcedureRightsToUser(
  in @Username          nchar(80),
  in @StoredProcMask    nchar(200), // Use single name, regular LIKE expression or comma separated
  in @StoredProcRights  nchar(200))
begin
  // Rights on stored procs
  if @StoredProcRights <> '' then
    //No name? then everything!
    if @StoredProcMask = '' then
      set @StoredProcMask = '%'
    end if;

    // Separate each comma delimited
    for @masks as CURSOR_Masks CURSOR for
      SELECT @mask
        FROM OPENSTRING( VALUE @StoredProcMask)
        WITH (@mask VARCHAR(100)) OPTION ( ROW DELIMITED BY ',' delimited by '') AS dummy
    for read only
    do

      for @Cursor AS CURSOR_StoredProcs CURSOR FOR
        // KingSystem laten staan, want de procedures zijn onder die user (group) aangemaakt!
        select Proc_Name @Proc
        from   sysProcedure
               inner join sysUserperm on (User_Id = Creator and User_name = 'KingSystem')
        where  @Proc like @mask
      for read only
      do
        execute immediate with batch off with result set off 'grant ' + @StoredProcRights + ' on ' || @Proc || ' to ' + @Username;
      end for;
    end for;
  end if;
end;

alter procedure GrantProcedureRightsToUser set hidden;


create or replace procedure GrantRightsToUser(
  in @Username          nchar(80),
  in @Passw             nchar(80),
  in @MemberOf          nchar(80),
  in @RevokeRights      nchar(80),
  in @GrantRights       nchar(80),
  in @TableRights       nchar(200),
  in @StoredProcRights  nchar(200))
begin
  execute immediate with batch off with result set off 'grant connect to ' + @Username + ' identified by "' + @Passw + '"';

  // Make member of group
  if @MemberOf <> '' then
    if not exists(select 1 from sysgroup inner join sysuserperm on (user_id = group_member and user_name = @Username)
              where group_id = (select a.User_Id from sysuserperm a where a.user_name = @MemberOf)) then
      execute immediate with batch off with result set off 'grant membership in group ' || @MemberOf || ' to ' + @Username;
    end if;
  end if;

  // Grant extra rights
  if @GrantRights <> '' then
    execute immediate with batch off with result set off 'grant ' + @GrantRights + ' to ' + @Username;
  end if;

  // Revoke extra rights
  if @RevokeRights <> '' then
    execute immediate with batch off with result set off 'revoke ' + @RevokeRights + ' from ' + @Username;
  end if;

  // Rights on all tables
  if @TableRights <> '' then
    for @Cursor AS CURSOR_Tables CURSOR FOR
      // KingSystem laten staan, want de tabellen zijn onder die user (group) aangemaakt!
      select Table_name @Table from sysTable inner join sysUserperm on (User_Id = Creator and User_name = 'KingSystem') where table_type in ('base', 'gbl temp', 'view')
    for read only
    do
      execute immediate with batch off with result set off 'grant ' + @TableRights + ' on ' || @Table || ' to ' + @Username;
    end for;
  end if;

  // Rights on stored procs
  if @StoredProcRights <> '' then
    call GrantProcedureRightsToUser(@Username, '' /*@StoredProcMask*/, @StoredProcRights)
  end if;
end;

alter procedure GrantRightsToUser set hidden;


create or replace procedure ReCreateUsersExtern()
begin
  declare @DecryptWachtwoord nchar(20);

  set @@ErrorTextProcedure = 'ReCreateUsersExtern > ';
  //call TraceBegin(@@ErrorTextProcedure);
  if @@Gebruikercode <> 'KingGatewayDba' then
    for @Cursor AS CURSOR_object CURSOR FOR
      select user_name @user from sysuserperm where remarks = 'Externe user #218123'
    for read only
    do
      set @DecryptWachtwoord = null;
      select (select Wachtwoord from WachtwoordDecrypt2(UeWachtwoord)) into @DecryptWachtwoord from tabUserExtern where ueName = @User;

      call DeleteUserExtern(@user);
      if (@DecryptWachtwoord is not null) and (CharIndex('y1',@@ModuleCodes)) > 0 then
        call CreateUserExtern(@User, @DecryptWachtwoord);
      end if;
    end for;
  end if;

  set @@ErrorTextProcedure = 'ReCreateUsersExtern';
  //call TraceEind(@@ErrorTextProcedure);
end;

alter procedure ReCreateUsersExtern set hidden;


create or replace procedure RefreshAllUserRights()
begin
  // Alle gebruikers (zoals KingSystem, KingMobile, KingGatewayUser) de juiste rechten geven
  call WachtwoordWijzigen();

  // Alle ODBC-gebruikers opnieuw instellen
  call ReCreateUsersExtern();

end;


create or replace procedure WachtwoordWijzigen( in @UserId nchar(20) default null)
begin
  // ADMIN-variant
  // Bij wijzigen graag wiki pagina aanpassen: http://intranet.quadrant.local/wiki/index.php?title=Userconnecties_aan_database
  // Bij toekennen van nieuwe wachtwoorden:
  // - geen single/double quotes,
  // - geen blokhaken
  // - geen spatie op het einde,
  // - geen semicolons,
  // - geen procent teken,
  // - geen escape karakters,
  // - geen ampersand (&)
  // dus alleen: a-z, A-Z, 0-9,?!@#$*_-.,:;

  // This part is equal to QSYSTEEM! Validate that these are equal!!
  declare @PW_KingSystem      nchar(20) = '1fwmAU@@40fwF8hZ8WN7';
  declare @PW_KingGatewayDba  nchar(20) = '1!22!Ed2sElMvZBm@iq7';
  declare @PW_KingGatewayUser nchar(20) = '1jH4fky4d!n4M6Bk4ed7';
  declare @PW_KingWebservice  nchar(20) = '1pki4JN@7QgFh4pYVZ&7';
  // DO NOT CHANGE
  declare @QPW_KingSystem     nchar(20) = 'J$RQ@*FA5C-F9BP7QA+V';
  declare @PW_KINGINFO        nchar(20) = '#DrinkYour1st7UpB48!';

  set @@ErrorTextProcedure = 'WachtwoordWijzigen';
  //call TraceBegin(@@ErrorTextProcedure);

  // Rights: lege string betekent GEEN wijziging van de rechten
  //                                                                                    Username           Password             Member of group   Revoke rights   Grand rights        Table rights                      StoredProc rights
  if isnull(@UserId, 'KingSystem'     ) = 'KingSystem'      then call GrantRightsToUser('KingSystem',      @PW_KingSystem     , '',               '',             'DROP CONNECTION',  '',                               '') end if;
  if isnull(@UserId, 'KingGatewayDba' ) = 'KingGatewayDba'  then call GrantRightsToUser('KingGatewayDba',  @PW_KingGatewayDba , 'KingSystem',     '',             'DBA, resource',    '',                               '') end if;
  if isnull(@UserId, 'KingGatewayUser') = 'KingGatewayUser' then call GrantRightsToUser('KingGatewayUser', @PW_KingGatewayUser, 'KingSystem',     'DBA',          '',                 'select, insert, update, delete', 'execute')end if;
  if isnull(@UserId, 'KingWebservice' ) = 'KingWebservice'  then call GrantRightsToUser('KingWebservice',  @PW_KingWebservice , 'KingSystem',     'DBA',          '',                 'select, insert, update, delete', 'execute')end if;

  // Deze gebruikers worden NIET aangepast!
  if isnull(@UserId, 'KingKad'   ) = 'KingKad'    then call GrantRightsToUser('KingKad',         'fedDxAGAjnQmK#rN!t3g', 'KingSystem',     'DBA',          '',                 '',                               '') end if;
  if isnull(@UserId, 'KingMobile') = 'KingMobile' then call GrantRightsToUser('KingMobile',      's929uAPvmJjR&EVG!u6e', 'KingSystem',     '',             '',                 'select, insert, update, delete', 'execute') end if;
  if isnull(@UserId, 'KingBackup') = 'KingBackup' then
    call GrantRightsToUser('KingBackup',      'KingBackup',           '',               'DBA',          'backup, validate', '',                               '') ;
    // Vanaf ASA 16 is er een wijziging in de rechten. Dit is nodig zodat transaction log kan worden verwijderd/opnieuw gemaakt
    if exists(select first 1 from syshistory where operation in ('INIT', 'UPGRADE') and Version >= '16') then
      GRANT MANAGE ANY DBSPACE TO KingBackup;
    end if;
  end if;


  if exists(select first 1 from sys.sysprocedure inner join SYS.SYSUSER on user_id = creator where proc_name='king_info' and user_name='KingInfo') then
    grant execute on KingInfo.King_Info     to KingSystem;
  end if;


  //LET OP! DEZE GEBRUIKER WORDT OOK AL MET KING_INFO.SP TOEGEVOEGD. HIER WORDEN DE RECHTEN VERDER TOEGEKEND
  if isnull(@UserId, 'KingInfo') = 'KingInfo' then
    call GrantRightsToUser('KingInfo',        '#DrinkYour1st7UpB48!', '',               'DBA, resource','',                 '',                               '');

    // Speciaal setje voor de KingInfo, dis is namelijk GEEN public, maar heeft toch iets nodig om met de database aan de slag te kunnen
    if exists(select first 1 from syshistory where operation in ('INIT', 'UPGRADE') and Version >= '17') then
      revoke role public from kinginfo;
      grant select on syshistory to kinginfo;
      grant select on sysuserperms to kinginfo;
      grant select on sysprocedure to kinginfo;
      grant select on sysuser to kinginfo;
      grant select on systab to kinginfo;
      grant select on systabcol to kinginfo;
      grant select on sysoption to kinginfo;
      grant select on sysprocparm to kinginfo;
      grant select on sysarticle to kinginfo;
      grant execute on sa_db_list to kinginfo;
    end if;

    if exists(select first 1 from sys.sysprocedure inner join SYS.SYSUSER on user_id = creator where proc_name='king_info' and user_name='KingInfo') then
      grant execute on KingInfo.King_Info     to KingInfo;
    end if;

    if exists(select first 1 from sys.sysprocedure inner join SYS.SYSUSER on user_id = creator where proc_name='DatabaseInit' and user_name='KingSystem') then
      grant execute on DatabaseInit  to KingInfo;
    end if;

    if exists(select first 1 from sys.systable inner join SYS.SYSUSER on user_id = creator where table_name='tabregistry' and user_name='KingSystem') then
      grant select on tabregistry to kinginfo;
    end if;

    if exists(select first 1 from sys.systable inner join SYS.SYSUSER on user_id = creator where table_name='qdtabversion' and user_name='KingSystem') then
      grant select on qdtabversion to kinginfo;
    end if;

    if exists(select first 1 from sys.systable where table_name='dummy') then
      grant select on dummy to kinginfo;
    end if;
  end if;

  set @@ErrorTextProcedure = 'WachtwoordWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;

alter procedure WachtwoordWijzigen set hidden;


create or replace procedure InkoopFactuurVerwerkenInInkoopStatistieken(in @IfkGid integer,
                                                                       in @BoekDatum date)
//MR 28-mei-2018: Deze sp verwerkt de inkoopfactuur in de inkoopdata
//Aanleiding: Bij het verwerken van de inkoopfacturen moet de verwerkte data gelijk in de tabel TabInkoopdata komen.
//call InkoopFactuurVerwerkenInInkoopStatistieken(1,'2018-05-30');
begin
  //Zet de Inkoopdata in de tabel tbv inkoopstatistieken vanuit de inkoopfacturen;
  declare @BjGid                    integer;
  declare @Pernr                    integer;

  //call TraceBegin('InkoopFactuurVerwerkenInInkoopStatistieken > ' + '@IfkGid = ' + string(@IfkGid)+', @BoekDatum = ' + string(@BoekDatum));

  call BepaalBoekjaarEnPeriode(@BoekDatum, @BjGid, @PerNr);

  insert into tabInkoopData
  (
    IndAantal,
    IndArtGid,
    IndArtSoort,
    IndDatum,
    IndNawGid,
    IndOpbrGrpGId,
    IndValNummer,
    IndBedragInFactuurValuta,
    IndBedragInBasisValuta
   )
  select
          (IfrAantal * IfrVoorraadeenhedenInInkoopeenheid)                                @Aantal,    //Altijd in voorraadeenheden. Dus * de inkoopeenheden doen.
          ArtGid                                                                          @ArtGid,
          ArtSoort                                                                        @ArtSoort,
          @BoekDatum,
          IfkNawGid                                                                       @NawGid,
          ArtOpbrGrpGId                                                                   @OpbrGrpGid,
          IfkValNummer                                                                    @ValNummer,
          IfrRegeltotaalExclBtw                                                           @Omzet,
          if (IfkValNummer <> @@BasisValutaNummer) then
            ValutaOmrekenen(IfkValNummer, @Omzet, @@BasisValutaNummer, @BjGid, @Pernr, 2)
          else
            @Omzet
          endif                                                                           @OmzetInBasisValuta
    from   tabInkoopfactuurKop
           inner join tabInkoopfactuurRegel on (IfrIfkGid = IfkGid)
           inner join tabArtikel      on (ArtGid = IfrArtGid)
    where IfkGid = @IfkGid
    and   IfrRegelSoort in (1,2)                   // Artikelregels en tariefregels meenemen.
    and   @Aantal <> 0                             //In ieder geval moet het aantal van de regel ongelijk aan 0 zijn

  //call TraceEind('InkoopFactuurVerwerkenInInkoopStatistieken');
end;

