//MR 05-mei-2022 Incident: 16138 en 16142
//Repareren van de waardes in de voorraadeenheid van artikelen waarbij de verkoopprijs in het artikel anders is dan in de tabverkoopeenheid
//call Repareer_ArtikelenMetAndereVerkoopprijsInVkeRecord();
create or replace procedure Repareer_ArtikelenMetAndereVerkoopprijsInVkeRecord()
begin atomic
  update tabVerkoopEenheid
  set     VkeVerkoopEenheid                         = ArtOmsEenheid,
          VkeIsVerkoopprijsInclusiefBTW             = ArtVerkprijsIsIncl,
          VkeIsAdviesprijsInclusiefBTW              = ArtIsAdviesPrijsInclBtw,
          VkeAantalVoorraadEenhedenInVerkoopEenheid = 1,
          VkeAantalDecimalen                        = ArtAantDecAantallen,
          VkeAdviesprijs                            = ArtAdviesPrijs,
          VkeGewichtPer                             = ArtGewichtPer,
          VkeGewicht                                = ArtGewicht,
          VkeVolumePer                              = ArtVolumePer,
          VkeVolume                                 = ArtVolume,
          VkeVerkoopprijs                           = ArtVerkprijs,
          VkeAbcIndeling                            = ArtAbcIndeling,
          VkeDimensieLengte                         = ArtDimensieLengte,
          VkeDimensieBreedte                        = ArtDimensieBreedte,
          VkeDimensieHoogte                         = ArtDimensieHoogte
  from tabartikel
  inner join vwControleer_ArtikelenMetAndereVerkoopprijsInVkeRecord on vwArtGid = ArtGid
  where VkeArtGid = ArtGid
    and VkeIsVoorraadEenheid = 1;
end;

//MR 05-mei-2022 Incident 16142
//Verwijderen van de prijsafspraken waarbij de prijsafspraak van een verkoopeenheid is waar de voorraadeenheid is ingevuld
//call Repareer_Verwijder_PrijsafsprakenVerkoopEenheidopVoorraadeenheid();
create or replace procedure Repareer_Verwijder_PrijsafsprakenVerkoopEenheidopVoorraadeenheid()
begin atomic
  delete
  from tabprijsafspraak
  where pragid in (select vwPraGid from vwControleer_PrijsafsprakenVerkoopEenheidopVoorraadeenheid);
end;

//MR 13-mei-2022 Incident 16147: Verwijder de dubbele voorraadeenheden
//Verwijdert alle behalve 1 van de dubbele of meerdere voorraadeenheden.
//call Repareer_ArtikelDubbeleVerkoopEenheid();
create or replace procedure Repareer_ArtikelDubbeleVerkoopEenheid()
begin atomic
  delete from tabVerkoopEenheid vkeBase
  where vkeBase.vkeartgid in (SELECT vkpe.VkeArtGid
                              FROM tabVerkoopEenheid vkpe
                              WHERE  vkpe.VkeIsVoorraadEenheid = 1
                              GROUP BY vkpe.VkeArtGid
                              having count(*) > 1)
  and vkeBase.vkegid <> (select first vke2.vkegid
                      from tabVerkoopEenheid vke2
                      where vke2.vkeartgid = vkeBase.VkeartGid
                      order by vkelastmodified desc)
  and vkeBase.VkeIsVoorraadEenheid = 1;
end;

create or replace procedure Repareer_BestelRegelDetail()
begin atomic
  //Neem de aantallen vanuit de bestelregel naar de detailregel over, waarvoor geldt dat er maar 1 detailregel per bestelregel is
  update tabBestelRegelDetail
  set    brdAantalNogTeOntvangen = BstRglAantalNogTeOntvangenInVoorrEenh,
         brdAantalOntvangen      = BstRglAantalOntvangenInVoorrEenh
  from   tabBestelRegel
  where  brdBstRglGid = BstRglGid
         and BstRglGid in (select a.brdBstRglGid from tabBestelRegelDetail a group by a.brdBstRglGid having count(1) = 1)
         and (brdAantalNogTeOntvangen <> BstRglAantalNogTeOntvangenInVoorrEenh or brdAantalOntvangen <> BstRglAantalOntvangenInVoorrEenh)
         and BstRglSoort = 2
         and BrdSoort = 0;
end;
//call Repareer_BestelRegelDetail();

create or replace procedure Repareer_MeerdereBestelRegelDetails()
begin atomic
  // Voor alle detailregels het Nog te ontvangen op 0 zetten als voor die detailregel geldt.
  // Dit werkt dus voor de bestelregels met mÃ©Ã©r dan 1 detailregel
  // - Het betreft een artikelregel
  // - Nog te ontvangen van de bestelregel is 0 (dus volledig ontvangen)
  // - Totaal van Nog te ontvangen van de detailregels wijkt af van het Nog te ontvangen van de regel
  // - Totaal van Aantal besteld van de detailregels is gelijk aan het aantal besteld van de bestelregel
  //Reden: Alleen omdat de regel volledig is ontvangen, kunnen we de detailregels van die regel ook als volledig ontvangen beschouwen
  update tabBestelRegelDetail Det_buiten
  set    brdAantalNogTeOntvangen = 0
  where  brdBstRglGid in
         (select BstRglGid
          from tabBestelRegel
               inner join tabBestelRegelDetail Det_binnen on Det_binnen.brdBstRglGid=BstRglGid
          where BstRglAantalNogTeOntvangenInVoorrEenh = 0
            and BstRglSoort = 2
          group by BstRglGid, BstRglAantalNogTeOntvangenInVoorrEenh, BstRglAantalBesteld
          having sum(brdAantalNogTeOntvangen) <> BstRglAantalNogTeOntvangenInVoorrEenh
             and sum(brdAantalBesteld) = BstRglAantalBesteld
         );
end;
//call Repareer_BestelRegelDetail();

