create or replace procedure Repareer_NawGidCorrespondentieVanAndereNawGid()
//MR 07-02-2019 Incident I13269:
//Deze stored procedure repareert het veld NawGidCorrespondentie. Als deze niet van de NAW is zal deze gelijk gesteld worden aan het vestigingsadres
//Requirement: adrnawgid hoort gelijk te zijn aan de nawgid.
//Haal een verzendadres op. Is dat er 1, zet deze dan gelijk aan dit adres.
//De view toont records waarbij dat niet het geval is.
begin atomic
  set temporary option fire_triggers = 'off';

  //Eerst alle adressen corrigeren van de juistenaws
  update tabnaw
  set NawGidCorrespondentie = NawGidVestiging
  from vwControleer_NawGidCorrespondentieVanAndereNawGid
  inner join tabadres Corr  on Corr.adrGid = AdresGid
  inner join tabadres Vest  on Vest.adrNawGid = JuisteNawGid and Vest.adrOms = 'Vestigingsadres'
  where nawgid = JuisteNawGid
  and  Corr.AdrPostcodeHuisnr <> Vest.AdrPostcodeHuisnr;

  update tabnaw
  set NawGidCorrespondentie = NawGidVestiging
  from vwControleer_NawGidCorrespondentieVanAndereNawGid
  where nawgid = FoutieveNawGid;

  set temporary option fire_triggers = 'on';
end;

//call Repareer_NawGidCorrespondentieVanAndereNawGid();


create or replace procedure Repareer_PosBonnenZonderRegelsOuderDan3Maanden()
begin atomic
  //Bonnen die geen regels hebben en egeen betalingen verwijderen
  delete from tabPosKop
  where PokDatumTijd <= DateAdd( month, -3, Now())
    and (Select Count(porpokgid) from tabPosRegel Where porpokgid = pokgid) = 0
    and ((Select Count(PoaPokGid) from tabPosAfrekening Where PoaPokGid = pokgid)) = 0;
end;
