create or replace procedure Repareer_PosGepindZonderBedragBetaaldMetFoutInEJournaal()
begin atomic
  //Bonnen die op gepint staan maar een pinbetaling van 0 hebben met een foutmelding op niet gepind plaatsen
  Update tabPosKop
  set PokBonIsGePind = 0
  where PokGid in (select PokGid from vwControleer_PosGepindZonderBedragBetaaldMetFoutInEJournaal);

  //de pinbetalingen van 0 met een foutmelding in E-journal verwijderen
  delete from tabPosAfrekening
  from tabPosBetaalwijzen
  where pobwnummer = PoaPobwNummer
  and PobwGebruikPin = 1
  and PoaBedragBetaald = 0
  and (PoaPinEJournal like '%<TransactionResultText>NIET GECREDITEERD</TransactionResultText>%'
     or PoaPinEJournal like '%<TransactionResultText>GESTOPT KAARTHOUDER</TransactionResultText>%'
     or PoaPinEJournal like '%<TransactionResultText>TE LANG GEWACHT</TransactionResultText>%'
     or PoaPinEJournal like '%<TransactionResultText>TRANSACTIE GEWEIGERD</TransactionResultText>%'
     or PoaPinEJournal like '%<TransactionResultText>NIET AKKOORD CODE%');
end;
//call Repareer_PosGepindZonderBedragBetaaldMetFoutInEJournaal();


