begin atomic
  //Bonnen die op gepint staan maar een pinbetaling van 0 hebben met een foutmelding op niet gepind plaatsen
  Update tabPosKop
  set PokBonIsGePind = 0
  where PokGid in (select PokGid from vwControleer_PosGepindZonderBedragBetaaldZonderEJournaal);

  //de pinbetalingen van 0 zonder E-journal verwijderen
  delete from tabPosAfrekening
