create or replace procedure LockRelease(in @LockSoort smallint, in @TableName nchar(40), in @PrimKey nchar(80))
begin

  set @@ErrorTextProcedure = 'Begin LockRelease > @LockSoort='+string(@LockSoort)+', @TableName='+@TableName+', @Primkey='+@Primkey+', @@SpId='+string(@@SpId);
  //call Trace(@@ErrorTextProcedure);

  call LockReleaseOnId(@@Spid, @@LoginTime, @LockSoort, @TableName, @PrimKey);

  set @@ErrorTextProcedure = 'Einde LockRelease';
  //call Trace(@@ErrorTextProcedure);

end;


create or replace procedure LockReleaseOnId(in @ConnId integer, in @LoginTime datetime, in @LockSoort smallint, in @TableName nchar(40), in @PrimKey nchar(80))
// Als @ConnId EN @LoginTime NULL zijn, dan automatisch vullen met de huidige login
begin
  //declare @IsolationLevel smallint;

  set @@ErrorTextProcedure = 'LockReleaseOnId > ';
  //call TraceBegin(@@ErrorTextProcedure + '@ConnId = ' + string(@ConnId) + ', @LockSoort = ' + string(@LockSoort) + ', @TableName = ' + @TableName + ', @PrimKey = ' + @PrimKey);

  // Isolation level op 0 forceren
  //set @IsolationLevel = @@Isolation;
  //if @@Isolation > 0 and @@Isolation < 4 then // ACW 4=snapshot, dan dus niet locken!
  //  set temporary option Isolation_Level = 0;
  //end if;

  // ACW 18-07-2013 n.a.v. vervallen LockSet: Indien parameters NIET ingevuld, dan gebruiken we de huidige connectie
  if @ConnId is null and @LoginTime is null then
    set @LoginTime = @@LoginTime;
    set @ConnId    = @@Spid;
  end if;

  //Gooi maximaal 1 lock weg, omdat bij er anders bij een readlock in 1 keer alle betreffende readlocks weg worden gegooid
  delete first qtabLock where (qLockConnection=@ConnId) and (qLockLoginTime=@LoginTime) and (qLockSoort=@LockSoort) and (qLockTableName=@TableName) and (qLockPKey=@PrimKey) order by qLockGid OPTION (Isolation_level=0);

  // Herstellen isolation level
  //if @IsolationLevel <> 0 and @@Isolation < 4 then // ACW 4=snapshot, dan dus niet locken!
  //  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;
  //end if;

  set @@ErrorTextProcedure = 'LockReleaseOnId';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure LockReleaseOnUserName(
  in @UserName nchar(40),
  in @LockSoort smallint,
  in @TableName nchar(40),
  in @PrimKey nchar(80)
)
//Let op : Deze stored proc is in eerste instantie bedoeld, om locks te verwijderen door KingMobile.
//         Deze procedure werkt dus niet op connection id en ook niet op login datum en tijd.
//         Voor de standaard King-programmatuur zal deze NIET gebruikt moeten worden.
begin

  set @@ErrorTextProcedure = 'Begin LockReleaseOnUserName > @UserName='+string(@UserName)+', @LockSoort='+string(@LockSoort)+', @TableName='+@TableName+', @Primkey='+@Primkey;
  //call Trace(@@ErrorTextProcedure);

  delete first qtabLock
  where (qLockUser = @UserName) and (qLockSoort = @LockSoort) and (qLockTableName = @TableName or @TableName = '') and (qLockPkey = @PrimKey or @PrimKey = '')
  order by qlockGid
  OPTION(Isolation_level=0);


  set @@ErrorTextProcedure = 'Einde LockReleaseOnUserName';
  //call Trace(@@ErrorTextProcedure);

end;


//------ VERVALLEN; ZIE LockSetOnId

create or replace procedure LockSet(in @LockSoort smallint, in @TableName nchar(40), in @PrimKey nchar(80), inout @Result smallint)
begin

  set @@ErrorTextProcedure = 'Begin LockSet > @LockSoort='+string(@LockSoort)+', @TableName='+@TableName+', @Primkey='+@Primkey+', @@SpId='+string(@@SpId)+', @LoginTime='+string(@@LoginTime);
  //call Trace(@@ErrorTextProcedure);

  call LockSetOnId(@@SpId, @@LoginTime, @LockSoort, @TableName, @PrimKey, @Result);

  set @@ErrorTextProcedure = 'Einde LockSet > @Result='+string(@Result);
  //call Trace(@@ErrorTextProcedure);
end;


create or replace procedure LockSetOnId(
  in @ConnId integer,
  in @LoginTime datetime,
  in @LockSoort smallint, // 0 = readlock/shared lock,
                          // 1 = writelock/exclusive lock,
                          // 2 = non-exclusive writelock
                          //     - Will be added to the table as a regular write lock, so to remove, use @LockSoort=1
                          //     - Other write locks are permitted during setting of this lock,
                          //       however, other read locks are not permitted!
  in @TableName nchar(40),
  in @PrimKey nchar(80),
  inout @Result smallint,
  in @AutomatischOpruimen smallint default 1,
  in @LockUser nchar(40) default @@GebruikerCode
)
// Als @ConnId EN @LoginTime NULL zijn, dan automatisch vullen met de huidige login
begin

  //declare @IsolationLevel smallint; Hoeft niet meer met een OPTION in de queries
  declare @aantal integer;

  set @@ErrorTextProcedure = 'LockSetOnId > ';
  //call TraceBegin(@@ErrorTextProcedure + '@ConnId = ' + string(@ConnId) + ', @LockSoort = ' + string(@LockSoort) + ', @TableName = ' + @TableName + ', @PrimKey = ' + @PrimKey);

  //@LockSoort = 0 -> ReadLock, meerdere Readlocks kunnen worden gezet als er geen ExlusiveLock is gezet
  //@LockSoort = 1 -> ExclusiveLock, hier kan er maar 1 per LockString en in dat geval mogen er ook geen ReadLocks zijn
  //@LockSoort = 2 -> non-exclusive writelock, er mogen geen andere read-locks staan, maar andere write-locks mogen wel. Is bedoeld voor overnemen van een object naar een andere taak in de tijd.

  //@Result = 0 -> Lock is gelukt
  //@Result = 1 -> Lock is niet gelukt

  // Isolation level op 0 forceren
  //set @IsolationLevel = @@Isolation;
  //if @@Isolation > 0 and @@Isolation < 4 then // ACW 4=snapshot, dan dus niet locken!
  //  set temporary option Isolation_Level = 0;
  //end if;

  set @Result    = 1;    // Default niet gelukt

  // ACW 18-07-2013 n.a.v. vervallen LockSet: Indien parameters NIET ingevuld, dan gebruiken we de huidige connectie
  if @ConnId is null and @LoginTime is null then
    set @ConnId    = @@Spid;
    set @LoginTime = @@LoginTime;
  end if;

  savepoint;
  // Eerst de insert proberen
  insert into qtabLock(qLockConnection, qLockLoginTime, qLockUser, qLockSoort, qLockTableName, qLockPKey, qLockAutomatischOpruimen)
               values (@ConnId, @LoginTime, IsNull(@LockUser, @@GebruikerCode),
                if @LockSoort = 2 /*non-exclusive writelock*/ then 1 /*writelock*/ else @LockSoort endif,
                @TableName, @PrimKey, IsNull(@AutomatischOpruimen, 1))
  OPTION (Isolation_level=0); // Zo hoeven we de temporary option etc. niet te gebruiken!;

  // Testen of de lock wel mocht
  case @LockSoort
  when  0 then
    // read-lock? Test of er een writelock is
    select count(*) into @aantal from qtabLock where (qLockSoort = 1) and (qLockTableName = @TableName) and (qLockPKey = @PrimKey) OPTION (Isolation_level=0);
    if @aantal = 0 then
      set @result = 0; // Nee, GEEN writelock, dus result is ok!!
    end if;
  when  2 then
    // non-exclusive write-lock? Test of er andere readlocks locks staan
    select count(*) into @aantal from qtabLock where (qLockSoort = 0) and (qLockTableName = @TableName) and (qLockPKey = @PrimKey) OPTION (Isolation_level=0);
    if @aantal = 0 then
      set @result = 0; // Nee, geen readlocks, dus result is ok!!
    end if;
  else
    // write-lock? Test of er meer locks staan
    select count(*) into @aantal from qtabLock where (qLockTableName = @TableName) and (qLockPKey = @PrimKey) OPTION (Isolation_level=0);
    if @aantal = 1 then
      set @result = 0; // Nee, slechts 1 lock, dus dat moet deze lock zijn
    end if;
  end;

  // Als de lock niet mocht, dan deze weer verwijderen!
  if @result <> 0 then
    //bug #27628 Geen delete doen, omdat bij gelijktijdig factureren en leveren er een deadlock kan ontstaan
    rollback to savepoint;
  end if;

  // Herstellen isolation level
  //if @IsolationLevel <> 0 and @@Isolation < 4 then // ACW 4=snapshot, dan dus niet locken!
  //  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;
  //end if;

  set @@ErrorTextProcedure = 'LockSetOnId';
  //call TraceEind(@@ErrorTextProcedure + ' > @Result = ' + string(@Result));
end;


create or replace procedure LockSetOnIdandReleaseRedundantLocks(
  in  @ConnId         integer,
  in  @LoginTime      datetime,
	in 	@LockSoort 			smallint,
  in  @TableName      nchar(40),
  in  @PrimKey        nchar(80),
  out @LockIsGelukt   integer default 0)
begin
	declare @_LockResult smallint;
	declare @_ExclusiveLock smallint = 1 			/*Exclusive lock*/;
	declare @_AutomOpruimen smallint = 1 			/*Automatisch opruimen */;
	declare @_NietAutomOpruimen smallint = 0 	/*NIet automatisch opruimen */;
	declare @_LockID integer;
	//declare @_IsolationLevel smallint;


	LockLoop:
	loop
		call LockSetOnId(@ConnId, @LoginTime, @LockSoort, @Tablename, @PrimKey, @_LockResult, @_AutomOpruimen);
		if @_LockResult = 0 then
			// Lock is gelukt
			set @_LockID = @@identity;
			leave LockLoop;
		end if;
		// Isolation level op 0 forceren
		//set @_IsolationLevel = @@Isolation;
		//if @@Isolation > 0 then
		//	set temporary option Isolation_Level = 0;
		//end if;

		// Verwijder lock als deze ouder dan 5 minuten is en een niet-verwijderbare lock is
		delete qtabLock
		where (qLockTableName           = @Tablename)
			and (qLockPkey                = @PrimKey)
			and (qLockSoort               = @_ExclusiveLock)
			and (qLockAutomatischOpruimen = @_NietAutomOpruimen)
			and (DateAdd(minute, 5, qLockDateTime) < now())
		OPTION(Isolation_level=0);
		if @@rowcount = 0 then
			// Er zijn geen records verwijderd, dus lock zal niet lukken
			leave LockLoop;
		end if;

		// Isolation level terugzetten op oude waarde
		//if @_IsolationLevel <> 0 then
		//	execute immediate 'set temporary option Isolation_Level = ' || @_IsolationLevel;
		//end if;

		// Blijf proberen omdat er een lockrecord kon worden verwijderd
	end loop LockLoop;

	set @LockIsGelukt = 1 - @_LockResult;	// 1 = Gelukt (Succesvol), 0 = niet gelukt (niet succesvol)
	/* output
	select
		1 - @_LockResult,	// 1 = Gelukt (Succesvol), 0 = niet gelukt (niet succesvol)
		@_LockID;         // LockID, recordID van gelockte record
		*/
end;


create or replace function LocksOnRecord(
  in @TableName nchar(40),
  in @qLockPKey nchar(40),
  in @TestOpLockSoort smallint,
  in @IncludeMyOwnConnId smallint,
  in @ConnId integer
)
// Test of er op een bepaald record (@LockPkey) in een bepaalde tabel (@TableName) een lock staat.
// Je kan meegeven of hij moet testen op de soort lock (@TestOpLockSoort: 0 - Readlock, 1 - Exclusive, 2 - Allebei)
// en op de connection id (@IncludeMyOwnConnId: 0 - Negeer eigen locks, 1 - Ook eigen locks testen).
// @Connid is de 'eigen' id. (=@@SpId meestal)
returns smallint
begin
  declare @IsGelocked     smallint;

  set @@ErrorTextProcedure = 'Begin LocksOnRecord';
  //call Trace(@@ErrorTextProcedure);

  set @IsGelocked = 0;

  select first 1
  into   @IsGelocked
  from   qtabLock
  where (qLockTableName    = @TableName)
    and (qLockPkey         = @qLockPkey)
    and ((@TestOpLockSoort = qLockSoort) or (@TestOpLockSoort=2))
    and ((@Connid <> qLockConnection)    or (@IncludeMyOwnConnid=1))
  OPTION(Isolation_level=0);

  set @@ErrorTextProcedure = 'Einde LocksOnRecord > @IsGelocked='+string(@IsGelocked);
  //call Trace(@@ErrorTextProcedure);
  return(@IsGelocked);
end;


create or replace procedure LocksWithoutConnection(in @TabelNaam nchar(40))
begin
  declare @ConnId integer;
  declare local temporary table tmpConnection
   (ConnId integer null) on commit preserve rows;

  set @@ErrorTextProcedure = 'Begin LocksWithoutConnection > @TabelNaam='+@TabelNaam+', @@Spid='+string(@@SpId)+', @@LoginTime='+string(@@LoginTime);
  //call Trace(@@ErrorTextProcedure);

  set @ConnId=next_connection(null);
  while @ConnId is not null loop
    //Test op Db_id is niet nodig. De "Next_Connection" zonder 2e parameter geeft alleen connecties terug van de huidige database
    //if connection_property('DBNumber',@ConnId) = Db_Id() then
    insert into tmpConnection values(@ConnId);  //Zet alleen die id''s er in die deze database gebruiken
    //end if;
    set @ConnId=next_connection(@ConnId);
  end loop;

  set @@ErrorTextProcedure = 'Einde LocksWithoutConnection';
  //call Trace(@@ErrorTextProcedure);

  //Combinatie SpId + logintime is nodig, omdat bij iedere eerste keer database opstarten, zal hetzelfde id uitgedeeld worden
  select qlockGid, qLockConnection, qLockDateTime, qLockLoginTime, qlockPkey, qlockSoort, qLockTableName, qlockUser from qtabLock
  where (qLockAutomatischOpruimen = 1) and
        (@TabelNaam = left(qLockTableName, length(@TabelNaam)) and (((qLockConnection=@@SpId) and (@@LoginTime<>qLockLoginTime)) or
                                                                     (qLockConnection not in (select ConnId from tmpConnection))));
end;


create or replace function LocksWithoutConnectionExist()
returns smallint
begin
  declare @ConnId integer;
  declare local temporary table tmpConnection
   (ConnId integer null) on commit preserve rows;

  set @@ErrorTextProcedure = 'Begin LocksWithoutConnectionExist > @@Spid='+string(@@SpId)+', @@LoginTime='+string(@@LoginTime);
  //call Trace(@@ErrorTextProcedure);

  set @ConnId=next_connection(null);
  while @ConnId is not null loop
    //Test op Db_id is niet nodig. De "Next_Connection" zonder 2e parameter geeft alleen connecties terug van de huidige database
    //if connection_property('DBNumber',@ConnId) = Db_Id() then
    insert into tmpConnection values(@ConnId);  //Zet alleen die id''s er in die deze database gebruiken
    //end if;
    set @ConnId=next_connection(@ConnId);
  end loop;

  set @@ErrorTextProcedure = 'Einde LocksWithoutConnectionExist';
  //call Trace(@@ErrorTextProcedure);

  //Combinatie SpId + logintime is nodig, omdat bij iedere eerste keer database opstarten, zal hetzelfde id uitgedeeld worden
  //KingMobile buiten beschouwing laten omdat deze door Mobile wordt afgehandeld en deze locks kunnen laten staan ook als de connectie is verbroken
  if exists(select 1 from qtabLock where (qLockAutomatischOpruimen = 1) and (((qLockConnection=@@SpId) and (@@LoginTime<>qLockLoginTime)) or (qLockConnection not in (select ConnId from tmpConnection)))) then
    return 1
  else
    return 0
  end if;
end;

create or replace procedure LockWaitAndSetForUniqueLock
/* Deze routine maakt een write-semafoorlock o.b.v. opgegeven tabel en primary key.
   - Als de lock is gelukt, dan wordt @LockIsGelukt op 1 gezet.
   - Als @MaxWaitSeconds wordt meegegeven en deze is groter dan 0, dan wordt maximaal dat aantal seconden geprobeerd om de lock te zetten
     Als na deze tijd geen lock lukte, dan wordt @LockIsGelukt op 0 gezet.
   - De parameter @LockIsGelukt is optioneel, maar deze niet opgeven is zinloos als @MaxWaitSeconds > 0 wordt opgegeven, omdat je dan neit weet of de lock lukte.
*/
(
  in  @ConnId         integer,
  in  @LoginTime      datetime,
  in  @TableName      nchar(40),
  in  @PrimKey        nchar(80),
  in  @MaxWaitSeconds integer default -1, //0 of kleiner: Onbeperkt wachten!
  out @LockIsGelukt   integer default 0)
begin
  declare @LockRes smallint;

  if @MaxWaitSeconds = 0 then
    set @MaxWaitSeconds = -1;
  else
    set @MaxWaitSeconds = @MaxWaitSeconds * 2; // Dus 2 halve seconden!
  end if;

  LockLoop:
  loop
    //call trace('@MaxWaitSeconds=' + string(@MaxWaitSeconds));
    call LockSetOnId(@ConnId, @LoginTime, 1, @TableName, @PrimKey, @LockRes);
    if @LockRes = 0 or @MaxWaitSeconds = 0 then
      leave LockLoop;
    end if;
    waitfor delay '0:00:00:500'; // 500 miliseconden wachten (1/2 seconde dus!)
    call ReleaseLocksOnTableWithoutConnection(@TableName);
    if @MaxWaitSeconds > 0 then
      set @MaxWaitSeconds = @MaxWaitSeconds - 1;
    end if;
  end loop LockLoop;
  if @LockRes = 0 then
     set @LockIsGelukt = 1
  else
    set @LockIsGelukt = 0;
  end if;
end;


create or replace function GenerateNextUniqueNumber(
  in @Tabelname    nchar(40),
  in @Fieldname    nchar(40),
  in @ExtraWhere   nchar(100) default '',
  in @MaxAllowed   integer    default 0,
  in @RangeMax     integer    default 0 // To prevent numbers beyond e.g. 900 (for fixed sets/rlay-outs issued by us)
)
returns integer
begin
  // Maak een uniek nummer obv. een tabel en veld
  // Opmerkingen: - Berekent hoogte nummer plus 1
  //              - Werkt alleen op integervelden en op velden waarvan de inhoud in een integer kan staan
  declare @sqlString long nvarchar;
  declare @result Integer;

  set @sqlString = 'select IsNull(max(' || @Fieldname || ')+1, 1) result into @result from ' || @tabelname ||
                   if @ExtraWhere <> '' or @RangeMax <> 0 then ' where ' endif ||
                   if @ExtraWhere <> '' then @ExtraWhere endif ||
                   if @ExtraWhere <> '' and @RangeMax <> 0 then ' and ' endif ||
                   if @RangeMax <> 0 then @Fieldname || ' < ' || @RangeMax endif ||
                   if @MaxAllowed <> 0 then ' having result <= @MaxAllowed' endif
                   ;
  execute immediate @sqlString;

  return(@result);

end;



create or replace procedure ProgressAdd(in @Value integer)
begin
  //call TraceBegin('ProgressAdd > @Value = ' + string(@Value));

  if @@IgnoreProgressAdd = 0 then
    update tabProgress set ProgressValue = ProgressValue + @Value
    where  ProgressConnId= connection_property('number');
  end if;

  //call TraceEind('ProgressAdd');
end;


create or replace procedure ProgressAddAndSetDesc(in @Value integer, in @Desc nchar(40))
begin
  //call TraceBegin('ProgressAddAndSetDesc (@Value='+string(@Value)+')');

  if @@IgnoreProgressAdd = 0 then
    update tabProgress set ProgressValue = ProgressValue + @Value, ProgressDesc = @Desc
    where  ProgressConnId= connection_property('number');
  end if;

  //call TraceEind('ProgressAddAndSetDesc');
end;


create or replace procedure ProgressCreate(in @MinValue integer, in @MaxValue integer, in @Desc nchar(40))
begin
  //call TraceBegin('ProgressCreate (@MinValue='+string(@MinValue)+', @MaxValue='+string(@MaxValue)+', @Desc='+string(@Desc)+')');

  if (@MinValue=0) and (@MaxValue=0) then
    set @MaxValue=100;
  end if;
  delete tabProgress where ProgressConnId = connection_property('number');
  insert into tabProgress(ProgressConnId,ProgressMin,ProgressMax, ProgressValue, ProgressDesc)
  values(connection_property('number'), @MinValue, @MaxValue, @MinValue, @Desc);

  //call TraceEind('ProgressCreate');

end;


