create or replace function IntToCodenummer(
  @i              integer,             // Number to convert to string
  @length         smallint default 3,  // Prefixed with 0 until this length matches
  @Maxlength      smallint default 10, // Maximum length to return (if larger than @length); Must be equal or higher than @length, otherwise, obviously, this IS the length being returned
  @NullIfOverflow smallint default 0   // 0 = return right (up to @MaxLength) part of the string, 1 = Return NULL when larger than @MaxLength
)
returns
  nchar(20)
begin
  if @i >= power(10, @length) then
    if @i < power(10, @MaxLength) then
      return string(@i)
    else
      if @NullIfOverflow = 0 then
        return (right('000' || @i, @maxLength))
      else
        return null;
      end if;
    end if;
  else
    return (right('000' || @i, @Length));
  end if;
end;




create or replace function IsSelectieInLijst(
  in @Selectie  nchar (100),
  in @Selecties long nvarchar,
  in @RowDelimiter nchar(4) default ',',
  in @FieldDelimiter nchar(4) default ';'
  )
returns smallint // 0 = Niet aanwezig, 1 = WEL aanwezig
begin
  declare @GevondenSelectie nchar(40);
  declare @Resultaat        smallint = 0  /* Niet aanwezig */;
  declare @cmd              long nvarchar;

  if (NULLIF(TRIM(@Selecties), '')  is not null) and (NULLIF(TRIM(@Selectie), '') is not null) then
    set @RowDelimiter   = Replace(@RowDelimiter, '''', '''''');
    set @FieldDelimiter = Replace(@FieldDelimiter, '''', '''''');

    set @cmd = '
select first 1 into @Resultaat
from openstring(value @Selecties)
     with (keuze nchar(40))
     option (delimited by ''' || @FieldDelimiter || ''' row delimited by ''' || @RowDelimiter || ''')
     as Keuzelijst
where keuze = @Selectie';
call trace(@cmd);
    execute immediate with batch off @cmd;
  end if;

  Return(@Resultaat); // 0 = Niet aanwezig, 1 = WEL aanwezig
end;


create or replace function LeesNummerUitNederlandsBetalingskenmerk(
  in @Betalingskenmerk nchar(40)
)
returns nchar(40)
begin
  // Zie https://www.betaalvereniging.nl/betalingsverkeer/giraal-betalingsverkeer/wijzigingen-verwerking-acceptgirobetalingen/specificaties-betalingskenmerk/
  // Voorbeelden:
  //select LeesNummerUitNederlandsBetalingskenmerk('12234534622567'); // -> 234534622567
  //select LeesNummerUitNederlandsBetalingskenmerk('13234534622567'); // -> niks, want lengte onjuist
  //select LeesNummerUitNederlandsBetalingskenmerk('22234534622567'); // -> niks, want controlegetal onjuist
  //select LeesNummerUitNederlandsBetalingskenmerk('5000056789012345'); // -> 000056789012345 (16 lang, duc geen lengtecijfer)
  //select LeesNummerUitNederlandsBetalingskenmerk('42123456789012'); // -> 123456789012

  // Opbouw cijferreeks:
  // 7 cijfers = 7N
  // 9 cijfers = C+L+7N waarbij L=7
  // 10 cijfers = C+L+8N waarbij L=8
  // 11 cijfers = C+L+9N waarbij L=9
  // 12 cijfers = C+L+10N waarbij L=0
  // 13 cijfers = C+L+11N waarbij L=1
  // 14 cijfers = C+L+12N waarbij L=2
  // 16 cijfers = C+15N
  // Berekening controlecijfer:
  // Bepaal som van alle gewogen cijfers:
  // - Gewicht per cijfer (vanaf rechts gezien; indien meer dan 10 cijfers, dan herhalen):
  //   2, 4, 8, 5, 10, 9, 7, 3, 6, 1
  // - Van dit totaal de modulo 11 nemen; dat is de rest na deling door 11
  // - Controlecijfer is 11 - rest
  // - als controlecijfer = 10, gebruik dan 1
  // - als controlecijfer = 11, gebruik dan 0
  // Voorbeeld: (5)000 0567 8901 2345
  // Cijfers  :   0  0  0  0  5  6  7  8  9  0  1  2  3  4  5
  // Gewichten:  10  5  8  4  2  1  6  3  7  9 10  5  8  4  2
  // Producten:   0  0  0  0 10  6 42 24 63  0 10 10 24 16 10
  // Totaal   : 215
  // Modulo 11: 215/11 = 19 rest 6
  // C = 11 - 6 = 5

  // Gewichten obv ascii: A=1, B=2, C=3, etc.
  declare @gewicht nchar(40) = 'AFCGIJEHDBAFCGIJEHDBAFCGIJEHDBAFCGIJEHDB';

  declare @som integer = 0;
  declare @teller integer;
  declare @lengte integer = length(@Betalingskenmerk);
  declare @Ascii0 smallint = ascii('0');
  declare @AsciiA smallint = ascii('A') - 1;

  // obv lengte controleren of we doorgaan
  case
    when @lengte < 7 then
      return null;

    when @lengte = 7 then
      return @Betalingskenmerk;

    when @lengte = 15 then
      // Lengte van 15 kan niet
      return null;

    when @lengte = 16 then
      // Hier dus niks, want een getal van 16 heeft geen lengte
    when @lengte > 16 then
      return null;

    else
      begin
        declare @lengtegetal smallint;
        set @lengtegetal = ascii(substring(@Betalingskenmerk, 2, 1)) - @Ascii0;
        if @lengtegetal <= 2 then set @lengtegetal = @lengtegetal + 10 endif;
        if @lengtegetal + 2 <> @Lengte then
          // Lengtegetal komt niet overeen
          return null;
        end if;
      end;
  end case;

  // Nu de rest uitrekenen...
  set @teller = @lengte;
  set @gewicht = substring(@gewicht, length(@gewicht) - @lengte + 1); // Maak lengte van gewichten gelijk aan lengte van betalingskenmerk

  while @teller > 1 loop // 1e karakter niet meetellen, dat is het controlegetal
    set @som = @som + (ascii(substring(@Betalingskenmerk, @teller)) - @Ascii0) * (ascii(substring(@gewicht, @teller)) - @AsciiA);
    set @teller = @teller - 1;
  end loop;

  begin
    declare @Controlegetal smallint;
    declare @ControleCijfer nchar(1);

    set @Controlegetal = 11 - mod(@som, 11);
    case @Controlegetal
      when 10 then set @ControleCijfer = '1';
      when 11 then set @ControleCijfer = '0';
      else set @ControleCijfer = string(@Controlegetal);
    end case;

    if left(@Betalingskenmerk, 1) = @ControleCijfer then
      // Yes, getal is geldig en heeft soms nog een lengtegetal dat eraf moet!!
      if @lengte = 16 then
        return substring(@Betalingskenmerk, 2);
      else
        return substring(@Betalingskenmerk, 3);
      end if;
    else
      // Niet geldig
      return null;
    end if;
  end;

end;


create or replace function LeftOrWhole(@s long nvarchar, @delimiter nchar(40))
returns long nvarchar
begin
  declare @LastDelimPosition integer = charindex(@delimiter, @s + @delimiter);
  return left(@s, @LastDelimPosition - 1);
end;


create or replace function nchar2tag(in @veld nchar(100))
returns nchar(100)
begin
  declare @ValidChars nchar(200) = 'a-zA-Z1-9_';
  declare @Replacement nchar(1) = '_';
  declare @result nchar(100) = '';
  declare @teller integer;
  // Change all invalid chars to _: !! are 2 question marks => ___are_2_question_marks
  set @teller = patindex('%[^' + @ValidChars + ']%', @veld);
  while @teller > 0 loop
    set @result = @result + @Replacement + substr(@veld, 1, @teller-1);
    set @veld = substr(@veld, @teller+1);
    set @teller = patindex('%[^' + @ValidChars + ']%', @veld);
  end loop;
  set @result = @result + '_' + @veld; // De rest gewoon overnemen, want die is allemaal geldig

  // Remove all double @Replacement: abc__de__fg___hij -> abc_de_fg_hij
  while locate(@result, @Replacement+@Replacement) > 0 loop
    set @result = replace(@result, @Replacement+@Replacement, @Replacement);
  end loop;
  set @result = 'vr_' || lower(trim(@result, '_')); // Eerste en laatste _ weghalen, alles in lowercase

  return @result;
end;
//select nchar2tag('Dit is een !-teken, moet van alles & nog wat worden vervangen :)');


create or replace function RightOrNone(@s long nvarchar, @delimiter nchar(40))
returns long nvarchar
begin
  declare @LastDelimPosition integer = charindex(@delimiter, @s + @delimiter);
  declare @NextDelimPosition integer;

  loop
    set @NextDelimPosition = charindex(@delimiter, substring(@s, @LastDelimPosition + 1));
    if @NextDelimPosition = 0 then
      leave;
    end if;
    set @LastDelimPosition = @LastDelimPosition + @NextDelimPosition;
  end loop;
  return substring(@s, @LastDelimPosition + 1);
end;


create or replace function RightOrWhole(@s long nvarchar, @delimiter nchar(40))
returns long nvarchar
begin
  declare @LastDelimPosition integer = charindex(@delimiter, @s);
  declare @NextDelimPosition integer;

  loop
    set @NextDelimPosition = charindex(@delimiter, substring(@s, @LastDelimPosition + 1));
    if @NextDelimPosition = 0 then
      leave;
    end if;
    set @LastDelimPosition = @LastDelimPosition + @NextDelimPosition;
  end loop;
  return substring(@s, @LastDelimPosition + 1);
end;


create or replace procedure SplitCode(
  @Code       long nvarchar,
  @Delimiters nchar(10)
)
result(
  ListGid integer,
  Code    long nvarchar
)
begin
  // Splits de code o.b.v. meegegeven delimiters
  // Houdt rekening met haakjes [{( en dubbele/enkele aanhalingstekens

  declare local temporary table tmpList(
    ListGid as integer default autoincrement,
    Code long nvarchar
  ) on commit preserve rows;

  declare @charpointer smallint = 1;
  declare @StartOfRecord smallint = 1;
  declare @char nchar;
  declare @haken nchar(100) = '';

  if @Code <> '' then
    while @charpointer <= length(@Code) loop
      set @char = substring(@Code, @charpointer, 1);

      case
        when @char = '''' then
          // Skip tot volgende kwootje
          set @charpointer = locate(@code, @char, @charpointer + 1);
        when @char = '"' then
          // Skip tot volgende kwootje
          set @charpointer = locate(@code, @char, @charpointer + 1);
        when @char in ('(', '[', '{') then
          // Doorzoeken tot zelfde haakje sluiten, dus
          set @haken = @haken + @char;
        when @char = ')' then
          if right(@haken, 1) = '(' then
            set @haken = left(@haken, length(@haken) - 1);
          else
            // FOUT!
            set @charpointer = length(@Code);
            delete tmpList;
          end if;
        when @char = ']' then
          // Als losse code opnemen is sneller dan gezamenlijk met code hierboven
          if right(@haken, 1) = '[' then
            set @haken = left(@haken, length(@haken) - 1);
          else
            // FOUT!
            set @charpointer = length(@Code);
            delete tmpList;
          end if;
        when @char = '}' then
          // Als losse code opnemen is sneller dan gezamenlijk met code hierboven
          if right(@haken, 1) = '{' then
            set @haken = left(@haken, length(@haken) - 1);
          else
            // FOUT!
            set @charpointer = length(@Code);
            delete tmpList;
          end if;
      end case;
      if @haken = '' and locate(@Delimiters, @char) > 0 then
        // Zet dit deel in de lijst
        insert into tmpList(Code) values(trim(substring(@Code, @StartOfRecord, @charpointer - @StartOfRecord)));
        set @StartOfRecord = @charpointer + 1;
      end if;
      set @charpointer = @charpointer + 1;
    end loop;
    if @haken = '' then
      insert into tmpList(Code) values(trim(substring(@Code, @StartOfRecord)));
    else
      // FOUT!
      delete tmpList;
    end if;
  end if;

  select * from tmpList order by ListGid;

end;


create or replace function TekstVoldoetAanHerkenningstekst(
  in @tekst long nvarchar,
  in @Herkenningstekst long nvarchar
)
  returns smallint // 0 = Tekst voldoet niet aan herkenningstekst, 1 = Tekst voldoet WEL aan herkenningstekst
  //als 1 van beide teksten leeg, dan altijd 0 als resultaat
begin
  declare @AantalHerkenningsteksten smallint;
  declare @AantalGevondenTeksten smallint;

  if @Herkenningstekst = '' or @tekst = '' then
    return 0; // Lege strings, dus voldoet niet
  end if;

  //Enkele karakters escapen (dit is sneller dan een lus)
  set @Herkenningstekst = replace(@Herkenningstekst, '\', '\\');
  set @Herkenningstekst = replace(@Herkenningstekst, '%', '\%');
  set @Herkenningstekst = replace(@Herkenningstekst, '[', '\[');
  set @Herkenningstekst = replace(@Herkenningstekst, '_', '\_');

  SELECT count(*), sum(if @tekst like '%'+tekstveld+'%' escape '\' then 1 endif)
  INTO @AantalHerkenningsteksten, @AantalGevondenTeksten
  FROM OPENSTRING( VALUE @Herkenningstekst)
  WITH (tekstveld LONG NVARCHAR) OPTION ( ROW DELIMITED BY ';') AS dummy;

  //call trace('Aantal teksten: ' + string(@AantalHerkenningsteksten)+'; Herkend: ' + string(@AantalGevondenTeksten));

  if @AantalHerkenningsteksten = @AantalGevondenTeksten then
    return 1;
  else
    return 0;
  end if;
end;

//select TekstVoldoetAanHerkenningstekst('Dit is een tekst', 'Herkenningstekst;dit is;ook een tekst;tekst')


create or replace function VRTemplateValueToPrint ( @template nchar(250), @value nchar(250) )
returns nchar(250)
begin
    declare @result nchar(250);
    declare @templateIndex int;
    declare @valueIndex int;
    declare @templateChar nchar(1);
    declare @optionalTrailingBlanks bit;
    declare @optionalLeadingBlanks bit;
    declare @uppercaseMode bit;
    declare @lowercaseMode bit;
    declare @caseCheckMode bit;
    declare @charIsSet bit;

    set @result = '';
    set @templateIndex = 1;
    set @valueIndex = 1;
    set @optionalTrailingBlanks = 1;
    set @optionalLeadingBlanks = 0;
    set @uppercaseMode = 0;
    set @lowercaseMode = 0;
    set @caseCheckMode = 0;

    while @templateIndex <= length(@template)
    loop
      set @templateChar = substring(@template, @templateIndex, 1);
      set @charIsSet = 0;

      if @templateChar = '!' then
        set @optionalTrailingBlanks = 0;
        set @optionalLeadingBlanks = 1;
        set @charIsSet = 1;
      elseif @templateChar = '>' then
        if @lowercaseMode = 1 then // zitten we al in een casemode, dan alleen uitzetten
          set @lowercaseMode = 0;
        else
          set @uppercaseMode = 1;
        end if;
        set @charIsSet = 1;
      elseif @templateChar = '<' then
        if @uppercaseMode = 1 then // zitten we al in een casemode, dan alleen uitzetten
          set @uppercaseMode = 0;
        else
          set @lowercaseMode = 1;
        end if;
        set @charIsSet = 1;
      elseif @templateChar = '\' then
        set @templateIndex = @templateIndex + 1; // skip volgende character
        set @charIsSet = 1;
        if @templateIndex <= length(@template) then
          set @result = @result || substring(@template, @templateIndex, 1);
          set @charIsSet = 1;
        end if;
      elseif @templateChar = ':' or @templateChar = ';' or @templateChar = '/' or @templateChar = '.' or @templateChar = '_' then
        set @result = @result || ' ';
        set @charIsSet = 1;
      elseif @templateChar = 'L' or @templateChar = 'l' and @valueIndex <= length(@value) then
        if patindex('%[A-Z]%', substring(@value, @valueIndex, 1)) > 0 then
          set @result = @result || (if @uppercaseMode = 1 then upper(substring(@value, @valueIndex, 1)) else if @lowercaseMode = 1 then lower(substring(@value, @valueIndex, 1)) else substring(@value, @valueIndex, 1) endif endif);
          set @charIsSet = 1;
        end if;
        set @valueIndex = @valueIndex + 1;
      elseif @templateChar = 'A' or @templateChar = 'a' and @valueIndex <= length(@value) then
        if patindex('%[A-Z,0-9]%', substring(@value, @valueIndex, 1)) > 0 then
          set @result = @result || (if @uppercaseMode = 1 then upper(substring(@value, @valueIndex, 1)) else if @lowercaseMode = 1 then lower(substring(@value, @valueIndex, 1)) else substring(@value, @valueIndex, 1) endif endif);
          set @charIsSet = 1;
        end if;
        set @valueIndex = @valueIndex + 1;
      elseif @templateChar = 'C' or @templateChar = 'c' then
        if @valueIndex <= length(@value) then
          set @result = @result || (if @uppercaseMode = 1 then upper(substring(@value, @valueIndex, 1)) else if @lowercaseMode = 1 then lower(substring(@value, @valueIndex, 1)) else substring(@value, @valueIndex, 1) endif endif);
          set @charIsSet = 1;
        end if;
        set @valueIndex = @valueIndex + 1;
      elseif @templateChar = '0' or @templateChar = '9' and @valueIndex <= length(@value) then
        if patindex('%[0-9]%', substring(@value, @valueIndex, 1)) > 0 then
          set @result = @result || substring(@value, @valueIndex, 1);
          set @charIsSet = 1;
        end if;
        set @valueIndex = @valueIndex + 1;
      elseif @templateChar = '#' and @valueIndex <= length(@value) then
        if patindex('%[0-9,+,-]%', substring(@value, @valueIndex, 1)) > 0 then
          set @result = @result || substring(@value, @valueIndex, 1);
          set @charIsSet = 1;
        end if;
        set @valueIndex = @valueIndex + 1;
      else
        set @result = @result || ' '; //@templateChar;
        set @valueIndex = @valueIndex + 1;
        set @charIsSet = 1;
      end if;

      // Geen karakter gevuld, opvullen met spatie
      if @charIsSet = 0 then
          if @optionalTrailingBlanks = 1 then
              set @result = @result || ' ';
          end if;
          if @optionalLeadingBlanks = 1 then
              set @result = ' ' || @result;
          end if;
      end if;

      set @templateIndex = @templateIndex + 1;
    end loop;

    return @result;
end;



create or replace procedure DisableEvents(
  in @TimeoutInSeconden smallint default 30)
begin
  // Dit is de tegenhanger van ReEnableEvents en heet zowel in qsysteem als in de administratieDB hetzelfde!
  // Kan vaker worden aangeroepen, waarbij de lijst wordt aangevuld, zodat later de gehele lijst weer kan worden enabled
  if not exists(select first 1 from systable where table_name = 'tabConvertDisabledEvents') then
    create table tabConvertDisabledEvents(cdeEventName nchar(250));
  end if;

  insert into tabConvertDisabledEvents(cdeEventName)
  select event_name from sys.sysevent where enabled = 'Y' and event_name not in(select cdeEventName from tabConvertDisabledEvents);

  for @CursorDisabledEvents AS CURSOR_DisabledEvents CURSOR FOR
    select event_name @event_name from sys.sysevent where enabled = 'Y'
  for read only do
    execute immediate string('alter event "', @event_name, '" disable');
  end for;

  // Wachtlus totdat de events klaar zijn (met time-out van 30 seconden)
  begin
    declare @teller smallint = 0;
    WaitForEventLoop: loop
      if not exists(select first 1 from sa_conn_info() inner join sysevent on name = event_name) then
        leave WaitForEventLoop; // Er draaien geen events, dus doorgaan
      end if;
      set @teller = @teller + 1;
      if @teller > @TimeoutInSeconden then
        leave WaitForEventLoop; // Lang genoeg gewacht, dus alsnog stoppen (fail..)
      end if;
      waitfor delay '00:00:01'; // Wacht 1 seconden
    end loop;
  end;

end;


create or replace procedure ReEnableEvents()
begin
  // Dit is de tegenhanger van DisableEvents en heet zowel in qsysteem als in de administratieDB hetzelfde!
  if exists(select first 1 from systable where table_name = 'tabConvertDisabledEvents') then
    for @CursorReEnabledEvents AS CURSOR_ReEnabledEvents CURSOR FOR
      select cdeEventName @event_name from tabConvertDisabledEvents inner join sys.sysevent on event_name = cdeEventName where enabled = 'N'
    for read only do
      execute immediate string('alter event "', @event_name, '" enable');
    end for;
    delete from tabConvertDisabledEvents;
  end if;
end;


create or replace function TestDatabaseAndServerVersion()
returns integer //-1 = Db > Server, 0 = Gelijk, 1 = Server > Db
begin
  declare @DbVersion nchar(80);
  declare @ServerVersion nchar(80);

  declare @a long nvarchar;
  set @a =
      '(select last_time, operation, ' +
        'locate(version + ''.'', ''.'')-1 Version1Len, ' +
        '1 Version1Start, ' +
        'cast(substr(version, Version1Start, Version1Len) as nchar(15)) Version1, ' +
        'Version1Start + Version1Len + 1 Version2Start, ' +
        'locate(version + ''.'', ''.'',Version2Start)-Version2Start Version2Len, ' +
        'cast(substr(version, Version2Start, Version2Len) as nchar(15))Version2, ' +
        'Version2Start + Version2Len + 1 Version3Start, ' +
        'locate(version + ''.'', ''.'',Version3Start)-Version3Start Version3Len, ' +
        'cast(substr(version, Version3Start, Version3Len) as nchar(15)) Version3, ' +
        'Version3Start + Version3Len + 1 Version4Start, ' +
        'locate(version + ''.'', ''.'',Version4Start)-Version4Start Version4Len, ' +
        'cast(substr(version, Version4Start, Version4Len) as nchar(15)) Version4, ' +
        'repeat(''0'', 10 - Version1Len) + Version1 + ''.'' + ' +
        'repeat(''0'', 10 - Version2Len) + Version2 + ''.'' + ' +
        'repeat(''0'', 10 - Version3Len) + Version3 + ''.'' + ' +
        'repeat(''0'', 10 - Version4Len) + Version4 TotalVersion ' +
      'from sys.syshistory ' +
      ') a ';

  // Databaseversie opvragen
  execute immediate 'select first TotalVersion into @DbVersion from ' + @a +
    'where operation in (''INIT'', ''UPGRADE'') ' +
    'order by TotalVersion desc';

  // Serverversie opvragen
  execute immediate 'select first TotalVersion into @ServerVersion from ' + @a +
    ' order by last_time desc, ' +
    ' if operation=''LAST_START'' then 0 else 1 endif';
//ACW Hier mogen GEEN traces in zitten, want het wordt aangeroepen door events nog voor de DatbaseInit!!!!!
//call trace('@DbVersion    =' + @DbVersion);
//call trace('@ServerVersion=' + @ServerVersion);

  case
    when @ServerVersion = @DbVersion then
      return 0;
    when @ServerVersion < @DbVersion then
      return -1;
    else
      return 1;
  end case;

end;


