// Het creeeren van een materialized view voor het gebruik in o.a. rapportages.
create or replace procedure CreateMatViewvwBackorderAantallen(in @UniekNummer nchar(20))
begin
  declare @View nchar(100);
  declare @Def long nvarchar;

  set @@ErrorTextProcedure = 'Begin CreateMatViewvwBackorderAantallen > @UniekNummer = ' + @UniekNummer;
  //call Trace(@@ErrorTextProcedure);

  select table_name, view_def into @View, @Def from systable inner join sysusers on (uid = creator) where table_name = 'vwBackorderAantallen' and name='KINGSYSTEM';
  set @View = @View+@UniekNummer;
  set @Def  = Substr(@Def, Locate(@Def, ' as') + 3);

  if not exists(select 1 from sys.systable where table_name=@View) then
    set temporary option string_rtruncation = 'On';
    execute immediate 'create materialized view ' || @view || ' as ' || @Def ;
    set temporary option string_rtruncation = 'Off';
    execute immediate 'refresh materialized view '  || @view  || ' WITH ISOLATION LEVEL READ UNCOMMITTED';
    execute immediate 'create index Idx_calcBoOrrGid on '  || @view || '  (calcBoOrrGid)';
  else
    execute immediate 'refresh materialized view '  || @view  || ' WITH ISOLATION LEVEL READ UNCOMMITTED';
  end if;

  set @@ErrorTextProcedure = 'Einde CreateMatViewvwBackorderAantallen > @UniekNummer = ' + @UniekNummer;
  //call Trace(@@ErrorTextProcedure);
end;

