//Verwijder alle materialized views in de database. Maak ook de tabel tabPooledMaterializedView leeg, waarin al deze views in gedefinieerd staan.
//Deze storedprocedure wordt o.a. gebruikt als er administraties ter reparatie worden aangeboden.

create or replace procedure DropMatView()
begin
  // Zelfs als @@UseMaterializeViews op 0 staat, dan dienen we bestaande materialized views op te ruimen!! (ivm updates)

  set @@ErrorTextProcedure = 'Begin DropMatView';
  //call Trace(@@ErrorTextProcedure);

  for @Cursor as Cursor_MatView Cursor for
    select table_name @vwName from systable key join sysusers where table_type = 'mat view' and name = 'KingSystem'
  for read only
  do
    execute immediate 'drop materialized view ' ||  @vwName;
  end for;
  if exists(select 1 from systable key join sysusers where name = 'KingSystem' and table_name = 'tabPooledMaterializedView') then
    delete KingSystem.tabPooledMaterializedView;
  end if;

  set @@ErrorTextProcedure = 'Einde DropMatView';
  //call Trace(@@ErrorTextProcedure);
end;


// Het creeeren van een materialized view voor het begruik in rapportages.
// Deze word nu gebruikt in dmVoorraadOverichtGroepData.
create or replace procedure DropMatViewvwVoorraadAantallen(in @UniekNummer nchar(20))
begin

  //call TraceBegin('DropMatViewvwVoorraadAantallen');
  if isnull(@UniekNummer, '') <> '' then
    if exists(select 1 from sys.systable where table_name='vwVoorraadAantallen' || @UniekNummer) then
      execute immediate 'drop view ' || 'vwVoorraadAantallen' || @UniekNummer
    end if;
  end if;

  //call TraceEind('DropMatViewvwVoorraadAantallen > '+@UniekNummer);
end;

create or replace procedure PooledMatViewRefresh(
  in @Soort             smallint,
  in @UniekNummer       nchar(20)
)
begin
  // Als er geen materialized views gebruikt mogen worden, dan mogen we geen materialized view gaan maken of refreshen!
  if isnull(@@UseMaterializeViews, 1) <> 1 then
    leave;
  end if;


  set @@ErrorTextProcedure = 'Begin PooledMatViewRefresh > @Soort = ' + string(@Soort) + ', @UniekNummer = ' + string(@UniekNummer);
  //call Trace(@@ErrorTextProcedure);

  case @Soort
  when 0 then //vwVoorraadAantallen
    call CreateMatViewvwVoorraadAantallen(@UniekNummer);
  when 1 then //vwBackorderAantallen
    call CreateMatViewvwBackorderAantallen(@UniekNummer);
  when 2 then //vwVoorraadAantallenKlein
    call CreateMatViewvwVoorraadAantallenKlein(@UniekNummer);
  when 3 then //vwBestelKopTotalen
    call CreateMatViewvwBestelKopTotalen(@UniekNummer);
  when 4 then //vwMeestRecenteOpenstaandePosten
    call CreateMatViewvwMeestRecenteOpenstaandePosten(@UniekNummer);
  else
    Raiserror 20352; //(20352) Materialized View soort onbekend!
  end case;

  set @@ErrorTextProcedure = 'Einde PooledMatViewRefresh';
  //call Trace(@@ErrorTextProcedure);
end;

create or replace procedure PooledMatViewRelease(in @UniekNummer nchar(20))
begin
  declare @pmvGid integer;

  set @@ErrorTextProcedure = 'Begin PooledMatViewRelease > @UniekNummer = ' + @UniekNummer;
  //call Trace(@@ErrorTextProcedure);

  select pmvGid into @pmvGid from tabPooledMaterializedView where pmvInGebruik = 1 and pmvUniekNummer = @UniekNummer;

  if @pmvGid is not null then
    // Uit gebruik nemen
    update tabPooledMaterializedView set pmvInGebruik = 0 where pmvGid = @pmvGid;

    // en de semafoorlock vrijgeven
    call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabPooledMaterializedView', 'pmvGid='+string(@pmvGid));
  end if;

  set @@ErrorTextProcedure = 'Einde PooledMatViewRelease > @UniekNummer = ' + @UniekNummer;
  //call Trace(@@ErrorTextProcedure);
end;


// Het creeeren van een materialized view voor het begruik in rapportages.
// Deze word nu gebruikt in dmVoorraadOverichtGroepData.

create or replace procedure PooledMatViewUse(
  in  @Soort             smallint, //Zie tabPooledMaterializedView.pmvSoortView
  in  @CreateWithRefresh smallint, //0 = Alleen nummer in gebruik nemen, 1 = in gebruik nemen+refresh
  out @UniekNummer       nchar(20)
)
begin
  declare @pmvGid         	integer;
  declare @LockGelukt      	integer;
  declare @IsolationLevel  	smallint;
  declare @UniekNummerInt  	integer;
	declare @CountUniekNummer integer;
  declare @RecordAangemaakt smallint;

  set @@ErrorTextProcedure = 'Begin PooledMatViewUse > @Soort = ' + string(@Soort) + ', @CreateWithRefresh = ' + string(@CreateWithRefresh);
  //call Trace(@@ErrorTextProcedure);

  // Als er een live reorganisatie draait, dan mogen we geen materialized view gaanmaken of refreshen!
  if isnull(@@UseMaterializeViews, 1) <> 1 then
    set @UniekNummer = '' ;
    leave;
  end if;

  // Isolation-level 3 gekozen zodat de eerste select al direct dat record lockt (ivm. updaten naar InGebruik)
  set @IsolationLevel = @@Isolation;
  if @@Isolation < 3 then
    set temporary option Isolation_Level = 3;
  end if;

  set @RecordAangemaakt = 0; //Als deze 1 is dan is er een record aangemaakt in tabPooledMaterializedView en moet er ook een refresh worden gegeven

  // Zoek eerste de beste niet-in-gebruik-zijnde view
  select first  pmvGid,  pmvUniekNummer
  into         @pmvGid, @UniekNummer
  from   tabPooledMaterializedView
  where  pmvInGebruik = 0
     and pmvSoortView = @Soort
  order by pmvGid;

  if @pmvGid is null then
    // Eerst uniek nummer genereren

    //MR 23-jan-2012 bug #34641: Als het nummer al bestaat, dit record verwijderen en een nieuwe genereren.
    RandomNumberLoop:
    loop
      call RandomNumber2(@UniekNummerInt);
      set @UniekNummer = string(@UniekNummerInt);
      // Direct onthouden en in gebruik nemen
      insert into tabPooledMaterializedView(pmvUniekNummer, pmvSoortView, pmvInGebruik)
                                  values(@UniekNummer,      @Soort,       1);

      select count(pmvUniekNummer) into @CountUniekNummer
      from tabPooledMaterializedView
      where pmvUniekNummer = @UniekNummer;

      if (@CountUniekNummer = 1) then
        leave RandomNumberLoop;
      end if;

      delete from tabPooledMaterializedView where pmvGid = @@Identity;
      waitfor delay '0:00:00:010'; // 10 miliseconde wachten
    end loop RandomNumberLoop;

    set @pmvGid = @@Identity;
    set @RecordAangemaakt = 1;
  else
    // In gebruik nemen
    update tabPooledMaterializedView set pmvInGebruik = 1 where pmvGid = @pmvGid;
  end if;

  // IsolationLevel weer standaard instellen
  execute immediate 'set temporary option Isolation_Level = ' || @IsolationLevel;


  //Semafoorlockje zetten
  call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabPooledMaterializedView','pmvGid='+string(@pmvGid), @LockGelukt);

  // 2025-11-17 OnTime defect 60123: Direct een commit geven
  // (de create/refresh later zal een auto-commit doen, dus deze commit is niet erg en zo weten we zeker dat record wordt opgeslagen)
  commit;

  // En de materialized view aanmaken/refreshen
  if (isnull(@CreateWithRefresh, 1) = 1) or (@RecordAangemaakt = 1) then
    call PooledMatViewRefresh(@Soort, @UniekNummer);
  end if;

  set @@ErrorTextProcedure = 'Einde PooledMatViewUse > @UniekNummer = ' + @UniekNummer;
  //call Trace(@@ErrorTextProcedure);
end;



CREATE OR REPLACE PROCEDURE ConnectionInfo()
BEGIN
  SELECT
    // Generic info
    now()                                             AS QueriedTime,                // Datum+tijd tbv genereren van lijsten (meerdere malen uitvoeren)
    // Connection info
    'BLOCKED'                                         AS ConnCondition,              // Conditie van deze connectie
    INFO.Userid                                       AS ConnUser,                   // Gebruiker van deze connectie
    INFO.Number                                       AS ConnNr,                     // Connectienummer van deze connectie. Is met DROP CONNECTION te gebruiken
    connection_property ('AppInfo', INFO.Number)      AS ConnHost,                   // Host-informatie van deze connectie
    cast((SELECT Value FROM sa_conn_properties() PROP WHERE PropName = 'isolation_level' and PROP.Number = INFO.Number) as smallint) AS ConnIsolationLevel,         // Isolatielevel van deze connectie
    AL.LastStatement                                  AS ConnLastStatement,          // Statement van deze connectie.
    // Lock made by this connection
    LOCKS.lock_class                                  AS LockedObject,                 // Lock object soort, Row, Schema, Table, etc. door deze connectie
    LOCKS.lock_type                                   AS LockedType,                   // Soort lock, intent, prim key, etc. door deze connectie
    LOCKS.table_name                                  AS LockedTable,                // Tabel van de lock door deze connectie
    AL.LastReqTime                                    AS LockedSince,                // Datumtijd van de poging om te locken door deze connectie
    // Lock blocked by this user
    AB.Userid                                         AS BlockedByUser,              // Blokkerende lock gezet door gebruiker
    AB.Number                                         AS BlockedByConn,              // Blokkerende lock gezet door connectie. Is met DROP CONNECTION te gebruiken
    cast((SELECT Value FROM sa_conn_properties() PROP WHERE PropName = 'isolation_level' and PROP.Number = AB.Number) as smallint) AS BlockedIsolationLevel,         // Isolatielevel van deze connectie
    AB.LastStatement                                  AS BlockedConnLastStatement,   // Statement dat de Blokkerende lock veroorzaakte; werkt alleen na statement: call sa_server_option('rememberlaststatement', 'yes')
    connection_property ('AppInfo', AB.Number)        AS BlockedConnHost,            // Host-informatie van de connectie die de blockerende lock heeft gezet
    AB.LastReqTime                                    AS BlockedLockedSince          // Datumtijd van blokkerende lock
  FROM       sa_conn_info()                   INFO
  INNER JOIN sa_locks()                       LOCKS
          ON (LOCKS.Conn_Id = INFO.Number)
  INNER JOIN sa_conn_activity()               AL
          ON (INFO.Number = AL.Number)
  // Info over connectie die de lock eerder had en de huidige connectie blokkeert
  INNER JOIN sa_conn_activity()               AB
          ON (INFO.BlockedOn = AB.Number)
  WHERE INFO.BlockedOn > 0                                  // connections met transacties die door anderen geblokkeerd zijn
UNION ALL
  SELECT
    now()                                             AS QueriedTime,
    'ACTION'                                          AS ConnCondition,
    INFO.Userid                                       AS ConnUser,                   // Gebruiker van deze connectie
    INFO.Number                                       AS ConnNr,                     // Connectienummer van deze connectie. Is met DROP CONNECTION te gebruiken
    connection_property ('AppInfo', INFO.Number)      AS ConnHost,                   // Host-informatie van deze connectie
    cast((SELECT Value FROM sa_conn_properties() PROP WHERE PropName = 'isolation_level' and PROP.Number = INFO.Number) as smallint) AS ConnIsolationLevel,         // Isolatielevel van deze connectie
    AL.LastStatement                                  AS ConnLastStatement,          // Statement van deze connectie.
    // Lock made by this connection
    LOCKS.lock_class                                  AS LockedObject,                 // Lock object soort, Row, Schema, Table, etc. door deze connectie
    LOCKS.lock_type                                   AS LockedType,                   // Soort lock, intent, prim key, etc. door deze connectie
    LOCKS.table_name                                  AS LockedTable,                // Tabel van de lock door deze connectie
    AL.LastReqTime                                    AS LockedSince,                // Datumtijd van de poging om te locken door deze connectie
    // Lock blocked by this user
    NULL                                              AS BlockedByUser,              // Blokkerende lock gezet door gebruiker
    NULL                                              AS BlockedByConn,              // Blokkerende lock gezet door connectie. Is met DROP CONNECTION te gebruiken
    NULL                                              AS BlockedIsolationLevel,         // Isolatielevel van deze connectie
    NULL                                              AS BlockedConnLastStatement,   // Statement dat de Blokkerende lock veroorzaakte; werkt alleen na statement: call sa_server_option('rememberlaststatement', 'yes')
    NULL                                              AS BlockedConnHost,            // Host-informatie van de connectie die de blockerende lock heeft gezet
    NULL                                              AS BlockedLockedSince          // Datumtijd van blokkerende lock
  FROM       sa_conn_info()                   INFO
  INNER JOIN sa_locks()                       LOCKS
          ON (LOCKS.Conn_Id = INFO.Number)
  INNER JOIN sa_conn_activity()               AL
          ON (INFO.Number = AL.Number)
//  JOIN sa_conn_activity()               AB
//    ON (INFO.Number = AB.Number)
  WHERE INFO.BlockedOn = 0;                                // connections met lopende transacties die niet geblokkeerd lijken
END;


create or replace procedure CreateDynamicTriggersStaticPart(
  in @RemoveFirst smallint default 0, // 0 = de oude NIET verwijderen, 1 = de oude eerst allemaal verwijderen
  in @TableName nchar(60) default ''  // Leeg = alle DynTriggers verwijderen en opnieuw aanmaken, anders alleen voor die tabel
)
//*************************************************************
//*** ALLE tabellen geschikt maken voor dynamische triggers ***
//*************************************************************
begin
  declare @inhoud long nvarchar;
  declare @inhoud2 long nvarchar;

  if @RemoveFirst = 1 then
    for @DynTriggerCursor AS DynTriggerCursor CURSOR FOR
    select trigger_name @trName from systrigger where trigger_name like '%'+@TableName+'_DynTrigger'
    for read only
    do
      execute immediate ' drop trigger ' || @trName;
    end for;
  end if;

  for @tables AS TablesCursor CURSOR FOR
  select table_name @tabName from sysTable inner join sysuser on user_id = creator where table_type='base' and user_name = 'kingsystem' and (@TableName = '' or table_name = @TableName)
    //and @tabName not in ('tabConvertDisabledEvents')
  for read only
  do
    set @inhoud =
'
begin
  if @@{tabName}HasDynamicTriggers = 1 then
  for @DynTriggerCursor AS DynTriggerCursor CURSOR FOR
    select dtExecute as @dtExecute,
           dtName as @dtName
    from tabDynamicTriggers
    where dtTablename = ''{tabName}''
      and dtMutationType = {MutType}
    order by
      dtOrder, DtGid
    for read only
  do
    begin
      execute immediate @dtExecute;
    exception
      when others then call WriteLog(2 /*fout*/, ''Fout '' || SQLSTATE || '' in Dyn.trigger: '' || @dtName || ''('' || ERRORMSG() || '')'', '''', 1 /*Overschrijf de laatste*/);
    end;
  end for;
end if;
exception
  when others then call WriteLog(2 /* fout*/, ''Fout '' || SQLSTATE || '' in Dyn.trigger for table {tabName}'',1);
end;
';

    set @inhoud2 = replace(@inhoud, '{tabName}', @tabName);
    execute immediate 'create or replace trigger tib_' || @tabName || '_DynTrigger before insert order 9900 on ' || @tabName || ' referencing new as new_record for each row begin ' || replace(@inhoud2, '{MutType}',                   '00 /*Before insert*/') || ' end';
    execute immediate 'create or replace trigger tia_' || @tabName || '_DynTrigger after  insert order 9900 on ' || @tabName || ' referencing new as new_record for each row begin ' || replace(@inhoud2, '{MutType}',                   '10 /*After insert*/' ) || ' end';
    execute immediate 'create or replace trigger tub_' || @tabName || '_DynTrigger before update order 9900 on ' || @tabName || ' referencing new as new_record old as old_record for each row begin ' || replace(@inhoud2, '{MutType}', '01 /*Before update*/') || ' end';
    execute immediate 'create or replace trigger tua_' || @tabName || '_DynTrigger after  update order 9900 on ' || @tabName || ' referencing new as new_record old as old_record for each row begin ' || replace(@inhoud2, '{MutType}', '11 /*After update*/' ) || ' end';
    execute immediate 'create or replace trigger tdb_' || @tabName || '_DynTrigger before delete order 9900 on ' || @tabName || ' referencing old as old_record for each row begin ' || replace(@inhoud2, '{MutType}',                   '02 /*Before delete*/') || ' end';
    execute immediate 'create or replace trigger tda_' || @tabName || '_DynTrigger after  delete order 9900 on ' || @tabName || ' referencing old as old_record for each row begin ' || replace(@inhoud2, '{MutType}',                   '12 /*After delete*/' ) || ' end';
  end for;
end;


create or replace procedure CreateDynamicTriggersVars()
begin
  for @tables AS TablesCursor CURSOR FOR
  select table_name @tabName, (select first 1 from tabDynamicTriggers where dtTablename = table_name) @HasDynTrigger from sysTable inner join sysuser on user_id = creator where table_type='base' and user_name = 'kingsystem'
  for read only
  do
    execute immediate 'create or replace variable @@' || @tabName || 'HasDynamicTriggers smallint = ' || if @HasDynTrigger is null then 0 else 1 endif;
  end for;
end;


CREATE OR REPLACE PROCEDURE LogSqlCommands(
  in @State smallint,                     // 0 = OFF, 1 = ON
  in @ConnId integer default null,        // NULL -> alle
  in @DbNumber integer default null,      // NULL -> this database
  in @Filename nchar(200) default null,   // NULL -> DbName + _SqlLog.log (no path please!), empty string or 'CON' to log to console
  in @WhatToLog nchar(200) default 'A',   // Multiple of following:
                                          // A = SQL,
                                          // B = HOST-variables
                                          // C = Plan,
                                          // D = Procedures,
                                          // E = Triggers,
                                          // F = Other
                                          // G = Blocks
  in @AddTiming smallint default 0,       // 0 = NO timing, 1 = Yes timing (Has small impact on performance)
  in @ReplaceFile smallint default 0,
  in @MaxFileSizeBytes integer default 0, // 0 = no min size
  in @MaxFileCopies integer default 0     // 0 = no limit, otehrwise ???
)
begin
  case @State
  when 1 then
    // - Filer connection
    if @ConnId is null then
      call sa_server_option('RequestFilterDB', -1);
    else
      call sa_server_option('RequestFilterDB', @ConnId);
    end if;

    // - Filter this DB
    if @DbNumber is null then
      //select first CONNECTION_PROPERTY('DBNumber') into @DbNumber;
      call sa_server_option('RequestFilterDB', -1); // Alle
    else
      call sa_server_option('RequestFilterDB', @DbNumber);
    end if;

    // - Set file name
    if @Filename is null then
      if @DbNumber is null then
        // Path of current Db
        select substring(File, 1, locate(File, '\', -1)) || 'KING_trace_SqlLog.log' into @Filename from sa_db_info() where Number = CONNECTION_PROPERTY('DBNumber');
      else
        select replace(File, '.DB', '_SqlLog.log') into @Filename from sa_db_info() where Number = @DbNumber;
      end if;
    else
      if @Filename = 'CON' then
        set @Filename = '';
      end if;
    end if;
    //set @Filename = substring(@Filename, locate(@Filename, '\', -1)+1);
    set @Filename = replace(@Filename, '\', '\\');
    call sa_server_option('RequestLogFile', @Filename);

    // - Max size of logfile
    if @MaxFileSizeBytes >= 0 then
      call sa_server_option('RequestLogMaxSize', @MaxFileSizeBytes);
    end if;

    // - Max number of files
    if @MaxFileCopies >= 0 then
      call sa_server_option('RequestLogNumFiles', @MaxFileCopies);
    end if;

    // - Add timing request
    call sa_server_option('RequestTiming', if @AddTiming = 0 then 'NO' else 'YES' endif);

    // Add last statement (to log too)
    call sa_server_option('RememberLastStatement', 'YES' );

    // What to log
    begin
      declare @What long nvarchar = '';
      if locate(@WhatToLog, 'A') > 0 then set @What = @what + ',SQL'        end if;
      if locate(@WhatToLog, 'B') > 0 then set @What = @what + ',HOSTVARS'   end if;
      if locate(@WhatToLog, 'C') > 0 then set @What = @what + ',PLAN'       end if;
      if locate(@WhatToLog, 'D') > 0 then set @What = @what + ',PROCEDURES' end if;
      if locate(@WhatToLog, 'E') > 0 then set @What = @what + ',TRIGGERS'   end if;
      if locate(@WhatToLog, 'F') > 0 then set @What = @what + ',OTHER'      end if;
      if locate(@WhatToLog, 'G') > 0 then set @What = @what + ',BLOCKS'     end if;
      if @what = '' then
        set @What = ',NONE';
      end if;

      if @ReplaceFile = 1            then set @What = @What + ',REPLACE'    end if;

      set @what = substring(@What, 2); // First comma removed

      call sa_server_option('RequestLogging', @What);
    end;

  when 0 then
    // - Stop logging
    call sa_server_option('RequestLogging', 'NONE');
    // - Remove logging of LastStatement
    call sa_server_option('RememberLastStatement', 'NO' );
    // - Clear DB filter
    call sa_server_option('RequestFilterDB', -1);
    // - Clear filename
    call sa_server_option('RequestLogFile', '');
    // - Remove timing request
    call sa_server_option('RequestTiming', 'NO');
  end;
end;




create or replace procedure AdminOnderhoud_Mobilink_CreateMobilinkSynchronisation(in @Info smallint default 0, out @Description nchar(200) default '')
begin
  if @Info = 1 then
    // Alleen voor Bax
    if exists(select first 1 from kinginfo.king_info('Licentienr') where isnumeric(Value) = 1 and value = 24627) then
      set @Description = _A('Mobilink: Aanmaken synchronisatie');
    end if;
  else
    // Events uit zetten
    call DisableEvents(10*60); // Wacht hooguit 10 minuten
    if exists(select first 1 from sa_conn_info() inner join sysevent on name = event_name) then
      call Raise(20780, _U('Events uitzetten'), _U('Wachten duurt te lang')); //(20780) %1! niet mogelijk: %2!.
    end if;

    call MobilinkSetup();

    // Events weer aan zetten
    call ReEnableEvents();
  end if;
end;


create or replace procedure AdminOnderhoud_Mobilink_DropMobilinkSynchronisation(in @Info smallint default 0, out @Description nchar(200) default '')
begin
  if @Info = 1 then
    // Alleen voor Bax
    if exists(select first 1 from kinginfo.king_info('Licentienr') where isnumeric(Value) = 1 and value = 24627) then
      set @Description = _A('Mobilink: Verwijderen synchronisatie');
    end if;
  else
    // Events uit zetten
    call DisableEvents(10*60); // Wacht hooguit 10 minuten
    if exists(select first 1 from sa_conn_info() inner join sysevent on name = event_name) then
      call Raise(20780, _U('Events uitzetten'), _U('Wachten duurt te lang')); //(20780) %1! niet mogelijk: %2!.
    end if;

    call MobilinkDrop();

    // Events weer aan zetten
    call ReEnableEvents();
  end if;
end;


create or replace procedure AdminOnderhoud_Mobilink_ExportTables(in @Info smallint default 0, out @Description nchar(200) default '')
begin
  if @Info = 1 then
    // Alleen voor Bax
    if exists(select first 1 from kinginfo.king_info('Licentienr') where isnumeric(Value) = 1 and value = 24627) then
      set @Description = _A('Mobilink: Exporteren tabellenlijst synchronisatie');
    end if;
  else
    call Mobilink_ExportTableList();
  end if;
end;


create or replace procedure MobilinkDrop(@CalledFromCreate smallint default 0)
begin
  declare @ProcPrefix nchar(40) = 'MobilinkReplication_';


  begin
    declare @VtbGid_tabelnames smallint;
    declare @VrijeTabelTables     nchar(40);  // should be like '1';

    select VrijeTabelTables
    into   @VrijeTabelTables
    from   MobilinkSetup_GetVrijeRubrieken();

    select first VtbGid into @VtbGid_tabelnames from tabVrijeTabel where VtbNummer = @VrijeTabelTables;
    if @VtbGid_tabelnames is not null then
      call Mobilink_UpdateVrijeTabel(@VtbGid_tabelnames, 2 /*Drop Mobilink*/);
    end if;

    exception when others then
      // Ignore all exceptions in this part
      set @VtbGid_tabelnames = 0;
  end;

  call MobilinkSetup_ExecuteStatement('Dropping full mobilink replication access', -1 /*initialisation*/ + @CalledFromCreate);


  // Remove subscriptions
  call MobilinkSetup_ExecuteStatement('Dropping subscriptions', 0 /*remark*/);
  for @Cursor AS CURSOR_MobilLinkSubscriptions CURSOR FOR
  SELECT publication_name @PublicationSyncName, site_name @SiteName
  FROM sys.syssyncsubscriptions
  for read only
  do
    call MobilinkSetup_ExecuteStatement('DROP SYNCHRONIZATION SUBSCRIPTION TO ' || @PublicationSyncName || ' FOR "' || @SiteName || '"');
  end for;


  // Remove remote MobiLink user
  call MobilinkSetup_ExecuteStatement('Dropping remote Mobilink users', 0 /*remark*/);
  for @Cursor AS CURSOR_MobiLinkServerUsers CURSOR FOR
  SELECT site_name @MobiLinkServerUserName
  FROM sys.syssync
  for read only
  do
    call MobilinkSetup_ExecuteStatement('drop synchronization user "' || @MobiLinkServerUserName ||'"');
  end for;


  // Remove MobiLink users
  call MobilinkSetup_ExecuteStatement('Dropping local access users for Mobilink client', 0 /*remark*/);

  for @Cursor AS CURSOR_MobiLinkUsers CURSOR FOR
    SELECT user_name @UserName
    FROM sys.sysuser inner join sys.sysremark on sysuser.object_id = sysremark.object_id
    where remarks like '%#22900357%'
  for read only
  do
    call MobilinkSetup_ExecuteStatement('Removing mobilink acces user ' || @UserName, 0/*remark*/);
    call MobilinkSetup_ExecuteStatement('DROP USER ' || @UserName);
  end for;
  update tabRegistry set contents = '' where regkey = 'MobiLinkUsers';


  //Removing publications
  for @Cursor AS CURSOR_Publications CURSOR FOR
    select publication_name @PublicationName
    from sys.syspublication
  for read only
  do
    call MobilinkSetup_ExecuteStatement('drop publication ' || @PublicationName);
  end for;

  // Removing mutation procedures
  for @Cursor AS CURSOR_Mobilink_DropProcedures CURSOR FOR
    select proc_name @procName
    from sys.sysprocedure
    where proc_name like @ProcPrefix + '%'
    order by proc_name
  for read only
  do
    call MobilinkSetup_ExecuteStatement('drop procedure ' || @procName);
  end for;

  call MobilinkSetup_ExecuteStatement('', 0);

  // Resultaat wegschrijven
  begin
    declare @FonGid integer;
    declare @VrRecordId integer;

    select  FonGid, VrRecordId
    into   @FonGid, @VrRecordId
    from   MobilinkSetup_GetVrijeRubrieken();

    call VrWaardeWijzigen('NAW', @FonGid, @FonGid, @VrRecordId, 'MobilinkResult', 'Mobilink client dropped on ' || now());
  exception
  when others then
    if not exists(select first 1 where ERROR_SQLCODE() = -20679 /*RUbriek not found*/) then
      resignal;
    end if;
  end;

end;


create or replace procedure MobilinkSetup()
begin
  // Gebruikt vrije rubrieken van de bedrijfsgegevens voor enkele parameters
  // De lijst van tabellen die benodigd zijn staan in tabMobilinkTabellen
  // Per tabel worden nu alle velden doorgegeven. Kunnen we later wellicht aanpassen
  // Resultaat van het aanmaken/updaten van de mobilink wordt in een vrije rubriek teruggegeven

  declare @ErrorText nchar(250);

  declare @ProcPrefix nchar(40) = 'MobilinkReplication_';
  declare @PublicationNameFull  nchar(100); // should be like 'PublicationSyncFull';
  declare @PublicationNameLog   nchar(100); // should be like 'PublicationSyncLog';
  declare @SubscriptionNameFull nchar(100); // should be like 'SubscriptionSyncFull';
  declare @SubscriptionNameLog  nchar(100); // should be like 'SubscriptionSyncLog';
  declare @ScriptVersion        nchar(40);  // should be like '7102345';
  declare @VrijeTabelTables     nchar(40);  // should be like '1';

  declare @FonGid integer;
  declare @VrRecordId integer;
  declare @UserName nchar(80);
  declare @ServerUserName nchar(80);
  declare @VtbGid_tabelnames smallint;

  declare @Command long nvarchar;

begin try
  call MobilinkSetup_ExecuteStatement('Creation script for Mobilink synchronisation (start: ' || now() || ')', -1 /*Initialisation*/);

  if exists(select first 1 from sys.sysprocedure where proc_name = 'DisableEvents') then
    call DisableEvents();
  end if;

  select FonGid into @FonGid from tabFileOfNaw where FonId = 'B';

  // t.b.v. rapporteren voortgang in vrije rubrieken
  begin
    declare @VrTabelNaam nchar(100);
    declare @VrGidNaam nchar(100);
    set @VrTabelNaam = VrTabelnaam('NAW', @FonGid, @FonGid);
    if not exists(select 1 from systable where table_name = @VrTabelNaam) then
      set @FonGid = null;
      call Raise(20541); //Vrije rubrieken tabel niet gevonden!
    end if;
    set @VrGidNaam = 'VrNAW' + right(repeat('0', 3) + string(@FonGid), 3) + right(repeat('0', 3) + string(@FonGid), 3) || 'RecordId';
    execute immediate 'select first ' || @VrGidNaam || ' into @VrRecordId from ' || @VrTabelNaam;
  end;

  call MobilinkDrop(1);

  // Er volgt een fout als de velden niet bestaan!
  begin
    declare @tmpKingDbUserName     nchar(80);
    declare @tmpKingDbUserPassword nchar(80);
    declare @tmpServerUserName     nchar(80);
    declare @tmpServerAddress      nchar(250);
    declare @tmpServerConnectionType nchar(80);
    declare @VrijeRubriekTekst     long nvarchar;


    // We testen ook alle andere verplichte vrije rubrieken, zodat we die straks niet meer foutief tegenkomen
    select  VrRecordId,
            PublicationNameFull,   PublicationNameLog,
            SubscriptionNameFull,  SubscriptionNameLog,
            KingDbUserName,        KingDbUserPassword,
            ServerUserName,
            ServerAddress,         ServerConnectionType,
            VrijeTabelTables
    into   @VrRecordId,
           @PublicationNameFull,  @PublicationNameLog,
           @SubscriptionNameFull, @SubscriptionNameLog,
           @tmpKingDbUserName,    @tmpKingDbUserPassword,
           @tmpServerUserName,
           @tmpServerAddress,     @tmpServerConnectionType,
           @VrijeTabelTables
    from   MobilinkSetup_GetVrijeRubrieken();

    // Test hier gelijk voor ALLE verplichte vrije rubrieken
    set @VrijeRubriekTekst = _U('Vrije rubriek %1!');
    if isnull(@PublicationNameFull, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkPublicationName_Full')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnull(@PublicationNameLog, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkPublicationName_Log')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnull(@SubscriptionNameFull, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkSubscriptionName_Full')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnull(@SubscriptionNameLog, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkSubscriptionName_Log')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnull(@tmpKingDbUserName, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkKingDbUserName')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnull(@tmpKingDbUserPassword, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkKingDbUserPassword')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnull(@tmpServerUserName, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkServerUserName')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnull(@tmpServerAddress, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkServerAddress')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnull(@tmpServerConnectionType, '') = '' then
      call Raise(20700, _P(@VrijeRubriekTekst, 'MobilinkServerConnectionType')); //(20700) Ongeldige waarde: %1!
    end if;

    if isnull(@VrijeTabelTables, '') = '' then
      call Raise(20700, _U('Vrije rubriek %1! (leeg/niet gevonden)', 'MobilinkVrijeTabel_Tablenames')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnumeric(@VrijeTabelTables) = 0 then
      call Raise(20700, _U('Vrije rubriek %1! (geen getal)', 'MobilinkVrijeTabel_Tablenames')); //(20700) Ongeldige waarde: %1!
    end if;
    if @VrijeTabelTables < 0 or @VrijeTabelTables > 999 then
      call Raise(20700, _U('Vrije rubriek %1! (niet tussen 1 en 999)', 'MobilinkVrijeTabel_Tablenames')); //(20700) Ongeldige waarde: %1!
    end if;
    select first VtbGid into @VtbGid_tabelnames from tabVrijeTabel where VtbNummer = @VrijeTabelTables;
    if @VtbGid_tabelnames is null then
      call Raise(20700, _U('Vrije rubriek %1! (niet gevonden)', 'MobilinkVrijeTabel_Tablenames')); //(20700) Ongeldige waarde: %1!
    end if;
  end;

  // Tabel met tabelnamen updaten, resultaat: alle zonder tekst in de omschrijving kunnen worden opgenomen
  call Mobilink_UpdateVrijeTabel(@VtbGid_tabelnames);

  // Test of er nog tabellen over blijven
  if not exists(select first 1 from tabVrijeTabelItems where  VtbiVtbGid = @VtbGid_tabelnames and VtbiOmschrijving not like 'fout%') then
    call Raise(20780, _U('Aanmaken Mobilinkkoppeling'), _U('Er zijn geen geschikte tabelnamen opgenomen in de vrije tabel')); //(20780) %1! niet mogelijk: %2!.
  end if;

  // ************************************************
  // *** Aanmaken insert/update/delete procedures ***
  // ************************************************
  call MobilinkSetup_CreateMutationProcedures(@VtbGid_tabelnames, @ProcPrefix);

  // **************************
  // *** Create publication ***
  // **************************
  call MobilinkSetup_CreatePublication(@VtbGid_tabelnames, @ProcPrefix, @PublicationNameFull, 1 /*with Using*/);

  call MobilinkSetup_CreatePublication(@VtbGid_tabelnames, @ProcPrefix, @PublicationNameLog, 0 /*without Using*/);

  // *********************************************
  // *** Create user for synchronization login ***
  // *********************************************
  set @UserName = MobilinkSetup_CreateUserForMobilinkLogin();

  // *******************************************
  // *** Grant access to mutation procedures ***
  // *******************************************
  call MobilinkSetup_GrantAccessToTablesForUser(@VtbGid_tabelnames, @ProcPrefix, @UserName);


  // ************************************************
  // *** Create user for external Mobilink server ***
  // ************************************************
  call MobilinkSetup_CreateUserForMobilinkServer();

  // *************************************
  // *** Subscribe user to publication ***
  // *************************************

  begin
    //select first Contents into @ScriptVersion from tabregistry where regkey = 'KingBuildNr';
    //if isnull(@ScriptVersion, '') = '' then
    //  set @ScriptVersion = '5.62';
    //end if;
    select first qdVerVersion into @ScriptVersion from qdtabversion where qdvergid = 1 /*DB buildnummer*/;


    call MobilinkSetup_SubscribeUserToPublication(@PublicationNameFull, @SubscriptionNameFull, @ScriptVersion);
    call MobilinkSetup_SubscribeUserToPublication(@PublicationNameLog, @SubscriptionNameLog, @ScriptVersion);
  end;


  // *****************************
  // *** Commando DbMlSync.exe ***
  // *****************************
  begin
    call MobilinkSetup_ExecuteStatement('Statements for DbMlSync.exe', 0 /*comment only*/);
    call MobilinkSetup_ExecuteStatement(
      'DbMlSync.exe' ||
      ' -c "uid="' + @UserName + ';pwd=%Password%;dbn=%DatabaseName%;eng=KING_SERVER" ' ||
      ' -n "' + @PublicationNameFull + '"' ||
      ' -uo' ||
      ' -s "' + @SubscriptionNameFull + '"' ||
      ' -do'
      , 0 /*comment only*/);
    call MobilinkSetup_ExecuteStatement(
      'DbMlSync.exe' ||
      ' -c "uid="' + @UserName + ';pwd=%Password%;dbn=%DatabaseName%;eng=KING_SERVER" ' ||
      ' -n "' + @PublicationNameLog + '"' ||
      ' -uo' ||
      ' -s "' + @SubscriptionNameLog + '"' ||
      ' -do'
      , 0 /*comment only*/);
  end;


  // Resultaat wegschrijven
  update tabVrijeTabelItems
  set    VtbiOmschrijving = 'Tabel is in Mobilink opgenomen (' || now() || ')'
  where  VtbiVtbGid = @VtbGid_tabelnames and VtbiOmschrijving = '';

  begin
    call VrWaardeWijzigen('NAW', @FonGid, @FonGid, @VrRecordId, 'MobilinkResult', 'Mobilink version ' || @ScriptVersion || ' client created on ' || now());
  end;
end try
begin catch
  //call trace('Ging fout!');
  select '(' || now() || ') error: ' || ERROR_SQLCODE() || ' in line ' || ERROR_LINE() || ' of proc ' || ERROR_PROCEDURE() || '(' || ERROR_MESSAGE() || ')'
  into @ErrorText;
  //call trace(@ErrorText);
  call VrWaardeWijzigen('NAW', @FonGid, @FonGid, @VrRecordId, 'MobilinkResult', @ErrorText);

  if exists(select first 1 from sys.sysprocedure where proc_name = 'ReEnableEvents') then
    call ReEnableEvents();
  end if;

  resignal;
end catch;
end;


//call MobilinkSetup();


create or replace function MobilinkSetup_CreateDeleteTable(
  in @ProcPrefix nchar(100),
  in @TableName nchar(128)
)
returns long nvarchar
begin
  declare @command long nvarchar;

  declare @FieldDeclares long nvarchar;
  declare @FieldList long nvarchar;
  declare @PKeyList long nvarchar;

  select
    list(ALL mlFieldName + ' '  + mlFieldType            , ', \x0D\x0A  ' order by mlFieldId),
    list(ALL mlFieldName                                 , ', \x0D\x0A    ' order by mlFieldId),
    list(ALL (if mlIsPrimaryKey = 1 then mlFieldName endif), ', ' order by mlFieldId)
  into @FieldDeclares, @FieldList, @PKeyList
  from Mobilink_lib_GetFieldsList(@TableName);

  set @command =
    'CREATE OR REPLACE PROCEDURE KingSystem.' + @ProcPrefix + @TableName + '_delete() \x0D\x0A' +
    'RESULT(\x0D\x0A  ' + @FieldDeclares + ')\x0D\x0A' +
    'BEGIN \x0D\x0A' +
    '  SELECT first\x0D\x0A    ' + @FieldList + '\x0D\x0A' +
    '  FROM KingSystem.' + @TableName + '\x0D\x0A' +
    '  ORDER BY ' + @PKeyList + '\x0D\x0A' +
    'END';

  return @command;
end;


create or replace function MobilinkSetup_CreateInsertTable(
  in @ProcPrefix nchar(100),
  in @TableName nchar(128)
)
returns long nvarchar
begin
  declare @command long nvarchar;

  declare @FieldDeclares long nvarchar;
  declare @FieldList long nvarchar;
  declare @PKeyList long nvarchar;

  select
    list(ALL mlFieldName + ' '  + mlFieldType            , ', \x0D\x0A  ' order by mlFieldId),
    list(ALL mlFieldName                                 , ', \x0D\x0A    ' order by mlFieldId),
    list(ALL (if mlIsPrimaryKey = 1 then mlFieldName endif), ', ' order by mlFieldId)
  into @FieldDeclares, @FieldList, @PKeyList
  from Mobilink_lib_GetFieldsList(@TableName);

  set @command =
    'CREATE OR REPLACE PROCEDURE KingSystem.' + @ProcPrefix + @TableName + '_insert() \x0D\x0A' +
    'RESULT(\x0D\x0A  ' + @FieldDeclares + ')\x0D\x0A' +
    'BEGIN \x0D\x0A' +
    '  SELECT \x0D\x0A    ' + @FieldList + '\x0D\x0A' +
    '  FROM KingSystem.' + @TableName + '\x0D\x0A' +
    '  ORDER BY ' + @PKeyList + '\x0D\x0A' +
    'END';

  return @command;
end;


create or replace procedure MobilinkSetup_CreateMutationProcedures(
  in @VtbGid_tabelnames smallint,
  in @ProcPrefix nchar(100)
)
begin
  declare @Command long nvarchar;
  declare @Resultaat nchar(100);

  call MobilinkSetup_ExecuteStatement('Create mutation procedures', 0);

  for @Cursor AS CURSOR_Mobilink_CreateMutationsForTables CURSOR FOR
    select VtbiGid @VtbiGid, VtbiCode @TableName
    from   tabVrijeTabelItems
    where  VtbiVtbGid = @VtbGid_tabelnames
       and VtbiOmschrijving = ''
    order by VtbiCode
  for read only

//    select mltTablename @TableName
//    from tabMobilinkTabellen
//    inner join sys.systable on table_name = mltTablename
//    order by mltTablename
  do
    set @Command = MobilinkSetup_CreateInsertTable(@ProcPrefix, @TableName);
    call MobilinkSetup_ExecuteStatement(@Command);

    set @Command = MobilinkSetup_CreateUpdateTable(@ProcPrefix, @TableName);
    call MobilinkSetup_ExecuteStatement(@Command);

    set @Command = MobilinkSetup_CreateDeleteTable(@ProcPrefix, @TableName);
    call MobilinkSetup_ExecuteStatement(@Command);

    set @Resultaat = 'Tabel in Mobilink opgenomen';
  end for;

  call MobilinkSetup_ExecuteStatement('', 0);

end;


create or replace procedure MobilinkSetup_CreatePublication(
  in @VtbGid_tabelnames smallint,
  in @ProcPrefix nchar(100),
  in @PublicationName nchar(100),
  in @WithUsing smallint //0 = no, 1 = yes
)
begin
  declare @command long nvarchar;
  declare @TableListForPublication long nvarchar = '';
  declare @FieldsList long nvarchar;

  call MobilinkSetup_ExecuteStatement('Create publication ' || @PublicationName, 0);

  set @command = 'IF EXISTS(SELECT FIRST 1 FROM SYS.SYSPUBLICATION WHERE publication_name = ''' +@PublicationName + ''') then \x0D\x0A' +
    '  DROP PUBLICATION ' + @PublicationName + ';\x0D\x0A' +
    'END IF;\x0D\x0A\x0D\x0A';
  set @command = @command + 'CREATE PUBLICATION ' + @PublicationName;
  if @WithUsing = 1 then
    set @command = @command + ' WITH SCRIPTED UPLOAD';
  end if;

  set @command = @command + '(\x0D\x0A';

  for @Cursor AS CURSOR_TablesForPublication CURSOR FOR
    select VtbiCode @TableName
    from   tabVrijeTabelItems
    where  VtbiVtbGid = @VtbGid_tabelnames
       and VtbiOmschrijving = ''
    order by VtbiCode
  for read only
  do
    select list(mlFieldName, ', ' order by mlFieldId) into @FieldsList from Mobilink_lib_GetFieldsList(@TableName);

    set @TableListForPublication = @TableListForPublication + if @TableListForPublication = '' then '' else ',\x0D\x0A' endif +
      '  TABLE KingSystem.' + @TableName + '(' + @FieldsList + ')\x0D\x0A';
    if @WithUsing = 1 then
      set @TableListForPublication = @TableListForPublication +
        '    USING (\x0D\x0A' +
        '      PROCEDURE KingSystem.MobilinkReplication_' + @TableName +'_insert FOR UPLOAD INSERT,\x0D\x0A' +
        '      PROCEDURE KingSystem.MobilinkReplication_' + @TableName +'_update FOR UPLOAD UPDATE,\x0D\x0A' +
        '      PROCEDURE KingSystem.MobilinkReplication_' + @TableName +'_delete FOR UPLOAD DELETE\x0D\x0A' +
        '    )\x0D\x0A';
      end if;
  end for;

  set @command = @command + @TableListForPublication;
  set @command = @command +')';

  call MobilinkSetup_ExecuteStatement(@command, 1 /*With batch*/);

  call MobilinkSetup_ExecuteStatement('', 0);

end;


create or replace function MobilinkSetup_CreateUpdateTable(
  in @ProcPrefix nchar(100),
  in @TableName nchar(128)
)
returns long nvarchar
begin
  declare @Pre_prefix nchar(100) = 'preimage_';
  declare @Post_prefix nchar(100) = 'postimage_';

  declare @command long nvarchar;

  declare @FieldDeclaresPre  long nvarchar;
  declare @FieldDeclaresPost long nvarchar;
  declare @FieldListPre      long nvarchar;
  declare @FieldListPost     long nvarchar;
  declare @PKeyList          long nvarchar;

    select
      list(ALL @Pre_prefix  + mlFieldName + ' '  + mlFieldType            , ', \x0D\x0A  ' order by mlFieldId),
      list(ALL @Post_prefix + mlFieldName + ' '  + mlFieldType            , ', \x0D\x0A  ' order by mlFieldId),
      list(ALL mlFieldName + ' ' + @Pre_prefix  + mlFieldName             , ', \x0D\x0A  ' order by mlFieldId),
      list(ALL mlFieldName + ' ' + @Post_prefix + mlFieldName             , ', \x0D\x0A  ' order by mlFieldId),
      list(ALL (if mlIsPrimaryKey = 1 then mlFieldName endif), ', ' order by mlFieldId)
    into @FieldDeclaresPre, @FieldDeclaresPost, @FieldListPre, @FieldListPost, @PKeyList
    from Mobilink_lib_GetFieldsList(@TableName);

  set @command =
    'CREATE OR REPLACE PROCEDURE KingSystem.' + @ProcPrefix + @TableName + '_update() \x0D\x0A' +
    'RESULT(\x0D\x0A  ' + @FieldDeclaresPre + ', \x0D\x0A  ' + @FieldDeclaresPost + ')\x0D\x0A' +
    'BEGIN \x0D\x0A' +
    '  SELECT first \x0D\x0A  ' + @FieldListPre + ', \x0D\x0A  ' + @FieldListPost + '\x0D\x0A' +
    '  FROM KingSystem.' + @TableName + '\x0D\x0A' +
    '  ORDER BY ' + @PKeyList + '\x0D\x0A' +
    'END';

  return @command;
end;



create or replace function MobilinkSetup_CreateUserForMobilinkLogin()
returns nchar(80)  // Username
begin
  declare @command long nvarchar;
  declare @UserName nchar(80);
  declare @Password nchar(80);


  select KingDbUserName, KingDbUserPassword
  into @UserName, @Password
  from MobilinkSetup_GetVrijeRubrieken();


  call MobilinkSetup_ExecuteStatement('Create user ' || @UserName, 0);

  call MobilinkSetup_ExecuteStatement(
    'IF EXISTS(SELECT FIRST 1 FROM sys.sysuser WHERE user_name = ''' || @UserName || ''') THEN\x0D\x0A' ||
      'DROP USER ' || @UserName || '\x0D\x0A' +
    'END IF'
  );

  call MobilinkSetup_ExecuteStatement('CREATE USER ' || @UserName || ' IDENTIFIED BY "' || @Password + '"');
  call MobilinkSetup_ExecuteStatement('COMMENT ON USER "' || @UserName || '" IS "MobiLink user #22900357"');  //Nummer staat er allee bij om commentaar te kunnen herkennen om gebruiker weg te kunnen gooien
  call MobilinkSetup_ExecuteStatement('GRANT ROLE SYS_RUN_REPLICATION_ROLE TO ' || @UserName);
  // Alle replication users van DBA afhalen
  call MobilinkSetup_ExecuteStatement('REVOKE ROLE SYS_AUTH_DBA_ROLE FROM SYS_RUN_REPLICATION_ROLE');
  // Security breach: Geef Mobilink remote DBA rechten! Dit is helaas nodig om o.a. sys.syssync te kunnen lezen
  call MobilinkSetup_ExecuteStatement('GRANT REMOTE DBA TO ' || @UserName);
  call MobilinkSetup_ExecuteStatement('GRANT EXECUTE ON sa_app_register TO SYS_RUN_REPLICATION_ROLE');
  call MobilinkSetup_ExecuteStatement('GRANT EXECUTE ON sa_start_recording_commits TO SYS_RUN_REPLICATION_ROLE');
  call MobilinkSetup_ExecuteStatement('GRANT EXECUTE ON sa_stop_recording_commits TO SYS_RUN_REPLICATION_ROLE');
  call MobilinkSetup_ExecuteStatement('GRANT EXECUTE ON sa_sync_sub TO SYS_RUN_REPLICATION_ROLE');

  call MobilinkSetup_ExecuteStatement('', 0);

  return @UserName;
end;


create or replace procedure MobilinkSetup_CreateUserForMobilinkServer()
begin
  declare @ServerUserName nchar(80);

  select  ServerUserName
  into   @ServerUserName
  from   MobilinkSetup_GetVrijeRubrieken();

  call MobilinkSetup_ExecuteStatement('Create user ''' || @ServerUserName || ''' for Mobilink Server', 0);

  call MobilinkSetup_ExecuteStatement('IF NOT EXISTS(	SELECT FIRST 1	FROM sys.syssync WHERE site_name = ''' + @ServerUserName + ''') THEN ' +
    'CREATE SYNCHRONIZATION USER "' || @ServerUserName ||'" ' +
    'END IF');

  call MobilinkSetup_ExecuteStatement('', 0);

end;


create or replace procedure MobilinkSetup_ExecuteStatement(
  in @command long nvarchar,
  in @Mode smallint default 2 //-1 = initialisation, 0 = Comment only, 1 = with batch, 2 = without batch
)
begin

  if @Mode in (-1 /*init*/, 0 /*comment*/) and locate(@command, '\x0D') = 0 and locate(@command, '\x0A') = 0 and @command <> '' then
    set @command = '//' + @command;
  end if;

  //call trace(@Command);

  begin
    declare @OutputToFile nchar(250);
    declare @FonGid integer;

    select FonGid into @FonGid from tabFileOfNaw where FonId = 'B';
    select first DebugOutputFile
    into @OutputToFile
    from VrGetContent('NAW', @FonGid, @FonGid, 'DebugOutputFile', '', '')
       WITH (
         VrRecordId      integer,
         DebugOutputFile nchar(250)
       );

    if @Mode = -1 then
      unload
        select '//Init'
        to @OutputToFile
        QUOTE ''
        FORMAT text
        ESCAPES off
        DELIMITED BY ''
    end if;

    if isnull(@OutputToFile, '') <> '' then
      unload
        select @Command || if @command <>'' then ';\x0D\x0A' endif
        to @OutputToFile
        QUOTE ''
        FORMAT text
        ESCAPES off
        DELIMITED BY ''
        APPEND ON ;
    end if;

  exception
    when others then
      if not exists(select first 1 where ERROR_SQLCODE() = -20679 /*RUbriek not found*/) then
        resignal;
      end if;
  end;

  case @Mode
    when 1 then // with batch
      execute immediate with result set off @command;
    when 2 then // without batch
      execute immediate with batch off with result set off @command;
  end case;

end;


create or replace procedure MobilinkSetup_GetVrijeRubrieken()
result
(
  FonGid                  integer,
  VrRecordId              integer,
  PublicationNameFull     nchar(80),
  PublicationNameLog      nchar(80),
  SubscriptionNameFull    nchar(80),
  SubscriptionNameLog     nchar(80),
  KingDbUserName          nchar(80),
  KingDbUserPassword      nchar(80),
  ServerUserName          nchar(80),
  ServerAddress           nchar(80),
  ServerConnectionType    nchar(80),
  VrijeTabelTables        nchar(10),
  Result                  nchar(250)
)
begin
  declare @FonGid integer;

  select FonGid into @FonGid from tabFileOfNaw where FonId = 'B';

  select first
    @FonGid FonGid,
    VrRecordId,
    Mobilink_lib_FormatToValidName(PublicationNameFull),
    Mobilink_lib_FormatToValidName(PublicationNameLog),
    Mobilink_lib_FormatToValidName(SubscriptionNameFull),
    Mobilink_lib_FormatToValidName(SubscriptionNameLog),
    Mobilink_lib_FormatToValidName(MobiLinkKingDbUserName),
    Mobilink_lib_FormatToValidName(MobiLinkKingDbUserPassword),
    Mobilink_lib_FormatToValidName(MobilinkServerUserName),
    Mobilink_lib_FormatToValidName(MobilinkServerAddress),
    Mobilink_lib_FormatToValidName(MobilinkServerConnectionType),
    Mobilink_lib_FormatToValidName(MobilinkVrijeTabel_Tables),
    MobilinkResult
  from VrGetContent('NAW', @FonGid, @FonGid,
    'MobilinkPublicationName_Full\n' ||
    'MobilinkPublicationName_Log\n' ||
    'MobilinkSubscriptionName_Full\n' ||
    'MobilinkSubscriptionName_Log\n' ||
    'MobilinkKingDbUserName\n' ||
    'MobilinkKingDbUserPassword\n' ||
    'MobilinkServerUserName\n' ||
    'MobilinkServerAddress\n' ||
    'MobilinkServerConnectionType\n' ||
    'MobilinkVrijeTabel_Tablenames\n' ||
    'MobilinkResult'
    , '', '')
       WITH (
         VrRecordId                   integer,
         PublicationNameFull          nchar(80),
         PublicationNameLog           nchar(80),
         SubscriptionNameFull         nchar(80),
         SubscriptionNameLog          nchar(80),
         MobiLinkKingDbUserName       nchar(80),
         MobiLinkKingDbUserPassword   nchar(80),
         MobilinkServerUserName       nchar(80),
         MobilinkServerAddress        nchar(80),
         MobilinkServerConnectionType nchar(80),
         MobilinkVrijeTabel_Tables    nchar(10),
         MobilinkResult               nchar(250)
       );
end;


create or replace procedure MobilinkSetup_GrantAccessToTablesForUser(
  in @VtbGid_tabelnames smallint,
  in @ProcPrefix nchar(40),
  in @UserName nchar(80)
)
begin
  call MobilinkSetup_ExecuteStatement('Grant access to tables', 0);

  // Toegang geven tot alle procedures t.b.v. replication
  for @Cursor AS CURSOR_Mobilink_GrantAccessToTables CURSOR FOR
    select VtbiCode @TableName
    from   tabVrijeTabelItems
    where  VtbiVtbGid = @VtbGid_tabelnames
       and VtbiOmschrijving = ''
    order by VtbiCode
  for read only
  do
    call MobilinkSetup_ExecuteStatement('GRANT SELECT ON KingSystem.' || @tableName || ' to "' || @UserName || '"');
    call MobilinkSetup_ExecuteStatement('GRANT EXECUTE ON KingSystem.' || @ProcPrefix || @TableName || '_insert TO SYS_RUN_REPLICATION_ROLE');
    call MobilinkSetup_ExecuteStatement('GRANT EXECUTE ON KingSystem.' || @ProcPrefix || @TableName || '_update TO SYS_RUN_REPLICATION_ROLE');
    call MobilinkSetup_ExecuteStatement('GRANT EXECUTE ON KingSystem.' || @ProcPrefix || @TableName || '_delete TO SYS_RUN_REPLICATION_ROLE');
  end for;

  call MobilinkSetup_ExecuteStatement('', 0);
end;


create or replace procedure MobilinkSetup_SubscribeUserToPublication(
  in @PublicationSyncName nchar(80),
  in @SubscriptionSyncName nchar(80),
  in @ScriptVersion nchar(40)
)
begin
  declare @ServerUserName       nchar(80);
  declare @ServerAddress        nchar(250);
  declare @ServerConnectionType nchar(250);

  call MobilinkSetup_ExecuteStatement('Create subscription ' || @SubscriptionSyncName, 0);

  select  ServerUserName, ServerAddress,  ServerConnectionType
  into   @ServerUserName, @ServerAddress, @ServerConnectionType
  from   MobilinkSetup_GetVrijeRubrieken();

  call MobilinkSetup_ExecuteStatement('IF EXISTS(SELECT FIRST 1 FROM sys.syssyncsubscriptions WHERE publication_name = ''' || @PublicationSyncName || ''') THEN ' ||
    'DROP SYNCHRONIZATION SUBSCRIPTION ' || @SubscriptionSyncName ||
    ' END IF');

  call MobilinkSetup_ExecuteStatement('CREATE SYNCHRONIZATION SUBSCRIPTION ' || @SubscriptionSyncName ||
    ' TO "' || @PublicationSyncName || '"' ||
    ' FOR "' || @ServerUserName || '" ' ||
    ' TYPE ' || @ServerConnectionType ||
    ' ADDRESS ''' || @ServerAddress ||'''' ||
    ' OPTION uo=''on'', SendTriggers=''on'', LockTables=''off''' || // Update only
    ' SCRIPT VERSION ''' || @ScriptVersion ||''''
  );

  call MobilinkSetup_ExecuteStatement('', 0);
end;


create or replace procedure Mobilink_ExportTableList()
begin
  declare @Filename nchar(250);
  declare @json long nvarchar = '';
  declare @FieldDeclares long nvarchar;
  declare @VtbGid_tabelnames smallint;

    declare @FonGid integer;
    declare @VrRecordId integer;
  // Read Filename from Vrije Rubrieken
  begin
    declare @VrijeTabelTables nchar(40);

    select FonGid into @FonGid from tabFileOfNaw where FonId = 'B';
    select first VrRecordId,
      TableListExportFilename
    into @VrRecordId, @Filename
    from VrGetContent('NAW', @FonGid, @FonGid,
      'MobilinkTableListExportFilename' , '', '')
         WITH (
           VrRecordId                   integer,
           TableListExportFilename      nchar(250)
         );
//  exception
//    when others then
//      set @Filename = null;
      ;// Niks doen...


    select  VrijeTabelTables
    into   @VrijeTabelTables
    from   MobilinkSetup_GetVrijeRubrieken();

    if isnull(@VrijeTabelTables, '') = '' then
      call Raise(20700, _U('Vrije rubriek %1! (leeg/niet gevonden)', 'MobilinkVrijeTabel_Tablenames')); //(20700) Ongeldige waarde: %1!
    end if;
    if isnumeric(@VrijeTabelTables) = 0 then
      call Raise(20700, _U('Vrije rubriek %1! (geen getal)', 'MobilinkVrijeTabel_Tablenames')); //(20700) Ongeldige waarde: %1!
    end if;
    if @VrijeTabelTables < 0 or @VrijeTabelTables > 999 then
      call Raise(20700, _U('Vrije rubriek %1! (niet tussen 1 en 999)', 'MobilinkVrijeTabel_Tablenames')); //(20700) Ongeldige waarde: %1!
    end if;

    select first VtbGid into @VtbGid_tabelnames from tabVrijeTabel where VtbNummer = @VrijeTabelTables;

    if @VtbGid_tabelnames is null then
      call Raise(20700, _U('Vrije rubriek %1! (niet gevonden)', 'MobilinkVrijeTabel_Tablenames')); //(20700) Ongeldige waarde: %1!
    end if;

  end;
  set @Filename = replace(@Filename, '\\', '\\\\');
  set @Filename = replace(@Filename, '''', '''''');

    call Mobilink_UpdateVrijeTabel(@VtbGid_tabelnames, 0);

    call VrWaardeWijzigen('NAW', @FonGid, @FonGid, @VrRecordId, 'MobilinkResult', 'Json file: ' || @Filename || ' creating on ' || now());

  if @Filename is not null then

    set @json = '{\x0D\x0A\x09"tables":[\x0D\x0A';
    for @Cursor AS CURSOR_Mobilink_ExportTableDefinitionsToJson CURSOR FOR
      select VtbiGid @VtbiGid, VtbiCode @TableName
      from   tabVrijeTabelItems
      where  VtbiVtbGid = @VtbGid_tabelnames
         and VtbiOmschrijving not like 'fout%'
      order by VtbiCode
    for read only
    do

      set @FieldDeclares = null;
      select
        list(ALL '{"name": "' || mlFieldName || '", "type": "'  || mlFieldType || '"' || if mlIsPrimaryKey = 1 then ', "isprimary": "true"' endif, '},\x0D\x0A\x09\x09\x09\x09' order by mlFieldId)
      into @FieldDeclares
      from Mobilink_lib_GetFieldsList(@TableName);

      if isnull(@FieldDeclares, '') <> '' then
        set @json = @json || '\x09\x09{\x0D\x0A\x09\x09\x09"name": "' || @TableName || '",\x0D\x0A\x09\x09\x09"Fields":[\x0D\x0A\x09\x09\x09\x09' ||
         @FieldDeclares || '}\x0D\x0A\x09\x09\x09]\x0D\x0A\x09\x09},\x0D\x0A';
      end if;

    end for;

    // Laatste komma en CrLf verwijderen en einde json toevoegen
    set @json = substring(@json, 1, length(@json) - 3) || '\x0D\x0A\x09]\x0D\x0A}';
    unload
      select @json
      to @Filename
      QUOTE ''
      FORMAT text
      ESCAPES off
      DELIMITED BY '';
  end if;
end;


create or replace function Mobilink_lib_FormatToValidName(
  in @s nchar(250),
  in @ValidChars nchar(100) default 'abcdefghijklmnopqrstuvwxyz1234567890-+_=!@#$%^&*()<>,./?'';:'
)
returns nchar(250)
begin
  declare @so nchar(250);
  declare @teller integer;
  declare @c nchar(1);

  // Remove double quote
  set @s = isnull(replace(@s, '"', ''), '');
  // Only keep these chars
  set @teller = 1;
  loop
    if @teller > length(@s) then
      leave;
    end if;
    set @c = substring(@s, @teller, 1);
    if charindex(@c, @ValidChars) <> 0 then
      set @so = @so + @c;
    end if;
    set @teller = @teller + 1;
  end loop;

  // Single quote to 2 single quotes
  set @s = replace(@s, '''', '''''');
  return @so;
end;


create or replace procedure Mobilink_lib_GetFieldsList(in @TableName nchar(128))
result (
  mlTableName nchar(128),
  mlFieldId integer, //nchar(100),
  mlFieldName nchar(100),
  mlFieldType nchar(100),
  mlIsPrimaryKey smallint,
  mlFieldSpecs nchar(100)
)
begin
  select

      Tdeze.Table_Name,

      column_id,
/*
     (if Cdeze.pkey='Y' then '0' else  '1' endif) + // First: Primary key
     (if exists(
        select first 1 from SYS.SYSFOREIGNKEY FK
        inner join sys.systable Tandere on Tandere.table_id = FK.primary_table_id
        inner join sys.syscolumn Candere on cAndere.table_id = FK.primary_table_id and Candere.pkey = 'Y'
        where FK.foreign_table_id = Tdeze.table_id and Cdeze.pkey = 'N' and role like '%' + Cdeze.column_name + '%'
      ) then '1' else '0' endif)+ // Next: Foreign keys
     Cdeze.column_name,
*/
     Cdeze.column_name,

     domain_name +
     if domain_name like '%char' and Cdeze.width between 1 and 32766 then '(' + string(Cdeze.width) + ')' else '' endif  + /* char length */
     if domain_name = 'numeric' then '(' + string(Cdeze.width) + ',' + string(Cdeze.scale) + ')' else '' endif, /* Numeric width and precision */

     if Cdeze.pkey='Y' then 1 else 0 endif,

     if Cdeze.pkey='Y' then 'Primary key' else '' endif
  from
    sys.systable Tdeze
    inner join  sys.syscolumn Cdeze on Cdeze.table_id = Tdeze.table_id
    inner join sys.sysDomain on sys.sysDomain.domain_id = Cdeze.domain_id
      where Tdeze.table_name = @TableName;
end;


create or replace procedure Mobilink_UpdateVrijeTabel(
  in @VtbGid_tabelnames smallint,
  in @Doel smallint default 1 //0 = Herken fouten, laat de rest ongemoeid; 1 = Herken fouten, maak de rest leeg; 2 = Drop mobilink; 3 = Maak alles leeg
)
begin
  declare _DOEL_Read smallint = 0; // Foute tabellen worden/blijven fout, omschrijving van goede tabellen blijven zoals ze zijn
  declare _DOEL_ResetOmschrijving smallint = 1; // Foute tabellen worden/blijven fout, omschrijving van goede tabellen worden leeg
  declare _DOEL_Drop smallint = 2; // Meldt dat Mobilink is gedropt
  declare _DOEL_Clear smallint = 3; // Alle omschrijvingen wordt leeggemaakt
  update tabVrijeTabelItems
  set    VtbiOmschrijving =
           if @Doel = _DOEL_Clear then
             ''
           else
             if not exists(select first 1 from sys.systable where table_name = VtbiCode) then
              _A('Fout: Tabel is niet gevonden! (%1!)', now())
             else
               if  (VtbiCode like '%''%')
                or (VtbiCode like '% %')
                or (VtbiCode like '%\n%')
                or (VtbiCode like '%.%')
                or (VtbiCode like '%;%')
                or (VtbiCode like '%)%')
                or (VtbiCode like '%(%')
                or (VtbiCode like '%"%') then
                _A('Fout: Tabelnaam is onjuist! (%1!)', now())
               else
                if substr(VtbiCode, 1, 3) <> 'tab' then
                  _A('Fout: Tabelnaam moet met TAB beginnen! (%1!)', now())
                 else
                   if VtbiCode in ('tabLicentie',
                                   'tabLicentieChecksum',
                                   'tabLicentieChecksumOptiesCommercieel',
                                   'tabLicentieOptiesCommercieel',
                                   'tabLicMask',
                                   'tabLogLicentie',
                                   'tabModule',
                                   'tabOptiesCommercieel',
                                   'tabProcedure',
                                   'tabUserExtern',
                                   'tabWebserviceVasteGegevens'
                                   ) then
                    _A('Fout: Geen rechten op deze tabel! (%1!)', now())
                   else
                     case @Doel
                       when _DOEL_ResetOmschrijving then '' // Mag worden opgenomen!
                       when _DOEL_Drop then 'Mobilink is verwijderd'
                       else VtbiOmschrijving
                     end //case
                   endif
                 endif
               endif
             endif
            endif
  where  VtbiVtbGid = @VtbGid_tabelnames;
end;


//----------------------------------------------------------------------------------------------------------------------------
// Maakt obv de normale tabelnaam een storedproc voor de _HIST tabel waarmee de verschillen per mutatie inzichtelijk gemaakt worden
//----------------------------------------------------------------------------------------------------------------------------
create or replace procedure MutatieLog_AddProcHistTable(in @TableName nchar(128), in @PrimKeyVeldParam nchar(128) default '')
begin
  declare @Statement long nvarchar;
  declare @StatementSP long nvarchar;
  declare @ColNames    long nvarchar; // AdrNaam1_OldValue, AdrNaam1_NewValue, AdrNaam2_OldValue, AdrNaam2_NewValue
  declare @ColNamesInject long nvarchar; // Values above if any and prepped for insertion, otherwise empty string
  declare @InsertsTmpTable long nvarchar;
  declare @CRLF nchar(2);
  declare @HistPostfix nchar(10);
  declare @ProcName nchar(128);
  declare @IndexName nchar(128);
  declare @Hist_TableName nchar(128);
  declare @PrimaryKeyVeld nchar(128);
  declare @ForeignKeyVeld nchar(128);
  declare @ForeignKeyVeldHist nchar(128);
  declare @UserId nchar(255);
  declare @IsVR smallint default 0;

  //Datatypes overgenomen uit SYSCOLUMN en SYSCOLUMNS.
  declare @ColName nchar(128);
  declare @Pkey nchar(1);
  declare @ColType nchar(128);
  declare @Length smallint;
  declare @Decimals smallint;
  declare @AllowNulls nchar(1);
  declare @In_primary_key nchar(1);
  declare @ColNo unsigned int;

  declare cursor_VIEWCOL dynamic scroll cursor for
    select column_name, pkey, coltype, length, scale, col.nulls, in_primary_key, colno
    from sys.syscolumn col
    inner join sys.systable tab on tab.table_id = col.table_id
    inner join sys.syscolumns col2 on col2.tname = tab.table_Name and col2.cname = col.column_name
    where tab.Table_Name = Upper(@TableName)
    order by colno;

  //call Trace('MutatieLog_AddProcHistTable Table='+string(@TableName));

  set @CRLF = nchar(13);
  set @HistPostfix = '_HIST';
  set @Hist_TableName = @TableName + @HistPostFix;
  set @ProcName = 'sp_'+@Hist_TableName;

  if @PrimKeyVeldParam <> '' then  // Vanuit MutatieLog_EnableTable meegegeven
    set @PrimaryKeyVeld = @PrimKeyVeldParam;
    //call Trace('MutatieLog_CreateProc: param set @PrimaryKeyVeld='+string(@PrimaryKeyVeld));
  else
    select column_name into @PrimaryKeyVeld
    from sys.syscolumn col
    inner join sys.systable tab on tab.table_id = col.table_id
    inner join sys.syscolumns col2 on col2.tname = tab.table_Name and col2.cname = col.column_name
    where tab.Table_Name = @TableName
    and in_primary_key = 'Y'
  end if; // End @PrimaryKeyVeld = ''

  // De foreignkey veldnaam en de select voor de identifier vullen
  select MutFKVeld, MutUserId into @ForeignKeyVeld, @UserId from tabMutatieLogTabel where MutTabelNaam = @TableName;
  // is het een vrije rubriek dan hebben we alleen de prefix en weten we dat ie eindigt op RecordId, de veldnaam dan ophalen uit syscolumns
  if @ForeignKeyVeld is null then
    if exists(select 1 from tabMutatieLogTabel where @TableName like MutTabelNaam+'%' and MutIsPrefix = 1) then
       select column_name into @ForeignKeyVeld
       from sys.syscolumn col
       inner join sys.systable tab on tab.table_id = col.table_id
       inner join sys.syscolumns col2 on col2.tname = tab.table_Name and col2.cname = col.column_name
       where tab.Table_Name = @TableName and column_name like (select MutFKVeld from tabMutatieLogTabel where @TableName like MutTabelNaam+'%' and MutIsPrefix = 1) || '%' || 'RecordId';
       set @IsVR = 1;
    end if;
    // Als we een VR tabel hebben dan is de UserId statement nog niet opgehaald want die was obv volledige tabelnaam. Dan als volgt ophalen
    if @IsVr = 1 then
      select MutUserId into @UserId from tabMutatieLogTabel where @TableName like MutTabelNaam+'%' and MutIsPrefix = 1;
      //call Trace('VR!!  >> @TableName='+string(@TableName)+'; @UserId='+string(@UserId));
    end if;
  end if;

  if @ForeignKeyVeld is null then
    set @ForeignKeyVeld = 'null';
    set @ForeignKeyVeldHist = 'null';
  else
    set @ForeignKeyVeldHist = @ForeignKeyVeld + @HistPostfix;
  end if;
  //call Trace('MutatieLog_CreateProc: FkVeld='+string(@ForeignKeyVeld));

  if @UserId is null then
    set @UserId = 'null';
  end if;

  //call Trace('MutatieLog_CreateProc: IsVR='+string(@IsVR));

  //FASE 5: Proc maken waar je de history makkelijk mee kan zien. Dit wordt een grote union van de verschillen per Veld.
  //We maken dus eerst weer een loop over het aantal velden in de main-tabel.
  set @Statement = 'set temporary option string_rtruncation = ''On''';
  execute immediate @Statement;

  open cursor_VIEWCOL WITH HOLD;
    fetch next cursor_VIEWCOL into @ColName, @Pkey, @ColType, @Length, @Decimals, @AllowNulls, @In_Primary_Key, @ColNo;
    while @@sqlstatus = 0 loop
      //call Trace('Fase 5: Col: '+ @ColName);

    //De verschillen van 1 record worden uiteraard bepaald adhv 1 primarykey-waarde. Het primarykey-veld zelf hoeft
    // dus niet opgenomen te worden als 'select' dus die wordt overgeslagen.
    // Ook een evt LastModified overslaan
    if (@ColName <> @PrimaryKeyVeld) and (Right(@ColName, Length('LastModified')) <> 'LastModified') and (@ColName <> 'ArtTimeStamp')  then

      set @ColNames = @ColNames + ', ' + @ColName+'_OldValue, '+@ColName+'_NewValue';
      if @ColType = 'long nvarchar' or @ColType = 'long varchar' then
        set @StatementSP = @StatementSP + ', ' + @CRLF +
         '          cast(string(' + @ColName + @HistPostfix  +') as long nvarchar)              '+@ColName+'_OldValue, ' + @CRLF +
         '          last_value('+@ColName+'_OldValue)                 over VolgendeMutatie    '+@ColName+'_NewValue';
      else
        set @StatementSP = @StatementSP + ', ' + @CRLF +
         '          cast(left(' + @ColName + @HistPostfix  +' , 255) as nchar(255))              '+@ColName+'_OldValue, ' + @CRLF +
         '          last_value('+@ColName+'_OldValue)                 over VolgendeMutatie    '+@ColName+'_NewValue';
      end if;

      set @InsertsTmpTable = @InsertsTmpTable + @CRLF +
        '      if (('+@ColName+'_OldValue is not null and '+@ColName+'_NewValue is null) or ('+@ColName+'_OldValue is null and '+@ColName+'_NewValue is not null) or ('+@ColName+'_NewValue <> '+@ColName+'_OldValue)) then ' + @CRLF +
        '        set @FkUserId = null; ' + @CRLF +
        '        select TAndere.table_name FkTabel, CAndere.column_name FkColumn, (select MutFKBronUserId from tabMutatieLogTabel where MutTabelnaam = TAndere.table_name) FkUserId into @FKTabel, @FKColumn, @FKUserId from sys.syscolumn CDeze ' + @CRLF +
        '           key join sys.systable TDeze key join sys.sysDomain left outer join ' + @CRLF +
        '            (SYS.SYSFOREIGNKEY FK ' + @CRLF +
        '             inner join sys.systable Tandere on Tandere.table_id = FK.primary_table_id ' + @CRLF +
        '             inner join sys.syscolumn Candere on cAndere.table_id = FK.primary_table_id and Candere.pkey = \x27Y\x27 ' + @CRLF +
        '            ) on FK.foreign_table_id = CDeze.table_id  and Cdeze.pkey = \x27N\x27 and role like \x27%\x27 + Cdeze.column_name ' + @CRLF +
        '        where Cdeze.table_id = CDeze.table_id and TDeze.table_type = \x27BASE\x27 and CDeze.column_name = \x27' + @ColName + '\x27;' + @CRLF +
        '        select (if @FkUserId is not null then 1 else 0 endif) into @IsFk;' + @CRLF +
//          '      set @IsFK = 0; ' + @CRLF +
        '        insert into tmpMutaties (RecordGid, ForeignKeyGid, OldHistGid, NewHistGid, Id, Veld, OudeWaarde, NieuweWaarde, MutatieType, Wanneer, Gebruiker, Machine, Proces) values ' + @CRLF +
        '                                 (@BronRecGid, @BronFkGid, @OldHistGid, @NewHistGid, @UserId, \x27' + @ColName + '\x27, '+
        '   (if @IsFk = 1 then MutatieLog_GetUserIdFromForeignKey(@FkTabel, @FkColumn, @FkUserId, '+ @ColName+'_OldValue) else '+ @ColName+'_OldValue endif), '+
        '   (if @IsFk = 1 then MutatieLog_GetUserIdFromForeignKey(@FkTabel, @FkColumn, @FkUserId, '+ @ColName+'_NewValue) else '+ @ColName+'_NewValue endif), '+
        '1, @Wanneer, @Gebruiker, @Machine, @Proces); ' + @CRLF +
        '      end if; ' + @CRLF;
    end if;
    fetch next cursor_VIEWCOL into @ColName, @Pkey, @ColType, @Length, @Decimals, @AllowNulls, @In_Primary_Key, @ColNo;
    end loop;
  close cursor_VIEWCOL;

  set @ColNames = Right(@ColNames, Length(@ColNames)-2);
  //call Trace('@ColNames='+string(@ColNames));
  if @ColNames <> '' then
    set @ColNamesInject = ',' || @CRLF || '        '+Replace(@ColNames, ',', ','+@CRLF+'       ');
  else
    set @ColNamesInject = '';
  end if;
  set @StatementSP = 'create or replace procedure '+@ProcName+'(in @MutTypes smallint, in @VanafDatum date default null, in @TmDatum date default null, in @RecordGid integer default null, in @FkGid integer default null, in @VrId integer default null)' + @CRLF +
                     'begin '                                       + @CRLF +
                     '  declare local temporary table tmpMutaties ('+ @CRLF +
                     '    tmpGid        integer not null default autoincrement, ' + @CRLF +
                     '    RecordGid     integer, '                  + @CRLF +
                     '    ForeignKeyGid integer, '                  + @CRLF +
                     '    OldHistGid    integer, '                  + @CRLF +
                     '    NewHistGid    integer, '                  + @CRLF +
                     '    ID            nchar(255), '               + @CRLF +
                     '    Veld          nchar(100), '               + @CRLF +
                     '    OudeWaarde    long nvarchar, // nchar(255), '               + @CRLF +
                     '    NieuweWaarde  long nvarchar, //nchar(255), '               + @CRLF +
                     '    MutatieType   smallint, '                 + @CRLF +
                     '    Wanneer       datetime, '                 + @CRLF +
                     '    Gebruiker     nchar(40), '                + @CRLF +
                     '    Machine       nchar(40), '                + @CRLF +
                     '    Proces        nchar(100) '                + @CRLF +
                     ' ) on commit preserve rows; '                 + @CRLF +
                     @CRLF +
                     '  declare @EigenTabelNaam nchar(128) default \x27'+@TableName+'\x27;' + @CRLF +
                     '  declare @MaxTmpGid integer; '               + @CRLF +
                     '  declare @FKTabel   varchar(128); '          + @CRLF +
                     '  declare @FKColumn  varchar(128); '          + @CRLF +
                     '  declare @FKUserId  varchar(128); '          + @CRLF +
                     '  declare @IsFk      smallint;  '             + @CRLF +
                     '  declare @ShowInserts smallint default (if @MutTypes & 1 <> 0 then 1 else 0 endif); ' + @CRLF +
                     '  declare @ShowUpdates smallint default (if @MutTypes & 2 <> 0 then 1 else 0 endif); ' + @CRLF +
                     '  declare @ShowDeletes smallint default (if @MutTypes & 4 <> 0 then 1 else 0 endif); ' + @CRLF +

                     @CRLF +

                     //'  select RecordGid, OldHistGid, NewHistGid, '+@ColNames+', Gebruiker, Machine, Wanneer, Proces from ( ' + @CRLF +
                     '  if @ShowUpdates = 1 then '                  + @CRLF +
                     '    for @Cursor AS Cursor_Mutaties CURSOR for ' + @CRLF +
                     '      select '                                 + @CRLF +
                     '        BronRecGid @BronRecGid, '              + @CRLF +
                     '        BronFkGid  @BronFkGid, '               + @CRLF +
                     '        OldHistGid @OldHistGid, '              + @CRLF +
                     '        NewHistGid @NewHistGid, '              + @CRLF +
                     '        Gebruiker  @Gebruiker, '               + @CRLF +
                     '        Machine    @Machine, '                 + @CRLF +
                     '        Wanneer    @Wanneer, '                 + @CRLF +
                     '        Proces     @Proces, '                  + @CRLF +
                     '        IsVR       @IsVR, '                    + @CRLF +
                     '        UserId     @UserId '                   + @CRLF +
                     @ColNamesInject + @CRLF +
                     '      from ( '                                 + @CRLF +

                     '        select ' + @CRLF +
                     '          '+@PrimaryKeyVeld + @HistPostfix+'                              BronRecGid, '  + @CRLF +
                     '          '+@ForeignKeyVeldHist+'                                         BronFkGid, '   + @CRLF +
                     '          '+@Hist_TableName + '_gid                                       OldHistGid, '  + @CRLF +
                     '          last_value(OldHistGid) over VolgendeMutatie                     NewHistGid, '  + @CRLF +
                     '          last_value('+@Hist_TableName+'_user)    over VolgendeMutatie    Gebruiker, '   + @CRLF +
                     '          last_value('+@Hist_TableName+'_machine) over VolgendeMutatie    Machine, '     + @CRLF +
                     '          last_value('+@Hist_TableName+'_date)    over VolgendeMutatie    Wanneer, '     + @CRLF +
                     '          last_value('+@Hist_TableName+'_appname) over VolgendeMutatie    Proces,'       + @CRLF +
                     '          ('+string(@IsVR)+') IsVR,'                                                     + @CRLF +
                     '          ('+@UserId+') UserId'                                                    +
                     @StatementSP;

  set @StatementSP = @StatementSP + @CRLF +
   '        from ' + @Hist_TableName + ', tabMutatieLogTabel ' +  @CRLF +
   '        where ' + @CRLF +
   '          (@VanafDatum is null or '+@Hist_TableName+'_date >= @VanafDatum) and ' + @CRLF +
   '          (@TmDatum is null or '+@Hist_TableName+'_date <= @TmDatum) and ' + @CRLF +
   '          (@RecordGid is null or '+@PrimaryKeyVeld + @HistPostfix+' = @RecordGid) and ' + @CRLF +
   '          (('+@ForeignKeyVeldHist+' is null or @FkGid is null) or ('+@ForeignKeyVeldHist+' = @FkGid)) and ' + @CRLF +
   '          ((MutIsPrefix = 0 and MutTabelNaam = \x27' + @TableName + '\x27 ) or (MutIsPrefix = 1 and \x27' + @TableName + '\x27 like MutTabelNaam + ''%'' )) ' + @CRLF +
   '        window VolgendeMutatie as (partition by '+@PrimaryKeyVeld + @HistPostfix+' order by '+@Hist_TableName + '_gid ROWS BETWEEN CURRENT ROW and 1 FOLLOWING )' + @CRLF;

  //set @StatementSP = @StatementSP + ' ) Derived where ((OldValue is not null and NewValue is null) or (OldValue is null and NewValue is not null) or (OldValue <> NewValue)) order by HistGid end; ' + @CRLF;
  set @StatementSP = @StatementSP + '    ) Derived order by NewHistGid ' + @CRLF +
      '    FOR READ ONLY '  + @CRLF +
      '    do '             + @CRLF +
      + @InsertsTmpTable    + @CRLF +
      '    end for; '       + @CRLF +
      '  end if; '          + @CRLF +
      + @CRLF +
      '  if @ShowInserts = 1 or @ShowDeletes = 1 then ' + @CRLF +
      '    // Alle inserts en deletes ook toevoegen ' + @CRLF +
      '    insert into tmpMutaties (RecordGid, ForeignKeyGid, OldHistGid, Id, Veld, OudeWaarde, NieuweWaarde, MutatieType, Wanneer, Gebruiker, Machine, Proces) ' + @CRLF +
      '    select distinct ' + @CRLF +
      '      '+@PrimaryKeyVeld + @HistPostfix+'                              BronRecGid, '           + @CRLF +
      '      '+@ForeignKeyVeldHist+'                                         BronFkGid, '            + @CRLF +
      '      '+@Hist_TableName + '_gid                                       OldHistGid, '           + @CRLF +
      '      ('+@UserId+') @UserId, '                                                                + @CRLF +
      '      ('''+@TableName+''')                                            TableName, '            + @CRLF +
      '      (if '+@Hist_TableName + '_mutatietype = 0 then '''' else @UserId endif) OudeWaarde, '   + @CRLF +
      '      (if '+@Hist_TableName + '_mutatietype = 2 then '''' else @UserId endif) NieuweWaarde, ' + @CRLF +
      '      '+@Hist_TableName + '_mutatietype, '  + @CRLF +
      '      '+@Hist_TableName+'_date, '           + @CRLF +
      '      '+@Hist_TableName+'_user, '           + @CRLF +
      '      '+@Hist_TableName+'_machine, '        + @CRLF +
      '      '+@Hist_TableName+'_appname'          + @CRLF +
      '    from ' + @Hist_TableName + ', tabMutatieLogTabel ' +  @CRLF +
      '    where ' + @CRLF +
      '      ((@ShowInserts = 1 and '+@Hist_TableName + '_mutatietype = 0) or (@ShowDeletes = 1 and '+@Hist_TableName + '_mutatietype = 2)) and '                 + @CRLF +
      '      (@VanafDatum is null or '+@Hist_TableName+'_date >= @VanafDatum) and '                                                                               + @CRLF +
      '      (@TmDatum is null or '+@Hist_TableName+'_date <= @TmDatum) and '                                                                                     + @CRLF +
      '      (@RecordGid is null or '+@PrimaryKeyVeld + @HistPostfix+' = @RecordGid) and '                                                                        + @CRLF +
      '      (('+@ForeignKeyVeldHist+' is null or @FkGid is null) or ('+@ForeignKeyVeldHist+' = @FkGid)) and '                                                    + @CRLF +
      '      ((MutIsPrefix = 0 and MutTabelNaam = \x27' + @TableName + '\x27 ) or (MutIsPrefix = 1 and \x27' + @TableName + '\x27 like MutTabelNaam + ''%'' )); ' + @CRLF +
      '  end if; ' + @CRLF +
      + @CRLF +
      '  //select count(1) into @MaxTmpGid from tmpMutaties; ' + @CRLF +
      '  //call Trace(''Count @MaxTmpGid=''+string(@MaxTmpGid)+''; @EigenTabelNaam=''+@EigenTabelNaam); ' + @CRLF +
      '  // Alleen als we een PK of FK hebben dan alle detail tabellen ook doorlopen ' + @CRLF +
      '  if not(@RecordGid is null and @FkGid is null) then ' + @CRLF +
      '    select max(tmpGid) into @MaxTmpGid from tmpMutaties; ' + @CRLF +
      '    // Loopen door de primary keys van de tabel waar we nu in zitten, eerst de historische en daarna de live' + @CRLF +
      '    for @Cursor AS CURSOR_PrimKeys CURSOR for' + @CRLF +
/*        '    select distinct ' + @CRLF +
      '        RecordGid @BronRecGid, ' + @CRLF +
      '        ForeignKeyGid  @BronFkGid ' + @CRLF +
      '      from tmpMutaties where tmpGid <= @MaxTmpGid ' + @CRLF + */
      '      select distinct @BronRecGid from ( ' + @CRLF +
      '        // De historische records doorlopen ' + @CRLF +
      '        select distinct ' + @CRLF +
      '          RecordGid @BronRecGid ' + @CRLF +
      '        from tmpMutaties where tmpGid <= @MaxTmpGid ' + @CRLF +
      '        union all ' + @CRLF +
      '        // en ook de live records ' + @CRLF +
      '        select ' + @CRLF +
      '         '+@PrimaryKeyVeld+' @BronRecGid ' + @CRLF +
      '        from '+@TableName+' where '+@ForeignKeyVeld+' = @FkGid ' + @CRLF +
      '        union all ' + @CRLF +
      '        // en het @RecordGid zelf in de selectie, voor geval bovenstaande niets oplevert maar er wel onderliggende mutaties zijn ' + @CRLF +
      '        select @RecordGid where @RecordGid is not null ' + @CRLF +
      '      ) Dummy ' + @CRLF +
      '    for read only' + @CRLF +
      '    do' + @CRLF +

      '      for @Cursor AS CURSOR_MutDetailTabel CURSOR for ' + @CRLF +
      '         select ' + @CRLF +
      '           if MutIsPrefix = 0 then ' + @CRLF +
      '             MutTabelNaam ' + @CRLF +
      '           else ' + @CRLF +
      '             MutTabelNaam + replicate( ''0'', 3-length( string( @VrId ) ) ) + string(@VrId) + replicate( ''0'', 3-length( string( @VrId ) ) ) + string(@VrId) ' + @CRLF +
      '           endif @TabelNaam '  + @CRLF +
      '         from tabMutatieLogTabel ' + @CRLF +
      '         where MutMasterTabel = @EigenTabelNaam order by MutProcVolgorde ' + @CRLF +

      '       for read only' + @CRLF +
      '       do' + @CRLF +
      '         // De storedproc aanroepen van alle tabellen die de huidige tabel als master hebbben, de PK als FK param gebruiken ' + @CRLF +
      '         //call Trace(''Detailtabel call @BronRecGid=''+string(@BronRecGid)+''; @TabelNaam=''+@TabelNaam); ' + @CRLF +
      '         if exists(select 1 from sysprocedure key join sysusers where name=\x27KINGSYSTEM\x27 and proc_name = \x27sp_'' + @TabelNaam + ''_HIST\x27) then ' + @CRLF +
      '           execute immediate ''insert into tmpMutaties (RecordGid, ForeignKeyGid, OldHistGid, NewHistGid, ID, Veld, OudeWaarde, NieuweWaarde, MutatieType, Wanneer, Gebruiker, Machine, Proces) ' + @CRLF +
      '                               select RecordGid, ForeignKeyGid, OldHistGid, NewHistGid, ID, Veld, OudeWaarde, NieuweWaarde, MutatieType, Wanneer, Gebruiker, Machine, Proces ' + @CRLF +
      '                               from sp_'' + @TabelNaam + ''_HIST(@MutTypes, @VanafDatum, @TmDatum, null, @BronRecGid, @VrId)''' + @CRLF +
      '         end if; ' + @CRLF +
      '       end for;' + @CRLF +
      '    end for;' + @CRLF+
      '  end if;' + @CRLF +

      '  select RecordGid, ForeignKeyGid, OldHistGid, NewHistGid, ID, Veld, OudeWaarde, NieuweWaarde, MutatieType, Wanneer, Gebruiker, Machine, Proces from tmpMutaties' + @CRLF +
  'end; ' + @CRLF;

  set @ProcName = 'd:\test\procs\'+@ProcName+'.sp';
  //unload select @StatementSP to @ProcName;

  //call Trace('Fase 5: Nieuwe proc opvoeren: '+ @ProcName);
  execute immediate @StatementSP;

  set @Statement = 'set temporary option string_rtruncation = ''Off''';
  execute immediate @Statement;

  //FASE 6: We maken een index op de voormalige primarykey in de historietabel.
  set @IndexName = 'Idx_'+@PrimaryKeyVeld + @HistPostFix;
  if exists(select 1 from sys.sysIndex where index_name=@IndexName) then
    //call Trace('Fase 6: Oude index verwijderen: '+ @IndexName);
    set @Statement = 'drop index '+ @IndexName;
    execute immediate @Statement;
  end if;
  set @Statement = 'create index ' + @IndexName + ' on ' + @Hist_TableName + '(' + @PrimaryKeyVeld + @HistPostFix+ ');';
  //call Trace('Fase 6: Nieuwe index toevoegen: ' + @IndexName);
  execute immediate @Statement;

  //FASE 6: We maken een index op de date in de historietabel.
  set @IndexName = 'Idx_'+@Hist_TableName+'_date';
  if exists(select 1 from sys.sysIndex where index_name=@IndexName) then
    //call Trace('Fase 6: Oude index verwijderen: '+ @IndexName);
    set @Statement = 'drop index '+ @IndexName;
    execute immediate @Statement;
  end if;
  set @Statement = 'create index ' + @IndexName + ' on ' + @Hist_TableName + '(' + @Hist_TableName+'_date);';
  //call Trace('Fase 6: Nieuwe index toevoegen: ' + @IndexName);
  execute immediate @Statement;
end;

//call MutatieLog_AddProcHistTable('tabAdres');
//call sp_tabAdres_HIST(null, null, null, 50360175);

create or replace procedure MutatieLog_DeleteAllHistProcsIndexes()
begin
  declare @PrimaryKeyVeld nchar(128);
  declare @IndexName      nchar(128);
  declare @ProcName       nchar(128);

  // Alle _HIST tables langslopen en evt aanwezige Procs en indexes verwijderen
  for @Cursor AS CURSOR_MutLog CURSOR for
      select
        table_name @TableName
      from systable
      where creator = (select uid from sysusers where name = 'KingSystem')
      and table_type = 'BASE'
      and (table_Name like '%\_HIST' escape '\')
      order by table_name

      FOR READ ONLY
    do
      // PK ophalen voor de indexnaam, is obv de brontabel dus _HIST postfix van de tablename strippen
      select column_name into @PrimaryKeyVeld
      from sys.syscolumn col
      inner join sys.systable tab on tab.table_id = col.table_id
      inner join sys.syscolumns col2 on col2.tname = tab.table_Name and col2.cname = col.column_name
      where tab.Table_Name = Left(@TableName, Length(@TableName)-5)
      and in_primary_key = 'Y';

      // Dag Index PK
      set @IndexName = 'Idx_'+@PrimaryKeyVeld+'_HIST';
      if exists(select 1 from sys.sysIndex where index_name=@IndexName) then
        //call Trace('Index verwijderen: '+ @IndexName);
        execute immediate 'drop index '+ @IndexName
      end if;

      // Dag Index date
      set @IndexName = 'Idx_'+@TableName+'_date';
      if exists(select 1 from sys.sysIndex where index_name=@IndexName) then
        //call Trace('Index verwijderen: '+ @IndexName);
        execute immediate 'drop index '+ @IndexName
      end if;

      // Dag Proc
      set @ProcName = 'sp_'+@TableName;
      if exists(select 1 from sys.sysprocedure where proc_name=@ProcName) then
        //call Trace('Proc verwijderen: '+ @ProcName);
        execute immediate 'drop procedure '+ @ProcName;
      end if;

      //call Trace('Table: ' + @TableName + '; Proc: ' + @ProcName + '; Index: ' + @IndexName);
    end for;
end;


//----------------------------------------------------------------------------------
//---------  Verwijdert alle historische gegevens voor een meegegeven --------------
//-----------     Hoofdgroep OF Subgroep obv een From EN/OF ToDate   ---------------
//----------------------------------------------------------------------------------
create or replace procedure MutatieLog_DeleteHistory(in @MuhGid integer, in @MugGid integer, in @FromDate datetime, in @ToDate datetime)
begin
  declare @Statement long nvarchar;

  //call Trace('@MuhGid='+string(@MuhGid)+ '; @MugGid='+string(@MugGid)+'; @FromDate='+string(@FromDate)+'; @ToDate='+string(@ToDate));
  for @Cursor AS CURSOR_MutLog CURSOR for
    select
      table_name @HistTabelNaam,
      @HistTabelnaam || '_date' @HistDateColumn
    from systable inner join (tabMutatieLogHoofdGroep
         inner join tabMutatieLogGroep on MugMuhGid = MuhGid
         inner join tabMutatieLogTabel on MutMugGid = MugGid
         ) on (table_name = MutTabelNaam || '_HIST') or ((MutIsPrefix = 1) and (Left(table_Name, Length(MutTabelNaam)) = MutTabelNaam))
    where creator = (select uid from sysusers where name = 'KingSystem')
    and table_type = 'BASE'
    and table_name like '%_HIST'
    and ((@MuhGid is not null and MuhGid = @MuhGid) or
         (@MugGid is not null and MugGid = @MugGid))
    order by MuhGid, MugGid, table_name

    FOR READ ONLY
  do
    //call Trace('Tablename: ' + string(@HistTabelNaam) + '; DateCol: ' + @HistDateColumn);
    set @Statement = '';
    if @FromDate is null and @ToDate is not null then
      set @Statement = 'delete ' || @HistTabelnaam || ' where ' || @HistDateColumn || ' < \x27' || @ToDate || '\x27'
    elseif @FromDate is not null and @ToDate is null then
      set @Statement = 'delete ' || @HistTabelnaam || ' where ' || @HistDateColumn || ' > \x27' || @FromDate || '\x27'
    elseif @FromDate is not null and @ToDate is not null then
      set @Statement = 'delete ' || @HistTabelnaam || ' where ' || @HistDateColumn || ' between \x27' || @FromDate || '\x27 and \x27' || @ToDate || '\x27'
    elseif @FromDate is null and @ToDate is null then
      set @Statement = 'delete ' || @HistTabelnaam
    end if;
    if @Statement <> '' then
      //call Trace('Executing: ' + string(@Statement));
      execute immediate @Statement;
    end if;
  end for;

end;


//Disablet voor alle tabellen binnen de groepen in de instellingen de mutatielogging
create or replace procedure MutatieLog_DisableAll()
begin
  for @Cursor AS CURSOR_MutLog CURSOR for
      select
        MugGid @MugGid
      from tabMutatieLogInstellingen inner join tabMutatieLogGroep on MuiMugGid = MugGid
      order by MugMuhGid, MugGid
      FOR READ ONLY
    do
      //call Trace('MutatieLog_DisableAll > MutatieLog_DisableGroup: '+string(@MugGid));
      call MutatieLog_DisableGroup(@MugGid);
    end for;
end;


//----------------------------------------------------------------------------------
//-----  Verwijdert de dynamische triggers voor alle tabellen binnen de groep ------
//----------------------------------------------------------------------------------
create or replace procedure MutatieLog_DisableGroup(in @MugGid integer, in @RemoveHISTTrigger smallint default 0)
begin
  for @Cursor AS CURSOR_MutLog CURSOR for
      select
        table_name @TabelNaam
      from systable
        inner join (tabMutatieLogHoofdGroep
        inner join tabMutatieLogGroep on MugMuhGid = MuhGid
        inner join tabMutatieLogTabel on MutMugGid = MugGid) on (table_name = MutTabelNaam) or ((MutIsPrefix = 1) and (Left(table_Name, Length(MutTabelNaam)) = MutTabelNaam))
      where creator = (select uid from sysusers where name = 'KingSystem')
      and table_type = 'BASE'
      and MuhGeblokkeerd = 0
      and not (table_Name like '%\_HIST' escape '\')
      and MugGid = @MugGid
      order by MuhGid, MugGid, table_name
      FOR READ ONLY
    do
      //call Trace('MutatieLog_DisableGroup > MutatieLog_DisableTable - '+string(@TabelNaam));
      call MutatieLog_DisableTable(@TabelNaam, @RemoveHISTTrigger);
    end for;
end;


//----------------------------------------------------------------
//-----  Verwijdert de dynamische triggers op de hoofdtabel ------
//----------------------------------------------------------------
create or replace procedure MutatieLog_DisableTable(in @TableName nchar(255), in @RemoveHISTTrigger smallint default 0)
begin
  declare @Statement long varchar;
  declare @TriggerName nchar(128);
  declare @HISTTriggerName nchar(128);
  declare @HistPostfix nchar(10);

  //call TraceBegin('MutatieLog_RemoveTrigger > @TableName = ' + @TableName);

  //Nieuwe tabel en veldnamen krijgen deze postfix:
  set @HistPostfix = '_HIST';

  //Input controles:
  if @TableName = '' then
    call Raise(17000, _U('Inputerror: Tabelnaam is verplicht!'));
  end if;
  if not exists(select 1 from systable where table_name = @TableName) then
    call Raise(17000, _U('Inputerror: Onbekende tabel: %1!', @TableName));
  end if;
  //Vve: Anti-verwarrings-beveiliging: De history tabellen hebben natuurlijk geen mutatie-logging-trigger.
  if right(@TableName, Length(@HistPostfix)) = @HistPostFix then
    call Raise(17000, _U('Inputerror: Beveiliging: Deze tabel is historisch! (%1!)', @TableName));
  end if;

  //call trace('Dyn-triggers verwijderen: '+ 'dt*a_' + @TableName + @HistPostfix);
  delete tabDynamicTriggers where DtName = 'dtia_' + @TableName + @HistPostfix;
  delete tabDynamicTriggers where DtName = 'dtua_' + @TableName + @HistPostfix;
  delete tabDynamicTriggers where DtName = 'dtda_' + @TableName + @HistPostfix;

  // Evt naast de dynamische triggers ook de ordinaire trigger op de _HIST tabel droppen
  if @RemoveHISTTrigger = 1 then
    set @HISTTriggerName = 'tb_'+@TableName+'_HIST';
    if exists(select 1 from systrigger where trigger_name = @HISTTriggerName) then
      //call trace('HIST-trigger verwijderen: '+ @HISTTriggerName);
      execute immediate 'drop trigger ' + @HISTTriggerName;
    end if;
  end if;

  //call TraceEind('MutatieLog_RemoveTrigger');
end;

//Obv tabMutatieLogInstellingen worden voor alle tabellen binnen de
//groepen die ingesteld staan de mutatielogging (weer) aangezet
create or replace procedure MutatieLog_EnableAll()
begin
  for @Cursor AS CURSOR_MutLog CURSOR for
      select
        MugGid @MugGid
      from tabMutatieLogInstellingen inner join tabMutatieLogGroep on MuiMugGid = MugGid
      order by MugMuhGid, MugGid
      FOR READ ONLY
    do
      //call Trace('MutatieLog_DisableAll > MutatieLog_EnableGroup: '+string(@MugGid));
      call MutatieLog_EnableGroup(@MugGid);
    end for;
end;


//----------------------------------------------------------------------------------
//---------  Stelt voor alle tabellen binnen de groep de historie in  --------------
-----------      als ze in de mutatielog instellingen staan           --------------
//----------------------------------------------------------------------------------
create or replace procedure MutatieLog_EnableGroup(in @MugGid integer)
begin
  for @Cursor AS CURSOR_MutLog CURSOR for

      select
        table_name @TabelNaam
      from systable
        inner join (tabMutatieLogHoofdGroep
                    inner join tabMutatieLogGroep on MugMuhGid = MuhGid
                    inner join tabMutatieLogTabel on MutMugGid = MugGid
                   ) on (table_name = MutTabelNaam) or ((MutIsPrefix = 1) and (Left(table_Name, Length(MutTabelNaam)) = MutTabelNaam))
        inner join tabMutatieLogInstellingen on MuiMugGid = MugGid
      where creator = (select uid from sysusers where name = 'KingSystem')
      and table_type = 'BASE'
      and MuhGeblokkeerd = 0
      and not (table_Name like '%\_HIST' escape '\')
      and MugGid = @MugGid
      order by MuhGid, MugGid, table_name

      FOR READ ONLY
    do
      //call Trace('MutatieLog_EnableGroup > MutatieLog_EnableTable: '+string(@TabelNaam));
      call MutatieLog_EnableTable(@TabelNaam);
    end for;
end;


create or replace procedure MutatieLog_EnableTable(
  //----------------------------------------------------
  //-----  Toevoegen mutatiehistorie aan 1 tabel -------
  //----------------------------------------------------

  //FASE 1: Nieuwe historietabel maken indien hij er nog niet is.
  //FASE 2: Evt. oude historietabel bijwerken met nieuwe velden/datatypes.
  //FASE 3: Trigger op hist.tabel zetten waarmee een aantal defaultjes gevuld worden.
  //FASE 4: Multi-Trigger maken op de main-tabel, die schrijft alle mutaties weg in de nieuwe historietabel.
  //FASE 5: Optioneel obv instelling: Een view maken zodat je verschillen makkelijk uit de historie kan opvragen.
  //FASE 6: Optioneel obv instelling: Een index maken op de historietabel zodat de view werkbaar snel is.
  in @TableName nchar(255),
  in @ReCreateHistTrigger smallint default 0
)
begin
  declare @Statement long nvarchar;
  declare @CRLF nchar(2);
  declare @MutLogCreateProcs smallint;
  declare @Hist_TableName nchar(128);
  declare @HistPostfix nchar(10);
  declare @TriggerName nchar(128);
  declare @TriggerOrder smallint;
  declare @Command nchar(10);
  declare @ViewName nchar(128);
  declare @AantalPks smallint;
  declare @PrimaryKeyVeld nchar(128);
  declare @IndexName nchar(128);

  //Deze 3 zijn nodig om het insert statement te maken wat in de trigger komt te staan:
  declare @TriggerColumnList long nvarchar;
  declare @TriggerValuesOld long nvarchar;
  declare @TriggerValuesNew long nvarchar;

  //Datatypes overgenomen uit SYSCOLUMN en SYSCOLUMNS.
  declare @ColName nchar(128);
  declare @Pkey nchar(1);
  declare @ColType nchar(128);
  declare @Length smallint;
  declare @Decimals smallint;
  declare @AllowNulls nchar(1);
  declare @In_primary_key nchar(1);
  declare @ColNo unsigned int;

  declare cursor_COL dynamic scroll cursor for
    select column_name, pkey, coltype, length, scale, col.nulls, in_primary_key, colno
    from sys.syscolumn col
    inner join sys.systable tab on tab.table_id = col.table_id
    inner join sys.syscolumns col2 on col2.tname = tab.table_Name and col2.cname = col.column_name
    where tab.Table_Name = Upper(@TableName)
    order by colno;

  //call TraceBegin('MutatieLog_EnableTable > @TableName = ' + @TableName);

  //VVE 20-10-2016 tbv leesbaarheid
  set @CRLF = nchar(13);

  set @MutLogCreateProcs = (select IsNull((select cast(Contents as smallint) from tabRegistry where RegKey = 'MUTLOGCREATEPROCS'),0));
  //call Trace('@MutLogCreateProcs='+string(@MutLogCreateProcs));

  //Nieuwe tabel en veldnamen krijgen deze postfix, evenals de dyn-triggers
  set @HistPostfix = '_HIST';
  //We zetten triggers op een hoge(re) order zodat ze niet conflicteren met de handmatig aangemaakte triggers.
  set @TriggerOrder = 10;

  //Input controles:
  if @TableName = '' then
    call Raise(17000, _U('Inputerror: Tabelnaam is verplicht!'));
  end if;
  if not exists(select 1 from systable where table_name = @TableName) then
    call Raise(17000, _U('Inputerror: Onbekende tabel: %1!', @TableName));
  end if;
  if length(@TableName) > (128 - Length(@HistPostfix)) then
    call Raise(17000, _U('Inputerror: De originele tabelnaam is te lang om een historietabel van te maken! (%1!)', @TableName));
  end if;
  //Vve: Historie van de historietabel bijhouden... het gaat allemaal goed, maar lijkt me nogal zinloos.
  //     Beveiliging ingebouwd, voor het geval iemand alle tabellen gaat adden, incl. HIST-tabellen die er al zijn.
  if right(@TableName, Length(@HistPostfix)) = @HistPostFix then
    call Raise(17000, _U('Inputerror: Beveiliging: Deze tabel is al historisch! (%1!)', @TableName));
  end if;

  //Vve 16-5-2007: Differencing wil je per "record" kunnen vaststellen. Een record wordt geidentificeerd door 1 id.
  // Kortom er moet 1 en precies 1 primarykey zijn.
  //Zonder primary key kunnen we niks. Met meerdere primary keys misschien wel maar daar heb ik nog geen oplossing voor nu.
  set @AantalPks = null;
  select count() into @AantalPks
       from sys.syscolumn col
       inner join sys.systable tab on tab.table_id = col.table_id
       inner join sys.syscolumns col2 on col2.tname = tab.table_Name and col2.cname = col.column_name
       where In_Primary_key = 'Y' and tab.Table_Name = @TableName;
  if IsNull(@AantalPks, 0) = 0 then
    call Raise(17000, _U('Inputerror: De tabel heeft geen primarykey. Hierdoor kan er straks geen differencing worden opgebouwd.(%1!)', +@TableName));
  end if;
  if @AantalPks > 1 then
    call Raise(17000, _U('Inputerror: De tabel heeft meerdere primarykey-velden (%1!). Hier kan de differ niet mee overweg en dit wordt zodoende niet ondersteund.(%2!)', string(@AantalPks), @TableName));
  end if;

  //VvE 20-10-2016: Verplaatst naar voren: Oude view droppen voordat we de brontabel wijzigen.
  // In 2012 is het viewtype veranderd naar materialized views. Deze leggen een constraint op wijzigingen op het schema vd brontabel.
  //RS 4-4-2022: de view aanmaken is verplaatst en wordt voorlopig niet opgevoerd. Wel wordt ie hier nog verwijderd indien aanwezig
  set @ViewName = 'vw_'+@TableName + @HistPostFix;
  if exists(select 1 from sys.systable where table_name=@ViewName) then
    //call Trace('Fase 0: Oude view verwijderen: '+ @ViewName);
    set @Statement = 'drop view '+ @ViewName;
    execute immediate @Statement;
  end if;

  //FASE 1: Nieuwe historietabel maken indien hij er nog niet is.
  set @Hist_TableName = @TableName + @HistPostfix;
  if exists (select 1 from sys.sysTable where table_name=@Hist_TableName) then
    //call Trace('Fase 1: Historietabel bestaat al. '+@Hist_TableName);
  else
    //call Trace('Fase 1: Nieuwe tabel opvoeren: '+ @Hist_TableName);
    set @Statement = 'create table ' + @Hist_TableName + '(' + @CRLF+
                   '  ' + @Hist_TableName +'_gid   integer not null default autoincrement primary key,' + @CRLF+
                   '  ' + @Hist_TableName +'_date  datetime not null default timestamp, ' + @CRLF+
                   '  ' + @Hist_TableName +'_user  nchar(40) not null, ' +@CRLF+
                   '  ' + @Hist_TableName +'_machine  nchar(40) not null, ' +@CRLF +
                   '  ' + @Hist_TableName +'_appname  nchar(100), ' +@CRLF +
                   '  ' + @Hist_TableName +'_mutatietype smallint not null);'; //0 nieuw, 1 update, 2 delete

    //call Trace(@Statement);
    execute immediate @Statement;
    set @Statement = 'comment on table '+ @Hist_TableName + ' is '+ '''Table gegenereerd door MutatieLog-systeem op '+ string(Now())+'.''';
    execute immediate @Statement;

    // De externe users select permissies geven voor de nieuwe tabel
    for @Cursor AS CURSOR_object CURSOR FOR
      select user_name @user from sysuserperm where remarks = 'Externe user #218123'
    for read only
    do
      execute immediate 'grant select on KingSystem.' || @Hist_TableName || ' to "' || @User ||'"'
    end for;
  end if;

  //FASE 2: Evt. oude historietabel bijwerken met nieuwe velden/datatypes.
  //Alvast de vaste velden en waarden voor de _HIST tabel vullen
  set @TriggerColumnList = ', ' + @Hist_TableName + '_date, ' + @Hist_TableName + '_user, ' + @Hist_TableName + '_machine, ' + @Hist_TableName + '_appname';
  set @TriggerValuesNew  = ', Now(), @@MutLogGebruikerCode, @@MutLogMachinename, @@MutLogAppName';
  set @TriggerValuesOld  = ', Now(), @@MutLogGebruikerCode, @@MutLogMachinename, @@MutLogAppName';

  set @Statement = '';
  open cursor_COL WITH HOLD;
  //We loopen langs alle kolommen in de hoofdtabel en checken of die goed in de history tabel staan.
  fetch next cursor_COL into @ColName, @Pkey, @ColType, @Length, @Decimals, @AllowNulls, @In_Primary_Key, @ColNo;
  while @@sqlstatus = 0 loop
    //call Trace('Fase 2: Col: '+ @ColName);
    set @Command = '';
    //Checken of deze kolom al in de Hist-tabel staat.
    if exists(select 1 from sys.syscolumn col inner join sys.systable tab on tab.table_id = col.table_id
               where tab.Table_Name = Upper(@Hist_TableName)
                 and col.column_name = (@ColName + @HistPostFix)) then
      //call Trace('Fase 2: Col'+ @ColName + ' bestaat al in ' + @Hist_TableName+ '.');
      //Checken of het datatype ook nog steeds hetzelfde is. Hiervoor hebben we syscolumnS weer nodig.
      if exists(select 1 from sys.syscolumn col inner join sys.systable tab on tab.table_id = col.table_id inner join sys.syscolumns col2 on col2.tname = tab.table_Name and col2.cname = col.column_name
               where tab.Table_Name = Upper(@Hist_TableName)
                 and col.column_name = (@ColName + @HistPostFix)
                 and colType = @ColType and Length= @Length and Scale=@Decimals) then
        //call Trace('Fase 2: Col '+ @ColName + ' is van hetzelfde type en lengte. Veld=ok!');
      else
        //call Trace('Fase 2: Col '+ @ColName + ' is van een ander type of lengte!');
        set @Command = ' MODIFY ';
      end if;
    else
      //call Trace('Fase 2: Col '+ @ColName + ' bestaat nog niet in ' + @Hist_TableName+ '.');
      set @Command = ' ADD ';
    end if;

    if @Command <> '' then
      //VvE 20-10-2016: Unicode ondersteuning erbij mv nchar. Char er nog bijgehouden ter ondersteuning van andere/oude databases.
      if (@ColType = 'char') or (@ColType = 'nchar') then
        set @Statement = @Statement + @Command + @ColName + @HistPostfix +  '  ' + @ColType + '('+string(@Length)+'),' + @CRLF;
      else
        if @ColType = 'numeric' then
          set @Statement = @Statement + @Command + @ColName + @HistPostfix +  '  ' + @ColType + '('+string(@Length)+', ' + string(@Decimals) + '),' + @CRLF;
        else
          set @Statement = @Statement + @Command + @ColName + @HistPostfix + '  ' + @ColType + ',' + @CRLF;
        end if;
      end if;
    end if;

    //Voorbereind werk voor de trigger zometeen
    set @TriggerColumnList = @TriggerColumnList + ', ' + @ColName + @HistPostFix;
    set @TriggerValuesOld  = @TriggerValuesOld  + ', ' + 'Old_Record.'+@ColName;
    set @TriggerValuesNew  = @TriggerValuesNew  + ', ' + 'New_Record.'+@ColName;

    //Voorbreidend werk voor de view zometeen
    if @In_Primary_Key = 'Y' then
      //call Trace('Fase 2: Primary key gevonden: '+ @ColName);
      set @PrimaryKeyVeld = @ColName
    end if;

    fetch next cursor_COL into @ColName, @Pkey, @ColType, @Length, @Decimals, @AllowNulls, @In_Primary_Key, @ColNo;
  end loop;
  close cursor_COL;

  //Zijn er mutaties?
  if @Statement = '' then
    //call Trace('Fase 2: Geen wijzigingen voor de Historytabel gevonden: '+ @Hist_TableName);
  else
    //call Trace('Fase 2: Historytabel bijwerken: '+ @Hist_TableName);

    //Laatste kommaatje mag niet in altertable statement
    set @Statement = left(@Statement, length(@Statement)-2);
    //Alter table eromheen zetten
    set @Statement = 'alter table ' + @Hist_TableName + @CRLF +
                     @Statement;

    //call Trace(@Statement);
    execute immediate @Statement;
  end if;

  // De proc is eerder al verwijderd. De index kan nu ook nu de PK bekend is.
  // Alleen als we geen views meer gebruiken. Gebruiker we die wel dan wordt de index daar opnieuw aangemaakt
  set @IndexName = 'Idx_'+@PrimaryKeyVeld + @HistPostFix;
  if (@MutLogCreateProcs = 0) and exists(select 1 from sys.sysIndex where index_name=@IndexName) then
    //call Trace('Fase 6: Oude index verwijderen: '+ @IndexName);
    set @Statement = 'drop index '+ @IndexName;
    execute immediate @Statement;
  end if;
  // Idem voor de index op de date column
  set @IndexName = 'Idx_'+@Hist_TableName+'_date';
  if (@MutLogCreateProcs = 0) and exists(select 1 from sys.sysIndex where index_name=@IndexName) then
    //call Trace('Fase 6: Oude index verwijderen: '+ @IndexName);
    set @Statement = 'drop index '+ @IndexName;
    execute immediate @Statement;
  end if;

  //Fase 3: Dyn-Trigger maken op hoofdtabel die de historie tabel gaat vullen, eerst evt oude verwijderen:
  set @TriggerName = 'dtia_'+@TableName + @HistPostfix;
  delete tabDynamicTriggers where DtName = @TriggerName;
  //call Trace('Fase 4: Nieuwe AfterInsert dyn-trigger opvoeren: '+ @TriggerName);
  set @Statement = 'insert into tabDynamicTriggers(dtName, dtTablename, dtMutationType, dtExecute) values ' + @CRLF +
                   '  ('''+@TriggerName+''', '''+@TableName+''', 10, ''insert into ' + @Hist_TableName + '('+@Hist_TableName +'_mutatietype' + @TriggerColumnList+')'+ @CRLF +
                   '                                               values (0' + @TriggerValuesNew + ');'');';
  //call Trace('DynTrig Insert='+@Statement);
  execute immediate @Statement;

  set @TriggerName = 'dtua_'+@TableName + @HistPostfix;
  delete tabDynamicTriggers where DtName = @TriggerName;
  //call Trace('Fase 4: Nieuwe AfterUpdate dyn-trigger opvoeren: '+ @TriggerName);
  set @Statement = 'insert into tabDynamicTriggers(dtName, dtTablename, dtMutationType, dtExecute) values ' + @CRLF +
                   '  ('''+@TriggerName+''', '''+@TableName+''', 11, ''insert into ' + @Hist_TableName + '('+@Hist_TableName +'_mutatietype' + @TriggerColumnList+')'+ @CRLF +
                   '                                               values (1' + @TriggerValuesNew + ');'');';
  //call Trace('DynTrig Update='+@Statement);
  execute immediate @Statement;

  set @TriggerName = 'dtda_'+@TableName + @HistPostfix;
  delete tabDynamicTriggers where DtName = @TriggerName;
  //call Trace('Fase 4: Nieuwe AfterDelete dyn-trigger opvoeren: '+ @TriggerName);
  set @Statement = 'insert into tabDynamicTriggers(dtName, dtTablename, dtMutationType, dtExecute) values ' + @CRLF +
                   '  ('''+@TriggerName+''', '''+@TableName+''', 12, ''insert into ' + @Hist_TableName + '('+@Hist_TableName +'_mutatietype' + @TriggerColumnList+')'+ @CRLF +
                   '                                               values (2' + @TriggerValuesOld + ');'');';
  //call Trace('DynTrig Delete='+@Statement);
  execute immediate @Statement;

  //RS 12-10-2022 : Storedproc + indexen voor mutaties per veld aanmaken
  if @MutLogCreateProcs = 1 then
    call MutatieLog_AddProcHistTable(@TableName, @PrimaryKeyVeld);
  end if;

  //call TraceEind('MutatieLog_EnableTable');
end;


create or replace function MutatieLog_GetUserIdFromForeignKey(in @FKTable varchar(100), in @FKColumn varchar(100), in @FKUserId varchar(128), in @FKValue integer) returns nchar(100)
begin
  declare @Result nchar(100);
  declare @Stmt nchar(255);
  if @FKValue is null then
    set @Result = null
  else
    //select `[@FKUserId]` into @Result from `[@FKTable]` where `[@FKColumn]` = @FKValue;
    set @Stmt = 'select ' || @FKUserId || ' into @Result from ' || @FKTable || ' where ' || @FKColumn || ' = ' || @FKValue;
    //call Trace(@Stmt);
    execute immediate @Stmt;
  end if;
  return @Result;
end;


create or replace procedure MutatieLog_GroupUnion(in @MutTypes smallint, in @MugGid integer, in @RecordGid integer, in @VrId integer)
begin
  declare @HistPostfix nchar(10) = '_HIST';
  declare @ProcPrefix  nchar(3)  = 'sp_';
  declare @CRLF        nchar(2)  = char(13);
  declare @ProcName    nchar(128);
  declare @Statement   long nvarchar;

  for @Cursor AS CURSOR_MutLog CURSOR for
    select
      MutTabelNaam        @Tabelnaam,
      MutProcVolgorde     @Volgorde,
      MutIsPrefix         @IsPrefix,
      (if MutFKVeld is null then 0 else 1 endif) @IsFk
    from tabMutatieLogTabel
    where MutMugGid = @MugGid
    and MutProcVolgorde > 0 and MutMasterTabel is null
    order by MutProcVolgorde

    FOR READ ONLY
    do
      if @IsPrefix = 0 then
        set @ProcName = @ProcPrefix || @Tabelnaam || @HistPostFix;
        //call Trace('NoTablePrefix @ProcName='+string(@ProcName));
      else
        select first proc_name into @ProcName from sysprocedure where proc_name like @ProcPrefix || @Tabelnaam || '%' || @HistPostFix;
      end if;
      if @IsFk = 0 then
        //call Trace('PK @ProcName='+string(@ProcName));
        set @Statement = @Statement || 'select RecordGid, ForeignKeyGid, OldHistGid, NewHistGid, Id, Veld, OudeWaarde, NieuweWaarde, MutatieType, Wanneer, Gebruiker, Machine, Proces from ' || @ProcName || '(' || string(@MutTypes) || ', null, null, ' || string(@RecordGid)+', null, ' || string(@VrId) || ') ' || @CRLF || ' UNION ALL ' || @CRLF;
      else
        //call Trace('FK @ProcName='+string(@ProcName));
        set @Statement = @Statement || 'select RecordGid, ForeignKeyGid, OldHistGid, NewHistGid, Id, Veld, OudeWaarde, NieuweWaarde, MutatieType, Wanneer, Gebruiker, Machine, Proces from ' || @ProcName || '(' || string(@MutTypes) || ', null, null, null, ' || string(@RecordGid)+', ' || string(@VrId)+') ' || @CRLF || ' UNION ALL ' || @CRLF;
      end if;

    end for;

  set @Statement = left(@Statement, length(@Statement)-length(' UNION ALL ' || @CRLF));
  set @Statement = 'select RecordGid, ForeignKeyGid, OldHistGid, NewHistGid, Id, Veld, OudeWaarde, NieuweWaarde, MutatieType, Wanneer, Gebruiker, Machine, Proces from ( ' || @CRLF || @Statement || @CRLF || ') as Dummy order by Wanneer desc';

  //unload select @Statement to 'd:\unload.sql';
  execute immediate with result set on @Statement;
end;

//call MutatieLog_GroupUnion(18,2,1)

// Zet de @@AppName variabele voor het mutatielog
// Optioneel ook de @@MachineNaam en @@GebruikerCode indien gevuld
create or replace procedure SetMutatieLogVars(
  in @AppName       nchar(100),
  in @MachineName   nchar(20) default '',
  in @GebruikerCode nchar(20) default '')
begin
  set @@MutLogAppName = @AppName;

  if @MachineName <> '' then
    set @@MutLogMachineName = @MachineName;
  else
    set @@MutLogMachineName = @@MachineName;
  end if;

  if @GebruikerCode <> '' then
    set @@MutLogGebruikerCode = @GebruikerCode;
  else
    set @@MutLogGebruikerCode = @@GebruikerCode;
  end if;
end;




