create or replace procedure KingInfo.King_Info(
  in @Property nchar(20) default null // Indien leeg/niet meegegeven, dan alle properties teruggeven, anders alleen de opgegeven property
)
result(
  Property nchar(20),
  Value    long nvarchar
)
begin
  //Admin variant

  // In alfabetische volgorde houden!
  declare @_PropDbBuildNr       nchar(20) = 'DbBuildNr';
  declare @_PropKingBuildNr     nchar(20) = 'KingBuildNr';
  declare @_PropKingMainBuildNr nchar(20) = 'KingMainBuildNr';
  declare @_PropLicentieNr      nchar(20) = 'LicentieNr';

  declare @DbBuildNr       nchar(40);
  declare @KingBuildNr     nchar(40);
  declare @KingMainBuildNr nchar(40);
  declare @LicentieNr      nchar(40);

  if @property = '' then
    set @property = null;
  end if;

  // Database buildnumber
  select string(qdVerVersion) into @DbBuildNr from KingSystem.qdtabversion where qdVerSoort = 'Meta-informatie';


  select Contents into @KingBuildNr from KingSystem.tabregistry where regkey='KingBuildNr';


  select qdVerVersion into @KingMainBuildNr from kingsystem.qdtabVersion where qdVerSoort = 'MainRelease';
  if @KingMainBuildNr is null then
    begin
      declare @iKingMainBuildNr integer;
      set @iKingMainBuildNr = cast(left(@KingBuildNr, locate(@KingBuildNr + '.', '.') - 1)  as integer);
      set @KingMainBuildNr  = string(@iKingMainBuildNr);
    exception
    when others then
      set @KingMainBuildNr = @KingBuildNr;
    end;
  end if;


  select if isnumeric(Contents) <> 0 then contents endif into @LicentieNr from KingSystem.tabregistry where regkey='LICENTIENUMMER';

  // ******************
  // *** Result set ***
  // ******************
            select @_PropDbBuildNr       Property, @DbBuildNr       where isnull(@Property, @_PropDbBuildNr) = @_PropDbBuildNr
  union all select @_PropKingBuildNr     Property, @KingBuildNr     where isnull(@Property, @_PropKingBuildNr    ) = @_PropKingBuildNr
  union all select @_PropKingMainBuildNr Property, @KingMainBuildNr where isnull(@Property, @_PropKingMainBuildNr) = @_PropKingMainBuildNr
  union all select @_PropLicentieNr      Property, @LicentieNr      where isnull(@Property, @_PropLicentieNr     ) = @_PropLicentieNr
  order by 1
end;

alter procedure KingInfo.King_Info set hidden;
// Zeker weten dat ook de kingsystem namespace deze routine kan gebruiken
grant execute on KingInfo.King_Info     to KingSystem;



create or replace procedure PrijzenBerekenenObvInkoopPrijzen(
  in @SelecterenOp          integer,  // 0 = ArtikelCode, 1 = ArtikelZoekcode, 2 = Leverancier, 3 = Opbrengstgroep
  in @SelecterenVan         nchar(20),
  in @SelecterenTm          nchar(20),
  in @KostPrijsberekenen    smallint,
  in @VerkoopPrijsberekenen smallint,
  in @VerwerkDatum          datetime,
  out @FoutNummer           smallint // 0 = Ok, 1 = Fout
)
/*
  Deze stored procedure maakt prijswijzigingsrecords aan van artikelen die een default leverancier hebben en waarvoor inkoopprijzen berekenen aanstaat

  begin
    declare @FoutNummer smallint;
    call PrijzenBerekenenObvInkoopPrijzen(0, 'Broodrooster1', 'Broodrooster1', 1, 1, Now(), @Foutnummer);
    select @FoutNummer;
  end;

  LET OP !!! Code is gebaseerd op Delphi code in fArtikelEdit scherm. Mochten hier wijzigingen doorgevoerd worden,
             dan moet bekeken worden of die wijzigingen ook in dat scherm doorgevoerd moeten worden.
*/

begin
  declare @_PwkId integer;
  declare @_BjGid integer;
  declare @_PerNr integer;

  declare @_StaffelKortingSoort  integer;
  declare @_KortingBedrag        numeric(15,3);
  declare @_KortingPercentage    numeric(15,2);
  declare @_NettoInkoopPrijs     numeric(15,3);
  declare @_KostprijsEenheid     numeric(15,3);
  declare @_VerkoopPrijsExcl     numeric(15,3);
  declare @_VerkoopPrijsIncl     numeric(15,3);

  declare @_Percentage            numeric(15,2);

  declare @_ArtVastAutomBerekenen smallint;
  declare @_ArtVastBerekenPrijs   smallint;
  declare @_ArtVastBerekenMarge   smallint;
  declare @_ArtVastPercentage     numeric(15,2);

  declare local temporary table TempArtikel (
    // velden uit king tabellen
    ArtGid                  integer,
    ArtAantDecPrijzen       integer,
    ArtPrijsPer             numeric(15,3),

    ArtBerekenPrijs         smallint,
    ArtBerekenPrijsVan      numeric(5,2),
    ArtBerekenPrijsMargeIs  smallint,
    ArtBerekenPrijsPerc     numeric(5,2),
    ArtVerkprijsIsIncl      smallint,

    AldKortingSoort         smallint,
    AldInkoopPrijs          numeric(15,3),
    AldInkoopPrijsPer       smallint,
    AldKortingBedrag        numeric(15,3),
    AldKortingPercentage    numeric(15,2),
    AldNstfKopGid           integer,
    AldValNummer            nchar(10),
    AldBerekeningKostprijs  smallint,
    AldFactorKostprijs      numeric(15,3),
    AldBedragToeslag        numeric(15,3),
    AldVoorraadEenhedenInInkoopEenheid numeric(15,3),

    BtwPercentage           numeric(6,2),

    // berekende velden
    calcKostprijsEenheid    numeric(15,3),
    calcVerkoopPrijs        numeric(15,3)
  ) on commit preserve rows;

  set @foutnummer = 0;

  //call trace('@SelecterenOp=' + string(@SelecterenOp) + '@SelecterenVan= ' + @SelecterenVan + ', @SelecterenTm=' + @SelecterenTm + ' @KostPrijsberekenen=' + string(@KostPrijsberekenen)+', ');

  // als bij een artikel ingesteld staat dat prijzen volgens de vaste gegevens berekend moeten worden, dan halen we nu de vaste gegevens op
  select
    ArtVastAutomBerekenen,
    ArtVastBerekenPrijs,
    ArtVastBerekenMarge,
    ArtVastPercentage
  into
    @_ArtVastAutomBerekenen,
    @_ArtVastBerekenPrijs,
    @_ArtVastBerekenMarge,
    @_ArtVastPercentage
  from
    tabArtikelVasteGegevens
  where
    ArtVastSoort = 2; /* artikel */

  /* Deze sp volgt dezelfde werkwijze als de sp voor het berekenen van prijzen o.b.v. recepten. */
  /* Dus eerst de te selecteren artikelen en benodigde gegevens in een tijdelijke tabel plaatsen en daarmee verder rekenen. */
  insert into TempArtikel (ArtGid, ArtAantDecPrijzen, ArtPrijsPer, ArtBerekenPrijs, ArtBerekenPrijsVan, ArtBerekenPrijsMargeIs, ArtBerekenPrijsPerc, ArtVerkprijsIsIncl,
                           AldKortingSoort, AldInkoopPrijs, AldKortingBedrag, AldKortingPercentage, AldNstfKopGid, AldValNummer, AldVoorraadEenhedenInInkoopEenheid, AldBerekeningKostprijs, AldFactorKostprijs, AldBedragToeslag, AldInkoopPrijsPer,
                           BtwPercentage)
  select ArtGid, ArtAantDecPrijzen, ArtPrijsPer, ArtBerekenPrijs, ArtBerekenPrijsVan, ArtBerekenPrijsMargeIs, ArtBerekenPrijsPerc, ArtVerkprijsIsIncl,
         AldKortingSoort, AldInkoopPrijs, AldKortingBedrag, AldKortingPercentage, AldNstfKopGid, AldValNummer, AldVoorraadEenhedenInInkoopEenheid, AldBerekeningKostprijs, AldFactorKostprijs, AldBedragToeslag, AldInkoopPrijsPer,
         BtwPercentage
  from tabArtikel
  inner join (tabArtikelLeverancier inner join tabNawFile on (nawFilNawGid = ArtLevNawGid)) on (ArtLevArtGid = ArtGid and ArtLevIsDefault = 1)
  inner join tabArtikelLeverancierDetail on (AldArtLevGid = ArtLevGid and AldIsDefaultInkoopEenheidBijLev = 1 and AldHeeftEigenInkoopprijs=1)
  inner join tabBtw on BtwCode = ArtBTWcode
  inner join tabOpbrengstgroep on OpbrGrpGId = ArtOpbrGrpGId
  where ((@SelecterenOp=0 /* artikelCode */      and (artcode between @SelecterenVan and @SelecterenTm)) or
         (@SelecterenOp=1 /* artikelZoekcode */  and (ArtZoekcode between @SelecterenVan and @SelecterenTm)) or
         (@SelecterenOp=2 /*Leverancier*/        and (NawFilNummer between @SelecterenVan and @SelecterenTm)) or
         (@SelecterenOp=3 /* opbrengstgroep */   and (OpbrGrpNummer between @SelecterenVan and @SelecterenTm))
        );
  //RB altijd kostprijs berekenen als er inkoopprijs is bij default leverancier/inkoopeenheid
  //RB and (ArtBerekenPrijsVan = 1)  /* verkoopprijs o.b.v. kostprijs */
  //RB and (   (ArtBerekenPrijs = 1  /* volgens vaste gegegevens   */ and @_ArtVastAutomBerekenen = 1)
  //RB      or (ArtBerekenPrijs = 2  /* volgens eigen instellingen */));

  call BepaalBoekjaarEnPeriode(@VerwerkDatum, @_BjGid /* out */, @_PerNr /*out */);

  /*
    De artikelen die doorgerekend moeten worden, zijn nu bekend.
    Per artikel de netto inkoopprijs berekenen (gebaseerd op fArtikelenEdit, BerekenNettoInkoopPrijs, aldaar: sqlArtikelLeverancierDetailEditCalcArtLevNettoInkoopPrijs)
  */

  /* netto inkoopprijzen berekenen */
  for artikelen as ArtikelInkoopprijsCursor Cursor For
     select ArtGid @_ArtGidBron,
            ArtAantDecPrijzen @_ArtAantDecPrijzen,
            ArtBerekenPrijs @_ArtBerekenPrijs,
            ArtBerekenPrijsVan @_ArtBerekenPrijsVan,
            ArtBerekenPrijsMargeIs @_ArtBerekenPrijsMargeIs,
            ArtBerekenPrijsPerc @_ArtBerekenPrijsPerc,
            ArtVerkprijsIsIncl @_ArtVerkprijsIsIncl,
            AldInkoopPrijs @_AldInkoopPrijs,
            AldKortingSoort @_AldKortingSoort,
            AldKortingPercentage @_AldKortingPercentage,
            AldNstfKopGid @_AldNstfKopGid,
            AldValNummer @_AldValNummer,
            AldBerekeningKostprijs @_AldBerekeningKostprijs,
            AldFactorKostprijs @_AldFactorKostprijs,
            AldBedragToeslag @_AldBedragToeslag,
            AldInkoopPrijsPer @_AldInkoopPrijsPer,
            AldVoorraadEenhedenInInkoopEenheid @_AldVoorraadEenhedenInInkoopEenheid,
            AldKortingBedrag @_AldKortingBedrag,
            BtwPercentage @_BtwPercentage,
            ArtPrijsPer @_ArtPrijsPer
     from tempArtikel
  do
    case @_AldKortingSoort
    when 0 /* Bedrag */ then
      set @_NettoInkoopPrijs = @_AldInkoopPrijs - @_AldKortingBedrag;
    when 1 /* Percentage */  then
       set @_NettoInkoopPrijs = round (@_AldInkoopPrijs - ((@_AldInkoopPrijs / 100) * @_AldKortingPercentage), @_ArtAantDecPrijzen);
    when 2 /* Gestaffeld */ then
      if (@_AldNstfKopGid is not null) then
        call PrijzenBerekenenObvInkoopPrijzen_BepaalNawStaffelEersteRegelKortingen(@_AldNstfKopGid, @_AldValNummer, @_BjGid, @_PerNr, @_StaffelKortingSoort /* out */, @_KortingBedrag  /* out */, @_KortingPercentage  /* out */);

        if @_StaffelKortingSoort = 0 /* Bedrag */ then
           if @_AldInkoopPrijsPer = 1    /* prijs per X voorraadeenheden */ then
             set @_NettoInkoopPrijs = round (@_AldInkoopPrijs - round(((@_KortingBedrag / @_AldVoorraadEenhedenInInkoopEenheid) * @_ArtPrijsPer), @_ArtAantDecPrijzen), @_ArtAantDecPrijzen)
           else                        /* prijs per inkoopeenheid */
             set @_NettoInkoopPrijs = round (@_AldInkoopPrijs - round(@_KortingBedrag, @_ArtAantDecPrijzen), @_ArtAantDecPrijzen);
           end if
        else
          if @_StaffelKortingSoort = 1 /* Percentage */ then
            set @_NettoInkoopPrijs = round (@_AldInkoopPrijs - ((@_AldInkoopPrijs / 100) * @_KortingPercentage), @_ArtAantDecPrijzen);
          end if
        end if;
      end if;
    else
      set @_NettoInkoopPrijs = @_AldInkoopPrijs;
    end case;

    /* De netto inkoop prijs is nu bekend. De kostprijs eenheid berekenen (gebaseerd op fArtikelenEdit, BerekenKostprijsEenheid, InkoopprijsTegenwaarde) */
    // kostprijs maal factor of plus toeslag
    if (@_AldBerekeningKostprijs = 0) then  /* maal factor */
      set @_KostprijsEenheid = round(@_NettoInkoopPrijs * @_AldFactorKostprijs, @_ArtAantDecPrijzen);
    else                                  /* plus bedrag */
      set @_KostprijsEenheid = round(@_NettoInkoopPrijs + @_AldBedragToeslag, @_ArtAantDecPrijzen);
    end if;

    // prijs per inkoopeenheid omrekenen naar .... voorraadeenheden
    if (@_AldInkoopPrijsPer = 0 /* Prijs per inkoopeenheid */) then
      if (@_AldVoorraadEenhedenInInkoopEenheid <> 0) then /* niet door nul delen */
        set @_KostprijsEenheid = round((@_KostprijsEenheid / @_AldVoorraadEenhedenInInkoopEenheid) * @_ArtPrijsPer, @_ArtAantDecPrijzen);
      else
        set @_KostprijsEenheid = 0;
      end if
    end if;

    set @_KostprijsEenheid = PrijzenBerekenenObvInkoopPrijzen_OmrekenenValuta(@_KostprijsEenheid, @_AldValNummer, @@BasisValutaNummer, @_ArtAantDecPrijzen, @_BjGid, @_PerNr);

    // Berekenen van verkoopprijs o.b.v. kostprijs (overgenomen van TfrmPrijzenWijzigenEdit: edKostprijsExit en BerekenMetMarge)

    //RB Verkoopprijs alleen berekenen als nodig volgens artikel/VG artcode
    set @_VerkoopPrijsExcl = null; //Eerst op leeg zetten anders gebruik je degene van een vorig artikel
    set @_VerkoopPrijsIncl = null; //Eerst op leeg zetten anders gebruik je degene van een vorig artikel

    if (@_ArtBerekenPrijs = 1 /* volgens vaste gegegevens */   and @_ArtVastAutomBerekenen = 1 /* prijs autom. berekenen*/ and @_ArtVastBerekenPrijs = 1 /* bereken verkoopprijs obv kostprijs */) or
       (@_ArtBerekenPrijs = 2 /* volgens eigen instellingen */ and @_ArtBerekenPrijsVan = 1 /* bereken verkoopprijs obv kostprijs */) then

      // welke marge?
      if (@_ArtBerekenPrijs = 1 /* volgens vaste gegegevens */)  then
        set @_Percentage = @_ArtVastPercentage;
      else
        set @_Percentage = @_ArtBerekenPrijsPerc;
      end if;

      // verkoopprijs is marge van kostprijs?
      if (@_ArtBerekenPrijs = 1    /* volgens vaste gegegevens   */ and @_ArtVastBerekenMarge = 0  /* marge van kostprijs */)
         or (@_ArtBerekenPrijs = 2 /* volgens eigen instellingen */ and @_ArtBerekenPrijsMargeIs = 0 /* marge van kostprijs */) then
         // ja, verkoopprijs is marge van kostprijs
         set @_VerkoopPrijsExcl = @_KostprijsEenheid * (1 + (@_Percentage/100 ));
      else
         // kostprijs is marge van verkoopprijs?
         if (@_ArtBerekenPrijs = 1    /* volgens vaste gegegevens   */ and @_ArtVastBerekenMarge = 1  /* marge van verkoopprijs */)
            or (@_ArtBerekenPrijs = 2 /* volgens eigen instellingen */ and @_ArtBerekenPrijsMargeIs = 1 /* marge van verkoopprijs */) then
            // ja, kostprijs is marge van verkoopprijs

            // met marge berekenen
            if @_Percentage = 100 then
              set @_VerkoopPrijsExcl = @_KostprijsEenheid;
            else
              set @_VerkoopPrijsExcl = @_KostprijsEenheid * (100/(100 - @_Percentage));
            end if
         end if
      end if;

      // van excl naar incl omrekenen
      set @_VerkoopPrijsIncl = @_VerkoopPrijsExcl * (if @_ArtVerkprijsIsIncl = 1 then (1 + @_BtwPercentage / 100) else 1 endif);

      // verkoopprijzen afronden
      set @_VerkoopPrijsExcl = round(@_VerkoopPrijsExcl, @_ArtAantDecPrijzen);
      set @_VerkoopPrijsIncl = round(@_VerkoopPrijsIncl, @_ArtAantDecPrijzen);
    end if;

    update tempArtikel
       set calcKostprijsEenheid = @_KostprijsEenheid,
           calcVerkoopPrijs     = if @VerkoopPrijsberekenen = 1 then
                                    if @_ArtVerkprijsIsIncl = 1 then
                                      ArtikelPrijsAfronding(@_VerkoopPrijsIncl, @_ArtAantDecPrijzen)
                                    else
                                      ArtikelPrijsAfronding(@_VerkoopPrijsExcl, @_ArtAantDecPrijzen)
                                    endif
                                  endif
     where ArtGid = @_ArtGidBron;
  end for;

  if @foutnummer = 0 then
      // Haal de prijswijzigingskop ID op.
      select first PwkId into @_PwkId from tabPrijsWijzigingskop;

      //Update bestaande prijswijzigingsrecords en voeg niet bestaande toe
      merge into tabPrijsWijzigingsregel(PwrPwkId              , PwrArtGid ,         PwrPrijsPer ,             PwrKostprijs        , PwrIsVerkoopprijsIncl ,         PwrVerkoopprijs)
        using (
                select                   @_PwkId as calcPwkGid , TempArtikel.ArtGid, TempArtikel.ArtPrijsPer , calcKostprijsEenheid, TempArtikel.ArtVerkprijsIsIncl, calcVerkoopPrijs
                from TempArtikel
                inner join tabartikel normArt on normArt.artgid = TempArtikel.ArtGid and (normArt.artKostPrijsex <> calcKostprijsEenheid or normArt.ArtVerkprijs <> calcVerkoopPrijs)
               ) t
        on (PwrPwkId = t.calcPwkGid and PwrArtGid = t.ArtGid)
        when matched then update set  PwrPrijsPer           = t.ArtPrijsPer,
                                      PwrKostprijs          = if @KostPrijsberekenen = 1    and t.calcKostprijsEenheid is not null then t.calcKostprijsEenheid else PwrKostprijs           endif,
                                      PwrIsVerkoopprijsIncl = if @VerkoopPrijsberekenen = 1 and t.calcVerkoopprijs     is not null then t.ArtVerkprijsIsIncl   else PwrIsVerkoopprijsIncl  endif,
                                      PwrVerkoopprijs       = if @VerkoopPrijsberekenen = 1 and t.calcVerkoopprijs     is not null then t.calcVerkoopprijs     else PwrVerkoopprijs        endif
        when not matched then insert;
    end if;

  //call TraceEind('PrijzenBerekenenObvInkoopPrijzen');
end;


create or replace procedure PrijzenBerekenenObvInkoopPrijzen_BepaalNawStaffelEersteRegelKortingen(
  in  @NstfKopGid    integer,
  in  @ValNummer     nchar(10),
  in  @BjGid         integer,
  in  @PerNr         integer,
  out @KortingSoort  integer,
  out @Bedrag        numeric(15,3),
  out @Percentage    numeric(15,2)
)
begin
  declare @_ValNummer integer;

  select first
    NstfKopSoort,
    NstfKopValNummer,
    NstfRglBedrag,
    NstfRglPercentage
  into
    @KortingSoort,
    @_ValNummer,
    @Bedrag,
    @Percentage
  from tabNawStaffelRegel
  inner join tabNawStaffelKop on NstfKopGid = NstfRglNstfKopGid
  where NstfRglNstfKopGid = @NstfKopGid
  order by NstfRglVanafAantal;

  if (@KortingSoort = 0 /* Bedrag */ ) then
    set @Bedrag = PrijzenBerekenenObvInkoopPrijzen_OmrekenenValuta(@Bedrag, @_ValNummer, @ValNummer, 3, @BjGid, @PerNr);
  end if;
end;


create or replace function PrijzenBerekenenObvInkoopPrijzen_OmrekenenValuta(
  in  @Bedrag           numeric(15,3),
  in  @VanValutaNummer  integer,
  in  @NaarValutaNummer integer,
  in  @AantalDecimalen  integer,
  in  @BjGid            integer,
  in  @Pernr            integer
) returns numeric(15,3)
begin
  declare @_ValutaBedrag numeric(15,3);

  if @VanValutaNummer = @NaarValutaNummer then
    set @_ValutaBedrag = round(@Bedrag, @AantalDecimalen);
  else
    call ValutaOmrekenenProc(@VanValutaNummer, @Bedrag, @NaarValutaNummer, @BjGid, null /* datum */, @Pernr, null /* dgbgid */, @AantalDecimalen, @_ValutaBedrag);
  end if;

  return (@_ValutaBedrag);
end;

create or replace procedure PrijzenBerekenenObvRecepten(in @SelecterenOp                  integer,  // 0 = ArtikelCode
                                                                                                    // 1 = ArtikelZoekcode
                                                                                                    // 2 = Leverancier
                                                                                                    // 3 = Opbrengstgroep
                                                        in @SelecterenVan                 nchar(20),
                                                        in @SelecterenTm                  nchar(20),
                                                        in @KostPrijsberekenen            smallint,
                                                        in @VerkoopPrijsberekenen         smallint,

                                                        out @FoutNummer                   smallint) // 0 = OK
                                                                                                    // 1 = Fout

//MR 09-feb-2018: Deze stored procedure maakt prijzwijzigingsrecords aan van artikelen die een recept hebben ingesteld bij het artikel.
/*
begin
  declare @FoutNummer smallint;
  call PrijzenBerekenenObvRecepten(0,'BD-R25GB','WORD',1,1,@Foutnummer);
  select @foutnummer from Dummy;
end;
*/
begin
  //call TraceBegin('PrijzenBerekenenObvRecepten');
  declare @PwkId integer;
  declare local temporary table TempArtikel (
    calcArtGid                  integer,
    calcRcptGid                 integer,
    calcRcpeGid                 integer,
    calcRcpeAantal              numeric(15,3),
    calcBTWcode                 integer,
    calcPrijsPer                numeric(15,3),
    calcAantalDecimalenPrijzen  smallint,
    calcKostprijsEx             numeric(30,6),
    calcVerkprijsIsIncl         smallint,
    calcVerkoopprijs            numeric(30,6),
    calcAantalProductiePerBatch numeric(15,3),
    //Hulpvelden
    calcHulpKostprijsVanComponenten    numeric(30,6),
    calcHulpVerkoopprijsVanComponenten numeric(30,6),
    //Rekenmethode per receptregel
    calcBerekenArtKostprijsBerekening smallint,
    calcBerekenArtKostprijsPercentage numeric(15,3),
    calcBerekenArtVerkoopprijsBerekening smallint,
    calcBerekenArtVerkoopprijsPercentage numeric(15,3)
  ) on commit preserve rows;

  set @foutnummer = 0;

  //Selecteer de artikelen waarvoor de prijzen moeten worden berekend en zet deze in een temporary table
  case @SelecterenOp
  when 0 /*ArtikelCode*/      then
    insert into TempArtikel (calcArtGid, calcRcptGid, calcRcpeGid, calcBTWcode, calcPrijsPer, calcAantalDecimalenPrijzen, calcVerkprijsIsIncl)
      select                 calcArtGid, calcRcptGid, calcRcpeGid, calcBTWcode, calcPrijsPer, calcAantalDecimalenPrijzen, calcVerkprijsIsIncl
      from vwArtikelMetDefaultRecept
      where (calcArtcode between @SelecterenVan and @SelecterenTm) and (calcKostprijsBerekening = 1 or calcVerkoopprijsBerekening = 1);
  when 1 /*ArtikelZoekcode*/  then
    insert into TempArtikel (calcArtGid, calcRcptGid, calcRcpeGid, calcBTWcode, calcPrijsPer, calcAantalDecimalenPrijzen, calcVerkprijsIsIncl)
      select                 calcArtGid, calcRcptGid, calcRcpeGid, calcBTWcode, calcPrijsPer, calcAantalDecimalenPrijzen, calcVerkprijsIsIncl
      from vwArtikelMetDefaultRecept
      where (CalcArtZoekcode between @SelecterenVan and @SelecterenTm) and (calcKostprijsBerekening = 1 or calcVerkoopprijsBerekening = 1);
  when 2 /*Leverancier*/      then
    insert into TempArtikel (calcArtGid, calcRcptGid, calcRcpeGid, calcBTWcode, calcPrijsPer, calcAantalDecimalenPrijzen, calcVerkprijsIsIncl)
      select                 calcArtGid, calcRcptGid, calcRcpeGid, calcBTWcode, calcPrijsPer, calcAantalDecimalenPrijzen, calcVerkprijsIsIncl
      from vwArtikelMetDefaultRecept
           inner join tabArtikelLeverancier  on (ArtLevArtGid = calcArtGid and ArtLevIsDefault = 1)
           inner join tabNawFile             on (nawFilNawGid = ArtLevNawGid)
      where (NawFilNummer between @SelecterenVan and @SelecterenTm) and (calcKostprijsBerekening = 1 or calcVerkoopprijsBerekening = 1);
  when 3 /*Opbrengstgroep*/   then
    insert into TempArtikel (calcArtGid, calcRcptGid, calcRcpeGid, calcBTWcode, calcPrijsPer, calcAantalDecimalenPrijzen, calcVerkprijsIsIncl)
      select                 calcArtGid, calcRcptGid, calcRcpeGid, calcBTWcode, calcPrijsPer, calcAantalDecimalenPrijzen, calcVerkprijsIsIncl
      from vwArtikelMetDefaultRecept
           inner join tabOpbrengstgroep on OpbrGrpGId = calcOpbrGrpGId
      where (OpbrGrpNummer between @SelecterenVan and @SelecterenTm) and (calcKostprijsBerekening = 1 or calcVerkoopprijsBerekening = 1);
  end case;

  // Gegevens aanvullen vanuit eindproductregel
  update tempArtikel
  set calcAantalProductiePerBatch             = RcptBatchDefault,
      calcRcpeAantal                          = RcpeAantal,
      calcBerekenArtKostprijsBerekening       = RcpeBerekenArtKostprijsBerekening,
      calcBerekenArtKostprijsPercentage       = RcpeBerekenArtKostprijsPercentage,
      calcBerekenArtVerkoopprijsBerekening    = RcpeBerekenArtVerkoopprijsBerekening,
      calcBerekenArtVerkoopprijsPercentage    = RcpeBerekenArtVerkoopprijsPercentage
  from tempArtikel
       inner join tabReceptuurEindproduct on RcpeGid = calcRcpeGid
       inner join tabReceptuur            on RcptGid = calcRcptGid;

  // Gegevens aanvullen vanuit componentenregel (Bereken de Kostprijs en de verkoopprijs)
  update TempArtikel
  Set calcHulpKostprijsVanComponenten =
        // Alleen berekenen als nodig!
        if    (@KostPrijsberekenen = 1 and calcBerekenArtKostprijsBerekening = 1 /*obv kostprijs componenten*/)               // Kostprijs berekenen
           or (@VerkoopPrijsberekenen = 1 and calcBerekenArtVerkoopprijsBerekening = 3 /*obv berekende kostprijs*/) then      // Verkoopprijs obv kostprijs
          (PrijzenBerekenenObvRecepten_Kostprijs(calcRcptGid, calcAantalProductiePerBatch) * calcPrijsPer)
        endif,
      calcHulpVerkoopprijsVanComponenten =
        if (@VerkoopPrijsberekenen = 1) and (calcBerekenArtVerkoopprijsBerekening <> 0 /*niet*/) then
          // Alleen als we wellicht de verkoopprijs gaan berekenen
          (PrijzenBerekenenObvRecepten_Verkoopprijs(calcRcptGid, calcAantalProductiePerBatch, calcVerkprijsIsIncl, calcBTWcode) * calcPrijsPer)
        endif;

  // Kost- en verkoopprijzen berekenen volgens opgegeven methode (o.b.v. van wat en percentage)
  update TempArtikel
  set
      calcKostprijsEx    = round(calcHulpKostprijsVanComponenten * (calcBerekenArtKostprijsPercentage / 100), calcAantalDecimalenPrijzen),

      calcVerkoopprijs   = case calcBerekenArtVerkoopprijsBerekening
                             when 1 /*obv kostprijs componenten*/ then
                               calcHulpKostprijsVanComponenten * (calcBerekenArtVerkoopprijsPercentage / 100)

                             when 2 /*obv verkoopprijs componenten*/ then
                               // Verkoopprijs totaliseren en afronden volgens vaste gegevens
                               calcHulpVerkoopprijsVanComponenten * (calcBerekenArtVerkoopprijsPercentage / 100)

                             when 3 /*obv berekende kostprijs*/ then
                               round(calcHulpKostprijsVanComponenten * (calcBerekenArtKostprijsPercentage / 100), calcAantalDecimalenPrijzen) /*De berekende kostprijs afgerond, zelfde berekening als hierboven*/
                                * (calcBerekenArtVerkoopprijsPercentage / 100)

                           end;//case

  // Bedragen per artikel totaliseren en in prijswijzigingen zetten
  begin
    declare local temporary table tempartikelTotalen(
      calcArtGid          integer,
      calcPrijsPer        numeric(15,3),
      calcKostprijsEx     numeric(15,3),
      calcVerkprijsIsIncl smallint,
      calcVerkoopprijs    numeric(15,3)
    ) on commit preserve rows;

    // Voor eenzelfde artikel de losse regels bij elkaar tellen
    // LET OP! Hier mag maar 1 artikelregel uit komen, anders gaat de MERGE hieronder fout!
    insert into tempartikelTotalen(calcArtGid, calcPrijsPer, calcKostprijsEx, calcVerkprijsIsIncl, calcVerkoopprijs)
    select calcArtGid,
           calcPrijsPer,
           sum(calcKostprijsEx)/sum(calcRcpeAantal),
           calcVerkprijsIsIncl,
           ArtikelPrijsAfronding((sum(calcVerkoopprijs)/sum(calcRcpeAantal)), calcAantalDecimalenPrijzen)
    from tempArtikel
    group by calcArtgid, calcVerkprijsIsIncl, calcPrijsPer, calcAantalDecimalenPrijzen;


    //Kijk of er prijzen zijn groter dan numeric(15,3)
    if exists(select first 1
              from tempartikelTotalen
              where (calcKostprijsEx not between -10000000000 and 10000000000)
                 or (calcVerkoopprijs not between -10000000000 and 10000000000)
             ) then
      set @foutnummer = 1;
    end if;

    if @foutnummer = 0 then
      // Haal de prijswijzigingskop ID op.
      select first PwkId into @PwkId from tabPrijsWijzigingskop;

      //Update bestaande prijswijzigingsrecords en voeg niet bestaande toe
      merge into tabPrijsWijzigingsregel(PwrPwkId             , PwrArtGid , PwrPrijsPer , PwrKostprijs    , PwrIsVerkoopprijsIncl , PwrVerkoopprijs)
        using (
                select                   @PwkId as calcPwkGid , calcArtGid, calcPrijsPer, calcKostprijsEx , calcVerkprijsIsIncl   , calcVerkoopprijs
                from TempArtikelTotalen
                inner join tabartikel normArt on normArt.artgid = calcArtGid and (normArt.artKostPrijsex <> calcKostprijsEx or normArt.ArtVerkprijs <> calcVerkoopprijs or normArt.ArtVerkPrijsIsIncl <> calcVerkprijsIsIncl or normArt.ArtPrijsPer <> calcPrijsPer)
              ) t
        on (PwrPwkId = t.calcPwkGid and PwrArtGid = t.calcArtGid)
        when matched then update set  PwrPrijsPer           = t.calcPrijsPer,
                                      PwrKostprijs          = if @KostPrijsberekenen = 1    and t.calcKostprijsEx is not null  then t.calcKostprijsEx      else PwrKostprijs           endif,
                                      PwrIsVerkoopprijsIncl = if @VerkoopPrijsberekenen = 1 and t.calcVerkoopprijs is not null then t.calcVerkprijsIsIncl  else PwrIsVerkoopprijsIncl  endif,
                                      PwrVerkoopprijs       = if @VerkoopPrijsberekenen = 1 and t.calcVerkoopprijs is not null then t.calcVerkoopprijs     else PwrVerkoopprijs        endif
        when not matched then insert;
    end if;
  end;

  //call TraceEind('PrijzenBerekenenObvRecepten');
end;

Create or Replace Function PrijzenBerekenenObvRecepten_Kostprijs(
  in @calcRcptGid integer,
  in @RcptAantalPerBatch numeric(15,3)
) returns numeric(30,6)
begin
  declare @Kostprijs numeric(30,6);
  Select sum((ArtKostprijsEx/ArtPrijsPer) * RcpcAantal /
             // Kostprijs terugrekenen naar 1 productierun
             case RcpcVerbruik
               when 0 /*Per recept*/ then
                 1
               when 1 /*Per verwerking*/ then
                 @RcptAantalPerBatch
               when 2 /*per X recepten*/ then
                 @RcptAantalPerBatch / ceiling(@RcptAantalPerBatch / RcpcVerbruikAantal)
             end
            )
  into @Kostprijs
  from tabartikel
  inner join tabReceptuurComponent on ArtGid = RcpcArtGid
  where RcpcRcptGid = @calcRcptGid;

  return @Kostprijs;
end;



Create or Replace Function PrijzenBerekenenObvRecepten_Verkoopprijs(
  in @RcptGid          integer,
  in @RcptAantalPerBatch numeric(15,3),
  in @VerkprijsIsIncl  smallint,
  in @BTWcodeArtikel   integer
) returns numeric(30,6)
//MR 13-feb-2018  : Deze function berekent de verkoopprijs van een artikel obv de componenten van een recept
//Aanleiding      : PrijzenBerekenenObvRecepten gebruikt deze function voor het bepalen van de verkoopprijs.
//Test            : select PrijzenBerekenenObvRecepten_Verkoopprijs(52490012,0,1) from dummy;
begin
  declare @Verkoopprijs numeric;
  //call TraceBegin('PrijzenBerekenenObvRecepten_Verkoopprijs');

 Select sum( case
               when (ArtVerkprijsIsIncl = 0) then
                 //Excl. BTW, dus overnemen en evt. omrekenen naar incl. btw volgens BTWcode van eindproduct
                 (ArtVerkprijs/ArtPrijsPer) * RcpcAantal * if @VerkprijsIsIncl = 1 then (1 + BTWEindproduct.BtwPercentage / 100) else 1 endif
               when (ArtVerkprijsIsIncl = 1) and (@VerkprijsIsIncl = 1) and (BTWComponent.BtwPercentage = BTWEindproduct.BtwPercentage) then
                 //Beiden incl. BTW met zelfde BTW%, dus overnemen naar incl. btw van eindproduct
                 (ArtVerkprijs/ArtPrijsPer) * RcpcAantal
               when (ArtVerkprijsIsIncl = 1) then
                 // Component incl. BTW, dus exclusief maken en evt. omrekenen naar incl. btw volgens BTWcode van eindproduct
                 (ArtVerkprijs/ArtPrijsPer) * (100/( BTWComponent.BtwPercentage+100)) * RcpcAantal * if @VerkprijsIsIncl = 1 then (1 + BTWEindproduct.BtwPercentage / 100) else 1 endif
             end /
             // Kostprijs terugrekenen naar 1 productierun, dus delen door het aantal productieruns
             // Als dus per 5 runs een machine wordt afgesteld voor 500 euro, dan geldt voor 1 run 500/5=100 om in de prijs door te rekenen
             case RcpcVerbruik
               when 0 /*Per recept*/ then
                 1
               when 1 /*Per verwerking*/ then
                 @RcptAantalPerBatch
               when 2 /*per X recepten*/ then
                 @RcptAantalPerBatch / ceiling(@RcptAantalPerBatch / RcpcVerbruikAantal)
             end

            ) into @Verkoopprijs
  from tabartikel
    inner join tabReceptuurComponent on ArtGid = RcpcArtGid
    inner join tabBtw BTWComponent   on BTWComponent.BtwCode = ArtBTWcode
    inner join tabBtw BTWEindproduct on BTWEindproduct.BtwCode = @BTWcodeArtikel
  where RcpcRcptGid = @RcptGid;

  //call TraceEind('PrijzenBerekenenObvRecepten_Verkoopprijs');
  return @Verkoopprijs;
end;



create or replace procedure ProductieAdviesAanmaken(in @ConnectionId integer,
                                                    in @LoginTime datetime,
                                                    // artikel selectie
                                                    in @ArtSelect smallint,
                                                    in @VanArt nchar(40),
                                                    in @TotArt nchar(40),
                                                    // magazijn selectie
                                                    in @MagSelect smallint,
                                                    in @VanMag nchar(40),
                                                    in @TotMag nchar(40),
                                                    // Produceren voor voorraad
                                                    in @ProducerenVoorVoorraad smallint,
                                                    in @RekeningHoudenMetProductieOrders smallint,
                                                    in @RekeningHoudenMetBestellingen smallint,
                                                    in @PerMagazijnAparteProductie smallint,
                                                    in @AlleenIndienVoorraadBenedenMinimumVoorraad smallint,
                                                    in @RekeningHoudenMetProductieAdviezen smallint,
                                                    // Produceren voor verkooporders
                                                    in @ProducerenVoorVerkoopOrders smallint,
                                                    in @RekeninghoudenMetSelectie smallint,
                                                    in @VerkoopOrderSelectie smallint,
                                                    in @VanOrder nchar(40),
                                                    in @TotOrder nchar(40),
                                                    in @AparteProductieOrder smallint,
                                                    //  Uitgaande parameters
                                                    out @Resultaat smallint, //0=ok, 1=Geen vrij nummer
                                                    out @PakGid integer)
begin
  //----- Productie-advies aanmaken -------
  declare @LockString   nchar(100);
  declare @AantalVerkoopOrderAdviesRegelsAangemaakt integer;

  //call TraceBegin('ProductieAdviesAanmaken > ');

  set @Resultaat = 0;

  //Maak eerst de kop aan
  call ProductieAdviesKopAanmaken( @ArtSelect, @VanArt, @TotArt,
                                   @MagSelect, @VanMag, @TotMag,
                                   @ProducerenVoorVoorraad, @RekeningHoudenMetProductieOrders, @RekeningHoudenMetBestellingen, @PerMagazijnAparteProductie, @AlleenIndienVoorraadBenedenMinimumVoorraad,
                                   @RekeningHoudenMetProductieAdviezen,
                                   @ProducerenVoorVerkoopOrders, @RekeninghoudenMetSelectie , @VerkoopOrderSelectie, @VanOrder, @TotOrder, @AparteProductieOrder,
                                   @PakGid);

  if (@PakGid is not null) then
    //Plaats een lock op het nieuwe productieadvies
    set @LockString = 'PakGid = '+string(@PakGid);
    call LockSetOnId(@ConnectionId, @LoginTime, 1, 'tabProductieAdviesKop', @LockString, null);

    // Productieadviesregels voor magazijnen aanmaken.
    if (@ProducerenVoorVoorraad = 1) then
      call ProductieAdviesRegelsAanmakenVoorVoorraden(@PakGid,
                                                      @ArtSelect, @VanArt, @TotArt,
                                                      @MagSelect, @VanMag, @TotMag,
                                                      @RekeningHoudenMetProductieOrders, @RekeningHoudenMetBestellingen, @PerMagazijnAparteProductie,
                                                      @AlleenIndienVoorraadBenedenMinimumVoorraad, @RekeningHoudenMetProductieAdviezen);
    endif;

    //Productieadviesregels voor verkooporderregels aanmaken.
    if (@ProducerenVoorVerkoopOrders = 1) then
      call ProductieAdviesRegelsAanmakenVoorVerkoopOrders(@PakGid,
                                                          @ArtSelect, @VanArt, @TotArt,
                                                          @MagSelect, @VanMag, @TotMag,
                                                          @RekeninghoudenMetSelectie,
                                                          @VerkoopOrderSelectie, @VanOrder, @TotOrder, @AparteProductieOrder);
    endif;

    //Controleer of er regels zijn aangemaakt. Zoniet, dan de kop verwijderen
    if not exists(select 1 from tabProductieAdviesRegel where PrrPakGid = @PakGid) then
      delete tabProductieAdviesKop where PakGid = @PakGid;
      call LockreleaseOnId(@ConnectionId, @LoginTime, 1, 'tabProductieAdviesKop', @LockString);
      set @PakGid = null;
    end if;
  else
    //Resultaat is 1. Dit betekent dat er geen nummer meer vrij is. 1 t/m 999 zijn in gebruik
    set @Resultaat = 1;
  end if;

  //Verwijder het record voor de voortgangsbalk
  call ProgressDelete();

  //call TraceEind('ProductieAdviesAanmaken > @PakGid = ' + string(@PakGid));
end;

create or replace procedure ProductieAdviesKopAanmaken( // artikel selectie
                                                        in @ArtSelect smallint,
                                                        in @VanArt nchar(40),
                                                        in @TotArt nchar(40),
                                                        // magazijn selectie
                                                        in @MagSelect smallint,
                                                        in @VanMag nchar(40),
                                                        in @TotMag nchar(40),
                                                        // Produceren voor voorraad
                                                        in @ProducerenVoorVoorraad smallint,
                                                        in @RekeningHoudenMetProductieOrders smallint,
                                                        in @RekeningHoudenMetBestellingen smallint,
                                                        in @PerMagazijnAparteProductie smallint,
                                                        in @AlleenIndienVoorraadBenedenMinimumVoorraad smallint,
                                                        in @RekeningHoudenMetProductieAdviezen smallint,
                                                        // Produceren voor verkooporders
                                                        in @ProducerenVoorVerkoopOrders smallint,
                                                        in @RekeninghoudenMetSelectie smallint,
                                                        in @VerkoopOrderSelectie smallint,
                                                        in @VanOrder nchar(40),
                                                        in @TotOrder nchar(40),
                                                        in @AparteProductieOrder smallint,
                                                        //  Het aangemaakte Productie-advieskopgid teruggeven
                                                        out @PakGid integer)
begin
  declare @NieuwPakNummer integer;

  //call TraceBegin('ProductieAdviesKopAanmaken');
  set @PakGid = null;

  set @NieuwPakNummer = GeefEersteUniekeNummer('tabProductieAdviesKop', 'PakNummer', '', 1, 999, 2);

  if (@NieuwPakNummer is not null) then
    insert into tabProductieAdviesKop (PakNummer, PakOmschrijving,
                                       PakArtSelect, PakArtVan, PakArtTot,
                                       PakMagSelect, PakMagVan, PakMagTot,
                                       PakProducerenVoorVoorraad, PakRekeningHoudenProducties, PakRekeningHoudenBestellingen, PakAparteProductiePerMagazijn, PakIndienVoorraadBenedenMinimum,
                                       PakRekeningHoudenMetProductieAdviezen,
                                       PakProducerenVoorVerkoopOrders, PakRekeninghoudenMetSelectie, PakOrderSelect, PakOrderTot, PakOrderVan,
                                       PakAparteProductieOrder)
    values(@NieuwPakNummer, _A('Gegenereerd productieadvies'),
           @ArtSelect, @VanArt, @TotArt,
           @MagSelect, @VanMag, @TotMag,
           @ProducerenVoorVoorraad, @RekeningHoudenMetProductieOrders, @RekeningHoudenMetBestellingen, @PerMagazijnAparteProductie,  @AlleenIndienVoorraadBenedenMinimumVoorraad,
           @RekeningHoudenMetProductieAdviezen,
           @ProducerenVoorVerkoopOrders, @RekeninghoudenMetSelectie , @VerkoopOrderSelectie, @TotOrder, @VanOrder,
           @AparteProductieOrder);

    set @PakGid = @@Identity;
  endif;

  //ProductieAdviesKopAanmaken-lock weer vrijgeven
  call ReleaseLockOpGeefEersteUniekeNummer('tabProductieAdviesKop', 'PakNummer');

  //call TraceEind('ProductieAdviesKopAanmaken > @PakGid = ' + string(@PakGid));
end;

create or replace procedure ProductieAdviesRegelsAanmakenVoorVerkoopOrders(
                                                    in @PakGid integer,

                                                    // artikel en magazijn selectie
                                                    in @ArtSelect smallint,
                                                    in @VanArt nchar(40),
                                                    in @TotArt nchar(40),

                                                    in @MagSelect smallint,
                                                    in @VanMag nchar(40),
                                                    in @TotMag nchar(40),

                                                    // verkooporders
                                                    in @RekeninghoudenMetSelectie smallint,
                                                    in @VerkoopOrderSelectie smallint,
                                                    in @VanOrder nchar(40),
                                                    in @TotOrder nchar(40),
                                                    in @AparteProductieOrder smallint)
begin
  //----- Productie-adviesregels aanmaken voor verkooporders -------
  declare @ProgressCreate integer = 0;

  //call TraceBegin('ProductieAdviesRegelsAanmakenVoorVerkoopOrders');
  call ProgressCreate(1, 2, _U('Aanmaken voor verkooporders'));

  // Adviesregels toevoegen voor verkooporderregels
  // Verzamel all orderregel gids waarvan we de backorderaantallen moeten verwerken.
  // En het recept welke bij de orderregel is ingevuld
  for @Cursor As Cursor_TeProducerenAdviesRegels Cursor For
  select
    OrrGid                                                                @OrrGid,
    OrrArtGid                                                             @ArtGid,
    OrrMagGid                                                             @MagGid,
    vwRcptGid                                                             @RcptGid,
    OrrAantalBackorderVrrdEenh                                            @AantalMaalTeProducerenVolgensBackorder,
    isNull(vwRcptBatchMinimum,0)                                          @RcptBatchMinimum,
    isNull(vwRcptBatchMaximum,0)                                          @RcptBatchMaximum,
    sum(isNull(vwRcpeAantal,0))                                           @RcpeAantal,
    sum(isNull(vwBatchMinimumMaalAantalEindproducten,0))                  @BatchMinimumMaalAantalEindproducten,
    sum(isNull(vwBatchMaximumMaalAantalEindproducten,0))                  @BatchMaximumMaalAantalEindproducten,
    rank() OVER AantalWindow                                              @AantalRecords //Voor de progressBar
  from tabOrderRegel
  inner join tabMagazijn                   on (MagGid = OrrMagGid)
  inner join tabArtikel                    on (ArtGid = OrrArtGid)
  inner join tabOrderKop                   on (OrkGid = OrrOrkGid)
  left outer join vwProductieAdviesRegelReceptuurGegevens on (vwrcpeArtGid = OrrArtGid) and (vwRcptGid = isNull(OrrRcptGid, (select first vwrcptGid
                                                                                                                             from vwProductieAdviesRegelReceptuurGegevens
                                                                                                                             where (vwrcpeArtGid = OrrArtGid)
                                                                                                                               and (vwAantalReceptenVoorArtikel = 1))
                                                                                                                )
                                                                                            )
//  left outer join tabReceptuur             on (RcptGid = OrrRcptGid)                                    // omdat we recept minimum en maximum nodig hebben
//  left outer join tabReceptuurEindproduct  on (RcpeRcptGid = RcptGid) and (rcpeArtGid = OrrArtGid)      // omdat we RcpeAantal nodig hebben
  where (OrrProductie = 1)
    and (OrkGoedgekeurd = 1)                                                                            // en alleen goedgekeurde verkooporders
    and (OrrAantalBackorderVrrdEenh > 0)                                                                // en aantal in backorder groter dan 0.
    and (ArtSoort = 2)                                                                                  // en alleen artikelen
    and (ArtIsGebruikVoorProductieAdvies <> 0)                                                          // en alleen artikelen die via productie-advies gaan
    and not exists(select PrdOesGid from tabProductieOrderEindproductSpec where PrdOesOrrGid = orrGid)  // en checken of er al geen productieorder voor is
    and not exists(select PrrGid    from tabProductieAdviesRegel where PrrOrrGid = orrGid)              // en checken of er al geen productieadvies voor is
    and (
             (@RekeninghoudenMetSelectie = 0)
          or (
                  ( // artikelselectie
                    (@ArtSelect = 0 AND (ArtCode      BETWEEN @VanArt AND @TotArt)) OR
                    (@ArtSelect = 1 AND (ArtZoekCode  BETWEEN @VanArt AND @TotArt)) OR
                    (@ArtSelect = 2 AND (ArtOms       BETWEEN @VanArt AND @TotArt))
                  )
              and ( // magazijnselectie
                    (@MagSelect = 0 AND (right('000'+string(tabMagazijn.MagCode),3) BETWEEN @VanMag AND @TotMag )) OR
                    (@MagSelect = 1 AND (tabMagazijn.MagZoekcode  BETWEEN @VanMag AND @TotMag )) OR
                    (@MagSelect = 2 AND (tabMagazijn.MagOms       BETWEEN @VanMag AND @TotMag ))
                  )
            )
        )
    and ( // selectie op ordernummer of debiteurnummer
          (@VerkoopOrderSelectie = 0 and (OrkNummer between @VanOrder and @TotOrder)) or
          (@VerkoopOrderSelectie = 1 and OrkNawGid in (select NawFilNawGid from tabNawFile where NawFilNummer between @VanOrder and @TotOrder))
        )
  Group By OrrGid, OrrArtGid, OrrMagGid,  vwrcptGid, OrrAantalBackorderVrrdEenh, vwRcptBatchMinimum, vwRcptBatchMaximum, vwrcpeArtGid
  WINDOW AantalWindow as (order by OrrGid desc)  //De Orderby van dit statement en van de query niet veranderen. Aantal bij het eerste record, geeft het aantal records van deze select terug

  Order By OrrGid
  for read only
  do
    if @ProgressCreate = 0 then
      call ProgressCreate(1, @AantalRecords, _U('Aanmaken voor verkooporders'));
      set @ProgressCreate = 1;
    end if;

    call ProgressAdd(1);

    insert into tabProductieAdviesRegel (PrrPakGid, PrrVoorraadWaarvanuitWordtGegaan, PrrAantalTeKort, PrrAantalMaalTeProduceren, PrrArtGid, PrrMagGid, PrrRcptGid, PrrOrrGid)
    values(
      @PakGid,                  // PrrPakGid
      0,                                        // PrrVoorraadWaarVanuitWordtGegaan ???
      @AantalMaalTeProducerenVolgensBackorder,  // PrrAantalTeKort
      @AantalMaalTeProducerenVolgensBackorder,
      @ArtGid,                // PrrArtGid
      @MagGid,                // PrrMagGid
      @RcptGid,               // PrrRcptGid
      @OrrGid                 // PrrOrrGid
      );
//    from vwProductieAdviesRegelReceptuurGegevens
//    where vwRcpeArtGid = @ArtGid;
  end for;

//call TraceEind('ProductieAdviesRegelsAanmakenVoorVoorraden');
end;

create or replace procedure ProductieAdviesRegelsAanmakenVoorVoorraden( in @PakGid integer,
                                                                        // artikel selectie
                                                                        in @ArtSelect smallint,
                                                                        in @VanArt nchar(40),
                                                                        in @TotArt nchar(40),
                                                                        // magazijn selectie
                                                                        in @MagSelect smallint,
                                                                        in @VanMag nchar(40),
                                                                        in @TotMag nchar(40),
                                                                        // Produceren voor voorraad
                                                                        in @RekeningHoudenMetProductieOrders smallint,
                                                                        in @RekeningHoudenMetBestellingen smallint,
                                                                        in @PerMagazijnAparteProductie smallint,
                                                                        in @AlleenIndienVoorraadBenedenMinimumVoorraad smallint,
                                                                        in @RekeningHoudenMetProductieAdviezen smallint)
begin
  //----- Productie-adviesregels aanmaken voor voorraden -------
  declare @ProgressCreate integer = 0;

  //call TraceBegin('ProductieAdviesRegelsAanmakenVoorVoorraden');
  call ProgressCreate(1, 2, _U('Aanmaken voor voorraden'));

  for @Cursor As Cursor_TeProducerenAdviesRegels Cursor For
  SELECT
    MagGid                                                                                                                                    @MagGid,
    ArtGid                                                                                                                                    @ArtGid,
    sum(calcMinimumVoorraad)                                                                                                                  @MinimumVoorraad,
    sum(calcMaximumVoorraad)                                                                                                                  @MaximumVoorraad,
    sum(calcInBestellingVerwerkt)                                                                                                             @BstRglAantalBesteldVerwerkt,
    sum(calcInBestellingGoedgek)                                                                                                              @BstRglAantalBesteldGoedGek,
    sum(calcInBestellingConcept)                                                                                                              @BstRglAantalBesteldNietGoedGek,
    (@BstRglAantalBesteldGoedGek + @BstRglAantalBesteldNietGoedGek)                                                                           @BstRglAantalBesteldNietVerwerkt,
    ((case @RekeningHoudenMetBestellingen              /* Rekening houden met bestellingen */
      when 0 then @BstRglAantalBesteldNietVerwerkt     //0 = Verwerkte en niet-verwerkte bestellingen
      when 1 then @BstRglAantalBesteldGoedGek          //1 = Verwerkte en Goedgekeurde niet-verwerkte bestellingen
      else 0.00 end                                    //2 = Alleen de verwerkte bestellingen
      ) + @BstRglAantalBesteldVerwerkt)                                                                                                       @BstRglAantalBesteldMeenemen,
    isnull(
    if @RekeningHoudenMetProductieOrders <> 0 /*niet*/ then
      sum((isnull(calcInEindProductie, 0) - isnull(calcGereserveerdProductie, 0))*
          /* Alleen optellen als de status van de prod.order overeenkomt!*/
          (if     (   (@RekeningHoudenMetProductieOrders = 1 /*Ingepland+onderhanden*/ and PrdOkStatus in (2, 3))
                   or (@RekeningHoudenMetProductieOrders = 2 /*Alle (minus Gereed)*/))
              and ((@PerMagazijnAparteProductie = 0) or (calcMagGid = MagGid)) then 1 else 0 endif)
         )
    endif, 0.0)                                                                                                                               @TeProducerenInProdOrders,
    /* Econ.voorraad EXCL. productie en bestellingen minus rekening mee te houden AantalInBestelling plus Productie rekening mee te houden*/
    isNull(sum(if calcPrdOkGid is null and calcBstKopGid is null then calcEconomischeVoorraad endif),0.00)
    + @BstRglAantalBesteldMeenemen + @TeProducerenInProdOrders + @AantalMaalTeProduceren                                                      @VoorraadWaarVanuitWordtGegaan,
    (@MinimumVoorraad - @VoorraadWaarVanuitWordtGegaan)                                                                                       @TeKortMinimum,
    (@MaximumVoorraad - @VoorraadWaarVanuitWordtGegaan)                                                                                       @TeKort,
    (
    IF (@TeKort <= 0) THEN                                                          /*geen tekort*/
      0                                                                             /*te produceren niets*/
    ELSE                                                                            /*wel tekort*/
      if @TeKort < @TeKortMinimum Then @TeKortMinimum else @TeKort endif            /*te produceren Tekort*/
    ENDIF
    )                                                                                                                                         @TeProduceren,
    if @RekeningHoudenMetProductieAdviezen = 1 then
      (select isNull(sum(prrAantalMaalTeProduceren),0) from tabProductieAdviesRegel where prrArtgid = artgid and prrmaggid = maggid)
    else
      0
    endif                                                                                                                                     @AantalMaalTeProduceren,
    rank() OVER AantalWindow                                                                                                                  @AantalRecords //Voor de progressBar

  FROM
  (
    select
      calcArtGid,
      calcMagGid,
      calcPrdOkGid,
      calcBstKopGid,
      calcMinimumVoorraad,
      calcMaximumVoorraad,
      calcInBestellingVerwerkt,
      calcEconomischeVoorraad,
      calcInBestellingGoedgek,
      calcInBestellingConcept,
      calcInEindProductie,
      calcGereserveerdProductie
    from vwVoorraadAantallen
    UNION ALL
    select
      calcArtGid,
      calcMagGid,
      calcPrdOkGid,
      calcBstKopGid,
      calcMinimumVoorraad,
      calcMaximumVoorraad,
      calcInBestellingVerwerkt,
      calcEconomischeVoorraad,
      calcInBestellingGoedgek,
      calcInBestellingConcept,
      calcInEindProductie,
      calcGereserveerdProductie
    from vwProductieOrderNieuwEnInteplannenProducties
    where (@RekeningHoudenMetProductieOrders = 2) /*Alle producties*/
  ) tabAllesMetView
  inner join      tabMagazijn           on (MagGid = calcMagGid)
  inner join      tabArtikel            on (ArtGid = calcArtGid)
  left outer join tabProductieOrderKop  on PrdOkGid = calcPrdOkGid
  //inner join tabReceptuurEindproduct on RcpeArtGid = ArtGid

  WHERE (ArtSoort = 2)
    AND ( // artikelselectie
          (@ArtSelect = 0 AND (ArtCode      BETWEEN @VanArt AND @TotArt)) OR
          (@ArtSelect = 1 AND (ArtZoekCode  BETWEEN @VanArt AND @TotArt)) OR
          (@ArtSelect = 2 AND (ArtOms       BETWEEN @VanArt AND @TotArt))
        )
    AND ( // magazijnselectie
          (@MagSelect = 0 AND (right('000'+string(tabMagazijn.MagCode),3) BETWEEN @VanMag AND @TotMag )) OR
          (@MagSelect = 1 AND (tabMagazijn.MagZoekcode  BETWEEN @VanMag AND @TotMag )) OR
          (@MagSelect = 2 AND (tabMagazijn.MagOms       BETWEEN @VanMag AND @TotMag ))
        )
    AND (ArtIsGebruikVoorProductieAdvies <> 0)

  GROUP BY
    MagGid,
    ArtGid
  HAVING
    (@AlleenIndienVoorraadBenedenMinimumVoorraad = 0 OR @TeKortMinimum > 0)
  WINDOW AantalWindow as (order by ArtGid desc)  //De Orderby van dit statement en van de query niet veranderen. Aantal bij het eerste record, geeft het aantal records van deze select terug
  ORDER BY
    ArtGid
  for read only
  do
    if @ProgressCreate = 0 then
      call ProgressCreate(1, @AantalRecords, _U('Aanmaken voor voorraden'));
      set @ProgressCreate = 1;
    end if;

    call ProgressAdd(1);

    //Voor een recept een regel aanmaken in het productie advies. Zijn er meerdere recepten, dan word er NULL ingevuld
    insert into tabProductieAdviesRegel (PrrPakGid, PrrVoorraadWaarvanuitWordtGegaan, PrrAantalTeKort, PrrAantalMaalTeProduceren, PrrArtGid, PrrMagGid, PrrRcptGid)
    Select  first @PakGid,
                  @VoorraadWaarVanuitWordtGegaan,
                  @TeProduceren,
                  @TeProduceren,
                  @ArtGid,
                  @MagGid,
                  if (vwAantalReceptenVoorArtikel = 1) then vwRcptGid endif
    from vwProductieAdviesRegelReceptuurGegevens
    where vwRcpeArtGid = @ArtGid;
  end for;

//call TraceEind('ProductieAdviesRegelsAanmakenVoorVoorraden');
end;

if exists (select 1 from sys.sysProcedure where proc_name='MarkeerProductieOrderVoorVerwerken') then
  drop procedure MarkeerProductieOrderVoorVerwerken;
end if;

create procedure MarkeerProductieOrderVoorVerwerken(in @ProductieOrderKopGid integer, in @Volgnr integer, in @Verwerken smallint, in @Resultaat long nvarchar)
begin
  set @@ErrorTextProcedure = 'MarkeerProductieOrderVoorVerwerken';
  //call TraceBegin(@@ErrorTextProcedure);

  if exists(select 1 from tmpMeerdereProductieOrdersVerwerken where PoVwkProductieOrderKopGid = @ProductieOrderKopGid and PoVwkVolgNr = @Volgnr) then
    // verwerking bestaat al
    // dan updaten
    update tmpMeerdereProductieOrdersVerwerken
       set PoVwkVerwerken = @Verwerken,
           PoVwkResultaat = @Resultaat
    where PoVwkProductieOrderKopGid = @ProductieOrderKopGid and PoVwkVolgNr = @Volgnr
  else
    // verwerking bestaat niet
    // dan inserten
    insert into tmpMeerdereProductieOrdersVerwerken(PoVwkProductieOrderKopGid, PoVwkVerwerken, PoVwkVolgNr, PoVwkResultaat)
                                             values(@ProductieOrderKopGid, @Verwerken, @Volgnr, @Resultaat )
  endif

  //call TraceEind('MarkeerProductieOrderVoorVerwerken');
end;


//$Workfile: ProdOrderCompDoorschuivenRegelNrs.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// **********************************************
// Productieorder: Component: doorschuiven regels
// **********************************************

if exists (select 1 from sys.sysProcedure where proc_name='ProdOrderCompDoorschuivenRegelNrs') then
  drop procedure ProdOrderCompDoorschuivenRegelNrs;
end if;

create procedure ProdOrderCompDoorschuivenRegelNrs(
 in @PrdOkGid   integer,
 in @VanRegelNr integer,   // Vanaf welk regelnummer doorschuiven (indien leeg, dan wordt 1 gebruikt!)
 in @Delta      integer    // Indien leeg, dan wordt 1 gebruikt (1 doorschuiven), maar nu kan ook worden teruggescvhoven indien nodig (@delta=-1)
)
begin
  set @@ErrorTextProcedure = 'ProdOrderCompDoorschuivenRegelNrs(@PrdOkGid='+string(@PrdOkGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @Delta is null then
    set @Delta = 1;
  end if;
  if @VanRegelNr is null then
    set @VanRegelNr = 1
  end if;

  update tabproductieordercomponent
  set    PrdOcRegelNr = PrdOcRegelNr + @Delta
  where  PrdOcPrdOkGid = @PrdOkGid
     and PrdOcRegelNr >= @VanRegelNr
  order by PrdOcRegelNr * sign(@Delta) desc; // Bij negatief moeten we vanaf de kleinste werken, anders vanaf de grootste!

  set @@ErrorTextProcedure = 'ProdOrderCompDoorschuivenRegelNrs(@PrdOkGid='+string(@PrdOkGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProdOrderCompUitdelenRegelNr.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// ************************************************************************************
// ProductieOrder: Component: regelnummers opnieuw uitdelen in volgorde van regelnummer
// ************************************************************************************

if exists (select 1 from sys.sysProcedure where proc_name='ProdOrderCompUitdelenRegelNr') then
  drop procedure ProdOrderCompUitdelenRegelNr;
end if;

create procedure ProdOrderCompUitdelenRegelNr(
 in @PrdOkGid integer
)
begin
  set @@ErrorTextProcedure = 'ProdOrderCompUitdelenRegelNr(@PrdOkGid='+string(@PrdOkGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  // Eerst de regels een negatief doorlopend nummer geven (zodat die altijd uniek zijn!)
  update tabproductieordercomponent
  set    PrdOcRegelNr = -number()
  where  PrdOcPrdOkGid = @PrdOkGid
  order by PrdOcRegelNr;

  // En vervolgens de regels een positief doorlopende nummering geven
  update tabproductieordercomponent
  set    PrdOcRegelNr = number()
  where  PrdOcPrdOkGid = @PrdOkGid
  order by PrdOcRegelNr desc;

  set @@ErrorTextProcedure = 'ProdOrderCompUitdelenRegelNr(@PrdOkGid='+string(@PrdOkGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


//$Workfile: ProdOrderCompVerplaatsRegelNr.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// ********************************************
// Productieorder: Component: verplaatsen regel
// ********************************************

if exists (select 1 from sys.sysProcedure where proc_name='ProdOrderCompVerplaatsRegelNr') then
  drop procedure ProdOrderCompVerplaatsRegelNr;
end if;

create procedure ProdOrderCompVerplaatsRegelNr(
 in @PrdOkGid    integer,
 in @VanRegelNr  integer,   // Vanaf welk regelnummer verplaatsen
 in @NaarRegelNr integer    // Naar  welk regelnummer verplaatsen
)
begin
  set @@ErrorTextProcedure = 'ProdOrderCompVerplaatsRegelNr(@PrdOkGid='+string(@PrdOkGid)+', @VanRegelNr=' + string(@VanRegelNr)+', @NaarRegelNr=' + string(@NaarRegelNr) + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  if @VanRegelNr <> @NaarRegelNr then
    // Eerst de betreffende regel een speciaal nummer geven

    update tabproductieordercomponent
    set    PrdOcRegelNr = 999999
    where  PrdOcPrdOkGid = @PrdOkGid
       and PrdOcRegelNr = @VanRegelNr;

    if @VanRegelNr < @NaarRegelNr then
      // Naar beneden verplaatsen
      // Geef vanaf regel VanRegelNr+1 tot NaarRegelNr de regels 1 nummer lager
      update tabproductieordercomponent
      set    PrdOcRegelNr = PrdOcRegelNr - 1
      where  PrdOcPrdOkGid = @PrdOkGid
         and PrdOcRegelNr >  @VanRegelNr
         and PrdOcRegelNr <= @NaarRegelNr
      order by PrdOcRegelNr ;
    else
      // Naar boven verplaatsen
      update tabproductieordercomponent
      set    PrdOcRegelNr = PrdOcRegelNr + 1
      where  PrdOcPrdOkGid = @PrdOkGid
         and PrdOcRegelNr >= @NaarRegelNr
         and PrdOcRegelNr <  @VanRegelNr
      order by PrdOcRegelNr desc;
    end if;

    // Als laatste de hernoemde keurig in het rijtje zetten
    update tabproductieordercomponent
    set    PrdOcRegelNr = @NaarRegelNr
    where  PrdOcPrdOkGid = @PrdOkGid
       and PrdOcRegelNr = 999999;

  end if;

  set @@ErrorTextProcedure = 'ProdOrderCompVerplaatsRegelNr(@PrdOkGid='+string(@PrdOkGid)+')';
  //call TraceEind(@@ErrorTextProcedure);

end;


