//$Workfile: ProdOrderHerberekenRegelWerkelijkeAantal.sp $ $Revision: 5 $ $Modtime: 31-08-07 15:54 $'

// *******************************************************************************
// ProductieOrder: Opnieuw berekenen van het werkelijke aantal obv aantal recepten
// *******************************************************************************

if exists (select 1 from sys.sysProcedure where proc_name='ProdOrderHerberekenRegelWerkelijkeAantal') then
  drop procedure ProdOrderHerberekenRegelWerkelijkeAantal;
end if;

create procedure ProdOrderHerberekenRegelWerkelijkeAantal(
 in @PrdOkGid                 integer,
 in @OudeAantal               numeric(15,3),
 in @NieuweAantal             numeric(15,3),
 in @RestantInvullenComponent smallint,
 in @RestantInvullenEindprod  smallint
 )
begin
  declare @AantalTotaalTeVerwerken numeric(15,3);
  declare @AantalDezeVerwerking    numeric(15,3);
  declare @UpdatePrdOcsGid         integer;
  declare @UpdatePrdOesGid         integer;

  set @@ErrorTextProcedure = 'ProdOrderHerberekenRegelWerkelijkeAantal(@PrdOkGid='+string(@PrdOkGid)+', oud=' + string(@OudeAantal) + ', nieuw=' + string(@NieuweAantal) + ')';
  //call TraceBegin(@@ErrorTextProcedure);

  // *** C O M P O N E N T - R E G E L S ***

  // Toegepaste berekening voor het bepalen van het werkelijke regelaantal:
  // PrdOcRcpVerbruik = 0 -> round(@Aantal * PrdOcRcpAantal, 3)                    : Per recept
  // PrdOcRcpVerbruik = 1 -> PrdOcRcpAantal                                        : Per batch (dus hoeft NIET te worden herberekend!)
  // PrdOcRcpVerbruik = 2 -> ceiling( @Aantal / RcpcVerbruikAantal) * RcpcAantal   : per X recepten

  // Loop alle componentenregels af en bepaal opnieuw het werkelijke aantal
  // Alleen herberekenen als de berekening met het oude aantal recepten overeenkomt met de oude waarde van het werkelijke aantal
  // Anders het werkelijke aantal gewoon laten staan!
  for @Cursor AS CURSOR_ComponentRegelsHerberekenen CURSOR FOR
    select
      PrdOcGid                          @CursPrdOcGid,
      PrdOcRcpAantal                    @CursPrdOcRcpAantal,
      PrdOcRcpVerbruik                  @CursPrdOcRcpVerbruik,
      PrdOcRcpVerbruikAantal            @CursPrdOcRcpVerbruikAantal,
      PrdOcAantalDezeVerwerking         @CursPrdOcAantalDezeVerwerking,
      PrdOcAantalReedsVerwerkt          @CursPrdOcAantalReedsVerwerkt,
      PrdOcAantalTotaalTeVerwerken      @CursPrdOcAantalTotaalTeVerwerken,
      ArtAantDecAantallen               @CursArtAantDecAantallen
    from
      tabProductieOrderComponent
      inner join tabArtikel on (ArtGid = PrdOcArtGid)
    where PrdOcPrdOkGid = @PrdOkGid
      and PrdOcRegelSoort <> 0          /* Tekstregels niet opnieuw berekenen */
      and PrdOcRcpVerbruik in (0, 1, 2) /* Alleen berekenen als per recept of per X recepten of per verwerking is */
      and PrdOcAantalTotaalTeVerwerken = (case @CursPrdOcRcpVerbruik
                                          when 0 then round(@OudeAantal * @CursPrdOcRcpAantal, @CursArtAantDecAantallen)
                                          when 1 then sign(@OudeAantal) * @CursPrdOcRcpAantal
                                          when 2 then round(ceiling(@OudeAantal /  if @CursPrdOcRcpVerbruikAantal = 0 then 1 else @CursPrdOcRcpVerbruikAantal endif) * @CursPrdOcRcpAantal, @CursArtAantDecAantallen)
                                         end)
  for update
  do
    set @AantalTotaalTeVerwerken = case @CursPrdOcRcpVerbruik
                                     when 0 then round(@NieuweAantal * @CursPrdOcRcpAantal, @CursArtAantDecAantallen)
                                     when 1 then sign(@NieuweAantal) * @CursPrdOcRcpAantal
                                     when 2 then round(ceiling(@NieuweAantal / if @CursPrdOcRcpVerbruikAantal = 0 then 1 else @CursPrdOcRcpVerbruikAantal endif) * @CursPrdOcRcpAantal, @CursArtAantDecAantallen)
                                   end;

    set @AantalDezeVerwerking    = if (@RestantInvullenComponent <> 1) or (@CursPrdOcAantalTotaalTeVerwerken - @CursPrdOcAantalReedsVerwerkt <> @CursPrdOcAantalDezeVerwerking) then
                                     @CursPrdOcAantalDezeVerwerking
                                   else
                                     case @CursPrdOcRcpVerbruik
                                       when 0 then round(@NieuweAantal * @CursPrdOcRcpAantal, @CursArtAantDecAantallen)
                                       when 2 then ceiling(@NieuweAantal / if @CursPrdOcRcpVerbruikAantal = 0 then 1 else @CursPrdOcRcpVerbruikAantal endif) * @CursPrdOcRcpAantal
                                     end - @CursPrdOcAantalReedsVerwerkt
                                   endif;

    update tabProductieOrderComponent
    set    PrdOcAantalTotaalTeVerwerken = @AantalTotaalTeVerwerken,
           PrdOcAantalDezeVerwerking    = @AantalDezeVerwerking
    where  current of CURSOR_ComponentRegelsHerberekenen;

    set @UpdatePrdOcsGid = null;

    //TG 01-11-2006: Deze query is wellicht wat complex maar is ter vervanging van 3 losse queries. We checken hiermee in 1x 3 voorwaarden
    //waaraan voldaan moet worden om een update uit te mogen voeren:
    //1. we mogen maar 1 specificatie bij de component-regel hebben.
    //   gewaarborgd door: having count(*)=1; geeft alleen een resultaat als er precies 1 regel is.
    //2. Die ene regel mag geen serienummer bevatten.
    //   gewaarborgd door: Count(PrdOcsArtserieGid) = 0; geeft alleen een resultaat als er geen regel(s) zijn.
    //3. Die ene regel moet hetzelfde "aantal op te boeken" hebben als de oude waarde van de componentregel;
    //   gewaarborgd door: PrdOcsAantalDezeVerwerking = @CursPrdOcAantalDezeVerwerking (In de cursor zijn de oude waarden nog terug te vinden)
    //
    //als aan al die voorwaarden voldaan zijn dan geven we een Max(gidje) terug. We krijgen met de query dus 0 of 1 gidje terug. krijgen we
    //geen gidje terug, dan blijft de variabele null.
    select Max(PrdOcsGid) into @UpdatePrdOcsGid
    from   tabProductieOrderComponentSpec
    where      PrdOcsPrdOcGid             = @CursPrdOcGid
           and PrdOcsAantalDezeVerwerking = @CursPrdOcAantalDezeVerwerking
    having Count(*) = 1 and Count(PrdOcsArtserieGid) = 0;

    //als we geen gidje terug gehad hebben dan is aan 1 van de 3 voorwaarden niet voldaan:
    //het resultaat was dan dus: 0 of meer dan 1 regel, een serienummer ingevuld of het aantal in de spec.regel is aangepast door de gebruiker
    //In dat geval updaten we de regel(s) niet.
    if @UpdatePrdOcsGid is not null then
      update tabProductieOrderComponentSpec
         set PrdOcsAantalDezeVerwerking = @AantalDezeVerwerking
       where PrdOcsGid = @UpdatePrdOcsGid;
    end if;

  end for;

  // *** E I N D P R O D U C T - R E G E L S ***
  for @Cursor AS CURSOR_EindproductRegelsHerberekenen CURSOR FOR
    select
      PrdOeGid                          @CursPrdOeGid,
      PrdOeRcpAantal                    @CursPrdOeRcpAantal,
      PrdOeAantalDezeVerwerking         @CursPrdOeAantalDezeVerwerking,
      PrdOeAantalReedsVerwerkt          @CursPrdOeAantalReedsVerwerkt,
      PrdOeAantalTotaalTeVerwerken      @CursPrdOeAantalTotaalTeVerwerken,
      ArtAantDecAantallen               @CursArtAantDecAantallen
    from
      tabProductieOrderEindproduct
      inner join tabArtikel on (ArtGid = PrdOeArtGid)
    where PrdOePrdOkGid = @PrdOkGid
      and (PrdOeAantalTotaalTeVerwerken = round(@OudeAantal * PrdOeRcpAantal, @CursArtAantDecAantallen) or PrdOeIsReceptRegel <> 0)
  for update
  do
    set @AantalTotaalTeVerwerken = round(@NieuweAantal * @CursPrdOeRcpAantal, @CursArtAantDecAantallen);

    set @AantalDezeVerwerking    = if (@RestantInvullenEindprod <> 1) or (@CursPrdOeAantalTotaalTeVerwerken - @CursPrdOeAantalReedsVerwerkt <> @CursPrdOeAantalDezeVerwerking) then
                                     @CursPrdOeAantalDezeVerwerking
                                   else
                                     round(@NieuweAantal * @CursPrdOeRcpAantal, @CursArtAantDecAantallen) - @CursPrdOeAantalReedsVerwerkt
                                   endif;

    update tabProductieOrderEindProduct
    set    PrdOeAantalTotaalTeVerwerken = @AantalTotaalTeVerwerken,
           PrdOeAantalDezeVerwerking    = @AantalDezeVerwerking
    where  current of CURSOR_EindproductRegelsHerberekenen;

    set @UpdatePrdOesGid = null;

    //TG 01-11-2006: voor uitleg zie component-cursor.
    select Max(PrdOesGid) into @UpdatePrdOesGid
    from   tabProductieOrderEindproductSpec
    where PrdOesPrdOeGid = @CursPrdOeGid
      and PrdOesAantalTotaalTeVerwerken = @CursPrdOeAantalTotaalTeVerwerken
      and PrdOesAantalDezeVerwerking = @CursPrdOeAantalDezeVerwerking
      and PrdOesGid = (select Max(PrdOesGid)
                       from tabProductieOrderEindproductSpec
                       where PrdOesPrdOeGid = @CursPrdOeGid
                       having Count(*) = 1 and Count(PrdOesArtserieGid) = 0);

    if @UpdatePrdOesGid is not null then
      update tabProductieOrderEindproductSpec
         set PrdOesAantalTotaalTeVerwerken = @AantalTotaalTeVerwerken,
             PrdOesAantalDezeVerwerking = @AantalDezeVerwerking
       where PrdOesGid = @UpdatePrdOesGid;
    end if;

  end for;

  set @@ErrorTextProcedure = 'ProdOrderHerberekenRegelWerkelijkeAantal(@PrdOkGid='+string(@PrdOkGid)+', oud=' + string(@OudeAantal) + ', nieuw=' + string(@NieuweAantal) + ')';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure ProductieOrderAanmaken(
  in  @Startnummer           numeric(10,0),
  in  @ProductieAdviesKopGid integer,
  in  @ReceptGid             integer,
  in  @TotaalAantalStuks     numeric(15,3),
  in  @AantalStuksPerRecept  numeric(15,3),
  in  @ArtikelGid            integer,
  in  @MagazijnGid           integer,
  out @ProductieOrderKopGid  integer)
begin
  call ProductieOrderKopAanmaken(@StartNummer, @ProductieAdviesKopGid, @ReceptGid, @TotaalAantalStuks, @AantalStuksPerRecept, @ArtikelGid, @MagazijnGid, @ProductieOrderKopGid);


  // Overnemen van alle receptcomponent/eindproductregels naar deze productieorder
  // Dus geen recept meegeven, alles toevoegen en niks verwijderen (hoeft niet; is toch nog leeg!)
  call ProductieOrderVulRegelsUitRecept(
                @ProductieOrderKopGid,
                null,  // Indien NULL, dan via de code uit de productieorderkop selecteren
                0,     // 0 = gehele recept; 1 = componentregel(s), 2 = eindproductregel(s)
                null,  // indien NULL, dan alles van soort @WatToevoegen
                0,     // 0 = bestaande regels gewoon toevoegen; 1 = verwijderen (verwijderen alleen als @WatToevoegen=0)
                0);    // 0 = eindproduct specificatieregels worden niet aangemaakt; in dat geval moet ProductieOrderToevoegenEindProductSpecificatie aangeroepen worden; 1=ze worden wel aangemaakt

  // Let er op dat ProductieOrderToevoegenEindProductSpecificatie.sp los aangeroepen moet worden voor iedere eindproductspecificatieregel
end;

create or replace procedure ProductieOrderAantalVerdelenOverNieuweOrders(
  in  @Startnummer        numeric(10,0),
  in  @PrdOkGid           integer,
  in  @RcptGid            integer,
  in  @ArtGid             integer,
  in  @MagGid             integer,
  in  @Aantal             numeric(15,3),
  in  @MinAantalRcpt      numeric(15,3),
  in  @MaxAantalRcpt      numeric(15,3),
  in  @PrdOkOms           nchar(40))
begin
  declare @_CurrentOrder integer = 0;
  declare @_ProductieOrderKopGid integer = 0;
  declare @_AantalVolleOrders integer = 0;
  declare @_AantalRestant numeric(15,3);

  select Floor(@Aantal / @MaxAantalRcpt), Mod(@Aantal, @MaxAantalRcpt) into @_AantalVolleOrders, @_AantalRestant;
  set @_AantalVolleOrders = @_AantalVolleOrders -1; // Minus de order waarvandaan we dit aanroepen

  //call Trace('ProductieOrderAantalVerdelenOverNieuweOrders - @_AantalVolleOrders='+string(@_AantalVolleOrders)+', @_AantalRestant='+string(@_AantalRestant));

  LoopOrdersAanmaken:
  Loop
    while exists(select 1 from tabProductieOrderKop where PrdOkNummer = @StartNummer)
    loop
      set @Startnummer = @Startnummer + 1;
    end loop;

    if @_CurrentOrder = @_AantalVolleOrders then
      //call Trace('ProductieOrderAantalVerdelenOverNieuweOrders > Current (Last) Order = ' + string(@_CurrentOrder) +', Startnummer='+string(@Startnummer)+', Aantal='+string(@_AantalRestant));
      if @_AantalRestant <> 0 then
        call ProductieOrderAanmaken(@Startnummer, null, @RcptGid, @_AantalRestant, 1, @ArtGid, @MagGid, @_ProductieOrderKopGid);
        update tabProductieOrderKop set PrdOkOmschrijving = @PrdOkOms where PrdOkGid = @_ProductieOrderKopGid;
      end if;
      leave LoopOrdersAanmaken;
    else
      //call Trace('ProductieOrderAantalVerdelenOverNieuweOrders > Current Order = ' + string(@_CurrentOrder) +', Startnummer='+string(@Startnummer)+', Aantal='+string(@MaxAantalRcpt) );
      call ProductieOrderAanmaken(@Startnummer, null, @RcptGid, @MaxAantalRcpt, 1, @ArtGid, @MagGid, @_ProductieOrderKopGid);
      update tabProductieOrderKop set PrdOkOmschrijving = @PrdOkOms where PrdOkGid = @_ProductieOrderKopGid;
    end if;

    set @_CurrentOrder = @_CurrentOrder + 1;

  end loop LoopOrdersAanmaken;
end;

//$Workfile: ProductieOrderArtikelInProductieOrdersVoorMagazijn.sp $ $Revision: 2 $ $Modtime: 31-08-07 15:54 $'

// Hulproutine voor productieadvies

if exists (select 1 from sys.sysProcedure where proc_name='ProductieOrderArtikelInProductieOrdersVoorMagazijn') then
  drop function ProductieOrderArtikelInProductieOrdersVoorMagazijn;
end if;

create function ProductieOrderArtikelInProductieOrdersVoorMagazijn(
  in @NietVerwerkteProdOrder smallint, // 0 = GEEN rekening houden, 1 = ingeplande en onderhanden, 2 = alles
  in @ArtGid integer,
  in @MagGid integer)
returns numeric(15,3)
begin
  declare @Resultaat numeric(15,3);

  set @@ErrorTextProcedure = 'ProductieOrderArtikelInProductieOrdersVoorMagazijn(@NietVerwerkteProdOrder='+string(@NietVerwerkteProdOrder)+', @ArtGid='+string(@ArtGid)+', @MagGid='+String(@MagGid)+')';
  //call TraceBegin(@@ErrorTextProcedure);

  set @Resultaat = 0.0;
  if @NietVerwerkteProdOrder <> 0 then
    if @MagGid is null then
      // GEEN magazijn, dus gewoon voor alles. De spec.regels doen er dus niet toe!!
      select
      sum(PrdOeAantalTotaalTeVerwerken - (PrdOeAantalReedsVerwerkt - PrdOeAantalUitvalInReedsVerwerkt))
      into @Resultaat
      from
       tabProductieOrderKop
       inner join tabProductieOrderEindProduct on (PrdOePrdOkGid = PrdOkGid)
      where
           (   (@NietVerwerkteProdOrder = 1 and PrdOkStatus in (2, 3))
            or (@NietVerwerkteProdOrder = 2))
       and (PrdOeArtGid = @ArtGid);
    else
      // Magazijn-specifiek
      select
      sum(
       if PrdOeMagGid = @MagGid then
          /*Nog te verwerken van regels*/
          (PrdOeAantalTotaalTeVerwerken - (PrdOeAantalReedsVerwerkt - PrdOeAantalUitvalInReedsVerwerkt)) -
          /*MINUS Nog te verwerken van spec.regels*/
          isnull((select sum(PrdOesAantalTotaalTeVerwerken - (PrdOesAantalReedsVerwerkt - PrdOesAantalUitvalInReedsVerwerkt))
                  from   tabProductieOrderEindproductSpec
                  where (PrdOesPrdOeGid = PrdOeGid)
          ), 0)
        else
          0.0  /*regel staat op ander magazijn, dus er is geen restant in dit magazijn*/
        endif
        +
        isnull((select sum(PrdOesAantalTotaalTeVerwerken - (PrdOesAantalReedsVerwerkt - PrdOesAantalUitvalInReedsVerwerkt))
                from   tabProductieOrderEindproductSpec
                where (PrdOesPrdOeGid = PrdOeGid)
                  and (PrdOesMagGid = @MagGid)
               ), 0)
      )
      into @Resultaat
      from
       tabProductieOrderKop
       inner join tabProductieOrderEindProduct on (PrdOePrdOkGid = PrdOkGid)
      where
           (   (@NietVerwerkteProdOrder = 1 and PrdOkStatus in (2, 3))
            or (@NietVerwerkteProdOrder = 2))
       and (PrdOeArtGid = @ArtGid);
    end if;
    set @resultaat = isnull(@resultaat, 0.0);
  end if;

  set @@ErrorTextProcedure = @@ErrorTextProcedure + ' -> ' + string(@Resultaat);
  //call TraceEind(@@ErrorTextProcedure);
  return(@Resultaat);

end;


create or replace procedure ProductieOrderComponentVerwerkBedragenNaAfsluiten(in @PrdOkGid integer)
begin
  //call TraceBegin('ProductieOrderComponentVerwerkBedragenNaAfsluiten > @PrdOkGid = ' + string(@PrdOkGid));

  //Zet de bedragen in de naar reeds verwerkt
  update tabProductieOrderComponent
  set PrdOcBedragGeboekt = isNull(PrdOcBedragGeboekt,0) + PrdOcBedragReedsVerwerkt,
      PrdOcBedragUitvalGeboekt = isNull(PrdOcBedragUitvalGeboekt,0) + PrdOcBedragUitvalInReedsVerwerkt
  where PrdOcPrdOkGid = @PrdOkGid;

  //Zet de bedragen reeds verwerkt naar 0
  update tabProductieOrderComponent
  set PrdOcBedragReedsVerwerkt = 0.0,
      PrdOcBedragUitvalInReedsVerwerkt = 0.0
  where PrdOcPrdOkGid = @PrdOkGid;

  //call TraceEind('ProductieOrderComponentVerwerkBedragenNaAfsluiten > @PrdOkGid = ' + string(@PrdOkGid));
end;

create or replace procedure ProductieOrderEindProductSpecificatieNaarVerkoopOrder(
                                                    in @PrdOesGid         integer,
                                                    in @OrrGid            integer,
                                                    in @EindProductAantal numeric(15,3))
begin
  //----- Productie-order eindproductspecificaties naar verkooporders  -------
  declare @DoInsert bit = 0;    //inserten of updaten van de taborderregellocatie?
  declare @OrlGid   integer;
  declare @EindProductAantalVrrdEenh numeric(15,3);
  declare @AantDecVerkEenh integer;
  declare @OrrAantalVrrdEenhInVerkEenh numeric(15,3);
  declare @TotaalVoorraadEenh numeric (15,3);
  declare @TotaalVerkoopEenh numeric(15,3);
  declare @MaxAantalVerkEenh numeric(15,3);
  declare @OrrAantalLeveringVrrdEenh numeric(15,3);
  declare @OrrAantalVrrdEenhInVerkEenhMagAfwijken int;
  declare @OrrAantalLevering numeric(15,3);
  declare @OrrAantalBesteld numeric(15,3);
  declare @OrrAantalBesteldVrrdEenh numeric(15, 3);
  declare @OrrAantalBackorderVrrdEenh numeric(15,3);
  //call TraceBegin('ProductieOrderEindProductSpecificatieNaarVerkoopOrder');

  //Haal basisgegevens op om berekeningen te kunnen maken voor de orderregel
  select
    OrrAantalBackorderVrrdEenh,     // @OrrAantalBackorderVrrdEenh
    @EindProductAantal,
    if (VkeAantalDecimalen is null) or (VkeAantalDecimalen = 4 /*4=volgens voorraadeenheid*/) then OrrAantDecAantal else VkeAantalDecimalen end if,     // @AantDecVerkEenh
    if (OrrAantalVrrdEenhInVerkEenh is null) or (OrrAantalVrrdEenhInVerkEenh = 0) then 1 else OrrAantalVrrdEenhInVerkEenh end if,                       // @OrrAantalVrrdEenhInVerkEenh
    OrrAantalVrrdEenhInVerkEenhMagAfwijken,    // @OrrAantalVrrdEenhInVerkEenhMagAfwijken
    OrrAantalLeveringVrrdEenh,                 // @OrrAantalLeveringVrrdEenh
    OrrAantalLevering,                         // @OrrAantalLevering
    OrrAantalBesteldVrrdEenh,                  // @OrrAantalBesteldVrrdEenh
    OrrAantalBesteld                           // @OrrAantalBesteld
  into
    @OrrAantalBackorderVrrdEenh,
    @EindProductAantalVrrdEenh,
    @AantDecVerkEenh,
    @OrrAantalVrrdEenhInVerkEenh,
    @OrrAantalVrrdEenhInVerkEenhMagAfwijken,
    @OrrAantalLeveringVrrdEenh,
    @OrrAantalLevering,
    @OrrAantalBesteldVrrdEenh,
    @OrrAantalBesteld
  from tabOrderRegel
  left outer join tabVerkoopEenheid on Vkegid = OrrVkeGid
  where OrrGid = @OrrGid;

  if (@OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0) then
     set @TotaalVoorraadEenh = @OrrAantalLeveringVrrdEenh + @EindProductAantalVrrdEenh;
     set @TotaalVerkoopEenh = round(@TotaalVoorraadEenh / @OrrAantalVrrdEenhInVerkEenh, @AantDecVerkEenh);      // totaal aantal verkoopeenheden
  else
    // in 2de en 3de geval rekenen we eindproduct aantal om naar verkoopeenheden
    set @TotaalVerkoopEenh = @OrrAantalLevering + round(@EindProductAantalVrrdEenh / @OrrAantalVrrdEenhInVerkEenh, @AantDecVerkEenh);  // totaal aantal verkoopeenheden
    set @TotaalVoorraadEenh = @OrrAantalLeveringVrrdEenh + @EindProductAantalVrrdEenh;
  end if;

  // de eindproducten die opgeboekt zijn voor de orderregel uit backorder halen en in deze levering plaatsen.
  update tabOrderRegel
  set OrrAantalLevering         = @TotaalVerkoopEenh,
      OrrAantalLeveringVrrdEenh = @TotaalVoorraadEenh
  where OrrGid = @OrrGid;

  //Defect 57270: Aantal deze facturering gelijk trekken aan het aantal levering als de vaste gegevens dit aangeeft
  //Verkoopeenheden
  update tabOrderRegel
  set OrrAantalDezeFacturering = OrrAantalLevering
  where OrrGid = @OrrGid
    and OrrAantalDezeFacturering = @OrrAantalLevering
    and OrrRegelsoort = 2
    and exists (select 1 from tabVasteGegevensOrdersFactureren where vofRegelDefNuFactureren = 2); /* 2=aantal levering */

  //Voorraadeenheden
  update tabOrderRegel
  set OrrAantalDezeFactureringVrrdEenh = OrrAantalLeveringVrrdEenh
  where OrrGid = @OrrGid
    and OrrAantalDezeFactureringVrrdEenh = @OrrAantalLeveringVrrdEenh
    and OrrRegelsoort = 2
    and exists (select 1 from tabVasteGegevensOrdersFactureren where vofRegelDefNuFactureren = 2); /* 2=aantal levering */


  // zoek een orderspecificatieregel
  if IsOrderSpecificatieregelActief() = 1 then
    select first OrlGid into @OrlGid
    from   tabOrderRegelLocatie
    inner join tabProductieOrderEindproductSpec on PrdOesOrrGid = OrlOrrGid
    where OrlOrrGid                 = @OrrGid
      and PrdOesGid                 = @PrdOesGid
      and isNull(OrlArtPartijGid,0) = isNull(PrdOesArtPartijGid,0)
      and isNull(OrlArtSerieGid,0)  = isNull(PrdOesArtSerieGid,0);

    if @OrlGid is null then
      set @DoInsert = 1;
    end if;

    if (@DoInsert = 1) then
      insert into tabOrderRegelLocatie (
      OrlArtPartijGid,
      OrlArtSerieGid,
      OrlVkeGid,
      OrlAantDecAantal,
      OrlAantDecAantalVrrdEenh,
      OrlDezeLevering,
      OrlDezeLeveringVrrdEenh,
      OrlLocGid,
      OrlMagGid,
      OrlOrrGid )
      Select
            // OrlArtPartijGid partij overnemen uit de Productieorder eindproductspecificatieregel
            PrdOesArtPartijGid,

            // OrlArtSerieGid  serienummer overnemen uit de Productieorder eindproductspecificatieregel
            PrdOesArtSerieGid,

            // OrlVkeGid
            OrrVkeGid,

            // OrlAantDecAantal
            OrrAantDecAantal,

            // OrlAantDecAantalVrrdEenh
            OrrAantDecAantalVrrdEenh,

            // OrlDezeLevering in verkoopeenheden
            round(@EindProductAantalVrrdEenh / @OrrAantalVrrdEenhInVerkEenh, @AantDecVerkEenh),

            // OrlDezeLeveringVrrdEenh
            @EindProductAantalVrrdEenh,

            // OrlLocGid
            (isnull((select first tabArtikelMagazijn.ArtMagDefaultLocGid
                     from tabArtikelMagazijn
                     where tabArtikelMagazijn.ArtMagArtGid = OrrArtGid
                     and tabArtikelMagazijn.ArtMagMagGid = OrrMagGid),
                    (select first tabLocatie.LocGid
                    from tabLocatie where
                    tabLocatie.LocMagGid = OrrMagGid
                    and tabLocatie.LocNaam = '(Standaard)'))),
            OrrMagGid,
            OrrGid
      from tabOrderRegel
      inner join tabProductieOrderEindproductSpec on PrdOesOrrGid = OrrGid
      where OrrRegelSoort     = 2
        and OrrAantalLevering <> 0
        and PrdOesGid         = @PrdOesGid
        and OrrGid            = @OrrGid;
    else
      update tabOrderRegelLocatie
      set    OrlDezeLevering         = if OrlArtSerieGid is not null then 1 else round( (OrlDezeLeveringVrrdEenh + @EindProductAantalVrrdEenh) / @OrrAantalVrrdEenhInVerkEenh, @AantDecVerkEenh) end if,
             OrlDezeLeveringVrrdEenh = if OrlArtSerieGid is not null then 1 else OrlDezeLeveringVrrdEenh + @EindProductAantalVrrdEenh end if
      where  OrlGid = @OrlGid;
    end if;
  end if;

  //Zet deze eindproductregels op verwerkt in verkooporder
  update tabProductieOrderEindproductSpec
  set PrdOesVerwerktInVerkoopOrder = 1
  where  PrdOesGid = @PrdOesGid;
//  PrdOesOrrGid = @OrrGid
//  and PrdOesPrdOeGid in (select PrdOeGid from tabProductieOrderEindProduct where PrdOePrdOkGid = @PrdOkGid);

  //call TraceEind('ProductieOrderEindProductSpecificatieNaarVerkoopOrder');
end;

create or replace procedure ProductieOrderEindProductVerwerkBedragenNaAfsluiten(in @PrdOkGid integer)
begin
  //call TraceBegin('ProductieOrderEindProductVerwerkBedragenNaAfsluiten > @PrdOkGid = ' + string(@PrdOkGid));

  //Zet de bedragen in de naar reeds verwerkt
  update tabProductieOrderEindproduct
  set PrdOeBedragGeboekt = isNull(PrdOeBedragGeboekt,0) + PrdOeBedragReedsVerwerkt,
      PrdOeBedragUitvalGeboekt = isNull(PrdOeBedragUitvalGeboekt,0) + PrdOeBedragUitvalInReedsVerwerkt
  where PrdOePrdOkGid = @PrdOkGid;

  //Zet de bedragen reeds verwerkt naar 0
  update tabProductieOrderEindproduct
  set PrdOeBedragReedsVerwerkt = 0.0,
      PrdOeBedragUitvalInReedsVerwerkt = 0.0
  where PrdOePrdOkGid = @PrdOkGid;

  //call TraceEind('ProductieOrderEindProductVerwerkBedragenNaAfsluiten > @PrdOkGid = ' + string(@PrdOkGid));
end;


create or replace procedure ProductieOrderKopAanmaken(
  in  @Startnummer           numeric(10,0),
  in  @ProductieAdviesKopGid integer,
  in  @ReceptGid             integer,
  in  @TotaalAantalStuks     numeric(15,3),
  in  @AantalStuksPerRecept  numeric(15,3),
  in  @ArtikelGid            integer,
  in  @MagazijnGid           integer,
  out @ProductieOrderKopGid  integer)
begin
//MR 28-apr-2021 incident 5762: @MagazijnGid wordt nu niet gebruikt omdat de aanpassing voor defect 55348 is teruggedraaid. De code bestaat nog wel in delphi

  // variabelen declareren en initialiseren
  declare @DefMagProdComp         integer;
  declare @DefMagProdEindProd     integer;
  declare @TeGebruikenStartnummer numeric(10,0);

  set @TeGebruikenStartnummer = '';

  // default magazijngegevens bepalen
  select MagGid, MagGid into @DefMagProdComp, @DefMagProdEindProd from tabMagazijn where MagCode='001';

  if @@ModuleM1 = 1 then
    select IsNull(ToeMagMagGid, @DefMagProdComp)     into @DefMagProdComp     from tabToegestaneMagazijnen inner join tabGebruiker ON (GebruikerGid = ToeMagGebrGid) where (NaamGebruiker = @@GebruikerCode) and (toemagtoepassing = 50);
    select IsNull(ToeMagMagGid, @DefMagProdEindProd) into @DefMagProdEindProd from tabToegestaneMagazijnen inner join tabGebruiker ON (GebruikerGid = ToeMagGebrGid) where (NaamGebruiker = @@GebruikerCode) and (toemagtoepassing = 55);
  endif;

  // startnummer bepalen
  if @TeGebruikenStartnummer = '' then
    set @TeGebruikenStartnummer = @Startnummer;
  else
    select RcpvProdOrderStartnummer into @TeGebruikenStartnummer from tabReceptuurVasteGegevens;
  endif;

  // nu de productieorderkop aanmaken
  insert into tabProductieOrderKop
  (
    PrdOkAangemaaktDoor,                    // @@GebruikerCode
    PrdOkAangemaaktOp,                      // Now()
    PrdOkAantalRcpt,                        // @TotaalAantalStuks/@AantalStuksPerRecept naar boven afgerond
    PrdOkAantalRcptMaximum,                 // komt uit tabReceptuur
    PrdOkAantalRcptMinimum,                 // komt uit tabReceptuur
    PrdOkDefMagGidComponent,                // @DefMagProdComp
    PrdOkDefMagGidEindproduct,              // @DefMagProdEindProd
    PrdOkDocument,                          // komt uit receptuur
    //PrdOkGid,                                --> komt via @@Identity terug
    PrdOkNummer,                            // startnummer uit voorloopscherm
    PrdOkOmschrijving,                      // komt uit tabReceptuur
    PrdOkOpmerking,                         // komt uit receptuur
    //PrdOkProductieKlaarOp,                   --> doen we niets mee
    //PrdOkProductieStartOp,                   --> doen we niets mee
    PrdOkRcptCode,                          // komt uit tabReceptuur
    PrdOkRcptSoort,                         // komt uit tabReceptuur
    PrdOkRcptZoekcode,                      // komt uit tabReceptuur
    PrdOkRksGidProdResultaat,               // komt uit tabReceptuur
    PrdOkStatus,                            // komt uit tabReceptuur: RcptDefaultProductieOrderStatus
    PrdOkProductieStartOp,                  // Now
    PrdOkUitTeVoerenDoor,                   // @@GebruikerCode
    PrdOkVulAantalDezeVerwerkingComponent,  // komt uit tabReceptuur
    PrdOkVulAantalDezeVerwerkingEindproduct,// komt uit tabReceptuur
	PrdOkAantalRcptProductieGrootte         // komt uit tabReceptuur
  )
  select
    @@GebruikerCode,                                    // PrdOkAangemaaktDoor
    Now(),                                              // PrdOkAangemaaktOp
    Ceiling(round(@TotaalAantalStuks, ArtAantDecAantallen) / round(@AantalStuksPerRecept, ArtAantDecAantallen)),  // PrdOkAantalRcpt
    RcptBatchMaximum,                                   // PrdOkAantalRcptMaximum
    RcptBatchMinimum,                                   // PrdOkAantalRcptMinimum
    @DefMagProdComp,                                    // PrdOkDefMagGidComponent
    @DefMagProdEindProd,                                // PrdOkDefMagGidEindproduct
    RcptDocument,                                       // PrdOkDocument
    @TeGebruikenStartnummer,                            // PrdOkNummer
    RcptOmschrijving,                                   // PrdOkOmschrijving
    RcptOpmerking,                                      // PrdOkOpmerking
    RcptCode,                                           // PrdOkRcptCode
    RcptSoort,                                          // PrdOkRcptSoort
    RcptZoekcode,                                       // PrdOkRcptZoekcode
    RcptRksGid,                                         // PrdOkRksGidProdResultaat
    RcptDefaultProductieOrderStatus,                    // PrdOkStatus
    Now(),                                              // PrdOkProductieStartOp
    @@GebruikerCode,                                    // PrdOkUitTeVoerenDoor
    RcptVulAantalDezeVerwerkingComponent,               // PrdOkVulAantalDezeVerwerkingComponent
    RcptVulAantalDezeVerwerkingEindproduct,             // PrdOkVulAantalDezeVerwerkingEindproduct
	RcptBatchProductieGrootte                           // PrdOkAantalRcptProductieGrootte
  from
    tabReceptuur
  left join tabProductieAdviesKop on pakGid = @ProductieAdviesKopGid
  left join tabArtikel on artGid = @ArtikelGid
  where
    rcptGid = @ReceptGid;

  // de buitenwereld wil graag weten welke productieorderkop we zojuist hebben aangemaakt
  set @ProductieOrderKopGid = @@Identity;

  // startnummer onthouden voor de volgende keer
  update tabReceptuurVasteGegevens set RcpvProdOrderStartnummer = @TeGebruikenStartnummer + 1;
end;

create or replace procedure ProductieOrderToevoegenEindProductSpecificatie(
  in @ArtikelGid            integer,
  in @MagazijnGid           integer,
  in @Aantal                numeric(15,3),
  in @ProductieOrderKopGid  integer,
  in @Soort                 integer,
  in @VerkoopOrderRegelGid  integer)
begin
  declare @_StandaardMagazijnLocatieGid  integer;
  declare @_MagGidVolgensKop             integer;
  declare @_ProductieOrderEindProductGid integer;
  declare @_StandaardArtikelLocatieGid   integer;
  declare @_ArtPartijGid                 integer;
  declare @_AantalTotaalTeVerwerken numeric(15,3);

  //Het magazjn en de locatie alleen vullen bij een magazijnregel. Bij een orderregel niet
  if (@VerkoopOrderRegelGid is null) then
    // voor de zekerheid (voor de artikelen die GEEN standaard locatie in het aangegeven magazijn hebben)
    select  PrdOkDefMagGidEindproduct into @_MagGidVolgensKop
    from    tabProductieOrderKop
    where   PrdOkGid = @ProductieOrderKopGid;

    select  LocGid into @_StandaardMagazijnLocatieGid
    from    tablocatie
    where   locmaggid = IsNull(@MagazijnGid, @_MagGidVolgensKop) and locnaam = '(Standaard)';

    // we hebben default locatie van magazijn nodig
    select  ArtMagDefaultLocGid into @_StandaardArtikelLocatieGid
    from    tabArtikelMagazijn
    where   ArtMagArtGid = @ArtikelGid and ArtMagMagGid = IsNull(@MagazijnGid, @_MagGidVolgensKop);

    set @_ArtPartijGid = null;
  else
    //Het magazijn leegmaken als het om een verkooporderregel gaat
    set @MagazijnGid = null;

    select OrrArtPartijGid into @_ArtPartijGid
    from   tabOrderRegel
    where  OrrGid = @VerkoopOrderRegelGid;
  end if;

  // we hebben het gid nodig van de productieorder eindproduct regel
  select  first PrdOeGid into @_ProductieOrderEindProductGid
  from    tabProductieOrderEindproduct
  where   PrdOeArtGid = @ArtikelGid and PrdOePrdOkGid = @ProductieOrderKopGid;

  //Als het aanntal 0 is, dan het aantaltotaalteverwerken uitrekenen
  if @Aantal = 0 then
    select (PrdOeAantalTotaalTeVerwerken - isnull(sum(PrdOesAantalTotaalTeVerwerken),0)) into @_AantalTotaalTeVerwerken
    from tabProductieOrderEindproduct
    left outer join tabProductieOrderEindproductSpec on PrdOesPrdOeGid = PrdOeGid
    where PrdOeGid = @_ProductieOrderEindProductGid
    group by PrdOeAantalTotaalTeVerwerken;
  else
    // ACW Uiteraard wel het aantal overnemen naar totaal als het aantal niet 0 is he!
    set @_AantalTotaalTeVerwerken = @Aantal;
  end if;

  insert into tabProductieOrderEindproductSpec
  (
    PrdOesPrdOeGid,
    PrdOesMagGid,
    PrdOesLocGid,
    PrdOesAantalDezeVerwerking,
    PrdOesAantalReedsVerwerkt,
    PrdOesAantalTotaalTeVerwerken,
    PrdOesSoort,
    PrdOesOrrGid,
    PrdOesArtPartijGid
  )
  values
  (
    @_ProductieOrderEindProductGid,                                     // = PrdOeGid,
    IsNull(@MagazijnGid, @_MagGidVolgensKop),                           // = PrdOesMagGid
    IsNull(@_StandaardArtikelLocatieGid, @_StandaardMagazijnLocatieGid), // = PrdOesLocGid
    @Aantal,                                                           // = PrdOesAantalDezeVerwerking
    0,                                                                 // = PrdOesAantalReedsVerwerkt
    @_AantalTotaalTeVerwerken,                                         // = PrdOeAantalTotaalTeVerwerken
    @Soort,                                                            // = PrdOesSoort
    @VerkoopOrderRegelGid,                                             // = PrdOesOrrGid
    @_ArtPartijGid                                                      // = PrdOesArtPartijGid
  );
end;

create or replace procedure ProductieOrderVerwerkBedragenNaAfsluiten(in @PrdOkGid integer)
begin
  //call TraceBegin('ProductieOrderVerwerkBedragenNaAfsluiten > @PrdOkGid = ' + string(@PrdOkGid));

  //Verplaats de bedragen van de componenten naar de historische velden
  Call ProductieOrderComponentVerwerkBedragenNaAfsluiten(@PrdOkGid);

  //Verplaats de bedragen naar de historische velden
  Call ProductieOrderEindProductVerwerkBedragenNaAfsluiten(@PrdOkGid);

  //call TraceEind('ProductieOrderVerwerkBedragenNaAfsluiten > @PrdOkGid = ' + string(@PrdOkGid));
end;

create or replace procedure ProductieOrderVulRegelsUitRecept(
 in @PrdOkGid                 integer,
 in @RcptGid                  integer,    // Indien NULL, dan via de code uit de productieorderkop selecteren
 in @WatToevoegen             smallint,   // 0 = gehele recept; 1 = componentregel(s); 2 = eindproductregel(s)
 in @ToevoegGid               integer,    // indien NULL, dan alles van soort @WatToevoegen
 in @VerwijderBestaandeRegels smallint,   // 0 = bestaande regels gewoon toevoegen; 1 = verwijderen (verwijderen alleen als @WatToevoegen=0)
 in @MaakEindProdSpecRegels   smallint    // 0 = eindproduct specificatieregels worden niet aangemaakt; in dat geval moet ProductieOrderToevoegenEindProductSpecificatie aangeroepen worden; 1=ze worden wel aangemaakt
 )
begin
  declare @RcptCode                           nchar(20);
  declare @DefMagGidComponent                 integer;
  declare @DefMagGidEindproduct               integer;
  declare @StandaardLocGidInMagazijn          integer;
  declare @EersteRegelNrComponent             integer;
  declare @EersteRegelNrEindproduct           integer;
  declare @VulAantalDezeVerwerkingComponent   smallint;
  declare @VulAantalDezeVerwerkingEindproduct smallint;
  declare @AantalVolgensRecept                numeric(15,3);
  declare @DefaultTaalGid                     integer;

     // om te voorkomen dat een bestaande productieorder nogmaals uitgebreid wordt met regels; controleren we of dit al is gedaan
  if not exists(select 1 from tabProductieOrderEindProduct where PrdOePrdOkGid = @PrdOkGid) then

    set @@ErrorTextProcedure = 'ProdOrderVulRegelsUitRecept(@PrdOkGid='+string(@PrdOkGid)+')';
    //call TraceBegin(@@ErrorTextProcedure);

    // Extra controle op soort toevoeging
    if @WatToevoegen = 0 then
      // indien gehele recept toevoegen, dan gid voor toe te voegen regel resetten
      set @ToevoegGid = null
    else
      // indien deel toevoegen, dan regels NIET verwijderen
      set @VerwijderBestaandeRegels = 0;
    end if;

    // Uitlezen productieorderkop
    select PrdOkRcptCode, PrdOkDefMagGidComponent, PrdOkDefMagGidEindproduct, PrdOkAantalRcpt     , PrdOkVulAantalDezeVerwerkingComponent, PrdOkVulAantalDezeVerwerkingEindproduct
    into   @RcptCode,     @DefMagGidComponent,     @DefMagGidEindproduct,     @AantalVolgensRecept, @VulAantalDezeVerwerkingComponent    , @VulAantalDezeVerwerkingEindproduct
    from   tabProductieOrderKop
    where  PrdOkGid = @PrdOkGid;

    // Opzoeken recept (indien niet meegegeven!)
    if @RcptGid is null then
      select RcptGid into @RcptGid from tabReceptuur where RcptCode = @RcptCode;
    end if;

    // default taalgid bepalen
    Select first DefaultTaalGid into @DefaultTaalGid from tabVasteGegevens;

    // Bestaande regels uit productieorder dumpen (kan alleen als we een heel recept toevoegen!)
    if @VerwijderBestaandeRegels <> 0 and (@WatToevoegen = 0) then
      delete tabProductieOrderComponent   where PrdOcPrdOkGid = @PrdOkGid;
      delete tabProductieOrderEindproduct where PrdOePrdOkGid = @PrdOkGid;
    else
      // Start regelnummer componenten/eindproducten vinden
      select max(PrdOcRegelNr) into @EersteRegelNrComponent   from tabProductieOrderComponent   where PrdOcPrdOkGid = @PrdOkGid;
      select max(PrdOeRegelNr) into @EersteRegelNrEindproduct from tabProductieOrderEindProduct where PrdOePrdOkGid = @PrdOkGid;
    end if;
    set @EersteRegelNrComponent   = isnull(@EersteRegelNrComponent,   0);
    set @EersteRegelNrEindproduct = isnull(@EersteRegelNrEindProduct, 0);

    // Toevoegen component als alles toevoegen of specifiek de component(en)
    if @WatToevoegen in (0, 1) then
      // Nieuwe componentregels toevoegen aan productieorder

      // Voor de zekerheid (voor de artikelen die GEEN standaard locatie in het aangegeven magazijn hebben)
      select LocGid
      into   @StandaardLocGidInMagazijn
      from   tablocatie
      where      locmaggid = @DefMagGidComponent
             and locnaam   = '(Standaard)';

      insert into tabProductieOrderComponent (
       PrdOcPrdOkGid, PrdOcRegelNr,        PrdOcRegelSoort,
       PrdOcArtGid,   PrdOcMagGid,         PrdOcLocGid,
       PrdOcOmschrijving,
       PrdOcRcpAantal,      PrdOcRcpVerbruik,    PrdOcRcpVerbruikAantal,
       PrdOcAantalTotaalTeVerwerken,
       PrdOcAantalDezeVerwerking)
      select
       @PrdOkGid,     RcpcRegelNr + @EersteRegelNrComponent,         RcpcRegelsoort,
  RcpcArtGid, if RcpcRegelsoort = 2 then @DefMagGidComponent endif, if RcpcRegelsoort = 2 then isnull(ArtMagDefaultLocGid, @StandaardLocGidInMagazijn) endif,
       if RcpcArtGid is not null and RcpcRegelsoort = 0 then (select first ArtTekst from tabArtikelTeksten where ArtTekstArtGid = RcpcArtGid and ArtTaalGid = @DefaultTaalGid)
       else RcpcOmschrijving endif,
       RcpcAantal,          RcpcVerbruik,        RcpcVerbruikAantal,
       case RcpcVerbruik
         when 0 then round(@AantalVolgensRecept * RcpcAantal, 3)                      // Per recept
         when 1 then sign(@AantalVolgensRecept) * RcpcAantal                                                       // Per batch
         when 2 then ceiling( @AantalVolgensRecept / RcpcVerbruikAantal) * RcpcAantal // Per X recepten
       end,
       if (@VulAantalDezeVerwerkingComponent = 1) then //0 = niet vullen, 1 = vullen met restant
        case RcpcVerbruik
         when 0 then round(@AantalVolgensRecept * RcpcAantal, 3)                      // Per recept
         when 1 then sign(@AantalVolgensRecept) * RcpcAantal                                                       // Per batch
         when 2 then ceiling( @AantalVolgensRecept / RcpcVerbruikAantal) * RcpcAantal // Per X recepten
       end endif
      from
       tabReceptuurComponent
       inner join      tabReceptuur       on (RcptGid = RcpcRcptGid)
       left outer join tabArtikel         on (ArtGid = RcpcArtGid)
       left outer join tabArtikelMagazijn on (ArtMagArtGid = ArtGid and ArtMagMagGid = @DefMagGidComponent)
      where
           (RcpcRcptGid = @RcptGid)
       and (isnull(@ToevoegGid, RcpcGid) = RcpcGid); // Slechts 1 regel of allemaal

       // Ook de detailregels maar vast vullen (aantallen overnemen, serienummers en partijen gewoon leeg laten)
       insert into tabProductieOrderComponentSpec(
         PrdOcsPrdOcGid, PrdOcsMagGid, PrdOcsLocGid, PrdOcsAantalDezeVerwerking, PrdOcsAantalReedsVerwerkt, PrdOcsAantalTotaalTeVerwerken)
       select PrdOcGid, PrdOcMagGid, PrdOcLocGid, PrdOcAantalDezeVerwerking, PrdOcAantalReedsVerwerkt, PrdOcAantalTotaalTeVerwerken
       from   tabProductieOrderComponent
       where  PrdOcPrdOkGid = @PrdOkGid
         and  PrdOcRegelSoort = 2;
    end if;


    // Toevoegen eindproduct als alles toevoegen of specifiek de eindproduct(en)
    if @WatToevoegen in (0, 2) then
      // Nieuwe eindproductregels toevoegen aan productieorder

      // Voor de zekerheid (voor de artikelen die GEEN standaard locatie in het aangegeven magazijn hebben)
      select LocGid
      into   @StandaardLocGidInMagazijn
      from   tablocatie
      where      locmaggid = @DefMagGidEindproduct
             and locnaam   = '(Standaard)';

      insert into tabProductieOrderEindProduct (
       PrdOePrdOkGid, PrdOeRegelNr,PrdOeIsReceptRegel,
       PrdOeArtGid,   PrdOeMagGid,           PrdOeLocGid, PrdOeOmschrijving,
       PrdOeRcpAantal,
       PrdOeAantalTotaalTeVerwerken, PrdOeAantalDezeVerwerking)
      select
       @PrdOkGid,     RcpeRegelNr + @EersteRegelNrEindProduct, 1,
       RcpeArtGid,    @DefMagGidEindproduct, isnull(ArtMagDefaultLocGid, @StandaardLocGidInMagazijn), ArtOms,
       RcpeAantal,
       round(RcpeAantal * @AantalVolgensRecept, 3),
       if (@VulAantalDezeVerwerkingEindproduct = 1) then //0 = niet vullen, 1 = vullen met restant
         round(RcpeAantal * @AantalVolgensRecept, 3)
       endif
      from
       tabReceptuurEindproduct
       inner join      tabReceptuur       on (RcptGid = RcpeRcptGid)
       inner join      tabArtikel         on (ArtGid = RcpeArtGid)
       left outer join tabArtikelMagazijn on (ArtMagArtGid = ArtGid and ArtMagMagGid = @DefMagGidEindproduct)
      where
           (RcpeRcptGid = @RcptGid)
       and (isnull(@ToevoegGid, RcpeGid) = RcpeGid); // Slechts 1 regel of allemaal


      if @MaakEindProdSpecRegels = 1 then
        // Ook de detailregels maar vast vullen (aantallen overnemen, serienummers en partijen gewoon leeg laten)
        insert into tabProductieOrderEindproductSpec(
          PrdOesPrdOeGid, PrdOesMagGid, PrdOesLocGid, PrdOesAantalDezeVerwerking, PrdOesAantalReedsVerwerkt, PrdOesAantalTotaalTeVerwerken)
        select
          PrdOeGid, PrdOeMagGid, PrdOeLocGid, PrdOeAantalDezeVerwerking, PrdOeAantalReedsVerwerkt, PrdOeAantalTotaalTeVerwerken
        from tabProductieOrderEindproduct
        where PrdOePrdOkGid = @PrdOkGid;
      end if;
    end if;

    set @@ErrorTextProcedure = 'ProdOrderVulRegelsUitRecept(@PrdOkGid='+string(@PrdOkGid)+')';
    //call TraceEind(@@ErrorTextProcedure);
  end if;
end;


create or replace procedure LicentieStartDatum(@release nchar(10) default '')
result (
  LicRelease    nchar(10),
  LicStartdatum date
  )
begin
  declare @Releases long nvarchar =
    '535,2005-06-30\n' ||
    '537,2005-06-30\n' ||
    '540,2005-06-30\n' ||
    '541,2005-06-30\n' ||
    '542,2005-06-30\n' ||
    '543,2008-10-02\n' ||
    '544,2008-10-02\n' ||
    '545,2008-10-02\n' ||
    '546,2011-12-08\n' ||
    '547,2012-06-07\n' ||
    '548,2013-01-14\n' ||
    '549,2013-09-10\n' ||
    '550,2014-01-01\n' ||
    '551,2014-08-11\n' ||
    '552,2015-02-01\n' ||
    '553,2015-11-01\n' ||
    '554,2016-03-01\n' ||
    '555,2016-10-01\n' ||
    '556,2017-04-11\n' ||
    '557,2017-12-25\n' ||
    '558,2018-06-01\n' ||
    '559,2018-08-08\n' ||
    '560,2019-02-22\n' ||
    '561,2019-08-01\n' ||
    '562,2020-04-16\n' ||
    '563,2020-11-09\n' ||
    '564,2021-04-07\n' ||
    '565,2021-06-04\n' ||
    '566,2021-10-14\n' ||
    '567,2022-04-14\n' ||
    '568,2023-04-01\n' ||
    '569,2024-05-01\n' ||
    '570,2026-03-01\n' ||
    /*Hier de nieuwe release tussenvoegen en de datum ook naar release 916 (Trunk) overnemen*/
    '916,2026-03-01';

  declare @stripped nchar(40) = isnull(replace(regexp_substr(@release, '^[[:digit:].]*'), '.', '') , '');

  select if @release = '' then LicRelease else @release endif LicRelease, LicStartdatum
  from  openstring(VALUE @Releases) with(LicRelease nvarchar(4), LicStartdatum date) OPTION ( ROW DELIMITED BY '\n') as tabelletje
  where @stripped = '' or tabelletje.LicRelease = @stripped
  order by LicRelease;

end;


create or replace function OrderGeefAfleverLndGid(
  in @OrkGid integer
)
returns integer
begin
  declare @result integer;

  select AdrLndGid
  into @result
  from tabOrderKop
  inner join tabNaw on NawGid = if (OrkVerzendAdres in (3,4,5)) then OrkFactuurNawGid else OrkNawGid endif
  inner join tabAdres on AdrGid = case OrkVerzendAdres
                                    when 0 then //Correspondentieadres
                                      NawGidCorrespondentie
                                    when 1 then //Vestigingsadres
                                      NawGidVestiging
                                    when 2 then //Verzendadres
                                      OrkAdrGid
                                    when 3 then //Factuurdeb.correspondentieadres
                                      NawGidCorrespondentie
                                    when 4 then //Factuurdeb.vestigingsadres
                                      NawGidVestiging
                                    when 5 then //Factuurdeb.verzendadres
                                      OrkAdrGid
                                  end
  where OrkGid = @OrkGid;

  return @result;
end;


create or replace procedure OrderRegelSpecificaties_BeschikbaarPerLocatie(
  in @MagGid integer,
  in @AantalBenodigdVoorrEenh numeric(15,3),
  in @ArtGid integer,
  in @ArtPartijGid integer default null,
  in @ZoekPerAantalVoorraadeenheden numeric(15,3) default 1, // We zoeken naar batches met dit aantal.
                                                          // als niet mag worden afgeweken of het aantal benodigd past
                                                          // niet in de verkoopeenheid, dan 1 (in voorreenheid),
                                                          // anders het aantal van de verkoopeenheid
  in @MatViewNummerVoorraadAantallen nchar(20) default null,
  // Enkele gegevens van de order zelf indien nodig
  in @OrrAantalBesteld numeric(15,3) default null,  //LET OP! DIT IS HET AANTAL DEZE LEVERING (MAAR KAN IVM DELPHI-CODE NIET WORDEN GEWIJZIGD)
  in @OverruleAllesVan1BulkLocatie smallint default 0,        // 0  = Gebruik nstellingen van VG,
                                                              // 1  = Overrule, gebruik altijd alles van een gevonden bulklocatie,
                                                              // -1 = Overrule, doe alsof vinkje Gebruik alles van 1 bulklocatie UIT staat
  in @AfrondenPer numeric(15,3) default null,                 // Als we 50 zoeken en er 19 vinden, maar afronden per 10, dan resultaat=20 en we zoeken er dan nog 30
  in @AfkappenPer numeric(15,3) default null,                 // Als we 50 zoeken en er 19 vinden, maar afkappen per 10, dan resultaat=10 en we zoeken er dan nog 40
  in @OrrGid      integer       default null                  // Als voor orderregel, dan als die NIET is gereserveerd, dan TOCH de aantallen van de spec.regels van vrije voorraad afhalen
)
result (
  tmpGid       integer,
  tmpStap      smallint,
  tmpLocGid    integer,
  tmpPartijGid integer,
  tmpAantal    numeric(15,3)
)
begin
/*
  Volledige routine (na elke regel wordt het restant berekend en doorgegaan naar de volgende regel tot restant=0)
  - 1. Negatief aantal OF altijd voorkeurslocatie -> gebruik alles in de voorkeurslocatie
  - 2. Lus per partij:
  - 2.A Voorkeurslocatie indien volledig beschikbaar
  - 2.B Volledige restant uit eerste picklocatie in oplopende volgorde van beschikbare voorraad
  - 2.C Bulklocatie indien volledig beschikbaar (restant na deze picklocaties), volgorde: oplopend
  - 2.D Zoveel mogelijk uit voorkeurslocatie
  - 2.E grijplocatie indien volledig beschikbaar, volgorde: oplopend
  - 2.F Eerste van overige pick-locaties deels beschikbaar, volgorde: aflopend
  - Lus:
    - Bepaal restant
    - 3.A picklocaties indien restant volledig beschikbaar, volgorde: oplopend
    - 3.B picklocaties voor restant, volgorde: aflopend
  - Lus indien Bulklocaties ook gebruiken (Alleen als vinkje Bulklocaties gebuiken als niet voldoende beschikbaar op picklocaties aan):
    (Hier geldt NIET het vinkje Gebruik 1 bulklocatie als niet in 1 picklocatie beschikbaar)
     - Bepaal restant
     - 3.A bulklocaties indien restant volledig beschikbaar, volgorde: oplopend
     - 3.B bulklocaties voor restant, volgorde: aflopend
*/
  declare @IsLeveringSoort smallint =  sign(@OrrAantalBesteld); // 0 = niets doen, -1 = retourlevering, 1 = normale levering


  // We vullen deze tabel, die geven we gesorteerd terug
  declare local temporary table tmpLocaties(
    tmpGid integer default autoincrement,
    tmpStap smallint,
    tmpLocGid integer,
    tmpPartijGid integer,
    tmpAantal numeric(15,3)
  ) on commit preserve rows;

  declare @AantalNogTeVinden numeric(15,3) = @AantalBenodigdVoorrEenh;


  // Instellingen uit vaste gegevens
  declare @VofRegelDefLocatie smallint; // Welke locatie gebruiken? 0 = Picklocatie, 1 = Standaard locatie
  declare @Gebruik1BulkLocatie smallint = 1; // we doen alvast alsof het mag, hieronder wordt het uit de vaste gegevens gelezen
  declare @GebruikBulkLocaties smallint = 1; // we doen alvast alsof het mag, hieronder wordt het uit de vaste gegevens gelezen

  // Instellingen bij artikel
  declare @PartijVolgorde smallint;
  declare @ArtIsVoorraadRegistrerend smallint;

  // Instellingen bij orderregel
  declare @_OrrGid integer = @OrrGid; // Doen we niks mee, niet gereserveerd op deze orderregel, dan toch niet te pakken

  // Maatwerk-haakje voor overrulen van deze routine
  if exists(select first 1 from sys.sysprocedure where proc_name = 'MAATWERK_OrderRegelSpecificaties_BeschikbaarPerLocatie') then
    begin
      declare @IsStandaardRoutineOverruled smallint = 0;
      call MAATWERK_OrderRegelSpecificaties_BeschikbaarPerLocatie(
        @MagGid = @MagGid,
        @AantalBenodigdVoorrEenh = @AantalBenodigdVoorrEenh,
        @ArtGid = @ArtGid,
        @ArtPartijGid = @ArtPartijGid,
        @ZoekPerAantalVoorraadeenheden = @ZoekPerAantalVoorraadeenheden,
        @MatViewNummerVoorraadAantallen = @MatViewNummerVoorraadAantallen,
        @OrrAantalBesteld = @OrrAantalBesteld,
        @OverruleAllesVan1BulkLocatie = @OverruleAllesVan1BulkLocatie,
        @IsStandaardRoutineOverruled = @IsStandaardRoutineOverruled,
        @AfrondenPer = @AfrondenPer,
        @AfkappenPer = @AfkappenPer
      );
      if @IsStandaardRoutineOverruled = 1 then
        leave; // Gelijk stoppen met deze procedure!
      end if;
    end;
  end if;

  // Enkele gegevens van artikel opvragen
  select
    if ArtIsPartijVerkoopCheckOuderePartijOp = 0 then 0 else ArtPartijVerkoopCheckOuderePartij + 1 endif,
    ArtHeeftVoorraad
  into
    @PartijVolgorde,
    @ArtIsVoorraadRegistrerend
  from tabArtikel
  where Artgid = @ArtGid;

  // Vaste gegevens ophalen
  if (IsModuleActive('m1') = 0) or (@ArtIsVoorraadRegistrerend = 0) then
    // Geen meerdere magazijnen/locaties, DUS altijd standaard locatie (en gewoon dus altijd gebruiken ongeacht soort)
    set @VofRegelDefLocatie = 1 /*Standaard locatie*/ ;
  else
    select first VofRegelDefLocatie,
    case @OverruleAllesVan1BulkLocatie
      when 0 then isnull(VofRegelBulkAllesBeschikbaar, 0)  // 0 = volgens VG
      when 1 then 1                                        // 1 = altijd WEL (dus doe altijd controle op 1 bulklocatie)
      when -1 then 0                                       // -1 = altijd NIET (dus skip controle op alles uit 1 bulklocatie)
    end,
    isnull(VofRegelBulkDeelsBeschikbaar, 0)
    into @VofRegelDefLocatie, @Gebruik1BulkLocatie, @GebruikBulkLocaties
    from tabVasteGegevensOrdersFactureren;
  end if;

  // Als is ingesteld om de standaard locatie te gebruiken, dan gewoon die pakken, ongeacht het aantal in voorraad
  // Als de regel zelf negatief is (aantal besteld < 0) dan ook gewoon de default pakken
  // --- 1. Negatief aantal OF standaard locatie
  if @AantalNogTeVinden <> 0 and (@VofRegelDefLocatie = 1 /*Standaard locatie*/ or @IsLeveringSoort = -1 /*retourlevering*/) then
    insert into tmpLocaties(tmpStap,tmpLocGid, tmpPartijGid, tmpAantal)
    values(
      1,
      IsNull((select ArtMagDefaultLocGid from tabArtikelMagazijn where ArtMagMagGid  = @MagGid and ArtMagArtGid = @ArtGid),
             (select first LocGid from tabLocatie where LocNaam='(Standaard)' and (LocMagGid = @MagGid))),
      @ArtPartijGid,
      case
        when @AfkappenPer is not null then floor(@AantalNogTeVinden/@AfkappenPer) * @AfkappenPer
        when @AfrondenPer is not null then round(@AantalNogTeVinden/@AfrondenPer, 0)*@AfrondenPer
        else @AantalNogTeVinden
      end
    );
    set @AantalNogTeVinden = 0;
  end if;



  /// --- 2 Lus per partij
  if @AantalNogTeVinden <> 0 then
    // Lus om bijv. vanaf de oudste partij te gaan zoeken, als we al een parij hebben, dan alleen die partij (dus slechts 1 record)
    // Als er geen partij is meegegeven, dan moeten we hier alsnog 1 record uit krijgen, daarom de untion
    for @PartijCursor AS CURSOR_ArtikelPartij CURSOR FOR
      select ArtPartijGid @_ArtPartijGid,
        case @PartijVolgorde
          //when 0 /*naam*/ then noppes (dus obv naam hierna)
          when 1 /*productiedatum*/ then ArtPartijDatumProductie
          when 2 /*ontvangstdatum*/ then ArtPartijDatumOntvangst
          when 3 /*THTdatum*/ then ArtPartijThtDatum
        end,
        ArtPartijNummer

      from   tabartikel
             left outer join tabArtikelPartij on
                   (ArtPartijArtGid = @ArtGid)
               and (@ArtPartijGid is null or ArtPartijGid = @ArtPartijGid)
               and (ArtPartijIsGeblokkeerdVoorVerkoop = 0)
               and (   @ArtPartijGid is not null
                    or (    (ArtPartijVrijVanafDatum is null or date(now()) >= ArtPartijVrijVanafDatum)
                        and (ArtPartijVrijTmDatum    is null or date(now()) <= ArtPartijVrijTmDatum)
                       )
                   )
      where  ArtGid = @ArtGid and ((ArtIsPartijRegistreren + ArtSerieNrRegistreren) > 0 and (@PartijVolgorde <> 0 or @ArtPartijGid is not null))
             // Partij moet wel verkoopbaar zijn OP HET MOMENT VAN VANDAAG (serverdatum)


      UNION ALL

      select null, null, null // Zorg ervoor dat er 1 record terugkomt als hierboven niks terug kwam
      from tabartikel
      where ArtGid = @ArtGid and not ((ArtIsPartijRegistreren + ArtSerieNrRegistreren) > 0 and (@PartijVolgorde <> 0 or @ArtPartijGid is not null))

      order by 2, 3

    for read only
    do
      // --- 2.A    Voorkeurslocatie indien volledig beschikbaar
      if @AantalNogTeVinden > 0 then
        // TODO: Hier is nu de partij gewoon meegenomen, maar het gaat erom dat als partij niet uitmaakt en er is in totaal voldoende, dan moete de partijen apart worden opgenomen in de tmpLocaties
        //call trace('  (1) Alles uit voorkeurslocatie');
        insert into tmpLocaties(tmpStap,tmpLocGid, tmpPartijGid, tmpAantal)
        select 2, zlLocGid, zlArtPartijGid, zlAantalBeschikbaar
        from OrderRegelSpecificaties_ZoekLocaties(
               @MatViewNummerVoorraadAantallen,
               @MagGid,
               @ArtGid,
               @_ArtPartijGid,
               @PartijVolgorde,
               @AantalNogTeVinden,
               @ZoekPerAantalVoorraadEenheden,
               0 /*Voorkeur, onafhankelijk van type*/,
               1 /*Stop zodra te weinig, niet teruggeven als te weinig*/,
               @OrrGid = @_OrrGid,
               @ExclLocList = (select list(tmpLocGid) from tmpLocaties where tmpPartijGid is not distinct from @_ArtPartijGid),
               @AfrondenPer = @AfrondenPer,
               @AfkappenPer = @AfkappenPer
             );

        // Restant
        select @AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalNogTeVinden from tmpLocaties;
        //call trace('  (1) Alles uit voorkeurslocatie. nog te vinden: ' || @AantalNogTeVinden || ' records in tmpLocaties: ' || (select count(*) from tmpLocaties));
      end if;


      // --- 2.B    Volledige restant uit eerste picklocatie in oplopende volgorde van beschikbare voorraad
      // (excl. voorkeur, want die is al gecontroleerd)
      if @AantalNogTeVinden > 0 then
        //call trace('  (2) Alles uit 1 grijplocatie');
        insert into tmpLocaties(tmpStap, tmpLocGid, tmpPartijGid, tmpAantal)
        select 3, zlLocGid, zlArtPartijGid, zlAantalBeschikbaar
        from OrderRegelSpecificaties_ZoekLocaties(
               @MatViewNummerVoorraadAantallen,
               @MagGid,
               @ArtGid,
               @_ArtPartijGid,
               @PartijVolgorde,
               @AantalNogTeVinden,
               @ZoekPerAantalVoorraadEenheden,
               2 /*Grijp excl. voorkeur*/,
               1 /*Stop zodra te weinig, niet teruggeven als te weinig*/,
               1 /*Minste eerst*/,
               @OrrGid = @_OrrGid,
               @ExclLocList = (select list(tmpLocGid) from tmpLocaties where tmpPartijGid is not distinct from @_ArtPartijGid),
               @AfrondenPer = @AfrondenPer,
               @AfkappenPer = @AfkappenPer
             );
             //where zlAantalBeschikbaar >= @AantalNogTeVinden;
        select @AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalNogTeVinden from tmpLocaties;
        //call trace('  (2) Alles uit 1 grijplocatie, nu nog benodigd: ' || @AantalNogTeVinden || ' records in tmpLocaties: ' || (select count(*) from tmpLocaties));
      end if;


      // --- 2.C    Bulklocatie indien volledig beschikbaar, volgorde: oplopend
      // Als mag, dan volledige restant uit 1 bulk-locatie halen in oplopende volgorde van beschikbare voorraad
      // (excl. voorkeur, want die is al gecontroleerd)
      if @AantalNogTeVinden > 0 and @Gebruik1BulkLocatie = 1 then
        //call trace('  (3) Alles uit 1 bulklocatie');
        insert into tmpLocaties(tmpStap, tmpLocGid, tmpPartijGid, tmpAantal)
        select 4, zlLocGid, zlArtPartijGid, zlAantalBeschikbaar
        from OrderRegelSpecificaties_ZoekLocaties(
               @MatViewNummerVoorraadAantallen,
               @MagGid,
               @ArtGid,
               @_ArtPartijGid,
               @PartijVolgorde,
               @AantalNogTeVinden,
               @ZoekPerAantalVoorraadEenheden,
               3 /*Bulk excl. voorkeur*/,
               1 /*Stop zodra te weinig, niet teruggeven als te weinig*/,
               1 /*Minste eerst*/,
               @OrrGid = @_OrrGid,
               @ExclLocList = (select list(tmpLocGid) from tmpLocaties where tmpPartijGid is not distinct from @_ArtPartijGid),
               @AfrondenPer = @AfrondenPer,
               @AfkappenPer = @AfkappenPer
             );
        select @AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalNogTeVinden from tmpLocaties;
        //call trace('  (3) Alles uit 1 bulklocatie, nu nog benodigd: ' || @AantalNogTeVinden || ' records in tmpLocaties: ' || (select count(*) from tmpLocaties));
      end if;

      // --- 2.D    Zoveel mogelijk uit voorkeurslocatie
      // Als er iets in de voorkeur is, ongeacht type, dan dat gebruiken
      if @AantalNogTeVinden > 0 then
        //call trace('  (4) iets uit voorkeurslocatie, ongeacht type');
        insert into tmpLocaties(tmpStap,tmpLocGid, tmpPartijGid, tmpAantal)
        select 5, zlLocGid, zlArtPartijGid, zlAantalBeschikbaar
        from OrderRegelSpecificaties_ZoekLocaties(
               @MatViewNummerVoorraadAantallen,
               @MagGid,
               @ArtGid,
               @_ArtPartijGid,
               @PartijVolgorde,
               @AantalNogTeVinden,
               @ZoekPerAantalVoorraadEenheden,
               0 /*Voorkeur, onafhankelijk van type*/,
               0 /*Ga door als te weinig, dus geef voorkeur terug ook als niet voldoende*/,
               @OrrGid = @_OrrGid,
               @ExclLocList = (select list(tmpLocGid) from tmpLocaties where tmpPartijGid is not distinct from @_ArtPartijGid),
               @AfrondenPer = @AfrondenPer,
               @AfkappenPer = @AfkappenPer
             );

        // Restant
        select @AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalNogTeVinden from tmpLocaties;
        //call trace('  (4) Alles uit voorkeurslocatie. nog te vinden: ' || @AantalNogTeVinden || ' records in tmpLocaties: ' || (select count(*) from tmpLocaties));
      end if;


      // --- 2.E    Grijplocatie indien volledig beschikbaar, volgorde: oplopend
      if @AantalNogTeVinden > 0 then
        insert into tmpLocaties(tmpStap, tmpLocGid, tmpPartijGid, tmpAantal)
        select 6, zlLocGid, zlArtPartijGid, zlAantalBeschikbaar
        from OrderRegelSpecificaties_ZoekLocaties(
               @MatViewNummerVoorraadAantallen,
               @MagGid,
               @ArtGid,
               @_ArtPartijGid,
               @PartijVolgorde,
               @AantalNogTeVinden,
               @ZoekPerAantalVoorraadEenheden,
               2 /*Grijplocaties excl. voorkeur*/,
               1 /*Stop als te weinig*/,
               @LocatieVolgorde = 1 /*oplopend*/,
               @OrrGid = @_OrrGid,
               @ExclLocList = (select list(tmpLocGid) from tmpLocaties where tmpPartijGid is not distinct from @_ArtPartijGid),
               @AfrondenPer = @AfrondenPer,
               @AfkappenPer = @AfkappenPer
             )
        where zlAantalBeschikbaar >= @AantalNogTeVinden;
        select @AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalNogTeVinden from tmpLocaties;
      end if;

      // --- 2.F    Eerste van overige pick-locaties deels beschikbaar, volgorde: aflopend
      if @AantalNogTeVinden > 0 then
        //call trace('  (4) volledige aantal, Uit meer locaties, eerst voorkeur');
        insert into tmpLocaties(tmpStap, tmpLocGid, tmpPartijGid, tmpAantal)
        select 6, zlLocGid, zlArtPartijGid, zlAantalBeschikbaar
        from OrderRegelSpecificaties_ZoekLocaties(
               @MatViewNummerVoorraadAantallen,
               @MagGid,
               @ArtGid,
               @_ArtPartijGid,
               @PartijVolgorde,
               @AantalNogTeVinden,
               @ZoekPerAantalVoorraadEenheden,
               2 /*Grijplocaties excl. voorkeur*/,
               2 /*Stop als te weinig, geef die locatie nog wel terug*/,
               @LocatieVolgorde = 0 /*aflopend*/,
               @OrrGid = @_OrrGid,
               @ExclLocList = (select list(tmpLocGid) from tmpLocaties where tmpPartijGid is not distinct from @_ArtPartijGid),
               @AfrondenPer = @AfrondenPer,
               @AfkappenPer = @AfkappenPer
             );
        select @AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalNogTeVinden from tmpLocaties;
        //call trace('  (4) Uit meer locaties, eerst voorkeur. nu nog benodigd: ' || @AantalNogTeVinden || ' records in tmpLocaties: ' || (select count(*) from tmpLocaties));
      end if;

      //--- lus: Eerst voor de grijp- daarna voor de bulklocaties, enige verschil is @DoLocSoort die voor bulk altijd 1 hoger is dan grijp
      begin
        declare @VorigeAantalNogTeVinden numeric(15,3) = @AantalBenodigdVoorrEenh;
        declare @GrijpIpvBulk smallint = 1; // 1 = grijp, 0 = bulk; alleen 0 of 1, zodat we kunnen rekenen!= hiermee
        declare @AantalGevondenIn3A numeric(15,3) = 0; // Gebruiken om 3B alleen te doen als 3A niks gevonden
        loop_grijp_dan_bulk:
        loop

          // Bij bulk alleen indien vinkjes!! @GrijpIpvBulk + @Gebruik1BulkLocatie+@GebruikBulkLocaties
          // Lus: - restant uit pick(of bulk)locaties indien volledig beschikbaar, in oplopende volgorde
          //      - restant uit 1 pick(of bulk)locatie indien deels beschikbaar, in oplopende volgorde (Dus stop zodra er iets is gevonden)
          set @VorigeAantalNogTeVinden = @AantalNogTeVinden;
          loop_volledig_locatie_of_restant:
          loop
            // --- 3.A    picklocaties indien restant volledig beschikbaar, volgorde: oplopend
            // - restant uit picklocaties indien volledig beschikbaar, in oplopende volgorde
            set @AantalGevondenIn3A = 0;
            if @AantalNogTeVinden > 0 and (@GrijpIpvBulk + /*@Gebruik1BulkLocatie + (deze NIET, want dat geldt alleen voor ALLES uit 1 bulklocatie*/ @GebruikBulkLocaties > 0) then
              //call trace('  (5) Uit meer locaties, niet-voorkeurs-grijplocaties');
              insert into tmpLocaties(tmpStap, tmpLocGid, tmpPartijGid, tmpAantal)
              select 7+2-@GrijpIpvBulk*2, zlLocGid, zlArtPartijGid, zlAantalBeschikbaar
              from OrderRegelSpecificaties_ZoekLocaties(
                     @MatViewNummerVoorraadAantallen,
                     @MagGid,
                     @ArtGid,
                     @_ArtPartijGid,
                     @PartijVolgorde,
                     @AantalNogTeVinden,
                     @ZoekPerAantalVoorraadEenheden,
                     2+(1-@GrijpIpvBulk) /*Grijp(of bulk) excl. voorkeur*/,
                     1 /*stop als te weinig, deze niet teruggeven*/,
                     1 /*minste eerst*/,
                     @OrrGid = @_OrrGid,
                     @ExclLocList = (select list(tmpLocGid) from tmpLocaties where tmpPartijGid is not distinct from @_ArtPartijGid),
                     @AfrondenPer = @AfrondenPer,
                     @AfkappenPer = @AfkappenPer
                   );
                   //where zlAantalBeschikbaar >= @AantalNogTeVinden;
              select @AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalNogTeVinden from tmpLocaties;
              set @AantalGevondenIn3A = @VorigeAantalNogTeVinden - @AantalNogTeVinden;
              //call trace('  (5) Uit meer locaties, niet-voorkeurs-grijplocaties. nu nog benodigd: ' || @AantalNogTeVinden || ' records in tmpLocaties: ' || (select count(*) from tmpLocaties));
            end if;
            // Als er niks meer te vinden is dan verlaten van de lus
            if @AantalNogTeVinden = 0 then
              leave loop_volledig_locatie_of_restant;
            end if;
            // --- 3.B    picklocaties voor restant, volgorde: aflopend
            //     Deze alleen doen als bij 3.A niets was gevonden!
            if @AantalGevondenIn3A = 0 and @AantalNogTeVinden > 0 and (@GrijpIpvBulk + @GebruikBulkLocaties > 0) then
              //call trace('  (5) Uit meer locaties, niet-voorkeurs-grijplocaties');
              insert into tmpLocaties(tmpStap, tmpLocGid, tmpPartijGid, tmpAantal)
              select 8+2-@GrijpIpvBulk*2, zlLocGid, zlArtPartijGid, zlAantalBeschikbaar
              from OrderRegelSpecificaties_ZoekLocaties(
                     @MatViewNummerVoorraadAantallen,
                     @MagGid,
                     @ArtGid,
                     @_ArtPartijGid,
                     @PartijVolgorde,
                     @AantalNogTeVinden,
                     @ZoekPerAantalVoorraadEenheden,
                     2+(1-@GrijpIpvBulk) /*Grijp(of bulk) excl. voorkeur*/,
                     2 /*stop als te weinig, geef de eerstgevondene wel terug*/,
                     0 /*Aflopend (Let ook op de order by van deze query!!)*/,
                     @OrrGid = @_OrrGid,
                     @ExclLocList = (select list(tmpLocGid) from tmpLocaties where tmpPartijGid is not distinct from @_ArtPartijGid),
                     @AfrondenPer = @AfrondenPer,
                     @AfkappenPer = @AfkappenPer
                   );
              select @AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalNogTeVinden from tmpLocaties;
              //call trace('  (5) Uit meer locaties, niet-voorkeurs-grijplocaties. nu nog benodigd: ' || @AantalNogTeVinden || ' records in tmpLocaties: ' || (select count(*) from tmpLocaties));
            end if;
            // Als er niks meer is te vinden, dan zijn we helemaal klaar, zowel met grijp- als bulklocaties
            if @AantalNogTeVinden = 0 then
              leave loop_grijp_dan_bulk;
            end if;
            // Als er niets is gevonden in de grijp, dan zijn we klaar met deze lus (ready voor de bulklocaties)
            if @VorigeAantalNogTeVinden = @AantalNogTeVinden then
              leave loop_volledig_locatie_of_restant;
            end if;

            set @VorigeAantalNogTeVinden = @AantalNogTeVinden; // En onthouden, zodat we de volgende keer misschien wel kunnen verlaten
          end loop /*loop_volledig_locatie_of_restant*/;

          set @GrijpIpvBulk = @GrijpIpvBulk - 1;
          if @GrijpIpvBulk < 0 or @Gebruik1BulkLocatie+@GebruikBulkLocaties = 0 then
            leave loop_grijp_dan_bulk;
          end if;
        end loop /*loop_grijp_dan_bulk*/;
      end;
    end for; // partijlus
  end if; // @AantalBenodigdVoorrEenh<>0

  // Als er nog wat over is, dan zonder locatie (niet op te lossen)
  //if @AantalNogTeVinden > 0 then
  //  insert into tmpLocaties(tmpStap, tmpLocGid, tmpPartijGid, tmpAantal)
  //  values(99, null, @ArtPartijGid, @AantalNogTeVinden)
  //end if;

  select
    tmpGid,
    tmpStap,
    tmpLocGid,
    tmpPartijGid,
    tmpAantal
  from
    tmpLocaties left outer join tabLocatie on LocGid = tmpLocGid
  order by if tmpLocGid is null then 1 else 0 endif /*zonder locatie als laatste*/, locNaam, tmpGid;
end;


create or replace function OrderRegelSpecificaties_Opschonen(
  in  @OrkGid integer,
  in  @OrrGid integer,
  in  @NegeerLocatie smallint default 0
)
  returns smallint //0 = Niks gewijzigd, 1 = Iets gewijzigd
begin
  declare @result smallint = 0;

  // Locatieregels verwijderen die geen locatie, partij en serienummer en geen aantal leverd hebben
  // LET OP Deze condities moeten gelijk zijn aan die in de berekening van @_AantalBenodigdVoorrEenh in de for...loop van de OrderRegelSpecificaties_VulLocatiesAan
  //call trace('Stap 2 van updaten');
  delete from tabOrderregelLocatie
  where OrlOrrGid = @OrrGid
    and (OrlLocGid is null or @NegeerLocatie = 1)
    and OrlArtPartijGid is null // Niet nodig, is ofwel die van de regel, ofwel handmatig aangepast
    and OrlArtSerieGid is null
    and OrlGeleverd = 0;
    //ACWdefect72989removed and OrlHandmatig = 0;
  if @@rowcount <> 0 then
    set @result = 1;
  end if;

  // Update bestaande regels MET aanteal geleverd en zet DezeLevering op 0
  //call trace('Stap 3 van updaten');
  if @NegeerLocatie = 1 then
    update tabOrderregelLocatie
    set OrlDezeLevering = 0,
        OrlDezeLeveringVrrdEenh = 0
    where OrlOrrGid = @OrrGid
      //and OrlLocGid is null
      and OrlArtSerieGid is null
      //and OrlHandmatig = 0;
    ;

    if @@rowcount <> 0 then
      set @result = 1;
    end if;
  end if;

  return @result;
end;


create or replace procedure OrderRegelSpecificaties_SplitsSpecRegel(
  in @OrlGid integer,
  in @AantalBehoudenInVrrdEenh numeric(15,3),
  out @OrlGidNew integer
)
begin
  // Past restant in verkoopeenheid?
  // ja -> nieuw record + bestaande record aanpassen op aantallen
  // nee -> mag spec.regel afwijken?
  //        ja -> zet eenheid op voorraadeenheid
  //        nee -> kan niet! geef fout

  declare @OrlDezeLeveringVrrdEenh numeric(15,3);
  declare @OrlArtSerieGid integer;
  declare @AantalVrrdEenhInVerkEenh numeric(15,3);
  declare @EenheidMagAfwijken smallint;
  declare @VkeGid integer;
  declare @VkeAantalDecimalen integer;
  declare @artgid integer;

  // info uitlezen
  select OrrArtGid, OrlArtSerieGid, OrlDezeLeveringVrrdEenh, VkeAantalVoorraadEenhedenInVerkoopEenheid,
          VkeGid, if VkeAantalDecimalen = 4 then (select VkeAantalDecimalen from tabVerkoopEenheid where VkeIsVoorraadEenheid = 1 and VkeArtGid = OrrArtGid) else VkeAantalDecimalen endif,
         if (   (OrrAantalVrrdEenhInVerkEenhMagAfwijken <> 0) /*vast aantal,        dus VKE mag niet afwijken*/
             or (OrrVervolgMasterOrrGid is not null)          /*volgregel,          dus VKE mag niet afwijken!*/
             or (OrlArtSerieGid is not null)                  /*Serienummer,        dus VKE mag niet afwijken*/
             or (OrlGeleverd <> 0)                            /*Al aantal geleverd, dus VKE mag niet afwijken*/
            )
         then 0 else 1 endif
  into @ArtGid, @OrlArtSerieGid, @OrlDezeLeveringVrrdEenh, @AantalVrrdEenhInVerkEenh,
       @VkeGid, @VkeAantalDecimalen,
       @EenheidMagAfwijken
  from tabOrderRegelLocatie
  inner join tabVerkoopeenheid on VkeGid = OrlVkeGid
  inner join tabOrderRegel on OrrGid = OrlOrrGid
  where OrlGid = @OrlGid;

  // Meer overhouden dan de regel, dan niks doen
  if @AantalBehoudenInVrrdEenh >= @OrlDezeLeveringVrrdEenh or @OrlArtSerieGid is not null then
    set @OrlGidNew = null;
    leave;
  end if;

  // Past aantal in VKE?
  // nee -> mag andere vke? ja -> zoek op, anders FOUT
  if mod(@AantalBehoudenInVrrdEenh, @AantalVrrdEenhInVerkEenh) <> 0 then
    // Aantal past niet in verkoopeenheid!
    if @EenheidMagAfwijken = 0 then
      // (20780) %1! niet mogelijk: %2!.
      call raise(20780, 'Specificatieregel splitsen', 'Verkoopeenheid mag niet afwijken');
    else
      // Pak de voorraadeenheid!
      select VkeGid, VkeAantalDecimalen, VkeAantalVoorraadEenhedenInVerkoopEenheid
      into @VkeGid, @VkeAantalDecimalen, @AantalVrrdEenhInVerkEenh
      from tabVerkoopEenheid
      where VkeIsVoorraadEenheid = 1 and VkeArtGid = @ArtGid;
    end if;
  end if;

  // Toevoegen van nieuwe regel obv bestaande regel en de gevonden eenheid en spec.aantal-aantal dat we willen behouden
  insert into tabOrderRegelLocatie with auto name
  select
     OrlOrrGid,
     OrlMagGid,
     OrlLocGid,
     OrlArtPartijGid,
     OrlArtSerieGid,
     @VkeGid OrlVkeGid,
     @VkeAantalDecimalen OrlAantDecAantal,
     OrlAantDecAantalVrrdEenh,
     (tabOrderRegelLocatie.OrlDezeLeveringVrrdEenh - @AantalBehoudenInVrrdEenh) / @AantalVrrdEenhInVerkEenh OrlDezeLevering,
     tabOrderRegelLocatie.OrlDezeLeveringVrrdEenh - @AantalBehoudenInVrrdEenh OrlDezeLeveringVrrdEenh,
     OrlSSCCID,
     OrlWMSstatus
  from
    tabOrderRegelLocatie
  where
    OrlGid = @OrlGid;
  set @OrlGidNew = @@Identity;

  // update bestaande regel obv gevonden eenheid en aantal te behouden
  update tabOrderRegelLocatie
  set OrlDezeLevering         = @AantalBehoudenInVrrdEenh/@AantalVrrdEenhInVerkEenh,
      OrlDezeLeveringVrrdEenh = @AantalBehoudenInVrrdEenh,
      // voor als de VKE is gewijzigd
      OrlVkeGid = @VkeGid,
      OrlAantDecAantal = @VkeAantalDecimalen
  where OrlGid = @OrlGid;
end;


create or replace function OrderRegelSpecificaties_ToewijzenNodigObvStatus(
  in  @OrkGid  integer,
  in  @GewijzigdeOrderstatus nchar(20) default 'A', // Wordt gebruikt om te bepalen waardoor we nu zuden moeten toewijzen
                                                    // Alleen als de gewijzigde status in de keuze in vaste gegevens staat moeten we toewijzen!
                                                    // A = invoer (Bij INVOER dan moet de huidige orderstatus >= keuze in VG zijn)
                                                    // B = goedgekeurd
                                                    // C = Vrijgegeven voor verzamellijst
                                                    // D = Verzamellijst afgedrukt
                                                    // E = WMS-Dashboard: toewijzen aan scanner
                                                    // F = WMS-orderpicken: start picken
                                                    // G = Verzamellijst verwerkt
                                                    // H = Vrijgegeven voor levering
                                                    // I = Vrijgegeven voor facturering
  in  @OverruledOrderStatus smallint default null   // Nodig omdat deze routine soms wordt aangeroepen terwijl in de database de nieuwe status nog niet bekend is. Die hier dan meegeven ipv door de storedproc op te halen
                                                    // 1 = Invoeren orderregel,
                                                    // 2 = Goedkeuren order,
                                                    // 3 = Vrij voor verzamellijst,
                                                    // 4 = Verzamellijst afgedrukt
                                                    // 5 = WMS, toewijzen
                                                    // 6 = WMS, start picken
                                                    // 7 = Vrij voor leveren
)
  returns smallint // 0 = niet nodig, 1 = nodig obv wel/niet verzamellijst en status order tobv status in vaste gegevens
begin
  declare @LocatieToewijzenStatus smallint; // Zie veld VofRegelLocatieToewijzenWelViaVerzamellijst/VofRegelLocatieToewijzenNietViaVerzamellijst
  declare @LocatieToewijzenStatusChar nchar(1);
  declare @OrderStatus smallint;
  declare @result smallint;

  if IsOrderSpecificatieregelActief() = 0 then
    /*overrule, WEL toewijzen*/
      set @result = 1;
  else

    // Vaste gegevens opvragen
    case @@OverruleOrderregelLocatieAanvullen
      when 0 /*niet overrulen*/ then
        select
          if OrkIsVerzamellijstGebruiken = 0 then VofRegelLocatieToewijzenNietViaVerzamellijst else VofRegelLocatieToewijzenWelViaVerzamellijst endif LocatieToewijzenStatus,
          case LocatieToewijzenStatus
            when 1 /*Invoeren van orderregel*/                      then 'A'
            when 2 /*Goedkeuren van order*/                         then 'B'
            when 3 /*Vrijgeven voor verzamellijst*/                 then 'C'
            when 4 /*Verzamellijst afgedrukt*/                      then 'D'
            when 5 /*WMS-dashboard - toewijzen order aan scanner*/  then 'E'
            when 6 /*WMS-orderpicken-app - start met picken order*/ then 'F'
            //when ? /*Verzamellijst verwerkt*/                       then 'G'
            when 7 /*Vrijgeven voor leveren*/                       then 'H'
            //when ? /*Vrijgeven voor factureren*/                       then 'I'
          end,
          case
            when OrkVrijVoorLevering = 1 then 7 /*Vrij voor levering*/
            when OrkVerzamelLijstAfgedrukt = 1 then 4 /*Verzamellijst afgedrukt*/
            when OrkVrijVoorVerzamelLijst = 1 then 3 /*Vrij voor verzamellijst*/
            when OrkGoedgekeurd = 1 then 2 /*Goedgekeurd*/
            else 1 /*Invoeren order*/
          end

        into @LocatieToewijzenStatus, @LocatieToewijzenStatusChar, @OrderStatus
        from tabOrderkop, tabVasteGegevensOrdersFactureren
        where OrkGid = @OrkGid;

        if @OverruledOrderStatus is not null and @OverruledOrderStatus > @LocatieToewijzenStatus then
          // Overrule = 1 (Invoeren), order = 3 (Vrij voor verzamellijst), vaste gegevens=2 ->
          // WEL nodig, want orderstatus > meegegeven status, dus orderstatus prevaleerd en die is in voorbeeld > vaste gegevens
          set @OrderStatus = @OverruledOrderStatus; // Overruled orderstatus, misschien voor WMS of toekomstige status
        end if;

        set @result =
          if    locate(@GewijzigdeOrderstatus, @LocatieToewijzenStatusChar) > 0           // Is precies de statuswijzigingskeuze in VG
             or (
                 locate(@GewijzigdeOrderstatus, 'A') > 0 // de statuswijziging is het invoeren/wijzigen
                 and @OrderStatus >= @LocatieToewijzenStatus                    // en de orderstatus is groter of gelijk aan keuze in VG
                )
        then 1 else 0 endif;
      when 1 /*overrule, NIET toewijzen*/ then
        set result = 0;
      when -1 /*overrule, WEL toewijzen*/ then
        set result = 1;
    end;

  end if;

  return @result;

//  select
//    if OrkIsVerzamellijstGebruiken = 0 then VofRegelLocatieToewijzenNietViaVerzamellijst else VofRegelLocatieToewijzenWelViaVerzamellijst endif,
//    case
//      when OrkVrijVoorLevering = 1 then 7 /*Vrij voor levering*/
//      when OrkVerzamelLijstAfgedrukt = 1 then 4 /*Verzamellijst afgedrukt*/
//      when OrkVrijVoorVerzamelLijst = 1 then 3 /*Vrij voor verzamellijst*/
//      when OrkGoedgekeurd = 1 then 2 /*Goedgekeurd*/
//      else 1 /*Invoeren order*/
//    end
//  into @LocatieToewijzenStatus, @OrderStatus
//  from tabOrderkop,
//       tabVasteGegevensOrdersFactureren
//  where OrkGid = @OrkGid;
//
//  if @OverruledOrderStatus is not null and @OverruledOrderStatus > @LocatieToewijzenStatus then
//    // Overrule = 1 (Invoeren), order = 3 (Vrij voor verzamellijst), vaste gegevens=2 ->
//    // WEL nodig, want orderstatus > meegegeven status, dus orderstatus prevaleerd en die is in voorbeeld > vaste gegevens
//    set @OrderStatus = @OverruledOrderStatus; // Overruled orderstatus, misschien voor WMS of toekomstige status
//  end if;
//
//  // Bepaal de huidige status van de order
//
//  set @result = if @OrderStatus >= @LocatieToewijzenStatus then 1 else 0 endif;
//  return @result;
end;


create or replace procedure OrderRegelSpecificaties_VulLocatiesAan(
  in  @OrkGid integer,
  in  @OrrGid integer default null,
  in  @MatViewNummerVoorraadAantallen nchar(20) default null,    // Als deze gevuld, dan verversen en gebruiken, anders maken we (tijdelijk) onze eigen materialized view
  in  @VulLocaties smallint default 0, // 0 = afhankelijk van status in VGverkopen en meegegeven actie (@GewijzigdeOrderstatus),
                                       // 1 = altijd invullen,
                                       // anders leeg laten (niet toewijzen)
  in  @GewijzigdeOrderstatus nchar(20) default 'A', // Wordt gebruikt om te bepalen waardoor we nu zuden moeten toewijzen
                                                   // Zie OrderRegelSpecificaties_ToewijzenNodigObvStatus
  in  @OrkIsVrijgegevenVoorLeveren smallint default null, // Om de standaard te overrulen, kunnen we alvast hard op testen omdat deze routine kan worden aangeroepen venuit de BEFORE trigger
  in  @ForceerVoorraadEenheid smallint default 0, // 0 = doe normaal, 1 = altijd voorraadeenheid forceren
  out @HeeftSpecregelsZonderLocatie smallint
)
begin
  declare @MatViewNummer nchar(20) = @MatViewNummerVoorraadAantallen;
  declare @SqlStatement long nvarchar;
  declare @AantalGevonden numeric(15,3);
  declare @DoVulLocaties smallint; //1 = invullen, 0 = obv orderstatus

  declare @ListOfArtGid long nvarchar = ','; // Lijst van verwerkte artgid tbv performance
  // Instellingen uit vaste gegevens
  declare @VofRegelDefLocatie smallint; // Welke locatie gebruiken? 0 = Picklocatie, 1 = Standaard locatie
  declare @Gebruik1BulkLocatie smallint = 0; // Nu even hard gezet, Kunnen we uit 1 (EEN) bulk-locatie pakken?
  declare @GebruikBulkLocaties smallint = 1; // Nu even hard gezet, komt straks uit vaste gegevens (of zelfs order?)
  // Instellingen vanuit de orderkop
  declare @OrkIsVerzamellijstGebruiken smallint;

  // We vullen eerst deze tabel voordat we daarvandaan de locatieregels gaan aanmaken/aanvullen
  declare local temporary table tmpLocaties(
    tmpGid integer default autoincrement,
    tmpOrlGid integer, // Alleen als de locatie specifiek voor een specregel is gevonden
    tmpLocGid integer,
    tmpPartijGid integer,
    tmpAantal numeric(15,3),
    tmpSetBlok smallint default 0
  ) on commit preserve rows;

  // Maatwerk-haakje voor overrulen van deze routine
  if exists(select first 1 from sys.sysprocedure where proc_name = 'MAATWERK_OrderRegelSpecificaties_VulLocatiesAan') then
    begin
      declare @IsStandaardRoutineOverruled smallint = 0;
      call MAATWERK_OrderRegelSpecificaties_VulLocatiesAan(
        @OrkGid = @OrkGid,
        @OrrGid = @OrrGid,
        @MatViewNummerVoorraadAantallen = @MatViewNummerVoorraadAantallen,
        @VulLocaties = @VulLocaties,
        @GewijzigdeOrderstatus = @GewijzigdeOrderstatus,
        @OrkIsVrijgegevenVoorLeveren = @OrkIsVrijgegevenVoorLeveren,
        @HeeftSpecregelsZonderLocatie = @HeeftSpecregelsZonderLocatie,
        @IsStandaardRoutineOverruled = @IsStandaardRoutineOverruled
      );
      if @IsStandaardRoutineOverruled = 1 then
        leave; // Gelijk stoppen met deze procedure!
      end if;
    end;
  end if;


  set @MatViewNummerVoorraadAantallen = ''; // ACW Om geen materialized views te gebruiken!

  if @GewijzigdeOrderstatus is null then
    set @GewijzigdeOrderstatus = 'A';
  end if;
/*
  Volledige routine (na elke regel wordt het restant berekend en doorgegaan naar de volgende regel tot restant=0)
  - Negatief aantal OF altijd voorkeurslocatie -> gebruik alles in de voorkeurslocatie
  - Is er al een spec.regel voor bulk/grijp en daarin is voldoende beschikbaar, dan die aanvullen
  - Ga alle locaties af (via routine Beschikbaar per locatie)
*/

  //call trace('OrderRegelSpecificaties_VulLocatiesAan(@OrkGid=' || @OrkGid || ', @OrrGid=' || @OrrGid || ', @MatViewNummerVoorraadAantallen=' || @MatViewNummerVoorraadAantallen || ', @VulLocaties=' ||@VulLocaties);

  set @HeeftSpecregelsZonderLocatie = 0;

  // Gegevens opvragen vanuit de orderkop
  if @OrkIsVrijgegevenVoorLeveren is null then
    // Niet overruled, dus status uit de orderkop lezen
    select OrkVrijVoorLevering, OrkIsVerzamellijstGebruiken into @OrkIsVrijgegevenVoorLeveren, @OrkIsVerzamellijstGebruiken from taborderkop where OrkGid = @OrkGid;
  else
    // Wel overruled, dus alleen de overige gegevens uit de kop lezen
    select OrkIsVerzamellijstGebruiken into @OrkIsVerzamellijstGebruiken from taborderkop where OrkGid = @OrkGid;
  end if;

  // Vaste gegevens ophalen
  select first VofRegelDefLocatie, VofRegelBulkAllesBeschikbaar, VofRegelBulkDeelsBeschikbaar
  into @VofRegelDefLocatie, @Gebruik1BulkLocatie, @GebruikBulkLocaties
  from tabVasteGegevensOrdersFactureren;

  case @VulLocaties
    when 0 /*obv orderstatus*/ then
      case OrderRegelSpecificaties_ToewijzenNodigObvStatus(@OrkGid, @GewijzigdeOrderstatus)
        when 0 /*niet nodig*/ then set @DoVulLocaties = 0
        when 1 /*Wel nodig*/  then set @DoVulLocaties = 1
      end;
    when 1 /*Altijd invullen*/ then
      set @DoVulLocaties = 1; // Altijd invullen obv voorraad
    else
      set @DoVulLocaties = 0; // Niet invullen
  end;

  // LET OP!!! HIER STOPPEN WE ALS ER NIETS TE DOEN IS
  // Defect 59709: Spec.regels niet vullen? Dan ook niet opschonen etc.
  if @DoVulLocaties = 0 then
    leave;
  end if;


  // Geen materialized view als we toch geen voorraad gaan opvragen
  if @VofRegelDefLocatie = 0 /*picklocaties*/ and @DoVulLocaties = 1 then
    if @MatViewNummerVoorraadAantallen is null then
      call PooledMatViewUse(0 /*vwVoorraadAantallen*/, 1 /*Create+refresh*/, @MatViewNummer);
    else if @MatViewNummerVoorraadAantallen <> '' then
        // Vanuit de trigger van orderkop kan dit ook worden aangeroepen, maar dan met een lege en dat moet zo blijven,
        // kan potentieel fout gaan als op meerdere regels hetzelfde artikel wordt gebruikt
        call PooledMatViewRefresh(0 /*vwVoorraadAantallen*/, @MatViewNummer);
      end if;
    end if;
  end if;

  // Per orderregel verwerken
  // *** LUS: elke orderregel van opgegeven order (en regel) ***
  for @RegelCursor AS CURSOR_OrderRegel CURSOR FOR
    select
      OrrGid @_OrrGid,
      OrrArtGid @_ArtGid,
      OrrArtPartijGid @_ArtPartijGid,
      OrrMagGid @_MagGid,
      OrrAantalBesteld @OrrAantalBesteld,
      (select VkeGid from tabVerkoopEenheid where VkeArtGid = OrrArtGid and VkeIsVoorraadEenheid = 1) @VoorraadEenheidVkeGid,
      // Als wel mag worden afgeweken, dan MOET de verkoopeenheid worden gebruikt
      // Als niet mag worden afgeweken, maar de omrekening is mogelijk dan verkoopeenheid, anders voorraadeenheid
      if OrrAantalVrrdEenhInVerkEenhMagAfwijken in (1 /*afw. bij aantal besteld*/, 2 /*Mag afwijken bij DezeLevering*/) then 1 else 0 endif @AlleenInVeelvoudVanEenheid,
      OrrAantalVrrdEenhInVerkEenhMagAfwijken @OrrAantalVrrdEenhInVerkEenhMagAfwijken,
      OrrAantDecAantalVrrdEenh @OrrAantDecAantalVrrdEenh,
      if @ForceerVoorraadEenheid = 0 then OrrVkeGid                   else @VoorraadEenheidVkeGid endif @_OrrVkeGid,
      if @ForceerVoorraadEenheid = 0 then OrrAantalVrrdEenhInVerkEenh else 1                      endif @_OrrAantalVrrdEenhInVerkEenh,
      ArtIsPartijVerkoopCheckOuderePartijOp @_PartijOudsteEerst,
      ArtPartijVerkoopCheckOuderePartij @_PartijVolgorde,
      // Restant waar nog geen locatie voor is; Aantal gereserveerd voor deze levering minus wat al in de specificatieregels een locatie heeft
      // De handmatige regels gooien we NIET weg, dus die houden we buiten de te zoeken artikelen
      // ACW De reserveringen in backorder laten we achterwege, die kunnen we nu toch niet in de spec.regels kwijt
      OrrAantalLevering @OrrAantalLevering,
      OrrAantalLeveringVrrdEenh @_OrrAantalLeveringVrrdEenh,
      OrrAantDecAantal @_OrrAantDecAantal,
      ArtAantDecAantallen @ArtAantDecAantallen,
      ArtSerieNrRegistreren * ArtIsSerieNrBijVrijgaveVerplicht @SerienummerVerplicht,
      ArtSerieNrRegistreren * ArtSerieNrBijVerkoopAanmaken @SerienummerAanmaken,
      // Hier bepalen we of de regel moet worden nagekeken/opnieuw worden toegewezen
      if  (OrrAantalLeveringVrrdEenh <> OrrAantalTotaalLevVanDetail) // Spec.regels hebben niet zelfde hoeveelheid, dus moeten we toewijzen
        //or @VofRegelDefLocatie = 1 /*Standaard locatie*/ or
        or exists(select first 1
                 from   tabOrderRegelLocatie
                 where  OrlOrrGid = @_OrrGid
                    and (
                         OrlLocGid is null // Geen locatie ingevuld? Dan moeten we misschien wat toewijzen
                        )
                ) then 1 else 0 endif @_ErIsNogIetsTeVerwerken,
      if exists(select first 1 from taborderregellocatie where OrlOrrGid = OrrGid and OrlLocGid is not null and OrlDezeLeveringVrrdEenh <> 0) then 1 else 0 endif @_ErZijnAndereSpecRegels,
      sign(OrrAantalLeveringVrrdEenh) @TekenVanOrrDezeLevering

    from tabOrderRegel
    inner join tabArtikel on ArtGid = OrrArtGid
    where OrrOrkGid = @OrkGid and (@OrrGid is null or OrrGid = @OrrGid)
    and OrrRegelSoort = 2 /*Artikel*/
    //and ArtHeeftVoorraad = 1 /*Alleen als van het artikel voorraad wordt bijgehouden*/
    //and (@_AantalBenodigdVoorrEenh > 0 or @VofRegelDefLocatie = 1 /*Standaard locatie*/)
    and @_ErIsNogIetsTeVerwerken <> 0
    order by OrrRegelnr
  for read only do
  begin
    declare @AantalBenodigd             numeric(15,3);
    //declare @ErZijnSPecregelsVerwijderd smallint; // 0 = geen spec.regels verwijderd, 1 = spec.regels verwijderd
    declare @_AantalBenodigdVoorrEenh   numeric(15,3);
    declare @ZoekPerAantalVoorrEenheden numeric(15,3);
    declare @VrrdEenhPerInkEenh         numeric(15,3);
    declare @VkeGid                     integer;
    declare @VkeAantDecAantallen        integer;

    // Als ook partijen, in welke volgorde worden die dan doorlopen?
    // 0 = geen volgorde, 1 = oudste productiedatum eerst, 2 = oudste ontvangstdatum eerst, 3 = oudste THT-datum eerst, 4 = naam
    declare @PartijVolgorde smallint = if @_PartijOudsteEerst = 0 then 0 else @_PartijVolgorde + 1 endif;

    //call trace('OrrGid = ' ||@_OrrGid||'; ArtGid = '|| @_ArtGid || '; @_MagGid = ' || @_MagGid ||'; Aantal = ' || @AantalBenodigd);

    // *** STAP: OPSCHONEN: Alle specificatieregels die we helemaal opnieuw gaan maken eerst verwijderen ***
    call OrderRegelSpecificaties_Opschonen(@OrkGid, @_OrrGid);

    // *** STAP: CALC: Bepaal het aantal dat we moeten opzoeken in magazijnlocaties en toevoegen aan de spec.regels
    select @_OrrAantalLeveringVrrdEenh - isnull(sum(OrlDezeLeveringVrrdEenh), 0)
    into   @_AantalBenodigdVoorrEenh
    from   tabOrderRegelLocatie
    where  OrlOrrGid = @_OrrGid;

    // Bepaal de eenheid voor de spec.regels:
    // - Voorraadeenheid als:
    //    - aantal dat we nog nodig hebben 'past' NIET in de verkoopeenheid (obv aantal voorreenh.per verk.eenh van de regel)
    //      EN
    //    - AantalKanVerschillen=0 (vast aantal) -> op spec.regel mag voorraadeenheid worden gebruikt, zelfs als de orderregel afwijkt
    // - Eenheid van de regel als:
    //   - aantal dat we nog nodig hebben 'past' in de verkoopeenheid (obv aantal voorreenh.per verk.eenh van de regel)
    //     OF
    //   - aantal past niet, MAAR AantalKanVerschillen=2 (afw. bij lev/fact.)
    // Als de eenheid voor de spec.regels de voorraadeenheid is en er mag worden afgeweken, dan kunnen we pakken per 0,....
    begin
      declare @AantalPastInVerkEenh smallint = if round(@_AantalBenodigdVoorrEenh / @_OrrAantalVrrdEenhInVerkEenh, @_OrrAantDecAantal) = (@_AantalBenodigdVoorrEenh / @_OrrAantalVrrdEenhInVerkEenh) then 1 else 0 endif;

      //ACW HIERO: Altijd verkoopeenheid van de regel, tenzij we voorraadeenheid forceren
      //Op die manier proberen we eerst zoveel mogelijk verkoopeenheiden te pakken en pas daarna om te schakelen
      set @VkeGid = if @ForceerVoorraadEenheid = 1 then //@AantalPastInVerkEenh = 0 and @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0 /*Vast aantal*/ then
                      @VoorraadEenheidVkeGid
                    else
                      @_OrrVkeGid
                    endif;

      // Aantal decimalen kan ook 4(volgens voorr.eenh. zijn)!
      set @VkeAantDecAantallen =
        isnull((select first VkeAantalDecimalen
                from tabVerkoopEenheid
                where (VkeGid = @VkeGid and VkeAantalDecimalen <> 4)
                   or (VkeGid = @VoorraadEenheidVkeGid)
                order by if VkeGid = @VkeGid then 0 else 1 endif // Eerst de verkoopeenheid, maar als die 4 heeft, dan automatisch voorraadeenheid
               ), 1);

      // Per batch, afhankelijk van eenheid:
      // - bij voorr.eenh. OF afwijken bij lev/fact. dan minimum aantal obv aantal decimalen
      // - bij verk.eenh. het aantal voorr.eenh. van de regel
      set @VrrdEenhPerInkEenh =
        if @VkeGid = @VoorraadEenheidVkeGid or @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2 /*Afw. bij lev/fact*/ or @VkeGid = @_OrrVkeGid then
          @_OrrAantalVrrdEenhInVerkEenh
        else
          1
        endif;

      set @ZoekPerAantalVoorrEenheden =
        if @VkeGid = @VoorraadEenheidVkeGid or @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2 /*Afw. bij lev/fact*/ then
          cast(power(0.1, @OrrAantDecAantalVrrdEenh) as numeric(15,3))
        else
          if @VkeGid = @_OrrVkeGid then @_OrrAantalVrrdEenhInVerkEenh else 1 endif
        endif;
    end;


//    // Bepaal juiste eenheid en het aantal voorraadeenheden van die eenheid
//    set @VkeGid =
//      if @AlleenInVeelvoudVanEenheid = 1
//         or round(@_AantalBenodigdVoorrEenh / @_OrrAantalVrrdEenhInVerkEenh, @_OrrAantDecAantal) = (@_AantalBenodigdVoorrEenh / @_OrrAantalVrrdEenhInVerkEenh) then
//        @_OrrVkeGid
//      else
//        @VoorraadEenheidVkeGid
//      endif;
//    set @ZoekPerAantalVoorrEenheden =
//      if @VkeGid = @_OrrVkeGid then
//        if @AlleenInVeelvoudVanEenheid = 0 then
//          @_OrrAantalVrrdEenhInVerkEenh
//        else
//          lesser(@_OrrAantalVrrdEenhInVerkEenh, @_AantalBenodigdVoorrEenh)
//        endif
//      else
//        1
//      endif;
//    // Aantal decimalen kan ook 4(volgens voorr.eenh. zijn)!
//    set @VkeAantDecAantallen =
//      isnull((select first VkeAantalDecimalen
//              from tabVerkoopEenheid
//              where (VkeGid = @VkeGid and VkeAantalDecimalen <> 4)
//                 or (VkeGid = @VoorraadEenheidVkeGid)
//              order by if VkeGid = @VkeGid then 0 else 1 endif // Eerst de verkoopeenheid, maar als die 4 heeft, dan automatisch voorraadeenheid
//             ), 1);


    // *** STAP: MATVIEW: Materialized view refreshen
    // Materialized view verversen als we al een regel gevonden hebben
    // Alleen nodig als het artikel al een keer voorkwam in de lijst
    // maar NIET als we niet met materialized view werken (dus als @MatViewNummerVoorraadAantallen='')
    if (@MatViewNummerVoorraadAantallen <> '') and ((select count(*) from tmpLocaties) > 0) and @ListOfArtGid like '%,' || @_ArtGid || ',%' then
      call PooledMatViewRefresh(0 /*vwVoorraadAantallen*/, @MatViewNummer);
    end if;
    set @ListOfArtGid = @ListOfArtGid || ',' || @_ArtGid;

    // *** STAP: INIT: Initialiseren van zoekresultaat ***
    delete tmpLocaties;


    // *** VERVALLEN STAP: SERIENR: Van niet-geblokkeerde serienummers met locatie de locatie leeg maken, zodat die opnieuw kunnen worden gezocht
    //update tabOrderRegelLocatie
    //set    OrlLocGid = null
    //where  OrlOrrGid = @_OrrGid
    //   and OrlArtSerieGid is not null
    //   //and OrlHandmatig = 0
    //   and OrlLocGid is not null
    //   and OrlDezeLeveringVrrdEenh = 1;

    // *** STAP: SERIENR: Serienummers met aantal van 1 zonder locatie proberen te verwerken
    for @SerienumCursor AS CURSOR_Serienummers CURSOR FOR
      select OrlGid @OrlGid, OrlArtPartijGid @OrlArtPartijGid
      from tabOrderRegelLocatie
      where OrlOrrGid = @_OrrGid
      and OrlArtSerieGid is not null
      and (/*ACWdefect72989removed OrlHandmatig = 0 or */OrlLocGid is null)
      and OrlDezeLeveringVrrdEenh = 1
    for read only do

      //if @MatViewNummer <> '' then
      //  call PooledMatViewRefresh(0 /*vwVoorraadAantallen*/, @MatViewNummer);
      //end if;

      begin
        declare @tmpLocGid integer;
        declare @tmpPartijGid integer;

        select first tmpLocGid, tmpPartijGid
        into @tmpLocGid, @tmpPartijGid
        from OrderRegelSpecificaties_BeschikbaarPerLocatie(
          @MagGid                         = @_MagGid,
          @AantalBenodigdVoorrEenh        = 1, // Want serienummers hebben slechts 1 (of -1, maar die worden anders behandeld)
          @ArtGid                         = @_ArtGid,
          @ArtPartijGid                   = @OrlArtPartijGid,
          @MatViewNummerVoorraadAantallen = @MatViewNummerVoorraadAantallen,
          @OrrAantalBesteld               = @OrrAantalLevering, // LET OP!! Foute naam, maar het gaat erop dat we weten dat het een retourlevering is (aantal negatief)
          @OverruleAllesVan1BulkLocatie   = if @_ErZijnAndereSpecRegels = 1 then -1 else 0 endif,
          @OrrGid                         = @_OrrGid
        )
        //where tmpPartijGid is not null /*anders is die eigenlijk niet gevonden, serienummer moet van zelfde partij zijn*/
        order by tmpGid;

        if @tmpLocGid is not null then
          update tabOrderRegelLocatie
          set    OrlLocGid = @tmpLocGid
          where OrlGid = @OrlGid;
        end if;

      end;
    end for;


    // *** STAP: UPDATEEXISTING: Partij-specregels met vinkje opnieuw toewijzen ***
    // Bestaande (niet-verwijderde) specificatieregels opnieuw toewijzen voor zover mogelijk
    // Resultaat in tijdelijke tabel
    call OrderRegelSpecificaties_ZoekLocatieVoorBestaandeSpecregels(
      @_OrrGid = @_OrrGid,
      @_MagGid = @_MagGid,
      @_ArtGid = @_ArtGid,
      @ZoekPerAantalVoorrEenheden = @ZoekPerAantalVoorrEenheden,
      @AlleenInVeelvoudVanEenheid = @AlleenInVeelvoudVanEenheid,
      @OrrAantalLevering = @OrrAantalLevering,
      @tmpLocaties = table ref(tmpLocaties),
      @MatViewNummerVoorraadAantallen = @MatViewNummerVoorraadAantallen,
      @AfrondenPer                    = if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2 /*afw bij lev/fact*/ then @_OrrAantalVrrdEenhInVerkEenh endif,
      @AfkappenPer                    = if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*afw bij besteld*/  then @_OrrAantalVrrdEenhInVerkEenh endif
    );
    // De hier gevonden aantallen vallen BUITEN de reguliere aantallen van niet-bestaande spec.regels, dus die
    // hier even bij het reguliere aantal optellen ivm latere berekeningen
    //ACW BestaandeSpecregelsOpnieuwToewijzen verwijdert nu niet meer, dus aantal ook niet aanpassen!
    //select @_AantalBenodigdVoorrEenh + isnull(sum(tmpAantal), 0) into @_AantalBenodigdVoorrEenh from tmpLocaties;
    set @AantalBenodigd = @_AantalBenodigdVoorrEenh;


    // *** VERVALLEN STAP: Liefst aantallen van 1 bestaande spec.regel updaten ***
    //           ipv in andere locaties te zoeken
    // Als er 1 bulk/grijp-specificatieregel is, dan liefst diezelfde aanvullen als op die locatie meer ligt EN het is een grijp- of bulklocatie
    //ACW We gaan bestaande specregels met locatie niet meer aanpassen, dus dit ook niet!
    //if @AantalBenodigd <> 0 then
    //  insert into tmpLocaties(tmpLocGid, tmpPartijGid, tmpAantal)
    //  select Locgid, ArtPartijGid, AantalVoorraadEenheden
    //  from OrderRegelSpecificaties_GetAanvulAantalVoorEnkeleSpecRegelIndienBeschikbaar(
    //    @_OrrGid,
    //    @_MagGid,
    //    @_ArtGid,
    //    @_ArtPartijGid,
    //    @PartijVolgorde,
    //    @AantalBenodigd,
    //    @ZoekPerAantalVoorrEenheden,
    //    @AlleenInVeelvoudVanEenheid,
    //    @OrrAantalBesteld,
    //    @MatViewNummerVoorraadAantallen);
    //  // Restant
    //  select @_AantalBenodigdVoorrEenh - isnull(sum(tmpAantal), 0) into @AantalBenodigd from tmpLocaties;
    //end if;



    // *** STAP: Opzoeken van beschkbare voorraad voor benodigde aantal
    // Als we de locaties nog niet invullen (is niet nodig of zo), dan zonder locatie toevoegen,
    // dat is dus niet anders dan het aantal op 0 zetten, zodat het restant als egbruikelijk op locatieloos wordt gezet
    if @DoVulLocaties = 0 or @AantalBenodigd = 0 then
      // Locaties niet vullen, dus alles op lege locatie (Lossen we op met restant)
      set @AantalBenodigd = 0
    else
      // Zoek obv beschikbaarheid
      insert into tmpLocaties(tmpLocGid, tmpPartijGid, tmpAantal)
      select tmpLocGid, tmpPartijGid,
             if @AlleenInVeelvoudVanEenheid = 0 or tmpLocGid is null then tmpAantal else floor(tmpAantal/@ZoekPerAantalVoorrEenheden)*@ZoekPerAantalVoorrEenheden endif AantalGevonden
      from OrderRegelSpecificaties_BeschikbaarPerLocatie(
        @MagGid                         = @_MagGid,
        @AantalBenodigdVoorrEenh        = @AantalBenodigd,
        @ArtGid                         = @_ArtGid,
        @ArtPartijGid                   = @_ArtPartijGid,
        @ZoekPerAantalVoorraadeenheden  = @ZoekPerAantalVoorrEenheden,
        @MatViewNummerVoorraadAantallen = @MatViewNummerVoorraadAantallen,
        @OrrAantalBesteld               = @OrrAantalLevering, // LET OP!! Foute naam, maar het gaat erop dat we weten dat het een retourlevering is (aantal negatief)
        @OverruleAllesVan1BulkLocatie   = if @_ErZijnAndereSpecRegels = 1 then -1 else 0 endif,
        //Vast aantal -> niet afronden; Aantal bij besteld -> afkappen; Aantal bij lev/fact -> afronden
        @AfrondenPer                    = if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2 /*afw bij lev/fact*/ then @_OrrAantalVrrdEenhInVerkEenh endif,
        @AfkappenPer                    = if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*afw bij besteld*/  then @_OrrAantalVrrdEenhInVerkEenh endif,
        @OrrGid                         = @_OrrGid
      )
      where AantalGevonden <> 0
    end if;



    // *****************************************************************
    // *** UPDATE SPEC: juiste aantallen en locaties in spec.regels zetten
    // *****************************************************************
    // Eerst bestaande specificatieregels aanvullen
    // TODO: Meerdere spec.regels op dezelfde locatie gaat nu fout!
    // TODO: Rekening houden met deadlocks (aantal keren opnieuw proberen)
    //call trace('Stap 1 van updaten');

    if @DoVulLocaties <> 0 then
      begin
        declare @KeepPosting smallint = 1;
        declare @AantalAanRegelToevoegen smallint; // als is gezocht op specifieke OrlGid, dan wordt die regel vervangen qua aantallen.
                                                   // als niet op specifieke OrlGid is gezocht, dan moet het aantal bij een gevonden regel worden opgeteld
        declare @VorigeOrlGid integer;

        // Bestaande specregels die specifiek zijn opgezocht aanvullen, maar dan alleen als we daar iets voor hebben gevonden
        // dus obv tmpOrlGid die is gezet door OrderRegelSpecificaties_BestaandeSpecregelsOpnieuwToewijzen
        for @CursorTmpLocaties AS CURSOR_tmpLocaties CURSOR FOR

        // Eerste deel: Met bekende tmpOrlGid.
        //              voor bestaande ORL wordt het aantal aangepast, er is namelijk specifiek voor die ORL gezocht
        //              Dat werkt daardoor ook voor al eerder ingevoerde partijen
        select tmpGid @tmpGid, tmpLocGid @tmpLocGid, tmpPartijGid @tmpPartijGid, tmpAantal @tmpAantal, OrlGid @OrlGid,
          if locnaam = '' then 1 else 0 endif /*zonder locatie als laatste*/, locNaam
        from tmpLocaties
             inner join tabLocatie on LocGid = tmpLocGid
             inner join tabOrderRegelLocatie on OrlGid = tmpOrlGid and isnull(OrlArtPartijGid, -1) = isnull(tmpPartijGid, -1)
             inner join tabVerkoopEenheid on VkeGid = OrlVkeGid
        where OrlOrrGid = @_OrrGid
          //and (OrlHandmatig = 0 /*or OrlArtSerieGid is not null or tmpSetBlok = 1*/)
          and OrlArtSerieGid is null // Serienummer-regels hebben we al gedaan
          and VkeArtGid = @_ArtGid
          // Verkoopeenheid moet wel zelfde aantal voor 1 batch hebben of het is gewoon de voorkeursverkoopeenheid als het aantal op 1 staat of (DevOpsDefect #29834) aantal voorr.eenh. per verk.eenh. mag afwijken bij fact/lev.
          and (   (VkeAantalVoorraadEenhedenInVerkoopEenheid = @ZoekPerAantalVoorrEenheden)
               or (VkeIsVoorraadEenheid = 1)
               or (@OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2 /*Mag afwijken bij DezeLevering*/)
              )
          and tmpAantal <> 0
        UNION ALL
        // Tweede deel: zonder bekende tmpOrlGid.
        //              Kunnen we een ORL vinden voor de gevonden aantallen om te verhogen?
        //              dat doen we als: locatie gelijk, partij gelijk, eenheid gelijk
        select tmpGid @tmpGid, tmpLocGid @tmpLocGid, tmpPartijGid @tmpPartijGid, tmpAantal @tmpAantal, null @OrlGid,
          if locnaam = '' then 1 else 0 endif /*zonder locatie als laatste*/, locNaam
        from tmpLocaties
             inner join tabLocatie on LocGid = tmpLocGid
        where tmpOrlGid is null
          and tmpAantal <> 0
          //and (OrlHandmatig = 0 /*or OrlArtSerieGid is not null or tmpSetBlok = 1*/)

        order by
          5, 6, 7
        for read only
        do
          //call trace('Stap 1a van updaten');
          // Als @OrlGid leeg, dan zoeken of we een specregel vinden voor de betreffende locatie/partij/eenheid

          if @OrlGid is null then
            select first OrlGid
            into @OrlGid
            from tabOrderregelLocatie
             inner join tabVerkoopEenheid on VkeGid = OrlVkeGid
            where OrlOrrGid = @_OrrGid                                   // specregel van zelfde orderregel
              and isnull(OrlArtPartijGid, -1) = isnull(@tmpPartijGid, -1) // zelfde partij
              and OrlArtSerieGid is null                                 // zonder serienummer
              // zelfde verkoopeenheid (of i.i.g. zelfde voorraadeenheden per verkoopeenheid)
              // Mogen we afwijken, dan is het prima, kunenn we die alsnog gebruiken
              and (   (@OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0 /*vast aantal, mag bij spec.afwijken*/)
                   or (VkeIsVoorraadEenheid = 1) // Regel is voorraadeenheid, zoeken per 1, dus dat past
                   or (@ZoekPerAantalVoorrEenheden = (if "OrlVkeGid" = @_OrrVkeGid then @_OrrAantalVrrdEenhInVerkEenh else "VkeAantalVoorraadEenhedenInVerkoopEenheid" endif)) // Zoeken per aantal van verkoopeenheid, dus prima
                  )
              and (VkeIsVoorraadEenheid = 1    // Is de spec.regel geen voorraadartikel, dan alleen toevoegen als het totaal past in de verkoopeenheid
                  or round((OrlDezeLeveringVrrdEenh + @tmpAantal) / if OrlVkeGid = @_OrrVkeGid then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif, @_OrrAantDecAantal)
                      =
                      ((OrlDezeLeveringVrrdEenh + @tmpAantal) / if OrlVkeGid = @_OrrVkeGid then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif)
                  )
              and (OrlLocGid is null or OrlLocGid = @tmpLocGid)
              // Teken mag na wijziging niet anders zijn dan het huidige teken!
              and (   sign(OrlDezeLeveringVrrdEenh) = sign(OrlDezeLeveringVrrdEenh + @tmpAantal)
                   or (OrlDezeLeveringVrrdEenh + @tmpAantal = 0)
                  )
            order by abs(OrlDezeLeveringVrrdEenh), OrlGid;
            set @AantalAanRegelToevoegen = 1;
          else
            set @AantalAanRegelToevoegen = 0;
          end if;

          if @OrlGid is not null then
            set @KeepPosting = 1;
            loop
              begin
                // TODO: Als @AantalAanRegelToevoegen=0 EN de vorige orlgid is gelijk, dan moeten we nieuwe spec.regel aanmaken met partij+serienummer volgens gevonden spec.regel MAAR met nieuwe aantal+loc en de @orlgid onthouden om na deze lus te verwijderen
                // bestaande regel met zelfde locatie updaten en aantallen erbij zetten
                if @VorigeOrlGid is null or @VorigeOrlGid <> @OrlGid then
                begin
                  declare @NieuweOrlDezeLeveringVrrdEenh numeric(15,3);
                  select @AantalAanRegelToevoegen * OrlDezeLeveringVrrdEenh + @tmpAantal
                  into @NieuweOrlDezeLeveringVrrdEenh
                  from tabOrderregelLocatie
                       inner join tabVerkoopEenheid on VkeGid = OrlVkeGid
                  where OrlGid = @OrlGid;
                  if @NieuweOrlDezeLeveringVrrdEenh = 0.0 then
                    // regel is gevonden, maar nieuwe aantal zou 0.00 zijn, dan maar de regel verwijderen ipv aanpassen
                    delete tabOrderregelLocatie where OrlGid = @OrlGid;
                  else
                    // De reeds bestaande orl aanvullen
                    update tabOrderregelLocatie
                    set    OrlLocGid = @tmpLocGid,
                           OrlDezeLeveringVrrdEenh = @NieuweOrlDezeLeveringVrrdEenh,
                           OrlDezeLevering = @AantalAanRegelToevoegen * OrlDezeLevering +
                             if @AlleenInVeelvoudVanEenheid = 0 then
                                @tmpAantal / if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*Afw bij Besteld*/ then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif
                             else
                                // We mogen niet afwijken, DUS altijd meer verkoopeenheden, dan is die laatste evt. maar een halve kaas/rol/...
                                ceiling((@tmpAantal) / if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*Afw bij Besteld*/ then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif * power(10,@VkeAantDecAantallen)) / power(10,@VkeAantDecAantallen)
                            end if
                    from tabVerkoopEenheid
                    where OrlGid = @OrlGid and VkeGid = OrlVkeGid;
                  end if;
                end
                else
                  // De reeds aanwezige orl is al aangevuld, dus nu een nieuwe maken obv die regel en gevonden aantal, mits teken gelijk aan DezeLevering!!
                  insert into tabOrderregelLocatie
                  (OrlOrrGid,OrlArtPartijGid,OrlVkeGid,OrlAantDecAantal,OrlAantDecAantalVrrdEenh,
                   OrlMagGid,OrlLocGid,OrlDezeLeveringVrrdEenh,OrlDezeLevering)
                  select OrlOrrGid,
                         OrlArtPartijGid,
                         OrlVkeGid,
                         OrlAantDecAantal,
                         OrlAantDecAantalVrrdEenh,
                         OrlMagGid,
                         @tmpLocGid OrlLocGid,
                         @tmpAantal OrlDezeLeveringVrrdEenh,
                         if @AlleenInVeelvoudVanEenheid = 0 then
                            @tmpAantal / if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*Afw bij Besteld*/ then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif
                         else
                            // We mogen niet afwijken, DUS altijd meer verkoopeenheden, dan is die laatste evt. maar een halve kaas/rol/...
                            ceiling((@tmpAantal) / if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*Afw bij Besteld*/ then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif * power(10,@VkeAantDecAantallen)) / power(10,@VkeAantDecAantallen)
                        end if NieuweOrlDezeLevering
                  from tabOrderregelLocatie
                       inner join tabVerkoopEenheid on VkeGid = OrlVkeGid
                  where OrlGid = @OrlGid
                  and sign(NieuweOrlDezeLevering) = @TekenVanOrrDezeLevering; // Alleen toevoegen als teken gelijk is!
                end if;
                set @KeepPosting = 0;
              exception
              when others then
                if not exists(select 1 where ERROR_SQLSTATE() = '') then
                  resignal; // De rest wel doorzetten
                end if;
              end;
              if @KeepPosting = 0 then
                leave
              end if;
            end loop;

            // De tmpLocaties-regel is verwerkt, dus leeg maken
            update tmpLocaties set tmpAantal = 0 where tmpGid = @tmpGid; // Aantal is verwerkt, dus record verwijderen
          end if;
          set @VorigeOrlGid = @OrlGid;
        end for;
      end;

      begin
        declare @Doorzoeken smallint;
        // Hier kan, als serienummers verplicht EN moet worden aangemaakt bij orderinvoer, alvast meer regels worden gemaakt, per serienummer 1
        // Daana de rest toevoegen
        //call trace('Stap 4 van updaten');
        // LET OP! Omdat we @VkeGid ofwel verkoopeenheid ofwel voorraadeenheid is,
        //         moeten we het gevonden aantal tmpAantal nog delen door het aantal voorraadeenheden per verkoopeenheid
        // Alleen toevoegen als het teken gelijk is aan het teken van DezeLevering!
        insert into tabOrderRegelLocatie(
               OrlOrrgid, OrlArtPartijGid, OrlMagGid, OrlLocGid, OrlDezeLeveringVrrdEenh, OrlDezeLevering, OrlVkeGid, OrlAantDecAantalVrrdEenh, OrlAantDecAantal /*ACWdefect72989removed , OrlHandmatig*/)
        select @_OrrGid,  tmpPartijGid,    @_MagGid,  tmpLocGid, tmpAantal,
               if @AlleenInVeelvoudVanEenheid = 0 then
                 tmpAantal / if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*Afw bij Besteld*/ then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif
               else
                 ceiling(tmpAantal / if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*Afw bij Besteld*/ then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif * power(10,@VkeAantDecAantallen)) / power(10,@VkeAantDecAantallen)
               endif, @VkeGid, @ArtAantDecAantallen, @VkeAantDecAantallen
               /*ACWdefect72989removed ,tmpSetBlok*/
        from tmpLocaties
             inner join  tabVerkoopEenheid on VkeGid = @VkeGid
             left outer join tabLocatie on LocGid = tmpLocGid /*tmpLocGid kan leeg zijn ivm vullen zonder locatie*/
             left outer join tabArtikelPartij on ArtPartijGid = tmpPartijGid
        where tmpAantal <> 0 and sign(tmpAantal) = @TekenVanOrrDezeLevering
        order by tmpSetBlok desc, if tmpLocGid is null then 1 else 0 endif /*zonder locatie als laatste*/, locNaam, ArtPartijNummer;

        // Als laatste het restant zonder locatie toevoegen, zodat het gelijk is aan het aantal deze levering van de orderregel
        //ACW NIET meer de specregel toevoegen zonder locatie
        //ACW Toch maar weer wel... anders krijgen we misschien bij afdruk verzamellijst en orderpicken te weinig om te pakken
        set @Doorzoeken = isnull((select first contents from tabregistry where regkey = 'OrderSpec_ZoekVoorrEenh' and isnumeric(contents) = 1), 1);

        if @VkeGid <> @VoorraadEenheidVkeGid
          and @ForceerVoorraadEenheid = 0 //Dus als we al forceren, dan niet nogmaals aanroepen!
          and @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0 /*Vast aantal*/
          and exists(select first 1 from tabOrderRegel where OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail <> 0)
          and @Doorzoeken = 1
        then
          // We hebben nog wat over EN we kunnen ipv de verkoopeenheid ook de voorraadeenheid nog proberen
          call OrderRegelSpecificaties_VulLocatiesAan(
            @OrkGid = @OrkGid,
            @OrrGid = @_OrrGid,
            @MatViewNummerVoorraadAantallen = @MatViewNummerVoorraadAantallen,
            @VulLocaties = @VulLocaties,
            @GewijzigdeOrderstatus = @GewijzigdeOrderstatus,
            @OrkIsVrijgegevenVoorLeveren = @OrkIsVrijgegevenVoorLeveren,
            @ForceerVoorraadEenheid = 1, // Forceer nu wel de voorraadeenheid
            @HeeftSpecregelsZonderLocatie = @HeeftSpecregelsZonderLocatie
          );
        end if;
          // Alles wat we nu nog te doen hebben is het laatste stukje verschil plaatsen, als mogelijk. Dat is dus eventueel NA we de voorraadeenheid hebben geprobeerd.
          // Als het te verwerken aantal past in de verkoopeenheid, gebruik dan die verkoopeenheid, anders, indien mogelijk, voorraadeenheid
        begin
          // Het restant zou best op een bestaande regel aangevuld kunnen worden. Maar dan moet die regel wel precies gelijk zijn! Daarom eerst alles bijeen harken
          declare @OrlLocGid                integer;
          declare @OrlDezeLeveringVrrdEenh  numeric(15,3);
          declare @OrlDezeLevering          numeric(15,3);
          declare @OrlVkeGid                integer;
          declare @OrlAantDecAantalVrrdEenh numeric(15,3);
          declare @OrlAantDecAantal         numeric(15,3);
          declare @orlgid integer;
          select if @AantalTePlaatsen < 0 and @OrkIsVrijgegevenVoorLeveren = 1 then (select ArtMagDefaultLocGid from tabArtikelMagazijn where ArtMagMagGid = @_MagGid and ArtMagArtGid = @_ArtGid) endif,
                 if @ForceerVoorraadEenheid = 0 then
                   (OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail)
                 else
                    // We wilden verkoopeenheid, maar krijgen voorraadeenheid, dus zo MIN mogelijk voorraadeenheden, dan kan de rest in verkoopeenheid: restant modulo VoorrEenhPerVerkEenheid
                   mod((OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail) , (select OrrAantalVrrdEenhInVerkEenh from tabOrderregel where OrrGid = @OrrGid) /*Originele aantal VrrdEenhInVerkEenh*/)
                 endif AantalInVoorrEenheid,
                 if @AlleenInVeelvoudVanEenheid = 0 then
                   AantalInVoorrEenheid / if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*Afw bij Besteld*/ then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif
                 else
                   ceiling((AantalInVoorrEenheid / if @OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1 /*Afw bij Besteld*/ then @_OrrAantalVrrdEenhInVerkEenh else VkeAantalVoorraadEenhedenInVerkoopEenheid endif) * power(10,@VkeAantDecAantallen)) / power(10,@VkeAantDecAantallen)
                 endif @AantalTePlaatsen,
                 @VkeGid, @ArtAantDecAantallen, @VkeAantDecAantallen
          into   @OrlLocGid, @OrlDezeLeveringVrrdEenh, @OrlDezeLevering, @OrlVkeGid, @OrlAantDecAantalVrrdEenh, @OrlAantDecAantal
          from   tabOrderRegel
                 inner join  tabVerkoopEenheid on VkeGid = @VkeGid
          where  OrrGid = @_OrrGid
             //and OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail > 0
             and sign(orrAantalLeveringVrrdEenh) * (OrrAantalLeveringVrrdEenh-OrrAantalTotaalLevVanDetail) > 0     // Alleen opnemen als teken gelijk is (dus alleen een overschot opnemen), als DezeLev<0, dan moet e r juist een onderschot zijn!
             //and sign(OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail) = sign(orrAantalLeveringVrrdEenh) // Alleen opnemen als teken gelijk is (dus alleen een overschot opnemen)
                 // Afwijken bij lev/fact, dan alleen opnemen als aantal VERKOOPeenheden ongelijk
             and (@OrrAantalVrrdEenhInVerkEenhMagAfwijken <> 2 /*Afwijken bij lev/fact*/
                  or OrrAantalLevering <> isnull((select sum(OrlDezeLevering) from tabOrderregelLocatie where OrlOrrGid = @_OrrGid),0))
             and AantalInVoorrEenheid <> 0;

          // Moeten we toevoegen? Dan eerst een bestaande opzoeken en die, indien gevonden, aanvullen
          if @OrlDezeLeveringVrrdEenh <> 0 then

            // Zoek zelfde record op o.b.v. kenmerken
            set @orlgid = null;
            select first OrlGid into @orlgid
            from tabOrderRegelLocatie
            where OrlOrrGid = @_OrrGid
              and OrlArtPartijGid is not distinct from @_ArtPartijGid
              and OrlMagGid is not distinct from @_MagGid
              and OrlLocGid is not distinct from @OrlLocGid
              and OrlVkeGid is not distinct from @OrlVkeGid
            order by OrlGid desc;

            if @orlgid is null then
              // Bestaat niet -> nieuwe regel aanmaken
              // MAAAAAR, dan MOET het teken gelijk zijn aan het teken van dezeLevering, om te voorkomen dat we verkeerde tekenregels gaan toevoegen!
              if sign(@OrlDezeLeveringVrrdEenh) = @TekenVanOrrDezeLevering then
                insert into tabOrderRegelLocatie(
                       OrlOrrgid, OrlArtPartijGid, OrlMagGid, OrlLocGid,
                       OrlDezeLeveringVrrdEenh, OrlDezeLevering, OrlVkeGid, OrlAantDecAantalVrrdEenh, OrlAantDecAantal)
                values(@_OrrGid,  @_ArtPartijGid,  @_MagGid, @OrlLocGid,
                       @OrlDezeLeveringVrrdEenh, @OrlDezeLevering, @OrlVkeGid, @OrlAantDecAantalVrrdEenh, @OrlAantDecAantal);
              end if;
            else
              // Bestaat wel, regel aanvullen!
              update tabOrderregelLocatie
              set OrlDezeLeveringVrrdEenh = OrlDezeLeveringVrrdEenh + @OrlDezeLeveringVrrdEenh,
                  OrlDezeLevering = OrlDezeLevering + @OrlDezeLevering
              where OrlGid = @OrlGid and sign(OrlDezeLeveringVrrdEenh + @OrlDezeLeveringVrrdEenh) = @TekenVanOrrDezeLevering;
            end if;
          end if;
        end;
      end;

      // Spec.regels vullen met default locatie als:
      // - VG-instelling op voorkeurslocatie EN
      // - het is nodig obv orderstatus
      // //- order is vrij voor leveren EN
      // //- order gaat NIET via verzamellijst
      if @VofRegelDefLocatie = 1 /*Voorkeurslocatie*/ and @DoVulLocaties = 1 then
        if exists(select first 1 from tabOrderRegelLocatie where OrlOrrGid = @_OrrGid and OrlLocGid is null) then
          // Er zijn specregels zonder locatie, dus die alsnog vullen
          update tabOrderRegelLocatie
          set OrlLocGid = IsNull((select ArtMagDefaultLocGid from tabArtikelMagazijn where ArtMagMagGid = OrlMagGid and ArtMagArtGid = @_ArtGid),
                                 (select first LocGid from tabLocatie where LocNaam='(Standaard)' and (LocMagGid = OrlMagGid)))
          where OrlOrrGid = @_OrrGid and OrlLocGid is null;
        else
          // Er zijn geen specregels zonder locatie
          set @HeeftSpecregelsZonderLocatie = 0;
        end if;
      else
        // Vullen met picklocaties OF er hoeft niet te worden gevuld, dan nog steeds kijken of er specregels zonder locatie zijn
        if @HeeftSpecregelsZonderLocatie = 0 then
          // Er blijven regels leeg, dus dat teruggeven als waarschuwing
          set @HeeftSpecregelsZonderLocatie = if exists(select first 1 from tabOrderRegelLocatie where OrlOrrGid = @_OrrGid and OrlLocGid is null) then 1 else 0 endif;
        end if;
      end if;
    else
      // @DoVulLocaties = 0, niks gedaan, wel ff teruggeven of we spec.regels zonder locatie hebben
      set @HeeftSpecregelsZonderLocatie = if exists(select first 1
                                                    from tabOrderRegel
                                                         inner join tabOrderRegelLocatie on OrlOrrGid = OrrGid
                                                    where OrrOrkGid = @OrkGid
                                                      and (@OrrGid is null or OrrGid = @OrrGid)
                                                      and OrlLocGid is null
                                                   ) then 1 else 0 endif;
    end if; // @DoVulLocaties <> 0

    //call trace('Klaar met updaten');
  end; // Routine voor update van spec.regels

  //select LocNaam, tmpAantal, * from tmpLocaties inner join tabLocatie on LocGid = tmpLocGid;

  // *** EINDE LUS per orderregel
  end for;

  // *** STAP: Vrijgeven materialized view
  if @MatViewNummerVoorraadAantallen is null and @MatViewNummer is not null then
    // We hebben geen view meegegeven gekregen, dus zelf aangemaakt, kortom, ook zelf weer opruimen
    call PooledMatViewRelease(@MatViewNummer);
  end if;

end;




create or replace procedure OrderRegelSpecificaties_ZoekLocaties(
  in @MatViewNummer nchar(100),              // Wordt hier niet meer gebruikt, wordt nu de StoredProc voor gebruikt, maar wordt wel in deze variabele gezet
  in @MagGid integer,
  in @ArtGid integer,
  in @ArtPartijGid integer,                  // Kan null zijn, dan maakt de partij niet uit, doen we dat lekker zelf (obv THT ed.)
  in @PartijVolgorde smallint,               // 0 = niet op letten (ook niet teruggeven),
                                             // 1 = oudste productiedatum eerst,
                                             // 2 = oudste ontvangstdatum eerst,
                                             // 3 = oudste THT-datum eerst
                                             // 4 = Nummer
  in @aantalbenodigd numeric(15,3),
  in @PakPerAantal numeric(15,3),            // Pak per batch van dit aantal (als verkoopeenheid per dozijn is, dan staat hier 12)
  in @DoLocSoort smallint default 1,         // 0 = Voorkeurslocatie ongeacht type
                                             // 1 = Voorkeurslocatie van type GRIJP
                                             // 2 = Grijp-locatie(s) excl. voorkeurslocatie,
                                             // 3 = Bulk-locatie(s) excl. voorkeurslocatie,
                                             // 4 = Grijp-locatie(s) incl. voorkeurslocatie,
                                             // 5 = Bulk-locatie(s) incl. voorkeurslocatie,
                                             // 6 = Locatie zoals (in param @LocGid) is opgegeven
                                             // 7 = Voorkeurslocatie met type PICK
  in @StopAlsTeWeinig   smallint default 0,  // 0 = door met volgende locaties
                                             // 1 = stoppen zodra eerste locatie al tekort, locatie niet teruggeven (dus alleen teruggeven als volledige aantal nog beschikbaar)
                                             // 2 = stoppen zodra eerste locatie tekort, maar die locatie WEL teruggeven (dus locatie teruggeven ook als niet volledige aantal nog beschikbaar)
  in @LocatieVolgorde smallint default 1,    // 0 = volgorde vanaf meeste beschikbaar tot minst beschikbaar,
                                             // 1 = volgorde vanaf minst beschikbaar tot meest beschikbaar
  in @LocGid integer default null,
  in @OrrGid integer default null,           // Nodig om de specregels van deze orderregel evt. van de beschikbare voorraad af te halen als we NIET reserveren
  in @ExclLocList long nvarchar default null,// List van locgid die NIET moeten worden gecontroleerxd (zijn bijvoorbeeld al opgenomen)
  in @AfrondenPer numeric(15,3) default null,// Als we 50 zoeken en er 19 vinden, maar afronden per 10, dan resultaat=20 en we zoeken er dan nog 30
  in @AfkappenPer numeric(15,3) default null // Als we 50 zoeken en er 19 vinden, maar afkappen per 10, dan resultaat=10 en we zoeken er dan nog 40
)
/*
  Deze procedure loopt binnen een magazijn de locaties af, instelbaar met @DoLocSoort:
  1: Alleen de default locatie van dit artikel in dit magazijn
  2: Alleen grijp-locaties in de volgorde van aantal beschikbaar (minste eerst)
  3: Alleen bulk-locaties in de volgorde van aantal beschikbaar (minste eerst)
  Als een partij is meegegeven, dan wordt alleen voor die partij gezocht.
  Als een partij niet is meegegeven, maar het artikel is wel partij-registrerend, dan
    kunnen er meerdere records van 1 locatie terugkomen, namelijk per partij.
    Issue is dan wel dat als het om het volledige aantal binnen een locatie gaat, het dan ook het volledige aantal uit 1 partij moet zijn
*/
begin
  declare local temporary table tmpLocaties(
    tmpGid integer default autoincrement,
    tmpLocGid integer,
    tmpPartijGid integer,
    tmpAantal numeric(15,3)
  ) on commit preserve rows;

  declare @sql long nvarchar;     // Bevat commando dat wordt uitgevoerd
  declare @MatView long nvarchar; // Bevat de view (evt. samengevoegd met deze specregels) waaruit we de voorraad putten
  declare @IsGereserveerd smallint;

  select OrrReservering into @IsGereserveerd
  from tabOrderRegel
  where OrrGid = @OrrGid;

  //call trace(
  //  'MagGid='||            @MagGid            || '; ' ||
  //  'ArtGid='||            @ArtGid            || '; ' ||
  //  'ArtPartijGid='||      @ArtPartijGid      || '; ' ||
  //  'aantalbenodigd='||    @AantalNogTeVinden || '; ' ||
  //  'DoLocSoort='||        @DoLocSoort        || '(' ||case @DoLocSoort when 1 then 'Voorkeur' when 2 then 'Grijp excl.voorkeur' when 3 then 'Bulk excl. voorkeur' when 4 then 'grijp incl.voorkeur' when 5 then 'bulk incl.voorkeur' end ||  '); ' ||
  //  'StopAlsTeWeinig='||   @StopAlsTeWeinig   || '; ' ||
  //  'LocatieVolgorde=' ||  @LocatieVolgorde || ' ' || if @LocatieVolgorde = 0 then '(DESC)' else '(ASC)' endif
  //);

  // ACW Maak gebruik van de stored procedure ipv de view, specifiek voor 1 artikel in 1 magazijn
  if @ArtGid is not null then
    set @MatViewNummer = '(' ||
      if @MagGid is not null then '@MagGid=' || @MagGid || ', ' endif ||
      '@ArtGid=' || @ArtGid ||
      if @ArtPartijGid is not null then ', @ArtPartijGid= ' || @ArtPartijGid endif ||
      ')';
  end if;

  set @MatView = 'vwVoorraadAantallen' || @MatViewNummer;

  /*Negatief aantal? Dan gewoon overnemen naar de opgegeven of voorkeurslocatie*/
  /*Of, indien van toepassing, de reeds opgegeven locatie*/
  if @aantalbenodigd < 0 then
    /*Alles overnemen naar de opgegeven of voorkeurslocatie omdat we een negatief aantal hebben*/
    if @LocGid is null then
      insert into tmpLocaties(tmpLocGid, tmpPartijGid, tmpAantal)
      select LocGid, @ArtPartijGid,
      case
        when @AfkappenPer is not null then floor(@aantalbenodigd / @AfkappenPer) * @AfkappenPer
        when @AfrondenPer is not null then round(@aantalbenodigd / @AfrondenPer, 0) * @AfrondenPer
        else @aantalbenodigd
      end
      from tabartikelmagazijn
      inner join tabArtikelLocatie on ArtLocLocGid = ArtMagDefaultLocGid and ArtLocArtMagGid = ArtMagGid
      where ArtMagArtGid = @ArtGid and ArtMagMagGid = @MagGid;
    else
      insert into tmpLocaties(tmpLocGid, tmpPartijGid, tmpAantal)
      values(@LocGid, @ArtPartijGid, @aantalbenodigd);
    endif;
    set @AantalBenodigd = 0;

  else
    // Positief aantal benodigd, dus in magazijnen/locaties zoeken

    // Als een orderregel NIET wordt gereserveerd, maar WEL aan een locatie is toegewezen,
    // dan zou dat aantal alsnog NIET gepakt mogen worden. Voofr de huidige regel wordt daar nu rekening mee gehouden,
    // maar met andere toegewezen maar niet gereserveerde regels wordt nu geen rekening gehouden.
    // Op zich geen probleem, omdat we er dan best vanuit kunnen gaan dat de regels gereserveerd moeten zijn.
    // (Anders kunnen we het al niet eens meer over beschikbare voorraad hebben)
    if @IsGereserveerd = 0 /*Niet reserveren*/ then
      // Deze levering is niet gereserveerd, dus de spec.regels nog van het aantal beschikbaar afhalen
      set @MatView =
        '(select calcArtGid, calcArtPartijGid, calcMagGid, calcLocGid, calcBeschikbareVoorraad
          from (select calcArtGid, calcArtPartijGid, calcMagGid, calcLocGid, calcBeschikbareVoorraad from ' || @MatView || ') as vwView
          union All
          select ' || @ArtGid || ', OrlArtPartijGid, OrlMagGid, OrlLocGid, -OrlDezeLeveringVrrdEenh
          from tabOrderRegelLocatie where OrlOrrGid = ' || @OrrGid || '
          and OrlMagGid = ' || @MagGid ||'
          and OrlLocGid is not null
         ) as vwTotalen'
    end if;

    set @sql = '
    begin
      declare @AantalNogTeVinden numeric(15,3) = ' || @AantalBenodigd || ';
      declare @_PakPerAantal numeric(15,3) = '|| @PakPerAantal || ';
      declare @ExclLocList long nvarchar = ' || if isnull(@ExclLocList, '') = '' then 'null' else '''' || Replace(@ExclLocList, '''', '''''') || '''' endif || ';
      declare @AantalNuPakken numeric(15,3);
      ' ||
      if @AfkappenPer is not null then '
        declare @AfkappenPer numeric(15,3) = ' || @AfkappenPer || ';
        '
      endif ||
      if @AfrondenPer is not null then '
        declare @AfrondenPer numeric(15,3) = ' || @AfrondenPer || ';
        '
      endif || '

      for @Partijcursor as cursor_partij cursor for
        select
          calcLocGid @calcLocGid, ' ||
          if @PartijVolgorde = 0 /*geen*/ and @ArtPartijGid is null /*geen volgorde en geen partij meegegeven, dan ook niet teruggeven*/
          then 'null ' else 'calcArtPartijGid ' endif || '
          @calcArtPartijGid, ' ||
          if @PartijVolgorde = 0 /*geen*/ and @ArtPartijGid is null /*geen volgorde en geen partij meegegeven, dan ook niet teruggeven*/
          then 'null ' else 'ArtPartijNummer ' endif || '
          @ArtPartijNummer,
          sum(calcBeschikbareVoorraad) @AantalBeschikbaar,
          ArtMagDefaultLocGid @ArtMagDefaultLocGid, ' ||
          case @PartijVolgorde
            // when 0 /*niet*/ then noppes (want dan slaan we de datum over en orderby gelijk op naam
            when 1 /*productiedatum*/ then 'ArtPartijDatumProductie '
            when 2 /*ontvangstdatum*/ then 'ArtPartijDatumOntvangst '
            when 3 /*THTdatum*/ then 'ArtPartijThtDatum '
          else 'NULL '
          end || '@PartijDatumOrderBy

        from ' || @MatView || '
             inner join tabArtikelMagazijn on ArtMagMagGid = ' || @Maggid || ' and ArtMagArtGid = ' || @ArtGid || ' /* tbv bepalen voorkeurslocatie in het magazijn*/
             inner join tabLocatie on LocGid = calcLocGid
             left outer join tabArtikelLocatie on ArtLocLocGid = calcLocGid and ArtLocLocGid = LocGid and ArtLocArtMagGid = ArtMagGid and artlocpartijgid = calcartpartijgid
             left outer join tabArtikelPartij on ArtPartijGid = calcArtPartijGid

        where calcMagGid = ' || @MagGid || '
          and calcArtGid = ' || @ArtGid || ' ' ||
          if @ArtPartijGid is not null then 'and calcArtPartijGid = ' || @ArtPartijGid || ' ' endif  ||
          // Voorkeurslocatie?
          if @DoLocSoort in (0 /*Default loc van willekeurig type*/, 1 /*Default loc van type grijp*/, 7 /*default type PICK*/) then 'and calcLocGid = ArtMagDefaultLocGid /*Default locatie*/  ' endif ||
          // Type grijp?
          if @DoLocSoort in (1 /*Default loc van type grijp*/, 2 /*grijp excl.voorkeur*/, 4 /*grijp incl.voorkeur*/, 7 /*default type grijp*/) then 'and LocLocatietype = 4 /*grijp*/ ' endif ||
          // Type Bulk?
          if @DoLocSoort in (3 /*bulk excl.voorkeur*/,  5 /*bulk incl.voorkeur*/)  then 'and LocLocatietype = 3 /*bulk*/ ' endif ||
          // Excl. voorkeurslocatie?
          if @DoLocSoort in (2 /*grijp excl.voorkeur*/, 3 /*bulk excl.voorkeur*/) then 'and (ArtMagDefaultLocGid is null or calcLocGid <> ArtMagDefaultLocGid) ' endif ||
          // Opgegeven locatie?
          if @DoLocSoort = 6 /*Locatie zoals opgegeven*/ then 'and LocGid = ' || @LocGid || ' ' endif ||
          // Exclusief deze lijst van locaties
          if isnull(@ExclLocList, '') <> '' then  'and LocGid not in (select ExclLocGid from openstring(value @ExclLocList) with (ExclLocGid integer) option (delimited by '';'' row delimited by '','') tmpExclLocaties )  ' endif ||
          '
        group by
          /*Magazijninfo*/
          ArtMagDefaultLocGid,
          /*Locatiegegevens*/
          calcLocGid,
          LocLocatietype,
          /*Partijgegevens*/
          @calcArtPartijGid, @PartijDatumOrderBy, @ArtPartijNummer

        having
          @AantalBeschikbaar > 0 /*In ieder geval moet er wat beschikbaar zijn*/
          /*Als de locatie het aantal volledig moet bevatten, dan controleren we daarop en locaties met tekort worden dan niet teruggegeven
            Omdat dit PER PARTIJ gaat, kan er genoeg in de locatie liggen, maar voor de individuele partijen alsnog niet genoeg, dan krijgen we niks terug */
          ' || if @StopAlsTeWeinig = 1 then ' and @AantalBeschikbaar >= @AantalNogTeVinden ' endif ||
          '
        order by ' ||
          if @doLocSoort = 1 /*default*/ then 'ArtMagDefaultLocGid,' endif ||
          if @LocatieVolgorde = 0 /*Vanaf meest beschikbaar*/ then '@AantalBeschikbaar DESC, ' endif ||
          if @LocatieVolgorde = 1 /*Vanaf minst beschikbaar*/ then '@AantalBeschikbaar, ' endif || '
          @PartijDatumOrderBy,
          @ArtPartijNummer

      for read only do ' ||

        // Verlaten als de locatie niet meer de default is terwijl we alleen default willen of er ligt toch niet genoeg in de default
        if @doLocSoort = 1 /*default*/ then
          // Is niet (meer) de voorkeurslocatie, dus stoppen
          'if (@calcLocGid <> @ArtMagDefaultLocGid) then
            leave;
          end if;'
        endif || '

        set @AantalNuPakken = lesser(
          floor(@AantalBeschikbaar/@_PakPerAantal) * @_PakPerAantal,
          @AantalNogTeVinden
        );
        ' ||
        /*Bij afronden/afkappen eerst nieuwe resultaat bepalen*/
        if @AfrondenPer is not null then '
        set @AantalNuPakken = round(@AantalNuPakken/@AfrondenPer, 0)*@AfrondenPer;'
        end if ||
        if @AfkappenPer is not null then '
        set @AantalNuPakken = floor(@AantalNuPakken/@AfkappenPer) * @AfkappenPer;'
        end if ||
        '
        if @AantalNuPakken <> 0 then
          insert into tmpLocaties(tmpLocGid, tmpPartijGid, tmpAantal)
          values(
            @calcLocGid,
            @calcArtPartijGid,
            @AantalNuPakken
          );
          ' ||
          if @StopAlsTeWeinig = 2 /*Stop als te weinig, maar wel de ene locatie nog teruggeven*/ then
          'if @AantalNuPakken < @AantalNogTeVinden then
             leave;
           end if;'
          end if ||
          '
          set @AantalNogTeVinden = @AantalNogTeVinden - @AantalNuPakken;
        end if;

        // Stoppen als we niks meer te zoeken hebben
        if @AantalNogTeVinden < @_PakPerAantal then
          leave;
        end if;

      end for;
    end;
    ';
    //message @sql;
    execute immediate @sql;
  end if;

  select
    tmpLocGid zlLocGid,
    tmpPartijGid zlArtPartijGid,
    tmpAantal zlAantalBeschikbaar
  from tmpLocaties
  where zlAantalBeschikbaar <> 0
  order by tmpGid;
end;


create or replace procedure OrderRegelSpecificaties_ZoekLocatieVoorBestaandeSpecregels(
  in @_OrrGid integer,
  in @_MagGid integer,
  in @_ArtGid integer,
  in @ZoekPerAantalVoorrEenheden numeric(15,3),
  in @AlleenInVeelvoudVanEenheid smallint,
  in @OrrAantalLevering numeric(15,3),
  in @tmpLocaties table ref,
  in @MatViewNummerVoorraadAantallen nchar(20) default null,
  in @AfrondenPer numeric(15,3) default null,// Als we 50 zoeken en er 19 vinden, maar afronden per 10, dan resultaat=20 en we zoeken er dan nog 30
  in @AfkappenPer numeric(15,3) default null // Als we 50 zoeken en er 19 vinden, maar afkappen per 10, dan resultaat=10 en we zoeken er dan nog 40
)
begin
  // LET OP! We verwijderen de regels niet, maar plaatsen wel in tmplocaties,
  //         dus gaan we ervan uit dat VulLocatiesAan ook regels kan updaten!!!!!

  declare @_ErZijnAndereSpecRegels smallint = 0;

  if exists(select first 1 from taborderregellocatie where OrlOrrGid = @_OrrGid and OrlLocGid is not null and OrlDezeLeveringVrrdEenh <> 0) then
    set @_ErZijnAndereSpecRegels = 1;
  end if;

  // *** STAP: VERWERK BESTAANDE PARTIJEN IN SPECREGELS ***
  // Ga als eerste de in de specificatieregels bestaande partijen proberen te resolven
  // Dus voor alle spec.regels die niet zijn geblokkeerd het totaal per partij bepalen en vervolgens die proberen te vinden
  // Elke specregel apart, we gaan niet meer samenvoegen (kan niet, want we verwijderen niks meer)
  for @CursorSpecPartijen AS CURSOR_SpecPartijen CURSOR FOR
    select
      OrlGid @OrlGid,
      OrlArtPartijgid @ArtPartijGid,
      OrlDezeLevering @AantalBenodigdVerkEenh,
      OrlDezeLeveringVrrdEenh @AantalBenodigdVoorrEenh
    from tabOrderRegelLocatie
         left outer join tabArtikelPartij on ArtPartijGid = OrlArtPartijGid
    where
      OrlOrrGid = @_OrrGid
      //and OrlArtSerieGid is null //Serienummers zijn al toegewezen, daarvoor gaan we geen andere partij opzoeken
      //ACWdefect72989removed and (OrlHandmatig = 1 /*or OrlArtSerieGid is not null*/) // Serienummer-regels niet verwijderen, maar toewijzen!
      and OrlLocGid is null
      //and OrlArtPartijgid is not null Ook de specregels zonder partij, maar waar de locatie leeg is proberen op te zoeken
    order by ArtPartijNummer, orlgid
  for read only do
  begin
    //declare @GevondenlocGid integer;
    //declare @GevondenpartijGid integer;
    //declare @gevondenAantal numeric(15,3);
    //
    //select first tmpLocGid, tmpPartijGid,
    //       if @AlleenInVeelvoudVanEenheid = 0 or tmpLocGid is null then tmpAantal else floor(tmpAantal/@ZoekPerAantalVoorrEenheden)*@ZoekPerAantalVoorrEenheden endif AantalGevonden
    //into @GevondenlocGid, @GevondenpartijGid, @gevondenAantal
    //from   OrderRegelSpecificaties_BeschikbaarPerLocatie(
    //  @MagGid                         = @_MagGid,
    //  @AantalBenodigdVoorrEenh        = @AantalBenodigdVoorrEenh,
    //  @ArtGid                         = @_ArtGid,
    //  @ArtPartijGid                   = @ArtPartijGid,
    //  @ZoekPerAantalVoorraadeenheden  = @ZoekPerAantalVoorrEenheden,
    //  @MatViewNummerVoorraadAantallen = @MatViewNummerVoorraadAantallen,
    //  @OrrAantalBesteld               = @OrrAantalBesteld
    //)
    //
    //update tabOrderRegelLocatie
    //set    OrlDezeLeveringVrrdEenh = @gevondenAantal,
    //       OrlDezeLevering = @gevondenAantal / @ZoekPerAantalVoorrEenheden,
    //       OrlLocGid = @GevondenlocGid
    //where  OrlGid = @OrlGid;


    insert into table ref(@tmpLocaties)
      (tmpOrlGid, tmpLocGid, tmpPartijGid, tmpAantal, tmpSetBlok)
    select @OrlGid, tmpLocGid, tmpPartijGid,
           if @AlleenInVeelvoudVanEenheid = 0 or tmpLocGid is null then tmpAantal else floor(tmpAantal/@ZoekPerAantalVoorrEenheden)*@ZoekPerAantalVoorrEenheden endif AantalGevonden,
           1 /*Spec.regel was geblokkerd, dus blijft ook zo)*/
    from OrderRegelSpecificaties_BeschikbaarPerLocatie(
      @MagGid                         = @_MagGid,
      @AantalBenodigdVoorrEenh        = @AantalBenodigdVoorrEenh,
      @ArtGid                         = @_ArtGid,
      @ArtPartijGid                   = @ArtPartijGid,
      @ZoekPerAantalVoorraadeenheden  = @ZoekPerAantalVoorrEenheden,
      @MatViewNummerVoorraadAantallen = @MatViewNummerVoorraadAantallen,
      @OrrAantalBesteld               = @OrrAantalLevering, // LET OP!! Foute naam, maar het gaat erop dat we weten dat het een retourlevering is (aantal negatief)
      @OverruleAllesVan1BulkLocatie   = if @_ErZijnAndereSpecRegels = 1 then -1 else 0 endif,
      @AfrondenPer                    = @AfrondenPer,
      @AfkappenPer                    = @AfkappenPer

    )
    where AantalGevonden <> 0;

    //rollback to savepoint;
    //commit savepoint;
  end;
  end for;
end;


create or replace function VerkooporderHeeftSpecregelsZonderLocatie(
  in @OrkGid integer,
  in @OrrGid integer default null
)
returns smallint
begin
  if exists(
    select first 1
    from taborderregel
         inner join tabOrderRegelLocatie on OrlOrrGid = OrrGid
    where OrrOrkGid = @OrkGid
      and OrrGid = isnull(@OrrGid, OrrGid)
      and OrlLocGid is null
      and OrlDezeLevering <> 0
    ) then
    return 1
  else
    return 0
  end if;
end;


create or replace procedure Verkooporder_ControleerSpecregelsOpVolledigheid(
  in @OrkGid integer,
  in @DitIsVrijVoorLeveren smallint
)
result (
    TestSerieNummers            smallint,
    TestPartijen                smallint,
    TestAantallen               smallint,
    OrrRegelnr                  integer,
    ArtCode                     nchar(20),
    SpecRegelsZonderSerienummer smallint,
    SpecRegelsZonderPartij      smallint,
    FouteAantallen              smallint
)
begin
  // Bij vrijgeven voor leveren moeten de specregels volledig zijn ingevuld:
  // Partijregistratie -> partijen moeten zijn ingevuld als het voor vrij voor levering is OF partijen verplicht bij vrijgeven verzamellijst
  // Serienummerregistratie -> serienummers moeten zijn ingevuld als het voor vrij voor levering is OF serienummers verplicht bij vrijgeven verzamellijst
  // totale aantal moet overeenkomen met de regel:
  // - Aantal mag afwijken bij levering/facturering: sum(SpecRegel.AantalInVerkEenh) MOET gelijk zijn aan regel.AantalDezeLeveringInVerkEenh
  // - Aantal mag niet afwijken: sum(SpecRegel.AantalInVoorrEenh) MOET gelijk zijn aan regel.AantalDezeLeveringInVoorraadEenh
  SELECT
    sign(ArtSerieNrRegistreren * (ArtIsSerieNrBijVrijgaveVerplicht + @DitIsVrijVoorLeveren)) TestSerieNummers, // SerieRegistratie en (bij vrijgave verplicht of is vrij voor levering)
    sign(ArtSerieNrRegistreren * (ArtIsPartijNrBijLeverenVerplicht + @DitIsVrijVoorLeveren)) TestPartijen,
    sign(@DitIsVrijVoorLeveren + TestSerieNummers) TestAantallen,
    OrrRegelnr,
    ArtCode,

    if TestSerieNummers = 0 then 0 else
      sign((select count(OrlDezeLeveringVrrdEenh) from tabOrderRegelLocatie where OrlOrrGid = OrrGid and OrlArtSerieGid  is null))
    endif SpecRegelsZonderSerienummer,

    if TestPartijen     = 0 then 0 else
      sign((select count(OrlDezeLeveringVrrdEenh) from tabOrderRegelLocatie where OrlOrrGid = OrrGid and OrlArtPartijGid is null)) endif
    SpecRegelsZonderPartij,

    if TestAantallen    = 0 then 0 else
      if VkeAantalKanVerschillen = 2 /*Verschillen bij lev/fact*/ then
        // Aantal mag afwijken bij leveren of factureren? Dan moet sum(spec.AantalInVerkEenh) gelijk zijn aan regel.DezeLevInVerkEenh
        if (OrrAantalTotaalLevVanDetail <> OrrAantalLeveringVrrdEenh) /*defect 58843: Verkoopeenheid mag hier niet afwijken, voorr.eenheden evt. wel, dus controleren we beide aantallen*/
          or (select sum(OrlDezeLevering) from tabOrderRegelLocatie where OrlOrrGid = OrrGid) <> OrrAantalLevering then 1 else 0 endif
      else
        // Aantal mag niet afwijken of alleen bij besteld? Dan moet sum(spec.AantalInVoorrEenh) gelijk zijn aan regel.DezeLevInVoorrEenh
        if OrrAantalTotaalLevVanDetail <> OrrAantalLeveringVrrdEenh then 1 else 0 endif
      endif
    endif FouteAantallen

  FROM tabOrderRegel
  inner join tabArtikel on (ArtGid = OrrArtGid)
  inner join tabVerkoopEenheid on VkeArtGid = OrrArtGid and VkeGid = OrrVkeGid
  WHERE
   // Hier de juiste regels selecteren, dus juiste order, alleen indien serienummers registreren en indien dit nodig is.
      OrrOrkGid = @OrkGid
  AND (FouteAantallen +                   // Aantallen op spec.regel ongelijk aan aantal van de orderregel
       SpecRegelsZonderSerienummer +      // Er zijn spec.regels zonder ingevuld serienummer
       SpecRegelsZonderPartij            // Er zijn spec.regels zonder ingevuld partijnummer
      ) <> 0
  AND (OrrRegelsoort = 2)                       // Natuurlijk alleen voor artikelen
  ORDER BY
    OrrRegelNr
end;


create or replace procedure Raise(
  in @nr    integer,
  in @par1  long nvarchar default null,
  in @par2  long nvarchar default null,
  in @par3  long nvarchar default null,
  in @par4  long nvarchar default null,
  in @par5  long nvarchar default null
)
begin
  declare @_VertaaldeTekst long nvarchar;

  select VrvrTekst into @_VertaaldeTekst from tabVertaal_Vertaald_RaiseErrors where VrvrFoutCode = @nr and VrvrVrttGid = @@VrttGid_Gebruiker; // Raise errors in andere talen halen we uit onze eigen tabel
  if @_VertaaldeTekst is null then
    select description into @_VertaaldeTekst from sys.sysusermessage where error=@nr;                // Nederlandse raise errors halen we uit sys.sysusermessage
  endif;
  if isnull(@_VertaaldeTekst, '') = '' then
    Raiserror @nr '(%1!) %2!', @nr, @par1 ||
                                    if @par2 is not null then ' | ' || @par2 endif ||
                                    if @par3 is not null then ' | ' || @par3 endif ||
                                    if @par4 is not null then ' | ' || @par4 endif ||
                                    if @par5 is not null then ' | ' || @par5 endif;
  else
    if @par1 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%1!', @par1); endif;
    if @par2 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%2!', @par2); endif;
    if @par3 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%3!', @par3); endif;
    if @par4 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%4!', @par4); endif;
    if @par5 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%5!', @par5); endif;

    // Raiserror @nr, @_VertaaldeTekst; gaat fout, call Raise(20371, _U('Inkoopfactuur')); krijg je dan (20371) (20371) Inkoopfactuur niet gevonden! niet gevonden!
    Raiserror @nr '%1!', @_VertaaldeTekst;
  end if;
end;



create or replace procedure RaiseEx(
  in @nr    integer,
  in @tekst long nvarchar,
  in @par1  long nvarchar default null,
  in @par2  long nvarchar default null,
  in @par3  long nvarchar default null,
  in @par4  long nvarchar default null,
  in @par5  long nvarchar default null
)
// geeft de mogelijkheid om bij een bestaande error message een andere tekst te raisen met hetzelfde nummer
// aanroeper moet bij de @tekst en @par parameters wel zelf de _U of _A functie opgeven om vertaalde teksten te tonen

// voorbeeld: call RaiseEx(20001, _U('Aan deze rekening zijn kostenplaatsen gekoppeld'));
//     geeft: (20001) Aan deze rekening zijn kostenplaatsen gekoppeld
//     terwijl de 20001 tekst is: '(20001) Aan deze rekening zijn nog kostenplaatsen en/of kostendragers gekoppeld'
//
// voorbeeld: call RaiseEx(20357, _U('Order is ingebruik omdat %1! en %2!'), _U('aantallen groter zijn dan %1!', 50),  _U('en aantallen zijn kleiner dan %1!', 100));
//     geeft: (20357) Order is ingebruik omdat aantallen groter zijn dan 50 en en aantallen zijn kleiner dan 100
//     terwijl de tekst is:  '(20357) Order is in gebruik!';
begin
  declare @_Tekst long nvarchar;

  if isnull(@tekst, '') = '' then
    Raiserror @nr '(%1!) %2!', @nr, @par1 ||
                                    if @par2 is not null then ' | ' || @par2 endif ||
                                    if @par3 is not null then ' | ' || @par3 endif ||
                                    if @par4 is not null then ' | ' || @par4 endif ||
                                    if @par5 is not null then ' | ' || @par5 endif;
  else
    set @_Tekst = @tekst;
    if @par1 is not null then set @_Tekst = replace(@_Tekst, '%1!', @par1); endif;
    if @par2 is not null then set @_Tekst = replace(@_Tekst, '%2!', @par2); endif;
    if @par3 is not null then set @_Tekst = replace(@_Tekst, '%3!', @par3); endif;
    if @par4 is not null then set @_Tekst = replace(@_Tekst, '%4!', @par4); endif;
    if @par5 is not null then set @_Tekst = replace(@_Tekst, '%5!', @par5); endif;

    Raiserror @nr '(%1!) %2!', @nr, @_Tekst;
  end if;
end;




create or replace function _A(
  in @tekst long nvarchar,
  in @par1  long nvarchar default null,
  in @par2  long nvarchar default null,
  in @par3  long nvarchar default null,
  in @par4  long nvarchar default null,
  in @par5  long nvarchar default null
)
  returns long nvarchar
  DETERMINISTIC
begin
  // select _A('Test %1! middag', 'goede') moet opleveren 'Test goede middag'.

  declare @_VtbtGid integer;
  declare @_VertaaldeTekst long nvarchar;

  set @_VertaaldeTekst = @tekst;

  if (@@VrttGid_Admin <> @@VrttGid_Nederlands) then
    // gebruiker werkt in een andere taal dan Nederlands
    // eerst het gidje van de tekst in de basistaal tabel opzoeken
    select VtbtGid into @_VtbtGid from tabVertaal_Basistaal where VtbtTekst = @tekst;

    // tekst in andere taal ophalen
    select VrtvTekst into @_VertaaldeTekst from tabVertaal_Vertaald
    where  VrtvVtbtGid     = @_VtbtGid         // tekst moet vertaling zijn van de basistekst
           and VrtvVrttGid = @@VrttGid_Admin;  // in de taal van de gebruiker
  endif;

  if @par1 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%1!', @par1); endif;
  if @par2 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%2!', @par2); endif;
  if @par3 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%3!', @par3); endif;
  if @par4 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%4!', @par4); endif;
  if @par5 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%5!', @par5); endif;

  return @_VertaaldeTekst;
end;


// vervangt alleen parameters
// wordt hergebruikt in storedprocs met loopjes waarin teksten gebruikt worden,
// dan wordt voor de loop met _U of _A eerst de tekst vertaald en in de loop _P gebruikt.
// zie bijvoorbeeld BestelAdviesObvVerkoopOrder.sp
create or replace function _P(
  in @tekst long nvarchar,
  in @par1  long nvarchar default null,
  in @par2  long nvarchar default null,
  in @par3  long nvarchar default null,
  in @par4  long nvarchar default null,
  in @par5  long nvarchar default null
)
  returns long nvarchar
  DETERMINISTIC
begin
  // select _P('Test %1! middag', 'goede') moet opleveren 'Test goede middag'.

  if @par1 is not null then set @tekst = replace(@tekst, '%1!', @par1); endif;
  if @par2 is not null then set @tekst = replace(@tekst, '%2!', @par2); endif;
  if @par3 is not null then set @tekst = replace(@tekst, '%3!', @par3); endif;
  if @par4 is not null then set @tekst = replace(@tekst, '%4!', @par4); endif;
  if @par5 is not null then set @tekst = replace(@tekst, '%5!', @par5); endif;

  return @tekst;
end;

create or replace function _U(
  in @tekst long nvarchar,
  in @par1  long nvarchar default null,
  in @par2  long nvarchar default null,
  in @par3  long nvarchar default null,
  in @par4  long nvarchar default null,
  in @par5  long nvarchar default null
)
  returns long nvarchar
  DETERMINISTIC
begin
  // select _U('Test %1! middag', 'goede') moet opleveren 'Test goede middag'.

  declare @_VtbtGid integer;
  declare @_VertaaldeTekst long nvarchar;

  set @_VertaaldeTekst = @tekst;

  if (@@VrttGid_Gebruiker <> @@VrttGid_Nederlands) then
    // gebruiker werkt in een andere taal dan Nederlands
    // eerst het gidje van de tekst in de basistaal tabel opzoeken
    select VtbtGid into @_VtbtGid from tabVertaal_Basistaal where VtbtTekst = @tekst;

    // tekst in andere taal ophalen
    select VrtvTekst into @_VertaaldeTekst from tabVertaal_Vertaald
    where  VrtvVtbtGid     = @_VtbtGid         // tekst moet vertaling zijn van de basistekst
           and VrtvVrttGid = @@VrttGid_Gebruiker;  // in de taal van de gebruiker
  endif;

  if @par1 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%1!', @par1); endif;
  if @par2 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%2!', @par2); endif;
  if @par3 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%3!', @par3); endif;
  if @par4 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%4!', @par4); endif;
  if @par5 is not null then set @_VertaaldeTekst = replace(@_VertaaldeTekst, '%5!', @par5); endif;

  return @_VertaaldeTekst;
end;



create or replace function _VervangMetRondeHaakjes
(@Tekst           long nvarchar,
 @MaxLengteTekst  integer,
 @ParameterWaarde long nvarchar)
// vervangt de eerste parameter in @Tekst met de @Parameterwaarde waarbij haakjes om de parameter gezet worden
// waarbij de parameterwaarde zodanig ingekort wordt dat de maximale lengte van de totale tekst niet overschreden wordt
//
// Voorbeeld:
//   select _VervangMetRondeHaakjes('Directe levering %1!', 40, '012345678901234567891234');
// levert op:
//   Directe levering (012345678901234567891)
returns long nvarchar
begin
  set @Tekst = _P(@Tekst, '***');
  set @Tekst = left(replace(@Tekst, '***', '(' || left(@ParameterWaarde, @MaxLengteTekst - length(@Tekst)  + 1) || ')'), @MaxLengteTekst);
  return @Tekst;
end;

create or replace procedure vwVoorraadAantallen(
  in @MagGid               integer default null,
  in @ArtGid               integer,
  in @ArtPartijGid         integer default null,
  in @LocGid               integer default null,
  in @SkipPartsToCalculate nchar(20) default '' // Onderdelen die worden overgeslagen in de berekening; indien '' dan wordt alles meegenomen
  // ********************************************************************************************
  // LET OP!!! BIJ AANPASSINGEN IN ORDERGEDEELTE OOK DE VIEWS
  // vwVoorraadAantallen, vwVoorraadAantallenKlein EN storedproc vwVoorraadAantallen NAKIJKEN!!!!
  // ********************************************************************************************

  // Hierdoor kunnen bepaalde onderdelen worden overgeslagen om de performance te versnellen.
  // Let er dan wel op welke delen je overslaat! Voorbeelden:
  // - Alleen beschikbare voorraad relevant? Sla dan magazijnontvangsten en bestellingen over
  // - Alleen min/max voorraden? Sla dan alles over behalve de magazijngegevens
  // A = Verkooporderregels reserveringen
  // B = Verkooporderregelspecificaties reserveringen
  // C = Verkooporderregels backorders
  // D = Verkooporderregelspecificaties backorders
  // E = Productie eindproduct
  // F = Productie eindproduct specificatieregels
  // G = Productie componenten: reserveringen
  // H = Productie componenten specificatieregels: reserveringen
  // I = Projecten: mutaties: reserveringen
  // J = Projecten: mutaties specificatieregels: reserveringen
  // K = Projecten: werkbonnen: reserveringen
  // L = Projecten: werkbonnen specificatieregels: reserveringen
  // M = Bestellingen
  // N = Magazijnontvangsten
  // O = Magazijnvoorraden: magazijngegevens (min/max voorraad)
  // P = Magazijnvoorraden: aantal in voorraad
  // Q = Verplaatsingsvoorstellen
  // R = Externe applicaties (bijv. WMS, maatwerk)
)
result (
  calcResRegelSoort                       integer,
  calcNawGid                              integer,
  calcOrkGid                              integer,
  calcOrrGid                              integer,
  calcPrdOkGid                            integer,
  calcPrdOcGid                            integer,
  calcPrdOeGid                            integer,
  calcPbkGid                              integer,
  calcPbrGid                              integer,
  calcPwbkGid                             integer,
  calcPwbrGid                             integer,
  calcBstKopGid                           integer,
  calcBstRglGid                           integer,
  calcMokGid                              integer,
  calcMagOntGid                           integer,
  calcArtGid                              integer,
  calcMagGid                              integer,
  calcLocGid                              integer,
  calcArtPartijGid                        integer,
  calcArtSerieGid                         integer,
  calcVvorGid                             integer,
  calcDatum                               Date,
  calcAantalBesteld                       numeric(15,3),
  calcAantalGeleverd                      numeric(15,3),
  calcAantalLeveringConcept               numeric(15,3),
  calcAantalLeveringGoedgek               numeric(15,3),
  calcAantalLeveringGoedgekVrijgegeven    numeric(15,3),
  calcAantalLevering                      numeric(15,3),// compute(calcAantalLeveringConcept+calcAantalLeveringGoedgek+calcAantalLeveringGoedgekVrijgegeven),
  calcAantalBackorderConcept              numeric(15,3),
  calcAantalBackorderGoedgek              numeric(15,3),
  calcAantalBackorder                     numeric(15,3),// compute(calcAantalBackorderConcept+calcAantalBackorderGoedgek),
  calcAantalBackorderDirecteInkoopConcept numeric(15,3),
  calcAantalBackorderDirecteInkoopGoedgek numeric(15,3),
  calcAantalBackorderDirecteInkoop        numeric(15,3),// compute(calcAantalBackorderDirecteInkoopConcept+calcAantalBackorderDirecteInkoopGoedgek),
  calcAantalBackorderProductieConcept     numeric(15,3),
  calcAantalBackorderProductieGoedgek     numeric(15,3),
  calcAantalBackorderProductie            numeric(15,3),// compute(calcAantalBackorderProductieConcept+calcAantalBackorderProductieGoedgek),
  calcGereserveerdTotaal                  numeric(15,3),// compute(calcGereserveerdBackorderConcept+calcGereserveerdBackorderGoedgek+calcGereserveerdLeveringConcept+calcGereserveerdLeveringGoedgek+calcGereserveerdProjectOnderhanden+calcGereserveerdProjectVoorbereid),
  calcGereserveerdBackorderConcept        numeric(15,3),
  calcGereserveerdBackorderGoedgek        numeric(15,3),
  calcGereserveerdBackorder               numeric(15,3),// compute(calcGereserveerdBackorderConcept+calcGereserveerdBackorderGoedgek),
  calcGereserveerdLeveringConcept         numeric(15,3),
  calcGereserveerdLeveringGoedgek         numeric(15,3),
  calcGereserveerdLevering                numeric(15,3),// compute(calcGereserveerdLeveringConcept+calcGereserveerdLeveringGoedgek),
  calcGereserveerdProjectOnderhanden      numeric(15,3),
  calcGereserveerdProjectVoorbereid       numeric(15,3),
  calcGereserveerdVoorraadverplaatsing    numeric(15,3),
  calcGereserveerdProductie               numeric(15,3),// compute(calcGereserveerdProjectOnderhanden+calcGereserveerdProjectVoorbereid),
  calcInEindProductie                     numeric(15,3),
  calcInBestellingConcept                 numeric(15,3),
  calcInBestellingGoedgek                 numeric(15,3),
  calcInBestellingVerwerkt                numeric(15,3),
  calcInBestellingDirecteInkoop           numeric(15,3),
  calcInVerkoopOrderProductie             numeric(15,3),
  calcInVoorraadVerplaatsingen            numeric(15,3),
  calcInBestellingVoorEconomischeVoorraad numeric(15,3),
  calcInMagOntvangst                      numeric(15,3),
  calcInMagOntvangstDirecteInkoop         numeric(15,3),
  calcMagazijnVoorraad                    numeric(15,3),
  calcVrijeVoorraad                       numeric(15,3),
  calcBeschikbareVoorraad                 numeric(15,3),
  calcEconomischeVoorraad                 numeric(15,3),
  calcMaximumVoorraad                     numeric(15,3),
  calcMinimumVoorraad                     numeric(15,3),
  calcReserveVoorraad                     numeric(15,3)

)
begin
  // Verkooporders - Reserveringen
  // ***************************************************
  // ********** Verkooporders - Reserveringen **********
  // ***************************************************
  select
      0                                                 as calcResRegelSoort,
      orders.vwNawGid                                   as calcNawGid,
      orders.vwOrkGid                                   as calcOrkGid,
      orders.vwOrrGid                                   as calcOrrGid,
      null                                              as calcPrdOkGid,
      null                                              as calcPrdOcGid,
      null                                              as calcPrdOeGid,
      null                                              as calcPbkGid,
      null                                              as calcPbrGid,
      null                                              as calcPwbkGid,
      null                                              as calcPwbrGid,
      null                                              as calcBstKopGid,
      null                                              as calcBstRglGid,
      null                                              as calcMokGid,
      null                                              as calcMagOntGid,
      orders.vwArtGid                                   as calcArtGid,
      orders.vwMagGid                                   as calcMagGid,
      orders.vwLocGid                                   as calcLocGid,
      orders.vwArtPartijGid                             as calcArtPartijGid,
      orders.vwArtSerieGid                              as calcArtSerieGid,
      null                                              as calcVvorGid,
      orders.vwDatum                                    as calcDatum,
      sum(orders.vwAantalBesteld)                       as calcAantalBesteld,
      sum(orders.vwAantalGeleverd)                      as calcAantalGeleverd,
      sum(orders.vwAantalLeveringConcept)               as calcAantalLeveringConcept,
      sum(orders.vwAantalLeveringGoedgek)               as calcAantalLeveringGoedgek,
      sum(orders.vwAantalLeveringGoedgekVrijgegeven)    as calcAantalLeveringGoedgekVrijgegeven,
      sum(orders.vwAantalLevering)                      as calcAantalLevering,
      0.0                                               as calcAantalBackorderConcept,
      0.0                                               as calcAantalBackorderGoedgek,
      0.0                                               as calcAantalBackorder,
      0.0                                               as calcAantalBackorderDirecteInkoopConcept,
      0.0                                               as calcAantalBackorderDirecteInkoopGoedgek,
      0.0                                               as calcAantalBackorderDirecteInkoop,
      0.0                                               as calcAantalBackorderProductieConcept,
      0.0                                               as calcAantalBackorderProductieGoedgek,
      0.0                                               as calcAantalBackorderProductie,
      sum(orders.vwGereserveerdTotaal)                  as calcGereserveerdTotaal,
      0.0                                               as calcGereserveerdBackorderConcept,
      0.0                                               as calcGereserveerdBackorderGoedgek,
      0.0                                               as calcGereserveerdBackorder,
      sum(orders.vwGereserveerdLeveringConcept)         as calcGereserveerdLeveringConcept,
      sum(orders.vwGereserveerdLeveringGoedgek)         as calcGereserveerdLeveringGoedgek,
      sum(orders.vwGereserveerdLevering)                as calcGereserveerdLevering,
      0.0                                               as calcGereserveerdProjectOnderhanden,
      0.0                                               as calcGereserveerdProjectVoorbereid,
      0.0                                               as calcGereserveerdVoorraadverplaatsing,
      0.0                                               as calcGereserveerdProductie,
      0.0                                               as calcInEindProductie,
      0.0                                               as calcInBestellingConcept,
      0.0                                               as calcInBestellingGoedgek,
      0.0                                               as calcInBestellingVerwerkt,
      0.0                                               as calcInBestellingDirecteInkoop,
      0.0                                               as calcInVerkoopOrderProductie,
      0.0                                               as calcInVoorraadVerplaatsingen,
      0.0                                               as calcInBestellingVoorEconomischeVoorraad,
      0.0                                               as calcInMagOntvangst,
      0.0                                               as calcInMagOntvangstDirecteInkoop,
      0.0                                               as calcMagazijnVoorraad,
      sum(-orders.vwGereserveerdTotaal)                 as calcVrijeVoorraad,
      sum(-orders.vwGereserveerdLevering)               as calcBeschikbareVoorraad,
      calcVrijeVoorraad                                 as calcEconomischeVoorraad,
      0.0                                               as calcMaximumVoorraad,
      0.0                                               as calcMinimumVoorraad,
      calcEconomischeVoorraad - calcMinimumVoorraad     as calcReserveVoorraad

  from
   (
    // Orderregellocatie
    select
      OrkNawGid                                                              as vwNawGid,
      OrkGid                                                                 as vwOrkGid,
      OrrGid                                                                 as vwOrrGid,
      OrrArtGid                                                              as vwArtGid,
      OrlMagGid                                                              as vwMagGid,
      OrlLocGid                                                              as vwLocGid,
      OrlArtPartijGid                                                        as vwArtPartijGid,
      OrlArtSerieGid                                                         as vwArtSerieGid,
      OrkLeverDatum                                                          as vwDatum,
      0.0                                                                    as vwAantalBesteld,
      sum(OrlGeleverdVrrdEenh)                                                       as vwAantalGeleverd,
      sum(if OrkGoedgekeurd = 0 then OrlDezeLeveringVrrdEenh else 0.0 endif)         as vwAantalLeveringConcept,
      sum(if OrkGoedgekeurd = 1 and OrkVrijVoorLevering = 0 then
        OrlDezeLeveringVrrdEenh else 0.0 endif)                                      as vwAantalLeveringGoedgek,
      sum(if OrkVrijVoorLevering = 1 then OrlDezeLeveringVrrdEenh else 0.0 endif)    as vwAantalLeveringGoedgekVrijgegeven,
      sum(OrlDezeLeveringVrrdEenh)                                                   as vwAantalLevering,
      sum(if OrrReservering in (1,2) then OrlAantalGereserveerd else 0.0 endif)  vwGereserveerdTotaal,
      sum(if OrkGoedgekeurd = 0 and OrrReservering in (1,2) then OrlAantalGereserveerd else 0.0 endif)   as vwGereserveerdLeveringConcept,
      sum(if OrkGoedgekeurd = 1 and OrrReservering in (1,2) then OrlAantalGereserveerd else 0.0 endif)   as vwGereserveerdLeveringGoedgek,
      sum(if OrrReservering in (1,2) then OrlAantalGereserveerd else 0.0 endif )  as vwGereserveerdLevering
    from
      tabOrderRegelLocatie
      inner join tabOrderregel on (OrrGid = OrlOrrGid) and (OrrRegelSoort = 2)
      inner join tabOrderkop on (OrkGid = OrrOrkGid) and (OrkSoort = 0)
    where
      locate(@SkipPartsToCalculate, 'B') = 0
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    group by
      vwNawGid,
      vwOrkGid,
      vwOrrGid,
      vwArtGid,
      vwMagGid,
      vwLocGid,
      vwArtPartijGid,
      vwArtSerieGid,
      vwDatum

    union all

    // Orderregels (met restant)
    select
      OrkNawGid                                                                                        as vwNawGid,
      OrkGid                                                                                           as vwOrkGid,
      OrrGid                                                                                           as vwOrrGid,
      OrrArtGid                                                                                        as vwArtGid,
      OrrMagGid                                                                                        as vwMagGid,
      null                                                                                             as vwLocGid,
      OrrArtPartijGid                                                                                  as vwArtPartijGid,
      null                                                                                             as vwArtSerieGid,
      OrkLeverDatum                                                                                    as vwDatum,
      sum(OrrAantalBesteldVrrdEenh)                                                                            as vwAantalBesteld,
      sum(OrrAantalGeleverdVrrdEenh)                                                                           as vwAantalGeleverd,
      sum(if OrkGoedgekeurd = 0 then OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail else 0.0 endif)   as vwAantalLeveringConcept,
      sum(if OrkGoedgekeurd = 1 and OrkVrijVoorLevering = 0 then
        OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail else 0.0 endif)                                as vwAantalLeveringGoedgek,
      sum(if OrkVrijVoorLevering = 1 then
        OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail else 0.0 endif)                                as vwAantalLeveringGoedgekVrijgegeven,
      sum(OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail)                                             as vwAantalLevering,
      sum(if OrrReservering in (1,2) and (sign(OrrAantalGereserveerdDezeLevering) > 0 or OrrReserveringNegatief = 1) and
          abs(OrrAantalGereserveerdDezeLevering) > abs(OrrAantalTotaalLevVanDetail) then
            OrrAantalGereserveerdDezeLevering - OrrAantalTotaalLevVanDetail else 0.0 endif)            as vwGereserveerdTotaal,
      sum(if OrkGoedgekeurd = 0 and OrrReservering in (1,2) and (sign(OrrAantalGereserveerdDezeLevering) > 0 or OrrReserveringNegatief = 1) and
          abs(OrrAantalGereserveerdDezeLevering) > abs(OrrAantalTotaalLevVanDetail) then
            OrrAantalGereserveerdDezeLevering - OrrAantalTotaalLevVanDetail else 0.0 endif)            as vwGereserveerdLeveringConcept,
      sum(if OrkGoedgekeurd = 1 and OrrReservering in (1,2) and (sign(OrrAantalGereserveerdDezeLevering) > 0 or OrrReserveringNegatief = 1) and
          abs(OrrAantalGereserveerdDezeLevering) > abs(OrrAantalTotaalLevVanDetail) then
            OrrAantalGereserveerdDezeLevering - OrrAantalTotaalLevVanDetail else 0.0 endif)            as vwGereserveerdLeveringGoedgek,
      sum(if OrrReservering in (1,2) and (sign(OrrAantalGereserveerdDezeLevering) > 0 or OrrReserveringNegatief = 1) and
          abs(OrrAantalGereserveerdDezeLevering) > abs(OrrAantalTotaalLevVanDetail) then
             OrrAantalGereserveerdDezeLevering - OrrAantalTotaalLevVanDetail else 0.0 endif)           as vwGereserveerdLevering
    from
      tabOrderregel
      inner join tabOrderkop on (OrkGid = OrrOrkGid) and (OrkSoort = 0)
    where
      locate(@SkipPartsToCalculate, 'A') = 0
      and OrrRegelSoort = 2
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    group by
      vwNawGid,
      vwOrkGid,
      vwOrrGid,
      vwArtGid,
      vwMagGid,
      vwLocGid,
      vwArtPartijGid,
      vwArtSerieGid,
      vwDatum
   ) Orders
  group by
      calcNawGid,
      calcOrkGid,
      calcOrrGid,
      calcArtGid,
      calcMagGid,
      calcLocGid,
      calcArtPartijGid,
      calcArtSerieGid,
      calcVvorGid,
      calcDatum

union all // Verkooporders - Backorders

  // ************************************************
  // ********** Verkooporders - Backorders **********
  // ************************************************
  select
      1                                                as calcResRegelSoort,
      BackOrders.vwNawGid                              as calcNawGid,
      BackOrders.vwOrkGid                              as calcOrkGid,
      BackOrders.vwOrrGid                              as calcOrrGid,
      null                                             as calcPrdOkGid,
      null                                             as calcPrdOcGid,
      null                                             as calcPrdOeGid,
      null                                             as calcPbkGid,
      null                                             as calcPbrGid,
      null                                             as calcPwbkGid,
      null                                             as calcPwbrGid,
      null                                             as calcBstKopGid,
      null                                             as calcBstRglGid,
      null                                             as calcMokGid,
      null                                             as calcMagOntGid,
      BackOrders.vwArtGid                              as calcArtGid,
      BackOrders.vwMagGid                              as calcMagGid,
      BackOrders.vwLocGid                              as calcLocGid,
      BackOrders.vwArtPartijGid                        as calcArtPartijGid,
      BackOrders.vwArtSerieGid                         as calcArtSerieGid,
      null                                             as calcVvorGid,
      BackOrders.vwDatum                               as calcDatum,
      0.0                                              as calcAantalBesteld,
      0.0                                              as calcAantalGeleverd,
      0.0                                              as calcAantalLeveringConcept,
      0.0                                              as calcAantalLeveringGoedgek,
      0.0                                              as calcAantalLeveringGoedgekVrijgegeven,
      0.0                                              as calcAantalLevering,
      BackOrders.vwAantalBackorderConcept              as calcAantalBackorderConcept,
      BackOrders.vwAantalBackorderGoedgek              as calcAantalBackorderGoedgek,
      BackOrders.vwAantalBackorder                     as calcAantalBackorder,
      BackOrders.vwAantalBackorderDirecteInkoopConcept as calcAantalBackorderDirecteInkoopConcept,
      BackOrders.vwAantalBackorderDirecteInkoopGoedgek as calcAantalBackorderDirecteInkoopGoedgek,
      BackOrders.vwAantalBackorderDirecteInkoop        as calcAantalBackorderDirecteInkoop,
      BackOrders.vwAantalBackorderProductieConcept     as calcAantalBackorderProductieConcept,
      BackOrders.vwAantalBackorderProductieGoedgek     as calcAantalBackorderProductieGoedgek,
      BackOrders.vwAantalBackorderProductie            as calcAantalBackorderProductie,
      BackOrders.vwGereserveerdTotaal                  as calcGereserveerdTotaal,
      BackOrders.vwGereserveerdBackorderConcept        as calcGereserveerdBackorderConcept,
      BackOrders.vwGereserveerdBackorderGoedgek        as calcGereserveerdBackorderGoedgek,
      BackOrders.vwGereserveerdBackorder               as calcGereserveerdBackorder,
      0.0                                              as calcGereserveerdLeveringConcept,
      0.0                                              as calcGereserveerdLeveringGoedgek,
      0.0                                              as calcGereserveerdLevering,
      0.0                                              as calcGereserveerdProjectOnderhanden,
      0.0                                              as calcGereserveerdProjectVoorbereid,
      0.0                                              as calcGereserveerdVoorraadverplaatsing,
      0.0                                              as calcGereserveerdProductie,
      0.0                                              as calcInEindProductie,
      0.0                                              as calcInBestellingConcept,
      0.0                                              as calcInBestellingGoedgek,
      0.0                                              as calcInBestellingVerwerkt,
      0.0                                              as calcInBestellingDirecteInkoop,
      0.0                                              as calcInVerkoopOrderProductie,
      0.0                                              as calcInVoorraadVerplaatsingen,
      0.0                                              as calcInBestellingVoorEconomischeVoorraad,
      0.0                                              as calcInMagOntvangst,
      0.0                                              as calcInMagOntvangstDirecteInkoop,
      0.0                                              as calcMagazijnVoorraad,
      -BackOrders.vwGereserveerdTotaal                 as calcVrijeVoorraad,
      //ACW 23-10-2009: Reserveringen van ONTVANGEN backorders van directe inkopen zijn NIET beschikbaar!
      -BackOrders.calcBoDirInkAantalOntvangenTbvBackorder - BackOrders.calcBoProdAantalReedsVerwerktTbvBackorder as calcBeschikbareVoorraad,
      calcVrijeVoorraad                                as calcEconomischeVoorraad,
      0.0                                              as calcMaximumVoorraad,
      0.0                                              as calcMinimumVoorraad,
      calcEconomischeVoorraad - calcMinimumVoorraad    as calcReserveVoorraad
  from
   (
    // Orderregels (met restant)
    select
      OrkNawGid                                                                                        as vwNawGid,
      OrkGid                                                                                           as vwOrkGid,
      OrrGid                                                                                           as vwOrrGid,
      OrrArtGid                                                                                        as vwArtGid,
      OrrMagGid                                                                                        as vwMagGid,
      null                                                                                             as vwLocGid,
      OrrArtPartijGid                                                                                  as vwArtPartijGid,
      null                                                                                             as vwArtSerieGid,
      IsNull (OrrLeverDatum, OrkLeverDatum)                                                            as vwDatum,

      //ACW 23-10-2009: Aantal (gereserveerd voor) backorder wordt nu anders berekend:
      //                Eerst werden directe inkopen gewoon niet meegenomen in beide berekeningen
      //                Nu wordt het aantal dat daarwerkelijk is ontvangen toch meegenomen, tot aan het aantal dat in backorder staat
      //                Dus wordt als Aantal Backorder het minimum genomen van Backorder en Aantal in backorder minus NogTeOntvangen op de bestelling (Als er geen bestelregel van is, dan is NogTeOntvangen eigenlijk het aantal in backorder!)
      //                Let op: Dit gaat alleen op als de magazijnontvangst verwerkt is! Dus moeten we het aantal dat in een magazijnontvangst gekoppeld aan de bestelregel staat er weer vanaf halen.

      // Velden rechtstreeks uit vwBackorderAantallen.
      // ********************************************************************************************************
      // LET OP - indien hier een aanpassing komt, dan OOK in vwBackorderAantallen en vwVoorraadAantallenKlein!!!
      // ********************************************************************************************************
      //calcBoDirInkAantalBesteld                         = isnull(brdAantalBesteld, 0.00),


      if OrrDirecteInkoop = 0 then 0.00 else
        (select sum(MagOntLocAantal) MagOntLocAantal2
         from tabMagazijnOntvangstenDetail
              inner join tabMagazijnOntvangstLocatieSerie on (MagOntLocMagOntDetGid = MagOntDetGid)
         where  (MagOntDetbrdGid is null and MagOntDetOrrGid = OrrGid)
        )
      endif calcBoOntvangenNietBesteldDI,

      isnull(brdAantalOntvangen, 0.00) + isnull(calcBoOntvangenNietBesteldDI, 0.00) calcBoDirInkAantalOntvangen,

      isnull(if brdGid is not null then isnull(brdAantalNogTeOntvangen, 0) endif, if OrrDirecteInkoop = 1 then OrrAantalBackorderVrrdEenh - isnull(calcBoOntvangenNietBesteldDI, 0) else 0 endif) calcBoDirInkAantalNogTeOntvangen,

      if OrrDirecteInkoop = 0 then 0 else
        isnull((select sum(MagOntLocAantal) MagOntLocAantal2
                from tabMagazijnOntvangstenDetail
                     inner join tabMagazijnOntvangstLocatieSerie on (MagOntLocMagOntDetGid = MagOntDetGid)
                where  MagOntDetbrdGid = BrdGid
               )
              , 0) + isnull(calcBoOntvangenNietBesteldDI, 0)
      endif calcBoDirInkAantalOntvangenNietVerwerkt,

      calcBoDirInkAantalOntvangen - calcBoDirInkAantalOntvangenNietVerwerkt calcBoDirInkAantalOntvangenEnVerwerkt,

      calcBoDirInkAantalNogTeOntvangen + calcBoDirInkAantalOntvangenNietVerwerkt calcBoDirInkAantalNogTeOntvangenOfTeVerwerken, // Dit is aantal nog te ontvangen + aantal ontvangenNogTeVerwerken!

      if sign(calcBoDirInkAantalOntvangenEnVerwerkt) = sign(OrrAantalLeveringVrrdEenh + OrrAantalGeleverdVrrdEenh) then
        if abs(calcBoDirInkAantalOntvangenEnVerwerkt) < abs(OrrAantalLeveringVrrdEenh + OrrAantalGeleverdVrrdEenh) then
          calcBoDirInkAantalOntvangenEnVerwerkt
        else
          OrrAantalLeveringVrrdEenh + OrrAantalGeleverdVrrdEenh
        endif
      else
        0 // Teken is niet gelijk dus niets ontvangen tbv. DezeLeveringGeleverd
      endif calcBoDirInkAantalOntvangenTbvLeveringGeleverd,

      calcBoDirInkAantalOntvangenEnVerwerkt - calcBoDirInkAantalOntvangenTbvLeveringGeleverd calcBoDirInkAantalOntvangenTbvBackorder,

      if OrrDirecteInkoop = 1 then
        if calcBoDirInkAantalOntvangenTbvBackorder < OrrAantalBackorderVrrdEenh then
          if (calcBoDirInkAantalOntvangenTbvBackorder > 0) or (OrrReserveringNegatief = 1) then calcBoDirInkAantalOntvangenTbvBackorder else 0 endif
        else
          if (orrReservering = 2 /*2=levering + backorder*/) and ((OrrAantalBackorderVrrdEenh > 0) or (OrrReserveringNegatief = 1)) then OrrAantalBackorderVrrdEenh else 0 endif
        endif
      else
        0 // Geen directe inkoop, DUS niets reserveren voor directe inkoop
      endif calcBoAantalInBackorderVoorReserveringDI,

      if OrrProductie = 1 then
        if calcBoProdAantalReedsVerwerktTbvBackorder < OrrAantalBackorderVrrdEenh then
          if calcBoProdAantalReedsVerwerktTbvBackorder > 0 or OrrReserveringNegatief = 1 then calcBoProdAantalReedsVerwerktTbvBackorder else 0 endif
        else
          if OrrAantalBackorderVrrdEenh > 0 or OrrReserveringNegatief = 1 then OrrAantalBackorderVrrdEenh else 0 endif
        endif
      else
        0
      endif calcBoAantalInBackorderVoorReserveringProductie,

      if OrrDirecteInkoop = 1 then
        if OrrAantalBackorderVrrdEenh - calcBoDirInkAantalOntvangenTbvBackorder - calcBoDirInkAantalNogTeOntvangenOfTeVerwerken > 0 or (OrrReserveringNegatief = 1) then
          OrrAantalBackorderVrrdEenh - calcBoDirInkAantalOntvangenTbvBackorder - calcBoDirInkAantalNogTeOntvangenOfTeVerwerken
        else
          0
        endif
      else
        0
      endif +
      if OrrProductie = 1 then
        if OrrAantalBackorderVrrdEenh - calcBoProdAantalReedsVerwerktTbvBackorder - IsNull(calcBoProdAantalNogTeOntvangen, 0) > 0 or (OrrReserveringNegatief = 1) then
          OrrAantalBackorderVrrdEenh - calcBoProdAantalReedsVerwerktTbvBackorder - IsNull(calcBoProdAantalNogTeOntvangen, 0)
        else
          0
        endif
      else
        0
      endif +
      if OrrDirecteInkoop + OrrProductie = 0 then
        if (orrReservering = 2 /*2=levering + backorder*/) and (OrrAantalBackorderVrrdEenh > 0 or OrrReserveringNegatief = 1) then OrrAantalBackorderVrrdEenh else 0.00 endif
      else
        0
      endif calcBoAantalInBackorderVoorReserveringVoorraad,

      calcBoAantalInBackorderVoorReserveringDI + calcBoAantalInBackorderVoorReserveringProductie + calcBoAantalInBackorderVoorReserveringVoorraad calcBoAantalInBackorderVoorReservering,

      (
        if (OrrDirecteInkoop = 1) and sign(calcBoDirInkAantalNogTeOntvangenOfTeVerwerken) <> 0 then
          if (sign(calcBoDirInkAantalNogTeOntvangenOfTeVerwerken) = sign(OrrAantalBackorderVrrdEenh)) and (abs(calcBoDirInkAantalNogTeOntvangenOfTeVerwerken) < abs(OrrAantalBackorderVrrdEenh)) then
            if calcBoDirInkAantalNogTeOntvangenOfTeVerwerken > 0 then calcBoDirInkAantalNogTeOntvangenOfTeVerwerken else 0 endif
          else
            if OrrAantalBackorderVrrdEenh > 0 then OrrAantalBackorderVrrdEenh else 0 endif
          endif
        else
          0 // Geen directe inkoop, DUS geen nog te ontvangen
        endif
      ) calcBoDirInkAantalInBackorderNogTeOntvTeVerw,

      (
        if OrrDirecteInkoop = 1 then
          if sign(OrrAantalBackorderVrrdEenh - calcBoDirInkAantalInBackorderNogTeOntvTeVerw) = 0 then
            0 // Is nul, dus niet meer met de sign van aantalbackorder vergelijken omdat dat waarschijnlijk een false oplevert, waardoor aantalbackorder wordt gebruikt
          else
            if (sign(OrrAantalBackorderVrrdEenh - calcBoDirInkAantalInBackorderNogTeOntvTeVerw) = sign(OrrAantalBackorderVrrdEenh)) and (abs(OrrAantalBackorderVrrdEenh - calcBoDirInkAantalInBackorderNogTeOntvTeVerw) < abs(OrrAantalBackorderVrrdEenh)) then
              OrrAantalBackorderVrrdEenh - calcBoDirInkAantalInBackorderNogTeOntvTeVerw
            else
              OrrAantalBackorderVrrdEenh
            endif
          endif
        else
          OrrAantalBackorderVrrdEenh
        endif
      ) calcBoInBackOrderExclDirecteInkoopNogTeOntvangen,

      (
        OrrAantalBackorderVrrdEenh - calcBoInBackOrderExclDirecteInkoopNogTeOntvangen
      ) calcBoDirInkAantalBackorderDirecteInkoop,

      //Productie
      (
        isnull(PrdOesTotaalPrdOesAantalTotaalTeVerwerken, 0.00)
      ) calcBoProdTotaalAantalOpteBoeken,

      (
        isnull(PrdOesTotaalPrdOesAantalTotaalTeVerwerken,
               if OrrProductie = 1 then OrrAantalBackorderVrrdEenh endif, 0)
      ) calcBoProdAantalNuOpTeBoeken,

      (
        if OrrProductie = 1 then isNull(PrdOesTotaalPrdOesAantalDezeVerwerking,0) else 0 endif
      ) calcBoProdAantalDezeVerwerking,

      (
        if OrrProductie = 1 then isNull(PrdOesTotaalPrdOesAantalReedsVerwerkt,0) else 0 endif
      ) calcBoProdAantalReedsVerwerkt,

      (
        isnull(if PrdOesTotaalAantalGekoppeld > 0 then isnull(PrdOesTotaalPrdOesAantalTotaalTeVerwerken-calcBoProdAantalReedsVerwerkt, 0) endif, if OrrProductie = 1 then OrrAantalBackorderVrrdEenh else 0 endif)
      ) calcBoProdAantalNogTeOntvangen,

      (
        if sign(calcBoProdAantalReedsVerwerkt) = sign(OrrAantalLeveringVrrdEenh + OrrAantalGeleverdVrrdEenh) then
          if abs(calcBoProdAantalReedsVerwerkt) < abs(OrrAantalLeveringVrrdEenh + OrrAantalGeleverdVrrdEenh) then
            calcBoProdAantalReedsVerwerkt
          else
            OrrAantalLeveringVrrdEenh + OrrAantalGeleverdVrrdEenh
          endif
        else
          0 // Teken is niet gelijk dus niets ontvangen tbv. DezeLeveringGeleverd
        endif
      ) calcBoProdAantalReedsVerwerktTbvLeveringGeleverd,

      (
        calcBoProdAantalReedsVerwerkt - calcBoProdAantalReedsVerwerktTbvLeveringGeleverd
      ) calcBoProdAantalReedsVerwerktTbvBackorder,

      (
        if (OrrProductie = 1) and sign(calcBoProdAantalNuOpTeBoeken) <> 0 then
          if (sign(calcBoProdAantalNuOpTeBoeken) = sign(OrrAantalBackorderVrrdEenh)) and (abs(calcBoProdAantalNuOpTeBoeken) < abs(OrrAantalBackorderVrrdEenh)) then
            if calcBoProdAantalNuOpTeBoeken > 0 then calcBoProdAantalNuOpTeBoeken else 0 endif
          else
            if OrrAantalBackorderVrrdEenh > 0 then OrrAantalBackorderVrrdEenh else 0 endif
          endif
        else
          0 // Geen productie, DUS geen nog te ontvangen
        endif
      ) calcBoProdAantalInBackorderNogTeOntvTeVerw,

      (
        if OrrProductie = 1 then
          if sign(OrrAantalBackorderVrrdEenh - calcBoProdAantalInBackorderNogTeOntvTeVerw) = 0 then
            0 // Is nul, dus niet meer met de sign van aantalbackorder vergelijken omdat dat waarschijnlijk een false oplevert, waardoor aantalbackorder wordt gebruikt
          else
            if (sign(OrrAantalBackorderVrrdEenh - calcBoProdAantalInBackorderNogTeOntvTeVerw) = sign(OrrAantalBackorderVrrdEenh)) and (abs(OrrAantalBackorderVrrdEenh - calcBoProdAantalInBackorderNogTeOntvTeVerw) < abs(OrrAantalBackorderVrrdEenh)) then
              OrrAantalBackorderVrrdEenh - calcBoProdAantalInBackorderNogTeOntvTeVerw
            else
              OrrAantalBackorderVrrdEenh
            endif
          endif
        else
          OrrAantalBackorderVrrdEenh
        endif
      ) calcBoInBackOrderExclProductieNogTeOntvangen,

      (
        OrrAantalBackorderVrrdEenh - calcBoInBackOrderExclProductieNogTeOntvangen
      ) calcBoProdAantalBackorderProductie,

      OrrAantalBackorderVrrdEenh vwAantalBackorder,
      (if OrkGoedgekeurd = 1 then 0 else vwAantalBackorder endif) vwAantalBackorderConcept,
      (if OrkGoedgekeurd = 0 then 0 else vwAantalBackorder endif) vwAantalBackorderGoedgek,
      //Dezen laten staan en niet omrekenen zoals de velden hierboven omdat dit rechtstreeks met DirecteInkoop te maken heeft en niet wordt gebruikt bij optellingen
      (
        if OrrDirecteInkoop <>0 and OrkGoedgekeurd = 0 then calcBoDirInkAantalBackorderDirecteInkoop else 0.0 endif
      ) vwAantalBackorderDirecteInkoopConcept,
      (
        if OrrDirecteInkoop <>0 and OrkGoedgekeurd = 1 then calcBoDirInkAantalBackorderDirecteInkoop else 0.0 endif
      ) vwAantalBackorderDirecteInkoopGoedgek,
      (
        if OrrDirecteInkoop <>0 then calcBoDirInkAantalBackorderDirecteInkoop else 0.0 endif
      ) vwAantalBackorderDirecteInkoop,
      //Dezen laten staan en niet omrekenen zoals de velden hierboven omdat dit rechtstreeks met DirecteInkoop te maken heeft en niet wordt gebruikt bij optellingen
      (
        if OrrProductie <>0 and OrkGoedgekeurd = 0 then calcBoProdAantalBackorderProductie else 0.0 endif
      ) vwAantalBackorderProductieConcept,
      (
        if OrrProductie <>0 and OrkGoedgekeurd = 1 then calcBoProdAantalBackorderProductie else 0.0 endif
      ) vwAantalBackorderProductieGoedgek,
      (
        if OrrProductie <>0 then calcBoProdAantalBackorderProductie else 0.0 endif
      ) vwAantalBackorderProductie,
      (calcBoAantalInBackorderVoorReservering) vwGereserveerdTotaal, // = Aantal gereserveerd voor backorders dat in het totaal gereserveerd wordt meegenomen;

      (
        if OrkGoedgekeurd = 0 then vwGereserveerdTotaal else 0.0 endif
      ) vwGereserveerdBackorderConcept,
      (
        if OrkGoedgekeurd = 1 then vwGereserveerdTotaal else 0.0 endif
      ) vwGereserveerdBackorderGoedgek,
      (vwGereserveerdTotaal) vwGereserveerdBackorder
    from
      tabOrderregel
      inner join tabOrderkop on (OrkGid = OrrOrkGid) and (OrkSoort = 0)
      left outer join tabBestelRegelDetail on (BrdOrrGid = OrrGid)
      left outer join ( select
                          sum(PrdOesAantalTotaalTeVerwerken) PrdOesTotaalPrdOesAantalTotaalTeVerwerken,
                          sum(PrdOesAantalDezeVerwerking) PrdOesTotaalPrdOesAantalDezeVerwerking,
                          sum(PrdOesAantalReedsVerwerkt) PrdOesTotaalPrdOesAantalReedsVerwerkt,
                          count(PrdOesGid) PrdOesTotaalAantalGekoppeld,
                          max(PrdOesOrrGid) PrdOesTotaalOrrGid
                        From tabProductieOrderEindproductSpec
                        group by PrdOesOrrGid
                        ) ProductieOrderEindproduct on (PrdOesTotaalOrrGid = OrrGid)
    where
      locate(@SkipPartsToCalculate, 'C') = 0
      and OrrRegelSoort = 2
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
) BackOrders

union all // Productie

  // ***********************************
  // ************ Productie ************
  // ***********************************
  select
    2                                             as calcResRegelSoort,
    null                                          as calcNawGid,
    null                                          as calcOrkGid,
    tbProductie.vwPrdOesOrrGid                    as calcOrrGid,
    tbProductie.vwPrdOkGid                        as calcPrdOkGid,
    tbProductie.vwPrdOcGid                        as calcPrdOcGid,
    tbProductie.vwPrdOeGid                        as calcPrdOeGid,
    null                                          as calcPbkGid,
    null                                          as calcPbrGid,
    null                                          as calcPwbkGid,
    null                                          as calcPwbrGid,
    null                                          as calcBstKopGid,
    null                                          as calcBstRglGid,
    null                                          as calcMokGid,
    null                                          as calcMagOntGid,
    tbProductie.vwArtGid                          as calcArtGid,
    tbProductie.vwMagGid                          as calcMagGid,
    tbProductie.vwLocGid                          as calcLocGid,
    tbProductie.vwArtPartijGid                    as calcArtPartijGid,
    tbProductie.vwArtSerieGid                     as calcArtSerieGid,
    null                                          as calcVvorGid,
    tbProductie.vwPrdDatum                        as calcDatum,
    0.0                                           as calcAantalBesteld,
    0.0                                           as calcAantalGeleverd,
    0.0                                           as calcAantalLeveringConcept,
    0.0                                           as calcAantalLeveringGoedgek,
    0.0                                           as calcAantalLeveringGoedgekVrijgegeven,
    0.0                                           as calcAantalLevering,
    0.0                                           as calcAantalBackorderConcept,
    0.0                                           as calcAantalBackorderGoedgek,
    0.0                                           as calcAantalBackorder,
    0.0                                           as calcAantalBackorderDirecteInkoopConcept,
    0.0                                           as calcAantalBackorderDirecteInkoopGoedgek,
    0.0                                           as calcAantalBackorderDirecteInkoop,
    0.0                                           as calcAantalBackorderProductieConcept,
    0.0                                           as calcAantalBackorderProductieGoedgek,
    0.0                                           as calcAantalBackorderProductie,
    sum(tbProductie.vwGereserveerdProductie)      as calcGereserveerdTotaal,
    0.0                                           as calcGereserveerdBackorderConcept,
    0.0                                           as calcGereserveerdBackorderGoedgek,
    0.0                                           as calcGereserveerdBackorder,
    0.0                                           as calcGereserveerdLeveringConcept,
    0.0                                           as calcGereserveerdLeveringGoedgek,
    0.0                                           as calcGereserveerdLevering,
    0.0                                           as calcGereserveerdProjectOnderhanden,
    0.0                                           as calcGereserveerdProjectVoorbereid,
    0.0                                           as calcGereserveerdVoorraadverplaatsing,
    sum(tbProductie.vwGereserveerdProductie)      as calcGereserveerdProductie,
  //  sum(tbProductie.vwAantalEindProductie)        as calcInEindProductie,
    // ACW Aantal in productie is exclusief het aantal dat al was geproduceerd
    (if tbProductie.vwPrdOesOrrGid is null then sum(tbProductie.vwAantalEindProductieNogTeProduceren)   else 0.00 endif) as calcInEindProductie,
    0.0                                           as calcInBestellingConcept,
    0.0                                           as calcInBestellingGoedgek,
    0.0                                           as calcInBestellingVerwerkt,
    0.0                                           as calcInBestellingDirecteInkoop,
    (if tbProductie.vwPrdOesOrrGid is not null then sum(tbProductie.vwAantalEindProductieNogTeProduceren)   else 0.00 endif) as calcInVerkoopOrderProductie,
    0.0                                           as calcInVoorraadVerplaatsingen,
    0.0                                           as calcInBestellingVoorEconomischeVoorraad,
    0.0                                           as calcInMagOntvangst,
    0.0                                           as calcInMagOntvangstDirecteInkoop,
    0.0                                           as calcMagazijnVoorraad,
    sum(-tbProductie.vwGereserveerdProductie)     as calcVrijeVoorraad,
    sum(-tbProductie.vwGereserveerdProductie)     as calcBeschikbareVoorraad,
    sum(-tbProductie.vwGereserveerdProductie)+
    calcInEindProductie                           as calcEconomischeVoorraad,
    0.0                                           as calcMaximumVoorraad,
    0.0                                           as calcMinimumVoorraad,
    calcEconomischeVoorraad - calcMinimumVoorraad as calcReserveVoorraad
  from
  ( // Aantal in productie (Eindproduct) bepalen
    select
      vwPrdOkGid                 vwPrdOkGid,
      null                       vwPrdOcGid,
      vwPrdOeGid                 vwPrdOeGid,
      vwArtGid                   vwArtGid,
      vwMagGid                   vwMagGid,
      vwLocGid                   vwLocGid,
      vwArtPartijGid             vwArtPartijGid,
      vwArtSerieGid              vwArtSerieGid,
      vwPrdOesOrrGid             vwPrdOesOrrGid,
      vwPrdDatum                 vwPrdDatum,
      0                          vwMaxSpec,
      0.0                        vwGereserveerdProductie,
      sum(vwAantalEindProductie) vwAantalEindProductie,
      sum(vwAantalEindProductieNogTeProduceren) vwAantalEindProductieNogTeProduceren
    from (
          // Aantal 'In Productie' (Eindproduct) van productieorderregel
          select
            PrdOkGid          as vwPrdOkGid,
            PrdOeGid          as vwPrdOeGid,
            Art.ArtGid        as vwArtGid,
            Mag.MagGid        as vwMagGid,
            PrdOeLocGid       as vwLocGid,
            PrdOeArtPartijGid as vwArtPartijGid,
            null              as vwArtSerieGid,
            null              as vwPrdOesOrrGid,
            IsNull (PrdOkProductieStartOp, PrdOkTeProducerenVoor) as vwPrdDatum,
            IsNull((select sum(greater(PrdOesAantalDezeVerwerking, (PrdOesAantalTotaalTeVerwerken - PrdOesAantalUitvalInDezeVerwerking - PrdOesAantalReedsVerwerkt))) from tabProductieOrderEindProductSpec where  PrdOesPrdOeGid = PrdOeGid), 0.0) as vwMaxSpec,
            PrdOeAantalTotaalTeVerwerken - PrdOeAantalReedsVerwerkt NogTeVerwerkenOpRegel,
            (if vwMaxSpec >=  NogTeVerwerkenOpRegel then 0 else NogTeVerwerkenOpRegel - vwMaxSpec  endif) as vwAantalEindProductie,
            vwAantalEindProductie vwAantalEindProductieNogTeProduceren
            from tabProductieOrderEindProduct
            inner join tabProductieOrderKop on (PrdOePrdOkGid = PrdOkGid and PrdOkStatus in (2,3))
            inner join tabMagazijn Mag on (Mag.MagGid = PrdOeMagGid)
            inner join tabArtikel Art on (Art.ArtGid = PrdOeArtGid)
            where
              locate(@SkipPartsToCalculate, 'E') = 0
              and ArtSoort = 2
              and vwArtGid = @ArtGid
              and (@MagGid is null or vwMagGid = @MagGid)
              and (@LocGid is null or vwLocGid = @LocGid)
              and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
              and vwAantalEindProductie <> 0.00

          union all

          // Aantal 'In Productie' (Eindproduct) van productieorderspecificatieregel (dat is dus excl. uitval!)
          select
            PrdOkGid            as vwPrdOkGid,
            PrdOeGid            as vwPrdOeGid,
            PrdOeArtGid         as vwArtGid,
            if (PrdOesSoort = 0) then PrdOesMagGid else (select orrMagGid from tabOrderRegel where orrGid = PrdOesOrrGid) endif  as vwMagGid,
            if (PrdOesSoort = 0) then PrdOesLocGid else (select isNull(ArtMagDefaultLocGid, (select LocGid
                                                                                             from tabLocatie
                                                                                             where locMagGid = vwMagGid
                                                                                             and LocNaam = '(Standaard)'))
                                                         from tabArtikelMagazijn
                                                         where  ArtMagArtGid = @ArtGid and ArtMagMagGid = vwMagGid) endif  as vwLocGid,
            PrdOesArtPartijGid  as vwArtPartijGid,
            PrdOesArtSerieGid   as vwArtSerieGid,
            PrdOesOrrGid        as vwPrdOesOrrGid,
            IsNull (PrdOkProductieStartOp, PrdOkTeProducerenVoor) as vwPrdDatum,
            0                   as vwMaxSpec,
            0 NogTeVerwerkenOpRegel, // Niet van toepassing
            (PrdOesAantalTotaalTeVerwerken - PrdOesAantalUitvalInDezeVerwerking) vwAantalEindProductie,
            greater(PrdOesAantalDezeVerwerking, (PrdOesAantalTotaalTeVerwerken - PrdOesAantalUitvalInDezeVerwerking - PrdOesAantalReedsVerwerkt)) vwAantalEindProductieNogTeProduceren

            from
              tabProductieOrderEindProduct
              inner join tabProductieOrderKop on (PrdOePrdOkGid = PrdOkGid and PrdOkStatus in (2,3))
              left outer join tabProductieOrderEindProductSpec on (PrdOesPrdOeGid = PrdOeGid) //and (PrdOesOrrGid is null)
            //group by PrdOkGid, PrdOeGid, PrdOeArtGid, PrdOesMagGid, PrdOesLocGid, prdOesArtPartijGid, PrdOesArtSerieGid, vwPrdDatum, PrdOesOrrGid, PrdOesSoort
            where
              locate(@SkipPartsToCalculate, 'F') = 0
              and (@MagGid is null or vwMagGid = @MagGid)
              and (@LocGid is null or vwLocGid = @LocGid)
              and vwArtGid = @ArtGid
              and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    ) tbInEindProductie
    group by vwPrdOkGid, vwPrdOeGid, vwArtGid, vwMagGid, vwLocGid, vwArtPartijGid, vwArtSerieGid, vwPrdOesOrrGid, vwPrdDatum

    union all

    // Reserveringen voor productie orders, van componentspecificatieregel
    select
      PrdOkGid              as vwPrdOkGid,
      PrdOcGid              as vwPrdOcGid,
      null                  as vwPrdOeGid,
      PrdOcArtGid           as vwArtGid,
      PrdOcsMagGid          as vwMagGid,
      PrdOcsLocGid          as vwLocGid,
      PrdOcsArtPartijGid    as vwArtPartijGid,
      PrdOcsArtSerieGid     as vwSerieGid,
      null                  as vwPrdOesOrrGid,
      IsNull (PrdOkProductieStartOp, PrdOkTeProducerenVoor) as vwPrdDatum,
      0                     as vwMaxSpec,
      sum(PrdOcsAantalDezeVerwerking) as vwGereserveerdProductie,
      0.00                  as vwAantalEindProductie,
      0.00                  as vwAantalEindProductieNogTeProduceren
    from
      tabProductieOrderComponentSpec
      inner join tabProductieOrderComponent on PrdOcGid = PrdOcsPrdOcGid
      inner join tabProductieOrderKop on PrdOkGid = PrdOcPrdOkGid and PrdOkStatus in (2,3)
    where
      locate(@SkipPartsToCalculate, 'H') = 0
      and ((PrdOcsAantalDezeVerwerking) <> 0)
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    group by
      vwPrdOkGid, PrdOcGid, PrdOcArtGid, PrdOcsMagGid, PrdOcsLocGid, PrdOcsArtPartijGid, PrdOcsArtSerieGid, vwPrdDatum
    having
     (vwGereserveerdProductie <> 0 )

    union all

    // Reserveringen voor productie orders, van componentregel
    select
      PrdOkGid             as vwPrdOkGid,
      PrdOcGid             as vwPrdOcGid,
      null                 as vwPrdOeGid,
      PrdOcArtGid          as vwArtGid,
      PrdOcMagGid          as vwMagGid,
      PrdOcLocGid          as vwLocGid,
      PrdOcArtPartijGid    as vwArtPartijGid,
      null                 as vwArtSerieGid,
      null                 as vwPrdOesOrrGid,
      IsNull (PrdOkProductieStartOp, PrdOkTeProducerenVoor) as vwPrdDatum,
      IsNull((select sum(PrdOcsAantalDezeVerwerking) from tabProductieOrderComponentSpec where PrdOcsPrdOcGid = PrdOcGid), 0.0) as vwMaxSpec,
      (if ((PrdOcAantalTotaalTeVerwerken - IsNull(PrdOcAantalReedsVerwerkt,0.0)+IsNull(PrdOcAantalUitvalInReedsVerwerkt,0.0)) -vwMaxSpec) > 0 then
                       (PrdOcAantalTotaalTeVerwerken - IsNull(PrdOcAantalReedsVerwerkt,0.0)+IsNull(PrdOcAantalUitvalInReedsVerwerkt,0.0)) -vwMaxSpec
                  else 0.0 endif) as vwGereserveerdProductie,
       0.0 as vwAantalEindProductie,
      0.00                  as vwAantalEindProductieNogTeProduceren
    from
      tabProductieOrderComponent
      inner join tabProductieOrderKop on PrdOkGid = PrdOcPrdOkGid and PrdOkStatus in (2,3)
    where
      locate(@SkipPartsToCalculate, 'G') = 0
      //ACW 17-08-2016 #49309 -  Alleen artikelen teruggeven!
      and PrdOcRegelSoort = 2 /*Artikelen*/
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    group by
      PrdOkGid, PrdOcGid, PrdOcArtGid, PrdOcMagGid, PrdOcLocGid, PrdOcArtPartijGid, vwPrdOesOrrGid,vwPrdDatum, PrdOcAantalReedsVerwerkt, PrdOcAantalTotaalTeVerwerken, PrdOcAantalUitvalInReedsVerwerkt
    having
     (vwGereserveerdProductie <> 0 )
  ) tbProductie
  group by
    calcPrdOkGid,
    calcPrdOcGid,
    calcPrdOeGid,
    calcArtGid,
    calcMagGid,
    calcLocGid,
    calcArtPartijGid,
    calcArtSerieGid,
    calcVvorGid,
    vwPrdOesOrrGid,
    calcDatum

union all // Projectmutaties

  // ***********************************
  // ********* Projectmutaties *********
  // ***********************************
  select
    3                                                   as calcResRegelSoort,
    tbProjecten.vwNawGid                                as calcNawGid,
    null                                                as calcOrkGid,
    null                                                as calcOrrGid,
    null                                                as calcPrdOkGid,
    null                                                as calcPrdOcGid,
    null                                                as calcPrdOeGid,
    tbProjecten.vwPbkGid                                as calcPbkGid,
    tbProjecten.vwPbrGid                                as calcPbrGid,
    null                                                as calcPwbkGid,
    null                                                as calcPwbrGid,
    null                                                as calcBstKopGid,
    null                                                as calcBstRglGid,
    null                                                as calcMokGid,
    null                                                as calcMagOntGid,
    tbProjecten.vwArtGid                                as calcArtGid,
    tbProjecten.vwMagGid                                as calcMagGid,
    tbProjecten.vwLocGid                                as calcLocGid,
    tbProjecten.vwArtPartijGid                          as calcArtPartijGid,
    tbProjecten.vwSerieGid                              as calcArtSerieGid,
    null                                                as calcVvorGid,
    tbProjecten.vwMutatieDatum                          as calcDatum,
    0.0                                                 as calcAantalBesteld,
    0.0                                                 as calcAantalGeleverd,
    0.0                                                 as calcAantalLeveringConcept,
    0.0                                                 as calcAantalLeveringGoedgek,
    0.0                                                 as calcAantalLeveringGoedgekVrijgegeven,
    0.0                                                 as calcAantalLevering,
    0.0                                                 as calcAantalBackorderConcept,
    0.0                                                 as calcAantalBackorderGoedgek,
    0.0                                                 as calcAantalBackorder,
    0.0                                                 as calcAantalBackorderDirecteInkoopConcept,
    0.0                                                 as calcAantalBackorderDirecteInkoopGoedgek,
    0.0                                                 as calcAantalBackorderDirecteInkoop,
    0.0                                                 as calcAantalBackorderProductieConcept,
    0.0                                                 as calcAantalBackorderProductieGoedgek,
    0.0                                                 as calcAantalBackorderProductie,
    (calcGereserveerdProjectOnderhanden+calcGereserveerdProjectVoorbereid) as calcGereserveerdTotaal,
    0.0                                                 as calcGereserveerdBackorderConcept,
    0.0                                                 as calcGereserveerdBackorderGoedgek,
    0.0                                                 as calcGereserveerdBackorder,
    0.0                                                 as calcGereserveerdLeveringConcept,
    0.0                                                 as calcGereserveerdLeveringGoedgek,
    0.0                                                 as calcGereserveerdLevering,
    sum(tbProjecten.vwGereserveerdProjectOnderhanden)   as calcGereserveerdProjectOnderhanden,
    sum(tbProjecten.vwGereserveerdProjectVoorbereid)    as calcGereserveerdProjectVoorbereid,
    0.0                                                 as calcGereserveerdVoorraadverplaatsing,
    0.0                                                 as calcGereserveerdProductie,
    0.0                                                 as calcInEindProductie,
    0.0                                                 as calcInBestellingConcept,
    0.0                                                 as calcInBestellingGoedgek,
    0.0                                                 as calcInBestellingVerwerkt,
    0.0                                                 as calcInBestellingDirecteInkoop,
    0.0                                                 as calcInVerkoopOrderProductie,
    0.0                                                 as calcInVoorraadVerplaatsingen,
    0.0                                                 as calcInBestellingVoorEconomischeVoorraad,
    0.0                                                 as calcInMagOntvangst,
    0.0                                                 as calcInMagOntvangstDirecteInkoop,
    0.0                                                 as calcMagazijnVoorraad,
    -calcGereserveerdTotaal                             as calcVrijeVoorraad,
    calcVrijeVoorraad                                   as calcBeschikbareVoorraad,
    calcVrijeVoorraad                                   as calcEconomischeVoorraad,
    0.0                                                 as calcMaximumVoorraad,
    0.0                                                 as calcMinimumVoorraad,
    calcEconomischeVoorraad - calcMinimumVoorraad       as calcReserveVoorraad
  from
  (  // Reserveringen voor projectmutaties, van specificatieregel
    select
      ProjNawGid                as vwNawGid,
      PbkGid                    as vwPbkGid,
      PbrGid                    as vwPbrGid,
      PbrArtGid                 as vwArtGid,
      PbrMagGid                 as vwMagGid,
      PbrLocGid                 as vwLocGid,
      PbrArtPartijGid           as vwArtPartijGid,
      PbrdArtSerieGid           as vwSerieGid,
      PbrMutatieDatum           as vwMutatieDatum,
      0                         as MaxSpec,
      sum(PbrdAantal)           as vwGereserveerdProjectOnderhanden,
      0.0                       as vwGereserveerdProjectVoorbereid
    from
      tabProjectBoekingsRegelDetail
      inner join tabProjectBoekingsRegel on (PbrGid = PbrdPbrGid) and (PbrMutSoort = 2) and (PbrStatus in (0,1,2)) and (PbrIsDirecteInkoop = 0)
      inner join tabProjectBoekingsKop on PbkGid = PbrPbkGid
      inner join tabProject on ProjGid = PbrProjGid
    where
      locate(@SkipPartsToCalculate, 'J') = 0
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    group by
      ProjNawGid, PbkGid, PbrGid, PbrArtGid, PbrMagGid, PbrLocGid, PbrArtPartijGid, PbrdArtSerieGid, PbrMutatieDatum

    union all

    // Reserveringen voor projectmutaties, van boekingsregel
    select
      ProjNawGid         as vwNawGid,
      PbkGid             as vwPbkGid,
      PbrGid             as vwPbrGid,
      PbrArtGid          as vwArtGid,
      PbrMagGid          as vwMagGid,
      PbrLocGid          as vwLocGid,
      PbrArtPartijGid    as vwArtPartijGid,
      null               as vwSerieGid,
      PbrMutatieDatum    as vwMutatieDatum,
      IsNull((select sum(PbrdAantal) from tabProjectBoekingsRegelDetail where PbrdPbrGid = PbrGid), 0.0) as MaxSpec,
      if (PbrAantalGeboekt - MaxSpec) > 0 then
                       (PbrAantalGeboekt) - MaxSpec
                  else 0.0 endif as vwGereserveerdProjectOnderhanden,
      0.0                as vwGereserveerdProjectVoorbereid
    from
      tabProjectBoekingsRegel
      inner join tabProjectBoekingsKop on PbkGid = PbrPbkGid
      inner join tabProject on ProjGid = PbrProjGid
    where
      locate(@SkipPartsToCalculate, 'I') = 0
      and PbrMutSoort = 2
      and PbrStatus in (0,1,2)
      and PbrIsDirecteInkoop = 0
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    group by
      ProjNawGid, PbkGid, PbrGid, PbrArtGid, PbrMagGid, PbrLocGid, PbrArtPartijGid, PbrAantalGeboekt, PbrMutatieDatum
  ) tbProjecten
  group by
    vwNawGid,
    vwPbkGid,
    vwPbrGid,
    vwArtGid,
    vwMagGid,
    vwLocGid,
    vwArtPartijGid,
    vwSerieGid,
    vwMutatieDatum
  having
    (calcGereserveerdProjectOnderhanden <> 0)

union all // Projectwerkbonnen

  // ***********************************
  // ******* Projectwerkbonnen *********
  // ***********************************
  select
    4                                                   as calcResRegelSoort,
    tbProjWerkbonnen.vwNawGid                           as calcNawGid,
    null                                                as calcOrkGid,
    null                                                as calcOrrGid,
    null                                                as calcPrdOkGid,
    null                                                as calcPrdOcGid,
    null                                                as calcPrdOeGid,
    null                                                as calcPbkGid,
    null                                                as calcPbrGid,
    tbProjWerkbonnen.vwPwbkGid                          as calcPwbkGid,
    tbProjWerkbonnen.vwPwbrGid                          as calcPwbrGid,
    null                                                as calcBstKopGid,
    null                                                as calcBstRglGid,
    null                                                as calcMokGid,
    null                                                as calcMagOntGid,
    tbProjWerkbonnen.vwArtGid                           as calcArtGid,
    tbProjWerkbonnen.vwMagGid                           as calcMagGid,
    tbProjWerkbonnen.vwLocGid                           as calcLocGid,
    tbProjWerkbonnen.vwArtPartijGid                     as calcArtPartijGid,
    tbProjWerkbonnen.vwSerieGid                         as calcArtSerieGid,
    null                                                as calcVvorGid,
    tbProjWerkbonnen.vwDatum                            as calcDatum,
    0.0                                                 as calcAantalBesteld,
    0.0                                                 as calcAantalGeleverd,
    0.0                                                 as calcAantalLeveringConcept,
    0.0                                                 as calcAantalLeveringGoedgek,
    0.0                                                 as calcAantalLeveringGoedgekVrijgegeven,
    0.0                                                 as calcAantalLevering,
    0.0                                                 as calcAantalBackorderConcept,
    0.0                                                 as calcAantalBackorderGoedgek,
    0.0                                                 as calcAantalBackorder,
    0.0                                                 as calcAantalBackorderDirecteInkoopConcept,
    0.0                                                 as calcAantalBackorderDirecteInkoopGoedgek,
    0.0                                                 as calcAantalBackorderDirecteInkoop,
    0.0                                                 as calcAantalBackorderProductieConcept,
    0.0                                                 as calcAantalBackorderProductieGoedgek,
    0.0                                                 as calcAantalBackorderProductie,
    (calcGereserveerdProjectOnderhanden+calcGereserveerdProjectVoorbereid) as calcGereserveerdTotaal,
    0.0                                                 as calcGereserveerdBackorderConcept,
    0.0                                                 as calcGereserveerdBackorderGoedgek,
    0.0                                                 as calcGereserveerdBackorder,
    0.0                                                 as calcGereserveerdLeveringConcept,
    0.0                                                 as calcGereserveerdLeveringGoedgek,
    0.0                                                 as calcGereserveerdLevering,
    sum(tbProjWerkbonnen.vwGereserveerdProjectOnderhanden) as calcGereserveerdProjectOnderhanden,
    sum(tbProjWerkbonnen.vwGereserveerdProjectVoorbereid)  as calcGereserveerdProjectVoorbereid,
    0.0                                                 as calcGereserveerdVoorraadverplaatsing,
    0.0                                                 as calcGereserveerdProductie,
    0.0                                                 as calcInEindProductie,
    0.0                                                 as calcInBestellingConcept,
    0.0                                                 as calcInBestellingGoedgek,
    0.0                                                 as calcInBestellingVerwerkt,
    0.0                                                 as calcInBestellingDirecteInkoop,
    0.0                                                 as calcInVerkoopOrderProductie,
    0.0                                                 as calcInVoorraadVerplaatsingen,
    0.0                                                 as calcInBestellingVoorEconomischeVoorraad,
    0.0                                                 as calcInMagOntvangst,
    0.0                                                 as calcInMagOntvangstDirecteInkoop,
    0.0                                                 as calcMagazijnVoorraad,
    -calcGereserveerdTotaal                             as calcVrijeVoorraad,
    calcVrijeVoorraad                                   as calcBeschikbareVoorraad,
    calcVrijeVoorraad                                   as calcEconomischeVoorraad,
    0.0                                                 as calcMaximumVoorraad,
    0.0                                                 as calcMinimumVoorraad,
    calcEconomischeVoorraad - calcMinimumVoorraad       as calcReserveVoorraad
  from
  (  // Reserveringen voor werkbonnen, van specificatieregel
    select
      ProjNawGid                as vwNawGid,
      PwbkGid                   as vwPwbkGid,
      PwbrGid                   as vwPwbrGid,
      PwbrArtGid                as vwArtGid,
      PwbrMagGid                as vwMagGid,
      PwbrLocGid                as vwLocGid,
      PwbrArtPartijGid          as vwArtPartijGid,
      PwbdArtSerieGid           as vwSerieGid,
      PwbkUitvoerenOp           as vwDatum,
      0                         as MaxSpec,
      sum(if PwbkStatus = 2 then PwbdAantal else 0.0 endif) as vwGereserveerdProjectOnderhanden,
      sum(if PwbkStatus = 1 then PwbdAantal else 0.0 endif) as vwGereserveerdProjectVoorbereid
    from
      tabProjectWerkbonRegelDetail
      inner join tabProjectWerkbonRegel on (PwbrGid = PwbdPwbrGid) and (PwbrMutSoort = 2) and (PwbrIsDirecteInkoop = 0)
      inner join tabProjectWerkbonKop on PwbkGid = PwbrPwbkGid
      inner join tabProject on ProjGid = PwbkProjGid
    where
      locate(@SkipPartsToCalculate, 'L') = 0
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    group by
      vwNawGid, vwPwbkGid, vwPwbrGid, vwArtGid, vwMagGid, vwLocGid, vwArtPartijGid, vwSerieGid, PwbdPwbrGid, PwbkUitvoerenOp, PwbkStatus

    union all

    // Reserveringen voor werkbonnen, van werkbonregel
    select
      ProjNawGid                as vwNawGid,
      PwbkGid                   as vwPwbkGid,
      PwbrGid                   as vwPwbrGid,
      PwbrArtGid                as vwArtGid,
      PwbrMagGid                as vwMagGid,
      PwbrLocGid                as vwLocGid,
      PwbrArtPartijGid          as vwArtPartijGid,
      null                      as vwSerieGid,
      PwbkUitvoerenOp           as vwDatum,
      IsNull((select sum(PwbdAantal) from tabProjectWerkbonRegelDetail where PwbdPwbrGid = PwbrGid),0.0) as MaxSpec,
      if PwbkStatus = 2 and PwbkIsVoorraadGereserveerd = 1 and (IsNull(PwbrAantalGeboekt,0.0) - MaxSpec) > 0 then
        IsNull(PwbrAantalGeboekt,0.0) - MaxSpec
      else
        0.0
      endif  as vwGereserveerdProjectOnderhanden,
      if PwbkStatus = 1 and PwbkIsVoorraadGereserveerd = 1 and (IsNull(PwbrAantalGeboekt,0.0) - MaxSpec) > 0 then
        IsNull(PwbrAantalGeboekt,0.0) - MaxSpec
      else
        0.0
      endif  as vwGereserveerdProjectVoorbereid
    from
      tabProjectWerkbonRegel
      inner join tabProjectWerkbonKop on PwbkGid = PwbrPwbkGid
      inner join tabProject on ProjGid = PwbkProjGid
    where
      locate(@SkipPartsToCalculate, 'K') = 0
      and PwbrMutSoort = 2
      and PwbrIsDirecteInkoop = 0
      and vwArtGid = @ArtGid
      and (@MagGid is null or vwMagGid = @MagGid)
      and (@LocGid is null or vwLocGid = @LocGid)
      and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
    group by
      vwNawGid, vwPwbkGid, vwPwbrGid, vwArtGid, vwMagGid, vwLocGid, vwArtPartijGid, vwSerieGid, vwDatum, PwbrAantalGeboekt, PwbkIsVoorraadGereserveerd, PwbkStatus
  ) tbProjWerkbonnen
  group by
    vwNawGid,
    vwPwbkGid,
    vwPwbrGid,
    vwArtGid,
    vwMagGid,
    vwLocGid,
    vwArtPartijGid,
    vwSerieGid,
    vwDatum
  having
    (calcGereserveerdProjectOnderhanden <> 0) or
    (calcGereserveerdProjectVoorbereid  <> 0)

union all // Bestellingen

  // ***********************************
  // ********* Bestellingen ************
  // ***********************************
  //ACW 12-03-2009 project Directe inkoop nu via tabBestelregelDetail
  select
    5                 as calcResRegelSoort,
    BstKopNawGid      as calcNawGid,
    null              as calcOrkGid,
    null              as calcOrrGid,
    null              as calcPrdOkGid,
    null              as calcPrdOcGid,
    null              as calcPrdOeGid,
    null              as calcPbkGid,
    null              as calcPbrGid,
    null              as calcPwbkGid,
    null              as calcPwbrGid,
    BstKopGid         as calcBstKopGid,
    BstRglGid         as calcBstRglGid,
    null              as calcMokGid,
    null              as calcMagOntGid,
    BstRglArtGid      as calcArtGid,
    (if (BstKopAfleverAdres = 1 and brdOrrGid is not null) then OrrMagGid else BstKopMagGid endif) as calcMagGid,
    null              as calcLocGid,
    BstRglArtPartijGid as calcArtPartijGid,
    null              as calcArtSerieGid,
    null              as calcVvorGid,
    IsNull (BstRglAfleverdatum, BstKopAfleverDatum, BstKopBestelDatum) as calcDatum,
    0.0               as calcAantalBesteld,
    0.0               as calcAantalGeleverd,
    0.0               as calcAantalLeveringConcept,
    0.0               as calcAantalLeveringGoedgek,
    0.0               as calcAantalLeveringGoedgekVrijgegeven,
    0.0               as calcAantalLevering,
    0.0               as calcAantalBackorderConcept,
    0.0               as calcAantalBackorderGoedgek,
    0.0               as calcAantalBackorder,
    0.0               as calcAantalBackorderDirecteInkoopConcept,
    0.0               as calcAantalBackorderDirecteInkoopGoedgek,
    0.0               as calcAantalBackorderDirecteInkoop,
    0.0               as calcAantalBackorderProductieConcept,
    0.0               as calcAantalBackorderProductieGoedgek,
    0.0               as calcAantalBackorderProductie,
    0.0               as calcGereserveerdTotaal,
    0.0               as calcGereserveerdBackorderConcept,
    0.0               as calcGereserveerdBackorderGoedgek,
    0.0               as calcGereserveerdBackorder,
    0.0               as calcGereserveerdLeveringConcept,
    0.0               as calcGereserveerdLeveringGoedgek,
    0.0               as calcGereserveerdLevering,
    0.0               as calcGereserveerdProjectOnderhanden,
    0.0               as calcGereserveerdProjectVoorbereid,
    0.0               as calcGereserveerdVoorraadverplaatsing,
    0.0               as calcGereserveerdProductie,
    0.0               as calcInEindProductie,
    // Nog te ontvangen hier gebruiken en niet het verschil tussen aantal besteld en ontvangen,
    // omdat men een deel kan laten vervallen.
    // Bijgevolg kan een bestelling dus volledig afgehandeld zijn,
    // maar dat er wel verschil is tussen aantal besteld en ontvangen.
    //ACW 12-03-2009: Test op brdOrrGid, want als ingevuld, dan is het een directe inkoop!
    (if brdOrrGid is null and BstKopIsGoedgekeurd = 0                              then sum(brdAantalNogTeOntvangen)   else 0.00 endif) as calcInBestellingConcept,
    (if brdOrrGid is null and (BstKopIsGoedgekeurd = 1) and (BstKopIsVerwerkt = 0) then sum(brdAantalNogTeOntvangen)   else 0.00 endif) as calcInBestellingGoedgek,
    (if brdOrrGid is null and (BstKopIsVerwerkt = 1)                               then sum(brdAantalNogTeOntvangen)   else 0.00 endif) as calcInBestellingVerwerkt,
    (if brdOrrGid is not null                                                      then sum(brdAantalNogTeOntvangen)   else 0.00 endif) as calcInBestellingDirecteInkoop,
    0.0                                                                                                                                 as calcInVerkoopOrderProductie,
    0.0                                                                                                                                 as calcInVoorraadVerplaatsingen,
    ((if ArtVastBestellingConceptInEcoVrd  = 1 then calcInBestellingConcept else 0.0 endif) +
     (if ArtVastBestellingGoedgekInEcoVrd  = 1 then calcInBestellingGoedgek else 0.0 endif) +
     (if ArtVastBestellingVerwerktInEcoVrd = 1 then calcInBestellingVerwerkt else 0.0 endif)) as calcInBestellingVoorEconomischeVoorraad,
    0.0               as calcInMagOntvangst,
    0.0               as calcInMagOntvangstDirecteInkoop,
    0.0               as calcMagazijnVoorraad,
    0.0               as calcVrijeVoorraad,
    0.0               as calcBeschikbareVoorraad,
    calcInBestellingVoorEconomischeVoorraad as calcEconomischeVoorraad,
    0.0               as calcMaximumVoorraad,
    0.0               as calcMinimumVoorraad,
    calcEconomischeVoorraad - calcMinimumVoorraad  as calcReserveVoorraad
  from
    tabArtikelVasteGegevens,
    tabBestelKop
    inner join tabBestelRegel       on (BstRglBstKopGid = BstKopGid)
    inner join tabBestelRegelDetail on (brdBstRglGid    = BstRglGid and brdAantalNogTeOntvangen <> 0)
    left outer join tabOrderRegel   on (OrrGid          = brdOrrGid)
  where
    locate(@SkipPartsToCalculate, 'M') = 0
    and ArtVastSoort = 2
    and BstRglSoort  = 2
    and calcArtGid = @ArtGid
    and (@MagGid is null or calcMagGid = @MagGid)
    and (@LocGid is null or calcLocGid = @LocGid)
    and (@ArtPartijGid is null or calcArtPartijGid = @ArtPartijGid)
  group by
    BstKopGid, BstRglGid, BstKopNawGid, BstRglArtGid, BstRglArtPartijGid, BstKopMagGid, OrrMagGid, calcDatum, BstKopIsGoedgekeurd, BstKopIsVerwerkt,
    BstRglAantalNogTeOntvangenInVoorrEenh, ArtVastBestellingConceptInEcoVrd, ArtVastBestellingGoedgekInEcoVrd, ArtVastBestellingVerwerktInEcoVrd,
    BstRglVoorraadEenhedenInInkoopEenheid, brdOrrGid, BstKopAfleverAdres

union all // MagazijnOntvangsten

  // ***********************************
  // ******* MagazijnOntvangsten *******
  // ***********************************
  // aantal in magazijnontvangsten, we kunne uitgaan van de specregels omdat deze altijd gelijk lopen aan de hoofdregel
  select
    6                                                                 as calcResRegelSoort,
    MokNawGid                                                         as calcNawGid,
    null                                                              as calcOrkGid,
    null                                                              as calcOrrGid,
    null                                                              as calcPrdOkGid,
    null                                                              as calcPrdOcGid,
    null                                                              as calcPrdOeGid,
    null                                                              as calcPbkGid,
    null                                                              as calcPbrGid,
    null                                                              as calcPwbkGid,
    null                                                              as calcPwbrGid,
    null                                                              as calcBstKopGid,
    null                                                              as calcBstRglGid,
    MokGid                                                            as calcMokGid,
    MagOntGid                                                         as calcMagOntGid,
    MagOntArtGid                                                      as calcArtGid,
    (if (MokSoort = 1 and MagOntDetOrrGid is not null) then (select OrrMagGid  from tabOrderRegel where (OrrGid = MagOntDetOrrGid)) else MokMagGid endif) as calcMagGid,
    MagOntLocLocGid                                                   as calcLocGid,
    MagOntArtPartijGid                                                as calcArtPartijGid,
    MagOntLocArtSerieGid                                              as calcArtSerieGid,
    null                                                              as calcVvorGid,
    MokOntvangstDatum                                                 as calcDatum,
    0.0                                                               as calcAantalBesteld,
    0.0                                                               as calcAantalGeleverd,
    0.0                                                               as calcAantalLeveringConcept,
    0.0                                                               as calcAantalLeveringGoedgek,
    0.0                                                               as calcAantalLeveringGoedgekVrijgegeven,
    0.0                                                               as calcAantalLevering,
    0.0                                                               as calcAantalBackorderConcept,
    0.0                                                               as calcAantalBackorderGoedgek,
    0.0                                                               as calcAantalBackorder,
    0.0                                                               as calcAantalBackorderDirecteInkoopConcept,
    0.0                                                               as calcAantalBackorderDirecteInkoopGoedgek,
    0.0                                                               as calcAantalBackorderDirecteInkoop,
    0.0                                                               as calcAantalBackorderProductieConcept,
    0.0                                                               as calcAantalBackorderProductieGoedgek,
    0.0                                                               as calcAantalBackorderProductie,
    0.0                                                               as calcGereserveerdTotaal,
    0.0                                                               as calcGereserveerdBackorderConcept,
    0.0                                                               as calcGereserveerdBackorderGoedgek,
    0.0                                                               as calcGereserveerdBackorder,
    0.0                                                               as calcGereserveerdLeveringConcept,
    0.0                                                               as calcGereserveerdLeveringGoedgek,
    0.0                                                               as calcGereserveerdLevering,
    0.0                                                               as calcGereserveerdProjectOnderhanden,
    0.0                                                               as calcGereserveerdProjectVoorbereid,
    0.0                                                               as calcGereserveerdVoorraadverplaatsing,
    0.0                                                               as calcGereserveerdProductie,
    0.0                                                               as calcInEindProductie,
    0.0                                                               as calcInBestellingConcept,
    0.0                                                               as calcInBestellingGoedgek,
    0.0                                                               as calcInBestellingVerwerkt,
    0.0                                                               as calcInBestellingDirecteInkoop,
    0.0                                                               as calcInVerkoopOrderProductie,
    0.0                                                               as calcInVoorraadVerplaatsingen,
    0.0                                                               as calcInBestellingVoorEconomischeVoorraad,
    sum(if (brdOrrGid is null and MagOntDetOrrGid is null) then MagOntLocAantal else 0.0 endif)     as calcInMagOntvangst,
    //Veld hieronder aan zetten zodra in infoschermen de directe inkoop apart wordt getoond
    sum(if (brdOrrGid is not null) or (MagOntDetbrdGid is null and MagOntDetOrrGid is not null) then MagOntLocAantal else 0.0 endif) as calcInMagOntvangstDirecteInkoop,
    0.0                                                               as calcMagazijnVoorraad,
    0.0                                                               as calcVrijeVoorraad,
    0.0                                                               as calcBeschikbareVoorraad,
    calcInMagOntvangst                                                as calcEconomischeVoorraad,
    0.0                                                               as calcMaximumVoorraad,
    0.0                                                               as calcMinimumVoorraad,
    calcEconomischeVoorraad - calcMinimumVoorraad                     as calcReserveVoorraad
  from
    tabMagazijnOntvangstLocatieSerie
    inner join tabMagazijnOntvangstenDetail on MagOntDetGid = MagOntLocMagOntDetGid
    inner join tabMagazijnOntvangsten on MagOntGid = MagOntDetMagOntGid
    inner join tabMagazijnOntvangstenKop on MokGid = MagOntMokGid
    left outer join tabBestelRegelDetail on (brdGid = MagOntDetBrdGid)
  where
    locate(@SkipPartsToCalculate, 'N') = 0
    and calcArtGid = @ArtGid
    and (@MagGid is null or calcMagGid = @MagGid)
    and (@LocGid is null or calcLocGid = @LocGid)
    and (@ArtPartijGid is null or calcArtPartijGid = @ArtPartijGid)
  group by
    MokGid, MagOntGid, MokNawGid, MokMagGid, calcMagGid, MagOntLocLocGid, MagOntArtGid, MagOntArtPartijGid, MagOntLocArtSerieGid, MokOntvangstDatum, MokSoort, MagOntDetOrrGid
  having
    (calcInMagOntvangst <> 0) or (calcInMagOntvangstDirecteInkoop <> 0)

union all // Magazijnvoorraden

  // ***********************************
  // ******** Magazijnvoorraden ********
  // ***********************************
  select
    7                                     as calcResRegelSoort,
    null                                  as calcNawGid,
    null                                  as calcOrkGid,
    null                                  as calcOrrGid,
    null                                  as calcPrdOkGid,
    null                                  as calcPrdOcGid,
    null                                  as calcPrdOeGid,
    null                                  as calcPbkGid,
    null                                  as calcPbrGid,
    null                                  as calcPwbkGid,
    null                                  as calcPwbrGid,
    null                                  as calcBstKopGid,
    null                                  as calcBstRglGid,
    null                                  as calcMokGid,
    null                                  as calcMagOntGid,
    tbArtMagazijn.vwArtGid                as calcArtGid,
    tbArtMagazijn.vwMagGid                as calcMagGid,
    tbArtMagazijn.vwLocGid                as calcLocGid,
    tbArtMagazijn.vwArtPartijGid          as calcArtPartijGid,
    null                                  as calcArtSerieGid,
    null                                  as calcVvorGid,
    null                                  as calcDatum,
    0.0                                   as calcAantalBesteld,
    0.0                                   as calcAantalGeleverd,
    0.0                                   as calcAantalLeveringConcept,
    0.0                                   as calcAantalLeveringGoedgek,
    0.0                                   as calcAantalLeveringGoedgekVrijgegeven,
    0.0                                   as calcAantalLevering,
    0.0                                   as calcAantalBackorderConcept,
    0.0                                   as calcAantalBackorderGoedgek,
    0.0                                   as calcAantalBackorder,
    0.0                                   as calcAantalBackorderDirecteInkoopConcept,
    0.0                                   as calcAantalBackorderDirecteInkoopGoedgek,
    0.0                                   as calcAantalBackorderDirecteInkoop,
    0.0                                   as calcAantalBackorderProductieConcept,
    0.0                                   as calcAantalBackorderProductieGoedgek,
    0.0                                   as calcAantalBackorderProductie,
    0.0                                   as calcGereserveerdTotaal,
    0.0                                   as calcGereserveerdBackorderConcept,
    0.0                                   as calcGereserveerdBackorderGoedgek,
    0.0                                   as calcGereserveerdBackorder,
    0.0                                   as calcGereserveerdLeveringConcept,
    0.0                                   as calcGereserveerdLeveringGoedgek,
    0.0                                   as calcGereserveerdLevering,
    0.0                                   as calcGereserveerdProjectOnderhanden,
    0.0                                   as calcGereserveerdProjectVoorbereid,
    0.0                                   as calcGereserveerdVoorraadverplaatsing,
    0.0                                   as calcGereserveerdProductie,
    0.0                                   as calcInEindProductie,
    0.0                                   as calcInBestellingConcept,
    0.0                                   as calcInBestellingGoedgek,
    0.0                                   as calcInBestellingVerwerkt,
    0.0                                   as calcInBestellingDirecteInkoop,
    0.0                                   as calcInVerkoopOrderProductie,
    0.0                                   as calcInVoorraadVerplaatsingen,
    0.0                                   as calcInBestellingVoorEconomischeVoorraad,
    0.0                                   as calcInMagOntvangst,
    0.0                                   as calcInMagOntvangstDirecteInkoop,
    sum(tbArtMagazijn.vwMagazijnVoorraad) as calcMagazijnVoorraad,
    calcMagazijnVoorraad                  as calcVrijeVoorraad,
    calcMagazijnVoorraad                  as calcBeschikbareVoorraad,
    calcMagazijnVoorraad                  as calcEconomischeVoorraad,
    sum(tbArtMagazijn.vwMaxVoorraad)      as calcMaximumVoorraad,
    sum(tbArtMagazijn.vwMinVoorraad)      as calcMinimumVoorraad,
    calcEconomischeVoorraad - calcMinimumVoorraad  as calcReserveVoorraad

  from
  (
   // Magazijngegevens (min/max voorraad)
   select
    ArtMagArtGid           as vwArtGid,
    ArtMagMagGid           as vwMagGid,
    null                   as vwLocGid,
    null                   as vwArtPartijGid,
    0.00                   as vwMagazijnVoorraad,
    ArtMagMaximumVoorraad  as vwMaxVoorraad,
    ArtMagMinimumVoorraad  as vwMinVoorraad
   from
    tabArtikelMagazijn
  where
    locate(@SkipPartsToCalculate, 'O') = 0
    and vwArtGid = @ArtGid
    and (@MagGid is null or vwMagGid = @MagGid)
    and (@LocGid is null or vwLocGid = @LocGid)
    and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)

   union all

   select
    // Voorraad per locatie niet-partij
    ArtMagArtGid          as vwArtGid,
    ArtMagMagGid          as vwMagGid,
    ArtLocLocGid          as vwLocGid,
    null                  as vwArtPartijGid,
    sum(ArtLocVoorraad)   as vwMagazijnVoorraad,
    0.0                   as vwMaxVoorraad,
    0.0                   as vwMinVoorraad
   from
    tabArtikelMagazijn
    inner join tabArtikelLocatie on (ArtLocArtMagGid = ArtMagGid and ArtLocPartijGid is null)
   where
    locate(@SkipPartsToCalculate, 'P') = 0
    and vwArtGid = @ArtGid
    and (@MagGid is null or vwMagGid = @MagGid)
    and (@LocGid is null or vwLocGid = @LocGid)
    and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid) // Moet er WEL staan, want als we een partij opvragen, dan niet de niet-partijvoorraden tonen!
   group by ArtMagArtGid, ArtMagMagGid, ArtLocLocGid

   union all

   select
    // Voorraad per partij per locatie
    ArtLocArtGid           as vwArtGid,
    ArtMagMagGid           as vwMagGid,
    ArtLocLocGid           as vwLocGid,
    ArtPartijGid           as vwArtPartijGid,
    sum(ArtLocVoorraad)    as vwMagazijnVoorraad,
    0.0                    as vwMaxVoorraad,
    0.0                    as vwMinVoorraad
   from
    tabArtikelMagazijn
    inner join tabArtikelLocatie on (ArtLocArtMagGid = ArtMagGid)
    inner join tabArtikelPartij on (ArtLocPartijGid = ArtPartijGid)
   where
    locate(@SkipPartsToCalculate, 'P') = 0
    and vwArtGid = @ArtGid
    and (@MagGid is null or vwMagGid = @MagGid)
    and (@LocGid is null or vwLocGid = @LocGid)
    and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
   group by ArtLocArtGid, ArtMagMagGid, ArtLocLocGid, ArtPartijGid
  ) tbArtMagazijn
  where
        vwArtGid = @ArtGid
    and (@MagGid is null or vwMagGid = @MagGid)
    and (@LocGid is null or vwLocGid = @LocGid)
    and (@ArtPartijGid is null or vwArtPartijGid = @ArtPartijGid)
  group by
    vwArtGid,
    vwMagGid,
    vwLocGid,
    vwArtPartijGid

union all

  // ******************************************************
  // ******** Voorraadverplaatsingsvoorstellen VAN ********
