    0.0                                   as calcGereserveerdBackorderGoedgek,
    0.0                                   as calcGereserveerdBackorder,
    0.0                                   as calcGereserveerdLeveringConcept,
    0.0                                   as calcGereserveerdLeveringGoedgek,
    0.0                                   as calcGereserveerdLevering,
    0.0                                   as calcGereserveerdProjectOnderhanden,
    0.0                                   as calcGereserveerdProjectVoorbereid,
    VvorAantalGereserveerdInVanLocInVrrdEenh as calcGereserveerdVoorraadverplaatsing,
    0.0                                   as calcGereserveerdProductie,
    0.0                                   as calcInEindProductie,
    0.0                                   as calcInBestellingConcept,
    0.0                                   as calcInBestellingGoedgek,
    0.0                                   as calcInBestellingVerwerkt,
    0.0                                   as calcInBestellingDirecteInkoop,
    0.0                                   as calcInVerkoopOrderProductie,
    0.0                                   as calcInVoorraadVerplaatsingen,
    0.0                                   as calcInBestellingVoorEconomischeVoorraad,
    0.0                                   as calcInMagOntvangst,
    0.0                                   as calcInMagOntvangstDirecteInkoop,
    0.0                                   as calcMagazijnVoorraad,
    -VvorAantalGereserveerdInVanLocInVrrdEenh as calcVrijeVoorraad,
    -VvorAantalGereserveerdInVanLocInVrrdEenh as calcBeschikbareVoorraad,
    calcVrijeVoorraad                     as calcEconomischeVoorraad,
    0.0                                   as calcMaximumVoorraad,
    0.0                                   as calcMinimumVoorraad,
    calcEconomischeVoorraad - calcMinimumVoorraad  as calcReserveVoorraad
  from
    tabVoorraadVerplaatsingsOpdrachtRegel
  where
    locate(@SkipPartsToCalculate, #!#Q#!#) = 0
    and (@ArtGid is null or VvorArtGid = @ArtGid)
    and (@MagGid is null or VvorMagGidVan = @MagGid)
    and (@LocGid is null or VvorLocGidVan = @LocGid)
    and (@ArtPartijGid is null or VvorArtPartijGid = @ArtPartijGid)
    and (VvorStatus between 1 /*Klaar voor verplaatsen*/ and 8 /*net voor Verwerkt*/)
    and VvorAantalGereserveerdInVanLocInVrrdEenh <> 0

UNION ALL
  // *******************************************************
  // ******** Voorraadverplaatsingsvoorstellen NAAR ********
  // *******************************************************
  select
    15                                    as calcResRegelSoort,
    null                                  as calcNawGid,
    null                                  as calcOrkGid,
    null                                  as calcOrrGid,
    null                                  as calcPrdOkGid,
    null                                  as calcPrdOcGid,
    null                                  as calcPrdOeGid,
    null                                  as calcPbkGid,
    null                                  as calcPbrGid,
    null                                  as calcPwbkGid,
    null                                  as calcPwbrGid,
    null                                  as calcBstKopGid,
    null                                  as calcBstRglGid,
    null                                  as calcMokGid,
    null                                  as calcMagOntGid,
    VvorArtGid                            as calcArtGid,
    VvorMagGidNaar                        as calcMagGid,
    VvorLocGidNaar                        as calcLocGid,
    VvorArtPartijGid                      as calcArtPartijGid,
    null                                  as calcArtSerieGid,
    VvorGid                               as calcVvorGid,
    null                                  as calcDatum,
    0.0                                   as calcAantalBesteld,
    0.0                                   as calcAantalGeleverd,
    0.0                                   as calcAantalLeveringConcept,
    0.0                                   as calcAantalLeveringGoedgek,
    0.0                                   as calcAantalLeveringGoedgekVrijgegeven,
    0.0                                   as calcAantalLevering,
    0.0                                   as calcAantalBackorderConcept,
    0.0                                   as calcAantalBackorderGoedgek,
    0.0                                   as calcAantalBackorder,
    0.0                                   as calcAantalBackorderDirecteInkoopConcept,
    0.0                                   as calcAantalBackorderDirecteInkoopGoedgek,
    0.0                                   as calcAantalBackorderDirecteInkoop,
    0.0                                   as calcAantalBackorderProductieConcept,
    0.0                                   as calcAantalBackorderProductieGoedgek,
    0.0                                   as calcAantalBackorderProductie,
    0.0                                   as calcGereserveerdTotaal,
    0.0                                   as calcGereserveerdBackorderConcept,
    0.0                                   as calcGereserveerdBackorderGoedgek,
    0.0                                   as calcGereserveerdBackorder,
    0.0                                   as calcGereserveerdLeveringConcept,
    0.0                                   as calcGereserveerdLeveringGoedgek,
    0.0                                   as calcGereserveerdLevering,
    0.0                                   as calcGereserveerdProjectOnderhanden,
    0.0                                   as calcGereserveerdProjectVoorbereid,
    0.0                                   as calcGereserveerdVoorraadverplaatsing,
    0.0                                   as calcGereserveerdProductie,
    0.0                                   as calcInEindProductie,
    0.0                                   as calcInBestellingConcept,
    0.0                                   as calcInBestellingGoedgek,
    0.0                                   as calcInBestellingVerwerkt,
    0.0                                   as calcInBestellingDirecteInkoop,
    0.0                                   as calcInVerkoopOrderProductie,
    VvorAantalGereserveerdInVanLocInVrrdEenh as calcInVoorraadVerplaatsingen,
    0.0                                   as calcInBestellingVoorEconomischeVoorraad,
    0.0                                   as calcInMagOntvangst,
    0.0                                   as calcInMagOntvangstDirecteInkoop,
    0.0                                   as calcMagazijnVoorraad,
    0.0                                   as calcVrijeVoorraad,
    0.0                                   as calcBeschikbareVoorraad,
    VvorAantalGereserveerdInVanLocInVrrdEenh as calcEconomischeVoorraad,
    0.0                                   as calcMaximumVoorraad,
    0.0                                   as calcMinimumVoorraad,
    calcEconomischeVoorraad - calcMinimumVoorraad  as calcReserveVoorraad
  from
    tabVoorraadVerplaatsingsOpdrachtRegel
  where
    locate(@SkipPartsToCalculate, #!#Q#!#) = 0
    and (@ArtGid is null or VvorArtGid = @ArtGid)
    and (@MagGid is null or VvorMagGidNaar = @MagGid)
    and (@LocGid is null or VvorLocGidNaar = @LocGid)
    and (@ArtPartijGid is null or VvorArtPartijGid = @ArtPartijGid)
    and (VvorStatus between 1 /*Klaar voor verplaatsen*/ and 8 /*net voor Verwerkt*/)
    and VvorAantalGereserveerdInVanLocInVrrdEenh <> 0


UNION ALL

  // ***************************************************
  // ********** Externe aanpassingen *******************
  // ***************************************************
  select
      20                                                as calcResRegelSoort,
      null                                              as calcNawGid,
      null                                              as calcOrkGid,
      null                                              as calcOrrGid,
      null                                              as calcPrdOkGid,
      null                                              as calcPrdOcGid,
      null                                              as calcPrdOeGid,
      null                                              as calcPbkGid,
      null                                              as calcPbrGid,
      null                                              as calcPwbkGid,
      null                                              as calcPwbrGid,
      null                                              as calcBstKopGid,
      null                                              as calcBstRglGid,
      null                                              as calcMokGid,
      null                                              as calcMagOntGid,
      VeaArtGid                                         as calcArtGid,
      VeaMagGid                                         as calcMagGid,
      VeaLocGid                                         as calcLocGid,
      VeaArtPartijGid                                   as calcArtPartijGid,
      null                                              as calcArtSerieGid,
      null                                              as calcVvorGid,
      VeaDatum                                          as calcDatum,
      null                                              as calcAantalBesteld,
      null                                              as calcAantalGeleverd,
      null                                              as calcAantalLeveringConcept,
      null                                              as calcAantalLeveringGoedgek,
      null                                              as calcAantalLeveringGoedgekVrijgegeven,
      null                                              as calcAantalLevering,
      0.0                                               as calcAantalBackorderConcept,
      0.0                                               as calcAantalBackorderGoedgek,
      0.0                                               as calcAantalBackorder,
      0.0                                               as calcAantalBackorderDirecteInkoopConcept,
      0.0                                               as calcAantalBackorderDirecteInkoopGoedgek,
      0.0                                               as calcAantalBackorderDirecteInkoop,
      0.0                                               as calcAantalBackorderProductieConcept,
      0.0                                               as calcAantalBackorderProductieGoedgek,
      0.0                                               as calcAantalBackorderProductie,
      VeaAantalGereserveerdInVrrdEenh                   as calcGereserveerdTotaal,
      0.0                                               as calcGereserveerdBackorderConcept,
      0.0                                               as calcGereserveerdBackorderGoedgek,
      0.0                                               as calcGereserveerdBackorder,
      0.0                                               as calcGereserveerdLeveringConcept,
      0.0                                               as calcGereserveerdLeveringGoedgek,
      0.0                                               as calcGereserveerdLevering,
      0.0                                               as calcGereserveerdProjectOnderhanden,
      0.0                                               as calcGereserveerdProjectVoorbereid,
      0.0                                               as calcGereserveerdVoorraadverplaatsing,
      0.0                                               as calcGereserveerdProductie,
      0.0                                               as calcInEindProductie,
      0.0                                               as calcInBestellingConcept,
      0.0                                               as calcInBestellingGoedgek,
      0.0                                               as calcInBestellingVerwerkt,
      0.0                                               as calcInBestellingDirecteInkoop,
      0.0                                               as calcInVerkoopOrderProductie,
      0.0                                               as calcInVoorraadVerplaatsingen,
      0.0                                               as calcInBestellingVoorEconomischeVoorraad,
      0.0                                               as calcInMagOntvangst,
      0.0                                               as calcInMagOntvangstDirecteInkoop,
      VeaAantalInMagazijnInVrrdEenh                     as calcMagazijnVoorraad,
      VeaAantalInMagazijnInVrrdEenh
      -VeaAantalGereserveerdInVrrdEenh                  as calcVrijeVoorraad,
      calcVrijeVoorraad                                 as calcBeschikbareVoorraad,
      calcVrijeVoorraad                                 as calcEconomischeVoorraad,
      0.0                                               as calcMaximumVoorraad,
      0.0                                               as calcMinimumVoorraad,
      calcEconomischeVoorraad - calcMinimumVoorraad     as calcReserveVoorraad
  from
    tabVoorraadExterneApp
  where
    locate(@SkipPartsToCalculate, #!#R#!#) = 0
    and (@ArtGid is null or VeaArtGid = @ArtGid)
    and (@MagGid is null or VeaMagGid = @MagGid)
    and (@LocGid is null or VeaLocGid = @LocGid)
    and (@ArtPartijGid is null or VeaArtPartijGid = @ArtPartijGid)
    ';

  // Secure parameters
  set @SkipPartsToCalculate = Replace(@SkipPartsToCalculate, '''', '''''');
  set @GroupByList          = Replace(@GroupByList         , '''', '''''');
  set @ResultList           = Replace(@ResultList          , '''', '''''');

  // Repair the quotes in main query
  set @sql = replace(@sql, '#!#', '''');
  // Put parameters in main query
  set @sql = 'begin
    declare @SkipPartsToCalculate nchar(30) =''' || @SkipPartsToCalculate || ''';
    declare @ArtGid integer ' || if @ArtGid is not null then ' = ' || @ArtGid endif || ';
    declare @ArtPartijGid integer ' || if @ArtPartijGid is not null then ' = ' || @ArtPartijGid endif || ';
    declare @MagGid integer ' || if @MagGid is not null then ' = ' || @MagGid endif || ';
    declare @LocGid integer ' || if @LocGid is not null then ' = ' || @LocGid endif || ';
    select ' || replace(@GroupByList, '\n', ',') || ', ' ||
      (select list(@fieldname, ',') from openstring(value @ResultList) with (@fieldname nchar(100)) option ( ROW DELIMITED BY '\n' delimited by '') AS dummy) ||
    ' from ('   || @sql || ') as vw
      group by ' || (select list(@fieldname, ',') from openstring(value @GroupByList) with (@fieldname nchar(100)) option ( ROW DELIMITED BY '\n' delimited by '') AS dummy) || '
    end;';
  //unload select @sql To 'd:\sql.sql';
  //call trace(@sql);
  execute immediate with result set on @sql;

end;


create or replace function AanmakenVerplaatsingsopdracht_GetLocGidDestination(
  in @NaarLocatie                 smallint,
  in @GeblokkeerdeLocatieToestaan smallint, // 0 = Als bestemmingsloc geblokkeerd, dan volgende proberen (en uiteindelijk misschien leeg), 1 = Ook geblokkeerde gewoon teruggeven, 2 = Geblokkeerde niet toestaan, maar niet naar andere zoeken
  in @ArtGid                      integer,
  in @MagGidNaar                  integer
)
returns integer
begin
  declare @i integer;
  declare @LocGid integer;
  declare _SEARCHFOR_MAG_DIRINK     smallint = 0;
  declare _SEARCHFOR_MAG_BACKORDERS smallint = 1;
  declare _SEARCHFOR_MAG_ONTVANGST  smallint = 2;
  declare _SEARCHFOR_ART_PLAATSEN   smallint = 10;
  declare _SEARCHFOR_ART_PICKEN     smallint = 11;
  declare @SearchActionSets array of array of smallint =
  array( // LET OP!! DEZE ARRAY MOET EVENVEEL ELEMENTEN HEBBEN ALS IN VvcrNaarLocatie BESCHIKBAAR!!!
    array( // Voorkeur voor directe inkopen
      _SEARCHFOR_MAG_DIRINK,
      _SEARCHFOR_ART_PLAATSEN,
      _SEARCHFOR_ART_PICKEN
    ),
    array( // Voorkeur voor plaatsen in magazijn
      _SEARCHFOR_MAG_ONTVANGST,
      _SEARCHFOR_ART_PLAATSEN,
      _SEARCHFOR_ART_PICKEN
    ),
    array( // Voorkeur voor plaatsen van artikel
      _SEARCHFOR_ART_PLAATSEN,
      _SEARCHFOR_ART_PICKEN
    ),
    array( // Voorkeur voor picken van artikel
      _SEARCHFOR_ART_PICKEN
    ),
    array( // Voorkeur voor backorders
      _SEARCHFOR_MAG_BACKORDERS,
      _SEARCHFOR_ART_PLAATSEN,
      _SEARCHFOR_ART_PICKEN
    )
  );
  declare @SearchActionSet array of smallint = @SearchActionSets[[@NaarLocatie+1]]; // Select correct set as template for the searchable locations

  declare @SearchAction smallint;

  declare @LocGeblokkeerd smallint;

  set @NaarLocatie = @NaarLocatie + 1; // Array is 1-based!!!
  set @i = 1;
  while @LocGid is null and @i <= cardinality(@SearchActionSet)
  loop
    set @SearchAction = @SearchActionSet[[@i]];
    case
      when @SearchAction = _SEARCHFOR_MAG_DIRINK then
        select MagLocGidVoorkeurDirecteInkoop, LocBlokkade into @LocGid, @LocGeblokkeerd from tabMagazijn inner join tabLocatie on LocGid = MagLocGidVoorkeurDirecteInkoop where MagGid = @MagGidNaar;

      when @SearchAction = _SEARCHFOR_MAG_BACKORDERS then
        select MagLocGidVoorkeurBackorder    , LocBlokkade into @LocGid, @LocGeblokkeerd from tabMagazijn inner join tabLocatie on LocGid = MagLocGidVoorkeurDirecteInkoop where MagGid = @MagGidNaar;

      when @SearchAction = _SEARCHFOR_MAG_ONTVANGST then
        select MagLocGidVoorkeurOntvangst    , LocBlokkade into @LocGid, @LocGeblokkeerd from tabMagazijn inner join tabLocatie on LocGid = MagLocGidVoorkeurOntvangst where MagGid = @MagGidNaar;

      when @SearchAction = _SEARCHFOR_ART_PLAATSEN then
        select ArtMagLocGidVoorkeurOntvangst , LocBlokkade into @LocGid, @LocGeblokkeerd from tabArtikelMagazijn inner join tabLocatie on LocGid = ArtMagLocGidVoorkeurOntvangst where ArtMagMagGid = @MagGidNaar and ArtMagArtGid = @ArtGid;

      when @SearchAction = _SEARCHFOR_ART_PICKEN then
        select ArtMagDefaultLocGid           , LocBlokkade into @LocGid, @LocGeblokkeerd from tabArtikelMagazijn inner join tabLocatie on LocGid = ArtMagDefaultLocGid where ArtMagMagGid = @MagGidNaar and ArtMagArtGid = @ArtGid;
    end;

    // Checks
    if @LocGeblokkeerd = 1 then
      case @GeblokkeerdeLocatieToestaan
        when 0 /*blocked not permitted, search for next*/ then
          set @LocGid = null;
        when 1 /*Block permitted*/ then
        when 2 /*Blocked not permitted, do not search for other*/ then
          set @LocGid = null;
          leave;
      end;
    end if;

    set @i = @i + 1;
  end loop;
  return(@LocGid);
end;

create or replace procedure AanmakenVoorraadVerplaatsingsOpdracht(
  in @VvckGid       integer,
  in @BronType      smallint,                 // Vergelijk VvckBron! Geeft aan wat voor soort @BronGid is.
                                              // 0 = MohkGid (Historische magazijnontvangst),
                                              // 1 = LocGid (Locatie leegmaken)
  in @BronParentGid integer    default null,  // als @BronType = 1, dan MagGid
  in @BronGid       integer,
  in @Peildatum     datetime   default null,  // Indien null, dan de huidige datumtijd
  in @SpId          integer    default null,  // Indien leeg/niet meegegeven, dan die van deze connectie
  in @LoginTime     Date       default null,  // Indien leeg/niet meegegeven, dan die van deze connectie
  in @KeepLocked    smallint   default 0,     // Als aangemaakt, moet de opdracht dan gelockt blijven? (0=nee, 1=ja)
  in @vvokGid       integer                   // al IN, dan moet die al zijn gelockt!
)
result(
    avvoVvokGid          integer,       // Deze is aangemaakt
    avvoVvokNummer       numeric(10,0), // Deze is aangemaakt
    avvoBronKopGid       integer,
    avvoBronKopNummer    nchar(40),
    avvoBronKopOms       nchar(80),
    avvoBronRegelGid     integer,
    avvoBronRegelnummer  nchar(40),
    avvoResult           integer, //0 = OK, 1 = Melding Opdracht is aangemaakt, 2 = Melding Regel is/zijn aangemaakt, 10 = Info, 20 = Warning (wel aangemaakt), 30 = Error (niet aangemaakt)
    avvoMsg              long nvarchar
)
begin
  declare @VvokNummer      numeric(10,0);
  declare @VvckGeblokkeerd smallint;
  declare @VvckBron integer;
  declare @VvckVanLocTypes nchar(20); // Zie VvckVanLocTypes en LocLocatietype
  declare @VvckDefKopStatus smallint; // Default status van de kop
  declare @LaatsteRegelDezeBronRegel      integer; // Het aantal van de bron steeds verlagen met alle verplaatsingsregels van deze bronregel
  declare @VorigeRegelDezeBronRegel       integer; // tbv geven van melding
  declare @AantalNogTeVerwerkenInVrrdEenh numeric(15,3); // Per bronregel moeten we dit aantal nog verwerken
  declare @AantalVerwerktInVrrdEenh       numeric(15,3);
  declare @BronRegelTeller                integer = 0;
  declare @BufBronKopNummer               integer;
  declare @BufBronKopOms                  nchar(100);
  declare @Vvcr                           TAanmakenVoorraadVerplaatsingsOpdrachtCriterium;


  declare @LockIsGelukt                   smallint = 0;

  // Overgenomen uit AanmakenVoorraadVerplaatsingsOpdracht_BronRegels
  declare _GELDIGHEID_BRON_NIET_GEVONDEN integer = 1;
  declare _GELDIGHEID_BRONLOCATIES_OVERGESLAGEN integer = 2;

  // Results in resultset
  declare _RESULT_OK         integer = 0;
  declare _RESULT_CREATE     integer = 1;
  declare _RESULT_CREATELINE integer = 2;
  declare _RESULT_INFO       integer = 10;
  declare _RESULT_WARNING    integer = 20;
  declare _RESULT_ERROR      integer = 30;

  declare local temporary table tmpResult( // Zie resultset van deze procedure
    avvoGid              integer default autoincrement,
    avvoVvokGid          integer,       // Deze is aangemaakt
    avvoVvokNummer       numeric(10,0), // Deze is aangemaakt
    avvoBronKopGid       integer,
    avvoBronKopNummer    nchar(40),
    avvoBronKopOms       nchar(80),
    avvoBronRegelGid     integer,
    avvoBronRegelnummer  nchar(40),
    avvoResult           integer, //0 = OK, 10 = Info, 20 = Warning (wel aangemaakt), 30 = Error (niet aangemaakt)
    avvoMsg              long nvarchar
  ) on commit preserve rows;

  if @Peildatum is null then
    set @Peildatum = now();
  end if;

  select VvckGeblokkeerd, VvckBron, VvckVanLocTypes, VvckDefKopStatus
  into @VvckGeblokkeerd, @VvckBron, @VvckVanLocTypes, @VvckDefKopStatus from tabVoorraadVerplaatsingCriteriaKop where VvckGid = @VvckGid;

  if @VvckBron is null then
    insert into tmpResult with auto name
    select  @VvokGid avvoVvokGid,
            @BronGid avvoBronKopGid,
            '' avvoBronKopNummer,
            '' avvoBronKopOms,
            _RESULT_ERROR avvoResult,
            _U('De set van verplaatsingscriteria is niet gevonden.') avvoMsg;
    select avvoVvokGid, avvoVvokNummer, avvoBronKopGid, avvoBronKopNummer, avvoBronKopOms, avvoBronRegelGid, avvoBronRegelnummer, avvoResult, avvoMsg
    from tmpResult order by avvoGid;
    leave;
  end if;

  // Geblokkeerd? Dan terugmelden en gelijk eruit
  if @VvckGeblokkeerd <> 0 then
    insert into tmpResult with auto name
    select  @VvokGid avvoVvokGid,
            @BronGid avvoBronKopGid,
            '' avvoBronKopNummer,
            '' avvoBronKopOms,
            _RESULT_ERROR avvoResult,
            _U('De set van verplaatsingscriteria is geblokkeerd voor uitvoeren.') avvoMsg;
    select avvoVvokGid, avvoVvokNummer, avvoBronKopGid, avvoBronKopNummer, avvoBronKopOms, avvoBronRegelGid, avvoBronRegelnummer, avvoResult, avvoMsg
    from tmpResult order by avvoGid;
    leave;
  end if;

  //De BRON van de verplaatsingsset levert bronregels met art/partij/vanmag/vanloc/aantal op
  //Deze bronregels lopen we 1 voor 1 af en kjken waar die o.b.v. de verplaatsingssetregels naartoe kunnen
  for @VvckBronCursor AS CURSOR_VvckBronCursor CURSOR FOR
  select
    BronRegelGid     @BronRegelGid,
    BronKopNummer    @BronKopNummer,
    BronKopOms       @BronKopOms,
    BronRegelnummer  @BronRegelnummer,
    TbvSoort         @TbvSoort,
    TbvGid           @TbvGid,
    ArtGid           @ArtGid,
    ArtPartijGid     @ArtPartijGid,
    MagGid           @VanMagGid,
    LocGid           @VanLocGid,
    AantalInVrrdEenh @AantalInVrrdEenh,
    NodigVoor        @NodigVoor,
    NodigVoorOms     @NodigVoorOms,
    //OrrGid           @OrrGid,
    NodigOpDatum     @NodigOpDatum,
    // tbv wel of niet verwerking
    GeldigheidBits   @GeldigheidBits,
    RedenNietGeldig  @RedenNietGeldig,
    Serienummers     @Serienummers
  from
    AanmakenVoorraadVerplaatsingsOpdracht_BronRegels(
      @VvckGid,
      @VvckBron,
      @BronGid,
      @VvckVanLocTypes=@VvckVanLocTypes
    )
  for read only
  do
    //call trace('Bron='||@BronRegelnummer||'; artgid='||@artgid|| '; artpartijgid='||@artpartijgid||'; VanMagGid='||@VanMagGid||'; VanLocGid='||@VanLocGid||'; aantal='|| @AantalInVrrdEenh || '; NodigVoorOms='||@NodigVoorOms||'; NodigOp='||@NodigOpDatum);

    // Buffer deze ivm controles NA de loop
    set @BufBronKopNummer = @BronKopNummer;
    set @BufBronKopOms    = @BronKopOms;

    //****************************
    //*** Bijhouden van status ***
    //****************************
    set @BronRegelTeller = @BronRegelTeller + 1; // OOK verhogen als de regel niet geldig is! ivm teruggeven van status
    if @GeldigheidBits <> 0 then
      // Redenen onthouden tbv aanroeper
      if (@GeldigheidBits & _GELDIGHEID_BRONLOCATIES_OVERGESLAGEN) <> 0 then
        insert into tmpResult with auto name
        select  @VvokGid avvoVvokGid,
                @BronGid avvoBronKopGid,
                @BronKopNummer avvoBronKopNummer,
                @BronKopOms avvoBronKopOms,
                @BronRegelGid avvoBronRegelGid,
                IntToCodenummer(@BronRegelnummer) avvoBronRegelnummer,
                _RESULT_WARNING avvoResult,
                _U('Locatietype(s) voldoen niet aan verplaatsingscriteria.') avvoMsg;
      end if;
      if (@GeldigheidBits & _GELDIGHEID_BRON_NIET_GEVONDEN) <> 0 then
        insert into tmpResult with auto name
        select  @VvokGid avvoVvokGid,
                @BronGid avvoBronKopGid,
                @BronKopNummer avvoBronKopNummer,
                @BronKopOms avvoBronKopOms,
                @BronRegelGid avvoBronRegelGid,
                IntToCodenummer(@BronRegelnummer) avvoBronRegelnummer,
                _RESULT_WARNING avvoResult,
                _U('Er zijn geen regels gevonden om een opdracht aan te maken.') avvoMsg;
      end if;
      // Skip rest van code in de loop en pak volgende record
      continue;
    end if;

    // Controleer of aantal wel positief in (<=0 negeren)
    if @AantalInVrrdEenh <= 0 then
      insert into tmpResult with auto name
      select  @VvokGid avvoVvokGid,
              @BronGid avvoBronKopGid,
              @BronKopNummer avvoBronKopNummer,
              @BronKopOms avvoBronKopOms,
              @BronRegelGid avvoBronRegelGid,
              IntToCodenummer(@BronRegelnummer) avvoBronRegelnummer,
              _RESULT_WARNING avvoResult,
              _U('Aantal te verplaatsen in voorraadeenheden moet groter dan nul zijn.') avvoMsg;
      // Skip rest van code in de loop en pak volgende record
      continue;
    end if;

    //***************************
    //*** Verwerken bronregel ***
    //***************************

    //--- - Aanmaken verplaatsingskop
    if @vvokGid is not null then
      // Verplaatsingsopdrachtkop meegegeven, controleren of deze bestaat, zo niet, dan alsnog aanmaken (geen fout)
      set @VvokNummer = 0;
      select VvokNummer into @VvokNummer from tabvoorraadVerplaatsingsOpdrachtKop where VvokGid = @VvokGid and VvokStatus <> 9 /*Verwerkt*/;
      if @VvokNummer is null then
        // vvok niet gevonden, dus maak maar een nieuwe aan
        set @VvokGid = null;
      end if;
    end if;


    // Als we nog geen verplaatsingskop hebben, dan alsnog aanmaken (zo kunnen we zelfs aanvullen, indien gewenst)
    if @vvokGid is null then
      insert into tabvoorraadVerplaatsingsOpdrachtKop with auto name
      select
        //0 vvokStatus,
        @VvckBron vvokBron,
        @BronKopNummer vvokBronReferentie,
        @BronKopOms vvokOms,
        @VvckDefKopStatus VvokStatus;

      set @vvokGid = @@Identity;
      select VvokNummer into @VvokNummer from tabvoorraadVerplaatsingsOpdrachtKop where VvokGid = @VvokGid;

      call LockWaitAndSetForUniqueLock(isnull(@SpId, @@SpId), isnull(@LoginTime, @@LoginTime), 'tabvoorraadVerplaatsingsOpdrachtKop', @vvokGid, 5 /*Wacht max. 5 seconde*/, @LockIsGelukt);
      if @LockIsGelukt = 0 then
        insert into tmpResult with auto name
        select  @VvokGid avvoVvokGid,
                @VvokNummer avvoVvokNummer,
                @BronGid avvoBronKopGid,
                @BronKopNummer avvoBronKopNummer,
                @BronKopOms avvoBronKopOms,
                @BronRegelGid avvoBronRegelGid,
                IntToCodenummer(@BronRegelnummer) avvoBronRegelnummer,
                _RESULT_ERROR avvoResult,
                _U('De voorraadverplaatsingsopdracht is in gebruik.') avvoMsg;
        select avvoVvokGid, avvoVvokNummer, avvoBronKopGid, avvoBronKopNummer, avvoBronKopOms, avvoBronRegelGid, avvoBronRegelnummer, avvoResult, avvoMsg
        from tmpResult order by avvoGid;
        leave; // We kappen gelijk met de verdere verwerking, dus de lus verlaten
      end if;
    end if;


    // Onthouden tot welke verplaatsingsregel we hebben aangemaakt, zodat we voor de bronregel waar we
    // mee bezig zijn kunnen bepalen hoeveel we inmiddels al verwerkt hebben en welk deel nog overblijft
    // voor de volgende setregels.
    select isnull(max(vvorRegelnummer), 0) into @LaatsteRegelDezeBronRegel from tabvoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @vvokGid;
    set @VorigeRegelDezeBronRegel = @LaatsteRegelDezeBronRegel;

    // Onthouden hoeveel we van deze bronregel nog te doen hebben
    set @AantalNogTeVerwerkenInVrrdEenh = @AantalInVrrdEenh;


    // Doorlopen van de setregels, zolang het aantal >0 is, gaan we door
    for @VvcrRegelsCursor AS CURSOR_VvcrRegels CURSOR FOR
    select
      VvcrGid                   @VvcrGid,
      VvcrBetrekkingOp          @VvcrBetrekkingOp,
      VvcrMaxDagenNaPeildatum   @VvcrMaxDagenNaPeildatum,
      VvcrNaarMagazijn          @VvcrNaarMagazijn,
      VvcrNaarLocatie           @VvcrNaarLocatie,
      VvcrMutOmschrijving       @VvcrMutOmschrijving,
      VvcrDefRegelstatus        @VvcrDefRegelstatus,
      VvcrDefAantalVerplaatst   @VvcrDefAantalVerplaatst,
      VvcrWhatIfLocBlocked      @VvcrWhatIfLocBlocked,
      VvcrDefKenmerk            @VvcrDefKenmerk,
      VvcrDefLocGebloktToestaan @VvcrDefLocGebloktToestaan
    from
      tabVoorraadVerplaatsingCriteriaRegel
    where VvcrVvckGid = @VvckGid
    for read only
    do
      set @AantalVerwerktInVrrdEenh = 0;
      set @Vvcr.VccrGid            = @VvcrGid;
      set @Vvcr.RelatesTo          = @VvcrBetrekkingOp;
      set @Vvcr.ToWarehouse        = @VvcrNaarMagazijn;
      set @Vvcr.ToLocation         = @VvcrNaarLocatie;
      set @Vvcr.StockMovementDescr = @VvcrMutOmschrijving;
      set @Vvcr.DefLineState       = @VvcrDefRegelstatus;
      set @Vvcr.DefNumberMoved     = @VvcrDefAantalVerplaatst;
      set @Vvcr.DefFeature         = @VvcrDefKenmerk;
      set @Vvcr.DefLocblockedPermitted = @VvcrDefLocGebloktToestaan;
      set @Vvcr.WhatIfLocBlocked   = @VvcrWhatIfLocBlocked;

      case @VvcrBetrekkingOp
        when 0 /* Directe inkoop*/ then
          call AanmakenVoorraadVerplaatsingsOpdracht_DirecteInkopenBackorders(
            1, // Directe inkopen
            @vvokGid,
            @Vvcr,
            @ArtGid,
            @ArtPartijGid,
            @VanMagGid,
            @VanLocGid,
            @Serienummers,
            @AantalNogTeVerwerkenInVrrdEenh,
            @BronRegelGid,
            @TbvSoort,
            @TbvGid,
            @NodigVoor,
            @NodigVoorOms,
            @NodigOpDatum,
            @AantalVerwerktInVrrdEenh
          );
        when 1 /*Gekoppelde backorders*/ then
          // Backorders doorlopen
          call AanmakenVoorraadVerplaatsingsOpdracht_DirecteInkopenBackorders(
            0, // Backorders
            @vvokGid,
            @Vvcr,
            @ArtGid,
            @ArtPartijGid,
            @VanMagGid,
            @VanLocGid,
            @Serienummers,
            @AantalNogTeVerwerkenInVrrdEenh,
            @BronRegelGid,
            @TbvSoort,
            @TbvGid,
            @NodigVoor,
            @NodigVoorOms,
            @NodigOpDatum,
            @AantalVerwerktInVrrdEenh
          );

        when 3 /*Inruimen*/ then // Restant gewoon naar voorraad, naar aangegeven locatie, MET RESERVEREN
          call AanmakenVoorraadVerplaatsingsOpdracht_Inruimen(
            @vvokGid,
            @Vvcr,
            @ArtGid,
            @ArtPartijGid,
            @VanMagGid,
            @VanLocGid,
            @Serienummers,
            @AantalNogTeVerwerkenInVrrdEenh,
            @BronRegelGid,
            @TbvSoort,
            @TbvGid,
            @AantalVerwerktInVrrdEenh
          );

      end case;

      // Verwijder 0-regels, mochten die per ongeluk zijn gemaakt
      delete tabvoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @vvokGid and vvorAantalInVrrdEenh = 0;

      // Tellingen bijhouden
      begin
        // Teruggeven van hoogst weggeschreven regelnummer tbv tellingen
        select isnull(max(vvorRegelnummer), 0) into @LaatsteRegelDezeBronRegel from tabvoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @vvokGid;

        if @LaatsteRegelDezeBronRegel - @VorigeRegelDezeBronRegel >= 1 then
          insert into tmpResult with auto name
          select  @VvokGid avvoVvokGid,
                  @VvokNummer avvoVvokNummer,
                  @BronGid avvoBronKopGid,
                  @BronKopNummer avvoBronKopNummer,
                  @BronKopOms avvoBronKopOms,
                  @BronRegelGid avvoBronRegelGid,
                  IntToCodenummer(@BronRegelnummer) avvoBronRegelnummer,
                  _RESULT_CREATELINE avvoResult,
                  _U('Verplaatsingsopdrachtregels zijn aangemaakt.') avvoMsg;
        end if;

        // update tellingen tbv melding
        set @VorigeRegelDezeBronRegel = @LaatsteRegelDezeBronRegel;
      end; // tellingen bijhouden

      // Restant bepalen voor de volgende setregel
      set @AantalNogTeVerwerkenInVrrdEenh = @AantalNogTeVerwerkenInVrrdEenh - @AantalVerwerktInVrrdEenh;

      // Test of we nog in de cursor moeten blijven (alles verwerkt, dan cursor sluiten en volgende bronregel verwerken)
      if @AantalNogTeVerwerkenInVrrdEenh <= 0 then
        leave; // CURSOR_VvcrRegels
      end if;
    end for;

  end for;

  //*************************
  //*** Status afhandelen ***
  //*************************
  //--- - Geen bronregels gevonden
  if @BronRegelTeller = 0 then
    insert into tmpResult with auto name
    select  @VvokGid avvoVvokGid,
            @VvokNummer avvoVvokNummer,
            @BronGid avvoBronKopGid,
            @BufBronKopNummer avvoBronKopNummer,
            @BufBronKopOms avvoBronKopOms,
            _RESULT_WARNING avvoResult,
            _U('Er zijn geen gegevens gevonden om een opdracht aan te maken.') avvoMsg;
  else
    //--- - Geen verplaatsingsregels aangemaakt?
    // Als het resultaat geen regels bevat, dan verwijderen en status teruggeven
    if not exists(select first 1 from tabvoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @vvokGid) then
      // Geen regels, dus kop verwijderen
      delete tabvoorraadVerplaatsingsOpdrachtKop where vvokGid = @vvokGid;
      if @LockIsGelukt = 1 then
        call LockReleaseOnId(isnull(@SpId, @@SpId), isnull(@LoginTime, @@LoginTime), 1, 'tabvoorraadVerplaatsingsOpdrachtKop', @vvokGid);
      end if;
      set @vvokGid = null;
      insert into tmpResult with auto name
      select  @VvokGid avvoVvokGid,
              @VvokNummer avvoVvokNummer,
              @BronGid avvoBronKopGid,
              @BufBronKopNummer avvoBronKopNummer,
              @BufBronKopOms avvoBronKopOms,
              _RESULT_ERROR avvoResult,
              _U('De verplaatsingsopdracht kan niet worden aangemaakt.') avvoMsg;
    else
      insert into tmpResult with auto name
      select  -1 avvoGid,
              @vvokGid avvoVvokGid,
              @VvokNummer avvoVvokNummer,
              @BronGid avvoBronKopGid,
              @BufBronKopNummer avvoBronKopNummer,
              @BufBronKopOms avvoBronKopOms,
              _RESULT_CREATE avvoResult,
              _U('Verplaatsingsopdracht %1! is aangemaakt.', @VvokNummer) avvoMsg;
    end if;
  end if;

  // Lock vrijgeven, indien niet anders was aangegeven
  if @vvokGid is not null and @KeepLocked = 0 and @LockIsGelukt = 1 then
    call LockReleaseOnId(isnull(@SpId, @@SpId), isnull(@LoginTime, @@LoginTime), 1, 'tabvoorraadVerplaatsingsOpdrachtKop', @vvokGid);
  end if;

  // ACW De meldingen worden distinct teruggegeven, dus bijv. voor 1 MO-regel met meerdere spec.regels maar 1x met onjuiste locatie
  select distinct avvoVvokGid, avvoVvokNummer, avvoBronKopGid, avvoBronKopNummer, avvoBronKopOms, avvoBronRegelGid, avvoBronRegelnummer, avvoResult, avvoMsg
  from tmpResult
  order by avvoVvokNummer, avvoBronKopNummer, avvoBronRegelnummer, avvoResult;
end;


create or replace procedure AanmakenVoorraadVerplaatsingsOpdracht_BronRegels(
  in @VvckGid integer,                    // Mocht je nog meer informatie willen, dan kan je het uit deze setkop halen
  in @VvckBron smallint,                  // 0 = historische magazijnontvangst
  in @BronGid  integer,                   // @VvckBron=0: MohkGid, @VvckBron=1: LocGid
  in @BronParentGid integer  default null, // @VvckBron=1: MagGid
  in @VvckVanLocTypes nchar(20) default 'ABCDEFGHIJKLMNOPQRSTUVWXYZ' // In ieder geval voldoende voor default
)
result (
  BronRegelGid     integer,      // Gid van bron, bijv. MohrGid (dus NIET de kop!!)
  BronKopNummer    integer,      // Kopnummer van bron, bijv. magazijnontvangstnummer
  BronRegelnummer  integer,      // Regelnummer in de bron, bijv. magazijnontvangstregelnummer
  BronKopOms       nchar(100),   // Omschrijving van de bron, hoofd (kop), bijv. Magazijnontvangst 12345
  BronOms          nchar(100),   // Omschrijving, bijv. Magazijnontvangst 12345/001
  TbvSoort         smallint,     // 0 = Inruimen (geen reden, overig); 1 = Verkooporder
  TbvGid           integer,      // Verwijzing naar reden, bijv. orrgid
  ArtGid           integer,
  ArtPartijGid     integer,
  MagGid           integer,
  LocGid           integer,
  AantalInVrrdEenh numeric(15,3),
  NodigVoor        nchar(100),    // bijv. Ordernummer+regel, productienummer+regel
  NodigVoorOms     nchar(100),
  NodigOpDatum     datetime,       // Optioneel, datum benodigd (leverdatum voor order, productiedatum voor productie)
  GeldigheidBits   integer,       // 0 = geldig, kan worden verwerkt, anders met bits aangegeven waarom niet:
                                  // bit 0 (=  1): Artikelen in locatie van locatietype worden niet verplaatst
  RedenNietGeldig  long nvarchar,  // Bevat reden(en) waarom de regel niet kan worden verwerkt, bijv. omdat er geen geschikte locatietype is gevonden
  Serienummers     long nvarchar  // lege string OF een lijst van serienummers gescheiden door een \n
)
begin
  declare _GELDIGHEID_BRON_NIET_GEVONDEN integer = 1;
  declare _GELDIGHEID_BRONLOCATIES_OVERGESLAGEN integer = 2;

  //call trace('AanmakenVoorraadVerplaatsingsOpdracht_BronRegels(@VvckGid='||isnull(string(@VvckGid), 'NULL')||', @VvckBron='||isnull(string(@VvckBron), 'NULL')||', @BronGid='||isnull(string(@BronGid), 'NULL') ||', @BronParentGid=' ||isnull(string(@BronParentGid), 'NULL')||', @VvckVanLocTypes='|| @VvckVanLocTypes||')');

  //Haakje voor maatwerk/WMS tbv bepaling bronregels
  if exists(select first 1 from sys.sysprocedure where proc_name = 'MAATWERK_AanmakenVoorraadVerplaatsingsOpdracht_BronRegels') then
    begin
      declare @IsStandaardRoutineOverruled smallint = 0;
      call MAATWERK_AanmakenVoorraadVerplaatsingsOpdracht_BronRegels(
        @VvckGid                     = @VvckGid,
        @VvckBron                    = @VvckBron,
        @BronGid                     = @BronGid,
        @BronParentGid               = @BronParentGid,
        @VvckVanLocTypes             = @VvckVanLocTypes,
        @IsStandaardRoutineOverruled = @IsStandaardRoutineOverruled
      );
      if @IsStandaardRoutineOverruled = 1 then
        leave; // Gelijk stoppen met deze procedure!
      end if;
    end;
  end if;


  case @VvckBron
    when 0 /*Historische magazijnontvangst*/ then
      begin
        declare @NodigVoorOmsDirecteInkopen nchar(100) = _A('Directe inkoop %1!/%2!');
        declare @NodigVoorOmsBackorder      nchar(100) = _A('Backorder %1!/%2!');
        declare @NodigVoorOmsInruimen       nchar(100) = _A('Inruimen');
        declare @BronOms                    nchar(100) = _A('Magazijnontvangst %1!/%2!');
        declare @BronKopOms                 nchar(100) = _A('Magazijnontvangst %1!');
        (
          select
            MohrGid BronRegelGid,
            MohkNummer BronKopnummer,
            MohrRegelnr,
            _P(@BronKopOms, MohkNummer) BronKopOms,
            _P(@BronOms, MohkNummer, repeat('0', 3-length(MohrRegelnr)) || MohrRegelnr ) BronOms,
            // Reden (als foreign key)
            if TbvGid is null then
              0 /*Overige/inruimen*/
            else
              1 /*Altijd een verkooporder, straks misschien ook een productieorder*/
            endif TbvSoort,
            isnull(MohdOrrGid, brdOrrGid) TbvGid,
            // Artikel/partij
            (select ArtGid from tabArtikel where ArtCode = MohrArtCode and ArtSoort = 2) ArtGid,
            (select ArtpartijGid from tabArtikelPartij where ArtPartijArtGid = ArtGid and ArtPartijNummer = MohrArtPartijNummer) ArtpartijGid,
            // Van magazijn/locatie
            (select maggid from tabMagazijn where MagCode = MohkMagCode) MagGid,
            LocGid,
            // Aantal
            sum(MohlAantal) AantalInVrrdEenh, // Sum, zodat alle serienummers ed gelijk meegaan

            // Reden (als tekst/nummer)
            // Bij gekoppelde backorders is veld MohdOrrGid gevuld
            // Bij directe inkopen zijn velden MohdOrkNummer en MohdOrrRegelnr gevuld
            if OrkGid is not null then
              OrkNummer || '/' || OrrRegelNr
            else if MohdOrkNummer <> 0 then MohdOrkNummer endif ||
                 if MohdOrkNummer + MohdOrrRegelnr <> 0 then '/' endif ||
                 if MohdOrrRegelnr <> 0 then MohdOrrRegelnr endif
            endif NodigVoor,

            case
              when MohdOrrGid is not null then _A(@NodigVoorOmsBackorder,     OrkNummer, OrrRegelnr)
              when NodigVoor is not null then _A(@NodigVoorOmsDirecteInkopen, MohdOrkNummer, MohdOrrRegelnr)
              else _A(@NodigVoorOmsInruimen)
            end NodigVoorOms,
            //MohdOrrGid OrrGid,
            isnull(OrrLeverDatum, MohdLeverDatum) Leverdatum,

            // Locatietype wordt niet in verplaatsingsOpdracht opgenomen
            if @VvckVanLocTypes like '%' || char(LocLocatietype-1+ascii('A')) || '%' then 0 else _GELDIGHEID_BRONLOCATIES_OVERGESLAGEN endif |
            // Andere redenen voor niet-geldigheid
            0
            GeldigheidBits, // Als 0, dan is het goed
            if GeldigheidBits <> 0 then
              // Niet geldig, dan de reden aangeven indien mogelijk
              if not @VvckVanLocTypes like '%' || char(LocLocatietype-1+ascii('A')) || '%' then
                _U('Artikelen van locatietype %1! worden niet verplaatst', case LocLocatietype when 0 then 'Overige' when 1 then 'Ontvangst' when 2 then 'Retour' when 3 then 'Bulk' when 4 then 'Pick' when 5 then 'Cross dock' when 6 then 'Productiecomponenten' when 7 then 'Productie-eindproducten' end)
              endif
            endif RedenNietGeldig,
            list(MohlArtSerienummer, '\n') Serienummers
          from
            tabMagazijnOntvangstHistKop
            inner join tabMagazijnontvangstHistRegel        on MohrMohkGid = MohkGid
            inner join tabMagazijnOntvangstHistDetail       on MohdMohrGid = MohrGid
            inner join tabMagazijnOntvangstHistLocatieSerie on MohlMohdGid = MohdGid
            inner join tabLocatie on LocNaam = MohlLocNaam and LocMagGid = MagGid

            // ivm indirecte koppeling richting order
            left outer join tabBestelRegelDetail on BrdGid = MohdbrdGid

            // ivm koppeling naar verkooporders (gekoppelde backorders)
            left outer join (taborderregel inner join taborderkop on OrkGid = OrrOrkGid) on OrrGid = isnull(MohdOrrGid, brdOrrGid)
          where MohkGid = @BronGid
          group by
            // Group by nodig ivm list van serienummers
            MohrGid,
            MohkNummer,
            MohrRegelnr,
            MohdOrrGid,
            brdOrrGid,
            MohrArtCode,
            MohlLocNaam,
            ArtpartijGid,
            MohkMagCode,
            LocGid,
            OrkGid,
            OrkNummer,
            OrrRegelNr,
            MohdOrkNummer,
            MohdOrrRegelnr,
            OrrLeverDatum,
            MohdLeverDatum,
            LocLocatietype

          order by
            MohrRegelnr, MohlLocNaam, MohdOrkNummer, MohdOrrRegelnr
        )
        UNION ALL
        (
          // HistMag niet gevonden! Dat teruggeven als ongeldige regel!
          select
            null BronRegelGid,
            null BronKopNummer,
            null BronRegelnummer,
            null BronKopOms,
            null BronOms,
            null TbvSoort,
            null TbvGid,
            null ArtGid,
            null ArtPartijGid,
            null MagGid,
            null LocGid,
            null AantalInVrrdEenh,
            null NodigVoor,
            null NodigVoorOms,
            null NodigOpDatum,
            _GELDIGHEID_BRON_NIET_GEVONDEN GeldigheidBits,
            _U('Historische magazijnontvangst niet gevonden') RedenNietGeldig,
            '' Serienummers
          where not exists(select first 1 from tabMagazijnOntvangstHistKop where MohkGid = @BronGid)
        );
      end;
    when 1 /*BIJV VERKOOPORDER/PRODUCTIE/LOCATIELEEG*/ then
      set @BronKopOms = _A('Not yet implemented %1!');
      set @BronOms = _A('Not yet implemented %1!/%2!');
  end case;

end;


create or replace procedure AanmakenVoorraadVerplaatsingsOpdracht_DirecteInkopenBackorders(
  in @IsDirecteInkopen                smallint, // 0 = Backorders (zelfde verkooporder, maar zonder vinkje DirInk),
                                                // 1 = Directe inkopen
  in @vvokGid                         integer,
  in @Vvcr                            TAanmakenVoorraadVerplaatsingsOpdrachtCriterium,
  in @ArtGid                          integer,
  in @ArtPartijGid                    integer,
  in @VanMagGid                       integer,
  in @VanLocGid                       integer,
  in @Serienummers                    long nvarchar,
  in @AantalNogTeVerwerkenInVrrdEenh  numeric(15,3),
  in @BronRegelGid                    integer, // Mohrgid o.i.d.
  in @TbvSoort                        smallint, // 0 = Inruimen (overige), 1 = verkooporder, ...
  in @TbvGid                          integer, // OrderregelGid o.i.d.
  in @NodigVoor                       nchar(100),
  in @NodigVoorOms                    nchar(100),
  in @NodigOpDatum                    datetime,
  out @AantalVerwerktInVrrdEenh       numeric(15,3)
)
begin
  // Test of @NodigVoor ook een directe inkoop is. Zo niet, dan gelijk door. Zo wel, dan afhandelen
  // De directe inkoop is al uit backorder gehaald door verwerken mag.ontv.EN heeft al een locatie, maar die locatie
  // in de orderspec.regel moet worden omgezet naar de cross-dock volgens de instelling
  declare @AantalVerwerktInVrrdEenhDoorMaatwerk numeric(15,3) = 0;
  declare @OrkGid integer;
  declare @OrrGid integer;
  declare @AantalNaarVerplaatsing numeric(15,3);
  declare @LaatsteRegel           integer;

  if exists(select first 1 from sys.sysprocedure where proc_name = 'MAATWERK_AanmakenVoorraadVerplaatsingsOpdracht_DirecteInkopenBackorders') then
    begin
      // Maatwerk-haakje voor inruimen in magazijn
      // Het is mogelijk om slechts een deel in te ruimen en de rest aan destandaard routine over te laten!
      // Daartoe moet in de eigen routine het aantal worden aangepast en de laatsteregel alvast goed gezet (dat is het nummer van laatst toegevoegde regel)
      // De standaard routine zal dan de rest op gebruikelijke manier inruimen
      declare @IsStandaardRoutineOverruled smallint = 0;
      call MAATWERK_AanmakenVoorraadVerplaatsingsOpdracht_DirecteInkopenBackorders(
        @IsDirecteInkopen               = @IsDirecteInkopen,
        @vvokGid                        = @vvokGid,
        @Vvcr                           = @Vvcr,
        @ArtGid                         = @ArtGid,
        @ArtPartijGid                   = @ArtPartijGid,
        @VanMagGid                      = @VanMagGid,
        @VanLocGid                      = @VanLocGid,
        @Serienummers                   = @Serienummers,
        @AantalNogTeVerwerkenInVrrdEenh = @AantalNogTeVerwerkenInVrrdEenh,
        @BronRegelGid                   = @BronRegelGid,
        @TbvSoort                       = @TbvSoort,
        @TbvGid                         = @TbvGid,
        @NodigVoor                      = @NodigVoor,
        @NodigVoorOms                   = @NodigVoorOms,
        @NodigOpDatum                   = @NodigOpDatum,
        @AantalVerwerktInVrrdEenh       = @AantalVerwerktInVrrdEenhDoorMaatwerk,
        @IsStandaardRoutineOverruled    = @IsStandaardRoutineOverruled // 0 -> restant gaan we standaard verwerken, 1 -> maatwerk heeft alles gedaan
      );
      if @IsStandaardRoutineOverruled = 1 then
        set @AantalVerwerktInVrrdEenh = @AantalVerwerktInVrrdEenhDoorMaatwerk;
        leave; // Gelijk stoppen met deze procedure!
      end if;
      // Restant doen we zelf op de gebruikelijke manier
      set @AantalNogTeVerwerkenInVrrdEenh = @AantalNogTeVerwerkenInVrrdEenh - isnull(@AantalVerwerktInVrrdEenhDoorMaatwerk, 0.0);
    end;
  end if;

  select isnull(max(vvorRegelnummer), 0) into @LaatsteRegel from tabvoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @vvokGid;


  select OrkGid into @OrkGid
  from taborderkop
  where OrkNummer = regexp_substr(@NodigVoor, '\\d+');       // Eerste deel tot slash

  // Zoek regel op, gelijk aantal alvast bepalen voor als er nog geen specregels zijn
  select OrrGid, if OrrAantalLeveringVrrdEenh >= 0 then OrrAantalLeveringVrrdEenh else 0.0 endif
  into @OrrGid, @AantalNaarVerplaatsing
  from taborderRegel
  where OrrOrkgid = @OrkGid
    and OrrRegelnr = regexp_substr(@NodigVoor, '(?<=/)\\d+'); // laatste deel tot slash


  // Geen spec.regels -> overnemen totaal
  if exists(select first 1 from taborderregellocatie where OrlOrrGid = @OrrGid ) then
    // Totaal aantal toevoegen van de spec.regels
    // We houden hier geen rekening met de serienummers die misschien al in de orderregel staan
    select sum(OrlDezeLeveringVrrdEenh)
    into   @AantalNaarVerplaatsing
    from   taborderregellocatie
    where  OrlOrrGid = @OrrGid
      and (   (@ArtPartijGid is     null and  OrlArtPartijGid is null)  // Partijloos, dus zoeken naar partijloze spec.regels
           or (@ArtPartijGid is not null and (OrlArtPartijGid is null or OrlArtPartijGid = @ArtPartijGid) ) // Partijrijk, dus zoeken naar die partij-specregels OF specregels zonder partij
          )
  end if;


  // We verplaatsen maximaal het aantal van de orderregel of van de magazijnontvangst, maar minstens 0!
  set @AantalNaarVerplaatsing = greater(0.0, lesser(@AantalNaarVerplaatsing, @AantalNogTeVerwerkenInVrrdEenh));


  if @AantalNaarVerplaatsing > 0 then
    select
      @vvokGid vvorvvokGid,
      @LaatsteRegel + number() vvorRegelnummer,
      @ArtGid vvorArtGid,
      @ArtPartijGid vvorArtPartijGid,

      // Van mag/locatie
      @VanMagGid vvorMagGidVan,
      @VanLocGid vvorLocGidVan,

      // Naar mag/locatie
      case @Vvcr.ToWarehouse
        when 0 /*Zelfde magazijn*/ then @VanMagGid
        when 1 /*Vookeursmag van artikel*/ then isnull((select ArtDefaultMagGid from tabArtikel where Artgid = @ArtGid), @VanMagGid)
      end vvorMagGidNaar,
      AanmakenVerplaatsingsOpdracht_GetLocGidDestination(@Vvcr.ToLocation, @Vvcr.WhatIfLocBlocked, vvorArtGid, vvorMagGidNaar) vvorLocGidNaar,
      @Vvcr.DefLocblockedPermitted VvorLocGebloktToestaan,

      // Aantallen
      0 vvorAantalGereserveerdInVanLocInVrrdEenh, // Gaat via verkooporder, dus niet reserveren
      @AantalNaarVerplaatsing vvorAantalInVrrdEenh,
      case @Vvcr.DefNumberMoved
        when 0 /*nul*/  then 0.0
        when 1 /*AantTeVerplaatsen*/ then vvorAantalInVrrdEenh
      end VvorAantalVerwerktInVrrdEenh,

      // Referenties
      @BronRegelGid vvorMohrGidReden,
      @TbvSoort vvorTenBehoeveVan,
      if @TbvSoort = 1 /*Verkooporder*/ then @TbvGid endif vvorOrrGidtbv,

      // Overige
      @Vvcr.DefLineState vvorStatus,
      case @IsDirecteInkopen
        when 0 /*backorder*/      then _A('Directe inkoop voor verkooporder %1!/%2!', OrkNummer, repeat('0', 3-length(OrrRegelNr)) || OrrRegelNr)
        when 1 /*directeinkopen*/ then _A('Gespecificeerde backorder %1!/%2!', OrkNummer, repeat('0', 3-length(OrrRegelNr)) || OrrRegelNr)
      end vvorTbvOms,
      @Vvcr.StockMovementDescr VvorMutOmschrijving,
      @Vvcr.DefFeature         VvorKenmerk
    into local temporary table tmpVoorraadVerplaatsingVoorstelRegel // zodat we straks weten wat we echt hebben toegevoegd (zou meer records kunnen worden)
    from
      taborderregel
      inner join taborderkop on OrkGid = OrrOrkGid
    where
      OrrGid = @OrrGid
      and OrrDirecteInkoop = 1   // Alleen de directe inkopen
      and vvorAantalInVrrdEenh > 0
    ;

    insert into tabvoorraadVerplaatsingsOpdrachtRegel with auto name
    select * from tmpVoorraadVerplaatsingVoorstelRegel;

    // Gelijk erachteraan de serienummers wegschrijven
    if isnull(@serienummers, '') <> '' then
      call AanmakenVoorraadverplaatsingsOpdracht_SerienummersToevoegen(
        @vvokGid,
        isnull(@LaatsteRegel + 1, 1), // De eerste regel waar we gaan resolven is de laatsteregel+1, want number() begint bij 1
        @ArtGid,
        @ArtPartijGid,
        @serienummers,
      );
    end if;

    // Bepaal het aantal dat we via directe inkopen hebben verwerkt
    set @AantalVerwerktInVrrdEenh = @AantalVerwerktInVrrdEenhDoorMaatwerk + isnull((select sum(vvorAantalInVrrdEenh) from tmpVoorraadVerplaatsingVoorstelRegel), 0);
  else
    set @AantalVerwerktInVrrdEenh = @AantalVerwerktInVrrdEenhDoorMaatwerk;
  end if;
end;


create or replace procedure AanmakenVoorraadVerplaatsingsOpdracht_Inruimen(
  in @vvokGid                         integer,
  in @Vvcr                            TAanmakenVoorraadVerplaatsingsOpdrachtCriterium,
  in @ArtGid                          integer,
  in @ArtPartijGid                    integer,
  in @VanMagGid                       integer,
  in @VanLocGid                       integer,
  in @Serienummers                    long nvarchar,
  in @AantalNogTeVerwerkenInVrrdEenh  numeric(15,3),
  in @BronRegelGid                    integer,
  in @TbvSoort                        smallint, // 0 = Inruimen (soort Overig), 1 = verkooporder, ...
  in @TbvGid                          integer,
  out @AantalVerwerktInVrrdEenh       numeric(15,3)
)
begin
  declare @AantalVerwerktInVrrdEenhDoorMaatwerk numeric(15,3) = 0;
  declare @LaatsteRegel           integer;


  if exists(select first 1 from sys.sysprocedure where proc_name = 'MAATWERK_AanmakenVoorraadVerplaatsingsOpdracht_Inruimen') then
    begin
      // Maatwerk-haakje voor inruimen in magazijn
      // Het is mogelijk om slechts een deel in te ruimen en de rest aan destandaard routine over te laten!
      // Daartoe moet in de eigen routine het aantal worden aangepast en de laatsteregel alvast goed gezet (dat is het nummer van laatst toegevoegde regel)
      // De standaard routine zal dan de rest op gebruikelijke manier inruimen
      declare @IsStandaardRoutineOverruled smallint = 0;
      call MAATWERK_AanmakenVoorraadVerplaatsingsOpdracht_Inruimen(
        @vvokGid,
        @Vvcr,
        @ArtGid,
        @ArtPartijGid,
        @VanMagGid,
        @VanLocGid,
        @Serienummers,
        @AantalNogTeVerwerkenInVrrdEenh,
        @BronRegelGid,
        @TbvSoort,
        @TbvGid,
        @AantalVerwerktInVrrdEenhDoorMaatwerk,
        @IsStandaardRoutineOverruled = @IsStandaardRoutineOverruled
      );
      if @IsStandaardRoutineOverruled = 1 then
        set @AantalVerwerktInVrrdEenh = @AantalVerwerktInVrrdEenhDoorMaatwerk;
        leave; // Gelijk stoppen met deze procedure!
      end if;
    end;
  end if;

  select isnull(max(vvorRegelnummer), 0) into @LaatsteRegel from tabvoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @vvokGid;


  insert into tabvoorraadVerplaatsingsOpdrachtRegel with auto name
  select // Hoe omgaan met minder dan verwachte aantal??
    @vvokGid vvorvvokGid,
    isnull(@LaatsteRegel, 0) + number() vvorRegelnummer,
    @ArtGid vvorArtGid,
    @ArtPartijGid vvorArtPartijGid,

    // Van mag/locatie
    @VanMagGid vvorMagGidVan,
    @VanLocGid vvorLocGidVan,

    // Naar mag/locatie
    case @Vvcr.ToWarehouse
      when 0 /*Zelfde magazijn*/ then @VanMagGid
      when 1 /*Vookeursmag van artikel*/ then isnull(ArtDefaultMagGid, @VanMagGid)
    end vvorMagGidNaar,
    AanmakenVerplaatsingsOpdracht_GetLocGidDestination(@Vvcr.ToLocation, @Vvcr.WhatIfLocBlocked, vvorArtGid, vvorMagGidNaar) vvorLocGidNaar,
    @Vvcr.DefLocblockedPermitted VvorLocGebloktToestaan,

    // Aantallen
    @AantalNogTeVerwerkenInVrrdEenh vvorAantalGereserveerdInVanLocInVrrdEenh,
    @AantalNogTeVerwerkenInVrrdEenh vvorAantalInVrrdEenh,
    case @Vvcr.DefNumberMoved
      when 0 /*nul*/  then 0.0
      when 1 /*AantTeVerplaatsen*/ then vvorAantalInVrrdEenh
    end VvorAantalVerwerktInVrrdEenh,

    // Referenties
    @BronRegelGid vvorMohrGidReden,
    @TbvSoort vvorTenBehoeveVan,
    null vvorOrrGidTbv,

    // Overige
    @Vvcr.DefLineState vvorStatus,
    _A('Inruimen in magazijn') vvorTbvOms,
    @Vvcr.StockMovementDescr VvorMutOmschrijving,
    @Vvcr.DefFeature         VvorKenmerk

  from
    tabArtikel
  where
    ArtGid = @ArtGid
    // Op dit moment alsnog een regel aanmaken, maar dan dus zonder locatie.
//    and
//    (
//      // This might lead to something strange: from and to equal -> skip and try to 'give' the products to another target
//      // Completely acceptable for placing into regular warehouse, but NOT for eg Direct purchase
//         vvorMagGidVan <> vvorMagGidNaar
//      or vvorLocGidVan <> vvorLocGidNaar
//    );
    and vvorAantalInVrrdEenh > 0
;

  // Gelijk erachteraan de serienummers wegschrijven
  if isnull(@serienummers, '') <> '' then
    call AanmakenVoorraadverplaatsingsOpdracht_SerienummersToevoegen(
      @vvokGid,
      isnull(@LaatsteRegel + 1, 1), // De eerste regel waar we gaan resolven is de laatsteregel+1, want number() begint bij 1
      @ArtGid,
      @ArtPartijGid,
      @serienummers,
    );
  end if;



  // Bepaal het aantal dat we via wegleggen hebben verwerkt (in principe alles, tenzij we geen locatie konden vinden)
  set @AantalVerwerktInVrrdEenh = isnull((select sum(vvorAantalInVrrdEenh) from tabvoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @vvokGid and vvorRegelnummer >= @LaatsteRegel), 0);
end;


create or replace procedure AanmakenVoorraadverplaatsingsOpdracht_SerienummersToevoegen(
  in @vvokGid      integer,
  in @VanafRegel   integer, // When multiple article records are added this will ensure that the serienummers will only be added to the latest rows
  in @ArtGid       integer,
  in @ArtPartijGid integer,
  in @serienummers long nvarchar // Serienummers separated with \n
)
begin
  // Add a list of serienummers to the verplaatsingsopdrachtregels of the corresponding article and lot

  // In de voorraadverplaatsingsregelserienummer nu de serienummers wegschrijven
  for @serienummercursor AS Cursor_Serienummers CURSOR FOR
  select
    ArtSerieGid @ArtSerieGid
  from
    openstring(VALUE @serienummers) with (Serienummer nchar(20)) option (row delimited by '\n') tabSerienummers
    inner join tabArtikelSerienummer on ArtSerienummer = Serienummer and ArtSerieArtGid = @ArtGid and ArtSeriePartijGid = @ArtPartijGid
  order by
  Serienummer
  for read only do

    // Waar kunnen we dit serienummer kwijt? Eerstvolgende verplaatsingsregel van zelfde @VvokGid met zelfde order,artikel,partij, etc.
    insert into tabVoorraadVerplaatsingsOpdrachtSN with auto name
    select
      VvorGid      VvosVvorGid,
      @ArtSerieGid VvosArtSerieGid,
      1            VvosAantal
    from
      tabvoorraadVerplaatsingsOpdrachtRegel
    where
      VvorVvokGid = @vvokGid
      and  vvorRegelnummer >= @VanafRegel // Alleen voor de huidige toegevoegde regels
      and vvorArtGid = @ArtGid // Zelfde artikel
      and vvorArtPartijGid = @ArtPartijGid // Zelfde partij (Partij is bij serienummers ALTIJD ingevuld!!)
      and isnull((select count(1) from tabVoorraadVerplaatsingsOpdrachtSN where VvosVvorGid = VvorGid), 0) < vvorAantalInVrrdEenh // Niet alle serienummers zijn ingevuld, dus aanvullen

  end for;
end;



create or replace function GetNewVvckNumber()
  returns integer
begin
  // Geef hoogste + 1 of, indien niet mogelijk, een niet gebruikt nummer ergens tussendoor.
  // Indien niets beschikbaar, dan leeg teruggeven
  declare @result integer;

  // Hoogste+1, maar onder de 900 blijven!
  set @result = GenerateNextUniqueNumber('tabVoorraadVerplaatsingCriteriaKop', 'VvckNummer', '', 899, 899);

  // niet gevonden, dan eerstvolgende lege vanaf begin
  if @result is null then
    set @result = GenereerEersteUniekeNummer('tabVoorraadVerplaatsingCriteriaKop', 'VvckNummer');
    if @result >= 900 then
      set @result = null;
    end if;
  end if;
  return @result;

end;


create or replace procedure VerwerkVoorraadVerplaatsingsOpdracht
(
  @vvokNummer      integer,
  @vvorRegelnummer integer default null,  // If added, only this line will be addressed. WARNING! No locking is performed!!! (No lock check either)
  @VanVvorRegelnummer integer default null,
  @TotVvorRegelnummer integer default null,
  @SkipLock           smallint default 0 // if 1 then skip all locking
)
result
(
  vvvoVvokNummer      integer,
  vvvovvorRegelnummer integer,
  vvvoResult          integer, //0 = OK, 1 = Melding Opdracht is verwerkt, 2 = Melding Regel is/zijn verwerkt, 10 = Info, 20 = Warning (wel aangemaakt), 30 = Error (niet aangemaakt)
  vvvoResultMsg       nchar(80),    // Resultaat (korte melding)
  vvvoMsg             long nvarchar // Opmerking
)
begin
  // Status indien vvorGid == null: Goedgekeurd of Afgedrukt; status wordt op Onderhanden gezet, dan regels verwerkt, dan status op Verwerkt
  // Status indien vvorGid != null: Goedgekeurd, Afgedrukt of Onderhanden. Als laatste regel, dan wordt status op Verwerkt gezet
  // Als er een koppeling naar een verkooporderregel is:
  // - spec.regels verwijzend naar de vvorLocGidVan, dan de spec.regels updaten naar de vvorLocGidNaar (tot aan het minimum van aantal verplaatst of aantal in spec.regels)
  // - backorders worden vrijgegeven en aan de locatie gekoppeld (voor zover er meer is verplaatst dan al in de spec.regels stond)

  declare local temporary table tmpResult( // Zie resultset van deze procedure
    vvvoVvokNummer      integer,
    vvvoVvorRegelnummer integer,
    vvvoResult          integer,
    vvvoResultMsg       nchar(80),    // Resultaat (korte melding)
    vvvoMsg             long nvarchar
  );
  declare @vvokLockIsGelukt smallint = 0;
  declare _TEVERWERKEN_OPDRACHT smallint = 0;
  declare _TEVERWERKEN_REGEL    smallint = 1;
  declare _TEVERWERKEN_REGELS   smallint = 2;

  // zie Delphi unit dVoorraadVerplaatsingsOpdrachtChecks
  // LET OP! Hoe hoger, hoe ernstiger de melding!

  // Opdracht: Akkoord-meldingen
  declare __vvvoOK                        smallint = 0;
  declare __vvvoOpdrachtVerwerkt          smallint = 1;
  declare __vvvoOpdrachtStatusKlaar       smallint = 2;
  // Opdracht: Opmerkingen/waarschuwingen
  declare __vvvoOpdrachtLeeg              smallint = 20;
  declare __vvvoOpdrachtGeenGegevens      smallint = 21;
  // Opdracht: Fouten
  declare __vvvoOpdrachtOnbekend          smallint = 50;
  declare __vvvoOpdrachtInGebruik         smallint = 52;
  declare __vvvoOpdrachtOnjuisteStatus    smallint = 53;
  declare __vvvoOpdrachtAlVerwerkt        smallint = 54; // Hoeft meestal niet te worden gemeld

  // Regel: Akkoord-meldingen
  declare __vvvoRegelOK                   smallint = 100;
  declare __vvvoRegelVerwerkt             smallint = 101;
  // Regel: Info-meldingen
  declare __vvvoRegelAlVerwerkt           smallint = 110;
  // Regel: Opmerkingen/waarschuwingen
  declare __vvvoRegelVanNaarGelijk        smallint = 120;
  declare __vvvoRegelVerkooporderWeg      smallint = 122;
  declare __vvvoRegelVerkooporderInGebruik smallint = 123; // Gebruikt in VerwerkVoorraadVerplaatsingsOpdracht_BoekVoorraadVerplaatsing
  declare __vvvoRegelVerkooporderUpdateLuktNiet smallint = 124; // Gebruikt in VerwerkVoorraadVerplaatsingsOpdracht_InVerkooporder

  // Regel: Fouten
  declare __vvvoRegelOnjuisteStatus       smallint = 150;
  declare __vvvoRegelAantalIsNul          smallint = 151;
  declare __vvvoRegelAantalIsNegatief     smallint = 152;
  declare __vvvoRegelAantallenOngelijk    smallint = 153;
  declare __vvvoRegelVanMagLeeg           smallint = 154;
  declare __vvvoRegelVanLocLeeg           smallint = 155;
  declare __vvvoRegelNaarMagLeeg          smallint = 156;
  declare __vvvoRegelNaarLocLeeg          smallint = 157;
  declare __vvvoRegelNaarLocGeblokkeerd   smallint = 158;
  declare __vvvoRegelPartijLeeg           smallint = 159;
  declare __vvvoRegelSerienumTeveel       smallint = 160;
  declare __vvvoRegelVerkOrderInGebruik   smallint = 170;

  // Komen terug in vvvoResultMsg
  declare __vvvoResultMsg_OpdrachtVerwerkt     nchar(80) = _U('Opdracht verwerkt');
  declare __vvvoResultMsg_OpdrachtNietVerwerkt nchar(80) = _U('Opdracht niet verwerkt');
  declare __vvvoResultMsg_RegelVerwerkt        nchar(80) = _U('Regel verwerkt');
  declare __vvvoResultMsg_RegelNietVerwerkt    nchar(80) = _U('Regel niet verwerkt');

  declare @TeVerwerken smallint = case
                                    when @vvorRegelnummer is not null or (@VanVvorRegelnummer = @TotVvorRegelnummer) then
                                      _TEVERWERKEN_REGEL
                                    when @VanVvorRegelnummer is null and @TotVvorRegelnummer is null then
                                      _TEVERWERKEN_OPDRACHT
                                    else
                                      _TEVERWERKEN_REGELS
                                  end;


  declare _VerwerkStatus_VerwerkOpdracht  smallint = 0; // Verwerk de opdracht
  declare _VerwerkStatus_SkipRegel        smallint = 1; // Skip deze regel en ga door met de volgende
  declare _VerwerkStatus_ZetOpVerwerk     smallint = 2; // zet regelstatus op Verwerkt (Geen voorraadmutatie)
  declare _VerwerkStatus_BoekEnVerwerk    smallint = 3; // Maak voorraadmutatie + zet regelstatus op Verwerkt
  declare _VerwerkStatus_SkipHeleOpdracht smallint = 10; // Skip deze opdracht en stop

  declare @_vvokGidParam integer;   // Found header from parameter
  declare @_vvorGidParam integer;   // Found line from parameter (if applicable)

  declare @_LockResult   smallint;

  declare @MsgRegel      long nvarchar;
  declare @MsgStatus     smallint;

  declare @VerwerkStatus smallint = _VerwerkStatus_VerwerkOpdracht; // In beginsel verwerken
  declare @DoChecks      smallint;

  declare @LaatstGelockedOrKGid integer; // Buffer om niet voor elke regel steeds de order te moeten locken

  // DESIGNTIME-OPLOSSING
  if @vvokNummer = -1 /*designtime*/ then
    select
      vvvoVvokNummer, vvvovvorRegelnummer, vvvoResult, vvvoResultMsg, vvvoMsg
    from tmpResult
    order by vvvovvorRegelnummer;
    leave;
  end if;

  // Correction for single line
  if @TeVerwerken = _TEVERWERKEN_REGEL and @vvorRegelnummer is null then
    set @vvorRegelnummer = @VanVvorRegelnummer;
  end if;

  begin
    declare @vvokStatus      smallint = -1;
    declare @RegelStatusIsOk smallint = 0;
    declare @AantalRegels    integer  = 0;

    // Komplete opdracht, DUS moet de status Goedgekeurd of Afgedrukt zijn
    select vvokGid,
           vvokStatus,
           (select count(*) from tabvoorraadVerplaatsingsOpdrachtRegel where VvorVvokGid = VvokGid)
    into @_vvokGidParam, @vvokStatus, @AantalRegels
    from  tabvoorraadVerplaatsingsOpdrachtKop
    where vvokNummer = @vvokNummer;

    case @TeVerwerken

      when 0 /*_TEVERWERKEN_OPDRACHT*/ then

        if @_vvokGidParam is null then
          insert into tmpResult with auto name
          select
            @vvokNummer            vvvoVvokNummer,
            __vvvoOpdrachtOnbekend vvvoResult,
            __vvvoResultMsg_OpdrachtNietVerwerkt vvvoResultMsg,
            _U('Verplaatsingsopdracht is niet gevonden!') vvvoMsg;
           //Raiserror 20720, _U('Verplaatsingsopdracht'); //(20720) %1! niet gevonden!
          set @VerwerkStatus = _VerwerkStatus_SkipHeleOpdracht;
        end if;

        // lock zetten
        if (@VerwerkStatus = _VerwerkStatus_VerwerkOpdracht) and @SkipLock = 0 then
          call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, 'tabvoorraadVerplaatsingsOpdrachtKop', @_vvokGidParam, 5 /*seconds*/, @vvokLockIsGelukt);
          if @vvokLockIsGelukt = 0 then
            insert into tmpResult with auto name
            select
              @vvokNummer             vvvoVvokNummer,
              __vvvoOpdrachtInGebruik vvvoResult,
            __vvvoResultMsg_OpdrachtNietVerwerkt vvvoResultMsg,
              _U('Verplaatsingsopdracht is in gebruik!') vvvoMsg;
            //Raiserror 20741, _U('Verplaatsingsopdracht'); //(20741) %1! is in gebruik!
            set @VerwerkStatus = _VerwerkStatus_SkipHeleOpdracht;
          end if;
        end if;

        if (@VerwerkStatus = _VerwerkStatus_VerwerkOpdracht) and @vvokStatus = 9 /*verwerkt*/  then
          insert into tmpResult with auto name
          select
            @vvokNummer                  vvvoVvokNummer,
            __vvvoOpdrachtAlVerwerkt     vvvoResult,
            __vvvoResultMsg_OpdrachtNietVerwerkt vvvoResultMsg,
            _U('Verplaatsingsopdracht is al verwerkt!') vvvoMsg;
          //Raiserror 20760, _U('Verplaatsingsopdracht is al verwerkt'); //(20760) Ongeldige status: %1!
          set @VerwerkStatus = _VerwerkStatus_SkipHeleOpdracht;
        end if;

        if (@VerwerkStatus = _VerwerkStatus_VerwerkOpdracht) and (@vvokStatus <> 1 /*Klaar voor verplaatsen*/) then
          insert into tmpResult with auto name
          select
            @vvokNummer                  vvvoVvokNummer,
            __vvvoOpdrachtOnjuisteStatus vvvoResult,
            __vvvoResultMsg_OpdrachtNietVerwerkt vvvoResultMsg,
            _U('Verplaatsingsopdracht moet status ''Klaar voor verplaatsen'' hebben!') vvvoMsg;
          //Raiserror 20760, _U('Verplaatsingsopdracht moet status ''Klaar voor verplaatsen'' hebben'); //(20760) Ongeldige status: %1!
          set @VerwerkStatus = _VerwerkStatus_SkipHeleOpdracht;
        end if;

        // Opdracht zonder regels niet verwerken
        if (@VerwerkStatus = _VerwerkStatus_VerwerkOpdracht) and @AantalRegels = 0 then
          insert into tmpResult with auto name
          select
            @vvokNummer            vvvoVvokNummer,
            __vvvoOpdrachtLeeg     vvvoResult,
            __vvvoResultMsg_OpdrachtNietVerwerkt vvvoResultMsg,
            _U('Verplaatsingsopdracht heeft geen regels.') vvvoMsg;
          //Raiserror 20760, _U('Verplaatsingsopdracht moet status ''Klaar voor verplaatsen'' hebben'); //(20760) Ongeldige status: %1!
          set @VerwerkStatus = _VerwerkStatus_SkipHeleOpdracht;
        end if;

      when 1 /*_TEVERWERKEN_REGEL*/ then

        // Slechts een enkele regel, DUS moet die wel zijn gevonden. Gevonden GIDs worden gebruikt in de lus om deze ene regel te verwerken
        select
          vvorGid
        into @_vvorGidParam
        from  tabvoorraadVerplaatsingsOpdrachtRegel
        where vvorRegelnummer = @vvorRegelnummer
              and VvorVvokGid = @_vvokGidParam;

        if @_vvorGidParam is null then
          insert into tmpResult with auto name
          select
            @vvokNummer            vvvoVvokNummer,
            @vvorRegelnummer       vvvovvorRegelnummer,
            __vvvoOpdrachtOnbekend vvvoResult,
            __vvvoResultMsg_RegelNietVerwerkt vvvoResultMsg,
            _U('Verplaatsingsopdracht/-regel is niet gevonden!') vvvoMsg;
          //Raiserror 20720, _U('Verplaatsingsopdracht'); //(20720) %1! niet gevonden!
          set @VerwerkStatus = _VerwerkStatus_SkipHeleOpdracht;
        end if;

        if (@VerwerkStatus = _VerwerkStatus_VerwerkOpdracht) and (@vvokStatus <> 1 /*Klaar voor verplaatsen*/) then
          //Raiserror 20760, _U('Verplaatsingsopdracht moet status ''Klaar voor verplaatsen'' hebben'); //(20760) Ongeldige status: %1!
          insert into tmpResult with auto name
          select
            @vvokNummer                  vvvoVvokNummer,
            __vvvoOpdrachtOnjuisteStatus vvvoResult,
            __vvvoResultMsg_RegelNietVerwerkt vvvoResultMsg,
            _U('Verplaatsingsopdracht moet status ''Klaar voor verplaatsen'' hebben!') vvvoMsg;
          set @VerwerkStatus = _VerwerkStatus_SkipHeleOpdracht;
        end if;

    end case;

  end;

  if @VerwerkStatus = _VerwerkStatus_VerwerkOpdracht then
    // Nu de regel(s) verwerken
    for @VerplaatsingsOpdrachtRegelCursor AS CURSOR_VerplaatsingsOpdrachtRegelCursor CURSOR FOR
      select vvorGid @_vvorGid,
             VvorRegelnummer @_VvorRegelnummer,
             vvorStatus @_vvorStatus,
             vvorArtGid @_ArtGid,
             ArtSerieNrRegistreren @_ArtSerieRegistrerend,
             ArtIsPartijRegistreren + ArtSerieNrRegistreren @_ArtPartijSerieRegistrerend,
             vvorArtPartijGid @_ArtPartijGid,
             vvorMagGidVan @_MagGidVan,
             vvorLocGidVan @_LocGidVan,
             vvorMagGidNaar @_MagGidNaar,
             vvorLocGidNaar @_LocGidNaar,
             vvorAantalInVrrdEenh @_AantalInVrrdEenh,
             vvorAantalGereserveerdInVanLocInVrrdEenh @_AantalGereserveerdInVanLocInVrrdEenh,
             vvorAantalVerwerktInVrrdEenh @_AantalVerwerktInVrrdEenh,
             VvorTenBehoeveVan @_VvorTenBehoeveVan,

             // locatiegegevens VAN
             //tabLocatieVan.LocLocatietype @_VanLocLocatietype,

             // locatiegegevens NAAR
             tabLocatieNaar.LocNaam @_NaarLocNaam,
             tabLocatieNaar.LocBlokkade @_NaarLocBlokkade,
             VvorLocGebloktToestaan @_VvorLocGebloktToestaan,

             // Artikelgegevens
             ArtPrijsPer @_ArtPrijsPer,
             ArtKostprijsEx @_ArtKostprijsEx,

             // partijgegevens
             ArtPartijNummer @_ArtPartijNummer,

             // Serienummergegevens
             (select count(1) from tabVoorraadVerplaatsingsOpdrachtSN where VvosVvorGid = VvorGid) @_AantalSerienummers,
             (select list(VvosArtSerieGid, '\n') from tabVoorraadVerplaatsingsOpdrachtSN where VvosVvorGid = VvorGid) @_ListOf_ArtSerieGid,


             // Metagegevens
             VvokNummer @_VvokNummer,
             VvokBron @_vvokBron,

             //Bron = magazijnontvangst
             MohkGid @_MohkGid,

             // Bron: verkooporder
             // -Nu nog niet in gebruik-

             // tbv voorraadmutatie
             isnull(case vvokBron
                    when 0 then MohkNummer
                    //when ?? /*Leegmaken van locatie*/ then right('00' || tabMagazijnVan.MagCode, 3) || '/' || tabLocatieVan.LocNaam
                    //when ?? /*Productie*/ then ProductieKopNummer
                    end,
                    vvokNummer
                   ) @_UitleverOntvangstNr,
             isnull(OrkNummer, VvorTbvNummer) @_OrderBestelNr, // productienummer, ...

             OrkGid     @_OrkGidTbv,
             isnull(OrkNummer, if VvorTenBehoeveVan = 1 /*Verkooporder*/ then VvorTbvNummer endif)  @_OrkNummerTbv,
             vvorOrrGidTbv @_OrrGidTbv,
             OrkNawGid  @_OrkNawGidTbv,

             // overige gegevens
             VvorMutOmschrijving @_MutOmschrijving


      from tabvoorraadVerplaatsingsOpdrachtRegel
           inner join tabvoorraadVerplaatsingsOpdrachtKop on vvokGid = vvorvvokGid and vvokGid = @_vvokGidParam // Is gelijk een controle dat de regel bij de kop hoort
           left outer join tabLocatie tabLocatieNaar on tabLocatieNaar.LocGid = vvorLocGidNaar

           // Artikelgegevens
           inner join tabArtikel on ArtGid = vvorArtGid

           // Partijgegevens
           left outer join tabartikelpartij on ArtPartijGid = vvorArtpartijGid

           // Voor orderreden
           left outer join (
             tabOrderRegel
             inner join tabOrderkop on OrkGid = OrrOrkGid
             //inner join tabnaw on NawGid = OrkNawGid
           )  on OrrGid = vvorOrrGidTbv

           // Voor magazijnontvangstreden
           left outer join (tabMagazijnontvangstHistRegel inner join tabMagazijnontvangstHistKop on MohkGid = MohrMohkGid) on MohrGid = vvorMohrGidReden

           // Voor reden: locatie leegmaken
           left outer join tabMagazijn tabMagazijnVan on tabMagazijnVan.magGid = vvorMagGidVan
           left outer join tabLocatie tabLocatieVan  on tabLocatieVan.LocGid  = vvorLocGidVan

      where
          vvokGid = @_vvokGidParam
      and (@TeVerwerken = _TEVERWERKEN_OPDRACHT
           or (@TeVerwerken = _TEVERWERKEN_REGEL and vvorGid = @_vvorGidParam)
           or (@TeVerwerken = _TEVERWERKEN_REGELS and vvorRegelnummer between @VanVvorRegelnummer and @TotVvorRegelnummer)
          )

      order by
        vvorRegelnummer,
        vvorGid
    for read only
    do
      set @VerwerkStatus = _VerwerkStatus_BoekEnVerwerk;
      set @MsgRegel  = '';
      set @MsgStatus = __vvvoRegelOK;
      set @DoChecks  = 1; // Do all the checks

      if @_vvorStatus >= 9 /*Verwerkt*/ then
        // We gaan de regels die al in behandeling zijn niet nogmaals verplaatsen
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('De regel is al verwerkt.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelAlVerwerkt);
        set @Verwerkstatus = _VerwerkStatus_SkipRegel;
        set @DoChecks = 0;
      end if;

      // Van en naar gelijk? dan melden, maar wel gewoon verwerken
      if @DoChecks = 1 and (@_MagGidVan = @_MagGidNaar and @_LocGidVan = @_LocGidNaar) and (@_MagGidVan <> '' and @_LocGidVan <> '') then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('De Van en Naar magazijn/locaties zijn gelijk.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelVanNaarGelijk);
        //set @VerwerkStatus = _VerwerkStatus_ZetOpVerwerk; We gaan deze toch boeken, zelfs als de locaties gelijk zijn
      end if;

      // Orderregel is inmiddels al verdwenen? Melden maar wel doorgaan
      if @DoChecks = 1 and @_OrkGidTbv is null and @_VvorTenBehoeveVan = 1 /*Verkooporder*/ then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('De verkooporder(regel) is inmiddels verwerkt of verwijderd.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelVerkooporderWeg);
      end if;

      if @DoChecks = 1 and @_vvorStatus = 0 /*Concept*/ then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Dit is een conceptregel.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelOnjuisteStatus);
        set @Verwerkstatus = _VerwerkStatus_SkipRegel;
        set @DoChecks = 0; // Skip all other checks, wont do this line anyhow (ONLY for status >= _VerwerkStatus_SkipRegel)
      end if;

      if @DoChecks = 1 and not @_vvorStatus in (0 /*Concept*/ /*Has been checked above!!*/, 1 /*Klaar voor verplaatsen*/, 2 /*Toegewezen*/, 3 /*Onderhanden*/)  then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Verplaatsingsopdrachtregel moet status ''Klaar voor verplaatsen'', ''Toegewezen'' of ''Onderhanden'' hebben!');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelOnjuisteStatus);
        set @Verwerkstatus = _VerwerkStatus_SkipRegel;
      end if;

      // Aantal-checks
      if @DoChecks = 1 then
        case

          when @_AantalVerwerktInVrrdEenh = 0 then
            set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Aantal verplaatst is nul.');
            set @MsgStatus = greater(@MsgStatus, __vvvoRegelAantalIsNul);
            set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!

          when @_AantalVerwerktInVrrdEenh <> @_AantalInVrrdEenh then
            set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Aantal te verplaatsen en Aantal verplaatst zijn ongelijk.');
            set @MsgStatus = greater(@MsgStatus, __vvvoRegelAantallenOngelijk);
            set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!

          when @_AantalVerwerktInVrrdEenh < 0 then
            set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Aantal verplaatst moet groter dan nul zijn.');
            set @MsgStatus = greater(@MsgStatus, __vvvoRegelAantalIsNegatief);
            set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!

        end case;
      end if;

      // Van magazijn moet zijn ingevuld
      if @DoChecks = 1 and @_MagGidVan is null then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Van magazijn moet zijn ingevuld.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelVanMagLeeg);
        set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!
      end if;

      // Van locatie moet zijn ingevuld
      if @DoChecks = 1 and @_LocGidVan is null then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Van locatie moet zijn ingevuld.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelVanLocLeeg);
        set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!
      end if;

      // Naar magazijn moet zijn ingevuld
      if @DoChecks = 1 and @_MagGidNaar is null then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Naar magazijn moet zijn ingevuld.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelNaarMagLeeg);
        set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!
      end if;

      // Naar locatie moet zijn ingevuld
      if @DoChecks = 1 and @_LocGidNaar is null then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Naar locatie moet zijn ingevuld.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelNaarLocLeeg);
        set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!
      end if;

      // Naar locatie mag niet geblokkeerd zijn
      if @DoChecks = 1 and @_NaarLocBlokkade = 1 /*Geblokkeerd*/ and @_VvorLocGebloktToestaan = 0 then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Locatie %1! is geblokkeerd voor plaatsen.', @_NaarLocNaam);
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelNaarLocGeblokkeerd);
        set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!
      end if;

      if @DoChecks = 1 and @_ArtPartijSerieRegistrerend <> 0 and @_ArtPartijGid is null then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Partij is verplicht.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelPartijLeeg);
        set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!
      end if;

      if @DoChecks = 1 and @_ArtSerieRegistrerend <> 0 and @_AantalSerienummers <> 0 and @_AantalSerienummers > @_AantalVerwerktInVrrdEenh then
        set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('''Aantal serienummers'' is groter dan ''Aantal verplaatst''.');
        set @MsgStatus = greater(@MsgStatus, __vvvoRegelSerienumTeveel);
        set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt!
      end if;

      // --- Verkooporder locken indien nodig
      if @VerwerkStatus = _VerwerkStatus_BoekEnVerwerk and @_OrkGidTbv is not null then
        // Lock order
        if @LaatstGelockedOrKGid is null or @_OrkGidTbv <> @LaatstGelockedOrKGid then
          if @LaatstGelockedOrKGid is not null then
            // Orderlock vrijgeven
            call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @LaatstGelockedOrKGid);
          end if;
          // Orderlock zetten
          begin
            declare @tmp smallint;
            call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGidTbv, @tmp);
            if @tmp <> 0 then
              set @MsgRegel = @MsgRegel || if @MsgRegel <> '' then ' ' endif || _U('Verkooporder %1! is in gebruik.', @_OrkNummerTbv);
              set @MsgStatus = greater(@MsgStatus, __vvvoRegelVerkOrderInGebruik);
              set @VerwerkStatus = _VerwerkStatus_SkipRegel; // Status niet aanpassen naar Verwerkt, maar sla de regel over
            else
              // Onthouden dat we deze verkooporder gelockt hebben
              set @LaatstGelockedOrKGid = @_OrkGidTbv;
            end if;
          end;
        end if;
      end if;


      // Melding wegschrijven (als alles ok, dan wordt na afloop geschreven dat het is gelukt, dus de vvvoOK overslaan)
      if @MsgStatus <> __vvvoOK or @MsgRegel <> '' then
        begin
          //Hier bepalen we welk resultaat er terugkomt
          declare @vvvoResultMsg nchar(80) = '';
          // Mag zo niet met een case...
          if @VerwerkStatus = _VerwerkStatus_VerwerkOpdracht  then set @vvvoResultMsg = __vvvoResultMsg_OpdrachtVerwerkt     end if;
          if @VerwerkStatus = _VerwerkStatus_SkipRegel        then set @vvvoResultMsg = __vvvoResultMsg_RegelNietVerwerkt    end if;
          if @VerwerkStatus = _VerwerkStatus_ZetOpVerwerk     then set @vvvoResultMsg = __vvvoResultMsg_RegelVerwerkt        end if;
          if @VerwerkStatus = _VerwerkStatus_BoekEnVerwerk    then set @vvvoResultMsg = __vvvoResultMsg_RegelVerwerkt        end if;
          if @VerwerkStatus = _VerwerkStatus_SkipHeleOpdracht then set @vvvoResultMsg = __vvvoResultMsg_OpdrachtNietVerwerkt end if;

          insert into tmpResult(vvvoVvokNummer, vvvovvorRegelnummer, vvvoResult, vvvoResultMsg, vvvoMsg)
          values (@vvokNummer, @_VvorRegelnummer, @MsgStatus, @vvvoResultMsg, @MsgRegel);
        end;
      end if;



      // *********************************
      // *** Voorraadmutatie onthouden ***
      // *********************************
      // Aanmaken van de voorraadmutaties levert automatisch de aanpassingen in de magazijn/locatievoorraden!
      // Aantallen verplaatsen, mits van en naar zijn ingevuld, maar ook afwijken van elkaar
      // Bij uit backorder halen en directe inkopen worden misschien geen Naar meegegeven;
      // in dat geval geen voorraadmutatie, maar backorders op VanLocatie reserveren
      if @Verwerkstatus = _VerwerkStatus_BoekEnVerwerk then
        call VerwerkVoorraadVerplaatsingsOpdracht_BoekVoorraadVerplaatsing(
          // Object
          @ArtGid                   = @_ArtGid,
          @ArtPartijGid             = @_ArtPartijGid,
          @ArtPartijNummer          = @_ArtPartijNummer,
          // Van
          @MagGidVan                = @_MagGidVan,
          @LocGidVan                = @_LocGidVan,
          // Naar
          @MagGidNaar               = @_MagGidNaar,
          @LocGidNaar               = @_LocGidNaar,
          // Aantal
          @AantalInVrrdEenh         = @_AantalInVrrdEenh,
          // Artikelprijsgegevens
          @ArtKostprijsValutaNummer = @@BasisValutaNummer,
          @ArtKostprijsEx           = @_ArtKostprijsEx,
          @ArtPrijsPer              = @_ArtPrijsPer,
          // Serienummers
          @ListOf_ArtSerieGid       = @_ListOf_ArtSerieGid,
          // Oorzaak (Reden/soort)
          @MutSoort                 = 6 /*Magazijnverplaatsing*/,
          // Referenties
          @VvokNummer               = @_VvokNummer,
          @VvorNummer               = @_VvorRegelnummer,
          @UitleverOntvangstNr      = @_UitleverOntvangstNr,
          @OrderBestelNr            = @_OrderBestelNr,
          // Magazijnontvangst
          @MokGid                   = null,
          // Historische ontvangst
          @MohkGid                  = if @_vvokBron = 0 /*MagazijnOntvangst*/ then @_MohkGid endif,
          // Uitlevering
          // Verkooporder
          @OrkGid                   = @_OrkGidTbv,
          @OrrGid                   = @_OrrGidTbv,
          @OrkNawGid                = @_OrkNawGidTbv,
          @VrdMutOmschrijving       = @_MutOmschrijving,
          @IsOrderLocked            = 1, // De eventuele verkooporder is hier al gelockt
          @tmpResult                = table ref(tmpResult)
        );
      end if;

      //*************************************
      //*** Status van de regel aanpassen ***
      //*************************************
      if @VerwerkStatus in (_VerwerkStatus_ZetOpVerwerk, _VerwerkStatus_BoekEnVerwerk) then
        update tabvoorraadVerplaatsingsOpdrachtRegel
        set vvorStatus = 9 /*Verwerkt*/
        where vvorGid = @_vvorGid;
        insert into tmpResult with auto name
        select
          @vvokNummer                   vvvoVvokNummer,
          @_VvorRegelnummer             vvvovvorRegelnummer,
          __vvvoRegelVerwerkt           vvvoResult,
          __vvvoResultMsg_RegelVerwerkt vvvoResultMsg,
          _U('Regel is verwerkt.') vvvoMsg;
      end if;

    end for;

    // Lock van verkooporder vrijgeven
    if @LaatstGelockedOrKGid is not null then
      // Orderlock vrijgeven
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @LaatstGelockedOrKGid);
      set @LaatstGelockedOrKGid = null;
    end if;


    //***********************************
    //*** Status van de kop aanpassen ***
    //***********************************
    // Alleen als inmiddels elke regel op Verwerkt staat
    if @_vvokGidParam is not null and not exists(select first 1 from tabvoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @_vvokGidParam and vvorStatus < 9 /*Verwerkt*/)  then
      update tabvoorraadVerplaatsingsOpdrachtKop
      set vvokStatus = 9 /*Verwerkt*/
      where vvokGid = @_vvokGidParam;
      insert into tmpResult with auto name
      select
        @vvokNummer                        vvvoVvokNummer,
        __vvvoOpdrachtVerwerkt             vvvoResult,
        __vvvoResultMsg_OpdrachtVerwerkt   vvvoResultMsg,
        _U('De opdrachtstatus is gewijzigd naar Verwerkt.') vvvoMsg
    else
      insert into tmpResult with auto name
      select
        @vvokNummer                        vvvoVvokNummer,
        __vvvoOpdrachtStatusKlaar          vvvoResult,
        __vvvoResultMsg_OpdrachtVerwerkt   vvvoResultMsg,
        _U('De opdrachtstatus blijft op ''Klaar voor verplaatsen'' staan.') vvvoMsg;
    end if;

  end if;

  if not exists(select first 1 from tmpResult) then
    insert into tmpResult with auto name
    select
      @vvokNummer                vvvoVvokNummer,
      __vvvoOpdrachtGeenGegevens vvvoResult,
      __vvvoResultMsg_OpdrachtNietVerwerkt   vvvoResultMsg,
      _U('Er zijn geen te verwerken gegevens.') vvvoMsg;
  end if;

  //************************************************************
  //*** Lock op kop vrijgeven als we die zelf gelockt hadden ***
  //************************************************************
  if @TeVerwerken = _TEVERWERKEN_OPDRACHT and @vvokLockIsGelukt = 1 then
    // We locked, so we unlock
    call LockReleaseOnId(@@SpId, @@LoginTime, 1 /*exclusive*/, 'tabvoorraadVerplaatsingsOpdrachtKop', @_vvokGidParam);
    set @vvokLockIsGelukt = 0; // Niet meer gelockt
  end if;

  // Result teruggeven
  select
    vvvoVvokNummer, vvvovvorRegelnummer, vvvoResult, vvvoResultMsg, vvvoMsg
  from tmpResult
  order by vvvovvorRegelnummer;

exception
  when others then
    // Eerst alles dat was gelockt weer unlocken indien nodig
    if @LaatstGelockedOrKGid is not null then
      // Orderlock vrijgeven
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @LaatstGelockedOrKGid);
    end if;

    if @TeVerwerken = _TEVERWERKEN_OPDRACHT and @vvokLockIsGelukt = 1 then
      call LockReleaseOnId(@@SpId, @@LoginTime, 1 /*exclusive*/, 'tabvoorraadVerplaatsingsOpdrachtKop', @_vvokGidParam);
    end if;

    resignal;
end;


create or replace procedure VerwerkVoorraadVerplaatsingsOpdracht_BoekVoorraadVerplaatsing
(
  // Object
  in @ArtGid                   integer,
  in @ArtPartijGid             integer default null,
  in @ArtPartijNummer          nchar(20) default null, // If empty then retrieve from tabArtikelPartij.@ArtPartijGid
  // Van
  in @MagGidVan                integer,
  in @LocGidVan                integer,
  // Naar
  in @MagGidNaar               integer,
  in @LocGidNaar               integer,
  // Aantal
  in @AantalInVrrdEenh         numeric(15,3),
  // Artikelprijsgegevens
  in @ArtKostprijsValutaNummer integer,
  in @ArtKostprijsEx           numeric(15,3),
  in @ArtPrijsPer              numeric(15,3) default 1,
  // Serienummers
  in @ListOf_ArtSerieGid       long nvarchar,
  // Oorzaak (Reden/soort)
  in @MutSoort                 smallint, // Zie VrdMutSoort
  // Referenties
  in @VvokNummer               nchar(10),
  in @VvorNummer               nchar(10),
  in @UitleverOntvangstNr      nchar(10) default null,
  in @OrderBestelNr            nchar(10) default null,
  // Bestelling (geen velden)
  // Magazijnontvangst
  in @MokGid                   integer default null,
  // Historische ontvangst
  in @MohkGid                  integer default null,
  // Uitlevering
  // Verkooporder
  in @IsOrderLocked            smallint default 0,
  in @OrkGid                   integer default null,
  in @OrrGid                   integer default null,  // Indien meegegeven, dan alle spec.regels met VanMag/VanLoc wijzigen naar de NaarMag/NaarLoc (tot juiste aantal!)
  in @OrkNawGid                integer default null,
  // Extra informatie voor de voorraadmutatie(s)
  in @VrdMutOmschrijving       nchar(40),
  // Referentie naar de tabel voor de resultaten
  in @tmpResult                table ref
)
begin
  declare __vvvoRegelVerkooporderInGebruik smallint = 123;

  declare __vvvoResultMsg_OrderNietAangepast    nchar(80) = _U('Order niet aangepast');


  declare @_LockResult smallint;

  declare local temporary table tmpTabSerienummer(
    tmpArtSerieGid integer,
    tmpArtSerieNummer nchar(20)
  ) on commit preserve rows;

  // Zet eerst de serienummers in de temp tabel
  insert into tmpTabSerienummer with auto name
  select tmpArtSerieGid, ArtSerienummer tmpArtSerieNummer
  from
    openstring(VALUE @ListOf_ArtSerieGid) with (tmpArtSerieGid nchar(20)) option (row delimited by '\n') tabSerienummers
    inner join tabArtikelSerienummer on ArtSerieGid = tmpArtSerieGid;

  //*** Begincontroles ***
  //if (@MagGidVan = @MagGidNaar and @LocGidVan = @LocGidNaar) then
  //  // van = naar, dus niks te doen
  //  leave;
  //end if;

  //*************************
  //*** Gegevens opzoeken ***
  //*************************
  // --- - Partijgegevens opzoeken
  if @ArtPartijNummer is null and @ArtPartijGid is not null then
    select first ArtPartijNummer
    into @ArtPartijNummer
    from tabArtikelPartij
    where ArtPartijGid = @ArtPartijGid;
  end if;

  // --- - Orderkop vanuit orderregel opzoeken
  if @OrkGid is null and @OrrGid is not null then
    select OrrOrkGid into @OrkGid from tabOrderregel where OrrGid = @OrrGid;
  end if;

  //********************************
  //*** Voorraadmutatie plaatsen ***
  //********************************
  // (evenveel erbij als eraf, dus geen financiele boeking)
  begin
    declare @AantalNogTeVerwerken numeric(15,3) = @AantalInVrrdEenh;

    insert into tabVoorraadMutatie(
      vrdMutArtGid,              vrdMutNawGid,         vrdMutDatum,          vrdMutSoort,
      vrdMutUitleverOntvangstNr, vrdMutOrderBestelNr,  vrdMutValNummer,      vrdMutGeprijsdPer,
      vrdMutPrijsInValuta,       vrdMutHistKostprijs,  vrdMutGebruikerCode,  vrdMutJpGid,
      vrdMutOmschrijving
    )
    values(
      @ArtGid,                  @OrkNawGid,          date(now()),          @MutSoort,
      @VvokNummer,              @OrderBestelNr,      @@BasisValutaNummer,  @ArtPrijsPer,
      @ArtKostprijsEx,          @ArtKostprijsEx,     @@GebruikerCode,      null,
      @VrdMutOmschrijving
    );
    set @@VrdMutGid = @@Identity;

    if isnull(@ListOf_ArtSerieGid, '') <> '' then
      insert into tabVoorraadMutatieLocatieSerie(
        VrdMutLocVrdMutGid, VrdMutLocMagGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocSerieNummer, VrdMutLocAantal
      )
      select @@VrdMutGid, @MagGidVan, @LocGidVan, @ArtPartijNummer, tmpArtSerieNummer, -1
      from
        tmpTabSerienummer

      union all

      select @@VrdMutGid, @MagGidNaar, @LocGidNaar, @ArtPartijNummer, tmpArtSerieNummer, 1
      from
        tmpTabSerienummer
      order by 6, 5; // eerst AF, daarna BIJ en daarbinnen op serienummer

      set @AantalNogTeVerwerken = @AantalNogTeVerwerken - @@rowcount/2; // Number of added records divided by 2
    end if;

    // Restant (of geheel, als serienummers niet bekend)
    if @AantalNogTeVerwerken <> 0 then
      insert into tabVoorraadMutatieLocatieSerie(
        VrdMutLocVrdMutGid, VrdMutLocMagGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocAantal
      )
      values(
        @@VrdMutGid, @MagGidVan, @LocGidVan, @ArtPartijNummer, -@AantalNogTeVerwerken
      );
      insert into tabVoorraadMutatieLocatieSerie(
        VrdMutLocVrdMutGid, VrdMutLocMagGid, VrdMutLocLocGid, VrdMutLocPartijNummer, VrdMutLocAantal
      )
      values(
        @@VrdMutGid, @MagGidNaar, @LocGidNaar, @ArtPartijNummer, @AantalNogTeVerwerken
      );
    end if;
  end;


  // *************************************************
  // *** Voorkeurslocatie van artikel evt invullen ***
  // *************************************************
  // We kunnen hier alleen met de module Meerdere magazijnen/locaties komen, dus netjes voorkeur etc. gebruiken
  begin
    declare @ZetVoorkeurVoorPlaatsen smallint;
    declare @ZetVoorkeurVoorPicken   smallint;

    select first MagVastOntvangstEersteLocWordtVoorkeurVoorPlaatsen, MagVastOntvangstEersteLocatieWordtVoorkeurslocatie
    into @ZetVoorkeurVoorPlaatsen, @ZetVoorkeurVoorPicken
    from tabMagazijnOntvangstenVastegegevens;

    if @ZetVoorkeurVoorPlaatsen + @ZetVoorkeurVoorPicken <> 0 then
      // We moeten misschien iets vdoen volgens VGinkopen, moet wel juiste locatietype zijn natuurlijk
      update tabArtikelMagazijn
        set ArtMagLocGidVoorkeurOntvangst = isnull(ArtMagLocGidVoorkeurOntvangst, if @ZetVoorkeurVoorPlaatsen = 1 then @LocGidNaar endif),
            ArtMagDefaultLocGid           = isnull(ArtMagDefaultLocGid,           if @ZetVoorkeurVoorPicken   = 1 then @LocGidNaar endif)
      from tabLocatie
      where ArtMagArtGid = @ArtGid
        and ArtMagMagGid = @MagGidNaar
        and LocGid = @LocGidNaar
        and LocLocatietype in (3 /*bulk*/, 4 /*Pick*/)
        and (   (ArtMagLocGidVoorkeurOntvangst is null and @ZetVoorkeurVoorPlaatsen = 1)    // Alleen als er iets moet worden aangepast!
             or (ArtMagDefaultLocGid           is null and @ZetVoorkeurVoorPicken   = 1)
            );
    end if;
  end;

  //***************************************************
  //*** Betreft verkooporder: spec.regels aanpassen ***
  //***************************************************
  // Let op: uiteindelijk kan het aantal dat hier wordt aangepast anders zijn dan
  //         van de verplaatsing, omdat we dan meer/minder verplaatsen dan aanwezig in spec.regels
  // Dat doen we alleen als de bron-locatie gelijk was aan de locatie in de orderregels. Kan over meerdere spec.regels gaan
  // Bijwerken van orderregels is nodig als:
  // - de naar mag/loc is leeg (want dan is het uit backorder halen);
  //   - in orderregel DezeLevering aanpassen
  //   - al Van-locatie niet bulk/pick/voorkeur is, dan spec.regels aanmaken
  // - de orderregellocaties verwijzen al naar de van mag/loc (bijv. in geval van directe inkoop)
  //   - spec.regels omzetten tot minimum van het aantal in spec.regel en het aantal verplaatsen
  //   Dus als de regels naar een andere locatie verwijzen, dan blijven we daar gewoon vanaf!

  if @OrrGid is not null then
    // ---   Order: Stap 1: Order locken; indien niet gelukt, dan ... voorlopig exception
    if @IsOrderLocked = 0 then
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @_LockResult, 0);
      if @_LockResult <> 0 then
          insert into table ref(@tmpResult) with auto name
          select
            @vvokNummer   vvvoVvokNummer,
            @VvorNummer   vvvoVvorRegelnummer,
            __vvvoResultMsg_OrderNietAangepast vvvoResultMsg,
            __vvvoRegelVerkooporderInGebruik vvvoResult,
            _U('Verkooporder is in gebruik en is niet aangepast!') vvvoMsg;
          set @OrrGid = null;
        //call Raise(20741, _U('Verkooporder %1!', @OrderBestelNr)); // (20741) %1! is in gebruik!
      end if;
    end if;
  end if;
  if @OrrGid is not null then // OrrGid kon inmiddels weg zijn gehaald!

    // ---   Order: Stap 2: Controles uitvoeren
    // - TODO Als partij, dan moet de regelpartij gelijk zijn als partij niet mag afwijken, anders NIET verwerken
    // - TODO Als partij, maar partij op spec.regels wijken af van verplaatsing, dan net doen alsof die partijen er niet zijn?


    // ---   Order: Stap 3: aanpassen specregels (tbv directe inkopen die al op van-locatie liggen)
    // - In volgorde van partij+serienummer
    // - MOET geen partij OF dezelfde partij zijn
    // - Indien serienummer in spec.regel, dan moet die in de lijst staan OF er zijn minder serienummers in de lijst dan aantal verplaatsen
    // - Indien geen serienummer
    // - Verplaats spec.regels totdat aantal is gehaald; laatste regel wellicht opsplitsen
    begin
      call VerwerkVoorraadVerplaatsingsOpdracht_InVerkooporder(
        @OrrGid = @OrrGid,
        @ArtGid = @ArtGid,
        @ArtPartijGid = @ArtPartijGid,
        @AantalInVrrdEenh = @AantalInVrrdEenh,
        @MagGidVan  = @MagGidVan,
        @LocGidVan  = @LocGidVan,
        @MagGidNaar = @MagGidNaar,
        @LocGidNaar = @LocGidNaar,
        @ListOf_ArtSerieGid = @ListOf_ArtSerieGid,
        @VvokNummer = @VvokNummer,
        @VvorNummer = @VvorNummer,
        @tmpResult  = @tmpResult
      );
    exception when others then
      // Order was al gelockt, dus de lock eerst vrijgeven
      if @IsOrderLocked = 0 then
        call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
      end if;
      resignal;
    end;

    // ---   Order: Stap 5: Order vrijgeven
    if @IsOrderLocked = 0 then
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid);
    end if;

  end if; // @OrrGid is not null


  // Voor productie krijgen we wellicht iets vergelijkbaars als voor de verkooporders

end;



create or replace procedure VerwerkVoorraadVerplaatsingsOpdracht_InVerkooporder(
  in @OrrGid             integer,
  in @ArtGid             integer,
  in @ArtPartijGid       integer,
  in @AantalInVrrdEenh   numeric(15,3),
  in @MagGidVan          integer,
  in @LocGidVan          integer,
  in @MagGidNaar         integer,
  in @LocGidNaar         integer,
  in @ListOf_ArtSerieGid long nvarchar,
  in @VvokNummer         nchar(10),
  in @VvorNummer         nchar(10),
  in @tmpResult          table ref
)
begin
  declare __vvvoRegelVerkooporderUpdateLuktNiet smallint = 124; // Gebruikt in VerwerkVoorraadVerplaatsingsOpdracht_InVerkooporder

  declare __vvvoResultMsg_OrderNietAangepast    nchar(80) = _U('Order niet aangepast');

  declare @LusOrder integer;
  declare @BlijfZoeken smallint = 1;

  declare @ArtSerieGid integer;
  declare @ArtSerienummer nchar(20);
  declare @OrlGid integer;
  declare @ExtraOrlGid integer; // tbv splitsen
  declare @OrlMagGid integer;
  declare @OrlLocGid integer;
  declare @OrlAantal numeric(15,3);
  declare @AantalDezeRegel numeric(15,3) = 0; // Aantal dat we van de huidige lusregel nog kunnen/moeten verwerken

  declare @AllesIsVerwerkt smallint = 1; // Voor terugmelding, in beginsel is alles verwerkt


  // lijst van reeds verwerkte OrlGids
  declare local temporary table tmpOrlGedaan(
    tmpOrlGid integer
  ) on commit preserve rows;

  declare local temporary table tmpTabSerienummer(
    tmpOrder integer,
    tmpArtSerieGid integer,
    tmpArtSerieNummer nchar(20),
    tmpAantal integer
  ) on commit preserve rows;

  // Zet eerst de serienummers in de temp tabel
  insert into tmpTabSerienummer with auto name
    select number() tmpOrder, tmpArtSerieGid, ArtSerienummer tmpArtSerieNummer, 1 tmpAantal
    from
      openstring(VALUE @ListOf_ArtSerieGid) with (tmpArtSerieGid nchar(20)) option (row delimited by '\n') tabSerienummers
      inner join tabArtikelSerienummer on ArtSerieGid = tmpArtSerieGid;
    // Lege record als laatste met resterende aantal
   insert into tmpTabSerienummer with auto name
     select isnull((select count(*) from tmpTabSerienummer)+1,1) tmpOrder,
            NULL tmpArtSerieGid,
            NULL tmpArtSerieNummer,
            @AantalInVrrdEenh - (tmpOrder-1) tmpAantal
     where tmpAantal > 0;

  set @LusOrder = 0;

  // *** Lus: record per serienummer of restant ***
AantallenNaarSpecregelLoop:
  loop

    set @BlijfZoeken = 1;
    // *** LUS-framework ***

    if @AantalDezeRegel = 0 then
      // --- - Aantal van deze regel = 0 -> pak volgende record
      set @AantalDezeRegel = null;
      select first tmpOrder, tmpAantal, tmpArtSerieGid, tmpArtSerieNummer
      into @LusOrder, @AantalDezeRegel, @ArtSerieGid, @ArtSerienummer
      from tmpTabSerienummer
      where tmpOrder > @LusOrder // Alleen volgende regels verwerken
      order by tmpOrder;
      if @AantalDezeRegel is null then
        // --- - Geen regels meer over -> klaar!
        leave AantallenNaarSpecregelLoop;
      end if;
    end if;


    // *** ZOEKACTIES ***
    // --- - Serienum: Bestaat serienummer in spec?
    set @OrlGid = null;
    select first OrlGid, OrlMagGid, OrlLocGid into @OrlGid, @OrlMagGid, @OrlLocGid from tabOrderregelLocatie
    where OrlOrrGid = @OrrGid and OrlGid not in (select tmpOrlGid from tmpOrlGedaan)
      and OrlArtSerieGid = @ArtSerieGid
    order by OrlGid;

    if @OrlGid is not null then

      // ---   - JA ->
      // ---     mag/loc gelijk aan VanMag/VanLoc? (of Locgid is leeg)
      if (@OrlMagGid is null or (@OrlMagGid = @MagGidVan) )
        and (@OrlLocGid is null or (@OrlLocGid = @LocGidVan)) then
        // ---     - JA -> update specregel
        update tabOrderregelLocatie
        set OrlMagGid = @MagGidNaar, OrlLocGid = @LocGidNaar
        where OrlGid = @OrlGid;
        set  @AantalDezeRegel = @AantalDezeRegel - 1; // Serienummer verwerkt
        insert into tmpOrlGedaan(tmpOrlGid) values(@OrlGid);

      else
        // ---     - NEE -> mag/loc niet aanpassen in spec.regel; NOT RESOLVED
        set  @AantalDezeRegel = @AantalDezeRegel - 1; // Doen alsof serienummer is verwerkt
        insert into table ref(@tmpResult) with auto name
        select
          @vvokNummer   vvvoVvokNummer,
          @VvorNummer   vvvoVvorRegelnummer,
          __vvvoRegelVerkooporderUpdateLuktNiet vvvoResult,
          __vvvoResultMsg_OrderNietAangepast vvvoResultMsg,
          _U('Serienummer %1! staat in de specificatieregel van de order op een andere locatie.', @ArtSerienummer) vvvoMsg;
      end if;
      set @BlijfZoeken = 0;
      // ---     Ga verder met volgende in de loop
    end if;

    if @BlijfZoeken = 1 then

      // ---   (NEE) ->
      // ---   Bestaat VanMag/VanLoc/partij in spec zonder serienummer? (excl. al verwerkte spec.regels)
      set @OrlGid = null;
      select first OrlGid, OrlMagGid, OrlLocGid, OrlDezeLeveringVrrdEenh
      into @OrlGid, @OrlMagGid, @OrlLocGid, @OrlAantal
      from tabOrderregelLocatie
      where OrlOrrGid = @OrrGid and OrlGid not in (select tmpOrlGid from tmpOrlGedaan)
        and OrlMagGid = @MagGidVan and OrlLocGid = @LocGidVan
        and (   (OrlArtPartijGid is null and @ArtPartijGid is null)
             or (OrlArtPartijGid is null)
             or (OrlArtPartijGid = @ArtPartijGid)
            )
        and OrlArtSerieGid is null
      order by OrlArtPartijGid desc,                       // Pak eerst die MET dezelfde partij
               OrlGid;
      if @OrlGid is not null then
        // ---   - JA ->
        // ---     - splits regel: 1e regelaantal=(kleinste van spec.aantal of nu te verwerken), 2e regelaantal=restant
        begin
          call OrderRegelSpecificaties_SplitsSpecRegel(@OrlGid, lesser(@OrlAantal, @AantalDezeRegel) /*Houden we over*/, @ExtraOrlGid);
          // ---     - Pas mag/loc van 1e regel aan en vul (evt.) serienummer in
          update tabOrderregelLocatie
          set OrlArtSerieGid = isnull(@ArtSerieGid, OrlArtSerieGid), // Kan zijn dat we niet weten dat we een serienummer verplaatsen...
              OrlArtpartijGid = isnull(@ArtPartijGid, OrlArtpartijGid),
              OrlMagGid = @MagGidNaar,
              OrlLocGid = @LocGidNaar
          where OrlGid = @OrlGid;
        exception
          when others then
            // Splitsen lukt niet: Vreet exception op en ga verder met de volgende; we doen alsof we deze verwerkt hebben
            insert into table ref(@tmpResult) with auto name
            select
              @vvokNummer   vvvoVvokNummer,
              @VvorNummer   vvvoVvorRegelnummer,
              __vvvoRegelVerkooporderUpdateLuktNiet vvvoResult,
              __vvvoResultMsg_OrderNietAangepast vvvoResultMsg,
              _U('Het aantal verplaatst is geen veelvoud van de verkoopeenheid.') vvvoMsg;
        end;
        insert into tmpOrlGedaan(tmpOrlGid) values(@OrlGid); // Zelfs na exception deze niet meer opnieuw vinden
        set  @AantalDezeRegel = @AantalDezeRegel - lesser(@OrlAantal, @AantalDezeRegel); // Serienummer is verwerkt, (deel van) aantal is verwerkt
        set @BlijfZoeken = 0;
        // ---     - Ga verder met volgende in de loop
      end if;
    end if;


    if @BlijfZoeken = 1 then
      begin
        declare @MaxTeVerwerkenInVrrdEenh numeric(15,3);
        declare @VkeGid integer;
        declare @VkeMagAfwijken smallint;
        declare @AantalVrrdEenhInVerkEenh numeric(15,3);

        // --- - verwerk hooguit het aantal dat nog niet in de spec.regels zit (of 1 als serienummer):

        // ---   - Bepaal wat we mogen plaatsen: als serienummer, dan max. 1, anders max. aantal van nu te verwerken,
        //         MAAR nooit meer dan wat we nog over hebben in de verkooporder (regel-sum(spec))
        set @MaxTeVerwerkenInVrrdEenh = null;
        select lesser(OrrAantalLeveringVrrdEenh - OrrAantalTotaalLevVanDetail, @AantalDezeRegel)
        into @MaxTeVerwerkenInVrrdEenh
        from tabOrderregel
        where OrrGid = @OrrGid;
        if @MaxTeVerwerkenInVrrdEenh <= 0 then
          set @MaxTeVerwerkenInVrrdEenh = 0;
          // ---   - Niks meer te verwerken? Dan deze regel maar afsluiten
          set @AantalDezeRegel = 0; // We kunnen niks meer verwerken op deze regel, dan maar sluiten! (Anders verwerken we meer dan mogelijk)
          set @AllesIsVerwerkt = 0;
        end if;


        // ---   - Is er ruimte in de orderregel om wat aan de specregels toe te voegen?
        if @MaxTeVerwerkenInVrrdEenh > 0 then
          // ---     - JA->
          // ---       - Bepaal de eenheid obv aantal dat we willen plaatsen
          // Mogen we afwijken volgens de order?
          select OrrAantalVrrdEenhInVerkEenhMagAfwijken, OrrVkeGid, VkeAantalVoorraadEenhedenInVerkoopEenheid // of OrrAantalVrrdEenhInVerkEenh?
          into @VkeMagAfwijken, @VkeGid, @AantalVrrdEenhInVerkEenh
          from tabOrderRegel
               inner join tabVerkoopeenheid on VkeGid = OrrVkeGid
          where OrrGid = @OrrGid;

          // ---       - Past het aantal in de verkoopeenheid?
          if @VkeMagAfwijken = 1 and mod(@MaxTeVerwerkenInVrrdEenh, @AantalVrrdEenhInVerkEenh) <> 0 then
            // ---         - NEE: Overstappen naar voorraadeenheid, want het aantal past niet!
            select VkeGid, VkeAantalVoorraadEenhedenInVerkoopEenheid
            into @VkeGid, @AantalVrrdEenhInVerkEenh
            from tabVerkoopeenheid
            where VkeIsVoorraadEenheid = 1 and VkeArtGid = @ArtGid;
          end if;

          // ---       - Past het te verwerken aantal in de verkoopeenheid?
          if @VkeMagAfwijken = 1 or mod(@MaxTeVerwerkenInVrrdEenh, @AantalVrrdEenhInVerkEenh) = 0 then
            // ---         - JA: toevoegen nieuwe spec.regel op NaarMag/NaarLoc/Partij/Serienummer, eenheid = voorraadeenheid, aantal=@MaxTeVerwerkenInVrrdEenh
            insert into tabOrderRegelLocatie with auto name
            select
               @OrrGid OrlOrrGid,
               @MagGidNaar OrlMagGid,
               @LocGidNaar OrlLocGid,
               @ArtPartijGid OrlArtPartijGid,
               @ArtSerieGid OrlArtSerieGid,
               VkeGid OrlVkeGid,
               (if VkeAantalDecimalen = 4 then OrlAantDecAantalVrrdEenh else VkeAantalDecimalen endif) OrlAantDecAantal,
               (select VkeAantalDecimalen from tabVerkoopEenheid where VkeIsVoorraadEenheid = 1 and VkeArtGid = @ArtGid) OrlAantDecAantalVrrdEenh,
               @MaxTeVerwerkenInVrrdEenh / @AantalVrrdEenhInVerkEenh OrlDezeLevering,
               @MaxTeVerwerkenInVrrdEenh OrlDezeLeveringVrrdEenh
            from
              tabVerkoopEenheid
            where VkeGid = @VkeGid;
            set @OrlGid = @@Identity;

            set  @AantalDezeRegel = @AantalDezeRegel - @MaxTeVerwerkenInVrrdEenh; // Serienummer en (deel)aantal is verwerkt
            insert into tmpOrlGedaan(tmpOrlGid) values(@OrlGid);

          else
            // ---         - NEE: NIKS meer over... SERIENUMMER en/of AANTAL NOT RESOLVED
            set @AantalDezeRegel = 0; // Doen alsof serienummer is verwerkt
            set @AllesIsVerwerkt = 0; // Voor terugmelding
          end if;
        else
          // ---     - NEE: We kunnen niets meer kwijt... SERIENUMMER en/of AANTAL NOT RESOLVED
          set  @AantalDezeRegel = 0; // Doen alsof serienummer is verwerkt
          set @AllesIsVerwerkt = 0; // Voor terugmelding
        end if; //if @MaxTeVerwerkenInVrrdEenh > 0 then
      end;
    end if; //(hoort bij de end hierboven)

  end loop AantallenNaarSpecregelLoop;

  if @AllesIsVerwerkt = 0 then
    insert into table ref(@tmpResult) with auto name
    select
      @vvokNummer   vvvoVvokNummer,
      @VvorNummer   vvvoVvorRegelnummer,
      __vvvoRegelVerkooporderUpdateLuktNiet vvvoResult,
      __vvvoResultMsg_OrderNietAangepast vvvoResultMsg,
      _U('Het aantal verplaatst kan niet (geheel) in de specificatieregels worden verwerkt.') vvvoMsg;
  end if;
end;



create or replace procedure VoorraadVerplaatsingsCriteriaKopieren(
  in  @VanVvckNummer  integer,
  in  @NaarVvckNummer integer,
  in  @VvckOms        nchar(40),
  out @NaarVvckGid    integer
)
begin
  declare @VanVvckGid integer;

  // Controles
  if @NaarVvckNummer is null then
    call raise(20700, _U('Naar criteria moet zijn ingevuld.'));
  end if;

  select VvckGid into @VanVvckGid
  from tabVoorraadVerplaatsingCriteriaKop
  where VvckNummer = @VanVvckNummer;

  if @VanVvckGid is null then
    call raise(20700, _U('Criteria zijn verwijderd.'));
  end if;


  if @NaarVvckNummer >= 900 then
    call raise(20700, _U('Criteria kunnen alleen worden gekopieerd naar nummers onder de 900.'));
  end if;

  // Kan zijn dat de NAAR al bestaat! Dat levert een exception op
  insert into tabVoorraadVerplaatsingCriteriaKop with auto name
  select
    @NaarVvckNummer VvckNummer,
    VvckGeblokkeerd,
    VvckBron,
    VvckDefKopStatus,
    VvckVanLocTypes,
    now() VvckAangemaaktOp,
    @@GebruikerCode VvckAangemaaktDoor,
    @VvckOms VvckOms,
    VvckOpm
  from tabVoorraadVerplaatsingCriteriaKop
  where VvckGid = @VanVvckGid;

  set @NaarVvckGid = @@Identity;

  insert into tabVoorraadVerplaatsingCriteriaRegel with auto name
  select
    @NaarVvckGid VvcrVvckGid,
    VvcrNummer,
    VvcrBetrekkingOp,
    VvcrDefAantalVerplaatst,
    VvcrNaarMagazijn,
    VvcrNaarLocatie,
    VvcrDefKenmerk,
    VvcrDefRegelStatus,
    VvcrDefLocGebloktToestaan,
    VvcrMaxDagenNaPeildatum,
    VvcrMutOmschrijving,
    VvcrWhatIfLocBlocked
  from tabVoorraadVerplaatsingCriteriaRegel tabVanVvcr
  where tabVanVvcr.VvcrVvckGid = @VanVvckGid
  order by tabVanVvcr.VvcrNummer;

end;


create or replace procedure VoorraadVerplaatsingsCriteriaRegelChangePos(
  in  @VvckGid       integer,
  in  @VvcrGid       integer, // When @Action = 5, then this is empty
  in  @Action        smallint, //0 = first, 1 = up, 2 = down, 3 = last, 4 = insert space, 5 = delete number (so all numbers higher one down)
  in  @LineNumber    numeric(10,0) default null,
  out @NewLineNumber integer
)
begin atomic
  // Move a line up/down/top/bottom or insert at current position
  declare @FirstLineToMove numeric(10,0);
  declare @LastLineToMove  numeric(10,0);
  declare _SaveLineNumber  numeric(10,0) = 9999999999;
  declare _MaxLineNumber   numeric(10,0) = _SaveLineNumber-2; // might be increased by one!!

  if @Action <> 5 then
    // Delete has no line ID, so we use the given line number
    select VvcrVvckGid, VvcrNummer
    into   @VvckGid, @LineNumber
    from tabVoorraadVerplaatsingCriteriaRegel
    where VvcrGid = @VvcrGid and VvcrVvckGid = @VvckGid;
  end if;

  if @LineNumber is null then
    call Raise(20780, 'Regel verplaatsen', 'Regel niet gevonden!'); //(20780) %1! niet mogelijk: %2!.
  end if;

  // Let us presume nothing will change
  set @NewLineNumber = @LineNumber;

  if @Action = 4 /*Insert space between*/ then
    // This one is easy: make a gap at desired position
    update tabVoorraadVerplaatsingCriteriaRegel set VvcrNummer = VvcrNummer + 1 where VvcrVvckGid = @VvckGid and VvcrNummer >= @LineNumber order by VvcrNummer desc;
  else
    // Move line to change out of the way
    if @Action <> 5 /*Delete*/ then
      update tabVoorraadVerplaatsingCriteriaRegel set VvcrNummer = _SaveLineNumber where VvcrGid = @VvcrGid;
    end if;

    case @Action
      when 0 then // first
        if @LineNumber > 1 then
          // Update all lines between 1 and line to change (descending)
          update tabVoorraadVerplaatsingCriteriaRegel set VvcrNummer = VvcrNummer + 1 where VvcrVvckGid = @VvckGid and VvcrNummer between 1 and @LineNumber order by VvcrNummer desc;
          // Set line to correct number
          set @NewLineNumber = 1;
        end if;
      when 1 then // up
        if @LineNumber > 1 then
          // Update prior line
          update tabVoorraadVerplaatsingCriteriaRegel set VvcrNummer = @LineNumber where VvcrVvckGid = @VvckGid and VvcrNummer = @LineNumber - 1;
          // Set line to correct number
          set @NewLineNumber = @LineNumber - 1;
        end if;
      when 2 then // down
        if @LineNumber < isnull((select max(VvcrNummer) from tabVoorraadVerplaatsingCriteriaRegel where VvcrVvckGid = @VvckGid and VvcrNummer <= _MaxLineNumber), 0) then
          // Update next line
          update tabVoorraadVerplaatsingCriteriaRegel set VvcrNummer = @LineNumber where VvcrVvckGid = @VvckGid and VvcrNummer = @LineNumber + 1;
          // Set line to correct number
          set @NewLineNumber = @LineNumber + 1;
        end if;
      when 3 then // last
        if @LineNumber < isnull((select max(VvcrNummer) from tabVoorraadVerplaatsingCriteriaRegel where VvcrVvckGid = @VvckGid and VvcrNummer <= _MaxLineNumber), 0) then
          // Update all lines between line to change and last line
          update tabVoorraadVerplaatsingCriteriaRegel set VvcrNummer = VvcrNummer - 1 where VvcrVvckGid = @VvckGid and VvcrNummer between @LineNumber and _MaxLineNumber order by VvcrNummer asc;
          // Set line to correct number
          set @NewLineNumber = 1 + isnull((select max(VvcrNummer) from tabVoorraadVerplaatsingCriteriaRegel where VvcrVvckGid = @VvckGid and VvcrNummer <= _MaxLineNumber), 0);
        end if;
      when 5 then // delete
        // Update all lines after the number
        update tabVoorraadVerplaatsingCriteriaRegel set VvcrNummer = VvcrNummer - 1 where VvcrVvckGid = @VvckGid and VvcrNummer > @LineNumber order by VvcrNummer;
        // Set line to correct number
        set @NewLineNumber = @LineNumber - 1;
    end case;

    // Set line to correct number
    update tabVoorraadVerplaatsingCriteriaRegel set VvcrNummer = @NewLineNumber where VvcrGid = @VvcrGid;
  end if;

end;


create or replace procedure VoorraadVerplaatsingsOpdrachtRegelpositieVerschuiven(
 in @vvokGid integer,
 in @StartOpPositie integer default 1,   // Vanaf welk regelnummer doorschuiven (indien leeg, dan wordt 1 gebruikt!)
 in @Delta integer default 1,    // Indien leeg, dan wordt 1 gebruikt (1 doorschuiven), maar nu kan ook worden teruggeschoven indien nodig (@delta=-1)
 in @UseLocking smallint default 0, //Gebruik locking voor alle regels die gewijzigd gaan worden.
 in @LockUserNaam nchar(40) default null
)
begin
  // T.b.v. locken
  declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId wordt gebruikt
  declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime wordt gebruikt

  //call TraceBegin('VoorraadVerplaatsingsOpdrachtRegelpositieVerschuiven(@vvokkGid='+string(@vvokkGid)+', @StartOpPositie='+string(@StartOpPositie)+', @Delta='+string(@Delta)+')');
  set @Delta = IsNull(@Delta, 1);
  set @StartOpPositie = IsNull(@StartOpPositie, 1);

  //Lock de regels
  if @UseLocking = 1 then
  begin atomic
    for @Cursor AS CURSOR_RegelsLocken CURSOR FOR
      select vvorGid @_CursorVvorGid
      from tabvoorraadVerplaatsingsOpdrachtRegel
      where VvorvvokGid = @vvokGid
        and VvorRegelnummer >= @StartOpPositie
      order by VvorRegelnummer desc
    for read only
    do
      call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken(@_CursorVvorGid, @LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusive*/);
    end for;
  end;
  end if;

  //Om er voor te zorgen dat er geen deadlock kan komen updaten we het laatste record. In het geval dat er al een update bezig is zal er hier op gewacht worden.
  update top 1 tabvoorraadVerplaatsingsOpdrachtRegel set vvorGid = vvorGid where VvorvvokGid = @vvokGid order by VvorRegelnummer desc;

  update tabvoorraadVerplaatsingsOpdrachtRegel
  set VvorRegelnummer = VvorRegelnummer + @Delta
  where VvorvvokGid = @vvokGid
    and VvorRegelnummer >= @StartOpPositie
  order by VvorRegelnummer * sign(@Delta) desc; //Bij negatief moeten we vanaf de kleinste werken, anders vanaf de grootste!

  //lock vrijgeven
  if @UseLocking = 1 then
    for @Cursor AS CURSOR_RegelsVrijgeven CURSOR FOR
      select  vvokNummer @_CursorVvokNummer,
              VvorRegelnummer @_CursorVvokRegelNummer
      from tabvoorraadVerplaatsingsOpdrachtRegel
      inner join tabvoorraadVerplaatsingsOpdrachtKop on vvokgid = VvorvvokGid
      where VvorvvokGid = @vvokGid
        and VvorRegelnummer >= @StartOpPositie
      order by VvorRegelnummer desc
    for read only
    do
      call WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(@_CursorVvokNummer, @_CursorVvokRegelNummer, 1 /*Exclusive*/);
    end for;
  end if;

  //call TraceEind('VoorraadVerplaatsingsOpdrachtRegelpositieVerschuiven(@vvokkGid='+string(@vvokGid)+')');
end;


create or replace procedure VrAlterColumn(in @TabelNaam nchar(40), in @Kolomnaam nchar(40), in @Type nchar(20))
begin
  declare local temporary table tmpvr
    (
      tmpvrGid  integer,
      tmpvrVeld long nvarchar
    ) on commit preserve rows;
  declare @Exists    smallint;

  declare @OudeType nchar(100);
  //call TraceBegin('VrAlterColumn(@TabelNaam='+@TabelNaam+',  @Kolomnaam='+@Kolomnaam+', @Type='+@Type+')');

  call ColumnExist(@TabelNaam, @Kolomnaam, @Exists);

  if @Exists <> 0 then
    if (select domain_id from systabcol where column_name = @Kolomnaam) = 8 then //Alleen bij char velden
      //ACW 30-08-2012 bug #36141: Als type gelijk gebleven, dan niet alles opnieuw doen, omdat anders de webshop-synchronisatie plotseling ALLES
      //                           als Gewijzigd ziet.
      select base_type_str into @OudeType from systabcol where column_name = @Kolomnaam;
      if @OudeType <> @Type then
        execute immediate 'insert into tmpvr (tmpvrGid,tmpvrVeld) select ' +
        subStr(@TabelNaam,4,length(@TabelNaam)) + 'RecordID, ' + @Kolomnaam + ' from ' + @TabelNaam ;

        execute immediate 'alter table '+@TabelNaam+' drop '  + @kolomnaam;
        execute immediate 'alter table '+@TabelNaam+' add '   + @Kolomnaam + ' ' + @Type + ' ';

        execute immediate 'update ' + @TabelNaam + ' ' +
                          'set ' + @kolomnaam + '  = tmpvrVeld from tmpvr ' +
                          'where ' + subStr(@TabelNaam,4,length(@TabelNaam)) + 'RecordID = tmpvrgid';
      end if;
    else
      execute immediate 'alter table '+@TabelNaam+' '+
                        'modify '+@Kolomnaam+' '+@Type+' ';
    end if;
  end if;

  //call TraceEind('VrAlterColumn');

end;


create or replace procedure VrApiGetContent(
  in @VrBestandOms   nchar(3),      //NAW, ART, etc.
  in @VrGroepId      integer,       //000-999
  in @VrSubGroepId   integer,       //000-999
  in @FieldList      long nvarchar,  // Vrije rubriek veldnamen gescheiden door een komma
  in @WhereClause    long nvarchar default '' // Optionele where-parameter (tbv. performance beter om de where alvast mee te geven)
)
begin
  set @FieldList = replace(@FieldList, ',', '\n');
  call VrGetContentByQuery(VrGetContentQuery(@VrBestandOms, @VrGroepId, @VrSubGroepId, @FieldList, @WhereClause, '' /*order by*/, '' /*AddAsResult*/, 1 /*Fields=Identifiers*/, 0 /*Fields must exist*/));
end;


create or replace procedure VrApiGetFields(
  in @VrBestandOms   nchar(3),      //NAW, ART, etc.
  in @VrGroepId      integer,       //000-999
  in @VrSubGroepId   integer        //000-999
)
result (
  UserFriendlyName nchar(80),
  ApiName nchar(80),
  FieldId nchar(80),
  DbType nchar(40)
)
begin
  //declare @VrTableName nchar(80);
  declare @sql long nvarchar;

  // Bij API wordt niet gecontroleerd of de tabel bestaat; als niet gevonden, dan leeg resultaat teruggeven ipv fout
  //set @VrTableName = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);
  //if not exists(select 1 from systable where table_name = @VrTableName) then
  //  raiserror 20541; //Vrije rubrieken tabel niet gevonden!
  //end if;

  select
    VrLabel UserFriendlyName,
    nchar2tag(VrLabel) + (if (ROW_NUMBER(*) over AantalWindow ) > 1 then '_' || (ROW_NUMBER(*) over AantalWindow) -1 else '' endif) ApiName,
    VrVeldNaam as FIELD_ID,
    (select sys.sysdomain.domain_name ||
     case sys.sysdomain.domain_id
       when 2 then '' // integer
       when 3 then '('||width||','||scale||')' // numeric
       when 7 then '('||width||')' // char, char, nchar, nchar
       when 8 then '('||width||')' // char, char, nchar, nchar
       when 12 then '('||width||')' // var char
       when 33 then '('||width||')' // nchar, nchar
       when 34 then '('||width||')' // nchar
       when 35 then '('||width||')' // varnchar
      else ''
     end
     from sys.syscolumn
          inner join sys.sysdomain on sys.sysdomain.domain_id = sys.syscolumn.domain_id
     where sys.syscolumn.column_name = VrVeldNaam
    )

  from tabVrijeRubrieken
  where VrBestandOms = @VrBestandOms and VrGroepId = @VrGroepId and VrSubGroepId = @VrSubGroepId
  window AantalWindow as (partition by nchar2tag(VrLabel) order by VrLabel)
  order by VrLabel
//  execute immediate @sql;
end;

//---- procedure creeert een kolom voor de vrije rubrieken van naw
create or replace procedure VrCreateColumn(in @TabelNaam nchar(40), in @Kolomnaam nchar(40), in @Type nchar(20))
begin
  declare @Exists    smallint;

  //call TraceBegin('VrCreateColumn(@TabelNaam='+@TabelNaam+',  @Kolomnaam='+@Kolomnaam+', @Type='+@Type+')');

  call ColumnExist(@TabelNaam, @Kolomnaam, @Exists);

  if @Exists = 0 then
    execute immediate 'alter table '+@TabelNaam+' '+
                      'add '+@Kolomnaam+' '+@Type+' ';
  end if;

  //call TraceEind('VrCreateColumn');

end;


create or replace procedure VrCreateIndex(in @TabelNaam nchar(40), in @Kolomnaam nchar(40))
begin
  declare @Exists    smallint;
  declare @IndexNaam nchar(40);

  set @@ErrorTextProcedure = 'VrCreateIndex > @TabelNaam='+@TabelNaam+', @Kolomnaam='+@Kolomnaam;
  //call TraceBegin(@@ErrorTextProcedure);

  set @IndexNaam = 'IDX_'+ @Kolomnaam;

  call IndexExist(@IndexNaam, @Exists);

  if @Exists = 0 then
    execute immediate 'create index '+@IndexNaam+' ' +
                      'on '+@TabelNaam+' ( '+@Kolomnaam+' ) ';
  end if;

  set @@ErrorTextProcedure = 'VrCreateIndex > @Indexnaam='+@Indexnaam;
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure VrCreateTable(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer, in @TabelNaam nchar(40),
															 in @MasterTabelnaam nchar(40), in @MasterTabelRecordVeldnaam nchar(40))
begin
  declare @Exists           smallint;
  declare @GroepNaam        nchar(30);
  declare @RecordVeldNaam   nchar(40);
  declare @LastModifiedNaam nchar(40);
  declare @ForeignKeyName   nchar(20);
  declare @ProcName         nchar(40);
  declare @_CreateTable long nvarchar = '';
  set @@ErrorTextProcedure = 'VrCreateTable > @VrBestandOms='+@VrBestandOms+', @VrGroepId='+string(@VrGroepId)+', @VrSubGroepId='+string(@VrSubGroepId);
  //call TraceBegin(@@ErrorTextProcedure);

  call TableExist(@TabelNaam, @Exists);

  if @Exists = 0 then

    set @RecordVeldnaam   = VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);
    set @LastModifiedNaam = VrLastModifiedNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

    set @ForeignKeyName = 'FK_VR' + @VrBestandOms  +
                           right(repeat('0', 3) + string(@VrGroepId)   , 3) +
                           right(repeat('0', 3) + string(@VrSubGroepId), 3) ;

    select distinct group_name into @GroepNaam from sys.sysgroups where group_name not in ('public', 'dbo', 'sys');
    set @_CreateTable = 'create table '+@GroepNaam+'.'+@TabelNaam+' '+
                        '(' + @RecordVeldnaam + ' integer not null, '+
                        @LastModifiedNaam + ' timestamp null default timestamp, '+
                        ' primary key ('+ @RecordVeldnaam + ')';

    if isNull(@MasterTabelNaam,'') <> '' then
      set @_CreateTable = @_CreateTable + ', foreign key '+ @ForeignKeyName +' ('+ @RecordVeldnaam + ') references ' + @MasterTabelNaam + ' (' + @MasterTabelRecordVeldNaam + ') on delete cascade' ;
    end if;

    set @_CreateTable = @_CreateTable + ')';

    execute immediate @_CreateTable;
    execute immediate 'grant select, insert, update, delete on ' || @TabelNaam || ' to KingWebservice';

    call CreateDynamicTriggersStaticPart(0 /* niet verwijderen */, @TabelNaam);
    call CreateDynamicTriggersVars();

    //Vve 13-12-2005 #19048: Een soort event idee om triggers te kunnen maken.
    set @ProcName='VrEvent_'+@VrBestandOms+'_AfterTableCreate';
    if exists (select 1 from sys.sysProcedure where proc_name=@ProcName) then
      //let op: parameters worden allemaal als string doorgestuurd, anders krijg je het niet uitgevoerd via execimm.
      execute immediate 'call '+ @ProcName + '('''+@VrBestandOms + ''', '''+ string(@VrGroepId) + ''', ''' + string(@VrSubGroepId) + ''', ''' + @TabelNaam+ ''')';
    end if;

    //ACW defect 51589: Ook alle rechten weer uitdelen, zodat deze tabel beschikbaar wordt voor ODBC
    call RefreshAllUserRights();

  end if;

  set @@ErrorTextProcedure = 'VrCreateTable';
  //call TraceEind(@@ErrorTextProcedure);

end;


//---- procedure verwijdert een vrije rubriek voor naw aan
create or replace procedure VrDelete(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer, in @VrGid integer, in @VrVeldNaam nchar(40))
begin
  declare @Exists    smallint;
  declare @TabelNaam nchar(40);
  declare @MutatieLog smallint = 0;

  set @@ErrorTextProcedure = 'VrDelete > @VrBestandOms='+@VrBestandOms+', @VrGroepId='+string(@VrGroepId)+', @VrSubGroepId='+string(@VrSubGroepId);
  //call TraceBegin(@@ErrorTextProcedure);

  set @TabelNaam = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

  // 20099 : De tabel van de vrije rubrieken moet door mezelf gelocked zijn !
  if LockedById(@@SpId, @@LoginTime, 1, @TabelNaam, '') = 0 then
    raiserror 20099;
  end if;

  delete from tabVrijeRubrieken where vrGid = @VrGid;

  call VrDeleteColumn(@TabelNaam, @VrVeldnaam);

  //--- controleren of er nog rubrieken zijn
  set @Exists = null;
  select first 1 into @Exists
  from   tabVrijeRubrieken
  where  vrBestandOms = @VrBestandOms and vrGroepId = @VrGroepId and vrSubGroepId = @VrSubGroepId;

  set @MutatieLog = if exists(select 1 from tabMutatieLogInstellingen
                                inner join tabMutatieLogGroep on MugGid = MuiMugGid
                                inner join tabMutatieLogTabel on MutMugGid = MugGid
                                where (MutTabelNaam = @TabelNaam) or ((MutIsPrefix = 1) and (Left(@TabelNaam, Length(MutTabelNaam)) = MutTabelNaam))
                              ) then 1 else 0 endif;

  if @MutatieLog = 1 then
    call MutatieLog_DisableTable(@TabelNaam);
  end if;

  //--- geen rubrieken --> tabel weggooien
  if IsNull(@Exists, 0) = 0 then
    call VrDropTable(@TabelNaam);
  else
    if @MutatieLog = 1 then
      call MutatieLog_EnableTable(@TabelNaam);
    end if;
  end if;

  set @@ErrorTextProcedure = 'VrDelete';
  //call TraceEind(@@ErrorTextProcedure);

end;


//---- procedure verwijdert een kolom voor de vrije rubrieken van naw
create or replace procedure VrDeleteColumn(in @TabelNaam nchar(40), in @Kolomnaam nchar(40))
begin
  declare @Exists    smallint;

  //call TraceBegin('VrDeleteColumn(@TabelNaam='+@TabelNaam+',  @Kolomnaam='+@Kolomnaam+')');

  call ColumnExist(@TabelNaam, @Kolomnaam, @Exists);

  if @Exists <> 0 then
    call VrDropIndex('IDX_'+ @Kolomnaam);
    execute immediate 'alter table '+@TabelNaam+' delete '+@Kolomnaam+' ';
  end if;

  //call TraceEind('VrDeleteColumn');

end;


//---- procedure verwijdert een index voor de vrije rubrieken van naw
