begin
  declare @Exists    smallint;

  //call TraceBegin('VrDropIndex(@IndexNaam='+@IndexNaam+')');

  call IndexExist(@IndexNaam, @Exists);

  if @Exists <> 0 then
    execute immediate 'drop index '+@IndexNaam+' ';
  end if;

  //call TraceEind('VrDropIndex --> @Indexnaam='+@IndexNaam+')');

end;


//---- procedure verwijdert een tabel voor de vrije rubrieken van naw
create or replace procedure VrDropTable(in @TabelNaam nchar(40))
begin
  declare @Exists    smallint;

  set @@ErrorTextProcedure = 'VrDropTable > @TabelNaam='+@TabelNaam;
  //call TraceBegin(@@ErrorTextProcedure);

  call TableExist(@TabelNaam, @Exists);

  if @Exists <> 0 then
    execute immediate 'drop table '+@TabelNaam;
