  set @@ErrorTextProcedure = 'VrDropTable';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure VrEvent_ADR_AfterTableCreate(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer, in @TabelNaam nchar(40))
begin
  declare @TriggerStatement long nvarchar;
  declare @TriggerName      nchar(40);
  declare @FonGid           integer;
  declare @TriggerEnabled   smallint;

  set @@ErrorTextProcedure='VrEvent_ADR_AfterTableCreate > @VrBestandOms='+@VrBestandOms+'; @VrGroepId='+string(@VrGroepId)+ '; @VrSubGroepId='+string(@VrSubGroepId)+ '; @TabelNaam='+@TabelNaam;
  //call TraceBegin(@@ErrorTextProcedure);


  //Vve 14-12-2005 #19048: Als er vrije rubrieken bij een verzendadres worden aangemaakt, willen we dat wijzigingen in de vrije rubriek data,
  // worden gezien als een mutatie bij de debiteur zodat die debiteur gesynchroniseerd wordt met de webwinkel.
  //Dit hoeft alleen bij debiteuren, en alleen als de betreffende debiteur op webklant staat.
  select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';
  if @VrGroepId = @FonGid then
    set @TriggerName = WebTriggerNaam(@TabelNaam, 'XmlDebiteuren');
    if exists (select 1 from sys.sysTrigger where trigger_name=@TriggerName) then
      //call Trace('VrEvent_ADR_AfterTableCreate oude trigger verwijderen');
      set @TriggerStatement = 'drop trigger ' + @TriggerName;
      execute immediate @TriggerStatement;
    end if;

    // Bepalen of de trigger aangemaakt moet worden volgens Vaste gegevens webwinkel (tabJobRegel) - qcExpSoort_XmlDebiteuren = 20
    select max(jobrEnabled) into @TriggerEnabled from tabJobRegel inner join tabJobKop on JobrJobkGid = JobkGid where jobkNummer <= -1 and JobkSoort = 1 and JobrExpSoortGid = 20;

    if @TriggerEnabled = 1 then
      //We moeten via de pk van de vrijerubrieken tabel naar tabAdres en dan naar een NawFilnummer.
      //Dit RecordID is gekoppeld aan tabAdres.Adrgid
      set @TriggerStatement = 'create trigger ' + @TriggerName + ' after insert, update order 20 on ' + @TabelNaam +char(13) +
                              'referencing new as New_Record for each row ' + char(13) +
                              'begin ' + char(13) +
                              '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                              '//call TraceBegin(@@ErrorTextTrigger);' + char(13) +

                              '  if (IsModuleActive(''w1'') <> 0) then ' + char(13) +
                              '    insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, wqWscGid) ' + char(13) +
                              '    select 0, NawFilNummer, 0, WnawWscGid from tabNawFile inner join tabWebNaw on WnawNawGid = NawFilNawGid inner join tabAdres on AdrNawGid = NawFilNawGid '+ char(13) +
                              '    where AdrGid=New_Record.' + VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId)+ ' and NawFilWebNaw=1;' + char(13) +
                              '  end if;'+ char(13) +

                              '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                              '//call TraceEind(@@ErrorTextTrigger);' + char(13) +
                              'end;';

      //call Trace('VrEvent_ADR_AfterTableCreate nieuwe trigger opvoeren');
      execute immediate @TriggerStatement;
    end if;
  end if;

  set @@ErrorTextProcedure='VrEvent_ADR_AfterTableCreate';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure VrEvent_ART_AfterTableCreate(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer, in @TabelNaam nchar(40))
begin
  declare @TriggerStatement long nvarchar;
  declare @TriggerName      nchar(40);
  declare @TriggerEnabled   smallint;

  set @@ErrorTextProcedure='VrEvent_ART_AfterTableCreate > @VrBestandOms='+@VrBestandOms+'; @VrGroepId='+string(@VrGroepId)+ '; @VrSubGroepId='+string(@VrSubGroepId)+ '; @TabelNaam='+@TabelNaam;
  //call TraceBegin(@@ErrorTextProcedure);


  //Vve 14-12-2005 #19048: Als er vrije rubrieken bij een artikel worden aangemaakt, willen we dat wijzigingen in de vrije rubriek data,
  // worden gezien als een mutatie bij het artikel zodat dat artikel gesynchroniseerd wordt met de webwinkel.
  //Dit hoeft alleen bij artikelen die op webartikel staan.
  set @TriggerName = WebTriggerNaam(@TabelNaam, 'XmlArtikelen');
  if exists (select 1 from sys.sysTrigger where trigger_name=@TriggerName) then
    //call Trace('VrEvent_ART_AfterTableCreate oude trigger verwijderen');
    set @TriggerStatement = 'drop trigger ' + @TriggerName;
    execute immediate @TriggerStatement;
  end if;

  // Bepalen of de trigger aangemaakt moet worden volgens Vaste gegevens webwinkel (tabJobRegel) - qcExpSoort_XmlArtikelen = 18
  select max(jobrEnabled) into @TriggerEnabled from tabJobRegel inner join tabJobKop on JobrJobkGid = JobkGid where JobkSoort = 1 and JobrExpSoortGid = 18;

  if @TriggerEnabled = 1 then
    //We moeten via de pk van de vrijerubrieken tabel naar een Artikelcode.
    //Dit RecordID is gekoppeld aan tabArtikel.ArtGid
    set @TriggerStatement = 'create trigger ' + @TriggerName + ' after insert, update order 20 on ' + @TabelNaam +char(13) +
                            'referencing new as New_Record for each row ' + char(13) +
                            'begin ' + char(13) +
                            '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                            '//call TraceBegin(@@ErrorTextTrigger);' + char(13) +

                           '  if (IsModuleActive(''w1'') <> 0) then ' + char(13) +
                            '    insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, WqWscGid) ' + char(13) +
                            '    select 0, ArtCode, 2, WartWscGid from tabArtikel inner join tabWebArtikel on WartArtGid = ArtGid ' + char(13) +
                            '    where ArtGid = New_Record.' + VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId)+ ' and ArtWebArtikel=1;' + char(13) +
                            '  end if;'+ char(13) +

                            '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                            '//call TraceEind(@@ErrorTextTrigger);' + char(13) +
                            'end;';

    //call Trace('VrEvent_ART_AfterTableCreate nieuwe trigger opvoeren');
    execute immediate @TriggerStatement;
  end if;

  set @@ErrorTextProcedure='VrEvent_ART_AfterTableCreate';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure VrEvent_CP_AfterTableCreate(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer, in @TabelNaam nchar(40))
begin
  declare @TriggerStatement long nvarchar;
  declare @TriggerName      nchar(40);
  declare @FonGid           integer;
  declare @TriggerEnabled   smallint;

  set @@ErrorTextProcedure= 'VrEvent_CP_AfterTableCreate > @VrBestandOms='+@VrBestandOms+'; @VrGroepId='+string(@VrGroepId)+ '; @VrSubGroepId='+string(@VrSubGroepId)+ '; @TabelNaam='+@TabelNaam;
  //call TraceBegin(@@ErrorTextProcedure);


  //Vve 14-12-2005 #19048: Als er vrije rubrieken bij een contactpersoon worden aangemaakt, willen we dat wijzigingen in de vrije rubriek data,
  // worden gezien als een mutatie bij de debiteur zodat die debiteur gesynchroniseerd wordt met de webwinkel.
  //Dit hoeft alleen bij debiteuren, en alleen als de betreffende debiteur op webklant staat.
  select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';
  if @VrGroepId = @FonGid then
    set @TriggerName = WebTriggerNaam(@TabelNaam, 'XmlDebiteuren');
    if exists (select 1 from sys.sysTrigger where trigger_name=@TriggerName) then
      //call Trace('VrEvent_CP_AfterTableCreate oude trigger verwijderen');
      set @TriggerStatement = 'drop trigger ' + @TriggerName;
      execute immediate @TriggerStatement;
    end if;

    // Bepalen of de trigger aangemaakt moet worden volgens Vaste gegevens webwinkel (tabJobRegel) - qcExpSoort_XmlDebiteuren = 20
    select max(jobrEnabled) into @TriggerEnabled from tabJobRegel inner join tabJobKop on JobrJobkGid = JobkGid where JobkSoort = 1 and JobrExpSoortGid = 20;

    if @TriggerEnabled = 1 then
      //We moeten via de pk van de vrijerubrieken tabel naar contactpersoon en naar een NawFilnummer.
      //Dit RecordID is gekoppeld aan tabRelatie.relgid
      set @TriggerStatement = 'create trigger ' + @TriggerName + ' after insert, update order 20 on ' + @TabelNaam +char(13) +
                              'referencing new as New_Record for each row ' + char(13) +
                              'begin ' + char(13) +
                              '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                              '//call TraceBegin(@@ErrorTextTrigger);' + char(13) +

                              '  if (IsModuleActive(''w1'') <> 0) then ' + char(13) +
                              '    insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, wqWscGid) ' + char(13) +
                              '    select 0, NawFilNummer, 0, WnawWscGid from tabNawFile inner join tabWebNaw on WnawNawGid = NawFilNawGid inner join tabRelatie on RelNawGid=NawFilNawGid' + char(13) +
                              '    where RelGid=New_Record.' + VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId)+ ' and NawFilWebNaw=1;' + char(13) +
                              '  end if;'+ char(13) +

                              '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                              '//call TraceEind(@@ErrorTextTrigger);' + char(13) +
                              'end;';

      //call Trace('VrEvent_CP_AfterTableCreate nieuwe trigger opvoeren');
      execute immediate @TriggerStatement;
    end if;
  end if;

  set @@ErrorTextProcedure='VrEvent_CP_AfterTableCreate';
  //call TraceEind(@@ErrorTextProcedure);
end;


/*
Vve 14-12-2005:

                          goed opletten!



Nieuw systeem om triggers op vrijerubrieken-tabellen te kunnen zetten. Dit was initeel nodig wegens bug #19048.

Probleem was: Je kan pas een trigger maken als de tabel bestaat. De tabel wordt echter door de eindgebruiker
aangemaakt. Dit kan dus niet zomaar even in AdmTriggers erbij gezet worden.

Wat hebben we dus nodig: Op het moment dat de 1e vrije rubriek wordt toegevoegd, wordt de tabel gemaakt. Op dat
moment moet eigenlijk ook meteen een trigger gemaakt worden.

Oplossing: Een soortement event-systeem, die kijkt of er een storedproc is met een bepaalde, voorafgesproken naam.
Als deze bestaat wordt die aangeroepen.

Het aanmaken vd tabel zit in AdmVrijeRubrieken.sql, in VrCreateTable. Hierin wordt nu het eerst event gepolled,
namelijk het "AfterTableCreate"-event. Dit event moet de volgende naam hebben:
VrEvent_<BestandsOms>_AfterTableCreate
en het event heeft 4 parameters, BestandsOms, GroepId, SubgroepId en TabelNaam (zie voorbeelden).
Net als bij Delphi moet je dus zorgen dat je procedure-signature overeen komt met wat het event verwacht.

In dat event (=storedproc) bouwen we nu een trigger-statement op, wat met execute immediate wordt opgevoerd aan
de database. Zoals te zien is aan de huidige events, is het goed opletten op de quootjes, haakjes en enters.

BELANGRIJK:
DBDelta ziet deze eventprocs vanzelf als gewijzigd. Echter: Als de *trigger* gewijzigd wordt, is deze natuurlijk
niet meteen doorgevoerd! Daarvoor moet je dus na elke trigger-wijziging een stukje script in ManualAdmScripts zetten,
zodat de trigger opnieuw wordt opgevoerd bij bestaande klanten. Dit kan je doen door het event simpelweg aan te roepen.

      call VrEvent_NAW_AfterTableCreate('NAW',1,1,'tabVrNAW001001');
      call VrEvent_ADR_AfterTableCreate('ADR',1,1,'tabVrADR001001');
      call VrEvent_CP_AfterTableCreate('CP',1,1,'tabVrCP001001');
      call VrEvent_ART_AfterTableCreate('ART',0,0,'tabVrArt000000');

//Vve 13-11-2007 : Je kan nu ook in 1x alles activeren vanuit ManualAdmScripts via

      call VrOpvoerenTriggers;


*/

create or replace procedure VrEvent_NAW_AfterTableCreate(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer, in @TabelNaam nchar(40))
begin
  declare @TriggerStatement long nvarchar;
  declare @TriggerName      nchar(40);
  declare @FonGid           integer;
  declare @TriggerEnabled   smallint;

  set @@ErrorTextProcedure = 'VrEvent_NAW_AfterTableCreate > @VrBestandOms='+@VrBestandOms+'; @VrGroepId='+string(@VrGroepId)+ '; @VrSubGroepId='+string(@VrSubGroepId)+ '; @TabelNaam='+@TabelNaam;
  //call TraceBegin(@@ErrorTextProcedure);


  //Vve 14-12-2005 #19048: Als er vrije rubrieken bij een debiteur worden aangemaakt, willen we dat wijzigingen in de vrije rubriek data,
  // worden gezien als een mutatie bij de debiteur zodat die debiteur gesynchroniseerd wordt met de webwinkel.
  //Dit hoeft alleen bij debiteuren, en alleen als de betreffende debiteur op webklant staat.
  select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';
  if @VrGroepId = @FonGid then
    set @TriggerName = WebTriggerNaam(@TabelNaam, 'XmlDebiteuren');
    if exists (select 1 from sys.sysTrigger where trigger_name=@TriggerName) then
      //call Trace('VrEvent_NAW_AfterTableCreate oude trigger verwijderen');
      set @TriggerStatement = 'drop trigger ' + @TriggerName;
      execute immediate @TriggerStatement;
    end if;

    // Bepalen of de trigger aangemaakt moet worden volgens Vaste gegevens webwinkel (tabJobRegel) - qcExpSoort_XmlDebiteuren = 20
    select max(jobrEnabled) into @TriggerEnabled from tabJobRegel inner join tabJobKop on JobrJobkGid = JobkGid where jobkNummer <= -1 and JobkSoort = 1 and JobrExpSoortGid = 20;

    if @TriggerEnabled = 1 then
      //We moeten via de pk van de vrijerubrieken tabel naar een NawFilnummer.
      //Dit RecordID is gekoppeld aan tabnaw.NawGid.
      set @TriggerStatement = 'create trigger ' + @TriggerName + ' after insert, update order 20 on ' + @TabelNaam +char(13) +
                              'referencing new as New_Record for each row ' + char(13) +
                              'begin ' + char(13) +
                              '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                              '//call TraceBegin(@@ErrorTextTrigger);' + char(13) +

                              '  if (IsModuleActive(''w1'') <> 0) then ' + char(13) +
                              '    insert into tabWebQueue(wqActie, wqRecordId, wqRecordSoort, wqWscGid) ' + char(13) +
                              '    select 0, NawFilNummer, 0, WnawWscGid from tabNawFile inner join tabWebNaw on WnawNawGid = NawFilNawGid' + char(13) +
                              '    where NawFilNawGid=New_Record.' + VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId)+ ' and NawFilWebNaw=1;' + char(13) +
                              '  end if;'+ char(13) +

                              '  set @@ErrorTextTrigger = '''+@TriggerName+''';' + char(13) +
                              '//call TraceEind(@@ErrorTextTrigger);' + char(13) +
                              'end;';

      //call Trace('VrEvent_NAW_AfterTableCreate nieuwe trigger opvoeren');
      execute immediate @TriggerStatement;
    end if;
  end if;

  set @@ErrorTextProcedure = 'VrEvent_NAW_AfterTableCreate';
  //call TraceEind(@@ErrorTextProcedure);
end;


