//Let op! Gebruikt message 20679;
create or replace function VrGetContentQuery(
  in @VrBestandOms          nchar(3),      //NAW, ART, etc.
  in @VrGroepId             integer,       //000-999
  in @VrSubGroepId          integer,       //000-999
  in @FieldList             long nvarchar, // Vrije rubriek veldnamen gescheiden door een \n (dus een array): USB poorten\n
  in @WhereClause           nchar(250),    // Optionele where-clausule; velden hierin worden met { en } om het veldlabel aangegeven!
  in @OrderByClause         nchar(250),    // Optionele order by -clausule; velden hierin worden met { en } om het veldlabel aangegeven!
  in @AddAsResult           integer default 0, // 0 = geen extra velden, 1=LastModified
  in @FielListIsIdentifiers smallint default 0, //0 = fieldlist = user-friendly labels, 1 = fieldlist = fieldname (VRNAW001001veld123)
  in @VeldenMoetenBestaan   smallint  default 1 // 0=Als veld niet bestaat, dan wordt met (NULL) gewerkt, anders volgt een fout
) returns long nvarchar
begin
  //declare @VeldenMoetenBestaan smallint = 1; // Voorlopig altijd aan, dus altijd een foutmelding geven
  declare @VeldKenmerkBegin    nchar(1) = '{';
  declare @VeldKenmerkEind     nchar(1) = '}';

  declare @VrTabelNaam         nchar(40);
  declare @Veldenlijst         long nvarchar;
  declare @ResultsetLabel      nchar(80);
  declare @VrLabel             nchar(40);
  declare @VrVeldNaam          nchar(100);

  declare @VrTabelBestaat      smallint = 1;



  set @@errorTextProcedure = 'VrGetContent';
  //call traceBegin(@@errorTextProcedure);
  //call trace('@FieldList      = '+ @FieldList    );
  //call trace('@WhereClause    = '+ @WhereClause  );
  //call trace('@OrderByClause  = '+ @OrderByClause);

  // Zorg ervoor dat kwootjes goed worden neergezet
  //set @FieldList      = replace(@FieldList    , '''', '''''');
  //set @WhereClause    = replace(@WhereClause  , '''', '''''');
  //set @OrderByClause  = replace(@OrderByClause, '''', '''''');


  set @VrTabelNaam = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);
  // Controle overslaan als fields niet verplicht moeten bestaan en het betreft API (want dan hoeft de tabel ook niet te bestaan)
  if not exists(select 1 from systable where table_name = @VrTabelNaam) then
    if @VeldenMoetenBestaan = 0 and @FielListIsIdentifiers = 1 then
      set @VrTabelBestaat = 0;
    else
      call Raise(20541); //Vrije rubrieken tabel niet gevonden!
    end if;
  end if;

  // List uitpluizen en voor elke rubriek de namenlijst aanvullen, te beginnen met een LastModifed
  set @Veldenlijst = '';

  begin
    declare @Veldnaam        nchar(40);
    declare @Onbekendevelden nchar(200) = '';
    declare @VeldenTeller    integer = 1;

    for @cursor as cursor_veldenlijst cursor for
      select * from openstring(VALUE @FieldList) with(@Tuple nvarchar(250)) OPTION ( ROW DELIMITED BY '\n') as tmpVeldenlijst
    for read only
    do
      if @FielListIsIdentifiers = 0 then
        set @Veldnaam = VrVeldNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId, @Tuple);
      else
        set @Veldnaam = @Tuple;
      end if;
      if @Veldnaam is null then
        set @Onbekendevelden = @Onbekendevelden + if @Onbekendevelden = '' then '' else ', ' endif + @Tuple;
        if @VeldenMoetenBestaan = 0 then
          set @Veldnaam = 'DUMMY_' || @VeldenTeller;
          set @VeldenTeller = @VeldenTeller + 1;
        end if;
      end if;
      set @Veldenlijst = @Veldenlijst + ', "' + @Veldnaam + '"' || if @VrTabelBestaat = 0 or @Veldnaam like 'DUMMY_%' then '=NULL' endif;

      // In de where- en group by clause vervangen van de VrLabels door de veldnamen
      set @WhereClause   = replace(@WhereClause,   @VeldKenmerkBegin + @Tuple + @VeldKenmerkEind, '"' + @Veldnaam + '"');
      set @OrderByClause = replace(@OrderByClause, @VeldKenmerkBegin + @Tuple + @VeldKenmerkEind, '"' + @Veldnaam + '"');
    end for;

    if @VeldenMoetenBestaan <> 0 and @Onbekendevelden <> '' then
      call Raise(20679, @Onbekendevelden); //(20679) RubriekOmschrijving niet gevonden: %1!
    end if;

    // RecordId altijd toevoegen en in de where/orderby clausules vertalen
    set @Veldenlijst =
      'VrRecordId=' ||
      if @VrTabelBestaat = 0
        then 'NULL'
        else 'Vr' || @VrBestandOms ||
             right(repeat('0', 3) + string(@VrGroepId)   , 3) +
             right(repeat('0', 3) + string(@VrSubGroepId), 3) +
             'RecordId'
        endif ||
      @Veldenlijst +
      if @AddAsResult&1 = 0
        then ''
        else ', VrLastModified=' || if @VrTabelBestaat = 0 then 'NULL' else VrLastModifiedNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId) endif
      endif;
    set @WhereClause   = replace(@WhereClause,   @VeldKenmerkBegin + 'VrRecordId' + @VeldKenmerkEind, '"VrRecordId"');
    set @OrderByClause = replace(@OrderByClause, @VeldKenmerkBegin + 'VrRecordId' + @VeldKenmerkEind, '"VrRecordId"');
  end;

  // In de where en order by clause is het mogelijk om ook andere velden op te nemen die niet worden getoond. Dat wordt hier uitgewerkt
  begin
    declare @teller smallint = 0; //0 = where-clause, 1 = order by-clause
    declare @regel  long nvarchar;
    while @teller<=1 loop
      case @teller
        when 0 then set @regel = @WhereClause;
        when 1 then set @regel = @OrderByClause;
      end case;

      begin
        declare @Beginpos    integer;
        declare @Eindpos     integer;
        declare @Veldnaam    nchar(40);
        declare @VrFieldname nchar(40);
        while @regel like '%' + @VeldKenmerkBegin + '%' + @VeldKenmerkEind + '%' loop
          set @Beginpos    = locate(@regel, @VeldKenmerkBegin);
          set @Eindpos     = locate(@regel, @VeldKenmerkEind, @Beginpos);
          set @Veldnaam    = substr(@regel, @Beginpos + 1, @Eindpos - @Beginpos - 1);
          set @VrFieldname = '"' + isnull(VrVeldNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId, @Veldnaam), '') + '"';
          // Veldnaam kan een directe vr-veld zijn (als @FielListIsIdentifiers=1)
          if     (@FielListIsIdentifiers = 1)
             and (@VrFieldname = '""')
             and (@Veldnaam like 'vr' || @VrBestandOms || right('000' || @VrGroepId, 3) || right('000' || @VrSubGroepId, 3) || '%') then
            set @VrFieldname = '"' || @Veldnaam || '"';
          end if;
          if @VrFieldname = '""' then
            if @VeldenMoetenBestaan <> 0 then
              call Raise(20679, @Veldnaam); //(20679) RubriekOmschrijving niet gevonden: %1!
            else
              set @VrFieldname = ' null ';
            end if;
          end if;
          set @regel = left(@regel, @Beginpos - 1) + @VrFieldname + substr(@regel, @Eindpos + 1);
        end loop;
      end;

      case @teller
        when 0 then set @WhereClause   = @regel;
        when 1 then set @OrderByClause = @regel;
      end case;
      set @teller = @teller + 1;
    end loop;
  end;

  begin
    declare @Commando long nvarchar;
    set @Commando = 'Select ' + @Veldenlijst + ' from ' + if @VrTabelBestaat = 0 then 'dummy' else @VrTabelnaam endif;
    if isnull(@WhereClause, '') <> '' then
      set @Commando = @Commando + ' WHERE (' || @WhereClause || ')';
    end if;
    // Tabel bestaat niet, dus geen resultaat!
    if @VrTabelBestaat = 0 then
      set @Commando = @Commando || if isnull(@WhereClause, '') = '' then ' WHERE 1=0' else ' and 1=0' endif;
    end if;

    if isnull(@OrderByClause, '') <> '' then
      set @Commando = @Commando + ' ORDER BY ' + @OrderByClause;
    end if;

    //Werkt natuurlijk niet omdat er ook letterlijke strings in het commando moeten kunnen worden gebruikt geweest geworden.
    //set @Commando  = replace(@Commando, '''', '''''');
    //call trace(@Commando);
    return @Commando;
  end;
  //call traceEind(@@errorTextProcedure);
end;


create or replace procedure VrijeRubriekenVulDefaults(
  in @BestandOms    nchar(3),
  in @GroepId       integer,
  in @SubGroepId    integer,
  in @PrimaryKeyGid integer,
  in @Overschrijven      smallint default 1, // 0 = Alleen NULL waarden overschrijven, 1 = altijd overschrijven
  in @BestandOmsExtra    nchar(3) default NULL,
  in @GroepIdExtra       integer  default NULL,
  in @SubGroepIdExtra    integer  default NULL,
  in @Veldnaam           nchar(40) default NULL, // Indien veldnaam (en eventueel VeldnaamExtra) zijn meegegeven, dan worden alleen die hier doorlopen
  in @VeldnaamExtra      nchar(40) default NULL
  )
begin
  declare @TableName    nchar(40);
  declare @RecordId     nchar(40);
  declare @SqlVeldNaam  nchar(40);
  declare @SqlStatement long nvarchar;

  set @@ErrorTextProcedure = 'VrijeRubriekenVulDefaults > @BestandOms = ' + @BestandOms+', @PrimaryKeyGid = '+string(@PrimaryKeyGid);
  //call TraceBegin(@@ErrorTextProcedure);

  //call trace('@Veldnaam='+@Veldnaam+', @VeldnaamExtra=' + @VeldnaamExtra);

  if @BestandOmsExtra is null then
    // Bron = doel, dan gelijkstellen
    set @BestandOmsExtra  = @BestandOms;
    set @GroepIdExtra     = @GroepId;
    set @SubGroepIdExtra  = @SubGroepId;
  end if;

  set @TableName = VrTabelnaam(@BestandOms, @GroepId, @SubGroepId);
  set @RecordId  = VrPrimaryKeyNaam(@BestandOms, @GroepId, @SubGroepId);

  if exists(select 1 from systable where table_name = @TableName) then
    //call Trace('VrijeRubriekenVulDefaults > Vrije rubrieken tabel bestaat:' + @TableName);
    set @SqlStatement  = ' if not exists(select 1 from ' + @TableName + ' where ' + @RecordId + ' = ' + string(@PrimaryKeyGid) + ') then '+
                         '  insert into ' + @TableName + ' ( ' + @RecordId + ') values (' + string(@PrimaryKeyGid) + ')'+
                         ' end if';
    //call Trace('VrijeRubriekenVulDefaults > @SqlStatement = '+@SqlStatement);
    execute immediate @SqlStatement;

    for @Cursor As Cursor_tabVrijeRubrieken Cursor For
      select Doel.VrGid @VrGid,
             Doel.VrType          @VrType,
             isnull(Bron.VrDefaultDate  , case Doel.VrDefaultDateType when 0 /*Andere datum*/ then Doel.VrDefaultDate
                                                                      when 1 /*Verwerkingsdatum*/ then @@VerwerkingsDatum
                                                                      when 2 /*Systeemdatum*/ then date(now())
                                          end) @VrDefaultDate,
             isnull(Bron.VrDecimalen    , Doel.VrDecimalen    ) @VrDecimalen,
             isnull(Bron.VrDefaultGetal , Doel.VrDefaultGetal ) @VrDefaultGetal,
             isnull(Bron.VrDefaultString, Doel.VrDefaultString) @VrDefaultString,
             isnull(Bron.VrDefaultTime  , case Doel.VrDefaultTimeType when 0 /*Eigen tijd*/ then Doel.VrDefaultTime
                                                                      when 1 /*Systeemtijd*/ then cast(now() as time)
                                          end) @VrDefaultTime
    from   tabVrijeRubrieken Doel
           left outer join tabVrijeRubrieken Bron on
           (    Bron.VrBestandOms = @BestandOmsExtra and Bron.VrGroepId = @GroepIdExtra and Bron.VrSubGroepId = @SubGroepIdExtra
            and isnull(@VeldnaamExtra, Bron.VrVeldnaam) = Bron.VrVeldnaam
            and Bron.VrLabel     = Doel.VrLabel
            and Bron.VrType      = Doel.VrType
            and Bron.VrLengte    = Doel.VrLengte
            and Bron.VrVerplicht = Doel.VrVerplicht
            and Bron.VrUniek     = Doel.VrUniek
           )
    where  Doel.VrBestandOms = @BestandOms and Doel.VrGroepId = @GroepId and Doel.VrSubGroepId = @SubGroepId
       and isnull(@Veldnaam, Doel.VrVeldnaam) = Doel.VrVeldnaam
    for read only
    do

      set @SqlVeldnaam = 'Vr' + @BestandOms + right(repeat('0', 3) + string(@GroepId), 3) + right(repeat('0', 3) + string(@SubGroepId), 3) + 'Veld' + string(@VrGid);
      case @VrType
        when 1 then set @SqlStatement = 'update ' + @TableName + ' set ' + @SqlVeldnaam + ' = @VrDefaultGetal where ' + @RecordId + ' = ' + string(@PrimaryKeyGid);
        when 2 then set @SqlStatement = 'update ' + @TableName + ' set ' + @SqlVeldnaam + ' = @VrDefaultDate where ' + @RecordId + ' = ' + string(@PrimaryKeyGid);
        when 3 then set @SqlStatement = 'update ' + @TableName + ' set ' + @SqlVeldnaam + ' = @VrDefaultTime where ' + @RecordId + ' = ' + string(@PrimaryKeyGid);
        else        set @SqlStatement = 'update ' + @TableName + ' set ' + @SqlVeldnaam + ' = @VrDefaultString where ' + @RecordId + ' = ' + string(@PrimaryKeyGid);
      end case;

      if @Overschrijven = 0 then
        set @SqlStatement = @SqlStatement + ' and ' + @SqlVeldnaam + ' is null';
      end if;
      //call Trace('VrijeRubriekenVulDefaults > @SqlStatement = '+@SqlStatement);
      execute immediate @SqlStatement;

    end for;
  //else
  //  call Trace('VrijeRubriekenVulDefaults > Vrije rubrieken tabel bestaat NIET: ' + @TableName);
  end if;

  set @@ErrorTextProcedure = 'VrijeRubriekenVulDefaults';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure VrijeTabelItemKopieren
(
  in  @VtbGid            integer,
  in  @VtbNummer         smallint,
  in  @BronItemGid       integer,
  in  @NieuwItemCode     nchar(40),
  out @NieuwItemGid      integer
)

//Alle insert/select statements gegenereerd door in meta editor op sql tab select statement te genereren
//Als er later velden bijgevoegd worden gaarne deze nieuwe velden lijst er even naast zetten en velden op juist positie tussenvoegen

begin
  set @@ErrorTextProcedure = 'VrijeTabelItemKopieren > @BronItemGid='+string(@BronItemGid)+'@NieuwItemCode='+string(@NieuwItemCode)+'@NieuwItemGid='+string(@NieuwItemGid);

  set @NieuwItemCode	          = IsNull(@NieuwItemCode, '');

  insert into tabVrijeTabelItems with auto name
  select
    @VtbGid        VtbiVtbGid,
    @NieuwItemCode VtbiCode,
    VtbiOmschrijving,
    VtbiOpmerking

  from tabVrijeTabelItems
  where VtbiGid = @BronItemGid;

  //Artgid van nieuwe artikel ophalen
  set @NieuwItemGid = @@Identity;

  call VrKopieerRecord('VTB',@VtbNummer,@VtbNummer,'VTB',@VtbNummer,@VtbNummer,@BronItemGid,@NieuwItemGid);

  set @@ErrorTextProcedure = 'VrijeTabelItemKopieren > @BronItemGid='+string(@BronItemGid)+'@NieuwItemCode='+string(@NieuwItemCode)+'@NieuwItemGid='+string(@NieuwItemGid);

end;


create or replace procedure VrijeTabelItemVerwijderen(in @VtbNummer numeric(3,0), in @VtbiCode nchar(40))
begin
  declare @TableName    nchar(40);
  declare @RecordId     nchar(40);
  declare @VtbiGid      integer;
  declare @SqlStatement long nvarchar;

  //call TraceBegin('VrijeTabelItemVerwijderen >');

  set @TableName = VrTabelnaam('VTB', @VtbNummer, @VtbNummer);
  select VtbiGid into @VtbiGid from tabVrijeTabel inner join tabVrijeTabelItems on (VtbiVtbGid = VtbGid and VtbiCode = @VtbiCode) where VtbNummer = @VtbNummer;
  if @VtbiGid is not null then
    if exists(select 1 from systable where table_name = @TableName) then
      set @RecordId  = VrPrimaryKeyNaam('VTB', @VtbNummer, @VtbNummer);
      //call trace('VrijeTabelItemVerwijderen > '+ @RecordId);
      set @SqlStatement = 'delete ' + @TableName + ' where ' + @RecordId + ' = ' + string(@VtbiGid);
      execute immediate @SqlStatement;
    end if;
    delete tabVrijeTabelItems where VtbiGid = @VtbiGid;
  end if;

  //call TraceEind('VrijeTabelItemVerwijderen');
end;


create or replace procedure VrijeTabelVerwijderen(in @VtbNummer smallint)
begin
  declare @TableName    nchar(40);
  declare @VtbGid       integer;
  declare @SqlStatement long nvarchar;

  set @@ErrorTextProcedure = 'VrijeTabelVerwijderen >';
  //call TraceBegin(@@ErrorTextProcedure);

  select VtbGid into @VtbGid from tabVrijeTabel where VtbNummer = @VtbNummer;
  if @VtbGid is not null then
    set @TableName = 'tabVrVtb' + right(repeat('0', 3) + string(@VtbNummer), 3) + right(repeat('0', 3) + string(@VtbNummer), 3);
    if exists(select 1 from systable where table_name = @TableName) then
      set @SqlStatement = 'drop table ' + @TableName;
      //call Trace('VrijeTabelVerwijderen > @SqlStatement = '+@SqlStatement);
      execute immediate @SqlStatement;
    end if;
    delete tabVrijeRubrieken where VrBestandOms = 'VTB' and VrGroepId = @VtbNummer and VrSubGroepId = @VtbNummer;
    delete tabVrijeTabelItems where VtbiVtbGid = @VtbGid;
    delete tabVrijeTabel where VtbGid = @VtbGid;
  end if;

  set @@ErrorTextProcedure = 'VrijeTabelVerwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure VrInsert(
  in @VrBestandOms nchar(3),
  in @VrGroepId integer,
  in @VrSubGroepId integer,
  in @VrType integer,
  in @VrHint nchar(80),
  in @VrVerplicht smallint,
  in @VrUniek smallint,
  in @VrOpVerkoopDocument smallint,
  in @VrLabel nchar(40),
  in @VrDefaultString nchar(255),
  in @VrDefaultDateType smallint,
  in @VrDefaultDate Date,
  in @VrDefaultTimeType smallint,
  in @VrDefaultTime Time,
  in @VrDefaultGetal Double,
  in @VrLengte smallint,
  in @VrDecimalen smallint,
  in @VrSjabloon nchar(255),
  in @VrvrgrpGid integer,
  in @MasterTabelnaam nchar(40),
  in @MasterTabelRecordVeldnaam nchar(40))
begin
  declare @Type              nchar(20);
  declare @TabelNaam         nchar(40);
  declare @VrVeldNaam        nchar(40);
  declare @VrGid             integer;

  set @@ErrorTextProcedure = 'VrInsert > ';
  //call TraceBegin(@@ErrorTextProcedure + '@VrBestandOms = ' + @VrBestandOms + ', @VrGroepId = ' + string(@VrGroepId) + ', @VrSubGroepId = ' + string(@VrSubGroepId));

  set @TabelNaam = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

  // 20099 : De tabel van de vrije rubrieken moet door mezelf gelocked zijn !
  if LockedById(@@SpId, @@LoginTime, 1, @TabelNaam, '') = 0 then
    call Raise(20099);
  end if;

  //--- grootste deel gegevens in tabel zetten
  insert into tabVrijeRubrieken
    (vrBestandOms, vrGroepId, vrSubGroepId, vrType, vrVerplicht, VrUniek, VrOpVerkoopDocument, vrLabel, vrLengte, vrDecimalen,
     vrDefaultDateType, vrDefaultDate, vrDefaultTimeType, vrDefaultTime, vrDefaultGetal, vrDefaultString, vrHint, vrSjabloon, VrvrgrpGid)
  values
    (@VrBestandOms, @VrGroepId, @VrSubGroepId, @VrType, @VrVerplicht, @VrUniek, @VrOpVerkoopDocument, @VrLabel, @VrLengte, @VrDecimalen,
     @VrDefaultDateType, @VrDefaultDate, @VrDefaultTimeType, @VrDefaultTime, @VrDefaultGetal, @VrDefaultString, @VrHint, @VrSjabloon, @VrvrgrpGid);

  //--- VrGid ophalen en veldnaam samenstellen
  set @VrGid      = @@Identity;
  set @VrVeldnaam = 'vr' + @VrBestandOms +
                           right(repeat('0', 3) + string(@VrGroepId)   , 3) +
                           right(repeat('0', 3) + string(@VrSubGroepId), 3) +
                           'Veld' + string(@VrGid);

  //--- veldnaam in de tabel zetten
  update tabVrijeRubrieken
  set    vrVeldNaam = @VrVeldNaam
  where  vrGid = @VrGid;

  //--- indien nodig de selecties updaten
  if @VrType = 5 then
    call VrUpdateSelecties(@VrGid);
  end if;


  //--- tabel aanmaken
  call VrCreateTable(@VrBestandOms, @VrGroepId, @VrSubGroepId, @TabelNaam, @MasterTabelnaam, @MasterTabelRecordVeldnaam);

  //--- colom maken in tabel
  select VrTypeString(@VrType, @VrLengte, @VrDecimalen) into @Type;
  call VrCreateColumn(@TabelNaam, @VrVeldnaam, @Type);

  //--- indien uniek, index aanleggen
  if IsNull(@VrUniek, 0) <> 0 then
    call VrCreateIndex(@TabelNaam, @VrVeldNaam);
  end if;

  if exists(select 1 from tabMutatieLogInstellingen
            inner join tabMutatieLogGroep on MugGid = MuiMugGid
            inner join tabMutatieLogTabel on MutMugGid = MugGid
            where (MutTabelNaam = @TabelNaam) or ((MutIsPrefix = 1) and (Left(@TabelNaam, Length(MutTabelNaam)) = MutTabelNaam))) then
    call MutatieLog_DisableTable(@TabelNaam);
    // Controleren of de static-part triggers van het dyn-trigger systeem aanwezig zijn, zo niet dan aanmaken
    if not exists(select 1 from systrigger where trigger_name like '%'+@TabelNaam+'_DynTrigger') then
      call CreateDynamicTriggersStaticPart(0, @TabelNaam);
    end if;
    call MutatieLog_EnableTable(@TabelNaam);
  end if;

  set @@ErrorTextProcedure = 'VrInsert';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure VrInsertFromDefaults(
  in @BestandOms    nchar(3),
  in @GroepId       integer,
  in @SubGroepId    integer,
  in @PrimaryKeyGid integer,
  // Als defaults ook van een andere bron kunnen komen, dan ook deze velden aangeven
  in @BestandOmsExtra    nchar(3) default null,
  in @GroepIdExtra       integer  default null,
  in @SubGroepIdExtra    integer  default null,
  in @PrimaryKeyGidExtra integer  default null)
begin
  declare @TableName    nchar(40);
  declare @RecordId     nchar(40);

  declare @IsFromExtra smallint default 0;
  declare @TableNameExtra    nchar(40);
  declare @RecordIdExtra     nchar(40);

  set @@ErrorTextProcedure = 'VrInsertFromDefaults';
  //call tracebegin(@@ErrorTextProcedure);

  set @TableName = VrTabelnaam(@BestandOms, @GroepId, @SubGroepId);
  set @RecordId  = VrPrimaryKeyNaam(@BestandOms, @GroepId, @SubGroepId);

  // Alleen als de tabel bestaat
  if exists(select 1 from systable where table_name = @TableName) then
    set @IsFromExtra = if @BestandOmsExtra is null then 0 else 1 endif;

    if @IsFromExtra = 1 then
      set @TableNameExtra = VrTabelnaam(@BestandOmsExtra, @GroepIdExtra, @SubGroepIdExtra);
      set @RecordIdExtra  = VrPrimaryKeyNaam(@BestandOmsExtra, @GroepIdExtra, @SubGroepIdExtra);
    end if;

    // Als de oorsprong (extra) niet bestaat, dan net doen alsof we daar niks van overnemen
    if not exists(select 1 from systable where table_name = @TableName) then
      set @IsFromExtra = 0;
    end if;

    //call trace('@IsFromExtra='+string(@IsFromExtra));

    // kopieer gegevens van oorspronkelijke (extra) tabel
    if @IsFromExtra = 1 then
      call VrKopieerRecord(@BestandOmsExtra, @GroepIdExtra, @SubGroepIdExtra, @BestandOms, @GroepId, @SubGroepId, @PrimaryKeyGidExtra, @PrimaryKeyGid);
    else
      // Niks overnemen van record, maar rechtstreeks vanuit de defaults vullen
      call VrijeRubriekenVulDefaults(@BestandOms, @GroepId, @SubGroepId, @PrimaryKeyGid, 0 /*Alleen NULL overschrijven*/)
    end if;

  end if;

  set @@ErrorTextProcedure = 'VrInsertFromDefaults';
  //call traceeind(@@ErrorTextProcedure);
end;

create or replace procedure VrInsertOrReplaceValue(
  in @VrBestandOms        nchar(3),
  in @VrGroepId           integer,
  in @VrSubGroepId        integer,
  in @VrPrimaryKey        integer,   // Primary key (bijv. OrkGid, NawGid) die naar betreffende object verwijst
  in @RubriekOmschrijving nchar(40), // Naam van de vrije rubriek
  in @Value               Long nvarchar  // Kunnen ook datum- en tijdveld bevatten
)
begin
  declare @VrTabelNaam           nchar(40);
  declare @VrVeldNaam            nchar(40);
  declare @VrPrimaryKeyFieldName nchar(40);

  // Tabelnaam opzoeken
  set @VrTabelNaam  = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);
  //call Trace('@VrTabelNaam = '+@VrTabelNaam);
  if not exists(select 1 from systable where table_name = @VrTabelNaam) then
    call Raise(20541); //Vrije rubrieken tabel niet gevonden!
  end if;

  // Veldnaam opzoeken
  set @VrVeldNaam   = VrVeldNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId, @RubriekOmschrijving);
  //call Trace('@VrVeldNaam = '+@VrVeldNaam);
  if not exists(select 1 from sys.syscolumns where tname = @VrTabelNaam and cname = @VrVeldNaam) then
    call Raise(20542); //Ongeldige of geen RubriekOmschrijving meegegeven!
  end if;

  // Veldnaam voor de primary key opvragen
  set @VrPrimaryKeyFieldName = VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);
  if not exists(select 1 from sys.syscolumns where tname = @VrTabelNaam and cname = @VrVeldNaam) then
    call Raise(20542); //Ongeldige of geen RubriekOmschrijving meegegeven!
  end if;

  if @Value is not null then //Als we "null" meegeven, dan laten we de oude waarde staan, dus in het geval van vrije rubrieken hoeft er dan helemaal niets gedaan te worden.
    begin
      declare @_VrType integer;
      declare @_VrSelecties long nvarchar;

      select VrType, VrSelecties into @_VrType, @_VrSelecties
      from tabVrijeRubrieken
      where VrVeldnaam = @VrVeldNaam;

      case @_VrType
        when 2 /*datum*/ then
          if (IsNull(@Value, '') <> '') and ((length(@Value) < 8) or (length(@Value) > 10) or (substr(@Value, 5, 1)<>'-') or ((substr(@Value, 7, 1)<>'-')  and (substr(@Value, 8, 1)<>'-'))) then
              call Raise(20543); //RubriekInhoud is geen geldig date-formaat!
           end if;
           execute immediate 'create or replace variable @@GlobalTmp_VrValue date';
          if (IsNull(@Value, '') = '') then
            set @@GlobalTmp_VrValue = null;
          else
            begin
              set @@GlobalTmp_VrValue = cast(@Value as date);
            exception when others then
              drop variable @@GlobalTmp_VrValue;
              call Raise(20543); //RubriekInhoud is geen geldig date-formaat!
            end;
          end if;
        when 3 /*Tijd*/ then
          if (IsNull(@Value, '') <> '') and ((length(@Value) < 4) or (length(@Value) > 12) or ((substr(@Value, 2, 1)<>':') and (substr(@Value, 3, 1)<>':'))) then
            call Raise(20544); //RubriekInhoud is geen geldig time-formaat!
          end if;
          execute immediate 'create or replace variable @@GlobalTmp_VrValue time';
          if (IsNull(@Value, '') = '') then
            set @@GlobalTmp_VrValue = null;
          else
            begin
              set @@GlobalTmp_VrValue = cast(@Value as time);
            exception when others then
              drop variable @@GlobalTmp_VrValue;
              call Raise(20544); //RubriekInhoud is geen geldig time-formaat!
            end;
          end if;
        when 4 /*Selectievakje*/ then
          execute immediate 'create or replace variable @@GlobalTmp_VrValue smallint';
          begin
            case isnull(trim(@Value), '0')
              // Wellus-lijstje
              when '-1'   then set @@GlobalTmp_VrValue = 1
              when '1'    then set @@GlobalTmp_VrValue = 1
              when 'true' then set @@GlobalTmp_VrValue = 1
              when 't'    then set @@GlobalTmp_VrValue = 1
              when 'ja'   then set @@GlobalTmp_VrValue = 1
              when 'yes'  then set @@GlobalTmp_VrValue = 1
              when 'waar' then set @@GlobalTmp_VrValue = 1
              when 'wel'  then set @@GlobalTmp_VrValue = 1
              // Nietus-lijstje
              when '0'         then set @@GlobalTmp_VrValue = 0
              when 'false'     then set @@GlobalTmp_VrValue = 0
              when 'f'         then set @@GlobalTmp_VrValue = 0
              when 'nee'       then set @@GlobalTmp_VrValue = 0
              when 'no'        then set @@GlobalTmp_VrValue = 0
              when 'niet waar' then set @@GlobalTmp_VrValue = 0
              when 'niet'      then set @@GlobalTmp_VrValue = 0
            else
              call Raise(20697); //(20697) RubriekInhoud is niet geldig!
            end;

            //if @Value <> 0 then
            //  set @@GlobalTmp_VrValue = 1;
            //else
            //  set @@GlobalTmp_VrValue = @Value;
            //end if;
          exception when others then
            drop variable @@GlobalTmp_VrValue;
            call Raise(20697); //(20697) RubriekInhoud is niet geldig!
          end;
        when 5 /*Keuzelijst*/ then
          execute immediate 'create or replace variable @@GlobalTmp_VrValue long nvarchar';
          //Foutmelding als de waarde niet niet voorkomt.
          if (isNull(@Value, '') <> '') and not exists(select first 1 from openstring( VALUE @_VrSelecties) WITH(keuze nchar(40)) as Keuzelijst where @Value = keuze) then
            drop variable @@GlobalTmp_VrValue;
            call Raise(20697); //(20697) RubriekInhoud is niet geldig!
          end if;

          begin
            set @@GlobalTmp_VrValue = @Value;
          exception when others then
            drop variable @@GlobalTmp_VrValue;
            call Raise(20697); //(20697) RubriekInhoud is niet geldig!
          end;
        else
          execute immediate 'create or replace variable @@GlobalTmp_VrValue long nvarchar';
          begin
            //call trace('Long nvarchar!');
            set @@GlobalTmp_VrValue = @Value;
          exception when others then
            drop variable @@GlobalTmp_VrValue;
            call Raise(20697); //(20697) RubriekInhoud is niet geldig!
          end;
      end case;


      // Nu de waarde toevoegen of wijzigen
      begin
        declare @Query long nvarchar;
        set @Query = 'if exists(select 1 from ' || @VrTabelNaam || ' where ' || @VrPrimaryKeyFieldName || ' = ' || string(@VrPrimaryKey) || ') then ' ||
                       'update ' || @VrTabelNaam || ' set ' || @VrVeldNaam || ' = @@GlobalTmp_VrValue where ' || @VrPrimaryKeyFieldName || ' = ' || string(@VrPrimaryKey) || ';' ||
                     ' else ' ||
                       'insert into ' || @VrTabelNaam || '(' || @VrPrimaryKeyFieldName || ', ' || @VrVeldNaam || ') values (' || @VrPrimaryKey || ', @@GlobalTmp_VrValue' || ');' ||
                     ' end if';
        //call trace('@Query=' + @Query);
        //call trace('@@GlobalTmp_VrValue=' + string(@@GlobalTmp_VrValue));
        begin
          execute immediate with batch off @Query;
          //call trace('Drop variable');
          drop variable @@GlobalTmp_VrValue;
        exception when others then
          //call trace('Exception bij execute immediate');
          drop variable @@GlobalTmp_VrValue;
            call Raise(20697); //(20697) RubriekInhoud is niet geldig!
        end;
      end;
    end;
  end if;
end;


//---- procedure retourneert het aantal records in de data-tabel met de keuze 'keuze'
create or replace procedure VrKeuzeKomtVoor(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer,
                                 in @MasterTabelnaam nchar(40), in @MasterTabelRecordVeldnaam nchar(40),
																 in @VrGid integer, in @Keuze nchar(40),
                                 out @KeuzeKomtVoor integer)
begin
  declare @Exists                     integer;
  declare @VrTableName                nchar(40);
  declare @VrRecordFieldName          nchar(40);
  declare @KeuzelijstVeldnaam         nchar(40);
  declare @VrType                     integer;

  //call TraceBegin('VrKeuzeKomtVoor');

  //--- naam tabel samenstellen
  set @VrTableName = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

  //--- veldnaam en soort van de keuzelijst ophalen
  select VrVeldnaam, VrType into @KeuzelijstVeldnaam, @VrType
  from   tabVrijeRubrieken
  where  vrGid = @VrGid;

  //--- controle op bestaan tabel en kolom
  call ColumnExist(@VrTableName, @KeuzelijstVeldnaam, @Exists);

  //--- kijken of tellen mogelijk is
  if (@Exists <> 0) and (@VrType = 5) then

    //--- veldnaam van de identifiers samenstellen
    set @VrRecordFieldName = VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

    //--- records in vr-tabel tellen met de keuze
    execute immediate 'select IsNull((select count(distinct '+ @MasterTabelRecordVeldnaam + ') ' +
                                     'from  '+ @MasterTabelnaam + ', '+@VrTablename+' ' +
                                     'where ('+ @MasterTabelRecordVeldnaam + '='+@VrRecordFieldName+') AND '+
                                           '('+ @KeuzelijstVeldnaam + '=''' + Replace(@Keuze, '''', '''''') + ''')'+
                       '),0) into @KeuzeKomtVoor';
  else
    set @KeuzeKomtVoor=0;
  end if;

  //call TraceEind('VrKeuzeKomtVoor ---> @KeuzeKomtVoor ='+string(@KeuzeKomtVoor));

end;


create or replace procedure VrKopieerRecord(
//---- procedure kopieert een record in een vr-tabel
//Als doelgid al bestaat, dan wordt er niet gekopieerd.
//AvB 25-Okt-2022 Defect# 58444: Als bron en doel niet hetzelfde zijn, nu bij keuzelijst check of de waarde uit de bron geldig is voor het doel.
//MR 05-jun-2007 Bug# 25956: Procedure zo omgebouwd dat je identieke vrijerubrieken die voorkomen in verschillende groepen
//              gekopieerd kunnen worden.
  in @BronVrBestandOms nchar(3),
  in @BronVrGroepId    integer,
  in @BronVrSubGroepId integer,
  in @DoelVrBestandOms nchar(3),
  in @DoelVrGroepId    integer,
  in @DoelVrSubGroepId integer,
  in @BronGid          integer,
  in @DoelGid          integer,
  in @NieuwRecord      smallint default 1) // 0 = Bestaand record, 1 = Nieuw record
begin
  declare @VeldValue          nchar(40);
  declare @BronVrTabelNaam    nchar(20);
  declare @BronRecordIdNaam   nchar(30);
  declare @BronVeldenLijst    long nvarchar;
  declare @DoelVrTabelNaam    nchar(20);
  declare @DoelRecordIdNaam   nchar(30);
  declare @DoelVeldenLijst    long nvarchar;
  declare @DoelVeldenLijstOvergeslagen long nvarchar;
  declare @VeldIsGeldig smallint = 0;
  declare @sql long nvarchar;

  set @@ErrorTextProcedure = 'VrKopieerRecord';
    //call TraceBegin(@@ErrorTextProcedure);
    //call trace('VAN : ' +
    //             '@BronVrBestandOms='+string(@BronVrBestandOms)+
    //           '; @BronVrGroepId='+string(@BronVrGroepId)+
    //           '; @BronVrSubGroepId='+string(@BronVrSubGroepId)+
    //           '; @BronGid='+string(@BronGid));
    //call trace('NAAR: ' +
    //             '@DoelVrBestandOms='+string(@DoelVrBestandOms)+
    //           '; @DoelVrGroepId='+   string(@DoelVrGroepId)+
    //           '; @DoelVrSubGroepId='+string(@DoelVrSubGroepId)+
    //           '; @DoelGid='+         string(@DoelGid));

  set @BronVrTabelNaam  = VrTabelnaam(@BronVrBestandOms, @BronVrGroepId, @BronVrSubGroepId);//bijv. tabVrArt000000
  set @BronRecordIdNaam = VrPrimaryKeyNaam(@BronVrBestandOms, @BronVrGroepId, @BronVrSubGroepId);
  set @BronVeldenLijst  = '';
  set @DoelVrTabelNaam  = VrTabelnaam(@DoelVrBestandOms, @DoelVrGroepId, @DoelVrSubGroepId);//bijv. tabVrArt000000
  set @DoelRecordIdNaam = VrPrimaryKeyNaam(@DoelVrBestandOms, @DoelVrGroepId, @DoelVrSubGroepId);
  set @DoelVeldenLijst  = '';
  set @DoelVeldenLijstOvergeslagen = '';

  // ************************
  // *** Genereer lijsten ***
  // ************************
  // Opbouwen van lijst aan zelfde velden in bron en doel
  // Onthoud ook die doelvelden waarvoor geen bron is, zodat die kunnen worden gevuld met de defaults van vaste gegevens van dat doel
  for @Cursor AS cursor_VrijeRubriekVelden CURSOR FOR
    select Doel.VrGid @DoelVrGid, Doel.VrVeldNaam @DoelVrVeldNaam, Doel.VrType @DoelVrType, Doel.VrSelecties @DoelSelecties,
           (select Bron.VrVeldNaam @BronVrVeldNaam
           from tabVrijeRubrieken Bron
           where
                 Bron.VrBestandOms = @BronVrBestandOms
             and Bron.VrGroepId    = @BronVrGroepId
             and Bron.VrSubGroepId = @BronVrSubGroepId
             and Bron.VrLabel     = Doel.VrLabel
             and Bron.VrType      = Doel.VrType
             and Bron.VrLengte    = Doel.VrLengte
             and Bron.VrDecimalen = Doel.VrDecimalen
             and Bron.VrSjabloon  = Doel.VrSjabloon
             //and Bron.VrVerplicht = Doel.VrVerplicht
             //and Bron.VrUniek     = Doel.VrUniek
           )
    from   tabVrijeRubrieken Doel
    where  // Bron
           Doel.VrBestandOms = @DoelVrBestandOms
       and Doel.VrGroepId    = @DoelVrGroepId
       and Doel.VrSubGroepId = @DoelVrSubGroepId
  for read only
  do

    //Dezelfde velden in een lijst plaatsen.
    set @VeldIsGeldig = if @BronVrVeldNaam is not null then 1 else 0 endif;

    if @VeldIsGeldig = 1 and @DoelVrType = 5 /* Keuzelijst */ then
      if @BronVrBestandOms <> @DoelVrBestandOms then
         // call TraceBegin('Ceck geldigheid van gevonden waarde bij een keuzelijst');

        // indien de waarde niet kan voorkomen bij opgeven doel, dan aan overgeslagen velden toevoegen ipv van waarde kopieren.
        set @SQL = '
select ' || @BronVrVeldNaam || ' into @VeldValue
from '   || @BronVrTabelnaam  || '
where '  || @BronRecordIdNaam || ' = ' || @BronGid;

        execute immediate with batch off @SQL;

        // ivm debugmogelijkheden laatste stukje hieronder niet in bovenstaande query opgenomen.
        set @VeldIsGeldig = IsSelectieInLijst(@VeldValue , @DoelSelecties, '\x0D\x0A');

      end if;
    end if;

    if @VeldIsGeldig = 1 then
      set @BronVeldenLijst = @BronVeldenLijst + ',' + @BronVrVeldNaam;
      set @DoelVeldenLijst = @DoelVeldenLijst + ',' + @DoelVrVeldNaam;
    else
      // als het een bestaand record is, mag de default uit vaste gegevens van het doel niet gebruikt worden.
	  // via VeldIsGeldig is 'BronVrVeldNaam is not null' al gecheckt.
      if (@NieuwRecord = 1) then
        set @DoelVeldenLijstOvergeslagen = @DoelVeldenLijstOvergeslagen + ',' + @DoelVrVeldNaam;
      end if;
    end if;
  end for;

  //call trace('Over te nemen: ' + @BronVeldenLijst);
  //call trace('Naar         : ' + @DoelVeldenLijst);
  //call trace('Niet gevonden: ' + @DoelVeldenLijstOvergeslagen);


  // ************************************
  // *** Overnemen vanuit andere bron ***
  // ************************************

  if (@BronVeldenLijst <> '')  then
    begin
      declare @HeeftRecord smallint;
      //Veldenlijsten beginnen met een komma, zodat we hieronder het recordId veld er voor kunnen plakken.
      set @sql = 'insert into ' + @DoelVrTabelNaam +
                                    ' ( ' + @DoelRecordIdNaam  + @DoelVeldenLijst + ' ) ' +
                        ' select ' + String(@DoelGid) + @BronVeldenLijst +
                        ' from ' + @BronVrTabelnaam +
                        ' where ' + @BronRecordIdNaam + ' = ' + String(@BronGid) +
                        ' and not exists(select 1 from ' + @DoelVrTabelnaam + ' where ' + @DoelRecordIdNaam + ' = ' + String(@DoelGid) + ' )';
      //call trace(@sql);
      execute immediate with batch off @sql;

      // Als er nog geen Doelrecord is aangemaakt, dan Aanroepen van VrijeRubriekenVulDefaults voor alle velden in @BronVeldenLijst en @DoelVeldenLijst
      set @sql = 'set @HeeftRecord = if exists(select 1 from ' + @DoelVrTabelnaam + ' where ' + @DoelRecordIdNaam + ' = ' + String(@DoelGid) + ' ) then 1 else 0 endif';
      //call trace(@sql);
      execute immediate with batch off @sql;

      //call trace('@HeeftRecord='+string(@HeeftRecord));
      if @HeeftRecord = 0 then
        // Geen record aangemaakt, dan defaults overnemen voor alle zelfde velden vanuit het andere doel
        call VrijeRubriekenVulDefaults(@DoelVrBestandOms,
                                       @DoelVrGroepId,
                                       @DoelVrSubGroepId,
                                       @DoelGid,
                                       1 /*overschrijven*/,
                                       @BronVrBestandOms,
                                       @BronVrGroepId,
                                       @BronVrSubGroepId,
                                       NULL /*@DoelVeldnaam*/,
                                       NULL /*@BronVeldnaam*/
                                      );
      end if;
    end;
  end if;


  // ********************************************************************
  // *** Overnemen van overige velden uit vaste gegevens van het doel ***
  // ********************************************************************

  if @DoelVeldenLijstOvergeslagen <> '' then
    // Voor alle overige velden 1 voor 1 de default vullen MET overschrijven
    //Alle velden in Doel die NIET in Bron voorkomen alsnog default vullen (met overschrijven)
    if @BronVeldenLijst = '' then
      // Geen bronvelden, dus alles vanuit de eigen vaste gegevens, dus niet via een lus, maar rechtstreeks alle defaults overhalen
      call VrijeRubriekenVulDefaults(@DoelVrBestandOms,
                                     @DoelVrGroepId,
                                     @DoelVrSubGroepId,
                                     @DoelGid,
                                     1 /*overschrijven*/,
                                     NULL /*@BronBestandOms*/,
                                     NULL /*@BronGroepId*/,
                                     NULL /*@BronSubGroepId*/,
                                     NULL /*@DoelVeldnaam*/, // Deze leeg, dus alle velden vullen
                                     NULL /*@BronVeldnaam*/
                                    );
    else
      // Beperkte set van velden vullen, omdat sommige velden al zijn gevuld vanuit andere velden van de bron
      for @Cursor2 AS cursor_VanuitDefault CURSOR FOR
      select DoelVeldNaam @DoelVrVeldNaam
      from
        openstring( VALUE @DoelVeldenLijstOvergeslagen) WITH(DoelVeldNaam nchar(40)) OPTION(DELIMITED BY ';' ROW DELIMITED BY ',') tabDoel
      where @DoelVrVeldNaam <> '' //Omdat het begint met een komma moeten we de lege overslaan!
      for read only
      do
        //call trace('Overnemen default van @DoelVrVeldNaam=' + @DoelVrVeldNaam);
        call VrijeRubriekenVulDefaults(@DoelVrBestandOms,
                                       @DoelVrGroepId,
                                       @DoelVrSubGroepId,
                                       @DoelGid,
                                       1 /*overschrijven*/,
                                       NULL /*@BronBestandOms*/,
                                       NULL /*@BronGroepId*/,
                                       NULL /*@BronSubGroepId*/,
                                       @DoelVrVeldNaam /*@DoelVeldnaam*/,
                                       NULL /*@BronVeldnaam*/
                                      );
      end for;
    end if;
  end if;

  // Alle overgeslagen velden vullen vanuit vaste gegevens, liefst vanuit de vaste gegevens van Bron, anders van Doel
  //call TraceEind('VrKopieerRecord');

end;


//--- functie die de naam voor het veld lastmodified van de tabel van de vrije rubrieken retourneerd.
create or replace function VrLastModifiedNaam(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer)
returns nchar(24)
begin

  return('Vr' + @VrBestandOms +
                 right(repeat('0', 3) + string(@VrGroepId)   , 3) +
                 right(repeat('0', 3) + string(@VrSubGroepId), 3) + 'LastModified');


end;


create or replace procedure VrNumberOfRecords(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer,
                                   in @MasterTabelnaam nchar(40), in @MasterTabelRecordVeldnaam nchar(40),
                                   out @NumberInVrTable integer)
begin
  declare @Exists                     integer;
  declare @VrTableName                nchar(20);
  declare @VrRecordFieldName          nchar(20);

  //call TraceBegin('VrNumberOfRecords');

  //--- naam tabel samenstellen
  set @VrTableName = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

  //--- controle op bestaan tabel
  call TableExist(@VrTableName, @Exists);

  //--- aantal records in de vrije rubrieken tabel bekijken
  if @Exists <> 0 then
    //--- veldnaam samenstellen
    set @VrRecordFieldName = VrPrimaryKeyNaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);


    //--- records in vr-tabel tellen
    execute immediate 'select IsNull((select count(distinct '+ @MasterTabelRecordVeldnaam + ') ' +
                      'from  '+ @MasterTabelnaam + ', '+@VrTablename+' ' +
                      'where '+ @MasterTabelRecordVeldnaam + '='+@VrRecordFieldName+'),0) '+
                      'into @NumberInVrTable';
  else
    set @NumberInVrTable=0;
  end if;

  //call TraceEind('VrNumberOfRecords ---> @NumberInVrTabel ='+string(@NumberInVrTabel));

end;


create or replace procedure VrOpvoerenTriggers()
begin
  //Vve 13-11-2007: Deze storedproc actualiseert alle eventuele triggers op vrije rubrieken.
  declare @Exists         smallint;

  set @@ErrorTextProcedure = 'VrOpvoerenTriggers';
  //call Trace(@@ErrorTextProcedure);

  set @Exists=0;
  call TableExist('tabVrNAW001001', @Exists);
  if @Exists <> 0 then
    call VrEvent_NAW_AfterTableCreate('NAW',1,1,'tabVrNAW001001');
  end if;

  set @Exists=0;
  call TableExist('tabVrADR001001', @Exists);
  if @Exists <> 0 then
    call VrEvent_ADR_AfterTableCreate('ADR',1,1,'tabVrADR001001');
  end if;

  set @Exists=0;
  call TableExist('tabVrCP001001', @Exists);
  if @Exists <> 0 then
    call VrEvent_CP_AfterTableCreate('CP',1,1,'tabVrCP001001');
  end if;

  set @Exists=0;
  call TableExist('tabVrArt000000', @Exists);
  if @Exists <> 0 then
