  end if;
  set @@ErrorTextProcedure = 'VrOpvoerenTriggers';
  //call TraceEind(@@ErrorTextProcedure);
end;



//--- functie die de naam voor de primary key van de tabel van de vrije rubrieken retourneerd.
create or replace function VrPrimaryKeyNaam(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer)
returns nchar(20)
begin

  return('Vr' + @VrBestandOms +
                 right(repeat('0', 3) + string(@VrGroepId)   , 3) +
                 right(repeat('0', 3) + string(@VrSubGroepId), 3) + 'RecordId');


end;


create or replace procedure VrRecreateCompleteVrStructure()
begin
  declare @TabelNaam                 nchar(40);
	declare @MasterTabelnaam           nchar(40);
	declare @MasterTabelRecordVeldnaam nchar(40);

  // Eerst de tabellen aanmaken
  //call trace('Aanmaken vrije rubriek tabellen');
  FOR @Cursor AS CURSOR_VrTabellen CURSOR FOR
    select distinct VrBestandOms @VrBestandOms, VrGroepId @VrGroepId, VrSubGroepId  @VrSubGroepId
    from tabVrijeRubrieken
  FOR READ ONLY
  DO
    case @VrBestandOms
      when 'CP'  then set @MasterTabelnaam = 'tabRelatie';
      when 'ABO' then set @MasterTabelnaam = 'tabAbonnementVersie';
      when 'ACT' then set @MasterTabelnaam = 'tabActivaKop';
      when 'ADR' then set @MasterTabelnaam = 'tabAdres';
      when 'ART' then set @MasterTabelnaam = 'tabArtikel';
      when 'BST' then set @MasterTabelnaam = 'tabBestelKop';
      when 'LIC' then set @MasterTabelnaam = 'tabLicentie';
      when 'LOC' then set @MasterTabelnaam = 'tabLocatie';
      when 'MEV' then set @MasterTabelnaam = 'tabMarketingevent';
      when 'NAW' then set @MasterTabelnaam = 'tabNAW';
      when 'OFK' then set @MasterTabelnaam = 'tabOfferteKop';
      when 'ORK' then set @MasterTabelnaam = 'tabOrderKop';
      when 'ORR' then set @MasterTabelnaam = 'tabOrderRegel';
      when 'PAR' then set @MasterTabelnaam = 'tabArtikelPartij';
      when 'PRD' then set @MasterTabelnaam = 'tabProductieOrderKop';
      when 'PRJ' then set @MasterTabelnaam = 'tabProject';
      when 'RCP' then set @MasterTabelnaam = 'tabReceptuur';
      when 'VRT' then set @MasterTabelnaam = 'tabBedrijfsmiddel';
      when 'VTB' then set @MasterTabelnaam = 'tabVrijeTabelItems';
      else
        call Raise(20677, _U('Bestandsomschrijving ''%1!''', @VrBestandOms)); //(20677) Ongeldige waarde: %1!
    end case;

    // Tabelnaam opbouwen
    set @TabelNaam = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

    // Primary key opzoeken
    select column_name into @MasterTabelRecordVeldnaam
    from SYS.SYScolumn
         inner join sys.systable on systable.table_id = syscolumn.table_id
    where table_name = @MasterTabelnaam
      and pkey = 'Y';

    //call trace('Create Table ' + @TabelNaam);
    call VrCreateTable(@VrBestandOms, @VrGroepId, @VrSubGroepId, @TabelNaam, @MasterTabelnaam, @MasterTabelRecordVeldnaam);
  END FOR;

  //call trace('Aanmaken vrije rubriek velden');
  begin
    declare @type nchar(40);

    // Dan de velden aanmaken
    FOR @Cursor AS CURSOR_VrRubrieken CURSOR FOR
      select VrBestandOms @VrBestandOms, VrGroepId @VrGroepId, VrSubGroepId  @VrSubGroepId, VrVeldnaam @VrVeldnaam, VrLabel @VrLabel, VrType @VrType, VrLengte @VrLengte, VrDecimalen @VrDecimalen, VrUniek @VrUniek
      from tabVrijeRubrieken
    FOR READ ONLY
    DO
      // Tabelnaam opbouwen
      set @TabelNaam = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

      // type bepalen
      select VrTypeString(@VrType, @VrLengte, @VrDecimalen) into @Type;

      // Veld aanmaken
      //call trace('Tabel ' + @TabelNaam + ': \x09Create field ' + @VrVeldnaam + '\x09(' + @VrLabel + ')');
      call VrCreateColumn(@TabelNaam, @VrVeldnaam, @Type);

      //--- indien uniek, index aanleggen
      if IsNull(@VrUniek, 0) <> 0 then
        call VrCreateIndex(@TabelNaam, @VrVeldNaam);
      end if;
    END FOR;
  end;

end;
//call VrRecreateCompleteVrStructure();
/*
Bij herstellen van een database dient de nieuwe database te worden gemaakt:
- Een nieuwe blanco.db van dezelfde release in dezelfde folder zetten
- in Blanco het Script VrRecreateCompleteVrStructure doorvoeren
- Vanuit de oude database de data van tabVrijeRubrieken trekken:
  unload select VrGid, VrBestandOms, VrGroepId, VrSubGroepId, VrDecimalen, VrDefaultDate, VrDefaultGetal, VrDefaultString, VrDefaultTime, VrHint, VrLabel, VrLastModified, VrLengte, VrSelecties, VrSjabloon, VrSubType, VrType, VrUniek, VrVeldnaam, VrVerplicht, VrVolgorde from tabVrijeRubrieken to 'tabVrijeRubrieken.txt' encoding 'UTF-8';
- Deze data in de blanco importeren
  load into table tabVrijeRubrieken(VrGid, VrBestandOms, VrGroepId, VrSubGroepId, VrDecimalen, VrDefaultDate, VrDefaultGetal, VrDefaultString, VrDefaultTime, VrHint, VrLabel, VrLastModified, VrLengte, VrSelecties, VrSjabloon, VrSubType, VrType, VrUniek, VrVeldnaam, VrVerplicht, VrVolgorde) from 'tabVrijeRubrieken.txt' encoding 'UTF-8';
- In de blanco storec procedure VrRecreateCompleteVrStructure aanroepen
- Blanco bewaren
- Herstel draaien o.b.v. structuur uit blanco, data uit database

*/

create or replace function VrTabelnaam(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer)
returns nchar(20)
begin

  return('tabVr' + @VrBestandOms +
                   right(repeat('0', 3) + string(@VrGroepId)   , 3) +
                   right(repeat('0', 3) + string(@VrSubGroepId), 3)    );


end;


//--- functie die in een string het type van een vrije rubriek retourneerd.
create or replace function VrTypeString(in @VrType integer, in @VrLengte integer, in @VrDecimalen integer)
returns nchar(20)
begin
  declare @TypeString nchar(20);

  // Let op: Als de types veranderen, dan ook FactureringOvernemenVrijeRubrieken aanpassen !!!
  case @VrType
    when 1 then // getal
      set @TypeString = 'Numeric('+string(@VrLengte + @VrDecimalen)+', '+string(@VrDecimalen)+')';
    when 2 then // datum
      set @TypeString = 'Date';
    when 3 then // tijd
      set @TypeString = 'Time';
    when 4 then // checkbox
      set @TypeString = 'Smallint';
    when 5 then // combobox; 9-2-2004 vve: Was eerst 20, maar veranderd naar 40 wegens bug 13199.
      set @TypeString = 'nchar(40)';
    else // 0=tekst, 6=email, 7=http:-adres, 8=bestand
      set @TypeString = 'nchar('+string(@VrLengte)+')';
  end case;

  return(@TypeString)

end;


create or replace procedure VrUpdate(
  in @VrBestandOms nchar(3),
  in @VrGroepId integer,
  in @VrSubGroepId integer,
  in @VrType integer,
  in @VrHint nchar(80),
  in @VrVerplicht smallint,
  in @VrUniek smallint,
  in @VrOpVerkoopDocument smallint,
  in @VrLabel nchar(40),
  in @VrDefaultString nchar(255),
  in @VrDefaultDateType smallint,
  in @VrDefaultDate Date,
  in @VrDefaultTimeType smallint,
  in @VrDefaultTime Time,
  in @VrVeldnaam nchar(40),
  in @VrDefaultGetal Double,
  in @VrLengte smallint,
  in @VrDecimalen smallint,
  in @VrSjabloon nchar(255),
  in @VrvrgrpGid integer,
  in @VrGid integer)

begin
  declare @Type              nchar(20);
  declare @TabelNaam         nchar(40);

  set @@ErrorTextProcedure = 'VrUpdate > @VrBestandOms='+@VrBestandOms+', @VrGroepId='+string(@VrGroepId)+', @VrSubGroepId='+string(@VrSubGroepId);
  //call TraceBegin(@@ErrorTextProcedure);

  set @TabelNaam = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

  // 20099 : De tabel van de vrije rubrieken moet door mezelf gelocked zijn !
  if LockedById(@@SpId, @@LoginTime, 1, @TabelNaam, '') = 0 then
    call Raise(20099);
  end if;

  //--- velden updaten
  update tabVrijeRubrieken
  set    vrLabel             = @VrLabel,
         vrType              = @VrType,
         vrVerplicht         = @VrVerplicht,
         vrUniek             = @VrUniek,
         VrOpVerkoopDocument = @VrOpVerkoopDocument,
         vrLengte            = @VrLengte,
         vrDecimalen         = @VrDecimalen,
         vrHint              = @VrHint,
         vrDefaultDateType   = @VrDefaultDateType,
         vrDefaultDate       = @VrDefaultDate,
         vrDefaultTimeType   = @VrDefaultTimeType,
         vrDefaultTime       = @VrDefaultTime,
         vrDefaultString     = @VrDefaultString,
         vrDefaultGetal      = @VrDefaultGetal,
         vrSjabloon          = @VrSjabloon,
				 VrvrgrpGid			     = @VrvrgrpGid
  where  vrGid = @VrGid;

  //--- selectie updaten indien nodig
  if @VrType = 5 then
    call VrUpdateSelecties(@VrGid);
  end if;

  //--- colom aanpassen indien nodig
  select VrTypeString(@VrType, @VrLengte, @VrDecimalen) into @Type;
  call VrAlterColumn(@TabelNaam, @VrVeldnaam, @Type);

  //--- index aanleggen of verwijderen
  if @VrUniek = 0 then
    call VrDropIndex('IDX_'+ @VrVeldnaam);
  else
    call VrCreateIndex(@TabelNaam, @VrVeldNaam);
  end if;

  if exists(select 1 from tabMutatieLogInstellingen
            inner join tabMutatieLogGroep on MugGid = MuiMugGid
            inner join tabMutatieLogTabel on MutMugGid = MugGid
            where (MutTabelNaam = @TabelNaam) or ((MutIsPrefix = 1) and (Left(@TabelNaam, Length(MutTabelNaam)) = MutTabelNaam))) then
    call MutatieLog_DisableTable(@TabelNaam);
    call MutatieLog_EnableTable(@TabelNaam);
  end if;

  set @@ErrorTextProcedure = 'VrUpdate';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure VrUpdateSelecties(in @VrGid integer)
begin
  //--- procedure die de selecties van een tijdelijke tabel copieert naar de tabel van de vrije rubrieken

  update tabVrijeRubrieken
  set    vrSelecties = (select first tmpVrSelecties from tmpVrijeRubrieken)
  where  vrGid = @VrGid;

end;


create or replace function VrVeldNaam(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer, in @VrLabel nchar(40))
returns nchar(40)
begin
  declare @VrVeldNaam nchar(40);

  select VrVeldNaam into @VrVeldNaam from tabVrijeRubrieken where (VrBestandOms = @VrBestandOms) and (VrGroepId = @VrGroepId) and (VrSubGroepId = @VrGroepId) and (VrLabel = @VrLabel);
  return(@VrVeldNaam);
end;


create or replace procedure VrVervangKeuze(in @VrBestandOms nchar(3), in @VrGroepId integer, in @VrSubGroepId integer,
															  in @VrGid integer, in @OudeKeuze nchar(40), in @NieuweKeuze nchar(40))
begin
  declare @Exists                     integer;
  declare @VrTableName                nchar(20);
  declare @KeuzelijstVeldnaam         nchar(40);
  declare @VrType                     integer;

  //call TraceBegin('VrVervangKeuze');

  //--- naam tabel samenstellen
  set @VrTableName = VrTabelnaam(@VrBestandOms, @VrGroepId, @VrSubGroepId);

  //--- veldnaam en soort van de keuzelijst ophalen
  select VrVeldnaam, VrType into @KeuzelijstVeldnaam, @VrType
  from   tabVrijeRubrieken
  where  vrGid = @VrGid;

  //--- controle op bestaan tabel en kolom
  call ColumnExist(@VrTableName, @KeuzelijstVeldnaam, @Exists);

  //--- vervangen als dat mogelijk is
  if (@Exists <> 0) and (@VrType = 5) then

    //--- records updaten
    execute immediate 'update ' +@VrTablename+ ' set ' + @KeuzelijstVeldnaam + ' = ''' + Replace(@NieuweKeuze, '''', '''''') + ''' '+
                      'where  ' +@KeuzelijstVeldnaam+ ' = ''' +Replace(@OudeKeuze, '''', '''''')+ '''';

  end if;

  //call TraceEind('VrVervangKeuze');

end;


create or replace procedure VrWaardeWijzigen(
  in @VrBestandOms nchar(3),
  in @VrGroepId integer,
  in @VrSubGroepId integer,
  in @ItemGid integer,
  in @VrLabel nchar(40),
  in @VrData nchar(255))
begin
  //call TraceBegin('VrWaardeWijzigen(' + @VrbestandOnms + string(VtbNummer) + ',' + @VtbiCode + ')');
  //MR 23-mar-2022 defect 57505: Deze sp is dezelfde als VrInsertOrReplaceValue. Als je deze wil gebruiken gebruik dan VrInsertOrReplaceValue.
  call VrInsertOrReplaceValue(@VrBestandOms,
                              @VrGroepId,
                              @VrSubGroepId,
                              @ItemGid,
                              @VrLabel,
                              @VrData);

  //call TraceEnd('WebSvcProc_VrijeTabel_Item_VrijeRubriek_Wijzigen');
end;

create or replace function WebSvcHulpProc_CheckAndReturn_BtwCode(
  in @Veldnaam nchar(40),      // tbv terugmelden
  in @BtwCode nchar(3),         // < 0 betekent returnwaarde NULL zonder controles (t.b.v. verwijderen)
  in @BtwSoort smallint,       // zie BtwSoort; 1=Af te dragen, 2= Te verrekenen
  in @BtwLndGidLandAangifte integer,
  in @BtwLeveringVanuit smallint, // zie BtwLeveringVanuit
  in @BtwPrestatiesoort smallint  // zie BtwPrestatieSoort
  )
returns integer // BTWcode
begin
  declare @result integer = null;
  declare @_BtwCode integer;
  declare @_BtwLndGid         integer;
  declare @_BtwLeveringVanuit smallint;
  declare @_BtwPrestatieSoort smallint;
  declare @_BtwSoort          smallint;

  if (@BtwCode like '%.%' or isnumeric(@BtwCode) = 0) and (isnull(@BtwCode, '') <> '') then
    // Lege string OF integer
    call Raise(20700, @Veldnaam); //(20700) Ongeldige waarde: %1!
  end if;

  if isnumeric(@BtwCode) = 1 and cast(@BtwCode as integer) >= 0 then
    select BtwCode, BtwLndGid, BtwLeveringVanuit, BtwPrestatieSoort, BtwSoort
    into @_BtwCode, @_BtwLndGid,  @_BtwLeveringVanuit, @_BtwPrestatieSoort, @_BtwSoort
    from tabBtw where BtwCode = @BtwCode;

    // Controleer bestaan van BTW-code
    if (@_BtwCode is null) then
      call Raise(20700, @Veldnaam); //(20700) Ongeldige waarde: %1!
    end if;
    // Controleer BTW-soort
    if @_BtwSoort <> @BtwSoort then
      call Raise(20780, @Veldnaam, _U('Soort BTW is onjuist')); //(20780) %1! niet mogelijk: %2!.
    end if;

    // Controleer LeveringVanuit
    call trace('BTW: ' || @_BtwLeveringVanuit || '; Meegegeven: ' || @BtwLeveringVanuit);
    if @_BtwLeveringVanuit <> @BtwLeveringVanuit then
      call Raise(20780, @Veldnaam, _U('Levering vanuit van de BTW-code komt niet overeen')); //(20780) %1! niet mogelijk: %2!.
    end if;
    // Controleer Prestatiesoort
    if @_BtwPrestatieSoort <> @BtwPrestatieSoort then
      call Raise(20780, @Veldnaam, _U('Prestatiesoort van de BTW-code en de opbrengstgroep komen niet overeen')); //(20780) %1! niet mogelijk: %2!.
    end if;

    if @BtwLndGidLandAangifte <> @_BtwLndGid then
      call Raise(20780, @Veldnaam, _U('Land van aangifte van de BTW-code en de Landcode komen niet overeen')); //(20701) Ongeldige combinatie: %1!
    end if;

    set @result = @_BtwCode;
  end if;

  return @result;
end;


create or replace procedure WebSvcHulpProc_Inkoopfactuur_ValideerKopgegevens(
  in @Mode smallint default 1, //1 = toevoegen, 0 = Wijzigen
  in @LeverancierNummer nchar(10) default null,
  in @InkoopfactuurNummer nchar(40) default null,
  in @InkoopfactuurDatum date default null,
  in @Betalingsconditie integer default null,
  in @ValutaCode nchar(3) default null,
  in @VervalDatum date default null,
  in @Betalingskenmerk nchar(140) default null,
  in @Referentienummer nchar(40) default null,
  in @BerekenBTWBlok smallint default null,
  in @Goedgekeurd smallint default null,
  in @GoedgekeurdOp datetime default null,
  in @GoedgekeurdDoor nchar(20) default null,
  out @_NawGid integer default null,
  out @_IfkGid integer default null,
  out @_BtcNummer integer default null,
  out @_ValNummer integer default null,
  out @_VervalDatum date default null,
  out @_Betalingskenmerk nchar(140) default null,
  out @_Referentienummer nchar(40) default null,
  out @_BerekenBTWBlok smallint default null,
  out @_IsGoedgekeurd smallint default null,
  out @_GoedgekeurdOp datetime default null,
  out @_GoedgekeurdDoor nchar(20) default null,
  out @_AanGemaaktOp datetime default null,
  out @_AanGemaaktDoor nchar(20) default null
  )
begin
  // Query constants
  declare _qcTOEVOEGEN smallint = 1;
  declare _qcWIJZIGEN smallint = 0;
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  //Module check
  if IsModuleActive('if') = _qcNEE then
    call Raise(20905); //Optie ''Webservices Inkoopfactuur'' niet geactiveerd!
  end if;

  //Leveranciernummer checks
  if IsNull(@Leveranciernummer, '') = '' then
    call Raise(20613); //(20613) Ongeldige of geen LeverancierNummer meegegeven!
  end if;

  select NawFilNawGid into @_NawGid from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @Leveranciernummer;
  if (@_NawGid is null) then
    call Raise(20613); //(20613) Ongeldige of geen LeverancierNummer meegegeven!
  end if;

  //Inkoopfactuurnummer check
  if IsNull(@Inkoopfactuurnummer, '') = '' then
    call Raise(20684); //(20684) Ongeldige of geen Inkoopfactuurnummer meegegeven!
  end if;

  //Inkoopfactuurdatum check
  if @Inkoopfactuurdatum is null then
    call Raise(20685); //(20685) Ongeldige of geen Inkoopfactuurdatum meegegeven!
  end if;

  if not exists (select PerBjGid from tabPeriode where @Inkoopfactuurdatum between BeginDatum and EindDatum) then
    call Raise(20107); //(20107) Datum moet in een bestaand boekjaar liggen!
  end if;

  //Check bij het wijzigen of de combinatie van leveranciernummer, inkoopfactuurdatum en inkoopfactuurnummer bestaat.
  if @mode = _qcWIJZIGEN then
  begin
    declare @_IfkIsVerwerkt smallint;

    select IfkGid, IfkIsVerwerkt
    into @_IfkGid, @_IfkIsVerwerkt
    from tabInkoopfactuurKop
    where IfkNawGid = @_NawGid
      and IfkFactuurDatum = @InkoopfactuurDatum
      and IfkFactuurNummer = @InkoopfactuurNummer;

    if (@_IfkGid is null) then
      call Raise(20720, _U('Inkoopfactuur')); //(20720) %1! niet gevonden!
    end if;

    if @_IfkIsVerwerkt = _qcJA then
      call Raise(20780, _U('Wijzigen inkoopfactuur'),_U('Inkoopfactuur is al verwerkt'));  // <Actie> niet mogelijk. Reden: <Reden>.
    end if;
  end;
  else
  begin
  //Bestaat Factuurnummer in een boekjaar
    declare @_BjCode nchar(20);

    select first Code into @_BjCode
    from tabInkoopfactuurKop
    inner join tabBoekjaar on BjGid = BoekjaarBepalen(@InkoopfactuurDatum)
    where
      IfkFactuurNummer_lengte = Len(@Inkoopfactuurnummer) and
      IfkFactuurNummer = @Inkoopfactuurnummer and
      IfkNawGid = @_NawGid and
      BjGid = BoekjaarBepalen(IfkFactuurDatum);

    if @_BjCode is not null then
      call Raise(20689, @InkoopfactuurNummer, @LeverancierNummer, @_BjCode); // (20689) Inkoopfactuurnummer %1 van leverancier %2 komt al voor in boekjaar %3!;
    end if;
  end;
  end if;

  //Als je in mode wijzigen zit kan je de waardes vullen met de waarde uit de tabellen.
  if @mode = _qcWIJZIGEN then
    select
      IfkVervaldatum,
      IfkBetalingskenmerk,
      IfkBtcNummer,
      IfkValNummer,
      IfkBerekenBtwBlokAutom,
      IfkReferentienummer,
      IfkIsGoedgekeurd,
      IfkGoedgekeurdDoor,
      IfkGoedgekeurdOp,
      IfkAangemaaktDoor,
      IfkAangemaaktOp
    into
      @_VervalDatum,
      @_Betalingskenmerk,
      @_BtcNummer,
      @_ValNummer,
      @_BerekenBTWBlok,
      @_Referentienummer,
      @_IsGoedgekeurd,
      @_GoedgekeurdDoor,
      @_GoedgekeurdOp,
      @_AangemaaktDoor,
      @_AangemaaktOp
    from tabInkoopfactuurKop
    where IfkGid = @_IfkGid;
  else
    set @_AangemaaktOp = Now();
    set @_AangemaaktDoor = @@Gebruikercode;
  end if;

  // Betalingsconditie
  if @BetalingsConditie is not null then
    select BtcNummer into @_BtcNummer from tabBetalingsConditie where BtcNummer = @BetalingsConditie;
    if (@_BtcNummer is null) then
      call Raise(20514);  //Ongeldige of geen BetalingsConditie meegegeven
    end if;
  else
    if @mode = _qcTOEVOEGEN then
      select NawFilBtcNummer into @_BtcNummer from tabNawFile where NawFilNawGid = @_NawGid and NawFilFonID = 'C';
    end if;
  end if;

  //Valnummer
  if (@mode = _qcTOEVOEGEN) then
    select ValNummer into @_ValNummer from tabValuta where ValCode = @ValutaCode;

    if (@_ValNummer is null) then
      call Raise(20512);  //Ongeldige of geen ValutaCode meegegeven
    end if;
  end if;

  // Vervaldatum
  if @Vervaldatum is null then
    if @Mode = _qcTOEVOEGEN then
      call BerekenVervalDatumFactuur (@InkoopfactuurDatum, @_BtcNummer, @_VervalDatum);
    end if;
  else
    if @Vervaldatum < @InkoopfactuurDatum then
      call Raise(20067); //(20067) De vervaldatum moet na de factuurdatum liggen
    end if;

    set @_VervalDatum = @VervalDatum;
  end if;

  //Betalingskenmerk
  if (@Mode = _qcTOEVOEGEN) and (@Betalingskenmerk is null) then
  begin
    declare @_OnsDebiteurNummer  nchar(20);
    select NawOnsDebiteurNummer into @_OnsDebiteurNummer from tabNaw where NawGid = @_NawGid;
    set @_Betalingskenmerk = InkoopfactuurDefaultBetalingskenmerk(@Inkoopfactuurnummer, @_OnsDebiteurNummer, @LeverancierNummer)
  end;
  else
    set @_Betalingskenmerk = isNull(@Betalingskenmerk, @_Betalingskenmerk);
  end if;

  //Referentienummer
  if (@Mode = _qcTOEVOEGEN) and IsNull(@Referentienummer, '') = '' then
    set @_Referentienummer = @InkoopfactuurNummer
  else
    set @_Referentienummer = isNull(@Referentienummer, @_Referentienummer);
  end if;

  //BerekenBTWBlokBTW
  if (@Mode = _qcTOEVOEGEN) or (@BerekenBTWBlok is not null) then
    set @_BerekenBTWBlok = isNull(@BerekenBTWBlok, _qcJA);

    if not (@_BerekenBTWBlok in (_qcNEE, _qcJA)) then
      call Raise(20700, 'BerekenBTWblok'); // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  //Goedgekeurd
  if (@Mode = _qcTOEVOEGEN) or (@Goedgekeurd is not null) then
    set @_IsGoedgekeurd = isNull(@Goedgekeurd, _qcJA);

    if not (@_IsGoedgekeurd in (_qcNEE, _qcJA)) then
      call Raise(20700, 'Goedgekeurd') ; // (20700) Ongeldige waarde: %1!
    end if;

    if @_IsGoedgekeurd = _qcJA then
      if (not @GoedgekeurdDoor is Null) and
      not exists(select 1 from tabGebruiker where NaamGebruiker = @GoedgekeurdDoor) then
        call Raise(20720, 'GoedgekeurdDoor') ; //(20720) %1! niet gevonden!
      end if;

      set @_GoedgekeurdOp = isNull(@GoedgekeurdOp, Now());
      set @_GoedgekeurdDoor = isNull(@GoedgekeurdDoor, @@Gebruikercode);
    else
      set @_GoedgekeurdOp = null;
      set @_GoedgekeurdDoor = null;
    end if;
  end if;
end;


create or replace procedure WebSvcHulpProc_NAW_ContactPersoon_ToevoegenWijzigen(
  in @NawGid integer,
  in @ContactPersoonNummer numeric(3,0),
  in @AchterNaam nchar(40),
  in @VoorVoegsel nchar(40),
  in @VoorLetters nchar(15),
  in @VoorNaam nchar(40),
  in @Titel nchar(15),
  in @AchterVoegsel nchar(15),
  in @VolledigeNaam nchar(40),
  in @Geslacht nchar(8),
  in @Telefoon1 nchar(25),
  in @Telefoon2 nchar(25),
  in @Telefax nchar(25),
  in @EMail nchar(80),
  in @ContributieCode numeric(3,0),
  in @NaamInAdres nchar(60),
  in @NaamInAanhef nchar(60),
  in @NaamInBrief nchar(60),
  in @Opmerking long nvarchar,
  in @AanheftekstenAutomatischVullen nchar(3)) //'JA', 'NEE'

result(ContactPersoonNummer numeric(3,0))

begin
  declare _qcNee smallint = 0;
  declare _qcJa nchar(2) = 'JA';
  declare @_RelGid       integer;
  declare @_RelGeslacht  smallint;
  declare @_ContrCode    integer;

  if IsModuleActive('we') = _qcNee then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select RelGid, RelGeslacht into @_RelGid, @_RelGeslacht
  from   tabRelatie
  where  RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;

  if @_RelGid is null then // nieuwe contactpersoon toevoegen
    set @_RelGeslacht = 0; // default is geslacht dan onbekend
  end if;

  // geslacht ingevuld? dan @_RelGeslacht bepalen
  if IsNull(@Geslacht, '') <> '' then
    case @Geslacht
      when 'ONBEKEND' then set @_RelGeslacht = 0;
      when 'MAN'      then set @_RelGeslacht = 1;
      when 'VROUW'    then set @_RelGeslacht = 2;
      else call Raise(20589); //Ongeldige of geen Geslacht meegegeven!
    end case;
  end if;

  if @ContributieCode is not null then
    select ContributieCode
      into @_ContrCode
    from tabContributieCode
    where ContributieCode = @ContributieCode;

    if (@_ContrCode is null) then
      call Raise(20591); //Ongeldige of geen ContributieCode meegegeven!
    end if;
  end if;


  //Negeer de opgegeven namen en de aanhefteksten automatisch vullen
  if UPPER(@AanheftekstenAutomatischVullen) = _qcJa then
      select TekstAanhef + rtrim(' ' + Upper(left(IsNull(@VoorVoegsel, RelVoorvoegsel),1)) +
                          right(IsNull(@VoorVoegsel, RelVoorvoegsel),length(IsNull(@VoorVoegsel, RelVoorvoegsel))-1)) +
                          rtrim(' ' + IsNull(@AchterNaam, RelAchternaam)),
           TekstAdres + rtrim(' ' + IsNull(@VolledigeNaam, RelVolledigeNaam)),
           TekstBrief +  rtrim(' ' + Upper(left(IsNull(@VoorVoegsel, RelVoorvoegsel),1)) +
                          right(IsNull(@VoorVoegsel, RelVoorvoegsel),length(IsNull(@VoorVoegsel, RelVoorvoegsel))-1)) +
                          rtrim(' ' + IsNull(@AchterNaam, RelAchternaam))
    into @NaamInAanhef, @NaamInAdres, @NaamInBrief
    from tabNaw
    inner join tabAanhef on AanhefTaalGid = nawTaalGid
    left outer join tabRelatie on RelNawGid = nawGid and RelGid = @_RelGid
    where nawGid = @NawGid
      and GeslachtAanhef = @_RelGeslacht
  end if;

  if (@_RelGid is null) then
    if (@ContactPersoonNummer is null) then
      set @ContactPersoonNummer = IsNull((select max(RelNummer) from tabRelatie where RelNawGid = @NawGid), 0)+1;

      if length(@ContactPersoonNummer) > 3 then
        call Raise(20590); //Er kan geen nieuwe ContactPersoonNummer worden gegenereerd, het hoogst gebruikte ContactPersoonNummer is 999!
      end if;
    end if;

    insert into tabRelatie (
      RelNawGid, RelNummer, RelAchternaam, RelVoorvoegsel,
      RelVoorletters, RelVoornaam, RelTitel, RelAchtervoegsel,
      RelVolledigeNaam, RelGeslacht, RelTelefoon, RelTelefoon2,
      RelEmail, RelContributieCode, RelTelefax,
      RelNaamInAdres, RelNaamInAanhef, RelNaamInBrief)
    values (
      @NawGid, @ContactPersoonNummer, @AchterNaam, @VoorVoegsel,
      @VoorLetters, @VoorNaam, @Titel, @AchterVoegsel,
      @VolledigeNaam, @_RelGeslacht, @Telefoon1, @Telefoon2,
      @EMail, @_ContrCode, @Telefax,
      @NaamInAdres, @NaamInAanhef, @NaamInBrief);

    set @_RelGid = @@Identity;
  else
    update tabRelatie
    set RelAchternaam = IsNull(@AchterNaam, RelAchternaam),
        RelVoorvoegsel = IsNull(@VoorVoegsel, RelVoorvoegsel),
        RelVoorletters = IsNull(@VoorLetters, RelVoorletters),
        RelVoornaam = IsNull(@VoorNaam, RelVoornaam),
        RelTitel = IsNull(@Titel, RelTitel),
        RelAchtervoegsel = IsNull(@AchterVoegsel, RelAchtervoegsel),
        RelVolledigeNaam = IsNull(@VolledigeNaam, RelVolledigeNaam),
        RelTelefoon = IsNull(@Telefoon1, RelTelefoon),
        RelTelefoon2 = IsNull(@Telefoon2, RelTelefoon2),
        RelTelefax = IsNull(@Telefax, RelTelefax),
        RelEmail = IsNull(@EMail, RelEmail),
        RelContributieCode = IsNull(@_ContrCode, RelContributieCode),
        RelNaamInAdres = IsNull(@NaamInAdres, RelNaamInAdres),
        RelNaamInAanhef = IsNull(@NaamInAanhef, RelNaamInAanhef),
        RelNaamInBrief = IsNull(@NaamInBrief, RelNaamInBrief),
        RelGeslacht = IsNull(@_RelGeslacht, RelGeslacht)
    where RelGid = @_RelGid;
  end if;

  if exists(select 1 from tabRelatieOpmerkingen where RelOpmRelGid = @_RelGid) then
    update tabRelatieOpmerkingen
    set RelOpmOpmerking = IsNull(@Opmerking, RelOpmOpmerking)
    where RelOpmRelGid = @_RelGid;
  else
    if IsNull(@Opmerking, '') <> '' then
      insert into tabRelatieOpmerkingen (RelOpmRelGid, RelOpmOpmerking) select @_RelGid, @Opmerking;
    end if;
  end if;

  select RelNummer as ContactPersoonNummer from tabRelatie where RelGid = @_RelGid;

end;


create or replace procedure WebSvcHulpProc_NAW_ControleerVeldenEnOvernemenVastegegevens(
  //Crediteuren/Debiteuren
  in @Mode smallint default 1,    //0 = wijzigen, 1 = toevoegen
  in @FonGid integer default null,
  in @LandCode nchar(3) default null,
  in @TaalCode nchar(3) default null,
  in @BetalingsConditieNummer numeric(3,0) default null,
  in @LeveringsConditieNummer numeric(3,0) default null,
  in @ValutaCode nchar(3) default null,
  in @BtwCode numeric(3,0) default null,
  in @KredietLimiet numeric(15,2) default null,
  in @DefaultTegenrekening nchar(28) default null,
  //Debiteuren
  in @AanmaningsType nchar(20) default null,  //'GEEN', 'AANMANING', 'REKENINGOVERZICHT'
  in @AparteFacturen nchar(10) default null, //'JA', 'NEE', 'PERCP', 'PERVZ', 'PERCPVZ'
  in @FacturerenInclusiefBtw smallint default null,
  in @FactuurAdres nchar(4) default null, //'COR', 'VEST'
  in @IsInkoopCombinatie smallint default null,
  in @VerzendAdres nchar(10) default null, //'COR', 'VEST', 'VERZ', 'FACT_COR', 'FACT_VEST', 'FACT_VERZ'
  in @NawVerzendadres smallint default null,
  in @Debiteurgroep numeric(3,0) default null,
  in @VertegenwoordigerNummer numeric(3,0) default null,
  in @AantalKopieFacturen integer default null,
  in @OrdKortingDebOfDebGroep smallint default null,
  in @OrderKortingsPercentage numeric(6,2) default null,
  in @BlokkerenVoorOrderInvoer smallint default null,
  in @WebKlant smallint default null,
  in @DefaultVervoerder nchar(40) default null,
  //Crediteuren/Debiteuren
  inout @_FonLndGid integer default null,
  inout @_TaalGid integer default null,
  inout @_FonBtcNummer integer default null,
  inout @_FonLvcNummer integer default null,
  inout @_ValNummer integer default null,
  inout @_FonBtwCode integer default null,
  inout @_FonKredietLimiet numeric(15,2) default null,
  inout @_FonTegenRksGid integer default null,
  //Debiteuren
  inout @_FonAanmaningType smallint default 1,
//  inout @_fonIncMaxPogingen smallint,
  inout @_FonApartFactureren smallint default 0,
  inout @_FonAparteLevering smallint default null,
  inout @_FonFactuurBTW smallint default 1,
  inout @_FonFactuurAdres smallint default null,
  inout @_FonVerzendAdres smallint default null,
  inout @_FonEindAdres smallint default null,
  inout @_FonDebGrpGid integer default null,
  inout @_FonVtCode integer default null,
  inout @_FonContributieCode integer default null,
  inout @_FonAantKopieFacturen integer default null,
  inout @_FonOrdKortingDebOfDebGroep smallint default null, //0 = van debiteur, 1 = van debiteurgroep
  inout @_FonOrderKorting numeric(6,2) default null,
  inout @_FonVrvGid integer default null,
  inout @_FonBlokOrderInvoer smallint default null,
  inout @_FonIsWebklant smallint default null
  )
begin
  declare _TOEVOEGEN smallint = 1;
  declare _WIJZIGEN smallint = 0;
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;
  declare _qcCrediteur nchar(1) = 'C';
  declare _qcDebiteur nchar(1) = 'D';

  declare @_FonGid integer;

  //Taal en land
  if isNull(@TaalCode, '') <> '' then
    select TaalGid
    into @_TaalGid
    from tabTaal
    where TaalCode = @TaalCode;

    if (@_TaalGid is null) then
      call Raise(20549); //Ongeldige of geen TaalCode meegegeven!
    end if;
  end if;

  if (IsNull(@ValutaCode, '') <> '') then
    select ValNummer into @_ValNummer from tabValuta where ValCode = @ValutaCode;

    if (@_ValNummer is null) then
      call Raise(20512); //Ongeldige of geen ValutaCode meegegeven!
    end if;
  end if;

  if isNull(@LandCode, '') <> '' then
    select isNull(@_TaalGid, LndTaalGid),LndGid, isNull(@_ValNummer, lndValNummer)
    into @_TaalGid, @_FonLndGid, @_ValNummer
    from tabland
    where LndEigenCode = @Landcode;

    if (@_FonLndGid is null) then
      call Raise(20553); //Ongeldige of geen LandCode meegegeven!
    end if;
  end if;

  if @BetalingsConditieNummer is not null then
    select BtcNummer into @_FonBtcNummer from tabBetalingsConditie where BtcNummer = @BetalingsConditieNummer;

    if (@_FonBtcNummer is null) then
      call Raise(20514); //Ongeldige of geen BetalingsConditieNummer meegegeven!
    end if;
  end if;

  if @LeveringsConditieNummer is not null then
    select LvcNummer into @_FonLvcNummer from tabLeveringsConditie where LvcNummer = @LeveringsConditieNummer;

    if (@_FonLvcNummer is null) then
      call Raise(20515); //Ongeldige of geen LeveringsConditieNummer meegegeven!
    end if;
  end if;

  if @BtwCode is not null then
    select BtwCode into @_FonBtwCode from tabBtw where BtwCode = @BtwCode;

    if (@_FonBtwCode is null) then
      call Raise(20525); //Ongeldige of geen BtwCode meegegeven!
    end if;
  end if;

  if IsNull(@AanmaningsType, '') <> '' then
    case @AanmaningsType
      when 'GEEN'              then set @_FonAanmaningType = 0;
      when 'AANMANING'         then set @_FonAanmaningType = 1;
      when 'REKENINGOVERZICHT' then set @_FonAanmaningType = 2;
      else call Raise(20551); //Ongeldige of geen AanmaningsType meegegeven!
    end case;
  end if;

  if IsNull(@DefaultTegenrekening, '') <> '' then
    Select RksGid
    into @_FonTegenRksGid
    from tabRekeningSchema
    where RksInvoer = @DefaultTegenrekening;

    if @_FonTegenRksGid is null then
      call Raise(20700,'DefaultTegenrekening'); //Ongeldige waarde: %1!
    end if;
  end if;

  if IsNull(@AparteFacturen, '') <> '' then
    case @AparteFacturen
      when 'JA'      then set @_FonApartFactureren = 0;
      when 'NEE'     then set @_FonApartFactureren = 1;
      when 'PERCP'   then set @_FonApartFactureren = 2;
      when 'PERVZ'   then set @_FonApartFactureren = 3;
      when 'PERCPVZ' then set @_FonApartFactureren = 4;
      else call Raise(20552); //Ongeldige of geen AparteFacturen meegegeven!
    end case;
  end if;

  if IsNull(@FactuurAdres, '') <> '' then
    case @FactuurAdres
      when 'COR'  then set @_FonFactuurAdres = 0;
      when 'VEST' then set @_FonFactuurAdres = 1;
      else call Raise(20506); //Ongeldige of geen FactuurAdres meegegeven!
    end case;
  end if;

  if IsNull(@VerzendAdres, '') <> '' then
    if @IsInkoopCombinatie = _qcJA then
      case @VerzendAdres
        when 'COR'       then set @_FonVerzendAdres = 0;
        when 'VEST'      then set @_FonVerzendAdres = 1;
        when 'VERZ'      then set @_FonVerzendAdres = 2;
        when 'FACT_COR'  then set @_FonVerzendAdres = 3;
        when 'FACT_VEST' then set @_FonVerzendAdres = 4;
        when 'FACT_VERZ' then set @_FonVerzendAdres = 5;
        else call Raise(20507); //Ongeldige of geen VerzendAdres meegegeven!
      end case;
    else
      case @VerzendAdres
        when 'COR'       then set @_FonVerzendAdres = 0;
        when 'VEST'      then set @_FonVerzendAdres = 1;
        when 'VERZ'      then set @_FonVerzendAdres = 2;
        else call Raise(20507); //Ongeldige of geen VerzendAdres meegegeven!
      end case;
    end if;
  else
    //Geen inkoopcombinatie en huidige verzendadres is 3,4 of 5 wijzigen naar de vaste gegeven
    if @IsInkoopCombinatie = _qcNEE and @NawVerzendadres in (3,4,5) and @Mode = _WIJZIGEN then
      select FonVerzendAdres into @_FonVerzendAdres from tabFileOfNaw WHERE FonGid = @FonGid;
    end if;
  end if;

  if @Debiteurgroep is not null then
    select DebGrpGid into @_FonDebGrpGid from tabDebiteurGroepen where DebGrpNr = @Debiteurgroep;

    if @_FonDebGrpGid is null then
      call Raise(20686, 'Debiteurgroep'); // (20686) %1! niet gevonden!
    end if;
  end if;

  if @VertegenwoordigerNummer is not null then
    select VtgCode into @_FonVtCode from tabVertegenWoordiger where VtgCode = @VertegenwoordigerNummer;

    if (@_FonVtCode is null) then
      call Raise(20513); //Ongeldige of geen VertegenwoordigerNummer meegegeven!
    end if;
  end if;

  if @AantalKopieFacturen is not null then
    if (@AantalKopieFacturen < 0) or (@AantalKopieFacturen > 99) then
      call Raise(20550); //Ongeldige of geen AantalKopieFacturen meegegeven
    end if;
  end if;

  if @OrderKortingsPercentage is not null then
    set @OrdKortingDebOfDebGroep = 0; //Van debiteur als er een kortingspercentage is meegegeven
    if (@OrderKortingsPercentage < -100) or (@OrderKortingsPercentage > 100) then
      call Raise(20516); //Ongeldige of geen OrderKortingsPercentage meegegeven
    end if;
    select @OrderKortingsPercentage into @_FonOrderKorting;
  end if;

  if IsNull(@DefaultVervoerder, '') <> '' then
    Select VrvGid
    into @_FonVrvGid
    from tabVervoerder
    where VrVNaam = @DefaultVervoerder;

    if @_FonVrvGid is null then
      call Raise(20700, 'DefaultVervoerder'); //Ongeldige waarde: %1!
    end if;
  end if;

  if (@KredietLimiet is not null) and (@Mode = _WIJZIGEN) then
    select (if (@KredietLimiet = FonKredietLimiet) then null else @KredietLimiet endif)
      into @_FonKredietLimiet
    FROM tabFileOfNaw
    left outer join tabland on lndGid = fonLndGid
    WHERE FonGid = @FonGid
  end if;

  //Waarde niet 0 of null omzetten naar 1
  if @FacturerenInclusiefBtw not in (_qcNEE , _qcJA) then
    call Raise(20700, 'FacturerenInclusiefBtw');  //Ongeldige waarde <Parameternaam of opmerking>
  end if;

  if @BlokkerenVoorOrderInvoer not in (_qcNEE , _qcJA) then
    call Raise(20700, 'BlokkerenVoorOrderInvoer');  //Ongeldige waarde <Parameternaam of opmerking>
  end if;

  if @WebKlant not in (_qcNEE , _qcJA) then
    call Raise(20700, 'WebKlant');  //Ongeldige waarde <Parameternaam of opmerking>
  end if;

  //Als de meegegeven parameter gevuld is die gebruiken, anders degene uit vaste gegevens
  //Lees de vaste gegevens in.
  SELECT
    fonGID,
    isNull(@_FonLndGid, fonLndGid),
    isNull(@_TaalGid, lndTaalgid),
    isNull(@_FonBtcNummer, FonBtcNummer),
    isNull(@_FonLvcNummer, FonLvcNummer),
    isNull(@_ValNummer, lndValNummer),
    isNull(@_FonBtwCode, FonBtwCode),
    (if (@KredietLimiet = FonKredietLimiet) then null else @KredietLimiet endif), //KredietLimiet alleen vullen als deze afwijkt van de default
    isNull(@_FonTegenRksGid, FonTegenRksGid),
    isNull(@_FonAanmaningType, if (FonID = _qcDebiteur) then FonAanmaningType endif),
    isNull(@_FonApartFactureren, if (FonID = _qcDebiteur) then FonApartFactureren endif),
    isNull(@_FonAparteLevering, if (FonID = _qcDebiteur) then FonApartLeveren endif),
    isNull(@FacturerenInclusiefBtw, if (FonID = _qcDebiteur) then FonFactuurBTW endif),
    isNull(@_FonFactuurAdres, if (FonID = _qcDebiteur) then FonFactuurAdres endif),
    isNull(@_FonVerzendAdres, if (FonID = _qcDebiteur) then FonVerzendAdres endif),
    FonEindAdres,
    isNull(@_FonDebGrpGid, if (FonID = _qcDebiteur) then FonDebGrpGid endif),
    isNull(@_FonVtCode, if (FonID = _qcDebiteur) then FonVtCode endif),
    FonContributieCode,
    isNull(@AantalKopieFacturen, if (FonID = _qcDebiteur) then FonAantKopieFacturen endif),
    isNull(@OrdKortingDebOfDebGroep, if (FonID = _qcDebiteur) then FonOrdKortingDebOfDebGroep endif),
    isNull(@OrderKortingsPercentage, if (FonID = _qcDebiteur) then FonOrderKorting endif),
    isNull(@_FonVrvGid, if (FonID = _qcDebiteur) then FonVrvGid endif),
    isNull(@BlokkerenVoorOrderInvoer, if (FonID = _qcDebiteur) then FonBlokOrderInvoer endif),
    isNull(@WebKlant, if (FonID = _qcDebiteur) then FonIsWebklant endif)
  into
    @_FonGid,
    @_fonLndGid,
    @_TaalGid,
    @_FonBtcNummer,
    @_FonLvcNummer,
    @_ValNummer,
    @_FonBtwCode,
    @_FonKredietLimiet,
    @_FonTegenRksGid,
    @_FonAanmaningType,
    @_FonApartFactureren,
    @_FonAparteLevering,
    @_FonFactuurBTW,
    @_FonFactuurAdres,
    @_FonVerzendAdres,
    @_FonEindAdres,
    @_FonDebGrpGid,
    @_FonVtCode,
    @_FonContributieCode,
    @_FonAantKopieFacturen,
    @_FonOrdKortingDebOfDebGroep,
    @_FonOrderKorting,
    @_FonVrvGid,
    @_FonBlokOrderInvoer,
    @_FonIsWebklant
  FROM tabFileOfNaw
  left outer join tabland on lndGid = fonLndGid
  WHERE FonGid = @FonGid
    and @Mode = _TOEVOEGEN;

  if @Mode = _WIJZIGEN then
    set @_FonIsWebklant = @WebKlant;
    set @_FonFactuurBTW = @FacturerenInclusiefBtw;
    set @_FonBlokOrderInvoer = @BlokkerenVoorOrderInvoer;
    set @_FonOrdKortingDebOfDebGroep = @OrdKortingDebOfDebGroep;
  end if;

  if (@_TaalGid is null) and (@Mode = _TOEVOEGEN) then
    call Raise(20549); //Ongeldige of geen TaalCode meegegeven!
  end if;

  if (@_ValNummer is null) and (@Mode = _TOEVOEGEN) then
    call Raise(20512); //Ongeldige of geen ValutaCode meegegeven!
  end if;

  //if @_FonGid is null then
  //  raiserror 20063; //(20063) Geen geldig FonId ingevoerd
  //end if;

end;


create or replace procedure WebSvcHulpProc_NAW_OvernemenWebWinkels(
  in @NawFilWebNaw smallint, // 1 = ja, 0 = nee
  in @NawGid integer default null)
begin
  // Query constants
  declare _qcJA smallint = 1;
  declare _qcDebiteur smallint = 0;

  //Als NawFilWebNaw leeg (null) is, niets doen
  if @NawFilWebNaw is not null then
    //Geen webklant, dan hoef je niets te doen
    if @NawFilWebNaw = _qcJA then
      insert into tabWebNaw (WNawNawGid, WNawWscGid)
        select @NawGid, WscGid
        from tabWebshopConfiguratie
        inner join tabWebStamVasteGeg on WsvgSoort = _qcDebiteur and WsvgWscGid = WscGid
        where not exists(select 1 from tabWebNaw where WNawNawGid = @NawGid and WNawWscGid = WscGid);
    else
      delete tabWebNaw where WnawNawGid = @NawGid;
    end if;
  end if;
end;


create or replace procedure WebSvcHulpProc_NAW_ValideerInkoopcombinatie(
  in @Mode smallint, // 1 = toevoegen, 0 = Wijzigen
  in @NawGid integer default null,
  in @DebiteurNummer nchar(10),
  in @DebiteurNummerFactuur nchar(10),
  in @DebiteurNummerOmzet nchar(10),
  in @DebiteurNummerPrijsafspraken nchar(10),
  in @IsInkoopcombinatie smallint,
  out @_IsInkoopCombinatie smallint,
  out @_NawGidInkCombiFactuur integer,
  out @_NawGidInkCombiOmzet integer,
  out @_NawGidInkCombiPrijzen integer)
begin
  // Query constants
  declare _qcTOEVOEGEN smallint = 1;
  declare _qcWIJZIGEN smallint = 0;
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;
  declare _qcDebiteur nchar(1) = 'D';

  // ****************
  // INGANGSCONTROLES
  // ****************
  if @Mode = _qcTOEVOEGEN then
    set @_IsInkoopCombinatie = isnull(@IsInkoopCombinatie, _qcNEE);
  else
    select isnull(@IsInkoopCombinatie, NawIsInkoopCombinatie),
           isnull(nawIdFactDeb, @NawGid),
           isnull(NawidDebOmzet, @NawGid),
           isnull(NawidDebPrijzen, @NawGid)
    into @_IsInkoopCombinatie, @_NawGidInkCombiFactuur, @_NawGidInkCombiOmzet, @_NawGidInkCombiPrijzen
    from tabNaw
    where NawGid = @NawGid;
  end if;

  if @_IsInkoopCombinatie not in (_qcNEE , _qcJA) then
    call Raise(20700, 'InkoopCombinatie');  //Ongeldige waarde <Parameternaam of opmerking>
  end if;

  // inkoopcombinaties is alleen te gebruiken als licentie-optie actief is
  if IsModuleActive('i2') = _qcNEE /* niet actief */ then
    if @IsInkoopCombinatie is not null then
      call Raise(20790, _U('Optie Inkoopcombinaties')); // <Optie/Module> niet geactiveerd!
    end if;
  end if;

  if @_IsInkoopCombinatie = _qcJA then
    // Factuurdebiteur
    if IsNull(@DebiteurNummerFactuur, '') <> '' then
      set @_NawGidInkCombiFactuur = (select NawFilNawGid
                                     from tabNawFile
                                     where NawFilFonId = _qcDebiteur
                                      and NawFilNummer = @DebiteurNummerFactuur);

      if (@_NawGidInkCombiFactuur is null) and ((@DebiteurNummerFactuur <> @DebiteurNummer) and (@Mode = _qcTOEVOEGEN)) then
        call Raise(20700, String('DebiteurNummerFactuur: ', @DebiteurNummerFactuur)) ;  //Ongeldige waarde <Parameternaam of opmerking>
      end if;
    end if;

    // Debiteur Omzet
    if IsNull(@DebiteurNummerOmzet, '') <> '' then
      set @_NawGidInkCombiOmzet = ( select NawFilNawGid
                                    from tabNawFile
                                    where NawFilFonId = _qcDebiteur
                                      and NawFilNummer = @DebiteurNummerOmzet );

      if (@_NawGidInkCombiOmzet is null) and ((@DebiteurNummerOmzet <> @DebiteurNummer) and (@Mode = _qcTOEVOEGEN)) then
        call Raise(20700, String('DebiteurNummerOmzet: ', @DebiteurNummerOmzet)) ;  //Ongeldige waarde <Parameternaam of opmerking>
      end if;
    end if;

    // Debiteur Prijsafspraken
    if IsNull(@DebiteurNummerPrijsafspraken, '') <> '' then
      set @_NawGidInkCombiPrijzen = ( select NawFilNawGid
                                      from tabNawFile
                                      where NawFilFonId = _qcDebiteur
                                        and NawFilNummer = @DebiteurNummerPrijsafspraken );

      if (@_NawGidInkCombiPrijzen is null) and ((@DebiteurNummerPrijsafspraken <> @DebiteurNummer) and (@Mode = _qcTOEVOEGEN)) then

        call Raise(20700, String('DebiteurNummerPrijsafspraken: ', @DebiteurNummerPrijsafspraken));  //Ongeldige waarde <Parameternaam of opmerking>
      end if;
    end if;
  else
    set @_NawGidInkCombiFactuur = null;
    set @_NawGidInkCombiOmzet = null;
    set @_NawGidInkCombiPrijzen = null;
  end if;

  // Alle debiteuren zijn nu bekend als inkoopcombinatie aan staat.
  //Behalve bij een nieuwe debiteur. Als dan inkoopcombinatie aangezet wordt neem je later de huidige debiteur over.
  if (@_IsInkoopCombinatie = _qcJA) and (@mode = _qcWIJZIGEN) then
    if @_NawGidInkCombiFactuur is null then
      call Raise(20700, _U('%1! is verplicht.', 'DebiteurNummerFactuur')); //Ongeldige waarde <Parameternaam of opmerking>
    end if;
    if @_NawGidInkCombiOmzet is null then
      call Raise(20700, _U('%1! is verplicht.', 'DebiteurNummerOmzet')); //Ongeldige waarde <Parameternaam of opmerking>
    end if;
    if @_NawGidInkCombiPrijzen is null then
      call Raise(20700, _U('%1! is verplicht.', 'DebiteurNummerPrijsafspraken')); //Ongeldige waarde <Parameternaam of opmerking>
    end if;
  end if;
end;


create or replace procedure WebSvcProc_Abonnementen_Abonnementsregel_Toevoegen
(  in @AbonnementCode             nchar(20),
   in @VersieNummer               smallint,
   in @RegelSoort                 nchar(5),
   in @ArtikelNummer              nchar(20),
   in @PartijNummer               nchar(20),
   in @Aantal                     numeric(15,3),
   in @BtwCode                    integer,
   in @KostprijsOpnieuwBepalenBij nchar(15),
   in @Kostprijs                  numeric(15,3),
   in @BrutoVerkoopprijs          numeric(15,3),
   in @PrijsOpnieuwBepalenBij     nchar(15),
   in @Korting1IsPercentage       smallint,
   in @Korting1                   numeric(15,3),
   in @Korting1OpnieuwBepalenBij  nchar(15),
   in @Korting2                   numeric(15,3),
   in @Korting2OpnieuwBepalenBij  nchar(15),
   in @TekstOpOrder               long nvarchar)

result(RegelNr smallint)

begin
  declare @AboGid                  integer;
  declare @AboNawGidDebiteur       integer;
  declare @AbvGid                  integer;
  declare @AbvIsInkoopcombinatie   smallint;
  declare @AbvNawGidPrijzen        integer;
  declare @AbvValNummer            numeric(3,0);
  declare @AbvBtwStand             smallint;
  declare @AbvTaalGid              integer;
  declare @AbrGid                  integer;
  declare @AbrRegelNr              smallint;
  declare @AbrRegelsoort           smallint;
  declare @AbrBtwCode              integer;
  declare @AbrKostprijsBepalenBij  smallint;
  declare @AbrKostPrijs            numeric(15,3);
  declare @AbrPrijsBepalenBij      smallint;
  declare @AbrPrijs                numeric(15,3);
  declare @AbrKorting1BepalenBij   smallint;
  declare @AbrIsKortingsPercentage smallint;
  declare @AbrKorting1             numeric(15,3);
  declare @AbrKorting2BepalenBij   smallint;
  declare @AbrKorting2             numeric(15,3);
  declare @ArtGid                  integer;
  declare @ArtOpbrGrpGid           integer;
  declare @ArtKostprijsEx          numeric(15,3);
  declare @ArtAantDecAantallen     smallint;
  declare @ArtAantDecPrijzen       smallint;
  declare @ArtAantallen            smallint;
  declare @ArtKostprijsWijzigen    smallint;
  declare @ArtVerkprijs            numeric(15,3);
  declare @ArtPartijGid            integer;
  declare @ArtPartijIsVerplicht    smallint;
  declare @VkeGid                  integer;
  declare @NawGid                  integer;
  declare @DebGrpGid               integer;
  declare @BasisValNummer          numeric(3,0);
  declare @BasisValCode            nchar(3);
  declare @PraVerkoopPrijs         numeric(15,3);
  declare @PraKortingsoort         smallint;
  declare @PraKortingsPerc         numeric(6,2);
  declare @PraKortingsBedrag       numeric(15,3);
  declare @PrijzenPer              smallint;
  declare @_GeprijsdPer integer = 1;

  //call TraceBegin('WebSvcProc_Abonnementen_Abonnementsregel_Toevoegen > @AbonnementCode = ' + @AbonnementCode + ', @VersieNummer = ' + string(@VersieNummer));

  if IsModuleActive('aa') = 0 then   // Module t.b.v. abonnementen
    call Raise(20790,_U('Optie Abonnementen')  ); // '(20790) '%1!' niet geactiveerd!'
  end if;

  if not ((@Kostprijs >= 0) and (@Kostprijs <= 9999999999.999)) then
    call Raise(20700, 'Kostprijs')
  end if;

  begin atomic
    // AbonnementKop
    // Ophalen AbonnenmentKop gegevens
    select AboGid,
           AboNawGidDebiteur
    into   @AboGid,
           @AboNawGidDebiteur
    from   tabAbonnementKop
    where  AboCode = @AbonnementCode;

    // Controle: AbonnementCode is altijd verplicht
    if @AboGid is null then
      call Raise(20700,'AbonnementCode');   // (20700) Ongeldige waarde: %1!
    end if;

    // Gevonden abonnement locken
    begin
      declare @LockResult integer;
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid, @LockResult, 0);
      if @LockResult <> 0 /*Lock gelukt*/ then
        call Raise(20741,_U('Abonnement'));   // (20741) %1! is in gebruik!
      end if;
    end;

    // AbonnementVersie
    // Ophalen AbonnenmentVersie gegevens
    select AbvGid,
           AbvIsInkoopcombinatie,
           AbvNawGidPrijzen,
           AbvBtwStand,
           AbvValNummer,
           AbvTaalGid
    into   @AbvGid,
           @AbvIsInkoopcombinatie,
           @AbvNawGidPrijzen,
           @AbvBtwStand,
           @AbvValNummer,
           @AbvTaalGid
    from   tabAbonnementVersie
    where  AbvAboGid = @AboGid
    and    AbvNummer = @VersieNummer;

    // Controle: VersieNummer is altijd verplicht
    if @AbvGid is null then
      call Raise(20700,'VersieNummer');   // (20700) Ongeldige waarde: %1!
    end if;

    // AbonnementRegel
    // Controle: Heeft het AbonnementVersie al een AbonnementRegel, zo nee, dan altijd 1
    if not exists (select first abrGid from tabAbonnementRegel where abrAbvGid = @AbvGid) then
      set @AbrRegelNr = 1;
    else
      // Er is minimaal één AbonnementRegel aanwezig, dan hoogste regelnummer ophalen en 1 bij optellen
      select first (abrRegelNr + 1) into @AbrRegelNr from tabAbonnementRegel where abrAbvGid = @AbvGid order by abrRegelNr desc;
    end if;

    // Controle: Is er sprake van een Inkoopcombinatie?
    if @AbvIsInkoopcombinatie = 0 then
      // Nee, neem dan het NawGid over van de orderdebiteur
      set @NawGid = @AboNawGidDebiteur
    else
      // Ja, neem dan het NawGid over van de Inkoopcombinatie debiteur prijzen
      set @NawGid = @AbvNawGidPrijzen
    end if;

    // Ophalen van de debiteurgroep, basis Valutanummer en Valutacode t.b.v. ophalen prijsafspraken
    select NawFilDebGrpGid into @DebGrpGid from tabNawFile where NawFilNawGid = @NawGid;
    select ValNummer,ValCode into @BasisValNummer,@BasisValCode from tabValuta where IsBasisValuta = 1;

    // Controle: Er moet een geldige waarde in RegelSoort worden meegegeven
    case @RegelSoort
      when 'TEKST' then set @AbrRegelsoort = 0;
      when 'TAR' then set @AbrRegelsoort = 1;
      when 'ART' then set @AbrRegelsoort = 2;
    else
      call Raise(20700,'RegelSoort');   // (20700) Ongeldige waarde: %1!
    end case;

    // Controle: Er moet een bestaande ArtikelNummer worden meegegeven, indien RegelSoort = 'TAR' (1) of 'ART' (2)
    // Als ArtikelNummer wordt meegegeven en RegelSoort = 'TEKST' (0), dan moet het ook een bestaande Tekstblok zijn
    if isnull(@ArtikelNummer,'') <> '' or @AbrRegelsoort in (1,2) then
      select    ArtGid,
                ArtOpbrGrpGid,
                ArtKostprijsEx,
                ArtAantDecAantallen,
                ArtAantDecPrijzen,
                ArtAantallen,
                ArtVerkprijs,
                ArtIsPartijNrBijLeverenVerplicht,
                ArtIsKostprijsWijzigenInOrder,
                VkeGid,
                ArtPrijsPer
      into      @ArtGid,
                @ArtOpbrGrpGid,
                @ArtKostprijsEx,
                @ArtAantDecAantallen,
                @ArtAantDecPrijzen,
                @ArtAantallen,
                @ArtVerkprijs,
                @ArtPartijIsVerplicht,
                @ArtKostprijsWijzigen,
                @VkeGid,
                @_GeprijsdPer
      from      tabArtikel
      left join tabVerkoopeenheid on VkeArtGid = ArtGid and VkeIsVoorraadeenheid = 1
      where     ArtSoort = @AbrRegelsoort
      and       Artcode = @ArtikelNummer;

      if @ArtGid is null then
        call Raise(20700,'ArtikelNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: PartijNummer moet altijd meegegeven worden voor regelsoort artikel regel waarbij partije verplicht is.
    if (@AbrRegelsoort = 2) and (@ArtPartijIsVerplicht = 1) and (isnull(@PartijNummer,'') = '') then
      call Raise(20526); //Ongeldige of geen PartijNummer meegegeven!
    else
      // Controle: Indien PartijNummer wordt meegegeven, dan moet dit een bestaande Partijnummer zijn
      if isnull(@PartijNummer,'') <> '' then
        select ArtPartijGid
        into   @ArtPartijGid
        from   tabArtikelPartij
        where  ArtPartijArtGid = @ArtGid
        and    ArtPartijNummer = @PartijNummer;

        if @ArtPartijGid is null then
          call Raise(20700,'Partijnummer');   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
    end if;

    // Controle: Indien Aantallen in Artikel/Tarief van toepassing is, dan moet een Aantal ongelijk aan 0 worden meegegeven
    if @AbrRegelsoort <> 0 then     // Artikel (2) of Tarief (1)
      if @ArtAantallen = 1 then     // Aantallen in Artikel/Tarief is van toepassing.
        if isnull(@Aantal,0) = 0 then
          call Raise(20700,'Aantal');   // (20700) Ongeldige waarde: %1!
        else
          // Controle: Er mag geen waarde in decimalen voorkomen, dan in het Artikel/Tarief van toepassing is.
          if (truncnum(@Aantal,@ArtAantDecAantallen) <> @Aantal) then
            call Raise(20700,_U('Teveel decimalen in %1! meegegeven!', 'Aantal'));   // (20700) Ongeldige waarde: %1!
          end if;
        end if;
      end if;
    end if;

    // Controle: Er moet een bestaande BtwCode worden meegegeven
    if @AbrRegelsoort <> 0 then     // Artikel (2) of Tarief (1)
      select BtwCode into @AbrBtwCode from tabBtw where BtwCode = @BtwCode;
      if @AbrBtwCode is null then
        call Raise(20700,'BtwCode');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Indien geen KostprijsOpnieuwBepalenBij is meegegeven, dan default ophalen uit Vaste gegevens
    if isnull(@KostprijsOpnieuwBepalenBij,'') = '' then
      set @AbrKostprijsBepalenBij = (select isnull(AbvgDefKostprijsBepalenBij,1) from tabAbonnementVasteGegevens);
    else
      // Controle: Indien KostprijsOpnieuwBepalenBij is meegegeven, dan moet dit een geldige waarde zijn
      case @KostprijsOpnieuwBepalenBij
        when 'NIET' then set @AbrKostprijsBepalenBij = 0
        when 'CONTRACTPER' then set @AbrKostprijsBepalenBij = 1
        when 'FACTFREQ' then set @AbrKostprijsBepalenBij = 2
      else
        call Raise(20700,'KostprijsOpnieuwBepalenBij');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Neem de huidige kostprijs van het Artikel/Tarief over
    set @AbrKostPrijs = @ArtKostprijsEx;
    if (@AbrKostprijsBepalenBij = 0) and (@ArtKostprijsWijzigen = 1) then       //niet automatisch en wel kan wijzigen
      set @AbrKostPrijs = isnull(@Kostprijs, @ArtKostprijsEx);                  //bug:54561
    end if;

    // Haal actuele prijsafspraak op
    call BepaalPrijsAfspraak(@NawGid, @ArtGid, @VkeGid, @ArtOpbrGrpGid, @DebGrpGid, @ArtPartijGid, @AbvBtwStand, @AbvValNummer, @Aantal, @Aantal, @BasisValNummer, @BasisValCode, now(),                // IN parameters
                             null, null, null, null, @PraVerkoopPrijs, @PraKortingSoort, @PraKortingsPerc, @PraKortingsBedrag, null, null, @PrijzenPer);   // OUT parameters

    // Controle: Indien geen PrijsOpnieuwBepalenBij is meegegeven, dan default ophalen uit Vaste gegevens
    if isnull(@PrijsOpnieuwBepalenBij,'') = '' then
      set @AbrPrijsBepalenBij = (select isnull(AbvgDefPrijsBepalenBij,1) from tabAbonnementVasteGegevens);
    else
      // Controle: Indien PrijsOpnieuwBepalenBij is meegegeven, dan moet dit een geldige waarde zijn
      case @PrijsOpnieuwBepalenBij
        when 'NIET' then set @AbrPrijsBepalenBij = 0
        when 'CONTRACTPER' then set @AbrPrijsBepalenBij = 1
        when 'FACTFREQ' then set @AbrPrijsBepalenBij = 2
      else
        call Raise(20700,'PrijsOpnieuwBepalenBij');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: Indien PrijsOpnieuwBepalenBij = NIET (0), dan meegegeven BrutoVerkoopprijs toepassen
    if @AbrPrijsBepalenBij = 0 then
      set @AbrPrijs = isnull(@BrutoVerkoopprijs,@ArtVerkprijs);     // Geen verkooprijs meegegeven, dan Default verkoopprijs van Tarief/Artikel
      // Controle: Er mag geen waarde in decimalen voorkomen, dan in het Artikel/Tarief van toepassing is.
      if (@AbrPrijs <> truncnum(@AbrPrijs,@ArtAantDecPrijzen)) then
         call Raise(20700,_U('Teveel decimalen in %1! meegegeven!', 'BrutoVerkoopprijs'));   // (20700) Ongeldige waarde: %1!
      end if;
    else
      // Controle: Indien PrijsOpnieuwBepalenBij <> NIET, dan Verkoopprijs uit Prijsafspraken toepassen
      set @AbrPrijs = isnull(@PraVerkoopPrijs,0);
    end if;

    // Controle: Indien geen Korting1OpnieuwBepalenBij is meegegeven, dan default ophalen uit Vaste gegevens
    if isnull(@Korting1OpnieuwBepalenBij,'') = '' then
      set @AbrKorting1BepalenBij = (select isnull(AbvgDefKorting1BepalenBij,1) from tabAbonnementVasteGegevens);
    else
      // Controle: Indien Korting1OpnieuwBepalenBij is meegegeven, dan moet dit een geldige waarde zijn
      case @Korting1OpnieuwBepalenBij
        when 'NIET' then set @AbrKorting1BepalenBij = 0
        when 'CONTRACTPER' then set @AbrKorting1BepalenBij = 1
        when 'FACTFREQ' then set @AbrKorting1BepalenBij = 2
      else
        call Raise(20700,'Korting1OpnieuwBepalenBij');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: Indien Korting1OpnieuwBepalenBij = NIET (0), dan meegegeven Korting1 toepassen
    if @AbrKorting1BepalenBij = 0 then
      set @AbrIsKortingsPercentage = isnull(@Korting1IsPercentage,1);   // 0 = Kortingsbedrag, 1 = Kortingspercentage (Default)
      if @AbrIsKortingsPercentage = 1 then   // Kortingspercentage
        // Controle: Korting1 (percentage) mag niet kleiner zijn dan -100 en niet groter zijn dan 100
        if (isnull(@Korting1,0) < -100 or isnull(@Korting1,0) > 100) then
          call Raise(20700,_U('%1! (percentage) moet tussen %2! en %3! liggen!', _U('Korting1'), '-100', '100'));   // (20700) Ongeldige waarde: %1!
        else
          set @AbrKorting1 = isnull(@Korting1,0);
          // Controle: In een Kortingspercentage mogen maximaal 2 decimalen worden meegegeven
          if (@AbrKorting1 <> truncnum(@AbrKorting1,2)) then
            call Raise(20700,_U('Teveel decimalen in %1! (percentage) meegegeven!', _U('Korting1')));   // (20700) Ongeldige waarde: %1!
          end if;
        end if;
      else   // Kortingbedrag
        set @AbrKorting1 = isnull(@Korting1,0);
        if (@AbrKorting1 - truncnum(@AbrKorting1,@ArtAantDecPrijzen)) <> 0 then
          call Raise(20700,_U('Teveel decimalen in %1! (bedrag) meegegeven!', _U('Korting1')));   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
    else
      set @AbrIsKortingsPercentage = isnull(@PraKortingSoort,1);
      // Controle: Indien Korting1OpnieuwBepalenBij <> NIET (0), dan Korting1 uit Prijsafspraken toepassen
      if @AbrIsKortingsPercentage = 1 then
        set @AbrKorting1 = isnull(@PraKortingsPerc,0);
      else
        set @AbrKorting1 = isnull(@PraKortingsBedrag,0);
      end if;
    end if;

    // Controle: Indien geen Korting2OpnieuwBepalenBij is meegegeven, dan default ophalen uit Vaste gegevens
    if isnull(@Korting2OpnieuwBepalenBij,'') = '' then
      set @AbrKorting2BepalenBij = (select isnull(AbvgDefKorting2BepalenBij,1) from tabAbonnementVasteGegevens);
    else
      // Controle: Indien Korting2OpnieuwBepalenBij is meegegeven, dan moet dit een geldige waarde zijn
      case @Korting2OpnieuwBepalenBij
        when 'NIET' then set @AbrKorting2BepalenBij = 0
        when 'CONTRACTPER' then set @AbrKorting2BepalenBij = 1
        when 'FACTFREQ' then set @AbrKorting2BepalenBij = 2
      else
        call Raise(20700,'Korting2OpnieuwBepalenBij');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: Indien Korting2OpnieuwBepalenBij = NIET (0), dan meegegeven Korting2 toepassen
    if @AbrKorting2BepalenBij = 0 then
      // Controle: Korting2 (percentage) mag niet kleiner zijn dan -100 en niet groter zijn dan 100
      if (isnull(@Korting2,0) < -100 or isnull(@Korting2,0) > 100) then
        call Raise(20700, _U('%1! (percentage) moet tussen %2! en %3! liggen!', 'Korting2', '-100', '100'));   // (20700) Ongeldige waarde: %1!
      else
        set @AbrKorting2 = isnull(@Korting2,0);
        // Controle: In een Kortingspercentage mogen maximaal 2 decimalen worden meegegeven
        if (@AbrKorting2 <> truncnum(@AbrKorting2, 2)) then
          call Raise(20700, _U('Teveel decimalen in %1! (percentage) meegegeven!', 'Korting2'));   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
    else
      set @AbrKorting2 = 0;
    end if;

    // Controle: Indien geen TekstOpOrder is meegegeven, haal dan de TekstOpFactuur van het Tekstblok/Tarief/Artikel op
    if isnull(@TekstOpOrder,'') = '' then
      set @TekstOpOrder = isnull((select ArtTekst from tabArtikelTeksten where ArtTekstArtGid = @ArtGid and ArtTaalGid = @AbvTaalGid),'');
    end if;

    //Als het om een tekstregel gaat de volgende velden "leeghalen"
    if @AbrRegelsoort = 0 then
      set @AbrBtwCode           = null;
      set @ArtAantDecAantallen  = 0;
      set @ArtAantDecPrijzen    = 0;
      set @AbrKostprijs         = 0;
      set @Aantal               = 0;
      set @PrijzenPer           = 0;
    end if;

    // Nieuwe abonnementregel toevoegen in de database
    insert into tabAbonnementRegel
           (    abrAbvGid,
                abrArtGid,
                abrArtPartijGid,
                abrBtwCode,
                abrAantalDecimalenVoorAantallen,
                abrAantalDecimalenVoorPrijzen,
                abrAantalOpOrder,
                abrIsKortingsPercentage,
                abrKorting1,
                abrKorting2,
                abrKostprijs,
                abrPrijs,
                abrRegelNr,
                abrRegelSoort,
                abrTekstOpOrder,
                abrVolgartikelFactor,
                abrPrijsBepalenBij,
                abrKostprijsBepalenBij,
                abrKorting1BepalenBij,
                abrKorting2BepalenBij,
                abrPrijsPer
           )
           values
           (    @AbvGid,
                @ArtGid,
                @ArtPartijGid,
                @AbrBtwCode,
                @ArtAantDecAantallen,
                @ArtAantDecPrijzen,
                @Aantal,
                @AbrIsKortingsPercentage,
                @AbrKorting1,
                @AbrKorting2,
                @AbrKostprijs,
                @AbrPrijs,
                @AbrRegelNr,
                @AbrRegelSoort,
                @TekstOpOrder,
                0,
                @AbrPrijsBepalenBij,
                @AbrKostprijsBepalenBij,
                @AbrKorting1BepalenBij,
                @AbrKorting2BepalenBij,
                @_GeprijsdPer
           );

    // Unlock abonnement
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid);
  end;   // atomic

  // Resultaat teruggeven
  select @AbrRegelNr as RegelNr;

  // call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Abonnementen_Abonnementsregel_Verwijderen
(  in @AbonnementCode nchar(20),
   in @VersieNummer smallint,
   in @RegelNr smallint)

begin atomic
  declare @AboGid                                       integer;
  declare @AbvGid                                       integer;
  declare @AbrGid                                       integer;
  declare @AbrRegelNr                                   smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Abonnementen_Abonnementsregel_Verwijderen > ';
  // call TraceBegin('WebSvcProc_Abonnementen_Abonnementsregel_Verwijderen > @AbonnementCode = ' + @AbonnementCode + ', @VersieNummer = ' + string(@VersieNummer) + ', @RegelNr = ' + string(@RegelNr));

  if IsModuleActive('aa') = 0 then   // Module t.b.v. abonnementen
    call Raise(20790,_U('Optie Abonnementen'));   // '(20790) '%1!' niet geactiveerd!';
  end if;       // Einde if IsModuleActive('aa') <> 0

  // AbonnementKop
  // Ophalen AbonnenmentKop gegevens
  select AboGid
  into   @AboGid
  from   tabAbonnementKop
  where AboCode = @AbonnementCode;

  // Controle: AbonnementCode is altijd verplicht
  if @AboGid is null then
    call Raise(20700,'AbonnementCode');   // (20700) Ongeldige waarde: %1!
  end if;

  // Gevonden abonnement locken
  begin
    declare @LockResult integer;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid, @LockResult, 0);
    if @LockResult <> 0 /*Lock gelukt*/ then
      call Raise(20741,_U('Abonnement'));   // (20741) %1! is in gebruik!
    end if;
  end;

  // AbonnementVersie
  // Ophalen AbonnenmentVersie gegevens
  select AbvGid
  into   @AbvGid
  from   tabAbonnementVersie
  where  AbvAboGid = @AboGid
  and    AbvNummer = @VersieNummer;

  // Controle: VersieNummer is altijd verplicht
  if @AbvGid is null then
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid);
    call Raise(20700,'VersieNummer');   // (20700) Ongeldige waarde: %1!
  end if;

  // AbonnementRegel
  // Ophalen AbonnenmentRegel gegevens
  select abrGid
  into   @AbrGid
  from   tabAbonnementRegel
  where  abrAbvGid = @AbvGid
  and    abrRegelNr = @RegelNr;

  // Controle: RegelNr is altijd verplicht
  if @AbrGid is null then
    call Raise(20700,'RegelNr');   // (20700) Ongeldige waarde: %1!
  end if;

  // Geselecteerde AbonnementRegel verwijderen uit de database
  delete from tabAbonnementRegel
  where       abrGid = @AbrGid;

  // Unlock abonnement na verwijderen
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid);

  set @@ErrorTextProcedure = 'WebSvcProc_Abonnementen_Abonnementsregel_Verwijderen';
  // call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Abonnementen_Abonnementsregel_Wijzigen
(  in @AbonnementCode             nchar(20),
   in @VersieNummer               smallint,
   in @RegelNr                    smallint,
   in @PartijNummer               nchar(20),
   in @Aantal                     numeric(15,3),
   in @BtwCode                    integer,
   in @KostprijsOpnieuwBepalenBij nchar(15),
   in @Kostprijs                  numeric(15,3),
   in @BrutoVerkoopprijs          numeric(15,3),
   in @PrijsOpnieuwBepalenBij     nchar(15),
   in @Korting1IsPercentage       smallint,
   in @Korting1                   numeric(15,3),
   in @Korting1OpnieuwBepalenBij  nchar(15),
   in @Korting2                   numeric(15,3),
   in @Korting2OpnieuwBepalenBij  nchar(15),
   in @TekstOpOrder               long nvarchar)

begin atomic
  declare @AboGid                  integer;
  declare @AboNawGidDebiteur       integer;
  declare @AbvGid                  integer;
  declare @AbvIsInkoopcombinatie   smallint;
  declare @AbvNawGidPrijzen        integer;
  declare @AbvValNummer            numeric(3,0);
  declare @AbvBtwStand             smallint;
  declare @AbvTaalGid              integer;
  declare @AbrGid                  integer;
  declare @AbrRegelNr              smallint;
  declare @AbrRegelsoort           smallint;
  declare @AbrAantalOpOrder        numeric(15,3);
  declare @AbrBtwCode              integer;
  declare @AbrKostprijsBepalenBij  smallint;
  declare @AbrPrijsBepalenBij      smallint;
  declare @AbrPrijs                numeric(15,3);
  declare @AbrKorting1BepalenBij   smallint;
  declare @AbrIsKortingsPercentage smallint;
  declare @AbrKorting1             numeric(15,3);
  declare @AbrKorting2BepalenBij   smallint;
  declare @ArtGid                  integer;
  declare @ArtAantallen            smallint;
  declare @ArtAantDecAantallen     smallint;
  declare @ArtAantDecPrijzen       smallint;
  declare @ArtPartijGid            integer;
  declare @ArtPartijIsVerplicht    smallint;
  declare @ArtKostprijsWijzigen    smallint;
  declare @AbrKostprijs            numeric(15,3);
  declare @ArtKostprijsEx          numeric(15,3);

  // call TraceBegin('WebSvcProc_Abonnementen_Abonnementsregel_Wijzigen > @AbonnementCode = ' + @AbonnementCode + ', @VersieNummer = ' + string(@VersieNummer) + ', @RegelNr = ' + string(@RegelNr));

  if IsModuleActive('aa') = 0 then   // Module t.b.v. abonnementen
    call Raise(20790,_U('Optie Abonnementen'));   // '(20790) '%1!' niet geactiveerd!';
  end if;

  if not ((@Kostprijs >= 0) and (@Kostprijs <= 9999999999.999)) then
    call Raise(20700,'Kostprijs');   // (20700) Ongeldige waarde: %1!
  end if;

  // AbonnementKop
  // Ophalen AbonnenmentKop gegevens
  select AboGid,
         AboNawGidDebiteur
  into   @AboGid,
         @AboNawGidDebiteur
  from   tabAbonnementKop
  where  AboCode = @AbonnementCode;

  // Controle: AbonnementCode is altijd verplicht
  if @AboGid is null then
    call Raise(20700,'AbonnementCode');   // (20700) Ongeldige waarde: %1!
  end if;

  // Gevonden abonnement locken
  begin
    declare @LockResult integer;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid, @LockResult, 0);
    if @LockResult <> 0 /*Lock gelukt*/ then
      call Raise(20741, _U('Abonnement'));   // (20741) %1! is in gebruik!
    end if;
  end;

  // AbonnementVersie
  // Ophalen AbonnenmentVersie gegevens
  select AbvGid,
         AbvIsInkoopcombinatie,
         AbvNawGidPrijzen,
         AbvBtwStand,
         AbvValNummer,
         AbvTaalGid
  into   @AbvGid,
         @AbvIsInkoopcombinatie,
         @AbvNawGidPrijzen,
         @AbvBtwStand,
         @AbvValNummer,
         @AbvTaalGid
  from   tabAbonnementVersie
  where  AbvAboGid = @AboGid
  and    AbvNummer = @VersieNummer;

  // Controle: VersieNummer is altijd verplicht
  if @AbvGid is null then
    call Raise(20700,'VersieNummer');   // (20700) Ongeldige waarde: %1!
  end if;

  // AbonnementRegel
  // Ophalen AbonnementRegel gegevens
  select abrGid,
         abrRegelNr,
         abrArtGid,
         abrRegelsoort,
         abrAantalOpOrder,
         abrKostprijsBepalenBij,
         abrPrijsBepalenBij,
         abrIsKortingsPercentage,
         abrKorting1BepalenBij,
         abrKorting2BepalenBij,
         ArtAantallen,
         ArtAantDecAantallen,
         ArtAantDecPrijzen,
         ArtIsPartijNrBijLeverenVerplicht,
         ArtIsKostprijsWijzigenInOrder,
         ArtKostprijsEx
  into   @AbrGid,
         @AbrRegelNr,
         @ArtGid,
         @AbrRegelsoort,
         @AbrAantalOpOrder,
         @AbrKostprijsBepalenBij,
         @AbrPrijsBepalenBij,
         @AbrIsKortingsPercentage,
         @AbrKorting1BepalenBij,
         @AbrKorting2BepalenBij,
         @ArtAantallen,
         @ArtAantDecAantallen,
         @ArtAantDecPrijzen,
         @ArtPartijIsVerplicht,
         @ArtKostprijsWijzigen,
         @ArtKostPrijsEx
  from   tabAbonnementRegel
  left outer join tabartikel on ArtGid = abrArtGid
  where  abrAbvGid = @AbvGid
  and    abrRegelNr = @RegelNr;
  if @AbrGid is null then
    call Raise(20700,'RegelNr');   // (20700) Ongeldige waarde: %1!
  end if;

  // Controle: Indien PartijNummer wordt meegegeven, dan moet dit een bestaande Partijnummer zijn
  if @PartijNummer is not null then
    if (@PartijNummer = '') and (@ArtPartijIsVerplicht = 0) then
        set @ArtPartijGid = null;
    else
      select ArtPartijGid
      into   @ArtPartijGid
      from   tabArtikelPartij
      where  ArtPartijArtGid = @ArtGid
      and    ArtPartijNummer = @PartijNummer;

      if @ArtPartijGid is null then
        call Raise(20700,'Partijnummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;
  end if;

  // Controle: Indien Aantal is meegegeven, dan Aantal op voorwaarde wijzigen
  if isnull(@Aantal,0) <> 0 then
    // Controle: Aantal is alleen van toepassing voor Tarief (1) of Artikel (2)
    if @AbrRegelsoort <> 0 then
      // Controle: Tarief/Artikel zijn aantallen van toepassing
      if @ArtAantallen = 1 then
        set @AbrAantalOpOrder = @Aantal;
        // Controle: Er mag geen waarde in decimalen voorkomen, dan in het Artikel/Tarief van toepassing is
        if (truncnum(@AbrAantalOpOrder,@ArtAantDecAantallen) <> @AbrAantalOpOrder) then
          call Raise(20700,_U('Teveel decimalen in %1! meegegeven!', 'Aantal'));   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
    end if;
  end if;

  // Controle: Indien BtwCode is meegegeven, dan moet dit een bestaande BtwCode zijn
  if @BtwCode is not null then
    select BtwCode into @AbrBtwCode from tabBtw where BtwCode = @BtwCode;

    if @AbrBtwCode is null then
      call Raise(20700,'BtwCode');   // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  // Controle: Indien KostprijsOpnieuwBepalenBij is meegegeven, dan moet dit een geldige waarde zijn
  if isnull(@KostprijsOpnieuwBepalenBij,'') <> '' then
    case @KostprijsOpnieuwBepalenBij
      when 'NIET' then set @AbrKostprijsBepalenBij = 0
      when 'CONTRACTPER' then set @AbrKostprijsBepalenBij = 1
      when 'FACTFREQ' then set @AbrKostprijsBepalenBij = 2
    else
      call Raise(20700,'KostprijsOpnieuwBepalenBij');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

    // Neem de huidige kostprijs van het Artikel/Tarief over
    set @AbrKostPrijs = @ArtKostprijsEx;
    if (@AbrKostprijsBepalenBij = 0) and (@ArtKostprijsWijzigen = 1) then       //niet automatisch en wel kan wijzigen
      set @AbrKostPrijs = isnull(@Kostprijs, @ArtKostprijsEx);                  //bug:54561
    end if;

  // Controle: Indien PrijsOpnieuwBepalenBij is meegegeven, dan moet dit een geldige waarde zijn
  if isnull(@PrijsOpnieuwBepalenBij,'') <> '' then
    case @PrijsOpnieuwBepalenBij
      when 'NIET' then set @AbrPrijsBepalenBij = 0
      when 'CONTRACTPER' then set @AbrPrijsBepalenBij = 1
      when 'FACTFREQ' then set @AbrPrijsBepalenBij = 2
    else
      call Raise(20700,'PrijsOpnieuwBepalenBij');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  // Controle: Indien BrutoVerkoopprijs is meegegeven, dan alleen wijzigen indien PrijsOpnieuwBepalenBij = 'NIET' (0), anders negeren
  if @AbrPrijsBepalenBij = 0 and @BrutoVerkoopprijs is not null then
    set @AbrPrijs = @BrutoVerkoopprijs;
    // Controle: Er mag geen waarde in decimalen voorkomen, dan in het Artikel/Tarief van toepassing is.
    if (@AbrPrijs <> truncnum(@AbrPrijs,@ArtAantDecPrijzen)) then
       call Raise(20700,_U('Teveel decimalen in %1! meegegeven!', 'BrutoVerkoopprijs'));   // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  // Controle: Indien Korting1OpnieuwBepalenBij is meegegeven, dan moet dit een geldige waarde zijn
  if isnull(@Korting1OpnieuwBepalenBij,'') <> '' then
    case @Korting1OpnieuwBepalenBij
      when 'NIET' then set @AbrKorting1BepalenBij = 0
      when 'CONTRACTPER' then set @AbrKorting1BepalenBij = 1
      when 'FACTFREQ' then set @AbrKorting1BepalenBij = 2
    else
      call Raise(20700,'Korting1OpnieuwBepalenBij');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  // Controle: Indien Korting1 is meegegeven, dan onder voorwaarde wijzigen
  if @Korting1 is not null then
    // Controle: Indien Korting1OpnieuwBepalenBij is gelijk aan 'NIET' (0), dan mag Korting1 worden gewijzigd, anders negeren
    if @AbrKorting1BepalenBij = 0 then
      // Controle: Indien Korting1IsPercentage is meegegeven, dan moet dit een geldige waarde zijn
      if @Korting1IsPercentage is not null then
        if @Korting1IsPercentage in (0,1) then
          set @AbrIsKortingsPercentage = @Korting1IsPercentage;
        else
          call Raise(20700,'Korting1IsPercentage');   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
      if @AbrIsKortingsPercentage = 1 then   // Korting is percentage
        // Controle: Korting1 (percentage) mag niet kleiner zijn dan -100 en niet groter zijn dan 100
        if @Korting1 < -100 or @Korting1 > 100 then
          call Raise(20700,_U('%1! (percentage) moet tussen %2! en %3! liggen!', 'Korting1', '-100', '100'));   // (20700) Ongeldige waarde: %1!
        else
          set @AbrKorting1 = @Korting1;
          // Controle: In een Kortingspercentage mogen maximaal 2 decimalen worden meegegeven
          if (@AbrKorting1 <> truncnum(@AbrKorting1,2)) then
            call Raise(20700,_U('Teveel decimalen in %1! (percentage) meegegeven!', 'Korting1'));   // (20700) Ongeldige waarde: %1!
          end if;
        end if;
      else   // Korting is bedrag
        set @AbrKorting1 = @Korting1;
        // Controle: Er mag geen waarde in decimalen voorkomen, dan in het Artikel/Tarief van toepassing is.
        if (@AbrKorting1 <> truncnum(@AbrKorting1,@ArtAantDecPrijzen)) then
          call Raise(20700,_U('Teveel decimalen in %1! (bedrag) meegegeven!', 'Korting1'));   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
    end if;
  end if;

  // Controle: Indien Korting2OpnieuwBepalenBij is meegegeven, dan moet dit een geldige waarde zijn
  if isnull(@Korting2OpnieuwBepalenBij,'') <> '' then
    case @Korting2OpnieuwBepalenBij
      when 'NIET'         then set @AbrKorting2BepalenBij = 0
      when 'CONTRACTPER'  then set @AbrKorting2BepalenBij = 1
      when 'FACTFREQ'     then set @AbrKorting2BepalenBij = 2
    else
      call Raise(20700,'Korting2OpnieuwBepalenBij');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  // Controle: Indien Korting2 is meegegeven, dan onder voorwaarde wijzigen
  if @Korting2 is not null then
    // Controle: Indien Korting2OpnieuwBepalenBij is gelijk aan 'NIET' (0), dan mag Korting2 worden gewijzigd, anders negeren
    if @AbrKorting2BepalenBij = 0 then
      // Controle: Korting2 (percentage) mag niet kleiner zijn dan -100 en niet groter zijn dan 100
      if @Korting2 < -100 or @Korting2 > 100 then
        call Raise(20700,_U('%1! (percentage) moet tussen %2! en %3! liggen!', 'Korting2', '-100', '100'));   // (20700) Ongeldige waarde: %1!
      else
        // Controle: In een Kortingspercentage mogen maximaal 2 decimalen worden meegegeven
        if (@Korting2 <> truncnum(@Korting2,2)) then
          call Raise(20700,_U('Teveel decimalen in %1! (percentage) meegegeven!', 'Korting2'));   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
    end if;
  end if;

  // Wijzigingen bijwerken in de database
  update tabAbonnementRegel
  set    abrArtPartijGid         = @ArtPartijGid,
         abrAantalOpOrder        = isnull(@AbrAantalOpOrder,abrAantalOpOrder),
         abrBtwCode              = isnull(@AbrBtwCode,abrBtwCode),
         abrKostprijs            = isnull(@AbrKostprijs,abrKostprijs),
         abrKostprijsBepalenBij  = isnull(@AbrKostprijsBepalenBij,abrKostprijsBepalenBij),
         abrPrijs                = isnull(@AbrPrijs,abrPrijs),
         abrPrijsBepalenBij      = isnull(@AbrPrijsBepalenBij,abrPrijsBepalenBij),
         abrKorting1             = isnull(@AbrKorting1,abrKorting1),
         abrIsKortingsPercentage = isnull(@AbrIsKortingsPercentage,abrIsKortingsPercentage),
         abrKorting1BepalenBij   = isnull(@AbrKorting1BepalenBij,abrKorting1BepalenBij),
         abrKorting2             = isnull(@Korting2,abrKorting2),
         abrKorting2BepalenBij   = isnull(@AbrKorting2BepalenBij,abrKorting2BepalenBij),
         abrTekstOpOrder         = isnull(@TekstOpOrder,abrTekstOpOrder)
  where  abrGid = @AbrGid;

  // Unlock abonnement na update
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid);

  // call TraceEind('WebSvcProc_Abonnementen_Abonnementsregel_Wijzigen');
end;



create or replace procedure WebSvcProc_Abonnementen_Onderhoud_VrijeRubriek_LockVrijgeven()
begin
end;


create or replace procedure WebSvcProc_Abonnementen_Onderhoud_VrijeRubriek_ToevoegenWijzigen(
  in @Omschrijving nchar(40),
  in @Type nchar(15),   /* Geldige waardes: null (bij wijzigen), 'tekst', 'getal', 'datum', 'tijd', 'selectievakje', 'keuzelijst', 'email', 'website', 'bestand', 'telefoon'*/
  in @Hint nchar(80),
  in @Verplicht nchar(3), /* 'JA', 'NEE' */
  in @Uniek nchar(3), /* 'JA', 'NEE' */
  in @Lengte numeric(3,0),
  in @Decimalen numeric(1,0), /* >= 0 en <= 5 */
  in @Keuzelijst long varchar, //Delimited met CrLf (/0x0d/0x0a) OF '|'
  in @Defaultwaarde nchar(250), //Bevat default voor elk type veld!. Bij datum/tijd: nu/now levert datum/tijd van server
  in @DefaultDatum nchar(16), //Eigendatum, Verwerkingsdatum, Systeemdatum
  in @DefaultTijd nchar(11), //EigenTijd, SysteemTijd
  in @Sjabloon nchar(250), //Bevat sjabloon voor elk type dat een sjabloon kan hebben
  in @Groep nchar(40),
  in @OpVerkoopDocument nchar(3) /* 'JA', 'NEE' */
)
begin
  //call trace('Begin WebSvcProc_Abonnementen_Onderhoud_VrijeRubriek_ToevoegenWijzigen')

  if IsModuleActive('aa') = 0 then // Module t.b.v. abonnementen
    call Raise(20790, _U('Abonnementen')); // '(20790) '%1!' niet geactiveerd!';
  end if;

  call WebSvcHulpProc_VrijeRubriek_ToevoegenWijzigen(
    'ABO', //@VrBestandOms
    0, //@VrGroepID
    0, //@VrSubGroepId
    @Omschrijving,
    @Type,
    @Hint,
    @Verplicht,
    @Uniek,
    @Lengte,
    @Decimalen,
    @Keuzelijst,
    @Defaultwaarde,
    @Sjabloon,
    @Groep,
    @DefaultDatum,
    @DefaultTijd,
    @OpVerkoopDocument
  );

  //call trace('Einde WebSvcProc_Abonnementen_Onderhoud_VrijeRubriek_ToevoegenWijzigen');
end;

