create or replace procedure WebSvcProc_Abonnementen_ToevoegenWijzigen
( in @AbonnementCode               nchar(20),
  in @AbonnementOms                nchar(40),
  in @DebiteurNummer               nchar(10),
  in @VertegenwoordigerNummer      numeric(3,0),
  in @Opmerking                    long nvarchar,
  in @VersieNummer                 smallint,
  in @Begindatum                   date,
  in @EindDatum                    date,
  in @EersteOrderDatum             date,
  in @FactureerFreqAantal          smallint,
  in @FactureerFreqPeriode         nchar(10),
  in @ContractperiodeAantal        smallint,
  in @ContractperiodePeriode       nchar(10),
  in @OpzegtermijnAantal           smallint,
  in @OpzegTermijnPeriode          nchar(10),
  in @Referentie                   long nvarchar,
  in @IsInkoopcombinatie           smallint,
  in @DebiteurNummerFactuur        nchar(10),
  in @DebiteurNummerOmzet          nchar(10),
  in @DebiteurnummerPrijsafspraken nchar(10),
  in @FactuurAdres                 nchar(10),
  in @VerzendAdres                 nchar(10),
  in @VerzendAdresNummer           numeric(3,0),
  in @EindAdres                    nchar(10),
  in @EindAdresNummer              numeric(3,0),
  in @LeveringsConditieNummer      numeric(3,0),
  in @BetalingsConditieNummer      numeric(3,0),
  in @ValutaCode                   nchar(3),
  in @BtwPrijzen                   nchar(15),
  in @OrderKortingPercentage       numeric(15,2),
  in @KostenPlaatsCode             nchar(8),
  in @KostenDragerCode             nchar(8),
  in @VerzamellijstGebruiken       nchar(5),
  in @DeelLeveringToegestaan       nchar(20),
  in @AparteFactuur                nchar(35),
  in @OrderIsGoedgekeurd           smallint,
  in @OrderIsVrijVoorVerzamellijst smallint,
  in @OrderIsVrijVoorLeveren       smallint,
  in @OrderIsVrijVoorFactureren    smallint,
  in @TaalCode                     nchar(3)
)
result(AbonnementCode nchar(20), VersieNummer smallint)

begin
  declare @AboGid                           integer;
  declare @AboCode                          nchar(20);
  declare @AboNawGidDebiteur                integer;
  declare @AboAangemaaktDoor                nchar(40) = '';
  declare @AboVtgCode                       integer;
  declare @AbvGid                           integer;
  declare @AbvNummer                        smallint;
  declare @AbvFactureerFrequentiePeriode    smallint;
  declare @AbvContractperiodePeriode        smallint;
  declare @AbvOpzegTermijnPeriode           smallint;
  declare @AbvNawGidFactuur                 integer;
  declare @AbvNawGidOmzet                   integer;
  declare @AbvNawGidPrijzen                 integer;
  declare @AbvFactuurAdres                  smallint;
  declare @AbvVerzendAdres                  smallint;
  declare @AbvAdrGidVerzendAdres            integer;
  declare @AbvEindAdres                     smallint;
  declare @AbvAdrGidEindBestemming          integer;
  declare @AbvLvcNummer                     numeric(3,0);
  declare @AbvBtcNummer                     numeric(3,0);
  declare @AbvValNummer                     numeric(3,0);
  declare @AbvBtwStand                      smallint;
  declare @AbvKstpGid                       integer;
  declare @AbvKstdGid                       integer;
  declare @AbvOrderVerzamellijstGebruiken   smallint;
  declare @AbvIsDeelLeveringToegestaan      smallint;
  declare @AbvAparteFactuur                 smallint;
  declare @AbvTaalGid                       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Abonnementen_ToevoegenWijzigen > ';
  // call TraceBegin('WebSvcProc_Abonnementen_ToevoegenWijzigen > @AbonnementCode = ' + @AbonnementCode + ', @DebiteurNummer = ' + @DebiteurNummer);

  if IsModuleActive('aa') = 0 then   // Module t.b.v. abonnementen
    call Raise(20790,_U('Optie Abonnementen'));   // '(20790) '%1!' niet geactiveerd!';
  end if;

  begin atomic
    // AbonnementKop
    // Controle: AbonnementCode is altijd verplicht
    if (isnull(@AbonnementCode,'')) = '' then
      call Raise(20700,'AbonnementCode');   // (20700) Ongeldige waarde: %1!
    else
      set @AboCode = @AbonnementCode;
    end if;

    // Ophalen Abonnenment gegevens
    select AboGid,
           AboNawGidDebiteur
    into   @AboGid,
           @AboNawGidDebiteur
    from   tabAbonnementKop
    where  AboCode = @AbonnementCode;

    // @AboGid is null, dan nieuw abonnement, anders bestaand abonnement
    if (@AboGid is null) then
      select NawFilNawGid
      into   @AboNawGidDebiteur
      from   tabNawFile
      where  NawFilFonId = 'D'
      and    NawFilNummer = @DebiteurNummer;
      // Controle: Tijdens toevoegen is DebiteurNummer verplicht
      if (@AboNawGidDebiteur is null) then
        call Raise(20700,'DebiteurNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Debiteurnummer mag niet worden gewijzigd
    if (@AboGid is not null) and (@DebiteurNummer is not null) then
      if isnull((select NawFilNawGid from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummer),0) <> @AboNawGidDebiteur then
        call Raise(20000,_U('Abonnement komt bij een andere debiteur voor'));   // (20000) %1!
      end if;
    end if;

    // Controle: Indien VertegenwoordigerNummer is meegegeven, dan moet dit een bestaande vertegenwoordiger zijn
    if @VertegenwoordigerNummer is not null then
      select VtgCode into @AboVtgCode from tabVertegenwoordiger where VtgCode = @VertegenwoordigerNummer;
      if (@AboVtgCode is null) then
        call Raise(20700,'VertegenwoordigerNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Nieuwe AbonnementKop wordt toegevoegd in de database
    if (@AboGid is null) then
      insert into tabAbonnementKop
             (    AboNawGidDebiteur,
                  AboAangemaaktDoor,
                  AboCode,
                  AboOmschrijving,
                  AboOpmerking,
                  AboVtgCode
             )
             values
             (    @AboNawGidDebiteur,
                  isnull(@AboAangemaaktDoor,''),
                  @AboCode,
                  isnull(@AbonnementOms,''),
                  isnull(@Opmerking,''),
                  @AboVtgCode
             );
      set @AboGid = @@Identity;
    end if;

    // Gevonden of toegevoegde abonnement locken
    begin
      declare @LockResult integer;
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid, @LockResult, 0);
      if @LockResult <> 0 /*Lock gelukt*/ then
        call Raise(20741,_U('Abonnement'));   // (20741) %1! is in gebruik!
      end if;
    end;

    // Ophalen Abonnenment gegevens na locken
    select AboGid,
           AboNawGidDebiteur
    into   @AboGid,
           @AboNawGidDebiteur
    from   tabAbonnementKop
    where  AboCode = @AbonnementCode;

    // Gegevens AbonnementKop opslaan in de database
    update tabAbonnementKop
    set    AboOmschrijving = isnull(@AbonnementOms,AboOmschrijving),
           AboOpmerking    = isnull(@Opmerking,AboOpmerking),
           AboVtgCode      = isnull(@VertegenwoordigerNummer,AboVtgCode)
    where  AboGid = @AboGid;

    // AbonnementVersie
    // Indien geen Versienummer wordt meegegeven, dan wordt een nieuwe Versie toegevoegd, anders bestaande Versie wijzigen
    if @VersieNummer is null then   // Geen VersieNummer meegegeven, dan toevoegen
      // Controle: Heeft het Abonnement al een Versie, zo nee, dan altijd 1
      if not exists (select first AbvGid from tabAbonnementVersie where AbvAboGid = @AboGid) then
        set @AbvNummer = 1;
      else
        // Er is minimaal één versie aanwezig, dan hoogste versienummer ophalen en 1 bij optellen
        select first (AbvNummer + 1) into @AbvNummer from tabAbonnementVersie where AbvAboGid = @AboGid order by AbvNummer desc;
      end if;
    else   // Bestaande Versie record
      // Controle: Versienummer is meegegeven, dan moet dit een bestaande versienummer zijn binnen het abonnement
      select AbvGid,
             AbvNummer
      into   @AbvGid,
             @AbvNummer
      from   tabAbonnementVersie
      where  AbvAboGid = @AboGid
      and    AbvNummer = @VersieNummer;
      if @AbvNummer is null then
        call Raise(20700,'VersieNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: De EindDatum mag niet voor de BeginDatum liggen
    if @BeginDatum is not null or @EindDatum is not null then
      if isnull(@BeginDatum,dateformat('1900-01-01','YYYY-MM-DD')) > isnull(@EindDatum,dateformat('2099-12-31','YYYY-MM-DD')) then
        call Raise(20701,_U('Eind datum ligt voor de begin datum!'));   // (20701) Ongeldige combinatie: %1!
      end if;
    end if;

    // Controle: Indien FactureerFreqAantal niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if @FactureerFreqAantal is null and @AbvGid is null then
      set @FactureerFreqAantal = (select isnull(AbvgDefFactureerFrequentieAantal,1) from tabAbonnementVasteGegevens);
    end if;

    // Controle: Indien FactureerFreqPeriode niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if isnull(@FactureerFreqPeriode,'') = '' and @AbvGid is null then
      set @AbvFactureerFrequentiePeriode = (select isnull(AbvgDefFactureerFrequentiePeriode,2) from tabAbonnementVasteGegevens);
    end if;

    // Controle: Indien FactureerFreqPeriode is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@FactureerFreqPeriode,'') <> '' then
      case @FactureerFreqPeriode
        when 'DAGEN' then set @AbvFactureerFrequentiePeriode = 0
        when 'WEKEN' then set @AbvFactureerFrequentiePeriode = 1
        when 'MAANDEN' then set @AbvFactureerFrequentiePeriode = 2
        when 'JAAR' then set @AbvFactureerFrequentiePeriode = 3
      else
        call Raise(20700,'FactureerFreqPeriode');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: Indien ContractperiodeAantal niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if @ContractperiodeAantal is null and @AbvGid is null then
      set @ContractperiodeAantal = (select isnull(AbvgDefContractperiodeAantal,1) from tabAbonnementVasteGegevens);
    end if;

    // Controle: Indien ContractperiodePeriode niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if isnull(@ContractperiodePeriode,'') = '' and @AbvGid is null then
      set @AbvContractperiodePeriode = (select isnull(AbvgDefContractperiodePeriode,2) from tabAbonnementVasteGegevens);
    end if;

    // Controle: Indien ContractperiodePeriode is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@ContractperiodePeriode,'') <> '' then
      case @ContractperiodePeriode
        when 'DAGEN' then set @AbvContractperiodePeriode = 0
        when 'WEKEN' then set @AbvContractperiodePeriode = 1
        when 'MAANDEN' then set @AbvContractperiodePeriode = 2
        when 'JAAR' then set @AbvContractperiodePeriode = 3
      else
        call Raise(20700,'ContractperiodePeriode');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: Indien OpzegtermijnAantal niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if @OpzegtermijnAantal is null and @AbvGid is null then
      set @OpzegtermijnAantal = (select isnull(AbvgDefOpzegTermijnAantal,1) from tabAbonnementVasteGegevens);
    end if;

    // Controle: Indien OpzegTermijnPeriode niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if isnull(@OpzegTermijnPeriode,'') = '' and @AbvGid is null then
      set @AbvOpzegTermijnPeriode = (select isnull(AbvgDefOpzegTermijnPeriode,2) from tabAbonnementVasteGegevens);
    end if;

    // Controle: Indien OpzegTermijnPeriode is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@OpzegTermijnPeriode,'') <> '' then
      case @OpzegTermijnPeriode
        when 'DAGEN' then set @AbvOpzegTermijnPeriode = 0
        when 'WEKEN' then set @AbvOpzegTermijnPeriode = 1
        when 'MAANDEN' then set @AbvOpzegTermijnPeriode = 2
        when 'JAAR' then set @AbvOpzegTermijnPeriode = 3
      else
        call Raise(20700,'OpzegTermijnPeriode');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: Referentie is niet verplicht, maar mag ook niet "NULL" zijn
    if @Referentie is null then
      set @Referentie = ''
    end if;

    // Controle: Indien IsInkoopcombinatie niet is meegegeven, controleer dan of debiteur deel uit maakt van een inkoopcombinatie
    if @IsInkoopcombinatie is null then
      select     NawIsInkoopCombinatie
      into       @IsInkoopcombinatie
      from       tabNaw
      inner join tabNawFile
      on         NawFilNawGid = NawGid
      where      NawFilFonId = 'D'
      and        NawFilNummer = @DebiteurNummer;
    end if;

    // Controle: Als er sprake is van een Inkoopcombinatie, dan is DebiteurNummerFactuur verplicht
    if @IsInkoopcombinatie = 1 then
      select NawFilNawGid
      into   @AbvNawGidFactuur
      from   tabNawFile
      where  NawFilFonId = 'D'
      and    NawFilNummer = isnull(@DebiteurNummerFactuur,'');
      if @AbvNawGidFactuur is null then
        call Raise(20700,'DebiteurNummerFactuur');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Als er sprake is van een Inkoopcombinatie, dan is DebiteurNummerOmzet verplicht
    if @IsInkoopcombinatie = 1 then
      select NawFilNawGid
      into   @AbvNawGidOmzet
      from   tabNawFile
      where  NawFilFonId = 'D'
      and    NawFilNummer = isnull(@DebiteurNummerOmzet,'');
      if @AbvNawGidOmzet is null then
        call Raise(20700,'DebiteurNummerOmzet');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Als er sprake is van een Inkoopcombinatie, dan is DebiteurNummerPrijsafspraken verplicht
    if @IsInkoopcombinatie = 1 then
      select NawFilNawGid
      into   @AbvNawGidPrijzen
      from   tabNawFile
      where  NawFilFonId = 'D'
      and    NawFilNummer = isnull(@DebiteurnummerPrijsafspraken,'');
      if @AbvNawGidPrijzen is null then
        call Raise(20700,'DebiteurNummerPrijsafspraken');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: FactuurAdres is verplicht tijdens toevoegen
    if isnull(@FactuurAdres,'') = '' and @AbvGid is null then
        call Raise(20700,'FactuurAdres');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien FactuurAdres is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@FactuurAdres,'') <> '' then
      case @FactuurAdres
        when 'COR' then set @AbvFactuurAdres = 0
        when 'VEST' then set @AbvFactuurAdres = 1
      else
        call Raise(20700,'FactuurAdres');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: VerzendAdres is verplicht tijdens toevoegen
    if isnull(@VerzendAdres,'') = '' and @AbvGid is null then
        call Raise(20700,'VerzendAdres');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien VerzendAdres is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@VerzendAdres,'') <> '' then
      case @VerzendAdres
        when 'COR' then set @AbvVerzendAdres = 0
        when 'VEST' then set @AbvVerzendAdres = 1
        when 'VERZ' then set @AbvVerzendAdres = 2
        when 'FACT_COR' then set @AbvVerzendAdres = 3
        when 'FACT_VEST' then set @AbvVerzendAdres = 4
        when 'FACT_VERZ' then set @AbvVerzendAdres = 5
      else
        call Raise(20700,'VerzendAdres');   // (20700) Ongeldige waarde: %1!
      end case;
      // Controle: FACT_COR (3), FACT_VEST (4) en FACT_VERZ (5) zijn alleen toegestaan, indien er sprake is van een Inkoopcombinatie
      if @AbvVerzendAdres in (3,4,5) and @IsInkoopcombinatie = 0 then
        call Raise(20700,'VerzendAdres');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Indien VERZ (2) of FACT_VERZ (5) is geselecteerd, dan is VerzendAdresNummer verplicht
    if @AbvVerzendAdres in (2,5) then
      select AdrGid
      into   @AbvAdrGidVerzendAdres
      from   tabAdres
      where  AdrNawGid = (if @IsInkoopcombinatie = 1 and @AbvVerzendAdres = 5 then @AbvNawGidFactuur else @AboNawGidDebiteur endif)
      and    AdrCode = @VerzendAdresNummer;
      if @AbvAdrGidVerzendAdres is null or @VerzendAdresNummer is null then
        call Raise(20700,'VerzendAdresNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: EindAdres is verplicht tijdens toevoegen
    if isnull(@EindAdres,'') = '' and @AbvGid is null then
        call Raise(20700,'EindAdres');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien EindAdres is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@EindAdres,'') <> '' then
      case @EindAdres
        when 'COR' then set @AbvEindAdres = 0
        when 'VEST' then set @AbvEindAdres = 1
        when 'VERZ' then set @AbvEindAdres = 2
        when 'NVT' then set @AbvEindAdres = 3
      else
        call Raise(20700,'EindAdres');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: Indien VERZ (2) is geselecteerd, dan is EindAdresNummer verplicht
    if @AbvEindAdres = 2 then
      select AdrGid
      into   @AbvAdrGidEindBestemming
      from   tabAdres
      where  AdrNawGid = @AboNawGidDebiteur
      and    AdrCode = @EindAdresNummer;
      if @AbvAdrGidEindBestemming is null or @EindAdresNummer is null then
        call Raise(20700,'EindAdresNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Indien LeveringsConditieNummer is meegegeven, dan moet dit een bestaande Leveringsconditie zijn
    if @LeveringsConditieNummer is not null then
      select LvcNummer
      into   @AbvLvcNummer
      from   tabLeveringsConditie
      where LvcNummer = @LeveringsConditieNummer;
      if @AbvLvcNummer is null then
        call Raise(20700,'LeveringsConditieNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Indien BetalingsConditieNummer is meegegeven, dan moet dit een bestaande Betalingsconditie zijn
    if @BetalingsConditieNummer is not null then
      select BtcNummer
      into   @AbvBtcNummer
      from   tabBetalingsConditie
      where BtcNummer = @BetalingsConditieNummer;
      if @AbvBtcNummer is null then
        call Raise(20700,'BetalingsConditieNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: ValutaCode is verplicht tijdens toevoegen
    if isnull(@ValutaCode,'') = '' and @AbvGid is null then
      call Raise(20700,'ValutaCode');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien ValutaCode is meegegeven, dan moet dit een bestaande Valutacode zijn
    if isnull(@ValutaCode,'') <> '' then
      select ValNummer
      into   @AbvValNummer
      from   tabValuta
      where  ValCode = @ValutaCode;
      if @AbvValNummer is null then
        call Raise(20700,'ValutaCode');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: BtwPrijzen is verplicht tijdens toevoegen
    if isnull(@BtwPrijzen,'') = '' and @AbvGid is null then
      call Raise(20700,'BtwPrijzen');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien BtwPrijzen is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@BtwPrijzen,'') <> '' then
      case @BtwPrijzen
        when 'EXCLUSIEFBTW' then set @AbvBtwStand = 0
        when 'INCLUSIEFBTW' then set @AbvBtwStand = 1
      else
        call Raise(20700,'BtwPrijzen');   // (20700) Ongeldige waarde: %1!
      end  case;
    end if;

    // Controle: OrderKortingPercentage is verplicht tijdens toevoegen
    if @OrderKortingPercentage is null and @AbvGid is null then
      call Raise(20700,'OrderKortingPercentage');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien BtwPrijzen is meegegeven, dan moet de waarde liggen tussen -100 en 100
    if @OrderKortingPercentage < -100 or @OrderKortingPercentage > 100 then
      call Raise(20700,'OrderKortingPercentage');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien KostenPlaatsCode is meegegeven, dan moet dit een bestaande Kostenplaats zijn
    if isnull(@KostenPlaatsCode,'') <> '' then
      select KstpGid
      into   @AbvKstpGid
      from   tabKostenPlaats
      where  KstpCode = @KostenPlaatsCode;
      if @AbvKstpGid is null then
        call Raise(20700,'KostenPlaatsCode');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Indien KostenDragerCode is meegegeven, dan moet dit een bestaande Kostendrager zijn
    if isnull(@KostenDragerCode,'') <> '' then
      select KstdGid
      into   @AbvKstdGid
      from   tabKostenDrager
      where KstdCode = @KostenDragerCode;
      if @AbvKstdGid is null then
        call Raise(20700,'KostenDragerCode');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Indien VerzamellijstGebruiken niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if isnull(@VerzamellijstGebruiken,'') = '' and @AbvGid is null then
      set @AbvOrderVerzamellijstGebruiken = (select isnull(AbvgDefOrderVerzamellijstGebruiken,0) from tabAbonnementVasteGegevens);
    end if;
    // Controle: Indien VerzamellijstGebruiken is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@VerzamellijstGebruiken,'') <> '' then
      case @VerzamellijstGebruiken
        when 'NIET' then set @AbvOrderVerzamellijstGebruiken = 0
        when 'WEL' then set @AbvOrderVerzamellijstGebruiken = 1
      else
        call Raise(20700,'VerzamellijstGebruiken');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: DeelLeveringToegestaan is verplicht tijdens toevoegen
    if isnull(@DeelLeveringToegestaan,'') = '' and @AbvGid is null then
      call Raise(20700,'DeelLeveringToegestaan');   // (20700) Ongeldige waarde: %1!
    end if;
    // Controle: Indien DeelLeveringToegestaan is meegegeven, dam moet dit een geldige waarde zijn
    if isnull(@DeelLeveringToegestaan,'') <> '' then
      case @DeelLeveringToegestaan
        when 'NIET_TOEGESTAAN' then set @AbvIsDeelLeveringToegestaan = 0
        when 'TOEGESTAAN' then set @AbvIsDeelLeveringToegestaan = 1
      else
        call Raise(20700,'DeelLeveringToegestaan');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: AparteFactuur is verplicht tijdens toevoegen
    if isnull(@AparteFactuur,'') = '' and @AbvGid is null then
      call Raise(20700,'AparteFactuur');   // (20700) Ongeldige waarde: %1!
    end if;
    // Controle: Indien AparteFactuur is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@AparteFactuur,'') <> '' then
      case @AparteFactuur
        when 'JA' then set @AbvAparteFactuur = 0
        when 'NEE' then set @AbvAparteFactuur = 1
        when 'PERCONTACTPERSOON' then set @AbvAparteFactuur = 2
        when 'PERVERZENDADRES' then set @AbvAparteFactuur = 3
        when 'PERCONTACTPERSOONENVERZENDADRES' then set @AbvAparteFactuur = 4
      else
        call Raise(20700,'AparteFactuur');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // Controle: Indien OrderIsGoedgekeurd niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if @OrderIsGoedgekeurd is null and @AbvGid is null then
      set @OrderIsGoedgekeurd = (select isnull(AbvgDefOrderStatusIsGoedgekeurd,0) from tabAbonnementVasteGegevens);
    end if;
    // Controle: Indien OrderIsGoedgekeurd is meegegeven, dan moet dit een geldige waarde zijn
    if @OrderIsGoedgekeurd is not null and @OrderIsGoedgekeurd not in (0,1) then
      call Raise(20700,'OrderIsGoedgekeurd');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien OrderIsVrijVoorVerzamellijst niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if @OrderIsVrijVoorVerzamellijst is null and @AbvGid is null then
      set @OrderIsVrijVoorVerzamellijst = (select isnull(AbvgDefOrderStatusIsVrijVoorVerzamellijst,0) from tabAbonnementVasteGegevens);
    end if;
    // Controle: Indien OrderIsVrijVoorVerzamellijst is meegegeven, dan moet dit een geldige waarde zijn
    if @OrderIsVrijVoorVerzamellijst is not null and @OrderIsVrijVoorVerzamellijst not in (0,1) then
      call Raise(20700,'OrderIsVrijVoorVerzamellijst');   // (20700) Ongeldige waarde: %1!
    end if;
    // Controle: Indien VerzamellijstGebruiken = 'NIET' (0), dan is OrderIsVrijVoorVerzamellijst = Aangevinkt (1) niet toegestaan
    if @AbvOrderVerzamellijstGebruiken = 0 and @OrderIsVrijVoorVerzamellijst = 1 then
      call Raise(20701,_U('%1! mag niet zijn aangevinkt, indien ''Niet via verzamellijst'' van toepassing is!', 'OrderIsVrijVoorVerzamellijst'));   // (20701) Ongeldige combinatie: %1!
    end if;

    // Controle: Indien OrderIsVrijVoorLeveren niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if @OrderIsVrijVoorLeveren is null and @AbvGid is null then
      set @OrderIsVrijVoorLeveren = (select isnull(AbvgDefOrderStatusIsVrijVoorLeveren,0) from tabAbonnementVasteGegevens);
    end if;
    // Controle: Indien OrderIsVrijVoorLeveren is meegegeven, dan moet dit een geldige waarde zijn
    if @OrderIsVrijVoorLeveren is not null and @OrderIsVrijVoorLeveren not in (0,1) then
      call Raise(20700,'OrderIsVrijVoorLeveren');   // (20700) Ongeldige waarde: %1!
    end if;
    // Controle: Indien VerzamellijstGebruiken = 'WEL' (1), dan is OrderIsVrijVoorLeveren = Aangevinkt (1) niet toegestaan
    if @AbvOrderVerzamellijstGebruiken = 1 and @OrderIsVrijVoorLeveren = 1 then
      call Raise(20701,_U('%1! mag niet zijn aangevinkt, indien ''Wel via verzamellijst'' van toepassing is!', 'OrderIsVrijVoorLeveren'));   // (20701) Ongeldige combinatie: %1!
    end if;

    // Controle: Indien OrderIsVrijVoorFactureren niet is meegegeven tijdens toevoegen, dan default ophalen uit Vaste gegevens
    if @OrderIsVrijVoorFactureren is null and @AbvGid is null then    // Niet meegegeven en nieuw record, dan ophalen uit Vaste gegevens
      set @OrderIsVrijVoorFactureren = (select isnull(AbvgDefOrderStatusIsVrijVoorFactureren,0) from tabAbonnementVasteGegevens);
    end if;
    // Controle: Indien OrderIsVrijVoorFactureren is meegegeven, dan moet dit een geldige waarde zijn
    if @OrderIsVrijVoorFactureren is not null and @OrderIsVrijVoorFactureren not in (0,1) then
      call Raise(20700,'OrderIsVrijVoorFactureren');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: TaalCode is verplicht tijdens toevoegen
    if isnull(@TaalCode,'') = '' and @AbvGid is null then
      call Raise(20700,'TaalCode');   // (20700) Ongeldige waarde: %1!
    end if;
    // Controle: Indien TaalCode is meegegeven, dan moet dit een geldige waarde zijn
    if isnull(@TaalCode,'') <> '' then
      select TaalGid
      into   @AbvTaalGid
      from   tabTaal
      where   TaalCode = @TaalCode;
      if @AbvTaalGid is null then
        call Raise(20700,'TaalCode');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Nieuwe AbonnementVersie wordt toegevoegd in de database
    if @AbvGid is null then      // Nieuwe AbonnementVersie toevoegen
      insert into tabAbonnementVersie
             (    AbvNummer,
                  AbvAboGid,
                  AbvBeginDatum,
                  AbvEindDatum,
                  AbvEersteOrderDatum,
                  AbvFactureerFrequentieAantal,
                  AbvFactureerFrequentiePeriode,
                  AbvContractperiodeAantal,
                  AbvContractperiodePeriode,
                  AbvOpzegTermijnAantal,
                  AbvOpzegTermijnPeriode,
                  AbvReferentie,
                  AbvIsInkoopcombinatie,
                  AbvNawGidFactuur,
                  AbvNawGidOmzet,
                  AbvNawGidPrijzen,
                  AbvFactuurAdres,
                  AbvVerzendAdres,
                  AbvAdrGidVerzendAdres,
                  AbvEindAdres,
                  AbvAdrGidEindBestemming,
                  AbvLvcNummer,
                  AbvBtcNummer,
                  AbvValNummer,
                  AbvBtwStand,
                  AbvOrderKorting,
                  AbvKstpGid,
                  AbvKstdGid,
                  AbvOrderVerzamellijstGebruiken,
                  AbvIsDeelLeveringToegestaan,
                  AbvAparteFactuur,
                  AbvOrderStatusIsGoedgekeurd,
                  AbvOrderStatusIsVrijVoorVerzamellijst,
                  AbvOrderStatusIsVrijVoorLeveren,
                  AbvOrderStatusIsVrijVoorFactureren,AbvTaalGid
             )
             values
             (    @AbvNummer,
                  @AboGid,
                  @BeginDatum,
                  @EindDatum,
                  @EersteOrderDatum,
                  @FactureerFreqAantal,
                  @AbvFactureerFrequentiePeriode,
                  @ContractperiodeAantal,
                  @AbvContractperiodePeriode,
                  @OpzegtermijnAantal,
                  @AbvOpzegTermijnPeriode,
                  @Referentie,
                  @IsInkoopcombinatie,
                  @AbvNawGidFactuur,
                  @AbvNawGidOmzet,
                  @AbvNawGidPrijzen,
                  @AbvFactuurAdres,
                  @AbvVerzendAdres,
                  @AbvAdrGidVerzendAdres,
                  @AbvEindAdres,
                  @AbvAdrGidEindBestemming,
                  @AbvLvcNummer,
                  @AbvBtcNummer,
                  @AbvValNummer,
                  @AbvBtwStand,
                  @OrderKortingPercentage,
                  @AbvKstpGid,
                  @AbvKstdGid,
                  @AbvOrderVerzamellijstGebruiken,
                  @AbvIsDeelLeveringToegestaan,
                  @AbvAparteFactuur,
                  @OrderIsGoedgekeurd,
                  @OrderIsVrijVoorVerzamellijst,
                  @OrderIsVrijVoorLeveren,
                  @OrderIsVrijVoorFactureren,@AbvTaalGid
             );
    // Bestaande AbonnementVersie wordt gewijzigd in de database
    else
        update tabAbonnementVersie
        set    AbvBeginDatum                         = isnull(@Begindatum,AbvBeginDatum),
               AbvEindDatum                          = isnull(@EindDatum,AbvEindDatum),
               AbvEersteOrderDatum                   = isnull(@EersteOrderDatum,AbvEersteOrderDatum),
               AbvFactureerFrequentieAantal          = isnull(@FactureerFreqAantal,AbvFactureerFrequentieAantal),
               AbvFactureerFrequentiePeriode         = isnull(@AbvFactureerFrequentiePeriode,AbvFactureerFrequentiePeriode),
               AbvContractperiodeAantal              = isnull(@ContractperiodeAantal,AbvContractperiodeAantal),
               AbvContractperiodePeriode             = isnull(@AbvContractperiodePeriode,AbvContractperiodePeriode),
               AbvOpzegTermijnAantal                 = isnull(@OpzegtermijnAantal,AbvOpzegTermijnAantal),
               AbvOpzegTermijnPeriode                = isnull(@AbvOpzegTermijnPeriode,AbvOpzegTermijnPeriode),
               AbvReferentie                         = isnull(@Referentie,AbvReferentie),
               AbvIsInkoopcombinatie                 = isnull(@IsInkoopcombinatie,AbvIsInkoopcombinatie),
               AbvNawGidFactuur                      = isnull(@AbvNawGidFactuur,AbvNawGidFactuur),
               AbvNawGidOmzet                        = isnull(@AbvNawGidOmzet,AbvNawGidOmzet),
               AbvNawGidPrijzen                      = isnull(@AbvNawGidPrijzen,AbvNawGidPrijzen),
               AbvFactuurAdres                       = isnull(@AbvFactuurAdres,AbvFactuurAdres),
               AbvVerzendAdres                       = isnull(@AbvVerzendAdres,AbvVerzendAdres),
               AbvAdrGidVerzendAdres                 = isnull(@AbvAdrGidVerzendAdres,AbvAdrGidVerzendAdres),
               AbvEindAdres                          = isnull(@AbvEindAdres,AbvEindAdres),
               AbvAdrGidEindBestemming               = isnull(@AbvAdrGidEindBestemming,AbvAdrGidEindBestemming),
               AbvLvcNummer                          = isnull(@AbvLvcNummer,AbvLvcNummer),
               AbvBtcNummer                          = isnull(@AbvBtcNummer,AbvBtcNummer),
               AbvValNummer                          = isnull(@AbvValNummer,AbvValNummer),
               AbvBtwStand                           = isnull(@AbvBtwStand,AbvBtwStand),
               AbvOrderKorting                       = isnull(@OrderKortingPercentage,AbvOrderKorting),
               AbvKstpGid                            = isnull(@AbvKstpGid,AbvKstpGid),
               AbvKstdGid                            = isnull(@AbvKstdGid,AbvKstdGid),
               AbvOrderVerzamellijstGebruiken        = isnull(@AbvOrderVerzamellijstGebruiken,AbvOrderVerzamellijstGebruiken),
               AbvIsDeelLeveringToegestaan           = isnull(@AbvIsDeelLeveringToegestaan,AbvIsDeelLeveringToegestaan),
               AbvAparteFactuur                      = isnull(@AbvAparteFactuur,AbvAparteFactuur),
               AbvOrderStatusIsGoedgekeurd           = isnull(@OrderIsGoedgekeurd,AbvOrderStatusIsGoedgekeurd),
               AbvOrderStatusIsVrijVoorVerzamellijst = isnull(@OrderIsVrijVoorVerzamellijst,AbvOrderStatusIsVrijVoorVerzamellijst),
               AbvOrderStatusIsVrijVoorLeveren       = isnull(@OrderIsVrijVoorLeveren,AbvOrderStatusIsVrijVoorLeveren),
               AbvOrderStatusIsVrijVoorFactureren    = isnull(@OrderIsVrijVoorFactureren,AbvOrderStatusIsVrijVoorFactureren),
               AbvTaalGid                            = isnull(@AbvTaalGid,AbvTaalGid)
        where  AbvGid = @AbvGid;
    end if;
    // Na afloop Abonnement unlocken
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @AboGid);
  end;   //Atomic

  //Resultaat teruggeven
  select @AboCode   as AbonnementCode,
         @AbvNummer as VersieNummer;

  set @@ErrorTextProcedure = 'WebSvcProc_Abonnementen_ToevoegenWijzigen';
  // call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Abonnementen_VrijeRubriek_Wijzigen(
  in @AbonnementCode      nchar(20),
  in @VersieNummer        numeric(10,0),
  in @RubriekOmschrijving nchar(40),
  in @RubriekInhoud       nchar(255)
)
begin
  declare @_AboGid        integer;
  declare @_AbvGid        integer;

  set @@ErrorTextProcedure =  'WebSvcProc_Abonnementen_VrijeRubriek_Wijzigen > @AbonnementCode = ' + String(@AbonnementCode) +
                              ', @Versienummer = ' + String(@VersieNummer) +
                              ' @RubriekOmschrijving = ' + String(@RubriekOmschrijving);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('aa') = 0 then
    call Raise(20790, _U('Optie Abonnementen')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Abonnementcode
  set @_AboGid = (select AboGid from tabAbonnementKop where AboCode = @AbonnementCode);
  if (@_AboGid is null) then
    call Raise(20720, 'AbonnementCode');        // (20720) %1 niet gevonden!
  end if;

  // Abonnementversie
  set @_AbvGid = (select AbvGid from tabAbonnementVersie where AbvAboGid = @_AboGid and AbvNummer = @VersieNummer);
  if (@_AbvGid is null) then
    call Raise(20720, 'VersieNummer');          // (20720) %1 niet gevonden!
  end if;

  begin atomic
    // Abonnementcode locken als dat nog niet het geval is.
    begin
      declare @_LockResult  integer;

      call LockSetOnId(@@SpId, @@LoginTime, 1 /*Exclusive lock)*/, 'tabAbonnementKop', @_AboGid, @_Lockresult, 0 /*Loc niet aut. opruimen*/, 'KingWebService');
        if @_Lockresult = 1 /*Lock niet gelukt*/  then
           if LockedById(@@SpId, @@LoginTime, 1 /*Exclusive lock)*/, 'tabAbonnementKop', @_AboGid) = 0 /*Lock bestaat niet*/ then
              call Raise(20741, 'Abonnementcode');    // (20741) %1! is in gebruik!
           end if;
        end if;
    end;

    // Vrije rubriek aanpassen
    call VrInsertOrReplaceValue('ABO', 0, 0, @_AbvGid, @RubriekOmschrijving, @RubriekInhoud);

    // Unlock abonnement na update (er is geen aparte webservice om Abonnementen te unlocken)
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabAbonnementKop', @_AboGid);
  end; // atomic

  set @@ErrorTextProcedure = 'WebSvcProc_Abonnementen_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


//TG 26-09-2016 LET OP: DEZE MAATWERKPROCEDURE HEEFT EEN AANTAL AFWIJKINGEN T.O.V. EEN STANDAARD PROCEDURE:
// - IN DE DOCUMENTATIE IS EEN PARAMETER BESTAND OPGENOMEN DIE HIERONDER NIET AANWEZIG IS. PARAMETER BESTAND IN HET JSON BERICHT WORDT AFGEVANGEN IN DE WEBSERVER EN WEGGESCHREVEN OP SCHIJF.
// - IN DE DOCUMENTATIE ONTBREEKT PARAMETER @MD5Checksum UIT DE PROC HIERONDER. DE GEBRUIKER KAN DEZE NIET MEEGEVEN, MAAR DEZE WORDT DOOR DE WEBSERVER GEGENEREERD EN INGEVULD ALS HET BESTAND IS OPGESLAGEN.
// - DE PARAMETERS @Bestandsnaam EN @MD5Checksum MOGEN NIET HERNOEMD WORDEN, OMDAT DEZE HARDGECODEERD OPGENOMEN ZIJN IN DE SOURCECODE VAN KING WEBSERVICES (VOOR NU).
create or replace procedure WebSvcProc_Archiefstuk_Toevoegen(in @ArchiefSoort nchar(10), in @InterneCode nchar(40), in @ExterneCode nchar(40), in @AangemaaktDoor nchar(40), in @Verwerking nchar(25),
                                                             in @DagboekCode nchar(10), in @Opmerking long nvarchar, in @Afgehandeld smallint, in @NawBestand nchar(15), in @NawNummer nchar(10),
                                                             in @DatumDocument date, in @ContactPersoonNummer numeric(3,0), in @ProjectCode nchar(10), in @Bestandsnaam nchar(255), in @MD5Checksum nchar(32))
result (DigitaalArchiefstukNummer nchar(20))
begin
  declare index_not_unique exception for sqlstate '23505';
  declare @DasGid              integer;
  declare @VolgendVolgNummer   nchar(20);
  declare @DasIsEigenNummering smallint;
  declare @DarVerwerkSoort     integer;
  declare @DarNummer           nchar(20);
  declare @DgbGid              integer;
  declare @FonGid              integer;
  declare @DarNawSoort         integer;
  declare @NawGid              integer;
  declare @RelGid              integer;
  declare @ProjGid             integer;
  declare @IsOpslaanGelukt     smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Archiefstuk_Toevoegen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@ArchiefSoort = ' + @ArchiefSoort);

  if IsModuleActive('we') = 0 then
    call Raise(20902); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select DasGid, DasVolgNummer, DasIsEigenNummering into @DasGid, @DarNummer, @DasIsEigenNummering from tabDigitaalArchiefSoort where DasCode = @ArchiefSoort;
  if (@DasGid is null) then
    call Raise(20668); //Ongeldige of geen Archiefsoort meegegeven!
  end if;


  if (@InterneCode is null) then
    call Raise(20669); //Ongeldige of geen InterneCode meegegeven!
  end if;

  if IsNull(@Verwerking, '') <> '' then
    case @Verwerking
      when 'GEEN'                    then set @DarVerwerkSoort = 0;
      when 'INVOEREN_JOURNAALPOSTEN' then set @DarVerwerkSoort = 1;
      when 'OVERIGE'                 then set @DarVerwerkSoort = 2;
      else call Raise(20670); //Ongeldige of geen Verwerking meegegeven!
    end case;
  end if;

  if @DarVerwerkSoort = 1 then
    if IsNull(@DagboekCode, '') <> '' then
      select DgbGid into @DgbGid from tabDagboek where DgbCode = @DagboekCode;
      if (@DgbGid is null) then
        call Raise(20572); //Ongeldige of geen DagboekCode meegegeven
      end if;
    end if;
  else
    if IsNull(@DagboekCode, '') <> '' then
      call Raise(20572); //Ongeldige of geen DagboekCode meegegeven!
    end if;
  end if;

  if @NawBestand = 'NOGTOEWIJZEN' or IsNull(@NawBestand, '') = '' then
    set @DarNawSoort = 4;
  else
    if @NawBestand = 'GEEN' then
      set @DarNawSoort = 3;
    else
      select FonGid into @FonGid from tabFileOfNaw where FonId = @NawBestand;
      if @FonGid is null then
        call Raise(20656);  //Ongeldige of geen NawBestand meegegeven
      end if;
      case @NawBestand
        when 'D' then set @DarNawSoort = 0;
        when 'C' then set @DarNawSoort = 1;
        else          set @DarNawSoort = 2;
      end case;
    end if;
  end if;

  if @DarNawSoort in (0, 1, 2) then
    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @NawNummer;
    if (@NawGid is null) then
      call Raise(20657);  //Ongeldige of geen NawNummer meegegeven
    end if;
    //if IsNull(@ContactPersoonNummer, '') <> '' then
    if @ContactPersoonNummer is not null then
      select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
      if @RelGid is null then
        call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
      end if;
    end if;
  else
    if IsNull(@NawNummer, '') <> '' then
      call Raise(20657);  //Ongeldige of geen NawNummer meegegeven
    end if;
    if IsNull(@ContactPersoonNummer, '') <> '' then
      call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
    end if;
  end if;

  if @ProjectCode is not null then
    select ProjGid into @ProjGid from tabProject where ProjCode = @ProjectCode;
    if @ProjGid is null then
      call Raise(20630); //Ongeldige of geen ProjectCode meegegeven!
    end if;
  end if;

  set @IsOpslaanGelukt = 0;
  while @IsOpslaanGelukt = 0 loop
    if @DasIsEigenNummering = 1 then
      call GenereerVolgendeCode(@DarNummer, @VolgendVolgNummer);
      update tabDigitaalArchiefSoort set DasVolgNummer = @VolgendVolgNummer where DasGid = @DasGid;
    else
      select DavVolgNummer into @DarNummer from tabDigitaalArchiefVasteGegevens;
      call GenereerVolgendeCode(@DarNummer, @VolgendVolgNummer);
      update tabDigitaalArchiefVasteGegevens set DavVolgNummer = @VolgendVolgNummer;
    end if;

    begin
      //call Trace('WebSvcProc_Archiefstuk_Toevoegen > @DarNummer = ' + @DarNummer + ', @VolgendVolgNummer = ' + @VolgendVolgNummer);

      insert into tabDigitaalArchief(DarNummer, DarDasGid, DarCodeIntern, DarCodeExtern, DarAangemaaktDoor, DarVerwerkSoort, DarDgbGid, DarOpmerking, DarIsVerwerkt,
                                     DarNawSoort, DarNawGid, DarDatum, DarRelGid, DarProjGid, DarBestandsnaam, DarMd5CheckSum)
                              select @DarNummer, @DasGid,  @InterneCode,  IsNull(@ExterneCode, ''),  IsNull(@AangemaaktDoor, ''), @DarVerwerkSoort, @DgbGid, IsNull(@Opmerking, ''), IsNull(@Afgehandeld, 0),
                                     @DarNawSoort, @NawGid, @DatumDocument, @RelGid, @ProjGid, @Bestandsnaam, @MD5Checksum;
      set @IsOpslaanGelukt = 1;
      exception
        when index_not_unique then
        begin
          //call Trace('WebSvcProc_Archiefstuk_Toevoegen > Niet uniek afgevangen');
          if @DarNummer = @VolgendVolgNummer then //Als het volgende gegenereerde nummer gelijk is aan het huidige nummer, dan stoppen we, anders komen we in oneindige loop
            resignal
          else
            set @DarNummer = @VolgendVolgNummer;
          end if;
        end;
        when others then
          resignal;
    end;
  end loop;

  select @DarNummer as DigitaalArchiefstukNummer from dummy;

  set @@ErrorTextProcedure = 'WebSvcProc_Archiefstuk_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_BTW_ToevoegenWijzigen(
  in @ArtikelNummer                        nchar(20),
  in @LandCode                             nchar(3),
  in @BtwCodeLeveringVanuitEigenLand       nchar(3), // ''/null=overslaan, <'0'=verwijderen, >='0'=wijzigen/toevoegen
  in @BtwCodeLeveringVanuitAnderEUland     nchar(3), // ''/null=overslaan, <'0'=verwijderen, >='0'=wijzigen/toevoegen
  in @BtwCodeLeveringVanuitLandVanAangifte nchar(3), // ''/null=overslaan, <'0'=verwijderen, >='0'=wijzigen/toevoegen
  in @BtwCodeLeveringVanuitNietEUland      nchar(3)  // ''/null=overslaan, <'0'=verwijderen, >='0'=wijzigen/toevoegen
  )
begin
  declare @_ArtGid                               integer;
  declare @_LndGid                               integer;
  declare @_BtwCodeLeveringVanuitEigenLand       numeric(3,0);
  declare @_BtwCodeLeveringVanuitAnderEUland     numeric(3,0);
  declare @_BtwCodeLeveringVanuitLandVanAangifte numeric(3,0);
  declare @_BtwCodeLeveringVanuitNietEUland      numeric(3,0);
  declare @_AbaGid                               integer;
  declare @_LndIsEGLid                           smallint;
  declare @_EigenLndGid                          integer;
  declare @_Prestatiesoort                       smallint; //0=dienst, 1=goed

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_BTW_ToevoegenWijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') = 0 then
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  select ArtGid, IsOpbrGrpGoederen into @_ArtGid, @_Prestatiesoort from tabArtikel inner join tabOpbrengstGroep on OpbrGrpGid = ArtOpbrGrpGId where ArtSoort = 2 and ArtCode = @ArtikelNummer;
  if (@_ArtGid is null) then
    call Raise(20700, 'ArtikelNummer'); //(20700) Ongeldige waarde: %1!
  end if;

  select LndGid, LndIsEGLid into @_LndGid, @_LndIsEGLid from tabLand where LndEigenCode = @LandCode;
  if (@_LndGid is null) then
    call Raise(20700, 'LandCode'); //(20700) Ongeldige waarde: %1!
  end if;
  if @_LndIsEGLid = 0 then
    call Raise(20780, 'LandCode', _U('Land is geen lid van de EU')); //(20780) %1! niet mogelijk: %2!.
  end if;

  select LndGid into @_EigenLndGid from tabLand inner join tabVasteGegevens on LndGid = DefaultLndGid where VastId = 1;
  if @_LndGid = @_EigenLndGid then
    call Raise(20780, 'LandCode', _U('Land is eigen land')); //(20780) %1! niet mogelijk: %2!.
  end if;

  // Bestaande codes (indien bestaan) alvast opvragen
  select AbaBtwCodeVanuitEigenLand,
         AbaBtwCodeVanuitAnderEULand,
         AbaBtwCodeVanuitLandVanAangifte,
         AbaBtwCodeVanuitNietEULand
  into   @_BtwCodeLeveringVanuitEigenLand,
         @_BtwCodeLeveringVanuitAnderEUland,
         @_BtwCodeLeveringVanuitLandVanAangifte,
         @_BtwCodeLeveringVanuitNietEUland
  from tabArtikelBTWAfstandsVerkopen
  where AbaArtGid = @_ArtGid and AbaLndGid = @_LndGid;

  if isnull(@BtwCodeLeveringVanuitEigenLand, '') <> '' then
    set @_BtwCodeLeveringVanuitEigenLand =
      WebSvcHulpProc_CheckAndReturn_BtwCode('BtwCodeLeveringVanuitEigenLand', @BtwCodeLeveringVanuitEigenLand, 1 /*Af te dragen BTW*/, @_LndGid, 0 /*eigen land*/, @_Prestatiesoort);
  end if;


  if isnull(@BtwCodeLeveringVanuitAnderEUland, '') <> '' then
    set @_BtwCodeLeveringVanuitAnderEUland =
      WebSvcHulpProc_CheckAndReturn_BtwCode('BtwCodeLeveringVanuitAnderEUland', @BtwCodeLeveringVanuitAnderEUland, 1 /*Af te dragen BTW*/, @_LndGid, 1 /*ander EU-land*/, @_Prestatiesoort);
  end if;

  if isnull(@BtwCodeLeveringVanuitLandVanAangifte, '') <> '' then
    set @_BtwCodeLeveringVanuitLandVanAangifte =
      WebSvcHulpProc_CheckAndReturn_BtwCode('BtwCodeLeveringVanuitLandVanAangifte', @BtwCodeLeveringVanuitLandVanAangifte, 1 /*Af te dragen BTW*/, @_LndGid, 2 /*land van aangifte*/, @_Prestatiesoort);
  end if;

  if isnull(@BtwCodeLeveringVanuitNietEUland, '') <> '' then
    set @_BtwCodeLeveringVanuitNietEUland =
      WebSvcHulpProc_CheckAndReturn_BtwCode('BtwCodeLeveringVanuitNietEUland', @BtwCodeLeveringVanuitNietEUland, 1 /*Af te dragen BTW*/, @_LndGid, 3 /*niet-EU-land*/, @_Prestatiesoort);
  end if;


  select AbaGid into @_AbaGid from tabArtikelBTWAfstandsVerkopen where AbaArtGid = @_ArtGid and AbaLndGid = @_LndGid;


  if (    @_BtwCodeLeveringVanuitEigenLand       is null
      and @_BtwCodeLeveringVanuitAnderEUland     is null
      and @_BtwCodeLeveringVanuitLandVanAangifte is null
      and @_BtwCodeLeveringVanuitNietEUland      is null
     ) then
    // Geen BTW-codes, dus wellicht verwijderen van record
    if @_AbaGid is not null then
      delete tabArtikelBTWAfstandsVerkopen where AbaArtGid = @_ArtGid and AbaLndGid = @_LndGid;
    end if;
  else
    // Er zijn BTW-codes, dus updaten/toevoegen

    if @_AbaGid is null then
      // Record bestaat niet, dus toevoegen
      insert into tabArtikelBTWAfstandsVerkopen(AbaArtGid, AbaLndGid,
        AbaBtwCodeVanuitEigenLand,
        AbaBtwCodeVanuitAnderEULand,
        AbaBtwCodeVanuitLandVanAangifte,
        AbaBtwCodeVanuitNietEULand)
      values (@_ArtGid, @_LndGid,
              @_BtwCodeLeveringVanuitEigenLand,
              @_BtwCodeLeveringVanuitAnderEUland,
              @_BtwCodeLeveringVanuitLandVanAangifte,
              @_BtwCodeLeveringVanuitNietEUland
             );

    else
      // Er is iets gevuld, dus updaten
      update tabArtikelBTWAfstandsVerkopen
      set    AbaBtwCodeVanuitEigenLand  = @_BtwCodeLeveringVanuitEigenLand,
        AbaBtwCodeVanuitAnderEULand     = @_BtwCodeLeveringVanuitAnderEUland,
        AbaBtwCodeVanuitLandVanAangifte = @_BtwCodeLeveringVanuitLandVanAangifte,
        AbaBtwCodeVanuitNietEULand      = @_BtwCodeLeveringVanuitNietEUland
      where AbaArtGid = @_ArtGid and AbaLndGid = @_LndGid;
    end if;
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_BTW_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Ean_ToevoegenWijzigen(in @ArtikelNummer nchar(20), in @EanCode nchar(30), in @DefaultEanCode smallint)
begin
  declare @ArtGid    integer;
  declare @ArtEanGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_ArtikelEanToevoegenWijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    if IsNull(@EanCode, '') = '' then
      call Raise(20612); //Ongeldige of geen EanCode meegegeven!
    end if;

    select ArtEanGid into @ArtEanGid from tabArtikelEan where ArtEanArtGid = @ArtGid and ArtEanCode = @EanCode;
    if @ArtEanGid is null then
      insert into tabArtikelEan(ArtEanCode, ArtEanArtGid, ArtEanIsDefault)
      values (@EanCode, @ArtGid, @DefaultEanCode);

      set @ArtEanGid = @@Identity;
    else
      update tabArtikelEan
      set    ArtEanIsDefault = IsNull(@DefaultEanCode, ArtEanIsDefault)
      where  ArtEanGid = @ArtEanGid;
    end if;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_ArtikelEanToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Ean_Verwijderen(
  in @ArtikelNummer nchar(20),
  in @EanCode nchar(30)
)
begin
  declare @_ArtGid integer;
  declare @_ArtEanGid integer;

  //call TraceBegin('WebSvcProc_Artikel_Ean_Verwijderen > @ArtikelNummer = ' + @ArtikelNummer);

  if IsModuleActive('wl') = 0 then
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  select ArtGid
  into @_ArtGid
  from tabArtikel
  where ArtSoort = 2
    and ArtCode = @ArtikelNummer;

  if (@_ArtGid is null) then
    call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
  end if;

  if IsNull(@EanCode, '') = '' then
    call Raise(20612); //Ongeldige of geen EanCode meegegeven!
  end if;

  select ArtEanGid
  into @_ArtEanGid
  from tabArtikelEan
  where ArtEanArtGid = @_ArtGid
    and ArtEanCode = @EanCode;

  if exists(select 1 from tabArtikelLeverancierDetail where AldArtEanGid = @_ArtEanGid) then
    call Raise(20780,_U('Artikel EAN-code verwijderen'),_U('Gegeven is in gebruik bij inkoopeenheden leverancier'));   // (20780) %1! niet mogelijk: %2!
  end if;

  delete tabArtikelEan where ArtEanGid = @_ArtEanGid;

  //call TraceEind('WebSvcProc_Artikel_Ean_Verwijderen');
end;


create or replace procedure WebSvcProc_Artikel_Leverancier_InkoopEenheid_ToevoegenWijzigen(
                            in @ArtikelNummer nchar(20),
                            in @LeverancierNummer nchar(10),
                            in @InkoopEenheid nchar(20),
                            in @DefaultInkoopEenheidBijLeverancier integer,
                            in @InkoopEenheidBijLeverancier nchar(20),
                            in @AantalVoorraadEenhedenInInkoopEenheid numeric(15,3),
                            in @ArtikelNummerBijLeverancier nchar(20),
                            in @OmschrijvingBijLeverancier long nvarchar,
                            in @LevertijdInDagen smallint,
                            in @DirecteLevering nchar(35),
                            in @BestelGrootte numeric(15,3),
                            in @InkoopEenheidHeeftEigenInkoopprijs smallint,
                            in @InkoopPrijsPer nchar(20),
                            in @ValutaCode nchar(3),
                            in @InkoopPrijs numeric(15,3),
                            in @KortingSoort smallint,
                            in @KortingsBedrag numeric(15,3),
                            in @KortingsPercentage numeric(15,2),
                            in @KostprijsBerekening nchar(8),
                            in @KostprijsFactor numeric(15,3),
                            in @KostprijsToeslag numeric(15,3),
                            in @EanCode nchar(30) default null,
                            in @KortingStaffelCode nchar(10) default null
                            )
begin
  declare @ArtGid               integer;
  declare @NawGid               integer;
  declare @ArtLevGid            integer;
  declare @AldGid               integer;
  declare @InkPrijsPer          integer;
  declare @AldValNummer         integer;
  declare @Berekening           smallint;
  declare @AldDirecteLevering   smallint;
  declare @ArtEanGid            integer;
  declare @ArtEanArtGid         integer;
  declare @KortingStaffelGid    integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Leverancier_InkoopEenheid_ToevoegenWijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @LeverancierNummer;
    if (@NawGid is null) then
      call Raise(20613); //Ongeldige of geen LeverancierNummer meegegeven!
    end if;

    select ArtLevGid into @ArtLevGid from tabArtikelLeverancier where ArtLevNawGid = @NawGid and ArtLevArtGid = @ArtGid;
    if (@ArtLevGid is null) then
      call Raise(20614); //Combinatie artikel en leverancier niet gevonden!
    end if;

    if IsNull(trim(@InkoopEenheid), '') = '' then
      call Raise(20615); //Ongeldige of geen InkoopEenheid meegegeven!
    end if;

    if IsNull(@InkoopPrijsPer, '') <> '' then
      case @InkoopPrijsPer
        when 'INKOOPEENHEID'    then set @InkPrijsPer = 0;
        when 'VOORRAADEENHEDEN' then set @InkPrijsPer = 1;
        else call Raise(20616); //Ongeldige of geen InkoopPrijsPer meegegeven!
      end case;
    end if;

    if IsNull(@KostprijsBerekening, '') <> '' then
      case @KostprijsBerekening
        when 'FACTOR'   then set @Berekening = 0;
        when 'TOESLAG'  then set @Berekening = 1;
        else call Raise(20617); //Ongeldige of geen KostprijsBerekening meegegeven!
      end case;
    end if;

    select AldGid,
           if @InkoopEenheidHeeftEigenInkoopprijs is null then AldHeeftEigenInkoopprijs else @InkoopEenheidHeeftEigenInkoopprijs endif,
           if @KortingSoort is null then AldKortingSoort else @KortingSoort endif,
           if @Berekening is null then AldBerekeningKostprijs else @Berekening endif
      into @AldGid, @InkoopEenheidHeeftEigenInkoopprijs, @KortingSoort, @Berekening from tabArtikelLeverancierDetail where AldArtLevGid = @ArtLevGid and AldInkoopEenheid = @InkoopEenheid;

    if IsNull(@ValutaCode, '') <> '' then
      select ValNummer into @AldValNummer from tabValuta where ValCode = @ValutaCode;
      if (@AldValNummer is null) then
        call Raise(20512); //Ongeldige of geen ValutaCode meegegeven!
      end if;
    end if;

    if IsNull(@InkoopEenheidHeeftEigenInkoopprijs, 0) = 0 then
      set @KostprijsToeslag   = null;
      set @KostprijsFactor    = null;
      set @KortingsPercentage = null;
      set @KortingsBedrag     = null;
      set @KortingSoort       = null;
      set @KortingStaffelCode = null;
      set @KortingStaffelGid  = null;
      set @InkoopPrijs        = null;
      set @ValutaCode         = null;
      set @InkoopPrijsPer     = null;
    else
      if (IsNull(@KortingSoort,0) not in (0,1,2)) then
        call Raise(20618); //Ongeldige of geen KortingSoort meegegeven!
      end if;
      if IsNull(@Berekening, 0) = 1 then
        set @KostprijsFactor = null;
        if (IsNull(@KostprijsToeslag, 0) < 0) then
          call Raise(20619); //Ongeldige of geen KostprijsToeslag meegegeven!
        end if;
      end if;
      if IsNull(@Berekening, 0) = 0 then
        set @KostprijsToeslag = null;
        if @KostprijsFactor is null then  //Veld niet meegegeven, dan default met 1 vullen (net zoals in King)
          set @KostprijsFactor = 1;
        else
          if (IsNull(@KostprijsFactor, 0) < 1) or (IsNull(@KostprijsFactor, 0) > 999.99) then
            call Raise(20620); //Ongeldige of geen KostprijsFactor meegegeven!
          end if;
        end if;
      end if;
      if IsNull(@KortingSoort, 0) = 0 then //Kortingsbedrag
        set @KortingsPercentage = null;
        set @KortingStaffelCode = null;
        set @KortingStaffelGid  = null;
      end if;
      if IsNull(@KortingSoort, 0) = 1 then  //Kortingspercentage
        set @KortingsBedrag     = null;
        set @KortingStaffelCode = null;
        set @KortingStaffelGid  = null;
      end if;
      if IsNull(@KortingSoort, 0) = 2 then  //Kortingstaffel
        set @KortingsBedrag     = null;
        set @KortingsPercentage = null;

        // bestaat Staffelkortingcode?
        select nstfKopGid into @KortingStaffelGid from tabNawStaffelKop where NstfKopCode=IsNull(@KortingStaffelCode, '') and NstfKopNawGid=@NawGid;
        if @KortingStaffelGid is null then
          call Raise(20720, _U('Kortingstaffel')); // %1 niet gevonden
        end if;
      end if;

    end if;

    // Directe levering alleen als optie Directe inkoop is geactiveerd
    if  IsModuleActive('di') = 1 and @DirecteLevering is not null then      // di = Optie Directie Inkoop
        case @DirecteLevering
             when 'NIETTOEGESTAAN'                   then set @AldDirecteLevering = 0;
             when 'TOEGESTAANNIETVIADIRECTELEVERING' then set @AldDirecteLevering = 1;
             when 'TOEGESTAANVIADIRECTELEVERING'     then set @AldDirecteLevering = 2;
             else call Raise(20700, 'DirecteLevering');   // (20700) Ongeldige waarde: %1!
        end case;
    else
        // Optie Directe Inkoop is niet geactiveerd of @DirecteLevering is niet meegegeven, dan is de defaultwaarde 0
        set @AldDirecteLevering = 0;
    end if;

    // controleer eancode
    set @EanCode = trim(@EanCode);

    // bestaat eancode?
    if IsNull(@EanCode, '') <> '' then
      select ArtEanGid, ArtEanArtGid into @ArtEanGid, @ArtEanArtGid from tabArtikelEan where ArtEanCode = @EanCode;
      if @ArtEanGid is null then
        call Raise(20700, _U('EAN-code bestaat niet.')); // Ongeldige waarde: %1
      else
        if (@ArtGid <> @ArtEanArtGid)  then
          call Raise(20700, _U('EAN-code is in gebruik bij ander artikel.')); // Ongeldige waarde: %1
        end if;
      end if;
    end if;

    // trigger tb_tabArtikelLeverancierDetail controleert of eancode al voorkomt bij andere inkoopeenheid van dit artikel

    if @AldGid is null then
      if IsNull(@AantalVoorraadEenhedenInInkoopEenheid, 0) = 0 then
        call Raise(20621); //Ongeldige of geen AantalVoorraadEenhedenInInkoopEenheid meegegeven!
      end if;

      insert into tabArtikelLeverancierDetail
             (  AldArtLevGid,
                AldInkoopEenheid,
                AldInkoopEenheidBijLeverancier,
                AldVoorraadEenhedenInInkoopEenheid,
                AldArtCodeBijLeverancier,
                AldBestelGrootte,
                AldDirecteLevering,
                AldIsDefaultInkoopEenheidBijLev,
                AldHeeftEigenInkoopprijs,
                AldOmsBijLeverancier,
                AldLevertijd,
                AldInkoopPrijsPer,
                AldInkoopPrijs,
                AldKortingSoort,
                AldKortingBedrag,
                AldKortingPercentage,
                AldNstfKopGid,
                AldFactorKostprijs,
                AldValNummer,
                AldBerekeningKostprijs,
                AldBedragToeslag,
                AldArtEanGid)
      values (  @ArtLevGid,
                @InkoopEenheid,
                @InkoopEenheidBijLeverancier,
                @AantalVoorraadEenhedenInInkoopEenheid,
                @ArtikelNummerBijLeverancier,
                @BestelGrootte,
                @AldDirecteLevering,
                @DefaultInkoopEenheidBijLeverancier,
                @InkoopEenheidHeeftEigenInkoopprijs,
                @OmschrijvingBijLeverancier,
                @LevertijdInDagen,
                @InkPrijsPer,
                @InkoopPrijs,
                @KortingSoort,
                @KortingsBedrag,
                @KortingsPercentage,
                @KortingStaffelGid,
                @KostprijsFactor,
                @AldValNummer,
                @Berekening,
                @KostprijsToeslag,
                @ArtEanGid);
      set @AldGid = @@Identity;
    else
      if @AantalVoorraadEenhedenInInkoopEenheid = 0 then
        call Raise(20621); //Ongeldige of geen AantalVoorraadEenhedenInInkoopEenheid meegegeven!
      end if;

      update tabArtikelLeverancierDetail
      set    AldInkoopEenheidBijLeverancier     = IsNull(@InkoopEenheidBijLeverancier, AldInkoopEenheidBijLeverancier),
             AldVoorraadEenhedenInInkoopEenheid = IsNull(@AantalVoorraadEenhedenInInkoopEenheid, AldVoorraadEenhedenInInkoopEenheid),
             AldArtCodeBijLeverancier           = IsNull(@ArtikelNummerBijLeverancier, AldArtCodeBijLeverancier),
             AldBestelGrootte                   = IsNull(@BestelGrootte, AldBestelGrootte),
             AldDirecteLevering                 = isnull(@AldDirecteLevering, AldDirecteLevering),
             AldIsDefaultInkoopEenheidBijLev    = IsNull(@DefaultInkoopEenheidBijLeverancier, AldIsDefaultInkoopEenheidBijLev),
             AldHeeftEigenInkoopprijs           = IsNull(@InkoopEenheidHeeftEigenInkoopprijs, AldHeeftEigenInkoopprijs),
             AldOmsBijLeverancier               = IsNull(@OmschrijvingBijLeverancier, AldOmsBijLeverancier),
             AldLevertijd                       = IsNull(@LevertijdInDagen, AldLevertijd),
             AldInkoopPrijsPer                  = IsNull(@InkPrijsPer, AldInkoopPrijsPer),
             AldInkoopPrijs                     = IsNull(@InkoopPrijs, AldInkoopPrijs),
             AldKortingSoort                    = IsNull(@KortingSoort, AldKortingSoort),
             AldKortingBedrag                   = if IsNull(@KortingSoort, AldKortingSoort) = 0 then IsNull(@KortingsBedrag, AldKortingBedrag) else 0 endif,
             AldKortingPercentage               = if IsNull(@KortingSoort, AldKortingSoort) = 1 then IsNull(@KortingsPercentage, AldKortingPercentage) else 0 endif,
             AldNstfKopGid                      = if IsNull(@KortingSoort, AldKortingSoort) = 2 then IsNull(@KortingStaffelGid, AldNstfKopGid) else null endif,
             AldFactorKostprijs                 = if IsNull(@InkoopEenheidHeeftEigenInkoopprijs, AldHeeftEigenInkoopprijs) = 1 then IsNull(@KostprijsFactor, AldFactorKostprijs) else null endif,
             AldValNummer                       = IsNull(@AldValNummer, if @ValutaCode is null then AldValNummer else null endif),
             AldBerekeningKostprijs             = IsNull(@Berekening, AldBerekeningKostprijs),
             AldBedragToeslag                   = if IsNull(@InkoopEenheidHeeftEigenInkoopprijs, AldHeeftEigenInkoopprijs) = 1 then IsNull(@KostprijsToeslag, AldBedragToeslag) else null endif,
             AldArtEanGid                       = if @EanCode is null then
                                                     AldArtEanGid
                                                  else
                                                    if @EanCode = '' then
                                                      null
                                                    else
                                                      @ArtEanGid
                                                    end if
                                                  end if
      where  AldGid = @AldGid;
    end if;

  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Leverancier_InkoopEenheid_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Leverancier_InkoopEenheid_Verwijderen(in @ArtikelNummer nchar(20), in @LeverancierNummer nchar(10), in @InkoopEenheid nchar(20))
begin
  declare @ArtGid    integer;
  declare @NawGid    integer;
  declare @ArtLevGid integer;
  declare @AldGid    integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Leverancier_InkoopEenheid_Verwijderen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @LeverancierNummer;
    if (@NawGid is null) then
      call Raise(20613); //Ongeldige of geen LeverancierNummer meegegeven!
    end if;

    select ArtLevGid into @ArtLevGid from tabArtikelLeverancier where ArtLevNawGid = @NawGid and ArtLevArtGid = @ArtGid;
    if (@ArtLevGid is null) then
      call Raise(20614); //Combinatie artikel en leverancier niet gevonden!
    end if;

    select AldGid into @AldGid from tabArtikelLeverancierDetail where AldArtLevGid = @ArtLevGid and AldInkoopEenheid = @InkoopEenheid;
    if (@AldGid is null) then
      call Raise(20615); //Ongeldige of geen InkoopEenheid meegegeven!
    end if;

    delete tabArtikelLeverancierDetail where AldGid = @AldGid;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Leverancier_InkoopEenheid_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Leverancier_ToevoegenWijzigen(in @ArtikelNummer nchar(20), in @LeverancierNummer nchar(10), in @DefaultLeverancier integer)
begin
  declare @ArtGid    integer;
  declare @NawGid    integer;
  declare @ArtLevGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Leverancier_ToevoegenWijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @LeverancierNummer;
    if (@NawGid is null) then
      call Raise(20613); //Ongeldige of geen LeverancierNummer meegegeven!
    end if;

    select ArtLevGid into @ArtLevGid from tabArtikelLeverancier where ArtLevNawGid = @NawGid and ArtLevArtGid = @ArtGid;
    if @ArtLevGid is null then
      insert into tabArtikelLeverancier(ArtLevNawGid, ArtLevArtGid, ArtLevIsDefault)
      values (@NawGid, @ArtGid, @DefaultLeverancier);

      set @ArtLevGid = @@Identity;
    else
      update tabArtikelLeverancier
      set    ArtLevIsDefault = IsNull(@DefaultLeverancier, ArtLevIsDefault)
      where  ArtLevGid = @ArtLevGid;
    end if;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Leverancier_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Leverancier_Verwijderen(in @ArtikelNummer nchar(20), in @LeverancierNummer nchar(10))
begin
  declare @ArtGid    integer;
  declare @NawGid    integer;
  declare @ArtLevGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Leverancier_Verwijderen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @LeverancierNummer;
    if (@NawGid is null) then
      call Raise(20613); //Ongeldige of geen LeverancierNummer meegegeven!
    end if;

    select ArtLevGid into @ArtLevGid from tabArtikelLeverancier where ArtLevNawGid = @NawGid and ArtLevArtGid = @ArtGid;
    delete tabArtikelLeverancier where ArtLevGid = @ArtLevGid;

  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Leverancier_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Locatie_Verwijderen(
   in @ArtikelNummer   nchar(20),
   in @MagazijnCode    numeric(3,0),
   in @LocatieCode     nchar(20)
)
begin
  // Verwijder een artikellocatie als daar geen voorraad op ligt
  // Als locatie de voorkeurslocatie is, dan alsnog verwijderen

  declare @_ArtGid       integer;
  declare @_ArtPartijGid integer;
  declare @_MagGid       integer;
  declare @_LocGid       integer;
  declare @_ArtMagGid    integer;
  declare @_ArtLocGid    integer;
  declare @_artIsPartijRegistrerend smallint;
  declare @_artIsSerieRegistrerend  smallint;

  declare @IsStandaardPartijOfLeeg smallint;  // Altijd partij (Standaard) en zonder partij
  declare @IsPartij                smallint;  // test altijd op partij (evt. partij NULL)

  declare _JA  smallint = 1;
  declare _NEE smallint = 0;

  if IsModuleActive('wl') = 0 then
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  select ArtGid, ArtIsPartijRegistreren, ArtSerieNrRegistreren
  into   @_ArtGid, @_artIsPartijRegistrerend, @_artIsSerieRegistrerend
  from   tabArtikel
  where  ArtSoort = 2 and ArtCode = @ArtikelNummer;
  if (@_ArtGid is null) then
    call Raise(20720, 'ArtikelNummer'); //(20720) %1! niet gevonden!
  end if;

  set @IsStandaardPartijOfLeeg = if @_artIsSerieRegistrerend = 1 and @_artIsPartijRegistrerend = 0 then _JA else _NEE endif;
  set @IsPartij = if @_artIsPartijRegistrerend = 0 then _NEE else _JA endif;


  // @MagazijnCode mag alleen cijfers bevatten
  if @MagazijnCode is null or @MagazijnCode < 0 or @MagazijnCode > 999 then
    call Raise(20700, 'MagazijnCode'); //(20700) Ongeldige waarde: %1!
  end if;

  select MagGid
  into @_MagGid
  from tabMagazijn
  where MagCode = @MagazijnCode;
  if @_MagGid is null then
    call Raise(20720, 'MagazijnCode'); //(20720) %1! niet gevonden!
  end if;

  select LocGid
  into @_LocGid
  from tabLocatie
  where LocMagGid = @_MagGid and LocNaam = @LocatieCode;
  if @_LocGid is null then
    call Raise(20202); //(20202) Locatie is niet bekend binnen magazijn!
  end if;


  // Opzoeken artikelmagazijn
  select ArtMagGid
  into   @_ArtMagGid
  from tabArtikelMagazijn
  where ArtMagArtGid = @_ArtGid
    and ArtMagMagGid = @_MagGid;


  if @_ArtMagGid is not null then
    begin
      declare  @_AantalMetVoorraad integer;
      declare  @_AantalTeVerwijderen integer;

      //Verwijder alle artikellocatierecords van artikel + locatie zonder voorraad
      select sum(abs(sign(ArtLocVoorraad))), count(*)
      into @_AantalMetVoorraad, @_AantalTeVerwijderen
      from  tabArtikelLocatie
      where  ArtLocArtGid = @_ArtGid
          and ArtLocArtMagGid = @_ArtMagGid
          and ArtLocLocGid = @_LocGid;

      if @_AantalTeVerwijderen <> 0 then

        // Do your job!
        delete tabArtikelLocatie
        where  ArtLocArtGid = @_ArtGid
            and ArtLocArtMagGid = @_ArtMagGid
            and ArtLocLocGid = @_LocGid
            and ArtLocVoorraad = 0;

        // Meldingen
        case
          when @_AantalMetVoorraad <> 0 then
            call Raise(20780, _U('Locatie van artikel verwijderen'), _U('De locatievoorraad ') || if @_artIsPartijRegistrerend = 1 then _U('(per partij) ') endif || _U('moet nul zijn')); //(20780) %1! niet mogelijk: %2!.
        end case;
      end if;
    end;
  end if;

end;


create or replace procedure WebSvcProc_Artikel_Magazijn_ToevoegenWijzigen(in @ArtikelNummer nchar(20), in @MagazijnCode numeric(3,0), in @DefaultMagazijn integer, in @MinimumVoorraad numeric(15,3), in @MaximumVoorraad numeric(15,3))
begin
  declare @ArtGid    integer;
  declare @MagGid    integer;
  declare @ArtMagGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Magazijn_ToevoegenWijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel  where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select MagGid into @MagGid from tabMagazijn where MagCode = @MagazijnCode;
    if (@MagGid is null) then
      call Raise(20511); //Ongeldige of geen MagazijnCode meegegeven!
    end if;

    if (@DefaultMagazijn is not null) then
      if @DefaultMagazijn not in (0,1) then
        call Raise(20641); //Ongeldige of geen DefaultMagazijn meegegeven!
      end if;
    end if;

    select ArtMagGid into @ArtMagGid from tabArtikelMagazijn where ArtMagArtGid = @ArtGid and ArtMagMagGid = @MagGid;
    if @ArtMagGid is null then
      insert into tabArtikelMagazijn(ArtMagMagGid, ArtMagArtGid, ArtMagMinimumVoorraad, ArtMagMaximumVoorraad)
      values (@MagGid, @ArtGid, @MinimumVoorraad, @MaximumVoorraad);

      set @ArtMagGid = @@Identity;
    else
      update tabArtikelMagazijn
      set    ArtMagMinimumVoorraad = IsNull(@MinimumVoorraad, ArtMagMinimumVoorraad),
             ArtMagMaximumVoorraad = IsNull(@MaximumVoorraad, ArtMagMaximumVoorraad)
      where  ArtMagGid = @ArtMagGid;
    end if;

    if @DefaultMagazijn is not null then
      update tabArtikel set ArtDefaultMagGid = if @DefaultMagazijn = 1 then @MagGid else if ArtDefaultMagGid = @MagGid then null else ArtDefaultMagGid endif endif where ArtGid = @ArtGid;
    end if;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Magazijn_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Magazijn_Verwijderen(in @ArtikelNummer nchar(20), in @MagazijnCode numeric(3,0))
begin
  declare @ArtGid    integer;
  declare @MagGid    integer;
  declare @ArtMagGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_ArtikelMagazijnKoppelingVerwijderen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select MagGid into @MagGid from tabMagazijn where MagCode = @MagazijnCode;
    if (@MagGid is null) then
      call Raise(20511); //Ongeldige of geen MagazijnCode meegegeven!
    end if;

    select ArtMagGid into @ArtMagGid from tabArtikelMagazijn where ArtMagArtGid = @ArtGid and ArtMagMagGid = @MagGid;
    delete tabArtikelMagazijn where ArtMagGid = @ArtMagGid;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_ArtikelMagazijnKoppelingVerwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Omschrijving_ToevoegenWijzigen(in @ArtikelNummer nchar(20), in @Taalcode nchar(3), in @Omschrijving long nvarchar)
begin
  declare @ArtGid      integer;
  declare @TaalGid     integer;
  declare @ArtTekstGid integer;
  declare @DocSoort    integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Omschrijving_ToevoegenWijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    set @DocSoort = 50;

    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select TaalGid into @TaalGid from tabTaal where TaalCode = @TaalCode;
    if (@TaalGid is null) then
      call Raise(20549); //Ongeldige of geen TaalCode meegegeven!
    end if;

    select ArtTekstGid into @ArtTekstGid from tabArtikelTeksten where ArtTekstDocSoort = @DocSoort and ArtTekstArtGid = @ArtGid and ArtTaalGid = @TaalGid;
    if @ArtTekstGid is null then
      insert into tabArtikelTeksten(ArtTekstDocSoort, ArtTekstArtGid, ArtTaalGid, ArtTekst)
      values (@DocSoort, @ArtGid, @TaalGid, @Omschrijving);

      set @ArtTekstGid = @@Identity;
    else
      update tabArtikelTeksten
      set    ArtTekst = IsNull(@Omschrijving, ArtTekst)
      where  ArtTekstGid = @ArtTekstGid;
    end if;

  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Omschrijving_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


