create or replace procedure WebSvcProc_Artikel_Partij_ToevoegenWijzigen(
  in @ArtikelNummer nchar(20),
  in @PartijNummer nchar(20),
  in @Omschrijving nchar(40),
  in @LeverancierNummer nchar(10),
  in @PartijNummerBijLeverancier nchar(20),
  in @ProductieDatum date,
  in @ThtDatum date,
  in @Opmerking long nvarchar,
  in @ValutaCode nchar(3),
  in @InkoopPrijs numeric(15,3),
  in @CbsLandOorsprong nchar(3)
  )
begin
  declare @ArtGid                      integer;
  declare @ArtPartijNawGid             integer;
  declare @ArtPartijGid                integer;
  declare @ArtPartijInkoopValNummer    integer;
  declare @ArtIsPartijRegistreren      smallint;
  declare @ArtPartijLndGidCbsOorsprong integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Partij_ToevoegenWijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid, ArtIsPartijRegistreren into @ArtGid, @ArtIsPartijRegistreren from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20524); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    if IsNull(@PartijNummer, '') = '' then
      call Raise(20526); //Ongeldige of geen PartijNummer meegegeven!
    end if;

    if (@ArtIsPartijRegistreren = 0) then
      call Raise(20537); //Artikel is geen partij registrerend artikel!
    end if;

    if IsNull(@LeverancierNummer, '') <> '' then
      select NawFilNawGid into @ArtPartijNawGid from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @LeverancierNummer;
      if (@ArtPartijNawGid is null) then
        call Raise(20613); //Ongeldige of geen LeverancierNummer meegegeven!
      end if;
    end if;

    if (@ValutaCode is not null) then
      select ValNummer into @ArtPartijInkoopValNummer from tabValuta where ValCode = @ValutaCode;
      if (@ArtPartijInkoopValNummer is null) then
        call Raise(20512); //Ongeldige of geen ValutaCode meegegeven!
      end if;
    end if;

    if IsNull(@CbsLandOorsprong, '') <> '' then
      select first LndGid into @ArtPartijLndGidCbsOorsprong from tabLand where LndEigenCode = @CbsLandOorsprong;
      if (@ArtPartijLndGidCbsOorsprong is null) then
        call Raise(20698); // Ongeldige of geen CbsLandOorsprong meegegeven!
      end if;
    end if;

    select ArtPartijGid into @ArtPartijGid from tabArtikelPartij where ArtPartijArtGid = @ArtGid and ArtPartijNummer = @PartijNummer;
    if @ArtPartijGid is null then
      if @ValutaCode is null then
        set @ArtPartijInkoopValNummer = @@BasisValutanummer;  //Geen valutacode meegegeven, dan is het de basisvaluta (alleen bij toevoegen)
      end if;
      insert into tabArtikelPartij(ArtPartijNummer, ArtPartijArtGid, ArtPartijOms, ArtPartijNawGid, ArtPartijNrBijLeverancier, ArtPartijDatumProductie,
                                   ArtPartijTHTdatum, ArtPartijOpm, ArtPartijInkoopValNummer, ArtPartijInkoopPrijs, ArtPartijLndGidCbsOorsprong)
      select @PartijNummer, @ArtGid, @Omschrijving, @ArtPartijNawGid, @PartijNummerBijLeverancier, DateTimeConversieVoorWebServices(@ProductieDatum, @ProductieDatum),
             DateTimeConversieVoorWebServices(@ThtDatum, @ThtDatum), @Opmerking, @ArtPartijInkoopValNummer, @InkoopPrijs, @ArtPartijLndGidCbsOorsprong;

      set @ArtPartijGid = @@Identity;

      // Vrije rubrieken het artikel overnemen naar partij
      // ACW 2022-11-28 defect 58571: PartijOvernemenVrijeRubrieken->VrKopieerRecord
      //call PartijOvernemenVrijeRubrieken(@ArtPartijGid);
      call VrKopieerRecord('ART',0,0,'PAR',0,0,@ArtGid,@ArtPartijGid);

    else
      update tabArtikelPartij
      set    ArtPartijOms                = IsNull(@Omschrijving, ArtPartijOms),
             ArtPartijNawGid             = IsNull(@ArtPartijNawGid, ArtPartijNawGid),
             ArtPartijNrBijLeverancier   = IsNull(@PartijNummerBijLeverancier, ArtPartijNrBijLeverancier),
             ArtPartijDatumProductie     = (select DateTimeConversieVoorWebServices(@ProductieDatum, ArtPartijDatumProductie)),
             ArtPartijOpm                = IsNull(@Opmerking, ArtPartijOpm),
             ArtPartijInkoopValNummer    = IsNull(@ArtPartijInkoopValNummer, if @ValutaCode is null then ArtPartijInkoopValNummer else null endif),
             ArtPartijInkoopPrijs        = IsNull(@InkoopPrijs, ArtPartijInkoopPrijs),
             ArtPartijTHTdatum           = (select DateTimeConversieVoorWebServices(@ThtDatum, ArtPartijTHTdatum)),
             ArtPartijLndGidCbsOorsprong = IsNull(@ArtPartijLndGidCbsOorsprong, ArtPartijLndGidCbsOorsprong)
      where  ArtPartijGid = @ArtPartijGid;
    end if;

  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Partij_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Partij_VrijeRubriek_Wijzigen(in @ArtikelNummer nchar(20), in @PartijNummer nchar(20), in @RubriekOmschrijving nchar(40), in @RubriekInhoud nchar(255))
begin
  declare @ArtGid       integer;
  declare @ArtPartijGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Partij_VrijeRubriek_Wijzigen > @ArtikelNummer = ' + @ArtikelNummer +'; @PartijNummer = ' + @PartijNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  // --- Controle: juiste modules
  if IsModuleActive('wl') = 0 then
    call Raise(20904); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  // --- Controle: Geldig artikel
  select ArtGid  into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
  if (@ArtGid is null) then
    call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
  end if;

  // --- Controle: Geldige partij
  select ArtPartijGid  into @ArtPartijGid from tabArtikelPartij where ArtPartijArtGid = @ArtGid and ArtPartijNummer = @PartijNummer;
  if (@ArtPartijGid is null) then
    call Raise(20526); //Ongeldige of geen PartijNummer meegegeven!
  end if;

  call VrInsertOrReplaceValue('PAR', 0, 0, @ArtPartijGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Partij_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Prijswijzigingen_Verwerken(in @Boekdatum date)
result(BoekingsgangNummer integer)
begin
  declare @Pernr                  integer;
  declare @ArtVastPrijsWijzDgbGid integer;
  declare @BoekStukNummer         numeric(10,0);
  declare @BoekGangGid            integer;
  declare @Foutnummer             integer;
  declare @Foutmelding            nchar(250);

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Prijswijzigingen_Verwerken >';
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    set @BoekDatum = (select DateTimeConversieVoorWebServices(@BoekDatum, @BoekDatum));
    if (@BoekDatum is null) then
      set @@Verwerkingsdatum = date(now());
    else
      set @@Verwerkingsdatum = @BoekDatum;
    end if;
    select PerBjGid, PerNr into @@BjGid, @PerNr from tabPeriode where @@Verwerkingsdatum between BeginDatum and EindDatum;
    if @@BjGid is null then
      call Raise(20625); //De prijswijzigingen kunnen niet worden verwerkt! De huidige datum valt niet binnen een boekjaar!
    end if;

    for @Cursor AS Cursor_Locks Cursor for
      select PwrArtGid @PwrArtGid from tabPrijsWijzigingsRegel
    for read only
    do
      call CheckPrijswijzigingsHistorie(@PwrArtGid, @@Verwerkingsdatum, @Foutnummer, @Foutmelding);
      if @FoutNummer <> 0 then
        call Raise(20000, @Foutmelding);
      end if;
    end for;

    select ArtVastPrijsWijzDgbGid into @ArtVastPrijsWijzDgbGid from tabArtikelVasteGegevens where ArtVastSoort = 2;
    call BoekStukNummerGenereren(@ArtVastPrijsWijzDgbGid, @@BjGid, @BoekStukNummer);
    call PrijswijzigingenVerwerken(1, @ArtVastPrijsWijzDgbGid, @BoekStukNummer, _A('Webservice prijswijzigingen verwerken'), @@Verwerkingsdatum, @BoekGangGid);

    select BoekGangNummer as BoekingsgangNummer from tabBoekingsgang where BoekGangGID = @BoekGangGid;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Prijswijzigingen_Verwerken';
  //call TraceEind(@@ErrorTextProcedure);
end;


