  in @ArtikelNummer                     nchar(20),
  in @ZoekCode                          nchar(20),
  in @OmschrijvingKort                  nchar(40),
  in @OpbrengstgroepNummer              nchar(4),
  in @AantalDecimalenAantallen          smallint,
