  in @VolumePer                         numeric(15,3),
  in @Volume                            numeric(15,3),
  in @BtwCodeVerkoop                    numeric(3,0),
  in @BestellenViaDirecteInkoop         smallint,
  in @OmschrijvingVerkooporderOvernemen smallint,
  in @BestellenVoorDirecteLevering      nchar(20),
  in @CbsGoederencode                   nchar(8),
