  in @GeprijsdPer                       numeric(15,3),
  in @Kostprijs                         numeric(15,3),
  in @Verkoopprijs                      numeric(15,3),
  in @VerkoopprijsIsInclusiefBtw        smallint,
  in @VoorraadBijhouden                 smallint,
  in @GeblokkeerdVoorVerkoop            smallint,
  in @MeenemenInBesteladviezen          smallint,
  in @AfbeeldingKlein                   nchar(80),
  in @AfbeeldingGroot                   nchar(80),
  in @Omschrijving                      long nvarchar,
  in @Opmerking                         long nvarchar,
  in @WebArtikel                        smallint,
  in @WebBestelGrootte                  numeric(15,3),
  in @BtwCodeInkoop                     numeric(3,0),
  in @GeblokkeerdVoorBestelling         smallint,
  in @AbcIndeling                       nchar(20),
  in @Lengte                            numeric(15,2),
  in @Breedte                           numeric(15,2),
  in @Hoogte                            numeric(15,2),
  in @KostprijsWijzigenBijOrderinvoer   smallint,
  in @StandaardReceptCode               nchar(20)     default null,
  in @Adviesprijs                       numeric(15,3) default null,
  in @AdviesprijsIsInclusiefBtw         smallint      default null
  )
begin atomic
  // Fixed enumerators
  declare @_Mode smallint;
  declare _TOEVOEGEN smallint = 0;
  declare _WIJZIGEN smallint = 1;

  // Vaste gegevens Artikelen
  declare @_VG_VoorraadEenheid                   nchar(20);
  declare @_VG_BestellenViaDirecteInkoop         smallint;
  declare @_VG_OmschrijvingVerkooporderOvernemen smallint;
  declare @_VG_BestellenVoorDirecteLevering      nchar(20);
  declare @_VG_MeenemenInBesteladviezen          smallint;
  declare @_VG_OpbrGrpGId                        integer;
  declare @_VG_AantalDecimalenAantallen          smallint;
  declare @_VG_AantalDecimalenPrijzen            smallint;
  declare @_VG_BtwCodeVerk                       integer;
  declare @_VG_BtwCodeInk                        integer;
  declare @_VG_VerkoopprijsExcl                  smallint;
  declare @_VG_AdviesprijsExcl                   smallint;
  declare @_VG_VoorraadBijhouden                 smallint;
  declare @_VG_WebArtikel                        smallint;
  declare @_VG_KostprijsWijzigenBijOrderinvoer smallint;

  // Variabelen
  declare @_OpbrGrpGid                        integer;
  declare @_ArtGid                            integer;
  declare @_ArtCbsGcGid                       integer;
  declare @_ArtLndGidCbsOorsprong             integer;
  declare @_ArtTekstGid                       integer;
  declare @_ArtTaalGid                        integer;
  declare @_AutomBerekenen                    integer;
  declare @_ArtBerekenPrijs                   integer;
  declare @_BerekenPrijsMargeIs               integer;
  declare @_ArtKostprijsExOld                 numeric(15,3);
  declare @_ArtPrijsPerOld                    numeric(15,3);
  declare @_ArtVerkprijsIsInclOld             integer;
  declare @_ArtVerkprijsOld                   numeric(15,3);
  declare @_ArtVastPrijsWijzDgbGid            integer;
  declare @_BoekStukNummer                    numeric(10,0);
  declare @_PerNr                             integer;
  declare @_VoorraadEenheid                   nchar(20);
  declare @_BestellenViaDirecteInkoop         smallint;
  declare @_OmschrijvingVerkooporderOvernemen smallint;
  declare @_BestellenVoorDirecteLevering      smallint;
  declare @_MeenemenInBesteladviezen          smallint;
  declare @_KostprijsWijzigenBijOrderinvoer smallint;
  declare @_BtwCodeVerk                       integer;
  declare @_BtwCodeInk                        integer;
  declare @_PrijzenGewijzigd                  smallint;
  declare @_WebArtikelOld                     smallint;
  declare @_Foutnummer                        integer;
  declare @_Foutmelding                       nchar(250);
  declare @_ArtAbcIndeling                    smallint;
  declare @_RcptGid integer default null;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_ToevoegenWijzigen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@ArtikelNummer = ' + @ArtikelNummer);

  if IsModuleActive('wl') <> 0 then

    // ---------------------------------------------------------
    // --- KEUZE TOEVOEGEN OF WIJZIGEN (o.b.v. @ArtikelNummer) -
    // ---------------------------------------------------------
    select ArtGid, ArtKostprijsEx, ArtPrijsPer, ArtVerkprijsIsIncl, ArtVerkprijs, ArtWebArtikel
    into   @_ArtGid, @_ArtKostprijsExOld, @_ArtPrijsPerOld, @_ArtVerkprijsIsInclOld, @_ArtVerkprijsOld, @_WebArtikelOld
    from   tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;

    if @_ArtGid is null then
      // --- Toevoegen
      set @_Mode = _TOEVOEGEN;
    else
      // --- Wijzigen
      set @_Mode = _WIJZIGEN;
    end if;

    if @_Mode = _TOEVOEGEN then
      // Vaste gegevens Artikelen opvragen (Alleen bij toevoegen nieuwe artikelen)
      select  if isnull(ArtVastEenheid,'') = '' then _A('Eenheid') else ArtVastEenheid endif,
              ArtVastBestellenViaDirecteInkoop,
              ArtVastOmsVerkooporderOvernemen,
              ArtVastBestellenVoorDirecteLevering,
              ArtVastIsGebruikVoorBestelAdvies,
              ArtVastDefaultOpbrGrpGId,
              ArtVastDecimalenAantallen,
              ArtVastDecimalenPrijzen,
              ArtVastDefaultBtwCode,
              ArtVastDefaultBtwCodeInkoop,
              ArtVastDefaultVerkoopprijsExcl,
              ArtVastDefaultAdviesprijsExcl,
              ArtVastVoorraadArtikel,
              ArtVastWebArtikel,
              ArtVastIsKostprijsWijzigenInOrder
      into    @_VG_VoorraadEenheid,
              @_VG_BestellenViaDirecteInkoop,
              @_VG_OmschrijvingVerkooporderOvernemen,
              @_VG_BestellenVoorDirecteLevering,
              @_VG_MeenemenInBesteladviezen,
              @_VG_OpbrGrpGId,
              @_VG_AantalDecimalenAantallen,
              @_VG_AantalDecimalenPrijzen,
              @_VG_BtwCodeVerk,
              @_VG_BtwCodeInk,
              @_VG_VerkoopprijsExcl,
              @_VG_AdviesprijsExcl,
              @_VG_VoorraadBijhouden,
              @_VG_WebArtikel,
              @_VG_KostprijsWijzigenBijOrderinvoer
      from tabArtikelVasteGegevens
      where ArtVastSoort = 2;
    end if;

    // Controles
    if IsNull(@ArtikelNummer, '') = '' then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    if @OpbrengstgroepNummer is not null then
      select OpbrGrpGid into @_OpbrGrpGid from tabOpbrengstGroep where OpbrGrpNummer = @OpbrengstgroepNummer;
      if (@_OpbrGrpGid is null) then
        call Raise(20593); //Ongeldige of geen OpbrengstgroepNummer meegegeven!
      end if;
    else
      if @_Mode = _TOEVOEGEN then
        if (@_VG_OpbrGrpGId is null) then
          call Raise(20593); //Ongeldige of geen OpbrengstgroepNummer meegegeven!
        else
          // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
          set @_OpbrGrpGid = @_VG_OpbrGrpGId;
        end if;
      end if;
    end if;

    if IsNull(@CbsGoederencode, '') <> '' then
      select CbsGcGid into @_ArtCbsGcGid from tabCbsGoederenCodes where CbsGcCode = @CbsGoederencode;
      if (@_ArtCbsGcGid is null) then
        call Raise(20607); //Ongeldige of geen CbsGoederencode meegegeven!
      end if;
    end if;

    if IsNull(@CbsLandOorsprong, '') <> '' then
      select first LndGid into @_ArtLndGidCbsOorsprong from tabLand where LndEigenCode = @CbsLandOorsprong;
      if (@_ArtLndGidCbsOorsprong is null) then
        call Raise(20698); // Ongeldige of geen CbsLandOorsprong meegegeven!
      end if;
    end if;

    if @BtwCodeVerkoop is not null then
      select BtwCode into @_BtwCodeVerk from tabBtw where BtwCode = @BtwCodeVerkoop;
      if (@_BtwCodeVerk is null) then
        call Raise(20608); //Ongeldige of geen BtwCodeVerkoop meegegeven!
      end if;
    else
      if @_Mode = _TOEVOEGEN then
        if (@_VG_BtwCodeVerk is null) then
          call Raise(20608); //Ongeldige of geen BtwCodeVerkoop meegegeven!
        else
          // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
          set @_BtwCodeVerk = @_VG_BtwCodeVerk;
        end if;
      end if;
    end if;

    if @BtwCodeInkoop is not null then
      select BtwCode into @_BtwCodeInk from tabBtw where BtwCode = @BtwCodeInkoop;
      if (@_BtwCodeInk is null) then
        call Raise(20645); //Ongeldige of geen BtwCodeInkoop meegegeven!
      end if;
    else
      if @_Mode = _TOEVOEGEN then
        if (@_VG_BtwCodeInk is not null) then
          set @_BtwCodeInk = @_VG_BtwCodeInk;
        end if;
      end if;
    end if;

    // Controle: BestellenViaDirecteInkoop heeft een geldige waarde
    if @BestellenViaDirecteInkoop is not null then
      if @BestellenViaDirecteInkoop not in (0,1) then
        call Raise(20700,'BestellenViaDirecteInkoop');   // (20700) Ongeldige waarde: %1!
      else
        set @_BestellenViaDirecteInkoop = @BestellenViaDirecteInkoop;
      end if;
    else
      if @_Mode = _TOEVOEGEN then
        // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
        set @_BestellenViaDirecteInkoop = @_VG_BestellenViaDirecteInkoop;
      end if;
    end if;

    // Controle: OmschrijvingVerkooporderOvernemen heeft een geldige waarde
    if @OmschrijvingVerkooporderOvernemen is not null then
      if @OmschrijvingVerkooporderOvernemen not in (0,1) then
        call Raise(20700,'OmschrijvingVerkooporderOvernemen');   // (20700) Ongeldige waarde: %1!
       else
        set @_OmschrijvingVerkooporderOvernemen = @OmschrijvingVerkooporderOvernemen;
      end if;
    else
      if @_Mode = _TOEVOEGEN then
        // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
        set @_OmschrijvingVerkooporderOvernemen = @_VG_OmschrijvingVerkooporderOvernemen;
      end if;
    end if;

    // Controle: BestellenVoorDirecteLevering heeft een geldige waarde
    if @BestellenVoorDirecteLevering is not null then
      if @BestellenVoorDirecteLevering not in ('JA','NEE','VOLGENSLEVEENHEID') then
        call Raise(20700,'BestellenVoorDirecteLevering');   // (20700) Ongeldige waarde: %1!
      else
        set @_BestellenVoorDirecteLevering = (select case @BestellenVoorDirecteLevering
                                                          when 'JA'  then 1
                                                          when 'NEE' then 0
                                                          when 'VOLGENSLEVEENHEID' then 2
                                                     end case);
      end if;
    else
      if @_Mode = _TOEVOEGEN then
        // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
        set @_BestellenVoorDirecteLevering = @_VG_BestellenVoorDirecteLevering;
      end if;
    end if;

    if IsNull(@BerekenenPrijs, '') <> '' then
      case @BerekenenPrijs
        when 'NIET'     then set @_AutomBerekenen = 0;
        when 'VASTEGEG' then set @_AutomBerekenen = 1;
        when 'ARTIKEL'  then set @_AutomBerekenen = 2;
        else call Raise(20609); //Ongeldige of geen BerekenenPrijs meegegeven!
      end case;
    end if;

    if IsNull(@BerekenPrijsVan, '') <> '' then
      case @BerekenPrijsVan
        when 'KOSTPRIJS'    then set @_ArtBerekenPrijs = 0;
        when 'VERKOOPPRIJS' then set @_ArtBerekenPrijs = 1;
        else call Raise(20610); //Ongeldige of geen BerekenPrijsVan meegegeven!
      end case;
    end if;

    if IsNull(@BerekenPrijsMargeIsPercentageVan, '') <> '' then
      case @BerekenPrijsMargeIsPercentageVan
        when 'KOSTPRIJS'    then set @_BerekenPrijsMargeIs = 0;
        when 'VERKOOPPRIJS' then set @_BerekenPrijsMargeIs = 1;
        else call Raise(20611); //Ongeldige of geen BerekenPrijsMargeIsPercentageVan meegegeven!
      end case;
    end if;

    if IsNull(@BerekenPrijsPercentage, 0) < 0 then
      call Raise(20642); //Ongeldige of geen BerekenPrijsPercentage meegegeven!
    end if;

    // Controle: MeenemenInBesteladviezen heeft een geldige waarde
    if @MeenemenInBesteladviezen is not null then
      if @MeenemenInBesteladviezen not in (0,1) then
        call Raise(20700,'MeenemenInBesteladviezen');   // (20700) Ongeldige waarde: %1!
       else
        set @_MeenemenInBesteladviezen = @MeenemenInBesteladviezen;
      end if;
    else
      if @_Mode = _TOEVOEGEN then
        // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
        set @_MeenemenInBesteladviezen = @_VG_MeenemenInBesteladviezen;
      end if;
    end if;

    // Controle: KostprijsWijzigenBijOrderinvoer
    if @KostprijsWijzigenBijOrderinvoer is not null then
      if @KostprijsWijzigenBijOrderinvoer not in (0,1) then
        call Raise(20700, 'KostprijsWijzigenBijOrderinvoer');   // (20700) Ongeldige waarde: %1!
       else
        set @_KostprijsWijzigenBijOrderinvoer = @KostprijsWijzigenBijOrderinvoer;
      end if;
    else
      if @_Mode = _TOEVOEGEN then
        //Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
        set @_KostprijsWijzigenBijOrderinvoer = @_VG_KostprijsWijzigenBijOrderinvoer;
      end if;
    end if;

    if IsNull(@WebBestelGrootte, 0) < 0 then
      call Raise(20643); //Ongeldige of geen WebBestelGrootte meegegeven!
    end if;

    if @AantalDecimalenAantallen is null then
      // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
      set @AantalDecimalenAantallen = @_VG_AantalDecimalenAantallen;
    end if;

    if @AantalDecimalenPrijzen is null then
      // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
      set @AantalDecimalenPrijzen = @_VG_AantalDecimalenPrijzen;
    end if;

    if @VerkoopprijsIsInclusiefBtw is null then
      // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
      set @VerkoopprijsIsInclusiefBtw = if @_VG_VerkoopprijsExcl = 1 then 0 else 1 end if;
    end if;

    if @AdviesprijsIsInclusiefBtw is null then
      // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
      set @AdviesprijsIsInclusiefBtw = if @_VG_AdviesprijsExcl = 1 then 0 else 1 end if;
    end if;

    if @VoorraadBijhouden is null then
      // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
      set @VoorraadBijhouden = @_VG_VoorraadBijhouden;
    end if;

    if @WebArtikel is null then
      // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
      set @WebArtikel = @_VG_WebArtikel;
    end if;

    set @_ArtAbcIndeling = 0;
    if IsNull(@AbcIndeling, '') <> '' then
      case @AbcIndeling
        when 'OVERIGE'  then set @_ArtAbcIndeling = 0;
        when 'A'        then set @_ArtAbcIndeling = 1;
        when 'B'        then set @_ArtAbcIndeling = 2;
        when 'C'        then set @_ArtAbcIndeling = 3;
        else call Raise(20680);  //Ongeldige of geen ABC-indeling meegegeven!
      end case;
    end if;

    if isNull(@VoorraadEenheid,'') = '' then
      if @_Mode = _TOEVOEGEN then
        // Gegevens uit vaste gegevens gebruiken bij toevoegen indien niet meegegeven
        set @_VoorraadEenheid = @_VG_VoorraadEenheid;
      end if;
    else
      set @_VoorraadEenheid = @VoorraadEenheid;
    end if;

    //Standaard recept
    if (IsNull(@StandaardReceptCode, '') <> '') and (@_Mode = _WIJZIGEN) then
      select RcptGid into @_RcptGid
      from tabReceptuur
      inner join tabReceptuurEindproduct on (RcpeRcptGid = RcptGid)
      where RcptCode = @StandaardReceptCode
        and RcpeArtGid = @_ArtGid;

      if @_RcptGid is null then
        call Raise(20700,'StandaardReceptCode');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Einde controles

    if @_Mode = _TOEVOEGEN then
      insert into tabArtikel with auto name
      select 2                                   as ArtSoort,
             @ArtikelNummer                      as ArtCode,
             @ZoekCode                           as ArtZoekcode,
             @OmschrijvingKort                   as ArtOms,
             @_OpbrGrpGid                        as ArtOpbrGrpGid,
             @AantalDecimalenAantallen           as ArtAantDecAantallen,
             @AantalDecimalenPrijzen             as ArtAantDecPrijzen,
             @_VoorraadEenheid                   as ArtDefaultVerkoopEenheid,
             @_VoorraadEenheid                   as ArtOmsEenheid,
             @GewichtPer                         as ArtGewichtPer,
             @Gewicht                            as ArtGewicht,
             @VolumePer                          as ArtVolumePer,
             @Volume                             as ArtVolume,
             @_BtwCodeVerk                       as ArtBtwCode,
             @_ArtCbsGcGid                       as ArtCbsGcGid,
             @_ArtLndGidCbsOorsprong             as ArtLndGidCbsOorsprong,
             @_AutomBerekenen                    as ArtBerekenPrijs,
             @_ArtBerekenPrijs                   as ArtBerekenPrijsVan,
             @_BestellenViaDirecteInkoop         as ArtBestellenViaDirecteInkoop,
             @_BerekenPrijsMargeIs               as ArtBerekenPrijsMargeIs,
             @BerekenPrijsPercentage             as ArtBerekenPrijsPerc,
             @GeprijsdPer                        as ArtPrijsPer,
             @_OmschrijvingVerkooporderOvernemen as ArtOmsVerkooporderOvernemen,
             @_BestellenVoorDirecteLevering      as ArtBestellenVoorDirecteLevering,
             @_MeenemenInBesteladviezen          as ArtIsGebruikVoorBestelAdvies,
             @_KostprijsWijzigenBijOrderinvoer as ArtIsKostprijsWijzigenInOrder,
             @Kostprijs                          as ArtKostprijsEx,
             @Verkoopprijs                       as ArtVerkprijs,
             @VerkoopprijsIsInclusiefBtw         as ArtVerkprijsIsIncl,
             @Adviesprijs                        as ArtAdviesPrijs,
             @AdviesprijsIsInclusiefBtw          as ArtIsAdviesPrijsInclBtw,
             @VoorraadBijhouden                  as ArtHeeftVoorraad,
             @GeblokkeerdVoorVerkoop             as ArtIsGeblokkeerd,
             @AfbeeldingKlein                    as ArtAfbeeldingKlein,
             @AfbeeldingGroot                    as ArtAfbeeldingGroot,
             @WebArtikel                         as ArtWebArtikel,
             @WebBestelGrootte                   as ArtWebBestelGrootte,
             @_BtwCodeInk                        as ArtBtwCodeInkoop,
             @GeblokkeerdVoorBestelling          as ArtIsGeblokkeerdInkoop,
             @_ArtAbcIndeling                    as ArtAbcIndeling,
             @Lengte                             as ArtDimensieLengte,
             @Breedte                            as ArtDimensieBreedte,
             @Hoogte                             as ArtDimensieHoogte;

      set @_ArtGid = @@Identity;

      /* Default waarden van vrije rubrieken vullen */
      call VrijeRubriekenVulDefaults('ART', 0, 0, @_ArtGid);

    else // Wijzigen

      set @_PrijzenGewijzigd = 0;
      //Prijzen worden gewijzigd via tabPrijswijzigingsRegel
      if (@_ArtKostprijsExOld <> IsNull(@Kostprijs, @_ArtKostprijsExOld)) or (@_ArtPrijsPerOld <> IsNull(@GeprijsdPer, @_ArtPrijsPerOld)) or
         (@_ArtVerkprijsIsInclOld <> IsNull(@VerkoopprijsIsInclusiefBtw, @_ArtVerkprijsIsInclOld)) or (@_ArtVerkprijsOld <> IsNull(@Verkoopprijs, @_ArtVerkprijsOld)) then
         set @_PrijzenGewijzigd = 1;
      end if;

      //De toe te voegen voorraadeenheid bestaat al als verkoopeenheid.
      if exists(select 1 from tabVerkoopEenheid
                where VkeArtGid = @_ArtGid
                  and VkeVerkoopEenheid = @_VoorraadEenheid
                  and VkeIsVoorraadEenheid  = 0) then
        call Raise(20700, _U('Voorraadeenheid komt al voor als verkoopeenheid voor dit artikel!')); //Ongeldige waarde: <parameter of opmerking>
      end if;

      update tabArtikel
      set    ArtZoekCode = IsNull(@ZoekCode, ArtZoekCode),
             ArtOms = IsNull(@OmschrijvingKort, ArtOms),
             ArtOpbrGrpGid = IsNull(@_OpbrGrpGid, ArtOpbrGrpGid),
             ArtAantDecAantallen = IsNull(@AantalDecimalenAantallen, ArtAantDecAantallen),
             ArtAantDecPrijzen = IsNull(@AantalDecimalenPrijzen, ArtAantDecPrijzen),
             ArtOmsEenheid = IsNull(@_VoorraadEenheid, ArtOmsEenheid),
             ArtGewichtPer = IsNull(@GewichtPer, ArtGewichtPer),
             ArtGewicht = IsNull(@Gewicht, ArtGewicht),
             ArtVolumePer = IsNull(@VolumePer, ArtVolumePer),
             ArtVolume = IsNull(@Volume, ArtVolume),
             ArtBtwCode = IsNull(@_BtwCodeVerk, if @_BtwCodeVerk is null then ArtBtwCode else null endif),
             ArtBtwCodeInkoop = IsNull(@_BtwCodeInk, if @_BtwCodeInk is null then ArtBtwCodeInkoop else null endif),
             ArtCbsGcGid = IsNull(@_ArtCbsGcGid, ArtCbsGcGid),
             ArtLndGidCbsOorsprong = IsNull(@_ArtLndGidCbsOorsprong, ArtLndGidCbsOorsprong),
             ArtBerekenPrijs = IsNull(@_AutomBerekenen, ArtBerekenPrijs),
             ArtBerekenPrijsVan = IsNull(@_ArtBerekenPrijs, ArtBerekenPrijsVan),
             ArtBestellenViaDirecteInkoop = IsNull(@_BestellenViaDirecteInkoop, ArtBestellenViaDirecteInkoop),
             ArtBerekenPrijsMargeIs = IsNull(@_BerekenPrijsMargeIs, ArtBerekenPrijsMargeIs),
             ArtBerekenPrijsPerc = IsNull(@BerekenPrijsPercentage, ArtBerekenPrijsPerc),
             ArtAdviesPrijs = IsNull(@Adviesprijs, ArtAdviesPrijs),
             ArtIsAdviesPrijsInclBtw = IsNull(@AdviesprijsIsInclusiefBtw, ArtIsAdviesPrijsInclBtw),
             ArtOmsVerkooporderOvernemen = IsNull(@_OmschrijvingVerkooporderOvernemen, ArtOmsVerkooporderOvernemen),
             ArtBestellenVoorDirecteLevering = IsNull(@_BestellenVoorDirecteLevering, ArtBestellenVoorDirecteLevering),
             ArtIsGebruikVoorBestelAdvies = IsNull(@_MeenemenInBesteladviezen, ArtIsGebruikVoorBestelAdvies),
             ArtIsKostprijsWijzigenInOrder = isNull(@_KostprijsWijzigenBijOrderinvoer, ArtIsKostprijsWijzigenInOrder),
             ArtHeeftVoorraad = IsNull(@VoorraadBijhouden, ArtHeeftVoorraad),
             ArtIsGeblokkeerd = IsNull(@GeblokkeerdVoorVerkoop, ArtIsGeblokkeerd),
             ArtAfbeeldingKlein = IsNull(@AfbeeldingKlein, ArtAfbeeldingKlein),
             ArtAfbeeldingGroot = IsNull(@AfbeeldingGroot, ArtAfbeeldingGroot),
             ArtWebArtikel = IsNull(@WebArtikel, ArtWebArtikel),
             ArtWebBestelGrootte = IsNull(@WebBestelGrootte, ArtWebBestelGrootte),
             ArtIsGeblokkeerdInkoop = IsNull(@GeblokkeerdVoorBestelling, ArtIsGeblokkeerdInkoop),
             ArtAbcIndeling = IsNull(@_ArtAbcIndeling, ArtAbcIndeling),
             ArtDimensieLengte = IsNull(@Lengte, ArtDimensieLengte),
             ArtDimensieBreedte = IsNull(@Breedte, ArtDimensieBreedte),
             ArtDimensieHoogte = IsNull(@Hoogte, ArtDimensieHoogte),
             ArtRcptGidStandaard = (if @StandaardReceptCode is null then ArtRcptGidStandaard else @_RcptGid endif)
      where  ArtGid = @_ArtGid;

      //Prijzen worden gewijzigd via tabPrijswijzigingsRegel
      if @_PrijzenGewijzigd = 1 then

        //Prijswijzigingskop regel aanmaken als die niet bestaat
        if not exists(select 1 from tabPrijsWijzigingsKop where PwkId = 1) then
          insert into tabPrijsWijzigingsKop(PwkId) values(1);
        end if;
        //Prijswijzigingsregel aanmaken
        if exists(select 1 from tabPrijsWijzigingsRegel where PwrArtGid = @_ArtGid and PwrPwkId = 1) then
          update tabPrijsWijzigingsRegel
          set    PwrIsVerkoopprijsIncl = IsNull(@VerkoopprijsIsInclusiefBtw, PwrIsVerkoopprijsIncl), PwrKostprijs = IsNull(@Kostprijs, PwrKostprijs),
                 PwrPrijsPer = IsNull(@GeprijsdPer, PwrPrijsPer), PwrVerkoopprijs = IsNull(@Verkoopprijs, PwrVerkoopprijs)
          where  PwrArtGid = @_ArtGid and PwrPwkId = 1;
        else
          insert into tabPrijsWijzigingsRegel(PwrPwkId, PwrArtGid, PwrIsVerkoopprijsIncl, PwrKostprijs, PwrPrijsPer, PwrVerkoopprijs)
          values(1, @_ArtGid, @VerkoopprijsIsInclusiefBtw, @Kostprijs, @GeprijsdPer, @Verkoopprijs);
        end if;
      end if;

      // Webartikel vinkje wordt uitgezet
      if (@WebArtikel = 0) and (@_WebArtikelOld = 1) then
        delete tabWebArtikel where WartArtGid = @_ArtGid;
      end if;

    end if;

    if @Omschrijving is not null then
      set @_ArtTaalGid  =(select DefaultTaalgid from tabVastegegevens);
      set @_ArtTekstGid = (select ArtTekstGid from tabArtikelTeksten where ArtTekstArtGid = @_ArtGid and ArtTaalGid = @_ArtTaalGid and ArtTekstDocSoort = 50);
      if @_ArtTekstGid is not null then
        update tabArtikelTeksten set ArtTekst = @Omschrijving where ArtTekstGid = @_ArtTekstGid;
      else
        insert into tabArtikelTeksten(ArtTekstArtGid, ArtTekst, ArtTaalGid, ArtTekstDocSoort)
        values (@_ArtGid, @Omschrijving, @_ArtTaalGid, 50);
      end if;
    end if;

    if @Opmerking is not null then
      set @_ArtTekstGid = (select ArtTekstGid from tabArtikelTeksten where ArtTekstArtGid = @_ArtGid and ArtTekstDocSoort = 90);
      if @_ArtTekstGid is not null then
        update tabArtikelTeksten set ArtTekst = @Opmerking where ArtTekstGid = @_ArtTekstGid;
      else
        insert into tabArtikelTeksten(ArtTekstArtGid, ArtTekst, ArtTekstDocSoort)
        values (@_ArtGid, @Opmerking, 90);
      end if;
    end if;

  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);

end; // atomic


create or replace procedure WebSvcProc_Artikel_Verwijderen(in @ArtikelNummer nchar(20))
begin
  // **********************
  // ***** Variabelen *****
  // **********************
  declare fk_constraint exception for sqlstate '23W05';  -- foreign key constraint violation
  declare @_ArtGid   integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Omschrijving_Verwijderen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  /** Ingangscontroles (licentie, opties, abonnement...)  **/
  if IsModuleActive('wl') = 0 then      // Optie Webservices Logistiek
    call Raise(20790, _U('Optie Webservices Logistiek')); // (20790) '%1!' niet geactiveerd!
  end if;

  select ArtGid into @_ArtGid
  from   tabArtikel
  where  ArtSoort = 2 // 2 = Artikel
         and ArtCode = @ArtikelNummer;

  if (@_ArtGid is null) then
    call Raise(20720, 'ArtikelNummer'); // (20720) %1! niet gevonden!;
  end if;

  //** Verwerking **/
  begin atomic

    // Verwijderen van het artikel
    delete from tabArtikel where ArtGid = @_ArtGid;

    exception
      when fk_constraint  then call Raise(20780, _U('Artikel verwijderen'), _U('Wordt nog gebruikt!')); // (20780) %1! niet mogelijk: %2!.;
      when others         then call Raise(20780, _U('Artikel verwijderen'), _U('Wordt nog gebruikt!')); // (20780) %1! niet mogelijk: %2!.;

  end;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Omschrijving_Verwijderen<';
  //call TraceEind(@@ErrorTextProcedure);
end;

// call RefreshAllUserRights();

create or replace procedure WebSvcProc_Artikel_VolgArtikel_ToevoegenWijzigen(in @ArtikelNummer nchar(20), in @VolgArtikelNummer nchar(20), in @Aantal numeric(15,3))
begin
  declare @ArtVlgMasterArtGid  integer;
  declare @ArtVlgDetailArtGid  integer;
  declare @ArtVlgGid           integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_VolgArtikel_ToevoegenWijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then

  select ArtGid into @ArtVlgMasterArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtVlgMasterArtGid is null) then
      call Raise(20524); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select ArtGid into @ArtVlgDetailArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @VolgArtikelNummer;
    if (@ArtVlgDetailArtGid is null) then
      call Raise(20622); //Ongeldige of geen VolgArtikelNummer meegegeven!
    end if;

    if IsNull(@Aantal, 0) = 0 then
      call Raise(20623); //Ongeldige of geen Aantal meegegeven!
    end if;

    if IsNull((select count() from tabArtikelVervolg where ArtVlgMasterArtGid = @ArtVlgMasterArtGid and ArtVlgDetailArtGid = @ArtVlgDetailArtGid), 0) < 2 then

      select ArtVlgGid into @ArtVlgGid from tabArtikelVervolg where ArtVlgMasterArtGid = @ArtVlgMasterArtGid and ArtVlgDetailArtGid = @ArtVlgDetailArtGid;

      if @ArtVlgGid is null then
        insert into tabArtikelVervolg(ArtVlgMasterArtGid, ArtVlgDetailArtGid, ArtVlgAantal)
        values (@ArtVlgMasterArtGid, @ArtVlgDetailArtGid, @Aantal);

        set @ArtVlgGid = @@Identity;
      else
        update tabArtikelVervolg
        set    ArtVlgAantal = IsNull(@Aantal, ArtVlgAantal)
        where  ArtVlgGid = @ArtVlgGid;
      end if;
    else
      call Raise(20624); //Volgartikel komt meerdere keren voor bij dit artikel!
    end if;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_VolgArtikel_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_VolgArtikel_Verwijderen(in @ArtikelNummer nchar(20), in @VolgArtikelNummer nchar(20))
begin
  declare @ArtVlgMasterArtGid  integer;
  declare @ArtVlgDetailArtGid  integer;
  declare @ArtVlgGid           integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_VolgArtikel_Verwijderen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtVlgMasterArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtVlgMasterArtGid is null) then
      call Raise(20524); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select ArtGid into @ArtVlgDetailArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @VolgArtikelNummer;
    if (@ArtVlgDetailArtGid is null) then
      call Raise(20622); //Ongeldige of geen VolgArtikelNummer meegegeven!
    end if;

    if IsNull((select count() from tabArtikelVervolg where ArtVlgMasterArtGid = @ArtVlgMasterArtGid and ArtVlgDetailArtGid = @ArtVlgDetailArtGid), 0) < 2 then
      select ArtVlgGid into @ArtVlgGid from tabArtikelVervolg where ArtVlgMasterArtGid = @ArtVlgMasterArtGid and ArtVlgDetailArtGid = @ArtVlgDetailArtGid;
      delete tabArtikelVervolg where ArtVlgGid = @ArtVlgGid;
    else
      delete tabArtikelVervolg where ArtVlgMasterArtGid = @ArtVlgMasterArtGid and ArtVlgDetailArtGid = @ArtVlgDetailArtGid;
    end if;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_VolgArtikel_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_VrijeRubriek_Wijzigen(in @ArtikelNummer nchar(20), in @RubriekOmschrijving nchar(40), in @RubriekInhoud nchar(255))
begin
  declare @ArtGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_VrijeRubriek_Wijzigen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  // --- Controle: juiste modules
  if IsModuleActive('wl') = 0 then
    call Raise(20904); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  // --- Controle: Geldig artikel
  select ArtGid  into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
  if (@ArtGid is null) then
    call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
  end if;

  call VrInsertOrReplaceValue('ART', 0, 0, @ArtGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Webwinkel_Toevoegen(in @ArtikelNummer nchar(20), in @WebwinkelID nchar(20))
begin
  declare @ArtGid    integer;
  declare @WscGid    integer;
  declare @WartGid   integer;
  declare @WebArtikel smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Webwinkel_Toevoegen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    select ArtWebArtikel into @WebArtikel from tabArtikel where ArtGid = @ArtGid;
    if IsNull(@WebArtikel, 0) = 0 then
      call Raise(20682);  //Artikel is geen webwinkel artikel!
    end if;

    if IsNull(@WebwinkelID, '') = '' then
      call Raise(20681); //Ongeldige of geen webshop id meegegeven!
    end if;

    select WscGid into @WscGid from tabWebshopConfiguratie where WscWebshopId = @WebwinkelID;
    if IsNull(@WscGid, '') = '' then
      call Raise(20681); //Ongeldige of geen webshop id meegegeven!
    end if;

    select WartGid into @WartGid from tabWebArtikel where WartArtGid = @ArtGid and WartWscGid = @WscGid;
    if @WartGid is null then
      insert into tabWebArtikel(WartArtGid, WartWscGid)
      values (@ArtGid, @WscGid);
    end if;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Webwinkel_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Artikel_Webwinkel_Verwijderen(in @ArtikelNummer nchar(20), in @WebwinkelID nchar(20))
begin
  declare @ArtGid   integer;
  declare @WscGid   integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Webwinkel_Verwijderen > @ArtikelNummer = ' + @ArtikelNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select ArtGid into @ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @ArtikelNummer;
    if (@ArtGid is null) then
      call Raise(20606); //Ongeldige of geen ArtikelNummer meegegeven!
    end if;

    if IsNull(@WebwinkelID, '') = '' then
      call Raise(20681); //Ongeldige of geen webshop id meegegeven!
    end if;

    select WscGid into @WscGid from tabWebshopConfiguratie where WscWebshopId = @WebwinkelID;
    if IsNull(@WscGid, '') = '' then
      call Raise(20681); //Ongeldige of geen webshop id meegegeven!
    end if;

    delete from tabWebArtikel
    where (WartArtGid = @ArtGid) and (WartWscGid = @WscGid)

  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Artikel_Webwinkel_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Boekingsgang_Afsluiten(in @BoekjaarCode nchar(10), in @BoekingsgangNummer numeric(10,0))
begin
  declare @BjGid       integer;
  declare @BoekGangGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Boekingsgang_Afsluiten > @BoekjaarCode = ' + @BoekjaarCode + ', @BoekingsgangNummer = ' + string(@BoekingsgangNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wf') <> 0 then
    select BjGid into @BjGid from tabBoekjaar where Code = @BoekjaarCode;
    if (@BjGid is null) then
      call Raise(20559); //Ongeldige of geen BoekjaarCode meegegeven!
    end if;

    select BoekGangGid into @BoekGangGid from tabBoekingsGang where BoekGangBjGid = @BjGid and BoekGangNummer = @BoekingsgangNummer;
    if (@BoekGangGid is null) then
      call Raise(20560); //Ongeldige of geen BoekingsgangNummer meegegeven!
    end if;

    update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangGid = @BoekGangGid;
    //RVL/TG 10-12-2014: de lock op de boekingsgang wordt gezet in de service BoekingsgangToevoegen. Omdat elke webservice zijn eigen connection id heeft,
    //                   werkt het standaard lockmechanisme bij boekingsgangen niet. Derhalve geven we hem zelf vrij hier.
    //                   nb: ik (TG) liep hier tegenaan bij testen van de services via een testapplicatie. De volgende services werden uitgevoerd:
    //                   boekingsgangToevoegen -> JournaalPostToevoegen -> JournaalregelToevoegen -> BoekingsgangAfsluiten. Vervolgens in een reeds draainde King
    //                   de voorlopige boekingsgang proberen te verwijderen gaf een uitklapper (raise 20040).
    call LockReleaseOnUserName('KingWebservice', 1, 'tabBoekingsGang', 'BoekgangGid='+string(@BoekGangGid));
  else
    call Raise(20902); //Optie ''Webservices Financieel'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Boekingsgang_Afsluiten';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Boekingsgang_Journaalpost_Journaalregel_Toevoegen(
  in @BoekjaarCode nchar(10),
  in @BoekingsgangNummer integer,
  in @JournaalPostNummer integer,
  in @VolgNummer numeric(3,0),
  in @RekeningNummer nchar(28),
  in @Boekdatum date,
  in @Aantal numeric(12,2),
  in @BoekzijdeIsCredit smallint,
  in @ValutaCode nchar(3),
  in @ValutaBedrag numeric(12,2),
  in @Omschrijving nchar(40),
  in @FactuurReferentieNummer nchar(40),
  in @FactuurDatum date,
  in @VervalDatum date,
  in @BetalingsKenmerk nchar(24),
  in @ArchiefStukVolgNummer nchar(20),
  in @ArchiefstukExternId nchar(20),
  in @HulpRekeningSoort nchar(5),
  in @HulpRekeningBtwCode numeric(3,0),
  in @HulpRekeningRekeningNummer nchar(28),
  in @HulpRekeningBoekzijdeIsCredit smallint,
  in @HulpRekeningValutaCode nchar(3),
  in @HulpRekeningValutaBedrag numeric(12,2),
  // projectboekingsvelden, worden alleen gebruikt wanneer @ProjectMutatieProjectCode ongelijk aan null is
  in @ProjectMutatieProjectCode       nchar(10)           default null, // wordt alleen ingevuld als @ProjectMutatieProjectOnderdeel niet ingevuld is
  in @ProjectMutatieProjectOnderdeel  nchar(40)           default null, // indien ingevuld dan wordt deze gebruikt anders @ProjectMutatieProjectCode
  in @ProjectMutatieTariefcode        nchar(20)           default null,
  in @ProjectMutatieOmschrijving      long nvarchar       default null,
  in @ProjectMutatieCategorieen       long nvarchar       default null)

result(JournaalregelNummer integer)

begin
/*
  -- Parameters t.b.v. test -->
  declare @BoekjaarCode                  nchar(10)     = '2020';
  declare @BoekingsgangNummer            integer       = 13;
  declare @JournaalPostNummer            integer       = 1;
  declare @VolgNummer                    numeric(3,0)  = null;
  declare @RekeningNummer                nchar(28)     = '8042';
  declare @Boekdatum                     date          = '2020-05-28';
  declare @Aantal                        numeric(12,2) = 150;
  declare @BoekzijdeIsCredit             smallint      = 1;
  declare @ValutaCode                    nchar(3)      = null;
  declare @ValutaBedrag                  numeric(15,2) = 22.50;
  declare @Omschrijving                  nchar(40)     = 'Test met aantal';
  declare @FactuurReferentieNummer       nchar(40)     = '';
  declare @FactuurDatum                  date          = null;
  declare @VervalDatum                   date          = null;
  declare @BetalingsKenmerk              nchar(24)     = '';
  declare @ArchiefStukVolgNummer         nchar(20)     = null;
  declare @ArchiefstukExternId           nchar(20)     = null;
  declare @HulpRekeningSoort             nchar(5)      = 'BETVS';
  declare @HulpRekeningBtwCode           numeric(3,0)  = 11;
  declare @HulpRekeningRekeningNummer    nchar(28)     = null;
  declare @HulpRekeningBoekzijdeIsCredit smallint      = 1;
  declare @HulpRekeningValutaCode        nchar(3)      = 'EUR';
  declare @HulpRekeningValutaBedrag      numeric(15,2) = 4.00;
  -- Parameters t.b.v. test <--
*/

  declare @BjGid                         integer;
  declare @BoekGangGid                   integer;
  declare @PerGid                        integer;
  declare @PerIsGeblokkeerd              integer;
  declare @BjIsGeblokkeerd               integer;
  declare @JrGid                         integer;
  declare @JrBjGid                       integer;
  declare @JrPerNr                       integer;
  declare @JpPerNr                       integer;
  declare @JpBjGid                       integer;
  declare @JrJpGid                       integer;
  declare @JrRksGid                      integer;
  declare @DagboekSoort                  integer;
  declare @DefaultSoort                  integer;
  declare @RksValNummer                  integer;
  declare @RksBtwCode                    integer;
  declare @IsRksGeblokkeerd              smallint;
  declare @GebruikAantallen              smallint;
  declare @TariefInkoop                  numeric(15,2);
  declare @TariefVerkoop                 numeric(15,2);
  declare @TariefBedrag                  numeric(15,2);
  declare @TariefValutaBedrag            numeric(15,2);
  declare @TariefValutaBtwBedrag         numeric(15,2);
  declare @ValutaBedragIsBerekend        smallint;
  declare @BedragAantal                  numeric(15,2);
  declare @HulpRekRksGid                 integer;
  declare @BtwPercentage                 numeric(6,2);
  declare @BtwSoort                      smallint;
  declare @SoortBerekening               smallint;
  declare @JrHulpRekSoort                integer;
  declare @JpDgbGid                      integer;
  declare @BtwBoeken                     smallint;
  declare @DgbDefBetkenmCred             integer;
  declare @DgbDefBetkenmDeb              integer;
  declare @JrDarGid                      integer;
  declare @JrValNummer                   integer;
  declare @HulpRekValnummer              integer;
  declare @DgbBoekdatumPerJournaalRegel  smallint;
  declare @NawOnsDebiteurNummer          nchar(20);
  declare @JpBoekdatum                   date;
  declare @JrBasisBedrag                 numeric(15,2);
  declare @HulpRekBasisBedrag            numeric(15,2);

  // variabelen om een projectboeking aan een journaalregel te koppelen
  declare @_PbkGid                       integer;
  declare @_PbrGid                       integer;
  declare @_DgbCode                      nchar(10);
  declare @_BoekstukNummer               numeric(10,0);

  set @@ErrorTextProcedure = 'WebSvcProc_Boekingsgang_Journaalpost_Journaalregel_Toevoegen > @BoekjaarCode = ' + @BoekjaarCode + ', @BoekingsgangNummer = ' + string(@BoekingsgangNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wf') <> 0 then
    select BjGid, BjIsGeblokkeerd into @BjGid, @BjIsGeblokkeerd from tabBoekjaar where Code = @BoekjaarCode;
    if (@BjGid is null) then
      call Raise(20559); //Ongeldige of geen BoekjaarCode meegegeven!
    end if;

    select BoekGangGid into @BoekGangGid from tabBoekingsGang where BoekGangBjGid = @BjGid and BoekGangNummer = @BoekingsgangNummer;
    if (@BoekGangGid is null) then
      call Raise(20560); //Ongeldige of geen BoekingsgangNummer meegegeven!
    end if;

    select     JpGid,
               JpDgbGid,
               BoekDatum,
               isnull(BtwBoeken,2),     // 2 = Geen waarde in King, maar geeft aan, dat BTW boeken niet van toepassing is binnen het dagboek ("BTW boeken bij" is leeg)
               DagboekSoort,
               DgbDefBetkenmCred,
               DgbDefBetkenmDeb,
               DgbBoekdatumPerJournaalRegel,
               DgbCode,
               BoekstukNummer
    into       @JrJpGid,
               @JpDgbGid,
               @JpBoekdatum,
               @BtwBoeken,
               @DagboekSoort,
               @DgbDefBetkenmCred,
               @DgbDefBetkenmDeb,
               @DgbBoekdatumPerJournaalRegel,
               @_DgbCode,
               @_BoekstukNummer
    from       tabJournaalPost
    inner join tabDagboek
    on         (DgbGid = JpDgbGid)
    where      JpBoekgangGid = @BoekGangGid
    and        JpNummer = @JournaalpostNummer;
    if (@JrJpGid is null) then
      call Raise(20508); //Ongeldige of geen JournaalpostNummer meegegeven!
    end if;

    if (@Boekdatum is null) or (@DgbBoekdatumPerJournaalRegel = 0) then
      set @Boekdatum = @JpBoekdatum;
    else
      if (@DagboekSoort <> 5 /* Beginbalans*/) then
        call BepaalBoekjaarEnPeriode(@Boekdatum, @JrBjGid, @JrPerNr);
        call BepaalBoekjaarEnPeriode(@JpBoekdatum, @JpBjGid, @JpPerNr);

        if (@DgbBoekdatumPerJournaalRegel = 1) then  //Boekdatum van de journaalregel moet binnen dezelfde periode vallen als die van de journaalpost
          if @JrPerNr <> @JpPerNr then
            call Raise(20575); //Ongeldige BoekDatum meegegeven. Periode van de BoekDatum van de journaalregel komt niet overeen met die van de journaalpost meegegeven!
          end if;
        end if;

        if (@DgbBoekdatumPerJournaalRegel = 2) then  //Boekdatum van de journaalregel moet binnen hetzelfde boekjaar vallen als die van de journaalpost
          if @JrBjGid <> @JpBjGid then
            call Raise(20700, _U('Boekdatum van de journaalregel moet binnen hetzelfde boekjaar vallen als die van de journaalpost')); //(20700) Ongeldige waarde: %1!
          end if;
        end if;
      end if;
    end if;

    set @PerIsGeblokkeerd = 0;

    if (@DagboekSoort <> 5) then
      select PerGid, PerIsGeblokkeerd
        into @PerGid, @PerIsGeblokkeerd
      from tabPeriode
      where @Boekdatum between BeginDatum and EindDatum
        and PerBjGid = @BjGid;

      if (@PerGid is null) then
        call Raise(20576); //Ongeldige of geen Boekdatum meegegeven!
      end if;
    end if;

    if (@BjIsGeblokkeerd = 1) or (@PerIsGeblokkeerd = 1) then
      call Raise(20574); //Boekjaar en/of periode is geblokkeerd!
    end if;

    select    RksGid,
              DefaultSoort,
              RksValNummer,
              RksBtwCode,
              BtwPercentage,
              BtwSoort,
              SoortBerekening,
              GebruikAantallen,
              TariefInkoop,
              TariefVerkoop ,
              IsRksGeblokkeerd
    into      @JrRksGid,
              @DefaultSoort,
              @RksValNummer,
              @RksBtwCode,
              @BtwPercentage,
              @BtwSoort,
              @SoortBerekening,
              @GebruikAantallen,
              @TariefInkoop,
              @TariefVerkoop ,
              @IsRksGeblokkeerd
    from      tabRekeningschema
    left join tabBtw
    on        BtwCode = RksBtwCode
    where     RksInvoer = @RekeningNummer;
    if (@JrRksGid is null) then
      call Raise(20547); //Ongeldige of geen RekeningNummer meegegeven!
    end if;

    if @IsRksGeblokkeerd = 1 then
      call Raise(20700, _U('Grootboekrekening is geblokkeerd voor boeken')); //(20700) Ongeldige waarde: %1!
    end if;

    if @GebruikAantallen = 1 then    // 1 = Rekeningnummer heeft aantallen
       if @DagboekSoort = 2 then     // 2 = Inkoop/Crediteuren dagboek
          set @TariefBedrag = @TariefInkoop * isnull(@Aantal,0);  // Alleen bij Dagboeksoort (2) "Inkoop/Crediteuren dagboek" is TariefInkoop van toepassing.
       else
          set @TariefBedrag = @TariefVerkoop * isnull(@Aantal,0); // Bij overige dagboeksoorten is TariefVerkoop van toepassing.
       end if;
    end if;

    select ValNummer into @JrValNummer from tabValuta where ValCode = @ValutaCode;
    if (@JrValNummer is null) then
      if @GebruikAantallen = 1 then
         set @JrValNummer = @RksValNummer;
      else
        call Raise(20512); //Ongeldige of geen ValutaCode meegegeven!
      end if;
    end if;

    // Als @ValutaBedrag niet is meegegeven en de Grootboekrekening gebruikt aantallen,
    // dan @ValutaBedrag berekenen o.b.v. Tarief vermeld binnen de Grootboekrekening
    set @ValutaBedragIsBerekend = 0;
    if isnull(@ValutaBedrag,0) = 0 and @GebruikAantallen = 1 then
       if isnull(@TariefBedrag,0) <> 0 then
          if @JrValNummer <> @RksValNummer then
             call ValutaOmrekenenProc(@RksValNummer, @TariefBedrag, @JrValNummer, 0, @Boekdatum, 0, @JpDgbGid, 2, @TariefValutaBedrag);
          else
             set @TariefValutaBedrag = @TariefBedrag;
          end if;
          // Bereken de BTW alleen als Rekeningnummer is gekoppeld aan een BTW code en
          // @ValutaCode overeenkomt met de Valuta van de grootboekrekening en
          // @DefaultSoort (uit Rekeningschema) is een Resultaat- (3) of Kosten- (4) of Opbrengstrekening (5) en
          // @BtwBoeken (uit Dagboek) is bij Opbrengsten/Kosten (1)
          if @RksBtwCode is not null and @JrValNummer = @RksValNummer and @DefaultSoort in (3,4,5) and @BtwBoeken = 1 then
             case
               when @SoortBerekening = 1            // 1 = @TariefValutaBedrag is inclusief BTW (BTW er uit halen)
               then set @ValutaBedrag = (@TariefValutaBedrag / (1 + (@BtwPercentage / 100)));
                    set @TariefValutaBtwBedrag = (@TariefValutaBedrag - @ValutaBedrag);
                    set @ValutaBedragIsBerekend = 1;
               when @SoortBerekening = 2            // 2 = @TariefValutaBedrag is exclusief BTW (BTW over berekenen)
               then set @ValutaBedrag = @TariefValutaBedrag;
                    set @TariefValutaBtwBedrag = (@TariefValutaBedrag * (@BtwPercentage / 100));
                    set @ValutaBedragIsBerekend = 1;
               when @BtwPercentage = 0              // Geen BTW berekening van toepassing.
               then set @ValutaBedrag = @TariefValutaBedrag;
                    set @TariefValutaBtwBedrag = 0;
                    set @ValutaBedragIsBerekend = 1;
               else
                    call Raise(20700,_U('Binnen de Btwcode heeft rubriek Incl./Excl. BTW de hier niet toegestane waarde: Geen voorkeur'));   // (20700) Ongeldige waarde: %1!
             end case;
          else
             set @ValutaBedrag = @TariefValutaBedrag;
             set @TariefValutaBtwBedrag = 0;
             set @ValutaBedragIsBerekend = 1;
          end if;
       else
          // Geen @ValutaBedrag meegegeven, @RekeningNummer gebruikt wel aantallen, maar @TariefBedrag is 0,00.
          set @ValutaBedrag = 0;
          set @TariefValutaBtwBedrag = 0;
          set @ValutaBedragIsBerekend = 1;
       end if;
    end if;

    if (@ValutaBedrag is null) then
       call Raise(20700,_U('Ongeldige of geen %1! meegegeven', 'ValutaBedrag'));   // (20700) Ongeldige waarde: %1!
    end if;

    if (@DefaultSoort in (6,7)) and (IsNull(@FactuurReferentieNummer, '')='') then
      call Raise(20577); //Ongeldige of geen FactuurReferentieNummer meegegeven!
    end if;

    if (@BoekzijdeIsCredit is null) then
      call Raise(20538); //Ongeldige of geen BoekzijdeIsCredit meegegeven!
    end if;

    if (@ArchiefStukVolgNummer is not null) and (@ArchiefstukExternId is not null) then
      call Raise(20501); //ArchiefStukVolgNummer en ArchiefstukExternId mogen niet beiden gevuld zijn!
    end if;

    if @ArchiefStukVolgNummer is not null then
      select DarGid into @JrDarGid from tabDigitaalArchief where DarNummer = @ArchiefStukVolgNummer;
    else
      if @ArchiefstukExternId is not null then
        select first DarGid into @JrDarGid from tabDigitaalArchief where DarExternId = @ArchiefstukExternId;
      end if;
    end if;

    //Als er wel een ArchiefStukVolgNummer of externid is meegegeven, maar we kunnen het archiefstuk niet vinden, dan voegen we ook niet de journaalregel toe
    if ((@ArchiefStukVolgNummer is null) and (@ArchiefstukExternId is null)) or (@JrDarGid is not null) then

      if (IsNull(@HulpRekeningSoort, '') <> '') then
         case @HulpRekeningSoort
           when 'BTW'   then set @JrHulpRekSoort = 1;
           when 'BETVS' then set @JrHulpRekSoort = 2;
           when 'KRSVS' then set @JrHulpRekSoort = 3;
           when 'GEEN'  then set @JrHulpRekSoort = null;
           else call Raise(20502); //Ongeldige of geen HulpRekeningSoort meegegeven!
          end case;
      end if;

      // Indien @HulpRekeningSoort niet is meegegeven of 'GEEN' is meegegeven, dan controleren of BTW boeking t.b.v. @Aantal van toepassing is.
      // Grootboekrekening gebruikt aantallen (@GebruikAantallen = 1) en
      // Aan de Grootboekrekening is een BTW code gekoppeld (@RksBtwCode is not null) en
      // @ValutaCode overeenkomt met de Valuta van de grootboekrekening en
      // @DefaultSoort (uit Rekeningschema) is een Resultaat- (3) of Kosten- (4) of Opbrengstrekening (5) en
      // @BtwBoeken (uit Dagboek) is bij Opbrengsten/Kosten (1) en
      // @ValutaBedrag is berekend op basis van vermelde tarief binnen de grootboekrekening (@ValutaBedragIsBerekend = 1)
--      if @JrHulpRekSoort is null and @GebruikAantallen = 1 and @RksBtwCode is not null and @JrValNummer = @RksValNummer and @DefaultSoort in (3,4,5) and @BtwBoeken = 1 and @ValutaBedragIsBerekend = 1  then
      if @GebruikAantallen = 1 and @RksBtwCode is not null and @JrValNummer = @RksValNummer and @DefaultSoort in (3,4,5) and @BtwBoeken = 1 and @ValutaBedragIsBerekend = 1  then
         set @JrHulpRekSoort = 1;
         set @HulpRekValNummer = @RksValNummer;
         set @HulpRekeningBtwCode = @RksBtwCode;
         set @HulpRekeningRekeningNummer = '';
         if @BtwSoort = 1 then                       // 1 = Af te dragen (Verkoop)
            set @HulpRekeningBoekzijdeIsCredit = 1   // 1 = Boekzijde Credit
         else                                        // 2 = Te verrekenen (Inkoop)
            set @HulpRekeningBoekzijdeIsCredit = 0   // 0 = Boekzijde Debet
         end if;
         // Normaal worden opbrengsten credit en kosten debet geboekt evenals de eventuele BTW
         // Mocht dit echter afwijken, dan moet het BTW bedrag negatief aan de andere boekzijde geboekt worden.
         if @HulpRekeningBoekzijdeIsCredit <> @BoekzijdeIsCredit then
            set @HulpRekeningValutaBedrag = (@TariefValutaBtwBedrag * -1);
         else
            set @HulpRekeningValutaBedrag = @TariefValutaBtwBedrag;
         end if;
      end if;

      if (@JrHulpRekSoort is null) then            // HulpRekeningSoort "GEEN" is of niets is meegegeven.
        if (@HulpRekeningBtwCode is not null) then
           call Raise(20701,_U('%1! is niet toegestaan in combinatie met %2! %3!', 'HulpRekeningBtwCode', 'HulpRekeningSoort', 'GEEN'));   // (20701) Ongeldige combinatie: %1!
        end if;
        if (IsNull(@HulpRekeningRekeningNummer, '') <> '') then
--          raiserror 20578; //Ongeldige of geen HulpRekeningRekeningNummer meegegeven!
          call Raise(20701,_U('%1! is niet toegestaan in combinatie met %2! %3!', 'HulpRekeningRekeningNummer', 'HulpRekeningSoort', 'GEEN'));   // (20701) Ongeldige combinatie: %1!
        end if;
        if (@HulpRekeningBoekzijdeIsCredit is not null) then
--          raiserror 20579; //Ongeldige of geen HulpRekeningBoekzijdeIsCredit meegegeven!
          call Raise(20701,_U('%1! is niet toegestaan in combinatie met %2! %3!', 'HulpRekeningBoekzijdeIsCredit', 'HulpRekeningSoort', 'GEEN'));   // (20701) Ongeldige combinatie: %1!
        end if;
        if (IsNull(@HulpRekeningValutaCode, '') <> '') then
--          raiserror 20580; //Ongeldige of geen HulpRekeningValutaCode meegegeven!
          call Raise(20701,_U('%1! is niet toegestaan in combinatie met %2! %3!', 'HulpRekeningValutaCode', 'HulpRekeningSoort', 'GEEN'));   // (20701) Ongeldige combinatie: %1!
        end if;
        if (IsNull(@HulpRekeningValutaBedrag, 0) <> 0) then
--          raiserror 20581; //Ongeldige of geen HulpRekeningValutaBedrag meegegeven!
          call Raise(20701,_U('%1! is niet toegestaan in combinatie met %2! %3!', 'HulpRekeningValutaBedrag', 'HulpRekeningSoort', 'GEEN'));   // (20701) Ongeldige combinatie: %1!
        end if;
      else         // HulpRekeningSoort ongelijk aan "GEEN" is meegegeven
        if (@JrHulpRekSoort <> 1) then                // 1 = "BTW"
          if (@HulpRekeningBtwCode is not null) then
             call Raise(20701,_U('%1! is niet toegestaan in combinatie met %2! en %3!', 'HulpRekeningBtwCode',  'HulpRekeningSoort BETVS', 'KRSVS'));   // (20701) Ongeldige combinatie: %1!
          end if;
        end if;
        if (@JrHulpRekSoort in (2,3)) then            // 2 = BETVS, 3 = KRSVS
          select RksGid into @HulpRekRksGid from tabRekeningschema where RksInvoer = @HulpRekeningRekeningNummer;
          if (@HulpRekRksGid is null) then
            call Raise(20578); //Ongeldige of geen HulpRekeningRekeningNummer meegegeven!
          end if;
        end if;
        if (IsNull(@HulpRekeningBoekzijdeIsCredit,2) not in (0,1))  then
          call Raise(20579); //Ongeldige of geen HulpRekeningBoekzijdeIsCredit meegegeven!
        end if;
        if (@HulpRekeningValutaBedrag is null) then
          call Raise(20581); //Ongeldige of geen HulpRekeningValutaBedrag meegegeven!
        end if;

        //Als hulprekening van het type BTW is, dan zoeken we zelf de bijbehorende grootboekrekening erbij en negeren we de rekening die is meegegeven.
        if (@JrHulpRekSoort = 1) then
          select BtwRksGid into @HulpRekRksGid from tabBtw where BtwCode = @HulpRekeningBtwCode;
          if (@HulpRekRksGid is null) then
            call Raise(20582); //Ongeldige of geen HulpRekeningBtwCode meegegeven!
          end if;
        end if;

        select ValNummer into @HulpRekValNummer from tabValuta where ValCode = @HulpRekeningValutaCode;
        if (@HulpRekValNummer is null) then
             call Raise(20580); //Ongeldige of geen HulpRekeningValutaCode meegegeven!
        end if;
      end if;

      call ValutaOmrekenenProc(@JrValNummer, @ValutaBedrag,             @@BasisValutanummer, 0, @Boekdatum, 0, @JpDgbGid, 2, @JrBasisBedrag);
      call ValutaOmrekenenProc(@JrValNummer, @HulpRekeningValutaBedrag, @@BasisValutanummer, 0, @Boekdatum, 0, @JpDgbGid, 2, @HulpRekBasisBedrag);

      set @Boekdatum    = (select DateTimeConversieVoorWebServices(@Boekdatum, @Boekdatum));
      set @FactuurDatum = (select DateTimeConversieVoorWebServices(@FactuurDatum, @FactuurDatum));
      set @VervalDatum  = (select DateTimeConversieVoorWebServices(@VervalDatum, @VervalDatum));

      if (@DefaultSoort in (6,7)) then        // 6 = Debiteur, 7 = Crediteur
        if @FactuurDatum is null then
          call Raise(20583); //Ongeldige of geen FactuurDatum meegegeven!
        end if;
        if @VervalDatum is null then
          call Raise(20584); //Ongeldige of geen VervalDatum meegegeven!
        end if;
        if @VervalDatum < @FactuurDatum then
          call Raise(20585); //VervalDatum mag niet voor de FactuurDatum liggen!
        end if;
        if @BetalingsKenmerk is null then //Geen betalingskenmerk meegegeven, dan vullen volgens de instelling van het dagboek
          if @DefaultSoort = 6 then
            case @DgbDefBetkenmDeb
              when 0 then set @BetalingsKenmerk = '';
              when 1 then set @BetalingsKenmerk = @RekeningNummer+'/'+@FactuurReferentieNummer;
              when 2 then set @BetalingsKenmerk = @RekeningNummer;
              when 3 then set @BetalingsKenmerk = @FactuurReferentieNummer;
            end case
          else //Crediteur
            select NawOnsDebiteurNummer into @NawOnsDebiteurNummer from tabNawFile inner join tabNaw on (NawGid = NawfilNawGid) where NawFilRksGid = @JrRksGid;
            case @DgbDefBetkenmCred
              when 0 then set @BetalingsKenmerk = '';
              when 1 then set @BetalingsKenmerk = @RekeningNummer+'/'+@FactuurReferentieNummer;
              when 2 then set @BetalingsKenmerk = @RekeningNummer;
              when 3 then set @BetalingsKenmerk = @FactuurReferentieNummer;
              when 4 then set @BetalingsKenmerk = @NawOnsDebiteurNummer+'/'+@FactuurReferentieNummer;
              when 5 then set @BetalingsKenmerk = @NawOnsDebiteurNummer;
            end case
          end if;
        end if;
      else    // DefaultSoort not in (6,7)       6 = Debiteur, 7 = Crediteur
        if (@FactuurDatum is not null) then
          call Raise(20583); //Ongeldige of geen FactuurDatum meegegeven!
        end if;
        if (@VervalDatum is not null) then
          call Raise(20584); //Ongeldige of geen VervalDatum meegegeven!
        end if;
        if (IsNull(@BetalingsKenmerk, '') <> '') then
          call Raise(20586); //Ongeldige of geen BetalingsKenmerk meegegeven!
        end if;
      end if;

      insert into tabJournaalregel( JrJpGid,  StukVolgnr,  JrRksGid,  JrBoekdatum,  IsCreditBoeking,  JrValNummer,  JrValutaBedrag,  OmsJournaalRegel,  JrReferentie,  JrFactuurDatum,
                                    JrVervalDatum,  JrBetalingsKenmerk, Aantal,  JrBasisBedrag,  JrDarGid)
                            values(@JrJpGid, @VolgNummer, @JrRksGid, @Boekdatum, @BoekzijdeIsCredit, @JrValNummer, @ValutaBedrag, IsNull(@Omschrijving, ''), IsNull(@FactuurReferentieNummer, ''), @FactuurDatum,
                                   @VervalDatum, IsNull(@BetalingsKenmerk, ''), IsNull(@Aantal,0), @JrBasisBedrag, @JrDarGid);
      set @JrGid = @@Identity;

      if @JrHulpRekSoort is not null then
        insert into tabHulprekening( HulpRekJrGid, HulpRekSoort,  HulpRekBtwCode,  HulpRekRksGid,  HulpRekIsCredit,  HulpRekValNummer,  HulpRekValutaBedrag,  HulpRekBasisBedrag)
                             values(@JrGid,    @JrHulpRekSoort, @HulpRekeningBtwCode, @HulpRekRksGid, @HulpRekeningBoekzijdeIsCredit, @HulpRekValNummer, @HulpRekeningValutaBedrag, @HulpRekBasisBedrag);
      end if;

      select JrNummer as JournaalregelNummer from tabJournaalregel where JrGid = @JrGid;        // Toon het resultaat (nummer van de eerste volgende journaalregel)
    else
      call Raise(20587); //Archiefstuk niet gevonden!
    end if;

    // projectboeking toevoegen
    if @ProjectMutatieProjectCode is not null then
      call ProjectBoekingsKopToevoegen(
            @PbkOms = @_DgbCode + '/' + Convert(nchar(10), @_BoekstukNummer),
            @PbkHerkomst = 3, /* qcFDV_PbkHerkomst_Gekoppeld_aan_journaal */
            @NieuwPbkGid = @_PbkGid);

      call ProjectBoekingsRegelToevoegenWijzigen(
            @PbkGid = @_PbkGid,
            @Soort =  1, /*= Ov. kosten*/
            @ProjectCode = @ProjectMutatieProjectCode,
            @ProjectOnderdeel = @ProjectMutatieProjectOnderdeel,
            @MutatieDatum = @BoekDatum,
            @ArtikelTarief = @ProjectMutatieTariefcode,
            @Omschrijving = @ProjectMutatieOmschrijving,
            @Categorieen = @ProjectMutatieCategorieen,
            @Kostprijs = if @BoekzijdeIsCredit = 1 then -@JrBasisBedrag else @JrBasisBedrag endif,
            @Status = 1, /*'INGELEVERD'*/
            @NieuwPbrGid = @_PbrGid);

      call JournaalRegelKoppelenAanProjectboekingsRegel(@_PbrGid, @JrGid);
    end if;
  else
    call Raise(20902); //Optie ''Webservices Financieel'' niet geactiveerd!
  end if;

/*--  T.b.v. Debugging
select @JrRksGid,@DefaultSoort,@RksValNummer,@RksBtwCode,@BtwPercentage,@BtwSoort,@SoortBerekening,@GebruikAantallen,@TariefInkoop,@TariefVerkoop,@TariefBedrag,@TariefValutaBedrag,@TariefValutaBtwBedrag;
select @JrJpGid,@JpDgbGid,@JpBoekdatum,@BtwBoeken,@DagboekSoort,@DgbDefBetkenmCred,@DgbDefBetkenmDeb;
select @HulpRekRksGid, @BtwSoort, @SoortBerekening;
select @JrJpGid, @VolgNummer, @JrRksGid, @Boekdatum, @BoekzijdeIsCredit, @JrValNummer, @ValutaBedrag, IsNull(@Omschrijving, ''), IsNull(@FactuurReferentieNummer, ''), @FactuurDatum,
       @VervalDatum, IsNull(@BetalingsKenmerk, ''), IsNull(@Aantal,0), @JrBasisBedrag, @JrDarGid;
select @JrGid,    @JrHulpRekSoort, @HulpRekeningBtwCode, @HulpRekRksGid, @HulpRekeningBoekzijdeIsCredit, @HulpRekValNummer, @HulpRekeningValutaBedrag, @HulpRekBasisBedrag;
*/

  set @@ErrorTextProcedure = 'WebSvcProc_Boekingsgang_Journaalpost_Journaalregel_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Boekingsgang_Journaalpost_Toevoegen(
                                    in @BoekjaarCode nchar(10),
                                    in @BoekingsgangNummer integer,
                                    in @DagboekCode nchar(10),
                                    in @BoekstukDatum date,
                                    in @BoekstukNummer numeric(10,0),
                                    in @Omschrijving nchar(40))
result(JournaalpostNummer integer)
begin
  declare @BoekGangGid      integer;
  declare @BjGid            integer;
  declare @PerGid           integer;
  declare @PerIsGeblokkeerd integer;
  declare @BjIsGeblokkeerd  integer;
  declare @DgbGid           integer;
  declare @DagboekSoort     integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Boekingsgang_Journaalpost_Toevoegen > @BoekjaarCode = ' + @BoekjaarCode + ', @BoekingsgangNummer = ' + string(@BoekingsgangNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wf') <> 0 then
    set @BoekstukDatum = (select DateTimeConversieVoorWebServices(@BoekstukDatum, @BoekstukDatum));

    select BjGid, BjIsGeblokkeerd into @BjGid, @BjIsGeblokkeerd from tabBoekjaar where Code = @BoekjaarCode;
    if (@BjGid is null) then
      call Raise(20559); //Ongeldige of geen BoekjaarCode meegegeven!
    end if;

    select BoekGangGid into @BoekGangGid from tabBoekingsGang where BoekGangBjGid = @BjGid and BoekGangNummer = @BoekingsgangNummer;
    if (@BoekGangGid is null) then
      call Raise(20560); //Ongeldige of geen BoekingsgangNummer meegegeven!
    end if;

    select DgbGid, DagboekSoort into @DgbGid, @DagboekSoort from tabDagboek where DgbCode = @DagboekCode;
    if (@DgbGid is null) then
      call Raise(20572); //Ongeldige of geen DagboekCode meegegeven!
    end if;

    set @PerIsGeblokkeerd = 0;
    if (@DagboekSoort <> 5) then
      select PerGid, PerIsGeblokkeerd into @PerGid, @PerIsGeblokkeerd from tabPeriode where @BoekstukDatum between BeginDatum and EindDatum and PerBjGid = @BjGid;
      if (@PerGid is null) then
        call Raise(20573); //Ongeldige of geen BoekstukDatum meegegeven!
      end if;
    end if;

    if (@BjIsGeblokkeerd = 1) or (@PerIsGeblokkeerd = 1) then
      call Raise(20574); //Boekjaar en/of periode is geblokkeerd!
    end if;

    if (@BoekstukDatum is null) then
      call Raise(20573); //Ongeldige of geen BoekstukDatum meegegeven!
    end if;

    if @BoekstukNummer is null then
      call BoekstuknummerGenereren(@BjGid, @DgbGid,  @BoekstukNummer);
    end if;

    insert into tabJournaalpost(JpBjGid,  JpBoekGangGid, JpDgbGid, Boekdatum,  BoekstukNummer,  OmsJournaalPost)
                         values(@BjGid,  @BoekGangGid,  @DgbGid,  @BoekstukDatum, @BoekstukNummer, @Omschrijving);

    select JpNummer as JournaalpostNummer from tabJournaalpost where JpGid = @@Identity;
  else
    call Raise(20902); //Optie ''Webservices Financieel'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Boekingsgang_Journaalpost_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Boekingsgang_Journaalpost_Verwijderen(in @BoekjaarCode nchar(10), in @BoekingsgangNummer integer, in @JournaalpostNummer integer)
begin
  declare @BjGid                 integer;
  declare @BjIsGeblokkeerd       integer;
  declare @PerIsGeblokkeerd      integer;
  declare @BoekgangGid           integer;
  declare @IsBoekGangDefinitief  integer;
  declare @JpGid                 integer;
  declare @BoekstukDatum         date;
  declare @DgbGid                integer;
  declare @DagboekSoort          integer;
  declare @Result                integer;

  //call TraceBegin('WebSvcProc_Boekingsgang_Journaalpost_Verwijderen > @BoekjaarCode = ' + @BoekjaarCode + ', @BoekingsgangNummer = ' + string(@BoekingsgangNummer));

  if IsModuleActive('wf') <> 0 then
    select BjGid, BjIsGeblokkeerd into @BjGid, @BjIsGeblokkeerd from tabBoekjaar where Code = @BoekjaarCode;
    if (@BjGid is null) then
      call Raise(20559); //Ongeldige of geen BoekjaarCode meegegeven!
    end if;

    select BoekGangGid, IsBoekGangDefinitief into @BoekGangGid, @IsBoekGangDefinitief from tabBoekingsGang where BoekGangBjGid = @BjGid and BoekGangNummer = @BoekingsgangNummer;
    if (@BoekGangGid is null) then
      call Raise(20560); //Ongeldige of geen BoekingsgangNummer meegegeven!
    end if;

    if @IsBoekGangDefinitief = 1 then
      call Raise(20666); //Journaalpost kan niet worden verwijderd uit een definitieve boekingsgang!
    end if;

    select JpGid, BoekDatum, DgbGid, DagboekSoort into @JpGid, @BoekstukDatum, @DgbGid, @DagboekSoort from tabJournaalPost inner join tabDagboek on (DgbGid = JpDgbGid) where JpBoekgangGid = @BoekGangGid and JpNummer = @JournaalpostNummer;
    if (@JpGid is null) then
      call Raise(20508); //Ongeldige of geen JournaalpostNummer meegegeven!
    end if;

    set @PerIsGeblokkeerd = 0;
    if (@DagboekSoort <> 5) then
      select PerIsGeblokkeerd into @PerIsGeblokkeerd from tabPeriode where @BoekstukDatum between BeginDatum and EindDatum and PerBjGid = @BjGid;
    end if;

    if (@BjIsGeblokkeerd = 1) or (@PerIsGeblokkeerd = 1) then
      call Raise(20574); //Boekjaar en/of periode is geblokkeerd!
    end if;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabBoekingsGang', 'BoekGangGid='+string(@BoekGangGid)) = 0 then  //Als de boekingsgang nog niet in gebruik is genomen, dan eerst locken
      set @Result = BoekingsGangInGebruikNemen(@BoekGangGid);
      if @Result <> 0 then
        call Raise(20667); //Boekingsgang is in gebruik!
      end if;
    end if;

    update tabJournaalpost set JpIsInGebruik = 1 where JpBoekGangGid = @BoekGangGid and JpIsInGebruik = 0;

    //ACW 16-02-2017 Deze mag natuurlijk niet zelf he, dat gebeurt al bij het in gebruik nemen van de journaalpost!
    //call JournaalpostOpenenOfSluiten(1, @BjGid, @BoekgangGid, @JpGid, @JournaalpostNummer, @DgbGid);

    delete tabJournaalpost where JpGid = @JpGid;

    update tabBoekingsgang set BoekGangInGebruik = 0 where BoekGangGid = @BoekGangGid;

  else
    call Raise(20902); //Optie ''Webservices Financieel'' niet geactiveerd!
  end if;

  //call TraceEind('WebSvcProc_Boekingsgang_Journaalpost_Verwijderen');
end;


create or replace procedure WebSvcProc_Boekingsgang_Toevoegen(in @BoekjaarCode nchar(10), in @Gebruiker nchar(40), in @Omschrijving nchar(40), in @BoekingsgangIsDefinitief smallint)
result(BoekingsgangNummer integer)
begin
  declare @BjGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Boekingsgang_Toevoegen > @BoekjaarCode = ' + @BoekjaarCode;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wf') <> 0 then
    if IsNull(@Omschrijving, '') = '' then
	   set @Omschrijving = 'KingWebservice';
	end if;

    select BjGid into @BjGid from tabBoekjaar where Code = @BoekjaarCode;
    if (@BjGid is null) then
      call Raise(20559);  //Ongeldige of geen BoekjaarCode meegegeven!
    end if;

    insert into tabBoekingsGang(BoekGangBjGid, BoekGangGebruikersnaam, BoekGangBronId, BronOms, IsBoekGangDefinitief)
                         values(@BjGid, @Gebruiker, 36, @Omschrijving, @BoekingsgangIsDefinitief);

    select BoekGangNummer as BoekingsgangNummer from tabBoekingsGang where BoekGangGid = @@Identity;
  else
    call Raise(20902); //Optie ''Webservices Financieel'' niet geactiveerd!;
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Boekingsgang_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Crediteur_Adres_ToevoegenWijzigen(in @CrediteurNummer nchar(10), in @ContactPersoonNummer numeric(3,0), in @AdresCode nchar(4), in @Omschrijving nchar(40), in @Naam1 nchar(40),
                                                                         in @Naam2 nchar(40), in @Straat nchar(40), in @HuisNummer nchar(10), in @PostCode nchar(40), in @Plaats nchar(40), in @EMail nchar(80),
                                                                         in @LandCode nchar(3), in @Telefoon1 nchar(25), in @Telefoon2 nchar(25), in @Telefax nchar(40), in @EanCode nchar(13), in @Opmerking long nvarchar)
result(AdresCode nchar(3))
begin
  declare @FonGid     integer;
  declare @AdrGid     integer;
  declare @NawGid     integer;
  declare @AdrLndGid  integer;
  declare @RelGid     integer;
  declare @TempNawGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_Adres_ToevoegenWijzigen > @CrediteurNummer = ' + @CrediteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  // Eerst alle velden trimmen, anders komen ze met naloopspaties in de database!
  set @CrediteurNummer      = trim(@CrediteurNummer      );
  set @ContactPersoonNummer = trim(@ContactPersoonNummer );
  set @AdresCode            = trim(@AdresCode            );
  set @Omschrijving         = trim(@Omschrijving         );
  set @Naam1                = trim(@Naam1                );
  set @Naam2                = trim(@Naam2                );
  set @Straat               = trim(@Straat               );
  set @HuisNummer           = trim(@HuisNummer           );
  set @PostCode             = trim(@PostCode             );
  set @Plaats               = trim(@Plaats               );
  set @EMail                = trim(@EMail                );
  set @LandCode             = trim(@LandCode             );
  set @Telefoon1            = trim(@Telefoon1            );
  set @Telefoon2            = trim(@Telefoon2            );
  set @Telefax              = trim(@Telefax              );
  set @EanCode              = trim(@EanCode              );
  set @Opmerking            = trim(@Opmerking            );

  if IsModuleActive('we') <> 0 then
    select FonGid into @FonGid from tabFileOfNaw where FonId = 'C';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @CrediteurNummer;
    if (@NawGid is null) then
      call Raise(20571); //Ongeldige of geen CrediteurNummer meegegeven!
    end if;

    if @ContactPersoonNummer is not null then
      select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
      if (@RelGid is null) then
        call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
      end if;
    end if;

    if IsNull(@LandCode, '') <> '' then
      select LndGid into @AdrLndGid  from tabLand where LndEigenCode = @LandCode;
      if (@AdrLndGid is null) then
        call Raise(20553); //Ongeldige of geen LandCode meegegeven!
      end if;
    end if;

    if (@RelGid is not null) and (@AdresCode in ('COR', 'VEST')) then
      call Raise(20556); //Er kan geen ContactPersoonNummer worden meegegeven aan een vestigings- of correspondentie adres
    end if;

    case @AdresCode
      when 'COR' then
      begin
        set @AdresCode    = null;
        set @Omschrijving = _A('Correspondentieadres');

        //Eerst controleren of vestigingsadres gelijk is aan correspondentie adres. Zo ja, dan een apart adres aanmaken voor correspondentie adres
        select NawGid, NawGidCorrespondentie into @TempNawGid, @AdrGid from tabNaw where NawGid = @NawGid and NawGidCorrespondentie = NawGidVestiging;
        if @TempNawGid is not null then      //Als TempNawGid gevuld is, dan is ie altijd gelijk aan @NawGid. Verderop weer gebruik maken van @NawGid
          insert into tabAdres with auto name
          select AdrNawGid, AdrCode, AdrOms, AdrNaam1, AdrNaam2, AdrStraat, AdrHuisnummer, AdrPostcode, AdrPlaats,
                 AdrTelefoon, AdrTelefax, AdrEmail, AdrLndGID, AdrEanCode, AdrTelefoon2 from tabAdres where AdrGid = @AdrGid;
          set @AdrGid = @@Identity;
          update tabNaw set NawGidCorrespondentie = @AdrGid where NawGid = @NawGid;
        else
          select NawGidCorrespondentie into @AdrGid from tabNaw where NawGid = @NawGid;
        end if;
      end;

      when 'VEST' then
      begin
        set @AdresCode    = null;
        set @Omschrijving = _A('Vestigingsadres');
        select NawGidVestiging into @AdrGid from tabNaw where NawGid = @NawGid;
      end;

      else
        //Als er geen AdresCode is meegegeven, dan genereren we een adrescode voor dit verzendadres
        if IsNull(@AdresCode, '') = '' then
          // Hier kijken of er een adres is met precies dezelfde inhoud (Alleen controleren op meegegeven velden!)
          select first AdrGid, AdrCode into @AdrGid, @AdresCode from tabAdres
          where AdrNawGid = @NawGid
             and AdrGid <> (select NawGidCorrespondentie from tabNaw where nawgid = @NawGid)
             and AdrGid <> (select NawGidVestiging from tabNaw where nawgid = @NawGid)
             //and (AdrCode               = isnull(@AdresCode   , AdrCode       ) )
             and (isnull(AdrRelGid, -1) = isnull(@RelGid      , AdrRelGid, -1 ) )
             and (AdrOms                = isnull(@Omschrijving, AdrOms        ) )
             and (AdrNaam1              = isnull(@Naam1       , AdrNaam1      ) )
             and (AdrNaam2              = isnull(@Naam2       , AdrNaam2      ) )
             and (AdrStraat             = isnull(@Straat      , AdrStraat     ) )
             and (AdrHuisnummer         = isnull(@HuisNummer  , AdrHuisnummer ) )
             and (AdrPostCode           = isnull(@PostCode    , AdrPostCode   ) )
             and (AdrPlaats             = isnull(@Plaats      , AdrPlaats     ) )
             and (AdrTelefoon           = isnull(@Telefoon1   , AdrTelefoon   ) )
             and (AdrTelefax            = isnull(@Telefax     , AdrTelefax    ) )
             and (AdrEmail              = isnull(@EMail       , AdrEmail      ) )
             and (isnull(AdrLndGID, -1) = isnull(@AdrLndGid   , AdrLndGID, -1 ) )
             and (AdrEanCode            = isnull(@EanCode     , AdrEanCode    ) )
             and (AdrTelefoon2          = isnull(@Telefoon2   , AdrTelefoon2  ) ) ;
          if @AdrGid is null then
            set @AdresCode = IsNull((select max(AdrCode) from tabAdres where AdrNawGid = @NawGid), 0)+1;
            if length(@AdresCode) > 3 then
              call Raise(20557); //Er kan geen nieuwe AdresCode worden gegenereerd, de hoogste gebruikte AdresCode is 999!
            end if;
          end if;
        end if;
        select AdrGid into @AdrGid from tabAdres where AdrNawGid = @NawGid and AdrCode = @AdresCode;
    end case;

    if @AdrGid is null then
      insert into tabAdres (AdrNawGid, AdrCode, AdrRelGid, AdrOms, AdrNaam1, AdrNaam2, AdrStraat, AdrHuisnummer, AdrPostCode, AdrPlaats,
                            AdrTelefoon, AdrTelefax, AdrEmail, AdrLndGID, AdrEanCode,
                            AdrTelefoon2)
                values     (@NawGid, @AdresCode, @RelGid, @Omschrijving, @Naam1, @Naam2, @Straat, @HuisNummer,
                            @PostCode, @Plaats, @Telefoon1, @Telefax, @EMail, @AdrLndGid, @EanCode,
                            @Telefoon2);
      set @AdrGid = @@Identity;

      if IsNull(@Opmerking, '') <> '' then
        insert into tabAdresOpmerkingen(AdrOpmAdrGid, AdrOpmOpmerking)
        values (@AdrGid, @Opmerking);
      end if;

    else
      update tabAdres set AdrOms = IsNull(@Omschrijving, AdrOms), AdrNaam1 = IsNull(@Naam1, AdrNaam1), AdrNaam2 = IsNull(@Naam2, AdrNaam2), AdrStraat = IsNull(@Straat, AdrStraat),
                          AdrHuisnummer = IsNull(@HuisNummer, AdrHuisnummer), AdrPostcode = IsNull(@PostCode, AdrPostcode), AdrPlaats = IsNull(@Plaats, AdrPlaats),
                          AdrTelefoon = IsNull(@Telefoon1, AdrTelefoon), AdrTelefax = IsNull(@Telefax, AdrTelefax), AdrEmail = IsNull(@EMail, AdrEmail),
                          AdrEanCode = IsNull(@EanCode, AdrEanCode), AdrTelefoon2 = IsNull(@Telefoon2, AdrTelefoon2),
                          AdrLndGid = IsNull(@AdrLndGid, if @LandCode is null then AdrLndGid else null endif),
                          AdrRelGid = IsNull(@RelGid, if @ContactPersoonNummer is null then AdrRelGid else null endif)
      where AdrGid = @AdrGid;

      if @Opmerking is not null then
        if exists(select 1 from tabAdresOpmerkingen where AdrOpmAdrGid = @AdrGid) then
          update tabAdresOpmerkingen set AdrOpmOpmerking = @Opmerking where AdrOpmAdrGid = @AdrGid;
        else
          insert into tabAdresOpmerkingen(AdrOpmAdrGid, AdrOpmOpmerking)
          values (@AdrGid, @Opmerking);
        end if;
      end if;
    end if;

    if (@AdresCode is not null) then  //Alleen adrescode teruggeven als we een verzend/besteladres teruggeven. Dus niet bij vest- of corr. adres
      select right('000'+string(AdrCode), 3) as AdresCode from tabAdres where AdrGid = @AdrGid;
    end if;
  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_Adres_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Crediteur_Adres_VrijeRubriek_Wijzigen(in @CrediteurNummer nchar(10), in @AdresCode nchar(4), in @RubriekOmschrijving nchar(40), in @RubriekInhoud nchar(255))
begin
  declare @FonGid        integer;
  declare @NawGid        integer;
  declare @AdrGid        integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_Adres_VrijeRubriek_Wijzigen > @CrediteurNummer = ' + @CrediteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select FonGid into @FonGid from tabFileOfNaw where FonId = 'C';

  select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @CrediteurNummer;
  if (@NawGid is null) then
    call Raise(20571); //Ongeldige of geen CrediteurNummer meegegeven!
  end if;

  select AdrGid into @AdrGid from tabAdres where AdrNawGid = @NawGid and AdrCode = @AdresCode;
  if (@AdrGid is null) then
    call Raise(20558); //Ongeldige of geen AdresCode meegegeven!
  end if;

  call VrInsertOrReplaceValue('ADR', @FonGid, @FonGid, @AdrGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_Adres_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Crediteur_BankRekening_Toevoegen(in @CrediteurNummer nchar(10), in @BankRekeningNummer nchar(34), in @BankNaam  nchar(70), in @BankAdres nchar(70),
                                                                        in @BankPostCode nchar(70), in @BankPlaats nchar(70), in @BankLandCode nchar(3), in @BankBic nchar(11), in @RekeningHouderNaam nchar(70),
                                                                        in @RekeningHouderAdres nchar(70), in @RekeningHouderPostCode nchar(70), in @RekeningHouderPlaats nchar(70), in @RekeningHouderLandCode nchar(3),
                                                                        in @Opmerking long nvarchar, in @DefaultBankRekening smallint, in @DefaultBankRekeningBetaling smallint)
begin
  declare @NawGid                integer;
  declare @NawFilFonGid          integer;
  declare @NawRekBankLndGid      integer;
  declare @NawRekLndGidRekHouder integer;
  declare @NawRekGid             integer;
  declare @NawRekSoort           nchar(3);

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_BankRekening_Toevoegen > @CrediteurNummer = ' + @CrediteurNummer+', @BankRekeningNummer = ' + @BankRekeningNummer + ', @RekeningHouderNaam = ' + @RekeningHouderNaam;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid into @NawFilFonGid from tabFileOfNaw where FonId = 'C';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @CrediteurNummer;
    if (@NawGid is null) then
      call Raise(20571); //Ongeldige of geen CrediteurNummer meegegeven!
    end if;

    if IsNull(@BankRekeningNummer, '') = '' then
      call Raise(20561); //Ongeldige of geen BankRekeningNummer meegegeven!
    end if;

    select NawRekGid into @NawRekGid from tabNawRekening where NawRekNawGid = @NawGid and NawRekBankRekeningInvoer = @BankRekeningNummer;
    if (@NawRekGid is not null) then
      call Raise(20562); //BankRekeningNummer bestaat al!
    end if;

    if IsNull(@BankLandCode, '') <> '' then
      select LndGid into @NawRekBankLndGid  from tabLand where LndEigenCode = @BankLandCode;
      if (@NawRekBankLndGid is null) then
        call Raise(20563); //Ongeldige of geen BankLandCode meegegeven!
      end if;
    end if;

    if IsNull(@RekeningHouderLandCode, '') <> '' then
      select LndGid into @NawRekLndGidRekHouder  from tabLand where LndEigenCode = @RekeningHouderLandCode;
      if (@NawRekLndGidRekHouder is null) then
        call Raise(20564); //Ongeldige of geen RekeningHouderLandCode meegegeven!
      end if;
    end if;

    if IsNull(@DefaultBankRekening, 0) in (0,1) then
      if IsNull(@DefaultBankRekening, 0) = 1 then
        set @NawRekSoort = @NawRekSoort + 'D';
      end if;
    else
      call Raise(20637); //Ongeldige of geen DefaultBankRekening meegegeven!
    end if;

    if IsNull(@DefaultBankRekeningBetaling, 0) in (0,1) then
      if IsNull(@DefaultBankRekeningBetaling, 0) = 1 then
        set @NawRekSoort = @NawRekSoort + 'B';
      end if;
    else
      call Raise(20639); //Ongeldige of geen DefaultBankRekeningBetaling meegegeven!
    end if;

    insert into tabNawRekening(NawRekNawGid, NawRekBankRekeningInvoer, NawRekBankNaam , NawRekBankAdres, NawRekBankPostcode, NawRekBankPlaats, NawRekBankLndGid, NawRekSoort, NawRekBankBIC,
                               NawRekNaamRekHouder, NawRekAdresRekHouder, NawRekPostcodeRekHouder, NawRekPlaatsRekHouder, NawRekLndGidRekHouder, NawRekOpmerking)
                        values(@NawGid, @BankRekeningNummer, @BankNaam , @BankAdres, @BankPostCode, @BankPlaats, @NawRekBankLndGid, @NawRekSoort, @BankBic,
                               @RekeningHouderNaam, @RekeningHouderAdres, @RekeningHouderPostCode, @RekeningHouderPlaats, @NawRekLndGidRekHouder, @Opmerking);
  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_BankRekening_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Crediteur_BankRekening_Verwijderen(in @CrediteurNummer nchar(10), in @BankRekeningNummer nchar(34))
begin
  declare @NawGid       integer;
  declare @NawFilFonGid integer;
  declare @NawRekGid    integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_BankRekening_Verwijderen > @CrediteurNummer = ' + @CrediteurNummer+', @BankRekeningNummer = ' + @BankRekeningNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid into @NawFilFonGid from tabFileOfNaw where FonId = 'C';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @CrediteurNummer;
    if (@NawGid is null) then
      call Raise(20571); //Ongeldige of geen CrediteurNummer meegegeven!
    end if;

    select NawRekGid into @NawRekGid from tabNawRekening where NawRekNawGid = @NawGid and NawRekBankRekening = @BankRekeningNummer;
    if (@NawRekGid is null) then
      call Raise(20561); //Ongeldige of geen BankRekeningNummer meegegeven!
    end if;

    delete tabNawRekening where NawRekGid = @NawRekGid;

  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_BankRekening_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Crediteur_ContactPersoon_Functie_ToevoegenWijzigen(in @CrediteurNummer nchar(10), in @ContactPersoonNummer numeric(3,0), in @FunctieNummer numeric(3,0), in @VoorkeurContactPersoonVoorFunctie smallint)
begin
  declare @NawGid       integer;
  declare @RelGid       integer;
  declare @RelFnCode    integer;
  declare @NawFilFonGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_ContactPersoon_Functie_ToevoegenWijzigen > @CrediteurNummer = ' + @CrediteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid into @NawFilFonGid from tabFileOfNaw where FonId = 'C';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @CrediteurNummer;
    if (@NawGid is null) then
      call Raise(20571); //Ongeldige of geen CrediteurNummer meegegeven!
    end if;

    select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
    if (@RelGid is null) then
      call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
    end if;

    select FnCode into @RelFnCode from tabFunctieContact where FnCode = @FunctieNummer;
    if (@RelFnCode is null) then
      call Raise(20565); //Ongeldige of geen FunctieNummer meegegeven!
    end if;

    if exists(select 1 from tabRelatieFunctie where FnRelGid = @RelGid and RelFnCode = @RelFnCode) then
      update tabRelatieFunctie set IsBelangrijkste = @VoorkeurContactPersoonVoorFunctie where FnRelGid = @RelGid and RelFnCode = @RelFnCode;
    else
      insert into tabRelatieFunctie(FnRelGid, RelFnCode, IsBelangrijkste) values (@RelGid, @RelFnCode, @VoorkeurContactPersoonVoorFunctie);
    end if;

  else
    call Raise(20901); //Optie ''Webservice NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_ContactPersoon_Functie_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


