create or replace procedure WebSvcProc_Crediteur_ContactPersoon_SelectieCode_Toevoegen(in @CrediteurNummer nchar(10), in @ContactPersoonNummer numeric(3,0), in @SelectieCode nchar(3))
begin
  declare @NawGid       integer;
  declare @RelGid       integer;
  declare @SltGid       integer;
  declare @NawFilFonGid integer;
  declare @SlcGid       integer;
  declare @SprGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_ContactPersoon_SelectieCode_Toevoegen > @CrediteurNummer = ' + @CrediteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid, FonSltGid into @NawFilFonGid, @SltGid from tabFileOfNaw where FonId = 'C';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @CrediteurNummer;
    if (@NawGid is null) then
      call Raise(20571); //Ongeldige of geen CrediteurNummer meegegeven!
    end if;

    select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
    if (@RelGid is null) then
      call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
    end if;

    if (@SltGid is null) then
      call Raise(20566); //Geen selectiecodetabel ingevuld bij dit type NAW!
    end if;

    select SlcGid into @SlcGid from tabSelectiecodes where SlcCode = @SelectieCode and SlcSltGid = @SltGid;
    if (@SlcGid is null) then
      call Raise(20567); //Ongeldige of geen SelectieCode meegegeven!
    end if;

    select SprGid into @SprGid from tabSlcPerRelatie where SprSlcGid = @SlcGid and SprRelGid = @RelGid;
    if (@SprGid is null) then
      insert into tabSlcPerRelatie(SprRelGid, SprSlcGid) select @RelGid, @SlcGid;
      set @SprGid = @@Identity;
    end if;

  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_ContactPersoon_SelectieCode_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


