    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  call WebSvcHulpProc_VrijeRubriek_ToevoegenWijzigen(
    'NAW', //@VrBestandOms
    2, //@VrGroepID
    2, //@VrSubGroepId
    @Omschrijving,
    @Type,
    @Hint,
    @Verplicht,
    @Uniek,
    @Lengte,
    @Decimalen,
    @Keuzelijst,
    @Defaultwaarde,
    @Sjabloon,
    @Groep,
    @DefaultDatum,
    @DefaultTijd,
    @OpVerkoopDocument
  );

  //call trace('Einde WebSvcProc_Crediteur_Onderhoud_VrijeRubriek_ToevoegenWijzigen');
