  in @KvkNummer nchar(40),
  in @DefaultTegenrekening nchar(28),
  in @ControleerFormaatEanCode smallint default 1, // indien 1, dan wordt er gecontroleerd of eancode voldoet aan het ucc-13 formaat
  in @WebSite nchar(250) default null
)

result(CrediteurNummer nchar(10))

begin
  //Constanten
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  //Variabelen
  declare @_FonGid integer;
  declare @_NawGid integer = null;
  declare @_LndGid integer;
  declare @_TaalGid integer;
  declare @_ValNummer integer;
  declare @_BtcNummer integer;
  declare @_LvcNummer integer;
  declare @_NawBtwCode integer;
  declare @_KredietLimiet numeric(15,2);
  declare @_TegenRksGid integer;
  declare @_Toevoegen smallint = _qcJA;
  declare @_ParIsAkkoord integer;

  //call TraceBegin('WebSvcProc_Crediteur_ToevoegenWijzigen > @CrediteurNummer = ' + @CrediteurNummer+', @ZoekCode = ' + @ZoekCode + ', @ValutaCode = ' + @ValutaCode);

  if IsModuleActive('we') = _qcNEE then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select FonGid into @_FonGid from tabFileOfNaw where FonId = 'C';

  if IsNull(@CrediteurNummer, '') <> '' then
    if (RegExp_Substr(@CrediteurNummer, '\D') is not null) then   //Mogen allen maar cijfers zijn
      call Raise(20571); //Ongeldige of geen CrediteurNummer meegegeven!
    end if;

    select NawFilNawGid into @_NawGid from tabNawFile where NawFilFonGid = @_FonGid and NawFilNummer = @CrediteurNummer;

    set @_Toevoegen = if @_NawGid is not null then _qcNEE else _qcJA endif; //Toevoegen of wijzigen mode
  end if;

  //Velden aanvullen met de waarde in de vaste gegevens mits deze niet gevuld zijn.
  call WebSvcHulpProc_NAW_ControleerVeldenEnOvernemenVastegegevens(
    @Mode = @_Toevoegen /*Toevoegen*/,
    @FonGid = @_FonGid,
    @LandCode = @LandCode,
    @TaalCode = @TaalCode,
    @BetalingsConditieNummer = @BetalingsConditieNummer,
    @LeveringsConditieNummer = @LeveringsConditieNummer,
    @ValutaCode = @ValutaCode,
    @BtwCode = @BtwCode,
    @KredietLimiet = @KredietLimiet,
    @DefaultTegenrekening = @DefaultTegenrekening,
    @_FonLndGid = @_LndGid,
    @_TaalGid = @_TaalGid,
    @_FonBtcNummer = @_BtcNummer,
    @_FonLvcNummer = @_LvcNummer,
    @_ValNummer = @_ValNummer,
    @_FonBtwCode = @_NawBtwCode,
    @_FonKredietLimiet = @_KredietLimiet,
    @_FonTegenRksGid = @_TegenRksGid);

  call WebSvcHulpProc_ValideerNawEanCode(
      @EanCode,
      'C',                  // c = crediteur, d = debiteur, b = bedrijfsgegevens, 123 = nummer relatiebestand
      null,                 // Indien NawGid ingevuld, wordt getoetst of EAN code hierbij hoort ( let op de FonId!)
      @ControleerFormaatEanCode,
      //out
      null,                 // de gevalideerde EAN code
      null);                // de NAW waar het bij hoort.

  if (@_Toevoegen = _qcJA) then
    //Een nieuwe crediteur toevoegen
    if IsNull(@CrediteurNummer, '') = '' then
      call NawGenereerNummer(@_FonGid, @CrediteurNummer, null)
    else
      call ParagraafSoort(@CrediteurNummer, 20 /* parsoort */, @_ParIsAkkoord);
      if (@_ParIsAkkoord = 0) then
        call Raise(20004); // Paragraaf en rekeningnummer komen niet overeen
      end if;
    end if;

    call NawInsert(
      /*@NawFilFonGID               */   @_FonGid,
      /*@nawfilNummer               */   @CrediteurNummer,
      /*@nawfilZoekcode             */   @ZoekCode,
      /*@nawfilRksGID               */   null,
      /*@nawfilValNummer            */   @_ValNummer,
      /*@nawfilBtcNummer            */   @_BtcNummer,
      /*@nawfilLvcNummer            */   @_LvcNummer,
      /*@nawfilKredLimiet           */   @_KredietLimiet,
      /*@nawfilAutoOSP              */   null,
      /*@nawfilBTWcode              */   @_NawBtwCode,
      /*@adrNaam1                   */   @Naam1,
      /*@adrNaam2                   */   @Naam2,
      /*@adrStraat                  */   @Straat,
      /*@adrHuisnummer              */   @HuisNummer,
      /*@adrPostcode                */   @PostCode,
      /*@adrPlaats                  */   @Plaats,
      /*@AdrEanCode                 */   @EanCode,
      /*@adrLndGid                  */   @_LndGid,
      /*@adrEMail                   */   @EMail,
      /*@adrTelefoon                */   @Telefoon1,
      /*@adrTelefax                 */   @Telefax,
      /*@nawTaalGid                 */   @_TaalGid,
      /*@_NawGidVestiging            */   null,
      /*@_NawGidCorrespondentie      */   null,
      /*@nawBtwNummer               */   @BtwNummer,
      /*@nawAanmaningsType          */   null,
      /*@nawOnsDebiteurNummer       */   '',
      /*@nawFacturerenInclBtw       */   null,
      /*@nawAparteFacturen          */   null,
      /*@NawAparteLevering          */   null,
      /*@NawIsDeelLeveringToegestaan*/   null,
      /*@nawAantalKopieFacturen     */   null,
      /*@nawOrderKorting            */   null,
      /*@nawVertegenwCode           */   null,
      /*@nawFactuurAdres            */   null,
      /*@nawVerzendAdres            */   0,
      /*@_NawGidVerzendAdres         */  null,
      /*@nawBlokOrderInvoer         */   null,
      /*@nawContributieCode         */   null,
      /*@TegenRksGid                */   @_TegenRksGid,
      /*@nawIdFactDeb               */   null,
      /*@NawFilDebGrpGid            */   null,
      /*@NawFilWelkeOrderkorting    */   0,
      /*@NawFilWebNaw               */   0,
      /*@NawidDebOmzet              */   null,
      /*@NawidDebPrijzen            */   null,
      /*@NawIsInkoopCombinatie      */   0,
      /*@NawKvkNummer               */   @KvkNummer,
      /*@NawBedrijfstak             */   '',
      /*@NawIncassantReferentie     */   '',
      /*@nawBlokSupport             */   0,
      /*@NawEindAdres               */   null,
      /*@_NawGidEindAdres            */  null,
      /*@adrTelefoon2               */   @Telefoon2,
      /*@NawWebsite                 */   @WebSite,
      /*@NawVrvGid                  */   null);

      select NawFilNawGid into @_NawGid from tabNawFile where NawFilNummer = @CrediteurNummer and NawFilFonGid = @_FonGid;

    // Vaste gegevens Documenten overnemen naar de NAW
    call VasteGegNawDocumentenOvernemen(@_NawGid, @_FonGid);

    /* Default waarden van vrije rubrieken vullen */
    call VrijeRubriekenVulDefaults('NAW', @_FonGid, @_FonGid, @_NawGid);
  else /*WIJZIGEN*/
    update tabNaw set NawTaalGid   = IsNull(@_TaalGid, if @TaalCode is null then NawTaalGid else null endif),
                      NawBtwNummer = IsNull(@BtwNummer, NawBtwNummer),
                      NawKvkNummer = IsNull(@KvkNummer, NawKvkNummer),
                      NawWebsite = isNull(@WebSite, NawWebSite)
    where NawGid = @_NawGid;

    update tabNawFile set NawFilZoekcode   = IsNull(@ZoekCode, NawFilZoekcode),
                          NawFilValNummer  = IsNull(@_ValNummer, if @ValutaCode is null then NawFilValNummer else null endif),
                          NawFilBtcNummer  = IsNull(@_BtcNummer, if @BetalingsConditieNummer is null then NawFilBtcNummer else null endif),
                          NawFilLvcNummer  = IsNull(@_LvcNummer, if @LeveringsConditieNummer is null then NawFilLvcNummer else null endif),
                          NawFilKredLimiet = (if @KredietLimiet is null then NawFilKredLimiet else @_KredietLimiet endif),
                          NawFilBtwCode    = IsNull(@_NawBtwCode, if @BtwCode is null then NawFilBtwCode else null endif)
    where NawFilNawGid = @_NawGid;

    update tabAdres set AdrNaam1 = IsNull(@Naam1, AdrNaam1), AdrNaam2 = IsNull(@Naam2, AdrNaam2),
                        AdrStraat = IsNull(@Straat, AdrStraat),
                        AdrHuisnummer = IsNull(@HuisNummer, AdrHuisnummer),
                        AdrPostcode = IsNull(@PostCode, AdrPostcode),
                        AdrPlaats = IsNull(@Plaats, AdrPlaats),
                        AdrTelefoon = IsNull(@Telefoon1, AdrTelefoon),
                        AdrTelefax = IsNull(@Telefax, AdrTelefax),
                        AdrEmail = IsNull(@EMail, AdrEmail),
                        AdrEanCode = IsNull(@EanCode, AdrEanCode),
                        AdrTelefoon2 = IsNull(@Telefoon2, AdrTelefoon2),
                        AdrLndGid = IsNull(@_LndGid, if @LandCode is null then AdrLndGid else null endif)
    where AdrGid = (select NawGidVestiging from tabNaw where NawGid = @_NawGid);

    if @_TegenRksGid is not null then
      update tabRekeningSchema
      set TegenRksGid = @_TegenRksGid
      where (RksInvoer = @CrediteurNummer)
        and (isnull(TegenRksGid, '') <> isnull(@_TegenRksGid, '')
              or isnull(RksNaam, '') <> isnull(@Naam1, ''));
    end if;
  end if;

  select NawFilNummer as CrediteurNummer from tabNawFile where NawFilNawGid = @_NawGid;

  //call TraceEind('WebSvcProc_Crediteur_ToevoegenWijzigen');
end;


create or replace procedure WebSvcProc_Crediteur_VrijeRubriek_Wijzigen(in @CrediteurNummer nchar(10), in @RubriekOmschrijving nchar(40), in @RubriekInhoud nchar(255))
begin
  declare @FonGid       integer;
  declare @NawGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_VrijeRubriek_Wijzigen > @CrediteurNummer = ' + @CrediteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);
  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select FonGid into @FonGid from tabFileOfNaw where FonId = 'C';

  select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @CrediteurNummer;
  if (@NawGid is null) then
    call Raise(20571); //Ongeldige of geen CrediteurNummer meegegeven!
  end if;

  call VrInsertOrReplaceValue('NAW', @FonGid, @FonGid, @NawGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Crediteur_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_Adres_ToevoegenWijzigen(in @DebiteurNummer nchar(10), in @ContactPersoonNummer numeric(3,0), in @AdresCode nchar(4), in @Omschrijving nchar(40), in @Naam1 nchar(40),
                                                                        in @Naam2 nchar(40), in @Straat nchar(40), in @HuisNummer nchar(10), in @PostCode nchar(40), in @Plaats nchar(40), in @EMail nchar(80),
                                                                        in @LandCode nchar(3), in @Telefoon1 nchar(25), in @Telefoon2 nchar(25), in @Telefax nchar(40), in @EanCode nchar(13), in @Opmerking long nvarchar)
result(AdresCode nchar(3))
begin
  declare @FonGid     integer;
  declare @AdrGid     integer;
  declare @NawGid     integer;
  declare @AdrLndGid  integer;
  declare @RelGid     integer;
  declare @TempNawGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_Adres_ToevoegenWijzigen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  // Eerst alle velden trimmen, anders komen ze met naloopspaties in de database!
  set @DebiteurNummer       = trim(@DebiteurNummer       );
  set @ContactPersoonNummer = trim(@ContactPersoonNummer );
  set @AdresCode            = trim(@AdresCode            );
  set @Omschrijving         = trim(@Omschrijving         );
  set @Naam1                = trim(@Naam1                );
  set @Naam2                = trim(@Naam2                );
  set @Straat               = trim(@Straat               );
  set @HuisNummer           = trim(@HuisNummer           );
  set @PostCode             = trim(@PostCode             );
  set @Plaats               = trim(@Plaats               );
  set @EMail                = trim(@EMail                );
  set @LandCode             = trim(@LandCode             );
  set @Telefoon1            = trim(@Telefoon1            );
  set @Telefoon2            = trim(@Telefoon2            );
  set @Telefax              = trim(@Telefax              );
  set @EanCode              = trim(@EanCode              );
  set @Opmerking            = trim(@Opmerking            );

  if IsModuleActive('we') <> 0 then
    select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @DebiteurNummer;
    if (@NawGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    if @ContactPersoonNummer is not null then
      select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
      if (@RelGid is null) then
        call Raise(20555); //Ongeldige ContactPersoonNummer meegegeven!
      end if;
    end if;

    if IsNull(@LandCode, '') <> '' then
      select LndGid into @AdrLndGid  from tabLand where LndEigenCode = @LandCode;
      if (@AdrLndGid is null) then
        call Raise(20553); //Ongeldige LandCode meegegeven!
      end if;
    end if;

    if (@RelGid is not null) and (@AdresCode in ('COR', 'VEST')) then
      call Raise(20556); //Er kan geen ContactPersoonNummer worden meegegeven aan een vestigings- of correspondentie adres
    end if;

    case @AdresCode
      when 'COR' then
      begin
        set @AdresCode    = null;
        set @Omschrijving = _A('Correspondentieadres');

        //Eerst controleren of vestigingsadres gelijk is aan correspondentie adres. Zo ja, dan een apart adres aanmaken voor correspondentie adres
        select NawGid, NawGidCorrespondentie into @TempNawGid, @AdrGid from tabNaw where NawGid = @NawGid and NawGidCorrespondentie = NawGidVestiging;
        if @TempNawGid is not null then      //Als TempNawGid gevuld is, dan is ie altijd gelijk aan @NawGid. Verderop weer gebruik maken van @NawGid
          insert into tabAdres with auto name
          select AdrNawGid, AdrCode, AdrOms, AdrNaam1, AdrNaam2, AdrStraat, AdrHuisnummer, AdrPostcode, AdrPlaats,
                 AdrTelefoon, AdrTelefax, AdrEmail, AdrLndGID, AdrEanCode, AdrTelefoon2 from tabAdres where AdrGid = @AdrGid;
          set @AdrGid = @@Identity;
          update tabNaw set NawGidCorrespondentie = @AdrGid where NawGid = @NawGid;
        else
          select NawGidCorrespondentie into @AdrGid from tabNaw where NawGid = @NawGid;
        end if;
      end;

      when 'VEST' then
      begin
        set @AdresCode    = null;
        set @Omschrijving = _A('Vestigingsadres');
        select NawGidVestiging into @AdrGid from tabNaw where NawGid = @NawGid;
      end;

      else
        //Als er geen AdresCode is meegegeven, dan genereren we een adrescode voor dit verzendadres, MITS nog niet bestaat
        if IsNull(@AdresCode, '') = '' then
          // Hier kijken of er een adres is met precies dezelfde inhoud (Alleen controleren op meegegeven velden!)
          select first AdrGid, AdrCode into @AdrGid, @AdresCode from tabAdres
          where AdrNawGid = @NawGid
             and AdrGid <> (select NawGidCorrespondentie from tabNaw where nawgid = @NawGid)
             and AdrGid <> (select NawGidVestiging from tabNaw where nawgid = @NawGid)
             //and (AdrCode               = isnull(@AdresCode   , AdrCode       ) )
             and (isnull(AdrRelGid, -1) = isnull(@RelGid      , AdrRelGid, -1 ) )
             and (AdrOms                = isnull(@Omschrijving, AdrOms        ) )
             and (AdrNaam1              = isnull(@Naam1       , AdrNaam1      ) )
             and (AdrNaam2              = isnull(@Naam2       , AdrNaam2      ) )
             and (AdrStraat             = isnull(@Straat      , AdrStraat     ) )
             and (AdrHuisnummer         = isnull(@HuisNummer  , AdrHuisnummer ) )
             and (AdrPostCode           = isnull(@PostCode    , AdrPostCode   ) )
             and (AdrPlaats             = isnull(@Plaats      , AdrPlaats     ) )
             and (AdrTelefoon           = isnull(@Telefoon1   , AdrTelefoon   ) )
             and (AdrTelefax            = isnull(@Telefax     , AdrTelefax    ) )
             and (AdrEmail              = isnull(@EMail       , AdrEmail      ) )
             and (isnull(AdrLndGID, -1) = isnull(@AdrLndGid   , AdrLndGID, -1 ) )
             and (AdrEanCode            = isnull(@EanCode     , AdrEanCode    ) )
             and (AdrTelefoon2          = isnull(@Telefoon2   , AdrTelefoon2  ) ) ;

          if @AdrGid is null then
            set @AdresCode = IsNull((select max(AdrCode) from tabAdres where AdrNawGid = @NawGid), 0)+1;
            if length(@AdresCode) > 3 then
              call Raise(20557); //Er kan geen nieuwe AdresCode worden gegenereerd, de hoogste gebruikte AdresCode is 999!
            end if;
          end if;
        end if;
        select AdrGid into @AdrGid from tabAdres where AdrNawGid = @NawGid and AdrCode = @AdresCode;
    end case;

    if @AdrGid is null then
      insert into tabAdres (AdrNawGid, AdrCode, AdrRelGid, AdrOms, AdrNaam1, AdrNaam2, AdrStraat, AdrHuisnummer, AdrPostCode, AdrPlaats,
                            AdrTelefoon, AdrTelefax, AdrEmail, AdrLndGID, AdrEanCode,
                            AdrTelefoon2)
                values     (@NawGid, @AdresCode, @RelGid, @Omschrijving, @Naam1, @Naam2, @Straat, @HuisNummer,
                            @PostCode, @Plaats, @Telefoon1, @Telefax, @EMail, @AdrLndGid, @EanCode,
                            @Telefoon2);
      set @AdrGid = @@Identity;

      if IsNull(@Opmerking, '') <> '' then
        insert into tabAdresOpmerkingen(AdrOpmAdrGid, AdrOpmOpmerking)
        values (@AdrGid, @Opmerking);
      end if;

    else
      update tabAdres set AdrOms = IsNull(@Omschrijving, AdrOms), AdrNaam1 = IsNull(@Naam1, AdrNaam1), AdrNaam2 = IsNull(@Naam2, AdrNaam2), AdrStraat = IsNull(@Straat, AdrStraat),
                          AdrHuisnummer = IsNull(@HuisNummer, AdrHuisnummer), AdrPostcode = IsNull(@PostCode, AdrPostcode), AdrPlaats = IsNull(@Plaats, AdrPlaats),
                          AdrTelefoon = IsNull(@Telefoon1, AdrTelefoon), AdrTelefax = IsNull(@Telefax, AdrTelefax), AdrEmail = IsNull(@EMail, AdrEmail),
                          AdrEanCode = IsNull(@EanCode, AdrEanCode), AdrTelefoon2 = IsNull(@Telefoon2, AdrTelefoon2),
                          AdrLndGid = IsNull(@AdrLndGid, if @LandCode is null then AdrLndGid else null endif),
                          AdrRelGid = IsNull(@RelGid, if @ContactPersoonNummer is null then AdrRelGid else null endif)
      where AdrGid = @AdrGid;

      if @Opmerking is not null then
        if exists(select 1 from tabAdresOpmerkingen where AdrOpmAdrGid = @AdrGid) then
          update tabAdresOpmerkingen set AdrOpmOpmerking = @Opmerking where AdrOpmAdrGid = @AdrGid;
        else
          insert into tabAdresOpmerkingen(AdrOpmAdrGid, AdrOpmOpmerking)
          values (@AdrGid, @Opmerking);
        end if;
      end if;
    end if;

    if (@AdresCode is not null) then  //Alleen adrescode teruggeven als we een verzend/besteladres teruggeven. Dus niet bij vest- of corr. adres
      select right('000'+string(AdrCode), 3) as AdresCode from tabAdres where AdrGid = @AdrGid;
    end if;
  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_Adres_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Debiteur_Adres_VrijeRubriek_Wijzigen(in @DebiteurNummer nchar(10), in @AdresCode nchar(4), in @RubriekOmschrijving nchar(40), in @RubriekInhoud nchar(255))
begin
  declare @FonGid        integer;
  declare @NawGid        integer;
  declare @AdrGid        integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_Adres_VrijeRubriek_Wijzigen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';

  select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @DebiteurNummer;
  if (@NawGid is null) then
    call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
  end if;

  select AdrGid into @AdrGid from tabAdres where AdrNawGid = @NawGid and AdrCode = @AdresCode;
  if (@AdrGid is null) then
    call Raise(20558); //Ongeldige of geen AdresCode meegegeven!
  end if;

  call VrInsertOrReplaceValue('ADR', @FonGid, @FonGid, @AdrGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_Adres_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_BankRekening_Toevoegen(in @DebiteurNummer nchar(10), in @BankRekeningNummer nchar(34), in @BankNaam  nchar(70), in @BankAdres nchar(70),
                                                                       in @BankPostCode nchar(70), in @BankPlaats nchar(70), in @BankLandCode nchar(3), in @BankBic nchar(11), in @RekeningHouderNaam nchar(70),
                                                                       in @RekeningHouderAdres nchar(70), in @RekeningHouderPostCode nchar(70), in @RekeningHouderPlaats nchar(70), in @RekeningHouderLandCode nchar(3),
                                                                       in @Opmerking long nvarchar, in @DefaultBankRekening smallint, in @DefaultBankRekeningIncasso smallint)
begin
  declare @NawGid                integer;
  declare @NawFilFonGid          integer;
  declare @NawRekBankLndGid      integer;
  declare @NawRekLndGidRekHouder integer;
  declare @NawRekGid             integer;
  declare @NawRekSoort           nchar(3);

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_BankRekening_Toevoegen > @DebiteurNummer = ' + @DebiteurNummer+', @BankRekeningNummer = ' + @BankRekeningNummer + ', @RekeningHouderNaam = ' + @RekeningHouderNaam;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid into @NawFilFonGid from tabFileOfNaw where FonId = 'D';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;
    if (@NawGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    if IsNull(@BankRekeningNummer, '') = '' then
      call Raise(20561); //Ongeldige of geen BankRekeningNummer meegegeven!
    end if;

    select NawRekGid into @NawRekGid from tabNawRekening where NawRekNawGid = @NawGid and NawRekBankRekeningInvoer = @BankRekeningNummer;
    if (@NawRekGid is not null) then
      call Raise(20562); //BankRekeningNummer bestaat al!
    end if;

    if IsNull(@BankLandCode, '') <> '' then
      select LndGid into @NawRekBankLndGid  from tabLand where LndEigenCode = @BankLandCode;
      if (@NawRekBankLndGid is null) then
        call Raise(20563); //Ongeldige of geen BankLandCode meegegeven!
      end if;
    end if;

    if IsNull(@RekeningHouderLandCode, '') <> '' then
      select LndGid into @NawRekLndGidRekHouder  from tabLand where LndEigenCode = @RekeningHouderLandCode;
      if (@NawRekLndGidRekHouder is null) then
        call Raise(20564); //Ongeldige of geen RekeningHouderLandCode meegegeven!
      end if;
    end if;

    if IsNull(@DefaultBankRekening, 0) in (0,1) then
      if IsNull(@DefaultBankRekening, 0) = 1 then
        set @NawRekSoort = @NawRekSoort + 'D';
      end if;
    else
      call Raise(20637); //Ongeldige of geen DefaultBankRekening meegegeven!
    end if;

    if IsNull(@DefaultBankRekeningIncasso, 0) in (0,1) then
      if IsNull(@DefaultBankRekeningIncasso, 0) = 1 then
        set @NawRekSoort = @NawRekSoort + 'I';
      end if;
    else
      call Raise(20638); //Ongeldige of geen DefaultBankRekeningIncasso meegegeven!
    end if;

    insert into tabNawRekening(NawRekNawGid, NawRekBankRekeningInvoer, NawRekBankNaam , NawRekBankAdres, NawRekBankPostcode, NawRekBankPlaats, NawRekBankLndGid, NawRekSoort, NawRekBankBIC,
                               NawRekNaamRekHouder, NawRekAdresRekHouder, NawRekPostcodeRekHouder, NawRekPlaatsRekHouder, NawRekLndGidRekHouder, NawRekOpmerking)
                        values(@NawGid, @BankRekeningNummer, @BankNaam , @BankAdres, @BankPostCode, @BankPlaats, @NawRekBankLndGid, @NawRekSoort, @BankBic,
                               @RekeningHouderNaam, @RekeningHouderAdres, @RekeningHouderPostCode, @RekeningHouderPlaats, @NawRekLndGidRekHouder, @Opmerking);
  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_BankRekening_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_BankRekening_Verwijderen(in @DebiteurNummer nchar(10), in @BankRekeningNummer nchar(34))
begin
  declare @NawGid       integer;
  declare @NawFilFonGid integer;
  declare @NawRekGid    integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_BankRekening_Verwijderen > @DebiteurNummer = ' + @DebiteurNummer+', @BankRekeningNummer = ' + @BankRekeningNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid into @NawFilFonGid from tabFileOfNaw where FonId = 'D';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;
    if (@NawGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    select NawRekGid into @NawRekGid from tabNawRekening where NawRekNawGid = @NawGid and NawRekBankRekening = @BankRekeningNummer;
    if (@NawRekGid is null) then
      call Raise(20561); //Ongeldige of geen BankRekeningNummer meegegeven!
    end if;

    delete tabNawRekening where NawRekGid = @NawRekGid;

  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_BankRekening_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_ContactPersoon_Functie_ToevoegenWijzigen(in @DebiteurNummer nchar(10), in @ContactPersoonNummer numeric(3,0), in @FunctieNummer numeric(3,0), in @VoorkeurContactPersoonVoorFunctie  smallint)
begin
  declare @NawGid       integer;
  declare @RelGid       integer;
  declare @RelFnCode    integer;
  declare @NawFilFonGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactPersoon_Functie_ToevoegenWijzigen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid into @NawFilFonGid from tabFileOfNaw where FonId = 'D';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;
    if (@NawGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
    if (@RelGid is null) then
      call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
    end if;

    select FnCode into @RelFnCode from tabFunctieContact where FnCode = @FunctieNummer;
    if (@RelFnCode is null) then
      call Raise(20565); //Ongeldige of geen FunctieNummer meegegeven!
    end if;

    if exists(select 1 from tabRelatieFunctie where FnRelGid = @RelGid and RelFnCode = @RelFnCode) then
      update tabRelatieFunctie set IsBelangrijkste = @VoorkeurContactPersoonVoorFunctie where FnRelGid = @RelGid and RelFnCode = @RelFnCode;
    else
      insert into tabRelatieFunctie(FnRelGid, RelFnCode, IsBelangrijkste) values (@RelGid, @RelFnCode, @VoorkeurContactPersoonVoorFunctie);
    end if;

  else
    call Raise(20901); //Optie ''Webservice NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactPersoon_Functie_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


