create or replace procedure WebSvcProc_Debiteur_ContactPersoon_SelectieCode_Toevoegen(in @DebiteurNummer nchar(10), in @ContactPersoonNummer numeric(3,0), in @SelectieCode nchar(3))
begin
  declare @NawGid       integer;
  declare @RelGid       integer;
  declare @SltGid       integer;
  declare @NawFilFonGid integer;
  declare @SlcGid       integer;
  declare @SprGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactPersoon_SelectieCode_Toevoegen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid, FonSltGid into @NawFilFonGid, @SltGid from tabFileOfNaw where FonId = 'D';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;
    if (@NawGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
    if (@RelGid is null) then
      call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
    end if;

    if (@SltGid is null) then
      call Raise(20566); //Geen selectiecodetabel ingevuld bij dit type NAW!
    end if;

    select SlcGid into @SlcGid from tabSelectiecodes where SlcCode = @SelectieCode and SlcSltGid = @SltGid;
    if (@SlcGid is null) then
      call Raise(20567); //Ongeldige of geen SelectieCode meegegeven!
    end if;

    select SprGid into @SprGid from tabSlcPerRelatie where SprSlcGid = @SlcGid and SprRelGid = @RelGid;
    if (@SprGid is null) then
      insert into tabSlcPerRelatie(SprRelGid, SprSlcGid) select @RelGid, @SlcGid;
      set @SprGid = @@Identity;
    end if;

  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactPersoon_SelectieCode_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_ContactPersoon_SelectieCode_Verwijderen(in @DebiteurNummer nchar(10), in @ContactPersoonNummer numeric(3,0), in @SelectieCode nchar(3))
begin
  declare @NawGid       integer;
  declare @RelGid       integer;
  declare @SprGid       integer;
  declare @NawFilFonGid integer;
  declare @SlcGid       integer;
  declare @SltGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactPersoon_SelectieCode_Verwijderen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid into @NawFilFonGid from tabFileOfNaw where FonId = 'D';

    select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;
    if (@NawGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
    if (@RelGid is null) then
      call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
    end if;

    select FonSltGid into @SltGid from tabFileOfNaw where FonGid = @NawFilFonGid;
    if (@SltGid is null) then
      call Raise(20566); //Geen selectiecodetabel ingevuld bij dit type NAW!
    end if;

    select SlcGid into @SlcGid from tabSelectiecodes where SlcCode = @SelectieCode and SlcSltGid = @SltGid;
    if (@SlcGid is null) then
      call Raise(20567); //Ongeldige of geen SelectieCode meegegeven!
    end if;

    select SprGid into @SprGid from tabSlcPerRelatie where SprSlcGid = @SlcGid and SprRelGid = @RelGid;
    delete tabSlcPerRelatie where SprGid = @SprGid;

  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactPersoon_SelectieCode_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_ContactPersoon_ToevoegenWijzigen(
  in @DebiteurNummer nchar(10),
  in @ContactPersoonNummer numeric(3,0),
  in @AchterNaam nchar(40),
  in @VoorVoegsel nchar(40),
  in @VoorLetters nchar(15),
  in @VoorNaam nchar(40),
  in @Titel nchar(15),
  in @AchterVoegsel nchar(15),
  in @VolledigeNaam nchar(40),
  in @Geslacht nchar(8),
  in @Telefoon1 nchar(25),
  in @Telefoon2 nchar(25),
  in @Telefax nchar(25),
  in @EMail nchar(80),
  in @ContributieCode numeric(3,0),
  in @NaamInAdres nchar(60),
  in @NaamInAanhef nchar(60),
  in @NaamInBrief nchar(60),
  in @Opmerking long nvarchar,
  in @AanheftekstenAutomatischVullen nchar(3)) //'JA', 'NEE'

result(ContactPersoonNummer numeric(3,0))

begin
  declare _qcNee smallint = 0;
  declare _qcJa nchar(2) = 'JA';
  declare @_NawGid       integer;
  declare @_RelGid       integer;
  declare @_RelGeslacht  smallint = 0;
  declare @_ContrCode    integer;

  //call TraceBegin('WebSvcProc_Debiteur_ContactPersoon_ToevoegenWijzigen > @DebiteurNummer = ' + @DebiteurNummer);

  if IsModuleActive('we') = _qcNee then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select NawFilNawGid
    into @_NawGid
  from tabNawFile
  inner join tabFileOfNaw on FonGid = NawFilFonGid and FonId = 'D'
  where NawFilNummer = @DebiteurNummer;

  if (@_NawGid is null) then
    call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
  end if;

  select ContactPersoonNummer
  from WebSvcHulpProc_NAW_ContactPersoon_ToevoegenWijzigen(
    @_NawGid, //@NawGid
    @ContactPersoonNummer, //@ContactPersoonNummer
    @AchterNaam, //@AchterNaam
    @VoorVoegsel, //@VoorVoegsel
    @VoorLetters, //@VoorLetters
    @VoorNaam, //@VoorNaam
    @Titel, //@Titel
    @AchterVoegsel, //@AchterVoegsel
    @VolledigeNaam, //@VolledigeNaam
    @Geslacht, //@Geslacht
    @Telefoon1, //@Telefoon1
    @Telefoon2, //@Telefoon2
    @Telefax, //@Telefax
    @EMail, //@EMail
    @ContributieCode, //@ContributieCode
    @NaamInAdres, //@NaamInAdres
    @NaamInAanhef, //@NaamInAanhef
    @NaamInBrief, //@NaamInBrief
    @Opmerking, //@Opmerking
    @AanheftekstenAutomatischVullen ); //@AanheftekstenAutomatischVullen

  //call TraceEind('WebSvcProc_Debiteur_ContactPersoon_ToevoegenWijzigen');
end;


create or replace procedure WebSvcProc_Debiteur_ContactPersoon_VrijeRubriek_Wijzigen(in @DebiteurNummer nchar(10), in @ContactPersoonNummer numeric(3,0), in @RubriekOmschrijving nchar(40), in @RubriekInhoud nchar(255))
begin
  declare @NawGid       integer;
  declare @FonGid       integer;
  declare @RelGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactPersoon_VrijeRubriek_Wijzigen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';

  select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @DebiteurNummer;
  if (@NawGid is null) then
    call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
  end if;

  select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
  if (@RelGid is null) then
    call Raise(20555); //Ongeldige of geen ContactPersoonNummer meegegeven!
  end if;

  call VrInsertOrReplaceValue('CP', @FonGid, @FonGid, @RelGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactPersoon_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_ContactRegistratie_Toevoegen(in @Gebruiker nchar(10), in @ContactSoortCode nchar(10), in @InvoerDatum date, in @InvoerTijd time, in @EindTijd time,
                                                                             in @DebiteurNummer nchar(10), in @ContactMet nchar(40), in @Notitie long nvarchar, in @OfferteNummer numeric(10,0))
begin
  declare @NawFilFonGid integer;
  declare @CosGid    integer;
  declare @NawFilGid integer;
  declare @OffGid    integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactRegistratie_Toevoegen > @Gebruiker = ' + @Gebruiker + ', @ContactSoortCode = ' + @ContactSoortCode;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid into @NawFilFonGid from tabFileOfNaw where FonId = 'D';

    select NawFilGid into @NawFilGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;

    if IsNull(@Gebruiker, '') = '' or (not exists(select 1 from tabGebruiker where NaamGebruiker = @Gebruiker)) then
      call Raise(20568); //Ongeldige of geen Gebruiker meegegeven!
    end if;

    select NawFilGid into @NawFilGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;
    if (@NawFilGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    select CosGid into @CosGid from tabContactSoort where CosCode = @ContactSoortCode;
    if (@CosGid is null) then
      call Raise(20569); //Ongeldige of geen ContactSoortCode meegegeven!
    end if;

    if @OfferteNummer is not null then
      select OffGid into @OffGid from tabOfferte where OffOffertenummer = @OfferteNummer;
      if (@OffGid is null) then
        call Raise(20570); //Ongeldige of geen OfferteNummer meegegeven!
      end if;
    end if;

    insert into tabGespreksNotitie(GnotGebruiker, GnotCosGid, GnotInvoerDatum, GnotInvoerTijd, GnotEindtijd, GnotNawFilGid, GnotNotitie, GnotGesprokenMet, GnotOffGid)
    select @Gebruiker, @CosGid, DateTimeConversieVoorWebServices(@InvoerDatum, @InvoerDatum), @InvoerTijd, @EindTijd, @NawFilGid, @Notitie, @ContactMet, @OffGid;

  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_ContactRegistratie_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


