  //call trace('Einde WebSvcProc_Debiteur_Onderhoud_VrijeRubriek_Verwijderen');
end;

create or replace procedure WebSvcProc_Debiteur_SelectieCode_Toevoegen(in @DebiteurNummer nchar(10), in @SelectieCode nchar(3))
begin
  declare @NawFilFonGid integer;
  declare @NawFilGid    integer;
  declare @SltGid       integer;
  declare @SlcGid       integer;
  declare @SpnGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_SelectieCode_Toevoegen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid, FonSltGid into @NawFilFonGid, @SltGid from tabFileOfNaw where FonId = 'D';

    select NawFilGid into @NawFilGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;
    if (@NawFilGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    if (@NawFilGid is null) then
      call Raise(20566); //Geen selectiecodetabel ingevuld bij dit type NAW!
    end if;

    select SlcGid into @SlcGid from tabSelectiecodes where SlcCode = @SelectieCode and SlcSltGid = @SltGid;
    if (@SlcGid is null) then
      call Raise(20567); //Ongeldige of geen SelectieCode meegegeven!
    end if;

    select SpnGid into @SpnGid from tabSlcPerNaw where SpnSlcGid = @SlcGid and SpnNawFilGid = @NawFilGid;
    if (@SpnGid is null) then
      insert into tabSlcPerNaw(SpnNawFilGid, SpnSlcGid) select @NawFilGid, @SlcGid;
    end if;

  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_SelectieCode_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_SelectieCode_Verwijderen(in @DebiteurNummer nchar(10), in @SelectieCode nchar(3))
begin
  declare @NawFilFonGid integer;
  declare @NawFilGid    integer;
  declare @SltGid       integer;
  declare @SlcGid       integer;
  declare @SpnGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_SelectieCode_Verwijderen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') <> 0 then
    select FonGid, FonSltGid into @NawFilFonGid, @SltGid from tabFileOfNaw where FonId = 'D';

    select NawFilGid into @NawFilGid from tabNawFile where NawFilFonGid = @NawFilFonGid and NawFilNummer = @DebiteurNummer;
    if (@NawFilGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    if (@NawFilGid is null) then
      call Raise(20566); //Geen selectiecodetabel ingevuld bij dit type NAW!
    end if;

    select SlcGid into @SlcGid from tabSelectiecodes where SlcCode = @SelectieCode and SlcSltGid = @SltGid;
    if (@SlcGid is null) then
      call Raise(20567); //Ongeldige of geen SelectieCode meegegeven!
    end if;

    select SpnGid into @SpnGid from tabSlcPerNaw where SpnSlcGid = @SlcGid and SpnNawFilGid = @NawFilGid;

    delete tabSlcPerNaw where SpnGid = @SpnGid;
  else
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_SelectieCode_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Debiteur_ToevoegenWijzigen(
  in @DebiteurNummer nchar(10),
  in @ZoekCode nchar(10),
  in @ValutaCode nchar(3),
  in @BetalingsConditieNummer numeric(3,0),
  in @LeveringsConditieNummer numeric(3,0),
  in @KredietLimiet numeric(15,2),
  in @BtwCode numeric(3,0),
  in @Naam1 nchar(40),
  in @Naam2 nchar(40),
  in @Straat nchar(40),
  in @HuisNummer nchar(10),
  in @PostCode nchar(40),
  in @Plaats nchar(40),
  in @EanCode nchar(13),
  in @LandCode nchar(3),
  in @EMail nchar(80),
  in @Telefoon1 nchar(25),
  in @Telefoon2 nchar(25),
  in @Telefax nchar(40),
  in @TaalCode nchar(3),
  in @BtwNummer nchar(15),
  in @AanmaningsType nchar(20),
  in @FacturerenInclusiefBtw smallint,
  in @AparteFacturen nchar(10),
  in @AantalKopieFacturen integer,
  in @OrderKortingsPercentage numeric(6,2),
  in @VertegenwoordigerNummer numeric(3,0),
  in @FactuurAdres nchar(4),
  in @BlokkerenVoorOrderInvoer smallint,
  in @WebKlant smallint,
  in @KvkNummer nchar(40),
  in @VerzendAdres nchar(10),
  in @VerzendAdresNummer numeric(3,0),
  in @Debiteurgroep numeric(3,0),
  in @InkoopCombinatie smallint,
  in @DebiteurNummerFactuur nchar(10),
  in @DebiteurNummerOmzet nchar(10),
  in @DebiteurNummerPrijsafspraken nchar(10),
  in @DefaultTegenrekening nchar(28),
  in @DefaultVervoerder nchar(40),
  in @ControleerFormaatEanCode smallint default 1, // indien 1, dan wordt er gecontroleerd of eancode voldoet aan het ucc-13 formaat
  in @WebSite nchar(250) default null
)
result(DebiteurNummer nchar(10))

begin
  //Constanten
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  //Variabelen
  declare @_Toevoegen smallint = _qcJA;

  declare @_FonGid integer;
  declare @_NawGid integer;
  declare @_NawGidFactuur integer;
  declare @_NawGidOmzet integer;
  declare @_NawGidPrijzen integer;
  declare @_LndGid integer;
  declare @_TaalGid integer;
  declare @_DebGrpGid integer;
  declare @_ValNummer integer;
  declare @_VzaGid integer;
  declare @_VtgCode integer;
  declare @_BtcNummer integer;
  declare @_LvcNummer integer;
  declare @_NawBtwCode integer;
  declare @_KredietLimiet numeric(15,2);
  declare @_TegenRksGid integer;
  declare @_NawFactuurAdres smallint;
  declare @_NawAanmaningsType smallint;
  declare @_NawVerzendAdres smallint;
  declare @_NawAparteFacturen smallint;
  declare @_NawAparteLevering smallint;
  declare @_NawIsInkoopCombinatie   smallint;
  declare @_nawFacturerenInclBtw smallint;
  declare @_NawEindAdres smallint;
  declare @_nawContributieCode integer;
  declare @_nawAantalKopieFacturen integer;
  declare @_NawFilWelkeOrderkorting smallint;
  declare @_nawOrderKorting numeric(6,2);
  declare @_NawVrvGid integer;
  declare @_nawBlokOrderInvoer smallint;
  declare @_NawFilWebNaw smallint;
  declare @_DebiteurStartNummer nchar(10) = '';
  declare @_ParIsAkkoord integer;

  //call TraceBegin('WebSvcProc_Debiteur_ToevoegenWijzigen > @DebiteurNummer = ' + @DebiteurNummer+', @ZoekCode = ' + @ZoekCode + ', @ValutaCode = ' + @ValutaCode);

  if IsModuleActive('we') = _qcNEE then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select FonGid into @_FonGid from tabFileOfNaw where FonId = 'D';

  if IsNull(@DebiteurNummer, '') <> '' then
    if (RegExp_Substr(@DebiteurNummer, '\D') is not null) then   //Mogen allen maar cijfers zijn
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    select NawFilNawGid, NawVerzendAdres
      into @_NawGid, @_NawVerzendAdres
    from tabNawFile
    inner join tabNaw on NawFilNawGid = NawGid
    where NawFilFonGid = @_FonGid
      and NawFilNummer = @DebiteurNummer;

    set @_Toevoegen = if @_NawGid is not null then _qcNEE else _qcJA endif; //Toevoegen of wijzigen mode

    if (@_Toevoegen = _qcJA) then
      call ParagraafSoort(@DebiteurNummer, 10 /* parsoort */, @_ParIsAkkoord);
      if (@_ParIsAkkoord = 0) then
        call Raise(20003); // Paragraaf en rekeningnummer komen niet overeen
      end if;
    end if;
  end if;

  //Velden aanvullen met de waarde in de vaste gegevens mits deze niet gevuld zijn.
  call WebSvcHulpProc_NAW_ControleerVeldenenOvernemenVastegegevens(
    @Mode = @_Toevoegen /*Toevoegen*/,
    @FonGid = @_FonGid,
    @LandCode = @LandCode,
    @TaalCode = @TaalCode,
    @BetalingsConditieNummer = @BetalingsConditieNummer,
    @LeveringsConditieNummer = @LeveringsConditieNummer,
    @ValutaCode = @ValutaCode,
    @BtwCode = @BtwCode,
    @KredietLimiet = @KredietLimiet,
    @DefaultTegenrekening = @DefaultTegenrekening,
    @AanmaningsType = @AanmaningsType,
    @AparteFacturen = @AparteFacturen,
    @FacturerenInclusiefBtw = @FacturerenInclusiefBtw,
    @FactuurAdres = @FactuurAdres,
    @IsInkoopCombinatie = @InkoopCombinatie,
    @VerzendAdres = @VerzendAdres,
    @NawVerzendadres = @_NawVerzendAdres,
    @Debiteurgroep = @Debiteurgroep,
    @VertegenwoordigerNummer = @VertegenwoordigerNummer,
    @AantalKopieFacturen = @AantalKopieFacturen,
    @OrdKortingDebOfDebGroep = if (@OrderKortingsPercentage is null) then null else 0 endif,
    @OrderKortingsPercentage = @OrderKortingsPercentage,
    @BlokkerenVoorOrderInvoer = @BlokkerenVoorOrderInvoer,
    @WebKlant = @WebKlant,
    @DefaultVervoerder = @DefaultVervoerder,
    @_FonLndGid = @_LndGid,
    @_TaalGid = @_TaalGid,
    @_FonBtcNummer = @_BtcNummer,
    @_FonLvcNummer = @_LvcNummer,
    @_ValNummer = @_ValNummer,
    @_FonBtwCode = @_NawBtwCode,
    @_FonKredietLimiet = @_KredietLimiet,
    @_FonTegenRksGid = @_TegenRksGid,
    @_FonAanmaningType = @_NawAanmaningsType,
    @_FonApartFactureren = @_NawAparteFacturen,
    @_FonAparteLevering = @_NawAparteLevering,
    @_FonFactuurBTW = @_nawFacturerenInclBtw,
    @_FonFactuurAdres = @_NawFactuurAdres,
    @_FonVerzendAdres = @_NawVerzendAdres,
    @_FonEindAdres = @_NawEindAdres,
    @_FonDebGrpGid = @_DebGrpGid,
    @_FonVtCode = @_VtgCode,
    @_FonContributieCode = @_nawContributieCode,
    @_FonAantKopieFacturen = @_nawAantalKopieFacturen,
    @_FonOrdKortingDebOfDebGroep = @_NawFilWelkeOrderkorting,
    @_FonOrderKorting = @_nawOrderKorting,
    @_FonVrvGid = @_NawVrvGid,
    @_FonBlokOrderInvoer = @_nawBlokOrderInvoer,
    @_FonIsWebklant = @_NawFilWebNaw
    );

  call WebSvcHulpProc_ValideerNawEanCode(
      @EanCode,
      'D',                  // c = crediteur, d = debiteur, b = bedrijfsgegevens, 123 = nummer relatiebestand
      null,                 // Indien NawGid ingevuld, wordt getoetst of EAN code hierbij hoort ( let op de FonId!)
      @ControleerFormaatEanCode,
      //out
      null,                 // de gevalideerde EAN code
      null);                // de NAW waar het bij hoort.

  begin
    if (@_Toevoegen = _qcJA) then
      if IsNull(@DebiteurNummer, '') = '' then
        call NawGenereerNummer(@_FonGid, @DebiteurNummer, @_DebiteurStartNummer)
      end if;
    end if;

    call WebSvcHulpProc_NAW_ValideerInkoopcombinatie(
      @_Toevoegen,
      @_NawGid,
      @DebiteurNummer,
      @DebiteurNummerFactuur,
      @DebiteurNummerOmzet,
      @DebiteurNummerPrijsafspraken,
      @InkoopCombinatie,
      @_NawIsInkoopCombinatie,
      @_NawGidFactuur,
      @_NawGidOmzet,
      @_NawGidPrijzen);
  exception
  when others then
    //Alleen terugzetten als het @_DebiteurStartNummer nog klopt met de db
    if isNull(@_DebiteurStartNummer,'') <> '' and (@_Toevoegen = _qcJA) then
      update tabFileOfNaw
      set fonStartNummer = @DebiteurNummer
      where fonGID = @_FonGid
        and fonStartNummer = @_DebiteurStartNummer;
    end if;

    Resignal; //Geef de foutmelsing die gegeven is in ValideerInkoopcombinatie
  end;

  if @VerzendAdresNummer is not null then
    if (@_NawVerzendAdres in (0,1,3,4)) then
      set @_VzaGid = null;
    else
      if (@_Toevoegen = _qcJA) and (@_NawVerzendAdres <> 5) then
        set @_VzaGid = null; //Bij toevoegen kun je nog geen verzendadresnummer hebben
      else
        select AdrGid into @_VzaGid
        from tabAdres
        where AdrNawGid = (if @_NawVerzendAdres = 5 then @_NawGidFactuur else @_NawGid endif)
          and AdrCode = @VerzendAdresNummer;

        if @_VzaGid is null then
          call Raise(20509); //Ongeldige of geen VerzendAdresNummer meegegeven!
        end if;
      end if;
    end if;
  end if;

  if (@_Toevoegen = _qcJA) then
    call NawInsert(
      /*@NawFilFonGID               */   @_FonGid,
      /*@nawfilNummer               */   @DebiteurNummer,
      /*@nawfilZoekcode             */   @ZoekCode,
      /*@nawfilRksGID               */   null,
      /*@nawfilValNummer            */   @_ValNummer,
      /*@nawfilBtcNummer            */   @_BtcNummer,
      /*@nawfilLvcNummer            */   @_LvcNummer,
      /*@nawfilKredLimiet           */   @_KredietLimiet,
      /*@nawfilAutoOSP              */   null,
      /*@nawfilBTWcode              */   @_NawBtwCode,
      /*@adrNaam1                   */   @Naam1,
      /*@adrNaam2                   */   @Naam2,
      /*@adrStraat                  */   @Straat,
      /*@adrHuisnummer              */   @HuisNummer,
      /*@adrPostcode                */   @PostCode,
      /*@adrPlaats                  */   @Plaats,
      /*@AdrEanCode                 */   @EanCode,
      /*@adrLndGid                  */   @_LndGid,
      /*@adrEMail                   */   @EMail,
      /*@adrTelefoon                */   @Telefoon1,
      /*@adrTelefax                 */   @Telefax,
      /*@nawTaalGid                 */   @_TaalGid,
      /*@nawGidVestiging            */   null,
      /*@nawGidCorrespondentie      */   null,
      /*@nawBtwNummer               */   @BtwNummer,
      /*@_NawAanmaningsType          */   @_NawAanmaningsType,
      /*@nawOnsDebiteurNummer       */   '',
      /*@nawFacturerenInclBtw       */   @_nawFacturerenInclBtw,
      /*@NawAparteFacturen          */  @_NawAparteFacturen,
      /*@NawAparteLevering          */  @_NawAparteLevering,
      /*@NawIsDeelLeveringToegestaan*/   null,
      /*@nawAantalKopieFacturen     */   @_nawAantalKopieFacturen,
      /*@nawOrderKorting            */   @_nawOrderKorting,
      /*@nawVertegenwCode           */   @_VtgCode,
      /*@NawFactuurAdres            */   @_NawFactuurAdres,
      /*@NawVerzendAdres            */   @_NawVerzendAdres,
      /*@nawGidVerzendAdres         */   @_VzaGid,
      /*@nawBlokOrderInvoer         */   @_nawBlokOrderInvoer,
      /*@nawContributieCode         */   @_nawContributieCode,
      /*@TegenRksGid                */   @_TegenRksGid,
      /*@nawIdFactDeb               */   @_NawGidFactuur,
      /*@NawFilDebGrpGid            */   @_DebGrpGid,
      /*@NawFilWelkeOrderkorting    */   @_NawFilWelkeOrderkorting,
      /*@NawFilWebNaw               */   @_NawFilWebNaw,
      /*@NawidDebOmzet              */   @_NawGidOmzet,
      /*@NawidDebPrijzen            */   @_NawGidPrijzen,
      /*@NawIsInkoopCombinatie      */  @_NawIsInkoopCombinatie,
      /*@NawKvkNummer               */   @KvkNummer,
      /*@NawBedrijfstak             */   '',
      /*@NawIncassantReferentie     */   '',
      /*@nawBlokSupport             */   0,
      /*@NawEindAdres               */   @_NawEindAdres,
      /*@NawGidEindAdres            */   null,
      /*@adrTelefoon2               */   @Telefoon2,
      /*@NawWebsite                 */   @WebSite,
      /*@NawVrvGid                  */   @_NawVrvGid);

    select NawFilNawGid into @_NawGid from tabNawFile where NawFilNummer = @DebiteurNummer and NawFilFonGid = @_FonGid;

    // Na het toevoegen of wijzigen (met inkoopcombinaws op null) de inkoopcombinatiedebiteuren bijwerken indien die gevuld moeten worden met de eigen debiteur
    if (@_NawIsInkoopCombinatie = _qcJA) then
      update tabNaw set
        NawIdFactDeb = isNull(NawIdFactDeb, @_NawGid),
        NawidDebOmzet = isNull(NawidDebOmzet, @_NawGid),
        NawidDebPrijzen = isNull(NawidDebPrijzen, @_NawGid)
      where NawGid = @_NawGid;
    end if;

    // Vaste gegevens Documenten overnemen naar de NAW
    call VasteGegNawDocumentenOvernemen(@_NawGid, @_FonGid);

    /* Default waarden van vrije rubrieken vullen */
    call VrijeRubriekenVulDefaults('NAW', @_FonGid, @_FonGid, @_NawGid);
  else
    update tabNaw
    set NawTaalGid = IsNull(@_TaalGid, if @TaalCode is null then NawTaalGid else null endif),
        NawBtwNummer = IsNull(@BtwNummer, NawBtwNummer),
        NawAanmaningsType = IsNull(@_NawAanmaningsType, NawAanmaningsType),
        NawFacturerenInclBtw = IsNull(@_nawFacturerenInclBtw, NawFacturerenInclBtw),
        NawAparteFacturen = IsNull(@_NawAparteFacturen, NawAparteFacturen),
        NawAparteLevering = IsNull(@_NawAparteLevering, NawAparteLevering),
        NawAantalKopieFacturen = IsNull(@_nawAantalKopieFacturen,    NawAantalKopieFacturen),
        NawOrderKorting = IsNull(@_nawOrderKorting, NawOrderKorting),
        NawVertegenwCode = IsNull(@_VtgCode, NawVertegenwCode),
        NawFactuurAdres = IsNull(@_NawFactuurAdres, NawFactuurAdres),
        NawBlokOrderInvoer = IsNull(@_nawBlokOrderInvoer, NawBlokOrderInvoer),
        NawKvkNummer = IsNull(@KvkNummer, NawKvkNummer),
        NawVerzendAdres = IsNull(@_NawVerzendAdres, NawVerzendAdres),
        NawGidVerzendAdres = if @_NawVerzendAdres in (0,1,3,4) then null else isNull(@_VzaGid,NawGidVerzendAdres) endif,
        NawIsInkoopCombinatie = IsNull(@_NawIsInkoopCombinatie, NawIsInkoopCombinatie),
        NawIdFactDeb = if @_NawIsInkoopCombinatie = _qcJA then IsNull(@_NawGidFactuur, NawIdFactDeb) else null endif,
        NawidDebOmzet = if @_NawIsInkoopCombinatie = _qcJA then IsNull(@_NawGidOmzet, NawidDebOmzet) else null endif,
        NawIdDebPrijzen = if @_NawIsInkoopCombinatie = _qcJA then IsNull(@_NawGidPrijzen, NawIdDebPrijzen) else null endif,
        NawVrvGid = isNull(@_NawVrvGid, NawVrvGid),
        NawWebsite = isNull(@WebSite, NawWebSite)
    where NawGid = @_NawGid;

    update tabNawFile
    set NawFilZoekcode   = IsNull(@ZoekCode, NawFilZoekcode),
        NawFilValNummer  = IsNull(@_ValNummer, if @ValutaCode is null then NawFilValNummer else null endif),
        NawFilBtcNummer  = IsNull(@_BtcNummer, if @BetalingsConditieNummer is null then NawFilBtcNummer else null endif),
        NawFilLvcNummer  = IsNull(@_LvcNummer, if @LeveringsConditieNummer is null then NawFilLvcNummer else null endif),
        NawFilKredLimiet = (if @KredietLimiet is null then NawFilKredLimiet else @_KredietLimiet endif),
        NawFilBtwCode    = IsNull(@_NawBtwCode, if @BtwCode is null then NawFilBtwCode else null endif),
        NawFilWebNaw     = IsNull(@_NawFilWebNaw, NawFilWebNaw),
        NawFilDebGrpGid  = IsNull(@_DebGrpGid, if @Debiteurgroep is null then NawFilDebGrpGid else null endif),
        NawFilWelkeOrderkorting = IsNull(@_NawFilWelkeOrderkorting, NawFilWelkeOrderkorting)
    where NawFilNawGid = @_NawGid;

    update tabAdres
    set AdrNaam1 = IsNull(@Naam1, AdrNaam1),
        AdrNaam2 = IsNull(@Naam2, AdrNaam2),
        AdrStraat = IsNull(@Straat, AdrStraat),
        AdrHuisnummer = IsNull(@HuisNummer, AdrHuisnummer),
        AdrPostcode = IsNull(@PostCode, AdrPostcode),
        AdrPlaats = IsNull(@Plaats, AdrPlaats),
        AdrTelefoon = IsNull(@Telefoon1, AdrTelefoon),
        AdrTelefax = IsNull(@Telefax, AdrTelefax),
        AdrEmail = IsNull(@EMail, AdrEmail),
        AdrEanCode = IsNull(@EanCode, AdrEanCode),
        AdrTelefoon2 = IsNull(@Telefoon2, AdrTelefoon2),
        AdrLndGid = IsNull(@_LndGid, if @LandCode is null then AdrLndGid else null endif)
    where AdrGid = (select NawGidVestiging from tabNaw where NawGid = @_NawGid);

    if @_TegenRksGid is not null then
      update tabRekeningSchema
      set TegenRksGid = @_TegenRksGid
      where (RksInvoer = @DebiteurNummer)
        and (isnull(TegenRksGid, '') <> isnull(@_TegenRksGid, '')
              or isnull(RksNaam, '') <> isnull(@Naam1, ''));
    end if;
  end if;

  // Vaste gegevens Webwinkels overnemen naar de NAW
  call WebSvcHulpProc_NAW_OvernemenWebWinkels(@_NawFilWebNaw, @_NawGid);

  select NawFilNummer as DebiteurNummer from tabNawFile where NawFilNawGid = @_NawGid;

  //call TraceEind('WebSvcProc_Debiteur_ToevoegenWijzigen');
end;



create or replace procedure WebSvcProc_Debiteur_VrijeRubriek_Wijzigen(in @DebiteurNummer nchar(10), in @RubriekOmschrijving nchar(40), in @RubriekInhoud nchar(255))
begin
  declare @FonGid       integer;
  declare @NawGid       integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_VrijeRubriek_Wijzigen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';

  select NawFilNawGid into @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @DebiteurNummer;
  if (@NawGid is null) then
    call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
  end if;

  call VrInsertOrReplaceValue('NAW', @FonGid, @FonGid, @NawGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_Webwinkel_Toevoegen(in @DebiteurNummer nchar(10), in @WebwinkelID nchar(20))
begin
  declare @FonGid       integer;
  declare @NawFilGid    integer;
  declare @NawGid       integer;
  declare @WebNaw       smallint;
  declare @WscGid       integer;
  declare @WnawGid      integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_Webwinkel_Toevoegenl > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';
    select NawFilGid into @NawFilGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @DebiteurNummer;
    if (@NawFilGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    select NawFilWebNaw into @WebNaw from tabNawFile where NawFilGid = @NawFilGid;
    if IsNull(@WebNaw, 0) = 0 then
      call Raise(20683); //Debiteur is geen web-klant!
    end if;

    if IsNull(@WebwinkelID, '') = '' then
      call Raise(20681); //Ongeldige of geen webshop id meegegeven!
    end if;

    select WscGid into @WscGid from tabWebshopConfiguratie where WscWebshopId = @WebwinkelID;
    if IsNull(@WscGid, '') = '' then
      call Raise(20681); //Ongeldige of geen webshop id meegegeven!
    end if;

    select NawFilNawGid into @NawGid from tabNawFile where NawFilGid = @NawFilGid;

    select WnawGid into @WnawGid from tabWebNaw where WnawNawGid = @NawGid and WnawWscGid = @WscGid;
    if @WnawGid is null then
      insert into tabWebNaw(WnawNawGid, WnawWscGid)
      values (@NawGid, @WscGid);
    end if;
  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_Webwinkel_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Debiteur_Webwinkel_Verwijderen(in @DebiteurNummer nchar(10), in @WebwinkelID nchar(20))
begin
  declare @FonGid       integer;
  declare @NawFilGid    integer;
  declare @NawGid       integer;
  declare @WebNaw       smallint;
  declare @WscGid       integer;
  declare @WnawGid      integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_Webwinkel_Verwijderen > @DebiteurNummer = ' + @DebiteurNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wl') <> 0 then
    select FonGid into @FonGid from tabFileOfNaw where FonId = 'D';
    select NawFilGid into @NawFilGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @DebiteurNummer;
    if (@NawFilGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    if IsNull(@WebwinkelID, '') = '' then
      call Raise(20681); //Ongeldige of geen webshop id meegegeven!
    end if;

    select WscGid into @WscGid from tabWebshopConfiguratie where WscWebshopId = @WebwinkelID;
    if IsNull(@WscGid, '') = '' then
      call Raise(20681); //Ongeldige of geen webshop id meegegeven!
    end if;

    select NawFilNawGid into @NawGid from tabNawFile where NawFilGid = @NawFilGid;

    delete from tabWebNaw
    where (WnawNawGid = @NawGid) and (WnawWscGid = @WscGid);

  else
    call Raise(20903); //Optie ''Webservices Logistiek'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Debiteur_Webwinkel_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_IcpAangifte_Regel_Toevoegen(in @AangifteJaar numeric(4,0), in @AangifteTijdvak nchar(10), in @DebiteurNummer nchar(10), in @RegelSoort nchar(15), in @CorrectieJaar numeric(4,0),
                                                                   in @CorrectieTijdvak nchar(10), in @BtwNummerDebiteur nchar(12), in @LandCode nchar(2), in @BedragDiensten numeric(12,0), in @BedragLeveringen numeric(12,0))
begin
  declare @AilKopJaar    integer;
  declare @AilKopTijdvak smallint;
  declare @AilRglGid     integer;
  declare @AilKopGid     integer;
  declare @NawGid        integer;
  declare @NawBtwNummer  nchar(15);
  declare @BtwNummer     nchar(12);
  declare @RglSoort      smallint;
  declare @Jaar          smallint;
  declare @Tijdvak       smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_IcpAangifte_Regel_Toevoegen > @AilKopGid = ' + string(@AilKopGid);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then
    case @AangifteTijdvak
      when '1ekwartaal' then set @TijdVak = 100;
      when '2ekwartaal' then set @TijdVak = 200;
      when '3ekwartaal' then set @TijdVak = 300;
      when '4ekwartaal' then set @TijdVak = 400;
      when 'heeljaar'   then set @TijdVak = 40;
      when 'jan'        then set @TijdVak = 101;
      when 'feb'        then set @TijdVak = 102;
      when 'mrt'        then set @TijdVak = 103;
      when 'apr'        then set @TijdVak = 204;
      when 'mei'        then set @TijdVak = 205;
      when 'jun'        then set @TijdVak = 206;
      when 'jul'        then set @TijdVak = 307;
      when 'aug'        then set @TijdVak = 308;
      when 'sep'        then set @TijdVak = 309;
      when 'okt'        then set @TijdVak = 410;
      when 'nov'        then set @TijdVak = 411;
      when 'dec'        then set @TijdVak = 412;
      when 'jan/feb'    then set @TijdVak = 113;
      when 'apr/mei'    then set @TijdVak = 214;
      when 'jul/aug'    then set @TijdVak = 315;
      when 'okt/nov'    then set @TijdVak = 416;
      else call Raise(20596); //Ongeldige of geen AangifteTijdvak meegegeven!
    end case;

    if (@AangifteJaar is null) then
      call Raise(20597); //Ongeldige of geen AangifteJaar meegegeven!
    end if;

    select AilKopGid, AilKopJaar, AilKopTijdvak into @AilKopGid, @AilKopJaar, @AilKopTijdvak from tabICLAangifteKop where AilKopJaar = @AangifteJaar and AilKopTijdVak = @TijdVak;
    if @AilKopJaar is null then
      call Raise(20598); //Combinatie van AangifteJaar en AangifteTijdvak niet gevonden!
    end if;

    select NawFilNawGid, NawBtwNummer into @NawGid, @NawBtwNummer from tabNawFile inner join tabNaw on (NawGid = NawFilNawGid) where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummer;
    if (@NawGid is null) then
      call Raise(20554); //Ongeldige of geen DebiteurNummer meegegeven!
    end if;

    if IsNull(@LandCode, '' ) = '' then
      call Raise(20553); //Ongeldige of geen LandCode meegegeven!
    end if;

    if not exists(select 1 from tabNawFile left outer join tabBtw on (BtwCode = NawFilBtwCode) where NawFilNawGid = @NawGid and IsNull(BtwRubriekAangifte, 0) = 7) then //Test op rubriek 3b
      call Raise(20599); //Bij deze debiteur is geen BTW-code ingevuld of de aangifterubriek van de BTW-code is ongelijk aan 3b!
    end if;

    case @RegelSoort
      when 'prestaties'      then set @RglSoort = 0;
      when 'abc'             then set @RglSoort = 1;
      when 'corr-prestaties' then set @RglSoort = 2;
      when 'corr-abc'        then set @RglSoort = 3;
      else call Raise(20523); //Ongeldige of geen RegelSoort meegegeven!
    end case;

    if @RglSoort in (1,3) then
      set @BedragDiensten = 0;
    end if;

    if @RglSoort in (0,1) then
      set @Jaar    = @AilKopJaar;
      set @Tijdvak = @AilKopTijdvak;
    else
      if @CorrectieJaar is null then
        set @Jaar = @AilKopJaar;
      else
        if (@CorrectieJaar <= @AilKopJaar) and (@CorrectieJaar >= 2000) then
          set @Jaar = @CorrectieJaar;
        else
          call Raise(20600); //Ongeldige of geen CorrectieJaar meegegeven!
        end if;
      end if;
      if @CorrectieTijdvak is null then
        set @Tijdvak = @AilKopTijdvak;
      else
        case @CorrectieTijdvak
          when '1ekwartaal' then set @TijdVak = 100;
          when '2ekwartaal' then set @TijdVak = 200;
          when '3ekwartaal' then set @TijdVak = 300;
          when '4ekwartaal' then set @TijdVak = 400;
          when 'heeljaar'   then set @TijdVak = 40;
          when 'jan'        then set @TijdVak = 101;
          when 'feb'        then set @TijdVak = 102;
          when 'mrt'        then set @TijdVak = 103;
          when 'apr'        then set @TijdVak = 204;
          when 'mei'        then set @TijdVak = 205;
          when 'jun'        then set @TijdVak = 206;
          when 'jul'        then set @TijdVak = 307;
          when 'aug'        then set @TijdVak = 308;
          when 'sep'        then set @TijdVak = 309;
          when 'okt'        then set @TijdVak = 410;
          when 'nov'        then set @TijdVak = 411;
          when 'dec'        then set @TijdVak = 412;
          when 'jan/feb'    then set @TijdVak = 113;
          when 'apr/mei'    then set @TijdVak = 214;
          when 'jul/aug'    then set @TijdVak = 315;
          when 'okt/nov'    then set @TijdVak = 416;
          else call Raise(20601); //Ongeldige of geen CorrectieTijdvak meegegeven!
        end case;
      end if;
    end if;

    if IsNull(@BtwNummerDebiteur, '') = '' then
      set @BtwNummer = @NawBtwNummer
    else
      set @BtwNummer = @BtwNummerDebiteur
    end if;

    if IsNull(@BtwNummer, '') = '' then
      call Raise(20602); //Ongeldige of geen BtwNummerDebiteur meegegeven!
    end if;

    select AilRglGid into @AilRglGid from tabICLAangifteRegel where AilRglAilKopGid = @AilKopGid and AilRglJaar = @Jaar and AilRglTijdVak = @TijdVak and AilRglSoort = @RglSoort and AilRglNawGid = @NawGid;
    if @AilRglGid is not null then
      call Raise(20603); //Combinatie van AangifteJaar, AangifteTijdvak, CorrectieJaar, CorrectieTijdvak, RegelSoort en DebiteurNummer komt al voor!
    else
      insert into tabICLAangifteRegel(AilRglAilKopGid, AilRglNawGid, AilRglSoort, AilRglTijdVak, AilRglJaar, AilRglNawObNummer, AilRglLandCode, AilRglBedragDienst, AilRglBedragLevering, AilRglBedrag)
                             values(@AilKopGid, @NawGid, @RglSoort, @TijdVak, @Jaar, @BtwNummer, @LandCode, IsNull(@BedragDiensten, 0), IsNull(@BedragLeveringen, 0), 0);

      set @AilRglGid = @@Identity;
    end if;
  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_IcpAangifte_Regel_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_IcpAangifte_Toevoegen(in @BtwNummer nchar(12), in @BtwNummerOnderdeelFiscaleEenheid nchar(12), in @AangifteJaar numeric(4,0), in @AangifteTijdvak nchar(10), in @AangemaaktDoor nchar(10),
                                                             in @AanmaakDatum timestamp, in @ContactPersoonAchternaam nchar(35), in @Telefoon nchar(25), in @Opmerking long nvarchar)
begin
  declare @AilKopGid integer;
  declare @Tijdvak   smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_IcpAangifte_Toevoegen > @BtwNummer = ' + @BtwNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then
    if IsNull(@BtwNummer, '') = '' then
      call Raise(20604); //Ongeldige of geen BtwNummer meegegeven!
    end if;

    if IsNull(@AangifteJaar, 0) < 2000 then
      call Raise(20597); //Ongeldige of geen AangifteJaar meegegeven!
    end if;

    case @AangifteTijdvak
      when '1ekwartaal' then set @TijdVak = 100;
      when '2ekwartaal' then set @TijdVak = 200;
      when '3ekwartaal' then set @TijdVak = 300;
      when '4ekwartaal' then set @TijdVak = 400;
      when 'heeljaar'   then set @TijdVak = 40;
      when 'jan'        then set @TijdVak = 101;
      when 'feb'        then set @TijdVak = 102;
      when 'mrt'        then set @TijdVak = 103;
      when 'apr'        then set @TijdVak = 204;
      when 'mei'        then set @TijdVak = 205;
      when 'jun'        then set @TijdVak = 206;
      when 'jul'        then set @TijdVak = 307;
      when 'aug'        then set @TijdVak = 308;
      when 'sep'        then set @TijdVak = 309;
      when 'okt'        then set @TijdVak = 410;
      when 'nov'        then set @TijdVak = 411;
      when 'dec'        then set @TijdVak = 412;
      when 'jan/feb'    then set @TijdVak = 113;
      when 'apr/mei'    then set @TijdVak = 214;
      when 'jul/aug'    then set @TijdVak = 315;
      when 'okt/nov'    then set @TijdVak = 416;
      else call Raise(20596); //Ongeldige of geen AangifteTijdvak meegegeven!
    end case;

    select AilKopGid into @AilKopGid from tabICLAangifteKop where AilKopTijdVak = @TijdVak and AilKopJaar = @AangifteJaar;
    if @AilKopGid is not null then
      call Raise(20605); //Combinatie van AangifteJaar en AangifteTijdvak komt al voor!
    else
      insert into tabICLAangifteKop(AilKopObNummer, AilKopObNummerFiscaleEenheid, AilKopJaar, AilKopTijdVak, AilKopAangemaaktDoor, AilKopAanmaakDatum, AilKopBplContactPersoonNaam, AilKopBplTelefoon, AilKopOpm)
                             values(@BtwNummer, @BtwNummerOnderdeelFiscaleEenheid, @AangifteJaar, @TijdVak, @AangemaaktDoor, @AanmaakDatum, @ContactPersoonAchternaam, @Telefoon, @Opmerking);

      set @AilKopGid = @@Identity;
    end if;
  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_IcpAangifte_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Inkoopfactuur_Archiefstuk_Toevoegen
( in @Leveranciernummer       nchar(10),
  in @Inkoopfactuurnummer     nchar(40),
  in @Archiefstuknummer       nchar(20),
  in @ExternId                nchar(20),
  in @IsInkoopfactuur         smallint
)
result (InkoopFactuurNr nchar(40))

begin
/* T.b.v. Bouw en Test (input parameters)
  declare @Leveranciernummer       nchar(10) = '17001955';
  declare @Inkoopfactuurnummer     nchar(40) = '201912345';
  declare @Archiefstuknummer       nchar(20) = '00000000000000000009';
  declare @ExternId                nchar(20);
  declare @IsInkoopfactuur         smallint = 1;
*/

  set @@ErrorTextProcedure = 'WebSvcProc_Inkoopfactuur_Archiefstuk_Toevoegen > ';
  // call TraceBegin('WebSvcProc_Inkoopfactuur_Archiefstuk_Toevoegen > @Archiefstuknummer = ' + @Archiefstuknummer);

  // Module controle
  if  IsModuleActive('if') = 0 then              // Module Inkoopfactuur
      call Raise(20790,_U('Optie Inkoopfactuur')     ); // (20790) '%1!' niet geactiveerd!
  end if;
  if  IsModuleActive('da') = 0 then              // Module Digitaal Archief
      call Raise(20790,_U('Optie Digitaal archief')  ); // (20790) '%1!' niet geactiveerd!
  end if;

    begin atomic
      declare @_DaIfkIfkGid       integer;
      declare @_DaIfkDarGid       integer;
      declare @_DaIfkIsFactuur    smallint;
      declare @_IfkFactuurNummer  nchar(40);
      declare @_NawGid            integer;

      // *********************************************************************
      // *** Controleer of input parameters zijn meegegeven en geldig zijn ***
      // *********************************************************************

      // Er moet een bestaande crediteurnummer zijn meegegeven
      select NawFilNawGid
      into   @_NawGid
      from   tabNawFile
      where  NawFilFonId = 'C'
      and    NawFilNummer = isnull(@Leveranciernummer,'');
      if  @_NawGid is null then
          call Raise(20613); //(20613) Ongeldige of geen LeverancierNummer meegegeven!
      end if;

      // Er moet een bestaande factuurnummer binnen de crediteur zijn meegegeven
      select IfkGid,
             IfkFactuurNummer
      into   @_DaIfkIfkGid,
             @_IfkFactuurNummer
      from   tabInkoopfactuurKop
      where  IfkNawGid        = @_NawGid
      and    IfkFactuurNummer = isnull(@Inkoopfactuurnummer,'');
      if  @_DaIfkIfkGid is null then
          call Raise(20684); //(20684) Ongeldige of geen Inkoopfactuurnummer meegegeven!
      end if;

      // 1 van beide input parameters moet zijn meegegeven
      if  isnull(@Archiefstuknummer,'') = '' and isnull(@ExternId,'') = '' then
          call Raise(20700,_U('Geen %1! of %2! meegegeven!', 'Archiefstuknummer', 'ExternId')   ); // (20700) Ongeldige waarde: %1!
      end if;

      // Er moet een bestaande Archiefstuk nummer of een bestaande Archiefstuk Extern-Id binnen de crediteur zijn meegegeven
      if  isnull(@Archiefstuknummer,'') <> '' then
          select DarGid
          into   @_DaIfkDarGid
          from   tabDigitaalArchief
          where  DarNawGid = @_NawGid
          and    DarNummer = @Archiefstuknummer;
          if  @_DaIfkDarGid is null then
              call Raise(20700,_U('Ongeldige of geen %1! meegegeven!', 'Archiefstuknummer')   ); // (20700) Ongeldige waarde: %1!
          end if;
      else
          select DarGid
          into   @_DaIfkDarGid
          from   tabDigitaalArchief
          where  DarNawGid   = @_NawGid
          and    DarExternId = @ExternId;
          if  @_DaIfkDarGid is null then
              call Raise(20700,_U('Ongeldige of geen %1! meegegeven!', 'Extern-Id')   ); // (20700) Ongeldige waarde: %1!
          end if;
      end if;

      // Controleren of @IsInkoopfactuur de waarde 0 of 1 bevat
      if  isnull(@IsInkoopfactuur,0) not in (0,1) then
          call Raise(20700,_U('Ongeldige of geen %1! meegegeven!', 'IsInkoopfactuur')   ); // (20700) Ongeldige waarde: %1!
      end if;

      // Controleren of de koppeling al gemaakt is.
      if  exists (select first 1
                  from   tabDigitaalArchiefInkoopfactuur
                  where  DaIfkIfkGid = @_DaIfkIfkGid
                  and    DaIfkDarGid = @_DaIfkDarGid) then
          call Raise(20780,_U('Koppelen Archiefstuk met Inkoopfactuur is'),_U('Koppeling is al aanwezig')   ); // (20780) %1! niet mogelijk: %2!
      end if;

      // ************************************************************
      // *** Archiefstuk daadwerkelijk koppelen aan inkoopfactuur ***
      // ************************************************************

      // Neem de waarde t.b.v. DaIfkIsFactuur over uit de input parameter
      set @_DaIfkIsFactuur = isnull(@IsInkoopfactuur,0);

      // Er kan maar 1 archiefstuk zijn aangemerkt als Inkoopfactuur
      // Zet deze status uit bij alle archiefstukken binnen deze inkoopfactuur,
      // indien het nieuwe archiefstuk de Inkoopfactuur is geworden.
      if  @_DaIfkIsFactuur = 1 then
          update tabDigitaalArchiefInkoopfactuur
          set    DaIfkIsFactuur = 0
          where  DaIfkIfkGid = @_DaIfkIfkGid;
      end if;

      // De koppeling tussen archiefstuk en inkoopfactuur toevoegen in koppeltabel
      insert into tabDigitaalArchiefInkoopfactuur
      (  DaIfkIfKGid,
         DaIfkDarGid,
         DaIfkIsFactuur
      )
      values
      (  @_DaIfkIfkGid,
         @_DaIfkDarGid,
         @_DaIfkIsFactuur
      );
    end;    // atomic

  // Ophalen resultaat
  select @Inkoopfactuurnummer as InkoopFactuurNr;

end;



create or replace procedure WebSvcProc_Inkoopfactuur_BtwRegel_Toevoegen(
  in @LeverancierNummer   nchar(10),
  in @InkoopfactuurNummer nchar(40),
  in @InkoopfactuurDatum  date,
  in @BtwCode             integer,
  in @BasisBedrag         numeric(15,3),
  in @BtwBedrag           numeric(15,3)
)

begin
  declare @_BtwCode integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Inkoopfactuur_BtwRegel_Toevoegen';
  //call TraceBegin(@@ErrorTextProcedure);

  // --- Controle: juiste modules
  if IsModuleActive('if') = 0 then
    call Raise(20905); //Optie ''Webservices Inkoopfactuur'' niet geactiveerd!
  end if;

  // Check of input parameters zijn meegegeven en geldig zijn

  if IsNull(@Leveranciernummer, '') = '' then
    call Raise(20613); //(20613) Ongeldige of geen LeverancierNummer meegegeven!
  end if;

  if ISNull(@Inkoopfactuurnummer, '') = '' then
    call Raise(20684); //(20684) Ongeldige of geen Inkoopfactuurnummer meegegeven!
  end if;

  if @Inkoopfactuurdatum is null then
    call Raise(20685); //(20685) Ongeldige of geen Inkoopfactuurdatum meegegeven!
  end if;

  if @BtwCode is null then
    call Raise(20525);  // (20525) Ongeldige of geen BtwCode meegegeven!
  end if;

  // Bestaat @BtwCode
  select BtwCode into @_BtwCode
  from   tabBtw
  where  BtwCode = @BtwCode;
  if @_BtwCode is null then
    call Raise(20525);  // (20525) Ongeldige of geen BtwCode meegegeven!
  end if;

  if @BasisBedrag is null then
    call Raise(20690);  // (20690) Ongeldige of geen BasisBedrag meegegeven
  end if;

  if @BtwBedrag is null then
    call Raise(20691);  // (20691) Ongeldige of geen BtwBedrag meegegeven
  end if;

//-------------------------------------------------------------------------------------
  begin
    declare @_NawGid integer;
    declare @_IfkGid integer;

    // --- Leverancier ---
    select NawfilNawGid into @_NawGid from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @Leveranciernummer;
    if @_NawGid is null then
      call Raise(20613); // (20613) Ongeldige of geen LeverancierNummer meegegeven!
    end if;

    // --- Inkoopfactuur ---
    select IfkGid into @_IfkGid from tabInkoopfactuurKop where IfkNawGid = @_NawGid and IfkFactuurNummer_Lengte = length(@Inkoopfactuurnummer) and IfkFactuurNummer = @Inkoopfactuurnummer and IfkFactuurdatum = @Inkoopfactuurdatum;
    if @_IfkGid is null then
      call Raise(20686, _U('Inkoopfactuur')); // (20686) %1 niet gevonden!
    end if;

    // *** Valideer lock op inkoopfactuur ***
    if LockedByUser('tabInkoopfactuurKop', string(@_IfkGid)) <> 'KingWebservice' then
      call Raise(20687, _U('Inkoopfactuur')); // (20687) %1 is niet gelockt!
    end if;

    // Er is een Btw-regel -> automatisch berekenen wordt afgezet
    update tabInkoopfactuurKop
    set    IfkBerekenBtwBlokAutom = 0
    where  IfkGid = @_IfkGid
       and IfkBerekenBtwBlokAutom <> 0;

    insert into tabInkoopfactuurBtwBlok(
      IfbIfkGid,
      IfbBtwCode,
      IfbGrondslagBedrag,
      IfbBtwBedrag
    )
    values(
      /* IfbIfkGid,          = */ @_IfkGid,
      /* IfbBtwCode,         = */ @_BtwCode,
      /* IfbGrondslagBedrag, = */ @BasisBedrag,
      /* IfbBtwBedrag,       = */ @BtwBedrag
    );
  end;
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Inkoopfactuur_FactuurRegel_Toevoegen(
  in @Leveranciernummer                      nchar(10),
  in @Inkoopfactuurnummer                    nchar(40),
  in @Inkoopfactuurdatum                     Date,
  in @Regelsoort                             nchar(5), //ART, TAR of TEKST
  in @Artikelnummer                          nchar(20),
  in @ArtikelnummerBijLev                    nchar(20),
  in @EANcode                                nchar(30),
  in @Referentie                             nchar(40),
  in @Inkoopeenheid                          nchar(20),
  in @AantalVoorraadeenhedenPerInkoopeenheid numeric(15,3),
  in @Partijnummer                           nchar(20),
  in @AantalInkoopeenheden                   Numeric(15,3),
  in @InkoopprijsPer                         nchar(30), //INKOOPEENHEID, AANTALVOORRAADEENHEID
  in @Inkoopprijs                            numeric(15,3),
  in @KortingsPercentage                     numeric(5,2),
  in @KortingsBedrag                         numeric(15,3),
  in @BtwCode                                integer,
  in @Omschrijving                           long nvarchar,
  in @Magazijnontvangstnummer                numeric(10,0),  // Indien gevuld, dan wordt de prijs op tussenrekening van die regel overgenomen (in verhouding tot het aantal)
  in @MagazijnOntvangstRegelnummer           integer         // Maar dan alleen als de magazijnontvangst reeds is geboekt (verwerkt)
)

//result(RegelNummer smallint)
begin
  // Alle variabelen die met @_ beginnen zijn lokaal en bevatten alleen gecontroleerde waarden

  // Uit NAW
  declare @_NawGid                  integer;
  declare @_BtwCodeVanNaw           integer;
  // Uit artikel
  declare @_IfrArtGid               integer;
  declare @_ArtIsPartijRegistreren  smallint;
  declare @_BtwCodeVanArtikel       integer;
  declare @_ArtAantDecAantallen     smallint;
  declare @_ArtAantDecPrijzen       smallint;
  // Uit artikelpartij
  declare @_ArtPartijGid            integer;
  // Uit inkoopfactuurkop
  declare @_IfkGid                  integer;
  // Berekend uit parameters
  declare @_IfrRegelsoort           smallint;
  declare @_IfrInkoopeenheid        nchar(20);
  declare @_IfrAantalVEperIE        numeric(15,3);
  declare @_IfrEANcode              nchar(30);
  declare @_IfrArtikelnummerBijLev  nchar(20);
  declare @_IsArtOfTarief           smallint;
  declare @_IfrBtwCode              integer;

  declare @_IfrPrijsPerSoort        smallint;
  declare @_IfrPrijsPer             numeric(15,3);
  declare @_IfrInkoopprijs          numeric(15,3);
  declare @_IfrKortingSoort         smallint;
  declare @_IfrKortingsBedrag       numeric(15,3);
  declare @_IfrKortingsPercentage   numeric(5,2);
  declare @_IfrAantalInkoopeenheden numeric(15,3);
  declare @_IfrReferentie           nchar(40);
  declare @_IfrOmschrijving         long nvarchar;
  declare @_IfrTussenrekeningBedragInPrijsPer numeric(15,3);
  declare @_IfrTussenrekeningPrijsPerAantal   numeric(15,3);
  declare @_IfrTussenrekeningValNummer        numeric(15,3);

  //Om een koppeling tussen inkoop en mag.ontv. te kunnen leggen
  declare @_MohkGid                 integer;
  declare @_MohrGid                 integer;

  // Hulpvariabele
  declare @_RegelsoortTekst         nchar(20);

  set @@ErrorTextProcedure = 'WebSvcProc_Inkoopfactuur_FactuurRegel_Toevoegen > ';
  //call TraceBegin(@@ErrorTextProcedure);

  // --- Controle: juiste modules
  if IsModuleActive('if') = 0 then
    call Raise(20905); //Optie ''Webservices Inkoopfactuur'' niet geactiveerd!
  end if;

  // ***********************
  // *** Ingangscontrole ***
  // ***********************

  // --- Leverancier ---
  select NawfilNawGid, NawFilBtwCode into @_NawGid, @_BtwCodeVanNaw from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @Leveranciernummer;
  if @_NawGid is null then
    call Raise(20613); // (20613) Ongeldige of geen LeverancierNummer meegegeven!
  end if;

  // --- Inkoopfactuurnummer ---
  if isnull(@Inkoopfactuurnummer, '') = '' then
    call Raise(20684); // (20684) Ongeldige of geen Inkoopfactuurnummer meegegeven!
  end if;

  // --- Inkoopfactuurdatum ---
  if @Inkoopfactuurdatum is null then
    call Raise(20685); // (20685) Ongeldige of geen Inkoopfactuurdatum meegegeven!
  end if;

  // --- Inkoopfactuur ---
  select IfkGid into @_IfkGid from tabInkoopfactuurKop where IfkNawGid = @_NawGid and IfkFactuurNummer = @Inkoopfactuurnummer and IfkFactuurdatum = @Inkoopfactuurdatum;
  if @_IfkGid is null then
    call Raise(20686, _U('Inkoopfactuur')); // (20686) %1! niet gevonden!
  end if;

  // *** Valideer lock op inkoopfactuur ***
  if LockedByUser('tabInkoopfactuurKop', string(@_IfkGid)) <> 'KingWebservice' then
    call Raise(20687, _U('Inkoopfactuur')); // (20687) %1! is niet gelockt!
  end if;

  // --- Regelsoort ---
  // Regelsoort parameteriseert verschillende andere controles!
  case @Regelsoort
    when 'ART'   then set @_IfrRegelsoort = 2; set @_RegelsoortTekst = _U('Artikel');    set @_IsArtOfTarief = 1;
    when 'TAR'   then set @_IfrRegelsoort = 1; set @_RegelsoortTekst = _U('Tarief');     set @_IsArtOfTarief = 1;
    when 'TEKST' then set @_IfrRegelsoort = 0; set @_RegelsoortTekst = _U('Tekstblok');  set @_IsArtOfTarief = 0;
  else
    call Raise(20677, 'Regelsoort'); // (20677) Ongeldige waarde: %1!
  end;

  if isnull(@Artikelnummer, '') <> '' then
    // Zoek artikel/tarief/tekstblok o.b.v. Artikelnummer
    select ArtGid into @_IfrArtGid from tabArtikel where Artsoort = @_IfrRegelsoort and ArtCode = @Artikelnummer;
  end if;


  if @_IfrArtGid is null and @_IfrRegelsoort = 2 /* Artikel */  then
    // --- Artikel opzoeken aan de hand van Leveranciers-code en EAN-code ---
    case
      when isnull(@ArtikelnummerBijLev, '') <> '' then
        // Zoek artikel o.b.v. artikelnummer bij leverancier
        set @_IfrArtikelnummerBijLev = @ArtikelnummerBijLev;
        select ArtGid into @_IfrArtGid
        from   tabArtikel
               inner join tabArtikelLeverancier on ArtlevArtgid = Artgid
               inner join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid
        where  ArtlevNawGid = @_NawGid
           and AldArtCodeBijLeverancier = @_IfrArtikelnummerBijLev
      when isnull(@EANcode, '') <> '' then
        // Zoek artikel o.b.v. EANcode
        set @_IfrEANcode = @EANcode;
        select ArtGid into @_IfrArtGid
        from   tabArtikel
               inner join tabArtikelEan on ArteanArtgid = ArtGid
        where  ArtEanCode = @EANcode
    end;
  end if;

  // Artikel of tarief niet gevonden? Knal boem dinges! Tekstblok niet opgegeven is best prima
  if @_IfrArtGid is null and (@_IfrRegelsoort <> 0 /*Tekst*/ or isnull(@Artikelnummer, '') <> '') then
    call Raise(20686, @_RegelsoortTekst); // (20686) %1 niet gevonden!
  end if;


  // --- Artikelafhankelijke zaken ophalen ---
  select isnull(ArtBtwCodeInkoop, ArtBtwCode), ArtIsPartijRegistreren,   ArtPrijsPer,   ArtAantDecAantallen,  ArtAantDecPrijzen
  into  @_BtwCodeVanArtikel,                  @_ArtIsPartijRegistreren, @_IfrPrijsPer, @_ArtAantDecAantallen, @_ArtAantDecPrijzen
  from   tabArtikel
  where  ArtGid = @_IfrArtGid;


  // --- Inkoopeenheid en daarvan afhankelijke velden ---
  // Hier kunnen gegevens gelezen van het artikel weer worden overschreven door inkoopeenheidgegevens
  begin
    declare @AldGid                             integer;
    declare @tmpArtCodeBijLeverancier           nchar(20);
    declare @tmpEanCode                         nchar(30);
    declare @tmpVoorraadEenhedenInInkoopEenheid numeric(15,3);
    declare @tmpInkoopPrijsPerSoort             smallint;

    set @_IfrInkoopeenheid = @Inkoopeenheid;

    select AldGid,  AldArtCodeBijLeverancier,  ArtEanCode,  AldVoorraadEenhedenInInkoopEenheid, AldInkoopPrijsPer
    into  @AldGid, @tmpArtCodeBijLeverancier, @tmpEanCode, @tmpVoorraadEenhedenInInkoopEenheid, @tmpInkoopPrijsPerSoort
    from   tabArtikelLeverancierDetail
           inner join      tabArtikelLeverancier on ArtLevGid = AldArtLevGid
           left outer join tabArtikelEan         on Arteangid = AldArtEanGid
    where  ArtlevArtgid     = @_IfrArtGid
       and AldInkoopEenheid = @_IfrInkoopeenheid
       and ArtLevNawGid     = @_NawGid;

    if @AldGid is not null then
      // Artikelnummer + EAN overnemen van de inkoopeenheid, als die niet waren ingevuld
      if isnull(@_IfrArtikelnummerBijLev, '') = '' then
        set @_IfrArtikelnummerBijLev = @tmpArtCodeBijLeverancier
      end if;
      if isnull(@_IfrEANcode, '') = '' then
        set @_IfrEANcode = @tmpEanCode;
      end if;

      // --- Aantal voorraadeenheden per inkoopeenheid ---
      if isnull(@AantalVoorraadeenhedenPerInkoopeenheid, 0) = 0 then
        set @_IfrAantalVEperIE = @tmpVoorraadEenhedenInInkoopEenheid
      else
          set @_IfrAantalVEperIE = isnull(@AantalVoorraadeenhedenPerInkoopeenheid, 0);
      end if;

      if @_IfrAantalVEperIE = 0 and @_IsArtOfTarief = 1 then
        call Raise(20677, 'AantalVoorraadeenhedenPerInkoopeenheid'); // (20677) Ongeldige waarde: %1!
      end if;

      //ACW 2022-05-06: @_IfrPrijsPer vervangen door @_IfrPrijsPerSoort
      set @_IfrPrijsPerSoort = @tmpInkoopPrijsPerSoort;
    end if;
  end;


  // --- Referentienummer ---
  // Indien niet meegegeven, dan overnemen van de kop
  if isnull(@Referentie, '') = '' then
    select IfkReferentienummer into @_IfrReferentie from tabInkoopfactuurKop where IfkGid = @_IfkGid;
  else
    set @_IfrReferentie = @Referentie;
  end if;


  // --- Partijnummer ---
  if @_ArtIsPartijRegistreren = 1 and isnull(@Partijnummer, '') <> '' then
    select ArtPartijGid
    into  @_ArtPartijGid
    from   tabArtikelPartij
    where  ArtpartijArtGid = @_IfrArtGid and ArtPartijNummer = @Partijnummer;
    if @_ArtPartijGid is null then
      call Raise(20526); // (20526) Ongeldige of geen PartijNummer meegegeven!
    end if;
  end if;


  // --- Aantal inkoopeenheden ---
  if @_IsArtOfTarief = 1 and isnull(@AantalInkoopeenheden, 0) = 0 then
    call Raise(20677, 'AantalInkoopeenheden'); // (20677) Ongeldige waarde: %1!
  else
    set @_IfrAantalInkoopeenheden = @AantalInkoopeenheden;
  end if;


  // --- Inkoopprijs per ---
  case @_IfrRegelsoort
    when 0 then /*Tekst*/
      set @_IfrPrijsPerSoort = 0;
    when 1 then /*Tarief*/
      set @_IfrPrijsPerSoort = 0;
    when 2 then /*Artikel*/
      case @InkoopprijsPer
        when 'INKOOPEENHEID'         then set @_IfrPrijsPerSoort = 0;
        when 'AANTALVOORRAADEENHEID' then set @_IfrPrijsPerSoort = 1;
      else
        call Raise(20677, 'InkoopprijsPer'); // (20677) Ongeldige waarde: %1!
      end case;
  end case;

  // Parameters die alleen voor artikel/tarief gelden
  if @_IsArtOfTarief = 1 then

    // --- Inkoopprijs ---
    if isnull(@Inkoopprijs, -1) < 0 then
      call Raise(20677, 'Inkoopprijs'); // (20677) Ongeldige waarde: %1!
    end if;
    set @_IfrInkoopprijs = @Inkoopprijs;

    // --- Kortingspercentage ---
    if @KortingsPercentage < -100 or @KortingsPercentage > 100 then
      call Raise(20677, 'Kortingspercentage'); // (20677) Ongeldige waarde: %1!
    end if;


    // --- Kortingssoort ---
    if isnull(@KortingsPercentage, 0.0) <> 0 and isnull(@KortingsBedrag, 0.0) <> 0.0 then
      call Raise(20688); // (20688) Het is niet mogelijk om zowel een kortingsbedrag als een -percentage op te geven!
    end if;

    if @KortingsPercentage is null or isnull(@KortingsBedrag, 0.0) <> 0.0 then
      set @_IfrKortingSoort = 0; /*bedrag*/
      set @_IfrKortingsBedrag = @KortingsBedrag;
      set @_IfrKortingsPercentage = null;
    else
      set @_IfrKortingSoort = 1; /*percentage*/
      set @_IfrKortingsBedrag = null;
      set @_IfrKortingsPercentage = isnull(@KortingsPercentage, 0.0);
    end if;

    // --- BTW ---
    if @BtwCode is not null then
      if not exists(select first 1 from tabBTW where BtwCode = @BtwCode) then
        call Raise(20525); //(20525) Ongeldige of geen BtwCode meegegeven!
      end if;
      set @_IfrBtwCode = @BtwCode;
    end if;

    // Valider aantal decimalen voor artikel/tarief
    if round(@AantalVoorraadeenhedenPerInkoopeenheid, @_ArtAantDecAantallen) <> @AantalVoorraadeenhedenPerInkoopeenheid then
      call Raise(20692, 'AantalVoorraadeenhedenPerInkoopeenheid'); //(20692) Aantal decimalen van %1! is groter dan toegestaan bij het artikel of tarief!
    end if;
    if round(@AantalInkoopeenheden, @_ArtAantDecAantallen) <> @AantalInkoopeenheden then
      call Raise(20692, 'AantalInkoopeenheden'); //(20692) Aantal decimalen van %1! is groter dan toegestaan bij het artikel of tarief!
    end if;
    if round(@Inkoopprijs, @_ArtAantDecPrijzen) <> @Inkoopprijs then
      call Raise(20692, 'Inkoopprijs'); //(20692) Aantal decimalen van %1! is groter dan toegestaan bij het artikel of tarief!
    end if;
    if round(@KortingsBedrag, @_ArtAantDecPrijzen) <> @KortingsBedrag then
      call Raise(20692, 'KortingsBedrag'); //(20692) Aantal decimalen van %1! is groter dan toegestaan bij het artikel of tarief!
    end if;


    // Controle op magazijnontvangstregel: ingevuld, dan moet die bestaan EN van zelfde leverancier en Artikel
    // Het geboekte bedrag op de tussenrekening wordt dan hier weer gebruikt om de tussenrekening weg te boeken
    if @Magazijnontvangstnummer is not null and @MagazijnOntvangstRegelnummer is not null then
      begin
        declare @_NawFilNummer nchar(10);
        declare @_MohrArtNummer nchar(20);

        select MohkGid,   MohaNawFilNummer
        into   @_MohkGid, @_NawFilNummer
        from   tabMagazijnOntvangstHistKop
               inner join tabMagazijnOntvangstHistAdres on MohaGid = MohkMohaGidLeverancier
        where MohkNummer = @Magazijnontvangstnummer;

        if @_MohkGid is null then
          call Raise(20720, _U('Magazijnontvangst') || ' ' || @Magazijnontvangstnummer); // (20720) %1 niet gevonden!
        end if;
        //Controleer of de magazijnontvangst van dezelfde leverancier is
        if @_NawFilNummer <> @Leveranciernummer then
          call Raise(20701, _U('Magazijnontvangst %1! is niet van dezelfde leverancier',  @Magazijnontvangstnummer)); // (20701) Ongeldige combinatie: %1!
        end if;
        // Controleer of de magazijnontvangstregel hetzelfde artikel is
        select MohrGid, MohrArtCode into @_MohrGid, @_MohrArtNummer from tabMagazijnontvangstHistRegel where MohrMohkGid = @_MohkGid and MohrRegelnr = @MagazijnOntvangstRegelnummer;
        if @_MohrArtNummer <> @Artikelnummer then
          call Raise(20701, _U('Magazijnontvangstregel is niet van hetzelfde artikel')); // (20701) Ongeldige combinatie: %1!
        end if;
      end;

      // Bereken de bedragen op de tussenrekening
      select MohkValNummer into @_IfrTussenrekeningValNummer from tabMagazijnOntvangstHistKop where MohkGid = @_MohkGid;
      select MohrPrijsPer,
             MohrTussenrekeningTotaalGeboekt / if (MohrAantalInkoopEenheden * MohrVoorraadEenhedenInInkoopEenheid) = 0 then 1 else (MohrAantalInkoopEenheden * MohrVoorraadEenhedenInInkoopEenheid) endif * MohrPrijsPer // Als tegen werkelijke inkoopprijs geboekt, dan is het prijsverschil al bij de mag.ontv. geboekt; hier NIET afronden!
      into   @_IfrTussenrekeningPrijsPerAantal,
             @_IfrTussenrekeningBedragInPrijsPer
      from tabMagazijnontvangstHistRegel where MohrGid = @_MohrGid;
    end if;



  else
    set @_IfrInkoopprijs        = 0.00;
    set @_IfrKortingSoort       = 1; /*percentage*/
    set @_IfrKortingsBedrag     = null;
    set @_IfrKortingsPercentage = null;
  end if;

  // --- Omschrijving ---
  if isnull(@Omschrijving, '') <> '' then
    set @_IfrOmschrijving = @Omschrijving;
  else
    begin
    // Omschrijving lezen uit bestaande art/lev/IE combinatie, of
      declare @_nawTaalGid integer;

      select NawTaalGid into @_nawTaalGid from tabNaw where NawGid = @_NawGid;

      set @_IfrOmschrijving = LeesArtikelTekst(/* @ArtGid = */        @_IfrArtGid,
                                               /* @NawGid = */        @_NawGid,
                                               /* @InkoopEenheid = */ @_IfrInkoopeenheid,
                                               /* @ArtPartijGid = */  @_ArtPartijGid,
                                               /* @TaalGid = */       @_nawTaalGid,
                                               /* @TbvInkoop = */     1
                                              );
    end;
  end if;


  // *******************
  // *** Verwerkfase ***
  // *******************
  begin
    declare @_IfrRegelNr integer;

    // -- Default BTW---
    if @_IfrBtwCode is null and @_IsArtOfTarief = 1 then
      if exists(select first 1 from tabBtw where BtwCode = @_BtwCodeVanNaw and BtwPercentage = 0) then
        // Leverancier heeft BTW met 0%, dus die gebruiken
        set @_IfrBtwCode = @_BtwCodeVanNaw
      else
        case @_IfrRegelsoort
          when 1 /*Tarief*/ then
            if exists(select first 1 from tabBtw where BtwCode = @_BtwCodeVanArtikel and BtwSoort = 2 /*Te verrekenen BTW*/) then
              set @_IfrBtwCode = @_BtwCodeVanArtikel
            end if;
          when 2 /*Artikel*/ then
            set @_IfrBtwCode = @_BtwCodeVanArtikel
        end case;
      end if;
      // Als nog steeds geen BTW gevonden, dan maar melden
      if @_IfrBtwCode is null then
        call Raise(20693); //(20693) Ongeldige of geen BtwCode meegegeven en de BtwCode kan niet worden bepaald!
      end if;
    end if;

    // --- Regelnummr ---
    select max(IfrRegelNr) + 1 into @_IfrRegelNr from tabInkoopfactuurRegel where IfrIfkGid = @_IfkGid;
    if @_IfrRegelNr is null then
      set @_IfrRegelNr = 1;
    end if;

    // Nu de regel toevoegen
    insert into tabInkoopfactuurRegel (
      IfrIfkGid,
      IfrRegelNr,
      IfrRegelSoort,
      IfrArtGid,
      IfrArtikelNummerLeverancier,
      IfrEANcode,
      IfrInkoopeenheid,
      IfrVoorraadeenhedenInInkoopeenheid,
      IfrArtPartijGid,
      IfrAantal,
      IfrPrijsPerSoort,
      IfrPrijsPer,
      IfrPrijs,
      IfrBtwCode,
      IfrKortingSoort,
      IfrKortingBedrag,
      IfrKortingPercentage,
      IfrReferentienummer,
      IfrReferentienummer_lengte,
      IfrRegeltotaalExclBtw,
      IfrAantalDecimalenVoorAantallen,
      IfrAantalDecimalenVoorPrijzen,
      IfrOms,
      IfrTussenrekeningBedragInPrijsPer,
      IfrTussenrekeningPrijsPerAantal,
      IfrTussenrekeningValNummer

    )
    values (
      /*IfrIfkGid                          = */ @_IfkGid,
      /*IfrRegelNr                         = */ @_IfrRegelNr,
      /*IfrRegelSoort                      = */ @_IfrRegelsoort,
      /*IfrArtGid                          = */ @_IfrArtGid,
      /*IfrArtikelNummerLeverancier        = */ @_IfrArtikelnummerBijLev,
      /*IfrEANcode                         = */ @_IfrEANcode,
      /*IfrInkoopeenheid                   = */ @_IfrInkoopeenheid,
      /*IfrVoorraadeenhedenInInkoopeenheid = */ @_IfrAantalVEperIE,
      /*IfrArtPartijGid                    = */ @_ArtPartijGid,
      /*IfrAantal                          = */ @_IfrAantalInkoopeenheden,
      /*IfrPrijsPerSoort                   = */ @_IfrPrijsPerSoort,
      /*IfrPrijsPer                        = */ @_IfrPrijsPer,
      /*IfrPrijs                           = */ @_IfrInkoopprijs,
      /*IfrBtwCode                         = */ @_IfrBtwCode,
      /*IfrKortingSoort                    = */ @_IfrKortingSoort,
      /*IfrKortingBedrag                   = */ @_IfrKortingsBedrag,
      /*IfrKortingPercentage               = */ @_IfrKortingsPercentage,
      /*IfrReferentienummer                = */ @_IfrReferentie,
      /*IfrReferentienummer_lengte         = */ length(@_IfrReferentie),
      /*IfrRegeltotaalExclBtw              = */ 0.0, // Wordt berekend in de trigger
      /*IfrAantalDecimalenVoorAantallen    = */ @_ArtAantDecAantallen,
      /*IfrAantalDecimalenVoorPrijzen      = */ @_ArtAantDecPrijzen,
      /*IfrOms                             = */ @_IfrOmschrijving,
                                                @_IfrTussenrekeningBedragInPrijsPer,
                                                @_IfrTussenrekeningPrijsPerAantal,
                                                @_IfrTussenrekeningValNummer
    );
  end;

  set @@ErrorTextProcedure = 'WebSvcProc_Inkoopfactuur_FactuurRegel_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;

