create or replace procedure WebSvcProc_Inkoopfactuur_LockVrijgeven(
  in @Leveranciernummer   nchar(10),
  in @Inkoopfactuurnummer nchar(40),
  in @Inkoopfactuurdatum  date
  )

begin
  declare @_nawGid   integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Inkoopfactuur_LockVrijgeven';
  //call TraceBegin(@@ErrorTextProcedure);

  // --- Controle: juiste modules
  if IsModuleActive('if') = 0 then
    call Raise(20905); //Optie ''Webservices Inkoopfactuur'' niet geactiveerd!
  end if;

  if IsNull(@Leveranciernummer, '') = '' then
    call Raise(20613); //(20613) Ongeldige of geen LeverancierNummer meegegeven!
  end if;

  select NawFilNawGid into @_nawGid from tabNawFile where NawFilFonId = 'C' and NawFilNummer = @Leveranciernummer;
  if (@_nawGid is null) then
    call Raise(20613); //(20613) Ongeldige of geen LeverancierNummer meegegeven!
  end if;

  if ISNull(@Inkoopfactuurnummer, '') = '' then
    call Raise(20684); //(20684) Ongeldige of geen Inkoopfactuurnummer meegegeven!
  end if;

  if @Inkoopfactuurdatum is null then
    call Raise(20685); //(20685) Ongeldige of geen Inkoopfactuurdatum meegegeven!
  end if;

  //-------------------------------------------------------------------------------------
  begin
    declare @_ifkGid integer;
    declare @_BerekenBtwBlokAutom smallint;
    declare @_qLockGid integer;

    // zoek inkoopfactuur op
    select ifkGid, IfkBerekenBtwBlokAutom into @_ifkGid, @_BerekenBtwBlokAutom from tabInkoopfactuurKop where IfkNawGid = @_nawGid and IfkFactuurNummer = @Inkoopfactuurnummer and IfkFactuurdatum = @Inkoopfactuurdatum;
    if @_ifkGid is null then
       call Raise(20686, _U('Inkoopfactuur')); // (20686) %1 niet gevonden!
    end if;

    // zoek lock van de inkoopfactuur op
    select first qLockGid into @_qLockGid from qtabLock where qLockUser = 'KingWebservice' and qLockTableName = 'tabInkoopfactuurKop' and qLockPkey = @_ifkGid;
    if @_qLockGid is null then
      call Raise(20548); //Lock niet gevonden!
    end if;

    // Herbereken BtwBlok indien nodig
    if @_BerekenBtwBlokAutom = 1 then
      call InkoopfactuurAanmakenBtwBlok(@_ifkGid);
    end if;

    // Geef lock vrij
    delete qtabLock where qLockGid = @_qLockGid;

  end;

  set @@ErrorTextProcedure = 'WebSvcProc_Inkoopfactuur_LockVrijgeven';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Inkoopfactuur_Toevoegen(
  in @LeverancierNummer   nchar(10),
  in @InkoopfactuurNummer nchar(40),
  in @InkoopfactuurDatum  date,
  in @VervalDatum         date,
  in @Betalingskenmerk    nchar(140),
  in @Betalingsconditie   integer,
  in @ValutaCode          nchar(3),
  in @BerekenBTWBlok      smallint,
  in @Referentienummer    nchar(40),
  in @Omschrijving        nchar(40),
  in @Goedgekeurd         smallint
)

begin
  declare @_NawGid integer;
  declare @_BtcNummer integer;
  declare @_ValNummer integer;
  declare @_VervalDatum date;
  declare @_Betalingskenmerk nchar(140);
  declare @_Referentienummer nchar(40);
  declare @_BerekenBTWBlok smallint;
  declare @_IsGoedgekeurd smallint;
  declare @_GoedgekeurdOp datetime;
  declare @_GoedgekeurdDoor nchar(20);
  declare @_AanGemaaktOp datetime;
  declare @_AanGemaaktDoor nchar(20);

  //call TraceBegin('WebSvcProc_Inkoopfactuur_Toevoegen');

  //Check de gegevens
  call WebSvcHulpProc_Inkoopfactuur_ValideerKopgegevens(
    @Mode = 1,
    @LeverancierNummer = @LeverancierNummer,
    @InkoopfactuurNummer = @InkoopfactuurNummer,
    @InkoopfactuurDatum = @InkoopfactuurDatum,
    @Betalingsconditie = @Betalingsconditie,
    @ValutaCode = @ValutaCode,
    @VervalDatum = @VervalDatum,
    @Betalingskenmerk = @Betalingskenmerk,
    @Referentienummer = @Referentienummer,
    @BerekenBTWBlok = @BerekenBTWBlok,
    @Goedgekeurd = @Goedgekeurd,
    @_NawGid = @_NawGid,
    @_BtcNummer = @_BtcNummer,
    @_ValNummer = @_ValNummer,
    @_VervalDatum = @_VervalDatum,
    @_Betalingskenmerk = @_Betalingskenmerk,
    @_Referentienummer = @_Referentienummer,
    @_BerekenBTWBlok = @_BerekenBTWBlok,
    @_IsGoedgekeurd = @_IsGoedgekeurd,
    @_GoedgekeurdOp = @_GoedgekeurdOp,
    @_GoedgekeurdDoor = @_GoedgekeurdDoor,
    @_AanGemaaktOp = @_AanGemaaktOp,
    @_AanGemaaktDoor = @_AanGemaaktDoor
  );

  begin
    declare @_IfkGid integer;
    declare @_LockResult integer default 0;

    insert into tabInkoopfactuurKop(
      IfkNawGid,
      IfkFactuurNummer,
      IfkFactuurdatum,
      IfkVervaldatum,
      IfkBetalingskenmerk,
      IfkBtcNummer,
      IfkValNummer,
      IfkBerekenBtwBlokAutom,
      IfkReferentienummer,
      IfkOmschrijving,
      IfkIsGoedgekeurd,
      IfkGoedgekeurdDoor,
      IfkGoedgekeurdOp,
      IfkAangemaaktDoor,
      IfkAangemaaktOp
    )
    values (
      /* IfkNawGid,              = */ @_NawGid,
      /* IfkFactuurNummer,       = */ @InkoopfactuurNummer,
      /* IfkFactuurdatum,        = */ @InkoopfactuurDatum,
      /* IfkVervaldatum,         = */ @_VervalDatum,
      /* IfkBetalingskenmerk,    = */ @_Betalingskenmerk,
      /* IfkBtcNummer,           = */ @_BtcNummer,
      /* IfkValNummer,           = */ @_ValNummer,
      /* IfkBerekenBtwBlokAutom, = */ @_BerekenBTWBlok,
      /* IfkReferentienummer,    = */ @_Referentienummer,
      /* IfkOmschrijving,        = */ @Omschrijving,
      /* IfkIsGoedgekeurd,       = */ @_IsGoedgekeurd,
      /* IfkGoedgekeurdDoor,     = */ @_GoedgekeurdDoor,
      /* IfkGoedgekeurdOp,       = */ @_GoedgekeurdOp,
      /* IfkAangemaaktDoor,      = */ @_AanGemaaktDoor,
      /* IfkAangemaaktOp         = */ @_AanGemaaktOp
    );

    set @_IfkGid = @@Identity;

    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabInkoopfactuurKop', @_IfkGid, @_LockResult, 0, 'KingWebservice');
    if @_LockResult != 0 then
      call Raise(20370, _U('Nieuwe inkoopfactuur')); //(20370) %1! kan niet worden gelockt!
    end if;
  end;

  //call TraceEind('WebSvcProc_Inkoopfactuur_Toevoegen');
end;


create or replace procedure WebSvcProc_InkoopFactuur_Verwerken(
                                in @LeverancierNummer nchar(10),
                                in @InkoopFactuurnummer nchar(40),
                                in @Boekdatum date,                 // Indien leeg, dan wordt huidige datum gebruikt
                                in @BoekStukNummer numeric(10,0),   // Indien leeg, dan op basis van instelling van dagboek
                                in @BoekgangNummer integer)         // Indien leeg, dan wordt een nieuw boekgangnummer gemaakt

result(BoekstukNummer numeric(10,0), BoekgangNummer integer)
//call WebSvcProc_InkoopFactuur_Verwerken('17001540', '445566', /* boekdatum: */ null,       /* geen boekstuknummer: */ null, /* geen boekgangnummer: */ null)  --> foutmelding: boekdatum valt niet in een boekjaar
//call WebSvcProc_InkoopFactuur_Verwerken('17001540', '757', /* boekdatum: */ '2021-12-25',  /*      boekstuknummer: */ 15,   /* boekgangnummer: */ 10)  --> is verwerkt: dat is ok.
begin
  // variabelen
  declare @_IfkGid integer;
  declare @_DgbGid integer;
  declare @_BoekgangGid integer;
  declare @_IfkIsGoedgekeurd integer;
  declare @_IfkIsVerwerkt integer;
  declare @_BjGid integer;

 //call TraceBegin('WebSvcProc_InkoopFactuur_Verwerken');

  // --- Controle: juiste modules
  if IsModuleActive('if') = 0 then
    call Raise(20905); //Optie ''Webservices Inkoopfactuur'' niet geactiveerd!
  end if;

  // @_IfkGid opvragen
  select IfkGid, IfkIsGoedgekeurd, IfkIsVerwerkt into @_IfkGid, @_IfkIsGoedgekeurd, @_IfkIsVerwerkt
  from   tabInkoopFactuurKop
  inner join tabNawFile on NawFilNawGid = IfkNawGid and NawFilNummer = @LeverancierNummer and NawFilFonId = 'C'
  where  IfkFactuurNummer = @InkoopFactuurnummer;

  if @_IfkGid is null then
    call Raise(20780, _U('Verwerken inkoopfactuur'),_U('Inkoopfactuur niet gevonden'));  // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if @_IfkIsGoedgekeurd = 0  then
    call Raise(20780, _U('Verwerken inkoopfactuur'),_U('Inkoopfactuur is niet goedgekeurd'));  // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if @_IfkIsVerwerkt = 1  then
    call Raise(20780, _U('Verwerken inkoopfactuur'),_U('Inkoopfactuur is al verwerkt'));  // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // @_DgbGid opvragen
  select MagVastInkDgbGid into @_DgbGid from tabMagazijnOntvangstenVasteGegevens;

  if @_DgbGid is null then
    call Raise(20780, _U('Verwerken inkoopfactuur'),_U('Geen dagboekcode ingevuld bij vaste gegevens inkoopfacturen!') ); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // @Boekdatum bepalen en controleren
  if @Boekdatum is null then
    set @Boekdatum = now();
  end if;

  // call BepaalBoekjaarEnPeriode(@Boekdatum, @_BjGid, @_PerNr); wanneer @BoekDatum niet in een boekjaar valt, dan geeft deze sp altijd de eerste of de laatste boekjaar terug
  select PerBjGid into @_BjGid from tabPeriode where @Boekdatum between BeginDatum and EindDatum;
  if @_BjGid is null then
	  call Raise(20780, _U('Verwerken inkoopfactuur'),_U('Boekdatum valt niet in een boekjaar!') ); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // @_BoekgangGid opvragen
  set @_BoekgangGid = null;
  if @BoekgangNummer is not null then
    select BoekgangGid into @_BoekgangGid from tabBoekingsGang
    where  BoekgangNummer = @BoekgangNummer and BoekGangBjGID = @_BjGid;

    if @_BoekgangGid is null then
      call Raise(20780, _U('Verwerken inkoopfactuur'),_U('Meegegeven boekgangnummer niet gevonden'));  // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    // @_JpDgbGID opvragen
    begin
      declare @_JpDgbGID integer;
      select first JpDgbGID into @_JpDgbGID from tabJournaalpost
      where JpBoekGangGID = @_BoekgangGid
      order by BoekDatum, JpGID;

      if (@_JpDgbGID is not null) and (@_DgbGid <> @_JpDgbGID) then
        call Raise(20780, _U('Verwerken inkoopfactuur'),_U('Dagboek van eerste journaalpost is niet hetzelfde als het dagboek in vaste gegevens!'));  // <Actie> niet mogelijk. Reden: <Reden>.
      end if;
    end;
  end if;

  // inkoopfactuur verwerken
  call BoekInkoopfactuur(@@SpId, @@LoginTime, @_IfkGid, @BoekDatum, /* @KeepBoekgangOpen: sluiten*/ 0, @_DgbGid, @BoekstukNummer, @_BoekgangGid);

  // output voor de webservice
  select
    @BoekstukNummer as BoekstukNummer,
    (select tabBoekingsGang.BoekgangNummer from tabBoekingsGang where  BoekgangGid = @_BoekgangGid) as BoekgangNummer;

 //call TraceEind('WebSvcProc_InkoopFactuur_Verwerken');
end;





create or replace procedure WebSvcProc_InkoopFactuur_Verwijderen(
                                in @LeverancierNummer nchar(10),
                                in @InkoopFactuurnummer nchar(40))
//call WebSvcProc_InkoopFactuur_Verwerken('17001540', '445566')
begin
  declare @_IfkGid        integer;
  declare @_IfkIsVerwerkt integer;
  declare @_Result        integer;
  declare @_NawGid        integer;

 //call TraceBegin('WebSvcProc_InkoopFactuur_Verwijderen');

  // --- Controle: juiste modules
  if IsModuleActive('if') = 0 then
    call Raise(20905); //Optie ''Webservices Inkoopfactuur'' niet geactiveerd!
  end if;

   // @_NawGid opvragen
  select NawFilNawGid into @_NawGid
  from   tabNawFile
  where  NawFilNummer = @LeverancierNummer and NawFilFonId = 'C';

  if @_NawGid is null then
    call Raise(20780, _U('Verwijderen inkoopfactuur'),_U('Ongeldige of geen %1! meegegeven', 'LeverancierNummer'));  // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // @_IfkGid opvragen
  select IfkGid, IfkIsVerwerkt into @_IfkGid, @_IfkIsVerwerkt
  from   tabInkoopFactuurKop
  where  IfkFactuurNummer = @InkoopFactuurnummer and IfkNawGid = @_NawGid;

  if @_IfkGid is null then
    call Raise(20780, _U('Verwijderen inkoopfactuur'),_U('Ongeldige of geen %1! meegegeven', 'InkoopFactuurnummer'));  // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if @_IfkIsVerwerkt = 1  then
    call Raise(20780, _U('Verwijderen inkoopfactuur'),_U('Inkoopfactuur is al verwerkt'));  // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  call LockSetOnId(@@SpId, @@LoginTime , 1 /* exclusief */, 'tabInkoopFactuurKop', @_IfkGid, @_Result);
  if @_Result = 0 then
    delete tabInkoopfactuurKop where IfkGid = @_IfkGid;
    call LockreleaseOnId(@@SpId, @@LoginTime, 1 /* exclusief */, 'tabInkoopFactuurKop', @_IfkGid);
  else
    call Raise(20780, _U('Verwijderen inkoopfactuur'),_U('Inkoopfactuur is in gebruik'));  // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

 //call TraceEind('WebSvcProc_InkoopFactuur_Verwijderen');
end;


create or replace procedure WebSvcProc_Inkoopfactuur_Wijzigen(
  in @LeverancierNummer nchar(10) default null,
  in @InkoopfactuurNummer nchar(40) default null,
  in @InkoopfactuurDatum date default null,
  in @Omschrijving nchar(40) default null,
  in @Betalingsconditie integer default null,
  in @VervalDatum date default null,
  in @Betalingskenmerk nchar(140) default null,
  in @Referentienummer nchar(40) default null,
  in @BerekenBTWBlok smallint default null,
  in @Goedgekeurd smallint default null,
  in @GoedgekeurdOp datetime default null,
  in @GoedgekeurdDoor nchar(20) default null
)

begin atomic
  declare @_IfkGid integer;
  declare @_BtcNummer integer;
  declare @_ValNummer integer;
  declare @_VervalDatum date;
  declare @_Betalingskenmerk nchar(140);
  declare @_Referentienummer nchar(40);
  declare @_BerekenBTWBlok smallint;
  declare @_IsGoedgekeurd smallint;
  declare @_GoedgekeurdOp datetime;
  declare @_GoedgekeurdDoor nchar(20);
  declare @_LockResult integer default 0;

  //call TraceBegin('WebSvcProc_Inkoopfactuur_Wijzigen');

  //Check de gegevens
  call WebSvcHulpProc_Inkoopfactuur_ValideerKopgegevens(
    @Mode = 0,
    @LeverancierNummer = @LeverancierNummer,
    @InkoopfactuurNummer = @InkoopfactuurNummer,
    @InkoopfactuurDatum = @InkoopfactuurDatum,
    @Betalingsconditie = @Betalingsconditie,
    @VervalDatum = @VervalDatum,
    @Betalingskenmerk = @Betalingskenmerk,
    @Referentienummer = @Referentienummer,
    @BerekenBTWBlok = @BerekenBTWBlok,
    @Goedgekeurd = @Goedgekeurd,
    @GoedgekeurdOp = @GoedgekeurdOp,
    @GoedgekeurdDoor = @GoedgekeurdDoor,
    @_IfkGid = @_IfkGid,
    @_BtcNummer = @_BtcNummer,
    @_VervalDatum = @_VervalDatum,
    @_Betalingskenmerk = @_Betalingskenmerk,
    @_Referentienummer = @_Referentienummer,
    @_BerekenBTWBlok = @_BerekenBTWBlok,
    @_IsGoedgekeurd = @_IsGoedgekeurd,
    @_GoedgekeurdOp = @_GoedgekeurdOp,
    @_GoedgekeurdDoor = @_GoedgekeurdDoor
  );

  //Locken
  if LockedById(@@SpId, @@LoginTime, 1 /*exclusieve lock*/, 'tabInkoopfactuurKop', @_IfkGid) = 0  then
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabInkoopfactuurKop', @_IfkGid, @_LockResult, 0, 'KingWebservice');
    if @_LockResult != 0 then
      call Raise(20370, _U('Inkoopfactuur')); //(20370) %1! kan niet worden gelockt!
    end if;
  end if;

  update tabInkoopfactuurKop
  set IfkOmschrijving = isNull(@Omschrijving, IfkOmschrijving),
      IfkBtcNummer = @_BtcNummer,
      IfkVervaldatum = @_VervalDatum,
      IfkBetalingskenmerk = @_Betalingskenmerk,
      IfkReferentienummer = @_Referentienummer,
      IfkBerekenBtwBlokAutom = @_BerekenBTWBlok,
      IfkIsGoedgekeurd = @_IsGoedgekeurd,
      IfkGoedgekeurdOp = @_GoedgekeurdOp,
      IfkGoedgekeurdDoor = @_GoedgekeurdDoor
  where IfkGid = @_IfkGid;

  //call TraceEind('WebSvcProc_Inkoopfactuur_Wijzigen');
end;


create or replace procedure WebSvcProc_Opbrengstgroep_ToevoegenWijzigen(in @OpbrengstgroepNummer nchar(4), in @Omschrijving nchar(40), in @Soort nchar(8), in @ParagraafSoort nchar(10), in @RekeningNummer nchar(10))
begin
  declare @OpbrGrpGid  integer;
  declare @GrpSoortGid integer;
  declare @RksGid      integer;
  declare @IsGoederen  smallint;
  declare @ParSoort    smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Opbrengstgroep_ToevoegenWijzigen > @OpbrengstgroepNummer = ' + @OpbrengstgroepNummer;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wf') <> 0 then

    if (IsNull(@OpbrengstgroepNummer, '') = '') or (RegExp_Substr(@OpbrengstgroepNummer, '\D') is not null) then   //Mogen allen maar cijfers zijn
      call Raise(20593); //Ongeldige of geen OpbrengstgroepNummer meegegeven!
    end if;

    case @Soort
      when 'DIENST' then set @IsGoederen = 0;
      when 'GOED'   then set @IsGoederen = 1;
      else call Raise(20594); //Ongeldige of geen Soort meegegeven!
    end case;

    if IsNull(@ParagraafSoort, '') <> '' then
      case @ParagraafSoort
        when 'OPBR'      then set @ParSoort =  30;
        when 'KP'        then set @ParSoort =  40;
        when 'VRD'       then set @ParSoort =  50;
        when 'KORT'      then set @ParSoort =  60;
        when 'HERW'      then set @ParSoort =  80;
        when 'PRVERSCH'  then set @ParSoort =  90;
        when 'VRDVERSCH' then set @ParSoort = 100;
        else call Raise(20595); //Ongeldige of geen ParagraafSoort meegegeven!
      end case;
      select RksGid into @RksGid from tabRekeningschema where RksInvoer = @RekeningNummer;
      if @RksGid is null then
        call Raise(20547); //Ongeldige of geen RekeningNummer meegegeven!
      end if;
    else
      if IsNull(@RekeningNummer, '') <> '' then
        call Raise(20547); //Ongeldige of geen RekeningNummer meegegeven!
      end if;
    end if;

    select OpbrGrpGid into @OpbrGrpGid from tabOpbrengstGroep where OpbrGrpNummer = @OpbrengstgroepNummer;
    //call Trace('@OpbrGrpGid = '+string(@OpbrGrpGid));
    if @OpbrGrpGid is null then
      insert into tabOpbrengstGroep (IsOpbrGrpGoederen, OpbrGrpNummer, OpbrGrpOms)
                             values (@IsGoederen, @OpbrengstgroepNummer, @Omschrijving);
      set @OpbrGrpGid = @@Identity;
    else
      update tabOpbrengstGroep set IsOpbrGrpGoederen = IsNull(@IsGoederen, IsOpbrGrpGoederen), OpbrGrpOms = IsNull(@Omschrijving, OpbrGrpOms) where OpbrGrpGid = @OpbrGrpGid
    end if;

    if (@ParSoort is not null) then
      select GrpSoortGid into @GrpSoortGid from tabOpbrengstGroepSoort where GrpSoortGrpGid = @OpbrGrpGid and GrpSoortParSoort = @ParSoort;
      //call Trace('@GrpSoortGid = '+string(@GrpSoortGid));
      if @GrpSoortGid is null then
        insert into tabOpbrengstGroepSoort (GrpSoortGrpGid, GrpSoortParSoort, GrpSoortRksGid)
                                    values (@OpbrGrpGid, @ParSoort, @RksGid);
      else
        update tabOpbrengstGroepSoort set GrpSoortRksGid = IsNull(@RksGid, if @RekeningNummer is null then GrpSoortRksGid else null endif) where GrpSoortGrpGid = @OpbrGrpGid and GrpSoortParSoort = @ParSoort;
      end if;
    end if;
  else
    call Raise(20902); //Optie ''Webservices Financieel'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Opbrengstgroep_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_OpenstaandePost_Wijzigen(in @BoekjaarCode nchar(10), in @Rekeningnummer nchar(10), in @FactuurNummer nchar(40), in @PostIsGeblokkeerd smallint,
                                                                in @PostIsGefiatteerd smallint, in @FiatteringGewijzigdDoor nchar(40), in @Opmerking long nvarchar,
                                                                in @BetalingsKenmerk nchar(140) default null)
begin
  declare @BjGid                  integer;
  declare @RksGid                 integer;
  declare @OspGid                 integer;
  declare @OrigineleGebruikerCode nchar(20);

  set @@ErrorTextProcedure = 'WebSvcProc_OpenstaandePost_Wijzigen > @BoekjaarCode = ' + @BoekjaarCode;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wf') <> 0 then
    select BjGid into @BjGid from tabBoekjaar where Code = @BoekjaarCode;
    if @BjGid is null then
      call Raise(20559); //Ongeldige of geen BoekjaarCode meegegeven!
    end if;

    select RksGid into @RksGid from tabRekeningschema where RksInvoer = @Rekeningnummer and DefaultSoort in (6,7);
    if @RksGid is null then
      call Raise(20547); //Ongeldige of geen Rekeningnummer meegegeven!
    end if;

    select OspGid into @OspGid
    from   tabOpenstaandePost
    where  OspBjGid = @BjGid and OspRksGid = @RksGid and OspFactuurNummer = @FactuurNummer and OspFactuurNummer_Lengte = length(@FactuurNummer);

    if @OspGid is null then
      call Raise(20592); //Ongeldige of geen FactuurNummer meegegeven!
    end if;

    //Omdat FiatteringGewijzigdDoor in de trigger wordt gevuld met @@Gebruikercode, vullen we hier tijdelijk @@GebruikerCode
    set @OrigineleGebruikerCode = @@GebruikerCode;
    set @@GebruikerCode = IsNull(@FiatteringGewijzigdDoor, @@GebruikerCode);
    update tabOpenstaandePost
    set    OspGefiatteerd = IsNull(@PostIsGefiatteerd, OspGefiatteerd),
           OspIsGeblokkeerd = IsNull(@PostIsGeblokkeerd, OspIsGeblokkeerd),
           OspOpmerking = IsNull(@Opmerking, OspOpmerking)
    where OspGid = @OspGid;


    set @@GebruikerCode = @OrigineleGebruikerCode;

    if not @BetalingsKenmerk is null then
      update tabOpenstaandePost
      set    OspBetalingsKenmerk = @BetalingsKenmerk
      where OspGid = @OspGid;
    end if;

  else
    call Raise(20902); //Optie ''Webservices Financieel'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_OpenstaandePost_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Opruimen_Webqueue()
begin
  //ACW #60167: extra commentaar, zodat deze weer naar de database wordt gepusht (was verdwenen)
	Call WebQueueOpruimen;
end;

create or replace procedure WebSvcProc_Order_Collo_Toevoegen(in @OrderNummer numeric(10,0), in @ColloTypeCode nchar(20), in @Aantal numeric(15,3), in @Gewicht numeric(15,3), in @Volume numeric(15,3),
                                                             in @Lengte numeric(15,3), in @Breedte numeric(15,3), in @Hoogte numeric(15,3), in @TrackEnTraceCode nchar(40), in @TrackEnTraceUrl nchar(255), in @Opmerking long nvarchar)

result(RegelNummer integer)
begin
  declare @OrkGid      integer;
  declare @OrclGid     integer;
  declare @ColtGid     integer;
  declare @OrclRegelNr smallint;
  declare @Lockresult  smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_Collo_Toevoegen > @OrderNummer = ' + string(@OrderNummer) + ', @ColloTypeCode = ' + @ColloTypeCode;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then
    select OrkGid into @OrkGid from tabOrderkop where OrkSoort = 0 and OrkNummer = @OrderNummer;
    if @OrkGid is null then
      call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
    end if;

    if IsNull(@ColloTypeCode, '') <> '' then
      select ColtGid into @ColtGid from tabColliType where ColtCode = @ColloTypeCode;
      if @ColtGid is null then
        call Raise(20532); //Ongeldige of geen ColloTypeCode meegegeven!
      end if;
    end if;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @LockResult, 0);
      if @LockResult <> 0 then
        call Raise(20531); //Order is in gebruik!
      end if;
    end if;

    set @OrclRegelNr = IsNull((select max(OrclRegelNr) into @OrclRegelNr from tabOrderColli where OrclOrkGid = @OrkGid), 0)+1;

    insert into tabOrderColli(OrclOrkGid, OrclRegelNr, OrclColtGid, OrclAantal, OrclGewicht, OrclVolume, OrclHoogte, OrclBreedte, OrclDiepte, OrclTrackTraceCode, OrclTrackTraceUrl, OrclOpmerking)
                       values(@OrkGid, @OrclRegelNr, @ColtGid, @Aantal, @Gewicht, @Volume, @Hoogte, @Breedte, @Lengte, @TrackEnTraceCode, @TrackEnTraceUrl, @Opmerking);

    set @OrclGid = @@Identity;

    select OrclRegelNr as RegelNummer from tabOrderColli where OrclGid = @OrclGid;
  else
    call Raise(20900) ; //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_Collo_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Order_Collo_ToevoegenWijzigen(in @OrderNummer numeric(10,0), in @Regelnummer numeric(3,0), in @ColloTypeCode nchar(20), in @Aantal numeric(15,3), in @Gewicht numeric(15,3), in @Volume numeric(15,3),
                                                                     in @Lengte numeric(15,3), in @Breedte numeric(15,3), in @Hoogte numeric(15,3), in @TrackEnTraceCode nchar(40), in @TrackEnTraceUrl nchar(255), in @Opmerking long nvarchar)

result(RegelNummer integer)
begin
  declare @OrkGid      integer;
  declare @OrclGid     integer;
  declare @ColtGid     integer;
  declare @OrclRegelNr smallint;
  declare @Lockresult  smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_Collo_ToevoegenWijzigen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@OrderNummer = ' + string(@OrderNummer) + ', @ColloTypeCode = ' + @ColloTypeCode);

  if IsModuleActive('wo') <> 0 then
    select OrkGid into @OrkGid from tabOrderkop where OrkSoort = 0 and OrkNummer = @OrderNummer;
    if @OrkGid is null then
      call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
    end if;

    if IsNull(@ColloTypeCode, '') <> '' then
      select ColtGid into @ColtGid from tabColliType where ColtCode = @ColloTypeCode;
      if @ColtGid is null then
        call Raise(20532); //Ongeldige of geen ColloTypeCode meegegeven!
      end if;
    end if;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @LockResult, 0);
      if @LockResult <> 0 then
        call Raise(20531); //Order is in gebruik!
      end if;
    end if;

    if (@Regelnummer is null) then
      set @OrclRegelNr = IsNull((select max(OrclRegelNr) into @OrclRegelNr from tabOrderColli where OrclOrkGid = @OrkGid), 0)+1;

      insert into tabOrderColli(OrclOrkGid, OrclRegelNr, OrclColtGid, OrclAantal, OrclGewicht, OrclVolume, OrclHoogte, OrclBreedte, OrclDiepte, OrclTrackTraceCode, OrclTrackTraceUrl, OrclOpmerking)
                         values(@OrkGid, @OrclRegelNr, @ColtGid, IsNull(@Aantal, 0), IsNull(@Gewicht, 0), IsNull(@Volume, 0), IsNull(@Hoogte, 0), IsNull(@Breedte, 0), IsNull(@Lengte, 0), IsNull(@TrackEnTraceCode, ''), IsNull(@TrackEnTraceUrl, ''), @Opmerking);

      set @OrclGid = @@Identity;
    else
      set @OrclGid = (select OrclGid from tabOrderColli where OrclOrkGid = @OrkGid and OrclRegelNr = @Regelnummer);
      if @OrclGid is null then
        call Raise(20663); // Ongeldige of geen Regelnummer meegegeven!
      end if;

      update tabOrderColli set OrclColtGid = IsNull(@ColtGid, OrclColtGid), OrclAantal  = IsNull(@Aantal, OrclAantal), OrclGewicht = IsNull(@Gewicht, OrclGewicht), OrclVolume = IsNull(@Volume, OrclVolume),
                               OrclHoogte = Isnull(@Hoogte, OrclHoogte), OrclBreedte = Isnull(@Breedte, OrclBreedte), OrclDiepte = Isnull(@Lengte, OrclDiepte),
                               OrclTrackTraceCode = Isnull(@TrackEnTraceCode, OrclTrackTraceCode), OrclTrackTraceUrl = Isnull(@TrackEnTraceUrl, OrclTrackTraceUrl), OrclOpmerking = Isnull(@Opmerking, OrclOpmerking)
      where OrclGid = @OrclGid
    end if;

    select OrclRegelNr as RegelNummer from tabOrderColli where OrclGid = @OrclGid;
  else
    call Raise(20900) ; //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_Collo_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Order_LockVrijgeven(in @OrderNummer numeric(10,0))
begin
  declare @OrkGid   integer;
  declare @qLockGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_LockVrijgeven';
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then

    if IsNull(@OrderNummer, 0) = 0 then
      call Raise(20545); //Geen of geen OrderNummer meegegeven!
    else
      select OrkGid into @OrkGid from tabOrderKop where OrkSoort = 0 and OrkNummer = @OrderNummer;
      if (@OrkGid is null) then
        call Raise(20545); //Ongeldige of geen OrderNummer meegegeven!
      end if;
    end if;

    select qLockGid into @qLockGid from qtabLock where qLockUser = 'KingWebservice' and qLockTableName = 'tabOrderKop' and qLockPkey = @OrkGid;
    if @qLockGid is null then
      call Raise(20548); //Lock niet gevonden!
    else
      delete qtabLock where qLockGid = @qLockGid
    end if;

  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_LockVrijgeven';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Order_OrderRegel_SpecificatieRegels_Verwijderen(in @OrderNummer numeric(10,0), in @RegelNummer integer)
begin
  declare @OrkGid                   integer;
  declare @OrrGid                   integer;
  declare @Lockresult               smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_OrderRegel_SpecificatieRegels_Verwijderen > @OrderNummer = ' + string(@OrderNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then
    select OrkGid into @OrkGid from tabOrderkop where OrkSoort = 0 and OrkNummer = @OrderNummer;
    if (@OrkGid is null) then
      call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
    end if;

    select OrrGid into @OrrGid from tabOrderRegel where OrrOrkGid = @OrkGid and OrrRegelnr = @RegelNummer;
    if (@OrrGid is null) then
      call Raise(20520); //Ongeldige of geen RegelNummer meegegeven!
    end if;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @LockResult, 0);
      if @LockResult <> 0 then
        call Raise(20531); //Order is in gebruik!
      end if;
    end if;

    delete tabOrderRegelLocatie where OrlOrrGid = @OrrGid;

  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_OrderRegel_SpecificatieRegels_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Order_OrderRegel_SpecificatieRegel_Toevoegen(
   in @OrderNummer                 numeric(10,0),
   in @RegelNummer                 integer,
   in @MagazijnCode                nchar(3),
   in @LocatieCode                 nchar(20),
   in @PartijNummer                nchar(20),
   in @SerieNummer                 nchar(20),
   in @AantalDezeLevering          numeric(15,3),
   in @ColliIdentifier             nchar(30),
   in @VerkoopEenheid              nchar(20)     default '',
   in @AantalDezeLeveringVrrdEenh  numeric(15,3) default null,
   in @BlokkeerVoorToewijzen       smallint      default 1 // 0 = niet, 1 = ja //ACWdefect72989removed Wordt volledig genegeerd
)
begin
  declare @_OrkGid                    integer;
  declare @_OrkVrijVoorLevering       smallint;
  declare @_OrrGid                    integer;
  declare @_OrlGid                    integer;
  declare @_OrlVkeGid                 integer;
  declare @_OrlAantDecAantal          smallint;
  declare @_OrlAantDecAantalVrrdEenh  smallint;
  declare @_OrrArtGid                 integer;
  declare @_OrrAantalLevering         numeric(15,3);
  declare @_OrrRegelsoort             smallint;
  declare @_Lockresult                smallint;
  declare @_MagGid                    integer;
  declare @_LocGid                    integer;
  declare @_ArtIsPartijRegistreren    smallint;
  declare @_ArtSerieNrRegistreren     smallint;
  declare @_ArtSerieGid               integer;
  declare @_ArtPartijGid              integer;
  declare @_BlokkeerVoorToewijzen     smallint;

  declare @_VkeAantalVoorraadEenhedenInVerkoopEenheid numeric(15,3);
  declare @_VkeIsVoorraadeenheid                      smallint;
  declare @_VkeAantalKanVerschillen                   integer;

  //call TraceBegin('WebSvcProc_Order_OrderRegel_SpecificatieRegel_Toevoegen > ' + '@OrderNummer = ' + string(@OrderNummer));

  if IsModuleActive('wo') = 0 then
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  select OrkGid, OrkVrijVoorLevering
  into    @_OrkGid, @_OrkVrijVoorLevering
  from tabOrderkop
  where OrkSoort  = 0
  and   OrkNummer = @OrderNummer;

  if (@_OrkGid is null) then
    call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
  end if;

  select  OrrGid  , OrrRegelsoort   , OrrArtGid   , OrrAantalLevering
  into    @_OrrGid, @_OrrRegelsoort , @_OrrArtGid , @_OrrAantalLevering
  from tabOrderRegel
  where OrrOrkGid   = @_OrkGid
  and   OrrRegelnr  = @RegelNummer;

  if (@_OrrGid is null) then
    call Raise(20520); //Ongeldige of geen RegelNummer meegegeven!
  end if;
  if (@_OrrRegelsoort <> 2) then
    call Raise(20533); //Bij een tarief- of tekstregel kunnen geen specificatieregels worden toegevoegd!
  end if;

  select MagGid into @_MagGid from tabMagazijn where MagCode = @MagazijnCode;
  if (@_MagGid is null) then
    call Raise(20511); //Ongeldige of geen MagazijnCode meegegeven!
  end if;

  // Locatie verplicht bij vrij voor leveren, anders alleen controleren als een locatie is meegegeven
  if isnull(@LocatieCode, '') <> '' or @_OrkVrijVoorLevering = 1 then
    select LocGid into @_LocGid from tabLocatie where LocNaam = @LocatieCode and LocMagGid = @_MagGid;
    if (@_LocGid is null) then
      call Raise(20534); //Ongeldige of geen LocatieCode meegegeven!
    end if;
  end if;

  if @BlokkeerVoorToewijzen is null then
    set @_BlokkeerVoorToewijzen = 1 /*Standaard geblokkeerd voor hertoewijzen*/
  else
    if @BlokkeerVoorToewijzen not in (0,1) then
      call Raise(20700, 'BlokkeerVoorToewijzen'); //(20700) Ongeldige waarde: %1!
    end if;
      set @_BlokkeerVoorToewijzen = @BlokkeerVoorToewijzen;
  end if;

  select  ArtIsPartijRegistreren  , ArtSerieNrRegistreren
  into    @_ArtIsPartijRegistreren, @_ArtSerieNrRegistreren
  from tabArtikel
  where ArtGid = @_OrrArtGid;
  if @_ArtSerieNrRegistreren = 0 then
    if IsNull(@SerieNummer, '') <> '' then
      call Raise(20535); //Artikel is geen serienummer registrerend artikel!
    end if;
  else
    if IsNull(@SerieNummer, '') <> '' then
      select  ArtSerieGid   , ArtSeriePartijGid
      into    @_ArtSerieGid , @_ArtPartijGid
      from tabArtikelSerienummer
      where ArtSerienummer = @SerieNummer
      and   ArtSerieArtGid = @_OrrArtGid;
      if (@_ArtSerieGid is null) then
        call Raise(20536); //Ongeldige of geen SerieNummer meegegeven!
      end if;
    end if;
  end if;

  if (@_ArtSerieNrRegistreren = 0) or ((@_ArtSerieNrRegistreren = 1) and (@_ArtSerieGid is null)) then
    if (@_ArtIsPartijRegistreren = 0)  then
      if (IsNull(@PartijNummer, '') <> '') then
        call Raise(20537); //Artikel is geen partij registrerend artikel!
      end if;
    else
      if IsNull(@PartijNummer, '') <> '' then
        select ArtPartijGid into @_ArtPartijGid
        from tabArtikelPartij
        where ArtPartijNummer = @PartijNummer
        and   ArtPartijArtGid = @_OrrArtGid;
        if (@_ArtPartijGid is null) then
          call Raise(20526); //Ongeldige of geen PartijNummer meegegeven!
        end if;
      end if;
    end if;
  end if;

  if (@_ArtSerieGid is not null) then
    if exists(select 1 from tabOrderRegelLocatie where OrlArtSerieGid = @_ArtSerieGid and OrlOrrGid = @_OrrGid) then  //Binnen 1 orderregel mag een serienummer maar bij 1 specificatieregel voorkomen
      call Raise(20539); //SerieNummer is al op een andere specifictieregel gebruikt!
    end if;
    if (@AantalDezeLevering <> -1) and (@AantalDezeLevering <> 1) then
      call Raise(20540); //Ongeldige AantalDezeLevering meegegeven!
    end if;
  end if;

  if (IsNull(@AantalDezeLevering, 0) <> 0) and (IsNull(@_OrrAantalLevering, 0) <> 0) then
    if sign(@AantalDezeLevering) <> sign(@_OrrAantalLevering) then
      call Raise(20644); //De aantallen ''Deze levering'' in orderregel en specificatieregel moeten beide positief of negatief zijn!
    end if;
  end if;

  if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid, @_Lockresult, 0);
    if @_Lockresult <> 0 then
      call Raise(20531); //Order is in gebruik!
    end if;
  end if;

  select  VkeGid, VkeAantalVoorraadEenhedenInVerkoopEenheid, VkeIsVoorraadeenheid,
          if VkeAantalDecimalen = 4 then ArtAantDecAantallen else VkeAantalDecimalen end if, ArtAantDecAantallen, VkeAantalKanVerschillen
  into   @_OrlVkeGid, @_VkeAantalVoorraadEenhedenInVerkoopEenheid, @_VkeIsVoorraadeenheid,
         @_OrlAantDecAantal, @_OrlAantDecAantalVrrdEenh, @_VkeAantalKanVerschillen
  from   tabVerkoopEenheid
  inner join tabArtikel on (VkeArtGid=ArtGid)
  where  ArtGid = @_OrrArtGid
    and  ((VkeVerkoopEenheid = @Verkoopeenheid) or ((IsNull(@Verkoopeenheid,'') = '') and VkeIsVoorraadeenheid=1));

  if (@_OrlVkeGid is null) then
    call Raise(20700,_U('Ongeldige of geen %1! meegegeven!', 'Verkoopeenheid'));   // (20700) Ongeldige waarde: %1!
  end if;

  //In bepaalde gevallen mogen velden niet afwijken van elkaar. Reken de verkoopeenheden om naar voorraadeenheden.
  if @_VkeIsVoorraadeenheid = 1 then    /*De voorraadeenheid. Dus alles gelijkstellen aan elkaar.*/
    set @AantalDezeLeveringVrrdEenh    = @AantalDezeLevering;
  else
  begin
    if @_VkeAantalKanVerschillen = 2   /*Afwijkend aantal bij Levering/Facturering*/  then
      //Reken de verkoopeenheden om naar voorraadeenheden
      set @AantalDezeLeveringVrrdEenh = IsNull(@AantalDezeLeveringVrrdEenh, @AantalDezeLevering * @_VkeAantalVoorraadEenhedenInVerkoopEenheid);
    else
      set @AantalDezeLeveringVrrdEenh = @AantalDezeLevering * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
    end if;
  end;
  end if;

  insert into tabOrderRegelLocatie( OrlOrrGid, OrlMagGid, OrlLocGid, OrlDezeLevering,
                                    OrlDezeLeveringVrrdEenh, OrlArtPartijGid, OrlArtSerieGid, OrlSSCCID,
                                    OrlVkeGid, OrlAantDecAantal, OrlAantDecAantalVrrdEenh/*ACWdefect72989removed , OrlHandmatig*/)
                            values( @_OrrGid, @_MagGid, @_LocGid, @AantalDezeLevering,
                                    @AantalDezeLeveringVrrdEenh, @_ArtPartijGid, @_ArtSerieGid, @ColliIdentifier,
                                    @_OrlVkeGid, @_OrlAantDecAantal, @_OrlAantDecAantalVrrdEenh/*ACWdefect72989removed , @_BlokkeerVoorToewijzen*/);

  set @_OrlGid = @@Identity;

  //call TraceEind('WebSvcProc_Order_OrderRegel_SpecificatieRegel_Toevoegen');
end;

create or replace procedure WebSvcProc_Order_OrderRegel_Toevoegen(
    in @OrderNummer                             numeric(10,0),
    in @ExternOrderregelID                      nchar(20),
    in @RegelSoort                              nchar(5),
    in @ArtikelNummer                           nchar(20),
    in @KostenplaatsCode                        nchar(8),
    in @KostendragerCode                        nchar(8),
    in @TekstOpFactuur                          long nvarchar,
    in @AantalBesteld                           numeric(15,3),
    in @AantalDezeLevering                      numeric(15,3),
    in @AantalDezeFacturering                   numeric(15,3),
    in @BrutoVerkoopprijs                       numeric(15,3),
    in @Korting1                                numeric(15,3),
    in @Korting2                                numeric(15,2),
    in @LeverDatum                              date,
    in @EdiBuffer                               long nvarchar,
    in @BtwCode                                 numeric(3,0),
    in @MagazijnCode                            numeric(3,0),
    in @Korting1IsPercentage                    smallint,
    in @PartijNummer                            nchar(20),
    in @VerkoopEenheid                          nchar(20)     default '',
    in @EenheidPrijsPer                         nchar(20)     default 'VOORRAADEENHEDEN',
    in @AantalVoorraadEenhedenInVerkoopEenheid  numeric(15,3) default 1,
    in @AantalDezeLeveringVrrdEenh              numeric(15,3) default null,
    in @AantalDezeFactureringVrrdEenh           numeric(15,3) default null,
    in @DirecteInkoop                           smallint  default null,
    in @OmschrijvingOvernemen                   smallint  default null,
    in @Leverancier                             nchar(10) default null,
    in @InkoopEenheid                           nchar(20) default null,
    in @DirecteLevering                         nchar(40) default null,
    in @CBSLandOorsprong                        nchar(3)  default null,
    in @CbsDouaneRegeling                       nchar(4)  default null,
    in @CbsTransactiecode                       nchar(2)  default null,
    in @Kostprijs                               numeric(15,3) default null,
    in @Productie                               smallint default null
)
result(RegelNummer smallint)
begin
  /*Constanten*/
  declare _qcNee smallint = 0;

  //call TraceBegin('WebSvcProc_Order_OrderRegel_Toevoegen > ' + '@OrderNummer = ' + string(@OrderNummer) + ', @RegelSoort = ' + string(@RegelSoort) +', @ArtikelNummer = ' + @ArtikelNummer);

  if IsModuleActive('wo') = _qcNee then
    call Raise(20900);  //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  //Aanroepen van de hulp routine voor het toevoegen
  select RegelNummer
  from WebSvcHulpProc_Order_OrderRegel_ToevoegenTussenvoegen(
    @OrderNummer,
    null, /*Orderregelnummer is leeg bij het toevoegen*/
    0, /*0 = Toevoegen*/
    @ExternOrderregelID,
    @RegelSoort,
    @ArtikelNummer,
    @KostenplaatsCode,
    @KostendragerCode,
    @TekstOpFactuur,
    @AantalBesteld,
    @AantalDezeLevering,
    @AantalDezeFacturering,
    @BrutoVerkoopprijs,
    @Korting1,
    @Korting2,
    @LeverDatum,
    @EdiBuffer,
    @BtwCode,
    @MagazijnCode,
    @Korting1IsPercentage,
    @PartijNummer,
    @VerkoopEenheid,
    @EenheidPrijsPer,
    @AantalVoorraadEenhedenInVerkoopEenheid,
    @AantalDezeLeveringVrrdEenh,
    @AantalDezeFactureringVrrdEenh,
    @DirecteInkoop,
    @OmschrijvingOvernemen,
    @Leverancier,
    @InkoopEenheid,
    @DirecteLevering,
    @CBSLandOorsprong,
    @CbsDouaneRegeling,
    @CbsTransactiecode,
    @Kostprijs,
    @Productie
  );

  //call TraceEind('WebSvcProc_Order_OrderRegel_Toevoegen');
end;


create or replace procedure WebSvcProc_Order_OrderRegel_Verwijderen(in @OrderNummer numeric(10,0), in @RegelNummer integer)
begin
  declare @OrkGid                                 integer;
  declare @OrrGid                                 integer;
  declare @OrrRegelsoort                          smallint;
  declare @Lockresult                             smallint;
  declare @OrrAantalGeleverd                      numeric(15,3);
  declare @OrrAantalGeleverdVrrdEenh              numeric(15,3);
  declare @OrrAantalGefactureerd                  numeric(15,3);
  declare @OrrAantalGefactureerdVrrdEenh          numeric(15,3);
  declare @OrrAantalVrrdEenhInVerkEenhMagAfwijken smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_OrderRegel_Verwijderen > @OrderNummer = ' + string(@OrderNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then
    select OrkGid into @OrkGid from tabOrderkop where OrkSoort = 0 and OrkNummer = @OrderNummer;
    if (@OrkGid is null) then
      call Raise(20519);  //Ongeldige of geen OrderNummer meegegeven
    end if;

    select OrrGid, OrrRegelsoort, OrrAantalVrrdEenhInVerkEenhMagAfwijken,
           Round(OrrAantalGeleverd, OrrAantDecAantal), Round(OrrAantalGeleverdVrrdEenh, OrrAantDecAantalVrrdEenh),
           Round(OrrAantalGefactureerd, OrrAantDecAantal), Round(OrrAantalGefactureerdVrrdEenh, OrrAantDecAantalVrrdEenh)
    into   @OrrGid, @OrrRegelsoort, @OrrAantalVrrdEenhInVerkEenhMagAfwijken,
           @OrrAantalGeleverd, @OrrAantalGeleverdVrrdEenh,
           @OrrAantalGefactureerd, @OrrAantalGefactureerdVrrdEenh
    from   tabOrderRegel where OrrOrkGid = @OrkGid and OrrRegelnr = @RegelNummer;


    if (@OrrGid is null) then
      call Raise(20520);  //Ongeldige of geen RegelNummer meegegeven
    end if;


    if (@OrrRegelSoort = 2) then
        if ((@OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0) and (@OrrAantalGeleverdVrrdEenh <> @OrrAantalGefactureerdVrrdEenh)) or //Mag niet afwijken (vast aantal)
           ((@OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1) and (@OrrAantalGeleverd <> @OrrAantalGefactureerd)) or //Mag afwijken bij aantal besteld
           ((@OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2) and ((@OrrAantalGeleverd <> @OrrAantalGefactureerd) or (@OrrAantalGeleverdVrrdEenh <> @OrrAantalGefactureerdVrrdEenh))) then //Mag afwijken bij Levering/Facturering
          call Raise(20640); //Bij deze orderregel is het ''aantal reeds geleverd'' ongelijk aan het ''aantal reeds gefactureerd''!
        end if;
    end if;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @LockResult, 0);
      if @LockResult <> 0 then
        call Raise(20531);  //Order is in gebruik
      end if;
    end if;

    delete tabOrderRegel where OrrGid = @OrrGid;
  else
    call Raise(20900);  //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_OrderRegel_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Order_OrderRegel_VrijeRubriek_Wijzigen(in @OrderNummer numeric(10,0), in @RegelNummer integer, in @RubriekOmschrijving nchar(40), in @RubriekInhoud  nchar(255))
begin
  declare @OrkGid       integer;
  declare @OrrGid       integer;
  declare @Lockresult   smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_OrderRegel_VrijeRubriek_Wijzigen > @OrderNummer = ' + string(@OrderNummer) + ', @RegelNummer = ' + string(@RegelNummer) + ', @RubriekOmschrijving = ' + @RubriekOmschrijving;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') = 0 then
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  select OrkGid into @OrkGid from tabOrderKop where OrkSoort = 0 and OrkNummer = @OrderNummer;
  if (@OrkGid is null) then
    call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
  end if;

  select OrrGid into @OrrGid from tabOrderRegel where OrrOrkGid = @OrkGid and OrrRegelnr = @RegelNummer;
  if (@OrrGid is null) then
    call Raise(20520); //Ongeldige of geen RegelNummer meegegeven!
  end if;

  if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @LockResult, 0);
    if @LockResult <> 0 then
      call Raise(20531); //Order is in gebruik!
    end if;
  end if;

  if not exists(select 1 from tabVrORR000000 where VrORR000000RecordId = @OrrGid) then
    // Er is nog geen VR record, die gaan we aanmaken nu door deze wijziging, dan eerst de defaults voor alle velden vullen
    call VrijeRubriekenVulDefaults('ORR', 0, 0, @OrrGid, 0);
  end if;

  call VrInsertOrReplaceValue('ORR', 0, 0, @OrrGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Order_OrderRegel_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Order_OrderRegel_Wijzigen(
  in @OrderNummer                             numeric(10,0),
  in @RegelNummer                             integer,
  in @RegelID                                 integer,
  in @AantalBesteld                           numeric(15,3),
  in @AantalDezeLevering                      numeric(15,3),
  in @AantalDezeFacturering                   numeric(15,3),
  in @VerkoopEenheid                          nchar(20)     default '',
  in @EenheidPrijsPer                         nchar(20)     default null,
  in @AantalVoorraadEenhedenInVerkoopEenheid  numeric(15,3) default null,
  in @AantalDezeLeveringVrrdEenh              numeric(15,3) default null,
  in @AantalDezeFactureringVrrdEenh           numeric(15,3) default null,
  in @CBSLandOorsprong                        nchar(3)      default null,
  in @CbsDouaneRegeling                       nchar(4)      default null,
  in @CbsTransactiecode                       nchar(2)      default null,
  in @MagazijnCode                            integer       default null)
begin
  declare @_OrkGid                                    integer;
  declare @_OrrGid                                    integer;
  declare @_OrrVkeGid                                 integer;
  declare @_OrrRegelsoort                             smallint;
  declare @_OrrIsAantallen                            smallint;
  declare @_ArtGid                                    integer;
  declare @_OrlDezeLevering                           numeric(15,3);
  declare @_Lockresult                                smallint;
  declare @_OrrEenheidPrijsPer                        smallint;
  declare @_OrrAantalGeleverd                         numeric(15,3);
  declare @_OrrAantalGefactureerd                     numeric(15,3);
  declare @_OrrIsKortingsPercentage                   smallint;
  declare @_OrrAantalVrrdEenhInVerkEenh               numeric(15,3);
  declare @_OrrAantDecBedrag                          smallint;
  declare @_OrrPrijsPer                               smallint;
  declare @_OrrBrutoVerkoopPrijs                      numeric(15,3);
  declare @_OrrRegelKorting1                          numeric(15,3);
  declare @_OrrAantalVrrdEenhInVerkEenhMagAfwijken    smallint;
  declare @_VkeGid                                    integer       default null;
  declare @_AantalBesteldVrrdEenh                     numeric(15,3) default 0;
  declare @_VkeAantalKanVerschillen                   integer;
  declare @_VkeVerkoopPrijsPer                        smallint;
  declare @_VkeAantalDecimalen                        smallint; /* 0,1,2,3 = aantal decimalen, 4 = Volgens voorraadeenheid */
  declare @_VkeIsVoorraadeenheid                      smallint;
  declare @_VkeIsGeblokkeerdVoorVerkoop               smallint;
  declare @_VkeAantalVoorraadEenhedenInVerkoopEenheid numeric(15,3);
  declare @_CbsLndGidOorsprong                        integer;
  declare @_CbsDouaneRegeling                         nchar(4);
  declare @_CbsTrGid                                  integer;
  declare @_OrrMagGid                                 integer;
  declare @_MagGid                                    integer;

  //call TraceBegin('WebSvcProc_Order_OrderRegel_Wijzigen > @OrderNummer = ' + string(@OrderNummer));

  if IsModuleActive('wo') = 0 then
    call Raise(20900);  //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  select OrkGid into @_OrkGid from tabOrderkop where OrkSoort = 0 and OrkNummer = @OrderNummer;
  if (@_OrkGid is null) then
    call Raise(20519);  //Ongeldige of geen OrderNummer meegegeven
  end if;

  if (@RegelNummer is null) and (@RegelID is null) then
    call Raise(20695); // Geen RegelNummer of RegelID meegegeven!
  end if;

  if @RegelID is null then
    select  OrrGid, OrrRegelsoort, OrrArtGid, OrrVkeGid, OrrIsAantallen, OrrAantalGeleverd,
            OrrAantalGefactureerd, OrrIsKortingsPercentage, OrrAantDecBedrag,
            OrrPrijsPer, OrrBrutoVerkoopPrijs, OrrRegelKorting1,
            OrrAantalVrrdEenhInVerkEenhMagAfwijken, OrrAantalVrrdEenhInVerkEenh, OrrEenheidPrijsPer, OrrMagGid
    into    @_OrrGid, @_OrrRegelsoort, @_ArtGid, @_OrrVkeGid, @_OrrIsAantallen, @_OrrAantalGeleverd,
            @_OrrAantalGefactureerd, @_OrrIsKortingsPercentage, @_OrrAantDecBedrag,
            @_OrrPrijsPer, @_OrrBrutoVerkoopPrijs, @_OrrRegelKorting1,
            @_OrrAantalVrrdEenhInVerkEenhMagAfwijken, @_OrrAantalVrrdEenhInVerkEenh, @_OrrEenheidPrijsPer, @_OrrMagGid
    from tabOrderRegel
    where OrrOrkGid = @_OrkGid
      and OrrRegelnr = @RegelNummer;
  else
    if ((select OrkNummer from tabOrderKop inner join tabOrderRegel on OrrOrkGid = OrkGid where OrrGid = @RegelID) <> @OrderNummer) then
      call Raise(20696); // Meegegeven RegelID hoort niet bij het meegegeven OrderNummer!
    else
      select  OrrGid, OrrRegelsoort, OrrArtGid, OrrVkeGid, OrrIsAantallen, OrrAantalGeleverd,
              OrrAantalGefactureerd, OrrIsKortingsPercentage, OrrAantDecBedrag,
              OrrPrijsPer, OrrBrutoVerkoopPrijs, OrrRegelKorting1,
              OrrAantalVrrdEenhInVerkEenhMagAfwijken, OrrAantalVrrdEenhInVerkEenh, OrrEenheidPrijsPer, OrrMagGid
      into    @_OrrGid, @_OrrRegelsoort, @_ArtGid, @_OrrVkeGid, @_OrrIsAantallen, @_OrrAantalGeleverd,
              @_OrrAantalGefactureerd, @_OrrIsKortingsPercentage, @_OrrAantDecBedrag,
              @_OrrPrijsPer, @_OrrBrutoVerkoopPrijs, @_OrrRegelKorting1,
              @_OrrAantalVrrdEenhInVerkEenhMagAfwijken, @_OrrAantalVrrdEenhInVerkEenh, @_OrrEenheidPrijsPer, @_OrrMagGid
      from tabOrderRegel
      where OrrOrkGid = @_OrkGid
        and OrrGid = @RegelID;
    end if
  end if;

  if (@_OrrGid is null) then
    call Raise(20520);  //Ongeldige of geen RegelNummer meegegeven
  end if;

  if @_OrrRegelsoort = 0 then //Tekstregel
    call Raise(20521);  //Een tekstregel kan niet worden gewijzigd
  end if;

  if @_OrrRegelsoort = 1 then //Tariefregel
    if @AantalDezeLevering is not null then
      if @AantalDezeLevering <> @AantalBesteld then
        call Raise(20522); //Bij een tariefregel moet AantalDezeLevering gelijk zijn aan AantalBesteld
      end if;
    end if;
  end if;

  if @_OrrRegelsoort = 2 then //Artikelregel
    if isNull(@VerkoopEenheid,'') = '' then
      Set @_VkeGid = @_OrrVkeGid;
    else
      select  VkeGid, VkeIsVoorraadeenheid, VkeAantalKanVerschillen,
              VkeIsGeblokkeerdVoorVerkoop, VkeAantalVoorraadEenhedenInVerkoopEenheid
      into    @_VkeGid, @_VkeIsVoorraadeenheid, @_VkeAantalKanVerschillen,
              @_VkeIsGeblokkeerdVoorVerkoop, @_VkeAantalVoorraadEenhedenInVerkoopEenheid
      from tabVerkoopeenheid
      where VkeVerkoopEenheid = @VerkoopEenheid
        and VkeArtGid         = @_ArtGid;

      if ((@_OrrAantalGeleverd <> 0) and (@_VkeIsVoorraadeenheid <> 1)) and (@_VkeGid <> @_OrrVkeGid) then
        //Als er geleverd is mag de verkoopeenheid niet meer gewijzigd worden
        call Raise(20780, _U('Verkoopeenheid wijzigen is'), _U('Deze regel is reeds (deels) geleverd! De verkoopeenheid mag alleen gewijzigd worden in de voorraadeenheid.'));        //(20780) %1! niet mogelijk: %2!.
      end if;
      if (@_OrrAantalGefactureerd <> 0) and (@_VkeGid <> @_OrrVkeGid) then
        //Als er gefactureerd is mag de verkoopeenheid niet meer gewijzigd worden
        call Raise(20780, _U('Verkoopeenheid wijzigen is'), _U('Deze regel is reeds (deels) gefactureerd!'));        //(20780) %1! niet mogelijk: %2!.
      end if;
    end if;

    if @_VkeGid is null then
      //Hij mag alleen gewijzigd worden in de voorraadeenheid of niet wijzigen
      call Raise(20700,_U('De verkoopeenheid ''%1!'' is onbekend',  @Verkoopeenheid));        // (20700) Ongeldige waarde: %1!
    end if;

    if @_VkeGid = @_OrrVkeGId then
      // Is dezelfde als in de orderregel, zet dan wat opties uit de orderregel ipv opnieuw ophalen
      select  VkeGid, VkeIsVoorraadeenheid, @_OrrAantalVrrdEenhInVerkEenhMagAfwijken,
              0, VkeAantalVoorraadEenhedenInVerkoopEenheid
      into    @_VkeGid, @_VkeIsVoorraadeenheid, @_VkeAantalKanVerschillen,
              @_VkeIsGeblokkeerdVoorVerkoop, @_VkeAantalVoorraadEenhedenInVerkoopEenheid
      from tabVerkoopeenheid
      where (VkeGid = @_OrrVkeGid);
    end if;

    if (@_VkeIsGeblokkeerdVoorVerkoop = 1) and (@_VkeGid <> @_OrrVkeGId) then
      call Raise(20760,_U('De verkoopeenheid is geblokkeerd voor verkoop'));                              // (20760) Ongeldige status: %1!
    end if;

    //In bepaalde gevallen mogen velden niet afwijken van elkaar. Reken de verkoopeenheden om naar voorraadeenheden.
    if @_VkeIsVoorraadeenheid = 1 then    /*De voorraadeenheid. Dus alles gelijkstellen aan elkaar.*/
      set @_AantalBesteldVrrdEenh        = @AantalBesteld;
      set @AantalDezeLeveringVrrdEenh    = @AantalDezeLevering;
      set @AantalDezeFactureringVrrdEenh = @AantalDezeFacturering;
    else
      if @_VkeAantalKanVerschillen = 2   /*Afwijkend aantal bij Levering/Facturering*/  then
        //Reken de verkoopeenheden om naar voorraadeenheden
        set @_AantalBesteldVrrdEenh          = @AantalBesteld          * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        set @AantalDezeLeveringVrrdEenh      = isNull(@AantalDezeLeveringVrrdEenh, @AantalDezeLevering * @_VkeAantalVoorraadEenhedenInVerkoopEenheid);
        set @AantalDezeFactureringVrrdEenh   = isNull(@AantalDezeFactureringVrrdEenh, @AantalDezeFacturering * @_VkeAantalVoorraadEenhedenInVerkoopEenheid);
      else
        if @_VkeAantalKanVerschillen = 1 /*Afwijkend aantal bij Aantal besteld*/ then
          if IsNull(@AantalVoorraadEenhedenInVerkoopEenheid,0)  = 0 then
            set @AantalVoorraadEenhedenInVerkoopEenheid = @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
          end if;

          set @_VkeAantalVoorraadEenhedenInVerkoopEenheid = @AantalVoorraadEenhedenInVerkoopEenheid;
          set @_AantalBesteldVrrdEenh        = @AantalBesteld          * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
          set @AantalDezeLeveringVrrdEenh    = @AantalDezeLevering     * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
          set @AantalDezeFactureringVrrdEenh = @AantalDezeFacturering  * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        else                             /*Vast aantal, niet te wijzigen*/
          set @_AantalBesteldVrrdEenh        = @AantalBesteld          * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
          set @AantalDezeLeveringVrrdEenh    = @AantalDezeLevering     * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
          set @AantalDezeFactureringVrrdEenh = @AantalDezeFacturering  * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        end if;
      end if;
    end if;

    case isNull(@EenheidPrijsPer,'')
      when 'VERKOOPEENHEID'   then set @_VkeVerkoopPrijsPer = 0;
      when 'VOORRAADEENHEDEN' then set @_VkeVerkoopPrijsPer = 1;
      when ''                 then set @_VkeVerkoopPrijsPer = @_OrrEenheidPrijsPer;
      else call Raise(20700,_U('%1! moet ''%2!'' of ''%3!'' zijn', 'EenheidPrijsPer', 'VERKOOPEENHEID', 'VOORRAADEENHEDEN'));  // (20700) Ongeldige waarde: %1!
    end case;

    if @_OrrEenheidPrijsPer <> @_VkeVerkoopPrijsPer then
      if @_OrrAantalGefactureerd <> 0 then
        call Raise(20780, _U('Prijs per wijzigen'), _U('Deze regel is reeds (deels) gefactureerd!'));        //(20780) %1! niet mogelijk: %2!.
      end if;

      if @_VkeVerkoopPrijsPer = 1 then  /* van verkoopeenheid naar voorraadeenheid */
        set @_OrrBrutoVerkoopPrijs = round((@_OrrBrutoVerkoopPrijs / @_OrrAantalVrrdEenhInVerkEenh) * @_OrrPrijsPer, @_OrrAantDecBedrag);
      else                                /* van voorraadeenheid naar verkoopeenheid */
        set @_OrrBrutoVerkoopPrijs = round((@_OrrBrutoVerkoopPrijs / @_OrrPrijsPer) * @_VkeAantalVoorraadEenhedenInVerkoopEenheid, @_OrrAantDecBedrag);
      end if;

      if @_OrrIsKortingsPercentage = 0 then
      /* Als het een kortingsbedrag is reken deze dan om naar de voorraadeenheid/verkoopeenheid */
        if @_VkeVerkoopPrijsPer = 1 then  /* van verkoopeenheid naar voorraadeenheid */
          set @_OrrRegelKorting1 = round((@_OrrRegelKorting1 / @_OrrAantalVrrdEenhInVerkEenh) * @_OrrPrijsPer, @_OrrAantDecBedrag);
        else                                /* van voorraadeenheid naar verkoopeenheid */
          set @_OrrRegelKorting1 = round((@_OrrRegelKorting1 / @_OrrPrijsPer) * @_VkeAantalVoorraadEenhedenInVerkoopEenheid, @_OrrAantDecBedrag);
        end if;
      end if;
    end if;
  end if;

  if (IsNull(@AantalDezeLevering, 0) <> 0) and (@_OrrRegelsoort = 2) then
    select first OrlDezeLevering into @_OrlDezeLevering from tabOrderRegelLocatie where OrlOrrGid = @_OrrGid and OrlDezeLevering <> 0;
    if @_OrlDezeLevering is not null then
      if sign(@_OrlDezeLevering) <> sign(@AantalDezeLevering) then
        call Raise(20644); //De aantallen ''Deze levering'' in orderregel en specificatieregel moeten beide positief of negatief zijn!
      end if;
    end if;
  end if;

  if (@_OrrRegelsoort = 2) then  //artikel
    if @AantalBesteld = 0 then
      call Raise(20659); //Ongeldige of geen AantalBesteld meegegeven!;
    end if;
  end if;

  if (@_OrrRegelsoort = 1) then  //tarief
    if (@_OrrIsAantallen = 0) and (@AantalBesteld <> 0) then
      set @_OrrIsAantallen = 1;
    end if;

    if @_OrrIsAantallen = 1 then
      if @AantalBesteld = 0 then
        call Raise(20659); //Ongeldige of geen AantalBesteld meegegeven!;
      end if;
    end if;
  end if;

  // Controleren CBS landcode oorsprong
  if IsNull(@CbsLandOorsprong, '') <> '' then
    select first LndGid into @_CBSLndGidOorsprong from tabLand where LndEigenCode = @CbsLandOorsprong;
    if (@_CBSLndGidOorsprong is null) then
      call Raise(20698); // Ongeldige of geen CbsLandOorsprong meegegeven!
    end if;
  end if;

  if not @CbsDouaneRegeling is null then
    set @_CbsDouaneRegeling = @CbsDouaneRegeling;
  end if;

  // Transactiecode alleen bij regel ART/TAR
  if not @CbsTransactiecode is null and @_OrrRegelsoort <> 0 then
    if @CbsTransactiecode = '' then
      set @_CbsTrGid = null;
    else
      // Opzoeken transactie en opnemen
      set @_CbsTrGid = null;
      select first CbsTrGid
      into @_CbsTrGid
      from tabCbsTransactie
      where CbsTrCode = @CbsTransactiecode;
      if @_CbsTrGid is null then
        call Raise(20720, 'CbsTransactiecode'); //(20720) %1! niet gevonden!
      end if;
    end if;
  end if;

  if @MagazijnCode is not null then
    select MagGid into @_MagGid from tabMagazijn where MagCode = @MagazijnCode;
    if (@_MagGid is null) then
      call Raise(20511); //Ongeldige of geen MagazijnCode meegegeven!
    end if;
  end if;

  if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid, @_Lockresult, 0, 'KingWebService');
    if @_Lockresult <> 0 then
      call Raise(20531);  //Order is in gebruik
    end if;
  end if;

  update tabOrderRegel
  set OrrIsAantallen                    = IsNull(@_OrrIsAantallen, OrrIsAantallen),
      OrrAantalBesteld                  = IsNull(@AantalBesteld, OrrAantalBesteld),
      OrrAantalBesteldVrrdEenh          = IsNull(@_AantalBesteldVrrdEenh, OrrAantalBesteldVrrdEenh),
      OrrAantalLevering                 = IsNull(@AantalDezeLevering, OrrAantalLevering),
      OrrAantalLeveringVrrdEenh         = IsNull(@AantalDezeLeveringVrrdEenh, OrrAantalLeveringVrrdEenh),
      OrrAantalDezeFacturering          = IsNull(@AantalDezeFacturering, OrrAantalDezeFacturering),
      OrrAantalDezeFactureringVrrdEenh  = IsNull(@AantalDezeFactureringVrrdEenh, OrrAantalDezeFactureringVrrdEenh),
      OrrVkeGid                               = @_VkeGid,
      OrrAantalVrrdEenhInVerkEenhMagAfwijken  = @_VkeAantalKanVerschillen,
      OrrAantalVrrdEenhInVerkEenh             = @_VkeAantalVoorraadEenhedenInVerkoopEenheid,
      OrrEenheidPrijsPer                      = @_VkeVerkoopPrijsPer,
      OrrBrutoVerkoopPrijs                    = @_OrrBrutoVerkoopPrijs,
      OrrRegelKorting1                        = @_OrrRegelKorting1,
      OrrLndGidCbsOorsprong                   = IsNull(@_CBSLndGidOorsprong, OrrLndGidCbsOorsprong),
      OrrCbsDouaneregeling                    = isnull(@_CbsDouaneRegeling, OrrCbsDouaneregeling),
      OrrCbsTrGid                             = if isnull(@CbsTransactiecode, '_') = '' then null else isnull(@_CbsTrGid, OrrCbsTrGid) endif, // Lege transactiecode moet veld ook leeg maken
      OrrMagGid                         = IsNull(@_MagGid, @_OrrMagGid)

  where OrrGid = @_OrrGid;

  //call TraceEind('WebSvcProc_Order_OrderRegel_Wijzigen');
end;


create or replace procedure WebSvcProc_Order_Toevoegen(
  in @OrderNummer                   numeric(10,0),
  in @ExternOrderID                 nchar(20),
  in @DebiteurNummer                nchar(10),
  in @ContactPersoonNummer          numeric(3,0),
  in @ValutaCode                    nchar(3),
  in @Referentie                    long nvarchar,
  in @EmailExtraTekst               long nvarchar,
  in @OrderDatum                    date,
  in @LeverDatum                    date,
  in @InkoopCombinatie              smallint,
  in @DebiteurNummerFactuur         nchar(10),
  in @DebiteurNummerOmzet           nchar(10),
  in @DebiteurNummerPrijsafspraken  nchar(10),
  in @FactuurAdres                  nchar(4),
  in @VerzendAdres                  nchar(10),
  in @VerzendAdresNummer            numeric(3,0),
  in @PrijzenInclusiefBtw           smallint,
  in @OrderKortingsPercentage       numeric(6,2),
  in @BetalingsConditieNummer       numeric(3,0),
  in @LeveringsConditieNummer       numeric(3,0),
  in @MagazijnCode                  numeric(3,0),
  in @Opmerking                     long nvarchar,
  in @VervoerderNaam                nchar(40),
  in @VertegenwoordigerNummer       numeric(3,0),
  in @EdiOrder                      smallint,
  in @AparteFactuur                 nchar(40),
  in @AparteLevering                nchar(4),
  in @Deellevering                  nchar(20),
  in @Verzamellijst                 nchar(4),
  in @Gebruikdefaults               smallint default 0,
  in @WebshopId                     nchar(20) default null,
  in @EindAdres nchar(10) default 'NVT', //'VEST', 'COR', 'VERZ', 'NVT'
  in @EindAdresNummer numeric(3,0) default null
)
result(OrderNummer numeric(10,0))
begin
  // constanten...
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  declare @_NawGid integer;
  declare @_RelGid integer;
  declare @_OrkGid integer;
  declare @_OrkFactuurNawGid integer;
  declare @_OrkNawGidOmzet integer;
  declare @_OrkNawGidPrijzen integer;
  declare @_OrkFactuurAdres integer;
  declare @_OrkVerzendAdres integer;
  declare @_OrkEindAdres integer = null;
  declare @_OrkAdrGidEindAdres integer = null;
  declare @_OrkApartFaktureren integer;
  declare @_OrkApartLevering integer;
  declare @_OrkIsDeelLeveringToegestaan integer;
  declare @_OrkIsVerzamellijstGebruiken integer;
  declare @_OrkAdrGid integer;
  declare @_OrkVrvGid integer;
  declare @_OrkDefaultMagGid integer;
  declare @_ValNummer integer;
  declare @_OrkVtgCode integer;
  declare @_OrkIsInkoopcombinatie smallint;
  declare @_LvcNummer integer;
  declare @_BtcNummer integer;
  declare @_LockResult integer;
  declare @_OrkWscGid integer;
  //CBS
  declare @_tmpAdrGid integer;
  declare @_OrkCbsMeenemenInAangifte integer;
  declare @_OrkCbsLndGidBestemming integer;
  declare @_OrrCbsLndGidOorsprong integer;
  //CBS Vaste gegevens
  declare @_CbsExtra integer;
  declare @_CbsVastCbsGsGidUitvoer integer;
  declare @_CbsVastCbsSsGidUitvoer integer;
  declare @_CbsVastPtnGidUitvoer integer;
  declare @_CbsVastCbsVwGidUitvoer integer;
  declare @_CbsVastCbsCoGidUitvoer integer;
  declare @_CbsVastCbsTrGidUitvoer integer;

  //call TraceBegin('WebSvcProc_Order_Toevoegen > @OrderNummer = ' + string(@OrderNummer) + ', @DebiteurNummer = ' + @DebiteurNummer);

  if IsModuleActive('wo') = _qcNEE then //Webservices Orders
    call Raise(20900);  //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  select NawFilNawGid into @_NawGid from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummer;
  if (@_NawGid is null) then
    call Raise(20554);  //Ongeldige of geen DebiteurNummer meegegeven
  end if;

  if @ContactPersoonNummer is not null then
    select RelGid into @_RelGid from tabRelatie where RelNawGid = @_NawGid and RelNummer = @ContactPersoonNummer;
    if (@_RelGid is null) then
      call Raise(20555);  //Ongeldige of geen ContactPersoonNummer meegegeven
    end if;
  end if;

  if IsNull(@DebiteurNummerFactuur, '') <> '' then
    select NawFilNawGid into @_OrkFactuurNawGid from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummerFactuur;
    if (@_OrkFactuurNawGid is null) or (IsNull(@InkoopCombinatie, _qcNEE) = _qcNEE) then   //Geen inkoopcombinatie, dan ook geen factuur debiteur meegeven
      call Raise(20503);  //Ongeldige of geen DebiteurNummerFactuur meegegeven
    end if;
  else
    // Default situatie? Dan ID bij (factuur-)debiteur opvragen. Maar alleen als er geen InkoopCombinatie is meegegeven
    select NawidFactDeb into @_OrkFactuurNawGid from tabNaw where NawGid = @_NawGid and NawIsInkoopCombinatie = 1 and @InkoopCombinatie is null and @Gebruikdefaults = _qcJA;
  end if;

  if IsNull(@DebiteurNummerOmzet, '') <> '' then
    select NawFilNawGid into @_OrkNawGidOmzet from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummerOmzet;
    if (@_OrkNawGidOmzet is null) or (IsNull(@InkoopCombinatie, _qcNEE) = _qcNEE) then
      call Raise(20504);  //Ongeldige of geen DebiteurNummerOmzet meegegeven
    end if;
  else
    select NawidDebOmzet into @_OrkNawGidOmzet from tabNaw where NawGid = @_NawGid and NawIsInkoopCombinatie = 1 and @InkoopCombinatie is null and @Gebruikdefaults = _qcJA;
  end if;

  if IsNull(@DebiteurNummerPrijsafspraken, '') <> '' then
    select NawFilNawGid into @_OrkNawGidPrijzen from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummerPrijsafspraken;
    if (@_OrkNawGidPrijzen is null) or (IsNull(@InkoopCombinatie, _qcNEE) = _qcNEE) then
      call Raise(20505); //Ongeldige of geen DebiteurNummerPrijzen meegegeven
    end if;
  else
    select NawidDebPrijzen into @_OrkNawGidPrijzen from tabNaw where NawGid = @_NawGid and NawIsInkoopCombinatie = 1 and @InkoopCombinatie is null and @Gebruikdefaults = _qcJA;
  end if;

  if IsNull(@InkoopCombinatie, _qcNEE) = _qcJA then
    if @_OrkFactuurNawGid is null then
      call Raise(20503); //Ongeldige of geen DebiteurNummerFactuur meegegeven
    end if;
    if @_OrkNawGidOmzet is null then
      call Raise(20504);  //Ongeldige of geen DebiteurNummerOmzet meegegeven
    end if;
    if @_OrkNawGidPrijzen is null then
      call Raise(20505);  //Ongeldige of geen DebiteurNummerPrijzen meegegeven
    end if;
  end if;

  set @_OrkIsInkoopcombinatie = IsNull(@InkoopCombinatie, (select NawIsInkoopCombinatie from tabNaw where NawGid = @_NawGid and @Gebruikdefaults = _qcJA) );

  // De combinatie van inkoopcombinaties en debiteurnummers is nu gecheckt en valide bevonden.
  // Er wordt hierna gebruik gemaakt van de GIDjes (ingevuld betekent inkoopcombinatie)

  // we halen alvast default op. Is er echter een waarde meegegeven, dan wordt dat overgenomen.
  // Factuuradres van Inkoopcombinatie indien bekend, anders van de orderdebiteur
  select NawFactuurAdres into @_OrkFactuurAdres from tabNaw where NawGid = IsNull(@_OrkFactuurNawGid,@_NawGid) and @Gebruikdefaults = _qcJA;
  if IsNull(@FactuurAdres, '') <> '' then
    case @FactuurAdres
      when 'COR'  then set @_OrkFactuurAdres = 0;
      when 'VEST' then set @_OrkFactuurAdres = 1;
      else call Raise(20506);  //Ongeldige of geen FactuurAdres meegegeven
    end case;
  end if;

  if IsNull(@VerzendAdres, '') <> '' then
    case @VerzendAdres
      when 'COR'       then set @_OrkVerzendAdres = 0;
      when 'VEST'      then set @_OrkVerzendAdres = 1;
      when 'VERZ'      then set @_OrkVerzendAdres = 2;
      when 'FACT_COR'  then set @_OrkVerzendAdres = 3;
      when 'FACT_VEST' then set @_OrkVerzendAdres = 4;
      when 'FACT_VERZ' then set @_OrkVerzendAdres = 5;
      else call Raise(20507);  //Ongeldige of geen VerzendAdres meegegeven
    end case;
    if (@_OrkVerzendAdres in (3,4,5)) and (IsNull(@InkoopCombinatie, _qcNEE) = _qcNEE) then
      call Raise(20507);  //Ongeldige of geen VerzendAdres meegegeven
    end if;
  end if;

  if (IsNull(@_OrkVerzendAdres, 0) in (2,5)) then  //Bij Verzendadres of Factuurverzendadres, verplicht verzendadresnummer invoeren
    select AdrGid into @_OrkAdrGid from tabAdres where AdrNawGid = if (IsNull(@_OrkIsInkoopcombinatie, 0) = 1) and (@_OrkVerzendAdres = 5) then @_OrkFactuurNawGid else @_NawGid endif and AdrCode = @VerzendAdresNummer;
    //ACW Defect 59772: Verzendadresnummer niet verplicht
    if @VerzendAdresNummer is not null then
      if (@_OrkAdrGid is null) or (@VerzendAdresNummer is null) then
        call Raise(20509);  //Ongeldige of geen VerzendAdresNummer meegegeven
      end if;
    end if;
  end if;

  // Niets meegegeven? dan defaults opvragen indien aangegeven.
  if @_OrkVerzendAdres is null and @_OrkAdrGid is null and @Gebruikdefaults = _qcJA then
    select NawVerzendAdres into @_OrkVerzendAdres from tabNaw where NawGid = @_NawGid;
    select NawGidVerzendAdres into @_OrkAdrGid from tabNaw where ( NawVerzendAdres = 5 and NawGid = @_OrkFactuurNawGid ) or ( NawVerzendAdres = 2 and NawGid = @_NawGid); // default bij inkoopcombinatie, anders bij debiteur
  end if;

  if IsNull(@EindAdres, '') <> '' then
    case @EindAdres
      when 'COR' then set @_OrkEindAdres = 0;
      when 'VEST' then set @_OrkEindAdres = 1;
      when 'VERZ' then set @_OrkEindAdres = 2;
      when 'NVT' then set @_OrkEindAdres = 3;
      else call Raise(20700, 'Eindadres');  //Ongeldige waarde: <parameter of opmerking>
    end case;
  end if;

  if @_OrkEindAdres = 2 /*VERZ*/ then
    if @EindAdresNummer is not null then
      set @_OrkAdrGidEindAdres = ( select AdrGid from tabAdres where AdrCode = @EindAdresNummer and AdrNawGid = @_NawGid );
      //ACW Defect 59772: Eindadresnummer niet verplicht, dus alleen testen als eindadres is meegegeven
      if @_OrkAdrGidEindAdres is null then
        call Raise(20700, 'EindAdresNummer');  //Ongeldige waarde: <parameter of opmerking>
      end if;
    end if;
  end if;

  // Niets meegegeven? dan defaults opvragen indien aangegeven.
  if @_OrkEindAdres is null and @_OrkAdrGidEindAdres is null and @Gebruikdefaults = _qcJA then
    select NawEindAdres, case NawEindAdres when 2 then NawGidEindAdres else null end case
    into @_OrkEindAdres, @_OrkAdrGidEindAdres
    from tabNaw
    where NawGid = @_NawGid;
  end if;

  if IsNull(@AparteFactuur, '') <> '' then
    case @AparteFactuur
      when 'JA' then set @_OrkApartFaktureren = 0;
      when 'NEE' then set @_OrkApartFaktureren = 1;
      when 'PERCONTACTPERSOON' then set @_OrkApartFaktureren = 2;
      when 'PERVERZENDADRES' then set @_OrkApartFaktureren = 3;
      when 'PERCONTACTPERSOONENVERZENDADRES' then set @_OrkApartFaktureren = 4;
      else call Raise(20660); //Ongeldige of geen AparteFactuur meegegeven
    end case;
  else
    set @_OrkApartFaktureren = 0; // Er moet een waarde zijn
    select NawAparteFacturen into @_OrkApartFaktureren from tabNaw where nawGid = @_NawGid and @Gebruikdefaults = _qcJA;
  end if;

  if IsNull(@AparteLevering, '') <> '' then
    case @AparteLevering
      when 'JA' then set @_OrkApartLevering = 0;
      when 'NEE' then set @_OrkApartLevering = 1;
      when '1' then set @_OrkApartLevering = 0;
      when '0' then set @_OrkApartLevering = 1;
      else call Raise(20700, 'AparteLevering'); //(20700) Ongeldige waarde: %1!
    end case;
  else
    set @_OrkApartLevering = 0; // Er moet een waarde zijn
    select NawAparteLevering into @_OrkApartLevering from tabNaw where nawGid = @_NawGid and @Gebruikdefaults = _qcJA;
  end if;

  if IsNull(@Deellevering, '') <> '' then
    case @Deellevering
      when 'NIET_TOEGESTAAN' then set @_OrkIsDeelLeveringToegestaan = 0;
      when 'TOEGESTAAN'      then set @_OrkIsDeelLeveringToegestaan = 1;
      else call Raise(20661); //Ongeldige of geen DeelleveringToegestaan meegegeven
    end case;
  else
    set @_OrkIsDeelLeveringToegestaan = 0; // Er moet een waarde zijn
    select  case NawIsDeelleveringToegestaan
              when 2 then (select vofKopDefDeellevering from tabVasteGegevensOrdersFactureren)
              else IsNull(NawIsDeelleveringToegestaan,0)
            end case into @_OrkIsDeelLeveringToegestaan from tabNaw where NawGid = @_NawGid and @Gebruikdefaults = _qcJA;
  end if;

  if IsNull(@Verzamellijst, '') <> '' then
    case @Verzamellijst
      when 'NIET' then set @_OrkIsVerzamellijstGebruiken = _qcNEE;
      when 'WEL'  then set @_OrkIsVerzamellijstGebruiken = _qcJA;
      else call Raise(20662); //Ongeldige of geen VerzamellijstGebruiken meegegeven
    end case;
  else
    set @_OrkIsVerzamellijstGebruiken = _qcNEE;  // Er moet een waarde zijn
    select vofIsVerzamelLijstGebruiken into @_OrkIsVerzamellijstGebruiken from tabVasteGegevensOrdersFactureren where @Gebruikdefaults = _qcJA;
  end if;

  if IsNull(@VervoerderNaam, '') <> '' then
    select VrvGid into @_OrkVrvGid from tabVervoerder where VrvNaam = @VervoerderNaam;
    if (@_OrkVrvGid is null) then
      call Raise(20510);  //Ongeldige of geen VervoerderNaam meegegeven
    end if;
  else
    select NawVrvGid into @_OrkVrvGid from tabNaw where NawGid = @_NawGid and @Gebruikdefaults = _qcJA; // default vervoerder bij debiteur
    if (@_OrkVrvGid is null) then
      select LndVrvGid into @_OrkVrvGid from tabLand inner join tabAdres on AdrLndGid = LndGid where AdrGid = @_NawGid and @Gebruikdefaults = _qcJA; // default vervoerder bij land van debiteur (vestiging)
    end if;
    if (@_OrkVrvGid is null) then
      select VrvGid into @_OrkVrvGid from tabVervoerder where VrvIsDefault = 1 and @Gebruikdefaults = _qcJA; // default vervoerder (bij vaste gegevens orders)
    end if;
  end if;

  // Deze veld moet waarde hebben, is verplicht
  select MagGid into @_OrkDefaultMagGid from tabMagazijn where MagCode = @MagazijnCode;
  if (@_OrkDefaultMagGid is null) then
    call Raise(20511);  //Ongeldige of geen MagazijnCode meegegeven
  end if;

  // Deze veld moet waarde hebben, is verplicht
  select ValNummer into @_ValNummer from tabValuta where ValCode = @ValutaCode;
  if (@_ValNummer is null) then
    call Raise(20512);  //Ongeldige of geen ValutaCode meegegeven
  end if;

  if @VertegenwoordigerNummer is not null then
    select VtgCode into @_OrkVtgCode from tabVertegenWoordiger where VtgCode = @VertegenwoordigerNummer;
    if (@_OrkVtgCode is null) then
      call Raise(20513);  //Ongeldige of geen VertegenwoordigerNummer meegegeven
    end if;
  else // vertegenwoordiger debiteur mits bij vaste gegevens orders/facturering ingesteld.
    select  case vofKopDefVtg
              when 2 then (select NawVertegenwCode from tabnaw where NawGid = @_NawGid)
              when 1 then (select VtgCode from tabVertegenwoordiger inner join tabRelatie on VtgRelGid = RelGid inner join tabGebruiker on RelGid = GebrRelGid and Naamgebruiker = @@GebruikerNaam)
              else null
            end case into @_OrkVtgCode from tabVasteGegevensOrdersFactureren where @Gebruikdefaults = _qcJA;
  end if;

  if @BetalingsConditieNummer is not null then
    select BtcNummer into @_BtcNummer from tabBetalingsConditie where BtcNummer = @BetalingsConditieNummer;
    if (@_BtcNummer is null) then
      call Raise(20514);  //Ongeldige of geen BetalingsConditieNummer meegegeven
    end if;
  else
    select NawFilBtcNummer into @_BtcNummer from tabNawFile where NawFilNawGid = @_NawGid and @Gebruikdefaults = _qcJA;
  end if;

  if @LeveringsConditieNummer is not null then
    select LvcNummer into @_LvcNummer from tabLeveringsConditie where LvcNummer = @LeveringsConditieNummer;
    if (@_LvcNummer is null) then
      call Raise(20515);  //Ongeldige of geen LeveringsConditieNummer meegegeven
    end if;
  else
    select NawFilLvcNummer into @_LvcNummer from tabNawFile where NawFilNawGid = @_NawGid and @Gebruikdefaults = _qcJA;
  end if;

  if @OrderKortingsPercentage is not null then
    if (@OrderKortingsPercentage < -100) or (@OrderKortingsPercentage > 100) then
      call Raise(20516);  //Ongeldige of geen OrderKortingsPercentage meegegeven
    end if;
  else // default gebruiken? Dan van Inkoopcombinatie indien bekend, anders van de orderdebiteur
    select case NawFilWelkeOrderKorting
      when 0 then (select NawOrderKorting from tabNaw where NawGid = NawFilNawGid)
      when 1 then (select DebGrpOrderKorting from tabDebiteurgroepen where debGrpGid = NawFilDebGrpGid)
      else null
      end case into @OrderKortingsPercentage
    from tabNawFile
    where NawFilNawGid = IsNull(@_OrkFactuurNawGid,@_NawGid) and @Gebruikdefaults = _qcJA;
  end if;

  if IsNull(@OrderNummer, 0) = 0 then
    call OrdersGenereerNieuwOrderNummer(0, 1, @OrderNummer);
  else
    select OrkGid into @_OrkGid from tabOrderKop where OrkSoort = 0 and OrkNummer = @OrderNummer;
    if (@_OrkGid is not null) then
      call Raise(20517);  //OrderNummer komt al voor
    end if;
  end if;

  if IsNull(@ExternOrderID, '') <> '' then
    if exists(select 1 from tabOrderKop where OrkExternId = @ExternOrderID) then
      call Raise(20518);  //ExternOrderID komt al voor
    end if;
  end if;

  set @OrderDatum  = (select DateTimeConversieVoorWebServices(@OrderDatum, @OrderDatum));

  set @LeverDatum  = (select DateTimeConversieVoorWebServices(@LeverDatum , @LeverDatum ));
  set @LeverDatum = IsNull(@Leverdatum, ( select  case vofKopDefLeverdatum
                                                    when 1 then date(Now())
                                                    when 2 then @@VerwerkingsDatum
                                                    when 3 then @OrderDatum // Geldige datum, moet voor de orderkop ingevuld zijn
                                                    else null
                                                  end case from tabVasteGegevensOrdersFactureren where @Gebruikdefaults = _qcJA ) );

  set @EdiOrder = IsNull(@EdiOrder, (select vofKopIsEDIorder from tabVasteGegevensOrdersFactureren where @Gebruikdefaults = _qcJA));

  set @referentie = IsNull(@referentie, (select vofKopDefReferentie from tabVasteGegevensOrdersFactureren where @Gebruikdefaults = _qcJA));

  set @PrijzenInclusiefBtw = IsNull(@PrijzenInclusiefBtw, (select NawFacturerenInclBtw from tabNaw where NawGid = @_NawGid and @Gebruikdefaults = _qcJA ));

  // Ingangscontroles gedaan.
  // Nu de overige defaults, zoals orders.xml import ook werkt, en
  // bankrekening(en) bij de btc die incasso betreft.
  begin
    declare @_OrkIncNawRekGid integer;
    declare @_OrkGoedgekeurd smallint = _qcNEE; // nieuwe order standaard niet goedkeuren

    if @Gebruikdefaults = _qcJA then
      // incasso bankrekening op basis van betalingsconditie
      select first NawRekGid into @_OrkIncNawRekGid from tabNawRekening
      where NawRekNawGid = @_NawGid and NawRekSoort like '%I%' and NawRekIsIban = 1
        and exists (select 1 from tabBetalingsConditie where BtcNummer = @_BtcNummer and SoortFactuurBtc = 3);

      // Eindbestemming
      // select NawEindAdres, case NawEindAdres when 2 then NawGidEindAdres else null end case into @_OrkEindAdres, @_OrkAdrGidEindAdres from tabNaw where NawGid = @_NawGid;

      // Goedkeuring order
      select vofKopDefIsGoedgekeurd into @_OrkGoedgekeurd from tabVasteGegevensOrdersFactureren;

      // CBS
      if (IsModuleActive('c1') = 1) then
        select CbsVastExtraHandelNaarCbsIris,  CbsVastCbsGsGidUitvoer,  CbsVastCbsSsGidUitvoer,  CbsVastPtnGidUitvoer,  CbsVastCbsVwGidUitvoer,  CbsVastCbsCoGidUitvoer,  CbsVastCbsTrGidUitvoer
         into  @_CbsExtra,                     @_CbsVastCbsGsGidUitvoer, @_CbsVastCbsSsGidUitvoer, @_CbsVastPtnGidUitvoer, @_CbsVastCbsVwGidUitvoer, @_CbsVastCbsCoGidUitvoer, @_CbsVastCbsTrGidUitvoer
        from tabCbsVast;

        case @_OrkVerzendAdres
          when 0 then set @_tmpAdrGid = (select NawGidCorrespondentie from tabNaw where NawGid = @_NawGid);
          when 1 then set @_tmpAdrGid = (select NawGidVestiging from tabNaw where NawGid = @_NawGid);
          when 2 then set @_tmpAdrGid = @_OrkAdrGid;
          when 3 then set @_tmpAdrGid = (select NawGidCorrespondentie from tabNaw where NawGid = @_OrkFactuurNawGid);
          when 4 then set @_tmpAdrGid = (select NawGidVestiging from tabNaw where NawGid = @_OrkFactuurNawGid);
          when 5 then set @_tmpAdrGid = @_OrkAdrGid;
        end case;

        set @_OrkCbsLndGidBestemming = (select AdrLndGid from tabAdres where AdrGid = @_tmpAdrGid);

        set @_OrkCbsMeenemenInAangifte = IsNull(if (@_OrkCbsLndGidBestemming <> (select DefaultLndGid from tabVasteGegevens)) and
                                               ((@_CbsExtra <> 0) or (select LndIsEGLid from tabLand where LndGid = @_OrkCbsLndGidBestemming) <> 0) then 1 else 0 endif, 0);

        if @_OrkCbsMeenemenInAangifte = _qcNEE then
          set @_OrkCbsLndGidBestemming = null;
          set @_CbsVastCbsGsGidUitvoer = null;
          set @_CbsVastCbsSsGidUitvoer = null;
          set @_CbsVastPtnGidUitvoer   = null;
          set @_CbsVastCbsVwGidUitvoer = null;
          set @_CbsVastCbsCoGidUitvoer = null;
          set @_CbsVastCbsTrGidUitvoer = null;
        end if;
      end if; // Optie CBS actief

    end if; // GebruikDefaults

    // webshop configuratie gid opvragen
    if IsNull(@WebshopId, '') <> '' then
      select WscGid into @_OrkWscGid from tabWebshopConfiguratie where WscWebshopId = @WebshopId;

      if (@_OrkWscGid is null) then
        call Raise(20720, string('Webshop id ', @WebshopId));  // (20720) %1! niet gevonden!
      end if;
    end if;

    // ACW Defect 59772: Alleen als order een verzend- of eindadresnummer mist, en de order staat op Goedgekeurd, dan van Goedgekeurd afhalen
    if ((@_OrkVerzendAdres in (2 /*verzendadres orderdebiteur*/, 5 /*Verzenadres factuurdebiteur*/)) and @_OrkAdrGid is null)
      or ((@_OrkEindAdres = 2 /*Verzendadres orderdebiteur*/) and @_OrkAdrGidEindAdres is null) then
      set @_OrkGoedgekeurd = _qcNee;
    end if;

    insert into tabOrderKop(OrkSoort, OrkNummer, OrkExternId, OrkNawGid, OrkRelGid, OrkValNummer, OrkReferentie, OrkEmailExtraTekst, OrkDatum, OrkLeverdatum, OrkIsInkoopCombinatie, OrkFactuurNawGid, OrkNawGidOmzet, OrkNawGidPrijzen,
                            OrkFactuurAdres, OrkVerzendAdres, OrkAdrGid, OrkInclBtw, OrkBtcNummer, OrkLvcNummer, OrkDefaultMagGid, OrkVrvGid, OrkVtgCode, OrkIsEDIorder, OrkApartFaktureren, OrkApartLeveren,
                            OrkIsDeelLeveringToegestaan, OrkIsVerzamellijstGebruiken, OrkIncNawRekGid, OrkEindAdres, OrkAdrGidEindAdres, OrkGoedgekeurd,
                            OrkCbsMeenemenInAangifte, OrkCbslndGIDBestemming, OrkCbsGsGid, OrkCbsSsGid, OrkCbsPtnGidVerkeersgebied, OrkCbsVwGid, OrkCbsCoGid, OrkWscGid)
                     values(0, @OrderNummer, @ExternOrderID, @_NawGid, @_RelGid, @_ValNummer, @Referentie, @EmailExtraTekst, @OrderDatum, @LeverDatum , @_OrkIsInkoopcombinatie, @_OrkFactuurNawGid, @_OrkNawGidOmzet, @_OrkNawGidPrijzen,
                            @_OrkFactuurAdres, @_OrkVerzendAdres, @_OrkAdrGid, @PrijzenInclusiefBtw, @_BtcNummer, @_LvcNummer, @_OrkDefaultMagGid, @_OrkVrvGid, @_OrkVtgCode, @EdiOrder, @_OrkApartFaktureren, @_OrkApartLevering,
                            @_OrkIsDeelLeveringToegestaan, @_OrkIsVerzamellijstGebruiken, @_OrkIncNawRekGid, @_OrkEindAdres, @_OrkAdrGidEindAdres, @_OrkGoedgekeurd,
                            @_OrkCbsMeenemenInAangifte, @_OrkCbsLndGidBestemming, @_CbsVastCbsGsGidUitvoer, @_CbsVastCbsSsGidUitvoer, @_CbsVastPtnGidUitvoer, @_CbsVastCbsVwGidUitvoer, (if @_CbsExtra = 1 then @_CbsVastCbsCoGidUitvoer else null endif), @_OrkWscGid);
    set @_OrkGid = @@Identity;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid, @_LockResult, 0, 'KingWebService');
  end;

  // Vrije rubrieken vd debiteur overnemen naar order
  call OrdersOvernemenVrijeRubrieken(@_OrkGid);

  if IsNull(@OrderKortingsPercentage, 0 ) <> 0 then
    insert into tabOrderExtraRegel (OerOrkGid, OerBerekenOverToeslag, OerBerekenOverKorting, OerBerekenOverEmballage, OerBerekenOverArtikel, OerBerekenOverTarief, OerRegelnr,OerRegelSoort, OerOmschrijving, OerTekstOpFactuur, OerPerc)
    values (@_OrkGid,1, 1, 2, 2, 2, 0, 0, _A('Orderkorting'), _A('Orderkorting'), @OrderKortingsPercentage)
  end if;

  if IsNull(@Opmerking, '') <> '' then
    insert into tabOrderOpmerkingen (OrdOpmOrkGid, OrdOpmOpmerking) values (@_OrkGid, @Opmerking);
  end if;

  select OrkNummer as OrderNummer from tabOrderKop where OrkGid = @_OrkGid;

  //call TraceEind('WebSvcProc_Order_Toevoegen');
end;


create or replace procedure WebSvcProc_Order_Verwijderen(in @OrderNummer numeric(10,0))
begin
  declare @OrkGid      integer;
  declare @qLockGid    integer;
  declare @LockResult  integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_Verwijderen > @OrderNummer = ' + string(@OrderNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then
    select OrkGid into @OrkGid from tabOrderkop where OrkSoort = 0 and OrkNummer = @OrderNummer;
    if @OrkGid is null then
      call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
    end if;

    if exists(select 1 from tabOrderRegel where  (OrrOrkGid = @OrkGid) and (OrrRegelSoort = 2) and
              (((OrrAantalVrrdEenhInVerkEenhMagAfwijken = 0) and (Round(OrrAantalGeleverdVrrdEenh, OrrAantDecAantalVrrdEenh) <> Round(OrrAantalGefactureerdVrrdEenh, OrrAantDecAantalVrrdEenh))) or //Mag niet afwijken (vast aantal)
               ((OrrAantalVrrdEenhInVerkEenhMagAfwijken = 1) and (Round(OrrAantalGeleverd, OrrAantDecAantal) <> Round(OrrAantalGefactureerd, OrrAantDecAantal))) or //Mag afwijken bij aantal besteld
               ((OrrAantalVrrdEenhInVerkEenhMagAfwijken = 2) and ((Round(OrrAantalGeleverd, OrrAantDecAantal) <> Round(OrrAantalGefactureerd, OrrAantDecAantal)) or (Round(OrrAantalGeleverdVrrdEenh, OrrAantDecAantalVrrdEenh) <> Round(OrrAantalGefactureerdVrrdEenh, OrrAantDecAantalVrrdEenh)))))) then //Mag afwijken bij Levering/Facturering
      call Raise(20546); //Er zijn 1 of meerdere orderregels waarbij het ''aantal reeds geleverd'' ongelijk is aan het ''aantal reeds gefactureerd''
    end if;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @LockResult);
      if @LockResult <> 0 then
        call Raise(20531); //Order is in gebruik!
      end if;
    end if;

    delete tabOrderkop where OrkGid = @OrkGid;

    select qLockGid into @qLockGid from qtabLock where qLockUser = 'KingWebservice' and qLockTableName = 'tabOrderKop' and qLockPkey = @OrkGid;
    delete qtabLock where qLockGid = @qLockGid;

  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);

end;


create or replace procedure WebSvcProc_Order_VrijeRubriek_Wijzigen(in @OrderNummer numeric(10,0), in @RubriekOmschrijving nchar(40), in @RubriekInhoud  nchar(255))
begin
  declare @OrkGid       integer;
  declare @Lockresult   smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Order_VrijeRubriek_Wijzigen > @OrderNummer = ' + string(@OrderNummer) + ', @RubriekOmschrijving = ' + @RubriekOmschrijving;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') = 0 then
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;


  select OrkGid into @OrkGid from tabOrderKop where OrkSoort = 0 and OrkNummer = @OrderNummer;
  if (@OrkGid is null) then
    call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
  end if;

  if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @OrkGid, @LockResult, 0);
    if @LockResult <> 0 then
      call Raise(20531); //Order is in gebruik!
    end if;
  end if;

  if not exists(select 1 from tabVrORK000000 where VrORK000000RecordId = @OrkGid) then
    // Er is nog geen VR record, die gaan we aanmaken nu door deze wijziging, dan eerst de defaults voor alle velden vullen
    call VrijeRubriekenVulDefaults('ORK', 0, 0, @OrkGid, 0);
  end if;

  call VrInsertOrReplaceValue('ORK', 0, 0, @OrkGid, @RubriekOmschrijving, @RubriekInhoud);

  set @@ErrorTextProcedure = 'WebSvcProc_Order_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Order_Wijzigen(
  in @OrderNummer                  numeric(10,0),
  in @StatusGoedgekeurd            smallint default null,
  in @StatusVrijVoorFacturering    smallint default null,  // ivm backward compatibiliteit
  in @StatusVrijVoorLevering       smallint default null,
  in @StatusVrijVoorVerzamellijst  smallint default null,
  in @StatusVerzamellijstAfgedrukt smallint default null,
  in @StatusVerzamellijstVerwerkt  smallint default null,
  in @LeverDatum                   date default null
)
begin
  declare @_OrkGid                     integer;
  declare @_OrkIsVerzamellijstGebruiken smallint;
  declare @_OrkGoedgekeurd             smallint;
  declare @_OrkVrijVoorFaktureren      smallint;
  declare @_OrkVrijVoorVerzamelLijst   smallint;
  declare @_OrkVerzamelLijstAfgedrukt  smallint;
  declare @_OrkVerzamelLijstVerwerkt   smallint;
  declare @_OrkVrijVoorLevering        smallint;
  declare @_OrkLeverDatum              date;

  //call TraceBegin('WebSvcProc_Order_Wijzigen > @OrderNummer = ' + string(@OrderNummer));

  if IsModuleActive('wo') = 0 then
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  // ******************************
  // *** ORDERGEGEVENS OPZOEKEN ***
  // ******************************

  select OrkGid,   OrkGoedgekeurd,   OrkVrijVoorFaktureren,   OrkVrijVoorVerzamelLijst,   OrkVerzamelLijstAfgedrukt,   OrkVerzamelLijstVerwerkt,   OrkVrijVoorLevering,   OrkLeverDatum, OrkIsVerzamellijstGebruiken
  into   @_OrkGid, @_OrkGoedgekeurd, @_OrkVrijVoorFaktureren, @_OrkVrijVoorVerzamelLijst, @_OrkVerzamelLijstAfgedrukt, @_OrkVerzamelLijstVerwerkt, @_OrkVrijVoorLevering, @_OrkLeverDatum, @_OrkIsVerzamellijstGebruiken
  from   tabOrderkop
  where  OrkSoort = 0 and OrkNummer = @OrderNummer;

  // ***********************
  // *** INGANGSCONTROLE ***
  // ***********************

  if @_OrkGid is null then
    call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
  end if;

  // -------------------
  // Status: Leverdatum
  // -------------------
  if @LeverDatum is not null then
    set @_OrkLeverDatum = @LeverDatum;
  end if;

  if @StatusGoedgekeurd is not null and @StatusGoedgekeurd not in (0,1) then
    call Raise(20672); //Ongeldige of geen StatusGoedgekeurd meegegeven!
  end if;

  if @StatusVrijVoorVerzamellijst is not null and @StatusVrijVoorVerzamellijst not in (0,1) then
     call Raise(20700, _U('Vrijgegeven voor verzamellijst')); //(20677) Ongeldige waarde: %1!
  end if;

  if @StatusVrijVoorFacturering is not null and @StatusVrijVoorFacturering not in (0,1) then
     call Raise(20700, _U('Vrijgegeven voor facturering')); //(20677) Ongeldige waarde: %1!
  end if;

  if @StatusVerzamellijstAfgedrukt is not null and @StatusVerzamellijstAfgedrukt not in (0,1) then
     call Raise(20700, _U('Verzamellijst afgedrukt')); //(20677) Ongeldige waarde: %1!
  end if;

  if @StatusVerzamellijstVerwerkt is not null and @StatusVerzamellijstVerwerkt not in (0,1) then
     call Raise(20700, _U('Verzamellijst verwerkt')); //(20677) Ongeldige waarde: %1!
  end if;

  if @StatusVrijVoorLevering is not null and @StatusVrijVoorLevering not in (0,1) then
     call Raise(20700, _U('Vrijgegeven voor levering')); //(20677) Ongeldige waarde: %1!
  end if;

  // Alle statussen onthouden
  set @_OrkGoedgekeurd             = isnull(@StatusGoedgekeurd           , @_OrkGoedgekeurd           );
  set @_OrkVrijVoorFaktureren      = isnull(@StatusVrijVoorFacturering   , @_OrkVrijVoorFaktureren    );
  set @_OrkVrijVoorVerzamelLijst   = isnull(@StatusVrijVoorVerzamellijst , @_OrkVrijVoorVerzamelLijst );
  set @_OrkVerzamelLijstAfgedrukt  = isnull(@StatusVerzamellijstAfgedrukt, @_OrkVerzamelLijstAfgedrukt);
  set @_OrkVerzamelLijstVerwerkt   = isnull(@StatusVerzamellijstVerwerkt , @_OrkVerzamelLijstVerwerkt );
  set @_OrkVrijVoorLevering        = isnull(@StatusVrijVoorLevering      , @_OrkVrijVoorLevering      );

  // *****************
  // *** Controles ***
  // *****************

  // -----------------------
  // Status: Goedgekeurd AAN
  // -----------------------
  if @StatusGoedgekeurd is not null then
    if @StatusGoedgekeurd = 1 then
      // AAN
      // Controleer of verzendadres is ingevuld
      if not exists(select first 1 from tabOrderkop where OrkSoort = 0 and OrkGid = @_OrkGid and (OrkVerzendAdres in (1 /*vest.*/, 0 /*corr.*/, 4 /*fact.vest.*/, 3 /*fact.corr.*/) or OrkAdrGid is not null)) then
         call Raise(20780, _U('Goedkeuren'), _U('Verzendadres is niet ingevuld')); // (20780) %1! niet mogelijk: %2!.
      end if;

      // Controleer of eindadres is ingevuld
      if not exists(select first 1 from tabOrderkop where OrkSoort = 0 and OrkGid = @_OrkGid and (OrkEindAdres in (1 /*vestiging*/, 0 /*correspondentie*/, 3 /*nvt*/) or OrkAdrGidEindAdres is not null)) then
         call Raise(20780, _U('Goedkeuren'), _U('Eindadres is niet ingevuld')); // (20780) %1! niet mogelijk: %2!.
      end if;
      // Alleen wel op goedgekeurd zetten is mogelijk, uit zetten moeten we juist als laatste proberen, zodat alle andere statussen reeds zijn gezet
    else
      // UIT
      // Alleen van goedgekeurd afhalen is mogelijk, aan zetten is hierboven al gebeurd
      if @_OrkVrijVoorFaktureren +
         @_OrkVrijVoorVerzamelLijst +
         @_OrkVerzamelLijstAfgedrukt+
         @_OrkVerzamelLijstVerwerkt +
         @_OrkVrijVoorLevering > 0 then
         call Raise(20780, _U('Goedkeuring annuleren'), _U('order is vrijgegeven voor verzamellijst, levering en/of facturering')); // (20780) %1! niet mogelijk: %2!.
      end if;
    end if;
  end if;


  // -----------------------------
  // Status: Vrij voor facturering
  // -----------------------------
  if @StatusVrijVoorFacturering is not null then
    if @StatusVrijVoorfacturering = 1 and @_OrkGoedgekeurd <> 1 then
       call Raise(20761, _U('Alleen een goedgekeurde order kan worden vrijgegeven voor facturering!'));
    end if;
  end if;


  // ***************************************
  // *** Status: Vrij voor verzamellijst ***
  // ***************************************
  if @StatusVrijVoorVerzamellijst is not null then
    if @_OrkIsVerzamellijstGebruiken = 0 then
       call Raise(20780, _U('Vrijgeven voor verzamellijst'), _U('Voor deze order wordt geen gebruikt gemaakt van verzamellijst')); // (20780) %1! niet mogelijk: %2!.
    end if;

    // AAN
    if @StatusVrijVoorVerzamellijst = 1 and @_OrkGoedgekeurd <> 1 then
       call Raise(20761, _U('Alleen een goedgekeurde order kan worden vrijgegeven voor verzamellijst!'));
    end if;

    // UIT
    if @StatusVrijVoorVerzamellijst = 0 and @_OrkVerzamelLijstAfgedrukt + @_OrkVerzamelLijstVerwerkt <> 0 then
       call Raise(20780, _U('Vrijgeven voor verzamellijst annuleren'), _U('Verzamellijst is al afgedrukt of verwerkt')); // (20780) %1! niet mogelijk: %2!.
    end if;
  end if;

  // ***************************************
  // *** Status: Verzamellijst afgedrukt ***
  // ***************************************
  if @StatusVerzamellijstAfgedrukt is not null then
    if @_OrkIsVerzamellijstGebruiken = 0 then
       call Raise(20780, _U('verzamellijst afdrukken'), _U('Voor deze order wordt geen gebruikt gemaakt van verzamellijst')); // (20780) %1! niet mogelijk: %2!.
    end if;

    // AAN
    if @StatusVerzamellijstAfgedrukt = 1 and @_OrkVrijVoorVerzamelLijst <> 1 then
       call Raise(20761, _U('Alleen een vrijgegeven verzamellijst kan afgedrukt zijn!'));
    end if;

    // UIT
    if @StatusVerzamellijstAfgedrukt = 0 and @_OrkVerzamelLijstVerwerkt = 1 then
       call Raise(20780, _U('Verzamellijst niet afgedrukt'), _U('De verzamellijst is al verwerkt')); // (20780) %1! niet mogelijk: %2!.
    end if;


  end if;

  // **************************************
  // *** Status: Verzamellijst verwerkt ***
  // **************************************
  if @StatusVerzamellijstVerwerkt is not null then
    if @_OrkIsVerzamellijstGebruiken = 0 then
       call Raise(20780, _U('Vrijgeven voor verzamellijst'), _U('Voor deze order wordt geen gebruikt gemaakt van verzamellijst')); // (20780) %1! niet mogelijk: %2!.
    end if;

    if @StatusVerzamellijstVerwerkt = 1 and @_OrkVerzamelLijstAfgedrukt <> 1 then
       call Raise(20761, _U('Alleen een afgedrukte verzamellijst kan zijn verwerkt!'));
    end if;
  end if;



  // --------------------------
  // Status: Vrij voor levering
  // --------------------------
  if @StatusVrijVoorLevering is not null then
    if @StatusVrijVoorLevering = 1 and @_OrkGoedgekeurd <> 1 then
       call Raise(20761, _U('Alleen een goedgekeurde order kan worden vrijgegeven voor levering!'));
    end if;

    // Vrij voor leveren kan niet als verzamellijst nog niet verwerkt is en de levering wel via verzamellijst moet.
    if @StatusVrijVoorLevering = 1 then
      // Controle op verwerkte verzamellijst
      if @_OrkIsVerzamellijstGebruiken = 1 and @_OrkVerzamellijstVerwerkt = 0 then
         call Raise(20780, _U('Vrijgeven voor levering'), _U('Verzamellijst is niet verwerkt')); // (20780) %1! niet mogelijk: %2!.
      end if;

      // Controle op deellevering
      if exists ( select first 1
                  from tabOrderRegel inner join tabOrderKop on OrkGid = OrrOrkGid and OrkGid = @_OrkGid
                  where OrkIsDeelLeveringToegestaan <> 1
                    and OrrAantalBackorderVrrdEenh <> 0
                )
      then
         call Raise(20780, _U('Vrijgeven voor levering'), _U('Deellevering niet toegestaan')); // (20780) %1! niet mogelijk: %2!.
      end if;
    end if;
  end if;



  // ***********************
  // *** Order bijwerken ***
  // ***********************

  begin atomic // Start transactie
    declare @LockInProcGezet smallint = 0;
    declare @LockResult      integer;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid) = 0 then  //Als de order nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid, @LockResult);
      if @LockResult <> 0 then
        call Raise(20741, _U('Order')); //(20741) %1! is in gebruik!
      end if;
      set @LockInProcGezet = 1;
    else
      if LockedByUser('tabOrderKop', @_OrkGid) <> 'KingWebservice' then
        call Raise(20741, _U('Order')); //(20741) %1! is in gebruik!
      end if;
    end if;

    update tabOrderkop
    set
        OrkGoedgekeurd                = @_OrkGoedgekeurd,
		    OrkLeverDatum                 = @_OrkLeverDatum,

		    OrkVrijVoorFaktureren         = @_OrkVrijVoorFaktureren,
        OrkVrijgegevenDoor            = if OrkVrijVoorFaktureren <> @_OrkVrijVoorFaktureren and @_OrkVrijVoorFaktureren = 1 then 'KingWebservice' else OrkVrijgegevenDoor endif,

        OrkVrijVoorVerzamelLijst      = @_OrkVrijVoorVerzamelLijst,
        OrkVrijVoorVerzamelLijstDoor  = if OrkVrijVoorVerzamelLijst <> @_OrkVrijVoorVerzamelLijst and @_OrkVrijVoorVerzamelLijst = 1 then 'KingWebservice' else OrkVrijVoorVerzamelLijstDoor endif,

        OrkVerzamelLijstAfgedrukt     = @_OrkVerzamelLijstAfgedrukt,
        OrkVerzamelLijstAfgedruktDoor = if OrkVerzamelLijstAfgedrukt <> @_OrkVerzamelLijstAfgedrukt and @_OrkVerzamelLijstAfgedrukt = 1 then 'KingWebservice' else OrkVerzamelLijstAfgedruktDoor endif,

        OrkVerzamelLijstVerwerkt      = @_OrkVerzamelLijstVerwerkt,
        OrkVerzamelLijstVerwerktDoor  = if OrkVerzamelLijstVerwerkt <> @_OrkVerzamelLijstVerwerkt then 'KingWebservice' else OrkVerzamelLijstVerwerktDoor endif,

        OrkVrijVoorLevering           = @_OrkVrijVoorLevering,
        OrkVrijVoorLeveringDoor       = if OrkVrijVoorLevering   <> @_OrkVrijVoorLevering   and @_OrkVrijVoorLevering   = 1 then 'KingWebservice' else OrkVrijVoorLeveringDoor endif
    where OrkGid = @_OrkGid;

    // Als na vrij voor leveren ineens nog niet alle locaties zijn ingevuld, dan annuleren
    if @StatusVrijVoorLevering = 1 then
      //if exists(select first 1 from taborderkop where OrkGid = @_OrkGid and OrkVrijVoorLevering = 0) then
      if VerkooporderHeeftSpecregelsZonderLocatie(@_OrkGid) = 1 then
        // We willen vrij voor leveren, maar dat is blijkbaar niet gelukt (doordat er lege locaties in de specregels staan)
         call Raise(20780, _U('Vrijgeven voor levering'), _U('Er zijn specificatieregels zonder ingevulde locatie')); // (20780) %1! niet mogelijk: %2!.
      end if;
    end if;



    if @LockInProcGezet = 1 then
      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid);
    end if;
  end; // Einde transactie
  //call TraceEind('WebSvcProc_Order_Wijzigen');

end;

// ********** Test buiten King Webservice om **********
// call WebSvcProc_Order_Wijzigen( 25000034 /* demoArt order */, 1, 0, 1 );
// delete qtabLock where qLockTableName = 'tabOrderKop' and qLockPkey in (select OrkGid from taborderkop where OrkSoort = 0 and OrkNummer = 25000034); /* DemoArt Order */


create or replace procedure WebSvcProc_Project_Werkbon_LockVrijgeven(in @WerkbonVolgnummer numeric(10,0))
begin
  declare @PwbkGid  integer;
  declare @qLockGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Project_Werkbon_LockVrijgeven';
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then

    if IsNull(@WerkbonVolgnummer, 0) = 0 then
      call Raise(20626); //Ongeldige of geen WerkbonVolgnummer meegegeven!
    else
      select PwbkGid into @PwbkGid from tabProjectWerkbonKop where PwbkVolgnummer = @WerkbonVolgnummer;
      if (@PwbkGid is null) then
        call Raise(20626); //Ongeldige of geen WerkbonVolgnummer meegegeven!
      end if;
    end if;

    select qLockGid into @qLockGid from qtabLock where qLockUser = 'KingWebservice' and qLockTableName = 'tabProjectWerkbonKop' and qLockPkey = @PwbkGid;
    if @qLockGid is null then
      call Raise(20548); //Lock niet gevonden!
    else
      delete qtabLock where qLockGid = @qLockGid
    end if;
  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Project_Werkbon_LockVrijgeven';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Project_Werkbon_Regel_ToevoegenWijzigen(in @WerkbonVolgnummer numeric(10,0), in @RegelNummer integer, in @ProjectOnderdeelZoekCode nchar(40), in @MutatieSoort nchar(14), in @ArtikelNummer nchar(20),
                                                                               in @Categorieen long nvarchar, in @AantalBesteed numeric(15,3), in @AantalDeclarabel numeric(15,3),
                                                                               in @MagazijnCode numeric(3,0), in @LocatieCode nchar(20), in @KostPrijs numeric(15,3), in @VerkoopPrijs numeric(15,3), in @Serienummer nchar(20),
                                                                               in @Opmerking long nvarchar, in @ExternID nchar(50), in @Omschrijving long nvarchar, in @MedewerkerExtern smallint,
                                                                               in @MedewerkerCrediteurNummer nchar(10), in @MedewerkerNummer numeric(3,0))
result(RegelNummer integer)
begin
  declare @PwbkGid           integer;
  declare @PwbrGid           integer;
  declare @PwbkStatus        smallint;
  declare @PwbrPbGid         integer;
  declare @ProjGid           integer;
  declare @RelGid            integer;
  declare @ArtGid            integer;
  declare @MagGid            integer;
  declare @LocGid            integer;
  declare @ArtSerieGid       integer;
  declare @ArtSeriePartijGid integer;
  declare @MutSoort          smallint;
  declare @ArtSoort          smallint;
  declare @ToevoegMode       smallint;
  declare @HuidigSoort       smallint;
  declare @IslockGelukt      smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Project_Werkbon_Regel_ToevoegenWijzigen > @WerkbonVolgnummer = ' + string(@WerkbonVolgnummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then

    set @ToevoegMode = if @RegelNummer is null then 1 else 0 endif;

    if (IsNull(@MutatieSoort, '') <> '') or (@ToevoegMode = 1) then
      case @MutatieSoort
        when 'ACTIVITEIT' then
          set @MutSoort = 0;
          set @ArtSoort = 1;
        when 'OVERIGE_KOSTEN' then
          set @MutSoort = 1;
          set @ArtSoort = 1;
        when 'ARTIKEL' then
          set @MutSoort = 2;
          set @ArtSoort = 2;
        when 'TEKSTBLOK' then
          set @MutSoort = 3;
          set @ArtSoort = 0;
        else call Raise(20632); //Ongeldige of geen MutatieSoort meegegeven!
      end case;
    end if;

    select PwbkGid, PwbkProjGid, PwbkStatus into @PwbkGid, @ProjGid, @PwbkStatus from tabProjectWerkbonKop where PwbkVolgnummer = @WerkbonVolgnummer;
    if @PwbkGid is null then
      call Raise(20626); //Ongeldige of geen WerkbonVolgnummer meegegeven!
    end if;
    if @PwbkStatus = 3 /* Afgehaneld */ then
      call Raise(20627); //Werkbon kan niet meer gewijzigd worden, omdat de status al op "Afgehandeld" staat!
    end if;

    if @ToevoegMode = 0 then
      select PwbrGid, PwbrMutSoort into @PwbrGid, @HuidigSoort from tabProjectWerkbonRegel where PwbrPwbkGid = @PwbkGid and PwbrRegelnr = @RegelNummer;
      if @PwbrGid is null then
        call Raise(20520); //Ongeldige of geen RegelNummer meegegeven!
      end if;
      if (@MutSoort is not null) and (@MutSoort <> @HuidigSoort) then
        call Raise(20633); //MutatieSoort mag niet worden gewijzigd!
      end if;
    end if;

    if (IsNull(@ProjectOnderdeelZoekCode, '') <> '') or (@ToevoegMode = 1) then
      select PbGid into @PwbrPbGid from tabProjectBoom where PbZoekCode = @ProjectOnderdeelZoekCode and PbProjGid = @ProjGid;
      if @PwbrPbGid is null then
        call Raise(20634); //Ongeldige of geen ProjectOnderdeelZoekCode meegegeven!
      end if;
    end if;

    if IsNull(@MedewerkerExtern, 0) not in (0,1) then
      call Raise(20635); //Ongeldige of geen MedewerkerExtern meegegeven!
    end if;

    if (IsNull(@MedewerkerNummer, '') <> '') and (@MedewerkerExtern is not null)then
      if (@MedewerkerExtern = 1) then
        select RelGid into @RelGid from tabRelatie inner join tabNawFile on (RelNawGid = NawFilNawGid and NawFilFonId = 'C' and NawFilNummer = @MedewerkerCrediteurNummer) where RelNummer = @MedewerkerNummer;
      else
        select RelGid into @RelGid from tabRelatie inner join tabNawFile on (RelNawGid = NawFilNawGid and NawFilFonId = 'B' and NawFilNummer = '00000000') where RelNummer = @MedewerkerNummer;
      end if;
      if @RelGid is null then
        call Raise(20636); //Ongeldige of geen MedewerkerNummer meegegeven!
      end if;
    end if;

    if (@ArtSoort = 2) then
      if (IsNull(@MagazijnCode, '') <> '') or (@ToevoegMode = 1) then
        select MagGid into @MagGid from tabMagazijn where MagCode = @MagazijnCode;
        if @MagGid is null then
          call Raise(20511); //Ongeldige of geen MagazijnCode meegegeven!
        end if;
      end if;

      if IsNull(@LocatieCode, '') = '' then
        if (@ToevoegMode = 1) then
          select LocGid into @LocGid from tabLocatie where LocMagGid = @MagGid and LocNaam = '(Standaard)';
        else
          if @MagGid is not null then  //Als we het magazijn van een bestaande werkbonregel wijzigen en we geven geen nieuwe locatie mee, dan wel even controleren of de locatie ook bekend is in het nieuwe magazijn.
            select LocGid into @LocGid from tabLocatie where LocMagGid = @MagGid and LocNaam = (select a.LocNaam from tabProjectWerkbonRegel inner join tabLocatie a on (a.LocGid = PwbrLocGid) where PwbrGid = @PwbrGid);
            if @LocGid is null then
              call Raise(20534); //Ongeldige of geen LocatieCode meegegeven
            end if;
          end if;
        end if;
      else
        select LocGid into @LocGid from tabLocatie where LocMagGid = @MagGid and LocNaam = @LocatieCode;
        if @LocGid is null then
          call Raise(20534); //Ongeldige of geen LocatieCode meegegeven
        end if;
      end if;
    end if;

    if (IsNull(@ArtikelNummer, '') <> '') or (@ToevoegMode = 1) then
      if (@ArtSoort in (0,2)) then
        select ArtGid into @ArtGid from tabArtikel where ArtSoort = @ArtSoort and ArtCode = @ArtikelNummer;
      else
        if @ArtSoort = 1 then
          select ArtGid into @ArtGid from tabArtikel inner join tabProjectArtikel on (pArtArtgid = ArtGid and pArtSoort = @MutSoort) where ArtSoort = @ArtSoort and ArtCode = @ArtikelNummer;
        end if;
      end if;
      if @ArtGid is null then
        call Raise(20524); //Ongeldige of geen ArtikelNummer meegegeven!
      end if;
    end if;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabProjectWerkbonKop', @PwbkGid) = 0 then  //Als de werkbon nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabProjectWerkbonKop', @PwbkGid, @IslockGelukt, 0, 'KingWebservice');
      if @IslockGelukt <> 0 then
        call Raise(20628); //Werkbon is in gebruik!
      end if;
    end if;

    if @ToevoegMode = 1 then
      if IsNull(@Serienummer, '') <> '' then
        select ArtSerieGid, ArtSeriePartijGid into @ArtSerieGid, @ArtSeriePartijGid from tabArtikelSerienummer where ArtSerieArtGid = @ArtGid and ArtSerienummer = @Serienummer;
        if @ArtSerieGid is null then
          call Raise(20536); //Ongeldige of geen Serienummer meegegeven!
        end if;
      end if;

      insert into tabProjectWerkbonRegel(PwbrPwbkGid, PwbrPbGid, PwbrMutSoort, PwbrArtGid, PwbrRelGid, PwbrSelectieCodes, PwbrAantalGeboekt, PwbrAantalDeclarabel, PwbrMagGid, PwbrLocGid, PwbrOpm, PwbrExternID, PwbrKostprijs, PwbrVerkoopprijs, PwbrOms, PwbrArtPartijGid)
                                  values(@PwbkGid, @PwbrPbGid, @MutSoort, @ArtGid, @RelGid, @Categorieen, @AantalBesteed, @AantalDeclarabel, @MagGid, @LocGid, @Opmerking, @ExternID, @KostPrijs, @VerkoopPrijs, @Omschrijving, @ArtSeriePartijGid);
      set @PwbrGid = @@Identity;

      if (@ArtSerieGid is not null) then
        insert into tabProjectWerkbonRegelDetail(PwbdPwbrGid, PwbdArtSerieGid, PwbdAantal)
        values(@PwbrGid, @ArtSerieGid, 1 * sign(@AantalBesteed));
      end if;
    else
      update tabProjectWerkbonRegel set PwbrArtGid = if PwbrMutSoort = 3 and @MutSoort = 3 then IsNull(@ArtGid, PwbrArtGid) else PwbrArtGid endif, //Alleen een tekstblok kan nog veranderd worden
                                        PwbrPbGid = IsNull(@PwbrPbGid, PwbrPbGid), PwbrRelGid = IsNull(@RelGid, PwbrRelGid), PwbrSelectieCodes = IsNull(@Categorieen, PwbrSelectieCodes),
                                        PwbrAantalGeboekt = IsNull(@AantalBesteed, PwbrAantalGeboekt), PwbrAantalDeclarabel = IsNull(@AantalDeclarabel, PwbrAantalDeclarabel),
                                        PwbrMagGid = IsNull(@MagGid, PwbrMagGid), PwbrLocGid = IsNull(@LocGid, PwbrLocGid),
                                        PwbrOpm = IsNull(@Opmerking, PwbrOpm), PwbrExternID = IsNull(@ExternID, PwbrExternID), PwbrKostprijs = IsNull(@KostPrijs, PwbrKostprijs),
                                        PwbrVerkoopprijs = IsNull(@VerkoopPrijs, PwbrVerkoopprijs), PwbrOms = IsNull(@Omschrijving, PwbrOms)
      where PwbrGid = @PwbrGid;
    end if;
    select PwbrRegelnr as RegelNummer from tabProjectWerkbonRegel where PwbrGid = @PwbrGid;
  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Project_Werkbon_Regel_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Project_Werkbon_Regel_Verwijderen(in @WerkbonVolgNummer numeric(10,0), in @RegelNummer integer)
begin
  declare @PwbkGid      integer;
  declare @PwbkStatus   smallint;
  declare @PwbrGid      integer;
  declare @IslockGelukt smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Project_Werkbon_Regel_Verwijderen > @WerkbonVolgNummer = ' + string(@WerkbonVolgNummer);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then

    select PwbkGid, PwbkStatus into @PwbkGid, @PwbkStatus from tabProjectWerkbonKop where PwbkVolgnummer = @WerkbonVolgNummer;
    if @PwbkGid is null then
      call Raise(20626); //Ongeldige of geen WerkbonVolgnummer meegegeven!
    end if;

    if @PwbkStatus = 3 /* Afgehaneld */ then
      call Raise(20627); //Werkbon kan niet meer gewijzigd worden, omdat de status al op "Afgehandeld" staat!
    end if;

    if LockedById(@@SpId, @@LoginTime, 1, 'tabProjectWerkbonKop', @PwbkGid) = 0 then  //Als de werkbon nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabProjectWerkbonKop', @PwbkGid, @IslockGelukt, 0, 'KingWebservice');
      if @IslockGelukt <> 0 then
        call Raise(20628); //Werkbon is in gebruik!
      end if;
    end if;

    select PwbrGid into @PwbrGid from tabProjectWerkbonRegel where PwbrPwbkGid = @PwbkGid and PwbrRegelnr = @RegelNummer;
    delete tabProjectWerkbonRegel where PwbrGid = @PwbrGid;
  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Project_Werkbon_Regel_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Project_Werkbon_ToevoegenWijzigen(in @ProjectCode nchar(10), in @WerkbonVolgNummer numeric(10,0), in @Status nchar(12), in @VoorraadGereserveerd smallint,
                                                                          in @AangemaaktDoor nchar(40), in @AangemaaktOp date, in @Omschrijving nchar(40), in @UitvoerenOp date, in @VoorbereidenOp date,
                                                                          in @Opmerking long nvarchar, in @ExternId nchar(50))
result(WerkbonVolgNummer numeric(10,0))
begin
  declare @PwbkGid       integer;
  declare @PwbkStatus    smallint;
  declare @OldPwbkStatus smallint;
  declare @ProjGid       integer;
  declare @IslockGelukt  smallint;

  set @@ErrorTextProcedure = 'WebSvcProc_Project_Werkbon_ToevoegenWijzigen > @ProjectCode = ' + @ProjectCode;
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('wo') <> 0 then

    if IsNull(@Status, '') <> '' then
      case @Status
        when 'CONCEPT'     then set @PwbkStatus = 0;
        when 'VOORBEREID'  then set @PwbkStatus = 1;
        when 'ONDERHANDEN' then set @PwbkStatus = 2;
        else call Raise(20629); //Ongeldige of geen Status meegegeven!
      end case;
    end if;

    if @WerkbonVolgNummer is null then

      select ProjGid into @ProjGid from tabProject where ProjCode = @ProjectCode;
      if @ProjGid is null then
        call Raise(20630); //Ongeldige of geen ProjectCode meegegeven!
      end if;

      if (@PwbkStatus is null) then
        call Raise(20629); //Ongeldige of geen Status meegegeven!
      end if;

      if (@VoorraadGereserveerd is null) then
        call Raise(20631); //Ongeldige of geen VoorraadGereserveerd meegegeven!
      end if;

      call ProjectWerkbonVolgnummerGenereren(0, @WerkbonVolgNummer);

      set @AangemaaktOp   = (select DateTimeConversieVoorWebServices(@AangemaaktOp, @AangemaaktOp));
      set @UitvoerenOp    = (select DateTimeConversieVoorWebServices(@UitvoerenOp, @UitvoerenOp));
      set @VoorbereidenOp = (select DateTimeConversieVoorWebServices(@VoorbereidenOp, @VoorbereidenOp));

      insert into tabProjectWerkbonKop (PwbkProjGid, PwbkVolgnummer, PwbkStatus, PwbkIsVoorraadGereserveerd, PwbkAangemaaktDoor, PwbkAangemaaktOp,
                                        PwbkOms, PwbkUitvoerenOp, PwbkVoorbereidenOp, PwbkOpm, PwbkExternID)
                               values (@ProjGid, @WerkbonVolgNummer, @PwbkStatus, @VoorraadGereserveerd, IsNull(@AangemaaktDoor, @@GebruikerCode), IsNull(@AangemaaktOp, Date(now())),
                                       @Omschrijving, @UitvoerenOp, @VoorbereidenOp, @Opmerking, @ExternId);
      set @PwbkGid = @@Identity;
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabProjectWerkbonKop', @PwbkGid, @IslockGelukt, 0, 'KingWebservice');
    else
      select PwbkGid, PwbkStatus into @PwbkGid, @OldPwbkStatus from tabProjectWerkbonKop where PwbkVolgnummer = @WerkbonVolgNummer;
      if (@PwbkGid is null) then
        call Raise(20626); //Ongeldige of geen WerkbonVolgNummer meegegeven!
      end if;

      if @OldPwbkStatus = 3 /* Afgehandeld */ then
        call Raise(20627); //Werkbon kan niet meer gewijzigd worden, omdat de status al op "Afgehandeld" staat!
      end if;

      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabProjectWerkbonKop', @PwbkGid, @IslockGelukt, 0, 'KingWebservice');
      if @IslockGelukt <> 0 then
        call Raise(20628); //Werkbon is in gebruik!
      else
        update tabProjectWerkbonKop set PwbkStatus = IsNull(@PwbkStatus, PwbkStatus), PwbkIsVoorraadGereserveerd = IsNull(@VoorraadGereserveerd, PwbkIsVoorraadGereserveerd),
                                        PwbkAangemaaktDoor = IsNull(@AangemaaktDoor, PwbkAangemaaktDoor),
                                        PwbkAangemaaktOp = (select DateTimeConversieVoorWebServices(@AangemaaktOp, PwbkAangemaaktOp)), PwbkOms = IsNull(@Omschrijving, PwbkOms),
                                        PwbkUitvoerenOp = (select DateTimeConversieVoorWebServices(@UitvoerenOp, PwbkUitvoerenOp)),
                                        PwbkVoorbereidenOp = (select DateTimeConversieVoorWebServices(@VoorbereidenOp, PwbkVoorbereidenOp)), PwbkOpm = IsNull(@Opmerking, PwbkOpm),
                                        PwbkExternID = IsNull(@ExternId, PwbkExternID)
        where PwbkGid = @PwbkGid;
      end if;
    end if;

    select PwbkVolgnummer as WerkbonVolgNummer from tabProjectWerkbonKop where PwbkGid = @PwbkGid;
  else
    call Raise(20900); //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Project_Werkbon_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Relatie_ContactRegistratie_Toevoegen(
  in @RelatieBestand nchar(3) default null,
  in @RelatieNummer nchar(10) default null,
  in @Gebruiker nchar(10),
  in @ContactSoortCode nchar(10),
  in @InvoerDatum date,
  in @InvoerTijd time,
  in @EindTijd time,
  in @ContactMet nchar(40),
  in @Notitie long nvarchar,
  in @OfferteNummer numeric(10,0))
begin
  declare @_FonGidRelatie integer;
  declare @_CosGid    integer;
  declare @_NawFilGid integer;
  declare @_OffGid    integer;

  //call TraceBegin('WebSvcProc_Debiteur_ContactRegistratie_Toevoegen > @Gebruiker = ' + @Gebruiker + ', @ContactSoortCode = ' + @ContactSoortCode);

  select FonGid
  into @_FonGidRelatie
  from tabFileOfNaw
  where FonId = @RelatieBestand;

  select NawFilGid
  into @_NawFilGid
  from tabNawFile
  where NawFilFonGid = @_FonGidRelatie
    and NawFilNummer = @RelatieNummer;

  if (@_NawFilGid is null) then
    call Raise(20720,'RelatieNummer'); // (20720) niet gevonden: %1!
  end if;

  if IsNull(@Gebruiker, '') = '' or (not exists(select 1 from tabGebruiker where NaamGebruiker = @Gebruiker)) then
    call Raise(20568); //Ongeldige of geen Gebruiker meegegeven!
  end if;

  select CosGid
  into @_CosGid
  from tabContactSoort
  where CosCode = @ContactSoortCode;

  if (@_CosGid is null) then
    call Raise(20569); //Ongeldige of geen ContactSoortCode meegegeven!
  end if;

  if @OfferteNummer is not null then
    select OffGid into @_OffGid from tabOfferte where OffOffertenummer = @OfferteNummer;
    if (@_OffGid is null) then
      call Raise(20570); //Ongeldige of geen OfferteNummer meegegeven!
    end if;
  end if;

  insert into tabGespreksNotitie(GnotGebruiker, GnotCosGid, GnotInvoerDatum, GnotInvoerTijd, GnotEindtijd, GnotNawFilGid, GnotNotitie, GnotGesprokenMet, GnotOffGid)
  select @Gebruiker, @_CosGid, DateTimeConversieVoorWebServices(@InvoerDatum, @InvoerDatum), @InvoerTijd, @EindTijd, @_NawFilGid, @Notitie, @ContactMet, @_OffGid;

  //call TraceEind('WebSvcProc_Debiteur_ContactRegistratie_Toevoegen');
end;


