create or replace procedure WebSvcProc_Relatie_Onderhoud_VrijeRubriek_ToevoegenWijzigen(
  in @RelatieBestand nchar(3) default null,
  in @Omschrijving nchar(40),
  in @Type nchar(15),   /* Geldige waardes: null (bij wijzigen), 'tekst', 'getal', 'datum', 'tijd', 'selectievakje', 'keuzelijst', 'email', 'website', 'bestand', 'telefoon'*/
  in @Hint nchar(80),
  in @Verplicht nchar(3), /* 'JA', 'NEE' */
  in @Uniek nchar(3), /* 'JA', 'NEE' */
  in @Lengte numeric(3,0),
  in @Decimalen numeric(1,0), /* >= 0 en <= 5 */
  in @Keuzelijst long varchar, //Delimited met CrLf (/0x0d/0x0a) OF '|'
  in @Defaultwaarde nchar(250), //Bevat default voor elk type veld!. Bij datum/tijd: nu/now levert datum/tijd van server
  in @DefaultDatum nchar(16), //Eigendatum, Verwerkingsdatum, Systeemdatum
  in @DefaultTijd nchar(11), //EigenTijd, SysteemTijd
  in @Sjabloon nchar(255), //Bevat sjabloon voor elk type dat een sjabloon kan hebben
  in @Groep nchar(40),
  in @OpVerkoopDocument nchar(3) /* 'JA', 'NEE' */
)
begin
  declare @_FonGidRelatie integer;

  //call trace('Begin WebSvcProc_Relatie_Onderhoud_VrijeRubriek_ToevoegenWijzigen')
  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  select FonGid
  into @_FonGidRelatie
  from tabFileOfNaw
  where FonId = @RelatieBestand;

  if (@_FonGidRelatie is null) then
    call Raise(20720,_U('Relatiebestand')); // (20720) niet gevonden: %1!
  end if;

  call WebSvcHulpProc_VrijeRubriek_ToevoegenWijzigen(
    'NAW', //@VrBestandOms
    @_FonGidRelatie, //@VrGroepID
    @_FonGidRelatie, //@VrSubGroepId
    @Omschrijving,
    @Type,
    @Hint,
    @Verplicht,
    @Uniek,
    @Lengte,
    @Decimalen,
    @Keuzelijst,
    @Defaultwaarde,
    @Sjabloon,
    @Groep,
    @DefaultDatum,
    @DefaultTijd,
    @OpVerkoopDocument
  );

  //call trace('Einde WebSvcProc_Relatie_Onderhoud_VrijeRubriek_ToevoegenWijzigen');
end;

