create or replace procedure WebSvcProc_Taak_Toevoegen(in @Gebruiker nchar(10), in @TaakSoort nchar(10), in @BeginDatum date, in @EindDatum date, in @Prioriteit nchar(12), in @Omschrijving nchar(80),
                                                      in @Opmerking long nvarchar, in @IngevoerdDoor nchar(10), in @IngevoerdOp datetime, in @Afgehandeld smallint, in @AfgehandeldDoor nchar(10),
                                                      in @AfgehandeldOp date, in @InBehandeling smallint, in @InBehandelingBij nchar(10), in @InBehandelingOp date, in @HeeftBetrekkingOpNaw smallint,
                                                      in @NawBestand nchar(3), in @NawNummer nchar(10), in @ContactPersoonNummer numeric(3,0))
begin
  declare @TsGid          integer;
  declare @TaakPrioriteit integer;
  declare @FonGid         integer;
  declare @NawFilGid      integer;
  declare @NawGid         integer;
  declare @RelGid         integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Taak_Toevoegen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Gebruiker = ' + @Gebruiker + ', @TaakSoort = ' + string(@TaakSoort));

  if IsModuleActive('we') <> 0 then

    if not exists(select 1 from tabGebruiker where NaamGebruiker = @Gebruiker) then
      call Raise(20568); //Ongeldige of geen Gebruiker meegegeven!
    end if;

    select TsGid into @TsGid from tabTaakSoort where TsCode = @TaakSoort;
    if (@TsGid is null) then
      call Raise(20646); //Ongeldige of geen Taaksoort meegegeven!;
    end if;

    if (@BeginDatum is null) then
      call Raise(20647); //Ongeldige of geen BeginDatum meegegeven!;
    end if;

    if (@EindDatum is null) then
      call Raise(20648); //Ongeldige of geen EindDatum meegegeven!;
    end if;

    if (@BeginDatum > @EindDatum) then
      call Raise(20649); //EindDatum mag niet voor de BeginDatum liggen!;
    end if;

    if IsNull(@Prioriteit, '') <> '' then
      case @Prioriteit
        when 'PRIO_GEEN'    then set @TaakPrioriteit = 0;
        when 'PRIO_LAAG'    then set @TaakPrioriteit = 1;
        when 'PRIO_NORMAAL' then set @TaakPrioriteit = 2;
        when 'PRIO_HOOG'    then set @TaakPrioriteit = 3;
        when 'PRIO_URGENT'  then set @TaakPrioriteit = 4;
        else call Raise(20650);  //Ongeldige of geen Prioriteit meegegeven
      end case;
    else
      set @TaakPrioriteit = 0;
    end if;

    if not exists(select 1 from tabGebruiker where NaamGebruiker = @IngevoerdDoor) then
      call Raise(20655); //Ongeldige of geen IngevoerdDoor meegegeven!
    end if;

    if (@Afgehandeld = 1) then
      if @AfgehandeldOp is null then
        call Raise(20652); //Ongeldige of geen AfgehandeldOp meegegeven!
      end if;
      if not exists(select 1 from tabGebruiker where NaamGebruiker = @AfgehandeldDoor) then
        call Raise(20651); //Ongeldige of geen AfgehandeldDoor meegegeven!
      end if;
    end if;

    if (@InBehandeling = 1) then
      if @InBehandelingOp is null then
        call Raise(20653); //Ongeldige of geen InBehandelingOp meegegeven!
      end if;
      if not exists(select 1 from tabGebruiker where NaamGebruiker = @InBehandelingBij) then
        call Raise(20654); //Ongeldige of geen InBehandelingBij meegegeven!
      end if;
    end if;

    if IsNull(@HeeftBetrekkingOpNaw, 0) not in (0,1) then
      call Raise(20658);  //Ongeldige of geen HeeftBetrekkingOpNaw meegegeven
    end if;

    if @HeeftBetrekkingOpNaw = 1 then
      select FonGid into @FonGid from tabFileOfNaw where FonId = @NawBestand;
      if @FonGid is null then
        call Raise(20656);  //Ongeldige of geen NawBestand meegegeven
      end if;

      select NawFilGid, NawFilNawGid into @NawFilGid, @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @NawNummer;
      if (@NawGid is null) then
        call Raise(20657);  //Ongeldige of geen NawNummer meegegeven
      end if;

      if @ContactPersoonNummer is not null then
        select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
        if (@RelGid is null) then
          call Raise(20555);  //Ongeldige of geen ContactPersoonNummer meegegeven
        end if;
      end if;
    end if;

    set @IngevoerdOp  = (select DateTimeConversieVoorWebServices(@IngevoerdOp, @IngevoerdOp));

    insert into tabTaak(TaakGebruiker, TaakTsGid, TaakUitvoerenBeginDatum, TaakUitvoerenEindDatum, TaakPrioriteit, TaakOmschrijving, TaakOpmerking, TaakAfgehandeld, TaakAfgehandeldDoor, TaakAfgehandeldOp,
                        TaakInBehandeling, TaakInBehandelingDoor, TaakInBehandelingOp, TaakIngevoerdDoor, TaakIngevoerdOp, TaakHeeftBetrekkingOpNaw, TaakNawFilGid, TaakRelGid)
    select @Gebruiker, @TsGid, @BeginDatum, @EindDatum, @TaakPrioriteit, @Omschrijving, @Opmerking, @Afgehandeld, @AfgehandeldDoor, @AfgehandeldOp,
                       @InBehandeling, @InBehandelingBij, @InBehandelingOp, @IngevoerdDoor, @IngevoerdOp, @HeeftBetrekkingOpNaw, @NawFilGid, @RelGid;

  else
    call Raise(20902); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Taak_Toevoegen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Taak_ToevoegenWijzigen(in @TaakNummer numeric(10,0), in @Gebruiker nchar(10), in @TaakSoort nchar(10), in @BeginDatum date, in @EindDatum date, in @Prioriteit nchar(12),
                                                              in @Omschrijving nchar(80), in @Opmerking long nvarchar, in @IngevoerdDoor nchar(10), in @IngevoerdOp datetime, in @Afgehandeld smallint,
                                                              in @AfgehandeldDoor nchar(10), in @AfgehandeldOp date, in @InBehandeling smallint, in @InBehandelingBij nchar(10), in @InBehandelingOp date,
                                                              in @HeeftBetrekkingOpNaw smallint, in @NawBestand nchar(3), in @NawNummer nchar(10), in @ContactPersoonNummer numeric(3,0))
result(TaakNummer numeric(10,0))
begin
  declare @TsGid          integer;
  declare @TaakPrioriteit integer;
  declare @FonGid         integer;
  declare @NawFilGid      integer;
  declare @NawGid         integer;
  declare @RelGid         integer;
  declare @TaakGid        integer;
  declare @LockResult     integer;
  declare @TaakWijzigen   smallint = 0; // 0 - Toevoegen (Default) / 1 = Wijzigen

  set @@ErrorTextProcedure = 'WebSvcProc_Taak_ToevoegenWijzigen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Gebruiker = ' + @Gebruiker + ', @TaakSoort = ' + string(@TaakSoort));

  if IsModuleActive('we') <> 0 then

    //Bepalen of taak gewijzigd moet worden
    if @TaakNummer is not null then
      set @TaakGid = (select TaakGid from tabTaak where TaakGid = @TaakNummer);
      if @TaakGid is null then
        call Raise(20686, 'TaakNummer'); // (20686) %1 niet gevonden!
      else
        set @TaakWijzigen = 1; //Taak bestaat, dus kan gewijzigd worden
      end if;
    end if;

    //Een deel van de controles geldt zowel bij Toevoegen als Wijzigen
    if (@TaakWijzigen = 0) or (@TaakWijzigen = 1 and nullif(@Gebruiker,'') is not null) then //Controle bij Toevoegen taak, of Wijzigen veld @Gebruiker
      if not exists(select 1 from tabGebruiker where NaamGebruiker = @Gebruiker) then
        call Raise(20568); //Ongeldige of geen Gebruiker meegegeven!
      end if;
    end if;

    if (@TaakWijzigen = 0) or (@TaakWijzigen = 1 and nullif(@TaakSoort,'') is not null) then //Controle bij Toevoegen taak, of Wijzigen veld @TaakSoort
      select TsGid into @TsGid from tabTaakSoort where TsCode = @TaakSoort;
      if (@TsGid is null) then
        call Raise(20646); //Ongeldige of geen Taaksoort meegegeven!;
      end if;
    end if;

    if (@TaakWijzigen = 0) or (@TaakWijzigen = 1 and nullif(@Prioriteit,'') is not null) then //Controle bij Toevoegen taak, of Wijzigen veld @Prioriteit
      if IsNull(@Prioriteit,'') <> '' then
        case @Prioriteit
          when 'PRIO_GEEN'    then set @TaakPrioriteit = 0;
          when 'PRIO_LAAG'    then set @TaakPrioriteit = 1;
          when 'PRIO_NORMAAL' then set @TaakPrioriteit = 2;
          when 'PRIO_HOOG'    then set @TaakPrioriteit = 3;
          when 'PRIO_URGENT'  then set @TaakPrioriteit = 4;
          else call Raise(20650);  //Ongeldige of geen Prioriteit meegegeven
        end case;
      else
        set @TaakPrioriteit = 0;
      end if;
    end if;

    if (@Afgehandeld = 1) then
      if @AfgehandeldOp is null then
        call Raise(20652); //Ongeldige of geen AfgehandeldOp meegegeven!
      end if;
      if not exists(select 1 from tabGebruiker where NaamGebruiker = @AfgehandeldDoor) then
        call Raise(20651); //Ongeldige of geen AfgehandeldDoor meegegeven!
      end if;
    end if;

    if (@InBehandeling = 1) then
      if @InBehandelingOp is null then
        call Raise(20653); //Ongeldige of geen InBehandelingOp meegegeven!
      end if;
      if not exists(select 1 from tabGebruiker where NaamGebruiker = @InBehandelingBij) then
        call Raise(20654); //Ongeldige of geen InBehandelingBij meegegeven!
      end if;
    end if;

    if IsNull(@HeeftBetrekkingOpNaw, 0) not in (0,1) then
      call Raise(20658);  //Ongeldige of geen HeeftBetrekkingOpNaw meegegeven
    end if;

    if @HeeftBetrekkingOpNaw = 1 then
      select FonGid into @FonGid from tabFileOfNaw where FonId = @NawBestand;
      if @FonGid is null then
        call Raise(20656);  //Ongeldige of geen NawBestand meegegeven
      end if;

      select NawFilGid, NawFilNawGid into @NawFilGid, @NawGid from tabNawFile where NawFilFonGid = @FonGid and NawFilNummer = @NawNummer;
      if (@NawGid is null) then
        call Raise(20657);  //Ongeldige of geen NawNummer meegegeven
      end if;

      if @ContactPersoonNummer is not null then
        select RelGid into @RelGid from tabRelatie where RelNawGid = @NawGid and RelNummer = @ContactPersoonNummer;
        if (@RelGid is null) then
          call Raise(20555);  //Ongeldige of geen ContactPersoonNummer meegegeven
        end if;
      end if;
    end if;

    if @TaakWijzigen = 0 then // Nieuwe taak

      //Datum/tijd conversie
      set @IngevoerdOp     = (select DateTimeConversieVoorWebServices(@IngevoerdOp, @IngevoerdOp));
      set @InBehandelingOp = (select DateTimeConversieVoorWebServices(@InBehandelingOp, @InBehandelingOp));
      set @AfgehandeldOp   = (select DateTimeConversieVoorWebServices(@AfgehandeldOp, @AfgehandeldOp));
      set @BeginDatum      = (select DateTimeConversieVoorWebServices(@BeginDatum, @BeginDatum));
      set @EindDatum       = (select DateTimeConversieVoorWebServices(@EindDatum, @EindDatum));

      if (@BeginDatum is null) then
        call Raise(20647); //Ongeldige of geen BeginDatum meegegeven!;
      end if;

      if (@EindDatum is null) then
        call Raise(20648); //Ongeldige of geen EindDatum meegegeven!;
      end if;

      if (@BeginDatum > @EindDatum) then
        call Raise(20649); //EindDatum mag niet voor de BeginDatum liggen!;
      end if;

      if not exists(select 1 from tabGebruiker where NaamGebruiker = @IngevoerdDoor) then
        call Raise(20655); //Ongeldige of geen IngevoerdDoor meegegeven!
      end if;

      //Als taak direct afgehandeld wordt zonder dat deze in behandeling is genomen, ook 'In behandeling' vullen. Anders wordt de taak niet afgehandeld.
      set @InBehandeling    = if (@Afgehandeld = 1 and IsNull(@InBehandeling,0) = 0) then @Afgehandeld else @InBehandeling end if;
      set @InBehandelingBij = if (@Afgehandeld = 1 and @InBehandelingBij is null) then @AfgehandeldDoor else @InBehandelingBij end if;
      set @InBehandelingOp  = if (@Afgehandeld = 1 and @InBehandelingOp is null) then @AfgehandeldOp else @InBehandelingOp end if;

      insert into tabTaak with auto name
      select @Gebruiker            as TaakGebruiker,
             @TsGid                as TaakTsGid,
             @BeginDatum           as TaakUitvoerenBeginDatum,
             @EindDatum            as TaakUitvoerenEindDatum,
             @TaakPrioriteit       as TaakPrioriteit,
             @Omschrijving         as TaakOmschrijving,
             @Opmerking            as TaakOpmerking,
             @Afgehandeld          as TaakAfgehandeld,
             @AfgehandeldDoor      as TaakAfgehandeldDoor,
             @AfgehandeldOp        as TaakAfgehandeldOp,
             @InBehandeling        as TaakInBehandeling,
             @InBehandelingBij     as TaakInBehandelingDoor,
             @InBehandelingOp      as TaakInBehandelingOp,
             @IngevoerdDoor        as TaakIngevoerdDoor,
             @IngevoerdOp          as TaakIngevoerdOp,
             @HeeftBetrekkingOpNaw as TaakHeeftBetrekkingOpNaw,
             @NawFilGid            as TaakNawFilGid,
             @RelGid               as TaakRelGid;

      set @TaakNummer = @@identity; //Vooralsnog is het TaakNummer het TaakGid

    else // Wijzigen bestaande taak

      if (@BeginDatum = '1899-01-01') then
        call Raise(20647); //Ongeldige of geen BeginDatum meegegeven!;
      end if;

      if (@EindDatum = '1899-01-01') then
        call Raise(20648); //Ongeldige of geen EindDatum meegegeven!;
      end if;

      if exists (select first 1 from tabTaak where TaakGid = @TaakGid and DateTimeConversieVoorWebServices(@BeginDatum, TaakUitvoerenBeginDatum) > DateTimeConversieVoorWebServices(@EindDatum, TaakUitvoerenEindDatum)) then
        call Raise(20649); //EindDatum mag niet voor de BeginDatum liggen!;
      end if;

      if (@IngevoerdDoor is not null) then
        call Raise(20655); //Ongeldige of geen IngevoerdDoor meegegeven!
      end if;

      //Lock plaatsen op de taak
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabTaak', @TaakGid, @LockResult);
      if @LockResult <> 0 then
        call Raise(20690, 'Taak'); // (20690) %1! is gelockt!
      end if;

      update tabTaak
      set    TaakGebruiker = IsNull(@Gebruiker, TaakGebruiker),
             TaakTsGid = IsNull(@TsGid, TaakTsGid),
             TaakUitvoerenBeginDatum = (select DateTimeConversieVoorWebServices(@BeginDatum, TaakUitvoerenBeginDatum)),
             TaakUitvoerenEindDatum = (select DateTimeConversieVoorWebServices(@EindDatum, TaakUitvoerenEindDatum)),
             TaakPrioriteit = IsNull(@TaakPrioriteit, TaakPrioriteit),
             TaakOmschrijving = IsNull(@Omschrijving, TaakOmschrijving),
             TaakOpmerking = IsNull(@Opmerking, TaakOpmerking),
             TaakAfgehandeld = IsNull(@Afgehandeld, TaakAfgehandeld),
             TaakAfgehandeldDoor = IsNull(@AfgehandeldDoor, TaakAfgehandeldDoor),
             TaakAfgehandeldOp = (select DateTimeConversieVoorWebServices(@AfgehandeldOp, TaakAfgehandeldOp)),
             //Als taak direct afgehandeld wordt zonder dat deze in behandeling is genomen, ook 'In behandeling' vullen. Anders wordt de taak niet afgehandeld.
             TaakInBehandeling = if (IsNull(@Afgehandeld, TaakAfgehandeld) = 1 and IsNull(@InBehandeling, TaakInBehandeling) = 0) then IsNull(@Afgehandeld, TaakAfgehandeld) else IsNull(@InBehandeling, TaakInBehandeling) end if,
             TaakInBehandelingDoor = if (IsNull(@Afgehandeld, TaakAfgehandeld) = 1 and NullIf(IsNull(@InBehandelingBij, TaakInBehandelingDoor),'') is null) then IsNull(@AfgehandeldDoor, TaakAfgehandeldDoor) else IsNull(@InBehandelingBij, TaakInBehandelingDoor) end if,
             TaakInBehandelingOp = if (IsNull(@Afgehandeld, TaakAfgehandeld) = 1 and (select DateTimeConversieVoorWebServices(@InBehandelingOp, TaakInBehandelingOp)) is null) then (select DateTimeConversieVoorWebServices(@AfgehandeldOp, TaakAfgehandeldOp)) else (select DateTimeConversieVoorWebServices(@InBehandelingOp, TaakInBehandelingOp)) end if,
             TaakHeeftBetrekkingOpNaw = IsNull(@HeeftBetrekkingOpNaw, TaakHeeftBetrekkingOpNaw),
             TaakNawFilGid = IsNull(@NawFilGid, TaakNawFilGid),
             TaakRelGid = IsNull(@RelGid, TaakRelGid)
      where TaakGid = @TaakGid;

      call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabTaak', @TaakGid); // Lock vrijgeven na wijzigen
    end if;

    select @TaakNummer as TaakNummer;
  else
    call Raise(20902); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_Taak_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_UitleverHistorie_Collo_Wijzigen(in @Uitlevernummer nchar(40), in @DirecteLevering smallint, in @OrderNummer numeric(10,0), in @Regelnummer numeric(3,0),
                                                                       in @TrackEnTraceCode nchar(40), in @TrackEnTraceUrl nchar(255))

begin
  declare @SoortBatch smallint;
  declare @FkGid      integer;
  declare @FrefGid    integer;
  declare @FclGid     integer;

  set @@ErrorTextProcedure = 'WebSvcProc_UitleverHistorie_Collo_Wijzigen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Uitlevernummer = ' + @Uitlevernummer + ', @OrderNummer = ' + string(@OrderNummer) + ', @Regelnummer = ' + string(@Regelnummer));

  if IsModuleActive('wo') <> 0 then
    case @DirecteLevering
      when 0 then set @SoortBatch = 30;
      when 1 then set @SoortBatch = 35;
      else call Raise(20664); //Ongeldige of geen DirecteLevering meegegeven!
    end case;

    select first FkGid into @FkGid from tabFactuurBatch inner join tabFactuurKop where fbSoortBatch = @SoortBatch and fkFactuurNummer = @Uitlevernummer and FkFactuurNummer_Lengte = length(@Uitlevernummer) order by FkGid desc;
    if @FkGid is null then
      call Raise(20665); //Ongeldige of geen Uitlevernummer meegegeven!
    end if;

    select FrefGid into @FrefGid from tabFactuurReferentie where frefFkGid = @FkGid and frefOrderNummer = @OrderNummer;
    if @FrefGid is null then
      call Raise(20519); //Ongeldige of geen OrderNummer meegegeven!
    end if;

    select FclGid into @FclGid from tabFactuurColli where FclfrefGid = @FrefGid and FclRegelNr = @Regelnummer;
    if @FclGid is null then
      call Raise(20520); //Ongeldige of geen Regelnummer meegegeven!
    end if;

    update tabFactuurColli set FclTrackTraceCode = Isnull(@TrackEnTraceCode, FclTrackTraceCode), FclTrackTraceUrl = Isnull(@TrackEnTraceUrl, FclTrackTraceUrl)
    where FclGid = @FclGid;

  else
    call Raise(20900) ; //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  set @@ErrorTextProcedure = 'WebSvcProc_UitleverHistorie_Collo_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


