create or replace procedure WebSvcProc_VrijeTabel_Item_ToevoegenWijzigen(
  in @TabelNummer  numeric(3,0),
  in @ItemCode     nchar(40),
  in @Omschrijving nchar(250),
  in @Opmerking    long nvarchar)
begin
  declare @VtbGid      integer;
  declare @VtbiGid     integer;

  //call TraceBegin('WebSvcProc_VrijeTabel_Item_ToevoegenWijzigen (' + string(VtbNummer) + ',' + @ItemCode + ',' + @Omschrijving + ',' + @Opmerking + ')');

  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;

  if IsModuleActive('ft') = 0 then
    call Raise(20904); //Optie Vrije Tabellen niet geactiveerd!
  end if;


  select VtbGid into @VtbGid from tabVrijeTabel where VtbNummer = @TabelNummer;
  if (@VtbGid is null) then
    call Raise(20675); //Ongeldige of geen TabelNummer meegegeven!
  else
    select VtbiGid into @VtbiGid from tabVrijeTabelItems where (VtbiVtbGid = @VtbGid) and (VtbiCode = @ItemCode);
    if @VtbiGid is null then
      insert into tabVrijeTabelItems(VtbiVtbGid, VtbiCode, VtbiOmschrijving, VtbiOpmerking)
      values (@VtbGid, @ItemCode, isnull(@Omschrijving, ''), isnull(@Opmerking, ''));
    else
      update tabVrijeTabelItems
      set    //VtbiVtbGid = @VtbGid,
             VtbiOmschrijving = IsNull(@Omschrijving, VtbiOmschrijving),
             VtbiOpmerking = IsNull(@Opmerking, VtbiOpmerking)
      where  VtbiGid = @VtbiGid;
    end if;
  end if;

  //call TraceEnd('WebSvcProc_VrijeTabel_Item_ToevoegenWijzigen');
end;

create or replace procedure WebSvcProc_VrijeTabel_Item_Verwijderen(in @TabelNummer numeric(3,0), in @ItemCode nchar(40))
begin
  declare @VtbGid      integer;
  declare @VtbiGid     integer;

  //call TraceBegin('WebSvcProc_VrijeTabel_Item_Verwijderen(' + string(VtbNummer) + ',' + @ItemCode + ')');

  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  else
    if IsModuleActive('ft') = 0 then
      call Raise(20904); //Optie Vrije Tabellen niet geactiveerd!
    else
      select VtbGid into @VtbGid from tabVrijeTabel where VtbNummer = @TabelNummer;
      if (@VtbGid is null) then
        call Raise(20675); //Ongeldige of geen TabelNummer meegegeven!
      else
        select VtbiGid into @VtbiGid from tabVrijeTabelItems where (VtbiVtbGid = @VtbGid) and (VtbiCode = @ItemCode);
        if (@VtbiGid is null) then
          call Raise(20676); //Ongeldige of geen ItemCode meegegeven!
        else
          call VrijeTabelItemVerwijderen(@TabelNummer, @ItemCode);
        end if;
      end if;
    end if;
  end if;

  //call TraceEnd('WebSvcProc_VrijeTabel_Item_Verwijderen');
end;




