create or replace procedure WebSvcProc_VrijeTabel_Onderhoud_ToevoegenWijzigen(in @TabelNummer numeric(3,0), in @Omschrijving nchar(250), in @Opmerking long varchar)
begin atomic
  declare @VtbGid          integer;
  declare @VtbTabelNummer  numeric(3,0);
  declare @VtbOmschrijving nchar(250);
  declare @VtbOpmerking    long nvarchar;

  set @@errortextprocedure = 'Begin WebSvcProc_VrijeTabel_Onderhoud_ToevoegenWijzigen';
  //call trace(@@errortextprocedure)
  // Ingangscontroles
  // Webservices NAW is verplicht
  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;
  // Optie voor Vrije tabellen is verplicht
  if IsModuleActive('ft') = 0 then
    call Raise(20904); //Optie Vrije Tabellen niet geactiveerd!
  end if;
  // Tabelnummer moet geldig zijn
  if @TabelNummer < 0 then
    call Raise(20675); //Ongeldige of geen TabelNummer meegegeven!
  end if;

  select VtbGid, VtbOmschrijving, VtbOpmerking into @VtbGid, @VtbOmschrijving, @VtbOpmerking from tabVrijeTabel where VtbNummer = @TabelNummer;

  set @VtbTabelNummer  = @TabelNummer;
  set @VtbOmschrijving = isnull(@Omschrijving, @VtbOmschrijving, '');
  set @VtbOpmerking    = isnull(@Opmerking, @VtbOpmerking, '');

  // VrijeTabel opzoeken, bestaat niet, dan toevoegen. Bestaat wel, dan updaten
  begin
    declare @VrTabelNaam nchar(20);

    set @VrTabelNaam = VrTabelnaam('VTB', @VtbTabelNummer, @VtbTabelNummer);

    if (@VtbGid is null) then
      //Nieuwe maken

      insert into tabVrijeTabel(VtbNummer, VtbOmschrijving, VtbOpmerking)
      values(@VtbTabelNummer, @VtbOmschrijving, @VtbOpmerking)
    else
      // Bestaande updaten, maar eerst locken!
      call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, @VrTabelNaam, '');

      update tabVrijeTabel
      set    VtbOmschrijving = if @Omschrijving is null then VtbOmschrijving else @Omschrijving endif,
             VtbOpmerking    = if @Opmerking    is null then VtbOpmerking    else @Opmerking    endif
      where  VtbGid = @VtbGid;

      call LockReleaseOnId(@@SpId,@@LoginTime, 1, @VrTabelNaam, '');
    end if;

  end;

  set @@errortextprocedure = 'Einde WebSvcProc_VrijeTabel_Onderhoud_ToevoegenWijzigen';
  //call trace(@@errortextprocedure);
end;


create or replace procedure WebSvcProc_VrijeTabel_Onderhoud_Verwijderen(in @TabelNummer numeric(3,0))
begin
  set @@errortextprocedure = 'Begin WebSvcProc_VrijeTabel_Onderhoud_Verwijderen';
  //call trace(@@errortextprocedure)
  // Ingangscontroles
  // Webservices NAW is verplicht
  if IsModuleActive('we') = 0 then
    call Raise(20901); //Optie ''Webservices NAW'' niet geactiveerd!
  end if;
  // Optie voor Vrije tabellen is verplicht
  if IsModuleActive('ft') = 0 then
    call Raise(20904); //Optie Vrije Tabellen niet geactiveerd!
  end if;
  // Tabelnummer moet geldig zijn
  if @TabelNummer < 0 then
    call Raise(20675); //Ongeldige of geen TabelNummer meegegeven!
  end if;

  // VrijeTabel opzoeken, bestaat niet, dan fout, anders locken en weggooien
  begin
    declare @VtbGid integer;
    declare @VrTabelNaam nchar(20);

    select VtbGid into @VtbGid from tabVrijeTabel where VtbNummer = @TabelNummer;
    // Als al verwijderd, dan hoeft dat dus niet meer
    //if @VtbGid is null then
    //  raiserror 20675; //Ongeldige of geen TabelNummer meegegeven!
    //end if;

    if @VtbGid is not null then
      set @VrTabelNaam = VrTabelnaam('VTB', @TabelNummer, @TabelNummer);
      call LockWaitAndSetForUniqueLock(@@SpId, @@LoginTime, @VrTabelNaam, '');

      // Tabel verwijderen
      delete tabvrijetabel where vtbgid = @vtbgid;

      call LockReleaseOnId(@@SpId,@@LoginTime, 1, @VrTabelNaam, '');
    end if;
  end;

  set @@errortextprocedure = 'Einde WebSvcProc_VrijeTabel_Onderhoud_Verwijderen';
  //call trace(@@errortextprocedure)

end;


