create or replace procedure WebSvcProc_VrijeTabel_Onderhoud_VrijeRubriek_ToevoegenWijzigen(
  in @TabelNummer numeric(3,0),
  in @Omschrijving nchar(40),
  in @Type nchar(15),
  in @Hint nchar(80),
  in @Verplicht smallint,
  in @Uniek smallint,
  in @Lengte numeric(3,0),
  in @Decimalen numeric(1,0), // >= 0, <= 5
  in @Keuzelijst long varchar, //Delimited met CrLf (/0x0d/0x0a) OF '|'
  in @Defaultwaarde nchar(250), //Bevat default voor elk type veld!. Bij datum/tijd: nu/now levert datum/tijd van server
  in @Sjabloon nchar(255), //Bevat sjabloon voor elk type dat een sjabloon kan hebben
  in @Groep nchar(40),
  in @DefaultDatum nchar(16), //Eigendatum, Verwerkingsdatum, Systeemdatum
  in @DefaultTijd nchar(11) //EigenTijd, SysteemTijd
)
begin
  declare @VtbGid integer;

  //call trace('Begin WebSvcProc_VrijeTabel_Onderhoud_VrijeRubriek_ToevoegenWijzigen')

  if IsModuleActive('ft') = 0 then
    call Raise(20904); //Optie Vrije Tabellen niet geactiveerd!
  end if;

  select VtbGid into @VtbGid from tabVrijeTabel where VtbNummer = @TabelNummer;

  if (@VtbGid is null) then
    call Raise(20675); //Ongeldige of geen TabelNummer meegegeven!
  end if;

  call WebSvcHulpProc_VrijeRubriek_ToevoegenWijzigen(
    'VTB', //@VrBestandOms
    @TabelNummer, //@VrGroepID
    @TabelNummer, //@VrSubGroepId
    @Omschrijving, //@Omschrijving
    @Type,
    @Hint,
    @Verplicht,
    @Uniek,
    @Lengte,
    @Decimalen,
    @Keuzelijst,
    @Defaultwaarde,
    @Sjabloon,
    @Groep,
    @DefaultDatum,
    @DefaultTijd,
    'NEE' // @OpVerkoopDocument
  );

  //call trace('Einde WebSvcProc_VrijeTabel_Onderhoud_VrijeRubriek_ToevoegenWijzigen');
end;


