create or replace procedure WebSvcHulpProc_BestellingExclusiefLocken(
  in @LockBstKopGid integer                   ,
  in @LockUserName  nchar(40)   default null  , // null - King 5 zoekt het zelf wel uit...
  in @SpId          integer     default null  , // idem
  in @LoginTime     datetime    default null    // idem
)
begin
  declare @_LockResult integer;

  // Defaults instellen
  if @LockUserName is null then
    set @LockUserName = 'KingWebservice';
  end if;
  if @SpId is null then
    set @SpId = @@SpId;
  end if;
  if @LoginTime is null then
    set @LoginTime = @@LoginTime;
  end if;

  if not exists(select first 1 from tabBestelKop where  BstKopGid = @LockBstKopGid ) then
    call Raise(20780, _U('In gebruik nemen'), _U('bestelling niet gevonden'));        // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if LockedById(@SpId, @LoginTime, 1 /*exclusieve lock*/, 'tabBestelKop', @LockBstKopGid) = 0  then
    // locken, met standaard King 5 procedure
    call LockSetOnId(
      @@Spid,
      @@LoginTime,
      1,                                // 1 = Exclusieve lock, 0 = ReadLock
      'tabBestelKop',                   // tabel waarin record te locken is - nchar(40)
      string(@LockBstKopGid),           // lockstring voor record, nchar(80)
      @_LockResult,                     // 0 = OK, anders fout
      0,                                // Automatisch opruimen: 0 = nee, 1 = ja
      @LockUserName
    );

    if @_LockResult <> 0 then
      call Raise(20741,_U('Bestelling'));    // (20741) %1 is in gebruik!
    end if;
  end if;
end;



create or replace procedure WebSvcHulpProc_Bestelling_BestelRegel_ToevoegenTussenvoegen
(
  in @BestelNummer                    numeric(10,0) ,
  in @RegelSoort                      nchar(5)      ,   // vaste waarden: ART, TAR, TEKST
  in @RegelNummer                     integer       ,
  in @Actie                           smallint      ,   //0 = Toevoegen, 1 = Tussenvoegen (met opschuiven), 2 = Wijzigen
  in @ArtikelNummer                   nchar(20)     ,
  in @AantalBesteld                   numeric(15,3) ,
  // hieronder de optionele velden
  in @InkoopEenheid                   nchar(21)     ,
  in @VoorraadEenhedenInInkoopEenheid numeric(13,3) ,
  in @ArtikelNummerLeverancier        nchar(20)     ,
  in @EanCode                         nchar(30)     ,
  in @PartijNummer                    nchar(20)     ,
  in @Omschrijving                    long nvarchar ,
  in @InkoopprijsPer                  nchar(16)     ,   // vaste waarden: INKOOPEENHEID, of VOORRAADEENHEDEN
  in @InkoopPrijs                     numeric(15,3) ,
  in @Kortingspercentage              numeric(5,2)  ,
  in @Kortingsbedrag                  numeric(15,3) ,
  in @BtwCode                         numeric(3,0)  ,
  in @OntvangstDatum                  date          ,
  in @Opmerking                       long nvarchar ,
  in @StandaardSpecificatieRegel      nchar(4)          // vaste waarden: JA, NEE
)
result (
  BestelNummer      numeric(10,0) ,
  BestelRegelNummer numeric(3,0)
)
begin
  declare @_BstKopIsVerwerkt                        smallint;
  declare @_BstRglBstKopGid                         integer;
  declare @_BstRglNummer                            integer;
  declare @_BstRglActie                             smallint;
  declare @_BstRglGid                               integer;
  declare @_BstRglSoort                             smallint;
  declare @_BstRglArtGid                            integer;
  declare @_BstRglArtPartijGid                      integer;
  declare @_BstRglAantalBesteld                     numeric(15,3);
  declare @_BstRglAantalNogTeOntvangenInVoorrEenh   numeric(15,3);
  declare @_BstRglAantalOntvangenInVoorrEenh        numeric(15,3);
  declare @_BstRglAfleverDatum                      date;
  declare @_BstRglBtwCode                           integer;
  declare @_BstRglArtikelNummerLeverancier          nchar(20);
  declare @_BstRglEANcode                           nchar(30);
  declare @_BstRglInkoopEenheid                     nchar(20);
  declare @_BstRglVoorraadEenhedenInInkoopEenheid   numeric(15,3);
  declare @_BstRglKortingSoort                      smallint;
  declare @_BstRglKortingPercentage                 numeric(5,2);
  declare @_BstRglKortingBedrag                     numeric(15,3);
  declare @_BstRglOms                               long nvarchar;
  declare @_BstRglOpm                               long nvarchar;
  declare @_BstRglPrijs                             numeric(15,3);
  declare @_BstRglPrijsPer                          numeric(15,3);
  declare @_BstRglPrijsPerSoort                     smallint;
  declare @_BstRglTotaalAantalSpecRegelsKomtOvereen smallint;
  declare @_ArtPartijNummer                         nchar(20);
  declare @_BstRglHeeftMagazijnOntvangstRegel       smallint;
  declare @_SpecificatieregelAanmaken smallint = 0;

  declare @_InkoopEenheidChanged                    smallInt = 0;
  declare @_OrgInkoopEenheid                        nchar(20);

  // Constanten
  declare _ACTIE_TOEVOEGEN    smallint = 0;
  declare _ACTIE_TUSSENVOEGEN smallint = 1;
  declare _ACTIE_WIJZIGEN     smallint = 2;

  //Initialisatie
  set @_BstRglAantalOntvangenInVoorrEenh  = null;
  set @_BstRglOpm = null;
  set @_BstRglAfleverDatum = null;
  set @_BstRglTotaalAantalSpecRegelsKomtOvereen = 0;  // een bestelregelregel wordt eerst gemaakt, een detailregel is er dan nog niet.

  // ********************
  // Controle verplichte velden
  // ********************

  // Controle actie
  if (@Actie is not null) then
    if @Actie not in (_ACTIE_TOEVOEGEN, _ACTIE_TUSSENVOEGEN, _ACTIE_WIJZIGEN) then
      call Raise(20700, _U('Actie, waarde: null, 0, 1, 2 toegestaan')); // Ongeldige waarde: %1
    end if;

    set @_BstRglActie = @Actie;
  end if;

  // Bestaat de opgegeven bestelling, en is die niet al verwerkt?
  set @_BstRglBstKopGid = null;
  select BstKopGid,           BstKopIsVerwerkt
    into @_BstRglBstKopGid ,  @_BstKopIsVerwerkt
  from tabBestelKop
  where BstKopNummer = @BestelNummer;

  if (@_BstRglBstKopGid is null ) then
    call Raise(20720,    'BestelNummer');        // (20720) niet gevonden: %1!
  end if;

  if @_BstKopIsVerwerkt = 1 and @_BstRglActie <> _ACTIE_WIJZIGEN then
    call Raise(20780 , _U('Bestelregel toevoegen/wijzigen'),_U('bestelling is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // Controle op RegelNummer
  if (@RegelNummer is not null) then
    // RegelNummer, is deze minimaal 1 en maximaal 999
    if (@RegelNummer not between 1 and 999) then
      call Raise(20700, _U('%1! moet tussen %2! en %3! liggen!', 'RegelNummer', '1', '999')); // Ongeldige waarde: %1
    end if;
    set @_BstRglNummer = @RegelNummer;

    if @_BstRglActie = _ACTIE_WIJZIGEN then
      select first BstRglGid into @_BstRglGid from tabBestelregel where BstRglBstKopGid = @_BstRglBstKopGid and BstRglNummer = @_BstRglNummer;
      if @_BstRglGid is null then
        call Raise(20720,    'Regelnummer');        // (20720) niet gevonden: %1!
      end if;
    end if;
  else
    if @_BstRglActie = _ACTIE_WIJZIGEN then
      call Raise(20700, _U('Bij wijzigen moet het %1! worden meegegeven.', 'RegelNummer')); // Ongeldige waarde: %1
    end if;

  end if;

  // --- Bij wijzigen de gehele regel ophalen
  if @_BstRglActie = _ACTIE_WIJZIGEN then
    select
      BstRglBstKopGid,
      BstRglNummer,
      BstRglSoort,
      BstRglArtGid,
      BstRglArtPartijGid,
      BstRglAantalBesteld,
      BstRglAantalNogTeOntvangenInVoorrEenh,
      BstRglAantalOntvangenInVoorrEenh,
      BstRglAfleverDatum,
      BstRglBtwCode,
      BstRglArtikelNummerLeverancier,
      BstRglEANcode,
      BstRglInkoopEenheid,
      BstRglVoorraadEenhedenInInkoopEenheid,
      BstRglKortingSoort,
      BstRglKortingPercentage,
      BstRglKortingBedrag,
      BstRglOms,
      BstRglOpm,
      BstRglPrijs,
      BstRglPrijsPer,
      BstRglPrijsPerSoort,
      BstRglTotaalAantalSpecRegelsKomtOvereen,
      ArtPartijNummer,
      if exists(select first 1 from tabmagazijnontvangsten where magontbstrglgid = bstrglgid) then 1 else 0 endif
    into
      @_BstRglBstKopGid,
      @_BstRglNummer,
      @_BstRglSoort,
      @_BstRglArtGid,
      @_BstRglArtPartijGid,
      @_BstRglAantalBesteld,
      @_BstRglAantalNogTeOntvangenInVoorrEenh,
      @_BstRglAantalOntvangenInVoorrEenh,
      @_BstRglAfleverDatum,
      @_BstRglBtwCode,
      @_BstRglArtikelNummerLeverancier,
      @_BstRglEANcode,
      @_BstRglInkoopEenheid,
      @_BstRglVoorraadEenhedenInInkoopEenheid,
      @_BstRglKortingSoort,
      @_BstRglKortingPercentage,
      @_BstRglKortingBedrag,
      @_BstRglOms,
      @_BstRglOpm,
      @_BstRglPrijs,
      @_BstRglPrijsPer,
      @_BstRglPrijsPerSoort,
      @_BstRglTotaalAantalSpecRegelsKomtOvereen,
      @_ArtPartijNummer,
      @_BstRglHeeftMagazijnOntvangstRegel
    from tabBestelRegel
         left outer join tabArtikelPartij on ArtPartijGid = BstRglArtPartijGid
    where BstRglGid = @_BstRglGid;

    Set @_OrgInkoopEenheid = @_BstRglInkoopEenheid;

    // deze gegevens mogen niet worden gewijzigd in een verwerkte bestelling, dus als ze zijn doorgegeven en wijken af, dan melden
    if @_BstKopIsVerwerkt = 1 or @_BstRglHeeftMagazijnOntvangstRegel = 1 then
      begin
        // Deze mogen niet meer na verwerken, gewoon overschrijven met de omschrijving vanuit de regel
        declare @msg nchar(200);
        if @_BstKopIsVerwerkt = 1 then
          set @msg = _U('bestelling is al verwerkt');
        else
          set @msg = _U('er is een magazijnontvangst voor deze regel aangemaakt')
        end if;

        if isnull(@AantalBesteld, @_BstRglAantalBesteld) <> @_BstRglAantalBesteld then call Raise(20780 , _U('Wijzigen aantal besteld'),@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if isnull(@InkoopEenheid, @_BstRglInkoopEenheid) <> @_BstRglInkoopEenheid then call Raise(20780 , _U('Wijzigen inkoopeenheid') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if isnull(@VoorraadEenhedenInInkoopEenheid, @_BstRglVoorraadEenhedenInInkoopEenheid) <> @_BstRglVoorraadEenhedenInInkoopEenheid then call Raise(20780 , _U('Wijzigen voorraadeenheden in inkoopeenheid') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if isnull(@ArtikelNummerLeverancier, @_BstRglArtikelNummerLeverancier) <> @_BstRglArtikelNummerLeverancier then call Raise(20780 , _U('Wijzigen artikelnummer leverancier') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if isnull(@EanCode, @_BstRglEANcode) <> @_BstRglEANcode then call Raise(20780 , _U('Wijzigen EAN-code artikel') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if isnull(@PartijNummer, @_ArtPartijNummer) <> @_ArtPartijNummer then call Raise(20780 , _U('Wijzigen partijnummer') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if (case @InkoopprijsPer when 'INKOOPEENHEID' then 0 when 'VOORRAADEENHEDEN' then 1 else @_BstRglPrijsPerSoort end) <> @_BstRglPrijsPerSoort then raiserror 20780 , _U('Wijzigen kortingsoort') ,@msg; end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if isnull(@InkoopPrijs, @_BstRglPrijs) <> @_BstRglPrijs then call Raise(20780 , _U('Wijzigen inkoopprijs') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if isnull(@BtwCode, @_BstRglBtwCode) <> @_BstRglBtwCode then call Raise(20780 , _U('Wijzigen BTW-code') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        if isnull(@Omschrijving, @_BstRglOms) <> @_BstRglOms then call Raise(20780 , _U('Wijzigen omschrijving') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.

	if @_BstRglKortingSoort = 0 /*bedrag*/ then
          if (@Kortingspercentage is not null) then call Raise(20780 , _U('Wijzigen kortingsbedrag naar kortingspercentage') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        else
          if (@Kortingsbedrag is not null) then call Raise(20780 , _U('Wijzigen kortingspercentage naar kortingsbedrag'),@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
        end if;

        if @_BstRglKortingSoort = 0 /*bedrag*/ then
          if isnull(@Kortingsbedrag, @_BstRglKortingBedrag) <> @_BstRglKortingBedrag then call Raise(20780 , _U('Wijzigen kortingsbedrag') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
          set @Kortingspercentage = null;
        else
          if isnull(@Kortingspercentage, @_BstRglKortingPercentage) <> @_BstRglKortingPercentage then call Raise(20780 , _U('Wijzigen kortingspercentage') ,@msg); end if;// <Actie> niet mogelijk. Reden: <Reden>.
          set @Kortingsbedrag = null;
        end if;
      end;
    end if;


    set @AantalBesteld = isnull(@AantalBesteld, @_BstRglAantalBesteld);
    //set @InkoopEenheid = isnull(@InkoopEenheid, @_BstRglInkoopEenheid);
    set @VoorraadEenhedenInInkoopEenheid = isnull(@VoorraadEenhedenInInkoopEenheid, @_BstRglVoorraadEenhedenInInkoopEenheid);
    set @ArtikelNummerLeverancier = isnull(@ArtikelNummerLeverancier, @_BstRglArtikelNummerLeverancier);
    //set @EanCode = isnull(@EanCode, @_BstRglEANcode);
    set @PartijNummer = isnull(@PartijNummer, @_ArtPartijNummer);
    set @Omschrijving = isnull(@Omschrijving, @_BstRglOms);
    set @InkoopprijsPer = isnull(@InkoopprijsPer, if @_BstRglPrijsPerSoort = 0 then 'INKOOPEENHEID' else 'VOORRAADEENHEDEN' endif);
    set @InkoopPrijs    = isnull(@InkoopPrijs, @_BstRglPrijs);
    set @_BstRglKortingSoort = if @Kortingspercentage is not null then 1 /*percentage*/ else if @Kortingsbedrag is not null then 0 /*bedrag*/ else @_BstRglKortingSoort endif endif;
    if @_BstRglKortingSoort = 0 /*bedrag*/ then
      set @Kortingsbedrag     = isnull(@Kortingsbedrag, @_BstRglKortingBedrag);
    else
      set @Kortingspercentage = isnull(@Kortingspercentage, @_BstRglKortingPercentage);
    end if;
    set @OntvangstDatum = isnull(@OntvangstDatum, @_BstRglAfleverDatum);
    set @Opmerking = isnull(@Opmerking, @_BstRglOpm);
  end if;


  // ArtikelNummer: soort , aantal besteld, partij
  begin
    declare @ArtAantDecAantallen    smallint;
    declare @ArtIsPartijRegistreren smallint;
    declare @ArtIsGeblokkeerdInkoop smallint;
    declare @_PartijNummer          nchar(20);

    // Velden die bij wijzigen regel niet gewijzigd mogen worden hier controleren en vullen
    if @_BstRglActie <> _ACTIE_WIJZIGEN then
      // Artikelsoort
      select  case trim(isnull(@RegelSoort, ''))
                when 'ART'  then 2 /*artikel*/
                when 'TAR'  then 1 /*Tarief*/
                when 'TEKST'then 0 /*Tekst*/
                else null
              end case
        into  @_BstRglSoort
      from dummy;

      if ( @_BstRglSoort is null ) then
        call Raise(20700, 'RegelSoort'); // Ongeldige waarde: %1
      end if;

    end if;

    if @_BstRglActie <> _ACTIE_WIJZIGEN or @_BstRglSoort = 0 /*tekst*/ then
      begin
        declare @IsGevonden smallint;
        // Tekstblok mag nog wel worden gewijzigd, artikel/tarief alleen bij toevoegen
        // Bestaat Artikelnummer bij Artikelsoort...
        select  first ArtGid,         ArtAantDecAantallen,  ArtIsGeblokkeerdInkoop,   ArtIsPartijRegistreren, 1
          into        @_BstRglArtGid, @ArtAantDecAantallen, @ArtIsGeblokkeerdInkoop,  @ArtIsPartijRegistreren, @IsGevonden
        from tabArtikel
        where ArtCode = trim(@ArtikelNummer)
          and ArtSoort = @_BstRglSoort;

        // Bij een tekstblok moet een opgegeven artikelnummer bestaan.
        if @IsGevonden is null then
          if ( @_BstRglSoort <> 0 /*tekst*/) or ( isnull(trim(@ArtikelNummer), '') <> '' ) then
            call Raise(20700, 'ArtikelNummer'); // Ongeldige waarde: %1
          end if;
        end if;
      end;
    end if;

    // Aantal
    if ( @_BstRglSoort <> 0 /*tekst*/) then            // 0 = tekst, 1 = tarief, 2 = artikel
      // Aantal besteld
      if (isnull(@AantalBesteld, 0) = 0 ) then
        call Raise(20700, 'AantalBesteld'); // Ongeldige waarde: %1
      end if;
    end if;

    // Partijen registratie van artikel
    if @_BstKopIsVerwerkt = 0 or @_BstRglActie <> _ACTIE_WIJZIGEN then
      set @_PartijNummer = trim(isnull(@PartijNummer, @_PartijNummer, ''));
      if ( @_PartijNummer <> '' ) then
        if ( @ArtIsPartijRegistreren = 0 ) then
          call Raise(20700, _U('%1!, artikel is niet partijregistrerend', 'PartijNummer')); // Ongeldige waarde: %1
        end if;

        set @_BstRglArtPartijGid= ( select first ArtPartijGid from tabArtikelPartij where ArtPartijArtGid = @_BstRglArtGid and ArtPartijNummer = @_PartijNummer );
        if @_BstRglArtPartijGid is null then
          call Raise(20720,  'PartijNummer') ; // (20720) %1 niet gevonden!
        end if;
      end if;
    end if;

  end; // ArtikelNummer: soort , aantal besteld, partij


  // ******************************
  // Controle overige velden
  // ******************************

  // BTW code
  if @_BstRglActie <> _ACTIE_WIJZIGEN then
    // Opzoeken op volgorde: 1. leverancier (indien 0%), 2 artikel, 3 anders leeg.
    set @_BstRglBtwCode = isnull( @_BstRglBtwCode,
                                  ( select NawFilBtwCode from tabNawFile inner join tabBtw on BtwCode = NawFilBtwCode where BtwPercentage = 0 and NawFilNawGid = ( select BstKopNawGid from tabBestelKop where BstKopGid = @_BstRglBstKopGid ) ),
                                  ( select ArtBtwCodeinkoop from tabArtikel where ArtGid = @_BstRglArtGid ) );
  end if; // BTW Code
  if ( @BtwCode is not null ) then
    if not exists( select BtwCode from tabBtw where BtwCode = @BtwCode ) then
      call Raise(20700, 'BtwCode'); // Ongeldige waarde: %1
    end if;
    set @_BstRglBtwCode = @BtwCode;
  end if;


  // Wijzigen van specificatieregel
  select  case isnull(@StandaardSpecificatieRegel, '')
            when ''     then 1
            when 'JA'   then 1
            when 'NEE'  then 0
            else null // oeps, een foute waarde?
          end case
    into  @_SpecificatieregelAanmaken
  from dummy;

  if @_SpecificatieregelAanmaken is null then
    call Raise(20700, 'StandaardSpecificatieRegel'); // (20700) Ongeldige waarde: %1
  end if;


  // Inkoopeenheid, EAN Code, Omschrijving en bijbehorende Inkoopprijs
  begin
    declare @BstKopNawGid       integer;
    declare @BstKopValNummer    integer;
    declare @BstKopBestelDatum  integer;
    declare @_OrigBstRglAantalBesteld numeric(15,3) = @_BstRglAantalBesteld;

    select BstKopNawGid,  BstKopValNummer,  BstKopBestelDatum
    into   @BstKopNawGid, @BstKopValNummer, @BstKopBestelDatum
    from tabBestelKop
    where BstKopGid = @_BstRglBstKopGid;

    begin
      declare @_GevondenInkoopEenheid nchar(20);
      declare @_GevondenEANcode nchar(30);

      //In wijzigen mode hoef je niet op de eancode te checken als deze niet gewijzigd is.
      if isnull(@EanCode, '') <> '' and @_BstRglSoort <> 2 /*Artikel*/ then
        call Raise(20700, 'EAN-code'); // (20700) Ongeldige waarde: %1
      end if;

      //Als er iets is gewijzigd of je bent aan het toevoegen
      if (@_BstRglActie <> _ACTIE_WIJZIGEN) or
      (isnull(@Inkoopeenheid, @_BstRglInkoopEenheid) <> @_BstRglInkoopEenheid) or ((isnull(@EanCode, @_BstRglEANcode) <> @_BstRglEANcode)) then
        call WebSvcHulpProc_Inkopen_ValideerArtEanCodeInkoopeenheid(
          @EANcode,               // De te valideren EAN code indien opgegeven
          @_BstRglArtGid,
          @Inkoopeenheid,
          @BstKopNawGid,          // Leverancier waar de inkoopeenheid bij hoort
          @_GevondenInkoopEenheid,  // Kan eventueel wijzigen a.g.v. EAN-code
          @_GevondenEANcode,        // EAN code bekend of niet
          null                    // Gid van EAN Code, gebruiken we hier niet.
        );

        if isnull(@Inkoopeenheid, '') = '' then
          // Geen inkoopeenheid meegegeven, dan die van de EAN, indien gevonden
          if @_GevondenInkoopEenheid <> '' then
            set @_BstRglInkoopEenheid = @_GevondenInkoopEenheid;
          end if;
        else
          set @_BstRglInkoopEenheid = @Inkoopeenheid;
        end if;

        if isnull(@EanCode, '') = '' then
          set @_BstRglEANcode = @_GevondenEANcode;
        else
          set @_BstRglEANcode = @EanCode;
        end if;
      end if;

      // Eerst maar de inkoopeenheid controleren, en dan de opgegeven EAN
      call WebSvcHulpProc_Inkopen_ValideerInkoopeenheid_Regel(
        /*in*/
        @_BstRglSoort                               ,       // 0=tekstblok, 1=tarief, 2=artikel
        @_BstRglArtGid                              ,
        @ArtikelnummerLeverancier                   ,
        @AantalBesteld                              ,       // aantal inkoopeenheden dat is besteld
        @VoorraadEenhedenInInkoopEenheid            ,
        @_BstRglInkoopEenheid                       ,
        @BstKopNawGid                               ,       // Leverancier
        /*out*/
        @_BstRglInkoopEenheid                       ,
        @_BstRglVoorraadEenhedenInInkoopEenheid     ,
        null                                        ,       // @_AldAantalKanVerschillen, // 0=nee, 1= mag afwijken
        @_GevondenEANcode                             ,
        @_BstRglArtikelNummerLeverancier            ,
        @_BstRglOms                                 ,       // omschrijving/tekst bij de inkoopeenheid van de leverancier
        @_BstRglAantalBesteld                       ,
        @_BstRglAantalNogTeOntvangenInVoorrEenh     ,       // Hoeveel voorraadeenheden krijg je voor de inkoopeenheden
        @_BstRglAantalOntvangenInVoorrEenh                  // Wat is de correctie (als die er is)?
      );

      //Er is een EANcode opgegeven, dan die gebruiken
      //zoniet dan degene van de inkoopeenheid
      if (isnull(@EanCode, '') <> '') then
        set @_BstRglEANcode = @EanCode;
      else
        if (isNull(@Inkoopeenheid, @_BstRglInkoopEenheid ) <> @_BstRglInkoopEenheid) then
          set @_BstRglEANcode = @_GevondenEANcode;
        end if;
      end if;
    end;

    // Validatie Omschrijving bij inkoopeenheid artikel
    // Geen omschrijving meegegeven of het betreft een artikel, dan de tekst berekenen
    // en  zo niet, dan moeten we dat elders opzoeken.
    call WebSvcHulpProc_ValideerArtikelOmschrijvingBestelRegel(
      /*in*/
      @_BstRglSoort,
      @_BstRglArtGid,        // inout, zodat deze leeg gemaakt kan worden als blijkt dat het een tekstregel met omschrijving betreft
      @_BstRglArtPartijGid,
      @BstKopNawGid,
      @Omschrijving,
      /*inout*/
      @_BstRglOms   // dit is omschrijving bij de al gevalideerde inkoopeenheid
    );

    // Nu nog (voor inkoopeenheid) inkoopprijs bepalen
//    if @_BstRglActie <> _ACTIE_WIJZIGEN then
      call  WebSvcHulpProc_Inkopen_ValideerInkoopprijs_Regel(
        /*in*/
        @_BstRglArtGid,
        @_BstRglArtPartijGid,
        @_BstRglInkoopEenheid,
        @_BstRglVoorraadEenhedenInInkoopEenheid,  // Aantal
        @BstKopNawGid,
        @BstKopValNummer,
        @_BstRglAantalNogTeOntvangenInVoorrEenh,  // Aantal voorraadeenheden bij aantal besteld.
        @BstKopBestelDatum,
        @Inkoopprijs,
        @InkoopprijsPer,                          // 'INKOOPEENHEID' of 'VOORRAADEENHEDEN'
        @Kortingsbedrag,
        @Kortingspercentage,
        /*out*/
        @_BstRglPrijs,
        @_BstRglPrijsPer,
        @_BstRglPrijsPerSoort,                    // 0 = inkoopeenheid, 1 = voorraadeenheden
        @_BstRglKortingSoort,                     // 1 = percentage, 0 = bedrag
        @_BstRglKortingbedrag,
        @_BstRglKortingPercentage
      );
//    end if;


    // Bij wijzigen alleen de detailregels aanpassen als er maar 1 is.
    if @_BstRglActie = _ACTIE_WIJZIGEN then
      if @_BstRglAantalBesteld <> @_OrigBstRglAantalBesteld and @_SpecificatieregelAanmaken = 1 then
        // Als meer dan 1 besteldetailregel, dan niks aanpassen
        if (select count(1) from tabBestelRegelDetail where BrdBstRglGid = @_BstRglGid) <> 1 then
          set @_SpecificatieregelAanmaken = 0; // Doe het zelf maar!
        end if;
        set @_BstRglTotaalAantalSpecRegelsKomtOvereen = 0; // Komen niet meer overeen
      else
        set @_SpecificatieregelAanmaken = 0; // Aantal niet gewijzigd, dus geen spec.regels maken
      end if;

      if @_BstRglAantalBesteld = @_OrigBstRglAantalBesteld then
        set @_BstRglAantalNogTeOntvangenInVoorrEenh = null;
        set @_BstRglAantalOntvangenInVoorrEenh = null;
      end if;
    end if;

  end;

  // Afleverdatum
  begin
    //Mag gewoon in het verleden liggen
    //// opgegeven afLeverdatum hoort wel na besteldatum en in ieder geval vandaag of later te zijn.
    // Stel nu de afleverdatum vast. Bij wijzigen is het al snel goed, nodige controles staan hierboven, verder is het prima zo
    if @_BstRglActie = _ACTIE_WIJZIGEN then
      set @_BstRglAfleverDatum = @OntvangstDatum;
    else
      call WebSvcHulpProc_ValideerAfleverDatumBestelregel( /*in*/ @_BstRglArtGid, @_BstRglBstKopGid, @InkoopEenheid, @OntvangstDatum, /*out*/ @_BstRglAfleverDatum);
    end if;
  end; // Afleverdatum

  // Opmerking
  set @_BstRglOpm = isnull(trim(@Opmerking), @_BstRglOpm);

  // ********************
  // Regel toevoegen
  // ********************

  // voorbereiding specificatieregel, deze ook aanmaken/wijzigen of niet
  begin
    declare @BrdGid                     integer;

    // er is (nog) geen specificatieregel bij de bestelregel,
    // deze regel moet er nog wel bij voor een artikel bij toevoegen, tussenvoegen en wijzigen als de aantallen wijzigen
    if (@_BstRglActie <> _ACTIE_WIJZIGEN) or (@_SpecificatieregelAanmaken = 1) then
      select case @_BstRglSoort
               when 2 then 0  // 2 = artikel
               else 1         // anders: tarief, tekstblok, ...
             end
        into @_BstRglTotaalAantalSpecRegelsKomtOvereen
      from dummy;
    end if;

    begin atomic
      // Bestelling eerst locken. Lukt dat niet: abort
      call WebSvcHulpProc_BestellingExclusiefLocken(@_BstRglBstKopGid);

      if (@_BstRglNummer is not null) then
        // Komt regelnummer al voor? Dan tussenvoegen!
        if exists (select first 1 from tabBestelRegel where BstRglBstKopGid = @_BstRglBstKopGid and BstRglNummer = @_BstRglNummer) then

          // Waneer regelnummer al bestaat, en RegelTussenvoegen = 1, worden de bestaande regel(s) opgeschoven met +1
          // Bij regels 1,2,3,6,7,8 wordt bij tussenvoegen van regelnummer 2, alleen de regelnummers 2 en 3 doorgeschoven. Resultaat is dan: 1,2(nieuw), 3, 4, 6, 7, 8
          // ACW Omslachtige routine om het eerstvolgende niet-bestaande regelnummer te vinden
          case
            when isnull(@_BstRglActie,0) = _ACTIE_TUSSENVOEGEN then
            begin
              declare @totregel integer;

              // Eerstvolgende niet-bestaande regelnummer NA @regelnummer opzoeken
              select first row_num
              into   @totregel
              from sa_rowgenerator(@_BstRglNummer, 1000)
              where not exists(select first 1 from tabbestelregel where BstRglBstKopGid = @_BstRglBstKopGid and BstRglNummer = row_num)
              order by row_num;

              update tabBestelRegel
              set    BstRglNummer = BstRglNummer + 1 // Regelnummer 1 positie doorschuiven
              where  BstRglBstKopGid = @_BstRglBstKopGid
                     and BstRglNummer between @_BstRglNummer and @totregel
              order by BstRglNummer asc;
            end;

            when isnull(@_BstRglActie,0) = _ACTIE_TOEVOEGEN then
              call Raise(20780, _U('Bestelregel toevoegen'), _U('%1! komt al voor', 'RegelNummer'));  // <Actie> niet mogelijk. Reden: <Reden>.
          end case;

        end if;
      end if;

      // regelnummer bepalen en met 1 verhogen
      if (@_BstRglNummer is null) then
        Set @_BstRglNummer = isnull( (select max(BstRglNummer) from tabBestelRegel where BstRglBstKopGid = @_BstRglBstKopGid), 0) + 1;
        if (@_BstRglNummer > 999) then
          call Raise(20780, _U('Toevoegen'), _U('bestelling heeft al maximaal 999 regels') ); // <Actie> niet mogelijk. Reden: <Reden>.
        end if;
      end if;

      // We gaan nu Bestelregel aanmaken of wijzigen
      if @_BstRglActie = _ACTIE_WIJZIGEN then
        // Wijzigen

        //RB 60219 Kijk of inkoopeenheid is gewijzigd, zo ja, dan BstRglPrijsPer aanpassen anders gelijk houden.
        If (@_OrgInkoopEenheid <> @_BstRglInkoopEenheid) then
          set @_InkoopEenheidChanged = 1;
        end if;

        update tabBestelRegel
          set BstRglArtGid                            = if @_BstRglSoort = 0 /*tekst*/ then @_BstRglArtGid else BstRglArtGid endif,
              BstRglArtPartijGid                      = isnull(@_BstRglArtPartijGid                      , BstRglArtPartijGid                      ),
              BstRglAantalBesteld                     = isnull(@_BstRglAantalBesteld                     , BstRglAantalBesteld                     ),
              BstRglAantalNogTeOntvangenInVoorrEenh   = isnull(@_BstRglAantalNogTeOntvangenInVoorrEenh   , BstRglAantalNogTeOntvangenInVoorrEenh   ),
              BstRglAantalOntvangenInVoorrEenh        = isnull(@_BstRglAantalOntvangenInVoorrEenh        , BstRglAantalOntvangenInVoorrEenh        ),
              BstRglAfleverDatum                      = isnull(@_BstRglAfleverDatum                      , BstRglAfleverDatum                      ),
              BstRglBtwCode                           = isnull(@_BstRglBtwCode                           , BstRglBtwCode                           ),
              BstRglArtikelNummerLeverancier          = isnull(@_BstRglArtikelNummerLeverancier          , BstRglArtikelNummerLeverancier          ),
              BstRglEANcode                           = isnull(@_BstRglEANcode                           , BstRglEANcode                           ),
              BstRglInkoopEenheid                     = isnull(@_BstRglInkoopEenheid                     , BstRglInkoopEenheid                     ),
              BstRglVoorraadEenhedenInInkoopEenheid   = isnull(@_BstRglVoorraadEenhedenInInkoopEenheid   , BstRglVoorraadEenhedenInInkoopEenheid   ),
              BstRglKortingSoort                      = isnull(@_BstRglKortingSoort                      , BstRglKortingSoort                      ),
              BstRglKortingPercentage                 = isnull(@_BstRglKortingPercentage                 , BstRglKortingPercentage                 ),
              BstRglKortingBedrag                     = isnull(@_BstRglKortingBedrag                     , BstRglKortingBedrag                     ),
              BstRglOms                               = isnull(@_BstRglOms                               , BstRglOms                               ),
              BstRglOpm                               = isnull(@_BstRglOpm                               , BstRglOpm                               ),
              BstRglPrijs                             = isnull(@_BstRglPrijs                             , BstRglPrijs                             ),
              BstRglPrijsPer                          = (if @_InkoopEenheidChanged = 1
                                                           then isnull(@_BstRglPrijsPer, BstRglPrijsPer)
                                                           else BstRglPrijsPer
                                                         endif),  //RB 60219
              BstRglPrijsPerSoort                     = isnull(@_BstRglPrijsPerSoort                     , BstRglPrijsPerSoort                     ),
              BstRglTotaalAantalSpecRegelsKomtOvereen = isnull(@_BstRglTotaalAantalSpecRegelsKomtOvereen , BstRglTotaalAantalSpecRegelsKomtOvereen )
        where BstRglGid = @_BstRglGid;
      else
        // Tussen- of toevoegen
        insert tabBestelRegel
          ( BstRglBstKopGid
          , BstRglNummer
          , BstRglSoort
          , BstRglArtGid
          , BstRglArtPartijGid
          , BstRglAantalBesteld
          , BstRglAantalNogTeOntvangenInVoorrEenh
          , BstRglAantalOntvangenInVoorrEenh
          , BstRglAfleverDatum
          , BstRglBtwCode
          , BstRglArtikelNummerLeverancier
          , BstRglEANcode
          , BstRglInkoopEenheid
          , BstRglVoorraadEenhedenInInkoopEenheid
          , BstRglKortingSoort
          , BstRglKortingPercentage
          , BstRglKortingBedrag
          , BstRglOms
          , BstRglOpm
          , BstRglPrijs
          , BstRglPrijsPer
          , BstRglPrijsPerSoort
          , BstRglTotaalAantalSpecRegelsKomtOvereen
          )
        values
          ( @_BstRglBstKopGid
          , @_BstRglNummer
          , @_BstRglSoort
          , @_BstRglArtGid
          , @_BstRglArtPartijGid
          , @_BstRglAantalBesteld
          , @_BstRglAantalNogTeOntvangenInVoorrEenh
          , @_BstRglAantalOntvangenInVoorrEenh
          , @_BstRglAfleverDatum
          , @_BstRglBtwCode
          , @_BstRglArtikelNummerLeverancier
          , @_BstRglEANcode
          , @_BstRglInkoopEenheid
          , @_BstRglVoorraadEenhedenInInkoopEenheid
          , @_BstRglKortingSoort
          , @_BstRglKortingPercentage
          , @_BstRglKortingBedrag
          , @_BstRglOms
          , @_BstRglOpm
          , @_BstRglPrijs
          , @_BstRglPrijsPer
          , @_BstRglPrijsPerSoort
          , @_BstRglTotaalAantalSpecRegelsKomtOvereen
          );
        set @_BstRglGid = @@Identity;
      end if;
    end;  //atomic

    // Er is nog geen webservice/API voor specificatieregel.
    // We maken er in het geval van een artikel meteen eentje (en enige) aan als erom gevraagd wordt
    // LET OP: de aanroep van stored proc is buiten de atomic van hierboven,
    //         omdat deze "volgens boekje" een eigen atomic en lock mechanisme heeft
    if ( @_BstRglTotaalAantalSpecRegelsKomtOvereen = 0 ) and ( @_SpecificatieregelAanmaken = 1 ) then
      begin
        declare @OrderNummer numeric(10,0);
        declare @OrrNummer   numeric(5,0);
        declare @DetailRegelSoort nchar(12);

        if @_BstRglActie = _ACTIE_WIJZIGEN then
          // Wijzigen, dan de regel gewoon verwijderen en nogmaals aanmaken omdat de aantallen toch niet kloppen
          select BrdOrkNummer, BrdOrrRegelNr, if BrdSoort = 0 /*magazijn*/ then 'MAGAZIJN' else 'VERKOOPORDER' endif
          into   @OrderNummer, @OrrNummer, @DetailRegelSoort
          from tabBestelRegelDetail
          where BrdBstRglGid = @_BstRglGid;
          delete tabBestelRegelDetail where BrdBstRglGid = @_BstRglGid;
        end if;

        set @BrdGid = ( select  SpecificatieRegelID
                        from    WebSvcProc_Bestelling_BestelRegel_SpecificatieRegel_Toevoegen(
                                  @BestelNummer,
                                  @_BstRglNummer,
                                  @DetailRegelSoort,     // @RegelSoort
                                  @OrderNummer,          // @OrderNummer
                                  @OrrNummer,            // @OrderRegelNummer
                                  @_BstRglAantalNogTeOntvangenInVoorrEenh + isNull(@_BstRglAantalOntvangenInVoorrEenh,0), // Aantal Besteld in bestelregel is inkoopeenheid, moet hier voorraadeenheid zijn!
                                  @_BstRglAantalNogTeOntvangenInVoorrEenh
                                )
                      );

        if @BrdGid is null then
          call Raise(20761 , _U('er is iets fout gegaan met de specificatieregel bij de bestelregel nummer %1!', string(@_BstRglNummer))); // (20761) Ongeldige status: <Opmerking>
        end if;

        // Nu nog in de bestelregel aangeven dat er een specificatieregel is.
        update tabBestelRegel
          set BstRglTotaalAantalSpecRegelsKomtOvereen = 1
        where BstRglGid = @_BstRglGid ;

      end;
    end if; // Specificatieregel
  end;

  // Resultaat
  select  @BestelNummer as BestelNummer, (select BstRglNummer
                                          from tabBestelRegel
                                          where BstRglGid = @_BstRglGid ) as BestelRegelNummer
  from dummy;

end;


create or replace procedure WebSvcHulpProc_Bestelling_LockVrijgeven(
  in @BestelNummer numeric(10,0),
  in @LockBstKopGid integer                   ,
  in @LockUserName  nchar(40)   default null  , // null - King 5 zoekt het zelf wel uit...
  in @SpId          integer     default null  , // idem
  in @LoginTime     datetime    default null    // idem
)
begin
  // *********************** Beschrijving ****************************
  // * Vrijgeven van een lock, zonder erop te letten of de bestelling
  // * (nog) wel bestaat.
  // * Dat is nu gedaan omdat de lock ook vrijgegeven moet kunnen
  // * worden als de bestelling net is verwijderd
  // *****************************************************************

  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabBestelKop';

  // Defaults instellen
  if @LockUserName is null then
    set @LockUserName = 'KingWebservice';
  end if;
  if @SpId is null then
    set @SpId = @@SpId;
  end if;
  if @LoginTime is null then
    set @LoginTime = @@LoginTime;
  end if;

  begin // lock vrijgeven
    call LockReleaseOnId( @Spid, @LoginTime, 1, _QLOCKTABLENAME, @LockBstKopGid);

    // gelockt, maar niet door KingWebService? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = _QLOCKTABLENAME and qLockPKey = String(@LockBstKopGid) and qLockUser <> @LockUserName) then
      call Raise(20741, _U('Bestelling %1!' , string(@BestelNummer))) ;              // (20741) %1! is in gebruik!
    end if;

    // De record zou dus wel door KingWebService gelockt zijn, deze opruimen.
    call LockReleaseOnUserName(@LockUserName, 1, _QLOCKTABLENAME, @LockBstKopGid);
  end; // lock vrijgeven

end;



create or replace procedure WebSvcHulpProc_Bestelling_ValideerInkoper(
  in  @BstKopNawGid   integer       ,
  in  @InkoperNummer  numeric(3,0)  ,
  out @_RelGidInkoper  integer
)
begin
  declare @_VgbDefInkoperVerplicht  smallint;
  declare @_VgbDefInkoper           smallint;
  declare @GebruikersNaam  nchar(40) ='Webservice'; // Default
  declare @GebruikersNaam2 nchar(40) ='KingWebser%'; // Default, i.v.m. max. 10 posities, via Like

  select  VgbDefInkoperVerplicht,   VgbDefInkoper
    into  @_VgbDefInkoperVerplicht, @_VgbDefInkoper
  from  tabVasteGegevensBestellingen;

  if ( @InkoperNummer is null ) then
    // Geen inkopernummer, dus o.b.v. instelling bepalen
    case @_VgbDefInkoper
      when 2 /*Volgens leverancier*/ then
        set @_RelGidInkoper = (select LevGegRelGidInkoper from tabLeverancierGegevens where LevGegNawGid = @BstKopNawGid);
      when 1 /*Volgens gebruiker*/ then
        set @_RelGidInkoper = ( select first REL.RelGid
                                from tabRelatie                 REL
                                  inner join tabRelatieFunctie  FN      on FN.FnRelGid = REL.RelGid
                                  inner join tabFunctieContact  CON     on CON.FnCode = FN.RelFnCode
                                  inner join tabNaw             NAW     on NAW.NawGid = RelNawGid
                                  inner join tabNawFile         NAWFIL  on NAWFIL.NawFilNawGid = NAW.NawGid and NawFilFonId = 'B'
                                  inner join tabGebruiker       GEBR    on GEBR.GebrRelGid = REL.RelGid
                                where (GEBR.NaamGebruiker = @GebruikersNaam or GEBR.NaamGebruiker like @GebruikersNaam2)
                                  and (CON.OmsFunctie like '%Inkoop%' or CON.OmsFunctie like '%Inkoper%') // Zoek inkoopterm in omschrijving
                                order by FN.IsBelangrijkste desc );                                       // voorkeur eerst
    end case;

  else

    // Inkopernummer opgegeven
    set @_RelGidInkoper = ( select REL.RelGid
                            from tabRelatie                 REL
                              inner join tabNaw             NAW     on NAW.NawGid = RelNawGid
                              inner join tabNawFile         NAWFIL  on NAWFIL.NawFilNawGid = NAW.NawGid and NawFilFonId = 'B'
                            where REL.RelNummer = @InkoperNummer );

    if ( @_RelGidInkoper is null ) then
      call Raise(20720, 'InkoperNummer') ; // %1 niet gevonden!
    end if;
  end if;

  // Een verplichte inkoper is niet bekend...
  if ( @_VgbDefInkoperVerplicht <> 0 ) and ( @_RelGidInkoper is null ) then
    call Raise(20780, _U('Toevoegen'), _U('%1! is niet opgegeven, dit is verplicht', 'InkoperNummer')); // <Actie> niet mogelijk: <Reden>.
  end if;

end;



create or replace procedure WebSvcHulpProc_Inkopen_ValideerArtEanCodeInkoopeenheid(
  in @EanCode nchar(30),         // De te valideren EAN code indien opgegeven
  in @ArtGid integer,
  in @Inkoopeenheid nchar(20),   // De te valideren inkoopeenheid indien opgegeven
  in @ArtLevNawGid integer,      // Leverancier waar de inkoopeenheid bij hoort
  out @_Inkoopeenheid nchar(20), // o.b.v. EAN wellicht aanpassen
  out @_ArtEanCode nchar(30),    // de gevalideerde EAN code
  out @_ArtEanGid integer
)
begin
  set @_ArtEanCode = nullif(trim(@EanCode),'');

  // (1) Begin met EAN code te vinden bij inkoopeenheid
  // EAN code bij inkoopeenheid nemen we over,
  // en anders nemen we de ingevulde EAN code
  begin
    declare @AldInkoopeenheid      nchar(20);
    declare @AldGid                integer;
    declare @AldArtEanGid          integer;

    set @AldInkoopeenheid = nullif(trim(@Inkoopeenheid), '');

    //IE leeg, EAN gevuld                   -> Zoek IE o.b.v. EAN
    //IE gevuld of o.b.v. EAN niet gevonden -> Gebruik IE
    //IE leeg, EAN leeg                     -> Gebruik defaultIEbijLev
    if @AldInkoopeenheid is null and @_ArtEanCode is not null then
      // Inkoopeenheid is leeg, EAN is opgegeven, dan IE o.b.v. EAN opzoeken
      select first  ALD.AldArtEanGid, ALDEAN.ArtEanCode,  AldGid, ALD.AldInkoopEenheid
        into        @AldArtEanGid,    @_ArtEanCode,       @AldGid, @AldInkoopeenheid
      from tabArtikelLeverancierDetail    ALD
      inner join tabArtikelLeverancier  ARTLEV  on ARTLEV.ArtLevGid = ALD.AldArtLevGid
      inner join tabArtikelEan          ALDEAN  on ALDEAN.ArtEanGid = ALD.AldArtEanGid
      where ( ARTLEV.ArtLevArtGid = @ArtGid )
        and ( ARTLEV.ArtLevNawGid = @ArtLevNawGid )
        and ( ALDEAN.ArtEanCode = @_ArtEanCode)             // EAN opgegeven maar geen inkoopeenheid, dan die EAN opzoeken
      order by ALD.AldIsDefaultInkoopEenheidBijLev desc;    // Dan liefst EAN code bij default inkoopeenheid bekijken.
    end if;

//    if @AldInkoopeenheid is not null or @_ArtEanCode is null then
    if @_ArtEanCode is null then
      //EAN is leeg -> Zoek EAN o.b.v. inkoopeenheid of default IE bij leverancier
      select first  ALD.AldArtEanGid, ALDEAN.ArtEanCode,  AldGid
        into        @AldArtEanGid,    @_ArtEanCode,       @AldGid
      from tabArtikelLeverancierDetail    ALD
      inner join tabArtikelLeverancier  ARTLEV  on ARTLEV.ArtLevGid = ALD.AldArtLevGid
      inner join tabArtikelEan          ALDEAN  on ALDEAN.ArtEanGid = ALD.AldArtEanGid
      where ( ARTLEV.ArtLevArtGid = @ArtGid )
        and ( ARTLEV.ArtLevNawGid = @ArtLevNawGid )
        and ( (ALD.AldInkoopEenheid = @AldInkoopeenheid ) or ( @AldInkoopeenheid is null ) ) // Geen inkoopeenheid opgegeven?
      order by ALD.AldIsDefaultInkoopEenheidBijLev desc;                                     // Dan EAN code bij default inkoopeenheid bekijken.
    end if;

    set @_Inkoopeenheid = isnull(@AldInkoopeenheid, '');

    // Als er bij inkoopeenheid een EAN code is, dan gebruiken we die.
    // anders blijven we de bij de opgegeven EAN code.
    select @AldArtEanGid into @_ArtEanGid from dummy where @AldArtEanGid is not null;
    // is er helemaal geen inkoopeenheid, dan negeren we de opgegeven EAN code
//    select null into @_ArtEanGid where @AldGid is null;
  end; // EAN code inkoopeenheid

  //Voorraadeenheid Artikel bekijken als er bij inkoopeenheid niets gevonden is.
  if @_ArtEanGid is null then
    select first  ArtEanGid,   ArtEanCode
      into        @_ArtEanGid, @_ArtEanCode
    from tabArtikelEan
    inner join tabVerkoopEenheid on VkeArtEanGid = ArtEanGid
    where VkeArtGid = @ArtGid
      and VkeIsVoorraadEenheid = 1;
  end if; // voorraadeenheid artikel

  //Default EAN code Artikel bekijken, als er bij voorraadeenheid geen EAN code bekend is.
  if @_ArtEanGid is null then
    select ArtEanGid,   ArtEanCode
      into @_ArtEanGid, @_ArtEanCode
    from tabArtikelEan
    where ArtEanArtGid = @ArtGid
      and ArtEanIsDefault = 1;
  end if; // voorraadeenheid artikel
end;


create or replace procedure WebSvcHulpProc_Inkopen_ValideerInkoopeenheid_Regel(
  in    @ArtSoort                                       smallint      ,       // 0=tekstblok, 1=tarief, 2=artikel
  in    @ArtGid                                         integer       ,
  in    @ArtikelnummerLeverancier                       nchar(20)     ,
  in    @AantalInkoopeenheden                           numeric(15,3) ,
  in    @AantalVoorraadEenhedenInInkoopEenheid          numeric(15,3) ,
  in    @Inkoopeenheid                                  nchar(20)     ,
  in    @NawGid                                         integer       ,        // Leverancier
  out   @_AldInkoopeenheid                              nchar(20)     ,
  out   @_AldAantalVoorraadEenhedenInInkoopEenheid      numeric(15,3) ,
  out   @_AldAantalKanVerschillen                       smallint      ,       // 0=nee, 1= mag afwijken, 2=facturering/levering mag afwijken
  out   @_AldArtEanCode                                 nchar(30)     ,
  out   @_AldArtCodeBijLeverancier                      nchar(20)     ,
  out   @_AldOmsBijLeverancier                          long nvarchar ,
  out   @_AantalInkoopeenheden                          numeric(15,3) ,       // Tbv bestelling / ontvangst: hoeveel inkoopeenheden zijn het precies?
  out   @_AantalTeOntvangenInVoorraadEenheid            numeric(15,3) ,       // Tbv bestelling / ontvangst: hoeveel voorraadeenheden krijg je voor de inkoopeenheden
  out   @_AantalCorrectieInVoorraadEenheid              numeric(15,3)         // Wat is Correctie (als die van toepassing is)
)
begin
  declare @FilterInkoopeenheid    nchar(20);
  declare @ArtAantDecAantallen    smallint;

  if @ArtSoort not in (0 /*Tekst*/, 1 /*tarief*/, 2 /*Artikel*/) then
    call Raise(20700,'Soort artikel'); // (20700) Ongeldige waarde: %1!
  end if;

  // Initialisatie
  set @FilterInkoopeenheid = trim(isnull(@Inkoopeenheid, ''));

  case @ArtSoort
    when 1 /*Tarief*/ then
      begin
        declare @ArtIsAantallen smallint;

        select ArtAantDecAantallen,   ArtAantallen
          into @ArtAantDecAantallen,  @ArtIsAantallen
        from tabArtikel
        where ArtGid = @ArtGid;

        //Tarief kan met vinkje aangeven dat aantal moet worden opgegeven. Is dat ook gedaan?
        if (@ArtIsAantallen = 1) and ( isnull(@AantalInkoopeenheden, 0) = 0 ) then
          call Raise(20700, 'Aantal. Voor tarief is dit verplicht.');  //
        end if;

        set @_AldAantalKanVerschillen = 0;
        if (isnull(@AantalVoorraadEenhedenInInkoopEenheid,0) not in (0, 1) ) then
          // Boeien, 1 is ook goed...
          call Raise(20701, 'VoorraadEenhedenInInkoopEenheid is niet met tarief te gebruiken.'); // (20701) Ongeldige combinatie: <Opmerking>
        end if;

        set @_AldAantalVoorraadEenhedenInInkoopEenheid = 1;                                             // Tarief kent alleen voorraadeenheid

        set @_AantalInkoopeenheden = round(isnull(@AantalInkoopeenheden, 1), @ArtAantDecAantallen);              // Niets opgegeven? dan minimaal 1
        if (@ArtAantDecAantallen = 0 and @_AantalInkoopeenheden= 0 ) then set @_AantalInkoopeenheden = 1 end if; // bij 0 decimalen naar 0 afgerond, dan 1 maken.
        set @_AantalTeOntvangenInVoorraadEenheid = @_AantalInkoopeenheden;
        set @_AantalCorrectieInVoorraadEenheid = null;
      end;
    when 2 /*Artikel*/ then
      begin
        declare @ArtMutatieInkoopBijhouden  smallint;
        declare @_AldBestelGrootte          numeric(15,3);
        declare @_AldMinimumAfname          numeric(15,3);

        // we zoeken eerst voorraadeenheid bij artikel op, die is er altijd.
        // Daar staat ook of inkoopgegevens apart worden bijgehouden.

        // Eerst maar de defaults bij Artikel...
        select  ART.ArtAantDecAantallen
        ,       ART.artOmsEenheid
        ,       ART.ArtMutatieInkoopBijhouden
        ,       1   // aantal voorraadeenheden gelijk aan aantal in inkoopeenheid
        ,       0   // geen afwijking in aantal voorraadeenheden per inkoopeenheid
        ,       1   // kleinste minimale voorraadeenheid
        ,       1   // en in stapjes van 1 voorraadeenheid.
          into  @ArtAantDecAantallen
          ,     @_AldInkoopeenheid
          ,     @ArtMutatieInkoopBijhouden
          ,     @_AldAantalVoorraadEenhedenInInkoopEenheid
          ,     @_AldAantalKanVerschillen
          ,     @_AldMinimumAfname
          ,     @_AldBestelGrootte
        from tabArtikel ART
        where Artgid = @ArtGid;

        // Artikel zonder inkoopgegevens: bestaat de opgegeven inkoopeenheid?
        if (@ArtMutatieInkoopBijhouden = 0) and (@FilterInkoopeenheid <> '' ) and ( @FilterInkoopeenheid <> @_AldInkoopEenheid ) then
            call Raise(20720,  'InkoopEenheid') ; // (20720) %1 niet gevonden!
        end if;

        // Inkoopeenheden worden bijgehouden bij het artikel,
        // haal inkoopeenheid op bij leverancier...
        if (@ArtMutatieInkoopBijhouden = 1) then
          select  ALD.AldAantalKanVerschillen,
                  ALD.AldInkoopEenheid,
                  ALD.AldVoorraadEenhedenInInkoopEenheid,
                  EAN.ArtEanCode,
                  ALD.AldArtCodeBijLeverancier,
                  ALD.AldOmsBijLeverancier,
                  ALD.AldMinimumAfname,
                  ALD.AldBestelGrootte
            into  @_AldAantalKanVerschillen,
                  @_AldInkoopEenheid,
                  @_AldAantalVoorraadEenhedenInInkoopEenheid,
                  @_AldArtEanCode,
                  @_AldArtCodeBijLeverancier,
                  @_AldOmsBijLeverancier,
                  @_AldMinimumAfname,
                  @_AldBestelGrootte
          from    tabArtikelLeverancierDetail ALD
            inner join tabArtikelLeverancier  ARTLEV  on ARTLEV.ArtlevGid = ALD.AldArtLevGid
            left join  tabArtikelEan          EAN     on EAN.ArtEanGid = ALD.AldArtEanGid
          where ARTLEV.ArtLevArtGid = @ArtGid
            and ARTLEV.ArtLevNawGid = @NawGid
            and ( ( @FilterInkoopeenheid =  ''  and ALD.AldIsDefaultInkoopEenheidBijLev = 1 )  // default inkoopeenheid, of ...
                  or ( ALD.AldInkoopEenheid = @FilterInkoopeenheid ) );                        // de opgegeven inkoopeenheid

          // Is bij leverancier van artikel de opgegeven inkoopeenheid gevonden?
          if (@FilterInkoopeenheid <> '' ) and ( @FilterInkoopeenheid <> @_AldInkoopEenheid ) then
            call Raise(20720,  'InkoopEenheid') ; // (20720) %1 niet gevonden!
          end if;


          // Er is is een artikelnummer opgegeven? Deze overnemen...
          set @_AldArtCodeBijLeverancier =  isnull(nullif(trim(@ArtikelnummerLeverancier),''), @_AldArtCodeBijLeverancier);

        end if; // ArtMutatieInkoopBijhouden = 1

        // Nu de definitieve aantallen vaststellen voor artikel...
        // We gaan niet met minimum afname en bestelgrootte werken,
        // de gebruiker kan in King ook kiezen voor "Doorgaan"
        begin
          declare @AantalVoorraadEenhedenAfgerond numeric(15,3);
          declare @AantalInkoopeenhedenAfgerond   numeric(15,3);

          // King GUI rekent met waarden met aantal decimalen zoals bij artikel ingesteld.
          // Dan wel afronden doen, alleen als er een waarde is opgegeven.
          select  round(@AantalVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen)
            into  @AantalVoorraadEenhedenAfgerond
          from dummy
          where isnull(@AantalVoorraadEenhedenInInkoopEenheid, 0) <> 0;
          select  round(@AantalInkoopeenheden, @ArtAantDecAantallen)
            into  @AantalInkoopeenhedenAfgerond
          from dummy
          where isnull(@AantalInkoopeenheden, 0) <> 0;

          // Mag niet afwijken, en de opgegeven waarde wijkt wel af van wat er bij inkoopeenheid staat...
          if ( @_AldAantalKanVerschillen = 0 ) and ( isnull(@AantalVoorraadEenhedenAfgerond, @_AldAantalVoorraadEenhedenInInkoopEenheid) <> @_AldAantalVoorraadEenhedenInInkoopEenheid) then
            call Raise(20701, 'VoorraadEenhedenInInkoopEenheid mag niet afwijken bij het artikel.'); // (20701) Ongeldige combinatie: <Opmerking>
          end if;

          // wat zijn nu de definitieve voorraadeenheden per inkoopeenheid.
          // Als het aantal voorraaadenheden mag afwijken, en er is een waarde opgegeven, neem die dan over.
          select isnull( @AantalVoorraadEenhedenAfgerond, @_AldAantalVoorraadEenhedenInInkoopEenheid )
            into @_AldAantalVoorraadEenhedenInInkoopEenheid
          from dummy
          where @_AldAantalKanVerschillen = 1;

          // Als er geen aantal inkoopeemheden is opgegeven, neem dan de minimum afname over, en anders is het 1...
          // Als het aantal decimalen meer is dan het artikel aangeeft, dan eerst aantal inkoopeenheden afronden.
          set @_AantalInkoopeenheden = coalesce(@AantalInkoopeenhedenAfgerond, @_AldMinimumAfname, 1);
          if (@ArtAantDecAantallen = 0 and @_AantalInkoopeenheden = 0 ) then set @_AantalInkoopeenheden = 1 end if;  // bij 0 decimalen naar 0 afgerond, dan 1 maken.

          set @_AantalTeOntvangenInVoorraadEenheid = round(@_AantalInkoopeenheden * @_AldAantalVoorraadEenhedenInInkoopEenheid, @ArtAantDecAantallen);
          set @_AantalCorrectieInVoorraadEenheid = null;
        end;
      end; // artikelen
  end case;

end;



create or replace procedure WebSvcHulpProc_Inkopen_ValideerInkoopprijs_Regel(
  in    @ArtGid                                 integer       ,
  in    @ArtPartijGid                           integer       ,
  in    @Inkoopeenheid                          nchar(20)     ,
  in    @VoorraadeenhedenInkoopeenheid          numeric(15,3) ,
  in    @ArtLevNawGid                           integer       ,
  in    @ValutaNummer                           integer       ,
  in    @AantalOntvangen                        numeric(15,3) ,
  in    @PeilDatum                              date          ,  // Peildatum: kan besteldatum, ontvangstdatum of factuurdatum zijn...
  in    @ValidatieInkoopprijs                   numeric(15,3) ,
  in    @ValidatieInkoopprijsPer                nchar(16)     ,   // 'INKOOPEENHEID' of 'VOORRAADEENHEDEN'
  in    @ValidatieKortingBedrag                 numeric(15,3) ,
  in    @ValidatieKortingPercentage             numeric(15,2) ,
  out   @_ivirInkoopprijs                       numeric(15,3) ,
  out   @_ivirInkoopprijsPer                    numeric(15,3) ,
  out   @_ivirPrijsPerSoort                     smallint      ,
  out   @_ivirKortingSoort                      smallint      ,
  out   @_ivirKortingBedrag                     numeric(15,3) ,
  out   @_ivirKortingPercentage                 numeric(15,2)
)
begin
  declare @FilterInkoopeenheid  nchar(20);
  declare @_ArtAantDecPrijzen   smallint;
  declare @_ArtSoort            smallint;

  // Initialisatie
  set @FilterInkoopeenheid = trim(isnull(@Inkoopeenheid, ''));

  // **************************************************
  // Eerst Inkoopprijs e.d. bepalen o.b.v.
  // gegevens bij artikel, leverancier en inkoopeenheid.
  // **************************************************
  begin
    // Ingangscontrole
    declare @_ArtGid            integer;
    declare @_ArtPartijGid      integer;

    select first ArtSoort,    ArtGid,   ArtPartijGid,   ArtAantDecPrijzen
      into       @_ArtSoort,  @_ArtGid, @_ArtPartijGid, @_ArtAantDecPrijzen
    from tabArtikel
      left join tabArtikelPartij on (ArtPartijArtGid = ArtGid) and (ArtPartijGid = @ArtPartijGid)
    where ArtGid = @ArtGid;

    if @_ArtSoort not in (0 /*tekst*/, 1 /*Tarief*/, 2 /*Artikel*/) then
      call Raise(20720,_U('Artikel/Tarief')); // (20720) %1 niet gevonden!
    end if;

    //call trace( String( 'BEPAAL INKOOPPPRIJS -',' ArtGid = ', @_ArtGid,' ArtPartijGid = ', @_ArtPartijGid,' Inkoopeenheid = ', @FilterInkoopeenheid,' AantalVoorraadeenhedeninInkoopeenheid = ', @VoorraadeenhedenInkoopeenheid,' ArtLevNawGid = ', @ArtLevNawGid,' Valutanummer = ', @ValutaNummer,' AantalOntvangen = ', @AantalOntvangen,' PeilDatum = ', @PeilDatum ) ) ;

    // Inkooprpijs ophalen, die is altijd per 1 inkoopeenheid of X voorraadeenheden (ArtPrijsPer van artikel zelf)
    // ACW We hebben hier geluk dat in de bestelling niet kan worden afgeweken van ArtPrijsPer, anders zouden we die van de bestelling zelf moeten opvragen
    //     Dit naar aanleiding van Ontime defect 59946
    select  Inkoopprijs,        KortingSoort,       Kortingbedrag,        KortingPercentage,        PrijsPerSoort
      into  @_ivirInkoopprijs,  @_ivirKortingSoort, @_ivirKortingBedrag,  @_ivirKortingPercentage,  @_ivirPrijsPerSoort
    from  BepaalInkoopprijs(
            @_ArtGid,
            @_ArtPartijGid,
            @FilterInkoopeenheid,
            @VoorraadeenhedenInkoopeenheid,
            @ArtLevNawGid,
            @ValutaNummer,
            @AantalOntvangen,
            @PeilDatum )
    where @_ArtSoort in (1 /*tarief*/, 2 /*artikel*/);

    //call trace( String( 'UITKOMST INKOOPPRIJS -',' Inkoopprijs = ', @_ivirInkoopprijs,' InkooppprijsPer = ', @_ivirInkoopprijsPer,' KortingSoort = ', @_ivirKortingSoort,' Kortingbedrag = ', @_ivirKortingBedrag,' KortingPercentage = ', @_ivirKortingPercentage,' PrijsPerSoort = ', @_ivirPrijsPerSoort ) ) ;
  end; // Inkoopppijrs o.b.v. artikel / leverancier / inkoopeenheid


  // ****************************************
  // Valideren van ingevulde parameters
  // natuurlijk alleen voor tarief / artikel
  // ****************************************

  // 1 = Tarief
  if ( @_ArtSoort = 1 /*tarief*/) then
    //ACW Is ook voor tarief gewoon toegestaan
    //if ( isnull(@ValidatieKortingBedrag,0) <> 0 ) then
    //  raiserror 20701, 'KortingBedrag is met tarief niet mogelijk.'; // (20701) Ongeldige combinatie: <opmerking>
    //end if;

    if (@ValidatieKortingPercentage is not null) then

      if (@ValidatieKortingPercentage not between -100 and 100 ) then
        call Raise(20700, _U('%1! moet tussen %2! en %3! liggen!', 'ValidatieKortingPercentage', '-100', '100')); // 920700) Ongeldige waarde: %1
      end if;

      set @_ivirKortingSoort = 1 /*Percentage*/;
      set @_ivirKortingPercentage = @ValidatieKortingPercentage;
    end if;

    // Er is een prijs voor tarief opgegeven? Neem die dan over.
    set @_ivirInkoopprijs = isnull(@ValidatieInkoopprijs, @_ivirInkoopprijs);
  end if; // tarief


    // KortingBedrag, KortingPercentage
  if @_ArtSoort in (1 /*Tarief*/, 2 /*Artikel*/) then
    if (@ValidatieKortingBedrag is not null and @ValidatieKortingPercentage is not null) then
      call Raise(20701, _U('%1! en %2! mogen niet beide ingevuld zijn!', 'ValidatieKortingBedrag', 'ValidatieKortingspercentage')); // (20701) Ongeldige combinatie: <opmerking>
    end if;

    if (@ValidatieKortingBedrag is not null) then
      set @_ivirKortingSoort = 0 /*Bedrag*/;
      set @_ivirKortingBedrag = @ValidatieKortingBedrag;
    end if;

    if ( @ValidatieKortingPercentage is not null ) then

      if (@ValidatieKortingPercentage not between -100 and 100 ) then
        call Raise(20700, _U('%1! moet tussen %2! en %3! liggen!', 'ValidatieKortingPercentage', '-100', '100')); // 920700) Ongeldige waarde: %1
      end if;

      set @_ivirKortingSoort = 1 /*Percentage*/;
      set @_ivirKortingPercentage = @ValidatieKortingPercentage;
    end if;

  end if;

  if ( @_ArtSoort = 2 /*Artikel*/) then

    // InkoopPrijsPer
    begin
      declare @PrijsPerSoort smallint;

      select  case isnull(@ValidatieInkoopprijsPer, '')
                when 'INKOOPEENHEID'    then 0
                when 'VOORRAADEENHEDEN' then 1
                when ''                 then @_ivirPrijsPerSoort // volgens gegevens bij de inkoopeenheid
                else null     // Oeps, een fout...
              end case
        into @PrijsPerSoort
      from dummy;

      if ( @PrijsPerSoort is null ) then
        call Raise(20700,'InkoopprijsPer'); // (20700) Ongeldige waarde: %1
      end if;

      // ACW 03-01-2025 Defect 59946: For a price per purchase unit this is always 1. With a price per stock unit this depends of the product itself (the X in: priced per X stock units)
      // RB/ACW 1903-2026 Defect 60219: PrijsPer van 1 bij prijs per inkoopeenheid gaat nog fout, besloten altijd ArtPrijsPer te gebruiken.
      // RB/ACW if @PrijsPerSoort = 0 /*Inkoopeenheid*/ then
      // RB/ACW   set @_ivirInkoopprijsPer = 1;
      // RB/ACW  else
         select ArtPrijsPer into @_ivirInkoopprijsPer from tabArtikel where ArtGid = @ArtGid;
      // RB/ACW end if;

      // De bij artikel opgehaalde inkoopprijs moet wel kloppen bij de PrijsPerSoort,
      // Omrekenen indien nodig
      select  case @_ivirPrijsPerSoort
                when 1  then round(@_ivirInkoopprijs * @VoorraadeenhedenInkoopeenheid, @_ArtAantDecPrijzen) // Prijs wordt per inkoopeenheid
                when 0  then round(@_ivirInkoopprijs / @VoorraadeenhedenInkoopeenheid, @_ArtAantDecPrijzen) // Prijs wordt per voorraadeenheid
                else 0  // geen prijs vast te stellen
              end case
        into @_ivirInkoopprijs
      from dummy
      where ( @_ivirPrijsPerSoort <> @PrijsPerSoort )
        and ( isnull(@_ivirInkoopprijs, 0) <> 0 );         // omrekenen heeft alleen zin als je een prijs hebt.

      // omrekenen gedaan, nu de soort goed zetten.
      set @_ivirPrijsPerSoort = @PrijsPerSoort;
      // Er is een prijs opgegeven? Neem die dan over.
      set @_ivirInkoopprijs = isnull(@ValidatieInkoopprijs, @_ivirInkoopprijs);

    end;
  else
    // Not a product, so price always per 1 item
    set @_ivirInkoopprijsPer = 1;
  end if ;
end;



create or replace procedure WebSvcHulpProc_ValideerAfleverDatumBestelregel(
  in  @ArtGid                     integer   ,
  in  @BstKopGid                  integer   ,
  in  @Inkoopeenheid              nchar(20),
  in  @AfleverDatum               date      ,
  out @_BstRglAfleverDatum        date
)
begin
  declare @BstKopBestelDatum        date;
  declare @BstKopBestelTijd         time;
  declare @BstKopAfleverDatum       date;
  declare @BstKopNawGid             integer;

  // De afleverdatum is alleen gevraagd bij artikel/tarief, niet bij tekstblok.
  if exists( select first 1 from tabArtikel where ArtSoort in (1 /*Tarief*/, 2 /*Artikel*/) and ArtGid = @ArtGid) then

    // een afleverdatum is alleen nodig voor echte artikelen.
    if (@AfleverDatum is null) then
      begin
        declare @AfleverTijdInDagen       smallint;
        declare @VgbDefAfleverDatumRegels smallint;

        select BstKopBestelDatum,   BstKopBestelTijd,   BstKopNawGid,   BstKopAfleverDatum
          into @BstKopBestelDatum,  @BstKopBestelTijd,  @BstKopNawGid,  @BstKopAfleverDatum
        from tabBestelKop where BstKopGid = @BstKopGid;

        // Zoek de aflevertijd in dagen op:
        // (1) In geval artikel een inkoopeenheid gespecificeerd heeft, dan staat dat daar.
        // (2) Zo niet, probeer het bij de leverancier van de bestelling als die bij artikel bekend is
        // (3) En is daar ook helemaal niks, dan 0, zoals de King GUI in alle gevallen voor afleverdagen ook laat zien.
        set @AfleverTijdInDagen = coalesce( ( select AldLeverTijd
                                              from tabArtikelLeverancierDetail    ALD
                                                inner join tabArtikelLeverancier  ARTLEV on ARTLEV.ArtlevGid = ALD.AldArtLevGid
                                              where  ArtLevNawGid = @BstKopNawGid
                                                and  ArtlevArtGid = @ArtGid
                                                and  AldInkoopEenheid = @Inkoopeenheid ),
                                            ( select LevGegLeverTijd from tabLeverancierGegevens where LevGegNawGid = @BstKopNawGid ),
                                            0 );

        select  case VgbDefAfleverDatumRegels
                  when  0 then now()                                        // Systeemdatum
                  when  1 then @@VerwerkingsDatum                           // Verwerkingsdatum
                  when  2 then (  select dateadd( day, @AfleverTijdInDagen, @BstKopBestelDatum ) )  // Besteldatum + levertijd in dagen
                  when  3 then (  select dateadd( day, @AfleverTijdInDagen, @BstKopBestelDatum ) )  // Zelfde als 2, er volgt later check om met afleverdagen rekening te houden
                  when  4 then @BstKopAfleverDatum                          // OntvangstDatum van de bestelling
                  when  5 then null                                         // Leeg laten
                  else null                                                 // iets raars, afwijkends? geef dan geen datum op.
                end case
        ,       VgbDefAfleverDatumRegels
          into  @_BstRglAfleverDatum,
                @VgbDefAfleverDatumRegels
        from tabVasteGegevensBestellingen;

        //call trace( String( ' BestelDatum = ', @BstKopBestelDatum, ' instelling = ', @VgbDefAfleverDatumRegels, ' AflevertijdIndagen = ', @AfleverTijdInDagen, ' ==> afleverdatum = ', @_BstRglAfleverDatum ) );

        // Mits een afleverdatum bekend is met de levertijd alvast opgeteld,
        // moeten we nog wel met afleverdagen van leverancier rekening houden
        // en dus zorgen dat we op de datum van afleverdag uit komen.
        if ( @VgbDefAfleverDatumRegels = 3 ) and ( @_BstRglAfleverDatum is not null ) then
          begin
            declare @_BstRglAfleverDag           smallint; //  1 = maandag, ... 7 = zondag
            declare @_BestelDag               smallint; //  1 = maandag, ... 7 = zondag

            //Sybase kent eigen nummering van dagen, die omzetten naar de King 5 definitie
            select  case dow(@BstKopBestelDatum)   // Sybase dagnummer van de week
                      when 1 then  7   //  Zondag
                      when 2 then  1   //  Maandag
                      when 3 then  2   //  Dinsdag
                      when 4 then  3   //  Woensdag
                      when 5 then  4   //  Donderdag
                      when 6 then  5   //  Vrijdag
                      when 7 then  6   //  Zaterdag
                    end case
            ,       case dow(@_BstRglAfleverDatum)   // Sybase dagnummer van de week
                      when 1 then  7   //  Zondag
                      when 2 then  1   //  Maandag
                      when 3 then  2   //  Dinsdag
                      when 4 then  3   //  Woensdag
                      when 5 then  4   //  Donderdag
                      when 6 then  5   //  Vrijdag
                      when 7 then  6   //  Zaterdag
                    end case
              into @_BestelDag, @_BstRglAfleverDag
            from dummy;

            // Je mag alleen die leverdagen nemen, waar de besteldatum aan de bestellen vÃ³Ã³r criterium voldoet.
            // Is er geen tijd opgegeven in de betselling, dan laatste tel van de dag,
            // dit helpt bij testen tegen ingevulde tijdstip bij Bestellen vÃ³Ã³r dag
            select first  case
                            when @_BstRglAfleverDag < ladAfleverdag then dateadd(day, ladAfleverdag - @_BstRglAfleverDag, @_BstRglAfleverDatum )
                            when @_BstRglAfleverDag > ladAfleverdag then dateadd(day, 7 + ladAfleverdag - @_BstRglAfleverDag, @_BstRglAfleverDatum )
                            else @_BstRglAfleverDatum
                          end case
              into @_BstRglAfleverDatum
            from tabLeverancierAfleverDagen       LAD
              inner join  tabLeverancierGegevens  LEVGEG  on LEVGEG.LevGegGid = LAD.LadLevGegGid
            where ( LEVGEG.levGegNawGid = @BstKopNawGid )                                 // afleverdagen van leverancier uit de bestelling
              and ( ( @_BestelDag = LAD.ladBestellenVoor                                  // Bestellen op de dag
                      and isnull(@BstKopBestelTijd, '23:59:59.999') < LAD.ladTijdStip )   // maar wel vÃ³Ã³r een tijdstip
                    or  ( @_BestelDag < LAD.ladBestellenVoor)                             // of er is geen tijdstip, dan is besteldag vÃ³Ã³r de dag waarop besteld diende te worden
                    or  ( @_BestelDag >= LAD.ladBestellenVoor
                          and @_BestelDag < (LAD.ladBestellenVoor + 7)                    // of besteldag is op of nÃ¡ de dag waarvoor besteld diende te worden
                          and LAD.ladTijdStip is null )                                   // sluit wel de dag uit waar een tijdstip bij is opgegeven.
                  )
            order by LAD.ladAfleverDag asc;                                               // de (eerstvolgende) leverdag telt.
          end;
        end if; // datum van afleverdag.
      end;
    else
      set @_BstRglAfleverDatum = @AfleverDatum;
    end if;
  else
    // Geen artikel, dus ook geen afleverdatum
    set @_BstRglAfleverDatum = null;
  end if;

end;


create or replace procedure WebSvcHulpProc_ValideerArtikelOmschrijvingBestelRegel(
  in    @RegelSoort                   smallint      , //0=tekst, 1=tarief, 2=artikel
  inout @ArtGid                       integer       ,
  in    @ArtPartijGid                 integer       ,
  in    @NawGid                       integer       ,
  in    @Omschrijving                 long nvarchar ,
  inout @_OmschrijvingInkoopEenheid   long nvarchar
)
begin

  if isnull(trim(@Omschrijving),'') <> '' then
    set @_OmschrijvingInkoopEenheid = trim(@Omschrijving);
  else
    set @_OmschrijvingInkoopEenheid = isnull(trim(@_OmschrijvingInkoopEenheid), '');
  end if;

  if @RegelSoort = 0 /*tekst*/ then
    // Artikel leeg, dan oms overnemen (is hierboven al gebeurd)
    // artikel gevuld, tekst leeg, dan artikel overnemen
    // artikel gevuld, tekst gevuld, dan tekst vergelijken met tekstblok, zelfde, dan tekst leeg, anders, dan artikel leeg
    if @ArtGid is not null then
      begin
        declare @t long nvarchar;
        declare @TaalGid integer;
        set @TaalGid = ( select NawTaalGid from tabNaw where NawGid = @NawGid);
        set @t = coalesce( (select ArtTekst from tabArtikelTeksten where ArtTekstArtGid = @ArtGid and ArtTaalGid = @TaalGid),
                           (select ArtOms from tabArtikel where ArtGid = @ArtGid) );
        if trim(@Omschrijving) <> '' and @_OmschrijvingInkoopEenheid <> @t then
          set @ArtGid = null; // Deze leeg maken, zodat de eigen tekst op factuur voor de tekstregel wordt onthouden
        end if;
      end;
    end if;

  else
    // Geen omschrijving bekend, ook niet bij inkoopeenheid van leverancier van artikel?
    // Dan volgens defaults in vaste gegevens bestellingen werken.
    if @_OmschrijvingInkoopEenheid = '' then
      begin
        declare @TaalGid integer;
        set @TaalGid = ( select NawTaalGid from tabNaw where NawGid = @NawGid);

        select  case VgbDefOmsRegels
                    // 0 = Tekst op factuur bij tarief / artikel:
                    // a) Tekst bij partij op basis van taal van crediteur, en indien onbekend dan
                    // b) interne omschrijving van partij , en anders
                    // c) tekst bij artikel op basis van taal van crediteur, en indien onbekend dan
                    // d) interne omschrijving van artikel.
                    when 0  then  coalesce( (select ArtPartijTekstOpFactuur from tabArtikelPartijTeksten where ArtPartijTekstArtPartijGid = @ArtPartijGid and ArtPartijTekstTaalGid = @TaalGid ),
                                            (select ArtpartijOms from tabArtikelPartij where ArtPartijGid = @ArtPartijGid ),
                                            (select ArtTekst from tabArtikelTeksten where ArtTekstArtGid = @ArtGid and ArtTaalGid = @TaalGid),
                                            (select ArtOms from tabArtikel where ArtGid = @ArtGid) )
                    // 1 = Interne omschrijving:
                    // a) van de partij, en anders
                    // b) van het artikel zelf
                    when 1  then  isnull( (select ArtpartijOms from tabArtikelPartij where ArtPartijGid = @ArtPartijGid ),
                                          (select ArtOms from tabArtikel where ArtGid = @ArtGid) )
                    // 2 = Leeg laten.
                    when 2  then null
                    else null         // onbekende optie, niets mee doen.
                  end case
            into @_OmschrijvingInkoopEenheid
          from tabVasteGegevensBestellingen
      end;
    end if; //if @_OmschrijvingInkoopEenheid = '' then
  end if;

end;



create or replace procedure WebSvcHulpProc_ValideerBesteladresBestelling(
  in @BstKopNawGid          integer     ,
  in @BestelAdres           nchar(4)    ,
  in @BestelAdresNummer     numeric(3,0),
  out @_BestelAdresSoort    smallint    ,
  out @_AdrGid              integer
)
begin

  // Er is een soort besteladres gesepcificeerd.
  if ( trim( isnull(@BestelAdres, '') ) = '') then
    // Default ophalen bij leveranciergegevens (mits die er zijn), en anders 'COR'
    set @_BestelAdresSoort = isnull(  ( select LevGegBestelAdres from tabLeverancierGegevens where LevGegNawGid = @BstKopNawGid )
                                   ,  0 );   // 0 = COR, 1 = VEST , 2 = BEST
  else
    set @_BestelAdresSoort = ( select  case trim(@BestelAdres)
                                  when 'COR'       then 0 /*Correspondentieadres*/
                                  when 'VEST'      then 1 /*Vestigingsadres*/
                                  when 'BEST'      then 2 /*Besteladres*/
                                  else null                 // ongeldige waardes
                                end case
                                from dummy );

    if (@_BestelAdresSoort is null ) then
      call Raise(20700, 'BestelAdres');  // Ongeldige waarde: %1
    end if;

    set @_AdrGid = null; // we moeten adres gegevens opnieuw gaan opvragen.

      // Is er ook een adresnummer bij opgegeven Besteladres?
    if ( @_BestelAdresSoort = 2 /*Besteladres*/) then
      if ( isnull(@BestelAdresNummer,-1) =  -1 ) then
        call Raise(20701, _U('Bij %1! is %2! verplicht.', 'BestelAdres', 'BestelAdresNummer')) ; // Ongeldige combinatie: %1
      end if;

      //Er is een besteladresnummer, is er ook een adres bij?
      set @_AdrGid = ( select AdrGid from tabAdres where AdrCode = @BestelAdresNummer and AdrNawGid = @BstKopNawGid );
      if (@_AdrGid is null ) then
        call Raise(20720, 'BestelAdresNummer');  // (20720) %1 niet gevonden!
      end if;

    end if; // Soort = besteladres
  end if; // @BestelAdres gespecificeerd

  // we weten definitieve BestelAdresSoort, nu adres erbij zoeken.
  select  case @_BestelAdresSoort
            when  2 then isnull( @_AdrGid                                                           // 2 = besteladres, heeft gebruiker opgegeven, en anders ...
                               , ( select LevGegAdrGidBestelAdres from tabLeverancierGegevens where LevGegNawGid = @BstKopNawGid ) ) // adres ingesteld bij leveranciergegevens
            //ACW Correspondentie en vestiging niet als adrgid invullen
            //when  1 then ( select NawGidVestiging from tabNaw where nawGid = @BstKopNawGid )        // 1 = Vestiging
            //when  0 then ( select NawGidCorrespondentie from tabNaw where nawGid = @BstKopNawGid )  // 0 = correspondentie
            else null
          end case
    into @_AdrGid
  from dummy;

  // we hebben een adres gevonden, toch?
  if (@_BestelAdresSoort = 2 /*Besteladres*/) and ( @_AdrGid is null ) then
    call Raise(20720, _U('Adres van leverancier')) ; // %1 niet gevonden!
  end if;
end;


create or replace procedure WebSvcHulpProc_ValideerLeverancierNummerOfEan(
  in @NawFilNummer        nchar(15)     ,   // langer dan maximaal 10, ivm afkapgedrag van King Webservices V2
  in @AdrEanCode          nchar(14)     ,   // GLN code is 13 tekens, en voorloopnullen tellen mee...
  out @_NawGid            integer
)
begin
  declare @_NawFilNummer        nchar(10);
  declare @_AdrEanCode          nchar(13);

  // *** Valideer NAW-nummer (max. 10 positites)
  if length(trim(@NawFilNummer)) > 10 then
    call Raise(20700, _U('%1!, is langer dan %2! cijfers.', 'Leveranciernummer', '10')); // Ongeldige waarde: %1
  end if;
  set @_NawFilNummer =  trim(@NawFilNummer);


  // *** Valideer GLN code is (max 13 tekens voor leverende (OEM) partijen)
  if length(trim(@AdrEanCode)) > 13 then
    call Raise(20700, _U('%1!, is langer dan %2! cijfers.', 'Leverancier ean code', '13')); // Ongeldige waarde: %1
  end if;
  set @_AdrEanCode = trim(@AdrEanCode);

  // *** Valideer combinaties
  if  ( @_AdrEanCode is null and @_NawFilNummer is null ) then
    call Raise(20701, _U('%1! of %2! moet ingevuld zijn!', _U('Leveranciernummer'), _U('Leverancier ean code'))) ; // Ongeldige combinatie: %1
  end if;

  if ( @_AdrEanCode <> ''  and @_NawFilNummer <> '' ) then
    call Raise(20701, _U('%1! en %2! mogen niet beide ingevuld zijn!', _U('Leveranciernummer'), _U('Leverancier ean code'))); // Ongeldige combinatie: %1
  end if;

  // *** leveranciernummer
  if  ( @_NawFilNummer <> '' ) then
    select  NawFilNawGid into @_NawGid from tabNawFile inner join tabFileOfNaw on FonGid = NawFilFonGid and FonId = 'C' where NawFilNummer = @_NawFilNummer;
    if @_NawGid is null then
      call Raise(20720, _U('Leveranciernummer')) ; // %1 niet gevonden!
    end if;
  end if;

  // *** Valideer EAN code leverancier
  if  ( @_AdrEanCode <> '' ) then
    // EAN c.q. GLN code  mag alleen uit cijfers bestaan
    if ( patindex('%[^0-9]%', @_AdrEanCode) <> 0 ) then
      call Raise(20700, _U('Leverancier ean code mag alleen uit cijfers bestaan.')); // Ongeldige waarde: %1
    end if;

    call WebSvcHulpProc_ValideerNawEanCode(
      @_AdrEanCode,
      'C',                  // c = crediteur, d = debiteur, b = bedrijfsgegevens, 123 = nummer relatiebestand
      null,                 // Indien NawGid ingevuld, wordt getoetst of EAN code hierbij hoort ( let op de FonId!)
      //out
      null,                 // de gevalideerde EAN code
      @_NawGid);         // de NAW waar het bij hoort.
    if @_NawGid is null then
      call Raise(20720, _U('Leverancier ean code')); // %1 niet gevonden!
    end if;
  end if;
end;



create or replace procedure WebSvcHulpProc_ValideerNawValuta(
  in    @ValutaCode   nchar(3)  ,
  in    @NawGid       integer   ,         // Indien ingevuld, wordt daar de valuta opgezocht
  out   @_ValNummer   integer   ,
  out   @_ValCode     nchar(3)
)
begin

  // Er is een valutacode opgegeven, is die te gebruiken?
  if ( isnull(@ValutaCode,'') = '' ) then
    // Geen valuta opgegeven, dus dan proberen die van de NAW te gebruiken, indien een NAW is opgegeven
    // Als bij de NAW geen valuta is opgegeven, dan levert de query niks op
    // dus pakken we straks de basisvaluta
    select  NAW.NawFilValNummer,  VAL.ValCode
      into  @_ValNummer,          @_ValCode
    from  tabNawFile        NAW
      inner join TabValuta  VAL on VAL.ValNummer = NAW.NawFilValNummer
    where NawFilNawGid = @NawGid;

  else
    set @_ValNummer = ( Select ValNummer from tabValuta where ValCode = @ValutaCode );
    if @_ValNummer is null then
      call Raise(20700 , 'ValutaCode'); // Ongeldige waarde : %1
    end if;

    set @_ValCode = ( select ValCode from tabValuta where ValNummer = @_ValNummer );

  end if; // isnull(@ValutaCode, ... )

  if @_ValNummer is null or @_ValCode is null then
    // Niks gevonden, dan de basisvalutagegevens...
    call BasisValuta( @_ValNummer, @_ValCode );
  end if;

end;



create or replace procedure WebSvcProc_Bestelling_BestelRegel_SpecificatieRegel_Toevoegen (
  in @BestelNummer numeric(10,0) default null,
  in @BestelRegelNummer numeric(3,0) default null,
  in @Soort nchar(12) default 'MAGAZIJN',   // 'MAGAZIJN', 'VERKOOPORDER'
  in @OrderNummer numeric(10,0) default null,
  in @OrderRegelNummer numeric(5,0) default null,
  in @AantalBesteldVrrdEenh numeric(15,3) default 0,
  in @AantalNogTeOntvangenVrrdEenh numeric(15,3) default 0
)
result (SpecificatieRegelID integer)
begin
  // variabelen overeenkomend met tabBestelRegelDetail velden
  declare @_BrdOrrGid integer;

  // overige variabelen
  declare @_BstKopGid integer;
  declare @_BrdBstRglGid integer;
  declare @_BrdSoort smallint default 0; /*0=Magazijn, 1=Verkooporder*/
  declare @_BstRglArtGid integer;
  declare @_BstRglArtPartijGid integer;

  declare @_BrdGid integer;

  //call TraceBegin('WebSvcProc_Bestelling_BestelRegel_SpecificatieRegel_Toevoegen');

  // Module: is er geen bestelling actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('be') = 0 then
    call Raise(20790, _U('Optie Bestelling')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790, _U('Optie Voorraad')); //(20790) '%1!' niet geactiveerd!
  end if;

  //Bestaat de opgegeven bestelregel, en is de bestelling niet al verwerkt?
  begin
    declare @_BstKopIsVerwerkt smallint;
    declare @_BstRglTotaalAantalSpecRegelsKomtOvereen  smallint;
    declare @_BstRglSoort smallint; /*0= Tekst, 1= Tarief, 2= Artikel */

    select BstKopGid, BstKopIsVerwerkt
    into @_BstKopGid, @_BstKopIsVerwerkt
    from tabBestelKop
    where BstKopNummer = @BestelNummer;

    if (@_BstKopGid is null) then
      call Raise(20720, 'BestelNummer'); //(20720) niet gevonden: %1!
    end if;

    if @_BstKopIsVerwerkt = 1 then
      call Raise(20780, _U('Specificatieregel toevoegen'),_U('bestelling is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    select BstRglGid, BstRglTotaalAantalSpecRegelsKomtOvereen, BstRglSoort, BstRglArtGid, BstRglArtPartijGid
    into @_BrdBstRglGid, @_BstRglTotaalAantalSpecRegelsKomtOvereen, @_BstRglSoort, @_BstRglArtGid, @_BstRglArtPartijGid
    from tabBestelRegel
    where BstRglBstKopGid = @_BstKopGid
      and BstRglNummer = @BestelRegelNummer;

    if (@_BrdBstRglGid is null) then
      call Raise(20720, 'BestelRegelNummer'); //(20720) niet gevonden: %1!
    end if;

    if @_BstRglSoort <> 2 /* Artikel */ then
      call Raise(20780, _U('Specificatieregel toevoegen') ,_U('Tekst- en tariefregels kunnen geen specificatieregels bevatten')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    if @_BstRglTotaalAantalSpecRegelsKomtOvereen <> 0 then
      call Raise(20780, _U('Specificatieregel toevoegen'), _U('regels komen dan niet meer overeen met bestelregel')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;
  end; // Bestelregel

  //Regelsoort
  if @Soort not in ('MAGAZIJN', 'VERKOOPORDER') then
    call Raise(20700,'RegelSoort'); // (20700) Ongeldige waarde: %1!
  end if;

  if @Soort = 'VERKOOPORDER' then
  begin
    declare @_OrrArtPartijGid integer;
    declare @_OrrArtGid integer;
    declare @_GekoppeldAanBrdBstRglGid integer;

    set @_BrdSoort = 1; /*Verkooporder*/

    //Ordernummer check
    if isNull(@OrderNummer, '') = '' then
      call Raise(20700,'OrderNummer'); // (20700) Ongeldige waarde: %1!
    end if;

    //OrderRegelNummer check
    if isNull(@OrderRegelNummer, '') = '' then
      call Raise(20700,'OrderRegelNummer'); // (20700) Ongeldige waarde: %1!
    end if;

    select OrrGid, OrrArtGid, OrrArtPartijGid  into @_BrdOrrGid, @_OrrArtGid, @_OrrArtPartijGid
    from tabOrderRegel
    inner join tabOrderKop on OrkGid = OrrOrkGid
    where OrkNummer = @OrderNummer
      and OrrRegelNr = @OrderRegelNummer;

    if @_BrdOrrGid is null then
      call Raise(20720, 'OrderNummer/OrderRegelNummer'); //(20720) %1! niet gevonden!
    end if;

    if @_OrrArtGid <> @_BstRglArtGid then
      call Raise(20780,  _U('Specificatieregel toevoegen'),_U('het artikel van verkooporder %1!/%2! komt niet overeen met die van de bestelregel', string(@OrderNummer), string(@OrderRegelNummer))); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    //Is de orderregel al gekoppeld aan een (andere) bestellingsregel
    select first BrdBstRglGid into @_GekoppeldAanBrdBstRglGid
    from tabBestelRegelDetail
    where BrdSoort = 1 /*Verkooporder*/
      and ((BrdOrrGid = @_BrdOrrGid));

    if @_GekoppeldAanBrdBstRglGid is not null then
      //De regel is al gekoppeld aan deze bestelling
      if @_GekoppeldAanBrdBstRglGid = @_BrdBstRglGid then
        call Raise(20780, _U('Specificatieregel toevoegen'), _U('verkooporder %1!/%2! is al gekoppeld aan deze bestelregel', string(@OrderNummer), string(@OrderRegelNummer))); // <Actie> niet mogelijk. Reden: <Reden>.
      end if;

      //De regel is al gekoppeld aan een bestelling
      if @_GekoppeldAanBrdBstRglGid <> @_BrdBstRglGid then
        call Raise(20780, _U('Specificatieregel toevoegen'), _U('verkooporder %1!/%2! is al gekoppeld aan een bestelregel', string(@OrderNummer), string(@OrderRegelNummer))); // <Actie> niet mogelijk. Reden: <Reden>.
      end if;
    end if;

    //De regel is al gekoppeld aan een magazijnontvangst
    if exists(select first 1 from tabMagazijnOntvangstenDetail where MagOntDetOrrGid = @_BrdOrrGid) then
      call Raise(20780, _U('Specificatieregel toevoegen'), _U('verkooporder %1!/%2! is al gekoppeld aan een magazijnontvangst', string(@OrderNummer), string(@OrderRegelNummer))); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    //Heeft de order partijen.
    select OrrArtGid, OrrArtPartijGid into @_OrrArtGid, @_OrrArtPartijGid
    from taborderregel
    inner join tabOrderKop on OrkGid = OrrOrkGid
    where OrrGid = @_BrdOrrGid;

    if (@_OrrArtPartijGid is not null) then
      if (@_OrrArtPartijGid <> @_BstRglArtPartijGid) then
        call Raise(20780, _U('Specificatieregel toevoegen'), _U('Partij van verkooporder %1!/%2! komt niet overeen met die van de bestelregel', string(@OrderNummer), string(@OrderRegelNummer))); // <Actie> niet mogelijk. Reden: <Reden>.
      end if;
      if exists(select 1 from tabArtikelPartij where ArtPartijGid = @_OrrArtPartijGid and ArtPartijArtGid = @_OrrArtGid and ArtPartijIsGeblokkeerdVoorInkoop <> 0) then
        call Raise(20780, _U('Specificatieregel toevoegen'), _U('Partij is geblokkeerd voor magazijnontvangst')); // <Actie> niet mogelijk. Reden: <Reden>.
      end if;
      if exists(select 1 from tabArtikelPartij where ArtPartijGid = @_OrrArtPartijGid and ArtPartijArtGid = @_OrrArtGid and ArtPartijIsGeblokkeerdVoorVerkoop <> 0) then
        call Raise(20780, _U('Specificatieregel toevoegen'), _U('Partij is geblokkeerd voor verkoop')); // <Actie> niet mogelijk. Reden: <Reden>.
      end if;
    end if;
  end;
  else
    //Als het een magazijn regel is, kijk dan wel of deze nog niet bestaat. Dit mag er maar 1 zijn.
    if exists(select 1 from tabBestelRegelDetail where BrdBstRglGid = @_BrdBstRglGid and BrdSoort = 0 /*Magazijn*/) then
      call Raise(20780, _U('Specificatieregel toevoegen'), _U('er kan maar 1 magazijnregel worden toegevoegd')); //20780) %1! niet mogelijk: %2!
    end if;
  end if;

  //Toevoegen
  begin atomic
    // Bestelling eerst locken. Lukt dat niet: abort
    call WebSvcHulpProc_BestellingExclusiefLocken(@_BstKopGid);

    insert into tabBestelRegelDetail with auto name
    select @_BrdBstRglGid as BrdBstRglGid,
           @_BrdOrrGid as BrdOrrGid,
           @_BrdSoort as BrdSoort,
           @AantalBesteldVrrdEenh as BrdAantalBesteld,
           @AantalNogTeOntvangenVrrdEenh as BrdAantalNogTeOntvangen,
           @AantalBesteldVrrdEenh - @AantalNogTeOntvangenVrrdEenh as BrdAantalOntvangen,
           now() as BrdLastModified;

    set @_BrdGid = @@Identity;
  end; // atomic

  //Resultaat
  select @_BrdGid as SpecificatieRegelID from dummy;

  //call TraceEind('WebSvcProc_Bestelling_BestelRegel_SpecificatieRegel_Toevoegen');
end;


create or replace procedure WebSvcProc_Bestelling_BestelRegel_Toevoegen
(
  in @BestelNummer                    numeric(10,0) ,
  in @RegelSoort                      nchar(5)      ,   // vaste waarden: ART, TAR, TEKST
  in @RegelNummer                     integer       ,   // Optioneel: minimaal 1 en maximaal 999
  in @ArtikelNummer                   nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservcies V2
  in @AantalBesteld                   numeric(15,3) ,
  // hieronder de optionele velden
  in @InkoopEenheid                   nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
  in @VoorraadEenhedenInInkoopEenheid numeric(13,3) ,
  in @ArtikelNummerLeverancier        nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
  in @EanCode                         nchar(31)     ,   // langer dan 30 , ivm afkappen door King webservices V2
  in @PartijNummer                    nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
  in @Omschrijving                    long nvarchar ,
  in @InkoopprijsPer                  nchar(16)     ,   // vaste waarden: INKOOPEENHEID, of VOORRAADEENHEDEN
  in @InkoopPrijs                     numeric(15,3) ,
  in @Kortingspercentage              numeric(5,2)  ,
  in @Kortingsbedrag                  numeric(15,3) ,
  in @BtwCode                         numeric(3,0)  ,
  in @OntvangstDatum                  date          ,
  in @Opmerking                       long nvarchar ,
  in @StandaardSpecificatieRegel      nchar(3)          // vaste waarden: JA, NEE
)
result (
  BestelRegelNummer numeric(3,0)
)
begin


  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen bestelling actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('be') = 0 then
    call Raise(20790,    _U('Optie Bestelling'));    // (20790) '%1!' niet geactiveerd!
  end if;

  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790,    _U('Optie Voorraad'));         // (20790) '%1!' niet geactiveerd!
  end if;

  // King webservices V2 kapt automatisch invoer af op de bij de paramater gespecifieerde lengte
  // we hebben die parameters nu extr alengte gegeven, en testen deie parameters op echte maximumlengte

  if (@RegelNummer is not null) and (@RegelNummer not between 1 and 999) then
    call Raise(20700, _U('%1!, minimaal %2!, maximaal %3! toegestaan.', 'RegelNummer', '1', '999')); // Ongeldige waarde: %1
  end if;

  if length(@ArtikelNummer) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'ArtikelNummer', '20')); // Ongeldige waarde: %1
  end if;

  if length(@InkoopEenheid) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'InkoopEenheid', '20')); // Ongeldige waarde: %1
  end if;

  if length(@ArtikelNummerLeverancier) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'ArtikelNummerLeverancier', '20')); // Ongeldige waarde: %1
  end if;

  if length(@EanCode) > 30 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'EanCode', 30)); // Ongeldige waarde: %1
  end if;

  if length(@PartijNummer) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'PartijNummer', 20)); // Ongeldige waarde: %1
  end if;


  // Nu gaat het echte werk beginnen...
  // T.b.v. specificatieregel  zijn de nummers nodig, zie verderop in de code.
  select  BestelRegelNummer
  from    WebSvcHulpProc_Bestelling_BestelRegel_ToevoegenTussenvoegen(
            @BestelNummer,                    //  numeric(10,0) ,
            @RegelSoort,                      //  nchar(5)      ,   // vaste waarden: ART, TAR, TEKST
            @RegelNummer,                     //  integer       ,
            0,                                //  @RegelTussenvoegen smallint Boolean: 0 = Nee, 1 = Ja, bestaande regels opschuiven om nieuwe regel tussen te voegen
            @ArtikelNummer,                   //  nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservcies V2
            @AantalBesteld,                   //  numeric(15,3) ,
            // hieronder de optionele velden
            @InkoopEenheid,                   //  nchar(21)     ,
            @VoorraadEenhedenInInkoopEenheid, //  numeric(15,3) ,
            @ArtikelNummerLeverancier,        //  nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
            @EanCode,                         //  nchar(31)     ,   // langer dan 14, ivm afkappen door King webservices V2
            @PartijNummer,                    //  nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
            @Omschrijving,                    //  long nvarchar ,
            @InkoopprijsPer,                  //  nchar(16)     ,   // vaste waarden: INKOOPEENHEID, of VOORRAADEENHEDEN
            @InkoopPrijs,                     //  numeric(15,3) ,
            @Kortingspercentage,              //  numeric(5,2)  ,
            @Kortingsbedrag,                  //  numeric(15,3) ,
            @BtwCode,                         //  numeric(3,0)  ,
            @OntvangstDatum,                  //  date          ,
            @Opmerking,                       //  long nvarchar ,
            @StandaardSpecificatieRegel       //  nchar(4)          // vaste waarden: JA, NEE
          );

end;


create or replace procedure WebSvcProc_Bestelling_BestelRegel_Tussenvoegen
(
  in @BestelNummer                    numeric(10,0) ,
  in @RegelSoort                      nchar(5)      ,   // vaste waarden: ART, TAR, TEKST
  in @RegelNummer                     integer       ,   // Optioneel: minimaal 1 en maximaal 999
  in @ArtikelNummer                   nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservcies V2
  in @AantalBesteld                   numeric(15,3) ,
  // hieronder de optionele velden
  in @InkoopEenheid                   nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
  in @VoorraadEenhedenInInkoopEenheid numeric(13,3) ,
  in @ArtikelNummerLeverancier        nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
  in @EanCode                         nchar(31)     ,   // langer dan 30 , ivm afkappen door King webservices V2
  in @PartijNummer                    nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
  in @Omschrijving                    long nvarchar ,
  in @InkoopprijsPer                  nchar(16)     ,   // vaste waarden: INKOOPEENHEID, of VOORRAADEENHEDEN
  in @InkoopPrijs                     numeric(15,3) ,
  in @Kortingspercentage              numeric(5,2)  ,
  in @Kortingsbedrag                  numeric(15,3) ,
  in @BtwCode                         numeric(3,0)  ,
  in @OntvangstDatum                  date          ,
