  in @StandaardSpecificatieRegel      nchar(3)          // vaste waarden: JA, NEE
)
result (
  BestelRegelNummer numeric(3,0)
)
begin


  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen bestelling actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('be') = 0 then
    call Raise(20790,    _U('Optie Bestelling'));    // (20790) '%1!' niet geactiveerd!
  end if;

  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790,    _U('Optie Voorraad'));         // (20790) '%1!' niet geactiveerd!
  end if;

  // King webservices V2 kapt automatisch invoer af op de bij de paramater gespecifieerde lengte
  // we hebben die parameters nu extr alengte gegeven, en testen deie parameters op echte maximumlengte

  if (@RegelNummer is null) or (@RegelNummer not between 1 and 999) then
    call Raise(20700, _U('%1!, minimaal %2!, maximaal %3! toegestaan.', 'RegelNummer', '1', '999')); // Ongeldige waarde: %1
  end if;

  if length(@ArtikelNummer) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'ArtikelNummer', '20')); // Ongeldige waarde: %1
  end if;

  if length(@InkoopEenheid) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'InkoopEenheid', '20')); // Ongeldige waarde: %1
  end if;

  if length(@ArtikelNummerLeverancier) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'ArtikelNummerLeverancier', '20')); // Ongeldige waarde: %1
  end if;

  if length(@EanCode) > 30 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'EanCode', '30')); // Ongeldige waarde: %1
  end if;

  if length(@PartijNummer) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'PartijNummer', '20')); // Ongeldige waarde: %1
  end if;

  // Nu gaat het echte werk beginnen...
  // T.b.v. specificatieregel  zijn de nummers nodig, zie verderop in de code.
  select  BestelRegelNummer
  from    WebSvcHulpProc_Bestelling_BestelRegel_ToevoegenTussenvoegen(
            @BestelNummer,                    //  numeric(10,0) ,
            @RegelSoort,                      //  nchar(5)      ,   // vaste waarden: ART, TAR, TEKST
            @RegelNummer,                     //  integer       ,
            1,                                //  @RegelTussenvoegen smallint Boolean: 0 = Nee, 1 = Ja, bestaande regels opschuiven om nieuwe regel tussen te voegen
            @ArtikelNummer,                   //  nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservcies V2
            @AantalBesteld,                   //  numeric(15,3) ,
            // hieronder de optionele velden
            @InkoopEenheid,                   //  nchar(21)     ,
            @VoorraadEenhedenInInkoopEenheid, //  numeric(15,3) ,
            @ArtikelNummerLeverancier,        //  nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
            @EanCode,                         //  nchar(31)     ,   // langer dan 14, ivm afkappen door King webservices V2
            @PartijNummer,                    //  nchar(21)     ,   // Langer dan 20 , ivm afkappen door King webservices V2
            @Omschrijving,                    //  long nvarchar ,
            @InkoopprijsPer,                  //  nchar(16)     ,   // vaste waarden: INKOOPEENHEID, of VOORRAADEENHEDEN
            @InkoopPrijs,                     //  numeric(15,3) ,
            @Kortingspercentage,              //  numeric(5,2)  ,
            @Kortingsbedrag,                  //  numeric(15,3) ,
            @BtwCode,                         //  numeric(3,0)  ,
            @OntvangstDatum,                  //  date          ,
            @Opmerking,                       //  long nvarchar ,
            @StandaardSpecificatieRegel       //  nchar(4)          // vaste waarden: JA, NEE
            );

end;



create or replace procedure WebSvcProc_Bestelling_BestelRegel_Verwijderen(
   in @BestelNummer      numeric(10,0),
   in @BestelRegelNummer numeric(3,0)
)
begin
  // *** ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen bestelling actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('be') = 0 then
    call Raise(20790, _U('Optie Bestelling')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790, _U('Optie Voorraad'));   // (20790) '%1!' niet geactiveerd!
  end if;

  begin
    declare @_BstRglBstKopGid  integer;
    declare @_BstRglGid        integer;

    // **************************
    // *** Controle verplichte velden
    // **************************

    // --- Bestaat de opgegeven bestelling?
    begin
      set @_BstRglBstKopGid = null;
      select BstKopGid
      into   @_BstRglBstKopGid
      from   tabBestelKop
      where  BstKopNummer = @BestelNummer;

      if (@_BstRglBstKopGid is null) then
        call Raise(20720, 'BestelNummer'); // (20720) niet gevonden: %1!
      end if;
    end; // Bestelling

    // --- Bestaat de opgegeven bestelregel?
    begin
      set @_BstRglGid = null;
      select BstRglGid
      into   @_BstRglGid
      from   tabBestelRegel
      where  BstRglBstKopGid = @_BstRglBstKopGid
             and BstRglNummer = @BestelRegelNummer;

      if (@_BstRglGid is null) then
        call Raise(20720, 'BestelRegelNummer'); // (20720) niet gevonden: %1!
      end if;
    end; // Bestelling

    // *** Regel verwijderen
    begin Atomic
      // Bestelling eerst locken. Lukt dat niet: abort
      call WebSvcHulpProc_BestellingExclusiefLocken(@_BstRglBstKopGid);

      // Verwijderen bestelregel
      delete from tabBestelRegel where BstRglBstKopGid = @_BstRglBstKopGid and BstRglGid = @_BstRglGid;
    end;

  end;

end;


create or replace procedure WebSvcProc_Bestelling_BestelRegel_Wijzigen
(
  in @BestelNummer                    numeric(10,0) ,
