  end if;

  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790,    _U('Optie Voorraad'));         // (20790) '%1!' niet geactiveerd!
  end if;

  // King webservices V2 kapt automatisch invoer af op de bij de paramater gespecifieerde lengte
  // we hebben die parameters nu extr alengte gegeven, en testen deie parameters op echte maximumlengte

  if (@RegelNummer is not null) and (@RegelNummer not between 1 and 999) then
    call Raise(20700, _U('%1!, minimaal %2!, maximaal %3! toegestaan.', 'RegelNummer', '1', '999')); // Ongeldige waarde: %1
  end if;

  if length(@InkoopEenheid) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'InkoopEenheid', '20')); // Ongeldige waarde: %1
  end if;

  if length(@ArtikelNummerLeverancier) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'ArtikelNummerLeverancier', '20')); // Ongeldige waarde: %1
  end if;

  if length(@EanCode) > 30 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'EanCode', '30')); // Ongeldige waarde: %1
  end if;

  if length(@PartijNummer) > 20 then
    call Raise(20700, _U('%1!, maximaal %2! tekens toegestaan.', 'PartijNummer', '20')); // Ongeldige waarde: %1
  end if;


  // Nu gaat het echte werk beginnen...
  // T.b.v. specificatieregel  zijn de nummers nodig, zie verderop in de code.
  begin
    declare @dummyBestelNummer      numeric(10,0);
