create or replace procedure WebSvcProc_Bestelling_LockVrijgeven(
  in @BestelNummer numeric(10,0)
)
begin
  // **************** Beschrijving *************************
  // * Controleer of de bestelling bestaat en, zo ja,
  // * verwijder dan een eventuele lock die door gebruiker
  // * KingWebservice op de bestelling is gezet
  // *******************************************************

  // variabelen
  declare @_BstKopGid   integer;
  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabBestelKop';

  // ingangscontroles (licentie, opties, abonnement...)
  if IsModuleActive('be') = 0 then
    call Raise(20790,    _U('Optie Bestelling'));    // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken Bestelling
  select BstKopGid into @_BstKopGid
  from   tabBestelKop
  where  BstKopNummer = @BestelNummer;
  if @_BstKopGid is null then
    call Raise(20720,    'BestelNummer');        // (20720) niet gevonden: %1!
  end if;

  //Lock vrijgeven
  call WebSvcHulpProc_Bestelling_LockVrijgeven(@BestelNummer, @_BstKopGid);

  //call TraceEind('WebSvcProc_Bestelling_LockVrijgeven');
end;


