create or replace procedure WebSvcProc_Bestelling_Toevoegen(
  in @MagazijnCode            numeric(3,0)  ,
  in @LeverancierNummer       nchar(11)     ,   // langer dan maximaal 10, ivm afkapgedrag van King Webservices V2
  //in @LeverancierEanCode      nchar(14)     ,   // idem, GLN code is 13 tekens, en voorloopnullen tellen mee...
  in @InkoperNummer           numeric(3,0)  ,   // conditioneel
  // hieronder de optionele velden
  in @BestelNummer            numeric(10,0) ,
  in @ValutaCode              nchar(3)      ,
  in @BestelDatum             date          ,
  in @BestelTijd              time          ,
  in @OntvangstDatum          date          ,
  in @Referentie              long nvarchar ,
  in @BestelAdres             nchar(4)      ,   // vaste waarden: "COR" (default), "VEST", of "BEST"
  in @BestelAdresNummer       numeric(3,0)  ,
  in @ContactPersoonNummer    numeric(3,0)  ,
  in @BetalingsConditieNummer numeric(3,0)  ,
  in @LeveringsConditieNummer numeric(3,0)  ,
  in @Opmerking               long nvarchar ,
  in @BestellingGoedgekeurd   smallint,          // Waarden: 0=niet (default) , 1=wel, leeg=volgens vaste gegevens
  in @EmailExtraTekst         long nvarchar default null
)
result(
  BestelNummer                numeric(10,0)
)
begin
  declare @LeverancierEanCode nchar(14); // Wordt niet als parameter opgenomen

  declare @_NawFilNummer      nchar(11);

  // interne variabelen, nodig om m.b.v. de bovenstaande parameters
  // een bestelkop in te vullen
  declare @_BstKopGid                         integer;
  declare @_BstKopMagGid                      integer;
  declare @_BstKopNawGid                      integer;
  declare @_BstKopNummer                      numeric(10,0);
  declare @_BstKopIsGoedgekeurd               smallint;
  declare @_BstKopGoedgekeurdDoor             nchar(40);
  declare @_BstKopGoedgekeurdOp               timestamp;
  declare @_BstKopIsVerwerkt                  smallint;
  declare @_BstKopVerwerktDoor                nchar(40);
  declare @_BstKopVerwerktOp                  timestamp;
  declare @_BstKopIsVolledigGeboekt           smallint;
  declare @_BstKopLaatstGeboektDoor           nchar(40);
  declare @_BstKopLaatstGeboektOp             timestamp;
  declare @_BstKopIsVolledigOntvangen         smallint;
  declare @_BstKopLaatstOntvangenDoor         nchar(40);
  declare @_BstKopLaatstOntvangenOp           timestamp;
  declare @_BstKopBestelDatum                 date;
  declare @_BstKopBestelTijd                  time;
  declare @_BstKopValNummer                   integer;
  declare @_BstKopBestelAdresSoort            smallint;
  declare @_BstKopAdrGid                      integer;
  declare @_BstKopBtcNummer                   integer;
  declare @_BstKopLvcNummer                   integer;
  declare @_BstKopOpm                         long nvarchar;
  declare @_BstKopReferentie                  long nvarchar;
  declare @_BstKopAanmaakDatum                timestamp;
  declare @_BstKopRelGidInkoper               integer;
  declare @_BstKopRelGid                      integer;
  // gegevens aflevering...
  declare @_BstKopAfleverDatum                date;         // dit is ontvangstdatum in geval van magazijnontvangst)
  declare @_BstKopAfleverAdresNAW             smallint;
  declare @_BstKopNawGidAflevering            integer;
  declare @_BstKopAdrGidAflevering            integer;
  declare @_BstKopRelGidAflevering            integer;

  // constanten
  declare _NAWBESTAND                         nchar(3)        = 'C';          //Bestelling toevoegen is momenteel beperkt tot alleen crediteuren.


  // Initialisatie...
  set @_BstKopAanmaakDatum        = now();
  set @_BstKopIsVerwerkt          = 0;
  set @_BstKopVerwerktOp          = null;
  set @_BstKopVerwerktDoor        = null;
  set @_BstKopIsVolledigGeboekt   = 0;
  set @_BstKopLaatstGeboektDoor   = null;
  set @_BstKopLaatstGeboektOp     = null;
  set @_BstKopIsVolledigOntvangen = 0;
  set @_BstKopLaatstOntvangenDoor = null;
  set @_BstKopLaatstOntvangenOp   = null;

  set @_BstKopOpm                 = trim(@Opmerking);


  // Directe leveringen (bij een debiteur) doen we hier momenteel niet...
  set @_BstKopAfleverAdresNAW   = null;
  set @_BstKopNawGidAflevering  = null;
  set @_BstKopAdrGidAflevering  = null;
  set @_BstKopRelGidAflevering  = null;


  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen bestelling actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('be') = 0 then
    call Raise(20790,    _U('Optie Bestelling'));    // (20790) '%1!' niet geactiveerd!
  end if;

  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790,    _U('Optie Voorraad'));         // (20790) '%1!' niet geactiveerd!
  end if;

  // controle te lange strings (afkap gedrag King Webservices V2 ondervangen)
  // Leveranciernummer
  begin

    set @_NawFilNummer = trim(isnull(@Leveranciernummer, ''));

    if length(@_NawFilNummer) > 10 then
      call Raise(20700 , _U('%1!, maximaal %2! tekens toegestaan.', 'Leveranciernummer', '10')) ; // Ongeldige waarde: %1!
    end if;

    // De procedure voor aanmaken bestelkopo accepteert zowel Leveranciersnummer als EAN,
    // maar EAN wordt nu even niet meegegeven.
    // Dus nu even vooraf testen dat men LeverancierNummer heeft ingeveuld.
    if (@_NawFilnummer = '') then
      call Raise(20700 , _U('%1! is verplicht.', 'Leveranciernummer')) ; // Ongeldige waarde: %1!
    end if;
  end;

  // **********************************
  // *** controle verplichte velden ***
  // **********************************
  // Magazijncode
  set @_BstKopMagGid = (select MagGid from tabMagazijn where MagCode = @MagazijnCode );
  if @_BstKopMagGid is null then
    call Raise(20700, 'MagazijnCode') ; // Ongeldige waarde: %1
  end if;

  // Leverancier
  begin
    // Nummer of EAN valideren
    call WebSvcHulpProc_ValideerLeverancierNummerOfEan(/*in*/ @LeverancierNummer, @LeverancierEanCode, /*out*/ @_BstKopNawGid );

    // Leverancier geblokkeerd voor bestellen?
    // Van een leverancier hoeven trouwens geen inkoopgegevens aanwezig te zijn (vinkje in King GUI)...
    if exists (select first 1 from tabLeverancierGegevens where LevGegNawGid = @_BstKopNawGid and LevGegBestellenGeblokkeerd <> 0) then
      call Raise(20780, _U('Toevoegen'), _U('leverancier is geblokkeerd voor bestellingen')) ;  // (20780) <Actie> niet mogelijk: <Reden>.
    end if;
  end;

  // ***************************
  // *** Conditionele velden ***
  // ***************************
  // Inkoper is voorwaardelijk.
  call WebSvcHulpProc_Bestelling_ValideerInkoper( @_BstKopNawGid, @InkoperNummer, @_BstKopRelGidInkoper);

  // ********************************
  // *** Overige optionele velden ***
  // ********************************

  // ContactPersoon
  if @ContactPersoonNummer is not null then
    set @_BstKopRelGid = ( select RelGid from tabRelatie where RelNawGid = @_BstKopNawGid and RelNummer = @ContactPersoonNummer );
    if (@_BstKopRelGid is null) then
        call Raise(20720, 'ContactPersoonNummer');  // %1 niet gevonden!
    end if;
  end if;

  // Referentie, BestelDatum en OntvangstDatum/AfleverDatum
  select  case VgbDefBestelDatum
            when 2 then null                // 2 = leeg
            when 1 then @@VerwerkingsDatum  // 1 = verwerkingsdatum
            when 0 then date(now())         // 0 = systeemdatum
            else null
          end case,
          null,                             // King GUI laat bij alle soorten besteldatums het rubriek besteltijd leeg.
          case VgbDefAfleverDatumKop
            when 3 then null                // 3 = leeg
            when 1 then @@VerwerkingsDatum  // 1 = verwerkingsdatum
            when 0 then date(now())         // 0 = systeemdatum
            else null                       // leeg, of ander onbekend optie
          end case,
          VgbDefStatus,
          isnull( nullif(trim(@Referentie),''), vgbDefReferentie ) // Referentie: indien niet opgegeven, overnemen uit vaste gegevens
    into  @_BstKopBestelDatum,
          @_BstKopBestelTijd,
          @_BstKopAfleverDatum,
          @_BstKopIsGoedgekeurd,
          @_BstKopReferentie
  from  tabVasteGegevensBestellingen;

  // BestelDatum
  if ( @BestelDatum is not null ) then
    set @_BstKopBestelDatum = @BestelDatum;
  end if;

  if ( @BestelTijd is not null ) then
    set @_BstKopBestelTijd = @BestelTijd;
  end if;

  // OntvangstDatum ==> is voor magazijn
  // In geval van debiteur is het een afleverdatum, dan wordt OntvangstDatum als afleverdatum beschouwd.
  if @OntvangstDatum is not null then
    set @_BstKopAfleverDatum = ( select first @OntvangstDatum from tabBoekjaar where ( BjAfsluiting <> 2 ) and @OntvangstDatum between BjBeginDatum and BjEindDatum );
    // boekjaar is definitief afgesloten, of er is geen boekjaar bekend (datum is in geen enkel boekjaar)
    if @_BstKopAfleverDatum is null then
      call Raise(20700, _U('Ontvangst op %1! boeken kan niet, er is geen boekjaar die open is', string(@OntvangstDatum))) ; // Ongeldige waarde: %1
    end if;
  end if;

  // Goedgekeurd: 0 = niet (default), 1 = wel, leeg = volgens vaste gegevens
  if @BestellingGoedgekeurd is not null then
    // Als null, dan volgens vaste gegevens (is al eerder opgevraagd)
    if @BestellingGoedgekeurd in (0 /*Niet goedgekeurd*/, 1 /*Wel goedgekeurd*/) then
      set @_BstKopIsGoedgekeurd = @BestellingGoedgekeurd;
    else
      call Raise(20700, 'BestellingGoedgekeurd'); // Ongeldige waarde: %1
    end if;
  end if;



  // Betalingsconditie
  // Is die bij leverancier niet ingevuld, dan de default voor ale crediteuren
  begin
    set @_BstKopBtcNummer = isnull( ( select NawFilBtcNummer from tabNawFile where NawFilNawGid = @_BstKopNawGid and NawFilFonId = _NAWBESTAND )
                                  , ( select FonBtcNummer from tabFileOfNaw where FonId = _NAWBESTAND ) );

    if @BetalingsConditieNummer is not null then
      set @_BstKopBtcNummer = (  select BtcNummer from tabBetalingsConditie where BtcNummer = @BetalingsConditieNummer );
      if @_BstKopBtcNummer is null then
        call Raise(20700, 'BetalingsConditieNummer'); // Ongeldige waarde: %1
      end if;
    end if;
  end ; //Betalingsconditie

  // Leveringsconditie
  // Is die bij leverancier niet ingevuld, dan de default voor ale crediteuren
  begin
    set @_BstKopLvcNummer = isnull( ( select NawFilLvcNummer from tabNawFile where NawFilNawGid = @_BstKopNawGid and NawFilFonId = _NAWBESTAND )
                                  , ( select FonLvcNummer from tabFileOfNaw where FonId = _NAWBESTAND ) );

    if @LeveringsConditieNummer is not null then
      set @_BstKopLvcNummer = (  select LvcNummer from tabLeveringsConditie where LvcNummer = @LeveringsConditieNummer );
      if @_BstKopLvcNummer is null then
        call Raise(20700, 'LeveringsConditieNummer'); // Ongeldige waarde: %1
      end if;
    end if;
  end ; //Leveringsconditie


  // Valuta
  call WebSvcHulpProc_ValideerNawValuta(/*in*/ @ValutaCode, @_BstKopNawGid, /*out*/ @_BstKopValNummer, null /*valutacode */ );

  // BestelAdres
  call WebSvcHulpProc_ValideerBestelAdresBestelling( /*in*/ @_BstKopNawGid, @BestelAdres, @BestelAdresNummer,  /*out */ @_BstKopBestelAdresSoort, @_BstKopAdrGid);

  // overige ingevulde velden overnemen
  set @_BstKopOpm         = trim(@Opmerking);

  // BestelNummer -
  // dit doen we op laatste moment, een gegenereerd nummer kan niet opnieuw gebruikt worden.
  set @_BstKopNummer = @BestelNummer;
  // opgegeven nummer mag niet al bestaan...
  set @_BstKopGid = (select BstKopGid from tabBestelKop where BstKopNummer = @_BstKopNummer);
  if @_BstKopGid is not null then
    call Raise(20721, string('BestelNummer ', @BestelNummer)); // %1 komt al voor!
  end if;

  // Geen nummer gespecifieerd? genereer er een...
  if ( isnull(@_BstKopNummer, 0) = 0 ) then
    call BestellingGenereerNieuwBestellingnummer( 1 /* Forceer*/, -1 /*startnr, -1=Genereren*/, @_BstKopNummer); // King 5 procedure. Er moet een eerstvolgende vrije nummer worden uitgedeeld.
  end if;

  // ******************************
  // Maak nu de Bestelling aan...
  // ******************************
  begin atomic // Dit moet, want lock moet hierna nog erop en daar kan het nog fout gaan
    insert into tabBestelKop (
      BstKopMagGid,
      BstKopNawGid,
      BstKopNummer,
      BstKopIsGoedgekeurd,
      BstKopGoedgekeurdDoor,
      BstKopGoedgekeurdOp,
      BstKopIsVerwerkt,
      BstKopVerwerktDoor,
      BstKopVerwerktOp,
      BstKopIsVolledigGeboekt,
      BstKopLaatstGeboektDoor,
      BstKopLaatstGeboektOp,
      BstKopIsVolledigOntvangen,
      BstKopLaatstOntvangenDoor,
      BstKopLaatstOntvangenOp,
      BstKopBestelDatum,
      BstKopBestelTijd,
      BstKopValNummer,
      BstKopBestelAdresSoort,
      BstKopAdrGid,
      BstKopBtcNummer,
      BstKopLvcNummer,
      BstKopOpm,
      BstKopReferentie,
      BstKopAanmaakDatum,
      BstKopRelGidInkoper,
      BstKopRelGid,
      BstKopAfleverDatum,
      BstKopAfleverAdresNAW,
      BstKopNawGidAflevering,
      BstKopAdrGidAflevering,
      BstKopRelGidAflevering,
      BstKopEmailExtraTekst,
      BstKopLastModified
    )
    values (
      @_BstKopMagGid,
      @_BstKopNawGid,
      @_BstKopNummer,
      @_BstKopIsGoedgekeurd,
      @_BstKopGoedgekeurdDoor,
      @_BstKopGoedgekeurdOp,
      @_BstKopIsVerwerkt,
      @_BstKopVerwerktDoor,
      @_BstKopVerwerktOp,
      @_BstKopIsVolledigGeboekt,
      @_BstKopLaatstGeboektDoor,
      @_BstKopLaatstGeboektOp,
      @_BstKopIsVolledigOntvangen,
      @_BstKopLaatstOntvangenDoor,
      @_BstKopLaatstOntvangenOp,
      @_BstKopBestelDatum,
      @_BstKopBestelTijd,
      @_BstKopValNummer,
      @_BstKopBestelAdresSoort,
      @_BstKopAdrGid,
      @_BstKopBtcNummer,
      @_BstKopLvcNummer,
      @_BstKopOpm,
      @_BstKopReferentie,
      @_BstKopAanmaakDatum,
      @_BstKopRelGidInkoper,
      @_BstKopRelGid,
      @_BstKopAfleverDatum,
      @_BstKopAfleverAdresNAW,
      @_BstKopNawGidAflevering,
      @_BstKopAdrGidAflevering,
      @_BstKopRelGidAflevering,
	  @EmailExtraTekst,
      now()
    );
    set @_BstKopGid = @@Identity;

    // Aangemaakt bestelling meteen in gebruik nemen. Lukt dat niet: abort
    call WebSvcHulpProc_BestellingExclusiefLocken(@_BstKopGid);

    // Vrije rubrieken vullen van de defaults en vd crediteur overnemen naar order
    call VrijeRubriekenVulDefaults('BST', 0, 0, @_BstKopGid);
    call BestellingOvernemenVrijeRubrieken(@_BstKopGid);
  end; //atomic

  // resultaat terug geven
  select  BstKopNummer  as BestelNummer
  from    tabBestelKop
  where   BstKopGid = @_BstKopGid;

end;


create or replace procedure WebSvcProc_Bestelling_Verwerken(
  in @BestelNummer numeric(10,0) default null,
  in @InclusiefBestelbrief nchar(3) default 'NEE' /*'JA', 'NEE'*/
  )
begin
  //Constanten
  declare _JobIVSoort integer = 90; // 90 = bestellingen (Dit nummer is gereserveerd. Hier is geen impSoort voor)

  declare @_BstKopGid integer;
  declare @_BstKopNawGid integer;

  declare @_LockUserNaam nchar(40) = 'KingWebservice';

  //call TraceBegin('WebSvcProc_Bestelling_Verwerken');

  //Module: is er geen bestelling actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('be') = 0 then
    call Raise(20790, _U('Optie Bestelling')); //(20790) '%1!' niet geactiveerd!
  end if;

  //Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790, _U('Optie Voorraad')); //(20790) '%1!' niet geactiveerd!
  end if;

  //*** Test (status) bestelling ***
  begin
    declare @_BstKopIsGoedgekeurd smallint;
    declare @_BstKopIsVerwerkt smallint;

    // Opzoeken Bestelling
    select BstKopGid,
           BstKopNawGid,
           isnull(BstKopIsGoedgekeurd,0),
           isnull(BstKopIsVerwerkt,0)
      into @_BstKopGid,
           @_BstKopNawGid,
           @_BstKopIsGoedgekeurd,
           @_BstKopIsVerwerkt
    from tabBestelKop
    where BstKopNummer = @BestelNummer;

    if @_BstKopGid is null then
      call Raise(20720, 'BestelNummer'); //(20720) niet gevonden: %1!
    end if;

    // --- Niet al verwerkt?...
    if ( @_BstKopIsVerwerkt <> 0 ) then
      call Raise(20780, _U('Bestelling verwerken'),_U('bestelling is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    // --- nog niet GoedGekeurd...
    if ( @_BstKopIsGoedgekeurd = 0 ) then
      call Raise(20780, _U('Bestelling verwerken'),_U('bestelling is niet goedgekeurd')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;
  end;

  // --- Bestelling zonder regels niet verwerken.
  if not exists ( select first 1 from tabBestelRegel where BstRglBstKopGid = @_BstKopGid ) then
    call Raise(20780, _U('Bestelling verwerken'),_U('er zijn geen bestelregels')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if (@InclusiefBestelbrief = 'JA') then
    //Inclusief bestelbrief. Ga de jobscript vullen
    //Bestelling aanmelden voor verwerking
    if exists(select first 1 from tabJobImportVerwerking where JobivImportRecordGid = @_BstKopGid and JobivSoort = _JobIVSoort) then
      call Raise(20780, _U('Bestelling verwerken'),_U('een King job is al met verwerken bezig')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    //Bij de king Job hoort een jobscript die de te verwerken bestellingen uit tab_WebSvc_BestellingVerwerken moet halen.
    if exists(select first 1 from tab_WebSvc_BestellingVerwerken where BsvBstKopGid = @_BstKopGid) then
      call Raise(20780, _U('Bestelling verwerken'),_U('staat al klaar voor verwerking door een KING job')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    //Bestelling voor verwerking door een King job aanmelden
    insert into tab_WebSvc_BestellingVerwerken(BsvBstKopGid) values (@_BstKopGid);

    // lock weer vrijgeven.
    // De King Job die de echte verwerking doet zorgt zelf voor de locking.
    call WebSvcProc_Bestelling_LockVrijgeven(@BestelNummer);
  else
  begin atomic //Zet in afdrukverslag voor bestellingen dat er geen bestelbrief is aangemaakt.
    declare @_AvkGid integer;

    //Er zijn bestelregels waarbij de specificatieregels niet overeenkomen
    if exists(select 1 from tabBestelRegel where BstRglBstKopGid = @_BstKopGid and BstRglTotaalAantalSpecRegelsKomtOvereen = 0) then
      call Raise(20780, _U('Bestelling verwerken'),_U('aantallen van specificatieregels komen niet overeen met de bestelregel')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    // Bestelling eerst locken. Lukt dat niet: abort
    call WebSvcHulpProc_BestellingExclusiefLocken(@_BstKopGid);

    // zet de bestelling op verwerkt (administratief)
    // er wordt hiermee geen bestelbrief gemaakt en ook niet opgestuurd (per e-mail of post). dat moet men toch vanuit King GUI doen.
    update tabBestelKop
      set BstKopIsVerwerkt = 1,
          BstKopVerwerktDoor = @_LockUserNaam,  // 30-03-2020: dit werkt niet, in King GUI zien we KingSystem als naam staan.
          BstKopVerwerktOp = now()
    where BstKopGid = @_BstKopGid ;

    //Kop
    insert into tabAfdrukVerslagKop with auto name
    select 120 /*bestelbrief*/ as AvkDocumentSoort,
           @_LockUserNaam as AvkAangemaaktDoor,
           now() as avkDatumTijd;

    set @_AvkGid = @@Identity;

    //Documentregel
    insert into tabAfdrukVerslagRegel with auto name
    select  @_AvkGid as AvrAvkGid,
            1 as AvrAfdrukGelukt,
            @BestelNummer as AvrDocumentNr,
            (select NawFilNummer from tabNawFile where NawFilNawGid = @_BstKopNawGid and NawFilFonId = 'C') as AvrNawNr,
            0 as AvrRegelSoort,
            null as AvrUitVoerType,
            _U('Geen bestelbrief, verwerking is uitgevoerd door webservice') as AvrRedenNietGelukt,
            'C' as AvrNawFonId,
            now() as AvrLAstModified;
  end // atomic
  end if;

  //call TraceEind('WebSvcProc_Bestelling_Verwerken');
end;


create or replace procedure WebSvcProc_Bestelling_Verwijderen(
  in @BestelNummer numeric(10,0)
)
begin
  // *** ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen bestelling actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('be') = 0 then
    call Raise(20790, _U('Optie Bestelling')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790, _U('Optie Voorraad'));   // (20790) '%1!' niet geactiveerd!
  end if;

  begin Atomic // Al snel atomic ivm lock van de bestelling
    declare @_BstKopGid  integer;
    declare @_BstKopIsVerwerkt smallint;
    declare @_BstKopIsVolledigOntvangen smallint;

    // **************************
    // *** Controle verplichte velden
    // **************************

    // --- Bestaat de opgegeven bestelling?
    set @_BstKopGid = null;
    select BstKopGid, BstKopIsVerwerkt, BstKopIsVolledigOntvangen
    into   @_BstKopGid, @_BstKopIsVerwerkt, @_BstKopIsVolledigOntvangen
    from   tabBestelKop
    where  BstKopNummer = @BestelNummer;

    if (@_BstKopGid is null) then
      call Raise(20720, 'BestelNummer'); // (20720) niet gevonden: %1!
    end if;

    // *** Regel verwijderen
    call WebSvcHulpProc_BestellingExclusiefLocken(@_BstKopGid);

    // Controleer status van de bestelling: Mag niet als al is verwerkt
    //if @_BstKopIsVerwerkt = 0 then
    //  raiserror 20760, _U('De bestelling is nog niet verwerkt') //(20760) Ongeldige status: %1!
    //end if;
    //
    //if @_BstKopIsVolledigOntvangen = 0 then
    //  raiserror 20760, _U('De bestelling is nog niet volledig ontvangen') //(20760) Ongeldige status: %1!
    //end if;
    //
    //// Controleer status van de bestelling: Mag niet worden verwijderd als de bestelling wijst naar een verkooporderregel
    //if exists (select first 1
    //           from tabBestelRegel
    //                inner join tabBestelRegelDetail on (brdBstRglGid = BstRglGid and BstRglBstKopGid = @_BstKopGid)
    //           where BrdOrrGid is not null) then
    //  raiserror 20760, _U('De bestelling heeft regels voor verkooporders') //(20760) Ongeldige status: %1!
    //end if;
    delete tabBestelKop where BstKopGid = @_BstKopGid;

    call WebSvcHulpProc_Bestelling_LockVrijgeven(@BestelNummer, @_BstKopGid);
  end;
end;


create or replace procedure WebSvcProc_Bestelling_VrijeRubriek_Wijzigen(
  in @BestelNummer        numeric(10,0),
  in @RubriekOmschrijving nchar(40),
  in @RubriekInhoud       nchar(255)
)
begin
  declare @_BstKopGid     integer;

  set @@ErrorTextProcedure =  'WebSvcProc_Bestelling_VrijeRubriek_Wijzigen > @BestelNummer = ' + String(@BestelNummer) +
                              ' @RubriekOmschrijving = ' + String(@RubriekOmschrijving);
  //call TraceBegin(@@ErrorTextProcedure);

  if IsModuleActive('be') = 0 then
    call Raise(20790, _U('Optie Bestelling')); // (20790) '%1!' niet geactiveerd!
  end if;

  // BestelKop Gid opvragen
  set @_BstKopGid = (select BstKopGid from tabBestelKop where BstKopNummer = @BestelNummer );
  if (@_BstKopGid is null) then
    call Raise(20720, 'BestelNummer');          // (20720 %1 niet gevonden!
  end if;

  begin atomic
    // Bestelling locken als dat nog niet het geval is.
    call WebSvcHulpProc_BestellingExclusiefLocken(@_BstKopGid, 'KingWebService', @@SpId, @@LoginTime);

    // Vrije rubriek aanpassen
    call VrInsertOrReplaceValue('BST', 0, 0,  @_BstKopGid, @RubriekOmschrijving, @RubriekInhoud);

  end; // atomic

  set @@ErrorTextProcedure = 'WebSvcProc_Bestelling_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Bestelling_Wijzigen
( in @BestelNummer numeric(10,0) default null,
  in @MagazijnCode numeric(3,0) default null,
  in @InkoperNummer numeric(3,0) default null, //conditioneel
  in @ValutaCode nchar(3) default null,
  in @BestelDatum date default null,
  in @BestelTijd time default null,
  in @OntvangstDatum date default null,
  in @Referentie long nvarchar default null,
  in @BestelAdres nchar(4) default null,   //vaste waarden: "COR" , "VEST" of "BEST"
  in @BestelAdresNummer numeric(3,0) default null,
  in @ContactPersoonNummer numeric(3,0) default null,
  in @BetalingsConditieNummer numeric(3,0) default null,
  in @LeveringsConditieNummer numeric(3,0) default null,
  in @Opmerking long nvarchar default null,
  in @BestellingGoedgekeurd smallint default null, //Waarden: 0=niet (default) , 1=wel
  in @BestellingVerwerkt smallint default null,
  in @EmailExtraTekst long nvarchar default null
)
begin
  //Constanten
  declare @_qcJA smallint = 1;
  declare @_qcNEE smallint = 0;
  //Variabelen
  declare @_BstKopBestelDatum date;
  declare @_BstKopBestelTijd time;
  declare @_BstKopGid integer;
  declare @_BstKopMagGid integer;
  declare @_BstKopNawGid integer;
  declare @_BstKopNummer numeric(10,0);
  declare @_BstKopIsGoedgekeurd smallint;
  declare @_BstKopIsVerwerkt smallint;
  declare @_BstKopValNummer integer;
  declare @_BstKopIsVolledigOntvangen smallint;
  declare @_OudeValNummer integer;
  declare @_BstKopBestelAdresSoort smallint;
  declare @_BstKopAdrGid integer;
  declare @_BstKopBtcNummer integer;
  declare @_BstKopLvcNummer integer;
  declare @_BstKopOpm long nvarchar;
  declare @_BstKopReferentie long nvarchar;
  declare @_BstKopRelGidInkoper integer;
  declare @_BstKopRelGid integer;
  declare @_BstKopAfleverDatum date; // dit is ontvangstdatum in geval van magazijnontvangst)
  declare @_EmailExtraTekst long nvarchar;

//------------------
//  declare @test long nvarchar;
//  set @test ='@BestelNummer='||@BestelNummer
//||'; @MagazijnCode='||@MagazijnCode
//||'; @InkoperNummer='||@InkoperNummer
//||'; @ValutaCode='||@ValutaCode
//||'; @BestelDatum='||@BestelDatum
//||'; @BestelTijd='||@BestelTijd
//||'; @OntvangstDatum='||@OntvangstDatum
//||'; @Referentie='||@Referentie
//||'; @BestelAdres='||@BestelAdres
//||'; @BestelAdresNummer='||@BestelAdresNummer
//||'; @ContactPersoonNummer='||@ContactPersoonNummer
//||'; @BetalingsConditieNummer='||@BetalingsConditieNummer
//||'; @LeveringsConditieNummer='||@LeveringsConditieNummer
//||'; @Opmerking='||@Opmerking
//||'; @BestellingGoedgekeurd='||@BestellingGoedgekeurd
//||'; @BestellingVerwerkt='||@BestellingVerwerkt
//;
//  if exists(select first 1 from tabregistry where regkey='logtest') then
//    update tabRegistry
//    set contents=@test
//    where regkey='logtest';
//  else
//    insert into tabRegistry(RegKey,SoortVeld, Contents)
//    values('logtest', 0, @test);
//  end if;
//  commit;
//------------------



  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen bestelling actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('be') = 0 then
    call Raise(20790, _U('Optie Bestelling')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen Bestellingen doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790, _U('Optie Voorraad')); // (20790) '%1!' niet geactiveerd!
  end if;

  //Lees voor het aanpassen alle bestaande velden in. Alleen de opgegeven velden worden gewijzigd.
  select
    BstKopAdrGid,
    BstKopAfleverDatum,
    BstKopBestelAdresSoort,
    BstKopBestelDatum,
    BstKopBestelTijd,
    BstKopBtcNummer,
    BstKopGid,
    BstKopIsGoedgekeurd,
    BstKopIsVerwerkt,
    BstKopIsVolledigOntvangen,
    BstKopLvcNummer,
    BstKopMagGid,
    BstKopNawGid,
    BstKopNummer,
    BstKopOpm,
    BstKopReferentie,
    BstKopRelGid,
    BstKopRelGidInkoper,
    BstKopValNummer,
    BstKopEmailExtraTekst
  into
    @_BstKopAdrGid,
    @_BstKopAfleverDatum,
    @_BstKopBestelAdresSoort,
    @_BstKopBestelDatum,
    @_BstKopBestelTijd,
    @_BstKopBtcNummer,
    @_BstKopGid,
    @_BstKopIsGoedgekeurd,
    @_BstKopIsVerwerkt,
    @_BstKopIsVolledigOntvangen,
    @_BstKopLvcNummer,
    @_BstKopMagGid,
    @_BstKopNawGid,
    @_BstKopNummer,
    @_BstKopOpm,
    @_BstKopReferentie,
    @_BstKopRelGid,
    @_BstKopRelGidInkoper,
    @_BstKopValNummer,
    @_EmailExtraTekst
  from tabBestelKop
  where BstKopNummer = @BestelNummer;

  if @_BstKopGid is null then
    call Raise(20720, string('BestelNummer ', @BestelNummer)); // (20720) niet gevonden: %1!
  end if;

  //Verwerkt
  if @BestellingVerwerkt is not null then
    if @BestellingVerwerkt in (0 /*Niet verwerkt*/, 1 /*Wel verwerkt*/) then
      if (@BestellingVerwerkt = @_qcNEE) and (@_BstKopIsVerwerkt = @_qcja) then
        set @_BstKopIsVerwerkt = @BestellingVerwerkt;
      end if;
    else
      call Raise(20700, 'BestellingVerwerkt'); // Ongeldige waarde: %1
    end if;
  else
    set @BestellingVerwerkt = @_BstKopIsVerwerkt;
  end if;

  //Goedgekeurd: 0 = niet, 1 = wel
  if @BestellingGoedgekeurd is not null then
    if @BestellingGoedgekeurd in (0 /*Niet goedgekeurd*/, 1 /*Wel goedgekeurd*/) then
      if @_BstKopIsVerwerkt = @_qcJA and (@_BstKopIsGoedgekeurd <> @BestellingGoedgekeurd) then
        call Raise(20780 , _U('%1! wijzigen is', 'BestellingGoedgekeurd'),_U('De bestelling is reeds verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
      end if;
      if @_BstKopIsVolledigOntvangen = @_qcJA and (@_BstKopIsGoedgekeurd <> @BestellingGoedgekeurd) then
        call Raise(20780 , _U('%1! wijzigen is', 'BestellingGoedgekeurd'),_U('De bestelling is reeds volledig ontvangen')); // <Actie> niet mogelijk. Reden: <Reden>.
      end if;

      set @_BstKopIsGoedgekeurd = @BestellingGoedgekeurd;
    else
      call Raise(20700, 'BestellingGoedgekeurd'); // Ongeldige waarde: %1
    end if;
  end if;

  //BestelDatum
  if ( @BestelDatum is not null ) and @BestelDatum > '1900-01-01' then
    set @_BstKopBestelDatum = @BestelDatum;
  end if;

  //BestelTijd
  if ( @BestelTijd is not null ) then
    set @_BstKopBestelTijd = @BestelTijd;
  end if;

  //OntvangstDatum
  if @OntvangstDatum is not null and @OntvangstDatum > '1900-01-01' then
    set @_BstKopAfleverDatum = ( select first @OntvangstDatum from tabBoekjaar where ( BjAfsluiting <> 2 ) and @OntvangstDatum between BjBeginDatum and BjEindDatum );
    // boekjaar is definitief afgesloten, of er is geen boekjaar bekend (datum is in geen enkel boekjaar)
    if @_BstKopAfleverDatum is null then
      call Raise(20700, _U('Ontvangst op %1! boeken kan niet, er is geen boekjaar die open is', string(@OntvangstDatum))) ; // Ongeldige waarde: %1
    end if;
  end if;

  // Magazijncode
  if @MagazijnCode is not null then
    set @_BstKopMagGid = (select MagGid from tabMagazijn where MagCode = @MagazijnCode );
    if @_BstKopMagGid is null then
      call Raise(20700, 'MagazijnCode') ; // Ongeldige waarde: %1
    end if;

    if @_BstKopIsVerwerkt = @_qcJA then
      call Raise(20780 , _U('Magazijn wijzigen'),_U('De bestelling is reeds verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;
  end if;

  //Inkoper
  if @InkoperNummer is not null then
    call WebSvcHulpProc_Bestelling_ValideerInkoper( @_BstKopNawGid, @InkoperNummer, @_BstKopRelGidInkoper);
  end if;

  //ValutaCode
  if isnull(@ValutaCode, '') <> '' then
    set @_OudeValNummer = @_BstKopValNummer;
    call WebSvcHulpProc_ValideerNawValuta(/*in*/ @ValutaCode, @_BstKopNawGid, /*out*/ @_BstKopValNummer, null /*valutacode */ );

    if (@_BstKopIsVerwerkt = @_qcJA) and (@_OudeValNummer <> @_BstKopValNummer) then
      call Raise(20780 , _U('Valutacode wijzigen'),_U('De bestelling is reeds verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

  end if;

  //Referentie
  if @Referentie is not null then
    set @_BstKopReferentie = trim(@Referentie);
  end if;

  //BestelAdres
  if (isnull(@BestelAdres, '') <> '') or (@BestelAdresNummer is not null) then
    if @_BstKopIsVerwerkt = @_qcJA then
      call Raise(20780 , _U('Besteladres wijzigen'),_U('De bestelling is reeds verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    call WebSvcHulpProc_ValideerBestelAdresBestelling( /*in*/ @_BstKopNawGid, @BestelAdres, @BestelAdresNummer,  /*out */ @_BstKopBestelAdresSoort, @_BstKopAdrGid);
  end if;

  //Contactpersoon
  if @ContactPersoonNummer is not null then
    if @_BstKopIsVerwerkt = @_qcJA then
      call Raise(20780 , _U('Contactpersoon wijzigen'),_U('De bestelling is reeds verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    set @_BstKopRelGid = (select RelGid from tabRelatie where RelNawGid = @_BstKopNawGid and RelNummer = @ContactPersoonNummer);
    if (@_BstKopRelGid is null) then
      call Raise(20720, 'ContactPersoonNummer');  // %1 niet gevonden!
    end if;
  end if;

  //Betalingsconditie
  if @BetalingsConditieNummer is not null then
    if @_BstKopIsVerwerkt = @_qcJA then
      call Raise(20780 , _U('Betalingsconditie wijzigen'),_U('De bestelling is reeds verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    set @_BstKopBtcNummer = (select BtcNummer from tabBetalingsConditie where BtcNummer = @BetalingsConditieNummer);
    if @_BstKopBtcNummer is null then
      call Raise(20700, 'BetalingsConditieNummer'); // Ongeldige waarde: %1
    end if;
  end if;

  // Leveringsconditie
  if @LeveringsConditieNummer is not null then
    if @_BstKopIsVerwerkt = @_qcJA then
      call Raise(20780 , _U('Leveringsconditie wijzigen'),_U('De bestelling is reeds verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
    end if;

    set @_BstKopLvcNummer = (select LvcNummer from tabLeveringsConditie where LvcNummer = @LeveringsConditieNummer);
    if @_BstKopLvcNummer is null then
      call Raise(20700, 'LeveringsConditieNummer'); // Ongeldige waarde: %1
    end if;
  end if;

  //Opmerking
  if @Opmerking is not null then
    set @_BstKopOpm = trim(@Opmerking);
  end if;

  // EmailExtraTekst
  if @EmailExtraTekst is not null then
    set @_EmailExtraTekst = trim(@EmailExtraTekst);
  end if;

  // Wijzig nu de Bestelling ...
  begin atomic
    // Bestelling meteen in gebruik nemen. Lukt dat niet: abort
    call WebSvcHulpProc_BestellingExclusiefLocken(@_BstKopGid);

    update tabBestelKop set
      BstKopMagGid = @_BstKopMagGid,
      BstKopNawGid = @_BstKopNawGid,
      BstKopNummer = @_BstKopNummer,
      BstKopIsGoedgekeurd = @_BstKopIsGoedgekeurd,
      BstKopIsVerwerkt = @_BstKopIsVerwerkt,
      BstKopBestelDatum = @_BstKopBestelDatum,
      BstKopBestelTijd = @_BstKopBestelTijd,
      BstKopValNummer = @_BstKopValNummer,
      BstKopBestelAdresSoort = @_BstKopBestelAdresSoort,
      BstKopAdrGid = @_BstKopAdrGid,
      BstKopBtcNummer = @_BstKopBtcNummer,
      BstKopLvcNummer = @_BstKopLvcNummer,
      BstKopOpm = @_BstKopOpm,
      BstKopReferentie = @_BstKopReferentie,
      BstKopRelGidInkoper = @_BstKopRelGidInkoper,
      BstKopRelGid = @_BstKopRelGid,
      BstKopAfleverDatum = @_BstKopAfleverDatum,
      BstKopEmailExtraTekst = @_EmailExtraTekst
    where BstKopGid = @_BstKopGid;

    //Als het valutanummer is gewijzigd ook alle regels wijzigen
    if @_OudeValNummer <> @_BstKopValNummer then
      update tabBestelRegel
      set    BstRglPrijs         = ValutaOmrekenen(@_OudeValNummer, BstRglPrijs,         @_BstKopValNummer, null, null, (select ArtAantDecPrijzen from tabartikel where artgid = BstRglArtGid)),
             BstRglKortingBedrag = ValutaOmrekenen(@_OudeValNummer, BstRglKortingBedrag, @_BstKopValNummer, null, null, (select ArtAantDecPrijzen from tabartikel where artgid = BstRglArtGid))
      where  BstRglBstKopGid = @_BstKopGid;
    end if;

    //Als laatste de bestelling verwerken
    if (@BestellingVerwerkt = @_qcJA) and (@_BstKopIsVerwerkt = @_qcNEE) then
      call WebSvcProc_Bestelling_Verwerken(@_BstKopNummer);
    end if;
  end; //atomic
end;

create or replace procedure WebSvcHulpProc_Boekingsgang_Journaalpost_Toevoegen(
  in @BoekjaarCode        nchar(10)     default null, // Verplicht
  in @BoekingsgangNummer  integer       default null, // Verplicht
  in @DagboekCode         nchar(10)     default null, // Verplicht
  in @BoekstukDatum       date          default null, // Verplicht
  in @BoekstukNummer      numeric(10,0) default null, // Wort gegenereerd indien leeg
  in @Omschrijving        nchar(40)     default null,
  out @_JpGid             integer       default null
)
begin
  declare @BoekGangGid      integer;
  declare @BjGid            integer;
  declare @PerGid           integer;
  declare @PerIsGeblokkeerd integer;
  declare @BjIsGeblokkeerd  integer;
  declare @DgbGid           integer;
  declare @DagboekSoort     integer;

  //call TraceBegin('WebSvcHulpProc_Boekingsgang_Journaalpost_Toevoegen > @BoekjaarCode = ' + @BoekjaarCode + ', @BoekingsgangNummer = ' + string(@BoekingsgangNummer));

  set @BoekstukDatum = (select DateTimeConversieVoorWebServices(@BoekstukDatum, @BoekstukDatum));

  select BjGid, BjIsGeblokkeerd into @BjGid, @BjIsGeblokkeerd from tabBoekjaar where Code = @BoekjaarCode;
  if (@BjGid is null) then
    call Raise(20700, 'BoekjaarCode');        // (20700) Ongeldige waarde: %1
  end if;
  if (@BjIsGeblokkeerd = 1) then
    call Raise(20700, _U('%1!, is geblokkeerd', 'BoekjaarCode')); // (20700) Ongeldige waarde: %1!
  end if;

  select BoekGangGid into @BoekGangGid from tabBoekingsGang where BoekGangBjGid = @BjGid and BoekGangNummer = @BoekingsgangNummer;
  if (@BoekGangGid is null) then
    call Raise(20700, 'BoekingsgangNummer');  // (20700) Ongeldige waarde: %1
  end if;

  // Zie hierboven: hoe zit het met BoekgangIngebruik? Geen controle hierop...

  select DgbGid, DagboekSoort into @DgbGid, @DagboekSoort from tabDagboek where DgbCode = @DagboekCode;
  if (@DgbGid is null) then
    call Raise(20700, 'DagboekCode');         // (20700) Ongeldige waarde: %1
  end if;

  set @PerIsGeblokkeerd = 0;
  if (@DagboekSoort <> 5) then
    select PerGid, PerIsGeblokkeerd into @PerGid, @PerIsGeblokkeerd from tabPeriode where @BoekstukDatum between BeginDatum and EindDatum and PerBjGid = @BjGid;
    if (@PerGid is null) then
      call Raise(20700, 'BoekstukDatum'); //Ongeldige of geen BoekstukDatum meegegeven!
    end if;
  end if;

  if (@PerIsGeblokkeerd = 1) then
    call Raise(20700, _U('%1!, periode is geblokkeerd', 'BoekstukDatum')); // (20700) Ongeldige waarde: %1!
  end if;

  if (@BoekstukDatum is null) then
    call Raise(20700, 'BoekstukDatum'); // (20700) Ongeldige waarde: %1!
  end if;

  if @BoekstukNummer is null then
    call BoekstuknummerGenereren(@BjGid, @DgbGid,  @BoekstukNummer);
  end if;

  // Journaalpost aanmaken
  // Kennlijk hoeft men niet eerst te zorgen dat men een boekingsgnag in gebruik neemt
  insert into tabJournaalpost(JpBjGid,  JpBoekGangGid, JpDgbGid, Boekdatum,  BoekstukNummer,  OmsJournaalPost)
                       values(@BjGid,  @BoekGangGid,  @DgbGid,  @BoekstukDatum, @BoekstukNummer, @Omschrijving);
  set @_JpGid = @@Identity;
end;


create or replace procedure WebSvcHulpProc_Boekingsgang_Toevoegen(
  in @BoekjaarCode nchar(10) default null,  // verplicht
  in @Gebruiker nchar(40) default null,
  in @Omschrijving nchar(40) default null,
  in @BronId smallint default null
)
result(
  BoekGangGid integer,
  BoekgangNummer numeric(10,0) )
begin
  declare @_BjGid integer;
  declare @BoekgangBronId smallint = 27;  // 27 = verwerken productie order, 36 = webservices
  declare @_BoekgangBronId smallint;

  // controle boekjaar
  begin
    declare @BjIsGeblokkeerd smallint;

    select BjGid,   BjIsGeblokkeerd
      into @_BjGid, @BjIsGeblokkeerd
    from tabBoekjaar where Code = @BoekjaarCode;
    if (@_BjGid is null) then
      call Raise(20700, 'Boekjaar') ;   // (20700) Ongeldige waarde: %1!
    end if;

    if (@BjIsGeblokkeerd = 1) then
      call Raise(20700, _U('%1!, is geblokkeerd', 'Boekjaar')) ;   // (20700) Ongeldige waarde: %1!
    end if;
  end; // controle boekjaar

  // Bron ID van boekingsgang: alleen toegestane nummers (Zie combowaarden document King 5.61a)
  select @BronId into @_BoekgangBronId from dummy where ( @BronId not in (28,29) ) and ( @BronId between 1 and 38 );
  if @_BoekgangBronId is null then
    call Raise(20700, _U('Bron boekingsgang (Id=%1!)', string(@BronId))) ; // (20700) Ongeldige waarde: %1!
  end if;

  // Boekingsgang aanmaken,
  begin
    declare @BoekgangGid integer;
    // die is met insert vanzelfsprekend in gebruik ( BoekGangInGebruik = 1 )
    // Er wordt ook atomatisch een lock gezet op naam van @gebruiker
    insert into tabBoekingsGang(BoekGangBjGid, BoekGangGebruikersnaam, BoekGangBronId, BronOms, IsBoekGangDefinitief)
      values( @_BjGid,
              @Gebruiker,
              @_BoekgangBronId,
              @Omschrijving, // OPGELET:  die kan door trigger Boekingsgang.tr worden overschreven, o.b.v. BoekGangBronId
              0 );  // 0 = voorlopig, 1 = definitief
    set @BoekgangGid = @@Identity;

    // resultset
    select BoekgangGid, BoekgangNummer from tabBoekingsGang where BoekgangGid = @BoekgangGid;
  end; // boekingsgang toevoegen
end;



create or replace procedure WebSvcHulpProc_Order_LockVrijgeven(
  in @OrkNummer     numeric(10,0) default null, //Verplicht
  in @LockUserNaam  nchar(40)     default null, // Dit kan per API verschillen. De aanroeper moet zich identificeren
  in @SpId          integer       default null, // NULL =>  systeemvariabele @@SpId       wordt gebruikt
  in @LoginTime     timestamp     default null  // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt
)
begin
  // variabelen
  declare @_OrkGid        integer;
  declare @_LockUserNaam  nchar(40);
  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabOrderKop';

  //call TraceBegin('WebSvcHulpProc_Order_LockVrijgeven');

  // Opzoeken Order
  set @_OrkGid =( select OrkGid from tabOrderKop where OrkNummer = @OrkNummer );
  if @_OrkGid is null then
    call Raise(20720, _U('Order %1!', string(@OrkNummer))); // (20720) %1 niet gevonden!
  end if;

  if @LockUserNaam is null then
    call Raise(20700, 'LockUserNaam') ;   // (20700) Ongeldige waarde: %1!
  end if;
  set @_LockUserNaam = @LockUserNaam;

  //Elke api heeft zijn eigen connection id.
  //Het standaard lockmechanisme werkt in dat geval dan niet.
  //het vrij geven van een lock gaat dan niet op SpId, maar op usernaam

  begin // lock vrijgeven
    call LockReleaseOnId(isnull(@Spid, @@SpId), isnull(@LoginTime,@@LoginTime), 1, _QLOCKTABLENAME, @_OrkGid);

    // gelockt, maar niet door @_LockUserNaam? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = _QLOCKTABLENAME and qLockPKey = string(@_OrkGid) and qLockUser <> @_LockUserNaam) then
      call Raise(20741, _U('Order %1!', string(@OrkNummer))); // (20741) %1! is in gebruik!
    end if;

    // De record zou dus wel door @LockUserNaam gelockt zijn, deze opruimen.
    call LockReleaseOnUserName(@_LockUserNaam, 1, _QLOCKTABLENAME, @_OrkGid);
  end; // lock vrijgeven

  //call TraceEind('WebSvcHulpProc_Order_LockVrijgeven');
end;



create or replace procedure WebSvcHulpProc_MagazijnontvangstExclusiefLocken
( in @LockMokGid integer,
  in @LockUserNaam nchar(40) default null,
  in @SpId integer default null,
  in @LoginTime datetime default null)
begin
  declare @_LockResult integer;

  // Defaults instellen
  if @LockUserNaam is null then
    set @LockUserNaam = 'KingWebservice';
  end if;
  if @SpId is null then
    set @SpId = @@SpId;
  end if;
  if @LoginTime is null then
    set @LoginTime = @@LoginTime;
  end if;

  if not exists(select first 1 from tabMagazijnOntvangstenKop where MokGid = @LockMokGid ) then
    call Raise(20780, _U('In gebruik nemen'), _U('magazijnontvangst niet gevonden')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if LockedById(@SpId, @LoginTime, 1 /*exclusieve lock*/, 'tabMagazijnOntvangstenKop', @LockMokGid) = 0  then
    // locken, met standaard King 5 procedure
    call LockSetOnId( @Spid,
                      @LoginTime,
                      1,                            // 1 = Exclusieve lock, 0 = ReadLock
                      'tabMagazijnOntvangstenKop',  // tabel waarin record te locken is - nchar(40)
                      string(@LockMokGid),          // lockstring voor record, nchar(80)
                      @_LockResult,                 // 0 = OK, anders fout
                      0,                            // Automatisch opruimen: 0 = nee, 1 = ja
                      @LockUserNaam);               // Welke King gebruiker of proces

    if @_LockResult <> 0 then
      call Raise(20741,_U('Magazijnontvangst'));    // (20741) %1 is in gebruik!
    end if;
  end if;
end;



create or replace procedure WebSvcHulpProc_MagazijnOntvangst_CbsAangifte(
  in    @NawGid                   integer,
  out   @_CbsMeenemenInAangifte   smallint,
  out   @_CbsCoGid                integer,
  out   @_CbsGsGid                integer,
  out   @_CbsLndGidHerkomst       integer,
  out   @_CbsPtnGidCerkeersgebied integer,
  out   @_CbsSsGid                integer,
  out   @_CbsVwGid                integer)
begin
  declare @_LndGid integer;

  // Initialiseren, we doen alsof er geen aangifte gedaan hoeft te worden
  set @_CbsMeenemenInAangifte = 0;
  set @_CbsCoGid = null;
  set @_CbsGsGid = null;
  set @_CbsLndGidHerkomst = @_LndGid;
  set @_CbsPtnGidCerkeersgebied = null;
  set @_CbsSsGid = null;
  set @_CbsVwGid = null;

  // Herkomst is uit het buitenland?
  set @_LndGid = (select AdrLndGid
                  from tabAdres
                  inner join tabLand on (LndGid = AdrLndGid)
                  inner join tabNaw on (NawGidVestiging = AdrGid) and (NawGid = @NawGid)                      // deze ene crediteur...
                  where LndGid not in (select DefaultLndGID from tabVasteGegevens )                           // met vestiging in buitenland
                    and ((LndIsEGLid = 1)                                                                     // dat EU lidstaat is, OF ...
                         or exists(select first 1 from tabCbsVast where CbsVastExtraHandelNaarCbsIris = 1))); // buiten de EU waarvoor je OOK handel moet aangeven

  // En moet je daarvoor wel aangifte doen of niet?
  select 1, CbsVastCbsCoGidInvoer, CbsVastCbsGsGidInvoer, @_LndGid, CbsVastPtnGidInvoer, CbsVastCbsSsGidInvoer, CbsVastCbsVwGidInvoer
    into @_CbsMeenemenInAangifte, @_CbsCoGid, @_CbsGsGid, @_CbsLndGidHerkomst, @_CbsPtnGidCerkeersgebied, @_CbsSsGid, @_CbsVwGid
  from tabCbsVast
  where (CbsVastNaarCbsIrisInvoer = 1)  // alleen als aangifte moet
    and (@_LndGid is not null) ;          // en het is uit buitenland afkomstig
end;


create or replace procedure WebSvcHulpProc_Magazijnontvangst_Inkoopfactuur(
  in  @InkoopfactuurAanmaken            smallint      ,
  in  @FactuurNummer                    nchar(40)     , // Factuurreferentie
  in  @FactuurDatum                     date          ,
  in  @VervalDatum                      date          ,
  in  @BetKenmerk                       nchar(24)    ,
  in  @InkoopfactuurVerwerken           smallint      ,
  //  Onderstaande invoer parameters  moeten vooraf al gevalideerd zijn
  in  @MokNummer                        numeric(10,0) ,
  in  @MokOntvangstDatum                date          ,
  in  @MokBtcNummer                     integer       ,
  in  @MokNawGid                        integer       ,
  out @_MokInkoopfactuurAanmaken        smallint      ,
  out @_MokFactuurNummer                nchar(40)     , // Factuurreferentie
  out @_MokFactuurNummer_Lengte         integer       , // Dit is vanwege index op uitlever-/factuurhistorie
  out @_MokFactuurDatum                 date          ,
  out @_MokVervalDatum                  date          ,
  out @_MokBetKenmerk                   nchar(24)     ,
  out @_MokInkoopfactuurVerwerken       smallint      ,
  out @_MokValNummer                    integer       )
begin
  declare @_IsInkoopFactuurAanmakenToegestaan smallint;
  declare @_NawFilNummer          nchar(10);
  declare @_NawOnsDebiteurNummer  nchar(20);

  // crediteurgegevens opvragen
  select NawFilNummer, NawOnsDebiteurNummer
    into @_NawFilNummer, @_NawOnsDebiteurNummer
  from tabNawFile
  inner join tabNaw on NawGid = NawFilNawGid and NawGid = @MokNawGid
  inner join tabFileOfNaw on FonGid = NawFilFonGid and FonId = 'C';

  // ----------------------------------------
  // Wordt er wel met inkoopfacturen gewerkt,
  // Dan de default instellingen uit vaste gegevens inkopen.
  // ----------------------------------------
  // inkoopfacturen nu niet toestaan, eerst kijken of inkoopfactuur module actief is.
  set @_IsInkoopFactuurAanmakenToegestaan = 0 ;

  begin
    declare @_MagVastDefVervaldatum smallint;

    select  MagVastIsInkoopfactuurAanmakenToegestaan, MagVastDefInkoopFactuurAanMaken,
            case MagVastDefFactuurnummer
              when 1 then @MokNummer            // 1 = ontvangstnummer,
              else null                         // 0 = leeg, of onbekende optie
            end case  as [DefaultFactuurnummer],
            length([DefaultFactuurnummer]),
            case MagVastDefFactuurdatum
              when 3  then date(now())          // 3 = systeemdatum
              when 2  then @@VerwerkingsDatum   // 2 = verwerkingsdatum
              when 1  then @MokOntvangstDatum   // 1 = ontvangstdatum
              else null                         // 0 = leeg, of ander onbekend optie
            end case,
            MagVastDefVervaldatum, InkoopfactuurDefaultBetalingskenmerk(@MokNummer, @_NawOnsDebiteurNummer, @_NawFilNummer), MagVastDefInkoopfactuurVerwerken
      into  @_IsInkoopFactuurAanmakenToegestaan, @_MokInkoopfactuurAanmaken, @_MokFactuurNummer, @_MokFactuurNummer_Lengte, @_MokFactuurDatum,
            @_MagVastDefVervaldatum, @_MokBetKenmerk, @_MokInkoopfactuurVerwerken
    from tabMagazijnOntvangstenVastegegevens
    where IsModuleActive('if') <> 0;          // je gaat niks met defaults doen als module niet actief is.

    // op basis van default instelling de vervaldatum nog definitief bepalen.
    // 2 = Volgens Betalingsconditie (leverancier)
    // 1 = factuurdatum
    set @_MokVervalDatum = null ;
    if  (@_MagVastDefVervaldatum = 2) and (@MokBtcNummer is not null) and (@_MokFactuurDatum is not null) then
      // Van onderstaande stored proc is niet duidelijk wat het doet met factuurdatum = null
      call BerekenVervalDatumFactuur(@_MokFactuurDatum, @MokBtcNummer, @_MokVervalDatum);
    end if;
    if (@_MagVastDefVervaldatum = 1) then
      set  @_MokVervalDatum = @_MokFactuurDatum
    end if;
  end;

  // ----------------------------------------
  // defaults zetten waar men standaard *niet* met inkoopfactuur wil werken
  // de hierboven bepaalde factuurreferentie mag wel blijven staan
  // ----------------------------------------
  select  0, null, null, null, 0, null
    into  @_MokInkoopfactuurAanmaken, @_MokFactuurDatum, @_MokVervalDatum, @_MokBetKenmerk, @_MokInkoopfactuurVerwerken, @_MokValNummer
  from    dummy
  where   @_IsInkoopFactuurAanmakenToegestaan = 0; // dit kan ook betekenen: module is niet actief in King


  // ----------------------------------------
  // Ingevulde parameters voor inkoopfactuur valideren
  // ----------------------------------------
  begin
    declare @_suffixmsg nchar(80);
    declare @_FactuurNummer nchar(40) = isnull(trim(@FactuurNummer),'');
    declare @_BetalingsKenmerk nchar(24) = isnull(trim(@BetKenmerk),'');

    // Inkoopfactuur aanmaken is niet de bedoeling (verboden of aangegeven), dan andere ingevulde parameters als fout melden.
    // Raiserror 20701 - Ongeldige combinatie: %1
    // Test ongeldige waardes, in geval van een null blijft default insteling uit vaste gegevens staan.
    select @InkoopfactuurAanmaken into @_MokInkoopfactuurAanmaken where @InkoopfactuurAanmaken is not null;
    if @_MokInkoopfactuurAanmaken not in (0,1) then
      call Raise(20700, 'InkoopfactuurAanmaken'); // Ongeldige Waarde : %1
    end if;

    // wil je geen inkoopfactuur, ga dan niet andere parameters invullen.
    if (@InkoopfactuurAanmaken = 0) then
      set @_suffixmsg = ', '+ _U('laat leeg als je geen inkoopfactuur wil.')
    end if;

    if (@_IsInkoopFactuurAanmakenToegestaan = 0) then
      set @_suffixmsg = ', '+ _U('inkoopfactuur aanmaken is niet toegestaan!');
      if @_MokInkoopfactuurAanmaken <> 0 then
        call Raise(20701 , string('InkoopfactuurAanmaken', @_suffixmsg));
      end if;
    end if;

    if @_suffixmsg is not null then
      if  @FactuurDatum is not null              then call Raise(20701, string('Factuurdatum', @_suffixmsg)); end if;
      if  @VervalDatum is not null               then call Raise(20701, string('Vervaldatum', @_suffixmsg)); end if;
      if  @_BetalingsKenmerk <> ''               then call Raise(20701, string('Betalingskenmerk', @_suffixmsg)); end if;
      if  isnull(@InkoopfactuurVerwerken,0) <> 0 then call Raise(20701, string('InkoopfactuurVerwerken', @_suffixmsg)); end if;
    end if;

    // vinkje
    select @InkoopfactuurVerwerken into @_MokInkoopfactuurVerwerken where @InkoopfactuurVerwerken is not null;
    if (@_MokInkoopfactuurVerwerken not in (0,1))then
      call Raise(20700, 'InkoopfactuurVerwerken'); // Ongeldige Waarde : %1
    end if;

    // factuurdatum
    if (@FactuurDatum is not null) then
      select first @FactuurDatum into @_MokFactuurDatum
      from tabBoekjaar
      where (BjAfsluiting <> 2)
        and @FactuurDatum between BjBeginDatum and BjEindDatum;
      // boekjaar is definitief afgesloten, of er is geen boekjaar bekend (datum is in geen enkel boekjaar)
      if (@_MokFactuurDatum is null) then
        call Raise(20700, _U('Factuurdatum %1! voor inkoopfactuur kan niet, geen boekjaar die open is', string(@FactuurDatum))) ; // Ongeldige waarde: %1
      end if;
    end if;

    if (@_MokFactuurDatum > @VervalDatum) then
      //een gegenereerd factuurdatum kan later zijn dan expliciet ingevulde vervaldatum
      call Raise(20701, _U('Vervaldatum, deze is eerder dan de factuurdatum %1!', string(@_MokFactuurDatum))); // Ongeldige Combinatie : %1
    end if;

    // vervaldatum
    if (@VervalDatum is null) then
      call BerekenVervalDatumFactuur (@_MokFactuurDatum, @MokBtcNummer, @_MokVervalDatum);
    end if;

    select @VervalDatum
    into @_MokVervalDatum
    where @VervalDatum is not null;

    // overige onderdelen
    select @_FactuurNummer into @_MokFactuurNummer where @_FactuurNummer <> '';
    select @_BetalingsKenmerk into @_MokBetKenmerk where @_BetalingsKenmerk <> '';
    set @_MokFactuurNummer_Lengte = length(@_MokFactuurNummer);

    // factuurreferentie staat hier nu vast,
    // nu kunnen we openstaande post opzoeken en kijken wat de valuta ervan is.
    select OspValNummer
      into @_MokValNummer
    from tabOpenstaandePost
    where OspIsCrediteur = 1
      and OspSoortFactuur = 0   // 0=std. factuur, 1=kredietbeperking, 2=betalingskorting, 3=autom.incasso, 4=factoring
      and OspRksInvoer = @_NawFilNummer
      and OspFactuurnummer = @_MokFactuurNummer;
  end; // validatie ingevulde parameters
end;


create or replace procedure WebSvcHulpProc_Magazijnontvangst_OntvangstRegel_Toevoegen
( in @OntvangstNummer                   numeric(10,0),
  in @ArtikelSoort                      nchar(3), // Waarden: "TAR" of "ART"
  in @ArtikelNummer                     nchar(20),
  in @ArtikelEanCode                    nchar(30),
  in @ArtikelNummerLeverancier          nchar(20),
  in @AantalOntvangen                   numeric(14,3), // Aantal ontvangen in Inkoopeenheden
  in @AantalCorrectie                   numeric(14,3), // Aantal correctie in Voorraadeenheden
  in @Partijnummer                      nchar(20),
  in @Bestelnummer                      numeric(10,0),
  in @Bestelregelnummer                 numeric(3,0),
  in @InkoopEenheid                     nchar(20),
  in @VoorraadEenhedenInInkoopEenheid   numeric(15,3),
  in @InkoopPrijs                       numeric(14,3),
  in @Kortingspercentage                numeric(15,2),
  in @Kortingsbedrag                    numeric(14,3),
  in @BTWCode                           numeric(3,0),
  in @CBSLandOorsprong                  nchar(3),
  in @CbsDouaneregeling                 nchar(4),
  in @Opmerking                         long nvarchar,
  in @StandaardSpecificatieRegel        nchar(3), // Waarden: "JA" of "NEE", "JA" is default
  // T.b.v. locken
  in @LockUserNaam    nchar(40),   // Dit kan per API verschillen. De aanroeper moet zich identificeren
  in @SpId            integer default null,   // NULL =>  systeemvariabele @@SpId       wordt gebruikt
  in @LoginTime       timestamp default null)   // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt
result (OntvangstRegelNummer numeric(3,0))

begin
  //Constanten
  declare _qcNEE smallint = 0;
  declare _qcJA smallint = 1;

  declare @_RegelNummer numeric(3,0);

  //call TraceBegin('WebSvcHulpProc_Magazijnontvangst_OntvangstRegel_Toevoegen > @OntvangstNummer = ' + @OntvangstNummer);
  begin atomic
    declare @_BjGid integer;
    declare @_PerNr integer;
    declare @_BasisValNummer numeric(3,0);
    declare @_BstKopGid integer;
    declare @_BstKopValNummer numeric(3,0);
    declare @_BstRglAantalBesteld numeric(15,3);
    declare @_BstRglPrijs numeric(15,3);
    declare @_BstRglKortingBedrag numeric(15,3);
    declare @_BstRglKortingPercentage numeric(15,3);
    declare @_BstRglKortingSoort smallint;
    declare @_MagVastKoppelenBestelling smallint; // 0 = Automatisch, 1 = Niet automatisch.
    declare @_MagVastDefInkoopprijs smallint; // 0 = Vaste verrekenprijs, 1 = Inkoopprijs
    declare @_MokGid integer;
    declare @_MokMagGid integer;
    declare @_MokNawGid integer;
    declare @_MokNummer numeric(10,0);
    declare @_MokValNummer numeric(3,0);
    declare @_MokOntvangstDatum date;
    declare @_MokSoort smallint;
    declare @_MokInkoopfactuurAanmaken smallint;
    declare @_MokCbsLndGidHerkomst integer;
    declare @_AldGid integer;
    declare @_AldAantalKanVerschillen smallint;
    declare @_AldHeeftEigenInkoopprijs smallint;
    declare @_AldVoorraadEenhedenInInkoopEenheid numeric(15,3);
    declare @_AldValNummer numeric(3,0);
    declare @_AldInkoopPrijs numeric(15,3);
    declare @_AldKortingBedrag numeric(15,3);
    declare @_AldKortingPercentage numeric(15,2);
    declare @_AldKortingSoort smallint; // 0 = Bedrag, 1 = Percentage, 2 = Gestaffeld
    declare @_AldNstfKopGid integer;
    declare @_ArtEanCode nchar(30);
    declare @_ArtPartijInkoopValNummer numeric(3,0);
    declare @_ArtPartijInkoopPrijs numeric(15,3);
    declare @_VkeGid integer;
    declare @_VkeVerkoopEenheid nchar(20);
    declare @_VkeIsVoorraadEenheid smallint;
    declare @_VkeAantalVoorraadEenhedenInVerkoopEenheid numeric(15,3);
    declare @_VkeVerkoopPrijsPer numeric(15,3);
    declare @_DefaultSpecificatie smallint; // 0 = Geen default specificatie, 1 = Wel default specificatie
    // tabMagazijnOntvangsten
    declare @_MagOntMokGid integer;
    declare @_MagOntRegelSoort smallint; // 0 = Tekst, 1 = Tarief, 2 = Artikel
    declare @_MagOntArtGid integer;
    declare @_MagOntEanCode nchar(30);
    declare @_MagOntArtCodeBijLeverancier nchar(20);
    declare @_MagOntInkoopEenheid nchar(20);
    declare @_MagOntInkoopprijs numeric(15,3);
    declare @_MagOntInkoopprijsPer smallint;
    declare @_MagOntPrijsPer numeric(15,3);
    declare @_MagOntVoorraadEenhedenInInkoopEenheid numeric(15,3);
    declare @_MagOntArtPartijGid integer;
    declare @_MagOntBstRglGid integer;
    declare @_MagOntRegelNr integer;
    declare @_MagOntBstRglOms long nvarchar;
    declare @_MagOntAantalInkoopEenheden numeric(15,3);
    declare @_MagOntAantal numeric(15,3);
    declare @_MagOntAantalCorrectie numeric(15,3);
    declare @_MagOntKortingPercentage numeric(15,2);
    declare @_MagOntKortingBedrag numeric(15,3);
    declare @_MagOntKortingSoort smallint;
    declare @_MagOntBtwCode integer;
    declare @_MagOntOpm long nvarchar;
    declare @_MagOntCbsPreferentieCode nchar(3);
    declare @_MagOntCbsTaric nchar(2);
    declare @_MagOntCbsTrGid integer;
    declare @_MagOntCbsLndGidOorsprong integer;
    declare @_MagOntCbsDouaneregeling nchar(4);
    // tabMagazijnOntvangstenDetail
    declare @_MagOntDetMagOntGid integer;
    declare @_MagOntDetbrdGid integer;
    declare @_MagOntDetAantalCorrectie numeric(15,3);
    declare @_MagOntDetBrdSoort smallint;
    declare @_MagOntDetKoppeling smallint;
    // tabMagazijnOntvangstLocatieSerie
    declare @_MagOntLocMagOntDetGid integer;
    declare @_MagOntLocLocGid integer;
    declare @_MagOntLocAantal numeric(15,3);

    declare @_ArtPrijsPer numeric(15,3);

    // Ophalen Basis Valutanummer
    select ValNummer into @_BasisValNummer from tabValuta where IsBasisValuta = _qcJA;

    // Ophalen benodigde gegevens uit Vaste gegevens Inkopen
    select MagVastKoppelenBestelling, MagVastDefInkoopprijs
      into @_MagVastKoppelenBestelling, @_MagVastDefInkoopprijs
    from tabMagazijnOntvangstenVastegegevens
    where MagVastId = 1;

    // Opzoeken onderhanden Magazijnontvangstkop
    select MokGid, MokMagGid, MokNawGid, MokValNummer, MokOntvangstDatum, MokInkoopfactuurAanmaken, MokCbsLndGidHerkomst, MokSoort
      into @_MokGid, @_MokMagGid, @_MokNawGid, @_MokValNummer, @_MokOntvangstDatum, @_MokInkoopfactuurAanmaken, @_MokCbsLndGidHerkomst, @_MokSoort
    from tabMagazijnOntvangstenKop
    where MokNummer = @OntvangstNummer;
    if  @_MokGid is null then
      call Raise(20780,_U('Magazijnontvangst wijzigen is'),_U('Ongeldige of geen %1! meegegeven', 'OntvangstNummer'));     // (20780) %1! niet mogelijk: %2!
    end if;
    set @_MagOntMokGid = @_MokGid;

    // Ophalen Boekjaar en Periode t.b.v. valutakoers omrekeningen
    call BepaalBoekjaarEnPeriode(@_MokOntvangstDatum,@_BjGid,@_PerNr);

    // Gevonden Magazijnontvangst locken of bestaande lock overnemen
    call WebSvcHulpProc_MagazijnontvangstExclusiefLocken(@_MokGid, @LockUserNaam, @Spid, @LoginTime);

    // Controle: Indien @Bestelnummer is ingevuld, dan moet dit een bestaande bestelling zijn
    if isnull(@Bestelnummer,0) <> 0 then
      select BstKopGid, BstKopValNummer
        into @_BstKopGid, @_BstKopValNummer
      from tabBestelKop
      where BstKopNummer = @Bestelnummer;
      if @_BstKopGid is null then
        call Raise(20720,'Bestelnummer');   // (20720) %1! niet gevonden!
      end if;
    else
      // Indien @Bestelregelnummer is meegegeven, zonder @Bestelnummer, dan is @Bestelnummer verplicht
      if isnull(@Bestelregelnummer,0) > 0 then
        call Raise(20701, _U('%1! is verplicht in combinatie met %2!', 'Bestelnummer', 'Bestelregelnummer'));    // (20701) Ongeldige combinatie: %1!
      end if
    end if;

    // Controle: @ArtikelSoort moet 'ART' of 'TAR' zijn.
    case
      when isnull(@ArtikelSoort,'') = 'ART' then set @_MagOntRegelSoort = 2;
      when isnull(@ArtikelSoort,'') = 'TAR' then set @_MagOntRegelSoort = 1;
      else call Raise(20700, 'ArtikelSoort');   // (20700) Ongeldige waarde: %1!
    end case;

    // Controle: Tarief is alleen toegestaan in combinatie met aanmaken van inkoopfactuur
    if @_MagOntRegelSoort = 1 and @_MokInkoopfactuurAanmaken = _qcNEE then
      call Raise(20701,_U('Bij %1! is %2! verplicht.', 'TAR', 'FactuurBoekingMaken'));   // (20701) Ongeldige combinatie: %1!
    end if;

    // Controle: Indien @ArtikelNummer is meegegeven, dan moet dit een bestaand artikel of tarief zijn, afhankelijk van @ArtikelSoort.
    if isnull(@ArtikelNummer,'') <> '' then
      select ArtGid into @_MagOntArtGid from tabArtikel where ArtCode = @ArtikelNummer and ArtSoort = @_MagOntRegelSoort;
      if @_MagOntArtGid is null then
         call Raise(20720,'ArtikelNummer');   // (20720) %1! niet gevonden!
      end if;
    end if;

    // Controle: Indien geen @ArtikelNummer, maar wel @ArtikelEanNummer is meegegeven, dat moet @ArtikelEanNummer een bestaande EAN code zijn.
    //           Meegegeven @ArtikelEanCode wordt genegeerd , indien @ArtikelNummer is meegegeven.
    if @_MagOntArtGid is null and isnull(@ArtikelEanCode,'') <> '' then
      // Controleer of een bestaande EanCode is meegegeven
      select ArtEanArtGid, ArtEanCode
        into @_MagOntArtGid, @_MagOntEanCode
      from tabArtikelEan
      where ArtEanCode = @ArtikelEanCode;

      if @_MagOntArtGid is not null then
        // EAN code bestaat, nu controleren of deze toebehoort aan de juiste leverancier
        if exists(select 1
                  from tabArtikelEan
                  inner join tabArtikelLeverancierDetail on AldArtEanGid = ArtEanGid
                  inner join tabArtikelLeverancier on ArtLevGid = AldArtLevGid and ArtLevNawGid <> @_MokNawGid
                  where ArtEanCode = @ArtikelEanCode) then
          call Raise(20701, _U('EAN-code inkoopeenheid is van een andere leverancier'));   // (20701) Ongeldige combinatie: %1!
        end if;
      else
        call Raise(20720, 'ArtikelEanCode');   // (20720) %1! niet gevonden!
      end if;
    end if;

    // Controle: Indien geen @ArtikelNummer en @ArtikelEanCode, maar wel @ArtikelNummerLeverancier is meegegeven,
    //           dan moet dit wel een bestaande en uniek artikelnummer zijn binnen de leverancier.
    //           Meegegeven @ArtikelNummerLeverancier wordt genegeerd, indien @ArtikelNummer of @ArtikelEanCode is meegegeven.
    if @_MagOntArtGid is null and isnull(@ArtikelNummerLeverancier,'') <> '' then
      if (select count(distinct ArtLevArtGid)
          from tabArtikelLeverancier
          inner join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid and AldArtCodeBijLeverancier = @ArtikelNummerLeverancier
          where ArtLevNawGid = @_MokNawGid) > 1
      then
        call Raise(20780,_U('Artikel ophalen'),_U('Artikelnummer van leverancier wordt bij meerdere artikelen gebruikt'));   // (20780) %1! niet mogelijk: %2!
      else
        select first ArtLevArtGid into @_MagOntArtGid
        from tabArtikelLeverancier
        inner join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid and AldArtCodeBijLeverancier = @ArtikelNummerLeverancier
        where ArtLevNawGid = @_MokNawGid;

        if @_MagOntArtGid is null then
           call Raise(20720,'ArtikelNummerLeverancier');   // (20720) %1! niet gevonden!
        end if;

        set @_MagOntArtCodeBijLeverancier = @ArtikelNummerLeverancier;
      end if
    end if;

    // Controle: Een artikel moet succesvol zijn opgehaald.
    if @_MagOntArtGid is null then
       call Raise(20700,_U('%1! of %2! of %3!', 'ArtikelNummer', 'ArtikelEanCode', 'ArtikelNummerLeverancier'));   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Artikel mag niet geblokkeerd zijn voor magazijnontvangsten
    if (select ArtIsGeblokkeerdMagOntv from tabArtikel where ArtGid = @_MagOntArtGid) = _qcJA then
      call Raise(20780,_U('Artikel ophalen'),_U('Artikel is geblokkeerd voor magazijnontvangst'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Controle: Indien @Bestelregelnummer is meegegeven, dan moet dit een bestaande bestelregel zijn binnen de gekoppelde bestelling
    //           en Artikel uit de bestelregel moet overeenkomen met het meegegeven artikel.
    if isnull(@Bestelregelnummer,0) > 0 then
      select BstRglGid, BstRglOms, BstRglAantalBesteld, BstRglPrijs, BstRglKortingBedrag, BstRglKortingPercentage, BstRglKortingSoort
        into @_MagOntBstRglGid, @_MagOntBstRglOms, @_BstRglAantalBesteld, @_BstRglPrijs, @_BstRglKortingBedrag, @_BstRglKortingPercentage, @_BstRglKortingSoort
      from tabBestelRegel
      where BstRglBstKopGid = @_BstKopGid
        and BstRglNummer    = @Bestelregelnummer;
      if @_MagOntBstRglGid is null then
        call Raise(20720,'Bestelregelnummer');   // (20720) %1! niet gevonden!
      else
        // Controle: Artikel in bestelregel moet overeenkomen met meegegeven artikel.
        if (select BstRglArtGid from tabBestelRegel where BstRglGid = @_MagOntBstRglGid) <> @_MagOntArtGid then
          call Raise(20701,_U('Artikel in bestelregel komt niet overeen met het meegegeven artikel'));   // (20701) Ongeldige combinatie: %1!
        end if;
      end if;
    else
      // Indien @Bestelnummer is meegegeven, maar @Bestelnummerregel is niet meegegeven
      // en in Vaste gegevens Magazijnontvangsten staat vermeld, dat een bestelregel automatisch gekoppeld moet worden,
      // dan de eerst voorkomende bestelregel ophalen, waarbij het meegegeven artikel overeenkomt met de bestelregel binnen de meegegeven bestelnummer
      if @_BstKopGid is not null and @_MagVastKoppelenBestelling = _qcNEE then   // @_MagVastKoppelenBestelling = 0 is automatisch koppelen aan bestelregel
        // Indien geen bestelregel wordt gevonden, dan is de magazijnontvangstregel niet gekoppeld aan een bestelregel.
        select first BstRglGid, BstRglOms, BstRglAantalBesteld, BstRglPrijs, BstRglKortingBedrag, BstRglKortingPercentage, BstRglKortingSoort
          into @_MagOntBstRglGid, @_MagOntBstRglOms, @_BstRglAantalBesteld, @_BstRglPrijs, @_BstRglKortingBedrag, @_BstRglKortingPercentage, @_BstRglKortingSoort
        from tabBestelRegel
        where BstRglBstKopGid = @_BstKopGid
          and BstRglArtGid = @_MagOntArtGid
        order by BstRglNummer;
      end if;
    end if;

    // Als de bestelregel is gekoppeld, dan ook de eerste besteldetailregel ophalen, gesorteerd op brdSoort (Magazijn eerst)
    if @_MagOntBstRglGid is not null then
      select first brdGid, brdSoort,
               if brdSoort = 0 then      // brdSoort: 0 = Magazijn
                  1                      // MagOntDetKoppeling: 1 = Bestelling    (Magazijnontvangst is gekoppeld aan Bestelregel)
               else                      // brdSoort: 1 = Verkooporder
                  2                      // MagOntDetKoppeling: 2 = Verkooporder  (Magazijnontvangst is gekoppeld aan Verkooporder)
               end if
      into @_MagOntDetbrdGid, @_MagOntDetBrdSoort, @_MagOntDetKoppeling
      from tabBestelRegelDetail
      where brdBstRglGid = @_MagOntBstRglGid
      order by brdSoort;
    else
      set @_MagOntDetKoppeling = 0;    // MagOntDetKoppeling: 0 = Magazijn  (Magazijnontvangst is niet gekoppeld aan een bestelregel of een verkooporder)
    end if;

    // Controle: @Partijnummer is verplicht, indien het artikel partijregistreren is.
    //           Indien verplicht, dan moet het partijnummer voorkomen binnen het artikel
    //           en het partijnummer mag niet geblokkeerd zijn voor magazijnontvangsten.
    if (select ArtIsPartijRegistreren from tabArtikel where ArtGid = @_MagOntArtGid) = _qcJA then    // ArtIsPartijRegistreren = 1 Artikel is partijregistrerend
      if isnull(@Partijnummer,'') <> '' then
        select ArtPartijGid, ArtPartijInkoopValNummer, ArtPartijInkoopPrijs
          into @_MagOntArtPartijGid, @_ArtPartijInkoopValNummer, @_ArtPartijInkoopPrijs
        from tabArtikelPartij
        where ArtPartijArtGid = @_MagOntArtGid
          and ArtPartijNummer = @Partijnummer;

        if @_MagOntArtPartijGid is not null then
          // Partijnummer is gevonden, maar mag niet zijn geblokkeerd voor magazijnontvangsten
          if (select ArtPartijIsGeblokkeerdVoorInkoop from tabArtikelPartij where ArtPartijGid = @_MagOntArtPartijGid) = _qcJA then     // ArtPartijIsGeblokkeerdVoorInkoop = 1 Partijnummer is geblokkeerd voor magazijnontvangsten
            call Raise(20780,_U('Partijnummer is'),_U('Partijnummer is geblokkeerd voor magazijnontvangsten'));   // (20780) %1! niet mogelijk: %2!
          end if;
        else
          call Raise(20720,'Partijnummer');   // (20720) %1! niet gevonden!
        end if;
      else
        // Geen @Partijnummer meegegeven, is wel verplicht
        call Raise(20700,_U('Partijnummer niet meegegeven, artikel is partijregistrerend'));   // (20700) Ongeldige waarde: %1!
      end if;
    else
      // @Partijnummer meegegeven, maar het artikel is niet partijregistrerend.
      if isnull(@Partijnummer,'') <> '' then
        call Raise(20700,_U('Partijnummer is niet toegestaan, artikel is niet partijregistrerend'));   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Ophalen gegevens van de voorraadeenheid van het artikel
    select VkeGid, VkeVerkoopEenheid, VkeAantalVoorraadEenhedenInVerkoopEenheid, VkeIsVoorraadEenheid, VkeVerkoopprijsPer, ArtEanCode
      into @_VkeGid, @_VkeVerkoopEenheid, @_VkeAantalVoorraadEenhedenInVerkoopEenheid, @_VkeIsVoorraadEenheid, @_VkeVerkoopprijsPer, @_ArtEanCode
    from tabVerkoopEenheid
    left join  tabArtikelEan on ArtEanGid = VkeArtEanGid
    where VkeArtGid = @_MagOntArtGid
      and VkeIsVoorraadEenheid = _qcJA; // Alleen VoorraadEenheid

    // Controle: Indien @Inkoopeenheid is meegegeven, dat moet dit een bestaande inkoopeenheid zijn binnen het Artikel en Leverancier
    //           en moet overeenkomen met een eventueel gekoppelde bestelregel.
    if isnull(@InkoopEenheid,'') <> '' then

      select ArtPrijsPer into @_ArtPrijsPer from tabArtikel where ArtGid = @_MagOntArtGid;

      // @InkoopEenheid is meegegeven
      select AldGid, AldAantalKanVerschillen, AldHeeftEigenInkoopprijs, AldValNummer, AldInkoopPrijs, AldKortingBedrag, AldKortingPercentage, AldKortingSoort, AldInkoopEenheid,
             AldVoorraadEenhedenInInkoopEenheid, AldArtCodeBijLeverancier, AldNstfKopGid, ArtEanCode, @_ArtPrijsPer  //RB foute prijsper gebruikt @_VkeVerkoopprijsPer
        into @_AldGid, @_AldAantalKanVerschillen, @_AldHeeftEigenInkoopprijs, @_AldValNummer, @_AldInkoopPrijs, @_AldKortingBedrag, @_AldKortingPercentage, @_AldKortingSoort, @_MagOntInkoopEenheid,
             @_MagOntVoorraadEenhedenInInkoopEenheid, @_MagOntArtCodeBijLeverancier, @_AldNstfKopGid, @_MagOntEanCode, @_MagOntPrijsPer
      from tabArtikelLeverancier
      inner join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid
      left join tabArtikelEan on ArtEanGid = AldArtEanGid
      where AldInkoopEenheid = @InkoopEenheid
        and ArtLevArtGid = @_MagOntArtGid
        and ArtLevNawGid = @_MokNawGid;

      if @_AldGid is not null then
         // Indien een bestelregel is gekoppeld, dan moet de meegegeven @InkoopEenheid overeenkomen met de bestelregel
        if @_MagOntBstRglGid is not null then
          if (select BstRglInkoopEenheid from tabBestelregel where BstRglGid = @_MagOntBstRglGid) <> @_MagOntInkoopEenheid then
            call Raise(20701,_U('Inkoopeenheid in bestelregel komt niet overeen met de meegegeven %1!', 'InkoopEenheid'));   // (20701) Ongeldige combinatie: %1!
          end if;
        end if;
      else
        call Raise(20720,'InkoopEenheid');   // (20720) %1! niet gevonden!
      end if;
    else
      // @InkoopEenheid is niet meegegeven.
      // Is een bestelregel gekoppeld, neem dan de InkoopEenheid over uit de bestelregel, indien aanwezig.
      if @_MagOntBstRglGid is not null then
        select AldGid, AldAantalKanVerschillen, AldHeeftEigenInkoopprijs, AldValNummer, AldInkoopPrijs, AldKortingBedrag, AldKortingPercentage, AldKortingSoort, AldInkoopEenheid,
               AldVoorraadEenhedenInInkoopEenheid, AldArtCodeBijLeverancier, AldNstfKopGid, ArtEanCode
        into @_AldGid, @_AldAantalKanVerschillen, @_AldHeeftEigenInkoopprijs, @_AldValNummer, @_AldInkoopPrijs, @_AldKortingBedrag, @_AldKortingPercentage, @_AldKortingSoort, @_MagOntInkoopEenheid,
             @_MagOntVoorraadEenhedenInInkoopEenheid, @_MagOntArtCodeBijLeverancier, @_AldNstfKopGid, @_MagOntEanCode
        from tabArtikelLeverancier
        inner join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid
        left join tabArtikelEan on ArtEanGid = AldArtEanGid
        where AldInkoopEenheid = isnull((select BstRglInkoopEenheid from tabBestelRegel where BstRglGid = @_MagOntBstRglGid),'')
          and ArtLevArtGid = @_MagOntArtGid
          and ArtLevNawGid = @_MokNawGid;
      end if;

       // Is geen bestelregel gekoppeld of InkoopEenheid is onbekend, dan wordt de VoorraadEenheid toegepast.
       if @_MagOntBstRglGid is null or @_AldGid is null then
          select ArtPrijsPer into @_ArtPrijsPer from tabArtikel where ArtGid = @_MagOntArtGid;
          set @_MagOntInkoopEenheid = @_VkeVerkoopEenheid;
          set @_MagOntVoorraadEenhedenInInkoopEenheid = isnull(@_VkeAantalVoorraadEenhedenInVerkoopEenheid,1);  // Tarief heeft geen Voorraadeenheid, bij tarief altijd waarde 1
          set @_MagOntPrijsPer = @_ArtPrijsPer;
          set @_MagOntEanCode = @_ArtEanCode;
       end if;
    end if;

    // Bepaal InkoopPrijsPer eerst o.b.v. Bestelregel, dan o.b.v. Inkoopeenheid en in alle andere situaties wordt '... Voorraadeenheden' toegepast.
    case
      // Indien bestelregel is gekoppeld, dan altijd overnemen uit de bestelregel.
      when @_MagOntBstRglGid is not null then
        select BstRglPrijsPerSoort, BstRglPrijsPer
          into @_MagOntInkoopprijsPer, @_MagOntPrijsPer
        from tabBestelRegel
        where BstRglGid = @_MagOntBstRglGid;
      // Indien de combinatie Artikel - Leverancier - Inkoopeenheid bestaat en een eigen inkoopprijs heeft,
      // dan overnemen uit Inkoopeenheid, waarde uit @InkoopPrijsPer negeren.
      when @_AldGid is not null and isnull(@_AldHeeftEigenInkoopprijs,0) = 1  then // 1 = Artikel heeft eigen inkoopprijs
        select AldInkoopPrijsPer
          into @_MagOntInkoopprijsPer
        from tabArtikelLeverancierDetail
        where AldGid = @_AldGid;
      // In alle andere situaties wordt VoorraadEenheden toegepast
      else  set @_MagOntInkoopprijsPer = 1;      // 0 = Inkoopeenheid, 1 = ... Voorraadeenheden
    end case;

    // Controle: @VoorraadEenhedenInInkoopEenheid wordt alleen toegepast,
    // indien de combinatie van Artikel - Leverancier - Inkoopeenheid afwijkendende aantallen toestaat en de InkoopEenheid ongelijk is aan de VoorraadEenheid.
    // In alle andere situaties wordt het meegegeven aantal in @VoorraadEenhedenInInkoopEenheid genegeerd.
    if isnull(@_AldAantalKanVerschillen,0) = 1 and isnull(@VoorraadEenhedenInInkoopEenheid,0) > 0 then        // AldAantalKanVerschillen = 1 is Aantal binnen Inkoopeenheid kan verschillen
      if isnull(@_MagOntInkoopEenheid,'') <> (select VkeVerkoopEenheid from tabVerkoopEenheid where VkeArtGid = @_MagOntArtGid and VkeIsVoorraadEenheid = _qcJA) then
        set @_MagOntVoorraadEenhedenInInkoopEenheid = @VoorraadEenhedenInInkoopEenheid;
      end if;
    end if;

    // Controle: @AantalOntvangen moet gespecificeerd zijn.
    if (@AantalOntvangen is not null)  then
      set @_MagOntAantalInkoopEenheden = @AantalOntvangen;                                                                   // Aantal in Inkoopeenheden
      set @_MagOntAantal = @_MagOntAantalInkoopEenheden * isnull(@_MagOntVoorraadEenhedenInInkoopEenheid,1);   // Aantal in Voorraadeenheden
      set @_MagOntLocAantal = @_MagOntAantalInkoopEenheden * isnull(@_MagOntVoorraadEenhedenInInkoopEenheid,1);   // Aantal in Voorraadeenheden
    else
       call Raise(20700,'AantalOntvangen');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien @AantalCorrectie is meegegeven, dan moet dit aantal ongelijk aan 0 zijn en gekoppeld aan een bestelregel
    if isnull(@AantalCorrectie,0) = 0 then
      set @_MagOntAantalCorrectie    = 0;
      set @_MagOntDetAantalCorrectie = 0;
    else
      if @_MagOntBstRglGid is not null and (@AantalCorrectie between -9999999999.999 and 9999999999.999) then   // Grenswaarde i.v.m. Constraint in de database
        set @_MagOntAantalCorrectie    = @AantalCorrectie;
        set @_MagOntDetAantalCorrectie = @AantalCorrectie;
      else
        call Raise(20700,'AantalCorrectie');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: @Inkoopprijs mag alleen worden meegegeven, indien in "Vaste gegevens Inkoop" de 'Inkoopprijs' als inkoopprijs is ingesteld.
    if @_MagVastDefInkoopprijs = 0 then       // @_MagVastDefInkoopprijs = 0 is Vaste verrekenprijs
      if isnull(@InkoopPrijs,0) = 0 then
        // In Vaste gegevens Inkoop staat ingesteld op Vaste verrekenprijs, dan moet de kostprijs van het artikel worden toegepast.
        set @_MagOntInkoopprijs = (select ValutaOmrekenen(@_BasisValNummer,(select ArtKostprijsEx from tabArtikel where ArtGid = @_MagOntArtGid),@_MokValNummer,@_BjGid,@_PerNr,3));     // 3 = Aantal decimalen
      else
        call Raise(20701,_U('%1! is niet toegestaan in combinatie met vaste verrekenprijs', 'InkoopPrijs'));   // (20701) Ongeldige combinatie: %1!
      end if;
    else
      // @_MagVastDefInkoopprijs = 1 is Inkoopprijs
      if isnull(@InkoopPrijs,0) = 0 then
        // @InkoopPrijs is niet meegegeven, dan de kostprijs ophalen uit respectievelijk -> 1.Bestelregel, 2.Partij, 3.Inkoopeenheid en 4.Artikel
        case
          // 1.Bestelregel
          when @_MagOntBstRglGid is not null then
            set @_MagOntInkoopprijs = (select ValutaOmrekenen(@_BstKopValNummer,@_BstRglPrijs,@_MokValNummer,@_BjGid,@_PerNr,3));    // 3 = Aantal decimalen
          // 2.Partij  (Indien geen bestelregel aanwezig is)
          when @_MagOntArtPartijGid is not null then
            set @_MagOntInkoopprijs = (select ValutaOmrekenen(@_ArtPartijInkoopValNummer,@_ArtPartijInkoopPrijs,@_MokValNummer,@_BjGid,@_PerNr,3));    // 3 = Aantal decimalen
          // 3.Inkoopeenheid  (Indien geen bestelregel en partij aanwezig is)
          when @_AldGid is not null and isnull(@_AldHeeftEigenInkoopprijs,0) = 1 then
            set @_MagOntInkoopprijs = (select ValutaOmrekenen(@_AldValNummer,@_AldInkoopPrijs,@_MokValNummer,@_BjGid,@_PerNr,3));      // 3 = Aantal decimalen
          // 4.Artikel  (Indien geen bestelregel, partij en inkoopeenheid aanwezig is)
          else
            set @_MagOntInkoopprijs = (select ValutaOmrekenen(@_BasisValNummer,(select ArtKostprijsEx from tabArtikel where ArtGid = @_MagOntArtGid),@_MokValNummer,@_BjGid,@_PerNr,3));    // 3 = Aantal decimalen
        end case;
      else
        // @Inkoopprijs is meegegeven in de valuta van de Magazijnontvangst
        set @_MagOntInkoopprijs = @InkoopPrijs;
      end if;
    end if;

    // Controle: @Kortingspercentage en @Kortingsbedrag mogen niet samen zijn meegegeven.
    if isnull(@Kortingspercentage,0) <> 0 and isnull(@Kortingsbedrag,0) <> 0 then
      call Raise(20701,_U('%1! en %2! mogen niet beide ingevuld zijn!', 'Kortingsbedrag', 'Kortingspercentage'));   // (20701) Ongeldige combinatie: %1!
    else
      // Alleen @Kortingspercentage is meegegeven.
      if isnull(@Kortingspercentage,0) <> 0 and isnull(@Kortingsbedrag,0) = 0 then
        // @Kortingspercentage mag niet kleiner zijn dan -100 en niet groter zijn dan 100.
        if isnull(@Kortingspercentage,0) < -100 or isnull(@Kortingspercentage,0) > 100 then
          call Raise(20700,'Kortingpercentage');   // (20700) Ongeldige waarde: %1!
        else
          set @_MagOntKortingPercentage = @Kortingspercentage;
          set @_MagOntKortingBedrag = 0;
          set @_MagOntKortingSoort = 1;   // 1 = Kortingspercentage.
        end if;
      end if;
      // Alleen @Kortingsbedrag is meegegeven in de valuta van de Magazijnontvangst
      if isnull(@Kortingspercentage,0) = 0 and isnull(@Kortingsbedrag,0) <> 0 then
        set @_MagOntKortingBedrag = @Kortingsbedrag;
        set @_MagOntKortingPercentage = 0;
        set @_MagOntKortingSoort = 0;   // 0 = Kortingsbedrag.
      end if;
    end if;

    // Controle: Indien @Kortingspercentage en @Kortingsbedrag niet zijn meegegeven,
    //           dan eventuele korting bepalen o.b.v. respectievelijk 1.Bestelregel, 2.Partij, 3.Inkoopeenheid 4.Geen korting.
    if @Kortingspercentage is null and @Kortingsbedrag is null then
      case
         // 1.Bestelregel
        when @_MagOntBstRglGid is not null then
          if @_BstRglKortingSoort = 0 then   // 0 = Kortingsbedrag
            set @_MagOntKortingSoort = @_BstRglKortingSoort;
            set @_MagOntKortingBedrag     = (select ValutaOmrekenen(@_BstKopValNummer,@_BstRglKortingBedrag,@_MokValNummer,@_BjGid,@_PerNr,3));     // 3 = Aantal decimalen
            set @_MagOntKortingPercentage = 0;
          else                               // 1 = Kortingspercentage
            set @_MagOntKortingSoort = @_BstRglKortingSoort;
            set @_MagOntKortingPercentage = @_BstRglKortingPercentage;
            set @_MagOntKortingBedrag = 0;
          end if;
         // 2.Partij (Indien geen bestelregel aanwezig is)
        when @_MagOntArtPartijGid is not null then
          set @_MagOntKortingSoort = 0;    // 1 = Kortingsbedrag
          set @_MagOntKortingBedrag = 0;
          set @_MagOntKortingPercentage = 0;
         // 3.Inkoopeenheid  (Indien geen bestelregel en partij aanwezig is)
        when @_AldGid is not null then
          case
            when @_AldKortingSoort = 0 then        // 0 = Kortingsbedrag
              set @_MagOntKortingSoort = @_AldKortingSoort;
              set @_MagOntKortingBedrag = (select ValutaOmrekenen(@_AldValNummer,@_AldKortingBedrag,@_MokValNummer,@_BjGid,@_PerNr,3));     // 3 = Aantal decimalen
              set @_MagOntKortingPercentage = 0;
            when @_AldKortingSoort = 1 then         // 1 = Kortingspercentage
              set @_MagOntKortingSoort = @_AldKortingSoort;
              set @_MagOntKortingBedrag = 0;
              set @_MagOntKortingPercentage = @_AldKortingPercentage;
            when @_AldKortingSoort = 2 then         // 2 = Staffelkorting
              if (select NstfKopSoort from tabNawStaffelKop where NstfKopGid = @_AldNstfKopGid) = 0 then     // 0 = Staffel Kortingsbedrag
              // Staffelkorting is bedrag
                select first NstfKopSoort, (select ValutaOmrekenen(@_AldValNummer,NstfRglBedrag,@_MokValNummer,@_BjGid,@_PerNr,3)), 0
                  into @_MagOntKortingSoort, @_MagOntKortingBedrag, @_MagOntKortingPercentage
                from tabNawStaffelKop
                inner join tabNawStaffelRegel on NstfRglNstfKopGid = NstfKopGid
                where NstfKopGid = @_AldNstfKopGid
                  and NstfRglVanafAantal <= @_MagOntAantalInkoopEenheden
                order by NstfRglVanafAantal desc;
              else // Staffelkorting is percentage
                select first NstfKopSoort, NstfRglPercentage, 0
                  into @_MagOntKortingSoort, @_MagOntKortingPercentage, @_MagOntKortingBedrag
                from tabNawStaffelKop
                inner join tabNawStaffelRegel on NstfRglNstfKopGid = NstfKopGid
                where NstfKopGid = @_AldNstfKopGid
                  and NstfRglVanafAantal <= @_MagOntAantalInkoopEenheden
                order by NstfRglVanafAantal desc;
              end if;
          end case;
        // 4.Geen inkoopkorting  (Indien geen bestelregel, partij en inkoopeenheid aanwezig is)
        else
          set @_MagOntKortingSoort = 1;    // 1 = Kortingspercentage
          set @_MagOntKortingBedrag = 0;
          set @_MagOntKortingPercentage = 0;
      end case;
    end if;

    // Controle: Indien @BTWCode is meegegeven, dan moet dit een bestaande BTW code t.b.v. inkoop zijn.
    //           Indien @BTWCode niet is meegegeven, dan wordt de Btw code inkoop van het artikel toegepast.
    if @BTWCode is not null then
      // @BTWCode is meegegeven
      if exists(select 1 from tabBtw where BtwCode = @BTWCode and BtwSoort = 2) then     // BtwSoort: 2 = Te verrekenen (inkoop)
        set @_MagOntBtwCode = @BTWCode;
      else
        call Raise(20700,'BtwCode');   // (20700) Ongeldige waarde: %1!
      end if;
    else
      // @BTWCode is niet meegegeven
      select ArtBtwCodeInkoop into @_MagOntBtwCode from tabArtikel where ArtGid = @_MagOntArtGid;
    end if;

    // Opmerking t.b.v. de magazijn ontvangst
    set @_MagOntOpm = isnull(@Opmerking,'');

    // Controle: Indien @StandaardSpecificatieRegel is meegegeven, dan moet dit wel "JA" of "NEE" zijn.
    //           Indien @StandaardSpecificatieRegel niet is meegegeven, dan is de default waarde "JA"
    //           Indien @ArtikelSoort = 'TAR', dan altijd op "NEE"
    if @ArtikelSoort = 'ART' then
      case
        when isnull(@StandaardSpecificatieRegel,'JA') = 'JA' then
          set @_DefaultSpecificatie = _qcJA;                    // 1 = Wel default specificatieregel
        when isnull(@StandaardSpecificatieRegel,'JA') = 'NEE' then
          set @_DefaultSpecificatie = _qcNEE;                    // 0 = Geen default specificatieregel
        else
          call Raise(20700,'StandaardSpecificatieRegel');     // (20700) Ongeldige waarde: %1!
      end case;
    else
      set @_DefaultSpecificatie = _qcNEE; // 0 = Geen default specificatieregel
    end if;

    // Controle: Automatisch specificatie regel toevoegen mag alleen als de ontvangstregel niet is gekoppeld aan een verkooporder
    if @_DefaultSpecificatie = _qcJA and @_MagOntDetKoppeling = 2 then     // @_DefaultSpecificatie: 1 = Wel default specificatieregel, @_MagOntDetKoppeling: 2 = Verkooporder
       call Raise(20780,_U('Automatisch specificatieregel toevoegen is'),_U('Ontvangstregel is gekoppeld aan een verkooporder'));     // (20780) %1! niet mogelijk: %2!
    end if;

    if @_DefaultSpecificatie = _qcJA then //Wel specificatieregel toevoegen
    begin
      declare @_LocBlokkade smallint = _qcNEE;

      select GeefLocatieVoorMagazijnOntvangst(@_MokMagGid, null, @_MagOntArtGid, null, @_MokGid) as LocGidVoorkeur, LocBlokkade
        into @_MagOntLocLocGid, @_LocBlokkade
      from tabLocatie
      where LocGid = LocGidVoorkeur;

      if @_LocBlokkade = _qcJA then
        //Locatie is geblokkeerd voor het plaatsen van artikelen!
        call Raise(20780,_U('Automatisch specificatieregel toevoegen is'),_U('Locatie is geblokkeerd voor het plaatsen van artikelen')); // (20780) %1! niet mogelijk: %2!
      end if;
    end;
    end if;

    // Ophalen CBS gegevens uit Vaste gegevens CBS
    select CbsVastPreferentieCodeInvoer, isnull(CbsVastTaricInvoer,''), isnull(CbsVastCbsTrGidInvoer,'')
    into @_MagOntCbsPreferentieCode, @_MagOntCbsTaric, @_MagOntCbsTrGid
    from tabCbsVast;

    // Controleren CBS landcode oorsprong
    if IsNull(@CbsLandOorsprong, '') <> '' then
      select first LndGid into @_MagOntCBSLndGidOorsprong from tabLand where LndEigenCode = @CbsLandOorsprong;
      if (@_MagOntCBSLndGidOorsprong is null) then
        call Raise(20698); // Ongeldige of geen CbsLandOorsprong meegegeven!
      end if;
    else
      set @_MagOntCBSLndGidOorsprong = (select first IsNull(ArtPartijLndGidCbsOorsprong, IsNull(AldLndGidCBSOorsprong, ArtLndGidCbsOorsprong))
                                        from tabArtikel
                                        left outer join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijGid = @_MagOntArtPartijGid
                                        left outer join (tabArtikelLeverancier
                                            inner join tabArtikelLeverancierDetail on AldArtLevGid = ArtLevGid and AldInkoopEenheid = @_MagOntInkoopEenheid
                                                        ) on ArtLevArtGid = ArtGid and ArtLevNawGid = @_MokNawGid
                                        where ArtGid = @_MagOntArtGid);
    end if;

    // Douaneregeling
    if @CbsDouaneregeling is null then
      select CbsVastDouaneregelingInvoer into @_MagOntCbsDouaneregeling from tabCbsVast;
    else
      set @_MagOntCbsDouaneregeling = @CbsDouaneregeling;
    end if;

    // Genereer regelnummer t.b.v. magazijnontvangstregel.
    select isnull((max(MagOntRegelNr) + 1),1) into @_MagOntRegelNr from tabMagazijnOntvangsten where MagOntMokGid = @_MokGid;

    // Gegevens bijwerken in de database
    insert into tabMagazijnOntvangsten with auto name
    select @_MagOntMokGid as MagOntMokGid,
           @_MagOntArtGid as MagOntArtGid,
           @_MagOntArtPartijGid as MagOntArtPartijGid,
           @_MagOntBstRglGid as MagOntBstRglGid,
           @_MagOntBstRglOms as MagOntBstRglOms,
           @_MagOntBtwCode as MagOntBtwCode,
           @_MagOntAantal as MagOntAantal,
           @_MagOntAantalCorrectie as MagOntAantalCorrectie,
           @_MagOntAantalInkoopEenheden as MagOntAantalInkoopEenheden,
           isnull(@_MagOntArtCodeBijLeverancier,'') as MagOntArtCodeBijLeverancier,
           isnull(@_MagOntEanCode,'') as MagOntEanCode,
           @_MagOntInkoopEenheid as MagOntInkoopEenheid,
           @_MagOntInkoopprijs as MagOntInkoopprijs,
           @_MagOntInkoopprijsPer as MagOntInkoopprijsPer,
           @_MagOntKortingBedrag as MagOntKortingBedrag,
           @_MagOntKortingPercentage as MagOntKortingPercentage,
           @_MagOntKortingSoort as MagontKortingSoort,
           isnull(nullif(@_MagOntPrijsPer,0),1) as MagOntPrijsPer, // Constraint ASA 904 > 0 en <= 9999999999.999
           @_MagOntRegelNr as MagOntRegelNr,
           @_MagOntRegelSoort as MagOntRegelSoort,
           @_MagOntOpm as MagOntOpm,
           @_MagOntVoorraadEenhedenInInkoopEenheid  as MagOntVoorraadEenhedenInInkoopEenheid,
           @_MagOntCbsLndGidOorsprong as MagOntCbsLndGidOOrsprong,
           @_MagOntCbsDouaneregeling as MagOntCbsDouaneregeling,
           @_MagOntCbsPreferentieCode as MagOntCbsPreferentieCode,
           @_MagOntCbsTaric as MagOntCbsTaric,
           @_MagOntCbsTrGid as MagOntCbsTrGid;

    set @_MagOntDetMagOntGid = @@Identity;

    // Detail alleen toevoegen indien sprake is van een Magazijnontvangst
    // I.c.m. met Directe inkoop, moeten aparte webservices worden gebruikt
    if @_DefaultSpecificatie = _qcJA then     // 1 = Wel specificatieregel toevoegen
       insert into tabMagazijnOntvangstenDetail with auto name
       select @_MagOntDetMagOntGid as MagOntDetMagOntGid,
              @_MagOntDetbrdGid as MagOntDetbrdGid,
              null as MagOntDetOrrGid,
              @_MagOntDetAantalCorrectie as MagOntDetAantalCorrectie,
              '' as MagOntDetAdrNaam1,
              @_MagOntDetBrdSoort as MagOntDetBrdSoort,
              @_MagOntDetKoppeling as MagOntDetKoppeling,
              '' as MagOntDetNawFilNummer,
              0 as MagOntDetOrkNummer,
              0 as MagOntDetOrrRegelNr;
       set @_MagOntLocMagOntDetGid = @@Identity;

       insert into tabMagazijnOntvangstLocatieSerie with auto name
       select @_MagOntLocMagOntDetGid as MagOntLocMagOntDetGid,
              null as MagOntLocArtSerieGid,
              @_MagOntLocLocGid as MagOntLocLocGid,
              @_MagOntLocAantal as MagOntLocAantal,
              0 as MagOntLocIsSerieNetAangemaakt;
    end if;

    set @_RegelNummer = @_MagOntRegelNr;
  end;  //Einde atomic

  // Ophalen resultaat
  select @_RegelNummer as OntvangstRegelNummer;

  set @@ErrorTextProcedure = 'WebSvcHulpProc_Magazijnontvangst_OntvangstRegel_Toevoegen > ';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcHulpProc_ValideerNawEanCode(
  in @EanCode nchar(13) ,
  in @FonId char(3) default null, // c = crediteur, d = debiteur, b = bedrijfsgegevens, ??? = relatie
  in @NawGid integer default null, // Indien ingevuld, wordt getoetst of EAN code bij NAW hoort ( let op de FonId!)
  in @ControleerFormaatEanCode smallint default 1, // indien 1, dan wordt er gecontroleerd of eancode voldoet aan het ucc-13 formaat
  out @_NawEanCode nchar(13) default null, // de gevalideerde EAN code
  out @_NawGidEan integer default null) // de NAW waar het bij hoort.
begin
  set @_NawEanCode = trim(@EanCode);
  set @_NawGidEan = null;

  if (isnull(@_NawEanCode,'')  = '') then
    set @NawGid = null;
  else
    if (@ControleerFormaatEanCode = 1) and (length(@_NawEanCode) < 13) then
      call Raise(20700, _U('%1!, deze moet minstens %2! cijfers zijn.', 'EAN Code', '13'));
    end if;

    //ean code mag niet die van een artikel zijn.
    if exists(select first 1 from tabArtikelEan where ArtEanCode = @_NawEanCode) then
      call Raise(20700, _U('%1!, deze komt bij een artikel voor.', 'EAN Code'));
    end if;

    // kijk even of je een NAW hebt waar dat EAN code bekend is.
    //adresgegevens: vestigingsadres, eindadres, correspondentieadres, verzendadres...
    select first NawGid
      into @_NawGidEan
    from tabNaw
      inner join tabAdres on  (AdrEanCode = @_NawEanCode) and (AdrGid in (NawGidVestiging, NawGidEindAdres, NawGidCorrespondentie, NawGidVerzendAdres))
      inner join tabNawFile on  NawFilNawGid = NawGid and ( @NawGid is null or NawGid = @NawGid )
      inner join tabFileOfNaw on  FonGid = NawFilFonGid and FonId = trim(@FonId)
    order by NawGid asc;

    // Het is een nieuwe EAN die nog niet in king bij de FonID bestaat dan wel even checken dat de opgegeven EAN code deugt.
    // Heb je al een EAN gevonden bij een NAW dan is die al valide...
    if (@ControleerFormaatEanCode = 1) and (@_NawGidEan is null) and (@NawGid is null) then
      // draai de EAN even om, en vul rechts uit met nullen tot maximum lengte
      Set @_NawEanCode = left(reverse(@_NawEanCode) + '00000000000000', 14) ;

      if PATINDEX('[^0-9]', @_NawEanCode) <> 0 then
        set @_NawEanCode = null;
        call Raise(20700, _U('%1! alleen cijfers zijn toegestaan', 'EAN code'));   // Ongeldige waarde: %1
      end if;

      if ( 10 - ( 3 * substring(@_NawEanCode,2,1)
                + 1 * substring(@_NawEanCode,3,1)
                + 3 * substring(@_NawEanCode,4,1)
                + 1 * substring(@_NawEanCode,5,1)
                + 3 * substring(@_NawEanCode,6,1)
                + 1 * substring(@_NawEanCode,7,1)
                + 3 * substring(@_NawEanCode,8,1)
                + 1 * substring(@_NawEanCode,9,1)
                + 3 * substring(@_NawEanCode,10,1)
                + 1 * substring(@_NawEanCode,11,1)
                + 3 * substring(@_NawEanCode,12,1)
                + 1 * substring(@_NawEanCode,13,1)
                + 3 * substring(@_NawEanCode,14,1) ) % 10 ) <> substring(@_NawEanCode,1,1) then
        set @_NawEanCode = null;
        call Raise(20700, _U('%1!, validatie controlecijfer.', 'EAN code'));   // Ongeldige waarde: %1
      end if;
    end if;

    // wij zijn hier uit gekomen, dan is het EAN code goed.
    set @_NawEanCode = trim(@EanCode); // schoon opleveren, geen spaties eromheen.

  end if;
end;


create or replace procedure WebSvcProc_MagazijnOntvangst_LockVrijgeven(in @OntvangstNummer numeric(10,0))
begin
  declare @_MokGid integer;
  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabMagazijnOntvangstenKop';
  declare @_LockUserNaam nchar(40) = 'KingWebService';

  //call TraceBegin('WebSvcProc_MagazijnOntvangst_LockVrijgeven');

  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen magazijnontvangsten doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790, _U('Optie Voorraad')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken MagazijnOntvangst
  select MokGid into @_MokGid
  from tabMagazijnOntvangstenKop
  where MokNummer = @OntvangstNummer;
  if @_MokGid is null then
    call Raise(20720, 'OntvangstNummer'); // (20720) niet gevonden: %1!
  end if;

  //Elke api heeft zijn eigen connection id.
  //Het standaard lockmechanisme werkt in dat geval dan niet.
  //het vrij geven van een lock gaat dan niet op SpId, maar op usernaam
  begin // lock vrijgeven
    call LockReleaseOnId(@@SpId, @@LoginTime, 1, _QLOCKTABLENAME, @_MokGid);

    // gelockt, maar niet door KingWebService? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = _QLOCKTABLENAME and qLockPKey = String(@_MokGid) and qLockUser <> @_LockUserNaam) then
      call Raise(20741, _U('Magazijnontvangst')); // (20741) %1! is in gebruik!
    end if;

    // De record zou dus wel door KingWebService gelockt zijn, deze opruimen.
    call LockReleaseOnUserName(@_LockUserNaam, 1, _QLOCKTABLENAME, @_MokGid);
  end; // lock vrijgeven

  //call TraceEind('WebSvcProc_MagazijnOntvangst_LockVrijgeven');
end;

create or replace procedure WebSvcProc_Magazijnontvangst_OntvangstRegel_Detail_Toevoegen
( in @OntvangstNummer       numeric(10,0),
  in @OntvangstRegelNummer  numeric(3,0),
  in @DetailRegelSoort      nchar(12),             // Waarden: "MAGAZIJN" of "VERKOOPORDER"
  in @VerkoopOrderNummer    numeric(10,0),
  in @OrderRegelNummer      numeric(3,0),
  in @DetailAantalCorrectie numeric(15,3))

result (DetailIdNummer integer)

begin
  declare @_IDnummerDetail integer;

  // T.b.v. locken
  declare @_LockUserNaam nchar(40) = 'KingWebService';
  declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId       wordt gebruikt
  declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt

  //call TraceBegin('WebSvcProc_Magazijnontvangst_OntvangstRegel_Detail_Toevoegen > @OntvangstNummer = ' + @OntvangstNummer);

  // Module controle
  if IsModuleActive('w7') = 0 then // Module Webservices Logistiek
    call Raise(20790,_U('Optie Webservices logistiek')); // (20790) '%1!' niet geactiveerd!
  end if;

  if IsModuleActive('d2') = 0 and isnull(@DetailRegelSoort,'') = 'VERKOOPORDER' then // Module Directe inkoop
    call Raise(20790,_U('Optie Directe inkoop')); // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    declare @_MokGid                   integer;
    declare @_MokMagGid                integer;
    declare @_MokNawGid                integer;
    declare @_MagOntArtGid             integer;
    declare @_MagOntBstRglGid          integer;
    declare @_OrkGid                   integer;
    declare @_OrrRegelsoort            smallint;
    // tabMagazijnOntvangstenDetail
    declare @_MagOntDetMagOntGid       integer;
    declare @_MagOntDetAantalCorrectie numeric(15,3);       // Constraint -9999999999.999 t/m 9999999999.999
    declare @_MagOntDetAdrNaam1        nchar(40);
    declare @_MagOntDetbrdGid          integer;
    declare @_MagOntDetBrdSoort        smallint;            // 0 = Magazijn, 1 = Verkooporder
    declare @_MagOntDetKoppeling       smallint;            // 0 = Magazijn, 1 = Bestelling, 2 = Verkooporder
    declare @_MagOntDetNawFilNummer    nchar(20);
    declare @_MagOntDetOrkNummer       numeric(10,0);
    declare @_MagOntDetOrrGid          integer;
    declare @_MagOntDetOrrRegelNr      smallint;

    // Opzoeken onderhanden Magazijnontvangstkop
    select MokGid,MokMagGid, MokNawGid
      into @_MokGid, @_MokMagGid, @_MokNawGid
    from tabMagazijnOntvangstenKop
    where MokNummer = @OntvangstNummer;

    if  @_MokGid is null then
      call Raise(20780,_U('Magazijnontvangst wijzigen is'),_U('Ongeldige of geen %1! meegegeven', 'OntvangstNummer'));     // (20780) %1! niet mogelijk: %2!
    end if;

    // Gevonden Magazijnontvangst locken of bestaande lock overnemen
    call WebSvcHulpProc_MagazijnontvangstExclusiefLocken(@_MokGid, @_LockUserNaam, @_Spid, @_LoginTime);

    // Controle: @OntvangstRegelNummer moet een bestaande Magazijnontvangstregel zijn
    if isnull(@OntvangstRegelNummer,0) > 0 then
      select MagOntGid, MagOntArtGid, MagOntBstRglGid
        into @_MagOntDetMagOntGid, @_MagOntArtGid, @_MagOntBstRglGid
      from tabMagazijnOntvangsten
      where MagOntMokGid  = @_MokGid
        and MagOntRegelNr = @OntvangstRegelNummer;
      if @_MagOntDetMagOntGid is null then
        call Raise(20720,'OntvangstRegelNummer');   // (20720) %1! niet gevonden!
      end if;
    else
      call Raise(20700,'OntvangstRegelNummer');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: @DetailRegelSoort moet 'MAGAZIJN' of 'VERKOOPORDER' zijn
    case
      when isnull(@DetailRegelSoort,'') = 'MAGAZIJN'     then set @_MagOntDetBrdSoort = 0     // @_MagOntDetBrdSoort: 0 = Magazijn
      when isnull(@DetailRegelSoort,'') = 'VERKOOPORDER' then set @_MagOntDetBrdSoort = 1     // @_MagOntDetBrdSoort: 1 = Verkooporder
      else call Raise(20700,'DetailRegelSoort');   // (20700) Ongeldige waarde: %1!
    end case;

    // Controle: Er mag maar 1 detailregel aanwezig zijn per ontvangstregel met Soort = 'Magazijn'
    if @_MagOntDetBrdSoort = 0 then   // @_MagOntDetBrdSoort: 0 = Magazijn
      if exists(select 1 from tabMagazijnOntvangstenDetail where MagOntDetMagOntGid = @_MagOntDetMagOntGid and MagOntDetBrdSoort = 0) then     // MagOntDetBrdSoort: 0 = Magazijn
        call Raise(20780,_U('Detailregel toevoegen is'),_U('Detailregel met soort ''Magazijn'' is al aanwezig'));     // (20780) %1! niet mogelijk: %2!
      end if;
    end if;

    // Controle: Indien @DetailRegelSoort = 'VERKOOPORDER' dan moet een bestaande verkooporder (@VerkoopOrderNummer) en regelnummer (@OrderRegelNummer) met overeenkomende artikel worden meegegeven.
    //           Inhoud van @VerkoopOrderNummer en @OrderRegelNummer worden genegeerd indien @DetailRegelSoort = 'MAGAZIJN' is.
    if @_MagOntDetBrdSoort = 1 then      // @_MagOntDetBrdSoort: 1 = Verkooporder
      if isnull(@VerkoopOrderNummer,0) <> 0 then
          // Haal de benodigde gegevens op van de verkooporder
        select OrkGid, OrkNummer, NawFilNummer, AdrNaam1
          into @_OrkGid, @_MagOntDetOrkNummer, @_MagOntDetNawFilNummer, @_MagOntDetAdrNaam1
        from tabOrderKop
        inner join tabNaw on NawGid = OrkNawGid
        inner join tabNawFile on NawFilNawGid = NawGid
        inner join tabAdres on AdrGid = NawGidVestiging
        where OrkNummer = @VerkoopOrderNummer;

        if @_OrkGid is null then
           call Raise(20720,'VerkoopOrderNummer');   // (20720) %1! niet gevonden!
        end if;
      else
        call Raise(20700,'VerkoopOrderNummer');   // (20700) Ongeldige waarde: %1!
      end if;
       if isnull(@OrderRegelNummer,0) <> 0 then
          // Haal de benodigde orderregel gegevens op
          select OrrGid, OrrRegelnr, OrrRegelsoort, brdGid
            into @_MagOntDetOrrGid, @_MagOntDetOrrRegelNr, @_OrrRegelsoort, @_MagOntDetbrdGid
          from tabOrderRegel
          left join tabBestelRegelDetail on brdBstRglGid = @_MagOntBstRglGid and brdOrrGid = OrrGid
          where OrrOrkGid  = @_OrkGid               // Orderregel uit meegegeven verkooporder
            and OrrArtGid  = @_MagOntArtGid         // Artikel uit orderregel komt overeen met de Magazijnontvangstregel
            and OrrRegelnr = @OrderRegelNummer;     // Regelnummer komt overeen met meegegeven @OrderRegelNummer

          if @_MagOntDetOrrGid is null then
             call Raise(20720,'OrderRegelNummer');   // (20720) %1! niet gevonden!
          end if;
          if @_OrrRegelsoort = 1 then      // @_OrrRegelsoort: 1 = Tarief
             call Raise(20701,_U('Tarief is niet toegestaan in combinatie met directe inkoop'));    // (20701) Ongeldige combinatie: %1!
          end if;
          // Orderregel mag niet zijn gekoppeld aan zowel een bestelregel als een magazijnontvangstregel (Error 20339)
          if @_MagOntDetbrdGid is not null then   // Orderregel is gekoppeld aan bestelregel
             set @_MagOntDetOrrGid = null;        // Magazijnontvangstregel niet koppelen aan orderregel
          end if;
       else
          call Raise(20700,'OrderRegelNummer');   // (20700) Ongeldige waarde: %1!
       end if;
    else  // @_MagOntDetBrdSoort: 0 = Magazijn
      set @_MagOntDetOrkNummer = 0;
      set @_MagOntDetOrrRegelNr = 0;
      set @_MagOntDetNawFilNummer = '';
      set @_MagOntDetAdrNaam1 = '';
      set @_MagOntDetOrrGid = null;
      // Als de ontvangsregel is gekoppeld aan een bestelregel, dan ook het het gidje van de bestelregeldetail ophalen.
      if @_MagOntBstRglGid is not null then
         select brdGid into @_MagOntDetbrdGid from tabBestelRegelDetail where brdBstRglGid = @_MagOntBstRglGid and brdSoort = 0;        // brdSoort: 0 = Magazijn
      else
         set @_MagOntDetbrdGid = null;
      end if;
    end if;

    // Bepaal de soort koppeling van de magazijnontvangstregel
    case
      when @_MagOntDetOrrGid is not null then set @_MagOntDetKoppeling = 2;     // @_MagOntDetKoppeling: 2 = Verkooporder
      when @_MagOntBstRglGid is not null then set @_MagOntDetKoppeling = 1;     // @_MagOntDetKoppeling: 1 = Bestelling
      else                                    set @_MagOntDetKoppeling = 0;     // @_MagOntDetKoppeling: 0 = Magazijn
    end case;

    // Controle: Indien @DetailAantalCorrectie is meegegeven, dan moet dit aantal ongelijk zijn aan 0 en zijn gekoppeld aan een bestelregel
    if isnull(@DetailAantalCorrectie,0) = 0 then
      set @_MagOntDetAantalCorrectie = 0;
    else
      if (@_MagOntBstRglGid is not null) and (@_MagOntDetKoppeling = 1) and (@DetailAantalCorrectie between -9999999999.999 and 9999999999.999) then   // Grenswaarde i.v.m. Constraint in de database
        set @_MagOntDetAantalCorrectie = @DetailAantalCorrectie;
      else
        call Raise(20700,'DetailAantalCorrectie');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Detailregel toevoegen aan de Magazijnontvangstregel
    insert into tabMagazijnOntvangstenDetail with auto name
    select @_MagOntDetMagOntGid as MagOntDetMagOntGid,
           @_MagOntDetbrdGid as MagOntDetbrdGid,
           @_MagOntDetOrrGid as MagOntDetOrrGid,
           @_MagOntDetAantalCorrectie as MagOntDetAantalCorrectie,
           @_MagOntDetAdrNaam1 as MagOntDetAdrNaam1,
           @_MagOntDetBrdSoort as MagOntDetBrdSoort,
           @_MagOntDetKoppeling as MagOntDetKoppeling,
           @_MagOntDetNawFilNummer as MagOntDetNawFilNummer,
           @_MagOntDetOrkNummer as MagOntDetOrkNummer,
           @_MagOntDetOrrRegelNr as MagOntDetOrrRegelNr;
    set @_IDnummerDetail = @@Identity;

  end;    // Einde atomic

  // Ophalen resultaat
  select @_IDnummerDetail as DetailIdNummer;
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Magazijnontvangst_OntvangstRegel_LocatieSerie_Toevoegen
( in @OntvangstNummer numeric(10,0),
  in @IDnummerDetail  integer,
  in @Locatie         nchar(20),
  in @SerieNummer     nchar(20),
  in @AantalOntvangen numeric(15,3))

begin
  //Constanten
  declare _qcNEE smallint = 0;
  declare _qcJA smallint = 1;

  // T.b.v. locken
  declare @_LockUserNaam nchar(40) = 'KingWebService';
  declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId       wordt gebruikt
  declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt

  // call TraceBegin('WebSvcProc_Magazijnontvangst_OntvangstRegel_Detail_Toevoegen > @OntvangstNummer = ' + @OntvangstNummer);

  // Module controle
  if IsModuleActive('w7') = _qcNEE then                                          // Module Webservices Logistiek
    call Raise(20790,_U('Optie Webservices logistiek'));                      // (20790) '%1!' niet geactiveerd!
  end if;

  if IsModuleActive('s1') = _qcNEE and isnull(@SerieNummer,'') <> '' then        // Module Serienummers
     call Raise(20790,_U('Optie Serienummers'));                                  // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    declare @_MagVastDefLocatie        smallint;
    declare @_MokGid                   integer;
    declare @_MokMagGid                integer;
    declare @_MagOntGid                integer;
    declare @_MagOntArtGid             integer;
    declare @_MagOntAantal             numeric(15,3);
    declare @_MagOntArtPartijGid       integer;
    declare @_ArtSerieNrRegistreren    smallint;
    declare @_ArtSerieNrAanmakenBij    smallint;
    declare @_ArtSerieArtPartijGid     integer;
    // tabMagazijnOntvangstLocatieSerie
    declare @_MagOntLocMagOntDetGid    integer;
    declare @_MagOntLocArtSerieGid     integer;
    declare @_MagOntLocLocGid          integer;
    declare @_MagOntLocAantal          numeric(15,3);

    // Ophalen benodigde gegevens uit Vaste gegevens Inkopen
    select MagVastDefLocatie
      into @_MagVastDefLocatie
    from tabMagazijnOntvangstenVastegegevens
    where MagVastId = 1;

    // Opzoeken onderhanden Magazijnontvangstkop
    select MokGid, MokMagGid
      into @_MokGid, @_MokMagGid
    from tabMagazijnOntvangstenKop
    where MokNummer = @OntvangstNummer;

    if  @_MokGid is null then
      call Raise(20780,_U('Magazijnontvangst wijzigen is'),_U('Ongeldige of geen %1! meegegeven', 'OntvangstNummer'));     // (20780) %1! niet mogelijk: %2!
    end if;

    // Gevonden Magazijnontvangst locken of bestaande lock overnemen
    call WebSvcHulpProc_MagazijnontvangstExclusiefLocken(@_MokGid, @_LockUserNaam, @_Spid, @_LoginTime);

    // Controle: @IDnummerDetail moet een bestaande Detailregel zijn binnen de magazijnontvangst
    if isnull(@IDnummerDetail,0) > 0 then
      select MagOntGid, MagOntDetGid, MagOntArtGid, MagOntAantal, MagOntArtPartijGid, ArtSerieNrRegistreren, ArtSerieNrAanmakenBij
        into @_MagOntGid, @_MagOntLocMagOntDetGid, @_MagOntArtGid, @_MagOntAantal, @_MagOntArtPartijGid, @_ArtSerieNrRegistreren, @_ArtSerieNrAanmakenBij
      from tabMagazijnOntvangstenDetail
      inner join tabMagazijnOntvangsten on MagOntMokGid = @_MokGid and MagOntGid = MagOntDetMagOntGid
      inner join tabArtikel on ArtGid = MagOntArtGid
      where MagOntDetGid = @IDnummerDetail;

      if @_MagOntLocMagOntDetGid is null then
        call Raise(20720,'IDnummerDetail');   // (20720) %1! niet gevonden!
      end if;
    else
      call Raise(20700,'IDnummerDetail');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Indien meegegeven, dan moet @Locatie een bestaande locatie zijn binnen het magazijn van de magazijnontvangst
    //           Indien niet meegegeven, dan wordt de instelling uit de Vaste gegeven inkopen toegepast.
    begin
      declare @_LocBlokkade smallint default _qcNEE;

      if isnull(@Locatie,'') <> '' then
        // @Locatie is meegegeven
        select LocGid, LocBlokkade
          into @_MagOntLocLocGid, @_LocBlokkade
        from tabLocatie
        where LocMagGid = @_MokMagGid           // Uitsluitend locaties uit het magazijn van de magazijnontvangst
          and LocNaam   = @Locatie;

        if @_MagOntLocLocGid is null then
          call Raise(20720,_U('Locatie'));   // (20720) %1! niet gevonden!
        end if;
      else
        // @Locatie is niet meegegeven
        select GeefLocatieVoorMagazijnOntvangst(@_MokMagGid, null, @_MagOntArtGid, null, @_MokGid) as LocGidVoorkeur, LocBlokkade
          into @_MagOntLocLocGid, @_LocBlokkade
        from tabLocatie
        where LocGid = LocGidVoorkeur;
      end if;

      if @_LocBlokkade = _qcJA then
        //Locatie is geblokkeerd voor het plaatsen van artikelen!
        call Raise(20780,_U('Locatie gebruiken is'),_U('Locatie is geblokkeerd voor het plaatsen van artikelen'));     // (20780) %1! niet mogelijk: %2!
      end if;
    end;

    // Controle: @SerieNummer is verplicht indien artikel Serienummer registrerend is en "Moment van registratie" is ingesteld op 'Bij invoeren magazijnontvangst'
    //           Meegegeven @Serienummer moet wel een bestaand serienummer zijn binnen het artikel
    if isnull(@SerieNummer,'') <> '' then
      // @Serienummer is meegegeven
      if @_ArtSerieNrRegistreren = _qcNEE then      // @_ArtSerieNrRegistreren: 0 = Artikel is NIET serienummer registrerend
        call Raise(20780,_U('Serienummer toekennen is'),_U('Artikel is niet serienummer registrerend'));     // (20780) %1! niet mogelijk: %2!
      else
        // Artikel is wel serienummer registrerend
        select ArtSerieGid , ArtSeriePartijGid
          into @_MagOntLocArtSerieGid , @_ArtSerieArtPartijGid
        from tabArtikelSerienummer
        where ArtSerieArtGid = @_MagOntArtGid
          and ArtSerienummer = @Serienummer;

        if @_MagOntLocArtSerieGid is null then
          call Raise(20720,'Serienummer');   // (20720) %1! niet gevonden!
        end if;

        // Controle: Eventueel meegegeven partijnummer in de magazijnontvangsregel moet overeenkomen met het partijnummer van het Serienummer
        if @_MagOntArtPartijGid is not null and @_MagOntArtPartijGid <> @_ArtSerieArtPartijGid then
          call Raise(20780,_U('Serienummer gebruiken is'),_U('Partijnummer van serienummer komt niet overeen met magazijnontvangstregel'));     // (20780) %1! niet mogelijk: %2!
        end if;
      end if;
    else
      // @Serienummer is niet meegegeven, dan wel even controleren of het serienummer toch verplicht is
      if @_ArtSerieNrRegistreren = _qcJA and @_ArtSerieNrAanmakenBij = _qcNEE then   // @_ArtSerieNrRegistreren: 1 = Artikel is serienummer registrerend, @_ArtSerieNrAanmakenBij: 0 = Magazijnontvangst
        call Raise(20700,'Serienummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Indien @Serienummer verplicht is meegegeven, dan moet in @AantalOntvangen verplicht de waarde -1 of 1 worden meegegeven.
    //           Indien @Serienummer niet verplicht is meegegeven en @AantalOntvangen is niet meegegeven, dan wordt het aantal uit de Magazijnontvangstregel overgenomen.
    if (isnull(@SerieNummer,'') <> '') and (isnull(@AantalOntvangen,0) <> -1 and isnull(@AantalOntvangen,0) <> 1) then
      // @Serienummer is meegegeven, dan moet in @AantalOntvangen de waarde -1 of 1 zijn meegegeven.
      call Raise(20701,_U('In combinatie met serienummer moet in %1! de waarde -1 of 1 worden meegegeven', 'AantalOntvangen'));    // (20701) Ongeldige combinatie: %1!
    end if;
    if isnull(@AantalOntvangen,0) <> 0 then
      // @AantalOntvangen is meegegeven
      set @_MagOntLocAantal = @AantalOntvangen;
    else
      // @AantalOntvangen is niet meegegeven, dan aantal overnemen uit de magazijnontvangstregel
      set @_MagOntLocAantal = @_MagOntAantal;
    end if;

    // Indien het artikel niet Partij registrerend, maar wel Serienummer registrerend is,
    // dan moet ook het Partijnummer van het Serienummer in de Magazijnontvangstregel worden bijgewerkt,
    // ter voorkomimg van error (20220) Serienummers mogen niet zonder partijspecificatie worden ingevoerd! tijdens verwerking van de Magazijnontvangst.
    if @_MagOntArtPartijGid is null and @_MagOntLocArtSerieGid is not null then
      update tabMagazijnOntvangsten
      set MagOntArtPartijGid = @_ArtSerieArtPartijGid
      where MagOntGid = @_MagOntGid;
    end if;

    // LocatieSerieregel toevoegen aan de Magazijnontvangstdetailregel
    insert into tabMagazijnOntvangstLocatieSerie with auto name
    select @_MagOntLocMagOntDetGid as MagOntLocMagOntDetGid,
           @_MagOntLocArtSerieGid as MagOntLocArtSerieGid,
           @_MagOntLocLocGid as MagOntLocLocGid,
           @_MagOntLocAantal as MagOntLocAantal,
           0 as MagOntLocIsSerieNetAangemaakt;
  end;     // Einde atomic
  // call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Magazijnontvangst_OntvangstRegel_Toevoegen
( in @OntvangstNummer                   numeric(10,0),
  in @ArtikelSoort                      nchar(3)     ,      // Waarden: "TAR" of "ART"
  in @ArtikelNummer                     nchar(20)    ,
  in @ArtikelEanCode                    nchar(30)    ,
  in @ArtikelNummerLeverancier          nchar(20)    ,
  in @AantalOntvangen                   numeric(15,3),
  in @AantalCorrectie                   numeric(15,3),
  in @Partijnummer                      nchar(20)    ,
  in @Bestelnummer                      numeric(10,0),
  in @Bestelregelnummer                 numeric(3,0) ,
  in @InkoopEenheid                     nchar(20)    ,
  in @VoorraadEenhedenInInkoopEenheid   numeric(15,3),
  in @InkoopPrijs                       numeric(15,3),
  in @Kortingspercentage                numeric(15,2),
  in @Kortingsbedrag                    numeric(15,3),
  in @BTWCode                           numeric(3,0) ,
  in @CBSLandOorsprong                  nchar(3)     ,
  in @Opmerking                         long nvarchar,
  in @StandaardSpecificatieRegel        nchar(3),
  in @CbsDouaneregeling                 nchar(4) default null
)

result (OntvangstRegelNummer numeric(3,0))

begin
  declare @_MokGid integer;

  // call TraceBegin('WebSvcProc_Magazijnontvangst_OntvangstRegel_Toevoegen > @OntvangstNummer = ' + @OntvangstNummer);

  // Module controle
  if IsModuleActive('w7') = 0 then // Module Webservices Logistiek
    call Raise(20790,_U('Optie Webservices logistiek')); //(20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('ed') = 0 and isnull(@ArtikelEanCode,'') <> '' then // Module t.b.v. EDI (vanaf King Handel Pro)
    call Raise(20790,_U('Optie EDI')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken onderhanden Magazijnontvangstkop
  select MokGid into @_MokGid from tabMagazijnOntvangstenKop where MokNummer = @OntvangstNummer;
  if (@_MokGid is null) then
    call Raise(20780,_U('Magazijnontvangst wijzigen is'),_U('Ongeldige of geen %1! meegegeven', 'OntvangstNummer'));     // (20780) %1! niet mogelijk: %2!
  end if;

  // Aanroepen WebSvcHulpProc_Magazijnontvangst_OntvangstRegel_Toevoegen t.b.v. het toevoegen van de magazijnontvangstregel
  select    OntvangstRegelNummer
  from      WebSvcHulpProc_Magazijnontvangst_OntvangstRegel_Toevoegen
            ( @OntvangstNummer, @ArtikelSoort, @ArtikelNummer, @ArtikelEanCode, @ArtikelNummerLeverancier, @AantalOntvangen, @AantalCorrectie,
              @Partijnummer, @Bestelnummer,  @Bestelregelnummer, @InkoopEenheid, @VoorraadEenhedenInInkoopEenheid, @InkoopPrijs, @Kortingspercentage,
              @Kortingsbedrag, @BTWCode, @CBSLandOorsprong, @CbsDouaneregeling, @Opmerking, @StandaardSpecificatieRegel, 'KingWebService');

  // call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_MagazijnOntvangst_Toevoegen
( in @MagazijnCode            numeric(3,0),
  in @LeverancierNummer       nchar(15), // langer dan maximaal 10, ivm afkapgedrag van King Webservices V2
  in @LeverancierEanCode      numeric(13,0), // GLN code is 13 tekens, en voorloopnullen tellen mee... numeric dwingt af dat het cijfers zijn.
  in @OntvangstNummer         numeric(10,0),
  in @Goedgekeurd             nchar(3), // Waarden: JA, NEE
  in @OntvangstDatum          date,
  in @ValutaCode              nchar(3),
  in @TotaalBedragOntvangst   numeric(15,2), // Bedrag excl. BTW
  in @BetalingsConditie       numeric(3,0),
  in @Omschrijving            nchar(40),
  in @PakbonNummerLeverancier nchar(25), // langer dan maximuaal 20, ivm afkapgedrag van King Webservices V2
  in @Opmerking               long nvarchar,
  in @InkoopFactuurAanmaken   smallint,
  in @FactuurReferentie       nchar(45), // langer dan maximuaal 40, ivm afkapgedrag van King Webservices V2
  in @FactuurDatum            date,
  in @VervalDatum             date,
  in @BetalingsKenmerk        nchar(24),
  in @InkoopFactuurVerwerken  smallint,
  in @AangemaaktOp            date,
  in @Leveringsconditie       numeric(3,0) default null,
  in @ControleerFormaatEanCode smallint default 1, // indien 1, dan wordt er gecontroleerd of eancode voldoet aan het ucc-13 formaat
  in @OntvangstLocatie nchar(20) default null
)
result (OntvangstNummer numeric(10,0))
begin
  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen magazijnontvangsten doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790, _U('Optie Voorraad')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Als men iets wil doen met inkoopfactuur
  // en die optie is niet geactiveerd, dan als fout melden.
  if (IsModuleActive('if') = 0
      and ((@InkoopFactuurAanmaken is not null)
            or (isnull(@FactuurReferentie, '') <> '')
            or (@FactuurDatum is not null)
            or (@VervalDatum is not null)
            or (isnull(@BetalingsKenmerk, '') <> '')
          )
      ) then
    call Raise(20905); // Module 'Inkoopfacturen' niet geactiveerd!
  end if;

  // Is EDI optie niet actief, dan kan je niks met EAN code
  if (IsModuleActive('ed') = 0 and isnull(@LeverancierEanCode,0) <> 0 ) then
    call Raise(20790, _U('EDI optie (EAN)'));  // (20790) '%1!' niet geactiveerd!
  end if;

  begin
    // interne variabelen, nodig bij de bovenstaande parameters
    declare @_MokGid integer;
    declare @_MokMagGid integer;
    declare @_MokNawGid integer;
    declare @_MokNummer numeric(10,0);
    declare @_MokGoedgekeurd smallint;
    declare @_MokOntvangstDatum date;
    declare @_MokValNummer integer;
    declare @_MokTeBoeken numeric(15,2); // Totaalbedrag ontvangst
    declare @_MokBtcNummer integer;
    declare @_MokLvcNummer integer;
    declare @_MokOmschrijving nchar(40);
    declare @_MokPakBonNummerLeverancier nchar(40);
    declare @_MokOpm long nvarchar;
    declare @_MokInkoopfactuurAanmaken smallint; // Facturboeking maken
    declare @_MokInkoopfactuurVerwerken smallint;
    declare @_MokFactuurNummer nchar(40); // Factuurreferentie
    declare @_MokFactuurNummer_Lengte integer; // Dit is vanwege index op uitlever-/factuurhistorie
    declare @_MokFactuurDatum date;
    declare @_MokVervalDatum date;
    declare @_MokBetKenmerk nchar(24);
    declare @_MokAangemaaktDoor nchar(40);
    declare @_MokAangemaaktOp timestamp;

    // extra velden in de magazijnontvangstenkop
    declare @_MokCbsMeenemenInAangifte smallint;
    declare @_MokCbsCoGid integer;
    declare @_MokCbsGsGid integer;
    declare @_MokCbsSsGid integer;
    declare @_MokCbsVwGid integer;
    declare @_MokCbsPtnGidVerkeersgebied integer;
    declare @_MokCbsLndGidHerkomst integer;

    declare @_MokLocGidOntvangst integer = null;

    // constanten...
    declare _NAWBESTAND nchar(3) = 'C'; //Magazijnontvangst toevoegen is momenteel beperkt tot alleen crediteuren.
    declare _AANGEMAAKTDOOR nchar(10) = 'Webservice';
    declare _AANGEMAAKTOP timestamp = now();
    declare _MOKSOORT smallint = 0; // 0 = magazijnontvangst , 1 = directe levering

    // ******************************
    // controle verplichte velden
    // ******************************
    // Magazijncode
    set @_MokMagGid = (select MagGid from tabMagazijn where MagCode = @MagazijnCode );
    if @_MokMagGid is null then
      call Raise(20700, 'MagazijnCode') ; // Ongeldige waarde: %1
    end if;

    //Ontvangstlocatie
    if @OntvangstLocatie is null then
      if exists(Select 1 from TabMagazijnOntvangstenVasteGegevens where MagVastOntvangstLocatie = 1 /*Ontvangstloc. van mag.*/) then
        select MagLocGidVoorkeurOntvangst into @_MokLocGidOntvangst
        from tabMagazijn
        inner join tabLocatie on (locGid=MagLocGidVoorkeurOntvangst)
        where (MagGid = @_MokMagGid) and (LocBlokkade = 0);
      end if;
    else
      if @OntvangstLocatie <> '' then
      begin
        declare @_LocBlokkade smallint = 0;

        select LocGid, LocBlokkade
        into @_MokLocGidOntvangst, @_LocBlokkade
          from tabLocatie
          where Locnaam = @OntvangstLocatie
            and LocMagGid = @_MokMagGid;

          if @_MokLocGidOntvangst is null then
            call Raise(20700, 'Ontvangstlocatie') ; // Ongeldige waarde: %1
          end if;

          if @_LocBlokkade = 1 then
            //Locatie is geblokkeerd voor het plaatsen van artikelen!
            call Raise(20780,_U('Toevoegen'),_U('Locatie is geblokkeerd voor het plaatsen van artikelen')); // (20780) %1! niet mogelijk: %2!
          end if;
      end;
      end if;
    end if;

    // Leverancier
    begin
      declare @_NawFilNummer nchar(10);
      declare @_AdrEanCode nchar(13);

      if length(trim(@LeverancierNummer)) > 10 then
        call Raise(20700, _U('%1!, is langer dan %2! cijfers.', 'Leveranciernummer', '10')); // Ongeldige waarde: %1
      end if;
      set @_NawFilNummer = trim(@LeverancierNummer);

      if (@ControleerFormaatEanCode = 1) and (length(trim(@LeverancierEanCode)) > 13) then
        call Raise(20700, _U('%1!, is langer dan %2! cijfers.', 'LeverancierEanCode', '13')); // Ongeldige waarde: %1
      end if;
      set @_AdrEanCode = trim(@LeverancierEanCode);

      if (@_AdrEanCode is null and @_NawFilNummer is null ) then
        call Raise(20780, _U('Toevoegen'), _U('Leverancier is niet ingevuld')); // <Actie> niet mogelijk: <Reden>.
      end if;

      if (@_AdrEanCode <> ''  and @_NawFilNummer <> '' ) then
        call Raise(20701, _U('%1! en %2! mogen niet beide ingevuld zijn!', 'Leveranciernummer', 'LeverancierEanCode')) ; // Ongeldige combinatie: %1
      end if;

      // test leveranciernummer
      if (@_NawFilNummer <> '' ) then
        select  NawFilNawGid into @_MokNawGid from tabNawFile inner join tabFileOfNaw on FonGid = NawFilFonGid and FonId = _NAWBESTAND where NawFilNummer = @_NawFilNummer;
        if @_MokNawGid is null then
          call Raise(20720, 'LeverancierNummer') ; // %1 niet gevonden!
        end if;
      end if;

      // test EAN code leverancier
      if (@_AdrEanCode <> '' ) then
        call WebSvcHulpProc_ValideerNawEanCode(
          @EanCode = @_AdrEanCode,
          @FonId = _NAWBESTAND,          // c = crediteur, d = debiteur, b = bedrijfsgegevens, ??? = relatie
          @NawGid=null,                          // Indien ingevuld, wordt getoetst of EAN code bij NAW hoort ( let op de FonId!)
          @ControleerFormaatEanCode = @ControleerFormaatEanCode,
          //out
          // null,                 // de gevalideerde EAN code
          @_NawGidEan = @_MokNawGid);         // de NAW waar het bij hoort.

        if @_MokNawGid is null then
          call Raise(20720, 'LeverancierEanCode'); // %1 niet gevonden!
        end if;
      end if;
    end; // leverancier

    // ******************************
    // Optionele parameters voor MagzijnontvangstenKop
    // ******************************

    // Goedgekeurd
    set @_MokGoedgekeurd = (select MagVastDefStatus from tabMagazijnOntvangstenVastegegevens );
    select  case isnull(trim(@Goedgekeurd),'')
              when ''     then @_MokGoedgekeurd
              when 'JA'   then 1
              when 'NEE'  then 0
              else null
            end case
      into @_MokGoedgekeurd
    from dummy;

    if @_MokGoedgekeurd is null then
      call Raise(20700, 'Goedgekeurd'); // Ongeldige waarde: %1
    end if;

    // OntvangstDatum
    begin
      select  case MagVastDefBoekdatum
                when 2  then date(now())                              // 2 = systeemdatum
                when 1  then isnull(@@VerwerkingsDatum, date(now()) ) // 1 = verwerkingsdatum (king 5 global variable database init)
                when 0  then @OntvangstDatum                          // 0 = leeg, dus moet er een ingevulde datum zijn.
                else null                                             // onbekend optie
              end case
        into  @_MokOntvangstDatum
      from tabMagazijnOntvangstenVastegegevens;

      if @_MokOntvangstDatum is null then
        call Raise(20700, _U('%1!, is verplicht.', 'OntvangstDatum')); // Ongeldige waarde: %1
      end if;

      if @OntvangstDatum is not null then
        set @_MokOntvangstDatum = (select first @OntvangstDatum from tabBoekjaar where ( BjAfsluiting <> 2 ) and @OntvangstDatum between BjBeginDatum and BjEindDatum);
        // boekjaar is definitief afgesloten, of er is geen boekjaar bekend (datum is in geen enkel boekjaar)
        if @_MokOntvangstDatum is null then
          call Raise(20700, _U('Ontvangst op %1! boeken kan niet, er is geen boekjaar die open is', string(@OntvangstDatum))) ; // Ongeldige waarde: %1
        end if;
      end if;
    end; // Ontvangstdatum

    // Betalingsconditie
    // Is die bij leverancier niet ingevuld, dan de default voor ale crediteuren
    begin
      set @_MokBtcNummer = isnull((select NawFilBtcNummer from tabNawFile where NawFilNawGid = @_MokNawGid and NawFilFonId = _NAWBESTAND),
                                  (select FonBtcNummer from tabFileOfNaw where FonId = _NAWBESTAND));

      if @BetalingsConditie is not null then
        set @_MokBtcNummer = (select BtcNummer from tabBetalingsConditie where BtcNummer = @BetalingsConditie );
        if @_MokBtcNummer is null then
          call Raise(20700, 'Betalingsconditie'); // Ongeldige waarde: %1
        end if;
      end if;
    end; //Betalingsconditie

    // Leveringsconditie
    if @Leveringsconditie is null then
      set @_MokLvcNummer = isnull((select NawFilLvcNummer from tabNawFile where NawFilNawGid = @_MokNawGid and NawFilFonId = _NAWBESTAND),
                                  (select FonLvcNummer from tabFileOfNaw where FonId = _NAWBESTAND));
    else
      set @_MokLvcNummer = (select LvcNummer from tabLeveringsConditie where LvcNummer = @LeveringsConditie );
      if @_MokLvcNummer is null then
        call Raise(20700, 'Leveringsconditie'); // Ongeldige waarde: %1
      end if;
    end if;

    // OntvangstNummer - dit doen we zo laat mogelijk omdat een gegenereerd nummer niet meer opnieuw gebruikt kan worden.
    begin
      set @_MokNummer = @OntvangstNummer;
      set @_MokGid = (select MokGid from tabMagazijnOntvangstenKop where MokNummer = @_MokNummer);
      if @_MokGid is not null then
        call Raise(20721, _U('Ontvangstnummer %1!', string(@OntvangstNummer))); // %1 komt al voor!
      end if;
      // Check de historie, daar kan die al gebruikt zijn...
      set @_MokGid = (select MohkGid from tabMagazijnOntvangstHistKop where MohkNummer = @_MokNummer);
      if @_MokGid is not null then
        call Raise(20721, _U('OntvangstNummer %1!', string(@OntvangstNummer))); // %1 komt al voor!
      end if;

      if ( @_MokNummer is null ) then
        call MagazijnOntvangstNrGenereren(1 /* Forceer*/, @_MokNummer); // King 5 procedure. Er moet een eerstvolgende vrije nummer worden uitgedeeld.
      end if;
    end; // Ontvangstnummer

    // ******************************
    // Inkoopfactuur - er is vooraf al gecheckt dat deze king module actief is.
    // Geeft ValutaNummer van OSP indien er bij factuurreferentie een is.
    // En dan is het checken of bij aanroep een geldige valuta is opgegeven of niet.
    // ******************************
    begin
      if length(trim(@FactuurReferentie)) > 40 then
        call Raise(20700, _U('%1!, is langer dan %2! tekens.', 'FactuurReferentie', '40')); // Ongeldige waarde: %1
      end if;

      //if length(trim(@BetalingsKenmerk)) > 140 then
      //  raiserror 20700, 'BetalingsKenmerk, is langer dan 140 tekens.'; // Ongeldige waarde: %1
      //end if;

      call WebSvcHulpProc_Magazijnontvangst_Inkoopfactuur(
        @InkoopfactuurAanmaken,
        @FactuurReferentie,        // FactuurNummer inkoopfactuur
        @FactuurDatum,
        @VervalDatum,
        @BetalingsKenmerk,
        @InkoopfactuurVerwerken,
        //  Onderstaande invoer parameters  moeten vooraf al gevalideerd zijn
        @_MokNummer,
        @_MokOntvangstDatum,
        @_MokBtcNummer,
        @_MokNawGid,
        // out:
        @_MokInkoopfactuurAanmaken,
        @_MokFactuurNummer,
        @_MokFactuurNummer_Lengte,
        @_MokFactuurDatum,
        @_MokVervalDatum,
        @_MokBetKenmerk,
        @_MokInkoopfactuurVerwerken,
        @_MokValNummer);
    end;
    // Valuta
    // Hiervoor moet al bekend zijn of inkoopfactuur OSP kent, diens valuta is van belang.
    begin
      declare @_ValNummer integer;

      // Overnemen van OSP bij inkoopfactuur
      set @_ValNummer = @_MokValNummer;

      // Bestaat de opgegeven valuta?
      if (isnull(@ValutaCode,'') <> '' ) then
        set @_ValNummer = ( Select ValNummer from tabValuta where ValCode = @ValutaCode );
        if @_ValNummer is null then
          call Raise(20700, 'ValutaCode'); // Ongeldige waarde : %1
        end if;

        // Bij aan te maken inkoopfactuur is een OSP? dan mag opgegeven valuta er niet van afwijken.
        if (@_MokInkoopfactuurAanmaken <> 0) and (@_MokValNummer is not null) and ( @_ValNummer <> @_MokValNummer ) then
          call Raise(20701, _U('%1!, er is een openstaande post in andere valuta.', 'ValutaCode')); // Ongeldige Combinatie : %1
        end if;
      end if;

      // Er is geen OSP bij inkoopfactuur, en er is niks opgegeven? dan valuta van leverancier of de default valuta afhankelijk van de vaste gegeven vvp of Werkelijke inkoopprijs.
      if exists(Select 1 from TabMagazijnOntvangstenVasteGegevens where MagVastOntvBoekenTegen = 1) then
        set @_MokValNummer = isnull(@_ValNummer, (select NawFilValNummer from tabNawFile where NawFilNawGid = @_MokNawGid and NawFilFonId = _NAWBESTAND) );
      else
        set @_MokValNummer = isnull(@_ValNummer, @@BasisValutaNummer );
      end if;
    end; // valuta

    // Aangemaakt - door wie en wanneer
    set @_MokAangemaaktDoor = _A('Systeem');
    set @_MokAangemaaktOp = isnull(@AangemaaktOp, now());

    // Omschrijving
    set @_MokOmschrijving = trim(@Omschrijving);
    select  case MagVastDefOmschrijving
              when 2 then ( select AdrNaam1 from tabAdres inner join tabNaw on NawGidVestiging = AdrGid and NawGid = @_MokNawGid )
              when 1 then ( select NawFilZoekCode from tabNawFile where NawFilNawGid = @_MokNawGid )
              when 0 then null
              else null
            end case
      into @_MokOmschrijving
    from tabMagazijnOntvangstenVastegegevens
    where isnull(@_MokOmschrijving, '') = '';

    // overige ingevulde velden overnemen
    if length(trim(@PakBonNummerLeverancier)) > 20 then
      call Raise(20700, _U('%1!, is langer dan %2! tekens.', 'PakBonNummerLeverancier', '20')); // Ongeldige waarde: %1
    end if;
    set @_MokPakBonNummerLeverancier = trim(@PakBonNummerLeverancier);
    set @_MokOpm = trim(@Opmerking);
    set @_MokTeBoeken = @TotaalBedragOntvangst;

    // ******************************
    // Cbs aangifte doen of niet, hangt o.a. van vestiging van leverancier af.
    // ******************************
    call WebSvcHulpProc_MagazijnOntvangst_CbsAangifte(
      @_MokNawGid,                  // leverancier
      // out:
      @_MokCbsMeenemenInAangifte,
      @_MokCbsCoGid,
      @_MokCbsGsGid,
      @_MokCbsLndGidHerkomst,
      @_MokCbsPtnGidVerkeersgebied,
      @_MokCbsSsGid,
      @_MokCbsVwGid);

    // ******************************
    // Maak nu de magazijnontvangst aan...
    // ******************************
    begin atomic // Dit moet, want lock moet hierna nog erop en daar kan het nog fout gaan
      insert into tabMagazijnOntvangstenKop (
        MokGid,
        MokMagGid,
        MokNawGid,
        MokNummer,
        MokGoedgekeurd,
        MokOntvangstDatum,
        MokValNummer,
        MokTeBoeken,
        MokBtcNummer,
        MokLvcNummer,
        MokOmschrijving,
        MokPakBonNummerLeverancier,
        MokOpm,
        MokInkoopfactuurAanmaken,
        MokInkoopfactuurVerwerken,
        MokFactuurNummer,
        MokFactuurNummer_Lengte,
        MokFactuurDatum,
        MokVervalDatum,
        MokBetKenmerk,
        MokAangemaaktDoor,
        MokAangemaaktOp,
        MokCbsMeenemenInAangifte,
        MokCbsCoGid,
        MokCbsGsGid,
        MokCbsVwGid,
        MokCbsSsGid,
        MokCbsPtnGidVerkeersgebied,
        MokCbsLndGidHerkomst,
        MokLocGidOntvangst
      )
      values (
        @_MokGid,
        @_MokMagGid,
        @_MokNawGid,
        @_MokNummer,
        @_MokGoedgekeurd,
        @_MokOntvangstDatum,
        @_MokValNummer,
        @_MokTeBoeken,
        @_MokBtcNummer,
        @_MokLvcNummer,
        @_MokOmschrijving,
        @_MokPakBonNummerLeverancier,
        @_MokOpm,
        @_MokInkoopfactuurAanmaken,
        @_MokInkoopfactuurVerwerken,
        @_MokFactuurNummer,
        @_MokFactuurNummer_Lengte,
        @_MokFactuurDatum,
        @_MokVervalDatum,
        @_MokBetKenmerk,
        @_MokAangemaaktDoor,
        @_MokAangemaaktOp,
        @_MokCbsMeenemenInAangifte,
        @_MokCbsCoGid,
        @_MokCbsGsGid,
        @_MokCbsVwGid,
        @_MokCbsSsGid,
        @_MokCbsPtnGidVerkeersgebied,
        @_MokCbsLndGidHerkomst,
        @_MokLocGidOntvangst
      );
      set @_MokGid = @@Identity;

      // Aangemaakte Magazijnontvangst locken
      call WebSvcHulpProc_MagazijnontvangstExclusiefLocken(@_MokGid, 'KingWebService', @@Spid, @@LoginTime);
    end; //atomic

    // resultaat terug geven
    select MokNummer as OntvangstNummer
    from tabMagazijnOntvangstenKop
    where MokGid = @_MokGid;
  end;
end;


create or replace procedure WebSvcProc_MagazijnOntvangst_Verwerken(in @OntvangstNummer numeric(10,0))
begin
  // variabelen
  declare @_MokGid integer;
  declare @_MokGoedGekeurd smallint;
  declare @_qLockGid integer;
  declare @_SpId integer = @@SpId;  //NULL =>  systeemvariabele @@SpId       wordt gebruikt
  declare @_LoginTime timestamp = @@LoginTime; //NULL =>  systeemvariabele @@LoginTime  wordt gebruikt
  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabMagazijnOntvangstenKop';

  //call TraceBegin('WebSvcProc_MagazijnOntvangst_Verwerken');

  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen voorraadbeheer actief , dan kan je de facto geen magazijnontvangsten doen.
  if IsModuleActive('vr') = 0 then
    call Raise(20790, _U('Optie Voorraad')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken MagazijnOntvangst
  select MokGid, isnull(MokGoedGekeurd,0)
    into @_MokGid, @_MokGoedGekeurd
  from tabMagazijnOntvangstenKop
  where MokNummer = @OntvangstNummer;
  if @_MokGid is null then
    call Raise(20720, 'OntvangstNummer'); // (20720) niet gevonden: %1!
  end if;

  // magaqzijnontvangst zonder regels niet verwerken.
  if not exists(select first 1 from tabMagazijnontvangsten where MagOntMokGid = @_MokGid) then
    call Raise(20780, _U('Verwerken magazijnontvangst'),_U('er zijn geen ontvangstregels')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // Magazijnontvangst aanmelden voor verwerking
  // vanwege gebrekkige documentatie hier even de soorten vasxtgelegd:
  // 3 = qcImpLayoutXmlOrders
  // 20 = ImpSoortGid magazijnontvangst
  // 28 = ImpSoortGid directe leveringen
  if exists(select first 1 from tabJobImportVerwerking where JobivImportRecordGid = @_MokGid and JobivSoort = 20) then
    call Raise(20780, _U('Verwerken magazijnontvangst'),_U('een King job is al met verwerken bezig')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // Bij de king Job hoort een jobscript die de te verwerken ontvangsten uit tab_WebSvc_MagazijnOntvangstVerwerken moet halen.
  if exists(select first 1 from tab_WebSvc_MagazijnOntvangstVerwerken where MOVMokGid = @_MokGid) then
    call Raise(20780, _U('Verwerken magazijnontvangst'),_U('staat al klaar voor verwerking door een King job')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  begin atomic
    // Magazijnontvangst eerst locken
    call WebSvcHulpProc_MagazijnontvangstExclusiefLocken(@_MokGid, 'KingWebService', @_Spid, @_LoginTime);

    // Nog niet GoedGekeurd? forceren!
    if (@_MokGoedGekeurd = 0) then
      update tabMagazijnOntvangstenKop set MokGoedgekeurd = 1 where MokGid = @_MokGid;
    end if;

    // Magazijnontvangst voor verwerking door een King job aanmelden
    insert into tab_WebSvc_MagazijnOntvangstVerwerken(MOVMokGid) values (@_MokGid) ;

    // lock weer vrijgeven.
    // De King Job die de echte verwerking doet zorgt zelf voor de locking.
    call LockReleaseOnId( isnull(@_Spid, @@SpId) , isnull(@_LoginTime,@@LoginTime), 1, _QLOCKTABLENAME, @_MokGid);

  end // atomic

  //call TraceEind('WebSvcProc_MagazijnOntvangst_Verwerken');
end;


create or replace procedure WebSvcHulpProc_Offerteversie_ControleerVastegegevens(
  in @Mode smallint,    // 0 = toevoegen, 1 = wijzigen
  in @OffFonGidRelatie integer,
  in @OffNawGid integer,
  in @IsInkoopCombinatie smallint,
  in @NawGidInkCombiFactuur integer,
  in @Referentie long nvarchar,
  in @Opmerking long nvarchar,
  in @PrijzenInclusiefBtw smallint,
  in @ValutaCode nchar(3),
  in @BetalingsConditieNummer numeric(3,0),
  in @LeveringsConditieNummer numeric(3,0),
  in @ExtraTekstEmailbericht long nvarchar,
  in @OrderKorting numeric(6,2),
  in @FactuurAdres nchar(4),
  in @VerzendAdres nchar(10),
  in @VerzendAdresNummer numeric(3,0),
  in @EindAdres nchar(40),
  in @EindAdresNummer numeric(3,0),
  in @AparteFactuur nchar(40),
  in @Apartelevering nchar(4),
  inout @_Referentie long nvarchar,
  inout @_Opmerking long nvarchar,
  inout @_PrijzenInclusiefBtw smallint,
  inout @_ValutaNummer numeric(3,0),
  inout @_BtcNummer numeric(3,0),
  inout @_LvcNummer numeric(3,0),
  inout @_ExtraTekstEmailbericht long nvarchar,
  inout @_OrderKorting numeric(6,2),
  inout @_FactuurAdres smallint,
  inout @_VerzendAdres smallint,
  inout @_AdrGidVerzendAdres integer,
  inout @_EindAdres smallint,
  inout @_AdrGidEindAdres integer,
  inout @_AparteFactuur smallint,
  inout @_Apartelevering smallint)
begin
  declare _TOEVOEGEN smallint = 0;
  declare _WIJZIGEN smallint = 1;
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  //Bij het toevoegen halen we de defaults van de debiteur op. Bij relatie zijn dit andere defaults
  if @Mode = _TOEVOEGEN then
    // Vastegegevens Debiteuren toepassen voor Relatie
    // Het is ook bruikbaar voor debiteur waar rubrieken niet ingevuld zijn
    select FonBtcNummer,
           FonFactuurAdres,
           FonVerzendAdres,
           FonApartFactureren,
           FonLvcNummer,
           @@BasisValutaNummer,
           fonFactuurBTW,
           FonApartLeveren,
           case FonOrdKortingDebOfDebGroep
            when 0 /*debiteur*/ then FonOrderkorting
            when 1 /*deb. groep*/ then (select DebGrpOrderKorting from tabDebiteurgroepen where DebGrpGid = fonDebGrpGid)
            else null
           end case,
           FonEindAdres
    into @_BtcNummer,
         @_FactuurAdres,
         @_VerzendAdres,
         @_AparteFactuur,
         @_LvcNummer,
         @_ValutaNummer,
         @_PrijzenInclusiefBtw,
         @_Apartelevering,
         @_OrderKorting,
         @_EindAdres
    from tabFileofNaw
    where FonId = 'D';

    // Gaat het om een debiteur, dan daarvan instellingen overnemen.
    // Er zijn Defaults bij waar inkoopcombinatie een rol speelt
    if @OffFonGidRelatie is null then
      select isnull(NawFilBtcNummer, @_BtcNummer), // onbekend? Dan uit vaste gegevens debiteuren
             NawFactuurAdres,
             NawAparteFacturen
      into @_BtcNummer,
           @_FactuurAdres,
           @_AparteFactuur
      from  tabNaw
      inner join tabNawFile on NawFilNawGid = NawGid
      where (@IsInkoopCombinatie = _qcNEE and NawFilNawGid = @OffNawGid )
        or  (@IsInkoopCombinatie = _qcJA and NawFilNawGid = @NawGidInkCombiFactuur );

      // Overige defaults uit Debiteur
      // Er zijn Defaults bij waar inkoopcombinatie een rol speelt
      select isnull(NawFilLvcNummer, @_LvcNummer),      // onbekend? Dan uit vaste gegevens debiteuren
             isnull(NawFilValNummer, @@BasisValutaNummer),
             NawFacturerenInclBtw,
             NawAparteLevering,
             case NawFilWelkeOrderKorting
               when 0 /*debiteur*/ then NawOrderKorting
               when 1 /*deb. groep*/ then ( select DebGrpOrderKorting from tabDebiteurgroepen where debGrpGid = NawFilDebGrpGid )
             end case,
             case
               when @IsInkoopCombinatie = _qcJA then NawVerzendAdres
               when NawVerzendAdres in (3/*FACT_COR*/, 4 /*FACT_VEST*/, 5 /*FACT_VERZ*/ ) then @_VerzendAdres // terugvallen op vaste gegevens
               else NawVerzendAdres
             end case,
             case
               when @IsInkoopCombinatie = _qcJA then NawGidVerzendAdres
               when NawVerzendAdres in (3/*FACT_COR*/, 4 /*FACT_VEST*/, 5 /*FACT_VERZ*/ ) then null // Adres niet valide c.q. vindbaar bij offertedebiteur c.q. vaste gegevens
               else NawGidVerzendAdres
             end case,
             NawEindAdres,
             NawGidEindAdres
      into @_LvcNummer,
           @_ValutaNummer,
           @_PrijzenInclusiefBtw,
           @_Apartelevering,
           @_OrderKorting,
           @_VerzendAdres,
           @_AdrGidVerzendAdres,
           @_EindAdres,
           @_AdrGidEindAdres
      from tabNaw
      inner join tabNawFile on NawFilNawGid = NawGid
      where NawFilNawGid = @OffNawGid;
    end if;
  end if;

  // ********
  // Adressen
  // ********
  // FactuurAdres
  if isnull(@FactuurAdres, '') <> '' then
    case @FactuurAdres
      when 'COR'  then set @_FactuurAdres = 0;
      when 'VEST' then set @_FactuurAdres = 1;
      else call Raise(20700, string('FactuurAdres')) ;  //Ongeldige waarde: <parameter of opmerking>
    end case;
  end if;

  // VerzendAdres
  if isnull(@VerzendAdres, '') <> '' then
    case @VerzendAdres
      when 'COR'       then set @_VerzendAdres = 0;
      when 'VEST'      then set @_VerzendAdres = 1;
      when 'VERZ'      then set @_VerzendAdres = 2;
      when 'FACT_COR'  then set @_VerzendAdres = 3;
      when 'FACT_VEST' then set @_VerzendAdres = 4;
      when 'FACT_VERZ' then set @_VerzendAdres = 5;
      else call Raise(20700, string( 'VerzendAdres = ', @VerzendAdres )) ;  //Ongeldige waarde: <parameter of opmerking>
    end case;

    if ( @_VerzendAdres in (3,4,5) ) and @IsInkoopCombinatie = _qcNEE then
      call Raise(20701, _U('%1!, er is geen inkoopcombinatie.', 'VerzendAdres'));   //Ongeldige combinatie: <parameter of opmerking>
    end if;
  end if;

  //Verzendadresnummer Bij Verzendadres (2) of Factuurverzendadres (5)
  if ( @_VerzendAdres in (2,5) ) and @VerzendAdresNummer is not null then
    set @_AdrGidVerzendAdres = ( select AdrGid
                                 from tabAdres
                                 where AdrCode = @VerzendAdresNummer
                                  and ((AdrNawGid = @NawGidInkCombiFactuur and @IsInkoopCombinatie = _qcJA and @_VerzendAdres = 5 /*FACT_VERZ*/ )
                                        or (AdrNawGid = @OffNawGid and @_VerzendAdres = 2 /*VERZ*/ ) ) );

    if (@_AdrGidVerzendAdres is null) then
      call Raise(20700, string('VerzendAdresNummer ', @VerzendAdresNummer));  //Ongeldige waarde: <parameter of opmerking>
    end if;
  end if;

  // EindAdres
  if isnull(@Eindadres, '') <> '' then
    case @Eindadres
      when 'COR'  then set @_EindAdres = 0;
      when 'VEST' then set @_EindAdres = 1;
      when 'VERZ' then set @_EindAdres = 2;
      when 'NVT'  then set @_EindAdres = 3;
      else call Raise(20700, string( 'Eindadres = ', @Eindadres )) ;  //Ongeldige waarde: <parameter of opmerking>
    end case;
  end if;

  //Eindadresnummer
  if @_EindAdres = 2 /*VERZ*/ and @EindAdresNummer is not null then
    set @_AdrGidEindAdres = ( select AdrGid from tabAdres where AdrCode = @EindAdresNummer and AdrNawGid = @OffNawGid );
    if @_AdrGidEindAdres is null then
      call Raise(20700, string('EindAdresNummer ', @EindAdresNummer));  //Ongeldige waarde: <parameter of opmerking>
    end if;
  end if;

  // **************************************
  // Condities t.b.v. factureren en leveren
  // **************************************
  //ValutaCode
  if isnull(@ValutaCode, '') <> '' then
    set @_ValutaNummer = (select ValNummer from tabValuta where ValCode = @ValutaCode ) ;

    if @_ValutaNummer is null then
      call Raise(20700, string('ValutaCode = ', @ValutaCode )) ;  //Ongeldige waarde: <parameter of opmerking>
    end if;
  end if;

  //PrijzenInclusiefBtw
  if (@PrijzenInclusiefBtw is not null) and (@PrijzenInclusiefBtw not in (0,1) ) then
    call Raise(20700,'PrijzenInclusiefBtw'); // (20700) Ongeldige waarde: %1!
  end if;

  case @PrijzenInclusiefBtw
    when 0 then set @_PrijzenInclusiefBtw = 0
    when 1 then set @_PrijzenInclusiefBtw = 1
  end case;

  //BetalingsConditieNummer
  if @BetalingsConditieNummer is not null then
    set @_BtcNummer = (select BtcNummer from tabBetalingsConditie where BtcNummer = @BetalingsConditieNummer);

    if (@_BtcNummer is null) then
      call Raise(20700, string( 'BetalingsConditieNummer = ', @BetalingsConditieNummer )) ;  //Ongeldige waarde: <parameter of opmerking>
    end if;
  end if;

  if @LeveringsConditieNummer is not null then
    set @_LvcNummer = (select LvcNummer from tabLeveringsConditie where LvcNummer = @LeveringsConditieNummer);

    if (@_LvcNummer is null) then
      call Raise(20700, string( 'LeveringsConditieNummer = ', @LeveringsConditieNummer )) ;  //Ongeldige waarde: <parameter of opmerking>
    end if;
  end if;

  if @OrderKorting is not null then
    if (@OrderKorting not between -100 and 100 ) then
      call Raise(20700, _U('%1! moet tussen %2! en %3! liggen!', 'OrderKorting', '-100', '100')); //920700 Ongeldige waarde: %1
    end if;

    set @_OrderKorting = @OrderKorting;
  end if;

  //Aparte Factuur
  if isnull(@AparteFactuur, '') <> '' then
    case @AparteFactuur
      when 'JA' then set @_AparteFactuur = 0
      when 'NEE' then set @_AparteFactuur = 1
      when 'PERCONTACTPERSOON' then set @_AparteFactuur = 2
      when 'PERVERZENDADRES' then set @_AparteFactuur = 3
      when 'PERCONTACTPERSOONENVERZENDADRES' then set @_AparteFactuur = 4
      else call Raise(20700, string( 'AparteFactuur = ', @AparteFactuur )) ;  //Ongeldige waarde: <parameter of opmerking>
    end case;
  else
    if @Mode = _TOEVOEGEN and @_AparteFactuur is null then
        call Raise(20700,'AparteFactuur'); //(20700) Ongeldige waarde: %1!
    end if;
  end if;

  //Aparte Levering
  if isnull(@AparteLevering, '') <> '' then
    case @AparteLevering
      when 'JA' then set @_Apartelevering = 0
      when 'NEE' then set @_Apartelevering = 1
      else call Raise(20700, string( 'AparteLevering = ', @AparteLevering )) ;  //Ongeldige waarde: <parameter of opmerking>
    end case;
  else
    if @Mode = _TOEVOEGEN and @_Apartelevering is null then
        call Raise(20700,'AparteLevering'); //(20700) Ongeldige waarde: %1!
    end if;
  end if;

  // ******************
  // Vrije tekst velden
  // ******************
  if isnull(@Referentie,'') <> '' then set @_Referentie = @Referentie end if;
  if isnull(@Opmerking,'') <> '' then set @_Opmerking = @Opmerking end if;
  if isnull(@ExtraTekstEmailbericht,'') <> '' then set @_ExtraTekstEmailbericht = @ExtraTekstEmailbericht end if;

end;


create or replace procedure WebSvcHulpProc_Offerteversie_ValideerInkoopcombinatie(
  in @Mode                          smallint,                // 0 = toevoegen, 1 = Wijzigen
  in @NawGid                        integer default null,    // Debiteur of Relatie van de offerte, nodig igv toevoegen
  in @FonGidRelatie                 integer default null,    // null = debiteur, anders betreft het een relatie
  in @OfkGid                        integer default null,    // OfferteVersie, nodig igv wijzigingen
  in @DebiteurNummerFactuur         nchar(10),
  in @DebiteurNummerOmzet           nchar(10),
  in @DebiteurNummerPrijsafspraken  nchar(10),
  in @IsInkoopcombinatie            smallint,
  out @_IsInkoopCombinatie          smallint,
  out @_NawGidInkCombiFactuur       integer,
  out @_NawGidInkCombiOmzet         integer,
  out @_NawGidInkCombiPrijzen       integer)
begin
  // Query constants
  declare qcTOEVOEGEN smallint = 0;
  declare qcWIJZIGEN smallint = 1;
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;
  // ****************
  // INGANGSCONTROLES
  // ****************
  set @_IsInkoopCombinatie = isnull(@IsInkoopCombinatie, _qcNEE);

  if @_IsInkoopCombinatie not in (_qcNEE , _qcJA) then
    call Raise(20700, 'InkoopCombinatie');  //Ongeldige waarde <Parameternaam of opmerking>
  end if;

  // inkoopcombinaties is alleen te gebruiken als licentie-optie actief is
  if IsModuleActive('i2') = _qcNEE /* niet actief */ then
    if @IsInkoopCombinatie is not null then
      call Raise(20790, _U('Optie Inkoopcombinaties')); // <Optie/Module> niet geactiveerd!
    end if;
  end if;

  // Bij relaties (dus *niet* debiteur) is inkoopcombinatie niet mogelijk
  if (@_IsInkoopCombinatie = _qcJA and @FonGidRelatie is not null) then
    call Raise(20701, _U('Inkoopcombinatie is niet toepasbaar voor relatie.')); // Ongeldige combinatie: <Parameternaam of opmerking>
  end if;

  if @_IsInkoopCombinatie = _qcJA then
    // Factuurdebiteur
    if IsNull(@DebiteurNummerFactuur, '') <> '' then
      if @_IsInkoopCombinatie = _qcNEE then
        call Raise(20701, _U('%1! is 0, terwijl %2! is opgegeven.', 'InkoopCombinatie', 'DebiteurNummerFactuur')); // Ongeldige combinatie: <Parameternaam of opmerking>
      end if;
      set @_NawGidInkCombiFactuur = ( select NawFilNawGid from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummerFactuur );
      if @_NawGidInkCombiFactuur is null then
        call Raise(20700, String('DebiteurNummerFactuur: ', @DebiteurNummerFactuur )) ;  //Ongeldige waarde <Parameternaam of opmerking>
      end if;
    end if;

    // Debiteur Omzet
    if IsNull(@DebiteurNummerOmzet, '') <> '' then
      if @_IsInkoopCombinatie = _qcNEE then
        call Raise(20701, _U('%1! is 0, terwijl %2! is opgegeven.', 'InkoopCombinatie', 'DebiteurNummerOmzet')); // Ongeldige combinatie: <Parameternaam of opmerking>
      end if;
      set @_NawGidInkCombiOmzet = ( select NawFilNawGid from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummerOmzet );
      if @_NawGidInkCombiOmzet is null then
        call Raise(20700, String('DebiteurNummerOmzet: ', @DebiteurNummerOmzet )) ;  //Ongeldige waarde <Parameternaam of opmerking>
      end if;
    end if;

    // Debiteur Prijsafspraken
    if IsNull(@DebiteurNummerPrijsafspraken, '') <> '' then
      if @_IsInkoopCombinatie = _qcNEE then
        call Raise(20701, _U('%1! is 0, terwijl %2! is opgegeven.', 'InkoopCombinatie', 'DebiteurNummerPrijsafspraken')); // Ongeldige combinatie: <Parameternaam of opmerking>
      end if;
      set @_NawGidInkCombiPrijzen = ( select NawFilNawGid from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @DebiteurNummerPrijsafspraken );
      if @_NawGidInkCombiPrijzen is null then
        call Raise(20700, String('DebiteurNummerPrijsafspraken: ', @DebiteurNummerPrijsafspraken )) ;  //Ongeldige waarde <Parameternaam of opmerking>
      end if;
    end if;
  else
    set @_NawGidInkCombiFactuur = null;
    set @_NawGidInkCombiOmzet = null;
    set @_NawGidInkCombiPrijzen = null;
  end if;

  // **********************
  // DEFAULTS BIJ TOEVOEGEN
  // **********************
  if @Mode = qcTOEVOEGEN then
    // Defaults ophalen bij debiteur in geval van toevoegen
    // Maar alleen in geval van een in te vullen inkoopcombinatie
    select  NawIsInkoopCombinatie,
            isnull(@_NawGidInkCombiFactuur, NawIdFactDeb),
            isnull(@_NawGidInkCombiOmzet, NawIdDebOmzet),
            isnull(@_NawGidInkCombiPrijzen, NawIdDebPrijzen)
    into @_IsInkoopCombinatie,
         @_NawGidInkCombiFactuur,
         @_NawGidInkCombiOmzet,
         @_NawGidInkCombiPrijzen
    from tabNaw
    where NawGid = @NawGid
      and NawIsInkoopCombinatie = _qcJA;
  end if;

  // *********************
  // DEFAULTS BIJ WIJZIGEN
  // *********************
  if @Mode = qcWIJZIGEN then
    // Waarden uit de offerteversie overnemen,
    // Maar alleen in geval van een in te vullen inkoopcombinatie
    select  OfkIsInkoopCombinatie,
            isnull(@_NawGidInkCombiFactuur, OfkNawGidInkCombiFactuur),
            isnull(@_NawGidInkCombiOmzet, OfkNawGidInkCombiOmzet),
            isnull(@_NawGidInkCombiPrijzen, OfkNawGidInkCombiPrijzen)
    into @_IsInkoopCombinatie,
         @_NawGidInkCombiFactuur,
         @_NawGidInkCombiOmzet,
         @_NawGidInkCombiPrijzen
    from tabOfferteKop
    where OfkGid = @OfkGid
      and OfkIsInkoopCombinatie = _qcJA;
  end if;

  // ******************************************
  // ALLE DEBITEUREN IN INKOOPCOMBINATIE BEKEND
  // ******************************************
  if @_IsInkoopCombinatie = _qcJA then
    if @_NawGidInkCombiFactuur is null then
      call Raise(20700, _U('%1!, is verplicht.', 'DebiteurNummerFactuur')); //Ongeldige waarde <Parameternaam of opmerking>
    end if;
    if @_NawGidInkCombiOmzet is null then
      call Raise(20700, _U('%1!, is verplicht.', 'DebiteurNummerOmzet')); //Ongeldige waarde <Parameternaam of opmerking>
    end if;
    if @_NawGidInkCombiPrijzen is null then
      call Raise(20700, _U('%1!, is verplicht.', 'DebiteurNummerPrijsafspraken')); //Ongeldige waarde <Parameternaam of opmerking>
    end if;
  end if;
end;


create or replace procedure WebSvcHulpProc_Offerte_Controleer_Offerte
( in @OfferteNummer numeric(10,0),
  in @RelatieBestand nchar(3) default null,
  in @RelatieNummer nchar(10) default null,
  in @DebiteurNummer nchar(10),
  in @GebruikDefaults smallint default 0,
  in @ContactPersoonNummer numeric(3,0),
  in @KeuzeVertegenwoordiger nchar(10),
  in @VertegenwoordigerNummer numeric(3,0),
  in @DefaultBtwCode nchar(3),
  in @KostenplaatsNummer nchar(8),
  in @KostendragerNummer nchar(8),
  in @MarketingEventCode nchar(40),
  in @LeverDatum date,
  in @PeriodeDoorlooptijd nchar(7),
  in @Doorlooptijd smallint,
  in @BerekeningOfferteTotaal nchar(23),
  in @OfferteTotaal numeric(15,2),
  in @OffScoringskans numeric(15,2),
  inout @_OffGid integer,
  inout @_OffOfferteNummer numeric(10,0),
  inout @_OffFonGidRelatie integer,
  inout @_OffNawGidRelatie integer,
  inout @_OffNawGidDebiteur integer,
  inout @_OffKstpGid integer,
  inout @_OffKstdGid integer,
  inout @_OffRelGidRelatie integer,        // Dit is contactpersoon van de relatie
  inout @_OffRelGidDebiteur integer,        // Dit is contactpersoon van de debiteur
  inout @_OffVtgCode integer,
  inout @_OffDoorlooptijdAantal smallint,
  inout @_OffDoorlooptijdPeriode smallint,
  inout @_OffLeverDatum date,
  inout @_OffMaevGid integer,
  inout @_OffBerekenMethodeOfferteTotaal  smallint,
  inout @_OffOfferteTotaal numeric(15,2) default null,
  inout @_OffVerwachteScoringsDatum date,
  inout @_OffBtwCode integer,
  inout @_OffScoringskans numeric(15,2)
)
begin
  declare _NAWBESTANDDEBITEUR nchar(3) = 'D';

  declare @_NawBestand nchar(3) default null;

  //Module controle
  if IsModuleActive('on') = 0 then
    call Raise(20790,_U('Optie Offertes')); // (20790) '%1!' niet geactiveerd!
  end if;

  //Gebruik defaults
  if @GebruikDefaults not in (0,1) then
    call Raise(20700,'GebruikDefaults'); // (20700) Ongeldige waarde: %1!
  end if;

  //Debiteur of relatie
  if @DebiteurNummer is not null then
  begin
    set @_NawBestand = _NAWBESTANDDEBITEUR;
    set @_OffFonGidRelatie = null;

    select NawFilNawGid
    into @_OffNawGidDebiteur
    from tabNawFile
    where NawFilFonId = @_NawBestand
      and NawFilNummer = @DebiteurNummer;

    if (@_OffNawGidDebiteur is null) then
      call Raise(20720,'DebiteurNummer'); // (20720) niet gevonden: %1!
    end if;
  end;
  else
    if @RelatieBestand is not null then
    begin
      set @_NawBestand = @RelatieBestand;

      select FonGid
      into @_OffFonGidRelatie
      from tabFileOfNaw
      where FonId = @_NawBestand;

      if @_OffFonGidRelatie = null then
        call Raise(20720,'RelatieBestand'); // (20720) niet gevonden: %1!
      end if;

      select NawFilNawGid
      into @_OffNawGidRelatie
      from tabNawFile
      where NawFilFonId = @_NawBestand
        and NawFilNummer = @RelatieNummer;

      if (@_OffNawGidRelatie is null) then
        call Raise(20720,'RelatieNummer'); // (20720) niet gevonden: %1!
      end if;
    end;
    end if;
  end if;

  //Contactpersoon van de relatie
  if isnull(@ContactPersoonNummer, 0) <> 0 then
    case @_NawBestand
      when 'D' then set @_OffRelGidDebiteur = ( select RelGid from tabRelatie where RelNawGid = @_OffNawGidDebiteur and RelNummer = @ContactPersoonNummer );
      else set @_OffRelGidRelatie = ( select RelGid from tabRelatie where RelNawGid = @_OffNawGidRelatie and RelNummer = @ContactPersoonNummer );
    end case;

    if (@_OffRelGidDebiteur is null and @_OffRelGidRelatie is null) then
      call Raise(20720,'ContactPersoonnummer'); // (20720) Niet gevonden: %1!
    end if;
  else
    case @_NawBestand
      when 'D' then set @_OffRelGidDebiteur = ( select RelGid
                                                from tabRelatie
                                                inner join  tabRelatieFunctie on (RelGid = FnRelGid)
                                                inner join (tabFunctieContact
                                                            inner join tabScherm on (SchermFnCode = FnCode and SchermSoort = 50 /* = offertes */)
                                                           ) on (FnCode = RelFnCode and IsBelangrijkste = 1)
                                                where RelNawGid = @_OffNawGidDebiteur
                                              );
      else set @_OffRelGidRelatie = ( select RelGid
                                      from tabRelatie
                                      inner join  tabRelatieFunctie on (RelGid = FnRelGid)
                                      inner join (tabFunctieContact
                                                  inner join tabScherm on (SchermFnCode = FnCode and SchermSoort = 50 /* = offertes */)
                                                 ) on (FnCode = RelFnCode and IsBelangrijkste = 1)
                                      where RelNawGid = @_OffNawGidRelatie
                                    );
    end case;
    end if;

  //Vaste gegevens offertes uitvragen v.w.b. vertegenwoordigercode
  //In Relatiebestand is geen vertegenwoordiger
  select  case OfvgDefaultVertegenwoordiger
            when 0 then null //leeg
            when 1 then null //van gebruiker, maar kingwebservice staat niet in tabGebruiker
            when 2 then (select NawVertegenwCode from tabNaw where NawGid = isNull(@_OffNawGidDebiteur, @_OffNawGidRelatie))  // Debiteur
            else null
          end case
  into @_OffVtgCode
  from tabOfferteVasteGegevens;

  if isnull(@VertegenwoordigerNummer,0) = 0 then
    // Men hoort een keuze opgegeven te hebben als men geen defaults gebruikt.
    if ( isnull(@KeuzeVertegenwoordiger,'') = '' and @GebruikDefaults = 0 ) then
      call Raise(20700,_U('%1!, is verplicht.', 'KeuzeVertegenwoordiger'));   // (20700) Ongeldige waarde: %1
    end if;

    // er is een keuze, wie wordt dan de vertegenwoordiger
    case isnull(@KeuzeVertegenwoordiger, 'VASTEGEG')
      when 'LEEG'     then set @_OffVtgCode = null;
      when 'DEBITEUR' then set @_OffVtgCode = (select NawVertegenwCode from tabNaw where NawGid = isNull(@_OffNawGidDebiteur, @_OffNawGidRelatie));
      when 'VASTEGEG' then set @_OffVtgCode = @_OffVtgCode;
      else call Raise(20700,_U('%1!, was: %2!', 'KeuzeVertegenwoordiger', @KeuzeVertegenwoordiger)); // (20700) Ongeldige waarde: %1
    end case ;
  else
    // Er is een vertegenwoordiger opgegeven, bestaat die ook...
    set @_OffVtgCode = (select VtgCode from tabVertegenwoordiger where VtgCode = @VertegenwoordigerNummer);

    if @_OffVtgCode is null then
      call Raise(20720,'VertegenwoordigerNummer'); // (20720) Niet gevonden: %1!
    end if;
  end if;

  if isnull(@DefaultBtwCode,'') <> '' then
    set @_OffBtwCode = (select BtwCode from tabBtw where BtwCode = @DefaultBtwCode );

    if @_OffBtwCode is null then
      call Raise(20700,'DefaultBtwCode'); // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  if isnull(@KostenplaatsNummer,'') <> '' then
    set @_OffKstpGid = (select KstpGid from tabKostenPlaats where KstpCode = @KostenplaatsNummer);

    if @_OffKstpGid is null then
      call Raise(20720,'KostenplaatsNummer'); // (20720) %1 niet gevonden: %1!
    end if;
  end if;

  if isnull(@KostendragerNummer,'') <> '' then
    set @_OffKstdGid = (select KstdGid from tabKostenDrager where KstdCode = @KostendragerNummer);

    if @_OffKstdGid is null then
      call Raise(20720,'KostendragerNummer'); // (20720) %1 niet gevonden: %1!
    end if;
  end if;

  if isnull(@MarketingEventCode, '') <> '' then
    set @_OffMaevGid = (select MaevGid from tabMarketingEvent where MaevCode = @MarketingEventCode );

    if @_OffMaevGid is null then
      call Raise(20720,'MarketingEventCode ' + '''' +  @MarketingEventCode + ''''); // (20720) %1 niet gevonden!
    end if;
  end if;

  if @LeverDatum is not null then
    set @_OffLeverDatum = @LeverDatum;
  end if;

  if ( isnull(@PeriodeDoorlooptijd,'') = '' and @GebruikDefaults = 0 ) then
    call Raise(20700,_U('%1!, is verplicht.', 'PeriodeDoorlooptijd')); // (20700) Ongeldige waarde: %1!
  end if;

  case isnull(@PeriodeDoorlooptijd,'MAANDEN')
    when 'DAGEN'    then set @_OffDoorlooptijdPeriode = 0;
    when 'WEKEN'    then set @_OffDoorlooptijdPeriode = 1;
    when 'MAANDEN'  then set @_OffDoorlooptijdPeriode = 2;
    when 'JAREN'    then set @_OffDoorlooptijdPeriode = 3;
    else call Raise(20700,_U('%1!, was: %2!', 'PeriodeDoorlooptijd', @PeriodeDoorlooptijd)) ; // (20700) Ongeldige waarde: %1!
  end case ;

  if (@Doorlooptijd is null and @GebruikDefaults = 0 ) then
    call Raise(20700,_U('%1!, is verplicht.', 'Doorlooptijd')); // (20700) Ongeldige waarde: %1!
  end if;
  set @_OffDoorlooptijdAantal = isnull(@Doorlooptijd,1);
  if not ( @_OffDoorlooptijdAantal between 1 and 999 ) then
    call Raise(20700,_U('%1!, toegestaan is waarde tussen %2! en %3!.', 'Doorlooptijd', '1', '999')); // (20700) Ongeldige waarde: %1!
  end if;

  // Doorlooptijd is nu gevalideerd, we kunnen de scoringsdatum berekenen.
  case @_OffDoorlooptijdPeriode
    when 0 then set @_OffVerwachteScoringsDatum = dateadd(day,   @_OffDoorlooptijdAantal, getdate() );
    when 1 then set @_OffVerwachteScoringsDatum = dateadd(week,  @_OffDoorlooptijdAantal, getdate() );
    when 2 then set @_OffVerwachteScoringsDatum = dateadd(month, @_OffDoorlooptijdAantal, getdate() );
    when 3 then set @_OffVerwachteScoringsDatum = dateadd(year,  @_OffDoorlooptijdAantal, getdate() );
    else call Raise(20700,'PeriodeDoorlooptijd'); // (20700) Ongeldige waarde: %1!
  end case;

  if (@BerekeningOfferteTotaal is null and @GebruikDefaults = 0) then
    call Raise(20700,_U('%1!, is verplicht.', 'BerekeningOfferteTotaal')); // (20700) Ongeldige waarde: %1!
  end if;

  case @BerekeningOfferteTotaal
    when null                       then set @_OffBerekenMethodeOfferteTotaal = @_OffBerekenMethodeOfferteTotaal;
    when 'HANDMATIG_OPGAVE'         then set @_OffBerekenMethodeOfferteTotaal = 0;
    when 'GEMIDDELDE_ALLE_VERSIES'  then set @_OffBerekenMethodeOfferteTotaal = 1;
    when 'VERSIE_LAAGSTE_TOTAAL'    then set @_OffBerekenMethodeOfferteTotaal = 2;
    when 'VERSIE_HOOGSTE_TOTAAL'    then set @_OffBerekenMethodeOfferteTotaal = 3;
    when 'EERSTE_VERSIE_TOTAAL'     then set @_OffBerekenMethodeOfferteTotaal = 4;
    when 'LAATSTE_VERSIE_TOTAAL'    then set @_OffBerekenMethodeOfferteTotaal = 5;
    when 'VASTEGEG'                 then set @_OffBerekenMethodeOfferteTotaal = @_OffBerekenMethodeOfferteTotaal;
    else call Raise(20700,'BerekeningOfferteTotaal'); // (20700) Ongeldige waarde: %1!
  end case;

  //Alleen bij een handmatige opgave mag het offertetotaal worden gevuld.
  if @_OffBerekenMethodeOfferteTotaal = 0 then
    set @_OffOfferteTotaal = @OfferteTotaal;
  end if;

  if @OffScoringskans is not null then
    if (@OffScoringskans not between 0 and 100 ) then
      call Raise(20700, _U('%1! moet tussen %2! en %3! liggen!', 'OffScoringskans', '0', '100')); // 20700 Ongeldige waarde: %1
    end if;

    set @_OffScoringskans = @OffScoringskans;
  end if;

  // Dit moet je als laatste actie in deze stored proc doen,
  // een gebruiker kan in King bezig zijn, en mogelijk een offertenummer ingevuld hebben,
  // maak dus het tijdgat zo klein mogelijk.
  if isnull(@OfferteNummer,0) = 0 then
    // Verkrijg een eerstvolgende offertenummer.die nog niet in gebruik is.
    set @_OffOfferteNummer = OfferteGenereerTrajectnummer(); // king 5 stored proc
  else
    set @_OffOfferteNummer = @OfferteNummer;
  end if;

  // Test of die opgegeven nummer niet al bestaat
  set @_OffGid = ( Select OffGid from tabOfferte where OffOfferteNummer = @_OffOfferteNummer );

  if @_OffGid is not null then
    call Raise(20721, _U('Offerte')); //(20721) %1! komt al voor!
  end if;
end;


create or replace procedure WebSvcHulpProc_Offerte_Controleer_OfferteRegel
(
  in @Regelsoort                                  nchar(7),
  in @ArtikelNummer                               nchar(20),
  in @TekstOpOfferte                              long nvarchar,
  in @Aantal                                      numeric(15,3),
  in @Bedrag                                      numeric(15,3),
  in @Korting1                                    numeric(15,3),
  in @Korting2                                    numeric(15,2),
  in @Korting1IsPercentage                        smallint,
  in @PartijNummer                                nchar(20),
  in @VerkoopEenheid                              nchar(20),
  in @EenheidPrijsPer                             nchar(20),
  in @AantalVoorraadEenhedenInVerkoopEenheid      numeric(15,3),
  in @OfkGid                                      integer,
  inout @_OfrArtGidArtikel                        integer,
  inout @_OfrArtGidTarief                         integer,
  inout @_OfrArtGidTekstblok                      integer,
  inout @_OfrArtPartijGid                         integer,
  inout @_OfrBtwCode                              integer,
  inout @_OfrAantalDecimalenVoorAantallen         smallint,
  inout @_OfrAantalDecimalenVoorPrijzen           smallint,
  inout @_OfrAantalteOffreren                     numeric(15,3),
  inout @_OfrGeprijsdPer                          numeric(15,3),
  inout @_OfrKostprijs                            numeric(15,3),
  inout @_OfrPrijs                                numeric(15,3),
  inout @_OfrStukskorting1Bedrag                  numeric(15,3),
  inout @_OfrStukskorting1Percentage              numeric(15,2),
  inout @_OfrStukskorting2Percentage              numeric(15,2),
  inout @_OfrRegelPositie                         smallint,
  inout @_OfrRegelSoort                           smallint,
  inout @_OfrTekstOpOfferte                       long nvarchar,
  inout @_OfrVkeGid                               integer,
  inout @_OfrAantalVrrdEenhInVerkEenh             numeric(15,3),
  inout @_OfrEenheidPrijsPer                      smallint,
  inout @_OfrAantalDecimalenVoorAantallenVrrdEenh smallint,
  inout @_OfrAantalTeOffrerenVrrdEenh             numeric(15,3),
  inout @_OfrAantalVrrdEenhInVerkEenhMagAfwijken  smallint
)
begin

  case @Regelsoort
    when 'TEKST'    then set @_OfrRegelSoort = 0;
    when 'TAR'      then set @_OfrRegelSoort = 1;
    when 'ART'      then set @_OfrRegelSoort = 2;
    when 'KORTING'  then set @_OfrRegelSoort = 3;
    when 'INRUIL'   then set @_OfrRegelSoort = 4;
    else call Raise(20720,'Regelsoort');            // (20720) %1 niet gevonden!
  end case;

  if ( (IsNull(@ArtikelNummer, '') = '') and @_OfrRegelSoort in (0,1,2) )
     or ( ( IsNull(@ArtikelNummer, '') <> '') and @_OfrRegelSoort in (3,4) ) then
    call Raise(20700,'ArtikelNummer'              ); // (20700) Ongeldige waarde %1!
  end if;

  begin // ArtGid bij soort regel en wat er nog bij hoort.
    declare @_TmpArtGid                         integer;
    declare @_TmpArtSoort                       smallint;
    declare @_TmpBtwStand                       smallint;


    set @_OfrAantalteOffreren = isnull(@Aantal,0);

    // Voor tekstblok, tarief of artikel moet het nummer bestaan.
    if @_OfrRegelSoort in (0,1,2) then
      set @_TmpArtGid = (select ArtGid from tabArtikel where ArtSoort = @_OfrRegelSoort and ArtCode = @ArtikelNummer);
      if @_TmpArtGid is null then
        call Raise(20720, 'ArtikelNummer');           // (20720) %1 niet gevonden!
      end if;
    end if;

    set @_TmpArtSoort = @_OfrRegelSoort;
    // Kortingstarief ...
    if @_OfrRegelSoort = 3 then
      set @_TmpArtGid = ( select OfvgArtGidKortingstarief from tabOfferteVasteGegevens );
      if @_TmpArtGid is null then
        call Raise(20700, _U('Kortingstarief. Controleer in King de vaste gegevens Offertes'));
      end if;
      set @_TmpArtSoort = 1; // ... is een tarief
      set @_OfrAantalteOffreren = -1;
    end if;

    // Inruiltarief
    if @_OfrRegelSoort = 4 then
      set @_TmpArtGid = ( select OfvgArtGidInruiltarief from tabOfferteVasteGegevens );
      if @_TmpArtGid is null then
        call Raise(20700, _U('Inruiltarief. Controleer in King de vaste gegevens Offertes'));
      end if;
      set @_TmpArtSoort = 1; // ... is een tarief
      set @_OfrAantalteOffreren = -1;
    end if;

    if (isnull(@VerkoopEenheid,'') <> '' ) then
      set @_OfrVkeGid = (select VkeGid from tabVerkoopeenheid where VkeVerkoopEenheid = @Verkoopeenheid and VkeArtGid = @_TmpArtGid );
      if @_OfrVkeGid is null then
        call Raise(20720,'Verkoopeenheid ' + '''' + @VerkoopEenheid + '''') ; // (20720) %1 niet gevonden!
      end if;
    end if;

    call WebsvcHulpProc_Offerte_ValideerVerkoopeenheid_Regel(
      @_TmpArtSoort,                            //in  0= tekstblok, 1= tarief, 2= artikel
      @_TmpArtGid,                              //in    @ArtGid
      @_OfrAantalteOffreren,                    //in    @Aantal
      @_OfrAantalteOffreren,                    //in    @AantalDezeFacturering
      @_OfrAantalteOffreren,                    //in    @AantalDezeLevering
      @AantalVoorraadEenhedenInVerkoopEenheid,  //in    @AantalVoorraadEenhedenInVerkoopEenheid
      @AantalVoorraadEenhedenInVerkoopEenheid,  //in    @AantalVrrdEenhDezeFacturering
      @AantalVoorraadEenhedenInVerkoopEenheid,  //in    @AantalVrrdEenhDezeLevering
      @VerkoopEenheid,                          //in
      @_OfrVkeGid,                              //out
      @_OfrGeprijsdPer,                         //out
      @_OfrAantalDecimalenVoorPrijzen,          //out
      @_OfrAantalVrrdEenhInVerkEenh,            //out
      @_OfrEenheidPrijsPer,                     //out
      @_OfrAantalVrrdEenhInVerkEenhMagAfwijken, //out 0 = nee, 1= ja, 2= alleen bij facturering/levering
      @_OfrAantalDecimalenVoorAantallen,        //out
      @_TmpBtwStand,                            //out  ArtVerkPrijsisIncl: 0=excl, 1=incl
      @_OfrPrijs,                               //out  VkeVerkoopPrijs
      @_OfrBtwCode,                             //out  BTW code van artikel
      @_OfrAantalTeOffrerenVrrdEenh,            //out
      @_OfrKostprijs,                           //out   @_ArtKostprijsEx
      // Onderstaande niet nodig voor offertes, maar wel voor o.a. orderregel
      // We zijn al bezig met artikelgegevens, dan maar gelijk meenemen...
      null, //out   @_ArtOpbrGrpGid
      null, //out   @_AantalVrrdEenhDezeFacturering
      null, //out   @_AantalVrrdEenhDezeLevering
      null  //out  @_ArtIsAantallen
    );


    //raiserror 20700,'TESTTEST';
    begin // verkoopprijs omrekenen of niet...
      //Verkoopprijs is per verkoopeenheid, maar moet per voorraadeenheid
      if ( isnull(@EenheidPrijsPer,'VOORRAADEENHEDEN') = 'VOORRAADEENHEDEN' and @_OfrEenheidPrijsPer = 0 ) then
        set @_OfrPrijs = @_OfrPrijs / @_OfrAantalTeOffrerenVrrdEenh;
      end if;

      //Verkoopprijs is per voorraadeenheid, maar moet per verkoopeenheid
      if ( isnull(@EenheidPrijsPer,'VOORRAADEENHEDEN') = 'VERKOOPEENHEID' and @_OfrEenheidPrijsPer = 1 ) then
        set @_OfrPrijs = @_OfrPrijs * @_OfrAantalVrrdEenhInVerkEenh;
      end if;

      // prijs is omgerekend maar niet afgerond op decimalen vanwege eventueel BTW omrekenwerk.
      // nu kan je definitief aangeven wat de eenheid is.
      case isnull(@EenheidPrijsPer,'VOORRAADEENHEDEN')
        when 'VOORRAADEENHEDEN' then set @_OfrEenheidPrijsPer = 1;
        when 'VERKOOPEENHEID'   then set @_OfrEenheidPrijsPer = 0;
        else call Raise(20700,'EenheidPrijsPer') ;      // (20700) Ongeldige waarde %1!
      end case;
    end;  // verkoopprijs omrekenen of niet...

    begin // Prijs/Bedrag en bijbehorende BTW code van regel definitief vaststellen

      declare @ArtBtwPercentage   numeric(6,2) = (select BtwPercentage from tabBtw where BtwCode = @_OfrBtwCode );
      declare @OfkBtwStand        smallint;
      declare @OfkBtwPercentage   numeric(6,2);
      declare @OffBtwCode         integer;
      // Wat is BTW code en percentage volgens de offerte? Btw code kan daar null zijn.
      select  OfkBtwStand,
              OffBtwCode,
              BtwPercentage
        into  @OfkBtwStand,
              @OffBtwCode,
              @OfkBtwPercentage
      from      tabOfferteKop
      key join  tabOfferte
      left join tabBtw
      where     OfkGid = @OfkGid;

      // Prijs artikel is incl BTW maar moet in offerteversie ex BTW zijn
      if (@_TmpBtwStand <> 0 and @OfkBtwStand = 0 ) then
        set @_OfrPrijs = round( @_OfrPrijs * 100 / (100 + @ArtBtwPercentage), @_OfrAantalDecimalenVoorPrijzen );
      end if;
      // prijs artikel is ex BTW ,aar moet in offerteversie incl BTW zijn
      // Percentage:  Als BTW code bij offerte niet ingevuls is dan volgens BTW code artikel
      if (@_TmpBtwStand = 0 and @OfkBtwStand <> 0 ) then
        set @_OfrPrijs = round( @_OfrPrijs * (100 + isnull(@OfkBtwPercentage ,@ArtBtwPercentage)) / 100 , @_OfrAantalDecimalenVoorPrijzen );
      end if;
      // prijs bij artikel is incl BTW, en dat moet ook n offerteversie,
      // dan kan nog wel de BTW code in offerteversie verschil maken.
      if (@_TmpBtwStand <> 0 and @OfkBtwStand <> 0 ) then
        set @_OfrPrijs = round( @_OfrPrijs * (100 + isnull(@OfkBtwPercentage, @ArtBtwPercentage)) / (100 + @ArtBtwPercentage ), @_OfrAantalDecimalenVoorPrijzen );
      end if;
      // Er is een bedrag opgegeven, dan die gewoon toepassen.
      if @Bedrag is not null then set @_OfrPrijs = @Bedrag end if;

      // BTW code nu definitief goed zetten. Is die niet bij offerte ingevuld, dan volgens artikel/tarief
      set @_OfrBtwCode = isnull(@OffBtwCode, @_OfrBtwCode);

    end; // Prijs/Bedrag van regel definitief vaststellen

    // bij elke Regelsoort is nu artikelnummer gevalideerd,
    // nu in juiste rubriek van offerteregel zetten.
    // A.u.b. geen enkele gid invullen voor inruil of korting
    case @_OfrRegelSoort
      when 0 then set @_OfrArtGidTekstblok = @_TmpArtGid;
      when 1 then set @_OfrArtGidTarief = @_TmpArtGid;
      when 2 then set @_OfrArtGidArtikel = @_TmpArtGid;
    end case;

    // Omschrijving eerst o.b.v. taalcode in offerteversie uitvragen.
    // Is daar niks, dan terug vallen op artikelomschrijving bij artikel zelf.
    if ( isnull(@TekstOpOfferte,'') = '' ) then
      set @_OfrTekstOpOfferte = (select ArtOms from tabArtikel where ArtGid = @_TmpArtGid);
      set @_OfrTekstOpOfferte = isnull( ( select ArtTekst
                                          from tabArtikelTeksten
                                          where artTaalGid = (select OfkTaalGid from tabOfferteKop where OfkGid = @OfkGid and artTekstArtGid = @_TmpArtGid) ),
                                          @_OfrTekstOpOfferte );
    else
      set @_OfrTekstOpOfferte = @TekstOpOfferte ;
    end if;



  end; // ArtGid van soort regel en wat erbij hoort

  begin // Partijnummer
    if ( isnull(@PartijNummer, '') <> '' and @_OfrArtGidArtikel is not null ) then
      select ArtPartijGid into @_OfrArtPartijGid from tabArtikelPartij where ArtPartijArtGid = @_OfrArtGidArtikel and ArtPartijNummer = @PartijNummer;
      if (@_OfrArtPartijGid is null) then
        call Raise(20720,'PartijNummer');           // (20720) %1 niet gevonden!
      end if;
    end if;
  end; // Partijnummer

  begin // Stukskorting
    if IsNull(@Korting1IsPercentage, 0) not in (0,1) then
      call Raise(20700,'Korting1IsPercentage');                             // (20700) Ongeldige waarde %1
    end if;

    if (@Korting1IsPercentage = 0) then
      set @_OfrStukskorting1Bedrag = @Korting1;
    end if;

    if (@Korting1 is not null) and (@Korting1IsPercentage = 1) then
      if (@Korting1 < -100) or (@Korting1 > 100) then
        call Raise(20700,_U('%1!, percentage niet tussen %2! en %3!', 'Korting1', '-100', '100'));   // (20700) Ongeldige waarde %1
      end if;
      set @_OfrStukskorting1Percentage = Round(@Korting1, 2);
    end if;

    if (@Korting2 is not null) then
      if (@Korting2 < -100) or (@Korting2 > 100) then
        call Raise(20700,_U('%1!, percentage niet tussen %2! en %3!', 'Korting2', '-100', '100'));  // (20700) Ongeldige waarde %1
      end if;
      set @_OfrStukskorting2Percentage = Round(@Korting2, 2);
    end if;
  end; // Stukskorting
end;

create or replace procedure WebSvcHulpProc_Offerte_ExclusiefLocken(
  in @LockOffGid integer,
  in @LockUserNaam nchar(40) default null,
  in @SpId integer default null,
  in @LoginTime datetime default null)
begin
  declare @_LockResult  integer;

  // Defaults instellen
  if @LockUserNaam is null then
    set @LockUserNaam = 'KingWebservice';
  end if;
  if @SpId is null then
    set @SpId = @@SpId;
  end if;
  if @LoginTime is null then
    set @LoginTime = @@LoginTime;
  end if;

  if not exists ( select 1 from tabOfferte where OffGid = @LockOffGid ) then
    call Raise(20780, _U('In gebruik nemen'), _U('offerte niet gevonden')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if LockedById(@SpId, @LoginTime, 1 /*exclusieve lock*/, 'tabOfferte', @LockOffGid) = 0 then
    call LockSetOnId( @Spid,
                      @LoginTime,
                      1,                        // 1 = Exclusieve lock, 0 = ReadLock
                      'tabOfferte',             // tabel waarin record te locken is - nchar(40)
                      string(@LockOffGid),      // lockstring voor record, nchar(80)
                      @_LockResult,             // 0 = OK, anders fout
                      0,                        // Automatisch opruimen: 0 = nee, 1 = ja
                      @LockUserNaam);         // Welke King gebruiker of proces

     if @_Lockresult <> 0 /* OK */ then
       call Raise(20741, _U('Offerte'));    // (20741) %1 is in gebruik!
     end if;
  end if;
end;



create or replace procedure WebsvcHulpProc_Offerte_ValideerVerkoopeenheid_Regel
( in    @ArtSoort                                       smallint,       // 0=tekstblok, 1=tarief, 2=artikel
  in    @ArtGid                                         integer,
  in    @Aantal                                         numeric(15,3),
  in    @AantalDezeFacturering                          numeric(15,3),
  in    @AantalDezeLevering                             numeric(15,3),
  in    @AantalVoorraadEenhedenInVerkoopEenheid         numeric(15,3),
  in    @AantalVrrdEenhDezeFacturering                  numeric(15,3),
  in    @AantalVrrdEenhDezeLevering                     numeric(15,3),
  in    @Verkoopeenheid                                 nchar(20),
  out   @_VkeGid                                        integer,
  out   @_ArtPrijsPer                                   numeric(15,3),  // Aantal prijseenheden waarvoor de prijs geldt
  out   @_ArtAantDecPrijzen                             smallint,
  out   @_VkeAantalVoorraadEenhedenInVerkoopEenheid     numeric(15,3),
  out   @_VkeVerkoopPrijsPer                            smallint,       // 0=verkoopeenheid, 1=voorraadeenheden
  out   @_VkeAantalKanVerschillen                       smallint,       // 0=nee, 1=bestelling mag afwijken, 2=facturering/levering mag afwijken
  out   @_VkeAantalDecimalen                            smallint,
  out   @_VkeIsVerkoopprijsInclusiefBTW                 smallint,       // 0=excl, 1=incl
  out   @_VkeVerkoopPrijs                               numeric(15,3),
  out   @_ArtBtwCode                                    integer,        // Code van toegepaste BTW percentage
  out   @_AantalVrrdEenh                                numeric(15,3),
  out   @_ArtKostprijsEx                                numeric(15,3),
  // Onderstaande niet nodig voor offertes, maar wel voor o.a. orderregel
  // We zijn in deze stored proc toch al bezig met artikelgegevens, dan maar gelijk meenemen...
  out   @_ArtOpbrGrpGid                                 integer,
  out   @_AantalVrrdEenhDezeFacturering                 numeric(15,3),
  out   @_AantalVrrdEenhDezeLevering                    numeric(15,3),
  out   @_ArtIsAantallen                                smallint
)
begin
  // bron van deze stored proc is afkomstig uit de webservice Order_OrderRegel_Toevoegen
  // Hier zoveel reusable / generiek te maken, dat het als eerste voor de offerteregel getest is,
  // en dan via refactoren bij andere stored procs of webservices gebruikt kan worden.
  // Er is wel een verbetering doorgevoerd:
  // verkoopeenheden kent extra instelling VkeHeeftAparteVerkoopPrijsOfKorting,
  // Dat heeft invloed op de bepaling van verkooprijs en bijbehorende soort eenheid waarvoor die geldt.

  declare @_VkeIsVoorraadeenheid          smallint;
  declare @_VkeIsGeblokkeerdVoorVerkoop   smallint;

  if @ArtSoort not in (0,1,2) then
    call Raise(20700,'ArtSoort');
  end if;
  //
  select  ArtOpbrGrpGid,
          ArtKostprijsEx,
          ArtPrijsPer,
          ArtAantDecPrijzen,
          ArtAantallen,
          VkeGid,
          case VkeHeeftAparteVerkoopPrijsOfKorting                              // 2= aparte prijs en korting, 1= alleen aparte korting, 0= nee
            when 2 then isnull(VkeVerkoopPrijsPer,1)                            // default = voorraadeenheid
            else 1                                                              // niet apart, dan bij voorraadeenheid
          end case,
          isnull(VkeAantalVoorraadEenhedenInVerkoopEenheid,1),                  // default = 1 voorraadeenheid
          isnull(VkeAantalKanVerschillen,0),                                    // default = mag niet afwijken (bij voorraadeenheid)
          if VkeAantalDecimalen = 4 then isnull(ArtAantDecAantallen,0) else VkeAantalDecimalen end if,
          VkeIsVoorraadeenheid,
          VkeIsGeblokkeerdVoorVerkoop,
          case
            when VkeHeeftAparteVerkoopPrijsOfKorting <> 2 then ArtVerkPrijsIsIncl
            else isnull(VkeIsVerkoopprijsInclusiefBTW, ArtVerkPrijsIsIncl)
          end case,
          case
            when ArtSoort = 0 then 0                                            // tekstblok:     kost niks, kan misschien in de toekomst geld kosten :O)
            when ArtSoort = 1 then ArtVerkPrijs                                 // tarief:        kent geen verkoopeenheid
            when VkeHeeftAparteVerkoopPrijsOfKorting  = 2 then VkeVerkoopPrijs  // voor artikel:  2= aparte prijs en korting, 1= alleen aparte korting, 0= nee
            else isnull( (select VkeVerkoopPrijs from tabVerkoopEenheid where VkeArtGid = ArtGid and VkeIsVoorraadeenheid = 1 ), ArtVerkPrijs ) // geen aparte prijs, dan bij voorraadeenheid ophalen.
          end case,
          ArtBtwCode
  into    @_ArtOpbrGrpGid,
          @_ArtKostprijsEx,
          @_ArtPrijsPer,
          @_ArtAantDecPrijzen,
          @_ArtIsAantallen,
          @_VkeGid,
          @_VkeVerkoopPrijsPer,
          @_VkeAantalVoorraadEenhedenInVerkoopEenheid,
          @_VkeAantalKanVerschillen,
          @_VkeAantalDecimalen,
          @_VkeIsVoorraadeenheid,
          @_VkeIsGeblokkeerdVoorVerkoop,
          @_VkeIsVerkoopprijsInclusiefBTW,
          @_VkeVerkoopPrijs,
          @_ArtBtwCode

  from              tabArtikel
  left outer join   tabVerkoopeenheid
               on   VkeArtGid=ArtGid
               and ( ( VkeVerkoopEenheid = @VerkoopEenheid ) or ( ( isnull(@VerkoopEenheid,'') = '' ) and VkeIsVoorraadeenheid=1 ) )
  where   ArtSoort = @ArtSoort
    and   ArtGid = @ArtGid;

  // bij artikel moet er een verkoopeenheid zijn (er is een voorraadeenheid)
  if ( @_VkeGid is null and @ArtSoort = 2 ) then
    call Raise(20720,  'Verkoopeenheid');                                   // (20720) %1 niet gevonden
  end if;

  //artikel of tarief: als die aangeven met aantallen te werken, dan moet men ook een aantal aanleveren
  if (@ArtSoort <> 0) and (@_ArtIsAantallen = 1) and ( isnull(@Aantal, 0) = 0 ) then
    call Raise(20700, _U('%1! voor artikel of tarief is dit verplicht.', 'Aantal'));  //Ongeldige of geen Aantal meegegeven!;
  end if;

  // nu rekenwerk doen op basis van opgegeven @aantal
  if @_VkeIsGeblokkeerdVoorVerkoop = 1 then
    call Raise(20760,  _U('De verkoopeenheid is geblokkeerd voor verkoop'));    // (20760) Ongeldige status: %1!
  end if;

  //In bepaalde gevallen mogen velden niet afwijken van elkaar. Reken de verkoopeenheden om naar voorraadeenheden.
  if @_VkeIsVoorraadeenheid = 1 then    /*De voorraadeenheid. Dus alles gelijkstellen aan elkaar.*/
    set @_AantalVrrdEenh                  = @Aantal;
  else
    begin
      if @_VkeAantalKanVerschillen = 2   /*Afwijkend aantal bij Levering/Facturering*/  then
        //Reken de verkoopeenheden om naar voorraadeenheden
        set @_AantalVrrdEenh                = @Aantal                                                       * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        set @_AantalVrrdEenhDezeLevering    = isNull(@AantalVrrdEenhDezeLevering, @AantalDezeLevering       * @_VkeAantalVoorraadEenhedenInVerkoopEenheid);
        set @_AantalVrrdEenhDezeFacturering = isNull(@AantalVrrdEenhDezeFacturering, @AantalDezeFacturering * @_VkeAantalVoorraadEenhedenInVerkoopEenheid);
      else
        if @_VkeAantalKanVerschillen = 1 /*Afwijkend aantal bij Aantal geoffreerd/besteld*/ then
          // heeft men geen vooorraadeenheden in verkoopeenheid opgegeven, dan blijft het bij het aantal dat bij verkoopenheid staat.
          set @_VkeAantalVoorraadEenhedenInVerkoopEenheid = isNull( @AantalVoorraadEenhedenInVerkoopEenheid,  @_VkeAantalVoorraadEenhedenInVerkoopEenheid );
        end if;
        set @_AantalVrrdEenh                = @Aantal                 * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        set @_AantalVrrdEenhDezeLevering    = @AantalDezeLevering     * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        set @_AantalVrrdEenhDezeFacturering = @AantalDezeFacturering  * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
      end if;
    end;
  end if;

end;



create or replace procedure WebSvcProc_Offerte_LockVrijgeven(in @OfferteNummer numeric(10,0))
begin
  declare @_OffGid   integer;
  declare @_qLockGid integer;

  //call TraceBegin('WebSvcProc_Order_LockVrijgeven');

  // Module controle
  if IsModuleActive('on') = 0 then
    call Raise(20790, _U('Optie Offertes')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken Offerte
  select OffGid into @_OffGid
  from   tabOfferte
  where  OffOfferteNummer = @OfferteNummer;

  if @_OffGid is null then
    call Raise(20720, 'OfferteNummer'); // (20720) niet gevonden: %1!
  end if;

  //Elke webservice heeft zijn eigen connection id.
  //Het standaard lockmechanisme werkt in dat geval dan niet.
  //het vrijgeven van een lock gaat dan niet op SpId, maar op usernaam

  begin // lock vrijgeven
    call LockReleaseOnId(@@SpId, @@LoginTime, 1, 'tabOfferte', @_OffGid);

    // gelockt, maar niet door KingWebService? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = 'tabOfferte' and qLockPKey = String(@_OffGid) and qLockUser <> 'KingWebService') then
      call Raise(20741, _U('Offerte')); // (20741) %1! is in gebruik!
    end if;

    // De offerte zou dus wel door KingWebService gelockt zijn, deze opruimen.
    call LockReleaseOnUserName('KingWebService', 1, 'tabOfferte', @_OffGid);
  end; // lock vrijgeven

  //call TraceEind('WebSvcProc_Order_LockVrijgeven');
end;


create or replace procedure WebSvcProc_Offerte_Offerteregel_Toevoegen
(
  in @OfferteNummer                           numeric(10,0),
  in @VersieNummer                            numeric(3,0),
  in @RegelSoort                              nchar(7),
  in @ArtikelNummer                           nchar(20),
  in @TekstOpOfferte                          long nvarchar,
  in @Aantal                                  numeric(15,3),
  in @Bedrag                                  numeric(15,3),
  in @Korting1                                numeric(15,3),
  in @Korting2                                numeric(15,2),
  in @Korting1IsPercentage                    smallint,
  in @PartijNummer                            nchar(20),
  in @VerkoopEenheid                          nchar(20)       default '',
  in @EenheidPrijsPer                         nchar(20)       default 'VOORRAADEENHEDEN',
  in @AantalVoorraadEenhedenInVerkoopEenheid  numeric(15,3)   default 1
)
result( RegelNummer smallint )
begin
  declare @_OfrGid                                    integer;
  declare @_OfrOfkGid                                 integer;
  declare @_OfrArtGidArtikel                          integer;
  declare @_OfrArtGidTarief                           integer;
  declare @_OfrArtGidTekstblok                        integer;
  declare @_OfrArtPartijGid                           integer;
  declare @_OfrBtwCode                                integer;
  declare @_OfrAantalDecimalenVoorAantallen           smallint;
  declare @_OfrAantalDecimalenVoorPrijzen             smallint;
  declare @_OfrAantalteOffreren                       numeric(15,3);
  declare @_OfrGeprijsdPer                            numeric(15,3);
  declare @_OfrKostprijs                              numeric(15,3);
  declare @_OfrPrijs                                  numeric(15,3);
  declare @_OfrStukskorting1Bedrag                    numeric(15,3);
  declare @_OfrStukskorting1Percentage                numeric(15,2);
  declare @_OfrStukskorting2Percentage                numeric(15,2);
  declare @_OfrRegelkorting1Bedrag                    numeric(15,3);
  declare @_OfrRegelkorting1Percentage                numeric(15,2);
  declare @_OfrRegelkorting2Percentage                numeric(15,2);
  declare @_OfrRegelPositie                           smallint;
  declare @_OfrRegelsoort                             smallint;
  declare @_OfrTekstOpOfferte                         long nvarchar;
  declare @_OfrVkeGid                                 integer;
  declare @_OfrAantalVrrdEenhInVerkEenh               numeric(15,3);
  declare @_OfrEenheidPrijsPer                        smallint;
  declare @_OfrAantalDecimalenVoorAantallenVrrdEenh   smallint;
  declare @_OfrAantalTeOffrerenVrrdEenh               numeric(15,3);
  declare @_OfrAantalVrrdEenhInVerkEenhMagAfwijken    smallint;

  //call TraceBegin('WebSvcProc_Offerte_OfferteRegel_Toevoegen ' + '> @OfferteNummer = ' + string(@OfferteNummer) +   ', @VersieNummer = ' + string(@VersieNummer) +   ', @RegelSoort = ' + string(@RegelSoort) +', @ArtikelNummer = ' + @ArtikelNummer);

  if IsModuleActive('on') = 0 then
    call Raise(20790,_U('Optie Offertes'));          // (20790) '%1!' niet geactiveerd!
  end if;

  if not exists (select OffGid from tabOfferte where OffOfferteNummer = @OfferteNummer) then
    call Raise(20720, 'OfferteNummer');             // (20720 %1 niet gevonden!
  end if;

  set @_OfrOfkGid = (select OfkGid from tabOfferteKop inner join tabOfferte on OffGid = OfkOffGid where OffOfferteNummer = @OfferteNummer and OfkVersieNummer = @VersieNummer );
  if (@_OfrOfkGid is null) then
    call Raise(20720, 'VersieNummer');              // (20720 %1 niet gevonden!
  end if;

  // ******************************
  // Defaults voor offerteRegel
  // Dit kan pas met een bestaande offerte
  // ******************************
  begin
    set @_OfrAantalDecimalenVoorAantallen = 0;
    set @_OfrAantalDecimalenVoorPrijzen = 2;
    set @_OfrStukskorting1Bedrag = 0;
    set @_OfrStukskorting1Percentage = 0;
    set @_OfrStukskorting2Percentage = 0;
    set @_OfrRegelkorting1Bedrag = 0;
    set @_OfrRegelkorting1Percentage = 0;
    set @_OfrRegelkorting2Percentage = 0;
    set @_OfrKostprijs = 0;
    set @_OfrPrijs = 0;
    set @_OfrAantalTeOffreren = 1;
    set @_OfrVkeGid = null ;                  // geen verkoopeenheid
    set @_OfrEenheidPrijsPer = 1;             // per voorraadeenheden
    set @_OfrAantalVrrdEenhInVerkEenh = 1;    //
    set @_OfrAantalDecimalenVoorAantallenVrrdEenh = 0;
    set @_OfrAantalTeOffrerenVrrdEenh = 1;
  end;

  // We gaan de details voor de regel in aparte hulpprocedure regelen,
  // de inhoud ervan is mogelijk reusable (denk aan orders, etc).
  call WebSvcHulpProc_Offerte_Controleer_OfferteRegel(
    //in
    @RegelSoort,
    @ArtikelNummer,
    @TekstOpOfferte,
    @Aantal,
    @Bedrag,
    @Korting1,
    @Korting2,
    @Korting1IsPercentage,
    @PartijNummer,
    @VerkoopEenheid,
    @EenheidPrijsPer,
    @AantalVoorraadEenhedenInVerkoopEenheid,
    @_OfrOfkGid,
    // out
    @_OfrArtGidArtikel,
    @_OfrArtGidTarief,
    @_OfrArtGidTekstblok,
    @_OfrArtPartijGid,
    @_OfrBtwCode,
    @_OfrAantalDecimalenVoorAantallen,
    @_OfrAantalDecimalenVoorPrijzen,
    @_OfrAantalteOffreren,
    @_OfrGeprijsdPer,
    @_OfrKostprijs,
    @_OfrPrijs,
    @_OfrStukskorting1Bedrag,
    @_OfrStukskorting1Percentage,
    @_OfrStukskorting2Percentage,
    @_OfrRegelPositie,
    @_OfrRegelsoort,
    @_OfrTekstOpOfferte,
    @_OfrVkeGid,
    @_OfrAantalVrrdEenhInVerkEenh,
    @_OfrEenheidPrijsPer,
    @_OfrAantalDecimalenVoorAantallenVrrdEenh,
    @_OfrAantalTeOffrerenVrrdEenh,
    @_OfrAantalVrrdEenhInVerkEenhMagAfwijken
  );

  // De controle offerteregel geeft stukskortingen terug (indien van toepassing)
  // Als de instelling in vaste gegevens orders/facturering wat anders aangeeft,
  // dan moeten we vooraf even wat andere velden invullen.
  // 0 = regelkorting , 1 = stukskorting
  if isnull(  (select vofIsStukskorting from tabVasteGegevensOrdersFactureren), -1  ) = 0 then
    set @_OfrRegelkorting1Bedrag      = @_OfrStukskorting1Bedrag;
    set @_OfrRegelkorting1Percentage  = @_OfrStukskorting1Percentage;
    set @_OfrRegelkorting2Percentage  = @_OfrStukskorting2Percentage;

    set @_OfrStukskorting1Bedrag      = 0;
    set @_OfrStukskorting1Percentage  = 0;
    set @_OfrStukskorting2Percentage  = 0;
  end if;

  begin atomic
    // offerteregels toevoegen kan alleen in versie met status concept
    if not exists (select OfkStatus from tabOfferteKop where OfkGid = @_OfrOfkGid and OfkStatus = 0 ) then
      call Raise(20780, _U('Offerteregel toevoegen'), _U('offerteversie heeft niet de concept status'));
    end if;

    // Offerte locken als dat nog niet het geval is.
    begin
      declare @_LockResult  integer;
      declare @_OffGid      integer;

      set @_OffGid = (select OfkOffGid from tabOfferteKop where OfkGid = @_OfrOfkGid);

      if LockedById(@@SpId, @@LoginTime, 1, 'tabOfferte', @_OffGid) = 0 then
        call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOfferte', @_OffGid, @_Lockresult, 0, 'KingWebService');
        if @_Lockresult <> 0 then
          call Raise(20741,_U('Offerte'));    // (20741) %1! is in gebruik!
        end if;
      end if;
    end;

    //We voegen een regel toe, dus nieuw regelnummer bepalen.
    if (@_OfrRegelPositie is null) then
      set @_OfrRegelPositie = isnull( ( select max(OfrRegelPositie) from tabOfferteRegel where OfrOfkGid = @_OfrOfkGid ) ,0 ) + 1 ;
    end if;

    // ******************************
    // Voeg offerteregel toe
    // ******************************
    insert into tabOfferteRegel(
      OfrOfkGid,
      OfrArtGidArtikel,
      OfrArtGidTarief,
      OfrArtGidTekstblok,
      OfrArtPartijGid,
      OfrBtwCode,
      OfrAantalDecimalenVoorAantallen,
      OfrAantalDecimalenVoorPrijzen,
      OfrAantalteOffreren,
      OfrGeprijsdPer,
      OfrKostprijs,
      OfrPrijs,
      OfrStukskorting1Bedrag,
      OfrStukskorting1Percentage,
      OfrStukskorting2Percentage,
      OfrRegelkorting1Bedrag,
      OfrRegelkorting1Percentage,
      OfrRegelkorting2Percentage,
      OfrRegelPositie,
      OfrRegelsoort,
      OfrTekstOpOfferte,
      OfrVkeGid,
      OfrAantalVrrdEenhInVerkEenh,
      OfrEenheidPrijsPer,
      OfrAantalDecimalenVoorAantallenVrrdEenh,
      OfrAantalTeOffrerenVrrdEenh,
      OfrAantalVrrdEenhInVerkEenhMagAfwijken
    )
    values (
      @_OfrOfkGid,
      @_OfrArtGidArtikel,
      @_OfrArtGidTarief,
      @_OfrArtGidTekstblok,
      @_OfrArtPartijGid,
      @_OfrBtwCode,
      @_OfrAantalDecimalenVoorAantallen,
      @_OfrAantalDecimalenVoorPrijzen,
      @_OfrAantalteOffreren,
      @_OfrGeprijsdPer,
      @_OfrKostprijs,
      @_OfrPrijs,
      @_OfrStukskorting1Bedrag,
      @_OfrStukskorting1Percentage,
      @_OfrStukskorting2Percentage,
      @_OfrRegelkorting1Bedrag,
      @_OfrRegelkorting1Percentage,
      @_OfrRegelkorting2Percentage,
      @_OfrRegelPositie,
      @_OfrRegelsoort,
      @_OfrTekstOpOfferte,
      @_OfrVkeGid,
      @_OfrAantalVrrdEenhInVerkEenh,
      @_OfrEenheidPrijsPer,
      @_OfrAantalDecimalenVoorAantallenVrrdEenh,
      @_OfrAantalTeOffrerenVrrdEenh,
      @_OfrAantalVrrdEenhInVerkEenhMagAfwijken
    );
    set @_OfrGid = @@Identity;

  end; // atomic

  // resultaat terug geven
  select OfrRegelPositie as RegelNummer
  from tabOfferteRegel
  where OfrGid = @_OfrGid;
end;



