    @Decimalen,
    @Keuzelijst,
    @Defaultwaarde,
    @Sjabloon,
    @Groep,
    @DefaultDatum,
    @DefaultTijd,
    @OpVerkoopDocument
  );

  //call trace('Einde WebSvcProc_Offerte_Onderhoud_VrijeRubriek_ToevoegenWijzigen');
end;

