create or replace procedure WebSvcProc_Offerte_Toevoegen
( in @OfferteNummer numeric(10,0),
  in @RelatieBestand nchar(3) default null,
  in @RelatieNummer nchar(10) default null,
  in @DebiteurNummer nchar(10),
  in @GebruikDefaults smallint default 0,
  in @ContactPersoonNummer numeric(3,0),
  in @KeuzeVertegenwoordiger nchar(10),
  in @VertegenwoordigerNummer numeric(3,0),
  in @Referentie long nvarchar,
  in @DefaultBtwCode nchar(3),
  in @KostenplaatsNummer numeric(8,0),
  in @KostendragerNummer numeric(8,0),
  in @MarketingEventCode nchar(40),
  in @LeverDatum date,
  in @PeriodeDoorlooptijd nchar(7),
  in @Doorlooptijd smallint,
  in @BerekeningOfferteTotaal nchar(23),
  in @OfferteTotaal numeric(15,2) default null,
  in @Scoringskans numeric(15,2) default null,
  in @Opmerking long nvarchar,
  in @AanmaakDatum date,
  in @GeldigheidsDatum date,
  in @PrijzenInclusiefBtw smallint,
  in @ValutaCode nchar(3),
  in @BetalingsConditieNummer numeric(3,0),
  in @LeveringsConditieNummer numeric(3,0),
  in @IsInkoopcombinatie smallint,
  in @DebiteurNummerFactuur nchar(10),
  in @DebiteurNummerOmzet nchar(10),
  in @DebiteurnummerPrijsafspraken nchar(10),
  in @FactuurAdres nchar(10), //'VEST', 'COR'
  in @VerzendAdres nchar(10), //'VEST', 'COR', 'VERZ', 'FACT_VEST', 'FACT_COR', 'FACT_VERZ'
  in @VerzendAdresNummer numeric(3,0),
  in @EindAdres nchar(10), //'VEST', 'COR', 'VERZ', 'NVT'
  in @EindAdresNummer numeric(3,0),
  in @OrderKorting numeric(6,2),
  in @AparteFactuur  nchar(35), //'JA', 'NEE', 'PERCONTACTPERSOON', 'PERVERZENDADRES', 'PERCONTACTPERSOONENVERZENDADRES'
  in @AparteLevering nchar(4), //'JA', 'NEE'
  in @OpmerkingVersie long nvarchar,
  in @ReferentieVersie long nvarchar,
  in @ExtraTekstEmailbericht long nvarchar
)
result
( OfferteNummer numeric(10,0),
  OfferteVersieNummer smallint
)
begin
  declare @_VersieOfferteNummer numeric(10,0);
  declare @_VersieOfferteVersieNummer smallint;

  declare @_GebruikDefaults                 smallint;
  declare @_OffGid                          integer;
  declare @_OffOfferteNummer                numeric(10,0);
  declare @_OffFonGidRelatie                integer;
  declare @_OffNawGidRelatie                integer;
  declare @_OffNawGidDebiteur               integer;
  declare @_OffKstpGid                      integer;
  declare @_OffKstdGid                      integer;
  declare @_OffRelGidRelatie                integer;        // Dit is contactpersoon van relatie
  declare @_OffRelGidDebiteur               integer;        // Dit is contactpersoon van debiteur
  declare @_OffVtgCode                      integer;
  declare @_OffDoorlooptijdAantal           smallint;
  declare @_OffDoorlooptijdPeriode          smallint;
  declare @_OffLeverDatum                   date;
  declare @_OffScoringskans                 numeric(15,2);
  declare @_OffStatus                       smallint;
  declare @_OffMaevGid                      integer;
  declare @_OffBerekenMethodeOfferteTotaal  smallint;
  declare @_OffOfferteTotaal numeric(15,2);
  declare @_OffVerwachteScoringsDatum       date;
  declare @_OffBtwCode                      integer;
  declare @_OffOpmerking long nvarchar;
  declare @_OffReferentie long nvarchar;

  // constanten...
  declare _AANGEMAAKTDOOR nchar(10) = 'Webservice';
  declare _AANGEMAAKTOP timestamp = now();

  //call TraceBegin('WebSvcProc_Offerte_Toevoegen > @OfferteNummer = ' + string(@OfferteNummer) + ', @DebiteurNummer = ' + @DebiteurNummer);

  // ******************************
  // Defaults voor offerte
  // ******************************
  begin
    set @_GebruikDefaults = isnull(@GebruikDefaults,0);
    set @_OffBerekenMethodeOfferteTotaal = (select OfvgDefaultBerekenMethodeOfferteTotaal from tabOfferteVasteGegevens);
    set @_OffScoringskans = isNull(@Scoringskans, 50);
    set @_OffStatus = 0;                    // Openstaand
    set @_OffDoorlooptijdAantal = 1;
    set @_OffDoorlooptijdPeriode = 2;       // Maanden
    set @_OffVerwachteScoringsDatum = dateadd( month,@_OffDoorlooptijdAantal,getdate() );
    set @_OffBtwCode = null;                // geen BTW code, dan volgens artikel / tarief
    if isnull(@Opmerking,'') <> '' then set @_OffOpmerking = @Opmerking end if;
    if isnull(@Referentie,'') <> '' then set @_OffReferentie = @Referentie end if;

  end;

  // ******************************
  // controleer aangeboden gegevens
  // ******************************
  call WebSvcHulpProc_Offerte_Controleer_Offerte(
    @OfferteNummer,
    @RelatieBestand,
    @RelatieNummer,
    @DebiteurNummer,
    @_GebruikDefaults,
    @ContactPersoonNummer,
    @KeuzeVertegenwoordiger,
    @VertegenwoordigerNummer,
    @DefaultBtwCode,
    @KostenplaatsNummer,
    @KostendragerNummer,
    @MarketingEventCode,
    @LeverDatum,
    @PeriodeDoorlooptijd,
    @Doorlooptijd,
    @BerekeningOfferteTotaal,
    @OfferteTotaal,
    @_OffScoringskans,
    @_OffGid,
    @_OffOfferteNummer,
    @_OffFonGidRelatie,
    @_OffNawGidRelatie,
    @_OffNawGidDebiteur,
    @_OffKstpGid,
    @_OffKstdGid,
    @_OffRelGidRelatie,
    @_OffRelGidDebiteur,
    @_OffVtgCode,
    @_OffDoorlooptijdAantal,
    @_OffDoorlooptijdPeriode,
    @_OffLeverDatum,
    @_OffMaevGid,
    @_OffBerekenMethodeOfferteTotaal,
    @_OffOfferteTotaal,
    @_OffVerwachteScoringsDatum,
    @_OffBtwCode,
    @_OffScoringskans
  );

  // ******************************
  // Maak nu de offerte aan...
  // ******************************
  begin atomic // Dit moet, want offerteversie moet hierna nog en daar kan het nog fout gaan
    insert into tabOfferte (
      OffOfferteNummer,
      OffFonGidRelatie,
      OffKstpGid,
      OffKstdGid,
      OffNawGidRelatie,
      OffNawGidDebiteur,
      OffRelGidRelatie,
      OffRelGidDebiteur,
      OffVtgCode,
      OffDoorlooptijdAantal,
      OffDoorlooptijdPeriode,
      OffLeverDatum,
      OffScoringskans,
      OffStatus,
      OffMaevGid,
      OffBerekenMethodeOfferteTotaal,
      OffOfferteTotaal,
      OffVerwachteScoringsDatum,
      OffBtwCode,
      OffAangemaaktDatum,
      OffAangemaaktDoor,
      OffOpmerking,
      OffReferentie
    )
    values (
      @_OffOfferteNummer,
      @_OffFonGidRelatie,
      @_OffKstpGid,
      @_OffKstdGid,
      @_OffNawGidRelatie,
      @_OffNawGidDebiteur,
      @_OffRelGidRelatie,
      @_OffRelGidDebiteur,
      @_OffVtgCode,
      @_OffDoorlooptijdAantal,
      @_OffDoorlooptijdPeriode,
      @_OffLeverDatum,
      @_OffScoringskans,
      @_OffStatus,
      @_OffMaevGid,
      @_OffBerekenMethodeOfferteTotaal,
      @_OffOfferteTotaal,
      @_OffVerwachteScoringsDatum,
      @_OffBtwCode,
      _AANGEMAAKTOP,
      _AANGEMAAKTDOOR,
      @_OffOpmerking,
      @_OffReferentie
    );
    set @_OffGid = @@Identity;

    // Aangemaakte offerte locken
    begin
      declare @_LockResult integer;

      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOfferte', @_OffGid, @_LockResult, 0, 'KingWebService');
      if @_LockResult <> 0 then
        call Raise(20740,_U('Offerte')); // (20740) %1! is niet gelockt!
      end if;
    end;

    // **********************************************************************
    // We gaan nu een eerste offerteversie regelen.
    // **********************************************************************
    select OfferteNummer, VersieNummer
    into @_VersieOfferteNummer, @_VersieOfferteVersieNummer
    from WebSvcProc_Offerte_Versie_Toevoegen(
      @_OffOfferteNummer,
      @ReferentieVersie,
      @OpmerkingVersie,
      @AanmaakDatum,
      @GeldigheidsDatum,
      @PrijzenInclusiefBtw,
      @ValutaCode,
      @BetalingsConditieNummer,
      @LeveringsConditieNummer,
      @ExtraTekstEmailbericht,
      @OrderKorting,
      @IsInkoopcombinatie,
      @DebiteurNummerFactuur,
      @DebiteurNummerOmzet,
      @DebiteurNummerPrijsafspraken,
      @FactuurAdres,
      @VerzendAdres,
      @VerzendAdresNummer,
      @EindAdres,
      @EindAdresNummer,
      @AparteFactuur,
      @Apartelevering);

  end; // atomic

  // resultaat terug geven
  select  @_VersieOfferteNummer  as OfferteNummer,
          @_VersieOfferteVersieNummer as OfferteVersieNummer;

  //call TraceEind('WebSvcProc_Order_Toevoegen');
end; //atomic


create or replace procedure WebSvcProc_Offerte_Versie_Toevoegen(
  in @OfferteNummer numeric(10,0),
  in @Referentie long nvarchar,
  in @Opmerking long nvarchar,
  in @AanmaakDatum date,
  in @GeldigheidsDatum date,
  in @PrijzenInclusiefBtw smallint,
  in @ValutaCode nchar(3),
  in @BetalingsConditieNummer numeric(3,0),
  in @LeveringsConditieNummer numeric(3,0),
  in @ExtraTekstEmailbericht long nvarchar,
  in @OrderKorting numeric(6,2),
  in @IsInkoopCombinatie smallint,
  in @DebiteurNummerFactuur nchar(10),
  in @DebiteurNummerOmzet nchar(10),
  in @DebiteurNummerPrijsafspraken nchar(10),
  in @FactuurAdres nchar(4),
  in @VerzendAdres nchar(10),
  in @VerzendAdresNummer numeric(3,0),
  in @Eindadres nchar(40),
  in @EindAdresNummer numeric(3,0),
  in @AparteFactuur nchar(40),
  in @Apartelevering nchar(4))
result( OfferteNummer numeric(10,0), VersieNummer numeric(3,0) )

begin
  declare @_OfkGid integer;
  declare @_OfkOffGid integer;
  declare @_OfktaalGid integer;
  declare @_OfkAanmaakDatum date;
  declare @_OfkBtcNummer integer;
  declare @_OfkLvcNummer integer;
  declare @_OfkValNummer integer;
  declare @_OfkBtwStand smallint;
  declare @_OfkStatus smallint;
  declare @_OfkVersieNummer smallint;
  declare @_OfkGeldigheidsDatum date;
  declare @_OfkReferentie long nvarchar;
  declare @_OfkOpmerking long nvarchar;
  declare @_OfkOfferteNummer nchar(14);
  declare @_OfkOrderKorting numeric(6,2);
  declare @_OfkEmailExtraTekst long nvarchar;
  declare @_OfkApartFactureren smallint;
  declare @_OfkApartLeveren smallint;
  declare @_OfkIsInKoopCombinatie smallint;
  declare @_OfkNawGidInkCombiFactuur integer;
  declare @_OfkNawGidInkCombiOmzet integer;
  declare @_OfkNawGidInkCombiPrijzen integer;
  declare @_OfkFactuurAdres smallint;
  declare @_OfkVerzendAdres smallint;
  declare @_OfkEindAdres smallint;
  declare @_OfkAdrGidVerzendAdres integer;
  declare @_OfkAdrGidEindAdres integer;

  declare @_OffNawGid integer;
  declare @_OffFonGidRelatie integer;
  declare @_OffStatus smallint;

  // constanten...
  declare _AANGEMAAKTDOOR nchar(10) = 'Webservice';
  declare _AANGEMAAKTOP timestamp = now();
  declare _TOEVOEGEN smallint = 0;
  declare _qcJA smallint = 1;
  declare _qcNEE smallint = 0;

  //Is de optie Offertes geactiveerd?
  if IsModuleActive('o3') = _qcNEE then
    call Raise(20790, _U('Optie Offertes')) ; // <Optie/Module> niet geactiveerd!
  end if;

  // Heb ik een valide offerte, en zo ja wie is de Relatie of Debiteur?
  select OffGid, OffFonGidRelatie, isnull(OffNawGidRelatie, OffNawGidDebiteur), OffStatus
  into @_OfkOffGid, @_OffFonGidRelatie, @_OffNawGid, @_OffStatus
  from tabOfferte
  where OffOfferteNummer = @OfferteNummer;

  if @_OfkOffGid is null then
    call Raise(20720, _U('Offerte %1!', string(@OfferteNummer) )); // <Object> niet gevonden!
  end if;

  if (@_OffStatus = 1 /* Afgewezen */) then
    call Raise(20780, _U('Offerteversie toevoegen'), _U('Offertestatus is afgewezen.')); // <Actie> niet mogelijk: <Reden>
  end if;

  if exists(select first 1 from tabOfferteKop where OfkOffgid = @_OfkOffGid and OfkStatus = 3 /*geaccepteerd*/ ) then
    call Raise(20780, _U('Offerteversie toevoegen'), _U('Offerte is geaccepteerd.')); // <Actie> niet mogelijk: <Reden>
  end if;

  // **********************************
  // Valideer eerst de InkoopCombinatie
  // **********************************
  call WebSvcHulpProc_Offerteversie_ValideerInkoopcombinatie(
    // IN
    @Mode = _TOEVOEGEN,
    @NawGid = @_OffNawGid,
    @FonGidRelatie = @_OffFonGidRelatie,
    @DebiteurNummerFactuur = @DebiteurNummerFactuur,
    @DebiteurNummerOmzet = @DebiteurNummerOmzet,
    @DebiteurNummerPrijsafspraken = @DebiteurNummerPrijsafspraken,
    @IsInkoopCombinatie = @IsInkoopCombinatie,
    // OUT
    @_IsInKoopCombinatie = @_OfkIsInkoopCombinatie,
    @_NawGidInkCombiFactuur = @_OfkNawGidInkCombiFactuur,
    @_NawGidInkCombiOmzet = @_OfkNawGidInkCombiOmzet,
    @_NawGidInkCombiPrijzen = @_OfkNawGidInkCombiPrijzen);

  // *****************************************************
  // Defaults voor offerteversie, hou hierbij rekening met
  // hiervoor gevalideerde gegevens voor inkoopcombinatie
  // *****************************************************
  begin
    set @_OfkStatus = 0; //Concept

    set @_OfkTaalGid = isnull( (select NawTaalGid from tabNaw where NawGid = @_OffNawGid),
                               (select NawTaalGid from tabNaw where NawGid = (select NawFilNawGid from tabNawFile where NawFilFonId = 'B') )
                             );

    // Defaults uit vaste gegevens offertes
    // Ook voor o.a. berekenen datums, tenzij ze expliciet zijn opgegeven.
    set @_OfkAanmaakDatum = isNull(@AanmaakDatum, date(now()));

    if @GeldigheidsDatum is not null then
      if @GeldigheidsDatum < @_OfkAanmaakDatum then
        call Raise(20700, _U('%1!, deze ligt voor de aanmaakdatum.', 'GeldigheidsDatum')); //Ongeldige waarde: <parameter of opmerking>
      end if;

      set @_OfkGeldigheidsDatum = @GeldigheidsDatum;
    end if;

    select  isnull(@_OfkGeldigheidsDatum, DateAdd(day, OfvgDefaultAantalDagenGeldig, @_OfkAanmaakDatum )),
            OfvgDefaultReferentie,
            case OfvgDefaultBtwstandOffertesVoorRelaties
              when 0 /*vlgns deb*/ then (select FonfactuurBTW from tabFileOfNaw where FonId = 'D')
              when 1 /*incl BTW*/  then 1
              when 2 /*excl BTW*/  then 0
            end case
    into @_OfkGeldigheidsDatum, @_OfkReferentie, @_OfkBtwStand
    from tabOfferteVasteGegevens;
  end; // defaults offerteversie

  // *************************************
  // Controle vaste gegevens offerteversie
  // *************************************
  call WebSvcHulpProc_Offerteversie_ControleerVastegegevens(
    //IN
    @Mode = _TOEVOEGEN,
    @OffFonGidRelatie = @_OffFonGidRelatie,
    @OffNawGid = @_OffNawGid,
    @IsInkoopCombinatie = @_OfkIsInkoopCombinatie,
    @NawGidInkCombiFactuur = @_OfkNawGidInkCombiFactuur,
    @Referentie = @Referentie,
    @Opmerking = @Opmerking,
    @PrijzenInclusiefBtw = @PrijzenInclusiefBtw,
    @ValutaCode = @ValutaCode,
    @BetalingsConditieNummer  = @BetalingsConditieNummer,
    @LeveringsConditieNummer = @LeveringsConditieNummer,
    @ExtraTekstEmailbericht = @ExtraTekstEmailbericht,
    @OrderKorting = @OrderKorting,
    @FactuurAdres = @FactuurAdres,
    @VerzendAdres = @VerzendAdres,
    @VerzendAdresNummer = @VerzendAdresNummer,
    @Eindadres = @Eindadres,
    @EindAdresNummer = @EindAdresNummer,
    @AparteFactuur = @AparteFactuur,
    @Apartelevering = @Apartelevering,
    //INOUT
    @_Referentie = @_OfkReferentie,
    @_Opmerking = @_OfkOpmerking,
    @_PrijzenInclusiefBtw = @_OfkBtwStand,
    @_ValutaNummer = @_OfkValNummer,
    @_BtcNummer = @_OfkBtcNummer,
    @_LvcNummer = @_OfkLvcNummer,
    @_ExtraTekstEmailbericht = @_OfkEmailExtraTekst,
    @_OrderKorting = @_OfkOrderKorting,
    @_FactuurAdres = @_OfkFactuurAdres,
    @_VerzendAdres = @_OfkVerzendAdres,
    @_AdrGidVerzendAdres = @_OfkAdrGidVerzendAdres,
    @_EindAdres = @_OfkEindAdres,
    @_AdrGidEindAdres = @_OfkAdrGidEindAdres,
    @_AparteFactuur = @_OfkApartFactureren,
    @_Apartelevering = @_OfkApartLeveren);

  // ******************************
  // maak nu de offerteversie aan.
  // ******************************
  begin atomic

    // eerst de offerte locken voordat je versie gaat toevoegen
    call WebSvcHulpProc_Offerte_ExclusiefLocken(@_OfkOffGid);

    set @_OfkVersieNummer = isnull((select max(OfkVersieNummer) from tabOfferteKop where OfkOffGid = @_OfkOffGid) + 1, 1 );

    if @_OfkVersieNummer >= 999 then
      call Raise(20780, _U('Offerteversie toevoegen'), _U('maximum aantal versies bereikt.')); // <Actie> niet mogelijk: <Reden>
    end if;

    set @_OfkOfferteNummer = string(@OfferteNummer, '.', @_OfkVersieNummer); // v.b. '1234567890.999'

    insert into tabOfferteKop (
      OfkOffGid, OfkVersieNummer, OfkOfferteNummer, OfktaalGid,
      OfkIsInkoopCombinatie, OfkNawGidInkCombiFactuur, OfkNawGidInkCombiOmzet, OfkNawGidInkCombiPrijzen,
      OfkFactuurAdres, OfkVerzendAdres, OfkAdrGidVerzendAdres, OfkEindAdres, OfkAdrGidEindAdres,
      OfkOrderKorting, OfkAanmaakDatum, OfkGeldigheidsDatum, OfkBtwStand, OfkValNummer,
      OfkApartFactureren, OfkApartLeveren, OfkBtcNummer, OfkLvcNummer,
      OfkReferentie, OfkEmailExtraTekst, OfkStatus, OfkOpmerking)
    values (
      @_OfkOffGid, @_OfkVersieNummer, @_OfkOfferteNummer, @_OfktaalGid,
      @_OfkIsInkoopCombinatie, @_OfkNawGidInkCombiFactuur, @_OfkNawGidInkCombiOmzet, @_OfkNawGidInkCombiPrijzen,
      @_OfkFactuurAdres, @_OfkVerzendAdres, @_OfkAdrGidVerzendAdres, @_OfkEindAdres, @_OfkAdrGidEindAdres,
      @_OfkOrderKorting, @_OfkAanmaakDatum, @_OfkGeldigheidsDatum, @_OfkBtwStand, @_OfkValNummer,
      @_OfkApartFactureren, @_OfkApartLeveren, @_OfkBtcNummer, @_OfkLvcNummer,
      @_OfkReferentie, @_OfkEmailExtraTekst, @_OfkStatus, @_OfkOpmerking);

    set @_OfkGid = @@Identity;

    // *********************************
    // Statuslog offerteversie aanvullen
    // *********************************
    insert into tabOfferteversieStatuslog(OfvsOfkGid, OfvsGebruikerCode,  OfvsStatus,   OfvsTijdstip,   OfvsToelichting)
                                  values (@_OfkGid,   _AANGEMAAKTDOOR,    @_OfkStatus,  _AANGEMAAKTOP,  _A('Nieuwe versie aangemaakt.'));
  end; // atomic

  // ***********************
  // Resultaat terugkoppelen
  // ***********************
  select @OfferteNummer, OfkVersieNummer from tabOfferteKop where OfkGid = @_OfkGid;
end;


create or replace procedure WebSvcProc_Offerte_VrijeRubriek_Wijzigen(
  in @OfferteNummer numeric(10,0),
  in @VersieNummer numeric(10,0),
  in @RubriekOmschrijving nchar(40),
  in @RubriekInhoud nchar(255)
)
begin
  declare @_OfkGid integer;
  declare @_OffGid integer;

  //call TraceBegin('WebSvcProc_Offerte_VrijeRubriek_Wijzigen > @OfferteNummer = ' + String(@OfferteNummer) + ', @Versienummer = ' + String(@VersieNummer) + ' @RubriekOmschrijving = ' + String(@RubriekOmschrijving));

  if IsModuleActive('on') = 0 then
    call Raise(20790, _U('Optie Offertes')); //(20790) '%1!' niet geactiveerd!
  end if;

  set @_OffGid = (select OffGid from tabOfferte where OffOfferteNummer = @OfferteNummer);

  if @_OffGid is null then
    call Raise(20720, 'OfferteNummer'); //(20720 %1 niet gevonden!
  end if;

  set @_OfkGid = (select OfkGid from tabOfferteKop where OfkOffGid = @_OffGid and OfkVersieNummer = @VersieNummer );
  if (@_OfkGid is null) then
    call Raise(20720, 'VersieNummer'); //(20720 %1 niet gevonden!
  end if;

  begin atomic
    // Offerte locken als dat nog niet het geval is.
    call WebSvcHulpProc_Offerte_ExclusiefLocken(@_OffGid);

    call VrInsertOrReplaceValue('OFK', 0, 0, @_OfkGid, @RubriekOmschrijving, @RubriekInhoud);
  end; // atomic

  //call TraceEind('WebSvcProc_Offerte_VrijeRubriek_Wijzigen');
end;


create or replace procedure WebSvcHulpProc_Order_BepaalStandaardLocatieVanArtikelPartij(
  in  @LocatieCode    nchar(20) ,     // bij specificatieregels kan dit opgegeven worden, dan controleren
  in  @ArtGid         integer   ,
  in  @ArtPartijGid   integer   ,
  in  @MagGid         integer   ,
  out @LocGid         integer   )
begin
  // RtK, 26-04-2019: Er wordt niet naar vaste gegevens orders/facturering gekeken.
  // De King GUI vult altijd vooraf de standaardlocatie voor artikel in, ongeacht wat er bij vaste gegevens staat (in King 5.59).
  // bij 'leeg' wordt de gebruiker niet gedwongen om locatie op te geven. Dus vullen we altijd een (standaard) locatie van artikel in.
  declare @_TempGid integer;
  set @locGid = null;

  if isnull(@LocatieCode,'') <> '' then
    select LocGid into @LocGid from tabLocatie where LocNaam = @LocatieCode and LocMagGid = @MagGid;
    if (@LocGid is null) then
      call Raise(20700, _U('Locatie ''%1!'' is in magazijn niet bekend!', @LocatieCode)); //Ongeldige of geen LocatieCode meegegeven!
    end if;
  end if;

  // Nog geen locatie? Kijk even of er van partij een locatie is
  // zijn er meerdere locaties, neem dan eerst de default indien mogelijk.
  if ( @locGid is null ) and ( @ArtPartijGid is not null ) then
    select first
            case  ArtlocLocGid
              when  ArtMagDefaultLocGid then ArtMagDefaultLocGid
              else  null
            end case as TempGid,
            ArtlocLocGid
      into  @_TempGid,
            @LocGid
    from tabArtikelLocatie
      inner join tabLocatie on LocGid = ArtLocLocGid
      inner join tabArtikelMagazijn on ArtMagGid = ArtLocArtMagGid
    where ( ArtlocArtGid = @ArtGid )
      and ( ArtlocPartijGid = @ArtPartijGid )
      and ( ArtMagMagGid = @MagGid )
    order by 1 desc, locNaam // default locatie eerst, daarna locatienaam op alfabetische volgorde
  end if;

  // Laatste mogelijkheid: uiteindelijk moet je wel de standaardlocatie van artikel hebben.
  // we gebruiken hiervoor de stored proc van King 5
  if (@LocGid is null) then
    call CreateStandaardLocatieVoorArtikelMagazijn(
      @ArtGid,  // in
      @MagGid,  // in
      @LocGid   // out
    );
  end if;
end;

begin // test
  /*
  declare  @_LocatieCode    nchar(20);
  declare  @_ArtGid         integer;
  declare  @_ArtPartijGid   integer;
  declare  @_MagGid         integer;
  declare  @_LocGid         integer;

  set @_LocatieCode = '';
  set @_ArtGid = (select ArtGid from tabArtikel where artCode = 'BLUERAYSPELER');
  set @_ArtPartijGid = (select ArtPartijGid from tabArtikelPArtij where ArtPartijArtGid = @_ArtGid and ArtPartijNummer = '' );
  set @_MagGid = (select MagGid from tabMagazijn where MagCode = '001');

  call WebSvcHulpProc_Order_BepaalStandaardLocatieVanArtikelPartij(
    @_LocatieCode,
    @_ArtGid,
    @_ArtPartijGid,
    @_MagGid,
    @_LocGid );

  select LocNaam from tabLocatie where LocGid = @_LocGid;
  */
end;


create or replace procedure WebSvcHulpProc_Order_ControleerDirecteInkoop(
  in  @ArtGid                 integer,
  in  @DirecteInkoop          smallint,
  in  @OmschrijvingOvernemen  smallint,
  in  @Leverancier            nchar(10),
  in  @InkoopEenheid          nchar(20),
  in  @DirecteLevering        nchar(40),
  out @_DirecteInkoop         smallint,
  out @_OmschrijvingOvernemen smallint,
  out @_NawGidDirecteInkoop   integer,
  out @_InkoopEenheid         nchar(20),
  out @_DirecteLevering       smallint
)
begin

  // Initialiseren: alvast default settings van artikel ophalen.
  select  ArtBestellenViaDirecteInkoop,
          ArtOmsVerkooporderOvernemen,
          ArtBestellenVoorDirecteLevering,
          null,                             // default leverancier
          null                              // met dito default eenheid
    into  @_DirecteInkoop,
          @_OmschrijvingOvernemen,
          @_DirecteLevering,
          @_NawGidDirecteInkoop,
          @_InkoopEenheid
  from tabArtikel
  where ArtGid = @ArtGid;

  // defaults opruimen als optie niet geactiveerd is.
  if IsModuleActive('dl') = 0 then
    set @_DirecteInkoop         = null;
    set @_OmschrijvingOvernemen = null;
    set @_DirecteLevering       = null;
  end if;

  // ******************************
  // Controle vinkjes directe inkoop
  // ******************************
  // Als directe inkoop expliciet wordt ingesteld, dan ...
  // moet de module wel actief zijn. Is dat het geval, ...
  // dan pas gaan we andere parameters verwerken.
  if (@DirecteInkoop is not null) then
    // Er wordt expliciet een waarde gezet, maar is de module wel geactiveerd?
    if IsModuleActive('dl') = 0 then
      call Raise(20790, _U('Optie Directe inkoop'));  // (20790) %1 niet geactiveerd!
    end if;

    if @DirecteInkoop not in (0,1) then
      call Raise(20700, 'DirecteInkoop') ;                                        // (20700) Ongeldige waarde: %1
    end if;
    set @_DirecteInkoop = @DirecteInkoop ;

    if (@OmschrijvingOvernemen is not null) then
      if @OmschrijvingOvernemen not in (0,1) then
        call Raise(20700, 'OmschrijvingOvernemen') ;                              // (20700) Ongeldige waarde: %1
      end if;

      // combinatie die niet toegestaan is
      if ( @OmschrijvingOvernemen = 1 ) and (@_DirecteInkoop = 0) then
        call Raise(20701, _U('%1! en %2!', 'OmschrijvingOvernemen = 1', 'DirecteInkoop = 0')) ;     // (20701) Ongeldige Combinatie: %1
      end if;

      set @_OmschrijvingOvernemen = @OmschrijvingOvernemen ;

    end if;

    if ( isnull(@DirecteLevering,'') <> '' ) then
      case @DirecteLevering
        when 'NEE'                  then set @_DirecteLevering = 0
        when 'JA'                   then set @_DirecteLevering = 1
        when 'VOLGENS LEV./EENHEID' then set @_DirecteLevering = 2
        else call Raise(20700, 'DirecteLevering') ;                               // (20700) Ongeldige waarde: %1
      end case ;
    end if;

    // ******************************
    // Controle leverancier
    // ******************************
    // vraag alvast default leverancier op.
    // Opmerking: NawGid mag leeg gelaten worden in de King GUI, maar dan mag je weer geen inkoopeenheid opgeven.
    // Dus toch maar expliciet de default leverancier in, dat scheelt wel bij checks op inkoopeenheid.
    set @_NawGidDirecteInkoop = ( select ArtlevNawGid
                                  from  tabArtikelLeverancier
                                  where ( ArtLevArtGid = @ArtGid )
                                    and ( ArtLevIsDefault = 1 )
                                );

    // Er is een leverancier aangewezen, bestaat die...
    if (@Leverancier is not null) then
      set @_NawGidDirecteInkoop = ( select NawFilNawGid
                                    from tabNawFile
                                    where NawFilNummer = @Leverancier
                                      and NawfilFonGid = (  select FonGid from tabFileOfNaw where FonId = 'C' )
                                  );

      if ( @_NawGidDirecteInkoop is null ) then
       call Raise(20700, _U('Leverancier ''%1!'' is onbekend!', @Leverancier));     // (20700) Ongeldige waarde: %1
      end if;
    end if;

    // ******************************
    // Controle inkoopeenheid
    // ******************************
    // De leverancier is uiteindelijk bekend.
    // Ga checken of een eventueel opgegeven inkoopeenheid bij die leverancier bestaat.
    set @_InkoopEenheid = ( select AldInkoopEenheid
                            from tabArtikelLeverancierDetail
                              inner join tabArtikelLeverancier on ArtLevGid = AldArtLevGid and ArtLevArtGid = @ArtGid
                            where ( ArtLevNawGid = @_NawGidDirecteInkoop )
                              and ( ( ( isnull(@InkoopEenheid,'') = '') and (AldIsDefaultInkoopEenheidBijLev = 1 ) ) // niet opgegeven, dan default inkoopeenheid
                                    or ( AldInkoopEenheid = @InkoopEenheid )                                         // wel opgegeven, dan moet die bestaan
                                  )
                          );

    // de opgegeven verkoopeenheid bestaat niet bij de leverancier
    // dan kijken of het als verkoopeenheid bestaat. Voorraadeenheid is ook een verkoopeenheid...
    if ( @_InkoopEenheid is null ) then
      set @_InkoopEenheid = ( select VkeVerkoopEenheid
                              from tabVerkoopEenheid
                              where VkeVerkoopEenheid = @InkoopEenheid
                                and VkeArtgid = @ArtGid
                            );

      if (@_InkoopEenheid is null) and ( isnull(@InkoopEenheid,'') <> '' ) then
        call Raise(20700, _U('Inkoopeenheid moet hetzij bij leverancier bekend zijn, of een verkoopeenheid zijn.')) ; // (20700) Ongeldige waarde: %1
      end if;
    end if;

  end if; // @DirecteInkoop is not null

end;

begin // testquery
  /*
  declare @DirecteInkoop            smallint = null;
  declare @OmschrijvingOvernemen    smallint = 1;
  declare @Leverancier              nchar(10) = '17380011';
  declare @InkoopEenheid            nchar(20) = 'ICH';
  declare @DirecteLevering          nchar(40) = 'ONMOGELIJK'; // keuzelijst: 'JA', 'NEE', of 'VOLGENS LEV./EENHEID'
  declare @_DirecteInkoop           smallint;
  declare @_OmschrijvingOvernemen   smallint;
  declare @_NawGidDirecteInkoop     integer;
  declare @_InkoopEenheid           nchar(20);
  declare @_Directelevering         smallint; // 0 = nee, 1 = ja, 2 = volgens lev./eenheid

  call WebSvcHulpProc_Order_ControleerDirecteInkoop(
    //in
    (select ArtGid from tabArtikel where artCode = 'BLUERAYSPELER'), // @ArtGid
    @DirecteInkoop,
    @OmschrijvingOvernemen,
    @Leverancier,
    @InkoopEenheid,
    @DirecteLevering,
    // out
    @_DirecteInkoop,
    @_OmschrijvingOvernemen,
    @_NawGidDirecteInkoop,
    @_InkoopEenheid,
    @_Directelevering
  );

  select  @_DirecteInkoop,
          @_OmschrijvingOvernemen,
          @_NawGidDirecteInkoop,
          @_InkoopEenheid,
          @_Directelevering
  from dummy;
  */
end;

create or replace procedure WebSvcHulpProc_Order_OrderRegel_ToevoegenTussenvoegen(
  //Ontime Defect #56894 - optional VAT code, optional warehouse code
  in @OrderNummer numeric(10,0),
  in @OrderRegelNummer numeric(10,0) default null,
  in @Actie smallint default 0,   //0 = Toevoegen, 1 = Tussenvoegen (met opschuiven)
  in @ExternOrderregelID nchar(20),
  in @RegelSoort nchar(5),
  in @ArtikelNummer nchar(20),
  in @KostenplaatsCode nchar(8),
  in @KostendragerCode nchar(8),
  in @TekstOpFactuur long nvarchar default null,
  in @AantalBesteld numeric(15,3),
  in @AantalDezeLevering numeric(15,3),
  in @AantalDezeFacturering numeric(15,3),
  in @BrutoVerkoopprijs numeric(15,3),
  in @Korting1 numeric(15,3),
  in @Korting2 numeric(15,2),
  in @LeverDatum date,
  in @EdiBuffer long nvarchar,
  in @BtwCode numeric(3,0),
  in @MagazijnCode numeric(3,0),
  in @Korting1IsPercentage smallint,
  in @PartijNummer nchar(20),
  in @VerkoopEenheid nchar(20) default '',
  in @EenheidPrijsPer nchar(20) default 'VOORRAADEENHEDEN',
  in @AantalVoorraadEenhedenInVerkoopEenheid numeric(15,3) default 1,
  in @AantalDezeLeveringVrrdEenh numeric(15,3) default null,
  in @AantalDezeFactureringVrrdEenh numeric(15,3) default null,
  in @DirecteInkoop smallint default null,
  in @OmschrijvingOvernemen smallint default null,
  in @Leverancier nchar(10) default null,
  in @InkoopEenheid nchar(20) default null,
  in @DirecteLevering nchar(40) default null,
  in @CBSLandOorsprong nchar(3) default null,
  in @CbsDouaneRegeling nchar(4) default null,
  in @CbsTransactiecode nchar(2) default null,
  in @Kostprijs numeric(15,3) default null,
  in @Productie smallint default null
)
result(RegelNummer smallint)
begin
  /*Constanten*/
  declare _qcJa smallint = 1;
  declare _qcNee smallint = 0;

  declare _ACTIE_TOEVOEGEN smallint = 0;
  declare _ACTIE_TUSSENVOEGEN smallint = 1;

  /*Variabelen*/
  declare @_OrkGid integer;
  declare @_OrkGoedgekeurd smallint;
  declare @_OrkNawGid integer;
  declare @_OrkFactuurNawGid integer;
  declare @_OrkIsInclBtw smallint;
  declare @_OrkValNummer integer;
  declare @_OrkCbsMeenemenInAangifte smallint;
  declare @_ArtGid integer;
  declare @_ArtOpbrGrpGid integer;
  declare @_OrrBtwCode integer;
  declare @_OrrGid integer;
  declare @_ArtPartijGid integer;
  declare @_ArtPartijKostprijsEx numeric(15,3) default null;
  declare @_ArtKostprijsEx numeric(15,3);
  declare @_ArtPrijsPer numeric(15,3); // ACW n.a.v. incident I11444: Deze werd niet opgehaald en dus niet in de orderregel gezet
  declare @_ArtAantDecAantallen smallint;
  declare @_ArtAantDecPrijzen smallint;
  declare @_ArtAantallen smallint;
  declare @_ArtHeeftVoorraad smallint;
  declare @_ArtDefaultMagGid integer;
  declare @_OrrMagGid integer;
  declare @_OrrRegelsoort smallint;
  declare @_Lockresult smallint;
  declare @_KstpGid integer;
  declare @_KstdGid integer;
  declare @_VkeGid integer;
  declare @_AantalBesteldVrrdEenh numeric(15,3) default 0;
  declare @_VkeAantalKanVerschillen integer;
  declare @_VkeAantalVoorraadEenhedenInVerkoopEenheid numeric(15,3);
  declare @_VkeVerkoopPrijsPer smallint;
  declare @_VkeAantalDecimalen smallint; /* 0,1,2,3 = aantal decimalen, 4 = Volgens voorraadeenheid */
  declare @_VkeIsVoorraadeenheid smallint;
  declare @_VkeIsGeblokkeerdVoorVerkoop smallint;
  declare @_ArtIsPartijNrBijLeverenVerplicht smallint;
  declare @_ArtIsKostprijsWijzigenInOrder smallint;
  declare @_ArtIsPartijAparteKostPrijs smallint;
  declare @_DirecteInkoop smallint;
  declare @_DirecteProductie smallint;
  declare @_OmschrijvingOvernemen smallint;
  declare @_NawGidDirecteInkoop integer;
  declare @_InkoopEenheid nchar(20);
  declare @_Directelevering smallint; /* 0 = nee, 1 = ja, 2 = volgens lev./eenheid */
  declare @_Reservering smallint; /* 0 = Geen, 1 = Levering, 2 = Levering + Backorder */
  declare @_VofVoorraadReserveren smallint; /* 0 = Geen, 1 = Levering, 2 = Levering + Backorder */
  declare @_VofRegelDefLocatie smallint; /* 0 = Leeg, 1 = Standaard locatie */
  declare @_vofRegelDefNuLeveren smallint; //0=Leeg, 1=Aantal Besteld, 2=Aantal in voorraad (Vrije voorraad), 3=aantal in voorraad(beschikbaar)
  declare @_vofRegelDefNuLeverenDirInkoop smallint; //0=Leeg, 2=Aantal in voorraad (Vrije voorraad), 3=aantal in voorraad(beschikbaar)
  declare @_vofRegelDefNuLeverenDirProductie smallint; //0=Leeg, 2=Aantal in voorraad (Vrije voorraad), 3=aantal in voorraad(beschikbaar)
  declare @_vofRegelDefNuFactureren smallint; //0=Leeg, 1=Aantal besteld, 2=Aantal deze levering
  declare @_vofRegelKstpVerplicht smallint;
  declare @_vofRegelKstdVerplicht smallint;
  declare @_vofRegelInvPartij smallint;
  declare @_vofRegelDefPartijAlsNietVerplicht smallint;
  declare @_CbsLndGidOorsprong integer;
  declare @_CbsDouaneRegeling nchar(4);
  declare @_CbsTrGid integer;
  declare @_CbsUitvoer smallint;
  declare @_CbsExtraHandel smallint;
  declare @_Voorraad numeric(15,3);
  declare @_OrrKostprijs numeric(15,3);
  declare @_OrrRcptGid integer;
  declare @_AantalRecepten integer;
  declare @_AantalBackorder numeric(15,3);
  declare @_AantalBackorderVrrdEenh numeric(15,3);
  declare @_ArtIsPartijRegistreren smallint;
  declare @_ArtIsPartijVerkoopCheckOuderePartijOp smallint;
  declare @_ArtPartijVerkoopCheckOuderePartij smallint;

  //call TraceBegin('WebSvcHulpProc_Order_OrderRegel_ToevoegenTussenvoegen > ' + '@OrderNummer = ' + string(@OrderNummer) + ', @RegelSoort = ' + string(@RegelSoort) +', @ArtikelNummer = ' + @ArtikelNummer);

  //Controle actie

  if isNull(@Actie, _ACTIE_TOEVOEGEN) not in (_ACTIE_TOEVOEGEN, _ACTIE_TUSSENVOEGEN) then
    call Raise(20700, _U('%1!, waarde: 0 en 1 toegestaan', 'Actie')); // Ongeldige waarde: %1
  end if;

  if IsModuleActive('wo') = _qcNee then
    call Raise(20900);  //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  select vofFactVoorraadReserveren, VofRegelDefLocatie, vofRegelDefNuLeveren, vofRegelDefNuLeverenDirInkoop, vofRegelDefNuLeverenDirProductie, vofRegelDefNuFactureren, vofRegelKstpVerplicht, vofRegelKstdVerplicht, vofRegelInvPartij, vofRegelDefPartijAlsNietVerplicht
  into @_VofVoorraadReserveren, @_VofRegelDefLocatie, @_vofRegelDefNuLeveren, @_vofRegelDefNuLeverenDirInkoop, @_vofRegelDefNuLeverenDirProductie, @_vofRegelDefNuFactureren, @_vofRegelKstpVerplicht, @_vofRegelKstdVerplicht, @_vofRegelInvPartij, @_vofRegelDefPartijAlsNietVerplicht
  from tabVasteGegevensOrdersFactureren;

  // OptieNummer 67 Dossierfacturering
  if IsModuleActive('k2') <> _qcNee then
    if isnull(@KostenplaatsCode, '') <> '' then
      select KstpGid into @_KstpGid from tabKostenplaats where KstpCode = @KostenplaatsCode;
      if @_KstpGid is null then
        call Raise(20700, 'KostenplaatsCode'); // (20700) Ongeldige waarde: %1!
      end if;
    else
      if @_vofRegelKstpVerplicht = _qcJa then
        call Raise(20700 , _U('%1! is verplicht.', 'KostenplaatsCode')) ; // Ongeldige waarde: %1!
      end if;
    end if;

    if isnull(@KostendragerCode, '') <> '' then
      select KstdGid into @_KstdGid from tabKostendrager where KstdCode = @KostendragerCode;
      if @_KstdGid is null then
        call Raise(20700, 'KostendragerCode'); // (20700) Ongeldige waarde: %1!
      end if;
    else
      if @_vofRegelKstdVerplicht = _qcJa then
        call Raise(20700 , _U('%1! is verplicht.', 'KostendragerCode')) ; // Ongeldige waarde: %1!
      end if;
    end if;
  end if;

  select OrkGid, OrkGoedgekeurd,    OrkNawGid,    OrkInclBtw,     OrkValNummer,   isnull( OrkFactuurNawGid, OrkNawGid ),  OrkDefaultMagGid, OrkCbsMeenemenInAangifte
  into @_OrkGid, @_OrkGoedgekeurd,  @_OrkNawGid,  @_OrkIsInclBtw, @_OrkValNummer, @_OrkFactuurNawGid,                     @_OrrMagGid,     @_OrkCbsMeenemenInAangifte
  from tabOrderkop
  where OrkSoort = 0
    and OrkNummer = @OrderNummer;

  if (@_OrkGid is null) then
    call Raise(20700, _U('%1! %2! onbekend', 'OrderNummer', @OrderNummer));  // (20700) Ongeldige waarde: %1!
  end if;

  case @RegelSoort
    when 'TEKST' then set @_OrrRegelsoort = 0;
    when 'TAR'   then set @_OrrRegelsoort = 1;
    when 'ART'   then set @_OrrRegelsoort = 2;
    else call Raise(20700, 'RegelSoort'); // (20700) Ongeldige waarde: %1!
  end case;

  if (IsNull(@ArtikelNummer, '') <> '') or (@_OrrRegelsoort in (1,2)) then
    select  ArtGid, ArtOpbrGrpGid, ArtKostprijsEx, ArtPrijsPer, ArtAantDecAantallen, ArtHeeftVoorraad,
            ArtAantDecPrijzen, ArtAantallen, VkeGid, VkeVerkoopPrijsPer, VkeAantalVoorraadEenhedenInVerkoopEenheid,
            VkeAantalKanVerschillen, if VkeAantalDecimalen = 4 then ArtAantDecAantallen else VkeAantalDecimalen end if,
            VkeIsVoorraadeenheid, VkeIsGeblokkeerdVoorVerkoop, ArtIsPartijNrBijLeverenVerplicht,
            ArtIsKostprijsWijzigenInOrder, ArtIsPartijAparteKostPrijs,
            ArtIsPartijRegistreren, ArtPartijVerkoopCheckOuderePartij, ArtIsPartijVerkoopCheckOuderePartijOp, ArtDefaultMagGid

    into    @_ArtGid, @_ArtOpbrGrpGid, @_ArtKostprijsEx, @_ArtPrijsPer, @_ArtAantDecAantallen, @_ArtHeeftVoorraad,
            @_ArtAantDecPrijzen, @_ArtAantallen, @_VkeGid, @_VkeVerkoopPrijsPer, @_VkeAantalVoorraadEenhedenInVerkoopEenheid,
            @_VkeAantalKanVerschillen, @_VkeAantalDecimalen,
            @_VkeIsVoorraadeenheid, @_VkeIsGeblokkeerdVoorVerkoop, @_ArtIsPartijNrBijLeverenVerplicht,
            @_ArtIsKostprijsWijzigenInOrder, @_ArtIsPartijAparteKostPrijs,
            @_ArtIsPartijRegistreren, @_ArtPartijVerkoopCheckOuderePartij, @_ArtIsPartijVerkoopCheckOuderePartijOp, @_ArtDefaultMagGid
    from   tabArtikel
           left outer join tabVerkoopeenheid on VkeArtGid=ArtGid and
                                                ((VkeVerkoopEenheid = @Verkoopeenheid) or ((IsNull(@Verkoopeenheid,'') = '') and VkeIsVoorraadeenheid=1))
    where ArtSoort = @_OrrRegelsoort and
          Artcode = @ArtikelNummer ;
    if (@_ArtGid is null) then
        call Raise(20700, 'ArtikelNummer'); // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  if @_VkeGid is null then //=> bij tekst/tariefregels
    if (@_OrrRegelsoort = 2) then
      call Raise(20700,_U('Er is geen verkoopeenheid of voorraadeenheid ''%1!'' gevonden voor dit artikel', @Verkoopeenheid)); // (20700) Ongeldige waarde: %1!
    end if;

    set @_VkeAantalKanVerschillen                   = 0;
    set @_VkeAantalVoorraadEenhedenInVerkoopEenheid = 1;
    set @_VkeVerkoopPrijsPer                        = 1;
    set @_VkeAantalDecimalen                        = IsNull(@_ArtAantDecAantallen, 0);
  else
    if @EenheidPrijsPer = '' then set @EenheidPrijsPer = 'VOORRAADEENHEDEN' end if;
    case isNull(@EenheidPrijsPer,'VOORRAADEENHEDEN')
      when 'VERKOOPEENHEID'   then set @_VkeVerkoopPrijsPer = 0;
      when 'VOORRAADEENHEDEN' then set @_VkeVerkoopPrijsPer = 1;
      else call Raise(20700,_U('%1! moet ''%2!'' of ''%3!'' zijn', 'EenheidPrijsPer', 'VERKOOPEENHEID', 'VOORRAADEENHEDEN'));  // (20700) Ongeldige waarde: %1!
    end case
  end if;

  if @_VkeIsGeblokkeerdVoorVerkoop = _qcJa then
    call Raise(20760,_U('De verkoopeenheid is geblokkeerd voor verkoop')); // (20760) Ongeldige status: %1!
  end if;

  // Warehouse code
  if @_OrrRegelsoort = 2 then

    // Defect #56894 - ACW/RtK/MG - Same logic als manual input and xml import in KING ERP 5.69a
    set @_OrrMagGid = isnull( @_ArtDefaultMagGid, @_OrrMagGid );

    if @MagazijnCode is not null then
      set @_OrrMagGid = ( select MagGid from tabMagazijn where MagCode = @MagazijnCode );
      if (@_OrrMagGid is null) then
        call Raise(20700, 'MagazijnCode'); // (20700) Ongeldige waarde: %1!
      end if;
    end if;
  end if;

  //In bepaalde gevallen mogen velden niet afwijken van elkaar. Reken de verkoopeenheden om naar voorraadeenheden.
  if @_VkeIsVoorraadeenheid = _qcJa then    /*De voorraadeenheid. Dus alles gelijkstellen aan elkaar.*/
    set @_AantalBesteldVrrdEenh        = @AantalBesteld;
    set @AantalDezeLeveringVrrdEenh    = @AantalDezeLevering;
    set @AantalDezeFactureringVrrdEenh = @AantalDezeFacturering;
  else
  begin
    if @_VkeAantalKanVerschillen = 2   /*Afwijkend aantal bij Levering/Facturering*/  then
      //Reken de verkoopeenheden om naar voorraadeenheden
      set @_AantalBesteldVrrdEenh          = @AantalBesteld          * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
      set @AantalDezeLeveringVrrdEenh      = isNull(@AantalDezeLeveringVrrdEenh, @AantalDezeLevering * @_VkeAantalVoorraadEenhedenInVerkoopEenheid);
      set @AantalDezeFactureringVrrdEenh   = isNull(@AantalDezeFactureringVrrdEenh, @AantalDezeFacturering * @_VkeAantalVoorraadEenhedenInVerkoopEenheid);
    else
      if @_VkeAantalKanVerschillen = 1 /*Afwijkend aantal bij Aantal besteld*/ then
        set @_VkeAantalVoorraadEenhedenInVerkoopEenheid = isNull(@AantalVoorraadEenhedenInVerkoopEenheid,1);
        set @_AantalBesteldVrrdEenh        = @AantalBesteld          * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        set @AantalDezeLeveringVrrdEenh    = @AantalDezeLevering     * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        set @AantalDezeFactureringVrrdEenh = @AantalDezeFacturering  * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
      else                             /*Vast aantal, niet te wijzigen*/
        set @_AantalBesteldVrrdEenh        = @AantalBesteld          * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        set @AantalDezeLeveringVrrdEenh    = @AantalDezeLevering     * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        set @AantalDezeFactureringVrrdEenh = @AantalDezeFacturering  * @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
      end if;
    end if;
  end;
  end if;

  // nu de instellingen voor directe inkoop controleren
  call WebSvcHulpProc_Order_ControleerDirecteInkoop(
    //in
    @_ArtGid,
    @DirecteInkoop,
    @OmschrijvingOvernemen,
    @Leverancier,                           //nummer
    @InkoopEenheid,
    @DirecteLevering,
    // out
    @_DirecteInkoop,
    @_OmschrijvingOvernemen,
    @_NawGidDirecteInkoop,
    @_InkoopEenheid,
    @_Directelevering
  );

  set @_DirecteProductie = if (isnull(@Productie, 0) = 1) or ((@Productie is null) and exists(select 1 from tabArtikel where ArtGid= @_ArtGid and ArtProducerenViaDirecteProductie = 1)) then 1 else 0 endif;

  // Bepaal juiste vofRegelDefNuLeveren
  set @_vofRegelDefNuLeveren =
    case
      when @_DirecteInkoop    = 1 then @_vofRegelDefNuLeverenDirInkoop
      when @_DirecteProductie = 1 then @_vofRegelDefNuLeverenDirProductie
    else
      @_vofRegelDefNuLeveren
    end;

  //Als Aantaldezelevering niet is meegegeven gaan we hem vullen adhv de vaste gegevens
  if @AantalDezeLevering is null then
    // ipv dit 100x te doen hiermee beginnen
    set @AantalDezeLevering = 0;
    set @AantalDezeLeveringVrrdEenh = 0;
    //0=Leeg, 1=Aantal Besteld, 2=Aantal in voorraad (Vrije voorraad), 3=aantal in voorraad(beschikbaar)
    case @_vofRegelDefNuLeveren
    when 0 /* Leeg */ then
      set @AantalDezeLevering = 0;
      set @AantalDezeLeveringVrrdEenh = 0;
    when 1 /* Aantal Besteld */ then
      set @AantalDezeLevering = @AantalBesteld;
      set @AantalDezeLeveringVrrdEenh = @_AantalBesteldVrrdEenh;
    else
      if @_ArtHeeftVoorraad = _qcNee then
        // Geen voorraadregistratie, maar wel obv voorraad bepalen? Dan maar alles of niks
        if @_DirecteInkoop + @_DirecteProductie = 0 then
          // Geen directe inkoop/productie, dus aantal besteld overnemen
          set @AantalDezeLevering = @AantalBesteld;
          set @AantalDezeLeveringVrrdEenh = @_AantalBesteldVrrdEenh;
        end if;
      else
        // Voorraadregistrerend, dus obv voorraad controleren
        select Sum(if (@_vofRegelDefNuLeveren = 2) then calcVrijeVoorraad else calcBeschikbareVoorraad endif) into @_Voorraad
        from vwVoorraadAantallen
        where calcArtGid = @_ArtGid
          and calcMagGid = @_OrrMagGid;

        case
          when @_AantalBesteldVrrdEenh <= @_Voorraad then
            set @AantalDezeLevering = @AantalBesteld;
            set @AantalDezeLeveringVrrdEenh = @_AantalBesteldVrrdEenh;
          when @_Voorraad > 0 then
            set @AantalDezeLeveringVrrdEenh = @_Voorraad;
            set @AantalDezeLevering = @AantalDezeLeveringVrrdEenh / @_VkeAantalVoorraadEenhedenInVerkoopEenheid;
        end case;
      end if;
    end case;
  end if;

  //Als AantalDezeFacturering niet is meegegeven gaan we hem vullen adhv de vaste gegevens
  if @AantalDezeFacturering is null then
    if @_vofRegelDefNuFactureren = 0 /* Leeg */ then
      set @AantalDezeFacturering = 0;
      set @AantalDezeFactureringVrrdEenh = 0;
    end if;

    if @_vofRegelDefNuFactureren = 1 /* Aantal besteld */ then
      set @AantalDezeFacturering = @AantalBesteld;
      set @AantalDezeFactureringVrrdEenh = @_AantalBesteldVrrdEenh;
    end if;

    if @_vofRegelDefNuFactureren = 2 /* Aantal deze levering */ then
      set @AantalDezeFacturering = @AantalDezeLevering;
      set @AantalDezeFactureringVrrdEenh = @AantalDezeLeveringVrrdEenh;
    end if;
  end if;

  if IsNull(@PartijNummer, '') <> '' then
    select ArtPartijGid, if (@_ArtIsPartijAparteKostPrijs = _qcJa) then ArtPartijKostprijsEx else null endif
    into @_ArtPartijGid, @_ArtPartijKostprijsEx
    from tabArtikelPartij
    where ArtPartijArtGid = @_ArtGid
      and ArtPartijNummer = @PartijNummer;

    if (@_ArtPartijGid is null) then
      call Raise(20700, 'PartijNummer'); // (20700) Ongeldige waarde: %1!
    end if;

    if (select ArtPartijIsGeblokkeerdVoorVerkoop from tabArtikelPartij where ArtPartijGid = @_ArtPartijGid) = _qcJa then     // ArtPartijIsGeblokkeerdVoorInkoop = 1 Partijnummer is geblokkeerd voor verkoop
      call Raise(20780,_U('Partijnummer is'),_U('Partijnummer is geblokkeerd voor verkoop'));   // (20780) %1! niet mogelijk: %2!
    end if;
  else
    // geen partij meegegeven, kijk of we een partij kunnen voorzetten
    if (@_ArtIsPartijRegistreren = _qcJa)                                                    // artikel is partijregistrerend?
       and (@_ArtIsPartijVerkoopCheckOuderePartijOp = _qcJa)                                 // artikel heeft een controle op oudste partij?
       and (@_vofRegelDefPartijAlsNietVerplicht <> 0) /* 0=leeg */                           // partij volgens artikelinstellingen
    then

      call PartijGeefOudste(@_ArtGid, @_OrrMagGid, @_ArtPartijVerkoopCheckOuderePartij, @_ArtPartijGid);
    end if;

    if (@_ArtPartijGid is null) and (@_ArtIsPartijNrBijLeverenVerplicht = _qcJa) then  //Partij is verplicht bij het artikel
      call Raise(20700 , _U('%1! is verplicht.', 'Partijnummer')) ; // Ongeldige waarde: %1!
    end if;
  end if;

  //Verkoopprijs
  if (isNull(@BrutoVerkoopprijs, 0) < 0) then
    call Raise(20700, 'BrutoVerkoopprijs'); // (20700) Ongeldige waarde: %1!
  end if;

  if (@BrutoVerkoopprijs is null) or (@Korting1 is null) then
  begin
    declare @_DebGrpGid integer = (select NawFilDebGrpGid from tabNawFile where nawfilnawgid = @_OrkNawGid);
    declare @_BrutoVerkoopprijs numeric(15,3);
    declare @_VerkoopPrijsPer smallint;
    declare @_KortingSoort smallint;
    declare @_KortingsBedrag numeric(15,3);
    declare @_KortingsPerc numeric(15,3);

    // Haal actuele prijsafspraak op
    call BepaalPrijsAfspraak(@_OrkNawGid, @_ArtGid, @_VkeGid, @_ArtOpbrGrpGid, @_DebGrpGid, @_ArtPartijGid, @_OrkIsInclBtw, @_OrkValNummer, @_AantalBesteldVrrdEenh,
                             @_AantalBesteldVrrdEenh, @@BasisValutaNummer, @@BasisValutaCode, now(), // IN parameters
                             null, null, null, null, @_BrutoVerkoopprijs, @_KortingSoort, @_KortingsPerc, @_KortingsBedrag, null, null, @_VerkoopPrijsPer); //OUT parameters

    if (@BrutoVerkoopprijs is null) then
      set @BrutoVerkoopprijs = @_BrutoVerkoopprijs;
      set @_VkeVerkoopPrijsPer = @_VerkoopPrijsPer;
    end if;

    if (@Korting1 is null) then
      set @Korting1IsPercentage = if(@_KortingSoort = 1) then _qcJa else _qcNee end if;

      if @Korting1IsPercentage = _qcJa then
        set @Korting1 = @_KortingsPerc;
      else
        set @Korting1 = @_KortingsBedrag;
      end if;
    end if;
  end;
  end if;

  //Kostprijs instellen
  set @_OrrKostprijs = IsNull(@_ArtPartijKostprijsEx, @_ArtKostprijsEx);
  if (@Kostprijs is not null) and (@_ArtIsKostprijsWijzigenInOrder = _qcJa) then
    set @_OrrKostprijs = @Kostprijs;
  end if;

  if IsNull(@Korting1IsPercentage, 0) not in (0,1) then
    call Raise(20700, 'Korting1IsPercentage'); // (20700) Ongeldige waarde: %1!
  end if;

  if (@Korting1 is not null) and (@Korting1IsPercentage = 1) then
    if (@Korting1 < -100) or (@Korting1 > 100) then
      call Raise(20700, 'Korting1'); // (20700) Ongeldige waarde: %1!
    end if;
    set @Korting1 = Round(@Korting1, 2);
  end if;

  if (@Korting2 is not null) then
    if (@Korting2 < -100) or (@Korting2 > 100) then
      call Raise(20700, 'Korting2'); // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  if (@_OrrRegelsoort <> 0) then  //artikel
    if (@_ArtAantallen = 1) then
      if IsNull(@AantalBesteld, 0) = 0 then
        call Raise(20700, 'AantalBesteld'); // (20700) Ongeldige waarde: %1!
      end if;
    end if;
  end if;

  // Controleren CBS landcode oorsprong
  if IsNull(@CbsLandOorsprong, '') <> '' then
    select first LndGid into @_CBSLndGidOorsprong from tabLand where LndEigenCode = @CbsLandOorsprong;
    if (@_CBSLndGidOorsprong is null) then
      call Raise(20698); // Ongeldige of geen CbsLandOorsprong meegegeven!
    end if;
  else
    set @_CBSLndGidOorsprong = (select first IsNull(ArtPartijLndGidCbsOorsprong, ArtLndGidCbsOorsprong)
                                from tabArtikel
                                left outer join tabArtikelPartij on ArtPartijArtGid = ArtGid and ArtPartijGid = @_ArtPartijGid
                                where ArtGid = @_ArtGid);
  end if;

  select first CbsVastNaarCbsIrisUitvoer, CbsVastExtraHandelNaarCbsIris, CbsVastDouaneregelingUitvoer, CbsVastCbsTrGidUitvoer into @_CbsUitvoer, @_CbsExtraHandel, @_CbsDouaneRegeling, @_CbsTrGid from tabCbsVast;

  // Douaneregeling invullen indien meegegeven, Default alleen als Uitvoer + Extrahandel aanstaan in VG
  if @CbsDouaneRegeling is not null then
    set @_CbsDouaneRegeling =  @CbsDouaneRegeling;
  elseif @_CbsUitvoer = 0 or @_CbsExtraHandel = 0 then
    set @_CbsDouaneRegeling = null
  end if;

  // Transactie alleen default invullen indien Uitvoer aanstaat in VG OF als order niet meegaat in CBS-aangifte
  if @_OrrRegelsoort = 0 then
    // Regelsoort=tekst, dus geen transactiecode
    set @_CbsTrGid = null;
  else
    if @CbsTransactiecode is null then
      // Niet meegegeven, dus vullen obv instellingen in kop+CBSvast. @_CbsTrGid had al de instelling uit de CBSvast
      if @_CbsUitvoer = 0 or @_OrkCbsMeenemenInAangifte = 0 then
        set @_CbsTrGid = null;
      end if;
    else
      // Opzoeken transactie en opnemen
      set @_CbsTrGid = null;
      if @CbsTransactiecode <> '' then
        select first CbsTrGid
        into @_CbsTrGid
        from tabCbsTransactie
        where CbsTrCode = @CbsTransactiecode;
        if @_CbsTrGid is null then
          call Raise(20720, 'CbsTransactiecode'); //(20720) %1! niet gevonden!
        end if;
      end if;
    end if;
  end if;

  set @LeverDatum = (select DateTimeConversieVoorWebServices(@LeverDatum, @LeverDatum));

  // Voorraad reserveren volgens de VG instelling; indien goedgekeurd alles, anders volgens de VG. Invulling vindt plaats in trigger
  set @_Reservering = (if @_OrkGoedgekeurd = _qcJa then 2 else @_VofVoorraadReserveren endif);

  if (@_DirecteInkoop = 1) and (@Productie = 1) then
    set @Productie = 0; // beide kunnen niet aanstaan, 58661
  end if;

  if (@Productie = 1) then
    // eerst kijken of er een standaard recept is dat niet geblokkeerd is
    select ArtRcptGidStandaard into @_OrrRcptGid
    from   tabArtikel
    inner join tabReceptuur on (RcptGid=ArtRcptGidStandaard)
    where ArtGid = @_ArtGid and RcptGeblokkeerd=0;

    if @_OrrRcptGid is null then
      // als er geen standaard recept is, dan bepalen hoeveel recepten er met dit artikel als eindproduct zijn
      select count(*) into @_AantalRecepten
      from
        tabReceptuur
      inner join tabReceptuurEindProduct ON RcpeRcptGid = RcptGid
      where
         RcpeArtGid = @_ArtGid    // alleen recepten die hetzelfde eindproduct opleveren
         and rcptGeblokkeerd = 0; // geblokkeerde recepten doen niet mee

      if @_AantalRecepten = 1 then
        select first RcptGid into @_OrrRcptGid
        from   tabReceptuur
        inner join tabReceptuurEindProduct ON RcpeRcptGid = RcptGid
        where  RcpeArtGid = @_ArtGid and rcptGeblokkeerd = 0;
      end if;
    end if;
  end if;

  // Determine VAT code, only applicable to tariffs/rates and articles
  if ( @_OrrRegelsoort in ( 1 /*tariff*/ ,2 /*article*/ ) ) then
    begin
      declare @AfleverLndGid integer;
      declare @VerzendLndGid integer;

      if @BtwCode is not null then
        select BtwCode into @_OrrBtwCode from tabBtw where BtwCode = @BtwCode;
        if (@_OrrBtwCode is null) then
          call Raise(20700, 'BtwCode'); // (20700) Ongeldige waarde: %1!
        end if;
      end if;

      // In case VAT code is unknown, obtain default using several settings
      if (@_OrrBtwCode is null) then
        begin
          // Request Delivery country
          set @AfleverLndGid = ( select OrderGeefAfleverLndGid(@_OrkGid) );

          // Request shipping country
          set @VerzendLndGid =
            (if @_OrrRegelsoort = 2 then // article
              if @_DirecteInkoop = 0 then
                ( select AdrLndGid from tabMagazijn inner join tabAdres on MagAdrGid = AdrGid where MagGid = @_OrrMagGid )
              else
              ( select  IsNull(BestelAdres.AdrLndGid,  CorrVestAdres.AdrLndGid) LevVerzAdresLndGid
                from    tabNaw
                  inner join tabLeverancierGegevens       on LevGegNawGid = NawGid
                  left outer join tabAdres BestelAdres    on LevGegAdrGidBestelAdres = BestelAdres.AdrGid
                  left outer join tabAdres CorrVestAdres  on CorrVestAdres.AdrGid = (case LevGegBestelAdres when 0 then NawGidCorrespondentie when 1 then NawGidVestiging end)
                where NawGid = @_NawGidDirecteInkoop )
              end if
            else // tariff
              ( select  AdrLndGid
                from    tabMagazijn
                  inner join tabAdres     on MagAdrGid = AdrGid
                  inner join tabOrderKop  on OrkGid = @_OrkGid
                where MagGid = OrkDefaultMagGid )
            end if
          );

          set @_OrrBtwCode = GeefBtwCodeVerkoop( @_OrkFactuurNawGid, @_ArtGid, @_ArtPartijGid, @AfleverLndGid, @VerzendLndGid );
        end;
      end if;
    end;
  end if; // Determine VAT code

  /*Tekst op factuur*/
  if (@TekstOpFactuur is null) then
    select first ArtTekst into @TekstOpFactuur
    from (select 1 volgorde, ArtPartijTekstOpFactuur ArtTekst
          from tabArtikelPartijTeksten
          where ArtPartijTekstArtPartijGid = @_ArtPartijGid
            and ArtPartijTekstTaalGid=(select NawTaalGid from tabnaw where nawGid = @_OrkNawGid)
            and ArtTekst is not null
          union
          select 2 volgorde, ArtPartijTekstOpFactuur ArtTekst
          from tabArtikelPartijTeksten
          inner join tabVasteGegevensOrdersFactureren on (vofTekstOpFactuurTaalGid=ArtPartijTekstTaalGid)
          where ArtPartijTekstArtPartijGid = @_ArtPartijGid
            and ArtTekst is not null
          union
          select 3 volgorde, ArtTekst
          from tabArtikelTeksten
          where ArtTekstArtGid = @_ArtGid
            and ArtTaalGid=(select nawTaalGid from tabnaw where nawGid = @_OrkNawGid)
            and ArtTekst is not null
          union
          select 4 volgorde, ArtTekst
          from tabArtikelTeksten
          inner join tabVasteGegevensOrdersFactureren on (vofTekstOpFactuurTaalGid=ArtTaalGid)
          where ArtTekstArtGid = @_ArtGid
          ) as ArtikelTekst order by volgorde;
  end if;

  /*Regelnummer bepalen*/
  if (@OrderRegelNummer is not null) then
    //Komt regelnummer al voor? Dan tussenvoegen!
    if exists (select first 1 from tabOrderRegel where OrrOrkGid = @_OrkGid and OrrRegelnr = @OrderRegelNummer) then
      // Waneer regelnummer al bestaat, en RegelTussenvoegen = 1, worden de bestaande regel(s) opgeschoven met +1
      // Bij regels 1,2,3,6,7,8 wordt bij tussenvoegen van regelnummer 2, alleen de regelnummers 2 en 3 doorgeschoven. Resultaat is dan: 1,2(nieuw), 3, 4, 6, 7, 8
      case
        when isNull(@Actie, _ACTIE_TOEVOEGEN) = _ACTIE_TUSSENVOEGEN then
        begin
          declare @totregel integer;

          //Is de regel waar je wilt toevoegen een vervolgArtikel?
          if exists(select 1
                    from tabOrderRegel
                    where OrrVervolgMasterOrrGid is not null
                      and OrrOrkGid = @_OrkGid
                      and OrrRegelnr = @OrderRegelNummer) then
            call Raise(20780, _U('Orderregel tussenvoegen'), _U('regel is een volgartikel!'));  // <Actie> niet mogelijk. Reden: <Reden>.
          end if;

          // Eerstvolgende niet-bestaande regelnummer NA @regelnummer opzoeken
          select first row_num
          into   @totregel
          from sa_rowgenerator(@OrderRegelNummer, 1000)
          where not exists(select first 1 from taborderregel where OrrOrkGid = @_OrkGid and orrRegelnr = row_num)
          order by row_num;

          if @TotRegel = 1000 then
            call Raise(20780, _U('Orderregel tussenvoegen'), _U('regelnummers worden hoger dan 999!'));  // <Actie> niet mogelijk. Reden: <Reden>.
          end if;

          // Regelnummer 1 positie doorschuiven
          update tabOrderRegel
          set    orrRegelnr = orrRegelnr + 1
          where  OrrOrkGid = @_OrkGid
                 and orrRegelnr between @OrderRegelNummer and @totregel
          order by orrRegelnr asc;
        end;

        when isNull(@Actie, _ACTIE_TOEVOEGEN) = _ACTIE_TOEVOEGEN then
          call Raise(20780, _U('Orderregel toevoegen'), _U('%1! komt al voor', 'RegelNummer'));  // <Actie> niet mogelijk. Reden: <Reden>.
      end case;

    end if;
  end if;

  // Nu gaan we echt een regel toevoegen, dit gebeurt in meerdere transacties
  begin atomic

    if LockedById(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid) = _qcNee then  //Als de order nog niet in gebruik is genomen, dan eerst locken
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabOrderKop', @_OrkGid, @_Lockresult, 0, 'KingWebService');
      if @_Lockresult <> 0 then
        call Raise(20741, 'Order'); // (20741): %1 is in gebruik!
      end if;
    end if;

    insert into tabOrderRegel(OrrOrkGid, OrrRegelnr, OrrExternId, OrrRegelsoort, OrrArtGid, OrrKstpGid, OrrKstdGid, OrrTekstOpFactuur,
                              OrrAantalBesteld, OrrAantalBesteldVrrdEenh, OrrAantalLevering, OrrAantalLeveringVrrdEenh,
                              OrrAantalDezeFacturering, OrrAantalDezeFactureringVrrdEenh, OrrBrutoVerkoopPrijs,
                              OrrRegelKorting1, OrrRegelKorting2, OrrLeverDatum, OrrEdiBuffer, OrrOpbrGrpGid, OrrBtwCode, OrrMagGid,
                              OrrAantDecAantal, OrrAantDecAantalVrrdEenh, OrrAantDecBedrag, OrrKostprijs, OrrPrijsPer,
                              OrrIsAantallen, OrrIsKortingsPercentage, OrrArtPartijGid, OrrVkeGid,
                              OrrAantalVrrdEenhInVerkEenhMagAfwijken, OrrAantalVrrdEenhInVerkEenh, OrrEenheidPrijsPer,
                              OrrDirecteInkoop, OrrOmsNaarBestelling, OrrNawGidDirecteInkoop, OrrDirInkInkoopEenheid, OrrDirecteLevering, OrrReservering,
                              OrrLndGidCbsOorsprong, OrrCbsDouaneregeling, OrrCbsTrGid,
                              OrrProductie, OrrRcptGid
                             )
                       values(@_OrkGid, @OrderRegelNummer, @ExternOrderregelID, @_OrrRegelsoort, @_ArtGid, @_KstpGid, @_KstdGid, @TekstOpFactuur,
                              @AantalBesteld, @_AantalBesteldVrrdEenh, @AantalDezeLevering, @AantalDezeLeveringVrrdEenh,
                              @AantalDezeFacturering, @AantalDezeFactureringVrrdEenh, @BrutoVerkoopprijs,
                              @Korting1, @Korting2, @LeverDatum, @EdiBuffer, @_ArtOpbrGrpGid, @_OrrBtwCode, @_OrrMagGid,
                              @_VkeAantalDecimalen, @_ArtAantDecAantallen, @_ArtAantDecPrijzen, @_OrrKostprijs, @_ArtPrijsPer,
                              @_ArtAantallen, @Korting1IsPercentage, @_ArtPartijGid, @_VkeGid,
                              @_VkeAantalKanVerschillen, @_VkeAantalVoorraadEenhedenInVerkoopEenheid, @_VkeVerkoopPrijsPer,
                              @_DirecteInkoop, @_OmschrijvingOvernemen, @_NawGidDirecteInkoop, @_InkoopEenheid, @_Directelevering, @_Reservering,
                              @_CBSLndGidOorsprong, @_CbsDouaneRegeling, @_CbsTrGid,
                              @Productie, @_OrrRcptGid
                             );
    set @_OrrGid = @@Identity;

    // Vrije rubrieken vh artikel overnemen naar de orderregel
    call OrderRegelOvernemenVrijeRubrieken(@_OrrGid);

    // Locaties worden eventueel bij statuswijziging wel toegevoegd.
    begin  // locatie toewijzen
      declare @_LocGid  integer;
      declare @HeeftSpecregelsZonderLocatie smallint;
      declare @_Vullocaties smallint = if @_ArtHeeftVoorraad = _qcJa then 0 else 1 end if; //Art zonder voorraad altijd een locatie vullen.

      if  (IsNull(@AantalDezeLevering, 0) <> 0) and // er is iets te leveren
          (@_OrrRegelsoort = 2) then                // en dat is een echt artikel
        if not exists(select 1 from tabOrderRegelLocatie where OrlOrrGid = @_OrrGid) then
          call OrderRegelSpecificaties_VulLocatiesAan(
            @OrkGid = @_OrkGid,
            @OrrGid = @_OrrGid,
            @VulLocaties = @_Vullocaties, // 0 = afhankelijk van orderstatus, 1 = altijd invullen, -1 = altijd leeg; indien leeg, dan niet kijken naar beschikbare voorraad, gewoon altijd op voorkeurslocatie
            @MatViewNummerVoorraadAantallen = '', // Geen materialized view aanmaken! We zitten in een atomic!!
            @HeeftSpecregelsZonderLocatie = @HeeftSpecregelsZonderLocatie
          );
          // Als er nog specregels zonder locatie zijn, dan de order (eventueel) van vrij voor leveren afhalen
          if @HeeftSpecregelsZonderLocatie <> 0 then
            update taborderkop set OrkVrijVoorLevering = 0 where OrkGid = @_OrkGid and OrkVrijVoorLevering = 1;
          end if;
        end if;
      end if;
    end; // Locatie toewijzen

  end; // atomic

  select OrrRegelnr as RegelNummer from tabOrderRegel where OrrGid = @_OrrGid;

  //call TraceEind('WebSvcHulpProc_Order_OrderRegel_ToevoegenTussenvoegen');
end;


create or replace procedure WebSvcProc_Order_Onderhoud_VrijeRubriek_LockVrijgeven()
begin
end;


create or replace procedure WebSvcProc_Order_Onderhoud_VrijeRubriek_ToevoegenWijzigen(
  in @Omschrijving nchar(40),
  in @Type nchar(15),   /* Geldige waardes: null (bij wijzigen), 'tekst', 'getal', 'datum', 'tijd', 'selectievakje', 'keuzelijst', 'email', 'website', 'bestand', 'telefoon'*/
  in @Hint nchar(80),
  in @Verplicht nchar(3), /* 'JA', 'NEE' */
  in @Uniek nchar(3), /* 'JA', 'NEE' */
  in @Lengte numeric(3,0),
  in @Decimalen numeric(1,0), /* >= 0 en <= 5 */
  in @Keuzelijst long varchar, //Delimited met CrLf (/0x0d/0x0a) OF '|'
  in @Defaultwaarde nchar(250), //Bevat default voor elk type veld!. Bij datum/tijd: nu/now levert datum/tijd van server
  in @DefaultDatum nchar(16), //Eigendatum, Verwerkingsdatum, Systeemdatum
  in @DefaultTijd nchar(11), //EigenTijd, SysteemTijd
  in @Sjabloon nchar(255), //Bevat sjabloon voor elk type dat een sjabloon kan hebben
  in @Groep nchar(40),
  in @OpVerkoopDocument nchar(3) /* 'JA', 'NEE' */
)
begin
  //call trace('Begin WebSvcProc_Order_Onderhoud_VrijeRubriek_ToevoegenWijzigen')

  if IsModuleActive('wo') = 0 then
    call Raise(20900);  //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  call WebSvcHulpProc_VrijeRubriek_ToevoegenWijzigen(
    'ORK', //@VrBestandOms
    0, //@VrGroepID
    0, //@VrSubGroepId
    @Omschrijving,
    @Type,
    @Hint,
    @Verplicht,
    @Uniek,
    @Lengte,
    @Decimalen,
    @Keuzelijst,
    @Defaultwaarde,
    @Sjabloon,
    @Groep,
    @DefaultDatum,
    @DefaultTijd,
    @OpVerkoopDocument
  );

  //call trace('Einde WebSvcProc_Order_Onderhoud_VrijeRubriek_ToevoegenWijzigen');
end;

