create or replace procedure WebSvcProc_Order_OrderRegel_Tussenvoegen(
  in @OrderNummer numeric(10,0),
  in @OrderRegelNummer numeric(10,0) default null,
  in @ExternOrderregelID nchar(20),
  in @RegelSoort nchar(5),
  in @ArtikelNummer nchar(20),
  in @KostenplaatsCode nchar(8),
  in @KostendragerCode nchar(8),
  in @TekstOpFactuur long nvarchar,
  in @AantalBesteld numeric(15,3),
  in @AantalDezeLevering numeric(15,3),
  in @AantalDezeFacturering numeric(15,3),
  in @BrutoVerkoopprijs numeric(15,3),
  in @Korting1 numeric(15,3),
  in @Korting2 numeric(15,2),
  in @LeverDatum date,
  in @EdiBuffer long nvarchar,
  in @BtwCode numeric(3,0),
  in @MagazijnCode numeric(3,0),
  in @Korting1IsPercentage smallint,
  in @PartijNummer nchar(20),
  in @VerkoopEenheid nchar(20) default '',
  in @EenheidPrijsPer nchar(20) default 'VOORRAADEENHEDEN',
  in @AantalVoorraadEenhedenInVerkoopEenheid numeric(15,3) default 1,
  in @AantalDezeLeveringVrrdEenh numeric(15,3) default null,
  in @AantalDezeFactureringVrrdEenh numeric(15,3) default null,
  in @DirecteInkoop smallint default null,
  in @OmschrijvingOvernemen smallint default null,
  in @Leverancier nchar(10) default null,
  in @InkoopEenheid nchar(20) default null,
  in @DirecteLevering nchar(40) default null,
  in @CBSLandOorsprong nchar(3) default null,
  in @CbsDouaneRegeling nchar(4) default null,
  in @CbsTransactiecode nchar(2) default null,
  in @Kostprijs numeric(15,3) default null,
  in @Productie smallint default null
)
result(RegelNummer smallint)
begin
  /*Constanten*/
  declare _qcNee smallint = 0;

  //call TraceBegin('WebSvcProc_Order_OrderRegel_Tussenvoegen > ' + '@OrderNummer = ' + string(@OrderNummer) + ', @RegelSoort = ' + string(@RegelSoort) +', @ArtikelNummer = ' + @ArtikelNummer);

  if IsModuleActive('wo') = _qcNee then
    call Raise(20900);  //Optie ''Webservices Orders'' niet geactiveerd!
  end if;

  if (@OrderRegelNummer is null) or (@OrderRegelNummer not between 1 and 999) then
    call Raise(20700, _U('%1!, minimaal %2!, maximaal %3! toegestaan.', 'OrderRegelNummer', '1', '999')); // Ongeldige waarde: %1
  end if;

  //Aanroepen van de hulp routine voor het toevoegen
  select RegelNummer
  from WebSvcHulpProc_Order_OrderRegel_ToevoegenTussenvoegen(
    @OrderNummer,
    @OrderRegelNummer, /*Orderregelnummer is leeg bij het toevoegen*/
    1, /*1 = Tussenvoegen (met opschuiven)*/
    @ExternOrderregelID,
    @RegelSoort,
    @ArtikelNummer,
    @KostenplaatsCode,
    @KostendragerCode,
    @TekstOpFactuur,
    @AantalBesteld,
    @AantalDezeLevering,
    @AantalDezeFacturering,
    @BrutoVerkoopprijs,
    @Korting1,
    @Korting2,
    @LeverDatum,
    @EdiBuffer,
    @BtwCode,
    @MagazijnCode,
    @Korting1IsPercentage,
    @PartijNummer,
    @VerkoopEenheid,
    @EenheidPrijsPer,
    @AantalVoorraadEenhedenInVerkoopEenheid,
    @AantalDezeLeveringVrrdEenh,
    @AantalDezeFactureringVrrdEenh,
    @DirecteInkoop,
    @OmschrijvingOvernemen,
    @Leverancier,
    @InkoopEenheid,
    @DirecteLevering,
    @CBSLandOorsprong,
    @CbsDouaneRegeling,
    @CbsTransactiecode,
    @Kostprijs,
    @Productie
  );

  //call TraceEind('WebSvcProc_Order_OrderRegel_Tussenvoegen');
end;


create or replace procedure WebSvcProc_Prijsafspraak_ToevoegenWijzigen(
  in @SoortPrijsafspraak nchar(15), // DEB_ART,DEB_OPBRGRP,DEBGRP_ART of DEBGRP_OPBRGRP
  in @Debiteurnummer nchar(10),
  in @DebiteurGroepnummer nchar(3),
  in @Artikelnummer nchar(20),
  in @OpbrengstgroepNummer nchar(4),
  in @TypePrijsafspraak nchar(15), // KORTPERC, KORTBEDR, PRIJS_KORTPERC, PRIJS_KORTBEDR, PRIJS_KORTSTAF of KORTSTAF
  in @ValutaCode nchar(3),
  in @InExBtw nchar(7),            // EXCLBTW of INCLBTW
  in @Prijs numeric(15,3),
  in @Kortingspercentage numeric(5,2),
  in @Kortingsbedrag numeric(15,3),
  in @Staffelcode nchar(10),
  in @Opmerking long nvarchar)
begin
  declare @CombiSoort smallint;
  declare @PraGid     integer;

  declare @ArtGid     integer;
  declare @NawGid     integer;
  declare @DebGrpGid  integer;
  declare @OpbrGrpGid integer;
  declare @IsInclBtw  integer;
  declare @ValNummer  integer;
  declare @Type       smallint;
  declare @StfKopGid  integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Prijsafspraak_ToevoegenWijzigen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Gebruiker = ' + @Gebruiker + ', @TaakSoort = ' + string(@TaakSoort));

  if IsModuleActive('wl') = 0 then
    raiserror 20790, 'Optie Webservices Logistiek'; // (20790) '%1!' niet geactiveerd!
  end if;

  //SoortPrijsafspraak
  case
    when @SoortPrijsafspraak not in ('DEB_ART','DEB_OPBRGRP','DEBGRP_ART','DEBGRP_OPBRGRP') then raiserror 20700, 'SoortPrijsafspraak = ' + @SoortPrijsafspraak; //Ongeldige waarde: %1!
    when (@SoortPrijsafspraak = 'DEB_ART')        and (@Debiteurnummer is not null) and (@DebiteurGroepnummer is null)     and (@Artikelnummer is not null) and (@OpbrengstgroepNummer is null)     then set @CombiSoort = 4;
    when (@SoortPrijsafspraak = 'DEB_OPBRGRP')    and (@Debiteurnummer is not null) and (@DebiteurGroepnummer is null)     and (@Artikelnummer is null)     and (@OpbrengstgroepNummer is not null) then set @CombiSoort = 3;
    when (@SoortPrijsafspraak = 'DEBGRP_ART')     and (@Debiteurnummer is null)     and (@DebiteurGroepnummer is not null) and (@Artikelnummer is not null) and (@OpbrengstgroepNummer is null)     then set @CombiSoort = 2;
    when (@SoortPrijsafspraak = 'DEBGRP_OPBRGRP') and (@Debiteurnummer is null)     and (@DebiteurGroepnummer is not null) and (@Artikelnummer is null)     and (@OpbrengstgroepNummer is not null) then set @CombiSoort = 1;
    else raiserror 20241; //Er zijn velden ingevuld en/of leeggelaten die leeg en/of ingevuld moeten zijn bij deze prijsafspraak!
  end case;

  //Artikelnummer
  if @CombiSoort in (2,4) then
    set @ArtGid = (select ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @Artikelnummer);
    if @ArtGid is null then
      raiserror 20720, 'ArtikelNummer';  // (20720) %1! niet gevonden!
    end if;
  end if;

  //Debiteurnummer
  if @CombiSoort in (3,4) then
    set @NawGid = (select NawFilNawGid from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @Debiteurnummer);
    if (@NawGid is null) then
      raiserror 20720, 'Debiteurnummer';  // (20720) %1! niet gevonden!
    end if;
  end if;

  //DebiteurGroepnummer
  if @CombiSoort in (1,2) then
    set @DebGrpGid = (select DebGrpGid from tabDebiteurGroepen where DebGrpNr = @DebiteurGroepnummer);
    if (@DebGrpGid is null) then
      raiserror 20720, 'DebiteurGroepNummer';  // (20720) %1! niet gevonden!
    end if;
  end if;

  //OpbrengstgroepNummer
  if @CombiSoort in (1,3) then
    set @OpbrGrpGid = (select OpbrGrpGId from tabOpbrengstGroep where OpbrGrpNummer = @OpbrengstgroepNummer);
    if (@OpbrGrpGid is null) then
      raiserror 20720, 'OpbrengstgroepNummer!';   // (20720) %1! niet gevonden!
    end if;
  end if;

  //TypePrijsafspraak
  case @TypePrijsafspraak
    when 'KORTPERC'       then set @Type = 0;
    when 'KORTBEDR'       then set @Type = 1;
    when 'PRIJS_KORTPERC' then set @Type = 3;
    when 'PRIJS_KORTBEDR' then set @Type = 4;
    when 'PRIJS_KORTSTAF' then set @Type = 5;
    when 'KORTSTAF'       then set @Type = 6;
    when null             then raiserror 20700, 'TypePrijsafspraak'; //Ongeldige waarde: %1!
    else                       raiserror 20700, 'TypePrijsafspraak (' + @TypePrijsafspraak + ')'; //Ongeldige waarde: %1!
  end case;

  //ValutaCode
  if (@Type in (1,3,4,5) and @ValutaCode is null) then
    raiserror 20000, 'Bij prijsafspraken KORTBEDR, PRIJS_KORTPERC, PRIJS_KORTBEDR en PRIJS_KORTSTAF moet ValutaCode ingevuld zijn';  // (20000) %1!
  elseif (@Type not in (1,3,4,5) and @ValutaCode is not null) then
    raiserror 20000, 'Bij prijsafspraken KORTPERC en KORTSTAF mag ValutaCode niet ingevuld zijn'; // (20000) %1!
  elseif (@Type in (1,3,4,5) and @ValutaCode is not null) then
    set @ValNummer = (select ValNummer from tabValuta where ValCode = @ValutaCode);
    if (@ValNummer is null) then
      raiserror 20720, 'ValutaCode!';  // (20720) %1! niet gevonden!
    end if;
  end if;

  //BTW inclusief/exclusief
  if (@Type in (1,3,4,5) and @InExBtw is null) then
    raiserror 20000, 'Bij prijsafspraken KORTBEDR, PRIJS_KORTPERC, PRIJS_KORTBEDR en PRIJS_KORTSTAF moet InExBtw ingevuld zijn';  // (20000) %1!
  elseif (@Type not in (1,3,4,5) and @InExBtw is not null) then
    raiserror 20000, 'Bij prijsafspraken KORTPERC en KORTSTAF mag InExBtw niet ingevuld zijn'; // (20000) %1!
  elseif (@Type in (1,3,4,5) and @InExBtw is not null) then
    case @InExBtw
      when 'EXCLBTW' then set @IsInclBtw = 0;
      when 'INCLBTW' then set @IsInclBtw = 1;
      when null      then raiserror 20700, 'InExBtw moet ingevuld zijn';  // Ongeldige waarde: %1!
      else                raiserror 20700, 'InExBtw ' + string(@InExBtw); // Ongeldige waarde: %1!
    end case;
  end if;

  //Prijs
  if (@Type in (3,4,5) and @Prijs is null) then
    raiserror 20000, 'Bij prijsafspraken PRIJS_KORTPERC, PRIJS_KORTBEDR en PRIJS_KORTSTAF moet Prijs ingevuld zijn';  // (20000) %1!
  elseif (@Type not in (3,4,5) and @Prijs is not null) then
    raiserror 20000, 'Bij prijsafspraken KORTPERC, KORTBEDR en KORTSTAF mag Prijs niet ingevuld zijn';  // (20000) %1!
  end if;

  //Kortingspercentage
  if (@Type in (0,3) and @Kortingspercentage is null) then
    raiserror 20000, 'Bij prijsafspraken KORTPERC en PRIJS_KORTPERC moet Kortingspercentage ingevuld zijn';  // (20000) %1!
  elseif (@Type not in (0,3) and @Kortingspercentage is not null) then
    raiserror 20000, 'Bij prijsafspraken KORTBEDR, PRIJS_KORTBEDR, PRIJS_KORTSTAF en KORTSTAF mag Kortingspercentage niet ingevuld zijn';  // (20000) %1!
  elseif ((@Type in (0,3) and @Kortingspercentage not between -100 and 100)) then
    raiserror 20700, 'Kortingspercentage ' + string(@Kortingspercentage); // Ongeldige waarde: %1!
  end if;

  //Kortingsbedrag
  if (@Type in (1,4) and @Kortingsbedrag is null) then
    raiserror 20000, 'Bij prijsafspraken KORTBEDR en PRIJS_KORTBEDR moet Kortingsbedrag ingevuld zijn';  // (20000) %1!
  elseif (@Type not in (1,4) and @Kortingsbedrag is not null) then
    raiserror 20000, 'Bij prijsafspraken KORTPERC, PRIJS_KORTPERC, PRIJS_KORTSTAF en KORTSTAF mag Kortingsbedrag niet ingevuld zijn';  // (20000) %1!
  end if;

  //Staffelcode
  if (@Type in (5,6) and @Staffelcode is null) then
    raiserror 20000, 'Bij prijsafspraken PRIJS_KORTSTAF en KORTSTAF moet Staffelcode ingevuld zijn';  // (20000) %1!
  elseif (@Type not in (5,6) and @Staffelcode is not null) then
    raiserror 20000, 'Bij prijsafspraken KORTPERC, KORTBEDR, PRIJS_KORTPERC en PRIJS_KORTBEDR mag Staffelcode niet ingevuld zijn';  // (20000) %1!
  elseif (@Type in (5,6) and @Staffelcode is not null) then

    if IsModuleActive('sf') = 0 then
      raiserror 20790, 'Optie Staffelprijzen'; // (20790) '%1!' niet geactiveerd!
    end if;

    set @StfKopGid = (select StfKopGid from tabStaffelKop where StfKopCode = @Staffelcode);
    if (@StfKopGid is null) then
      raiserror 20720, 'Staffelcode!';  // (20720) %1! niet gevonden!
    end if;
  end if;

  // Opmerking niet leeg maken bij een bestaande prijsafspraak wanneer de opmerking null is
  if @Opmerking is null then
    begin
      declare @_PraGid integer;
      declare @_PraOpm long nvarchar;
      select PraGid, PraOpm into @_PraGid, @_PraOpm from tabPrijsAfspraak
      where ( ( (@ArtGid is not null)     and (PraArtGid=@ArtGid)         ) or ( (@ArtGid is null)     and (PraArtGid is null)     and (PraVkeGid is null) ) )
        and ( ( (@NawGid is not null)     and (PraNawGid=@NawGid)         ) or ( (@NawGid is null)     and (PraNawGid is null)     and (PraVkeGid is null) ) )
        and ( ( (@DebGrpGid is not null)  and (PraDebGrpGid=@DebGrpGid)   ) or ( (@DebGrpGid is null)  and (PraDebGrpGid is null)  and (PraVkeGid is null) ) )
        and ( ( (@OpbrGrpGid is not null) and (PraOpbrGrpGid=@OpbrGrpGid) ) or ( (@OpbrGrpGid is null) and (PraOpbrGrpGid is null) and (PraVkeGid is null) ) );

      if @_PraGid is not null then // prijsafspraak wijzigen
         set @Opmerking = @_PraOpm;
      end if;
    end;
  end if;

  //Prijsafspraak aanmaken of wijzigen
  call PrijsAfspraakUpdate(@ArtGid,
                           @NawGid,
                           @DebGrpGid,
                           @OpbrGrpGid,
                           @IsInclBtw,
                           @ValNummer,
                           @Prijs,
                           @Kortingspercentage,
                           @Kortingsbedrag,
                           @Opmerking,
                           @Type,
                           @StfKopGid);

  set @@ErrorTextProcedure = 'WebSvcProc_Prijsafspraak_ToevoegenWijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Prijsafspraak_Verwijderen(in @SoortPrijsafspraak nchar(15),
                                                                 in @Debiteurnummer nchar(10),
                                                                 in @DebiteurGroepnummer nchar(3),
                                                                 in @Artikelnummer nchar(20),
                                                                 in @OpbrengstgroepNummer nchar(4),
                                                                 in @MeerdereAfsprakenVerwijderen smallint)
begin
  declare @CombiSoort smallint;
  declare @PraGid     integer;

  declare @ArtGid     integer;
  declare @NawGid     integer;
  declare @DebGrpGid  integer;
  declare @OpbrGrpGid integer;
  declare @IsInclBtw  integer;
  declare @ValNummer  integer;
  declare @Type       smallint;
  declare @StfKopGid  integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Prijsafspraak_Verwijderen > ';
  //call TraceBegin(@@ErrorTextProcedure + '@Gebruiker = ' + @Gebruiker + ', @TaakSoort = ' + string(@TaakSoort));

  if IsModuleActive('wl') = 0 then
    raiserror 20790, 'Optie Webservices Logistiek'; // (20790) '%1!' niet geactiveerd!
  end if;

  //SoortPrijsafspraak
  case
    when (@SoortPrijsafspraak = 'DEB_ART')        and ((@Debiteurnummer is not null) or (@MeerdereAfsprakenVerwijderen = 1 and @Artikelnummer is not null)) and (@DebiteurGroepnummer is null       ) and ((@Artikelnummer is not null) or (@MeerdereAfsprakenVerwijderen = 1 and @Debiteurnummer is not null)) and (@OpbrengstgroepNummer is null)      then set @CombiSoort = 4;
    when (@SoortPrijsafspraak = 'DEB_OPBRGRP')    and ((@Debiteurnummer is not null) or (@MeerdereAfsprakenVerwijderen = 1 and @OpbrengstgroepNummer is not null)) and (@DebiteurGroepnummer is null) and (@Artikelnummer is null) and ((@OpbrengstgroepNummer is not null) or (@MeerdereAfsprakenVerwijderen = 1 and @Debiteurnummer is not null))      then set @CombiSoort = 3;
    when (@SoortPrijsafspraak = 'DEBGRP_ART')     and (@Debiteurnummer is null) and ((@DebiteurGroepnummer is not null) or (@MeerdereAfsprakenVerwijderen = 1 and @Artikelnummer is not null)       ) and ((@Artikelnummer is not null) or (@MeerdereAfsprakenVerwijderen = 1 and @DebiteurGroepnummer is not null)) and (@OpbrengstgroepNummer is null) then set @CombiSoort = 2;
    when (@SoortPrijsafspraak = 'DEBGRP_OPBRGRP') and (@Debiteurnummer is null) and ((@DebiteurGroepnummer is not null) or (@MeerdereAfsprakenVerwijderen = 1 and @OpbrengstgroepNummer is not null)) and (@Artikelnummer is null) and ((@OpbrengstgroepNummer is not null) or (@MeerdereAfsprakenVerwijderen = 1 and @DebiteurGroepnummer is not null)) then set @CombiSoort = 1;
    else raiserror 20241; //Er zijn velden ingevuld en/of leeggelaten die leeg en/of ingevuld moeten zijn bij deze prijsafspraak!
  end case;

  //Artikelnummer
  if @CombiSoort in (2,4) and (@MeerdereAfsprakenVerwijderen <> 1 or @Artikelnummer is not null) then
    set @ArtGid = (select ArtGid from tabArtikel where ArtSoort = 2 and ArtCode = @Artikelnummer);
    if @ArtGid is null then
      raiserror 20720, 'ArtikelNummer';  // (20720) %1! niet gevonden!
    end if;
  end if;

  //Debiteurnummer
  if @CombiSoort in (3,4) and (@MeerdereAfsprakenVerwijderen <> 1 or @Debiteurnummer is not null) then
    set @NawGid = (select NawFilNawGid from tabNawFile where NawFilFonId = 'D' and NawFilNummer = @Debiteurnummer);
    if (@NawGid is null) then
      raiserror 20720, 'Debiteurnummer';  // (20720) %1! niet gevonden!
    end if;
  end if;

  //DebiteurGroepnummer
  if @CombiSoort in (1,2) and (@MeerdereAfsprakenVerwijderen <> 1 or @DebiteurGroepnummer is not null) then
    set @DebGrpGid = (select DebGrpGid from tabDebiteurGroepen where DebGrpNr = @DebiteurGroepnummer);
    if (@DebGrpGid is null) then
      raiserror 20720, 'DebiteurGroepNummer';  // (20720) %1! niet gevonden!
    end if;
  end if;

  //OpbrengstgroepNummer
  if @CombiSoort in (1,3) and (@MeerdereAfsprakenVerwijderen <> 1 or @OpbrengstgroepNummer is not null) then
    set @OpbrGrpGid = (select OpbrGrpGId from tabOpbrengstGroep where OpbrGrpNummer = @OpbrengstgroepNummer);
    if (@OpbrGrpGid is null) then
      raiserror 20720, 'OpbrengstgroepNummer!';   // (20720) %1! niet gevonden!
    end if;
  end if;

  //Verwijderen prijsafspraak op basis van combinatie
  delete from tabPrijsAfspraak
  where PraCombiSoort = @CombiSoort
        and PraVkeGid is null
        and ((@ArtGid     is not null) and (PraArtGid = @ArtGid        ) or (@ArtGid is null))
        and ((@NawGid     is not null) and (PraNawGid = @NawGid        ) or (@NawGid is null))
        and ((@DebGrpGid  is not null) and (PraDebGrpGid = @DebGrpGid  ) or (@DebGrpGid is null))
        and ((@OpbrGrpGid is not null) and (PraOpbrGrpGid = @OpbrGrpGid) or (@OpbrGrpGid is null));

  set @@ErrorTextProcedure = 'WebSvcProc_Prijsafspraak_Verwijderen';
  //call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcHulpProc_OrderExclusiefLocken(
  in @LockOrkNummer numeric(10,0)               ,
  in @LockUserNaam  nchar(40)     default null  , // null - King 5 zoekt het zelf wel uit...
  in @SpId          integer       default null  , // idem
  in @LoginTime     datetime      default null    // idem
)
begin
  declare @_LockResult  integer;
  declare @_OrkGid      integer;

  set @_OrkGid = ( select first 1 from tabOrderKop where OrkNummer = @LockOrkNummer );
  if @_OrkGid is null then
    call Raise(20780, _U('In gebruik nemen'), _U('order %1! niet gevonden', string(@LockOrkNummer)));        // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // locken, met standaard King 5 procedure
  call LockSetOnId(
    @Spid,
    @LoginTime,
    1,                        // 1 = Exclusieve lock, 0 = ReadLock
    'tabOrderKop',            // tabel waarin record te locken is - nchar(40)
    string(@_OrkGid),         // lockstring voor record, nchar(80)
    @_LockResult,             // 0 = OK, anders fout
    0,                        // Automatisch opruimen: 0 = nee, 1 = ja
    @LockUserNaam);           // Welke King gebruiker of proces

  // LocksetOnId is niet gelukt?
  if @_LockResult <> 0 then
    // Er bestaat geen lock voor deze connectie?
    if LockedById(@SpId, @LoginTime, 1 /*exclusieve lock*/, 'tabOrderKop', @_OrkGid) = 0  then
      call Raise(20741, _U('Order %1!', string(@LockOrkNummer)));    // (20741) %1 is in gebruik!
    end if;
  end if;
end;



create or replace procedure WebSvcHulpProc_ProductieorderExclusiefLocken(
  in @LockPrdOkGid  integer     default null  , // Verplicht
  in @LockUserNaam  nchar(40)   default null  , // null - King 5 zoekt het zelf wel uit...
  in @SpId          integer     default null  , // idem
  in @LoginTime     datetime    default null  ) // idem
begin
  declare @_LockResult integer;

  declare @qcGEENLOCK       smallint = 0;
  declare @qcEXCLUSIVELOCK  smallint = 1;

  if LockedById(@SpId, @LoginTime, @qcEXCLUSIVELOCK, 'tabProductieOrderKop', @LockPrdOkGid) = @qcGEENLOCK  then

    // locken, met standaard King 5 procedure
    call LockSetOnId(
      @@Spid,
      @@LoginTime,
      @qcEXCLUSIVELOCK,                 // 1 = Exclusieve lock, 0 = ReadLock
      'tabProductieOrderKop',           // tabel waarin record te locken is - nchar(40)
      string(@LockPrdOkGid),            // lockstring voor record, nchar(80)
      @_LockResult,                     // 0 = OK, anders fout
      0,                                // Automatisch opruimen: 0 = nee, 1 = ja
      @LockUserNaam);                   // registreer gebruiker van lock

    // LocksetOnId is niet gelukt?
    if @_LockResult <> 0 then
      // Er bestaat geen lock voor deze connectie?
      call Raise(20741,_U('Productieorder'));    // (20741) %1 is in gebruik!
    end if;
  end if;
end;




create or replace procedure WebSvcHulpProc_Productieorder_ComponentAantalEnVoorraad(
  in  @PrdOkGid         integer   ,
  in  @SoortVerwerking  smallint  , // 0 = nu te verwerken, 1 = nog te verwerken
  in  @AlleRegelsTonen  smallint    // 0 = nee, alleen met negatieve voorraad na verwerking, 1 = alle te verwerken component(specificatie)regels
)
result(
  MagGid                          integer       ,
  ArtGid                          integer       ,
  PartijGid                       integer       ,
  MagCode                         integer       ,
  ArtCode                         nchar(20)     ,
  ArtOms                          nchar(40)     ,
  ArtAantDecAantallen             smallint      ,
  ArtPartijNummer                 nchar(20)     ,
  AantalDezeVerwerking            numeric(15,3) ,
  AantalNogTeVerwerken            numeric(15,3) ,
  MagazijnVoorraadNaVerwerking    numeric(15,3) ,
  BeschikbareVoorraadNaVerwerking numeric(15,3) ,
  VrijeVoorraadNaVerwerking       numeric(15,3) ,
  StatusCodeNegatieveVoorraad     smallint       // 1 = MAGAZIJN, 2 = BESCHIKBAAR, 4 =VRIJ, of opsomming van deze codes (2 tot de macht vinkje).
)
begin
  //test
  //declare @PrdOkGid         integer = 880;
  //declare @SoortVerwerking  smallint = 0;
  //declare @AlleRegelsTonen  smallint = 0;

  // gc = query constanten
  // Meldingsopties negatieve voorraad
  declare @qcNegatiefToestaan           smallint = 0;
  declare @qcNegatiefToestaanWelMelden  smallint = 1;
  declare @qcNegatiefNietToegestaan     smallint = 2;

  // Soort verwerkingen
  declare @qcNuTeVerwerken              smallint = 0;
  declare @qcNogTeVerwerken             smallint = 1;

  // Veste Gegevens Productie (Recept)
  declare @RcpvVoorrContrBeschikbaarNegatief  smallint;
  declare @RcpvVoorrContrMagazijnNegatief     smallint;
  declare @RcpvVoorrContrVrijNegatief         smallint;

  select RcpvVoorrContrBeschikbaarNegatief,  RcpvVoorrContrMagazijnNegatief,   RcpvVoorrContrVrijNegatief
    into @RcpvVoorrContrBeschikbaarNegatief, @RcpvVoorrContrMagazijnNegatief,  @RcpvVoorrContrVrijNegatief
  from tabReceptuurVasteGegevens;

  // result set
  select
    TEVERWERKEN.MagGid,
    TEVERWERKEN.ArtGid,
    TEVERWERKEN.PartijGid,
    TEVERWERKEN.MagCode,
    TEVERWERKEN.ArtCode,
    TEVERWERKEN.ArtOms,
    TEVERWERKEN.ArtAantDecAantallen,
    TEVERWERKEN.ArtPartijNummer,
    TEVERWERKEN.AantalDezeVerwerking,
    TEVERWERKEN.AantalNogTeVerwerken,
    case @SoortVerwerking
      when 1 then  VOORRAADINFO.MagazijnVoorraad - TEVERWERKEN.AantalNogTeVerwerken
      else  VOORRAADINFO.MagazijnVoorraad - TEVERWERKEN.AantalDezeVerwerking
    end case                            as MagazijnVoorraadNaVerwerking,
    VOORRAADINFO.BeschikbareVoorraad    as BeschikbareVoorraadNaVerwerking,
    VOORRAADINFO.VrijeVoorraad          as VrijeVoorraadNaVerwerking,
    isnull( ( select 1 from dummy
              where ( ( @RcpvVoorrContrMagazijnNegatief <> @qcNegatiefToestaan ) and ( @SoortVerwerking = @qcNuTeVerwerken ) and ( VOORRAADINFO.Magazijnvoorraad < TEVERWERKEN.AantalDezeVerwerking ) )
                or  ( ( @RcpvVoorrContrMagazijnNegatief <> @qcNegatiefToestaan ) and ( @SoortVerwerking = @qcNogTeVerwerken ) and ( VOORRAADINFO.Magazijnvoorraad < TEVERWERKEN.AantalNogTeVerwerken ) ) ),
            0) +
    isnull( ( select 2 from dummy where ( @RcpvVoorrContrBeschikbaarNegatief = @qcNegatiefToestaanWelMelden )  and ( VOORRAADINFO.Beschikbarevoorraad < 0 ) ), 0) +
    isnull( ( select 4 from dummy where ( @RcpvVoorrContrVrijNegatief = @qcNegatiefToestaanWelMelden )         and ( VOORRAADINFO.VrijeVoorraad < 0 ) ) , 0 ) as StatusCodeNegatieveVoorraad

  from (  select
            MagGid,
            ArtGid,
            tPartijGid                  as PartijGid,               // hier kan partij staan die niet bij artikel bekend is?
            MagCode,
            ArtCode,
            ArtOms,
            ArtAantDecAantallen,
            ArtPartijNummer,
            sum(tAantalDezeVerwerking) as AantalDezeVerwerking,
            sum(tAantalNogTeVerwerken) as AantalNogTeVerwerken
                    /* Artikel */
                    /* Toelichting bij onderstaande query */
                    /* Aantal nog te verwerken is hetzelfde als aantal deze verwerking. Deze kunnen een andere partijnummer hebben en die is nodig voor de berekening */
                    /* Artikel */
          from  ( select
                    PrdOcMagGid       as tMagGid,
                    PrdOcArtGid       as tArtGid,
                    PrdOcArtPartijGid as tPartijGid,
                    sum(PrdOcAantalDezeVerwerking - ( select sum(PrdOcsAantalDezeVerwerking)
                                                      from tabProductieOrderComponentSpec
                                                      where PrdOcsPrdOcGid = PrdOcGid)      ) as tAantalDezeVerwerking,
                    sum(PrdOcAantalTotaalTeVerwerken -( select sum( PrdOcsAantalReedsVerwerkt - PrdOcsAantalUitvalinReedsVerwerkt )
                                                        from tabProductieOrderComponentSpec
                                                        where PrdOcsPrdOcGid = PrdOcGid) ) -
                    ( select sum(PrdOcsAantalDezeVerwerking)
                      from tabProductieOrderComponentSpec
                      where PrdOcsPrdOcGid = PrdOcGid )                                       as tAantalNogTeVerwerken
                  from tabProductieOrderComponent
                  where(PrdOcPrdOkGid = @PrdOkGid)    // Productie order
                    and(PrdOcRegelSoort = 2)          // 2 = artikel
                  group by  PrdOcGid,
                            tMagGid,
                            tArtGid,
                            tPartijGid
                    having  ( ( @SoortVerwerking = @qcNuTeVerwerken     and tAantalDezeVerwerking <> 0.0 )     // 0 = Nu te verwerken
                              or (@SoortVerwerking = @qcNogTeVerwerken  and tAantalNogTeVerwerken <> 0.0) )  // 1 = Nog te verwerken

                  union all
                  select
                    PrdOcsMagGid                    as tMagGid,
                    PrdOcArtGid                     as tArtGid,
                    PrdOcsArtPartijGid              as tPartijGid,
                    sum(PrdOcsAantalDezeVerwerking) as tAantalDezeVerwerking,
                    tAantalDezeVerwerking           as tAantalNogTeVerwerken
                  from tabProductieOrderComponentSpec
                    join tabProductieOrderComponent on  ( PrdOcsPrdOcGid = PrdOcGid )
                  where ( PrdOcPrdOkGid = @PrdOkGid )
                    and ( PrdOcRegelSoort = 2 )
                  group by  tMagGid,
                            tArtGid,
                            tPartijGid
                    having  ( ( @SoortVerwerking = @qcNuTeVerwerken     and tAantalDezeVerwerking <> 0.0 )
                              or( @SoortVerwerking = @qcNogTeVerwerken  and tAantalNogTeVerwerken <> 0.0  )  )   ) as TUSSENTABEL
            join tabMagazijn                  on  ( MagGid = TUSSENTABEL.tMagGid  )
            join tabArtikel                   on  ( ArtGid = TUSSENTABEL.tArtGid  ) and  ( ArtHeeftVoorraad = 1 )
            left outer join tabArtikelPartij  on  ( ArtPartijGid = TUSSENTABEL.tPartijGid )

          group by
            MagCode,
            ArtCode,
            ArtPartijNummer,
            ArtAantDecAantallen,
            MagGid,
            ArtGid,
            tPartijGid,
            ArtOms ) as TEVERWERKEN
  outer apply ( select sum(calcMagazijnVoorraad)     as MagazijnVoorraad,
                       sum(calcBeschikbareVoorraad)  as BeschikbareVoorraad,
                       sum(calcVrijeVoorraad)        as VrijeVoorraad
                from   vwVoorraadAantallen
                where  ( ( calcArtPartijGid = TEVERWERKEN.PartijGid )                                          // partij, indien opgegeven
                         or (  ( TEVERWERKEN.PartijGid is null ) and ( calcArtGid = TEVERWERKEN.ArtGid ) ) )   // of anders artikel
                  and  ( ( calcMagGid = TEVERWERKEN.MagGid )                                                   // EN specifiek magazijn opgegeven
                          or ( TEVERWERKEN.MagGid is null )  )                                                 // of anders alle magazijnen
              ) as VOORRAADINFO
   where  ( ( @RcpvVoorrContrBeschikbaarNegatief = @qcNegatiefToestaanWelMelden ) and ( VOORRAADINFO.Beschikbarevoorraad < 0 ) )
     or   ( ( @RcpvVoorrContrVrijNegatief = @qcNegatiefToestaanWelMelden )        and ( VOORRAADINFO.VrijeVoorraad < 0 ) )
     or   ( ( @RcpvVoorrContrMagazijnNegatief <> @qcNegatiefToestaan ) and ( @SoortVerwerking = @qcNuTeVerwerken ) and ( VOORRAADINFO.Magazijnvoorraad < TEVERWERKEN.AantalDezeVerwerking ) )
     or   ( ( @RcpvVoorrContrMagazijnNegatief <> @qcNegatiefToestaan ) and ( @SoortVerwerking = @qcNogTeVerwerken ) and ( VOORRAADINFO.Magazijnvoorraad < TEVERWERKEN.AantalNogTeVerwerken ) )
     or   ( @AlleRegelsTonen = 1 ) // alle regels, ook die die geen negatieve voorraad hebben.
  order by
    TEVERWERKEN.MagCode asc,
    TEVERWERKEN.ArtCode asc,
    TEVERWERKEN.ArtPartijNummer asc;
end;



create or replace procedure WebSvcHulpProc_Productieorder_ComponentenPlatslaanTbvVerwerking(
  in @SessieNummer                integer ,
  in @PrdOkGid                    integer ,
  in @IsVerwerkenComponenten      smallint,
  in @IsVerwerkenWerkzaamheden    smallint
)
begin
  declare @_AantalDecimalenValuta  smallint;

  set @_AantalDecimalenValuta = (select DecimalenBoeking*2 from tabvaluta where ValNummer = @@BasisValutaNummer );

  // ****************************************
  // Specificatieregels van componenten
  // ****************************************
  insert into tmpProductieOrderVerwerkPlatgeslagen(
    tmpPrdVpSessieNr,
    tmpPrdVpIsComponent,
    tmpPrdVpCompEindpGid,
    tmpPrdVpRegelSoort,
    tmpPrdVpIsErbij,
    tmpPrdVpArtGid,
    tmpPrdVpMagGid,
    tmpPrdVpLocGid,
    tmpPrdVpArtPartijGid,
    tmpPrdVpArtSerieGid,
    tmpPrdVpOpbrGrpGid,
    tmpPrdVpAantal,
    tmpPrdVpBedrag,
    tmpPrdVpAantalUitval,
    tmpPrdVpBedragUitval )
  /* Specificatieregels */
  select  @SessieNummer,
          1,
          PrdOcGid,
          PrdOcRegelSoort,
          0, // IsErbij = 0, want het gaat van de voorraad AF
          PrdOcArtGid,
          PrdOcsMagGid,
          PrdOcsLocGid,
          PrdOcsArtPartijGid,
          PrdOcsArtSerieGid,
          ArtOpbrGrpGid,
          Sum(PrdOcsAantalDezeVerwerking)             as Aantal,
          Sum( Round( IsNull( PrdOcsAantalDezeVerwerking * ( if(ArtIsPartijAparteKostPrijs = 0) or(PrdOcsArtPartijGid is null) then ArtKostprijsEx else ArtPartijKostprijsEx end if ) / ArtPrijsPer,
                              0.0),
                      @_AantalDecimalenValuta))       as Bedrag,
          Sum(PrdOcsAantalUitvalInDezeVerwerking)     as AantalUitval,
          Sum( Round( IsNull( PrdOcsAantalUitvalInDezeVerwerking * ( if(ArtIsPartijAparteKostPrijs = 0) or(PrdOcsArtPartijGid is null) then ArtKostprijsEx else ArtPartijKostprijsEx end if ) / ArtPrijsPer,
                      0.0),
               @_AantalDecimalenValuta))              as BedragUitval
  from tabProductieOrderComponent
    inner join tabProductieOrderComponentSpec on ( PrdOcsPrdOcGid = PrdOcGid )
    inner join tabArtikel                     on ( ArtGid = PrdOcArtGid )
    left outer join tabArtikelPartij          on ( ArtPartijGid = PrdOcsArtPartijGid )
  where ( prdOcPrdOkGid = @PrdOkGid )
    and ( ( @IsVerwerkenComponenten <> 0 and PrdOcRegelSoort = 2 )         // artikelen bij verwerken componenten, en/of
          or ( @IsVerwerkenWerkzaamheden <> 0 and PrdOcRegelSoort = 1 ) )  // tarieven bij verwerken werkzaamheden / productiekosten
  group by  PrdOcGid,
            PrdOcRegelSoort,
            PrdOcArtGid,
            PrdOcsMagGid,
            PrdOcsLocGid,
            PrdOcsArtPartijGid,
            PrdOcsArtSerieGid,
            ArtOpbrGrpGid
  having  (isnull(Aantal,0) <> 0 or isnull(AantalUitval,0) <> 0);

  // **************************************************
  // Resterende componenten (zonder specificatieregels)
  // **************************************************
  insert into tmpProductieOrderVerwerkPlatgeslagen(
    tmpPrdVpSessieNr,
    tmpPrdVpIsComponent,
    tmpPrdVpCompEindpGid,
    tmpPrdVpRegelSoort,
    tmpPrdVpIsErbij,
    tmpPrdVpArtGid,
    tmpPrdVpMagGid,
    tmpPrdVpLocGid,
    tmpPrdVpArtPartijGid,
    tmpPrdVpArtSerieGid,
    tmpPrdVpOpbrGrpGid,
    tmpPrdVpAantal,
    tmpPrdVpBedrag,
    tmpPrdVpAantalUitval,
    tmpPrdVpBedragUitval)
  /* restant van de componentregel zelf */
  select  @SessieNummer,
          1,
          PrdOcGid,
          PrdOcRegelSoort,
          0,                    // IsErbij = 0, want het gaat van de voorraad AF
          PrdOcArtGid,
          PrdOcMagGid,
          PrdOcLocGid,
          PrdOcArtPartijGid,
          null,                 // serienummerGid
          ArtOpbrGrpGid,
          Sum( PrdOcAantalDezeVerwerking - isnull( (  select sum(PrdOcsAantalDezeVerwerking)
                                                      from tabProductieOrderComponentSpec
                                                      where PrdOcsPrdOcGid = PrdOcGid ) ,
                                                      0  ) )                                    as Aantal,
          Sum( Round( IsNull( ( if(ArtIsPartijAparteKostPrijs = 0) or(PrdOcArtPartijGid is null) then ArtKostprijsEx else ArtPartijKostprijsEx end if ) * // kostprijs excl. BTW MAAL
                              ( PrdOcAantalDezeVerwerking - isnull( ( select sum(PrdOcsAantalDezeVerwerking)                                              // Aantal
                                                                      from tabProductieOrderComponentSpec
                                                                      where PrdOcsPrdOcGid = PrdOcGid),
                                                                    0 ) ) / ArtPrijsPer,                                                                  // DELEN door aantal waarvoor prijs geldt
                              0.0),
                      @_AantalDecimalenValuta )  )                                              as Bedrag,                                                // afgerond op aantal decimalen
          Sum( PrdOcAantalUitvalInDezeVerwerking - isnull(  ( select sum(PrdOcsAantalUitvalInDezeVerwerking)
                                                              from tabProductieOrderComponentSpec
                                                              where PrdOcsPrdOcGid = PrdOcGid),
                                                            0) )                                as AantalUitval,
          Sum( Round( IsNull( ( if(ArtIsPartijAparteKostPrijs = 0) or(PrdOcArtPartijGid is null) then ArtKostprijsEx else ArtPartijKostprijsEx end if ) * // kostprijs excl.BTW MAAL
                              (PrdOcAantalUitvalInDezeVerwerking - isnull(  ( select sum(PrdOcsAantalUitvalInDezeVerwerking)                              // Aantal Uitval
                                                                              from tabProductieOrderComponentSpec
                                                                              where PrdOcsPrdOcGid = PrdOcGid),
                                                                            0) ) / ArtPrijsPer,                                                           // DELEN door aantal waarvoor prijs geldt
                              0.0),
                      @_AantalDecimalenValuta))                                                 as BedragUitval                                           // afgerond op aantal decimalen
  from tabProductieOrderComponent
    inner join tabArtikel             on ( ArtGid = PrdOcArtGid )
    left outer join tabArtikelPartij  on ( ArtPartijGid = PrdOcArtPartijGid )
  where ( prdOcPrdOkGid = @PrdOkGid )
    and ( ( @IsVerwerkenComponenten <> 0 and PrdOcRegelSoort = 2 )          // artikelen bij verwerken componenten, en/of
          or ( @IsVerwerkenWerkzaamheden <> 0 and PrdOcRegelSoort = 1 ) )   // tarieven bij verwerken werkzaamheden / productiekosten
  group by  PrdOcGid,
            PrdOcRegelSoort,
            PrdOcArtGid,
            PrdOcMagGid,
            PrdOcLocGid,
            PrdOcArtPartijGid,
            ArtOpbrGrpGid
  having ( isnull(Aantal,0) <> 0 or isnull(AantalUitval,0) <> 0 );
end;



create or replace procedure WebSvcHulpProc_Productieorder_ControleHerwaarderingenVoorraadmutaties(
  in @PrdOkGid                  integer   ,
  in @Boekdatum                 date      ,
  in @IsVerwerkenComponenten    smallint  ,
  in @IsVerwerkenEindproducten  smallint
)
begin
  declare @ControlerenKostprijs       smallint;
  declare @RedenNietMogelijk          nchar(255);
  declare @_BoekDatum                 date;

  // *********************
  // qc = Query Constanten
  // *********************
  declare @qcNEE                      smallint = 0;
  declare @qcJA                       smallint = 1;
  declare @qcKOSTPRIJSNIETCONTROLEREN smallint = 0;

  // instelling uit vaste gegevens artikelen.
  // 0 = geen controle, 1 = waarschuwen, 2 = blokkeren
  set @ControlerenKostprijs = ( select ArtVastDatumControleVrdMutaties from tabArtikelVasteGegevens where ArtVastSoort = 2 );

  set @_BoekDatum = isnull(@BoekDatum, now()); // systeemdatum , indien niet ingevuld

  // ****************************************
  // Controle herwaardering Componenten
  // ****************************************
  set @RedenNietMogelijk = null;
  if ( @IsVerwerkenComponenten <> @qcNEE and @ControlerenKostprijs <> @qcKOSTPRIJSNIETCONTROLEREN ) then
    select first _U('kostprijs van een of meerdere componenten wijzigt na de boekdatum van deze verwerking, met als gevolg een verschil tussen de grootboek- en voorraadadministratie m.b.t. de waarde van de voorraad')
      into @RedenNietMogelijk
    from( // Regels (voor als er geen specificatieregels zijn)
          select  PrdOcArtGid       as prdArtGid,
                  PrdOcArtPartijGid as prdPartijGid,
                  null              as prdSerieGid,
                  PrdOcMagGid       as prdMagGid,
                  PrdOcLocGid       as prdLocGid,
                  PrdOcAantalDezeVerwerking - ( select sum(PrdOcsAantalDezeVerwerking)
                                                from tabProductieOrderComponentSpec
                                                where ( PrdOcsPrdOcGid = PrdOcGid ) ) as Aantal
          from tabProductieOrderComponent
          where Aantal <> 0
            and PrdOcPrdOkGid = @PrdOkGid

          union

          // Specificatieregels
          select  PrdOcArtGid                     as prdArtGid,
                  PrdOcsArtPartijGid              as prdPartijGid,
                  PrdOcsArtSerieGid               as prdSerieGid,
                  PrdOcsMagGid                    as prdMagGid,
                  PrdOcsLocGid                    as prdLocGid,
                  sum(PrdOcsAantalDezeVerwerking) as Aantal
          from tabProductieOrderComponent
            inner join tabProductieOrderComponentSpec on  ( PrdOcsPrdOcGid = PrdOcGid )
          where PrdOcPrdOkGid = @PrdOkGid
          group by  prdArtGid,
                    prdPartijGid,
                    prdSerieGid,
                    prdMagGid,
                    prdLocGid
          having Aantal <> 0 ) as PRDAANTALLENPERCOMPONENT
      inner join tabArtikel on(ArtGid = PrdArtGid)
      left outer join tabArtikelPartij on(ArtPartijGid = PrdPartijGid)
      inner join tabPrijsWijzigingsHistorie on  ( PwhArtGid = prdArtGid )
                                                and ( ArtIsPartijRegistreren = 0
                                                      or ArtIsPartijAparteKostPrijs = 0
                                                      or isnull(PwhArtPartijNummer, '' ) = isnull(artPartijNummer, '' ) )
                                                and ( Date(PwhDatum) > @_BoekDatum );
    if @RedenNietMogelijk is not null then
      call Raise(20780, _U('Verwerken'), @RedenNietMogelijk); // (20780) <Actie> niet mogelijk: <reden>.
    end if;
  end if; // @ControlerenKostprijs

  // ****************************************
  // Controle herwaardering Eindproducten
  // ****************************************
  set @RedenNietMogelijk = null;

  if ( @IsVerwerkenEindproducten <> @qcNEE and @ControlerenKostprijs <> @qcKOSTPRIJSNIETCONTROLEREN ) then

    select first _U('kostprijs van een of meerdere eindproducten wijzigt na de boekdatum van deze verwerking, met als gevolg een verschil tussen de grootboek- en voorraadadministratie m.b.t. de waarde van de voorraad')
      into @RedenNietMogelijk
    from (  // Regels (voor als er geen specificatieregels zijn)
            select  PrdOeArtGid         as  prdArtGid
            ,       PrdOeArtPartijGid   as  prdPartijGid
            ,       null                as  prdSerieGid
            ,       PrdOeMagGid         as  prdMagGid
            ,       PrdOeLocGid         as  prdLocGid
            ,       PrdOeAantalDezeVerwerking + PrdOeAantalUitvalInDezeVerwerking - ( select sum(PrdOesAantalDezeVerwerking+PrdOesAantalUitvalInDezeVerwerking)
                                                                                      from tabProductieOrderEindproductSpec
                                                                                      where ( PrdOesPrdOeGid = PrdOeGid)  ) Aantal
            from  tabProductieOrderEindProduct
            where PrdOePrdOkGid = @PrdOkGid
              and Aantal <> 0

            union

            // Specificatieregels
            select  PrdOeArtGid         as  prdArtGid
            ,       PrdOesArtPartijGid  as  prdPartijGid
            ,       PrdOesArtSerieGid   as  prdSerieGid
            ,       PrdOesMagGid        as  prdMagGid
            ,       PrdOesLocGid        as  prdLocGid
            ,       sum( PrdOesAantalDezeVerwerking - PrdOesAantalUitvalInDezeVerwerking ) Aantal
            from tabProductieOrderEindProduct
              inner join tabProductieOrderEindproductSpec on ( PrdOesPrdOeGid = PrdOeGid )
            where   PrdOePrdOkGid = @PrdOkGid
            group by prdArtGid, prdPartijGid, prdSerieGid, prdMagGid, prdLocGid
            having   Aantal <> 0 ) PRDAANTALLENPEREINDPRODUCT
      inner join tabArtikel on ( ArtGid = PrdArtGid )
      left outer join tabArtikelPartij on ( ArtPartijGid = PrdPartijGid )
      left outer join tabBtw on (BtwCode = if ArtIsPartijAparteVerkoopPrijs = 0 then ArtBtwCode else ArtPartijVerkoopBtwCode endif)
      inner join tabPrijsWijzigingsHistorie on ( PwhArtGid = prdArtGid )
                                                and ( ( ArtIsPartijRegistreren = 0 )
                                                      or ( ArtIsPartijAparteKostPrijs = 0 )
                                                      or isnull( PwhArtPartijNummer, '' ) = isnull( artPartijNummer, '' ) )
                                                and ( Date( PwhDatum ) > @_BoekDatum );

    if @RedenNietMogelijk is not null then
      call Raise(20780, _U('Verwerken'), @RedenNietMogelijk); // (20780) <Actie> niet mogelijk: <reden>.
    end if;
  end if;
end;



create or replace procedure WebSvcHulpProc_Productieorder_EindproductenPlatslaanTbvVerwerking(
  in @SessieNummer                integer ,
  in @PrdOkGid                    integer ,
  in @IsVerwerkenEindProducten    smallint
)
begin
  declare @_AantalDecimalenValuta smallint;
  // qc - Query Constanten
  declare @qcNEE                  smallint = 0;

  set @_AantalDecimalenValuta = ( select DecimalenBoeking * 2 from tabvaluta where ValNummer = @@BasisValutaNummer );

  // ****************************************
  // Specificatieregels van eindproducten
  // ****************************************
  insert into tmpProductieOrderVerwerkPlatgeslagen(
    tmpPrdVpSessieNr,
    tmpPrdVpIsComponent,
    tmpPrdVpCompEindpGid,
    tmpPrdVpRegelSoort,
    tmpPrdVpIsErbij,
    tmpPrdVpArtGid,
    tmpPrdVpMagGid,
    tmpPrdVpLocGid,
    tmpPrdVpArtPartijGid,
    tmpPrdVpArtSerieGid,
    tmpPrdVpOpbrGrpGid,
    tmpPrdVpAantal,
    tmpPrdVpBedrag,
    tmpPrdVpAantalUitval,
    tmpPrdVpBedragUitval )
  select  @SessieNummer,
          0,
          PrdOeGid,
          2,                    // een eindproduct is ALTIJD een artikel
          1,                    // IsErbij = 1, want het komt BIJ de voorraad
          PrdOeArtGid,
          PrdOesMagGid,
          PrdOesLocGid,
          PrdOesArtPartijGid,
          PrdOesArtSerieGid,
          ArtOpbrGrpGid,
          sum( PrdOesAantalDezeVerwerking )         as Aantal,
          sum(  round(  isnull( PrdOesAantalDezeVerwerking * ( if ( ArtIsPartijAparteKostPrijs = 0 ) or ( PrdOesArtPartijGid is null ) then ArtKostprijsEx else ArtPartijKostprijsEx end if ) / ArtPrijsPer,
                                0.0),
                        @_AantalDecimalenValuta ) ) as Bedrag,
          sum( PrdOesAantalUitvalInDezeVerwerking ) as AantalUitval,
          sum(  round(  isnull( PrdOesAantalUitvalInDezeVerwerking * ( if ( ArtIsPartijAparteKostPrijs = 0 ) or ( PrdOesArtPartijGid is null ) then ArtKostprijsEx else ArtPartijKostprijsEx end if ) / ArtPrijsPer,
                                0.0),
                        @_AantalDecimalenValuta ) ) as BedragUitval
  from tabProductieOrderEindproduct
    inner join tabProductieOrderEindproductSpec on  ( PrdOesPrdOeGid = PrdOeGid )
    inner join tabArtikel                       on  ( ArtGid = PrdOeArtGid  )
    left outer join tabArtikelPartij            on  ( ArtPartijGid = PrdOesArtPartijGid )
  where ( prdOePrdOkGid = @PrdOkGid )
    and ( @IsVerwerkenEindProducten <> @qcNEE )
  group by  PrdOeGid,
            PrdOeArtGid,
            PrdOesMagGid,
            PrdOesLocGid,
            PrdOesArtPartijGid,
            PrdOesArtSerieGid,
            ArtOpbrGrpGid
  having ( isnull( Aantal, 0 ) <> 0 or isnull( AantalUitval, 0 ) <> 0 );

  // **************************************************
  // Resterende componenten (zonder specificatieregels)
  // **************************************************
  insert into tmpProductieOrderVerwerkPlatgeslagen(
    tmpPrdVpSessieNr,
    tmpPrdVpIsComponent,
    tmpPrdVpCompEindpGid,
    tmpPrdVpRegelSoort,
    tmpPrdVpIsErbij,
    tmpPrdVpArtGid,
    tmpPrdVpMagGid,
    tmpPrdVpLocGid,
    tmpPrdVpArtPartijGid,
    tmpPrdVpArtSerieGid,
    tmpPrdVpOpbrGrpGid,
    tmpPrdVpAantal,
    tmpPrdVpBedrag,
    tmpPrdVpAantalUitval,
    tmpPrdVpBedragUitval)
  // restant van de eindproductregel zelf
  select  @SessieNummer,
          0,
          PrdOeGid,
          2,                    // een eindproduct is ALTIJD een artikel
          0,                    // IsErbij = 1, want het komt BIJ de voorraad
          PrdOeArtGid,
          PrdOeMagGid,
          PrdOeLocGid,
          PrdOeArtPartijGid,
          null,                 // Serienummer
          ArtOpbrGrpGid,
          sum( PrdOeAantalDezeVerwerking - isnull( (  select sum( PrdOesAantalDezeVerwerking )
                                                      from tabProductieOrderEindproductSpec
                                                      where PrdOesPrdOeGid = PrdOeGid ),
                                                   0 ) )                                                        as Aantal,
          sum( round( isnull( ( if ( ArtIsPartijAparteKostPrijs = 0 ) or ( PrdOeArtPartijGid is null ) then ArtKostprijsEx else ArtPartijKostprijsEx end if ) * // Kostprijs excl BTW MAAL
                                ( PrdOeAantalDezeVerwerking - isnull( ( select sum( PrdOesAantalDezeVerwerking )                                                // Aantal
                                                                        from tabProductieOrderEindproductSpec
                                                                        where PrdOesPrdOeGid = PrdOeGid ), 0 ) ) / ArtPrijsPer,                                 // DELEN door aantal waarvoor prijs geldt
                               0.0 ),
                      @_AantalDecimalenValuta ) )                                                               as Bedrag,                                      // afgerond op aantal decimalen
          sum( PrdOeAantalUitvalInDezeVerwerking - isnull(  ( select sum( PrdOesAantalUitvalInDezeVerwerking )
                                                              from tabProductieOrderEindproductSpec
                                                              where PrdOesPrdOeGid = PrdOeGid ),
                                                            0) )                                                as AantalUitval,
          sum( round( isnull( ( if ( ArtIsPartijAparteKostPrijs = 0 ) or ( PrdOeArtPartijGid is null ) then ArtKostprijsEx else ArtPartijKostprijsEx end if ) * // Kostprijs excl BTW MAAL
                                ( PrdOeAantalUitvalInDezeVerwerking - isnull( ( select sum(PrdOesAantalUitvalInDezeVerwerking)                                  // Aantal
                                                                                from tabProductieOrderEindproductSpec
                                                                                where PrdOesPrdOeGid = PrdOeGid ), 0 ) ) / ArtPrijsPer,                         // DELEN door aantal waarvoor prijs geldt
                               0.0),
                      @_AantalDecimalenValuta ) )                                                               as BedragUitval                                 // afgerond op aantal decimalen
  from tabProductieOrderEindproduct
    inner join tabArtikel             on  ( ArtGid = PrdOeArtGid )
    left outer join tabArtikelPartij  on  ( ArtPartijGid = PrdOeArtPartijGid )
    where ( prdOePrdOkGid = @PrdOkGid )
      and ( @IsVerwerkenEindProducten <> @qcNEE )
  group by  PrdOeGid,
            PrdOeArtGid,
            PrdOeMagGid,
            PrdOeLocGid,
            PrdOeArtPartijGid,
            ArtOpbrGrpGid
  having ( isnull( Aantal, 0 ) <> 0 or isnull( AantalUitval, 0 ) <> 0 );

end;



create or replace procedure WebSvcHulpProc_Productieorder_GekoppeldeOrdersInGebruikNemen(
  in @PrdOkGid      integer                   ,
  in @LockUserNaam  nchar(40)   default null  , // null - King 5 zoekt het zelf wel uit...
  in @SpId          integer     default null  , // idem
  in @LoginTime     datetime    default null  ) // idem
begin
  declare @_LockResult  integer;

  for @Cursor as GekoppeldeVerkooporders cursor for
    select distinct OrkNummer as @OrkNummer
    from tabProductieOrderEindProduct
      inner join tabProductieOrderEindproductSpec on ( PrdOesPrdOeGid = PrdOeGid and PrdOesOrrGid is not null ) // er is een koppeling met verkooporder
      inner join tabOrderRegel                    on ( OrrGid = PrdOesOrrGid )
      inner join tabOrderKop                      on ( OrkGid = OrrOrkGid )
    where PrdOePrdOkGid = @PrdOkGid
    order by OrkNummer asc
  for read only
  do
    call WebSvcHulpProc_OrderExclusiefLocken( @OrkNummer, @LockUserNaam, @SpId, @LoginTime );
  end for;

end;



create or replace procedure WebSvcHulpProc_Productieorder_GekoppeldeOrdersVrijgeven(
  in @PrdOkGid      integer                   ,
  in @LockUserNaam  nchar(40)   default null  , // null - King 5 zoekt het zelf wel uit...
  in @SpId          integer     default null  , // idem
  in @LoginTime     datetime    default null  ) // idem
begin
  declare @_LockResult  integer;

  for @Cursor as GekoppeldeVerkoopordersVrijgeven cursor for
    select distinct OrkNummer as @OrkNummer
    from tabProductieOrderEindProduct
      inner join tabProductieOrderEindproductSpec on ( PrdOesPrdOeGid = PrdOeGid and PrdOesOrrGid is not null ) // er is een koppeling met verkooporder
      inner join tabOrderRegel                    on ( OrrGid = PrdOesOrrGid )
      inner join tabOrderKop                      on ( OrkGid = OrrOrkGid )
    where PrdOePrdOkGid = @PrdOkGid
    order by OrkNummer
  for read only
  do
    call WebSvcHulpProc_Order_LockVrijgeven( @OrkNummer, @LockUserNaam, @SpId, @LoginTime );
  end for;

end;



create or replace procedure WebSvcHulpProc_Productieorder_JournaalregelToevoegenInBasisValuta(
  in @JrJpGid          integer       ,
  in @IsCreditBoeking  smallint      ,
  in @JrBedrag         numeric(15,3) ,
  in @JrRksGid         integer       ,
  in @JrReferentie     nchar(40)     ,
  in @OmsJournaalRegel nchar(40)
)
begin
  declare @_StukVolgnr        smallint;
  declare @_JrReferentie      nchar(40);
  declare @_OmsJournaalRegel  nchar(40);

  set @_StukVolgnr        = isnull( (select max(StukVolgnr) from tabJournaalRegel where JrJpGID = @JrJpGid), 0) + 1;

  set @_OmsJournaalRegel  = isnull( @OmsJournaalRegel, '' );
  set @_JrReferentie      = isnull( @JrReferentie, '' );

  if isnull( @JrBedrag , 0.0) <> 0.0 then
    insert into tabJournaalRegel(
      Aantal,
      IsCreditBoeking,
      JrBasisBedrag,
      JrBetalingsKenmerk, JrBjGid, JrBoekdatum, JrFactuurDatum, JrIsViaIncasso,
      JrJpGID,
      JrNummer, JrOspGid, JrPerNr,  JrRarGid,
      JrReferentie,
      JrRksGID,
      JrRksInvoer,
      JrValNummer,
      JrValutaBedrag,
      JrVervalDatum,
      OmsJournaalRegel,
      RegelNummer,
      SoortBoeking,
      StukVolgnr )
    values(
      0,                          // Aantal
      @IsCreditBoeking,
      @JrBedrag,                  // JrBasisBedrag
      '', null, null, null, 0,    // Jrbetalingskenmerk, JrBjGid, JrBoekDatum, JrFactuurdatum, JrIsViaIncasso
      @JrJpGid,
      '0', null, null, null,      // JrNummer, JrOspGid, JrPerNr, JrRarGid
      @_JrReferentie,
      @JrRksGid,
      null,                       // JrRksInvoer
      @@BasisValutaNummer,
      @JrBedrag,                  // JrValutaBedrag
      null,                       // Vervaldatum
      @_OmsJournaalRegel,
      null,                       // RegelNummer
      0,                          // SoortBoeking: 0 = normaal, 1 = cjp tegenrek., 2 = cjp hulprek., 3 = cjp koerswijz., 4 = Herwaardering
      @_StukVolgnr );
  end if;
end;



create or replace procedure WebSvcHulpProc_Productieorder_MaakBoekingenBestandTbvVerwerking(
  in @SessieNummer                integer ,
  in @IsVerwerkenComponenten      smallint,
  in @IsVerwerkenWerkzaamheden    smallint,
  in @IsVerwerkenEindproducten    smallint
)
begin
  // Paragrefen t.b.v. Productie
  declare @ParagraafSoortVoorraad               integer = 50;
  declare @ParagraafSoortDekkingProductieKosten integer = 230;
  declare @ParagraafSoortUitvalProductie        integer = 240;

  // Boekingen voorbereiden per opbrengstgroep en verwerksoort
  // Er zijn deze verschillende soorten regels om te boeken (tmpPrdVbSoortRegel)
  // 0 = Voorraadboeking componenten
  // 1 = Dekking productiekosten
  // 2 = Voorraadboeking eindproducten
  // 3 = Uitval componenten / productiekosten >> DEBET-boeking (DEBET -deel NEGATIEF - Kostprijs productie in bewerking)
  // 4 = Uitval eindproducten

  for @Cursor as Cursor_OpbrengstgroepenTeVerwerken cursor for
    select  OpbrGrpGid                as @OpbrGrpGid,
            OpbrGrpNummer             as @OpbrGrpNummer,
            VERWERKSOORTEN.SoortRegel as @SoortTeVerwerken
    from tmpProductieOrderVerwerkPlatgeslagen
      inner join tabArtikel         on  (ArtGid = tmpPrdVpArtGid)
      inner join tabOpbrengstGroep  on  (OpbrGrpGid = ArtOpbrGrpGid)
      cross apply (select 0 as SoortRegel from dummy where @IsVerwerkenComponenten = 1                      // 0 = Voorraadboeking componenten
                   union
                   select 1 as SoortRegel from dummy where @IsVerwerkenWerkzaamheden = 1                    // 1 = Dekking productiekosten
                   union
                   select 2 as SoortRegel from dummy where @IsVerwerkenEindproducten = 1) as VERWERKSOORTEN // 2 = Voorraadboeking eindproducten
    where tmpPrdVpSessieNr = @SessieNummer
    group by OpbrGrpNummer,
             OpbrGrpGid,
             VERWERKSOORTEN.SoortRegel
    order by VERWERKSOORTEN.SoortRegel asc, OpbrGrpNummer asc
  for read only
  do

    insert into tmpProductieOrderVerwerkBoekingen(
      tmpPrdVbSessieNr,
      tmpPrdVbSoortRegel,
      tmpPrdVbOpbrGrpGid,
      tmpPrdVbParSoort,
      tmpPrdVbIsCreditBoeking,
      tmpPrdVbBedrag )
    select  @SessieNummer,
            @SoortTeVerwerken As SoortRegel,  // 0 = Voorraadboeking componenten   = CREDIT-boeking (DEBET- deel - Kostprijs productie in bewerking)
                                              // 1 = Dekking productiekosten       = CREDIT-boeking (DEBET- deel - kostprijs productie in bewerking)
                                              // 2 = Voorraadboeking eindproducten = DEBET- boeking (CREDIT-deel - Opbrengst productie in bewerking)
            @OpbrGrpGid, // Opbrengstgroep
            case @SoortTeVerwerken
              when 0 then @ParagraafSoortVoorraad   // voor componenten
              when 1 then @ParagraafSoortDekkingProductieKosten
              when 2 then @ParagraafSoortVoorraad   // voor eindproducten
            end case,    // Paragraafsoort
            case @SoortTeVerwerken
              when 0 then 1 // Voorraad componenten DUS is credit boeking
              when 1 then 1 // Dekking productiekosten DUS is credit boeking
              when 2 then 0 // Voorraad eindproducten DUS is debet
            end case,    // IsCreditBoeking
            isnull(sum(tmpPrdVpBedrag - ( if SoortRegel = 2 then tmpPrdVpBedragUitval else 0 end if ) ),0) as Bedrag
    from tmpProductieOrderVerwerkPlatgeslagen
    where (tmpPrdVpSessieNr = @SessieNummer)
      and (tmpPrdVpRegelSoort = ( case @SoortTeVerwerken
                                    when 0 then 2             // VoorraadComponenten DUS artikelen
                                    when 1 then 1             // DekkingComponenten DUS tarieven
                                    when 2 then 2             // VoorraadEindproducten DUS artikelen
                                   end case))
      and(tmpPrdVpIsErbij = ( case @SoortTeVerwerken
                                when 2 then 1                 // Eindproducten DUS erbij */
                                else 0                        // Componenten werkzaamheden of uitval DUS eraf
                              end case ))
      and(tmpPrdVpIsComponent = ( case @SoortTeVerwerken
                                    when 0 then 1             // VoorraadComponenten DUS artikelen
                                    when 1 then 1             // DekkingComponenten DUS tarieven
                                    when 2 then 0             // VoorraadEindproducten DUS artikelen
                                  end case ))
      and(tmpPrdVpOpbrGrpGid = @OpbrGrpGid)
    //group by SoortRegel
    having Bedrag <> 0

    union all
    // Uitval van zelfde soort regel ook boeken
    select  @SessieNummer,
            if @SoortTeVerwerken = 2 then
              4     // 4 = Uitval eindproducten = DEBET boeking
            else
              3     // 3 = Uitval = DEBET-boeking (DEBET -deel NEGATIEF - Kostprijs productie in bewerking)
            end if as SoortRegel,
            @OpbrGrpGid,                    // Opbrengstgroep
            @ParagraafSoortUitvalProductie, // Paragraafsoort
            0 as IsCreditBoeking,           // Uitval is altijd debet (zowel componenten als eindproducten)
            isnull(sum(tmpPrdVpBedragUitval),0) as Bedrag
    from tmpProductieOrderVerwerkPlatgeslagen
    where (tmpPrdVpSessieNr = @SessieNummer)
      and (tmpPrdVpRegelSoort = ( case @SoortTeVerwerken
                                    when 0 then 2             // VoorraadComponenten DUS artikelen
                                    when 1 then 1             // DekkingComponenten DUS tarieven
                                    when 2 then 2             // VoorraadEindproducten DUS artikelen
                                  end case ))
      and (tmpPrdVpIsComponent = (  case @SoortTeVerwerken
                                      when 0 then 1           // VoorraadComponenten DUS artikelen
                                      when 1 then 1           // DekkingComponenten DUS tarieven
                                      when 2 then 0           // VoorraadEindproducten DUS artikelen
                                    end case))
      and (tmpPrdVpIsErbij = (  case @SoortTeVerwerken
                                  when 2 then 1               // Eindproducten DUS erbij
                                  else 0                      // Componenten, werkzaamheden of uitval DUS eraf
                                end case ))
      and (tmpPrdVpOpbrGrpGid = @OpbrGrpGid)
    //group by SoortRegel
    having Bedrag <> 0;

  end for;
end;



create or replace procedure WebSvcHulpProc_Productieorder_MaakVoorraadMutatiesComponenten(
  in @PrdOkGid                  integer ,
  in @JpGid                     integer ,
  in @MutatieDatum              date    ,
  in @ComponentenAfboeken       integer
)
begin
  declare @_VrdMutArtGid  integer ;
  declare @_VrdMutGid     integer ;
  declare @_PrdOkNummer   numeric(10,0) ;

  // qc - Query Constanten
  declare @qcNEE                    smallint = 0;
  declare @qcVRDMUTSOORTCOMPONENT   smallint = 9;


  set @_PrdOkNummer = ( select PrdOkNummer from tabProductieOrderKop where PrdOkGid = @PrdOkGid );
  set @_VrdMutArtGid = 0;

  for @Cursor as LusVoorraadMutatieComponenten cursor for
    select  PRDAANTALLENPERARTIKEL.prdArtGid    as  @prdArtGid,
            PRDAANTALLENPERARTIKEL.prdPartijGid as  @prdPartijGid,
            PRDAANTALLENPERARTIKEL.prdSerieGid  as  @prdSerieGid,
            PRDAANTALLENPERARTIKEL.prdMagGid    as  @prdMagGid,
            PRDAANTALLENPERARTIKEL.prdLocGid    as  @prdLocGid,
            sum(PRDAANTALLENPERARTIKEL.Aantal)  as  @prdAantal,
            case ArtIsPartijAparteKostPrijs
              when 0 then ArtKostprijsEx
              else ArtPartijKostprijsEx
            end case                            as  @Kostprijs,
            case ArtIsPartijAparteVerkoopPrijs
              when 0 then round(ArtVerkprijs/(if ArtVerkprijsIsIncl = 0 then 1 else 1+(BtwPercentage/100) end if),2)
              else round(ArtPartijVerkoopPrijs/(if ArtPartijVerkoopPrijsIsIncl = 0 then 1 else 1+(BtwPercentage/100) end if),2)
            end case                            as @Verkoopprijs,
            ArtPrijsPer                         as @PrijsPer,
            ArtSerieNrRegistreren               as @ArtSerieNrRegistreren,
            ArtSerieNummer                      as @ArtSerieNummer,
            ArtPartijNummer                     as @ArtPartijNummer
    from  ( // Regels (voor als er geen specificatieregels zijn)
            select PrdOcArtGid                  as prdArtGid,
                    PrdOcArtPartijGid           as prdPartijGid,
                    null                        as prdSerieGid,
                    PrdOcMagGid                 as prdMagGid,
                    PrdOcLocGid                 as prdLocGid,
                    PrdOcAantalDezeVerwerking-(select sum(PrdOcsAantalDezeVerwerking) from tabProductieOrderComponentSpec where(PrdOcsPrdOcGid = PrdOcGid)) as Aantal
            from tabProductieOrderComponent
            where PrdOcPrdOkGid = @PrdOkGid
              and Aantal <> 0
              and @ComponentenAfboeken <> @qcNEE  // alleen voorraadmutaties mits componenten afboeken van toepassing.

            union

            // Specificatieregels
            select PrdOcArtGid                  as prdArtGid,
              PrdOcsArtPartijGid                as prdPartijGid,
              PrdOcsArtSerieGid                 as prdSerieGid,
              PrdOcsMagGid                      as prdMagGid,
              PrdOcsLocGid                      as prdLocGid,
              sum(PrdOcsAantalDezeVerwerking)   as Aantal
            from tabProductieOrderComponent
              join tabProductieOrderComponentSpec on  ( PrdOcsPrdOcGid = PrdOcGid )
            where PrdOcPrdOkGid = @PrdOkGid
              and @ComponentenAfboeken <> @qcNEE  // alleen voorraadmutaties mits componenten afboeken van toepassing.
            group by  prdArtGid,
                      prdPartijGid,
                      prdSerieGid,
                      prdMagGid,
                      prdLocGid
            having Aantal <> 0  ) as  PRDAANTALLENPERARTIKEL
    inner join tabArtikel                 on  ( ArtGid = PRDAANTALLENPERARTIKEL.PrdArtGid )
    left outer join tabArtikelPartij      on  ( ArtPartijGid = PRDAANTALLENPERARTIKEL.PrdPartijGid )
    left outer join tabArtikelSerieNummer on  ( ArtSerieGid = PRDAANTALLENPERARTIKEL.prdSerieGid )
    left outer join tabBtw                on  ( BtwCode = if ArtIsPartijAparteVerkoopPrijs = 0 then ArtBtwCode else ArtPartijVerkoopBtwCode end if )
    group by  PRDAANTALLENPERARTIKEL.prdArtGid,
              PRDAANTALLENPERARTIKEL.prdPartijGid,
              PRDAANTALLENPERARTIKEL.prdSerieGid,
              PRDAANTALLENPERARTIKEL.prdMagGid,
              PRDAANTALLENPERARTIKEL.prdLocGid,
              ArtIsPartijAparteKostPrijs,
              ArtKostprijsEx,
              ArtPartijKostprijsEx,
              ArtIsPartijAparteVerkoopPrijs,
              ArtVerkprijsIsIncl,
              ArtVerkprijs,
              ArtPartijVerkoopPrijs,
              ArtPartijVerkoopPrijsIsIncl,
              ArtPrijsPer,
              ArtSerieNrRegistreren,
              BtwPercentage,
              ArtPartijNummer,
              ArtSerieNummer
    order by  prdArtGid asc,
              prdPartijGid asc,
              prdSerieGid asc,
              prdMagGid asc,
              prdLocGid asc
  for read only
  do
    // een relgel per artikel
    insert into tabVoorraadMutatie  (
      VrdMutArtGid, VrdMutAantal, VrdMutDatum,    VrdMutJpGid,  VrdMutSoort,              VrdMutOrderBestelNr,    VrdMutValNummer,      VrdMutPrijsInBasis, VrdMutPrijsInValuta,  VrdMutGeprijsdPer  )
    select
      @prdArtGid,   -@prdAantal,  @MutatieDatum,  @JpGid,       @qcVRDMUTSOORTCOMPONENT,  string(@_PrdOkNummer),  @@BasisValutaNummer,  @Kostprijs,         @Kostprijs,           @PrijsPer
    from dummy
    where @_VrdMutArtGid <> @prdArtGid;                                               // Bij elk nieuw artikelnummer een nieuwe voorraadmutatie
    select @@Identity into @_VrdMutGid from dummy where @_VrdMutArtGid <> @prdArtGid; // Gid opslaan als er ook echt een record is toegevoegd

    insert into tabVoorraadMutatieLocatieSerie(
      VrdMutLocVrdMutGid, VrdMutLocAantal,  VrdMutLocMagGid,  VrdMutLocLocGid,
      VrdMutLocPartijNummer,
      VrdMutLocSerieNummer )
    select
      @_VrdMutGid,        -@prdAantal,      @prdMagGid,       @prdLocGid,
      case
        when @ArtSerieNrRegistreren = 0       then @artPartijNummer // Niet serienummer registrerend, dan gewoon partij as is overnemen,
        when isnull(@artPartijNummer,'') = '' then '(Standaard)'    // Wel serienummer registrerend, maar geen partijnummer? dan (Standaard)
        else @artPartijNummer                                       // Bij serienummer is er wel een (geldige) partij
      end case,
      @ArtSerieNummer
    from dummy;

    // Bijhouden wat laatst bijgewerkte artikel is.
    set @_VrdMutArtGid = @prdArtGid;
  end for;

end;



create or replace procedure WebSvcHulpProc_Productieorder_MaakVoorraadMutatiesEindproducten(
  in @PrdOkGid integer,
  in @JpGid integer,
  in @MutatieDatum date,
  in @EindproductenOpboeken integer
)
begin
  declare @_VrdMutArtGid integer = 0;
  declare @_VrdMutGid integer ;
  declare @_PrdOkNummer numeric(10,0) ;

  // qc - Query Constanten
  declare _qcNEE smallint = 0;
  declare _qcJA smallint = 1;
  declare _qcVRDMUTSOORTEINDPRODUCT smallint = 10;

  set @_PrdOkNummer = (select PrdOkNummer from tabProductieOrderKop where PrdOkGid = @PrdOkGid );

  // Het gaat hier niet alleen om voorraadmutaties,
  // bij gekoppelde orderregels worden ook orderrgels leverbaar gemaakt
  // Een partij krijgt tevens een productiedatum.
  for @Cursor as LusVoorraadMutatieEindproducten cursor for
    select  PRDAANTALLENPERARTIKEL.prdArtGid    as @prdArtGid,
            PRDAANTALLENPERARTIKEL.prdPartijGid as @prdPartijGid,
            PRDAANTALLENPERARTIKEL.prdSerieGid  as @prdSerieGid,
            PRDAANTALLENPERARTIKEL.prdMagGid    as @prdMagGid,
            PRDAANTALLENPERARTIKEL.prdLocGid    as @prdLocGid,
            PRDAANTALLENPERARTIKEL.prdOesGid    as @prdOesGid,
            PRDAANTALLENPERARTIKEL.prdOesOrrGid as @prdOesOrrGid,
            sum(Aantal)                         as @prdAantal,
            case ArtIsPartijAparteKostPrijs
              when 0 then ArtKostprijsEx
              else ArtPartijKostprijsEx
            end case                            as @Kostprijs,
            case ArtIsPartijAparteVerkoopPrijs
              when 0 then round( ArtVerkprijs / ( if ArtVerkprijsIsIncl = 0 then 1 else 1 + ( BtwPercentage / 100 ) end if ), 2 )
              else round( ArtPartijVerkoopPrijs / ( if ArtPartijVerkoopPrijsIsIncl = 0 then 1 else 1 + ( BtwPercentage / 100 ) end if ), 2 )
            end case                            as @Verkoopprijs,
            ArtPrijsPer                         as @PrijsPer,
            ArtSerieNrRegistreren               as @ArtSerieNrRegistreren,
            ArtSerieNummer                      as @ArtSerieNummer,
            ArtPartijNummer                     as @ArtPartijNummer
    from  ( // Regels (voor als er geen specificatieregels zijn)
            select  PrdOeArtGid           as prdArtGid,
                    PrdOeArtPartijGid     as prdPartijGid,
                    null                  as prdSerieGid,
                    PrdOeMagGid           as prdMagGid,
                    PrdOeLocGid           as prdLocGid,
                    null                  as prdOesGid,
                    null                  as PrdOesOrrGid,
                    PrdOeAantalDezeVerwerking + PrdOeAantalUitvalInDezeVerwerking - ( select sum( PrdOesAantalDezeVerwerking+PrdOesAantalUitvalInDezeVerwerking )
                                                                                      from tabProductieOrderEindproductSpec
                                                                                      where(PrdOesPrdOeGid = PrdOeGid ) ) as Aantal
            from tabProductieOrderEindProduct
            where PrdOePrdOkGid = @PrdOkGid
              and Aantal <> 0
              and @EindproductenOpboeken <> _qcNEE

            union
            // Specificatieregels
            select  PrdOeArtGid                                                             as prdArtGid,
                    PrdOesArtPartijGid                                                      as  prdPartijGid,
                    PrdOesArtSerieGid                                                       as prdSerieGid,
                    coalesce( ( select orrMagGid from tabOrderRegel where orrGid = PrdOesOrrGid and PrdOesOrrGid is not null ), // magazijn van orderregel indien gekoppeld aan eindproduct, ...
                              PrdOesMagGid,                                                                 // of magazijn uit specificatieregel
                              PrdOeMagGid )                                                 as prdMagGid,   // en anders bij eindproduct zelf.
                    if ( PrdOesOrrGid is not null ) or ( PrdOesLocGid is null ) then
                      isnull( ( select ArtMagDefaultLocGid from tabArtikelMagazijn where ArtMagArtGid = prdArtGid and ArtMagMagGid = prdMagGid ),
                              ( select LocGid from tabLocatie where locMagGid = prdMagGid and LocNaam = '(Standaard)' ) )
                    else
                      PrdOesLocGid
                    end if                                                                  as prdLocGid,
                    prdOesGid,
                    PrdOesOrrGid,
                    sum( PrdOesAantalDezeVerwerking - PrdOesAantalUitvalInDezeVerwerking )  as Aantal
            from tabProductieOrderEindProduct
              inner join tabProductieOrderEindproductSpec on(PrdOesPrdOeGid = PrdOeGid)
            where PrdOePrdOkGid = @PrdOkGid
              and @EindproductenOpboeken <> _qcNEE
            group by  prdArtGid,
                      prdPartijGid,
                      prdSerieGid,
                      prdMagGid,
                      prdLocGid,
                      prdOesGid,
                      prdOesOrrGid
            having Aantal <> 0 ) as PRDAANTALLENPERARTIKEL
      inner join tabArtikel on (ArtGid = PRDAANTALLENPERARTIKEL.PrdArtGid)
      left outer join tabArtikelPartij on (ArtPartijGid = PRDAANTALLENPERARTIKEL.PrdPartijGid)
      left outer join tabArtikelSerieNummer on (ArtSerieGid = PRDAANTALLENPERARTIKEL.prdSerieGid)
      left outer join tabBtw on (BtwCode = (if ArtIsPartijAparteVerkoopPrijs = 0 then ArtBtwCode else ArtPartijVerkoopBtwCode end if))
    group by  PRDAANTALLENPERARTIKEL.prdArtGid,
              PRDAANTALLENPERARTIKEL.prdPartijGid,
              PRDAANTALLENPERARTIKEL.prdSerieGid,
              PRDAANTALLENPERARTIKEL.prdMagGid,
              PRDAANTALLENPERARTIKEL.prdLocGid,
              PRDAANTALLENPERARTIKEL.prdOesGid,
              PRDAANTALLENPERARTIKEL.prdOesOrrGid,
              ArtIsPartijAparteKostPrijs,
              ArtKostprijsEx,
              ArtPartijKostprijsEx,
              ArtIsPartijAparteVerkoopPrijs,
              ArtVerkprijsIsIncl,
              ArtVerkprijs,
              ArtPartijVerkoopPrijs,
              ArtPartijVerkoopPrijsIsIncl,
              ArtPrijsPer,
              ArtSerieNrRegistreren,
              BtwPercentage,
              ArtPartijNummer,
              ArtSerieNummer
    order by  PRDAANTALLENPERARTIKEL.prdArtGid asc,
              PRDAANTALLENPERARTIKEL.prdPartijGid asc,
              PRDAANTALLENPERARTIKEL.prdSerieGid asc,
              PRDAANTALLENPERARTIKEL.prdMagGid asc,
              PRDAANTALLENPERARTIKEL.prdLocGid asc,
              PRDAANTALLENPERARTIKEL.prdOesGid asc,
              PRDAANTALLENPERARTIKEL.prdOesOrrGid asc
  for read only
  do
    // **********************************************************************
    // Acties volgens regel 945 en verder van oProductieOrderInfo.pas (Delphi)
    // **********************************************************************
    if exists(select 1 from tabLocatie where LocGid = @prdLocGid and LocBlokkade = _qcJA) then
      //Locatie is geblokkeerd voor het plaatsen van artikelen!
      call Raise(20780,_U('Locatie naar gebruiken is'),_U('locatie is geblokkeerd voor het plaatsen van artikelen'));     // (20780) %1! niet mogelijk: %2!
    end if;

    // een regel per artikel, aantal ERBIJ boeken.
    insert into tabVoorraadMutatie(
      VrdMutArtGid,
      VrdMutAantal,
      VrdMutDatum,
      VrdMutJpGid,
      VrdMutSoort,
      VrdMutOrderBestelNr,
      VrdMutValNummer,
      VrdMutPrijsInBasis,
      VrdMutPrijsInValuta,
      VrdMutGeprijsdPer)
    select
      @prdArtGid,
      @prdAantal,
      @MutatieDatum,
      @JpGid,
      _qcVRDMUTSOORTEINDPRODUCT,
      string(@_PrdOkNummer),
      @@BasisValutaNummer,
      @Kostprijs,
      @Kostprijs,
      @PrijsPer
    from dummy
    where @_VrdMutArtGid <> @prdArtGid;                                               // Bij elk nieuw artikelnummer een nieuwe voorraadmutatie
    select @@Identity into @_VrdMutGid from dummy where @_VrdMutArtGid <> @prdArtGid; // Gid opslaan als er ook echt een record is toegevoegd

    // specificatieregel maken
    insert into tabVoorraadMutatieLocatieSerie(
      VrdMutLocVrdMutGid,
      VrdMutLocAantal,
      VrdMutLocMagGid,
      VrdMutLocLocGid,
      VrdMutLocPartijNummer,
      VrdMutLocSerieNummer)
    select
      @_VrdMutGid,
      @prdAantal,
      @prdMagGid,
      @prdLocGid,
      case
        when @ArtSerieNrRegistreren = 0       then @artPartijNummer // Niet serienummer registrerend, dan gewoon partij as is overnemen,
        when isnull(@artPartijNummer,'') = '' then '(Standaard)'    // Wel serienummer registrerend, maar geen partijnummer? dan (Standaard)
        else @artPartijNummer                                       // Bij serienummer is er wel een (geldige) partij
      end case,
      @ArtSerieNummer
    from dummy;

    // Partij een productiedatum geven als die nog niet ingevuld is.
    update tabartikelpartij set ArtPartijDatumProductie = @MutatieDatum where ArtPartijGid = @prdPartijGid and ArtPartijDatumProductie is null;

    // Haal gekoppelde orderregel uit backorder, standaard King 5 stored proc
    // Let op: de stored proc neemt geen orders in gebruik! Dat moet je ergens vooraf al gedaan hebben.
    if @prdOesOrrGid is not null then
      call ProductieOrderEindProductSpecificatieNaarVerkoopOrder( @prdOesGid, @prdOesOrrGid, @prdAantal );
    end if;

    // Bijhouden wat laatst verwerkte artikel is.
    set @_VrdMutArtGid = @prdArtGid;
  end for;
end;



create or replace procedure WebSvcHulpProc_Productieorder_OnvolledigeComponenten(
  in @PrdOkGid  integer)
result(
  SoortRegel                      nchar(20)     ,   // Component, of Eindproduct ... (zie queries)
  RegelNr                         smallint      ,
  ArtCode                         nchar(20)     ,
  ArtOms                          nchar(40)     ,
  ArtAantDecAantallen             smallint      ,
  AantalDezeVerwerking            numeric(15,3) ,
  AantalUitval                    numeric(15,3) ,
  AantalSpecificatieRegels        numeric(15,3) ,
  AantalUitvalSpecificatieRegels  numeric(15,3) ,
  Reden                           nchar(50)     ,
  IsBlokkerendVoorVerwerking      smallint      ,   // 0 = nee, 1 = ja
  SoortControle                   smallint      )   // 10 = aantal, 20 = partij, 30 = serienummer
begin
  // test
  //declare @PrdOkGid integer = 913;
  declare @SoortRegelTekst   long nvarchar;
  declare @AantallenTekst    long nvarchar;
  declare @PartijenTekst     long nvarchar;
  declare @SerieNummersTekst long nvarchar;

  set @SoortRegelTekst   = _A('Component');
  set @AantallenTekst    = _A('Niet alle aantallen (volledig) gespecificeerd.');
  set @PartijenTekst     = _A('Partijnummer(s) niet ingevuld.');
  set @SerieNummersTekst = _A('Serienummer(s) niet ingevuld.');

  // ********************
  // 10 - aantallen
  // ********************
  select
    @SoortRegelTekst                                    as SoortRegel,
    PrdOcRegelNr                                        as RegelNr,
    ArtCode,
    ArtOms,
    ArtAantDecAantallen,
    PrdOcAantalDezeVerwerking                           as AantalDezeVerwerking,
    PrdOcAantalUitvalInDezeVerwerking                   as AantalUitval,
    isnull( ( select sum(PrdOcsAantalDezeVerwerking)
              from tabProductieOrderComponentSpec
              where PrdOcsPrdOcGid = PrdOcGid ),  0 )   as AantalSpecificatieRegels,
    isnull( ( select sum(PrdOcsAantalUitvalInDezeVerwerking)
              from tabProductieOrderComponentSpec
              where PrdOcsPrdOcGid = PrdOcGid), 0 )     as AantalUitvalSpecificatieRegels,
    @AantallenTekst                                     as Reden,
    1                                                   as IsBlokkerendVoorVerwerking,
    10                                                  as SoortControle
  from tabProductieOrderComponent
    join tabArtikel on  (ArtGid = PrdOcArtGid)
  where PrdOcPrdOkGid = @PrdOkGid
    and PrdOcRegelSoort = 2                                       // artikel
    and ( PrdOcAantalDezeVerwerking <> AantalSpecificatieRegels   // aantal in specificatieregels niet hetzelfde als te verwerken
          or AantalUitval <> AantalUitvalSpecificatieRegels )     // Idem voor uitval.

  // ********************
  // 20 - partijen
  // ********************
  union
  select distinct
    @SoortRegelTekst                  as SoortRegel,
    PrdOcRegelNr                      as RegelNr,
    ArtCode,
    ArtOms,
    ArtAantDecAantallen,
    PrdOcAantalDezeVerwerking         as AantalDezeVerwerking,
    null                              as AantalUitval,
    null                              as AantalSpecificatieRegels,
    null                              as AantalUitvalSpecificatieRegels,
    @PartijenTekst                    as Reden,
    1                                 as IsBlokkerendVoorVerwerking,
    20                                as SoortControle

    from tabProductieOrderComponent
      join tabProductieOrderComponentSpec on(PrdOcsPrdOcGid = PrdOcGid) and(PrdOcsAantalDezeVerwerking <> 0)
      join tabArtikel on(ArtGid = PrdOcArtGid)
    where ( PrdOcPrdOkGid = @PrdOkGid )
      and ( PrdOcRegelSoort = 2  )          // Artikel
      and ( ArtIsPartijRegistreren <> 0 )   // die partijregeistrerend is,
      and ( PrdOcsArtPartijGid is null  )   // maar geen partijnummer gespecificeerd

  // ********************
  // 30 - serienummer
  // ********************
  union
  select distinct
    @SoortRegelTekst                  as SoortRegel,
    PrdOcRegelNr                      as RegelNr,
    ArtCode,
    ArtOms,
    ArtAantDecAantallen,
    PrdOcAantalDezeVerwerking         as AantalDezeVerwerking,
    null                              as AantalUitval,
    null                              as AantalSpecificatieRegels,
    null                              as AantalUitvalSpecificatieRegels,
    @SerieNummersTekst                as Reden,
    1                                 as IsBlokkerendVoorVerwerking,
    30                                as SoortControle

  from tabProductieOrderComponent
    join tabProductieOrderComponentSpec on(PrdOcsPrdOcGid = PrdOcGid) and(PrdOcsAantalDezeVerwerking <> 0)
    join tabArtikel on(ArtGid = PrdOcArtGid)
  where ( PrdOcPrdOkGid = @PrdOkGid )
    and ( PrdOcRegelSoort = 2  )          // Artikel
    and ( ArtSerieNrRegistreren <> 0 )    // die serienummer registrerend is,
    and ( PrdOcsArtSerieGid is null  )    // maar geen serienummer gespecificeerd

  order by SoortControle asc; // controle op juistheid regels in specifieke volgorde.
end;



create or replace procedure WebSvcHulpProc_Productieorder_OnvolledigeEindproducten(
  in @PrdOkGid  integer
)
result(
  SoortRegel                      nchar(20)     ,   // 'Component', of 'Eindproduct' ... (zie queries)
  RegelNr                         smallint      ,
  ArtCode                         nchar(20)     ,
  ArtOms                          nchar(40)     ,
  ArtAantDecAantallen             smallint      ,
  AantalDezeVerwerking            numeric(15,3) ,
  AantalUitval                    numeric(15,3) ,
  AantalSpecificatieRegels        numeric(15,3) ,
  AantalUitvalSpecificatieRegels  numeric(15,3) ,
  Reden                           nchar(50)     ,
  IsBlokkerendVoorVerwerking      smallint      ,   // 0 = nee, 1 = ja
  SoortControle                   smallint      ,   // 10 = aantal, 20 = partij, 30 = partij in orderregel, 40 = serienummer
  PartijNummer                    nchar(20)     )
begin
  // test
  //declare @PrdOkGid integer = 1074;
  declare @SoortRegelTekst   long nvarchar;
  declare @AantallenTekst    long nvarchar;
  declare @PartijenTekst     long nvarchar;
  declare @SerieNummersTekst long nvarchar;
  declare @PartijOrderTekst  long nvarchar;

  set @SoortRegelTekst   = _A('Eindproduct');
  set @AantallenTekst    = _A('Niet alle aantallen (volledig) gespecificeerd.');
  set @PartijenTekst     = _A('Partijnummer(s) niet ingevuld.');
  set @SerieNummersTekst = _A('Serienummer(s) niet ingevuld.');
  set @PartijOrderTekst  = _A('Partij komt niet overeen met orderregel.');


  // ********************
  // 10 - aantallen
  // ********************
  select
    @SoortRegelTekst                                    as SoortRegel,
    PrdOeRegelNr                                        as RegelNr,
    ArtCode,
    ArtOms,
    ArtAantDecAantallen,
    PrdOeAantalDezeVerwerking                           as AantalDezeVerwerking,
    PrdOeAantalUitvalInDezeVerwerking                   as AantalUitval,
    isnull( ( select sum(PrdOesAantalDezeVerwerking)
              from tabProductieOrderEindproductSpec
              where PrdOesPrdOeGid = PrdOeGid ), 0 )    as AantalSpecificatieRegels,
    isnull( ( select sum(PrdOesAantalUitvalInDezeVerwerking)
              from tabProductieOrderEindproductSpec
              where PrdOesPrdOeGid = PrdOeGid ), 0 )    as AantalUitvalSpecificatieRegels,
    @AantallenTekst                                     as Reden,
    1                                                   as IsBlokkerendVoorVerwerking,
    10                                                  as SoortControle,
    null                                                as PartijNummer
  from tabProductieOrderEindproduct
    inner join tabArtikel on  ( ArtGid = PrdOeArtGid )
  where PrdOePrdOkGid = @PrdOkGid
    and ( PrdOeAantalDezeVerwerking <> AantalSpecificatieRegels   // aantal in specificatieregels niet hetzelfde als te verwerken
          or AantalUitval <> AantalUitvalSpecificatieRegels )     // Idem voor uitval.

  // ********************
  // 20 - partijen
  // ********************
  union
  select distinct
    @SoortRegelTekst                  as SoortRegel,
    PrdOeRegelNr                      as RegelNr,
    ArtCode,
    ArtOms,
    ArtAantDecAantallen,
    PrdOeAantalDezeVerwerking         as AantalDezeVerwerking,
    null                              as AantalUitval,
    null                              as AantalSpecificatieRegels,
    null                              as AantalUitvalSpecificatieRegels,
    @PartijenTekst                    as Reden,
    1                                 as IsBlokkerendVoorVerwerking,
    20                                as SoortControle,
    null                              as PartijNummer
  from tabProductieOrderEindproduct
    inner join tabProductieOrderEindproductSpec on ( PrdOesPrdOeGid = PrdOeGid ) and ( PrdOesAantalDezeVerwerking <> 0 )
    inner join tabArtikel                       on ( ArtGid = PrdOeArtGid )
  where PrdOePrdOkGid = @PrdOkGid
    and ( ArtIsPartijRegistreren <> 0 )   // is partijregistrerend,
    and ( PrdOesArtPartijGid is null )    // maar geen partij gespecificeerd

  // ********************
  // 30 - partijen in verkooporders
  // ********************
  union
  select distinct
    @SoortRegelTekst                          as SoortRegel,
    PrdOeRegelNr                              as RegelNr,
    ArtCode,
    ArtOms,
    ArtAantDecAantallen,
    PrdOeAantalDezeVerwerking                 as AantalDezeVerwerking,
    null                                      as AantalUitval,
    null                                      as AantalSpecificatieRegels,
    null                                      as AantalUitvalSpecificatieRegels,
     @PartijOrderTekst                        as Reden,
    1                                         as IsBlokkerendVoorVerwerking,
    30                                        as SoortControle,
    ArtPartijNummer                           as PartijNummer
  from tabProductieOrderEindproduct
    inner join tabProductieOrderEindproductSpec   on  ( PrdOesPrdOeGid = PrdOeGid ) and ( PrdOesAantalDezeVerwerking <> 0 )
    inner join tabArtikel                         on  ( ArtGid = PrdOeArtGid )
    inner join tabOrderRegel                      on  ( OrrGid = PrdOesOrrGid )
    left join tabArtikelPartij                    on  ( ArtPartijArtGid = PrdOeArtGid )
  where ( PrdOePrdOkGid = @PrdOkGid )
    and ( ArtIsPartijRegistreren <> 0 )                                                 // is partijregistrerend
    and ( ( ( ArtIsPartijNrBijLeverenVerplicht = 1 )                                    // is partij bij leveren verplicht,
            and ( isNull(PrdOesArtPartijGid,0) <> isNull(OrrArtPartijGid,0) ) )         // dan moet partij bij eindproduct met orderregel overeenkomen
          or  ( ( OrrArtPartijGid is not null ) and ( PrdOesArtPartijGid is not null )  // OF: orderregel bevat een partij en eindproduct ook
                and ( PrdOesArtPartijGid <> OrrArtPartijGid ) )                         // maar ze komen niet overeen
        )

  // ********************
  // 40 - serienummer
  // ********************
  union
  select distinct
    @SoortRegelTekst                          as SoortRegel,
    PrdOeRegelNr                              as RegelNr,
    ArtCode,
    ArtOms,
    ArtAantDecAantallen,
    PrdOeAantalDezeVerwerking                 as AantalDezeVerwerking,
    null                                      as AantalUitval,
    null                                      as AantalSpecificatieRegels,
    null                                      as AantalUitvalSpecificatieRegels,
    @SerieNummersTekst                        as Reden,
    1                                         as IsBlokkerendVoorVerwerking,
    40                                        as SoortControle,
    ArtPartijNummer                           as PartijNummer
  from tabProductieOrderEindproduct
    inner join tabProductieOrderEindproductSpec   on  ( PrdOesPrdOeGid = PrdOeGid ) and ( PrdOesAantalDezeVerwerking <> 0 )
    inner join tabArtikel                         on  ( ArtGid = PrdOeArtGid )
    left join tabArtikelPartij                    on  ( ArtPartijArtGid = PrdOeArtGid )
  where ( PrdOePrdOkGid = @PrdOkGid )
    and ( ArtSerieNrRegistreren <> 0 )    // die serienummer registrerend is,
    and ( PrdOesArtSerieGid is null  )    // maar geen serienummer gespecificeerd,
    and ( ArtSerieNrAanmakenBij <> 1 )    // tenzij 1 = via verkoorder, waarin een serienummer definitief wordt toegewezen.

  // resultset in in specifieke volgorde.
  order by SoortControle asc;
end;



create or replace procedure WebSvcHulpProc_Productieorder_OpenBoekingsgangTbvVerwerking(
  in  @BoekjaarCode   nchar(10)     ,  // verplicht
  in  @BoekgangNummer numeric(10,0) ,  // null = genereer een nummer, nieuw boekingsgang
  in  @Gebruiker      nchar(40)     ,
  in  @Omschrijving   nchar(40)     ,
  out @_BoekGangGid   integer       )
begin
  declare @_BjGid         integer;
  declare @BoekgangBronId smallint = 27;  // 27 = verwerken productie order, 36 = webservices

  // Nieuwe boekingsgang maken als er geen nummer is opgegeven.
  if @BoekgangNummer is null then
    set @_BoekGangGid = ( select BoekGangGid
                          from WebSvcHulpProc_Boekingsgang_Toevoegen(
                                  @BoekjaarCode,
                                  @Gebruiker,
                                  @Omschrijving,
                                  @BoekgangBronId) );
  end if;

  // onderstande zou ook in een aparte stored proc  ( WebSvcProc_Boekingsgang_Wijzigen ) kunnen
  // maar dit is nog erg nieuw en nog niet uitgekristalliseerd.
  // Gedachte bij het onderstaande er kunnen meerdere productieorders in 1 boekingsgang.
  if @BoekgangNummer is not null then
    begin
      declare @bgingebruik  smallint;
      declare @bggebruiker  nchar(40);
      declare @bgbronid     smallint;

      select BoekgangGid,   BoekGangBronId, BoekGangGebruikersnaam, BoekgangInGebruik
        into @_BoekGangGid, @bgbronid,      @bggebruiker,           @bgingebruik
      from  tabBoekingsGang
      where BoekGangNummer = @BoekGangNummer and BoekGangBjGid = @_BjGid;

      if @_BoekGangGid is null then
        call Raise(20720, _U('Boekingsgang')); // (20720) %1 niet gevonden!
      end if;

      if @bgbronid <> @BoekgangBronId then
        call Raise(20701, _U('Boekingsgang is niet voor verwerken van productieorder bedoeld')); // (20701), Ongeldige combinatie: %1!
      end if;

      // als boekingsgang in gebruik is, ben je dan ook jezelf die dat geweest is?
      if @bgingebruik = 1 then
        if isnull(@bggebruiker,'') <> '' and ( @bggebruiker <> @Gebruiker ) then
          call Raise(20741, _U('Boekingsgang t.b.v. verwerking productieorder')); // (20741) %1 is in gebruik!
        end if;
      end if;

      // Dit lijkt overbodig, maar is het niet:
      // achter deze DML statement zit een lock mechanisme.
      // als een andere webservice sessie die boekingsgang in gebruik heeft dan knalt dit eruit?
      // of erger: het is al definitief, en we nemen opnieuw in gebruik...
      update tabBoekingsGang set BoekGangInGebruik = 1, BoekGangGebruikersnaam = @Gebruiker where BoekgangGid = @_BoekGangGid;
    end;
  end if;

  // we hebben een boekingsgang... toch?
  if @_BoekGangGid is null then
    call Raise(20780, _U('Verwerken productieorder'), _U('openen van boekingsgang is mislukt')); // (20780) <Actie> niet mogelijk: <reden>.
  end if;
end;



create or replace procedure WebSvcHulpProc_Productieorder_ResultaatBoekenBijAfsluiten(
  in @Sessienummer              integer   ,
  in @JpGid                     integer   ,
  in @PrdOkGid                  integer   ,
  in @OmsAlleJournaalRegels     nchar(40) default null,
  in @RksGidProductieResultaat  integer   ,
  in @RksGidKostprijs           integer   ,
  in @RksGidOpbrengst           integer   ,
  in @TussenrekeningGebruikt    smallint    // 0 = nee, 1 = ja
)
begin
  declare @_TotaalGeboektKostprijs  numeric(15,3);
  declare @_TotaalGeboektOpbrengst  numeric(15,3);
  declare @_TotaalGeboektUitval     numeric(15,3);
  declare @_PrdOkNummer             integer;
  declare @_StukVolgnr              smallint;
  // qc - Query Constants
  // t.b.v. journaalregels
  declare @qcDEBET                  smallint = 0;
  declare @qcCREDIT                 smallint = 1;

  set @_PrdOkNummer = ( select PrdOkNummer from tabProductieorderKop where PrdOkGid = @PrdOkGid );

  set @_TotaalGeboektKostprijs = (  select sum(Kostprijs)
                                    from (  // Deel dat al is verwerkt
                                            select sum(PrdOcBedragReedsVerwerkt - PrdOcBedragUitvalInReedsVerwerkt)       as Kostprijs
                                            from   tabProductieOrderComponent
                                            where  PrdOcPrdOkGid = @PrdOkGid

                                            union all
                                            // Deel dat nu wordt verwerkt
                                            select sum(tmpPrdVpBedrag - tmpPrdVpBedragUitval)                             as Kostprijs
                                            from   tmpProductieOrderVerwerkPlatgeslagen
                                              inner join tabProductieOrderComponent on ( tmpPrdVpCompEindpGid = PrdOcGid )
                                            where  ( tmpPrdVpIsComponent = 1 ) and ( tmpPrdVpSessieNr = @Sessienummer ) ) TOTAALKOSTPRIJZEN );

  set @_TotaalGeboektOpbrengst = (  select sum(Opbrengst)
                                    from (  // Deel dat al is verwerkt
                                            select sum(PrdOeBedragReedsVerwerkt /*- PrdOeBedragUitvalInReedsVerwerkt*/ )  as Opbrengst
                                            from   tabProductieOrderEindproduct
                                            where  PrdOePrdOkGid = @PrdOkGid

                                            union all
                                            // Deel dat nu wordt verwerkt
                                            select sum(tmpPrdVpBedrag /*- tmpPrdVpBedragUitval*/)                         as Opbrengst
                                            from   tmpProductieOrderVerwerkPlatgeslagen
                                              inner join tabProductieOrderEindproduct on ( tmpPrdVpCompEindpGid = PrdOeGid )
                                            where  ( tmpPrdVpIsComponent = 0 ) and ( tmpPrdVpSessieNr = @Sessienummer ) ) TOTAALOPBRENGSTEN );

  // *******************************************************
  // Als er ooit al eens op een tussenrekening geboekt is,
  // dan moeten we dat weer tegenboeken
  // *******************************************************
  if ( @TussenrekeningGebruikt <> 0 ) then
    // Tegenboeken tussenrekening kostprijs
    if ( isnull( @_TotaalGeboektKostprijs, 0.0 ) <> 0.0 ) then
      call WebSvcHulpProc_Productieorder_JournaalregelToevoegenInBasisValuta( @JpGid, @qcCREDIT, @_TotaalGeboektKostprijs, @RksGidKostprijs, string( @_PrdOkNummer ), @OmsAlleJournaalRegels );
    end if;

    // Tegenboeken tussenrekening opbrengst
    if ( isnull( @_TotaalGeboektOpbrengst, 0.0 ) <> 0.0 ) then
      call WebSvcHulpProc_Productieorder_JournaalregelToevoegenInBasisValuta( @JpGid, @qcDEBET, @_TotaalGeboektOpbrengst, @RksGidOpbrengst, string( @_PrdOkNummer ), @OmsAlleJournaalRegels );
    end if;
  end if;

  // ******************************************************************
  // Uitval per opbrengstgroep apart tegenboeken,
  // op andere zijde dan de oorspronkelijke boekzijde.
  // Uitvalbedrag wordt ook tegengeboekt op productieresultaatrekening!
  // ******************************************************************
  begin
    declare @qcPARAGRAAFSOORTUITVALPRODUCTIE  smallint = 240; // zorg dat dit nummer hetzelfde is als bij het maken van het boekingenbestand
    declare @Referentie                       nchar(40) = '';
    declare @RksGidUitval                     integer;

    set @_TotaalGeboektUitval = 0.0;

    for @Cursor as TegenboekingenUitvalPerObrengstgroep cursor for

      select  tussenOpbrGrpGid                            as @OpbrGrpGid,
              sum(tussenBedrag)                           as @BedragUitval
      from  ( // Gegevens van DEZE VERWERKING uit productieorder lezen
              select tmpPrdVpOpbrGrpGid                       as tussenOpbrGrpGid,
                     sum( tmpPrdVpBedragUitval )              as tussenBedrag
              from tmpProductieOrderVerwerkPlatgeslagen
              where tmpPrdVpSessieNr = @Sessienummer
              group by TussenOpbrGrpGid
                having TussenBedrag <> 0.0

              union all
              // Gegevens van EERDERE VERWERKING (component) rechtstreeks uit productieorder lezen
              select ArtOpbrGrpGId                            as tussenOpbrGrpGid,
                     sum( PrdOcBedragUitvalInReedsVerwerkt )  as tussenBedrag
              from tabProductieorderComponent
                inner join tabArtikel on ( ArtGid = PrdOcArtGid )
              where ( PrdOcPrdOkGid = @PrdOkGid )
                and ( PrdOcRegelSoort = 2 ) // 2 = artikel
              group by TussenOpbrGrpGid
                having TussenBedrag <> 0.0

              union all
              // Gegevens van EERDERE VERWERKING (eindproduct) rechtstreeks uit productieorder lezen
              select ArtOpbrGrpGid                            as tussenOpbrGrpGid,
                     sum( PrdOeBedragUitvalInReedsVerwerkt )  as tussenBedrag
              from   tabProductieorderEindproduct
                inner join tabArtikel on ( ArtGid = PrdOeArtGid )
              where ( PrdOePrdOkGid = @PrdOkGid )
              group by TussenOpbrGrpGid
                having    TussenBedrag <> 0.0  ) TOTAALUITVAL
      group by  tussenOpbrGrpGid
      order by  tussenOpbrGrpGid
    for read only
    do
      set @RksGidUitval = ( select GrpSoortRksGid from tabOpbrengstGroepSoort where GrpSoortGrpGid = @OpbrGrpGid and GrpSoortParSoort = @qcPARAGRAAFSOORTUITVALPRODUCTIE );

      call WebSvcHulpProc_Productieorder_JournaalregelToevoegenInBasisValuta( @JpGid, @qcCREDIT, @BedragUitval, @RksGidUitval, @Referentie, @OmsAlleJournaalRegels );

      // uitval is verlies, vandaar aftrekken/negatief...
      set @_TotaalGeboektUitval = @_TotaalGeboektUitval - @BedragUitval;
    end for;
  end; // uitval

  // *********************************
  // Tot slot resultaat boeken
  // *********************************
  begin
    declare @Referentie nchar(40)     = '';
    declare @Boekzijde  smallint;
    declare @Verschil   numeric(15,3);

    // Opgelet: de berekening van het verschil hangt af van hoe de totale uitval is berekend!
    set @Verschil = @_TotaalGeboektOpbrengst + @_TotaalGeboektUitval - @_TotaalGeboektKostprijs;

    // Alleen boeken als er verschil is.
    if ( @Verschil <> 0.0 ) then

      // Combowaarde bepaalt boekzijde
      select  case DefaultBoekzijde
                when 0 then @qcDEBET                                                            // Debet zijde
                when 1 then @qcCREDIT                                                           // Credit zijde
                else isnull( ( select @qcDEBET from dummy where @Verschil < 0.0 ), @qcCREDIT )  // 2 = Geen voorkeur : altijd invoeren, 3 = Afhankelijk van dagboek
              end case
        into @Boekzijde
      from tabRekeningSchema
      where ( RksGid = @RksGidProductieResultaat );

      // Op basis van Boekzijde het bedrag correct boeken...
      if ( @Boekzijde = @qcDEBET ) then
        call WebSvcHulpProc_Productieorder_JournaalregelToevoegenInBasisValuta( @JpGid, @qcDEBET, -1 * @Verschil, @RksGidProductieResultaat, @Referentie, @OmsAlleJournaalRegels );
      end if;
      if ( @Boekzijde = @qcCREDIT ) then
        call WebSvcHulpProc_Productieorder_JournaalregelToevoegenInBasisValuta( @JpGid, @qcCREDIT, @Verschil, @RksGidProductieResultaat, @Referentie, @OmsAlleJournaalRegels );
      end if;
    end if;
  end; // resultaat

end;



create or replace procedure WebSvcHulpProc_Productieorder_UpdateAantallenBedragen(
  in @SessieNummer                integer   ,
  in @PrdOkGid                    integer   ,
  in @IsVerwerkenComponenten      smallint  ,
  in @IsVerwerkenEindproducten    smallint  ,
  in @IsVerwerkenProductiekosten  smallint  )
begin
  declare @qcNEE smallint = 0;

  if @IsVerwerkenComponenten <> @qcNEE then
    call WebSvcHulpProc_Productieorder_UpdateAantallenBedragenComponenten(@SessieNummer, @PrdOkGid);
  end if;

  if @IsVerwerkenEindproducten <> @qcNEE then
    call WebSvcHulpProc_Productieorder_UpdateAantallenBedragenEindproducten(@SessieNummer, @PrdOkGid);
  end if;

  if @IsVerwerkenProductiekosten <> @qcNEE then
    call WebSvcHulpProc_Productieorder_UpdateAantallenBedragenProductiekosten(@SessieNummer, @PrdOkGid);
  end if;
end;



create or replace procedure WebSvcHulpProc_Productieorder_UpdateAantallenBedragenComponenten(
  in @SessieNummer  integer ,
  in @PrdOkGid      integer
)
begin
  declare @qcREGELSOORTARTIKEL smallint = 2;
  // *********************************************
  // (1) Aantallen in specificatieregels
  // van artikelcomponenten bijwerken
  // *********************************************
  update  tabProductieOrderComponentSpec
    set PrdOcsAantalReedsVerwerkt = isnull( OCSDATA.PrdOcsAantalReedsVerwerkt, 0 ) + isnull( OCSDATA.PrdOcsAantalDezeVerwerking, 0 ),
        PrdOcsAantalDezeVerwerking = 0.0,
        PrdOcsAantalUitvalInReedsVerwerkt = isnull( OCSDATA.PrdOcsAantalUitvalInReedsVerwerkt, 0 ) + isnull( OCSDATA.PrdOcsAantalUitvalInDezeVerwerking, 0 ),
        PrdOcsAantalUitvalInDezeVerwerking = 0.0
  from tabProductieOrderComponentSpec     as OCSDATA
    inner join tabProductieOrderComponent as OCDATA   on  ( OCDATA.PrdOcGid = OCSDATA.PrdOcsPrdOcGid )
  where ( OCDATA.PrdOcPrdOkGid = @PrdOkGid )
    and ( OCDATA.PrdOcRegelSoort = @qcREGELSOORTARTIKEL )
    and ( ( isnull( OCSDATA.PrdOcsAantalDezeVerwerking, 0 ) <> 0 )
          or ( isnull( OCSDATA.PrdOcsAantalUitvalInDezeVerwerking, 0 ) <> 0 ) );

  // *********************************************
  // (2) Aantallen in artikelcomponenten bijwerken
  // *********************************************
  update tabProductieOrderComponent
    set PrdOcAantalReedsVerwerkt = isnull( OCDATA.PrdOcAantalReedsVerwerkt, 0 ) + isnull( OCDATA.PrdOcAantalDezeVerwerking, 0 ),
        PrdOcAantalDezeVerwerking = 0.0,
        PrdOcAantalUitvalInReedsVerwerkt = isnull( OCDATA.PrdOcAantalUitvalInReedsVerwerkt, 0 ) + isnull( OCDATA.PrdOcAantalUitvalInDezeVerwerking, 0 ),
        PrdOcAantalUitvalInDezeVerwerking = 0.0
  from tabProductieOrderComponent as OCDATA
  where ( OCDATA.PrdOcPrdOkGid = @PrdOkGid )
    and ( OCDATA.PrdOcRegelSoort = @qcREGELSOORTARTIKEL )
    and ( ( isnull( OCDATA.PrdOcAantalDezeVerwerking, 0 ) <> 0 )
          or ( isnull( OCDATA.PrdOcAantalUitvalInDezeVerwerking ,0 ) <> 0 ) );
  // *********************************************
  // (3) Bedragen artikelcomponenten bijwerken
  // *********************************************
  update tabProductieOrderComponent
    set PrdOcBedragReedsVerwerkt = PrdOcBedragReedsVerwerkt + isnull( ( select sum(tmpPrdVpBedrag)
                                                                        from tmpProductieOrderVerwerkPlatgeslagen
                                                                        where ( tmpPrdVpIsComponent = 1 )
                                                                          and ( tmpPrdVpSessieNr = @SessieNummer )
                                                                          and ( tmpPrdVpCompEindpGid = PrdOcGid ) )
                                                                    , 0.0),
        PrdOcBedragUitvalInReedsVerwerkt = PrdOcBedragUitvalInReedsVerwerkt + isnull( ( select sum(tmpPrdVpBedragUitval)
                                                                                        from tmpProductieOrderVerwerkPlatgeslagen
                                                                                        where ( tmpPrdVpIsComponent = 1 )
                                                                                        and ( tmpPrdVpSessieNr = @SessieNummer )
                                                                                        and ( tmpPrdVpCompEindpGid = PrdOcGid ) )
                                                                                    , 0.0)
  where PrdOcPrdOkGid = @PrdOkGid
    and ( PrdOcRegelSoort = @qcREGELSOORTARTIKEL );
end;



create or replace procedure WebSvcHulpProc_Productieorder_UpdateAantallenBedragenEindproducten(
  in @SessieNummer  integer,
  in @PrdOkGid      integer
)
begin

  // *********************************************
  // (1) Aantallen in specificatieregels
  // van eindproducten bijwerken
  // *********************************************
  update tabProductieOrderEindproductSpec
    set PrdOesAantalReedsVerwerkt = isnull( PrdOesAantalReedsVerwerkt, 0 ) + isnull( PrdOesAantalDezeVerwerking, 0 ),
        PrdOesAantalDezeVerwerking = 0,
        PrdOesAantalUitvalInReedsVerwerkt = isnull( PrdOesAantalUitvalInReedsVerwerkt, 0 ) + isnull( PrdOesAantalUitvalInDezeVerwerking, 0 ),
        PrdOesAantalUitvalInDezeVerwerking = 0.0
  from  tabProductieOrderEindproductSpec
    inner join tabProductieOrderEindproduct on  ( PrdOeGid = PrdOesPrdOeGid )
  where ( PrdOePrdOkGid = @PrdOkGid )
    and(  ( isnull( PrdOesAantalDezeVerwerking, 0 ) <> 0 ) or ( isnull( PrdOesAantalUitvalInDezeVerwerking, 0 ) <> 0 ) );

  // *********************************************
  // (2) Aantallen in eindproducten zelf bijwerken
  // *********************************************
  update  tabProductieOrderEindproduct
    set PrdOeAantalReedsVerwerkt = isnull(PrdOeAantalReedsVerwerkt,0)+isnull(PrdOeAantalDezeVerwerking,0),
        PrdOeAantalDezeVerwerking = 0.0,
        PrdOeAantalUitvalInReedsVerwerkt = isnull(PrdOeAantalUitvalInReedsVerwerkt,0)+isnull(PrdOeAantalUitvalInDezeVerwerking,0),
        PrdOeAantalUitvalInDezeVerwerking = 0.0
  where ( PrdOePrdOkGid = @PrdOkGid )
    and ( ( isnull( PrdOeAantalDezeVerwerking , 0 ) <> 0 ) or ( isnull( PrdOeAantalUitvalInDezeVerwerking, 0) <> 0 ) );

  // *********************************************
  // (3) Bedragen eindproducten bijwerken
  // *********************************************
  update  tabProductieOrderEindproduct
    set PrdOeBedragReedsVerwerkt = PrdOeBedragReedsVerwerkt + isnull( ( select sum( tmpPrdVpBedrag )
                                                                        from tmpProductieOrderVerwerkPlatgeslagen
                                                                        where ( tmpPrdVpIsComponent = 0 )
                                                                          and ( tmpPrdVpSessieNr = @SessieNummer )
                                                                          and ( tmpPrdVpCompEindpGid = PrdOeGid ) ), 0.0 ),
        PrdOeBedragUitvalInReedsVerwerkt = PrdOeBedragUitvalInReedsVerwerkt + isnull( ( select sum( tmpPrdVpBedragUitval )
                                                                                        from tmpProductieOrderVerwerkPlatgeslagen
                                                                                        where ( tmpPrdVpIsComponent = 0 )
                                                                                          and ( tmpPrdVpSessieNr = @SessieNummer )
                                                                                          and ( tmpPrdVpCompEindpGid = PrdOeGid ) ), 0.0)
  where PrdOePrdOkGid = @PrdOkGid;

end;



create or replace procedure WebSvcHulpProc_Productieorder_UpdateAantallenBedragenProductiekosten(
  in @SessieNummer  integer,
  in @PrdOkGid      integer
)
begin
  declare @qcREGELSOORTTARIEF smallint = 1;

  // *********************************************
  // (1) Aantallen in specificatieregels
  // *********************************************
  update tabProductieOrderComponentSpec
    set PrdOcsAantalReedsVerwerkt = isnull( OCSDATA.PrdOcsAantalReedsVerwerkt, 0 ) + isnull( OCSDATA.PrdOcsAantalDezeVerwerking, 0 ),
        PrdOcsAantalDezeVerwerking = 0.0,
        PrdOcsAantalUitvalInReedsVerwerkt = isnull( OCSDATA.PrdOcsAantalUitvalInReedsVerwerkt, 0 ) + isnull( OCSDATA.PrdOcsAantalUitvalInDezeVerwerking, 0 ),
        PrdOcsAantalUitvalInDezeVerwerking = 0.0
  from tabProductieOrderComponentSpec     as OCSDATA
    inner join tabProductieOrderComponent as OCDATA   on  ( OCDATA.PrdOcGid = OCSDATA.PrdOcsPrdOcGid )
  where ( OCDATA.PrdOcPrdOkGid = @PrdOkGid )
    and ( OCDATA.PrdOcRegelSoort = @qcREGELSOORTTARIEF )
    and ( ( isnull( OCSDATA.PrdOcsAantalDezeVerwerking, 0 ) <> 0 )
          or ( isnull( OCSDATA.PrdOcsAantalUitvalInDezeVerwerking, 0 ) <> 0 ) );

  // *********************************************
  // (2) Aantallen in tariefcomponenten bijwerken
  // *********************************************
  update tabProductieOrderComponent
    set PrdOcAantalReedsVerwerkt = isnull( OCDATA.PrdOcAantalReedsVerwerkt, 0 ) + isnull( OCDATA.PrdOcAantalDezeVerwerking, 0 ),
        PrdOcAantalDezeVerwerking = 0.0,
        PrdOcAantalUitvalInReedsVerwerkt = isnull( OCDATA.PrdOcAantalUitvalInReedsVerwerkt, 0 ) + isnull( OCDATA.PrdOcAantalUitvalInDezeVerwerking, 0 ),
        PrdOcAantalUitvalInDezeVerwerking = 0.0
  from tabProductieOrderComponent as OCDATA
  where ( OCDATA.PrdOcPrdOkGid = @PrdOkGid )
    and ( OCDATA.PrdOcRegelSoort = @qcREGELSOORTTARIEF )
    and ( ( isnull( OCDATA.PrdOcAantalDezeVerwerking, 0 ) <> 0 )
          or ( isnull( OCDATA.PrdOcAantalUitvalInDezeVerwerking ,0 ) <> 0 ) );

  // *********************************************
  // (3) Bedragen tariefcomponenten bijwerken
  // *********************************************
  update tabProductieOrderComponent
    set PrdOcBedragReedsVerwerkt = PrdOcBedragReedsVerwerkt + isnull( ( select sum(tmpPrdVpBedrag)
                                                                        from tmpProductieOrderVerwerkPlatgeslagen
                                                                        where ( tmpPrdVpIsComponent = 1 )
                                                                          and ( tmpPrdVpSessieNr = @SessieNummer )
                                                                          and ( tmpPrdVpCompEindpGid = PrdOcGid ) )
                                                                    , 0.0),
        PrdOcBedragUitvalInReedsVerwerkt = PrdOcBedragUitvalInReedsVerwerkt + isnull( ( select sum(tmpPrdVpBedragUitval)
                                                                                        from tmpProductieOrderVerwerkPlatgeslagen
                                                                                        where ( tmpPrdVpIsComponent = 1 )
                                                                                        and ( tmpPrdVpSessieNr = @SessieNummer )
                                                                                        and ( tmpPrdVpCompEindpGid = PrdOcGid ) )
                                                                                    , 0.0)
  where PrdOcPrdOkGid = @PrdOkGid
    and ( PrdOcRegelSoort = @qcREGELSOORTTARIEF );
end;



create or replace procedure WebSvcHulpProc_Productieorder_UpdateStatusVerwerking(
  in @PrdOkGid              integer   ,
  in @IsVerwerkenAfsluiten  smallint  , // 0 = nee, 1 = ja
  in @BoekDatum             date      )
begin
  // qc - Query Constanten
  declare @qcNEE                smallint = 0;
  declare @qcJA                 smallint = 1;

  // Productieorder op Gereed zetten als het om afsluiten gaat.
  update tabProductieOrderKop set PrdOkStatus = 4 where PrdOkGid = @PrdOkGid and @IsVerwerkenAfsluiten = @qcJA;

  // Niet afsluiten? zet de startdatum als dat nog niet ingevuld is.
  update tabProductieOrderKop set PrdOkProductieStartOp = @BoekDatum where PrdOkGid = @PrdOkGid and PrdOkProductieStartOp is null and @IsVerwerkenAfsluiten = @qcNEE;

  // Wanneer was de laatste (deel-)verwerking?
  update tabProductieOrderKop set PrdOkProductieKlaarOp = @BoekDatum where PrdOkGid = @PrdOkGid;

end;



create or replace procedure WebSvcHulpProc_Productieorder_ValideerJournaalpostgegevens(
  in  @PrdOkGid                     integer   default null,
  in  @Boekdatum                    date      default null,
  in  @Omschrijving                 nchar(40) default null,
  out @_Boekjaarcode                nchar(10) default null,
  out @_BoekstukDatum               date      default null,
  out @_DagBoekCodeProductie        nchar(10) default null,
  out @_JpOmschrijving              nchar(40) default null,
  out @_RksGidResultaat             integer   default null,
  out @_RksGidKostprijsInBewerking  integer   default null,
  out @_RksGidOpbrengstInBewerking  integer   default null
)
begin
  // ******************************
  // BoekDatum
  // ******************************
  begin
    set @_BoekStukDatum = isnull(@BoekDatum, now()); // systeemdatum , indien niet ingevuld

    select Code
     into @_BoekjaarCode
    from tabBoekjaar BJ
      inner join tabPeriode PER on PER.PerBjGid = BJ.BjGid
    where @_BoekStukDatum between PER.BegiNDatum and PER.EindDatum
      and BJ.BjIsGeblokkeerd = 0
      and PER.PerIsgeblokkeerd = 0;

    if @_BoekJaarCode is null then
      call Raise(20700, _U('BoekDatum, er is geen bijbehorend boekjaar en/of periode open')); // (20700) Ongeldige waarde: <Opmerking>
    end if;
  end;

  // ******************************
  // Omschrijving (t.b.v. journaalpost)
  // ******************************
  begin
    declare @Receptcode nchar(20);
    declare @Nummer     nchar(10);  // i.p.v. numeric(10,0)

    select  PrdOkRcptCode,  string(PrdOkNummer)
      into  @Receptcode,    @Nummer
    from tabProductieOrderKop
    where PrdOkGid = @PrdOkGid;

    // Is er geen omschrijving opgegeven, dan overnemen uit vaste gegevens,
    // en eventueel receptcode invullen indien aangegeven
    // let op: er passen maximaal 40 tekens in.
    set @_JpOmschrijving = isnull(trim(@Omschrijving), '');
    if (@_JpOmschrijving = '') then
      set @_JpOmschrijving = ( select RcpvJpOms from tabReceptuurVastegegevens);
      set @_JpOmschrijving = replace( @_JpOmschrijving, '<recept>', @Receptcode );
      set @_JpOmschrijving = replace( @_JpOmschrijving, '<nr>', @Nummer );
      set @_JpOmschrijving = replace( @_JpOmschrijving, '<nummer>', @Nummer );
    end if;
  end; // omschrijving

  // ***************
  // Dagboekcode
  // ***************
  set @_DagBoekCodeProductie = ( select DgbCode from tabDagboek inner join tabReceptuurVasteGegevens on RcpvDgbGidProductie = DgbGid );
  if ( @_DagBoekCodeProductie is null ) then
      call Raise(20700, _U('Dagboek, controleer vaste gegevens productie')); // (20700) Ongeldige waarde: %1!
    end if;

  // ********************
  // Rekeningen productie
  // ********************
  select RcpvRksGidResultaat, RcpvProdKostprijsTussenRksGid, RcpvProdOpbrengstTussenRksGid
    into @_RksGidResultaat,   @_RksGidKostprijsInBewerking,  @_RksGidOpbrengstInBewerking
  from tabReceptuurVasteGegevens ;

  // Rekening voor resultaat staat in productieorderkop. Zo niet, dan terugvallen op vaste gegevens
  set @_RksGidResultaat = isnull( ( select PrdOkRksGidProdResultaat from tabProductieOrderKop where PrdOkGid = @PrdOkGid ), @_RksGidResultaat);
  if ( @_RksGidResultaat  is null ) then
    call Raise(20700, _U('Grootboekrekening productieresultaat')); // Ongeldige waarde: %1!
  end if;
  if ( @_RksGidKostprijsInBewerking  is null ) then
    call Raise(20700, _U('Tussenrekening kostprijs productie in bewerking, controleer vaste gegevens productie')); // Ongeldige waarde: %1!
  end if;
  if ( @_RksGidOpbrengstInBewerking  is null ) then
    call Raise(20700, _U('Tussenrekening opbrengst productie in bewerking, controleer vaste gegevens productie')); // Ongeldige waarde: %1!
  end if;
end;



create or replace procedure WebSvcHulpProc_Productieorder_ValideerRekeningschemaBoekingenBestand(
  in @SessieNummer  integer
)
begin
  declare @RksGid integer;

  for @Cursor as OpbrengstGroepParagraafSoort cursor for
    select  tmpPrdVbOpbrGrpGid  as @OpbrengstgroepGid,
            OpbrGrpNummer       as @NummerOpbrengstgroep,
            tmpPrdVbParSoort    as @ParagraafSoort,
            count(*)            as @Aantalregels
    from tmpProductieOrderVerwerkBoekingen
      inner join tabOpbrengstGroep on OpbrGrpGid = tmpPrdVbOpbrGrpGid
    where ( tmpPrdVbSessieNr = @SessieNummer )
      and not exists (select 1 from tabOpbrengstGroepSoort where GrpSoortGrpGid=tmpPrdVbOpbrGrpGid and GrpSoortParSoort=tmpPrdVbParSoort)
    group by tmpPrdVbOpbrGrpGid, OpbrGrpNummer, tmpPrdVbParSoort
    order by tmpPrdVbOpbrGrpGid asc, tmpPrdVbParSoort asc
  for read only
  do
    // voor obrengstgroep en paragraaf waar GEEN rekeningschema van bekend is,
    // gaan we zorgen dat die er alsnog komt
    // met King 5 Stored Pro
    call  OpbrengtGroepsoortenPerStuk(@OpbrengstgroepGid, @ParagraafSoort);

    // gelukt, er is een rekening?
    set @RksGid = (select GrpSoortRksGid from tabOpbrengstGroepSoort where GrpSoortGrpGid=@OpbrengstgroepGid and GrpSoortParSoort=@ParagraafSoort);
    if @RksGid is null then
      call Raise(20780, _U('Boeken verwerking'), _U('geen grootboekrekening voor opbrengstgroep %1!, met paragraaf %2!', string(@NummerOpbrengstgroep), string(@ParagraafSoort))) ; //(20780) <actie> niet mogelijk: <reden>.
    end if;
  end for;
end;



create or replace procedure WebSvcHulpProc_Productieorder_ValideerTeVerwerkenComponenten(
  in @PrdOkGid                integer ,
  in @Boekdatum               date    ,
  in @ProductieorderAfsluiten smallint
)
begin


  // ************************************************************
  // controle specificaties op
  // matchend aantal, partijregistratie, en serienummerregistratie
  // ************************************************************
  begin
    declare @RedenNietMogelijk  nchar(255);

    select first
      case SoortControle
        when 10 /*aantal*/  then _U('van component %1! zijn niet alle aantallen (volledig) gespecificeerd', ArtCode)
        when 20 /*partij*/  then _U('van component %1! is een partijnummer niet ingevuld', ArtCode)
        when 30 /*serie*/   then _U('van component %1! is een serienummer niet ingevuld', ArtCode)
        else _U('onbekende fout met component %1!', ArtCode)
      end case
      into @RedenNietMogelijk
    from WebSvcHulpProc_Productieorder_OnvolledigeComponenten( @PrdOkGid );

    if @RedenNietMogelijk is not null then
      call Raise(20780, _U('Verwerken'), @RedenNietMogelijk) ; // (20780) <Actie> niet mogelijk: <reden>.
    end if;
  end; // controle specificatieregels

  // **************************************************
  // Melden als ergens voorraad negatief wordt
  // volgens instelling vaste gegevens productie
  // **************************************************
  begin
    declare @RedenNietMogelijk  nchar(255);

    select first
      String( ( select  case StatusCodeNegatieveVoorraad
                          when 7 then _U('negatieve magazijn-, beschikbare en vrije voorraad voor artikel:') || ' '
                          when 6 then _U('negatieve beschikbare en vrije voorraad voor artikel:') || ' '
                          when 5 then _U('negatieve magazijn- en vrije voorraad voor artikel:') || ' '
                          when 4 then _U('negatieve vrije voorraad voor artikel:') || ' '
                          when 3 then _U('negatieve magazijn- en beschikbare voorraad voor artikel:') || ' '
                          when 2 then _U('negatieve beschikbare voorraad voor artikel:') || ' '
                          when 1 then _U('negatieve magazijnvoorraad voor artikel:') || ' '
                          else ''
                        end case
                from dummy),
                ArtCode,
                ( select string(', ', _U('partij: %1!', ArtPartijnummer)) from dummy where PartijGid is not null ),
                ( select string(', ', _U('magazijn: %1!', MagCode)) from dummy where MagGid is not null) )
      into @RedenNietMogelijk
    from WebSvcHulpProc_Productieorder_ComponentAantalEnVoorraad( @PrdOkGid, 0 /* nu te verwerken*/, 0 /* alleen regels met te melden negatieve voorraad*/ );

    if @RedenNietMogelijk is not null then
      call Raise(20780, _U('Verwerken'), @RedenNietMogelijk) ; // (20780) <Actie> niet mogelijk: <reden>.
    end if;

  end; // melding negatieve voorraad

  // **************************************************
  // Controle: kostprijs wijzigt NA boekdatum verwerking
  // ( dit is vanwege voorraadmutaties )
  // **************************************************
  call WebSvcHulpProc_Productieorder_ControleHerwaarderingenVoorraadmutaties( @PrdOkGid, @Boekdatum, 1 /* Component afboeken */, 0 /* Eindproducten Opboeken */ );

  // **************************************************
  // Controle: bij afsluiten van productieorder
  // mag er niet nog iets te verwerken zijn
  // **************************************************
  begin
    declare @RedenNietMogelijk  nchar(255);

    if (@ProductieorderAfsluiten <> 0) then
      select first
        _U('van component %1! in regel %2! is het aantal nog te boeken ongelijk aan nul', ArtCode, string(PrdOcRegelNr)) into @RedenNietMogelijk
      from tabProductieOrderComponent
        inner join tabArtikel on  ( PrdOcArtGid = ArtGid )
      where PrdOcPrdOkGid = @PrdOkGid
        and ( ( PrdOcAantalTotaalTeVerwerken - PrdOcAantalReedsVerwerkt + PrdOcAantalUitvalInReedsVerwerkt - PrdOcAantalDezeVerwerking + PrdOcAantalUitvalInDezeVerwerking ) <> 0 )
        and ( PrdOcRegelSoort in ( 1,2 ) )    // 1 = tarief, 2 = artikel
      order by PrdOcRegelNr asc;

      if @RedenNietMogelijk is not null then
        call Raise(20780, _U('Verwerken'), @RedenNietMogelijk) ; // (20780) <Actie> niet mogelijk: <reden>.
      end if;
    end if;
  end // controle nog iets te verwerken
end;



create or replace procedure WebSvcHulpProc_Productieorder_ValideerTeVerwerkenEindproducten(
  in @PrdOkGid                integer ,
  in @Boekdatum               date    ,
  in @ProductieorderAfsluiten smallint)
begin

  // ************************************************************
  // controle specificaties op
  // matchend aantal, partijregistratie, en serienummerregistratie
  // ************************************************************
  begin
    declare @RedenNietMogelijk  nchar(255);

    select first
      case SoortControle
        when 10 /*aantal*/                then _U('van eindproduct %1! zijn niet alle aantallen (volledig) gespecificeerd', ArtCode)
        when 20 /*partij*/                then _U('van eindproduct %1! is een partijnummer niet ingevuld', ArtCode)
        when 30 /*partij in orderregel*/  then _U('van eindproduct %1! komt een partijnummer niet overeen met orderregel', ArtCode)
        when 40 /*serie*/                 then _U('van eindproduct %1! is een serienummer niet ingevuld', ArtCode)
        else _U('onbekende fout met eindproduct %1!', ArtCode)
      end case
      into @RedenNietMogelijk
    from WebSvcHulpProc_Productieorder_OnvolledigeEindproducten( @PrdOkGid );

    if @RedenNietMogelijk is not null then
      call Raise(20780, _U('Verwerken'), @RedenNietMogelijk) ; // (20780) <Actie> niet mogelijk: <reden>.
    end if;
  end; // controle specificatieregels

  // **************************************************
  // Controle: kostprijs wijzigt NA boekdatum verwerking
  // ( dit is vanwege voorraadmutaties )
  // **************************************************
  call WebSvcHulpProc_Productieorder_ControleHerwaarderingenVoorraadmutaties( @PrdOkGid, @Boekdatum, 0 /* Component afboeken */, 1 /* Eindproducten Opboeken */ );

  // **************************************************
  // Controle: bij afsluiten van productieorder
  // mag er niet nog iets te verwerken zijn
  // **************************************************
  begin
    declare @RedenNietMogelijk  nchar(255);

    if (@ProductieorderAfsluiten <> 0) then
      select first
        _U('van eindproduct %1! in regel %2! is het aantal nog te boeken ongelijk aan nul', ArtCode, PrdOeRegelNr)
        into @RedenNietMogelijk
      from tabProductieOrderEindproduct
        inner join tabArtikel on  ( PrdOeArtGid = ArtGid )
      where PrdOePrdOkGid = @PrdOkGid
        and ( ( PrdOeAantalTotaalTeVerwerken - PrdOeAantalReedsVerwerkt - PrdOeAantalDezeVerwerking  ) <> 0 )
      order by PrdOeRegelNr asc;

      if @RedenNietMogelijk is not null then
        call Raise(20780, _U('Verwerken'), @RedenNietMogelijk) ; // (20780) <Actie> niet mogelijk: <reden>.
      end if;
    end if;
  end // controle nog iets te verwerken
end;



create or replace procedure WebSvcHulpProc_Productieorder_ValideerVerwerkingsOpties(
  in  @PrdOkGid                 integer  default null,
  in  @ProductieorderAfsluiten  nchar(3) default null,  // 'JA' of 'NEE'
  in  @ComponentenAfboeken      nchar(3) default null,  // 'JA' of 'NEE'
  in  @EindproductenOpboeken    nchar(3) default null,  // 'JA' of 'NEE'
  in  @ProductiekostenBoeken    nchar(3) default null,  // 'JA' of 'NEE'
  out @_ProductieOrderAfsluiten smallint default null,
  out @_ComponentenAfboeken     smallint default null,
  out @_EindproductenOpboeken   smallint default null,
  out @_ProductiekostenBoeken   smallint default null
)
begin
  //call TraceBegin('WebSvcHulpProc_Productieorder_ValideerVerwerkingsOpties');

  // qc = Query Constanten
  declare @qcJA   smallint = 1;
  declare @qcNEE  smallint = 0;

  // ******************************
  // Productie order afsluiten
  // ******************************
  select  case isnull(trim(@ProductieorderAfsluiten), 'NEE')
            when 'JA'   then @qcJA
            when 'NEE'  then @qcNEE
            when '1'    then @qcJA
            when '0'    then @qcNEE
            else null
          end case
    into  @_ProductieOrderAfsluiten
  from dummy;

  if @_ProductieOrderAfsluiten is null then
    call Raise(20700, 'ProductieOrderAfsluiten'); // (20700) Ongeldige waarde: %1
  end if;

  // In geval van samenstelling wordt in King 5 een productieorder ALTIJD afgesloten
  // We gaan melden voor het geval de gebruiker denkt dat afsluiten niet gebeurt.
  if ( @_ProductieOrderAfsluiten <> @qcJA ) and exists ( select first @qcJA from tabProductieOrderKop where PrdOkGid = @PrdOkGid and prdokrcptsoort = 0 )
    then call Raise(20701, _U('%1! is verplicht voor productie-order van de soort samenstelling.', 'ProductieOrderAfsluiten')); // (20701) Ongeldige combinatie: <Parameternaam of opmerking>
  end if;

  // Productieorder afsluiten? Dan alle onderdelen boeken.
  select @qcJA,                 @qcJA,                    @qcJA
    into @_ComponentenAfboeken, @_EindproductenOpboeken,  @_ProductiekostenBoeken
  from dummy
  where @_ProductieOrderAfsluiten = @qcJA;

  // ******************************
  // Conponent afboeken?
  // N.v.t. als productieorder toch geheel afgesloten gaat worden.
  // ******************************
  select  case isnull(trim(@ComponentenAfboeken), 'NEE')
            when 'JA'   then @qcJA
            when 'NEE'  then @qcNEE
            when '1'    then @qcJA
            when '0'    then @qcNEE
            else null
          end case
    into  @_ComponentenAfboeken
  where @_ProductieOrderAfsluiten <> @qcJA;

  if @_ComponentenAfboeken is null then
    call Raise(20700, 'ComponentenAfboeken'); // (20700) Ongeldige waarde: %1
  end if;

  // ******************************
  // Eindproducten opboeken?
  // N.v.t. als productieorder toch geheel afgesloten gaat worden.
  // ******************************
  select  case isnull(trim(@EindproductenOpboeken), 'NEE')
            when 'JA'   then @qcJA
            when 'NEE'  then @qcNEE
            when '1'    then @qcJA
            when '0'    then @qcNEE
            else null
          end case
    into  @_EindproductenOpboeken
  where @_ProductieOrderAfsluiten <> @qcJA;

  if @_EindproductenOpboeken is null then
    call Raise(20700, 'EindproductenOpboeken'); // (20700) Ongeldige waarde: %1
  end if;

  // ******************************
  // Productiekosten boeken?
  // N.v.t. als productieorder toch geheel afgesloten gaat worden.
  // ******************************
  select  case isnull(trim(@ProductiekostenBoeken), 'NEE')
            when 'JA'   then @qcJA
            when 'NEE'  then @qcNEE
            when '1'    then @qcJA
            when '0'    then @qcNEE
            else null
          end case
    into  @_ProductiekostenBoeken
  where @_ProductieOrderAfsluiten <> @qcJA;

  if @_ProductiekostenBoeken is null then
    call Raise(20700, 'ProductiekostenBoeken'); // (20700) Ongeldige waarde: %1
  end if;

  // Nergens JA gezegd? dan heb je niks te verwerken dan.
  if ( @_ProductieOrderAfsluiten = @qcNEE and @_ComponentenAfboeken = @qcNEE and @_EindproductenOpboeken = @qcNEE and @_ProductiekostenBoeken = @qcNEE ) then
      call Raise(20780, _U('Verwerken'), string( _U('geen keuze gemaakt'),
                                            '( ProductieorderAfsluiten = ',  @ProductieorderAfsluiten,
                                            ', ComponentenAfboeken = ',      @ComponentenAfboeken,
                                            ', EindproductenOpboeken = ',    @EindproductenOpboeken,
                                            ', ProductiekostenBoeken = ',    @ProductiekostenBoeken,
                                            ' )')); // (20780) <Actie> niet mogelijk: <reden>.
  end if;

  // ****************************************
  // Valt er wel iets te verwerken?
  // Minstens 1 verwerkingsoptie is aangevinkt
  // ****************************************
  begin
    declare @IsTeVerwerkenComponent         smallint;
    declare @IsTeVerwerkenEindproduct       smallint;
    declare @IsTeVerwerkenProductieKosten   smallint;
    declare @RedenNietMogelijk              nchar(255);

    set @IsTeVerwerkenComponent = coalesce( ( select @qcNEE from dummy where @_ComponentenAfboeken = @qcNEE ),
                                            ( select first @qcJA from tabProductieOrderComponent where PrdOcPrdOkGid = @PrdOkGid and PrdOcAantalDezeVerwerking <> 0.0 and PrdOcRegelSoort = 2 /* artikel */ ),
                                            @qcNEE ); // we willen componenten afboeken, maar aantallen = 0.0

    if ( @IsTeVerwerkenComponent = @qcNEE and @_EindproductenOpboeken = @qcNee and @_ProductiekostenBoeken = @qcNEE ) then
      call Raise(20780, _U('Verwerken'), _U('er is geen component te verwerken (aantal = 0)')) ; // (20780) <Actie> niet mogelijk: <reden>.
    end if;

    set @IsTeVerwerkenEindproduct = coalesce( ( select @qcNEE from dummy where @_EindproductenOpboeken = @qcNEE ),
                                              ( select first @qcJA from tabProductieOrderEindProduct where PrdOePrdOkGid = @PrdOkGid and PrdOeAantalDezeVerwerking <> 0.0),
                                              @qcNEE ); // we willen eindproducten opboeken, maar aantallen = 0.0

    if ( @IsTeVerwerkenEindProduct = @qcNEE and @_ComponentenAfboeken = @qcNee and @_ProductiekostenBoeken = @qcNEE ) then
      call Raise(20780, _U('Verwerken'), _U('er is geen eindproduct te verwerken (aantal = 0)')) ; // (20780) <Actie> niet mogelijk: <reden>.
    end if;

    // Meerdere vinkjes?
    if ( @IsTeVerwerkenComponent = @qcNEE and @IsTeVerwerkenEindProduct = @qcNEE and @_ProductiekostenBoeken = @qcNEE ) then
      call Raise(20780, _U('Verwerken'), _U('er zijn geen componenten en eindproducten te verwerken (aantal = 0)')) ; // (20780) <Actie> niet mogelijk: <reden>.
    end if;

    // Dat er geen productiekosten zijn (dus geen tariefregels), dat is niet persÃ© fout...
    // Test op kostprijzen = 0 hoeft niet perse: king 5 ruimt journaalpost/boekingsgang op als er geen journaalregels zijn
    set @IsTeVerwerkenProductieKosten = coalesce( ( select @qcNEE from dummy where @_ProductiekostenBoeken = @qcNEE ),
                                                  ( select first @qcJA from tabProductieOrderComponent where PrdOcPrdOkGid = @PrdOkGid and PrdOcAantalDezeVerwerking <> 0.0 and PrdOcRegelSoort = 1 /* tarief */ ),
                                                  @qcNEE ); // we willen kosten boeken, maar aantallen = 0.0

    // Je kan hierboven op NEE eindigen omdat er geen productiekosten zijn (dus geen tariefregels),
    // dat is niet persÃ© fout...
    if ( @IsTeVerwerkenProductieKosten = @qcNEE and @_EindproductenOpboeken = @qcNee and @_ComponentenAfboeken = @qcNEE ) then

      // Er zijn wel tariefregels, maar met aantallen op 0.
      if exists ( select first @qcJA from tabProductieOrderComponent where PrdOcPrdOkGid = @PrdOkGid and PrdOcRegelSoort = 1 ) then
        call Raise(20780, _U('Verwerken'), _U('er zijn geen productiekosten te verwerken (aantal = 0)')) ; // (20780) <Actie> niet mogelijk: <reden>.
      end if;
    end if;

    // Er kan ook helemaal niks te verwerken zijn,
    // of er heeft al een verwerking plaatsgevonden, maar is vergeten aanpassingen te maken.
    // Als we wel gaan afsluiten. dan gaan we gewoon verwerken, dus niet checken.
    if ( @_ProductieOrderAfsluiten = @qcNEE ) then
      if ( @IsTeVerwerkenComponent = @qcNEE and @IsTeVerwerkenEindProduct = @qcNEE and @IsTeVerwerkenProductieKosten = @qcNEE ) then
        call Raise(20780, _U('Verwerken'), _U('er is helemaal niets om te verwerken')) ; // (20780) <Actie> niet mogelijk: <reden>.
      end if;
    end if;
  end; // check of er iets te verwerken valt

  //call TraceEind('WebSvcHulpProc_Productieorder_ValideerVerwerkingsOpties');
end;



create or replace procedure WebSvcHulpProc_Productieorder_VerwerkAantallenBedragenNaAfsluiten(
  in @PrdOkGid integer
)
begin

  // **********
  // Bedragen
  // **********
  begin
    declare @_NieuweKolommenKing563a  smallint;

    set @_NieuweKolommenKing563a = isnull( (  select count(*)
                                              from sys.syscolumns
                                              where ( tname = 'tabProductieOrderComponent'    and ( cname in ( 'PrdOcBedragGeboekt', 'PrdOcBedragUitvalGeboekt' ) ) )
                                                or  ( tname = 'tabProductieOrderEindproduct'  and ( cname in ( 'PrdOeBedragGeboekt', 'PrdOeBedragUitvalGeboekt' ) ) ) ),
                                            0);

    // standaard King 5 stored proc, beschikbaar met versie 5.63a
    // de tabellen moeten voor deze stored proc wel al nieuwe kolommen/velden hebben
    if ( @_NieuweKolommenKing563a = 4 ) then
      call ProductieOrderVerwerkBedragenNaAfsluiten( @PrdOkGid );
    else
      // Component - Zet de bedragen reeds verwerkt naar 0
      update tabProductieOrderComponent
      set PrdOcBedragReedsVerwerkt = 0.0,
          PrdOcBedragUitvalInReedsVerwerkt = 0.0
      where PrdOcPrdOkGid = @PrdOkGid;

      // Eindproduct - Zet de bedragen reeds verwerkt naar 0
      update tabProductieOrderEindproduct
      set PrdOeBedragReedsVerwerkt = 0.0,
          PrdOeBedragUitvalInReedsVerwerkt = 0.0
      where PrdOePrdOkGid = @PrdOkGid;

    end if;
  end; // Bedragen

  // **********
  // Aantallen
  // **********
  // ONTIME DEFECT 56541 - Geen extra (reset) acties m.b.t. aantallen bij eindproducten en componenten
  // De laatste (deel-)verwerking voorafgaand aan afsluiten zet de aantallen al goed.
  begin
  end; // Aantallen

end;



create or replace procedure WebSvcHulpProc_Productieorder_VerwerkBoekingenBestandInJournaalRegels(
  in @Sessienummer              integer   default null,
  in @JpGid                     integer   default null,
  in @PrdOkGid                  integer   default null,
  in @OmsAlleJournaalRegels     nchar(40) default null,
  in @IsVerwerkenAfsluiten      smallint  default null, // 1 = productieorder afsluiten, 0 = niet afsluiten
  in @RksGidProductieResultaat  integer   default null,
  in @RksGidKostprijs           integer   default null,
  in @RksGidOpbrengst           integer   default null
)
begin
  declare @_StukVolgnr              smallint;
  declare @_PrdOkNummer             numeric(10,0);
  declare @_TussenrekeningGebruiken smallint;


  // ******************************
  // Boekingenbestand verwerken
  // Bedragen in boekingbestand zijn in basisvaluta
  // ******************************
  insert into tabJournaalRegel(
    Aantal,
    IsCreditBoeking,
    JrBasisBedrag,
    JrBetalingsKenmerk, JrBjGid, JrBoekdatum, JrFactuurDatum, JrIsViaIncasso,
    JrJpGID,
    JrNummer, JrOspGid, JrPerNr,  JrRarGid,
    JrReferentie,
    JrRksGID,
    JrRksInvoer,
    JrValNummer,
    JrValutaBedrag,
    JrVervalDatum,
    OmsJournaalRegel,
    RegelNummer,
    SoortBoeking,
    StukVolgnr )
  select  0,// Aantal
          tmpPrdVbIsCreditBoeking,
          tmpPrdVbBedrag,   // in Basisvaluta
          '', null, null, null, 0,    // betalingskenmerk, BjGid, BoekDatum, Factuurdatum, IsViaIncasso
          @JpGid,
          '0', null, null, null,      // JrNummer, OspGid, PerNr, RarGid
          '',   // Referentie
          ( select GrpSoortRksGid from tabOpbrengstGroepSoort where GrpSoortGrpGid=tmpPrdVbOpbrGrpGid and GrpSoortParSoort=tmpPrdVbParSoort ) as JrRksGid,
          null, //RksInvoer
          @@BasisValutaNummer,
          tmpPrdVbBedrag,
          null, // Vervaldatum
          @OmsAlleJournaalRegels,
          null, // RegelNummer
          0,    // SoortBoeking: 0 = normaal, 1 = cjp tegenrek., 2 = cjp hulprek., 3 = cjp koerswijz., 4 = Herwaardering
          rank() over (partition by tmpPrdVbSessieNr order by tmpPrdVbGid asc) as StukVolgnr
  from tmpProductieOrderVerwerkBoekingen
  where tmpPrdVbSessieNr = @SessieNummer;


  // ********************************************
  // Nu gaan we tegenboeken, gaan we hiervoor
  // tussenrekeningen gebruiken of niet?
  // niet afsluiten ==> JA
  // wel afsluiten  ==> JA als regels verwerkt zijn
  // ********************************************
  set @_TussenrekeningGebruiken = isnull( ( select 1
                                            from dummy
                                            where ( @IsVerwerkenAfsluiten = 0 )
                                              or exists ( select first 1
                                                          from tabProductieOrderComponent
                                                          where PrdOcPrdOkGid = @PrdOkGid
                                                            and ( PrdOcAantalReedsVerwerkt <> 0.0 or PrdOcAantalUitvalInReedsVerwerkt <> 0.0) )
                                              or exists ( select first 1
                                                          from tabProductieOrderEindproduct
                                                          where PrdOePrdOkGid = @PrdOkGid
                                                            and ( PrdOeAantalReedsVerwerkt <> 0.0 or PrdOeAantalUitvalInReedsVerwerkt <> 0.0) ) ),
                                          0);

  begin
    if  ( @_TussenrekeningGebruiken <> 0 ) then

      // t.b.v. referentie
      set @_PrdOkNummer = ( select PrdOkNummer from tabProductieorderKop where PrdOkGid = @PrdOkGid );

      // 2A - Kostprijs
      call WebSvcHulpProc_Productieorder_VerwerkBoekingenOpTussenrekeningKostprijs(
        @Sessienummer,
        @JpGid,
        @_PrdOkNummer,
        @OmsAlleJournaalRegels,
        @RksGidKostprijs);

      // 2B - Opbrengst
      call WebSvcHulpProc_Productieorder_VerwerkBoekingenOpTussenrekeningOpbrengst(
        @Sessienummer,
        @JpGid,
        @_PrdOkNummer,
        @OmsAlleJournaalRegels,
        @RksGidOpbrengst);
    end if;
  end; // Tussenrekeningen gebruiken

  // ************************************************************
  // Bij afsluiten van productieorder resultaat en uitval boeken,
  // hierbij met tussenrekeningen rekening houden.
  // ************************************************************
  if ( @IsVerwerkenAfsluiten <> 0 ) then
    call WebSvcHulpProc_Productieorder_ResultaatBoekenBijAfsluiten(
      @Sessienummer,
      @JpGid,
      @PrdOkGid,
      @OmsAlleJournaalRegels,
      @RksGidProductieResultaat,
      @RksGidKostprijs,
      @RksGidOpbrengst,
      @_TussenrekeningGebruiken); // 0 = nee, 1 = ja
  end if;

end;



create or replace procedure WebSvcHulpProc_Productieorder_VerwerkBoekingenOpTussenrekeningKostprijs(
  in @Sessienummer          integer       default null, // Verplicht
  in @JpGid                 integer       default null, // Verplicht
  in @PrdOkNummer           numeric(10,0) default null, // Verplicht
  in @OmsAlleJournaalRegels nchar(40)     default null,
  in @RksGidKostprijs       integer       default null
)
begin
  declare @_StukVolgnr  smallint;
  declare @_Bedrag      numeric(15,3);

  // Kostprijs = [regulier]   regelsoort <> 3 (uitval) EN creditboeking
  //             [uitval]   + regelsoort =  3 (uitval) EN debetboeking
  set @_Bedrag = isnull( (  select sum( if tmpPrdVbSoortRegel = 3 then -1 else 1 end if * tmpPrdVbBedrag )
                            from tmpProductieOrderVerwerkBoekingen
                            where ( ( tmpPrdVbIsCreditBoeking = 1 and tmpPrdVbSoortRegel <> 3  )
                                    or ( tmpPrdVbIsCreditBoeking = 0 and tmpPrdVbSoortRegel =  3 ) )
                              and tmpPrdVbSessieNr = @SessieNummer ), 0.0 ); // null => 0.0

  set @_StukVolgnr = isnull( (select max(StukVolgnr) from tabJournaalRegel where JrJpGID = @JpGid), 0) + 1;

  insert into tabJournaalRegel(
    Aantal,
    IsCreditBoeking,
    JrBasisBedrag,
    JrBetalingsKenmerk, JrBjGid, JrBoekdatum, JrFactuurDatum, JrIsViaIncasso,
    JrJpGID,
    JrNummer, JrOspGid, JrPerNr,  JrRarGid,
    JrReferentie,
    JrRksGID,
    JrRksInvoer,
    JrValNummer,
    JrValutaBedrag,
    JrVervalDatum,
    OmsJournaalRegel,
    RegelNummer,
    SoortBoeking,
    StukVolgnr )
  select  0,        // Aantal
          0,        // IsCreditBoeking
          @_Bedrag, // in Basisvaluta
          '', null, null, null, 0,    // betalingskenmerk, BjGid, BoekDatum, Factuurdatum, IsViaIncasso
          @JpGid,
          '0', null, null, null,      // JrNummer, OspGid, PerNr, RarGid
          string(@PrdOkNummer),       // Referentie
          @RksGidKostprijs,           //JrRksGid,
          null,     //RksInvoer
          @@BasisValutaNummer,
          @_Bedrag, // JrValutaBedrag
          null,     // Vervaldatum
          @OmsAlleJournaalRegels,
          null,     // RegelNummer
          0,        // SoortBoeking: 0 = normaal, 1 = cjp tegenrek., 2 = cjp hulprek., 3 = cjp koerswijz., 4 = Herwaardering
          @_StukVolgnr
  from dummy
  where round(@_Bedrag,2) <> 0.0;

end;



create or replace procedure WebSvcHulpProc_Productieorder_VerwerkBoekingenOpTussenrekeningOpbrengst(
  in @Sessienummer          integer       default null, // Verplicht
  in @JpGid                 integer       default null, // Verplicht
  in @PrdOkNummer           numeric(10,0) default null, // Referentie
  in @OmsAlleJournaalRegels nchar(40)     default null,
  in @RksGidOpbrengst       integer       default null
)
begin
  declare @_StukVolgnr  smallint;
  declare @_Bedrag      numeric(15,3);

  // Opbrengst = [regulier]   regelsoort <> 3 (uitval) EN debetboeking
  //             [uitval]   + regelsoort =  3 (uitval) EN creditboeking
  set @_Bedrag = isnull( (  select sum( if tmpPrdVbSoortRegel = 3 then -1 else 1 end if * tmpPrdVbBedrag )
                            from tmpProductieOrderVerwerkBoekingen
                            where ( ( tmpPrdVbIsCreditBoeking = 0 and tmpPrdVbSoortRegel <> 3  )
                                    or ( tmpPrdVbIsCreditBoeking = 1 and tmpPrdVbSoortRegel =  3 ) )
                              and tmpPrdVbSessieNr = @SessieNummer ), 0.0 ); // null => 0.0

  set @_StukVolgnr = isnull( (select max(StukVolgnr) from tabJournaalRegel where JrJpGID = @JpGid), 0) + 1;

  insert into tabJournaalRegel(
    Aantal,
    IsCreditBoeking,
    JrBasisBedrag,
    JrBetalingsKenmerk, JrBjGid, JrBoekdatum, JrFactuurDatum, JrIsViaIncasso,
    JrJpGID,
    JrNummer, JrOspGid, JrPerNr,  JrRarGid,
    JrReferentie,
    JrRksGID,
    JrRksInvoer,
    JrValNummer,
    JrValutaBedrag,
    JrVervalDatum,
    OmsJournaalRegel,
    RegelNummer,
    SoortBoeking,
    StukVolgnr )
  select  0,        // Aantal
          1,        // IsCreditBoeking
          @_Bedrag, // in Basisvaluta
          '', null, null, null, 0,    // betalingskenmerk, BjGid, BoekDatum, Factuurdatum, IsViaIncasso
          @JpGid,
          '0', null, null, null,      // JrNummer, OspGid, PerNr, RarGid
          string(@PrdOkNummer),       // Referentie
          @RksGidOpbrengst,           //JrRksGid,
          null,     //RksInvoer
          @@BasisValutaNummer,
          @_Bedrag, // JrValutaBedrag
          null,     // Vervaldatum
          @OmsAlleJournaalRegels,
          null,     // RegelNummer
          0,        // SoortBoeking: 0 = normaal, 1 = cjp tegenrek., 2 = cjp hulprek., 3 = cjp koerswijz., 4 = Herwaardering
          @_StukVolgnr
  from dummy
  where round(@_Bedrag,2) <> 0.0;

end;



create or replace procedure WebSvcHulpProc_Productieorder_VerwerkenInAdministratie(
  in @PrdOkGid                integer      default null,     // Verplicht
  in @BoekDatum               date         default null,     // Verplicht
  in @Omschrijving            nchar(40)    default null,     // Verplicht
  in @ProductieorderAfsluiten smallint     default null,     // Verplicht; 0 = nee, 1 = ja
  in @ComponentenAfboeken     smallint     default null,     // Verplicht; 0 = nee, 1 = ja
  in @EindproductenOpboeken   smallint     default null,     // Verplicht; 0 = nee, 1 = ja
  in @ProductiekostenBoeken   smallint     default null,     // Verplicht; 0 = nee, 1 = ja
  // T.b.v. locken, wordt bepaald door aanroepende instantie
  in @LockUserNaam            nchar(40)    default null,     // Verplicht,   // Dit kan per API verschillen. De aanroeper moet zich identificeren
  in @SpId                    integer      default null  ,   // NULL =>  systeemvariabele @@SpId       wordt gebruikt
  in @LoginTime               timestamp    default null  )   // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt
begin
  declare @_ComponentenAfboeken         smallint;
  declare @_EindproductenOpboeken       smallint;
  declare @_ProductiekostenBoeken       smallint;

  declare @_BoekgangGid                 integer;
  declare @_JournaalpostGid             integer;
  declare @_BoekStukDatum               date;
  declare @_BoekjaarCode                nchar(10);
  declare @_OmsJournaalPost             char(40);
  declare @_DagBoekCodeProductie        nchar(10);
  declare @_RksGidResultaat             integer;
  declare @_RksGidKostprijsInBewerking  integer;
  declare @_RksGidOpbrengstInBewerking  integer;

  // qc = Query Constanten
  declare @qcNEE  smallint = 0;
  declare @qcJA   smallint = 1;

  if isnull(@ProductieorderAfsluiten, -1) in (@qcNEE, @qcJA) then
    if @ProductieorderAfsluiten = @qcJA then
      // Productie afsluiten, dan altijd op/afboeken
      set @_ComponentenAfboeken  = 1;
      set @_EindproductenOpboeken = 1;
      set @_ProductiekostenBoeken = 1;
    else
      set @_ComponentenAfboeken   = @ComponentenAfboeken;
      set @_EindproductenOpboeken = @EindproductenOpboeken;
      set @_ProductiekostenBoeken = @ProductiekostenBoeken;
    end if;
  else
    call Raise(20700,'RegelSoort');   // (20700) Ongeldige waarde: %1!
  end if;


  // ******************************
  // Validatie journaalpostgegevens
  // ******************************
  call WebSvcHulpProc_Productieorder_ValideerJournaalpostgegevens(
    /*in*/
    @PrdOkGid,
    @Boekdatum,
    @Omschrijving,
    /*out*/
    @_BoekjaarCode,
    @_BoekstukDatum,
    @_DagBoekCodeProductie,
    @_OmsJournaalPost,
    @_RksGidResultaat,
    @_RksGidKostprijsInBewerking,
    @_RksGidOpbrengstInBewerking);

  // ******************************
  // Verwerk de productie-order
  // als een complete transactie
  // Er mag onderweg niks mis gaan.
  // ******************************
  begin atomic
    declare @_SessieNummer                integer;

    // King 5 stored proc - Eerst een Sessie ID aanvragen, deze wordt gebruikt om bijbehorende data te identificeren
    call MaakUniekSessieNummer( @_SessieNummer );

    // Neem de Productie-order in gebruik, we gaan aan de slag.
    call WebSvcHulpProc_ProductieorderExclusiefLocken( @PrdOkGid, @LockUserNaam, @SpId, @LoginTime );

    // Verkooporders gekoppeld aan eindproducten moeten ook gelockt worden.
    if ( @_EindproductenOpboeken = @qcJA ) then
      call WebSvcHulpProc_Productieorder_GekoppeldeOrdersInGebruikNemen( @PrdOkGid, @LockUserNaam, @SpId, @LoginTime );
    end if;

    // *******************************************************
    // Voorbereiding Verwerking t.b.v. boekingsgang/journaalpost
    // *******************************************************

    delete from tmpProductieOrderVerwerkPlatgeslagen where tmpPrdVpSessieNr = @_SessieNummer;
    delete from tmpProductieOrderVerwerkBoekingen where tmpPrdVbSessieNr = @_SessieNummer;

    // Componenten (artikelen) en Productiekosten (tarieven)
    call WebSvcHulpProc_Productieorder_ComponentenPlatslaanTbvVerwerking( @_SessieNummer, @PrdOkGid, @_ComponentenAfboeken, @_ProductiekostenBoeken);

    // Eindproducten
    call WebSvcHulpProc_Productieorder_EindproductenPlatslaanTbvVerwerking( @_SessieNummer, @PrdOkGid, @_EindproductenOpboeken);

    // Tijdelijke boekingenbestand opbouwen
    call WebSvcHulpProc_Productieorder_MaakBoekingenBestandTbvVerwerking( @_SessieNummer, @_ComponentenAfboeken, @_ProductiekostenBoeken, @_EindproductenOpboeken );

    // Het kan zijn dat voor combinatie van paragraaf en opbrengstgroep geen rekening is
    // probeer die eerst aan te maken en daarna pas checken of je compleet bent
    call WebSvcHulpProc_Productieorder_ValideerRekeningschemaBoekingenBestand(@_SessieNummer);

    // ******************************************************************
    // Boekingsgang en journaaalpost
    // ******************************************************************

    // Boekingsgang aanmaken of bestaande openen
    // RtK/2020-05-08 - ik zou nu eerst altijd nieuw doen.
    // Hergebruik van een boekingsgang is niet bewezen dat dat goed gaat. Daar is mogelijk nog werk te doen.
    call WebSvcHulpProc_Productieorder_OpenBoekingsgangTbvVerwerking(
      /*in*/
      @_BoekjaarCode,           // Voor welk boekjaar
      null,                     // Nieuw boekingsgang maken met nieuw nummer.
      @LockUserNaam,            // Wie neemt boekingsgang in gebruik?
      _A('Productie'),              // Omschrijving boekingsgang
      /*out*/
      @_BoekGangGid);           // nodig voor journaalpost

    // Journaalpost (per productie-order)
    call WebSvcHulpProc_Boekingsgang_Journaalpost_Toevoegen(
      /*in*/
      @_BoekjaarCode,
      ( select BoekgangNummer from tabBoekingsGang where BoekgangGid = @_BoekGangGid ),
      @_DagBoekCodeProductie,
      @_BoekstukDatum,
      null,   // BoekstukNummer      numeric(10,0) ,
      @_OmsJournaalPost,
      /*out*/
      @_JournaalpostGid);

    // test
    /*
    call trace( String ( ' Boekingsgang = ',  ( select BoekgangNummer from tabBoekingsGang where BoekgangGid = @_BoekGangGid ),
                         ', Journaalpost = ', ( select JpNummer from tabJournaalPost where JpGid = @_JournaalpostGid),
                         ', JpGid = ',        @_JournaalpostGid ) );
    */

    // Journaalregels in de journaalpost, voor
    // componenten, eindproducten, kosten,
    // tussenrekeningen kostprijs en opbrengst,
    // en resultaten/tegenboekingen bij afsluiten productieorder.

    call WebSvcHulpProc_Productieorder_VerwerkBoekingenBestandInJournaalRegels(@_SessieNummer, @_JournaalpostGid, @PrdOkGid, @_OmsJournaalPost, @ProductieOrderAfsluiten, @_RksGidResultaat,    @_RksGidKostprijsInBewerking, @_RksGidOpbrengstInBewerking);

    // ********************************************
    // Voorraadmutaties (gekoppeld aan journaalpost)
    // voor componenten en eindproducten
    // ********************************************
    if ( @_ComponentenAfboeken = @qcJA )    then call WebSvcHulpProc_Productieorder_MaakVoorraadMutatiesComponenten(@PrdOkGid, @_JournaalpostGid, @_BoekStukDatum, @_ComponentenAfboeken) end if;
    if ( @_EindproductenOpboeken = @qcJA )  then call WebSvcHulpProc_Productieorder_MaakVoorraadMutatiesEindproducten(@PrdOkGid, @_JournaalpostGid, @_BoekStukDatum, @_EindproductenOpboeken) end if;

    // **************************
    // Productie-order bijwerken
    // **************************

    // Aantallen en bedragen van deze verwerkingsactie
    call WebSvcHulpProc_Productieorder_UpdateAantallenBedragen(@_SessieNummer, @PrdOkGid, @_ComponentenAfboeken, @_EindproductenOpboeken, @_ProductiekostenBoeken);

    // Update het Aantal NuTeFactureren in de gekoppelde OrderRegel
    update tabOrderRegel
      inner join tabOrderKop                      on OrkGid = OrrOrkGid
      inner join tabProductieOrderEindProduct     on PrdOePrdOkGid = @PrdOkGid
      inner join tabProductieOrderEindProductSpec on PrdOesPrdOeGid = PrdOeGid and PrdOesOrrGid = OrrGid
    set OrrAantalDezeFacturering = OrrAantalNogTeFactureren,
        OrrAantalDezeFactureringVrrdEenh = OrrAantalLeveringVrrdEenh
    where OrrAantalNogTeFacturerenVrrdEenh = OrrAantalLeveringVrrdEenh
      and OrkVrijVoorFaktureren = 1 // 1 = JA, 0 = NEE
      and exists( select 1 from tabVasteGegevensOrdersFactureren where vofRegelDefNuFactureren = 2 ); // 0 = Leeg, 1 = Aantal besteld, 2 = Aantal deze levering

    // *******************************************************
    // Tijdelijke zaken opruimen
    // en alle in gebruik genomen zaken weer vrijgeven
    // *******************************************************

    // Jounaalpost vrijgeven (moet dit expliciet?)
    begin
      update tabJournaalPost set JpIsIngebruik = 0 where JpGid = @_JournaalpostGid;
    end;

    // Boekingsgang vrijgeven/afsluiten
    // haal ook nog even de lock van de boekingsgang af als die er is.
    begin
      update tabBoekingsgang set BoekgangInGebruik = 0 where BoekgangGid = @_BoekgangGid;
      call LockReleaseOnUserName(@LockUserNaam, 1, 'tabBoekingsGang', 'BoekgangGid='+string(@_BoekGangGid));
    end;

    // Tijdelijke materiaal opruimen
    // In geval van testen (output controle) zou je dat kunnen uitschakelen.
    //delete from tmpProductieOrderVerwerkPlatgeslagen where tmpPrdVpSessieNr = @_SessieNummer;
    //delete from tmpProductieOrderVerwerkBoekingen where tmpPrdVbSessieNr = @_SessieNummer;

    // Verkooporders gekoppeld aan eindproducten weer vrijgeven
    if ( @_EindproductenOpboeken = @qcJA ) then
      call WebSvcHulpProc_Productieorder_GekoppeldeOrdersVrijgeven( @PrdOkGid, @LockUserNaam, @SpId, @LoginTime );
    end if;

    // *******************************************************
    // Afsluiten productieorder
    // Lock vrijgeven als productie order status gereed is gemeld.
    // *******************************************************
    call WebSvcHulpProc_Productieorder_UpdateStatusVerwerking( @PrdOkGid, @ProductieOrderAfsluiten, @_BoekStukDatum );
    if ( @ProductieOrderAfsluiten = @qcJA ) then
      if not exists( select 1 from tabProductieOrderKop where PrdOkGid = @PrdOkGid and PrdOkStatus = 4 /* Gereed */ ) then
        call Raise(20761, _U('Afsluiten is niet goed gegaan, productieorder heeft niet de status Gereed.'));
      end if;
      // De laatste actie als de productie order gereed is gemeld: we gaan definitief aantallen en bedragen goed zetten
      call WebSvcHulpProc_Productieorder_VerwerkAantallenBedragenNaAfsluiten(@PrdOkGid);
      // Definitief afgesloten/klaar, dus...
      call WebSvcProc_Productieorder_LockVrijgeven((select PrdOkNummer from tabProductieOrderKop where PrdOkGid = @PrdOkGid));
    end if;

  end; // ### atomic ###

  // *****************************************************************************
  // Verwerken gelukt.
  // Mocht boekingsgang echter niet in evenwicht zijn, dan
  // dan melden we dat als fout, en blijft de verwerkte data voor onderzoek wel staan.
  // *****************************************************************************
  begin
    declare @_TotaalBedragDebet   numeric(14,2);
    declare @_TotaalBedragCredit  numeric(14,2);

    // Controle op evenwicht heeft alleen zin als journaalpost nog bestaat.
    // Het kan na vrijgeven verdwijnen bij nul regels zijn of nul-bedragen.
    if exists( select first 1 from tabJournaalPost where JpGid = @_JournaalpostGid ) then
      //Is er in deze journaalpost evenwicht?
      set @_TotaalBedragDebet =   isnull( ( select sum( JrBasisBedrag ) from tabjournaalregel where JrJpGid = @_JournaalpostGid and IsCreditBoeking = 0 ), 0.0 );
      set @_TotaalBedragCredit =  isnull( ( select sum( JrBasisBedrag ) from tabjournaalregel where JrJpGid = @_JournaalpostGid and IsCreditBoeking = 1 ), 0.0 );

      if ( @_TotaalBedragDebet <> @_TotaalBedragCredit ) then
        call Raise(20761, _U('Verwerken is gelukt, maar in boekingsgang %1! is journaalpost %2! niet in evenwicht.',
                          (select BoekgangNummer from tabBoekingsGang where BoekgangGid = @_BoekGangGid),
                          (select JpNummer from tabJournaalPost where JpGid = @_JournaalpostGid)
                   ));  // (20761) Ongeldige status: <opmerking status>
      end if;
    end if;
  end; // evenwicht in journaalpost

end;



create or replace procedure WebSvcHulpProc_Valideer_ProductieOrderEnStatus(
  in  @PrdOkNummer              numeric(10,0) default null, // Verplicht
  in  @StatusGereedMagNiet      smallint      default 0   , // optioneel
  out @_PrdOkGid                integer       default null,
  out @_PrdOkStatus             smallint      default null)
begin
  declare @Foutmelding          nchar(250);

  select PrdOkGid,
         PrdOkStatus,
         case PrdOkStatus
            when 4 then ( select _U('Productieorder mag niet Gereed zijn.')      from dummy where @StatusGereedMagNiet <> 0 )
            when 3 then null
            when 2 then null
            when 1 then null    // In te plannen
            when 0 then null    // Nieuw
            else null
         end case
  into   @_PrdOkGid,
         @_PrdOkStatus,
         @Foutmelding
  from   tabProductieOrderKop
  where  PrdOkNummer = @PrdOkNummer;

  // Is er een productie-order met dat nummer?
  if  @_PrdOkGid is null then
      call Raise(20720,  'ProductieorderNummer') ;  // (20780) %1 niet gevonden!
  end if;
  // Heeft productie-order een status die niet mag?
  if @Foutmelding is not null then
      call Raise(20761,  @Foutmelding);      // (20761) Ongeldige status: <status-opmerking>
  end if;
end;



create or replace procedure WebSvcHulpProc_Valideer_ProductieorderKop(
  in    @Mode                                     smallint      default null,       // 0 = Toevoegen, 1 = Wijzigen
  in    @ReceptCode                               nchar(20)     default null,
  in    @Omschrijving                             nchar(40)     default null,
  in    @AantalTeProduceren                       numeric(15,3) default null,
  in    @Status                                   nchar(13)     default null,
  in    @TeProducerenDoor                         nchar(10)     default null,
  in    @TeProducerenVoor                         date          default null,
  in    @StartdatumProductie                      date          default null,
  in    @DefaultMagazijnComponenten               numeric(3,0)  default null,
  in    @DefaultMagazijnEindproduct               numeric(3,0)  default null,
  in    @DefaultAantalNuAfTeBoeken                nchar(16)     default null,
  in    @DefaultAantalNuOpTeBoeken                nchar(16)     default null,
  in    @RekeningnummerProductieResultaat         nchar(28)     default null,
  in    @Document                                 nchar(255)    default null,
  in    @Opmerking                                long nvarchar default null,
  inout @_PrdOkGid                                integer       default null,
  inout @_PrdOkRcptCode                           nchar(20)     default null,
  inout @_PrdOkRcptSoort                          smallint      default null,
  inout @_PrdOkRcptZoekcode                       nchar(20)     default null,
  inout @_PrdOkOmschrijving                       nchar(40)     default null,
  inout @_PrdOkAantalRcpt                         numeric(15,3) default null,
  inout @_PrdOkAantalRcptMinimum                  numeric(15,3) default null,
  inout @_PrdOkAantalRcptMaximum                  numeric(15,3) default null,
  inout @_PrdOkStatus                             smallint      default null,
  inout @_TeProducerenDoor                        nchar(40)     default null,
  inout @_PrdOkTeProducerenVoor                   date          default null,
  inout @_PrdOkProductieStartOp                   date          default null,
  inout @_PrdOkDefMagGidComponent                 integer       default null,
  inout @_PrdOkDefMagGidEindproduct               integer       default null,
  inout @_PrdOkVulAantalDezeVerwerkingComponent   integer       default null,
  inout @_PrdOkVulAantalDezeVerwerkingEindproduct integer       default null,
  inout @_PrdOkRksGidProdResultaat                integer       default null,
  inout @_PrdOkDocument                           nchar(255)    default null,
  inout @_PrdOkOpmerking                          long nvarchar default null
)

begin
  // Fixed enumerators
  declare _TOEVOEGEN smallint = 0;
  declare _WIJZIGEN  smallint = 1;

  // Vaste gegevens productie
  declare @RcpvGid                                integer;
  declare @RcpvRksGidResultaat                    integer;
  declare @RcpvDefaultProductieOrderStatus        smallint;
  declare @RcpvVulAantalDezeVerwerkingComponent   smallint;
  declare @RcpvVulAantalDezeVerwerkingEindproduct smallint;

  // tabReceptuur
  declare @RcptGid                                integer;
  declare @RcptRksGid                             integer;
  declare @RcptBatchDefault                       numeric(15,3);
  declare @RcptBatchMaximum                       numeric(15,3);
  declare @RcptBatchMinimum                       numeric(15,3);
  declare @RcptCode                               nchar(20);
  declare @RcptDefaultProductieOrderStatus        smallint;
  declare @RcptDocument                           nchar(255);
  declare @RcptGeblokkeerd                        smallint;
  declare @RcptOmschrijving                       nchar(40);
  declare @RcptPrijsBatchAantal                   numeric(15,3);
  declare @RcptPrijsBatchGrootte                  smallint;
  declare @RcptSoort                              smallint;
  declare @RcptVulAantalDezeVerwerkingComponent   smallint;
  declare @RcptVulAantalDezeVerwerkingEindproduct smallint;
  declare @RcptZoekcode                           nchar(20);
  declare @RcptOpmerking                          long nvarchar;
  declare @RcptAparteProductieOrdersPerRecept     smallint;

  // Overige variabelen
  declare @BatchMaximum                           numeric(10,0);
  declare @AantalTeProducerenNoDec                numeric(15,3);

  // --------------------------------
  // --- EXPLICIET VOOR TOEVOEGEN ---
  // --------------------------------
  if @Mode = _TOEVOEGEN then
     // Vaste gegevens Productieorder ophalen
     select  first RcpvGid,
             RcpvRksGidResultaat,
             RcpvDefaultProductieOrderStatus,
             RcpvVulAantalDezeVerwerkingComponent,
             RcpvVulAantalDezeVerwerkingEindproduct
     into    @RcpvGid,
             @RcpvRksGidResultaat,
             @RcpvDefaultProductieOrderStatus,
             @RcpvVulAantalDezeVerwerkingComponent,
             @RcpvVulAantalDezeVerwerkingEindproduct
     from    tabReceptuurVasteGegevens;

     // Ophalen Receptgegeven, indien @ReceptCode is meegegeven
     if @ReceptCode is not null then     // @ReceptCode is meegegeven
        select  RcptGid,
                RcptRksGid,
                RcptBatchDefault,
                RcptBatchMaximum,
                RcptBatchMinimum,
                RcptCode,
                isnull(RcptDefaultProductieOrderStatus,@RcpvDefaultProductieOrderStatus),
                RcptDocument,
                RcptGeblokkeerd,
                RcptOmschrijving,
                RcptPrijsBatchAantal,
                RcptPrijsBatchGrootte,
                RcptSoort,
                RcptVulAantalDezeVerwerkingComponent,
                RcptVulAantalDezeVerwerkingEindproduct,
                RcptZoekcode,
                RcptOpmerking,
                RcptAparteProductieOrdersPerRecept
        into    @RcptGid,
                @RcptRksGid,
                @RcptBatchDefault,
                @RcptBatchMaximum,
                @RcptBatchMinimum,
                @RcptCode,
                @RcptDefaultProductieOrderStatus,
                @RcptDocument,
                @RcptGeblokkeerd,
                @RcptOmschrijving,
                @RcptPrijsBatchAantal,
                @RcptPrijsBatchGrootte,
                @RcptSoort,
                @RcptVulAantalDezeVerwerkingComponent,
                @RcptVulAantalDezeVerwerkingEindproduct,
                @RcptZoekcode,
                @RcptOpmerking,
                @RcptAparteProductieOrdersPerRecept
        from    tabReceptuur
        where   RcptCode = @ReceptCode;
        // Meegegeven @ReceptCode moet een bestaande recept zijn
        if @RcptGid is null then
           call Raise(20720,'ReceptCode'); // (20720) niet gevonden: %1!
        end if;
        // Recept mag niet geblokkeerd zijn
        if @RcptGeblokkeerd = 1 then
           call Raise(20780,_U('Productieorder toevoegen is'),_U('Recept is geblokkeerd voor produceren'));      // (20780) %1! niet mogelijk: %2!
        end if;
     end if;

     // @DefaultMagazijnComponenten moet een bestaande magazijncode zijn
     if @DefaultMagazijnComponenten is not null then
        (select first MagGid into @_PrdOkDefMagGidComponent from tabMagazijn where MagCode = @DefaultMagazijnComponenten);
        if @_PrdOkDefMagGidComponent is null then
           call Raise(20720,  'DefaultMagazijnComponenten') ;  // (20780) %1 niet gevonden!
        end if;
     else
        call Raise(20700, 'DefaultMagazijnComponenten'); // (20700) Ongeldige waarde: %1!;
     end if;

     // @DefaultMagazijnEindproduct moet een bestaande magazijncode zijn
     if @DefaultMagazijnEindproduct is not null then
        (select first MagGid into @_PrdOkDefMagGidEindproduct from tabMagazijn where MagCode = @DefaultMagazijnEindproduct);
        if @_PrdOkDefMagGidEindproduct is null then
           call Raise(20720,  'DefaultMagazijnEindproduct') ;  // (20780) %1 niet gevonden!
        end if;
     else
        call Raise(20700, 'DefaultMagazijnEindproduct'); // (20700) Ongeldige waarde: %1!;
     end if;

     // In @AantalTeProduceren mogen geen decimalen worden meegegeven.
     if isnull(@AantalTeProduceren,0) > 0 then
        set @AantalTeProducerenNoDec = truncnum(@AantalTeProduceren,0);
        if @AantalTeProduceren - @AantalTeProducerenNoDec <> 0 then
           call Raise(20700, _U('In %1! zijn geen decimalen toegestaan', 'AantalTeProduceren')); // (20700) Ongeldige waarde: %1!;
        end if;
     end if;

     // @AantalTeProduceren moet een aantal groter dan 0 of kleiner of gelijk aan 9999999999, indien geen @ReceptCode is meegegeven
     // Indien @AantalTeProduceren samen met @ReceptCode is meegegeven, dan moet @AantalTeProduceren tussem minimum en maximum aantal uit recept bevinden.
     if @ReceptCode is null then
        // @ReceptCode is niet meegegeven
        if isnull(@AantalTeProduceren,0) > 0 and isnull(@AantalTeProduceren,0) <= 9999999999 then
           set @_PrdOkAantalRcpt = @AantalTeProduceren;
           set @_PrdOkAantalRcptMinimum = 1;    // Altijd minimaal 1 te produceren
           set @_PrdOkAantalRcptMaximum = 0;    // 0 = Geen maximum
           set @_PrdOkRcptCode = '';
           set @_PrdOkRcptZoekCode = '';
           set @_PrdOkRcptSoort = 1;            // Altijd Productie
        else
           call Raise(20700, 'AantalTeProduceren'); // (20700) Ongeldige waarde: %1!;
        end if;
        if @Status is null then
           // @Status is niet meegegeven, dan overnemen uit Vaste gegeven productie
           set @_PrdOkStatus = @RcpvDefaultProductieOrderStatus;
        end if;
        if @RekeningnummerProductieResultaat is null then
           // @RekeningnummerProductieResultaat niet meegegeven, dan ophalen uit Vaste gegevens productie
           set @_PrdOkRksGidProdResultaat = @RcpvRksGidResultaat;
        end if;
        if @DefaultAantalNuAfTeBoeken is null then
           // @DefaultAantalNuAfTeBoeken is niet meegegeven, dan ophalen uit Vaste gegevens productie
           set @_PrdOkVulAantalDezeVerwerkingComponent = @RcpvVulAantalDezeVerwerkingComponent;
        end if;
        if @DefaultAantalNuOpTeBoeken is null then
           // @DefaultAantalNuOpTeBoeken is niet meegegeven, dan ophalen uit Vaste gegevens productie
           set @_PrdOkVulAantalDezeVerwerkingEindproduct = @RcpvVulAantalDezeVerwerkingEindproduct;
        end if;
        if @Document is null then
           // @Document is niet meegegeven, dan "leeg" opslaan
           set @_PrdOkDocument = '';
        else
           set @_PrdOkDocument = @Document;
        end if;
        if @Omschrijving is null then
           // @Omschrijving is niet meegegeven, dan "leeg" opslaan
           set @_PrdOkOmschrijving = '';
        else
           set @_PrdOkOmschrijving = @Omschrijving;
        end if;
        if @Opmerking is null then
           // @Opmerking is niet meegegeven, dan "leeg" opslaan
           set @_PrdOkOpmerking = '';
        else
           set @_PrdOkOpmerking = @Opmerking;
        end if;
     else
        //ReceptCode is wel meegegeven
        set @_PrdOkAantalRcptMinimum = @RcptBatchMinimum;
        set @_PrdOkAantalRcptMaximum = @RcptBatchMaximum;
        set @_PrdOkRcptCode = @RcptCode;
        set @_PrdOkRcptZoekCode = @RcptZoekcode;
        set @_PrdOkRcptSoort = @RcptSoort;
        if @AantalTeProduceren is null then
           // @AantalTeProduceren is niet meegegeven, dan aantal uit recept overnemen
           set @_PrdOkAantalRcpt = @RcptBatchDefault;
        else
           // @AantalTeProduceren is wel meegegeven, dan moet @AantalTeProduceren tussen minimum en maximum aantal uit recept liggen.
           if @RcptBatchMaximum = 0 then
               set @BatchMaximum = 9999999999;
           else
               set @BatchMaximum = @RcptBatchMaximum;
           end if;
           if @AantalTeProduceren < @RcptBatchMinimum then
              call Raise(20701, _U('%1! moet groter of gelijk zijn aan minimum aantal', 'AantalTeProduceren')); // (20701) Ongeldige combinatie: %1!;
           else
              if @AantalTeProduceren > @BatchMaximum then
                 call Raise(20701, _U('%1! moet kleiner of gelijk zijn aan maximum aantal', 'AantalTeProduceren')); // (20701) Ongeldige combinatie: %1!;
              else
                 set @_PrdOkAantalRcpt = @AantalTeProduceren;
              end if;
           end if;
        end if;
        if @Status is null then
           // @Status is niet meegegeven, dan overnemen uit recept.
           set @_PrdOkStatus = @RcptDefaultProductieOrderStatus;
        end if;
        if @RekeningnummerProductieResultaat is null then
           // @RekeningnummerProductieResultaat niet meegegeven, dan overnemen uit het Recept
           set @_PrdOkRksGidProdResultaat = @RcptRksGid;
        end if;
        if @DefaultAantalNuAfTeBoeken is null or @RcptSoort = 0 then          // 0 = Samenstelling, dan meegegeven @DefaultAantalNuAfTeBoeken negeren
           // @DefaultAantalNuAfTeBoeken is niet meegegeven of Receptsoort = Samenstelling, dan overnemen uit het recept
           set @_PrdOkVulAantalDezeVerwerkingComponent = @RcptVulAantalDezeVerwerkingComponent;
        end if;
        if @DefaultAantalNuOpTeBoeken is null or @RcptSoort = 0 then          // 0 = Samenstelling, dan meegegeven @DefaultAantalNuOpTeBoeken negeren
           // @DefaultAantalNuOpTeBoeken is niet meegegeven of Receptsoort = Samenstelling, dan overnemen uit het recept, dan overnemen uit het recept
           set @_PrdOkVulAantalDezeVerwerkingEindproduct = @RcptVulAantalDezeVerwerkingEindproduct;
        end if;
        if @Document is null then
           // @Document is niet meegegeven, dan overnemen uit het recept
           set @_PrdOkDocument = @RcptDocument;
        else
           set @_PrdOkDocument = @Document;
        end if;
        if @Omschrijving is null then
           // @Omschrijving is niet meegegeven, dan overnemen uit het recept
           set @_PrdOkOmschrijving = @RcptOmschrijving;
        else
           set @_PrdOkOmschrijving = @Omschrijving;
        end if;
        if @Opmerking is null then
           // @Opmerking is niet meegegeven, dan overnemen uit het recept
           set @_PrdOkOpmerking = @RcptOpmerking;
        else
           set @_PrdOkOpmerking = @Opmerking;
        end if;
     end if;      // Einde if @ReceptCode is null
  end if;         // Einde if @Mode = _TOEVOEGEN

  // --------------------------------
  // --- EXPLICIET VOOR WIJZIGEN ---
  // --------------------------------
  if @Mode = _WIJZIGEN then
    //Controle: @ProductieorderNummer bestaat niet
    if @_PrdOkGid is null then
      call Raise(20720,  'ProductieorderNummer') ;  // (20780) %1 niet gevonden!
    end if;
  end if;

  // --------------------------
  // --- ALGEMENE CONTROLES ---
  // --------------------------

  // Controle op status Gereed
  if ((@_PrdOkStatus = 4) /* 4 = Gereed */ and (isnull(@Status,'') not in ('NIEUW','IN_TE_PLANNEN','INGEPLAND','ONDERHANDEN'))) then
    call Raise(20780, _U('Productieorder wijzigen is'),_U('Productieorder heeft status Gereed')); // (20780) %1! niet mogelijk: %2!
  end if;

  // Controle op Status
  if @Status is not null then
    case @Status
      when 'NIEUW'         then set @_PrdOkStatus = 0; // 0 = Nieuw
      when 'IN_TE_PLANNEN' then set @_PrdOkStatus = 1; // 1 = In te plannen
      when 'INGEPLAND'     then set @_PrdOkStatus = 2; // 2 = Ingepland
      when 'ONDERHANDEN'   then set @_PrdOkStatus = 3; // 3 = Onderhanden
    else
      call Raise(20760, @Status);  // (20760) Ongeldige status: %1!
    end case;
  end if;

  // Controle op RekeningnummerProductieResultaat
  if @RekeningnummerProductieResultaat is not null then
     (select first RksGid into @_PrdOkRksGidProdResultaat from tabRekeningSchema where RksInvoer = @RekeningnummerProductieResultaat);
     if @_PrdOkRksGidProdResultaat is null then
        call Raise(20720,  'RekeningnummerProductieResultaat') ;  // (20780) %1 niet gevonden!
     end if;
  end if;

  // Controle op DefaultAantalNuAfTeBoeken
  if @DefaultAantalNuAfTeBoeken is not null then
     if isnull(@RcptSoort,1) = 1 then                // 1 = Productie, alleen overnemen indien Receptsoort = Productie, bij Samenstelling @DefaultAantalNuAfTeBoeken dan negeren
        case @DefaultAantalNuAfTeBoeken
          when 'NIET_AANPASSEN'   then set @_PrdOkVulAantalDezeVerwerkingComponent = 0;  // 0 = Niet aanpassen
          when 'NOG_AF_TE_BOEKEN' then set @_PrdOkVulAantalDezeVerwerkingComponent = 1;  // 1 = Nog af te boeken
        else
          call Raise(20700, 'DefaultAantalNuAfTeBoeken'); // (20700) Ongeldige waarde: %1!;
        end case;
     end if;
  end if;

  // Controle op DefaultAantalNuOpTeBoeken
  if @DefaultAantalNuOpTeBoeken is not null then
     if isnull(@RcptSoort,1) = 1 then                // 1 = Productie, alleen overnemen indien Receptsoort = Productie, bij Samenstelling @DefaultAantalNuOpTeBoeken dan negeren
        case @DefaultAantalNuOpTeBoeken
          when 'NIET_AANPASSEN'   then set @_PrdOkVulAantalDezeVerwerkingEindproduct = 0;  // 0 = Niet aanpassen
          when 'NOG_OP_TE_BOEKEN' then set @_PrdOkVulAantalDezeVerwerkingEindproduct = 1;  // 1 = Nog op te boeken
        else
          call Raise(20700, 'DefaultAantalNuOpTeBoeken'); // (20700) Ongeldige waarde: %1!;
        end case;
     end if;
  end if;

  // Controle op Startdatum mag niet na Te produceren voor datum liggen
  if isnull(@TeProducerenVoor, @StartdatumProductie) is not null then // Als een van de ingevoerde waarden gevuld is, dan controleren
    if isnull(@TeProducerenVoor, @_PrdOkTeProducerenVoor) < isnull(@StartdatumProductie, @_PrdOkProductieStartOp) then
      call Raise(20701, _U('Startdatum ligt na de te produceren voor datum.')); // (20701) Ongeldige combinatie: %1!;
    end if;
  end if;

  // Controle op TeProducerenDoor
  if @TeProducerenDoor = '' then // Bewust leegmaken
    set @_TeProducerenDoor = '';
  else
    if isnull(@TeProducerenDoor,'') <> '' then // anders.. Gebruiker moet bestaan
      set @_TeProducerenDoor = (select first NaamGebruiker from tabGebruiker where NaamGebruiker = @TeProducerenDoor);
      if (@_TeProducerenDoor is null) then
        call Raise(20720,  'TeProducerenDoor') ;  // (20780) %1 niet gevonden!
      end if;
    end if;
  end if;

  // Datum velden
  set @_PrdOkTeProducerenVoor = (select DateTimeConversieVoorWebServices(@TeProducerenVoor, @_PrdOkTeProducerenVoor));
  set @_PrdOkProductieStartOp = (select DateTimeConversieVoorWebServices(@StartdatumProductie, @_PrdOkProductieStartOp));

end;



create or replace procedure WebSvcProc_Productieorder_Component_Toevoegen
( in @ProductieorderNummer       numeric(10,0),
  in @RegelSoort                 nchar(5),
  in @ArtikelNummer              nchar(20),
  in @PartijNummer               nchar(20),
  in @Omschrijving               long nvarchar,
  in @MagazijnCode               numeric(3,0),
  in @StandaardSpecificatieRegel nchar(3),
  in @Locatiecode                nchar(20),
  in @TotaalAfTeBoeken           numeric(15,3),
  in @NuAfTeBoeken               numeric(15,3),
  in @WaarvanUitval              numeric(15,3))

result (RegelNummer integer,
        RegelID     integer )

begin
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;

  declare @RegelNummer                integer;
  declare @RegelID                    integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Component_Toevoegen > begin';

  // Module controle
  if IsModuleActive('r2') = 0 then                    // Module Productie-1 (samengestelde artikelen vereist)
    call Raise(20790,_U('Optie Productie-1'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r3') = 0 then                    // Module Productie-2 (productie-1 vereist)
    call Raise(20790,_U('Optie Productie-2'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r4') = 0 then                    // Module Samengestelde artikelen (nodig voor productie-1)
    call Raise(20790,_U('Optie Samengestelde artikelen'));  // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    declare @PrdOkGid                            integer;
    declare @PrdOkNummer                         numeric(10,0);
    declare @PrdOkStatus                         smallint;
    declare @PrdOkRcptSoort                      smallint;
    declare @PrdOkDefMagGidComponent             integer;
    declare @ArtGid                              integer;
    declare @ArtAantDecAantallen                 smallint;
    declare @ArtIsPartijRegistreren              smallint;
    declare @ArtPartijGid                        integer;
    declare @MagGid                              integer;
    declare @LocGid                              integer;
    declare @ArtMagDefaultLocGid                 integer;
    declare @ControleDecimalen                   numeric(15,3);
    declare @DefaultSpecificatieRegel            smallint;

    // tabProductieOrderComponent
    declare @_PrdOcPrdOkGid                      integer;
    declare @_PrdOcRegelSoort                    smallint;
    declare @_PrdOcArtGid                        integer;
    declare @_PrdOcArtPartijGid                  integer;
    declare @_PrdOcLocGid                        integer;
    declare @_PrdOcMagGid                        integer;
    declare @_PrdOcOmschrijving                  long nvarchar;
    declare @_PrdOcAantalDezeVerwerking          numeric(15,3);
    declare @_PrdOcAantalTotaalTeVerwerken       numeric(15,3);
    declare @_PrdOcAantalUitvalInDezeVerwerking  numeric(15,3);
    declare @_PrdOcRcpAantal                     numeric(15,3);
    declare @_PrdOcRcpVerbruik                   smallint;
    declare @_PrdOcRcpVerbruikAantal             numeric(15,3);
    declare @_PrdOcRegelNr                       smallint;

    // tabProductieOrderComponentSpec
    declare @_PrdOcsPrdOcGid                     integer;
    declare @_PrdOcsArtPartijGid                 integer;
    declare @_PrdOcsLocGid                       integer;
    declare @_PrdOcsMagGid                       integer;
    declare @_PrdOcsAantalDezeVerwerking         numeric(15,3);
    declare @_PrdOcsAantalTotaalTeVerwerken      numeric(15,3);
    declare @_PrdOcsAantalUitvalInDezeVerwerking numeric(15,3);


    // Opzoeken onderhanden Productie order
    select PrdOkGid,
           PrdOkNummer,
           PrdOkStatus,
           PrdOkRcptSoort,
           PrdOkDefMagGidComponent
    into   @PrdOkGid,
           @PrdOkNummer,
           @PrdOkStatus,
           @PrdOkRcptSoort,
           @PrdOkDefMagGidComponent
    from   tabProductieOrderKop
    where  PrdOkNummer = @ProductieorderNummer;
    if  @PrdOkGid is null then
        call Raise(20780,_U('Component toevoegen is'),_U('Ongeldige of geen %1! meegegeven', 'ProductieorderNummer'));      // (20780) %1! niet mogelijk: %2!
    end if;
    if  @PrdOkStatus = 4 then       // 4 = Gereed
        call Raise(20780,_U('Component toevoegen is'),_U('Productieorder heeft status Gereed'));      // (20780) %1! niet mogelijk: %2!
    end if;

    // Gevonden Productieorder locken of bestaande lock overnemen
    call WebSvcHulpProc_ProductieorderExclusiefLocken(@PrdOkGid,@LockUserNaam,@SpId,@LoginTime);

    // ProductieOrderKopGid over
    set @_PrdOcPrdOkGid = @PrdOkGid;

    // Controle: @RegelSoort moet 'ART', 'TAR' of 'TEKST' zijn
    case
        when isnull(@RegelSoort,'') = 'ART'   then set @_PrdOcRegelSoort = 2;   // 2 = Artikel
        when isnull(@RegelSoort,'') = 'TAR'   then set @_PrdOcRegelSoort = 1;   // 1 = Tarief
        when isnull(@RegelSoort,'') = 'TEKST' then set @_PrdOcRegelSoort = 0;   // 0 = Tekstblok
        else call Raise(20700,'RegelSoort');   // (20700) Ongeldige waarde: %1!
    end case;

    // Controle: Combinatie van @_PrdOcRegelSoort = 1 (Tarief) en @PrdOkRcptSoort = 0 (Samenstelling) is niet toegestaan
    if  (@_PrdOcRegelSoort = 1) and (@PrdOkRcptSoort = 0) then
        call Raise(20701,_U('%1! %2! is niet toegestaan in combinatie met %3! %4!.', 'RegelSoort', 'TAR', 'ReceptSoort', 'SAMENSTELLING'));   // (20701) Ongeldige combinatie: %1!
    end if;

    // Controle: @ArtikelNummer moet zijn meegegeven i.c.m. Artikel of Tarief bij respectievelijk 'ART' en 'TAR'
    if  isnull(@ArtikelNummer,'') = '' and @_PrdOcRegelSoort <> 0 then      // 0 = Tekstblok
        call Raise(20700,'ArtikelNummer');   // (20700) Ongeldige waarde: %1!
    end if;

    // Ophalen van de benodigde Artikelgegevens o.b.v. meegegeven @ArtikelNummer en @RegelSoort
    if  isnull(@ArtikelNummer,'') <> '' then
        select ArtGid,
               ArtAantDecAantallen,
               ArtIsPartijRegistreren
        into   @ArtGid,
               @ArtAantDecAantallen,
               @ArtIsPartijRegistreren
        from   tabArtikel
        where  ArtCode = @ArtikelNummer
        and    ArtSoort = @_PrdOcRegelSoort;
        // Controle: Meegegeven @ArtilkelNummer moet een bestaande artikel, tarief of tekstblok zijn.
        if  @ArtGid is null then
            call Raise(20720,'ArtikelNummer');   // (20720) %1! niet gevonden!
        else
            set @_PrdOcArtGid = @ArtGid;
        end if;
    end if;

    // Controle: Indien @Omschrijving niet is meegegeven, dan 'Tekst op factuur' van artikel/tarief/tekstblok toepassen o.b.v. de standaard taalcode van de administratie.
    if  isnull(@Omschrijving,'') <> '' then
        set @_PrdOcOmschrijving = @Omschrijving;
    else
        if  @_PrdOcArtGid is not null then
            set @_PrdOcOmschrijving = isnull((select ArtTekst
                                              from   tabArtikelTeksten
                                              where  ArtTekstArtGid = @_PrdOcArtGid
                                              and    ArtTaalGid = (select DefaultTaalGid from tabVasteGegevens)),'');   // DefaultTaalGid is de standaard TaalGid van de administratie
            else
                set @_PrdOcOmschrijving = '';
        end if;
    end if;

    // Controle: Meegegeven @PartijNummer i.c.m. met artikel, die niet Partijregistrerend is, is niet toegestaan.
    if  isnull(@PartijNummer,'') <> '' and @ArtIsPartijRegistreren = 0 then     // 0 = Artikel is niet partijregistrerend
        if  @_PrdOcRegelSoort = 2 then
            call Raise(20701,_U('Partijnummer is niet toegestaan, artikel is niet partijregistrerend'));    // (20701) Ongeldige combinatie: %1!
        else
            call Raise(20701,_U('Partijnummer is niet toegestaan in combinatie met tarief of tekstblok'));    // (20701) Ongeldige combinatie: %1!
        end if;
    end if;

    // Controle: Indien @Partijnummer is meegegeven, dan moet het een bestaande partijnummer zijn binnen het artikel.
    if  isnull(@PartijNummer,'') <> '' then
        select ArtPartijGid
        into   @ArtPartijGid
        from   tabArtikelPartij
        where  ArtPartijArtGid = @_PrdOcArtGid
        and    ArtPartijNummer = @PartijNummer;
        if  @ArtPartijGid is null then
            call Raise(20720,'PartijNummer');   // (20720) %1! niet gevonden!
        else
            set @_PrdOcArtPartijGid  = @ArtPartijGid;
            set @_PrdOcsArtPartijGid = @ArtPartijGid;
        end if;
    end if;

    // Controle: Indien @MagazijnCode is meegegeven, dan moet dit een bestaande magazijn zijn.
    if  @MagazijnCode is not null then
        if  @_PrdOcRegelSoort = 2 then      // 2 = Artikel
            select MagGid
            into   @MagGid
            from   tabMagazijn
            where  MagCode = @MagazijnCode;
            if  @MagGid is null then
                call Raise(20720,'MagazijnCode');   // (20720) %1! niet gevonden!
            else
                set @_PrdOcMagGid  = @MagGid;
                set @_PrdOcsMagGid = @MagGid;
            end if;
        else
            // MagazijnCode is niet toegestaan i.c.m. een tarief of tekstblok
            call Raise(20701,_U('%1! is niet toegestaan in combinatie met tarief of tekstblok', 'MagazijnCode'));    // (20701) Ongeldige combinatie: %1!
        end if;
    else
        if  @_PrdOcRegelSoort = 2 then      // 2 = Artikel
            // @MagazijnCode is niet meegegeven, dan Default magazijn Componenten van de productieorder toepassen
            set @_PrdOcMagGid  = @PrdOkDefMagGidComponent;
            set @_PrdOcsMagGid = @PrdOkDefmagGidComponent;
        end if;
    end if;

    // Controle: Indien @Locatiecode is meegegeven, dan moet dit een bestaande locatie zijn binnen het betreffende magazijn
    if  isnull(@Locatiecode,'') <> '' then
        if  @_PrdOcRegelSoort = 2 then      // 2 = Artikel
            select LocGid
            into   @LocGid
            from   tabLocatie
            where  LocMagGid = @_PrdOcMagGid
            and    LocNaam   = @Locatiecode;
            if  @LocGid is null then
                call Raise(20720,'Locatiecode');   // (20720) %1! niet gevonden!
            else
                set @_PrdOcLocGid  = @LocGid;
                set @_PrdOcsLocGid = @LocGid;
            end if;
        else
            // Locatiecode is niet toegestaan i.c.m. een tarief of tekstblok
            call Raise(20701,_U('%1! is niet toegestaan in combinatie met tarief of tekstblok', 'Locatiecode'));    // (20701) Ongeldige combinatie: %1!
        end if;
    else
        if  @_PrdOcRegelSoort = 2 then      // 2 = Artikel
            // @Locatiecode is niet meegegeven, dan eerst proberen de Default locatie van het artikel op te halen.
            select ArtMagDefaultLocGid
            into   @ArtMagDefaultLocGid
            from   tabArtikelMagazijn
            where  ArtMagMagGid = @_PrdOcMagGid
            and    ArtMagArtGid = @_PrdOcArtGid;
            if  @ArtMagDefaultLocGid is not null then
                // Artikel heeft een Default locatie, dan gaan wij die ook toepassen.
                set @_PrdOcLocGid  = @ArtMagDefaultLocGid;
                set @_PrdOcsLocGid = @ArtMagDefaultLocGid;
            else
                // Artikel heeft geen Default locatie, dan wordt de locatie (Standaard) binnen het magazijn toegepast.
                select LocGid
                into   @LocGid
                from   tabLocatie
                where  LocMagGid = @_PrdOcMagGid
                and    LocNaam   = '(Standaard)';
                if  @LocGid is not null then
                    set @_PrdOcLocGid  = @LocGid;
                    set @_PrdOcsLocGid = @LocGid;
                else
                    // Geen geldige locatie gevonden, dan moet er een geldige @Locatiecode worden meegegeven.
                    call Raise(20700,'Locatiecode');   // (20700) Ongeldige waarde: %1!
                end if;
            end if;
        end if;
    end if;

    // Controle: @TotaalAfTeBoeken is verplicht tijdens het toevoegen van nieuwe component van @RegelSoort TAR (1) of ART (2)
    //           Ook wordt @TotaalAfTeBoeken gecontroleerd op het meegegeven aantal decimalen o.b.v. de Artikelgegevens
    if  @_PrdOcRegelSoort in (1,2) then   // Uitsluitend i.c.m. Tarief (1) of Artikel (2)
        if  isnull(@TotaalAfTeBoeken,0) = 0 then  // Aantal moet ongelijk zijn aan 0
            call Raise(20700,'TotaalAfTeBoeken');   // (20700) Ongeldige waarde: %1!
        else
            set @ControleDecimalen = truncnum(@TotaalAfTeBoeken,@ArtAantDecAantallen);      // Controleren op meegegeven waarde in decimalen
            if  (@ControleDecimalen - @TotaalAfTeBoeken) <> 0 then
                call Raise(20780,_U('Component toevoegen is'),_U('Teveel decimalen in %1! meegegeven!', 'TotaalAfTeBoeken'));   // (20780) %1! niet mogelijk: %2!
            else
                set @_PrdOcAantalTotaalTeVerwerken  = @TotaalAfTeBoeken;
                set @_PrdOcsAantalTotaalTeVerwerken = @TotaalAfTeBoeken;
            end if;
        end if;
    else
        // Tekstblok van toepassing, aantal is dan 0
        set @_PrdOcAantalTotaalTeVerwerken  = 0;
        set @_PrdOcsAantalTotaalTeVerwerken = 0;
    end if;

    // Controle: @NuAfTeBoeken is verplicht tijdens het toevoegen van nieuwe component van RegelSoort TAR (1) of ART (2)
    //           Ook wordt @NuAfTeBoeken gecontroleerd op het aantal decimalen o.b.v. de Artikelgegevens
    if  @_PrdOcRegelSoort in (1,2) then   // Uitsluitend i.c.m. Tarief (1) of Artikel (2)
        if @NuAfTeBoeken is null then     // Aantal moet ongelijk zijn aan 0
            call Raise(20700,'NuAfTeBoeken');   // (20700) Ongeldige waarde: %1!
        else
            set @ControleDecimalen = truncnum(@NuAfTeBoeken,@ArtAantDecAantallen);       // Controleren op meegegeven waarde in decimalen
            if  (@ControleDecimalen - @NuAfTeBoeken) <> 0 then
                call Raise(20780,_U('Component toevoegen is'),_U('Teveel decimalen in %1! meegegeven!', 'NuAfTeBoeken'));   // (20780) %1! niet mogelijk: %2!
            else
                set @_PrdOcAantalDezeVerwerking  = @NuAfTeBoeken;
                set @_PrdOcsAantalDezeVerwerking = @NuAfTeBoeken;
            end if;
        end if;
    else
        // Tekstblok van toepassing, aantal is dan 0
        set @_PrdOcAantalDezeVerwerking  = 0;
        set @_PrdOcsAantalDezeVerwerking = 0;
    end if;

    // Controle: @NuAfTeBoeken mag niet groter zijn dat @TotaalAfTeBoeken
    if  @_PrdOcAantalDezeVerwerking > @_PrdOcAantalTotaalTeVerwerken then
        call Raise(20780,_U('Component toevoegen is'),_U('Aantal %1! is groter dan aantal %2!', 'NuAfTeBoeken', 'TotaalAfTeBoeken'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Controle: @WaarvanUitval is verplicht tijdens het toevoegen van nieuwe component van RegelSoort ART (2)
    //           Ook wordt @WaarvanUitval gecontroleerd op het aantal decimalen o.b.v. de Artikelgegevens
    if  @_PrdOcRegelSoort = 2 then    // Uitsluitend i.c.m. Artikel (2)
        if  @WaarvanUitval is null then    // I.c.m. artikel moet een geldige waarde worden meegegeven
            call Raise(20700,'WaarvanUitval');   // (20700) Ongeldige waarde: %1!
        else
            set @ControleDecimalen = truncnum(@WaarvanUitval,@ArtAantDecAantallen);       // Controleren op meegegeven waarde in decimalen
            if  (@ControleDecimalen - @WaarvanUitval) <> 0 then
                call Raise(20780,_U('Component toevoegen is'),_U('Teveel decimalen in %1! meegegeven!', 'WaarvanUitval'));   // (20780) %1! niet mogelijk: %2!
            else
                set @_PrdOcAantalUitvalInDezeVerwerking  = @WaarvanUitval;
                set @_PrdOcsAantalUitvalInDezeVerwerking = @WaarvanUitval;
            end if;
        end if;
    end if;

    // Controle: @WaarvanUitval mag niet groter zijn dat @NuAfTeBoeken
    if  @_PrdOcAantalUitvalInDezeVerwerking > @_PrdOcAantalDezeVerwerking then
        call Raise(20780,_U('Component toevoegen is'),_U('Aantal %1! is groter dan aantal %2!', 'WaarvanUitval', 'NuAfTeBoeken'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Teken van TotaalOpTeBoeken, NuOpTeBoeken en WaarvanUitval moet gelijk zijn
    if sign(@_PrdOcAantalTotaalTeVerwerken /*Mag toch niet 0 zijn*/) <> sign(@_PrdOcAantalDezeVerwerking) and @_PrdOcAantalDezeVerwerking <> 0 then
        call Raise(20780,_U('Component toevoegen is'),_U('De tekens van %1! en %2! zijn ongelijk', 'TotaalAfTeBoeken', 'NuAfTeBoeken'));   // (20780) %1! niet mogelijk: %2!
    end if;
    if sign(@_PrdOcAantalTotaalTeVerwerken /*Mag toch niet 0 zijn*/) <> sign(@_PrdOcAantalUitvalInDezeVerwerking) and @_PrdOcAantalUitvalInDezeVerwerking <> 0 then
        call Raise(20780,_U('Component toevoegen is'),_U('De tekens van %1! en %2! zijn ongelijk', 'TotaalAfTeBoeken', 'WaarvanUitval'));   // (20780) %1! niet mogelijk: %2!
    end if;


    // Controle: Indien @StandaardSpecificatieRegel is meegegeven, dan moet dit wel "JA" of "NEE" zijn.
    //           Indien @StandaardSpecificatieRegel niet is meegegeven, dan is de default waarde "JA"
    case
      when isnull(@StandaardSpecificatieRegel,'JA') = 'JA'
      then set @DefaultSpecificatieRegel = 1;                 // 1 = Wel default specificatieregel
      when isnull(@StandaardSpecificatieRegel,'JA') = 'NEE'
      then set @DefaultSpecificatieRegel = 0;                 // 0 = Geen default specificatieregel
      else call Raise(20700,'StandaardSpecificatieRegel');      // (20700) Ongeldige waarde: %1!
    end case;

    // Recept gegevens initialiseren, omdat hier geen recept van toepassing is.
    if  @_PrdOcRegelSoort in (1,2) then   // Uitsluitend i.c.m. Tarief (1) of Artikel (2)
        set @_PrdOcRcpAantal = 1;         // Aantal 1 indien Tarief (1) of Artikel (2)
    else
        set @_PrdOcRcpAantal = 0;         // Aantal 0 indien Tekstblok (0)
    end if;
    set @_PrdOcRcpVerbruik       = -1;    // -1 = Directe invoer
    set @_PrdOcRcpVerbruikAantal =  0;    // Altijd 0


    // Genereer regelnummer t.b.v. Componentregel
    select isnull((max(PrdOcRegelNr) + 1),1) into @_PrdOcRegelNr from tabProductieOrderComponent where PrdOcPrdOkGid = @PrdOkGid;
    // Controle: Regelnummer mag niet groter zijn, dan 999
    if  @_PrdOcRegelNr > 999 then
        call Raise(20780,_U('Component toevoegen is'),_U('Hoogste regelnummer %1! is al bereikt', '999'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Gegevens bijwerken in de database
    // Componentregel toevoegen
    insert into tabProductieOrderComponent with auto name
    select @_PrdOcArtGid                       as PrdOcArtGid,
           @_PrdOcArtPartijGid                 as PrdOcArtPartijGid,
           @_PrdOcLocGid                       as PrdOcLocGid,
           @_PrdOcMagGid                       as PrdOcMagGid,
           @_PrdOcPrdOkGid                     as PrdOcPrdOkGid,
           @_PrdOcAantalDezeVerwerking         as PrdOcAantalDezeVerwerking,
           0                                   as PrdOcAantalReedsVerwerkt,
           @_PrdOcAantalTotaalTeVerwerken      as PrdOcAantalTotaalTeVerwerken,
           @_PrdOcAantalUitvalInDezeVerwerking as PrdOcAantalUitvalInDezeVerwerking,
           0                                   as PrdOcAantalUitvalInReedsVerwerkt,
           0                                   as PrdOcBedragReedsVerwerkt,
           0                                   as PrdOcBedragUitvalInReedsVerwerkt,
           @_PrdOcRcpAantal                    as PrdOcRcpAantal,
           @_PrdOcRcpVerbruik                  as PrdOcRcpVerbruik,
           @_PrdOcRcpVerbruikAantal            as PrdOcRcpVerbruikAantal,
           @_PrdOcRegelNr                      as PrdOcRegelNr,
           @_PrdOcRegelSoort                   as PrdOcRegelSoort,
           @_PrdOcOmschrijving                 as PrdOcOmschrijving;
    set @_PrdOcsPrdOcGid = @@identity;

    // Componentspecificatieregel conditioneel toevoegen
    if  @DefaultSpecificatieRegel = 1 and @_PrdOcRegelSoort = 2 then          // 1 = Wel Default specificatieregel    2 = Artikel
        insert into tabProductieOrderComponentSpec with auto name
        select @_PrdOcsPrdOcGid                     as PrdOcsPrdOcGid,
               @_PrdOcsArtPartijGid                 as PrdOcsArtPartijGid,
               null                                 as PrdOcsArtSerieGid,
               @_PrdOcsLocGid                       as PrdOcsLocGid,
               @_PrdOcsMagGid                       as PrdOcsMagGid,
               @_PrdOcsAantalDezeVerwerking         as PrdOcsAantalDezeVerwerking,
               0                                    as PrdOcsAantalReedsVerwerkt,
               @_PrdOcsAantalTotaalTeVerwerken      as PrdOcsAantalTotaalTeVerwerken,
               @_PrdOcsAantalUitvalInDezeVerwerking as PrdOcsAantalUitvalInDezeVerwerking,
               0                                    as PrdOcsAantalUitvalInReedsVerwerkt,
               0                                    as PrdOcsIsPartijNetAangemaakt,
               0                                    as PrdOcsIsSerieNetAangemaakt;
    end if;

    // Regelnummer en PrdOcGid overnemen t.b.v. het resultaat
    // en hier NIET als select teruggeven, want we zitten in een atomic begin..end
    set @RegelNummer = @_PrdOcRegelNr;
    set @RegelID     = @_PrdOcsPrdOcGid;

  end;    // Einde atomic

  // Ophalen Resultaat
  select @RegelNummer as RegelNummer,
         @RegelID     as RegelID;


  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Component_Toevoegen > eind';
end;


create or replace procedure WebSvcProc_Productieorder_Component_Verwijderen
( in @ProductieorderNummer       numeric(10,0),
  in @RegelNummer                integer,
  in @RegelID                    integer )
begin
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;

  declare @_PrdOkGid integer;
  declare @_PrdOcGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Component_Verwijderen > begin';

  // Module controle
  if IsModuleActive('r2') = 0 then                    // Module Productie-1 (samengestelde artikelen vereist)
    call Raise(20790,'Optie Productie-1');              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r3') = 0 then                    // Module Productie-2 (productie-1 vereist)
    call Raise(20790,'Optie Productie-2');              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r4') = 0 then                    // Module Samengestelde artikelen (nodig voor productie-1)
    call Raise(20790,'Optie Samengestelde artikelen');  // (20790) '%1!' niet geactiveerd!
  end if;


  // ********************
  // Productie Order Kop
  // en Status checken
  // ********************
  begin
    call WebSvcHulpProc_Valideer_ProductieOrderEnStatus(
      /*in*/
      @ProductieorderNummer ,
      1                     , // Mag niet gereed zijn (status)
      /*out*/
      @_PrdOkGid            ,
      null                  ); // status productie-order

    // 0 = samenstelling, 1 = productie
    if exists ( select first 1 from tabProductieOrderKop where PrdOkGid = @_PrdOkGid and PrdOkRcptSoort = 0 ) then
      call Raise(20780, 'Component verwijderen', 'het betreft een samenstelling o.b.v. recept') ; // (20780)  <Actie> niet mogelijk: <Reden>.
    end if;
  end;

  // ******************************
  // Component
  // ******************************
  begin
    declare @SomReedsVerwerkt numeric(16,3); // een digit meer, vanwege het optellen van eventuele maximum waarden.

    // Componentregel: Nummer of RegelID, niet beide.
    if ( @RegelNummer is null and @RegelId is null ) then
      call Raise(20700,  'RegelNummer en RegelID, ze zijn niet ingevuld.');  // (20700) Ongeldige Waarde: %1
    end if;

    select  PrdOcGid
    ,       isnull(PrdOcAantalReedsVerwerkt, 0) + isnull(PrdOcAantalUitvalInReedsVerwerkt,0) + isnull(PrdOcBedragReedsVerwerkt,0) + isnull(PrdOcBedragUitvalInReedsVerwerkt,0)
      into  @_PrdOcGid
      ,     @SomReedsVerwerkt
    from tabProductieOrderComponent
    where PrdOcPrdOkGid = @_PrdOkGid
      and ( ( PrdOcRegelNr = @RegelNummer )                         // We werken bij voorrang met regelnummer
             or ( PrdOcGid = @RegelID and @RegelNummer is null ) ); // Is er geen regelnummer, dan RegelID gebruiken

    if @_PrdOcGid is null then
      if @RegelNummer is not null then
        call Raise(20720,  'RegelNummer') ;  // (20780) %1 niet gevonden!
      else
        call Raise(20720,  'RegelID') ;  // (20780) %1 niet gevonden!
      end if;
    end if;

    if ( @SomReedsVerwerkt <> 0 ) then
      call Raise(20780,  'Component verwijderen', 'is al verwerkt') ; // (20780)  <Actie> niet mogelijk: <Reden>.
    end if;

    // Niet verwijderen als het bij een ingevuld recept hoort dat een samenstelling betreft.
    // Productie-order zelf hoeft hier geen samenstelling te zijn ( PrdOkRcptSoort <> 0 )

  end ; // Component


  // ******************************
  // Verwijderen Component
  // ******************************

  begin atomic
    // eerst de productie-order exclusief locken
    call WebSvcHulpProc_ProductieorderExclusiefLocken( @_PrdOkGid, @LockUserNaam, @SpId, @LoginTime );

    // eerst de specificatieregels opruimen
    delete tabProductieOrderComponentSpec where PrdOcsPrdOcGid = @_PrdOcGid;

    // tot slot het component zelf
    delete tabProductieOrderComponent where PrdOcGid = @_PrdOcGid;

    // Productieorder blijft gelockt, in apart proces de lock vrijgeven

  end;  // einde atomic

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Component_Verwijderen > eind';
end;


create or replace procedure WebSvcProc_Productieorder_Component_Wijzigen
( in @ProductieorderNummer       numeric(10,0),
  in @RegelNummer                integer,
  in @RegelID                    integer,
  in @MagazijnCode               numeric(3,0),
  in @StandaardSpecificatieRegel nchar(3),
  in @Locatiecode                nchar(20),
  in @TotaalAfTeBoeken           numeric(15,3),
  in @NuAfTeboeken               numeric(15,3),
  in @WaarvanUitval              numeric(15,3))

begin
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;
  declare _TRUE  smallint = 1;
  declare _FALSE smallint = 0;

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Component_Wijzigen > begin';

  // Module controle
  if IsModuleActive('r2') = 0 then                    // Module Productie-1 (samengestelde artikelen vereist)
    call Raise(20790,_U('Optie Productie-1'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r3') = 0 then                    // Module Productie-2 (productie-1 vereist)
    call Raise(20790,_U('Optie Productie-2'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r4') = 0 then                    // Module Samengestelde artikelen (nodig voor productie-1)
    call Raise(20790,_U('Optie Samengestelde artikelen'));  // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    declare @PrdOkGid                            integer;
    declare @PrdOkNummer                         numeric(10,0);
    declare @PrdOkStatus                         smallint;
    declare @PrdOkRcptSoort                      smallint;
    declare @PrdOkDefMagGidComponent             integer;
    declare @ArtGid                              integer;
    declare @ArtAantDecAantallen                 smallint;
    declare @MagGid                              integer;
    declare @LocGid                              integer;
    declare @ArtMagDefaultLocGid                 integer;
    declare @_DefaultSpecificatieRegel            smallint;
    declare @MagazijnIsGewijzigd                 smallint;
    declare @ControleDecimalen                   numeric(15,3);

    // tabProductieOrderComponent
    declare @_PrdOcGid                           integer;
    declare @_PrdOcArtGid                        integer;
    declare @_PrdOcArtPartijGid                  integer;
    declare @_PrdOcLocGid                        integer;
    declare @_PrdOcMagGid                        integer;
    declare @_PrdOcPrdOkGid                      integer;
    declare @_PrdOcAantalDezeVerwerking          numeric(15,3);
    declare @_PrdOcAantalReedsVerwerkt           numeric(15,3);
    declare @_PrdOcAantalTotaalTeVerwerken       numeric(15,3);
    declare @_PrdOcAantalUitvalInDezeVerwerking  numeric(15,3);
    declare @_PrdOcAantalUitvalInReedsVerwerkt   numeric(15,3);
    declare @_PrdOcBedragReedsVerwerkt           numeric(15,3);
    declare @_PrdOcBedragUitvalInReedsVerwerkt   numeric(15,3);
    declare @_PrdOcRcpAantal                     numeric(15,3);
    declare @_PrdOcRcpVerbruik                   smallint;
    declare @_PrdOcRcpVerbruikAantal             numeric(15,3);
    declare @_PrdOcRegelNr                       smallint;
    declare @_PrdOcRegelSoort                    smallint;
    declare @_PrdOcOmschrijving                  long nvarchar;

    // tabProductieOrderComponentSpec
    declare @_PrdOcsGid                          integer;
    declare @_PrdOcsArtPartijGid                 integer;
    declare @_PrdOcsArtSerieGid                  integer;
    declare @_PrdOcsLocGid                       integer;
    declare @_PrdOcsMagGid                       integer;
    declare @_PrdOcsPrdOcGid                     integer;
    declare @_PrdOcsAantalDezeVerwerking         numeric(15,3);
    declare @_PrdOcsAantalReedsVerwerkt          numeric(15,3);
    //declare @_PrdOcsAantalTotaalTeVerwerken      numeric(15,3); Doet nu toch al niks, dan maar helemaal weg
    declare @_PrdOcsAantalUitvalInDezeVerwerking numeric(15,3);
    declare @_PrdOcsAantalUitvalInReedsVerwerkt  numeric(15,3);
    declare @_PrdOcsIsPartijNetAangemaakt        smallint;
    declare @_PrdOcsIsSerieNetAangemaakt         smallint;

    // Opzoeken onderhanden Productieorder
    select PrdOkGid,
           PrdOkNummer,
           PrdOkStatus,
           PrdOkRcptSoort,
           PrdOkDefMagGidComponent
    into   @PrdOkGid,
           @PrdOkNummer,
           @PrdOkStatus,
           @PrdOkRcptSoort,
           @PrdOkDefMagGidComponent
    from   tabProductieOrderKop
    where  PrdOkNummer = @ProductieorderNummer;
    if  @PrdOkGid is null then
        call Raise(20700,'ProductieorderNummer');      // (20700) Ongeldige waarde: %1!
    end if;
    if  @PrdOkStatus = 4 then        // 4 = Gereed
        call Raise(20780,_U('Component wijzigen is'),_U('Productieorder heeft status Gereed'));      // (20780) %1! niet mogelijk: %2!
    end if;

    // Gevonden Productieorder locken of bestaande lock overnemen
    call WebSvcHulpProc_ProductieorderExclusiefLocken(@PrdOkGid,@LockUserNaam,@SpId,@LoginTime);

    // Controle: @RegelNummer of @RegelID moet zijn meegegeven
    if  @RegelNummer is null and @RegelID is null then
        call Raise(20700,_U('%1! en %2!', 'RegelNummer', 'RegelID'));    // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: @Regelnummer of @RegelID moet een geldige waarde bevatten.
    select first
           PrdOcGid,
           PrdOcArtGid,
           PrdOcArtPartijGid,
           PrdOcLocGid,
           PrdOcMagGid,
           PrdOcPrdOkGid,
           PrdOcAantalDezeVerwerking,
           PrdOcAantalReedsVerwerkt,
           PrdOcAantalTotaalTeVerwerken,
           PrdOcAantalUitvalInDezeVerwerking,
           PrdOcAantalUitvalInReedsVerwerkt,
           PrdOcBedragReedsVerwerkt,
           PrdOcBedragUitvalInReedsVerwerkt,
           PrdOcRcpAantal,
           PrdOcRcpVerbruik,
           PrdOcRcpVerbruikAantal,
           PrdOcRegelNr,
           PrdOcRegelSoort,
           PrdOcOmschrijving
    into   @_PrdOcGid,
           @_PrdOcArtGid,
           @_PrdOcArtPartijGid,
           @_PrdOcLocGid,
           @_PrdOcMagGid,
           @_PrdOcPrdOkGid,
           @_PrdOcAantalDezeVerwerking,
           @_PrdOcAantalReedsVerwerkt,
           @_PrdOcAantalTotaalTeVerwerken,
           @_PrdOcAantalUitvalInDezeVerwerking,
           @_PrdOcAantalUitvalInReedsVerwerkt,
           @_PrdOcBedragReedsVerwerkt,
           @_PrdOcBedragUitvalInReedsVerwerkt,
           @_PrdOcRcpAantal,
           @_PrdOcRcpVerbruik,
           @_PrdOcRcpVerbruikAantal,
           @_PrdOcRegelNr,
           @_PrdOcRegelSoort,
           @_PrdOcOmschrijving
    from   tabProductieOrderComponent
    where  PrdOcPrdOkGid = @PrdOkGid            // Onderhanden productieorder
    and    (   (@Regelnummer is not null and PrdOcRegelNr  = @RegelNummer)        // Meegegeven @RegelNummer
            or (@Regelnummer is     null and PrdOcGid = @RegelID)
           );
    if  @_PrdOcGid is null then
      if @Regelnummer is null then
        call Raise(20720,'RegelID');   // (20720) %1! niet gevonden!
      else
        call Raise(20720,'RegelNummer');   // (20720) %1! niet gevonden!
      end if;
    end if;

    // Controle: Indien @StandaardSpecificatieRegel is meegegeven, dan moet dit wel "JA" of "NEE" zijn.
    //           Indien @StandaardSpecificatieRegel niet is meegegeven, dan is de default waarde "JA"
    case isnull(@StandaardSpecificatieRegel,'JA')
      when 'JA'  then set @_DefaultSpecificatieRegel = _TRUE;                 // 1 = Wel default specificatieregel
      when 'NEE' then set @_DefaultSpecificatieRegel = _FALSE;                 // 0 = Geen default specificatieregel
      else call Raise(20700,'StandaardSpecificatieRegel');      // (20700) Ongeldige waarde: %1!
    end case;

    // Controle: Indien @StandaardSpecificatieRegel is "JA" en @RegelSoort = "ART" dan mag het aantal specificatieregels niet ongelijk zijn aan 1
    if  @_DefaultSpecificatieRegel = _TRUE and @_PrdOcRegelSoort = 2 /*Artikel*/
        and (select count(*) from tabProductieOrderComponentSpec where PrdOcsPrdOcGid = @_PrdOcGid ) <> 1 then
        call Raise(20701,_U('%1! = %2! in combinatie met aantal specificatieregels ongelijk aan 1', 'StandaardSpecificatieRegel', 'JA'));      // (20701) Ongeldige combinatie: %1!
    end if;

    // Ophalen Specificatieregel indien @StandaardSpecificatieRegel is "JA" en @RegelSoort = "ART"
    if  @_DefaultSpecificatieRegel = _TRUE and @_PrdOcRegelSoort = 2 /*Artikel*/ then
        select PrdOcsGid,
               PrdOcsArtPartijGid,
               PrdOcsArtSerieGid,
               PrdOcsLocGid,
               PrdOcsMagGid,
               PrdOcsPrdOcGid,
               PrdOcsIsPartijNetAangemaakt,
               PrdOcsIsSerieNetAangemaakt
        into   @_PrdOcsGid,
               @_PrdOcsArtPartijGid,
               @_PrdOcsArtSerieGid,
               @_PrdOcsLocGid,
               @_PrdOcsMagGid,
               @_PrdOcsPrdOcGid,
               @_PrdOcsIsPartijNetAangemaakt,
               @_PrdOcsIsSerieNetAangemaakt
        from   tabProductieOrderComponentSpec
        where  PrdOcsPrdOcGid = @_PrdOcGid;

    end if;

    // Deze zijn altijd nodig i.v.m. controles, dus ook als defaultspec.regel=false
    if  @_PrdOcRegelSoort = 2 /*Artikel*/ then
        select sum(PrdOcsAantalDezeVerwerking),
               sum(PrdOcsAantalReedsVerwerkt),
               //sum(PrdOcsAantalTotaalTeVerwerken), // Leuk, kan gewoon 0 zijn, heeft geen zin hier
               sum(PrdOcsAantalUitvalInDezeVerwerking),
               sum(PrdOcsAantalUitvalInReedsVerwerkt)
        into   @_PrdOcsAantalDezeVerwerking,
               @_PrdOcsAantalReedsVerwerkt,
               //@_PrdOcsAantalTotaalTeVerwerken,
               @_PrdOcsAantalUitvalInDezeVerwerking,
               @_PrdOcsAantalUitvalInReedsVerwerkt
        from   tabProductieOrderComponentSpec
        where  PrdOcsPrdOcGid = @_PrdOcGid;
    end if;

    // Ophalen van de benodigde Artikelgegevens
    select ArtGid,
           ArtAantDecAantallen
    into   @ArtGid,
           @ArtAantDecAantallen
    from   tabArtikel
    where  ArtGid = @_PrdOcArtGid;

    // Controle: Indien @MagazijnCode is meegegeven, dan moet dit een bestaande nagazijn zijn.
    //           Alleen toegestaan i.c.m. artikelregels.
    if  @MagazijnCode is not null then
        if  @_PrdOcRegelSoort = 2 then       // 2 = Artikel
            select MagGid
            into   @MagGid
            from   tabMagazijn
            where  MagCode = @MagazijnCode;
            if  @MagGid is null then
                call Raise(20720,'MagazijnCode');   // (20720) %1! niet gevonden!
            else
                if  @_PrdOcMagGid <> @MagGid then
                    // Magazijn is gewijzigd
                    set @MagazijnIsGewijzigd = _TRUE;
                    set @_PrdOcMagGid  = @MagGid;
                    set @_PrdOcsMagGid = @MagGid;
                else
                    // Magazijn is niet gewijzigd
                    set @MagazijnIsGewijzigd = _FALSE;
                end if;
            end if;
        else
            // MagazijnCode is niet toegestaan i.c.m. een tarief of tekstblok
            call Raise(20701,_U('%1! is niet toegestaan in combinatie met tarief of tekstblok', 'MagazijnCode'));    // (20701) Ongeldige combinatie: %1!
        end if;
    end if;

    // Controle: Indien @Locatiecode is meegegeven, dan moet dit een bestaande locatie zijn binnen het betreffende magazijn.
    //           Alleen toegestaan i.c.m. artikelregels.
    if  isnull(@Locatiecode,'') <> '' then
        if  @_PrdOcRegelSoort = 2 /*Artikel*/ then      // 2 = Artikel
            select LocGid
            into   @LocGid
            from   tabLocatie
            where  LocMagGid = @_PrdOcMagGid
            and    LocNaam   = @Locatiecode;
            if  @LocGid is null then
                call Raise(20720,'Locatiecode');   // (20720) %1! niet gevonden!
            else
                set @_PrdOcLocGid  = @LocGid;
                set @_PrdOcsLocGid = @LocGid;
            end if;
        else
            // Locatiecode is niet toegestaan i.c.m. een tarief of tekstblok
            call Raise(20701,_U('%1! is niet toegestaan in combinatie met tarief of tekstblok', 'Locatiecode'));    // (20701) Ongeldige combinatie: %1!
        end if;
    else
        if  @_PrdOcRegelSoort = 2 /*Artikel*/ and @MagazijnIsGewijzigd = _TRUE then
            // @Locatiecode is niet meegegeven en het magazijn is gewijzigd, dan eerst proberen de Default locatie van het artikel op te halen.
            select ArtMagDefaultLocGid
            into   @ArtMagDefaultLocGid
            from   tabArtikelMagazijn
            where  ArtMagMagGid = @_PrdOcMagGid
            and    ArtMagArtGid = @_PrdOcArtGid;
            if  @ArtMagDefaultLocGid is not null then
                // Artikel heeft een Default locatie, dan gaan wij die ook toepassen.
                set @_PrdOcLocGid  = @ArtMagDefaultLocGid;
                set @_PrdOcsLocGid = @ArtMagDefaultLocGid;
            else
                // Artikel heeft geen Default locatie, dan wordt de locatie (Standaard) binnen het magazijn toegepast.
                select LocGid
                into   @LocGid
                from   tabLocatie
                where  LocMagGid = @_PrdOcMagGid
                and    LocNaam   = '(Standaard)';
                if  @LocGid is not null then
                    set @_PrdOcLocGid  = @LocGid;
                    set @_PrdOcsLocGid = @LocGid;
                else
                    // Geen geldige locatie gevonden, dan moet er een geldige @Locatiecode worden meegegeven.
                    call Raise(20700,'Locatiecode');   // (20700) Ongeldige waarde: %1!
                end if;
            end if;
        end if;
    end if;

    // Controle: Indien @TotaalAfTeBoeken niet is meegegeven, dan blijft het aantal ongewijzigd en alleen van toepassing op @RegelSoort TAR (1) of ART (2)
    //           Indien wel meegegeven, dan moet het aantal ongelijk zijn aan 0 en het aantal decimalen o.b.v. de Artikelgegevens.
    if  @TotaalAfTeBoeken is not null then
        if  @_PrdOcRegelSoort in (1 /*Tarief*/, 2 /*Artikel*/) then
            // @TotaalAfTeBoeken is meegegeven
            if  @TotaalAfTeBoeken <> 0 then
                set @ControleDecimalen = truncnum(@TotaalAfTeBoeken,@ArtAantDecAantallen);      // Controleren op meegegeven waarde in decimalen
                if  (@ControleDecimalen - @TotaalAfTeBoeken) <> 0 then
                    call Raise(20780,_U('Component wijzigen is'),_U('Teveel decimalen in %1! meegegeven!', 'TotaalAfTeBoeken'));   // (20780) %1! niet mogelijk: %2!
                else
                    set @_PrdOcAantalTotaalTeVerwerken  = @TotaalAfTeBoeken;
                    //set @_PrdOcsAantalTotaalTeVerwerken = @TotaalAfTeBoeken;
                end if;
            else
                call Raise(20700,'TotaalAfTeBoeken');   // (20700) Ongeldige waarde: %1!
            end if;
        else
            // TotaalAfTeBoeken is niet toegestaan i.c.m. tekstblok
            call Raise(20701,_U('%1! is niet toegestaan in combinatie met tekstblok.', 'TotaalAfTeBoeken'));    // (20701) Ongeldige combinatie: %1!
        end if;
    end if;

    // Controle: Indien @NuAfTeBoeken niet is meegegeven, dan blijft het aantal ongewijzigd en alleen van toepassing op @RegelSoort TAR (1) of ART (2)
    //           Indien wel meegegeven, dan moet het aantal decimalen o.b.v. de Artikelgegevens.
    if  @NuAfTeBoeken is not null then
      if  @_PrdOcRegelSoort in (1 /*Tarief*/, 2 /*Artikel*/) then
        set @ControleDecimalen = truncnum(@NuAfTeBoeken,@ArtAantDecAantallen);      // Controleren op meegegeven waarde in decimalen
        if  (@ControleDecimalen - @NuAfTeBoeken) <> 0 then
            call Raise(20780,_U('Component wijzigen is'),_U('Teveel decimalen in %1! meegegeven!', 'NuAfTeBoeken'));   // (20780) %1! niet mogelijk: %2!
        else
            set @_PrdOcAantalDezeVerwerking  = @NuAfTeBoeken;
            set @_PrdOcsAantalDezeVerwerking = @NuAfTeBoeken;
        end if;
      else
        // NuAfTeBoeken is niet toegestaan i.c.m. tekstblok
        call Raise(20701,_U('%1! is niet toegestaan in combinatie met tekstblok.', 'NuAfTeBoeken'));    // (20701) Ongeldige combinatie: %1!
      end if;
    end if;

    // Controle: @NuAfTeBoeken mag niet groter zijn dat @TotaalAfTeBoeken
    if  (@_PrdOcAantalDezeVerwerking + @_PrdOcAantalReedsVerwerkt) > @_PrdOcAantalTotaalTeVerwerken then
        call Raise(20780,_U('Component wijzigen is'),_U('Aantal %1! + aantal reeds verwerkt is groter dan aantal %2!', 'NuAfTeBoeken', 'TotaalAfTeBoeken'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Controle: Indien @WaarvanUitval niet is meegegeven, dan blijft het aantal ongewijzigd en alleen van toepassing op @RegelSoort ART (2)
    //           Indien wel meegegeven, dan moet het aantal ongelijk zijn aan 0 en het aantal decimalen o.b.v. de Artikelgegevens.
    if  @WaarvanUitval is not null then
        if  @_PrdOcRegelSoort = 2 then   // Uitsluitend i.c.m. Artikel (2)
            // @WaarvanUItval is meegegeven
            set @ControleDecimalen = truncnum(@WaarvanUitval,@ArtAantDecAantallen);       // Controleren op meegegeven waarde in decimalen
            if  (@ControleDecimalen - @WaarvanUitval) <> 0 then
                 call Raise(20780,_U('Component wijzigen is'),_U('Teveel decimalen in %1! meegegeven!', 'WaarvanUitval'));   // (20780) %1! niet mogelijk: %2!
            else
                 set @_PrdOcAantalUitvalInDezeVerwerking  = @WaarvanUitval;
                 set @_PrdOcsAantalUitvalInDezeVerwerking = @WaarvanUitval;
            end if;
        else
            // WaarvanUitval is niet toegestaan i.c.m. tekstblok
            call Raise(20701,_U('%1! is niet toegestaan in combinatie met tarief of tekstblok', 'WaarvanUitval'));    // (20701) Ongeldige combinatie: %1!
        end if;
    end if;

    // Controle: @WaarvanUitval mag niet groter zijn dat @NuAfTeBoeken
//    if  @_PrdOcAantalUitvalInDezeVerwerking > @_PrdOcAantalDezeVerwerking then
//        raiserror 20780,'Component wijzigen is','Aantal WaarvanUitval is groter dan aantal NuAfTeBoeken';   // (20780) %1! niet mogelijk: %2!
//    end if;
    // Controle: totale uitval mag niet hoger zijn dan totale verwerkingsaantal
    if  @_PrdOcAantalUitvalInDezeVerwerking + isnull(@_PrdOcsAantalUitvalInReedsVerwerkt, 0) > isnull(@_PrdOcsAantalReedsVerwerkt, 0) + @_PrdOcAantalDezeVerwerking then
        call Raise(20780,_U('Component wijzigen is'),_U('Het totale aantal uitval mag niet hoger zijn dan het totaal afgeboekte aantal'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Omdat @_PrdOcsAantalTotaalTeVerwerken ook 0,000 kan zijn, kan de volgende code niet. Laten we maar overslaan
    // Zie incident I15817
    //begin
    //  declare @AantalTotaalVerwerking numeric(15,3) = @_PrdOcsAantalReedsVerwerkt + @_PrdOcAantalDezeVerwerking;
    //  declare @AantalTotaalUitval numeric(15,3) = @_PrdOcsAantalUitvalInReedsVerwerkt + @_PrdOcAantalUitvalInDezeVerwerking;
    //  // Teken van TotaalOpTeBoeken, NuOpTeBoeken en WaarvanUitval moet gelijk zijn
    //  if sign(@_PrdOcsAantalTotaalTeVerwerken) <> sign(@AantalTotaalVerwerking) and @AantalTotaalVerwerking <> 0 then
    //      raiserror 20780,'Component wijzigen is','De tekens van TotaalAfTeBoeken en NuAfTeBoeken zijn ongelijk';   // (20780) %1! niet mogelijk: %2!
    //  end if;
    //  if sign(@_PrdOcsAantalTotaalTeVerwerken /*Mag toch niet 0 zijn*/) <> sign(@AantalTotaalUitval) and @AantalTotaalUitval <> 0 then
    //      raiserror 20780,'Component wijzigen is','De tekens van TotaalAfTeBoeken en WaarvanUitval zijn ongelijk';   // (20780) %1! niet mogelijk: %2!
    //  end if;
    //end;


    // Gegevens bijwerken in de database.
    // Componentregel wijzigen.
    update tabProductieOrderComponent
    set    PrdOcLocGid                       = @_PrdOcLocGid,
           PrdOcMagGid                       = @_PrdOcMagGid,
           PrdOcAantalDezeVerwerking         = @_PrdOcAantalDezeVerwerking,
           PrdOcAantalTotaalTeVerwerken      = @_PrdOcAantalTotaalTeVerwerken,
           PrdOcAantalUitvalInDezeVerwerking = @_PrdOcAantalUitvalInDezeVerwerking
    where  PrdOcGid = @_PrdOcGid;

    // Componentspecificatieregel conditioneel wijzigen.
    if  @_DefaultSpecificatieRegel = _TRUE and @_PrdOcRegelSoort = 2 /*Artikel*/ then      //  1 = Wel default specificatieregel  2 = Artikel
        update tabProductieOrderComponentSpec
        set    PrdOcsLocGid                       = @_PrdOcsLocGid,
               PrdOcsMagGid                       = @_PrdOcsMagGid,
               PrdOcsAantalDezeVerwerking         = @_PrdOcsAantalDezeVerwerking,
               PrdOcsAantalTotaalTeVerwerken      = @_PrdOcAantalTotaalTeVerwerken, //@_PrdOcsAantalTotaalTeVerwerken Wordt niet gebruikt
               PrdOcsAantalUitvalInDezeVerwerking = @_PrdOcsAantalUitvalInDezeVerwerking
        where  PrdOcsGid = @_PrdOcsGid;
    end if;
  end;     // Einde atomic

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Component_Wijzigen > eind';
end;


create or replace procedure WebSvcProc_Productieorder_Eindproduct_Toevoegen
( in @ProductieorderNummer       numeric(10,0),
  in @ArtikelNummer              nchar(20),
  in @PartijNummer               nchar(20),
  in @Omschrijving               long nvarchar,
  in @MagazijnCode               numeric(3,0),
  in @StandaardSpecificatieRegel nchar(3),
  in @LocatieCode                nchar(20),
  in @TotaalOpTeBoeken           numeric(15,3),
  in @NuOpTeBoeken               numeric(15,3),
  in @WaarvanUitval              numeric(15,3))

result (RegelNummer integer,
        RegelID     integer)

begin
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;

  declare @RegelNummer integer;
  declare @RegelID     integer;

  declare _TRUE smallint = 1;
  declare _FALSE smallint = 0;

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Eindproduct_Toevoegen > begin';

  // Module controle
  if IsModuleActive('r2') = 0 then                    // Module Productie-1 (samengestelde artikelen vereist)
    call Raise(20790,_U('Optie Productie-1'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r3') = 0 then                    // Module Productie-2 (productie-1 vereist)
    call Raise(20790,_U('Optie Productie-2'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r4') = 0 then                    // Module Samengestelde artikelen (nodig voor productie-1)
    call Raise(20790,_U('Optie Samengestelde artikelen'));  // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    declare @PrdOkGid                            integer;
    declare @PrdOkNummer                         numeric(10,0);
    declare @PrdOkStatus                         smallint;
    declare @PrdOkRcptSoort                      smallint;
    declare @PrdOkDefMagGidEindproduct           integer;
    declare @ArtGid                              integer;
    declare @ArtAantDecAantallen                 smallint;
    declare @ArtIsPartijRegistreren              smallint;
    declare @ArtPartijGid                        integer;
    declare @MagGid                              integer;
    declare @LocGid                              integer;
    declare @ArtMagDefaultLocGid                 integer;
    declare @ControleDecimalen                   numeric(15,3);
    declare @DefaultSpecificatieRegel            smallint;

    // tabProductieOrderEindProduct
    declare @_PrdOePrdOkGid                      integer;
    declare @_PrdOeArtGid                        integer;
    declare @_PrdOeArtPartijGid                  integer;
    declare @_PrdOeLocGid                        integer;
    declare @_PrdOeMagGid                        integer;
    declare @_PrdOeOmschrijving                  long nvarchar;
    declare @_PrdOeAantalDezeVerwerking          numeric(15,3);
    declare @_PrdOeAantalTotaalTeVerwerken       numeric(15,3);
    declare @_PrdOeAantalUitvalInDezeVerwerking  numeric(15,3);
    declare @_PrdOeIsReceptRegel                 smallint;
    declare @_PrdOeRcpAantal                     numeric(15,3);
    declare @_PrdOeRegelNr                       integer;

    // tabProductieOrderEindproductSpec
    declare @_PrdOesPrdOeGid                     integer;
    declare @_PrdOesArtPartijGid                 integer;
    declare @_PrdOesLocGid                       integer;
    declare @_PrdOesMagGid                       integer;
    declare @_PrdOesAantalDezeVerwerking         numeric(15,3);
    declare @_PrdOesAantalTotaalTeVerwerken      numeric(15,3);
    declare @_PrdOesAantalUitvalInDezeVerwerking numeric(15,3);


    // Opzoeken onderhanden Productieorder
    select PrdOkGid,
           PrdOkNummer,
           PrdOkStatus,
           PrdOkRcptSoort,
           PrdOkDefMagGidEindProduct
    into   @PrdOkGid,
           @PrdOkNummer,
           @PrdOkStatus,
           @PrdOkRcptSoort,
           @PrdOkDefMagGidEindproduct
    from   tabProductieOrderKop
    where  PrdOkNummer = @ProductieorderNummer;

    if  @PrdOkGid is null then
        call Raise(20780,_U('Eindproduct toevoegen is'),_U('Ongeldige of geen %1! meegegeven', 'ProductieorderNummer'));      // (20780) %1! niet mogelijk: %2!
    end if;
    if  @PrdOkStatus = 4 then       // 4 = Gereed
        call Raise(20780,_U('Eindproduct toevoegen is'),_U('Productieorder heeft status Gereed'));      // (20780) %1! niet mogelijk: %2!
    end if;

    // Controle: Meerdere Eindproducten zijn niet toegestaan indien @PrdOkRcptSoort = 0 (Samenstelling)
    if  (select count(*) from tabProductieOrderEindProduct where PrdOePrdOkGid = @PrdOkGid and @PrdOkRcptSoort = 0) > 0 then
        call Raise(20780,_U('Eindproduct toevoegen is'),_U('Er is al een eindproduct aanwezig binnen deze samenstelling'));      // (20780) %1! niet mogelijk: %2!
    end if;

    // Gevonden Productieorder locken of bestaande lock overnemen
    call WebSvcHulpProc_ProductieorderExclusiefLocken(@PrdOkGid,@LockUserNaam,@SpId,@LoginTime);

    // Neem ProductieOrderKopGid over
    set @_PrdOePrdOkGid = @PrdOkGid;

    // Controle: @ArtikelNummer moet zijn meegegeven
    if  isnull(@ArtikelNummer,'') = '' then
        call Raise(20700,'ArtikelNummer');   // (20700) Ongeldige waarde: %1!
    end if;

    // Ophalen van de benodigde Artikelgegegevens o.b.v. meegegeven @ArtikelNummer
    select ArtGid,
           ArtAantDecAantallen,
           ArtIsPartijRegistreren
    into   @ArtGid,
           @ArtAantDecAantallen,
           @ArtIsPartijRegistreren
    from   tabArtikel
    where  ArtCode = @ArtikelNummer
    and    ArtSoort = 2;                // Uitsluitend artikelen
    // Controle: Meegegeven @ArtikelNummer moet een bestaande artikel zijn
    if  @ArtGid is null then
        call Raise(20720,'ArtikelNummer');   // (20720) %1! niet gevonden!
    else
        set @_PrdOeArtGid = @ArtGid;
    end if;

    // Controle: Indien @Omschrijving niet is meegegeven, dan 'Tekst op factuur' van artikel toepassen o.b.v. de standaard taalcode van de administratie.
    if  isnull(@Omschrijving,'') <> '' then
        set @_PrdOeOmschrijving = @Omschrijving;
    else
        if  @_PrdOeArtGid is not null then
            set @_PrdOeOmschrijving = isnull((select ArtTekst
                                              from   tabArtikelTeksten
                                              where  ArtTekstArtGid = @_PrdOeArtGid
                                              and    ArtTaalGid = (select DefaultTaalGid from tabVasteGegevens)),'');   // DefaultTaalGid is de standaard TaalGid van de administratie
            else
                set @_PrdOeOmschrijving = '';
        end if;
    end if;

    // Controle: Meegegeven @PartijNummer i.c.m. met artikel, die niet Partijregistrerend is, is niet toegestaan.
    if  isnull(@PartijNummer,'') <> '' and @ArtIsPartijRegistreren = 0 then     // 0 = Artikel is niet partijregistrerend
        call Raise(20701,_U('Partijnummer is niet toegestaan, artikel is niet partijregistrerend'));    // (20701) Ongeldige combinatie: %1!
    end if;

    // Controle: Indien @Partijnummer is meegegeven, dan moet het een bestaande partijnummer zijn binnen het artikel.
    if  isnull(@PartijNummer,'') <> '' then
        select ArtPartijGid
        into   @ArtPartijGid
        from   tabArtikelPartij
        where  ArtPartijArtGid = @_PrdOeArtGid
        and    ArtPartijNummer = @PartijNummer;
        if  @ArtPartijGid is null then
            call Raise(20720,'PartijNummer');   // (20720) %1! niet gevonden!
        else
            set @_PrdOeArtPartijGid  = @ArtPartijGid;
            set @_PrdOesArtPartijGid = @ArtPartijGid;
        end if;
    end if;

    // Controle: Indien @MagazijnCode is meegegeven, dan moet dit een bestaande magazijn zijn.
    if  @MagazijnCode is not null then
        // @MagazijnCode is meegegeven
        select MagGid
        into   @MagGid
        from   tabMagazijn
        where  MagCode = @MagazijnCode;
        if  @MagGid is null then
            call Raise(20720,'MagazijnCode');   // (20720) %1! niet gevonden!
        else
            set @_PrdOeMagGid  = @MagGid;
            set @_PrdOesMagGid = @MagGid;
        end if;
    else
        // @MagazijnCode is niet meegegeven, dan Default magazijn Eindproduct van de productieorder toepassen
        set @_PrdOeMagGid  = @PrdOkDefMagGidEindProduct;
        set @_PrdOesMagGid = @PrdOkDefMagGidEindProduct;
    end if;

    // Controle: Indien @Locatiecode is meegegeven, dan moet dit een bestaande locatie zijn binnen het betreffende magazijn
    if  isnull(@LocatieCode,'') <> '' then
        // @LocatieCode is meegegeven
        select LocGid
        into   @LocGid
        from   tabLocatie
        where  LocMagGid = @_PrdOeMagGid
        and    LocNaam   = @LocatieCode;
        if  @LocGid is null then
            call Raise(20720,'Locatiecode');   // (20720) %1! niet gevonden!
        else
            set @_PrdOeLocGid  = @LocGid;
            set @_PrdOesLocGid = @LocGid;
        end if;
    else
        // @Locatiecode is niet meegegeven, dan eerst proberen de Default locatie van het artikel op te halen.
        select ArtMagDefaultLocGid
        into   @ArtMagDefaultLocGid
        from   tabArtikelMagazijn
        where  ArtMagMagGid = @_PrdOeMagGid
        and    ArtMagArtGid = @_PrdOeArtGid;
        if  @ArtMagDefaultLocGid is not null then
            // Artikel heeft een Default locatie binnen het magazijn, dan gaan wij die ook toepassen
            set @_PrdOeLocGid  = @ArtMagDefaultLocGid;
            set @_PrdOesLocGid = @ArtMagDefaultLocGid;
        else
            // Artikel heeft geen Default locatie, dan wordt de locatie (Standaard) binnen het magazijn toegepast
            select LocGid
            into   @LocGid
            from   tabLocatie
            where  LocMagGid = @_PrdOeMagGid
            and    LocNaam = '(Standaard)';
            if  @LocGid is not null then
                set @_PrdOeLocGid  = @LocGid;
                set @_PrdOesLocGid = @LocGid;
            else
                // Geen geldige locatie gevonden, dan moet er een geldige @Locatiecode worden meegegeven.
                call Raise(20700,'Locatiecode');   // (20700) Ongeldige waarde: %1!
            end if;
        end if;
    end if;

    // Controle: @TotaalOpTeBoeken is verplicht tijdens het toevoegen van een nieuwe eindproduct.
    //           Ook wordt @ToraalOpTeBoeken gecontroleerd op het meegegeven aantal decimalen o.b.v. Artikelgegevens
    if  isnull(@TotaalOpTeBoeken,0) = 0 then   // Aantal moet ongelijk zijn aan 0
        call Raise(20700,'TotaalOpTeBoeken');   // (20700) Ongeldige waarde: %1!
    else
        set @ControleDecimalen = truncnum(@TotaalOpTeBoeken,@ArtAantDecAantallen);          // Controleren op meegegeven waarde in decimalen
        if  (@ControleDecimalen - @TotaalOpTeBoeken) <> 0 then
            call Raise(20780,_U('Eindproduct toevoegen is'),_U('Teveel decimalen in %1! meegegeven!', 'TotaalOpTeBoeken'));   // (20780) %1! niet mogelijk: %2!
        else
            set @_PrdOeAantalTotaalTeVerwerken  = @TotaalOpTeBoeken;
            set @_PrdOesAantalTotaalTeVerwerken = @TotaalOpTeBoeken;
        end if;
    end if;


    // Controle: @NuOpTeBoeken is verplicht tijdens het toevoegen van een nieuwe eindproduct
    //           Ook wordt @NuOpTeBoeken gecontroleerd op het meegegeven aantal decimalen o.b.v. Artikelgegevens
    if  @NuOpTeBoeken is null then
        call Raise(20700,'NuOpTeBoeken');   // (20700) Ongeldige waarde: %1!
    else
        set @ControleDecimalen = truncnum(@NuOpTeBoeken,@ArtAantDecAantallen);       // Controeleren op meegegeven waarde in decimalen
        if  (@ControleDecimalen - @NuOpTeBoeken) <> 0 then
            call Raise(20780,_U('Eindproduct toevoegen is'),_U('Teveel decimalen in %1! meegegeven!', 'NuOpTeBoeken'));   // (20780) %1! niet mogelijk: %2!
        else
            set @_PrdOeAantalDezeVerwerking  = @NuOpTeBoeken;
            set @_PrdOesAantalDezeVerwerking = @NuOpTeBoeken;
        end if;
    end if;

    // Controle: @NuOpTeboeken mag niet groter zijn dan @TotaalOpTeBoeken
    if  @_PrdOeAantalDezeVerwerking > @_PrdOeAantalTotaalTeVerwerken then
        call Raise(20780,_U('Eindproduct toevoegen is'),_U('Aantal %1! is groter dan aantal %2!', 'NuOpTeBoeken', 'TotaalOpTeBoeken'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Controle: @WaarvanUitval is verplicht tijdens het toevoegen van een nieuwe eindproduct
    //           Ook wordt @WaarvanUitval gecontroleerd op het meegegeven aantal decimalen o.b.v. Artikelgegevens
    if  @WaarvanUitval is null then             // @WaarvanUitval moet een geldig getal worden meegegeven.
        call Raise(20700,'WaarvanUitval');   // (20700) Ongeldige waarde: %1!
    else
        set @ControleDecimalen = truncnum(@WaarvanUitval,@ArtAantDecAantallen);       // Controleren op meegegeven waarde in decimalen
        if  (@ControleDecimalen - @WaarvanUitval) <> 0 then
            call Raise(20780,_U('Eindproduct toevoegen is'),_U('Teveel decimalen in %1! meegegeven!', 'WaarvanUitval'));   // (20780) %1! niet mogelijk: %2!
        else
            set @_PrdOeAantalUitvalInDezeVerwerking  = @WaarvanUitval;
            set @_PrdOesAantalUitvalInDezeVerwerking = @WaarvanUitval;
        end if;
    end if;

    // Controle: @WaarvanUitval mag niet groter zijn dan @NuOpTeBoeken
    if  @_PrdOesAantalUitvalInDezeVerwerking > @_PrdOesAantalDezeVerwerking then
        call Raise(20780,_U('Eindproduct toevoegen is'),_U('Aantal %1! is groter dan aantal %2!', 'WaarvanUitval', 'NuOpTeBoeken'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Teken van TotaalOpTeBoeken, NuOpTeBoeken en WaarvanUitval moet gelijk zijn
    if sign(@TotaalOpTeBoeken /*Mag toch niet 0 zijn*/) <> sign(@NuOpTeBoeken) and @NuOpTeBoeken <> 0 then
        call Raise(20780,_U('Eindproduct toevoegen is'),_U('De tekens van %1! en %2! zijn ongelijk', 'TotaalOpTeBoeken', 'NuOpTeBoeken'));   // (20780) %1! niet mogelijk: %2!
    end if;
    if sign(@TotaalOpTeBoeken /*Mag toch niet 0 zijn*/) <> sign(@WaarvanUitval) and @WaarvanUitval <> 0 then
        call Raise(20780,_U('Eindproduct toevoegen is'),_U('De tekens van %1! en %2! zijn ongelijk', 'TotaalOpTeBoeken', 'WaarvanUitval'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Controle: Indien @StandaardSpecificatieRegel is meegegeven, dan moet dit wel "JA" of "NEE" zijn.
    //           Indien @StandaardSpecificatieRegel niet is meegegeven, dan is de default waarde "JA"
    case isnull(@StandaardSpecificatieRegel,'JA')
      when 'JA'  then set @DefaultSpecificatieRegel = _TRUE;                 // 1 = Wel default specificatieregel
      when 'NEE' then set @DefaultSpecificatieRegel = _FALSE;                 // 0 = Geen default specificatieregel
      else call Raise(20700,'StandaardSpecificatieRegel');      // (20700) Ongeldige waarde: %1!
    end case;

    // Recept gegevens initialiseren, omdat hier geen recept van toepassing is
    set @_PrdOeIsReceptRegel = 0;
    set @_PrdOeRcpAantal     = 1;

    // Genereer regelnummer t.b.v. Eindproductregel
    select isnull((max(PrdOeRegelNr) + 1),1) into @_PrdOeRegelNr from tabProductieOrderEindproduct where PrdOePrdOkGid = @PrdOkGid;
    // Controle: Regelnummer mag niet groter zijn dan 999
    if  @_PrdOeRegelNr > 999 then
        call Raise(20780,_U('Eindproduct toevoegen is'),_U('Hoogste regelnummer %1! is al bereikt', '999'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Gegevens bijwerken in de database
    // Eindproductregel toevoegen
    insert into tabProductieOrderEindproduct with auto name
    select @_PrdOeArtGid                       as PrdOeArtGid,
           @_PrdOeArtPartijGid                 as PrdOeArtPartijGid,
           @_PrdOeLocGid                       as PrdOeLocGid,
           @_PrdOeMagGid                       as PrdOeMagGid,
           @_PrdOePrdOkGid                     as PrdOePrdOkGid,
           @_PrdOeAantalDezeVerwerking         as PrdOeAantalDezeVerwerking,
           0                                   as PrdOeAantalReedsVerwerkt,
           @_PrdOeAantalTotaalTeVerwerken      as PrdOeAantalTotaalTeVerwerken,
           @_PrdOeAantalUitvalInDezeVerwerking as PrdOeAantalUitvalInDezeVerwerking,
           0                                   as PrdOeAantalUitvalInReedsVerwerkt,
           0                                   as PrdOeBedragReedsVerwerkt,
           0                                   as PrdOeBedragUitvalInReedsVerwerkt,
           @_PrdOeIsReceptRegel                as PrdOeIsReceptRegel,
           @_PrdOeRcpAantal                    as PrdOeRcpAantal,
           @_PrdOeRegelNr                      as PrdOeRegelNr,
           @_PrdOeOmschrijving                 as PrdOeOmschrijving;
    set @_PrdOesPrdOeGid = @@identity;

    // Eindproductspecificatieregel conditioneel toevoegen
    if  @DefaultSpecificatieRegel = _TRUE then     // 1 = Wel Default specificatieregel
        insert into tabProductieOrderEindproductSpec with auto name
        select @_PrdOesArtPartijGid                 as PrdOesArtPartijGid,
               null                                 as PrdOesArtSerieGid,
               @_PrdOesLocGid                       as PrdOesLocGid,
               @_PrdOesMagGid                       as PrdOesMagGid,
               @_PrdOesPrdOeGid                     as PrdOesPrdOeGid,
               @_PrdOesAantalDezeVerwerking         as PrdOesAantalDezeVerwerking,
               0                                    as PrdOesAantalReedsVerwerkt,
               @_PrdOesAantalTotaalTeVerwerken      as PrdOesAantalTotaalTeVerwerken,
               @_PrdOesAantalUitvalInDezeVerwerking as PrdOesAantalUitvalInDezeVerwerking,
               0                                    as PrdOesAantalUitvalInReedsVerwerkt,
               0                                    as PrdOesIsPartijNetAangemaakt,
               0                                    as PrdOesIsSerieNetAangemaakt,
               null                                 as PrdOesOrrGid,
               null                                 as PrdOesAdrNaam1,
               null                                 as PrdOesNawFilNummer,
               null                                 as PrdOesOrkNummer,
               null                                 as PrdOesOrrRegelNr,
               0                                    as PrdOesSoort,                          // 0 = Magazijn, 1 = Verkooporder
               0                                    as PrdOesVerwerktInVerkoopOrder;
    end if;

    // Regelnummer en PrdOeGid overnemen t.b.v. het resultaat
    set @RegelNummer = @_PrdOeRegelNr;
    set @RegelID     = @_PrdOesPrdOeGid;

  end;  // Einde atomic

  // Ophalen resultaat (niet in de Begin Atomic... end!)
  select @RegelNummer as RegelNummer,
         @RegelID     as RegelID;

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Eindproduct_Toevoegen > eind';
end;


create or replace procedure WebSvcProc_Productieorder_LockVrijgeven(in @ProductieorderNummer numeric(10,0))
begin
  // Als Webservice API de stored proc in King database aanroepen die ook door andere APIs gebruikt kunnen worden.
  // variabelen
  declare @_PrdOkGid      integer;
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;

  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabProductieOrderKop';

  // ingangscontroles (licentie, opties, abonnement...)
  if IsModuleActive('r2') = 0 then                    // Module Productie-1 (samengestelde artikelen vereist)
    call Raise(20790,_U('Optie Productie-1'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r3') = 0 then                    // Module Productie-2 (productie-1 vereist)
    call Raise(20790,_U('Optie Productie-2'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r4') = 0 then                    // Module Samengestelde artikelen (nodig voor productie-1)
    call Raise(20790,_U('Optie Samengestelde artikelen'));  // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken Bestelling
  select PrdOkGid into @_PrdOkGid
  from   tabProductieOrderKop
  where  PrdOkNummer = @ProductieorderNummer;
  if @_PrdOkGid is null then
    call Raise(20720, _U('Productieorder')); // (20720) niet gevonden: %1!
  end if;

  //Elke api heeft zijn eigen connection id.
  //Het standaard lockmechanisme werkt in dat geval dan niet.
  //het vrij geven van een lock gaat dan niet op SpId, maar op usernaam

  begin // lock vrijgeven
    call LockReleaseOnId(isnull(@Spid, @@SpId), isnull(@LoginTime,@@LoginTime), 1, _QLOCKTABLENAME, @_PrdOkGid);

    // gelockt, maar niet door @LockUserNaam? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = _QLOCKTABLENAME and qLockPKey = string(@_PrdOkGid) and qLockUser <> @LockUserNaam) then
      call Raise(20741, _U('Productieorder %1!', @ProductieorderNummer)); // (20741) %1! is in gebruik!
    end if;

    // De record zou dus wel door @LockUserNaam gelockt zijn, deze opruimen.
    call LockReleaseOnUserName(@LockUserNaam, 1, _QLOCKTABLENAME, @_PrdOkGid);
  end; // lock vrijgeven

end;



