create or replace procedure WebSvcProc_Productieorder_Toevoegen
( in @ProductieorderNummer             numeric(10,0),
  in @ReceptCode                       nchar(20),
  in @Omschrijving                     nchar(40),
  in @AantalTeProduceren               numeric(15,3),
  in @Status                           nchar(13),
  in @TeProducerenDoor                 nchar(10),
  in @TeProducerenVoor                 date,
  in @StartdatumProductie              date,
  in @DefaultMagazijnComponenten       numeric(3,0),
  in @DefaultMagazijnEindproduct       numeric(3,0),
  in @DefaultAantalNuAfTeBoeken        nchar(16),
  in @DefaultAantalNuOpTeBoeken        nchar(16),
  in @RekeningnummerProductieResultaat nchar(28),
  in @Document                         nchar(255),
  in @Opmerking                        long nvarchar)

result(ProductieorderNummer numeric(10,0))

begin
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;

  declare @_PrdOkNummer                             numeric(10,0);

  // Variabelen
  declare @ProductieOrderNrGenereren                smallint;

  // Vaste gegevens productie
  declare @RcpvGid                                  integer;
  declare @RcpvProdOrderStartnummer                 numeric(10,0);
  declare @RcpvProdOrderStartnummerWijzigen         smallint;        // 0 = Productieordernr. toevoegen of wijzigen niet toegestaan
                                                                     // 1 = Productieordernr. toevoegen of wijzigen wel toegestaan
  declare _TRUE smallint = 1;
  declare _FALSE smallint = 0;


  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Toevoegen > begin';

  // --- Ingangscontroles (licentie, opties, abonnement...)
  if IsModuleActive('r2') = 0 then                    // Module Productie-1 (samengestelde artikelen vereist)
    call Raise(20790,_U('Optie Productie-1'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r3') = 0 then                    // Module Productie-2 (productie-1 vereist)
    call Raise(20790,_U('Optie Productie-2'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r4') = 0 then                    // Module Samengestelde artikelen (nodig voor productie-1)
    call Raise(20790,_U('Optie Samengestelde artikelen'));  // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    // tabProductieOrderKop
    declare @_PrdOkGid                                integer;
    declare @_PrdOkDefMagGidComponent                 integer;
    declare @_PrdOkDefMagGidEindproduct               integer;
    declare @_PrdOkRksGidProdResultaat                integer;
    declare @_PrdOkAangemaaktDoor                     nchar(40);
    declare @_PrdOkAangemaaktOp                       date;
    declare @_PrdOkAantalRcpt                         numeric(15,3);
    declare @_PrdOkAantalRcptMaximum                  numeric(15,3);
    declare @_PrdOkAantalRcptMinimum                  numeric(15,3);
    declare @_PrdOkDocument                           nchar(255);
    declare @_PrdOkOmschrijving                       nchar(40);
    declare @_PrdOkProductieKlaarOp                   date;
    declare @_PrdOkProductieStartOp                   date;
    declare @_PrdOkRcptCode                           nchar(20);
    declare @_PrdOkRcptSoort                          smallint;
    declare @_PrdOkRcptZoekcode                       nchar(20);
    declare @_PrdOkStatus                             smallint;
    declare @_PrdOkTeProducerenVoor                   date;
    declare @_TeProducerenDoor                        nchar(40);    // = PrdOkUitTeVoerenDoor
    declare @_PrdOkVulAantalDezeVerwerkingComponent   smallint;
    declare @_PrdOkVulAantalDezeVerwerkingEindproduct smallint;
    declare @_PrdOkOpmerking                          long nvarchar;

    // Vaste gegevens Productieorder ophalen
    select  first RcpvGid,
            RcpvProdOrderStartnummerWijzigen
    into    @RcpvGid,
            @RcpvProdOrderStartnummerWijzigen
    from    tabReceptuurVasteGegevens;

    // Controle invoer @ProductieorderNummer
    if @ProductieorderNummer is null then                      // @ProductieorderNummer is NIET meegegeven
       set @ProductieOrderNrGenereren = _TRUE;                     // ProductieorderNummer wordt gegenereerd.
    else                                                       // @ProductieorderNummer is WEL meegegeven
       if  @RcpvProdOrderStartnummerWijzigen = 0 then          // 0 = Productieordernummer toevoegen of wijzigen is NIET toegestaan.
           call Raise(20780,_U('%1! meegegeven is', 'ProductieorderNummer'),_U('%1! toewijzen is niet toegestaan', 'ProductieorderNummer'));           // (20780) %1! niet mogelijk: %2!
       else                                                    // 1 = Productieordernummer toevoegen of wijzigen is WEL toegestaan.
           // Meegegeven @ProductieorderNummer mag nog niet bestaan
           if  exists (select first 1 from tabProductieOrderKop where PrdOkNummer = @ProductieorderNummer) then
               call Raise(20780,_U('Productieorder toevoegen is'),_U('%1! bestaat al', 'ProductieorderNummer'));      // (20780) %1! niet mogelijk: %2!
           end if;
           set @ProductieOrderNrGenereren = _FALSE;                 // ProductieorderNummer wordt NIET gegenereerd.
           set @_PrdOkNummer = @ProductieorderNummer;
       end if;
    end if;

    // Productie order gegevens, niet in WebSvcHulpProc_Valideer_ProductieorderKop zijn opgenomen
    set @_PrdOkAangemaaktDoor   = @@GebruikerCode;
    set @_PrdOkAangemaaktOp     = today();
    set @_PrdOkProductieKlaarOp = null;

    // Controles
    call WebSvcHulpProc_Valideer_ProductieorderKop(
      // IN
      0, // @Mode 0 = Toevoegen
      @ReceptCode,
      @Omschrijving,
      @AantalTeProduceren,
      @Status,
      @TeProducerenDoor,
      @TeProducerenVoor,
      @StartdatumProductie,
      @DefaultMagazijnComponenten,
      @DefaultMagazijnEindproduct,
      @DefaultAantalNuAfTeBoeken,
      @DefaultAantalNuOpTeBoeken,
      @RekeningnummerProductieResultaat,
      @Document,
      @Opmerking,
      // IN/OUT
      null, // @_PrdOkGid,
      @_PrdOkRcptCode,
      @_PrdOkRcptSoort,
      @_PrdOkRcptZoekcode,
      @_PrdOkOmschrijving,
      @_PrdOkAantalRcpt,
      @_PrdOkAantalRcptMinimum,
      @_PrdOkAantalRcptMaximum,
      @_PrdOkStatus,
      @_TeProducerenDoor,               // = PrdOkUitTeVoerenDoor
      @_PrdOkTeProducerenVoor,
      @_PrdOkProductieStartOp,
      @_PrdOkDefMagGidComponent,
      @_PrdOkDefMagGidEindproduct,
      @_PrdOkVulAantalDezeVerwerkingComponent,
      @_PrdOkVulAantalDezeVerwerkingEindproduct,
      @_PrdOkRksGidProdResultaat,
      @_PrdOkDocument,
      @_PrdOkOpmerking
    );

    if @ProductieOrderNrGenereren = _TRUE then
    begin
      declare @ProdOrdNr numeric(10,0);
       // Eerstvolgende productieordernummer ophalen uit Vaste gegevens productie
       select RcpvProdOrderStartNummer into @ProdOrdNr from tabReceptuurVasteGegevens where RcpvGid = @RcpvGid;
       while exists (select first 1 from tabProductieOrderKop where PrdOkNummer = @ProdOrdNr)
       loop
         update tabReceptuurVasteGegevens
         set    RcpvProdOrderStartNummer = (@ProdOrdNr + 1)
         where  RcpvGid = @RcpvGid;
         select RcpvProdOrderStartNummer into @ProdOrdNr from tabReceptuurVasteGegevens where RcpvGid = @RcpvGid;
       end loop;
       set @_PrdOkNummer = @ProdOrdNr;      // Eerste niet gebruikte productieordernummer
       // Bijwerken naar het eerste volgende startnummer
       update tabReceptuurVasteGegevens
       set    RcpvProdOrderStartNummer = (@ProdOrdNr + 1)
       where  RcpvGid = @RcpvGid;
    end;
    end if;

    // ProductieOrderKop wegschrijven
    insert into tabProductieOrderKop with auto name
    select @_PrdOkNummer                             as PrdOkNummer,
           @_PrdOkRcptCode                           as PrdOkRcptCode,
           @_PrdOkRcptSoort                          as PrdOkRcptSoort,
           @_PrdOkRcptZoekcode                       as PrdOkRcptZoekcode,
           @_PrdOkOmschrijving                       as PrdOkOmschrijving,
           @_PrdOkAantalRcpt                         as PrdOkAantalRcpt,
           @_PrdOkAantalRcptMinimum                  as PrdOkAantalRcptMinimum,
           @_PrdOkAantalRcptMaximum                  as PrdOkAantalRcptMaximum,
           @_PrdOkStatus                             as PrdOkStatus,
           @_PrdOkAangemaaktDoor                     as PrdOkAangemaaktDoor,
           @_PrdOkAangemaaktOp                       as PrdOkAangemaaktOp,
           @_TeProducerenDoor                        as PrdOkUitTeVoerenDoor,
           @_PrdOkTeProducerenVoor                   as PrdOkTeProducerenVoor,
           @_PrdOkProductieStartOp                   as PrdOkProductieStartOp,
           @_PrdOkProductieKlaarOp                   as PrdOkProductieKlaarOp,
           @_PrdOkDefMagGidComponent                 as PrdOkDefMagGidComponent,
           @_PrdOkDefMagGidEindproduct               as PrdOkDefMagGidEindproduct,
           @_PrdOkVulAantalDezeVerwerkingComponent   as PrdOkVulAantalDezeVerwerkingComponent,
           @_PrdOkVulAantalDezeVerwerkingEindproduct as PrdOkVulAantalDezeVerwerkingEindproduct,
           @_PrdOkRksGidProdResultaat                as PrdOkRksGidProdResultaat,
           @_PrdOkDocument                           as PrdOkDocument,
           @_PrdOkOpmerking                          as PrdOkOpmerking;
    set @_PrdOkGid = @@identity;

    // Productieorder locken voor vervolg
    call WebSvcHulpProc_ProductieorderExclusiefLocken( @_PrdOkGid, @LockUserNaam, @SpId, @LoginTime );

    // Als @ReceptCode is meegegeven en gevalideerd, dan ook de bijbehorende component(en) en eindproduct(en) overnemen uit het recept
    if @_PrdOkRcptCode <> '' then
    begin
      declare @RcptGid integer;
       select first RcptGid into @RcptGid from tabReceptuur where RcptCode = @_PrdOkRcptCode;
       call ProductieOrderVulRegelsUitRecept
       (    @_PrdOkGid,      // Nieuw toegevoegde productieorder
            @RcptGid,        // Gebruikte recept tijdens toevoegen van productieorder
            0,               // @WatToevoegen             (0 = Gehele recept, 1 = Component, 2 = Eindproduct)
            null,            // @ToevoegGid               (null = Alles van @WatToevoegen)
            0,               // @VerwijderBestaandeRegels (0 = Bestaande regels toevoegen, 1 = Verwijderen)
            1,               // @MaakEindProdSpecRegels   (0 = Niet, 1 = Wel)
       );
    end;
    end if;

  end;         // Einde Atomic

  // Ophalen resultaat
  select @_PrdOkNummer as ProductieorderNummer;


  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_Toevoegen > eind';

end;


create or replace procedure WebSvcProc_Productieorder_Verwerken
( in @ProductieorderNummer        numeric(10,0)           ,
  in @BoekDatum                   date                    ,
  in @Omschrijving                nchar(40)               ,
  in @ProductieorderAfsluiten     nchar(3)  default 'NEE' ,
  in @ComponentenAfboeken         nchar(3)  default 'NEE' ,
  in @EindproductenOpboeken       nchar(3)  default 'NEE' ,
  in @ProductiekostenBoeken       nchar(3)  default 'NEE' )
begin
  //call TraceBegin('WebSvcProc_Productieorder_Verwerken');
  declare @LockUserNaam  nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime Datetime = @@LoginTime;

  declare @_PrdOkGid                    integer;
  declare @_ProductieOrderAfsluiten     smallint;
  declare @_ComponentenAfboeken         smallint;
  declare @_EindproductenOpboeken       smallint;
  declare @_ProductiekostenBoeken       smallint;

  // qc = Query Constanten
  declare @qcNEE  smallint = 0;
  declare @qcJA   smallint = 1;

  // ingangscontroles (licentie, opties, abonnement...)
  if IsModuleActive('rp') = 0 then
    call Raise(20790, _U('Optie Productie-orders')); // (20790) '%1' niet geactiveerd!
  end if;

  // ********************
  // Productie Order Kop
  // en Status checken
  // ********************
  begin
    declare @PrdOkStatus  smallint;

    call WebSvcHulpProc_Valideer_ProductieOrderEnStatus(
      /*in*/
      @ProductieorderNummer ,
      1                     , // Mag niet gereed zijn (status)
      /*out*/
      @_PrdOkGid            ,
      @PrdOkStatus          ); // status productie-order

    // Productieorder MOET onderhanden zijn
    if @PrdOkStatus <> 3 /*Onderhanden*/ then
      call Raise(20780, _U('Verwerken'), _U('Productieorder is niet onderhanden')) ; // (20780)  <Actie> niet mogelijk: <Reden>.
    end if;
  end; // controle Productie Order Kop

  // ********************
  // controle parameters t.b.v. verwerking
  // ********************
  call WebSvcHulpProc_Productieorder_ValideerVerwerkingsOpties(
    /*in*/
    @_PrdOkGid,
    @ProductieorderAfsluiten,
    @ComponentenAfboeken,
    @EindproductenOpboeken,
    @ProductiekostenBoeken,
    /*out*/
    @_ProductieOrderAfsluiten,
    @_ComponentenAfboeken,
    @_EindproductenOpboeken,
    @_ProductiekostenBoeken);

  // ******************************
  // Controle te verwerken onderdelen
  // Bij afsluiten extra controle(s)
  // ******************************
  if @_ComponentenAfboeken = @qcJA then
    call WebSvcHulpProc_Productieorder_ValideerTeVerwerkenComponenten( @_PrdOkGid, @BoekDatum, @_ProductieOrderAfsluiten );
  end if;

  if @_EindproductenOpboeken = @qcJA then
    call WebSvcHulpProc_Productieorder_ValideerTeVerwerkenEindproducten( @_PrdOkGid, @BoekDatum, @_ProductieOrderAfsluiten );
  end if;

  // ********************
  // Start de verwerking
  // ********************

  call WebSvcHulpProc_Productieorder_VerwerkenInAdministratie(
    @_PrdOkGid,
    @BoekDatum,
    @Omschrijving,
    @_ProductieorderAfsluiten,
    @_ComponentenAfboeken,
    @_EindproductenOpboeken,
    @_ProductiekostenBoeken,
    // T.b.v. locken, wordt bepaald door aanroepende instantie
    @LockUserNaam,
    @SpId,
    @LoginTime );

end;


create or replace procedure WebSvcProc_Productieorder_VrijeRubriek_Wijzigen(
  in @ProductieorderNummer  numeric(10),
  in @RubriekOmschrijving   nchar(41),
  in @RubriekInhoud         nchar(256))    // de haakje sluiten hoeft niet op aparte regel, kan ook hier
begin
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;

  declare @_PrdOkGid      integer;
  declare @_PrdOkStatus   integer;

  declare @qcGEREED       smallint = 4;

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_VrijeRubriek_Wijzigen > @ProductieorderNummer = '+string(@ProductieorderNummer)+', @RubriekOmschrijving = '+@RubriekOmschrijving;
  //call TraceBegin(@@ErrorTextProcedure);

  // Module controle
  if IsModuleActive('rp') = 0 then                    // Module Productie-1 (samengestelde artikelen vereist)
    call Raise(20790,_U('Optie Productie-1'));              // (20790) '%1!' niet geactiveerd!
  end if;

  if ( isnull( trim( @RubriekOmschrijving ), '' ) = '' ) then
    call Raise(20700, _U('%1!, bevat geen tekst.', 'RubriekOmschrijving'));  // (20700) Ongeldige waarde: <parameter of opmerking>
  end if;

  if length( trim( isnull( @RubriekOmschrijving, '' ) ) ) > 40 then
    call Raise(20700 , _U('%1!, maximaal %2! tekens toegestaan.', 'RubriekOmschrijving', '40')) ; // Ongeldige waarde: %1!
  end if;

  // King 5 stored proc VrInsertOrReplaceValue doet NIKS als waarde NULL is.
  // Men wil iets wijzigen, dus opgeven van waarde afdwingen
  if ( @RubriekInhoud is null ) then
    call Raise(20700, _U('%1! is verplicht.', 'RubriekInhoud'));     // (20700) Ongeldige waarde: <parameter of opmerking>
  end if;

  /** Ingangscontroles (licentie, opties, abonnement...)  **/
  select PrdOkGid, PrdOkStatus into @_PrdOkGid, @_PrdOkStatus from KingSystem.tabProductieOrderKop where PrdOkNummer = @ProductieorderNummer;

  if(@_PrdOkGid is null) then
    call Raise(20720,  _U('%1! %2!', 'ProductieorderNummer', @ProductieorderNummer)) ;  // (20720) %1 niet gevonden!
  end if;

  /** Error wanneer status al gereed is. **/
  if( @_PrdOkStatus = @qcGEREED ) then
    call Raise(20780, _U('Vrije rubriek wijzigen'), _U('productieorder heeft status gereed')  ); // (20780) <Actie> niet mogelijk: <Reden>.
  end if;


  begin atomic
    // Neem de productie-order in gebruik...
    call KingSystem.WebSvcHulpProc_ProductieorderExclusiefLocken( @_PrdOkGid, @LockUserNaam, @SpId, @LoginTime );
    // ... als je de vrije rubriek gaat wijzigen
    call KingSystem.VrInsertOrReplaceValue( 'PRD', 0, 0, @_PrdOkGid, @RubriekOmschrijving, @RubriekInhoud );

    // Lock blijft staan, vrijgeven via aparte API stored proc
  end;

  set @@ErrorTextProcedure = 'WebSvcProc_Productieorder_VrijeRubriek_Wijzigen > eind'
//call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Productieorder_Wijzigen(
  in @ProductieorderNummer numeric(10,0),
  in @Status               nchar(13),
  in @TeProducerenDoor     nchar(10),
  in @TeProducerenVoor     date,
  in @StartdatumProductie  date
)
begin
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;

  // variabelen
  declare @_PrdOkGid                  integer;
  declare @_PrdOkStatus               smallint;
  declare @_TeProducerenDoor          nchar(40);
  declare @_PrdOkTeProducerenVoor     date;
  declare @_PrdOkProductieStartOp     date;

  // --- Ingangscontroles (licentie, opties, abonnement...)
  if IsModuleActive('r2') = 0 then                    // Module Productie-1 (samengestelde artikelen vereist)
    call Raise(20790,_U('Optie Productie-1'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r3') = 0 then                    // Module Productie-2 (productie-1 vereist)
    call Raise(20790,_U('Optie Productie-2'));              // (20790) '%1!' niet geactiveerd!
  end if;
  if IsModuleActive('r4') = 0 then                    // Module Samengestelde artikelen (nodig voor productie-1)
    call Raise(20790,_U('Optie Samengestelde artikelen'));  // (20790) '%1!' niet geactiveerd!
  end if;

  // --- Opzoeken te wijzigen recept
  select PrdOkGid into @_PrdOkGid
  from   tabProductieOrderKop
  where  PrdOkNummer = @ProductieorderNummer;
  if @_PrdOkGid is null then
    call Raise(20720,'ProductieorderNummer'); // (20720) niet gevonden: %1!
  end if;

  // --- Atomic Transactie
  begin atomic
    // eerst de productie-order exclusief locken
    call WebSvcHulpProc_ProductieorderExclusiefLocken( @_PrdOkGid, @LockUserNaam, @SpId, @LoginTime );

    // --- Gegevens van de productie-order ophalen
    select PrdOkStatus,
           PrdOkUitTeVoerenDoor,
           PrdOkTeProducerenVoor,
           PrdOkProductieStartOp
    into   @_PrdOkStatus,
           @_TeProducerenDoor,
           @_PrdOkTeProducerenVoor,
           @_PrdOkProductieStartOp
    from   tabProductieOrderKop
    where  PrdOkGid = @_PrdOkGid;

    // --- Controles
    call WebSvcHulpProc_Valideer_ProductieorderKop(
      // IN
      //Parameternaam = Waarde
      @Mode                   = 1, // @Mode 1 = Wijzigen
      @Status                 = @Status,
      @TeProducerenDoor       = @TeProducerenDoor,
      @TeProducerenVoor       = @TeProducerenVoor,
      @StartdatumProductie    = @StartdatumProductie,
      // IN/OUT
      @_PrdOkGid              = @_PrdOkGid,
      @_PrdOkStatus           = @_PrdOkStatus,
      @_TeProducerenDoor      = @_TeProducerenDoor,
      @_PrdOkTeProducerenVoor = @_PrdOkTeProducerenVoor,
      @_PrdOkProductieStartOp = @_PrdOkProductieStartOp,
    );


    // --- Gewijzigde gegevens bijwerken in tabel tabProductieOrderKop
    update tabProductieOrderKop
    set    PrdOkStatus           = @_PrdOkStatus,
           PrdOkUitTeVoerenDoor  = @_TeProducerenDoor,
           PrdOkTeProducerenVoor = @_PrdOkTeProducerenVoor,
           PrdOkProductieStartOp = @_PrdOkProductieStartOp
    where  PrdOkGid = @_PrdOkGid;

  end;

end;


create or replace procedure WebSvcHulpProc_ProjectExclusiefLocken
( in @LockProjGid integer,
  in @LockUserNaam nchar(40) default null,
  in @SpId integer default null,
  in @LoginTime datetime default null)
begin
  declare @_LockResult integer;
  declare @qcGEENLOCK smallint = 0;
  declare @qcEXCLUSIVELOCK smallint = 1;

  // Defaults instellen
  set @LockUserNaam = IsNull(@LockUserNaam, 'KingWebservice');
  set @SpId = IsNull(@SpId, @@SpId);
  set @LoginTime = IsNull(@LoginTime, @@LoginTime);

  if not exists(select first 1 from tabProject where ProjGid = @LockProjGid ) then
    call Raise(20780, _U('In gebruik nemen'), _U('project niet gevonden')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if LockedById(@SpId, @LoginTime, @qcEXCLUSIVELOCK, 'tabProject', @LockProjGid) = @qcGEENLOCK  then
    // locken, met standaard King 5 procedure
    call LockSetOnId( @Spid,
                      @LoginTime,
                      @qcEXCLUSIVELOCK,             // 1 = Exclusieve lock, 0 = ReadLock
                      'tabProject',  // tabel waarin record te locken is - nchar(40)
                      string(@LockProjGid),          // lockstring voor record, nchar(80)
                      @_LockResult,                 // 0 = OK, anders fout
                      0,                            // Automatisch opruimen: 0 = nee, 1 = ja
                      @LockUserNaam);               // Welke King gebruiker of proces

    if @_LockResult <> 0 then
      call Raise(20741,_U('Project'));    // (20741) %1 is in gebruik!
    end if;
  end if;
end;



create or replace procedure WebSvcHulpProc_ProjectFactuurVerdichting_Toevoegen
( in @PbGid integer,
  //Detaillering van Activiteiten op facturen
  in @DetailleringActActiviteitSpecificeren smallint default 0,
  in @DetailleringActOpbrengstGroepSpecificeren smallint default 0,
  in @DetailleringActMedewerkerSpecificeren smallint default 0,
  //Detaillering van artikelen op facturen
  in @DetailleringArtArtikelSpecificeren smallint default 0,
  in @DetailleringArtOpbrengstGroepSpecificeren smallint default 0,
  //Detaillering van overige kosten op facturen
  in @DetailleringOverigOverigekostenSpecificeren smallint default 0,
  in @DetailleringOverigOpbrengstGroepSpecificeren smallint default 0,
  //Per factuurregel projectmutaties afdrukken
  in @PfvdActPerOnderdeel smallint default 0,
  in @AfdrukkenAlleActiviteitsMutaties smallint default 0,
  in @PfvdArtPerOnderdeel smallint default 0,
  in @AfdrukkenAlleArtikelMutaties smallint default 0,
  in @PfvdMachPerOnderdeel smallint default 0,
  in @AfdrukkenAlleOverigeKostenMutaties smallint default 0,
  in @PfvdTekstOpFactuur long nvarchar default null
)
begin
  declare @_qcJA smallint = 1;
  declare @_qcNEE smallint = 0;

  declare @_PbGid integer;
  declare @_ProjSoort integer;

  select PbGid, ProjSoort into @_PbGid, @_ProjSoort
  from tabProjectBoom
  inner join tabProject on ProjGid = PbProjGid
  where PbGid = @PbGid;
//  and pblevel = 1;

  if (@_PbGid is null) then
    call Raise(20700, 'PbGid'); //Ongeldige waarde: %1
  end if;

  //Bij Intern en Proef alles op nee zetten
  if @_ProjSoort in (2 /*Intern*/, 3 /*Proef*/) then
    set @DetailleringActActiviteitSpecificeren = @_qcNEE;
    set @DetailleringActOpbrengstGroepSpecificeren = @_qcNEE;
    set @DetailleringActMedewerkerSpecificeren = @_qcNEE;
    set @DetailleringArtArtikelSpecificeren = @_qcNEE;
    set @DetailleringArtOpbrengstGroepSpecificeren = @_qcNEE;
    set @DetailleringOverigOverigekostenSpecificeren = @_qcNEE;
    set @DetailleringOverigOpbrengstGroepSpecificeren = @_qcNEE;
    set @PfvdActPerOnderdeel = @_qcNEE;
    set @AfdrukkenAlleActiviteitsMutaties = @_qcNEE;
    set @PfvdArtPerOnderdeel = @_qcNEE;
    set @AfdrukkenAlleArtikelMutaties = @_qcNEE;
    set @PfvdMachPerOnderdeel = @_qcNEE;
    set @AfdrukkenAlleOverigeKostenMutaties = @_qcNEE;
  else
    //Test of de waarde null, 0 of 1 is
    if (isNull(@DetailleringActActiviteitSpecificeren,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'DetailleringActActiviteitSpecificeren'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@DetailleringActOpbrengstGroepSpecificeren,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'DetailleringActOpbrengstGroepSpecificeren'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@DetailleringActMedewerkerSpecificeren,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'DetailleringActMedewerkerSpecificeren'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@DetailleringArtArtikelSpecificeren,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'DetailleringArtArtikelSpecificeren'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@DetailleringArtOpbrengstGroepSpecificeren,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'DetailleringArtOpbrengstGroepSpecificeren'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@DetailleringOverigOverigekostenSpecificeren,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'DetailleringOverigOverigekostenSpecificeren'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@DetailleringOverigOpbrengstGroepSpecificeren,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'DetailleringOverigOpbrengstGroepSpecificeren'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@PfvdActPerOnderdeel,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'PfvdActPerOnderdeel'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@AfdrukkenAlleActiviteitsMutaties,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'AfdrukkenAlleActiviteitsMutaties'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@PfvdArtPerOnderdeel,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'PfvdArtPerOnderdeel'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@AfdrukkenAlleArtikelMutaties,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'AfdrukkenAlleArtikelMutaties'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@PfvdMachPerOnderdeel,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'PfvdMachPerOnderdeel'); /*Ongeldige waarde: %1*/ end if;
    if (isNull(@AfdrukkenAlleOverigeKostenMutaties,@_qcNEE) not in (@_qcJA, @_qcNEE)) then call Raise(20700, 'AfdrukkenAlleOverigeKostenMutaties'); /*Ongeldige waarde: %1*/ end if;

    if @DetailleringActActiviteitSpecificeren = @_qcJA then set @DetailleringActOpbrengstGroepSpecificeren = @_qcNEE; end if;
    if @DetailleringActOpbrengstGroepSpecificeren = @_qcJA then set @DetailleringActActiviteitSpecificeren = @_qcNEE; end if;

    if @DetailleringArtArtikelSpecificeren = @_qcJA then set @DetailleringArtOpbrengstGroepSpecificeren = @_qcNEE; end if;
    if @DetailleringArtOpbrengstGroepSpecificeren = @_qcJA then set @DetailleringArtArtikelSpecificeren = @_qcNEE; end if;

    if @DetailleringOverigOverigekostenSpecificeren = @_qcJA then set @DetailleringOverigOpbrengstGroepSpecificeren = @_qcNEE; end if;
    if @DetailleringOverigOpbrengstGroepSpecificeren = @_qcJA then set @DetailleringOverigOverigekostenSpecificeren = @_qcNEE; end if;
  end if;

  if (exists(select 1 from tabProjectFactuurVerdichting where PfvdPbGid=@_PbGid)) then
    update tabProjectFactuurVerdichting set
      PfvdActPerOnderdeel= @PfvdActPerOnderdeel,
      PfvdActPerOnderdeelSpecAfdruk= @AfdrukkenAlleActiviteitsMutaties,
      PfvdArtPerOnderdeel= @PfvdArtPerOnderdeel,
      PfvdArtPerOnderdeelSpecAfdruk= @AfdrukkenAlleArtikelMutaties,
      PfvdFactVerdActAct= @DetailleringActActiviteitSpecificeren,
      PfvdFactVerdActMedew= @DetailleringActMedewerkerSpecificeren,
      PfvdFactVerdActOpbrGrp= @DetailleringActOpbrengstGroepSpecificeren,
      PfvdFactVerdArtArt= @DetailleringArtArtikelSpecificeren,
      PfvdFactVerdArtOpbrGrp= @DetailleringArtOpbrengstGroepSpecificeren,
      PfvdFactVerdMachMach= @DetailleringOverigOverigekostenSpecificeren,
      PfvdFactVerdMachOpbrGrp= @DetailleringOverigOpbrengstGroepSpecificeren,
      PfvdMachPerOnderdeel= @PfvdMachPerOnderdeel,
      PfvdMachPerOnderdeelSpecAfdruk= @AfdrukkenAlleOverigeKostenMutaties,
      PfvdTekstOpFactuur= @PfvdTekstOpFactuur
    where PfvdPbGid = @_PbGid
  else
    insert into tabProjectFactuurVerdichting (
      PfvdActPerOnderdeel,
      PfvdActPerOnderdeelSpecAfdruk,
      PfvdArtPerOnderdeel,
      PfvdArtPerOnderdeelSpecAfdruk,
      PfvdFactVerdActAct,
      PfvdFactVerdActMedew,
      PfvdFactVerdActOpbrGrp,
      PfvdFactVerdArtArt,
      PfvdFactVerdArtOpbrGrp,
      PfvdFactVerdMachMach,
      PfvdFactVerdMachOpbrGrp,
      PfvdMachPerOnderdeel,
      PfvdMachPerOnderdeelSpecAfdruk,
      PfvdPbGid,
      PfvdTekstOpFactuur )
     values (
      @PfvdActPerOnderdeel,
      @AfdrukkenAlleActiviteitsMutaties,
      @PfvdArtPerOnderdeel,
      @AfdrukkenAlleArtikelMutaties,
      @DetailleringActActiviteitSpecificeren,
      @DetailleringActMedewerkerSpecificeren,
      @DetailleringActOpbrengstGroepSpecificeren,
      @DetailleringArtArtikelSpecificeren,
      @DetailleringArtOpbrengstGroepSpecificeren,
      @DetailleringOverigOverigekostenSpecificeren,
      @DetailleringOverigOpbrengstGroepSpecificeren,
      @PfvdMachPerOnderdeel,
      @AfdrukkenAlleOverigeKostenMutaties,
      @_PbGid,
      @PfvdTekstOpFactuur);
  end if;

end;

create or replace procedure WebSvcHulpProc_ProjectMutatie_Detail_Valideren(
  in @Mode smallint default 0, //0=toevoegen, 1 = verwijderen
  in @Volgnummer numeric(10,0) default null,
  in @Regelnummer integer default null,
  in @Serienummer nchar(20) default '',
  out @_PbrGid integer default null,
  out @_ArtSerieGid integer default null,
  out @_Aantal numeric(15,3) default 1
  )
begin
  // Constanten
  declare _qcNee smallint = 0;

  declare @_PbkGid integer;
  declare @_ArtGid integer;
  declare @_ArtSerienrRegistreren smallint default _qcNee;
  declare @_PbrStatus smallint default null; /*0=Concept, 1=Ingeleverd, 2=Afgekeurd, 3=Geaccepteerd*/

  //call TraceBegin('WebSvcHulpProc_ProjectMutatie_Detail_Valideren');

  // Module: is er geen Projecten-basis actief , dan kan je geen projectmutatiekop aanmaken.
  if IsModuleActive('pr') = _qcNee then
    call Raise(20790, _U('Optie Projecten-basis')); //(20790) '%1!' niet geactiveerd!
  end if;

  if IsModuleActive('s1') = _qcNee and isnull(@SerieNummer,'') <> '' then // Module Serienummers
     call Raise(20790,_U('Optie Serienummers')); //(20790) '%1!' niet geactiveerd!
  end if;

  //ProjectboekingsKop
  if (@Volgnummer is null) then
    call Raise(20700,'Volgnummer'); //(20700) Ongeldige waarde: %1!
  end if;

  select PbkGid into @_PbkGid from tabProjectBoekingsKop where PbkVolgNummer = @Volgnummer;

  if (@_PbkGid is null) then
    call Raise(20720, 'Volgnummer'); //(20720) %1! niet gevonden!
  end if;

  //ProjectboekingsRegel
  if (IsNull(@Regelnummer, 0) = 0) then
    call Raise(20700,'Regelnummer'); // (20700) Ongeldige waarde: %1!
  end if;

  //Regel ophalen.
  select PbrGid, PbrStatus, if PbrAantalGeboekt >= 0 then 1 else -1 endif, ArtGid, ArtSerienrRegistreren
  into @_PbrGid, @_PbrStatus, @_Aantal, @_ArtGid, @_ArtSerienrRegistreren
  from tabProjectBoekingsRegel
  inner join tabArtikel on ArtGid = PbrArtGid
  where PbrPbkGid = @_PbkGid
    and PbrRegelnr = @Regelnummer;

  if (@_PbrGid is null) then
    call Raise(20720, 'Regelnummer'); //(20720) %1! niet gevonden!
  end if;

  //Als de regel status ingeleverd heeft mag er niets meer worden gewijzigd
  if (@_PbrStatus in (1/*=Ingeleverd*/, 3/*=Geaccepteerd*/)) then
    if @Mode = 0 /*Toevoegen*/ then
      call Raise(20780, _U('Serienummer toekennen is'), _U('Projectmutatieregel moet de status ''Concept'' of ''Afgekeurd'' hebben!')); //(20780) %1! niet mogelijk: %2!.
    else
      call Raise(20780, _U('Verwijderen is'), _U('Projectmutatieregel moet de status ''Concept'' of ''Afgekeurd'' hebben!')); //(20780) %1! niet mogelijk: %2!.
    end if;
  end if;

  //Is het artikel serienummer registrerend?
  if (@_ArtSerienrRegistreren = _qcNee) then
    if @Mode = 0 /*Toevoegen*/ then
      call Raise(20780,_U('Serienummer toekennen is'),_U('Artikel is niet serienummer registrerend')); //(20780) %1! niet mogelijk: %2!
    else
      call Raise(20780,_U('Verwijderen is'),_U('Artikel is niet serienummer registrerend')); //(20780) %1! niet mogelijk: %2!
    end if;
  end if;

  //SerieNummer
  if (isNull(@Serienummer, '') = '') then
    //Geen serienummer meegegeven.
    call Raise(20700,'Serienummer'); // (20700) Ongeldige waarde: %1!
  end if;

  //Zoek het serienummer voor het betreffende artikel.
  select ArtSerieGid
  into @_ArtSerieGid
  from tabArtikelSerienummer
  where ArtSerieArtGid = @_ArtGid
    and ArtSerienummer = @Serienummer;

  if (@_ArtSerieGid is null) then
    call Raise(20720, 'Serienummer'); //(20720) %1! niet gevonden!
  end if;

  //call TraceEind('WebSvcHulpProc_ProjectMutatie_Detail_Valideren');
end;


create or replace procedure WebSvcHulpProc_ProjectPermissie_Toevoegen
( in @ProjGid integer,
  //Detaillering van Activiteiten op facturen
  in @Permissie smallint default 1 //Geldige waardes [1=Wel toegestaan 0=Niet toegestaan]
)
begin
  declare @_qcJA smallint = 1;
  declare @_PbGid integer;

  //Alleen met de module Projecten-gebruikstoestemming toevoegen/wijzigen
  if IsModuleActive('pg') = @_qcJA then
    select PbGid into @_PbGid
    from tabProjectBoom
    where PbProjGid = @ProjGid
    and pblevel = 1;

    if (@_PbGid is null) then
      call Raise(20700, 'ProjGid'); //Ongeldige waarde: %1
    end if;

    if (@Permissie not in (0 /*Niet toegestaan*/, 1 /*Wel toegestaan*/)) then
      call Raise(20700, 'StandaardwaardeGebruikstoestemming'); //Ongeldige waarde: %1
    end if;

    if (exists(select 1 from tabProjectPermissie where ppmPbGid=@_PbGid)) then
      update tabProjectPermissie set
        ppmPermissie= @Permissie
      where ppmPbGid = @_PbGid
    else
      insert into tabProjectPermissie (
        ppmPbGid,
        ppmPermissie )
       values (
        @_PbGid,
        @Permissie);
    end if;
  end if;
end;


create or replace procedure WebSvcProc_ProjectMutatie_Kop_Toevoegen (
  in @Volgnummer numeric(10,0) default null,
  in @Medewerker nchar(10) default '',
  //Moet de herkomst zelf bepaald worden? 1 of 6 afhankelijk van of de weekstaat gegevens zijn ingevuld.
  //in @PbkHerkomst smallint default 0, //0=inv projm mutaties , 1=imp proj mutaties , 2=via journaal , 3=Gekoppeld aan journaal , 4=via werkbon , 5=Inv weekstaat , 6=imp weekstaat
  in @Omschrijving nchar(40) default '',
  in @Jaar smallint default 0, //Verplicht bij Herkomst 5 en 6
  in @Week smallint default 0) //Verplicht bij Herkomst 5 en 6
result (Volgnummer numeric(10,0))

begin
  declare @_PbkGid integer;
  declare @_PbkHerkomst smallint = 1; /* 1= importeren proj mutaties*/
  declare @_RelGid integer;

  //call TraceBegin('WebSvcProc_ProjectMutatie_Kop_Toevoegen > begin');

  // Module: is er geen Projecten-basis actief , dan kan je geen projectmutatiekop aanmaken.
  if IsModuleActive('pr') = 0 then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  //De herkomst op importeren weekstaat zetten als de weekstaat gegevens zijn ingevuld
  if (IsNull(@Jaar, 0) <> 0) or (isNull(@Week, 0) <> 0) or (isNull(@Medewerker, '') <> '') then
    set @_PbkHerkomst = 6; /* 1= importeren weekstaat*/

    if (isNull(@Medewerker, '') <> '') then
      select PmwRelGid into @_RelGid from tabProjectMedewerker where PmwZoekcode = @Medewerker;

      if @_RelGid is null then
        call Raise(20720,'Medewerker'); //(20720) %1! niet gevonden!
      end if;
    end if;
  else
    //Dit zorgt er voor dat deze gegevens bij een normale projectmutatie niet gevuld worden.
    set @Jaar = 0;
    set @Week = 0;
    set @Medewerker = '';
  end if;

  call ProjectBoekingsKopToevoegen(
    @PbkVolgnummer = @Volgnummer,
    @PbkRelGid = @_RelGid,
    @PbkHerkomst = @_PbkHerkomst,
    @PbkOms = @Omschrijving,
    @PbkWeekJaar = @Jaar,
    @PbkWeeknr = @Week,
    @NieuwPbkGid = @_PbkGid);

  // Ophalen resultaat
  select PbkVolgnummer as Volgnummer
  from tabProjectBoekingsKop
  where pbkGid = @_PbkGid;

  //call TraceEind('WebSvcProc_Productieorder_Eindproduct_Toevoegen > eind');
end;


create or replace procedure WebSvcProc_ProjectMutatie_Kop_Verwijderen(
  in @Volgnummer numeric(10,0) default null
)
begin
  declare _qcNee smallint = 0;

  declare @_PbkGid integer;
  declare @_PbkHerkomst smallint = 1; /* 0= Inv. projmut, 1= Imp. projmut, 2= Via journaal, 3= Gekoppeld aan journaal, 4= Via werkbon, 5= Inv. weekstaat, 6= Imp. weekstaat */

  //call TraceBegin('WebSvcProc_ProjectMutatie_Kop_Verwijderen');

  // Module: is er geen Projecten-basis actief , dan kan je geen projectmutatiekop aanmaken.
  if IsModuleActive('pr') = _qcNee then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  //Zoek het volgnummer
  if (@Volgnummer is null) then
    call Raise(20700,'Volgnummer'); // (20700) Ongeldige waarde: %1!
  end if;

  select PbkGid, PbkHerkomst
  into @_PbkGid, @_PbkHerkomst
  from tabProjectBoekingsKop
  where PbkVolgNummer = @Volgnummer;

  if (@_PbkGid is null) then
    call Raise(20720, 'Volgnummer'); //(20720) %1! niet gevonden!
  end if;

  //Niet verwijderen als de herkomst Gekoppeld aan journaal is.
  if @_PbkHerkomst = 3 /*Gekoppeld aan journaal*/ then
    call Raise(20780, _U('Verwijderen'), _U('Projectmutatiekop mag niet de herkomst ''Gekoppeld aan journaal'' hebben!')); //(20780) %1! niet mogelijk: %2!.
  end if;

  //Als de regel status ingeleverd heeft mag er niets meer worden gewijzigd
  if exists(select 1 from tabProjectBoekingsRegel where PbrPbkGid = @_PbkGid and PbrStatus in  (1/*=Ingeleverd*/, 3/*=Geaccepteerd*/)) then
    call Raise(20780, _U('Verwijderen'), _U('Projectmutatiekop bevat regels met de status ''Ingeleverd'' of ''Geaccepteerd''!')); //(20780) %1! niet mogelijk: %2!.
  end if;

  delete tabProjectBoekingsKop where PbkGid = @_PbkGid;

  //call TraceEind('WebSvcProc_ProjectMutatie_Kop_Verwijderen');
end;


create or replace procedure WebSvcProc_ProjectMutatie_Regel_Detail_Toevoegen (
  in @Volgnummer numeric(10,0) default null,
  in @Regelnummer integer default null,
  in @Serienummer nchar(20) default '')
result (RegelDetailID integer)

begin
  declare @_PbrGid integer;
  declare @_ArtSerieGid integer;
  declare @_Aantal numeric(15,3) default 1;

  //call TraceBegin('WebSvcProc_ProjectMutatie_Regel_Detail_Toevoegen > begin');

  call WebSvcHulpProc_ProjectMutatie_Detail_Valideren(
    @Volgnummer = @Volgnummer,
    @Regelnummer = @Regelnummer,
    @Serienummer = @Serienummer,
    @_PbrGid = @_PbrGid,
    @_ArtSerieGid = @_ArtSerieGid,
    @_Aantal = @_Aantal
  );

  //Serienummer moet uniek zijn binnen deze mutatieregel!
  if exists(select 1 from tabProjectBoekingsRegelDetail where PbrdPbrGid = @_PbrGid and PbrdArtSerieGid = @_ArtSerieGid) then
    call Raise(20780,_U('Serienummer toekennen is'),_U('Serienummer moet uniek zijn binnen deze mutatieregel!')); //(20780) %1! niet mogelijk: %2!
  end if;

  //serienummerregel toevoegen
  insert into tabProjectBoekingsRegelDetail
    ( PbrdPbrGid,
      PbrdArtSerieGid,
      PbrdAantal)
  values
    ( /*PbrdPbrGid      = */  @_PbrGid,
      /*PbrdArtSerieGid = */  @_ArtSerieGid,
      /*PbrdAantal      = */  @_Aantal
    );

  //En het nieuwe PbrdGID teruggeven
  select @@Identity;
  //call TraceEind('WebSvcProc_ProjectMutatie_Regel_Detail_Toevoegen > eind');
end;


create or replace procedure WebSvcProc_ProjectMutatie_Regel_Detail_Verwijderen(
  in @Volgnummer numeric(10,0) default null,
  in @Regelnummer integer default null,
  in @Serienummer nchar(20) default ''
)
begin
  declare @_PbrGid integer;
  declare @_ArtSerieGid integer;

  //call TraceBegin('WebSvcProc_ProjectMutatie_Regel_Detail_Verwijderen');

  call WebSvcHulpProc_ProjectMutatie_Detail_Valideren(
    @Mode = 1 /*Verwijderen*/,
    @Volgnummer = @Volgnummer,
    @Regelnummer = @Regelnummer,
    @Serienummer = @Serienummer,
    @_PbrGid = @_PbrGid,
    @_ArtSerieGid = @_ArtSerieGid
  );

  //Serienummer moet uniek zijn binnen deze mutatieregel!
  if not exists(select 1 from tabProjectBoekingsRegelDetail where PbrdPbrGid = @_PbrGid and PbrdArtSerieGid = @_ArtSerieGid) then
    call Raise(20720, 'Serienummer'); //(20720) %1! niet gevonden!
  end if;

  //Serienummer moet uniek zijn binnen deze mutatieregel!
  delete tabProjectBoekingsRegelDetail where PbrdPbrGid = @_PbrGid and PbrdArtSerieGid = @_ArtSerieGid;

  //call TraceEind('WebSvcProc_ProjectMutatie_Regel_Detail_Verwijderen');
end;


create or replace procedure WebSvcProc_ProjectMutatie_Regel_ToevoegenWijzigen (
  in @Volgnummer numeric(10,0) default null,
  in @Regelnummer integer default null,
  in @Soort nchar(10) default null, /*'ACTIVITEIT', 'OV. KOSTEN', 'ARTIKEL'*/
  in @ArtikelTarief	nchar(20)	default null,
  in @GekoppeldAanActiviteit nchar(20) default null, //Als ArtikelTarief een overige kosten is en het gaat om een weekstaat moet hier instaan aan welke activiteitsregel er gekoppeld moet worden.
  in @Omschrijving long nvarchar default null,
  in @ProjectCode nchar(10) default null,
  in @ProjectOnderdeelZoekCode nchar(40) default null,
  in @Medewerker nchar(10) default null,
  in @Categorieen long nvarchar default null,
  in @UrenIngevoerdAls nchar(14) default null, /*'DECIMALEN', 'TIJDNOTATIE', 'BEGIN/EINDTIJD'*/
  in @Begintijd time default null,
  in @AantalBesteed numeric(20,8) default null,
  in @AantalDeclarabel numeric(20,8) default null,
  in @Datum date default null,
  in @DirecteInkoop nchar(3) default null, /*'JA', 'NEE'*/
  in @Leverancier nchar(10) default null,
  in @Magazijn nchar(3) default null,
  in @Locatie nchar(20) default null,
  in @Partij nchar(20) default null,
  in @Kostprijs numeric(15,3) default null,
  in @Verkoopprijs numeric(15,3) default null,
  in @Status nchar(12) default null, /*'CONCEPT', 'INGELEVERD', 'AFGEKEURD', 'GEACCEPTEERD'*/
  in @Opmerking long nvarchar default null)
result (Regel integer)

begin
  // Constanten
  declare _MutSoort_Activiteit smallint = 0;
  declare _MutSoort_OvKosten smallint = 1;
  declare _MutSoort_Artikel smallint = 2;
  declare _qcJa smallint = 1;
  declare _qcNee smallint = 0;

  declare @_PbkGid integer;
  declare @_PbrGid integer;
  declare @_ArtGid integer default null;
  declare @_PbrMutSoort smallint default null; /* 0= Activiteit, 1= Ov. kosten, 2= Artikel*/
  declare @_PbrStatus smallint default null; /*0=Concept, 1=Ingeleverd, 2=Afgekeurd, 3=Geaccepteerd*/
  declare @_PbrUrenIngevoerdAls smallint default null; /*0=Decimalen , 1=Tijdnotatie , 2=Begin/Eindtijd*/
  declare @_PbrIsDirecteInkoop smallint default null; /*0= Nee, 1= Ja*/
  declare @_PbrRelGid integer default null;
  declare @_PbrLeverancierNawGid integer default null;
  declare @_PbrMagGid integer default null;
  declare @_PbrLocGid integer default null;
  declare @_PbrArtPartijGid integer default null;

  //call TraceBegin('WebSvcProc_ProjectMutatie_Regel_ToevoegenWijzigen > begin');

  //Als Regelnummer leeg is dan zit je in toevoegmode. Gebruik dan defaults als er geen waarde is meegegeven
  if (@Regelnummer is null) then
    set @Soort = isNull(@Soort, 'ACTIVITEIT');
    set @_PbrMutSoort = _MutSoort_Activiteit;
    set @_PbrStatus = 0;
    set @_PbrUrenIngevoerdAls = 0;
    set @_PbrIsDirecteInkoop = _qcNee;
    set @ArtikelTarief = isNull(@ArtikelTarief, '');
    set @GekoppeldAanActiviteit = isNull(@GekoppeldAanActiviteit, '');
    set @Omschrijving = isNull(@Omschrijving, '');
    set @ProjectCode = isNull(@ProjectCode, '');
    set @ProjectOnderdeelZoekCode = isNull(@ProjectOnderdeelZoekCode, '');
    set @Medewerker = isNull(@Medewerker, '');
    set @Categorieen = isNull(@Categorieen, '');
    set @UrenIngevoerdAls = isNull(@UrenIngevoerdAls, 'DECIMALEN');
    set @AantalBesteed = isNull(@AantalBesteed, 0);
    set @Datum = isNull(@Datum, now());
    set @DirecteInkoop = isNull(@DirecteInkoop, 'NEE');
    set @Leverancier = isNull(@Leverancier, '');
    set @Magazijn = isNull(@Magazijn, '');
    set @Locatie = isNull(@Locatie, '');
    set @Partij = isNull(@Partij, '');
    set @Status = isNull(@Status, 'CONCEPT');
    set @Opmerking = isNull(@Opmerking, '');
  else
    if (@DirecteInkoop = 'NEE') then set @_PbrIsDirecteInkoop = _qcNee end if;
  end if;

  // Module: is er geen Projecten-basis actief , dan kan je geen projectmutatiekop aanmaken.
  if IsModuleActive('pr') = _qcNee then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  //Zoek het volgnummer
  if (@Volgnummer is null) then
    call Raise(20700,'Volgnummer'); // (20700) Ongeldige waarde: %1!
  else
    select PbkGid into @_PbkGid from tabProjectBoekingsKop where PbkVolgNummer = @Volgnummer;

    if (@_PbkGid is null) then
      call Raise(20720, 'Volgnummer'); //(20720) %1! niet gevonden!
    end if;
  end if;

  //Zoek de regel
  if (@Regelnummer is not null) then
    select PbrGid, if @ArtikelTarief is null then PbrArtGid else null endif
    into @_PbrGid, @_ArtGid
    from tabProjectBoekingsRegel
    where PbrPbkGid = @_PbkGid
    and PbrRegelnr = @Regelnummer;

    if (@_PbrGid is null) then
      call Raise(20720, 'Regelnummer'); //(20720) %1! niet gevonden!
    end if;
  end if;

  //Zet het soort om naar pbrMutsoort
  if @Soort not in ('ACTIVITEIT', 'OV. KOSTEN', 'ARTIKEL', null) then
    call Raise(20700,'Soort'); // (20700) Ongeldige waarde: %1!
  end if;

  case @Soort
  when 'ACTIVITEIT' then
    set @_PbrMutSoort = _MutSoort_Activiteit;
  when 'OV. KOSTEN' then
    set @_PbrMutSoort = _MutSoort_OvKosten;
  when 'ARTIKEL' then
    set @_PbrMutSoort = _MutSoort_Artikel;
  end case;

  //Medewerker alleen testen bij toevoegen en niet bij wijzigen
  if isNull(@Medewerker,'') <> '' then
    select PmwRelGid into @_PbrRelGid from tabProjectMedewerker where PmwZoekcode = @Medewerker;

    if @_PbrRelGid is null then
      call Raise(20720, 'Medewerker'); //(20720) %1! niet gevonden!
    end if;
  else
    //Bij Activiteit is de medewerker verplicht
    if (@_PbrMutSoort = _MutSoort_Activiteit) and (@Regelnummer is null) then
      call Raise(20700,'Medewerker'); // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  //Status
  //Zet het soort om naar PbrStatus
  if @Status not in ('CONCEPT', 'INGELEVERD', 'AFGEKEURD', 'GEACCEPTEERD', null) then
    call Raise(20700,'Status'); // (20700) Ongeldige waarde: %1!
  end if;

  case @Status
  when 'CONCEPT' then
    set @_PbrStatus = 0;
  when 'INGELEVERD' then
    set @_PbrStatus = 1;
  when 'AFGEKEURD' then
    set @_PbrStatus = 2;
  when 'GEACCEPTEERD' then
    set @_PbrStatus = 3;
  end case;

  //Uren ingevoerd als
  //Zet het soort om naar PbrStatus
  if @UrenIngevoerdAls not in ('DECIMALEN', 'TIJDNOTATIE', 'BEGIN/EINDTIJD', null) then
    call Raise(20700,'UrenIngevoerdAls'); // (20700) Ongeldige waarde: %1!
  end if;

  case @UrenIngevoerdAls
  when 'DECIMALEN' then
    set @_PbrUrenIngevoerdAls = 0;
  when 'TIJDNOTATIE' then
    set @_PbrUrenIngevoerdAls = 1;
  when 'BEGIN/EINDTIJD' then
    set @_PbrUrenIngevoerdAls = 2;
  end case;

  //Directe Inkoop
  //Wat velden checken
  if (@DirecteInkoop = 'JA') and (@_PbrMutSoort = _MutSoort_Activiteit) then
    call Raise(20700,'DirecteInkoop'); // (20700) Ongeldige waarde: %1!
  end if;

  if (@DirecteInkoop = 'JA') or (@_PbrMutSoort = _MutSoort_OvKosten) then
    if isNull(@Magazijn, '') <> '' then
      call Raise(20700,'Magazijn'); // (20700) Ongeldige waarde: %1!
    end if;

    if isNull(@Locatie, '') <> '' then
      call Raise(20700,'Locatie'); // (20700) Ongeldige waarde: %1!
    end if;

    if isNull(@Partij, '') <> '' then
      call Raise(20700,'Partij'); // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  if (@DirecteInkoop = 'NEE') and (isNull(@Leverancier, '') <> '') then
    call Raise(20700,'Leverancier'); // (20700) Ongeldige waarde: %1!
  end if;

  if @_PbrMutSoort in (_MutSoort_OvKosten, _MutSoort_Artikel)  then
    if (@DirecteInkoop = 'JA') then
      set @_PbrIsDirecteInkoop = _qcJa;

      //Leverancier
      if isNull(@Leverancier, '') = '' then
        call Raise(20700,'Leverancier'); // (20700) Ongeldige waarde: %1!
      end if;

      select NawFilNawGid into @_PbrLeverancierNawGid from tabNawFile where NawFilNummer = @Leverancier and NawFilFonId= 'C';

      if @_PbrLeverancierNawGid is null then
        call Raise(20720, 'Leverancier'); //(20720) %1! niet gevonden!
      end if;
    else
      //Alleen vullen bij artikelregels
      if @_PbrMutSoort = _MutSoort_Artikel then
      begin
        declare @_ArtIsPartijRegistreren smallint default _qcNee;
        declare @_ArtSerienrRegistreren smallint default _qcNee;
        declare @_DefaultMagGid integer default null;

        if (@_Artgid is not null) and (@ArtikelTarief is null) then
          select ArtIsPartijRegistreren, ArtSerienrRegistreren, BepaalDefaultMagazijnGid(ArtGid, 60 /*projectmutaties*/, null)
            into @_ArtIsPartijRegistreren, @_ArtSerienrRegistreren, @_DefaultMagGid
          from tabArtikel
          where (ArtGid = @_ArtGid)
            and (Artsoort = 2 /*Artikel*/);
        else
          select Artgid, ArtIsPartijRegistreren, ArtSerienrRegistreren, BepaalDefaultMagazijnGid(ArtGid, 60 /*projectmutaties*/, null)
            into @_ArtGid, @_ArtIsPartijRegistreren, @_ArtSerienrRegistreren, @_DefaultMagGid
          from tabArtikel
          where (ArtCode = @ArtikelTarief)
            and (Artsoort = 2 /*Artikel*/);
        end if;

        if @_ArtGid is null then
          call Raise(20700,'ArtikelTarief'); // (20700) Ongeldige waarde: %1!
        end if;

        //Magazijn
        if isNull(@Magazijn, '') = '' then
          //Gebruik het default magazijn van het artikel als er geen magazijn is ingevuld
          set @_PbrMagGid = @_DefaultMagGid;
        else
          select MagGid into @_PbrMagGid from tabMagazijn where MagCode = @Magazijn;
        end if;

        if @_PbrMagGid is null then
          call Raise(20720, 'Magazijn'); //(20720) %1! niet gevonden!
        end if;

        //Locatie
        if isNull(@Locatie, '') = '' then
          //Gebruik de default locatie als deze bestaat. Als hij niet bestaat wordt hij aaangemaakt.
          call CreateStandaardLocatieVoorArtikelMagazijn(@_ArtGid, @_PbrMagGid, @_PbrLocGid);
        else
          select LocGid into @_PbrLocGid from tabLocatie where LocNaam = @Locatie and LocMagGid = @_PbrMagGid;
        end if;

        if @_PbrLocGid is null then
          call Raise(20720, 'Locatie'); //(20720) %1! niet gevonden!
        end if;

        //Partij, Alleen als partijregistrerend of serienummer registrerend (dan de default partij)
        if (_qcJa in (@_ArtIsPartijRegistreren, @_ArtSerienrRegistreren)) then
          if isNull(@Partij, '') = '' or ((@_ArtIsPartijRegistreren=_qcNee) and (@_ArtSerienrRegistreren=_qcJa)) then
            //Geen partij ingevuld of partijregistrerend, pak dan partij standaard
            set @Partij = '(Standaard)';
          end if;

          select ArtPartijGid into @_PbrArtPartijGid
          from tabArtikelPartij
          where (ArtPartijArtGid = @_ArtGid)
            and (ArtPartijNummer = @Partij);

          if @_PbrArtPartijGid is null then
            call Raise(20720, 'Partij'); //(20720) %1! niet gevonden!
          end if;
        else
          if (isNull(@Partij, '') <> '') and (@_ArtIsPartijRegistreren = _qcNee) then
            call Raise(20537); //(20537) Artikel is geen partij registrerend artikel!
          end if;
        end if;
      end;
      end if;
    end if;
  end if;

  call ProjectBoekingsRegelToevoegenWijzigen(
    /*In*/
    @PbkGid = @_PbkGid,
    @PbrGid = @_PbrGid,
    @Soort = @_PbrMutSoort,
    @ProjectCode = @ProjectCode,
    @ProjectOnderdeel = @ProjectOnderdeelZoekCode,
    @PmwRelGid = @_PbrRelGid,
    @MutatieDatum = @Datum,
    @ArtikelTarief = @ArtikelTarief,
    @GekoppeldAanActiviteit = @GekoppeldAanActiviteit,
    @Omschrijving = @Omschrijving,
    @Categorieen = @Categorieen,
    @Kostprijs = @Kostprijs,
    @Verkoopprijs = @Verkoopprijs,
    @Status = @_PbrStatus,
    @UrenIngevoerdAls = @_PbrUrenIngevoerdAls,
    @AantalGeboekt = @AantalBesteed,
    @AantalGeboektBeginTijd = @Begintijd,
    @AantalDeclarabel = @AantalDeclarabel,
    @DirecteInkoop = @_PbrIsDirecteInkoop,
    @LeverancierNawGid = @_PbrLeverancierNawGid,
    @MagGid = @_PbrMagGid,
    @LocGid = @_PbrLocGid,
    @PartijGid = @_PbrArtPartijGid,
    @Opmerking = @Opmerking,
    /*Out*/
    @NieuwPbrGid = @_PbrGid);

  // Ophalen resultaat
  select PbrRegelNr as Regel
  from tabProjectBoekingsRegel
  where pbrGid = @_PbrGid;

  //call TraceEind('WebSvcProc_ProjectMutatie_Regel_ToevoegenWijzigen > eind');
end;


create or replace procedure WebSvcProc_ProjectMutatie_Regel_Verwijderen(
  in @Volgnummer numeric(10,0) default null,
  in @Regelnummer integer default null
)
begin
  declare _qcNee smallint = 0;

  declare @_PbkGid integer;
  declare @_PbrGid integer;
  declare @_PbrMutSoort smallint default null; /* 0= Activiteit, 1= Ov. kosten, 2= Artikel*/
  declare @_PbrStatus smallint default null; /*0=Concept, 1=Ingeleverd, 2=Afgekeurd, 3=Geaccepteerd*/

  //call TraceBegin('WebSvcProc_ProjectMutatie_Regel_Verwijderen');

  // Module: is er geen Projecten-basis actief , dan kan je geen projectmutatiekop aanmaken.
  if IsModuleActive('pr') = _qcNee then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  //Zoek het volgnummer
  if (@Volgnummer is null) then
    call Raise(20700,'Volgnummer'); // (20700) Ongeldige waarde: %1!
  end if;

  select PbkGid into @_PbkGid from tabProjectBoekingsKop where PbkVolgNummer = @Volgnummer;

  if (@_PbkGid is null) then
    call Raise(20720, 'Volgnummer'); //(20720) %1! niet gevonden!
  end if;

  //Zoek de regel
  if (@Regelnummer is null) then
    call Raise(20700,'Regelnummer'); // (20700) Ongeldige waarde: %1!
  end if;

  select PbrGid, PbrStatus
  into @_PbrGid, @_PbrStatus
  from tabProjectBoekingsRegel
  where PbrPbkGid = @_PbkGid
    and PbrRegelnr = @Regelnummer;

  if (@_PbrGid is null) then
    call Raise(20720, 'Regelnummer'); //(20720) %1! niet gevonden!
  end if;

  //Als de regel status ingeleverd heeft mag er niets meer worden gewijzigd
  if (@_PbrStatus in (1/*=Ingeleverd*/, 3/*=Geaccepteerd*/)) then
    call Raise(20780, _U('Verwijderen'), _U('Projectmutatieregel moet de status ''Concept'' of ''Afgekeurd'' hebben!')); //(20780) %1! niet mogelijk: %2!.
  end if;

  delete tabProjectBoekingsRegel where PbrGid = @_PbrGid;

  //call TraceEind('WebSvcProc_ProjectMutatie_Regel_Verwijderen');
end;


create or replace procedure WebSvcProc_ProjectOnderdeel_Toevoegen
( in @ProjectCode nchar(10) default null,
  in @ProjectOnderdeelZoekCodeOuder nchar(40) default '',
  in @ProjectOnderdeelZoekCode nchar(10) default null,
  in @ProjectOnderdeelOmschrijving nchar(80) default null,
  in @ProjectOnderdeelSoort nchar(7) default 'REGIE', /*0=Regie 1=Termijn*/
  in @HeeftAfwijkendBedragPrijsopgave smallint default 0, //0=nee 1=ja
  in @AfwijkendBedragPrijsopgave numeric(15,3) default null,
  in @BtwCode integer default null,
  in @OnderdeelspecificerenOpDePrijsopgave smallint default 1,  //0=nee 1=ja
  in @HeeftAfwijkendeOmschrijvingOpDePrijsopgave smallint default 0,  //0=nee 1=ja
  in @AfwijkendeOmschrijvingOpDePrijsopgave long nvarchar default null,
  in @AfwijkendeFactuurverdichting smallint default 0,
  //Detaillering van Activiteiten op facturen
  in @DetailleringActActiviteitSpecificeren smallint default 0,
  in @DetailleringActOpbrengstGroepSpecificeren smallint default 0,
  in @DetailleringActMedewerkerSpecificeren smallint default 0,
  //Detaillering van artikelen op facturen
  in @DetailleringArtArtikelSpecificeren smallint default 0,
  in @DetailleringArtOpbrengstGroepSpecificeren smallint default 0,
  //Detaillering van overige kosten op facturen
  in @DetailleringOverigOverigekostenSpecificeren smallint default 0,
  in @DetailleringOverigOpbrengstGroepSpecificeren smallint default 0,
  //Gegevens op factuur apart afdrukken of sommeren op hoger onderdeel
  in @ApartAfdrukkenActiviteiten smallint default 0,
  in @ApartAfdrukkenArtikelen smallint default 0,
  in @ApartAfdrukkenOverigeKosten smallint default 0,
  in @AfdrukkenAlleActiviteitsMutaties smallint default 0,
  in @AfdrukkenAlleArtikelMutaties smallint default 0,
  in @AfdrukkenAlleOverigeKostenMutaties smallint default 0,
  in @OmschrijvingOpFactuur long nvarchar default null
)
result (PbGid integer)
begin
  declare @_qcJA smallint = 1;
  declare @_qcNEE smallint = 0;

  declare @_PbGid integer;

  //set @@ErrorTextProcedure = 'WebSvcProc_ProjectOnderdeel_Toevoegen > @ProjectOnderdeelZoekCode = ' + @ProjectOnderdeelZoekCode;
  //call TraceBegin(@@ErrorTextProcedure);

  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen Projecten-basis actief , dan kan je geen project aanmaken.
  if IsModuleActive('pr') = 0 then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    //Variabelen
    declare @_ProjGid integer;
    declare @_PbParentPbGid integer;
    declare @_PbSoort smallint;
    declare @_ProjStatus smallint;
    declare @_ProjSoort smallint;

    //Projectcode ophalen
    select ProjGid, ProjStatus, ProjSoort
    into @_ProjGid, @_ProjStatus, @_ProjSoort
    from tabProject
    where ProjCode = @ProjectCode;

    if (@_ProjGid is null) then
      call Raise(20700, 'ProjectCode'); //Ongeldige waarde: %1
    end if;

    if (@_ProjStatus = 3 /*Afgesloten*/) then
      call Raise(20780, _U('Toevoegen projectonderdeel'), _U('De status van het project is ''Afgesloten''!')); // <Actie> niet mogelijk: <Reden>.
    end if;

    //Projectonderdeel zoekcode Parent
    select pbGid
    into @_PbParentPbGid
    from tabProjectBoom
    where PbZoekcode = isNull(@ProjectOnderdeelZoekCodeOuder,'')
      and PbProjgid = @_ProjGid;

    if (@_PbParentPbGid is null) then
      call Raise(20700, 'ProjectOnderdeelZoekCodeOuder'); //Ongeldige waarde: %1
    end if;

    //Projectonderdeel zoekcode
    if (isNull(@ProjectOnderdeelZoekCode,'') = '') then
      call Raise(20700, 'ProjectOnderdeelZoekCode'); //Ongeldige waarde: %1
    end if;

    if exists(select 1 where @ProjectOnderdeelZoekCode not REGEXP '[a-zA-Z0-9]{1,10}' ) then
      call Raise(20700, 'ProjectOnderdeelZoekCode'); //Ongeldige waarde: %1
    end if;

    //ProjectOnderdeelSoort
    //0=Regie 1=Termijn
    if (@_ProjSoort = 2 /*Intern*/) then
      //Bij een Intern project altijd termijn
      set @ProjectOnderdeelSoort = 'TERMIJN';
    end if;

    select case isnull(trim(upper(@ProjectOnderdeelSoort)),'')
            when 'REGIE' then 0
            when 'TERMIJN' then 1
            When '' then 0
            else null
           end case
    into @_PbSoort;

    if @_PbSoort is null then
      call Raise(20700, 'ProjectOnderdeelSoort'); //Ongeldige waarde: %1
    end if;

    //ProjectOnderdeelBtwCode
    if (@BtwCode is not null) and (not exists(select BTWCode from tabBTW where BTWCode = @BtwCode)) then
      call Raise(20720, 'BtwCode') ; // %1 niet gevonden!
    end if;

    //Boolean velden bekijken
    set @HeeftAfwijkendBedragPrijsopgave = isNull(@HeeftAfwijkendBedragPrijsopgave,@_qcNEE);
    set @OnderdeelspecificerenOpDePrijsopgave = isNull(@OnderdeelspecificerenOpDePrijsopgave,@_qcJA);
    set @HeeftAfwijkendeOmschrijvingOpDePrijsopgave = isNull(@HeeftAfwijkendeOmschrijvingOpDePrijsopgave,@_qcNEE);

    if (@HeeftAfwijkendBedragPrijsopgave not in (@_qcJA, @_qcNEE)) then
      call Raise(20700, 'HeeftAfwijkendBedragPrijsopgave'); //Ongeldige waarde: %1
    end if;
    if (@OnderdeelspecificerenOpDePrijsopgave not in (@_qcJA, @_qcNEE)) then
      call Raise(20700, 'OnderdeelspecificerenOpDePrijsopgave'); //Ongeldige waarde: %1
    end if;
    if (@HeeftAfwijkendeOmschrijvingOpDePrijsopgave not in (@_qcJA, @_qcNEE)) then
      call Raise(20700, 'HeeftAfwijkendeOmschrijvingOpDePrijsopgave'); //Ongeldige waarde: %1
    end if;

    //Project locken
    call WebSvcHulpProc_ProjectExclusiefLocken(@_ProjGid, 'KingWebService', @@Spid, @@LoginTime);

    //En nu toevoegen
    insert into tabProjectBoom (
      PbBtwCodeAfwijkend,
      //PbBtwCodeVastgesteld, //trigger en zie VaststellenProjectOfferte.sp
      PbIsOfferteBedragAfwijkend,
      //PbIsOfferteBedragVastgesteld, //trigger en zie VaststellenProjectOfferte.sp
      PbIsOfferteTekstAfwijkend,
      //PbIsOfferteTekstVastgesteld, //trigger en zie VaststellenProjectOfferte.sp
      //PbLevel,
      PbOfferteBedragAfwijkend,
      //PbOfferteBedragVastgesteld, //trigger en zie VaststellenProjectOfferte.sp
      PbOfferteTekstAfwijkend,
      //PbOfferteTekstVastgesteld, //trigger en zie VaststellenProjectOfferte.sp
      PbOmschr,
      PbParentPbGid,
      //PbPbCount,
      //PbPercGereed,
      PbProjGid,
      //PbPvcCount,
      PbSoort,
      PbUitsplitsen,
      //PbUitsplitsenVastgesteld, //trigger en zie VaststellenProjectOfferte.sp
      //PbVolgNr,
      PbZoekCode,
      PbZoekcodeSuffix
    )
    values (
      @BtwCode,
      //:PbBtwCodeVastgesteld,
      @HeeftAfwijkendBedragPrijsopgave,
      //:PbIsOfferteBedragVastgesteld,
      @HeeftAfwijkendeOmschrijvingOpDePrijsopgave,
      //:PbIsOfferteTekstVastgesteld,
      //:PbLevel,
      @AfwijkendBedragPrijsopgave,
      //:PbOfferteBedragVastgesteld,
      @AfwijkendeOmschrijvingOpDePrijsopgave,
      //:PbOfferteTekstVastgesteld,
      @ProjectOnderdeelOmschrijving,
      @_PbParentPbGid,
      //:PbPbCount,
      //:PbPercGereed,
      @_ProjGid,
      //:PbPvcCount,
      @_PbSoort, /*0=Regie 1=Termijn*/
      @OnderdeelspecificerenOpDePrijsopgave,
      //:PbUitsplitsenVastgesteld,
      //:PbVolgNr,
      @ProjectOnderdeelZoekCode,
      GenereerNieuweProjectSuffix(@_PbParentPbGid, @ProjectOnderdeelZoekCode)
    );

    set @_PbGid = @@Identity;

    if (isNull(@AfwijkendeFactuurverdichting,@_qcNEE) <> @_qcNEE) then
      //Alleen als Appart afdrukken aan staat
      if (@ApartAfdrukkenActiviteiten = @_qcNEE) then
        set @AfdrukkenAlleActiviteitsMutaties = @_qcNEE
      end if;

      if (@ApartAfdrukkenArtikelen = @_qcNEE) then
        set @AfdrukkenAlleArtikelMutaties = @_qcNEE
      end if;

      if (@apartAfdrukkenOverigeKosten = @_qcNEE) then
        set @AfdrukkenAlleOverigeKostenMutaties = @_qcNEE
      end if;

      //1 van deze @Afdrukken... moet aan staan. anders mag je geen omschrijving invullen
      if (@AfdrukkenAlleActiviteitsMutaties + @AfdrukkenAlleArtikelMutaties + @AfdrukkenAlleOverigeKostenMutaties = 0) then
        set @OmschrijvingOpFactuur = null;
      end if;

      //Factuurverdichting
      call WebSvcHulpProc_ProjectFactuurVerdichting_Toevoegen(
        @_PBGid,
        //Detaillering van Activiteiten op facturen
        @DetailleringActActiviteitSpecificeren,
        @DetailleringActOpbrengstGroepSpecificeren,
        @DetailleringActMedewerkerSpecificeren,
        //Detaillering van artikelen op facturen
        @DetailleringArtArtikelSpecificeren,
        @DetailleringArtOpbrengstGroepSpecificeren,
        //Detaillering van overige kosten op facturen
        @DetailleringOverigOverigekostenSpecificeren,
        @DetailleringOverigOpbrengstGroepSpecificeren,
        //Per factuurregel projectmutaties afdrukken
        @ApartAfdrukkenActiviteiten,
        @AfdrukkenAlleActiviteitsMutaties,
        @ApartAfdrukkenArtikelen,
        @AfdrukkenAlleArtikelMutaties,
        @apartAfdrukkenOverigeKosten,
        @AfdrukkenAlleOverigeKostenMutaties,
        @OmschrijvingOpFactuur);
    end if;
  end;

  // Ophalen resultaat
  select @_PBGid as PbGid;

  //set @@ErrorTextProcedure = 'WebSvcProc_ProjectOnderdeel_Toevoegen > @_PBGid = ' + @_PBGid;
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure WebSvcProc_ProjectTermijn_Toevoegen
( in @ProjectCode nchar(10) default null,
  in @TermijnNummer integer default null, //Als null dan hoogste nummer + 1
  in @Status  nchar(11) default 'Concept', /*0=Concept 1=Vrijgegeven*/
  in @Opmerking long nvarchar default null,
  in @FacturerenVoor Date default null,
  in @TeFactureren numeric(15,3) default 0,
  in @BtwCode integer default null,
  in @TekstOpFactuur long nvarchar default null
)
result (PtmGid integer)
begin
  declare @_PtmGid integer;

  //set @@ErrorTextProcedure = 'WebSvcProc_ProjectTermijn_Toevoegen > @ProjectCode = ' + @ProjectCode;
  //call TraceBegin(@@ErrorTextProcedure);

  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen Projecten-basis actief , dan kan je geen project aanmaken.
  if IsModuleActive('pr') = 0 then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  if IsModuleActive('pt') = 0 then
    call Raise(20790, _U('Optie Projecten-termijnen')); // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    //Variabelen
    declare @_ProjGid integer;
    declare @_ProjStatus smallint;
    declare @_ProjSoort smallint; //0=Regie 1=Termijn 2=Intern 3=Proef
    declare @_PtmTermijnNr integer;
    declare @_PtmStatus smallint;

    //Projectcode ophalen
    select ProjGid, ProjStatus, ProjSoort
    into @_ProjGid, @_ProjStatus, @_ProjSoort
    from tabProject
    where ProjCode = @ProjectCode;

    if (@_ProjGid is null) then
      call Raise(20700, 'ProjectCode'); //Ongeldige waarde: %1
    end if;

    if (@_ProjStatus = 3 /*Afgesloten*/) then
      call Raise(20780, _U('Toevoegen projecttermijn'), _U('De status van het project is ''Afgesloten''!')); // <Actie> niet mogelijk: <Reden>.
    end if;

    if (@_ProjSoort not in (0 /*Regie*/, 1 /*Termijn*/)) then
      call Raise(20780, _U('Toevoegen projecttermijn'), _U('Het soort project dient ''Regie'' of ''Termijn'' te zijn!')); // <Actie> niet mogelijk: <Reden>.
    end if;

    //TermijnNr
    //Default: hoogste termijnnummer + 1, per project.
    set @_PtmTermijnNr = isNull(@TermijnNummer,0);
    if isNull(@_PtmTermijnNr,0) = 0 then
        select isnull(max(PtmTermijnNr), 0) + 1
        into @_PtmTermijnNr
        from tabProjectTermijn
        where PtmTermijnNr < 999
          and PtmProjGid = @_ProjGid;
    end if;

    //Termijnnummer bestaat al
    if exists(select 1 from tabProjectTermijn where PtmTermijnNr =  @_PtmTermijnNr and PtmProjGid = @_ProjGid) then
      call Raise(20780, _U('Toevoegen projecttermijn'), _U('Het opgegeven termijnnummer bestaat al!')); // <Actie> niet mogelijk: <Reden>.
    end if;

    //Status
    ///*0=Concept 1=Vrijgegeven*/
    select case isnull(trim(upper(@Status)),'')
            when 'CONCEPT' then 0
            when 'VRIJGEGEVEN' then 1
            When '' then 0
            else null
           end case
    into @_PtmStatus;

    if @_PtmStatus is null then
      call Raise(20700, 'Status'); //Ongeldige waarde: %1
    end if;

    set @FacturerenVoor = (select DateTimeConversieVoorWebServices(@FacturerenVoor, @FacturerenVoor));
    if (@FacturerenVoor is null) then
      call Raise(20700, 'FacturerenVoor'); //Ongeldige waarde: %1
    end if;

    if (isNull(@TeFactureren,0) = 0) then
      call Raise(20700, 'TeFactureren'); //Ongeldige waarde: %1
    end if;

    //BtwCode
    if (@BtwCode is null) then
      call Raise(20700, 'BtwCode'); //Ongeldige waarde: %1
    end if;

    if (not exists(select BTWCode from tabBTW where BTWCode = @BtwCode)) then
      call Raise(20720, 'BtwCode') ; // %1 niet gevonden!
    end if;

  //Project locken
  call WebSvcHulpProc_ProjectExclusiefLocken(@_ProjGid, 'KingWebService', @@Spid, @@LoginTime);

  //En nu toevoegen
  insert into tabProjectTermijn (
      PtmBtwCode,
      PtmFacturerenVoor,
      PtmOpm,
      PtmProjGid,
      PtmStatus,
      PtmTeFactureren,
      PtmTekstOpFactuur,
      PtmTermijnNr
    )
    values (
      @BtwCode,
      @FacturerenVoor,
      @Opmerking,
      @_ProjGid,
      @_PtmStatus,
      @TeFactureren,
      @TekstOpFactuur,
      @_PtmTermijnNr
    );

    set @_PtmGid = @@PtmGid;
  end;

  // Ophalen resultaat
  select @_PtmGid as PtmGid;

  //set @@ErrorTextProcedure = 'WebSvcProc_ProjectTermijn_Toevoegen > @_PtmGid = ' + @_PtmGid;
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure WebSvcProc_ProjectVoorcalculatie_Toevoegen
( in @ProjectCode nchar(10) default null,
  in @ProjectOnderdeelZoekCode nchar(40) default null,
  in @VoorcalculatieSoort nchar(14) default 'ACTIVITEIT', /*0=Activiteit 1=Overige kosten 2=Artikel*/
  in @ArtikelNummer nchar(20) default null, /*Activiteit/Artikel/Overige kosten  */
  in @PartijNummer nchar(20)	default null, /*Moet een bestaand partijnummer zijn binnen het (partijregistrerend) artikel. */
  in @Omschrijving long nvarchar default null,
  in @Categorieen long nvarchar default null,
  in @MedewerkerZoekCode nchar(10) default null,
  in @AantalPrijsOpgave numeric(15,3) default 1,
  in @VerkoopPrijs numeric(15,3) default 0,
  in @Kostprijs numeric(15,3) default 0,
  in @BedragPrijsopgave  numeric(15,3) default null,
  in @IsDirecteInkoop smallint default 0, //0=nee 1=ja
  in @Leverancier nchar(10) default null,
  in @AantalBegroot numeric(15,3) default 1
)
result (PvcGid integer)
begin
  declare @_qcJA smallint = 1;
  declare @_qcNEE smallint = 0;

  declare @_PvcGid integer;

  //set @@ErrorTextProcedure = 'WebSvcProc_ProjectVoorcalculatie_Toevoegen > @ProjectOnderdeelZoekCode = ' + @ProjectOnderdeelZoekCode;
  //call TraceBegin(@@ErrorTextProcedure);

  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen Projecten-basis actief , dan kan je geen project aanmaken.
  if IsModuleActive('pr') = 0 then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  if IsModuleActive('pv') = 0 then
    call Raise(20790, _U('Optie Projecten-voorcalculatie')); // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    //Variabelen
    declare @_ProjGid integer;
    declare @_PbGid integer;
    declare @_ProjStatus smallint;
    declare @_ProjOfferteStatus smallint;
    declare @_ProjBegrotingsStatus smallint;
    declare @_PvcMutSoort smallint; /*0=Activiteit 1=Overige kosten 2=Artikel*/
    declare @_pvcArtgid integer;
    declare @_pvcArtPartijGid integer;
    declare @_ArtIsPartijRegistreren smallint = @_qcNEE;
    declare @_ArtikelTekst long nvarchar;
    declare @_PvcRelGid integer;
    declare @_PmwIsGeblokkeerd smallint;
    declare @_pArtDoorbelastPercentage numeric(15,3) = null;
    declare @_pArtBerekenVerkoopprijsObv smallint = 0;
    declare @_PvcLeverancierNawGid integer;
    declare @_pArtIsGeblokkeerd smallint;

    //Projectcode ophalen
    select ProjGid, ProjStatus, ProjOfferteStatus, ProjBegrotingsStatus
    into @_ProjGid, @_ProjStatus, @_ProjOfferteStatus, @_ProjBegrotingsStatus
    from tabProject
    where ProjCode = @ProjectCode;

    if (@_ProjGid is null) then
      call Raise(20700, 'ProjectCode'); //Ongeldige waarde: %1
    end if;

    if (@_ProjStatus = 3 /*Afgesloten*/) then
      call Raise(20780, _U('Toevoegen projectvoorcalculatie'), _U('De status van het project is ''Afgesloten''!')); // <Actie> niet mogelijk: <Reden>.
    end if;

    //Status Prijsopgave is vastgesteld
    if @_ProjOfferteStatus = 1 /*Vastgesteld*/ then
      call Raise(20780, _U('Toevoegen projectvoorcalculatie'), _U('De status prijsopgave is ''Vastgesteld''!')); // <Actie> niet mogelijk: <Reden>.
    end if;

    //Status begroting is vastgesteld
    if @_ProjBegrotingsStatus = 1 /*Vastgesteld*/ then
      call Raise(20780, _U('Toevoegen projectvoorcalculatie'), _U('De begrotingsstatus is ''Vastgesteld''!')); // <Actie> niet mogelijk: <Reden>.
    end if;

    //Projectonderdeel zoekcode
    select pbGid
    into @_PbGid
    from tabProjectBoom
    where PbZoekCode = @ProjectOnderdeelZoekCode
      and PbProjgid = @_ProjGid
      and PbLevel > 1;

    if (@_PbGid is null) then
      call Raise(20700, 'ProjectOnderdeelZoekCode'); //Ongeldige waarde: %1
    end if;

    //VoorcalculatieSoort
    //0=Activiteit 1=Overige kosten 2=Artikel
    select case isnull(trim(upper(@VoorcalculatieSoort)),'')
            when 'ACTIVITEIT' then 0
            when 'OVERIGE KOSTEN' then 1
            when 'ARTIKEL' then 2
            When '' then 0
            else null
           end case
    into @_PvcMutSoort;

    if @_PvcMutSoort is null then
      call Raise(20700, 'VoorcalculatieSoort'); //Ongeldige waarde: %1
    end if;

    //Artikelnummer
    if (isNull(@ArtikelNummer,'') = '') then
      call Raise(20700, 'Artikelnummer'); //Ongeldige waarde: %1
    end if;

    if @_PvcMutSoort = 2 /*Artikel*/ then
      select artgid, ArtIsPartijRegistreren, IsNull(ArtTekst, ArtOms)
      into @_pvcArtgid, @_ArtIsPartijRegistreren, @_ArtikelTekst
      from tabArtikel
      left outer join tabArtikelTeksten on (ArtTekstArtGid = ArtGid and
                                           ((ArtSoort = 2 and ArtTekstDocSoort = 50) or (ArtSoort<>2 and ArtTekstDocSoort is null)) and
                                           ArtTaalGid = (Select DefaultTaalGid from tabVasteGegevens))
      where artCode = @ArtikelNummer
        and artSoort = 2 /*Artikel*/;
    else
      select artgid, pArtIsGeblokkeerd, pArtBerekenVerkoopprijsObv, pArtDoorbelastPercentage, IsNull(ArtTekst, ArtOms)
      into @_pvcArtgid, @_pArtIsGeblokkeerd, @_pArtBerekenVerkoopprijsObv, @_pArtDoorbelastPercentage, @_ArtikelTekst
      from tabArtikel
      inner join tabProjectArtikel on pArtArtGid = ArtGid
      left outer join tabArtikelTeksten on (ArtTekstArtGid = ArtGid and
                                           ((ArtSoort = 2 and ArtTekstDocSoort = 50) or (ArtSoort<>2 and ArtTekstDocSoort is null)) and
                                           ArtTaalGid = (Select DefaultTaalGid from tabVasteGegevens))
      where artCode = @ArtikelNummer
        and artSoort = 1 /*Tarief*/
        and pArtSoort = @_PvcMutSoort; /*Activiteit of Overige kosten*/

      if (@_pArtIsGeblokkeerd = @_qcJA) then
      begin
        declare @_Melding nchar(100) = _U('De %1! is geblokkeerd voor gebruik bij projecten!', LOWER(@VoorcalculatieSoort));
        call Raise(20780, _U('Toevoegen projectvoorcalculatie'),@_Melding);  // <Actie> niet mogelijk: <Reden>.
      end;
      end if
    end if;

    if (@_pvcArtgid is null) then
      call Raise(20720, 'ArtikelNummer') ; // %1 niet gevonden!
    end if;

    //Artikelpartij
    if (isNull(@PartijNummer,'') <> '') and (@_ArtIsPartijRegistreren = @_qcJA) then
      select ArtPartijgid
      into @_pvcArtPartijGid
      from tabartikelPartij
      where artPartijArtGid = @_PvcArtGid
        and ArtPartijNummer = @PartijNummer;

      if (@_pvcArtPartijGid is null) then
        call Raise(20700, 'PartijNummer'); //Ongeldige waarde: %1
      end if
    else
      set @_PvcArtPartijGid = null;
    end if;

    //Medewerker
    if (@MedewerkerZoekCode is not null) and (@VoorcalculatieSoort = 'ACTIVITEIT') and
    (@_ProjOfferteStatus = 0 /*Concept*/) and (@_ProjBegrotingsStatus = 0 /*Concept*/) then
      select PmwRelGid, PmwIsGeblokkeerd
      into @_PvcRelGid, @_PmwIsGeblokkeerd
      from tabProjectMedewerker
      where PmwZoekCode = @MedewerkerZoekCode;

      if @_PvcRelGid is null then
        call Raise(20720, 'MedewerkerZoekCode') ; // %1 niet gevonden!
      end if;

      if (@_PmwIsGeblokkeerd = @_qcJA) then
        call Raise(20780, _U('Toevoegen projectvoorcalculatie'), _U('De medewerker is geblokkeerd voor gebruik in projecten!')); // <Actie> niet mogelijk: <Reden>.
      end if

    else
      set @_PvcRelGid = null;
    end if;

    //Aantallen
    set @AantalPrijsOpgave = isNull(@AantalPrijsOpgave, 1);
    set @AantalBegroot = isNull(@AantalBegroot, 1);

    //DirecteInkoop
    set @IsDirecteInkoop = isNull(@IsDirecteInkoop,@_qcNEE);

    if (@IsDirecteInkoop not in (@_qcJA, @_qcNEE)) then
      call Raise(20700, 'IsDirecteInkoop'); //Ongeldige waarde: %1
    end if;

    begin
      declare @_PvcRelatieNawGid integer;
      declare @_RelatieNAWBestand nchar(3);
      declare @_NAWBestandCrediteur nchar(3) = 'C';
      declare @_NAWBestandBedrijf nchar(3) = 'B';

      select NawFilNawGid, NawFilFonId
      into @_PvcRelatieNawGid, @_RelatieNAWBestand
      from tabProjectMedewerker
      inner join (tabRelatie
                    inner join tabNawFile on (RelNawGid = NawFilNawGid)
                  ) on (RelGid = PmwRelGid)
      where PmwRelGid = @_PvcRelGid
        and NawFilFonId in (@_NAWBestandBedrijf, @_NAWBestandCrediteur);

      if (@_RelatieNAWBestand = @_NAWBestandCrediteur) then
        //Als de medewerker gekoppeld is aan een crediteur, dan die gebruiken als Directe inkoop
        set @IsDirecteInkoop = @_qcJA;
        set @_PvcLeverancierNawGid = @_PvcRelatieNawGid;
      else
        if (isNull(@Leverancier,'') <> '') and (@_PvcRelGid is null) then
          set @IsDirecteInkoop = @_qcJA;

          select NawFilNawGid into @_PvcLeverancierNawGid
          from tabNawFile
          inner join tabFileOfNaw on FonGid = NawFilFonGid and FonId = @_NAWBestandCrediteur
          where NawFilNummer = @Leverancier;
        else
          set @IsDirecteInkoop = @_qcNEE;
          set @_PvcLeverancierNawGid = null;
        end if;
      end if;

      if (@_PvcLeverancierNawGid is null) and (@IsDirecteInkoop = @_qcJA) then
        call Raise(20720, 'Leverancier') ; // %1 niet gevonden!
      end if;

      if (@IsDirecteInkoop = @_qcNEE) then
        set @_PvcLeverancierNawGid = null;
      end if;
    end;

    //Kostprijs
    if (@IsDirecteInkoop = @_qcNEE) and (@_pArtBerekenVerkoopprijsObv = 0 /*Doorbelasten tegen percentage van de kostprijs*/)
    then
      //Kostprijs ophalen
      set @KostPrijs = null;
    end if;

    if (@Kostprijs is null) or (@VerkoopPrijs is null) then
    begin
      declare @_Kostprijs numeric(15,3);
      declare @_Verkoopprijs numeric(15,3);

      call BepaalProjectVerkoopEnKostprijs(@_ProjGid, @_PbGid, @_pvcArtgid, @_PvcArtPartijGid, @_PvcRelGid, @AantalPrijsOpgave, @_Verkoopprijs, @_Kostprijs, null, null);

      set @Kostprijs = IsNull(@Kostprijs, @_Kostprijs);
      set @VerkoopPrijs = IsNull(@VerkoopPrijs, @_Verkoopprijs);
    end;
    end if;

    //@DoorbelastPercentage
    begin
      if (@_pArtBerekenVerkoopprijsObv = 0 /*Verkoopprijs excl. BTW*/) then
        set @_pArtDoorbelastPercentage = null;
      end if;

      if (@_pArtBerekenVerkoopprijsObv = 1 /*Doorbelasten tegen percentage van de kostprijs*/) then
        set @AantalPrijsOpgave = 1;
        set @AantalBegroot = 1;
        set @VerkoopPrijs = (@_pArtDoorbelastPercentage* @Kostprijs) / 100;
      end if;
    end;

    if (@VerkoopPrijs < 0) then
      call Raise(20780, _U('Toevoegen projectvoorcalculatie'), _U('%1! mag niet negatief zijn!', 'Verkoopprijs')); // <Actie> niet mogelijk: <Reden>.
    end if;

    //BedragPrijsopgave bij null default vullen
    if (@BedragPrijsopgave is null) then
      set @BedragPrijsopgave = @AantalPrijsOpgave * @VerkoopPrijs;
    end if;

    if (isNull(@Omschrijving,'') = '') then
      //Als de omschrijving leeg is vullen met de artikeltekst
      set @Omschrijving = @_ArtikelTekst;
    end if;

    //Project locken
    call WebSvcHulpProc_ProjectExclusiefLocken(@_ProjGid, 'KingWebService', @@Spid, @@LoginTime);

    //En nu toevoegen
    insert into tabProjectVoorcalculatie (
      PvcArtGid,
      PvcArtPartijGid,
      PvcBudAantal,
      PvcDoorbelastPercentage,
      PvcIsDirecteInkoop,
      PvcKostprijs,
      //  PvcKostprijsRegelTotaal,
      PvcLeverancierNawGid,
      PvcMutSoort,
      PvcOffAantal,
      PvcOfferteBedrag,
      PvcOmschr,
      //  PvcPartFactEenheidFactor,
      PvcPbGid,
      //  PvcPdosGid,
      //  PvcPrijsPer,
      PvcProjGid,
      PvcRelGid,
      PvcSelectieCodes,
      //  PvcVastgesteldBegrootBedrag,
      //  PvcVastgesteldBudAantal,
      //  PvcVastgesteldOffAantal,
      //  PvcVastgesteldOfferteBedrag,
      //  PvcVastgesteldOmschr,
      PvcVerkoopprijs
      //  PvcVerkoopprijsRegelTotaal,
      //  PvcVolgNr
      )
     values (
      @_PvcArtGid,
      @_PvcArtPartijGid,
      @AantalBegroot,
      @_pArtDoorbelastPercentage,
      @IsDirecteInkoop,
      @Kostprijs,
    //  :PvcKostprijsRegelTotaal,
      @_PvcLeverancierNawGid,
      @_PvcMutSoort,
      @AantalPrijsOpgave,
      @BedragPrijsopgave,
      @Omschrijving,
    //  :PvcPartFactEenheidFactor,
      @_PbGid,
    //  :PvcPdosGid,
    //  :PvcPrijsPer,
      @_ProjGid,
      @_PvcRelGid,
      @Categorieen,
    //  :PvcVastgesteldBegrootBedrag,
    //  :PvcVastgesteldBudAantal,
    //  :PvcVastgesteldOffAantal,
    //  :PvcVastgesteldOfferteBedrag,
    //  :PvcVastgesteldOmschr,
      @VerkoopPrijs
    //  :PvcVerkoopprijsRegelTotaal,
    //  :PvcVolgNr
      );

    set @_PvcGid = @@Identity;
  end;

  // Ophalen resultaat
  select @_PvcGid as PvcGid;

  //set @@ErrorTextProcedure = 'WebSvcProc_ProjectVoorcalculatie_Toevoegen > @_PvcGid = ' + @_PvcGid;
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure WebSvcProc_Project_LockVrijgeven(in @ProjectCode nchar(10))
begin
  declare @_ProjGid integer;
  // constanten
  declare @_QLOCKTABLENAME nchar(40) = 'tabProject';
  declare @_LockUserNaam nchar(40) = 'KingWebService';

  //call TraceBegin('WebSvcProc_Project_LockVrijgeven');

  // Module: is er geen Projecten-basis actief , dan kan je geen project aanmaken.
  if IsModuleActive('pr') = 0 then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken Project
  select ProjGid into @_ProjGid
  from tabProject
  where ProjCode = @ProjectCode;

  if @_ProjGid is null then
    call Raise(20720, 'ProjectCode'); // (20720) niet gevonden: %1!
  end if;

  //Elke api heeft zijn eigen connection id.
  //Het standaard lockmechanisme werkt in dat geval dan niet.
  //het vrij geven van een lock gaat dan niet op SpId, maar op usernaam
  begin // lock vrijgeven
    call LockReleaseOnId(@@SpId, @@LoginTime, 1, @_QLOCKTABLENAME, @_ProjGid);

    // gelockt, maar niet door KingWebService? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = @_QLOCKTABLENAME and qLockPKey = String(@_ProjGid) and qLockUser <> @_LockUserNaam) then
      call Raise(20741, 'ProjectCode'); // (20741) %1! is in gebruik!
    end if;

    // Lock opruimen.
    call LockReleaseOnUserName(@_LockUserNaam, 1, @_QLOCKTABLENAME, @_ProjGid);
  end; // lock vrijgeven

  //call TraceEind('WebSvcProc_Project_LockVrijgeven');
end;

