create or replace procedure WebSvcProc_Project_Toevoegen
( in @ProjectCode nchar(10) default null,
  in @ProjectOmschrijving nchar(80) default null,
  in @ProjectSoort nchar(7) default 'PROEF', //geldige waardes [0=Regie 1=Termijn 2=Intern 3=Proef]
  in @ProjectLeider nchar(10) default null,
  in @ProjectGroep nchar(4) default null,
  in @ProjectDebiteur nchar(10) default null,
  in @LandvanBestemming nchar(3) default null, //Alleen als afstandsverkopen actief is word deze ingevuld
  in @VeelvoudVanFactuureenheidVerplicht smallint default 0, //Default op NEE
  in @StandaardwaardeGebruikstoestemming smallint default 1, //Geldige waardes [1=Wel toegestaan 0=Niet toegestaan]
  in @KostprijsMedewerkerPrevaleert smallint default null,
  in @VerkoopprijsMedewerkerPrevaleert smallint default null,
  in @ProjectMutatiesBoekenAlsDeclarabel smallint default 1,
  in @ProjectStatus nchar(16) default 'CONCEPT', //Geldige waardes [0=Concept 1=In voorbereiding 2=Onderhanden 3=Afgesloten]
  in @StatusPrijsOpgave nchar(11) default 'CONCEPT', //Geldige waardes [0=Concept 1=Vastgesteld 2=Herzien]
  in @BegrotingsStatus nchar(11) default 'CONCEPT', //Geldige waardes [0=Concept 1=Vastgesteld 2=Herzien]
  in @Opmerking long nvarchar default null,
  //Facturering
  in @DefaultBTWcode integer default null,
  in @ContactPersoonnummer integer default null,
  in @BetalingsConditie integer default null,
  in @LeveringsConditie integer default null,
  in @IsInkoopcombinatie smallint default 0,
  in @DebiteurNummerFactuur nchar(10) default null,
  in @DebiteurNummerOmzet nchar(10)  default null,
  in @DebiteurnummerPrijsafspraken nchar(10) default null,
  //Detaillering van Activiteiten op facturen
  in @DetailleringActActiviteitSpecificeren smallint default 0,
  in @DetailleringActOpbrengstGroepSpecificeren smallint default 0,
  in @DetailleringActMedewerkerSpecificeren smallint default 0,
  //Detaillering van artikelen op facturen
  in @DetailleringArtArtikelSpecificeren smallint default 0,
  in @DetailleringArtOpbrengstGroepSpecificeren smallint default 0,
  //Detaillering van overige kosten op facturen
  in @DetailleringOverigOverigekostenSpecificeren smallint default 0,
  in @DetailleringOverigOpbrengstGroepSpecificeren smallint default 0,
  //Per factuurregel projectmutaties afdrukken
  in @AfdrukkenAlleActiviteitsMutaties smallint default 0,
  in @AfdrukkenAlleArtikelMutaties smallint default 0,
  in @AfdrukkenAlleOverigeKostenMutaties smallint default 0,
  in @OmschrijvingOpFactuur long nvarchar default null
)
result (ProjGid integer)
begin
  declare @_qcJA smallint = 1;
  declare @_qcNEE smallint = 0;
  declare @_NAWBestandDebiteur nchar(3) = 'D'; //Projectdebiteur is een 'D'ebiteur
  declare @_NAWBestandBedrijf nchar(3) = 'B';

  declare @_ProjGid integer;

  //set @@ErrorTextProcedure = 'WebSvcProc_Project_Toevoegen > @ProjectCode = ' + @ProjectCode;
  //call TraceBegin(@@ErrorTextProcedure);

  // ingangscontroles (licentie, opties, abonnement...)
  // Module: is er geen Projecten-basis actief , dan kan je geen project aanmaken.
  if IsModuleActive('pr') = 0 then
    call Raise(20790, _U('Optie Projecten-basis')); // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    //vaste gegevens projecten
    declare @_ProjVastStartNummerProjCode nchar(10);
    declare @_ProjVastStartNummerProjCodeWijzigen smallint;
    declare @_ProjVastKostprijsMedewerker smallint;
    declare @_ProjVastVerkoopprijsMedewerker smallint;
    declare @_ProjDebContactPersRelGid integer;
    declare @_ProjBtcNummer integer;
    declare @_ProjLvcNummer integer;
    declare @_ProjnawGidFactuur integer;
    declare @_ProjnawGidOmzet integer;
    declare @_ProjnawGidPrijzen integer;
    declare @_ProjIsInkoopCombinatie smallint;

    //Tabproject variabelen
    declare @_PbGid integer;
    declare @_ProjCode nchar(10);
    declare @_ProjSoort smallint;
    declare @_ProjProjLeiderRelGid integer;
    declare @_ProjProjGrpGid integer;
    declare @_ProjNawGid  integer;
    declare @_ProjLndGid integer;
    declare @_ProjStatus smallint;
    declare @_ProjOfferteStatus smallint;
    declare @_ProjBegrotingsStatus smallint;

    select ProjVastStartNummerProjCode,
           ProjVastStartNummerProjCodeWijzigen,
           ProjVastKostprijsMedewerker,
           ProjVastVerkoopprijsMedewerker
    into @_ProjVastStartNummerProjCode, @_ProjVastStartNummerProjCodeWijzigen, @_ProjVastKostprijsMedewerker, @_ProjVastVerkoopprijsMedewerker
    from tabProjectVastegegevens
    where ProjVastId = 1;

    //Projectcode genereren
    if (isNull(@_ProjVastStartNummerProjCode,'') <> '') then
      if (isNull(@ProjectCode,'') <> '') and (@_ProjVastStartNummerProjCodeWijzigen = @_qcJA) then
        //Opgegegeven projectcode gebruiken
        set @_ProjCode = @ProjectCode;
      else
        //Gebruik degene in vaste gegevens en verhoog deze gelijk
        call ProjectGenereerProjCode(@_ProjCode, null);
      end if
    else
      set @_ProjCode = @ProjectCode;
    end if;

    if (isNull(@_ProjCode,'') = '') then
      call Raise(20700, 'ProjectCode'); //Ongeldige waarde: %1
    end if;

    //ProjectCode bestaat al
    if exists(select 1 from tabProject where ProjCode = @_ProjCode) then
      call Raise(20721, 'ProjectCode');  //(20721) %1! komt al voor!
    end if;

    //ProjectSoort
    //0=Regie 1=Termijn 2=Intern 3=Proef
    select case isnull(trim(upper(@ProjectSoort)),'')
            when 'REGIE' then 0
            when 'TERMIJN' then 1
            when 'INTERN' then 2
            when 'PROEF' then 3
            When '' then 3
            else null
           end case
    into @_ProjSoort;

    if @_ProjSoort is null then
      call Raise(20700, 'ProjectSoort'); //Ongeldige waarde: %1
    end if;

    //Projectleider
    if @ProjectLeider is null then
      call Raise(20700 , _U('%1! is verplicht.', 'Projectleider')) ; // Ongeldige waarde: %1!
    end if;

    select pmwRelgid into @_ProjProjLeiderRelGid
    from tabProjectMedewerker
    where pmwZoekCode = @ProjectLeider;

    if @_ProjProjLeiderRelGid is null then
      call Raise(20720, 'Projectleider') ; // %1 niet gevonden!
    end if;

    //ProjectGroep
    if @ProjectGroep is null then
      call Raise(20700 , _U('%1! is verplicht.', 'ProjectGroep')) ; // Ongeldige waarde: %1!
    end if;

    select ProjGrpGid into @_ProjProjGrpGid
    from tabProjectGroep
    where ProjGrpGroep = @ProjectGroep;

    if @_ProjProjGrpGid is null then
      call Raise(20720, 'ProjectGroep') ; // %1 niet gevonden!
    end if;

    //Projectdebiteur
    if @_ProjSoort = 2 /*Intern*/ then
      select NawFilNawGid into @_ProjNawGid
      from tabNawFile
      where NawFilFonId = @_NAWBestandBedrijf;
    else
      if @ProjectDebiteur is null then
        call Raise(20700 , _U('%1! is verplicht.', 'ProjectDebiteur')) ; // Ongeldige waarde: %1!
      end if;

      select NawFilNawGid into @_ProjNawGid
      from tabNawFile
      inner join tabFileOfNaw on FonGid = NawFilFonGid and FonId = @_NAWBestandDebiteur
      where NawFilNummer = @ProjectDebiteur;
    end if;

    if @_ProjNawGid is null then
      call Raise(20720, 'ProjectDebiteur') ; // %1 niet gevonden!
    end if;

    //Land van bestemming (afstandsverkopen)
    if (@LandvanBestemming is not null) and exists(select 1 from tabRegistry where RegKey = 'AFSTANDSVERKOPEN' and Contents = '1') then
      select LndGid into @_ProjLndGid
      from tabLand
      where LndEigenCode = @LandvanBestemming;

      if @_ProjLndGid is null then
        call Raise(20720, 'LandvanBestemming') ; // %1 niet gevonden!
      end if;
    end if;

    //Prijsvoorkeur
    if (@KostprijsMedewerkerPrevaleert is null) then
      set @KostprijsMedewerkerPrevaleert = @_ProjVastKostprijsMedewerker;
    end if;

    if (@VerkoopprijsMedewerkerPrevaleert is null) then
      set @VerkoopprijsMedewerkerPrevaleert = @_ProjVastVerkoopprijsMedewerker;
    end if;

    //Projectmutaties boeken als declarabel.
    if (@_ProjSoort <> 2 /*Intern*/) or (@ProjectMutatiesBoekenAlsDeclarabel is null)then
      set @ProjectMutatiesBoekenAlsDeclarabel = @_qcJA;
    end if;

    //ProjectStatus
    //0=Concept,1=In voorbereiding,2=Onderhanden,3=Afgesloten
    select case isnull(trim(upper(@ProjectStatus)),'')
            when 'CONCEPT' then 0
            when 'IN VOORBEREIDING' then 1
            when 'ONDERHANDEN' then 2
            when 'AFGESLOTEN' then 3
            when '' then 0
            else null
           end case
    into @_ProjStatus;

    if @_ProjStatus is null then
      call Raise(20700, 'ProjectStatus'); //Ongeldige waarde: %1
    end if;

    if (@_ProjSoort = 3 /*Proef*/) and (@_ProjStatus <> 0) then
      call Raise(20780, _U('Toevoegen'), _U('De status van een proefproject mag niet worden gewijzigd!')); // <Actie> niet mogelijk: <Reden>.
    end if;

    //Status prijsopgave
    //Geldige waardes [0=Concept 1=Vastgesteld 2=Herzien] ProjOfferteStatus
    select case isnull(trim(upper(@StatusPrijsOpgave)),'')
            when 'CONCEPT' then 0
            when 'VASTGESTELD' then 1
            when 'HERZIEN' then 2
            when '' then 0
            else null
           end case
    into @_ProjOfferteStatus;

    if @_ProjOfferteStatus is null then
      call Raise(20700, 'StatusPrijsOpgave'); //Ongeldige waarde: %1
    end if;

    //BegrotingsStatus
    //Geldige waardes [0=Concept 1=Vastgesteld 2=Herzien]
    select case isnull(trim(upper(@BegrotingsStatus)),'')
            when 'CONCEPT' then 0
            when 'VASTGESTELD' then 1
            when 'HERZIEN' then 2
            when '' then 0
            else null
           end case
    into @_ProjBegrotingsStatus;

    if @_ProjBegrotingsStatus is null then
      call Raise(20700, 'BegrotingsStatus'); //Ongeldige waarde: %1
    end if;

    //Default BTW-code
    if (@DefaultBTWcode is not null) and (not exists(select BTWCode from tabBTW where BTWCode = @DefaultBTWcode)) then
      call Raise(20720, 'DefaultBTWcode') ; // %1 niet gevonden!
    end if;

    //BetalingsConditie
    if (@BetalingsConditie is not null) then
      set @_ProjBtcNummer = (select BtcNummer from tabBetalingsConditie where BtcNummer = @BetalingsConditie );

      if @_ProjBtcNummer is null then
        call Raise(20700, 'Betalingsconditie'); // Ongeldige waarde: %1
      end if;
    end if;

    //Leveringsconditie
    if (@LeveringsConditie is not null) then
      set @_ProjLvcNummer = (select LvcNummer from tabLeveringsConditie where LvcNummer = @LeveringsConditie );

      if @_ProjLvcNummer is null then
        call Raise(20700, 'Leveringsconditie'); // Ongeldige waarde: %1
      end if;
    end if;

    //Inkoopcombinatie
    set @_ProjIsInkoopCombinatie = isnull(@IsInkoopcombinatie,@_qcNEE);

    if (@_ProjIsInkoopCombinatie = @_qcJA) then
      // Controle: Als er sprake is van een Inkoopcombinatie, dan is DebiteurNummerFactuur verplicht
      select NawFilNawGid
      into @_ProjnawGidFactuur
      from tabNawFile
      where NawFilFonId = @_NAWBestandDebiteur
        and NawFilNummer = isnull(@DebiteurNummerFactuur,'');

      if @_ProjnawGidFactuur is null then
        call Raise(20700,'DebiteurNummerFactuur');   // (20700) Ongeldige waarde: %1!
      end if;

      // Controle: Als er sprake is van een Inkoopcombinatie, dan is DebiteurNummerOmzet verplicht
      select NawFilNawGid
      into @_ProjNawGidOmzet
      from tabNawFile
      where NawFilFonId = @_NAWBestandDebiteur
        and NawFilNummer = isnull(@DebiteurNummerOmzet,'');

      if @_ProjNawGidOmzet is null then
        call Raise(20700,'DebiteurNummerOmzet');   // (20700) Ongeldige waarde: %1!
      end if;

      // Controle: Als er sprake is van een Inkoopcombinatie, dan is DebiteurNummerPrijsafspraken verplicht
      select NawFilNawGid
      into @_ProjNawGidPrijzen
      from tabNawFile
      where NawFilFonId = @_NAWBestandDebiteur
        and NawFilNummer = isnull(@DebiteurnummerPrijsafspraken,'');

      if @_ProjNawGidPrijzen is null then
        call Raise(20700,'DebiteurNummerPrijsafspraken');   // (20700) Ongeldige waarde: %1!
      end if;
    else
      set @_ProjIsInkoopCombinatie = @_qcNEE;
      set @_ProjnawGidFactuur = null;
      set @_ProjnawGidOmzet = null;
      set @_ProjnawGidPrijzen = null;
    end if;

    //Contactpersoon
    if (@ContactPersoonnummer is not null) then
    begin
      declare @_CPNawGid integer = @_ProjNawGid;

      if (@_ProjIsInkoopCombinatie = @_qcJA) and (@_ProjnawGidFactuur is not null) then
        set @_CPNawGid = @_ProjnawGidFactuur;
      end if;

      select RelGid into @_ProjDebContactPersRelGid
      from tabRelatie
      where RelNummer = @ContactPersoonnummer
        and RelNawGid = @_CPNawGid;

      if @_ProjDebContactPersRelGid is null then
        call Raise(20720, 'ContactPersoonnummer') ; // %1 niet gevonden!
      end if;
    end;
    end if;

    //Boolean velden bekijken
    if (isNull(@VeelvoudVanFactuureenheidVerplicht,@_qcNEE) not in (@_qcJA, @_qcNEE)) then
      call Raise(20700, 'VeelvoudVanFactuureenheidVerplicht'); //Ongeldige waarde: %1
    end if;
    if (isNull(@KostprijsMedewerkerPrevaleert,@_qcNEE) not in (@_qcJA, @_qcNEE)) then
      call Raise(20700, 'KostprijsMedewerkerPrevaleert'); //Ongeldige waarde: %1
    end if;
    if (isNull(@VerkoopprijsMedewerkerPrevaleert,@_qcNEE) not in (@_qcJA, @_qcNEE)) then
      call Raise(20700, 'VerkoopprijsMedewerkerPrevaleert'); //Ongeldige waarde: %1
    end if;
    if (isNull(@ProjectMutatiesBoekenAlsDeclarabel,@_qcNEE) not in (@_qcJA, @_qcNEE)) then
      call Raise(20700, 'ProjectMutatiesBoekenAlsDeclarabel'); //Ongeldige waarde: %1
    end if;


    //En nu toevoegen
    insert into tabProject (
      ProjCode,
      ProjOmschr,
      ProjSoort,
      ProjProjLeiderRelGid,
      ProjProjGrpGid,
      ProjNawGid,
      ProjLndGid,
      ProjUrenHeleFactuurEenheden,
      ProjVerkPrijsMedewPrevaleert,
      ProjKostPrijsMedewPrevaleert,
      ProjProjMutBoekenAlsDeclarabel,
      ProjStatus,
      ProjOfferteStatus,
      ProjBegrotingsStatus,
      ProjOpm,
      ProjBTWCode,
      ProjDebContactPersRelGid,
      ProjBtcNummer,
      ProjLvcNummer,
      ProjIsInkoopCombinatie,
      ProjnawGidFactuur,
      ProjNawGidOmzet,
      ProjNawGidPrijzen
    )
    values (
      @_ProjCode,
      @ProjectOmschrijving,
      @_ProjSoort,
      @_ProjProjLeiderRelGid,
      @_ProjProjGrpGid,
      @_ProjNawGid,
      @_ProjLndGid,
      @VeelvoudVanFactuureenheidVerplicht,
      @VerkoopprijsMedewerkerPrevaleert,
      @KostprijsMedewerkerPrevaleert,
      @ProjectMutatiesBoekenAlsDeclarabel,
      @_ProjStatus,
      @_ProjOfferteStatus,
      @_ProjBegrotingsStatus,
      trim(@Opmerking),
      @DefaultBTWcode,
      @_ProjDebContactPersRelGid,
      @_ProjBtcNummer,
      @_ProjLvcNummer,
      @_ProjIsInkoopCombinatie,
      @_ProjnawGidFactuur,
      @_ProjNawGidOmzet,
      @_ProjNawGidPrijzen
    );

    set @_ProjGid = @@Identity;

    // Aangemaakte Project locken
    call WebSvcHulpProc_ProjectExclusiefLocken(@_ProjGid, 'KingWebService', @@Spid, @@LoginTime);

    //PbGid ophalen
    select PbGid into @_PbGid
    from tabProjectBoom
    where PbProjGid = @_ProjGid
      and pblevel = 1;

    //Project permissie
    call WebSvcHulpProc_ProjectPermissie_Toevoegen(@_ProjGid, isNull(@StandaardwaardeGebruikstoestemming,1));

    //Factuurverdichting
    call WebSvcHulpProc_ProjectFactuurVerdichting_Toevoegen(
      @_PbGid,
      //Detaillering van Activiteiten op facturen
      @DetailleringActActiviteitSpecificeren,
      @DetailleringActOpbrengstGroepSpecificeren,
      @DetailleringActMedewerkerSpecificeren,
      //Detaillering van artikelen op facturen
      @DetailleringArtArtikelSpecificeren,
      @DetailleringArtOpbrengstGroepSpecificeren,
      //Detaillering van overige kosten op facturen
      @DetailleringOverigOverigekostenSpecificeren,
      @DetailleringOverigOpbrengstGroepSpecificeren,
      //Per factuurregel projectmutaties afdrukken
      null,
      @AfdrukkenAlleActiviteitsMutaties,
      null,
      @AfdrukkenAlleArtikelMutaties,
      null,
      @AfdrukkenAlleOverigeKostenMutaties,
      @OmschrijvingOpFactuur);

      /* Default waarden van vrije rubrieken vullen */
      call VrijeRubriekenVulDefaults('PRJ', 0, 0, @_ProjGid);
  end;

  // Ophalen resultaat
  select @_ProjGid as ProjGid;

  //set @@ErrorTextProcedure = 'WebSvcProc_Project_Toevoegen > @ProjectCode = ' + @_ProjCode;
  //call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure WebSvcProc_Project_VrijeRubriek_Wijzigen(
  in @ProjectCode nchar(10),
  in @RubriekOmschrijving nchar(40),
  in @RubriekInhoud nchar(255)
)
begin
  declare @_ProjGid integer;
  declare @_ProjStatus smallint;

  //set @@ErrorTextProcedure =  'WebSvcProc_Project_VrijeRubriek_Wijzigen > @ProjectCode = ' + String(@ProjectCode) + ' @RubriekOmschrijving = ' + String(@RubriekOmschrijving);
  //call TraceBegin(@@ErrorTextProcedure);

  // Module: is er geen Projecten-basis actief , dan kan je geen project aanmaken.
  if IsModuleActive('pr') = 0 then
    call Raise(20790, _U('Optie Projecten-basis')); //(20790) '%1!' niet geactiveerd!
  end if;

  select ProjGid, ProjStatus
  into @_ProjGid, @_ProjStatus
  from tabProject
  where ProjCode = @ProjectCode;

  if (@_ProjGid is null) then
    call Raise(20720,  'ProjectCode'); //(20720 %1 niet gevonden!
  end if;

  if (@_ProjStatus = 3 /*Afgesloten*/) then
    call Raise(20780, _U('Vrije rubriek wijzigen'), _U('De status van het project is ''afgesloten''!')); // <Actie> niet mogelijk: <Reden>.
  end if;


  begin atomic
    //Project locken
    call WebSvcHulpProc_ProjectExclusiefLocken(@_ProjGid, 'KingWebService', @@Spid, @@LoginTime);

    call VrInsertOrReplaceValue('PRJ', 0, 0, @_ProjGid, @RubriekOmschrijving, @RubriekInhoud);
  end; // atomic

  //set @@ErrorTextProcedure = 'WebSvcProc_Project_VrijeRubriek_Wijzigen';
  //call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcHulpProc_Recept_Controleer_ReceptuurKop(
  in    @Mode                                    smallint, // 0 = Toevoegen, 1 = Wijzigen
  in    @ReceptCode                              nchar(20),
  in    @Zoekcode                                nchar(20),
  in    @ReceptOms                               nchar(40),
  in    @ReceptSoort                             nchar(13), // SAMENSTELLING of PRODUCTIE
  in    @MinimumAantal                           numeric(15,0),
  in    @MaximumAantal                           numeric(15,0),
  in    @DefaultAantal                           numeric(15,0),
  in    @RekeningNrResultaat                     nchar(28),
  in    @Orderstatus                             nchar(13),
  in    @NuAfTeBoeken                            nchar(16),
  in    @NuOpTeBoeken                            nchar(16),
  in    @GeblokkeerdProductie                    smallint,
  in    @Document                                nchar(255),
  in    @Opmerking                               long nvarchar,
  in    @PrijsPerProductieEenh                   nchar(23),
  in    @AantalPrijsProductieEenheid             numeric(15,0),
  in    @AparteProductieOrdersPerRecept          smallint,
  in    @ProductieGrootte                        numeric(15,3) default 1,
  inout @_RcptGid                                integer,
  inout @_RcptCode                               nchar(20),
  inout @_RcptZoekcode                           nchar(20),
  inout @_RcptOmschrijving                       nchar(40),
  inout @_RcptSoort                              smallint,
  inout @_RcptBatchMinimum                       numeric(15,3),
  inout @_RcptBatchMaximum                       numeric(15,3),
  inout @_RcptBatchDefault                       numeric(15,3),
  inout @_RcptRksGid                             integer,
  inout @_RcptDefaultProductieOrderStatus        smallint,
  inout @_RcptVulAantalDezeVerwerkingComponent   smallint,
  inout @_RcptVulAantalDezeVerwerkingEindproduct smallint,
  inout @_RcptGeblokkeerd                        smallint,
  inout @_RcptDocument                           nchar(255),
  inout @_RcptOpmerking                          long nvarchar,
  inout @_RcptPrijsBatchGrootte                  smallint,
  inout @_RcptPrijsBatchAantal                   numeric(15,3),
  inout @_RcptAparteProductieOrdersPerRecept     smallint,
  inout @_RcptBatchProductieGrootte              numeric(15,3)
)
begin
  // Fixed enumerators
  declare _TOEVOEGEN smallint = 0;
  declare _WIJZIGEN  smallint = 1;


  // Modulecontrole
  if IsModuleActive('rr') = 0 then   // Module t.b.v. productie
    call Raise(20790,_U('Optie Productie')  ); // (20790) '%1!' niet geactiveerd!
  end if;       //Einde if IsModuleActive('rr') <> 0


  //Controle: @ReceptCode is verplicht
  if isnull(@ReceptCode,'') = '' then
    call Raise(20700,'ReceptCode');   // (20700) Ongeldige waarde: %1!
  end if;


  // --------------------------------
  // --- EXPLICIET VOOR TOEVOEGEN ---
  // --------------------------------
  if @mode = _TOEVOEGEN then
    // Controle: @ReceptCode mag nog niet een bestand recept zijn
    select RcptGid into @_RcptGid from tabReceptuur where RcptCode = @ReceptCode;
    if @_RcptGid is not null then
      call Raise(20721,'ReceptCode'); //(20721) %1! komt al voor!
    end if;
  end if;

  set @_RcptCode         = @ReceptCode;

  // Tekstvelden die niet hoeven te worden gecontroleerd
  set @_RcptZoekcode     = isnull(@Zoekcode,  @_RcptZoekcode,     '');
  set @_RcptOmschrijving = isnull(@ReceptOms, @_RcptOmschrijving, '');
  set @_RcptDocument     = isnull(@Document,  @_RcptDocument,     '');
  set @_RcptOpmerking    = isnull(@Opmerking, @_RcptOpmerking,    '');


  // -------------------
  // --- RECEPTSOORT ---
  // -------------------
  // Controle: @ReceptSoort moet een geldige waarde bevatten, indien meegegeven
  if isnull(@ReceptSoort,'') <> '' or @Mode = _TOEVOEGEN then
    case @ReceptSoort
      when 'SAMENSTELLING' then set @_RcptSoort = 0;
      when 'PRODUCTIE'     then set @_RcptSoort = 1;
    else
      call Raise(20700,'ReceptSoort');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  // Controle: Recept mag niet zijn gekoppeld aan een artikel (Eindproduct binnen een Samenstelling),
  //           indien 'SAMENSTELLING' wordt gewijzigd naar 'PRODUCTIE'
  if exists (select first 1 from tabArtikel where ArtSamengesteldRcptGid = @_RcptGid) and (@_RcptSoort = 1 /*Productie*/) then
    call Raise(20780,_U('%1! wijzigen is', 'ReceptSoort'),_U('Recept is gekoppeld aan een artikel (samenstelling)'));   // (20780) %1! niet mogelijk: %2!
  end if;

  //Controle: Indien ReceptSoort wordt gewijzigd van 'PRODUCTIE' naar 'SAMENSTELLING' dan mag maximaal 1 Eindproduct aanwezig zijn binnen het recept.
  if (isnull((select count(*) from tabReceptuurEindproduct where RcpeRcptGid = @_RcptGid ),0) > 1) and (@_RcptSoort = 0) then
    call Raise(20780,__U('%1! wijzigen is', 'ReceptSoort'),_U('Recept heeft meerdere eindproducten (maximaal 1 toegestaan)'));   // (20780) %1! niet mogelijk: %2!
  end if;

  //Controle: Indien ReceptSoort wordt gewijzigd van 'PRODUCTIE' naar 'SAMENSTELLING',
  //          dan is alleen in alle Componenten @Verbruik = 'PER_RECEPT' toegestaan.
  if (isnull((select count(*) from tabReceptuurComponent where RcpcRcptGid = @_RcptGid and RcpcVerbruik <> 0),0) > 0) then
    call Raise(20780,_U('%1! wijzigen is', 'ReceptSoort'),_U('Recept heeft componenten met %1! ongelijk aan %2!', 'Verbruik', '''PER_RECEPT'''));   // (20780) %1! niet mogelijk: %2!
  end if;

  //Controle: Indien ReceptSoort wordt gewijzigd van 'PRODUCTIE' naar 'SAMENSTELLING',
  //          dan is alleen in het Eindproduct @ProductieAantal = 1 toegestaan.
  if (isnull((select count(*) from tabReceptuurEindproduct where RcpeRcptGid = @_RcptGid and RcpeAantal <> 1),0) > 0) then
    call Raise(20780,_U('%1! wijzigen is', 'ReceptSoort'),_U('Recept heeft een eindproduct met productie-aantal ongelijk aan 1'));   // (20780) %1! niet mogelijk: %2!
  end if;

  // -----------------------------------
  // --- APARTE PRODUCTIE PER RECEPT ---
  // -----------------------------------
  // Controle: @AparteProductieOrdersPerRecept moet een geldige waarde bevatten, indien meegegeven
  if @AparteProductieOrdersPerRecept is not null then
    if @AparteProductieOrdersPerRecept in (0,1) then
      set @_RcptAparteProductieOrdersPerRecept = @AparteProductieOrdersPerRecept;
    else
      call Raise(20700,'AparteProductieOrdersPerRecept');   // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  // -----------------
  // --- AANTALLEN ---
  // -----------------
  //$region - Minimum aantal
  // Controle: @MinimumAantal niet meegegeven of kleiner dan/gelijk aan 0, dan Defaultwaarde is 1
  if @MinimumAantal is not null then
    if @MinimumAantal <= 0 then
      if @Mode = _WIJZIGEN then // Alleen melden bij wijzigen, want bij toevoegen blijft de default staan
        call Raise(20700,'MinimumAantal');   // (20700) Ongeldige waarde: %1!
      end if;
    else
      set @_RcptBatchMinimum = @MinimumAantal;
    end if;
  end if;

  //$region - Maximum aantal
  // Controle: @MaximumAantal niet meegegeven of kleiner dan 0, dan Defaultwaarde is 0 (Geen maximum)
  if @MaximumAantal is not null then
    if @MaximumAantal < 0 then
      if @Mode = _WIJZIGEN then
        call Raise(20700,'MaximumAantal');   // (20700) Ongeldige waarde: %1!
      end if;
    else
      set @_RcptBatchMaximum = @MaximumAantal;
    end if;
  end if;

  //$region - Aantal af te boeken
  // Controle: Indien @NuAfTeBoeken niet meegegeven, dan Default Vaste gegevens Receptuur, anders moet geldige waarde worden meegegeven
  if isnull(@NuAfTeBoeken,'') <> '' and @_RcptSoort = 1 /*PRODUCTIE*/ then
    case @NuAfTeBoeken
      when 'NIET_AANPASSEN'   then set @_RcptVulAantalDezeVerwerkingComponent = 0;
      when 'NOG_AF_TE_BOEKEN' then set @_RcptVulAantalDezeVerwerkingComponent = 1;
    else
      call Raise(20700,'NuAfTeBoeken');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  // Indien ReceptSoort = SAMENSTELLING, dan altijd NOG_AF_TE_BOEKEN (Default waarde MetaData)
  if @_RcptSoort = 0 /*Samenstelling*/ then
    set @_RcptVulAantalDezeVerwerkingComponent = 1   // NOG_AF_TE_BOEKEN
  end if;

  //$region - Aantal op te boeken
  // Controle: Indien @NuOpTeBoeken niet meegegeven, dan Default Vaste gegevens Receptuur, anders moet geldige waarde worden meegegeven
  if isnull(@NuOpTeBoeken,'') <> '' and @_RcptSoort = 1 /*PRODUCTIE*/ then
    case @NuOpTeBoeken
      when 'NIET_AANPASSEN'   then set @_RcptVulAantalDezeVerwerkingEindProduct = 0;
      when 'NOG_OP_TE_BOEKEN' then set @_RcptVulAantalDezeVerwerkingEindProduct = 1;
    else
      call Raise(20700,'NuOpTeBoeken');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  // Indien ReceptSoort = SAMENSTELLING, dan altijd NOG_OP_TE_BOEKEN (Default waarde MetaData)
  if @_RcptSoort = 0 /*Samenstelling*/ then
    set @_RcptVulAantalDezeVerwerkingEindProduct = 1   // NOG_OP_TE_BOEKEN
  end if;

  //$region - Batchgrootte
  // Controle: Indien @PrijsPerProductieEenh niet meegegeven, dan Default DEFAULT_AANTAL (0), anders moet geldige waarde worden meegegeven
  if isnull(@PrijsPerProductieEenh,'') <> '' then
    case @PrijsPerProductieEenh
      when 'DEFAULT_AANTAL'          then set @_RcptPrijsBatchGrootte = 0;
      when 'MINIMUM_AANTAL'          then set @_RcptPrijsBatchGrootte = 1;
      when 'MAXIMUM_AANTAL'          then set @_RcptPrijsBatchGrootte = 2;
      when 'ZELF_OP_TE_GEVEN_AANTAL' then set @_RcptPrijsBatchGrootte = 3;
    else
      call Raise(20700,'PrijsPerProductieEenh');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  // --------------------------------------
  // --- AANTALLEN: COMBINATIECONTROLES ---
  // --------------------------------------
  //$region COMBINATIECONTROLES
  // --- COMBINATIE MIN/MAX/DEFAULT AANTALLEN ---

  // Controle: Indien @_RcptAparteProductieOrdersPerRecept = 1, dan moet @_RcptBatchMinimum altijd de waarde 1 hebben
  if @_RcptAparteProductieOrdersPerRecept = 1 and @_RcptBatchMinimum <> 1 then
    call Raise(20701,_U('%1! ongelijk aan 1 is niet toegestaan als %2! gelijk aan 1 is', 'MinimumAantal', 'RcptAparteProductieOrdersPerRecept'));  // (20701) Ongeldige combinatie: %1!
  end if;

  // Controle: @_RcptPrijsBatchGrootte = MAXIMUM_AANTAL (2) is alleen toegestaan als @_RcptBatchMaximum groter is dan 0
  if (@_RcptPrijsBatchGrootte = 2 /*MaximumAantal*/ ) and (@_RcptBatchMaximum = 0) then
    call Raise(20701,_U('%1! is alleen toegestaan als %2! groter is dan 0', 'MaximumAantal', 'MaximumAantal'));  // (20701) Ongeldige combinatie: %1!
  end if;

  // Controle: @AantalPrijsProductieEenheid is verplicht, indien @_RcptPrijsBatchGrootte = ZELF_OP_TE_GEVEN_AANTAL (3)
  if (isnull(@AantalPrijsProductieEenheid,0) <= 0) and (@_RcptPrijsBatchGrootte = 3 /*Zelf op te geven aantal*/) then
    call Raise(20701,_U('%1! verplicht bij %2!', 'AantalPrijsProductieEenheid', 'ZELF_OP_TE_GEVEN_AANTAL'));   // (20701) Ongeldige combinatie: %1!
  end if;

  // Controle: MaximumAantal (groter dan 0) mag niet kleiner zijn dan MinimumAantal
  if (@_RcptBatchMaximum <> 0) and (@_RcptBatchMaximum < @_RcptBatchMinimum) then
    call Raise(20701,_U('%1! (groter dan 0) moet groter dan of gelijk aan %2! zijn!', 'MaximumAantal', 'MinimumAantal'));   // (20701) Ongeldige combinatie: %1!
  end if;


  // Controle: @DefaultAantal niet meegegeven of kleiner dan/gelijk aan 0, dan Defaultwaarde is 1
  if @DefaultAantal is not null then
    if @DefaultAantal <= 0 then
      if @Mode = _WIJZIGEN then
        call Raise(20700,'DefaultAantal');   // (20700) Ongeldige waarde: %1!
      end if;
    else
      set @_RcptBatchDefault = @DefaultAantal;
    end if;
  end if;


  // Controle: DefaultAantal mag niet kleiner zijn dan MinimumAantal
  if @_RcptBatchDefault < @_RcptBatchMinimum then
    call Raise(20701,_U('%1! moet groter dan of gelijk aan %2! zijn!', 'DefaultAantal', 'MinimumAantal'));   // (20701) Ongeldige combinatie: %1!
  end if;
  // Controle: DefaultAantal mag niet groter zijn dan MaximumAantal
  if (@_RcptBatchMaximum <> 0) and (@_RcptBatchDefault > @_RcptBatchMaximum) then
    call Raise(20701,_U('%1! moet kleiner dan of gelijk aan %2! zijn!', 'DefaultAantal', 'MaximumAantal'));    // (20701) Ongeldige combinatie: %1!
  end if;

  // -----------------------------------
  // --- GROOTBOEKREKENING RESULTAAT ---
  // -----------------------------------
  // Controle: Indien @RekeningNrResultaat niet meegegeven, dan Default Vaste gegevens Receptuur, anders moet geldige waarde worden meegegeven
  if isnull(@RekeningNrResultaat,'') <> '' then
    set @_RcptRksGid = null;
    select RksGid into @_RcptRksGid from tabRekeningSchema where (RksInvoer = @RekeningNrResultaat) and (DefaultSoort not in(6,7));   // Geen Debiteuren (6) of Crediteuren (7)
  end if;

  if @_RcptRksGid is null then
    call Raise(20720, 'RekeningNrResultaat'); //(20720) %1! niet gevonden!
  end if;


  // --------------
  // --- STATUS ---
  // --------------
  // Controle: Indien @Orderstatus niet meegegeven, dan Default Vaste gegevens Receptuur, anders moet geldige waarde worden meegegeven
  if isnull(@Orderstatus,'') <> '' then
    case @Orderstatus
      when 'NIEUW'         then set @_RcptDefaultProductieOrderStatus = 0;
      when 'IN_TE_PLANNEN' then set @_RcptDefaultProductieOrderStatus = 1;
      when 'INGEPLAND'     then set @_RcptDefaultProductieOrderStatus = 2;
      when 'ONDERHANDEN'   then set @_RcptDefaultProductieOrderStatus = 3;
    else
      call Raise(20700,'Orderstatus!');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  // Controle: @GeblokkeerdProductie moet een geldige waarde bevatten, indien meegegeven
  if @GeblokkeerdProductie is not null then
    if @GeblokkeerdProductie not in (0,1) then
      call Raise(20700,'GeblokkeerdProductie');   // (20700) Ongeldige waarde: %1!
    end if;
    set @_RcptGeblokkeerd = @GeblokkeerdProductie;
  end if;
  if @_RcptGeblokkeerd is null then
    call Raise(20700,'GeblokkeerdProductie');   // (20700) Ongeldige waarde: %1!
  end if;

  // Controle: @ProductieGrootte moet 1 of groter zijn
  if (@ProductieGrootte is null) or (@ProductieGrootte < 1) then
    call Raise(20700,'ProductieGrootte');   // (20700) Ongeldige waarde: %1!
  else
    set @_RcptBatchProductieGrootte = @ProductieGrootte;

    if @_RcptBatchMinimum % @_RcptBatchProductieGrootte <> 0 then
       call Raise(20700, _U('%1! moet een veelvoud van %2! zijn!', 'MinimumAantal', 'ProductieGrootte'));
    end if;

    if @_RcptBatchMaximum % @_RcptBatchProductieGrootte <> 0 then
       call Raise(20700, _U('%1! moet een veelvoud van %2! zijn!', 'MaximumAantal', 'ProductieGrootte'));
    end if;

    if @_RcptBatchDefault % @_RcptBatchProductieGrootte <> 0 then
       call Raise(20700, _U('%1! moet een veelvoud van %2! zijn!', 'DefaultAantal', 'ProductieGrootte'));
    end if;
  end if;

  // -----------------------------
  // --- BATCHPRIJS PER AANTAL ---
  // -----------------------------
  // Op basis van @_RcptPrijsBatchGrootte het juiste aantal overnemen
  case @_RcptPrijsBatchGrootte
    when 0 /*Default aantal*/          then set @_RcptPrijsBatchAantal = @_RcptBatchDefault;
    when 1 /*Minimum aantal*/          then set @_RcptPrijsBatchAantal = @_RcptBatchMinimum;
    when 2 /*Maximum aantal*/          then set @_RcptPrijsBatchAantal = @_RcptBatchMaximum;
    when 3 /*Zelf op te geven aantal*/ then set @_RcptPrijsBatchAantal = @AantalPrijsProductieEenheid;
  end case;

  // Controle: De prijs per batch aantal mag niet 0 zijn
  if @_RcptPrijsBatchAantal = 0 then
    call Raise(20700,_U('Prijs per aantal moet groter dan nul zijn! Pas %1! of de batch-aantallen aan.', 'PrijsPerProductieEenh'));   // (20700) Ongeldige waarde: %1!
  end if;
end;



create or replace procedure WebSvcProc_Recept_Component_ToevoegenWijzigen
(  in @ReceptCode     nchar(20),
   in @RegelNummer    integer,
   in @RegelSoort     nchar(5),
   in @ArtikelNummer  nchar(20),
   in @ArtikelOms     long nvarchar,
   in @Aantal         numeric(15,3),
   in @Verbruik       nchar(15),
   in @AantalRecepten numeric(15,0)
)
result(RegelNummer integer)

begin
  // Fixed enumerators
  declare @Mode smallint;
  declare _TOEVOEGEN smallint = 0;
  declare _WIJZIGEN  smallint = 1;

  declare @_RcpcRegelNr         integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Component_ToevoegenWijzigen > ';
  // call TraceBegin('WebSvcProc_Recept_Component_ToevoegenWijzigen > @ReceptCode = ' + @ReceptCode + ', @RegelNummer = ' + @RegelNummer);

  // Module controle
  if IsModuleActive('rr') = 0 then             // Module t.b.v. productie
    call Raise(20790,_U('Optie Productie')  ); // (20790) '%1!' niet geactiveerd!
  end if;

  begin atomic
    declare @_RcptGid             integer;
    declare @_RcptSoort           smallint;
    declare @_RcpcGid             integer;
    declare @_RcpcRegelsoort      integer;
    declare @_RcpcArtGid          integer;
    declare @_RcpcOmschrijving    long nvarchar;
    declare @_RcpcAantal          numeric(15,3);
    declare @_RcpcVerbruikAantal  numeric(15,3);
    declare @_RcpcVerbruik        smallint;
    declare @_ArtAantDecAantallen smallint;
    declare @_ContrAantal         numeric(15,3);
    declare @_ArtOms              long nvarchar;

    // Opzoeken te wijzigen recept
    select RcptGid into @_RcptGid
    from   tabReceptuur
    where  RcptCode = @ReceptCode;
    if @_RcptGid is null then
      call Raise(20780,_U('Recept wijzigen is'),_U('Ongeldige of geen %1! meegegeven', 'ReceptCode'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Gevonden recept locken
    begin
      declare @LockResult integer;
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid, @LockResult, 0);
      if @LockResult <> 0 /*Lock gelukt*/ then
        call Raise(20741,_U('Recept'));   // (20741) %1! is in gebruik!
      end if;
    end;

    // Ophalen van de benodigde Receptuur gegevens nadat recept succesvol is gelocked
    select RcptGid,
           RcptSoort
    into   @_RcptGid,
           @_RcptSoort
    from   tabReceptuur
    where  RcptGid = @_RcptGid;

    // ---------------------------------------------------------
    // --- KEUZE TOEVOEGEN OF WIJZIGEN (o.b.v. @RegelNummer) ---
    // ---------------------------------------------------------
    if @RegelNummer is null then
      // --- Toevoegen
      set @Mode = _TOEVOEGEN;

      set @_RcpcRegelNr = 1;
      // Als er geen regels zijn, dan blijft @_RcpcRegelNr zoals die al was, dus op 1
      select first (RcpcRegelNr + 1) into @_RcpcRegelNr from tabReceptuurComponent where RcpcRcptGid = @_RcptGid order by RcpcRegelNr desc;
      // Initialiseer variabelen, o.a. met default waarde
      set @_RcpcArtGid         = null;
      set @_RcpcOmschrijving   = '';
      set @_RcpcAantal         = 0;
      set @_RcpcVerbruik       = 0 /*Per recept*/;
      set @_RcpcVerbruikAantal = 0;

    else
      // --- Wijzigen
      set @Mode = _WIJZIGEN;

      // Ophalen gegevens van bestaande compoment
      select    RcpcGid,
                RcpcRegelNr,
                RcpcRegelsoort,
                RcpcArtGid,
                RcpcOmschrijving,
                RcpcAantal,
                RcpcVerbruik,
                RcpcVerbruikAantal
      into      @_RcpcGid,
                @_RcpcRegelNr,
                @_RcpcRegelsoort,
                @_RcpcArtGid,
                @_RcpcOmschrijving,
                @_RcpcAantal,
                @_RcpcVerbruik,
                @_RcpcVerbruikAantal
      from      tabReceptuurComponent
      where     RcpcRcptGid = @_RcptGid and RcpcRegelNr = @RegelNummer;
      // Controle: @RegelNummer moet wel een bestaande regelnummer zijn binnen het recept
      if @_RcpcGid is null then
        call Raise(20700,'RegelNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: @RegelSoort meegeven is verplicht tijdens toevoegen van nieuw component en niet toegestaan tijdens wijzigen van bestaand component
    if isnull(@RegelSoort,'') <> '' then
      if @Mode = _TOEVOEGEN then
        case @RegelSoort   // Alleen tijdens toevoegen van nieuw component
          when 'ART'   then set @_RcpcRegelsoort = 2;
          when 'TAR'   then set @_RcpcRegelsoort = 1;
          when 'TEKST' then set @_RcpcRegelsoort = 0;
        end case;
      else                 // Mag niet worden meegegeven tijdens het wijzigen van een component
        call Raise(20780,_U('Component wijzigen is'),_U('%1! wijzigen is niet toegestaan', 'RegelSoort'));   // (20780) %1! niet mogelijk: %2!
      end if;
    end if;

    // Controle: Indien @RegelNummer niet is meegegeven, dan is @RegelSoort verplicht (Toevoegen nieuw component),
    if @_RcpcRegelsoort is null then
          call Raise(20700,'RegelSoort');   // (20700) Ongeldige waarde: %1!
    end if;

    // Controle: Combinatie van @_RcpcRegelsoort = TAR (1) en @_RcptSoort = SAMENSTELLING (0) is niet toegestaan
    if (@_RcpcRegelsoort = 1) and (@_RcptSoort = 0) then
      call Raise(20701,_U('%1! %2! is niet toegestaan in combinatie met %3! %4!.', 'RegelSoort', '''TAR''', 'ReceptSoort', '''Samenstelling'''));   // (20701) Ongeldige combinatie: %1!
    end if;

    // ----------------------------------------
    // --- Controles voor artikel en tarief ---
    // ----------------------------------------
    if @_RcpcRegelsoort in (1 /*Tarief*/, 2 /*Artikel*/) then

      // --- - Controle: Meegegeven artikel moet bestaan
      if (isnull(@ArtikelNummer,'') <> '')  then
          set    @_RcpcArtGid = null;
          select ArtGid
          into   @_RcpcArtGid
          from   tabArtikel
          where  ArtCode = @ArtikelNummer and ArtSoort = @_RcpcRegelsoort;
          // Controle: Indien meegegeven, dan moet het een bestaand Artikel (2) of Tarief (1) zijn
          if @_RcpcArtGid is null then
            call Raise(20700,'ArtikelNummer');   // (20700) Ongeldige waarde: %1!
          end if;
      end if;

      // --- - Ophalen benodigde artikelgegevens
      select ArtAantDecAantallen, ArtOms
      into   @_ArtAantDecAantallen, @_ArtOms
      from   tabArtikel
      where  ArtGid = @_RcpcArtGid;

      // --- - Controle: Indien @ArtikelOms niet is meegegeven, maar @ArtikelNummer wel, dan de default artikelomschrijving ophalen
      if @ArtikelOms is not null then
        set @_RcpcOmschrijving = @ArtikelOms;
      else
        if @ArtikelNummer is not null then   // @Artikelnummer verplicht tijdens toevoegen, optioneel tijdens wijzigen
          // Alleen default omschrijving ophalen tijdens toevoegen van nieuw component of na meegeven van @Artikelnummer tijdens wijzigen
          set @_RcpcOmschrijving = isnull((select ArtTekst
                                           from   tabArtikelTeksten
                                           where  ArtTekstArtGid = @_RcpcArtGid
                                           and    ArtTaalGid = (select DefaultTaalGid from tabVasteGegevens)),'');  // DefaultTaalGid is standaard TaalGid van de administratie
          if @_RcpcOmschrijving = '' then
            set @_RcpcOmschrijving = @_ArtOms;
          end if;
        end if;
      end if;

      // --- - Controle: @Aantal
      // --- -- Controle: @Aantal moet groter dan 0 zijn
      if isnull(@Aantal,0) <= 0 then      // Aantal moet groter dan 0 zijn
        if @Mode = _TOEVOEGEN then
          call Raise(20700,'Aantal');    // (20700) Ongeldige waarde: %1!
        end if;
      else
      // --- -- Controle: Aantal decimalen van @Aantal moet passen in aantal decimalen van artikel
        set @_ContrAantal = truncnum(@Aantal,@_ArtAantDecAantallen);  // Controleren op meegegeven waarde in decimalen
        if (@_ContrAantal - @Aantal) <> 0 then
          call Raise(20780,_U('Component toevoegen is'),_U('Teveel decimalen in %1! meegegeven!', 'Aantal'));   // (20780) %1! niet mogelijk: %2!
        else
          set @_RcpcAantal = @Aantal;
        end if;
      end if;

      // --- - Controle: @Verbruik
      if isnull(@Verbruik,'') <> '' then
        case @Verbruik
          when 'PER_RECEPT'      then set @_RcpcVerbruik = 0;
          when 'PER_VERWERKING'  then set @_RcpcVerbruik = 1;
          when 'PER_XX_RECEPTEN' then set @_RcpcVerbruik = 2;
        else
          call Raise(20700,'Verbruik');   // (20700) Ongeldige waarde: %1!
        end case;
      end if;

    else
      // --- Regels voor tekstregels (0)
      // --- - Controle: Meegegeven Tekstblok moet bestaan
      if (isnull(@ArtikelNummer,'') <> '')  then
          set    @_RcpcArtGid = null;
          select ArtGid
          into   @_RcpcArtGid
          from   tabArtikel
          where  ArtCode = @ArtikelNummer and ArtSoort = @_RcpcRegelsoort;
          // Controle: Indien meegegeven, dan moet het een bestaand Tekstblok (0) zijn
          if @_RcpcArtGid is null then
            call Raise(20700,'ArtikelNummer');   // (20700) Ongeldige waarde: %1!
          end if;
      end if;

      // --- - Tekstomschrijving
      // Ophalen benodigde artikelgegevens
      select  ArtOms
      into   @_ArtOms
      from   tabArtikel
      where  ArtGid = @_RcpcArtGid;

      if @ArtikelOms is not null then
        set @_RcpcOmschrijving = @ArtikelOms;
      else
      // --- - Controle: Indien @ArtikelOms niet is meegegeven, maar @ArtikelNummer wel, dan de default tekstblok tekst ophalen
        if @ArtikelNummer is not null then
          set @_RcpcOmschrijving = isnull((select ArtTekst
                                           from   tabArtikelTeksten
                                           where  ArtTekstArtGid = @_RcpcArtGid
                                           and    ArtTaalGid = (select DefaultTaalGid from tabVasteGegevens)),'');  // DefaultTaalGid is standaard TaalGid van de administratie
          if @_RcpcOmschrijving = '' then
            set @_RcpcOmschrijving = @_ArtOms;
          end if;
        end if;
      end if;
    end if;

    // Controle: Indien @_RcptSoort = SAMENSTELLING (0), dan is alleen @_RcpcVerbruik = PER_RECEPT (0) toegestaan
    if (@_RcpcVerbruik <> 0 /*Per recept*/) and (@_RcptSoort = 0 /*Samenstelling*/) then
      call Raise(20701,_U('Alleen %1! %2! is toegestaan in combinatie met %3! %4!.', 'Verbruik', '''PER_RECEPT''', 'ReceptSoort', '''SAMENSTELLING'''));   // (20701) Ongeldige combinatie: %1!
    end if;

    // Controle: Indien @_RcpcVerbruik = PER_XX_RECEPTEN (2), dan moet @_RcpcVerbruikAantal groter zijn dan 0
    if @_RcpcVerbruik = 2 /*Per x recepten*/ then
      if isnull(@AantalRecepten,0) > 0 then
        set @_RcpcVerbruikAantal = @AantalRecepten;
      else
        call Raise(20700,'AantalRecepten');   // (20700) Ongeldige waarde: %1!
      end if;
    else
      // Indien @_RcpcVerbruik <> 2 dan is @_RcpcVerbruikAantal altijd NULL
      set @_RcpcVerbruikAantal = null;
    end if;

    // Gegevens bijwerken in de database
    if @Mode = _TOEVOEGEN then   // Nieuw componentregel toevoegen in de database
      insert into tabReceptuurComponent
      (  RcpcRcptGid,
         RcpcRegelNr,
         RcpcRegelsoort,
         RcpcArtGid,
         RcpcOmschrijving,
         RcpcAantal,
         RcpcVerbruik,
         RcpcVerbruikAantal
      )
      values
      (  @_RcptGid,
         @_RcpcRegelNr,
         @_RcpcRegelsoort,
         @_RcpcArtGid,
         @_RcpcOmschrijving,
         @_RcpcAantal,
         @_RcpcVerbruik,
         @_RcpcVerbruikAantal
      );
    else   // Gewijzigde componentregel opslaan in de database
      update tabReceptuurComponent
      set   RcpcArtGid         = @_RcpcArtGid,
            RcpcOmschrijving   = isnull(@ArtikelOms, @_RcpcOmschrijving),
            RcpcAantal         = @_RcpcAantal,
            RcpcVerbruik       = @_RcpcVerbruik,
            RcpcVerbruikAantal = @_RcpcVerbruikAantal
      where RcpcGid = @_RcpcGid;
    end if;
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid);
  end;   // atomic

  // Ophalen resultaat
  select @_RcpcRegelNr as RegelNummer;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Component_ToevoegenWijzigen';
  // call TraceEind(@@ErrorTextProcedure);
end;

create or replace procedure WebSvcProc_Recept_Component_Verwijderen
(  in @ReceptCode  nchar(20),
   in @RegelNummer integer
)

begin atomic
  declare @_RcptGid integer;
  declare @_RcpcGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Component_Verwijderen > ';
  // call TraceBegin('WebSvcProc_Recept_Component_Verwijderen > @ReceptCode = ' + @ReceptCode + ', @RegelNummer = ' + @RegelNummer);

  // --- Controle: Module
  if IsModuleActive('rr') = 0 then   // Module t.b.v. productie
    call Raise(20790,_U('Optie Productie'));   // (20790) '%1!' niet geactiveerd!
  end if;

  // --- Opzoeken te wijzigen recept
  select RcptGid into @_RcptGid
  from   tabReceptuur
  where  RcptCode = @ReceptCode;
  if @_RcptGid is null then
    call Raise(20780,_U('Component verwijderen is'),_U('Ongeldige of geen %1! meegegeven', 'ReceptCode'));   // (20780) %1! niet mogelijk: %2!
  end if;

  // --- Lock zetten op gevonden recept
  begin
    declare @LockResult integer;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid, @LockResult, 0);
    if @LockResult <> 0 /*Lock gelukt*/ then
      call Raise(20741,_U('Recept'));   // (20741) %1! is in gebruik!
    end if;
  end;

  // Ophalen te verwijderen eindproduct
  select RcpcGid into @_RcpcGid from tabReceptuurComponent where RcpcRcptGid = @_RcptGid and RcpcRegelNr = isnull(@RegelNummer,0);

  // Controle: @RegelNummer moet wel bestaan binnen het Recept
  if @_RcpcGid is null then
    call Raise(20700,'RegelNummer');   // (20700) Ongeldige waarde: %1!
  end if;

  // --- Verwijder Componentregel uit recept
  delete
  from  tabReceptuurComponent
  where RcpcRcptGid = @_RcptGid
  and   RcpcRegelNr = isnull(@RegelNummer,0);

  // --- Lock vrijgeven
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid);

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Component_Wijzigen';
  // call TraceEind(@@ErrorTextProcedure);
end;   // atomic


create or replace procedure WebSvcProc_Recept_Eindproduct_ToevoegenWijzigen
(  in @ReceptCode                                 nchar(20),
   in @RegelNummer                                integer,
   in @ArtikelNummer                              nchar(20),
   in @ProductieAantal                            numeric(15,3),
   in @BerekenKostprijsPrijswijzigingAdvies       nchar(21),
   in @PercentageKostprijsPrijswijzigingAdvies    numeric(15,2),
   in @BerekenVerkoopprijsPrijswijzigingAdvies    nchar(24),
   in @PercentageVerkoopprijsPrijswijzigingAdvies numeric(15,2)
)
result(RegelNummer integer)

begin
  // Fixed enumerators
  declare @Mode      smallint;
  declare _TOEVOEGEN smallint = 0;
  declare _WIJZIGEN  smallint = 1;

  declare @_RcpeRegelNr integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Eindproduct_ToevoegenWijzigen > ';
  // call TraceBegin('WebSvcProc_Recept_Eindproduct_ToevoegenWijzigen > @ReceptCode = ' + @ReceptCode + ', @RegelNummer = ' + @RegelNummer);

  // Module controle
  if IsModuleActive('rr') = 0 then   // Module t.b.v. productie
    call Raise(20790,_U('Optie Productie'));   // (20790) %1! niet geactiveerd!
  end if;

  begin atomic
    declare @_RcptGid                              integer;
    declare @_RcptSoort                            smallint;
    declare @_RcpeGid                              integer;
    declare @_RcpeArtGid                           integer;
    declare @_RcpeAantal                           numeric(15,3);
    declare @_RcpeBerekenArtKostprijsBerekening    smallint;
    declare @_RcpeBerekenArtKostprijsPercentage    numeric(15,2);
    declare @_RcpeBerekenArtVerkoopprijsBerekening smallint;
    declare @_RcpeBerekenArtVerkoopprijsPercentage numeric(15,2);
    declare @_ArtAantDecAantallen                  smallint;
    declare @_ContrAantal                          numeric(15,3);

    // Opzoeken te wijzigen recept
    select RcptGid into @_RcptGid
    from   tabReceptuur
    where  RcptCode = @ReceptCode;
    if @_RcptGid is null then
      call Raise(20780,_U('Recept wijzigen is'),_U('Ongeldige of geen %1! meegegeven', 'ReceptCode'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // Gevonden recept locken
    begin
      declare @LockResult integer;
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid, @LockResult, 0);
      if @LockResult <> 0 then
        call Raise(20741,_U('Recept'));   // (20741) %1! is in gebruik!
      end if;
    end;

    // Ophalen van de benodigde Receptuur gegevens nadat recept succesvol is gelocked
    select RcptGid,
           RcptSoort
    into   @_RcptGid,
           @_RcptSoort
    from   tabReceptuur
    where  RcptGid = @_RcptGid;

    // ---------------------------------------------------------
    // --- KEUZE TOEVOEGEN OF WIJZIGEN (o.b.v. @RegelNummer) ---
    // ---------------------------------------------------------
    if @RegelNummer is null then
      // --- Toevoegen
      set @Mode = _TOEVOEGEN;

      set @_RcpeRegelNr = 1;     // Nog geen eindproducten aanwezig, dan beginnen met Regelnummer 001
      // Als er geen regels zijn, dan blijft @_RcpeRegelNr zoals die al was, dus op 1
      select first (RcpeRegelNr + 1) into @_RcpeRegelNr from TabReceptuurEindProduct where RcpeRcptGid = @_RcptGid order by RcpeRegelNr desc;
      // Initialiseer variabelen o.a. met default waarden
      set @_RcpeArtGid                           = null;
      set @_RcpeAantal                           = 0;
      set @_RcpeBerekenArtKostprijsBerekening    = 0; /*niet*/
      set @_RcpeBerekenArtKostprijsPercentage    = 100;
      set @_RcpeBerekenArtVerkoopprijsBerekening = 0; /*niet*/
      set @_RcpeBerekenArtVerkoopprijsPercentage = 100;

    else
      // --- Wijzigen
      set @Mode = _WIJZIGEN;

      // Ophalen gegevens van bestaande eindproduct
      select     RcpeGid,
                 RcpeRegelNr,
                 RcpeArtGid,
                 RcpeAantal,
                 RcpeBerekenArtKostprijsBerekening,
                 RcpeBerekenArtKostprijsPercentage,
                 RcpeBerekenArtVerkoopprijsBerekening,
                 RcpeBerekenArtVerkoopprijsPercentage,
                 ArtAantDecAantallen
      into       @_RcpeGid,
                 @_RcpeRegelNr,
                 @_RcpeArtGid,
                 @_RcpeAantal,
                 @_RcpeBerekenArtKostprijsBerekening,
                 @_RcpeBerekenArtKostprijsPercentage,
                 @_RcpeBerekenArtVerkoopprijsBerekening,
                 @_RcpeBerekenArtVerkoopprijsPercentage,
                 @_ArtAantDecAantallen
      from       tabReceptuurEindproduct
      inner join tabArtikel
      on         ArtGid = RcpeArtGid
      and        ArtSoort = 2   // ArtSoort moet altijd type Artikel (2) zijn
      where      RcpeRcptGid = @_RcptGid
      and        RcpeRegelNr = @RegelNummer;
      // Controle: @RegelNummer moet wel een bestaande regelnummer zijn binnen het recept
      if @_RcpeGid is null then
        call Raise(20700,'RegelNummer');   // (20700) Ongeldige waarde: %1!
      end if;
    end if;

    // Controle: Indien @_RcptSoort = SAMENSTELLING (0) en @_RcpeRegelNr > 1, dan is slechts 1 eindproductregel toegestaan.
    if @_RcptSoort = 0 and @_RcpeRegelNr > 1 then   // Receptsoort = SAMENSTELLING (0) en Regelnummer is groter dan 1
      call Raise(20701,_U('Meerdere eindproducten zijn niet toegestaan in combinatie met %1! %2!.', 'ReceptSoort', '''SAMENSTELLING'''));   // (20701) Ongeldige combinatie: %1!
    end if;

    // ------------------------------
    // --- Controles voor artikel ---
    // ------------------------------

    // --- - Controle: Recept mag niet zijn gekoppeld aan een artikel (Eindproduct binnen een Samenstelling) tijdens het wijzigen
    if @Mode = _WIJZIGEN and @ArtikelNummer is not null and exists (select first 1 from tabArtikel where  ArtSamengesteldRcptGid = @_RcptGid) then
      call Raise(20780,_U('Artikel (Eindproduct) wijzigen is'),_U('Recept is gekoppeld aan een artikel (Samenstelling)'));   // (20780) %1! niet mogelijk: %2!
    end if;

    // --- - Controle: Meegegeven artikel moet bestaan
    if isnull(@ArtikelNummer,'') <> '' then
       set    @_RcpeArtGid = null;
       select ArtGid
       into   @_RcpeArtGid
       from   tabArtikel
       where  ArtCode = @ArtikelNummer
       and    ArtSoort = 2;     // Het Eindproduct moet altijd van type Artikel (2) zijn
    end if;

    if @_RcpeArtGid is null then
      call Raise(20700,'ArtikelNummer');   // (20700) Ongeldige waarde: %1!
    end if;

    // --- - Ophalen benodigde artikelgegevens
    select ArtAantDecAantallen
    into   @_ArtAantDecAantallen
    from   tabArtikel
    where  ArtGid = @_RcpeArtGid;

    // --- - Controle: @ProductieAantal groter dan 0 is verplicht tijdens toevoegen van een nieuw eindproduct en ReceptSoort = "PRODUCTIE" (1), optioneel tijdens wijzigen
    if @_RcptSoort = 1 /*Productie*/ then
      if isnull(@ProductieAantal,0) < 1 then
        if @Mode = _TOEVOEGEN then
          call Raise(20700,'ProductieAantal');    // Ongeldige of geen Aantal meegegeven
        end if;
      else
        // --- -- Aantal decimalen van @ProductieAantal moet passen in aantal decimalen van artikel
        set @_ContrAantal = truncnum(@ProductieAantal,@_ArtAantDecAantallen);  // Controleren op meegegeven waarde in decimalen
        if (@_ContrAantal - @ProductieAantal) <> 0 then
          call Raise(20780,_U('Eindproduct toevoegen is'),_U('Teveel decimalen in %1! meegegeven!', 'ProductieAantal'));   // (20780) %1! niet mogelijk: %2!
        else
          set @_RcpeAantal = @ProductieAantal;
        end if;
      end if;
    else   /*Samenstelling*/
      // Indien ReceptSoort = "SAMENSTELLING" (0), dan is @_RcpeAantal altijd 1, eventueel meegegeven @ProductieAantal wordt genegeerd
      set @_RcpeAantal = 1;
    end if;

    // --------------------------------------------------------
    // --- Bereken Kost-/Verkoopprijs prijswijziging advies ---
    // --------------------------------------------------------

    // --- - Controle: Indien BerekenKostprijsPrijswijzigingAdvies is meegegeven, dan moet dit een geldige keuze zijn.
    if isnull(@BerekenKostprijsPrijswijzigingAdvies,'') <> '' then
      case @BerekenKostprijsPrijswijzigingAdvies
        when 'NIET'                  then set @_RcpeBerekenArtKostprijsBerekening = 0;
        when 'TOTAAL_KOSTPRIJS_COMP' then set @_RcpeBerekenArtKostprijsBerekening = 1;
      else
        call Raise(20700,'BerekenKostprijsPrijswijzigingAdvies');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // --- - Controle: Indien BerekenKostprijsPrijswijzigingAdvies is ongelijk aan "NIET" (0)
    if @_RcpeBerekenArtKostprijsBerekening <> 0 /*NIET*/ then
      if @PercentageKostprijsPrijswijzigingAdvies is not null then
        // --- -- Controle: PercentageKostprijsPrijswijzigingAdvies is meegegeven, dan moet RcpeBerekenArtKostprijsPercentage een waarde hebben tussen 0.00% en 999.99%
        if @PercentageKostprijsPrijswijzigingAdvies >= 0.00 and @PercentageKostprijsPrijswijzigingAdvies <= 999.99 then
          set @_RcpeBerekenArtKostprijsPercentage = @PercentageKostprijsPrijswijzigingAdvies;
        else
          call Raise(20700,'PercentageKostprijsPrijswijzigingAdvies');   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
    // --- - Controle: Indien BerekenKostprijsPrijswijzigingAdvies is gelijk aan "NIET" (0), dan heeft RcpeBerekenArtKostprijsPercentage de Default waarde van 100.00%
    //                 en wordt eventueel meegegeven waarde in @PercentageKostprijsPrijswijzigingAdvies genegeerd
    else
      set @_RcpeBerekenArtKostprijsPercentage = 100;
    end if;

    // --- - Controle: Indien BerekenVerkoopprijsPrijswijzigingAdvies is meegegeven, dan moet dit een geldige keuze zijn.
    if isnull(@BerekenVerkoopprijsPrijswijzigingAdvies,'') <> '' then   // BerekenVerkoopprijsPrijswijzigingAdvies is meegegeven
      case @BerekenVerkoopprijsPrijswijzigingAdvies
        when 'NIET'                     then set @_RcpeBerekenArtVerkoopprijsBerekening = 0;
        when 'TOTAAL_KOSTPRIJS_COMP'    then set @_RcpeBerekenArtVerkoopprijsBerekening = 1;
        when 'TOTAAL_VERKOOPPRIJS_COMP' then set @_RcpeBerekenArtVerkoopprijsBerekening = 2;
        when 'BEREKENDE_KOSTPRIJS'      then set @_RcpeBerekenArtVerkoopprijsBerekening = 3;
      else
        call Raise(20700,'BerekenVerkoopprijsPrijswijzigingAdvies');   // (20700) Ongeldige waarde: %1!
      end case;
    end if;

    // --- - Controle: Indien BerekenVerkoopprijsPrijswijzigingAdvies is ongelijk aan "NIET" (0)
    if @_RcpeBerekenArtVerkoopprijsBerekening <> 0 /*NIET*/ then
      if @PercentageVerkoopprijsPrijswijzigingAdvies is not null then
        // --- -- Controle: PercentageVerkoopprijsPrijswijzigingAdvies is meegegeven, dan moet RcpeBerekenArtVerkoopprijsPercentage een waarde hebben tussen 0.00% en 999.99%
        if @PercentageVerkoopprijsPrijswijzigingAdvies >= 0.00 and @PercentageVerkoopprijsPrijswijzigingAdvies <= 999.99 then
          set @_RcpeBerekenArtVerkoopprijsPercentage = @PercentageVerkoopprijsPrijswijzigingAdvies;
        else
          call Raise(20700,'PercentageVerkoopprijsPrijswijzigingAdvies');   // (20700) Ongeldige waarde: %1!
        end if;
      end if;
    // --- - Controle: Indien BerekenVerkoopprijsPrijswijzigingAdvies is gelijk aan "NIET" (0), dan heeft RcpeBerekenArtVerkoopprijsPercentage de Default waarde van 100.00%
    //                 en wordt eventuele meegegeven waarde in @PercentageVerkoopprijsPrijswijzigingAdvies genegeerd
    else
      set @_RcpeBerekenArtVerkoopprijsPercentage = 100;
    end if;

    // Gegevens bijwerken in de database
    if @Mode = _TOEVOEGEN then   // Nieuw eindproductregel toevoegen in de database
      insert into tabReceptuurEindproduct
      (  RcpeRcptGid,
         RcpeRegelNr,
         RcpeArtGid,
         RcpeAantal,
         RcpeBerekenArtKostprijsBerekening,
         RcpeBerekenArtKostprijsPercentage,
         RcpeBerekenArtVerkoopprijsBerekening,
         RcpeBerekenArtVerkoopprijsPercentage
      )
      values
      (  @_RcptGid,
         @_RcpeRegelNr,
         @_RcpeArtGid,
         @_RcpeAantal,
         @_RcpeBerekenArtKostprijsBerekening,
         @_RcpeBerekenArtKostprijsPercentage,
         @_RcpeBerekenArtVerkoopprijsBerekening,
         @_RcpeBerekenArtVerkoopprijsPercentage
      );
    else   // Gewijzigde eindproductregel opslaan in de database
      update tabReceptuurEindproduct
      set   RcpeArtGid                           = @_RcpeArtGid,
            RcpeAantal                           = @_RcpeAantal,
            RcpeBerekenArtKostprijsBerekening    = @_RcpeBerekenArtKostprijsBerekening,
            RcpeBerekenArtKostprijsPercentage    = @_RcpeBerekenArtKostprijsPercentage,
            RcpeBerekenArtVerkoopprijsBerekening = @_RcpeBerekenArtVerkoopprijsBerekening,
            RcpeBerekenArtVerkoopprijsPercentage = @_RcpeBerekenArtVerkoopprijsPercentage
      where RcpeGid = @_RcpeGid;
    end if;
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid);
  end;  // atomic

  // Ophalen resultaat
  select @_RcpeRegelNr as RegelNummer;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Eindproduct_ToevoegenWijzigen';
  // call TraceEind(@@ErrorTextProcedure);
end;


create or replace procedure WebSvcProc_Recept_Eindproduct_Verwijderen
(  in @ReceptCode  nchar(20),
   in @RegelNummer integer
)

begin atomic
  declare @_RcptGid integer;
  declare @_RcpeGid integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Eindproduc_Verwijderen > ';
  // call TraceBegin('WebSvcProc_Recept_Eindproduct_Verwijderen > @ReceptCode = ' + @ReceptCode + ', @RegelNummer = ' + @RegelNummer);

  // Module controle
  if IsModuleActive('rr') = 0 then   // Module t.b.v. productie
    call Raise(20790,_U('Optie Productie')  ); // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken te wijzigen recept
  select RcptGid into @_RcptGid
  from   tabReceptuur
  where  RcptCode = @ReceptCode;
  if @_RcptGid is null then
    call Raise(20780,_U('Eindproduct verwijderen is'),_U('Ongeldige of geen %1! meegegeven', 'ReceptCode'));   // (20780) %1! niet mogelijk: %2!
  end if;

  // Gevonden recept locken
  begin
    declare @LockResult integer;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid, @LockResult, 0);
    if @LockResult <> 0 /*Lock gelukt*/ then
      call Raise(20741,_U('Recept'));   // (20741) %1! is in gebruik!
    end if;
  end;

  // Ophalen te verwijderen eindproduct
  select RcpeGid into @_RcpeGid from tabReceptuurEindproduct where RcpeRcptGid = @_RcptGid and RcpeRegelNr = isnull(@RegelNummer,0);

  // Controle: @RegelNummer moet wel bestaan binnen het Recept
  if @_RcpeGid is null then
    call Raise(20700,'RegelNummer');   // (20700) Ongeldige waarde: %1!
  end if;

  // Controle: Recept mag niet zijn gekoppeld aan een artikel (Eindproduct binnen een Samenstelling)
  if exists (select first 1 from tabArtikel where ArtSamengesteldRcptGid = @_RcptGid) then
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid);
    call Raise(20780,_U('Eindproduct verwijderen is'),_U('Recept is gekoppeld aan een artikel (Samenstelling)'));   // (20780) %1! niet mogelijk: %2!
  end if;

  // Recept Eindproductregel verwijderen uit de database
  delete
  from  tabReceptuurEindproduct
  where RcpeGid = @_RcpeGid
  and   RcpeRegelNr = isnull(@RegelNummer,0);
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid);

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Eindproduct_Wijzigen';
  // call TraceEind(@@ErrorTextProcedure);
end;  //atomic


