create or replace procedure WebSvcProc_Recept_Receptuur_Toevoegen
(  in @ReceptCode                     nchar(20),
   in @Zoekcode                       nchar(20),
   in @ReceptOms                      nchar(40),
   in @ReceptSoort                    nchar(13),
   in @MinimumAantal                  numeric(10,0),
   in @MaximumAantal                  numeric(10,0),
   in @DefaultAantal                  numeric(10,0),
   in @RekeningNrResultaat            nchar(28),
   in @Orderstatus                    nchar(13),
   in @NuAfTeBoeken                   nchar(16),
   in @NuOpTeBoeken                   nchar(16),
   in @GeblokkeerdProductie           smallint,
   in @Document                       nchar(255),
   in @Opmerking                      long nvarchar,
   in @PrijsPerProductieEenh          nchar(23),
   in @AantalPrijsProductieEenheid    numeric(10,0),
   in @AparteProductieOrdersPerRecept smallint,
   in @ProductieGrootte               numeric(15,3) default 1
)
result (ReceptCode nchar(20))

begin
  declare @_RcptGid                                integer;
  declare @_RcptCode                               nchar(20);
  declare @_RcptZoekcode                           nchar(20);
  declare @_RcptOmschrijving                       nchar(40);
  declare @_RcptSoort                              smallint;
  declare @_RcptBatchMinimum                       numeric(15,3);
  declare @_RcptBatchMaximum                       numeric(15,3);
  declare @_RcptBatchDefault                       numeric(15,3);
  declare @_RcptRksGid                             integer;
  declare @_RcptDefaultProductieOrderStatus        smallint;
  declare @_RcptVulAantalDezeVerwerkingComponent   smallint;
  declare @_RcptVulAantalDezeVerwerkingEindproduct smallint;
  declare @_RcptGeblokkeerd                        smallint;
  declare @_RcptDocument                           nchar(255);
  declare @_RcptOpmerking                          long nvarchar;
  declare @_RcptPrijsBatchGrootte                  smallint;
  declare @_RcptPrijsBatchAantal                   numeric(15,3);
  declare @_RcptAparteProductieOrdersPerRecept     smallint;
  declare @_RcptBatchProductieGrootte              numeric(15,3);

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Receptuur_Toevoegen > ';
  // call TraceBegin('WebSvcProc_Recept_Receptuur_Toevoegen > @ReceptCode = ' + @ReceptCode);

  begin -- Defaults
    set @_RcptSoort        = 0 /*Samenstelling*/;
    set @_RcptBatchMinimum = 1;
    set @_RcptBatchMaximum = null; //Geen maximum
    set @_RcptBatchDefault = 1;
    set @_RcptRksGid       = null; // MOET worden opgegeven
    select RcpvRksGidResultaat,
           RcpvDefaultProductieOrderStatus,
           RcpvVulAantalDezeVerwerkingComponent,
           RcpvVulAantalDezeVerwerkingEindProduct
    into   @_RcptRksGid,
           @_RcptDefaultProductieOrderStatus,
           @_RcptVulAantalDezeVerwerkingComponent,
           @_RcptVulAantalDezeVerwerkingEindProduct
    from   tabReceptuurVasteGegevens;
    set @_RcptGeblokkeerd                    = 0;
    set @_RcptPrijsBatchGrootte              = 0 /* Default aantal*/;
    set @_RcptAparteProductieOrdersPerRecept = 0; //Niet
  end;

  set @ProductieGrootte = IsNull(@ProductieGrootte, 1);

  begin -- Velden controleren en invullen waarde
    call WebSvcHulpProc_Recept_Controleer_ReceptuurKop(
      0 /*Toevoegen*/,
      @ReceptCode,
      @Zoekcode,
      @ReceptOms,
      @ReceptSoort,
      @MinimumAantal,
      @MaximumAantal,
      @DefaultAantal,
      @RekeningNrResultaat,
      @Orderstatus,
      @NuAfTeBoeken,
      @NuOpTeBoeken,
      @GeblokkeerdProductie,
      @Document,
      @Opmerking,
      @PrijsPerProductieEenh,
      @AantalPrijsProductieEenheid,
      @AparteProductieOrdersPerRecept,
      @ProductieGrootte,
      @_RcptGid,
      @_RcptCode,
      @_RcptZoekcode,
      @_RcptOmschrijving,
      @_RcptSoort,
      @_RcptBatchMinimum,
      @_RcptBatchMaximum,
      @_RcptBatchDefault,
      @_RcptRksGid,
      @_RcptDefaultProductieOrderStatus,
      @_RcptVulAantalDezeVerwerkingComponent,
      @_RcptVulAantalDezeVerwerkingEindproduct,
      @_RcptGeblokkeerd,
      @_RcptDocument,
      @_RcptOpmerking,
      @_RcptPrijsBatchGrootte,
      @_RcptPrijsBatchAantal,
      @_RcptAparteProductieOrdersPerRecept,
      @_RcptBatchProductieGrootte
    );
  end;


  begin -- Recept toevoegen in tabel tabReceptuur
    insert into tabReceptuur
    (  RcptCode,
       RcptZoekCode,
       RcptOmschrijving,
       RcptSoort,
       RcptBatchMinimum,
       RcptBatchMaximum,
       RcptBatchDefault,
       RcptRksGid,
       RcptDefaultProductieOrderStatus,
       RcptVulAantalDezeVerwerkingComponent,
       RcptVulAantalDezeVerwerkingEindProduct,
       RcptGeblokkeerd,
       RcptDocument,
       RcptOpmerking,
       RcptPrijsBatchGrootte,
       RcptPrijsBatchAantal,
       RcptAparteProductieOrdersPerRecept,
       RcptBatchProductieGrootte
    )
    values
    (  @_RcptCode,
       @_RcptZoekcode,
       @_RcptOmschrijving,
       @_RcptSoort,
       @_RcptBatchMinimum,
       @_RcptBatchMaximum,
       @_RcptBatchDefault,
       @_RcptRksGid,
       @_RcptDefaultProductieOrderStatus,
       @_RcptVulAantalDezeVerwerkingComponent,
       @_RcptVulAantalDezeVerwerkingEindProduct,
       @_RcptGeblokkeerd,
       @_RcptDocument,
       @_RcptOpmerking,
       @_RcptPrijsBatchGrootte,
       @_RcptPrijsBatchAantal,
       @_RcptAparteProductieOrdersPerRecept,
       @_RcptBatchProductieGrootte
    );
  end;

  // Resultaat ophalen
  select @_RcptCode as ReceptCode;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Receptuur_Toevoegen';
   // call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Recept_Receptuur_Verwijderen(in @ReceptCode nchar(20))

begin atomic
  declare @_RcptGid      integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Receptuur_Verwijderen > ';
  // call TraceBegin('WebSvcProc_Recept_Receptuur_Verwijderen > @ReceptCode = ' + @ReceptCode);

  if IsModuleActive('rr') = 0 then             // Module t.b.v. productie
    call Raise(20790,_U('Optie Productie')  ); // (20790) '%1!' niet geactiveerd!
  end if;

  // Opzoeken te verwijderen recept
  select RcptGid into @_RcptGid
  from   tabReceptuur
  where  RcptCode = @ReceptCode;
  if @_RcptGid is null then
    call Raise(20720,'ReceptCode');   // (20720) niet gevonden: %1!
  end if;

  // Gevonden recept Locken
  begin
    declare @LockResult integer;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid, @LockResult, 0);   // Recept wordt gelocked
    if @LockResult <> 0 /*Lock gelukt*/ then
      call Raise(20741,_U('Recept'));   // (20741) %1! is in gebruik!
    end if;
  end;

  // Controle: Recept mag niet zijn gekoppeld aan een artikel (Eindproduct binnen een Samenstelling)
  if exists (select first 1 from tabArtikel where ArtSamengesteldRcptGid = @_RcptGid) then
    call Raise(20780,_U('Recept verwijderen is'),_U('Recept is gekoppeld aan een artikel (Samenstelling)'));   // (20780) %1! niet mogelijk: %2!
  end if;

  // Controle: Recept mag niet worden gebruikt binnen een productieadvies
  if exists (select first 1 from tabProductieAdviesRegel where PrrRcptGid = @_RcptGid) then
    call Raise(20780,_U('Recept verwijderen is'),_U('Recept wordt gebruikt in een productieadvies'));   // (20780) %1! niet mogelijk: %2!
  end if;

  // Controle: Recept mag niet zijn gekoppeld aan orderregels
  if exists (select first 1 from tabOrderRegel where OrrRcptGid = @_RcptGid) then
    call Raise(20780,_U('Recept verwijderen is'),_U('Recept is gekoppeld aan orderregel(s)'));   // (20780) %1! niet mogelijk: %2!
  end if;

  // Recept verwijderen uit de database
  delete from tabReceptuur where RcptGid = @_RcptGid;
  call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid);

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Receptuur_Verwijderen';
  // call TraceEind(@@ErrorTextProcedure);
end;   // atomic


create or replace procedure WebSvcProc_Recept_Receptuur_Wijzigen
(  in @ReceptCode                     nchar(20),
   in @Zoekcode                       nchar(20),
   in @ReceptOms                      nchar(40),
   in @ReceptSoort                    nchar(13),
   in @MinimumAantal                  numeric(10,0),
   in @MaximumAantal                  numeric(10,0),
   in @DefaultAantal                  numeric(10,0),
   in @RekeningNrResultaat            nchar(28),
   in @Orderstatus                    nchar(13),
   in @NuAfTeBoeken                   nchar(16),
   in @NuOpTeBoeken                   nchar(16),
   in @GeblokkeerdProductie           smallint,
   in @Document                       nchar(255),
   in @Opmerking                      long nvarchar,
   in @PrijsPerProductieEenh          nchar(23),
   in @AantalPrijsProductieEenheid    numeric(10,0),
   in @AparteProductieOrdersPerRecept smallint,
   in @ProductieGrootte               numeric(15,3) default null
)
begin atomic
  declare @_RcptGid                                integer;
  declare @_RcptCode                               nchar(20);
  declare @_RcptZoekcode                           nchar(20);
  declare @_RcptOmschrijving                       nchar(40);
  declare @_RcptSoort                              smallint;
  declare @_RcptBatchMinimum                       numeric(15,3);
  declare @_RcptBatchMaximum                       numeric(15,3);
  declare @_RcptBatchDefault                       numeric(15,3);
  declare @_RcptRksGid                             integer;
  declare @_RcptDefaultProductieOrderStatus        smallint;
  declare @_RcptVulAantalDezeVerwerkingComponent   smallint;
  declare @_RcptVulAantalDezeVerwerkingEindproduct smallint;
  declare @_RcptGeblokkeerd                        smallint;
  declare @_RcptDocument                           nchar(255);
  declare @_RcptOpmerking                          long nvarchar;
  declare @_RcptPrijsBatchGrootte                  smallint;
  declare @_RcptPrijsBatchAantal                   numeric(15,3);
  declare @_RcptAparteProductieOrdersPerRecept     smallint;
  declare @_RcptBatchProductieGrootte              numeric(15,3);

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Receptuur_Wijzigen > ';
  // call TraceBegin('WebSvcProc_Recept_Receptuur_Wijzigen > @ReceptCode = ' + @ReceptCode);


  // --- Opzoeken te wijzigen recept
  select RcptGid into @_RcptGid
  from   tabReceptuur
  where  RcptCode = @ReceptCode;
  if @_RcptGid is null then
    call Raise(20720,'ReceptCode');   // (20720) niet gevonden: %1!
  end if;


  begin // Lock recept
    declare @LockResult integer;
    call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid, @LockResult, 0);   // Recept wordt gelocked
    if @LockResult <> 0 /*Lock gelukt*/ then
      call Raise(20741,_U('Recept'));   // (20741) %1! is in gebruik!
    end if;
  end;

  // --- Gegevens van het recept ophalen
  select RcptGid,
         RcptCode,
         RcptZoekcode,
         RcptOmschrijving,
         RcptSoort,
         RcptBatchMinimum,
         RcptBatchMaximum,
         RcptBatchDefault,
         RcptRksGid,
         RcptDefaultProductieOrderStatus,
         RcptVulAantalDezeVerwerkingComponent,
         RcptVulAantalDezeVerwerkingEindproduct,
         RcptGeblokkeerd,
         RcptDocument,
         RcptOpmerking,
         RcptPrijsBatchGrootte,
         RcptPrijsBatchAantal,
         RcptAparteProductieOrdersPerRecept,
         RcptBatchProductieGrootte
  into   @_RcptGid,
         @_RcptCode,
         @_RcptZoekcode,
         @_RcptOmschrijving,
         @_RcptSoort,
         @_RcptBatchMinimum,
         @_RcptBatchMaximum,
         @_RcptBatchDefault,
         @_RcptRksGid,
         @_RcptDefaultProductieOrderStatus,
         @_RcptVulAantalDezeVerwerkingComponent,
         @_RcptVulAantalDezeVerwerkingEindproduct,
         @_RcptGeblokkeerd,
         @_RcptDocument,
         @_RcptOpmerking,
         @_RcptPrijsBatchGrootte,
         @_RcptPrijsBatchAantal,
         @_RcptAparteProductieOrdersPerRecept,
         @_RcptBatchProductieGrootte
  from   tabReceptuur
  where  RcptGid = @_RcptGid;

  // --- Ter validatie, het recept zou net verwijderd kunnen zijn
  if @_RcptGid is null then
    call Raise(20720,'ReceptCode');   // (20720) niet gevonden: %1!
  end if;

  set @ProductieGrootte = IsNull(@ProductieGrootte, @_RcptBatchProductieGrootte);

  // --- Controles
  call WebSvcHulpProc_Recept_Controleer_ReceptuurKop(
    1 /*Wijzigen*/,
    @ReceptCode,
    @Zoekcode,
    @ReceptOms,
    @ReceptSoort,
    @MinimumAantal,
    @MaximumAantal,
    @DefaultAantal,
    @RekeningNrResultaat,
    @Orderstatus,
    @NuAfTeBoeken,
    @NuOpTeBoeken,
    @GeblokkeerdProductie,
    @Document,
    @Opmerking,
    @PrijsPerProductieEenh,
    @AantalPrijsProductieEenheid,
    @AparteProductieOrdersPerRecept,
    @ProductieGrootte,
    @_RcptGid,
    @_RcptCode,
    @_RcptZoekcode,
    @_RcptOmschrijving,
    @_RcptSoort,
    @_RcptBatchMinimum,
    @_RcptBatchMaximum,
    @_RcptBatchDefault,
    @_RcptRksGid,
    @_RcptDefaultProductieOrderStatus,
    @_RcptVulAantalDezeVerwerkingComponent,
    @_RcptVulAantalDezeVerwerkingEindproduct,
    @_RcptGeblokkeerd,
    @_RcptDocument,
    @_RcptOpmerking,
    @_RcptPrijsBatchGrootte,
    @_RcptPrijsBatchAantal,
    @_RcptAparteProductieOrdersPerRecept,
    @_RcptBatchProductieGrootte
  );

  // --- Gewijzigde gegevens bijwerken in tabel tabReceptuur
  update tabReceptuur
  set    RcptZoekcode                           = @_RcptZoekcode,
         RcptOmschrijving                       = @_RcptOmschrijving,
         RcptSoort                              = @_RcptSoort,
         RcptBatchMinimum                       = @_RcptBatchMinimum,
         RcptBatchMaximum                       = @_RcptBatchMaximum,
         RcptBatchDefault                       = @_RcptBatchDefault,
         RcptRksGid                             = @_RcptRksGid,
         RcptDefaultProductieOrderStatus        = @_RcptDefaultProductieOrderStatus,
         RcptVulAantalDezeVerwerkingComponent   = @_RcptVulAantalDezeVerwerkingComponent,
         RcptVulAantalDezeVerwerkingEindproduct = @_RcptVulAantalDezeVerwerkingEindproduct,
         RcptGeblokkeerd                        = @_RcptGeblokkeerd,
         RcptDocument                           = @_RcptDocument,
         RcptOpmerking                          = @_RcptOpmerking,
         RcptPrijsBatchGrootte                  = @_RcptPrijsBatchGrootte,
         RcptPrijsBatchAantal                   = @_RcptPrijsBatchAantal,
         RcptAparteProductieOrdersPerRecept     = @_RcptAparteProductieOrdersPerRecept,
         RcptBatchProductieGrootte              = @_RcptBatchProductieGrootte
    where  RcptGid = @_RcptGid;

  begin // Vrijgeven lock recept
    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid);
  end;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_Receptuur_Wijzigen';
  // call TraceEind(@@ErrorTextProcedure);
end;  // atomic



create or replace procedure WebSvcProc_Recept_VrijeRubriek_Wijzigen(
  in @ReceptCode            nchar(20),
  in @RubriekOmschrijving   nchar(41),
  in @RubriekInhoud         nchar(256))    // de haakje sluiten hoeft niet op aparte regel, kan ook hier
begin
  declare @LockUserNaam  nchar(40) = 'KingWebService';
  declare @SpId          integer = @@SpId;
  declare @LoginTime     datetime = @@LoginTime;

  declare @_RcptGid      integer;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_VrijeRubriek_Wijzigen > @ReceptCode = '+string(@ReceptCode)+', @RubriekOmschrijving = '+@RubriekOmschrijving;
  //call TraceBegin(@@ErrorTextProcedure);

  // Module controle
  if IsModuleActive('rr') = 0 then             // Module t.b.v. productie
    call Raise(20790,_U('Optie Productie')  ); // (20790) '%1!' niet geactiveerd!
  end if;

  if ( isnull( trim( @RubriekOmschrijving ), '' ) = '' ) then
    call Raise(20700, _U('%1! is verplicht.', 'RubriekOmschrijving'));  // (20700) Ongeldige waarde: <parameter of opmerking>
  end if;

  if length( trim( isnull( @RubriekOmschrijving, '' ) ) ) > 40 then
    call Raise(20700 , _U('%1!, maximaal %2! tekens toegestaan.', 'RubriekOmschrijving', '40')) ; // Ongeldige waarde: %1!
  end if;

  // King 5 stored proc VrInsertOrReplaceValue doet NIKS als waarde NULL is.
  // Men wil iets wijzigen, dus opgeven van waarde afdwingen
  if ( @RubriekInhoud is null ) then
    call Raise(20700, _U('%1! is verplicht.', 'RubriekInhoud'));     // (20700) Ongeldige waarde: <parameter of opmerking>
  end if;

  // Opzoeken te wijzigen recept
  select RcptGid into @_RcptGid
  from   tabReceptuur
  where  RcptCode = @ReceptCode;
  if @_RcptGid is null then
    call Raise(20780,_U('Recept wijzigen is'),_U('Ongeldige of geen %1! meegegeven', 'ReceptCode'));   // (20780) %1! niet mogelijk: %2!
  end if;

  if(@_RcptGid is null) then
    call Raise(20720,  _U('%1! %2!', 'Recept', @ReceptCode)) ;  // (20720) %1 niet gevonden!
  end if;

  begin atomic
    // Neem het recept in gebruik...
    begin
      declare @LockResult integer;
      call LockSetOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid, @LockResult, 0);
      if @LockResult <> 0 /*Lock gelukt*/ then
        call Raise(20741,_U('Recept'));   // (20741) %1! is in gebruik!
      end if;
    end;
    // ... als je de vrije rubriek gaat wijzigen
    call KingSystem.VrInsertOrReplaceValue( 'RCP', 0, 0, @_RcptGid, @RubriekOmschrijving, @RubriekInhoud );

    call LockreleaseOnId(@@SpId, @@LoginTime, 1, 'tabReceptuur', @_RcptGid);
  end;

  set @@ErrorTextProcedure = 'WebSvcProc_Recept_VrijeRubriek_Wijzigen > eind'
//call TraceEind(@@ErrorTextProcedure);
end;



create or replace procedure WebSvcProc_Verplaatsing_Toevoegen(
  in @CategorieCode nchar(20),
  in @CategorieOmschrijving nchar(40),
  in @ArtikelNummer nchar(20),
  in @PartijNummer nchar(20),
  in @AantalTeVerplaatsen numeric(15,3),
  in @VerpaktPer numeric(15,3),
  in @MagazijnCodeVan numeric(3,0),
  in @LocatieCodeVan nchar(20),
  in @MagazijnCodeNaar numeric(3,0),
  in @LocatieCodeNaar nchar(20)
)
result (VerplaatsingId integer)

begin
  declare @_ArtGid integer;
  declare @_ArtCode nchar(20);
  declare @_ArtOms nchar(40);
  declare @_AantalDecAantallen smallint;
  declare @_ArtIsPartijRegistreren smallint;
  declare @_ArtPartijGid integer;
  declare @_ArtPartijNummer nchar(20);
  declare @_MagGidVan integer;
  declare @_MagCodeVan integer;
  declare @_LocGidVan integer;
  declare @_LocNaamVan nchar(20);
  declare @_MagGidNaar integer;
  declare @_MagCodeNaar integer;
  declare @_LocGidNaar integer;
  declare @_LocNaamNaar nchar(20);
  declare @_LocBlokkade smallint;
  declare @_AantalTeVerplaatsen numeric(15,3);

  /* Module/optie Meerdere Magazijen en locaties actief */
  if IsModuleActive( 'm1' ) = 0 then
    call Raise(20790 , _U('Optie Meerdere magazijnen en magazijnlocaties')) ; /* (20790) <Optie/Module> niet geactiveerd! */
  end if;

  /* Controle CategorieCode, moet ingevuld zijn! */
  if (nullif(@CategorieCode,'') is null) then
    call Raise(20700, 'CategorieCode'); /* Ongeldige waarde: %1! */
  end if;

  set @CategorieOmschrijving = isnull(@CategorieOmschrijving,'');

  /* Ophalen Artikelgegevens */
  select first
         ArtGid,
         ArtCode,
         ArtOms,
         ArtIsPartijRegistreren,
         ArtAantDecAantallen
  into   @_ArtGid,
         @_ArtCode,
         @_ArtOms,
         @_ArtIsPartijRegistreren,
         @_AantalDecAantallen
  from   tabArtikel
  where  ArtSoort = 2 /* Artikel */
         and ArtCode = @ArtikelNummer;

  /* Controle Artikel */
  if (@_ArtGid is null) then
    call Raise(20700, 'ArtikelNummer'); /* (20700) Ongeldige waarde: %1! */
  end if;

  /* Controle Partijnummer */
  if IsNull(@PartijNummer,'') <> '' then

    if (@_ArtIsPartijRegistreren = 0) then
      call Raise(20701, _U('%1!, Artikel is niet partijregistrerend', 'ArtikelNummer/PartijNummer')); /* Ongeldige combinatie: %1! */
    end if;

    /* Ophalen partijgegevens */
    select first
           ArtPartijGid,
           ArtPartijNummer
    into   @_ArtPartijGid,
           @_ArtPartijNummer
    from   tabArtikelPartij
    where  ArtPartijArtGid = @_ArtGid
           and ArtPartijNummer = @PartijNummer;

    if (@_ArtPartijGid is null) then
      call Raise(20720, 'PartijNummer'); /* (20720) %1! niet gevonden! */
    end if;

  end if;

  /* Controle AantalTeVerplaatsen, moet groter zijn dan 0 */
  if (isnull(@AantalTeVerplaatsen,0) <= 0) then
    call Raise(20700, _U('%1!, moet groter zijn dan 0', 'AantalTeVerplaatsen')); /* Ongeldige waarde: %1! */
  end if;

  /* Afronden op het aantal decimalen voor aantallen */
  set @_AantalTeVerplaatsen = round(@AantalTeVerplaatsen, @_AantalDecAantallen);

  /* Controle op aantal decimalen. Komt het aantal overeen met het afgeronde aantal? */
  if (@AantalTeVerplaatsen <> @_AantalTeVerplaatsen) then
    call Raise(20700, _U('%1!, aantal decimalen komt niet overeen met instelling bij het artikel', 'AantalTeVerplaatsen')); /* Ongeldige waarde: %1! */
  end if;

  /* Controle VerpaktPer, Mag niet kleiner zijn dan 1 */
  set @VerpaktPer = isnull(@VerpaktPer, 1); /* Default 1, indien niet gevuld */
  if @VerpaktPer < 1 then
    call Raise(20700, _U('%1!, mag niet kleiner zijn dan 1', 'VerpaktPer')); /* Ongeldige waarde: %1! */
  end if;

  /* Ophalen Magazijn Van*/
  select first
         MagGid,
         MagCode
  into   @_MagGidVan,
         @_MagCodeVan
  from   tabMagazijn
  where  MagCode = @MagazijnCodeVan;

  if (@_MagGidVan is null) then
    call Raise(20720, 'MagazijnCodeVan'); /* (20720) %1! niet gevonden! */
  end if;

  /* Ophalen Locatie Van */
  select LocGid,
         LocNaam
  into   @_LocGidVan,
         @_LocNaamVan
  from   tabLocatie
  where  LocMagGid = @_MagGidVan
         and LocNaam = @LocatieCodeVan;

  if (@_LocGidVan is null) then
    call Raise(20720, 'LocatieCodeVan'); /* (20720) %1! niet gevonden! */
  end if;

  /* Ophalen Magazijn Naar */
  select first
         MagGid,
         MagCode
  into   @_MagGidNaar,
         @_MagCodeNaar
  from   tabMagazijn
  where  MagCode = @MagazijnCodeNaar;

  if (@_MagGidNaar is null) then
    call Raise(20720, 'MagazijnCodeNaar'); /* (20720) %1! niet gevonden! */
  end if;

  /* Ophalen Locatie Naar */
  select LocGid, LocNaam, LocBlokkade
  into @_LocGidNaar, @_LocNaamNaar, @_LocBlokkade
  from tabLocatie
  where LocMagGid = @_MagGidNaar
    and LocNaam = @LocatieCodeNaar;

  if (@_LocGidNaar is null) then
    call Raise(20720, 'LocatieCodeNaar'); /* (20720) %1! niet gevonden! */
  end if;

  /* Controle of locatie VAN anders is dan NAAR */
  if (@_LocGidVan = @_LocGidNaar) then
    call Raise(20701, _U('%1! en %2! zijn hetzelfde!', 'LocatieCodeVan', 'LocatieCodeNaar')); /* (20701) Ongeldige combinatie: %1! */
  end if;

  if @_LocBlokkade = 1 then
    //Locatie is geblokkeerd voor het plaatsen van artikelen!
    call Raise(20780,'LocatieCodeNaar', _U('locatie is geblokkeerd voor het plaatsen van artikelen'));     // (20780) %1! niet mogelijk: %2!
  end if;

  /* Verplaatsing regel toevoegen */
  insert into tab_KingMobile_BulkGrijp with auto name
  select @_AantalTeVerplaatsen    as KmBgAantalTeVerplaatsen,
         @_AantalDecAantallen     as KmBgArtAantDecAantallen,
         @_ArtCode                as KmBgArtCode,
         @_ArtGid                 as KmBgArtGid,
         @_ArtOms                 as KmBgArtOms,
         @_ArtIsPartijRegistreren as KmBgArtIsPartijRegistreren,
         @_ArtPartijNummer        as KmBgArtPartijnummer,
         @_ArtPartijGid           as KmBgArtPartijGid,
         @VerpaktPer              as KmBgArtVerpaktPer,
         @CategorieCode           as KmBgCatCode,
         @CategorieOmschrijving   as KmBgCatOms,
         /* Van */
         @_MagCodeVan             as KmBgMagCodeBulk,
         @_MagGidVan              as KmBgMagGidBulk,
         @_LocNaamVan             as KmBgLocNaamBulk,
         @_LocGidVan              as KmBgLocGidBulk,
         /* Naar */
         @_MagCodeNaar            as KmBgMagCodeGrijp,
         @_MagGidNaar             as KmBgMagGidGrijp,
         @_LocNaamNaar            as KmBgLocNaamGrijp,
         @_LocGidNaar             as KmBgLocGidGrijp,
         0                        as KmBgStatus; /* 0 = status nieuw */

  /* Output */
  select @@Identity as VerplaatsingId;

end;


create or replace procedure WebSvcProc_Verplaatsing_Verwijderen
(
  in @VerplaatsingId      integer,
  in @CategorieCode       nchar(20)
)
begin

  declare @_KmBgGid       integer;
  declare @_CategorieCode nchar(20);
  declare @_KmBgStatus    smallint;

  /* Module/optie Meerdere Magazijen en locaties actief */
  if IsModuleActive( 'm1' ) = 0 then
    call Raise(20790 , _U('Optie Meerdere magazijnen en magazijnlocaties')) ; /* (20790) <Optie/Module> niet geactiveerd! */
  end if;

  /********************************/
  /*** Controle verplichte velden**/
  /********************************/

  if (@VerplaatsingId is not null) and (@CategorieCode is not null) then
    call Raise(20701, _U('%1! en %2! mogen niet beide ingevuld zijn!', 'VerplaatsingId', 'CategorieCode')); /* (20701) Ongeldige combinatie: %1! */
  end if;

  if (@VerplaatsingId is not null) then
    /* Bestaat de opgegeven verplaatsing regel? En welke status heeft deze? */
    select KmBgGid,
           KmBgStatus
    into   @_KmBgGid,
           @_KmBgStatus
    from   tab_KingMobile_BulkGrijp
    where  KmBgGid = @VerplaatsingId;

    if (@_KmBgGid is null) then
      call Raise(20720, 'VerplaatsingId'); /* (20720) niet gevonden: %1! */
    end if;

    if (@_KmBgStatus <> 0) then
      call Raise(20760, _U('Verplaatsingregel heeft niet status 0 - Nieuw')); /* (20760) Ongeldige status: %1!; */
    end if;
  end if;

  if (@CategorieCode is not null) then
    /* Bestaat er een verplaatsing regel met de CategorieCode? */

    select first KmBgCatCode,      KmBgStatus
    into         @_CategorieCode,  @_KmBgStatus
    from   tab_KingMobile_BulkGrijp
    where  KmBgCatCode = @CategorieCode
    order by KmBgStatus asc; /* 0 = nieuw  als eerste record */

    if (@_CategorieCode is null) then
      call Raise(20720, 'CategorieCode'); /* (20720) niet gevonden: %1! */
    end if;

    if (@_KmBgStatus <> 0) then
      call Raise(20760, _U('Geen verplaatsingregels met status 0 - Nieuw')); /* (20760) Ongeldige status: %1!; */
    end if;
  end if;

  /***************************************/
  /*** Verplaatsing Regels verwijderen ***/
  /***************************************/
  begin
    /* o.b.v. Verplaatsing ID */
    if ( @_KmBgGid is not null) then
      if exists  ( select first 1
                          from qtablock
                          where qlockTableName = 'tab_KingMobile_BulkGrijp'
                            and qlockPkey = string(@_KmBgGid)
                  ) then
        call Raise(20741,_U('Verplaatsingregel')); /* (20741) %1 is in gebruik! */
      end if;

      /* niet gelockt, meteen verwijderen */
      delete tab_KingMobile_BulkGrijp
      where KmBgStatus = 0  /* Nieuw */
        and KmBgGid = @_KmBgGid;

    end if; // Verplaatsing ID

    /* o.b.v. Categorie Code */
    if (@_CategorieCode is not null) then
      delete tab_KingMobile_BulkGrijp
      where KmBgStatus = 0  /* Nieuw */
        and KmBgCatCode = @_CategorieCode
        and not exists  ( select first 1
                          from qtablock
                          where qlockTableName = 'tab_KingMobile_BulkGrijp'
                            and qlockPkey = string(KmBgGid)
                        );
      /* er is niks verwijderd? */
      if @@ROWCOUNT = 0 then
        call Raise(20780, _U('Verwijderen'),_U('Regels in gebruik, of ze hebben geen status 0 - Nieuw')) ; /*  <Actie> niet mogelijk: <Reden> */
      end if;

    end if; // Categorie Code
  end; // verplaatsings regels verwijderen
end;




create or replace procedure WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken
( in @LockVvokGid integer,
  in @LockUserNaam nchar(40) default null,
  in @SpId integer default null,
  in @LoginTime datetime default null,
  in @LockSoort smallint default 1 // 0 = readlock/shared lock,
                                   // 1 = writelock/exclusive lock
)
begin
  declare @_LockResult integer;

  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabVoorraadVerplaatsingsOpdrachtKop';

  //call TraceBegin('WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtExclusiefLocken > @LockVvokGid = ' + @LockVvokGid);

  // Defaults instellen
  if @LockUserNaam is null then
    set @LockUserNaam = 'KingWebservice';
  end if;
  if @SpId is null then
    set @SpId = @@SpId;
  end if;
  if @LoginTime is null then
    set @LoginTime = @@LoginTime;
  end if;

  if not exists(select first 1 from tabVoorraadVerplaatsingsOpdrachtKop where vvokGid = @LockVvokGid ) then
    call Raise(20780, _U('In gebruik nemen'), _U('voorraadverplaatsingsopdracht niet gevonden')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  //Als er geen exclusive lock is of je wil een shared lock.
  if (LockedById(@SpId, @LoginTime, 1 /*exclusieve lock*/, _QLOCKTABLENAME, @LockVvokGid) = 0) or (@LockSoort = 0 /*shared lock*/) then
    // locken, met standaard King 5 procedure
    call LockSetOnId( @Spid,
                      @LoginTime,
                      @LockSoort, //1 = Exclusieve lock, 0 = ReadLock
                      _QLOCKTABLENAME,  //tabel waarin record te locken is - nchar(40)
                      string(@LockVvokGid), //lockstring voor record, nchar(80)
                      @_LockResult, //0 = OK, anders fout
                      0, // Automatisch opruimen: 0 = nee, 1 = ja
                      @LockUserNaam); //Welke King gebruiker of proces

    if @_LockResult <> 0 then
      call Raise(20741,_U('voorraadverplaatsingsopdracht')); // (20741) %1 is in gebruik!
    end if;
  end if;
  //call TraceEind('WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtExclusiefLocken > @LockVvokGid = ' + @LockVvokGid);
end;



create or replace procedure WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken
( in @LockVvorGid integer,
  in @LockUserNaam nchar(40) default null,
  in @SpId integer default null,
  in @LoginTime datetime default null,
  in @LockSoort smallint default 1 // 0 = readlock/shared lock,
                                   // 1 = writelock/exclusive lock
)
begin
  declare @_LockResult integer;
  declare @_LockVvokGid integer;

  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabVoorraadVerplaatsingsOpdrachtRegel';

  //call TraceBegin('WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken > @LockVvorGid = ' + @LockVvorGid);

  // Defaults instellen
  if @LockUserNaam is null then
    set @LockUserNaam = 'KingWebservice';
  end if;
  if @SpId is null then
    set @SpId = @@SpId;
  end if;
  if @LoginTime is null then
    set @LoginTime = @@LoginTime;
  end if;

  if not exists(select first 1 from tabVoorraadVerplaatsingsOpdrachtRegel where vvorGid = @LockVvorGid ) then
    call Raise(20780, _U('In gebruik nemen'), _U('voorraadverplaatsingsopdrachtregel niet gevonden')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  select vvorVvokGid into @_LockVvokGid from tabVoorraadVerplaatsingsOpdrachtRegel where vvorGid = @LockVvorGid;

  //Als er een exclusive lock op de kop zit hoeft er geen regel lock aangemaakt te worden
  if LockedById(@SpId, @LoginTime, 1 /*exclusieve lock*/, 'tabVoorraadVerplaatsingsOpdrachtKop', @_LockVvokGid) = 0  then
    //Als er geen exclusive lock is of je wil een shared lock.
    if (LockedById(@SpId, @LoginTime, 1 /*exclusieve lock*/, _QLOCKTABLENAME, @LockVvorGid) = 0)  or (@LockSoort = 0 /*shared lock*/) then
      // locken, met standaard King 5 procedure
      call LockSetOnId( @Spid,
                        @LoginTime,
                        @LockSoort, // 1 = Exclusieve lock, 0 = ReadLock
                        _QLOCKTABLENAME,  // tabel waarin record te locken is - nchar(40)
                        string(@LockVvorGid),          // lockstring voor record, nchar(80)
                        @_LockResult,                 // 0 = OK, anders fout
                        0,                            // Automatisch opruimen: 0 = nee, 1 = ja
                        @LockUserNaam);               // Welke King gebruiker of proces

      if @_LockResult <> 0 then
        call Raise(20741,_U('voorraadverplaatsingsopdrachtregel'));    // (20741) %1 is in gebruik!
      end if;
    end if;
  end if;

  //call TraceEind('WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken > @LockVvorGid = ' + @LockVvorGid);
end;



create or replace procedure WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegel_ToevoegenTussenvoegen
( in @Actie smallint default 0, //0 = Toevoegen, 1 = Tussenvoegen (met opschuiven) 2 = Wijzigen
  in @Nummer numeric(10,0) default null,
  in @RegelNummer integer default null,
  in @Status nchar(20)  default null, /* Waarden 'CONCEPT', 'KLAARVOORVERPLAATSEN', 'TOEGEWEZEN', 'ONDERHANDEN' */
  in @ScannerToegewezenAan nchar(20) default null,
  in @TenBehoeveVan nchar(12)  default null, /* Waarden: 'VERPLAATSING', 'VERKOOPORDER' */
  in @OrderNummer	Numeric(10,0),
  in @OrderRegelNummer	Numeric(5,0),
  in @ArtikelNummer nchar(20) default null,
  in @PartijNummer nchar(20) default null,
  in @VanMagazijn numeric(3,0) default null,
  in @VanLocatie nchar(20) default null,
  in @NaarMagazijn numeric(3,0) default null,
  in @NaarLocatie nchar(20) default null,
  in @AantalTeVerplaatsen numeric(15,3) default null,
  in @AantalVerplaatst numeric(15,3) default null,
  in @Kenmerk nchar(40) default null,
  in @MutatieOmschrijving nchar(40) default null,
  in @Opmerking long nvarchar default null)
result (VoorraadVerplaatsingsOpdrachtRegelNummer integer,
        VoorraadVerplaatsingsOpdrachtRegelID integer)
begin
  // Constanten
  declare _ACTIE_TOEVOEGEN    smallint = 0;
  declare _ACTIE_TUSSENVOEGEN smallint = 1;
  declare _ACTIE_WIJZIGEN smallint = 2;

  declare _qcNEE smallint = 0;
  declare _qcJA smallint = 1;

  // Variabelen
  declare @_vvorActie smallint default _ACTIE_TOEVOEGEN; /*Toevoegen*/
  declare @_vvokGid integer;
  declare @_vvokStatus smallint = null;
  declare @_vvorGid integer;
  declare @_VvorRegelnummer integer;
  declare @_vvorStatus smallint = 0;
  declare @_VvorTenBehoeveVan smallint = 0;
  declare @_VvorOrrGidtbv integer = null;
  declare @_VvorArtGid integer = null;
  declare @_VvorArtPartijGid integer = null;
  declare @_VvorMagGidVan integer = null;
  declare @_VvorLocGidVan integer = null;
  declare @_VvorMagGidNaar integer = null;
  declare @_VvorLocGidNaar integer = null;
  declare @_VvorAantalInVrrdEenh numeric(15,3) = 0;
  declare @_VvorAantalVerwerktInVrrdEenh numeric(15,3) = 0;
  declare @_vvorAantalGereserveerdInVanLocInVrrdEenh numeric(15,3) = 0;
  declare @_ApartePartijNummersNietToegestaan smallint;
  declare @_OrrArtPartijGid integer = null;
  declare @_OldPartijGid integer = null;

  //call TraceBegin('WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegel_ToevoegenTussenvoegen');

  // Controle actie
  if (@Actie is not null) then
    if @Actie not in (_ACTIE_TOEVOEGEN, _ACTIE_TUSSENVOEGEN, _ACTIE_WIJZIGEN) then
      call Raise(20700, _U('Actie, waarde: null, 0, 1, 2 toegestaan')); // Ongeldige waarde: %1
    end if;

    set @_vvorActie = @Actie;
  end if;

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = _qcNEE then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if @_vvokGid is null then
    call Raise(20720, 'Nummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_vvokStatus = 9 /*Verwerkt*/) and (@_vvorActie <> _ACTIE_WIJZIGEN) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel toevoegen'),_U('opdracht is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  //Controle Regelnummer
  if @_vvorActie = _ACTIE_TUSSENVOEGEN and @RegelNummer is not null and @RegelNummer <= 0 then
    call Raise(20700, 'RegelNummer');  // (20700) Ongeldige waarde: %1!
  else
    if @_vvorActie = _ACTIE_WIJZIGEN then
      //Ophalen van de huidige gegevens
      select vvorGid, vvorStatus, VvorTenBehoeveVan, VvorOrrGidtbv, VvorArtGid, VvorArtPartijGid, VvorMagGidVan, VvorLocGidVan, VvorMagGidNaar, VvorLocGidNaar, VvorAantalInVrrdEenh, VvorAantalVerwerktInVrrdEenh
      into @_vvorGid, @_vvorStatus, @_VvorTenBehoeveVan, @_VvorOrrGidtbv, @_VvorArtGid, @_vvorArtPartijGid, @_VvorMagGidVan, @_VvorLocGidVan, @_VvorMagGidNaar, @_VvorLocGidNaar, @_VvorAantalInVrrdEenh, @_VvorAantalVerwerktInVrrdEenh
      from tabvoorraadVerplaatsingsOpdrachtRegel
      where vvorVvokGid = @_vvokGid
        and vvorRegelnummer = @RegelNummer;

      if @_vvorGid is null then
        call Raise(20720, 'RegelNummer');  // (20720) %1! niet gevonden!
      end if;

      if (@_vvorStatus in (2 /*Toegewezen*/, 3 /*Onderhanden*/, 9 /*Verwerkt*/)) then
        //Als de status toegewezen of onderhanden is kun je alleen Partijnummer, naar magazijn, naar locatie, verplaatst en de opmerking nog wijzigen.
        //Toegewezen aan mag ook mits de oude status concept of klaar voor verplaatsen was.
        if isNull(@Status,'') not in ('CONCEPT', 'KLAARVOORVERPLAATSEN') then
          set @ScannerToegewezenAan = null;
          set @TenBehoeveVan = null;
          set @OrderNummer = null;
          set @OrderRegelNummer = null;
          set @ArtikelNummer = null;
          set @VanMagazijn = null;
          set @VanLocatie = null;
          set @AantalTeVerplaatsen = null;
          set @Kenmerk = null;
          set @MutatieOmschrijving = null;
        end if;

        if (@_vvorStatus = 9 /*Verwerkt*/) then
          //Als de status verwerkt is kun je alleen de opmerking nog wijzigen.
          set @Status = null;
          set @ScannerToegewezenAan = null;
          set @PartijNummer = null;
          set @NaarMagazijn = null;
          set @NaarLocatie = null;
          set @AantalVerplaatst = null;
        end if;
      end if;
    end if;
  end if;

  // Controle Status: moet 'CONCEPT', 'KLAARVOORVERPLAATSEN', 'TOEGEWEZEN' of 'ONDERHANDEN' zijn.
  case
    when @Status is null and (@_vvorActie = _ACTIE_WIJZIGEN) then set @_vvorStatus = null;
    when isnull(@Status,'CONCEPT') = 'CONCEPT' then set @_vvorStatus = 0;
    when isnull(@Status,'') = 'KLAARVOORVERPLAATSEN' then set @_vvorStatus = 1;
    when isnull(@Status,'') = 'TOEGEWEZEN' then set @_vvorStatus = 2;
    when isnull(@Status,'') = 'ONDERHANDEN' then set @_vvorStatus = 3;
    else call Raise(20700, 'Status');   // (20700) Ongeldige waarde: %1!
  end case;

  // Controle TenBehoeveVan: moet 'VERPLAATSING' of 'VERKOOPORDER' zijn.
  if not(@TenBehoeveVan is null and (@_vvorActie = _ACTIE_WIJZIGEN)) then
    case
      when isnull(@TenBehoeveVan,'VERPLAATSING') = 'VERPLAATSING' then set @_VvorTenBehoeveVan = 0;
      when isnull(@TenBehoeveVan,'') = 'VERKOOPORDER' then set @_VvorTenBehoeveVan = 1;
      else call Raise(20700, 'TenBehoeveVan');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  if (@_VvorTenBehoeveVan = 1 /*VERKOOPORDER*/) then
    if (@_vvorActie <> _ACTIE_WIJZIGEN) or ((@Ordernummer is not null) and (@OrderRegelNummer is not null)) then
    begin
      declare @_OrrAantalLeveringVrrdEenh numeric(15,3);
      declare @_OrkGoedgekeurd smallint;
      declare @_OrrArtGid integer = null;

      set @_VvorOrrGidtbv = null;

      //Ordernummer check
      if isNull(@OrderNummer, '') = '' then
        call Raise(20700,'OrderNummer'); // (20700) Ongeldige waarde: %1!
      end if;

      //OrderRegelNummer check
      if isNull(@OrderRegelNummer, '') = '' then
        call Raise(20700,'OrderRegelNummer'); // (20700) Ongeldige waarde: %1!
      end if;

      select OrrGid, OrrArtGid, OrrArtPartijGid, OrrAantalLeveringVrrdEenh, OrkGoedgekeurd
      into @_VvorOrrGidtbv, @_OrrArtGid, @_OrrArtPartijGid, @_OrrAantalLeveringVrrdEenh, @_OrkGoedgekeurd
      from tabOrderRegel
      inner join tabOrderKop on OrkGid = OrrOrkGid
      inner join tabArtikel on ArtGid = OrrArtGid
      where OrkNummer = @OrderNummer
        and OrrRegelNr = @OrderRegelNummer
        and OrrRegelsoort = 2; /*Artikel*/

      if @_VvorOrrGidtbv is null then
        call Raise(20720, 'OrderNummer/OrderRegelNummer'); //(20720) %1! niet gevonden!
      end if;

      if @_OrrAantalLeveringVrrdEenh <= 0 then
        call Raise(20780, 'OrderNummer/OrderRegelNummer', _U('Aantal deze levering moet groter dan 0 zijn')); //(20780) %1! niet mogelijk: %2!
      end if;

      if @_OrkGoedgekeurd = _qcNEE then
        call Raise(20780, 'OrderNummer/OrderRegelNummer', _U('Order is niet goedgekeurd')); //(20780) %1! niet mogelijk: %2!
      end if;

      //Controle of het artikel overeenkomt met het artikel in de orderregel
      if isNull(@ArtikelNummer, '') <> '' then
        set @_VvorArtGid = null;

        select ArtGid into @_VvorArtGid from tabArtikel where ArtCode = @ArtikelNummer and ArtSoort = 2 /*Artikel*/;

        if @_VvorArtGid is null then
           call Raise(20720,'ArtikelNummer'); // (20720) %1! niet gevonden!
        end if;

        if @_VvorArtGid <> @_OrrArtGid then
          call Raise(20780, 'OrderNummer/OrderRegelNummer', _U('Artikelnummer komt niet overeen met de orderregel')); //(20780) %1! niet mogelijk: %2!
        end if;
      else
        set @_VvorArtGid = @_OrrArtGid
      end if;

      if (@_vvorActie <> _ACTIE_WIJZIGEN) then
        //Bij het toevoegen van de verplaatsingsregel de partij van de order gebruiken mits dat er 1 is.
        if (select count(distinct isNull(OrlArtPartijGid, OrrArtPartijGid)) from tabOrderRegel left outer join tabOrderRegelLocatie on OrlOrrGid = orrGid where orrGid = @_VvorOrrGidtbv) = 1 then
          select distinct isNull(OrlArtPartijGid, OrrArtPartijGid) as PartijGid
          into @_VvorArtPartijGid
          from tabOrderRegel
          left outer join tabOrderRegelLocatie on OrlOrrGid = orrGid
          where PartijGid is not null
            and orrGid = @_VvorOrrGidtbv;
        end if;

        //Van magazijn/locatie gebruiken van de order mits dat er 1 is.
        if (select count(distinct OrlMagGid) from tabOrderRegelLocatie where OrlOrrGid = @_VvorOrrGidtbv) = 1 then
          select distinct OrlMagGid into @_VvorMagGidVan from tabOrderRegelLocatie where OrlOrrGid = @_VvorOrrGidtbv;
        end if;

        if (select count(distinct OrlLocGid) from tabOrderRegelLocatie where OrlOrrGid = @_VvorOrrGidtbv) = 1 then
          select distinct OrlLocGid into @_VvorLocGidVan from tabOrderRegelLocatie where OrlOrrGid = @_VvorOrrGidtbv;
        end if;

        //En het aantal deze levering
        select SUM(OrlDezeLeveringVrrdEenh) into @_VvorAantalInVrrdEenh
        from tabOrderRegelLocatie
        where OrlOrrGid = @_VvorOrrGidtbv;
      end if;
    end;
    else
      if @_VvorOrrGidtbv is null then
        call Raise(20720, 'OrderNummer/OrderRegelNummer'); //(20720) %1! niet gevonden!
      end if;
    end if;
  else /*Verplaatsing*/
    set @_VvorOrrGidtbv = null;
    // Controle ArtikelNummer: Indien is meegegeven, dan moet dit een bestaand artikel zijn.
    if (@_vvorActie <> _ACTIE_WIJZIGEN) or ((@_VvorTenBehoeveVan = 0 /*Verplaatsing*/) and @ArtikelNummer is not null) then
      if isnull(@ArtikelNummer,'') <> '' then
        set @_VvorArtGid = null;
        select ArtGid into @_VvorArtGid from tabArtikel where ArtCode = @ArtikelNummer and ArtSoort = 2 /*Artikel*/;
      end if;

      if @_VvorArtGid is null then
         call Raise(20720,'ArtikelNummer'); // (20720) %1! niet gevonden!
      end if;
    end if;
  end if;

  //Controle Partij
  if @PartijNummer is not null then
    set @_OldPartijGid = @_VvorArtPartijGid;
    set @_VvorArtPartijGid = null;

    //Alleen als je niet tenbehoevevan een verkooporder bent en een aparte partij is niet toegestaan
    select 1 into @_ApartePartijNummersNietToegestaan
    from tabArtikel
    where ArtGid = @_VvorArtGid
      and ArtIsPartijRegistreren = _qcJA
      and (ArtIsPartijAparteKostPrijs = _qcJA or ArtIsPartijAparteVerkoopPrijs = _qcJA);

    select ArtPartijGid into @_VvorArtPartijGid from tabArtikelPartij where ArtPartijNummer = @PartijNummer and ArtPartijArtGid = @_VvorArtGid /*Artikel*/;

    if @_VvorArtPartijGid is null then
       call Raise(20720,'PartijNummer'); // (20720) %1! niet gevonden!
    end if;

    if (@TenBehoeveVan = 'VERKOOPORDER') and (isNull(@_ApartePartijNummersNietToegestaan, _qcNee) = _qcJa) and (@_VvorArtPartijGid <> @_OrrArtPartijGid) then
      call Raise(20780, 'PartijNummer', _U('Partij mag niet afwijken van de partij van de verkooporder')); //(20780) %1! niet mogelijk: %2!
    end if;

    //Is partij geblokkeerd voor verkoop en deze staat niet in de order geef een melding..
    if (@TenBehoeveVan = 'VERKOOPORDER') and exists(select 1 from tabartikelpartij where artPartijGid = @_VvorArtPartijGid and ArtPartijIsGeblokkeerdVoorVerkoop = _qcJA) then
      //Als de partij in de verkooporder staat mag hij wel geblokkeerd zijn.
      if exists(select 1 from taborderregel left outer join tabOrderRegelLocatie on OrlOrrGid = orrGid where orrgid = @_VvorOrrGidtbv and @_VvorArtPartijGid not in (OrlArtPartijGid, OrrArtPartijGid)) and (@_VvorArtPartijGid <> @_OldPartijGid) then
        call Raise(20780, 'PartijNummer', _U('Partij is geblokkeerd voor verkoop')); //(20780) %1! niet mogelijk: %2!
      end if
    end if;
  else
    //vul eventueel partijgid met standaard partij als niet partijregistrerend maar wel serienummerregistrerend
    if (@_vvorActie <> _ACTIE_WIJZIGEN) and exists(select 1 from tabArtikel where ArtGid= @_VvorArtGid and ArtSerieNrRegistreren = 1 and ArtIsPartijRegistreren = 0) then
      select ArtPartijGid into @_VvorArtPartijGid from tabArtikelPartij where ArtPartijNummer = '(Standaard)' and ArtPartijArtGid = @_VvorArtGid /*Artikel*/;
    end if;
  end if;

  //Controle van magazijn/locatie
  if @VanMagazijn is not null then
    set @_VvorMagGidVan = null;
    select MagGid into @_VvorMagGidVan from tabMagazijn where MagCode = @VanMagazijn
  end if;

  if (@_VvorMagGidVan is null) then
    call Raise(20700,'VanMagazijn'); // (20700) Ongeldige waarde: %1!
  end if;

  if @VanLocatie is not null then
    set @_VvorLocGidVan = null;
    select locGid into @_VvorLocGidVan from tabLocatie where LocMagGid = @_VvorMagGidVan and LocNaam = @VanLocatie;
  end if;

  if (@_VvorLocGidVan is null) or exists(select 1 from tabLocatie where LocMagGid <> @_VvorMagGidVan and LocGid =  @_VvorLocGidVan) then
    call Raise(20700,'VanLocatie'); // (20700) Ongeldige waarde: %1!
  end if;

  //Controle naar magazijn/locatie
  if @NaarMagazijn is not null then
    select MagGid into @_VvorMagGidNaar from tabMagazijn where MagCode = @NaarMagazijn
  else
    if (@_vvorActie <> _ACTIE_WIJZIGEN) then
      //Als naar magazijn leeg is, vul dan het van magazijn in.
      set @_VvorMagGidNaar = @_VvorMagGidVan;
    end if;
  end if;

  if @_VvorMagGidNaar is null then
    call Raise(20700,'NaarMagazijn'); // (20700) Ongeldige waarde: %1!
  end if;

//  if (isNull(@NaarLocatie,'') <> '') then
  if @NaarLocatie is not null then
    set @_VvorLocGidNaar = null;
    select locGid into @_VvorLocGidNaar from tabLocatie where LocMagGid = @_VvorMagGidNaar and LocNaam = @NaarLocatie;

    if @_VvorLocGidNaar is null then /*or exists(select 1 from tabLocatie where LocMagGid <> @_VvorMagGidNaar and LocGid =  @_VvorLocGidNaar) then*/
      call Raise(20700,'NaarLocatie'); // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  if @_VvorLocGidNaar is not null and exists(select 1 from tabLocatie where LocMagGid <> @_VvorMagGidNaar and LocGid =  @_VvorLocGidNaar) then
    call Raise(20700,'NaarLocatie'); // (20700) Ongeldige waarde: %1!
  end if;

  //Controle Aantal te verplaatsen
  if @AantalTeVerplaatsen is not null then
    set @_VvorAantalInVrrdEenh = @AantalTeVerplaatsen;
  end if;

  if IsNull(@_VvorAantalInVrrdEenh,0) <= 0 then
    call Raise(20700,'AantalTeVerplaatsen'); // (20700) Ongeldige waarde: %1!
  end if;

  //Check het aantal decimalen
  begin
    declare @_ArtAantDecAantallen smallint;
    declare @_CheckDecimalen numeric(15,3);

    select ArtAantDecAantallen into @_ArtAantDecAantallen from tabArtikel where ArtGid = @_VvorArtGid and ArtSoort = 2 /*Artikel*/;
    set @_CheckDecimalen = truncnum(@_VvorAantalInVrrdEenh,@_ArtAantDecAantallen);

    if  (@_CheckDecimalen - @_VvorAantalInVrrdEenh) <> 0 then
      call Raise(20780, 'AantalTeVerplaatsen', _U('Er zijn teveel decimalen meegegeven!'));   // (20780) %1! niet mogelijk: %2!
    end if;
  end;

  //Veld gelijkstellen aan aantal te verplaatsen als het een verplaatsingsregel is
  if (@_VvorTenBehoeveVan = 0 /*Verplaatsing*/) then
    set @_vvorAantalGereserveerdInVanLocInVrrdEenh = @_VvorAantalInVrrdEenh;
  end if;

  //Controle aantal verplaatst
  set @_VvorAantalVerwerktInVrrdEenh = isNull(@AantalVerplaatst, @_VvorAantalVerwerktInVrrdEenh);

  if IsNull(@_VvorAantalVerwerktInVrrdEenh, 0) < 0 then
      call Raise(20700,'AantalVerplaatst'); // (20700) Ongeldige waarde: %1!
  end if;

  if IsNull(@_VvorAantalVerwerktInVrrdEenh, 0) > @_VvorAantalInVrrdEenh then
    call Raise(20780,'AantalVerplaatst', _U('Aantal verplaatst mag niet groter zijn dan het aantal te verplaatsen')); //(20780) %1! niet mogelijk: %2!
  end if;

  begin
    declare @_ArtAantDecAantallen smallint;
    declare @_CheckDecimalen numeric(15,3);

    select ArtAantDecAantallen into @_ArtAantDecAantallen from tabArtikel where ArtGid = @_VvorArtGid and ArtSoort = 2 /*Artikel*/;
    set @_CheckDecimalen = truncnum(@_VvorAantalVerwerktInVrrdEenh,@_ArtAantDecAantallen);

    if  (@_CheckDecimalen - @_VvorAantalVerwerktInVrrdEenh) <> 0 then
      call Raise(20780,'AantalVerplaatst',_U('Er zijn teveel decimalen meegegeven!'));   // (20780) %1! niet mogelijk: %2!
    end if;
  end;

  begin atomic // Dit moet, want lock moet hierna nog erop en daar kan het nog fout gaan
    // Opdracht shared locken of bestaande lock overnemen
    // T.b.v. locken
    declare @_LockUserNaam nchar(40) = 'KingWebService';
    declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId       wordt gebruikt
    declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt

    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, @_LockUserNaam, @_Spid, @_LoginTime, 0 /*Shared*/);

    if (@_vvorActie <> _ACTIE_WIJZIGEN) then
      // Controle Regelnummer
      if @_vvorActie = _ACTIE_TUSSENVOEGEN and @RegelNummer is not null then
        if exists(select 1 from tabvoorraadVerplaatsingsOpdrachtRegel where vvorVvokGid = @_vvokGid and vvorRegelnummer = @RegelNummer) then
          //Tussenvoegen
          call VoorraadVerplaatsingsOpdrachtRegelpositieVerschuiven(@_vvokGid, @RegelNummer, null, 1, @_LockUserNaam);
        end if;

        set @_VvorRegelnummer = @RegelNummer;
      else
        select IsNull(max(vvorRegelnummer),0) + 1 into @_VvorRegelnummer
        from tabvoorraadVerplaatsingsOpdrachtRegel
        where vvorVvokGid = @_vvokGid
      end if;

      insert into tabVoorraadVerplaatsingsOpdrachtRegel with auto name
      select
        @_vvokGid VvorVvokGid,
        @_VvorRegelnummer VvorRegelnummer,
        @_vvorStatus VvorStatus,
        isNull(@ScannerToegewezenAan,'') VvorScannerToegewezenAan,
        @_VvorTenBehoeveVan VvorTenBehoeveVan,
        @_VvorOrrGidTbv VvorOrrGidTbv,
        @_VvorArtGid VvorArtGid,
        @_vvorArtPartijGid VvorArtPartijGid,
        @_VvorMagGidVan VvorMagGidVan,
        @_VvorLocGidVan VvorLocGidVan,
        @_VvorMagGidNaar VvorMagGidNaar,
        @_VvorLocGidNaar VvorLocGidNaar,
        @_VvorAantalInVrrdEenh VvorAantalInVrrdEenh,
        @_VvorAantalVerwerktInVrrdEenh VvorAantalVerwerktInVrrdEenh,
        @_vvorAantalGereserveerdInVanLocInVrrdEenh vvorAantalGereserveerdInVanLocInVrrdEenh,
        @Kenmerk VvorKenmerk,
        @MutatieOmschrijving VvorMutOmschrijving,
        @Opmerking VvorOpm,
        0 VvorLocGebloktToestaan;

      set @_vvorGid = @@Identity;
    else
      call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken(@_vvorGid, @_LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusive*/);

      update tabVoorraadVerplaatsingsOpdrachtRegel
      set VvorStatus = isNull(@_vvorStatus, VvorStatus),
          VvorScannerToegewezenAan = isNull(@ScannerToegewezenAan, VvorScannerToegewezenAan) ,
          VvorTenBehoeveVan = isNull(@_VvorTenBehoeveVan, VvorTenBehoeveVan),
          VvorOrrGidTbv = isNull(@_VvorOrrGidTbv, if @_VvorTenBehoeveVan = 1 then VvorOrrGidTbv else null endif),
          VvorArtGid = isNull(@_VvorArtGid, VvorArtGid),
          VvorArtPartijGid = isNull(@_vvorArtPartijGid, VvorArtPartijGid),
          VvorMagGidVan = isNull(@_VvorMagGidVan, VvorMagGidVan),
          VvorLocGidVan = isNull(@_VvorLocGidVan, VvorLocGidVan),
          VvorMagGidNaar = isNull(@_VvorMagGidNaar, VvorMagGidNaar),
          VvorLocGidNaar = isNull(@_VvorLocGidNaar, VvorLocGidNaar),
          VvorAantalInVrrdEenh = isNull(@_VvorAantalInVrrdEenh, VvorAantalInVrrdEenh),
          VvorAantalVerwerktInVrrdEenh = isNull(@_VvorAantalVerwerktInVrrdEenh, VvorAantalVerwerktInVrrdEenh),
          vvorAantalGereserveerdInVanLocInVrrdEenh = isNull(@_vvorAantalGereserveerdInVanLocInVrrdEenh, vvorAantalGereserveerdInVanLocInVrrdEenh),
          VvorKenmerk = isNull(@Kenmerk, VvorKenmerk),
          VvorMutOmschrijving = isNull(@MutatieOmschrijving, VvorMutOmschrijving),
          VvorOpm = isNull(@Opmerking, VvorOpm)
      where vvorGid = @_vvorGid;

      //Gooi alle Serienummers weg die niet bij de nieuwe partij horen
      if @_VvorArtPartijGid is not null then
        delete from tabVoorraadVerplaatsingsOpdrachtSN
        where VvosVvorGid = @_vvorGid
          and vvosArtSerieGid not in (select ArtSerieGid from tabArtikelSerienummer where ArtSeriePartijGid = @_VvorArtPartijGid)
      end if;

      //De exclusive lock vrijgeven
      call WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(@Nummer, @RegelNummer,  1 /*Exclusive lock*/);
    end if;

    //De shared lock vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, 0 /*Shared lock*/);
  end; //atomic

  // resultaat terug geven
  select VvorRegelnummer as VoorraadVerplaatsingsOpdrachtRegelNummer,
         vvorGid as VoorraadVerplaatsingsOpdrachtRegelID
  from tabVoorraadVerplaatsingsOpdrachtRegel
  where vvorGid = @_vvorGid;

  //call TraceEind('WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegel_ToevoegenTussenvoegen');
end;


create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdrachtRegelSerienummer_Toevoegen
( in @Nummer numeric(10,0) default null,
  in @RegelNummer integer default null,
  in @SerieNummer nchar(20) default null
)
begin
  // Constanten
  declare _qcNEE smallint = 0;

  // Variabelen
  declare @_vvokGid integer;
  declare @_vvokStatus smallint;
  declare @_vvorGid integer = null;
  declare @_vvorStatus smallint = null;
  declare @_ArtSerieNrRegistreren smallint = 0;
  declare @_VvosArtSerieGid integer = null;
  declare @_SerieNummerVanAnderePartij smallint = 1;

  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegelSerienummer_Toevoegen');

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = _qcNEE then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Module: Serienummers
  if IsModuleActive('s1') = _qcNEE  then
     call Raise(20790,_U('Optie Serienummers')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if @_vvokGid is null then
    call Raise(20720, 'Nummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_vvokStatus = 9 /*Verwerkt*/) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregelserienummer toevoegen'),_U('opdracht is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  //Ophalen van de huidige gegevens
  select vvorGid, vvorStatus, ArtSerieNrRegistreren, ArtSerieGid, (if isNull(VvorArtPartijGid,-1) = ArtSeriePartijGid then 1 else 0 endif)
  into @_vvorGid, @_vvorStatus, @_ArtSerieNrRegistreren, @_VvosArtSerieGid, @_SerieNummerVanAnderePartij
  from tabvoorraadVerplaatsingsOpdrachtRegel
  inner join (tabArtikel left outer join tabArtikelSerienummer on ArtSerieArtGid = ArtGid and ArtSerieNummer = @SerieNummer) on ArtGid = vvorArtGid
  where vvorVvokGid = @_vvokGid
    and vvorRegelnummer = @RegelNummer;

  if (@_vvorGid is null) then
    call Raise(20720, 'RegelNummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_vvorStatus = 9 /*Verwerkt*/) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregelserienummer toevoegen'),_U('regel is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if (@_ArtSerieNrRegistreren = 0) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregelserienummer toevoegen'),_U('Artikel is niet serienummer registrerend')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if @_VvosArtSerieGid is null then
    call Raise(20720, 'Serienummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_SerieNummerVanAnderePartij = 0) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregelserienummer toevoegen'),_U('Serienummer behoort niet tot de ingevulde partij')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if exists(select 1 from tabVoorraadVerplaatsingsOpdrachtSN where VvosVvorGid = @_vvorGid and VvosArtSerieGid = @_VvosArtSerieGid) then
    call Raise(20721, 'Serienummer');  // (20721) %1! komt al voor!
  end if;

  begin atomic // Dit moet, want lock moet hierna nog erop en daar kan het nog fout gaan
    // Opdracht shared locken of bestaande lock overnemen
    // T.b.v. locken
    declare @_LockUserNaam nchar(40) = 'KingWebService';
    declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId       wordt gebruikt
    declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt

    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, @_LockUserNaam, @_Spid, @_LoginTime, 0 /*Shared*/);
    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken(@_vvorGid, @_LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusive*/);

    insert into tabVoorraadVerplaatsingsOpdrachtSN with auto name
    select
      @_VvosArtSerieGid VvosArtSerieGid,
      @_vvorGid VvosVvorGid,
      1 VvosAantal;

    //De locks vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(@Nummer, @RegelNummer,  1 /*Exclusive lock*/);
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, 0 /*Shared lock*/);
  end; //atomic

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegelSerienummer_Toevoegen');
end;


create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdrachtRegelSerienummer_Verwijderen
( in @Nummer numeric(10,0) default null,
  in @RegelNummer integer default null,
  in @SerieNummer nchar(20) default null
)
begin
  // Constanten
  declare _qcNEE smallint = 0;

  // Variabelen
  declare @_vvokGid integer;
  declare @_vvokStatus smallint;
  declare @_vvorGid integer = null;
  declare @_vvorStatus smallint = null;
  declare @_ArtSerieNrRegistreren smallint = 0;
  declare @_VvosArtSerieGid integer = null;
  declare @_vvosGid integer = null;

  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegelSerienummer_Verwijderen');

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = _qcNEE then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Module: Serienummers
  if IsModuleActive('s1') = _qcNEE  then
     call Raise(20790,_U('Optie Serienummers')); // (20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if @_vvokGid is null then
    call Raise(20720, 'Nummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_vvokStatus = 9 /*Verwerkt*/) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregelserienummer verwijderen'),_U('opdracht is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  //Ophalen van de huidige gegevens
  select vvorGid, vvorStatus, ArtSerieNrRegistreren, ArtSerieGid, vvosGid
  into @_vvorGid, @_vvorStatus, @_ArtSerieNrRegistreren, @_VvosArtSerieGid, @_vvosGid
  from tabvoorraadVerplaatsingsOpdrachtRegel
  inner join (tabArtikel left outer join tabArtikelSerienummer on ArtSerieArtGid = ArtGid and ArtSerieNummer = @SerieNummer) on ArtGid = vvorArtGid
  left outer join tabVoorraadVerplaatsingsOpdrachtSN on VvosVvorGid = vvorGid and VvosArtSerieGid = ArtSerieGid
  where vvorVvokGid = @_vvokGid
    and vvorRegelnummer = @RegelNummer;

  if (@_vvorGid is null) then
    call Raise(20720, 'RegelNummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_vvorStatus = 9 /*Verwerkt*/) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregelserienummer verwijderen'),_U('regel is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if (@_ArtSerieNrRegistreren = 0) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregelserienummer verwijderen'),_U('Artikel is niet serienummer registrerend')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if (@_vvosGid is null) then
    call Raise(20720, 'Serienummer');  // (20720) %1! niet gevonden!
  end if;

  begin atomic // Dit moet, want lock moet hierna nog erop en daar kan het nog fout gaan
    // Opdracht shared locken of bestaande lock overnemen
    // T.b.v. locken
    declare @_LockUserNaam nchar(40) = 'KingWebService';
    declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId       wordt gebruikt
    declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt

    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, @_LockUserNaam, @_Spid, @_LoginTime, 0 /*Shared*/);
    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken(@_vvorGid, @_LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusive*/);

    delete from tabVoorraadVerplaatsingsOpdrachtSN where VvosGid = @_vvosGid;

    //De locks vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(@Nummer, @RegelNummer,  1 /*Exclusive lock*/);
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, 0 /*Shared lock*/);
  end; //atomic

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegelSerienummer_Verwijderen');
end;


create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(
  in @Nummer numeric(10,0),
  in @RegelNummer numeric(10,0),
  in @LockSoort smallint default 1, // 0 = readlock/shared lock,
                                   // 1 = writelock/exclusive lock
  in @vvorGid integer default null //Deze wordt bij het verwijderen gebruikt omdat dan het nummer natuurlijk niet meer bestaat
)
begin
  declare @_VvorGid integer;
  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabVoorraadVerplaatsingsOpdrachtRegel';
  declare @_LockUserNaam nchar(40) = 'KingWebService';
  declare @_LockSoort smallint = isNull(@Locksoort,1);

  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven');

  // ingangscontroles (licentie, opties, abonnement...)
  // Optie meerdere magazijnen geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); // (20790) '%1!' niet geactiveerd!
  end if;

  if @vvorGid is null then
    // Opzoeken Voorraadverplaatsingsopdracht
    select VvorGid into @_VvorGid
    from tabVoorraadVerplaatsingsOpdrachtKop
    inner join tabVoorraadVerplaatsingsOpdrachtRegel on vvorvvokgid = vvokgid
    where VvokNummer = @Nummer
      and vvorRegelNummer = @RegelNummer;

    if @_VvorGid is null then
      call Raise(20720, 'RegelNummer'); // (20720) niet gevonden: %1!
    end if;
  else
    set @_vvorGid = @vvorGid;
  end if;

  //Elke api heeft zijn eigen connection id.
  //Het standaard lockmechanisme werkt in dat geval dan niet.
  //het vrij geven van een lock gaat dan niet op SpId, maar op usernaam
  begin // lock vrijgeven
    if exists(select first qLockUser from qtablock where qLockTablename = _QLOCKTABLENAME and qLockPKey = String(@_VvorGid) and qLockUser = @_LockUserNaam and qlockSoort = @_LockSoort and qLockConnection = @@SpId) then
    // Haal de lock weg als deze ook echt bestaat via de spID
      call LockReleaseOnId(@@SpId, @@LoginTime, @_LockSoort, _QLOCKTABLENAME, @_VvorGid);
    else
      //Het record zou dus wel door KingWebService gelockt zijn, deze opruimen.
      call LockReleaseOnUserName(@_LockUserNaam, @_LockSoort , _QLOCKTABLENAME, @_VvorGid);
    end if;

    // exclusief gelockt, maar niet door KingWebService? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = _QLOCKTABLENAME and qLockPKey = String(@_VvorGid) and qLockUser <> @_LockUserNaam and qlockSoort = 1) then
      call Raise(20741, _U('Voorraadverplaatsingsopdrachtregel')); // (20741) %1! is in gebruik!
    end if;

  end; // lock vrijgeven

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven');
end;

create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Splitsen
(
  in @Nummer numeric(10,0) default null,
  in @RegelNummer integer default null
)
begin
  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Splitsen');
  declare @_vvokGid integer = null;
  declare @_vvokStatus smallint = null;
  declare @_vvorGid integer = null;
  declare @_vvorStatus smallint = null;
  declare @_KanSplitsen smallint = 0;

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if @_vvokGid is null then
    call Raise(20720, 'Nummer');  //(20720) %1! niet gevonden!
  end if;

  if @_vvokStatus = 9 /*Verwerkt*/  then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel splitsen'),_U('opdracht is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  //Ophalen van de huidige gegevens
  select vvorGid, vvorStatus, if ((VvorAantalInVrrdEenh <> VvorAantalVerwerktInVrrdEenh) and (VvorAantalVerwerktInVrrdEenh <> 0)) then 1 else 0 endif
  into @_vvorGid, @_vvorStatus, @_KanSplitsen
  from tabvoorraadVerplaatsingsOpdrachtRegel
  where vvorVvokGid = @_vvokGid
    and vvorRegelnummer = @RegelNummer;

  if (@_vvorGid is null) then
    call Raise(20720, 'RegelNummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_vvorStatus = 9 /*Verwerkt*/) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel splitsen'),_U('regel is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  //Valt er iets te splitsen?
  if (@_KanSplitsen = 0) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel splitsen'),_U('Er is geen aantal om te splitsen')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  // Opdracht locken of bestaande lock overnemen
  begin atomic
    // T.b.v. locken
    declare @_LockUserNaam nchar(40) = 'KingWebService';
    declare @_SpId integer = null; // NULL =>  systeemvariabele @@SpId wordt gebruikt
    declare @_LoginTime timestamp = null; // NULL =>  systeemvariabele @@LoginTime wordt gebruikt
    declare @_LockSoortKop smallint = 1 /*Exclusive*/;
    declare @_UseLockingBijVerschuiven smallint = 1;

    //Als er geen shared lock is op de kop, probeer een exclusive lock te plaatsen op de kop.
    if LocksOnRecord('tabVoorraadVerplaatsingsOpdrachtKop', @_vvokGid, 0 /*shared lock*/, 1, @@SpId) = 0 then
      set @_UseLockingBijVerschuiven = 0; /*In dit geval hoef je geen locking te gebruiken bij de te verschuiven regels*/
    else
      set @_LockSoortKop = 0 /*Shared*/;
    end if;

    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, @_LockUserNaam, @_Spid, @_LoginTime, @_LockSoortKop /*Exclusive*/);
    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken(@_vvorGid, @_LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusive*/);

    //Alle regels na de te splitsen regel locken en verschuiven
    if exists(select 1 from tabvoorraadVerplaatsingsOpdrachtRegel where vvorVvokGid = @_vvokGid and vvorRegelnummer > @RegelNummer) then
      call VoorraadVerplaatsingsOpdrachtRegelpositieVerschuiven(@_vvokGid, @RegelNummer+1, null, @_UseLockingBijVerschuiven, @_LockUserNaam);
    end if;

    //Nu splitsen
    insert into tabVoorraadVerplaatsingsOpdrachtRegel with auto name
    select
      VvorAantalInVrrdEenh - VvorAantalVerwerktInVrrdEenh as VvorAantalInVrrdEenh,
      VvorArtGid,
      VvorArtPartijGid,
      vvorKenmerk,
      VvorLocGidNaar,
      VvorLocGidVan,
      VvorMagGidNaar,
      VvorMagGidVan,
      VvorMutOmschrijving,
      VvorOpm,
      VvorOrrGidReden,
      VvorOrrGidtbv,
      VvorRedenOms,
      (VvorRegelnummer + 1) as VvorRegelnummer,
      VvorScannerToegewezenAan,
      VvorScannerToegewezenDoor,
      VvorScannerToegewezenOp,
      VvorStatus,
      VvorTbvOms,
      VvorTenBehoeveVan,
      VvorVvokGid
    from  tabVoorraadVerplaatsingsOpdrachtRegel
    where vvorGid = @_vvorGid;

    //Zet het aantal goed op de gesplitste regel
    update tabVoorraadVerplaatsingsOpdrachtRegel
    set VvorAantalInVrrdEenh = VvorAantalVerwerktInVrrdEenh
    where vvorGid = @_vvorGid;

    //De locks vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(@Nummer, @RegelNummer,  1 /*Exclusive lock*/);
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, @_LockSoortKop);
  end;

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Splitsen');
end;


create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Toevoegen
( in @Nummer numeric(10,0) default null,
  in @Status nchar(20)  default null, /* Waarden 'CONCEPT', 'KLAARVOORVERPLAATSEN', 'TOEGEWEZEN', 'ONDERHANDEN' */
  in @ScannerToegewezenAan nchar(20) default null,
  in @TenBehoeveVan nchar(12)  default null, /* Waarden: 'VERPLAATSING', 'VERKOOPORDER' */
