create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Verwerken
(
  in @Nummer numeric(10,0) default null,
  in @RegelNummer integer default null
)
result
(
  Regelnummer integer,
  Result      integer,      // Result als integer, zie procedure VerwerkVoorraadVerplaatsingsOpdracht voor de mogelijkheden
  Melding     nchar(80),    // Resultaat (korte melding)
  Opmerking   long nvarchar // Opmerking
)
begin
  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Verwerken');
  declare @_vvokGid integer = null;
  declare @_vvokStatus smallint = null;
  declare @_vvorGid integer = null;
  declare @_vvorStatus smallint = null;

  // Hier gebruikt, komen uit procedure VerwerkVoorraadVerplaatsingsOpdracht
  declare __vvvoRegelOK smallint = 100;


  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if @_vvokGid is null then
    call Raise(20720, 'Nummer');  //(20720) %1! niet gevonden!
  end if;

  if @_vvokStatus = 9 /*Verwerkt*/  then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwerken'),_U('opdracht is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if @_vvokStatus <> 1 /*Klaar voor verplaatsen*/ then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwerken'),_U('opdracht moet status ''Klaar voor verplaatsen'' hebben!')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  //Ophalen van de huidige gegevens
  select vvorGid, vvorStatus
  into @_vvorGid, @_vvorStatus
  from tabvoorraadVerplaatsingsOpdrachtRegel
  where vvorVvokGid = @_vvokGid
    and vvorRegelnummer = @RegelNummer;

  if @_vvorGid is null then
    call Raise(20720, 'RegelNummer');  // (20720) %1! niet gevonden!
  end if;

  case
    when @_vvorStatus = 0 /*Concept*/ then call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwerken'),_U('Dit is een conceptregel.')); // <Actie> niet mogelijk. Reden: <Reden>.
    when @_vvorStatus = 9 /*Verwerkt*/ then call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwerken'),_U('regel is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end case;

  // Opdracht locken of bestaande lock overnemen
  begin
    // T.b.v. locken
    declare @_LockUserNaam nchar(40) = 'KingWebService';
    declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId wordt gebruikt
    declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime wordt gebruikt
    declare @_LockStatus smallint = 0; // 0 = niks gelockt, 1 = shared lock op kop, 2 = shared lock op kop + exclusive lock op regel

    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, @_LockUserNaam, @_Spid, @_LoginTime, 0 /*Shared*/);
    set @_LockStatus = 1;
    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken(@_vvorGid, @_LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusive*/);
    set @_LockStatus = 2;

    //Nu verwerken
    select
      vvvovvorRegelnummer Regelnummer,
      vvvoResult          Result,
      vvvoResultMsg       Melding,
      vvvoMsg             Opmerking
    from VerwerkVoorraadVerplaatsingsOpdracht(@vvokNummer = @Nummer, @vvorRegelnummer = @RegelNummer,@SkipLock = 1)
    where not (vvvoResult = __vvvoRegelOK and vvvoMsg=''); // eerste Regel verwerkt ZONDER opmerking niet nodig

    //De locks vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(@Nummer, @RegelNummer,  1 /*Exclusive lock*/);
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, 0 /*Shared*/);

  exception
  when others then
    if @_LockStatus >= 2 then
      call WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(@Nummer, @RegelNummer,  1 /*Exclusive lock*/);
    end if;
    if @_LockStatus >= 1 then
      call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, 0 /*Shared*/);
    end if;
    resignal;
  end;

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Verwerken');
end;


create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Verwijderen
( in @Nummer numeric(10,0) default null,
  in @RegelNummer integer default null
)
begin
  // Variabelen
  declare @_vvokGid integer = null;
  declare @_vvokStatus smallint = null;
  declare @_vvorGid integer = null;
  declare @_vvorStatus smallint = null;

  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Verwijderen');

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if @_vvokGid is null then
    call Raise(20720, 'Nummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_vvokStatus = 9 /*Verwerkt*/) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwijderen'),_U('opdracht is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  //Ophalen van de huidige gegevens
  select vvorGid, vvorStatus
  into @_vvorGid, @_vvorStatus
  from tabvoorraadVerplaatsingsOpdrachtRegel
  where vvorVvokGid = @_vvokGid
    and vvorRegelnummer = @RegelNummer;

  if @_vvorGid is null then
    call Raise(20720, 'RegelNummer');  // (20720) %1! niet gevonden!
  end if;

  case
    when @_vvorStatus = 2 /*Toegewezen*/ then call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwijderen'),_U('regel is toegewezen')); // <Actie> niet mogelijk. Reden: <Reden>.
    when @_vvorStatus = 3 /*Onderhanden*/ then call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwijderen'),_U('regel is onderhanden')); // <Actie> niet mogelijk. Reden: <Reden>.
    when @_vvorStatus = 9 /*Verwerkt*/ then call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwijderen'),_U('regel is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end case;

  begin atomic
    //Lock zetten
    // T.b.v. locken
    declare @_LockUserNaam nchar(40) = 'KingWebService';
    declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId wordt gebruikt
    declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime wordt gebruikt

    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, @_LockUserNaam, @_Spid, @_LoginTime, 0 /*Shared*/);
    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtRegelLocken(@_vvorGid, @_LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusive*/);

    delete from tabVoorraadVerplaatsingsOpdrachtRegel where vvorGid = @_vvorGid;

      //Alle regels na de te splitsen regel locken en verschuiven
    if exists(select 1 from tabvoorraadVerplaatsingsOpdrachtRegel where vvorVvokGid = @_vvokGid and vvorRegelnummer > @RegelNummer) then
      call VoorraadVerplaatsingsOpdrachtRegelpositieVerschuiven(@_vvokGid, @RegelNummer+1, -1, 1, @_LockUserNaam);
    end if;

    //De locks vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_LockVrijgeven(@Nummer, @RegelNummer, @vvorGid = @_vvorGid);
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, 0 /*Shared*/);

    // Aangemaakte Voorraadverplaatsingsopdracht lock vrijgeven
  end; //atomic

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdrachtRegel_Verwijderen');
end;


