create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(
  in @Nummer numeric(10,0),
  in @LockSoort smallint default 1, // 0 = readlock/shared lock,
                                   // 1 = writelock/exclusive lock
  in @vvokGid integer default null //Deze wordt bij het verwijderen gebruikt omdat dan het nummer natuurlijk niet meer bestaat
)
begin
  declare @_VvokGid integer;
  // constanten
  declare _QLOCKTABLENAME nchar(40) = 'tabVoorraadVerplaatsingsOpdrachtKop';
  declare @_LockUserNaam nchar(40) = 'KingWebService';
  declare @_LockSoort smallint = isNull(@Locksoort,1);

  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven');

  // ingangscontroles (licentie, opties, abonnement...)
  // Optie meerdere magazijnen geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); // (20790) '%1!' niet geactiveerd!
  end if;

  if @vvokGid is null then
    // Opzoeken Voorraadverplaatsingsopdracht
    select VvokGid into @_VvokGid
    from tabVoorraadVerplaatsingsOpdrachtKop
    where VvokNummer = @Nummer;

    if @_VvokGid is null then
      call Raise(20720, 'Nummer'); // (20720) niet gevonden: %1!
    end if;
  else
    set @_VvokGid = @vvokGid;
  end if;

  //Elke api heeft zijn eigen connection id.
  //Het standaard lockmechanisme werkt in dat geval dan niet.
  //het vrij geven van een lock gaat dan niet op SpId, maar op usernaam
  begin // lock vrijgeven
    if exists(select first qLockUser from qtablock where qLockTablename = _QLOCKTABLENAME and qLockPKey = String(@_VvokGid) and qLockUser = @_LockUserNaam and qlockSoort = @_LockSoort and qLockConnection = @@SpId) then
    // Haal de lock weg als deze ook echt bestaat via de spID
      call LockReleaseOnId(@@SpId, @@LoginTime, @_LockSoort , _QLOCKTABLENAME, @_VvokGid);
    else
      //Het record zou dus wel door KingWebService gelockt zijn, deze opruimen.
      call LockReleaseOnUserName(@_LockUserNaam, @_LockSoort , _QLOCKTABLENAME, @_VvokGid);
    end if;

    // exclusief gelockt, maar niet door KingWebService? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = _QLOCKTABLENAME and qLockPKey = String(@_VvokGid) and qLockUser <> @_LockUserNaam and qlockSoort = 1) then
      call Raise(20741, _U('Voorraadverplaatsingsopdracht')); // (20741) %1! is in gebruik!
    end if;

  end; // lock vrijgeven

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven');
end;

create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdracht_Toevoegen
( in @Nummer numeric(10,0) default null,
  in @BronReferentie nchar(40) default null,
  in @Omschrijving nchar(80) default null,
  in @Opmerking long nvarchar default null,
  in @Status nchar(20) default null /* Waarden: CONCEPT, KLAARVOORVERPLAATSEN */
)
result (VoorraadVerplaatsingsOpdrachtNummer numeric(10,0))
begin
  // Variabelen
  declare @_vvokGid integer;
  declare @_vvokStatus smallint;

  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdracht_Toevoegen');

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  if (@Nummer is not null) and exists(select 1 from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer) then
    call Raise(20721, 'Nummer');  // (20721) '%1!' komt al voor!
  end if;

  // Controle: @Status moet 'CONCEPT' of 'KLAARVOORVERPLAATSEN' zijn.
  case
    when isnull(@Status,'CONCEPT') = 'CONCEPT' then set @_vvokStatus = 0;
    when isnull(@Status,'') = 'KLAARVOORVERPLAATSEN' then set @_vvokStatus = 1;
    else call Raise(20700, 'Status');   // (20700) Ongeldige waarde: %1!
  end case;

  begin atomic // Dit moet, want lock moet hierna nog erop en daar kan het nog fout gaan
    insert into tabVoorraadVerplaatsingsOpdrachtKop with auto name
    select
      1 /*WebService*/ VvokBron,
      isNull(@BronReferentie,'') VvokBronReferentie,
      @Nummer VvokNummer,
      @Omschrijving VvokOms,
      @_vvokStatus VvokStatus,
      @Opmerking VvokOpmerking;

    set @_vvokGid = @@Identity;
     // Aangemaakte Voorraadverplaatsingsopdracht locken
    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, 'KingWebService', @@Spid, @@LoginTime, 1 /*Exclusief*/);
  end; //atomic

  // resultaat terug geven
  select VvokNummer as VoorraadVerplaatsingsOpdrachtNummer
  from tabVoorraadVerplaatsingsOpdrachtKop
  where vvokGid = @_vvokGid;

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdracht_Toevoegen');
end;


create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdracht_Verwerken
(
  in @Nummer numeric(10,0) default null
)
result
(
  Regelnummer integer,
  Result      integer,      // Result als integer, zie procedure VerwerkVoorraadVerplaatsingsOpdracht voor de mogelijkheden
  Melding nchar(80),    // Resultaat (korte melding)
  Opmerking long nvarchar // Opmerking
)
begin
  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdracht_Verwerken');
  declare @_vvokGid integer = null;
  declare @_vvokStatus smallint = null;

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if @_vvokGid is null then
    call Raise(20720, 'Nummer');  //(20720) %1! niet gevonden!
  end if;

  if @_vvokStatus = 9 /*Verwerkt*/  then
    call Raise(20780 , _U('Voorraadverplaatsingsopdracht verwerken'),_U('opdracht is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if @_vvokStatus <> 1 /*Klaar voor verplaatsen*/ then
    call Raise(20780 , _U('Voorraadverplaatsingsopdrachtregel verwerken'),_U('opdracht moet status ''Klaar voor verplaatsen'' hebben!')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  begin
    // T.b.v. locken
    declare @_LockUserNaam nchar(40) = 'KingWebService';
    declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId wordt gebruikt
    declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime wordt gebruikt

    // Hier gebruikt, komen uit procedure VerwerkVoorraadVerplaatsingsOpdracht
    declare __vvvoRegelOK smallint = 100;

    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, @_LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusief*/);

    //Nu verwerken
    select
      vvvovvorRegelnummer Regelnummer,
      vvvoResult          Result,
      vvvoResultMsg       Melding,
      vvvoMsg             Opmerking
    from VerwerkVoorraadVerplaatsingsOpdracht(@vvokNummer = @Nummer,  @SkipLock = 1)
    where not (vvvoResult = __vvvoRegelOK and vvvoMsg=''); // eerste Regel verwerkt ZONDER opmerking niet nodig

    //De lock vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, 1 /*Exclusief*/);
  exception
  when others then
    //De lock vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, 1 /*Exclusief*/);
    resignal;
  end;
  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdracht_Verwerken');
end;


create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdracht_Verwijderen
( in @Nummer numeric(10,0) default null
)
begin
  // Variabelen
  declare @_vvokGid integer;
  declare @_vvokStatus smallint;

  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdracht_Verwijderen');

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if @_vvokGid is null then
    call Raise(20720, 'Nummer');  // (20720) %1! niet gevonden!
  end if;

  if (@_vvokStatus = 9 /*Verwerkt*/) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdracht verwijderen'),_U('opdracht is al verwerkt')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  if exists(select first 1 from tabVoorraadVerplaatsingsOpdrachtRegel where vvorvvokGid = @_vvokGid and vvorStatus in (2,3,9)) then
    call Raise(20780 , _U('Voorraadverplaatsingsopdracht verwijderen'),_U('opdracht heeft toegewezen, onderhanden of verwerkte regels')); // <Actie> niet mogelijk. Reden: <Reden>.
  end if;

  begin atomic
    //Lock zetten
    call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, 'KingWebService', @@Spid, @@LoginTime, 1 /*Exclusief*/);

    delete from tabVoorraadVerplaatsingsOpdrachtKop where vvokGid = @_vvokGid;

     // Aangemaakte Voorraadverplaatsingsopdracht lock vrijgeven
    call WebSvcProc_VoorraadVerplaatsingsOpdracht_LockVrijgeven(@Nummer, @vvokGid = @_vvokGid);
  end; //atomic

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdracht_Verwijderen');
end;


create or replace procedure WebSvcProc_VoorraadVerplaatsingsOpdracht_Wijzigen
( in @Nummer numeric(10,0) default null,
  in @Omschrijving nchar(80) default null,
  in @Opmerking long nvarchar default null,
  in @Status nchar(20) default null /* Waarden: CONCEPT, KLAARVOORVERPLAATSEN */
)
begin
  // Variabelen
  declare @_vvokGid integer;
  declare @_vvokStatus smallint;

  //call TraceBegin('WebSvcProc_VoorraadVerplaatsingsOpdracht_Wijzigen');

  // Module: Optie meerdere magazijnen is geactiveerd?
  if IsModuleActive('m2') = 0 then
    call Raise(20790, _U('Optie meerdere magazijnen')); //(20790) '%1!' niet geactiveerd!
  end if;

  // Controle nummer: Bestaat het meegegeven Voorraadverplaatsingsopdrachtnummer al?
  select vvokGid, vvokStatus into @_vvokGid, @_vvokStatus from tabVoorraadVerplaatsingsOpdrachtKop where VvokNummer = @Nummer;

  if (@_vvokGid is null) then
    call Raise(20700, 'Nummer');   // (20700) Ongeldige waarde: %1!
  end if;

  if (@_vvokStatus = 9 /*Verwerkt*/) then
    //Alleen opmerking mag bij verwerkt aangepast worden.
    set @Omschrijving = null;
  else
    // Controle: @Status moet 'CONCEPT' of 'KLAARVOORVERPLAATSEN' zijn.
    case
      when @Status is null then set @_vvokStatus = null;
      when @Status = 'CONCEPT' then set @_vvokStatus = 0;
      when @Status = 'KLAARVOORVERPLAATSEN' then set @_vvokStatus = 1;
      else call Raise(20700, 'Status');   // (20700) Ongeldige waarde: %1!
    end case;
  end if;

  begin atomic // Dit moet, want lock moet hierna nog erop en daar kan het nog fout gaan
    // Opdracht locken of bestaande lock overnemen
    begin
      // T.b.v. locken
      declare @_LockUserNaam nchar(40) = 'KingWebService';
      declare @_SpId integer = null;   // NULL =>  systeemvariabele @@SpId       wordt gebruikt
      declare @_LoginTime timestamp = null;   // NULL =>  systeemvariabele @@LoginTime  wordt gebruikt

      call WebSvcHulpProc_VoorraadVerplaatsingsOpdrachtLocken(@_vvokGid, @_LockUserNaam, @_Spid, @_LoginTime, 1 /*Exclusief*/);
    end;

    update tabVoorraadVerplaatsingsOpdrachtKop
    set VvokOms = isNull(@Omschrijving, VvokOms) ,
        VvokStatus = isNull(@_vvokStatus, VvokStatus) ,
        VvokOpmerking = isNull(@Opmerking, VvokOpmerking)
    where vvokGid = @_vvokGid;
  end; //atomic

  //call TraceEind('WebSvcProc_VoorraadVerplaatsingsOpdracht_Wijzigen');
end;


create or replace procedure WebSvcHulpProc_VrijeRubriekExclusiefLocken(
  in @TabelNaam nchar(40) default null,
  in @LockUserNaam nchar(40) default null,
  in @SpId integer default null,
  in @LoginTime datetime default null
)
begin
  declare @_LockResult integer;
  declare _qcGEENLOCK smallint = 0;
  declare _qcEXCLUSIVELOCK smallint = 1;

  // Defaults instellen
  set @LockUserNaam = IsNull(@LockUserNaam, 'KingWebservice');
  set @SpId = IsNull(@SpId, @@SpId);
  set @LoginTime = IsNull(@LoginTime, @@LoginTime);

  if LockedById(@SpId, @LoginTime, _qcEXCLUSIVELOCK, @TabelNaam, '') = _qcGEENLOCK  then
    // locken, met standaard King 5 procedure
    call LockSetOnId( @Spid,
                      @LoginTime,
                      _qcEXCLUSIVELOCK, // 1 = Exclusieve lock, 0 = ReadLock
                      @TabelNaam,       // tabel waarin record te locken is - nchar(40)
                      '',               // lockstring voor record, nchar(80)
                      @_LockResult,     // 0 = OK, anders fout
                      0,                // Automatisch opruimen: 0 = nee, 1 = ja
                      @LockUserNaam);   // Welke King gebruiker of proces

    if @_LockResult <> 0 then
      call Raise(20741, @TabelNaam);    // (20741) %1 is in gebruik!
    end if;
  end if;
end;



create or replace procedure WebSvcHulpProc_VrijeRubriek_LockVrijgeven(@TabelNaam nchar(40))
begin
  // Als Webservice API de stored proc in King database aanroepen die ook door andere APIs gebruikt kunnen worden.
  // variabelen
  declare @LockUserNaam nchar(40) = 'KingWebService';
  declare @SpId integer = @@SpId;
  declare @LoginTime datetime = @@LoginTime;

  //Elke api heeft zijn eigen connection id.
  //Het standaard lockmechanisme werkt in dat geval dan niet.
  //het vrij geven van een lock gaat dan niet op SpId, maar op usernaam

  begin // lock vrijgeven
    call LockReleaseOnId(isnull(@Spid, @@SpId), isnull(@LoginTime,@@LoginTime), 1, @TabelNaam, '');

    // gelockt, maar niet door @LockUserNaam? Melden...
    if exists(select first qLockUser from qtablock where qLockTablename = @TabelNaam and qLockUser <> @LockUserNaam) then
      call Raise(20741, _U('Vrijerubriektabel %1!', @TabelNaam)); // (20741) %1! is in gebruik!
    end if;

    // De record zou dus wel door @LockUserNaam gelockt zijn, deze opruimen.
    call LockReleaseOnUserName(@LockUserNaam, 1, @TabelNaam, '');
  end; // lock vrijgeven

end;



create or replace procedure WebSvcHulpProc_VrijeRubriek_ToevoegenWijzigen(
  in @VrBestandOms nchar(3), /* 'ACT', 'ART', 'BST', 'MEV', 'NAW', 'PRJ', 'ORK', 'ORR', 'VRT', 'LIC', 'OFK', 'ABO', 'PRD', 'RCP' */
  in @VrGroepID integer,
  in @VrSubGroepId integer,
  in @Omschrijving nchar(40),
  in @Type nchar(15),   /* Geldige waardes: null (bij wijzigen), 'tekst', 'getal', 'datum', 'tijd', 'selectievakje', 'keuzelijst', 'email', 'website', 'bestand', 'telefoon'*/
  in @Hint nchar(80),
  in @Verplicht nchar(3), /* 'JA', 'NEE', 1, 0 */
  in @Uniek nchar(3), /* 'JA', 'NEE', 1, 0  */
  in @Lengte numeric(3,0),
  in @Decimalen smallint, /* >= 0 en <= 5 */
  in @Keuzelijst long varchar, //Delimited met CrLf (/0x0d/0x0a) OF '|'
  in @Defaultwaarde nchar(250), //Bevat default voor elk type veld!. Bij datum/tijd: nu/now levert datum/tijd van server
  in @Sjabloon nchar(255), //Bevat sjabloon voor elk type dat een sjabloon kan hebben
  in @Groep nchar(40),
  in @DefaultDatum nchar(16), //Eigendatum, Verwerkingsdatum, Systeemdatum
  in @DefaultTijd nchar(11), //EigenTijd, SysteemTijd
  in @OpVerkoopDocument nchar(3) /* 'JA', 'NEE' */
)
begin
  /*Constanten*/
  declare _qcJa smallint = 1;
  declare _qcNee smallint = 0;

  /*Variabelen*/
  declare @_VrGid integer;
  declare @_IsUpdateVanRubriek smallint = _qcNee;
  declare @_Tabelnaam nchar(40);
  declare @_VrVeldnaam nchar(40); // Alleen gebruikt bij wijzigen
  declare @_VrType integer;
  declare @_NewVrType integer;
  declare @_VrHint nchar(80);
  declare @_VrVerplicht smallint;
  declare @_VrUniek smallint;
  declare @_VrOpVerkoopDocument smallint;
  declare @_VrLabel nchar(40);
  declare @_VrDefaultString nchar(255);
  declare @_VrDefaultDateType smallint = null;
  declare @_VrDefaultDate Date;
  declare @_VrDefaultTimeType smallint = null;
  declare @_VrDefaultTime Time;
  declare @_VrDefaultGetal Double;
  declare @_VrLengte smallint;
  declare @_VrDecimalen smallint;
  declare @_VrSjabloon nchar(255);
  declare @_VrSelecties long nvarchar;
  declare @_VrGroep nchar(40);

  //call trace('Begin WebSvcHulpProc_VrijeRubriek_ToevoegenWijzigen')

  if trim(isNull(@Omschrijving, '')) = '' then
    call Raise(20700, 'Omschrijving'); // (20700) Ongeldige waarde
  end if;

  set @_VrLabel = @Omschrijving;

  // Opzoeken veldgegevens als defaults voor de verschillende types
  select  VrGid, VrVeldnaam,   VrType,  VrHint,  VrVerplicht,  VrUniek,  VrOpVerkoopDocument,  VrLabel,  VrDefaultString,
          VrDefaultDateType, VrDefaultDate,  VrDefaultTimeType, VrDefaultTime,  VrDefaultGetal,  VrLengte,  VrDecimalen,
          VrSjabloon,  VrSelecties,  vrgrpNaam
  into  @_VrGid, @_VrVeldnaam, @_VrType, @_VrHint, @_VrVerplicht, @_VrUniek, @_VrOpVerkoopDocument, @_VrLabel, @_VrDefaultString,
        @_VrDefaultDateType, @_VrDefaultDate, @_VrDefaultTimeType, @_VrDefaultTime, @_VrDefaultGetal, @_VrLengte, @_VrDecimalen,
        @_VrSjabloon, @_VrSelecties, @_VrGroep
  from tabVrijeRubrieken
  left outer join tabVrijeRubriekenGroep on vrgrpGid = VrvrgrpGid
  where VrBestandOms = @VrBestandOms
    and VrLabel      = @_VrLabel
    and VrGroepId    = @VrGroepID
    and VrSubGroepId = @VrSubGroepId;

  set @_IsUpdateVanRubriek = if @_VrGid is null then _qcNee else _qcJa endif;

  //Nu alle waarden aanmaken
  case @Type
    when null            then if @_IsUpdateVanRubriek = _qcNee then
                                call Raise(20700, 'Type'); /* (20700) Ongeldige waarde*/
                              else
                                set @_NewVrType = @_VrType;
                              end if;
    when 'tekst'         then set @_NewVrType = 0
    when 'getal'         then set @_NewVrType = 1
    when 'datum'         then set @_NewVrType = 2
    when 'tijd'          then set @_NewVrType = 3
    when 'selectievakje' then set @_NewVrType = 4
    when 'keuzelijst'    then set @_NewVrType = 5
    when 'email'         then set @_NewVrType = 6
    when 'website'       then set @_NewVrType = 7
    when 'bestand'       then set @_NewVrType = 8
    when 'telefoon'      then set @_NewVrType = 9
  else
    call Raise(20700, 'Type'); // (20700) Ongeldige waarde
  end case;

  if @_IsUpdateVanRubriek = _qcJa and (@_NewVrType <> @_VrType) then
    call Raise(20700, _U('%1! mag niet gewijzigd worden', 'Type')); // (20700) Ongeldige waarde
  else
   set @_VrType = @_NewVrType;
  end if;

  if (@_VrType in (0, 1, 6, 7, 8, 9)) then
    if (isNull(@Lengte,-1) = 0) or ((@_IsUpdateVanRubriek = _qcNee) and (@Lengte is null)) then
      call Raise(20096); // 20096 : Vrije rubriek van type tekst en getal moet een lengte hebben !
    end if;
  end if;

  if @Hint is not null then
    set @_VrHint = @Hint;
  end if;

  case UPPER(@Verplicht)
    when null then if @_IsUpdateVanRubriek = _qcNee then set @_VrVerplicht = _qcNee  /* Default!*/ end if;
    when 'JA' then set @_VrVerplicht = _qcJa
    when '1' then set @_VrVerplicht = _qcJa
    when 'NEE' then set @_VrVerplicht = _qcNee
    when '0' then set @_VrVerplicht = _qcNee
  else
    call Raise(20700, 'Verplicht'); // (20700) Ongeldige waarde: %1!
  end case;

  if @_VrVerplicht = _qcNee then
    set @_VrUniek = _qcNee
  else
    case UPPER(@Uniek)
      when null then if @_IsUpdateVanRubriek = _qcNee then set @_VrUniek = _qcNee  /* Default!*/ end if;
      when 'JA' then set @_VrUniek = _qcJa
      when '1' then set @_VrVerplicht = _qcJa
      when 'NEE' then set @_VrUniek = _qcNee
      when '0' then set @_VrVerplicht = _qcNee
    else
      call Raise(20700, 'Uniek'); // (20700) Ongeldige waarde: %1!
    end case;

    // Bij uniek, dan is er geen default! (Eventuele eerder aangegeven default wordt nu dus ook leeg gemaakt!)
    if @_VrUniek = _qcJa and isNull(@DefaultWaarde,'') <> '' then
      call Raise(20700, _U('Defaultwaarde mag niet worden gevuld als de vrijerubriek uniek is')); // (20700) Ongeldige waarde: %1!
    end if;
  end if;

  case UPPER(@OpVerkoopDocument)
    when null then if @_IsUpdateVanRubriek = _qcNee then set @_VrOpVerkoopDocument = _qcJa  /* Default!*/ end if;
    when 'JA' then set @_VrOpVerkoopDocument = _qcJa
    when 'NEE' then set @_VrOpVerkoopDocument = _qcNee
  else
    call Raise(20700, 'OpVerkoopDocument'); // (20700) Ongeldige waarde: %1!
  end case;

  if (@VrBestandOms not in ('ART', 'ORK', 'ORR') and not(@VrBestandOms = 'NAW' and @VrGroepID = 1 /*Debiteuren*/ )) then
    set @_VrOpVerkoopDocument = _qcJa;
  end if;

  set @_VrGroep = isnull(@Groep, @_VrGroep);

  case @_VrType
    when 0 /* Tekst */ then
      set @_VrDefaultString = isnull(@DefaultWaarde, @_VrDefaultString);
      set @_VrSjabloon = isnull(@Sjabloon, @_VrSjabloon);
      set @_VrLengte = isnull(@Lengte, @_VrLengte);

	  if (length(@_VrDefaultString) > @_VrLengte) then
        call Raise(20700 , _U('Default waarde is te groot!')); //  (20700) Ongeldige waarde: %1!
      end if;

    when 1 /* Getal */then
      if (@Lengte not between 0 and 10) then
      		call Raise(20700, _U('Lengte moet groter dan %1! en kleiner of gelijk aan %2! zijn!', '0', '10')); // (20700) Ongeldige waarde: %1!
      end if;

      set @_VrDefaultGetal  = isnull(@DefaultWaarde, @_VrDefaultGetal);
      set @_VrLengte = isnull(@Lengte, @_VrLengte);
      set @_VrDecimalen = isnull(@Decimalen, @_VrDecimalen);
      set @_VrSjabloon = '';

      if @_IsUpdateVanRubriek = _qcNee and @Decimalen is null then
        set @_VrDecimalen = 2;
      end if;

      if not (@_VrDecimalen between 0 and 5) then
        call Raise(20700 , _U('%1! moet tussen %2! en %3! liggen!', 'Decimalen', '0', '5')); //  (20700) Ongeldige waarde: %1!
      end if;

      if (length(floor(ABS(@_VrDefaultGetal))) > @_VrLengte) or
      ((LENGTH(@_VrDefaultGetal) - LENGTH(floor(@_VrDefaultGetal)) - 1) > @_VrDecimalen) then
        call Raise(20700 , _U('Default waarde is te groot!')); //  (20700) Ongeldige waarde: %1!
      end if;

    when 2 /* Datum */ then
      set @_VrSjabloon = '';

      case UPPER(@DefaultDatum)
        when null then if @_IsUpdateVanRubriek = _qcNee then set @_VrDefaultDateType = 0  /* Eigen datum*/ end if;
        when 'EIGENDATUM' then set @_VrDefaultDateType = 0
        when 'VERWERKINGSDATUM' then set @_VrDefaultDateType = 1
        when 'SYSTEEMDATUM' then set @_VrDefaultDateType = 2
      else
        call Raise(20700, 'Defaultdatum'); // (20700) Ongeldige waarde: %1!
      end case;

      begin
        case
          when @DefaultWaarde = '' then
            set @_VrDefaultDate = null
          when @DefaultWaarde is not null then
            if UPPER(@DefaultWaarde) in ('NU', 'NOW') then
              set @_VrDefaultDate = cast(now() as date);
            else
              set @_VrDefaultDate = cast(@DefaultWaarde as date);
            end if;
        end case;
      exception when others then
        call Raise(20700, 'Defaultwaarde'); // (20700) Ongeldige waarde: %1!
      end;
    when 3 /* Tijd */ then
      set @_VrSjabloon = '';

      case UPPER(@DefaultTijd)
        when null then if @_IsUpdateVanRubriek = _qcNee then set @_VrDefaultTimeType = 0  /* Eigen tijd*/ end if;
        when 'EIGENTIJD' then set @_VrDefaultTimeType = 0
        when 'SYSTEEMTIJD' then set @_VrDefaultTimeType = 1
      else
        call Raise(20700, 'Defaulttijd'); // (20700) Ongeldige waarde: %1!
      end case;

      begin //14:45, 2:30, 14:56:22, 18:05:19.456 zijn allemaal goed
        case
          when @DefaultWaarde = '' then
            set @_VrDefaultTime = null;
          when @DefaultWaarde is not null then
            if UPPER(@DefaultWaarde) in ('NU', 'NOW') then
              set @_VrDefaultTime = cast(now() as time);
            else
              if not @DefaultWaarde REGEXP '^([0-1]?[0-9]|2[0-3]):[0-5][0-9]$' then
                call Raise(20700, 'Defaultwaarde'); // (20700) Ongeldige waarde: %1!
              end if;

              set @_VrDefaultTime = cast(@DefaultWaarde as time);
            end if;
        end case;
      exception when others then
        call Raise(20700, 'Defaultwaarde'); // (20700) Ongeldige waarde: %1!
      end;

    when 4 /* Selectievakje */ then
      set @_VrSjabloon = '';

      case @DefaultWaarde
        when null  then if @_IsUpdateVanRubriek = _qcNee then set @_VrDefaultString = 0  /* Default!*/ end if;
        when ''  then if @_IsUpdateVanRubriek = _qcNee then set @_VrDefaultString = 0  /* Default!*/ end if;
        when 'ja'  then set @_VrDefaultString = 1
        when 'yes' then set @_VrDefaultString = 1
        when '1'   then set @_VrDefaultString = 1
        when 'nee' then set @_VrDefaultString = 0
        when 'no'  then set @_VrDefaultString = 0
        when '0'   then set @_VrDefaultString = 0
      else
        call Raise(20700, 'Defaultwaarde'); // (20700) Ongeldige waarde: %1!
      end case;

      //Beide worden niet gebruikt bij Selectievakje. Dus zet maar op Nee.
      set @_VrVerplicht = _qcNee;
      set @_VrUniek = _qcNee;

    when 5 /* Keuzelijst */ then
      set @_VrSjabloon = '';

      // De keuzelijst wordt pas NA insert/update verwerkt via de tmpVrijeRubrieken tabel
      if (isNull(@keuzelijst,'') <> '') then
        if not @keuzelijst like '%' + char(13) + '%' and not @keuzelijst like '%' + char(10) + '%' then
          set @keuzelijst = replace(@keuzelijst, '|', char(10));
        else
          // Convert crlf correctly to lf
          set @keuzelijst = replace(@keuzelijst, char(13)+char(10), char(10));
          set @keuzelijst = replace(@keuzelijst, char(10)+char(13), char(10));
          set @keuzelijst = replace(@keuzelijst, char(13), char(10));
        end if;

        set @keuzelijst = replace(@keuzelijst, char(10)+char(10), char(10));

        if (@Keuzelijst like char(10) + '%') or (@Keuzelijst like  '%' + char(10)) then
          call Raise(20700, 'Keuzelijst'); // (20700) Ongeldige waarde: %1!
        end if;

        set @_VrSelecties = isnull(@keuzelijst, '');

        if @_VrSelecties = '' then
          call Raise(20700, 'Keuzelijst'); // (20700) Ongeldige waarde: %1!
        end if;
      end if;

      set @_VrDefaultString = isnull(@DefaultWaarde, @_VrDefaultString, '');

      // Als er een default is, dan moet die wel in de lijst zitten!
      if @_VrDefaultString <> '' then
        if isNull(@_VrSelecties, '') = '' or
        not exists(select first 1 from openstring( VALUE @_VrSelecties) WITH(keuze nchar(40)) as Keuzelijst where @DefaultWaarde = keuze) then
          call Raise(20700, _U('Defaultwaarde niet in keuzelijst')); // (20700) Ongeldige waarde: %1!
        end if;
      end if;

    when 6 /* Email */ then
      set @_VrDefaultString = isnull(@DefaultWaarde, @_VrDefaultString);
      set @_VrLengte = isnull(@Lengte, @_VrLengte); // wordt in vrInsert gecontroleerd
      set @_VrSjabloon = isnull(@Sjabloon, @_VrSjabloon);

    when 7 /* Website */ then
      set @_VrDefaultString = isnull(@DefaultWaarde, @_VrDefaultString);
      set @_VrLengte = isnull(@Lengte, @_VrLengte); // wordt in vrInsert gecontroleerd
      set @_VrSjabloon = isnull(@Sjabloon, @_VrSjabloon);

    when 8 /* Bestand */ then
      set @_VrDefaultString = isnull(@DefaultWaarde, @_VrDefaultString);
      set @_VrLengte = isnull(@Lengte, @_VrLengte); // wordt in vrInsert gecontroleerd
      set @_VrSjabloon = isnull(@Sjabloon, @_VrSjabloon);

    when 9 /* Telefoon */ then
      set @_VrDefaultString = isnull(@DefaultWaarde, @_VrDefaultString);
      set @_VrLengte = isnull(@Lengte, @_VrLengte); // wordt in vrInsert gecontroleerd
      set @_VrSjabloon = isnull(@Sjabloon, @_VrSjabloon);
  end case;

  if @_VrType in (0,6,7,8) and (@_VrLengte not between 0 and 255) then
    call Raise(20700, _U('Lengte moet groter dan %1! en kleiner of gelijk aan %2! zijn!', '0', '255')); // (20700) Ongeldige waarde: %1!
  end if;

  if @_VrType in (0,1,6,7,8,9) and Length(@_VrDefaultString) > @_VrLengte then
    call Raise(20700, _U('Default waarde mag niet langer zijn dan de lengte!')); // (20700) Ongeldige waarde: %1!
  end if;

  //Sjabloon checken
  call WebSvcHulpProc_VrijeRubriek_ValideerSjabloon(@_VrSjabloon, @_VrLengte);

  // Toevoegen of wijzigen van de vrije rubriek
  begin
    declare @_VrgrpGid integer = null;
    declare @_MasterTabelnaam nchar(40) = '';
    declare @_MasterTabelRecordVeldnaam nchar(40) = '' ;

    set @_Tabelnaam = VrTabelnaam(@VrBestandOms, @VrGroepID, @VrGroepID);
    begin
      call WebSvcHulpProc_VrijeRubriekExclusiefLocken(@TabelNaam = @_TabelNaam);

      if @_VrGroep is not null then
        // Opzoeken groep, indien gevonden, dan die gebruiken!
        if @_VrGroep = '' then
        // Uit de groep halen
        set @_VrgrpGid = null
        else
        select vrgrpGid
        into @_VrgrpGid
        from tabVrijeRubriekenGroep
        where vrgrpBestandOms = @VrBestandOms and vrgrpGroepID = @VrGroepID and vrgrpSubGroepID = @VrGroepID
        and  vrgrpNaam = @_VrGroep;

        if @_VrgrpGid is null then
          // Groep toevoegen!
          insert into tabVrijeRubriekenGroep
            (vrgrpBestandOms, vrgrpGroepID, vrgrpSubGroepID, vrgrpNaam, vrgrpVolgorde)
          values(@VrBestandOms,   @VrGroepID,   @VrSubGroepId,   @_VrGroep,
             isnull((select max(vrgrpVolgorde)+1 from tabVrijeRubriekenGroep where vrgrpBestandOms = @VrBestandOms and vrgrpGroepID = @VrGroepID and vrgrpSubGroepID = @VrSubGroepId), 1)
            );
          set @_VrgrpGid = @@Identity;
        end if;
         end if;
      end if;

      if @_VrGid is null then
        call VrInsert(@VrBestandOms,    @VrGroepID,       @VrSubGroepId,  @_VrType,
              @_VrHint,          @_VrVerplicht,     @_VrUniek,       @_VrOpVerkoopDocument, @_VrLabel,
              @_VrDefaultString, @_VrDefaultDateType, @_VrDefaultDate,  @_VrDefaultTimeType, @_VrDefaultTime,
              @_VrDefaultGetal,  @_VrLengte,        @_VrDecimalen, @_VrSjabloon,
              @_VrgrpGid,        @_MasterTabelnaam, @_MasterTabelRecordVeldnaam);
        set @_VrGid = @@Identity;
      else
        call VrUpdate(@VrBestandOms,    @VrGroepID,       @VrSubGroepId,  @_VrType,
              @_VrHint,          @_VrVerplicht,     @_VrUniek,       @_VrOpVerkoopDocument, @_VrLabel,
              @_VrDefaultString, @_VrDefaultDateType, @_VrDefaultDate, @_VrDefaultTimeType, @_VrDefaultTime, @_VrVeldnaam,
              @_VrDefaultGetal,  @_VrLengte,        @_VrDecimalen,   @_VrSjabloon,
              @_VrgrpGid,        @_VrGid);
      end if;

      // Keuzelijst aan vrijerubriek knopen
      if @_VrType = 5 and (@_VrSelecties <> '') /*Keuzelijst*/ then
        //type 5 -> Selecties updaten via call VrUpdateSelecties(@_VrGid);
        // Als er geen Cr en/of Lf in zitten, dan de | omzetten
        delete tmpVrijeRubrieken; // Is connectie-tabel, dus alles mag wel weg... where tmpVRGid = @_VrGid;
        insert into tmpVrijeRubrieken(tmpVRGid, tmpVRSelecties)
        //values(@_VrGid, 'PROEF');
        values(@_VrGid, @_VrSelecties);
        //select @_VrGid, keuze from openstring( VALUE @_VrSelecties) WITH(keuze nchar(40)) OPTION (row delimited by '|') as Keuzelijst;
        call VrUpdateSelecties(@_VrGid);
      end if;

      call WebSvcHulpProc_VrijeRubriek_LockVrijgeven(@_TabelNaam);
    exception when others then
      call WebSvcHulpProc_VrijeRubriek_LockVrijgeven(@_TabelNaam);
      resignal;
    end;
  end;

  //call trace('Einde WebSvcHulpProc_VrijeRubriek_ToevoegenWijzigen');
end;

create or replace procedure WebSvcHulpProc_VrijeRubriek_ValideerSjabloon(
  in @VrSjabloon nvarchar(255),
  in @VrLengte smallint
)
begin
  //Variabelen
  declare @_Positie integer = 1;
  declare @_Sjabloon nchar(255) = @VrSjabloon;
  declare @_AantalInTeVoerenTekens integer = 0;

  while @_Positie <= Length(@_Sjabloon) loop
    if SUBSTR(@_Sjabloon,@_Positie,1) IN ('l', 'L', 'a', 'A', 'c', 'C', '0', '9', '#') then
      set @_AantalInTeVoerenTekens = @_AantalInTeVoerenTekens + 1;
    end if;

    // als teken is \ dan volgende teken overslaan
    if SUBSTR(@_Sjabloon,@_Positie,1) = '\' then
      set @_Positie = @_Positie + 1;
    end if;

    set @_Positie = @_Positie + 1;
  end loop;

  if @_AantalInTeVoerenTekens > @VrLengte then
    call Raise(20700, _U('Sjabloon is langer dan de maximumlengte van het invoerveld!')); // (20700) Ongeldige waarde: %1!
  end if;

  if (Right(@_Sjabloon,1) = '\') and (Right(@_Sjabloon,2) <> string(char(92)+char(92))) then
    call Raise(20700, _U('Het sjabloon mag niet eindigen op een enkele %1!, U dient %2! hiervoor te gebruiken!', '''\''', '''\\''')); // (20700) Ongeldige waarde: %1!
  end if;
end;


create or replace procedure WebSvcHulpProc_VrijeRubriek_Verwijderen(
  in @VrBestandOms nchar(3), /* 'ACT', 'ART', 'BST', 'MEV', 'NAW', 'PRJ', 'ORK', 'ORR', 'VRT', 'LIC', 'OFK', 'ABO', 'PRD', 'RCP' */
  in @VrGroepID integer,
  in @VrSubGroepId integer,
  in @Omschrijving nchar(40)
)
begin
  /*Constanten*/
  declare _qcJa smallint = 1;
  declare _qcNee smallint = 0;

  declare @_Tabelnaam nchar(40);

  //call trace('Begin WebSvcHulpProc_VrijeRubriek_Verwijderen')

  if trim(isNull(@Omschrijving, '')) = '' then
    call Raise(20700, 'Omschrijving'); // (20700) Ongeldige waarde
  end if;

  set @_Tabelnaam = VrTabelnaam(@VrBestandOms, @VrGroepID, @VrSubGroepId);

  // Tabel moet al bestaan
  begin
    declare @_Exists smallint;
    call TableExist(@_Tabelnaam, @_Exists);
    if @_Exists = 0 then
      call Raise(20541); //Vrije rubrieken tabel niet gevonden!
    end if;
  end;

  // Opruimen vrije rubriek
  begin
    declare @_VrVeldnaam nchar(40);
    declare @_VrGid integer;

    set @_VrVeldNaam = @Omschrijving;

    select VrGid
    into @_VrGid
    from tabVrijeRubrieken
    where VrBestandOms = @VrBestandOms
      and VrLabel = @_VrVeldNaam
      and VrGroepId = @VrGroepId
      and VrSubGroepId = @VrSubGroepId;

    if @_VrGid is null then
      call Raise(20700, 'Omschrijving'); // (20700) Ongeldige waarde
    end if;

    begin
      call WebSvcHulpProc_VrijeRubriekExclusiefLocken(@TabelNaam = @_TabelNaam);

      call VrDelete(@VrBestandOms, @VrGroepId, @VrSubGroepId, @_VrGid, @_VrVeldNaam);

      call WebSvcHulpProc_VrijeRubriek_LockVrijgeven(@_TabelNaam);
    exception when others then
      call WebSvcHulpProc_VrijeRubriek_LockVrijgeven(@_TabelNaam);
      resignal;
    end;
  end;

  //call trace('Einde WebSvcHulpProc_VrijeRubriek_Verwijderen');
end;

